window.BIBLE_DATA = {"version":"hkbs-web-2","default_translation":"cunp","translations":[{"id":"cunp","short_name":"CUNP","names":{"simplified":"新标点和合本","traditional":"新標點和合本"}},{"id":"rcuv-shen","short_name":"RCUV Shen","names":{"simplified":"和合本2010（和修）（神版）","traditional":"和合本2010（和修）（神版）"}}],"books":[{"code":"GEN","traditional":"創世記","simplified":"创世记","chapters":50,"testament":"old"},{"code":"EXO","traditional":"出埃及記","simplified":"出埃及记","chapters":40,"testament":"old"},{"code":"LEV","traditional":"利未記","simplified":"利未记","chapters":27,"testament":"old"},{"code":"NUM","traditional":"民數記","simplified":"民数记","chapters":36,"testament":"old"},{"code":"DEU","traditional":"申命記","simplified":"申命记","chapters":34,"testament":"old"},{"code":"JOS","traditional":"約書亞記","simplified":"约书亚记","chapters":24,"testament":"old"},{"code":"JDG","traditional":"士師記","simplified":"士师记","chapters":21,"testament":"old"},{"code":"RUT","traditional":"路得記","simplified":"路得记","chapters":4,"testament":"old"},{"code":"1SA","traditional":"撒母耳記上","simplified":"撒母耳记上","chapters":31,"testament":"old"},{"code":"2SA","traditional":"撒母耳記下","simplified":"撒母耳记下","chapters":24,"testament":"old"},{"code":"1KI","traditional":"列王紀上","simplified":"列王纪上","chapters":22,"testament":"old"},{"code":"2KI","traditional":"列王紀下","simplified":"列王纪下","chapters":25,"testament":"old"},{"code":"1CH","traditional":"歷代志上","simplified":"历代志上","chapters":29,"testament":"old"},{"code":"2CH","traditional":"歷代志下","simplified":"历代志下","chapters":36,"testament":"old"},{"code":"EZR","traditional":"以斯拉記","simplified":"以斯拉记","chapters":10,"testament":"old"},{"code":"NEH","traditional":"尼希米記","simplified":"尼希米记","chapters":13,"testament":"old"},{"code":"EST","traditional":"以斯帖記","simplified":"以斯帖记","chapters":10,"testament":"old"},{"code":"JOB","traditional":"約伯記","simplified":"约伯记","chapters":42,"testament":"old"},{"code":"PSA","traditional":"詩篇","simplified":"诗篇","chapters":150,"testament":"old"},{"code":"PRO","traditional":"箴言","simplified":"箴言","chapters":31,"testament":"old"},{"code":"ECC","traditional":"傳道書","simplified":"传道书","chapters":12,"testament":"old"},{"code":"SNG","traditional":"雅歌","simplified":"雅歌","chapters":8,"testament":"old"},{"code":"ISA","traditional":"以賽亞書","simplified":"以赛亚书","chapters":66,"testament":"old"},{"code":"JER","traditional":"耶利米書","simplified":"耶利米书","chapters":52,"testament":"old"},{"code":"LAM","traditional":"耶利米哀歌","simplified":"耶利米哀歌","chapters":5,"testament":"old"},{"code":"EZK","traditional":"以西結書","simplified":"以西结书","chapters":48,"testament":"old"},{"code":"DAN","traditional":"但以理書","simplified":"但以理书","chapters":12,"testament":"old"},{"code":"HOS","traditional":"何西阿書","simplified":"何西阿书","chapters":14,"testament":"old"},{"code":"JOL","traditional":"約珥書","simplified":"约珥书","chapters":3,"testament":"old"},{"code":"AMO","traditional":"阿摩司書","simplified":"阿摩司书","chapters":9,"testament":"old"},{"code":"OBA","traditional":"俄巴底亞書","simplified":"俄巴底亚书","chapters":1,"testament":"old"},{"code":"JON","traditional":"約拿書","simplified":"约拿书","chapters":4,"testament":"old"},{"code":"MIC","traditional":"彌迦書","simplified":"弥迦书","chapters":7,"testament":"old"},{"code":"NAM","traditional":"那鴻書","simplified":"那鸿书","chapters":3,"testament":"old"},{"code":"HAB","traditional":"哈巴谷書","simplified":"哈巴谷书","chapters":3,"testament":"old"},{"code":"ZEP","traditional":"西番雅書","simplified":"西番雅书","chapters":3,"testament":"old"},{"code":"HAG","traditional":"哈該書","simplified":"哈该书","chapters":2,"testament":"old"},{"code":"ZEC","traditional":"撒迦利亞書","simplified":"撒迦利亚书","chapters":14,"testament":"old"},{"code":"MAL","traditional":"瑪拉基書","simplified":"玛拉基书","chapters":4,"testament":"old"},{"code":"MAT","traditional":"馬太福音","simplified":"马太福音","chapters":28,"testament":"new"},{"code":"MRK","traditional":"馬可福音","simplified":"马可福音","chapters":16,"testament":"new"},{"code":"LUK","traditional":"路加福音","simplified":"路加福音","chapters":24,"testament":"new"},{"code":"JHN","traditional":"約翰福音","simplified":"约翰福音","chapters":21,"testament":"new"},{"code":"ACT","traditional":"使徒行傳","simplified":"使徒行传","chapters":28,"testament":"new"},{"code":"ROM","traditional":"羅馬書","simplified":"罗马书","chapters":16,"testament":"new"},{"code":"1CO","traditional":"哥林多前書","simplified":"哥林多前书","chapters":16,"testament":"new"},{"code":"2CO","traditional":"哥林多後書","simplified":"哥林多后书","chapters":13,"testament":"new"},{"code":"GAL","traditional":"加拉太書","simplified":"加拉太书","chapters":6,"testament":"new"},{"code":"EPH","traditional":"以弗所書","simplified":"以弗所书","chapters":6,"testament":"new"},{"code":"PHP","traditional":"腓立比書","simplified":"腓立比书","chapters":4,"testament":"new"},{"code":"COL","traditional":"歌羅西書","simplified":"歌罗西书","chapters":4,"testament":"new"},{"code":"1TH","traditional":"帖撒羅尼迦前書","simplified":"帖撒罗尼迦前书","chapters":5,"testament":"new"},{"code":"2TH","traditional":"帖撒羅尼迦後書","simplified":"帖撒罗尼迦后书","chapters":3,"testament":"new"},{"code":"1TI","traditional":"提摩太前書","simplified":"提摩太前书","chapters":6,"testament":"new"},{"code":"2TI","traditional":"提摩太後書","simplified":"提摩太后书","chapters":4,"testament":"new"},{"code":"TIT","traditional":"提多書","simplified":"提多书","chapters":3,"testament":"new"},{"code":"PHM","traditional":"腓利門書","simplified":"腓利门书","chapters":1,"testament":"new"},{"code":"HEB","traditional":"希伯來書","simplified":"希伯来书","chapters":13,"testament":"new"},{"code":"JAS","traditional":"雅各書","simplified":"雅各书","chapters":5,"testament":"new"},{"code":"1PE","traditional":"彼得前書","simplified":"彼得前书","chapters":5,"testament":"new"},{"code":"2PE","traditional":"彼得後書","simplified":"彼得后书","chapters":3,"testament":"new"},{"code":"1JN","traditional":"約翰一書","simplified":"约翰一书","chapters":5,"testament":"new"},{"code":"2JN","traditional":"約翰二書","simplified":"约翰二书","chapters":1,"testament":"new"},{"code":"3JN","traditional":"約翰三書","simplified":"约翰三书","chapters":1,"testament":"new"},{"code":"JUD","traditional":"猶大書","simplified":"犹大书","chapters":1,"testament":"new"},{"code":"REV","traditional":"啟示錄","simplified":"启示录","chapters":22,"testament":"new"}],"chapters":{"cunp":{"simplified":{"GEN":{"1":{"heading":"神的创造","verses":[{"n":1,"t":"起初，神创造天地。","notes":[]},{"n":2,"t":"地是空虚混沌，渊面黑暗；神的灵运行在水面上。","notes":[]},{"n":3,"t":"神说：「要有光」，就有了光。","notes":[]},{"n":4,"t":"神看光是好的，就把光暗分开了。","notes":[]},{"n":5,"t":"神称光为「昼」，称暗为「夜」。有晚上，有早晨，这是头一日。","notes":[]},{"n":6,"t":"神说：「诸水之间要有空气，将水分为上下。」","notes":[]},{"n":7,"t":"神就造出空气，将空气以下的水、空气以上的水分开了。事就这样成了。","notes":[]},{"n":8,"t":"神称空气为「天」。有晚上，有早晨，是第二日。","notes":[]},{"n":9,"t":"神说：「天下的水要聚在一处，使旱地露出来。」事就这样成了。","notes":[]},{"n":10,"t":"神称旱地为「地」，称水的聚处为「海」。神看着是好的。","notes":[]},{"n":11,"t":"神说：「地要发生青草和结种子的菜蔬，并结果子的树木，各从其类，果子都包着核。」事就这样成了。","notes":[]},{"n":12,"t":"于是地发生了青草和结种子的菜蔬，各从其类；并结果子的树木，各从其类；果子都包着核。神看着是好的。","notes":[]},{"n":13,"t":"有晚上，有早晨，是第三日。","notes":[]},{"n":14,"t":"神说：「天上要有光体，可以分昼夜，作记号，定节令、日子、年岁，","notes":[]},{"n":15,"t":"并要发光在天空，普照在地上。」事就这样成了。","notes":[]},{"n":16,"t":"于是神造了两个大光，大的管昼，小的管夜，又造众星，","notes":[]},{"n":17,"t":"就把这些光摆列在天空，普照在地上，","notes":[]},{"n":18,"t":"管理昼夜，分别明暗。神看着是好的。","notes":[]},{"n":19,"t":"有晚上，有早晨，是第四日。","notes":[]},{"n":20,"t":"神说：「水要多多滋生有生命的物；要有雀鸟飞在地面以上，天空之中。」","notes":[]},{"n":21,"t":"神就造出大鱼和水中所滋生各样有生命的动物，各从其类；又造出各样飞鸟，各从其类。神看着是好的。","notes":[]},{"n":22,"t":"神就赐福给这一切，说：「滋生繁多，充满海中的水；雀鸟也要多生在地上。」","notes":[]},{"n":23,"t":"有晚上，有早晨，是第五日。","notes":[]},{"n":24,"t":"神说：「地要生出活物来，各从其类；牲畜、昆虫、野兽，各从其类。」事就这样成了。","notes":[]},{"n":25,"t":"于是神造出野兽，各从其类；牲畜，各从其类；地上一切昆虫，各从其类。神看着是好的。","notes":[]},{"n":26,"t":"神说：「我们要照着我们的形象、按着我们的样式造人，使他们管理海里的鱼、空中的鸟、地上的牲畜，和全地，并地上所爬的一切昆虫。」","notes":[]},{"n":27,"t":"神就照着自己的形象造人，乃是照着他的形象造男造女。","notes":[]},{"n":28,"t":"神就赐福给他们，又对他们说：「要生养众多，遍满地面，治理这地，也要管理海里的鱼、空中的鸟，和地上各样行动的活物。」","notes":[]},{"n":29,"t":"神说：「看哪，我将遍地上一切结种子的菜蔬和一切树上所结有核的果子全赐给你们作食物。","notes":[]},{"n":30,"t":"至于地上的走兽和空中的飞鸟，并各样爬在地上有生命的物，我将青草赐给它们作食物。」事就这样成了。","notes":[]},{"n":31,"t":"神看着一切所造的都甚好。有晚上，有早晨，是第六日。","notes":[]}]},"2":{"heading":"伊甸园","verses":[{"n":1,"t":"天地万物都造齐了。","notes":[]},{"n":2,"t":"到第七日，神造物的工已经完毕，就在第七日歇了他一切的工，安息了。","notes":[]},{"n":3,"t":"神赐福给第七日，定为圣日；因为在这日，神歇了他一切创造的工，就安息了。","notes":[]},{"n":4,"t":"创造天地的来历，在耶和华神造天地的日子，乃是这样，","notes":[]},{"n":5,"t":"野地还没有草木，田间的菜蔬还没有长起来；因为耶和华神还没有降雨在地上，也没有人耕地，","notes":[]},{"n":6,"t":"但有雾气从地上腾，滋润遍地。","notes":[]},{"n":7,"t":"耶和华神用地上的尘土造人，将生气吹在他鼻孔里，他就成了有灵的活人，名叫亚当。","notes":[]},{"n":8,"t":"耶和华神在东方的伊甸立了一个园子，把所造的人安置在那里。","notes":[]},{"n":9,"t":"耶和华神使各样的树从地里长出来，可以悦人的眼目，其上的果子好作食物。园子当中又有生命树和分别善恶的树。","notes":[]},{"n":10,"t":"有河从伊甸流出来，滋润那园子，从那里分为四道：","notes":[]},{"n":11,"t":"第一道名叫比逊，就是环绕哈腓拉全地的。在那里有金子，","notes":[]},{"n":12,"t":"并且那地的金子是好的；在那里又有珍珠和红玛瑙。","notes":[]},{"n":13,"t":"第二道河名叫基训，就是环绕古实全地的。","notes":[]},{"n":14,"t":"第三道河名叫底格里斯，流在亚述的东边。第四道河就是幼发拉底河。","notes":[]},{"n":15,"t":"耶和华神将那人安置在伊甸园，使他修理，看守。","notes":[]},{"n":16,"t":"耶和华神吩咐他说：「园中各样树上的果子，你可以随意吃，","notes":[]},{"n":17,"t":"只是分别善恶树上的果子，你不可吃，因为你吃的日子必定死！」","notes":[]},{"n":18,"t":"耶和华神说：「那人独居不好，我要为他造一个配偶帮助他。」","notes":[]},{"n":19,"t":"耶和华神用土所造成的野地各样走兽和空中各样飞鸟都带到那人面前，看他叫什么。那人怎样叫各样的活物，那就是它的名字。","notes":[]},{"n":20,"t":"那人便给一切牲畜和空中飞鸟、野地走兽都起了名；只是那人没有遇见配偶帮助他。","notes":[]},{"n":21,"t":"耶和华神使他沉睡，他就睡了；于是取下他的一条肋骨，又把肉合起来。","notes":[]},{"n":22,"t":"耶和华神就用那人身上所取的肋骨造成一个女人，领她到那人跟前。","notes":[]},{"n":23,"t":"那人说：这是我骨中的骨，肉中的肉，可以称她为「女人」，因为她是从「男人」身上取出来的。","notes":[]},{"n":24,"t":"因此，人要离开父母，与妻子连合，二人成为一体。","notes":[]},{"n":25,"t":"当时夫妻二人赤身露体，并不羞耻。","notes":[]}]},"3":{"heading":"人违背命令","verses":[{"n":1,"t":"耶和华神所造的，惟有蛇比田野一切的活物更狡猾。蛇对女人说：「神岂是真说不许你们吃园中所有树上的果子吗？」","notes":[]},{"n":2,"t":"女人对蛇说：「园中树上的果子，我们可以吃，","notes":[]},{"n":3,"t":"惟有园当中那棵树上的果子，神曾说：『你们不可吃，也不可摸，免得你们死。』」","notes":[]},{"n":4,"t":"蛇对女人说：「你们不一定死；","notes":[]},{"n":5,"t":"因为神知道，你们吃的日子眼睛就明亮了，你们便如神能知道善恶。」","notes":[]},{"n":6,"t":"于是女人见那棵树的果子好作食物，也悦人的眼目，且是可喜爱的，能使人有智慧，就摘下果子来吃了，又给她丈夫，她丈夫也吃了。","notes":[]},{"n":7,"t":"他们二人的眼睛就明亮了，才知道自己是赤身露体，便拿无花果树的叶子为自己编做裙子。","notes":[]},{"n":8,"t":"天起了凉风，耶和华神在园中行走。那人和他妻子听见神的声音，就藏在园里的树木中，躲避耶和华神的面。","notes":[]},{"n":9,"t":"耶和华神呼唤那人，对他说：「你在哪里？」","notes":[]},{"n":10,"t":"他说：「我在园中听见你的声音，我就害怕；因为我赤身露体，我便藏了。」","notes":[]},{"n":11,"t":"耶和华说：「谁告诉你赤身露体呢？莫非你吃了我吩咐你不可吃的那树上的果子吗？」","notes":[]},{"n":12,"t":"那人说：「你所赐给我、与我同居的女人，她把那树上的果子给我，我就吃了。」","notes":[]},{"n":13,"t":"耶和华神对女人说：「你做的是什么事呢？」女人说：「那蛇引诱我，我就吃了。」","notes":[]},{"n":14,"t":"耶和华神对蛇说：你既做了这事，就必受咒诅，比一切的牲畜野兽更甚；你必用肚子行走，终身吃土。","notes":[],"heads":["神的宣判"]},{"n":15,"t":"我又要叫你和女人彼此为仇；你的后裔和女人的后裔也彼此为仇。女人的后裔要伤你的头；你要伤他的脚跟。","notes":[]},{"n":16,"t":"又对女人说：我必多多加增你怀胎的苦楚；你生产儿女必多受苦楚。你必恋慕你丈夫；你丈夫必管辖你。","notes":[]},{"n":17,"t":"又对亚当说：你既听从妻子的话，吃了我所吩咐你不可吃的那树上的果子，地必为你的缘故受咒诅；你必终身劳苦才能从地里得吃的。","notes":[]},{"n":18,"t":"地必给你长出荆棘和蒺藜来；你也要吃田间的菜蔬。","notes":[]},{"n":19,"t":"你必汗流满面才得糊口，直到你归了土，因为你是从土而出的。你本是尘土，仍要归于尘土。","notes":[]},{"n":20,"t":"亚当给他妻子起名叫夏娃，因为她是众生之母。","notes":[]},{"n":21,"t":"耶和华神为亚当和他妻子用皮子做衣服给他们穿。","notes":[]},{"n":22,"t":"耶和华神说：「那人已经与我们相似，能知道善恶；现在恐怕他伸手又摘生命树的果子吃，就永远活着。」","notes":[],"heads":["亚当和夏娃被赶出伊甸园"]},{"n":23,"t":"耶和华神便打发他出伊甸园去，耕种他所自出之土。","notes":[]},{"n":24,"t":"于是把他赶出去了；又在伊甸园的东边安设基路伯和四面转动发火焰的剑，要把守生命树的道路。","notes":[]}]},"4":{"heading":"该隐和亚伯","verses":[{"n":1,"t":"有一日，那人和他妻子夏娃同房，夏娃就怀孕，生了该隐，便说：「耶和华使我得了一个男子。」","notes":["就是得的意思"]},{"n":2,"t":"又生了该隐的兄弟亚伯。亚伯是牧羊的；该隐是种地的。","notes":[]},{"n":3,"t":"有一日，该隐拿地里的出产为供物献给耶和华；","notes":[]},{"n":4,"t":"亚伯也将他羊群中头生的和羊的脂油献上。耶和华看中了亚伯和他的供物，","notes":[]},{"n":5,"t":"只是看不中该隐和他的供物。该隐就大大地发怒，变了脸色。","notes":[]},{"n":6,"t":"耶和华对该隐说：「你为什么发怒呢？你为什么变了脸色呢？","notes":[]},{"n":7,"t":"你若行得好，岂不蒙悦纳？你若行得不好，罪就伏在门前。它必恋慕你，你却要制伏它。」","notes":[]},{"n":8,"t":"该隐与他兄弟亚伯说话；二人正在田间。该隐起来打他兄弟亚伯，把他杀了。","notes":[]},{"n":9,"t":"耶和华对该隐说：「你兄弟亚伯在哪里？」他说：「我不知道！我岂是看守我兄弟的吗？」","notes":[]},{"n":10,"t":"耶和华说：「你做了什么事呢？你兄弟的血有声音从地里向我哀告。","notes":[]},{"n":11,"t":"地开了口，从你手里接受你兄弟的血。现在你必从这地受咒诅。","notes":[]},{"n":12,"t":"你种地，地不再给你效力；你必流离飘荡在地上。」","notes":[]},{"n":13,"t":"该隐对耶和华说：「我的刑罚太重，过于我所能当的。","notes":[]},{"n":14,"t":"你如今赶逐我离开这地，以致不见你面；我必流离飘荡在地上，凡遇见我的必杀我。」","notes":[]},{"n":15,"t":"耶和华对他说：「凡杀该隐的，必遭报七倍。」耶和华就给该隐立一个记号，免得人遇见他就杀他。","notes":[]},{"n":16,"t":"于是该隐离开耶和华的面，去住在伊甸东边挪得之地。","notes":[]},{"n":17,"t":"该隐与妻子同房，他妻子就怀孕，生了以诺。该隐建造了一座城，就按着他儿子的名将那城叫做以诺。","notes":[],"heads":["该隐的后代"]},{"n":18,"t":"以诺生以拿；以拿生米户雅利；米户雅利生玛土撒利；玛土撒利生拉麦。","notes":[]},{"n":19,"t":"拉麦娶了两个妻：一个名叫亚大，一个名叫洗拉。","notes":[]},{"n":20,"t":"亚大生雅八；雅八就是住帐棚、牧养牲畜之人的祖师。","notes":[]},{"n":21,"t":"雅八的兄弟名叫犹八；他是一切弹琴吹箫之人的祖师。","notes":[]},{"n":22,"t":"洗拉又生了土八·该隐；他是打造各样铜铁利器的。土八·该隐的妹子是拿玛。","notes":["或译：是铜匠铁匠的祖师"]},{"n":23,"t":"拉麦对他两个妻子说：亚大、洗拉，听我的声音；拉麦的妻子，细听我的话语：壮年人伤我，我把他杀了；少年人损我，我把他害了。","notes":["或译：我杀壮士却伤自己，我害幼童却损本身"]},{"n":24,"t":"若杀该隐，遭报七倍，杀拉麦，必遭报七十七倍。","notes":[]},{"n":25,"t":"亚当又与妻子同房，她就生了一个儿子，起名叫塞特，意思说：「神另给我立了一个儿子代替亚伯，因为该隐杀了他。」","notes":[],"heads":["塞特和以挪士"]},{"n":26,"t":"塞特也生了一个儿子，起名叫以挪士。那时候，人才求告耶和华的名。","notes":[]}]},"5":{"heading":"亚当的后代","verses":[{"n":1,"t":"亚当的后代记在下面。（当神造人的日子，是照着自己的样式造的，","notes":[]},{"n":2,"t":"并且造男造女。在他们被造的日子，神赐福给他们，称他们为「人」。）","notes":[]},{"n":3,"t":"亚当活到一百三十岁，生了一个儿子，形象样式和自己相似，就给他起名叫塞特。","notes":[]},{"n":4,"t":"亚当生塞特之后，又在世八百年，并且生儿养女。","notes":[]},{"n":5,"t":"亚当共活了九百三十岁就死了。","notes":[]},{"n":6,"t":"塞特活到一百零五岁，生了以挪士。","notes":[]},{"n":7,"t":"塞特生以挪士之后，又活了八百零七年，并且生儿养女。","notes":[]},{"n":8,"t":"塞特共活了九百一十二岁就死了。","notes":[]},{"n":9,"t":"以挪士活到九十岁，生了该南。","notes":[]},{"n":10,"t":"以挪士生该南之后，又活了八百一十五年，并且生儿养女。","notes":[]},{"n":11,"t":"以挪士共活了九百零五岁就死了。","notes":[]},{"n":12,"t":"该南活到七十岁，生了玛勒列。","notes":[]},{"n":13,"t":"该南生玛勒列之后，又活了八百四十年，并且生儿养女。","notes":[]},{"n":14,"t":"该南共活了九百一十岁就死了。","notes":[]},{"n":15,"t":"玛勒列活到六十五岁，生了雅列。","notes":[]},{"n":16,"t":"玛勒列生雅列之后，又活了八百三十年，并且生儿养女。","notes":[]},{"n":17,"t":"玛勒列共活了八百九十五岁就死了。","notes":[]},{"n":18,"t":"雅列活到一百六十二岁，生了以诺。","notes":[]},{"n":19,"t":"雅列生以诺之后，又活了八百年，并且生儿养女。","notes":[]},{"n":20,"t":"雅列共活了九百六十二岁就死了。","notes":[]},{"n":21,"t":"以诺活到六十五岁，生了玛土撒拉。","notes":[]},{"n":22,"t":"以诺生玛土撒拉之后，与神同行三百年，并且生儿养女。","notes":[]},{"n":23,"t":"以诺共活了三百六十五岁。","notes":[]},{"n":24,"t":"以诺与神同行，神将他取去，他就不在世了。","notes":[]},{"n":25,"t":"玛土撒拉活到一百八十七岁，生了拉麦。","notes":[]},{"n":26,"t":"玛土撒拉生拉麦之后，又活了七百八十二年，并且生儿养女。","notes":[]},{"n":27,"t":"玛土撒拉共活了九百六十九岁就死了。","notes":[]},{"n":28,"t":"拉麦活到一百八十二岁，生了一个儿子，","notes":[]},{"n":29,"t":"给他起名叫挪亚，说：「这个儿子必为我们的操作和手中的劳苦安慰我们；这操作劳苦是因为耶和华咒诅地。」","notes":[]},{"n":30,"t":"拉麦生挪亚之后，又活了五百九十五年，并且生儿养女。","notes":[]},{"n":31,"t":"拉麦共活了七百七十七岁就死了。","notes":[]},{"n":32,"t":"挪亚五百岁生了闪、含、雅弗。","notes":[]}]},"6":{"heading":"人类的邪恶","verses":[{"n":1,"t":"当人在世上多起来、又生女儿的时候，","notes":[]},{"n":2,"t":"神的儿子们看见人的女子美貌，就随意挑选，娶来为妻。","notes":[]},{"n":3,"t":"耶和华说：「人既属乎血气，我的灵就不永远住在他里面；然而他的日子还可到一百二十年。」","notes":[]},{"n":4,"t":"那时候有伟人在地上，后来神的儿子们和人的女子们交合生子；那就是上古英武有名的人。","notes":[]},{"n":5,"t":"耶和华见人在地上罪恶很大，终日所思想的尽都是恶，","notes":[]},{"n":6,"t":"耶和华就后悔造人在地上，心中忧伤。","notes":[]},{"n":7,"t":"耶和华说：「我要将所造的人和走兽，并昆虫，以及空中的飞鸟，都从地上除灭，因为我造他们后悔了。」","notes":[]},{"n":8,"t":"惟有挪亚在耶和华眼前蒙恩。","notes":[]},{"n":9,"t":"挪亚的后代记在下面。挪亚是个义人，在当时的世代是个完全人。挪亚与神同行。","notes":[],"heads":["挪亚"]},{"n":10,"t":"挪亚生了三个儿子，就是闪、含、雅弗。","notes":[]},{"n":11,"t":"世界在神面前败坏，地上满了强暴。","notes":[]},{"n":12,"t":"神观看世界，见是败坏了；凡有血气的人在地上都败坏了行为。","notes":[]},{"n":13,"t":"神就对挪亚说：「凡有血气的人，他的尽头已经来到我面前；因为地上满了他们的强暴，我要把他们和地一并毁灭。","notes":[]},{"n":14,"t":"你要用歌斐木造一只方舟，分一间一间地造，里外抹上松香。","notes":[]},{"n":15,"t":"方舟的造法乃是这样：要长三百肘，宽五十肘，高三十肘。","notes":[]},{"n":16,"t":"方舟上边要留透光处，高一肘。方舟的门要开在旁边。方舟要分上、中、下三层。","notes":[]},{"n":17,"t":"看哪，我要使洪水泛滥在地上，毁灭天下；凡地上有血肉、有气息的活物，无一不死。","notes":[]},{"n":18,"t":"我却要与你立约；你同你的妻，与儿子儿妇，都要进入方舟。","notes":[]},{"n":19,"t":"凡有血肉的活物，每样两个，一公一母，你要带进方舟，好在你那里保全生命。","notes":[]},{"n":20,"t":"飞鸟各从其类，牲畜各从其类，地上的昆虫各从其类，每样两个，要到你那里，好保全生命。","notes":[]},{"n":21,"t":"你要拿各样食物积蓄起来，好作你和它们的食物。」","notes":[]},{"n":22,"t":"挪亚就这样行。凡神所吩咐的，他都照样行了。","notes":[]}]},"7":{"heading":"洪水","verses":[{"n":1,"t":"耶和华对挪亚说：「你和你的全家都要进入方舟；因为在这世代中，我见你在我面前是义人。","notes":[]},{"n":2,"t":"凡洁净的畜类，你要带七公七母；不洁净的畜类，你要带一公一母；","notes":[]},{"n":3,"t":"空中的飞鸟也要带七公七母，可以留种，活在全地上；","notes":[]},{"n":4,"t":"因为再过七天，我要降雨在地上四十昼夜，把我所造的各种活物都从地上除灭。」","notes":[]},{"n":5,"t":"挪亚就遵着耶和华所吩咐的行了。","notes":[]},{"n":6,"t":"当洪水泛滥在地上的时候，挪亚整六百岁。","notes":[]},{"n":7,"t":"挪亚就同他的妻和儿子儿妇都进入方舟，躲避洪水。","notes":[]},{"n":8,"t":"洁净的畜类和不洁净的畜类，飞鸟并地上一切的昆虫，","notes":[]},{"n":9,"t":"都是一对一对地，有公有母，到挪亚那里进入方舟，正如神所吩咐挪亚的。","notes":[]},{"n":10,"t":"过了那七天，洪水泛滥在地上。","notes":[]},{"n":11,"t":"当挪亚六百岁，二月十七日那一天，大渊的泉源都裂开了，天上的窗户也敞开了，","notes":[]},{"n":12,"t":"四十昼夜降大雨在地上。","notes":[]},{"n":13,"t":"正当那日，挪亚和他三个儿子闪、含、雅弗，并挪亚的妻子和三个儿妇，都进入方舟。","notes":[]},{"n":14,"t":"他们和百兽，各从其类，一切牲畜，各从其类，爬在地上的昆虫，各从其类，一切禽鸟，各从其类，都进入方舟。","notes":[]},{"n":15,"t":"凡有血肉、有气息的活物，都一对一对地到挪亚那里，进入方舟。","notes":[]},{"n":16,"t":"凡有血肉进入方舟的，都是有公有母，正如神所吩咐挪亚的。耶和华就把他关在方舟里头。","notes":[]},{"n":17,"t":"洪水泛滥在地上四十天，水往上长，把方舟从地上漂起。","notes":[]},{"n":18,"t":"水势浩大，在地上大大地往上长，方舟在水面上漂来漂去。","notes":[]},{"n":19,"t":"水势在地上极其浩大，天下的高山都淹没了。","notes":[]},{"n":20,"t":"水势比山高过十五肘，山岭都淹没了。","notes":[]},{"n":21,"t":"凡在地上有血肉的动物，就是飞鸟、牲畜、走兽，和爬在地上的昆虫，以及所有的人，都死了。","notes":[]},{"n":22,"t":"凡在旱地上、鼻孔有气息的生灵都死了。","notes":[]},{"n":23,"t":"凡地上各类的活物，连人带牲畜、昆虫，以及空中的飞鸟，都从地上除灭了，只留下挪亚和那些与他同在方舟里的。","notes":[]},{"n":24,"t":"水势浩大，在地上共一百五十天。","notes":[]}]},"8":{"heading":"洪水消退","verses":[{"n":1,"t":"神记念挪亚和挪亚方舟里的一切走兽牲畜。神叫风吹地，水势渐落。","notes":[]},{"n":2,"t":"渊源和天上的窗户都闭塞了，天上的大雨也止住了。","notes":[]},{"n":3,"t":"水从地上渐退。过了一百五十天，水就渐消。","notes":[]},{"n":4,"t":"七月十七日，方舟停在亚拉腊山上。","notes":[]},{"n":5,"t":"水又渐消，到十月初一日，山顶都现出来了。","notes":[]},{"n":6,"t":"过了四十天，挪亚开了方舟的窗户，","notes":[]},{"n":7,"t":"放出一只乌鸦去；那乌鸦飞来飞去，直到地上的水都干了。","notes":[]},{"n":8,"t":"他又放出一只鸽子去，要看看水从地上退了没有。","notes":[]},{"n":9,"t":"但遍地上都是水，鸽子找不着落脚之地，就回到方舟挪亚那里，挪亚伸手把鸽子接进方舟来。","notes":[]},{"n":10,"t":"他又等了七天，再把鸽子从方舟放出去。","notes":[]},{"n":11,"t":"到了晚上，鸽子回到他那里，嘴里叼着一个新拧下来的橄榄叶子，挪亚就知道地上的水退了。","notes":[]},{"n":12,"t":"他又等了七天，放出鸽子去，鸽子就不再回来了。","notes":[]},{"n":13,"t":"到挪亚六百零一岁，正月初一日，地上的水都干了。挪亚撤去方舟的盖观看，便见地面上干了。","notes":[]},{"n":14,"t":"到了二月二十七日，地就都干了。","notes":[]},{"n":15,"t":"神对挪亚说：","notes":[]},{"n":16,"t":"「你和你的妻子、儿子、儿妇都可以出方舟。","notes":[]},{"n":17,"t":"在你那里凡有血肉的活物，就是飞鸟、牲畜，和一切爬在地上的昆虫，都要带出来，叫它在地上多多滋生，大大兴旺。」","notes":[]},{"n":18,"t":"于是挪亚和他的妻子、儿子、儿妇都出来了。","notes":[]},{"n":19,"t":"一切走兽、昆虫、飞鸟，和地上所有的动物，各从其类，也都出了方舟。","notes":[]},{"n":20,"t":"挪亚为耶和华筑了一座坛，拿各类洁净的牲畜、飞鸟献在坛上为燔祭。","notes":[],"heads":["挪亚献祭"]},{"n":21,"t":"耶和华闻那馨香之气，就心里说：「我不再因人的缘故咒诅地（人从小时心里怀着恶念），也不再按着我才行的灭各种的活物了。","notes":[]},{"n":22,"t":"地还存留的时候，稼穑、寒暑、冬夏、昼夜就永不停息了。」","notes":[]}]},"9":{"heading":"神跟挪亚立约","verses":[{"n":1,"t":"神赐福给挪亚和他的儿子，对他们说：「你们要生养众多，遍满了地。","notes":[]},{"n":2,"t":"凡地上的走兽和空中的飞鸟都必惊恐，惧怕你们，连地上一切的昆虫并海里一切的鱼都交付你们的手。","notes":[]},{"n":3,"t":"凡活着的动物都可以作你们的食物。这一切我都赐给你们，如同菜蔬一样。","notes":[]},{"n":4,"t":"惟独肉带着血，那就是它的生命，你们不可吃。","notes":[]},{"n":5,"t":"流你们血、害你们命的，无论是兽是人，我必讨他的罪，就是向各人的弟兄也是如此。","notes":[]},{"n":6,"t":"凡流人血的，他的血也必被人所流，因为神造人是照自己的形象造的。","notes":[]},{"n":7,"t":"你们要生养众多，在地上昌盛繁茂。」","notes":[]},{"n":8,"t":"神晓谕挪亚和他的儿子说：","notes":[]},{"n":9,"t":"「我与你们和你们的后裔立约，","notes":[]},{"n":10,"t":"并与你们这里的一切活物—就是飞鸟、牲畜、走兽，凡从方舟里出来的活物—立约。","notes":[]},{"n":11,"t":"我与你们立约，凡有血肉的，不再被洪水灭绝，也不再有洪水毁坏地了。」","notes":[]},{"n":12,"t":"神说：「我与你们并你们这里的各样活物所立的永约是有记号的。","notes":[]},{"n":13,"t":"我把虹放在云彩中，这就可作我与地立约的记号了。","notes":[]},{"n":14,"t":"我使云彩盖地的时候，必有虹现在云彩中，","notes":[]},{"n":15,"t":"我便记念我与你们和各样有血肉的活物所立的约，水就再不泛滥、毁坏一切有血肉的物了。","notes":[]},{"n":16,"t":"虹必现在云彩中，我看见，就要记念我与地上各样有血肉的活物所立的永约。」","notes":[]},{"n":17,"t":"神对挪亚说：「这就是我与地上一切有血肉之物立约的记号了。」","notes":[]},{"n":18,"t":"出方舟挪亚的儿子就是闪、含、雅弗。含是迦南的父亲。","notes":[],"heads":["挪亚和他的儿子们"]},{"n":19,"t":"这是挪亚的三个儿子，他们的后裔分散在全地。","notes":[]},{"n":20,"t":"挪亚作起农夫来，栽了一个葡萄园。","notes":[]},{"n":21,"t":"他喝了园中的酒便醉了，在帐棚里赤着身子。","notes":[]},{"n":22,"t":"迦南的父亲含看见他父亲赤身，就到外边告诉他两个弟兄。","notes":[]},{"n":23,"t":"于是闪和雅弗拿件衣服搭在肩上，倒退着进去，给他父亲盖上；他们背着脸就看不见父亲的赤身。","notes":[]},{"n":24,"t":"挪亚醒了酒，知道小儿子向他所做的事，","notes":[]},{"n":25,"t":"就说：迦南当受咒诅，必给他弟兄作奴仆的奴仆；","notes":[]},{"n":26,"t":"又说：耶和华—闪的神是应当称颂的！愿迦南作闪的奴仆。","notes":[]},{"n":27,"t":"愿神使雅弗扩张，使他住在闪的帐棚里；又愿迦南作他的奴仆。","notes":[]},{"n":28,"t":"洪水以后，挪亚又活了三百五十年。","notes":[]},{"n":29,"t":"挪亚共活了九百五十岁就死了。","notes":[]}]},"10":{"heading":"闪、含、雅弗的后代","verses":[{"n":1,"t":"挪亚的儿子闪、含、雅弗的后代记在下面。洪水以后，他们都生了儿子。","notes":[]},{"n":2,"t":"雅弗的儿子是歌篾、玛各、玛代、雅完、土巴、米设、提拉。","notes":[]},{"n":3,"t":"歌篾的儿子是亚实基拿、利法、陀迦玛。","notes":[]},{"n":4,"t":"雅完的儿子是以利沙、他施、基提、多单。","notes":[]},{"n":5,"t":"这些人的后裔将各国的地土、海岛分开居住，各随各的方言、宗族立国。","notes":[]},{"n":6,"t":"含的儿子是古实、麦西、弗、迦南。","notes":[]},{"n":7,"t":"古实的儿子是西巴、哈腓拉、撒弗他、拉玛、撒弗提迦。拉玛的儿子是示巴、底但。","notes":[]},{"n":8,"t":"古实又生宁录，他为世上英雄之首。","notes":[]},{"n":9,"t":"他在耶和华面前是个英勇的猎户，所以俗语说：「像宁录在耶和华面前是个英勇的猎户。」","notes":[]},{"n":10,"t":"他国的起头是巴别、以力、亚甲、甲尼，都在示拿地。","notes":[]},{"n":11,"t":"他从那地出来往亚述去，建造尼尼微、利河伯、迦拉，","notes":[]},{"n":12,"t":"和尼尼微、迦拉中间的利鲜，这就是那大城。","notes":[]},{"n":13,"t":"麦西生路低人、亚拿米人、利哈比人、拿弗土希人、","notes":[]},{"n":14,"t":"帕斯鲁细人、迦斯路希人、迦斐托人；从迦斐托出来的有非利士人。","notes":[]},{"n":15,"t":"迦南生长子西顿，又生赫","notes":[]},{"n":16,"t":"和耶布斯人、亚摩利人、革迦撒人、","notes":[]},{"n":17,"t":"希未人、亚基人、西尼人、","notes":[]},{"n":18,"t":"亚瓦底人、洗玛利人、哈马人，后来迦南的诸族分散了。","notes":[]},{"n":19,"t":"迦南的境界是从西顿向基拉耳的路上，直到迦萨，又向所多玛、蛾摩拉、押玛、洗扁的路上，直到拉沙。","notes":[]},{"n":20,"t":"这就是含的后裔，各随他们的宗族、方言，所住的地土、邦国。","notes":[]},{"n":21,"t":"雅弗的哥哥闪，是希伯子孙之祖，他也生了儿子。","notes":[]},{"n":22,"t":"闪的儿子是以拦、亚述、亚法撒、路德、亚兰。","notes":[]},{"n":23,"t":"亚兰的儿子是乌斯、户勒、基帖、玛施。","notes":[]},{"n":24,"t":"亚法撒生沙拉；沙拉生希伯。","notes":[]},{"n":25,"t":"希伯生了两个儿子，一个名叫法勒，因为那时人就分地居住；法勒的兄弟名叫约坍。","notes":["就是分的意思"]},{"n":26,"t":"约坍生亚摩答、沙列、哈萨玛非、耶拉、","notes":[]},{"n":27,"t":"哈多兰、乌萨、德拉、","notes":[]},{"n":28,"t":"俄巴路、亚比玛利、示巴、","notes":[]},{"n":29,"t":"阿斐、哈腓拉、约巴，这都是约坍的儿子。","notes":[]},{"n":30,"t":"他们所住的地方是从米沙直到西发东边的山。","notes":[]},{"n":31,"t":"这就是闪的子孙，各随他们的宗族、方言，所住的地土、邦国。","notes":[]},{"n":32,"t":"这些都是挪亚三个儿子的宗族，各随他们的支派立国。洪水以后，他们在地上分为邦国。","notes":[]}]},"11":{"heading":"巴别塔","verses":[{"n":1,"t":"那时，天下人的口音、言语都是一样。","notes":[]},{"n":2,"t":"他们往东边迁移的时候，在示拿地遇见一片平原，就住在那里。","notes":[]},{"n":3,"t":"他们彼此商量说：「来吧！我们要做砖，把砖烧透了。」他们就拿砖当石头，又拿石漆当灰泥。","notes":[]},{"n":4,"t":"他们说：「来吧！我们要建造一座城和一座塔，塔顶通天，为要传扬我们的名，免得我们分散在全地上。」","notes":[]},{"n":5,"t":"耶和华降临，要看看世人所建造的城和塔。","notes":[]},{"n":6,"t":"耶和华说：「看哪，他们成为一样的人民，都是一样的言语，如今既做起这事来，以后他们所要做的事就没有不成就的了。","notes":[]},{"n":7,"t":"我们下去，在那里变乱他们的口音，使他们的言语彼此不通。」","notes":[]},{"n":8,"t":"于是耶和华使他们从那里分散在全地上；他们就停工，不造那城了。","notes":[]},{"n":9,"t":"因为耶和华在那里变乱天下人的言语，使众人分散在全地上，所以那城名叫巴别。","notes":["就是变乱的意思"]},{"n":10,"t":"闪的后代记在下面。洪水以后二年，闪一百岁生了亚法撒。","notes":[],"heads":["闪的后代"]},{"n":11,"t":"闪生亚法撒之后又活了五百年，并且生儿养女。","notes":[]},{"n":12,"t":"亚法撒活到三十五岁，生了沙拉。","notes":[]},{"n":13,"t":"亚法撒生沙拉之后又活了四百零三年，并且生儿养女。","notes":[]},{"n":14,"t":"沙拉活到三十岁，生了希伯。","notes":[]},{"n":15,"t":"沙拉生希伯之后又活了四百零三年，并且生儿养女。","notes":[]},{"n":16,"t":"希伯活到三十四岁，生了法勒。","notes":[]},{"n":17,"t":"希伯生法勒之后又活了四百三十年，并且生儿养女。","notes":[]},{"n":18,"t":"法勒活到三十岁，生了拉吴。","notes":[]},{"n":19,"t":"法勒生拉吴之后又活了二百零九年，并且生儿养女。","notes":[]},{"n":20,"t":"拉吴活到三十二岁，生了西鹿。","notes":[]},{"n":21,"t":"拉吴生西鹿之后又活了二百零七年，并且生儿养女。","notes":[]},{"n":22,"t":"西鹿活到三十岁，生了拿鹤。","notes":[]},{"n":23,"t":"西鹿生拿鹤之后又活了二百年，并且生儿养女。","notes":[]},{"n":24,"t":"拿鹤活到二十九岁，生了他拉。","notes":[]},{"n":25,"t":"拿鹤生他拉之后又活了一百一十九年，并且生儿养女。","notes":[]},{"n":26,"t":"他拉活到七十岁，生了亚伯兰、拿鹤、哈兰。","notes":[]},{"n":27,"t":"他拉的后代记在下面。他拉生亚伯兰、拿鹤、哈兰；哈兰生罗得。","notes":[],"heads":["他拉的后代"]},{"n":28,"t":"哈兰死在他的本地迦勒底的吾珥，在他父亲他拉之先。","notes":[]},{"n":29,"t":"亚伯兰、拿鹤各娶了妻：亚伯兰的妻子名叫撒莱；拿鹤的妻子名叫密迦，是哈兰的女儿；哈兰是密迦和亦迦的父亲。","notes":[]},{"n":30,"t":"撒莱不生育，没有孩子。","notes":[]},{"n":31,"t":"他拉带着他儿子亚伯兰和他孙子哈兰的儿子罗得，并他儿妇亚伯兰的妻子撒莱，出了迦勒底的吾珥，要往迦南地去；他们走到哈兰，就住在那里。","notes":[]},{"n":32,"t":"他拉共活了二百零五岁，就死在哈兰。","notes":[]}]},"12":{"heading":"神呼召亚伯兰","verses":[{"n":1,"t":"耶和华对亚伯兰说：「你要离开本地、本族、父家，往我所要指示你的地去。","notes":[]},{"n":2,"t":"我必叫你成为大国。我必赐福给你，叫你的名为大；你也要叫别人得福。","notes":[]},{"n":3,"t":"为你祝福的，我必赐福与他；那咒诅你的，我必咒诅他。地上的万族都要因你得福。」","notes":[]},{"n":4,"t":"亚伯兰就照着耶和华的吩咐去了；罗得也和他同去。亚伯兰出哈兰的时候年七十五岁。","notes":[]},{"n":5,"t":"亚伯兰将他妻子撒莱和侄儿罗得，连他们在哈兰所积蓄的财物、所得的人口，都带往迦南地去。他们就到了迦南地。","notes":[]},{"n":6,"t":"亚伯兰经过那地，到了示剑地方、摩利橡树那里。那时迦南人住在那地。","notes":[]},{"n":7,"t":"耶和华向亚伯兰显现，说：「我要把这地赐给你的后裔。」亚伯兰就在那里为向他显现的耶和华筑了一座坛。","notes":[]},{"n":8,"t":"从那里他又迁到伯特利东边的山，支搭帐棚；西边是伯特利，东边是艾。他在那里又为耶和华筑了一座坛，求告耶和华的名。","notes":[]},{"n":9,"t":"后来亚伯兰又渐渐迁往南地去。","notes":[]},{"n":10,"t":"那地遭遇饥荒。因饥荒甚大，亚伯兰就下埃及去，要在那里暂居。","notes":[],"heads":["亚伯兰到埃及"]},{"n":11,"t":"将近埃及，就对他妻子撒莱说：「我知道你是容貌俊美的妇人。","notes":[]},{"n":12,"t":"埃及人看见你必说：『这是他的妻子』，他们就要杀我，却叫你存活。","notes":[]},{"n":13,"t":"求你说，你是我的妹子，使我因你得平安，我的命也因你存活。」","notes":[]},{"n":14,"t":"及至亚伯兰到了埃及，埃及人看见那妇人极其美貌。","notes":[]},{"n":15,"t":"法老的臣宰看见了她，就在法老面前夸奖她。那妇人就被带进法老的宫去。","notes":[]},{"n":16,"t":"法老因这妇人就厚待亚伯兰，亚伯兰得了许多牛、羊、骆驼、公驴、母驴、仆婢。","notes":[]},{"n":17,"t":"耶和华因亚伯兰妻子撒莱的缘故，降大灾与法老和他的全家。","notes":[]},{"n":18,"t":"法老就召了亚伯兰来，说：「你这向我做的是什么事呢？为什么没有告诉我她是你的妻子？","notes":[]},{"n":19,"t":"为什么说她是你的妹子，以致我把她取来要作我的妻子？现在你的妻子在这里，可以带她走吧。」","notes":[]},{"n":20,"t":"于是法老吩咐人将亚伯兰和他妻子，并他所有的都送走了。","notes":[]}]},"13":{"heading":"亚伯兰跟罗得分手","verses":[{"n":1,"t":"亚伯兰带着他的妻子与罗得，并一切所有的，都从埃及上南地去。","notes":[]},{"n":2,"t":"亚伯兰的金、银、牲畜极多。","notes":[]},{"n":3,"t":"他从南地渐渐往伯特利去，到了伯特利和艾的中间，就是从前支搭帐棚的地方，","notes":[]},{"n":4,"t":"也是他起先筑坛的地方；他又在那里求告耶和华的名。","notes":[]},{"n":5,"t":"与亚伯兰同行的罗得也有牛群、羊群、帐棚。","notes":[]},{"n":6,"t":"那地容不下他们；因为他们的财物甚多，使他们不能同居。","notes":[]},{"n":7,"t":"当时，迦南人与比利洗人在那地居住。亚伯兰的牧人和罗得的牧人相争。","notes":[]},{"n":8,"t":"亚伯兰就对罗得说：「你我不可相争，你的牧人和我的牧人也不可相争，因为我们是骨肉。","notes":["原文是弟兄"]},{"n":9,"t":"遍地不都在你眼前吗？请你离开我：你向左，我就向右；你向右，我就向左。」","notes":[]},{"n":10,"t":"罗得举目看见约旦河的全平原，直到琐珥，都是滋润的，那地在耶和华未灭所多玛、蛾摩拉以先如同耶和华的园子，也像埃及地。","notes":[]},{"n":11,"t":"于是罗得选择约旦河的全平原，往东迁移；他们就彼此分离了。","notes":[]},{"n":12,"t":"亚伯兰住在迦南地，罗得住在平原的城邑，渐渐挪移帐棚，直到所多玛。","notes":[]},{"n":13,"t":"所多玛人在耶和华面前罪大恶极。","notes":[]},{"n":14,"t":"罗得离别亚伯兰以后，耶和华对亚伯兰说：「从你所在的地方，你举目向东西南北观看；","notes":[],"heads":["亚伯兰迁往希伯仑"]},{"n":15,"t":"凡你所看见的一切地，我都要赐给你和你的后裔，直到永远。","notes":[]},{"n":16,"t":"我也要使你的后裔如同地上的尘沙那样多，人若能数算地上的尘沙才能数算你的后裔。","notes":[]},{"n":17,"t":"你起来，纵横走遍这地，因为我必把这地赐给你。」","notes":[]},{"n":18,"t":"亚伯兰就搬了帐棚，来到希伯仑、幔利的橡树那里居住，在那里为耶和华筑了一座坛。","notes":[]}]},"14":{"heading":"亚伯兰抢救罗得","verses":[{"n":1,"t":"当暗拉非作示拿王，亚略作以拉撒王，基大老玛作以拦王，提达作戈印王的时候，","notes":[]},{"n":2,"t":"他们都攻打所多玛王比拉、蛾摩拉王比沙、押玛王示纳、洗扁王善以别，和比拉王；比拉就是琐珥。","notes":[]},{"n":3,"t":"这五王都在西订谷会合；西订谷就是盐海。","notes":[]},{"n":4,"t":"他们已经事奉基大老玛十二年，到十三年就背叛了。","notes":[]},{"n":5,"t":"十四年，基大老玛和同盟的王都来在亚特律·加宁，杀败了利乏音人，在哈麦杀败了苏西人，在沙微·基列亭杀败了以米人，","notes":[]},{"n":6,"t":"在何利人的西珥山杀败了何利人，一直杀到靠近旷野的伊勒·巴兰。","notes":[]},{"n":7,"t":"他们回到安·密巴，就是加低斯，杀败了亚玛力全地的人，以及住在哈洗逊·他玛的亚摩利人。","notes":[]},{"n":8,"t":"于是所多玛王、蛾摩拉王、押玛王、洗扁王，和比拉王（比拉就是琐珥）都出来，在西订谷摆阵，与他们交战，","notes":[]},{"n":9,"t":"就是与以拦王基大老玛、戈印王提达、示拿王暗拉非、以拉撒王亚略交战；乃是四王与五王交战。","notes":[]},{"n":10,"t":"西订谷有许多石漆坑。所多玛王和蛾摩拉王逃跑，有掉在坑里的，其余的人都往山上逃跑。","notes":[]},{"n":11,"t":"四王就把所多玛和蛾摩拉所有的财物，并一切的粮食都掳掠去了；","notes":[]},{"n":12,"t":"又把亚伯兰的侄儿罗得和罗得的财物掳掠去了。当时罗得正住在所多玛。","notes":[]},{"n":13,"t":"有一个逃出来的人告诉希伯来人亚伯兰；亚伯兰正住在亚摩利人幔利的橡树那里。幔利和以实各并亚乃都是弟兄，曾与亚伯兰联盟。","notes":[]},{"n":14,"t":"亚伯兰听见他侄儿被掳去，就率领他家里生养的精练壮丁三百一十八人，直追到但，","notes":["原文是弟兄"]},{"n":15,"t":"便在夜间，自己同仆人分队杀败敌人，又追到大马士革左边的何把，","notes":[]},{"n":16,"t":"将被掳掠的一切财物夺回来，连他侄儿罗得和他的财物，以及妇女、人民也都夺回来。","notes":[]},{"n":17,"t":"亚伯兰杀败基大老玛和与他同盟的王回来的时候，所多玛王出来，在沙微谷迎接他；沙微谷就是王谷。","notes":[],"heads":["麦基洗德祝福亚伯兰"]},{"n":18,"t":"又有撒冷王麦基洗德带着饼和酒出来迎接；他是至高神的祭司。","notes":[]},{"n":19,"t":"他为亚伯兰祝福，说：「愿天地的主、至高的神赐福与亚伯兰！","notes":[]},{"n":20,"t":"至高的神把敌人交在你手里，是应当称颂的！」亚伯兰就把所得的拿出十分之一来，给麦基洗德。","notes":[]},{"n":21,"t":"所多玛王对亚伯兰说：「你把人口给我，财物你自己拿去吧！」","notes":[]},{"n":22,"t":"亚伯兰对所多玛王说：「我已经向天地的主—至高的神耶和华起誓：","notes":[]},{"n":23,"t":"凡是你的东西，就是一根线、一根鞋带，我都不拿，免得你说：『我使亚伯兰富足！』","notes":[]},{"n":24,"t":"只有仆人所吃的，并与我同行的亚乃、以实各、幔利所应得的分，可以任凭他们拿去。」","notes":[]}]},"15":{"heading":"神与亚伯兰立约","verses":[{"n":1,"t":"这事以后，耶和华在异象中有话对亚伯兰说：「亚伯兰，你不要惧怕！我是你的盾牌，必大大地赏赐你。」","notes":[]},{"n":2,"t":"亚伯兰说：「主耶和华啊，我既无子，你还赐我什么呢？并且要承受我家业的是大马士革人以利以谢。」","notes":[]},{"n":3,"t":"亚伯兰又说：「你没有给我儿子；那生在我家中的人就是我的后嗣。」","notes":[]},{"n":4,"t":"耶和华又有话对他说：「这人必不成为你的后嗣；你本身所生的才成为你的后嗣。」","notes":[]},{"n":5,"t":"于是领他走到外边，说：「你向天观看，数算众星，能数得过来吗？」又对他说：「你的后裔将要如此。」","notes":[]},{"n":6,"t":"亚伯兰信耶和华，耶和华就以此为他的义。","notes":[]},{"n":7,"t":"耶和华又对他说：「我是耶和华，曾领你出了迦勒底的吾珥，为要将这地赐你为业。」","notes":[]},{"n":8,"t":"亚伯兰说：「主耶和华啊，我怎能知道必得这地为业呢？」","notes":[]},{"n":9,"t":"他说：「你为我取一只三年的母牛，一只三年的母山羊，一只三年的公绵羊，一只斑鸠，一只雏鸽。」","notes":[]},{"n":10,"t":"亚伯兰就取了这些来，每样劈开，分成两半，一半对着一半地摆列，只有鸟没有劈开。","notes":[]},{"n":11,"t":"有鸷鸟下来，落在那死畜的肉上，亚伯兰就把它吓飞了。","notes":[]},{"n":12,"t":"日头正落的时候，亚伯兰沉沉地睡了；忽然有惊人的大黑暗落在他身上。","notes":[]},{"n":13,"t":"耶和华对亚伯兰说：「你要的确知道，你的后裔必寄居别人的地，又服事那地的人；那地的人要苦待他们四百年。","notes":[]},{"n":14,"t":"并且他们所要服事的那国，我要惩罚，后来他们必带着许多财物从那里出来。","notes":[]},{"n":15,"t":"但你要享大寿数，平平安安地归到你列祖那里，被人埋葬。","notes":[]},{"n":16,"t":"到了第四代，他们必回到此地，因为亚摩利人的罪孽还没有满盈。」","notes":[]},{"n":17,"t":"日落天黑，不料有冒烟的炉并烧着的火把从那些肉块中经过。","notes":[]},{"n":18,"t":"当那日，耶和华与亚伯兰立约，说：「我已赐给你的后裔，从埃及河直到幼发拉底大河之地，","notes":[]},{"n":19,"t":"就是基尼人、基尼洗人、甲摩尼人、","notes":[]},{"n":20,"t":"赫人、比利洗人、利乏音人、","notes":[]},{"n":21,"t":"亚摩利人、迦南人、革迦撒人、耶布斯人之地。」","notes":[]}]},"16":{"heading":"夏甲和以实玛利","verses":[{"n":1,"t":"亚伯兰的妻子撒莱不给他生儿女。撒莱有一个使女，名叫夏甲，是埃及人。","notes":[]},{"n":2,"t":"撒莱对亚伯兰说：「耶和华使我不能生育。求你和我的使女同房，或者我可以因她得孩子。」亚伯兰听从了撒莱的话。","notes":["得孩子：原文是被建立"]},{"n":3,"t":"于是亚伯兰的妻子撒莱将使女埃及人夏甲给了丈夫为妾；那时亚伯兰在迦南已经住了十年。","notes":[]},{"n":4,"t":"亚伯兰与夏甲同房，夏甲就怀了孕；她见自己有孕，就小看她的主母。","notes":[]},{"n":5,"t":"撒莱对亚伯兰说：「我因你受屈。我将我的使女放在你怀中，她见自己有了孕，就小看我。愿耶和华在你我中间判断。」","notes":[]},{"n":6,"t":"亚伯兰对撒莱说：「使女在你手下，你可以随意待她。」撒莱苦待她，她就从撒莱面前逃走了。","notes":[]},{"n":7,"t":"耶和华的使者在旷野书珥路上的水泉旁遇见她，","notes":[]},{"n":8,"t":"对她说：「撒莱的使女夏甲，你从哪里来？要往哪里去？」夏甲说：「我从我的主母撒莱面前逃出来。」","notes":[]},{"n":9,"t":"耶和华的使者对她说：「你回到你主母那里，服在她手下」；","notes":[]},{"n":10,"t":"又说：「我必使你的后裔极其繁多，甚至不可胜数」；","notes":[]},{"n":11,"t":"并说：「你如今怀孕要生一个儿子，可以给他起名叫以实玛利，因为耶和华听见了你的苦情。","notes":["就是神听见的意思"]},{"n":12,"t":"他为人必像野驴。他的手要攻打人，人的手也要攻打他；他必住在众弟兄的东边。」","notes":[]},{"n":13,"t":"夏甲就称那对她说话的耶和华为「看顾人的神」。因而说：「在这里我也看见那看顾我的吗？」","notes":[]},{"n":14,"t":"所以这井名叫庇耳·拉海·莱。这井正在加低斯和巴列中间。","notes":[]},{"n":15,"t":"后来夏甲给亚伯兰生了一个儿子；亚伯兰给他起名叫以实玛利。","notes":[]},{"n":16,"t":"夏甲给亚伯兰生以实玛利的时候，亚伯兰年八十六岁。","notes":[]}]},"17":{"heading":"割礼—立约的记号","verses":[{"n":1,"t":"亚伯兰年九十九岁的时候，耶和华向他显现，对他说：「我是全能的神。你当在我面前作完全人，","notes":[]},{"n":2,"t":"我就与你立约，使你的后裔极其繁多。」","notes":[]},{"n":3,"t":"亚伯兰俯伏在地；神又对他说：","notes":[]},{"n":4,"t":"「我与你立约：你要作多国的父。","notes":[]},{"n":5,"t":"从此以后，你的名不再叫亚伯兰，要叫亚伯拉罕，因为我已立你作多国的父。","notes":[]},{"n":6,"t":"我必使你的后裔极其繁多；国度从你而立，君王从你而出。","notes":[]},{"n":7,"t":"我要与你并你世世代代的后裔坚立我的约，作永远的约，是要作你和你后裔的神。","notes":[]},{"n":8,"t":"我要将你现在寄居的地，就是迦南全地，赐给你和你的后裔永远为业，我也必作他们的神。」","notes":[]},{"n":9,"t":"神又对亚伯拉罕说：「你和你的后裔必世世代代遵守我的约。","notes":[]},{"n":10,"t":"你们所有的男子都要受割礼；这就是我与你并你的后裔所立的约，是你们所当遵守的。","notes":[]},{"n":11,"t":"你们都要受割礼；这是我与你们立约的证据。","notes":["原文是割阳皮；十四、二十三、二十四、二十五节同"]},{"n":12,"t":"你们世世代代的男子，无论是家里生的，是在你后裔之外用银子从外人买的，生下来第八日，都要受割礼。","notes":[]},{"n":13,"t":"你家里生的和你用银子买的，都必须受割礼。这样，我的约就立在你们肉体上作永远的约。","notes":[]},{"n":14,"t":"但不受割礼的男子必从民中剪除，因他背了我的约。」","notes":[]},{"n":15,"t":"神又对亚伯拉罕说：「你的妻子撒莱不可再叫撒莱，她的名要叫撒拉。","notes":[]},{"n":16,"t":"我必赐福给她，也要使你从她得一个儿子。我要赐福给她，她也要作多国之母；必有百姓的君王从她而出。」","notes":[]},{"n":17,"t":"亚伯拉罕就俯伏在地喜笑，心里说：「一百岁的人还能得孩子吗？撒拉已经九十岁了，还能生养吗？」","notes":[]},{"n":18,"t":"亚伯拉罕对神说：「但愿以实玛利活在你面前。」","notes":[]},{"n":19,"t":"神说：「不然，你妻子撒拉要给你生一个儿子，你要给他起名叫以撒。我要与他坚定所立的约，作他后裔永远的约。","notes":[]},{"n":20,"t":"至于以实玛利，我也应允你：我必赐福给他，使他昌盛，极其繁多。他必生十二个族长；我也要使他成为大国。","notes":[]},{"n":21,"t":"到明年这时节，撒拉必给你生以撒，我要与他坚定所立的约。」","notes":[]},{"n":22,"t":"神和亚伯拉罕说完了话，就离开他上升去了。","notes":[]},{"n":23,"t":"正当那日，亚伯拉罕遵着神的命，给他的儿子以实玛利和家里的一切男子，无论是在家里生的，是用银子买的，都行了割礼。","notes":[]},{"n":24,"t":"亚伯拉罕受割礼的时候年九十九岁。","notes":[]},{"n":25,"t":"他儿子以实玛利受割礼的时候年十三岁。","notes":[]},{"n":26,"t":"正当那日，亚伯拉罕和他儿子以实玛利一同受了割礼。","notes":[]},{"n":27,"t":"家里所有的人，无论是在家里生的，是用银子从外人买的，也都一同受了割礼。","notes":[]}]},"18":{"heading":"神应许亚伯拉罕得儿子","verses":[{"n":1,"t":"耶和华在幔利橡树那里向亚伯拉罕显现出来。那时正热，亚伯拉罕坐在帐棚门口，","notes":[]},{"n":2,"t":"举目观看，见有三个人在对面站着。他一见，就从帐棚门口跑去迎接他们，俯伏在地，","notes":[]},{"n":3,"t":"说：「我主，我若在你眼前蒙恩，求你不要离开仆人往前去。","notes":[]},{"n":4,"t":"容我拿点水来，你们洗洗脚，在树下歇息歇息。","notes":[]},{"n":5,"t":"我再拿一点饼来，你们可以加添心力，然后往前去。你们既到仆人这里来，理当如此。」他们说：「就照你说的行吧。」","notes":[]},{"n":6,"t":"亚伯拉罕急忙进帐棚见撒拉，说：「你速速拿三细亚细面调和做饼。」","notes":[]},{"n":7,"t":"亚伯拉罕又跑到牛群里，牵了一只又嫩又好的牛犊来，交给仆人，仆人急忙预备好了。","notes":[]},{"n":8,"t":"亚伯拉罕又取了奶油和奶，并预备好的牛犊来，摆在他们面前，自己在树下站在旁边，他们就吃了。","notes":[]},{"n":9,"t":"他们问亚伯拉罕说：「你妻子撒拉在哪里？」他说：「在帐棚里。」","notes":[]},{"n":10,"t":"三人中有一位说：「到明年这时候，我必要回到你这里；你的妻子撒拉必生一个儿子。」撒拉在那人后边的帐棚门口也听见了这话。","notes":[]},{"n":11,"t":"亚伯拉罕和撒拉年纪老迈，撒拉的月经已断绝了。","notes":[]},{"n":12,"t":"撒拉心里暗笑，说：「我既已衰败，我主也老迈，岂能有这喜事呢？」","notes":[]},{"n":13,"t":"耶和华对亚伯拉罕说：「撒拉为什么暗笑，说：『我既已年老，果真能生养吗？』","notes":[]},{"n":14,"t":"耶和华岂有难成的事吗？到了日期，明年这时候，我必回到你这里，撒拉必生一个儿子。」","notes":[]},{"n":15,"t":"撒拉就害怕，不承认，说：「我没有笑。」那位说：「不然，你实在笑了。」","notes":[]},{"n":16,"t":"三人就从那里起行，向所多玛观看，亚伯拉罕也与他们同行，要送他们一程。","notes":[],"heads":["亚伯拉罕为所多玛祈求"]},{"n":17,"t":"耶和华说：「我所要做的事岂可瞒着亚伯拉罕呢？","notes":[]},{"n":18,"t":"亚伯拉罕必要成为强大的国；地上的万国都必因他得福。","notes":[]},{"n":19,"t":"我眷顾他，为要叫他吩咐他的众子和他的眷属遵守我的道，秉公行义，使我所应许亚伯拉罕的话都成就了。」","notes":[]},{"n":20,"t":"耶和华说：「所多玛和蛾摩拉的罪恶甚重，声闻于我。","notes":[]},{"n":21,"t":"我现在要下去，察看他们所行的，果然尽像那达到我耳中的声音一样吗？若是不然，我也必知道。」","notes":[]},{"n":22,"t":"二人转身离开那里，向所多玛去；但亚伯拉罕仍旧站在耶和华面前。","notes":[]},{"n":23,"t":"亚伯拉罕近前来，说：「无论善恶，你都要剿灭吗？","notes":[]},{"n":24,"t":"假若那城里有五十个义人，你还剿灭那地方吗？不为城里这五十个义人饶恕其中的人吗？","notes":[]},{"n":25,"t":"将义人与恶人同杀，将义人与恶人一样看待，这断不是你所行的。审判全地的主岂不行公义吗？」","notes":[]},{"n":26,"t":"耶和华说：「我若在所多玛城里见有五十个义人，我就为他们的缘故饶恕那地方的众人。」","notes":[]},{"n":27,"t":"亚伯拉罕说：「我虽然是灰尘，还敢对主说话。","notes":[]},{"n":28,"t":"假若这五十个义人短了五个，你就因为短了五个毁灭全城吗？」他说：「我在那里若见有四十五个，也不毁灭那城。」","notes":[]},{"n":29,"t":"亚伯拉罕又对他说：「假若在那里见有四十个怎么样呢？」他说：「为这四十个的缘故，我也不做这事。」","notes":[]},{"n":30,"t":"亚伯拉罕说：「求主不要动怒，容我说，假若在那里见有三十个怎么样呢？」他说：「我在那里若见有三十个，我也不做这事。」","notes":[]},{"n":31,"t":"亚伯拉罕说：「我还敢对主说话，假若在那里见有二十个怎么样呢？」他说：「为这二十个的缘故，我也不毁灭那城。」","notes":[]},{"n":32,"t":"亚伯拉罕说：「求主不要动怒，我再说这一次，假若在那里见有十个呢？」他说：「为这十个的缘故，我也不毁灭那城。」","notes":[]},{"n":33,"t":"耶和华与亚伯拉罕说完了话就走了；亚伯拉罕也回到自己的地方去了。","notes":[]}]},"19":{"heading":"所多玛的罪恶","verses":[{"n":1,"t":"那两个天使晚上到了所多玛；罗得正坐在所多玛城门口，看见他们，就起来迎接，脸伏于地下拜，","notes":[]},{"n":2,"t":"说：「我主啊，请你们到仆人家里洗洗脚，住一夜，清早起来再走。」他们说：「不！我们要在街上过夜。」","notes":[]},{"n":3,"t":"罗得切切地请他们，他们这才进去，到他屋里。罗得为他们预备筵席，烤无酵饼，他们就吃了。","notes":[]},{"n":4,"t":"他们还没有躺下，所多玛城里各处的人，连老带少，都来围住那房子，","notes":[]},{"n":5,"t":"呼叫罗得说：「今日晚上到你这里来的人在哪里呢？把他们带出来，任我们所为。」","notes":[]},{"n":6,"t":"罗得出来，把门关上，到众人那里，","notes":[]},{"n":7,"t":"说：「众弟兄，请你们不要做这恶事。","notes":[]},{"n":8,"t":"我有两个女儿，还是处女，容我领出来，任凭你们的心愿而行；只是这两个人既然到我舍下，不要向他们做什么。」","notes":[]},{"n":9,"t":"众人说：「退去吧！」又说：「这个人来寄居，还想要作官哪！现在我们要害你比害他们更甚。」众人就向前拥挤罗得，要攻破房门。","notes":[]},{"n":10,"t":"只是那二人伸出手来，将罗得拉进屋去，把门关上，","notes":[]},{"n":11,"t":"并且使门外的人，无论老少，眼都昏迷；他们摸来摸去，总寻不着房门。","notes":[]},{"n":12,"t":"二人对罗得说：「你这里还有什么人吗？无论是女婿是儿女，和这城中一切属你的人，你都要将他们从这地方带出去。","notes":[],"heads":["罗得离开所多玛"]},{"n":13,"t":"我们要毁灭这地方；因为城内罪恶的声音在耶和华面前甚大，耶和华差我们来，要毁灭这地方。」","notes":[]},{"n":14,"t":"罗得就出去，告诉娶了他女儿的女婿们说：「你们起来离开这地方，因为耶和华要毁灭这城。」他女婿们却以为他说的是戏言。","notes":["或译：将要娶"]},{"n":15,"t":"天明了，天使催逼罗得说：「起来！带着你的妻子和你在这里的两个女儿出去，免得你因这城里的罪恶同被剿灭。」","notes":[]},{"n":16,"t":"但罗得迟延不走。二人因为耶和华怜恤罗得，就拉着他的手和他妻子的手，并他两个女儿的手，把他们领出来，安置在城外；","notes":[]},{"n":17,"t":"领他们出来以后，就说：「逃命吧！不可回头看，也不可在平原站住。要往山上逃跑，免得你被剿灭。」","notes":[]},{"n":18,"t":"罗得对他们说：「我主啊，不要如此！","notes":[]},{"n":19,"t":"你仆人已经在你眼前蒙恩；你又向我显出莫大的慈爱，救我的性命。我不能逃到山上去，恐怕这灾祸临到我，我便死了。","notes":[]},{"n":20,"t":"看哪，这座城又小又近，容易逃到，这不是一个小的吗？求你容我逃到那里，我的性命就得存活。」","notes":[]},{"n":21,"t":"天使对他说：「这事我也应允你；我不倾覆你所说的这城。","notes":[]},{"n":22,"t":"你要速速地逃到那城；因为你还没有到那里，我不能做什么。」因此那城名叫琐珥。","notes":["就是小的意思"]},{"n":23,"t":"罗得到了琐珥，日头已经出来了。","notes":[],"heads":["所多玛蛾摩拉的毁灭"]},{"n":24,"t":"当时，耶和华将硫磺与火从天上耶和华那里降与所多玛和蛾摩拉，","notes":[]},{"n":25,"t":"把那些城和全平原，并城里所有的居民，连地上生长的，都毁灭了。","notes":[]},{"n":26,"t":"罗得的妻子在后边回头一看，就变成了一根盐柱。","notes":[]},{"n":27,"t":"亚伯拉罕清早起来，到了他从前站在耶和华面前的地方，","notes":[]},{"n":28,"t":"向所多玛和蛾摩拉与平原的全地观看，不料，那地方烟气上腾，如同烧窑一般。","notes":[]},{"n":29,"t":"当神毁灭平原诸城的时候，他记念亚伯拉罕，正在倾覆罗得所住之城的时候，就打发罗得从倾覆之中出来。","notes":[]},{"n":30,"t":"罗得因为怕住在琐珥，就同他两个女儿从琐珥上去，住在山里；他和两个女儿住在一个洞里。","notes":[],"heads":["摩押人和亚扪人的起源"]},{"n":31,"t":"大女儿对小女儿说：「我们的父亲老了，地上又无人按着世上的常规进到我们这里。","notes":[]},{"n":32,"t":"来！我们可以叫父亲喝酒，与他同寝。这样，我们好从他存留后裔。」","notes":[]},{"n":33,"t":"于是，那夜她们叫父亲喝酒，大女儿就进去和她父亲同寝；她几时躺下，几时起来，父亲都不知道。","notes":[]},{"n":34,"t":"第二天，大女儿对小女儿说：「我昨夜与父亲同寝。今夜我们再叫他喝酒，你可以进去与他同寝。这样，我们好从父亲存留后裔。」","notes":[]},{"n":35,"t":"于是，那夜她们又叫父亲喝酒，小女儿起来与她父亲同寝；她几时躺下，几时起来，父亲都不知道。","notes":[]},{"n":36,"t":"这样，罗得的两个女儿都从她父亲怀了孕。","notes":[]},{"n":37,"t":"大女儿生了儿子，给他起名叫摩押，就是现今摩押人的始祖。","notes":[]},{"n":38,"t":"小女儿也生了儿子，给他起名叫便·亚米，就是现今亚扪人的始祖。","notes":[]}]},"20":{"heading":"亚伯拉罕和亚比米勒","verses":[{"n":1,"t":"亚伯拉罕从那里向南地迁去，寄居在加低斯和书珥中间的基拉耳。","notes":[]},{"n":2,"t":"亚伯拉罕称他的妻撒拉为妹子，基拉耳王亚比米勒差人把撒拉取了去。","notes":[]},{"n":3,"t":"但夜间，神来，在梦中对亚比米勒说：「你是个死人哪！因为你取了那女人来；她原是别人的妻子。」","notes":[]},{"n":4,"t":"亚比米勒却还没有亲近撒拉；他说：「主啊，连有义的国，你也要毁灭吗？","notes":[]},{"n":5,"t":"那人岂不是自己对我说『她是我的妹子』吗？就是女人也自己说：『他是我的哥哥。』我做这事是心正手洁的。」","notes":[]},{"n":6,"t":"神在梦中对他说：「我知道你做这事是心中正直；我也拦阻了你，免得你得罪我，所以我不容你沾着她。","notes":[]},{"n":7,"t":"现在你把这人的妻子归还他；因为他是先知，他要为你祷告，使你存活。你若不归还他，你当知道，你和你所有的人都必要死。」","notes":[]},{"n":8,"t":"亚比米勒清早起来，召了众臣仆来，将这些事都说给他们听，他们都甚惧怕。","notes":[]},{"n":9,"t":"亚比米勒召了亚伯拉罕来，对他说：「你怎么向我这样行呢？我在什么事上得罪了你，你竟使我和我国里的人陷在大罪里？你向我行不当行的事了！」","notes":[]},{"n":10,"t":"亚比米勒又对亚伯拉罕说：「你见了什么才做这事呢？」","notes":[]},{"n":11,"t":"亚伯拉罕说：「我以为这地方的人总不惧怕神，必为我妻子的缘故杀我。","notes":[]},{"n":12,"t":"况且她也实在是我的妹子；她与我是同父异母，后来作了我的妻子。","notes":[]},{"n":13,"t":"当神叫我离开父家、飘流在外的时候，我对她说：『我们无论走到什么地方，你可以对人说：他是我的哥哥；这就是你待我的恩典了。』」","notes":[]},{"n":14,"t":"亚比米勒把牛、羊、仆婢赐给亚伯拉罕，又把他的妻子撒拉归还他。","notes":[]},{"n":15,"t":"亚比米勒又说：「看哪，我的地都在你面前，你可以随意居住」；","notes":[]},{"n":16,"t":"又对撒拉说：「我给你哥哥一千银子，作为你在合家人面前遮羞的，你就在众人面前没有不是了。」","notes":["羞：原文是眼"]},{"n":17,"t":"亚伯拉罕祷告神，神就医好了亚比米勒和他的妻子，并他的众女仆，她们便能生育。","notes":[]},{"n":18,"t":"因耶和华为亚伯拉罕的妻子撒拉的缘故，已经使亚比米勒家中的妇人不能生育。","notes":[]}]},"21":{"heading":"以撒出生","verses":[{"n":1,"t":"耶和华按着先前的话眷顾撒拉，便照他所说的给撒拉成就。","notes":[]},{"n":2,"t":"当亚伯拉罕年老的时候，撒拉怀了孕；到神所说的日期，就给亚伯拉罕生了一个儿子。","notes":[]},{"n":3,"t":"亚伯拉罕给撒拉所生的儿子起名叫以撒。","notes":[]},{"n":4,"t":"以撒生下来第八日，亚伯拉罕照着神所吩咐的，给以撒行了割礼。","notes":[]},{"n":5,"t":"他儿子以撒生的时候，亚伯拉罕年一百岁。","notes":[]},{"n":6,"t":"撒拉说：「神使我喜笑，凡听见的必与我一同喜笑」；","notes":[]},{"n":7,"t":"又说：「谁能预先对亚伯拉罕说『撒拉要乳养婴孩』呢？因为在他年老的时候，我给他生了一个儿子。」","notes":[]},{"n":8,"t":"孩子渐长，就断了奶。以撒断奶的日子，亚伯拉罕设摆丰盛的筵席。","notes":[]},{"n":9,"t":"当时，撒拉看见埃及人夏甲给亚伯拉罕所生的儿子戏笑，","notes":[],"heads":["夏甲和以实玛利被逐"]},{"n":10,"t":"就对亚伯拉罕说：「你把这使女和她儿子赶出去！因为这使女的儿子不可与我的儿子以撒一同承受产业。」","notes":[]},{"n":11,"t":"亚伯拉罕因他儿子的缘故很忧愁。","notes":[]},{"n":12,"t":"神对亚伯拉罕说：「你不必为这童子和你的使女忧愁。凡撒拉对你说的话，你都该听从；因为从以撒生的，才要称为你的后裔。","notes":[]},{"n":13,"t":"至于使女的儿子，我也必使他的后裔成立一国，因为他是你所生的。」","notes":[]},{"n":14,"t":"亚伯拉罕清早起来，拿饼和一皮袋水，给了夏甲，搭在她的肩上，又把孩子交给她，打发她走。夏甲就走了，在别是巴的旷野走迷了路。","notes":[]},{"n":15,"t":"皮袋的水用尽了，夏甲就把孩子撇在小树底下，","notes":[]},{"n":16,"t":"自己走开约有一箭之远，相对而坐，说：「我不忍见孩子死」，就相对而坐，放声大哭。","notes":[]},{"n":17,"t":"神听见童子的声音；神的使者从天上呼叫夏甲说：「夏甲，你为何这样呢？不要害怕，神已经听见童子的声音了。","notes":[]},{"n":18,"t":"起来！把童子抱在怀中，我必使他的后裔成为大国。」","notes":["怀：原文是手"]},{"n":19,"t":"神使夏甲的眼睛明亮，她就看见一口水井，便去将皮袋盛满了水，给童子喝。","notes":[]},{"n":20,"t":"神保佑童子，他就渐长，住在旷野，成了弓箭手。","notes":[]},{"n":21,"t":"他住在巴兰的旷野；他母亲从埃及地给他娶了一个妻子。","notes":[]},{"n":22,"t":"当那时候，亚比米勒同他军长非各对亚伯拉罕说：「凡你所行的事都有神的保佑。","notes":[],"heads":["亚伯拉罕跟亚比米勒立约"]},{"n":23,"t":"我愿你如今在这里指着神对我起誓，不要欺负我与我的儿子，并我的子孙。我怎样厚待了你，你也要照样厚待我与你所寄居这地的民。」","notes":[]},{"n":24,"t":"亚伯拉罕说：「我情愿起誓。」","notes":[]},{"n":25,"t":"从前，亚比米勒的仆人霸占了一口水井，亚伯拉罕为这事指责亚比米勒。","notes":[]},{"n":26,"t":"亚比米勒说：「谁做这事，我不知道，你也没有告诉我，今日我才听见了。」","notes":[]},{"n":27,"t":"亚伯拉罕把羊和牛给了亚比米勒，二人就彼此立约。","notes":[]},{"n":28,"t":"亚伯拉罕把七只母羊羔另放在一处。","notes":[]},{"n":29,"t":"亚比米勒问亚伯拉罕说：「你把这七只母羊羔另放在一处，是什么意思呢？」","notes":[]},{"n":30,"t":"他说：「你要从我手里受这七只母羊羔，作我挖这口井的证据。」","notes":[]},{"n":31,"t":"所以他给那地方起名叫别是巴，因为他们二人在那里起了誓。","notes":["就是盟誓的井的意思"]},{"n":32,"t":"他们在别是巴立了约，亚比米勒就同他军长非各起身回非利士地去了。","notes":[]},{"n":33,"t":"亚伯拉罕在别是巴栽上一棵垂丝柳树，又在那里求告耶和华—永生神的名。","notes":[]},{"n":34,"t":"亚伯拉罕在非利士人的地寄居了多日。","notes":[]}]},"22":{"heading":"神吩咐亚伯拉罕献以撒","verses":[{"n":1,"t":"这些事以后，神要试验亚伯拉罕，就呼叫他说：「亚伯拉罕！」他说：「我在这里。」","notes":[]},{"n":2,"t":"神说：「你带着你的儿子，就是你独生的儿子，你所爱的以撒，往摩利亚地去，在我所要指示你的山上，把他献为燔祭。」","notes":[]},{"n":3,"t":"亚伯拉罕清早起来，备上驴，带着两个仆人和他儿子以撒，也劈好了燔祭的柴，就起身往神所指示他的地方去了。","notes":[]},{"n":4,"t":"到了第三日，亚伯拉罕举目远远地看见那地方。","notes":[]},{"n":5,"t":"亚伯拉罕对他的仆人说：「你们和驴在此等候，我与童子往那里去拜一拜，就回到你们这里来。」","notes":[]},{"n":6,"t":"亚伯拉罕把燔祭的柴放在他儿子以撒身上，自己手里拿着火与刀；于是二人同行。","notes":[]},{"n":7,"t":"以撒对他父亲亚伯拉罕说：「父亲哪！」亚伯拉罕说：「我儿，我在这里。」以撒说：「请看，火与柴都有了，但燔祭的羊羔在哪里呢？」","notes":[]},{"n":8,"t":"亚伯拉罕说：「我儿，神必自己预备作燔祭的羊羔。」于是二人同行。","notes":[]},{"n":9,"t":"他们到了神所指示的地方，亚伯拉罕在那里筑坛，把柴摆好，捆绑他的儿子以撒，放在坛的柴上。","notes":[]},{"n":10,"t":"亚伯拉罕就伸手拿刀，要杀他的儿子。","notes":[]},{"n":11,"t":"耶和华的使者从天上呼叫他说：「亚伯拉罕！亚伯拉罕！」他说：「我在这里。」","notes":[]},{"n":12,"t":"天使说：「你不可在这童子身上下手。一点不可害他！现在我知道你是敬畏神的了；因为你没有将你的儿子，就是你独生的儿子，留下不给我。」","notes":[]},{"n":13,"t":"亚伯拉罕举目观看，不料，有一只公羊，两角扣在稠密的小树中，亚伯拉罕就取了那只公羊来，献为燔祭，代替他的儿子。","notes":[]},{"n":14,"t":"亚伯拉罕给那地方起名叫「耶和华以勒」，直到今日人还说：「在耶和华的山上必有预备。」","notes":["就是耶和华必预备的意思"]},{"n":15,"t":"耶和华的使者第二次从天上呼叫亚伯拉罕说：","notes":[]},{"n":16,"t":"「耶和华说：『你既行了这事，不留下你的儿子，就是你独生的儿子，我便指着自己起誓说：","notes":[]},{"n":17,"t":"论福，我必赐大福给你；论子孙，我必叫你的子孙多起来，如同天上的星，海边的沙。你子孙必得着仇敌的城门，","notes":[]},{"n":18,"t":"并且地上万国都必因你的后裔得福，因为你听从了我的话。』」","notes":[]},{"n":19,"t":"于是亚伯拉罕回到他仆人那里，他们一同起身往别是巴去，亚伯拉罕就住在别是巴。","notes":[]},{"n":20,"t":"这事以后，有人告诉亚伯拉罕说：「密迦给你兄弟拿鹤生了几个儿子，","notes":[],"heads":["拿鹤的后代"]},{"n":21,"t":"长子是乌斯，他的兄弟是布斯和亚兰的父亲基母利，","notes":[]},{"n":22,"t":"并基薛、哈琐、必达、益拉、彼土利（彼土利生利百加）。」","notes":[]},{"n":23,"t":"这八个人都是密迦给亚伯拉罕的兄弟拿鹤生的。","notes":[]},{"n":24,"t":"拿鹤的妾名叫流玛，生了提八、迦含、他辖，和玛迦。","notes":[]}]},"23":{"heading":"亚伯拉罕买坟地埋葬撒拉","verses":[{"n":1,"t":"撒拉享寿一百二十七岁，这是撒拉一生的岁数。","notes":[]},{"n":2,"t":"撒拉死在迦南地的基列·亚巴，就是希伯仑。亚伯拉罕为她哀恸哭号。","notes":[]},{"n":3,"t":"后来亚伯拉罕从死人面前起来，对赫人说：","notes":[]},{"n":4,"t":"「我在你们中间是外人，是寄居的。求你们在这里给我一块地，我好埋葬我的死人，使她不在我眼前。」","notes":[]},{"n":5,"t":"赫人回答亚伯拉罕说：","notes":[]},{"n":6,"t":"「我主请听。你在我们中间是一位尊大的王子，只管在我们最好的坟地里埋葬你的死人；我们没有一人不容你在他的坟地里埋葬你的死人。」","notes":[]},{"n":7,"t":"亚伯拉罕就起来，向那地的赫人下拜，","notes":[]},{"n":8,"t":"对他们说：「你们若有意叫我埋葬我的死人，使她不在我眼前，就请听我的话，为我求琐辖的儿子以弗仑；","notes":[]},{"n":9,"t":"把田头上那麦比拉洞给我；他可以按着足价卖给我，作我在你们中间的坟地。」","notes":[]},{"n":10,"t":"当时以弗仑正坐在赫人中间。于是，赫人以弗仑在城门出入的赫人面前对亚伯拉罕说：","notes":[]},{"n":11,"t":"「不然，我主请听。我送给你这块田，连田间的洞也送给你，在我同族的人面前都给你，可以埋葬你的死人。」","notes":[]},{"n":12,"t":"亚伯拉罕就在那地的人民面前下拜，","notes":[]},{"n":13,"t":"在他们面前对以弗仑说：「你若应允，请听我的话。我要把田价给你，求你收下，我就在那里埋葬我的死人。」","notes":[]},{"n":14,"t":"以弗仑回答亚伯拉罕说：","notes":[]},{"n":15,"t":"「我主请听。值四百舍客勒银子的一块田，在你我中间还算什么呢？只管埋葬你的死人吧！」","notes":[]},{"n":16,"t":"亚伯拉罕听从了以弗仑，照着他在赫人面前所说的话，把买卖通用的银子平了四百舍客勒给以弗仑。","notes":[]},{"n":17,"t":"于是，麦比拉、幔利前、以弗仑的那块田和其中的洞，并田间四围的树木，","notes":[]},{"n":18,"t":"都定准归与亚伯拉罕，乃是他在赫人面前并城门出入的人面前买妥的。","notes":[]},{"n":19,"t":"此后，亚伯拉罕把他妻子撒拉埋葬在迦南地幔利前的麦比拉田间的洞里。（幔利就是希伯仑）。","notes":[]},{"n":20,"t":"从此，那块田和田间的洞就借着赫人定准归与亚伯拉罕作坟地。","notes":[]}]},"24":{"heading":"以撒娶妻","verses":[{"n":1,"t":"亚伯拉罕年纪老迈，向来在一切事上耶和华都赐福给他。","notes":[]},{"n":2,"t":"亚伯拉罕对管理他全业最老的仆人说：「请你把手放在我大腿底下。","notes":[]},{"n":3,"t":"我要叫你指着耶和华—天地的主起誓，不要为我儿子娶这迦南地中的女子为妻。","notes":[]},{"n":4,"t":"你要往我本地本族去，为我的儿子以撒娶一个妻子。」","notes":[]},{"n":5,"t":"仆人对他说：「倘若女子不肯跟我到这地方来，我必须将你的儿子带回你原出之地吗？」","notes":[]},{"n":6,"t":"亚伯拉罕对他说：「你要谨慎，不要带我的儿子回那里去。","notes":[]},{"n":7,"t":"耶和华—天上的主曾带领我离开父家和本族的地，对我说话，向我起誓说：『我要将这地赐给你的后裔。』他必差遣使者在你面前，你就可以从那里为我儿子娶一个妻子。","notes":[]},{"n":8,"t":"倘若女子不肯跟你来，我使你起的誓就与你无干了，只是不可带我的儿子回那里去。」","notes":[]},{"n":9,"t":"仆人就把手放在他主人亚伯拉罕的大腿底下，为这事向他起誓。","notes":[]},{"n":10,"t":"那仆人从他主人的骆驼里取了十匹骆驼，并带些他主人各样的财物，起身往美索不达米亚去，到了拿鹤的城。","notes":[]},{"n":11,"t":"天将晚，众女子出来打水的时候，他便叫骆驼跪在城外的水井那里。","notes":[]},{"n":12,"t":"他说：「耶和华—我主人亚伯拉罕的神啊，求你施恩给我主人亚伯拉罕，使我今日遇见好机会。","notes":[]},{"n":13,"t":"我现今站在井旁，城内居民的女子们正出来打水。","notes":[]},{"n":14,"t":"我向那一个女子说：『请你拿下水瓶来，给我水喝』，她若说：『请喝！我也给你的骆驼喝。』愿那女子就作你所预定给你仆人以撒的妻。这样，我便知道你施恩给我主人了。」","notes":[]},{"n":15,"t":"话还没有说完，不料，利百加肩头上扛着水瓶出来。利百加是彼土利所生的；彼土利是亚伯拉罕兄弟拿鹤妻子密迦的儿子。","notes":[]},{"n":16,"t":"那女子容貌极其俊美，还是处女，也未曾有人亲近她。她下到井旁，打满了瓶，又上来。","notes":[]},{"n":17,"t":"仆人跑上前去迎着她，说：「求你将瓶里的水给我一点喝。」","notes":[]},{"n":18,"t":"女子说：「我主请喝！」就急忙拿下瓶来，托在手上给他喝。","notes":[]},{"n":19,"t":"女子给他喝了，就说：「我再为你的骆驼打水，叫骆驼也喝足。」","notes":[]},{"n":20,"t":"她就急忙把瓶里的水倒在槽里，又跑到井旁打水，就为所有的骆驼打上水来。","notes":[]},{"n":21,"t":"那人定睛看她，一句话也不说，要晓得耶和华赐他通达的道路没有。","notes":[]},{"n":22,"t":"骆驼喝足了，那人就拿一个金环，重半舍客勒，两个金镯，重十舍客勒，给了那女子，","notes":[]},{"n":23,"t":"说：「请告诉我，你是谁的女儿？你父亲家里有我们住宿的地方没有？」","notes":[]},{"n":24,"t":"女子说：「我是密迦与拿鹤之子彼土利的女儿」；","notes":[]},{"n":25,"t":"又说：「我们家里足有粮草，也有住宿的地方。」","notes":[]},{"n":26,"t":"那人就低头向耶和华下拜，","notes":[]},{"n":27,"t":"说：「耶和华—我主人亚伯拉罕的神是应当称颂的，因他不断地以慈爱诚实待我主人。至于我，耶和华在路上引领我，直走到我主人的兄弟家里。」","notes":[]},{"n":28,"t":"女子跑回去，照着这些话告诉她母亲和她家里的人。","notes":[]},{"n":29,"t":"利百加有一个哥哥，名叫拉班，看见金环，又看见金镯在他妹子的手上，并听见他妹子利百加的话，说那人对我如此如此说。拉班就跑出来往井旁去，到那人跟前，见他仍站在骆驼旁边的井旁那里，","notes":[],"end":30},{"n":31,"t":"便对他说：「你这蒙耶和华赐福的，请进来，为什么站在外边？我已经收拾了房屋，也为骆驼预备了地方。」","notes":[]},{"n":32,"t":"那人就进了拉班的家。拉班卸了骆驼，用草料喂上，拿水给那人和跟随的人洗脚；","notes":[]},{"n":33,"t":"把饭摆在他面前，叫他吃，他却说：「我不吃，等我说明白我的事情再吃。」拉班说：「请说。」","notes":[]},{"n":34,"t":"他说：「我是亚伯拉罕的仆人。","notes":[]},{"n":35,"t":"耶和华大大地赐福给我主人，使他昌大，又赐给他羊群、牛群、金银、仆婢、骆驼，和驴。","notes":[]},{"n":36,"t":"我主人的妻子撒拉年老的时候给我主人生了一个儿子；我主人也将一切所有的都给了这个儿子。","notes":[]},{"n":37,"t":"我主人叫我起誓说：『你不要为我儿子娶迦南地的女子为妻。","notes":[]},{"n":38,"t":"你要往我父家、我本族那里去，为我的儿子娶一个妻子。』","notes":[]},{"n":39,"t":"我对我主人说：『恐怕女子不肯跟我来。』","notes":[]},{"n":40,"t":"他就说：『我所事奉的耶和华必要差遣他的使者与你同去，叫你的道路通达，你就得以在我父家、我本族那里，给我的儿子娶一个妻子。","notes":[]},{"n":41,"t":"只要你到了我本族那里，我使你起的誓就与你无干。他们若不把女子交给你，我使你起的誓也与你无干。』","notes":[]},{"n":42,"t":"「我今日到了井旁，便说：『耶和华—我主人亚伯拉罕的神啊，愿你叫我所行的道路通达。","notes":[]},{"n":43,"t":"我如今站在井旁，对哪一个出来打水的女子说：请你把你瓶里的水给我一点喝；","notes":[]},{"n":44,"t":"她若说：你只管喝，我也为你的骆驼打水；愿那女子就作耶和华给我主人儿子所预定的妻。』","notes":[]},{"n":45,"t":"我心里的话还没有说完，利百加就出来，肩头上扛着水瓶，下到井旁打水。我便对她说：『请你给我水喝。』","notes":[]},{"n":46,"t":"她就急忙从肩头上拿下瓶来，说：『请喝！我也给你的骆驼喝。』我便喝了；她又给我的骆驼喝了。","notes":[]},{"n":47,"t":"我问她说：『你是谁的女儿？』她说：『我是密迦与拿鹤之子彼土利的女儿。』我就把环子戴在她鼻子上，把镯子戴在她两手上。","notes":[]},{"n":48,"t":"随后我低头向耶和华下拜，称颂耶和华—我主人亚伯拉罕的神；因为他引导我走合式的道路，使我得着我主人兄弟的孙女，给我主人的儿子为妻。","notes":[]},{"n":49,"t":"现在你们若愿以慈爱诚实待我主人，就告诉我；若不然，也告诉我，使我可以或向左，或向右。」","notes":[]},{"n":50,"t":"拉班和彼土利回答说：「这事乃出于耶和华，我们不能向你说好说歹。","notes":[]},{"n":51,"t":"看哪，利百加在你面前，可以将她带去，照着耶和华所说的，给你主人的儿子为妻。」","notes":[]},{"n":52,"t":"亚伯拉罕的仆人听见他们这话，就向耶和华俯伏在地。","notes":[]},{"n":53,"t":"当下仆人拿出金器、银器，和衣服送给利百加，又将宝物送给她哥哥和她母亲。","notes":[]},{"n":54,"t":"仆人和跟从他的人吃了喝了，住了一夜。早晨起来，仆人就说：「请打发我回我主人那里去吧。」","notes":[]},{"n":55,"t":"利百加的哥哥和她母亲说：「让女子同我们再住几天，至少十天，然后她可以去。」","notes":[]},{"n":56,"t":"仆人说：「耶和华既赐给我通达的道路，你们不要耽误我，请打发我走，回我主人那里去吧。」","notes":[]},{"n":57,"t":"他们说：「我们把女子叫来问问她」，","notes":[]},{"n":58,"t":"就叫了利百加来，问她说：「你和这人同去吗？」利百加说：「我去。」","notes":[]},{"n":59,"t":"于是他们打发妹子利百加和她的乳母，同亚伯拉罕的仆人，并跟从仆人的，都走了。","notes":[]},{"n":60,"t":"他们就给利百加祝福说：我们的妹子啊，愿你作千万人的母！愿你的后裔得着仇敌的城门！","notes":[]},{"n":61,"t":"利百加和她的使女们起来，骑上骆驼，跟着那仆人，仆人就带着利百加走了。","notes":[]},{"n":62,"t":"那时，以撒住在南地，刚从庇耳·拉海·莱回来。","notes":[]},{"n":63,"t":"天将晚，以撒出来在田间默想，举目一看，见来了些骆驼。","notes":[]},{"n":64,"t":"利百加举目看见以撒，就急忙下了骆驼，","notes":[]},{"n":65,"t":"问那仆人说：「这田间走来迎接我们的是谁？」仆人说：「是我的主人。」利百加就拿帕子蒙上脸。","notes":[]},{"n":66,"t":"仆人就将所办的一切事都告诉以撒。","notes":[]},{"n":67,"t":"以撒便领利百加进了他母亲撒拉的帐棚，娶了她为妻，并且爱她。以撒自从他母亲不在了，这才得了安慰。","notes":[]}]},"25":{"heading":"亚伯拉罕的其他后代","verses":[{"n":1,"t":"亚伯拉罕又娶了一妻，名叫基土拉。","notes":[]},{"n":2,"t":"基土拉给他生了心兰、约珊、米但、米甸、伊施巴，和书亚。","notes":[]},{"n":3,"t":"约珊生了示巴和底但。底但的子孙是亚书利族、利都是族，和利乌米族。","notes":[]},{"n":4,"t":"米甸的儿子是以法、以弗、哈诺、亚比大，和以勒大。这都是基土拉的子孙。","notes":[]},{"n":5,"t":"亚伯拉罕将一切所有的都给了以撒。","notes":[]},{"n":6,"t":"亚伯拉罕把财物分给他庶出的众子，趁着自己还在世的时候打发他们离开他的儿子以撒，往东方去。","notes":[]},{"n":7,"t":"亚伯拉罕一生的年日是一百七十五岁。","notes":[],"heads":["亚伯拉罕的死和埋葬"]},{"n":8,"t":"亚伯拉罕寿高年迈，气绝而死，归到他列祖那里。","notes":["原文是本民"]},{"n":9,"t":"他两个儿子以撒、以实玛利把他埋葬在麦比拉洞里。这洞在幔利前、赫人琐辖的儿子以弗仑的田中，","notes":[]},{"n":10,"t":"就是亚伯拉罕向赫人买的那块田。亚伯拉罕和他妻子撒拉都葬在那里。","notes":[]},{"n":11,"t":"亚伯拉罕死了以后，神赐福给他的儿子以撒。以撒靠近庇耳·拉海·莱居住。","notes":[]},{"n":12,"t":"撒拉的使女埃及人夏甲给亚伯拉罕所生的儿子是以实玛利。","notes":[],"heads":["以实玛利的后代"]},{"n":13,"t":"以实玛利儿子们的名字，按着他们的家谱记在下面。以实玛利的长子是尼拜约，又有基达、亚德别、米比衫、","notes":[]},{"n":14,"t":"米施玛、度玛、玛撒、","notes":[]},{"n":15,"t":"哈大、提玛、伊突、拿非施、基底玛。","notes":[]},{"n":16,"t":"这是以实玛利众子的名字，照着他们的村庄、营寨，作了十二族的族长。","notes":[]},{"n":17,"t":"以实玛利享寿一百三十七岁，气绝而死，归到他列祖那里。","notes":["原文是本民"]},{"n":18,"t":"他子孙的住处在他众弟兄东边，从哈腓拉直到埃及前的书珥，正在亚述的道上。","notes":[]},{"n":19,"t":"亚伯拉罕的儿子以撒的后代记在下面。亚伯拉罕生以撒。","notes":[],"heads":["以扫和雅各出生"]},{"n":20,"t":"以撒娶利百加为妻的时候正四十岁。利百加是巴旦·亚兰地的亚兰人彼土利的女儿，是亚兰人拉班的妹子。","notes":[]},{"n":21,"t":"以撒因他妻子不生育，就为她祈求耶和华；耶和华应允他的祈求，他的妻子利百加就怀了孕。","notes":[]},{"n":22,"t":"孩子们在她腹中彼此相争，她就说：「若是这样，我为什么活着呢？」她就去求问耶和华。","notes":["或译：我为什么如此呢"]},{"n":23,"t":"耶和华对她说：两国在你腹内；两族要从你身上出来。这族必强于那族；将来大的要服事小的。","notes":[]},{"n":24,"t":"生产的日子到了，腹中果然是双子。","notes":[]},{"n":25,"t":"先产的身体发红，浑身有毛，如同皮衣，他们就给他起名叫以扫。","notes":["就是有毛的意思"]},{"n":26,"t":"随后又生了以扫的兄弟，手抓住以扫的脚跟，因此给他起名叫雅各。利百加生下两个儿子的时候，以撒年正六十岁。","notes":["就是抓住的意思"]},{"n":27,"t":"两个孩子渐渐长大，以扫善于打猎，常在田野；雅各为人安静，常住在帐棚里。","notes":[],"heads":["以扫出卖长子的名分"]},{"n":28,"t":"以撒爱以扫，因为常吃他的野味；利百加却爱雅各。","notes":[]},{"n":29,"t":"有一天，雅各熬汤，以扫从田野回来累昏了。","notes":[]},{"n":30,"t":"以扫对雅各说：「我累昏了，求你把这红汤给我喝。」因此以扫又叫以东。","notes":["就是红的意思"]},{"n":31,"t":"雅各说：「你今日把长子的名分卖给我吧。」","notes":[]},{"n":32,"t":"以扫说：「我将要死，这长子的名分于我有什么益处呢？」","notes":[]},{"n":33,"t":"雅各说：「你今日对我起誓吧。」以扫就对他起了誓，把长子的名分卖给雅各。","notes":[]},{"n":34,"t":"于是雅各将饼和红豆汤给了以扫，以扫吃了喝了，便起来走了。这就是以扫轻看了他长子的名分。","notes":[]}]},"26":{"heading":"以撒住在基拉耳","verses":[{"n":1,"t":"在亚伯拉罕的日子，那地有一次饥荒；这时又有饥荒，以撒就往基拉耳去，到非利士人的王亚比米勒那里。","notes":[]},{"n":2,"t":"耶和华向以撒显现，说：「你不要下埃及去，要住在我所指示你的地。","notes":[]},{"n":3,"t":"你寄居在这地，我必与你同在，赐福给你，因为我要将这些地都赐给你和你的后裔。我必坚定我向你父亚伯拉罕所起的誓。","notes":[]},{"n":4,"t":"我要加增你的后裔，像天上的星那样多，又要将这些地都赐给你的后裔。并且地上万国必因你的后裔得福—","notes":[]},{"n":5,"t":"都因亚伯拉罕听从我的话，遵守我的吩咐和我的命令、律例、法度。」","notes":[]},{"n":6,"t":"以撒就住在基拉耳。","notes":[]},{"n":7,"t":"那地方的人问到他的妻子，他便说：「那是我的妹子。」原来他怕说：「是我的妻子」；他心里想：「恐怕这地方的人为利百加的缘故杀我」，因为她容貌俊美。","notes":[]},{"n":8,"t":"他在那里住了许久。有一天，非利士人的王亚比米勒从窗户里往外观看，见以撒和他的妻子利百加戏玩。","notes":[]},{"n":9,"t":"亚比米勒召了以撒来，对他说：「她实在是你的妻子，你怎么说她是你的妹子？」以撒说：「我心里想，恐怕我因她而死。」","notes":[]},{"n":10,"t":"亚比米勒说：「你向我们做的是什么事呢？民中险些有人和你的妻同寝，把我们陷在罪里。」","notes":[]},{"n":11,"t":"于是亚比米勒晓谕众民说：「凡沾着这个人，或是他妻子的，定要把他治死。」","notes":[]},{"n":12,"t":"以撒在那地耕种，那一年有百倍的收成。耶和华赐福给他，","notes":[]},{"n":13,"t":"他就昌大，日增月盛，成了大富户。","notes":[]},{"n":14,"t":"他有羊群牛群，又有许多仆人，非利士人就嫉妒他。","notes":[]},{"n":15,"t":"当他父亲亚伯拉罕在世的日子，他父亲的仆人所挖的井，非利士人全都塞住，填满了土。","notes":[]},{"n":16,"t":"亚比米勒对以撒说：「你离开我们去吧。因为你比我们强盛得多。」","notes":[]},{"n":17,"t":"以撒就离开那里，在基拉耳谷支搭帐棚，住在那里。","notes":[]},{"n":18,"t":"当他父亲亚伯拉罕在世之日所挖的水井因非利士人在亚伯拉罕死后塞住了，以撒就重新挖出来，仍照他父亲所叫的叫那些井的名字。","notes":[]},{"n":19,"t":"以撒的仆人在谷中挖井，便得了一口活水井。","notes":[]},{"n":20,"t":"基拉耳的牧人与以撒的牧人争竞，说：「这水是我们的。」以撒就给那井起名叫埃色，因为他们和他相争。","notes":["就是相争的意思"]},{"n":21,"t":"以撒的仆人又挖了一口井，他们又为这井争竞，因此以撒给这井起名叫西提拿。","notes":["就是为敌的意思"]},{"n":22,"t":"以撒离开那里，又挖了一口井，他们不为这井争竞了，他就给那井起名叫利河伯。他说：「耶和华现在给我们宽阔之地，我们必在这地昌盛。」","notes":["就是宽阔的意思"]},{"n":23,"t":"以撒从那里上别是巴去。","notes":[]},{"n":24,"t":"当夜耶和华向他显现，说：「我是你父亲亚伯拉罕的神，不要惧怕！因为我与你同在，要赐福给你，并要为我仆人亚伯拉罕的缘故，使你的后裔繁多。」","notes":[]},{"n":25,"t":"以撒就在那里筑了一座坛，求告耶和华的名，并且支搭帐棚；他的仆人便在那里挖了一口井。","notes":[]},{"n":26,"t":"亚比米勒，同他的朋友亚户撒和他的军长非各，从基拉耳来见以撒。","notes":[],"heads":["以撒跟亚比米勒立约"]},{"n":27,"t":"以撒对他们说：「你们既然恨我，打发我走了，为什么到我这里来呢？」","notes":[]},{"n":28,"t":"他们说：「我们明明地看见耶和华与你同在，便说，不如我们两下彼此起誓，彼此立约，","notes":[]},{"n":29,"t":"使你不害我们，正如我们未曾害你，一味地厚待你，并且打发你平平安安地走。你是蒙耶和华赐福的了。」","notes":[]},{"n":30,"t":"以撒就为他们设摆筵席，他们便吃了喝了。","notes":[]},{"n":31,"t":"他们清早起来彼此起誓。以撒打发他们走，他们就平平安安地离开他走了。","notes":[]},{"n":32,"t":"那一天，以撒的仆人来，将挖井的事告诉他说：「我们得了水了。」","notes":[]},{"n":33,"t":"他就给那井起名叫示巴；因此那城叫做别是巴，直到今日。","notes":[]},{"n":34,"t":"以扫四十岁的时候娶了赫人比利的女儿犹滴，与赫人以伦的女儿巴实抹为妻。","notes":[],"heads":["以扫的外族妻子"]},{"n":35,"t":"她们常使以撒和利百加心里愁烦。","notes":[]}]},"27":{"heading":"以撒祝福雅各","verses":[{"n":1,"t":"以撒年老，眼睛昏花，不能看见，就叫了他大儿子以扫来，说：「我儿。」以扫说：「我在这里。」","notes":[]},{"n":2,"t":"他说：「我如今老了，不知道哪一天死。","notes":[]},{"n":3,"t":"现在拿你的器械，就是箭囊和弓，往田野去为我打猎，","notes":[]},{"n":4,"t":"照我所爱的做成美味，拿来给我吃，使我在未死之先给你祝福。」","notes":[]},{"n":5,"t":"以撒对他儿子以扫说话，利百加也听见了。以扫往田野去打猎，要得野味带来。","notes":[]},{"n":6,"t":"利百加就对她儿子雅各说：「我听见你父亲对你哥哥以扫说：","notes":[]},{"n":7,"t":"『你去把野兽带来，做成美味给我吃，我好在未死之先，在耶和华面前给你祝福。』","notes":[]},{"n":8,"t":"现在，我儿，你要照着我所吩咐你的，听从我的话。","notes":[]},{"n":9,"t":"你到羊群里去，给我拿两只肥山羊羔来，我便照你父亲所爱的给他做成美味。","notes":[]},{"n":10,"t":"你拿到你父亲那里给他吃，使他在未死之先给你祝福。」","notes":[]},{"n":11,"t":"雅各对他母亲利百加说：「我哥哥以扫浑身是有毛的，我身上是光滑的；","notes":[]},{"n":12,"t":"倘若我父亲摸着我，必以我为欺哄人的，我就招咒诅，不得祝福。」","notes":[]},{"n":13,"t":"他母亲对他说：「我儿，你招的咒诅归到我身上；你只管听我的话，去把羊羔给我拿来。」","notes":[]},{"n":14,"t":"他便去拿来，交给他母亲；他母亲就照他父亲所爱的做成美味。","notes":[]},{"n":15,"t":"利百加又把家里所存大儿子以扫上好的衣服给她小儿子雅各穿上，","notes":[]},{"n":16,"t":"又用山羊羔皮包在雅各的手上和颈项的光滑处，","notes":[]},{"n":17,"t":"就把所做的美味和饼交在她儿子雅各的手里。","notes":[]},{"n":18,"t":"雅各到他父亲那里说：「我父亲！」他说：「我在这里。我儿，你是谁？」","notes":[]},{"n":19,"t":"雅各对他父亲说：「我是你的长子以扫；我已照你所吩咐我的行了。请起来坐着，吃我的野味，好给我祝福。」","notes":[]},{"n":20,"t":"以撒对他儿子说：「我儿，你如何找得这么快呢？」他说：「因为耶和华—你的神使我遇见好机会得着的。」","notes":[]},{"n":21,"t":"以撒对雅各说：「我儿，你近前来，我摸摸你，知道你真是我的儿子以扫不是。」","notes":[]},{"n":22,"t":"雅各就挨近他父亲以撒。以撒摸着他，说：「声音是雅各的声音，手却是以扫的手。」","notes":[]},{"n":23,"t":"以撒就辨不出他来；因为他手上有毛，像他哥哥以扫的手一样，就给他祝福；","notes":[]},{"n":24,"t":"又说：「你真是我儿子以扫吗？」他说：「我是。」","notes":[]},{"n":25,"t":"以撒说：「你递给我，我好吃我儿子的野味，给你祝福。」雅各就递给他，他便吃了，又拿酒给他，他也喝了。","notes":[]},{"n":26,"t":"他父亲以撒对他说：「我儿，你上前来与我亲嘴。」","notes":[]},{"n":27,"t":"他就上前与父亲亲嘴。他父亲一闻他衣服上的香气，就给他祝福，说：我儿的香气如同耶和华赐福之田地的香气一样。","notes":[]},{"n":28,"t":"愿神赐你天上的甘露，地上的肥土，并许多五谷新酒。","notes":[]},{"n":29,"t":"愿多民事奉你，多国跪拜你。愿你作你弟兄的主；你母亲的儿子向你跪拜。凡咒诅你的，愿他受咒诅；为你祝福的，愿他蒙福。","notes":[]},{"n":30,"t":"以撒为雅各祝福已毕，雅各从他父亲那里才出来，他哥哥以扫正打猎回来，","notes":[],"heads":["以扫求以撒祝福"]},{"n":31,"t":"也做了美味，拿来给他父亲，说：「请父亲起来，吃你儿子的野味，好给我祝福。」","notes":[]},{"n":32,"t":"他父亲以撒对他说：「你是谁？」他说：「我是你的长子以扫。」","notes":[]},{"n":33,"t":"以撒就大大地战兢，说：「你未来之先，是谁得了野味拿来给我呢？我已经吃了，为他祝福；他将来也必蒙福。」","notes":[]},{"n":34,"t":"以扫听了他父亲的话，就放声痛哭，说：「我父啊，求你也为我祝福！」","notes":[]},{"n":35,"t":"以撒说：「你兄弟已经用诡计来将你的福分夺去了。」","notes":[]},{"n":36,"t":"以扫说：「他名雅各，岂不是正对吗？因为他欺骗了我两次：他从前夺了我长子的名分，你看，他现在又夺了我的福分。」以扫又说：「你没有留下为我可祝的福吗？」","notes":[]},{"n":37,"t":"以撒回答以扫说：「我已立他为你的主，使他的弟兄都给他作仆人，并赐他五谷新酒可以养生。我儿，现在我还能为你做什么呢？」","notes":[]},{"n":38,"t":"以扫对他父亲说：「父啊，你只有一样可祝的福吗？我父啊，求你也为我祝福！」以扫就放声而哭。","notes":[]},{"n":39,"t":"他父亲以撒说：地上的肥土必为你所住；天上的甘露必为你所得。","notes":[]},{"n":40,"t":"你必倚靠刀剑度日，又必事奉你的兄弟；到你强盛的时候，必从你颈项上挣开他的轭。","notes":[]},{"n":41,"t":"以扫因他父亲给雅各祝的福，就怨恨雅各，心里说：「为我父亲居丧的日子近了，到那时候，我要杀我的兄弟雅各。」","notes":[]},{"n":42,"t":"有人把利百加大儿子以扫的话告诉利百加，她就打发人去，叫了她小儿子雅各来，对他说：「你哥哥以扫想要杀你，报仇雪恨。","notes":[]},{"n":43,"t":"现在，我儿，你要听我的话：起来，逃往哈兰、我哥哥拉班那里去，","notes":[]},{"n":44,"t":"同他住些日子，直等你哥哥的怒气消了。","notes":[]},{"n":45,"t":"你哥哥向你消了怒气，忘了你向他所做的事，我便打发人去把你从那里带回来。为什么一日丧你们二人呢？」","notes":[]},{"n":46,"t":"利百加对以撒说：「我因这赫人的女子连性命都厌烦了；倘若雅各也娶赫人的女子为妻，像这些一样，我活着还有什么益处呢？」","notes":[],"heads":["以撒打发雅各到拉班的家去"]}]},"28":{"heading":"以扫另娶一妻","verses":[{"n":1,"t":"以撒叫了雅各来，给他祝福，并嘱咐他说：「你不要娶迦南的女子为妻。","notes":[]},{"n":2,"t":"你起身往巴旦·亚兰去，到你外祖彼土利家里，在你母舅拉班的女儿中娶一女为妻。","notes":[]},{"n":3,"t":"愿全能的神赐福给你，使你生养众多，成为多族，","notes":[]},{"n":4,"t":"将应许亚伯拉罕的福赐给你和你的后裔，使你承受你所寄居的地为业，就是神赐给亚伯拉罕的地。」","notes":[]},{"n":5,"t":"以撒打发雅各走了，他就往巴旦·亚兰去，到亚兰人彼土利的儿子拉班那里。拉班是雅各、以扫的母舅。","notes":[]},{"n":6,"t":"以扫见以撒已经给雅各祝福，而且打发他往巴旦·亚兰去，在那里娶妻，并见祝福的时候嘱咐他说：「不要娶迦南的女子为妻」，","notes":[]},{"n":7,"t":"又见雅各听从父母的话往巴旦·亚兰去了，","notes":[]},{"n":8,"t":"以扫就晓得他父亲以撒看不中迦南的女子，","notes":[]},{"n":9,"t":"便往以实玛利那里去，在他二妻之外又娶了玛哈拉为妻。她是亚伯拉罕儿子以实玛利的女儿，尼拜约的妹子。","notes":[]},{"n":10,"t":"雅各出了别是巴，向哈兰走去；","notes":[],"heads":["雅各在伯特利做的梦"]},{"n":11,"t":"到了一个地方，因为太阳落了，就在那里住宿，便拾起那地方的一块石头枕在头下，在那里躺卧睡了，","notes":[]},{"n":12,"t":"梦见一个梯子立在地上，梯子的头顶着天，有神的使者在梯子上，上去下来。","notes":[]},{"n":13,"t":"耶和华站在梯子以上，说：「我是耶和华—你祖亚伯拉罕的神，也是以撒的神；我要将你现在所躺卧之地赐给你和你的后裔。","notes":["或译：站在他旁边"]},{"n":14,"t":"你的后裔必像地上的尘沙那样多，必向东西南北开展；地上万族必因你和你的后裔得福。","notes":[]},{"n":15,"t":"我也与你同在。你无论往哪里去，我必保佑你，领你归回这地，总不离弃你，直到我成全了向你所应许的。」","notes":[]},{"n":16,"t":"雅各睡醒了，说：「耶和华真在这里，我竟不知道！」","notes":[]},{"n":17,"t":"就惧怕，说：「这地方何等可畏！这不是别的，乃是神的殿，也是天的门。」","notes":[]},{"n":18,"t":"雅各清早起来，把所枕的石头立作柱子，浇油在上面。","notes":[]},{"n":19,"t":"他就给那地方起名叫伯特利；但那地方起先名叫路斯。","notes":["就是神殿的意思"]},{"n":20,"t":"雅各许愿说：「神若与我同在，在我所行的路上保佑我，又给我食物吃，衣服穿，","notes":[]},{"n":21,"t":"使我平平安安地回到我父亲的家，我就必以耶和华为我的神。","notes":[]},{"n":22,"t":"我所立为柱子的石头也必作神的殿；凡你所赐给我的，我必将十分之一献给你。」","notes":[]}]},"29":{"heading":"雅各到了拉班的家","verses":[{"n":1,"t":"雅各起行，到了东方人之地，","notes":[]},{"n":2,"t":"看见田间有一口井，有三群羊卧在井旁；因为人饮羊群都是用那井里的水。井口上的石头是大的。","notes":[]},{"n":3,"t":"常有羊群在那里聚集，牧人把石头转离井口饮羊，随后又把石头放在井口的原处。","notes":[]},{"n":4,"t":"雅各对牧人说：「弟兄们，你们是哪里来的？」他们说：「我们是哈兰来的。」","notes":[]},{"n":5,"t":"他问他们说：「拿鹤的孙子拉班，你们认识吗？」他们说：「我们认识。」","notes":[]},{"n":6,"t":"雅各说：「他平安吗？」他们说：「平安。看哪，他女儿拉结领着羊来了。」","notes":[]},{"n":7,"t":"雅各说：「日头还高，不是羊群聚集的时候，你们不如饮羊，再去放一放。」","notes":[]},{"n":8,"t":"他们说：「我们不能，必等羊群聚齐，人把石头转离井口才可饮羊。」","notes":[]},{"n":9,"t":"雅各正和他们说话的时候，拉结领着她父亲的羊来了，因为那些羊是她牧放的。","notes":[]},{"n":10,"t":"雅各看见母舅拉班的女儿拉结和母舅拉班的羊群，就上前把石头转离井口，饮他母舅拉班的羊群。","notes":[]},{"n":11,"t":"雅各与拉结亲嘴，就放声而哭。","notes":[]},{"n":12,"t":"雅各告诉拉结，自己是她父亲的外甥，是利百加的儿子，拉结就跑去告诉她父亲。","notes":[]},{"n":13,"t":"拉班听见外甥雅各的信息，就跑去迎接，抱着他，与他亲嘴，领他到自己的家。雅各将一切的情由告诉拉班。","notes":[]},{"n":14,"t":"拉班对他说：「你实在是我的骨肉。」雅各就和他同住了一个月。","notes":[]},{"n":15,"t":"拉班对雅各说：「你虽是我的骨肉，岂可白白地服事我？请告诉我，你要什么为工价？」","notes":["原文是弟兄"],"heads":["雅各为拉结和利亚服事拉班"]},{"n":16,"t":"拉班有两个女儿，大的名叫利亚，小的名叫拉结。","notes":[]},{"n":17,"t":"利亚的眼睛没有神气，拉结却生得美貌俊秀。","notes":[]},{"n":18,"t":"雅各爱拉结，就说：「我愿为你小女儿拉结服事你七年。」","notes":[]},{"n":19,"t":"拉班说：「我把她给你，胜似给别人，你与我同住吧！」","notes":[]},{"n":20,"t":"雅各就为拉结服事了七年；他因为深爱拉结，就看这七年如同几天。","notes":[]},{"n":21,"t":"雅各对拉班说：「日期已经满了，求你把我的妻子给我，我好与她同房。」","notes":[]},{"n":22,"t":"拉班就摆设筵席，请齐了那地方的众人。","notes":[]},{"n":23,"t":"到晚上，拉班将女儿利亚送来给雅各，雅各就与她同房。","notes":[]},{"n":24,"t":"拉班又将婢女悉帕给女儿利亚作使女。","notes":[]},{"n":25,"t":"到了早晨，雅各一看是利亚，就对拉班说：「你向我做的是什么事呢？我服事你，不是为拉结吗？你为什么欺哄我呢？」","notes":[]},{"n":26,"t":"拉班说：「大女儿还没有给人，先把小女儿给人，在我们这地方没有这规矩。","notes":[]},{"n":27,"t":"你为这个满了七日，我就把那个也给你，你再为她服事我七年。」","notes":[]},{"n":28,"t":"雅各就如此行。满了利亚的七日，拉班便将女儿拉结给雅各为妻。","notes":[]},{"n":29,"t":"拉班又将婢女辟拉给女儿拉结作使女。","notes":[]},{"n":30,"t":"雅各也与拉结同房，并且爱拉结胜似爱利亚，于是又服事了拉班七年。","notes":[]},{"n":31,"t":"耶和华见利亚失宠，就使她生育，拉结却不生育。","notes":["原文是被恨；下同"],"heads":["雅各的儿女"]},{"n":32,"t":"利亚怀孕生子，就给他起名叫吕便，因而说：「耶和华看见我的苦情，如今我的丈夫必爱我。」","notes":["就是有儿子的意思"]},{"n":33,"t":"她又怀孕生子，就说：「耶和华因为听见我失宠，所以又赐给我这个儿子」，于是给他起名叫西缅。","notes":["就是听见的意思"]},{"n":34,"t":"她又怀孕生子，起名叫利未，说：「我给丈夫生了三个儿子，他必与我联合。」","notes":["就是联合的意思"]},{"n":35,"t":"她又怀孕生子，说：「这回我要赞美耶和华」，因此给他起名叫犹大。这才停了生育。","notes":["就是赞美的意思"]}]},"30":{"heading":"雅各和拉班定工价","verses":[{"n":1,"t":"拉结见自己不给雅各生子，就嫉妒她姊姊，对雅各说：「你给我孩子，不然我就死了。」","notes":[]},{"n":2,"t":"雅各向拉结生气，说：「叫你不生育的是神，我岂能代替他作主呢？」","notes":[]},{"n":3,"t":"拉结说：「有我的使女辟拉在这里，你可以与她同房，使她生子在我膝下，我便因她也得孩子。」","notes":["原文是被建立"]},{"n":4,"t":"拉结就把她的使女辟拉给丈夫为妾；雅各便与她同房，","notes":[]},{"n":5,"t":"辟拉就怀孕，给雅各生了一个儿子。","notes":[]},{"n":6,"t":"拉结说：「神伸了我的冤，也听了我的声音，赐我一个儿子」，因此给他起名叫但。","notes":["就是伸冤的意思"]},{"n":7,"t":"拉结的使女辟拉又怀孕，给雅各生了第二个儿子。","notes":[]},{"n":8,"t":"拉结说：「我与我姊姊大大相争，并且得胜」，于是给他起名叫拿弗他利。","notes":["就是相争的意思"]},{"n":9,"t":"利亚见自己停了生育，就把使女悉帕给雅各为妾。","notes":[]},{"n":10,"t":"利亚的使女悉帕给雅各生了一个儿子。","notes":[]},{"n":11,"t":"利亚说：「万幸！」于是给他起名叫迦得。","notes":["就是万幸的意思"]},{"n":12,"t":"利亚的使女悉帕又给雅各生了第二个儿子。","notes":[]},{"n":13,"t":"利亚说：「我有福啊，众女子都要称我是有福的」，于是给他起名叫亚设。","notes":["就是有福的意思"]},{"n":14,"t":"割麦子的时候，吕便往田里去，寻见风茄，拿来给他母亲利亚。拉结对利亚说：「请你把你儿子的风茄给我些。」","notes":[]},{"n":15,"t":"利亚说：「你夺了我的丈夫还算小事吗？你又要夺我儿子的风茄吗？」拉结说：「为你儿子的风茄，今夜他可以与你同寝。」","notes":[]},{"n":16,"t":"到了晚上，雅各从田里回来，利亚出来迎接他，说：「你要与我同寝，因为我实在用我儿子的风茄把你雇下了。」那一夜，雅各就与她同寝。","notes":[]},{"n":17,"t":"神应允了利亚，她就怀孕，给雅各生了第五个儿子。","notes":[]},{"n":18,"t":"利亚说：「神给了我价值，因为我把使女给了我丈夫」，于是给他起名叫以萨迦。","notes":["就是价值的意思"]},{"n":19,"t":"利亚又怀孕，给雅各生了第六个儿子。","notes":[]},{"n":20,"t":"利亚说：「神赐我厚赏；我丈夫必与我同住，因我给他生了六个儿子」，于是给他起名西布伦。","notes":["就是同住的意思"]},{"n":21,"t":"后来又生了一个女儿，给她起名叫底拿。","notes":[]},{"n":22,"t":"神顾念拉结，应允了她，使她能生育。","notes":[]},{"n":23,"t":"拉结怀孕生子，说：「神除去了我的羞耻」，","notes":[]},{"n":24,"t":"就给他起名叫约瑟，意思说：「愿耶和华再增添我一个儿子。」","notes":["就是增添的意思"]},{"n":25,"t":"拉结生约瑟之后，雅各对拉班说：「请打发我走，叫我回到我本乡本土去。","notes":[]},{"n":26,"t":"请你把我服事你所得的妻子和儿女给我，让我走；我怎样服事你，你都知道。」","notes":[]},{"n":27,"t":"拉班对他说：「我若在你眼前蒙恩，请你仍与我同住，因为我已算定，耶和华赐福与我是为你的缘故」；","notes":[]},{"n":28,"t":"又说：「请你定你的工价，我就给你。」","notes":[]},{"n":29,"t":"雅各对他说：「我怎样服事你，你的牲畜在我手里怎样，是你知道的。","notes":[]},{"n":30,"t":"我未来之先，你所有的很少，现今却发大众多，耶和华随我的脚步赐福与你。如今，我什么时候才为自己兴家立业呢？」","notes":[]},{"n":31,"t":"拉班说：「我当给你什么呢？」雅各说：「什么你也不必给我，只有一件事，你若应承，我便仍旧牧放你的羊群。","notes":[]},{"n":32,"t":"今天我要走遍你的羊群，把绵羊中凡有点的、有斑的，和黑色的，并山羊中凡有斑的、有点的，都挑出来；将来这一等的就算我的工价。","notes":[]},{"n":33,"t":"以后你来查看我的工价，凡在我手里的山羊不是有点有斑的，绵羊不是黑色的，那就算是我偷的；这样便可证出我的公义来。」","notes":[]},{"n":34,"t":"拉班说：「好啊！我情愿照着你的话行。」","notes":[]},{"n":35,"t":"当日，拉班把有纹的、有斑的公山羊，有点的、有斑的、有杂白纹的母山羊，并黑色的绵羊，都挑出来，交在他儿子们的手下，","notes":[]},{"n":36,"t":"又使自己和雅各相离三天的路程。雅各就牧养拉班其余的羊。","notes":[]},{"n":37,"t":"雅各拿杨树、杏树、枫树的嫩枝，将皮剥成白纹，使枝子露出白的来，","notes":[]},{"n":38,"t":"将剥了皮的枝子，对着羊群，插在饮羊的水沟里和水槽里，羊来喝的时候，牝牡配合。","notes":[]},{"n":39,"t":"羊对着枝子配合，就生下有纹的、有点的、有斑的来。","notes":[]},{"n":40,"t":"雅各把羊羔分出来，使拉班的羊与这有纹和黑色的羊相对，把自己的羊另放一处，不叫他和拉班的羊混杂。","notes":[]},{"n":41,"t":"到羊群肥壮配合的时候，雅各就把枝子插在水沟里，使羊对着枝子配合。","notes":[]},{"n":42,"t":"只是到羊瘦弱配合的时候就不插枝子。这样，瘦弱的就归拉班，肥壮的就归雅各。","notes":[]},{"n":43,"t":"于是雅各极其发大，得了许多的羊群、仆婢、骆驼，和驴。","notes":[]}]},"31":{"heading":"雅各逃离拉班","verses":[{"n":1,"t":"雅各听见拉班的儿子们有话说：「雅各把我们父亲所有的都夺了去，并借着我们父亲的，得了这一切的荣耀。」","notes":["或译：财"]},{"n":2,"t":"雅各见拉班的气色向他不如从前了。","notes":[]},{"n":3,"t":"耶和华对雅各说：「你要回你祖、你父之地，到你亲族那里去，我必与你同在。」","notes":[]},{"n":4,"t":"雅各就打发人，叫拉结和利亚到田野羊群那里来，","notes":[]},{"n":5,"t":"对她们说：「我看你们父亲的气色向我不如从前了；但我父亲的神向来与我同在。","notes":[]},{"n":6,"t":"你们也知道，我尽了我的力量服事你们的父亲。","notes":[]},{"n":7,"t":"你们的父亲欺哄我，十次改了我的工价；然而神不容他害我。","notes":[]},{"n":8,"t":"他若说：『有点的归你作工价』，羊群所生的都有点；他若说：『有纹的归你作工价』，羊群所生的都有纹。","notes":[]},{"n":9,"t":"这样，神把你们父亲的牲畜夺来赐给我了。","notes":[]},{"n":10,"t":"羊配合的时候，我梦中举目一看，见跳母羊的公羊都是有纹的、有点的、有花斑的。","notes":[]},{"n":11,"t":"神的使者在那梦中呼叫我说：『雅各。』我说：『我在这里。』","notes":[]},{"n":12,"t":"他说：『你举目观看，跳母羊的公羊都是有纹的、有点的、有花斑的；凡拉班向你所做的，我都看见了。","notes":[]},{"n":13,"t":"我是伯特利的神；你在那里用油浇过柱子，向我许过愿。现今你起来，离开这地，回你本地去吧！』」","notes":[]},{"n":14,"t":"拉结和利亚回答雅各说：「在我们父亲的家里还有我们可得的分吗？还有我们的产业吗？","notes":[]},{"n":15,"t":"我们不是被他当作外人吗？因为他卖了我们，吞了我们的价值。","notes":[]},{"n":16,"t":"神从我们父亲所夺出来的一切财物，那就是我们和我们孩子们的。现今凡神所吩咐你的，你只管去行吧！」","notes":[]},{"n":17,"t":"雅各起来，使他的儿子和妻子都骑上骆驼，","notes":[]},{"n":18,"t":"又带着他在巴旦·亚兰所得的一切牲畜和财物，往迦南地、他父亲以撒那里去了。","notes":[]},{"n":19,"t":"当时拉班剪羊毛去了，拉结偷了他父亲家中的神像。","notes":[]},{"n":20,"t":"雅各背着亚兰人拉班偷走了，并不告诉他，","notes":[]},{"n":21,"t":"就带着所有的逃跑。他起身过大河，面向基列山行去。","notes":[]},{"n":22,"t":"到第三日，有人告诉拉班，雅各逃跑了。","notes":[],"heads":["拉班追赶雅各"]},{"n":23,"t":"拉班带领他的众弟兄去追赶，追了七日，在基列山就追上了。","notes":[]},{"n":24,"t":"夜间，神到亚兰人拉班那里，在梦中对他说：「你要小心，不可与雅各说好说歹。」","notes":[]},{"n":25,"t":"拉班追上雅各。雅各在山上支搭帐棚；拉班和他的众弟兄也在基列山上支搭帐棚。","notes":[]},{"n":26,"t":"拉班对雅各说：「你做的是什么事呢？你背着我偷走了，又把我的女儿们带了去，如同用刀剑掳去的一般。","notes":[]},{"n":27,"t":"你为什么暗暗地逃跑，偷着走，并不告诉我，叫我可以欢乐、唱歌、击鼓、弹琴地送你回去？","notes":[]},{"n":28,"t":"又不容我与外孙和女儿亲嘴？你所行的真是愚昧！","notes":[]},{"n":29,"t":"我手中原有能力害你，只是你父亲的神昨夜对我说：『你要小心，不可与雅各说好说歹。』","notes":[]},{"n":30,"t":"现在你虽然想你父家，不得不去，为什么又偷了我的神像呢？」","notes":[]},{"n":31,"t":"雅各回答拉班说：「恐怕你把你的女儿从我夺去，所以我逃跑。","notes":[]},{"n":32,"t":"至于你的神像，你在谁那里搜出来，就不容谁存活。当着我们的众弟兄，你认一认，在我这里有什么东西是你的，就拿去。」原来雅各不知道拉结偷了那些神像。","notes":[]},{"n":33,"t":"拉班进了雅各、利亚，并两个使女的帐棚，都没有搜出来，就从利亚的帐棚出来，进了拉结的帐棚。","notes":[]},{"n":34,"t":"拉结已经把神像藏在骆驼的驮篓里，便坐在上头。拉班摸遍了那帐棚，并没有摸着。","notes":[]},{"n":35,"t":"拉结对她父亲说：「现在我身上不便，不能在你面前起来，求我主不要生气。」这样，拉班搜寻神像，竟没有搜出来。","notes":[]},{"n":36,"t":"雅各就发怒斥责拉班说：「我有什么过犯，有什么罪恶，你竟这样火速地追我？","notes":[]},{"n":37,"t":"你摸遍了我一切的家具，你搜出什么来呢？可以放在你我弟兄面前，叫他们在你我中间辨别辨别。","notes":[]},{"n":38,"t":"我在你家这二十年，你的母绵羊、母山羊没有掉过胎。你群中的公羊，我没有吃过；","notes":[]},{"n":39,"t":"被野兽撕裂的，我没有带来给你，是我自己赔上。无论是白日，是黑夜，被偷去的，你都向我索要。","notes":[]},{"n":40,"t":"我白日受尽干热，黑夜受尽寒霜，不得合眼睡着，我常是这样。","notes":[]},{"n":41,"t":"我这二十年在你家里，为你的两个女儿服事你十四年，为你的羊群服事你六年，你又十次改了我的工价。","notes":[]},{"n":42,"t":"若不是我父亲以撒所敬畏的神，就是亚伯拉罕的神与我同在，你如今必定打发我空手而去。神看见我的苦情和我的劳碌，就在昨夜责备你。」","notes":[]},{"n":43,"t":"拉班回答雅各说：「这女儿是我的女儿，这些孩子是我的孩子，这些羊群也是我的羊群；凡在你眼前的都是我的。我的女儿并她们所生的孩子，我今日能向他们做什么呢？","notes":[],"heads":["雅各和拉班立约"]},{"n":44,"t":"来吧！你我二人可以立约，作你我中间的证据。」","notes":[]},{"n":45,"t":"雅各就拿一块石头立作柱子，","notes":[]},{"n":46,"t":"又对众弟兄说：「你们堆聚石头。」他们就拿石头来堆成一堆，大家便在旁边吃喝。","notes":[]},{"n":47,"t":"拉班称那石堆为伊迦尔·撒哈杜他，雅各却称那石堆为迦累得。","notes":["都是以石堆为证的意思"]},{"n":48,"t":"拉班说：「今日这石堆作你我中间的证据。」因此这地方名叫迦累得，","notes":[]},{"n":49,"t":"又叫米斯巴，意思说：「我们彼此离别以后，愿耶和华在你我中间鉴察。","notes":[]},{"n":50,"t":"你若苦待我的女儿，又在我的女儿以外另娶妻，虽没有人知道，却有神在你我中间作见证。」","notes":[]},{"n":51,"t":"拉班又说：「你看我在你我中间所立的这石堆和柱子。","notes":[]},{"n":52,"t":"这石堆作证据，这柱子也作证据。我必不过这石堆去害你；你也不可过这石堆和柱子来害我。","notes":[]},{"n":53,"t":"但愿亚伯拉罕的神和拿鹤的神，就是他们父亲的神，在你我中间判断。」雅各就指着他父亲以撒所敬畏的神起誓，","notes":[]},{"n":54,"t":"又在山上献祭，请众弟兄来吃饭。他们吃了饭，便在山上住宿。","notes":[]},{"n":55,"t":"拉班清早起来，与他外孙和女儿亲嘴，给他们祝福，回往自己的地方去了。","notes":[]}]},"32":{"heading":"雅各准备迎见以扫","verses":[{"n":1,"t":"雅各仍旧行路，神的使者遇见他。","notes":[]},{"n":2,"t":"雅各看见他们就说：「这是神的军兵」，于是给那地方起名叫玛哈念。","notes":["就是二军兵的意思"]},{"n":3,"t":"雅各打发人先往西珥地去，就是以东地，见他哥哥以扫，","notes":[]},{"n":4,"t":"吩咐他们说：「你们对我主以扫说：『你的仆人雅各这样说：我在拉班那里寄居，直到如今。","notes":[]},{"n":5,"t":"我有牛、驴、羊群、仆婢，现在打发人来报告我主，为要在你眼前蒙恩。』」","notes":[]},{"n":6,"t":"所打发的人回到雅各那里，说：「我们到了你哥哥以扫那里，他带着四百人，正迎着你来。」","notes":[]},{"n":7,"t":"雅各就甚惧怕，而且愁烦，便把那与他同在的人口和羊群、牛群、骆驼分做两队，","notes":[]},{"n":8,"t":"说：「以扫若来击杀这一队，剩下的那一队还可以逃避。」","notes":[]},{"n":9,"t":"雅各说：「耶和华—我祖亚伯拉罕的神，我父亲以撒的神啊，你曾对我说：『回你本地本族去，我要厚待你。』","notes":[]},{"n":10,"t":"你向仆人所施的一切慈爱和诚实，我一点也不配得；我先前只拿着我的杖过这约旦河，如今我却成了两队了。","notes":[]},{"n":11,"t":"求你救我脱离我哥哥以扫的手；因为我怕他来杀我，连妻子带儿女一同杀了。","notes":[]},{"n":12,"t":"你曾说：『我必定厚待你，使你的后裔如同海边的沙，多得不可胜数。』」","notes":[]},{"n":13,"t":"当夜，雅各在那里住宿，就从他所有的物中拿礼物要送给他哥哥以扫：","notes":[]},{"n":14,"t":"母山羊二百只，公山羊二十只，母绵羊二百只，公绵羊二十只，","notes":[]},{"n":15,"t":"奶崽子的骆驼三十只—各带着崽子，母牛四十只，公牛十只，母驴二十匹，驴驹十匹；","notes":[]},{"n":16,"t":"每样各分一群，交在仆人手下，就对仆人说：「你们要在我前头过去，使群群相离，有空闲的地方」；","notes":[]},{"n":17,"t":"又吩咐尽先走的说：「我哥哥以扫遇见你的时候，问你说：『你是哪家的人？要往哪里去？你前头这些是谁的？』","notes":[]},{"n":18,"t":"你就说：『是你仆人雅各的，是送给我主以扫的礼物；他自己也在我们后边。』」","notes":[]},{"n":19,"t":"又吩咐第二、第三，和一切赶群畜的人说：「你们遇见以扫的时候也要这样对他说；","notes":[]},{"n":20,"t":"并且你们要说：『你仆人雅各在我们后边。』」因雅各心里说：「我借着在我前头去的礼物解他的恨，然后再见他的面，或者他容纳我。」","notes":[]},{"n":21,"t":"于是礼物先过去了；那夜，雅各在队中住宿。","notes":[]},{"n":22,"t":"他夜间起来，带着两个妻子，两个使女，并十一个儿子，都过了雅博渡口，","notes":[],"heads":["雅各在毗努伊勒摔跤"]},{"n":23,"t":"先打发他们过河，又打发所有的都过去，","notes":[]},{"n":24,"t":"只剩下雅各一人。有一个人来和他摔跤，直到黎明。","notes":[]},{"n":25,"t":"那人见自己胜不过他，就将他的大腿窝摸了一把，雅各的大腿窝正在摔跤的时候就扭了。","notes":[]},{"n":26,"t":"那人说：「天黎明了，容我去吧！」雅各说：「你不给我祝福，我就不容你去。」","notes":[]},{"n":27,"t":"那人说：「你名叫什么？」他说：「我名叫雅各。」","notes":[]},{"n":28,"t":"那人说：「你的名不要再叫雅各，要叫以色列；因为你与神与人较力，都得了胜。」","notes":[]},{"n":29,"t":"雅各问他说：「请将你的名告诉我。」那人说：「何必问我的名？」于是在那里给雅各祝福。","notes":[]},{"n":30,"t":"雅各便给那地方起名叫毗努伊勒，意思说：「我面对面见了神，我的性命仍得保全。」","notes":["就是神之面的意思"]},{"n":31,"t":"日头刚出来的时候，雅各经过毗努伊勒，他的大腿就瘸了。","notes":[]},{"n":32,"t":"故此，以色列人不吃大腿窝的筋，直到今日，因为那人摸了雅各大腿窝的筋。","notes":[]}]},"33":{"heading":"雅各和以扫相见","verses":[{"n":1,"t":"雅各举目观看，见以扫来了，后头跟着四百人，他就把孩子们分开交给利亚、拉结，和两个使女，","notes":[]},{"n":2,"t":"并且叫两个使女和她们的孩子在前头，利亚和她的孩子在后头，拉结和约瑟在尽后头。","notes":[]},{"n":3,"t":"他自己在他们前头过去，一连七次俯伏在地才就近他哥哥。","notes":[]},{"n":4,"t":"以扫跑来迎接他，将他抱住，又搂着他的颈项，与他亲嘴，两个人就哭了。","notes":[]},{"n":5,"t":"以扫举目看见妇人孩子，就说：「这些和你同行的是谁呢？」雅各说：「这些孩子是神施恩给你的仆人的。」","notes":[]},{"n":6,"t":"于是两个使女和她们的孩子前来下拜；","notes":[]},{"n":7,"t":"利亚和她的孩子也前来下拜；随后约瑟和拉结也前来下拜。","notes":[]},{"n":8,"t":"以扫说：「我所遇见的这些群畜是什么意思呢？」雅各说：「是要在我主面前蒙恩的。」","notes":[]},{"n":9,"t":"以扫说：「兄弟啊，我的已经够了，你的仍归你吧！」","notes":[]},{"n":10,"t":"雅各说：「不然，我若在你眼前蒙恩，就求你从我手里收下这礼物；因为我见了你的面，如同见了神的面，并且你容纳了我。","notes":[]},{"n":11,"t":"求你收下我带来给你的礼物；因为神恩待我，使我充足。」雅各再三地求他，他才收下了。","notes":[]},{"n":12,"t":"以扫说：「我们可以起身前往，我在你前头走。」","notes":[]},{"n":13,"t":"雅各对他说：「我主知道孩子们年幼娇嫩，牛羊也正在乳养的时候，若是催赶一天，群畜都必死了。","notes":[]},{"n":14,"t":"求我主在仆人前头走，我要量着在我面前群畜和孩子的力量慢慢地前行，直走到西珥我主那里。」","notes":[]},{"n":15,"t":"以扫说：「容我把跟随我的人留几个在你这里。」雅各说：「何必呢？只要在我主眼前蒙恩就是了。」","notes":[]},{"n":16,"t":"于是，以扫当日起行，回往西珥去了。","notes":[]},{"n":17,"t":"雅各就往疏割去，在那里为自己盖造房屋，又为牲畜搭棚；因此那地方名叫疏割。","notes":["就是棚的意思"]},{"n":18,"t":"雅各从巴旦·亚兰回来的时候，平平安安地到了迦南地的示剑城，在城东支搭帐棚，","notes":[]},{"n":19,"t":"就用一百块银子向示剑的父亲、哈抹的子孙买了支帐棚的那块地，","notes":[]},{"n":20,"t":"在那里筑了一座坛，起名叫伊利·伊罗伊·以色列。","notes":["就是神、以色列神的意思"]}]},"34":{"heading":"底拿受辱","verses":[{"n":1,"t":"利亚给雅各所生的女儿底拿出去，要见那地的女子们。","notes":[]},{"n":2,"t":"那地的主—希未人、哈抹的儿子示剑看见她，就拉住她，与她行淫，玷辱她。","notes":[]},{"n":3,"t":"示剑的心系恋雅各的女儿底拿，喜爱这女子，甜言蜜语地安慰她。","notes":[]},{"n":4,"t":"示剑对他父亲哈抹说：「求你为我聘这女子为妻。」","notes":[]},{"n":5,"t":"雅各听见示剑玷污了他的女儿底拿。那时他的儿子们正和群畜在田野，雅各就闭口不言，等他们回来。","notes":[]},{"n":6,"t":"示剑的父亲哈抹出来见雅各，要和他商议。","notes":[]},{"n":7,"t":"雅各的儿子们听见这事，就从田野回来，人人忿恨，十分恼怒；因示剑在以色列家做了丑事，与雅各的女儿行淫，这本是不该做的事。","notes":[]},{"n":8,"t":"哈抹和他们商议说：「我儿子示剑的心恋慕这女子，求你们将她给我的儿子为妻。","notes":[]},{"n":9,"t":"你们与我们彼此结亲；你们可以把女儿给我们，也可以娶我们的女儿。","notes":[]},{"n":10,"t":"你们与我们同住吧！这地都在你们面前，只管在此居住，做买卖，置产业。」","notes":[]},{"n":11,"t":"示剑对女儿的父亲和弟兄们说：「但愿我在你们眼前蒙恩，你们向我要什么，我必给你们。","notes":[]},{"n":12,"t":"任凭向我要多重的聘金和礼物，我必照你们所说的给你们；只要把女子给我为妻。」","notes":[]},{"n":13,"t":"雅各的儿子们因为示剑玷污了他们的妹子底拿，就用诡诈的话回答示剑和他父亲哈抹，","notes":[]},{"n":14,"t":"对他们说：「我们不能把我们的妹子给没有受割礼的人为妻，因为那是我们的羞辱。","notes":[]},{"n":15,"t":"惟有一件才可以应允：若你们所有的男丁都受割礼，和我们一样，","notes":[]},{"n":16,"t":"我们就把女儿给你们，也娶你们的女儿；我们便与你们同住，两下成为一样的人民。","notes":[]},{"n":17,"t":"倘若你们不听从我们受割礼，我们就带着妹子走了。」","notes":[]},{"n":18,"t":"哈抹和他的儿子示剑喜欢这话。","notes":[]},{"n":19,"t":"那少年人做这事并不迟延，因为他喜爱雅各的女儿；他在他父亲家中也是人最尊重的。","notes":[]},{"n":20,"t":"哈抹和他儿子示剑到本城的门口，对本城的人说：","notes":[]},{"n":21,"t":"「这些人与我们和睦，不如许他们在这地居住，做买卖；这地也宽阔，足可容下他们。我们可以娶他们的女儿为妻，也可以把我们的女儿嫁给他们。","notes":[]},{"n":22,"t":"惟有一件事我们必须做，他们才肯应允和我们同住，成为一样的人民：就是我们中间所有的男丁都要受割礼，和他们一样。","notes":[]},{"n":23,"t":"他们的群畜、货财，和一切的牲口岂不都归我们吗？只要依从他们，他们就与我们同住。」","notes":[]},{"n":24,"t":"凡从城门出入的人就都听从哈抹和他儿子示剑的话；于是凡从城门出入的男丁都受了割礼。","notes":[]},{"n":25,"t":"到第三天，众人正在疼痛的时候，雅各的两个儿子，就是底拿的哥哥西缅和利未，各拿刀剑，趁着众人想不到的时候来到城中，把一切男丁都杀了，","notes":[]},{"n":26,"t":"又用刀杀了哈抹和他儿子示剑，把底拿从示剑家里带出来就走了。","notes":[]},{"n":27,"t":"雅各的儿子们因为他们的妹子受了玷污，就来到被杀的人那里，掳掠那城，","notes":[]},{"n":28,"t":"夺了他们的羊群、牛群，和驴，并城里田间所有的；","notes":[]},{"n":29,"t":"又把他们一切货财、孩子、妇女，并各房中所有的，都掳掠去了。","notes":[]},{"n":30,"t":"雅各对西缅和利未说：「你们连累我，使我在这地的居民中，就是在迦南人和比利洗人中，有了臭名。我的人丁既然稀少，他们必聚集来击杀我，我和全家的人都必灭绝。」","notes":[]},{"n":31,"t":"他们说：「他岂可待我们的妹子如同妓女吗？」","notes":[]}]},"35":{"heading":"神在伯特利赐福雅各","verses":[{"n":1,"t":"神对雅各说：「起来！上伯特利去，住在那里；要在那里筑一座坛给神，就是你逃避你哥哥以扫的时候向你显现的那位。」","notes":[]},{"n":2,"t":"雅各就对他家中的人并一切与他同在的人说：「你们要除掉你们中间的外邦神，也要自洁，更换衣裳。","notes":[]},{"n":3,"t":"我们要起来，上伯特利去，在那里我要筑一座坛给神，就是在我遭难的日子应允我的祷告、在我行的路上保佑我的那位。」","notes":[]},{"n":4,"t":"他们就把外邦人的神像和他们耳朵上的环子交给雅各；雅各都藏在示剑那里的橡树底下。","notes":[]},{"n":5,"t":"他们便起行前往。神使那周围城邑的人都甚惊惧，就不追赶雅各的众子了。","notes":[]},{"n":6,"t":"于是雅各和一切与他同在的人到了迦南地的路斯，就是伯特利。","notes":[]},{"n":7,"t":"他在那里筑了一座坛，就给那地方起名叫伊勒·伯特利；因为他逃避他哥哥的时候，神在那里向他显现。","notes":["就是伯特利之神的意思"]},{"n":8,"t":"利百加的奶母底波拉死了，就葬在伯特利下边橡树底下；那棵树名叫亚伦·巴古。","notes":[]},{"n":9,"t":"雅各从巴旦·亚兰回来，神又向他显现，赐福与他，","notes":[]},{"n":10,"t":"且对他说：「你的名原是雅各，从今以后不要再叫雅各，要叫以色列。」这样，他就改名叫以色列。","notes":[]},{"n":11,"t":"神又对他说：「我是全能的神；你要生养众多，将来有一族和多国的民从你而生，又有君王从你而出。","notes":[]},{"n":12,"t":"我所赐给亚伯拉罕和以撒的地，我要赐给你与你的后裔。」","notes":[]},{"n":13,"t":"神就从那与雅各说话的地方升上去了。","notes":[]},{"n":14,"t":"雅各便在那里立了一根石柱，在柱子上奠酒，浇油。","notes":[]},{"n":15,"t":"雅各就给那地方起名叫伯特利。","notes":[]},{"n":16,"t":"他们从伯特利起行，离以法他还有一段路程，拉结临产甚是艰难。","notes":[],"heads":["拉结去世"]},{"n":17,"t":"正在艰难的时候，收生婆对她说：「不要怕，你又要得一个儿子了。」","notes":[]},{"n":18,"t":"她将近于死，灵魂要走的时候，就给她儿子起名叫便·俄尼；他父亲却给他起名叫便雅悯。","notes":[]},{"n":19,"t":"拉结死了，葬在以法他的路旁；以法他就是伯利恒。","notes":[]},{"n":20,"t":"雅各在她的坟上立了一统碑，就是拉结的墓碑，到今日还在。","notes":[]},{"n":21,"t":"以色列起行前往，在以得台那边支搭帐棚。","notes":[]},{"n":22,"t":"以色列住在那地的时候，吕便去与他父亲的妾辟拉同寝，以色列也听见了。雅各共有十二个儿子。","notes":[],"heads":["雅各的儿子们"]},{"n":23,"t":"利亚所生的是雅各的长子吕便，还有西缅、利未、犹大、以萨迦、西布伦。","notes":[]},{"n":24,"t":"拉结所生的是约瑟、便雅悯。","notes":[]},{"n":25,"t":"拉结的使女辟拉所生的是但、拿弗他利。","notes":[]},{"n":26,"t":"利亚的使女悉帕所生的是迦得、亚设。这是雅各在巴旦·亚兰所生的儿子。","notes":[]},{"n":27,"t":"雅各来到他父亲以撒那里，到了基列·亚巴的幔利，乃是亚伯拉罕和以撒寄居的地方；基列·亚巴就是希伯仑。","notes":[],"heads":["以撒去世"]},{"n":28,"t":"以撒共活了一百八十岁。","notes":[]},{"n":29,"t":"以撒年纪老迈，日子满足，气绝而死，归到他列祖那里。他两个儿子以扫、雅各把他埋葬了。","notes":["原文是本民"]}]},"36":{"heading":"以扫的子孙","verses":[{"n":1,"t":"以扫就是以东，他的后代记在下面。","notes":[]},{"n":2,"t":"以扫娶迦南的女子为妻，就是赫人以伦的女儿亚大和希未人祭便的孙女、亚拿的女儿阿何利巴玛，","notes":[]},{"n":3,"t":"又娶了以实玛利的女儿、尼拜约的妹子巴实抹。","notes":[]},{"n":4,"t":"亚大给以扫生了以利法；巴实抹生了流珥；","notes":[]},{"n":5,"t":"阿何利巴玛生了耶乌施、雅兰、可拉。这都是以扫的儿子，是在迦南地生的。","notes":[]},{"n":6,"t":"以扫带着他的妻子、儿女，与家中一切的人口，并他的牛羊、牲畜，和一切货财，就是他在迦南地所得的，往别处去，离了他兄弟雅各。","notes":[]},{"n":7,"t":"因为二人的财物群畜甚多，寄居的地方容不下他们，所以不能同居。","notes":[]},{"n":8,"t":"于是以扫住在西珥山里；以扫就是以东。","notes":[]},{"n":9,"t":"以扫是西珥山里以东人的始祖，他的后代记在下面。","notes":[]},{"n":10,"t":"以扫众子的名字如下。以扫的妻子亚大生以利法；以扫的妻子巴实抹生流珥。","notes":[]},{"n":11,"t":"以利法的儿子是提幔、阿抹、洗玻、迦坦、基纳斯。","notes":[]},{"n":12,"t":"亭纳是以扫儿子以利法的妾；她给以利法生了亚玛力。这是以扫的妻子亚大的子孙。","notes":[]},{"n":13,"t":"流珥的儿子是拿哈、谢拉、沙玛、米撒。这是以扫妻子巴实抹的子孙。","notes":[]},{"n":14,"t":"以扫的妻子阿何利巴玛是祭便的孙女，亚拿的女儿；她给以扫生了耶乌施、雅兰、可拉。","notes":[]},{"n":15,"t":"以扫子孙中作族长的记在下面。以扫的长子以利法的子孙中，有提幔族长、阿抹族长、洗玻族长、基纳斯族长、","notes":[]},{"n":16,"t":"可拉族长、迦坦族长、亚玛力族长。这是在以东地从以利法所出的族长，都是亚大的子孙。","notes":[]},{"n":17,"t":"以扫的儿子流珥的子孙中，有拿哈族长、谢拉族长、沙玛族长、米撒族长。这是在以东地从流珥所出的族长，都是以扫妻子巴实抹的子孙。","notes":[]},{"n":18,"t":"以扫的妻子阿何利巴玛的子孙中，有耶乌施族长、雅兰族长、可拉族长。这是从以扫妻子，亚拿的女儿，阿何利巴玛子孙中所出的族长。","notes":[]},{"n":19,"t":"以上的族长都是以扫的子孙；以扫就是以东。","notes":[]},{"n":20,"t":"那地原有的居民—何利人西珥的子孙记在下面：就是罗坍、朔巴、祭便、亚拿、","notes":[],"heads":["西珥的子孙"]},{"n":21,"t":"底顺、以察、底珊。这是从以东地的何利人西珥子孙中所出的族长。","notes":[]},{"n":22,"t":"罗坍的儿子是何利、希幔；罗坍的妹子是亭纳。","notes":[]},{"n":23,"t":"朔巴的儿子是亚勒文、玛拿辖、以巴录、示玻、阿南。","notes":[]},{"n":24,"t":"祭便的儿子是亚雅、亚拿（当时在旷野放他父亲祭便的驴，遇着温泉的，就是这亚拿）。","notes":[]},{"n":25,"t":"亚拿的儿子是底顺；亚拿的女儿是阿何利巴玛。","notes":[]},{"n":26,"t":"底顺的儿子是欣但、伊是班、益兰、基兰。","notes":[]},{"n":27,"t":"以察的儿子是辟罕、撒番、亚干。","notes":[]},{"n":28,"t":"底珊的儿子是乌斯、亚兰。","notes":[]},{"n":29,"t":"从何利人所出的族长记在下面：就是罗坍族长、朔巴族长、祭便族长、亚拿族长、","notes":[]},{"n":30,"t":"底顺族长、以察族长、底珊族长。这是从何利人所出的族长，都在西珥地，按着宗族作族长。","notes":[]},{"n":31,"t":"以色列人未有君王治理以先，在以东地作王的记在下面。","notes":[],"heads":["以东诸王"]},{"n":32,"t":"比珥的儿子比拉在以东作王，他的京城名叫亭哈巴。","notes":[]},{"n":33,"t":"比拉死了，波斯拉人谢拉的儿子约巴接续他作王。","notes":[]},{"n":34,"t":"约巴死了，提幔地的人户珊接续他作王。","notes":[]},{"n":35,"t":"户珊死了，比达的儿子哈达接续他作王；这哈达就是在摩押地杀败米甸人的，他的京城名叫亚未得。","notes":[]},{"n":36,"t":"哈达死了，玛士利加人桑拉接续他作王。","notes":[]},{"n":37,"t":"桑拉死了，大河边的利河伯人扫罗接续他作王。","notes":[]},{"n":38,"t":"扫罗死了，亚革波的儿子巴勒·哈南接续他作王。","notes":[]},{"n":39,"t":"亚革波的儿子巴勒·哈南死了，哈达接续他作王，他的京城名叫巴乌；他的妻子名叫米希她别，是米·萨合的孙女，玛特列的女儿。","notes":[]},{"n":40,"t":"从以扫所出的族长，按着他们的宗族、住处、名字记在下面：就是亭纳族长、亚勒瓦族长、耶帖族长、","notes":[]},{"n":41,"t":"阿何利巴玛族长、以拉族长、比嫩族长、","notes":[]},{"n":42,"t":"基纳斯族长、提幔族长、米比萨族长、","notes":[]},{"n":43,"t":"玛基叠族长、以兰族长。这是以东人在所得为业的地上，按着他们的住处。（所有的族长都是以东人的始祖以扫的后代。）","notes":[]}]},"37":{"heading":"约瑟和他的兄弟","verses":[{"n":1,"t":"雅各住在迦南地，就是他父亲寄居的地。","notes":[]},{"n":2,"t":"雅各的记略如下。约瑟十七岁与他哥哥们一同牧羊。他是个童子，与他父亲的妾辟拉、悉帕的儿子们常在一处。约瑟将他哥哥们的恶行报给他们的父亲。","notes":[]},{"n":3,"t":"以色列原来爱约瑟过于爱他的众子，因为约瑟是他年老生的；他给约瑟做了一件彩衣。","notes":[]},{"n":4,"t":"约瑟的哥哥们见父亲爱约瑟过于爱他们，就恨约瑟，不与他说和睦的话。","notes":[]},{"n":5,"t":"约瑟做了一梦，告诉他哥哥们，他们就越发恨他。","notes":[]},{"n":6,"t":"约瑟对他们说：「请听我所做的梦：","notes":[]},{"n":7,"t":"我们在田里捆禾稼，我的捆起来站着，你们的捆来围着我的捆下拜。」","notes":[]},{"n":8,"t":"他的哥哥们回答说：「难道你真要作我们的王吗？难道你真要管辖我们吗？」他们就因为他的梦和他的话越发恨他。","notes":[]},{"n":9,"t":"后来他又做了一梦，也告诉他的哥哥们说：「看哪，我又做了一梦，梦见太阳、月亮，与十一个星向我下拜。」","notes":[]},{"n":10,"t":"约瑟将这梦告诉他父亲和他哥哥们，他父亲就责备他说：「你做的这是什么梦！难道我和你母亲、你弟兄果然要来俯伏在地，向你下拜吗？」","notes":[]},{"n":11,"t":"他哥哥们都嫉妒他，他父亲却把这话存在心里。","notes":[]},{"n":12,"t":"约瑟的哥哥们往示剑去放他们父亲的羊。","notes":[],"heads":["约瑟被卖到埃及"]},{"n":13,"t":"以色列对约瑟说：「你哥哥们不是在示剑放羊吗？你来，我要打发你往他们那里去。」约瑟说：「我在这里。」","notes":[]},{"n":14,"t":"以色列说：「你去看看你哥哥们平安不平安，群羊平安不平安，就回来报信给我」；于是打发他出希伯仑谷，他就往示剑去了。","notes":[]},{"n":15,"t":"有人遇见他在田野走迷了路，就问他说：「你找什么？」","notes":[]},{"n":16,"t":"他说：「我找我的哥哥们，求你告诉我，他们在何处放羊。」","notes":[]},{"n":17,"t":"那人说：「他们已经走了，我听见他们说要往多坍去。」约瑟就去追赶他哥哥们，遇见他们在多坍。","notes":[]},{"n":18,"t":"他们远远地看见他，趁他还没有走到跟前，大家就同谋要害死他，","notes":[]},{"n":19,"t":"彼此说：「你看！那做梦的来了。","notes":[]},{"n":20,"t":"来吧！我们将他杀了，丢在一个坑里，就说有恶兽把他吃了。我们且看他的梦将来怎么样。」","notes":[]},{"n":21,"t":"吕便听见了，要救他脱离他们的手，说：「我们不可害他的性命」；","notes":[]},{"n":22,"t":"又说：「不可流他的血，可以把他丢在这野地的坑里，不可下手害他。」吕便的意思是要救他脱离他们的手，把他归还他的父亲。","notes":[]},{"n":23,"t":"约瑟到了他哥哥们那里，他们就剥了他的外衣，就是他穿的那件彩衣，","notes":[]},{"n":24,"t":"把他丢在坑里；那坑是空的，里头没有水。","notes":[]},{"n":25,"t":"他们坐下吃饭，举目观看，见有一伙米甸的以实玛利人从基列来，用骆驼驮着香料、乳香、没药，要带下埃及去。","notes":[]},{"n":26,"t":"犹大对众弟兄说：「我们杀我们的兄弟，藏了他的血有什么益处呢？","notes":[]},{"n":27,"t":"我们不如将他卖给以实玛利人，不可下手害他；因为他是我们的兄弟，我们的骨肉。」众弟兄就听从了他。","notes":[]},{"n":28,"t":"有些米甸的商人从那里经过，哥哥们就把约瑟从坑里拉上来，讲定二十舍客勒银子，把约瑟卖给以实玛利人。他们就把约瑟带到埃及去了。","notes":[]},{"n":29,"t":"吕便回到坑边，见约瑟不在坑里，就撕裂衣服，","notes":[]},{"n":30,"t":"回到兄弟们那里，说：「童子没有了。我往哪里去才好呢？」","notes":[]},{"n":31,"t":"他们宰了一只公山羊，把约瑟的那件彩衣染了血，","notes":[]},{"n":32,"t":"打发人送到他们的父亲那里，说：「我们捡了这个；请认一认是你儿子的外衣不是？」","notes":[]},{"n":33,"t":"他认得，就说：「这是我儿子的外衣。有恶兽把他吃了，约瑟被撕碎了！撕碎了！」","notes":[]},{"n":34,"t":"雅各便撕裂衣服，腰间围上麻布，为他儿子悲哀了多日。","notes":[]},{"n":35,"t":"他的儿女都起来安慰他，他却不肯受安慰，说：「我必悲哀着下阴间，到我儿子那里。」约瑟的父亲就为他哀哭。","notes":[]},{"n":36,"t":"米甸人带约瑟到埃及，把他卖给法老的内臣—护卫长波提乏。","notes":[]}]},"38":{"heading":"犹大和她玛","verses":[{"n":1,"t":"那时，犹大离开他弟兄下去，到一个亚杜兰人名叫希拉的家里去。","notes":[]},{"n":2,"t":"犹大在那里看见一个迦南人名叫书亚的女儿，就娶她为妻，与她同房，","notes":[]},{"n":3,"t":"她就怀孕生了儿子，犹大给他起名叫珥。","notes":[]},{"n":4,"t":"她又怀孕生了儿子，母亲给他起名叫俄南。","notes":[]},{"n":5,"t":"她复又生了儿子，给他起名叫示拉。她生示拉的时候，犹大正在基悉。","notes":[]},{"n":6,"t":"犹大为长子珥娶妻，名叫她玛。","notes":[]},{"n":7,"t":"犹大的长子珥在耶和华眼中看为恶，耶和华就叫他死了。","notes":[]},{"n":8,"t":"犹大对俄南说：「你当与你哥哥的妻子同房，向她尽你为弟的本分，为你哥哥生子立后。」","notes":[]},{"n":9,"t":"俄南知道生子不归自己，所以同房的时候便遗在地，免得给他哥哥留后。","notes":[]},{"n":10,"t":"俄南所做的在耶和华眼中看为恶，耶和华也就叫他死了。","notes":[]},{"n":11,"t":"犹大心里说：「恐怕示拉也死，像他两个哥哥一样」，就对他儿妇她玛说：「你去，在你父亲家里守寡，等我儿子示拉长大。」她玛就回去，住在她父亲家里。","notes":[]},{"n":12,"t":"过了许久，犹大的妻子书亚的女儿死了。犹大得了安慰，就和他朋友亚杜兰人希拉上亭拿去，到他剪羊毛的人那里。","notes":[]},{"n":13,"t":"有人告诉她玛说：「你的公公上亭拿剪羊毛去了。」","notes":[]},{"n":14,"t":"她玛见示拉已经长大，还没有娶她为妻，就脱了她作寡妇的衣裳，用帕子蒙着脸，又遮住身体，坐在亭拿路上的伊拿印城门口。","notes":[]},{"n":15,"t":"犹大看见她，以为是妓女，因为她蒙着脸。","notes":[]},{"n":16,"t":"犹大就转到她那里去，说：「来吧！让我与你同寝。」他原不知道是他的儿妇。她玛说：「你要与我同寝，把什么给我呢？」","notes":[]},{"n":17,"t":"犹大说：「我从羊群里取一只山羊羔，打发人送来给你。」她玛说：「在未送以先，你愿意给我一个当头吗？」","notes":[]},{"n":18,"t":"他说：「我给你什么当头呢？」她玛说：「你的印、你的带子，和你手里的杖。」犹大就给了她，与她同寝，她就从犹大怀了孕。","notes":[]},{"n":19,"t":"她玛起来走了，除去帕子，仍旧穿上作寡妇的衣裳。","notes":[]},{"n":20,"t":"犹大托他朋友亚杜兰人送一只山羊羔去，要从那女人手里取回当头来，却找不着她，","notes":[]},{"n":21,"t":"就问那地方的人说：「伊拿印路旁的妓女在哪里？」他们说：「这里并没有妓女。」","notes":[]},{"n":22,"t":"他回去见犹大说：「我没有找着她，并且那地方的人说：『这里没有妓女。』」","notes":[]},{"n":23,"t":"犹大说：「我把这山羊羔送去了，你竟找不着她。任凭她拿去吧，免得我们被羞辱。」","notes":[]},{"n":24,"t":"约过了三个月，有人告诉犹大说：「你的儿妇她玛作了妓女，且因行淫有了身孕。」犹大说：「拉出她来，把她烧了！」","notes":[]},{"n":25,"t":"她玛被拉出来的时候便打发人去见她公公，对他说：「这些东西是谁的，我就是从谁怀的孕。请你认一认，这印和带子并杖都是谁的？」","notes":[]},{"n":26,"t":"犹大承认说：「她比我更有义，因为我没有将她给我的儿子示拉。」从此犹大不再与她同寝了。","notes":[]},{"n":27,"t":"她玛将要生产，不料她腹里是一对双生。","notes":[]},{"n":28,"t":"到生产的时候，一个孩子伸出一只手来；收生婆拿红线拴在他手上，说：「这是头生的。」","notes":[]},{"n":29,"t":"随后这孩子把手收回去，他哥哥生出来了；收生婆说：「你为什么抢着来呢？」因此给他起名叫法勒斯。","notes":[]},{"n":30,"t":"后来，他兄弟那手上有红线的也生出来，就给他起名叫谢拉。","notes":[]}]},"39":{"heading":"约瑟和波提乏之妻","verses":[{"n":1,"t":"约瑟被带下埃及去。有一个埃及人，是法老的内臣—护卫长波提乏，从那些带下他来的以实玛利人手下买了他去。","notes":[]},{"n":2,"t":"约瑟住在他主人埃及人的家中，耶和华与他同在，他就百事顺利。","notes":[]},{"n":3,"t":"他主人见耶和华与他同在，又见耶和华使他手里所办的尽都顺利，","notes":[]},{"n":4,"t":"约瑟就在主人眼前蒙恩，伺候他主人，并且主人派他管理家务，把一切所有的都交在他手里。","notes":[]},{"n":5,"t":"自从主人派约瑟管理家务和他一切所有的，耶和华就因约瑟的缘故赐福与那埃及人的家；凡家里和田间一切所有的都蒙耶和华赐福。","notes":[]},{"n":6,"t":"波提乏将一切所有的都交在约瑟的手中，除了自己所吃的饭，别的事一概不知。约瑟原来秀雅俊美。","notes":[]},{"n":7,"t":"这事以后，约瑟主人的妻以目送情给约瑟，说：「你与我同寝吧！」","notes":[]},{"n":8,"t":"约瑟不从，对他主人的妻说：「看哪，一切家务，我主人都不知道；他把所有的都交在我手里。","notes":[]},{"n":9,"t":"在这家里没有比我大的；并且他没有留下一样不交给我，只留下了你，因为你是他的妻子。我怎能作这大恶，得罪神呢？」","notes":[]},{"n":10,"t":"后来她天天和约瑟说，约瑟却不听从她，不与她同寝，也不和她在一处。","notes":[]},{"n":11,"t":"有一天，约瑟进屋里去办事，家中人没有一个在那屋里，","notes":[]},{"n":12,"t":"妇人就拉住他的衣裳，说：「你与我同寝吧！」约瑟把衣裳丢在妇人手里，跑到外边去了。","notes":[]},{"n":13,"t":"妇人看见约瑟把衣裳丢在她手里跑出去了，","notes":[]},{"n":14,"t":"就叫了家里的人来，对他们说：「你们看！他带了一个希伯来人进入我们家里，要戏弄我们。他到我这里来，要与我同寝，我就大声喊叫。","notes":[]},{"n":15,"t":"他听见我放声喊起来，就把衣裳丢在我这里，跑到外边去了。」","notes":[]},{"n":16,"t":"妇人把约瑟的衣裳放在自己那里，等着他主人回家，","notes":[]},{"n":17,"t":"就对他如此如此说：「你所带到我们这里的那希伯来仆人进来要戏弄我，","notes":[]},{"n":18,"t":"我放声喊起来，他就把衣裳丢在我这里，跑出去了。」","notes":[]},{"n":19,"t":"约瑟的主人听见他妻子对他所说的话，说「你的仆人如此如此待我」，他就生气，","notes":[]},{"n":20,"t":"把约瑟下在监里，就是王的囚犯被囚的地方。于是约瑟在那里坐监。","notes":[]},{"n":21,"t":"但耶和华与约瑟同在，向他施恩，使他在司狱的眼前蒙恩。","notes":[]},{"n":22,"t":"司狱就把监里所有的囚犯都交在约瑟的手下；他们在那里所办的事都是经他的手。","notes":[]},{"n":23,"t":"凡在约瑟手下的事，司狱一概不察，因为耶和华与约瑟同在；耶和华使他所做的尽都顺利。","notes":[]}]},"40":{"heading":"约瑟为囚犯解梦","verses":[{"n":1,"t":"这事以后，埃及王的酒政和膳长得罪了他们的主—埃及王，","notes":[]},{"n":2,"t":"法老就恼怒酒政和膳长这二臣，","notes":[]},{"n":3,"t":"把他们下在护卫长府内的监里，就是约瑟被囚的地方。","notes":[]},{"n":4,"t":"护卫长把他们交给约瑟，约瑟便伺候他们；他们有些日子在监里。","notes":[]},{"n":5,"t":"被囚在监之埃及王的酒政和膳长二人同夜各做一梦，各梦都有讲解。","notes":[]},{"n":6,"t":"到了早晨，约瑟进到他们那里，见他们有愁闷的样子。","notes":[]},{"n":7,"t":"他便问法老的二臣，就是与他同囚在他主人府里的，说：「你们今日为什么面带愁容呢？」","notes":[]},{"n":8,"t":"他们对他说：「我们各人做了一梦，没有人能解。」约瑟说：「解梦不是出于神吗？请你们将梦告诉我。」","notes":[]},{"n":9,"t":"酒政便将他的梦告诉约瑟说：「我梦见在我面前有一棵葡萄树，","notes":[]},{"n":10,"t":"树上有三根枝子，好像发了芽，开了花，上头的葡萄都成熟了。","notes":[]},{"n":11,"t":"法老的杯在我手中，我就拿葡萄挤在法老的杯里，将杯递在他手中。」","notes":[]},{"n":12,"t":"约瑟对他说：「你所做的梦是这样解：三根枝子就是三天；","notes":[]},{"n":13,"t":"三天之内，法老必提你出监，叫你官复原职，你仍要递杯在法老的手中，和先前作他的酒政一样。","notes":[]},{"n":14,"t":"但你得好处的时候，求你记念我，施恩与我，在法老面前提说我，救我出这监牢。","notes":[]},{"n":15,"t":"我实在是从希伯来人之地被拐来的；我在这里也没有做过什么，叫他们把我下在监里。」","notes":[]},{"n":16,"t":"膳长见梦解得好，就对约瑟说：「我在梦中见我头上顶着三筐白饼；","notes":[]},{"n":17,"t":"极上的筐子里有为法老烤的各样食物，有飞鸟来吃我头上筐子里的食物。」","notes":[]},{"n":18,"t":"约瑟说：「你的梦是这样解：三个筐子就是三天；","notes":[]},{"n":19,"t":"三天之内，法老必斩断你的头，把你挂在木头上，必有飞鸟来吃你身上的肉。」","notes":[]},{"n":20,"t":"到了第三天，是法老的生日，他为众臣仆设摆筵席，把酒政和膳长提出监来，","notes":[]},{"n":21,"t":"使酒政官复原职，他仍旧递杯在法老手中；","notes":[]},{"n":22,"t":"但把膳长挂起来，正如约瑟向他们所解的话。","notes":[]},{"n":23,"t":"酒政却不记念约瑟，竟忘了他。","notes":[]}]},"41":{"heading":"约瑟为法老解梦","verses":[{"n":1,"t":"过了两年，法老做梦，梦见自己站在河边，","notes":[]},{"n":2,"t":"有七只母牛从河里上来，又美好又肥壮，在芦荻中吃草。","notes":[]},{"n":3,"t":"随后又有七只母牛从河里上来，又丑陋又干瘦，与那七只母牛一同站在河边。","notes":[]},{"n":4,"t":"这又丑陋又干瘦的七只母牛吃尽了那又美好又肥壮的七只母牛。法老就醒了。","notes":[]},{"n":5,"t":"他又睡着，第二回做梦，梦见一棵麦子长了七个穗子，又肥大又佳美，","notes":[]},{"n":6,"t":"随后又长了七个穗子，又细弱又被东风吹焦了。","notes":[]},{"n":7,"t":"这细弱的穗子吞了那七个又肥大又饱满的穗子。法老醒了，不料是个梦。","notes":[]},{"n":8,"t":"到了早晨，法老心里不安，就差人召了埃及所有的术士和博士来；法老就把所做的梦告诉他们，却没有人能给法老圆解。","notes":[]},{"n":9,"t":"那时酒政对法老说：「我今日想起我的罪来。","notes":[]},{"n":10,"t":"从前法老恼怒臣仆，把我和膳长下在护卫长府内的监里。","notes":[]},{"n":11,"t":"我们二人同夜各做一梦，各梦都有讲解。","notes":[]},{"n":12,"t":"在那里同着我们有一个希伯来的少年人，是护卫长的仆人，我们告诉他，他就把我们的梦圆解，是按着各人的梦圆解的。","notes":[]},{"n":13,"t":"后来正如他给我们圆解的成就了：我官复原职，膳长被挂起来了。」","notes":[]},{"n":14,"t":"法老遂即差人去召约瑟，他们便急忙带他出监，他就剃头，刮脸，换衣裳，进到法老面前。","notes":[]},{"n":15,"t":"法老对约瑟说：「我做了一梦，没有人能解；我听见人说，你听了梦就能解。」","notes":[]},{"n":16,"t":"约瑟回答法老说：「这不在乎我，神必将平安的话回答法老。」","notes":[]},{"n":17,"t":"法老对约瑟说：「我梦见我站在河边，","notes":[]},{"n":18,"t":"有七只母牛从河里上来，又肥壮又美好，在芦荻中吃草。","notes":[]},{"n":19,"t":"随后又有七只母牛上来，又软弱又丑陋又干瘦，在埃及遍地，我没有见过这样不好的。","notes":[]},{"n":20,"t":"这又干瘦又丑陋的母牛吃尽了那以先的七只肥母牛，","notes":[]},{"n":21,"t":"吃了以后却看不出是吃了，那丑陋的样子仍旧和先前一样。我就醒了。","notes":[]},{"n":22,"t":"我又梦见一棵麦子，长了七个穗子，又饱满又佳美，","notes":[]},{"n":23,"t":"随后又长了七个穗子，枯槁细弱，被东风吹焦了。","notes":[]},{"n":24,"t":"这些细弱的穗子吞了那七个佳美的穗子。我将这梦告诉了术士，却没有人能给我解说。」","notes":[]},{"n":25,"t":"约瑟对法老说：「法老的梦乃是一个。神已将所要做的事指示法老了。","notes":[]},{"n":26,"t":"七只好母牛是七年，七个好穗子也是七年；这梦乃是一个。","notes":[]},{"n":27,"t":"那随后上来的七只又干瘦又丑陋的母牛是七年，那七个虚空、被东风吹焦的穗子也是七年，都是七个荒年。","notes":[]},{"n":28,"t":"这就是我对法老所说，神已将所要做的事显明给法老了。","notes":[]},{"n":29,"t":"埃及遍地必来七个大丰年，","notes":[]},{"n":30,"t":"随后又要来七个荒年，甚至在埃及地都忘了先前的丰收，全地必被饥荒所灭。","notes":[]},{"n":31,"t":"因那以后的饥荒甚大，便不觉得先前的丰收了。","notes":[]},{"n":32,"t":"至于法老两回做梦，是因神命定这事，而且必速速成就。","notes":[]},{"n":33,"t":"所以，法老当拣选一个有聪明有智慧的人，派他治理埃及地。","notes":[]},{"n":34,"t":"法老当这样行，又派官员管理这地。当七个丰年的时候，征收埃及地的五分之一，","notes":[]},{"n":35,"t":"叫他们把将来丰年一切的粮食聚敛起来，积蓄五谷，收存在各城里做食物，归于法老的手下。","notes":[]},{"n":36,"t":"所积蓄的粮食可以防备埃及地将来的七个荒年，免得这地被饥荒所灭。」","notes":[]},{"n":37,"t":"法老和他一切臣仆都以这事为妙。","notes":[],"heads":["约瑟被立为埃及的宰相"]},{"n":38,"t":"法老对臣仆说：「像这样的人，有神的灵在他里头，我们岂能找得着呢？」","notes":[]},{"n":39,"t":"法老对约瑟说：「神既将这事都指示你，可见没有人像你这样有聪明有智慧。","notes":[]},{"n":40,"t":"你可以掌管我的家；我的民都必听从你的话。惟独在宝座上我比你大。」","notes":[]},{"n":41,"t":"法老又对约瑟说：「我派你治理埃及全地。」","notes":[]},{"n":42,"t":"法老就摘下手上打印的戒指，戴在约瑟的手上，给他穿上细麻衣，把金链戴在他的颈项上，","notes":[]},{"n":43,"t":"又叫约瑟坐他的副车，喝道的在前呼叫说：「跪下。」这样，法老派他治理埃及全地。","notes":[]},{"n":44,"t":"法老对约瑟说：「我是法老，在埃及全地，若没有你的命令，不许人擅自办事。」","notes":["原文是动手动脚"]},{"n":45,"t":"法老赐名给约瑟，叫撒发那忒·巴内亚，又将安城的祭司波提非拉的女儿亚西纳给他为妻。约瑟就出去巡行埃及地。","notes":[]},{"n":46,"t":"约瑟见埃及王法老的时候年三十岁。他从法老面前出去，遍行埃及全地。","notes":[]},{"n":47,"t":"七个丰年之内，地的出产极丰极盛，","notes":["原文是一把一把的"]},{"n":48,"t":"约瑟聚敛埃及地七个丰年一切的粮食，把粮食积存在各城里；各城周围田地的粮食都积存在本城里。","notes":[]},{"n":49,"t":"约瑟积蓄五谷甚多，如同海边的沙，无法计算，因为谷不可胜数。","notes":[]},{"n":50,"t":"荒年未到以前，安城的祭司波提非拉的女儿亚西纳给约瑟生了两个儿子。","notes":[]},{"n":51,"t":"约瑟给长子起名叫玛拿西，因为他说：「神使我忘了一切的困苦和我父的全家。」","notes":["就是使之忘了的意思"]},{"n":52,"t":"他给次子起名叫以法莲，因为他说：「神使我在受苦的地方昌盛。」","notes":["就是使之昌盛的意思"]},{"n":53,"t":"埃及地的七个丰年一完，","notes":[]},{"n":54,"t":"七个荒年就来了。正如约瑟所说的，各地都有饥荒；惟独埃及全地有粮食。","notes":[]},{"n":55,"t":"及至埃及全地有了饥荒，众民向法老哀求粮食，法老对他们说：「你们往约瑟那里去，凡他所说的，你们都要做。」","notes":[]},{"n":56,"t":"当时饥荒遍满天下，约瑟开了各处的仓，粜粮给埃及人；在埃及地饥荒甚大。","notes":[]},{"n":57,"t":"各地的人都往埃及去，到约瑟那里籴粮，因为天下的饥荒甚大。","notes":[]}]},"42":{"heading":"约瑟的哥哥们往埃及买粮","verses":[{"n":1,"t":"雅各见埃及有粮，就对儿子们说：「你们为什么彼此观望呢？","notes":[]},{"n":2,"t":"我听见埃及有粮，你们可以下去，从那里为我们籴些来，使我们可以存活，不至于死。」","notes":[]},{"n":3,"t":"于是，约瑟的十个哥哥都下埃及籴粮去了。","notes":[]},{"n":4,"t":"但约瑟的兄弟便雅悯，雅各没有打发他和哥哥们同去，因为雅各说：「恐怕他遭害。」","notes":[]},{"n":5,"t":"来籴粮的人中有以色列的儿子们，因为迦南地也有饥荒。","notes":[]},{"n":6,"t":"当时治理埃及地的是约瑟；粜粮给那地众民的就是他。约瑟的哥哥们来了，脸伏于地，向他下拜。","notes":[]},{"n":7,"t":"约瑟看见他哥哥们，就认得他们，却装作生人，向他们说些严厉话，问他们说：「你们从哪里来？」他们说：「我们从迦南地来籴粮。」","notes":[]},{"n":8,"t":"约瑟认得他哥哥们，他们却不认得他。","notes":[]},{"n":9,"t":"约瑟想起从前所做的那两个梦，就对他们说：「你们是奸细，来窥探这地的虚实。」","notes":[]},{"n":10,"t":"他们对他说：「我主啊，不是的。仆人们是籴粮来的。","notes":[]},{"n":11,"t":"我们都是一个人的儿子，是诚实人；仆人们并不是奸细。」","notes":[]},{"n":12,"t":"约瑟说：「不然，你们必是窥探这地的虚实来的。」","notes":[]},{"n":13,"t":"他们说：「仆人们本是弟兄十二人，是迦南地一个人的儿子，顶小的现今在我们的父亲那里，有一个没有了。」","notes":[]},{"n":14,"t":"约瑟说：「我才说你们是奸细，这话实在不错。","notes":[]},{"n":15,"t":"我指着法老的性命起誓，若是你们的小兄弟不到这里来，你们就不得出这地方，从此就可以把你们证验出来了。","notes":[]},{"n":16,"t":"须要打发你们中间一个人去，把你们的兄弟带来。至于你们，都要囚在这里，好证验你们的话真不真，若不真，我指着法老的性命起誓，你们一定是奸细。」","notes":[]},{"n":17,"t":"于是约瑟把他们都下在监里三天。","notes":[]},{"n":18,"t":"到第三天，约瑟对他们说：「我是敬畏神的；你们照我的话行就可以存活。","notes":[]},{"n":19,"t":"你们如果是诚实人，可以留你们中间的一个人囚在监里，但你们可以带着粮食回去，救你们家里的饥荒。","notes":[]},{"n":20,"t":"把你们的小兄弟带到我这里来，如此，你们的话便有证据，你们也不至于死。」他们就照样而行。","notes":[]},{"n":21,"t":"他们彼此说：「我们在兄弟身上实在有罪。他哀求我们的时候，我们见他心里的愁苦，却不肯听，所以这场苦难临到我们身上。」","notes":[]},{"n":22,"t":"吕便说：「我岂不是对你们说过，不可伤害那孩子吗？只是你们不肯听，所以流他血的罪向我们追讨。」","notes":[]},{"n":23,"t":"他们不知道约瑟听得出来，因为在他们中间用通事传话。","notes":[]},{"n":24,"t":"约瑟转身退去，哭了一场，又回来对他们说话，就从他们中间挑出西缅来，在他们眼前把他捆绑。","notes":[]},{"n":25,"t":"约瑟吩咐人把粮食装满他们的器具，把各人的银子归还在各人的口袋里，又给他们路上用的食物，人就照他的话办了。","notes":[],"heads":["约瑟的哥哥们回迦南地"]},{"n":26,"t":"他们就把粮食驮在驴上，离开那里去了。","notes":[]},{"n":27,"t":"到了住宿的地方，他们中间有一个人打开口袋，要拿料喂驴，才看见自己的银子仍在口袋里，","notes":[]},{"n":28,"t":"就对弟兄们说：「我的银子归还了，看哪，仍在我口袋里！」他们就提心吊胆，战战兢兢地彼此说：「这是神向我们做什么呢？」","notes":[]},{"n":29,"t":"他们来到迦南地、他们的父亲雅各那里，将所遭遇的事都告诉他，说：","notes":[]},{"n":30,"t":"「那地的主对我们说严厉的话，把我们当作窥探那地的奸细。","notes":[]},{"n":31,"t":"我们对他说：『我们是诚实人，并不是奸细。","notes":[]},{"n":32,"t":"我们本是弟兄十二人，都是一个父亲的儿子，有一个没有了，顶小的如今同我们的父亲在迦南地。』","notes":[]},{"n":33,"t":"那地的主对我们说：『若要我知道你们是诚实人，可以留下你们中间的一个人在我这里，你们可以带着粮食回去，救你们家里的饥荒。","notes":[]},{"n":34,"t":"把你们的小兄弟带到我这里来，我便知道你们不是奸细，乃是诚实人。这样，我就把你们的弟兄交给你们，你们也可以在这地做买卖。』」","notes":[]},{"n":35,"t":"后来他们倒口袋，不料，各人的银包都在口袋里；他们和父亲看见银包就都害怕。","notes":[]},{"n":36,"t":"他们的父亲雅各对他们说：「你们使我丧失我的儿子：约瑟没有了，西缅也没有了，你们又要将便雅悯带去；这些事都归到我身上了。」","notes":[]},{"n":37,"t":"吕便对他父亲说：「我若不带他回来交给你，你可以杀我的两个儿子。只管把他交在我手里，我必带他回来交给你。」","notes":[]},{"n":38,"t":"雅各说：「我的儿子不可与你们一同下去；他哥哥死了，只剩下他，他若在你们所行的路上遭害，那便是你们使我白发苍苍、悲悲惨惨地下阴间去了。」","notes":[]}]},"43":{"heading":"约瑟的哥哥们带便雅悯到埃及","verses":[{"n":1,"t":"那地的饥荒甚大。","notes":[]},{"n":2,"t":"他们从埃及带来的粮食吃尽了，他们的父亲就对他们说：「你们再去给我籴些粮来。」","notes":[]},{"n":3,"t":"犹大对他说：「那人谆谆地告诫我们说：『你们的兄弟若不与你们同来，你们就不得见我的面。』","notes":[]},{"n":4,"t":"你若打发我们的兄弟与我们同去，我们就下去给你籴粮；","notes":[]},{"n":5,"t":"你若不打发他去，我们就不下去，因为那人对我们说：『你们的兄弟若不与你们同来，你们就不得见我的面。』」","notes":[]},{"n":6,"t":"以色列说：「你们为什么这样害我，告诉那人你们还有兄弟呢？」","notes":[]},{"n":7,"t":"他们回答说：「那人详细问到我们和我们的亲属，说：『你们的父亲还在吗？你们还有兄弟吗？』我们就按着他所问的告诉他，焉能知道他要说『必须把你们的兄弟带下来』呢？」","notes":[]},{"n":8,"t":"犹大又对他父亲以色列说：「你打发童子与我同去，我们就起身下去，好叫我们和你，并我们的妇人孩子，都得存活，不至于死。","notes":[]},{"n":9,"t":"我为他作保；你可以从我手中追讨，我若不带他回来交在你面前，我情愿永远担罪。","notes":[]},{"n":10,"t":"我们若没有耽搁，如今第二次都回来了。」","notes":[]},{"n":11,"t":"他们的父亲以色列说：「若必须如此，你们就当这样行：可以将这地土产中最好的乳香、蜂蜜、香料、没药、榧子、杏仁都取一点，收在器具里，带下去送给那人作礼物，","notes":[]},{"n":12,"t":"又要手里加倍地带银子，并将归还在你们口袋内的银子仍带在手里；那或者是错了。","notes":[]},{"n":13,"t":"也带着你们的兄弟，起身去见那人。","notes":[]},{"n":14,"t":"但愿全能的神使你们在那人面前蒙怜悯，释放你们的那弟兄和便雅悯回来。我若丧了儿子，就丧了吧！」","notes":[]},{"n":15,"t":"于是，他们拿着那礼物，又手里加倍地带银子，并且带着便雅悯，起身下到埃及，站在约瑟面前。","notes":[]},{"n":16,"t":"约瑟见便雅悯和他们同来，就对家宰说：「将这些人领到屋里。要宰杀牲畜，预备筵席，因为晌午这些人同我吃饭。」","notes":[]},{"n":17,"t":"家宰就遵着约瑟的命去行，领他们进约瑟的屋里。","notes":[]},{"n":18,"t":"他们因为被领到约瑟的屋里，就害怕，说：「领我们到这里来，必是因为头次归还在我们口袋里的银子，找我们的错缝，下手害我们，强取我们为奴仆，抢夺我们的驴。」","notes":[]},{"n":19,"t":"他们就挨近约瑟的家宰，在屋门口和他说话，","notes":[]},{"n":20,"t":"说：「我主啊，我们头次下来实在是要籴粮。","notes":[]},{"n":21,"t":"后来到了住宿的地方，我们打开口袋，不料，各人的银子，分量足数，仍在各人的口袋内，现在我们手里又带回来了。","notes":[]},{"n":22,"t":"另外又带下银子来籴粮。不知道先前谁把银子放在我们的口袋里。」","notes":[]},{"n":23,"t":"家宰说：「你们可以放心，不要害怕，是你们的神和你们父亲的神赐给你们财宝在你们的口袋里；你们的银子，我早已收了。」他就把西缅带出来，交给他们。","notes":[]},{"n":24,"t":"家宰就领他们进约瑟的屋里，给他们水洗脚，又给他们草料喂驴。","notes":[]},{"n":25,"t":"他们就预备那礼物，等候约瑟晌午来，因为他们听见要在那里吃饭。","notes":[]},{"n":26,"t":"约瑟来到家里，他们就把手中的礼物拿进屋去给他，又俯伏在地，向他下拜。","notes":[]},{"n":27,"t":"约瑟问他们好，又问：「你们的父亲—就是你们所说的那老人家平安吗？他还在吗？」","notes":[]},{"n":28,"t":"他们回答说：「你仆人—我们的父亲平安；他还在。」于是他们低头下拜。","notes":[]},{"n":29,"t":"约瑟举目看见他同母的兄弟便雅悯，就说：「你们向我所说那顶小的兄弟就是这位吗？」又说：「小儿啊，愿神赐恩给你！」","notes":[]},{"n":30,"t":"约瑟爱弟之情发动，就急忙寻找可哭之地，进入自己的屋里，哭了一场。","notes":[]},{"n":31,"t":"他洗了脸出来，勉强隐忍，吩咐人摆饭。","notes":[]},{"n":32,"t":"他们就为约瑟单摆了一席，为那些人又摆了一席，也为和约瑟同吃饭的埃及人另摆了一席，因为埃及人不可和希伯来人一同吃饭；那原是埃及人所厌恶的。","notes":[]},{"n":33,"t":"约瑟使众弟兄在他面前排列坐席，都按着长幼的次序，众弟兄就彼此诧异。","notes":[]},{"n":34,"t":"约瑟把他面前的食物分出来，送给他们；但便雅悯所得的比别人多五倍。他们就饮酒，和约瑟一同宴乐。","notes":[]}]},"44":{"heading":"失落的杯","verses":[{"n":1,"t":"约瑟吩咐家宰说：「把粮食装满这些人的口袋，尽着他们的驴所能驮的，又把各人的银子放在各人的口袋里，","notes":[]},{"n":2,"t":"并将我的银杯和那少年人籴粮的银子一同装在他的口袋里。」家宰就照约瑟所说的话行了；","notes":[]},{"n":3,"t":"天一亮就打发那些人带着驴走了。","notes":[]},{"n":4,"t":"他们出城走了不远，约瑟对家宰说：「起来，追那些人去，追上了就对他们说：『你们为什么以恶报善呢？","notes":[]},{"n":5,"t":"这不是我主人饮酒的杯吗？岂不是他占卜用的吗？你们这样行是作恶了。』」","notes":[]},{"n":6,"t":"家宰追上他们，将这些话对他们说了。","notes":[]},{"n":7,"t":"他们回答说：「我主为什么说这样的话呢？你仆人断不能做这样的事。","notes":[]},{"n":8,"t":"你看，我们从前在口袋里所见的银子，尚且从迦南地带来还你，我们怎能从你主人家里偷窃金银呢？","notes":[]},{"n":9,"t":"你仆人中无论在谁那里搜出来，就叫他死，我们也作我主的奴仆。」","notes":[]},{"n":10,"t":"家宰说：「现在就照你们的话行吧！在谁那里搜出来，谁就作我的奴仆；其余的都没有罪。」","notes":[]},{"n":11,"t":"于是他们各人急忙把口袋卸在地上，各人打开口袋。","notes":[]},{"n":12,"t":"家宰就搜查，从年长的起到年幼的为止，那杯竟在便雅悯的口袋里搜出来。","notes":[]},{"n":13,"t":"他们就撕裂衣服，各人把驮子抬在驴上，回城去了。","notes":[]},{"n":14,"t":"犹大和他弟兄们来到约瑟的屋中，约瑟还在那里，他们就在他面前俯伏于地。","notes":[]},{"n":15,"t":"约瑟对他们说：「你们做的是什么事呢？你们岂不知像我这样的人必能占卜吗？」","notes":[]},{"n":16,"t":"犹大说：「我们对我主说什么呢？还有什么话可说呢？我们怎能自己表白出来呢？神已经查出仆人的罪孽了。我们与那在他手中搜出杯来的都是我主的奴仆。」","notes":[]},{"n":17,"t":"约瑟说：「我断不能这样行！在谁的手中搜出杯来，谁就作我的奴仆；至于你们，可以平平安安地上你们父亲那里去。」","notes":[]},{"n":18,"t":"犹大挨近他，说：「我主啊，求你容仆人说一句话给我主听，不要向仆人发烈怒，因为你如同法老一样。","notes":[],"heads":["犹大替便雅悯哀求"]},{"n":19,"t":"我主曾问仆人们说：『你们有父亲有兄弟没有？』","notes":[]},{"n":20,"t":"我们对我主说：『我们有父亲，已经年老，还有他老年所生的一个小孩子。他哥哥死了，他母亲只撇下他一人，他父亲疼爱他。』","notes":[]},{"n":21,"t":"你对仆人说：『把他带到我这里来，叫我亲眼看看他。』","notes":[]},{"n":22,"t":"我们对我主说：『童子不能离开他父亲，若是离开，他父亲必死。』","notes":[]},{"n":23,"t":"你对仆人说：『你们的小兄弟若不与你们一同下来，你们就不得再见我的面。』","notes":[]},{"n":24,"t":"我们上到你仆人—我们父亲那里，就把我主的话告诉了他。","notes":[]},{"n":25,"t":"我们的父亲说：『你们再去给我籴些粮来。』","notes":[]},{"n":26,"t":"我们就说：『我们不能下去。我们的小兄弟若和我们同往，我们就可以下去。因为，小兄弟若不与我们同往，我们必不得见那人的面。』","notes":[]},{"n":27,"t":"你仆人—我父亲对我们说：『你们知道我的妻子给我生了两个儿子。","notes":[]},{"n":28,"t":"一个离开我出去了；我说他必是被撕碎了，直到如今我也没有见他。","notes":[]},{"n":29,"t":"现在你们又要把这个带去离开我，倘若他遭害，那便是你们使我白发苍苍、悲悲惨惨地下阴间去了。』","notes":[]},{"n":30,"t":"我父亲的命与这童子的命相连。如今我回到你仆人—我父亲那里，若没有童子与我们同在，","notes":[]},{"n":31,"t":"我们的父亲见没有童子，他就必死。这便是我们使你仆人—我们的父亲白发苍苍、悲悲惨惨地下阴间去了。","notes":[]},{"n":32,"t":"因为仆人曾向我父亲为这童子作保，说：『我若不带他回来交给父亲，我便在父亲面前永远担罪。』","notes":[]},{"n":33,"t":"现在求你容仆人住下，替这童子作我主的奴仆，叫童子和他哥哥们一同上去。","notes":[]},{"n":34,"t":"若童子不和我同去，我怎能上去见我父亲呢？恐怕我看见灾祸临到我父亲身上。」","notes":[]}]},"45":{"heading":"约瑟和兄弟相认","verses":[{"n":1,"t":"约瑟在左右站着的人面前情不自禁，吩咐一声说：「人都要离开我出去！」约瑟和弟兄们相认的时候并没有一人站在他面前。","notes":[]},{"n":2,"t":"他就放声大哭；埃及人和法老家中的人都听见了。","notes":[]},{"n":3,"t":"约瑟对他弟兄们说：「我是约瑟。我的父亲还在吗？」他弟兄不能回答，因为在他面前都惊惶。","notes":[]},{"n":4,"t":"约瑟又对他弟兄们说：「请你们近前来。」他们就近前来。他说：「我是你们的兄弟约瑟，就是你们所卖到埃及的。","notes":[]},{"n":5,"t":"现在，不要因为把我卖到这里自忧自恨。这是神差我在你们以先来，为要保全生命。","notes":[]},{"n":6,"t":"现在这地的饥荒已经二年了，还有五年不能耕种，不能收成。","notes":[]},{"n":7,"t":"神差我在你们以先来，为要给你们存留余种在世上，又要大施拯救，保全你们的生命。","notes":[]},{"n":8,"t":"这样看来，差我到这里来的不是你们，乃是神。他又使我如法老的父，作他全家的主，并埃及全地的宰相。","notes":[]},{"n":9,"t":"你们要赶紧上到我父亲那里，对他说：『你儿子约瑟这样说：神使我作全埃及的主，请你下到我这里来，不要耽延。","notes":[]},{"n":10,"t":"你和你的儿子孙子，连牛群羊群，并一切所有的，都可以住在歌珊地，与我相近。","notes":[]},{"n":11,"t":"我要在那里奉养你；因为还有五年的饥荒，免得你和你的眷属，并一切所有的，都败落了。』","notes":[]},{"n":12,"t":"况且你们的眼和我兄弟便雅悯的眼都看见是我亲口对你们说话。","notes":[]},{"n":13,"t":"你们也要将我在埃及一切的荣耀和你们所看见的事都告诉我父亲，又要赶紧地将我父亲搬到我这里来。」","notes":[]},{"n":14,"t":"于是约瑟伏在他兄弟便雅悯的颈项上哭，便雅悯也在他的颈项上哭。","notes":[]},{"n":15,"t":"他又与众弟兄亲嘴，抱着他们哭，随后他弟兄们就和他说话。","notes":[]},{"n":16,"t":"这风声传到法老的宫里，说：「约瑟的弟兄们来了。」法老和他的臣仆都很喜欢。","notes":[]},{"n":17,"t":"法老对约瑟说：「你吩咐你的弟兄们说：『你们要这样行：把驮子抬在牲口上，起身往迦南地去。","notes":[]},{"n":18,"t":"将你们的父亲和你们的眷属都搬到我这里来，我要把埃及地的美物赐给你们，你们也要吃这地肥美的出产。","notes":[]},{"n":19,"t":"现在我吩咐你们要这样行：从埃及地带着车辆去，把你们的孩子和妻子，并你们的父亲都搬来。","notes":[]},{"n":20,"t":"你们眼中不要爱惜你们的家具，因为埃及全地的美物都是你们的。』」","notes":[]},{"n":21,"t":"以色列的儿子们就如此行。约瑟照着法老的吩咐给他们车辆和路上用的食物，","notes":[]},{"n":22,"t":"又给他们各人一套衣服，惟独给便雅悯三百银子，五套衣服；","notes":[]},{"n":23,"t":"送给他父亲公驴十匹，驮着埃及的美物，母驴十匹，驮着粮食与饼和菜，为他父亲路上用。","notes":[]},{"n":24,"t":"于是约瑟打发他弟兄们回去，又对他们说：「你们不要在路上相争。」","notes":[]},{"n":25,"t":"他们从埃及上去，来到迦南地、他们的父亲雅各那里，","notes":[]},{"n":26,"t":"告诉他说：「约瑟还在，并且作埃及全地的宰相。」雅各心里冰凉，因为不信他们。","notes":[]},{"n":27,"t":"他们便将约瑟对他们说的一切话都告诉了他。他们父亲雅各又看见约瑟打发来接他的车辆，心就苏醒了。","notes":[]},{"n":28,"t":"以色列说：「罢了！罢了！我的儿子约瑟还在，趁我未死以先，我要去见他一面。」","notes":[]}]},"46":{"heading":"雅各带家属到埃及","verses":[{"n":1,"t":"以色列带着一切所有的，起身来到别是巴，就献祭给他父亲以撒的神。","notes":[]},{"n":2,"t":"夜间，神在异象中对以色列说：「雅各！雅各！」他说：「我在这里。」","notes":[]},{"n":3,"t":"神说：「我是神，就是你父亲的神。你下埃及去不要害怕，因为我必使你在那里成为大族。","notes":[]},{"n":4,"t":"我要和你同下埃及去，也必定带你上来；约瑟必给你送终。」","notes":["原文是将手按在你的眼睛上"]},{"n":5,"t":"雅各就从别是巴起行。以色列的儿子们使他们的父亲雅各和他们的妻子、儿女都坐在法老为雅各送来的车上。","notes":[]},{"n":6,"t":"他们又带着迦南地所得的牲畜、货财来到埃及。雅各和他的一切子孙都一同来了。","notes":[]},{"n":7,"t":"雅各把他的儿子、孙子、女儿、孙女，并他的子子孙孙，一同带到埃及。","notes":[]},{"n":8,"t":"来到埃及的以色列人名字记在下面。雅各和他的儿孙：雅各的长子是吕便。","notes":[]},{"n":9,"t":"吕便的儿子是哈诺、法路、希斯伦、迦米。","notes":[]},{"n":10,"t":"西缅的儿子是耶母利、雅悯、阿辖、雅斤、琐辖，还有迦南女子所生的扫罗。","notes":[]},{"n":11,"t":"利未的儿子是革顺、哥辖、米拉利。","notes":[]},{"n":12,"t":"犹大的儿子是珥、俄南、示拉、法勒斯、谢拉；惟有珥与俄南死在迦南地。法勒斯的儿子是希斯仑、哈母勒。","notes":[]},{"n":13,"t":"以萨迦的儿子是陀拉、普瓦、约伯、伸仑。","notes":[]},{"n":14,"t":"西布伦的儿子是西烈、以伦、雅利。","notes":[]},{"n":15,"t":"这是利亚在巴旦·亚兰给雅各所生的儿子，还有女儿底拿。儿孙共有三十三人。","notes":[]},{"n":16,"t":"迦得的儿子是洗非芸、哈基、书尼、以斯本、以利、亚罗底、亚列利。","notes":[]},{"n":17,"t":"亚设的儿子是音拿、亦施瓦、亦施韦、比利亚，还有他们的妹子西拉。比利亚的儿子是希别、玛结。","notes":[]},{"n":18,"t":"这是拉班给他女儿利亚的婢女悉帕从雅各所生的儿孙，共有十六人。","notes":[]},{"n":19,"t":"雅各之妻拉结的儿子是约瑟和便雅悯。","notes":[]},{"n":20,"t":"约瑟在埃及地生了玛拿西和以法莲，就是安城的祭司波提非拉的女儿亚西纳给约瑟生的。","notes":[]},{"n":21,"t":"便雅悯的儿子是比拉、比结、亚实别、基拉、乃幔、以希、罗实、母平、户平、亚勒。","notes":[]},{"n":22,"t":"这是拉结给雅各所生的儿孙，共有十四人。","notes":[]},{"n":23,"t":"但的儿子是户伸。","notes":[]},{"n":24,"t":"拿弗他利的儿子是雅薛、沽尼、耶色、示冷。","notes":[]},{"n":25,"t":"这是拉班给他女儿拉结的婢女辟拉从雅各所生的儿孙，共有七人。","notes":[]},{"n":26,"t":"那与雅各同到埃及的，除了他儿妇之外，凡从他所生的，共有六十六人。","notes":[]},{"n":27,"t":"还有约瑟在埃及所生的两个儿子。雅各家来到埃及的共有七十人。","notes":[]},{"n":28,"t":"雅各打发犹大先去见约瑟，请派人引路往歌珊去；于是他们来到歌珊地。","notes":[],"heads":["雅各和家属在埃及"]},{"n":29,"t":"约瑟套车往歌珊去，迎接他父亲以色列，及至见了面，就伏在父亲的颈项上，哭了许久。","notes":[]},{"n":30,"t":"以色列对约瑟说：「我既得见你的面，知道你还在，就是死我也甘心。」","notes":[]},{"n":31,"t":"约瑟对他的弟兄和他父的全家说：「我要上去告诉法老，对他说：『我的弟兄和我父的全家从前在迦南地，现今都到我这里来了。","notes":[]},{"n":32,"t":"他们本是牧羊的人，以养牲畜为业；他们把羊群牛群和一切所有的都带来了。』","notes":[]},{"n":33,"t":"等法老召你们的时候，问你们说：『你们以何事为业？』","notes":[]},{"n":34,"t":"你们要说：『你的仆人，从幼年直到如今，都以养牲畜为业，连我们的祖宗也都以此为业。』这样，你们可以住在歌珊地，因为凡牧羊的都被埃及人所厌恶。」","notes":[]}]},"47":{"heading":"饥荒","verses":[{"n":1,"t":"约瑟进去告诉法老说：「我的父亲和我的弟兄带着羊群牛群，并一切所有的，从迦南地来了，如今在歌珊地。」","notes":[]},{"n":2,"t":"约瑟从他弟兄中挑出五个人来，引他们去见法老。","notes":[]},{"n":3,"t":"法老问约瑟的弟兄说：「你们以何事为业？」他们对法老说：「你仆人是牧羊的，连我们的祖宗也是牧羊的。」","notes":[]},{"n":4,"t":"他们又对法老说：「迦南地的饥荒甚大，仆人的羊群没有草吃，所以我们来到这地寄居。现在求你容仆人住在歌珊地。」","notes":[]},{"n":5,"t":"法老对约瑟说：「你父亲和你弟兄到你这里来了，","notes":[]},{"n":6,"t":"埃及地都在你面前，只管叫你父亲和你弟兄住在国中最好的地；他们可以住在歌珊地。你若知道他们中间有什么能人，就派他们看管我的牲畜。」","notes":[]},{"n":7,"t":"约瑟领他父亲雅各进到法老面前，雅各就给法老祝福。","notes":[]},{"n":8,"t":"法老问雅各说：「你平生的年日是多少呢？」","notes":[]},{"n":9,"t":"雅各对法老说：「我寄居在世的年日是一百三十岁，我平生的年日又少又苦，不及我列祖在世寄居的年日。」","notes":[]},{"n":10,"t":"雅各又给法老祝福，就从法老面前出去了。","notes":[]},{"n":11,"t":"约瑟遵着法老的命，把埃及国最好的地，就是兰塞境内的地，给他父亲和弟兄居住，作为产业。","notes":[]},{"n":12,"t":"约瑟用粮食奉养他父亲和他弟兄，并他父亲全家的眷属，都是照各家的人口奉养他们。","notes":[]},{"n":13,"t":"饥荒甚大，全地都绝了粮，甚至埃及地和迦南地的人因那饥荒的缘故都饿昏了。","notes":[]},{"n":14,"t":"约瑟收聚了埃及地和迦南地所有的银子，就是众人籴粮的银子，约瑟就把那银子带到法老的宫里。","notes":[]},{"n":15,"t":"埃及地和迦南地的银子都花尽了，埃及众人都来见约瑟，说：「我们的银子都用尽了，求你给我们粮食，我们为什么死在你面前呢？」","notes":[]},{"n":16,"t":"约瑟说：「若是银子用尽了，可以把你们的牲畜给我，我就为你们的牲畜给你们粮食。」","notes":[]},{"n":17,"t":"于是他们把牲畜赶到约瑟那里，约瑟就拿粮食换了他们的牛、羊、驴、马；那一年因换他们一切的牲畜，就用粮食养活他们。","notes":[]},{"n":18,"t":"那一年过去，第二年他们又来见约瑟，说：「我们不瞒我主，我们的银子都花尽了，牲畜也都归了我主。我们在我主眼前，除了我们的身体和田地之外，一无所剩。","notes":[]},{"n":19,"t":"你何忍见我们人死地荒呢？求你用粮食买我们和我们的地，我们和我们的地就要给法老效力。又求你给我们种子，使我们得以存活，不至死亡，地土也不至荒凉。」","notes":[]},{"n":20,"t":"于是，约瑟为法老买了埃及所有的地，埃及人因被饥荒所迫，各都卖了自己的田地；那地就都归了法老。","notes":[]},{"n":21,"t":"至于百姓，约瑟叫他们，从埃及这边直到埃及那边，都各归各城。","notes":[]},{"n":22,"t":"惟有祭司的地，约瑟没有买，因为祭司有从法老所得的常俸。他们吃法老所给的常俸，所以他们不卖自己的地。","notes":[]},{"n":23,"t":"约瑟对百姓说：「我今日为法老买了你们和你们的地，看哪，这里有种子给你们，你们可以种地。","notes":[]},{"n":24,"t":"后来打粮食的时候，你们要把五分之一纳给法老，四分可以归你们做地里的种子，也做你们和你们家口孩童的食物。」","notes":[]},{"n":25,"t":"他们说：「你救了我们的性命。但愿我们在我主眼前蒙恩，我们就作法老的仆人。」","notes":[]},{"n":26,"t":"于是约瑟为埃及地定下常例，直到今日：法老必得五分之一，惟独祭司的地不归法老。","notes":[]},{"n":27,"t":"以色列人住在埃及的歌珊地。他们在那里置了产业，并且生育甚多。","notes":[],"heads":["雅各最后的吩咐"]},{"n":28,"t":"雅各住在埃及地十七年，雅各平生的年日是一百四十七岁。","notes":[]},{"n":29,"t":"以色列的死期临近了，他就叫了他儿子约瑟来，说：「我若在你眼前蒙恩，请你把手放在我大腿底下，用慈爱和诚实待我，请你不要将我葬在埃及。","notes":[]},{"n":30,"t":"我与我祖我父同睡的时候，你要将我带出埃及，葬在他们所葬的地方。」约瑟说：「我必遵着你的命而行。」","notes":[]},{"n":31,"t":"雅各说：「你要向我起誓。」约瑟就向他起了誓，于是以色列在床头上敬拜神。","notes":["或译：扶着杖头"]}]},"48":{"heading":"雅各祝福以法莲和玛拿西","verses":[{"n":1,"t":"这事以后，有人告诉约瑟说：「你的父亲病了。」他就带着两个儿子玛拿西和以法莲同去。","notes":[]},{"n":2,"t":"有人告诉雅各说：「请看，你儿子约瑟到你这里来了。」以色列就勉强在床上坐起来。","notes":[]},{"n":3,"t":"雅各对约瑟说：「全能的神曾在迦南地的路斯向我显现，赐福与我，","notes":[]},{"n":4,"t":"对我说：『我必使你生养众多，成为多民，又要把这地赐给你的后裔，永远为业。』","notes":[]},{"n":5,"t":"我未到埃及见你之先，你在埃及地所生的以法莲和玛拿西这两个儿子是我的，正如吕便和西缅是我的一样。","notes":[]},{"n":6,"t":"你在他们以后所生的就是你的，他们可以归于他们弟兄的名下得产业。","notes":[]},{"n":7,"t":"至于我，我从巴旦来的时候，拉结死在我眼前，在迦南地的路上，离以法他还有一段路程，我就把她葬在以法他的路上（以法他就是伯利恒）。」","notes":[]},{"n":8,"t":"以色列看见约瑟的两个儿子，就说：「这是谁？」","notes":[]},{"n":9,"t":"约瑟对他父亲说：「这是神在这里赐给我的儿子。」以色列说：「请你领他们到我跟前，我要给他们祝福。」","notes":[]},{"n":10,"t":"以色列年纪老迈，眼睛昏花，不能看见。约瑟领他们到他跟前，他就和他们亲嘴，抱着他们。","notes":[]},{"n":11,"t":"以色列对约瑟说：「我想不到得见你的面，不料，神又使我得见你的儿子。」","notes":[]},{"n":12,"t":"约瑟把两个儿子从以色列两膝中领出来，自己就脸伏于地下拜。","notes":[]},{"n":13,"t":"随后，约瑟又拉着他们两个，以法莲在他的右手里，对着以色列的左手，玛拿西在他的左手里，对着以色列的右手，领他们到以色列的跟前。","notes":[]},{"n":14,"t":"以色列伸出右手来，按在以法莲的头上（以法莲乃是次子），又剪搭过左手来，按在玛拿西的头上（玛拿西原是长子）。","notes":[]},{"n":15,"t":"他就给约瑟祝福说：「愿我祖亚伯拉罕和我父以撒所事奉的神，就是一生牧养我直到今日的神，","notes":[]},{"n":16,"t":"救赎我脱离一切患难的那使者，赐福与这两个童子。愿他们归在我的名下和我祖亚伯拉罕、我父以撒的名下。又愿他们在世界中生养众多。」","notes":[]},{"n":17,"t":"约瑟见他父亲把右手按在以法莲的头上，就不喜悦，便提起他父亲的手，要从以法莲头上挪到玛拿西的头上。","notes":[]},{"n":18,"t":"约瑟对他父亲说：「我父，不是这样。这本是长子，求你把右手按在他的头上。」","notes":[]},{"n":19,"t":"他父亲不从，说：「我知道，我儿，我知道。他也必成为一族，也必昌大。只是他的兄弟将来比他还大；他兄弟的后裔要成为多族。」","notes":[]},{"n":20,"t":"当日就给他们祝福说：「以色列人要指着你们祝福说：『愿神使你如以法莲、玛拿西一样。』」于是立以法莲在玛拿西以上。","notes":[]},{"n":21,"t":"以色列又对约瑟说：「我要死了，但神必与你们同在，领你们回到你们列祖之地。","notes":[]},{"n":22,"t":"并且我从前用弓用刀从亚摩利人手下夺的那块地，我都赐给你，使你比众弟兄多得一分。」","notes":[]}]},"49":{"heading":"雅各的遗嘱","verses":[{"n":1,"t":"雅各叫了他的儿子们来，说：「你们都来聚集，我好把你们日后必遇的事告诉你们。","notes":[]},{"n":2,"t":"雅各的儿子们，你们要聚集而听，要听你们父亲以色列的话。","notes":[]},{"n":3,"t":"吕便哪，你是我的长子，是我力量强壮的时候生的，本当大有尊荣，权力超众。","notes":[]},{"n":4,"t":"但你放纵情欲，滚沸如水，必不得居首位；因为你上了你父亲的床，污秽了我的榻。","notes":[]},{"n":5,"t":"西缅和利未是弟兄；他们的刀剑是残忍的器具。","notes":[]},{"n":6,"t":"我的灵啊，不要与他们同谋；我的心哪，不要与他们联络；因为他们趁怒杀害人命，任意砍断牛腿大筋。","notes":[]},{"n":7,"t":"他们的怒气暴烈可咒；他们的忿恨残忍可诅。我要使他们分居在雅各家里，散住在以色列地中。","notes":[]},{"n":8,"t":"犹大啊，你弟兄们必赞美你；你手必掐住仇敌的颈项；你父亲的儿子们必向你下拜。","notes":[]},{"n":9,"t":"犹大是个小狮子；我儿啊，你抓了食便上去。你屈下身去，卧如公狮，蹲如母狮，谁敢惹你？","notes":[]},{"n":10,"t":"圭必不离犹大，杖必不离他两脚之间，直等细罗来到，万民都必归顺。","notes":["就是赐平安者"]},{"n":11,"t":"犹大把小驴拴在葡萄树上，把驴驹拴在美好的葡萄树上。他在葡萄酒中洗了衣服，在葡萄汁中洗了袍褂。","notes":[]},{"n":12,"t":"他的眼睛必因酒红润；他的牙齿必因奶白亮。","notes":[]},{"n":13,"t":"西布伦必住在海口，必成为停船的海口；他的境界必延到西顿。","notes":[]},{"n":14,"t":"以萨迦是个强壮的驴，卧在羊圈之中。","notes":[]},{"n":15,"t":"他以安静为佳，以肥地为美，便低肩背重，成为服苦的仆人。","notes":[]},{"n":16,"t":"但必判断他的民，作以色列支派之一。","notes":[]},{"n":17,"t":"但必作道上的蛇，路中的虺，咬伤马蹄，使骑马的坠落于后。","notes":[]},{"n":18,"t":"耶和华啊，我向来等候你的救恩。","notes":[]},{"n":19,"t":"迦得必被敌军追逼，他却要追逼他们的脚跟。","notes":[]},{"n":20,"t":"亚设之地必出肥美的粮食，且出君王的美味。","notes":[]},{"n":21,"t":"拿弗他利是被释放的母鹿；他出嘉美的言语。","notes":[]},{"n":22,"t":"约瑟是多结果子的树枝，是泉旁多结果的枝子；他的枝条探出墙外。","notes":[]},{"n":23,"t":"弓箭手将他苦害，向他射箭，逼迫他。","notes":[]},{"n":24,"t":"但他的弓仍旧坚硬；他的手健壮敏捷。这是因以色列的牧者，以色列的磐石—就是雅各的大能者。","notes":[]},{"n":25,"t":"你父亲的神必帮助你；那全能者必将天上所有的福，地里所藏的福，以及生产乳养的福，都赐给你。","notes":[]},{"n":26,"t":"你父亲所祝的福胜过我祖先所祝的福，如永世的山岭，至极的边界；这些福必降在约瑟的头上，临到那与弟兄迥别之人的顶上。","notes":[]},{"n":27,"t":"便雅悯是个撕掠的狼，早晨要吃他所抓的，晚上要分他所夺的。」","notes":[]},{"n":28,"t":"这一切是以色列的十二支派；这也是他们的父亲对他们所说的话，为他们所祝的福，都是按着各人的福分为他们祝福。","notes":[]},{"n":29,"t":"他又嘱咐他们说：「我将要归到我列祖那里，你们要将我葬在赫人以弗仑田间的洞里，与我祖我父在一处，","notes":["原文是本民"],"heads":["雅各的死和埋葬"]},{"n":30,"t":"就是在迦南地幔利前、麦比拉田间的洞；那洞和田是亚伯拉罕向赫人以弗仑买来为业，作坟地的。","notes":[]},{"n":31,"t":"他们在那里葬了亚伯拉罕和他妻子撒拉，又在那里葬了以撒和他的妻子利百加；我也在那里葬了利亚。","notes":[]},{"n":32,"t":"那块田和田间的洞原是向赫人买的。」","notes":[]},{"n":33,"t":"雅各嘱咐众子已毕，就把脚收在床上，气绝而死，归他列祖那里去了。","notes":["原文是本民"]}]},"50":{"heading":"约瑟安慰哥哥们","verses":[{"n":1,"t":"约瑟伏在他父亲的面上哀哭，与他亲嘴。","notes":[]},{"n":2,"t":"约瑟吩咐伺候他的医生用香料薰他父亲，医生就用香料薰了以色列。","notes":[]},{"n":3,"t":"薰尸的常例是四十天；那四十天满了，埃及人为他哀哭了七十天。","notes":[]},{"n":4,"t":"为他哀哭的日子过了，约瑟对法老家中的人说：「我若在你们眼前蒙恩，请你们报告法老说：","notes":[]},{"n":5,"t":"『我父亲要死的时候叫我起誓说：你要将我葬在迦南地，在我为自己所掘的坟墓里。』现在求你让我上去葬我父亲，以后我必回来。」","notes":[]},{"n":6,"t":"法老说：「你可以上去，照着你父亲叫你起的誓，将他葬埋。」","notes":[]},{"n":7,"t":"于是约瑟上去葬他父亲。与他一同上去的，有法老的臣仆和法老家中的长老，并埃及国的长老，","notes":[]},{"n":8,"t":"还有约瑟的全家和他的弟兄们，并他父亲的眷属；只有他们的妇人孩子，和羊群牛群，都留在歌珊地。","notes":[]},{"n":9,"t":"又有车辆马兵，和他一同上去；那一帮人甚多。","notes":[]},{"n":10,"t":"他们到了约旦河外、亚达的禾场，就在那里大大地号咷痛哭。约瑟为他父亲哀哭了七天。","notes":[]},{"n":11,"t":"迦南的居民见亚达禾场上的哀哭，就说：「这是埃及人一场极大的哀哭。」因此那地方名叫亚伯·麦西，是在约旦河东。","notes":[]},{"n":12,"t":"雅各的儿子们就遵着他父亲所吩咐的办了，","notes":[]},{"n":13,"t":"把他搬到迦南地，葬在幔利前、麦比拉田间的洞里；那洞和田是亚伯拉罕向赫人以弗仑买来为业，作坟地的。","notes":[]},{"n":14,"t":"约瑟葬了他父亲以后，就和众弟兄，并一切同他上去葬他父亲的人，都回埃及去了。","notes":[]},{"n":15,"t":"约瑟的哥哥们见父亲死了，就说：「或者约瑟怀恨我们，照着我们从前待他一切的恶足足地报复我们。」","notes":[]},{"n":16,"t":"他们就打发人去见约瑟，说：「你父亲未死以先吩咐说：","notes":[]},{"n":17,"t":"『你们要对约瑟这样说：从前你哥哥们恶待你，求你饶恕他们的过犯和罪恶。』如今求你饶恕你父亲神之仆人的过犯。」他们对约瑟说这话，约瑟就哭了。","notes":[]},{"n":18,"t":"他的哥哥们又来俯伏在他面前，说：「我们是你的仆人。」","notes":[]},{"n":19,"t":"约瑟对他们说：「不要害怕，我岂能代替神呢？","notes":[]},{"n":20,"t":"从前你们的意思是要害我，但神的意思原是好的，要保全许多人的性命，成就今日的光景。","notes":[]},{"n":21,"t":"现在你们不要害怕，我必养活你们和你们的妇人孩子。」于是约瑟用亲爱的话安慰他们。","notes":[]},{"n":22,"t":"约瑟和他父亲的眷属都住在埃及。约瑟活了一百一十岁。","notes":[],"heads":["约瑟的死"]},{"n":23,"t":"约瑟得见以法莲第三代的子孙。玛拿西的孙子、玛吉的儿子也养在约瑟的膝上。","notes":[]},{"n":24,"t":"约瑟对他弟兄们说：「我要死了，但神必定看顾你们，领你们从这地上去，到他起誓所应许给亚伯拉罕、以撒、雅各之地。」","notes":[]},{"n":25,"t":"约瑟叫以色列的子孙起誓说：「神必定看顾你们；你们要把我的骸骨从这里搬上去。」","notes":[]},{"n":26,"t":"约瑟死了，正一百一十岁。人用香料将他薰了，把他收殓在棺材里，停在埃及。","notes":[]}]}},"EXO":{"1":{"heading":"以色列人在埃及受虐待","verses":[{"n":1,"t":"以色列的众子，各带家眷，和雅各一同来到埃及。他们的名字记在下面。","notes":[]},{"n":2,"t":"有吕便、西缅、利未、犹大、","notes":[]},{"n":3,"t":"以萨迦、西布伦、便雅悯、","notes":[]},{"n":4,"t":"但、拿弗他利、迦得、亚设。","notes":[]},{"n":5,"t":"凡从雅各而生的，共有七十人。约瑟已经在埃及。","notes":[]},{"n":6,"t":"约瑟和他的弟兄，并那一代的人，都死了。","notes":[]},{"n":7,"t":"以色列人生养众多，并且繁茂，极其强盛，满了那地。","notes":[]},{"n":8,"t":"有不认识约瑟的新王起来，治理埃及，","notes":[]},{"n":9,"t":"对他的百姓说：「看哪，这以色列民比我们还多，又比我们强盛。","notes":[]},{"n":10,"t":"来吧，我们不如用巧计待他们，恐怕他们多起来，日后若遇什么争战的事，就连合我们的仇敌攻击我们，离开这地去了。」","notes":[]},{"n":11,"t":"于是埃及人派督工的辖制他们，加重担苦害他们。他们为法老建造两座积货城，就是比东和兰塞。","notes":[]},{"n":12,"t":"只是越发苦害他们，他们越发多起来，越发蔓延；埃及人就因以色列人愁烦。","notes":[]},{"n":13,"t":"埃及人严严地使以色列人做工，","notes":[]},{"n":14,"t":"使他们因做苦工觉得命苦；无论是和泥，是做砖，是做田间各样的工，在一切的工上都严严地待他们。","notes":[]},{"n":15,"t":"有希伯来的两个收生婆，一名施弗拉，一名普阿；埃及王对她们说：","notes":[]},{"n":16,"t":"「你们为希伯来妇人收生，看她们临盆的时候，若是男孩，就把他杀了；若是女孩，就留她存活。」","notes":[]},{"n":17,"t":"但是收生婆敬畏神，不照埃及王的吩咐行，竟存留男孩的性命。","notes":[]},{"n":18,"t":"埃及王召了收生婆来，说：「你们为什么做这事，存留男孩的性命呢？」","notes":[]},{"n":19,"t":"收生婆对法老说：「因为希伯来妇人与埃及妇人不同；希伯来妇人本是健壮的，收生婆还没有到，她们已经生产了。」","notes":["原文是活泼的"]},{"n":20,"t":"神厚待收生婆。以色列人多起来，极其强盛。","notes":[]},{"n":21,"t":"收生婆因为敬畏神，神便叫她们成立家室。","notes":[]},{"n":22,"t":"法老吩咐他的众民说：「以色列人所生的男孩，你们都要丢在河里；一切的女孩，你们要存留她的性命。」","notes":[]}]},"2":{"heading":"摩西的出生","verses":[{"n":1,"t":"有一个利未家的人娶了一个利未女子为妻。","notes":[]},{"n":2,"t":"那女人怀孕，生一个儿子，见他俊美，就藏了他三个月，","notes":[]},{"n":3,"t":"后来不能再藏，就取了一个蒲草箱，抹上石漆和石油，将孩子放在里头，把箱子搁在河边的芦荻中。","notes":[]},{"n":4,"t":"孩子的姊姊远远站着，要知道他究竟怎么样。","notes":[]},{"n":5,"t":"法老的女儿来到河边洗澡，她的使女们在河边行走。她看见箱子在芦荻中，就打发一个婢女拿来。","notes":[]},{"n":6,"t":"她打开箱子，看见那孩子。孩子哭了，她就可怜他，说：「这是希伯来人的一个孩子。」","notes":[]},{"n":7,"t":"孩子的姊姊对法老的女儿说：「我去在希伯来妇人中叫一个奶妈来，为你奶这孩子，可以不可以？」","notes":[]},{"n":8,"t":"法老的女儿说：「可以。」童女就去叫了孩子的母亲来。","notes":[]},{"n":9,"t":"法老的女儿对她说：「你把这孩子抱去，为我奶他，我必给你工价。」妇人就抱了孩子去奶他。","notes":[]},{"n":10,"t":"孩子渐长，妇人把他带到法老的女儿那里，就作了她的儿子。她给孩子起名叫摩西，意思说：「因我把他从水里拉出来。」","notes":[]},{"n":11,"t":"后来，摩西长大，他出去到他弟兄那里，看他们的重担，见一个埃及人打希伯来人的一个弟兄。","notes":[],"heads":["摩西逃往米甸"]},{"n":12,"t":"他左右观看，见没有人，就把埃及人打死了，藏在沙土里。","notes":[]},{"n":13,"t":"第二天他出去，见有两个希伯来人争斗，就对那欺负人的说：「你为什么打你同族的人呢？」","notes":[]},{"n":14,"t":"那人说：「谁立你作我们的首领和审判官呢？难道你要杀我，像杀那埃及人吗？」摩西便惧怕，说：「这事必是被人知道了。」","notes":[]},{"n":15,"t":"法老听见这事，就想杀摩西，但摩西躲避法老，逃往米甸地居住。","notes":[]},{"n":16,"t":"一日，他在井旁坐下。米甸的祭司有七个女儿；她们来打水，打满了槽，要饮父亲的群羊。","notes":[]},{"n":17,"t":"有牧羊的人来，把她们赶走了，摩西却起来帮助她们，又饮了她们的群羊。","notes":[]},{"n":18,"t":"她们来到父亲流珥那里；他说：「今日你们为何来得这么快呢？」","notes":[]},{"n":19,"t":"她们说：「有一个埃及人救我们脱离牧羊人的手，并且为我们打水饮了群羊。」","notes":[]},{"n":20,"t":"他对女儿们说：「那个人在哪里？你们为什么撇下他呢？你们去请他来吃饭。」","notes":[]},{"n":21,"t":"摩西甘心和那人同住；那人把他的女儿西坡拉给摩西为妻。","notes":[]},{"n":22,"t":"西坡拉生了一个儿子，摩西给他起名叫革舜，意思说：「因我在外邦作了寄居的。」","notes":[]},{"n":23,"t":"过了多年，埃及王死了。以色列人因做苦工，就叹息哀求，他们的哀声达于神。","notes":[]},{"n":24,"t":"神听见他们的哀声，就记念他与亚伯拉罕、以撒、雅各所立的约。","notes":[]},{"n":25,"t":"神看顾以色列人，也知道他们的苦情。","notes":[]}]},"3":{"heading":"神呼召摩西","verses":[{"n":1,"t":"摩西牧养他岳父米甸祭司叶忒罗的羊群；一日领羊群往野外去，到了神的山，就是何烈山。","notes":[]},{"n":2,"t":"耶和华的使者从荆棘里火焰中向摩西显现。摩西观看，不料，荆棘被火烧着，却没有烧毁。","notes":[]},{"n":3,"t":"摩西说：「我要过去看这大异象，这荆棘为何没有烧坏呢？」","notes":[]},{"n":4,"t":"耶和华神见他过去要看，就从荆棘里呼叫说：「摩西！摩西！」他说：「我在这里。」","notes":[]},{"n":5,"t":"神说：「不要近前来。当把你脚上的鞋脱下来，因为你所站之地是圣地」；","notes":[]},{"n":6,"t":"又说：「我是你父亲的神，是亚伯拉罕的神，以撒的神，雅各的神。」摩西蒙上脸，因为怕看神。","notes":[]},{"n":7,"t":"耶和华说：「我的百姓在埃及所受的困苦，我实在看见了；他们因受督工的辖制所发的哀声，我也听见了。我原知道他们的痛苦，","notes":[]},{"n":8,"t":"我下来是要救他们脱离埃及人的手，领他们出了那地，到美好、宽阔、流奶与蜜之地，就是到迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人之地。","notes":[]},{"n":9,"t":"现在以色列人的哀声达到我耳中，我也看见埃及人怎样欺压他们。","notes":[]},{"n":10,"t":"故此，我要打发你去见法老，使你可以将我的百姓以色列人从埃及领出来。」","notes":[]},{"n":11,"t":"摩西对神说：「我是什么人，竟能去见法老，将以色列人从埃及领出来呢？」","notes":[]},{"n":12,"t":"神说：「我必与你同在。你将百姓从埃及领出来之后，你们必在这山上事奉我；这就是我打发你去的证据。」","notes":[]},{"n":13,"t":"摩西对神说：「我到以色列人那里，对他们说：『你们祖宗的神打发我到你们这里来。』他们若问我说：『他叫什么名字？』我要对他们说什么呢？」","notes":[]},{"n":14,"t":"神对摩西说：「我是自有永有的」；又说：「你要对以色列人这样说：『那自有的打发我到你们这里来。』」","notes":[]},{"n":15,"t":"神又对摩西说：「你要对以色列人这样说：『耶和华—你们祖宗的神，就是亚伯拉罕的神，以撒的神，雅各的神，打发我到你们这里来。』耶和华是我的名，直到永远；这也是我的纪念，直到万代。","notes":[]},{"n":16,"t":"你去招聚以色列的长老，对他们说：『耶和华—你们祖宗的神，就是亚伯拉罕的神，以撒的神，雅各的神，向我显现，说：我实在眷顾了你们，我也看见埃及人怎样待你们。","notes":[]},{"n":17,"t":"我也说：要将你们从埃及的困苦中领出来，往迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人的地去，就是到流奶与蜜之地。』","notes":[]},{"n":18,"t":"他们必听你的话。你和以色列的长老要去见埃及王，对他说：『耶和华—希伯来人的神遇见了我们，现在求你容我们往旷野去，走三天的路程，为要祭祀耶和华—我们的神。』","notes":[]},{"n":19,"t":"我知道虽用大能的手，埃及王也不容你们去。","notes":[]},{"n":20,"t":"我必伸手在埃及中间施行我一切的奇事，攻击那地，然后他才容你们去。","notes":[]},{"n":21,"t":"我必叫你们在埃及人眼前蒙恩，你们去的时候就不至于空手而去。","notes":[]},{"n":22,"t":"但各妇女必向她的邻舍，并居住在她家里的女人，要金器银器和衣裳，好给你们的儿女穿戴。这样你们就把埃及人的财物夺去了。」","notes":[]}]},"4":{"heading":"神赐摩西行神迹的权能","verses":[{"n":1,"t":"摩西回答说：「他们必不信我，也不听我的话，必说：『耶和华并没有向你显现。』」","notes":[]},{"n":2,"t":"耶和华对摩西说：「你手里是什么？」他说：「是杖。」","notes":[]},{"n":3,"t":"耶和华说：「丢在地上。」他一丢下去，就变作蛇；摩西便跑开。","notes":[]},{"n":4,"t":"耶和华对摩西说：「伸出手来，拿住它的尾巴，它必在你手中仍变为杖；","notes":[]},{"n":5,"t":"如此好叫他们信耶和华—他们祖宗的神，就是亚伯拉罕的神，以撒的神，雅各的神，是向你显现了。」","notes":[]},{"n":6,"t":"耶和华又对他说：「把手放在怀里。」他就把手放在怀里，及至抽出来，不料，手长了大麻风，有雪那样白。","notes":[]},{"n":7,"t":"耶和华说：「再把手放在怀里。」他就再把手放在怀里，及至从怀里抽出来，不料，手已经复原，与周身的肉一样；","notes":[]},{"n":8,"t":"又说：「倘或他们不听你的话，也不信头一个神迹，他们必信第二个神迹。","notes":[]},{"n":9,"t":"这两个神迹若都不信，也不听你的话，你就从河里取些水，倒在旱地上，你从河里取的水必在旱地上变作血。」","notes":[]},{"n":10,"t":"摩西对耶和华说：「主啊，我素日不是能言的人，就是从你对仆人说话以后，也是这样。我本是拙口笨舌的。」","notes":[]},{"n":11,"t":"耶和华对他说：「谁造人的口呢？谁使人口哑、耳聋、目明、眼瞎呢？岂不是我—耶和华吗？","notes":[]},{"n":12,"t":"现在去吧，我必赐你口才，指教你所当说的话。」","notes":[]},{"n":13,"t":"摩西说：「主啊，你愿意打发谁，就打发谁去吧！」","notes":[]},{"n":14,"t":"耶和华向摩西发怒说：「不是有你的哥哥利未人亚伦吗？我知道他是能言的；现在他出来迎接你，他一见你，心里就欢喜。","notes":[]},{"n":15,"t":"你要将当说的话传给他；我也要赐你和他口才，又要指教你们所当行的事。","notes":[]},{"n":16,"t":"他要替你对百姓说话；你要以他当作口，他要以你当作神。","notes":[]},{"n":17,"t":"你手里要拿这杖，好行神迹。」","notes":[]},{"n":18,"t":"于是，摩西回到他岳父叶忒罗那里，对他说：「求你容我回去见我在埃及的弟兄，看他们还在不在。」叶忒罗对摩西说：「你可以平平安安地去吧！」","notes":[],"heads":["摩西返回埃及"]},{"n":19,"t":"耶和华在米甸对摩西说：「你要回埃及去，因为寻索你命的人都死了。」","notes":[]},{"n":20,"t":"摩西就带着妻子和两个儿子，叫他们骑上驴，回埃及地去。摩西手里拿着神的杖。","notes":[]},{"n":21,"t":"耶和华对摩西说：「你回到埃及的时候，要留意将我指示你的一切奇事行在法老面前。但我要使他的心刚硬，他必不容百姓去。","notes":["或译：任凭；下同"]},{"n":22,"t":"你要对法老说：『耶和华这样说：以色列是我的儿子，我的长子。","notes":[]},{"n":23,"t":"我对你说过：容我的儿子去，好事奉我。你还是不肯容他去。看哪，我要杀你的长子。』」","notes":[]},{"n":24,"t":"摩西在路上住宿的地方，耶和华遇见他，想要杀他。","notes":[]},{"n":25,"t":"西坡拉就拿一块火石，割下他儿子的阳皮，丢在摩西脚前，说：「你真是我的血郎了。」","notes":[]},{"n":26,"t":"这样，耶和华才放了他。西坡拉说：「你因割礼就是血郎了。」","notes":[]},{"n":27,"t":"耶和华对亚伦说：「你往旷野去迎接摩西。」他就去，在神的山遇见摩西，和他亲嘴。","notes":[]},{"n":28,"t":"摩西将耶和华打发他所说的言语和嘱咐他所行的神迹都告诉了亚伦。","notes":[]},{"n":29,"t":"摩西、亚伦就去招聚以色列的众长老。","notes":[]},{"n":30,"t":"亚伦将耶和华对摩西所说的一切话述说了一遍，又在百姓眼前行了那些神迹，","notes":[]},{"n":31,"t":"百姓就信了。以色列人听见耶和华眷顾他们，鉴察他们的困苦，就低头下拜。","notes":[]}]},"5":{"heading":"摩西和亚伦见埃及王","verses":[{"n":1,"t":"后来摩西、亚伦去对法老说：「耶和华—以色列的神这样说：『容我的百姓去，在旷野向我守节。』」","notes":[]},{"n":2,"t":"法老说：「耶和华是谁，使我听他的话，容以色列人去呢？我不认识耶和华，也不容以色列人去！」","notes":[]},{"n":3,"t":"他们说：「希伯来人的神遇见了我们。求你容我们往旷野去，走三天的路程，祭祀耶和华—我们的神，免得他用瘟疫、刀兵攻击我们。」","notes":[]},{"n":4,"t":"埃及王对他们说：「摩西、亚伦！你们为什么叫百姓旷工呢？你们去担你们的担子吧！」","notes":[]},{"n":5,"t":"又说：「看哪，这地的以色列人如今众多，你们竟叫他们歇下担子！」","notes":[]},{"n":6,"t":"当天，法老吩咐督工的和官长说：","notes":[]},{"n":7,"t":"「你们不可照常把草给百姓做砖，叫他们自己去捡草。","notes":[]},{"n":8,"t":"他们素常做砖的数目，你们仍旧向他们要，一点不可减少；因为他们是懒惰的，所以呼求说：『容我们去祭祀我们的神。』","notes":[]},{"n":9,"t":"你们要把更重的工夫加在这些人身上，叫他们劳碌，不听虚谎的言语。」","notes":[]},{"n":10,"t":"督工的和官长出来对百姓说：「法老这样说：『我不给你们草。","notes":[]},{"n":11,"t":"你们自己在哪里能找草，就往那里去找吧！但你们的工一点不可减少。』」","notes":[]},{"n":12,"t":"于是百姓散在埃及遍地，捡碎秸当作草。","notes":[]},{"n":13,"t":"督工的催着说：「你们一天当完一天的工，与先前有草一样。」","notes":[]},{"n":14,"t":"法老督工的，责打他所派以色列人的官长，说：「你们昨天今天为什么没有照向来的数目做砖、完你们的工作呢？」","notes":[]},{"n":15,"t":"以色列人的官长就来哀求法老说：「为什么这样待你的仆人？","notes":[]},{"n":16,"t":"督工的不把草给仆人，并且对我们说：『做砖吧！』看哪，你仆人挨了打，其实是你百姓的错。」","notes":[]},{"n":17,"t":"但法老说：「你们是懒惰的！你们是懒惰的！所以说：『容我们去祭祀耶和华。』","notes":[]},{"n":18,"t":"现在你们去做工吧！草是不给你们的，砖却要如数交纳。」","notes":[]},{"n":19,"t":"以色列人的官长听说「你们每天做砖的工作一点不可减少」，就知道是遭遇祸患了。","notes":[]},{"n":20,"t":"他们离了法老出来，正遇见摩西、亚伦站在对面，","notes":[]},{"n":21,"t":"就向他们说：「愿耶和华鉴察你们，施行判断；因你们使我们在法老和他臣仆面前有了臭名，把刀递在他们手中杀我们。」","notes":[]},{"n":22,"t":"摩西回到耶和华那里，说：「主啊，你为什么苦待这百姓呢？为什么打发我去呢？","notes":[],"heads":["摩西向耶和华诉苦"]},{"n":23,"t":"自从我去见法老，奉你的名说话，他就苦待这百姓，你一点也没有拯救他们。」","notes":[]}]},"6":{"heading":"神呼召摩西","verses":[{"n":1,"t":"耶和华对摩西说：「现在你必看见我向法老所行的事，使他因我大能的手容以色列人去，且把他们赶出他的地。」","notes":[]},{"n":2,"t":"神晓谕摩西说：「我是耶和华。","notes":[]},{"n":3,"t":"我从前向亚伯拉罕、以撒、雅各显现为全能的神；至于我名耶和华，他们未曾知道。","notes":[]},{"n":4,"t":"我与他们坚定所立的约，要把他们寄居的迦南地赐给他们。","notes":[]},{"n":5,"t":"我也听见以色列人被埃及人苦待的哀声，我也记念我的约。","notes":[]},{"n":6,"t":"所以你要对以色列人说：『我是耶和华；我要用伸出来的膀臂重重地刑罚埃及人，救赎你们脱离他们的重担，不做他们的苦工。","notes":[]},{"n":7,"t":"我要以你们为我的百姓，我也要作你们的神。你们要知道我是耶和华—你们的神，是救你们脱离埃及人之重担的。","notes":[]},{"n":8,"t":"我起誓应许给亚伯拉罕、以撒、雅各的那地，我要把你们领进去，将那地赐给你们为业。我是耶和华。』」","notes":[]},{"n":9,"t":"摩西将这话告诉以色列人，只是他们因苦工愁烦，不肯听他的话。","notes":[]},{"n":10,"t":"耶和华晓谕摩西说：","notes":[]},{"n":11,"t":"「你进去对埃及王法老说，要容以色列人出他的地。」","notes":[]},{"n":12,"t":"摩西在耶和华面前说：「以色列人尚且不听我的话，法老怎肯听我这拙口笨舌的人呢？」","notes":[]},{"n":13,"t":"耶和华吩咐摩西、亚伦往以色列人和埃及王法老那里去，把以色列人从埃及地领出来。","notes":[]},{"n":14,"t":"以色列人家长的名字记在下面。以色列长子吕便的儿子是哈诺、法路、希斯伦、迦米；这是吕便的各家。","notes":[],"heads":["摩西和亚伦的族谱"]},{"n":15,"t":"西缅的儿子是耶母利、雅悯、阿辖、雅斤、琐辖，和迦南女子的儿子扫罗；这是西缅的各家。","notes":[]},{"n":16,"t":"利未众子的名字按着他们的后代记在下面：就是革顺、哥辖、米拉利。利未一生的岁数是一百三十七岁。","notes":[]},{"n":17,"t":"革顺的儿子按着家室是立尼、示每。","notes":[]},{"n":18,"t":"哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛。哥辖一生的岁数是一百三十三岁。","notes":[]},{"n":19,"t":"米拉利的儿子是抹利和母示；这是利未的家，都按着他们的后代。","notes":[]},{"n":20,"t":"暗兰娶了他父亲的妹妹约基别为妻，她给他生了亚伦和摩西。暗兰一生的岁数是一百三十七岁。","notes":[]},{"n":21,"t":"以斯哈的儿子是可拉、尼斐、细基利。","notes":[]},{"n":22,"t":"乌薛的儿子是米沙利、以利撒反、西提利。","notes":[]},{"n":23,"t":"亚伦娶了亚米拿达的女儿，拿顺的妹妹，以利沙巴为妻，她给他生了拿答、亚比户、以利亚撒、以他玛。","notes":[]},{"n":24,"t":"可拉的儿子是亚惜、以利加拿、亚比亚撒；这是可拉的各家。","notes":[]},{"n":25,"t":"亚伦的儿子以利亚撒娶了普铁的一个女儿为妻，她给他生了非尼哈。这是利未人的家长，都按着他们的家。","notes":[]},{"n":26,"t":"耶和华说：「将以色列人按着他们的军队从埃及地领出来。」这是对那亚伦、摩西说的。","notes":[]},{"n":27,"t":"对埃及王法老说要将以色列人从埃及领出来的，就是这摩西、亚伦。","notes":[]},{"n":28,"t":"当耶和华在埃及地对摩西说话的日子，","notes":[],"heads":["耶和华吩咐摩西和亚伦"]},{"n":29,"t":"他向摩西说：「我是耶和华；我对你说的一切话，你都要告诉埃及王法老。」","notes":[]},{"n":30,"t":"摩西在耶和华面前说：「看哪，我是拙口笨舌的人，法老怎肯听我呢？」","notes":[]}]},"7":{"heading":"亚伦的杖","verses":[{"n":1,"t":"耶和华对摩西说：「我使你在法老面前代替神，你的哥哥亚伦是替你说话的。","notes":[]},{"n":2,"t":"凡我所吩咐你的，你都要说。你的哥哥亚伦要对法老说，容以色列人出他的地。","notes":[]},{"n":3,"t":"我要使法老的心刚硬，也要在埃及地多行神迹奇事。","notes":[]},{"n":4,"t":"但法老必不听你们；我要伸手重重地刑罚埃及，将我的军队以色列民从埃及地领出来。","notes":[]},{"n":5,"t":"我伸手攻击埃及，将以色列人从他们中间领出来的时候，埃及人就要知道我是耶和华。」","notes":[]},{"n":6,"t":"摩西、亚伦这样行；耶和华怎样吩咐他们，他们就照样行了。","notes":[]},{"n":7,"t":"摩西、亚伦与法老说话的时候，摩西八十岁，亚伦八十三岁。","notes":[]},{"n":8,"t":"耶和华晓谕摩西、亚伦说：","notes":[]},{"n":9,"t":"「法老若对你们说：『你们行件奇事吧！』你就吩咐亚伦说：『把杖丢在法老面前，使杖变作蛇。』」","notes":[]},{"n":10,"t":"摩西、亚伦进去见法老，就照耶和华所吩咐的行。亚伦把杖丢在法老和臣仆面前，杖就变作蛇。","notes":[]},{"n":11,"t":"于是法老召了博士和术士来；他们是埃及行法术的，也用邪术照样而行。","notes":[]},{"n":12,"t":"他们各人丢下自己的杖，杖就变作蛇；但亚伦的杖吞了他们的杖。","notes":[]},{"n":13,"t":"法老心里刚硬，不肯听从摩西、亚伦，正如耶和华所说的。","notes":[]},{"n":14,"t":"耶和华对摩西说：「法老心里固执，不肯容百姓去。","notes":[],"heads":["埃及遭灾 血灾"]},{"n":15,"t":"明日早晨，他出来往水边去，你要往河边迎接他，手里要拿着那变过蛇的杖，","notes":[]},{"n":16,"t":"对他说：『耶和华—希伯来人的神打发我来见你，说：容我的百姓去，好在旷野事奉我。到如今你还是不听。","notes":[]},{"n":17,"t":"耶和华这样说：我要用我手里的杖击打河中的水，水就变作血；因此，你必知道我是耶和华。","notes":[]},{"n":18,"t":"河里的鱼必死，河也要腥臭，埃及人就要厌恶吃这河里的水。』」","notes":[]},{"n":19,"t":"耶和华晓谕摩西说：「你对亚伦说：『把你的杖伸在埃及所有的水以上，就是在他们的江、河、池、塘以上，叫水都变作血。在埃及遍地，无论在木器中，石器中，都必有血。』」","notes":[]},{"n":20,"t":"摩西、亚伦就照耶和华所吩咐的行。亚伦在法老和臣仆眼前举杖击打河里的水，河里的水都变作血了。","notes":[]},{"n":21,"t":"河里的鱼死了，河也腥臭了，埃及人就不能吃这河里的水；埃及遍地都有了血。","notes":[]},{"n":22,"t":"埃及行法术的，也用邪术照样而行。法老心里刚硬，不肯听摩西、亚伦，正如耶和华所说的。","notes":[]},{"n":23,"t":"法老转身进宫，也不把这事放在心上。","notes":[]},{"n":24,"t":"埃及人都在河的两边挖地，要得水喝，因为他们不能喝这河里的水。","notes":[]},{"n":25,"t":"耶和华击打河以后满了七天。","notes":[]}]},"8":{"heading":"—蛙灾","verses":[{"n":1,"t":"耶和华吩咐摩西说：「你进去见法老，对他说：『耶和华这样说：容我的百姓去，好事奉我。","notes":[]},{"n":2,"t":"你若不肯容他们去，我必使青蛙糟蹋你的四境。","notes":[]},{"n":3,"t":"河里要滋生青蛙；这青蛙要上来进你的宫殿和你的卧房，上你的床榻，进你臣仆的房屋，上你百姓的身上，进你的炉灶和你的抟面盆，","notes":[]},{"n":4,"t":"又要上你和你百姓并你众臣仆的身上。』」","notes":[]},{"n":5,"t":"耶和华晓谕摩西说：「你对亚伦说：『把你的杖伸在江、河、池以上，使青蛙到埃及地上来。』」","notes":[]},{"n":6,"t":"亚伦便伸杖在埃及的诸水以上，青蛙就上来，遮满了埃及地。","notes":[]},{"n":7,"t":"行法术的也用他们的邪术照样而行，叫青蛙上了埃及地。","notes":[]},{"n":8,"t":"法老召了摩西、亚伦来，说：「请你们求耶和华使这青蛙离开我和我的民，我就容百姓去祭祀耶和华。」","notes":[]},{"n":9,"t":"摩西对法老说：「任凭你吧，我要何时为你和你的臣仆并你的百姓祈求，除灭青蛙离开你和你的宫殿只留在河里呢？」","notes":[]},{"n":10,"t":"他说：「明天。」摩西说：「可以照你的话吧，好叫你知道没有像耶和华—我们神的。","notes":[]},{"n":11,"t":"青蛙要离开你和你的宫殿，并你的臣仆与你的百姓，只留在河里。」","notes":[]},{"n":12,"t":"于是摩西、亚伦离开法老出去。摩西为扰害法老的青蛙呼求耶和华。","notes":[]},{"n":13,"t":"耶和华就照摩西的话行。凡在房里、院中、田间的青蛙都死了。","notes":[]},{"n":14,"t":"众人把青蛙聚拢成堆，遍地就都腥臭。","notes":[]},{"n":15,"t":"但法老见灾祸松缓，就硬着心，不肯听他们，正如耶和华所说的。","notes":[]},{"n":16,"t":"耶和华吩咐摩西说：「你对亚伦说：『伸出你的杖击打地上的尘土，使尘土在埃及遍地变作虱子。』」","notes":["或译：虼蚤；下同"],"heads":["虱灾"]},{"n":17,"t":"他们就这样行。亚伦伸杖击打地上的尘土，就在人身上和牲畜身上有了虱子；埃及遍地的尘土都变成虱子了。","notes":[]},{"n":18,"t":"行法术的也用邪术要生出虱子来，却是不能。于是在人身上和牲畜身上都有了虱子。","notes":[]},{"n":19,"t":"行法术的就对法老说：「这是神的手段。」法老心里刚硬，不肯听摩西、亚伦，正如耶和华所说的。","notes":[]},{"n":20,"t":"耶和华对摩西说：「你清早起来，法老来到水边，你站在他面前，对他说：『耶和华这样说：容我的百姓去，好事奉我。","notes":[],"heads":["蝇灾"]},{"n":21,"t":"你若不容我的百姓去，我要叫成群的苍蝇到你和你臣仆并你百姓的身上，进你的房屋，并且埃及人的房屋和他们所住的地都要满了成群的苍蝇。","notes":[]},{"n":22,"t":"当那日，我必分别我百姓所住的歌珊地，使那里没有成群的苍蝇，好叫你知道我是天下的耶和华。","notes":[]},{"n":23,"t":"我要将我的百姓和你的百姓分别出来。明天必有这神迹。』」","notes":[]},{"n":24,"t":"耶和华就这样行。苍蝇成了大群，进入法老的宫殿，和他臣仆的房屋；埃及遍地就因这成群的苍蝇败坏了。","notes":[]},{"n":25,"t":"法老召了摩西、亚伦来，说：「你们去，在这地祭祀你们的神吧！」","notes":[]},{"n":26,"t":"摩西说：「这样行本不相宜，因为我们要把埃及人所厌恶的祭祀耶和华—我们的神；若把埃及人所厌恶的在他们眼前献为祭，他们岂不拿石头打死我们吗？","notes":[]},{"n":27,"t":"我们要往旷野去，走三天的路程，照着耶和华—我们神所要吩咐我们的祭祀他。」","notes":[]},{"n":28,"t":"法老说：「我容你们去，在旷野祭祀耶和华—你们的神；只是不要走得很远。求你们为我祈祷。」","notes":[]},{"n":29,"t":"摩西说：「我要出去求耶和华，使成群的苍蝇明天离开法老和法老的臣仆并法老的百姓；法老却不可再行诡诈，不容百姓去祭祀耶和华。」","notes":[]},{"n":30,"t":"于是摩西离开法老去求耶和华。","notes":[]},{"n":31,"t":"耶和华就照摩西的话行，叫成群的苍蝇离开法老和他的臣仆并他的百姓，一个也没有留下。","notes":[]},{"n":32,"t":"这一次法老又硬着心，不容百姓去。","notes":[]}]},"9":{"heading":"畜疫之灾","verses":[{"n":1,"t":"耶和华吩咐摩西说：「你进去见法老，对他说：『耶和华—希伯来人的神这样说：容我的百姓去，好事奉我。","notes":[]},{"n":2,"t":"你若不肯容他们去，仍旧强留他们，","notes":[]},{"n":3,"t":"耶和华的手加在你田间的牲畜上，就是在马、驴、骆驼、牛群、羊群上，必有重重的瘟疫。","notes":[]},{"n":4,"t":"耶和华要分别以色列的牲畜和埃及的牲畜，凡属以色列人的，一样都不死。』」","notes":[]},{"n":5,"t":"耶和华就定了时候，说：「明天耶和华必在此地行这事。」","notes":[]},{"n":6,"t":"第二天，耶和华就行这事。埃及的牲畜几乎都死了，只是以色列人的牲畜，一个都没有死。","notes":[]},{"n":7,"t":"法老打发人去看，谁知以色列人的牲畜连一个都没有死。法老的心却是固执，不容百姓去。","notes":[]},{"n":8,"t":"耶和华吩咐摩西、亚伦说：「你们取几捧炉灰，摩西要在法老面前向天扬起来。","notes":[],"heads":["疮灾"]},{"n":9,"t":"这灰要在埃及全地变作尘土，在人身上和牲畜身上成了起泡的疮。」","notes":[]},{"n":10,"t":"摩西、亚伦取了炉灰，站在法老面前。摩西向天扬起来，就在人身上和牲畜身上成了起泡的疮。","notes":[]},{"n":11,"t":"行法术的在摩西面前站立不住，因为在他们身上和一切埃及人身上都有这疮。","notes":[]},{"n":12,"t":"耶和华使法老的心刚硬，不听他们，正如耶和华对摩西所说的。","notes":[]},{"n":13,"t":"耶和华对摩西说：「你清早起来，站在法老面前，对他说：『耶和华—希伯来人的神这样说：容我的百姓去，好事奉我。","notes":[],"heads":["雹灾"]},{"n":14,"t":"因为这一次我要叫一切的灾殃临到你和你臣仆并你百姓的身上，叫你知道在普天下没有像我的。","notes":[]},{"n":15,"t":"我若伸手用瘟疫攻击你和你的百姓，你早就从地上除灭了。","notes":[]},{"n":16,"t":"其实，我叫你存立，是特要向你显我的大能，并要使我的名传遍天下。","notes":[]},{"n":17,"t":"你还向我的百姓自高，不容他们去吗？","notes":[]},{"n":18,"t":"到明天约在这时候，我必叫重大的冰雹降下，自从埃及开国以来，没有这样的冰雹。","notes":[]},{"n":19,"t":"现在你要打发人把你的牲畜和你田间一切所有的催进来；凡在田间不收回家的，无论是人是牲畜，冰雹必降在他们身上，他们就必死。』」","notes":[]},{"n":20,"t":"法老的臣仆中，惧怕耶和华这话的，便叫他的奴仆和牲畜跑进家来。","notes":[]},{"n":21,"t":"但那不把耶和华这话放在心上的，就将他的奴仆和牲畜留在田里。","notes":[]},{"n":22,"t":"耶和华对摩西说：「你向天伸杖，使埃及遍地的人身上和牲畜身上，并田间各样菜蔬上，都有冰雹。」","notes":[]},{"n":23,"t":"摩西向天伸杖，耶和华就打雷下雹，有火闪到地上；耶和华下雹在埃及地上。","notes":[]},{"n":24,"t":"那时，雹与火搀杂，甚是厉害，自从埃及成国以来，遍地没有这样的。","notes":[]},{"n":25,"t":"在埃及遍地，雹击打了田间所有的人和牲畜，并一切的菜蔬，又打坏田间一切的树木。","notes":[]},{"n":26,"t":"惟独以色列人所住的歌珊地没有冰雹。","notes":[]},{"n":27,"t":"法老打发人召摩西、亚伦来，对他们说：「这一次我犯了罪了。耶和华是公义的；我和我的百姓是邪恶的。","notes":[]},{"n":28,"t":"这雷轰和冰雹已经够了。请你们求耶和华，我就容你们去，不再留住你们。」","notes":[]},{"n":29,"t":"摩西对他说：「我一出城，就要向耶和华举手祷告；雷必止住，也不再有冰雹，叫你知道全地都是属耶和华的。","notes":[]},{"n":30,"t":"至于你和你的臣仆，我知道你们还是不惧怕耶和华神。」（","notes":[]},{"n":31,"t":"那时，麻和大麦被雹击打；因为大麦已经吐穗，麻也开了花。","notes":[]},{"n":32,"t":"只是小麦和粗麦没有被击打，因为还没有长成。）","notes":[]},{"n":33,"t":"摩西离了法老出城，向耶和华举手祷告；雷和雹就止住，雨也不再浇在地上了。","notes":[]},{"n":34,"t":"法老见雨和雹与雷止住，就越发犯罪；他和他的臣仆都硬着心。","notes":[]},{"n":35,"t":"法老的心刚硬，不容以色列人去，正如耶和华借着摩西所说的。","notes":[]}]},"10":{"heading":"蝗灾","verses":[{"n":1,"t":"耶和华对摩西说：「你进去见法老。我使他和他臣仆的心刚硬，为要在他们中间显我这些神迹，","notes":[]},{"n":2,"t":"并要叫你将我向埃及人所做的事，和在他们中间所行的神迹，传于你儿子和你孙子的耳中，好叫你们知道我是耶和华。」","notes":[]},{"n":3,"t":"摩西、亚伦就进去见法老，对他说：「耶和华—希伯来人的神这样说：『你在我面前不肯自卑要到几时呢？容我的百姓去，好事奉我。","notes":[]},{"n":4,"t":"你若不肯容我的百姓去，明天我要使蝗虫进入你的境内，","notes":[]},{"n":5,"t":"遮满地面，甚至看不见地，并且吃那冰雹所剩的和田间所长的一切树木。","notes":[]},{"n":6,"t":"你的宫殿和你众臣仆的房屋，并一切埃及人的房屋，都要被蝗虫占满了；自从你祖宗和你祖宗的祖宗在世以来，直到今日，没有见过这样的灾。』」摩西就转身离开法老出去。","notes":[]},{"n":7,"t":"法老的臣仆对法老说：「这人为我们的网罗要到几时呢？容这些人去事奉耶和华—他们的神吧！埃及已经败坏了，你还不知道吗？」","notes":[]},{"n":8,"t":"于是摩西、亚伦被召回来见法老；法老对他们说：「你们去事奉耶和华—你们的神；但那要去的是谁呢？」","notes":[]},{"n":9,"t":"摩西说：「我们要和我们老的少的、儿子女儿同去，且把羊群牛群一同带去，因为我们务要向耶和华守节。」","notes":[]},{"n":10,"t":"法老对他们说：「我容你们和你们妇人孩子去的时候，耶和华与你们同在吧！你们要谨慎；因为有祸在你们眼前，","notes":["或译：你们存着恶意"]},{"n":11,"t":"不可都去！你们这壮年人去事奉耶和华吧，因为这是你们所求的。」于是把他们从法老面前撵出去。","notes":[]},{"n":12,"t":"耶和华对摩西说：「你向埃及地伸杖，使蝗虫到埃及地上来，吃地上一切的菜蔬，就是冰雹所剩的。」","notes":[]},{"n":13,"t":"摩西就向埃及地伸杖，那一昼一夜，耶和华使东风刮在埃及地上；到了早晨，东风把蝗虫刮了来。","notes":[]},{"n":14,"t":"蝗虫上来，落在埃及的四境，甚是厉害；以前没有这样的，以后也必没有。","notes":[]},{"n":15,"t":"因为这蝗虫遮满地面，甚至地都黑暗了，又吃地上一切的菜蔬和冰雹所剩树上的果子。埃及遍地，无论是树木，是田间的菜蔬，连一点青的也没有留下。","notes":[]},{"n":16,"t":"于是法老急忙召了摩西、亚伦来，说：「我得罪耶和华—你们的神，又得罪了你们。","notes":[]},{"n":17,"t":"现在求你，只这一次，饶恕我的罪，求耶和华—你们的神使我脱离这一次的死亡。」","notes":[]},{"n":18,"t":"摩西就离开法老去求耶和华。","notes":[]},{"n":19,"t":"耶和华转了极大的西风，把蝗虫刮起，吹入红海；在埃及的四境连一个也没有留下。","notes":[]},{"n":20,"t":"但耶和华使法老的心刚硬，不容以色列人去。","notes":[]},{"n":21,"t":"耶和华对摩西说：「你向天伸杖，使埃及地黑暗；这黑暗似乎摸得着。」","notes":[],"heads":["黑暗之灾"]},{"n":22,"t":"摩西向天伸杖，埃及遍地就乌黑了三天。","notes":[]},{"n":23,"t":"三天之久，人不能相见，谁也不敢起来离开本处；惟有以色列人家中都有亮光。","notes":[]},{"n":24,"t":"法老就召摩西来，说：「你们去事奉耶和华；只是你们的羊群牛群要留下；你们的妇人孩子可以和你们同去。」","notes":[]},{"n":25,"t":"摩西说：「你总要把祭物和燔祭牲交给我们，使我们可以祭祀耶和华—我们的神。","notes":[]},{"n":26,"t":"我们的牲畜也要带去，连一蹄也不留下；因为我们要从其中取出来，事奉耶和华—我们的神。我们未到那里，还不知道用什么事奉耶和华。」","notes":[]},{"n":27,"t":"但耶和华使法老的心刚硬，不肯容他们去。","notes":[]},{"n":28,"t":"法老对摩西说：「你离开我去吧，你要小心，不要再见我的面！因为你见我面的那日你就必死！」","notes":[]},{"n":29,"t":"摩西说：「你说得好！我必不再见你的面了。」","notes":[]}]},"11":{"heading":"所有头胎的都死","verses":[{"n":1,"t":"耶和华对摩西说：「我再使一样的灾殃临到法老和埃及，然后他必容你们离开这地。他容你们去的时候，总要催逼你们都从这地出去。","notes":[]},{"n":2,"t":"你要传于百姓的耳中，叫他们男女各人向邻舍要金器银器。」","notes":[]},{"n":3,"t":"耶和华叫百姓在埃及人眼前蒙恩，并且摩西在埃及地、法老臣仆，和百姓的眼中看为极大。","notes":[]},{"n":4,"t":"摩西说：「耶和华这样说：『约到半夜，我必出去巡行埃及遍地。","notes":[]},{"n":5,"t":"凡在埃及地，从坐宝座的法老直到磨子后的婢女所有的长子，以及一切头生的牲畜，都必死。","notes":[]},{"n":6,"t":"埃及遍地必有大哀号；从前没有这样的，后来也必没有。","notes":[]},{"n":7,"t":"至于以色列中，无论是人是牲畜，连狗也不敢向他们摇舌，好叫你们知道耶和华是将埃及人和以色列人分别出来。』","notes":[]},{"n":8,"t":"你这一切臣仆都要俯伏来见我，说：『求你和跟从你的百姓都出去』，然后我要出去。」于是，摩西气忿忿地离开法老，出去了。","notes":[]},{"n":9,"t":"耶和华对摩西说：「法老必不听你 们，使我的奇事在埃及地多起来。」","notes":[]},{"n":10,"t":"摩西、亚伦在法老面前行了这一切奇事；耶和华使法老的心刚硬，不容以色列人出离他的地。","notes":[]}]},"12":{"heading":"逾越节","verses":[{"n":1,"t":"耶和华在埃及地晓谕摩西、亚伦说：","notes":[]},{"n":2,"t":"「你们要以本月为正月，为一年之首。","notes":[]},{"n":3,"t":"你们吩咐以色列全会众说：本月初十日，各人要按着父家取羊羔，一家一只。","notes":[]},{"n":4,"t":"若是一家的人太少，吃不了一只羊羔，本人就要和他隔壁的邻舍共取一只。你们预备羊羔，要按着人数和饭量计算。","notes":[]},{"n":5,"t":"要无残疾、一岁的公羊羔，你们或从绵羊里取，或从山羊里取，都可以。","notes":[]},{"n":6,"t":"要留到本月十四日，在黄昏的时候，以色列全会众把羊羔宰了。","notes":[]},{"n":7,"t":"各家要取点血，涂在吃羊羔的房屋左右的门框上和门楣上。","notes":[]},{"n":8,"t":"当夜要吃羊羔的肉；用火烤了，与无酵饼和苦菜同吃。","notes":[]},{"n":9,"t":"不可吃生的，断不可吃水煮的，要带着头、腿、五脏，用火烤了吃。","notes":[]},{"n":10,"t":"不可剩下一点留到早晨；若留到早晨，要用火烧了。","notes":[]},{"n":11,"t":"你们吃羊羔当腰间束带，脚上穿鞋，手中拿杖，赶紧地吃；这是耶和华的逾越节。","notes":[]},{"n":12,"t":"因为那夜我要巡行埃及地，把埃及地一切头生的，无论是人是牲畜，都击杀了，又要败坏埃及一切的神。我是耶和华。","notes":[]},{"n":13,"t":"这血要在你们所住的房屋上作记号；我一见这血，就越过你们去。我击杀埃及地头生的时候，灾殃必不临到你们身上灭你们。」","notes":[]},{"n":14,"t":"「你们要记念这日，守为耶和华的节，作为你们世世代代永远的定例。","notes":[],"heads":["无酵节"]},{"n":15,"t":"你们要吃无酵饼七日。头一日要把酵从你们各家中除去；因为从头一日起，到第七日为止，凡吃有酵之饼的，必从以色列中剪除。","notes":[]},{"n":16,"t":"头一日你们当有圣会，第七日也当有圣会。这两日之内，除了预备各人所要吃的以外，无论何工都不可做。","notes":[]},{"n":17,"t":"你们要守无酵节，因为我正当这日把你们的军队从埃及地领出来。所以，你们要守这日，作为世世代代永远的定例。","notes":[]},{"n":18,"t":"从正月十四日晚上，直到二十一日晚上，你们要吃无酵饼。","notes":[]},{"n":19,"t":"在你们各家中，七日之内不可有酵；因为凡吃有酵之物的，无论是寄居的，是本地的，必从以色列的会中剪除。","notes":[]},{"n":20,"t":"有酵的物，你们都不可吃；在你们一切住处要吃无酵饼。」","notes":[]},{"n":21,"t":"于是，摩西召了以色列的众长老来，对他们说：「你们要按着家口取出羊羔，把这逾越节的羊羔宰了。","notes":[],"heads":["第一个逾越节"]},{"n":22,"t":"拿一把牛膝草，蘸盆里的血，打在门楣上和左右的门框上。你们谁也不可出自己的房门，直到早晨。","notes":[]},{"n":23,"t":"因为耶和华要巡行击杀埃及人，他看见血在门楣上和左右的门框上，就必越过那门，不容灭命的进你们的房屋，击杀你们。","notes":[]},{"n":24,"t":"这例，你们要守着，作为你们和你们子孙永远的定例。","notes":[]},{"n":25,"t":"日后，你们到了耶和华按着所应许赐给你们的那地，就要守这礼。","notes":[]},{"n":26,"t":"你们的儿女问你们说：『行这礼是什么意思？』","notes":[]},{"n":27,"t":"你们就说：『这是献给耶和华逾越节的祭。当以色列人在埃及的时候，他击杀埃及人，越过以色列人的房屋，救了我们各家。』」于是百姓低头下拜。","notes":[]},{"n":28,"t":"耶和华怎样吩咐摩西、亚伦，以色列人就怎样行。","notes":[]},{"n":29,"t":"到了半夜，耶和华把埃及地所有的长子，就是从坐宝座的法老，直到被掳囚在监里之人的长子，以及一切头生的牲畜，尽都杀了。","notes":[],"heads":["头胎的被杀"]},{"n":30,"t":"法老和一切臣仆，并埃及众人，夜间都起来了。在埃及有大哀号，无一家不死一个人的。","notes":[]},{"n":31,"t":"夜间，法老召了摩西、亚伦来，说：「起来！连你们带以色列人，从我民中出去，依你们所说的，去事奉耶和华吧！","notes":[]},{"n":32,"t":"也依你们所说的，连羊群牛群带着走吧！并要为我祝福。」","notes":[]},{"n":33,"t":"埃及人催促百姓，打发他们快快出离那地，因为埃及人说：「我们都要死了。」","notes":[]},{"n":34,"t":"百姓就拿着没有酵的生面，把抟面盆包在衣服中，扛在肩头上。","notes":[]},{"n":35,"t":"以色列人照着摩西的话行，向埃及人要金器、银器，和衣裳。","notes":[]},{"n":36,"t":"耶和华叫百姓在埃及人眼前蒙恩，以致埃及人给他们所要的。他们就把埃及人的财物夺去了。","notes":[]},{"n":37,"t":"以色列人从兰塞起行，往疏割去；除了妇人孩子，步行的男人约有六十万。","notes":[],"heads":["以色列人出埃及"]},{"n":38,"t":"又有许多闲杂人，并有羊群牛群，和他们一同上去。","notes":[]},{"n":39,"t":"他们用埃及带出来的生面烤成无酵饼。这生面原没有发起；因为他们被催逼离开埃及，不能耽延，也没有为自己预备什么食物。","notes":[]},{"n":40,"t":"以色列人住在埃及共有四百三十年。","notes":[]},{"n":41,"t":"正满了四百三十年的那一天，耶和华的军队都从埃及地出来了。","notes":[]},{"n":42,"t":"这夜是耶和华的夜；因耶和华领他们出了埃及地，所以当向耶和华谨守，是以色列众人世世代代该谨守的。","notes":[]},{"n":43,"t":"耶和华对摩西、亚伦说：「逾越节的例是这样：外邦人都不可吃这羊羔。","notes":[],"heads":["逾越节的条例"]},{"n":44,"t":"但各人用银子买的奴仆，既受了割礼就可以吃。","notes":[]},{"n":45,"t":"寄居的和雇工人都不可吃。","notes":[]},{"n":46,"t":"应当在一个房子里吃；不可把一点肉从房子里带到外头去。羊羔的骨头一根也不可折断。","notes":[]},{"n":47,"t":"以色列全会众都要守这礼。","notes":[]},{"n":48,"t":"若有外人寄居在你们中间，愿向耶和华守逾越节，他所有的男子务要受割礼，然后才容他前来遵守，他也就像本地人一样；但未受割礼的，都不可吃这羊羔。","notes":[]},{"n":49,"t":"本地人和寄居在你们中间的外人同归一例。」","notes":[]},{"n":50,"t":"耶和华怎样吩咐摩西、亚伦，以色列众人就怎样行了。","notes":[]},{"n":51,"t":"正当那日，耶和华将以色列人按着他们的军队，从埃及地领出来。","notes":[]}]},"13":{"heading":"奉献头胎的","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「以色列中凡头生的，无论是人是牲畜，都是我的，要分别为圣归我。」","notes":[]},{"n":3,"t":"摩西对百姓说：「你们要记念从埃及为奴之家出来的这日，因为耶和华用大能的手将你们从这地方领出来。有酵的饼都不可吃。","notes":[],"heads":["除酵节"]},{"n":4,"t":"亚笔月间的这日是你们出来的日子。","notes":[]},{"n":5,"t":"将来耶和华领你进迦南人、赫人、亚摩利人、希未人、耶布斯人之地，就是他向你的祖宗起誓应许给你那流奶与蜜之地，那时你要在这月间守这礼。","notes":[]},{"n":6,"t":"你要吃无酵饼七日，到第七日要向耶和华守节。","notes":[]},{"n":7,"t":"这七日之久，要吃无酵饼；在你四境之内不可见有酵的饼，也不可见发酵的物。","notes":[]},{"n":8,"t":"当那日，你要告诉你的儿子说：『这是因耶和华在我出埃及的时候为我所行的事。","notes":[]},{"n":9,"t":"这要在你手上作记号，在你额上作纪念，使耶和华的律法常在你口中，因为耶和华曾用大能的手将你从埃及领出来。","notes":[]},{"n":10,"t":"所以你每年要按着日期守这例。』」","notes":[]},{"n":11,"t":"「将来，耶和华照他向你和你祖宗所起的誓将你领进迦南人之地，把这地赐给你，","notes":[],"heads":["长子"]},{"n":12,"t":"那时你要将一切头生的，并牲畜中头生的，归给耶和华；公的都要属耶和华。","notes":[]},{"n":13,"t":"凡头生的驴，你要用羊羔代赎；若不代赎，就要打折它的颈项。凡你儿子中头生的都要赎出来。","notes":[]},{"n":14,"t":"日后，你的儿子问你说：『这是什么意思？』你就说：『耶和华用大能的手将我们从埃及为奴之家领出来。","notes":[]},{"n":15,"t":"那时法老几乎不容我们去，耶和华就把埃及地所有头生的，无论是人是牲畜，都杀了。因此，我把一切头生的公牲畜献给耶和华为祭，但将头生的儿子都赎出来。","notes":[]},{"n":16,"t":"这要在你手上作记号，在你额上作经文，因为耶和华用大能的手将我们从埃及领出来。』」","notes":[]},{"n":17,"t":"法老容百姓去的时候，非利士地的道路虽近，神却不领他们从那里走；因为神说：「恐怕百姓遇见打仗后悔，就回埃及去。」","notes":[],"heads":["云柱和火柱"]},{"n":18,"t":"所以神领百姓绕道而行，走红海旷野的路。以色列人出埃及地，都带着兵器上去。","notes":[]},{"n":19,"t":"摩西把约瑟的骸骨一同带去；因为约瑟曾叫以色列人严严地起誓，对他们说：「神必眷顾你们，你们要把我的骸骨从这里一同带上去。」","notes":[]},{"n":20,"t":"他们从疏割起行，在旷野边的以倘安营。","notes":[]},{"n":21,"t":"日间，耶和华在云柱中领他们的路；夜间，在火柱中光照他们，使他们日夜都可以行走。","notes":[]},{"n":22,"t":"日间云柱，夜间火柱，总不离开百姓的面前。","notes":[]}]},"14":{"heading":"过红海","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「你吩咐以色列人转回，安营在比·哈希录前，密夺和海的中间，对着巴力· 洗分，靠近海边安营。","notes":[]},{"n":3,"t":"法老必说：『以色列人在地中绕迷了，旷野把他们困住了。』","notes":[]},{"n":4,"t":"我要使法老的心刚硬，他要追赶他们，我便在法老和他全军身上得荣耀；埃及人就知道我是耶和华。」于是以色列人这样行了。","notes":[]},{"n":5,"t":"有人告诉埃及王说：「百姓逃跑。」法老和他的臣仆就向百姓变心，说：「我们容以色列人去，不再服事我们，这做的是什么事呢？」","notes":[]},{"n":6,"t":"法老就预备他的车辆，带领军兵同去，","notes":[]},{"n":7,"t":"并带着六百辆特选的车和埃及所有的车，每辆都有车兵长。","notes":[]},{"n":8,"t":"耶和华使埃及王法老的心刚硬，他就追赶以色列人，因为以色列人是昂然无惧地出埃及。","notes":[]},{"n":9,"t":"埃及人追赶他们，法老一切的马匹、车辆、马兵，与军兵就在海边上，靠近比·哈希录，对着巴力·洗分，在他们安营的地方追上了。","notes":[]},{"n":10,"t":"法老临近的时候，以色列人举目看见埃及人赶来，就甚惧怕，向耶和华哀求。","notes":[]},{"n":11,"t":"他们对摩西说：「难道在埃及没有坟地，你把我们带来死在旷野吗？你为什么这样待我们，将我们从埃及领出来呢？","notes":[]},{"n":12,"t":"我们在埃及岂没有对你说过，不要搅扰我们，容我们服事埃及人吗？因为服事埃及人比死在旷野还好。」","notes":[]},{"n":13,"t":"摩西对百姓说：「不要惧怕，只管站住！看耶和华今天向你们所要施行的救恩。因为，你们今天所看见的埃及人必永远不再看见了。","notes":[]},{"n":14,"t":"耶和华必为你们争战；你们只管静默，不要作声。」","notes":[]},{"n":15,"t":"耶和华对摩西说：「你为什么向我哀求呢？你吩咐以色列人往前走。","notes":[]},{"n":16,"t":"你举手向海伸杖，把水分开。以色列人要下海中走干地。","notes":[]},{"n":17,"t":"我要使埃及人的心刚硬，他们就跟着下去。我要在法老和他的全军、车辆、马兵上得荣耀。","notes":[]},{"n":18,"t":"我在法老和他的车辆、马兵上得荣耀的时候，埃及人就知道我是耶和华了。」","notes":[]},{"n":19,"t":"在以色列营前行走神的使者，转到他们后边去；云柱也从他们前边转到他们后边立住。","notes":[]},{"n":20,"t":"在埃及营和以色列营中间有云柱，一边黑暗，一边发光，终夜两下不得相近。","notes":[]},{"n":21,"t":"摩西向海伸杖，耶和华便用大东风，使海水一夜退去，水便分开，海就成了干地。","notes":[]},{"n":22,"t":"以色列人下海中走干地，水在他们的左右作了墙垣。","notes":[]},{"n":23,"t":"埃及人追赶他们，法老一切的马匹、车辆，和马兵都跟着下到海中。","notes":[]},{"n":24,"t":"到了晨更的时候，耶和华从云火柱中向埃及的军兵观看，使埃及的军兵混乱了；","notes":[]},{"n":25,"t":"又使他们的车轮脱落，难以行走，以致埃及人说：「我们从以色列人面前逃跑吧！因耶和华为他们攻击我们了。」","notes":[]},{"n":26,"t":"耶和华对摩西说：「你向海伸杖，叫水仍合在埃及人并他们的车辆、马兵身上。」","notes":[]},{"n":27,"t":"摩西就向海伸杖，到了天一亮，海水仍旧复原。埃及人避水逃跑的时候，耶和华把他们推翻在海中，","notes":[]},{"n":28,"t":"水就回流，淹没了车辆和马兵。那些跟着以色列人下海法老的全军，连一个也没有剩下。","notes":[]},{"n":29,"t":"以色列人却在海中走干地；水在他们的左右作了墙垣。","notes":[]},{"n":30,"t":"当日，耶和华这样拯救以色列人脱离埃及人的手，以色列人看见埃及人的死尸都在海边了。","notes":[]},{"n":31,"t":"以色列人看见耶和华向埃及人所行的大事，就敬畏耶和华，又信服他和他的仆人摩西。","notes":[]}]},"15":{"heading":"摩西的歌","verses":[{"n":1,"t":"那时，摩西和以色列人向耶和华唱歌说：我要向耶和华歌唱，因他大大战胜，将马和骑马的投在海中。","notes":[]},{"n":2,"t":"耶和华是我的力量，我的诗歌，也成了我的拯救。这是我的神，我要赞美他，是我父亲的神，我要尊崇他。","notes":[]},{"n":3,"t":"耶和华是战士；他的名是耶和华。","notes":[]},{"n":4,"t":"法老的车辆、军兵，耶和华已抛在海中；他特选的军长都沉于红海。","notes":[]},{"n":5,"t":"深水淹没他们；他们如同石头坠到深处。","notes":[]},{"n":6,"t":"耶和华啊，你的右手施展能力，显出荣耀；耶和华啊，你的右手摔碎仇敌。","notes":[]},{"n":7,"t":"你大发威严，推翻那些起来攻击你的；你发出烈怒如火，烧灭他们像烧碎秸一样。","notes":[]},{"n":8,"t":"你发鼻中的气，水便聚起成堆，大水直立如垒，海中的深水凝结。","notes":[]},{"n":9,"t":"仇敌说：我要追赶，我要追上；我要分掳物，我要在他们身上称我的心愿。我要拔出刀来，亲手杀灭他们。","notes":[]},{"n":10,"t":"你叫风一吹，海就把他们淹没；他们如铅沉在大水之中。","notes":[]},{"n":11,"t":"耶和华啊，众神之中，谁能像你？谁能像你—至圣至荣，可颂可畏，施行奇事？","notes":[]},{"n":12,"t":"你伸出右手，地便吞灭他们。","notes":[]},{"n":13,"t":"你凭慈爱领了你所赎的百姓；你凭能力引他们到了你的圣所。","notes":[]},{"n":14,"t":"外邦人听见就发颤；疼痛抓住非利士的居民。","notes":[]},{"n":15,"t":"那时，以东的族长惊惶，摩押的英雄被战兢抓住，迦南的居民心都消化了。","notes":[]},{"n":16,"t":"惊骇恐惧临到他们。耶和华啊，因你膀臂的大能，他们如石头寂然不动，等候你的百姓过去，等候你所赎的百姓过去。","notes":[]},{"n":17,"t":"你要将他们领进去，栽于你产业的山上—耶和华啊，就是你为自己所造的住处；主啊，就是你手所建立的圣所。","notes":[]},{"n":18,"t":"耶和华必作王，直到永永远远！","notes":[]},{"n":19,"t":"法老的马匹、车辆，和马兵下到海中，耶和华使海水回流，淹没他们；惟有以色列人在海中走干地。","notes":[],"heads":["米利暗的歌"]},{"n":20,"t":"亚伦的姊姊，女先知米利暗，手里拿着鼓；众妇女也跟她出去拿鼓跳舞。","notes":[]},{"n":21,"t":"米利暗应声说：你们要歌颂耶和华，因他大大战胜，将马和骑马的投在海中。","notes":[]},{"n":22,"t":"摩西领以色列人从红海往前行，到了书珥的旷野，在旷野走了三天，找不着水。","notes":[],"heads":["苦水"]},{"n":23,"t":"到了玛拉，不能喝那里的水；因为水苦，所以那地名叫玛拉。","notes":[]},{"n":24,"t":"百姓就向摩西发怨言，说：「我们喝什么呢？」","notes":[]},{"n":25,"t":"摩西呼求耶和华，耶和华指示他一棵树。他把树丢在水里，水就变甜了。耶和华在那里为他们定了律例、典章，在那里试验他们；","notes":[]},{"n":26,"t":"又说：「你若留意听耶和华—你神的话，又行我眼中看为正的事，留心听我的诫命，守我一切的律例，我就不将所加与埃及人的疾病加在你身上，因为我—耶和华是医治你的。」","notes":[]},{"n":27,"t":"他们到了以琳，在那里有十二股水泉，七十棵棕树；他们就在那里的水边安营。","notes":[]}]},"16":{"heading":"吗哪和鹌鹑","verses":[{"n":1,"t":"以色列全会众从以琳起行，在出埃及后第二个月十五日到了以琳和西奈中间、汛的旷野。","notes":[]},{"n":2,"t":"以色列全会众在旷野向摩西、亚伦发怨言，","notes":[]},{"n":3,"t":"说：「巴不得我们早死在埃及地、耶和华的手下；那时我们坐在肉锅旁边，吃得饱足。你们将我们领出来，到这旷野，是要叫这全会众都饿死啊！」","notes":[]},{"n":4,"t":"耶和华对摩西说：「我要将粮食从天降给你们。百姓可以出去，每天收每天的分，我好试验他们遵不遵我的法度。","notes":[]},{"n":5,"t":"到第六天，他们要把所收进来的预备好了，比每天所收的多一倍。」","notes":[]},{"n":6,"t":"摩西、亚伦对以色列众人说：「到了晚上，你们要知道是耶和华将你们从埃及地领出来的。","notes":[]},{"n":7,"t":"早晨，你们要看见耶和华的荣耀，因为耶和华听见你们向他所发的怨言了。我们算什么，你们竟向我们发怨言呢？」","notes":[]},{"n":8,"t":"摩西又说：「耶和华晚上必给你们肉吃，早晨必给你们食物得饱；因为你们向耶和华发的怨言，他都听见了。我们算什么，你们的怨言不是向我们发的，乃是向耶和华发的。」","notes":[]},{"n":9,"t":"摩西对亚伦说：「你告诉以色列全会众说：『你们就近耶和华面前，因为他已经听见你们的怨言了。』」","notes":[]},{"n":10,"t":"亚伦正对以色列全会众说话的时候，他们向旷野观看，不料，耶和华的荣光在云中显现。","notes":[]},{"n":11,"t":"耶和华晓谕摩西说：","notes":[]},{"n":12,"t":"「我已经听见以色列人的怨言。你告诉他们说：『到黄昏的时候，你们要吃肉，早晨必有食物得饱，你们就知道我是耶和华—你们的神。』」","notes":[]},{"n":13,"t":"到了晚上，有鹌鹑飞来，遮满了营；早晨在营四围的地上有露水。","notes":[]},{"n":14,"t":"露水上升之后，不料，野地面上有如白霜的小圆物。","notes":[]},{"n":15,"t":"以色列人看见，不知道是什么，就彼此对问说：「这是什么呢？」摩西对他们说：「这就是耶和华给你们吃的食物。","notes":[]},{"n":16,"t":"耶和华所吩咐的是这样：你们要按着各人的饭量，为帐棚里的人，按着人数收起来，各拿一俄梅珥。」","notes":[]},{"n":17,"t":"以色列人就这样行；有多收的，有少收的。","notes":[]},{"n":18,"t":"及至用俄梅珥量一量，多收的也没有余，少收的也没有缺；各人按着自己的饭量收取。","notes":[]},{"n":19,"t":"摩西对他们说：「所收的，不许什么人留到早晨。」","notes":[]},{"n":20,"t":"然而他们不听摩西的话，内中有留到早晨的，就生虫变臭了；摩西便向他们发怒。","notes":[]},{"n":21,"t":"他们每日早晨，按着各人的饭量收取，日头一发热，就消化了。","notes":[]},{"n":22,"t":"到第六天，他们收了双倍的食物，每人两俄梅珥。会众的官长来告诉摩西；","notes":[]},{"n":23,"t":"摩西对他们说：「耶和华这样说：『明天是圣安息日，是向耶和华守的圣安息日。你们要烤的就烤了，要煮的就煮了，所剩下的都留到早晨。』」","notes":[]},{"n":24,"t":"他们就照摩西的吩咐留到早晨，也不臭，里头也没有虫子。","notes":[]},{"n":25,"t":"摩西说：「你们今天吃这个吧！因为今天是向耶和华守的安息日；你们在田野必找不着了。","notes":[]},{"n":26,"t":"六天可以收取，第七天乃是安息日，那一天必没有了。」","notes":[]},{"n":27,"t":"第七天，百姓中有人出去收，什么也找不着。","notes":[]},{"n":28,"t":"耶和华对摩西说：「你们不肯守我的诫命和律法，要到几时呢？","notes":[]},{"n":29,"t":"你们看！耶和华既将安息日赐给你们，所以第六天他赐给你们两天的食物，第七天各人要住在自己的地方，不许什么人出去。」","notes":[]},{"n":30,"t":"于是百姓第七天安息了。","notes":[]},{"n":31,"t":"这食物，以色列家叫吗哪；样子像芫荽子，颜色是白的，滋味如同搀蜜的薄饼。","notes":[]},{"n":32,"t":"摩西说：「耶和华所吩咐的是这样：『要将一满俄梅珥吗哪留到世世代代，使后人可以看见我当日将你们领出埃及地，在旷野所给你们吃的食物。』」","notes":[]},{"n":33,"t":"摩西对亚伦说：「你拿一个罐子，盛一满俄梅珥吗哪，存在耶和华面前，要留到世世代代。」","notes":[]},{"n":34,"t":"耶和华怎么吩咐摩西，亚伦就怎么行，把吗哪放在法柜前存留。","notes":[]},{"n":35,"t":"以色列人吃吗哪共四十年，直到进了有人居住之地，就是迦南的境界。（","notes":[]},{"n":36,"t":"俄梅珥就是伊法十分之一。）","notes":[]}]},"17":{"heading":"磐石出水","verses":[{"n":1,"t":"以色列全会众都遵耶和华的吩咐，按着站口从汛的旷野往前行，在利非订安营。百姓没有水喝，","notes":[]},{"n":2,"t":"所以与摩西争闹，说：「给我们水喝吧！」摩西对他们说：「你们为什么与我争闹？为什么试探耶和华呢？」","notes":[]},{"n":3,"t":"百姓在那里甚渴，要喝水，就向摩西发怨言，说：「你为什么将我们从埃及领出来，使我们和我们的儿女并牲畜都渴死呢？」","notes":[]},{"n":4,"t":"摩西就呼求耶和华说：「我向这百姓怎样行呢？他们几乎要拿石头打死我。」","notes":[]},{"n":5,"t":"耶和华对摩西说：「你手里拿着你先前击打河水的杖，带领以色列的几个长老，从百姓面前走过去。","notes":[]},{"n":6,"t":"我必在何烈的磐石那里，站在你面前。你要击打磐石，从磐石里必有水流出来，使百姓可以喝。」摩西就在以色列的长老眼前这样行了。","notes":[]},{"n":7,"t":"他给那地方起名叫玛撒，又叫米利巴；因以色列人争闹，又因他们试探耶和华，说：「耶和华是在我们中间不是？」","notes":["就是试探的意思","就是争闹的意思"]},{"n":8,"t":"那时，亚玛力人来在利非订，和以色列人争战。","notes":[],"heads":["跟亚玛力人争战"]},{"n":9,"t":"摩西对约书亚说：「你为我们选出人来，出去和亚玛力人争战。明天我手里要拿着神的杖，站在山顶上。」","notes":[]},{"n":10,"t":"于是约书亚照着摩西对他所说的话行，和亚玛力人争战。摩西、亚伦，与户珥都上了山顶。","notes":[]},{"n":11,"t":"摩西何时举手，以色列人就得胜，何时垂手，亚玛力人就得胜。","notes":[]},{"n":12,"t":"但摩西的手发沉，他们就搬石头来，放在他以下，他就坐在上面。亚伦与户珥扶着他的手，一个在这边，一个在那边，他的手就稳住，直到日落的时候。","notes":[]},{"n":13,"t":"约书亚用刀杀了亚玛力王和他的百姓。","notes":[]},{"n":14,"t":"耶和华对摩西说：「我要将亚玛力的名号从天下全然涂抹了；你要将这话写在书上作纪念，又念给约书亚听。」","notes":[]},{"n":15,"t":"摩西筑了一座坛，起名叫「耶和华尼西」，","notes":["就是耶和华是我旌旗的意思"]},{"n":16,"t":"又说：「耶和华已经起了誓，必世世代代和亚玛力人争战。」","notes":[]}]},"18":{"heading":"叶忒罗访问摩西","verses":[{"n":1,"t":"摩西的岳父，米甸祭司叶忒罗，听见神为摩西和神的百姓以色列所行的一切事，就是耶和华将以色列从埃及领出来的事，","notes":[]},{"n":2,"t":"便带着摩西的妻子西坡拉，就是摩西从前打发回去的，","notes":[]},{"n":3,"t":"又带着西坡拉的两个儿子，一个名叫革舜，因为摩西说：「我在外邦作了寄居的」；","notes":[]},{"n":4,"t":"一个名叫以利以谢，因为他说：「我父亲的神帮助了我，救我脱离法老的刀。」","notes":[]},{"n":5,"t":"摩西的岳父叶忒罗带着摩西的妻子和两个儿子来到神的山，就是摩西在旷野安营的地方。","notes":[]},{"n":6,"t":"他对摩西说：「我是你岳父叶忒罗，带着你的妻子和两个儿子来到你这里。」","notes":[]},{"n":7,"t":"摩西迎接他的岳父，向他下拜，与他亲嘴，彼此问安，都进了帐棚。","notes":[]},{"n":8,"t":"摩西将耶和华为以色列的缘故向法老和埃及人所行的一切事，以及路上所遭遇的一切艰难，并耶和华怎样搭救他们，都述说与他岳父听。","notes":[]},{"n":9,"t":"叶忒罗因耶和华待以色列的一切好处，就是拯救他们脱离埃及人的手，便甚欢喜。","notes":[]},{"n":10,"t":"叶忒罗说：「耶和华是应当称颂的；他救了你们脱离埃及人和法老的手，将这百姓从埃及人的手下救出来。","notes":[]},{"n":11,"t":"我现今在埃及人向这百姓发狂傲的事上得知，耶和华比万神都大。」","notes":[]},{"n":12,"t":"摩西的岳父叶忒罗把燔祭和平安祭献给神。亚伦和以色列的众长老都来了，与摩西的岳父在神面前吃饭。","notes":[]},{"n":13,"t":"第二天，摩西坐着审判百姓，百姓从早到晚都站在摩西的左右。","notes":[],"heads":["选立百姓的官长"]},{"n":14,"t":"摩西的岳父看见他向百姓所做的一切事，就说：「你向百姓做的是什么事呢？你为什么独自坐着，众百姓从早到晚都站在你的左右呢？」","notes":[]},{"n":15,"t":"摩西对岳父说：「这是因百姓到我这里来求问神。","notes":[]},{"n":16,"t":"他们有事的时候就到我这里来，我便在两造之间施行审判；我又叫他们知道神的律例和法度。」","notes":[]},{"n":17,"t":"摩西的岳父说：「你这做的不好。","notes":[]},{"n":18,"t":"你和这些百姓必都疲惫；因为这事太重，你独自一人办理不了。","notes":[]},{"n":19,"t":"现在你要听我的话。我为你出个主意，愿神与你同在。你要替百姓到神面前，将案件奏告神；","notes":[]},{"n":20,"t":"又要将律例和法度教训他们，指示他们当行的道，当做的事；","notes":[]},{"n":21,"t":"并要从百姓中拣选有才能的人，就是敬畏神、诚实无妄、恨不义之财的人，派他们作千夫长、百夫长、五十夫长、十夫长，管理百姓，","notes":[]},{"n":22,"t":"叫他们随时审判百姓，大事都要呈到你这里，小事他们自己可以审判。这样，你就轻省些，他们也可以同当此任。","notes":[]},{"n":23,"t":"你若这样行，神也这样吩咐你，你就能受得住，这百姓也都平平安安归回他们的住处。」","notes":[]},{"n":24,"t":"于是，摩西听从他岳父的话，按着他所说的去行。","notes":[]},{"n":25,"t":"摩西从以色列人中拣选了有才能的人，立他们为百姓的首领，作千夫长、百夫长、五十夫长、十夫长。","notes":[]},{"n":26,"t":"他们随时审判百姓，有难断的案件就呈到摩西那里，但各样小事他们自己审判。","notes":[]},{"n":27,"t":"此后，摩西让他的岳父去，他就往本地去了。","notes":[]}]},"19":{"heading":"以色列人在西奈山","verses":[{"n":1,"t":"以色列人出埃及地以后，满了三个月的那一天，就来到西奈的旷野。","notes":[]},{"n":2,"t":"他们离了利非订，来到西奈的旷野，就在那里的山下安营。","notes":[]},{"n":3,"t":"摩西到神那里，耶和华从山上呼唤他说：「你要这样告诉雅各家，晓谕以色列人说：","notes":[]},{"n":4,"t":"『我向埃及人所行的事，你们都看见了，且看见我如鹰将你们背在翅膀上，带来归我。","notes":[]},{"n":5,"t":"如今你们若实在听从我的话，遵守我的约，就要在万民中作属我的子民，因为全地都是我的。","notes":[]},{"n":6,"t":"你们要归我作祭司的国度，为圣洁的国民。』这些话你要告诉以色列人。」","notes":[]},{"n":7,"t":"摩西去召了民间的长老来，将耶和华所吩咐他的话都在他们面前陈明。","notes":[]},{"n":8,"t":"百姓都同声回答说：「凡耶和华所说的，我们都要遵行。」摩西就将百姓的话回复耶和华。","notes":[]},{"n":9,"t":"耶和华对摩西说：「我要在密云中临到你那里，叫百姓在我与你说话的时候可以听见，也可以永远信你了。」于是，摩西将百姓的话奏告耶和华。","notes":[]},{"n":10,"t":"耶和华又对摩西说：「你往百姓那里去，叫他们今天明天自洁，又叫他们洗衣服。","notes":[]},{"n":11,"t":"到第三天要预备好了，因为第三天耶和华要在众百姓眼前降临在西奈山上。","notes":[]},{"n":12,"t":"你要在山的四围给百姓定界限，说：『你们当谨慎，不可上山去，也不可摸山的边界；凡摸这山的，必要治死他。","notes":[]},{"n":13,"t":"不可用手摸他，必用石头打死，或用箭射透；无论是人是牲畜，都不得活。到角声拖长的时候，他们才可到山根来。』」","notes":[]},{"n":14,"t":"摩西下山往百姓那里去，叫他们自洁，他们就洗衣服。","notes":[]},{"n":15,"t":"他对百姓说：「到第三天要预备好了。不可亲近女人。」","notes":[]},{"n":16,"t":"到了第三天早晨，在山上有雷轰、闪电，和密云，并且角声甚大，营中的百姓尽都发颤。","notes":[]},{"n":17,"t":"摩西率领百姓出营迎接神，都站在山下。","notes":[]},{"n":18,"t":"西奈全山冒烟，因为耶和华在火中降于山上。山的烟气上腾，如烧窑一般，遍山大大地震动。","notes":[]},{"n":19,"t":"角声渐渐地高而又高，摩西就说话，神有声音答应他。","notes":[]},{"n":20,"t":"耶和华降临在西奈山顶上，耶和华召摩西上山顶，摩西就上去。","notes":[]},{"n":21,"t":"耶和华对摩西说：「你下去嘱咐百姓，不可闯过来到我面前观看，恐怕他们有多人死亡；","notes":[]},{"n":22,"t":"又叫亲近我的祭司自洁，恐怕我忽然出来击杀他们。」","notes":[]},{"n":23,"t":"摩西对耶和华说：「百姓不能上西奈山，因为你已经嘱咐我们说：『要在山的四围定界限，叫山成圣。』」","notes":[]},{"n":24,"t":"耶和华对他说：「下去吧，你要和亚伦一同上来；只是祭司和百姓不可闯过来上到我面前，恐怕我忽然出来击杀他们。」","notes":[]},{"n":25,"t":"于是摩西下到百姓那里告诉他们。","notes":[]}]},"20":{"heading":"十诫","verses":[{"n":1,"t":"神吩咐这一切的话说：","notes":[]},{"n":2,"t":"「我是耶和华—你的神，曾将你从埃及地为奴之家领出来。","notes":[]},{"n":3,"t":"「除了我以外，你不可有别的神。","notes":[]},{"n":4,"t":"「不可为自己雕刻偶像，也不可做什么形象仿佛上天、下地，和地底下、水中的百物。","notes":[]},{"n":5,"t":"不可跪拜那些像，也不可事奉它，因为我耶和华—你的神是忌邪的神。恨我的，我必追讨他的罪，自父及子，直到三四代；","notes":[]},{"n":6,"t":"爱我、守我诫命的，我必向他们发慈爱，直到千代。","notes":[]},{"n":7,"t":"「不可妄称耶和华—你神的名；因为妄称耶和华名的，耶和华必不以他为无罪。","notes":[]},{"n":8,"t":"「当记念安息日，守为圣日。","notes":[]},{"n":9,"t":"六日要劳碌做你一切的工，","notes":[]},{"n":10,"t":"但第七日是向耶和华—你神当守的安息日。这一日你和你的儿女、仆婢、牲畜，并你城里寄居的客旅，无论何工都不可做；","notes":[]},{"n":11,"t":"因为六日之内，耶和华造天、地、海，和其中的万物，第七日便安息，所以耶和华赐福与安息日，定为圣日。","notes":[]},{"n":12,"t":"「当孝敬父母，使你的日子在耶和华—你神所赐你的地上得以长久。","notes":[]},{"n":13,"t":"「不可杀人。","notes":[]},{"n":14,"t":"「不可奸淫。","notes":[]},{"n":15,"t":"「不可偷盗。","notes":[]},{"n":16,"t":"「不可作假见证陷害人。","notes":[]},{"n":17,"t":"「不可贪恋人的房屋；也不可贪恋人的妻子、仆婢、牛驴，并他一切所有的。」","notes":[]},{"n":18,"t":"众百姓见雷轰、闪电、角声、山上冒烟，就都发颤，远远地站立，","notes":[],"heads":["众民战惧"]},{"n":19,"t":"对摩西说：「求你和我们说话，我们必听；不要神和我们说话，恐怕我们死亡。」","notes":[]},{"n":20,"t":"摩西对百姓说：「不要惧怕；因为神降临是要试验你们，叫你们时常敬畏他，不致犯罪。」","notes":[]},{"n":21,"t":"于是百姓远远地站立；摩西就挨近神所在的幽暗之中。","notes":[]},{"n":22,"t":"耶和华对摩西说：「你要向以色列人这样说：『你们自己看见我从天上和你们说话了。","notes":[],"heads":["祭坛的条例"]},{"n":23,"t":"你们不可做什么神像与我相配，不可为自己做金银的神像。","notes":[]},{"n":24,"t":"你要为我筑土坛，在上面以牛羊献为燔祭和平安祭。凡记下我名的地方，我必到那里赐福给你。","notes":[]},{"n":25,"t":"你若为我筑一座石坛，不可用凿成的石头，因你在上头一动家具，就把坛污秽了。","notes":[]},{"n":26,"t":"你上我的坛，不可用台阶，免得露出你的下体来。』」","notes":[]}]},"21":{"heading":"对待奴仆的条例","verses":[{"n":1,"t":"「你在百姓面前所要立的典章是这样：","notes":[]},{"n":2,"t":"你若买希伯来人作奴仆，他必服事你六年；第七年他可以自由，白白地出去。","notes":[]},{"n":3,"t":"他若孤身来就可以孤身去；他若有妻，他的妻就可以同他出去。","notes":[]},{"n":4,"t":"他主人若给他妻子，妻子给他生了儿子或女儿，妻子和儿女要归主人，他要独自出去。","notes":[]},{"n":5,"t":"倘或奴仆明说：『我爱我的主人和我的妻子儿女，不愿意自由出去。』","notes":[]},{"n":6,"t":"他的主人就要带他到审判官那里，又要带他到门前，靠近门框，用锥子穿他的耳朵，他就永远服事主人。","notes":["或译：神；下同"]},{"n":7,"t":"「人若卖女儿作婢女，婢女不可像男仆那样出去。","notes":[]},{"n":8,"t":"主人选定她归自己，若不喜欢她，就要许她赎身；主人既然用诡诈待她，就没有权柄卖给外邦人。","notes":[]},{"n":9,"t":"主人若选定她给自己的儿子，就当待她如同女儿。","notes":[]},{"n":10,"t":"若另娶一个，那女子的吃食、衣服，并好合的事，仍不可减少。","notes":[]},{"n":11,"t":"若不向她行这三样，她就可以不用钱赎，白白地出去。」","notes":[]},{"n":12,"t":"「打人以致打死的，必要把他治死。","notes":[],"heads":["惩罚暴行的条例"]},{"n":13,"t":"人若不是埋伏着杀人，乃是神交在他手中，我就设下一个地方，他可以往那里逃跑。","notes":[]},{"n":14,"t":"人若任意用诡计杀了他的邻舍，就是逃到我的坛那里，也当捉去把他治死。","notes":[]},{"n":15,"t":"「打父母的，必要把他治死。","notes":[]},{"n":16,"t":"「拐带人口，或是把人卖了，或是留在他手下，必要把他治死。","notes":[]},{"n":17,"t":"「咒骂父母的，必要把他治死。","notes":[]},{"n":18,"t":"「人若彼此相争，这个用石头或是拳头打那个，尚且不至于死，不过躺卧在床，","notes":[]},{"n":19,"t":"若再能起来扶杖而出，那打他的可算无罪；但要将他耽误的工夫用钱赔补，并要将他全然医好。","notes":[]},{"n":20,"t":"「人若用棍子打奴仆或婢女，立时死在他的手下，他必要受刑。","notes":[]},{"n":21,"t":"若过一两天才死，就可以不受刑，因为是用钱买的。","notes":[]},{"n":22,"t":"「人若彼此争斗，伤害有孕的妇人，甚至坠胎，随后却无别害，那伤害她的，总要按妇人的丈夫所要的，照审判官所断的，受罚。","notes":[]},{"n":23,"t":"若有别害，就要以命偿命，","notes":[]},{"n":24,"t":"以眼还眼，以牙还牙，以手还手，以脚还脚，","notes":[]},{"n":25,"t":"以烙还烙，以伤还伤，以打还打。","notes":[]},{"n":26,"t":"「人若打坏了他奴仆或是婢女的一只眼，就要因他的眼放他去得以自由。","notes":[]},{"n":27,"t":"若打掉了他奴仆或是婢女的一个牙，就要因他的牙放他去得以自由。」","notes":[]},{"n":28,"t":"「牛若触死男人或是女人，总要用石头打死那牛，却不可吃它的肉；牛的主人可算无罪。","notes":[],"heads":["物主的责任"]},{"n":29,"t":"倘若那牛素来是触人的，有人报告了牛主，他竟不把牛拴着，以致把男人或是女人触死，就要用石头打死那牛，牛主也必治死。","notes":[]},{"n":30,"t":"若罚他赎命的价银，他必照所罚的赎他的命。","notes":[]},{"n":31,"t":"牛无论触了人的儿子或是女儿，必照这例办理。","notes":[]},{"n":32,"t":"牛若触了奴仆或是婢女，必将银子三十舍客勒给他们的主人，也要用石头把牛打死。","notes":[]},{"n":33,"t":"「人若敞着井口，或挖井不遮盖，有牛或驴掉在里头，","notes":[]},{"n":34,"t":"井主要拿钱赔还本主人，死牲畜要归自己。","notes":[]},{"n":35,"t":"「这人的牛若伤了那人的牛，以至于死，他们要卖了活牛，平分价值，也要平分死牛。","notes":[]},{"n":36,"t":"人若知道这牛素来是触人的，主人竟不把牛拴着，他必要以牛还牛，死牛要归自己。」","notes":[]}]},"22":{"heading":"赔偿的条例","verses":[{"n":1,"t":"「人若偷牛或羊，无论是宰了，是卖了，他就要以五牛赔一牛，四羊赔一羊。","notes":[]},{"n":2,"t":"人若遇见贼挖窟窿，把贼打了，以至于死，就不能为他有流血的罪。","notes":[]},{"n":3,"t":"若太阳已经出来，就为他有流血的罪。贼若被拿，总要赔还。若他一无所有，就要被卖，顶他所偷的物。","notes":[]},{"n":4,"t":"若他所偷的，或牛，或驴，或羊，仍在他手下存活，他就要加倍赔还。","notes":[]},{"n":5,"t":"「人若在田间或在葡萄园里放牲畜，任凭牲畜上别人的田里去吃，就必拿自己田间上好的和葡萄园上好的赔还。","notes":[]},{"n":6,"t":"「若点火焚烧荆棘，以致将别人堆积的禾捆，站着的禾稼，或是田园，都烧尽了，那点火的必要赔还。","notes":[]},{"n":7,"t":"「人若将银钱或家具交付邻舍看守，这物从那人的家被偷去，若把贼找到了，贼要加倍赔还；","notes":[]},{"n":8,"t":"若找不到贼，那家主必就近审判官，要看看他拿了原主的物件没有。","notes":[]},{"n":9,"t":"「两个人的案件，无论是为什么过犯，或是为牛，为驴，为羊，为衣裳，或是为什么失掉之物，有一人说：『这是我的』，两造就要将案件禀告审判官，审判官定谁有罪，谁就要加倍赔还。","notes":[]},{"n":10,"t":"「人若将驴，或牛，或羊，或别的牲畜，交付邻舍看守，牲畜或死，或受伤，或被赶去，无人看见，","notes":[]},{"n":11,"t":"那看守的人要凭着耶和华起誓，手里未曾拿邻舍的物，本主就要罢休，看守的人不必赔还。","notes":[]},{"n":12,"t":"牲畜若从看守的那里被偷去，他就要赔还本主；","notes":[]},{"n":13,"t":"若被野兽撕碎，看守的要带来当作证据，所撕的不必赔还。","notes":[]},{"n":14,"t":"「人若向邻舍借什么，所借的或受伤，或死，本主没有同在一处，借的人总要赔还；","notes":[]},{"n":15,"t":"若本主同在一处，他就不必赔还；若是雇的，也不必赔还，本是为雇价来的。」","notes":[]},{"n":16,"t":"「人若引诱没有受聘的处女，与她行淫，他总要交出聘礼，娶她为妻。","notes":[],"heads":["道德上和宗教上的条例"]},{"n":17,"t":"若女子的父亲决不肯将女子给他，他就要按处女的聘礼，交出钱来。","notes":[]},{"n":18,"t":"「行邪术的女人，不可容她存活。","notes":[]},{"n":19,"t":"「凡与兽淫合的，总要把他治死。","notes":[]},{"n":20,"t":"「祭祀别神，不单单祭祀耶和华的，那人必要灭绝。","notes":[]},{"n":21,"t":"「不可亏负寄居的，也不可欺压他，因为你们在埃及地也作过寄居的。","notes":[]},{"n":22,"t":"不可苦待寡妇和孤儿；","notes":[]},{"n":23,"t":"若是苦待他们一点，他们向我一哀求，我总要听他们的哀声，","notes":[]},{"n":24,"t":"并要发烈怒，用刀杀你们，使你们的妻子为寡妇，儿女为孤儿。","notes":[]},{"n":25,"t":"「我民中有贫穷人与你同住，你若借钱给他，不可如放债的向他取利。","notes":[]},{"n":26,"t":"你即或拿邻舍的衣服作当头，必在日落以先归还他；","notes":[]},{"n":27,"t":"因他只有这一件当盖头，是他盖身的衣服，若是没有，他拿什么睡觉呢？他哀求我，我就应允，因为我是有恩惠的。","notes":[]},{"n":28,"t":"「不可毁谤神；也不可毁谤你百姓的官长。","notes":[]},{"n":29,"t":"「你要从你庄稼中的谷和酒榨中滴出来的酒拿来献上，不可迟延。「你要将头生的儿子归给我。","notes":[]},{"n":30,"t":"你牛羊头生的，也要这样；七天当跟着母，第八天要归给我。","notes":[]},{"n":31,"t":"「你们要在我面前为圣洁的人。因此，田间被野兽撕裂牲畜的肉，你们不可吃，要丢给狗吃。」","notes":[]}]},"23":{"heading":"正义和公道","verses":[{"n":1,"t":"「不可随伙布散谣言；不可与恶人连手妄作见证。","notes":[]},{"n":2,"t":"不可随众行恶；不可在争讼的事上随众偏行，作见证屈枉正直；","notes":[]},{"n":3,"t":"也不可在争讼的事上偏护穷人。","notes":[]},{"n":4,"t":"「若遇见你仇敌的牛或驴失迷了路，总要牵回来交给他。","notes":[]},{"n":5,"t":"若看见恨你人的驴压卧在重驮之下，不可走开，务要和驴主一同抬开重驮。","notes":[]},{"n":6,"t":"「不可在穷人争讼的事上屈枉正直。","notes":[]},{"n":7,"t":"当远离虚假的事。不可杀无辜和有义的人，因我必不以恶人为义。","notes":[]},{"n":8,"t":"不可受贿赂；因为贿赂能叫明眼人变瞎了，又能颠倒义人的话。","notes":[]},{"n":9,"t":"「不可欺压寄居的；因为你们在埃及地作过寄居的，知道寄居的心。」","notes":[]},{"n":10,"t":"「六年你要耕种田地，收藏土产，","notes":[],"heads":["安息年和安息日"]},{"n":11,"t":"只是第七年要叫地歇息，不耕不种，使你民中的穷人有吃的；他们所剩下的，野兽可以吃。你的葡萄园和橄榄园也要照样办理。","notes":[]},{"n":12,"t":"「六日你要做工，第七日要安息，使牛、驴可以歇息，并使你婢女的儿子和寄居的都可以舒畅。","notes":[]},{"n":13,"t":"「凡我对你们说的话，你们要谨守。别神的名，你不可提，也不可从你口中传说。」","notes":[]},{"n":14,"t":"「一年三次，你要向我守节。","notes":[],"heads":["三大节期"]},{"n":15,"t":"你要守除酵节，照我所吩咐你的，在亚笔月内所定的日期，吃无酵饼七天。谁也不可空手朝见我，因为你是这月出了埃及。","notes":[]},{"n":16,"t":"又要守收割节，所收的是你田间所种、劳碌得来初熟之物。并在年底收藏，要守收藏节。","notes":[]},{"n":17,"t":"一切的男丁要一年三次朝见主耶和华。","notes":[]},{"n":18,"t":"「不可将我祭牲的血和有酵的饼一同献上；也不可将我节上祭牲的脂油留到早晨。","notes":[]},{"n":19,"t":"「地里首先初熟之物要送到耶和华—你神的殿。「不可用山羊羔母的奶煮山羊羔。」","notes":[]},{"n":20,"t":"「看哪，我差遣使者在你前面，在路上保护你，领你到我所预备的地方去。","notes":[],"heads":["应许和指示"]},{"n":21,"t":"他是奉我名来的；你们要在他面前谨慎，听从他的话，不可惹他，因为他必不赦免你们的过犯。","notes":["或译：违背"]},{"n":22,"t":"「你若实在听从他的话，照着我一切所说的去行，我就向你的仇敌作仇敌，向你的敌人作敌人。","notes":[]},{"n":23,"t":"「我的使者要在你前面行，领你到亚摩利人、赫人、比利洗人、迦南人、希未人、耶布斯人那里去，我必将他们剪除。","notes":[]},{"n":24,"t":"你不可跪拜他们的神，不可事奉他，也不可效法他们的行为，却要把神像尽行拆毁，打碎他们的柱像。","notes":[]},{"n":25,"t":"你们要事奉耶和华—你们的神，他必赐福与你的粮与你的水，也必从你们中间除去疾病。","notes":[]},{"n":26,"t":"你境内必没有坠胎的，不生产的。我要使你满了你年日的数目。","notes":[]},{"n":27,"t":"凡你所到的地方，我要使那里的众民在你面前惊骇，扰乱，又要使你一切仇敌转背逃跑。","notes":[]},{"n":28,"t":"我要打发黄蜂飞在你前面，把希未人、迦南人、赫人撵出去。","notes":[]},{"n":29,"t":"我不在一年之内将他们从你面前撵出去，恐怕地成为荒凉，野地的兽多起来害你。","notes":[]},{"n":30,"t":"我要渐渐地将他们从你面前撵出去，等到你的人数加多，承受那地为业。","notes":[]},{"n":31,"t":"我要定你的境界，从红海直到非利士海，又从旷野直到大河。我要将那地的居民交在你手中，你要将他们从你面前撵出去。","notes":[]},{"n":32,"t":"不可和他们并他们的神立约。","notes":[]},{"n":33,"t":"他们不可住在你的地上，恐怕他们使你得罪我。你若事奉他们的神，这必成为你的网罗。」","notes":[]}]},"24":{"heading":"立约的凭据","verses":[{"n":1,"t":"耶和华对摩西说：「你和亚伦、拿答、亚比户，并以色列长老中的七十人，都要上到我这里来，远远地下拜。","notes":[]},{"n":2,"t":"惟独你可以亲近耶和华；他们却不可亲近；百姓也不可和你一同上来。」","notes":[]},{"n":3,"t":"摩西下山，将耶和华的命令典章都述说与百姓听。众百姓齐声说：「耶和华所吩咐的，我们都必遵行。」","notes":[]},{"n":4,"t":"摩西将耶和华的命令都写上。清早起来，在山下筑一座坛，按以色列十二支派立十二根柱子，","notes":[]},{"n":5,"t":"又打发以色列人中的少年人去献燔祭，又向耶和华献牛为平安祭。","notes":[]},{"n":6,"t":"摩西将血一半盛在盆中，一半洒在坛上；","notes":[]},{"n":7,"t":"又将约书念给百姓听。他们说：「耶和华所吩咐的，我们都必遵行。」","notes":[]},{"n":8,"t":"摩西将血洒在百姓身上，说：「你看！这是立约的血，是耶和华按这一切话与你们立约的凭据。」","notes":[]},{"n":9,"t":"摩西、亚伦、拿答、亚比户，并以色列长老中的七十人，都上了山。","notes":[]},{"n":10,"t":"他们看见以色列的神，他脚下仿佛有平铺的蓝宝石，如同天色明净。","notes":[]},{"n":11,"t":"他的手不加害在以色列的尊者身上。他们观看神；他们又吃又喝。","notes":[]},{"n":12,"t":"耶和华对摩西说：「你上山到我这里来，住在这里，我要将石版并我所写的律法和诫命赐给你，使你可以教训百姓。」","notes":[],"heads":["摩西在西奈山上"]},{"n":13,"t":"摩西和他的帮手约书亚起来，上了神的山。","notes":[]},{"n":14,"t":"摩西对长老说：「你们在这里等着，等到我们再回来，有亚伦、户珥与你们同在。凡有争讼的，都可以就近他们去。」","notes":[]},{"n":15,"t":"摩西上山，有云彩把山遮盖。","notes":[]},{"n":16,"t":"耶和华的荣耀停于西奈山；云彩遮盖山六天，第七天他从云中召摩西。","notes":[]},{"n":17,"t":"耶和华的荣耀在山顶上，在以色列人眼前，形状如烈火。","notes":[]},{"n":18,"t":"摩西进入云中上山，在山上四十昼夜。","notes":[]}]},"25":{"heading":"奉献圣所","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「你告诉以色列人当为我送礼物来；凡甘心乐意的，你们就可以收下归我。","notes":[]},{"n":3,"t":"所要收的礼物：就是金、银、铜，","notes":[]},{"n":4,"t":"蓝色、紫色、朱红色线，细麻，山羊毛，","notes":[]},{"n":5,"t":"染红的公羊皮，海狗皮，皂荚木，","notes":[]},{"n":6,"t":"点灯的油并做膏油和香的香料，","notes":[]},{"n":7,"t":"红玛瑙与别样的宝石，可以镶嵌在以弗得和胸牌上。","notes":[]},{"n":8,"t":"又当为我造圣所，使我可以住在他们中间。","notes":[]},{"n":9,"t":"制造帐幕和其中的一切器具都要照我所指示你的样式。」","notes":[]},{"n":10,"t":"「要用皂荚木做一柜，长二肘半，宽一肘半，高一肘半。","notes":[],"heads":["约柜"]},{"n":11,"t":"要里外包上精金，四围镶上金牙边。","notes":[]},{"n":12,"t":"也要铸四个金环，安在柜的四脚上；这边两环，那边两环。","notes":[]},{"n":13,"t":"要用皂荚木做两根杠，用金包裹。","notes":[]},{"n":14,"t":"要把杠穿在柜旁的环内，以便抬柜。","notes":[]},{"n":15,"t":"这杠要常在柜的环内，不可抽出来。","notes":[]},{"n":16,"t":"必将我所要赐给你的法版放在柜里。","notes":[]},{"n":17,"t":"要用精金做施恩座，长二肘半，宽一肘半。","notes":["施恩：或译蔽罪；下同"]},{"n":18,"t":"要用金子锤出两个基路伯来，安在施恩座的两头。","notes":[]},{"n":19,"t":"这头做一个基路伯，那头做一个基路伯，二基路伯要接连一块，在施恩座的两头。","notes":[]},{"n":20,"t":"二基路伯要高张翅膀，遮掩施恩座。基路伯要脸对脸，朝着施恩座。","notes":[]},{"n":21,"t":"要将施恩座安在柜的上边，又将我所要赐给你的法版放在柜里。","notes":[]},{"n":22,"t":"我要在那里与你相会，又要从法柜施恩座上二基路伯中间，和你说我所要吩咐你传给以色列人的一切事。」","notes":[]},{"n":23,"t":"「要用皂荚木做一张桌子，长二肘，宽一肘，高一肘半。","notes":[],"heads":["陈设饼的桌子"]},{"n":24,"t":"要包上精金，四围镶上金牙边。","notes":[]},{"n":25,"t":"桌子的四围各做一掌宽的横梁，横梁上镶着金牙边。","notes":[]},{"n":26,"t":"要做四个金环，安在桌子的四角上，就是桌子四脚上的四角。","notes":[]},{"n":27,"t":"安环子的地方要挨近横梁，可以穿杠抬桌子。","notes":[]},{"n":28,"t":"要用皂荚木做两根杠，用金包裹，以便抬桌子。","notes":[]},{"n":29,"t":"要做桌子上的盘子、调羹，并奠酒的爵和瓶；这都要用精金制作。","notes":[]},{"n":30,"t":"又要在桌子上，在我面前，常摆陈设饼。」","notes":[]},{"n":31,"t":"「要用精金做一个灯台。灯台的座和干与杯、球、花，都要接连一块锤出来。","notes":[],"heads":["灯台"]},{"n":32,"t":"灯台两旁要杈出六个枝子：这旁三个，那旁三个。","notes":[]},{"n":33,"t":"这旁每枝上有三个杯，形状像杏花，有球，有花；那旁每枝上也有三个杯，形状像杏花，有球，有花。从灯台杈出来的六个枝子都是如此。","notes":[]},{"n":34,"t":"灯台上有四个杯，形状像杏花，有球，有花。","notes":[]},{"n":35,"t":"灯台每两个枝子以下有球与枝子接连一块。灯台出的六个枝子都是如此。","notes":[]},{"n":36,"t":"球和枝子要接连一块，都是一块精金锤出来的。","notes":[]},{"n":37,"t":"要做灯台的七个灯盏。祭司要点这灯，使灯光对照。","notes":[]},{"n":38,"t":"灯台的蜡剪和蜡花盘也是要精金的。","notes":[]},{"n":39,"t":"做灯台和这一切的器具要用精金一他连得。","notes":[]},{"n":40,"t":"要谨慎做这些物件，都要照着在山上指示你的样式。」","notes":[]}]},"26":{"heading":"会幕","verses":[{"n":1,"t":"「你要用十幅幔子做帐幕。这些幔子要用捻的细麻和蓝色、紫色、朱红色线制造，并用巧匠的手工绣上基路伯。","notes":[]},{"n":2,"t":"每幅幔子要长二十八肘，宽四肘，幔子都要一样的尺寸。","notes":[]},{"n":3,"t":"这五幅幔子要幅幅相连；那五幅幔子也要幅幅相连。","notes":[]},{"n":4,"t":"在这相连的幔子末幅边上要做蓝色的钮扣；在那相连的幔子末幅边上也要照样做。","notes":[]},{"n":5,"t":"要在这相连的幔子上做五十个钮扣；在那相连的幔子上也做五十个钮扣，都要两两相对。","notes":[]},{"n":6,"t":"又要做五十个金钩，用钩使幔子相连，这才成了一个帐幕。","notes":[]},{"n":7,"t":"「你要用山羊毛织十一幅幔子，作为帐幕以上的罩棚。","notes":[]},{"n":8,"t":"每幅幔子要长三十肘，宽四肘；十一幅幔子都要一样的尺寸。","notes":[]},{"n":9,"t":"要把五幅幔子连成一幅，又把六幅幔子连成一幅，这第六幅幔子要在罩棚的前面折上去。","notes":[]},{"n":10,"t":"在这相连的幔子末幅边上要做五十个钮扣；在那相连的幔子末幅边上也做五十个钮扣。","notes":[]},{"n":11,"t":"又要做五十个铜钩，钩在钮扣中，使罩棚连成一个。","notes":[]},{"n":12,"t":"罩棚的幔子所余那垂下来的半幅幔子，要垂在帐幕的后头。","notes":[]},{"n":13,"t":"罩棚的幔子所余长的，这边一肘，那边一肘，要垂在帐幕的两旁，遮盖帐幕。","notes":[]},{"n":14,"t":"又要用染红的公羊皮做罩棚的盖；再用海狗皮做一层罩棚上的顶盖。","notes":[]},{"n":15,"t":"「你要用皂荚木做帐幕的竖板。","notes":[]},{"n":16,"t":"每块要长十肘，宽一肘半；","notes":[]},{"n":17,"t":"每块必有两榫相对。帐幕一切的板都要这样做。","notes":[]},{"n":18,"t":"帐幕的南面要做板二十块。","notes":[]},{"n":19,"t":"在这二十块板底下要做四十个带卯的银座，两卯接这块板上的两榫，两卯接那块板上的两榫。","notes":[]},{"n":20,"t":"帐幕第二面，就是北面，也要做板二十块","notes":[]},{"n":21,"t":"和带卯的银座四十个；这板底下有两卯，那板底下也有两卯。","notes":[]},{"n":22,"t":"帐幕的后面，就是西面，要做板六块。","notes":[]},{"n":23,"t":"帐幕后面的拐角要做板两块。","notes":[]},{"n":24,"t":"板的下半截要双的，上半截要整的，直顶到第一个环子；两块都要这样做两个拐角。","notes":[]},{"n":25,"t":"必有八块板和十六个带卯的银座；这板底下有两卯，那板底下也有两卯。","notes":[]},{"n":26,"t":"「你要用皂荚木作闩：为帐幕这面的板作五闩，","notes":[]},{"n":27,"t":"为帐幕那面的板做五闩，又为帐幕后面的板做五闩。","notes":[]},{"n":28,"t":"板腰间的中闩要从这一头通到那一头。","notes":[]},{"n":29,"t":"板要用金子包裹，又要做板上的金环套闩；闩也要用金子包裹。","notes":[]},{"n":30,"t":"要照着在山上指示你的样式立起帐幕。","notes":[]},{"n":31,"t":"「你要用蓝色、紫色、朱红色线，和捻的细麻织幔子，以巧匠的手工绣上基路伯。","notes":[]},{"n":32,"t":"要把幔子挂在四根包金的皂荚木柱子上，柱子上当有金钩，柱子安在四个带卯的银座上。","notes":[]},{"n":33,"t":"要使幔子垂在钩子下，把法柜抬进幔子内；这幔子要将圣所和至圣所隔开。","notes":[]},{"n":34,"t":"又要把施恩座安在至圣所内的法柜上，","notes":[]},{"n":35,"t":"把桌子安在幔子外帐幕的北面；把灯台安在帐幕的南面，彼此相对。","notes":[]},{"n":36,"t":"「你要拿蓝色、紫色、朱红色线，和捻的细麻，用绣花的手工织帐幕的门帘。","notes":[]},{"n":37,"t":"要用皂荚木为帘子做五根柱子，用金子包裹。柱子上当有金钩；又要为柱子用铜铸造五个带卯的座。」","notes":[]}]},"27":{"heading":"祭坛","verses":[{"n":1,"t":"「你要用皂荚木做坛。这坛要四方的，长五肘，宽五肘，高三肘。","notes":[]},{"n":2,"t":"要在坛的四拐角上做四个角，与坛接连一块，用铜把坛包裹。","notes":[]},{"n":3,"t":"要做盆，收去坛上的灰，又做铲子、盘子、肉锸子、火鼎；坛上一切的器具都用铜做。","notes":[]},{"n":4,"t":"要为坛做一个铜网，在网的四角上做四个铜环，","notes":[]},{"n":5,"t":"把网安在坛四面的围腰板以下，使网从下达到坛的半腰。","notes":[]},{"n":6,"t":"又要用皂荚木为坛做杠，用铜包裹。","notes":[]},{"n":7,"t":"这杠要穿在坛两旁的环子内，用以抬坛。","notes":[]},{"n":8,"t":"要用板做坛，坛是空的，都照着在山上指示你的样式做。」","notes":[]},{"n":9,"t":"「你要做帐幕的院子。院子的南面要用捻的细麻做帷子，长一百肘。","notes":[],"heads":["会幕的周围"]},{"n":10,"t":"帷子的柱子要二十根，带卯的铜座二十个。柱子上的钩子和杆子都要用银子做。","notes":[]},{"n":11,"t":"北面也当有帷子，长一百肘，帷子的柱子二十根，带卯的铜座二十个。柱子上的钩子和杆子都要用银子做。","notes":[]},{"n":12,"t":"院子的西面当有帷子，宽五十肘，帷子的柱子十根，带卯的座十个。","notes":[]},{"n":13,"t":"院子的东面要宽五十肘。","notes":[]},{"n":14,"t":"门这边的帷子要十五肘，帷子的柱子三根，带卯的座三个。","notes":[]},{"n":15,"t":"门那边的帷子也要十五肘，帷子的柱子三根，带卯的座三个。","notes":[]},{"n":16,"t":"院子的门当有帘子，长二十肘，要拿蓝色、紫色、朱红色线，和捻的细麻，用绣花的手工织成，柱子四根，带卯的座四个。","notes":[]},{"n":17,"t":"院子四围一切的柱子都要用银杆连络，柱子上的钩子要用银做，带卯的座要用铜做。","notes":[]},{"n":18,"t":"院子要长一百肘，宽五十肘，高五肘，帷子要用捻的细麻做，带卯的座要用铜做。","notes":[]},{"n":19,"t":"帐幕各样用处的器具，并帐幕一切的橛子，和院子里一切的橛子，都要用铜做。」","notes":[]},{"n":20,"t":"「你要吩咐以色列人，把那为点灯捣成的清橄榄油拿来给你，使灯常常点着。","notes":[],"heads":["燃灯的条例"]},{"n":21,"t":"在会幕中法柜前的幔外，亚伦和他的儿子，从晚上到早晨，要在耶和华面前经理这灯。这要作以色列人世世代代永远的定例。」","notes":[]}]},"28":{"heading":"祭司的圣服","verses":[{"n":1,"t":"「你要从以色列人中，使你的哥哥亚伦和他的儿子拿答、亚比户、以利亚撒、以他玛一同就近你，给我供祭司的职分。","notes":[]},{"n":2,"t":"你要给你哥哥亚伦做圣衣为荣耀，为华美。","notes":[]},{"n":3,"t":"又要吩咐一切心中有智慧的，就是我用智慧的灵所充满的，给亚伦做衣服，使他分别为圣，可以给我供祭司的职分。","notes":[]},{"n":4,"t":"所要做的就是胸牌、以弗得、外袍、杂色的内袍、冠冕、腰带，使你哥哥亚伦和他儿子穿这圣服，可以给我供祭司的职分。","notes":[]},{"n":5,"t":"要用金线和蓝色、紫色、朱红色线，并细麻去做。","notes":[]},{"n":6,"t":"「他们要拿金线和蓝色、紫色、朱红色线，并捻的细麻，用巧匠的手工做以弗得。","notes":[]},{"n":7,"t":"以弗得当有两条肩带，接上两头，使它相连。","notes":[]},{"n":8,"t":"其上巧工织的带子，要和以弗得一样的做法，用以束上，与以弗得接连一块，要用金线和蓝色、紫色、朱红色线，并捻的细麻做成。","notes":[]},{"n":9,"t":"要取两块红玛瑙，在上面刻以色列儿子的名字：","notes":[]},{"n":10,"t":"六个名字在这块宝石上，六个名字在那块宝石上，都照他们生来的次序。","notes":[]},{"n":11,"t":"要用刻宝石的手工，仿佛刻图书，按着以色列儿子的名字，刻这两块宝石，要镶在金槽上。","notes":[]},{"n":12,"t":"要将这两块宝石安在以弗得的两条肩带上，为以色列人做纪念石。亚伦要在两肩上担他们的名字，在耶和华面前作为纪念。","notes":[]},{"n":13,"t":"要用金子做二槽，","notes":[]},{"n":14,"t":"又拿精金，用拧工仿佛拧绳子，做两条链子，把这拧成的链子搭在二槽上。」","notes":[]},{"n":15,"t":"「你要用巧匠的手工做一个决断的胸牌。要和以弗得一样的做法：用金线和蓝色、紫色、朱红色线，并捻的细麻做成。","notes":[],"heads":["胸牌"]},{"n":16,"t":"这胸牌要四方的，叠为两层，长一虎口，宽一虎口。","notes":[]},{"n":17,"t":"要在上面镶宝石四行：第一行是红宝石、红璧玺、红玉；","notes":[]},{"n":18,"t":"第二行是绿宝石、蓝宝石、金钢石；","notes":[]},{"n":19,"t":"第三行是紫玛瑙、白玛瑙、紫晶；","notes":[]},{"n":20,"t":"第四行是水苍玉、红玛瑙、碧玉。这都要镶在金槽中。","notes":[]},{"n":21,"t":"这些宝石都要按着以色列十二个儿子的名字，仿佛刻图书，刻十二个支派的名字。","notes":[]},{"n":22,"t":"要在胸牌上用精金拧成如绳的链子。","notes":[]},{"n":23,"t":"在胸牌上也要做两个金环，安在胸牌的两头。","notes":[]},{"n":24,"t":"要把那两条拧成的金链子，穿过胸牌两头的环子。","notes":[]},{"n":25,"t":"又要把链子的那两头接在两槽上，安在以弗得前面肩带上。","notes":[]},{"n":26,"t":"要做两个金环，安在胸牌的两头，在以弗得里面的边上。","notes":[]},{"n":27,"t":"又要做两个金环，安在以弗得前面两条肩带的下边，挨近相接之处，在以弗得巧工织的带子以上。","notes":[]},{"n":28,"t":"要用蓝细带子把胸牌的环子与以弗得的环子系住，使胸牌贴在以弗得巧工织的带子上，不可与以弗得离缝。","notes":[]},{"n":29,"t":"亚伦进圣所的时候，要将决断胸牌，就是刻着以色列儿子名字的，带在胸前，在耶和华面前常作纪念。","notes":[]},{"n":30,"t":"又要将乌陵和土明放在决断的胸牌里；亚伦进到耶和华面前的时候，要带在胸前，在耶和华面前常将以色列人的决断牌带在胸前。」","notes":[]},{"n":31,"t":"「你要做以弗得的外袍，颜色全是蓝的。","notes":[],"heads":["祭司的其他圣服"]},{"n":32,"t":"袍上要为头留一领口，口的周围织出领边来，仿佛铠甲的领口，免得破裂。","notes":[]},{"n":33,"t":"袍子周围底边上要用蓝色、紫色、朱红色线做石榴。在袍子周围的石榴中间要有金铃铛：","notes":[]},{"n":34,"t":"一个金铃铛一个石榴，一个金铃铛一个石榴，在袍子周围的底边上。","notes":[]},{"n":35,"t":"亚伦供职的时候要穿这袍子。他进圣所到耶和华面前，以及出来的时候，袍上的响声必被听见，使他不至于死亡。","notes":[]},{"n":36,"t":"「你要用精金做一面牌，在上面按刻图书之法刻着『归耶和华为圣』。","notes":[]},{"n":37,"t":"要用一条蓝细带子将牌系在冠冕的前面。","notes":[]},{"n":38,"t":"这牌必在亚伦的额上，亚伦要担当干犯圣物条例的罪孽；这圣物是以色列人在一切的圣礼物上所分别为圣的。这牌要常在他的额上，使他们可以在耶和华面前蒙悦纳。","notes":[]},{"n":39,"t":"要用杂色细麻线织内袍，用细麻布做冠冕，又用绣花的手工做腰带。","notes":[]},{"n":40,"t":"「你要为亚伦的儿子做内袍、腰带、裹头巾，为荣耀，为华美。","notes":[]},{"n":41,"t":"要把这些给你的哥哥亚伦和他的儿子穿戴，又要膏他们，将他们分别为圣，好给我供祭司的职分。","notes":[]},{"n":42,"t":"要给他们做细麻布裤子，遮掩下体；裤子当从腰达到大腿。","notes":[]},{"n":43,"t":"亚伦和他儿子进入会幕，或就近坛，在圣所供职的时候必穿上，免得担罪而死。这要为亚伦和他的后裔作永远的定例。」","notes":[]}]},"29":{"heading":"立亚伦和他子孙作祭司的条例","verses":[{"n":1,"t":"「你使亚伦和他儿子成圣，给我供祭司的职分，要如此行：取一只公牛犊，两只无残疾的公绵羊，","notes":[]},{"n":2,"t":"无酵饼和调油的无酵饼，与抹油的无酵薄饼；这都要用细麦面做成。","notes":[]},{"n":3,"t":"这饼要装在一个筐子里，连筐子带来，又把公牛和两只公绵羊牵来。","notes":[]},{"n":4,"t":"要使亚伦和他儿子到会幕门口来，用水洗身。","notes":[]},{"n":5,"t":"要给亚伦穿上内袍和以弗得的外袍，并以弗得，又带上胸牌，束上以弗得巧工织的带子。","notes":[]},{"n":6,"t":"把冠冕戴在他头上，将圣冠加在冠冕上，","notes":[]},{"n":7,"t":"就把膏油倒在他头上膏他。","notes":[]},{"n":8,"t":"要叫他的儿子来，给他们穿上内袍。","notes":[]},{"n":9,"t":"给亚伦和他儿子束上腰带，包上裹头巾，他们就凭永远的定例得了祭司的职任。又要将亚伦和他儿子分别为圣。","notes":[]},{"n":10,"t":"「你要把公牛牵到会幕前，亚伦和他儿子要按手在公牛的头上。","notes":[]},{"n":11,"t":"你要在耶和华面前，在会幕门口，宰这公牛。","notes":[]},{"n":12,"t":"要取些公牛的血，用指头抹在坛的四角上，把血都倒在坛脚那里。","notes":[]},{"n":13,"t":"要把一切盖脏的脂油与肝上的网子，并两个腰子和腰子上的脂油，都烧在坛上。","notes":[]},{"n":14,"t":"只是公牛的皮、肉、粪都要用火烧在营外。这牛是赎罪祭。","notes":[]},{"n":15,"t":"「你要牵一只公绵羊来，亚伦和他儿子要按手在这羊的头上。","notes":[]},{"n":16,"t":"要宰这羊，把血洒在坛的周围。","notes":[]},{"n":17,"t":"要把羊切成块子，洗净五脏和腿，连块子带头，都放在一处。","notes":[]},{"n":18,"t":"要把全羊烧在坛上，是给耶和华献的燔祭，是献给耶和华为馨香的火祭。","notes":[]},{"n":19,"t":"「你要将那一只公绵羊牵来，亚伦和他儿子要按手在羊的头上。","notes":[]},{"n":20,"t":"你要宰这羊，取点血抹在亚伦的右耳垂上和他儿子的右耳垂上，又抹在他们右手的大拇指上和右脚的大拇指上；并要把血洒在坛的四围。","notes":[]},{"n":21,"t":"你要取点膏油和坛上的血，弹在亚伦和他的衣服上，并他儿子和他儿子的衣服上，他们和他们的衣服就一同成圣。","notes":[]},{"n":22,"t":"「你要取这羊的脂油和肥尾巴，并盖脏的脂油与肝上的网子，两个腰子和腰子上的脂油并右腿（这是承接圣职所献的羊）。","notes":[]},{"n":23,"t":"再从耶和华面前装无酵饼的筐子中取一个饼，一个调油的饼和一个薄饼，","notes":[]},{"n":24,"t":"都放在亚伦的手上和他儿子的手上，作为摇祭，在耶和华面前摇一摇。","notes":[]},{"n":25,"t":"要从他们手中接过来，烧在耶和华面前坛上的燔祭上，是献给耶和华为馨香的火祭。","notes":[]},{"n":26,"t":"「你要取亚伦承接圣职所献公羊的胸，作为摇祭，在耶和华面前摇一摇，这就可以作你的分。","notes":[]},{"n":27,"t":"那摇祭的胸和举祭的腿，就是承接圣职所摇的、所举的，是归亚伦和他儿子的。这些你都要成为圣，","notes":[]},{"n":28,"t":"作亚伦和他子孙从以色列人中永远所得的分，因为是举祭。这要从以色列人的平安祭中，作为献给耶和华的举祭。","notes":[]},{"n":29,"t":"「亚伦的圣衣要留给他的子孙，可以穿着受膏，又穿着承接圣职。","notes":[]},{"n":30,"t":"他的子孙接续他当祭司的，每逢进会幕在圣所供职的时候，要穿七天。","notes":[]},{"n":31,"t":"「你要将承接圣职所献公羊的肉煮在圣处。","notes":[]},{"n":32,"t":"亚伦和他儿子要在会幕门口吃这羊的肉和筐内的饼。","notes":[]},{"n":33,"t":"他们吃那些赎罪之物，好承接圣职，使他们成圣；只是外人不可吃，因为这是圣物。","notes":[]},{"n":34,"t":"那承接圣职所献的肉或饼，若有一点留到早晨，就要用火烧了，不可吃这物，因为是圣物。","notes":[]},{"n":35,"t":"「你要这样照我一切所吩咐的，向亚伦和他儿子行承接圣职的礼七天。","notes":[]},{"n":36,"t":"每天要献公牛一只为赎罪祭。你洁净坛的时候，坛就洁净了；且要用膏抹坛，使坛成圣。","notes":[]},{"n":37,"t":"要洁净坛七天，使坛成圣，坛就成为至圣。凡挨着坛的都成为圣。」","notes":[]},{"n":38,"t":"「你每天所要献在坛上的就是两只一岁的羊羔；","notes":[],"heads":["每天当献的祭"]},{"n":39,"t":"早晨要献这一只，黄昏的时候要献那一只。","notes":[]},{"n":40,"t":"和这一只羊羔同献的，要用细面伊法十分之一与捣成的油一欣四分之一调和，又用酒一欣四分之一作为奠祭。","notes":[]},{"n":41,"t":"那一只羊羔要在黄昏的时候献上，照着早晨的素祭和奠祭的礼办理，作为献给耶和华馨香的火祭。","notes":[]},{"n":42,"t":"这要在耶和华面前、会幕门口，作你们世世代代常献的燔祭。我要在那里与你们相会，和你们说话。","notes":[]},{"n":43,"t":"我要在那里与以色列人相会，会幕就要因我的荣耀成为圣。","notes":[]},{"n":44,"t":"我要使会幕和坛成圣，也要使亚伦和他的儿子成圣，给我供祭司的职分。","notes":[]},{"n":45,"t":"我要住在以色列人中间，作他们的神。","notes":[]},{"n":46,"t":"他们必知道我是耶和华—他们的神，是将他们从埃及地领出来的，为要住在他们中间。我是耶和华—他们的神。」","notes":[]}]},"30":{"heading":"香坛","verses":[{"n":1,"t":"「你要用皂荚木做一座烧香的坛。","notes":[]},{"n":2,"t":"这坛要四方的，长一肘，宽一肘，高二肘；坛的四角要与坛接连一块。","notes":[]},{"n":3,"t":"要用精金把坛的上面与坛的四围，并坛的四角，包裹；又要在坛的四围镶上金牙边。","notes":[]},{"n":4,"t":"要做两个金环安在牙子边以下，在坛的两旁，两根横撑上，作为穿杠的用处，以便抬坛。","notes":[]},{"n":5,"t":"要用皂荚木做杠，用金包裹。","notes":[]},{"n":6,"t":"要把坛放在法柜前的幔子外，对着法柜上的施恩座，就是我要与你相会的地方。","notes":[]},{"n":7,"t":"亚伦在坛上要烧馨香料做的香；每早晨他收拾灯的时候，要烧这香。","notes":[]},{"n":8,"t":"黄昏点灯的时候，他要在耶和华面前烧这香，作为世世代代常烧的香。","notes":[]},{"n":9,"t":"在这坛上不可奉上异样的香，不可献燔祭、素祭，也不可浇上奠祭。","notes":[]},{"n":10,"t":"亚伦一年一次要在坛的角上行赎罪之礼。他一年一次要用赎罪祭牲的血在坛上行赎罪之礼，作为世世代代的定例。这坛在耶和华面前为至圣。」","notes":[]},{"n":11,"t":"耶和华晓谕摩西说：","notes":[],"heads":["会幕的捐献"]},{"n":12,"t":"「你要按以色列人被数的，计算总数，你数的时候，他们各人要为自己的生命把赎价奉给耶和华，免得数的时候在他们中间有灾殃。","notes":[]},{"n":13,"t":"凡过去归那些被数之人的，每人要按圣所的平，拿银子半舍客勒；这半舍客勒是奉给耶和华的礼物（一舍客勒是二十季拉）。","notes":[]},{"n":14,"t":"凡过去归那些被数的人，从二十岁以外的，要将这礼物奉给耶和华。","notes":[]},{"n":15,"t":"他们为赎生命将礼物奉给耶和华，富足的不可多出，贫穷的也不可少出，各人要出半舍客勒。","notes":[]},{"n":16,"t":"你要从以色列人收这赎罪银，作为会幕的使用，可以在耶和华面前为以色列人作纪念，赎生命。」","notes":[]},{"n":17,"t":"耶和华晓谕摩西说：","notes":[],"heads":["铜盆"]},{"n":18,"t":"「你要用铜做洗濯盆和盆座，以便洗濯。要将盆放在会幕和坛的中间，在盆里盛水。","notes":[]},{"n":19,"t":"亚伦和他的儿子要在这盆里洗手洗脚。","notes":[]},{"n":20,"t":"他们进会幕，或是就近坛前供职给耶和华献火祭的时候，必用水洗濯，免得死亡。","notes":[]},{"n":21,"t":"他们洗手洗脚就免得死亡。这要作亚伦和他后裔世世代代永远的定例。」","notes":[]},{"n":22,"t":"耶和华晓谕摩西说：","notes":[],"heads":["圣膏"]},{"n":23,"t":"「你要取上品的香料，就是流质的没药五百舍客勒，香肉桂一半，就是二百五十舍客勒，菖蒲二百五十舍客勒，","notes":[]},{"n":24,"t":"桂皮五百舍客勒，都按着圣所的平，又取橄榄油一欣，","notes":[]},{"n":25,"t":"按做香之法调和做成圣膏油。","notes":[]},{"n":26,"t":"要用这膏油抹会幕和法柜，","notes":[]},{"n":27,"t":"桌子与桌子的一切器具，灯台和灯台的器具，并香坛、","notes":[]},{"n":28,"t":"燔祭坛，和坛的一切器具，洗濯盆和盆座。","notes":[]},{"n":29,"t":"要使这些物成为圣，好成为至圣；凡挨着的都成为圣。","notes":[]},{"n":30,"t":"要膏亚伦和他的儿子，使他们成为圣，可以给我供祭司的职分。","notes":[]},{"n":31,"t":"你要对以色列人说：『这油，我要世世代代以为圣膏油。","notes":[]},{"n":32,"t":"不可倒在别人的身上，也不可按这调和之法做与此相似的。这膏油是圣的，你们也要以为圣。","notes":[]},{"n":33,"t":"凡调和与此相似的，或将这膏膏在别人身上的，这人要从民中剪除。』」","notes":[]},{"n":34,"t":"耶和华吩咐摩西说：「你要取馨香的香料，就是拿他弗、施喜列、喜利比拿；这馨香的香料和净乳香各样要一般大的分量。","notes":[],"heads":["香的做法"]},{"n":35,"t":"你要用这些加上盐，按做香之法做成清净圣洁的香。","notes":[]},{"n":36,"t":"这香要取点捣得极细，放在会幕内、法柜前，我要在那里与你相会。你们要以这香为至圣。","notes":[]},{"n":37,"t":"你们不可按这调和之法为自己做香；要以这香为圣，归耶和华。","notes":[]},{"n":38,"t":"凡做香和这香一样，为要闻香味的，这人要从民中剪除。」","notes":[]}]},"31":{"heading":"会幕的技工","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「看哪，犹大支派中，户珥的孙子、乌利的儿子比撒列，我已经提他的名召他。","notes":[]},{"n":3,"t":"我也以我的灵充满了他，使他有智慧，有聪明，有知识，能做各样的工，","notes":[]},{"n":4,"t":"能想出巧工，用金、银、铜制造各物，","notes":[]},{"n":5,"t":"又能刻宝石，可以镶嵌，能雕刻木头，能做各样的工。","notes":[]},{"n":6,"t":"我分派但支派中、亚希撒抹的儿子亚何利亚伯与他同工。凡心里有智慧的，我更使他们有智慧，能做我一切所吩咐的，","notes":[]},{"n":7,"t":"就是会幕和法柜，并其上的施恩座，与会幕中一切的器具，","notes":[]},{"n":8,"t":"桌子和桌子的器具，精金的灯台和灯台的一切器具并香坛，","notes":[]},{"n":9,"t":"燔祭坛和坛的一切器具，并洗濯盆与盆座，","notes":[]},{"n":10,"t":"精工做的礼服，和祭司亚伦并他儿子用以供祭司职分的圣衣，","notes":[]},{"n":11,"t":"膏油和为圣所用馨香的香料。他们都要照我一切所吩咐的去做。」","notes":[]},{"n":12,"t":"耶和华晓谕摩西说：","notes":[],"heads":["安息日"]},{"n":13,"t":"「你要吩咐以色列人说：『你们务要守我的安息日；因为这是你我之间世世代代的证据，使你们知道我—耶和华是叫你们成为圣的。","notes":[]},{"n":14,"t":"所以你们要守安息日，以为圣日。凡干犯这日的，必要把他治死；凡在这日做工的，必从民中剪除。","notes":[]},{"n":15,"t":"六日要做工，但第七日是安息圣日，是向耶和华守为圣的。凡在安息日做工的，必要把他治死。』","notes":[]},{"n":16,"t":"故此，以色列人要世世代代守安息日为永远的约。","notes":[]},{"n":17,"t":"这是我和以色列人永远的证据；因为六日之内耶和华造天地，第七日便安息舒畅。」","notes":[]},{"n":18,"t":"耶和华在西奈山和摩西说完了话，就把两块法版交给他，是神用指头写的石版。","notes":[]}]},"32":{"heading":"金牛犊","verses":[{"n":1,"t":"百姓见摩西迟延不下山，就大家聚集到亚伦那里，对他说：「起来！为我们做神像，可以在我们前面引路；因为领我们出埃及地的那个摩西，我们不知道他遭了什么事。」","notes":[]},{"n":2,"t":"亚伦对他们说：「你们去摘下你们妻子、儿女耳上的金环，拿来给我。」","notes":[]},{"n":3,"t":"百姓就都摘下他们耳上的金环，拿来给亚伦。","notes":[]},{"n":4,"t":"亚伦从他们手里接过来，铸了一只牛犊，用雕刻的器具做成。他们就说：「以色列啊，这是领你出埃及地的神。」","notes":[]},{"n":5,"t":"亚伦看见，就在牛犊面前筑坛，且宣告说：「明日要向耶和华守节。」","notes":[]},{"n":6,"t":"次日清早，百姓起来献燔祭和平安祭，就坐下吃喝，起来玩耍。","notes":[]},{"n":7,"t":"耶和华吩咐摩西说：「下去吧，因为你的百姓，就是你从埃及地领出来的，已经败坏了。","notes":[]},{"n":8,"t":"他们快快偏离了我所吩咐的道，为自己铸了一只牛犊，向它下拜献祭，说：『以色列啊，这就是领你出埃及地的神。』」","notes":[]},{"n":9,"t":"耶和华对摩西说：「我看这百姓真是硬着颈项的百姓。","notes":[]},{"n":10,"t":"你且由着我，我要向他们发烈怒，将他们灭绝，使你的后裔成为大国。」","notes":[]},{"n":11,"t":"摩西便恳求耶和华—他的神说：「耶和华啊，你为什么向你的百姓发烈怒呢？这百姓是你用大力和大能的手从埃及地领出来的。","notes":[]},{"n":12,"t":"为什么使埃及人议论说『他领他们出去，是要降祸与他们，把他们杀在山中，将他们从地上除灭』？求你转意，不发你的烈怒，后悔，不降祸与你的百姓。","notes":[]},{"n":13,"t":"求你记念你的仆人亚伯拉罕、以撒、以色列。你曾指着自己起誓说：『我必使你们的后裔像天上的星那样多，并且我所应许的这全地，必给你们的后裔，他们要永远承受为业。』」","notes":[]},{"n":14,"t":"于是耶和华后悔，不把所说的祸降与他的百姓。","notes":[]},{"n":15,"t":"摩西转身下山，手里拿着两块法版。这版是两面写的，这面那面都有字，","notes":[]},{"n":16,"t":"是神的工作，字是神写的，刻在版上。","notes":[]},{"n":17,"t":"约书亚一听见百姓呼喊的声音，就对摩西说：「在营里有争战的声音。」","notes":[]},{"n":18,"t":"摩西说：「这不是人打胜仗的声音，也不是人打败仗的声音；我所听见的乃是人歌唱的声音。」","notes":[]},{"n":19,"t":"摩西挨近营前就看见牛犊，又看见人跳舞，便发烈怒，把两块版扔在山下摔碎了，","notes":[]},{"n":20,"t":"又将他们所铸的牛犊用火焚烧，磨得粉碎，撒在水面上，叫以色列人喝。","notes":[]},{"n":21,"t":"摩西对亚伦说：「这百姓向你做了什么？你竟使他们陷在大罪里！」","notes":[]},{"n":22,"t":"亚伦说：「求我主不要发烈怒。这百姓专于作恶，是你知道的。","notes":[]},{"n":23,"t":"他们对我说：『你为我们做神像，可以在我们前面引路；因为领我们出埃及地的那个摩西，我们不知道他遭了什么事。』","notes":[]},{"n":24,"t":"我对他们说：『凡有金环的可以摘下来』，他们就给了我。我把金环扔在火中，这牛犊便出来了。」","notes":[]},{"n":25,"t":"摩西见百姓放肆（亚伦纵容他们，使他们在仇敌中间被讥刺），","notes":[]},{"n":26,"t":"就站在营门中，说：「凡属耶和华的，都要到我这里来！」于是利未的子孙都到他那里聚集。","notes":[]},{"n":27,"t":"他对他们说：「耶和华—以色列的神这样说：『你们各人把刀跨在腰间，在营中往来，从这门到那门，各人杀他的弟兄与同伴并邻舍。』」","notes":[]},{"n":28,"t":"利未的子孙照摩西的话行了。那一天百姓中被杀的约有三千。","notes":[]},{"n":29,"t":"摩西说：「今天你们要自洁，归耶和华为圣，各人攻击他的儿子和弟兄，使耶和华赐福与你们。」","notes":[]},{"n":30,"t":"到了第二天，摩西对百姓说：「你们犯了大罪。我如今要上耶和华那里去，或者可以为你们赎罪。」","notes":[]},{"n":31,"t":"摩西回到耶和华那里，说：「唉！这百姓犯了大罪，为自己做了金像。","notes":[]},{"n":32,"t":"倘或你肯赦免他们的罪..不然，求你从你所写的册上涂抹我的名。」","notes":[]},{"n":33,"t":"耶和华对摩西说：「谁得罪我，我就从我的册上涂抹谁的名。","notes":[]},{"n":34,"t":"现在你去领这百姓，往我所告诉你的地方去，我的使者必在你前面引路；只是到我追讨的日子，我必追讨他们的罪。」","notes":[]},{"n":35,"t":"耶和华杀百姓的缘故是因他们同亚伦做了牛犊。","notes":[]}]},"33":{"heading":"耶和华吩咐以色列人离开西奈山","verses":[{"n":1,"t":"耶和华吩咐摩西说：「我曾起誓应许亚伯拉罕、以撒、雅各说：『要将迦南地赐给你的后裔。』现在你和你从埃及地所领出来的百姓，要从这里往那地去。","notes":[]},{"n":2,"t":"我要差遣使者在你前面，撵出迦南人、亚摩利人、赫人、比利洗人、希未人、耶布斯人，","notes":[]},{"n":3,"t":"领你到那流奶与蜜之地。我自己不同你们上去；因为你们是硬着颈项的百姓，恐怕我在路上把你们灭绝。」","notes":[]},{"n":4,"t":"百姓听见这凶信就悲哀，也没有人佩戴妆饰。","notes":[]},{"n":5,"t":"耶和华对摩西说：「你告诉以色列人说：『耶和华说：你们是硬着颈项的百姓，我若一霎时临到你们中间，必灭绝你们。现在你们要把身上的妆饰摘下来，使我可以知道怎样待你们。』」","notes":[]},{"n":6,"t":"以色列人从住何烈山以后，就把身上的妆饰摘得干净。","notes":[]},{"n":7,"t":"摩西素常将帐棚支搭在营外，离营却远，他称这帐棚为会幕。凡求问耶和华的，就到营外的会幕那里去。","notes":[],"heads":["耶和华的会幕"]},{"n":8,"t":"当摩西出营到会幕去的时候，百姓就都起来，各人站在自己帐棚的门口，望着摩西，直等到他进了会幕。","notes":[]},{"n":9,"t":"摩西进会幕的时候，云柱降下来，立在会幕的门前，耶和华便与摩西说话。","notes":[]},{"n":10,"t":"众百姓看见云柱立在会幕门前，就都起来，各人在自己帐棚的门口下拜。","notes":[]},{"n":11,"t":"耶和华与摩西面对面说话，好像人与朋友说话一般。摩西转到营里去，惟有他的帮手—一个少年人嫩的儿子约书亚不离开会幕。","notes":[]},{"n":12,"t":"摩西对耶和华说：「你吩咐我说：『将这百姓领上去』，却没有叫我知道你要打发谁与我同去，只说：『我按你的名认识你，你在我眼前也蒙了恩。』","notes":[],"heads":["耶和华应许跟百姓同在"]},{"n":13,"t":"我如今若在你眼前蒙恩，求你将你的道指示我，使我可以认识你，好在你眼前蒙恩。求你想到这民是你的民。」","notes":[]},{"n":14,"t":"耶和华说：「我必亲自和你同去，使你得安息。」","notes":[]},{"n":15,"t":"摩西说：「你若不亲自和我同去，就不要把我们从这里领上去。","notes":[]},{"n":16,"t":"人在何事上得以知道我和你的百姓在你眼前蒙恩呢？岂不是因你与我们同去、使我和你的百姓与地上的万民有分别吗？」","notes":[]},{"n":17,"t":"耶和华对摩西说：「你这所求的我也要行；因为你在我眼前蒙了恩，并且我按你的名认识你。」","notes":[]},{"n":18,"t":"摩西说：「求你显出你的荣耀给我看。」","notes":[]},{"n":19,"t":"耶和华说：「我要显我一切的恩慈，在你面前经过，宣告我的名。我要恩待谁就恩待谁；要怜悯谁就怜悯谁」；","notes":[]},{"n":20,"t":"又说：「你不能看见我的面，因为人见我的面不能存活。」","notes":[]},{"n":21,"t":"耶和华说：「看哪，在我这里有地方，你要站在磐石上。","notes":[]},{"n":22,"t":"我的荣耀经过的时候，我必将你放在磐石穴中，用我的手遮掩你，等我过去，","notes":[]},{"n":23,"t":"然后我要将我的手收回，你就得见我的背，却不得见我的面。」","notes":[]}]},"34":{"heading":"复造法版","verses":[{"n":1,"t":"耶和华吩咐摩西说：「你要凿出两块石版，和先前你摔碎的那版一样；其上的字我要写在这版上。","notes":[]},{"n":2,"t":"明日早晨，你要预备好了，上西奈山，在山顶上站在我面前。","notes":[]},{"n":3,"t":"谁也不可和你一同上去，遍山都不可有人，在山根也不可叫羊群牛群吃草。」","notes":[]},{"n":4,"t":"摩西就凿出两块石版，和先前的一样。清晨起来，照耶和华所吩咐的上西奈山去，手里拿着两块石版。","notes":[]},{"n":5,"t":"耶和华在云中降临，和摩西一同站在那里，宣告耶和华的名。","notes":[]},{"n":6,"t":"耶和华在他面前宣告说：「耶和华，耶和华，是有怜悯有恩典的神，不轻易发怒，并有丰盛的慈爱和诚实，","notes":[]},{"n":7,"t":"为千万人存留慈爱，赦免罪孽、过犯，和罪恶，万不以有罪的为无罪，必追讨他的罪，自父及子，直到三、四代。」","notes":[]},{"n":8,"t":"摩西急忙伏地下拜，","notes":[]},{"n":9,"t":"说：「主啊，我若在你眼前蒙恩，求你在我们中间同行，因为这是硬着颈项的百姓。又求你赦免我们的罪孽和罪恶，以我们为你的产业。」","notes":[]},{"n":10,"t":"耶和华说：「我要立约，要在百姓面前行奇妙的事，是在遍地万国中所未曾行的。在你四围的外邦人就要看见耶和华的作为，因我向你所行的是可畏惧的事。","notes":[],"heads":["重新立约"]},{"n":11,"t":"「我今天所吩咐你的，你要谨守。我要从你面前撵出亚摩利人、迦南人、赫人、比利洗人、希未人、耶布斯人。","notes":[]},{"n":12,"t":"你要谨慎，不可与你所去那地的居民立约，恐怕成为你们中间的网罗；","notes":[]},{"n":13,"t":"却要拆毁他们的祭坛，打碎他们的柱像，砍下他们的木偶。","notes":[]},{"n":14,"t":"不可敬拜别神；因为耶和华是忌邪的神，名为忌邪者。","notes":[]},{"n":15,"t":"只怕你与那地的居民立约，百姓随从他们的神，就行邪淫，祭祀他们的神，有人叫你，你便吃他的祭物，","notes":[]},{"n":16,"t":"又为你的儿子娶他们的女儿为妻，他们的女儿随从她们的神，就行邪淫，使你的儿子也随从她们的神行邪淫。","notes":[]},{"n":17,"t":"「不可为自己铸造神像。","notes":[]},{"n":18,"t":"「你要守除酵节，照我所吩咐你的，在亚笔月内所定的日期吃无酵饼七天，因为你是这亚笔月内出了埃及。","notes":[]},{"n":19,"t":"凡头生的都是我的；一切牲畜头生的，无论是牛是羊，公的都是我的。","notes":[]},{"n":20,"t":"头生的驴要用羊羔代赎，若不代赎就要打折它的颈项。凡头生的儿子都要赎出来。谁也不可空手朝见我。","notes":[]},{"n":21,"t":"「你六日要做工，第七日要安息，虽在耕种收割的时候也要安息。","notes":[]},{"n":22,"t":"在收割初熟麦子的时候要守七七节；又在年底要守收藏节。","notes":[]},{"n":23,"t":"你们一切男丁要一年三次朝见主耶和华—以色列的神。","notes":[]},{"n":24,"t":"我要从你面前赶出外邦人，扩张你的境界。你一年三次上去朝见耶和华—你神的时候，必没有人贪慕你的地土。","notes":[]},{"n":25,"t":"「你不可将我祭物的血和有酵的饼一同献上。逾越节的祭物也不可留到早晨。","notes":[]},{"n":26,"t":"地里首先初熟之物要送到耶和华—你神的殿。不可用山羊羔母的奶煮山羊羔。」","notes":[]},{"n":27,"t":"耶和华吩咐摩西说：「你要将这些话写上，因为我是按这话与你和以色列人立约。」","notes":[]},{"n":28,"t":"摩西在耶和华那里四十昼夜，也不吃饭也不喝水。耶和华将这约的话，就是十条诫，写在两块版上。","notes":[]},{"n":29,"t":"摩西手里拿着两块法版下西奈山的时候，不知道自己的面皮因耶和华和他说话就发了光。","notes":[],"heads":["摩西下西奈山"]},{"n":30,"t":"亚伦和以色列众人看见摩西的面皮发光就怕挨近他。","notes":[]},{"n":31,"t":"摩西叫他们来；于是亚伦和会众的官长都到他那里去，摩西就与他们说话。","notes":[]},{"n":32,"t":"随后以色列众人都近前来，他就把耶和华在西奈山与他所说的一切话都吩咐他们。","notes":[]},{"n":33,"t":"摩西与他们说完了话就用帕子蒙上脸。","notes":[]},{"n":34,"t":"但摩西进到耶和华面前与他说话就揭去帕子，及至出来的时候便将耶和华所吩咐的告诉以色列人。","notes":[]},{"n":35,"t":"以色列人看见摩西的面皮发光。摩西又用帕子蒙上脸，等到他进去与耶和华说话就揭去帕子。","notes":[]}]},"35":{"heading":"安息日的条例","verses":[{"n":1,"t":"摩西招聚以色列全会众，对他们说：「这是耶和华所吩咐的话，叫你们照着行：","notes":[]},{"n":2,"t":"六日要做工，第七日乃为圣日，当向耶和华守为安息圣日。凡这日之内做工的，必把他治死。","notes":[]},{"n":3,"t":"当安息日，不可在你们一切的住处生火。」","notes":[]},{"n":4,"t":"摩西对以色列全会众说：「耶和华所吩咐的是这样：","notes":[],"heads":["为会幕奉献"]},{"n":5,"t":"你们中间要拿礼物献给耶和华，凡乐意献的可以拿耶和华的礼物来，就是金、银、铜，","notes":[]},{"n":6,"t":"蓝色、紫色、朱红色线，细麻，山羊毛，","notes":[]},{"n":7,"t":"染红的公羊皮，海狗皮，皂荚木，","notes":[]},{"n":8,"t":"点灯的油，并做膏油和香的香料，","notes":[]},{"n":9,"t":"红玛瑙与别样的宝石，可以镶嵌在以弗得和胸牌上。」","notes":[]},{"n":10,"t":"「你们中间凡心里有智慧的都要来做耶和华一切所吩咐的：","notes":[],"heads":["会幕的器物"]},{"n":11,"t":"就是帐幕和帐幕的罩棚，并帐幕的盖、钩子、板、闩、柱子、带卯的座，","notes":[]},{"n":12,"t":"柜和柜的杠，施恩座和遮掩柜的幔子，","notes":[]},{"n":13,"t":"桌子和桌子的杠与桌子的一切器具，并陈设饼，","notes":[]},{"n":14,"t":"灯台和灯台的器具，灯盏并点灯的油，","notes":[]},{"n":15,"t":"香坛和坛的杠，膏油和馨香的香料，并帐幕门口的帘子，","notes":[]},{"n":16,"t":"燔祭坛和坛的铜网，坛的杠并坛的一切器具，洗濯盆和盆座，","notes":[]},{"n":17,"t":"院子的帷子和帷子的柱子，带卯的座和院子的门帘，","notes":[]},{"n":18,"t":"帐幕的橛子并院子的橛子，和这两处的绳子，","notes":[]},{"n":19,"t":"精工做的礼服和祭司亚伦并他儿子在圣所用以供祭司职分的圣衣。」","notes":[]},{"n":20,"t":"以色列全会众从摩西面前退去。","notes":[],"heads":["百姓奉献礼物"]},{"n":21,"t":"凡心里受感和甘心乐意的都拿耶和华的礼物来，用以做会幕和其中一切的使用，又用以做圣衣。","notes":[]},{"n":22,"t":"凡心里乐意献礼物的，连男带女，各将金器，就是胸前针、耳环、打印的戒指，和手钏带来献给耶和华。","notes":["或译：鼻环"]},{"n":23,"t":"凡有蓝色、紫色、朱红色线，细麻，山羊毛，染红的公羊皮，海狗皮的，都拿了来；","notes":[]},{"n":24,"t":"凡献银子和铜给耶和华为礼物的都拿了来；凡有皂荚木可做什么使用的也拿了来。","notes":[]},{"n":25,"t":"凡心中有智慧的妇女亲手纺线，把所纺的蓝色、紫色、朱红色线，和细麻都拿了来。","notes":[]},{"n":26,"t":"凡有智慧、心里受感的妇女就纺山羊毛。","notes":[]},{"n":27,"t":"众官长把红玛瑙和别样的宝石，可以镶嵌在以弗得与胸牌上的，都拿了来；","notes":[]},{"n":28,"t":"又拿香料做香，拿油点灯，做膏油。","notes":[]},{"n":29,"t":"以色列人，无论男女，凡甘心乐意献礼物给耶和华的，都将礼物拿来，做耶和华借摩西所吩咐的一切工。","notes":[]},{"n":30,"t":"摩西对以色列人说：「犹大支派中，户珥的孙子、乌利的儿子比撒列，耶和华已经提他的名召他，","notes":[],"heads":["造会幕的技工"]},{"n":31,"t":"又以神的灵充满了他，使他有智慧、聪明、知识，能做各样的工，","notes":[]},{"n":32,"t":"能想出巧工，用金、银、铜制造各物，","notes":[]},{"n":33,"t":"又能刻宝石，可以镶嵌，能雕刻木头，能做各样的巧工。","notes":[]},{"n":34,"t":"耶和华又使他，和但支派中亚希撒抹的儿子亚何利亚伯，心里灵明，能教导人。","notes":[]},{"n":35,"t":"耶和华使他们的心满有智慧，能做各样的工，无论是雕刻的工，巧匠的工，用蓝色、紫色、朱红色线，和细麻、绣花的工，并机匠的工，他们都能做，也能想出奇巧的工。","notes":[]}]},"36":{"heading":"百姓奉献礼物","verses":[{"n":1,"t":"「比撒列和亚何利亚伯，并一切心里有智慧的，就是蒙耶和华赐智慧聪明、叫他知道做圣所各样使用之工的，都要照耶和华所吩咐的做工。」","notes":[]},{"n":2,"t":"凡耶和华赐他心里有智慧、而且受感前来做这工的，摩西把他们和比撒列并亚何利亚伯一同召来。","notes":[]},{"n":3,"t":"这些人就从摩西收了以色列人为做圣所并圣所使用之工所拿来的礼物。百姓每早晨还把甘心献的礼物拿来。","notes":[]},{"n":4,"t":"凡做圣所一切工的智慧人各都离开他所做的工，","notes":[]},{"n":5,"t":"来对摩西说：「百姓为耶和华吩咐使用之工所拿来的，富富有余。」","notes":[]},{"n":6,"t":"摩西传命，他们就在全营中宣告说：「无论男女，不必再为圣所拿什么礼物来。」这样才拦住百姓不再拿礼物来。","notes":[]},{"n":7,"t":"因为他们所有的材料够做一切当做的物，而且有余。","notes":[]},{"n":8,"t":"他们中间，凡心里有智慧做工的，用十幅幔子做帐幕。这幔子是比撒列用捻的细麻和蓝色、紫色、朱红色线制造的，并用巧匠的手工绣上基路伯。","notes":[],"heads":["造耶和华的会幕"]},{"n":9,"t":"每幅幔子长二十八肘，宽四肘，都是一样的尺寸。","notes":[]},{"n":10,"t":"他使这五幅幔子幅幅相连，又使那五幅幔子幅幅相连；","notes":[]},{"n":11,"t":"在这相连的幔子末幅边上做蓝色的钮扣，在那相连的幔子末幅边上也照样做；","notes":[]},{"n":12,"t":"在这相连的幔子上做五十个钮扣，在那相连的幔子上也做五十个钮扣，都是两两相对；","notes":[]},{"n":13,"t":"又做五十个金钩，使幔子相连。这才成了一个帐幕。","notes":[]},{"n":14,"t":"他用山羊毛织十一幅幔子，作为帐幕以上的罩棚。","notes":[]},{"n":15,"t":"每幅幔子长三十肘，宽四肘；十一幅幔子都是一样的尺寸。","notes":[]},{"n":16,"t":"他把五幅幔子连成一幅，又把六幅幔子连成一幅；","notes":[]},{"n":17,"t":"在这相连的幔子末幅边上做五十个钮扣，在那相连的幔子末幅边上也做五十个钮扣；","notes":[]},{"n":18,"t":"又做五十个铜钩，使罩棚连成一个；","notes":[]},{"n":19,"t":"并用染红的公羊皮做罩棚的盖，再用海狗皮做一层罩棚上的顶盖。","notes":[]},{"n":20,"t":"他用皂荚木做帐幕的竖板。","notes":[]},{"n":21,"t":"每块长十肘，宽一肘半；","notes":[]},{"n":22,"t":"每块有两榫相对。帐幕一切的板都是这样做。","notes":[]},{"n":23,"t":"帐幕的南面做板二十块。","notes":[]},{"n":24,"t":"在这二十块板底下又做四十个带卯的银座：两卯接这块板上的两榫，两卯接那块板上的两榫。","notes":[]},{"n":25,"t":"帐幕的第二面，就是北面，也做板二十块","notes":[]},{"n":26,"t":"和带卯的银座四十个：这板底下有两卯，那板底下也有两卯。","notes":[]},{"n":27,"t":"帐幕的后面，就是西面，做板六块。","notes":[]},{"n":28,"t":"帐幕后面的拐角做板两块。","notes":[]},{"n":29,"t":"板的下半截是双的，上半截是整的，直到第一个环子；在帐幕的两个拐角上都是这样做。","notes":[]},{"n":30,"t":"有八块板和十六个带卯的银座，每块板底下有两卯。","notes":[]},{"n":31,"t":"他用皂荚木做闩：为帐幕这面的板做五闩，","notes":[]},{"n":32,"t":"为帐幕那面的板做五闩，又为帐幕后面的板做五闩，","notes":[]},{"n":33,"t":"使板腰间的中闩从这一头通到那一头。","notes":[]},{"n":34,"t":"用金子将板包裹，又做板上的金环套闩；闩也用金子包裹。","notes":[]},{"n":35,"t":"他用蓝色、紫色、朱红色线，和捻的细麻织幔子，以巧匠的手工绣上基路伯。","notes":[]},{"n":36,"t":"为幔子做四根皂荚木柱子，用金包裹，柱子上有金钩，又为柱子铸了四个带卯的银座。","notes":[]},{"n":37,"t":"拿蓝色、紫色、朱红色线，和捻的细麻，用绣花的手工织帐幕的门帘；","notes":[]},{"n":38,"t":"又为帘子做五根柱子和柱子上的钩子，用金子把柱顶和柱子上的杆子包裹。柱子有五个带卯的座，是铜的。","notes":[]}]},"37":{"heading":"造约柜","verses":[{"n":1,"t":"比撒列用皂荚木做柜，长二肘半，宽一肘半，高一肘半。","notes":[]},{"n":2,"t":"里外包上精金，四围镶上金牙边，","notes":[]},{"n":3,"t":"又铸四个金环，安在柜的四脚上：这边两环，那边两环。","notes":[]},{"n":4,"t":"用皂荚木做两根杠，用金包裹。","notes":[]},{"n":5,"t":"把杠穿在柜旁的环内，以便抬柜。","notes":[]},{"n":6,"t":"用精金做施恩座，长二肘半，宽一肘半。","notes":[]},{"n":7,"t":"用金子锤出两个基路伯来，安在施恩座的两头，","notes":[]},{"n":8,"t":"这头做一个基路伯，那头做一个基路伯，二基路伯接连一块，在施恩座的两头。","notes":[]},{"n":9,"t":"二基路伯高张翅膀，遮掩施恩座；基路伯是脸对脸，朝着施恩座。","notes":[]},{"n":10,"t":"他用皂荚木做一张桌子，长二肘，宽一肘，高一肘半，","notes":[],"heads":["造陈设饼的桌子"]},{"n":11,"t":"又包上精金，四围镶上金牙边。","notes":[]},{"n":12,"t":"桌子的四围各做一掌宽的横梁，横梁上镶着金牙边，","notes":[]},{"n":13,"t":"又铸了四个金环，安在桌子四脚的四角上。","notes":[]},{"n":14,"t":"安环子的地方是挨近横梁，可以穿杠抬桌子。","notes":[]},{"n":15,"t":"他用皂荚木做两根杠，用金包裹，以便抬桌子；","notes":[]},{"n":16,"t":"又用精金做桌子上的器皿，就是盘子、调羹，并奠酒的瓶和爵。","notes":[]},{"n":17,"t":"他用精金做一个灯台；这灯台的座和干，与杯、球、花，都是接连一块锤出来的。","notes":[],"heads":["造灯台"]},{"n":18,"t":"灯台两旁杈出六个枝子：这旁三个，那旁三个。","notes":[]},{"n":19,"t":"这旁每枝上有三个杯，形状像杏花，有球有花；那旁每枝上也有三个杯，形状像杏花，有球有花。从灯台杈出来的六个枝子都是如此。","notes":[]},{"n":20,"t":"灯台上有四个杯，形状像杏花，有球有花。","notes":[]},{"n":21,"t":"灯台每两个枝子以下有球，与枝子接连一块；灯台杈出的六个枝子都是如此。","notes":[]},{"n":22,"t":"球和枝子是接连一块，都是一块精金锤出来的。","notes":[]},{"n":23,"t":"用精金做灯台的七个灯盏，并灯台的蜡剪和蜡花盘。","notes":[]},{"n":24,"t":"他用精金一他连得做灯台和灯台的一切器具。","notes":[]},{"n":25,"t":"他用皂荚木做香坛，是四方的，长一肘，宽一肘，高二肘，坛的四角与坛接连一块；","notes":[],"heads":["造香坛"]},{"n":26,"t":"又用精金把坛的上面与坛的四面并坛的四角包裹，又在坛的四围镶上金牙边。","notes":[]},{"n":27,"t":"做两个金环，安在牙子边以下，在坛的两旁、两根横撑上，作为穿杠的用处，以便抬坛。","notes":[]},{"n":28,"t":"用皂荚木做杠，用金包裹。","notes":[]},{"n":29,"t":"又按做香之法做圣膏油和馨香料的净香。","notes":[],"heads":["造圣油和圣膏"]}]},"38":{"heading":"造燔祭坛","verses":[{"n":1,"t":"他用皂荚木做燔祭坛，是四方的，长五肘，宽五肘，高三肘，","notes":[]},{"n":2,"t":"在坛的四拐角上做四个角，与坛接连一块，用铜把坛包裹。","notes":[]},{"n":3,"t":"他做坛上的盆、铲子、盘子、肉锸子、火鼎；这一切器具都是用铜做的。","notes":[]},{"n":4,"t":"又为坛做一个铜网，安在坛四面的围腰板以下，从下达到坛的半腰。","notes":[]},{"n":5,"t":"为铜网的四角铸四个环子，作为穿杠的用处。","notes":[]},{"n":6,"t":"用皂荚木做杠，用铜包裹，","notes":[]},{"n":7,"t":"把杠穿在坛两旁的环子内，用以抬坛，并用板做坛；坛是空的。","notes":[]},{"n":8,"t":"他用铜做洗濯盆和盆座，是用会幕门前伺候的妇人之镜子做的。","notes":[],"heads":["造铜盆"]},{"n":9,"t":"他做帐幕的院子。院子的南面用捻的细麻做帷子，宽一百肘。","notes":[],"heads":["耶和华会幕的周围"]},{"n":10,"t":"帷子的柱子二十根，带卯的铜座二十个；柱子上的钩子和杆子都是用银子做的。","notes":[]},{"n":11,"t":"北面也有帷子，宽一百肘。帷子的柱子二十根，带卯的铜座二十个；柱子上的钩子和杆子都是用银子做的。","notes":[]},{"n":12,"t":"院子的西面有帷子，宽五十肘。帷子的柱子十根，带卯的座十个；柱子的钩子和杆子都是用银子做的。","notes":[]},{"n":13,"t":"院子的东面，宽五十肘。","notes":[]},{"n":14,"t":"门这边的帷子十五肘，那边也是一样。帷子的柱子三根，带卯的座三个。在门的左右各有帷子十五肘，帷子的柱子三根，带卯的座三个。","notes":[],"end":15},{"n":16,"t":"院子四面的帷子都是用捻的细麻做的。","notes":[]},{"n":17,"t":"柱子带卯的座是铜的，柱子上的钩子和杆子是银的，柱顶是用银子包的。院子一切的柱子都是用银杆连络的。","notes":[]},{"n":18,"t":"院子的门帘是以绣花的手工，用蓝色、紫色、朱红色线，和捻的细麻织的，宽二十肘，高五肘，与院子的帷子相配。","notes":[]},{"n":19,"t":"帷子的柱子四根，带卯的铜座四个；柱子上的钩子和杆子是银的；柱顶是用银子包的。","notes":[]},{"n":20,"t":"帐幕一切的橛子和院子四围的橛子都是铜的。","notes":[]},{"n":21,"t":"这是法柜的帐幕中利未人所用物件的总数，是照摩西的吩咐，经祭司亚伦的儿子以他玛的手数点的。","notes":[],"heads":["耶和华会幕所用的金属"]},{"n":22,"t":"凡耶和华所吩咐摩西的都是犹大支派户珥的孙子、乌利的儿子比撒列做的。","notes":[]},{"n":23,"t":"与他同工的有但支派中亚希撒抹的儿子亚何利亚伯；他是雕刻匠，又是巧匠，又能用蓝色、紫色、朱红色线，和细麻绣花。","notes":[]},{"n":24,"t":"为圣所一切工作使用所献的金子，按圣所的平，有二十九他连得并七百三十舍客勒。","notes":[]},{"n":25,"t":"会中被数的人所出的银子，按圣所的平，有一百他连得并一千七百七十五舍客勒。","notes":[]},{"n":26,"t":"凡过去归那些被数之人的，从二十岁以外，有六十万零三千五百五十人。按圣所的平，每人出银半舍客勒，就是一比加。","notes":[]},{"n":27,"t":"用那一百他连得银子铸造圣所带卯的座和幔子柱子带卯的座；一百他连得共一百带卯的座，每带卯的座用一他连得。","notes":[]},{"n":28,"t":"用那一千七百七十五舍客勒银子做柱子上的钩子，包裹柱顶并柱子上的杆子。","notes":[]},{"n":29,"t":"所献的铜有七十他连得并二千四百舍客勒。","notes":[]},{"n":30,"t":"用这铜做会幕门带卯的座和铜坛，并坛上的铜网和坛的一切器具，","notes":[]},{"n":31,"t":"并院子四围带卯的座和院门带卯的座，与帐幕一切的橛子和院子四围所有的橛子。","notes":[]}]},"39":{"heading":"为祭司制圣服","verses":[{"n":1,"t":"比撒列用蓝色、紫色、朱红色线做精致的衣服，在圣所用以供职，又为亚伦做圣衣，是照耶和华所吩咐摩西的。","notes":[]},{"n":2,"t":"他用金线和蓝色、紫色、朱红色线，并捻的细麻做以弗得；","notes":[]},{"n":3,"t":"把金子锤成薄片，剪出线来，与蓝色、紫色、朱红色线，用巧匠的手工一同绣上。","notes":[]},{"n":4,"t":"又为以弗得做两条相连的肩带，接连在以弗得的两头。","notes":[]},{"n":5,"t":"其上巧工织的带子和以弗得一样的做法，用以束上，与以弗得接连一块，是用金线和蓝色、紫色、朱红色线，并捻的细麻做的，是照耶和华所吩咐摩西的。","notes":[]},{"n":6,"t":"又琢出两块红玛瑙，镶在金槽上，仿佛刻图书，按着以色列儿子的名字雕刻；","notes":[]},{"n":7,"t":"将这两块宝石安在以弗得的两条肩带上，为以色列人做纪念石，是照耶和华所吩咐摩西的。","notes":[]},{"n":8,"t":"他用巧匠的手工做胸牌，和以弗得一样的做法，用金线与蓝色、紫色、朱红色线，并捻的细麻做的。","notes":[],"heads":["制胸牌"]},{"n":9,"t":"胸牌是四方的，叠为两层；这两层长一虎口，宽一虎口，","notes":[]},{"n":10,"t":"上面镶着宝石四行：第一行是红宝石、红璧玺、红玉；","notes":[]},{"n":11,"t":"第二行是绿宝石、蓝宝石、金钢石；","notes":[]},{"n":12,"t":"第三行是紫玛瑙、白玛瑙、紫晶；","notes":[]},{"n":13,"t":"第四行是水苍玉、红玛瑙、碧玉。这都镶在金槽中。","notes":[]},{"n":14,"t":"这些宝石都是按着以色列十二个儿子的名字，仿佛刻图书，刻十二个支派的名字。","notes":[]},{"n":15,"t":"在胸牌上，用精金拧成如绳子的链子。","notes":[]},{"n":16,"t":"又做两个金槽和两个金环，安在胸牌的两头。","notes":[]},{"n":17,"t":"把那两条拧成的金链子穿过胸牌两头的环子，","notes":[]},{"n":18,"t":"又把链子的那两头接在两槽上，安在以弗得前面肩带上。","notes":[]},{"n":19,"t":"做两个金环，安在胸牌的两头，在以弗得里面的边上，","notes":[]},{"n":20,"t":"又做两个金环，安在以弗得前面两条肩带的下边，挨近相接之处，在以弗得巧工织的带子以上。","notes":[]},{"n":21,"t":"用一条蓝细带子把胸牌的环子和以弗得的环子系住，使胸牌贴在以弗得巧工织的带子上，不可与以弗得离缝，是照耶和华所吩咐摩西的。","notes":[]},{"n":22,"t":"他用织工做以弗得的外袍，颜色全是蓝的。","notes":[],"heads":["祭司其他的圣服"]},{"n":23,"t":"袍上留一领口，口的周围织出领边来，仿佛铠甲的领口，免得破裂。","notes":[]},{"n":24,"t":"在袍子底边上，用蓝色、紫色、朱红色线，并捻的细麻做石榴，","notes":[]},{"n":25,"t":"又用精金做铃铛，把铃铛钉在袍子周围底边上的石榴中间：","notes":[]},{"n":26,"t":"一个铃铛一个石榴，一个铃铛一个石榴，在袍子周围底边上用以供职，是照耶和华所吩咐摩西的。","notes":[]},{"n":27,"t":"他用织成的细麻布为亚伦和他的儿子做内袍，","notes":[]},{"n":28,"t":"并用细麻布做冠冕和华美的裹头巾，用捻的细麻布做裤子，","notes":[]},{"n":29,"t":"又用蓝色、紫色、朱红色线，并捻的细麻，以绣花的手工做腰带，是照耶和华所吩咐摩西的。","notes":[]},{"n":30,"t":"他用精金做圣冠上的牌，在上面按刻图书之法，刻着「归耶和华为圣」。","notes":[]},{"n":31,"t":"又用一条蓝细带子将牌系在冠冕上，是照耶和华所吩咐摩西的。","notes":[]},{"n":32,"t":"帐幕，就是会幕，一切的工就这样做完了。凡耶和华所吩咐摩西的，以色列人都照样做了。","notes":[],"heads":["会幕完工"]},{"n":33,"t":"他们送到摩西那里。帐幕和帐幕的一切器具，就是钩子、板、闩、柱子、带卯的座，","notes":[]},{"n":34,"t":"染红公羊皮的盖、海狗皮的顶盖，和遮掩柜的幔子，","notes":[]},{"n":35,"t":"法柜和柜的杠并施恩座，","notes":[]},{"n":36,"t":"桌子和桌子的一切器具并陈设饼，","notes":[]},{"n":37,"t":"精金的灯台和摆列的灯盏，与灯台的一切器具，并点灯的油，","notes":[]},{"n":38,"t":"金坛、膏油、馨香的香料、会幕的门帘，","notes":[]},{"n":39,"t":"铜坛和坛上的铜网，坛的杠并坛的一切器具，洗濯盆和盆座，","notes":[]},{"n":40,"t":"院子的帷子和柱子，并带卯的座，院子的门帘、绳子、橛子，并帐幕和会幕中一切使用的器具，","notes":[]},{"n":41,"t":"精工做的礼服，和祭司亚伦并他儿子在圣所用以供祭司职分的圣衣。","notes":[]},{"n":42,"t":"这一切工作都是以色列人照耶和华所吩咐摩西做的。","notes":[]},{"n":43,"t":"耶和华怎样吩咐的，他们就怎样做了。摩西看见一切的工都做成了，就给他们祝福。","notes":[]}]},"40":{"heading":"耶和华会幕的建立和奉献","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「正月初一日，你要立起帐幕，","notes":[]},{"n":3,"t":"把法柜安放在里面，用幔子将柜遮掩。","notes":[]},{"n":4,"t":"把桌子搬进去，摆设上面的物。把灯台搬进去，点其上的灯。","notes":[]},{"n":5,"t":"把烧香的金坛安在法柜前，挂上帐幕的门帘。","notes":[]},{"n":6,"t":"把燔祭坛安在帐幕门前。","notes":[]},{"n":7,"t":"把洗濯盆安在会幕和坛的中间，在盆里盛水。","notes":[]},{"n":8,"t":"又在四围立院帷，把院子的门帘挂上。","notes":[]},{"n":9,"t":"用膏油把帐幕和其中所有的都抹上，使帐幕和一切器具成圣，就都成圣。","notes":[]},{"n":10,"t":"又要抹燔祭坛和一切器具，使坛成圣，就都成为至圣。","notes":[]},{"n":11,"t":"要抹洗濯盆和盆座，使盆成圣。","notes":[]},{"n":12,"t":"要使亚伦和他儿子到会幕门口来，用水洗身。","notes":[]},{"n":13,"t":"要给亚伦穿上圣衣，又膏他，使他成圣，可以给我供祭司的职分；","notes":[]},{"n":14,"t":"又要使他儿子来，给他们穿上内袍。","notes":[]},{"n":15,"t":"怎样膏他们的父亲，也要照样膏他们，使他们给我供祭司的职分。他们世世代代凡受膏的，就永远当祭司的职任。」","notes":[]},{"n":16,"t":"摩西这样行，都是照耶和华所吩咐他的。","notes":[]},{"n":17,"t":"第二年正月初一日，帐幕就立起来。","notes":[]},{"n":18,"t":"摩西立起帐幕，安上带卯的座，立上板，穿上闩，立起柱子。","notes":[]},{"n":19,"t":"在帐幕以上搭罩棚，把罩棚的顶盖盖在其上，是照耶和华所吩咐他的。","notes":[]},{"n":20,"t":"又把法版放在柜里，把杠穿在柜的两旁，把施恩座安在柜上。","notes":[]},{"n":21,"t":"把柜抬进帐幕，挂上遮掩柜的幔子，把法柜遮掩了，是照耶和华所吩咐他的。","notes":[]},{"n":22,"t":"又把桌子安在会幕内，在帐幕北边，在幔子外。","notes":[]},{"n":23,"t":"在桌子上将饼陈设在耶和华面前，是照耶和华所吩咐他的。","notes":[]},{"n":24,"t":"又把灯台安在会幕内，在帐幕南边，与桌子相对，","notes":[]},{"n":25,"t":"在耶和华面前点灯，是照耶和华所吩咐他的。","notes":[]},{"n":26,"t":"把金坛安在会幕内的幔子前，","notes":[]},{"n":27,"t":"在坛上烧了馨香料做的香，是照耶和华所吩咐他的。","notes":[]},{"n":28,"t":"又挂上帐幕的门帘。","notes":[]},{"n":29,"t":"在会幕的帐幕门前，安设燔祭坛，把燔祭和素祭献在其上，是照耶和华所吩咐他的。","notes":[]},{"n":30,"t":"把洗濯盆安在会幕和坛的中间，盆中盛水，以便洗濯。","notes":[]},{"n":31,"t":"摩西和亚伦并亚伦的儿子在这盆里洗手洗脚。","notes":[]},{"n":32,"t":"他们进会幕或就近坛的时候，便都洗濯，是照耶和华所吩咐他的。","notes":[]},{"n":33,"t":"在帐幕和坛的四围立了院帷，把院子的门帘挂上。这样，摩西就完了工。","notes":[]},{"n":34,"t":"当时，云彩遮盖会幕，耶和华的荣光就充满了帐幕。","notes":[],"heads":["云彩覆盖会幕"]},{"n":35,"t":"摩西不能进会幕；因为云彩停在其上，并且耶和华的荣光充满了帐幕。","notes":[]},{"n":36,"t":"每逢云彩从帐幕收上去，以色列人就起程前往；","notes":[]},{"n":37,"t":"云彩若不收上去，他们就不起程，直等到云彩收上去。","notes":[]},{"n":38,"t":"日间，耶和华的云彩是在帐幕以上；夜间，云中有火，在以色列全家的眼前。在他们所行的路上都是这样。","notes":[]}]}},"LEV":{"1":{"heading":"燔祭的条例","verses":[{"n":1,"t":"耶和华从会幕中呼叫摩西，对他说：","notes":[]},{"n":2,"t":"「你晓谕以色列人说：你们中间若有人献供物给耶和华，要从牛群羊群中献牲畜为供物。","notes":[]},{"n":3,"t":"「他的供物若以牛为燔祭，就要在会幕门口献一只没有残疾的公牛，可以在耶和华面前蒙悦纳。","notes":[]},{"n":4,"t":"他要按手在燔祭牲的头上，燔祭便蒙悦纳，为他赎罪。","notes":[]},{"n":5,"t":"他要在耶和华面前宰公牛；亚伦子孙作祭司的，要奉上血，把血洒在会幕门口、坛的周围。","notes":[]},{"n":6,"t":"那人要剥去燔祭牲的皮，把燔祭牲切成块子。","notes":[]},{"n":7,"t":"祭司亚伦的子孙要把火放在坛上，把柴摆在火上。","notes":[]},{"n":8,"t":"亚伦子孙作祭司的，要把肉块和头并脂油摆在坛上火的柴上。","notes":[]},{"n":9,"t":"但燔祭的脏腑与腿要用水洗。祭司就要把一切全烧在坛上，当作燔祭，献与耶和华为馨香的火祭。","notes":[]},{"n":10,"t":"「人的供物若以绵羊或山羊为燔祭，就要献上没有残疾的公羊。","notes":[]},{"n":11,"t":"要把羊宰于坛的北边，在耶和华面前；亚伦子孙作祭司的，要把羊血洒在坛的周围。","notes":[]},{"n":12,"t":"要把燔祭牲切成块子，连头和脂油，祭司就要摆在坛上火的柴上；","notes":[]},{"n":13,"t":"但脏腑与腿要用水洗，祭司就要全然奉献，烧在坛上。这是燔祭，是献与耶和华为馨香的火祭。","notes":[]},{"n":14,"t":"「人奉给耶和华的供物，若以鸟为燔祭，就要献斑鸠或是雏鸽为供物。","notes":[]},{"n":15,"t":"祭司要把鸟拿到坛前，揪下头来，把鸟烧在坛上；鸟的血要流在坛的旁边；","notes":[]},{"n":16,"t":"又要把鸟的嗉子和脏物除掉，丢在坛的东边倒灰的地方。","notes":["脏物：或译翎毛"]},{"n":17,"t":"要拿着鸟的两个翅膀，把鸟撕开，只是不可撕断；祭司要在坛上、在火的柴上焚烧。这是燔祭，是献与耶和华为馨香的火祭。」","notes":[]}]},"2":{"heading":"素祭的条例","verses":[{"n":1,"t":"「若有人献素祭为供物给耶和华，要用细面浇上油，加上乳香，","notes":[]},{"n":2,"t":"带到亚伦子孙作祭司的那里；祭司就要从细面中取出一把来，并取些油和所有的乳香，然后要把所取的这些作为纪念，烧在坛上，是献与耶和华为馨香的火祭。","notes":[]},{"n":3,"t":"素祭所剩的要归给亚伦和他的子孙；这是献与耶和华的火祭中为至圣的。","notes":[]},{"n":4,"t":"「若用炉中烤的物为素祭，就要用调油的无酵细面饼，或是抹油的无酵薄饼。","notes":[]},{"n":5,"t":"若用铁鏊上做的物为素祭，就要用调油的无酵细面，","notes":[]},{"n":6,"t":"分成块子，浇上油；这是素祭。","notes":[]},{"n":7,"t":"若用煎盘做的物为素祭，就要用油与细面做成。","notes":[]},{"n":8,"t":"要把这些东西做的素祭带到耶和华面前，并奉给祭司，带到坛前。","notes":[]},{"n":9,"t":"祭司要从素祭中取出作为纪念的，烧在坛上，是献与耶和华为馨香的火祭。","notes":[]},{"n":10,"t":"素祭所剩的要归给亚伦和他的子孙。这是献与耶和华的火祭中为至圣的。","notes":[]},{"n":11,"t":"「凡献给耶和华的素祭都不可有酵；因为你们不可烧一点酵、一点蜜当作火祭献给耶和华。","notes":[]},{"n":12,"t":"这些物要献给耶和华作为初熟的供物，只是不可在坛上献为馨香的祭。","notes":[]},{"n":13,"t":"凡献为素祭的供物都要用盐调和，在素祭上不可缺了你神立约的盐。一切的供物都要配盐而献。","notes":[]},{"n":14,"t":"若向耶和华献初熟之物为素祭，要献上烘了的禾穗子，就是轧了的新穗子，当作初熟之物的素祭。","notes":[]},{"n":15,"t":"并要抹上油，加上乳香；这是素祭。","notes":[]},{"n":16,"t":"祭司要把其中作为纪念的，就是一些轧了的禾穗子和一些油，并所有的乳香，都焚烧，是向耶和华献的火祭。」","notes":[]}]},"3":{"heading":"平安祭的条例","verses":[{"n":1,"t":"「人献供物为平安祭，若是从牛群中献，无论是公的是母的，必用没有残疾的献在耶和华面前。","notes":["平安：或译酬恩；下同"]},{"n":2,"t":"他要按手在供物的头上，宰于会幕门口。亚伦子孙作祭司的，要把血洒在坛的周围。","notes":[]},{"n":3,"t":"从平安祭中，将火祭献给耶和华，也要把盖脏的脂油和脏上所有的脂油，","notes":[]},{"n":4,"t":"并两个腰子和腰子上的脂油，就是靠腰两旁的脂油，与肝上的网子和腰子，一概取下。","notes":[]},{"n":5,"t":"亚伦的子孙要把这些烧在坛的燔祭上，就是在火的柴上，是献与耶和华为馨香的火祭。","notes":[]},{"n":6,"t":"「人向耶和华献供物为平安祭，若是从羊群中献，无论是公的是母的，必用没有残疾的。","notes":[]},{"n":7,"t":"若献一只羊羔为供物，必在耶和华面前献上，","notes":[]},{"n":8,"t":"并要按手在供物的头上，宰于会幕前。亚伦的子孙要把血洒在坛的周围。","notes":[]},{"n":9,"t":"从平安祭中，将火祭献给耶和华，其中的脂油和整肥尾巴都要在靠近脊骨处取下，并要把盖脏的脂油和脏上所有的脂油，","notes":[]},{"n":10,"t":"两个腰子和腰子上的脂油，就是靠腰两旁的脂油，并肝上的网子和腰子，一概取下。","notes":[]},{"n":11,"t":"祭司要在坛上焚烧，是献给耶和华为食物的火祭。","notes":[]},{"n":12,"t":"「人的供物若是山羊，必在耶和华面前献上。","notes":[]},{"n":13,"t":"要按手在山羊头上，宰于会幕前。亚伦的子孙要把血洒在坛的周围，","notes":[]},{"n":14,"t":"又把盖脏的脂油和脏上所有的脂油，两个腰子和腰子上的脂油，就是靠腰两旁的脂油，并肝上的网子和腰子，一概取下，献给耶和华为火祭。","notes":[],"end":15},{"n":16,"t":"祭司要在坛上焚烧，作为馨香火祭的食物。脂油都是耶和华的。","notes":[]},{"n":17,"t":"在你们一切的住处，脂油和血都不可吃；这要成为你们世世代代永远的定例。」","notes":[]}]},"4":{"heading":"为误犯的罪献祭的条例","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你晓谕以色列人说：若有人在耶和华所吩咐不可行的什么事上误犯了一件，","notes":[]},{"n":3,"t":"或是受膏的祭司犯罪，使百姓陷在罪里，就当为他所犯的罪把没有残疾的公牛犊献给耶和华为赎罪祭。","notes":[]},{"n":4,"t":"他要牵公牛到会幕门口，在耶和华面前按手在牛的头上，把牛宰于耶和华面前。","notes":[]},{"n":5,"t":"受膏的祭司要取些公牛的血带到会幕，","notes":[]},{"n":6,"t":"把指头蘸于血中，在耶和华面前对着圣所的幔子弹血七次，","notes":[]},{"n":7,"t":"又要把些血抹在会幕内、耶和华面前香坛的四角上，再把公牛所有的血倒在会幕门口、燔祭坛的脚那里。","notes":[]},{"n":8,"t":"要把赎罪祭公牛所有的脂油，乃是盖脏的脂油和脏上所有的脂油，","notes":[]},{"n":9,"t":"并两个腰子和腰子上的脂油，就是靠腰两旁的脂油，与肝上的网子和腰子，一概取下，","notes":[]},{"n":10,"t":"与平安祭公牛上所取的一样；祭司要把这些烧在燔祭的坛上。","notes":[]},{"n":11,"t":"公牛的皮和所有的肉，并头、腿、脏、腑、粪，","notes":[]},{"n":12,"t":"就是全公牛，要搬到营外洁净之地、倒灰之所，用火烧在柴上。","notes":[]},{"n":13,"t":"「以色列全会众若行了耶和华所吩咐不可行的什么事，误犯了罪，是隐而未现、会众看不出来的，","notes":[]},{"n":14,"t":"会众一知道所犯的罪就要献一只公牛犊为赎罪祭，牵到会幕前。","notes":[]},{"n":15,"t":"会中的长老就要在耶和华面前按手在牛的头上，将牛在耶和华面前宰了。","notes":[]},{"n":16,"t":"受膏的祭司要取些公牛的血带到会幕，","notes":[]},{"n":17,"t":"把指头蘸于血中，在耶和华面前对着幔子弹血七次，","notes":[]},{"n":18,"t":"又要把些血抹在会幕内、耶和华面前坛的四角上，再把所有的血倒在会幕门口、燔祭坛的脚那里。","notes":[]},{"n":19,"t":"把牛所有的脂油都取下，烧在坛上；","notes":[]},{"n":20,"t":"收拾这牛，与那赎罪祭的牛一样。祭司要为他们赎罪，他们必蒙赦免。","notes":[]},{"n":21,"t":"他要把牛搬到营外烧了，像烧头一个牛一样；这是会众的赎罪祭。","notes":[]},{"n":22,"t":"「官长若行了耶和华—他神所吩咐不可行的什么事，误犯了罪，","notes":[]},{"n":23,"t":"所犯的罪自己知道了，就要牵一只没有残疾的公山羊为供物，","notes":[]},{"n":24,"t":"按手在羊的头上，宰于耶和华面前、宰燔祭牲的地方；这是赎罪祭。","notes":[]},{"n":25,"t":"祭司要用指头蘸些赎罪祭牲的血，抹在燔祭坛的四角上，把血倒在燔祭坛的脚那里。","notes":[]},{"n":26,"t":"所有的脂油，祭司都要烧在坛上，正如平安祭的脂油一样。至于他的罪，祭司要为他赎了，他必蒙赦免。","notes":[]},{"n":27,"t":"「民中若有人行了耶和华所吩咐不可行的什么事，误犯了罪，","notes":[]},{"n":28,"t":"所犯的罪自己知道了，就要为所犯的罪牵一只没有残疾的母山羊为供物，","notes":[]},{"n":29,"t":"按手在赎罪祭牲的头上，在那宰燔祭牲的地方宰了。","notes":[]},{"n":30,"t":"祭司要用指头蘸些羊的血，抹在燔祭坛的四角上，所有的血都要倒在坛的脚那里，","notes":[]},{"n":31,"t":"又要把羊所有的脂油都取下，正如取平安祭牲的脂油一样。祭司要在坛上焚烧，在耶和华面前作为馨香的祭，为他赎罪，他必蒙赦免。","notes":[]},{"n":32,"t":"「人若牵一只绵羊羔为赎罪祭的供物，必要牵一只没有残疾的母羊，","notes":[]},{"n":33,"t":"按手在赎罪祭牲的头上，在那宰燔祭牲的地方宰了作赎罪祭。","notes":[]},{"n":34,"t":"祭司要用指头蘸些赎罪祭牲的血，抹在燔祭坛的四角上，所有的血都要倒在坛的脚那里，","notes":[]},{"n":35,"t":"又要把所有的脂油都取下，正如取平安祭羊羔的脂油一样。祭司要按献给耶和华火祭的条例，烧在坛上。至于所犯的罪，祭司要为他赎了，他必蒙赦免。」","notes":[]}]},"5":{"heading":"赎愆祭的条例","verses":[{"n":1,"t":"「若有人听见发誓的声音，他本是见证，却不把所看见的、所知道的说出来，这就是罪；他要担当他的罪孽。","notes":["或译：若有人听见叫人发誓的声音"]},{"n":2,"t":"或是有人摸了不洁的物，无论是不洁的死兽，是不洁的死畜，是不洁的死虫，他却不知道，因此成了不洁，就有了罪。","notes":[]},{"n":3,"t":"或是他摸了别人的污秽，无论是染了什么污秽，他却不知道，一知道了就有了罪。","notes":[]},{"n":4,"t":"或是有人嘴里冒失发誓，要行恶，要行善，无论人在什么事上冒失发誓，他却不知道，一知道了就要在这其中的一件上有了罪。","notes":[]},{"n":5,"t":"他有了罪的时候，就要承认所犯的罪，","notes":[]},{"n":6,"t":"并要因所犯的罪，把他的赎愆祭牲—就是羊群中的母羊，或是一只羊羔，或是一只山羊—牵到耶和华面前为赎罪祭。至于他的罪，祭司要为他赎了。","notes":[]},{"n":7,"t":"「他的力量若不够献一只羊羔，就要因所犯的罪，把两只斑鸠或是两只雏鸽带到耶和华面前为赎愆祭：一只作赎罪祭，一只作燔祭。","notes":[]},{"n":8,"t":"把这些带到祭司那里，祭司就要先把那赎罪祭献上，从鸟的颈项上揪下头来，只是不可把鸟撕断，","notes":[]},{"n":9,"t":"也把些赎罪祭牲的血弹在坛的旁边，剩下的血要流在坛的脚那里；这是赎罪祭。","notes":[]},{"n":10,"t":"他要照例献第二只为燔祭。至于他所犯的罪，祭司要为他赎了，他必蒙赦免。","notes":[]},{"n":11,"t":"「他的力量若不够献两只斑鸠或是两只雏鸽，就要因所犯的罪带供物来，就是细面伊法十分之一为赎罪祭；不可加上油，也不可加上乳香，因为是赎罪祭。","notes":[]},{"n":12,"t":"他要把供物带到祭司那里，祭司要取出自己的一把来作为纪念，按献给耶和华火祭的条例烧在坛上；这是赎罪祭。","notes":[]},{"n":13,"t":"至于他在这几件事中所犯的罪，祭司要为他赎了，他必蒙赦免。剩下的面都归与祭司，和素祭一样。」","notes":[]},{"n":14,"t":"耶和华晓谕摩西说：","notes":[]},{"n":15,"t":"「人若在耶和华的圣物上误犯了罪，有了过犯，就要照你所估的，按圣所的舍客勒拿银子，将赎愆祭牲—就是羊群中一只没有残疾的公绵羊—牵到耶和华面前为赎愆祭；","notes":[]},{"n":16,"t":"并且他因在圣物上的差错要偿还，另外加五分之一，都给祭司。祭司要用赎愆祭的公绵羊为他赎罪，他必蒙赦免。","notes":[]},{"n":17,"t":"「若有人犯罪，行了耶和华所吩咐不可行的什么事，他虽然不知道，还是有了罪，就要担当他的罪孽；","notes":[]},{"n":18,"t":"也要照你所估定的价，从羊群中牵一只没有残疾的公绵羊来，给祭司作赎愆祭。至于他误行的那错事，祭司要为他赎罪，他必蒙赦免。","notes":[]},{"n":19,"t":"这是赎愆祭，因他在耶和华面前实在有了罪。」","notes":[]}]},"6":{"heading":"祭司献燔祭的责任","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「若有人犯罪，干犯耶和华，在邻舍交付他的物上，或是在交易上行了诡诈，或是抢夺人的财物，或是欺压邻舍，","notes":[]},{"n":3,"t":"或是在捡了遗失的物上行了诡诈，说谎起誓，在这一切的事上犯了什么罪；","notes":[]},{"n":4,"t":"他既犯了罪，有了过犯，就要归还他所抢夺的，或是因欺压所得的，或是人交付他的，或是人遗失他所捡的物，","notes":[]},{"n":5,"t":"或是他因什么物起了假誓，就要如数归还，另外加上五分之一，在查出他有罪的日子要交还本主。","notes":[]},{"n":6,"t":"也要照你所估定的价，把赎愆祭牲—就是羊群中一只没有残疾的公绵羊—牵到耶和华面前，给祭司为赎愆祭。","notes":[]},{"n":7,"t":"祭司要在耶和华面前为他赎罪；他无论行了什么事，使他有了罪，都必蒙赦免。」","notes":[]},{"n":8,"t":"耶和华晓谕摩西说：","notes":[]},{"n":9,"t":"「你要吩咐亚伦和他的子孙说，燔祭的条例乃是这样：燔祭要放在坛的柴上，从晚上到天亮，坛上的火要常常烧着。","notes":[]},{"n":10,"t":"祭司要穿上细麻布衣服，又要把细麻布裤子穿在身上，把坛上所烧的燔祭灰收起来，倒在坛的旁边；","notes":[]},{"n":11,"t":"随后要脱去这衣服，穿上别的衣服，把灰拿到营外洁净之处。","notes":[]},{"n":12,"t":"坛上的火要在其上常常烧着，不可熄灭。祭司要每日早晨在上面烧柴，并要把燔祭摆在坛上，在其上烧平安祭牲的脂油。","notes":[]},{"n":13,"t":"在坛上必有常常烧着的火，不可熄灭。」","notes":[]},{"n":14,"t":"「素祭的条例乃是这样：亚伦的子孙要在坛前把这祭献在耶和华面前。","notes":[],"heads":["祭司献素祭的责任"]},{"n":15,"t":"祭司要从其中—就是从素祭的细面中—取出自己的一把，又要取些油和素祭上所有的乳香，烧在坛上，奉给耶和华为馨香素祭的纪念。","notes":[]},{"n":16,"t":"所剩下的，亚伦和他子孙要吃，必在圣处不带酵而吃，要在会幕的院子里吃。","notes":[]},{"n":17,"t":"烤的时候不可搀酵。这是从所献给我的火祭中赐给他们的分，是至圣的，和赎罪祭并赎愆祭一样。","notes":[]},{"n":18,"t":"凡献给耶和华的火祭，亚伦子孙中的男丁都要吃这一分，直到万代，作他们永得的分。摸这些祭物的，都要成为圣。」","notes":[]},{"n":19,"t":"耶和华晓谕摩西说：","notes":[]},{"n":20,"t":"「当亚伦受膏的日子，他和他子孙所要献给耶和华的供物，就是细面伊法十分之一，为常献的素祭：早晨一半，晚上一半。","notes":[]},{"n":21,"t":"要在铁鏊上用油调和做成，调匀了，你就拿进来；烤好了分成块子，献给耶和华为馨香的素祭。","notes":[]},{"n":22,"t":"亚伦的子孙中，接续他为受膏的祭司，要把这素祭献上，要全烧给耶和华。这是永远的定例。","notes":[]},{"n":23,"t":"祭司的素祭都要烧了，却不可吃。」","notes":[]},{"n":24,"t":"耶和华晓谕摩西说：","notes":[],"heads":["祭司献赎罪祭的责任"]},{"n":25,"t":"「你对亚伦和他的子孙说，赎罪祭的条例乃是这样：要在耶和华面前、宰燔祭牲的地方宰赎罪祭牲；这是至圣的。","notes":[]},{"n":26,"t":"为赎罪献这祭的祭司要吃，要在圣处，就是在会幕的院子里吃。","notes":[]},{"n":27,"t":"凡摸这祭肉的要成为圣；这祭牲的血若弹在什么衣服上，所弹的那一件要在圣处洗净。","notes":[]},{"n":28,"t":"惟有煮祭物的瓦器要打碎；若是煮在铜器里，这铜器要擦磨，在水中涮净。","notes":[]},{"n":29,"t":"凡祭司中的男丁都可以吃；这是至圣的。","notes":[]},{"n":30,"t":"凡赎罪祭，若将血带进会幕在圣所赎罪，那肉都不可吃，必用火焚烧。」","notes":[]}]},"7":{"heading":"祭司献赎愆祭的责任","verses":[{"n":1,"t":"「赎愆祭的条例乃是如此：这祭是至圣的。","notes":[]},{"n":2,"t":"人在那里宰燔祭牲，也要在那里宰赎愆祭牲；其血，祭司要洒在坛的周围。","notes":[]},{"n":3,"t":"又要将肥尾巴和盖脏的脂油，","notes":[]},{"n":4,"t":"两个腰子和腰子上的脂油，就是靠腰两旁的脂油，并肝上的网子和腰子，一概取下。","notes":[]},{"n":5,"t":"祭司要在坛上焚烧，为献给耶和华的火祭，是赎愆祭。","notes":[]},{"n":6,"t":"祭司中的男丁都可以吃这祭物；要在圣处吃，是至圣的。","notes":[]},{"n":7,"t":"赎罪祭怎样，赎愆祭也是怎样，两个祭是一个条例。献赎愆祭赎罪的祭司要得这祭物。","notes":[]},{"n":8,"t":"献燔祭的祭司，无论为谁奉献，要亲自得他所献那燔祭牲的皮。","notes":[]},{"n":9,"t":"凡在炉中烤的素祭和煎盘中做的，并铁鏊上做的，都要归那献祭的祭司。","notes":[]},{"n":10,"t":"凡素祭，无论是油调和的是干的，都要归亚伦的子孙，大家均分。」","notes":[]},{"n":11,"t":"「人献与耶和华平安祭的条例乃是这样：","notes":[],"heads":["祭司献平安祭的责任"]},{"n":12,"t":"他若为感谢献上，就要用调油的无酵饼和抹油的无酵薄饼，并用油调匀细面做的饼，与感谢祭一同献上。","notes":[]},{"n":13,"t":"要用有酵的饼和为感谢献的平安祭，与供物一同献上。","notes":[]},{"n":14,"t":"从各样的供物中，他要把一个饼献给耶和华为举祭，是要归给洒平安祭牲血的祭司。","notes":[]},{"n":15,"t":"为感谢献平安祭牲的肉，要在献的日子吃，一点不可留到早晨。","notes":[]},{"n":16,"t":"若所献的是为还愿，或是甘心献的，必在献祭的日子吃，所剩下的第二天也可以吃。","notes":[]},{"n":17,"t":"但所剩下的祭肉，到第三天要用火焚烧；","notes":[]},{"n":18,"t":"第三天若吃了平安祭的肉，这祭必不蒙悦纳，人所献的也不算为祭，反为可憎嫌的，吃这祭肉的，就必担当他的罪孽。","notes":[]},{"n":19,"t":"「挨了污秽物的肉就不可吃，要用火焚烧。至于平安祭的肉，凡洁净的人都要吃；","notes":[]},{"n":20,"t":"只是献与耶和华平安祭的肉，人若不洁净而吃了，这人必从民中剪除。","notes":[]},{"n":21,"t":"有人摸了什么不洁净的物，或是人的不洁净，或是不洁净的牲畜，或是不洁可憎之物，吃了献与耶和华平安祭的肉，这人必从民中剪除。」","notes":[]},{"n":22,"t":"耶和华对摩西说：","notes":[]},{"n":23,"t":"「你晓谕以色列人说：牛的脂油、绵羊的脂油、山羊的脂油，你们都不可吃。","notes":[]},{"n":24,"t":"自死的和被野兽撕裂的，那脂油可以做别的使用，只是你们万不可吃。","notes":[]},{"n":25,"t":"无论何人吃了献给耶和华当火祭牲畜的脂油，那人必从民中剪除。","notes":[]},{"n":26,"t":"在你们一切的住处，无论是雀鸟的血是野兽的血，你们都不可吃。","notes":[]},{"n":27,"t":"无论是谁吃血，那人必从民中剪除。」","notes":[]},{"n":28,"t":"耶和华对摩西说：","notes":[]},{"n":29,"t":"「你晓谕以色列人说：献平安祭给耶和华的，要从平安祭中取些来奉给耶和华。","notes":[]},{"n":30,"t":"他亲手献给耶和华的火祭，就是脂油和胸，要带来，好把胸在耶和华面前作摇祭，摇一摇。","notes":[]},{"n":31,"t":"祭司要把脂油在坛上焚烧，但胸要归亚伦和他的子孙。","notes":[]},{"n":32,"t":"你们要从平安祭中把右腿作举祭，奉给祭司。","notes":[]},{"n":33,"t":"亚伦子孙中，献平安祭牲血和脂油的，要得这右腿为分；","notes":[]},{"n":34,"t":"因为我从以色列人的平安祭中，取了这摇的胸和举的腿给祭司亚伦和他子孙，作他们从以色列人中所永得的分。」","notes":[]},{"n":35,"t":"这是从耶和华火祭中，作亚伦受膏的分和他子孙受膏的分，正在摩西叫他们前来给耶和华供祭司职分的日子，","notes":["原文是他"]},{"n":36,"t":"就是在摩西膏他们的日子，耶和华吩咐以色列人给他们的。这是他们世世代代永得的分。","notes":["原文是他"]},{"n":37,"t":"这就是燔祭、素祭、赎罪祭、赎愆祭，和平安祭的条例，并承接圣职的礼，","notes":[]},{"n":38,"t":"都是耶和华在西奈山所吩咐摩西的，就是他在西奈旷野吩咐以色列人献供物给耶和华之日所说的。","notes":[]}]},"8":{"heading":"立亚伦和他的儿子们作祭司","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「你将亚伦和他儿子一同带来，并将圣衣、膏油，与赎罪祭的一只公牛、两只公绵羊、一筐无酵饼都带来，","notes":[]},{"n":3,"t":"又招聚会众到会幕门口。」","notes":[]},{"n":4,"t":"摩西就照耶和华所吩咐的行了；于是会众聚集在会幕门口。","notes":[]},{"n":5,"t":"摩西告诉会众说：「这就是耶和华所吩咐当行的事。」","notes":[]},{"n":6,"t":"摩西带了亚伦和他儿子来，用水洗了他们。","notes":[]},{"n":7,"t":"给亚伦穿上内袍，束上腰带，穿上外袍，又加上以弗得，用其上巧工织的带子把以弗得系在他身上，","notes":[]},{"n":8,"t":"又给他戴上胸牌，把乌陵和土明放在胸牌内，","notes":[]},{"n":9,"t":"把冠冕戴在他头上，在冠冕的前面钉上金牌，就是圣冠，都是照耶和华所吩咐摩西的。","notes":[]},{"n":10,"t":"摩西用膏油抹帐幕和其中所有的，使它成圣；","notes":[]},{"n":11,"t":"又用膏油在坛上弹了七次，又抹了坛和坛的一切器皿，并洗濯盆和盆座，使它成圣；","notes":[]},{"n":12,"t":"又把膏油倒在亚伦的头上膏他，使他成圣。","notes":[]},{"n":13,"t":"摩西带了亚伦的儿子来，给他们穿上内袍，束上腰带，包上裹头巾，都是照耶和华所吩咐摩西的。","notes":[]},{"n":14,"t":"他牵了赎罪祭的公牛来，亚伦和他儿子按手在赎罪祭公牛的头上，","notes":[]},{"n":15,"t":"就宰了公牛。摩西用指头蘸血，抹在坛上四角的周围，使坛洁净，把血倒在坛的脚那里，使坛成圣，坛就洁净了；","notes":[]},{"n":16,"t":"又取脏上所有的脂油和肝上的网子，并两个腰子与腰子上的脂油，都烧在坛上；","notes":[]},{"n":17,"t":"惟有公牛，连皮带肉并粪，用火烧在营外，都是照耶和华所吩咐摩西的。","notes":[]},{"n":18,"t":"他奉上燔祭的公绵羊；亚伦和他儿子按手在羊的头上，","notes":[]},{"n":19,"t":"就宰了公羊。摩西把血洒在坛的周围，","notes":[]},{"n":20,"t":"把羊切成块子，把头和肉块并脂油都烧了。","notes":[]},{"n":21,"t":"用水洗了脏腑和腿，就把全羊烧在坛上为馨香的燔祭，是献给耶和华的火祭，都是照耶和华所吩咐摩西的。","notes":[]},{"n":22,"t":"他又奉上第二只公绵羊，就是承接圣职之礼的羊；亚伦和他儿子按手在羊的头上，","notes":[]},{"n":23,"t":"就宰了羊。摩西把些血抹在亚伦的右耳垂上和右手的大拇指上，并右脚的大拇指上，","notes":[]},{"n":24,"t":"又带了亚伦的儿子来，把些血抹在他们的右耳垂上和右手的大拇指上，并右脚的大拇指上，又把血洒在坛的周围。","notes":[]},{"n":25,"t":"取脂油和肥尾巴，并脏上一切的脂油与肝上的网子，两个腰子和腰子上的脂油，并右腿，","notes":[]},{"n":26,"t":"再从耶和华面前、盛无酵饼的筐子里取出一个无酵饼，一个油饼，一个薄饼，都放在脂油和右腿上，","notes":[]},{"n":27,"t":"把这一切放在亚伦的手上和他儿子的手上作摇祭，在耶和华面前摇一摇。","notes":[]},{"n":28,"t":"摩西从他们的手上拿下来，烧在坛上的燔祭上，都是为承接圣职献给耶和华馨香的火祭。","notes":[]},{"n":29,"t":"摩西拿羊的胸作为摇祭，在耶和华面前摇一摇，是承接圣职之礼，归摩西的分，都是照耶和华所吩咐摩西的。","notes":[]},{"n":30,"t":"摩西取点膏油和坛上的血，弹在亚伦和他的衣服上，并他儿子和他儿子的衣服上，使他和他们的衣服一同成圣。","notes":[]},{"n":31,"t":"摩西对亚伦和他儿子说：「把肉煮在会幕门口，在那里吃，又吃承接圣职筐子里的饼，按我所吩咐的说：『这是亚伦和他儿子要吃的。』","notes":["或译：按所吩咐我的说"]},{"n":32,"t":"剩下的肉和饼，你们要用火焚烧。","notes":[]},{"n":33,"t":"你们七天不可出会幕的门，等到你们承接圣职的日子满了，因为主叫你们七天承接圣职。","notes":[]},{"n":34,"t":"像今天所行的都是耶和华吩咐行的，为你们赎罪。","notes":[]},{"n":35,"t":"七天你们要昼夜住在会幕门口，遵守耶和华的吩咐，免得你们死亡，因为所吩咐我的就是这样。」","notes":[]},{"n":36,"t":"于是亚伦和他儿子行了耶和华借着摩西所吩咐的一切事。","notes":[]}]},"9":{"heading":"亚伦献祭","verses":[{"n":1,"t":"到了第八天，摩西召了亚伦和他儿子，并以色列的众长老来，","notes":[]},{"n":2,"t":"对亚伦说：「你当取牛群中的一只公牛犊作赎罪祭，一只公绵羊作燔祭，都要没有残疾的，献在耶和华面前。","notes":[]},{"n":3,"t":"你也要对以色列人说：『你们当取一只公山羊作赎罪祭，又取一只牛犊和一只绵羊羔，都要一岁、没有残疾的，作燔祭，","notes":[]},{"n":4,"t":"又取一只公牛，一只公绵羊作平安祭，献在耶和华面前，并取调油的素祭，因为今天耶和华要向你们显现。』」","notes":[]},{"n":5,"t":"于是他们把摩西所吩咐的，带到会幕前；全会众都近前来，站在耶和华面前。","notes":[]},{"n":6,"t":"摩西说：「这是耶和华吩咐你们所当行的；耶和华的荣光就要向你们显现。」","notes":[]},{"n":7,"t":"摩西对亚伦说：「你就近坛前，献你的赎罪祭和燔祭，为自己与百姓赎罪，又献上百姓的供物，为他们赎罪，都照耶和华所吩咐的。」","notes":[]},{"n":8,"t":"于是，亚伦就近坛前，宰了为自己作赎罪祭的牛犊。","notes":[]},{"n":9,"t":"亚伦的儿子把血奉给他，他就把指头蘸在血中，抹在坛的四角上，又把血倒在坛脚那里。","notes":[]},{"n":10,"t":"惟有赎罪祭的脂油和腰子，并肝上取的网子，都烧在坛上，是照耶和华所吩咐摩西的；","notes":[]},{"n":11,"t":"又用火将肉和皮烧在营外。","notes":[]},{"n":12,"t":"亚伦宰了燔祭牲，他儿子把血递给他，他就洒在坛的周围，","notes":[]},{"n":13,"t":"又把燔祭一块一块地、连头递给他，他都烧在坛上；","notes":[]},{"n":14,"t":"又洗了脏腑和腿，烧在坛上的燔祭上。","notes":[]},{"n":15,"t":"他奉上百姓的供物，把那给百姓作赎罪祭的公山羊宰了，为罪献上，和先献的一样；","notes":[]},{"n":16,"t":"也奉上燔祭，照例而献。","notes":[]},{"n":17,"t":"他又奉上素祭，从其中取一满把，烧在坛上；这是在早晨的燔祭以外。","notes":[]},{"n":18,"t":"亚伦宰了那给百姓作平安祭的公牛和公绵羊。他儿子把血递给他，他就洒在坛的周围；","notes":[]},{"n":19,"t":"又把公牛和公绵羊的脂油、肥尾巴，并盖脏的脂油与腰子，和肝上的网子，都递给他；","notes":[]},{"n":20,"t":"把脂油放在胸上，他就把脂油烧在坛上。","notes":[]},{"n":21,"t":"胸和右腿，亚伦当作摇祭，在耶和华面前摇一摇，都是照摩西所吩咐的。","notes":[]},{"n":22,"t":"亚伦向百姓举手，为他们祝福。他献了赎罪祭、燔祭、平安祭就下来了。","notes":[]},{"n":23,"t":"摩西、亚伦进入会幕，又出来为百姓祝福，耶和华的荣光就向众民显现。","notes":[]},{"n":24,"t":"有火从耶和华面前出来，在坛上烧尽燔祭和脂油；众民一见，就都欢呼，俯伏在地。","notes":[]}]},"10":{"heading":"拿答和亚比户犯罪","verses":[{"n":1,"t":"亚伦的儿子拿答、亚比户各拿自己的香炉，盛上火，加上香，在耶和华面前献上凡火，是耶和华没有吩咐他们的，","notes":[]},{"n":2,"t":"就有火从耶和华面前出来，把他们烧灭，他们就死在耶和华面前。","notes":[]},{"n":3,"t":"于是摩西对亚伦说：「这就是耶和华所说：『我在亲近我的人中要显为圣；在众民面前，我要得荣耀。』」亚伦就默默不言。","notes":[]},{"n":4,"t":"摩西召了亚伦叔父乌薛的儿子米沙利、以利撒反来，对他们说：「上前来，把你们的亲属从圣所前抬到营外。」","notes":[]},{"n":5,"t":"于是二人上前来，把他们穿着袍子抬到营外，是照摩西所吩咐的。","notes":[]},{"n":6,"t":"摩西对亚伦和他儿子以利亚撒、以他玛说：「不可蓬头散发，也不可撕裂衣裳，免得你们死亡，又免得耶和华向会众发怒；只要你们的弟兄以色列全家为耶和华所发的火哀哭。","notes":[]},{"n":7,"t":"你们也不可出会幕的门，恐怕你们死亡，因为耶和华的膏油在你们的身上。」他们就照摩西的话行了。","notes":[]},{"n":8,"t":"耶和华晓谕亚伦说：","notes":[],"heads":["有关祭司的条例"]},{"n":9,"t":"「你和你儿子进会幕的时候，清酒、浓酒都不可喝，免得你们死亡；这要作你们世世代代永远的定例。","notes":[]},{"n":10,"t":"使你们可以将圣的、俗的，洁净的、不洁净的，分别出来；","notes":[]},{"n":11,"t":"又使你们可以将耶和华借摩西晓谕以色列人的一切律例教训他们。」","notes":[]},{"n":12,"t":"摩西对亚伦和他剩下的儿子以利亚撒、以他玛说：「你们献给耶和华火祭中所剩的素祭，要在坛旁不带酵而吃，因为是至圣的。","notes":[]},{"n":13,"t":"你们要在圣处吃；因为在献给耶和华的火祭中，这是你的分和你儿子的分；所吩咐我的本是这样。","notes":[]},{"n":14,"t":"所摇的胸，所举的腿，你们要在洁净地方吃。你和你的儿女都要同吃；因为这些是从以色列人平安祭中给你，当你的分和你儿子的分。","notes":[]},{"n":15,"t":"所举的腿，所摇的胸，他们要与火祭的脂油一同带来当摇祭，在耶和华面前摇一摇；这要归你和你儿子，当作永得的分，都是照耶和华所吩咐的。」","notes":[]},{"n":16,"t":"当下摩西急切地寻找作赎罪祭的公山羊，谁知已经焚烧了，便向亚伦剩下的儿子以利亚撒、以他玛发怒，说：","notes":[]},{"n":17,"t":"「这赎罪祭既是至圣的，主又给了你们，为要你们担当会众的罪孽，在耶和华面前为他们赎罪，你们为何没有在圣所吃呢？","notes":[]},{"n":18,"t":"看哪，这祭牲的血并没有拿到圣所里去，你们本当照我所吩咐的，在圣所里吃这祭肉。」","notes":[]},{"n":19,"t":"亚伦对摩西说：「今天他们在耶和华面前献上赎罪祭和燔祭，我又遇见这样的灾，若今天吃了赎罪祭，耶和华岂能看为美呢？」","notes":[]},{"n":20,"t":"摩西听见这话，便以为美。","notes":[]}]},"11":{"heading":"有关食物的条例","verses":[{"n":1,"t":"耶和华对摩西、亚伦说：","notes":[]},{"n":2,"t":"「你们晓谕以色列人说，在地上一切走兽中可吃的乃是这些：","notes":[]},{"n":3,"t":"凡蹄分两瓣、倒嚼的走兽，你们都可以吃。","notes":[]},{"n":4,"t":"但那倒嚼或分蹄之中不可吃的乃是：骆驼—因为倒嚼不分蹄，就与你们不洁净；","notes":[]},{"n":5,"t":"沙番—因为倒嚼不分蹄，就与你们不洁净；","notes":[]},{"n":6,"t":"兔子—因为倒嚼不分蹄，就与你们不洁净；","notes":[]},{"n":7,"t":"猪—因为蹄分两瓣，却不倒嚼，就与你们不洁净。","notes":[]},{"n":8,"t":"这些兽的肉，你们不可吃；死的，你们不可摸，都与你们不洁净。","notes":[]},{"n":9,"t":"「水中可吃的乃是这些：凡在水里、海里、河里、有翅有鳞的，都可以吃。","notes":[]},{"n":10,"t":"凡在海里、河里，并一切水里游动的活物，无翅无鳞的，你们都当以为可憎。","notes":[]},{"n":11,"t":"这些无翅无鳞、以为可憎的，你们不可吃它的肉；死的也当以为可憎。","notes":[]},{"n":12,"t":"凡水里无翅无鳞的，你们都当以为可憎。","notes":[]},{"n":13,"t":"「雀鸟中你们当以为可憎、不可吃的乃是：雕、狗头雕、红头雕、","notes":[]},{"n":14,"t":"鹞鹰、小鹰与其类；","notes":[]},{"n":15,"t":"乌鸦与其类；","notes":[]},{"n":16,"t":"鸵鸟、夜鹰、鱼鹰、鹰与其类；","notes":[]},{"n":17,"t":"鸮鸟、鸬鹚、猫头鹰、","notes":[]},{"n":18,"t":"角鸱、鹈鹕、秃雕、","notes":[]},{"n":19,"t":"鹳、鹭鸶与其类；戴鵀与蝙蝠。","notes":[]},{"n":20,"t":"「凡有翅膀用四足爬行的物，你们都当以为可憎。","notes":[]},{"n":21,"t":"只是有翅膀用四足爬行的物中，有足有腿，在地上蹦跳的，你们还可以吃。","notes":[]},{"n":22,"t":"其中有蝗虫、蚂蚱、蟋蟀与其类；蚱蜢与其类；这些你们都可以吃。","notes":[]},{"n":23,"t":"但是有翅膀有四足的爬物，你们都当以为可憎。","notes":[]},{"n":24,"t":"「这些都能使你们不洁净。凡摸了死的，必不洁净到晚上。","notes":[]},{"n":25,"t":"凡拿了死的，必不洁净到晚上，并要洗衣服。","notes":[]},{"n":26,"t":"凡走兽分蹄不成两瓣、也不倒嚼的，是与你们不洁净；凡摸了的就不洁净。","notes":[]},{"n":27,"t":"凡四足的走兽，用掌行走的，是与你们不洁净；摸其尸的，必不洁净到晚上。","notes":[]},{"n":28,"t":"拿其尸的，必不洁净到晚上，并要洗衣服。这些是与你们不洁净的。","notes":[]},{"n":29,"t":"「地上爬物与你们不洁净的乃是这些：鼬鼠、鼫鼠、蜥蜴与其类；","notes":[]},{"n":30,"t":"壁虎、龙子、守宫、蛇医、蝘蜓。","notes":[]},{"n":31,"t":"这些爬物都是与你们不洁净的。在它死了以后，凡摸了的，必不洁净到晚上。","notes":[]},{"n":32,"t":"其中死了的，掉在什么东西上，这东西就不洁净，无论是木器、衣服、皮子、口袋，不拘是做什么工用的器皿，须要放在水中，必不洁净到晚上，到晚上才洁净了。","notes":[]},{"n":33,"t":"若有死了掉在瓦器里的，其中不拘有什么，就不洁净，你们要把这瓦器打破了。","notes":[]},{"n":34,"t":"其中一切可吃的食物，沾水的就不洁净，并且那样器皿中一切可喝的，也必不洁净。","notes":[]},{"n":35,"t":"其中已死的，若有一点掉在什么物件上，那物件就不洁净，不拘是炉子，是锅台，就要打碎，都不洁净，也必与你们不洁净。","notes":[]},{"n":36,"t":"但是泉源或是聚水的池子仍是洁净；惟挨了那死的，就不洁净。","notes":[]},{"n":37,"t":"若是死的，有一点掉在要种的子粒上，子粒仍是洁净；","notes":[]},{"n":38,"t":"若水已经浇在子粒上，那死的有一点掉在上头，这子粒就与你们不洁净。","notes":[]},{"n":39,"t":"「你们可吃的走兽若是死了，有人摸它，必不洁净到晚上；","notes":[]},{"n":40,"t":"有人吃那死了的走兽，必不洁净到晚上，并要洗衣服；拿了死走兽的，必不洁净到晚上，并要洗衣服。","notes":[]},{"n":41,"t":"「凡地上的爬物是可憎的，都不可吃。","notes":[]},{"n":42,"t":"凡用肚子行走的和用四足行走的，或是有许多足的，就是一切爬在地上的，你们都不可吃，因为是可憎的。","notes":[]},{"n":43,"t":"你们不可因什么爬物使自己成为可憎的，也不可因这些使自己不洁净，以致染了污秽。","notes":[]},{"n":44,"t":"我是耶和华—你们的神；所以你们要成为圣洁，因为我是圣洁的。你们也不可在地上的爬物污秽自己。","notes":[]},{"n":45,"t":"我是把你们从埃及地领出来的耶和华，要作你们的神；所以你们要圣洁，因为我是圣洁的。」","notes":[]},{"n":46,"t":"这是走兽、飞鸟，和水中游动的活物，并地上爬物的条例。","notes":[]},{"n":47,"t":"要把洁净的和不洁净的，可吃的与不可吃的活物，都分别出来。","notes":[]}]},"12":{"heading":"产妇洁净礼的条例","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你晓谕以色列人说：若有妇人怀孕生男孩，她就不洁净七天，像在月经污秽的日子不洁净一样。","notes":[]},{"n":3,"t":"第八天，要给婴孩行割礼。","notes":[]},{"n":4,"t":"妇人在产血不洁之中，要家居三十三天。她洁净的日子未满，不可摸圣物，也不可进入圣所。","notes":[]},{"n":5,"t":"她若生女孩，就不洁净两个七天，像污秽的时候一样，要在产血不洁之中，家居六十六天。","notes":[]},{"n":6,"t":"「满了洁净的日子，无论是为男孩是为女孩，她要把一岁的羊羔为燔祭，一只雏鸽或是一只斑鸠为赎罪祭，带到会幕门口交给祭司。","notes":[]},{"n":7,"t":"祭司要献在耶和华面前，为她赎罪，她的血源就洁净了。这条例是为生育的妇人，无论是生男生女。","notes":[]},{"n":8,"t":"她的力量若不够献一只羊羔，她就要取两只斑鸠或是两只雏鸽，一只为燔祭，一只为赎罪祭。祭司要为她赎罪，她就洁净了。」","notes":[]}]},"13":{"heading":"有关皮肤病的条例","verses":[{"n":1,"t":"耶和华晓谕摩西、亚伦说：","notes":[]},{"n":2,"t":"「人的肉皮上若长了疖子，或长了癣，或长了火斑，在他肉皮上成了大麻风的灾病，就要将他带到祭司亚伦或亚伦作祭司的一个子孙面前。","notes":[]},{"n":3,"t":"祭司要察看肉皮上的灾病，若灾病处的毛已经变白，灾病的现象深于肉上的皮，这便是大麻风的灾病。祭司要察看他，定他为不洁净。","notes":[]},{"n":4,"t":"若火斑在他肉皮上是白的，现象不深于皮，其上的毛也没有变白，祭司就要将有灾病的人关锁七天。","notes":[]},{"n":5,"t":"第七天，祭司要察看他，若看灾病止住了，没有在皮上发散，祭司还要将他关锁七天。","notes":[]},{"n":6,"t":"第七天，祭司要再察看他，若灾病发暗，而且没有在皮上发散，祭司要定他为洁净，原来是癣；那人就要洗衣服，得为洁净。","notes":[]},{"n":7,"t":"但他为得洁净，将身体给祭司察看以后，癣若在皮上发散开了，他要再将身体给祭司察看。","notes":[]},{"n":8,"t":"祭司要察看，癣若在皮上发散，就要定他为不洁净，是大麻风。","notes":[]},{"n":9,"t":"「人有了大麻风的灾病，就要将他带到祭司面前。","notes":[]},{"n":10,"t":"祭司要察看，皮上若长了白疖，使毛变白，在长白疖之处有了红瘀肉，","notes":[]},{"n":11,"t":"这是肉皮上的旧大麻风，祭司要定他为不洁净，不用将他关锁，因为他是不洁净了。","notes":[]},{"n":12,"t":"大麻风若在皮上四外发散，长满了患灾病人的皮，据祭司察看，从头到脚无处不有，","notes":[]},{"n":13,"t":"祭司就要察看，全身的肉若长满了大麻风，就要定那患灾病的为洁净；全身都变为白，他乃洁净了。","notes":[]},{"n":14,"t":"但红肉几时显在他的身上就几时不洁净。","notes":[]},{"n":15,"t":"祭司一看那红肉就定他为不洁净。红肉本是不洁净，是大麻风。","notes":[]},{"n":16,"t":"红肉若复原，又变白了，他就要来见祭司。","notes":[]},{"n":17,"t":"祭司要察看，灾病处若变白了，祭司就要定那患灾病的为洁净，他乃洁净了。","notes":[]},{"n":18,"t":"「人若在皮肉上长疮，却治好了，","notes":[]},{"n":19,"t":"在长疮之处又起了白疖，或是白中带红的火斑，就要给祭司察看。","notes":[]},{"n":20,"t":"祭司要察看，若现象洼于皮，其上的毛也变白了，就要定他为不洁净，是大麻风的灾病发在疮中。","notes":[]},{"n":21,"t":"祭司若察看，其上没有白毛，也没有洼于皮，乃是发暗，就要将他关锁七天。","notes":[]},{"n":22,"t":"若在皮上发散开了，祭司就要定他为不洁净，是灾病。","notes":[]},{"n":23,"t":"火斑若在原处止住，没有发散，便是疮的痕迹，祭司就要定他为洁净。","notes":[]},{"n":24,"t":"「人的皮肉上若起了火毒，火毒的瘀肉成了火斑，或是白中带红的，或是全白的，","notes":[]},{"n":25,"t":"祭司就要察看，火斑中的毛若变白了，现象又深于皮，是大麻风在火毒中发出，就要定他为不洁净，是大麻风的灾病。","notes":[]},{"n":26,"t":"但是祭司察看，在火斑中若没有白毛，也没有洼于皮，乃是发暗，就要将他关锁七天。","notes":[]},{"n":27,"t":"到第七天，祭司要察看他，火斑若在皮上发散开了，就要定他为不洁净，是大麻风的灾病。","notes":[]},{"n":28,"t":"火斑若在原处止住，没有在皮上发散，乃是发暗，是起的火毒，祭司要定他为洁净，不过是火毒的痕迹。","notes":[]},{"n":29,"t":"「无论男女，若在头上有灾病，或是男人胡须上有灾病，","notes":[]},{"n":30,"t":"祭司就要察看；这灾病现象若深于皮，其间有细黄毛，就要定他为不洁净，这是头疥，是头上或是胡须上的大麻风。","notes":[]},{"n":31,"t":"祭司若察看头疥的灾病，现象不深于皮，其间也没有黑毛，就要将长头疥灾病的关锁七天。","notes":[]},{"n":32,"t":"第七天，祭司要察看灾病，若头疥没有发散，其间也没有黄毛，头疥的现象不深于皮，","notes":[]},{"n":33,"t":"那人就要剃去须发，但他不可剃头疥之处。祭司要将那长头疥的，再关锁七天。","notes":[]},{"n":34,"t":"第七天，祭司要察看头疥，头疥若没有在皮上发散，现象也不深于皮，就要定他为洁净，他要洗衣服，便成为洁净。","notes":[]},{"n":35,"t":"但他得洁净以后，头疥若在皮上发散开了，","notes":[]},{"n":36,"t":"祭司就要察看他。头疥若在皮上发散，就不必找那黄毛，他是不洁净了。","notes":[]},{"n":37,"t":"祭司若看头疥已经止住，其间也长了黑毛，头疥已然痊愈，那人是洁净了，就要定他为洁净。","notes":[]},{"n":38,"t":"「无论男女，皮肉上若起了火斑，就是白火斑，","notes":[]},{"n":39,"t":"祭司就要察看，他们肉皮上的火斑若白中带黑，这是皮上发出的白癣，那人是洁净了。","notes":[]},{"n":40,"t":"「人头上的发若掉了，他不过是头秃，还是洁净。","notes":[]},{"n":41,"t":"他顶前若掉了头发，他不过是顶门秃，还是洁净。","notes":[]},{"n":42,"t":"头秃处或是顶门秃处若有白中带红的灾病，这就是大麻风发在他头秃处或是顶门秃处，","notes":[]},{"n":43,"t":"祭司就要察看，他起的那灾病若在头秃处或是顶门秃处有白中带红的，像肉皮上大麻风的现象，","notes":[]},{"n":44,"t":"那人就是长大麻风，不洁净的，祭司总要定他为不洁净，他的灾病是在头上。","notes":[]},{"n":45,"t":"「身上有长大麻风灾病的，他的衣服要撕裂，也要蓬头散发，蒙着上唇，喊叫说：『不洁净了！不洁净了！』","notes":[]},{"n":46,"t":"灾病在他身上的日子，他便是不洁净；他既是不洁净，就要独居营外。」","notes":[]},{"n":47,"t":"「染了大麻风灾病的衣服，无论是羊毛衣服、是麻布衣服，","notes":[],"heads":["衣物发霉的条例"]},{"n":48,"t":"无论是在经上、在纬上，是麻布的、是羊毛的，是在皮子上，或在皮子做的什么物件上，","notes":[]},{"n":49,"t":"或在衣服上、皮子上，经上、纬上，或在皮子做的什么物件上，这灾病若是发绿，或是发红，是大麻风的灾病，要给祭司察看。","notes":[]},{"n":50,"t":"祭司就要察看那灾病，把染了灾病的物件关锁七天。","notes":[]},{"n":51,"t":"第七天，他要察看那灾病，灾病或在衣服上，经上、纬上，皮子上，若发散，这皮子无论当作何用，这灾病是蚕食的大麻风，都是不洁净了。","notes":[]},{"n":52,"t":"那染了灾病的衣服，或是经上、纬上，羊毛上，麻衣上，或是皮子做的什么物件上，他都要焚烧；因为这是蚕食的大麻风，必在火中焚烧。","notes":[]},{"n":53,"t":"「祭司要察看，若灾病在衣服上，经上、纬上，或是皮子做的什么物件上，没有发散，","notes":[]},{"n":54,"t":"祭司就要吩咐他们，把染了灾病的物件洗了，再关锁七天。","notes":[]},{"n":55,"t":"洗过以后，祭司要察看，那物件若没有变色，灾病也没有消散，那物件就不洁净，是透重的灾病，无论正面反面，都要在火中焚烧。","notes":[]},{"n":56,"t":"洗过以后，祭司要察看，若见那灾病发暗，他就要把那灾病从衣服上，皮子上，经上、纬上，都撕去。","notes":[]},{"n":57,"t":"若仍现在衣服上，或是经上、纬上、皮子做的什么物件上，这就是灾病又发了，必用火焚烧那染灾病的物件。","notes":[]},{"n":58,"t":"所洗的衣服，或是经，或是纬，或是皮子做的什么物件，若灾病离开了，要再洗，就洁净了。」","notes":[]},{"n":59,"t":"这就是大麻风灾病的条例，无论是在羊毛衣服上，麻布衣服上，经上、纬上，和皮子做的什么物件上，可以定为洁净或是不洁净。","notes":[]}]},"14":{"heading":"皮肤病后洁净的条例","verses":[{"n":1,"t":"耶和华晓谕摩西说：「","notes":[]},{"n":2,"t":"长大麻风得洁净的日子，其例乃是这样：要带他去见祭司；","notes":[]},{"n":3,"t":"祭司要出到营外察看，若见他的大麻风痊愈了，","notes":[]},{"n":4,"t":"就要吩咐人为那求洁净的拿两只洁净的活鸟和香柏木、朱红色线，并牛膝草来。","notes":[]},{"n":5,"t":"祭司要吩咐用瓦器盛活水，把一只鸟宰在上面。","notes":[]},{"n":6,"t":"至于那只活鸟，祭司要把它和香柏木、朱红色线并牛膝草一同蘸于宰在活水上的鸟血中，","notes":[]},{"n":7,"t":"用以在那长大麻风求洁净的人身上洒七次，就定他为洁净，又把活鸟放在田野里。","notes":[]},{"n":8,"t":"求洁净的人当洗衣服，剃去毛发，用水洗澡，就洁净了；然后可以进营，只是要在自己的帐棚外居住七天。","notes":[]},{"n":9,"t":"第七天，再把头上所有的头发与胡须、眉毛，并全身的毛，都剃了；又要洗衣服，用水洗身，就洁净了。","notes":[]},{"n":10,"t":"「第八天，他要取两只没有残疾的公羊羔和一只没有残疾、一岁的母羊羔，又要把调油的细面伊法十分之三为素祭，并油一罗革，一同取来。","notes":[]},{"n":11,"t":"行洁净之礼的祭司要将那求洁净的人和这些东西安置在会幕门口、耶和华面前。","notes":[]},{"n":12,"t":"祭司要取一只公羊羔献为赎愆祭，和那一罗革油一同作摇祭，在耶和华面前摇一摇；","notes":[]},{"n":13,"t":"把公羊羔宰于圣地，就是宰赎罪祭牲和燔祭牲之地。赎愆祭要归祭司，与赎罪祭一样，是至圣的。","notes":[]},{"n":14,"t":"祭司要取些赎愆祭牲的血，抹在求洁净人的右耳垂上和右手的大拇指上，并右脚的大拇指上。","notes":[]},{"n":15,"t":"祭司要从那一罗革油中取些倒在自己的左手掌里，","notes":[]},{"n":16,"t":"把右手的一个指头蘸在左手的油里，在耶和华面前用指头弹七次。","notes":[]},{"n":17,"t":"将手里所剩的油抹在那求洁净人的右耳垂上和右手的大拇指上，并右脚的大拇指上，就是抹在赎愆祭牲的血上。","notes":[]},{"n":18,"t":"祭司手里所剩的油要抹在那求洁净人的头上，在耶和华面前为他赎罪。","notes":[]},{"n":19,"t":"祭司要献赎罪祭，为那本不洁净、求洁净的人赎罪；然后要宰燔祭牲，","notes":[]},{"n":20,"t":"把燔祭和素祭献在坛上，为他赎罪，他就洁净了。","notes":[]},{"n":21,"t":"「他若贫穷不能预备够数，就要取一只公羊羔作赎愆祭，可以摇一摇，为他赎罪；也要把调油的细面伊法十分之一为素祭，和油一罗革一同取来；","notes":[]},{"n":22,"t":"又照他的力量取两只斑鸠或是两只雏鸽，一只作赎罪祭，一只作燔祭。","notes":[]},{"n":23,"t":"第八天，要为洁净，把这些带到会幕门口、耶和华面前，交给祭司。","notes":[]},{"n":24,"t":"祭司要把赎愆祭的羊羔和那一罗革油一同作摇祭，在耶和华面前摇一摇。","notes":[]},{"n":25,"t":"要宰了赎愆祭的羊羔，取些赎愆祭牲的血，抹在那求洁净人的右耳垂上和右手的大拇指上，并右脚的大拇指上。","notes":[]},{"n":26,"t":"祭司要把些油倒在自己的左手掌里，","notes":[]},{"n":27,"t":"把左手里的油，在耶和华面前，用右手的一个指头弹七次，","notes":[]},{"n":28,"t":"又把手里的油抹些在那求洁净人的右耳垂上和右手的大拇指上，并右脚的大拇指上，就是抹赎愆祭之血的原处。","notes":[]},{"n":29,"t":"祭司手里所剩的油要抹在那求洁净人的头上，在耶和华面前为他赎罪。","notes":[]},{"n":30,"t":"那人又要照他的力量献上一只斑鸠或是一只雏鸽，","notes":[]},{"n":31,"t":"就是他所能办的，一只为赎罪祭，一只为燔祭，与素祭一同献上；祭司要在耶和华面前为他赎罪。","notes":[]},{"n":32,"t":"这是那有大麻风灾病的人、不能将关乎得洁净之物预备够数的条例。」","notes":[]},{"n":33,"t":"耶和华晓谕摩西、亚伦说：","notes":[],"heads":["处理房屋发霉的条例"]},{"n":34,"t":"「你们到了我赐给你们为业的迦南地，我若使你们所得为业之地的房屋中有大麻风的灾病，","notes":[]},{"n":35,"t":"房主就要去告诉祭司说：『据我看，房屋中似乎有灾病。』","notes":[]},{"n":36,"t":"祭司还没有进去察看灾病以前，就要吩咐人把房子腾空，免得房子里所有的都成了不洁净；然后祭司要进去察看房子。","notes":[]},{"n":37,"t":"他要察看那灾病，灾病若在房子的墙上有发绿或发红的凹斑纹，现象洼于墙，","notes":[]},{"n":38,"t":"祭司就要出到房门外，把房子封锁七天。","notes":[]},{"n":39,"t":"第七天，祭司要再去察看，灾病若在房子的墙上发散，","notes":[]},{"n":40,"t":"就要吩咐人把那有灾病的石头挖出来，扔在城外不洁净之处；","notes":[]},{"n":41,"t":"也要叫人刮房内的四围，所刮掉的灰泥要倒在城外不洁净之处；","notes":[]},{"n":42,"t":"又要用别的石头代替那挖出来的石头，要另用灰泥墁房子。","notes":[]},{"n":43,"t":"「他挖出石头，刮了房子，墁了以后，灾病若在房子里又发现，","notes":[]},{"n":44,"t":"祭司就要进去察看，灾病若在房子里发散，这就是房内蚕食的大麻风，是不洁净。","notes":[]},{"n":45,"t":"他就要拆毁房子，把石头、木头、灰泥都搬到城外不洁净之处。","notes":[]},{"n":46,"t":"在房子封锁的时候，进去的人必不洁净到晚上；","notes":[]},{"n":47,"t":"在房子里躺着的必洗衣服；在房子里吃饭的也必洗衣服。","notes":[]},{"n":48,"t":"「房子墁了以后，祭司若进去察看，见灾病在房内没有发散，就要定房子为洁净，因为灾病已经消除。","notes":[]},{"n":49,"t":"要为洁净房子取两只鸟和香柏木、朱红色线并牛膝草，","notes":[]},{"n":50,"t":"用瓦器盛活水，把一只鸟宰在上面，","notes":[]},{"n":51,"t":"把香柏木、牛膝草、朱红色线，并那活鸟，都蘸在被宰的鸟血中与活水中，用以洒房子七次。","notes":[]},{"n":52,"t":"要用鸟血、活水、活鸟、香柏木、牛膝草，并朱红色线，洁净那房子。","notes":[]},{"n":53,"t":"但要把活鸟放在城外田野里。这样洁净房子，房子就洁净了。」","notes":["原文是为房子赎罪"]},{"n":54,"t":"这是为各类大麻风的灾病和头疥，","notes":[]},{"n":55,"t":"并衣服与房子的大麻风，","notes":[]},{"n":56,"t":"以及疖子、癣、火斑所立的条例，","notes":[]},{"n":57,"t":"指明何时为洁净，何时为不洁净。这是大麻风的条例。","notes":[]}]},"15":{"heading":"漏症患者洁净的条例","verses":[{"n":1,"t":"耶和华对摩西、亚伦说：","notes":[]},{"n":2,"t":"「你们晓谕以色列人说：人若身患漏症，他因这漏症就不洁净了。","notes":[]},{"n":3,"t":"他患漏症，无论是下流的，是止住的，都是不洁净。","notes":[]},{"n":4,"t":"他所躺的床都为不洁净，所坐的物也为不洁净。","notes":[]},{"n":5,"t":"凡摸那床的，必不洁净到晚上，并要洗衣服，用水洗澡。","notes":[]},{"n":6,"t":"那坐患漏症人所坐之物的，必不洁净到晚上，并要洗衣服，用水洗澡。","notes":[]},{"n":7,"t":"那摸患漏症人身体的，必不洁净到晚上，并要洗衣服，用水洗澡。","notes":[]},{"n":8,"t":"若患漏症人吐在洁净的人身上，那人必不洁净到晚上，并要洗衣服，用水洗澡。","notes":[]},{"n":9,"t":"患漏症人所骑的鞍子也为不洁净。","notes":[]},{"n":10,"t":"凡摸了他身下之物的，必不洁净到晚上；拿了那物的，必不洁净到晚上，并要洗衣服，用水洗澡。","notes":[]},{"n":11,"t":"患漏症的人没有用水涮手，无论摸了谁，谁必不洁净到晚上，并要洗衣服，用水洗澡。","notes":[]},{"n":12,"t":"患漏症人所摸的瓦器就必打破；所摸的一切木器也必用水涮洗。","notes":[]},{"n":13,"t":"「患漏症的人痊愈了，就要为洁净自己计算七天，也必洗衣服，用活水洗身，就洁净了。","notes":[]},{"n":14,"t":"第八天，要取两只斑鸠或是两只雏鸽，来到会幕门口、耶和华面前，把鸟交给祭司。","notes":[]},{"n":15,"t":"祭司要献上一只为赎罪祭，一只为燔祭；因那人患的漏症，祭司要在耶和华面前为他赎罪。","notes":[]},{"n":16,"t":"「人若梦遗，他必不洁净到晚上，并要用水洗全身。","notes":[]},{"n":17,"t":"无论是衣服是皮子，被精所染，必不洁净到晚上，并要用水洗。","notes":[]},{"n":18,"t":"若男女交合，两个人必不洁净到晚上，并要用水洗澡。","notes":[]},{"n":19,"t":"「女人行经，必污秽七天；凡摸她的，必不洁净到晚上。","notes":[]},{"n":20,"t":"女人在污秽之中，凡她所躺的物件都为不洁净，所坐的物件也都不洁净。","notes":[]},{"n":21,"t":"凡摸她床的，必不洁净到晚上，并要洗衣服，用水洗澡。","notes":[]},{"n":22,"t":"凡摸她所坐什么物件的，必不洁净到晚上，并要洗衣服，用水洗澡。","notes":[]},{"n":23,"t":"在女人的床上，或在她坐的物上，若有别的物件，人一摸了，必不洁净到晚上。","notes":[]},{"n":24,"t":"男人若与那女人同房，染了她的污秽，就要七天不洁净；所躺的床也为不洁净。","notes":[]},{"n":25,"t":"「女人若在经期以外患多日的血漏，或是经期过长，有了漏症，她就因这漏症不洁净，与她在经期不洁净一样。","notes":[]},{"n":26,"t":"她在患漏症的日子所躺的床、所坐的物都要看为不洁净，与她月经的时候一样。","notes":[]},{"n":27,"t":"凡摸这些物件的，就为不洁净，必不洁净到晚上，并要洗衣服，用水洗澡。","notes":[]},{"n":28,"t":"女人的漏症若好了，就要计算七天，然后才为洁净。","notes":[]},{"n":29,"t":"第八天，要取两只斑鸠或是两只雏鸽，带到会幕门口给祭司。","notes":[]},{"n":30,"t":"祭司要献一只为赎罪祭，一只为燔祭；因那人血漏不洁，祭司要在耶和华面前为她赎罪。","notes":[]},{"n":31,"t":"「你们要这样使以色列人与他们的污秽隔绝，免得他们玷污我的帐幕，就因自己的污秽死亡。」","notes":[]},{"n":32,"t":"这是患漏症和梦遗而不洁净的，","notes":[]},{"n":33,"t":"并有月经病的和患漏症的，无论男女，并人与不洁净女人同房的条例。","notes":[]}]},"16":{"heading":"赎罪日","verses":[{"n":1,"t":"亚伦的两个儿子近到耶和华面前死了。死了之后，耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「要告诉你哥哥亚伦，不可随时进圣所的幔子内、到柜上的施恩座前，免得他死亡，因为我要从云中显现在施恩座上。","notes":[]},{"n":3,"t":"亚伦进圣所，要带一只公牛犊为赎罪祭，一只公绵羊为燔祭。","notes":[]},{"n":4,"t":"要穿上细麻布圣内袍，把细麻布裤子穿在身上，腰束细麻布带子，头戴细麻布冠冕；这都是圣服。他要用水洗身，然后穿戴。","notes":[]},{"n":5,"t":"要从以色列会众取两只公山羊为赎罪祭，一只公绵羊为燔祭。","notes":[]},{"n":6,"t":"「亚伦要把赎罪祭的公牛奉上，为自己和本家赎罪；","notes":[]},{"n":7,"t":"也要把两只公山羊安置在会幕门口、耶和华面前，","notes":[]},{"n":8,"t":"为那两只羊拈阄，一阄归与耶和华，一阄归与阿撒泻勒。","notes":[]},{"n":9,"t":"亚伦要把那拈阄归与耶和华的羊献为赎罪祭，","notes":[]},{"n":10,"t":"但那拈阄归与阿撒泻勒的羊要活着安置在耶和华面前，用以赎罪，打发人送到旷野去，归与阿撒泻勒。","notes":[]},{"n":11,"t":"「亚伦要把赎罪祭的公牛牵来宰了，为自己和本家赎罪；","notes":[]},{"n":12,"t":"拿香炉，从耶和华面前的坛上盛满火炭，又拿一捧捣细的香料，都带入幔子内，","notes":[]},{"n":13,"t":"在耶和华面前，把香放在火上，使香的烟云遮掩法柜上的施恩座，免得他死亡；","notes":[]},{"n":14,"t":"也要取些公牛的血，用指头弹在施恩座的东面，又在施恩座的前面弹血七次。","notes":[]},{"n":15,"t":"「随后他要宰那为百姓作赎罪祭的公山羊，把羊的血带入幔子内，弹在施恩座的上面和前面，好像弹公牛的血一样。","notes":[]},{"n":16,"t":"他因以色列人诸般的污秽、过犯，就是他们一切的罪愆，当这样在圣所行赎罪之礼，并因会幕在他们污秽之中，也要照样而行。","notes":[]},{"n":17,"t":"他进圣所赎罪的时候，会幕里不可有人，直等到他为自己和本家并以色列全会众赎了罪出来。","notes":[]},{"n":18,"t":"他出来，要到耶和华面前的坛那里，在坛上行赎罪之礼，又要取些公牛的血和公山羊的血，抹在坛上四角的周围；","notes":[]},{"n":19,"t":"也要用指头把血弹在坛上七次，洁净了坛，从坛上除掉以色列人诸般的污秽，使坛成圣。」","notes":[]},{"n":20,"t":"「亚伦为圣所和会幕并坛献完了赎罪祭，就要把那只活着的公山羊奉上。","notes":[],"heads":["代罪羊"]},{"n":21,"t":"两手按在羊头上，承认以色列人诸般的罪孽过犯，就是他们一切的罪愆，把这罪都归在羊的头上，借着所派之人的手，送到旷野去。","notes":[]},{"n":22,"t":"要把这羊放在旷野，这羊要担当他们一切的罪孽，带到无人之地。","notes":[]},{"n":23,"t":"「亚伦要进会幕，把他进圣所时所穿的细麻布衣服脱下，放在那里，","notes":[]},{"n":24,"t":"又要在圣处用水洗身，穿上衣服，出来，把自己的燔祭和百姓的燔祭献上，为自己和百姓赎罪。","notes":[]},{"n":25,"t":"赎罪祭牲的脂油要在坛上焚烧。","notes":[]},{"n":26,"t":"那放羊归与阿撒泻勒的人要洗衣服，用水洗身，然后进营。","notes":[]},{"n":27,"t":"作赎罪祭的公牛和公山羊的血既带入圣所赎罪，这牛羊就要搬到营外，将皮、肉、粪用火焚烧。","notes":[]},{"n":28,"t":"焚烧的人要洗衣服，用水洗身，然后进营。」","notes":[]},{"n":29,"t":"「每逢七月初十日，你们要刻苦己心，无论是本地人，是寄居在你们中间的外人，什么工都不可做；这要作你们永远的定例。","notes":[],"heads":["守赎罪日"]},{"n":30,"t":"因在这日要为你们赎罪，使你们洁净。你们要在耶和华面前得以洁净，脱尽一切的罪愆。","notes":[]},{"n":31,"t":"这日你们要守为圣安息日，要刻苦己心；这为永远的定例。","notes":[]},{"n":32,"t":"那受膏、接续他父亲承接圣职的祭司要穿上细麻布的圣衣，行赎罪之礼。","notes":[]},{"n":33,"t":"他要在至圣所和会幕与坛行赎罪之礼，并要为众祭司和会众的百姓赎罪。","notes":[]},{"n":34,"t":"这要作你们永远的定例—就是因以色列人一切的罪，要一年一次为他们赎罪。」于是，亚伦照耶和华所吩咐摩西的行了。","notes":[]}]},"17":{"heading":"血的神圣","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你晓谕亚伦和他儿子并以色列众人说，耶和华所吩咐的乃是这样：","notes":[]},{"n":3,"t":"凡以色列家中的人宰公牛，或是绵羊羔，或是山羊，不拘宰于营内营外，","notes":[]},{"n":4,"t":"若未曾牵到会幕门口、耶和华的帐幕前献给耶和华为供物，流血的罪必归到那人身上。他流了血，要从民中剪除。","notes":[]},{"n":5,"t":"这是为要使以色列人把他们在田野里所献的祭带到会幕门口、耶和华面前，交给祭司，献与耶和华为平安祭。","notes":[]},{"n":6,"t":"祭司要把血洒在会幕门口、耶和华的坛上，把脂油焚烧，献给耶和华为馨香的祭。","notes":[]},{"n":7,"t":"他们不可再献祭给他们行邪淫所随从的鬼魔；这要作他们世世代代永远的定例。","notes":["原文是公山羊"]},{"n":8,"t":"「你要晓谕他们说：凡以色列家中的人，或是寄居在他们中间的外人，献燔祭或是平安祭，","notes":[]},{"n":9,"t":"若不带到会幕门口献给耶和华，那人必从民中剪除。","notes":[]},{"n":10,"t":"「凡以色列家中的人，或是寄居在他们中间的外人，若吃什么血，我必向那吃血的人变脸，把他从民中剪除。","notes":[]},{"n":11,"t":"因为活物的生命是在血中。我把这血赐给你们，可以在坛上为你们的生命赎罪；因血里有生命，所以能赎罪。","notes":[]},{"n":12,"t":"因此，我对以色列人说：你们都不可吃血；寄居在你们中间的外人也不可吃血。","notes":[]},{"n":13,"t":"凡以色列人，或是寄居在他们中间的外人，若打猎得了可吃的禽兽，必放出它的血来，用土掩盖。","notes":[]},{"n":14,"t":"「论到一切活物的生命，就在血中。所以我对以色列人说：无论什么活物的血，你们都不可吃，因为一切活物的血就是他的生命。凡吃了血的，必被剪除。","notes":[]},{"n":15,"t":"凡吃自死的，或是被野兽撕裂的，无论是本地人，是寄居的，必不洁净到晚上，都要洗衣服，用水洗身，到了晚上才为洁净。","notes":[]},{"n":16,"t":"但他若不洗衣服，也不洗身，就必担当他的罪孽。」","notes":[]}]},"18":{"heading":"有关淫乱的禁令","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你晓谕以色列人说：我是耶和华—你们的神。","notes":[]},{"n":3,"t":"你们从前住的埃及地，那里人的行为，你们不可效法，我要领你们到的迦南地，那里人的行为也不可效法，也不可照他们的恶俗行。","notes":[]},{"n":4,"t":"你们要遵我的典章，守我的律例，按此而行。我是耶和华—你们的神。","notes":[]},{"n":5,"t":"所以，你们要守我的律例典章；人若遵行，就必因此活着。我是耶和华。","notes":[]},{"n":6,"t":"「你们都不可露骨肉之亲的下体，亲近他们。我是耶和华。","notes":[]},{"n":7,"t":"不可露你母亲的下体，羞辱了你父亲。她是你的母亲，不可露她的下体。","notes":[]},{"n":8,"t":"不可露你继母的下体；这本是你父亲的下体。","notes":[]},{"n":9,"t":"你的姊妹，不拘是异母同父的，是异父同母的，无论是生在家生在外的，都不可露她们的下体。","notes":[]},{"n":10,"t":"不可露你孙女或是外孙女的下体，露了她们的下体就是露了自己的下体。","notes":[]},{"n":11,"t":"你继母从你父亲生的女儿本是你的妹妹，不可露她的下体。","notes":[]},{"n":12,"t":"不可露你姑母的下体；她是你父亲的骨肉之亲。","notes":[]},{"n":13,"t":"不可露你姨母的下体；她是你母亲的骨肉之亲。","notes":[]},{"n":14,"t":"不可亲近你伯叔之妻，羞辱了你伯叔；她是你的伯叔母。","notes":[]},{"n":15,"t":"不可露你儿妇的下体；她是你儿子的妻，不可露她的下体。","notes":[]},{"n":16,"t":"不可露你弟兄妻子的下体；这本是你弟兄的下体。","notes":[]},{"n":17,"t":"不可露了妇人的下体，又露她女儿的下体，也不可娶她孙女或是外孙女，露她们的下体；她们是骨肉之亲，这本是大恶。","notes":[]},{"n":18,"t":"你妻还在的时候，不可另娶她的姊妹作对头，露她的下体。","notes":[]},{"n":19,"t":"「女人行经不洁净的时候，不可露她的下体，与她亲近。","notes":[]},{"n":20,"t":"不可与邻舍的妻行淫，玷污自己。","notes":[]},{"n":21,"t":"不可使你的儿女经火归与摩洛，也不可亵渎你神的名。我是耶和华。","notes":[]},{"n":22,"t":"不可与男人苟合，像与女人一样；这本是可憎恶的。","notes":[]},{"n":23,"t":"不可与兽淫合，玷污自己。女人也不可站在兽前，与它淫合；这本是逆性的事。","notes":[]},{"n":24,"t":"「在这一切的事上，你们都不可玷污自己；因为我在你们面前所逐出的列邦，在这一切的事上玷污了自己；","notes":[]},{"n":25,"t":"连地也玷污了，所以我追讨那地的罪孽，那地也吐出它的居民。","notes":[]},{"n":26,"t":"故此，你们要守我的律例典章。这一切可憎恶的事，无论是本地人，是寄居在你们中间的外人，都不可行，（","notes":[]},{"n":27,"t":"在你们以先居住那地的人行了这一切可憎恶的事，地就玷污了，）","notes":[]},{"n":28,"t":"免得你们玷污那地的时候，地就把你们吐出，像吐出在你们以先的国民一样。","notes":[]},{"n":29,"t":"无论什么人，行了其中可憎的一件事，必从民中剪除。","notes":[]},{"n":30,"t":"所以，你们要守我所吩咐的，免得你们随从那些可憎的恶俗，就是在你们以先的人所常行的，以致玷污了自己。我是耶和华—你们的神。」","notes":[]}]},"19":{"heading":"圣洁和公正的法例","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你晓谕以色列全会众说：你们要圣洁，因为我耶和华—你们的神是圣洁的。","notes":[]},{"n":3,"t":"你们各人都当孝敬父母，也要守我的安息日。我是耶和华—你们的神。","notes":[]},{"n":4,"t":"你们不可偏向虚无的神，也不可为自己铸造神像。我是耶和华—你们的神。","notes":[]},{"n":5,"t":"你们献平安祭给耶和华的时候，要献得可蒙悦纳。","notes":[]},{"n":6,"t":"这祭物要在献的那一天和第二天吃，若有剩到第三天的，就必用火焚烧。","notes":[]},{"n":7,"t":"第三天若再吃，这就为可憎恶的，必不蒙悦纳。","notes":[]},{"n":8,"t":"凡吃的人必担当他的罪孽；因为他亵渎了耶和华的圣物，那人必从民中剪除。","notes":[]},{"n":9,"t":"「在你们的地收割庄稼，不可割尽田角，也不可拾取所遗落的。","notes":[]},{"n":10,"t":"不可摘尽葡萄园的果子，也不可拾取葡萄园所掉的果子；要留给穷人和寄居的。我是耶和华—你们的神。","notes":[]},{"n":11,"t":"「你们不可偷盗，不可欺骗，也不可彼此说谎。","notes":[]},{"n":12,"t":"不可指着我的名起假誓，亵渎你神的名。我是耶和华。","notes":[]},{"n":13,"t":"「不可欺压你的邻舍，也不可抢夺他的物。雇工人的工价，不可在你那里过夜，留到早晨。","notes":[]},{"n":14,"t":"不可咒骂聋子，也不可将绊脚石放在瞎子面前，只要敬畏你的神。我是耶和华。","notes":[]},{"n":15,"t":"「你们施行审判，不可行不义；不可偏护穷人，也不可重看有势力的人，只要按着公义审判你的邻舍。","notes":[]},{"n":16,"t":"不可在民中往来搬弄是非，也不可与邻舍为敌，置之于死。我是耶和华。","notes":["原文是流他的血"]},{"n":17,"t":"「不可心里恨你的弟兄；总要指摘你的邻舍，免得因他担罪。","notes":[]},{"n":18,"t":"不可报仇，也不可埋怨你本国的子民，却要爱人如己。我是耶和华。","notes":[]},{"n":19,"t":"「你们要守我的律例。不可叫你的牲畜与异类配合；不可用两样搀杂的种种你的地，也不可用两样搀杂的料做衣服穿在身上。","notes":[]},{"n":20,"t":"「婢女许配了丈夫，还没有被赎、得释放，人若与她行淫，二人要受刑罚，却不把他们治死，因为婢女还没有得自由。","notes":[]},{"n":21,"t":"那人要把赎愆祭，就是一只公绵羊牵到会幕门口、耶和华面前。","notes":[]},{"n":22,"t":"祭司要用赎愆祭的羊在耶和华面前赎他所犯的罪，他的罪就必蒙赦免。","notes":[]},{"n":23,"t":"「你们到了迦南地，栽种各样结果子的树木，就要以所结的果子如未受割礼的一样。三年之久，你们要以这些果子，如未受割礼的，是不可吃的。","notes":[]},{"n":24,"t":"但第四年所结的果子全要成为圣，用以赞美耶和华。","notes":[]},{"n":25,"t":"第五年，你们要吃那树上的果子，好叫树给你们结果子更多。我是耶和华—你们的神。","notes":[]},{"n":26,"t":"「你们不可吃带血的物；不可用法术，也不可观兆。","notes":[]},{"n":27,"t":"头的周围不可剃，胡须的周围也不可损坏。","notes":["或译：两鬓"]},{"n":28,"t":"不可为死人用刀划身，也不可在身上刺花纹。我是耶和华。","notes":[]},{"n":29,"t":"「不可辱没你的女儿，使她为娼妓，恐怕地上的人专向淫乱，地就满了大恶。","notes":[]},{"n":30,"t":"你们要守我的安息日，敬我的圣所。我是耶和华。","notes":[]},{"n":31,"t":"「不可偏向那些交鬼的和行巫术的；不可求问他们，以致被他们玷污了。我是耶和华—你们的神。","notes":[]},{"n":32,"t":"「在白发的人面前，你要站起来；也要尊敬老人，又要敬畏你的神。我是耶和华。","notes":[]},{"n":33,"t":"「若有外人在你们国中和你同居，就不可欺负他。","notes":[]},{"n":34,"t":"和你们同居的外人，你们要看他如本地人一样，并要爱他如己，因为你们在埃及地也作过寄居的。我是耶和华—你们的神。","notes":[]},{"n":35,"t":"「你们施行审判，不可行不义；在尺、秤、升、斗上也是如此。","notes":[]},{"n":36,"t":"要用公道天平、公道法码、公道升斗、公道秤。我是耶和华—你们的神，曾把你们从埃及地领出来的。","notes":[]},{"n":37,"t":"你们要谨守遵行我一切的律例典章。我是耶和华。」","notes":[]}]},"20":{"heading":"处罚悖逆的人","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你还要晓谕以色列人说：凡以色列人，或是在以色列中寄居的外人，把自己的儿女献给摩洛的，总要治死他；本地人要用石头把他打死。","notes":[]},{"n":3,"t":"我也要向那人变脸，把他从民中剪除；因为他把儿女献给摩洛，玷污我的圣所，亵渎我的圣名。","notes":[]},{"n":4,"t":"那人把儿女献给摩洛，本地人若佯为不见，不把他治死，","notes":[]},{"n":5,"t":"我就要向这人和他的家变脸，把他和一切随他与摩洛行邪淫的人都从民中剪除。","notes":[]},{"n":6,"t":"「人偏向交鬼的和行巫术的，随他们行邪淫，我要向那人变脸，把他从民中剪除。","notes":[]},{"n":7,"t":"所以你们要自洁成圣，因为我是耶和华—你们的神。","notes":[]},{"n":8,"t":"你们要谨守遵行我的律例；我是叫你们成圣的耶和华。","notes":[]},{"n":9,"t":"凡咒骂父母的，总要治死他；他咒骂了父母，他的罪要归到他身上。","notes":["原文是血；本章同"]},{"n":10,"t":"「与邻舍之妻行淫的，奸夫淫妇都必治死。","notes":[]},{"n":11,"t":"与继母行淫的，就是羞辱了他父亲，总要把他们二人治死，罪要归到他们身上。","notes":[]},{"n":12,"t":"与儿妇同房的，总要把他们二人治死；他们行了逆伦的事，罪要归到他们身上。","notes":[]},{"n":13,"t":"人若与男人苟合，像与女人一样，他们二人行了可憎的事，总要把他们治死，罪要归到他们身上。","notes":[]},{"n":14,"t":"人若娶妻，并娶其母，便是大恶，要把这三人用火焚烧，使你们中间免去大恶。","notes":[]},{"n":15,"t":"人若与兽淫合，总要治死他，也要杀那兽。","notes":[]},{"n":16,"t":"女人若与兽亲近，与它淫合，你要杀那女人和那兽，总要把他们治死，罪要归到他们身上。","notes":[]},{"n":17,"t":"「人若娶他的姊妹，无论是异母同父的，是异父同母的，彼此见了下体，这是可耻的事；他们必在本民的眼前被剪除。他露了姊妹的下体，必担当自己的罪孽。","notes":[]},{"n":18,"t":"妇人有月经，若与她同房，露了她的下体，就是露了妇人的血源，妇人也露了自己的血源，二人必从民中剪除。","notes":[]},{"n":19,"t":"不可露姨母或是姑母的下体，这是露了骨肉之亲的下体；二人必担当自己的罪孽。","notes":[]},{"n":20,"t":"人若与伯叔之妻同房，就羞辱了他的伯叔；二人要担当自己的罪，必无子女而死。","notes":[]},{"n":21,"t":"人若娶弟兄之妻，这本是污秽的事，羞辱了他的弟兄；二人必无子女。","notes":[]},{"n":22,"t":"「所以，你们要谨守遵行我一切的律例典章，免得我领你们去住的那地把你们吐出。","notes":[]},{"n":23,"t":"我在你们面前所逐出的国民，你们不可随从他们的风俗；因为他们行了这一切的事，所以我厌恶他们。","notes":[]},{"n":24,"t":"但我对你们说过，你们要承受他们的地，就是我要赐给你们为业、流奶与蜜之地。我是耶和华—你们的神，使你们与万民有分别的。","notes":[]},{"n":25,"t":"所以，你们要把洁净和不洁净的禽兽分别出来；不可因我给你们分为不洁净的禽兽，或是滋生在地上的活物，使自己成为可憎恶的。","notes":[]},{"n":26,"t":"你们要归我为圣，因为我—耶和华是圣的，并叫你们与万民有分别，使你们作我的民。","notes":[]},{"n":27,"t":"「无论男女，是交鬼的或行巫术的，总要治死他们。人必用石头把他们打死，罪要归到他们身上。」","notes":[]}]},"21":{"heading":"祭司圣洁的条例","verses":[{"n":1,"t":"耶和华对摩西说：「你告诉亚伦子孙作祭司的说：祭司不可为民中的死人沾染自己，","notes":[]},{"n":2,"t":"除非为他骨肉之亲的父母、儿女、弟兄，","notes":[]},{"n":3,"t":"和未曾出嫁、作处女的姊妹，才可以沾染自己。","notes":[]},{"n":4,"t":"祭司既在民中为首，就不可从俗沾染自己。","notes":[]},{"n":5,"t":"不可使头光秃；不可剃除胡须的周围，也不可用刀划身。","notes":[]},{"n":6,"t":"要归神为圣，不可亵渎神的名；因为耶和华的火祭，就是神的食物，是他们献的，所以他们要成为圣。","notes":[]},{"n":7,"t":"不可娶妓女或被污的女人为妻，也不可娶被休的妇人为妻，因为祭司是归神为圣。","notes":[]},{"n":8,"t":"所以你要使他成圣，因为他奉献你神的食物；你要以他为圣，因为我—使你们成圣的耶和华—是圣的。","notes":[]},{"n":9,"t":"祭司的女儿若行淫辱没自己，就辱没了父亲，必用火将她焚烧。","notes":[]},{"n":10,"t":"「在弟兄中作大祭司、头上倒了膏油、又承接圣职、穿了圣衣的，不可蓬头散发，也不可撕裂衣服。","notes":[]},{"n":11,"t":"不可挨近死尸，也不可为父母沾染自己。","notes":[]},{"n":12,"t":"不可出圣所，也不可亵渎神的圣所，因为神膏油的冠冕在他头上。我是耶和华。","notes":[]},{"n":13,"t":"他要娶处女为妻。","notes":[]},{"n":14,"t":"寡妇或是被休的妇人，或是被污为妓的女人，都不可娶；只可娶本民中的处女为妻。","notes":[]},{"n":15,"t":"不可在民中辱没他的儿女，因为我是叫他成圣的耶和华。」","notes":[]},{"n":16,"t":"耶和华对摩西说：","notes":[]},{"n":17,"t":"「你告诉亚伦说：你世世代代的后裔，凡有残疾的，都不可近前来献他神的食物。","notes":[]},{"n":18,"t":"因为凡有残疾的，无论是瞎眼的、瘸腿的、塌鼻子的、肢体有余的、","notes":[]},{"n":19,"t":"折脚折手的、","notes":[]},{"n":20,"t":"驼背的、矮矬的、眼睛有毛病的、长癣的、长疥的，或是损坏肾子的，都不可近前来。","notes":[]},{"n":21,"t":"祭司亚伦的后裔，凡有残疾的，都不可近前来，将火祭献给耶和华。他有残疾，不可近前来献神的食物。","notes":[]},{"n":22,"t":"神的食物，无论是圣的，至圣的，他都可以吃。","notes":[]},{"n":23,"t":"但不可进到幔子前，也不可就近坛前；因为他有残疾，免得亵渎我的圣所。我是叫他成圣的耶和华。」","notes":[]},{"n":24,"t":"于是，摩西晓谕亚伦和亚伦的子孙，并以色列众人。","notes":[]}]},"22":{"heading":"圣物的圣洁","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你吩咐亚伦和他子孙说：要远离以色列人所分别为圣、归给我的圣物，免得亵渎我的圣名。我是耶和华。","notes":[]},{"n":3,"t":"你要对他们说：你们世世代代的后裔，凡身上有污秽、亲近以色列人所分别为圣、归耶和华圣物的，那人必在我面前剪除。我是耶和华。","notes":[]},{"n":4,"t":"亚伦的后裔，凡长大麻风的，或是有漏症的，不可吃圣物，直等他洁净了。无论谁摸那因死尸不洁净的物，或是遗精的人，","notes":["或译：人"]},{"n":5,"t":"或是摸什么使他不洁净的爬物，或是摸那使他不洁净的人（不拘那人有什么不洁净），","notes":[]},{"n":6,"t":"摸了这些人、物的，必不洁净到晚上；若不用水洗身，就不可吃圣物。","notes":[]},{"n":7,"t":"日落的时候，他就洁净了，然后可以吃圣物，因为这是他的食物。","notes":[]},{"n":8,"t":"自死的或是被野兽撕裂的，他不可吃，因此污秽自己。我是耶和华。","notes":[]},{"n":9,"t":"所以他们要守我所吩咐的，免得轻忽了，因此担罪而死。我是叫他们成圣的耶和华。","notes":[]},{"n":10,"t":"「凡外人不可吃圣物；寄居在祭司家的，或是雇工人，都不可吃圣物；","notes":[]},{"n":11,"t":"倘若祭司买人，是他的钱买的，那人就可以吃圣物；生在他家的人也可以吃。","notes":[]},{"n":12,"t":"祭司的女儿若嫁外人，就不可吃举祭的圣物。","notes":[]},{"n":13,"t":"但祭司的女儿若是寡妇，或是被休的，没有孩子，又归回父家，与她青年一样，就可以吃她父亲的食物；只是外人不可吃。","notes":[]},{"n":14,"t":"若有人误吃了圣物，要照圣物的原数加上五分之一交给祭司。","notes":[]},{"n":15,"t":"祭司不可亵渎以色列人所献给耶和华的圣物，","notes":[]},{"n":16,"t":"免得他们在吃圣物上自取罪孽，因为我是叫他们成圣的耶和华。」","notes":[]},{"n":17,"t":"耶和华对摩西说：","notes":[]},{"n":18,"t":"「你晓谕亚伦和他子孙，并以色列众人说：以色列家中的人，或在以色列中寄居的，凡献供物，无论是所许的愿，是甘心献的，就是献给耶和华作燔祭的，","notes":[]},{"n":19,"t":"要将没有残疾的公牛，或是绵羊，或是山羊献上，如此方蒙悦纳。","notes":[]},{"n":20,"t":"凡有残疾的，你们不可献上，因为这不蒙悦纳。","notes":[]},{"n":21,"t":"凡从牛群或是羊群中，将平安祭献给耶和华，为要还特许的愿，或是作甘心献的，所献的必纯全无残疾的才蒙悦纳。","notes":[]},{"n":22,"t":"瞎眼的、折伤的、残废的、有瘤子的、长癣的、长疥的都不可献给耶和华，也不可在坛上作为火祭献给耶和华。","notes":[]},{"n":23,"t":"无论是公牛是绵羊羔，若肢体有余的，或是缺少的，只可作甘心祭献上；用以还愿，却不蒙悦纳。","notes":[]},{"n":24,"t":"肾子损伤的，或是压碎的，或是破裂的，或是骟了的，不可献给耶和华，在你们的地上也不可这样行。","notes":[]},{"n":25,"t":"这类的物，你们从外人的手，一样也不可接受作你们神的食物献上；因为这些都有损坏，有残疾，不蒙悦纳。」","notes":[]},{"n":26,"t":"耶和华晓谕摩西说：","notes":[]},{"n":27,"t":"「才生的公牛，或是绵羊或是山羊，七天当跟着母；从第八天以后，可以当供物蒙悦纳，作为耶和华的火祭。","notes":[]},{"n":28,"t":"无论是母牛是母羊，不可同日宰母和子。","notes":[]},{"n":29,"t":"你们献感谢祭给耶和华，要献得可蒙悦纳。","notes":[]},{"n":30,"t":"要当天吃，一点不可留到早晨。我是耶和华。","notes":[]},{"n":31,"t":"「你们要谨守遵行我的诫命。我是耶和华。","notes":[]},{"n":32,"t":"你们不可亵渎我的圣名；我在以色列人中，却要被尊为圣。我是叫你们成圣的耶和华，","notes":[]},{"n":33,"t":"把你们从埃及地领出来，作你们的神。我是耶和华。」","notes":[]}]},"23":{"heading":"节期","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你晓谕以色列人说：耶和华的节期，你们要宣告为圣会的节期。","notes":[]},{"n":3,"t":"六日要做工，第七日是圣安息日，当有圣会；你们什么工都不可做。这是在你们一切的住处向耶和华守的安息日。","notes":[]},{"n":4,"t":"耶和华的节期，就是你们到了日期要宣告为圣会的，乃是这些。」","notes":[]},{"n":5,"t":"「正月十四日，黄昏的时候，是耶和华的逾越节。","notes":[],"heads":["逾越节和无酵节"]},{"n":6,"t":"这月十五日是向耶和华守的无酵节；你们要吃无酵饼七日。","notes":[]},{"n":7,"t":"第一日当有圣会，什么劳碌的工都不可做；","notes":[]},{"n":8,"t":"要将火祭献给耶和华七日。第七日是圣会，什么劳碌的工都不可做。」","notes":[]},{"n":9,"t":"耶和华对摩西说：","notes":[]},{"n":10,"t":"「你晓谕以色列人说：你们到了我赐给你们的地，收割庄稼的时候，要将初熟的庄稼一捆带给祭司。","notes":[]},{"n":11,"t":"他要把这一捆在耶和华面前摇一摇，使你们得蒙悦纳。祭司要在安息日的次日把这捆摇一摇。","notes":[]},{"n":12,"t":"摇这捆的日子，你们要把一岁、没有残疾的公绵羊羔献给耶和华为燔祭。","notes":[]},{"n":13,"t":"同献的素祭，就是调油的细面伊法十分之二，作为馨香的火祭，献给耶和华。同献的奠祭，要酒一欣四分之一。","notes":[]},{"n":14,"t":"无论是饼，是烘的子粒，是新穗子，你们都不可吃，直等到把你们献给神的供物带来的那一天才可以吃。这在你们一切的住处作为世世代代永远的定例。」","notes":[]},{"n":15,"t":"「你们要从安息日的次日，献禾捆为摇祭的那日算起，要满了七个安息日。","notes":[],"heads":["五旬收获节"]},{"n":16,"t":"到第七个安息日的次日，共计五十天，又要将新素祭献给耶和华。","notes":[]},{"n":17,"t":"要从你们的住处取出细面伊法十分之二，加酵，烤成两个摇祭的饼，当作初熟之物献给耶和华。","notes":[]},{"n":18,"t":"又要将一岁、没有残疾的羊羔七只、公牛犊一只、公绵羊两只，和饼一同奉上。这些与同献的素祭和奠祭要作为燔祭献给耶和华，就是作馨香的火祭献给耶和华。","notes":[]},{"n":19,"t":"你们要献一只公山羊为赎罪祭，两只一岁的公绵羊羔为平安祭。","notes":[]},{"n":20,"t":"祭司要把这些和初熟麦子做的饼一同作摇祭，在耶和华面前摇一摇；这是献与耶和华为圣物归给祭司的。","notes":[]},{"n":21,"t":"当这日，你们要宣告圣会；什么劳碌的工都不可做。这在你们一切的住处作为世世代代永远的定例。","notes":[]},{"n":22,"t":"「在你们的地收割庄稼，不可割尽田角，也不可拾取所遗落的；要留给穷人和寄居的。我是耶和华—你们的神。」","notes":[]},{"n":23,"t":"耶和华对摩西说：","notes":[],"heads":["新年"]},{"n":24,"t":"「你晓谕以色列人说：七月初一，你们要守为圣安息日，要吹角作纪念，当有圣会。","notes":[]},{"n":25,"t":"什么劳碌的工都不可做；要将火祭献给耶和华。」","notes":[]},{"n":26,"t":"耶和华晓谕摩西说：","notes":[],"heads":["赎罪日"]},{"n":27,"t":"「七月初十是赎罪日；你们要守为圣会，并要刻苦己心，也要将火祭献给耶和华。","notes":[]},{"n":28,"t":"当这日，什么工都不可做；因为是赎罪日，要在耶和华—你们的神面前赎罪。","notes":[]},{"n":29,"t":"当这日，凡不刻苦己心的，必从民中剪除。","notes":[]},{"n":30,"t":"凡这日做什么工的，我必将他从民中除灭。","notes":[]},{"n":31,"t":"你们什么工都不可做。这在你们一切的住处作为世世代代永远的定例。","notes":[]},{"n":32,"t":"你们要守这日为圣安息日，并要刻苦己心。从这月初九日晚上到次日晚上，要守为安息日。」","notes":[]},{"n":33,"t":"耶和华对摩西说：","notes":[],"heads":["住棚节"]},{"n":34,"t":"「你晓谕以色列人说：这七月十五日是住棚节，要在耶和华面前守这节七日。","notes":[]},{"n":35,"t":"第一日当有圣会，什么劳碌的工都不可做。","notes":[]},{"n":36,"t":"七日内要将火祭献给耶和华。第八日当守圣会，要将火祭献给耶和华。这是严肃会，什么劳碌的工都不可做。","notes":[]},{"n":37,"t":"「这是耶和华的节期，就是你们要宣告为圣会的节期；要将火祭、燔祭、素祭、祭物，并奠祭，各归各日，献给耶和华。","notes":[]},{"n":38,"t":"这是在耶和华的安息日以外，又在你们的供物和所许的愿，并甘心献给耶和华的以外。","notes":[]},{"n":39,"t":"「你们收藏了地的出产，就从七月十五日起，要守耶和华的节七日。第一日为圣安息；第八日也为圣安息。","notes":[]},{"n":40,"t":"第一日要拿美好树上的果子和棕树上的枝子，与茂密树的枝条并河旁的柳枝，在耶和华—你们的神面前欢乐七日。","notes":[]},{"n":41,"t":"每年七月间，要向耶和华守这节七日。这为你们世世代代永远的定例。","notes":[]},{"n":42,"t":"你们要住在棚里七日；凡以色列家的人都要住在棚里，","notes":[]},{"n":43,"t":"好叫你们世世代代知道，我领以色列人出埃及地的时候曾使他们住在棚里。我是耶和华—你们的神。」","notes":[]},{"n":44,"t":"于是，摩西将耶和华的节期传给以色列人。","notes":[]}]},"24":{"heading":"燃灯的条例","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「要吩咐以色列人，把那为点灯捣成的清橄榄油拿来给你，使灯常常点着。","notes":[]},{"n":3,"t":"在会幕中法柜的幔子外，亚伦从晚上到早晨必在耶和华面前经理这灯。这要作你们世世代代永远的定例。","notes":[]},{"n":4,"t":"他要在耶和华面前常收拾精金灯台上的灯。」","notes":[]},{"n":5,"t":"「你要取细面，烤成十二个饼，每饼用面伊法十分之二。","notes":[],"heads":["陈设饼"]},{"n":6,"t":"要把饼摆列两行，每行六个，在耶和华面前精金的桌子上；","notes":["或译：摞；下同"]},{"n":7,"t":"又要把净乳香放在每行饼上，作为纪念，就是作为火祭献给耶和华。","notes":[]},{"n":8,"t":"每安息日要常摆在耶和华面前；这为以色列人作永远的约。","notes":[]},{"n":9,"t":"这饼是要给亚伦和他子孙的；他们要在圣处吃，为永远的定例，因为在献给耶和华的火祭中是至圣的。」","notes":[]},{"n":10,"t":"有一个以色列妇人的儿子，他父亲是埃及人，一日闲游在以色列人中。这以色列妇人的儿子和一个以色列人在营里争斗。","notes":[],"heads":["公正的判例"]},{"n":11,"t":"这以色列妇人的儿子亵渎了圣名，并且咒诅，就有人把他送到摩西那里。（他母亲名叫示罗密，是但支派底伯利的女儿。）","notes":[]},{"n":12,"t":"他们把那人收在监里，要得耶和华所指示的话。","notes":[]},{"n":13,"t":"耶和华晓谕摩西说：","notes":[]},{"n":14,"t":"「把那咒诅圣名的人带到营外。叫听见的人都放手在他头上；全会众就要用石头打死他。","notes":[]},{"n":15,"t":"你要晓谕以色列人说：凡咒诅神的，必担当他的罪。","notes":[]},{"n":16,"t":"那亵渎耶和华名的，必被治死；全会众总要用石头打死他。不管是寄居的是本地人，他亵渎耶和华名的时候，必被治死。","notes":[]},{"n":17,"t":"打死人的，必被治死；","notes":[]},{"n":18,"t":"打死牲畜的，必赔上牲畜，以命偿命。","notes":[]},{"n":19,"t":"人若使他邻舍的身体有残疾，他怎样行，也要照样向他行：","notes":[]},{"n":20,"t":"以伤还伤，以眼还眼，以牙还牙。他怎样叫人的身体有残疾，也要照样向他行。","notes":[]},{"n":21,"t":"打死牲畜的，必赔上牲畜；打死人的，必被治死。","notes":[]},{"n":22,"t":"不管是寄居的是本地人，同归一例。我是耶和华—你们的神。」","notes":[]},{"n":23,"t":"于是，摩西晓谕以色列人，他们就把那咒诅圣名的人带到营外，用石头打死。以色列人就照耶和华所吩咐摩西的行了。","notes":[]}]},"25":{"heading":"安息年","verses":[{"n":1,"t":"耶和华在西奈山对摩西说：","notes":[]},{"n":2,"t":"「你晓谕以色列人说：你们到了我所赐你们那地的时候，地就要向耶和华守安息。","notes":[]},{"n":3,"t":"六年要耕种田地，也要修理葡萄园，收藏地的出产。","notes":[]},{"n":4,"t":"第七年，地要守圣安息，就是向耶和华守的安息，不可耕种田地，也不可修理葡萄园。","notes":[]},{"n":5,"t":"遗落自长的庄稼不可收割；没有修理的葡萄树也不可摘取葡萄。这年，地要守圣安息。","notes":[]},{"n":6,"t":"地在安息年所出的，要给你和你的仆人、婢女、雇工人，并寄居的外人当食物。","notes":[]},{"n":7,"t":"这年的土产也要给你的牲畜和你地上的走兽当食物。」","notes":[]},{"n":8,"t":"「你要计算七个安息年，就是七七年。这便为你成了七个安息年，共是四十九年。","notes":[],"heads":["禧年"]},{"n":9,"t":"当年七月初十日，你要大发角声；这日就是赎罪日，要在遍地发出角声。","notes":[]},{"n":10,"t":"第五十年，你们要当作圣年，在遍地给一切的居民宣告自由。这年必为你们的禧年，各人要归自己的产业，各归本家。","notes":[]},{"n":11,"t":"第五十年要作为你们的禧年。这年不可耕种；地中自长的，不可收割；没有修理的葡萄树也不可摘取葡萄。","notes":[]},{"n":12,"t":"因为这是禧年，你们要当作圣年，吃地中自出的土产。","notes":[]},{"n":13,"t":"「这禧年，你们各人要归自己的地业。","notes":[]},{"n":14,"t":"你若卖什么给邻舍，或是从邻舍的手中买什么，彼此不可亏负。","notes":[]},{"n":15,"t":"你要按禧年以后的年数向邻舍买；他也要按年数的收成卖给你。","notes":[]},{"n":16,"t":"年岁若多，要照数加添价值；年岁若少，要照数减去价值，因为他照收成的数目卖给你。","notes":[]},{"n":17,"t":"你们彼此不可亏负，只要敬畏你们的神，因为我是耶和华—你们的神。」","notes":[]},{"n":18,"t":"「我的律例，你们要遵行，我的典章，你们要谨守，就可以在那地上安然居住。","notes":[],"heads":["安息年的问题"]},{"n":19,"t":"地必出土产，你们就要吃饱，在那地上安然居住。","notes":[]},{"n":20,"t":"你们若说：『这第七年我们不耕种，也不收藏土产，吃什么呢？』","notes":[]},{"n":21,"t":"我必在第六年将我所命的福赐给你们，地便生三年的土产。","notes":[]},{"n":22,"t":"第八年，你们要耕种，也要吃陈粮，等到第九年出产收来的时候，你们还吃陈粮。」","notes":[]},{"n":23,"t":"「地不可永卖，因为地是我的；你们在我面前是客旅，是寄居的。","notes":[],"heads":["赎房地产的条例"]},{"n":24,"t":"在你们所得为业的全地，也要准人将地赎回。","notes":[]},{"n":25,"t":"你的弟兄若渐渐穷乏，卖了几分地业，他至近的亲属就要来把弟兄所卖的赎回。","notes":["弟兄是指本国人说；下同"]},{"n":26,"t":"若没有能给他赎回的，他自己渐渐富足，能够赎回，","notes":[]},{"n":27,"t":"就要算出卖地的年数，把余剩年数的价值还那买主，自己便归回自己的地业。","notes":[]},{"n":28,"t":"倘若不能为自己得回所卖的，仍要存在买主的手里直到禧年；到了禧年，地业要出买主的手，自己便归回自己的地业。","notes":[]},{"n":29,"t":"「人若卖城内的住宅，卖了以后，一年之内可以赎回；在一整年，必有赎回的权柄。","notes":[]},{"n":30,"t":"若在一整年之内不赎回，这城内的房屋就定准永归买主，世世代代为业；在禧年也不得出买主的手。","notes":[]},{"n":31,"t":"但房屋在无城墙的村庄里，要看如乡下的田地一样，可以赎回；到了禧年，都要出买主的手。","notes":[]},{"n":32,"t":"然而利未人所得为业的城邑，其中的房屋，利未人可以随时赎回。","notes":[]},{"n":33,"t":"若是一个利未人不将所卖的房屋赎回，是在所得为业的城内，到了禧年就要出买主的手，因为利未人城邑的房屋是他们在以色列人中的产业。","notes":[]},{"n":34,"t":"只是他们各城郊野之地不可卖，因为是他们永远的产业。」","notes":[]},{"n":35,"t":"「你的弟兄在你那里若渐渐贫穷，手中缺乏，你就要帮补他，使他与你同住，像外人和寄居的一样。","notes":[],"heads":["借贷给穷人的条例"]},{"n":36,"t":"不可向他取利，也不可向他多要；只要敬畏你的神，使你的弟兄与你同住。","notes":[]},{"n":37,"t":"你借钱给他，不可向他取利；借粮给他，也不可向他多要。","notes":[]},{"n":38,"t":"我是耶和华—你们的神，曾领你们从埃及地出来，为要把迦南地赐给你们，要作你们的神。」","notes":[]},{"n":39,"t":"「你的弟兄若在你那里渐渐穷乏，将自己卖给你，不可叫他像奴仆服事你。","notes":[],"heads":["赎回奴仆的条例"]},{"n":40,"t":"他要在你那里像雇工人和寄居的一样，要服事你直到禧年。","notes":[]},{"n":41,"t":"到了禧年，他和他儿女要离开你，一同出去归回本家，到他祖宗的地业那里去。","notes":[]},{"n":42,"t":"因为他们是我的仆人，是我从埃及地领出来的，不可卖为奴仆。","notes":[]},{"n":43,"t":"不可严严地辖管他，只要敬畏你的神。","notes":[]},{"n":44,"t":"至于你的奴仆、婢女，可以从你四围的国中买。","notes":[]},{"n":45,"t":"并且那寄居在你们中间的外人和他们的家属，在你们地上所生的，你们也可以从其中买人；他们要作你们的产业。","notes":[]},{"n":46,"t":"你们要将他们遗留给你们的子孙为产业，要永远从他们中间拣出奴仆；只是你们的弟兄以色列人，你们不可严严地辖管。","notes":[]},{"n":47,"t":"「住在你那里的外人，或是寄居的，若渐渐富足，你的弟兄却渐渐穷乏，将自己卖给那外人，或是寄居的，或是外人的宗族，","notes":[]},{"n":48,"t":"卖了以后，可以将他赎回。无论是他的弟兄，","notes":[]},{"n":49,"t":"或伯叔、伯叔的儿子，本家的近支，都可以赎他。他自己若渐渐富足，也可以自赎。","notes":[]},{"n":50,"t":"他要和买主计算，从卖自己的那年起，算到禧年；所卖的价值照着年数多少，好像工人每年的工价。","notes":[]},{"n":51,"t":"若缺少的年数多，就要按着年数从买价中偿还他的赎价。","notes":[]},{"n":52,"t":"若到禧年只缺少几年，就要按着年数和买主计算，偿还他的赎价。","notes":[]},{"n":53,"t":"他和买主同住，要像每年雇的工人，买主不可严严地辖管他。","notes":[]},{"n":54,"t":"他若不这样被赎，到了禧年，要和他的儿女一同出去。","notes":[]},{"n":55,"t":"因为以色列人都是我的仆人，是我从埃及地领出来的。我是耶和华—你们的神。」","notes":[]}]},"26":{"heading":"遵行诫命者的福祉","verses":[{"n":1,"t":"「你们不可做什么虚无的神像，不可立雕刻的偶像或是柱像，也不可在你们的地上安什么錾成的石像，向它跪拜，因为我是耶和华—你们的神。","notes":[]},{"n":2,"t":"你们要守我的安息日，敬我的圣所。我是耶和华。","notes":[]},{"n":3,"t":"「你们若遵行我的律例，谨守我的诫命，","notes":[]},{"n":4,"t":"我就给你们降下时雨，叫地生出土产，田野的树木结果子。","notes":[]},{"n":5,"t":"你们打粮食要打到摘葡萄的时候，摘葡萄要摘到撒种的时候；并且要吃得饱足，在你们的地上安然居住。","notes":[]},{"n":6,"t":"我要赐平安在你们的地上；你们躺卧，无人惊吓。我要叫恶兽从你们的地上息灭；刀剑也必不经过你们的地。","notes":[]},{"n":7,"t":"你们要追赶仇敌，他们必倒在你们刀下。","notes":[]},{"n":8,"t":"你们五个人要追赶一百人，一百人要追赶一万人；仇敌必倒在你们刀下。","notes":[]},{"n":9,"t":"我要眷顾你们，使你们生养众多，也要与你们坚定所立的约。","notes":[]},{"n":10,"t":"你们要吃陈粮，又因新粮挪开陈粮。","notes":[]},{"n":11,"t":"我要在你们中间立我的帐幕；我的心也不厌恶你们。","notes":[]},{"n":12,"t":"我要在你们中间行走；我要作你们的神，你们要作我的子民。","notes":[]},{"n":13,"t":"我是耶和华—你们的神，曾将你们从埃及地领出来，使你们不作埃及人的奴仆；我也折断你们所负的轭，叫你们挺身而走。」","notes":[]},{"n":14,"t":"「你们若不听从我，不遵行我的诫命，","notes":[],"heads":["违反诫命者受惩罚"]},{"n":15,"t":"厌弃我的律例，厌恶我的典章，不遵行我一切的诫命，背弃我的约，","notes":[]},{"n":16,"t":"我待你们就要这样：我必命定惊惶，叫眼目干瘪、精神消耗的痨病热病辖制你们。你们也要白白地撒种，因为仇敌要吃你们所种的。","notes":[]},{"n":17,"t":"我要向你们变脸，你们就要败在仇敌面前。恨恶你们的，必辖管你们；无人追赶，你们却要逃跑。","notes":[]},{"n":18,"t":"你们因这些事若还不听从我，我就要为你们的罪加七倍惩罚你们。","notes":[]},{"n":19,"t":"我必断绝你们因势力而有的骄傲，又要使覆你们的天如铁，载你们的地如铜。","notes":[]},{"n":20,"t":"你们要白白地劳力；因为你们的地不出土产，其上的树木也不结果子。","notes":[]},{"n":21,"t":"「你们行事若与我反对，不肯听从我，我就要按你们的罪加七倍降灾与你们。","notes":[]},{"n":22,"t":"我也要打发野地的走兽到你们中间，抢吃你们的儿女，吞灭你们的牲畜，使你们的人数减少，道路荒凉。","notes":[]},{"n":23,"t":"「你们因这些事若仍不改正归我，行事与我反对，","notes":[]},{"n":24,"t":"我就要行事与你们反对，因你们的罪击打你们七次。","notes":[]},{"n":25,"t":"我又要使刀剑临到你们，报复你们背约的仇；聚集你们在各城内，降瘟疫在你们中间，也必将你们交在仇敌的手中。","notes":[]},{"n":26,"t":"我要折断你们的杖，就是断绝你们的粮。那时，必有十个女人在一个炉子给你们烤饼，按分量秤给你们；你们要吃，也吃不饱。","notes":[]},{"n":27,"t":"「你们因这一切的事若不听从我，却行事与我反对，","notes":[]},{"n":28,"t":"我就要发烈怒，行事与你们反对，又因你们的罪惩罚你们七次。","notes":[]},{"n":29,"t":"并且你们要吃儿子的肉，也要吃女儿的肉。","notes":[]},{"n":30,"t":"我又要毁坏你们的邱坛，砍下你们的日像，把你们的尸首扔在你们偶像的身上；我的心也必厌恶你们。","notes":[]},{"n":31,"t":"我要使你们的城邑变为荒凉，使你们的众圣所成为荒场；我也不闻你们馨香的香气。","notes":[]},{"n":32,"t":"我要使地成为荒场，住在其上的仇敌就因此诧异。","notes":[]},{"n":33,"t":"我要把你们散在列邦中；我也要拔刀追赶你们。你们的地要成为荒场；你们的城邑要变为荒凉。","notes":[]},{"n":34,"t":"「你们在仇敌之地居住的时候，你们的地荒凉，要享受众安息；正在那时候，地要歇息，享受安息。","notes":[]},{"n":35,"t":"地多时为荒场，就要多时歇息；地这样歇息，是你们住在其上的安息年所不能得的。","notes":[]},{"n":36,"t":"至于你们剩下的人，我要使他们在仇敌之地心惊胆怯。叶子被风吹的响声，要追赶他们；他们要逃避，像人逃避刀剑，无人追赶，却要跌倒。","notes":[]},{"n":37,"t":"无人追赶，他们要彼此撞跌，像在刀剑之前。你们在仇敌面前也必站立不住。","notes":[]},{"n":38,"t":"你们要在列邦中灭亡；仇敌之地要吞吃你们。","notes":[]},{"n":39,"t":"你们剩下的人必因自己的罪孽和祖宗的罪孽在仇敌之地消灭。","notes":[]},{"n":40,"t":"「他们要承认自己的罪和他们祖宗的罪，就是干犯我的那罪，并且承认自己行事与我反对，","notes":[]},{"n":41,"t":"我所以行事与他们反对，把他们带到仇敌之地。那时，他们未受割礼的心若谦卑了，他们也服了罪孽的刑罚，","notes":[]},{"n":42,"t":"我就要记念我与雅各所立的约，与以撒所立的约，与亚伯拉罕所立的约，并要记念这地。","notes":[]},{"n":43,"t":"他们离开这地，地在荒废无人的时候就要享受安息。并且他们要服罪孽的刑罚；因为他们厌弃了我的典章，心中厌恶了我的律例。","notes":[]},{"n":44,"t":"虽是这样，他们在仇敌之地，我却不厌弃他们，也不厌恶他们，将他们尽行灭绝，也不背弃我与他们所立的约，因为我是耶和华—他们的神。","notes":[]},{"n":45,"t":"我却要为他们的缘故记念我与他们先祖所立的约。他们的先祖是我在列邦人眼前、从埃及地领出来的，为要作他们的神。我是耶和华。」","notes":[]},{"n":46,"t":"这些律例、典章，和法度是耶和华与以色列人在西奈山借着摩西立的。","notes":[]}]},"27":{"heading":"许愿的条例","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你晓谕以色列人说：人还特许的愿，被许的人要按你所估的价值归给耶和华。","notes":[]},{"n":3,"t":"你估定的，从二十岁到六十岁的男人，要按圣所的平，估定价银五十舍客勒。","notes":[]},{"n":4,"t":"若是女人，你要估定三十舍客勒。","notes":[]},{"n":5,"t":"若是从五岁到二十岁，男子你要估定二十舍客勒，女子估定十舍客勒。","notes":[]},{"n":6,"t":"若是从一月到五岁，男子你要估定五舍客勒，女子估定三舍客勒。","notes":[]},{"n":7,"t":"若是从六十岁以上，男人你要估定十五舍客勒，女人估定十舍客勒。","notes":[]},{"n":8,"t":"他若贫穷，不能照你所估定的价，就要把他带到祭司面前，祭司要按许愿人的力量估定他的价。","notes":[]},{"n":9,"t":"「所许的若是牲畜，就是人献给耶和华为供物的，凡这一类献给耶和华的，都要成为圣。","notes":[]},{"n":10,"t":"人不可改换，也不可更换，或是好的换坏的，或是坏的换好的。若以牲畜更换牲畜，所许的与所换的都要成为圣。","notes":[]},{"n":11,"t":"若牲畜不洁净，是不可献给耶和华为供物的，就要把牲畜安置在祭司面前。","notes":[]},{"n":12,"t":"祭司就要估定价值；牲畜是好是坏，祭司怎样估定，就要以怎样为是。","notes":[]},{"n":13,"t":"他若一定要赎回，就要在你所估定的价值以外加上五分之一。","notes":[]},{"n":14,"t":"「人将房屋分别为圣，归给耶和华，祭司就要估定价值。房屋是好是坏，祭司怎样估定，就要以怎样为定。","notes":[]},{"n":15,"t":"将房屋分别为圣的人，若要赎回房屋，就必在你所估定的价值以外加上五分之一，房屋仍旧归他。","notes":[]},{"n":16,"t":"「人若将承受为业的几分地分别为圣，归给耶和华，你要按这地撒种多少估定价值，若撒大麦一贺梅珥，要估价五十舍客勒。","notes":[]},{"n":17,"t":"他若从禧年将地分别为圣，就要以你所估定的价为定。","notes":[]},{"n":18,"t":"倘若他在禧年以后将地分别为圣，祭司就要按着未到禧年所剩的年数推算价值，也要从你所估的减去价值。","notes":[]},{"n":19,"t":"将地分别为圣的人若定要把地赎回，他便要在你所估的价值以外加上五分之一，地就准定归他。","notes":[]},{"n":20,"t":"他若不赎回那地，或是将地卖给别人，就再不能赎了。","notes":[]},{"n":21,"t":"但到了禧年，那地从买主手下出来的时候，就要归耶和华为圣，和永献的地一样，要归祭司为业。","notes":[]},{"n":22,"t":"他若将所买的一块地，不是承受为业的，分别为圣归给耶和华，","notes":[]},{"n":23,"t":"祭司就要将你所估的价值给他推算到禧年。当日，他要以你所估的价银为圣，归给耶和华。","notes":[]},{"n":24,"t":"到了禧年，那地要归卖主，就是那承受为业的原主。","notes":[]},{"n":25,"t":"凡你所估定的价银都要按着圣所的平：二十季拉为一舍客勒。","notes":[]},{"n":26,"t":"「惟独牲畜中头生的，无论是牛是羊，既归耶和华，谁也不可再分别为圣，因为这是耶和华的。","notes":[]},{"n":27,"t":"若是不洁净的牲畜生的，就要按你所估定的价值加上五分之一赎回；若不赎回，就要按你所估定的价值卖了。","notes":[]},{"n":28,"t":"「但一切永献的，就是人从他所有永献给耶和华的，无论是人，是牲畜，是他承受为业的地，都不可卖，也不可赎。凡永献的是归给耶和华为至圣。","notes":[]},{"n":29,"t":"凡从人中当灭的都不可赎，必被治死。」","notes":[]},{"n":30,"t":"「地上所有的，无论是地上的种子是树上的果子，十分之一是耶和华的，是归给耶和华为圣的。","notes":[]},{"n":31,"t":"人若要赎这十分之一的什么物，就要加上五分之一。","notes":[]},{"n":32,"t":"凡牛群羊群中，一切从杖下经过的，每第十只要归给耶和华为圣。","notes":[]},{"n":33,"t":"不可问是好是坏，也不可更换；若定要更换，所更换的与本来的牲畜都要成为圣，不可赎回。」","notes":[]},{"n":34,"t":"这就是耶和华在西奈山为以色列人所吩咐摩西的命令。","notes":[]}]}},"NUM":{"1":{"heading":"以色列的第一次人口普查","verses":[{"n":1,"t":"以色列人出埃及地后，第二年二月初一日，耶和华在西奈的旷野、会幕中晓谕摩西说：","notes":[]},{"n":2,"t":"「你要按以色列全会众的家室、宗族、人名的数目计算所有的男丁。","notes":[]},{"n":3,"t":"凡以色列中，从二十岁以外，能出去打仗的，你和亚伦要照他们的军队数点。","notes":[]},{"n":4,"t":"每支派中必有一人作本支派的族长，帮助你们。","notes":[]},{"n":5,"t":"他们的名字：属吕便的，有示丢珥的儿子以利蓿；","notes":[]},{"n":6,"t":"属西缅的，有苏利沙代的儿子示路蔑；","notes":[]},{"n":7,"t":"属犹大的，有亚米拿达的儿子拿顺；","notes":[]},{"n":8,"t":"属以萨迦的，有苏押的儿子拿坦业；","notes":[]},{"n":9,"t":"属西布伦的，有希伦的儿子以利押；","notes":[]},{"n":10,"t":"约瑟子孙、属以法莲的，有亚米忽的儿子以利沙玛；属玛拿西的，有比大蓿的儿子迦玛列；","notes":[]},{"n":11,"t":"属便雅悯的，有基多尼的儿子亚比但；","notes":[]},{"n":12,"t":"属但的，有亚米沙代的儿子亚希以谢；","notes":[]},{"n":13,"t":"属亚设的，有俄兰的儿子帕结；","notes":[]},{"n":14,"t":"属迦得的，有丢珥的儿子以利雅萨；","notes":[]},{"n":15,"t":"属拿弗他利的，有以南的儿子亚希拉。","notes":[]},{"n":16,"t":"这都是从会中选召的，各作本支派的首领，都是以色列军中的统领。」","notes":[]},{"n":17,"t":"于是，摩西、亚伦带着这些按名指定的人，","notes":[]},{"n":18,"t":"当二月初一日招聚全会众。会众就照他们的家室、宗族、人名的数目，从二十岁以外的，都述说自己的家谱。","notes":[]},{"n":19,"t":"耶和华怎样吩咐摩西，他就怎样在西奈的旷野数点他们。","notes":[]},{"n":20,"t":"以色列的长子，吕便子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的男丁，共有四万六千五百名。","notes":[],"end":21},{"n":22,"t":"西缅子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的男丁，共有五万九千三百名。","notes":[],"end":23},{"n":24,"t":"迦得子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有四万五千六百五十名。","notes":[],"end":25},{"n":26,"t":"犹大子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有七万四千六百名。","notes":[],"end":27},{"n":28,"t":"以萨迦子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有五万四千四百名。","notes":[],"end":29},{"n":30,"t":"西布伦子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有五万七千四百名。","notes":[],"end":31},{"n":32,"t":"约瑟子孙属以法莲子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有四万零五百名。","notes":[],"end":33},{"n":34,"t":"玛拿西子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有三万二千二百名。","notes":[],"end":35},{"n":36,"t":"便雅悯子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有三万五千四百名。","notes":[],"end":37},{"n":38,"t":"但子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有六万二千七百名。","notes":[],"end":39},{"n":40,"t":"亚设子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有四万一千五百名。","notes":[],"end":41},{"n":42,"t":"拿弗他利子孙的后代，照着家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有五万三千四百名。","notes":[],"end":43},{"n":44,"t":"这些就是被数点的，是摩西、亚伦，和以色列中十二个首领所数点的；这十二个人各作各宗族的代表。","notes":[]},{"n":45,"t":"这样，凡以色列人中被数的，照着宗族，从二十岁以外，能出去打仗、被数的，共有六十万零三千五百五十名。","notes":[],"end":46},{"n":47,"t":"利未人却没有按着支派数在其中，","notes":[]},{"n":48,"t":"因为耶和华晓谕摩西说：","notes":[]},{"n":49,"t":"「惟独利未支派你不可数点，也不可在以色列人中计算他们的总数。","notes":[]},{"n":50,"t":"只要派利未人管法柜的帐幕和其中的器具，并属乎帐幕的；他们要抬帐幕和其中的器具，并要办理帐幕的事，在帐幕的四围安营。","notes":["或译：搬运"]},{"n":51,"t":"帐幕将往前行的时候，利未人要拆卸；将支搭的时候，利未人要竖起。近前来的外人必被治死。","notes":[]},{"n":52,"t":"以色列人支搭帐棚，要照他们的军队，各归本营，各归本纛。","notes":[]},{"n":53,"t":"但利未人要在法柜帐幕的四围安营，免得忿怒临到以色列会众；利未人并要谨守法柜的帐幕。」","notes":[]},{"n":54,"t":"以色列人就这样行。凡耶和华所吩咐摩西的，他们就照样行了。","notes":[]}]},"2":{"heading":"各支派在营地的位置","verses":[{"n":1,"t":"耶和华晓谕摩西、亚伦说：","notes":[]},{"n":2,"t":"「以色列人要各归自己的纛下，在本族的旗号那里，对着会幕的四围安营。","notes":[]},{"n":3,"t":"在东边，向日出之地，照着军队安营的是犹大营的纛。有亚米拿达的儿子拿顺作犹大人的首领。","notes":[]},{"n":4,"t":"他军队被数的，共有七万四千六百名。","notes":[]},{"n":5,"t":"挨着他安营的是以萨迦支派。有苏押的儿子拿坦业作以萨迦人的首领。","notes":[]},{"n":6,"t":"他军队被数的，共有五万四千四百名。","notes":[]},{"n":7,"t":"又有西布伦支派。希伦的儿子以利押作西布伦人的首领。","notes":[]},{"n":8,"t":"他军队被数的，共有五万七千四百名。","notes":[]},{"n":9,"t":"凡属犹大营、按着军队被数的，共有十八万六千四百名，要作第一队往前行。","notes":[]},{"n":10,"t":"「在南边，按着军队是吕便营的纛。有示丢珥的儿子以利蓿作吕便人的首领。","notes":[]},{"n":11,"t":"他军队被数的，共有四万六千五百名。","notes":[]},{"n":12,"t":"挨着他安营的是西缅支派。苏利沙代的儿子示路蔑作西缅人的首领。","notes":[]},{"n":13,"t":"他军队被数的，共有五万九千三百名。","notes":[]},{"n":14,"t":"又有迦得支派。丢珥的儿子以利雅萨作迦得人的首领。","notes":[]},{"n":15,"t":"他军队被数的，共有四万五千六百五十名，","notes":[]},{"n":16,"t":"凡属吕便营、按着军队被数的，共有十五万一千四百五十名，要作第二队往前行。","notes":[]},{"n":17,"t":"「随后，会幕要往前行，有利未营在诸营中间。他们怎样安营就怎样往前行，各按本位，各归本纛。","notes":[]},{"n":18,"t":"「在西边，按着军队是以法莲营的纛。亚米忽的儿子以利沙玛作以法莲人的首领。","notes":[]},{"n":19,"t":"他军队被数的，共有四万零五百名。","notes":[]},{"n":20,"t":"挨着他的是玛拿西支派。比大蓿的儿子迦玛列作玛拿西人的首领。","notes":[]},{"n":21,"t":"他军队被数的，共有三万二千二百名。","notes":[]},{"n":22,"t":"又有便雅悯支派。基多尼的儿子亚比但作便雅悯人的首领。","notes":[]},{"n":23,"t":"他军队被数的，共有三万五千四百名。","notes":[]},{"n":24,"t":"凡属以法莲营、按着军队被数的，共有十万零八千一百名，要作第三队往前行。","notes":[]},{"n":25,"t":"「在北边，按着军队是但营的纛。亚米沙代的儿子亚希以谢作但人的首领。","notes":[]},{"n":26,"t":"他军队被数的，共有六万二千七百名。","notes":[]},{"n":27,"t":"挨着他安营的是亚设支派。俄兰的儿子帕结作亚设人的首领。","notes":[]},{"n":28,"t":"他军队被数的，共有四万一千五百名。","notes":[]},{"n":29,"t":"又有拿弗他利支派。以南的儿子亚希拉作拿弗他利人的首领。","notes":[]},{"n":30,"t":"他军队被数的，共有五万三千四百名。","notes":[]},{"n":31,"t":"凡但营被数的，共有十五万七千六百名，要归本纛作末队往前行。」","notes":[]},{"n":32,"t":"这些以色列人，照他们的宗族，按他们的军队，在诸营中被数的，共有六十万零三千五百五十名。","notes":[]},{"n":33,"t":"惟独利未人没有数在以色列人中，是照耶和华所吩咐摩西的。","notes":[]},{"n":34,"t":"以色列人就这样行，各人照他们的家室、宗族归于本纛，安营起行，都是照耶和华所吩咐摩西的。","notes":[]}]},"3":{"heading":"亚伦的儿子们","verses":[{"n":1,"t":"耶和华在西奈山晓谕摩西的日子，亚伦和摩西的后代如下：","notes":[]},{"n":2,"t":"亚伦的儿子，长子名叫拿答，还有亚比户、以利亚撒、以他玛。","notes":[]},{"n":3,"t":"这是亚伦儿子的名字，都是受膏的祭司，是摩西叫他们承接圣职供祭司职分的。","notes":[]},{"n":4,"t":"拿答、亚比户在西奈的旷野向耶和华献凡火的时候就死在耶和华面前了。他们也没有儿子。以利亚撒、以他玛在他们的父亲亚伦面前供祭司的职分。","notes":[]},{"n":5,"t":"耶和华晓谕摩西说：","notes":[],"heads":["利未人被派作祭司"]},{"n":6,"t":"「你使利未支派近前来，站在祭司亚伦面前好服事他，","notes":[]},{"n":7,"t":"替他和会众在会幕前守所吩咐的，办理帐幕的事。","notes":[]},{"n":8,"t":"又要看守会幕的器具，并守所吩咐以色列人的，办理帐幕的事。","notes":[]},{"n":9,"t":"你要将利未人给亚伦和他的儿子，因为他们是从以色列人中选出来给他的。","notes":[]},{"n":10,"t":"你要嘱咐亚伦和他的儿子谨守自己祭司的职任。近前来的外人必被治死。」","notes":[]},{"n":11,"t":"耶和华晓谕摩西说：","notes":[]},{"n":12,"t":"「我从以色列人中拣选了利未人，代替以色列人一切头生的；利未人要归我。","notes":[]},{"n":13,"t":"因为凡头生的是我的；我在埃及地击杀一切头生的那日就把以色列中一切头生的，连人带牲畜都分别为圣归我；他们定要属我。我是耶和华。」","notes":[]},{"n":14,"t":"耶和华在西奈的旷野晓谕摩西说：","notes":[],"heads":["利未人男丁的统计"]},{"n":15,"t":"「你要照利未人的宗族、家室数点他们。凡一个月以外的男子都要数点。」","notes":[]},{"n":16,"t":"于是摩西照耶和华所吩咐的数点他们。","notes":[]},{"n":17,"t":"利未众子的名字是革顺、哥辖、米拉利。","notes":[]},{"n":18,"t":"革顺的儿子，按着家室，是立尼、示每。","notes":[]},{"n":19,"t":"哥辖的儿子，按着家室，是暗兰、以斯哈、希伯伦、乌薛。","notes":[]},{"n":20,"t":"米拉利的儿子，按着家室，是抹利、母示。这些按着宗族是利未人的家室。","notes":[]},{"n":21,"t":"属革顺的，有立尼族、示每族。这是革顺的二族。","notes":[]},{"n":22,"t":"其中被数、从一个月以外所有的男子共有七千五百名。","notes":[]},{"n":23,"t":"这革顺的二族要在帐幕后西边安营。","notes":[]},{"n":24,"t":"拉伊勒的儿子以利雅萨作革顺人宗族的首领。","notes":[]},{"n":25,"t":"革顺的子孙在会幕中所要看守的，就是帐幕和罩棚，并罩棚的盖与会幕的门帘，","notes":[]},{"n":26,"t":"院子的帷子和门帘（院子是围帐幕和坛的），并一切使用的绳子。","notes":[]},{"n":27,"t":"属哥辖的，有暗兰族、以斯哈族、希伯伦族、乌薛族。这是哥辖的诸族。","notes":[]},{"n":28,"t":"按所有男子的数目，从一个月以外看守圣所的，共有八千六百名。","notes":[]},{"n":29,"t":"哥辖儿子的诸族要在帐幕的南边安营。","notes":[]},{"n":30,"t":"乌薛的儿子以利撒反作哥辖宗族家室的首领。","notes":[]},{"n":31,"t":"他们所要看守的是约柜、桌子、灯台、两座坛与圣所内使用的器皿，并帘子和一切使用之物。","notes":[]},{"n":32,"t":"祭司亚伦的儿子以利亚撒作利未人众首领的领袖，要监察那些看守圣所的人。","notes":[]},{"n":33,"t":"属米拉利的，有抹利族、母示族。这是米拉利的二族。","notes":[]},{"n":34,"t":"他们被数的，按所有男子的数目，从一个月以外的，共有六千二百名。","notes":[]},{"n":35,"t":"亚比亥的儿子苏列作米拉利二宗族的首领。他们要在帐幕的北边安营。","notes":[]},{"n":36,"t":"米拉利子孙的职分是看守帐幕的板、闩、柱子、带卯的座，和帐幕一切所使用的器具，","notes":[]},{"n":37,"t":"院子四围的柱子、带卯的座、橛子，和绳子。","notes":[]},{"n":38,"t":"在帐幕前东边，向日出之地安营的是摩西、亚伦，和亚伦的儿子。他们看守圣所，替以色列人守耶和华所吩咐的。近前来的外人必被治死。","notes":[]},{"n":39,"t":"凡被数的利未人，就是摩西、亚伦照耶和华吩咐所数的，按着家室，从一个月以外的男子，共有二万二千名。","notes":[]},{"n":40,"t":"耶和华对摩西说：「你要从以色列人中数点一个月以外、凡头生的男子，把他们的名字记下。","notes":[],"heads":["利未人代替长子的地位"]},{"n":41,"t":"我是耶和华。你要拣选利未人归我，代替以色列人所有头生的，也取利未人的牲畜代替以色列所有头生的牲畜。」","notes":[]},{"n":42,"t":"摩西就照耶和华所吩咐的把以色列人头生的都数点了。","notes":[]},{"n":43,"t":"按人名的数目，从一个月以外、凡头生的男子，共有二万二千二百七十三名。","notes":[]},{"n":44,"t":"耶和华晓谕摩西说：","notes":[]},{"n":45,"t":"「你拣选利未人代替以色列人所有头生的，也取利未人的牲畜代替以色列人的牲畜。利未人要归我；我是耶和华。","notes":[]},{"n":46,"t":"以色列人中头生的男子比利未人多二百七十三个，必当将他们赎出来。","notes":[]},{"n":47,"t":"你要按人丁，照圣所的平，每人取赎银五舍客勒（一舍客勒是二十季拉），","notes":[]},{"n":48,"t":"把那多余之人的赎银交给亚伦和他的儿子。」","notes":[]},{"n":49,"t":"于是摩西从那被利未人所赎以外的人取了赎银。","notes":[]},{"n":50,"t":"从以色列人头生的所取之银，按圣所的平，有一千三百六十五舍客勒。","notes":[]},{"n":51,"t":"摩西照耶和华的话把这赎银给亚伦和他的儿子，正如耶和华所吩咐的。","notes":[]}]},"4":{"heading":"哥辖子孙的职责","verses":[{"n":1,"t":"耶和华晓谕摩西、亚伦说：","notes":[]},{"n":2,"t":"「你从利未人中，将哥辖子孙的总数，照他们的家室、宗族，","notes":[]},{"n":3,"t":"从三十岁直到五十岁，凡前来任职、在会幕里办事的，全都计算。","notes":[]},{"n":4,"t":"哥辖子孙在会幕搬运至圣之物，所办的事乃是这样：","notes":[]},{"n":5,"t":"起营的时候，亚伦和他儿子要进去摘下遮掩柜的幔子，用以蒙盖法柜，","notes":[]},{"n":6,"t":"又用海狗皮盖在上头，再蒙上纯蓝色的毯子，把杠穿上。","notes":[]},{"n":7,"t":"又用蓝色毯子铺在陈设饼的桌子上，将盘子、调羹、奠酒的爵，和杯摆在上头。桌子上也必有常设的饼。","notes":[]},{"n":8,"t":"在其上又要蒙朱红色的毯子，再蒙上海狗皮，把杠穿上。","notes":[]},{"n":9,"t":"要拿蓝色毯子，把灯台和灯台上所用的灯盏、剪子、蜡花盘，并一切盛油的器皿，全都遮盖。","notes":[]},{"n":10,"t":"又要把灯台和灯台的一切器具包在海狗皮里，放在抬架上。","notes":[]},{"n":11,"t":"在金坛上要铺蓝色毯子，蒙上海狗皮，把杠穿上。","notes":[]},{"n":12,"t":"又要把圣所用的一切器具包在蓝色毯子里，用海狗皮蒙上，放在抬架上。","notes":[]},{"n":13,"t":"要收去坛上的灰，把紫色毯子铺在坛上；","notes":[]},{"n":14,"t":"又要把所用的一切器具，就是火鼎、肉锸子、铲子、盘子，一切属坛的器具都摆在坛上，又蒙上海狗皮，把杠穿上。","notes":[]},{"n":15,"t":"将要起营的时候，亚伦和他儿子把圣所和圣所的一切器具遮盖完了，哥辖的子孙就要来抬，只是不可摸圣物，免得他们死亡。会幕里这些物件是哥辖子孙所当抬的。","notes":[]},{"n":16,"t":"「祭司亚伦的儿子以利亚撒所要看守的是点灯的油与香料，并当献的素祭和膏油，也要看守全帐幕与其中所有的，并圣所和圣所的器具。」","notes":[]},{"n":17,"t":"耶和华晓谕摩西、亚伦说：","notes":[]},{"n":18,"t":"「你们不可将哥辖人的支派从利未人中剪除。","notes":[]},{"n":19,"t":"他们挨近至圣物的时候，亚伦和他儿子要进去派他们各人所当办的，所当抬的。这样待他们，好使他们活着，不致死亡。","notes":[]},{"n":20,"t":"只是他们连片时不可进去观看圣所，免得他们死亡。」","notes":[]},{"n":21,"t":"耶和华晓谕摩西说：","notes":[],"heads":["革顺子孙的职责"]},{"n":22,"t":"「你要将革顺子孙的总数，照着宗族、家室，","notes":[]},{"n":23,"t":"从三十岁直到五十岁，凡前来任职、在会幕里办事的，全都数点。","notes":[]},{"n":24,"t":"革顺人各族所办的事、所抬的物乃是这样：","notes":[]},{"n":25,"t":"他们要抬帐幕的幔子和会幕，并会幕的盖与其上的海狗皮，和会幕的门帘，","notes":[]},{"n":26,"t":"院子的帷子和门帘（院子是围帐幕和坛的）、绳子，并所用的器具，不论是做什么用的，他们都要经理。","notes":[]},{"n":27,"t":"革顺的子孙在一切抬物办事之上都要凭亚伦和他儿子的吩咐；他们所当抬的，要派他们看守。","notes":[]},{"n":28,"t":"这是革顺子孙的各族在会幕里所办的事；他们所看守的，必在祭司亚伦儿子以他玛的手下。」","notes":[]},{"n":29,"t":"「至于米拉利的子孙，你要照着家室、宗族把他们数点。","notes":[],"heads":["米拉利子孙的职责"]},{"n":30,"t":"从三十岁直到五十岁，凡前来任职、在会幕里办事的，你都要数点。","notes":[]},{"n":31,"t":"他们办理会幕的事，就是抬帐幕的板、闩、柱子，和带卯的座，","notes":[]},{"n":32,"t":"院子四围的柱子和其上带卯的座、橛子、绳子，并一切使用的器具。他们所抬的器具，你们要按名指定。","notes":[]},{"n":33,"t":"这是米拉利子孙各族在会幕里所办的事，都在祭司亚伦儿子以他玛的手下。」","notes":[]},{"n":34,"t":"摩西、亚伦与会众的诸首领将哥辖的子孙，照着家室、宗族，","notes":[],"heads":["利未支派男丁的统计"]},{"n":35,"t":"从三十岁直到五十岁，凡前来任职、在会幕里办事的，都数点了。","notes":[]},{"n":36,"t":"被数的共有二千七百五十名。","notes":[]},{"n":37,"t":"这是哥辖各族中被数的，是在会幕里办事的，就是摩西、亚伦照耶和华借摩西所吩咐数点的。","notes":[]},{"n":38,"t":"革顺子孙被数的，照着家室、宗族，","notes":[]},{"n":39,"t":"从三十岁直到五十岁，凡前来任职、在会幕里办事的，共有二千六百三十名。","notes":[],"end":40},{"n":41,"t":"这是革顺子孙各族中被数的，是在会幕里办事的，就是摩西、亚伦照耶和华借摩西所吩咐数点的。","notes":[]},{"n":42,"t":"米拉利子孙中各族被数的，照着家室、宗族，","notes":[]},{"n":43,"t":"从三十岁直到五十岁，凡前来任职、在会幕里办事的，共有三千二百名。","notes":[],"end":44},{"n":45,"t":"这是米拉利子孙各族中被数的，就是摩西、亚伦照耶和华借摩西所吩咐数点的。","notes":[]},{"n":46,"t":"凡被数的利未人，就是摩西、亚伦并以色列众首领，照着家室、宗族所数点的，","notes":[]},{"n":47,"t":"从三十岁直到五十岁，凡前来任职、在会幕里做抬物之工的，共有八千五百八十名。","notes":[],"end":48},{"n":49,"t":"摩西按他们所办的事、所抬的物，凭耶和华的吩咐数点他们；他们这样被摩西数点，正如耶和华所吩咐他的。","notes":[]}]},"5":{"heading":"不洁的人","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「你吩咐以色列人，使一切长大麻风的，患漏症的，并因死尸不洁净的，都出营外去。","notes":[]},{"n":3,"t":"无论男女都要使他们出到营外，免得污秽他们的营；这营是我所住的。」","notes":[]},{"n":4,"t":"以色列人就这样行，使他们出到营外。耶和华怎样吩咐摩西，以色列人就怎样行了。","notes":[]},{"n":5,"t":"耶和华对摩西说：","notes":[],"heads":["赔偿亏负"]},{"n":6,"t":"「你晓谕以色列人说：无论男女，若犯了人所常犯的罪，以致干犯耶和华，那人就有了罪。","notes":[]},{"n":7,"t":"他要承认所犯的罪，将所亏负人的，如数赔还，另外加上五分之一，也归与所亏负的人。","notes":[]},{"n":8,"t":"那人若没有亲属可受所赔还的，那所赔还的就要归与服事耶和华的祭司；至于那为他赎罪的公羊是在外。","notes":[]},{"n":9,"t":"以色列人一切的圣物中，所奉给祭司的举祭都要归与祭司。","notes":[]},{"n":10,"t":"各人所分别为圣的物，无论是什么，都要归给祭司。」","notes":[]},{"n":11,"t":"耶和华对摩西说：","notes":[],"heads":["疑妻不贞的案件"]},{"n":12,"t":"「你晓谕以色列人说：人的妻若有邪行，得罪她丈夫，","notes":[]},{"n":13,"t":"有人与她行淫，事情严密，瞒过她丈夫，而且她被玷污，没有作见证的人，当她行淫的时候也没有被捉住，","notes":[]},{"n":14,"t":"她丈夫生了疑恨的心，疑恨她，她是被玷污，或是她丈夫生了疑恨的心，疑恨她，她并没有被玷污，","notes":[]},{"n":15,"t":"这人就要将妻送到祭司那里，又为她带着大麦面伊法十分之一作供物，不可浇上油，也不可加上乳香；因为这是疑恨的素祭，是思念的素祭，使人思念罪孽。","notes":[]},{"n":16,"t":"「祭司要使那妇人近前来，站在耶和华面前。","notes":[]},{"n":17,"t":"祭司要把圣水盛在瓦器里，又从帐幕的地上取点尘土，放在水中。","notes":[]},{"n":18,"t":"祭司要叫那妇人蓬头散发，站在耶和华面前，把思念的素祭，就是疑恨的素祭，放在她手中。祭司手里拿着致咒诅的苦水，","notes":[]},{"n":19,"t":"要叫妇人起誓，对她说：『若没有人与你行淫，也未曾背着丈夫做污秽的事，你就免受这致咒诅苦水的灾。","notes":[]},{"n":20,"t":"你若背着丈夫行了污秽的事，在你丈夫以外有人与你行淫，","notes":[]},{"n":21,"t":"（祭司叫妇人发咒起誓，）愿耶和华叫你大腿消瘦，肚腹发胀，使你在你民中被人咒诅，成了誓语；","notes":[]},{"n":22,"t":"并且这致咒诅的水入你的肠中，要叫你的肚腹发胀，大腿消瘦。』妇人要回答说：『阿们，阿们。』","notes":[]},{"n":23,"t":"「祭司要写这咒诅的话，将所写的字抹在苦水里，","notes":[]},{"n":24,"t":"又叫妇人喝这致咒诅的苦水；这水要进入她里面变苦了。","notes":[]},{"n":25,"t":"祭司要从妇人的手中取那疑恨的素祭，在耶和华面前摇一摇，拿到坛前；","notes":[]},{"n":26,"t":"又要从素祭中取出一把，作为这事的纪念，烧在坛上，然后叫妇人喝这水。","notes":[]},{"n":27,"t":"叫她喝了以后，她若被玷污，得罪了丈夫，这致咒诅的水必进入她里面变苦了，她的肚腹就要发胀，大腿就要消瘦，那妇人便要在他民中被人咒诅。","notes":[]},{"n":28,"t":"若妇人没有被玷污，却是清洁的，就要免受这灾，且要怀孕。","notes":[]},{"n":29,"t":"「妻子背着丈夫行了污秽的事，","notes":[]},{"n":30,"t":"或是人生了疑恨的心，疑恨他的妻，就有这疑恨的条例。那时他要叫妇人站在耶和华面前，祭司要在她身上照这条例而行。","notes":[]},{"n":31,"t":"男人就为无罪，妇人必担当自己的罪孽。」","notes":[]}]},"6":{"heading":"拿细耳人的条例","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你晓谕以色列人说：无论男女许了特别的愿，就是拿细耳人的愿，要离俗归耶和华。","notes":["拿细耳就是归主的意思；下同"]},{"n":3,"t":"他就要远离清酒浓酒，也不可喝什么清酒浓酒做的醋；不可喝什么葡萄汁，也不可吃鲜葡萄和干葡萄。","notes":[]},{"n":4,"t":"在一切离俗的日子，凡葡萄树上结的，自核至皮所做的物，都不可吃。","notes":[]},{"n":5,"t":"「在他一切许愿离俗的日子，不可用剃头刀剃头，要由发绺长长了。他要圣洁，直到离俗归耶和华的日子满了。","notes":[]},{"n":6,"t":"在他离俗归耶和华的一切日子，不可挨近死尸。","notes":[]},{"n":7,"t":"他的父母或是弟兄姊妹死了的时候，他不可因他们使自己不洁净，因为那离俗归神的凭据是在他头上。","notes":[]},{"n":8,"t":"在他一切离俗的日子是归耶和华为圣。","notes":[]},{"n":9,"t":"「若在他旁边忽然有人死了，以致沾染了他离俗的头，他要在第七日，得洁净的时候，剃头。","notes":[]},{"n":10,"t":"第八日，他要把两只斑鸠或两只雏鸽带到会幕门口，交给祭司。","notes":[]},{"n":11,"t":"祭司要献一只作赎罪祭，一只作燔祭，为他赎那因死尸而有的罪，并要当日使他的头成为圣洁。","notes":[]},{"n":12,"t":"他要另选离俗归耶和华的日子，又要牵一只一岁的公羊羔来作赎愆祭；但先前的日子要归徒然，因为他在离俗之间被玷污了。","notes":[]},{"n":13,"t":"「拿细耳人满了离俗的日子乃有这条例：人要领他到会幕门口，","notes":[]},{"n":14,"t":"他要将供物奉给耶和华，就是一只没有残疾、一岁的公羊羔作燔祭，一只没有残疾、一岁的母羊羔作赎罪祭，和一只没有残疾的公绵羊作平安祭，","notes":[]},{"n":15,"t":"并一筐子无酵调油的细面饼，与抹油的无酵薄饼，并同献的素祭和奠祭。","notes":[]},{"n":16,"t":"祭司要在耶和华面前献那人的赎罪祭和燔祭；","notes":[]},{"n":17,"t":"也要把那只公羊和那筐无酵饼献给耶和华作平安祭，又要将同献的素祭和奠祭献上。","notes":[]},{"n":18,"t":"拿细耳人要在会幕门口剃离俗的头，把离俗头上的发放在平安祭下的火上。","notes":[]},{"n":19,"t":"他剃了以后，祭司就要取那已煮的公羊一条前腿，又从筐子里取一个无酵饼和一个无酵薄饼，都放在他手上。","notes":[]},{"n":20,"t":"祭司要拿这些作为摇祭，在耶和华面前摇一摇；这与所摇的胸、所举的腿同为圣物，归给祭司。然后拿细耳人可以喝酒。","notes":[]},{"n":21,"t":"「许愿的拿细耳人为离俗所献的供物，和他以外所能得的献给耶和华，就有这条例。他怎样许愿就当照离俗的条例行。」","notes":[]},{"n":22,"t":"耶和华晓谕摩西说：","notes":[],"heads":["祭司的祝福"]},{"n":23,"t":"「你告诉亚伦和他儿子说：你们要这样为以色列人祝福，说：","notes":[]},{"n":24,"t":"『愿耶和华赐福给你，保护你。","notes":[]},{"n":25,"t":"愿耶和华使他的脸光照你，赐恩给你。","notes":[]},{"n":26,"t":"愿耶和华向你仰脸，赐你平安。』","notes":[]},{"n":27,"t":"他们要如此奉我的名为以色列人祝福；我也要赐福给他们。」","notes":[]}]},"7":{"heading":"各族长奉献祭物","verses":[{"n":1,"t":"摩西立完了帐幕，就把帐幕用膏抹了，使它成圣，又把其中的器具和坛，并坛上的器具，都抹了，使它成圣。","notes":[]},{"n":2,"t":"当天，以色列的众首领，就是各族的族长，都来奉献。他们是各支派的首领，管理那些被数的人。","notes":[]},{"n":3,"t":"他们把自己的供物送到耶和华面前，就是六辆篷子车和十二只公牛。每两个首领奉献一辆车，每首领奉献一只牛。他们把这些都奉到帐幕前。","notes":[]},{"n":4,"t":"耶和华晓谕摩西说：","notes":[]},{"n":5,"t":"「你要收下这些，好作会幕的使用，都要照利未人所办的事交给他们。」","notes":[]},{"n":6,"t":"于是摩西收了车和牛，交给利未人，","notes":[]},{"n":7,"t":"把两辆车，四只牛，照革顺子孙所办的事交给他们，","notes":[]},{"n":8,"t":"又把四辆车，八只牛，照米拉利子孙所办的事交给他们；他们都在祭司亚伦的儿子以他玛手下。","notes":[]},{"n":9,"t":"但车与牛都没有交给哥辖子孙；因为他们办的是圣所的事，在肩头上抬圣物。","notes":[]},{"n":10,"t":"用膏抹坛的日子，首领都来行奉献坛的礼，众首领就在坛前献供物。","notes":[]},{"n":11,"t":"耶和华对摩西说：「众首领为行奉献坛的礼，要每天一个首领来献供物。」","notes":[]},{"n":12,"t":"头一日献供物的是犹大支派的亚米拿达的儿子拿顺。","notes":[]},{"n":13,"t":"他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":14,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":15,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":16,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":17,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是亚米拿达儿子拿顺的供物。","notes":[]},{"n":18,"t":"第二日来献的是以萨迦子孙的首领、苏押的儿子拿坦业。","notes":[]},{"n":19,"t":"他献为供物的是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":20,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":21,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":22,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":23,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是苏押儿子拿坦业的供物。","notes":[]},{"n":24,"t":"第三日来献的是西布伦子孙的首领、希伦的儿子以利押。","notes":[]},{"n":25,"t":"他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":26,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":27,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":28,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":29,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是希伦儿子以利押的供物。","notes":[]},{"n":30,"t":"第四日来献的是吕便子孙的首领、示丢珥的儿子以利蓿。","notes":[]},{"n":31,"t":"他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":32,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":33,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":34,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":35,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是示丢珥的儿子以利蓿的供物。","notes":[]},{"n":36,"t":"第五日来献的是西缅子孙的首领、苏利沙代的儿子示路蔑。","notes":[]},{"n":37,"t":"他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":38,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":39,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":40,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":41,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是苏利沙代儿子示路蔑的供物。","notes":[]},{"n":42,"t":"第六日来献的是迦得子孙的首领、丢珥的儿子以利雅萨。","notes":[]},{"n":43,"t":"他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":44,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":45,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":46,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":47,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是丢珥的儿子以利雅萨的供物。","notes":[]},{"n":48,"t":"第七日来献的是以法莲子孙的首领、亚米忽的儿子以利沙玛。","notes":[]},{"n":49,"t":"他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":50,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":51,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":52,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":53,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是亚米忽儿子以利沙玛的供物。","notes":[]},{"n":54,"t":"第八日来献的是玛拿西子孙的首领、比大蓿的儿子迦玛列。","notes":[]},{"n":55,"t":"他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":56,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":57,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":58,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":59,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是比大蓿儿子迦玛列的供物。","notes":[]},{"n":60,"t":"第九日来献的是便雅悯子孙的首领、基多尼的儿子亚比但。","notes":[]},{"n":61,"t":"他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":62,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":63,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":64,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":65,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是基多尼儿子亚比但的供物。","notes":[]},{"n":66,"t":"第十日来献的是但子孙的首领、亚米沙代的儿子亚希以谢。","notes":[]},{"n":67,"t":"他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":68,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":69,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":70,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":71,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是亚米沙代儿子亚希以谢的供物。","notes":[]},{"n":72,"t":"第十一日来献的是亚设子孙的首领、俄兰的儿子帕结。","notes":[]},{"n":73,"t":"他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":74,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":75,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":76,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":77,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是俄兰儿子帕结的供物。","notes":[]},{"n":78,"t":"第十二日来献的是拿弗他利子孙的首领、以南儿子亚希拉。","notes":[]},{"n":79,"t":"他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；","notes":[]},{"n":80,"t":"一个金盂，重十舍客勒，盛满了香；","notes":[]},{"n":81,"t":"一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；","notes":[]},{"n":82,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":83,"t":"两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是以南儿子亚希拉的供物。","notes":[]},{"n":84,"t":"用膏抹坛的日子，以色列的众首领为行献坛之礼所献的是：银盘子十二个，银碗十二个，金盂十二个；","notes":[]},{"n":85,"t":"每盘子重一百三十舍客勒，每碗重七十舍客勒。一切器皿的银子，按圣所的平，共有二千四百舍客勒。","notes":[]},{"n":86,"t":"十二个金盂盛满了香，按圣所的平，每盂重十舍客勒，所有的金子共一百二十舍客勒。","notes":[]},{"n":87,"t":"作燔祭的，共有公牛十二只，公羊十二只，一岁的公羊羔十二只，并同献的素祭作赎罪祭的公山羊十二只；","notes":[]},{"n":88,"t":"作平安祭的，共有公牛二十四只，公绵羊六十只，公山羊六十只，一岁的公羊羔六十只。这就是用膏抹坛之后，为行奉献坛之礼所献的。","notes":[]},{"n":89,"t":"摩西进会幕要与耶和华说话的时候，听见法柜的施恩座以上、二基路伯中间有与他说话的声音，就是耶和华与他说话。","notes":[]}]},"8":{"heading":"安置七盏灯","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「你告诉亚伦说：点灯的时候，七盏灯都要向灯台前面发光。」","notes":[]},{"n":3,"t":"亚伦便这样行。他点灯台上的灯，使灯向前发光，是照耶和华所吩咐摩西的。","notes":[]},{"n":4,"t":"这灯台的做法是用金子锤出来的，连座带花都是锤出来的。摩西制造灯台，是照耶和华所指示的样式。","notes":[]},{"n":5,"t":"耶和华晓谕摩西说：","notes":[],"heads":["为利未人行洁净与奉献礼"]},{"n":6,"t":"「你从以色列人中选出利未人来，洁净他们。","notes":[]},{"n":7,"t":"洁净他们当这样行：用除罪水弹在他们身上，又叫他们用剃头刀刮全身，洗衣服，洁净自己。","notes":[]},{"n":8,"t":"然后叫他们取一只公牛犊，并同献的素祭，就是调油的细面；你要另取一只公牛犊作赎罪祭。","notes":[]},{"n":9,"t":"将利未人奉到会幕前，招聚以色列全会众。","notes":[]},{"n":10,"t":"将利未人奉到耶和华面前，以色列人要按手在他们头上。","notes":[]},{"n":11,"t":"亚伦也将他们奉到耶和华面前，为以色列人当作摇祭，使他们好办耶和华的事。","notes":[]},{"n":12,"t":"利未人要按手在那两只牛的头上；你要将一只作赎罪祭，一只作燔祭，献给耶和华，为利未人赎罪。","notes":[]},{"n":13,"t":"你也要使利未人站在亚伦和他儿子面前，将他们当作摇祭奉给耶和华。","notes":[]},{"n":14,"t":"「这样，你从以色列人中将利未人分别出来，利未人便要归我。","notes":[]},{"n":15,"t":"此后利未人要进去办会幕的事，你要洁净他们，将他们当作摇祭奉上；","notes":[]},{"n":16,"t":"因为他们是从以色列人中全然给我的，我拣选他们归我，是代替以色列人中一切头生的。","notes":[]},{"n":17,"t":"以色列人中一切头生的，连人带牲畜，都是我的。我在埃及地击杀一切头生的那天，将他们分别为圣归我。","notes":[]},{"n":18,"t":"我拣选利未人代替以色列人中一切头生的。","notes":[]},{"n":19,"t":"我从以色列人中将利未人当作赏赐给亚伦和他的儿子，在会幕中办以色列人的事，又为以色列人赎罪，免得他们挨近圣所，有灾殃临到他们中间。」","notes":[]},{"n":20,"t":"摩西、亚伦，并以色列全会众便向利未人如此行。凡耶和华指着利未人所吩咐摩西的，以色列人就向他们这样行。","notes":[]},{"n":21,"t":"于是利未人洁净自己，除了罪，洗了衣服；亚伦将他们当作摇祭奉到耶和华面前，又为他们赎罪，洁净他们。","notes":[]},{"n":22,"t":"然后利未人进去，在亚伦和他儿子面前，在会幕中办事。耶和华指着利未人怎样吩咐摩西，以色列人就怎样向他们行了。","notes":[]},{"n":23,"t":"耶和华晓谕摩西说：","notes":[]},{"n":24,"t":"「利未人是这样：从二十五岁以外，他们要前来任职，办会幕的事。","notes":[]},{"n":25,"t":"到了五十岁要停工退任，不再办事，","notes":[]},{"n":26,"t":"只要在会幕里，和他们的弟兄一同伺候，谨守所吩咐的，不再办事了。至于所吩咐利未人的，你要这样向他们行。」","notes":[]}]},"9":{"heading":"第二个逾越节","verses":[{"n":1,"t":"以色列人出埃及地以后，第二年正月，耶和华在西奈的旷野吩咐摩西说：","notes":[]},{"n":2,"t":"「以色列人应当在所定的日期守逾越节，","notes":[]},{"n":3,"t":"就是本月十四日黄昏的时候，你们要在所定的日期守这节，要按这节的律例典章而守。」","notes":[]},{"n":4,"t":"于是摩西吩咐以色列人守逾越节。","notes":[]},{"n":5,"t":"他们就在西奈的旷野，正月十四日黄昏的时候，守逾越节。凡耶和华所吩咐摩西的，以色列人都照样行了。","notes":[]},{"n":6,"t":"有几个人因死尸而不洁净，不能在那日守逾越节。当日他们到摩西、亚伦面前，","notes":[]},{"n":7,"t":"说：「我们虽因死尸而不洁净，为何被阻止、不得同以色列人在所定的日期献耶和华的供物呢？」","notes":[]},{"n":8,"t":"摩西对他们说：「你们暂且等候，我可以去听耶和华指着你们是怎样吩咐的。」","notes":[]},{"n":9,"t":"耶和华对摩西说：","notes":[]},{"n":10,"t":"「你晓谕以色列人说：你们和你们后代中，若有人因死尸而不洁净，或在远方行路，还要向耶和华守逾越节。","notes":[]},{"n":11,"t":"他们要在二月十四日黄昏的时候，守逾越节。要用无酵饼与苦菜，和逾越节的羊羔同吃。","notes":[]},{"n":12,"t":"一点不可留到早晨；羊羔的骨头一根也不可折断。他们要照逾越节的一切律例而守。","notes":[]},{"n":13,"t":"那洁净而不行路的人若推辞不守逾越节，那人要从民中剪除；因为他在所定的日期不献耶和华的供物，应该担当他的罪。","notes":[]},{"n":14,"t":"若有外人寄居在你们中间，愿意向耶和华守逾越节，他要照逾越节的律例典章行，不管是寄居的是本地人，同归一例。」","notes":[]},{"n":15,"t":"立起帐幕的那日，有云彩遮盖帐幕，就是法柜的帐幕；从晚上到早晨，云彩在其上，形状如火。","notes":[],"heads":["云彩遮盖帐幕"]},{"n":16,"t":"常是这样，云彩遮盖帐幕，夜间形状如火。","notes":[]},{"n":17,"t":"云彩几时从帐幕收上去，以色列人就几时起行；云彩在哪里停住，以色列人就在那里安营。","notes":[]},{"n":18,"t":"以色列人遵耶和华的吩咐起行，也遵耶和华的吩咐安营。云彩在帐幕上停住几时，他们就住营几时。","notes":[]},{"n":19,"t":"云彩在帐幕上停留许多日子，以色列人就守耶和华所吩咐的不起行。","notes":[]},{"n":20,"t":"有时云彩在帐幕上几天，他们就照耶和华的吩咐住营，也照耶和华的吩咐起行。","notes":[]},{"n":21,"t":"有时从晚上到早晨，有这云彩在帐幕上；早晨云彩收上去，他们就起行。有时昼夜云彩停在帐幕上，收上去的时候，他们就起行。","notes":[]},{"n":22,"t":"云彩停留在帐幕上，无论是两天，是一月，是一年，以色列人就住营不起行；但云彩收上去，他们就起行。","notes":[]},{"n":23,"t":"他们遵耶和华的吩咐安营，也遵耶和华的吩咐起行。他们守耶和华所吩咐的，都是凭耶和华吩咐摩西的。","notes":[]}]},"10":{"heading":"制银号","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「你要用银子做两枝号，都要锤出来的，用以招聚会众，并叫众营起行。","notes":[]},{"n":3,"t":"吹这号的时候，全会众要到你那里，聚集在会幕门口。","notes":[]},{"n":4,"t":"若单吹一枝，众首领，就是以色列军中的统领，要聚集到你那里。","notes":[]},{"n":5,"t":"吹出大声的时候，东边安的营都要起行。","notes":[]},{"n":6,"t":"二次吹出大声的时候，南边安的营都要起行。他们将起行，必吹出大声。","notes":[]},{"n":7,"t":"但招聚会众的时候，你们要吹号，却不要吹出大声。","notes":[]},{"n":8,"t":"亚伦子孙作祭司的要吹这号；这要作你们世世代代永远的定例。","notes":[]},{"n":9,"t":"你们在自己的地，与欺压你们的敌人打仗，就要用号吹出大声，便在耶和华—你们的神面前得蒙纪念，也蒙拯救脱离仇敌。","notes":[]},{"n":10,"t":"在你们快乐的日子和节期，并月朔，献燔祭和平安祭，也要吹号，这都要在你们的神面前作为纪念。我是耶和华—你们的神。」","notes":[]},{"n":11,"t":"第二年二月二十日，云彩从法柜的帐幕收上去。","notes":[],"heads":["离开西奈山"]},{"n":12,"t":"以色列人就按站往前行，离开西奈的旷野，云彩停住在巴兰的旷野。","notes":[]},{"n":13,"t":"这是他们照耶和华借摩西所吩咐的，初次往前行。","notes":[]},{"n":14,"t":"按着军队首先往前行的是犹大营的纛。统领军队的是亚米拿达的儿子拿顺。","notes":[]},{"n":15,"t":"统领以萨迦支派军队的是苏押的儿子拿坦业。","notes":[]},{"n":16,"t":"统领西布伦支派军队的是希伦的儿子以利押。","notes":[]},{"n":17,"t":"帐幕拆卸，革顺的子孙和米拉利的子孙就抬着帐幕先往前行。","notes":[]},{"n":18,"t":"按着军队往前行的是吕便营的纛。统领军队的是示丢珥的儿子以利蓿。","notes":[]},{"n":19,"t":"统领西缅支派军队的是苏利沙代的儿子示路蔑。","notes":[]},{"n":20,"t":"统领迦得支派军队的是丢珥的儿子以利雅萨。","notes":[]},{"n":21,"t":"哥辖人抬着圣物先往前行。他们未到以前，抬帐幕的已经把帐幕支好。","notes":[]},{"n":22,"t":"按着军队往前行的是以法莲营的纛，统领军队的是亚米忽的儿子以利沙玛。","notes":[]},{"n":23,"t":"统领玛拿西支派军队的是比大蓿的儿子迦玛列。","notes":[]},{"n":24,"t":"统领便雅悯支派军队的是基多尼的儿子亚比但。","notes":[]},{"n":25,"t":"在诸营末后的是但营的纛，按着军队往前行。统领军队的是亚米沙代的儿子亚希以谢。","notes":[]},{"n":26,"t":"统领亚设支派军队的是俄兰的儿子帕结。","notes":[]},{"n":27,"t":"统领拿弗他利支派军队的是以南的儿子亚希拉。","notes":[]},{"n":28,"t":"以色列人按着军队往前行，就是这样。","notes":[]},{"n":29,"t":"摩西对他岳父—米甸人流珥的儿子何巴—说：「我们要行路，往耶和华所应许之地去；他曾说：『我要将这地赐给你们。』现在求你和我们同去，我们必厚待你，因为耶和华指着以色列人已经应许给好处。」","notes":["或译：内兄"]},{"n":30,"t":"何巴回答说：「我不去；我要回本地本族那里去。」","notes":[]},{"n":31,"t":"摩西说：「求你不要离开我们；因为你知道我们要在旷野安营，你可以当作我们的眼目。","notes":[]},{"n":32,"t":"你若和我们同去，将来耶和华有什么好处待我们，我们也必以什么好处待你。」","notes":[]},{"n":33,"t":"以色列人离开耶和华的山，往前行了三天的路程；耶和华的约柜在前头行了三天的路程，为他们寻找安歇的地方。","notes":[],"heads":["众民和约柜往前行"]},{"n":34,"t":"他们拔营往前行，日间有耶和华的云彩在他们以上。","notes":[]},{"n":35,"t":"约柜往前行的时候，摩西就说：「耶和华啊，求你兴起！愿你的仇敌四散！愿恨你的人从你面前逃跑！」","notes":[]},{"n":36,"t":"约柜停住的时候，他就说：「耶和华啊，求你回到以色列的千万人中！」","notes":[]}]},"11":{"heading":"在他备拉发怨言","verses":[{"n":1,"t":"众百姓发怨言，他们的恶语达到耶和华的耳中。耶和华听见了就怒气发作，使火在他们中间焚烧，直烧到营的边界。","notes":[]},{"n":2,"t":"百姓向摩西哀求，摩西祈求耶和华，火就熄了。","notes":[]},{"n":3,"t":"那地方便叫做他备拉，因为耶和华的火烧在他们中间。","notes":[]},{"n":4,"t":"他们中间的闲杂人大起贪欲的心；以色列人又哭号说：「谁给我们肉吃呢？","notes":[],"heads":["摩西选立七十个长老"]},{"n":5,"t":"我们记得，在埃及的时候不花钱就吃鱼，也记得有黄瓜、西瓜、韭菜、葱、蒜。","notes":[]},{"n":6,"t":"现在我们的心血枯竭了，除这吗哪以外，在我们眼前并没有别的东西。」","notes":[]},{"n":7,"t":"这吗哪仿佛芫荽子，又好像珍珠。","notes":[]},{"n":8,"t":"百姓周围行走，把吗哪收起来，或用磨推，或用臼捣，煮在锅中，又做成饼，滋味好像新油。","notes":[]},{"n":9,"t":"夜间露水降在营中，吗哪也随着降下。）","notes":[]},{"n":10,"t":"摩西听见百姓各在各家的帐棚门口哭号。耶和华的怒气便大发作，摩西就不喜悦。","notes":[]},{"n":11,"t":"摩西对耶和华说：「你为何苦待仆人？我为何不在你眼前蒙恩，竟把这管理百姓的重任加在我身上呢？","notes":[]},{"n":12,"t":"这百姓岂是我怀的胎，岂是我生下来的呢？你竟对我说：『把他们抱在怀里，如养育之父抱吃奶的孩子，直抱到你起誓应许给他们祖宗的地去。』","notes":[]},{"n":13,"t":"我从哪里得肉给这百姓吃呢？他们都向我哭号说：『你给我们肉吃吧！』","notes":[]},{"n":14,"t":"管理这百姓的责任太重了，我独自担当不起。","notes":[]},{"n":15,"t":"你这样待我，我若在你眼前蒙恩，求你立时将我杀了，不叫我见自己的苦情。」","notes":[]},{"n":16,"t":"耶和华对摩西说：「你从以色列的长老中招聚七十个人，就是你所知道作百姓的长老和官长的，到我这里来，领他们到会幕前，使他们和你一同站立。","notes":[]},{"n":17,"t":"我要在那里降临，与你说话，也要把降于你身上的灵分赐他们，他们就和你同当这管百姓的重任，免得你独自担当。","notes":[]},{"n":18,"t":"又要对百姓说：『你们应当自洁，预备明天吃肉，因为你们哭号说：谁给我们肉吃！我们在埃及很好。这声音达到了耶和华的耳中，所以他必给你们肉吃。","notes":[]},{"n":19,"t":"你们不止吃一天、两天、五天、十天、二十天，","notes":[]},{"n":20,"t":"要吃一个整月，甚至肉从你们鼻孔里喷出来，使你们厌恶了，因为你们厌弃住在你们中间的耶和华，在他面前哭号说：我们为何出了埃及呢！』」","notes":[]},{"n":21,"t":"摩西对耶和华说：「这与我同住的百姓、步行的男人有六十万，你还说：『我要把肉给他们，使他们可以吃一个整月。』","notes":[]},{"n":22,"t":"难道给他们宰了羊群牛群，或是把海中所有的鱼都聚了来，就够他们吃吗？」","notes":[]},{"n":23,"t":"耶和华对摩西说：「耶和华的膀臂岂是缩短了吗？现在要看我的话向你应验不应验。」","notes":[]},{"n":24,"t":"摩西出去，将耶和华的话告诉百姓，又招聚百姓的长老中七十个人来，使他们站在会幕的四围。","notes":[]},{"n":25,"t":"耶和华在云中降临，对摩西说话，把降与他身上的灵分赐那七十个长老。灵停在他们身上的时候，他们就受感说话，以后却没有再说。","notes":[]},{"n":26,"t":"但有两个人仍在营里，一个名叫伊利达，一个名叫米达。他们本是在那些被录的人中，却没有到会幕那里去。灵停在他们身上，他们就在营里说预言。","notes":[]},{"n":27,"t":"有个少年人跑来告诉摩西说：「伊利达、米达在营里说预言。」","notes":[]},{"n":28,"t":"摩西的帮手，嫩的儿子约书亚，就是摩西所拣选的一个人，说：「请我主摩西禁止他们。」","notes":[]},{"n":29,"t":"摩西对他说：「你为我的缘故嫉妒人吗？惟愿耶和华的百姓都受感说话！愿耶和华把他的灵降在他们身上！」","notes":[]},{"n":30,"t":"于是，摩西和以色列的长老都回到营里去。","notes":[]},{"n":31,"t":"有风从耶和华那里刮起，把鹌鹑由海面刮来，飞散在营边和营的四围；这边约有一天的路程，那边约有一天的路程，离地面约有二肘。","notes":[],"heads":["神赐鹌鹑为食物"]},{"n":32,"t":"百姓起来，终日终夜，并次日一整天，捕取鹌鹑；至少的也取了十贺梅珥，为自己摆列在营的四围。","notes":[]},{"n":33,"t":"肉在他们牙齿之间尚未嚼烂，耶和华的怒气就向他们发作，用最重的灾殃击杀了他们。","notes":[]},{"n":34,"t":"那地方便叫做基博罗·哈他瓦，因为他们在那里葬埋那起贪欲之心的人。","notes":["就是贪欲之人的坟墓"]},{"n":35,"t":"百姓从基博罗·哈他瓦走到哈洗录，就住在哈洗录。","notes":[]}]},"12":{"heading":"米利暗受罚","verses":[{"n":1,"t":"摩西娶了古实女子为妻。米利暗和亚伦因他所娶的古实女子就毁谤他，说：","notes":[]},{"n":2,"t":"「难道耶和华单与摩西说话，不也与我们说话吗？」这话耶和华听见了。","notes":[]},{"n":3,"t":"摩西为人极其谦和，胜过世上的众人。","notes":[]},{"n":4,"t":"耶和华忽然对摩西、亚伦、米利暗说：「你们三个人都出来，到会幕这里。」他们三个人就出来了。","notes":[]},{"n":5,"t":"耶和华在云柱中降临，站在会幕门口，召亚伦和米利暗，二人就出来了。","notes":[]},{"n":6,"t":"耶和华说：「你们且听我的话：你们中间若有先知，我—耶和华必在异象中向他显现，在梦中与他说话。","notes":[]},{"n":7,"t":"我的仆人摩西不是这样；他是在我全家尽忠的。","notes":[]},{"n":8,"t":"我要与他面对面说话，乃是明说，不用谜语，并且他必见我的形象。你们毁谤我的仆人摩西，为何不惧怕呢？」","notes":[]},{"n":9,"t":"耶和华就向他们二人发怒而去。","notes":[]},{"n":10,"t":"云彩从会幕上挪开了，不料，米利暗长了大麻风，有雪那样白。亚伦一看米利暗长了大麻风，","notes":[]},{"n":11,"t":"就对摩西说：「我主啊，求你不要因我们愚昧犯罪，便将这罪加在我们身上。","notes":[]},{"n":12,"t":"求你不要使她像那出母腹、肉已半烂的死胎。」","notes":[]},{"n":13,"t":"于是摩西哀求耶和华说：「神啊，求你医治她！」","notes":[]},{"n":14,"t":"耶和华对摩西说：「她父亲若吐唾沫在她脸上，她岂不蒙羞七天吗？现在要把她在营外关锁七天，然后才可以领她进来。」","notes":[]},{"n":15,"t":"于是米利暗关锁在营外七天。百姓没有行路，直等到把米利暗领进来。","notes":[]},{"n":16,"t":"以后百姓从哈洗录起行，在巴兰的旷野安营。","notes":[]}]},"13":{"heading":"十二个探子","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「你打发人去窥探我所赐给以色列人的迦南地，他们每支派中要打发一个人，都要作首领的。」","notes":[]},{"n":3,"t":"摩西就照耶和华的吩咐从巴兰的旷野打发他们去；他们都是以色列人的族长。","notes":[]},{"n":4,"t":"他们的名字：属吕便支派的有撒刻的儿子沙母亚。","notes":[]},{"n":5,"t":"属西缅支派的有何利的儿子沙法。","notes":[]},{"n":6,"t":"属犹大支派的有耶孚尼的儿子迦勒。","notes":[]},{"n":7,"t":"属以萨迦支派的有约色的儿子以迦。","notes":[]},{"n":8,"t":"属以法莲支派的有嫩的儿子何希阿。","notes":[]},{"n":9,"t":"属便雅悯支派的有拉孚的儿子帕提。","notes":[]},{"n":10,"t":"属西布伦支派的有梭底的儿子迦叠。","notes":[]},{"n":11,"t":"约瑟的子孙，属玛拿西支派的有稣西的儿子迦底。","notes":[]},{"n":12,"t":"属但支派的有基玛利的儿子亚米利。","notes":[]},{"n":13,"t":"属亚设支派的有米迦勒的儿子西帖。","notes":[]},{"n":14,"t":"属拿弗他利支派的有缚西的儿子拿比。","notes":[]},{"n":15,"t":"属迦得支派的有玛基的儿子臼利。","notes":[]},{"n":16,"t":"这就是摩西所打发、窥探那地之人的名字。摩西就称嫩的儿子何希阿为约书亚。","notes":[]},{"n":17,"t":"摩西打发他们去窥探迦南地，说：「你们从南地上山地去，","notes":[]},{"n":18,"t":"看那地如何，其中所住的民是强是弱，是多是少，","notes":[]},{"n":19,"t":"所住之地是好是歹，所住之处是营盘是坚城。","notes":[]},{"n":20,"t":"又看那地土是肥美是瘠薄，其中有树木没有。你们要放开胆量，把那地的果子带些来。」（那时正是葡萄初熟的时候。）","notes":[]},{"n":21,"t":"他们上去窥探那地，从寻的旷野到利合，直到哈马口。","notes":[]},{"n":22,"t":"他们从南地上去，到了希伯仑；在那里有亚衲族人亚希幔、示筛、挞买。（原来希伯仑城被建造比埃及的锁安城早七年。）","notes":[]},{"n":23,"t":"他们到了以实各谷，从那里砍了葡萄树的一枝，上头有一挂葡萄，两个人用杠抬着，又带了些石榴和无花果来。（","notes":[]},{"n":24,"t":"因为以色列人从那里砍来的那挂葡萄，所以那地方叫做以实各谷。）","notes":[]},{"n":25,"t":"过了四十天，他们窥探那地才回来，","notes":[]},{"n":26,"t":"到了巴兰旷野的加低斯，见摩西、亚伦，并以色列的全会众，回报摩西、亚伦，并全会众，又把那地的果子给他们看；","notes":[]},{"n":27,"t":"又告诉摩西说：「我们到了你所打发我们去的那地，果然是流奶与蜜之地；这就是那地的果子。","notes":[]},{"n":28,"t":"然而住那地的民强壮，城邑也坚固宽大，并且我们在那里看见了亚衲族的人。","notes":[]},{"n":29,"t":"亚玛力人住在南地；赫人、耶布斯人、亚摩利人住在山地；迦南人住在海边并约旦河旁。」","notes":[]},{"n":30,"t":"迦勒在摩西面前安抚百姓，说：「我们立刻上去得那地吧！我们足能得胜。」","notes":[]},{"n":31,"t":"但那些和他同去的人说：「我们不能上去攻击那民，因为他们比我们强壮。」","notes":[]},{"n":32,"t":"探子中有人论到所窥探之地，向以色列人报恶信，说：「我们所窥探、经过之地是吞吃居民之地，我们在那里所看见的人民都身量高大。","notes":[]},{"n":33,"t":"我们在那里看见亚衲族人，就是伟人；他们是伟人的后裔。据我们看，自己就如蚱蜢一样；据他们看，我们也是如此。」","notes":[]}]},"14":{"heading":"民众埋怨","verses":[{"n":1,"t":"当下，全会众大声喧嚷；那夜百姓都哭号。","notes":[]},{"n":2,"t":"以色列众人向摩西、亚伦发怨言；全会众对他们说：「巴不得我们早死在埃及地，或是死在这旷野。","notes":[]},{"n":3,"t":"耶和华为什么把我们领到那地，使我们倒在刀下呢？我们的妻子和孩子必被掳掠。我们回埃及去岂不好吗？」","notes":[]},{"n":4,"t":"众人彼此说：「我们不如立一个首领回埃及去吧！」","notes":[]},{"n":5,"t":"摩西、亚伦就俯伏在以色列全会众面前。","notes":[]},{"n":6,"t":"窥探地的人中，嫩的儿子约书亚和耶孚尼的儿子迦勒撕裂衣服，","notes":[]},{"n":7,"t":"对以色列全会众说：「我们所窥探、经过之地是极美之地。","notes":[]},{"n":8,"t":"耶和华若喜悦我们，就必将我们领进那地，把地赐给我们；那地原是流奶与蜜之地。","notes":[]},{"n":9,"t":"但你们不可背叛耶和华，也不要怕那地的居民；因为他们是我们的食物，并且荫庇他们的已经离开他们。有耶和华与我们同在，不要怕他们！」","notes":[]},{"n":10,"t":"但全会众说：「拿石头打死他们二人。」忽然，耶和华的荣光在会幕中向以色列众人显现。","notes":[]},{"n":11,"t":"耶和华对摩西说：「这百姓藐视我要到几时呢？我在他们中间行了这一切神迹，他们还不信我要到几时呢？","notes":[],"heads":["摩西为民众祷告"]},{"n":12,"t":"我要用瘟疫击杀他们，使他们不得承受那地，叫你的后裔成为大国，比他们强胜。」","notes":[]},{"n":13,"t":"摩西对耶和华说：「埃及人必听见这事；因为你曾施展大能，将这百姓从他们中间领上来。","notes":[]},{"n":14,"t":"埃及人要将这事传给迦南地的居民；那民已经听见你—耶和华是在这百姓中间；因为你面对面被人看见，有你的云彩停在他们以上。你日间在云柱中，夜间在火柱中，在他们前面行。","notes":[]},{"n":15,"t":"如今你若把这百姓杀了，如杀一人，那些听见你名声的列邦必议论说：","notes":[]},{"n":16,"t":"『耶和华因为不能把这百姓领进他向他们起誓应许之地，所以在旷野把他们杀了。』","notes":[]},{"n":17,"t":"现在求主大显能力，照你所说过的话说：","notes":[]},{"n":18,"t":"『耶和华不轻易发怒，并有丰盛的慈爱，赦免罪孽和过犯；万不以有罪的为无罪，必追讨他的罪，自父及子，直到三、四代。』","notes":[]},{"n":19,"t":"求你照你的大慈爱赦免这百姓的罪孽，好像你从埃及到如今常赦免他们一样。」","notes":[]},{"n":20,"t":"耶和华说：「我照着你的话赦免了他们。","notes":[]},{"n":21,"t":"然我指着我的永生起誓，遍地要被我的荣耀充满。","notes":[]},{"n":22,"t":"这些人虽看见我的荣耀和我在埃及与旷野所行的神迹，仍然试探我这十次，不听从我的话，","notes":[]},{"n":23,"t":"他们断不得看见我向他们的祖宗所起誓应许之地。凡藐视我的，一个也不得看见；","notes":[]},{"n":24,"t":"惟独我的仆人迦勒，因他另有一个心志，专一跟从我，我就把他领进他所去过的那地；他的后裔也必得那地为业。","notes":[]},{"n":25,"t":"亚玛力人和迦南人住在谷中，明天你们要转回，从红海的路往旷野去。」","notes":[]},{"n":26,"t":"耶和华对摩西、亚伦说：","notes":[],"heads":["耶和华惩罚埋怨的民众"]},{"n":27,"t":"「这恶会众向我发怨言，我忍耐他们要到几时呢？以色列人向我所发的怨言，我都听见了。","notes":[]},{"n":28,"t":"你们告诉他们，耶和华说：『我指着我的永生起誓，我必要照你们达到我耳中的话待你们。","notes":[]},{"n":29,"t":"你们的尸首必倒在这旷野，并且你们中间凡被数点、从二十岁以外、向我发怨言的，","notes":[]},{"n":30,"t":"必不得进我起誓应许叫你们住的那地；惟有耶孚尼的儿子迦勒和嫩的儿子约书亚才能进去。","notes":[]},{"n":31,"t":"但你们的妇人孩子，就是你们所说、要被掳掠的，我必把他们领进去，他们就得知你们所厌弃的那地。","notes":[]},{"n":32,"t":"至于你们，你们的尸首必倒在这旷野；","notes":[]},{"n":33,"t":"你们的儿女必在旷野飘流四十年，担当你们淫行的罪，直到你们的尸首在旷野消灭。","notes":[]},{"n":34,"t":"按你们窥探那地的四十日，一年顶一日，你们要担当罪孽四十年，就知道我与你们疏远了，","notes":[]},{"n":35,"t":"我—耶和华说过，我总要这样待这一切聚集敌我的恶会众；他们必在这旷野消灭，在这里死亡。』」","notes":[]},{"n":36,"t":"摩西所打发、窥探那地的人回来，报那地的恶信，叫全会众向摩西发怨言，","notes":[]},{"n":37,"t":"这些报恶信的人都遭瘟疫，死在耶和华面前。","notes":[]},{"n":38,"t":"其中惟有嫩的儿子约书亚和耶孚尼的儿子迦勒仍然存活。","notes":[]},{"n":39,"t":"摩西将这些话告诉以色列众人，他们就甚悲哀。","notes":[],"heads":["首次进攻迦南"]},{"n":40,"t":"清早起来，上山顶去，说：「我们在这里，我们有罪了；情愿上耶和华所应许的地方去。」","notes":[]},{"n":41,"t":"摩西说：「你们为何违背耶和华的命令呢？这事不能顺利了。","notes":[]},{"n":42,"t":"不要上去；因为耶和华不在你们中间，恐怕你们被仇敌杀败了。","notes":[]},{"n":43,"t":"亚玛力人和迦南人都在你们面前，你们必倒在刀下；因你们退回不跟从耶和华，所以他必不与你们同在。」","notes":[]},{"n":44,"t":"他们却擅敢上山顶去，然而耶和华的约柜和摩西没有出营。","notes":[]},{"n":45,"t":"于是亚玛力人和住在那山上的迦南人都下来击打他们，把他们杀退了，直到何珥玛。","notes":[]}]},"15":{"heading":"献祭的条例","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你晓谕以色列人说：你们到了我所赐给你们居住的地，","notes":[]},{"n":3,"t":"若愿意从牛群羊群中取牛羊作火祭，献给耶和华，无论是燔祭是平安祭，为要还特许的愿，或是作甘心祭，或是逢你们节期献的，都要奉给耶和华为馨香之祭。","notes":[]},{"n":4,"t":"那献供物的就要将细面伊法十分之一，并油一欣四分之一，调和作素祭，献给耶和华。","notes":[]},{"n":5,"t":"无论是燔祭是平安祭，你要为每只绵羊羔，一同预备奠祭的酒一欣四分之一。","notes":[]},{"n":6,"t":"为公绵羊预备细面伊法十分之二，并油一欣三分之一，调和作素祭，","notes":[]},{"n":7,"t":"又用酒一欣三分之一作奠祭，献给耶和华为馨香之祭。","notes":[]},{"n":8,"t":"你预备公牛作燔祭，或是作平安祭，为要还特许的愿，或是作平安祭，献给耶和华，","notes":[]},{"n":9,"t":"就要把细面伊法十分之三，并油半欣，调和作素祭，和公牛一同献上，","notes":[]},{"n":10,"t":"又用酒半欣作奠祭，献给耶和华为馨香的火祭。","notes":[]},{"n":11,"t":"「献公牛、公绵羊、绵羊羔、山羊羔，每只都要这样办理。","notes":[]},{"n":12,"t":"照你们所预备的数目，按着只数都要这样办理。","notes":[]},{"n":13,"t":"凡本地人将馨香的火祭献给耶和华，都要这样办理。","notes":[]},{"n":14,"t":"若有外人和你们同居，或有人世世代代住在你们中间，愿意将馨香的火祭献给耶和华，你们怎样办理，他也要照样办理。","notes":[]},{"n":15,"t":"至于会众，你们和同居的外人都归一例，作为你们世世代代永远的定例，在耶和华面前，你们怎样，寄居的也要怎样。","notes":[]},{"n":16,"t":"你们并与你们同居的外人当有一样的条例，一样的典章。」","notes":[]},{"n":17,"t":"耶和华对摩西说：","notes":[]},{"n":18,"t":"「你晓谕以色列人说：你们到了我所领你们进去的那地，","notes":[]},{"n":19,"t":"吃那地的粮食，就要把举祭献给耶和华。","notes":[]},{"n":20,"t":"你们要用初熟的麦子磨面，做饼当举祭奉献；你们举上，好像举禾场的举祭一样。","notes":[]},{"n":21,"t":"你们世世代代要用初熟的麦子磨面，当举祭献给耶和华。","notes":[]},{"n":22,"t":"「你们有错误的时候，不守耶和华所晓谕摩西的这一切命令，","notes":[]},{"n":23,"t":"就是耶和华借摩西一切所吩咐你们的，自那日以至你们的世世代代，","notes":[]},{"n":24,"t":"若有误行，是会众所不知道的，后来全会众就要将一只公牛犊作燔祭，并照典章把素祭和奠祭一同献给耶和华为馨香之祭，又献一只公山羊作赎罪祭。","notes":[]},{"n":25,"t":"祭司要为以色列全会众赎罪，他们就必蒙赦免，因为这是错误。他们又因自己的错误，把供物，就是向耶和华献的火祭和赎罪祭，一并奉到耶和华面前。","notes":[]},{"n":26,"t":"以色列全会众和寄居在他们中间的外人就必蒙赦免，因为这罪是百姓误犯的。","notes":[]},{"n":27,"t":"「若有一个人误犯了罪，他就要献一岁的母山羊作赎罪祭。","notes":[]},{"n":28,"t":"那误行的人犯罪的时候，祭司要在耶和华面前为他赎罪，他就必蒙赦免。","notes":[]},{"n":29,"t":"以色列中的本地人和寄居在他们中间的外人，若误行了什么事，必归一样的条例。","notes":[]},{"n":30,"t":"但那擅敢行事的，无论是本地人是寄居的，他亵渎了耶和华，必从民中剪除。","notes":[]},{"n":31,"t":"因他藐视耶和华的言语，违背耶和华的命令，那人总要剪除；他的罪孽要归到他身上。」","notes":[]},{"n":32,"t":"以色列人在旷野的时候，遇见一个人在安息日捡柴。","notes":[],"heads":["违反安息日的人"]},{"n":33,"t":"遇见他捡柴的人，就把他带到摩西、亚伦并全会众那里，","notes":[]},{"n":34,"t":"将他收在监内；因为当怎样办他，还没有指明。","notes":[]},{"n":35,"t":"耶和华吩咐摩西说：「总要把那人治死；全会众要在营外用石头把他打死。」","notes":[]},{"n":36,"t":"于是全会众将他带到营外，用石头打死他，是照耶和华所吩咐摩西的。","notes":[]},{"n":37,"t":"耶和华晓谕摩西说：","notes":[],"heads":["有关衣服繸子的条例"]},{"n":38,"t":"「你吩咐以色列人，叫他们世世代代在衣服边上做繸子，又在底边的繸子上钉一根蓝细带子。","notes":[]},{"n":39,"t":"你们佩带这繸子，好叫你们看见就记念遵行耶和华一切的命令，不随从自己的心意、眼目行邪淫，像你们素常一样；","notes":[]},{"n":40,"t":"使你们记念遵行我一切的命令，成为圣洁，归与你们的神。","notes":[]},{"n":41,"t":"「我是耶和华—你们的神，曾把你们从埃及地领出来，要作你们的神。我是耶和华—你们的神。」","notes":[]}]},"16":{"heading":"可拉、大坍、亚比兰的叛变","verses":[{"n":1,"t":"利未的曾孙、哥辖的孙子、以斯哈的儿子可拉，和吕便子孙中以利押的儿子大坍、亚比兰，与比勒的儿子安，","notes":[]},{"n":2,"t":"并以色列会中的二百五十个首领，就是有名望选入会中的人，在摩西面前一同起来，","notes":[]},{"n":3,"t":"聚集攻击摩西、亚伦，说：「你们擅自专权！全会众个个既是圣洁，耶和华也在他们中间，你们为什么自高，超过耶和华的会众呢？」","notes":[]},{"n":4,"t":"摩西听见这话就俯伏在地，","notes":[]},{"n":5,"t":"对可拉和他一党的人说：「到了早晨，耶和华必指示谁是属他的，谁是圣洁的，就叫谁亲近他；他所拣选的是谁，必叫谁亲近他。","notes":[]},{"n":6,"t":"可拉啊，你们要这样行，你和你的一党要拿香炉来。","notes":[]},{"n":7,"t":"明日，在耶和华面前，把火盛在炉中，把香放在其上。耶和华拣选谁，谁就为圣洁。你们这利未的子孙擅自专权了！」","notes":[]},{"n":8,"t":"摩西又对可拉说：「利未的子孙哪，你们听我说！","notes":[]},{"n":9,"t":"以色列的神从以色列会中将你们分别出来，使你们亲近他，办耶和华帐幕的事，并站在会众面前替他们当差。","notes":[]},{"n":10,"t":"耶和华又使你和你一切弟兄—利未的子孙—一同亲近他，这岂为小事？你们还要求祭司的职任吗？","notes":[]},{"n":11,"t":"你和你一党的人聚集是要攻击耶和华。亚伦算什么，你们竟向他发怨言呢？」","notes":[]},{"n":12,"t":"摩西打发人去召以利押的儿子大坍、亚比兰。他们说：「我们不上去！","notes":[]},{"n":13,"t":"你将我们从流奶与蜜之地领上来，要在旷野杀我们，这岂为小事？你还要自立为王辖管我们吗？","notes":[]},{"n":14,"t":"并且你没有将我们领到流奶与蜜之地，也没有把田地和葡萄园给我们为业。难道你要剜这些人的眼睛吗？我们不上去！」","notes":[]},{"n":15,"t":"摩西就甚发怒，对耶和华说：「求你不要享受他们的供物。我并没有夺过他们一匹驴，也没有害过他们一个人。」","notes":[]},{"n":16,"t":"摩西对可拉说：「明天，你和你一党的人，并亚伦，都要站在耶和华面前；","notes":[]},{"n":17,"t":"各人要拿一个香炉，共二百五十个，把香放在上面，到耶和华面前。你和亚伦也各拿自己的香炉。」","notes":[]},{"n":18,"t":"于是他们各人拿一个香炉，盛上火，加上香，同摩西、亚伦站在会幕门前。","notes":[]},{"n":19,"t":"可拉招聚全会众到会幕门前，要攻击摩西、亚伦；耶和华的荣光就向全会众显现。","notes":[]},{"n":20,"t":"耶和华晓谕摩西、亚伦说：","notes":[]},{"n":21,"t":"「你们离开这会众，我好在转眼之间把他们灭绝。」","notes":[]},{"n":22,"t":"摩西、亚伦就俯伏在地，说：「神，万人之灵的神啊，一人犯罪，你就要向全会众发怒吗？」","notes":[]},{"n":23,"t":"耶和华晓谕摩西说：","notes":[]},{"n":24,"t":"「你吩咐会众说：『你们离开可拉、大坍、亚比兰帐棚的四围。』」","notes":[]},{"n":25,"t":"摩西起来，往大坍、亚比兰那里去；以色列的长老也随着他去。","notes":[]},{"n":26,"t":"他吩咐会众说：「你们离开这恶人的帐棚吧，他们的物件，什么都不可摸，恐怕你们陷在他们的罪中，与他们一同消灭。」","notes":[]},{"n":27,"t":"于是众人离开可拉、大坍、亚比兰帐棚的四围。大坍、亚比兰带着妻子、儿女、小孩子，都出来，站在自己的帐棚门口。","notes":[]},{"n":28,"t":"摩西说：「我行的这一切事本不是凭我自己心意行的，乃是耶和华打发我行的，必有证据使你们知道。","notes":[]},{"n":29,"t":"这些人死若与世人无异，或是他们所遭的与世人相同，就不是耶和华打发我来的。","notes":[]},{"n":30,"t":"倘若耶和华创作一件新事，使地开口，把他们和一切属他们的都吞下去，叫他们活活地坠落阴间，你们就明白这些人是藐视耶和华了。」","notes":[]},{"n":31,"t":"摩西刚说完了这一切话，他们脚下的地就开了口，","notes":[]},{"n":32,"t":"把他们和他们的家眷，并一切属可拉的人丁、财物，都吞下去。","notes":[]},{"n":33,"t":"这样，他们和一切属他们的，都活活地坠落阴间；地口在他们上头照旧合闭，他们就从会中灭亡。","notes":[]},{"n":34,"t":"在他们四围的以色列众人听他们呼号，就都逃跑，说：「恐怕地也把我们吞下去。」","notes":[]},{"n":35,"t":"又有火从耶和华那里出来，烧灭了那献香的二百五十个人。","notes":[]},{"n":36,"t":"耶和华晓谕摩西说：","notes":[],"heads":["香炉"]},{"n":37,"t":"「你吩咐祭司亚伦的儿子以利亚撒从火中捡起那些香炉来，把火撒在别处，因为那些香炉是圣的。","notes":[]},{"n":38,"t":"把那些犯罪、自害己命之人的香炉，叫人锤成片子，用以包坛。那些香炉本是他们在耶和华面前献过的，所以是圣的，并且可以给以色列人作记号。」","notes":[]},{"n":39,"t":"于是祭司以利亚撒将被烧之人所献的铜香炉拿来，人就锤出来，用以包坛，","notes":[]},{"n":40,"t":"给以色列人作纪念，使亚伦后裔之外的人不得近前来在耶和华面前烧香，免得他遭可拉和他一党所遭的。这乃是照耶和华借着摩西所吩咐的。","notes":[]},{"n":41,"t":"第二天，以色列全会众都向摩西、亚伦发怨言说：「你们杀了耶和华的百姓了。」","notes":[],"heads":["亚伦救了人民"]},{"n":42,"t":"会众聚集攻击摩西、亚伦的时候，向会幕观看，不料，有云彩遮盖了，耶和华的荣光显现。","notes":[]},{"n":43,"t":"摩西、亚伦就来到会幕前。","notes":[]},{"n":44,"t":"耶和华吩咐摩西说：","notes":[]},{"n":45,"t":"「你们离开这会众，我好在转眼之间把他们灭绝。」他们二人就俯伏于地。","notes":[]},{"n":46,"t":"摩西对亚伦说：「拿你的香炉，把坛上的火盛在其中，又加上香，快快带到会众那里，为他们赎罪；因为有忿怒从耶和华那里出来，瘟疫已经发作了。」","notes":[]},{"n":47,"t":"亚伦照着摩西所说的拿来，跑到会中，不料，瘟疫在百姓中已经发作了。他就加上香，为百姓赎罪。","notes":[]},{"n":48,"t":"他站在活人死人中间，瘟疫就止住了。","notes":[]},{"n":49,"t":"除了因可拉事情死的以外，遭瘟疫死的，共有一万四千七百人。","notes":[]},{"n":50,"t":"亚伦回到会幕门口，到摩西那里，瘟疫已经止住了。","notes":[]}]},"17":{"heading":"亚伦的杖","verses":[{"n":1,"t":"耶和华对摩西说：","notes":[]},{"n":2,"t":"「你晓谕以色列人，从他们手下取杖，每支派一根；从他们所有的首领，按着支派，共取十二根。你要将各人的名字写在各人的杖上，","notes":[]},{"n":3,"t":"并要将亚伦的名字写在利未的杖上，因为各族长必有一根杖。","notes":[]},{"n":4,"t":"你要把这些杖存在会幕内法柜前，就是我与你们相会之处。","notes":[]},{"n":5,"t":"后来我所拣选的那人，他的杖必发芽。这样，我必使以色列人向你们所发的怨言止息，不再达到我耳中。」","notes":[]},{"n":6,"t":"于是摩西晓谕以色列人，他们的首领就把杖交给他，按着支派，每首领一根，共有十二根；亚伦的杖也在其中。","notes":[]},{"n":7,"t":"摩西就把杖存在法柜的帐幕内，在耶和华面前。","notes":[]},{"n":8,"t":"第二天，摩西进法柜的帐幕去。谁知利未族亚伦的杖已经发了芽，生了花苞，开了花，结了熟杏。","notes":[]},{"n":9,"t":"摩西就把所有的杖从耶和华面前拿出来，给以色列众人看；他们看见了，各首领就把自己的杖拿去。","notes":[]},{"n":10,"t":"耶和华吩咐摩西说：「把亚伦的杖还放在法柜前，给这些背叛之子留作记号。这样，你就使他们向我发的怨言止息，免得他们死亡。」","notes":[]},{"n":11,"t":"摩西就这样行。耶和华怎样吩咐他，他就怎样行了。","notes":[]},{"n":12,"t":"以色列人对摩西说：「我们死啦！我们灭亡啦！都灭亡啦！","notes":[]},{"n":13,"t":"凡挨近耶和华帐幕的是必死的。我们都要死亡吗？」","notes":[]}]},"18":{"heading":"祭司和利未人的职责","verses":[{"n":1,"t":"耶和华对亚伦说：「你和你的儿子，并你本族的人，要一同担当干犯圣所的罪孽。你和你的儿子也要一同担当干犯祭司职任的罪孽。","notes":[]},{"n":2,"t":"你要带你弟兄利未人，就是你祖宗支派的人前来，使他们与你联合，服事你，只是你和你的儿子，要一同在法柜的帐幕前供职。","notes":[]},{"n":3,"t":"他们要守所吩咐你的，并守全帐幕，只是不可挨近圣所的器具和坛，免得他们和你们都死亡。","notes":[]},{"n":4,"t":"他们要与你联合，也要看守会幕，办理帐幕一切的事，只是外人不可挨近你们。","notes":[]},{"n":5,"t":"你们要看守圣所和坛，免得忿怒再临到以色列人。","notes":[]},{"n":6,"t":"我已将你们的弟兄利未人从以色列人中拣选出来归耶和华，是给你们为赏赐的，为要办理会幕的事。","notes":[]},{"n":7,"t":"你和你的儿子要为一切属坛和幔子内的事一同守祭司的职任。你们要这样供职；我将祭司的职任给你们当作赏赐事奉我。凡挨近的外人必被治死。」","notes":[]},{"n":8,"t":"耶和华晓谕亚伦说：「我已将归我的举祭，就是以色列人一切分别为圣的物，交给你经管；因你受过膏，把这些都赐给你和你的子孙，当作永得的分。","notes":[],"heads":["祭司当得之物"]},{"n":9,"t":"以色列人归给我至圣的供物，就是一切的素祭、赎罪祭、赎愆祭，其中所有存留不经火的，都为至圣之物，要归给你和你的子孙。","notes":[]},{"n":10,"t":"你要拿这些当至圣物吃；凡男丁都可以吃。你当以此物为圣。","notes":[]},{"n":11,"t":"以色列人所献的举祭并摇祭都是你的；我已赐给你和你的儿女，当作永得的分；凡在你家中的洁净人都可以吃。","notes":[]},{"n":12,"t":"凡油中、新酒中、五谷中至好的，就是以色列人所献给耶和华初熟之物，我都赐给你。","notes":[]},{"n":13,"t":"凡从他们地上所带来给耶和华初熟之物也都要归与你。你家中的洁净人都可以吃。","notes":[]},{"n":14,"t":"以色列中一切永献的都必归与你。","notes":[]},{"n":15,"t":"他们所有奉给耶和华的，连人带牲畜，凡头生的，都要归给你；只是人头生的，总要赎出来；不洁净牲畜头生的，也要赎出来。","notes":[]},{"n":16,"t":"其中在一月之外所当赎的，要照你所估定的价，按圣所的平，用银子五舍客勒赎出来（一舍客勒是二十季拉）。","notes":[]},{"n":17,"t":"只是头生的牛，或是头生的绵羊和山羊，必不可赎，都是圣的，要把它的血洒在坛上，把它的脂油焚烧，当作馨香的火祭献给耶和华。","notes":[]},{"n":18,"t":"它的肉必归你，像被摇的胸、被举的右腿归你一样。","notes":[]},{"n":19,"t":"凡以色列人所献给耶和华圣物中的举祭，我都赐给你和你的儿女，当作永得的分。这是给你和你的后裔、在耶和华面前作为永远的盐约。」","notes":["盐就是不废坏的意思"]},{"n":20,"t":"耶和华对亚伦说：「你在以色列人的境内不可有产业，在他们中间也不可有分。我就是你的分，是你的产业。」","notes":[]},{"n":21,"t":"「凡以色列中出产的十分之一，我已赐给利未的子孙为业；因他们所办的是会幕的事，所以赐给他们为酬他们的劳。","notes":[],"heads":["利未人的分"]},{"n":22,"t":"从今以后，以色列人不可挨近会幕，免得他们担罪而死。","notes":[]},{"n":23,"t":"惟独利未人要办会幕的事，担当罪孽；这要作你们世世代代永远的定例。他们在以色列人中不可有产业；","notes":[]},{"n":24,"t":"因为以色列人中出产的十分之一，就是献给耶和华为举祭的，我已赐给利未人为业。所以我对他们说：『在以色列人中不可有产业。』」","notes":[]},{"n":25,"t":"耶和华吩咐摩西说：","notes":[],"heads":["利未人的十分之一奉献"]},{"n":26,"t":"「你晓谕利未人说：你们从以色列人中所取的十分之一，就是我给你们为业的，要再从那十分之一中取十分之一作为举祭献给耶和华，","notes":[]},{"n":27,"t":"这举祭要算为你们场上的谷，又如满酒榨的酒。","notes":[]},{"n":28,"t":"这样，你们从以色列人中所得的十分之一也要作举祭献给耶和华，从这十分之一中，将所献给耶和华的举祭归给祭司亚伦。","notes":[]},{"n":29,"t":"奉给你们的一切礼物，要从其中将至好的，就是分别为圣的，献给耶和华为举祭。","notes":[]},{"n":30,"t":"所以你要对利未人说：你们从其中将至好的举起，这就算为你们场上的粮，又如酒榨的酒。","notes":[]},{"n":31,"t":"你们和你们家属随处可以吃；这原是你们的赏赐，是酬你们在会幕里办事的劳。","notes":[]},{"n":32,"t":"你们从其中将至好的举起，就不至因这物担罪。你们不可亵渎以色列人的圣物，免得死亡。」","notes":[]}]},"19":{"heading":"红母牛的灰","verses":[{"n":1,"t":"耶和华晓谕摩西、亚伦说：","notes":[]},{"n":2,"t":"「耶和华命定律法中的一条律例乃是这样说：你要吩咐以色列人，把一只没有残疾、未曾负轭、纯红的母牛牵到你这里来，","notes":[]},{"n":3,"t":"交给祭司以利亚撒；他必牵到营外，人就把牛宰在他面前。","notes":[]},{"n":4,"t":"祭司以利亚撒要用指头蘸这牛的血，向会幕前面弹七次。","notes":[]},{"n":5,"t":"人要在他眼前把这母牛焚烧；牛的皮、肉、血、粪都要焚烧。","notes":[]},{"n":6,"t":"祭司要把香柏木、牛膝草、朱红色线都丢在烧牛的火中。","notes":[]},{"n":7,"t":"祭司必不洁净到晚上，要洗衣服，用水洗身，然后可以进营。","notes":[]},{"n":8,"t":"烧牛的人必不洁净到晚上，也要洗衣服，用水洗身。","notes":[]},{"n":9,"t":"必有一个洁净的人收起母牛的灰，存在营外洁净的地方，为以色列会众调做除污秽的水。这本是除罪的。","notes":[]},{"n":10,"t":"收起母牛灰的人必不洁净到晚上，要洗衣服。这要给以色列人和寄居在他们中间的外人作为永远的定例。」","notes":[]},{"n":11,"t":"「摸了人死尸的，就必七天不洁净。","notes":[],"heads":["接触尸体不洁的条例"]},{"n":12,"t":"那人到第三天要用这除污秽的水洁净自己，第七天就洁净了。他若在第三天不洁净自己，第七天就不洁净了。","notes":[]},{"n":13,"t":"凡摸了人死尸、不洁净自己的，就玷污了耶和华的帐幕，这人必从以色列中剪除；因为那除污秽的水没有洒在他身上，他就为不洁净，污秽还在他身上。","notes":[]},{"n":14,"t":"「人死在帐棚里的条例乃是这样：凡进那帐棚的，和一切在帐棚里的，都必七天不洁净。","notes":[]},{"n":15,"t":"凡敞口的器皿，就是没有扎上盖的，也是不洁净。","notes":[]},{"n":16,"t":"无论何人在田野里摸了被刀杀的，或是尸首，或是人的骨头，或是坟墓，就要七天不洁净。","notes":[]},{"n":17,"t":"要为这不洁净的人拿些烧成的除罪灰放在器皿里，倒上活水。","notes":[]},{"n":18,"t":"必当有一个洁净的人拿牛膝草蘸在这水中，把水洒在帐棚上，和一切器皿并帐棚内的众人身上，又洒在摸了骨头，或摸了被杀的，或摸了自死的，或摸了坟墓的那人身上。","notes":[]},{"n":19,"t":"第三天和第七天，洁净的人要洒水在不洁净的人身上，第七天就使他成为洁净。那人要洗衣服，用水洗澡，到晚上就洁净了。","notes":[]},{"n":20,"t":"「但那污秽而不洁净自己的，要将他从会中剪除，因为他玷污了耶和华的圣所。除污秽的水没有洒在他身上，他是不洁净的。","notes":[]},{"n":21,"t":"这要给你们作为永远的定例。并且那洒除污秽水的人要洗衣服。凡摸除污秽水的，必不洁净到晚上。","notes":[]},{"n":22,"t":"不洁净人所摸的一切物就不洁净；摸了这物的人必不洁净到晚上。」","notes":[]}]},"20":{"heading":"在加低斯发生的事件","verses":[{"n":1,"t":"正月间，以色列全会众到了寻的旷野，就住在加低斯。米利暗死在那里，就葬在那里。","notes":[]},{"n":2,"t":"会众没有水喝，就聚集攻击摩西、亚伦。","notes":[]},{"n":3,"t":"百姓向摩西争闹说：「我们的弟兄曾死在耶和华面前，我们恨不得与他们同死。","notes":[]},{"n":4,"t":"你们为何把耶和华的会众领到这旷野、使我们和牲畜都死在这里呢？","notes":[]},{"n":5,"t":"你们为何逼着我们出埃及、领我们到这坏地方呢？这地方不好撒种，也没有无花果树、葡萄树、石榴树，又没有水喝。」","notes":[]},{"n":6,"t":"摩西、亚伦离开会众，到会幕门口，俯伏在地；耶和华的荣光向他们显现。","notes":[]},{"n":7,"t":"耶和华晓谕摩西说：","notes":[]},{"n":8,"t":"「你拿着杖去，和你的哥哥亚伦招聚会众，在他们眼前吩咐磐石发出水来，水就从磐石流出，给会众和他们的牲畜喝。」","notes":[]},{"n":9,"t":"于是摩西照耶和华所吩咐的，从耶和华面前取了杖去。","notes":[]},{"n":10,"t":"摩西、亚伦就招聚会众到磐石前。摩西说：「你们这些背叛的人听我说：我为你们使水从这磐石中流出来吗？」","notes":[]},{"n":11,"t":"摩西举手，用杖击打磐石两下，就有许多水流出来，会众和他们的牲畜都喝了。","notes":[]},{"n":12,"t":"耶和华对摩西、亚伦说：「因为你们不信我，不在以色列人眼前尊我为圣，所以你们必不得领这会众进我所赐给他们的地去。」","notes":[]},{"n":13,"t":"这水名叫米利巴水，是因以色列人向耶和华争闹，耶和华就在他们面前显为圣。","notes":["米利巴就是争闹的意思"]},{"n":14,"t":"摩西从加低斯差遣使者去见以东王，说：「你的弟兄以色列人这样说：『我们所遭遇的一切艰难，","notes":[],"heads":["以东王不容以色列人通行"]},{"n":15,"t":"就是我们的列祖下到埃及，我们在埃及久住；埃及人恶待我们的列祖和我们，","notes":[]},{"n":16,"t":"我们哀求耶和华的时候，他听了我们的声音，差遣使者把我们从埃及领出来。这事你都知道。如今，我们在你边界上的城加低斯。","notes":[]},{"n":17,"t":"求你容我们从你的地经过。我们不走田间和葡萄园，也不喝井里的水，只走大道，不偏左右，直到过了你的境界。』」","notes":["原文是王道"]},{"n":18,"t":"以东王说：「你不可从我的地经过，免得我带刀出去攻击你。」","notes":[]},{"n":19,"t":"以色列人说：「我们要走大道上去；我们和牲畜若喝你的水，必给你价值。不求别的，只求你容我们步行过去。」","notes":[]},{"n":20,"t":"以东王说：「你们不可经过！」就率领许多人出来，要用强硬的手攻击以色列人。","notes":[]},{"n":21,"t":"这样，以东王不肯容以色列人从他的境界过去。于是他们转去，离开他。","notes":[]},{"n":22,"t":"以色列全会众从加低斯起行，到了何珥山。","notes":[],"heads":["亚伦逝世"]},{"n":23,"t":"耶和华在附近以东边界的何珥山上晓谕摩西、亚伦说：","notes":[]},{"n":24,"t":"「亚伦要归到他列祖那里。他必不得入我所赐给以色列人的地；因为在米利巴水，你们违背了我的命。","notes":["原文是本民"]},{"n":25,"t":"你带亚伦和他的儿子以利亚撒上何珥山，","notes":[]},{"n":26,"t":"把亚伦的圣衣脱下来，给他的儿子以利亚撒穿上；亚伦必死在那里，归他列祖。」","notes":[]},{"n":27,"t":"摩西就照耶和华所吩咐的行。三人当着会众的眼前上了何珥山。","notes":[]},{"n":28,"t":"摩西把亚伦的圣衣脱下来，给他的儿子以利亚撒穿上，亚伦就死在山顶那里。于是摩西和以利亚撒下了山。","notes":[]},{"n":29,"t":"全会众，就是以色列全家，见亚伦已经死了，便都为亚伦哀哭了三十天。","notes":[]}]},"21":{"heading":"战胜迦南人","verses":[{"n":1,"t":"住南地的迦南人亚拉得王，听说以色列人从亚他林路来，就和以色列人争战，掳了他们几个人。","notes":[]},{"n":2,"t":"以色列人向耶和华发愿说：「你若将这民交付我手，我就把他们的城邑尽行毁灭。」","notes":[]},{"n":3,"t":"耶和华应允了以色列人，把迦南人交付他们，他们就把迦南人和迦南人的城邑尽行毁灭。那地方的名便叫何珥玛。","notes":["就是毁灭的意思"]},{"n":4,"t":"他们从何珥山起行，往红海那条路走，要绕过以东地。百姓因这路难行，心中甚是烦躁，","notes":[],"heads":["铜制的蛇"]},{"n":5,"t":"就怨讟神和摩西说：「你们为什么把我们从埃及领出来、使我们死在旷野呢？这里没有粮，没有水，我们的心厌恶这淡薄的食物。」","notes":[]},{"n":6,"t":"于是耶和华使火蛇进入百姓中间，蛇就咬他们。以色列人中死了许多。","notes":[]},{"n":7,"t":"百姓到摩西那里，说：「我们怨讟耶和华和你，有罪了。求你祷告耶和华，叫这些蛇离开我们。」于是摩西为百姓祷告。","notes":[]},{"n":8,"t":"耶和华对摩西说：「你制造一条火蛇，挂在杆子上；凡被咬的，一望这蛇，就必得活。」","notes":[]},{"n":9,"t":"摩西便制造一条铜蛇，挂在杆子上；凡被蛇咬的，一望这铜蛇就活了。","notes":[]},{"n":10,"t":"以色列人起行，安营在阿伯。","notes":[],"heads":["从何珥山到摩押谷"]},{"n":11,"t":"又从阿伯起行，安营在以耶·亚巴琳，与摩押相对的旷野，向日出之地。","notes":[]},{"n":12,"t":"从那里起行，安营在撒烈谷。","notes":[]},{"n":13,"t":"从那里起行，安营在亚嫩河那边。这亚嫩河是在旷野，从亚摩利的境界流出来的；原来亚嫩河是摩押的边界，在摩押和亚摩利人搭界的地方。","notes":[]},{"n":14,"t":"所以耶和华的战记上说：「苏法的哇哈伯与亚嫩河的谷，","notes":[]},{"n":15,"t":"并向亚珥城众谷的下坡，是靠近摩押的境界。」","notes":[]},{"n":16,"t":"以色列人从那里起行，到了比珥。从前耶和华吩咐摩西说：「招聚百姓，我好给他们水喝」，说的就是这井。","notes":["就是井的意思"]},{"n":17,"t":"当时，以色列人唱歌说：井啊，涌上水来！你们要向这井歌唱。","notes":[]},{"n":18,"t":"这井是首领和民中的尊贵人用圭用杖所挖所掘的。以色列人从旷野往玛他拿去，","notes":[]},{"n":19,"t":"从玛他拿到拿哈列，从拿哈列到巴末，","notes":[]},{"n":20,"t":"从巴末到摩押地的谷，又到那下望旷野之毗斯迦的山顶。","notes":[]},{"n":21,"t":"以色列人差遣使者去见亚摩利人的王西宏，说：","notes":[],"heads":["战胜亚摩利王和巴珊王"]},{"n":22,"t":"「求你容我们从你的地经过；我们不偏入田间和葡萄园，也不喝井里的水，只走大道，直到过了你的境界。」","notes":["原文是王道"]},{"n":23,"t":"西宏不容以色列人从他的境界经过，就招聚他的众民出到旷野，要攻击以色列人，到了雅杂与以色列人争战。","notes":[]},{"n":24,"t":"以色列人用刀杀了他，得了他的地，从亚嫩河到雅博河，直到亚扪人的境界，因为亚扪人的境界多有坚垒。","notes":[]},{"n":25,"t":"以色列人夺取这一切的城邑，也住亚摩利人的城邑，就是希实本与希实本的一切乡村。","notes":[]},{"n":26,"t":"这希实本是亚摩利王西宏的京城；西宏曾与摩押的先王争战，从他手中夺取了全地，直到亚嫩河。","notes":[]},{"n":27,"t":"所以那些作诗歌的说：你们来到希实本；愿西宏的城被修造，被建立。","notes":[]},{"n":28,"t":"因为有火从希实本发出，有火焰出于西宏的城，烧尽摩押的亚珥和亚嫩河邱坛的祭司 。","notes":["祭司原文是主"]},{"n":29,"t":"摩押啊，你有祸了！基抹的民哪，你们灭亡了！基抹的男子逃奔，女子被掳，交付亚摩利的王西宏。","notes":[]},{"n":30,"t":"我们射了他们；希实本直到底本尽皆毁灭。我们使地变成荒场，直到挪法；这挪法直延到米底巴。","notes":[]},{"n":31,"t":"这样，以色列人就住在亚摩利人之地。","notes":[]},{"n":32,"t":"摩西打发人去窥探雅谢，以色列人就占了雅谢的镇市，赶出那里的亚摩利人。","notes":[]},{"n":33,"t":"以色列人转回，向巴珊去。巴珊王噩和他的众民都出来，在以得来与他们交战。","notes":[]},{"n":34,"t":"耶和华对摩西说：「不要怕他！因我已将他和他的众民，并他的地，都交在你手中；你要待他像从前待住希实本的亚摩利王西宏一般。」","notes":[]},{"n":35,"t":"于是他们杀了他和他的众子，并他的众民，没有留下一个，就得了他的地。","notes":[]}]},"22":{"heading":"摩押王召巴兰","verses":[{"n":1,"t":"以色列人起行，在摩押平原、约旦河东，对着耶利哥安营。","notes":[]},{"n":2,"t":"以色列人向亚摩利人所行的一切事，西拨的儿子巴勒都看见了。","notes":[]},{"n":3,"t":"摩押人因以色列民甚多，就大大惧怕，心内忧急，","notes":[]},{"n":4,"t":"对米甸的长老说：「现在这众人要把我们四围所有的一概舔尽，就如牛舔尽田间的草一般。」那时西拨的儿子巴勒作摩押王。","notes":[]},{"n":5,"t":"他差遣使者往大河边的毗夺去，到比珥的儿子巴兰本乡那里，召巴兰来，说：「有一宗民从埃及出来，遮满地面，与我对居。","notes":[]},{"n":6,"t":"这民比我强盛，现在求你来为我咒诅他们，或者我能得胜，攻打他们，赶出此地。因为我知道，你为谁祝福，谁就得福；你咒诅谁，谁就受咒诅。」","notes":[]},{"n":7,"t":"摩押的长老和米甸的长老手里拿着卦金，到了巴兰那里，将巴勒的话都告诉了他。","notes":[]},{"n":8,"t":"巴兰说：「你们今夜在这里住宿，我必照耶和华所晓谕我的回报你们。」摩押的使臣就在巴兰那里住下了。","notes":[]},{"n":9,"t":"神临到巴兰那里，说：「在你这里的人都是谁？」","notes":[]},{"n":10,"t":"巴兰回答说：「是摩押王西拨的儿子巴勒打发人到我这里来，说：","notes":[]},{"n":11,"t":"『从埃及出来的民遮满地面，你来为我咒诅他们，或者我能与他们争战，把他们赶出去。』」","notes":[]},{"n":12,"t":"神对巴兰说：「你不可同他们去，也不可咒诅那民，因为那民是蒙福的。」","notes":[]},{"n":13,"t":"巴兰早晨起来，对巴勒的使臣说：「你们回本地去吧，因为耶和华不容我和你们同去。」","notes":[]},{"n":14,"t":"摩押的使臣就起来，回巴勒那里去，说：「巴兰不肯和我们同来。」","notes":[]},{"n":15,"t":"巴勒又差遣使臣，比先前的又多又尊贵。","notes":[]},{"n":16,"t":"他们到了巴兰那里，对他说：「西拨的儿子巴勒这样说：『求你不容什么事拦阻你不到我这里来，","notes":[]},{"n":17,"t":"因为我必使你得极大的尊荣。你向我要什么，我就给你什么；只求你来为我咒诅这民。』」","notes":[]},{"n":18,"t":"巴兰回答巴勒的臣仆说：「巴勒就是将他满屋的金银给我，我行大事小事也不得越过耶和华—我神的命。","notes":[]},{"n":19,"t":"现在我请你们今夜在这里住宿，等我得知耶和华还要对我说什么。」","notes":[]},{"n":20,"t":"当夜，神临到巴兰那里，说：「这些人若来召你，你就起来同他们去，你只要遵行我对你所说的话。」","notes":[]},{"n":21,"t":"巴兰早晨起来，备上驴，和摩押的使臣一同去了。","notes":[],"heads":["巴兰和他的驴"]},{"n":22,"t":"神因他去就发了怒；耶和华的使者站在路上敌挡他。他骑着驴，有两个仆人跟随他。","notes":[]},{"n":23,"t":"驴看见耶和华的使者站在路上，手里有拔出来的刀，就从路上跨进田间，巴兰便打驴，要叫它回转上路。","notes":[]},{"n":24,"t":"耶和华的使者就站在葡萄园的窄路上；这边有墙，那边也有墙。","notes":[]},{"n":25,"t":"驴看见耶和华的使者，就贴靠墙，将巴兰的脚挤伤了；巴兰又打驴。","notes":[]},{"n":26,"t":"耶和华的使者又往前去，站在狭窄之处，左右都没有转折的地方。","notes":[]},{"n":27,"t":"驴看见耶和华的使者，就卧在巴兰底下，巴兰发怒，用杖打驴。","notes":[]},{"n":28,"t":"耶和华叫驴开口，对巴兰说：「我向你行了什么，你竟打我这三次呢？」","notes":[]},{"n":29,"t":"巴兰对驴说：「因为你戏弄我，我恨不能手中有刀，把你杀了。」","notes":[]},{"n":30,"t":"驴对巴兰说：「我不是你从小时直到今日所骑的驴吗？我素常向你这样行过吗？」巴兰说：「没有。」","notes":[]},{"n":31,"t":"当时，耶和华使巴兰的眼目明亮，他就看见耶和华的使者站在路上，手里有拔出来的刀，巴兰便低头俯伏在地。","notes":[]},{"n":32,"t":"耶和华的使者对他说：「你为何这三次打你的驴呢？我出来敌挡你，因你所行的，在我面前偏僻。","notes":[]},{"n":33,"t":"驴看见我就三次从我面前偏过去；驴若没有偏过去，我早把你杀了，留它存活。」","notes":[]},{"n":34,"t":"巴兰对耶和华的使者说：「我有罪了。我不知道你站在路上阻挡我；你若不喜欢我去，我就转回。」","notes":[]},{"n":35,"t":"耶和华的使者对巴兰说：「你同这些人去吧！你只要说我对你说的话。」于是巴兰同着巴勒的使臣去了。","notes":[]},{"n":36,"t":"巴勒听见巴兰来了，就往摩押京城去迎接他；这城是在边界上，在亚嫩河旁。","notes":[],"heads":["巴勒欢迎巴兰"]},{"n":37,"t":"巴勒对巴兰说：「我不是急急地打发人到你那里去召你吗？你为何不到我这里来呢？我岂不能使你得尊荣吗？」","notes":[]},{"n":38,"t":"巴兰说：「我已经到你这里来了！现在我岂能擅自说什么呢？神将什么话传给我，我就说什么。」","notes":[]},{"n":39,"t":"巴兰和巴勒同行，来到基列·胡琐。","notes":[]},{"n":40,"t":"巴勒宰了牛羊，送给巴兰和陪伴的使臣。","notes":["原文是献"]},{"n":41,"t":"到了早晨，巴勒领巴兰到巴力的高处；巴兰从那里观看以色列营的边界。","notes":[],"heads":["巴兰首次预言"]}]},"23":{"heading":"巴兰第二次预言","verses":[{"n":1,"t":"巴兰对巴勒说：「你在这里给我筑七座坛，为我预备七只公牛，七只公羊。」","notes":[]},{"n":2,"t":"巴勒照巴兰的话行了。巴勒和巴兰在每座坛上献一只公牛，一只公羊。","notes":[]},{"n":3,"t":"巴兰对巴勒说：「你站在你的燔祭旁边，我且往前去，或者耶和华来迎见我。他指示我什么，我必告诉你。」于是巴兰上一净光的高处。","notes":[]},{"n":4,"t":"神迎见巴兰；巴兰说：「我预备了七座坛，在每座坛上献了一只公牛，一只公羊。」","notes":[]},{"n":5,"t":"耶和华将话传给巴兰，又说：「你回到巴勒那里，要如此如此说。」","notes":[]},{"n":6,"t":"他就回到巴勒那里，见他同摩押的使臣都站在燔祭旁边。","notes":[]},{"n":7,"t":"巴兰便题起诗歌说：巴勒引我出亚兰，摩押王引我出东山，说：来啊，为我咒诅雅各；来啊，怒骂以色列。","notes":[]},{"n":8,"t":"神没有咒诅的，我焉能咒诅？耶和华没有怒骂的，我焉能怒骂？","notes":[]},{"n":9,"t":"我从高峰看他，从小山望他；这是独居的民，不列在万民中。","notes":[]},{"n":10,"t":"谁能数点雅各的尘土？谁能计算以色列的四分之一？我愿如义人之死而死；我愿如义人之终而终。","notes":[]},{"n":11,"t":"巴勒对巴兰说：「你向我做的是什么事呢？我领你来咒诅我的仇敌，不料，你竟为他们祝福。」","notes":[]},{"n":12,"t":"他回答说：「耶和华传给我的话，我能不谨慎传说吗？」","notes":[]},{"n":13,"t":"巴勒说：「求你同我往别处去，在那里可以看见他们；你不能全看见，只能看见他们边界上的人。在那里要为我咒诅他们。」","notes":[]},{"n":14,"t":"于是领巴兰到了琐腓田，上了毗斯迦山顶，筑了七座坛；每座坛上献一只公牛，一只公羊。","notes":[]},{"n":15,"t":"巴兰对巴勒说：「你站在这燔祭旁边，等我往那边去迎见耶和华。」","notes":[]},{"n":16,"t":"耶和华临到巴兰那里，将话传给他；又说：「你回到巴勒那里，要如此如此说。」","notes":[]},{"n":17,"t":"他就回到巴勒那里，见他站在燔祭旁边；摩押的使臣也和他在一处。巴勒问他说：「耶和华说了什么话呢？」","notes":[]},{"n":18,"t":"巴兰就题诗歌说：巴勒，你起来听；西拨的儿子，你听我言。","notes":[]},{"n":19,"t":"神非人，必不致说谎，也非人子，必不致后悔。他说话岂不照着行呢？他发言岂不要成就呢？","notes":[]},{"n":20,"t":"我奉命祝福；神也曾赐福，此事我不能翻转。","notes":[]},{"n":21,"t":"他未见雅各中有罪孽，也未见以色列中有奸恶。耶和华—他的神和他同在；有欢呼王的声音在他们中间。","notes":[]},{"n":22,"t":"神领他们出埃及；他们似乎有野牛之力。","notes":[]},{"n":23,"t":"断没有法术可以害雅各，也没有占卜可以害以色列。现在必有人论及雅各，就是论及以色列说：神为他行了何等的大事！","notes":[]},{"n":24,"t":"这民起来，仿佛母狮，挺身，好像公狮，未曾吃野食，未曾喝被伤者之血，决不躺卧。","notes":[]},{"n":25,"t":"巴勒对巴兰说：「你一点不要咒诅他们，也不要为他们祝福。」","notes":[]},{"n":26,"t":"巴兰回答巴勒说：「我岂不是告诉你说『凡耶和华所说的，我必须遵行』吗？」","notes":[]},{"n":27,"t":"巴勒对巴兰说：「来吧，我领你往别处去，或者神喜欢你在那里为我咒诅他们。」","notes":[],"heads":["巴兰第三次预言"]},{"n":28,"t":"巴勒就领巴兰到那下望旷野的毗珥山顶上。","notes":[]},{"n":29,"t":"巴兰对巴勒说：「你在这里为我筑七座坛，又在这里为我预备七只公牛，七只公羊。」","notes":[]},{"n":30,"t":"巴勒就照巴兰的话行，在每座坛上献一只公牛，一只公羊。","notes":[]}]},"24":{"heading":"巴兰末次预言","verses":[{"n":1,"t":"巴兰见耶和华喜欢赐福与以色列，就不像前两次去求法术，却面向旷野。","notes":[]},{"n":2,"t":"巴兰举目，看见以色列人照着支派居住。神的灵就临到他身上，","notes":[]},{"n":3,"t":"他便题起诗歌说：比珥的儿子巴兰说，眼目闭住的人说，","notes":["或译：睁开"]},{"n":4,"t":"得听神的言语，得见全能者的异象，眼目睁开而仆倒的人说：","notes":[]},{"n":5,"t":"雅各啊，你的帐棚何等华美！以色列啊，你的帐幕何其华丽！","notes":[]},{"n":6,"t":"如接连的山谷，如河旁的园子，如耶和华所栽的沉香树，如水边的香柏木。","notes":[]},{"n":7,"t":"水要从他的桶里流出；种子要撒在多水之处。他的王必超过亚甲；他的国必要振兴。","notes":[]},{"n":8,"t":"神领他出埃及；他似乎有野牛之力。他要吞吃敌国，折断他们的骨头，用箭射透他们。","notes":[]},{"n":9,"t":"他蹲如公狮，卧如母狮，谁敢惹他？凡给你祝福的，愿他蒙福；凡咒诅你的，愿他受咒诅。","notes":[]},{"n":10,"t":"巴勒向巴兰生气，就拍起手来，对巴兰说：「我召你来为我咒诅仇敌，不料，你这三次竟为他们祝福。","notes":[]},{"n":11,"t":"如今你快回本地去吧！我想使你得大尊荣，耶和华却阻止你不得尊荣。」","notes":[]},{"n":12,"t":"巴兰对巴勒说：「我岂不是对你所差遣到我那里的使者说：","notes":[]},{"n":13,"t":"『巴勒就是将他满屋的金银给我，我也不得越过耶和华的命，凭自己的心意行好行歹。耶和华说什么，我就要说什么』？」","notes":[]},{"n":14,"t":"「现在我要回本族去。你来，我告诉你这民日后要怎样待你的民。」","notes":[]},{"n":15,"t":"他就题起诗歌说：比珥的儿子巴兰说：眼目闭住的人说，","notes":["或译：睁开"]},{"n":16,"t":"得听神的言语，明白至高者的意旨，看见全能者的异象，眼目睁开而仆倒的人说：","notes":[]},{"n":17,"t":"我看他却不在现时；我望他却不在近日。有星要出于雅各，有杖要兴于以色列，必打破摩押的四角，毁坏扰乱之子。","notes":[]},{"n":18,"t":"他必得以东为基业，又得仇敌之地西珥为产业；以色列必行事勇敢。","notes":[]},{"n":19,"t":"有一位出于雅各的，必掌大权；他要除灭城中的余民。","notes":[]},{"n":20,"t":"巴兰观看亚玛力，就题起诗歌说：亚玛力原为诸国之首，但他终必沉沦。","notes":[]},{"n":21,"t":"巴兰观看基尼人，就题起诗歌说：你的住处本是坚固；你的窝巢做在岩穴中。","notes":[]},{"n":22,"t":"然而基尼必至衰微，直到亚述把你掳去。","notes":[]},{"n":23,"t":"巴兰又题起诗歌说：哀哉！神行这事，谁能得活？","notes":[]},{"n":24,"t":"必有人乘船从基提界而来，苦害亚述，苦害希伯；他也必至沉沦。","notes":[]},{"n":25,"t":"于是巴兰起来，回他本地去；巴勒也回去了。","notes":[]}]},"25":{"heading":"以色列人在毗珥","verses":[{"n":1,"t":"以色列人住在什亭，百姓与摩押女子行起淫乱。","notes":[]},{"n":2,"t":"因为这女子叫百姓来，一同给她们的神献祭，百姓就吃她们的祭物，跪拜她们的神。","notes":[]},{"n":3,"t":"以色列人与巴力·毗珥连合，耶和华的怒气就向以色列人发作。","notes":[]},{"n":4,"t":"耶和华吩咐摩西说：「将百姓中所有的族长在我面前对着日头悬挂，使我向以色列人所发的怒气可以消了。」","notes":[]},{"n":5,"t":"于是摩西吩咐以色列的审判官说：「凡属你们的人，有与巴力·毗珥连合的，你们各人要把他们杀了。」","notes":[]},{"n":6,"t":"摩西和以色列全会众正在会幕门前哭泣的时候，谁知，有以色列中的一个人，当他们眼前，带着一个米甸女人到他弟兄那里去。","notes":[]},{"n":7,"t":"祭司亚伦的孙子，以利亚撒的儿子非尼哈看见了，就从会中起来，手里拿着枪，","notes":[]},{"n":8,"t":"跟随那以色列人进亭子里去，便将以色列人和那女人由腹中刺透。这样，在以色列人中瘟疫就止息了。","notes":[]},{"n":9,"t":"那时遭瘟疫死的，有二万四千人。","notes":[]},{"n":10,"t":"耶和华晓谕摩西说：","notes":[]},{"n":11,"t":"「祭司亚伦的孙子，以利亚撒的儿子非尼哈，使我向以色列人所发的怒消了；因他在他们中间，以我的忌邪为心，使我不在忌邪中把他们除灭。","notes":[]},{"n":12,"t":"因此，你要说：『我将我平安的约赐给他。","notes":[]},{"n":13,"t":"这约要给他和他的后裔，作为永远当祭司职任的约；因他为神有忌邪的心，为以色列人赎罪。』」","notes":[]},{"n":14,"t":"那与米甸女人一同被杀的以色列人，名叫心利，是撒路的儿子，是西缅一个宗族的首领。","notes":[]},{"n":15,"t":"那被杀的米甸女人，名叫哥斯比，是苏珥的女儿；这苏珥是米甸一个宗族的首领。","notes":[]},{"n":16,"t":"耶和华晓谕摩西说：","notes":[]},{"n":17,"t":"「你要扰害米甸人，击杀他们；","notes":[]},{"n":18,"t":"因为他们用诡计扰害你们，在毗珥的事上和他们的姊妹、米甸首领的女儿哥斯比的事上，用这诡计诱惑了你们；这哥斯比，当瘟疫流行的日子，因毗珥的事被杀了。」","notes":[]}]},"26":{"heading":"第二次的人口普查","verses":[{"n":1,"t":"瘟疫之后，耶和华晓谕摩西和祭司亚伦的儿子以利亚撒说：","notes":[]},{"n":2,"t":"「你们要将以色列全会众，按他们的宗族，凡以色列中从二十岁以外、能出去打仗的，计算总数。」","notes":[]},{"n":3,"t":"摩西和祭司以利亚撒在摩押平原与耶利哥相对的约旦河边向以色列人说：","notes":[]},{"n":4,"t":"「将你们中间从二十岁以外的计算总数」；是照耶和华吩咐出埃及地的摩西和以色列人的话。","notes":[]},{"n":5,"t":"以色列的长子是吕便。吕便的众子：属哈诺的，有哈诺族；属法路的，有法路族；","notes":[]},{"n":6,"t":"属希斯伦的，有希斯伦族；属迦米的，有迦米族；","notes":[]},{"n":7,"t":"这就是吕便的各族；其中被数的，共有四万三千七百三十名。","notes":[]},{"n":8,"t":"法路的儿子是以利押。","notes":[]},{"n":9,"t":"以利押的众子是尼母利、大坍、亚比兰。这大坍、亚比兰，就是从会中选召的，与可拉一党同向耶和华争闹的时候也向摩西、亚伦争闹；","notes":[]},{"n":10,"t":"地便开口吞了他们，和可拉、可拉的党类一同死亡。那时火烧灭了二百五十个人；他们就作了警戒。","notes":[]},{"n":11,"t":"然而可拉的众子没有死亡。","notes":[]},{"n":12,"t":"按着家族，西缅的众子：属尼母利的，有尼母利族；属雅悯的，有雅悯族；属雅斤的，有雅斤族；","notes":[]},{"n":13,"t":"属谢拉的，有谢拉族；属扫罗的，有扫罗族。","notes":[]},{"n":14,"t":"这就是西缅的各族，共有二万二千二百名。","notes":[]},{"n":15,"t":"按着家族，迦得的众子：属洗分的，有洗分族；属哈基的，有哈基族；属书尼的，有书尼族；","notes":[]},{"n":16,"t":"属阿斯尼的，有阿斯尼族；属以利的，有以利族；","notes":[]},{"n":17,"t":"属亚律的，有亚律族；属亚列利的，有亚列利族。","notes":[]},{"n":18,"t":"这就是迦得子孙的各族，照他们中间被数的，共有四万零五百名。","notes":[]},{"n":19,"t":"犹大的儿子是珥和俄南。这珥和俄南死在迦南地。","notes":[]},{"n":20,"t":"按着家族，犹大其余的众子：属示拉的，有示拉族；属法勒斯的，有法勒斯族；属谢拉的有谢拉族。","notes":[]},{"n":21,"t":"法勒斯的儿子：属希斯仑的，有希斯仑族；属哈母勒的，有哈母勒族。","notes":[]},{"n":22,"t":"这就是犹大的各族，照他们中间被数的，共有七万六千五百名。","notes":[]},{"n":23,"t":"按着家族，以萨迦的众子：属陀拉的，有陀拉族；属普瓦的，有普瓦族；","notes":[]},{"n":24,"t":"属雅述的，有雅述族；属伸仑的，有伸仑族。","notes":[]},{"n":25,"t":"这就是以萨迦的各族，照他们中间被数的，共有六万四千三百名。","notes":[]},{"n":26,"t":"按着家族，西布伦的众子：属西烈的，有西烈族；属以伦的，有以伦族；属雅利的，有雅利族。","notes":[]},{"n":27,"t":"这就是西布伦的各族，照他们中间被数的，共有六万零五百名。","notes":[]},{"n":28,"t":"按着家族，约瑟的儿子有玛拿西、以法莲。","notes":[]},{"n":29,"t":"玛拿西的众子：属玛吉的，有玛吉族；玛吉生基列；属基列的，有基列族。","notes":[]},{"n":30,"t":"基列的众子：属伊以谢的，有伊以谢族；属希勒的，有希勒族；","notes":[]},{"n":31,"t":"属亚斯烈的，有亚斯烈族；属示剑的，有示剑族；","notes":[]},{"n":32,"t":"属示米大的，有示米大族；属希弗的，有希弗族。","notes":[]},{"n":33,"t":"希弗的儿子：西罗非哈没儿子，只有女儿。西罗非哈女儿的名字就是玛拉、挪阿、曷拉、密迦、得撒。","notes":[]},{"n":34,"t":"这就是玛拿西的各族；他们中间被数的，共有五万二千七百名。","notes":[]},{"n":35,"t":"按着家族，以法莲的众子：属书提拉的，有书提拉族；属比结的，有比结族；属他罕的，有他罕族。","notes":[]},{"n":36,"t":"书提拉的众子：属以兰的，有以兰族。","notes":[]},{"n":37,"t":"这就是以法莲子孙的各族，照他们中间被数的，共有三万二千五百名。按着家族，这都是约瑟的子孙。","notes":[]},{"n":38,"t":"按着家族，便雅悯的众子：属比拉的，有比拉族；属亚实别的，有亚实别族；属亚希兰的，有亚希兰族；","notes":[]},{"n":39,"t":"属书反的，有书反族；属户反的，有户反族。","notes":[]},{"n":40,"t":"比拉的众子是亚勒、乃幔。属亚勒的，有亚勒族；属乃幔的，有乃幔族。","notes":[]},{"n":41,"t":"按着家族，这就是便雅悯的子孙，其中被数的，共有四万五千六百名。","notes":[]},{"n":42,"t":"按着家族，但的众子：属书含的，有书含族。按着家族，这就是但的各族。","notes":[]},{"n":43,"t":"照其中被数的，书含所有的各族，共有六万四千四百名。","notes":[]},{"n":44,"t":"按着家族，亚设的众子：属音拿的，有音拿族；属亦施韦的，有亦施韦族；属比利亚的，有比利亚族。","notes":[]},{"n":45,"t":"比利亚的众子：属希别的，有希别族；属玛结的，有玛结族。","notes":[]},{"n":46,"t":"亚设的女儿名叫西拉。","notes":[]},{"n":47,"t":"这就是亚设子孙的各族，照他们中间被数的，共有五万三千四百名。","notes":[]},{"n":48,"t":"按着家族，拿弗他利的众子：属雅薛的，有雅薛族；属沽尼的，有沽尼族；","notes":[]},{"n":49,"t":"属耶色的，有耶色族；属示冷的，有示冷族。","notes":[]},{"n":50,"t":"按着家族，这就是拿弗他利的各族；他们中间被数的，共有四万五千四百名。","notes":[]},{"n":51,"t":"以色列人中被数的，共有六十万零一千七百三十名。","notes":[]},{"n":52,"t":"耶和华晓谕摩西说：","notes":[]},{"n":53,"t":"「你要按着人名的数目将地分给这些人为业。","notes":[]},{"n":54,"t":"人多的，你要把产业多分给他们；人少的，你要把产业少分给他们；要照被数的人数，把产业分给各人。","notes":[]},{"n":55,"t":"虽是这样，还要拈阄分地。他们要按着祖宗各支派的名字承受为业。","notes":[]},{"n":56,"t":"要按着所拈的阄，看人数多，人数少，把产业分给他们。」","notes":[]},{"n":57,"t":"利未人，按着他们的各族被数的：属革顺的，有革顺族；属哥辖的，有哥辖族；属米拉利的，有米拉利族。","notes":[]},{"n":58,"t":"利未的各族有立尼族、希伯伦族、玛利族、母示族、可拉族。哥辖生暗兰。","notes":[]},{"n":59,"t":"暗兰的妻名叫约基别，是利未女子，生在埃及。她给暗兰生了亚伦、摩西，并他们的姊姊米利暗。","notes":[]},{"n":60,"t":"亚伦生拿答、亚比户、以利亚撒、以他玛。","notes":[]},{"n":61,"t":"拿答、亚比户在耶和华面前献凡火的时候就死了。","notes":[]},{"n":62,"t":"利未人中，凡一个月以外、被数的男丁，共有二万三千。他们本来没有数在以色列人中；因为在以色列人中，没有分给他们产业。","notes":[]},{"n":63,"t":"这些就是被摩西和祭司以利亚撒所数的；他们在摩押平原与耶利哥相对的约旦河边数点以色列人。","notes":[]},{"n":64,"t":"但被数的人中，没有一个是摩西和祭司亚伦从前在西奈的旷野所数的以色列人，","notes":[]},{"n":65,"t":"因为耶和华论到他们说：「他们必要死在旷野。」所以，除了耶孚尼的儿子迦勒和嫩的儿子约书亚以外，连一个人也没有存留。","notes":[]}]},"27":{"heading":"西罗非哈的女儿们","verses":[{"n":1,"t":"属约瑟的儿子玛拿西的各族，有玛拿西的玄孙，玛吉的曾孙，基列的孙子，希弗的儿子西罗非哈的女儿，名叫玛拉、挪阿、曷拉、密迦、得撒。她们前来，","notes":[]},{"n":2,"t":"站在会幕门口，在摩西和祭司以利亚撒，并众首领与全会众面前，说：","notes":[]},{"n":3,"t":"「我们的父亲死在旷野。他不与可拉同党聚集攻击耶和华，是在自己罪中死的；他也没有儿子。","notes":[]},{"n":4,"t":"为什么因我们的父亲没有儿子就把他的名从他族中除掉呢？求你们在我们父亲的弟兄中分给我们产业。」","notes":[]},{"n":5,"t":"于是，摩西将她们的案件呈到耶和华面前。","notes":[]},{"n":6,"t":"耶和华晓谕摩西说：","notes":[]},{"n":7,"t":"「西罗非哈的女儿说得有理。你定要在她们父亲的弟兄中，把地分给她们为业；要将她们父亲的产业归给她们。","notes":[]},{"n":8,"t":"你也要晓谕以色列人说：『人若死了没有儿子，就要把他的产业归给他的女儿。","notes":[]},{"n":9,"t":"他若没有女儿，就要把他的产业给他的弟兄。","notes":[]},{"n":10,"t":"他若没有弟兄，就要把他的产业给他父亲的弟兄。","notes":[]},{"n":11,"t":"他父亲若没有弟兄，就要把他的产业给他族中最近的亲属，他便要得为业。』这要作以色列人的律例典章，是照耶和华吩咐摩西的。」","notes":[]},{"n":12,"t":"耶和华对摩西说：「你上这亚巴琳山，观看我所赐给以色列人的地。","notes":[],"heads":["约书亚被选为摩西的继承人"]},{"n":13,"t":"看了以后，你也必归到你列祖那里，像你哥哥亚伦一样。","notes":["原文是本民"]},{"n":14,"t":"因为你们在寻的旷野，当会众争闹的时候，违背了我的命，没有在涌水之地、会众眼前尊我为圣。」（这水就是寻的旷野加低斯米利巴水。）","notes":[]},{"n":15,"t":"摩西对耶和华说：","notes":[]},{"n":16,"t":"「愿耶和华万人之灵的神，立一个人治理会众，","notes":[]},{"n":17,"t":"可以在他们面前出入，也可以引导他们，免得耶和华的会众如同没有牧人的羊群一般。」","notes":[]},{"n":18,"t":"耶和华对摩西说：「嫩的儿子约书亚是心中有圣灵的；你将他领来，按手在他头上，","notes":[]},{"n":19,"t":"使他站在祭司以利亚撒和全会众面前，嘱咐他，","notes":[]},{"n":20,"t":"又将你的尊荣给他几分，使以色列全会众都听从他。","notes":[]},{"n":21,"t":"他要站在祭司以利亚撒面前；以利亚撒要凭乌陵的判断，在耶和华面前为他求问。他和以色列全会众都要遵以利亚撒的命出入。」","notes":[]},{"n":22,"t":"于是摩西照耶和华所吩咐的将约书亚领来，使他站在祭司以利亚撒和全会众面前，","notes":[]},{"n":23,"t":"按手在他头上，嘱咐他，是照耶和华借摩西所说的话。","notes":[]}]},"28":{"heading":"每天例常的祭","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「你要吩咐以色列人说：『献给我的供物，就是献给我作馨香火祭的食物，你们要按日期献给我』；","notes":[]},{"n":3,"t":"又要对他们说：你们要献给耶和华的火祭，就是没有残疾、一岁的公羊羔，每日两只，作为常献的燔祭。","notes":[]},{"n":4,"t":"早晨要献一只，黄昏的时候要献一只；","notes":[]},{"n":5,"t":"又用细面伊法十分之一，并捣成的油一欣四分之一，调和作为素祭。","notes":[]},{"n":6,"t":"这是西奈山所命定为常献的燔祭，是献给耶和华为馨香的火祭。","notes":[]},{"n":7,"t":"为这一只羊羔，要同献奠祭的酒一欣四分之一。在圣所中，你要将醇酒奉给耶和华为奠祭。","notes":[]},{"n":8,"t":"晚上，你要献那一只羊羔，必照早晨的素祭和同献的奠祭献上，作为馨香的火祭，献给耶和华。」","notes":[]},{"n":9,"t":"「当安息日，要献两只没有残疾、一岁的公羊羔，并用调油的细面伊法十分之二为素祭，又将同献的奠祭献上。","notes":[],"heads":["安息日献的祭"]},{"n":10,"t":"这是每安息日献的燔祭；那常献的燔祭和同献的奠祭在外。」","notes":[]},{"n":11,"t":"「每月朔，你们要将两只公牛犊，一只公绵羊，七只没有残疾、一岁的公羊羔，献给耶和华为燔祭。","notes":[],"heads":["月初献的祭"]},{"n":12,"t":"每只公牛要用调油的细面伊法十分之三作为素祭；那只公羊也用调油的细面伊法十分之二作为素祭；","notes":[]},{"n":13,"t":"每只羊羔要用调油的细面伊法十分之一作为素祭和馨香的燔祭，是献给耶和华的火祭。","notes":[]},{"n":14,"t":"一只公牛要奠酒半欣，一只公羊要奠酒一欣三分之一，一只羊羔也奠酒一欣四分之一。这是每月的燔祭，一年之中要月月如此。","notes":[]},{"n":15,"t":"又要将一只公山羊为赎罪祭，献给耶和华；要献在常献的燔祭和同献的奠祭以外。」","notes":[]},{"n":16,"t":"「正月十四日是耶和华的逾越节。","notes":[],"heads":["除酵节献的祭"]},{"n":17,"t":"这月十五日是节期，要吃无酵饼七日。","notes":[]},{"n":18,"t":"第一日当有圣会；什么劳碌的工都不可做。","notes":[]},{"n":19,"t":"当将公牛犊两只，公绵羊一只，一岁的公羊羔七只，都要没有残疾的，用火献给耶和华为燔祭。","notes":[]},{"n":20,"t":"同献的素祭用调油的细面；为一只公牛要献伊法十分之三；为一只公羊要献伊法十分之二；","notes":[]},{"n":21,"t":"为那七只羊羔，每只要献伊法十分之一。","notes":[]},{"n":22,"t":"并献一只公山羊作赎罪祭，为你们赎罪。","notes":[]},{"n":23,"t":"你们献这些，要在早晨常献的燔祭以外。","notes":[]},{"n":24,"t":"一连七日，每日要照这例把馨香火祭的食物献给耶和华，是在常献的燔祭和同献的奠祭以外。","notes":[]},{"n":25,"t":"第七日当有圣会，什么劳碌的工都不可做。」","notes":[]},{"n":26,"t":"「七七节庄稼初熟，你们献新素祭给耶和华的日子，当有圣会；什么劳碌的工都不可做。","notes":[],"heads":["七七收获节献的祭"]},{"n":27,"t":"只要将公牛犊两只，公绵羊一只，一岁的公羊羔七只，作为馨香的燔祭献给耶和华。","notes":[]},{"n":28,"t":"同献的素祭用调油的细面；为每只公牛要献伊法十分之三；为一只公羊要献伊法十分之二；","notes":[]},{"n":29,"t":"为那七只羊羔，每只要献伊法十分之一。","notes":[]},{"n":30,"t":"并献一只公山羊为你们赎罪。","notes":[]},{"n":31,"t":"这些，你们要献在常献的燔祭和同献的素祭并同献的奠祭以外，都要没有残疾的。」","notes":[]}]},"29":{"heading":"新年献的祭","verses":[{"n":1,"t":"「七月初一日，你们当有圣会；什么劳碌的工都不可做，是你们当守为吹角的日子。","notes":[]},{"n":2,"t":"你们要将公牛犊一只，公绵羊一只，没有残疾、一岁的公羊羔七只，作为馨香的燔祭献给耶和华。","notes":[]},{"n":3,"t":"同献的素祭用调油的细面；为一只公牛要献伊法十分之三；为一只公羊要献伊法十分之二；","notes":[]},{"n":4,"t":"为那七只羊羔，每只要献伊法十分之一。","notes":[]},{"n":5,"t":"又献一只公山羊作赎罪祭，为你们赎罪。","notes":[]},{"n":6,"t":"这些是在月朔的燔祭和同献的素祭，并常献的燔祭与同献的素祭，以及照例同献的奠祭以外，都作为馨香的火祭献给耶和华。」","notes":[]},{"n":7,"t":"「七月初十日，你们当有圣会；要刻苦己心，什么工都不可做。","notes":[],"heads":["赎罪日献的祭"]},{"n":8,"t":"只要将公牛犊一只，公绵羊一只，一岁的公羊羔七只，都要没有残疾的，作为馨香的燔祭献给耶和华。","notes":[]},{"n":9,"t":"同献的素祭用调油的细面：为一只公牛要献伊法十分之三；为一只公羊要献伊法十分之二；","notes":[]},{"n":10,"t":"为那七只羊羔，每只要献伊法十分之一。","notes":[]},{"n":11,"t":"又献一只公山羊为赎罪祭。这是在赎罪祭和常献的燔祭，与同献的素祭并同献的奠祭以外。」","notes":[]},{"n":12,"t":"「七月十五日，你们当有圣会；什么劳碌的工都不可做，要向耶和华守节七日。","notes":[],"heads":["住棚节献的祭"]},{"n":13,"t":"又要将公牛犊十三只，公绵羊两只，一岁的公羊羔十四只，都要没有残疾的，用火献给耶和华为馨香的燔祭。","notes":[]},{"n":14,"t":"同献的素祭用调油的细面；为那十三只公牛，每只要献伊法十分之三；为那两只公羊，每只要献伊法十分之二；","notes":[]},{"n":15,"t":"为那十四只羊羔，每只要献伊法十分之一。","notes":[]},{"n":16,"t":"并献一只公山羊为赎罪祭，这是在常献的燔祭和同献的素祭并同献的奠祭以外。","notes":[]},{"n":17,"t":"「第二日要献公牛犊十二只，公绵羊两只，没有残疾、一岁的公羊羔十四只；","notes":[]},{"n":18,"t":"并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。","notes":[]},{"n":19,"t":"又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。","notes":[]},{"n":20,"t":"「第三日要献公牛十一只，公羊两只，没有残疾、一岁的公羊羔十四只；","notes":[]},{"n":21,"t":"并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。","notes":[]},{"n":22,"t":"又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。","notes":[]},{"n":23,"t":"「第四日要献公牛十只，公羊两只，没有残疾、一岁的公羊羔十四只；","notes":[]},{"n":24,"t":"并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。","notes":[]},{"n":25,"t":"又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。","notes":[]},{"n":26,"t":"「第五日要献公牛九只，公羊两只，没有残疾、一岁的公羊羔十四只；","notes":[]},{"n":27,"t":"并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。","notes":[]},{"n":28,"t":"又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。","notes":[]},{"n":29,"t":"「第六日要献公牛八只，公羊两只，没有残疾、一岁的公羊羔十四只；","notes":[]},{"n":30,"t":"并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。","notes":[]},{"n":31,"t":"又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。","notes":[]},{"n":32,"t":"「第七日要献公牛七只，公羊两只，没有残疾、一岁的公羊羔十四只；","notes":[]},{"n":33,"t":"并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。","notes":[]},{"n":34,"t":"又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。","notes":[]},{"n":35,"t":"「第八日你们当有严肃会；什么劳碌的工都不可做；","notes":[]},{"n":36,"t":"只要将公牛一只，公羊一只，没有残疾、一岁的公羊羔七只作火祭，献给耶和华为馨香的燔祭；","notes":[]},{"n":37,"t":"并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。","notes":[]},{"n":38,"t":"又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。","notes":[]},{"n":39,"t":"「这些祭要在你们的节期献给耶和华，都在所许的愿并甘心所献的以外，作为你们的燔祭、素祭、奠祭，和平安祭。」","notes":[]},{"n":40,"t":"于是，摩西照耶和华所吩咐他的一切话告诉以色列人。","notes":[]}]},"30":{"heading":"许愿的条例","verses":[{"n":1,"t":"摩西晓谕以色列各支派的首领说：「耶和华所吩咐的乃是这样：","notes":[]},{"n":2,"t":"人若向耶和华许愿或起誓，要约束自己，就不可食言，必要按口中所出的一切话行。","notes":[]},{"n":3,"t":"女子年幼、还在父家的时候，若向耶和华许愿，要约束自己，","notes":[]},{"n":4,"t":"她父亲也听见她所许的愿并约束自己的话，却向她默默不言，她所许的愿并约束自己的话就都要为定。","notes":[]},{"n":5,"t":"但她父亲听见的日子若不应承她所许的愿和约束自己的话，就都不得为定；耶和华也必赦免她，因为她父亲不应承。","notes":[]},{"n":6,"t":"她若出了嫁，有愿在身，或是口中出了约束自己的冒失话，","notes":[]},{"n":7,"t":"她丈夫听见的日子，却向她默默不言，她所许的愿并约束自己的话就都要为定。","notes":[]},{"n":8,"t":"但她丈夫听见的日子，若不应承，就算废了她所许的愿和她出口约束自己的冒失话；耶和华也必赦免她。","notes":[]},{"n":9,"t":"寡妇或是被休的妇人所许的愿，就是她约束自己的话，都要为定。","notes":[]},{"n":10,"t":"她若在丈夫家里许了愿或起了誓，约束自己，","notes":[]},{"n":11,"t":"丈夫听见，却向她默默不言，也没有不应承，她所许的愿并约束自己的话就都要为定。","notes":[]},{"n":12,"t":"丈夫听见的日子，若把这两样全废了，妇人口中所许的愿或是约束自己的话就都不得为定，因她丈夫已经把这两样废了；耶和华也必赦免她。","notes":[]},{"n":13,"t":"凡她所许的愿和刻苦约束自己所起的誓，她丈夫可以坚定，也可以废去。","notes":[]},{"n":14,"t":"倘若她丈夫天天向她默默不言，就算是坚定她所许的愿和约束自己的话；因丈夫听见的日子向她默默不言，就使这两样坚定。","notes":[]},{"n":15,"t":"但她丈夫听见以后，若使这两样全废了，就要担当妇人的罪孽。」","notes":[]},{"n":16,"t":"这是丈夫待妻子，父亲待女儿，女儿年幼、还在父家，耶和华所吩咐摩西的律例。","notes":[]}]},"31":{"heading":"跟米甸人打仗","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"「你要在米甸人身上报以色列人的仇，后来要归到你列祖那里。」","notes":["原文是本民"]},{"n":3,"t":"摩西吩咐百姓说：「要从你们中间叫人带兵器出去攻击米甸，好在米甸人身上为耶和华报仇。","notes":[]},{"n":4,"t":"从以色列众支派中，每支派要打发一千人去打仗。」","notes":[]},{"n":5,"t":"于是从以色列千万人中，每支派交出一千人，共一万二千人，带着兵器预备打仗。","notes":[]},{"n":6,"t":"摩西就打发每支派的一千人去打仗，并打发祭司以利亚撒的儿子非尼哈同去；非尼哈手里拿着圣所的器皿和吹大声的号筒。","notes":[]},{"n":7,"t":"他们就照耶和华所吩咐摩西的，与米甸人打仗，杀了所有的男丁。","notes":[]},{"n":8,"t":"在所杀的人中，杀了米甸的五王，就是以未、利金、苏珥、户珥、利巴，又用刀杀了比珥的儿子巴兰。","notes":[]},{"n":9,"t":"以色列人掳了米甸人的妇女孩子，并将他们的牲畜、羊群，和所有的财物都夺了来，当作掳物，","notes":[]},{"n":10,"t":"又用火焚烧他们所住的城邑和所有的营寨，","notes":[]},{"n":11,"t":"把一切所夺的、所掳的，连人带牲畜都带了去，","notes":[]},{"n":12,"t":"将所掳的人，所夺的牲畜、财物，都带到摩押平原，在约旦河边与耶利哥相对的营盘，交给摩西和祭司以利亚撒，并以色列的会众。","notes":[]},{"n":13,"t":"摩西和祭司以利亚撒，并会众一切的首领，都出到营外迎接他们。","notes":[],"heads":["打仗回来"]},{"n":14,"t":"摩西向打仗回来的军长，就是千夫长、百夫长，发怒，","notes":[]},{"n":15,"t":"对他们说：「你们要存留这一切妇女的活命吗？","notes":[]},{"n":16,"t":"这些妇女因巴兰的计谋，叫以色列人在毗珥的事上得罪耶和华，以致耶和华的会众遭遇瘟疫。","notes":[]},{"n":17,"t":"所以，你们要把一切的男孩和所有已嫁的女子都杀了。","notes":[]},{"n":18,"t":"但女孩子中，凡没有出嫁的，你们都可以存留她的活命。","notes":[]},{"n":19,"t":"你们要在营外驻扎七日；凡杀了人的，和一切摸了被杀的，并你们所掳来的人口，第三日，第七日，都要洁净自己，","notes":[]},{"n":20,"t":"也要因一切的衣服、皮物、山羊毛织的物，和各样的木器，洁净自己。」","notes":[]},{"n":21,"t":"祭司以利亚撒对打仗回来的兵丁说：「耶和华所吩咐摩西律法中的条例乃是这样：","notes":[]},{"n":22,"t":"金、银、铜、铁、锡、铅，","notes":[]},{"n":23,"t":"凡能见火的，你们要叫它经火就为洁净，然而还要用除污秽的水洁净它；凡不能见火的，你们要叫它过水。","notes":[]},{"n":24,"t":"第七日，你们要洗衣服，就为洁净，然后可以进营。」","notes":[]},{"n":25,"t":"耶和华晓谕摩西说：","notes":[],"heads":["分战利品"]},{"n":26,"t":"「你和祭司以利亚撒，并会众的各族长，要计算所掳来的人口和牲畜的总数。","notes":[]},{"n":27,"t":"把所掳来的分作两半：一半归与出去打仗的精兵，一半归与全会众。","notes":[]},{"n":28,"t":"又要从出去打仗所得的人口、牛、驴、羊群中，每五百取一，作为贡物奉给耶和华。","notes":[]},{"n":29,"t":"从他们一半之中，要取出来交给祭司以利亚撒，作为耶和华的举祭。","notes":[]},{"n":30,"t":"从以色列人的一半之中，就是从人口、牛、驴、羊群、各样牲畜中，每五十取一，交给看守耶和华帐幕的利未人。」","notes":[]},{"n":31,"t":"于是摩西和祭司以利亚撒照耶和华所吩咐摩西的行了。","notes":[]},{"n":32,"t":"除了兵丁所夺的财物以外，所掳来的：羊六十七万五千只；","notes":[]},{"n":33,"t":"牛七万二千只；","notes":[]},{"n":34,"t":"驴六万一千匹；","notes":[]},{"n":35,"t":"女人共三万二千口，都是没有出嫁的。","notes":[]},{"n":36,"t":"出去打仗之人的分，就是他们所得的那一半，共计羊三十三万七千五百只，","notes":[]},{"n":37,"t":"从其中归耶和华为贡物的，有六百七十五只；","notes":[]},{"n":38,"t":"牛三万六千只，从其中归耶和华为贡物的，有七十二只；","notes":[]},{"n":39,"t":"驴三万零五百匹，从其中归耶和华为贡物的，有六十一匹；","notes":[]},{"n":40,"t":"人一万六千口，从其中归耶和华的，有三十二口。","notes":[]},{"n":41,"t":"摩西把贡物，就是归与耶和华的举祭，交给祭司以利亚撒，是照耶和华所吩咐摩西的。","notes":[]},{"n":42,"t":"以色列人所得的那一半，就是摩西从打仗的人取来分给他们的。（","notes":[]},{"n":43,"t":"会众的那一半有：羊三十三万七千五百只；","notes":[]},{"n":44,"t":"牛三万六千只；","notes":[]},{"n":45,"t":"驴三万零五百匹；","notes":[]},{"n":46,"t":"人一万六千口。）","notes":[]},{"n":47,"t":"无论是人口是牲畜，摩西每五十取一，交给看守耶和华帐幕的利未人，是照耶和华所吩咐摩西的。","notes":[]},{"n":48,"t":"带领千军的各军长，就是千夫长、百夫长，都近前来见摩西，","notes":[]},{"n":49,"t":"对他说：「仆人权下的兵已经计算总数，并不短少一人。","notes":[]},{"n":50,"t":"如今我们将各人所得的金器，就是脚链子、镯子、打印的戒指、耳环、手钏，都送来为耶和华的供物，好在耶和华面前为我们的生命赎罪。」","notes":[]},{"n":51,"t":"摩西和祭司以利亚撒就收了他们的金子，都是打成的器皿。","notes":[]},{"n":52,"t":"千夫长、百夫长所献给耶和华为举祭的金子共有一万六千七百五十舍客勒。","notes":[]},{"n":53,"t":"各兵丁都为自己夺了财物。","notes":[]},{"n":54,"t":"摩西和祭司以利亚撒收了千夫长、百夫长的金子，就带进会幕，在耶和华面前作为以色列人的纪念。","notes":[]}]},"32":{"heading":"约旦河东的两支派","verses":[{"n":1,"t":"吕便子孙和迦得子孙的牲畜极其众多；他们看见雅谢地和基列地是可牧放牲畜之地，","notes":[]},{"n":2,"t":"就来见摩西和祭司以利亚撒，并会众的首领，说：","notes":[]},{"n":3,"t":"「亚大录、底本、雅谢、宁拉、希实本、以利亚利、示班、尼波、比稳，","notes":[]},{"n":4,"t":"就是耶和华在以色列会众前面所攻取之地，是可牧放牲畜之地，你仆人也有牲畜」；","notes":[]},{"n":5,"t":"又说：「我们若在你眼前蒙恩，求你把这地给我们为业，不要领我们过约旦河。」","notes":[]},{"n":6,"t":"摩西对迦得子孙和吕便子孙说：「难道你们的弟兄去打仗，你们竟坐在这里吗？","notes":[]},{"n":7,"t":"你们为何使以色列人灰心丧胆、不过去进入耶和华所赐给他们的那地呢？","notes":[]},{"n":8,"t":"我先前从加低斯·巴尼亚打发你们先祖去窥探那地，他们也是这样行。","notes":[]},{"n":9,"t":"他们上以实各谷，去窥探那地回来的时候，使以色列人灰心丧胆，不进入耶和华所赐给他们的地。","notes":[]},{"n":10,"t":"当日，耶和华的怒气发作，就起誓说：","notes":[]},{"n":11,"t":"『凡从埃及上来、二十岁以外的人断不得看见我对亚伯拉罕、以撒、雅各起誓应许之地，因为他们没有专心跟从我。","notes":[]},{"n":12,"t":"惟有基尼洗族耶孚尼的儿子迦勒和嫩的儿子约书亚可以看见，因为他们专心跟从我。』","notes":[]},{"n":13,"t":"耶和华的怒气向以色列人发作，使他们在旷野飘流四十年，等到在耶和华眼前行恶的那一代人都消灭了。","notes":[]},{"n":14,"t":"谁知，你们起来接续先祖，增添罪人的数目，使耶和华向以色列大发烈怒。","notes":[]},{"n":15,"t":"你们若退后不跟从他，他还要把以色列人撇在旷野，便是你们使这众民灭亡。」","notes":[]},{"n":16,"t":"两支派的人挨近摩西，说：「我们要在这里为牲畜垒圈，为妇人孩子造城。","notes":[]},{"n":17,"t":"我们自己要带兵器行在以色列人的前头，好把他们领到他们的地方；但我们的妇人孩子，因这地居民的缘故，要住在坚固的城内。","notes":[]},{"n":18,"t":"我们不回家，直等到以色列人各承受自己的产业。","notes":[]},{"n":19,"t":"我们不和他们在约旦河那边一带之地同受产业，因为我们的产业是坐落在约旦河东边这里。」","notes":[]},{"n":20,"t":"摩西对他们说：「你们若这样行，在耶和华面前带着兵器出去打仗，","notes":[]},{"n":21,"t":"所有带兵器的人都要在耶和华面前过约旦河，等他赶出他的仇敌，","notes":[]},{"n":22,"t":"那地被耶和华制伏了，然后你们可以回来，向耶和华和以色列才为无罪，这地也必在耶和华面前归你们为业。","notes":[]},{"n":23,"t":"倘若你们不这样行，就得罪耶和华，要知道你们的罪必追上你们。","notes":[]},{"n":24,"t":"如今你们口中所出的，只管去行，为你们的妇人孩子造城，为你们的羊群垒圈。」","notes":[]},{"n":25,"t":"迦得子孙和吕便子孙对摩西说：「仆人要照我主所吩咐的去行。","notes":[]},{"n":26,"t":"我们的妻子、孩子、羊群，和所有的牲畜都要留在基列的各城。","notes":[]},{"n":27,"t":"但你的仆人，凡带兵器的，都要照我主所说的话，在耶和华面前过去打仗。」","notes":[]},{"n":28,"t":"于是，摩西为他们嘱咐祭司以利亚撒和嫩的儿子约书亚，并以色列众支派的族长，说：","notes":[]},{"n":29,"t":"「迦得子孙和吕便子孙，凡带兵器在耶和华面前去打仗的，若与你们一同过约旦河，那地被你们制伏了，你们就要把基列地给他们为业。","notes":[]},{"n":30,"t":"倘若他们不带兵器和你们一同过去，就要在迦南地你们中间得产业。」","notes":[]},{"n":31,"t":"迦得子孙和吕便子孙回答说：「耶和华怎样吩咐仆人，仆人就怎样行。","notes":[]},{"n":32,"t":"我们要带兵器，在耶和华面前过去，进入迦南地，只是约旦河这边、我们所得为业之地仍归我们。」","notes":[]},{"n":33,"t":"摩西将亚摩利王西宏的国和巴珊王噩的国，连那地和周围的城邑，都给了迦得子孙和吕便子孙，并约瑟的儿子玛拿西半个支派。","notes":[]},{"n":34,"t":"迦得子孙建造底本、亚他录、亚罗珥、","notes":[]},{"n":35,"t":"亚他录·朔反、雅谢、约比哈、","notes":[]},{"n":36,"t":"伯·宁拉、伯·哈兰，都是坚固城。他们又垒羊圈。","notes":[]},{"n":37,"t":"吕便子孙建造希实本、以利亚利、基列亭、","notes":[]},{"n":38,"t":"尼波、巴力·免、西比玛（尼波、巴力·免，名字是改了的），又给他们所建造的城另起别名。","notes":[]},{"n":39,"t":"玛拿西的儿子玛吉，他的子孙往基列去，占了那地，赶出那里的亚摩利人。","notes":[]},{"n":40,"t":"摩西将基列赐给玛拿西的儿子玛吉，他子孙就住在那里。","notes":[]},{"n":41,"t":"玛拿西的子孙睚珥去占了基列的村庄，就称这些村庄为哈倭特·睚珥。","notes":[]},{"n":42,"t":"挪巴去占了基纳和基纳的乡村，就按自己的名称基纳为挪巴。","notes":[]}]},"33":{"heading":"从埃及到摩押","verses":[{"n":1,"t":"以色列人按着军队，在摩西、亚伦的手下出埃及地所行的路程记在下面。","notes":["或译：站口；下同"]},{"n":2,"t":"摩西遵着耶和华的吩咐记载他们所行的路程，其路程乃是这样：","notes":[]},{"n":3,"t":"正月十五日，就是逾越节的次日，以色列人从兰塞起行，在一切埃及人眼前昂然无惧地出去。","notes":[]},{"n":4,"t":"那时，埃及人正葬埋他们的长子，就是耶和华在他们中间所击杀的；耶和华也败坏他们的神。","notes":[]},{"n":5,"t":"以色列人从兰塞起行，安营在疏割。","notes":[]},{"n":6,"t":"从疏割起行，安营在旷野边的以倘。","notes":[]},{"n":7,"t":"从以倘起行，转到比哈·希录，是在巴力·洗分对面，就在密夺安营。","notes":[]},{"n":8,"t":"从比哈·希录对面起行，经过海中到了书珥旷野，又在伊坦的旷野走了三天的路程，就安营在玛拉。","notes":[]},{"n":9,"t":"从玛拉起行，来到以琳（以琳有十二股水泉，七十棵棕树），就在那里安营。","notes":[]},{"n":10,"t":"从以琳起行，安营在红海边。","notes":[]},{"n":11,"t":"从红海边起行，安营在汛的旷野。","notes":[]},{"n":12,"t":"从汛的旷野起行，安营在脱加。","notes":[]},{"n":13,"t":"从脱加起行，安营在亚录。","notes":[]},{"n":14,"t":"从亚录起行，安营在利非订；在那里，百姓没有水喝。","notes":[]},{"n":15,"t":"从利非订起行，安营在西奈的旷野。","notes":[]},{"n":16,"t":"从西奈的旷野起行，安营在基博罗·哈他瓦。","notes":[]},{"n":17,"t":"从基博罗·哈他瓦起行，安营在哈洗录。","notes":[]},{"n":18,"t":"从哈洗录起行，安营在利提玛。","notes":[]},{"n":19,"t":"从利提玛起行，安营在临门·帕烈。","notes":[]},{"n":20,"t":"从临门·帕烈起行，安营在立拿。","notes":[]},{"n":21,"t":"从立拿起行，安营在勒撒。","notes":[]},{"n":22,"t":"从勒撒起行，安营在基希拉他。","notes":[]},{"n":23,"t":"从基希拉他起行，安营在沙斐山。","notes":[]},{"n":24,"t":"从沙斐山起行，安营在哈拉大。","notes":[]},{"n":25,"t":"从哈拉大起行，安营在玛吉希录。","notes":[]},{"n":26,"t":"从玛吉希录起行，安营在他哈。","notes":[]},{"n":27,"t":"从他哈起行，安营在他拉。","notes":[]},{"n":28,"t":"从他拉起行，安营在密加。","notes":[]},{"n":29,"t":"从密加起行，安营在哈摩拿。","notes":[]},{"n":30,"t":"从哈摩拿起行，安营在摩西录。","notes":[]},{"n":31,"t":"从摩西录起行，安营在比尼·亚干。","notes":[]},{"n":32,"t":"从比尼·亚干起行，安营在曷·哈及甲。","notes":[]},{"n":33,"t":"从曷·哈及甲起行，安营在约巴他。","notes":[]},{"n":34,"t":"从约巴他起行，安营在阿博拿。","notes":[]},{"n":35,"t":"从阿博拿起行，安营在以旬·迦别。","notes":[]},{"n":36,"t":"从以旬·迦别起行，安营在寻的旷野，就是加低斯。","notes":[]},{"n":37,"t":"从加低斯起行，安营在何珥山，以东地的边界。","notes":[]},{"n":38,"t":"以色列人出了埃及地后四十年，五月初一日，祭司亚伦遵着耶和华的吩咐上何珥山，就死在那里。","notes":[]},{"n":39,"t":"亚伦死在何珥山的时候年一百二十三岁。","notes":[]},{"n":40,"t":"住在迦南南地的迦南人亚拉得王听说以色列人来了。","notes":[]},{"n":41,"t":"以色列人从何珥山起行，安营在撒摩拿。","notes":[]},{"n":42,"t":"从撒摩拿起行，安营在普嫩。","notes":[]},{"n":43,"t":"从普嫩起行，安营在阿伯。","notes":[]},{"n":44,"t":"从阿伯起行，安营在以耶·亚巴琳，摩押的边界。","notes":[]},{"n":45,"t":"从以耶·亚巴琳起行，安营在底本·迦得。","notes":[]},{"n":46,"t":"从底本·迦得起行，安营在亚门·低比拉太音。","notes":[]},{"n":47,"t":"从亚门·低比拉太音起行，安营在尼波对面的亚巴琳山里。","notes":[]},{"n":48,"t":"从亚巴琳山起行，安营在摩押平原—约旦河边、耶利哥对面。","notes":[]},{"n":49,"t":"他们在摩押平原沿约旦河边安营，从伯·耶施末直到亚伯·什亭。","notes":[]},{"n":50,"t":"耶和华在摩押平原—约旦河边、耶利哥对面晓谕摩西说：","notes":[],"heads":["过约旦河前的指示"]},{"n":51,"t":"「你吩咐以色列人说：你们过约旦河进迦南地的时候，","notes":[]},{"n":52,"t":"就要从你们面前赶出那里所有的居民，毁灭他们一切錾成的石像和他们一切铸成的偶像，又拆毁他们一切的邱坛。","notes":[]},{"n":53,"t":"你们要夺那地，住在其中，因我把那地赐给你们为业。","notes":[]},{"n":54,"t":"你们要按家室拈阄，承受那地；人多的，要把产业多分给他们；人少的，要把产业少分给他们。拈出何地给何人，就要归何人。你们要按宗族的支派承受。","notes":[]},{"n":55,"t":"倘若你们不赶出那地的居民，所容留的居民就必作你们眼中的刺，肋下的荆棘，也必在你们所住的地上扰害你们。","notes":[]},{"n":56,"t":"而且我素常有意怎样待他们，也必照样待你们。」","notes":[]}]},"34":{"heading":"迦南地的境界","verses":[{"n":1,"t":"耶和华晓谕摩西说：","notes":[]},{"n":2,"t":"「你吩咐以色列人说：你们到了迦南地，就是归你们为业的迦南四境之地，","notes":[]},{"n":3,"t":"南角要从寻的旷野，贴着以东的边界；南界要从盐海东头起，","notes":[]},{"n":4,"t":"绕到亚克拉滨坡的南边，接连到寻，直通到加低斯·巴尼亚的南边，又通到哈萨·亚达，接连到押们，","notes":[]},{"n":5,"t":"从押们转到埃及小河，直通到海为止。","notes":[]},{"n":6,"t":"「西边要以大海为界；这就是你们的西界。","notes":[]},{"n":7,"t":"「北界要从大海起，划到何珥山，","notes":[]},{"n":8,"t":"从何珥山划到哈马口，通到西达达，","notes":[]},{"n":9,"t":"又通到西斐仑，直到哈萨·以难。这要作你们的北界。","notes":[]},{"n":10,"t":"「你们要从哈萨·以难划到示番为东界。","notes":[]},{"n":11,"t":"这界要从示番下到亚延东边的利比拉，又要达到基尼烈湖的东边。","notes":[]},{"n":12,"t":"这界要下到约旦河，通到盐海为止。这四围的边界以内，要作你们的地。」","notes":[]},{"n":13,"t":"摩西吩咐以色列人说：「这地就是耶和华吩咐拈阄给九个半支派承受为业的；","notes":[]},{"n":14,"t":"因为吕便支派和迦得支派按着宗族受了产业，玛拿西半个支派也受了产业。","notes":[]},{"n":15,"t":"这两个半支派已经在耶利哥对面、约旦河东、向日出之地受了产业。」","notes":[]},{"n":16,"t":"耶和华晓谕摩西说：","notes":[],"heads":["各支派首领负责分地"]},{"n":17,"t":"「要给你们分地为业之人的名字是祭司以利亚撒和嫩的儿子约书亚。","notes":[]},{"n":18,"t":"又要从每支派中选一个首领帮助他们。","notes":[]},{"n":19,"t":"这些人的名字：犹大支派有耶孚尼的儿子迦勒。","notes":[]},{"n":20,"t":"西缅支派有亚米忽的儿子示母利。","notes":[]},{"n":21,"t":"便雅悯支派有基斯伦的儿子以利达。","notes":[]},{"n":22,"t":"但支派有一个首领，约利的儿子布基。","notes":[]},{"n":23,"t":"约瑟的子孙玛拿西支派有一个首领，以弗的儿子汉聂。","notes":[]},{"n":24,"t":"以法莲支派有一个首领，拾弗但的儿子基母利。","notes":[]},{"n":25,"t":"西布伦支派有一个首领，帕纳的儿子以利撒番。","notes":[]},{"n":26,"t":"以萨迦支派有一个首领，阿散的儿子帕铁。","notes":[]},{"n":27,"t":"亚设支派有一个首领，示罗米的儿子亚希忽。","notes":[]},{"n":28,"t":"拿弗他利支派有一个首领，亚米忽的儿子比大黑。」","notes":[]},{"n":29,"t":"这些人就是耶和华所吩咐、在迦南地把产业分给以色列人的。","notes":[]}]},"35":{"heading":"分给利未人的城邑","verses":[{"n":1,"t":"耶和华在摩押平原—约旦河边、耶利哥对面晓谕摩西说：","notes":[]},{"n":2,"t":"「你吩咐以色列人，要从所得为业的地中把些城给利未人居住，也要把这城四围的郊野给利未人。","notes":[]},{"n":3,"t":"这城邑要归他们居住，城邑的郊野可以牧养他们的牛羊和各样的牲畜，又可以安置他们的财物。","notes":[]},{"n":4,"t":"你们给利未人的郊野，要从城根起，四围往外量一千肘。","notes":[]},{"n":5,"t":"另外东量二千肘，南量二千肘，西量二千肘，北量二千肘，为边界，城在当中；这要归他们作城邑的郊野。","notes":[]},{"n":6,"t":"你们给利未人的城邑，其中当有六座逃城，使误杀人的可以逃到那里。此外还要给他们四十二座城。","notes":[]},{"n":7,"t":"你们要给利未人的城，共有四十八座，连城带郊野都要给他们。","notes":[]},{"n":8,"t":"以色列人所得的地业从中要把些城邑给利未人；人多的就多给，人少的就少给；各支派要按所承受为业之地把城邑给利未人。」","notes":[]},{"n":9,"t":"耶和华晓谕摩西说：","notes":[],"heads":["逃城"]},{"n":10,"t":"「你吩咐以色列人说：你们过约旦河，进了迦南地，","notes":[]},{"n":11,"t":"就要分出几座城，为你们作逃城，使误杀人的可以逃到那里。","notes":[]},{"n":12,"t":"这些城可以作逃避报仇人的城，使误杀人的不至于死，等他站在会众面前听审判。","notes":[]},{"n":13,"t":"你们所分出来的城，要作六座逃城。","notes":[]},{"n":14,"t":"在约旦河东要分出三座城，在迦南地也要分出三座城，都作逃城。","notes":[]},{"n":15,"t":"这六座城要给以色列人和他们中间的外人，并寄居的，作为逃城，使误杀人的都可以逃到那里。","notes":[]},{"n":16,"t":"「倘若人用铁器打人，以致打死，他就是故杀人的；故杀人的必被治死。","notes":[]},{"n":17,"t":"若用可以打死人的石头打死了人，他就是故杀人的；故杀人的必被治死。","notes":[]},{"n":18,"t":"若用可以打死人的木器打死了人，他就是故杀人的；故杀人的必被治死。","notes":[]},{"n":19,"t":"报血仇的必亲自杀那故杀人的，一遇见就杀他。","notes":[]},{"n":20,"t":"人若因怨恨把人推倒，或是埋伏往人身上扔物，以致于死，","notes":[]},{"n":21,"t":"或是因仇恨用手打人，以致于死，那打人的必被治死。他是故杀人的；报血仇的一遇见就杀他。","notes":[]},{"n":22,"t":"「倘若人没有仇恨，忽然将人推倒，或是没有埋伏把物扔在人身上，","notes":[]},{"n":23,"t":"或是没有看见的时候用可以打死人的石头扔在人身上，以致于死，本来与他无仇，也无意害他。","notes":[]},{"n":24,"t":"会众就要照典章，在打死人的和报血仇的中间审判。","notes":[]},{"n":25,"t":"会众要救这误杀人的脱离报血仇人的手，也要使他归入逃城。他要住在其中，直等到受圣膏的大祭司死了。","notes":[]},{"n":26,"t":"但误杀人的，无论什么时候，若出了逃城的境外，","notes":[]},{"n":27,"t":"报血仇的在逃城境外遇见他，将他杀了，报血仇的就没有流血之罪。","notes":[]},{"n":28,"t":"因为误杀人的该住在逃城里，等到大祭司死了。大祭司死了以后，误杀人的才可以回到他所得为业之地。","notes":[]},{"n":29,"t":"这在你们一切的住处，要作你们世世代代的律例典章。","notes":[]},{"n":30,"t":"「无论谁故杀人，要凭几个见证人的口把那故杀人的杀了，只是不可凭一个见证的口叫人死。","notes":[]},{"n":31,"t":"故杀人、犯死罪的，你们不可收赎价代替他的命；他必被治死。","notes":[]},{"n":32,"t":"那逃到逃城的人，你们不可为他收赎价，使他在大祭司未死以先再来住在本地。","notes":[]},{"n":33,"t":"这样，你们就不污秽所住之地，因为血是污秽地的；若有在地上流人血的，非流那杀人者的血，那地就不得洁净。","notes":["原文是赎"]},{"n":34,"t":"你们不可玷污所住之地，就是我住在其中之地，因为我—耶和华住在以色列人中间。」","notes":[]}]},"36":{"heading":"承业女子结婚的条例","verses":[{"n":1,"t":"约瑟的后裔，玛拿西的孙子，玛吉的儿子基列，他子孙中的诸族长来到摩西和作首领的以色列人族长面前，说：","notes":[]},{"n":2,"t":"「耶和华曾吩咐我主拈阄分地给以色列人为业，我主也受了耶和华的吩咐将我们兄弟西罗非哈的产业分给他的众女儿。","notes":[]},{"n":3,"t":"她们若嫁以色列别支派的人，就必将我们祖宗所遗留的产业加在她们丈夫支派的产业中。这样，我们拈阄所得的产业就要减少了。","notes":[]},{"n":4,"t":"到了以色列人的禧年，这女儿的产业就必加在她们丈夫支派的产业上。这样，我们祖宗支派的产业就减少了。」","notes":[]},{"n":5,"t":"摩西照耶和华的话吩咐以色列人说：「约瑟支派的人说得有理。","notes":[]},{"n":6,"t":"论到西罗非哈的众女儿，耶和华这样吩咐说：她们可以随意嫁人，只是要嫁同宗支派的人。","notes":[]},{"n":7,"t":"这样，以色列人的产业就不从这支派归到那支派，因为以色列人要各守各祖宗支派的产业。","notes":[]},{"n":8,"t":"凡在以色列支派中得了产业的女子必作同宗支派人的妻，好叫以色列人各自承受他祖宗的产业。","notes":[]},{"n":9,"t":"这样，他们的产业就不从这支派归到那支派，因为以色列支派的人要各守各的产业。」","notes":[]},{"n":10,"t":"耶和华怎样吩咐摩西，西罗非哈的众女儿就怎样行。","notes":[]},{"n":11,"t":"西罗非哈的女儿玛拉、得撒、曷拉、密迦、挪阿都嫁了他们伯叔的儿子。","notes":[]},{"n":12,"t":"她们嫁入约瑟儿子、玛拿西子孙的族中；她们的产业仍留在同宗支派中。","notes":[]},{"n":13,"t":"这是耶和华在摩押平原—约旦河边、耶利哥对面—借着摩西所吩咐以色列人的命令典章。","notes":[]}]}},"DEU":{"1":{"heading":"摩西回忆","verses":[{"n":1,"t":"以下所记的是摩西在约旦河东的旷野、疏弗对面的亚拉巴—就是巴兰、陀弗、拉班、哈洗录、底撒哈中间—向以色列众人所说的话。（","notes":[]},{"n":2,"t":"从何烈山经过西珥山到加低斯·巴尼亚有十一天的路程。）","notes":[]},{"n":3,"t":"出埃及第四十年十一月初一日，摩西照耶和华借着他所吩咐以色列人的话都晓谕他们。","notes":[]},{"n":4,"t":"那时，他已经击杀了住希实本的亚摩利王西宏和住以得来、亚斯他录的巴珊王噩。","notes":[]},{"n":5,"t":"摩西在约旦河东的摩押地讲律法说：","notes":[]},{"n":6,"t":"「耶和华—我们的神在何烈山晓谕我们说：你们在这山上住的日子够了；","notes":[]},{"n":7,"t":"要起行转到亚摩利人的山地和靠近这山地的各处，就是亚拉巴、山地、高原、南地，沿海一带迦南人的地，并黎巴嫩山又到幼发拉底大河。","notes":[]},{"n":8,"t":"如今我将这地摆在你们面前；你们要进去得这地，就是耶和华向你们列祖亚伯拉罕、以撒、雅各起誓应许赐给他们和他们后裔为业之地。」","notes":[]},{"n":9,"t":"「那时，我对你们说：『管理你们的重任，我独自担当不起。","notes":[],"heads":["摩西指派审判官"]},{"n":10,"t":"耶和华—你们的神使你们多起来。看哪，你们今日像天上的星那样多。","notes":[]},{"n":11,"t":"惟愿耶和华—你们列祖的神使你们比如今更多千倍，照他所应许你们的话赐福与你们。","notes":[]},{"n":12,"t":"但你们的麻烦，和管理你们的重任，并你们的争讼，我独自一人怎能担当得起呢？","notes":[]},{"n":13,"t":"你们要按着各支派选举有智慧、有见识、为众人所认识的，我立他们为你们的首领。』","notes":[]},{"n":14,"t":"你们回答我说：『照你所说的行了为妙。』","notes":[]},{"n":15,"t":"我便将你们各支派的首领，有智慧、为众人所认识的，照你们的支派，立他们为官长、千夫长、百夫长、五十夫长、十夫长，管理你们。","notes":[]},{"n":16,"t":"「当时，我嘱咐你们的审判官说：『你们听讼，无论是弟兄彼此争讼，是与同居的外人争讼，都要按公义判断。","notes":[]},{"n":17,"t":"审判的时候，不可看人的外貌；听讼不可分贵贱，不可惧怕人，因为审判是属乎神的。若有难断的案件，可以呈到我这里，我就判断。』","notes":[]},{"n":18,"t":"那时，我将你们所当行的事都吩咐你们了。」","notes":[]},{"n":19,"t":"「我们照着耶和华—我们神所吩咐的从何烈山起行，经过你们所看见那大而可怕的旷野，往亚摩利人的山地去，到了加低斯·巴尼亚。","notes":[],"heads":["从加低斯·巴尼亚派探子侦察"]},{"n":20,"t":"我对你们说：『你们已经到了耶和华—我们神所赐给我们的亚摩利人之山地。","notes":[]},{"n":21,"t":"看哪，耶和华—你的神已将那地摆在你面前，你要照耶和华—你列祖的神所说的上去得那地为业；不要惧怕，也不要惊惶。』","notes":[]},{"n":22,"t":"你们都就近我来说：『我们要先打发人去，为我们窥探那地，将我们上去该走何道，必进何城，都回报我们。』","notes":[]},{"n":23,"t":"这话我以为美，就从你们中间选了十二个人，每支派一人。","notes":[]},{"n":24,"t":"于是他们起身上山地去，到以实各谷，窥探那地。","notes":[]},{"n":25,"t":"他们手里拿着那地的果子下来，到我们那里，回报说：『耶和华—我们的神所赐给我们的是美地。』","notes":[]},{"n":26,"t":"「你们却不肯上去，竟违背了耶和华—你们神的命令，","notes":[]},{"n":27,"t":"在帐棚内发怨言说：『耶和华因为恨我们，所以将我们从埃及地领出来，要交在亚摩利人手中，除灭我们。","notes":[]},{"n":28,"t":"我们上哪里去呢？我们的弟兄使我们的心消化，说那地的民比我们又大又高，城邑又广大又坚固，高得顶天，并且我们在那里看见亚衲族的人。』","notes":[]},{"n":29,"t":"我就对你们说：『不要惊恐，也不要怕他们。","notes":[]},{"n":30,"t":"在你们前面行的耶和华—你们的神必为你们争战，正如他在埃及和旷野，在你们眼前所行的一样。","notes":[]},{"n":31,"t":"你们在旷野所行的路上，也曾见耶和华—你们的神抚养你们，如同人抚养儿子一般，直等你们来到这地方。』","notes":[]},{"n":32,"t":"你们在这事上却不信耶和华—你们的神。","notes":[]},{"n":33,"t":"他在路上，在你们前面行，为你们找安营的地方；夜间在火柱里，日间在云柱里，指示你们所当行的路。」","notes":[]},{"n":34,"t":"「耶和华听见你们这话，就发怒，起誓说：","notes":[],"heads":["耶和华刑罚以色列人"]},{"n":35,"t":"『这恶世代的人，连一个也不得见我起誓应许赐给你们列祖的美地；","notes":[]},{"n":36,"t":"惟有耶孚尼的儿子迦勒必得看见，并且我要将他所踏过的地赐给他和他的子孙，因为他专心跟从我。』","notes":[]},{"n":37,"t":"耶和华为你的缘故也向我发怒，说：『你必不得进入那地。","notes":[]},{"n":38,"t":"伺候你、嫩的儿子约书亚，他必得进入那地；你要勉励他，因为他要使以色列人承受那地为业。","notes":[]},{"n":39,"t":"并且你们的妇人孩子，就是你们所说、必被掳掠的，和今日不知善恶的儿女，必进入那地。我要将那地赐给他们，他们必得为业。","notes":[]},{"n":40,"t":"至于你们，要转回，从红海的路往旷野去。』","notes":[]},{"n":41,"t":"「那时，你们回答我说：『我们得罪了耶和华，情愿照耶和华—我们神一切所吩咐的上去争战。』于是你们各人带着兵器，争先上山地去了。","notes":[]},{"n":42,"t":"耶和华吩咐我说：『你对他们说：不要上去，也不要争战；因我不在你们中间，恐怕你们被仇敌杀败了。』","notes":[]},{"n":43,"t":"我就告诉了你们，你们却不听从，竟违背耶和华的命令，擅自上山地去了。","notes":[]},{"n":44,"t":"住那山地的亚摩利人就出来攻击你们，追赶你们，如蜂拥一般，在西珥杀退你们，直到何珥玛。","notes":[]},{"n":45,"t":"你们便回来，在耶和华面前哭号；耶和华却不听你们的声音，也不向你们侧耳。","notes":[]},{"n":46,"t":"于是你们在加低斯住了许多日子。」","notes":[]}]},"2":{"heading":"多年在旷野","verses":[{"n":1,"t":"「此后，我们转回，从红海的路往旷野去，是照耶和华所吩咐我的。我们在西珥山绕行了许多日子。","notes":[]},{"n":2,"t":"耶和华对我说：","notes":[]},{"n":3,"t":"『你们绕行这山的日子够了，要转向北去。","notes":[]},{"n":4,"t":"你吩咐百姓说：你们弟兄以扫的子孙住在西珥，你们要经过他们的境界。他们必惧怕你们，所以你们要分外谨慎。","notes":[]},{"n":5,"t":"不可与他们争战；他们的地，连脚掌可踏之处，我都不给你们，因我已将西珥山赐给以扫为业。","notes":[]},{"n":6,"t":"你们要用钱向他们买粮吃，也要用钱向他们买水喝。","notes":[]},{"n":7,"t":"因为耶和华—你的神在你手里所办的一切事上已赐福与你。你走这大旷野，他都知道了。这四十年，耶和华—你的神常与你同在，故此你一无所缺。』","notes":[]},{"n":8,"t":"「于是，我们离了我们弟兄以扫子孙所住的西珥，从亚拉巴的路，经过以拉他、以旬·迦别，转向摩押旷野的路去。","notes":[]},{"n":9,"t":"耶和华吩咐我说：『不可扰害摩押人，也不可与他们争战。他们的地，我不赐给你为业，因我已将亚珥赐给罗得的子孙为业。』","notes":[]},{"n":10,"t":"先前，有以米人住在那里，民数众多，身体高大，像亚衲人一样。","notes":[]},{"n":11,"t":"这以米人像亚衲人；也算为利乏音人；摩押人称他们为以米人。","notes":[]},{"n":12,"t":"先前，何利人也住在西珥，但以扫的子孙将他们除灭，得了他们的地，接着居住，就如以色列在耶和华赐给他为业之地所行的一样。","notes":[]},{"n":13,"t":"现在，起来过撒烈溪！于是我们过了撒烈溪。","notes":[]},{"n":14,"t":"自从离开加低斯·巴尼亚，到过了撒烈溪的时候，共有三十八年，等那世代的兵丁都从营中灭尽，正如耶和华向他们所起的誓。","notes":[]},{"n":15,"t":"耶和华的手也攻击他们，将他们从营中除灭，直到灭尽。","notes":[]},{"n":16,"t":"「兵丁从民中都灭尽死亡以后，","notes":[]},{"n":17,"t":"耶和华吩咐我说：","notes":[]},{"n":18,"t":"『你今天要从摩押的境界亚珥经过，","notes":[]},{"n":19,"t":"走近亚扪人之地，不可扰害他们，也不可与他们争战。亚扪人的地，我不赐给你们为业，因我已将那地赐给罗得的子孙为业。』","notes":[]},{"n":20,"t":"那地也算为利乏音人之地，先前利乏音人住在那里，亚扪人称他们为散送冥。","notes":[]},{"n":21,"t":"那民众多，身体高大，像亚衲人一样，但耶和华从亚扪人面前除灭他们，亚扪人就得了他们的地，接着居住。","notes":[]},{"n":22,"t":"正如耶和华从前为住西珥的以扫子孙将何利人从他们面前除灭、他们得了何利人的地、接着居住一样，直到今日。","notes":[]},{"n":23,"t":"从迦斐托出来的迦斐托人将先前住在乡村直到迦萨的亚卫人除灭，接着居住。","notes":[]},{"n":24,"t":"你们起来前往，过亚嫩谷；我已将亚摩利人希实本王西宏和他的地交在你手中，你要与他争战，得他的地为业。","notes":[]},{"n":25,"t":"从今日起，我要使天下万民听见你的名声都惊恐惧怕，且因你发颤伤恸。」","notes":[]},{"n":26,"t":"「我从基底莫的旷野差遣使者去见希实本王西宏，用和睦的话说：","notes":[],"heads":["击败希实本王西宏"]},{"n":27,"t":"『求你容我从你的地经过，只走大道，不偏左右。","notes":[]},{"n":28,"t":"你可以卖粮给我吃，也可以卖水给我喝，只要容我步行过去，","notes":[]},{"n":29,"t":"就如住西珥的以扫子孙和住亚珥的摩押人待我一样，等我过了约旦河，好进入耶和华—我们神所赐给我们的地。』","notes":[]},{"n":30,"t":"但希实本王西宏不容我们从他那里经过；因为耶和华—你的神使他心中刚硬，性情顽梗，为要将他交在你手中，像今日一样。","notes":[]},{"n":31,"t":"耶和华对我说：『从此起首，我要将西宏和他的地交给你；你要得他的地为业。』","notes":[]},{"n":32,"t":"那时，西宏和他的众民出来攻击我们，在雅杂与我们交战。","notes":[]},{"n":33,"t":"耶和华—我们的神将他交给我们，我们就把他和他的儿子，并他的众民，都击杀了。","notes":[]},{"n":34,"t":"我们夺了他的一切城邑，将有人烟的各城，连女人带孩子，尽都毁灭，没有留下一个。","notes":[]},{"n":35,"t":"惟有牲畜和所夺的各城，并其中的财物，都取为自己的掠物。","notes":[]},{"n":36,"t":"从亚嫩谷边的亚罗珥和谷中的城，直到基列，耶和华—我们的神都交给我们了，没有一座城高得使我们不能攻取的。","notes":[]},{"n":37,"t":"惟有亚扪人之地，凡靠近雅博河的地，并山地的城邑，与耶和华—我们神所禁止我们去的地方，都没有挨近。」","notes":[]}]},"3":{"heading":"击败巴珊王噩","verses":[{"n":1,"t":"「以后，我们转回，向巴珊去。巴珊王噩和他的众民都出来，在以得来与我们交战。","notes":[]},{"n":2,"t":"耶和华对我说：『不要怕他！因我已将他和他的众民，并他的地，都交在你手中；你要待他像从前待住希实本的亚摩利王西宏一样。』","notes":[]},{"n":3,"t":"于是耶和华—我们的神也将巴珊王噩和他的众民都交在我们手中；我们杀了他们，没有留下一个。","notes":[]},{"n":4,"t":"那时，我们夺了他所有的城，共有六十座，没有一座城不被我们所夺。这为亚珥歌伯的全境，就是巴珊地噩王的国。","notes":[]},{"n":5,"t":"这些城都有坚固的高墙，有门有闩。此外还有许多无城墙的乡村。","notes":[]},{"n":6,"t":"我们将这些都毁灭了，像从前待希实本王西宏一样，把有人烟的各城，连女人带孩子，尽都毁灭；","notes":[]},{"n":7,"t":"惟有一切牲畜和城中的财物都取为自己的掠物。","notes":[]},{"n":8,"t":"那时，我们从约旦河东两个亚摩利王的手将亚嫩谷直到黑门山之地夺过来（","notes":[]},{"n":9,"t":"这黑门山，西顿人称为西连，亚摩利人称为示尼珥），","notes":[]},{"n":10,"t":"就是夺了平原的各城、基列全地、巴珊全地，直到撒迦和以得来，都是巴珊王噩国内的城邑。（","notes":[]},{"n":11,"t":"利乏音人所剩下的只有巴珊王噩。他的床是铁的，长九肘，宽四肘，都是以人肘为度。现今岂不是在亚扪人的拉巴吗？）」","notes":[]},{"n":12,"t":"「那时，我们得了这地。从亚嫩谷边的亚罗珥起，我将基列山地的一半，并其中的城邑，都给了吕便人和迦得人。","notes":[],"heads":["定居约旦河东的二支派半"]},{"n":13,"t":"其余的基列地和巴珊全地，就是噩王的国，我给了玛拿西半支派。亚珥歌伯全地乃是巴珊全地；这叫做利乏音人之地。","notes":[]},{"n":14,"t":"玛拿西的子孙睚珥占了亚珥歌伯全境，直到基述人和玛迦人的交界，就按自己的名称这巴珊地为哈倭特·睚珥，直到今日。","notes":[]},{"n":15,"t":"我又将基列给了玛吉。","notes":[]},{"n":16,"t":"从基列到亚嫩谷，以谷中为界，直到亚扪人交界的雅博河，我给了吕便人和迦得人，","notes":[]},{"n":17,"t":"又将亚拉巴和靠近约旦河之地，从基尼烈直到亚拉巴海，就是盐海，并毗斯迦山根东边之地，都给了他们。","notes":[]},{"n":18,"t":"「那时，我吩咐你们说：『耶和华—你们的神已将这地赐给你们为业；你们所有的勇士都要带着兵器，在你们的弟兄以色列人前面过去。","notes":[]},{"n":19,"t":"但你们的妻子、孩子、牲畜（我知道你们有许多的牲畜）可以住在我所赐给你们的各城里。","notes":[]},{"n":20,"t":"等到你们弟兄在约旦河那边，也得耶和华—你们神所赐给他们的地，又使他们得享平安，与你们一样，你们才可以回到我所赐给你们为业之地。』","notes":[]},{"n":21,"t":"那时我吩咐约书亚说：『你亲眼看见了耶和华—你神向这二王所行的；耶和华也必向你所要去的各国照样行。","notes":[]},{"n":22,"t":"你不要怕他们，因那为你争战的是耶和华—你的神。』」","notes":[]},{"n":23,"t":"「那时，我恳求耶和华说：","notes":[],"heads":["摩西不得进入迦南"]},{"n":24,"t":"『主耶和华啊，你已将你的大力大能显给仆人看。在天上，在地下，有什么神能像你行事、像你有大能的作为呢？","notes":[]},{"n":25,"t":"求你容我过去，看约旦河那边的美地，就是那佳美的山地和黎巴嫩。』","notes":[]},{"n":26,"t":"但耶和华因你们的缘故向我发怒，不应允我，对我说：『罢了！你不要向我再提这事。","notes":[]},{"n":27,"t":"你且上毗斯迦山顶去，向东、西、南、北举目观望，因为你必不能过这约旦河。","notes":[]},{"n":28,"t":"你却要嘱咐约书亚，勉励他，使他胆壮；因为他必在这百姓前面过去，使他们承受你所要观看之地。』","notes":[]},{"n":29,"t":"于是我们住在伯·毗珥对面的谷中。」","notes":[]}]},"4":{"heading":"摩西劝人民遵行耶和华的律例典章","verses":[{"n":1,"t":"「以色列人哪，现在我所教训你们的律例典章，你们要听从遵行，好叫你们存活，得以进入耶和华—你们列祖之神所赐给你们的地，承受为业。","notes":[]},{"n":2,"t":"所吩咐你们的话，你们不可加添，也不可删减，好叫你们遵守我所吩咐的，就是耶和华—你们神的命令。","notes":[]},{"n":3,"t":"耶和华因巴力·毗珥的事所行的，你们亲眼看见了。凡随从巴力·毗珥的人，耶和华—你们的神都从你们中间除灭了。","notes":[]},{"n":4,"t":"惟有你们专靠耶和华—你们神的人，今日全都存活。","notes":[]},{"n":5,"t":"我照着耶和华—我神所吩咐的将律例典章教训你们，使你们在所要进去得为业的地上遵行。","notes":[]},{"n":6,"t":"所以你们要谨守遵行；这就是你们在万民眼前的智慧、聪明。他们听见这一切律例，必说：『这大国的人真是有智慧，有聪明！』","notes":[]},{"n":7,"t":"哪一大国的人有神与他们相近，像耶和华—我们的神、在我们求告他的时候与我们相近呢？","notes":[]},{"n":8,"t":"又哪一大国有这样公义的律例典章、像我今日在你们面前所陈明的这一切律法呢？","notes":[]},{"n":9,"t":"「你只要谨慎，殷勤保守你的心灵，免得忘记你亲眼所看见的事，又免得你一生、这事离开你的心；总要传给你的子子孙孙。","notes":[]},{"n":10,"t":"你在何烈山站在耶和华—你神面前的那日，耶和华对我说：『你为我招聚百姓，我要叫他们听见我的话，使他们存活在世的日子，可以学习敬畏我，又可以教训儿女这样行。』","notes":[]},{"n":11,"t":"那时你们近前来，站在山下；山上有火焰冲天，并有昏黑、密云、幽暗。","notes":[]},{"n":12,"t":"耶和华从火焰中对你们说话，你们只听见声音，却没有看见形象。","notes":[]},{"n":13,"t":"他将所吩咐你们当守的约指示你们，就是十条诫，并将这诫写在两块石版上。","notes":[]},{"n":14,"t":"那时耶和华又吩咐我将律例典章教训你们，使你们在所要过去得为业的地上遵行。」","notes":[]},{"n":15,"t":"「所以，你们要分外谨慎；因为耶和华在何烈山、从火中对你们说话的那日，你们没有看见什么形象。","notes":[],"heads":["警告人民不可拜偶像"]},{"n":16,"t":"惟恐你们败坏自己，雕刻偶像，仿佛什么男像女像，","notes":[]},{"n":17,"t":"或地上走兽的像，或空中飞鸟的像，","notes":[]},{"n":18,"t":"或地上爬物的像，或地底下水中鱼的像。","notes":[]},{"n":19,"t":"又恐怕你向天举目观看，见耶和华—你的神为天下万民所摆列的日月星，就是天上的万象，自己便被勾引敬拜事奉它。","notes":[]},{"n":20,"t":"耶和华将你们从埃及领出来，脱离铁炉，要特作自己产业的子民，像今日一样。","notes":[]},{"n":21,"t":"耶和华又因你们的缘故向我发怒，起誓必不容我过约旦河，也不容我进入耶和华—你神所赐你为业的那美地。","notes":[]},{"n":22,"t":"我只得死在这地，不能过约旦河；但你们必过去得那美地。","notes":[]},{"n":23,"t":"你们要谨慎，免得忘记耶和华—你们神与你们所立的约，为自己雕刻偶像，就是耶和华—你神所禁止你做的偶像；","notes":[]},{"n":24,"t":"因为耶和华—你的神乃是烈火，是忌邪的神。","notes":[]},{"n":25,"t":"「你们在那地住久了，生子生孙，就雕刻偶像，仿佛什么形象，败坏自己，行耶和华—你神眼中看为恶的事，惹他发怒。","notes":[]},{"n":26,"t":"我今日呼天唤地向你们作见证，你们必在过约旦河得为业的地上速速灭尽！你们不能在那地上长久，必尽行除灭。","notes":[]},{"n":27,"t":"耶和华必使你们分散在万民中；在他所领你们到的万国里，你们剩下的人数稀少。","notes":[]},{"n":28,"t":"在那里，你们必事奉人手所造的神，就是用木石造成、不能看、不能听、不能吃、不能闻的神。","notes":[]},{"n":29,"t":"但你们在那里必寻求耶和华—你的神。你尽心尽性寻求他的时候，就必寻见。","notes":[]},{"n":30,"t":"日后你遭遇一切患难的时候，你必归回耶和华—你的神，听从他的话。","notes":[]},{"n":31,"t":"耶和华—你神原是有怜悯的神；他总不撇下你，不灭绝你，也不忘记他起誓与你列祖所立的约。","notes":[]},{"n":32,"t":"「你且考察在你以前的世代，自神造人在世以来，从天这边到天那边，曾有何民听见神在火中说话的声音，像你听见还能存活呢？这样的大事何曾有、何曾听见呢？","notes":[],"end":33},{"n":34,"t":"神何曾从别的国中将一国的人民领出来，用试验、神迹、奇事、争战、大能的手，和伸出来的膀臂，并大可畏的事，像耶和华—你们的神在埃及，在你们眼前为你们所行的一切事呢？","notes":[]},{"n":35,"t":"这是显给你看，要使你知道，惟有耶和华—他是神，除他以外，再无别神。","notes":[]},{"n":36,"t":"他从天上使你听见他的声音，为要教训你，又在地上使你看见他的烈火，并且听见他从火中所说的话。","notes":[]},{"n":37,"t":"因他爱你的列祖，所以拣选他们的后裔，用大能亲自领你出了埃及，","notes":[]},{"n":38,"t":"要将比你强大的国民从你面前赶出，领你进去，将他们的地赐你为业，像今日一样。","notes":[]},{"n":39,"t":"所以，今日你要知道，也要记在心上，天上地下惟有耶和华他是神，除他以外，再无别神。","notes":[]},{"n":40,"t":"我今日将他的律例诫命晓谕你，你要遵守，使你和你的子孙可以得福，并使你的日子在耶和华—你神所赐的地上得以长久。」","notes":[]},{"n":41,"t":"「那时，摩西在约旦河东，向日出之地，分定三座城，","notes":[],"heads":["设立河东的庇护城"]},{"n":42,"t":"使那素无仇恨、无心杀了人的，可以逃到这三城之中的一座城，就得存活：","notes":[]},{"n":43,"t":"为吕便人分定旷野平原的比悉；为迦得人分定基列的拉末；为玛拿西人分定巴珊的哥兰。」","notes":[]},{"n":44,"t":"摩西在以色列人面前所陈明的律法—","notes":[],"heads":["重申律法诫命"]},{"n":45,"t":"就是摩西在以色列人出埃及后所传给他们的法度、律例、典章；","notes":[]},{"n":46,"t":"在约旦河东伯·毗珥对面的谷中，在住希实本、亚摩利王西宏之地；这西宏是摩西和以色列人出埃及后所击杀的。","notes":[]},{"n":47,"t":"他们得了他的地，又得了巴珊王噩的地，就是两个亚摩利王，在约旦河东向日出之地。","notes":[]},{"n":48,"t":"从亚嫩谷边的亚罗珥，直到西云山，就是黑门山。","notes":[]},{"n":49,"t":"还有约旦河东的全亚拉巴，直到亚拉巴海，靠近毗斯迦山根。","notes":[]}]},"5":{"heading":"十诫","verses":[{"n":1,"t":"摩西将以色列众人召了来，对他们说：「以色列人哪，我今日晓谕你们的律例典章，你们要听，可以学习，谨守遵行。","notes":[]},{"n":2,"t":"耶和华—我们的神在何烈山与我们立约。","notes":[]},{"n":3,"t":"这约不是与我们列祖立的，乃是与我们今日在这里存活之人立的。","notes":[]},{"n":4,"t":"耶和华在山上，从火中，面对面与你们说话—","notes":[]},{"n":5,"t":"那时我站在耶和华和你们中间，要将耶和华的话传给你们；因为你们惧怕那火，没有上山—说：","notes":[]},{"n":6,"t":"「『我是耶和华—你的神，曾将你从埃及地为奴之家领出来。","notes":[]},{"n":7,"t":"「『除了我以外，你不可有别的神。","notes":[]},{"n":8,"t":"「『不可为自己雕刻偶像，也不可做什么形象，仿佛上天、下地和地底下、水中的百物。","notes":[]},{"n":9,"t":"不可跪拜那些像，也不可事奉它，因为我耶和华—你的神是忌邪的神。恨我的，我必追讨他的罪，自父及子，直到三、四代；","notes":[]},{"n":10,"t":"爱我、守我诫命的，我必向他们发慈爱，直到千代。","notes":[]},{"n":11,"t":"「『不可妄称耶和华—你神的名；因为妄称耶和华名的，耶和华必不以他为无罪。","notes":[]},{"n":12,"t":"「『当照耶和华—你神所吩咐的守安息日为圣日。","notes":[]},{"n":13,"t":"六日要劳碌做你一切的工，","notes":[]},{"n":14,"t":"但第七日是向耶和华—你神当守的安息日。这一日，你和你的儿女、仆婢、牛、驴、牲畜，并在你城里寄居的客旅，无论何工都不可做，使你的仆婢可以和你一样安息。","notes":[]},{"n":15,"t":"你也要记念你在埃及地作过奴仆；耶和华—你神用大能的手和伸出来的膀臂将你从那里领出来。因此，耶和华—你的神吩咐你守安息日。","notes":[]},{"n":16,"t":"「『当照耶和华—你神所吩咐的孝敬父母，使你得福，并使你的日子在耶和华—你神所赐你的地上得以长久。","notes":[]},{"n":17,"t":"「『不可杀人。","notes":[]},{"n":18,"t":"「『不可奸淫。","notes":[]},{"n":19,"t":"「『不可偷盗。","notes":[]},{"n":20,"t":"「『不可作假见证陷害人。","notes":[]},{"n":21,"t":"「『不可贪恋人的妻子；也不可贪图人的房屋、田地、仆婢、牛、驴，并他一切所有的。』","notes":[]},{"n":22,"t":"「这些话是耶和华在山上，从火中、云中、幽暗中，大声晓谕你们全会众的；此外并没有添别的话。他就把这话写在两块石版上，交给我了。」","notes":[]},{"n":23,"t":"「那时，火焰烧山，你们听见从黑暗中出来的声音；你们支派中所有的首领和长老都来就近我，","notes":[],"heads":["百姓看见火焰烧山而惧怕"]},{"n":24,"t":"说：『看哪，耶和华—我们神将他的荣光和他的大能显给我们看，我们又听见他的声音从火中出来。今日我们得见神与人说话，人还存活。","notes":[]},{"n":25,"t":"现在这大火将要烧灭我们，我们何必冒死呢？若再听见耶和华—我们神的声音就必死亡。","notes":[]},{"n":26,"t":"凡属血气的，曾有何人听见永生神的声音从火中出来，像我们听见还能存活呢？","notes":[]},{"n":27,"t":"求你近前去，听耶和华—我们神所要说的一切话，将他对你说的话都传给我们，我们就听从遵行。』","notes":[]},{"n":28,"t":"「你们对我说的话，耶和华都听见了。耶和华对我说：『这百姓的话，我听见了；他们所说的都是。","notes":[]},{"n":29,"t":"惟愿他们存这样的心敬畏我，常遵守我的一切诫命，使他们和他们的子孙永远得福。","notes":[]},{"n":30,"t":"你去对他们说：你们回帐棚去吧！","notes":[]},{"n":31,"t":"至于你，可以站在我这里，我要将一切诫命、律例、典章传给你；你要教训他们，使他们在我赐他们为业的地上遵行。』","notes":[]},{"n":32,"t":"所以，你们要照耶和华—你们神所吩咐的谨守遵行，不可偏离左右。","notes":[]},{"n":33,"t":"耶和华—你们神所吩咐你们行的，你们都要去行，使你们可以存活得福，并使你们的日子在所要承受的地上得以长久。」","notes":[]}]},"6":{"heading":"最大的诫命","verses":[{"n":1,"t":"「这是耶和华—你们神所吩咐教训你们的诫命、律例、典章，使你们在所要过去得为业的地上遵行，","notes":[]},{"n":2,"t":"好叫你和你子子孙孙一生敬畏耶和华—你的神，谨守他的一切律例诫命，就是我所吩咐你的，使你的日子得以长久。","notes":[]},{"n":3,"t":"以色列啊，你要听，要谨守遵行，使你可以在那流奶与蜜之地得以享福，人数极其增多，正如耶和华—你列祖的神所应许你的。","notes":[]},{"n":4,"t":"「以色列啊，你要听！耶和华—我们神是独一的主。","notes":[]},{"n":5,"t":"你要尽心、尽性、尽力爱耶和华—你的神。","notes":[]},{"n":6,"t":"我今日所吩咐你的话都要记在心上，","notes":[]},{"n":7,"t":"也要殷勤教训你的儿女。无论你坐在家里，行在路上，躺下，起来，都要谈论。","notes":[]},{"n":8,"t":"也要系在手上为记号，戴在额上为经文；","notes":[]},{"n":9,"t":"又要写在你房屋的门框上，并你的城门上。」","notes":[]},{"n":10,"t":"「耶和华—你的神领你进他向你列祖亚伯拉罕、以撒、雅各起誓应许给你的地。那里有城邑，又大又美，非你所建造的；","notes":[],"heads":["警告人民不可背逆神"]},{"n":11,"t":"有房屋，装满各样美物，非你所装满的；有凿成的水井，非你所凿成的；还有葡萄园、橄榄园，非你所栽种的；你吃了而且饱足。","notes":[]},{"n":12,"t":"那时你要谨慎，免得你忘记将你从埃及地、为奴之家领出来的耶和华。","notes":[]},{"n":13,"t":"你要敬畏耶和华—你的神，事奉他，指着他的名起誓。","notes":[]},{"n":14,"t":"不可随从别神，就是你们四围国民的神；","notes":[]},{"n":15,"t":"因为在你们中间的耶和华—你神是忌邪的神，惟恐耶和华—你神的怒气向你发作，就把你从地上除灭。","notes":[]},{"n":16,"t":"「你们不可试探耶和华—你们的神，像你们在玛撒那样试探他。","notes":[]},{"n":17,"t":"要留意遵守耶和华—你们神所吩咐的诫命、法度、律例。","notes":[]},{"n":18,"t":"耶和华眼中看为正、看为善的，你都要遵行，使你可以享福，并可以进去得耶和华向你列祖起誓应许的那美地，","notes":[]},{"n":19,"t":"照耶和华所说的，从你面前撵出你的一切仇敌。","notes":[]},{"n":20,"t":"「日后，你的儿子问你说：『耶和华—我们神吩咐你们的这些法度、律例、典章是什么意思呢？』","notes":[]},{"n":21,"t":"你就告诉你的儿子说：『我们在埃及作过法老的奴仆；耶和华用大能的手将我们从埃及领出来，","notes":[]},{"n":22,"t":"在我们眼前，将重大可怕的神迹奇事施行在埃及地和法老并他全家的身上，","notes":[]},{"n":23,"t":"将我们从那里领出来，要领我们进入他向我们列祖起誓应许之地，把这地赐给我们。","notes":[]},{"n":24,"t":"耶和华又吩咐我们遵行这一切律例，要敬畏耶和华—我们的神，使我们常得好处，蒙他保全我们的生命，像今日一样。","notes":[]},{"n":25,"t":"我们若照耶和华—我们神所吩咐的一切诫命谨守遵行，这就是我们的义了。』」","notes":[]}]},"7":{"heading":"耶和华的子民","verses":[{"n":1,"t":"「耶和华—你神领你进入要得为业之地，从你面前赶出许多国民，就是赫人、革迦撒人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人，共七国的民，都比你强大。","notes":[]},{"n":2,"t":"耶和华—你神将他们交给你击杀，那时你要把他们灭绝净尽，不可与他们立约，也不可怜恤他们。","notes":[]},{"n":3,"t":"不可与他们结亲。不可将你的女儿嫁他们的儿子，也不可叫你的儿子娶他们的女儿；","notes":[]},{"n":4,"t":"因为他必使你儿子转离不跟从主，去事奉别神，以致耶和华的怒气向你们发作，就速速地将你们灭绝。","notes":[]},{"n":5,"t":"你们却要这样待他们：拆毁他们的祭坛，打碎他们的柱像，砍下他们的木偶，用火焚烧他们雕刻的偶像。","notes":[]},{"n":6,"t":"因为你归耶和华—你神为圣洁的民；耶和华—你神从地上的万民中拣选你，特作自己的子民。","notes":[]},{"n":7,"t":"「耶和华专爱你们，拣选你们，并非因你们的人数多于别民，原来你们的人数在万民中是最少的。","notes":[]},{"n":8,"t":"只因耶和华爱你们，又因要守他向你们列祖所起的誓，就用大能的手领你们出来，从为奴之家救赎你们脱离埃及王法老的手。","notes":[]},{"n":9,"t":"所以，你要知道耶和华—你的神，他是神，是信实的神；向爱他、守他诫命的人守约，施慈爱，直到千代；","notes":[]},{"n":10,"t":"向恨他的人当面报应他们，将他们灭绝。凡恨他的人必报应他们，决不迟延。","notes":[]},{"n":11,"t":"所以，你要谨守遵行我今日所吩咐你的诫命、律例、典章。」","notes":[]},{"n":12,"t":"「你们果然听从这些典章，谨守遵行，耶和华—你神就必照他向你列祖所起的誓守约，施慈爱。","notes":[],"heads":["遵行诫命必蒙福"]},{"n":13,"t":"他必爱你，赐福与你，使你人数增多，也必在他向你列祖起誓应许给你的地上赐福与你身所生的，地所产的，并你的五谷、新酒，和油，以及牛犊、羊羔。","notes":[]},{"n":14,"t":"你必蒙福胜过万民；你们的男女没有不能生养的，牲畜也没有不能生育的。","notes":[]},{"n":15,"t":"耶和华必使一切的病症离开你；你所知道埃及各样的恶疾，他不加在你身上，只加在一切恨你的人身上。","notes":[]},{"n":16,"t":"耶和华—你神所要交给你的一切人民，你要将他们除灭；你眼不可顾惜他们。你也不可事奉他们的神，因这必成为你的网罗。","notes":[]},{"n":17,"t":"「你若心里说，这些国的民比我更多，我怎能赶出他们呢？","notes":[]},{"n":18,"t":"你不要惧怕他们，要牢牢记念耶和华—你神向法老和埃及全地所行的事，","notes":[]},{"n":19,"t":"就是你亲眼所看见的大试验、神迹、奇事，和大能的手，并伸出来的膀臂，都是耶和华—你神领你出来所用的。耶和华—你神必照样待你所惧怕的一切人民。","notes":[]},{"n":20,"t":"并且耶和华—你神必打发黄蜂飞到他们中间，直到那剩下而藏躲的人从你面前灭亡。","notes":[]},{"n":21,"t":"你不要因他们惊恐，因为耶和华—你神在你们中间是大而可畏的神。","notes":[]},{"n":22,"t":"耶和华—你神必将这些国的民从你面前渐渐赶出；你不可把他们速速灭尽，恐怕野地的兽多起来害你。","notes":[]},{"n":23,"t":"耶和华—你神必将他们交给你，大大地扰乱他们，直到他们灭绝了；","notes":[]},{"n":24,"t":"又要将他们的君王交在你手中，你就使他们的名从天下消灭。必无一人能在你面前站立得住，直到你将他们灭绝了。","notes":[]},{"n":25,"t":"他们雕刻的神像，你们要用火焚烧；其上的金银，你不可贪图，也不可收取，免得你因此陷入网罗；这原是耶和华—你神所憎恶的。","notes":[]},{"n":26,"t":"可憎的物，你不可带进家去；不然，你就成了当毁灭的，与那物一样。你要十分厌恶，十分憎嫌，因为这是当毁灭的物。」","notes":[]}]},"8":{"heading":"将得美地","verses":[{"n":1,"t":"「我今日所吩咐的一切诫命，你们要谨守遵行，好叫你们存活，人数增多，且进去得耶和华向你们列祖起誓应许的那地。","notes":[]},{"n":2,"t":"你也要记念耶和华—你的神在旷野引导你这四十年，是要苦炼你，试验你，要知道你心内如何，肯守他的诫命不肯。","notes":[]},{"n":3,"t":"他苦炼你，任你饥饿，将你和你列祖所不认识的吗哪赐给你吃，使你知道，人活着不是单靠食物，乃是靠耶和华口里所出的一切话。","notes":[]},{"n":4,"t":"这四十年，你的衣服没有穿破，你的脚也没有肿。","notes":[]},{"n":5,"t":"你当心里思想，耶和华—你神管教你，好像人管教儿子一样。","notes":[]},{"n":6,"t":"你要谨守耶和华—你神的诫命，遵行他的道，敬畏他。","notes":[]},{"n":7,"t":"因为耶和华—你神领你进入美地，那地有河，有泉，有源，从山谷中流出水来。","notes":[]},{"n":8,"t":"那地有小麦、大麦、葡萄树、无花果树、石榴树、橄榄树，和蜜。","notes":[]},{"n":9,"t":"你在那地不缺食物，一无所缺。那地的石头是铁，山内可以挖铜。","notes":[]},{"n":10,"t":"你吃得饱足，就要称颂耶和华—你的神，因他将那美地赐给你了。」","notes":[]},{"n":11,"t":"「你要谨慎，免得忘记耶和华—你的神，不守他的诫命、典章、律例，就是我今日所吩咐你的；","notes":[],"heads":["警告百姓不可忘记主"]},{"n":12,"t":"恐怕你吃得饱足，建造美好的房屋居住，","notes":[]},{"n":13,"t":"你的牛羊加多，你的金银增添，并你所有的全都加增，","notes":[]},{"n":14,"t":"你就心高气傲，忘记耶和华—你的神，就是将你从埃及地为奴之家领出来的，","notes":[]},{"n":15,"t":"引你经过那大而可怕的旷野，那里有火蛇、蝎子、干旱无水之地。他曾为你使水从坚硬的磐石中流出来，","notes":[]},{"n":16,"t":"又在旷野将你列祖所不认识的吗哪赐给你吃，是要苦炼你，试验你，叫你终久享福；","notes":[]},{"n":17,"t":"恐怕你心里说：『这货财是我力量、我能力得来的。』","notes":[]},{"n":18,"t":"你要记念耶和华—你的神，因为得货财的力量是他给你的，为要坚定他向你列祖起誓所立的约，像今日一样。","notes":[]},{"n":19,"t":"你若忘记耶和华—你的神，随从别神，事奉敬拜，你们必定灭亡；这是我今日警戒你们的。","notes":[]},{"n":20,"t":"耶和华在你们面前怎样使列国的民灭亡，你们也必照样灭亡，因为你们不听从耶和华—你们神的话。」","notes":[]}]},"9":{"heading":"百姓悖逆","verses":[{"n":1,"t":"「以色列啊，你当听！你今日要过约旦河，进去赶出比你强大的国民，得着广大坚固、高得顶天的城邑。","notes":[]},{"n":2,"t":"那民是亚衲族的人，又大又高，是你所知道的；也曾听见有人指着他们说：『谁能在亚衲族人面前站立得住呢？』","notes":[]},{"n":3,"t":"你今日当知道，耶和华—你的神在你前面过去，如同烈火，要灭绝他们，将他们制伏在你面前。这样，你就要照耶和华所说的赶出他们，使他们速速灭亡。","notes":[]},{"n":4,"t":"「耶和华—你的神将这些国民从你面前撵出以后，你心里不可说：『耶和华将我领进来得这地是因我的义。』其实，耶和华将他们从你面前赶出去是因他们的恶。","notes":[]},{"n":5,"t":"你进去得他们的地，并不是因你的义，也不是因你心里正直，乃是因这些国民的恶，耶和华—你的神将他们从你面前赶出去，又因耶和华要坚定他向你列祖亚伯拉罕、以撒、雅各起誓所应许的话。","notes":[]},{"n":6,"t":"「你当知道，耶和华—你神将这美地赐你为业，并不是因你的义；你本是硬着颈项的百姓。","notes":[]},{"n":7,"t":"你当记念不忘，你在旷野怎样惹耶和华—你神发怒。自从你出了埃及地的那日，直到你们来到这地方，你们时常悖逆耶和华。","notes":[]},{"n":8,"t":"你们在何烈山又惹耶和华发怒；他恼怒你们，要灭绝你们。","notes":[]},{"n":9,"t":"我上了山，要领受两块石版，就是耶和华与你们立约的版。那时我在山上住了四十昼夜，没有吃饭，也没有喝水。","notes":[]},{"n":10,"t":"耶和华把那两块石版交给我，是神用指头写的。版上所写的是照耶和华在大会的日子、在山上、从火中对你们所说的一切话。","notes":[]},{"n":11,"t":"过了四十昼夜，耶和华把那两块石版，就是约版，交给我。","notes":[]},{"n":12,"t":"对我说：『你起来，赶快下去！因为你从埃及领出来的百姓已经败坏了自己；他们快快地偏离了我所吩咐的道，为自己铸成了偶像。』","notes":[]},{"n":13,"t":"「耶和华又对我说：『我看这百姓是硬着颈项的百姓。","notes":[]},{"n":14,"t":"你且由着我，我要灭绝他们，将他们的名从天下涂抹，使你的后裔比他们成为更大更强的国。』","notes":[]},{"n":15,"t":"于是我转身下山，山被火烧着，两块约版在我两手之中。","notes":[]},{"n":16,"t":"我一看见你们得罪了耶和华—你们的神，铸成了牛犊，快快地偏离了耶和华所吩咐你们的道，","notes":[]},{"n":17,"t":"我就把那两块版从我手中扔下去，在你们眼前摔碎了。","notes":[]},{"n":18,"t":"因你们所犯的一切罪，行了耶和华眼中看为恶的事，惹他发怒，我就像从前俯伏在耶和华面前四十昼夜，没有吃饭，也没有喝水。","notes":[]},{"n":19,"t":"我因耶和华向你们大发烈怒，要灭绝你们，就甚害怕；但那次耶和华又应允了我。","notes":[]},{"n":20,"t":"耶和华也向亚伦甚是发怒，要灭绝他；那时我又为亚伦祈祷。","notes":[]},{"n":21,"t":"我把那叫你们犯罪所铸的牛犊用火焚烧，又捣碎磨得很细，以致细如灰尘，我就把这灰尘撒在从山上流下来的溪水中。","notes":[]},{"n":22,"t":"「你们在他备拉、玛撒、基博罗·哈他瓦又惹耶和华发怒。","notes":[]},{"n":23,"t":"耶和华打发你们离开加低斯·巴尼亚，说：『你们上去得我所赐给你们的地。』那时你们违背了耶和华—你们神的命令，不信服他，不听从他的话。","notes":[]},{"n":24,"t":"自从我认识你们以来，你们常常悖逆耶和华。","notes":[]},{"n":25,"t":"「我因耶和华说要灭绝你们，就在耶和华面前照旧俯伏四十昼夜。","notes":[]},{"n":26,"t":"我祈祷耶和华说：『主耶和华啊，求你不要灭绝你的百姓。他们是你的产业，是你用大力救赎的，用大能从埃及领出来的。","notes":[]},{"n":27,"t":"求你记念你的仆人亚伯拉罕、以撒、雅各，不要想念这百姓的顽梗、邪恶、罪过，","notes":[]},{"n":28,"t":"免得你领我们出来的那地之人说，耶和华因为不能将这百姓领进他所应许之地，又因恨他们，所以领他们出去，要在旷野杀他们。","notes":[]},{"n":29,"t":"其实他们是你的百姓，你的产业，是你用大能和伸出来的膀臂领出来的。』」","notes":[]}]},"10":{"heading":"摩西重新接受十诫","verses":[{"n":1,"t":"「那时，耶和华吩咐我说：『你要凿出两块石版，和先前的一样，上山到我这里来，又要做一木柜。","notes":[]},{"n":2,"t":"你先前摔碎的那版，其上的字我要写在这版上；你要将这版放在柜中。』","notes":[]},{"n":3,"t":"于是我用皂荚木做了一柜，又凿出两块石版，和先前的一样，手里拿这两块版上山去了。","notes":[]},{"n":4,"t":"耶和华将那大会之日、在山上从火中所传与你们的十条诫，照先前所写的，写在这版上，将版交给我了。","notes":[]},{"n":5,"t":"我转身下山，将这版放在我所做的柜中，现今还在那里，正如耶和华所吩咐我的。」（","notes":[]},{"n":6,"t":"以色列人从比罗比尼·亚干起行，到了摩西拉。亚伦死在那里，就葬在那里。他儿子以利亚撒接续他供祭司的职分。","notes":["或译：亚干井"]},{"n":7,"t":"他们从那里起行，到了谷歌大，又从谷歌大到了有溪水之地的约巴他。","notes":[]},{"n":8,"t":"那时，耶和华将利未支派分别出来，抬耶和华的约柜，又侍立在耶和华面前事奉他，奉他的名祝福，直到今日。","notes":[]},{"n":9,"t":"所以利未人在他弟兄中无分无业，耶和华是他的产业，正如耶和华—你神所应许他的。","notes":[]},{"n":10,"t":"「我又像从前在山上住了四十昼夜。那次耶和华也应允我，不忍将你灭绝。","notes":[]},{"n":11,"t":"耶和华吩咐我说：『你起来引导这百姓，使他们进去得我向他们列祖起誓应许所赐之地。』」","notes":[]},{"n":12,"t":"「以色列啊，现在耶和华—你神向你所要的是什么呢？只要你敬畏耶和华—你的神，遵行他的道，爱他，尽心尽性事奉他，","notes":[],"heads":["神的要求"]},{"n":13,"t":"遵守他的诫命律例，就是我今日所吩咐你的，为要叫你得福。","notes":[]},{"n":14,"t":"看哪，天和天上的天，地和地上所有的，都属耶和华—你的神。","notes":[]},{"n":15,"t":"耶和华但喜悦你的列祖，爱他们，从万民中拣选他们的后裔，就是你们，像今日一样。","notes":[]},{"n":16,"t":"所以你们要将心里的污秽除掉，不可再硬着颈项。","notes":[]},{"n":17,"t":"因为耶和华—你们的神—他是万神之神，万主之主，至大的神，大有能力，大而可畏，不以貌取人，也不受贿赂。","notes":[]},{"n":18,"t":"他为孤儿寡妇伸冤，又怜爱寄居的，赐给他衣食。","notes":[]},{"n":19,"t":"所以你们要怜爱寄居的，因为你们在埃及地也作过寄居的。","notes":[]},{"n":20,"t":"你要敬畏耶和华—你的神，事奉他，专靠他，也要指着他的名起誓。","notes":[]},{"n":21,"t":"他是你所赞美的，是你的神，为你做了那大而可畏的事，是你亲眼所看见的。","notes":[]},{"n":22,"t":"你的列祖七十人下埃及；现在耶和华—你的神使你如同天上的星那样多。」","notes":[]}]},"11":{"heading":"主的伟大","verses":[{"n":1,"t":"「你要爱耶和华—你的神，常守他的吩咐、律例、典章、诫命。","notes":[]},{"n":2,"t":"你们今日当知道，我本不是和你们的儿女说话；因为他们不知道，也没有看见耶和华—你们神的管教、威严、大能的手，和伸出来的膀臂，","notes":[]},{"n":3,"t":"并他在埃及中向埃及王法老和其全地所行的神迹奇事；","notes":[]},{"n":4,"t":"也没有看见他怎样待埃及的军兵、车马，他们追赶你们的时候，耶和华怎样使红海的水淹没他们，将他们灭绝，直到今日，","notes":[]},{"n":5,"t":"并他在旷野怎样待你们，以致你们来到这地方；","notes":[]},{"n":6,"t":"也没有看见他怎样待吕便子孙以利押的儿子大坍、亚比兰，地怎样在以色列人中间开口，吞了他们和他们的家眷，并帐棚与跟他们的一切活物。","notes":[]},{"n":7,"t":"惟有你们亲眼看见耶和华所做的一切大事。」","notes":[]},{"n":8,"t":"「所以，你们要守我今日所吩咐的一切诫命，使你们胆壮，能以进去，得你们所要得的那地，","notes":[],"heads":["应许之地的福泽"]},{"n":9,"t":"并使你们的日子在耶和华向你们列祖起誓、应许给他们和他们后裔的地上得以长久；那是流奶与蜜之地。","notes":[]},{"n":10,"t":"你要进去得为业的那地，本不像你出来的埃及地。你在那里撒种，用脚浇灌，像浇灌菜园一样。","notes":[]},{"n":11,"t":"你们要过去得为业的那地乃是有山有谷、雨水滋润之地，","notes":[]},{"n":12,"t":"是耶和华—你神所眷顾的；从岁首到年终，耶和华—你神的眼目时常看顾那地。","notes":[]},{"n":13,"t":"「你们若留意听从我今日所吩咐的诫命，爱耶和华—你们的神，尽心尽性事奉他，","notes":[]},{"n":14,"t":"他必按时降秋雨春雨在你们的地上，使你们可以收藏五谷、新酒，和油，","notes":["原文是我"]},{"n":15,"t":"也必使你吃得饱足，并使田野为你的牲畜长草。","notes":[]},{"n":16,"t":"你们要谨慎，免得心中受迷惑，就偏离正路，去事奉敬拜别神。","notes":[]},{"n":17,"t":"耶和华的怒气向你们发作，就使天闭塞不下雨，地也不出产，使你们在耶和华所赐给你们的美地上速速灭亡。","notes":[]},{"n":18,"t":"「你们要将我这话存在心内，留在意中，系在手上为记号，戴在额上为经文；","notes":[]},{"n":19,"t":"也要教训你们的儿女，无论坐在家里，行在路上，躺下，起来，都要谈论；","notes":[]},{"n":20,"t":"又要写在房屋的门框上，并城门上，","notes":[]},{"n":21,"t":"使你们和你们子孙的日子在耶和华向你们列祖起誓、应许给他们的地上得以增多，如天覆地的日子那样多。","notes":[]},{"n":22,"t":"你们若留意谨守遵行我所吩咐这一切的诫命，爱耶和华—你们的神，行他的道，专靠他，","notes":[]},{"n":23,"t":"他必从你们面前赶出这一切国民，就是比你们更大更强的国民，你们也要得他们的地。","notes":[]},{"n":24,"t":"凡你们脚掌所踏之地都必归你们；从旷野和黎巴嫩，并幼发拉底大河，直到西海，都要作你们的境界。","notes":[]},{"n":25,"t":"必无一人能在你们面前站立得住；耶和华—你们的神必照他所说的，使惧怕惊恐临到你们所踏之地的居民。","notes":[]},{"n":26,"t":"「看哪，我今日将祝福与咒诅的话都陈明在你们面前。","notes":[]},{"n":27,"t":"你们若听从耶和华—你们神的诫命，就是我今日所吩咐你们的，就必蒙福。","notes":[]},{"n":28,"t":"你们若不听从耶和华—你们神的诫命，偏离我今日所吩咐你们的道，去事奉你们素来所不认识的别神，就必受祸。","notes":[]},{"n":29,"t":"及至耶和华—你的神领你进入要去得为业的那地，你就要将祝福的话陈明在基利心山上，将咒诅的话陈明在以巴路山上。","notes":[]},{"n":30,"t":"这二山岂不是在约旦河那边，日落之处，在住亚拉巴的迦南人之地与吉甲相对，靠近摩利橡树吗？","notes":[]},{"n":31,"t":"你们要过约旦河，进去得耶和华—你们神所赐你们为业之地，在那地居住。","notes":[]},{"n":32,"t":"你们要谨守遵行我今日在你们面前所陈明的一切律例典章。」","notes":[]}]},"12":{"heading":"惟一的敬拜场所","verses":[{"n":1,"t":"「你们存活于世的日子，在耶和华—你们列祖的神所赐你们为业的地上，要谨守遵行的律例典章乃是这些：","notes":[]},{"n":2,"t":"你们要将所赶出的国民事奉神的各地方，无论是在高山，在小山，在各青翠树下，都毁坏了；","notes":[]},{"n":3,"t":"也要拆毁他们的祭坛，打碎他们的柱像，用火焚烧他们的木偶，砍下他们雕刻的神像，并将其名从那地方除灭。","notes":[]},{"n":4,"t":"你们不可照他们那样事奉耶和华—你们的神。","notes":[]},{"n":5,"t":"但耶和华—你们的神从你们各支派中选择何处为立他名的居所，你们就当往那里去求问，","notes":[]},{"n":6,"t":"将你们的燔祭、平安祭、十分取一之物，和手中的举祭，并还愿祭、甘心祭，以及牛群羊群中头生的，都奉到那里。","notes":[]},{"n":7,"t":"在那里，耶和华—你们神的面前，你们和你们的家属都可以吃，并且因你手所办的一切事蒙耶和华—你的神赐福，就都欢乐。","notes":[]},{"n":8,"t":"我们今日在这里所行的是各人行自己眼中看为正的事，你们将来不可这样行；","notes":[]},{"n":9,"t":"因为你们还没有到耶和华—你神所赐你的安息地，所给你的产业。","notes":[]},{"n":10,"t":"但你们过了约旦河，得以住在耶和华—你们神使你们承受为业之地，又使你们太平，不被四围的一切仇敌扰乱，安然居住。","notes":[]},{"n":11,"t":"那时要将我所吩咐你们的燔祭、平安祭、十分取一之物，和手中的举祭，并向耶和华许愿献的一切美祭，都奉到耶和华—你们神所选择要立为他名的居所。","notes":[]},{"n":12,"t":"你们和儿女、仆婢，并住在你们城里无分无业的利未人，都要在耶和华—你们的神面前欢乐。","notes":[]},{"n":13,"t":"你要谨慎，不可在你所看中的各处献燔祭。","notes":[]},{"n":14,"t":"惟独耶和华从你那一支派中所选择的地方，你就要在那里献燔祭，行我一切所吩咐你的。","notes":[]},{"n":15,"t":"「然而，在你各城里都可以照耶和华—你神所赐你的福分，随心所欲宰牲吃肉；无论洁净人不洁净人都可以吃，就如吃羚羊与鹿一般。","notes":[]},{"n":16,"t":"只是不可吃血，要倒在地上，如同倒水一样。","notes":[]},{"n":17,"t":"你的五谷、新酒，和油的十分之一，或是牛群羊群中头生的，或是你许愿献的，甘心献的，或是手中的举祭，都不可在你城里吃。","notes":[]},{"n":18,"t":"但要在耶和华—你的神面前吃，在耶和华—你神所要选择的地方，你和儿女、仆婢，并住在你城里的利未人，都可以吃；也要因你手所办的，在耶和华—你神面前欢乐。","notes":[]},{"n":19,"t":"你要谨慎，在你所住的地方永不可丢弃利未人。","notes":[]},{"n":20,"t":"「耶和华—你的神照他所应许扩张你境界的时候，你心里想要吃肉，说：『我要吃肉』，就可以随心所欲地吃肉。","notes":[]},{"n":21,"t":"耶和华—你神所选择要立他名的地方若离你太远，就可以照我所吩咐的，将耶和华赐给你的牛羊取些宰了，可以随心所欲在你城里吃。","notes":[]},{"n":22,"t":"你吃那肉，要像吃羚羊与鹿一般；无论洁净人不洁净人都可以吃。","notes":[]},{"n":23,"t":"只是你要心意坚定，不可吃血，因为血是生命；不可将血与肉同吃。","notes":["原文是生命"]},{"n":24,"t":"不可吃血，要倒在地上，如同倒水一样。","notes":[]},{"n":25,"t":"不可吃血。这样，你行耶和华眼中看为正的事，你和你的子孙就可以得福。","notes":[]},{"n":26,"t":"只是你分别为圣的物和你的还愿祭要奉到耶和华所选择的地方去。","notes":[]},{"n":27,"t":"你的燔祭，连肉带血，都要献在耶和华—你神的坛上。平安祭的血要倒在耶和华—你神的坛上；平安祭的肉，你自己可以吃。","notes":[]},{"n":28,"t":"你要谨守听从我所吩咐的一切话，行耶和华—你神眼中看为善，看为正的事。这样，你和你的子孙就可以永远享福。」","notes":[]},{"n":29,"t":"「耶和华—你神将你要去赶出的国民从你面前剪除，你得了他们的地居住，","notes":[],"heads":["警告不可拜偶像"]},{"n":30,"t":"那时就要谨慎，不可在他们除灭之后随从他们的恶俗，陷入网罗，也不可访问他们的神说：『这些国民怎样事奉他们的神，我也要照样行。』","notes":[]},{"n":31,"t":"你不可向耶和华—你的神这样行，因为他们向他们的神行了耶和华所憎嫌所恨恶的一切事，甚至将自己的儿女用火焚烧，献与他们的神。","notes":[]},{"n":32,"t":"凡我所吩咐的，你们都要谨守遵行，不可加添，也不可删减。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"「你们中间若有先知或是做梦的起来，向你显个神迹奇事，","notes":[]},{"n":2,"t":"对你说：『我们去随从你素来所不认识的别神，事奉它吧。』他所显的神迹奇事虽有应验，","notes":[]},{"n":3,"t":"你也不可听那先知或是那做梦之人的话；因为这是耶和华—你们的神试验你们，要知道你们是尽心尽性爱耶和华—你们的神不是。","notes":[]},{"n":4,"t":"你们要顺从耶和华—你们的神，敬畏他，谨守他的诫命，听从他的话，事奉他，专靠他。","notes":[]},{"n":5,"t":"那先知或是那做梦的既用言语叛逆那领你们出埃及地、救赎你脱离为奴之家的耶和华—你们的神，要勾引你离开耶和华—你神所吩咐你行的道，你便要将他治死。这样，就把那恶从你们中间除掉。","notes":[]},{"n":6,"t":"「你的同胞弟兄，或是你的儿女，或是你怀中的妻，或是如同你性命的朋友，若暗中引诱你，说：『我们不如去事奉你和你列祖素来所不认识的别神—","notes":[]},{"n":7,"t":"是你四围列国的神。』无论是离你近，离你远，从地这边到地那边的神，","notes":[]},{"n":8,"t":"你不可依从他，也不可听从他，眼不可顾惜他。你不可怜恤他，也不可遮庇他，","notes":[]},{"n":9,"t":"总要杀他；你先下手，然后众民也下手，将他治死。","notes":[]},{"n":10,"t":"要用石头打死他，因为他想要勾引你离开那领你出埃及地为奴之家的耶和华—你的神。","notes":[]},{"n":11,"t":"以色列众人都要听见害怕，就不敢在你们中间再行这样的恶了。","notes":[]},{"n":12,"t":"「在耶和华—你神所赐你居住的各城中，你若听人说，有些匪类从你们中间的一座城出来勾引本城的居民，说：『我们不如去事奉你们素来所不认识的别神』；","notes":[],"end":13},{"n":14,"t":"你就要探听，查究，细细地访问，果然是真，准有这可憎恶的事行在你们中间，","notes":[]},{"n":15,"t":"你必要用刀杀那城里的居民，把城里所有的，连牲畜，都用刀杀尽。","notes":[]},{"n":16,"t":"你从那城里所夺的财物都要堆积在街市上，用火将城和其内所夺的财物都在耶和华—你神面前烧尽；那城就永为荒堆，不可再建造。","notes":[]},{"n":17,"t":"那当毁灭的物连一点都不可粘你的手。你要听从耶和华—你神的话，遵守我今日所吩咐你的一切诫命，行耶和华—你神眼中看为正的事，耶和华就必转意，不发烈怒，恩待你，怜恤你，照他向你列祖所起的誓使你人数增多。」","notes":[],"end":18}]},"14":{"heading":"举哀时的禁例","verses":[{"n":1,"t":"「你们是耶和华—你们神的儿女。不可为死人用刀划身，也不可将额上剃光；","notes":[]},{"n":2,"t":"因为你归耶和华—你神为圣洁的民，耶和华从地上的万民中拣选你特作自己的子民。」","notes":[]},{"n":3,"t":"「凡可憎的物都不可吃。","notes":[],"heads":["洁净和不洁净的动物"]},{"n":4,"t":"可吃的牲畜就是牛、绵羊、山羊、","notes":[]},{"n":5,"t":"鹿、羚羊、狍子、野山羊、麋鹿、黄羊、青羊。","notes":[]},{"n":6,"t":"凡分蹄成为两瓣又倒嚼的走兽，你们都可以吃。","notes":[]},{"n":7,"t":"但那些倒嚼或是分蹄之中不可吃的乃是骆驼、兔子、沙番—因为是倒嚼不分蹄，就与你们不洁净；","notes":[]},{"n":8,"t":"猪—因为是分蹄却不倒嚼，就与你们不洁净。这些兽的肉，你们不可吃，死的也不可摸。","notes":[]},{"n":9,"t":"「水中可吃的乃是这些：凡有翅有鳞的都可以吃；","notes":[]},{"n":10,"t":"凡无翅无鳞的都不可吃，是与你们不洁净。","notes":[]},{"n":11,"t":"「凡洁净的鸟，你们都可以吃。","notes":[]},{"n":12,"t":"不可吃的乃是雕、狗头雕、红头雕、","notes":[]},{"n":13,"t":"鹯、小鹰、鹞鹰与其类，","notes":[]},{"n":14,"t":"乌鸦与其类，","notes":[]},{"n":15,"t":"鸵鸟、夜鹰、鱼鹰、鹰与其类，","notes":[]},{"n":16,"t":"鸮鸟、猫头鹰、角鸱、","notes":[]},{"n":17,"t":"鹈鹕、秃雕、鸬鹚、","notes":[]},{"n":18,"t":"鹳、鹭鸶与其类，戴鵀与蝙蝠。","notes":[]},{"n":19,"t":"凡有翅膀爬行的物是与你们不洁净，都不可吃。","notes":[]},{"n":20,"t":"凡洁净的鸟，你们都可以吃。","notes":[]},{"n":21,"t":"「凡自死的，你们都不可吃，可以给你城里寄居的吃，或卖与外人吃，因为你是归耶和华—你神为圣洁的民。「不可用山羊羔母的奶煮山羊羔。」","notes":[]},{"n":22,"t":"「你要把你撒种所产的，就是你田地每年所出的，十分取一分；","notes":[],"heads":["十分献一的条例"]},{"n":23,"t":"又要把你的五谷、新酒、和油的十分之一，并牛群羊群中头生的，吃在耶和华—你神面前，就是他所选择要立为他名的居所。这样，你可以学习时常敬畏耶和华—你的神。","notes":[]},{"n":24,"t":"当耶和华—你神赐福与你的时候，耶和华—你神所选择要立为他名的地方若离你太远，那路也太长，使你不能把这物带到那里去，","notes":[]},{"n":25,"t":"你就可以换成银子，将银子包起来，拿在手中，往耶和华—你神所要选择的地方去。","notes":[]},{"n":26,"t":"你用这银子，随心所欲，或买牛羊，或买清酒浓酒，凡你心所想的都可以买；你和你的家属在耶和华—你神的面前吃喝快乐。","notes":[]},{"n":27,"t":"「住在你城里的利未人，你不可丢弃他，因为他在你们中间无分无业。","notes":[]},{"n":28,"t":"每逢三年的末一年，你要将本年的土产十分之一都取出来，积存在你的城中。","notes":[]},{"n":29,"t":"在你城里无分无业的利未人，和你城里寄居的，并孤儿寡妇，都可以来，吃得饱足。这样，耶和华—你的神必在你手里所办的一切事上赐福与你。」","notes":[]}]},"15":{"heading":"安息年","verses":[{"n":1,"t":"「每逢七年末一年，你要施行豁免。","notes":[]},{"n":2,"t":"豁免的定例乃是这样：凡债主要把所借给邻舍的豁免了；不可向邻舍和弟兄追讨，因为耶和华的豁免年已经宣告了。","notes":[]},{"n":3,"t":"若借给外邦人，你可以向他追讨；但借给你弟兄，无论是什么，你要松手豁免了。","notes":[]},{"n":4,"t":"你若留意听从耶和华—你神的话，谨守遵行我今日所吩咐你这一切的命令，就必在你们中间没有穷人了（在耶和华—你神所赐你为业的地上，耶和华必大大赐福与你。）","notes":[],"end":5},{"n":6,"t":"因为耶和华—你的神必照他所应许你的赐福与你。你必借给许多国民，却不致向他们借贷；你必管辖许多国民，他们却不能管辖你。","notes":[]},{"n":7,"t":"「在耶和华—你神所赐你的地上，无论哪一座城里，你弟兄中若有一个穷人，你不可忍着心、揝着手不帮补你穷乏的弟兄。","notes":[]},{"n":8,"t":"总要向他松开手，照他所缺乏的借给他，补他的不足。","notes":[]},{"n":9,"t":"你要谨慎，不可心里起恶念，说：『第七年的豁免年快到了』，你便恶眼看你穷乏的弟兄，什么都不给他，以致他因你求告耶和华，罪便归于你了。","notes":[]},{"n":10,"t":"你总要给他，给他的时候心里不可愁烦；因耶和华—你的神必在你这一切所行的，并你手里所办的事上，赐福与你。","notes":[]},{"n":11,"t":"原来那地上的穷人永不断绝；所以我吩咐你说：『总要向你地上困苦穷乏的弟兄松开手。』」","notes":[]},{"n":12,"t":"「你弟兄中，若有一个希伯来男人或希伯来女人被卖给你，服事你六年，到第七年就要任他自由出去。","notes":[],"heads":["对待奴婢的条例"]},{"n":13,"t":"你任他自由的时候，不可使他空手而去，","notes":[]},{"n":14,"t":"要从你羊群、禾场、酒榨之中多多地给他；耶和华—你的神怎样赐福与你，你也要照样给他。","notes":[]},{"n":15,"t":"要记念你在埃及地作过奴仆，耶和华—你的神将你救赎；因此，我今日吩咐你这件事。","notes":[]},{"n":16,"t":"他若对你说：『我不愿意离开你』，是因他爱你和你的家，且因在你那里很好，","notes":[]},{"n":17,"t":"你就要拿锥子将他的耳朵在门上刺透，他便永为你的奴仆了。你待婢女也要这样。","notes":[]},{"n":18,"t":"你任他自由的时候，不可以为难事，因他服事你六年，较比雇工的工价多加一倍了。耶和华—你的神就必在你所做的一切事上赐福与你。」","notes":[]},{"n":19,"t":"「你牛群羊群中头生的，凡是公的，都要分别为圣，归耶和华—你的神。牛群中头生的，不可用它耕地；羊群中头生的，不可剪毛。","notes":[],"heads":["头生牛羊的条例"]},{"n":20,"t":"这头生的，你和你的家属，每年要在耶和华所选择的地方，在耶和华—你神面前吃。","notes":[]},{"n":21,"t":"这头生的若有什么残疾，就如瘸腿的、瞎眼的，无论有什么恶残疾，都不可献给耶和华—你的神；","notes":[]},{"n":22,"t":"可以在你城里吃；洁净人与不洁净人都可以吃，就如吃羚羊与鹿一般。","notes":[]},{"n":23,"t":"只是不可吃它的血；要倒在地上，如同倒水一样。」","notes":[]}]},"16":{"heading":"逾越节","verses":[{"n":1,"t":"「你要注意亚笔月，向耶和华—你的神守逾越节，因为耶和华—你的神在亚笔月夜间领你出埃及。","notes":[]},{"n":2,"t":"你当在耶和华所选择要立为他名的居所，从牛群羊群中，将逾越节的祭牲献给耶和华—你的神。","notes":[]},{"n":3,"t":"你吃这祭牲，不可吃有酵的饼；七日之内要吃无酵饼，就是困苦饼—你本是急忙出了埃及地—要叫你一生一世记念你从埃及地出来的日子。","notes":[]},{"n":4,"t":"在你四境之内，七日不可见面酵，头一日晚上所献的肉，一点不可留到早晨。","notes":[]},{"n":5,"t":"在耶和华—你神所赐的各城中，你不可献逾越节的祭；","notes":[]},{"n":6,"t":"只当在耶和华—你神所选择要立为他名的居所，晚上日落的时候，乃是你出埃及的时候，献逾越节的祭。","notes":[]},{"n":7,"t":"当在耶和华—你神所选择的地方把肉烤了吃，次日早晨就回到你的帐棚去。","notes":["烤：或译煮"]},{"n":8,"t":"你要吃无酵饼六日，第七日要向耶和华—你的神守严肃会，不可做工。」","notes":[]},{"n":9,"t":"「你要计算七七日：从你开镰收割禾稼时算起，共计七七日。","notes":[],"heads":["七七收获节"]},{"n":10,"t":"你要照耶和华—你神所赐你的福，手里拿着甘心祭，献在耶和华—你的神面前，守七七节。","notes":[]},{"n":11,"t":"你和你儿女、仆婢，并住在你城里的利未人，以及在你们中间寄居的与孤儿寡妇，都要在耶和华—你神所选择立为他名的居所，在耶和华—你的神面前欢乐。","notes":[]},{"n":12,"t":"你也要记念你在埃及作过奴仆。你要谨守遵行这些律例。」","notes":[]},{"n":13,"t":"「你把禾场的谷、酒榨的酒收藏以后，就要守住棚节七日。","notes":[],"heads":["住棚节"]},{"n":14,"t":"守节的时候，你和你儿女、仆婢，并住在你城里的利未人，以及寄居的与孤儿寡妇，都要欢乐。","notes":[]},{"n":15,"t":"在耶和华所选择的地方，你当向耶和华—你的神守节七日；因为耶和华—你神在你一切的土产上和你手里所办的事上要赐福与你，你就非常地欢乐。","notes":[]},{"n":16,"t":"你一切的男丁要在除酵节、七七节、住棚节，一年三次，在耶和华—你神所选择的地方朝见他，却不可空手朝见。","notes":[]},{"n":17,"t":"各人要按自己的力量，照耶和华—你神所赐的福分，奉献礼物。」","notes":[]},{"n":18,"t":"「你要在耶和华—你神所赐的各城里，按着各支派设立审判官和官长。他们必按公义的审判判断百姓。","notes":[],"heads":["秉公审断"]},{"n":19,"t":"不可屈枉正直；不可看人的外貌。也不可受贿赂；因为贿赂能叫智慧人的眼变瞎了，又能颠倒义人的话。","notes":[]},{"n":20,"t":"你要追求至公至义，好叫你存活，承受耶和华—你神所赐你的地。","notes":[]},{"n":21,"t":"「你为耶和华—你的神筑坛，不可在坛旁栽什么树木作为木偶。","notes":[]},{"n":22,"t":"也不可为自己设立柱像；这是耶和华—你神所恨恶的。","notes":[]}]},"17":{"heading":"有关立王的指示","verses":[{"n":1,"t":"「凡有残疾，或有什么恶病的牛羊，你都不可献给耶和华—你的神，因为这是耶和华—你神所憎恶的。","notes":[]},{"n":2,"t":"「在你们中间，在耶和华—你神所赐你的诸城中，无论哪座城里，若有人，或男或女，行耶和华—你神眼中看为恶的事，违背了他的约，","notes":[]},{"n":3,"t":"去事奉敬拜别神，或拜日头，或拜月亮，或拜天象，是主不曾吩咐的；","notes":[]},{"n":4,"t":"有人告诉你，你也听见了，就要细细地探听，果然是真，准有这可憎恶的事行在以色列中，","notes":[]},{"n":5,"t":"你就要将行这恶事的男人或女人拉到城门外，用石头将他打死。","notes":[]},{"n":6,"t":"要凭两三个人的口作见证将那当死的人治死；不可凭一个人的口作见证将他治死。","notes":[]},{"n":7,"t":"见证人要先下手，然后众民也下手将他治死。这样，就把那恶从你们中间除掉。","notes":[]},{"n":8,"t":"「你城中若起了争讼的事，或因流血，或因争竞，或因殴打，是你难断的案件，你就当起来，往耶和华—你神所选择的地方","notes":[]},{"n":9,"t":"去见祭司利未人，并当时的审判官，求问他们，他们必将判语指示你。","notes":[]},{"n":10,"t":"他们在耶和华所选择的地方指示你的判语，你必照着他们所指教你的一切话谨守遵行。","notes":[]},{"n":11,"t":"要按他们所指教你的律法，照他们所断定的去行；他们所指示你的判语，你不可偏离左右。","notes":[]},{"n":12,"t":"若有人擅敢不听从那侍立在耶和华—你神面前的祭司，或不听从审判官，那人就必治死；这样，便将那恶从以色列中除掉。","notes":[]},{"n":13,"t":"众百姓都要听见害怕，不再擅敢行事。」","notes":[]},{"n":14,"t":"「到了耶和华—你神所赐你的地，得了那地居住的时候，若说：『我要立王治理我，像四围的国一样。』","notes":[]},{"n":15,"t":"你总要立耶和华—你神所拣选的人为王。必从你弟兄中立一人；不可立你弟兄以外的人为王。","notes":[]},{"n":16,"t":"只是王不可为自己加添马匹，也不可使百姓回埃及去，为要加添他的马匹，因耶和华曾吩咐你们说：『不可再回那条路去。』","notes":[]},{"n":17,"t":"他也不可为自己多立妃嫔，恐怕他的心偏邪；也不可为自己多积金银。","notes":[]},{"n":18,"t":"他登了国位，就要将祭司利未人面前的这律法书，为自己抄录一本，","notes":[]},{"n":19,"t":"存在他那里，要平生诵读，好学习敬畏耶和华—他的神，谨守遵行这律法书上的一切言语和这些律例，","notes":[]},{"n":20,"t":"免得他向弟兄心高气傲，偏左偏右，离了这诫命。这样，他和他的子孙便可在以色列中，在国位上年长日久。」","notes":[]}]},"18":{"heading":"祭司当得的分","verses":[{"n":1,"t":"「祭司利未人和利未全支派必在以色列中无分无业；他们所吃用的就是献给耶和华的火祭和一切所捐的。","notes":[]},{"n":2,"t":"他们在弟兄中必没有产业；耶和华是他们的产业，正如耶和华所应许他们的。","notes":[]},{"n":3,"t":"祭司从百姓所当得的分乃是这样：凡献牛或羊为祭的，要把前腿和两腮并脾胃给祭司。","notes":[]},{"n":4,"t":"初收的五谷、新酒和油，并初剪的羊毛，也要给他；","notes":[]},{"n":5,"t":"因为耶和华—你的神从你各支派中将他拣选出来，使他和他子孙永远奉耶和华的名侍立，事奉。","notes":[]},{"n":6,"t":"「利未人无论寄居在以色列中的哪一座城，若从那里出来，一心愿意到耶和华所选择的地方，","notes":[]},{"n":7,"t":"就要奉耶和华—他神的名事奉，像他众弟兄利未人侍立在耶和华面前事奉一样。","notes":[]},{"n":8,"t":"除了他卖祖父产业所得的以外，还要得一分祭物与他们同吃。」","notes":[]},{"n":9,"t":"「你到了耶和华—你神所赐之地，那些国民所行可憎恶的事，你不可学着行。","notes":[],"heads":["不可随从异邦的恶俗"]},{"n":10,"t":"你们中间不可有人使儿女经火，也不可有占卜的、观兆的、用法术的、行邪术的、","notes":[]},{"n":11,"t":"用迷术的、交鬼的、行巫术的、过阴的。","notes":[]},{"n":12,"t":"凡行这些事的都为耶和华所憎恶；因那些国民行这可憎恶的事，所以耶和华—你的神将他们从你面前赶出。","notes":[]},{"n":13,"t":"你要在耶和华—你的神面前作完全人。」","notes":[]},{"n":14,"t":"「因你所要赶出的那些国民都听信观兆的和占卜的，至于你，耶和华—你的神从来不许你这样行。","notes":[],"heads":["应许兴起先知"]},{"n":15,"t":"耶和华—你的神要从你们弟兄中间给你兴起一位先知，像我，你们要听从他。","notes":[]},{"n":16,"t":"正如你在何烈山大会的日子求耶和华—你神一切的话，说：『求你不再叫我听见耶和华—我神的声音，也不再叫我看见这大火，免得我死亡。』","notes":[]},{"n":17,"t":"耶和华就对我说：『他们所说的是。","notes":[]},{"n":18,"t":"我必在他们弟兄中间给他们兴起一位先知，像你。我要将当说的话传给他；他要将我一切所吩咐的都传给他们。","notes":[]},{"n":19,"t":"谁不听他奉我名所说的话，我必讨谁的罪。","notes":[]},{"n":20,"t":"若有先知擅敢托我的名说我所未曾吩咐他说的话，或是奉别神的名说话，那先知就必治死。』","notes":[]},{"n":21,"t":"你心里若说：『耶和华所未曾吩咐的话，我们怎能知道呢？』","notes":[]},{"n":22,"t":"先知托耶和华的名说话，所说的若不成就，也无效验，这就是耶和华所未曾吩咐的，是那先知擅自说的，你不要怕他。」","notes":[]}]},"19":{"heading":"设立庇护城","verses":[{"n":1,"t":"「耶和华—你神将列国之民剪除的时候，耶和华—你神也将他们的地赐给你，你接着住他们的城邑并他们的房屋，","notes":[]},{"n":2,"t":"就要在耶和华—你神所赐你为业的地上分定三座城。","notes":[]},{"n":3,"t":"要将耶和华—你神使你承受为业的地分为三段；又要预备道路，使误杀人的，都可以逃到那里去。","notes":[]},{"n":4,"t":"「误杀人的逃到那里可以存活，定例乃是这样：凡素无仇恨，无心杀了人的，","notes":[]},{"n":5,"t":"就如人与邻舍同入树林砍伐树木，手拿斧子一砍，本想砍下树木，不料，斧头脱了把，飞落在邻舍身上，以致于死，这人逃到那些城的一座城，就可以存活，","notes":[]},{"n":6,"t":"免得报血仇的，心中火热追赶他，因路远就追上，将他杀死；其实他不该死，因为他与被杀的素无仇恨。","notes":[]},{"n":7,"t":"所以我吩咐你说，要分定三座城。","notes":[]},{"n":8,"t":"耶和华—你神若照他向你列祖所起的誓扩张你的境界，将所应许赐你列祖的地全然给你，","notes":[]},{"n":9,"t":"你若谨守遵行我今日所吩咐的这一切诫命，爱耶和华—你的神，常常遵行他的道，就要在这三座城之外，再添三座城，","notes":[]},{"n":10,"t":"免得无辜之人的血流在耶和华—你神所赐你为业的地上，流血的罪就归于你。","notes":[]},{"n":11,"t":"「若有人恨他的邻舍，埋伏着起来击杀他，以致于死，便逃到这些城的一座城，","notes":[]},{"n":12,"t":"本城的长老就要打发人去，从那里带出他来，交在报血仇的手中，将他治死。","notes":[]},{"n":13,"t":"你眼不可顾惜他，却要从以色列中除掉流无辜血的罪，使你可以得福。」","notes":[]},{"n":14,"t":"「在耶和华—你神所赐你承受为业之地，不可挪移你邻舍的地界，那是先人所定的。」","notes":[],"heads":["旧地界"]},{"n":15,"t":"「人无论犯什么罪，作什么恶，不可凭一个人的口作见证，总要凭两三个人的口作见证才可定案。","notes":[],"heads":["有关证人的条例"]},{"n":16,"t":"若有凶恶的见证人起来，见证某人作恶，","notes":[]},{"n":17,"t":"这两个争讼的人就要站在耶和华面前，和当时的祭司，并审判官面前，","notes":[]},{"n":18,"t":"审判官要细细地查究，若见证人果然是作假见证的，以假见证陷害弟兄，","notes":[]},{"n":19,"t":"你们就要待他如同他想要待的弟兄。这样，就把那恶从你们中间除掉。","notes":[]},{"n":20,"t":"别人听见都要害怕，就不敢在你们中间再行这样的恶了。","notes":[]},{"n":21,"t":"你眼不可顾惜，要以命偿命，以眼还眼，以牙还牙，以手还手，以脚还脚。」","notes":[]}]},"20":{"heading":"有关战争的条例","verses":[{"n":1,"t":"「你出去与仇敌争战的时候，看见马匹、车辆，并有比你多的人民，不要怕他们，因为领你出埃及地的耶和华—你神与你同在。","notes":[]},{"n":2,"t":"你们将要上阵的时候，祭司要到百姓面前宣告","notes":[]},{"n":3,"t":"说：『以色列人哪，你们当听，你们今日将要与仇敌争战，不要胆怯，不要惧怕战兢，也不要因他们惊恐；","notes":[]},{"n":4,"t":"因为耶和华—你们的神与你们同去，要为你们与仇敌争战，拯救你们。』","notes":[]},{"n":5,"t":"官长也要对百姓宣告说：『谁建造房屋，尚未奉献，他可以回家去，恐怕他阵亡，别人去奉献。","notes":[]},{"n":6,"t":"谁种葡萄园，尚未用所结的果子，他可以回家去，恐怕他阵亡，别人去用。","notes":[]},{"n":7,"t":"谁聘定了妻，尚未迎娶，他可以回家去，恐怕他阵亡，别人去娶。』","notes":[]},{"n":8,"t":"官长又要对百姓宣告说：『谁惧怕胆怯，他可以回家去，恐怕他弟兄的心消化，和他一样。』","notes":[]},{"n":9,"t":"官长对百姓宣告完了，就当派军长率领他们。","notes":[]},{"n":10,"t":"「你临近一座城、要攻打的时候，先要对城里的民宣告和睦的话。","notes":[]},{"n":11,"t":"他们若以和睦的话回答你，给你开了城，城里所有的人都要给你效劳，服事你；","notes":[]},{"n":12,"t":"若不肯与你和好，反要与你打仗，你就要围困那城。","notes":[]},{"n":13,"t":"耶和华—你的神把城交付你手，你就要用刀杀尽这城的男丁。","notes":[]},{"n":14,"t":"惟有妇女、孩子、牲畜，和城内一切的财物，你可以取为自己的掠物。耶和华—你神把你仇敌的财物赐给你，你可以吃用。","notes":[]},{"n":15,"t":"离你甚远的各城，不是这些国民的城，你都要这样待他。","notes":[]},{"n":16,"t":"但这些国民的城，耶和华—你神既赐你为业，其中凡有气息的，一个不可存留；","notes":[]},{"n":17,"t":"只要照耶和华—你神所吩咐的将这赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人都灭绝净尽，","notes":[]},{"n":18,"t":"免得他们教导你们学习一切可憎恶的事，就是他们向自己神所行的，以致你们得罪耶和华—你们的神。","notes":[]},{"n":19,"t":"「你若许久围困、攻打所要取的一座城，就不可举斧子砍坏树木；因为你可以吃那树上的果子，不可砍伐。田间的树木岂是人，叫你糟蹋吗？","notes":[]},{"n":20,"t":"惟独你所知道不是结果子的树木可以毁坏、砍伐，用以修筑营垒，攻击那与你打仗的城，直到攻塌了。」","notes":[]}]},"21":{"heading":"有关未结案的谋杀案件","verses":[{"n":1,"t":"「在耶和华—你神所赐你为业的地上，若遇见被杀的人倒在田野，不知道是谁杀的，","notes":[]},{"n":2,"t":"长老和审判官就要出去，从被杀的人那里量起，直量到四围的城邑，","notes":[]},{"n":3,"t":"看哪城离被杀的人最近，那城的长老就要从牛群中取一只未曾耕地、未曾负轭的母牛犊，","notes":[]},{"n":4,"t":"把母牛犊牵到流水、未曾耕种的山谷去，在谷中打折母牛犊的颈项。","notes":[]},{"n":5,"t":"祭司利未的子孙要近前来；因为耶和华—你的神拣选了他们事奉他，奉耶和华的名祝福，所有争讼殴打的事都要凭他们判断。","notes":[]},{"n":6,"t":"那城的众长老，就是离被杀的人最近的，要在那山谷中，在所打折颈项的母牛犊以上洗手，","notes":[]},{"n":7,"t":"祷告说：『我们的手未曾流这人的血；我们的眼也未曾看见这事。","notes":["原文是回答"]},{"n":8,"t":"耶和华啊，求你赦免你所救赎的以色列民，不要使流无辜血的罪归在你的百姓以色列中间。』这样，流血的罪必得赦免。","notes":[]},{"n":9,"t":"你行耶和华眼中看为正的事，就可以从你们中间除掉流无辜血的罪。」","notes":[]},{"n":10,"t":"「你出去与仇敌争战的时候，耶和华—你的神将他们交在你手中，你就掳了他们去。","notes":[],"heads":["有关女战俘的案件"]},{"n":11,"t":"若在被掳的人中见有美貌的女子，恋慕她，要娶她为妻，","notes":[]},{"n":12,"t":"就可以领她到你家里去；她便要剃头发，修指甲，","notes":[]},{"n":13,"t":"脱去被掳时所穿的衣服，住在你家里哀哭父母一个整月，然后可以与她同房。你作她的丈夫，她作你的妻子。","notes":[]},{"n":14,"t":"后来你若不喜悦她，就要由她随意出去，决不可为钱卖她，也不可当婢女待她，因为你玷污了她。」","notes":[]},{"n":15,"t":"「人若有二妻，一为所爱，一为所恶，所爱的、所恶的都给他生了儿子，但长子是所恶之妻生的。","notes":[],"heads":["有关长子的继承权"]},{"n":16,"t":"到了把产业分给儿子承受的时候，不可将所爱之妻生的儿子立为长子，在所恶之妻生的儿子以上，","notes":[]},{"n":17,"t":"却要认所恶之妻生的儿子为长子，将产业多加一分给他；因这儿子是他力量强壮的时候生的，长子的名分本当归他。」","notes":[]},{"n":18,"t":"「人若有顽梗悖逆的儿子，不听从父母的话，他们虽惩治他，他仍不听从，","notes":[],"heads":["有关逆子的处置"]},{"n":19,"t":"父母就要抓住他，将他带到本地的城门、本城的长老那里，","notes":[]},{"n":20,"t":"对长老说：『我们这儿子顽梗悖逆，不听从我们的话，是贪食好酒的人。』","notes":[]},{"n":21,"t":"本城的众人就要用石头将他打死。这样，就把那恶从你们中间除掉，以色列众人都要听见害怕。」","notes":[]},{"n":22,"t":"「人若犯该死的罪，被治死了，你将他挂在木头上，","notes":[],"heads":["其他的条例"]},{"n":23,"t":"他的尸首不可留在木头上过夜，必要当日将他葬埋，免得玷污了耶和华—你神所赐你为业之地。因为被挂的人是在神面前受咒诅的。","notes":[]}]},"22":{"heading":"有关贞洁的条例","verses":[{"n":1,"t":"「你若看见弟兄的牛或羊失迷了路，不可佯为不见，总要把它牵回来交给你的弟兄。","notes":[]},{"n":2,"t":"你弟兄若离你远，或是你不认识他，就要牵到你家去，留在你那里，等你弟兄来寻找就还给他。","notes":[]},{"n":3,"t":"你的弟兄无论失落什么，或是驴，或是衣服，你若遇见，都要这样行，不可佯为不见。","notes":[]},{"n":4,"t":"你若看见弟兄的牛或驴跌倒在路上，不可佯为不见，总要帮助他拉起来。","notes":[]},{"n":5,"t":"「妇女不可穿戴男子所穿戴的，男子也不可穿妇女的衣服，因为这样行都是耶和华—你神所憎恶的。","notes":[]},{"n":6,"t":"「你若路上遇见鸟窝，或在树上或在地上，里头有雏或有蛋，母鸟伏在雏上或在蛋上，你不可连母带雏一并取去。","notes":[]},{"n":7,"t":"总要放母，只可取雏；这样你就可以享福，日子得以长久。","notes":[]},{"n":8,"t":"「你若建造房屋，要在房上的四围安栏杆，免得有人从房上掉下来，流血的罪就归于你家。","notes":[]},{"n":9,"t":"「不可把两样种子种在你的葡萄园里，免得你撒种所结的和葡萄园的果子都要充公。","notes":[]},{"n":10,"t":"不可并用牛、驴耕地。","notes":[]},{"n":11,"t":"不可穿羊毛、细麻两样搀杂料做的衣服。","notes":[]},{"n":12,"t":"「你要在所披的外衣上四围做繸子。」","notes":[]},{"n":13,"t":"「人若娶妻，与她同房之后恨恶她，","notes":[]},{"n":14,"t":"信口说她，将丑名加在她身上，说：『我娶了这女子，与她同房，见她没有贞洁的凭据』；","notes":[]},{"n":15,"t":"女子的父母就要把女子贞洁的凭据拿出来，带到本城门长老那里。","notes":[]},{"n":16,"t":"女子的父亲要对长老说：『我将我的女儿给这人为妻，他恨恶她，","notes":[]},{"n":17,"t":"信口说她，说：我见你的女儿没有贞洁的凭据；其实这就是我女儿贞洁的凭据。』父母就把那布铺在本城的长老面前。","notes":[]},{"n":18,"t":"本城的长老要拿住那人，惩治他，","notes":[]},{"n":19,"t":"并要罚他一百舍客勒银子，给女子的父亲，因为他将丑名加在以色列的一个处女身上。女子仍作他的妻，终身不可休她。","notes":[]},{"n":20,"t":"但这事若是真的，女子没有贞洁的凭据，","notes":[]},{"n":21,"t":"就要将女子带到她父家的门口，本城的人要用石头将她打死；因为她在父家行了淫乱，在以色列中做了丑事。这样，就把那恶从你们中间除掉。","notes":[]},{"n":22,"t":"「若遇见人与有丈夫的妇人行淫，就要将奸夫淫妇一并治死。这样，就把那恶从以色列中除掉。","notes":[]},{"n":23,"t":"「若有处女已经许配丈夫，有人在城里遇见她，与她行淫，","notes":[]},{"n":24,"t":"你们就要把这二人带到本城门，用石头打死—女子是因为虽在城里却没有喊叫；男子是因为玷污别人的妻。这样，就把那恶从你们中间除掉。","notes":[]},{"n":25,"t":"「若有男子在田野遇见已经许配人的女子，强与她行淫，只要将那男子治死。","notes":[]},{"n":26,"t":"但不可办女子；她本没有该死的罪，这事就类乎人起来攻击邻舍，将他杀了一样。","notes":[]},{"n":27,"t":"因为男子是在田野遇见那已经许配人的女子，女子喊叫，并无人救她。","notes":[]},{"n":28,"t":"「若有男子遇见没有许配人的处女，抓住她，与她行淫，被人看见，","notes":[]},{"n":29,"t":"这男子就要拿五十舍客勒银子给女子的父亲；因他玷污了这女子，就要娶她为妻，终身不可休她。","notes":[]},{"n":30,"t":"「人不可娶继母为妻；不可掀开他父亲的衣襟。」","notes":[]}]},"23":{"heading":"不许进入圣会的人","verses":[{"n":1,"t":"「凡外肾受伤的，或被阉割的，不可入耶和华的会。","notes":[]},{"n":2,"t":"「私生子不可入耶和华的会；他的子孙，直到十代，也不可入耶和华的会。","notes":[]},{"n":3,"t":"「亚扪人或是摩押人不可入耶和华的会；他们的子孙，虽过十代，也永不可入耶和华的会。","notes":[]},{"n":4,"t":"因为你们出埃及的时候，他们没有拿食物和水在路上迎接你们，又因他们雇了美索不达米亚的毗夺人比珥的儿子巴兰来咒诅你们。","notes":[]},{"n":5,"t":"然而耶和华—你的神不肯听从巴兰，却使那咒诅的言语变为祝福的话，因为耶和华—你的神爱你。","notes":[]},{"n":6,"t":"你一生一世永不可求他们的平安和他们的利益。","notes":[]},{"n":7,"t":"「不可憎恶以东人，因为他是你的弟兄。不可憎恶埃及人，因为你在他的地上作过寄居的。","notes":[]},{"n":8,"t":"他们第三代子孙可以入耶和华的会。」","notes":[]},{"n":9,"t":"「你出兵攻打仇敌，就要远避诸恶。","notes":[],"heads":["保持军营的卫生"]},{"n":10,"t":"「你们中间，若有人夜间偶然梦遗，不洁净，就要出到营外，不可入营；","notes":[]},{"n":11,"t":"到傍晚的时候，他要用水洗澡，及至日落了才可以入营。","notes":[]},{"n":12,"t":"「你在营外也该定出一个地方作为便所。","notes":[]},{"n":13,"t":"在你器械之中当预备一把锹，你出营外便溺以后，用以铲土，转身掩盖。","notes":[]},{"n":14,"t":"因为耶和华—你的神常在你营中行走，要救护你，将仇敌交给你，所以你的营理当圣洁，免得他见你那里有污秽，就离开你。」","notes":[]},{"n":15,"t":"「若有奴仆脱了主人的手，逃到你那里，你不可将他交付他的主人。","notes":[],"heads":["一般条例"]},{"n":16,"t":"他必在你那里与你同住，在你的城邑中，要由他选择一个所喜悦的地方居住；你不可欺负他。","notes":[]},{"n":17,"t":"「以色列的女子中不可有妓女；以色列的男子中不可有娈童。","notes":[]},{"n":18,"t":"娼妓所得的钱，或娈童所得的价，你不可带入耶和华—你神的殿还愿，因为这两样都是耶和华—你神所憎恶的。","notes":["原文是狗"]},{"n":19,"t":"「你借给你弟兄的，或是钱财或是粮食，无论什么可生利的物，都不可取利。","notes":[]},{"n":20,"t":"借给外邦人可以取利，只是借给你弟兄不可取利。这样，耶和华—你神必在你所去得为业的地上和你手里所办的一切事上赐福与你。","notes":[]},{"n":21,"t":"「你向耶和华—你的神许愿，偿还不可迟延；因为耶和华—你的神必定向你追讨，你不偿还就有罪。","notes":[]},{"n":22,"t":"你若不许愿，倒无罪。","notes":[]},{"n":23,"t":"你嘴里所出的，就是你口中应许甘心所献的，要照你向耶和华—你神所许的愿谨守遵行。","notes":[]},{"n":24,"t":"「你进了邻舍的葡萄园，可以随意吃饱了葡萄，只是不可装在器皿中。","notes":[]},{"n":25,"t":"你进了邻舍站着的禾稼，可以用手摘穗子，只是不可用镰刀割取禾稼。」","notes":[]}]},"24":{"heading":"离婚和再婚","verses":[{"n":1,"t":"「人若娶妻以后，见她有什么不合理的事，不喜悦她，就可以写休书交在她手中，打发她离开夫家。","notes":[]},{"n":2,"t":"妇人离开夫家以后，可以去嫁别人。","notes":[]},{"n":3,"t":"后夫若恨恶她，写休书交在她手中，打发她离开夫家，或是娶她为妻的后夫死了，","notes":[]},{"n":4,"t":"打发她去的前夫不可在妇人玷污之后再娶她为妻，因为这是耶和华所憎恶的；不可使耶和华—你神所赐为业之地被玷污了。」","notes":[]},{"n":5,"t":"「新娶妻之人不可从军出征，也不可托他办理什么公事，可以在家清闲一年，使他所娶的妻快活。","notes":[],"heads":["一般条例"]},{"n":6,"t":"「不可拿人的全盘磨石或是上磨石作当头，因为这是拿人的命作当头。","notes":[]},{"n":7,"t":"「若遇见人拐带以色列中的一个弟兄，当奴才待他，或是卖了他，那拐带人的就必治死。这样，便将那恶从你们中间除掉。","notes":[]},{"n":8,"t":"「在大麻风的灾病上，你们要谨慎，照祭司利未人一切所指教你们的留意遵行。我怎样吩咐他们，你们要怎样遵行。","notes":[]},{"n":9,"t":"当记念出埃及后，在路上，耶和华—你神向米利暗所行的事。","notes":[]},{"n":10,"t":"「你借给邻舍，不拘是什么，不可进他家拿他的当头。","notes":[]},{"n":11,"t":"要站在外面，等那向你借贷的人把当头拿出来交给你。","notes":[]},{"n":12,"t":"他若是穷人，你不可留他的当头过夜。","notes":[]},{"n":13,"t":"日落的时候，总要把当头还他，使他用那件衣服盖着睡觉，他就为你祝福；这在耶和华—你神面前就是你的义了。","notes":[]},{"n":14,"t":"「困苦穷乏的雇工，无论是你的弟兄或是在你城里寄居的，你不可欺负他。","notes":[]},{"n":15,"t":"要当日给他工价，不可等到日落—因为他穷苦，把心放在工价上—恐怕他因你求告耶和华，罪便归你了。","notes":[]},{"n":16,"t":"「不可因子杀父，也不可因父杀子；凡被杀的都为本身的罪。","notes":[]},{"n":17,"t":"「你不可向寄居的和孤儿屈枉正直，也不可拿寡妇的衣裳作当头。","notes":[]},{"n":18,"t":"要记念你在埃及作过奴仆。耶和华—你的神从那里将你救赎，所以我吩咐你这样行。","notes":[]},{"n":19,"t":"「你在田间收割庄稼，若忘下一捆，不可回去再取，要留给寄居的与孤儿寡妇。这样，耶和华—你神必在你手里所办的一切事上赐福与你。","notes":[]},{"n":20,"t":"你打橄榄树，枝上剩下的，不可再打；要留给寄居的与孤儿寡妇。","notes":[]},{"n":21,"t":"你摘葡萄园的葡萄，所剩下的，不可再摘；要留给寄居的与孤儿寡妇。","notes":[]},{"n":22,"t":"你也要记念你在埃及地作过奴仆，所以我吩咐你这样行。","notes":[]}]},"25":{"heading":"对丧亡的弟兄传宗接代","verses":[{"n":1,"t":"「人若有争讼，来听审判，审判官就要定义人有理，定恶人有罪。","notes":[]},{"n":2,"t":"恶人若该受责打，审判官就要叫他当面伏在地上，按着他的罪照数责打。","notes":[]},{"n":3,"t":"只可打他四十下，不可过数；若过数，便是轻贱你的弟兄了。","notes":[]},{"n":4,"t":"「牛在场上踹谷的时候，不可笼住它的嘴。」","notes":[]},{"n":5,"t":"「弟兄同居，若死了一个，没有儿子，死人的妻不可出嫁外人，她丈夫的兄弟当尽弟兄的本分，娶她为妻，与她同房。","notes":[]},{"n":6,"t":"妇人生的长子必归死兄的名下，免得他的名在以色列中涂抹了。","notes":[]},{"n":7,"t":"那人若不愿意娶她哥哥的妻，他哥哥的妻就要到城门长老那里，说：『我丈夫的兄弟不肯在以色列中兴起他哥哥的名字，不给我尽弟兄的本分。』","notes":[]},{"n":8,"t":"本城的长老就要召那人来问他，他若执意说：『我不愿意娶她』，","notes":[]},{"n":9,"t":"他哥哥的妻就要当着长老到那人的跟前，脱了他的鞋，吐唾沫在他脸上，说：『凡不为哥哥建立家室的都要这样待他。』","notes":[]},{"n":10,"t":"在以色列中，他的名必称为脱鞋之家。」","notes":[]},{"n":11,"t":"「若有二人争斗，这人的妻近前来，要救她丈夫脱离那打她丈夫之人的手，抓住那人的下体，","notes":[],"heads":["其他的条例"]},{"n":12,"t":"就要砍断妇人的手，眼不可顾惜她。","notes":[]},{"n":13,"t":"「你囊中不可有一大一小两样的法码。","notes":[]},{"n":14,"t":"你家里不可有一大一小两样的升斗。","notes":[]},{"n":15,"t":"当用对准公平的法码，公平的升斗。这样，在耶和华—你神所赐你的地上，你的日子就可以长久。","notes":[]},{"n":16,"t":"因为行非义之事的人都是耶和华—你神所憎恶的。」","notes":[]},{"n":17,"t":"「你要记念你们出埃及的时候，亚玛力人在路上怎样待你。","notes":[],"heads":["命令百姓消灭亚玛力人"]},{"n":18,"t":"他们在路上遇见你，趁你疲乏困倦击杀你尽后边软弱的人，并不敬畏神。","notes":[]},{"n":19,"t":"所以耶和华—你神使你不被四围一切的仇敌扰乱，在耶和华—你神赐你为业的地上得享平安。那时，你要将亚玛力的名号从天下涂抹了，不可忘记。」","notes":[]}]},"26":{"heading":"奉献初熟的土产","verses":[{"n":1,"t":"「你进去得了耶和华—你神所赐你为业之地居住，","notes":[]},{"n":2,"t":"就要从耶和华—你神赐你的地上将所收的各种初熟的土产取些来，盛在筐子里，往耶和华—你神所选择要立为他名的居所去，","notes":[]},{"n":3,"t":"见当时作祭司的，对他说：『我今日向耶和华—你神明认，我已来到耶和华向我们列祖起誓应许赐给我们的地。』","notes":[]},{"n":4,"t":"祭司就从你手里取过筐子来，放在耶和华—你神的坛前。","notes":[]},{"n":5,"t":"你要在耶和华—你神面前说：『我祖原是一个将亡的亚兰人，下到埃及寄居。他人口稀少，在那里却成了又大又强、人数很多的国民。","notes":[]},{"n":6,"t":"埃及人恶待我们，苦害我们，将苦工加在我们身上。","notes":[]},{"n":7,"t":"于是我们哀求耶和华—我们列祖的神，耶和华听见我们的声音，看见我们所受的困苦、劳碌、欺压，","notes":[]},{"n":8,"t":"他就用大能的手和伸出来的膀臂，并大可畏的事与神迹奇事，领我们出了埃及，","notes":[]},{"n":9,"t":"将我们领进这地方，把这流奶与蜜之地赐给我们。","notes":[]},{"n":10,"t":"耶和华啊，现在我把你所赐给我地上初熟的土产奉了来。』随后你要把筐子放在耶和华—你神面前，向耶和华—你的神下拜。","notes":[]},{"n":11,"t":"你和利未人，并在你们中间寄居的，要因耶和华—你神所赐你和你家的一切福分欢乐。","notes":[]},{"n":12,"t":"「每逢三年，就是十分取一之年，你取完了一切土产的十分之一，要分给利未人和寄居的，与孤儿寡妇，使他们在你城中可以吃得饱足。","notes":[]},{"n":13,"t":"你又要在耶和华—你神面前说：『我已将圣物从我家里拿出来，给了利未人和寄居的，与孤儿寡妇，是照你所吩咐我的一切命令。你的命令我都没有违背，也没有忘记。","notes":[]},{"n":14,"t":"我守丧的时候，没有吃这圣物；不洁净的时候，也没有拿出来，又没有为死人送去。我听从了耶和华—我神的话，都照你所吩咐的行了。","notes":[]},{"n":15,"t":"求你从天上、你的圣所垂看，赐福给你的百姓以色列与你所赐给我们的地，就是你向我们列祖起誓赐我们流奶与蜜之地。』」","notes":[]},{"n":16,"t":"「耶和华—你的神今日吩咐你行这些律例典章，所以你要尽心尽性谨守遵行。","notes":[],"heads":["作圣洁的子民"]},{"n":17,"t":"你今日认耶和华为你的神，应许遵行他的道，谨守他的律例、诫命、典章，听从他的话。","notes":[]},{"n":18,"t":"耶和华今日照他所应许你的，也认你为他的子民，使你谨守他的一切诫命，","notes":[]},{"n":19,"t":"又使你得称赞、美名、尊荣，超乎他所造的万民之上，并照他所应许的使你归耶和华—你神为圣洁的民。」","notes":[]}]},"27":{"heading":"神的律法写在石头上","verses":[{"n":1,"t":"摩西和以色列的众长老吩咐百姓说：「你们要遵守我今日所吩咐的一切诫命。","notes":[]},{"n":2,"t":"你们过约旦河，到了耶和华—你神所赐给你的地，当天要立起几块大石头，墁上石灰，","notes":[]},{"n":3,"t":"把这律法的一切话写在石头上。你过了河，可以进入耶和华—你神所赐你流奶与蜜之地，正如耶和华—你列祖之神所应许你的。","notes":[]},{"n":4,"t":"你们过了约旦河，就要在以巴路山上照我今日所吩咐的，将这些石头立起来，墁上石灰。","notes":[]},{"n":5,"t":"在那里要为耶和华—你的神筑一座石坛；在石头上不可动铁器。","notes":[]},{"n":6,"t":"要用没有凿过的石头筑耶和华—你神的坛，在坛上要将燔祭献给耶和华—你的神。","notes":[]},{"n":7,"t":"又要献平安祭，且在那里吃，在耶和华—你的神面前欢乐。","notes":[]},{"n":8,"t":"你要将这律法的一切话明明地写在石头上。」","notes":[]},{"n":9,"t":"摩西和祭司利未人晓谕以色列众人说：「以色列啊，要默默静听。你今日成为耶和华—你神的百姓了。","notes":[]},{"n":10,"t":"所以要听从耶和华—你神的话，遵行他的诫命律例，就是我今日所吩咐你的。」","notes":[]},{"n":11,"t":"当日，摩西嘱咐百姓说：","notes":[],"heads":["违命必受咒诅"]},{"n":12,"t":"「你们过了约旦河，西缅、利未、犹大、以萨迦、约瑟、便雅悯六个支派的人都要站在基利心山上为百姓祝福。","notes":[]},{"n":13,"t":"吕便、迦得、亚设、西布伦、但、拿弗他利六个支派的人都要站在以巴路山上宣布咒诅。","notes":[]},{"n":14,"t":"利未人要向以色列众人高声说：","notes":[]},{"n":15,"t":"「『有人制造耶和华所憎恶的偶像，或雕刻，或铸造，就是工匠手所做的，在暗中设立，那人必受咒诅！』百姓都要答应说：『阿们！』","notes":[]},{"n":16,"t":"「『轻慢父母的，必受咒诅！』百姓都要说：『阿们！』","notes":[]},{"n":17,"t":"「『挪移邻舍地界的，必受咒诅！』百姓都要说：『阿们！』","notes":[]},{"n":18,"t":"「『使瞎子走差路的，必受咒诅！』百姓都要说：『阿们！』","notes":[]},{"n":19,"t":"「『向寄居的和孤儿寡妇屈枉正直的，必受咒诅！』百姓都要说：『阿们！』","notes":[]},{"n":20,"t":"「『与继母行淫的，必受咒诅！因为掀开他父亲的衣襟。』百姓都要说：『阿们！』","notes":[]},{"n":21,"t":"「『与兽淫合的，必受咒诅！』百姓都要说：『阿们！』","notes":[]},{"n":22,"t":"「『与异母同父，或异父同母的姊妹行淫的，必受咒诅！』百姓都要说：『阿们！』","notes":[]},{"n":23,"t":"「『与岳母行淫的，必受咒诅！』百姓都要说：『阿们！』","notes":[]},{"n":24,"t":"「『暗中杀人的，必受咒诅！』百姓都要说：『阿们！』","notes":[]},{"n":25,"t":"「『受贿赂害死无辜之人的，必受咒诅！』百姓都要说：『阿们！』","notes":[]},{"n":26,"t":"「『不坚守遵行这律法言语的，必受咒诅！』百姓都要说：『阿们！』」","notes":[]}]},"28":{"heading":"遵行诫命蒙福","verses":[{"n":1,"t":"「你若留意听从耶和华—你神的话，谨守遵行他的一切诫命，就是我今日所吩咐你的，他必使你超乎天下万民之上。","notes":[]},{"n":2,"t":"你若听从耶和华—你神的话，这以下的福必追随你，临到你身上：","notes":[]},{"n":3,"t":"你在城里必蒙福，在田间也必蒙福。","notes":[]},{"n":4,"t":"你身所生的，地所产的，牲畜所下的，以及牛犊、羊羔，都必蒙福。","notes":[]},{"n":5,"t":"你的筐子和你的抟面盆都必蒙福。","notes":[]},{"n":6,"t":"你出也蒙福，入也蒙福。","notes":[]},{"n":7,"t":"「仇敌起来攻击你，耶和华必使他们在你面前被你杀败；他们从一条路来攻击你，必从七条路逃跑。","notes":[]},{"n":8,"t":"在你仓房里，并你手所办的一切事上，耶和华所命的福必临到你。耶和华—你神也要在所给你的地上赐福与你。","notes":[]},{"n":9,"t":"你若谨守耶和华—你神的诫命，遵行他的道，他必照着向你所起的誓立你作为自己的圣民。","notes":[]},{"n":10,"t":"天下万民见你归在耶和华的名下，就要惧怕你。","notes":[]},{"n":11,"t":"你在耶和华向你列祖起誓应许赐你的地上，他必使你身所生的，牲畜所下的，地所产的，都绰绰有余。","notes":[]},{"n":12,"t":"耶和华必为你开天上的府库，按时降雨在你的地上。在你手里所办的一切事上赐福与你。你必借给许多国民，却不致向他们借贷。","notes":[]},{"n":13,"t":"你若听从耶和华—你神的诫命，就是我今日所吩咐你的，谨守遵行，不偏左右，也不随从事奉别神，耶和华就必使你作首不作尾，但居上不居下。」","notes":[],"end":14},{"n":15,"t":"「你若不听从耶和华—你神的话，不谨守遵行他的一切诫命律例，就是我今日所吩咐你的，这以下的咒诅都必追随你，临到你身上：","notes":[],"heads":["悖逆的后果"]},{"n":16,"t":"你在城里必受咒诅，在田间也必受咒诅。","notes":[]},{"n":17,"t":"你的筐子和你的抟面盆都必受咒诅。","notes":[]},{"n":18,"t":"你身所生的，地所产的，以及牛犊、羊羔，都必受咒诅。","notes":[]},{"n":19,"t":"你出也受咒诅，入也受咒诅。","notes":[]},{"n":20,"t":"耶和华因你行恶离弃他，必在你手里所办的一切事上，使咒诅、扰乱、责罚临到你，直到你被毁灭，速速地灭亡。","notes":[]},{"n":21,"t":"耶和华必使瘟疫贴在你身上，直到他将你从所进去得为业的地上灭绝。","notes":[]},{"n":22,"t":"耶和华要用痨病、热病、火症、疟疾、刀剑、旱风、霉烂攻击你。这都要追赶你，直到你灭亡。","notes":["或译：干旱"]},{"n":23,"t":"你头上的天要变为铜，脚下的地要变为铁。","notes":[]},{"n":24,"t":"耶和华要使那降在你地上的雨变为尘沙，从天临在你身上，直到你灭亡。","notes":[]},{"n":25,"t":"「耶和华必使你败在仇敌面前，你从一条路去攻击他们，必从七条路逃跑。你必在天下万国中抛来抛去。","notes":[]},{"n":26,"t":"你的尸首必给空中的飞鸟和地上的走兽作食物，并无人哄赶。","notes":[]},{"n":27,"t":"耶和华必用埃及人的疮并痔疮、牛皮癣与疥攻击你，使你不能医治。","notes":[]},{"n":28,"t":"耶和华必用癫狂、眼瞎、心惊攻击你。","notes":[]},{"n":29,"t":"你必在午间摸索，好像瞎子在暗中摸索一样。你所行的必不亨通，时常遭遇欺压、抢夺，无人搭救。","notes":[]},{"n":30,"t":"你聘定了妻，别人必与她同房；你建造房屋，不得住在其内；你栽种葡萄园，也不得用其中的果子。","notes":[]},{"n":31,"t":"你的牛在你眼前宰了，你必不得吃它的肉；你的驴在你眼前被抢夺，不得归还；你的羊归了仇敌，无人搭救。","notes":[]},{"n":32,"t":"你的儿女必归与别国的民；你的眼目终日切望，甚至失明，你手中无力拯救。","notes":[]},{"n":33,"t":"你的土产和你劳碌得来的，必被你所不认识的国民吃尽。你时常被欺负，受压制，","notes":[]},{"n":34,"t":"甚至你因眼中所看见的，必致疯狂。","notes":[]},{"n":35,"t":"耶和华必攻击你，使你膝上腿上，从脚掌到头顶，长毒疮无法医治。","notes":[]},{"n":36,"t":"「耶和华必将你和你所立的王领到你和你列祖素不认识的国去；在那里你必事奉木头石头的神。","notes":[]},{"n":37,"t":"你在耶和华领你到的各国中，要令人惊骇、笑谈、讥诮。","notes":[]},{"n":38,"t":"你带到田间的种子虽多，收进来的却少，因为被蝗虫吃了。","notes":[]},{"n":39,"t":"你栽种、修理葡萄园，却不得收葡萄，也不得喝葡萄酒，因为被虫子吃了。","notes":[]},{"n":40,"t":"你全境有橄榄树，却不得其油抹身，因为树上的橄榄不熟自落了。","notes":[]},{"n":41,"t":"你生儿养女，却不算是你的，因为必被掳去。","notes":[]},{"n":42,"t":"你所有的树木和你地里的出产必被蝗虫所吃。","notes":[]},{"n":43,"t":"在你中间寄居的，必渐渐上升，比你高而又高；你必渐渐下降，低而又低。","notes":[]},{"n":44,"t":"他必借给你，你却不能借给他；他必作首，你必作尾。","notes":[]},{"n":45,"t":"这一切咒诅必追随你，赶上你，直到你灭亡；因为你不听从耶和华—你神的话，不遵守他所吩咐的诫命律例。","notes":[]},{"n":46,"t":"这些咒诅必在你和你后裔的身上成为异迹奇事，直到永远！","notes":[]},{"n":47,"t":"「因为你富有的时候，不欢心乐意地事奉耶和华—你的神，","notes":[]},{"n":48,"t":"所以你必在饥饿、干渴、赤露、缺乏之中事奉耶和华所打发来攻击你的仇敌。他必把铁轭加在你的颈项上，直到将你灭绝。","notes":[]},{"n":49,"t":"「耶和华要从远方、地极带一国的民，如鹰飞来攻击你。这民的言语，你不懂得。","notes":[]},{"n":50,"t":"这民的面貌凶恶，不顾恤年老的，也不恩待年少的。","notes":[]},{"n":51,"t":"他们必吃你牲畜所下的和你地土所产的，直到你灭亡。你的五谷、新酒，和油，以及牛犊、羊羔，都不给你留下，直到将你灭绝。","notes":[]},{"n":52,"t":"他们必将你困在你各城里，直到你所倚靠、高大坚固的城墙都被攻塌。他们必将你困在耶和华—你神所赐你遍地的各城里。","notes":[]},{"n":53,"t":"你在仇敌围困窘迫之中，必吃你本身所生的，就是耶和华—你神所赐给你的儿女之肉。","notes":[]},{"n":54,"t":"你们中间，柔弱娇嫩的人必恶眼看他弟兄和他怀中的妻，并他余剩的儿女；","notes":[]},{"n":55,"t":"甚至在你受仇敌围困窘迫的城中，他要吃儿女的肉，不肯分一点给他的亲人，因为他一无所剩。","notes":[]},{"n":56,"t":"你们中间，柔弱娇嫩的妇人，是因娇嫩柔弱不肯把脚踏地的，必恶眼看她怀中的丈夫和她的儿女。","notes":[]},{"n":57,"t":"她两腿中间出来的婴孩与她所要生的儿女，她因缺乏一切就要在你受仇敌围困窘迫的城中将他们暗暗地吃了。","notes":[]},{"n":58,"t":"「这书上所写律法的一切话是叫你敬畏耶和华—你神可荣可畏的名。你若不谨守遵行，耶和华就必将奇灾，就是至大至长的灾，至重至久的病，加在你和你后裔的身上，","notes":[],"end":59},{"n":60,"t":"也必使你所惧怕、埃及人的病都临到你，贴在你身上，","notes":[]},{"n":61,"t":"又必将没有写在这律法书上的各样疾病、灾殃降在你身上，直到你灭亡。","notes":[]},{"n":62,"t":"你们先前虽然像天上的星那样多，却因不听从耶和华—你神的话，所剩的人数就稀少了。","notes":[]},{"n":63,"t":"先前耶和华怎样喜悦善待你们，使你们众多，也要照样喜悦毁灭你们，使你们灭亡；并且你们从所要进去得的地上必被拔除。","notes":[]},{"n":64,"t":"耶和华必使你们分散在万民中，从地这边到地那边，你必在那里事奉你和你列祖素不认识、木头石头的神。","notes":[]},{"n":65,"t":"在那些国中，你必不得安逸，也不得落脚之地；耶和华却使你在那里心中跳动，眼目失明，精神消耗。","notes":[]},{"n":66,"t":"你的性命必悬悬无定；你昼夜恐惧，自料性命难保。","notes":[]},{"n":67,"t":"你因心里所恐惧的，眼中所看见的，早晨必说，巴不得到晚上才好；晚上必说，巴不得到早晨才好。","notes":[]},{"n":68,"t":"耶和华必使你坐船回埃及去，走我曾告诉你不得再见的路；在那里你必卖己身与仇敌作奴婢，却无人买。」","notes":[]}]},"29":{"heading":"在摩押跟以色列人立约","verses":[{"n":1,"t":"这是耶和华在摩押地吩咐摩西与以色列人立约的话，是在他和他们于何烈山所立的约之外。","notes":[]},{"n":2,"t":"摩西召了以色列众人来，对他们说：「耶和华在埃及地，在你们眼前向法老和他众臣仆，并他全地所行的一切事，你们都看见了，","notes":[]},{"n":3,"t":"就是你亲眼看见的大试验和神迹，并那些大奇事。","notes":[]},{"n":4,"t":"但耶和华到今日没有使你们心能明白，眼能看见，耳能听见。","notes":[]},{"n":5,"t":"我领你们在旷野四十年，你们身上的衣服并没有穿破，脚上的鞋也没有穿坏。","notes":[]},{"n":6,"t":"你们没有吃饼，也没有喝清酒浓酒。这要使你们知道，耶和华是你们的神。","notes":[]},{"n":7,"t":"你们来到这地方，希实本王西宏、巴珊王噩都出来与我们交战，我们就击杀了他们，","notes":[]},{"n":8,"t":"取了他们的地给吕便支派、迦得支派，和玛拿西半支派为业。","notes":[]},{"n":9,"t":"所以你们要谨守遵行这约的话，好叫你们在一切所行的事上亨通。","notes":[]},{"n":10,"t":"「今日，你们的首领、族长、长老、官长、以色列的男丁，你们的妻子儿女，和营中寄居的，以及为你们劈柴挑水的人，都站在耶和华—你们的神面前，","notes":["原文是支派"],"end":11},{"n":12,"t":"为要你顺从耶和华—你神今日与你所立的约，向你所起的誓。","notes":[]},{"n":13,"t":"这样，他要照他向你所应许的话，又向你列祖亚伯拉罕、以撒、雅各所起的誓，今日立你作他的子民，他作你的神。","notes":[]},{"n":14,"t":"我不但与你们立这约，起这誓，","notes":[]},{"n":15,"t":"凡与我们一同站在耶和华—我们神面前的，并今日不在我们这里的人，我也与他们立这约，起这誓。","notes":[]},{"n":16,"t":"「我们曾住过埃及地，也从列国经过；这是你们知道的。","notes":[]},{"n":17,"t":"你们也看见他们中间可憎之物，并他们木、石、金、银的偶像。","notes":[]},{"n":18,"t":"惟恐你们中间，或男或女，或族长或支派长，今日心里偏离耶和华—我们的神，去事奉那些国的神；又怕你们中间有恶根生出苦菜和茵陈来，","notes":[]},{"n":19,"t":"听见这咒诅的话，心里仍是自夸说：『我虽然行事心里顽梗，连累众人，却还是平安。』","notes":[]},{"n":20,"t":"耶和华必不饶恕他；耶和华的怒气与愤恨要向他发作，如烟冒出，将这书上所写的一切咒诅都加在他身上。耶和华又要从天下涂抹他的名，","notes":[]},{"n":21,"t":"也必照着写在律法书上、约中的一切咒诅将他从以色列众支派中分别出来，使他受祸。","notes":[]},{"n":22,"t":"你们的后代，就是以后兴起来的子孙，和远方来的外人，看见这地的灾殃，并耶和华所降与这地的疾病，","notes":[]},{"n":23,"t":"又看见遍地有硫磺，有盐卤，有火迹，没有耕种，没有出产，连草都不生长—好像耶和华在忿怒中所倾覆的所多玛、蛾摩拉、押玛、洗扁一样—","notes":[]},{"n":24,"t":"所看见的人，连万国人，都必问说：『耶和华为何向此地这样行呢？这样大发烈怒是什么意思呢？』","notes":[]},{"n":25,"t":"人必回答说：『是因这地的人离弃了耶和华—他们列祖的神，领他们出埃及地的时候与他们所立的约，","notes":[]},{"n":26,"t":"去事奉敬拜素不认识的别神，是耶和华所未曾给他们安排的。","notes":[]},{"n":27,"t":"所以耶和华的怒气向这地发作，将这书上所写的一切咒诅都降在这地上。","notes":[]},{"n":28,"t":"耶和华在怒气、忿怒、大恼恨中将他们从本地拔出来，扔在别的地上，像今日一样。』","notes":[]},{"n":29,"t":"「隐秘的事是属耶和华—我们神的；惟有明显的事是永远属我们和我们子孙的，好叫我们遵行这律法上的一切话。」","notes":[]}]},"30":{"heading":"复兴和蒙福的条件","verses":[{"n":1,"t":"「我所陈明在你面前的这一切咒诅都临到你身上；你在耶和华—你神追赶你到的万国中必心里追念祝福的话；","notes":[]},{"n":2,"t":"你和你的子孙若尽心尽性归向耶和华—你的神，照着我今日一切所吩咐的听从他的话；","notes":[]},{"n":3,"t":"那时，耶和华—你的神必怜恤你，救回你这被掳的子民；耶和华—你的神要回转过来，从分散你到的万民中将你招聚回来。","notes":[]},{"n":4,"t":"你被赶散的人，就是在天涯的，耶和华—你的神也必从那里将你招聚回来。","notes":[]},{"n":5,"t":"耶和华—你的神必领你进入你列祖所得的地，使你可以得着；又必善待你，使你的人数比你列祖众多。","notes":[]},{"n":6,"t":"耶和华—你神必将你心里和你后裔心里的污秽除掉，好叫你尽心尽性爱耶和华—你的神，使你可以存活。","notes":[]},{"n":7,"t":"耶和华—你的神必将这一切咒诅加在你仇敌和恨恶你、逼迫你的人身上。","notes":[]},{"n":8,"t":"你必归回，听从耶和华的话，遵行他的一切诫命，就是我今日所吩咐你的。","notes":[]},{"n":9,"t":"你若听从耶和华—你神的话，谨守这律法书上所写的诫命律例，又尽心尽性归向耶和华—你的神，他必使你手里所办的一切事，并你身所生的，牲畜所下的，地土所产的，都绰绰有余；因为耶和华必再喜悦你，降福与你，像从前喜悦你列祖一样。","notes":[],"end":10},{"n":11,"t":"「我今日所吩咐你的诫命不是你难行的，也不是离你远的；","notes":[]},{"n":12,"t":"不是在天上，使你说：『谁替我们上天取下来，使我们听见可以遵行呢？』","notes":[]},{"n":13,"t":"也不是在海外，使你说：『谁替我们过海取了来，使我们听见可以遵行呢？』","notes":[]},{"n":14,"t":"这话却离你甚近，就在你口中，在你心里，使你可以遵行。","notes":[]},{"n":15,"t":"「看哪，我今日将生与福，死与祸，陈明在你面前。","notes":[]},{"n":16,"t":"吩咐你爱耶和华—你的神，遵行他的道，谨守他的诫命、律例、典章，使你可以存活，人数增多，耶和华—你神就必在你所要进去得为业的地上赐福与你。","notes":[]},{"n":17,"t":"倘若你心里偏离，不肯听从，却被勾引去敬拜事奉别神，","notes":[]},{"n":18,"t":"我今日明明告诉你们，你们必要灭亡；在你过约旦河、进去得为业的地上，你的日子必不长久。","notes":[]},{"n":19,"t":"我今日呼天唤地向你作见证；我将生死祸福陈明在你面前，所以你要拣选生命，使你和你的后裔都得存活；","notes":[]},{"n":20,"t":"且爱耶和华—你的神，听从他的话，专靠他；因为他是你的生命，你的日子长久也在乎他。这样，你就可以在耶和华向你列祖亚伯拉罕、以撒、雅各起誓应许所赐的地上居住。」","notes":[]}]},"31":{"heading":"约书亚继承摩西","verses":[{"n":1,"t":"摩西去告诉以色列众人","notes":[]},{"n":2,"t":"说：「我现在一百二十岁了，不能照常出入；耶和华也曾对我说：『你必不得过这约旦河。』","notes":[]},{"n":3,"t":"耶和华—你们的神必引导你们过去，将这些国民在你们面前灭绝，你们就得他们的地。约书亚必引导你们过去，正如耶和华所说的。","notes":[]},{"n":4,"t":"耶和华必待他们，如同从前待他所灭绝的亚摩利二王西宏与噩以及他们的国一样。","notes":[]},{"n":5,"t":"耶和华必将他们交给你们；你们要照我所吩咐的一切命令待他们。","notes":[]},{"n":6,"t":"你们当刚强壮胆，不要害怕，也不要畏惧他们，因为耶和华—你的神和你同去。他必不撇下你，也不丢弃你。」","notes":[]},{"n":7,"t":"摩西召了约书亚来，在以色列众人眼前对他说：「你当刚强壮胆！因为，你要和这百姓一同进入耶和华向他们列祖起誓应许所赐之地；你也要使他们承受那地为业。","notes":[]},{"n":8,"t":"耶和华必在你前面行；他必与你同在，必不撇下你，也不丢弃你。不要惧怕，也不要惊惶。」","notes":[]},{"n":9,"t":"摩西将这律法写出来，交给抬耶和华约柜的祭司利未子孙和以色列的众长老。","notes":[],"heads":["每七年诵读律法一次"]},{"n":10,"t":"摩西吩咐他们说：「每逢七年的末一年，就在豁免年的定期住棚节的时候，","notes":[]},{"n":11,"t":"以色列众人来到耶和华—你神所选择的地方朝见他。那时，你要在以色列众人面前将这律法念给他们听。","notes":[]},{"n":12,"t":"要招聚他们男、女、孩子，并城里寄居的，使他们听，使他们学习，好敬畏耶和华—你们的神，谨守、遵行这律法的一切话，","notes":[]},{"n":13,"t":"也使他们未曾晓得这律法的儿女得以听见，学习敬畏耶和华—你们的神，在你们过约旦河要得为业之地，存活的日子，常常这样行。」","notes":[]},{"n":14,"t":"耶和华对摩西说：「你的死期临近了；要召约书亚来，你们二人站在会幕里，我好嘱咐他。」于是摩西和约书亚去站在会幕里。","notes":[],"heads":["对摩西和约书亚的最后嘱咐"]},{"n":15,"t":"耶和华在会幕里云柱中显现，云柱停在会幕门以上。","notes":[]},{"n":16,"t":"耶和华又对摩西说：「你必和你列祖同睡。这百姓要起来，在他们所要去的地上，在那地的人中，随从外邦神行邪淫，离弃我，违背我与他们所立的约。","notes":[]},{"n":17,"t":"那时，我的怒气必向他们发作；我也必离弃他们，掩面不顾他们，以致他们被吞灭，并有许多的祸患灾难临到他们。那日他们必说：『这些祸患临到我们，岂不是因我们的神不在我们中间吗？』","notes":[]},{"n":18,"t":"那时，因他们偏向别神所行的一切恶，我必定掩面不顾他们。","notes":[]},{"n":19,"t":"现在你要写一篇歌，教导以色列人，传给他们，使这歌见证他们的不是；","notes":[]},{"n":20,"t":"因为我将他们领进我向他们列祖起誓应许那流奶与蜜之地，他们在那里吃得饱足，身体肥胖，就必偏向别神，事奉他们，藐视我，背弃我的约。","notes":[]},{"n":21,"t":"那时，有许多祸患灾难临到他们，这歌必在他们面前作见证，他们后裔的口中必念诵不忘。我未领他们到我所起誓应许之地以先，他们所怀的意念我都知道了。」","notes":[]},{"n":22,"t":"当日摩西就写了一篇歌，教导以色列人。","notes":[]},{"n":23,"t":"耶和华嘱咐嫩的儿子约书亚说：「你当刚强壮胆，因为你必领以色列人进我所起誓应许他们的地；我必与你同在。」","notes":[]},{"n":24,"t":"摩西将这律法的话写在书上，及至写完了，","notes":[]},{"n":25,"t":"就吩咐抬耶和华约柜的利未人说：","notes":[]},{"n":26,"t":"「将这律法书放在耶和华—你们神的约柜旁，可以在那里见证以色列人的不是；","notes":[]},{"n":27,"t":"因为我知道你们是悖逆的，是硬着颈项的。我今日还活着与你们同在，你们尚且悖逆耶和华，何况我死后呢？","notes":[]},{"n":28,"t":"你们要将你们支派的众长老和官长都招聚了来，我好将这些话说与他们听，并呼天唤地见证他们的不是。","notes":[]},{"n":29,"t":"我知道我死后，你们必全然败坏，偏离我所吩咐你们的道，行耶和华眼中看为恶的事，以手所做的惹他发怒；日后必有祸患临到你们。」","notes":[]},{"n":30,"t":"摩西将这一篇歌的话都说与以色列全会众听。","notes":[],"heads":["摩西的歌"]}]},"32":{"heading":"摩西的最后训言","verses":[{"n":1,"t":"诸天哪，侧耳，我要说话；愿地也听我口中的言语。","notes":[]},{"n":2,"t":"我的教训要淋漓如雨；我的言语要滴落如露，如细雨降在嫩草上，如甘霖降在菜蔬中。","notes":[]},{"n":3,"t":"我要宣告耶和华的名；你们要将大德归与我们的神。","notes":[]},{"n":4,"t":"他是磐石，他的作为完全；他所行的无不公平，是诚实无伪的神，又公义，又正直。","notes":[]},{"n":5,"t":"这乖僻弯曲的世代向他行事邪僻；有这弊病就不是他的儿女。","notes":[]},{"n":6,"t":"愚昧无知的民哪，你们这样报答耶和华吗？他岂不是你的父、将你买来的吗？他是制造你、建立你的。","notes":[]},{"n":7,"t":"你当追想上古之日，思念历代之年；问你的父亲，他必指示你；问你的长者，他必告诉你。","notes":[]},{"n":8,"t":"至高者将地业赐给列邦，将世人分开，就照以色列人的数目立定万民的疆界。","notes":[]},{"n":9,"t":"耶和华的分本是他的百姓；他的产业本是雅各。","notes":[]},{"n":10,"t":"耶和华遇见他在旷野—荒凉野兽吼叫之地，就环绕他，看顾他，保护他，如同保护眼中的瞳人。","notes":[]},{"n":11,"t":"又如鹰搅动巢窝，在雏鹰以上两翅搧展，接取雏鹰，背在两翼之上。","notes":[]},{"n":12,"t":"这样，耶和华独自引导他，并无外邦神与他同在。","notes":[]},{"n":13,"t":"耶和华使他乘驾地的高处，得吃田间的土产；又使他从磐石中咂蜜，从坚石中吸油；","notes":[]},{"n":14,"t":"也吃牛的奶油，羊的奶，羊羔的脂油，巴珊所出的公绵羊和山羊，与上好的麦子，也喝葡萄汁酿的酒。","notes":[]},{"n":15,"t":"但耶书仑渐渐肥胖，粗壮，光润，踢跳，奔跑，便离弃造他的神，轻看救他的磐石；","notes":[]},{"n":16,"t":"敬拜别神，触动神的愤恨，行可憎恶的事，惹了他的怒气。","notes":[]},{"n":17,"t":"所祭祀的鬼魔并非真神，乃是素不认识的神，是近来新兴的，是你列祖所不畏惧的。","notes":[]},{"n":18,"t":"你轻忽生你的磐石，忘记产你的神。","notes":[]},{"n":19,"t":"耶和华看见他的儿女惹动他，就厌恶他们，说：","notes":[]},{"n":20,"t":"我要向他们掩面，看他们的结局如何。他们本是极乖僻的族类，心中无诚实的儿女。","notes":[]},{"n":21,"t":"他们以那「不算为神」的触动我的愤恨，以虚无的神惹了我的怒气。我也要以那「不成子民」的触动他们的愤恨，以愚昧的国民惹了他们的怒气。","notes":[]},{"n":22,"t":"因为在我怒中有火烧起，直烧到极深的阴间，把地和地的出产尽都焚烧，山的根基也烧着了。","notes":[]},{"n":23,"t":"我要将祸患堆在他们身上，把我的箭向他们射尽。","notes":[]},{"n":24,"t":"他们必因饥饿消瘦，被炎热苦毒吞灭。我要打发野兽用牙齿咬他们，并土中腹行的，用毒气害他们。","notes":[]},{"n":25,"t":"外头有刀剑，内室有惊恐，使人丧亡，使少男、童女、吃奶的、白发的，尽都灭绝。","notes":[]},{"n":26,"t":"我说，我必将他们分散远方，使他们的名号从人间除灭。","notes":[]},{"n":27,"t":"惟恐仇敌惹动我，只怕敌人错看，说：是我们手的能力，并非耶和华所行的。","notes":[]},{"n":28,"t":"因为以色列民毫无计谋，心中没有聪明。","notes":[]},{"n":29,"t":"惟愿他们有智慧，能明白这事，肯思念他们的结局。","notes":[]},{"n":30,"t":"若不是他们的磐石卖了他们，若不是耶和华交出他们，一人焉能追赶他们千人？二人焉能使万人逃跑呢？","notes":[]},{"n":31,"t":"据我们的仇敌自己断定，他们的磐石不如我们的磐石。","notes":[]},{"n":32,"t":"他们的葡萄树是所多玛的葡萄树，蛾摩拉田园所生的；他们的葡萄是毒葡萄，全挂都是苦的。","notes":[]},{"n":33,"t":"他们的酒是大蛇的毒气，是虺蛇残害的恶毒。","notes":[]},{"n":34,"t":"这不都是积蓄在我这里，封锁在我府库中吗？","notes":[]},{"n":35,"t":"他们失脚的时候，伸冤报应在我；因他们遭灾的日子近了；那要临在他们身上的必速速来到。","notes":[]},{"n":36,"t":"耶和华见他百姓毫无能力，无论困住的、自由的都没有剩下，就必为他们伸冤，为他的仆人后悔。","notes":[]},{"n":37,"t":"他必说：他们的神，他们所投靠的磐石，","notes":[]},{"n":38,"t":"就是向来吃他们祭牲的脂油，喝他们奠祭之酒的，在哪里呢？他可以兴起帮助你们，护卫你们。","notes":[]},{"n":39,"t":"你们如今要知道：我，惟有我是神；在我以外并无别神。我使人死，我使人活；我损伤，我也医治，并无人能从我手中救出来。","notes":[]},{"n":40,"t":"我向天举手说：我凭我的永生起誓：","notes":[]},{"n":41,"t":"我若磨我闪亮的刀，手掌审判之权，就必报复我的敌人，报应恨我的人。","notes":[]},{"n":42,"t":"我要使我的箭饮血饮醉，就是被杀被掳之人的血。我的刀要吃肉，乃是仇敌中首领之头的肉。","notes":[]},{"n":43,"t":"你们外邦人当与主的百姓一同欢呼；因他要伸他仆人流血的冤，报应他的敌人，洁净他的地，救赎他的百姓。","notes":[]},{"n":44,"t":"摩西和嫩的儿子约书亚去将这歌的一切话说给百姓听。","notes":[]},{"n":45,"t":"摩西向以色列众人说完了这一切的话，","notes":[]},{"n":46,"t":"又说：「我今日所警教你们的，你们都要放在心上；要吩咐你们的子孙谨守遵行这律法上的话。","notes":[]},{"n":47,"t":"因为这不是虚空、与你们无关的事，乃是你们的生命；在你们过约旦河要得为业的地上必因这事日子得以长久。」","notes":[]},{"n":48,"t":"当日，耶和华吩咐摩西说：","notes":[]},{"n":49,"t":"「你上这亚巴琳山中的尼波山去，在摩押地与耶利哥相对，观看我所要赐给以色列人为业的迦南地。","notes":[]},{"n":50,"t":"你必死在你所登的山上，归你列祖去，像你哥哥亚伦死在何珥山上，归他的列祖一样。","notes":["原文是本民"]},{"n":51,"t":"因为你们在寻的旷野，加低斯的米利巴水，在以色列人中没有尊我为圣，得罪了我。","notes":[]},{"n":52,"t":"我所赐给以色列人的地，你可以远远地观看，却不得进去。」","notes":[]}]},"33":{"heading":"摩西祝福以色列众支派","verses":[{"n":1,"t":"以下是神人摩西在未死之先为以色列人所祝的福：","notes":[]},{"n":2,"t":"他说：耶和华从西奈而来，从西珥向他们显现，从巴兰山发出光辉，从万万圣者中来临，从他右手为百姓传出烈火的律法。","notes":[]},{"n":3,"t":"他疼爱百姓；众圣徒都在他手中。他们坐在他的脚下，领受他的言语。","notes":[]},{"n":4,"t":"摩西将律法传给我们，作为雅各会众的产业。","notes":[]},{"n":5,"t":"百姓的众首领，以色列的各支派，一同聚会的时候，耶和华在耶书仑中为王。","notes":["原文是他"]},{"n":6,"t":"愿吕便存活，不致死亡；愿他人数不致稀少。","notes":[]},{"n":7,"t":"为犹大祝福说：求耶和华俯听犹大的声音，引导他归于本族；他曾用手为自己争战，你必帮助他攻击敌人。","notes":[]},{"n":8,"t":"论利未说：耶和华啊，你的土明和乌陵都在你的虔诚人那里。你在玛撒曾试验他，在米利巴水与他争论。","notes":[]},{"n":9,"t":"他论自己的父母说：我未曾看见；他也不承认弟兄，也不认识自己的儿女。这是因利未人遵行你的话，谨守你的约。","notes":[]},{"n":10,"t":"他们要将你的典章教训雅各，将你的律法教训以色列。他们要把香焚在你面前，把全牲的燔祭献在你的坛上。","notes":[]},{"n":11,"t":"求耶和华降福在他的财物上，悦纳他手里所办的事。那些起来攻击他和恨恶他的人，愿你刺透他们的腰，使他们不得再起来。","notes":[]},{"n":12,"t":"论便雅悯说：耶和华所亲爱的必同耶和华安然居住；耶和华终日遮蔽他，也住在他两肩之中。","notes":[]},{"n":13,"t":"论约瑟说：愿他的地蒙耶和华赐福，得天上的宝物、甘露，以及地里所藏的泉水；","notes":[]},{"n":14,"t":"得太阳所晒熟的美果，月亮所养成的宝物；","notes":[]},{"n":15,"t":"得上古之山的至宝，永世之岭的宝物；","notes":[]},{"n":16,"t":"得地和其中所充满的宝物，并住荆棘中上主的喜悦。愿这些福都归于约瑟的头上，归于那与弟兄迥别之人的顶上。","notes":[]},{"n":17,"t":"他为牛群中头生的，有威严；他的角是野牛的角，用以抵触万邦，直到地极。这角是以法莲的万万，玛拿西的千千。","notes":[]},{"n":18,"t":"论西布伦说：西布伦哪，你出外可以欢喜。以萨迦啊，在你帐棚里可以快乐。","notes":[]},{"n":19,"t":"他们要将列邦召到山上，在那里献公义的祭；因为他们要吸取海里的丰富，并沙中所藏的珍宝。","notes":[]},{"n":20,"t":"论迦得说：使迦得扩张的应当称颂！迦得住如母狮；他撕裂膀臂，连头顶也撕裂。","notes":[]},{"n":21,"t":"他为自己选择头一段地，因在那里有设立律法者的分存留。他与百姓的首领同来；他施行耶和华的公义和耶和华与以色列所立的典章。","notes":[]},{"n":22,"t":"论但说：但为小狮子，从巴珊跳出来。","notes":[]},{"n":23,"t":"论拿弗他利说：拿弗他利啊，你足沾恩惠，满得耶和华的福，可以得西方和南方为业。","notes":[]},{"n":24,"t":"论亚设说：愿亚设享受多子的福乐，得他弟兄的喜悦，可以把脚蘸在油中。","notes":[]},{"n":25,"t":"你的门闩是铜的，铁的。你的日子如何，你的力量也必如何。","notes":["或译：鞋"]},{"n":26,"t":"耶书仑哪，没有能比神的。他为帮助你，乘在天空，显其威荣，驾行穹苍。","notes":[]},{"n":27,"t":"永生的神是你的居所；他永久的膀臂在你以下。他在你前面撵出仇敌，说：毁灭吧。","notes":[]},{"n":28,"t":"以色列安然居住；雅各的本源独居五谷新酒之地。他的天也滴甘露。","notes":[]},{"n":29,"t":"以色列啊，你是有福的！谁像你这蒙耶和华所拯救的百姓呢？他是你的盾牌，帮助你，是你威荣的刀剑。你的仇敌必投降你；你必踏在他们的高处。","notes":[]}]},"34":{"heading":"摩西去世","verses":[{"n":1,"t":"摩西从摩押平原登尼波山，上了那与耶利哥相对的毗斯迦山顶。耶和华把基列全地直到但，","notes":[]},{"n":2,"t":"拿弗他利全地，以法莲、玛拿西的地，犹大全地直到西海，","notes":[]},{"n":3,"t":"南地和棕树城耶利哥的平原，直到琐珥，都指给他看。","notes":[]},{"n":4,"t":"耶和华对他说：「这就是我向亚伯拉罕、以撒、雅各起誓应许之地，说：『我必将这地赐给你的后裔。』现在我使你眼睛看见了，你却不得过到那里去。」","notes":[]},{"n":5,"t":"于是，耶和华的仆人摩西死在摩押地，正如耶和华所说的。","notes":[]},{"n":6,"t":"耶和华将他埋葬在摩押地、伯·毗珥对面的谷中，只是到今日没有人知道他的坟墓。","notes":[]},{"n":7,"t":"摩西死的时候年一百二十岁；眼目没有昏花，精神没有衰败。","notes":[]},{"n":8,"t":"以色列人在摩押平原为摩西哀哭了三十日，为摩西居丧哀哭的日子就满了。","notes":[]},{"n":9,"t":"嫩的儿子约书亚；因为摩西曾按手在他头上，就被智慧的灵充满，以色列人便听从他，照着耶和华吩咐摩西的行了。","notes":[]},{"n":10,"t":"以后以色列中再没有兴起先知像摩西的。他是耶和华面对面所认识的。","notes":[]},{"n":11,"t":"耶和华打发他在埃及地向法老和他的一切臣仆，并他的全地，行各样神迹奇事，","notes":[]},{"n":12,"t":"又在以色列众人眼前显大能的手，行一切大而可畏的事。","notes":[]}]}},"JOS":{"1":{"heading":"神命令约书亚征服迦南","verses":[{"n":1,"t":"耶和华的仆人摩西死了以后，耶和华晓谕摩西的帮手，嫩的儿子约书亚，说：","notes":[]},{"n":2,"t":"「我的仆人摩西死了。现在你要起来，和众百姓过这约旦河，往我所要赐给以色列人的地去。","notes":[]},{"n":3,"t":"凡你们脚掌所踏之地，我都照着我所应许摩西的话赐给你们了。","notes":[]},{"n":4,"t":"从旷野和这黎巴嫩，直到幼发拉底大河，赫人的全地，又到大海日落之处，都要作你们的境界。","notes":[]},{"n":5,"t":"你平生的日子，必无一人能在你面前站立得住。我怎样与摩西同在，也必照样与你同在；我必不撇下你，也不丢弃你。","notes":[]},{"n":6,"t":"你当刚强壮胆！因为你必使这百姓承受那地为业，就是我向他们列祖起誓应许赐给他们的地。","notes":[]},{"n":7,"t":"只要刚强，大大壮胆，谨守遵行我仆人摩西所吩咐你的一切律法，不可偏离左右，使你无论往哪里去，都可以顺利。","notes":[]},{"n":8,"t":"这律法书不可离开你的口，总要昼夜思想，好使你谨守遵行这书上所写的一切话。如此，你的道路就可以亨通，凡事顺利。","notes":[]},{"n":9,"t":"我岂没有吩咐你吗？你当刚强壮胆！不要惧怕，也不要惊惶；因为你无论往哪里去，耶和华—你的神必与你同在。」","notes":[]},{"n":10,"t":"于是，约书亚吩咐百姓的官长说：","notes":[],"heads":["约书亚吩咐百姓准备渡河"]},{"n":11,"t":"「你们要走遍营中，吩咐百姓说：『当预备食物；因为三日之内你们要过这约旦河，进去得耶和华—你们神赐你们为业之地。』」","notes":[]},{"n":12,"t":"约书亚对吕便人、迦得人，和玛拿西半支派的人说：","notes":[]},{"n":13,"t":"「你们要追念耶和华的仆人摩西所吩咐你们的话说：『耶和华—你们的神使你们得享平安，也必将这地赐给你们。』","notes":[]},{"n":14,"t":"你们的妻子、孩子，和牲畜都可以留在约旦河东、摩西所给你们的地；但你们中间一切大能的勇士都要带着兵器在你们的弟兄前面过去，帮助他们，","notes":[]},{"n":15,"t":"等到耶和华使你们的弟兄像你们一样得享平安，并且得着耶和华—你们神所赐他们为业之地，那时才可以回你们所得之地，承受为业，就是耶和华的仆人摩西在约旦河东、向日出之地所给你们的。」","notes":[]},{"n":16,"t":"他们回答约书亚说：「你所吩咐我们行的，我们都必行；你所差遣我们去的，我们都必去。","notes":[]},{"n":17,"t":"我们从前在一切事上怎样听从摩西，现在也必照样听从你；惟愿耶和华—你的神与你同在，像与摩西同在一样。","notes":[]},{"n":18,"t":"无论什么人违背你的命令，不听从你所吩咐他的一切话，就必治死他。你只要刚强壮胆！」","notes":[]}]},"2":{"heading":"约书亚派探子进耶利哥","verses":[{"n":1,"t":"当下，嫩的儿子约书亚从什亭暗暗打发两个人作探子，吩咐说：「你们去窥探那地和耶利哥。」于是二人去了，来到一个妓女名叫喇合的家里，就在那里躺卧。","notes":[]},{"n":2,"t":"有人告诉耶利哥王说：「今夜有以色列人来到这里窥探此地。」","notes":[]},{"n":3,"t":"耶利哥王打发人去见喇合说：「那来到你这里、进了你家的人要交出来，因为他们来窥探全地。」","notes":[]},{"n":4,"t":"女人将二人隐藏，就回答说：「那人果然到我这里来；他们是哪里来的我却不知道。","notes":[]},{"n":5,"t":"天黑、要关城门的时候，他们出去了，往哪里去我却不知道。你们快快地去追赶，就必追上。」（","notes":[]},{"n":6,"t":"先是女人领二人上了房顶，将他们藏在那里所摆的麻秸中。）","notes":[]},{"n":7,"t":"那些人就往约旦河的渡口追赶他们去了。追赶他们的人一出去，城门就关了。","notes":[]},{"n":8,"t":"二人还没有躺卧，女人就上房顶，到他们那里，","notes":[]},{"n":9,"t":"对他们说：「我知道耶和华已经把这地赐给你们，并且因你们的缘故我们都惊慌了。这地的一切居民在你们面前心都消化了；","notes":[]},{"n":10,"t":"因为我们听见你们出埃及的时候，耶和华怎样在你们前面使红海的水干了，并且你们怎样待约旦河东的两个亚摩利王西宏和噩，将他们尽行毁灭。","notes":[]},{"n":11,"t":"我们一听见这些事，心就消化了。因你们的缘故，并无一人有胆气。耶和华—你们的神本是上天下地的神。","notes":[]},{"n":12,"t":"现在我既是恩待你们，求你们指着耶和华向我起誓，也要恩待我父家，并给我一个实在的证据，","notes":[]},{"n":13,"t":"要救活我的父母、弟兄、姊妹，和一切属他们的，拯救我们性命不死。」","notes":[]},{"n":14,"t":"二人对她说：「你若不泄漏我们这件事，我们情愿替你们死。耶和华将这地赐给我们的时候，我们必以慈爱诚实待你。」","notes":[]},{"n":15,"t":"于是女人用绳子将二人从窗户里缒下去；因她的房子是在城墙边上，她也住在城墙上。","notes":[]},{"n":16,"t":"她对他们说：「你们且往山上去，恐怕追赶的人碰见你们；要在那里隐藏三天，等追赶的人回来，然后才可以走你们的路。」","notes":[]},{"n":17,"t":"二人对她说：「你要这样行。不然，你叫我们所起的誓就与我们无干了。","notes":[]},{"n":18,"t":"我们来到这地的时候，你要把这条朱红线绳系在缒我们下去的窗户上，并要使你的父母、弟兄，和你父的全家都聚集在你家中。","notes":[]},{"n":19,"t":"凡出了你家门往街上去的，他的罪必归到自己的头上，与我们无干了。凡在你家里的，若有人下手害他，流他血的罪就归到我们的头上。","notes":["原文是血"]},{"n":20,"t":"你若泄漏我们这件事，你叫我们所起的誓就与我们无干了。」","notes":[]},{"n":21,"t":"女人说：「照你们的话行吧！」于是打发他们去了，又把朱红线绳系在窗户上。","notes":[]},{"n":22,"t":"二人到山上，在那里住了三天，等着追赶的人回去了。追赶的人一路找他们，却找不着。","notes":[]},{"n":23,"t":"二人就下山回来，过了河，到嫩的儿子约书亚那里，向他述说所遭遇的一切事；","notes":[]},{"n":24,"t":"又对约书亚说：「耶和华果然将那全地交在我们手中；那地的一切居民在我们面前心都消化了。」","notes":[]}]},"3":{"heading":"以色列人过约旦河","verses":[{"n":1,"t":"约书亚清早起来，和以色列众人都离开什亭，来到约旦河，就住在那里，等候过河。","notes":[]},{"n":2,"t":"过了三天，官长走遍营中，","notes":[]},{"n":3,"t":"吩咐百姓说：「你们看见耶和华—你们神的约柜，又见祭司利未人抬着，就要离开所住的地方，跟着约柜去。","notes":[]},{"n":4,"t":"只是你们和约柜相离要量二千肘，不可与约柜相近，使你们知道所当走的路，因为这条路你们向来没有走过。」","notes":[]},{"n":5,"t":"约书亚吩咐百姓说：「你们要自洁，因为明天耶和华必在你们中间行奇事。」","notes":[]},{"n":6,"t":"约书亚又吩咐祭司说：「你们抬起约柜，在百姓前头过去。」于是他们抬起约柜，在百姓前头走。","notes":[]},{"n":7,"t":"耶和华对约书亚说：「从今日起，我必使你在以色列众人眼前尊大，使他们知道我怎样与摩西同在，也必照样与你同在。","notes":[]},{"n":8,"t":"你要吩咐抬约柜的祭司说：『你们到了约旦河的水边上，就要在约旦河水里站住。』」","notes":[]},{"n":9,"t":"约书亚对以色列人说：「你们近前来，听耶和华—你们神的话。」","notes":[]},{"n":10,"t":"约书亚说：「看哪，普天下主的约柜必在你们前头过去，到约旦河里，因此你们就知道在你们中间有永生神；并且他必在你们面前赶出迦南人、赫人、希未人、比利洗人、革迦撒人、亚摩利人、耶布斯人。","notes":[],"end":11},{"n":12,"t":"你们现在要从以色列支派中拣选十二个人，每支派一人，","notes":[]},{"n":13,"t":"等到抬普天下主耶和华约柜的祭司把脚站在约旦河水里，约旦河的水，就是从上往下流的水，必然断绝，立起成垒。」","notes":[]},{"n":14,"t":"百姓离开帐棚要过约旦河的时候，抬约柜的祭司乃在百姓的前头。","notes":[]},{"n":15,"t":"他们到了约旦河，脚一入水（原来约旦河水在收割的日子涨过两岸），","notes":[]},{"n":16,"t":"那从上往下流的水便在极远之地、撒拉但旁的亚当城那里停住，立起成垒；那往亚拉巴的海，就是盐海，下流的水全然断绝。于是百姓在耶利哥的对面过去了。","notes":[]},{"n":17,"t":"抬耶和华约柜的祭司在约旦河中的干地上站定，以色列众人都从干地上过去，直到国民尽都过了约旦河。","notes":[]}]},"4":{"heading":"立石为记","verses":[{"n":1,"t":"国民尽都过了约旦河，耶和华就对约书亚说：","notes":[]},{"n":2,"t":"「你从民中要拣选十二个人，每支派一人，","notes":[]},{"n":3,"t":"吩咐他们说：『你们从这里，从约旦河中、祭司脚站定的地方，取十二块石头带过去，放在你们今夜要住宿的地方。』」","notes":[]},{"n":4,"t":"于是，约书亚将他从以色列人中所预备的那十二个人，每支派一人，都召了来。","notes":[]},{"n":5,"t":"对他们说：「你们下约旦河中，过到耶和华—你们神的约柜前头，按着以色列人十二支派的数目，每人取一块石头扛在肩上。","notes":[]},{"n":6,"t":"这些石头在你们中间可以作为证据。日后，你们的子孙问你们说：『这些石头是什么意思？』","notes":[]},{"n":7,"t":"你们就对他们说：『这是因为约旦河的水在耶和华的约柜前断绝；约柜过约旦河的时候，约旦河的水就断绝了。这些石头要作以色列人永远的纪念。』」","notes":[]},{"n":8,"t":"以色列人就照约书亚所吩咐的，按着以色列人支派的数目，从约旦河中取了十二块石头，都遵耶和华所吩咐约书亚的行了。他们把石头带过去，到他们所住宿的地方，就放在那里。","notes":[]},{"n":9,"t":"约书亚另把十二块石头立在约旦河中，在抬约柜的祭司脚站立的地方；直到今日，那石头还在那里。","notes":[]},{"n":10,"t":"抬约柜的祭司站在约旦河中，等到耶和华晓谕约书亚吩咐百姓的事办完了，是照摩西所吩咐约书亚的一切话。于是百姓急速过去了。","notes":[]},{"n":11,"t":"众百姓尽都过了河，耶和华的约柜和祭司就在百姓面前过去。","notes":[]},{"n":12,"t":"吕便人、迦得人、玛拿西半支派的人都照摩西所吩咐他们的，带着兵器在以色列人前头过去。","notes":[]},{"n":13,"t":"约有四万人都准备打仗，在耶和华面前过去，到耶利哥的平原，等候上阵。","notes":[]},{"n":14,"t":"当那日，耶和华使约书亚在以色列众人眼前尊大。在他平生的日子，百姓敬畏他，像从前敬畏摩西一样。","notes":[]},{"n":15,"t":"耶和华晓谕约书亚说：","notes":[]},{"n":16,"t":"「你吩咐抬法柜的祭司从约旦河里上来。」","notes":[]},{"n":17,"t":"约书亚就吩咐祭司说：「你们从约旦河里上来。」","notes":[]},{"n":18,"t":"抬耶和华约柜的祭司从约旦河里上来，脚掌刚落旱地，约旦河的水就流到原处，仍旧涨过两岸。","notes":[]},{"n":19,"t":"正月初十日，百姓从约旦河里上来，就在吉甲，在耶利哥的东边安营。","notes":[]},{"n":20,"t":"他们从约旦河中取来的那十二块石头，约书亚就立在吉甲，","notes":[]},{"n":21,"t":"对以色列人说：「日后你们的子孙问他们的父亲说：『这些石头是什么意思？』","notes":[]},{"n":22,"t":"你们就告诉他们说：『以色列人曾走干地过这约旦河；","notes":[]},{"n":23,"t":"因为耶和华—你们的神在你们前面使约旦河的水干了，等着你们过来，就如耶和华—你们的神从前在我们前面使红海干了，等着我们过来一样，","notes":[]},{"n":24,"t":"要使地上万民都知道，耶和华的手大有能力，也要使你们永远敬畏耶和华—你们的神。』」","notes":[]}]},"5":{"heading":"在吉甲行割礼","verses":[{"n":1,"t":"约旦河西亚摩利人的诸王和靠海迦南人的诸王，听见耶和华在以色列人前面使约旦河的水干了，等到我们过去，他们的心因以色列人的缘故就消化了，不再有胆气。","notes":[]},{"n":2,"t":"那时，耶和华吩咐约书亚说：「你制造火石刀，第二次给以色列人行割礼。」","notes":[]},{"n":3,"t":"约书亚就制造了火石刀，在「除皮山」那里给以色列人行割礼。","notes":[]},{"n":4,"t":"约书亚行割礼的缘故，是因为从埃及出来的众民，就是一切能打仗的男丁，出了埃及以后，都死在旷野的路上。","notes":[]},{"n":5,"t":"因为出来的众民都受过割礼；惟独出埃及以后、在旷野的路上所生的众民都没有受过割礼。","notes":[]},{"n":6,"t":"以色列人在旷野走了四十年，等到国民，就是出埃及的兵丁，都消灭了，因为他们没有听从耶和华的话。耶和华曾向他们起誓，必不容他们看见耶和华向他们列祖起誓、应许赐给我们的地，就是流奶与蜜之地。","notes":[]},{"n":7,"t":"他们的子孙，就是耶和华所兴起来接续他们的，都没有受过割礼；因为在路上没有给他们行割礼，约书亚这才给他们行了。","notes":[]},{"n":8,"t":"国民都受完了割礼，就住在营中自己的地方，等到痊愈了。","notes":[]},{"n":9,"t":"耶和华对约书亚说：「我今日将埃及的羞辱从你们身上滚去了。」因此，那地方名叫吉甲，直到今日。","notes":["就是滚的意思"]},{"n":10,"t":"以色列人在吉甲安营。正月十四日晚上，在耶利哥的平原守逾越节。","notes":[]},{"n":11,"t":"逾越节的次日，他们就吃了那地的出产；正当那日吃无酵饼和烘的谷。","notes":[]},{"n":12,"t":"他们吃了那地的出产，第二日吗哪就止住了，以色列人也不再有吗哪了。那一年，他们却吃迦南地的出产。","notes":[]},{"n":13,"t":"约书亚靠近耶利哥的时候，举目观看，不料，有一个人手里有拔出来的刀，对面站立。约书亚到他那里，问他说：「你是帮助我们呢，是帮助我们敌人呢？」","notes":[],"heads":["约书亚和耶和华军队的元帅"]},{"n":14,"t":"他回答说：「不是的，我来是要作耶和华军队的元帅。」约书亚就俯伏在地下拜，说：「我主有什么话吩咐仆人。」","notes":[]},{"n":15,"t":"耶和华军队的元帅对约书亚说：「把你脚上的鞋脱下来，因为你所站的地方是圣的。」约书亚就照着行了。","notes":[]}]},"6":{"heading":"耶利哥城陷落","verses":[{"n":1,"t":"耶利哥的城门因以色列人就关得严紧，无人出入。","notes":[]},{"n":2,"t":"耶和华晓谕约书亚说：「看哪，我已经把耶利哥和耶利哥的王，并大能的勇士，都交在你手中。","notes":[]},{"n":3,"t":"你们的一切兵丁要围绕这城，一日围绕一次，六日都要这样行。","notes":[]},{"n":4,"t":"七个祭司要拿七个羊角走在约柜前。到第七日，你们要绕城七次，祭司也要吹角。","notes":[]},{"n":5,"t":"他们吹的角声拖长，你们听见角声，众百姓要大声呼喊，城墙就必塌陷，各人都要往前直上。」","notes":[]},{"n":6,"t":"嫩的儿子约书亚召了祭司来，吩咐他们说：「你们抬起约柜来，要有七个祭司拿七个羊角走在耶和华的约柜前」；","notes":[]},{"n":7,"t":"又对百姓说：「你们前去绕城，带兵器的要走在耶和华的约柜前。」","notes":[]},{"n":8,"t":"约书亚对百姓说完了话，七个祭司拿七个羊角走在耶和华面前吹角；耶和华的约柜在他们后面跟随。","notes":[]},{"n":9,"t":"带兵器的走在吹角的祭司前面，后队随着约柜行。祭司一面走一面吹。","notes":[]},{"n":10,"t":"约书亚吩咐百姓说：「你们不可呼喊，不可出声，连一句话也不可出你们的口，等到我吩咐你们呼喊的日子，那时才可以呼喊。」","notes":[]},{"n":11,"t":"这样，他使耶和华的约柜绕城，把城绕了一次；众人回到营里，就在营里住宿。","notes":[]},{"n":12,"t":"约书亚清早起来，祭司又抬起耶和华的约柜。","notes":[]},{"n":13,"t":"七个祭司拿七个羊角在耶和华的约柜前，时常行走吹角；带兵器的在他们前面走，后队随着耶和华的约柜行。祭司一面走一面吹。","notes":[]},{"n":14,"t":"第二日，众人把城绕了一次，就回营里去。六日都是这样行。","notes":[]},{"n":15,"t":"第七日清早，黎明的时候，他们起来，照样绕城七次；惟独这日把城绕了七次。","notes":[]},{"n":16,"t":"到了第七次，祭司吹角的时候，约书亚吩咐百姓说：「呼喊吧，因为耶和华已经把城交给你们了！","notes":[]},{"n":17,"t":"这城和其中所有的都要在耶和华面前毁灭；只有妓女喇合与她家中所有的可以存活，因为她隐藏了我们所打发的使者。","notes":[]},{"n":18,"t":"至于你们，务要谨慎，不可取那当灭的物，恐怕你们取了那当灭的物就连累以色列的全营，使全营受咒诅。","notes":[]},{"n":19,"t":"惟有金子、银子，和铜铁的器皿都要归耶和华为圣，必入耶和华的库中。」","notes":[]},{"n":20,"t":"于是百姓呼喊，祭司也吹角。百姓听见角声，便大声呼喊，城墙就塌陷，百姓便上去进城，各人往前直上，将城夺取；","notes":[]},{"n":21,"t":"又将城中所有的，不拘男女老少，牛羊和驴，都用刀杀尽。","notes":[]},{"n":22,"t":"约书亚吩咐窥探地的两个人说：「你们进那妓女的家，照着你们向她所起的誓，将那女人和她所有的都从那里带出来。」","notes":[]},{"n":23,"t":"当探子的两个少年人就进去，将喇合与她的父母、弟兄，和她所有的，并她一切的亲眷，都带出来，安置在以色列的营外。","notes":[]},{"n":24,"t":"众人就用火将城和其中所有的焚烧了；惟有金子、银子，和铜铁的器皿都放在耶和华殿的库中。","notes":[]},{"n":25,"t":"约书亚却把妓女喇合与她父家，并她所有的，都救活了；因为她隐藏了约书亚所打发窥探耶利哥的使者，她就住在以色列中，直到今日。","notes":[]},{"n":26,"t":"当时，约书亚叫众人起誓说：「有兴起重修这耶利哥城的人，当在耶和华面前受咒诅。他立根基的时候，必丧长子，安门的时候，必丧幼子。」","notes":[]},{"n":27,"t":"耶和华与约书亚同在，约书亚的声名传扬遍地。","notes":[]}]},"7":{"heading":"亚干犯罪","verses":[{"n":1,"t":"以色列人在当灭的物上犯了罪；因为犹大支派中，谢拉的曾孙，撒底的孙子，迦米的儿子亚干取了当灭的物；耶和华的怒气就向以色列人发作。","notes":[]},{"n":2,"t":"当下，约书亚从耶利哥打发人往伯特利东边、靠近伯·亚文的艾城去，吩咐他们说：「你们上去窥探那地。」他们就上去窥探艾城。","notes":[]},{"n":3,"t":"他们回到约书亚那里，对他说：「众民不必都上去，只要二三千人上去就能攻取艾城；不必劳累众民都去，因为那里的人少。」","notes":[]},{"n":4,"t":"于是民中约有三千人上那里去，竟在艾城人面前逃跑了。","notes":[]},{"n":5,"t":"艾城的人击杀了他们三十六人，从城门前追赶他们，直到示巴琳，在下坡杀败他们；众民的心就消化如水。","notes":[]},{"n":6,"t":"约书亚便撕裂衣服；他和以色列的长老把灰撒在头上，在耶和华的约柜前俯伏在地，直到晚上。","notes":[]},{"n":7,"t":"约书亚说：「哀哉！主耶和华啊，你为什么竟领这百姓过约旦河，将我们交在亚摩利人的手中，使我们灭亡呢？我们不如住在约旦河那边倒好。","notes":[]},{"n":8,"t":"主啊，以色列人既在仇敌面前转背逃跑，我还有什么可说的呢？","notes":[]},{"n":9,"t":"迦南人和这地一切的居民听见了就必围困我们，将我们的名从地上除灭。那时你为你的大名要怎样行呢？」","notes":[]},{"n":10,"t":"耶和华吩咐约书亚说：「起来！你为何这样俯伏在地呢？","notes":[]},{"n":11,"t":"以色列人犯了罪，违背了我所吩咐他们的约，取了当灭的物；又偷窃，又行诡诈，又把那当灭的放在他们的家具里。","notes":[]},{"n":12,"t":"因此，以色列人在仇敌面前站立不住。他们在仇敌面前转背逃跑，是因成了被咒诅的；你们若不把当灭的物从你们中间除掉，我就不再与你们同在了。","notes":[]},{"n":13,"t":"你起来，叫百姓自洁，对他们说：『你们要自洁，预备明天，因为耶和华—以色列的神这样说：以色列啊，你们中间有当灭的物，你们若不除掉，在仇敌面前必站立不住！』","notes":[]},{"n":14,"t":"到了早晨，你们要按着支派近前来；耶和华所取的支派，要按着宗族近前来；耶和华所取的宗族，要按着家室近前来；耶和华所取的家室，要按着人丁，一个一个地近前来。","notes":[]},{"n":15,"t":"被取的人有当灭的物在他那里，他和他所有的必被火焚烧；因他违背了耶和华的约，又因他在以色列中行了愚妄的事。」","notes":[]},{"n":16,"t":"于是，约书亚清早起来，使以色列人按着支派近前来，取出来的是犹大支派；","notes":[]},{"n":17,"t":"使犹大支派近前来，就取了谢拉的宗族；使谢拉的宗族，按着家室人丁，一个一个地近前来，取出来的是撒底；","notes":["原文是宗族"]},{"n":18,"t":"使撒底的家室，按着人丁，一个一个地近前来，就取出犹大支派的人谢拉的曾孙，撒底的孙子，迦米的儿子亚干。","notes":[]},{"n":19,"t":"约书亚对亚干说：「我儿，我劝你将荣耀归给耶和华—以色列的神，在他面前认罪，将你所做的事告诉我，不要向我隐瞒。」","notes":[]},{"n":20,"t":"亚干回答约书亚说：「我实在得罪了耶和华—以色列的神。我所做的事如此如此：","notes":[]},{"n":21,"t":"我在所夺的财物中看见一件美好的示拿衣服，二百舍客勒银子，一条金子重五十舍客勒，我就贪爱这些物件，便拿去了。现今藏在我帐棚内的地里，银子在衣服底下。」","notes":[]},{"n":22,"t":"约书亚就打发人跑到亚干的帐棚里。那件衣服果然藏在他帐棚内，银子在底下。","notes":[]},{"n":23,"t":"他们就从帐棚里取出来，拿到约书亚和以色列众人那里，放在耶和华面前。","notes":[]},{"n":24,"t":"约书亚和以色列众人把谢拉的曾孙亚干和那银子、那件衣服、那条金子，并亚干的儿女、牛、驴、羊、帐棚，以及他所有的，都带到亚割谷去。","notes":[]},{"n":25,"t":"约书亚说：「你为什么连累我们呢？今日耶和华必叫你受连累。」于是以色列众人用石头打死他，将石头扔在其上，又用火焚烧他所有的。","notes":["原文是他们"]},{"n":26,"t":"众人在亚干身上堆成一大堆石头，直存到今日。于是耶和华转意，不发他的烈怒。因此那地方名叫亚割谷，直到今日。","notes":["就是连累的意思"]}]},"8":{"heading":"攻取艾城","verses":[{"n":1,"t":"耶和华对约书亚说：「不要惧怕，也不要惊惶。你起来，率领一切兵丁上艾城去，我已经把艾城的王和他的民、他的城，并他的地，都交在你手里。","notes":[]},{"n":2,"t":"你怎样待耶利哥和耶利哥的王，也当照样待艾城和艾城的王。只是城内所夺的财物和牲畜，你们可以取为自己的掠物。你要在城后设下伏兵。」","notes":[]},{"n":3,"t":"于是，约书亚和一切兵丁都起来，要上艾城去。约书亚选了三万大能的勇士，夜间打发他们前往，","notes":[]},{"n":4,"t":"吩咐他们说：「你们要在城后埋伏，不可离城太远，都要各自准备。","notes":[]},{"n":5,"t":"我与我所带领的众民要向城前往。城里的人像初次出来攻击我们的时候，我们就在他们面前逃跑，","notes":[]},{"n":6,"t":"他们必出来追赶我们，直到我们引诱他们离开城；因为他们必说：『这些人像初次在我们面前逃跑。』所以我们要在他们面前逃跑，","notes":[]},{"n":7,"t":"你们就从埋伏的地方起来，夺取那城，因为耶和华—你们的神必把城交在你们手里。","notes":[]},{"n":8,"t":"你们夺了城以后，就放火烧城，要照耶和华的话行。这是我吩咐你们的。」","notes":[]},{"n":9,"t":"约书亚打发他们前往，他们就上埋伏的地方去，住在伯特利和艾城的中间，就是在艾城的西边。这夜约书亚却在民中住宿。","notes":[]},{"n":10,"t":"约书亚清早起来，点齐百姓，他和以色列的长老在百姓前面上艾城去。","notes":[]},{"n":11,"t":"众民，就是他所带领的兵丁，都上去，向前直往，来到城前，在艾城北边安营。在约书亚和艾城中间有一山谷。","notes":[]},{"n":12,"t":"他挑了约有五千人，使他们埋伏在伯特利和艾城的中间，就是在艾城的西边，","notes":[]},{"n":13,"t":"于是安置了百姓，就是城北的全军和城西的伏兵。这夜约书亚进入山谷之中。","notes":[]},{"n":14,"t":"艾城的王看见这景况，就和全城的人，清早急忙起来，按所定的时候，出到亚拉巴前，要与以色列人交战；王却不知道在城后有伏兵。","notes":[]},{"n":15,"t":"约书亚和以色列众人在他们面前装败，往那通旷野的路逃跑。","notes":[]},{"n":16,"t":"城内的众民都被招聚，追赶他们；艾城人追赶的时候，就被引诱离开城。","notes":[]},{"n":17,"t":"艾城和伯特利城没有一人不出来追赶以色列人的，撇了敞开的城门，去追赶以色列人。","notes":[]},{"n":18,"t":"耶和华吩咐约书亚说：「你向艾城伸出手里的短枪，因为我要将城交在你手里。」约书亚就向城伸出手里的短枪。","notes":[]},{"n":19,"t":"他一伸手，伏兵就从埋伏的地方急忙起来，夺了城，跑进城去，放火焚烧。","notes":[]},{"n":20,"t":"艾城的人回头一看，不料，城中烟气冲天，他们就无力向左向右逃跑。那往旷野逃跑的百姓便转身攻击追赶他们的人。","notes":[]},{"n":21,"t":"约书亚和以色列众人见伏兵已经夺了城，城中烟气飞腾，就转身回去，击杀艾城的人。","notes":[]},{"n":22,"t":"伏兵也出城迎击艾城人，艾城人就困在以色列人中间，前后都是以色列人。于是以色列人击杀他们，没有留下一个，也没有一个逃脱的，","notes":[]},{"n":23,"t":"生擒了艾城的王，将他解到约书亚那里。","notes":[]},{"n":24,"t":"以色列人在田间和旷野杀尽所追赶一切艾城的居民。艾城人倒在刀下，直到灭尽；以色列众人就回到艾城，用刀杀了城中的人。","notes":[]},{"n":25,"t":"当日杀毙的人，连男带女共有一万二千，就是艾城所有的人。","notes":[]},{"n":26,"t":"约书亚没有收回手里所伸出来的短枪，直到把艾城的一切居民尽行杀灭。","notes":[]},{"n":27,"t":"惟独城中的牲畜和财物，以色列人都取为自己的掠物，是照耶和华所吩咐约书亚的话。","notes":[]},{"n":28,"t":"约书亚将艾城焚烧，使城永为高堆、荒场，直到今日；","notes":[]},{"n":29,"t":"又将艾城王挂在树上，直到晚上。日落的时候，约书亚吩咐人把尸首从树上取下来，丢在城门口，在尸首上堆成一大堆石头，直存到今日。","notes":[]},{"n":30,"t":"那时，约书亚在以巴路山上为耶和华—以色列的神筑一座坛，","notes":[],"heads":["在以巴路山上宣读律法"]},{"n":31,"t":"是用没有动过铁器的整石头筑的，照着耶和华仆人摩西所吩咐以色列人的话，正如摩西律法书上所写的。众人在这坛上给耶和华奉献燔祭和平安祭。","notes":[]},{"n":32,"t":"约书亚在那里，当着以色列人面前，将摩西所写的律法抄写在石头上。","notes":[]},{"n":33,"t":"以色列众人，无论是本地人、是寄居的，和长老、官长，并审判官，都站在约柜两旁，在抬耶和华约柜的祭司利未人面前，一半对着基利心山，一半对着以巴路山，为以色列民祝福，正如耶和华仆人摩西先前所吩咐的。","notes":[]},{"n":34,"t":"随后，约书亚将律法上祝福、咒诅的话，照着律法书上一切所写的，都宣读了一遍。","notes":[]},{"n":35,"t":"摩西所吩咐的一切话，约书亚在以色列全会众和妇女、孩子，并他们中间寄居的外人面前，没有一句不宣读的。","notes":[]}]},"9":{"heading":"基遍人欺瞒约书亚","verses":[{"n":1,"t":"约旦河西，住山地、高原，并对着黎巴嫩山沿大海一带的诸王，就是赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人的诸王，听见这事，","notes":[]},{"n":2,"t":"就都聚集，同心合意地要与约书亚和以色列人争战。","notes":[]},{"n":3,"t":"基遍的居民听见约书亚向耶利哥和艾城所行的事，","notes":[]},{"n":4,"t":"就设诡计，假充使者，拿旧口袋和破裂缝补的旧皮酒袋驮在驴上，","notes":[]},{"n":5,"t":"将补过的旧鞋穿在脚上，把旧衣服穿在身上；他们所带的饼都是干的，长了霉了。","notes":[]},{"n":6,"t":"他们到吉甲营中见约书亚，对他和以色列人说：「我们是从远方来的，现在求你与我们立约。」","notes":[]},{"n":7,"t":"以色列人对这些希未人说：「只怕你们是住在我们中间的；若是这样，怎能和你们立约呢？」","notes":[]},{"n":8,"t":"他们对约书亚说：「我们是你的仆人。」约书亚问他们说：「你们是什么人？是从哪里来的？」","notes":[]},{"n":9,"t":"他们回答说：「仆人从极远之地而来，是因听见耶和华—你神的名声和他在埃及所行的一切事，","notes":[]},{"n":10,"t":"并他向约旦河东的两个亚摩利王，就是希实本王西宏和在亚斯他录的巴珊王噩一切所行的事。","notes":[]},{"n":11,"t":"我们的长老和我们那地的一切居民对我们说：『你们手里要带着路上用的食物去迎接以色列人，对他们说：我们是你们的仆人；现在求你们与我们立约。』","notes":[]},{"n":12,"t":"我们出来要往你们这里来的日子，从家里带出来的这饼还是热的；看哪，现在都干了，长了霉了。","notes":[]},{"n":13,"t":"这皮酒袋，我们盛酒的时候还是新的；看哪，现在已经破裂。我们这衣服和鞋，因为道路甚远，也都穿旧了。」","notes":[]},{"n":14,"t":"以色列人受了他们些食物，并没有求问耶和华。","notes":[]},{"n":15,"t":"于是约书亚与他们讲和，与他们立约，容他们活着；会众的首领也向他们起誓。","notes":[]},{"n":16,"t":"以色列人与他们立约之后，过了三天才听见他们是近邻，住在以色列人中间的。","notes":[]},{"n":17,"t":"以色列人起行，第三天到了他们的城邑，就是基遍、基非拉、比录、基列·耶琳。","notes":[]},{"n":18,"t":"因为会众的首领已经指着耶和华—以色列的神向他们起誓，所以以色列人不击杀他们；全会众就向首领发怨言。","notes":[]},{"n":19,"t":"众首领对全会众说：「我们已经指着耶和华—以色列的神向他们起誓，现在我们不能害他们。","notes":[]},{"n":20,"t":"我们要如此待他们，容他们活着，免得有忿怒因我们所起的誓临到我们身上。」","notes":[]},{"n":21,"t":"首领又对会众说：「要容他们活着。」于是他们为全会众作了劈柴挑水的人，正如首领对他们所说的话。","notes":[]},{"n":22,"t":"约书亚召了他们来，对他们说：「为什么欺哄我们说『我们离你们甚远』呢？其实你们是住在我们中间。","notes":[]},{"n":23,"t":"现在你们是被咒诅的！你们中间的人必断不了作奴仆，为我神的殿作劈柴挑水的人。」","notes":[]},{"n":24,"t":"他们回答约书亚说：「因为有人实在告诉你的仆人，耶和华—你的神曾吩咐他的仆人摩西，把这全地赐给你们，并在你们面前灭绝这地的一切居民，所以我们为你们的缘故甚怕丧命，就行了这事。","notes":[]},{"n":25,"t":"现在我们在你手中，你以怎样待我们为善为正，就怎样做吧！」","notes":[]},{"n":26,"t":"于是约书亚这样待他们，救他们脱离以色列人的手，以色列人就没有杀他们。","notes":[]},{"n":27,"t":"当日约书亚使他们在耶和华所要选择的地方，为会众和耶和华的坛作劈柴挑水的人，直到今日。","notes":[]}]},"10":{"heading":"击败亚摩利人","verses":[{"n":1,"t":"耶路撒冷王亚多尼·洗德听见约书亚夺了艾城，尽行毁灭，怎样待耶利哥和耶利哥的王，也照样待艾城和艾城的王，又听见基遍的居民与以色列人立了和约，住在他们中间，","notes":[]},{"n":2,"t":"就甚惧怕；因为基遍是一座大城，如都城一般，比艾城更大，并且城内的人都是勇士。","notes":[]},{"n":3,"t":"所以耶路撒冷王亚多尼·洗德打发人去见希伯仑王何咸、耶末王毗兰、拉吉王雅非亚，和伊矶伦王底璧，说：","notes":[]},{"n":4,"t":"「求你们上来帮助我，我们好攻打基遍，因为他们与约书亚和以色列人立了和约。」","notes":[]},{"n":5,"t":"于是五个亚摩利王，就是耶路撒冷王、希伯仑王、耶末王、拉吉王、伊矶伦王，大家聚集，率领他们的众军上去，对着基遍安营，攻打基遍。","notes":[]},{"n":6,"t":"基遍人就打发人往吉甲的营中去见约书亚，说：「你不要袖手不顾你的仆人，求你速速上来拯救我们，帮助我们，因为住山地亚摩利人的诸王都聚集攻击我们。」","notes":[]},{"n":7,"t":"于是约书亚和他一切兵丁，并大能的勇士，都从吉甲上去。","notes":[]},{"n":8,"t":"耶和华对约书亚说：「不要怕他们；因为我已将他们交在你手里，他们无一人能在你面前站立得住。」","notes":[]},{"n":9,"t":"约书亚就终夜从吉甲上去，猛然临到他们那里。","notes":[]},{"n":10,"t":"耶和华使他们在以色列人面前溃乱。约书亚在基遍大大地杀败他们，追赶他们，在伯·和仑的上坡路击杀他们，直到亚西加和玛基大。","notes":[]},{"n":11,"t":"他们在以色列人面前逃跑，正在伯·和仑下坡的时候，耶和华从天上降大冰雹在他们身上，直降到亚西加，打死他们。被冰雹打死的，比以色列人用刀杀死的还多。","notes":["原文是石头"]},{"n":12,"t":"当耶和华将亚摩利人交付以色列人的日子，约书亚就祷告耶和华，在以色列人眼前说：日头啊，你要停在基遍；月亮啊，你要止在亚雅仑谷。","notes":[]},{"n":13,"t":"于是日头停留，月亮止住，直等国民向敌人报仇。这事岂不是写在雅煞珥书上吗？日头在天当中停住，不急速下落，约有一日之久。","notes":[]},{"n":14,"t":"在这日以前，这日以后，耶和华听人的祷告，没有像这日的，是因耶和华为以色列争战。","notes":[]},{"n":15,"t":"约书亚和以色列众人回到吉甲的营中。","notes":[]},{"n":16,"t":"那五王逃跑，藏在玛基大洞里。","notes":[],"heads":["生擒亚摩利的五王"]},{"n":17,"t":"有人告诉约书亚说：「那五王已经找到了，都藏在玛基大洞里。」","notes":[]},{"n":18,"t":"约书亚说：「你们把几块大石头滚到洞口，派人看守，","notes":[]},{"n":19,"t":"你们却不可耽延，要追赶你们的仇敌，击杀他们尽后边的人，不容他们进自己的城邑，因为耶和华—你们的神已经把他们交在你们手里。」","notes":[]},{"n":20,"t":"约书亚和以色列人大大杀败他们，直到将他们灭尽；其中剩下的人都进了坚固的城。","notes":[]},{"n":21,"t":"众百姓就安然回玛基大营中，到约书亚那里。没有一人敢向以色列人饶舌。","notes":[]},{"n":22,"t":"约书亚说：「打开洞口，将那五王从洞里带出来，领到我面前。」","notes":[]},{"n":23,"t":"众人就这样行，将那五王，就是耶路撒冷王、希伯仑王、耶末王、拉吉王、伊矶伦王，从洞里带出来，领到约书亚面前。","notes":[]},{"n":24,"t":"带出那五王到约书亚面前的时候，约书亚就召了以色列众人来，对那些和他同去的军长说：「你们近前来，把脚踏在这些王的颈项上。」他们就近前来，把脚踏在这些王的颈项上。","notes":[]},{"n":25,"t":"约书亚对他们说：「你们不要惧怕，也不要惊惶。应当刚强壮胆，因为耶和华必这样待你们所要攻打的一切仇敌。」","notes":[]},{"n":26,"t":"随后约书亚将这五王杀死，挂在五棵树上。他们就在树上直挂到晚上。","notes":[]},{"n":27,"t":"日头要落的时候，约书亚一吩咐，人就把尸首从树上取下来，丢在他们藏过的洞里，把几块大石头放在洞口，直存到今日。","notes":[]},{"n":28,"t":"当日，约书亚夺了玛基大，用刀击杀城中的人和王；将其中一切人口尽行杀灭，没有留下一个。他待玛基大王，像从前待耶利哥王一样。","notes":[],"heads":["约书亚攻取更多的城邑"]},{"n":29,"t":"约书亚和以色列众人从玛基大往立拿去，攻打立拿。","notes":[]},{"n":30,"t":"耶和华将立拿和立拿的王也交在以色列人手里。约书亚攻打这城，用刀击杀了城中的一切人口，没有留下一个。他待立拿王，像从前待耶利哥王一样。","notes":[]},{"n":31,"t":"约书亚和以色列众人从立拿往拉吉去，对着拉吉安营，攻打这城。","notes":[]},{"n":32,"t":"耶和华将拉吉交在以色列人的手里。第二天约书亚就夺了拉吉，用刀击杀了城中的一切人口，是照他向立拿一切所行的。","notes":[]},{"n":33,"t":"那时基色王荷兰上来帮助拉吉，约书亚就把他和他的民都击杀了，没有留下一个。","notes":[]},{"n":34,"t":"约书亚和以色列众人从拉吉往伊矶伦去，对着伊矶伦安营，攻打这城。","notes":[]},{"n":35,"t":"当日就夺了城，用刀击杀了城中的人。那日，约书亚将城中的一切人口尽行杀灭，是照他向拉吉一切所行的。","notes":[]},{"n":36,"t":"约书亚和以色列众人从伊矶伦上希伯仑去，攻打这城，","notes":[]},{"n":37,"t":"就夺了希伯仑和属希伯仑的诸城邑，用刀将城中的人与王，并那些城邑中的人口，都击杀了，没有留下一个，是照他向伊矶伦所行的，把城中的一切人口尽行杀灭。","notes":[]},{"n":38,"t":"约书亚和以色列众人回到底璧，攻打这城，","notes":[]},{"n":39,"t":"就夺了底璧和属底璧的城邑，又擒获底璧的王，用刀将这些城中的人口尽行杀灭，没有留下一个。他待底璧和底璧王，像从前待希伯仑和立拿与立拿王一样。","notes":[]},{"n":40,"t":"这样，约书亚击杀全地的人，就是山地、南地、高原、山坡的人，和那些地的诸王，没有留下一个。将凡有气息的尽行杀灭，正如耶和华—以色列的神所吩咐的。","notes":[]},{"n":41,"t":"约书亚从加低斯·巴尼亚攻击到迦萨，又攻击歌珊全地，直到基遍。","notes":[]},{"n":42,"t":"约书亚一时杀败了这些王，并夺了他们的地，因为耶和华—以色列的神为以色列争战。","notes":[]},{"n":43,"t":"于是约书亚和以色列众人回到吉甲的营中。","notes":[]}]},"11":{"heading":"约书亚击败耶宾和他的盟国","verses":[{"n":1,"t":"夏琐王耶宾听见这事，就打发人去见玛顿王约巴、伸仑王、押煞王，","notes":[]},{"n":2,"t":"与北方山地、基尼烈南边的亚拉巴高原，并西边多珥山冈的诸王；","notes":[]},{"n":3,"t":"又去见东方和西方的迦南人，与山地的亚摩利人、赫人、比利洗人、耶布斯人，并黑门山根米斯巴地的希未人。","notes":[]},{"n":4,"t":"这些王和他们的众军都出来，人数多如海边的沙，并有许多马匹车辆。","notes":[]},{"n":5,"t":"这诸王会合，来到米伦水边，一同安营，要与以色列人争战。","notes":[]},{"n":6,"t":"耶和华对约书亚说：「你不要因他们惧怕。明日这时，我必将他们交付以色列人全然杀了。你要砍断他们马的蹄筋，用火焚烧他们的车辆。」","notes":[]},{"n":7,"t":"于是约书亚率领一切兵丁，在米伦水边突然向前攻打他们。","notes":[]},{"n":8,"t":"耶和华将他们交在以色列人手里，以色列人就击杀他们，追赶他们到西顿大城，到米斯利弗·玛音，直到东边米斯巴的平原，将他们击杀，没有留下一个。","notes":[]},{"n":9,"t":"约书亚就照耶和华所吩咐他的去行，砍断他们马的蹄筋，用火焚烧他们的车辆。","notes":[]},{"n":10,"t":"当时，约书亚转回夺了夏琐，用刀击杀夏琐王。（素来夏琐在这诸国中是为首的。）","notes":[]},{"n":11,"t":"以色列人用刀击杀城中的人口，将他们尽行杀灭；凡有气息的没有留下一个。约书亚又用火焚烧夏琐。","notes":[]},{"n":12,"t":"约书亚夺了这些王的一切城邑，擒获其中的诸王，用刀击杀他们，将他们尽行杀灭，正如耶和华仆人摩西所吩咐的。","notes":[]},{"n":13,"t":"至于造在山冈上的城，除了夏琐以外，以色列人都没有焚烧。约书亚只将夏琐焚烧了。","notes":[]},{"n":14,"t":"那些城邑所有的财物和牲畜，以色列人都取为自己的掠物；惟有一切人口都用刀击杀，直到杀尽；凡有气息的没有留下一个。","notes":[]},{"n":15,"t":"耶和华怎样吩咐他仆人摩西，摩西就照样吩咐约书亚，约书亚也照样行。凡耶和华所吩咐摩西的，约书亚没有一件懈怠不行的。","notes":[]},{"n":16,"t":"约书亚夺了那全地，就是山地、一带南地、歌珊全地、高原、亚拉巴、以色列的山地，和山下的高原。","notes":[],"heads":["约书亚占领的土地"]},{"n":17,"t":"从上西珥的哈拉山，直到黑门山下黎巴嫩平原的巴力·迦得，并且擒获那些地的诸王，将他们杀死。","notes":[]},{"n":18,"t":"约书亚和这诸王争战了许多年日。","notes":[]},{"n":19,"t":"除了基遍的希未人之外，没有一城与以色列人讲和的，都是以色列人争战夺来的。","notes":[]},{"n":20,"t":"因为耶和华的意思是要使他们心里刚硬，来与以色列人争战，好叫他们尽被杀灭，不蒙怜悯，正如耶和华所吩咐摩西的。","notes":[]},{"n":21,"t":"当时约书亚来到，将住山地、希伯仑、底璧、亚拿伯、犹大山地、以色列山地所有的亚衲族人剪除了。约书亚将他们和他们的城邑尽都毁灭。","notes":[]},{"n":22,"t":"在以色列人的地没有留下一个亚衲族人，只在迦萨、迦特，和亚实突有留下的。","notes":[]},{"n":23,"t":"这样，约书亚照着耶和华所吩咐摩西的一切话夺了那全地，就按着以色列支派的宗族将地分给他们为业。于是国中太平，没有争战了。","notes":[]}]},"12":{"heading":"摩西击败的诸王","verses":[{"n":1,"t":"以色列人在约旦河外向日出之地击杀二王，得他们的地，就是从亚嫩谷直到黑门山，并东边的全亚拉巴之地。","notes":[]},{"n":2,"t":"这二王，有住希实本、亚摩利人的王西宏。他所管之地是从亚嫩谷边的亚罗珥和谷中的城，并基列一半，直到亚扪人的境界，雅博河","notes":[]},{"n":3,"t":"与约旦河东边的亚拉巴，直到基尼烈海，又到亚拉巴的海，就是盐海，通伯·耶西末的路，以及南方，直到毗斯迦的山根。","notes":[]},{"n":4,"t":"又有巴珊王噩。他是利乏音人所剩下的，住在亚斯他录和以得来。","notes":[]},{"n":5,"t":"他所管之地是黑门山、撒迦、巴珊全地，直到基述人和玛迦人的境界，并基列一半，直到希实本王西宏的境界。","notes":[]},{"n":6,"t":"这二王是耶和华仆人摩西和以色列人所击杀的；耶和华仆人摩西将他们的地赐给吕便人、迦得人，和玛拿西半支派的人为业。","notes":[]},{"n":7,"t":"约书亚和以色列人在约旦河西击杀了诸王。他们的地是从黎巴嫩平原的巴力·迦得，直到上西珥的哈拉山。约书亚就将那地按着以色列支派的宗族分给他们为业，","notes":[],"heads":["约书亚击败的诸王"]},{"n":8,"t":"就是赫人、亚摩利人，迦南人、比利洗人、希未人、耶布斯人的山地、高原亚拉巴、山坡、旷野，和南地。","notes":[]},{"n":9,"t":"他们的王：一个是耶利哥王，一个是靠近伯特利的艾城王，","notes":[]},{"n":10,"t":"一个是耶路撒冷王，一个是希伯仑王，","notes":[]},{"n":11,"t":"一个是耶末王，一个是拉吉王，","notes":[]},{"n":12,"t":"一个是伊矶伦王，一个是基色王，","notes":[]},{"n":13,"t":"一个是底璧王，一个是基德王，","notes":[]},{"n":14,"t":"一个是何珥玛王，一个是亚拉得王，","notes":[]},{"n":15,"t":"一个是立拿王，一个是亚杜兰王，","notes":[]},{"n":16,"t":"一个是玛基大王，一个是伯特利王，","notes":[]},{"n":17,"t":"一个是他普亚王，一个是希弗王，","notes":[]},{"n":18,"t":"一个是亚弗王，一个是拉沙仑王，","notes":[]},{"n":19,"t":"一个是玛顿王，一个是夏琐王，","notes":[]},{"n":20,"t":"一个是伸仑·米仑王，一个是押煞王，","notes":[]},{"n":21,"t":"一个是他纳王，一个是米吉多王，","notes":[]},{"n":22,"t":"一个是基低斯王，一个是靠近迦密的约念王，","notes":[]},{"n":23,"t":"一个是多珥山冈的多珥王，一个是吉甲的戈印王，","notes":[]},{"n":24,"t":"一个是得撒王；共计三十一个王。","notes":[]}]},"13":{"heading":"尚未占领之地","verses":[{"n":1,"t":"约书亚年纪老迈，耶和华对他说：「你年纪老迈了，还有许多未得之地，","notes":[]},{"n":2,"t":"就是非利士人的全境和基述人的全地。","notes":[]},{"n":3,"t":"从埃及前的西曷河往北，直到以革伦的境界，就算属迦南人之地。有非利士人五个首领所管的迦萨人、亚实突人、亚实基伦人、迦特人、以革伦人之地，并有南方亚卫人之地。","notes":[]},{"n":4,"t":"又有迦南人的全地，并属西顿人的米亚拉到亚弗，直到亚摩利人的境界。","notes":[]},{"n":5,"t":"还有迦巴勒人之地，并向日出的全黎巴嫩，就是从黑门山根的巴力·迦得，直到哈马口。","notes":[]},{"n":6,"t":"山地的一切居民，从黎巴嫩直到米斯利弗·玛音，就是所有的西顿人，我必在以色列人面前赶出他们去。你只管照我所吩咐的，将这地拈阄分给以色列人为业。","notes":[]},{"n":7,"t":"现在你要把这地分给九个支派和玛拿西半个支派为业。」","notes":[]},{"n":8,"t":"玛拿西那半支派和吕便、迦得二支派已经受了产业，就是耶和华的仆人摩西在约旦河东所赐给他们的：","notes":[],"heads":["分配约旦河东之地"]},{"n":9,"t":"是从亚嫩谷边的亚罗珥和谷中的城，并米底巴的全平原，直到底本，","notes":[]},{"n":10,"t":"和在希实本作王亚摩利王西宏的诸城，直到亚扪人的境界；","notes":[]},{"n":11,"t":"又有基列地、基述人、玛迦人的地界，并黑门全山、巴珊全地，直到撒迦；","notes":[]},{"n":12,"t":"又有巴珊王噩的全国—他在亚斯他录和以得来作王（利乏音人所存留的只剩下他）。这些地的人都是摩西所击杀、所赶逐的。","notes":[]},{"n":13,"t":"以色列人却没有赶逐基述人、玛迦人；这些人仍住在以色列中，直到今日。","notes":[]},{"n":14,"t":"只是利未支派，摩西没有把产业分给他们。他们的产业乃是献与耶和华—以色列神的火祭，正如耶和华所应许他们的。","notes":["原文是他"]},{"n":15,"t":"摩西按着吕便支派的宗族分给他们产业。","notes":[],"heads":["分给吕便支派的土地"]},{"n":16,"t":"他们的境界是亚嫩谷边的亚罗珥和谷中的城，靠近米底巴的全平原；","notes":[]},{"n":17,"t":"希实本并属希实本平原的各城，底本、巴末·巴力、伯·巴力·勉、","notes":[]},{"n":18,"t":"雅杂、基底莫、米法押、","notes":[]},{"n":19,"t":"基列亭、西比玛、谷中山的细列·哈沙辖、","notes":[]},{"n":20,"t":"伯·毗珥、毗斯迦山坡、伯·耶西末；","notes":[]},{"n":21,"t":"平原的各城，并亚摩利王西宏的全国。这西宏曾在希实本作王，摩西把他和米甸的族长以未、利金、苏珥、户珥、利巴击杀了；这都是住那地属西宏为首领的。","notes":[]},{"n":22,"t":"那时以色列人在所杀的人中，也用刀杀了比珥的儿子术士巴兰。","notes":[]},{"n":23,"t":"吕便人的境界就是约旦河与靠近约旦河的地。以上是吕便人按着宗族所得为业的诸城，并属城的村庄。","notes":[]},{"n":24,"t":"摩西按着迦得支派的宗族分给他们产业。","notes":[],"heads":["分给迦得支派的土地"]},{"n":25,"t":"他们的境界是雅谢和基列的各城，并亚扪人的一半地，直到拉巴前的亚罗珥；","notes":[]},{"n":26,"t":"从希实本到拉抹·米斯巴和比多宁，又从玛哈念到底璧的境界，","notes":[]},{"n":27,"t":"并谷中的伯·亚兰、伯·宁拉、疏割、撒分，就是希实本王西宏国中的余地，以及约旦河与靠近约旦河的地，直到基尼烈海的极边，都在约旦河东。","notes":[]},{"n":28,"t":"以上是迦得人按着宗族所得为业的诸城，并属城的村庄。","notes":[]},{"n":29,"t":"摩西把产业分给玛拿西半支派，是按着玛拿西半支派的宗族所分的。","notes":[],"heads":["分给玛拿西半支派的土地"]},{"n":30,"t":"他们的境界是从玛哈念起，包括巴珊全地，就是巴珊王噩的全国，并在巴珊、睚珥的一切城邑，共六十个。","notes":[]},{"n":31,"t":"基列的一半，并亚斯他录、以得来，就是属巴珊王噩国的二城，是按着宗族给玛拿西的儿子玛吉的一半子孙。","notes":[]},{"n":32,"t":"以上是摩西在约旦河东对着耶利哥的摩押平原所分给他们的产业。","notes":[]},{"n":33,"t":"只是利未支派，摩西没有把产业分给他们。耶和华—以色列的神是他们的产业，正如耶和华所应许他们的。","notes":[]}]},"14":{"heading":"分配约旦河西的土地","verses":[{"n":1,"t":"以色列人在迦南地所得的产业，就是祭司以利亚撒和嫩的儿子约书亚，并以色列各支派的族长所分给他们的，都记在下面，","notes":[]},{"n":2,"t":"是照耶和华借摩西所吩咐的，把产业拈阄分给九个半支派。","notes":[]},{"n":3,"t":"原来，摩西在约旦河东已经把产业分给那两个半支派，只是在他们中间没有把产业分给利未人。","notes":[]},{"n":4,"t":"因为约瑟的子孙是两个支派，就是玛拿西和以法莲，所以没有把地分给利未人，但给他们城邑居住，并城邑的郊野，可以牧养他们的牲畜，安置他们的财物。","notes":[]},{"n":5,"t":"耶和华怎样吩咐摩西，以色列人就照样行，把地分了。","notes":[]},{"n":6,"t":"那时，犹大人来到吉甲见约书亚，有基尼洗族耶孚尼的儿子迦勒对约书亚说：「耶和华在加低斯·巴尼亚指着我与你对神人摩西所说的话，你都知道了。","notes":[],"heads":["迦勒得希伯仑为业"]},{"n":7,"t":"耶和华的仆人摩西从加低斯·巴尼亚打发我窥探这地，那时我正四十岁；我按着心意回报他。","notes":[]},{"n":8,"t":"然而，同我上去的众弟兄使百姓的心消化；但我专心跟从耶和华—我的神。","notes":[]},{"n":9,"t":"当日摩西起誓说：『你脚所踏之地定要归你和你的子孙永远为业，因为你专心跟从耶和华—我的神。』","notes":[]},{"n":10,"t":"自从耶和华对摩西说这话的时候，耶和华照他所应许的使我存活这四十五年；其间以色列人在旷野行走。看哪，现今我八十五岁了，","notes":[]},{"n":11,"t":"我还是强壮，像摩西打发我去的那天一样；无论是争战，是出入，我的力量那时如何，现在还是如何。","notes":[]},{"n":12,"t":"求你将耶和华那日应许我的这山地给我；那里有亚衲族人，并宽大坚固的城，你也曾听见了。或者耶和华照他所应许的与我同在，我就把他们赶出去。」","notes":[]},{"n":13,"t":"于是约书亚为耶孚尼的儿子迦勒祝福，将希伯仑给他为业。","notes":[]},{"n":14,"t":"所以希伯仑作了基尼洗族耶孚尼的儿子迦勒的产业，直到今日，因为他专心跟从耶和华—以色列的神。","notes":[]},{"n":15,"t":"希伯仑从前名叫基列·亚巴；亚巴是亚衲族中最尊大的人。于是国中太平，没有争战了。","notes":[]}]},"15":{"heading":"分给犹大支派的土地","verses":[{"n":1,"t":"犹大支派按着宗族拈阄所得之地是在尽南边，到以东的交界，向南直到寻的旷野。","notes":[]},{"n":2,"t":"他们的南界是从盐海的尽边，就是从朝南的海汊起，","notes":[]},{"n":3,"t":"通到亚克拉滨坡的南边，接连到寻，上到加低斯·巴尼亚的南边，又过希斯仑，上到亚达珥，绕到甲加，","notes":[]},{"n":4,"t":"接连到押们，通到埃及小河，直通到海为止。这就是他们的南界。","notes":[]},{"n":5,"t":"东界是从盐海南边到约旦河口。北界是从约旦河口的海汊起，","notes":[]},{"n":6,"t":"上到伯·曷拉，过伯·亚拉巴的北边，上到吕便之子波罕的磐石；","notes":[]},{"n":7,"t":"从亚割谷往北，上到底璧，直向河南亚都冥坡对面的吉甲；又接连到隐·示麦泉，直通到隐·罗结，","notes":[]},{"n":8,"t":"上到欣嫩子谷，贴近耶布斯的南界（耶布斯就是耶路撒冷）；又上到欣嫩谷西边的山顶，就是在利乏音谷极北的边界；","notes":[]},{"n":9,"t":"又从山顶延到尼弗多亚的水源，通到以弗仑山的城邑，又延到巴拉（巴拉就是基列·耶琳）；","notes":[]},{"n":10,"t":"又从巴拉往西绕到西珥山，接连到耶琳山的北边（耶琳就是基撒仑）；又下到伯·示麦过亭纳，","notes":[]},{"n":11,"t":"通到以革伦北边，延到施基仑，接连到巴拉山；又通到雅比聂，直通到海为止。","notes":[]},{"n":12,"t":"西界就是大海和靠近大海之地。这是犹大人按着宗族所得之地四围的交界。","notes":[]},{"n":13,"t":"约书亚照耶和华所吩咐的，将犹大人中的一段地，就是基列·亚巴，分给耶孚尼的儿子迦勒。亚巴是亚衲族的始祖（基列·亚巴就是希伯仑）。","notes":[],"heads":["迦勒攻取希伯仑和底璧"]},{"n":14,"t":"迦勒就从那里赶出亚衲族的三个族长，就是示筛、亚希幔、挞买；","notes":[]},{"n":15,"t":"又从那里上去，攻击底璧的居民。（这底璧从前名叫基列·西弗。）","notes":[]},{"n":16,"t":"迦勒说：「谁能攻打基列·西弗将城夺取，我就把我女儿押撒给他为妻。」","notes":[]},{"n":17,"t":"迦勒兄弟基纳斯的儿子俄陀聂夺取了那城，迦勒就把女儿押撒给他为妻。","notes":[]},{"n":18,"t":"押撒过门的时候，劝丈夫向她父亲求一块田，押撒一下驴，迦勒问她说：「你要什么？」","notes":[]},{"n":19,"t":"她说：「求你赐福给我，你既将我安置在南地，求你也给我水泉。」她父亲就把上泉下泉赐给她。","notes":[]},{"n":20,"t":"以下是犹大支派按着宗族所得的产业。","notes":[],"heads":["犹大所得的城邑"]},{"n":21,"t":"犹大支派尽南边的城邑，与以东交界相近的，就是甲薛、以得、雅姑珥、","notes":[]},{"n":22,"t":"基拿、底摩拿、亚大达、","notes":[]},{"n":23,"t":"基低斯、夏琐、以提楠、","notes":[]},{"n":24,"t":"西弗、提链、比亚绿、","notes":[]},{"n":25,"t":"夏琐·哈大他、加略·希斯仑（加略·希斯仑就是夏琐）、","notes":[]},{"n":26,"t":"亚曼、示玛、摩拉大、","notes":[]},{"n":27,"t":"哈萨·迦大、黑实门、伯·帕列、","notes":[]},{"n":28,"t":"哈萨·书亚、别是巴、比斯约他、","notes":[]},{"n":29,"t":"巴拉、以因、以森、","notes":[]},{"n":30,"t":"伊勒多腊、基失、何珥玛、","notes":[]},{"n":31,"t":"洗革拉、麦玛拿、三撒拿、","notes":[]},{"n":32,"t":"利巴勿、实忻、亚因、临门，共二十九座城，还有属城的村庄。","notes":[]},{"n":33,"t":"在高原有以实陶、琐拉、亚实拿、","notes":[]},{"n":34,"t":"撒挪亚、隐·干宁、他普亚、以楠、","notes":[]},{"n":35,"t":"耶末、亚杜兰、梭哥、亚西加、","notes":[]},{"n":36,"t":"沙拉音、亚底他音、基底拉、基底罗他音，共十四座城，还有属城的村庄。","notes":[]},{"n":37,"t":"又有洗楠、哈大沙、麦大·迦得、","notes":[]},{"n":38,"t":"底连、米斯巴、约帖、","notes":[]},{"n":39,"t":"拉吉、波斯加、伊矶伦、","notes":[]},{"n":40,"t":"迦本、拉幔、基提利、","notes":[]},{"n":41,"t":"基低罗、伯·大衮、拿玛、玛基大，共十六座城，还有属城的村庄。","notes":[]},{"n":42,"t":"又有立拿、以帖、亚珊、","notes":[]},{"n":43,"t":"益弗他、亚实拿、尼悉、","notes":[]},{"n":44,"t":"基伊拉、亚革悉、玛利沙，共九座城，还有属城的村庄。","notes":[]},{"n":45,"t":"又有以革伦和属以革伦的镇市村庄；","notes":[]},{"n":46,"t":"从以革伦直到海，一切靠近亚实突之地，并属其地的村庄。","notes":[]},{"n":47,"t":"亚实突和属亚实突的镇市村庄；迦萨和属迦萨的镇市村庄；直到埃及小河，并大海和靠近大海之地。","notes":[]},{"n":48,"t":"在山地有沙密、雅提珥、梭哥、","notes":[]},{"n":49,"t":"大拿、基列·萨拿（基列·萨拿就是底璧）、","notes":[]},{"n":50,"t":"亚拿伯、以实提莫、亚念、","notes":[]},{"n":51,"t":"歌珊、何伦、基罗，共十一座城，还有属城的村庄。","notes":[]},{"n":52,"t":"又有亚拉、度玛、以珊、","notes":[]},{"n":53,"t":"雅农、伯·他普亚、亚非加、","notes":[]},{"n":54,"t":"宏他、基列·亚巴（基列·亚巴就是希伯仑）、洗珥，共九座城，还有属城的村庄。","notes":[]},{"n":55,"t":"又有玛云、迦密、西弗、淤他、","notes":[]},{"n":56,"t":"耶斯列、约甸、撒挪亚、","notes":[]},{"n":57,"t":"该隐、基比亚、亭纳，共十座城，还有属城的村庄。","notes":[]},{"n":58,"t":"又有哈忽、伯·夙、基突、","notes":[]},{"n":59,"t":"玛腊、伯·亚诺、伊勒提君，共六座城，还有属城的村庄。","notes":[]},{"n":60,"t":"又有基列·巴力（基列·巴力就是基列·耶琳）、拉巴，共两座城，还有属城的村庄。","notes":[]},{"n":61,"t":"在旷野有伯·亚拉巴、密丁、西迦迦、","notes":[]},{"n":62,"t":"匿珊、盐城、隐·基底，共六座城，还有属城的村庄。","notes":[]},{"n":63,"t":"至于住耶路撒冷的耶布斯人，犹大人不能把他们赶出去，耶布斯人却在耶路撒冷与犹大人同住，直到今日。","notes":[]}]},"16":{"heading":"分给以法莲支派和玛拿西半支派的土地","verses":[{"n":1,"t":"约瑟的子孙拈阄所得之地是从靠近耶利哥的约旦河起，以耶利哥东边的水为界：从耶利哥上去，通过山地的旷野，到伯特利；","notes":[]},{"n":2,"t":"又从伯特利到路斯，接连到亚基人的境界，至亚他绿；","notes":[]},{"n":3,"t":"又往西下到押利提人的境界，到下伯·和仑的境界，直到基色，通到海为止。","notes":[]},{"n":4,"t":"约瑟的儿子玛拿西、以法莲就得了他们的地业。","notes":[]},{"n":5,"t":"以法莲子孙的境界，按着宗族所得的，记在下面：他们地业的东界是亚他绿·亚达到上伯·和仑；","notes":[],"heads":["以法莲支派"]},{"n":6,"t":"往西通到北边的密米他，又向东绕到他纳·示罗，又接连到雅挪哈的东边；","notes":[]},{"n":7,"t":"从雅挪哈下到亚他绿，又到拿拉，达到耶利哥，通到约旦河为止；","notes":[]},{"n":8,"t":"从他普亚往西，到加拿河，直通到海为止。这就是以法莲支派按着宗族所得的地业。","notes":[]},{"n":9,"t":"另外在玛拿西人地业中得了些城邑和属城的村庄。这都是分给以法莲子孙的。","notes":[]},{"n":10,"t":"他们没有赶出住基色的迦南人；迦南人却住在以法莲人中间，成为做苦工的仆人，直到今日。","notes":[]}]},"17":{"heading":"西玛拿西半支派","verses":[{"n":1,"t":"玛拿西是约瑟的长子，他的支派拈阄所得之地记在下面。至于玛拿西的长子基列之父玛吉，因为是勇士就得了基列和巴珊。","notes":["或译：主"]},{"n":2,"t":"玛拿西其余的子孙，按着宗族拈阄分地，就是亚比以谢子孙，希勒子孙，亚斯列子孙，示剑子孙，希弗子孙，示米大子孙；这些按着宗族，都是约瑟儿子玛拿西子孙的男丁。","notes":[]},{"n":3,"t":"玛拿西的玄孙，玛吉的曾孙，基列的孙子，希弗的儿子西罗非哈没有儿子，只有女儿。他的女儿名叫玛拉、挪阿、曷拉、密迦、得撒；","notes":[]},{"n":4,"t":"她们来到祭司以利亚撒和嫩的儿子约书亚并众首领面前，说：「耶和华曾吩咐摩西在我们弟兄中分给我们产业。」于是约书亚照耶和华所吩咐的，在她们伯叔中，把产业分给她们。","notes":[]},{"n":5,"t":"除了约旦河东的基列和巴珊地之外，还有十分地归玛拿西，","notes":[]},{"n":6,"t":"因为玛拿西的孙女们在玛拿西的孙子中得了产业。基列地是属玛拿西其余的子孙。","notes":[]},{"n":7,"t":"玛拿西的境界：从亚设起，到示剑前的密米他，往北到隐·他普亚居民之地。","notes":[]},{"n":8,"t":"他普亚地归玛拿西，只是玛拿西境界上的他普亚城归以法莲子孙。","notes":[]},{"n":9,"t":"其界下到加拿河的南边。在玛拿西城邑中的这些城邑都归以法莲。玛拿西的地界是在河北直通到海为止；","notes":[]},{"n":10,"t":"南归以法莲，北归玛拿西，以海为界；北边到亚设，东边到以萨迦。","notes":[]},{"n":11,"t":"玛拿西在以萨迦和亚设境内，有伯·善和属伯·善的镇市，以伯莲和属以伯莲的镇市，多珥的居民和属多珥的镇市；又有三处山冈，就是隐·多珥和属隐·多珥的镇市；他纳的居民和属他纳的镇市，米吉多的居民和属米吉多的镇市。","notes":[]},{"n":12,"t":"只是玛拿西子孙不能赶出这些城的居民，迦南人偏要住在那地。","notes":[]},{"n":13,"t":"及至以色列人强盛了，就使迦南人做苦工，没有把他们全然赶出。","notes":[]},{"n":14,"t":"约瑟的子孙对约书亚说：「耶和华到如今既然赐福与我们，我们也族大人多，你为什么仅将一阄一段之地分给我们为业呢？」","notes":[],"heads":["约瑟子孙要求多得土地"]},{"n":15,"t":"约书亚说：「你们如果族大人多，嫌以法莲山地窄小，就可以上比利洗人、利乏音人之地，在树林中砍伐树木。」","notes":[]},{"n":16,"t":"约瑟的子孙说：「那山地容不下我们，并且住平原的迦南人，就是住伯·善和属伯·善的镇市，并住耶斯列平原的人，都有铁车。」","notes":[]},{"n":17,"t":"约书亚对约瑟家，就是以法莲和玛拿西人，说：「你是族大人多，并且强盛，不可仅有一阄之地，","notes":[]},{"n":18,"t":"山地也要归你，虽是树林，你也可以砍伐；靠近之地必归你。迦南人虽有铁车，虽是强盛，你也能把他们赶出去。」","notes":[]}]},"18":{"heading":"余地的分配","verses":[{"n":1,"t":"以色列的全会众都聚集在示罗，把会幕设立在那里，那地已经被他们制伏了。","notes":[]},{"n":2,"t":"以色列人中其余的七个支派还没有分给他们地业。","notes":[]},{"n":3,"t":"约书亚对以色列人说：「耶和华—你们列祖的神所赐给你们的地，你们耽延不去得，要到几时呢？","notes":[]},{"n":4,"t":"你们每支派当选举三个人，我要打发他们去，他们就要起身走遍那地，按着各支派应得的地业写明，就回到我这里来。","notes":["或译：画图"]},{"n":5,"t":"他们要将地分做七分；犹大仍在南方，住在他的境内。约瑟家仍在北方，住在他的境内。","notes":[]},{"n":6,"t":"你们要将地分做七分，写明了拿到我这里来。我要在耶和华—我们神面前，为你们拈阄。","notes":[]},{"n":7,"t":"利未人在你们中间没有分，因为供耶和华祭司的职任就是他们的产业。迦得支派、吕便支派，和玛拿西半支派已经在约旦河东得了地业，就是耶和华仆人摩西所给他们的。」","notes":[]},{"n":8,"t":"划地势的人起身去的时候，约书亚嘱咐他们说：「你们去走遍那地，划明地势，就回到我这里来。我要在示罗这里，耶和华面前，为你们拈阄。」","notes":[]},{"n":9,"t":"他们就去了，走遍那地，按着城邑分做七分，写在册子上，回到示罗营中见约书亚。","notes":[]},{"n":10,"t":"约书亚就在示罗，耶和华面前，为他们拈阄。约书亚在那里，按着以色列人的支派，将地分给他们。","notes":[]},{"n":11,"t":"便雅悯支派，按着宗族拈阄所得之地，是在犹大、约瑟子孙中间。","notes":[],"heads":["分给便雅悯支派的土地"]},{"n":12,"t":"他们的北界是从约旦河起，往上贴近耶利哥的北边；又往西通过山地，直到伯·亚文的旷野；","notes":[]},{"n":13,"t":"从那里往南接连到路斯，贴近路斯（路斯就是伯特利），又下到亚他绿·亚达，靠近下伯·和仑南边的山；","notes":[]},{"n":14,"t":"从那里往西，又转向南，从伯·和仑南对面的山，直达到犹大人的城基列·巴力（基列·巴力就是基列·耶琳）；这是西界。","notes":[]},{"n":15,"t":"南界是从基列·耶琳的尽边起，往西达到尼弗多亚的水源；","notes":[]},{"n":16,"t":"又下到欣嫩子谷对面山的尽边，就是利乏音谷北边的山；又下到欣嫩谷，贴近耶布斯的南边；又下到隐·罗结；","notes":[]},{"n":17,"t":"又往北通到隐·示麦，达到亚都冥坡对面的基利绿；又下到吕便之子波罕的磐石；","notes":[]},{"n":18,"t":"又接连到亚拉巴对面，往北下到亚拉巴；","notes":[]},{"n":19,"t":"又接连到伯·曷拉的北边，直通到盐海的北汊，就是约旦河的南头；这是南界。","notes":[]},{"n":20,"t":"东界是约旦河。这是便雅悯人按着宗族，照他们四围的交界所得的地业。","notes":[]},{"n":21,"t":"便雅悯支派按着宗族所得的城邑就是：耶利哥、伯·曷拉、伊麦·基悉、","notes":[]},{"n":22,"t":"伯·亚拉巴、洗玛脸、伯特利、","notes":[]},{"n":23,"t":"亚文、巴拉、俄弗拉、","notes":[]},{"n":24,"t":"基法·阿摩尼、俄弗尼、迦巴，共十二座城，还有属城的村庄；","notes":[]},{"n":25,"t":"又有基遍、拉玛、比录、","notes":[]},{"n":26,"t":"米斯巴、基非拉、摩撒、","notes":[]},{"n":27,"t":"利坚、伊利毗勒、他拉拉、","notes":[]},{"n":28,"t":"洗拉、以利弗、耶布斯（耶布斯就是耶路撒冷）、基比亚、基列，共十四座城，还有属城的村庄。这是便雅悯人按着宗族所得的地业。","notes":[]}]},"19":{"heading":"分给西缅支派的土地","verses":[{"n":1,"t":"为西缅支派的人，按着宗族，拈出第二阄。他们所得的地业是在犹大人地业中间。","notes":[]},{"n":2,"t":"他们所得为业之地就是：别是巴（或名示巴）、摩拉大、","notes":[]},{"n":3,"t":"哈萨·书亚、巴拉、以森、","notes":[]},{"n":4,"t":"伊利多拉、比土力、何珥玛、","notes":[]},{"n":5,"t":"洗革拉、伯·玛加博、哈萨·苏撒、","notes":[]},{"n":6,"t":"伯·利巴勿、沙鲁险，共十三座城，还有属城的村庄；","notes":[]},{"n":7,"t":"又有亚因、利门、以帖、亚珊，共四座城，还有属城的村庄；","notes":[]},{"n":8,"t":"并有这些城邑四围一切的村庄，直到巴拉·比珥，就是南地的拉玛。这是西缅支派按着宗族所得的地业。","notes":[]},{"n":9,"t":"西缅人的地业是从犹大人地业中得来的；因为犹大人的分过多，所以西缅人在他们的地业中得了地业。","notes":[]},{"n":10,"t":"为西布伦人，按着宗族，拈出第三阄。他们地业的境界是到撒立；","notes":[],"heads":["分给西布伦支派的土地"]},{"n":11,"t":"往西上到玛拉拉，达到大巴设，又达到约念前的河；","notes":[]},{"n":12,"t":"又从撒立往东转向日出之地，到吉斯绿·他泊的境界，又通到大比拉，上到雅非亚；","notes":[]},{"n":13,"t":"从那里往东，接连到迦特·希弗，至以特·加汛，通到临门，临门延到尼亚；","notes":[]},{"n":14,"t":"又绕过尼亚的北边，转到哈拿顿，通到伊弗他·伊勒谷。","notes":[]},{"n":15,"t":"还有加他、拿哈拉、伸仑、以大拉、伯利恒，共十二座城，还有属城的村庄。","notes":[]},{"n":16,"t":"这些城并属城的村庄就是西布伦人按着宗族所得的地业。","notes":[]},{"n":17,"t":"为以萨迦人，按着宗族，拈出第四阄。","notes":[],"heads":["分给以萨迦支派的土地"]},{"n":18,"t":"他们的境界是到耶斯列、基苏律、书念、","notes":[]},{"n":19,"t":"哈弗连、示按、亚拿哈拉、","notes":[]},{"n":20,"t":"拉璧、基善、亚别、","notes":[]},{"n":21,"t":"利篾、隐·干宁、隐·哈大、伯·帕薛；","notes":[]},{"n":22,"t":"又达到他泊、沙哈洗玛、伯·示麦，直通到约旦河为止，共十六座城，还有属城的村庄。","notes":[]},{"n":23,"t":"这些城并属城的村庄就是以萨迦支派按着宗族所得的地业。","notes":[]},{"n":24,"t":"为亚设支派，按着宗族，拈出第五阄。","notes":[],"heads":["分给亚设支派的土地"]},{"n":25,"t":"他们的境界是黑甲、哈利、比田、押煞、","notes":[]},{"n":26,"t":"亚拉米勒、亚末、米沙勒；往西达到迦密，又到希曷·立纳，","notes":[]},{"n":27,"t":"转向日出之地，到伯·大衮，达到细步纶；往北到伊弗他·伊勒谷，到伯·以墨和尼业，也通到迦步勒的左边；","notes":[]},{"n":28,"t":"又到义伯仑、利合、哈们、加拿，直到西顿大城；","notes":[]},{"n":29,"t":"转到拉玛和坚固城泰尔；又转到何萨，靠近亚革悉一带地方，直通到海；","notes":[]},{"n":30,"t":"又有乌玛、亚弗、利合，共二十二座城，还有属城的村庄。","notes":[]},{"n":31,"t":"这些城并属城的村庄就是亚设支派按着宗族所得的地业。","notes":[]},{"n":32,"t":"为拿弗他利人，按着宗族，拈出第六阄。","notes":[],"heads":["分给拿弗他利支派的土地"]},{"n":33,"t":"他们的境界是从希利弗从撒拿音的橡树，从亚大米·尼吉和雅比聂，直到拉共，通到约旦河；","notes":[]},{"n":34,"t":"又转向西到亚斯纳·他泊，从那里通到户割，南边到西布伦，西边到亚设，又向日出之地，达到约旦河那里的犹大。","notes":[]},{"n":35,"t":"坚固的城就是：西丁、侧耳、哈末、拉甲、基尼烈、","notes":[]},{"n":36,"t":"亚大玛、拉玛、夏琐、","notes":[]},{"n":37,"t":"基低斯、以得来、隐·夏琐、","notes":[]},{"n":38,"t":"以利稳、密大·伊勒、和琏、伯·亚纳、伯·示麦，共十九座城，还有属城的村庄。","notes":[]},{"n":39,"t":"这些城并属城的村庄就是拿弗他利支派按着宗族所得的地业。","notes":[]},{"n":40,"t":"为但支派，按着宗族，拈出第七阄。","notes":[],"heads":["分给但支派的土地"]},{"n":41,"t":"他们地业的境界是琐拉、以实陶、伊珥·示麦、","notes":[]},{"n":42,"t":"沙拉宾、亚雅仑、伊提拉、","notes":[]},{"n":43,"t":"以伦、亭拿他、以革伦、","notes":[]},{"n":44,"t":"伊利提基、基比顿、巴拉、","notes":[]},{"n":45,"t":"伊胡得、比尼·比拉、迦特·临门、","notes":[]},{"n":46,"t":"美·耶昆、拉昆，并约帕对面的地界。","notes":[]},{"n":47,"t":"但人的地界越过原得的地界；因为但人上去攻取利善，用刀击杀城中的人，得了那城，住在其中，以他们先祖但的名将利善改名为但。","notes":[]},{"n":48,"t":"这些城并属城的村庄就是但支派按着宗族所得的地业。","notes":[]},{"n":49,"t":"以色列人按着境界分完了地业，就在他们中间将地给嫩的儿子约书亚为业，","notes":[],"heads":["最后分配的土地"]},{"n":50,"t":"是照耶和华的吩咐，将约书亚所求的城，就是以法莲山地的亭拿·西拉城，给了他。他就修那城，住在其中。","notes":[]},{"n":51,"t":"这就是祭司以利亚撒和嫩的儿子约书亚，并以色列各支派的族长，在示罗会幕门口，耶和华面前，拈阄所分的地业。这样，他们把地分完了。","notes":[]}]},"20":{"heading":"设立逃城","verses":[{"n":1,"t":"耶和华晓谕约书亚说：","notes":[]},{"n":2,"t":"「你吩咐以色列人说：你们要照着我借摩西所晓谕你们的，为自己设立逃城，","notes":[]},{"n":3,"t":"使那无心而误杀人的，可以逃到那里。这些城可以作你们逃避报血仇人的地方。","notes":[]},{"n":4,"t":"那杀人的要逃到这些城中的一座城，站在城门口，将他的事情说给城内的长老们听。他们就把他收进城里，给他地方，使他住在他们中间。","notes":[]},{"n":5,"t":"若是报血仇的追了他来，长老不可将他交在报血仇的手里；因为他是素无仇恨，无心杀了人的。","notes":[]},{"n":6,"t":"他要住在那城里，站在会众面前听审判，等到那时的大祭司死了，杀人的才可以回到本城本家，就是他所逃出来的那城。」","notes":[]},{"n":7,"t":"于是，以色列人在拿弗他利山地分定加利利的基低斯；在以法莲山地分定示剑；在犹大山地分定基列·亚巴（基列·亚巴就是希伯仑）；","notes":[]},{"n":8,"t":"又在约旦河外耶利哥东，从吕便支派中，在旷野的平原，设立比悉；从迦得支派中设立基列的拉末；从玛拿西支派中设立巴珊的哥兰。","notes":[]},{"n":9,"t":"这都是为以色列众人和在他们中间寄居的外人所分定的城邑，使误杀人的都可以逃到那里，不死在报血仇人的手中，等他站在会众面前听审判。","notes":[]}]},"21":{"heading":"利未人的城邑","verses":[{"n":1,"t":"那时，利未人的众族长来到祭司以利亚撒和嫩的儿子约书亚，并以色列各支派的族长面前，","notes":[]},{"n":2,"t":"在迦南地的示罗对他们说：「从前耶和华借着摩西吩咐给我们城邑居住，并城邑的郊野可以牧养我们的牲畜。」","notes":[]},{"n":3,"t":"于是以色列人照耶和华所吩咐的，从自己的地业中，将以下所记的城邑和城邑的郊野给了利未人。","notes":[]},{"n":4,"t":"为哥辖族拈阄：利未人的祭司、亚伦的子孙，从犹大支派、西缅支派、便雅悯支派的地业中，按阄得了十三座城。","notes":[]},{"n":5,"t":"哥辖其余的子孙，从以法莲支派、但支派、玛拿西半支派的地业中，按阄得了十座城。","notes":[]},{"n":6,"t":"革顺的子孙，从以萨迦支派、亚设支派、拿弗他利支派、住巴珊的玛拿西半支派的地业中，按阄得了十三座城。","notes":[]},{"n":7,"t":"米拉利的子孙，按着宗族，从吕便支派、迦得支派、西布伦支派的地业中，按阄得了十二座城。","notes":[]},{"n":8,"t":"以色列人照着耶和华借摩西所吩咐的，将这些城邑和城邑的郊野，按阄分给利未人。","notes":[]},{"n":9,"t":"从犹大支派、西缅支派的地业中，将以下所记的城给了利未支派哥辖宗族亚伦的子孙；因为给他们拈出头一阄，","notes":[],"end":10},{"n":11,"t":"将犹大山地的基列·亚巴和四围的郊野给了他们。亚巴是亚衲族的始祖。（基列·亚巴就是希伯仑）。","notes":[]},{"n":12,"t":"惟将属城的田地和村庄给了耶孚尼的儿子迦勒为业。","notes":[]},{"n":13,"t":"以色列人将希伯仑，就是误杀人的逃城和属城的郊野，给了祭司亚伦的子孙；又给他们立拿和属城的郊野，","notes":[]},{"n":14,"t":"雅提珥和属城的郊野，以实提莫和属城的郊野，","notes":[]},{"n":15,"t":"何仑和属城的郊野，底璧和属城的郊野，","notes":[]},{"n":16,"t":"亚因和属城的郊野，淤他和属城的郊野，伯·示麦和属城的郊野，共九座城，都是从这二支派中分出来的。","notes":[]},{"n":17,"t":"又从便雅悯支派的地业中给了他们基遍和属城的郊野，迦巴和属城的郊野，","notes":[]},{"n":18,"t":"亚拿突和属城的郊野，亚勒们和属城的郊野，共四座城。","notes":[]},{"n":19,"t":"亚伦子孙作祭司的共有十三座城，还有属城的郊野。","notes":[]},{"n":20,"t":"利未支派中哥辖的宗族，就是哥辖其余的子孙，拈阄所得的城有从以法莲支派中分出来的。","notes":[]},{"n":21,"t":"以色列人将以法莲山地的示剑，就是误杀人的逃城和属城的郊野，给了他们；又给他们基色和属城的郊野，","notes":[]},{"n":22,"t":"基伯先和属城的郊野，伯·和仑和属城的郊野，共四座城；","notes":[]},{"n":23,"t":"又从但支派的地业中给了他们伊利提基和属城的郊野，基比顿和属城的郊野，","notes":[]},{"n":24,"t":"亚雅仑和属城的郊野，迦特·临门和属城的郊野，共四座城；","notes":[]},{"n":25,"t":"又从玛拿西半支派的地业中给了他们他纳和属城的郊野，迦特·临门和属城的郊野，共两座城。","notes":[]},{"n":26,"t":"哥辖其余的子孙共有十座城，还有属城的郊野。","notes":[]},{"n":27,"t":"以色列人又从玛拿西半支派的地业中将巴珊的哥兰，就是误杀人的逃城和属城的郊野，给了利未支派革顺的子孙；又给他们比·施提拉和属城的郊野，共两座城；","notes":[]},{"n":28,"t":"又从以萨迦支派的地业中给了他们基善和属城的郊野，大比拉和属城的郊野，","notes":[]},{"n":29,"t":"耶末和属城的郊野，隐·干宁和属城的郊野，共四座城；","notes":[]},{"n":30,"t":"又从亚设支派的地业中给了他们米沙勒和属城的郊野，押顿和属城的郊野，","notes":[]},{"n":31,"t":"黑甲和属城的郊野，利合和属城的郊野，共四座城；","notes":[]},{"n":32,"t":"又从拿弗他利支派的地业中将加利利的基低斯，就是误杀人的逃城和属城的郊野，给了他们；又给他们哈末·多珥和属城的郊野，加珥坦和属城的郊野，共三座城。","notes":[]},{"n":33,"t":"革顺人按着宗族所得的城，共十三座，还有属城的郊野。","notes":[]},{"n":34,"t":"其余利未支派米拉利子孙，从西布伦支派的地业中所得的，就是约念和属城的郊野，加珥他和属城的郊野，","notes":[]},{"n":35,"t":"丁拿和属城的郊野，拿哈拉和属城的郊野，共四座城；","notes":[]},{"n":36,"t":"又从吕便支派的地业中给了他们比悉和属城的郊野，雅杂和属城的郊野，","notes":[]},{"n":37,"t":"基底莫和属城的郊野，米法押和属城的郊野，共四座城；","notes":[]},{"n":38,"t":"又从迦得支派的地业中，将基列的拉末，就是误杀人的逃城和属城的郊野，给了他们；又给他们玛哈念和属城的郊野，","notes":[]},{"n":39,"t":"希实本和属城的郊野，雅谢和属城的郊野，共四座城。","notes":[]},{"n":40,"t":"其余利未支派的人，就是米拉利的子孙，按着宗族拈阄所得的，共十二座城。","notes":[]},{"n":41,"t":"利未人在以色列人的地业中所得的城，共四十八座，并有属城的郊野。","notes":[]},{"n":42,"t":"这些城四围都有属城的郊野，城城都是如此。","notes":[]},{"n":43,"t":"这样，耶和华将从前向他们列祖起誓所应许的全地赐给以色列人，他们就得了为业，住在其中。","notes":[],"heads":["以色列人得地为业"]},{"n":44,"t":"耶和华照着向他们列祖起誓所应许的一切话，使他们四境平安；他们一切仇敌中，没有一人在他们面前站立得住。耶和华把一切仇敌都交在他们手中。","notes":[]},{"n":45,"t":"耶和华应许赐福给以色列家的话一句也没有落空，都应验了。","notes":[]}]},"22":{"heading":"约书亚打发二支派半的人回去","verses":[{"n":1,"t":"当时，约书亚召了吕便人、迦得人，和玛拿西半支派的人来，","notes":[]},{"n":2,"t":"对他们说：「耶和华仆人摩西所吩咐你们的，你们都遵守了；我所吩咐你们的，你们也都听从了。","notes":[]},{"n":3,"t":"你们这许多日子，总没有撇离你们的弟兄，直到今日，并守了耶和华—你们神所吩咐你们当守的。","notes":[]},{"n":4,"t":"如今耶和华—你们神照着他所应许的，使你们弟兄得享平安，现在可以转回你们的帐棚，到耶和华的仆人摩西在约旦河东所赐你们为业之地。","notes":[]},{"n":5,"t":"只要切切地谨慎遵行耶和华仆人摩西所吩咐你们的诫命律法，爱耶和华—你们的神，行他一切的道，守他的诫命，专靠他，尽心尽性事奉他。」","notes":[]},{"n":6,"t":"于是约书亚为他们祝福，打发他们去，他们就回自己的帐棚去了。","notes":[]},{"n":7,"t":"玛拿西那半支派，摩西早已在巴珊分给他们地业。这半支派，约书亚在约旦河西，在他们弟兄中，分给他们地业。约书亚打发他们回帐棚的时候为他们祝福，","notes":[]},{"n":8,"t":"对他们说：「你们带许多财物，许多牲畜和金、银、铜、铁，并许多衣服，回你们的帐棚去，要将你们从仇敌夺来的物，与你们众弟兄同分。」","notes":[]},{"n":9,"t":"于是吕便人、迦得人、玛拿西半支派的人从迦南地的示罗起行，离开以色列人，回往他们得为业的基列地，就是照耶和华借摩西所吩咐的得了为业之地。","notes":[]},{"n":10,"t":"吕便人、迦得人，和玛拿西半支派的人到了靠近约旦河的一带迦南地，就在约旦河那里筑了一座坛；那坛看着高大。","notes":[],"heads":["约旦河旁的祭坛"]},{"n":11,"t":"以色列人听说吕便人、迦得人、玛拿西半支派的人靠近约旦河边，在迦南地属以色列人的那边筑了一座坛。","notes":[]},{"n":12,"t":"全会众一听见，就聚集在示罗，要上去攻打他们。","notes":[]},{"n":13,"t":"以色列人打发祭司以利亚撒的儿子非尼哈，往基列地去见吕便人、迦得人、玛拿西半支派的人；","notes":[]},{"n":14,"t":"又打发十个首领与非尼哈同去，就是以色列每支派的一个首领，都是以色列军中的统领。","notes":[]},{"n":15,"t":"他们到了基列地，见吕便人、迦得人，和玛拿西半支派的人，对他们说：","notes":[]},{"n":16,"t":"「耶和华全会众这样说，你们今日转去不跟从耶和华，干犯以色列的神，为自己筑一座坛，悖逆了耶和华，这犯的是什么罪呢？","notes":[]},{"n":17,"t":"从前拜毗珥的罪孽还算小吗？虽然瘟疫临到耶和华的会众，到今日我们还没有洗净这罪。","notes":[]},{"n":18,"t":"你们今日竟转去不跟从耶和华吗？你们今日既悖逆耶和华，明日他必向以色列全会众发怒。","notes":[]},{"n":19,"t":"你们所得为业之地，若嫌不洁净，就可以过到耶和华之地，就是耶和华的帐幕所住之地，在我们中间得地业。只是不可悖逆耶和华，也不可得罪我们，在耶和华—我们神的坛以外为自己筑坛。","notes":[]},{"n":20,"t":"从前谢拉的曾孙亚干岂不是在那当灭的物上犯了罪，就有忿怒临到以色列全会众吗？那人在所犯的罪中不独一人死亡。」","notes":[]},{"n":21,"t":"于是吕便人、迦得人、玛拿西半支派的人回答以色列军中的统领说：","notes":[]},{"n":22,"t":"「大能者神耶和华！大能者神耶和华！他是知道的！以色列人也必知道！我们若有悖逆的意思，或是干犯耶和华（愿你今日不保佑我们），","notes":[]},{"n":23,"t":"为自己筑坛，要转去不跟从耶和华，或是要将燔祭、素祭、平安祭献在坛上，愿耶和华亲自讨我们的罪。","notes":[]},{"n":24,"t":"我们行这事并非无故，是特意做的，说：恐怕日后你们的子孙对我们的子孙说：『你们与耶和华—以色列的神有何关涉呢？","notes":[]},{"n":25,"t":"因为耶和华把约旦河定为我们和你们这吕便人、迦得人的交界，你们与耶和华无分了。』这样，你们的子孙就使我们的子孙不再敬畏耶和华了。","notes":[]},{"n":26,"t":"因此我们说：『不如为自己筑一座坛，不是为献燔祭，也不是为献别的祭，","notes":[]},{"n":27,"t":"乃是为你我中间和你我后人中间作证据，好叫我们也在耶和华面前献燔祭、平安祭，和别的祭事奉他，免得你们的子孙日后对我们的子孙说，你们与耶和华无分了。』","notes":[]},{"n":28,"t":"所以我们说：『日后你们对我们，或对我们的后人这样说，我们就可以回答说，你们看我们列祖所筑的坛是耶和华坛的样式；这并不是为献燔祭，也不是为献别的祭，乃是为作你我中间的证据。』","notes":[]},{"n":29,"t":"我们在耶和华—我们神帐幕前的坛以外，另筑一座坛，为献燔祭、素祭，和别的祭，悖逆耶和华，今日转去不跟从他，我们断没有这个意思。」","notes":[]},{"n":30,"t":"祭司非尼哈与会中的首领，就是与他同来以色列军中的统领，听见吕便人、迦得人、玛拿西人所说的话，就都以为美。","notes":[]},{"n":31,"t":"祭司以利亚撒的儿子非尼哈对吕便人、迦得人、玛拿西人说：「今日我们知道耶和华在我们中间，因为你们没有向他犯了这罪。现在你们救以色列人脱离耶和华的手了。」","notes":[]},{"n":32,"t":"祭司以利亚撒的儿子非尼哈与众首领离了吕便人、迦得人，从基列地回往迦南地，到了以色列人那里，便将这事回报他们。","notes":[]},{"n":33,"t":"以色列人以这事为美，就称颂神，不再提上去攻打吕便人、迦得人、毁坏他们所住的地了。","notes":[]},{"n":34,"t":"吕便人、迦得人给坛起名叫证坛，意思说：这坛在我们中间证明耶和华是神。","notes":[]}]},"23":{"heading":"约书亚的遗言","verses":[{"n":1,"t":"耶和华使以色列人安静，不与四围的一切仇敌争战，已经多日。约书亚年纪老迈，","notes":[]},{"n":2,"t":"就把以色列众人的长老、族长、审判官，并官长都召了来，对他们说：「我年纪已经老迈。","notes":[]},{"n":3,"t":"耶和华—你们的神因你们的缘故向那些国所行的一切事，你们亲眼看见了，因那为你们争战的是耶和华—你们的神。","notes":[]},{"n":4,"t":"我所剪除和所剩下的各国，从约旦河起到日落之处的大海，我已经拈阄分给你们各支派为业。","notes":[]},{"n":5,"t":"耶和华—你们的神必将他们从你们面前赶出去，使他们离开你们，你们就必得他们的地为业，正如耶和华—你们的神所应许的。","notes":[]},{"n":6,"t":"所以，你们要大大壮胆，谨守遵行写在摩西律法书上的一切话，不可偏离左右。","notes":[]},{"n":7,"t":"不可与你们中间所剩下的这些国民搀杂。他们的神，你们不可提他的名，不可指着他起誓，也不可事奉、叩拜；","notes":[]},{"n":8,"t":"只要照着你们到今日所行的，专靠耶和华—你们的神。","notes":[]},{"n":9,"t":"因为耶和华已经把又大又强的国民从你们面前赶出；直到今日，没有一人在你们面前站立得住。","notes":[]},{"n":10,"t":"你们一人必追赶千人，因耶和华—你们的神照他所应许的，为你们争战。","notes":[]},{"n":11,"t":"你们要分外谨慎，爱耶和华—你们的神。","notes":[]},{"n":12,"t":"你们若稍微转去，与你们中间所剩下的这些国民联络，彼此结亲，互相往来，","notes":[]},{"n":13,"t":"你们要确实知道，耶和华—你们的神必不再将他们从你们眼前赶出；他们却要成为你们的网罗、机槛、肋上的鞭、眼中的刺，直到你们在耶和华—你们神所赐的这美地上灭亡。","notes":[]},{"n":14,"t":"「我现在要走世人必走的路。你们是一心一意地知道，耶和华—你们神所应许赐福与你们的话没有一句落空，都应验在你们身上了。","notes":[]},{"n":15,"t":"耶和华—你们神所应许的一切福气怎样临到你们身上，耶和华也必照样使各样祸患临到你们身上，直到把你们从耶和华—你们神所赐的这美地上除灭。","notes":[]},{"n":16,"t":"你们若违背耶和华—你们神吩咐你们所守的约，去事奉别神，叩拜他，耶和华的怒气必向你们发作，使你们在他所赐的美地上速速灭亡。」","notes":[]}]},"24":{"heading":"约书亚在示剑向百姓讲话","verses":[{"n":1,"t":"约书亚将以色列的众支派聚集在示剑，召了以色列的长老、族长、审判官，并官长来，他们就站在神面前。","notes":[]},{"n":2,"t":"约书亚对众民说：「耶和华—以色列的神如此说：『古时你们的列祖，就是亚伯拉罕和拿鹤的父亲他拉，住在大河那边事奉别神，","notes":[]},{"n":3,"t":"我将你们的祖宗亚伯拉罕从大河那边带来，领他走遍迦南全地，又使他的子孙众多，把以撒赐给他；","notes":[]},{"n":4,"t":"又把雅各和以扫赐给以撒，将西珥山赐给以扫为业；后来雅各和他的子孙下到埃及去了。","notes":[]},{"n":5,"t":"我差遣摩西、亚伦，并照我在埃及中所行的降灾与埃及，然后把你们领出来。","notes":[]},{"n":6,"t":"我领你们列祖出埃及，他们就到了红海；埃及人带领车辆马兵追赶你们列祖到红海。","notes":[]},{"n":7,"t":"你们列祖哀求耶和华，他就使你们和埃及人中间黑暗了，又使海水淹没埃及人。我在埃及所行的事，你们亲眼见过。你们在旷野也住了许多年日。","notes":[]},{"n":8,"t":"我领你们到约旦河东亚摩利人所住之地。他们与你们争战，我将他们交在你们手中，你们便得了他们的地为业；我也在你们面前将他们灭绝。","notes":[]},{"n":9,"t":"那时，摩押王西拨的儿子巴勒起来攻击以色列人，打发人召了比珥的儿子巴兰来咒诅你们。","notes":[]},{"n":10,"t":"我不肯听巴兰的话，所以他倒为你们连连祝福。这样，我便救你们脱离巴勒的手。","notes":[]},{"n":11,"t":"你们过了约旦河，到了耶利哥；耶利哥人、亚摩利人、比利洗人、迦南人、赫人、革迦撒人、希未人、耶布斯人都与你们争战；我把他们交在你们手里。","notes":[]},{"n":12,"t":"我打发黄蜂飞在你们前面，将亚摩利人的二王从你们面前撵出，并不是用你的刀，也不是用你的弓。","notes":[]},{"n":13,"t":"我赐给你们地土，非你们所修治的；我赐给你们城邑，非你们所建造的。你们就住在其中，又得吃非你们所栽种的葡萄园、橄榄园的果子。』","notes":[]},{"n":14,"t":"「现在你们要敬畏耶和华，诚心实意地事奉他，将你们列祖在大河那边和在埃及所事奉的神除掉，去事奉耶和华。","notes":[]},{"n":15,"t":"若是你们以事奉耶和华为不好，今日就可以选择所要事奉的：是你们列祖在大河那边所事奉的神呢？是你们所住这地的亚摩利人的神呢？至于我和我家，我们必定事奉耶和华。」","notes":[]},{"n":16,"t":"百姓回答说：「我们断不敢离弃耶和华去事奉别神；","notes":[]},{"n":17,"t":"因耶和华—我们的神曾将我们和我们列祖从埃及地的为奴之家领出来，在我们眼前行了那些大神迹，在我们所行的道上，所经过的诸国，都保护了我们。","notes":[]},{"n":18,"t":"耶和华又把住此地的亚摩利人都从我们面前赶出去。所以，我们必事奉耶和华，因为他是我们的神。」","notes":[]},{"n":19,"t":"约书亚对百姓说：「你们不能事奉耶和华；因为他是圣洁的神，是忌邪的神，必不赦免你们的过犯罪恶。","notes":[]},{"n":20,"t":"你们若离弃耶和华去事奉外邦神，耶和华在降福之后，必转而降祸与你们，把你们灭绝。」","notes":[]},{"n":21,"t":"百姓回答约书亚说：「不然，我们定要事奉耶和华。」","notes":[]},{"n":22,"t":"约书亚对百姓说：「你们选定耶和华，要事奉他，你们自己作见证吧！」他们说：「我们愿意作见证。」","notes":[]},{"n":23,"t":"约书亚说：「你们现在要除掉你们中间的外邦神，专心归向耶和华—以色列的神。」","notes":[]},{"n":24,"t":"百姓回答约书亚说：「我们必事奉耶和华—我们的神，听从他的话。」","notes":[]},{"n":25,"t":"当日，约书亚就与百姓立约，在示剑为他们立定律例典章。","notes":[]},{"n":26,"t":"约书亚将这些话都写在神的律法书上，又将一块大石头立在橡树下耶和华的圣所旁边。","notes":[]},{"n":27,"t":"约书亚对百姓说：「看哪，这石头可以向我们作见证；因为是听见了耶和华所吩咐我们的一切话，倘或你们背弃你们的神，这石头就可以向你们作见证。」","notes":["倘或…见证：或译所以要向你们作见证，免得你们背弃耶和华—你们的神"]},{"n":28,"t":"于是约书亚打发百姓各归自己的地业去了。","notes":[]},{"n":29,"t":"这些事以后，耶和华的仆人嫩的儿子约书亚，正一百一十岁，就死了。","notes":[],"heads":["约书亚和以利亚撒去世"]},{"n":30,"t":"以色列人将他葬在他地业的境内，就是在以法莲山地的亭拿·西拉，在迦实山的北边。","notes":[]},{"n":31,"t":"约书亚在世和约书亚死后，那些知道耶和华为以色列人所行诸事的长老还在的时候，以色列人事奉耶和华。","notes":[]},{"n":32,"t":"以色列人从埃及所带来约瑟的骸骨，葬埋在示剑，就是在雅各从前用一百块银子向示剑的父亲、哈抹的子孙所买的那块地里；这就作了约瑟子孙的产业。","notes":[]},{"n":33,"t":"亚伦的儿子以利亚撒也死了，就把他葬在他儿子非尼哈所得以法莲山地的小山上。","notes":[]}]}},"JDG":{"1":{"heading":"犹大和西缅支派俘虏亚多尼·比色","verses":[{"n":1,"t":"约书亚死后，以色列人求问耶和华说：「我们中间谁当首先上去攻击迦南人，与他们争战？」","notes":[]},{"n":2,"t":"耶和华说：「犹大当先上去，我已将那地交在他手中。」","notes":[]},{"n":3,"t":"犹大对他哥哥西缅说：「请你同我到拈阄所得之地去，好与迦南人争战；以后我也同你到你拈阄所得之地去。」于是西缅与他同去。","notes":[]},{"n":4,"t":"犹大就上去；耶和华将迦南人和比利洗人交在他们手中。他们在比色击杀了一万人，","notes":[]},{"n":5,"t":"又在那里遇见亚多尼·比色，与他争战，杀败迦南人和比利洗人。","notes":[]},{"n":6,"t":"亚多尼·比色逃跑；他们追赶，拿住他，砍断他手脚的大拇指。","notes":[]},{"n":7,"t":"亚多尼·比色说：「从前有七十个王，手脚的大拇指都被我砍断，在我桌子底下拾取零碎食物。现在神按着我所行的报应我了。」于是他们将亚多尼·比色带到耶路撒冷，他就死在那里。","notes":[]},{"n":8,"t":"犹大人攻打耶路撒冷，将城攻取，用刀杀了城内的人，并且放火烧城。","notes":[],"heads":["犹大支派攻取耶路撒冷和希伯仑"]},{"n":9,"t":"后来犹大人下去，与住山地、南地，和高原的迦南人争战。","notes":[]},{"n":10,"t":"犹大人去攻击住希伯仑的迦南人，杀了示筛、亚希幔、挞买。希伯仑从前名叫基列·亚巴。","notes":[]},{"n":11,"t":"他们从那里去攻击底壁的居民；底壁从前名叫基列·西弗。","notes":[],"heads":["俄陀聂攻取底壁城"]},{"n":12,"t":"迦勒说：「谁能攻打基列·西弗，将城夺取，我就把我女儿押撒给他为妻。」","notes":[]},{"n":13,"t":"迦勒兄弟基纳斯的儿子俄陀聂夺取了那城，迦勒就把女儿押撒给他为妻。","notes":[]},{"n":14,"t":"押撒过门的时候，劝丈夫向她父亲求一块田。押撒一下驴，迦勒问她说：「你要什么？」","notes":[]},{"n":15,"t":"她说：「求你赐福给我，你既将我安置在南地，求你也给我水泉。」迦勒就把上泉下泉赐给她。","notes":[]},{"n":16,"t":"摩西的内兄是基尼人，他的子孙与犹大人一同离了棕树城，往亚拉得以南的犹大旷野去，就住在民中。","notes":["或译：岳父"],"heads":["犹大和便雅悯支派的胜利"]},{"n":17,"t":"犹大和他哥哥西缅同去，击杀了住洗法的迦南人，将城尽行毁灭，那城的名便叫何珥玛。","notes":[]},{"n":18,"t":"犹大又取了迦萨和迦萨的四境，亚实基伦和亚实基伦的四境，以革伦和以革伦的四境。","notes":[]},{"n":19,"t":"耶和华与犹大同在，犹大就赶出山地的居民，只是不能赶出平原的居民，因为他们有铁车。","notes":[]},{"n":20,"t":"以色列人照摩西所说的，将希伯仑给了迦勒；迦勒就从那里赶出亚衲族的三个族长。","notes":[]},{"n":21,"t":"便雅悯人没有赶出住耶路撒冷的耶布斯人。耶布斯人仍在耶路撒冷与便雅悯人同住，直到今日。","notes":[]},{"n":22,"t":"约瑟家也上去攻打伯特利；耶和华与他们同在。","notes":[],"heads":["以法莲和玛拿西支派攻取伯特利"]},{"n":23,"t":"约瑟家打发人去窥探伯特利（那城起先名叫路斯）。","notes":[]},{"n":24,"t":"窥探的人看见一个人从城里出来，就对他说：「求你将进城的路指示我们，我们必恩待你。」","notes":[]},{"n":25,"t":"那人将进城的路指示他们，他们就用刀击杀了城中的居民，但将那人和他全家放去。","notes":[]},{"n":26,"t":"那人往赫人之地去，筑了一座城，起名叫路斯。那城到如今还叫这名。","notes":[]},{"n":27,"t":"玛拿西没有赶出伯·善和属伯·善乡村的居民，他纳和属他纳乡村的居民，多珥和属多珥乡村的居民，以伯莲和属以伯莲乡村的居民，米吉多和属米吉多乡村的居民；迦南人却执意住在那些地方。","notes":[],"heads":["以色列人没有赶出去的民"]},{"n":28,"t":"及至以色列强盛了，就使迦南人做苦工，没有把他们全然赶出。","notes":[]},{"n":29,"t":"以法莲没有赶出住基色的迦南人。于是迦南人仍住在基色，在以法莲中间。","notes":[]},{"n":30,"t":"西布伦没有赶出基伦的居民和拿哈拉的居民。于是迦南人仍住在西布伦中间，成了服苦的人。","notes":[]},{"n":31,"t":"亚设没有赶出亚柯和西顿的居民，亚黑拉和亚革悉的居民，黑巴、亚弗革与利合的居民。","notes":[]},{"n":32,"t":"于是，亚设因为没有赶出那地的迦南人，就住在他们中间。","notes":[]},{"n":33,"t":"拿弗他利没有赶出伯·示麦和伯·亚纳的居民，于是拿弗他利就住在那地的迦南人中间；然而伯·示麦和伯·亚纳的居民成了服苦的人。","notes":[]},{"n":34,"t":"亚摩利人强逼但人住在山地，不容他们下到平原；","notes":[]},{"n":35,"t":"亚摩利人却执意住在希烈山和亚雅仑并沙宾。然而约瑟家胜了他们，使他们成了服苦的人。","notes":[]},{"n":36,"t":"亚摩利人的境界，是从亚克拉滨坡，从西拉而上。","notes":[]}]},"2":{"heading":"耶和华的使者在波金","verses":[{"n":1,"t":"耶和华的使者从吉甲上到波金，对以色列人说：「我使你们从埃及上来，领你们到我向你们列祖起誓应许之地。我又说：『我永不废弃与你们所立的约。","notes":[]},{"n":2,"t":"你们也不可与这地的居民立约，要拆毁他们的祭坛。你们竟没有听从我的话！为何这样行呢？』","notes":[]},{"n":3,"t":"因此我又说：『我必不将他们从你们面前赶出；他们必作你们肋下的荆棘。他们的神必作你们的网罗。』」","notes":[]},{"n":4,"t":"耶和华的使者向以色列众人说这话的时候，百姓就放声而哭；","notes":[]},{"n":5,"t":"于是给那地方起名叫波金。众人在那里向耶和华献祭。","notes":["就是哭的意思"]},{"n":6,"t":"从前约书亚打发以色列百姓去的时候，他们各归自己的地业，占据地土。","notes":[],"heads":["约书亚去世"]},{"n":7,"t":"约书亚在世和约书亚死后，那些见耶和华为以色列人所行大事的长老还在的时候，百姓都事奉耶和华。","notes":[]},{"n":8,"t":"耶和华的仆人、嫩的儿子约书亚，正一百一十岁就死了。","notes":[]},{"n":9,"t":"以色列人将他葬在他地业的境内，就是在以法莲山地的亭拿·希烈，在迦实山的北边。","notes":[]},{"n":10,"t":"那世代的人也都归了自己的列祖。后来有别的世代兴起，不知道耶和华，也不知道耶和华为以色列人所行的事。","notes":[]},{"n":11,"t":"以色列人行耶和华眼中看为恶的事，去事奉诸巴力，","notes":[],"heads":["以色列离弃耶和华"]},{"n":12,"t":"离弃了领他们出埃及地的耶和华—他们列祖的神，去叩拜别神，就是四围列国的神，惹耶和华发怒；","notes":[]},{"n":13,"t":"并离弃耶和华，去事奉巴力和亚斯她录。","notes":[]},{"n":14,"t":"耶和华的怒气向以色列人发作，就把他们交在抢夺他们的人手中，又将他们付与四围仇敌的手中，甚至他们在仇敌面前再不能站立得住。","notes":[]},{"n":15,"t":"他们无论往何处去，耶和华都以灾祸攻击他们，正如耶和华所说的话，又如耶和华向他们所起的誓；他们便极其困苦。","notes":[]},{"n":16,"t":"耶和华兴起士师，士师就拯救他们脱离抢夺他们人的手。","notes":[]},{"n":17,"t":"他们却不听从士师，竟随从叩拜别神，行了邪淫，速速地偏离他们列祖所行的道，不如他们列祖顺从耶和华的命令。","notes":[]},{"n":18,"t":"耶和华为他们兴起士师，就与那士师同在。士师在世的一切日子，耶和华拯救他们脱离仇敌的手。他们因受欺压扰害，就哀声叹气，所以耶和华后悔了。","notes":[]},{"n":19,"t":"及至士师死后，他们就转去行恶，比他们列祖更甚，去事奉叩拜别神，总不断绝顽梗的恶行。","notes":[]},{"n":20,"t":"于是耶和华的怒气向以色列人发作。他说：「因这民违背我吩咐他们列祖所守的约，不听从我的话，","notes":[]},{"n":21,"t":"所以约书亚死的时候所剩下的各族，我必不再从他们面前赶出，","notes":[]},{"n":22,"t":"为要借此试验以色列人，看他们肯照他们列祖谨守遵行我的道不肯。」","notes":[]},{"n":23,"t":"这样耶和华留下各族，不将他们速速赶出，也没有交付约书亚的手。","notes":[]}]},"3":{"heading":"留下来的民族","verses":[{"n":1,"t":"耶和华留下这几族，为要试验那不曾知道与迦南争战之事的以色列人，","notes":[]},{"n":2,"t":"好叫以色列的后代又知道又学习未曾晓得的战事。","notes":[]},{"n":3,"t":"所留下的就是非利士的五个首领和一切迦南人、西顿人，并住黎巴嫩山的希未人，从巴力·黑们山直到哈马口。","notes":[]},{"n":4,"t":"留下这几族，为要试验以色列人，知道他们肯听从耶和华借摩西吩咐他们列祖的诫命不肯。","notes":[]},{"n":5,"t":"以色列人竟住在迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人中间，","notes":[]},{"n":6,"t":"娶他们的女儿为妻，将自己的女儿嫁给他们的儿子，并事奉他们的神。","notes":[]},{"n":7,"t":"以色列人行耶和华眼中看为恶的事，忘记耶和华—他们的神，去事奉诸巴力和亚舍拉，","notes":[],"heads":["俄陀聂"]},{"n":8,"t":"所以耶和华的怒气向以色列人发作，就把他们交在美索不达米亚王古珊·利萨田的手中。以色列人服事古珊·利萨田八年。","notes":[]},{"n":9,"t":"以色列人呼求耶和华的时候，耶和华就为他们兴起一位拯救者救他们，就是迦勒兄弟基纳斯的儿子俄陀聂。","notes":[]},{"n":10,"t":"耶和华的灵降在他身上，他就作了以色列的士师，出去争战。耶和华将美索不达米亚王古珊·利萨田交在他手中，他便胜了古珊·利萨田。","notes":[]},{"n":11,"t":"于是国中太平四十年。基纳斯的儿子俄陀聂死了。","notes":[]},{"n":12,"t":"以色列人又行耶和华眼中看为恶的事，耶和华就使摩押王伊矶伦强盛，攻击以色列人。","notes":[],"heads":["以笏"]},{"n":13,"t":"伊矶伦招聚亚扪人和亚玛力人，去攻打以色列人，占据棕树城。","notes":[]},{"n":14,"t":"于是以色列人服事摩押王伊矶伦十八年。","notes":[]},{"n":15,"t":"以色列人呼求耶和华的时候，耶和华就为他们兴起一位拯救者，就是便雅悯人基拉的儿子以笏；他是左手便利的。以色列人托他送礼物给摩押王伊矶伦。","notes":[]},{"n":16,"t":"以笏打了一把两刃的剑，长一肘，带在右腿上衣服里面。","notes":[]},{"n":17,"t":"他将礼物献给摩押王伊矶伦（原来伊矶伦极其肥胖）；","notes":[]},{"n":18,"t":"以笏献完礼物，便将抬礼物的人打发走了，","notes":[]},{"n":19,"t":"自己却从靠近吉甲凿石之地回来，说：「王啊，我有一件机密事奏告你。」王说：「回避吧！」于是左右侍立的人都退去了。","notes":[]},{"n":20,"t":"以笏来到王面前；王独自一人坐在凉楼上。以笏说：「我奉神的命报告你一件事。」王就从座位上站起来。","notes":[]},{"n":21,"t":"以笏便伸左手，从右腿上拔出剑来，刺入王的肚腹，","notes":[]},{"n":22,"t":"连剑把都刺进去了。剑被肥肉夹住，他没有从王的肚腹拔出来，且穿通了后身。","notes":[]},{"n":23,"t":"以笏就出到游廊，将楼门尽都关锁。","notes":[]},{"n":24,"t":"以笏出来之后，王的仆人到了，看见楼门关锁，就说：「他必是在楼上大解。」","notes":[]},{"n":25,"t":"他们等烦了，见仍不开楼门，就拿钥匙开了，不料，他们的主人已死，倒在地上。","notes":[]},{"n":26,"t":"他们耽延的时候，以笏就逃跑了，经过凿石之地，逃到西伊拉；","notes":[]},{"n":27,"t":"到了，就在以法莲山地吹角。以色列人随着他下了山地，他在前头引路，","notes":[]},{"n":28,"t":"对他们说：「你们随我来，因为耶和华已经把你们的仇敌摩押人交在你们手中。」于是他们跟着他下去，把守约旦河的渡口，不容摩押一人过去。","notes":[]},{"n":29,"t":"那时击杀了摩押人约有一万，都是强壮的勇士，没有一人逃脱。","notes":[]},{"n":30,"t":"这样，摩押就被以色列人制伏了。国中太平八十年。","notes":[]},{"n":31,"t":"以笏之后，有亚拿的儿子珊迦，他用赶牛的棍子打死六百非利士人。他也救了以色列人。","notes":[],"heads":["珊迦"]}]},"4":{"heading":"底波拉和巴拉","verses":[{"n":1,"t":"以笏死后，以色列人又行耶和华眼中看为恶的事，","notes":[]},{"n":2,"t":"耶和华就把他们付与在夏琐作王的迦南王耶宾手中；他的将军是西西拉，住在外邦人的夏罗设。","notes":[]},{"n":3,"t":"耶宾王有铁车九百辆。他大大欺压以色列人二十年，以色列人就呼求耶和华。","notes":[]},{"n":4,"t":"有一位女先知名叫底波拉，是拉比多的妻，当时作以色列的士师。","notes":[]},{"n":5,"t":"她住在以法莲山地拉玛和伯特利中间，在底波拉的棕树下。以色列人都上她那里去听判断。","notes":[]},{"n":6,"t":"她打发人从拿弗他利的基低斯将亚比挪庵的儿子巴拉召了来，对他说：「耶和华—以色列的神吩咐你说：『你率领一万拿弗他利和西布伦人上他泊山去。","notes":[]},{"n":7,"t":"我必使耶宾的将军西西拉率领他的车辆和全军往基顺河，到你那里去；我必将他交在你手中。』」","notes":[]},{"n":8,"t":"巴拉说：「你若同我去，我就去；你若不同我去，我就不去。」","notes":[]},{"n":9,"t":"底波拉说：「我必与你同去，只是你在所行的路上得不着荣耀，因为耶和华要将西西拉交在一个妇人手里。」于是底波拉起来，与巴拉一同往基低斯去了。","notes":[]},{"n":10,"t":"巴拉就招聚西布伦人和拿弗他利人到基低斯，跟他上去的有一万人。底波拉也同他上去。","notes":[]},{"n":11,"t":"摩西岳父何巴的后裔，基尼人希百曾离开基尼族，到靠近基低斯、撒拿音的橡树旁支搭帐棚。","notes":["或译：内兄"]},{"n":12,"t":"有人告诉西西拉说：「亚比挪庵的儿子巴拉已经上他泊山了。」","notes":[]},{"n":13,"t":"西西拉就聚集所有的铁车九百辆和跟随他的全军，从外邦人的夏罗设出来，到了基顺河。","notes":[]},{"n":14,"t":"底波拉对巴拉说：「你起来，今日就是耶和华将西西拉交在你手的日子。耶和华岂不在你前头行吗？」于是巴拉下了他泊山，跟随他有一万人。","notes":[]},{"n":15,"t":"耶和华使西西拉和他一切车辆全军溃乱，在巴拉面前被刀杀败；西西拉下车步行逃跑。","notes":[]},{"n":16,"t":"巴拉追赶车辆、军队，直到外邦人的夏罗设。西西拉的全军都倒在刀下，没有留下一人。","notes":[]},{"n":17,"t":"只有西西拉步行逃跑，到了基尼人希百之妻雅亿的帐棚，因为夏琐王耶宾与基尼人希百家和好。","notes":[]},{"n":18,"t":"雅亿出来迎接西西拉，对他说：「请我主进来，不要惧怕」；西西拉就进了她的帐棚。雅亿用被将他遮盖。","notes":[]},{"n":19,"t":"西西拉对雅亿说：「我渴了，求你给我一点水喝。」雅亿就打开皮袋，给他奶子喝，仍旧把他遮盖。","notes":[]},{"n":20,"t":"西西拉又对雅亿说：「请你站在帐棚门口，若有人来问你说：『有人在这里没有？』你就说：『没有。』」","notes":[]},{"n":21,"t":"西西拉疲乏沉睡。希百的妻雅亿取了帐棚的橛子，手里拿着锤子，轻悄悄地到他旁边，将橛子从他鬓边钉进去，钉入地里。西西拉就死了。","notes":[]},{"n":22,"t":"巴拉追赶西西拉的时候，雅亿出来迎接他说：「来吧，我将你所寻找的人给你看。」他就进入帐棚，看见西西拉已经死了，倒在地上，橛子还在他鬓中。","notes":[]},{"n":23,"t":"这样，神使迦南王耶宾被以色列人制伏了。","notes":[]},{"n":24,"t":"从此以色列人的手越发有力，胜了迦南王耶宾，直到将他灭绝了。","notes":[]}]},"5":{"heading":"底波拉和巴拉的歌","verses":[{"n":1,"t":"那时，底波拉和亚比挪庵的儿子巴拉作歌，说：","notes":[]},{"n":2,"t":"因为以色列中有军长率领，百姓也甘心牺牲自己，你们应当颂赞耶和华！","notes":[]},{"n":3,"t":"君王啊，要听！王子啊，要侧耳而听！我要向耶和华歌唱；我要歌颂耶和华—以色列的神。","notes":[]},{"n":4,"t":"耶和华啊，你从西珥出来，由以东地行走。那时地震天漏，云也落雨。","notes":[]},{"n":5,"t":"山见耶和华的面就震动，西奈山见耶和华—以色列神的面也是如此。","notes":[]},{"n":6,"t":"在亚拿之子珊迦的时候，又在雅亿的日子，大道无人行走，都是绕道而行。","notes":[]},{"n":7,"t":"以色列中的官长停职，直到我底波拉兴起，等我兴起作以色列的母。","notes":[]},{"n":8,"t":"以色列人选择新神，争战的事就临到城门。那时，以色列四万人中岂能见盾牌枪矛呢？","notes":[]},{"n":9,"t":"我心倾向以色列的首领，他们在民中甘心牺牲自己。你们应当颂赞耶和华！","notes":[]},{"n":10,"t":"骑白驴的、坐绣花毯子的、行路的，你们都当传扬！","notes":[]},{"n":11,"t":"在远离弓箭响声打水之处，人必述说耶和华公义的作为，就是他治理以色列公义的作为。那时耶和华的民下到城门。","notes":[]},{"n":12,"t":"底波拉啊，兴起！兴起！你当兴起，兴起，唱歌。亚比挪庵的儿子巴拉啊，你当奋兴，掳掠你的敌人。","notes":[]},{"n":13,"t":"那时有余剩的贵胄和百姓一同下来；耶和华降临，为我攻击勇士。","notes":[]},{"n":14,"t":"有根本在亚玛力人的地，从以法莲下来的；便雅悯在民中跟随你。有掌权的从玛吉下来；有持杖检点民数的从西布伦下来；","notes":[]},{"n":15,"t":"以萨迦的首领与底波拉同来；以萨迦怎样，巴拉也怎样。众人都跟随巴拉冲下平原；在吕便的溪水旁有心中定大志的。","notes":[]},{"n":16,"t":"你为何坐在羊圈内听群中吹笛的声音呢？在吕便的溪水旁有心中设大谋的。","notes":[]},{"n":17,"t":"基列人安居在约旦河外。但人为何等在船上？亚设人在海口静坐，在港口安居。","notes":[]},{"n":18,"t":"西布伦人是拚命敢死的；拿弗他利人在田野的高处也是如此。","notes":[]},{"n":19,"t":"君王都来争战。那时迦南诸王在米吉多水旁的他纳争战，却未得掳掠银钱。","notes":[]},{"n":20,"t":"星宿从天上争战，从其轨道攻击西西拉。","notes":[]},{"n":21,"t":"基顺古河把敌人冲没；我的灵啊，应当努力前行。","notes":[]},{"n":22,"t":"那时壮马驰驱，踢跳，奔腾。","notes":[]},{"n":23,"t":"耶和华的使者说：应当咒诅米罗斯，大大咒诅其中的居民；因为他们不来帮助耶和华，不来帮助耶和华攻击勇士。","notes":[]},{"n":24,"t":"愿基尼人希百的妻雅亿比众妇人多得福气，比住帐棚的妇人更蒙福祉。","notes":[]},{"n":25,"t":"西西拉求水，雅亿给他奶子，用宝贵的盘子给他奶油。","notes":[]},{"n":26,"t":"雅亿左手拿着帐棚的橛子，右手拿着匠人的锤子，击打西西拉，打伤他的头，把他的鬓角打破穿通。","notes":[]},{"n":27,"t":"西西拉在她脚前曲身仆倒，在她脚前曲身倒卧；在那里曲身，就在那里死亡。","notes":[]},{"n":28,"t":"西西拉的母亲从窗户里往外观看，从窗棂中呼叫说：他的战车为何耽延不来呢？他的车轮为何行得慢呢？","notes":[]},{"n":29,"t":"聪明的宫女安慰她，她也自言自语地说：","notes":["原文是回答她"]},{"n":30,"t":"他们莫非得财而分？每人得了一两个女子？西西拉得了彩衣为掳物，得绣花的彩衣为掠物。这彩衣两面绣花，乃是披在被掳之人颈项上的。","notes":[]},{"n":31,"t":"耶和华啊，愿你的仇敌都这样灭亡！愿爱你的人如日头出现，光辉烈烈！这样，国中太平四十年。","notes":[]}]},"6":{"heading":"基甸","verses":[{"n":1,"t":"以色列人又行耶和华眼中看为恶的事，耶和华就把他们交在米甸人手里七年。","notes":[]},{"n":2,"t":"米甸人压制以色列人；以色列人因为米甸人，就在山中挖穴、挖洞、建造营寨。","notes":[]},{"n":3,"t":"以色列人每逢撒种之后，米甸人、亚玛力人，和东方人都上来攻打他们，","notes":[]},{"n":4,"t":"对着他们安营，毁坏土产，直到迦萨，没有给以色列人留下食物，牛、羊、驴也没有留下；","notes":[]},{"n":5,"t":"因为那些人带着牲畜帐棚来，像蝗虫那样多，人和骆驼无数，都进入国内，毁坏全地。","notes":[]},{"n":6,"t":"以色列人因米甸人的缘故，极其穷乏，就呼求耶和华。","notes":[]},{"n":7,"t":"以色列人因米甸人的缘故，呼求耶和华，","notes":[]},{"n":8,"t":"耶和华就差遣先知到以色列人那里，对他们说：「耶和华—以色列的神如此说：『我曾领你们从埃及上来，出了为奴之家，","notes":[]},{"n":9,"t":"救你们脱离埃及人的手，并脱离一切欺压你们之人的手，把他们从你们面前赶出，将他们的地赐给你们』；","notes":[]},{"n":10,"t":"又对你们说：『我是耶和华—你们的神。你们住在亚摩利人的地，不可敬畏他们的神。你们竟不听从我的话。』」","notes":[]},{"n":11,"t":"耶和华的使者到了俄弗拉，坐在亚比以谢族人约阿施的橡树下。约阿施的儿子基甸正在酒榨那里打麦子，为要防备米甸人。","notes":[]},{"n":12,"t":"耶和华的使者向基甸显现，对他说：「大能的勇士啊，耶和华与你同在！」","notes":[]},{"n":13,"t":"基甸说：「主啊，耶和华若与我们同在，我们何至遭遇这一切事呢？我们的列祖不是向我们说『耶和华领我们从埃及上来』吗？他那样奇妙的作为在哪里呢？现在他却丢弃我们，将我们交在米甸人手里。」","notes":[]},{"n":14,"t":"耶和华观看基甸，说：「你靠着你这能力去从米甸人手里拯救以色列人，不是我差遣你去的吗？」","notes":[]},{"n":15,"t":"基甸说：「主啊，我有何能拯救以色列人呢？我家在玛拿西支派中是至贫穷的。我在我父家是至微小的。」","notes":[]},{"n":16,"t":"耶和华对他说：「我与你同在，你就必击打米甸人，如击打一人一样。」","notes":[]},{"n":17,"t":"基甸说：「我若在你眼前蒙恩，求你给我一个证据，使我知道与我说话的就是主。","notes":[]},{"n":18,"t":"求你不要离开这里，等我归回将礼物带来供在你面前。」主说：「我必等你回来。」","notes":[]},{"n":19,"t":"基甸去预备了一只山羊羔，用一伊法细面做了无酵饼，将肉放在筐内，把汤盛在壶中，带到橡树下，献在使者面前。","notes":[]},{"n":20,"t":"神的使者吩咐基甸说：「将肉和无酵饼放在这磐石上，把汤倒出来。」他就这样行了。","notes":[]},{"n":21,"t":"耶和华的使者伸出手内的杖，杖头挨了肉和无酵饼，就有火从磐石中出来，烧尽了肉和无酵饼。耶和华的使者也就不见了。","notes":[]},{"n":22,"t":"基甸见他是耶和华的使者，就说：「哀哉！主耶和华啊，我不好了，因为我觌面看见耶和华的使者。」","notes":[]},{"n":23,"t":"耶和华对他说：「你放心，不要惧怕，你必不至死。」","notes":[]},{"n":24,"t":"于是基甸在那里为耶和华筑了一座坛，起名叫「耶和华沙龙」。（这坛在亚比以谢族的俄弗拉直到如今。）","notes":["就是耶和华赐平安的意思"]},{"n":25,"t":"当那夜，耶和华吩咐基甸说：「你取你父亲的牛来，就是那七岁的第二只牛，并拆毁你父亲为巴力所筑的坛，砍下坛旁的木偶，","notes":["或译：和"]},{"n":26,"t":"在这磐石上整整齐齐地为耶和华—你的神筑一座坛，将第二只牛献为燔祭，用你所砍下的木偶作柴。」","notes":["原文是保障"]},{"n":27,"t":"基甸就从他仆人中挑了十个人，照着耶和华吩咐他的行了。他因怕父家和本城的人，不敢在白昼行这事，就在夜间行了。","notes":[]},{"n":28,"t":"城里的人清早起来，见巴力的坛拆毁，坛旁的木偶砍下，第二只牛献在新筑的坛上，","notes":[]},{"n":29,"t":"就彼此说：「这事是谁做的呢？」他们访查之后，就说：「这是约阿施的儿子基甸做的。」","notes":[]},{"n":30,"t":"城里的人对约阿施说：「将你儿子交出来，好治死他；因为他拆毁了巴力的坛，砍下坛旁的木偶。」","notes":[]},{"n":31,"t":"约阿施回答站着攻击他的众人说：「你们是为巴力争论吗？你们要救他吗？谁为他争论，趁早将谁治死！巴力若果是神，有人拆毁他的坛，让他为自己争论吧！」","notes":[]},{"n":32,"t":"所以当日人称基甸为耶路·巴力，意思说：「他拆毁巴力的坛，让巴力与他争论。」","notes":[]},{"n":33,"t":"那时，米甸人、亚玛力人，和东方人都聚集过河，在耶斯列平原安营。","notes":[]},{"n":34,"t":"耶和华的灵降在基甸身上，他就吹角；亚比以谢族都聚集跟随他。","notes":[]},{"n":35,"t":"他打发人走遍玛拿西地，玛拿西人也聚集跟随他；又打发人去见亚设人、西布伦人、拿弗他利人，他们也都出来与他们会合。","notes":[]},{"n":36,"t":"基甸对神说：「你若果照着所说的话，借我手拯救以色列人，","notes":[]},{"n":37,"t":"我就把一团羊毛放在禾场上：若单是羊毛上有露水，别的地方都是干的，我就知道你必照着所说的话，借我手拯救以色列人。」","notes":[]},{"n":38,"t":"次日早晨基甸起来，见果然是这样；将羊毛挤一挤，从羊毛中拧出满盆的露水来。","notes":[]},{"n":39,"t":"基甸又对神说：「求你不要向我发怒，我再说这一次：让我将羊毛再试一次。但愿羊毛是干的，别的地方都有露水。」","notes":[]},{"n":40,"t":"这夜神也如此行：独羊毛上是干的，别的地方都有露水。","notes":[]}]},"7":{"heading":"基甸击败米甸人","verses":[{"n":1,"t":"耶路·巴力就是基甸，他和一切跟随的人早晨起来，在哈律泉旁安营。米甸营在他们北边的平原，靠近摩利冈。","notes":[]},{"n":2,"t":"耶和华对基甸说：「跟随你的人过多，我不能将米甸人交在他们手中，免得以色列人向我夸大，说：『是我们自己的手救了我们。』","notes":[]},{"n":3,"t":"现在你要向这些人宣告说：『凡惧怕胆怯的，可以离开基列山回去。』」于是有二万二千人回去，只剩下一万。","notes":[]},{"n":4,"t":"耶和华对基甸说：「人还是过多；你要带他们下到水旁，我好在那里为你试试他们。我指点谁说：『这人可以同你去』，他就可以同你去；我指点谁说：『这人不可同你去』，他就不可同你去。」","notes":[]},{"n":5,"t":"基甸就带他们下到水旁。耶和华对基甸说：「凡用舌头舔水，像狗舔的，要使他单站在一处；凡跪下喝水的，也要使他单站在一处。」","notes":[]},{"n":6,"t":"于是用手捧着舔水的有三百人，其余的都跪下喝水。","notes":[]},{"n":7,"t":"耶和华对基甸说：「我要用这舔水的三百人拯救你们，将米甸人交在你手中；其余的人都可以各归各处去。」","notes":[]},{"n":8,"t":"这三百人就带着食物和角；其余的以色列人，基甸都打发他们各归各的帐棚，只留下这三百人。米甸营在他下边的平原里。","notes":[]},{"n":9,"t":"当那夜，耶和华吩咐基甸说：「起来，下到米甸营里去，因我已将他们交在你手中。","notes":[]},{"n":10,"t":"倘若你怕下去，就带你的仆人普拉下到那营里去。","notes":[]},{"n":11,"t":"你必听见他们所说的，然后你就有胆量下去攻营。」于是基甸带着仆人普拉下到营旁。","notes":[]},{"n":12,"t":"米甸人、亚玛力人，和一切东方人都布散在平原，如同蝗虫那样多。他们的骆驼无数，多如海边的沙。","notes":[]},{"n":13,"t":"基甸到了，就听见一人将梦告诉同伴说：「我做了一梦，梦见一个大麦饼滚入米甸营中，到了帐幕，将帐幕撞倒，帐幕就翻转倾覆了。」","notes":[]},{"n":14,"t":"那同伴说：「这不是别的，乃是以色列人约阿施的儿子基甸的刀；神已将米甸和全军都交在他的手中。」","notes":[]},{"n":15,"t":"基甸听见这梦和梦的讲解，就敬拜神，回到以色列营中，说：「起来吧！耶和华已将米甸的军队交在你们手中了。」","notes":[]},{"n":16,"t":"于是基甸将三百人分作三队，把角和空瓶交在各人手里（瓶内都藏着火把），","notes":[]},{"n":17,"t":"吩咐他们说：「你们要看我行事：我到了营的旁边怎样行，你们也要怎样行。","notes":[]},{"n":18,"t":"我和一切跟随我的人吹角的时候，你们也要在营的四围吹角，喊叫说：『耶和华和基甸的刀！』」","notes":[]},{"n":19,"t":"基甸和跟随他的一百人，在三更之初才换更的时候，来到营旁，就吹角，打破手中的瓶。","notes":[]},{"n":20,"t":"三队的人就都吹角，打破瓶子，左手拿着火把，右手拿着角，喊叫说：「耶和华和基甸的刀！」","notes":[]},{"n":21,"t":"他们在营的四围各站各的地方；全营的人都乱窜。三百人呐喊，使他们逃跑。","notes":[]},{"n":22,"t":"三百人就吹角，耶和华使全营的人用刀互相击杀，逃到西利拉的伯·哈示他，直逃到靠近他巴的亚伯·米何拉。","notes":[]},{"n":23,"t":"以色列人就从拿弗他利、亚设，和玛拿西全地聚集来追赶米甸人。","notes":[]},{"n":24,"t":"基甸打发人走遍以法莲山地，说：「你们下来攻击米甸人，争先把守约旦河的渡口，直到伯·巴拉。」于是以法莲的众人聚集，把守约旦河的渡口，直到伯·巴拉，","notes":[]},{"n":25,"t":"捉住了米甸人的两个首领：一名俄立，一名西伊伯；将俄立杀在俄立磐石上，将西伊伯杀在西伊伯酒榨那里；又追赶米甸人，将俄立和西伊伯的首级带过约旦河，到基甸那里。","notes":[]}]},"8":{"heading":"击败米甸人","verses":[{"n":1,"t":"以法莲人对基甸说：「你去与米甸人争战，没有招我们同去，为什么这样待我们呢？」他们就与基甸大大地争吵。","notes":[]},{"n":2,"t":"基甸对他们说：「我所行的岂能比你们所行的呢？以法莲拾取剩下的葡萄不强过亚比以谢所摘的葡萄吗？","notes":[]},{"n":3,"t":"神已将米甸人的两个首领俄立和西伊伯交在你们手中；我所行的岂能比你们所行的呢？」基甸说了这话，以法莲人的怒气就消了。","notes":[]},{"n":4,"t":"基甸和跟随他的三百人到约旦河过渡，虽然疲乏，还是追赶。","notes":[]},{"n":5,"t":"基甸对疏割人说：「求你们拿饼来给跟随我的人吃，因为他们疲乏了；我们追赶米甸人的两个王西巴和撒慕拿。」","notes":[]},{"n":6,"t":"疏割人的首领回答说：「西巴和撒慕拿已经在你手里，你使我们将饼给你的军兵吗？」","notes":[]},{"n":7,"t":"基甸说：「耶和华将西巴和撒慕拿交在我手之后，我就用野地的荆条和枳棘打伤你们。」","notes":[]},{"n":8,"t":"基甸从那里上到毗努伊勒，对那里的人也是这样说；毗努伊勒人也与疏割人回答他的话一样。","notes":[]},{"n":9,"t":"他向毗努伊勒人说：「我平平安安回来的时候，我必拆毁这楼。」","notes":[]},{"n":10,"t":"那时西巴和撒慕拿，并跟随他们的军队都在加各，约有一万五千人，就是东方人全军所剩下的；已经被杀约有十二万拿刀的。","notes":[]},{"n":11,"t":"基甸就由挪巴和约比哈东边，从住帐棚人的路上去，杀败了米甸人的军兵，因为他们坦然无惧。","notes":[]},{"n":12,"t":"西巴和撒慕拿逃跑；基甸追赶他们，捉住米甸的二王西巴和撒慕拿，惊散全军。","notes":[]},{"n":13,"t":"约阿施的儿子基甸由希列斯坡从阵上回来，","notes":[]},{"n":14,"t":"捉住疏割的一个少年人，问他：「疏割的首领长老是谁？」他就将首领长老七十七个人的名字写出来。","notes":[]},{"n":15,"t":"基甸到了疏割，对那里的人说：「你们从前讥诮我说：『西巴和撒慕拿已经在你手里，你使我们将饼给跟随你的疲乏人吗？』现在西巴和撒慕拿在这里。」","notes":[]},{"n":16,"t":"于是捉住那城内的长老，用野地的荆条和枳棘责打疏割人；","notes":["原文是指教"]},{"n":17,"t":"又拆了毗努伊勒的楼，杀了那城里的人。","notes":[]},{"n":18,"t":"基甸问西巴和撒慕拿说：「你们在他泊山所杀的人是什么样式？」回答说：「他们好像你，各人都有王子的样式。」","notes":[]},{"n":19,"t":"基甸说：「他们是我同母的弟兄，我指着永生的耶和华起誓，你们从前若存留他们的性命，我如今就不杀你们了。」","notes":[]},{"n":20,"t":"于是对他的长子益帖说：「你起来杀他们。」但益帖因为是童子，害怕，不敢拔刀。","notes":[]},{"n":21,"t":"西巴和撒慕拿说：「你自己起来杀我们吧！因为人如何，力量也是如何。」基甸就起来，杀了西巴和撒慕拿，夺获他们骆驼项上戴的月牙圈。","notes":[]},{"n":22,"t":"以色列人对基甸说：「你既救我们脱离米甸人的手，愿你和你的儿孙管理我们。」","notes":[]},{"n":23,"t":"基甸说：「我不管理你们，我的儿子也不管理你们，惟有耶和华管理你们。」","notes":[]},{"n":24,"t":"基甸又对他们说：「我有一件事求你们：请你们各人将所夺的耳环给我。」（原来仇敌是以实玛利人，都是戴金耳环的。）","notes":[]},{"n":25,"t":"他们说：「我们情愿给你」，就铺开一件外衣，各人将所夺的耳环丢在其上。","notes":[]},{"n":26,"t":"基甸所要出来的金耳环重一千七百舍客勒金子。此外还有米甸王所戴的月环、耳坠，和所穿的紫色衣服，并骆驼项上的金链子。","notes":[]},{"n":27,"t":"基甸以此制造了一个以弗得，设立在本城俄弗拉。后来以色列人拜那以弗得行了邪淫；这就作了基甸和他全家的网罗。","notes":[]},{"n":28,"t":"这样，米甸人被以色列人制伏了，不敢再抬头。基甸还在的日子，国中太平四十年。","notes":[]},{"n":29,"t":"约阿施的儿子耶路·巴力回去，住在自己家里。","notes":[],"heads":["基甸去世"]},{"n":30,"t":"基甸有七十个亲生的儿子，因为他有许多的妻。","notes":[]},{"n":31,"t":"他的妾住在示剑，也给他生了一个儿子。基甸与他起名叫亚比米勒。","notes":[]},{"n":32,"t":"约阿施的儿子基甸，年纪老迈而死，葬在亚比以谢族的俄弗拉，在他父亲约阿施的坟墓里。","notes":[]},{"n":33,"t":"基甸死后，以色列人又去随从诸巴力行邪淫，以巴力·比利土为他们的神。","notes":[]},{"n":34,"t":"以色列人不记念耶和华—他们的神，就是拯救他们脱离四围仇敌之手的，","notes":[]},{"n":35,"t":"也不照着耶路·巴力，就是基甸向他们所施的恩惠厚待他的家。","notes":[]}]},"9":{"heading":"亚比米勒","verses":[{"n":1,"t":"耶路·巴力的儿子亚比米勒到了示剑见他的众母舅，对他们和他外祖全家的人说：","notes":[]},{"n":2,"t":"「请你们问示剑的众人说，是耶路·巴力的众子七十人都管理你们好呢？还是一人管理你们好呢？你们又要记念我是你们的骨肉。」","notes":[]},{"n":3,"t":"他的众母舅便将这一切话为他说给示剑人听，示剑人的心就归向亚比米勒。他们说：「他原是我们的弟兄」；","notes":[]},{"n":4,"t":"就从巴力·比利土的庙中取了七十舍客勒银子给亚比米勒；亚比米勒用以雇了些匪徒跟随他。","notes":[]},{"n":5,"t":"他往俄弗拉到他父亲的家，将他弟兄、耶路·巴力的众子七十人都杀在一块磐石上；只剩下耶路·巴力的小儿子约坦，因为他躲藏了。","notes":[]},{"n":6,"t":"示剑人和米罗人都一同聚集，往示剑橡树旁的柱子那里，立亚比米勒为王。","notes":[]},{"n":7,"t":"有人将这事告诉约坦，他就去站在基利心山顶上，向众人大声喊叫说：「示剑人哪，你们要听我的话，神也就听你们的话。","notes":[]},{"n":8,"t":"有一时，树木要膏一树为王，管理他们，就去对橄榄树说：『请你作我们的王。』","notes":[]},{"n":9,"t":"橄榄树回答说：『我岂肯止住供奉神和尊重人的油，飘摇在众树之上呢？』","notes":[]},{"n":10,"t":"树木对无花果树说：『请你来作我们的王。』","notes":[]},{"n":11,"t":"无花果树回答说：『我岂肯止住所结甜美的果子，飘摇在众树之上呢？』","notes":[]},{"n":12,"t":"树木对葡萄树说：『请你来作我们的王。』","notes":[]},{"n":13,"t":"葡萄树回答说：『我岂肯止住使神和人喜乐的新酒，飘摇在众树之上呢？』","notes":[]},{"n":14,"t":"众树对荆棘说：『请你来作我们的王。』","notes":[]},{"n":15,"t":"荆棘回答说：『你们若诚诚实实地膏我为王，就要投在我的荫下；不然，愿火从荆棘里出来，烧灭黎巴嫩的香柏树。』","notes":[]},{"n":16,"t":"「现在你们立亚比米勒为王，若按诚实正直善待耶路·巴力和他的全家，这就是酬他的劳。","notes":[]},{"n":17,"t":"从前我父冒死为你们争战，救了你们脱离米甸人的手。","notes":[]},{"n":18,"t":"你们如今起来攻击我的父家，将他众子七十人杀在一块磐石上，又立他婢女所生的儿子亚比米勒为示剑人的王；他原是你们的弟兄。","notes":[]},{"n":19,"t":"你们如今若按诚实正直待耶路·巴力和他的家，就可因亚比米勒得欢乐，他也可因你们得欢乐；","notes":[]},{"n":20,"t":"不然，愿火从亚比米勒发出，烧灭示剑人和米罗众人，又愿火从示剑人和米罗人中出来，烧灭亚比米勒。」","notes":[]},{"n":21,"t":"约坦因怕他弟兄亚比米勒，就逃跑，来到比珥，住在那里。","notes":[]},{"n":22,"t":"亚比米勒管理以色列人三年。","notes":[]},{"n":23,"t":"神使恶魔降在亚比米勒和示剑人中间，示剑人就以诡诈待亚比米勒。","notes":[]},{"n":24,"t":"这是要叫耶路·巴力七十个儿子所受的残害归与他们的哥哥亚比米勒，又叫那流他们血的罪归与帮助他杀弟兄的示剑人。","notes":[]},{"n":25,"t":"示剑人在山顶上设埋伏，等候亚比米勒。凡从他们那里经过的人，他们就抢夺。有人将这事告诉亚比米勒。","notes":[]},{"n":26,"t":"以别的儿子迦勒和他的弟兄来到示剑，示剑人都信靠他。","notes":[]},{"n":27,"t":"示剑人出城到田间去，摘下葡萄，踹酒，设摆筵宴，进他们神的庙中吃喝，咒诅亚比米勒。","notes":[]},{"n":28,"t":"以别的儿子迦勒说：「亚比米勒是谁？示剑是谁？使我们服事他呢？他不是耶路·巴力的儿子吗？他的帮手不是西布勒吗？你们可以服事示剑的父亲哈抹的后裔。我们为何服事亚比米勒呢？","notes":[]},{"n":29,"t":"惟愿这民归我的手下，我就除掉亚比米勒。」迦勒又对亚比米勒说：「增添你的军兵出来吧。」","notes":[]},{"n":30,"t":"邑宰西布勒听见以别的儿子迦勒的话，就发怒，","notes":[]},{"n":31,"t":"悄悄地打发人去见亚比米勒，说：「以别的儿子迦勒和他的弟兄到了示剑，煽惑城中的民攻击你。","notes":[]},{"n":32,"t":"现在你和跟随你的人今夜起来，在田间埋伏。","notes":[]},{"n":33,"t":"到早晨太阳一出，你就起来闯城。迦勒和跟随他的人出来攻击你的时候，你便向他们见机而做。」","notes":[]},{"n":34,"t":"于是，亚比米勒和跟随他的众人夜间起来，分作四队，埋伏等候示剑人。","notes":[]},{"n":35,"t":"以别的儿子迦勒出去，站在城门口。亚比米勒和跟随他的人从埋伏之处起来。","notes":[]},{"n":36,"t":"迦勒看见那些人，就对西布勒说：「看哪，有人从山顶上下来了。」西布勒说：「你看见山的影子，以为是人。」","notes":[]},{"n":37,"t":"迦勒又说：「看哪，有人从高处下来，又有一队从米恶尼尼橡树的路上而来。」","notes":[]},{"n":38,"t":"西布勒对他说：「你曾说，亚比米勒是谁，叫我们服事他？你所夸的口在哪里呢？这不是你所藐视的民吗？你现在出去，与他们交战吧！」","notes":[]},{"n":39,"t":"于是迦勒率领示剑人出去，与亚比米勒交战。","notes":[]},{"n":40,"t":"亚比米勒追赶迦勒；迦勒在他面前逃跑，有许多受伤仆倒的，直到城门。","notes":[]},{"n":41,"t":"亚比米勒住在亚鲁玛。西布勒赶出迦勒和他弟兄，不准他们住在示剑。","notes":[]},{"n":42,"t":"次日，民出到田间，有人告诉亚比米勒；","notes":[]},{"n":43,"t":"他就把他的人分作三队，埋伏在田间，看见示剑人从城里出来，就起来击杀他们。","notes":[]},{"n":44,"t":"亚比米勒和跟随他的一队向前闯去，站在城门口；那两队直闯到田间，击杀了众人。","notes":[]},{"n":45,"t":"亚比米勒整天攻打城，将城夺取，杀了其中的居民，将城拆毁，撒上了盐。","notes":[]},{"n":46,"t":"示剑楼的人听见了，就躲入巴力·比利土庙的卫所。","notes":[]},{"n":47,"t":"有人告诉亚比米勒说：「示剑楼的人都聚在一处。」","notes":[]},{"n":48,"t":"亚比米勒和跟随他的人就都上撒们山。亚比米勒手拿斧子，砍下一根树枝，扛在肩上，对跟随他的人说：「你们看我所行的，也当赶紧照样行。」","notes":[]},{"n":49,"t":"众人就各砍一枝，跟随亚比米勒，把树枝堆在卫所的四围，放火烧了卫所，以致示剑楼的人都死了，男女约有一千。","notes":[]},{"n":50,"t":"亚比米勒到提备斯，向提备斯安营，就攻取了那城。","notes":[]},{"n":51,"t":"城中有一座坚固的楼；城里的众人，无论男女，都逃进楼去，关上门，上了楼顶。","notes":[]},{"n":52,"t":"亚比米勒到了楼前攻打，挨近楼门，要用火焚烧。","notes":[]},{"n":53,"t":"有一个妇人把一块上磨石抛在亚比米勒的头上，打破了他的脑骨。","notes":[]},{"n":54,"t":"他就急忙喊叫拿他兵器的少年人，对他说：「拔出你的刀来，杀了我吧！免得人议论我说，他为一个妇人所杀。」于是少年人把他刺透，他就死了。","notes":[]},{"n":55,"t":"以色列人见亚比米勒死了，便各回自己的地方去了。","notes":[]},{"n":56,"t":"这样，神报应亚比米勒向他父亲所行的恶，就是杀了弟兄七十个人的恶。","notes":[]},{"n":57,"t":"示剑人的一切恶，神也都报应在他们头上；耶路·巴力的儿子约坦的咒诅归到他们身上了。","notes":[]}]},"10":{"heading":"陀拉","verses":[{"n":1,"t":"亚比米勒以后，有以萨迦人朵多的孙子、普瓦的儿子陀拉兴起，拯救以色列人。他住在以法莲山地的沙密。","notes":[]},{"n":2,"t":"陀拉作以色列的士师二十三年，就死了，葬在沙密。","notes":[]},{"n":3,"t":"在他以后有基列人睚珥兴起，作以色列的士师二十二年。","notes":[],"heads":["睚珥"]},{"n":4,"t":"他有三十个儿子，骑着三十匹驴驹。他们有三十座城邑，叫作哈倭特·睚珥，直到如今，都是在基列地。","notes":[]},{"n":5,"t":"睚珥死了，就葬在加们。","notes":[]},{"n":6,"t":"以色列人又行耶和华眼中看为恶的事，去事奉诸巴力和亚斯她录，并亚兰的神、西顿的神、摩押的神、亚扪人的神、非利士人的神，离弃耶和华，不事奉他。","notes":[],"heads":["耶弗他"]},{"n":7,"t":"耶和华的怒气向以色列人发作，就把他们交在非利士人和亚扪人的手中。","notes":[]},{"n":8,"t":"从那年起，他们扰害欺压约旦河那边、住亚摩利人之基列地的以色列人，共有十八年。","notes":[]},{"n":9,"t":"亚扪人又渡过约旦河去攻打犹大和便雅悯，并以法莲族。以色列人就甚觉窘迫。","notes":[]},{"n":10,"t":"以色列人哀求耶和华说：「我们得罪了你；因为离弃了我们神，去事奉诸巴力。」","notes":[]},{"n":11,"t":"耶和华对以色列人说：「我岂没有救过你们脱离埃及人、亚摩利人、亚扪人，和非利士人吗？","notes":[]},{"n":12,"t":"西顿人、亚玛力人、马云人也都欺压你们；你们哀求我，我也拯救你们脱离他们的手。","notes":[]},{"n":13,"t":"你们竟离弃我，事奉别神！所以我不再救你们了。","notes":[]},{"n":14,"t":"你们去哀求所选择的神；你们遭遇急难的时候，让他救你们吧！」","notes":[]},{"n":15,"t":"以色列人对耶和华说：「我们犯罪了，任凭你随意待我们吧！只求你今日拯救我们。」","notes":[]},{"n":16,"t":"以色列人就除掉他们中间的外邦神，事奉耶和华。耶和华因以色列人受的苦难，就心中担忧。","notes":[]},{"n":17,"t":"当时亚扪人聚集，安营在基列。以色列人也聚集，安营在米斯巴。","notes":[]},{"n":18,"t":"基列的民和众首领彼此商议说：「谁能先去攻打亚扪人，谁必作基列一切居民的领袖。」","notes":[]}]},"11":{"heading":"耶弗他的女儿","verses":[{"n":1,"t":"基列人耶弗他是个大能的勇士，是妓女的儿子。耶弗他是基列所生的。","notes":[]},{"n":2,"t":"基列的妻也生了几个儿子：他妻所生的儿子长大了，就赶逐耶弗他，说：「你不可在我们父家承受产业，因为你是妓女的儿子。」","notes":[]},{"n":3,"t":"耶弗他就逃避他的弟兄，去住在陀伯地，有些匪徒到他那里聚集，与他一同出入。","notes":[]},{"n":4,"t":"过了些日子，亚扪人攻打以色列。","notes":[]},{"n":5,"t":"亚扪人攻打以色列的时候，基列的长老到陀伯地去，要叫耶弗他回来；","notes":[]},{"n":6,"t":"对耶弗他说：「请你来作我们的元帅，我们好与亚扪人争战。」","notes":[]},{"n":7,"t":"耶弗他回答基列的长老说：「从前你们不是恨我、赶逐我出离父家吗？现在你们遭遇急难为何到我这里来呢？」","notes":[]},{"n":8,"t":"基列的长老回答耶弗他说：「现在我们到你这里来，是要你同我们去，与亚扪人争战；你可以作基列一切居民的领袖。」","notes":[]},{"n":9,"t":"耶弗他对基列的长老说：「你们叫我回去，与亚扪人争战，耶和华把他交给我，我可以作你们的领袖吗？」","notes":[]},{"n":10,"t":"基列的长老回答耶弗他说：「有耶和华在你我中间作见证，我们必定照你的话行。」","notes":[]},{"n":11,"t":"于是耶弗他同基列的长老回去，百姓就立耶弗他作领袖、作元帅。耶弗他在米斯巴将自己的一切话陈明在耶和华面前。","notes":[]},{"n":12,"t":"耶弗他打发使者去见亚扪人的王，说：「你与我有什么相干，竟来到我国中攻打我呢？」","notes":[]},{"n":13,"t":"亚扪人的王回答耶弗他的使者说：「因为以色列人从埃及上来的时候占据我的地，从亚嫩河到雅博河，直到约旦河。现在你要好好地将这地归还吧！」","notes":[]},{"n":14,"t":"耶弗他又打发使者去见亚扪人的王，","notes":[]},{"n":15,"t":"对他说：「耶弗他如此说，以色列人并没有占据摩押地和亚扪人的地。","notes":[]},{"n":16,"t":"以色列人从埃及上来乃是经过旷野到红海，来到加低斯，","notes":[]},{"n":17,"t":"就打发使者去见以东王，说：『求你容我从你的地经过。』以东王却不应允。又照样打发使者去见摩押王，他也不允准。以色列人就住在加低斯。","notes":[]},{"n":18,"t":"他们又经过旷野，绕着以东和摩押地，从摩押地的东边过来，在亚嫩河边安营，并没有入摩押的境内，因为亚嫩河是摩押的边界。","notes":[]},{"n":19,"t":"以色列人打发使者去见亚摩利王西宏，就是希实本的王，对他说：『求你容我们从你的地经过，往我们自己的地方去。』","notes":[]},{"n":20,"t":"西宏却不信服以色列人，不容他们经过他的境界，乃招聚他的众民在雅杂安营，与以色列人争战。","notes":[]},{"n":21,"t":"耶和华—以色列的神将西宏和他的众民都交在以色列人手中，以色列人就击杀他们，得了亚摩利人的全地：","notes":[]},{"n":22,"t":"从亚嫩河到雅博河，从旷野直到约旦河。","notes":[]},{"n":23,"t":"耶和华—以色列的神在他百姓以色列面前赶出亚摩利人，你竟要得他们的地吗？","notes":[]},{"n":24,"t":"你的神基抹所赐你的地你不是得为业吗？耶和华—我们的神在我们面前所赶出的人，我们就得他的地。","notes":[]},{"n":25,"t":"难道你比摩押王西拨的儿子巴勒还强吗？他曾与以色列人争竞，或是与他们争战吗？","notes":[]},{"n":26,"t":"以色列人住希实本和属希实本的乡村，亚罗珥和属亚罗珥的乡村，并沿亚嫩河的一切城邑，已经有三百年了；在这三百年之内，你们为什么没有取回这些地方呢？","notes":[]},{"n":27,"t":"原来我没有得罪你，你却攻打我，恶待我。愿审判人的耶和华今日在以色列人和亚扪人中间判断是非。」","notes":[]},{"n":28,"t":"但亚扪人的王不肯听耶弗他打发人说的话。","notes":[]},{"n":29,"t":"耶和华的灵降在耶弗他身上，他就经过基列和玛拿西，来到基列的米斯巴，又从米斯巴来到亚扪人那里。","notes":[]},{"n":30,"t":"耶弗他就向耶和华许愿，说：「你若将亚扪人交在我手中，","notes":[]},{"n":31,"t":"我从亚扪人那里平平安安回来的时候，无论什么人，先从我家门出来迎接我，就必归你，我也必将他献上为燔祭。」","notes":[]},{"n":32,"t":"于是耶弗他往亚扪人那里去，与他们争战；耶和华将他们交在他手中，","notes":[]},{"n":33,"t":"他就大大杀败他们，从亚罗珥到米匿，直到亚备勒·基拉明，攻取了二十座城。这样亚扪人就被以色列人制伏了。","notes":[]},{"n":34,"t":"耶弗他回米斯巴到了自己的家，不料，他女儿拿着鼓跳舞出来迎接他，是他独生的，此外无儿无女。","notes":[]},{"n":35,"t":"耶弗他看见她，就撕裂衣服，说：「哀哉！我的女儿啊，你使我甚是愁苦，叫我作难了；因为我已经向耶和华开口许愿，不能挽回。」","notes":[]},{"n":36,"t":"他女儿回答说：「父啊，你既向耶和华开口，就当照你口中所说的向我行，因耶和华已经在仇敌亚扪人身上为你报仇」；","notes":[]},{"n":37,"t":"又对父亲说：「有一件事求你允准：容我去两个月，与同伴在山上，好哀哭我终为处女。」","notes":[]},{"n":38,"t":"耶弗他说：「你去吧！」就容她去两个月。她便和同伴去了，在山上为她终为处女哀哭。","notes":[]},{"n":39,"t":"两月已满，她回到父亲那里，父亲就照所许的愿向她行了。女儿终身没有亲近男子。","notes":[]},{"n":40,"t":"此后以色列中有个规矩，每年以色列的女子去为基列人耶弗他的女儿哀哭四天。","notes":[]}]},"12":{"heading":"耶弗他和以法莲人","verses":[{"n":1,"t":"以法莲人聚集，到了北方，对耶弗他说：「你去与亚扪人争战，为什么没有招我们同去呢？我们必用火烧你和你的房屋。」","notes":[]},{"n":2,"t":"耶弗他对他们说：「我和我的民与亚扪人大大争战；我招你们来，你们竟没有来救我脱离他们的手。","notes":[]},{"n":3,"t":"我见你们不来救我，我就拚命前去攻击亚扪人，耶和华将他们交在我手中。你们今日为什么上我这里来攻打我呢？」","notes":[]},{"n":4,"t":"于是耶弗他招聚基列人，与以法莲人争战。基列人击杀以法莲人，是因他们说：「你们基列人在以法莲、玛拿西中间，不过是以法莲逃亡的人。」","notes":[]},{"n":5,"t":"基列人把守约旦河的渡口，不容以法莲人过去。以法莲逃走的人若说：「容我过去。」基列人就问他说：「你是以法莲人不是？」他若说：「不是」，","notes":[]},{"n":6,"t":"就对他说：「你说『示播列』。」以法莲人因为咬不真字音，便说「西播列」。基列人就将他拿住，杀在约旦河的渡口。那时以法莲人被杀的有四万二千人。","notes":[]},{"n":7,"t":"耶弗他作以色列的士师六年。基列人耶弗他死了，葬在基列的一座城里。","notes":[]},{"n":8,"t":"耶弗他以后，有伯利恒人以比赞作以色列的士师。","notes":[],"heads":["以比赞、以伦、押顿"]},{"n":9,"t":"他有三十个儿子，三十个女儿；女儿都嫁出去了。他给众子从外乡娶了三十个媳妇。他作以色列的士师七年。","notes":[]},{"n":10,"t":"以比赞死了，葬在伯利恒。","notes":[]},{"n":11,"t":"以比赞之后，有西布伦人以伦，作以色列的士师十年。","notes":[]},{"n":12,"t":"西布伦人以伦死了，葬在西布伦地的亚雅仑。","notes":[]},{"n":13,"t":"以伦之后，有比拉顿人希列的儿子押顿作以色列的士师。","notes":[]},{"n":14,"t":"他有四十个儿子，三十个孙子，骑着七十匹驴驹。押顿作以色列的士师八年。","notes":[]},{"n":15,"t":"比拉顿人希列的儿子押顿死了，葬在以法莲地的比拉顿，在亚玛力人的山地。","notes":[]}]},"13":{"heading":"参孙出生","verses":[{"n":1,"t":"以色列人又行耶和华眼中看为恶的事，耶和华将他们交在非利士人手中四十年。","notes":[]},{"n":2,"t":"那时，有一个琐拉人，是属但族的，名叫玛挪亚。他的妻不怀孕，不生育。","notes":[]},{"n":3,"t":"耶和华的使者向那妇人显现，对她说：「向来你不怀孕，不生育，如今你必怀孕生一个儿子。","notes":[]},{"n":4,"t":"所以你当谨慎，清酒浓酒都不可喝，一切不洁之物也不可吃。","notes":[]},{"n":5,"t":"你必怀孕生一个儿子，不可用剃头刀剃他的头，因为这孩子一出胎就归神作拿细耳人。他必起首拯救以色列人脱离非利士人的手。」","notes":[]},{"n":6,"t":"妇人就回去对丈夫说：「有一个神人到我面前来，他的相貌如神使者的相貌，甚是可畏。我没有问他从哪里来，他也没有将他的名告诉我，","notes":[]},{"n":7,"t":"却对我说：『你要怀孕生一个儿子，所以清酒浓酒都不可喝，一切不洁之物也不可吃；因为这孩子从出胎一直到死，必归神作拿细耳人。』」","notes":[]},{"n":8,"t":"玛挪亚就祈求耶和华说：「主啊，求你再差遣那神人到我们这里来，好指教我们怎样待这将要生的孩子。」","notes":[]},{"n":9,"t":"神应允玛挪亚的话；妇人正坐在田间的时候，神的使者又到她那里，她丈夫玛挪亚却没有同她在一处。","notes":[]},{"n":10,"t":"妇人急忙跑去告诉丈夫说：「那日到我面前来的人，又向我显现。」","notes":[]},{"n":11,"t":"玛挪亚起来跟随他的妻来到那人面前，对他说：「与这妇人说话的就是你吗？」他说：「是我。」","notes":[]},{"n":12,"t":"玛挪亚说：「愿你的话应验！我们当怎样待这孩子，他后来当怎样呢？」","notes":[]},{"n":13,"t":"耶和华的使者对玛挪亚说：「我告诉妇人的一切事，她都当谨慎。","notes":[]},{"n":14,"t":"葡萄树所结的都不可吃，清酒浓酒都不可喝，一切不洁之物也不可吃。凡我所吩咐的，她都当遵守。」","notes":[]},{"n":15,"t":"玛挪亚对耶和华的使者说：「求你容我们款留你，好为你预备一只山羊羔。」","notes":[]},{"n":16,"t":"耶和华的使者对玛挪亚说：「你虽然款留我，我却不吃你的食物，你若预备燔祭就当献与耶和华。」原来玛挪亚不知道他是耶和华的使者。","notes":[]},{"n":17,"t":"玛挪亚对耶和华的使者说：「请将你的名告诉我，到你话应验的时候，我们好尊敬你。」","notes":[]},{"n":18,"t":"耶和华的使者对他说：「你何必问我的名，我名是奇妙的。」","notes":[]},{"n":19,"t":"玛挪亚将一只山羊羔和素祭在磐石上献与耶和华，使者行奇妙的事；玛挪亚和他的妻观看，","notes":[]},{"n":20,"t":"见火焰从坛上往上升，耶和华的使者在坛上的火焰中也升上去了。玛挪亚和他的妻看见，就俯伏于地。","notes":[]},{"n":21,"t":"耶和华的使者不再向玛挪亚和他的妻显现，玛挪亚才知道他是耶和华的使者。","notes":[]},{"n":22,"t":"玛挪亚对他的妻说：「我们必要死，因为看见了神。」","notes":[]},{"n":23,"t":"他的妻却对他说：「耶和华若要杀我们，必不从我们手里收纳燔祭和素祭，并不将这一切事指示我们，今日也不将这些话告诉我们。」","notes":[]},{"n":24,"t":"后来妇人生了一个儿子，给他起名叫参孙。孩子长大，耶和华赐福与他。","notes":[]},{"n":25,"t":"在玛哈尼·但，就是琐拉和以实陶中间，耶和华的灵才感动他。","notes":[]}]},"14":{"heading":"参孙和亭拿的女子","verses":[{"n":1,"t":"参孙下到亭拿，在那里看见一个女子，是非利士人的女儿。","notes":[]},{"n":2,"t":"参孙上来禀告他父母说：「我在亭拿看见一个女子，是非利士人的女儿，愿你们给我娶来为妻。」","notes":[]},{"n":3,"t":"他父母说：「在你弟兄的女儿中，或在本国的民中，岂没有一个女子，何至你去在未受割礼的非利士人中娶妻呢？」参孙对他父亲说：「愿你给我娶那女子，因我喜悦她。」","notes":[]},{"n":4,"t":"他的父母却不知道这事是出于耶和华，因为他找机会攻击非利士人。那时，非利士人辖制以色列人。","notes":[]},{"n":5,"t":"参孙跟他父母下亭拿去，到了亭拿的葡萄园，见有一只少壮狮子向他吼叫。","notes":[]},{"n":6,"t":"耶和华的灵大大感动参孙，他虽然手无器械，却将狮子撕裂，如同撕裂山羊羔一样。他行这事并没有告诉父母。","notes":[]},{"n":7,"t":"参孙下去与女子说话，就喜悦她；","notes":[]},{"n":8,"t":"过了些日子，再下去要娶那女子，转向道旁要看死狮，见有一群蜂子和蜜在死狮之内，","notes":[]},{"n":9,"t":"就用手取蜜，且吃且走；到了父母那里，给他父母，他们也吃了；只是没有告诉这蜜是从死狮之内取来的。","notes":[]},{"n":10,"t":"他父亲下去见女子。参孙在那里设摆筵宴，因为向来少年人都有这个规矩。","notes":[]},{"n":11,"t":"众人看见参孙，就请了三十个人陪伴他。","notes":[]},{"n":12,"t":"参孙对他们说：「我给你们出一个谜语，你们在七日筵宴之内，若能猜出意思告诉我，我就给你们三十件里衣，三十套衣裳；","notes":[]},{"n":13,"t":"你们若不能猜出意思告诉我，你们就给我三十件里衣，三十套衣裳。」他们说：「请将谜语说给我们听。」","notes":[]},{"n":14,"t":"参孙对他们说：吃的从吃者出来；甜的从强者出来。他们三日不能猜出谜语的意思。","notes":[]},{"n":15,"t":"到第七天，他们对参孙的妻说：「你诓哄你丈夫，探出谜语的意思告诉我们，免得我们用火烧你和你父家。你们请了我们来，是要夺我们所有的吗？」","notes":[]},{"n":16,"t":"参孙的妻在丈夫面前啼哭说：「你是恨我，不是爱我，你给我本国的人出谜语，却没有将意思告诉我。」参孙回答说：「连我父母我都没有告诉，岂可告诉你呢？」","notes":[]},{"n":17,"t":"七日筵宴之内，她在丈夫面前啼哭，到第七天逼着他，他才将谜语的意思告诉他妻，他妻就告诉本国的人。","notes":[]},{"n":18,"t":"到第七天，日头未落以前，那城里的人对参孙说：有什么比蜜还甜呢？有什么比狮子还强呢？参孙对他们说：你们若非用我的母牛犊耕地，就猜不出我谜语的意思来。","notes":[]},{"n":19,"t":"耶和华的灵大大感动参孙，他就下到亚实基伦，击杀了三十个人，夺了他们的衣裳，将衣裳给了猜出谜语的人。参孙发怒，就上父家去了。","notes":[]},{"n":20,"t":"参孙的妻便归了参孙的陪伴，就是作过他朋友的。","notes":[]}]},"15":{"heading":"参孙击败非利士人","verses":[{"n":1,"t":"过了些日子，到割麦子的时候，参孙带着一只山羊羔去看他的妻，说：「我要进内室见我的妻。」他岳父不容他进去，","notes":[]},{"n":2,"t":"说：「我估定你是极其恨她，因此我将她给了你的陪伴。她的妹子不是比她还美丽吗？你可以娶来代替她吧！」","notes":[]},{"n":3,"t":"参孙说：「这回我加害于非利士人不算有罪。」","notes":[]},{"n":4,"t":"于是参孙去捉了三百只狐狸，将狐狸尾巴一对一对地捆上，将火把捆在两条尾巴中间，","notes":["或译：野狗"]},{"n":5,"t":"点着火把，就放狐狸进入非利士人站着的禾稼，将堆集的禾捆和未割的禾稼，并橄榄园尽都烧了。","notes":[]},{"n":6,"t":"非利士人说：「这事是谁做的呢？」有人说：「是亭拿人的女婿参孙，因为他岳父将他的妻给了他的陪伴。」于是非利士人上去，用火烧了妇人和她的父亲。","notes":[]},{"n":7,"t":"参孙对非利士人说：「你们既然这样行，我必向你们报仇才肯罢休。」","notes":[]},{"n":8,"t":"参孙就大大击杀他们，连腿带腰都砍断了。他便下去，住在以坦磐的穴内。","notes":[]},{"n":9,"t":"非利士人上去安营在犹大，布散在利希。","notes":[]},{"n":10,"t":"犹大人说：「你们为何上来攻击我们呢？」他们说：「我们上来是要捆绑参孙；他向我们怎样行，我们也要向他怎样行。」","notes":[]},{"n":11,"t":"于是有三千犹大人下到以坦磐的穴内，对参孙说：「非利士人辖制我们，你不知道吗？你向我们行的是什么事呢？」他回答说：「他们向我怎样行，我也要向他们怎样行。」","notes":[]},{"n":12,"t":"犹大人对他说：「我们下来是要捆绑你，将你交在非利士人手中。」参孙说：「你们要向我起誓，应承你们自己不害死我。」","notes":[]},{"n":13,"t":"他们说：「我们断不杀你，只要将你捆绑交在非利士人手中。」于是用两条新绳捆绑参孙，将他从以坦磐带上去。","notes":[]},{"n":14,"t":"参孙到了利希，非利士人都迎着喧嚷。耶和华的灵大大感动参孙，他臂上的绳就像火烧的麻一样，他的绑绳都从他手上脱落下来。","notes":[]},{"n":15,"t":"他见一块未干的驴腮骨，就伸手拾起来，用以击杀一千人。","notes":[]},{"n":16,"t":"参孙说：我用驴腮骨杀人成堆，用驴腮骨杀了一千人。","notes":[]},{"n":17,"t":"说完这话，就把那腮骨从手里抛出去了。那地便叫拉末·利希。","notes":[]},{"n":18,"t":"参孙甚觉口渴，就求告耶和华说：「你既借仆人的手施行这么大的拯救，岂可任我渴死、落在未受割礼的人手中呢？」","notes":[]},{"n":19,"t":"神就使利希的洼处裂开，有水从其中涌出来。参孙喝了，精神复原；因此那泉名叫隐·哈歌利，那泉直到今日还在利希。","notes":[]},{"n":20,"t":"当非利士人辖制以色列人的时候，参孙作以色列的士师二十年。","notes":[]}]},"16":{"heading":"参孙在迦萨","verses":[{"n":1,"t":"参孙到了迦萨，在那里看见一个妓女，就与她亲近。","notes":[]},{"n":2,"t":"有人告诉迦萨人说：「参孙到这里来了！」他们就把他团团围住，终夜在城门悄悄埋伏，说：「等到天亮我们便杀他。」","notes":[]},{"n":3,"t":"参孙睡到半夜，起来，将城门的门扇、门框、门闩，一齐拆下来，扛在肩上，扛到希伯仑前的山顶上。","notes":[]},{"n":4,"t":"后来，参孙在梭烈谷喜爱一个妇人，名叫大利拉。","notes":[],"heads":["参孙和大利拉"]},{"n":5,"t":"非利士人的首领上去见那妇人，对她说：「求你诓哄参孙，探探他因何有这么大的力气，我们用何法能胜他，捆绑克制他。我们就每人给你一千一百舍客勒银子。」","notes":[]},{"n":6,"t":"大利拉对参孙说：「求你告诉我，你因何有这么大的力气，当用何法捆绑克制你。」","notes":[]},{"n":7,"t":"参孙回答说：「人若用七条未干的青绳子捆绑我，我就软弱像别人一样。」","notes":[]},{"n":8,"t":"于是非利士人的首领拿了七条未干的青绳子来，交给妇人，她就用绳子捆绑参孙。","notes":[]},{"n":9,"t":"有人预先埋伏在妇人的内室里。妇人说：「参孙哪，非利士人拿你来了！」参孙就挣断绳子，如挣断经火的麻线一般。这样，他力气的根由人还是不知道。","notes":[]},{"n":10,"t":"大利拉对参孙说：「你欺哄我，向我说谎言。现在求你告诉我当用何法捆绑你。」","notes":[]},{"n":11,"t":"参孙回答说：「人若用没有使过的新绳捆绑我，我就软弱像别人一样。」","notes":[]},{"n":12,"t":"大利拉就用新绳捆绑他，对他说：「参孙哪，非利士人拿你来了！」有人预先埋伏在内室里。参孙将臂上的绳挣断了，如挣断一条线一样。","notes":[]},{"n":13,"t":"大利拉对参孙说：「你到如今还是欺哄我，向我说谎言。求你告诉我，当用何法捆绑你。」参孙回答说：「你若将我头上的七条发绺，与纬线同织就可以了。」","notes":[]},{"n":14,"t":"于是大利拉将他的发绺与纬线同织，用橛子钉住，对他说：「参孙哪，非利士人拿你来了！」参孙从睡中醒来，将机上的橛子和纬线一齐都拔出来了。","notes":[]},{"n":15,"t":"大利拉对参孙说：「你既不与我同心，怎么说你爱我呢？你这三次欺哄我，没有告诉我，你因何有这么大的力气。」","notes":[]},{"n":16,"t":"大利拉天天用话催逼他，甚至他心里烦闷要死。","notes":[]},{"n":17,"t":"参孙就把心中所藏的都告诉了她，对她说：「向来人没有用剃头刀剃我的头，因为我自出母胎就归神作拿细耳人；若剃了我的头发，我的力气就离开我，我便软弱像别人一样。」","notes":[]},{"n":18,"t":"大利拉见他把心中所藏的都告诉了她，就打发人到非利士人的首领那里，对他们说：「他已经把心中所藏的都告诉了我，请你们再上来一次。」于是非利士人的首领手里拿着银子，上到妇人那里。","notes":[]},{"n":19,"t":"大利拉使参孙枕着她的膝睡觉，叫了一个人来剃除他头上的七条发绺。于是大利拉克制他，他的力气就离开他了。","notes":[]},{"n":20,"t":"大利拉说：「参孙哪，非利士人拿你来了！」参孙从睡中醒来，心里说：「我要像前几次出去活动身体」；他却不知道耶和华已经离开他了。","notes":[]},{"n":21,"t":"非利士人将他拿住，剜了他的眼睛，带他下到迦萨，用铜链拘索他；他就在监里推磨。","notes":[]},{"n":22,"t":"然而他的头发被剃之后，又渐渐长起来了。","notes":[]},{"n":23,"t":"非利士人的首领聚集，要给他们的神大衮献大祭，并且欢乐，因为他们说：「我们的神将我们的仇敌参孙交在我们手中了。」","notes":[],"heads":["参孙的死"]},{"n":24,"t":"众人看见参孙，就赞美他们的神说：「我们的神将毁坏我们地、杀害我们许多人的仇敌交在我们手中了。」","notes":[]},{"n":25,"t":"他们正宴乐的时候，就说：「叫参孙来，在我们面前戏耍戏耍。」于是将参孙从监里提出来，他就在众人面前戏耍。他们使他站在两柱中间。","notes":[]},{"n":26,"t":"参孙向拉他手的童子说：「求你让我摸着托房的柱子，我要靠一靠。」","notes":[]},{"n":27,"t":"那时房内充满男女，非利士人的众首领也都在那里。房的平顶上约有三千男女观看参孙戏耍。","notes":[]},{"n":28,"t":"参孙求告耶和华说：「主耶和华啊，求你眷念我。神啊，求你赐我这一次的力量，使我在非利士人身上报那剜我双眼的仇。」","notes":[]},{"n":29,"t":"参孙就抱住托房的那两根柱子：左手抱一根，右手抱一根，","notes":[]},{"n":30,"t":"说：「我情愿与非利士人同死！」就尽力屈身，房子倒塌，压住首领和房内的众人。这样，参孙死时所杀的人比活着所杀的还多。","notes":[]},{"n":31,"t":"参孙的弟兄和他父的全家都下去取他的尸首，抬上来葬在琐拉和以实陶中间，在他父玛挪亚的坟墓里。参孙作以色列的士师二十年。","notes":[]}]},"17":{"heading":"米迦的偶像","verses":[{"n":1,"t":"以法莲山地有一个人名叫米迦。","notes":[]},{"n":2,"t":"他对母亲说：「你那一千一百舍客勒银子被人拿去，你因此咒诅，并且告诉了我。看哪，这银子在我这里，是我拿去了。」他母亲说：「我儿啊，愿耶和华赐福与你！」","notes":[]},{"n":3,"t":"米迦就把这一千一百舍客勒银子还他母亲。他母亲说：「我分出这银子来为你献给耶和华，好雕刻一个像，铸成一个像。现在我还是交给你。」","notes":[]},{"n":4,"t":"米迦将银子还他母亲，他母亲将二百舍客勒银子交给银匠，雕刻一个像，铸成一个像，安置在米迦的屋内。","notes":[]},{"n":5,"t":"这米迦有了神堂，又制造以弗得和家中的神像，分派他一个儿子作祭司。","notes":[]},{"n":6,"t":"那时以色列中没有王，各人任意而行。","notes":[]},{"n":7,"t":"犹大的伯利恒有一个少年人，是犹大族的利未人，他在那里寄居。","notes":[]},{"n":8,"t":"这人离开犹大的伯利恒城，要找一个可住的地方。行路的时候，到了以法莲山地，走到米迦的家。","notes":[]},{"n":9,"t":"米迦问他说：「你从哪里来？」他回答说：「从犹大的伯利恒来。我是利未人，要找一个可住的地方。」","notes":[]},{"n":10,"t":"米迦说：「你可以住在我这里，我以你为父、为祭司。我每年给你十舍客勒银子，一套衣服和度日的食物。」利未人就进了他的家。","notes":[]},{"n":11,"t":"利未人情愿与那人同住；那人看这少年人如自己的儿子一样。","notes":[]},{"n":12,"t":"米迦分派这少年的利未人作祭司，他就住在米迦的家里。","notes":[]},{"n":13,"t":"米迦说：「现在我知道耶和华必赐福与我，因我有一个利未人作祭司。」","notes":[]}]},"18":{"heading":"米迦和但支派","verses":[{"n":1,"t":"那时，以色列中没有王。但支派的人仍是寻地居住；因为到那日子，他们还没有在以色列支派中得地为业。","notes":[]},{"n":2,"t":"但人从琐拉和以实陶打发本族中的五个勇士，去仔细窥探那地，吩咐他们说：「你们去窥探那地。」他们来到以法莲山地，进了米迦的住宅，就在那里住宿。","notes":[]},{"n":3,"t":"他们临近米迦的住宅，听出那少年利未人的口音来，就进去问他说：「谁领你到这里来？你在这里做什么？你在这里得什么？」","notes":[]},{"n":4,"t":"他回答说：「米迦待我如此如此，请我作祭司。」","notes":[]},{"n":5,"t":"他们对他说：「请你求问神，使我们知道所行的道路通达不通达。」","notes":[]},{"n":6,"t":"祭司对他们说：「你们可以平平安安地去，你们所行的道路是在耶和华面前的。」","notes":[]},{"n":7,"t":"五人就走了，来到拉亿，见那里的民安居无虑，如同西顿人安居一样。在那地没有人掌权扰乱他们；他们离西顿人也远，与别人没有来往。","notes":[]},{"n":8,"t":"五人回到琐拉和以实陶，见他们的弟兄；弟兄问他们说：「你们有什么话？」","notes":[]},{"n":9,"t":"他们回答说：「起来，我们上去攻击他们吧！我们已经窥探那地，见那地甚好。你们为何静坐不动呢？要急速前往得那地为业，不可迟延。","notes":[]},{"n":10,"t":"你们到了那里，必看见安居无虑的民，地也宽阔。神已将那地交在你们手中；那地百物俱全，一无所缺。」","notes":[]},{"n":11,"t":"于是但族中的六百人，各带兵器，从琐拉和以实陶前往，","notes":[]},{"n":12,"t":"上到犹大的基列·耶琳，在基列·耶琳后边安营。因此那地方名叫玛哈尼·但，直到今日。","notes":[]},{"n":13,"t":"他们从那里往以法莲山地去，来到米迦的住宅。","notes":[]},{"n":14,"t":"从前窥探拉亿地的五个人对他们的弟兄说：「这宅子里有以弗得和家中的神像，并雕刻的像与铸成的像，你们知道吗？现在你们要想一想当怎样行。」","notes":[]},{"n":15,"t":"五人就进入米迦的住宅，到了那少年利未人的房内问他好。","notes":[]},{"n":16,"t":"那六百但人各带兵器，站在门口。","notes":[]},{"n":17,"t":"窥探地的五个人走进去，将雕刻的像、以弗得、家中的神像，并铸成的像，都拿了去。祭司和带兵器的六百人，一同站在门口。","notes":[]},{"n":18,"t":"那五个人进入米迦的住宅，拿出雕刻的像、以弗得、家中的神像，并铸成的像，祭司就问他们说：「你们做什么呢？」","notes":[]},{"n":19,"t":"他们回答说：「不要作声，用手捂口，跟我们去吧！我们必以你为父、为祭司。你作一家的祭司好呢？还是作以色列一族一支派的祭司好呢？」","notes":[]},{"n":20,"t":"祭司心里喜悦，便拿着以弗得和家中的神像，并雕刻的像，进入他们中间。","notes":[]},{"n":21,"t":"他们就转身离开那里，妻子、儿女、牲畜、财物都在前头。","notes":[]},{"n":22,"t":"离米迦的住宅已远，米迦的近邻都聚集来，追赶但人，","notes":[]},{"n":23,"t":"呼叫但人。但人回头问米迦说：「你聚集这许多人来做什么呢？」","notes":[]},{"n":24,"t":"米迦说：「你们将我所做的神像和祭司都带了去，我还有所剩的吗？怎么还问我说『做什么』呢？」","notes":[]},{"n":25,"t":"但人对米迦说：「你不要使我们听见你的声音，恐怕有性暴的人攻击你，以致你和你的全家尽都丧命。」","notes":[]},{"n":26,"t":"但人还是走他们的路。米迦见他们的势力比自己强盛，就转身回家去了。","notes":[]},{"n":27,"t":"但人将米迦所做的神像和他的祭司都带到拉亿，见安居无虑的民，就用刀杀了那民，又放火烧了那城，","notes":[]},{"n":28,"t":"并无人搭救；因为离西顿远，他们又与别人没有来往。城在平原，那平原靠近伯·利合。但人又在那里修城居住，","notes":[]},{"n":29,"t":"照着他们始祖以色列之子但的名字，给那城起名叫但；原先那城名叫拉亿。","notes":[]},{"n":30,"t":"但人就为自己设立那雕刻的像。摩西的孙子、革舜的儿子约拿单，和他的子孙作但支派的祭司，直到那地遭掳掠的日子。","notes":[]},{"n":31,"t":"神的殿在示罗多少日子，但人为自己设立米迦所雕刻的像也在但多少日子。","notes":[]}]},"19":{"heading":"利未人和他的妾","verses":[{"n":1,"t":"当以色列中没有王的时候，有住以法莲山地那边的一个利未人，娶了一个犹大伯利恒的女子为妾。","notes":[]},{"n":2,"t":"妾行淫离开丈夫，回犹大的伯利恒，到了父家，在那里住了四个月。","notes":[]},{"n":3,"t":"她丈夫起来，带着一个仆人、两匹驴去见她，用好话劝她回来。女子就引丈夫进入父家。她父见了那人，便欢欢喜喜地迎接。","notes":[]},{"n":4,"t":"那人的岳父，就是女子的父亲，将那人留下住了三天。于是二人一同吃喝、住宿。","notes":[]},{"n":5,"t":"到第四天，利未人清早起来要走，女子的父亲对女婿说：「请你吃点饭，加添心力，然后可以行路。」","notes":[]},{"n":6,"t":"于是二人坐下一同吃喝。女子的父亲对那人说：「请你再住一夜，畅快你的心。」","notes":[]},{"n":7,"t":"那人起来要走，他岳父强留他，他又住了一宿。","notes":[]},{"n":8,"t":"到第五天，他清早起来要走，女子的父亲说：「请你吃点饭，加添心力，等到日头偏西再走。」于是二人一同吃饭。","notes":[]},{"n":9,"t":"那人同他的妾和仆人起来要走，他岳父，就是女子的父亲，对他说：「看哪，日头偏西了，请你再住一夜；天快晚了，可以在这里住宿，畅快你的心。明天早早起行回家去。」","notes":[]},{"n":10,"t":"那人不愿再住一夜，就备上那两匹驴，带着妾起身走了，来到耶布斯的对面（耶布斯就是耶路撒冷。）","notes":[]},{"n":11,"t":"临近耶布斯的时候，日头快要落了，仆人对主人说：「我们不如进这耶布斯人的城里住宿。」","notes":[]},{"n":12,"t":"主人回答说：「我们不可进不是以色列人住的外邦城，不如过到基比亚去」；","notes":[]},{"n":13,"t":"又对仆人说：「我们可以到一个地方，或住在基比亚，或住在拉玛。」","notes":[]},{"n":14,"t":"他们就往前走。将到便雅悯的基比亚，日头已经落了；","notes":[]},{"n":15,"t":"他们进入基比亚要在那里住宿，就坐在城里的街上，因为无人接他们进家住宿。","notes":[]},{"n":16,"t":"晚上，有一个老年人从田间做工回来。他原是以法莲山地的人，住在基比亚；那地方的人却是便雅悯人。","notes":[]},{"n":17,"t":"老年人举目看见客人坐在城里的街上，就问他说：「你从哪里来？要往哪里去？」","notes":[]},{"n":18,"t":"他回答说：「我们从犹大的伯利恒来，要往以法莲山地那边去。我原是那里的人，到过犹大的伯利恒，现在我往耶和华的殿去，在这里无人接我进他的家。","notes":[]},{"n":19,"t":"其实我有粮草可以喂驴，我与我的妾，并我的仆人，有饼有酒，并不缺少什么。」","notes":[]},{"n":20,"t":"老年人说：「愿你平安！你所需用的我都给你，只是不可在街上过夜。」","notes":[]},{"n":21,"t":"于是领他们到家里，喂上驴，他们就洗脚吃喝。","notes":[]},{"n":22,"t":"他们心里正欢畅的时候，城中的匪徒围住房子，连连叩门，对房主老人说：「你把那进你家的人带出来，我们要与他交合。」","notes":[]},{"n":23,"t":"那房主出来对他们说：「弟兄们哪，不要这样作恶；这人既然进了我的家，你们就不要行这丑事。","notes":[]},{"n":24,"t":"我有个女儿，还是处女，并有这人的妾，我将她们领出来任凭你们玷辱她们，只是向这人不可行这样的丑事。」","notes":[]},{"n":25,"t":"那些人却不听从他的话。那人就把他的妾拉出去交给他们，他们便与她交合，终夜凌辱她，直到天色快亮才放她去。","notes":[]},{"n":26,"t":"天快亮的时候，妇人回到她主人住宿的房门前，就仆倒在地，直到天亮。","notes":[]},{"n":27,"t":"早晨，她的主人起来开了房门，出去要行路，不料那妇人仆倒在房门前，两手搭在门槛上；","notes":[]},{"n":28,"t":"就对妇人说：「起来，我们走吧！」妇人却不回答。那人便将她驮在驴上，起身回本处去了。","notes":[]},{"n":29,"t":"到了家里，用刀将妾的尸身切成十二块，使人拿着传送以色列的四境。","notes":[]},{"n":30,"t":"凡看见的人都说：「从以色列人出埃及地，直到今日，这样的事没有行过，也没有见过。现在应当思想，大家商议当怎样办理。」","notes":[]}]},"20":{"heading":"以色列人准备打仗","verses":[{"n":1,"t":"于是以色列从但到别是巴，以及住基列地的众人都出来，如同一人，聚集在米斯巴耶和华面前。","notes":[]},{"n":2,"t":"以色列民的首领，就是各支派的军长，都站在神百姓的会中；拿刀的步兵共有四十万。","notes":[]},{"n":3,"t":"以色列人上到米斯巴，便雅悯人都听见了。以色列人说：「请你将这件恶事的情由对我们说明。」","notes":[]},{"n":4,"t":"那利未人，就是被害之妇人的丈夫，回答说：「我和我的妾到了便雅悯的基比亚住宿。","notes":[]},{"n":5,"t":"基比亚人夜间起来，围了我住的房子，想要杀我，又将我的妾强奸致死。","notes":[]},{"n":6,"t":"我就把我妾的尸身切成块子，使人拿着传送以色列得为业的全地，因为基比亚人在以色列中行了凶淫丑恶的事。","notes":[]},{"n":7,"t":"你们以色列人都当筹划商议。」","notes":[]},{"n":8,"t":"众民都起来如同一人，说：「我们连一人都不回自己帐棚、自己房屋去。","notes":[]},{"n":9,"t":"我们向基比亚人必这样行，照所掣的签去攻击他们。","notes":[]},{"n":10,"t":"我们要在以色列各支派中，一百人挑取十人，一千人挑取百人，一万人挑取千人，为民运粮，等大众到了便雅悯的基比亚，就照基比亚人在以色列中所行的丑事征伐他们。」","notes":[]},{"n":11,"t":"于是以色列众人彼此连合如同一人，聚集攻击那城。","notes":[]},{"n":12,"t":"以色列众支派打发人去，问便雅悯支派的各家说：「你们中间怎么做了这样的恶事呢？","notes":[]},{"n":13,"t":"现在你们要将基比亚的那些匪徒交出来，我们好治死他们，从以色列中除掉这恶。」便雅悯人却不肯听从他们弟兄以色列人的话。","notes":[]},{"n":14,"t":"便雅悯人从他们的各城里出来，聚集到了基比亚，要与以色列人打仗。","notes":[]},{"n":15,"t":"那时便雅悯人从各城里点出拿刀的，共有二万六千；另外还有基比亚人点出七百精兵。","notes":[]},{"n":16,"t":"在众军之中有拣选的七百精兵，都是左手便利的，能用机弦甩石打人，毫发不差。","notes":[]},{"n":17,"t":"便雅悯人之外，点出以色列人拿刀的，共有四十万，都是战士。","notes":[]},{"n":18,"t":"以色列人就起来，到伯特利去求问神说：「我们中间谁当首先上去与便雅悯人争战呢？」耶和华说：「犹大当先上去。」","notes":[],"heads":["攻打便雅悯人"]},{"n":19,"t":"以色列人早晨起来，对着基比亚安营。","notes":[]},{"n":20,"t":"以色列人出来，要与便雅悯人打仗，就在基比亚前摆阵。","notes":[]},{"n":21,"t":"便雅悯人就从基比亚出来，当日杀死以色列人二万二千。","notes":[]},{"n":22,"t":"以色列人彼此奋勇，仍在头一日摆阵的地方又摆阵。","notes":[]},{"n":23,"t":"未摆阵之先，以色列人上去，在耶和华面前哭号，直到晚上，求问耶和华说：「我们再去与我们弟兄便雅悯人打仗可以不可以？」耶和华说：「可以上去攻击他们。」","notes":[]},{"n":24,"t":"第二日，以色列人就上前攻击便雅悯人。","notes":[]},{"n":25,"t":"便雅悯人也在这日从基比亚出来，与以色列人接战，又杀死他们一万八千，都是拿刀的。","notes":[]},{"n":26,"t":"以色列众人就上到伯特利，坐在耶和华面前哭号，当日禁食直到晚上；又在耶和华面前献燔祭和平安祭。","notes":[]},{"n":27,"t":"那时，神的约柜在那里；亚伦的孙子、以利亚撒的儿子非尼哈侍立在约柜前。以色列人问耶和华说：「我们当再出去与我们弟兄便雅悯人打仗呢？还是罢兵呢？」耶和华说：「你们当上去，因为明日我必将他们交在你们手中。」","notes":[],"end":28},{"n":29,"t":"以色列人在基比亚的四围设下伏兵。","notes":[]},{"n":30,"t":"第三日，以色列人又上去攻击便雅悯人，在基比亚前摆阵，与前两次一样。","notes":[]},{"n":31,"t":"便雅悯人也出来迎敌，就被引诱离城；在田间两条路上，一通伯特利，一通基比亚，像前两次，动手杀死以色列人约有三十个。","notes":[]},{"n":32,"t":"便雅悯人说：「他们仍旧败在我们面前。」但以色列人说：「我们不如逃跑，引诱他们离开城到路上来。」","notes":[]},{"n":33,"t":"以色列众人都起来，在巴力·他玛摆阵，以色列的伏兵从马利·迦巴埋伏的地方冲上前去。","notes":[]},{"n":34,"t":"有以色列人中的一万精兵，来到基比亚前接战，势派甚是凶猛；便雅悯人却不知道灾祸临近了。","notes":[]},{"n":35,"t":"耶和华使以色列人杀败便雅悯人。那日，以色列人杀死便雅悯人二万五千一百，都是拿刀的。","notes":[]},{"n":36,"t":"于是便雅悯人知道自己败了。先是以色列人；因为靠着在基比亚前所设的伏兵，就在便雅悯人面前诈败。","notes":[],"heads":["以色列人得胜"]},{"n":37,"t":"伏兵急忙闯进基比亚，用刀杀死全城的人。","notes":[]},{"n":38,"t":"以色列人预先同伏兵约定在城内放火，以烟气上腾为号。","notes":[]},{"n":39,"t":"以色列人临退阵的时候，便雅悯人动手杀死以色列人，约有三十个，就说：「他们仍像前次被我们杀败了。」","notes":[]},{"n":40,"t":"当烟气如柱从城中上腾的时候，便雅悯人回头观看，见全城的烟气冲天。","notes":[]},{"n":41,"t":"以色列人又转身回来，便雅悯人就甚惊惶，因为看见灾祸临到自己了。","notes":[]},{"n":42,"t":"他们在以色列人面前转身往旷野逃跑；以色列人在后面追杀。那从各城里出来的，也都夹攻杀灭他们。","notes":[]},{"n":43,"t":"以色列人围绕便雅悯人，追赶他们，在他们歇脚之处、对着日出之地的基比亚践踏他们。","notes":[]},{"n":44,"t":"便雅悯人死了的有一万八千，都是勇士。","notes":[]},{"n":45,"t":"其余的人转身向旷野逃跑，往临门磐去。以色列人在道路上杀了他们五千人，如拾取遗穗一样，追到基顿又杀了他们二千人。","notes":[]},{"n":46,"t":"那日便雅悯死了的共有二万五千人，都是拿刀的勇士。","notes":[]},{"n":47,"t":"只剩下六百人，转身向旷野逃跑，到了临门磐，就在那里住了四个月。","notes":[]},{"n":48,"t":"以色列人又转到便雅悯地，将各城的人和牲畜，并一切所遇见的，都用刀杀尽，又放火烧了一切城邑。","notes":[]}]},"21":{"heading":"为便雅悯支派人找妻","verses":[{"n":1,"t":"以色列人在米斯巴曾起誓说：「我们都不将女儿给便雅悯人为妻。」","notes":[]},{"n":2,"t":"以色列人来到伯特利，坐在神面前直到晚上，放声痛哭，","notes":[]},{"n":3,"t":"说：「耶和华—以色列的神啊，为何以色列中有这样缺了一支派的事呢？」","notes":[]},{"n":4,"t":"次日清早，百姓起来，在那里筑了一座坛，献燔祭和平安祭。","notes":[]},{"n":5,"t":"以色列人彼此问说：「以色列各支派中，谁没有同会众上到耶和华面前来呢？」先是以色列人起过大誓说，凡不上米斯巴到耶和华面前来的，必将他治死。","notes":[]},{"n":6,"t":"以色列人为他们的弟兄便雅悯后悔，说：「如今以色列中绝了一个支派了。","notes":[]},{"n":7,"t":"我们既在耶和华面前起誓说，必不将我们的女儿给便雅悯人为妻，现在我们当怎样办理、使他们剩下的人有妻呢？」","notes":[]},{"n":8,"t":"又彼此问说：「以色列支派中谁没有上米斯巴到耶和华面前来呢？」他们就查出基列·雅比没有一人进营到会众那里；","notes":[]},{"n":9,"t":"因为百姓被数的时候，没有一个基列·雅比人在那里。","notes":[]},{"n":10,"t":"会众就打发一万二千大勇士，吩咐他们说：「你们去用刀将基列·雅比人连妇女带孩子都击杀了。","notes":[]},{"n":11,"t":"所当行的就是这样：要将一切男子和已嫁的女子尽行杀戮。」","notes":[]},{"n":12,"t":"他们在基列·雅比人中，遇见了四百个未嫁的处女，就带到迦南地的示罗营里。","notes":[]},{"n":13,"t":"全会众打发人到临门磐的便雅悯人那里，向他们说和睦的话。","notes":[]},{"n":14,"t":"当时便雅悯人回来了，以色列人就把所存活基列·雅比的女子给他们为妻，还是不够。","notes":[]},{"n":15,"t":"百姓为便雅悯人后悔，因为耶和华使以色列人缺了一个支派 。","notes":["原文是使以色列中有了破口"]},{"n":16,"t":"会中的长老说：「便雅悯中的女子既然除灭了，我们当怎样办理、使那余剩的人有妻呢？」","notes":[]},{"n":17,"t":"又说：「便雅悯逃脱的人当有地业，免得以色列中涂抹了一个支派。","notes":[]},{"n":18,"t":"只是我们不能将自己的女儿给他们为妻；因为以色列人曾起誓说，有将女儿给便雅悯人为妻的，必受咒诅。」","notes":[]},{"n":19,"t":"他们又说：「在利波拿以南，伯特利以北，在示剑大路以东的示罗，年年有耶和华的节期」；","notes":[]},{"n":20,"t":"就吩咐便雅悯人说：「你们去，在葡萄园中埋伏。","notes":[]},{"n":21,"t":"若看见示罗的女子出来跳舞，就从葡萄园出来，在示罗的女子中各抢一个为妻，回便雅悯地去。","notes":[]},{"n":22,"t":"他们的父亲或是弟兄若来与我们争竞，我们就说：『求你们看我们的情面，施恩给这些人，因我们在争战的时候没有给他们留下女子为妻。这也不是你们将女子给他们的；若是你们给的，就算有罪。』」","notes":[]},{"n":23,"t":"于是便雅悯人照样而行，按着他们的数目从跳舞的女子中抢去为妻，就回自己的地业去，又重修城邑居住。","notes":[]},{"n":24,"t":"当时以色列人离开那里，各归本支派、本宗族、本地业去了。","notes":[]},{"n":25,"t":"那时，以色列中没有王，各人任意而行。","notes":[]}]}},"RUT":{"1":{"heading":"以利米勒全家迁往摩押","verses":[{"n":1,"t":"当士师秉政的时候，国中遭遇饥荒。在犹大的伯利恒，有一个人带着妻子和两个儿子往摩押地去寄居。","notes":[]},{"n":2,"t":"这人名叫以利米勒，他的妻名叫拿俄米；他两个儿子，一个名叫玛伦，一个名叫基连，都是犹大伯利恒的以法他人。他们到了摩押地，就住在那里。","notes":[]},{"n":3,"t":"后来拿俄米的丈夫以利米勒死了，剩下妇人和她两个儿子。","notes":[]},{"n":4,"t":"这两个儿子娶了摩押女子为妻，一个名叫俄珥巴，一个名叫路得，在那里住了约有十年。","notes":[]},{"n":5,"t":"玛伦和基连二人也死了，剩下拿俄米，没有丈夫，也没有儿子。","notes":[]},{"n":6,"t":"她就与两个儿妇起身，要从摩押地归回；因为她在摩押地听见耶和华眷顾自己的百姓，赐粮食与他们。","notes":[],"heads":["拿俄米和路得回伯利恒"]},{"n":7,"t":"于是她和两个儿妇起行离开所住的地方，要回犹大地去。","notes":[]},{"n":8,"t":"拿俄米对两个儿妇说：「你们各人回娘家去吧。愿耶和华恩待你们，像你们恩待已死的人与我一样！","notes":[]},{"n":9,"t":"愿耶和华使你们各在新夫家中得平安！」于是拿俄米与她们亲嘴。她们就放声而哭，","notes":[]},{"n":10,"t":"说：「不然，我们必与你一同回你本国去。」","notes":[]},{"n":11,"t":"拿俄米说：「我女儿们哪，回去吧！为何要跟我去呢？我还能生子作你们的丈夫吗？","notes":[]},{"n":12,"t":"我女儿们哪，回去吧！我年纪老迈，不能再有丈夫；即或说，我还有指望，今夜有丈夫可以生子，","notes":[]},{"n":13,"t":"你们岂能等着他们长大呢？你们岂能等着他们不嫁别人呢？我女儿们哪，不要这样。我为你们的缘故甚是愁苦，因为耶和华伸手攻击我。」","notes":[]},{"n":14,"t":"两个儿妇又放声而哭，俄珥巴与婆婆亲嘴而别，只是路得舍不得拿俄米。","notes":[]},{"n":15,"t":"拿俄米说：「看哪，你嫂子已经回她本国和她所拜的神那里去了，你也跟着你嫂子回去吧！」","notes":[]},{"n":16,"t":"路得说：「不要催我回去不跟随你。你往哪里去，我也往那里去；你在哪里住宿，我也在那里住宿；你的国就是我的国，你的神就是我的神。","notes":[]},{"n":17,"t":"你在哪里死，我也在那里死，也葬在那里。除非死能使你我相离！不然，愿耶和华重重地降罚与我。」","notes":[]},{"n":18,"t":"拿俄米见路得定意要跟随自己去，就不再劝她了。","notes":[]},{"n":19,"t":"于是二人同行，来到伯利恒。她们到了伯利恒，合城的人就都惊讶。妇女们说：「这是拿俄米吗？」","notes":[]},{"n":20,"t":"拿俄米对她们说：「不要叫我拿俄米，要叫我玛拉，因为全能者使我受了大苦。","notes":["就是甜的意思","就是苦的意思"]},{"n":21,"t":"我满满地出去，耶和华使我空空地回来。耶和华降祸与我；全能者使我受苦。既是这样，你们为何还叫我拿俄米呢？」","notes":[]},{"n":22,"t":"拿俄米和她儿妇摩押女子路得，从摩押地回来到伯利恒，正是动手割大麦的时候。","notes":[]}]},"2":{"heading":"路得在波阿斯田里捡麦穗","verses":[{"n":1,"t":"拿俄米的丈夫以利米勒的亲族中，有一个人名叫波阿斯，是个大财主。","notes":[]},{"n":2,"t":"摩押女子路得对拿俄米说：「容我往田间去，我蒙谁的恩，就在谁的身后拾取麦穗。」拿俄米说：「女儿啊，你只管去。」","notes":[]},{"n":3,"t":"路得就去了，来到田间，在收割的人身后拾取麦穗。她恰巧到了以利米勒本族的人波阿斯那块田里。","notes":[]},{"n":4,"t":"波阿斯正从伯利恒来，对收割的人说：「愿耶和华与你们同在！」他们回答说：「愿耶和华赐福与你！」","notes":[]},{"n":5,"t":"波阿斯问监管收割的仆人说：「那是谁家的女子？」","notes":[]},{"n":6,"t":"监管收割的仆人回答说：「是那摩押女子，跟随拿俄米从摩押地回来的。","notes":[]},{"n":7,"t":"她说：『请你容我跟着收割的人拾取打捆剩下的麦穗。』她从早晨直到如今，除了在屋子里坐一会儿，常在这里。」","notes":[]},{"n":8,"t":"波阿斯对路得说：「女儿啊，听我说，不要往别人田里拾取麦穗，也不要离开这里，要常与我使女们在一处。","notes":[]},{"n":9,"t":"我的仆人在那块田收割，你就跟着他们去。我已经吩咐仆人不可欺负你；你若渴了，就可以到器皿那里喝仆人打来的水。」","notes":[]},{"n":10,"t":"路得就俯伏在地叩拜，对他说：「我既是外邦人，怎么蒙你的恩，这样顾恤我呢？」","notes":[]},{"n":11,"t":"波阿斯回答说：「自从你丈夫死后，凡你向婆婆所行的，并你离开父母和本地，到素不认识的民中，这些事人全都告诉我了。","notes":[]},{"n":12,"t":"愿耶和华照你所行的赏赐你。你来投靠耶和华—以色列神的翅膀下，愿你满得他的赏赐。」","notes":[]},{"n":13,"t":"路得说：「我主啊，愿在你眼前蒙恩。我虽然不及你的一个使女，你还用慈爱的话安慰我的心。」","notes":[]},{"n":14,"t":"到了吃饭的时候，波阿斯对路得说：「你到这里来吃饼，将饼蘸在醋里。」路得就在收割的人旁边坐下；他们把烘了的穗子递给她。她吃饱了，还有余剩的。","notes":[]},{"n":15,"t":"她起来又拾取麦穗，波阿斯吩咐仆人说：「她就是在捆中拾取麦穗，也可以容她，不可羞辱她；","notes":[]},{"n":16,"t":"并要从捆里抽出些来，留在地下任她拾取，不可叱吓她。」","notes":[]},{"n":17,"t":"这样，路得在田间拾取麦穗，直到晚上，将所拾取的打了，约有一伊法大麦。","notes":[]},{"n":18,"t":"她就把所拾取的带进城去给婆婆看，又把她吃饱了所剩的给了婆婆。","notes":[]},{"n":19,"t":"婆婆问她说：「你今日在哪里拾取麦穗，在哪里做工呢？愿那顾恤你的得福。」路得就告诉婆婆说：「我今日在一个名叫波阿斯的人那里做工。」","notes":[]},{"n":20,"t":"拿俄米对儿妇说：「愿那人蒙耶和华赐福，因为他不断地恩待活人死人。」拿俄米又说：「那是我们本族的人，是一个至近的亲属。」","notes":[]},{"n":21,"t":"摩押女子路得说：「他对我说：『你要紧随我的仆人拾取麦穗，直等他们收完了我的庄稼。』」","notes":[]},{"n":22,"t":"拿俄米对儿妇路得说：「女儿啊，你跟着他的使女出去，不叫人遇见你在别人田间，这才为好。」","notes":[]},{"n":23,"t":"于是路得与波阿斯的使女常在一处拾取麦穗，直到收完了大麦和小麦。路得仍与婆婆同住。","notes":[]}]},"3":{"heading":"拿俄米替路得找归宿","verses":[{"n":1,"t":"路得的婆婆拿俄米对她说：「女儿啊，我不当为你找个安身之处，使你享福吗？","notes":[]},{"n":2,"t":"你与波阿斯的使女常在一处，波阿斯不是我们的亲族吗？他今夜在场上簸大麦；","notes":[]},{"n":3,"t":"你要沐浴抹膏，换上衣服，下到场上，却不要使那人认出你来。你等他吃喝完了，","notes":[]},{"n":4,"t":"到他睡的时候，你看准他睡的地方，就进去掀开他脚上的被，躺卧在那里，他必告诉你所当做的事。」","notes":[]},{"n":5,"t":"路得说：「凡你所吩咐的，我必遵行。」","notes":[]},{"n":6,"t":"路得就下到场上，照她婆婆所吩咐她的而行。","notes":[]},{"n":7,"t":"波阿斯吃喝完了，心里欢畅，就去睡在麦堆旁边。路得便悄悄地来掀开他脚上的被，躺卧在那里。","notes":[]},{"n":8,"t":"到了夜半，那人忽然惊醒，翻过身来，不料有女子躺在他的脚下。","notes":[]},{"n":9,"t":"他就说：「你是谁？」回答说：「我是你的婢女路得。求你用你的衣襟遮盖我，因为你是我一个至近的亲属。」","notes":[]},{"n":10,"t":"波阿斯说：「女儿啊，愿你蒙耶和华赐福。你末后的恩比先前更大；因为少年人无论贫富，你都没有跟从。","notes":[]},{"n":11,"t":"女儿啊，现在不要惧怕，凡你所说的，我必照着行；我本城的人都知道你是个贤德的女子。","notes":[]},{"n":12,"t":"我实在是你一个至近的亲属，只是还有一个人比我更近。","notes":[]},{"n":13,"t":"你今夜在这里住宿，明早他若肯为你尽亲属的本分，就由他吧！倘若不肯，我指着永生的耶和华起誓，我必为你尽了本分，你只管躺到天亮。」","notes":[]},{"n":14,"t":"路得便在他脚下躺到天快亮，人彼此不能辨认的时候就起来了。波阿斯说：「不可使人知道有女子到场上来」；","notes":[]},{"n":15,"t":"又对路得说：「打开你所披的外衣。」她打开了，波阿斯就撮了六簸箕大麦，帮她扛在肩上，她便进城去了。","notes":[]},{"n":16,"t":"路得回到婆婆那里，婆婆说：「女儿啊，怎么样了？」路得就将那人向她所行的述说了一遍，","notes":[]},{"n":17,"t":"又说：「那人给了我六簸箕大麦，对我说：『你不可空手回去见你的婆婆。』」","notes":[]},{"n":18,"t":"婆婆说：「女儿啊，你只管安坐等候，看这事怎样成就，因为那人今日不办成这事必不休息。」","notes":[]}]},"4":{"heading":"波阿斯娶路得","verses":[{"n":1,"t":"波阿斯到了城门，坐在那里，恰巧波阿斯所说的那至近的亲属经过。波阿斯说：「某人哪，你来坐在这里。」他就来坐下。","notes":[]},{"n":2,"t":"波阿斯又从本城的长老中拣选了十人，对他们说：「请你们坐在这里。」他们就都坐下。","notes":[]},{"n":3,"t":"波阿斯对那至近的亲属说：「从摩押地回来的拿俄米，现在要卖我们族兄以利米勒的那块地；","notes":[]},{"n":4,"t":"我想当赎那块地的是你，其次是我，以外再没有别人了。你可以在这里的人面前和我本国的长老面前说明，你若肯赎就赎，若不肯赎就告诉我。」那人回答说：「我肯赎。」","notes":[]},{"n":5,"t":"波阿斯说：「你从拿俄米手中买这地的时候，也当娶死人的妻摩押女子路得，使死人在产业上存留他的名。」","notes":["原文是买；十节同"]},{"n":6,"t":"那人说：「这样我就不能赎了，恐怕于我的产业有碍。你可以赎我所当赎的，我不能赎了。」","notes":[]},{"n":7,"t":"从前，在以色列中要定夺什么事，或赎回，或交易，这人就脱鞋给那人。以色列人都以此为证据。","notes":[]},{"n":8,"t":"那人对波阿斯说：「你自己买吧！」于是将鞋脱下来了。","notes":[]},{"n":9,"t":"波阿斯对长老和众民说：「你们今日作见证，凡属以利米勒和基连、玛伦的，我都从拿俄米手中置买了；","notes":[]},{"n":10,"t":"又娶了玛伦的妻摩押女子路得为妻，好在死人的产业上存留他的名，免得他的名在本族本乡灭没。你们今日可以作见证。」","notes":[]},{"n":11,"t":"在城门坐着的众民和长老都说：「我们作见证。愿耶和华使进你家的这女子，像建立以色列家的拉结、利亚二人一样。又愿你在以法他得亨通，在伯利恒得名声。","notes":[]},{"n":12,"t":"愿耶和华从这少年女子赐你后裔，使你的家像她玛从犹大所生法勒斯的家一般。」","notes":[]},{"n":13,"t":"于是，波阿斯娶了路得为妻，与她同房。耶和华使她怀孕生了一个儿子。","notes":[],"heads":["波阿斯和他的后代"]},{"n":14,"t":"妇人们对拿俄米说：「耶和华是应当称颂的！因为今日没有撇下你，使你无至近的亲属。愿这孩子在以色列中得名声。","notes":[]},{"n":15,"t":"他必提起你的精神，奉养你的老，因为是爱慕你的那儿妇所生的。有这儿妇比有七个儿子还好！」","notes":[]},{"n":16,"t":"拿俄米就把孩子抱在怀中，作他的养母。","notes":[]},{"n":17,"t":"邻舍的妇人说：「拿俄米得孩子了！」就给孩子起名叫俄备得。这俄备得是耶西的父，耶西是大卫的父。","notes":[]},{"n":18,"t":"法勒斯的后代记在下面：法勒斯生希斯仑；","notes":[]},{"n":19,"t":"希斯仑生兰；兰生亚米拿达；","notes":[]},{"n":20,"t":"亚米拿达生拿顺；拿顺生撒门；","notes":[]},{"n":21,"t":"撒门生波阿斯；波阿斯生俄备得；","notes":[]},{"n":22,"t":"俄备得生耶西；耶西生大卫。","notes":[]}]}},"1SA":{"1":{"heading":"以利加拿和他的家眷在示罗","verses":[{"n":1,"t":"以法莲山地的拉玛·琐非有一个以法莲人，名叫以利加拿，是苏弗的玄孙，托户的曾孙，以利户的孙子，耶罗罕的儿子。","notes":[]},{"n":2,"t":"他有两个妻：一名哈拿，一名毗尼拿。毗尼拿有儿女，哈拿没有儿女。","notes":[]},{"n":3,"t":"这人每年从本城上到示罗，敬拜祭祀万军之耶和华；在那里有以利的两个儿子何弗尼、非尼哈当耶和华的祭司。","notes":[]},{"n":4,"t":"以利加拿每逢献祭的日子，将祭肉分给他的妻毗尼拿和毗尼拿所生的儿女；","notes":[]},{"n":5,"t":"给哈拿的却是双分，因为他爱哈拿。无奈耶和华不使哈拿生育。","notes":[]},{"n":6,"t":"毗尼拿见耶和华不使哈拿生育，就作她的对头，大大激动她，要使她生气。","notes":[]},{"n":7,"t":"每年上到耶和华殿的时候，以利加拿都以双分给哈拿；毗尼拿仍是激动她，以致她哭泣不吃饭。","notes":[]},{"n":8,"t":"她丈夫以利加拿对她说：「哈拿啊，你为何哭泣，不吃饭，心里愁闷呢？有我不比十个儿子还好吗？」","notes":[]},{"n":9,"t":"他们在示罗吃喝完了，哈拿就站起来。祭司以利在耶和华殿的门框旁边，坐在自己的位上。","notes":[],"heads":["哈拿和以利"]},{"n":10,"t":"哈拿心里愁苦，就痛痛哭泣，祈祷耶和华，","notes":[]},{"n":11,"t":"许愿说：「万军之耶和华啊，你若垂顾婢女的苦情，眷念不忘婢女，赐我一个儿子，我必使他终身归与耶和华，不用剃头刀剃他的头。」","notes":[]},{"n":12,"t":"哈拿在耶和华面前不住地祈祷，以利定睛看她的嘴。（","notes":[]},{"n":13,"t":"原来哈拿心中默祷，只动嘴唇，不出声音，因此以利以为她喝醉了。）","notes":[]},{"n":14,"t":"以利对她说：「你要醉到几时呢？你不应该喝酒。」","notes":[]},{"n":15,"t":"哈拿回答说：「主啊，不是这样。我是心里愁苦的妇人，清酒浓酒都没有喝，但在耶和华面前倾心吐意。","notes":[]},{"n":16,"t":"不要将婢女看作不正经的女子。我因被人激动，愁苦太多，所以祈求到如今。」","notes":[]},{"n":17,"t":"以利说：「你可以平平安安地回去。愿以色列的神允准你向他所求的！」","notes":[]},{"n":18,"t":"哈拿说：「愿婢女在你眼前蒙恩。」于是妇人走去吃饭，面上再不带愁容了。","notes":[]},{"n":19,"t":"次日清早，他们起来，在耶和华面前敬拜，就回拉玛。到了家里，以利加拿和妻哈拿同房，耶和华顾念哈拿，","notes":[],"heads":["撒母耳出生和奉献"]},{"n":20,"t":"哈拿就怀孕。日期满足，生了一个儿子，给他起名叫撒母耳，说：「这是我从耶和华那里求来的。」","notes":[]},{"n":21,"t":"以利加拿和他全家都上示罗去，要向耶和华献年祭，并还所许的愿。","notes":[]},{"n":22,"t":"哈拿却没有上去，对丈夫说：「等孩子断了奶，我便带他上去朝见耶和华，使他永远住在那里。」","notes":[]},{"n":23,"t":"她丈夫以利加拿说：「就随你的意行吧！可以等儿子断了奶。但愿耶和华应验他的话。」于是妇人在家里乳养儿子，直到断了奶；","notes":[]},{"n":24,"t":"既断了奶，就把孩子带上示罗，到了耶和华的殿；又带了三只公牛，一伊法细面，一皮袋酒。（那时，孩子还小。）","notes":[]},{"n":25,"t":"宰了一只公牛，就领孩子到以利面前。","notes":[]},{"n":26,"t":"妇人说：「主啊，我敢在你面前起誓，从前在你这里站着祈求耶和华的那妇人，就是我。","notes":[]},{"n":27,"t":"我祈求为要得这孩子；耶和华已将我所求的赐给我了。","notes":[]},{"n":28,"t":"所以，我将这孩子归与耶和华，使他终身归与耶和华。」于是在那里敬拜耶和华。","notes":[]}]},"2":{"heading":"哈拿的祷告","verses":[{"n":1,"t":"哈拿祷告说：我的心因耶和华快乐；我的角因耶和华高举。我的口向仇敌张开；我因耶和华的救恩欢欣。","notes":[]},{"n":2,"t":"只有耶和华为圣；除他以外没有可比的，也没有磐石像我们的神。","notes":[]},{"n":3,"t":"人不要夸口说骄傲的话，也不要出狂妄的言语；因耶和华是大有智识的神，人的行为被他衡量。","notes":[]},{"n":4,"t":"勇士的弓都已折断；跌倒的人以力量束腰。","notes":[]},{"n":5,"t":"素来饱足的，反作用人求食；饥饿的，再不饥饿。不生育的，生了七个儿子；多有儿女的，反倒衰微。","notes":[]},{"n":6,"t":"耶和华使人死，也使人活，使人下阴间，也使人往上升。","notes":[]},{"n":7,"t":"他使人贫穷，也使人富足，使人卑微，也使人高贵。","notes":[]},{"n":8,"t":"他从灰尘里抬举贫寒人，从粪堆中提拔穷乏人，使他们与王子同坐，得着荣耀的座位。地的柱子属于耶和华；他将世界立在其上。","notes":[]},{"n":9,"t":"他必保护圣民的脚步，使恶人在黑暗中寂然不动；人都不能靠力量得胜。","notes":[]},{"n":10,"t":"与耶和华争竞的，必被打碎；耶和华必从天上以雷攻击他，必审判地极的人，将力量赐与所立的王，高举受膏者的角。","notes":[]},{"n":11,"t":"以利加拿往拉玛回家去了。那孩子在祭司以利面前事奉耶和华。","notes":[]},{"n":12,"t":"以利的两个儿子是恶人，不认识耶和华。","notes":[],"heads":["以利的两个儿子"]},{"n":13,"t":"这二祭司待百姓是这样的规矩：凡有人献祭，正煮肉的时候，祭司的仆人就来，手拿三齿的叉子，","notes":[]},{"n":14,"t":"将叉子往罐里，或鼎里，或釜里，或锅里一插，插上来的肉，祭司都取了去。凡上到示罗的以色列人，他们都是这样看待。","notes":[]},{"n":15,"t":"又在未烧脂油以前，祭司的仆人就来对献祭的人说：「将肉给祭司，叫他烤吧。他不要煮过的，要生的。」","notes":[]},{"n":16,"t":"献祭的人若说：「必须先烧脂油，然后你可以随意取肉。」仆人就说：「你立时给我，不然我便抢去。」","notes":[]},{"n":17,"t":"如此，这二少年人的罪在耶和华面前甚重了，因为他们藐视耶和华的祭物。","notes":["或译：他们使人厌弃给耶和华献祭"]},{"n":18,"t":"那时，撒母耳还是孩子，穿着细麻布的以弗得，侍立在耶和华面前。","notes":[],"heads":["撒母耳在示罗"]},{"n":19,"t":"他母亲每年为他做一件小外袍，同着丈夫上来献年祭的时候带来给他。","notes":[]},{"n":20,"t":"以利为以利加拿和他的妻祝福，说：「愿耶和华由这妇人再赐你后裔，代替你从耶和华求来的孩子。」他们就回本乡去了。","notes":[]},{"n":21,"t":"耶和华眷顾哈拿，她就怀孕生了三个儿子，两个女儿。那孩子撒母耳在耶和华面前渐渐长大。","notes":[]},{"n":22,"t":"以利年甚老迈，听见他两个儿子待以色列众人的事，又听见他们与会幕门前伺候的妇人苟合，","notes":[],"heads":["以利和他的儿子"]},{"n":23,"t":"他就对他们说：「你们为何行这样的事呢？我从这众百姓听见你们的恶行。","notes":[]},{"n":24,"t":"我儿啊，不可这样！我听见你们的风声不好，你们使耶和华的百姓犯了罪。","notes":[]},{"n":25,"t":"人若得罪人，有士师审判他；人若得罪耶和华，谁能为他祈求呢？」然而他们还是不听父亲的话，因为耶和华想要杀他们。","notes":[]},{"n":26,"t":"孩子撒母耳渐渐长大，耶和华与人越发喜爱他。","notes":[]},{"n":27,"t":"有神人来见以利，对他说：「耶和华如此说：『你祖父在埃及法老家作奴仆的时候，我不是向他们显现吗？","notes":[],"heads":["预言以利家遭祸"]},{"n":28,"t":"在以色列众支派中，我不是拣选人作我的祭司，使他烧香，在我坛上献祭，在我面前穿以弗得，又将以色列人所献的火祭都赐给你父家吗？","notes":[]},{"n":29,"t":"我所吩咐献在我居所的祭物，你们为何践踏？尊重你的儿子过于尊重我，将我民以色列所献美好的祭物肥己呢？』","notes":[]},{"n":30,"t":"因此，耶和华—以色列的神说：『我曾说，你和你父家必永远行在我面前；现在我却说，决不容你们这样行。因为尊重我的，我必重看他；藐视我的，他必被轻视。","notes":[]},{"n":31,"t":"日子必到，我要折断你的膀臂和你父家的膀臂，使你家中没有一个老年人。","notes":[]},{"n":32,"t":"在神使以色列人享福的时候，你必看见我居所的败落。在你家中必永远没有一个老年人。","notes":[]},{"n":33,"t":"我必不从我坛前灭尽你家中的人；那未灭的必使你眼目干瘪、心中忧伤。你家中所生的人都必死在中年。","notes":[]},{"n":34,"t":"你的两个儿子何弗尼、非尼哈所遭遇的事可作你的证据：他们二人必一日同死。","notes":[]},{"n":35,"t":"我要为自己立一个忠心的祭司；他必照我的心意而行。我要为他建立坚固的家；他必永远行在我的受膏者面前。","notes":[]},{"n":36,"t":"你家所剩下的人都必来叩拜他，求块银子，求个饼，说：求你赐我祭司的职分，好叫我得点饼吃。』」","notes":[]}]},"3":{"heading":"耶和华向撒母耳显现","verses":[{"n":1,"t":"童子撒母耳在以利面前事奉耶和华。当那些日子，耶和华的言语稀少，不常有默示。","notes":[]},{"n":2,"t":"一日，以利睡卧在自己的地方；他眼目昏花，看不分明。","notes":[]},{"n":3,"t":"神的灯在神耶和华殿内约柜那里，还没有熄灭，撒母耳已经睡了。","notes":[]},{"n":4,"t":"耶和华呼唤撒母耳。撒母耳说：「我在这里！」","notes":[]},{"n":5,"t":"就跑到以利那里，说：「你呼唤我？我在这里。」以利回答说：「我没有呼唤你，你去睡吧。」他就去睡了。","notes":[]},{"n":6,"t":"耶和华又呼唤撒母耳。撒母耳起来，到以利那里，说：「你呼唤我？我在这里。」以利回答说：「我的儿，我没有呼唤你，你去睡吧。」","notes":[]},{"n":7,"t":"那时撒母耳还未认识耶和华，也未得耶和华的默示。","notes":[]},{"n":8,"t":"耶和华第三次呼唤撒母耳。撒母耳起来，到以利那里，说：「你又呼唤我？我在这里。」以利才明白是耶和华呼唤童子。","notes":[]},{"n":9,"t":"因此以利对撒母耳说：「你仍去睡吧；若再呼唤你，你就说：『耶和华啊，请说，仆人敬听！』」撒母耳就去，仍睡在原处。","notes":[]},{"n":10,"t":"耶和华又来站着，像前三次呼唤说：「撒母耳啊！撒母耳啊！」撒母耳回答说：「请说，仆人敬听！」","notes":[]},{"n":11,"t":"耶和华对撒母耳说：「我在以色列中必行一件事，叫听见的人都必耳鸣。","notes":[]},{"n":12,"t":"我指着以利家所说的话，到了时候，我必始终应验在以利身上。","notes":[]},{"n":13,"t":"我曾告诉他必永远降罚与他的家，因他知道儿子作孽，自招咒诅，却不禁止他们。","notes":[]},{"n":14,"t":"所以我向以利家起誓说：『以利家的罪孽，虽献祭奉礼物，永不能得赎去。』」","notes":[]},{"n":15,"t":"撒母耳睡到天亮，就开了耶和华的殿门，不敢将默示告诉以利。","notes":[]},{"n":16,"t":"以利呼唤撒母耳说：「我儿撒母耳啊！」撒母耳回答说：「我在这里！」","notes":[]},{"n":17,"t":"以利说：「耶和华对你说什么，你不要向我隐瞒；你若将神对你所说的隐瞒一句，愿他重重地降罚与你。」","notes":[]},{"n":18,"t":"撒母耳就把一切话都告诉了以利，并没有隐瞒。以利说：「这是出于耶和华，愿他凭自己的意旨而行。」","notes":[]},{"n":19,"t":"撒母耳长大了，耶和华与他同在，使他所说的话一句都不落空。","notes":[]},{"n":20,"t":"从但到别是巴所有的以色列人都知道耶和华立撒母耳为先知。","notes":[]},{"n":21,"t":"耶和华又在示罗显现；因为耶和华将自己的话默示撒母耳，撒母耳就把这话传遍以色列地。","notes":[]}]},"4":{"heading":"约柜被掳","verses":[{"n":1,"t":"以色列人出去与非利士人打仗，安营在以便以谢；非利士人安营在亚弗。","notes":[]},{"n":2,"t":"非利士人向以色列人摆阵。两军交战的时候，以色列人败在非利士人面前；非利士人在战场上杀了他们的军兵约有四千人。","notes":[]},{"n":3,"t":"百姓回到营里，以色列的长老说：「耶和华今日为何使我们败在非利士人面前呢？我们不如将耶和华的约柜从示罗抬到我们这里来，好在我们中间救我们脱离敌人的手。」","notes":[]},{"n":4,"t":"于是百姓打发人到示罗，从那里将坐在二基路伯上万军之耶和华的约柜抬来。以利的两个儿子何弗尼、非尼哈与神的约柜同来。","notes":[]},{"n":5,"t":"耶和华的约柜到了营中，以色列众人就大声欢呼，地便震动。","notes":[]},{"n":6,"t":"非利士人听见欢呼的声音，就说：「在希伯来人营里大声欢呼，是什么缘故呢？」随后就知道耶和华的约柜到了营中。","notes":[]},{"n":7,"t":"非利士人就惧怕起来，说：「有神到了他们营中」；又说：「我们有祸了！向来不曾有这样的事。","notes":[]},{"n":8,"t":"我们有祸了！谁能救我们脱离这些大能之神的手呢？从前在旷野用各样灾殃击打埃及人的，就是这些神。","notes":[]},{"n":9,"t":"非利士人哪，你们要刚强，要作大丈夫，免得作希伯来人的奴仆，如同他们作你们的奴仆一样。你们要作大丈夫，与他们争战。」","notes":[]},{"n":10,"t":"非利士人和以色列人打仗，以色列人败了，各向各家奔逃，被杀的人甚多，以色列的步兵仆倒了三万。","notes":[]},{"n":11,"t":"神的约柜被掳去，以利的两个儿子何弗尼、非尼哈也都被杀了。","notes":[]},{"n":12,"t":"当日，有一个便雅悯人从阵上逃跑，衣服撕裂，头蒙灰尘，来到示罗。","notes":[],"heads":["以利的死"]},{"n":13,"t":"到了的时候，以利正在道旁坐在自己的位上观望，为神的约柜心里担忧。那人进城报信，合城的人就都呼喊起来。","notes":[]},{"n":14,"t":"以利听见呼喊的声音就问说：「这喧嚷是什么缘故呢？」那人急忙来报信给以利。","notes":[]},{"n":15,"t":"那时以利九十八岁了，眼目发直，不能看见。","notes":[]},{"n":16,"t":"那人对以利说：「我是从阵上来的，今日我从阵上逃回。」以利说：「我儿，事情怎样？」","notes":[]},{"n":17,"t":"报信的回答说：「以色列人在非利士人面前逃跑，民中被杀的甚多！你的两个儿子何弗尼、非尼哈也都死了，并且神的约柜被掳去。」","notes":[]},{"n":18,"t":"他一提神的约柜，以利就从他的位上往后跌倒，在门旁折断颈项而死；因为他年纪老迈，身体沉重。以利作以色列的士师四十年。","notes":[]},{"n":19,"t":"以利的儿妇、非尼哈的妻怀孕将到产期，她听见神的约柜被掳去，公公和丈夫都死了，就猛然疼痛，曲身生产；","notes":[],"heads":["非尼哈遗孀的死"]},{"n":20,"t":"将要死的时候，旁边站着的妇人们对她说：「不要怕！你生了男孩子了。」她却不回答，也不放在心上。","notes":[]},{"n":21,"t":"她给孩子起名叫以迦博，说：「荣耀离开以色列了！」这是因神的约柜被掳去，又因她公公和丈夫都死了。","notes":[]},{"n":22,"t":"她又说：「荣耀离开以色列，因为神的约柜被掳去了。」","notes":[]}]},"5":{"heading":"约柜在非利士人当中","verses":[{"n":1,"t":"非利士人将神的约柜从以便以谢抬到亚实突。","notes":[]},{"n":2,"t":"非利士人将神的约柜抬进大衮庙，放在大衮的旁边。","notes":[]},{"n":3,"t":"次日清早，亚实突人起来，见大衮仆倒在耶和华的约柜前，脸伏于地，就把大衮仍立在原处。","notes":[]},{"n":4,"t":"又次日清早起来，见大衮仆倒在耶和华的约柜前，脸伏于地，并且大衮的头和两手都在门槛上折断，只剩下大衮的残体。（","notes":[]},{"n":5,"t":"因此，大衮的祭司和一切进亚实突、大衮庙的人都不踏大衮庙的门槛，直到今日。）","notes":[]},{"n":6,"t":"耶和华的手重重加在亚实突人身上，败坏他们，使他们生痔疮。亚实突和亚实突的四境都是如此。","notes":[]},{"n":7,"t":"亚实突人见这光景，就说：「以色列神的约柜不可留在我们这里，因为他的手重重加在我们和我们神大衮的身上」；","notes":[]},{"n":8,"t":"就打发人去请非利士的众首领来聚集，问他们说：「我们向以色列神的约柜应当怎样行呢？」他们回答说：「可以将以色列神的约柜运到迦特去。」于是将以色列神的约柜运到那里去。","notes":[]},{"n":9,"t":"运到之后，耶和华的手攻击那城，使那城的人大大惊慌，无论大小都生痔疮。","notes":[]},{"n":10,"t":"他们就把神的约柜送到以革伦。神的约柜到了，以革伦人就喊嚷起来说：「他们将以色列神的约柜运到我们这里，要害我们和我们的众民！」","notes":[]},{"n":11,"t":"于是打发人去请非利士的众首领来，说：「愿你们将以色列神的约柜送回原处，免得害了我们和我们的众民！」原来神的手重重攻击那城，城中的人有因惊慌而死的；","notes":[]},{"n":12,"t":"未曾死的人都生了痔疮。合城呼号，声音上达于天。","notes":[]}]},"6":{"heading":"送回约柜","verses":[{"n":1,"t":"耶和华的约柜在非利士人之地七个月。","notes":[]},{"n":2,"t":"非利士人将祭司和占卜的聚了来，问他们说：「我们向耶和华的约柜应当怎样行？请指示我们用何法将约柜送回原处。」","notes":[]},{"n":3,"t":"他们说：「若要将以色列神的约柜送回去，不可空空地送去，必要给他献赔罪的礼物，然后你们可得痊愈，并知道他的手为何不离开你们。」","notes":[]},{"n":4,"t":"非利士人说：「应当用什么献为赔罪的礼物呢？」他们回答说：「当照非利士首领的数目，用五个金痔疮，五个金老鼠，因为在你们众人和你们首领的身上都是一样的灾。","notes":[]},{"n":5,"t":"所以当制造你们痔疮的像和毁坏你们田地老鼠的像，并要归荣耀给以色列的神，或者他向你们和你们的神，并你们的田地，把手放轻些。","notes":[]},{"n":6,"t":"你们为何硬着心像埃及人和法老一样呢？神在埃及人中间行奇事，埃及人岂不释放以色列人，他们就去了吗？","notes":[]},{"n":7,"t":"现在你们应当造一辆新车，将两只未曾负轭有乳的母牛套在车上，使牛犊回家去，离开母牛。","notes":[]},{"n":8,"t":"把耶和华的约柜放在车上，将所献赔罪的金物装在匣子里，放在柜旁，将柜送去。","notes":[]},{"n":9,"t":"你们要看看：车若直行以色列的境界到伯·示麦去，这大灾就是耶和华降在我们身上的；若不然，便可以知道不是他的手击打我们，是我们偶然遇见的。」","notes":[]},{"n":10,"t":"非利士人就这样行：将两只有乳的母牛套在车上，将牛犊关在家里，","notes":[]},{"n":11,"t":"把耶和华的约柜和装金老鼠并金痔疮像的匣子都放在车上。","notes":[]},{"n":12,"t":"牛直行大道，往伯·示麦去，一面走一面叫，不偏左右。非利士的首领跟在后面，直到伯·示麦的境界。","notes":[]},{"n":13,"t":"伯·示麦人正在平原收割麦子，举目看见约柜，就欢喜了。","notes":[]},{"n":14,"t":"车到了伯·示麦人约书亚的田间，就站住了。在那里有一块大磐石，他们把车劈了，将两只母牛献给耶和华为燔祭。","notes":[]},{"n":15,"t":"利未人将耶和华的约柜和装金物的匣子拿下来，放在大磐石上。当日伯·示麦人将燔祭和平安祭献给耶和华。","notes":[]},{"n":16,"t":"非利士人的五个首领看见，当日就回以革伦去了。","notes":[]},{"n":17,"t":"非利士人献给耶和华作赔罪的金痔疮像，就是这些：一个是为亚实突，一个是为迦萨，一个是为亚实基伦，一个是为迦特，一个是为以革伦。","notes":[]},{"n":18,"t":"金老鼠的数目是照非利士五个首领的城邑，就是坚固的城邑和乡村，以及大磐石。这磐石是放耶和华约柜的，到今日还在伯·示麦人约书亚的田间。","notes":[]},{"n":19,"t":"耶和华因伯·示麦人擅观他的约柜，就击杀了他们七十人；那时有五万人在那里。百姓因耶和华大大击杀他们，就哀哭了。","notes":["原文是七十人加五万人"],"heads":["约柜在基列·耶琳"]},{"n":20,"t":"伯·示麦人说：「谁能在耶和华这圣洁的神面前侍立呢？这约柜可以从我们这里送到谁那里去呢？」","notes":[]},{"n":21,"t":"于是打发人去见基列·耶琳的居民，说：「非利士人将耶和华的约柜送回来了，你们下来将约柜接到你们那里去吧！」","notes":[]}]},"7":{"heading":"撒母耳统治以色列","verses":[{"n":1,"t":"基列·耶琳人就下来，将耶和华的约柜接上去，放在山上亚比拿达的家中，分派他儿子以利亚撒看守耶和华的约柜。","notes":[]},{"n":2,"t":"约柜在基列·耶琳许久。过了二十年，以色列全家都倾向耶和华。","notes":[]},{"n":3,"t":"撒母耳对以色列全家说：「你们若一心归顺耶和华，就要把外邦的神和亚斯她录从你们中间除掉，专心归向耶和华，单单地事奉他。他必救你们脱离非利士人的手。」","notes":[]},{"n":4,"t":"以色列人就除掉诸巴力和亚斯她录，单单地事奉耶和华。","notes":[]},{"n":5,"t":"撒母耳说：「要使以色列众人聚集在米斯巴，我好为你们祷告耶和华。」","notes":[]},{"n":6,"t":"他们就聚集在米斯巴，打水浇在耶和华面前，当日禁食，说：「我们得罪了耶和华。」于是撒母耳在米斯巴审判以色列人。","notes":[]},{"n":7,"t":"非利士人听见以色列人聚集在米斯巴，非利士的首领就上来要攻击以色列人。以色列人听见，就惧怕非利士人。","notes":[]},{"n":8,"t":"以色列人对撒母耳说：「愿你不住地为我们呼求耶和华—我们的神，救我们脱离非利士人的手。」","notes":[]},{"n":9,"t":"撒母耳就把一只吃奶的羊羔献与耶和华作全牲的燔祭，为以色列人呼求耶和华；耶和华就应允他。","notes":[]},{"n":10,"t":"撒母耳正献燔祭的时候，非利士人前来要与以色列人争战。当日，耶和华大发雷声，惊乱非利士人，他们就败在以色列人面前。","notes":[]},{"n":11,"t":"以色列人从米斯巴出来，追赶非利士人，击杀他们，直到伯·甲的下边。","notes":[]},{"n":12,"t":"撒母耳将一块石头立在米斯巴和善的中间，给石头起名叫以便以谢，说：「到如今耶和华都帮助我们。」","notes":[]},{"n":13,"t":"从此，非利士人就被制伏，不敢再入以色列人的境内。撒母耳作士师的时候，耶和华的手攻击非利士人。","notes":[]},{"n":14,"t":"非利士人所取以色列人的城邑，从以革伦直到迦特，都归以色列人了。属这些城的四境，以色列人也从非利士人手下收回。那时以色列人与亚摩利人和好。","notes":[]},{"n":15,"t":"撒母耳平生作以色列的士师。","notes":[]},{"n":16,"t":"他每年巡行到伯特利、吉甲、米斯巴，在这几处审判以色列人。","notes":[]},{"n":17,"t":"随后回到拉玛，因为他的家在那里；也在那里审判以色列人，且为耶和华筑了一座坛。","notes":[]}]},"8":{"heading":"以色列人要求立王","verses":[{"n":1,"t":"撒母耳年纪老迈，就立他儿子作以色列的士师。","notes":[]},{"n":2,"t":"长子名叫约珥，次子名叫亚比亚；他们在别是巴作士师。","notes":[]},{"n":3,"t":"他儿子不行他的道，贪图财利，收受贿赂，屈枉正直。","notes":[]},{"n":4,"t":"以色列的长老都聚集，来到拉玛见撒母耳，","notes":[]},{"n":5,"t":"对他说：「你年纪老迈了，你儿子不行你的道。现在求你为我们立一个王治理我们，像列国一样。」","notes":[]},{"n":6,"t":"撒母耳不喜悦他们说「立一个王治理我们」，他就祷告耶和华。","notes":[]},{"n":7,"t":"耶和华对撒母耳说：「百姓向你说的一切话，你只管依从；因为他们不是厌弃你，乃是厌弃我，不要我作他们的王。","notes":[]},{"n":8,"t":"自从我领他们出埃及到如今，他们常常离弃我，事奉别神。现在他们向你所行的，是照他们素来所行的。","notes":[]},{"n":9,"t":"故此你要依从他们的话，只是当警戒他们，告诉他们将来那王怎样管辖他们。」","notes":[]},{"n":10,"t":"撒母耳将耶和华的话都传给求他立王的百姓，说：","notes":[]},{"n":11,"t":"「管辖你们的王必这样行：他必派你们的儿子为他赶车、跟马，奔走在车前；","notes":[]},{"n":12,"t":"又派他们作千夫长、五十夫长，为他耕种田地，收割庄稼，打造军器和车上的器械；","notes":[]},{"n":13,"t":"必取你们的女儿为他制造香膏，做饭烤饼；","notes":[]},{"n":14,"t":"也必取你们最好的田地、葡萄园、橄榄园赐给他的臣仆。","notes":[]},{"n":15,"t":"你们的粮食和葡萄园所出的，他必取十分之一给他的太监和臣仆；","notes":[]},{"n":16,"t":"又必取你们的仆人婢女，健壮的少年人和你们的驴，供他的差役。","notes":[]},{"n":17,"t":"你们的羊群他必取十分之一，你们也必作他的仆人。","notes":[]},{"n":18,"t":"那时你们必因所选的王哀求耶和华，耶和华却不应允你们。」","notes":[]},{"n":19,"t":"百姓竟不肯听撒母耳的话，说：「不然！我们定要一个王治理我们，","notes":[]},{"n":20,"t":"使我们像列国一样，有王治理我们，统领我们，为我们争战。」","notes":[]},{"n":21,"t":"撒母耳听见百姓这一切话，就将这话陈明在耶和华面前。","notes":[]},{"n":22,"t":"耶和华对撒母耳说：「你只管依从他们的话，为他们立王。」撒母耳对以色列人说：「你们各归各城去吧！」","notes":[]}]},"9":{"heading":"扫罗见撒母耳","verses":[{"n":1,"t":"有一个便雅悯人，名叫基士，是便雅悯人亚斐亚的玄孙，比歌拉的曾孙，洗罗的孙子，亚别的儿子，是个大能的勇士。","notes":["或译：大财主"]},{"n":2,"t":"他有一个儿子，名叫扫罗，又健壮、又俊美，在以色列人中没有一个能比他的；身体比众民高过一头。","notes":[]},{"n":3,"t":"扫罗的父亲基士丢了几头驴，他就吩咐儿子扫罗说：「你带一个仆人去寻找驴。」","notes":[]},{"n":4,"t":"扫罗就走过以法莲山地，又过沙利沙地，都没有找着；又过沙琳地，驴也不在那里；又过便雅悯地，还没有找着。","notes":[]},{"n":5,"t":"到了苏弗地，扫罗对跟随他的仆人说：「我们不如回去，恐怕我父亲不为驴挂心，反为我们担忧。」","notes":[]},{"n":6,"t":"仆人说：「这城里有一位神人，是众人所尊重的，凡他所说的全都应验。我们不如往他那里去，或者他能将我们当走的路指示我们。」","notes":[]},{"n":7,"t":"扫罗对仆人说：「我们若去，有什么可以送那人呢？我们囊中的食物都吃尽了，也没有礼物可以送那神人，我们还有什么没有？」","notes":[]},{"n":8,"t":"仆人回答扫罗说：「我手里有银子一舍客勒的四分之一，可以送那神人，请他指示我们当走的路。」（","notes":[]},{"n":9,"t":"从前以色列中，若有人去问神，就说：「我们问先见去吧！」现在称为「先知」的，从前称为「先见」。）","notes":[]},{"n":10,"t":"扫罗对仆人说：「你说的是，我们可以去。」于是他们往神人所住的城里去了。","notes":[]},{"n":11,"t":"他们上坡要进城，就遇见几个少年女子出来打水，问她们说：「先见在这里没有？」","notes":[]},{"n":12,"t":"女子回答说：「在这里，他在你们前面。快去吧！他今日正到城里，因为今日百姓要在邱坛献祭。","notes":[]},{"n":13,"t":"在他还没有上邱坛吃祭物之先，你们一进城必遇见他；因他未到，百姓不能吃，必等他先祝祭，然后请的客才吃。现在你们上去，这时候必遇见他。」","notes":[]},{"n":14,"t":"二人就上去；将进城的时候，撒母耳正迎着他们来，要上邱坛去。","notes":[]},{"n":15,"t":"扫罗未到的前一日，耶和华已经指示撒母耳说：","notes":[]},{"n":16,"t":"「明日这时候，我必使一个人从便雅悯地到你这里来，你要膏他作我民以色列的君。他必救我民脱离非利士人的手；因我民的哀声上达于我，我就眷顾他们。」","notes":[]},{"n":17,"t":"撒母耳看见扫罗的时候，耶和华对他说：「看哪，这人就是我对你所说的，他必治理我的民。」","notes":[]},{"n":18,"t":"扫罗在城门里走到撒母耳跟前，说：「请告诉我，先见的寓所在哪里？」","notes":[]},{"n":19,"t":"撒母耳回答说：「我就是先见。你在我前面上邱坛去，因为你们今日必与我同席；明日早晨我送你去，将你心里的事都告诉你。","notes":[]},{"n":20,"t":"至于你前三日所丢的那几头驴，你心里不必挂念，已经找着了。以色列众人所仰慕的是谁呢？不是仰慕你和你父的全家吗？」","notes":[]},{"n":21,"t":"扫罗说：「我不是以色列支派中至小的便雅悯人吗？我家不是便雅悯支派中至小的家吗？你为何对我说这样的话呢？」","notes":[]},{"n":22,"t":"撒母耳领扫罗和他仆人进了客堂，使他们在请来的客中坐首位；客约有三十个人。","notes":[]},{"n":23,"t":"撒母耳对厨役说：「我交给你收存的那一分祭肉现在可以拿来。」","notes":[]},{"n":24,"t":"厨役就把收存的腿拿来，摆在扫罗面前，撒母耳说：「这是所留下的，放在你面前。吃吧！因我请百姓的时候，特意为你存留这肉到此时。」当日，扫罗就与撒母耳同席。","notes":[]},{"n":25,"t":"众人从邱坛下来进城，撒母耳和扫罗在房顶上说话。","notes":[],"heads":["撒母耳膏扫罗作王"]},{"n":26,"t":"次日清早起来，黎明的时候，扫罗在房顶上。撒母耳呼叫他说：「起来吧，我好送你回去。」扫罗就起来，和撒母耳一同出去。","notes":[]},{"n":27,"t":"二人下到城角，撒母耳对扫罗说：「要吩咐仆人先走（仆人就先走了）；你且站在这里，等我将神的话传与你听。」","notes":[]}]},"10":{"heading":"抽签得扫罗为王","verses":[{"n":1,"t":"撒母耳拿瓶膏油倒在扫罗的头上，与他亲嘴，说：「这不是耶和华膏你作他产业的君吗？","notes":[]},{"n":2,"t":"你今日与我离别之后，在便雅悯境内的泄撒，靠近拉结的坟墓，要遇见两个人。他们必对你说：『你去找的那几头驴已经找着了。现在你父亲不为驴挂心，反为你担忧，说：我为儿子怎么才好呢？』","notes":[]},{"n":3,"t":"你从那里往前行，到了他泊的橡树那里，必遇见三个往伯特利去拜神的人：一个带着三只山羊羔，一个带着三个饼，一个带着一皮袋酒。","notes":[]},{"n":4,"t":"他们必问你安，给你两个饼，你就从他们手中接过来。","notes":[]},{"n":5,"t":"此后你到神的山，在那里有非利士人的防兵。你到了城的时候，必遇见一班先知从邱坛下来，前面有鼓瑟的、击鼓的、吹笛的、弹琴的，他们都受感说话。","notes":[]},{"n":6,"t":"耶和华的灵必大大感动你，你就与他们一同受感说话；你要变为新人。","notes":[]},{"n":7,"t":"这兆头临到你，你就可以趁时而做，因为神与你同在。","notes":[]},{"n":8,"t":"你当在我以先下到吉甲，我也必下到那里献燔祭和平安祭。你要等候七日，等我到了那里，指示你当行的事。」","notes":[]},{"n":9,"t":"扫罗转身离别撒母耳，神就赐他一个新心。当日这一切兆头都应验了。","notes":[]},{"n":10,"t":"扫罗到了那山，有一班先知遇见他，神的灵大大感动他，他就在先知中受感说话。","notes":[]},{"n":11,"t":"素来认识扫罗的，看见他和先知一同受感说话，就彼此说：「基士的儿子遇见什么了？扫罗也列在先知中吗？」","notes":[]},{"n":12,"t":"那地方有一个人说：「这些人的父亲是谁呢？」此后有句俗语说：「扫罗也列在先知中吗？」","notes":[]},{"n":13,"t":"扫罗受感说话已毕，就上邱坛去了。","notes":[]},{"n":14,"t":"扫罗的叔叔问扫罗和他仆人说：「你们往哪里去了？」回答说：「找驴去了。我们见没有驴，就到了撒母耳那里。」","notes":[]},{"n":15,"t":"扫罗的叔叔说：「请将撒母耳向你们所说的话告诉我。」","notes":[]},{"n":16,"t":"扫罗对他叔叔说：「他明明地告诉我们驴已经找着了。」至于撒母耳所说的国事，扫罗却没有告诉叔叔。","notes":[]},{"n":17,"t":"撒母耳将百姓招聚到米斯巴耶和华那里，","notes":[]},{"n":18,"t":"对他们说：「耶和华—以色列的神如此说：『我领你们以色列人出埃及，救你们脱离埃及人的手，又救你们脱离欺压你们各国之人的手。』","notes":[]},{"n":19,"t":"你们今日却厌弃了救你们脱离一切灾难的神，说：『求你立一个王治理我们。』现在你们应当按着支派、宗族都站在耶和华面前。」","notes":[]},{"n":20,"t":"于是，撒母耳使以色列众支派近前来掣签，就掣出便雅悯支派来；","notes":[]},{"n":21,"t":"又使便雅悯支派按着宗族近前来，就掣出玛特利族，从其中又掣出基士的儿子扫罗。众人寻找他却寻不着，","notes":[]},{"n":22,"t":"就问耶和华说：「那人到这里来了没有？」耶和华说：「他藏在器具中了。」","notes":[]},{"n":23,"t":"众人就跑去从那里领出他来。他站在百姓中间，身体比众民高过一头。","notes":[]},{"n":24,"t":"撒母耳对众民说：「你们看耶和华所拣选的人，众民中有可比他的吗？」众民就大声欢呼说：「愿王万岁！」","notes":[]},{"n":25,"t":"撒母耳将国法对百姓说明，又记在书上，放在耶和华面前，然后遣散众民，各回各家去了。","notes":[]},{"n":26,"t":"扫罗往基比亚回家去，有神感动的一群人跟随他。","notes":[]},{"n":27,"t":"但有些匪徒说：「这人怎能救我们呢？」就藐视他，没有送他礼物；扫罗却不理会。","notes":[]}]},"11":{"heading":"扫罗击败亚扪人","verses":[{"n":1,"t":"亚扪人的王拿辖上来，对着基列·雅比安营。雅比众人对拿辖说：「你与我们立约，我们就服事你。」","notes":[]},{"n":2,"t":"亚扪人拿辖说：「你们若由我剜出你们各人的右眼，以此凌辱以色列众人，我就与你们立约。」","notes":[]},{"n":3,"t":"雅比的长老对他说：「求你宽容我们七日，等我们打发人往以色列的全境去；若没有人救我们，我们就出来归顺你。」","notes":[]},{"n":4,"t":"使者到了扫罗住的基比亚，将这话说给百姓听，百姓就都放声而哭。","notes":[]},{"n":5,"t":"扫罗正从田间赶牛回来，问说：「百姓为什么哭呢？」众人将雅比人的话告诉他。","notes":[]},{"n":6,"t":"扫罗听见这话，就被神的灵大大感动，甚是发怒。","notes":[]},{"n":7,"t":"他将一对牛切成块子，托付使者传送以色列的全境，说：「凡不出来跟随扫罗和撒母耳的，也必这样切开他的牛。」于是耶和华使百姓惧怕，他们就都出来，如同一人。","notes":[]},{"n":8,"t":"扫罗在比色数点他们：以色列人有三十万，犹大人有三万。","notes":[]},{"n":9,"t":"众人对那使者说：「你们要回复基列·雅比人说，明日太阳近午的时候，你们必得解救。」使者回去告诉雅比人，他们就欢喜了。","notes":[]},{"n":10,"t":"于是雅比人对亚扪人说：「明日我们出来归顺你们，你们可以随意待我们。」","notes":[]},{"n":11,"t":"第二日，扫罗将百姓分为三队，在晨更的时候入了亚扪人的营，击杀他们直到太阳近午，剩下的人都逃散，没有二人同在一处的。","notes":[]},{"n":12,"t":"百姓对撒母耳说：「那说『扫罗岂能管理我们』的是谁呢？可以将他交出来，我们好杀死他。」","notes":[]},{"n":13,"t":"扫罗说：「今日耶和华在以色列中施行拯救，所以不可杀人。」","notes":[]},{"n":14,"t":"撒母耳对百姓说：「我们要往吉甲去，在那里立国。」","notes":[]},{"n":15,"t":"众百姓就到了吉甲那里，在耶和华面前立扫罗为王，又在耶和华面前献平安祭。扫罗和以色列众人大大欢喜。","notes":[]}]},"12":{"heading":"撒母耳临别赠言","verses":[{"n":1,"t":"撒母耳对以色列众人说：「你们向我所求的，我已应允了，为你们立了一个王；","notes":[]},{"n":2,"t":"现在有这王在你们前面行。我已年老发白，我的儿子都在你们这里。我从幼年直到今日都在你们前面行。","notes":[]},{"n":3,"t":"我在这里，你们要在耶和华和他的受膏者面前给我作见证。我夺过谁的牛，抢过谁的驴，欺负过谁，虐待过谁，从谁手里受过贿赂因而眼瞎呢？若有，我必偿还。」","notes":[]},{"n":4,"t":"众人说：「你未曾欺负我们，虐待我们，也未曾从谁手里受过什么。」","notes":[]},{"n":5,"t":"撒母耳对他们说：「你们在我手里没有找着什么，有耶和华和他的受膏者今日为证。」他们说：「愿他为证。」","notes":[]},{"n":6,"t":"撒母耳对百姓说：「从前立摩西、亚伦，又领你们列祖出埃及地的是耶和华。","notes":[]},{"n":7,"t":"现在你们要站住，等我在耶和华面前对你们讲论耶和华向你们和你们列祖所行一切公义的事。","notes":[]},{"n":8,"t":"从前雅各到了埃及，后来你们列祖呼求耶和华，耶和华就差遣摩西、亚伦领你们列祖出埃及，使他们在这地方居住。","notes":[]},{"n":9,"t":"他们却忘记耶和华—他们的神，他就把他们付与夏琐将军西西拉的手里，和非利士人并摩押王的手里。于是这些人常来攻击他们。","notes":[]},{"n":10,"t":"他们就呼求耶和华说：『我们离弃耶和华，事奉巴力和亚斯她录，是有罪了。现在求你救我们脱离仇敌的手，我们必事奉你。』","notes":[]},{"n":11,"t":"耶和华就差遣耶路·巴力、比但、耶弗他、撒母耳救你们脱离四围仇敌的手，你们才安然居住。","notes":[]},{"n":12,"t":"你们见亚扪人的王拿辖来攻击你们，就对我说：『我们定要一个王治理我们。』其实耶和华—你们的神是你们的王。","notes":[]},{"n":13,"t":"现在，你们所求所选的王在这里。看哪，耶和华已经为你们立王了。","notes":[]},{"n":14,"t":"你们若敬畏耶和华，事奉他，听从他的话，不违背他的命令，你们和治理你们的王也都顺从耶和华—你们的神就好了。","notes":[]},{"n":15,"t":"倘若不听从耶和华的话，违背他的命令，耶和华的手必攻击你们，像从前攻击你们列祖一样。","notes":[]},{"n":16,"t":"现在你们要站住，看耶和华在你们眼前要行一件大事。","notes":[]},{"n":17,"t":"这不是割麦子的时候吗？我求告耶和华，他必打雷降雨，使你们又知道又看出，你们求立王的事是在耶和华面前犯大罪了。」","notes":[]},{"n":18,"t":"于是撒母耳求告耶和华，耶和华就在这日打雷降雨，众民便甚惧怕耶和华和撒母耳。","notes":[]},{"n":19,"t":"众民对撒母耳说：「求你为仆人们祷告耶和华—你的神，免得我们死亡，因为我们求立王的事正是罪上加罪了。」","notes":[]},{"n":20,"t":"撒母耳对百姓说：「不要惧怕！你们虽然行了这恶，却不要偏离耶和华，只要尽心事奉他。","notes":[]},{"n":21,"t":"若偏离耶和华去顺从那不能救人的虚神是无益的。","notes":[]},{"n":22,"t":"耶和华既喜悦选你们作他的子民，就必因他的大名不撇弃你们。","notes":[]},{"n":23,"t":"至于我，断不停止为你们祷告，以致得罪耶和华。我必以善道正路指教你们。","notes":[]},{"n":24,"t":"只要你们敬畏耶和华，诚诚实实地尽心事奉他，想念他向你们所行的事何等大。","notes":[]},{"n":25,"t":"你们若仍然作恶，你们和你们的王必一同灭亡。」","notes":[]}]},"13":{"heading":"与非利士人争战","verses":[{"n":1,"t":"扫罗登基年四十岁；作以色列王二年的时候，","notes":[]},{"n":2,"t":"就从以色列中拣选了三千人：二千跟随扫罗在密抹和伯特利山，一千跟随约拿单在便雅悯的基比亚；其余的人扫罗都打发各回各家去了。","notes":[]},{"n":3,"t":"约拿单攻击在迦巴的非利士人的防营，非利士人听见了。扫罗就在遍地吹角，意思说，要使希伯来人听见。","notes":[]},{"n":4,"t":"以色列众人听见扫罗攻击非利士人的防营，又听见以色列人为非利士人所憎恶，就跟随扫罗聚集在吉甲。","notes":[]},{"n":5,"t":"非利士人聚集，要与以色列人争战，有车三万辆，马兵六千，步兵像海边的沙那样多，就上来在伯·亚文东边的密抹安营。","notes":[]},{"n":6,"t":"以色列百姓见自己危急窘迫，就藏在山洞、丛林、石穴、隐密处，和坑中。","notes":[]},{"n":7,"t":"有些希伯来人过了约旦河，逃到迦得和基列地。扫罗还是在吉甲，百姓都战战兢兢地跟随他。","notes":[]},{"n":8,"t":"扫罗照着撒母耳所定的日期等了七日。撒母耳还没有来到吉甲，百姓也离开扫罗散去了。","notes":[]},{"n":9,"t":"扫罗说：「把燔祭和平安祭带到我这里来。」扫罗就献上燔祭。","notes":[]},{"n":10,"t":"刚献完燔祭，撒母耳就到了。扫罗出去迎接他，要问他好。","notes":[]},{"n":11,"t":"撒母耳说：「你做的是什么事呢？」扫罗说：「因为我见百姓离开我散去，你也不照所定的日期来到，而且非利士人聚集在密抹。","notes":[]},{"n":12,"t":"所以我心里说：恐怕我没有祷告耶和华。非利士人下到吉甲攻击我，我就勉强献上燔祭。」","notes":[]},{"n":13,"t":"撒母耳对扫罗说：「你做了糊涂事了，没有遵守耶和华—你神所吩咐你的命令。若遵守，耶和华必在以色列中坚立你的王位，直到永远。","notes":[]},{"n":14,"t":"现在你的王位必不长久。耶和华已经寻着一个合他心意的人，立他作百姓的君，因为你没有遵守耶和华所吩咐你的。」","notes":[]},{"n":15,"t":"撒母耳就起来，从吉甲上到便雅悯的基比亚。 扫罗数点跟随他的，约有六百人。","notes":[]},{"n":16,"t":"扫罗和他儿子约拿单，并跟随他们的人，都住在便雅悯的迦巴；但非利士人安营在密抹。","notes":[]},{"n":17,"t":"有掠兵从非利士营中出来，分为三队：一队往俄弗拉向书亚地去，","notes":[]},{"n":18,"t":"一队往伯·和仑去，一队往洗波音谷对面的地境向旷野去。","notes":[]},{"n":19,"t":"那时，以色列全地没有一个铁匠；因为非利士人说，恐怕希伯来人制造刀枪。","notes":[]},{"n":20,"t":"以色列人要磨锄、犁、斧、铲，就下到非利士人那里去磨。","notes":[]},{"n":21,"t":"但有锉可以锉铲、犁、三齿叉、斧子，并赶牛锥。","notes":[]},{"n":22,"t":"所以到了争战的日子，跟随扫罗和约拿单的人没有一个手里有刀有枪的，惟独扫罗和他儿子约拿单有。","notes":[]},{"n":23,"t":"非利士人的一队防兵到了密抹的隘口。","notes":[]}]},"14":{"heading":"约拿单的勇敢战绩","verses":[{"n":1,"t":"有一日，扫罗的儿子约拿单对拿他兵器的少年人说：「我们不如过到那边，到非利士人的防营那里去。」但他没有告诉父亲。","notes":[]},{"n":2,"t":"扫罗在基比亚的尽边，坐在米矶仑的石榴树下，跟随他的约有六百人。","notes":[]},{"n":3,"t":"在那里有亚希突的儿子亚希亚，穿着以弗得。（亚希突是以迦博的哥哥，非尼哈的儿子，以利的孙子。以利从前在示罗作耶和华的祭司。）约拿单去了，百姓却不知道。","notes":[]},{"n":4,"t":"约拿单要从隘口过到非利士防营那里去。这隘口两边各有一个山峰：一名播薛，一名西尼；","notes":[]},{"n":5,"t":"一峰向北，与密抹相对，一峰向南，与迦巴相对。","notes":[]},{"n":6,"t":"约拿单对拿兵器的少年人说：「我们不如过到未受割礼人的防营那里去，或者耶和华为我们施展能力；因为耶和华使人得胜，不在乎人多人少。」","notes":[]},{"n":7,"t":"拿兵器的对他说：「随你的心意行吧。你可以上去，我必跟随你，与你同心。」","notes":[]},{"n":8,"t":"约拿单说：「我们要过到那些人那里去，使他们看见我们。","notes":[]},{"n":9,"t":"他们若对我们说：『你们站住，等我们到你们那里去』，我们就站住，不上他们那里去。","notes":[]},{"n":10,"t":"他们若说：『你们上到我们这里来』，这话就是我们的证据；我们便上去，因为耶和华将他们交在我们手里了。」","notes":[]},{"n":11,"t":"二人就使非利士的防兵看见。非利士人说：「希伯来人从所藏的洞穴里出来了！」","notes":[]},{"n":12,"t":"防兵对约拿单和拿兵器的人说：「你们上到这里来，我们有一件事指示你们。」约拿单就对拿兵器的人说：「你跟随我上去，因为耶和华将他们交在以色列人手里了。」","notes":[]},{"n":13,"t":"约拿单就爬上去，拿兵器的人跟随他。约拿单杀倒非利士人，拿兵器的人也随着杀他们。","notes":[]},{"n":14,"t":"约拿单和拿兵器的人起头所杀的约有二十人，都在一亩地的半犁沟之内。","notes":[]},{"n":15,"t":"于是在营中、在田野、在众民内都有战兢，防兵和掠兵也都战兢，地也震动，战兢之势甚大。","notes":[]},{"n":16,"t":"在便雅悯的基比亚，扫罗的守望兵看见非利士的军众溃散，四围乱窜。","notes":[],"heads":["非利士人败退"]},{"n":17,"t":"扫罗就对跟随他的民说：「你们查点查点，看从我们这里出去的是谁？」他们一查点，就知道约拿单和拿兵器的人没有在这里。","notes":[]},{"n":18,"t":"那时神的约柜在以色列人那里。扫罗对亚希亚说：「你将神的约柜运了来。」","notes":[]},{"n":19,"t":"扫罗正与祭司说话的时候，非利士营中的喧嚷越发大了；扫罗就对祭司说：「停手吧！」","notes":[]},{"n":20,"t":"扫罗和跟随他的人都聚集，来到战场，看见非利士人用刀互相击杀，大大惶乱。","notes":[]},{"n":21,"t":"从前由四方来跟随非利士军的希伯来人现在也转过来，帮助跟随扫罗和约拿单的以色列人了。","notes":[]},{"n":22,"t":"那藏在以法莲山地的以色列人听说非利士人逃跑，就出来紧紧地追杀他们。","notes":[]},{"n":23,"t":"那日，耶和华使以色列人得胜，一直战到伯·亚文。","notes":[]},{"n":24,"t":"扫罗叫百姓起誓说，凡不等到晚上向敌人报完了仇吃什么的，必受咒诅。因此这日百姓没有吃什么，就极其困惫。","notes":[],"heads":["战后发生的事件"]},{"n":25,"t":"众民进入树林，见有蜜在地上。","notes":[]},{"n":26,"t":"他们进了树林，见有蜜流下来，却没有人敢用手取蜜入口，因为他们怕那誓言。","notes":[]},{"n":27,"t":"约拿单没有听见他父亲叫百姓起誓，所以伸手中的杖，用杖头蘸在蜂房里，转手送入口内，眼睛就明亮了。","notes":[]},{"n":28,"t":"百姓中有一人对他说：「你父亲曾叫百姓严严地起誓说，今日吃什么的，必受咒诅；因此百姓就疲乏了。」","notes":[]},{"n":29,"t":"约拿单说：「我父亲连累你们了。你看，我尝了这一点蜜，眼睛就明亮了。","notes":[]},{"n":30,"t":"今日百姓若任意吃了从仇敌所夺的物，击杀的非利士人岂不更多吗？」","notes":[]},{"n":31,"t":"这日，以色列人击杀非利士人，从密抹直到亚雅仑。百姓甚是疲乏，","notes":[]},{"n":32,"t":"就急忙将所夺的牛羊和牛犊宰于地上，肉还带血就吃了。","notes":[]},{"n":33,"t":"有人告诉扫罗说：「百姓吃带血的肉，得罪耶和华了。」扫罗说：「你们有罪了，今日要将大石头滚到我这里来。」","notes":[]},{"n":34,"t":"扫罗又说：「你们散在百姓中，对他们说，你们各人将牛羊牵到我这里来宰了吃，不可吃带血的肉得罪耶和华。」这夜，百姓就把牛羊牵到那里宰了。","notes":[]},{"n":35,"t":"扫罗为耶和华筑了一座坛，这是他初次为耶和华筑的坛。","notes":[]},{"n":36,"t":"扫罗说：「我们不如夜里下去追赶非利士人，抢掠他们，直到天亮，不留他们一人。」众民说：「你看怎样好就去行吧！」祭司说：「我们先当亲近神。」","notes":[]},{"n":37,"t":"扫罗求问神说：「我下去追赶非利士人可以不可以？你将他们交在以色列人手里不交？」这日神没有回答他。","notes":[]},{"n":38,"t":"扫罗说：「你们百姓中的长老都上这里来，查明今日是谁犯了罪。","notes":[]},{"n":39,"t":"我指着救以色列—永生的耶和华起誓，就是我儿子约拿单犯了罪，他也必死。」但百姓中无一人回答他。","notes":[]},{"n":40,"t":"扫罗就对以色列众人说：「你们站在一边，我与我儿子约拿单也站在一边。」百姓对扫罗说：「你看怎样好就去行吧！」","notes":[]},{"n":41,"t":"扫罗祷告耶和华—以色列的神说：「求你指示实情。」于是掣签掣出扫罗和约拿单来；百姓尽都无事。","notes":[]},{"n":42,"t":"扫罗说：「你们再掣签，看是我，是我儿子约拿单」，就掣出约拿单来。","notes":[]},{"n":43,"t":"扫罗对约拿单说：「你告诉我，你做了什么事？」约拿单说：「我实在以手里的杖，用杖头蘸了一点蜜尝了一尝。这样我就死吗？」","notes":["或译：吧！"]},{"n":44,"t":"扫罗说：「约拿单哪，你定要死！若不然，愿神重重地降罚与我。」","notes":[]},{"n":45,"t":"百姓对扫罗说：「约拿单在以色列人中这样大行拯救，岂可使他死呢？断乎不可！我们指着永生的耶和华起誓，连他的一根头发也不可落地，因为他今日与神一同做事。」于是百姓救约拿单免了死亡。","notes":[]},{"n":46,"t":"扫罗回去，不追赶非利士人；非利士人也回本地去了。","notes":[]},{"n":47,"t":"扫罗执掌以色列的国权，常常攻击他四围的一切仇敌，就是摩押人、亚扪人、以东人，和琐巴诸王，并非利士人。他无论往何处去，都打败仇敌。","notes":[],"heads":["扫罗的王权和家眷"]},{"n":48,"t":"扫罗奋勇攻击亚玛力人，救了以色列人脱离抢掠他们之人的手。","notes":[]},{"n":49,"t":"扫罗的儿子是约拿单、亦施韦、麦基舒亚。他的两个女儿：长女名米拉，次女名米甲。","notes":[]},{"n":50,"t":"扫罗的妻名叫亚希暖，是亚希玛斯的女儿。扫罗的元帅名叫押尼珥，是尼珥的儿子；尼珥是扫罗的叔叔。","notes":[]},{"n":51,"t":"扫罗的父亲基士，押尼珥的父亲尼珥，都是亚别的儿子。","notes":[]},{"n":52,"t":"扫罗平生常与非利士人大大争战。扫罗遇见有能力的人或勇士，都招募了来跟随他。","notes":[]}]},"15":{"heading":"与亚玛力人争战","verses":[{"n":1,"t":"撒母耳对扫罗说：「耶和华差遣我膏你为王，治理他的百姓以色列；所以你当听从耶和华的话。","notes":[]},{"n":2,"t":"万军之耶和华如此说：『以色列人出埃及的时候，在路上亚玛力人怎样待他们，怎样抵挡他们，我都没忘。","notes":[]},{"n":3,"t":"现在你要去击打亚玛力人，灭尽他们所有的，不可怜惜他们，将男女、孩童、吃奶的，并牛、羊、骆驼，和驴尽行杀死。』」","notes":[]},{"n":4,"t":"于是扫罗招聚百姓在提拉因，数点他们，共有步兵二十万，另有犹大人一万。","notes":[]},{"n":5,"t":"扫罗到了亚玛力的京城，在谷中设下埋伏。","notes":[]},{"n":6,"t":"扫罗对基尼人说：「你们离开亚玛力人下去吧，恐怕我将你们和亚玛力人一同杀灭；因为以色列人出埃及的时候，你们曾恩待他们。」于是基尼人离开亚玛力人去了。","notes":[]},{"n":7,"t":"扫罗击打亚玛力人，从哈腓拉直到埃及前的书珥，","notes":[]},{"n":8,"t":"生擒了亚玛力王亚甲，用刀杀尽亚玛力的众民。","notes":[]},{"n":9,"t":"扫罗和百姓却怜惜亚甲，也爱惜上好的牛、羊、牛犊、羊羔，并一切美物，不肯灭绝。凡下贱瘦弱的，尽都杀了。","notes":[]},{"n":10,"t":"耶和华的话临到撒母耳说：","notes":[],"heads":["扫罗被废"]},{"n":11,"t":"「我立扫罗为王，我后悔了；因为他转去不跟从我，不遵守我的命令。」撒母耳便甚忧愁，终夜哀求耶和华。","notes":[]},{"n":12,"t":"撒母耳清早起来，迎接扫罗。有人告诉撒母耳说：「扫罗到了迦密，在那里立了纪念碑，又转身下到吉甲。」","notes":[]},{"n":13,"t":"撒母耳到了扫罗那里，扫罗对他说：「愿耶和华赐福与你，耶和华的命令我已遵守了。」","notes":[]},{"n":14,"t":"撒母耳说：「我耳中听见有羊叫、牛鸣，是从哪里来的呢？」","notes":[]},{"n":15,"t":"扫罗说：「这是百姓从亚玛力人那里带来的；因为他们爱惜上好的牛羊，要献与耶和华—你的神；其余的，我们都灭尽了。」","notes":[]},{"n":16,"t":"撒母耳对扫罗说：「你住口吧！等我将耶和华昨夜向我所说的话告诉你。」扫罗说：「请讲。」","notes":[]},{"n":17,"t":"撒母耳对扫罗说：「从前你虽然以自己为小，岂不是被立为以色列支派的元首吗？耶和华膏你作以色列的王。","notes":[]},{"n":18,"t":"耶和华差遣你，吩咐你说，你去击打那些犯罪的亚玛力人，将他们灭绝净尽。","notes":[]},{"n":19,"t":"你为何没有听从耶和华的命令，急忙掳掠财物，行耶和华眼中看为恶的事呢？」","notes":[]},{"n":20,"t":"扫罗对撒母耳说：「我实在听从了耶和华的命令，行了耶和华所差遣我行的路，擒了亚玛力王亚甲来，灭尽了亚玛力人。","notes":[]},{"n":21,"t":"百姓却在所当灭的物中，取了最好的牛羊，要在吉甲献与耶和华—你的神。」","notes":[]},{"n":22,"t":"撒母耳说：耶和华喜悦燔祭和平安祭，岂如喜悦人听从他的话呢？听命胜于献祭；顺从胜于公羊的脂油。","notes":[]},{"n":23,"t":"悖逆的罪与行邪术的罪相等；顽梗的罪与拜虚神和偶像的罪相同。你既厌弃耶和华的命令，耶和华也厌弃你作王。","notes":[]},{"n":24,"t":"扫罗对撒母耳说：「我有罪了，我因惧怕百姓，听从他们的话，就违背了耶和华的命令和你的言语。","notes":[],"heads":["扫罗认罪"]},{"n":25,"t":"现在求你赦免我的罪，同我回去，我好敬拜耶和华。」","notes":[]},{"n":26,"t":"撒母耳对扫罗说：「我不同你回去；因为你厌弃耶和华的命令，耶和华也厌弃你作以色列的王。」","notes":[]},{"n":27,"t":"撒母耳转身要走，扫罗就扯住他外袍的衣襟，衣襟就撕断了。","notes":[]},{"n":28,"t":"撒母耳对他说：「如此，今日耶和华使以色列国与你断绝，将这国赐与比你更好的人。","notes":[]},{"n":29,"t":"以色列的大能者必不致说谎，也不致后悔；因为他迥非世人，决不后悔。」","notes":[]},{"n":30,"t":"扫罗说：「我有罪了，虽然如此，求你在我百姓的长老和以色列人面前抬举我，同我回去，我好敬拜耶和华—你的神。」","notes":[]},{"n":31,"t":"于是撒母耳转身跟随扫罗回去，扫罗就敬拜耶和华。","notes":[]},{"n":32,"t":"撒母耳说：「要把亚玛力王亚甲带到我这里来。」亚甲就欢欢喜喜地来到他面前，心里说，死亡的苦难必定过去了。","notes":[]},{"n":33,"t":"撒母耳说：「你既用刀使妇人丧子，这样，你母亲在妇人中也必丧子。」于是，撒母耳在吉甲耶和华面前将亚甲杀死。","notes":[]},{"n":34,"t":"撒母耳回了拉玛。扫罗上他所住的基比亚，回自己的家去了。","notes":[]},{"n":35,"t":"撒母耳直到死的日子，再没有见扫罗；但撒母耳为扫罗悲伤，是因耶和华后悔立他为以色列的王。","notes":[]}]},"16":{"heading":"大卫被膏立为王","verses":[{"n":1,"t":"耶和华对撒母耳说：「我既厌弃扫罗作以色列的王，你为他悲伤要到几时呢？你将膏油盛满了角，我差遣你往伯利恒人耶西那里去；因为我在他众子之内，预定一个作王的。」","notes":[]},{"n":2,"t":"撒母耳说：「我怎能去呢？扫罗若听见，必要杀我。」耶和华说：「你可以带一只牛犊去，就说：『我来是要向耶和华献祭。』","notes":[]},{"n":3,"t":"你要请耶西来吃祭肉，我就指示你所当行的事。我所指给你的人，你要膏他。」","notes":[]},{"n":4,"t":"撒母耳就照耶和华的话去行。到了伯利恒，那城里的长老都战战兢兢地出来迎接他，问他说：「你是为平安来的吗？」","notes":[]},{"n":5,"t":"他说：「为平安来的，我是给耶和华献祭。你们当自洁，来与我同吃祭肉。」撒母耳就使耶西和他众子自洁，请他们来吃祭肉。","notes":[]},{"n":6,"t":"他们来的时候，撒母耳看见以 利押，就心里说，耶和华的受膏者必定在他面前。","notes":[]},{"n":7,"t":"耶和华却对撒母耳说：「不要看他的外貌和他身材高大，我不拣选他。因为，耶和华不像人看人：人是看外貌；耶和华是看内心。」","notes":[]},{"n":8,"t":"耶西叫亚比拿达从撒母耳面前经过，撒母耳说：「耶和华也不拣选他。」","notes":[]},{"n":9,"t":"耶西又叫沙玛从撒母耳面前经过，撒母耳说：「耶和华也不拣选他。」","notes":[]},{"n":10,"t":"耶西叫他七个儿子都从撒母耳面前经过，撒母耳说：「这都不是耶和华所拣选的。」","notes":[]},{"n":11,"t":"撒母耳对耶西说：「你的儿子都在这里吗？」他回答说：「还有个小的，现在放羊。」撒母耳对耶西说：「你打发人去叫他来；他若不来，我们必不坐席。」","notes":[]},{"n":12,"t":"耶西就打发人去叫了他来。他面色光红，双目清秀，容貌俊美。耶和华说：「这就是他，你起来膏他。」","notes":[]},{"n":13,"t":"撒母耳就用角里的膏油，在他诸兄中膏了他。从这日起，耶和华的灵就大大感动大卫。撒母耳起身回拉玛去了。","notes":[]},{"n":14,"t":"耶和华的灵离开扫罗，有恶魔从耶和华那里来扰乱他。","notes":[],"heads":["大卫在扫罗的宫里"]},{"n":15,"t":"扫罗的臣仆对他说：「现在有恶魔从神那里来扰乱你。","notes":[]},{"n":16,"t":"我们的主可以吩咐面前的臣仆，找一个善于弹琴的来，等神那里来的恶魔临到你身上的时候，使他用手弹琴，你就好了。」","notes":[]},{"n":17,"t":"扫罗对臣仆说：「你们可以为我找一个善于弹琴的，带到我这里来。」","notes":[]},{"n":18,"t":"其中有一个少年人说：「我曾见伯利恒人耶西的一个儿子善于弹琴，是大有勇敢的战士，说话合宜，容貌俊美，耶和华也与他同在。」","notes":[]},{"n":19,"t":"于是扫罗差遣使者去见耶西，说：「请你打发你放羊的儿子大卫到我这里来。」","notes":[]},{"n":20,"t":"耶西就把几个饼和一皮袋酒，并一只山羊羔，都驮在驴上，交给他儿子大卫，送与扫罗。","notes":[]},{"n":21,"t":"大卫到了扫罗那里，就侍立在扫罗面前。扫罗甚喜爱他，他就作了扫罗拿兵器的人。","notes":[]},{"n":22,"t":"扫罗差遣人去见耶西，说：「求你容大卫侍立在我面前，因为他在我眼前蒙了恩。」","notes":[]},{"n":23,"t":"从神那里来的恶魔临到扫罗身上的时候，大卫就拿琴，用手而弹，扫罗便舒畅爽快，恶魔离了他。","notes":[]}]},"17":{"heading":"歌利亚向以色列军挑战","verses":[{"n":1,"t":"非利士人招聚他们的军旅，要来争战；聚集在属犹大的梭哥，安营在梭哥和亚西加中间的以弗·大悯。","notes":[]},{"n":2,"t":"扫罗和以色列人也聚集，在以拉谷安营，摆列队伍，要与非利士人打仗。","notes":[]},{"n":3,"t":"非利士人站在这边山上，以色列人站在那边山上，当中有谷。","notes":[]},{"n":4,"t":"从非利士营中出来一个讨战的人，名叫歌利亚，是迦特人，身高六肘零一虎口；","notes":[]},{"n":5,"t":"头戴铜盔，身穿铠甲，甲重五千舍客勒；","notes":[]},{"n":6,"t":"腿上有铜护膝，两肩之中背负铜戟；","notes":[]},{"n":7,"t":"枪杆粗如织布的机轴，铁枪头重六百舍客勒。有一个拿盾牌的人在他前面走。","notes":[]},{"n":8,"t":"歌利亚对着以色列的军队站立，呼叫说：「你们出来摆列队伍做什么呢？我不是非利士人吗？你们不是扫罗的仆人吗？可以从你们中间拣选一人，使他下到我这里来。","notes":[]},{"n":9,"t":"他若能与我战斗，将我杀死，我们就作你们的仆人；我若胜了他，将他杀死，你们就作我们的仆人，服事我们。」","notes":[]},{"n":10,"t":"那非利士人又说：「我今日向以色列人的军队骂阵。你们叫一个人出来，与我战斗。」","notes":[]},{"n":11,"t":"扫罗和以色列众人听见非利士人的这些话，就惊惶，极其害怕。","notes":[]},{"n":12,"t":"大卫是犹大伯利恒的以法他人耶西的儿子。耶西有八个儿子。当扫罗的时候，耶西已经老迈。","notes":[],"heads":["大卫在扫罗的营中"]},{"n":13,"t":"耶西的三个大儿子跟随扫罗出征。这出征的三个儿子：长子名叫以利押，次子名叫亚比拿达，三子名叫沙玛。","notes":[]},{"n":14,"t":"大卫是最小的；那三个大儿子跟随扫罗。","notes":[]},{"n":15,"t":"大卫有时离开扫罗，回伯利恒放他父亲的羊。","notes":[]},{"n":16,"t":"那非利士人早晚都出来站着，如此四十日。","notes":[]},{"n":17,"t":"一日，耶西对他儿子大卫说：「你拿一伊法烘了的穗子和十个饼，速速地送到营里去，交给你哥哥们；","notes":[]},{"n":18,"t":"再拿这十块奶饼，送给他们的千夫长，且问你哥哥们好，向他们要一封信来。」","notes":[]},{"n":19,"t":"扫罗与大卫的三个哥哥和以色列众人，在以拉谷与非利士人打仗。","notes":[]},{"n":20,"t":"大卫早晨起来，将羊交托一个看守的人，照着他父亲所吩咐的话，带着食物去了。到了辎重营，军兵刚出到战场，呐喊要战。","notes":[]},{"n":21,"t":"以色列人和非利士人都摆列队伍，彼此相对。","notes":[]},{"n":22,"t":"大卫把他带来的食物留在看守物件人的手下，跑到战场，问他哥哥们安。","notes":[]},{"n":23,"t":"与他们说话的时候，那讨战的，就是属迦特的非利士人歌利亚，从非利士队中出来，说从前所说的话；大卫都听见了。","notes":[]},{"n":24,"t":"以色列众人看见那人，就逃跑，极其害怕。","notes":[]},{"n":25,"t":"以色列人彼此说：「这上来的人你看见了吗？他上来是要向以色列人骂阵。若有能杀他的，王必赏赐他大财，将自己的女儿给他为妻，并在以色列人中免他父家纳粮当差。」","notes":[]},{"n":26,"t":"大卫问站在旁边的人说：「有人杀这非利士人，除掉以色列人的耻辱，怎样待他呢？这未受割礼的非利士人是谁呢？竟敢向永生神的军队骂阵吗？」","notes":[]},{"n":27,"t":"百姓照先前的话回答他说：「有人能杀这非利士人，必如此如此待他。」","notes":[]},{"n":28,"t":"大卫的长兄以利押听见大卫与他们所说的话，就向他发怒，说：「你下来做什么呢？在旷野的那几只羊，你交托了谁呢？我知道你的骄傲和你心里的恶意，你下来特为要看争战！」","notes":[]},{"n":29,"t":"大卫说：「我做了什么呢？我来岂没有缘故吗？」","notes":[]},{"n":30,"t":"大卫就离开他转向别人，照先前的话而问；百姓仍照先前的话回答他。","notes":[]},{"n":31,"t":"有人听见大卫所说的话，就告诉了扫罗；扫罗便打发人叫他来。","notes":[]},{"n":32,"t":"大卫对扫罗说：「人都不必因那非利士人胆怯。你的仆人要去与那非利士人战斗。」","notes":[]},{"n":33,"t":"扫罗对大卫说：「你不能去与那非利士人战斗；因为你年纪太轻，他自幼就作战士。」","notes":[]},{"n":34,"t":"大卫对扫罗说：「你仆人为父亲放羊，有时来了狮子，有时来了熊，从群中衔一只羊羔去。","notes":[]},{"n":35,"t":"我就追赶它，击打它，将羊羔从它口中救出来。它起来要害我，我就揪着它的胡子，将它打死。","notes":[]},{"n":36,"t":"你仆人曾打死狮子和熊，这未受割礼的非利士人向永生神的军队骂阵，也必像狮子和熊一般。」","notes":[]},{"n":37,"t":"大卫又说：「耶和华救我脱离狮子和熊的爪，也必救我脱离这非利士人的手。」扫罗对大卫说：「你可以去吧！耶和华必与你同在。」","notes":[]},{"n":38,"t":"扫罗就把自己的战衣给大卫穿上，将铜盔给他戴上，又给他穿上铠甲。","notes":[]},{"n":39,"t":"大卫把刀跨在战衣外，试试能走不能走；因为素来没有穿惯，就对扫罗说：「我穿戴这些不能走，因为素来没有穿惯。」于是摘脱了。","notes":[]},{"n":40,"t":"他手中拿杖，又在溪中挑选了五块光滑石子，放在袋里，就是牧人带的囊里；手中拿着甩石的机弦，就去迎那非利士人。","notes":[]},{"n":41,"t":"非利士人也渐渐地迎着大卫来，拿盾牌的走在前头。","notes":[],"heads":["大卫击杀歌利亚"]},{"n":42,"t":"非利士人观看，见了大卫，就藐视他；因为他年轻，面色光红，容貌俊美。","notes":[]},{"n":43,"t":"非利士人对大卫说：「你拿杖到我这里来，我岂是狗呢？」非利士人就指着自己的神咒诅大卫。","notes":[]},{"n":44,"t":"非利士人又对大卫说：「来吧！我将你的肉给空中的飞鸟、田野的走兽吃。」","notes":[]},{"n":45,"t":"大卫对非利士人说：「你来攻击我，是靠着刀枪和铜戟；我来攻击你，是靠着万军之耶和华的名，就是你所怒骂带领以色列军队的神。","notes":[]},{"n":46,"t":"今日耶和华必将你交在我手里。我必杀你，斩你的头，又将非利士军兵的尸首给空中的飞鸟、地上的野兽吃，使普天下的人都知道以色列中有神；","notes":[]},{"n":47,"t":"又使这众人知道耶和华使人得胜，不是用刀用枪，因为争战的胜败全在乎耶和华。他必将你们交在我们手里。」","notes":[]},{"n":48,"t":"非利士人起身，迎着大卫前来。大卫急忙迎着非利士人，往战场跑去。","notes":[]},{"n":49,"t":"大卫用手从囊中掏出一块石子来，用机弦甩去，打中非利士人的额，石子进入额内，他就仆倒，面伏于地。","notes":[]},{"n":50,"t":"这样，大卫用机弦甩石，胜了那非利士人，打死他；大卫手中却没有刀。","notes":[]},{"n":51,"t":"大卫跑去，站在非利士人身旁，将他的刀从鞘中拔出来，杀死他，割了他的头。非利士众人看见他们讨战的勇士死了，就都逃跑。","notes":[]},{"n":52,"t":"以色列人和犹大人便起身呐喊，追赶非利士人，直到迦特和以革伦的城门。被杀的非利士人倒在沙拉音的路上，直到迦特和以革伦。","notes":["或译：该"]},{"n":53,"t":"以色列人追赶非利士人回来，就夺了他们的营盘。","notes":[]},{"n":54,"t":"大卫将那非利士人的头拿到耶路撒冷，却将他军装放在自己的帐棚里。","notes":[]},{"n":55,"t":"扫罗看见大卫去攻击非利士人，就问元帅押尼珥说：「押尼珥啊，那少年人是谁的儿子？」押尼珥说：「我敢在王面前起誓，我不知道。」","notes":[],"heads":["大卫觐见扫罗"]},{"n":56,"t":"王说：「你可以问问那幼年人是谁的儿子。」","notes":[]},{"n":57,"t":"大卫打死非利士人回来，押尼珥领他到扫罗面前，他手中拿着非利士人的头。","notes":[]},{"n":58,"t":"扫罗问他说：「少年人哪，你是谁的儿子？」大卫说：「我是你仆人伯利恒人耶西的儿子。」","notes":[]}]},"18":{"heading":"扫罗妒忌大卫","verses":[{"n":1,"t":"大卫对扫罗说完了话，约拿单的心与大卫的心深相契合。约拿单爱大卫，如同爱自己的性命。","notes":[]},{"n":2,"t":"那日扫罗留住大卫，不容他再回父家。","notes":[]},{"n":3,"t":"约拿单爱大卫如同爱自己的性命，就与他结盟。","notes":[]},{"n":4,"t":"约拿单从身上脱下外袍，给了大卫，又将战衣、刀、弓、腰带都给了他。","notes":[]},{"n":5,"t":"扫罗无论差遣大卫往何处去，他都做事精明。扫罗就立他作战士长，众百姓和扫罗的臣仆无不喜悦。","notes":[]},{"n":6,"t":"大卫打死了那非利士人，同众人回来的时候，妇女们从以色列各城里出来，欢欢喜喜，打鼓击磬，歌唱跳舞，迎接扫罗王。","notes":[]},{"n":7,"t":"众妇女舞蹈唱和，说：「扫罗杀死千千，大卫杀死万万。」","notes":[]},{"n":8,"t":"扫罗甚发怒，不喜悦这话，就说：「将万万归大卫，千千归我，只剩下王位没有给他了。」","notes":[]},{"n":9,"t":"从这日起，扫罗就怒视大卫。","notes":[]},{"n":10,"t":"次日，从神那里来的恶魔大大降在扫罗身上，他就在家中胡言乱语。大卫照常弹琴，扫罗手里拿着枪。","notes":[]},{"n":11,"t":"扫罗把枪一抡，心里说，我要将大卫刺透，钉在墙上。大卫躲避他两次。","notes":[]},{"n":12,"t":"扫罗惧怕大卫；因为耶和华离开自己，与大卫同在。","notes":[]},{"n":13,"t":"所以扫罗使大卫离开自己，立他为千夫长，他就领兵出入。","notes":[]},{"n":14,"t":"大卫做事无不精明，耶和华也与他同在。","notes":[]},{"n":15,"t":"扫罗见大卫做事精明，就甚怕他。","notes":[]},{"n":16,"t":"但以色列和犹大众人都爱大卫，因为他领他们出入。","notes":[]},{"n":17,"t":"扫罗对大卫说：「我将大女儿米拉给你为妻，只要你为我奋勇，为耶和华争战。」扫罗心里说：「我不好亲手害他，要借非利士人的手害他。」","notes":[],"heads":["大卫娶扫罗的女儿"]},{"n":18,"t":"大卫对扫罗说：「我是谁，我是什么出身，我父家在以色列中是何等的家，岂敢作王的女婿呢？」","notes":[]},{"n":19,"t":"扫罗的女儿米拉到了当给大卫的时候，扫罗却给了米何拉人亚得列为妻。","notes":[]},{"n":20,"t":"扫罗的次女米甲爱大卫。有人告诉扫罗，扫罗就喜悦。","notes":[]},{"n":21,"t":"扫罗心里说：「我将这女儿给大卫，作他的网罗，好借非利士人的手害他。」所以扫罗对大卫说：「你今日可以第二次作我的女婿。」","notes":[]},{"n":22,"t":"扫罗吩咐臣仆说：「你们暗中对大卫说：『王喜悦你，王的臣仆也都喜爱你，所以你当作王的女婿。』」","notes":[]},{"n":23,"t":"扫罗的臣仆就照这话说给大卫听。大卫说：「你们以为作王的女婿是一件小事吗？我是贫穷卑微的人。」","notes":[]},{"n":24,"t":"扫罗的臣仆回奏说，大卫所说的如此如此。","notes":[]},{"n":25,"t":"扫罗说：「你们要对大卫这样说：『王不要什么聘礼，只要一百非利士人的阳皮，好在王的仇敌身上报仇。』」扫罗的意思要使大卫丧在非利士人的手里。","notes":[]},{"n":26,"t":"扫罗的臣仆将这话告诉大卫，大卫就欢喜作王的女婿。日期还没有到，","notes":[]},{"n":27,"t":"大卫和跟随他的人起身前往，杀了二百非利士人，将阳皮满数交给王，为要作王的女婿。于是扫罗将女儿米甲给大卫为妻。","notes":[]},{"n":28,"t":"扫罗见耶和华与大卫同在，又知道女儿米甲爱大卫，","notes":[]},{"n":29,"t":"就更怕大卫，常作大卫的仇敌。","notes":[]},{"n":30,"t":"每逢非利士军长出来打仗，大卫比扫罗的臣仆做事精明，因此他的名被人尊重。","notes":[]}]},"19":{"heading":"扫罗逼迫大卫","verses":[{"n":1,"t":"扫罗对他儿子约拿单和众臣仆说，要杀大卫；扫罗的儿子约拿单却甚喜爱大卫。","notes":[]},{"n":2,"t":"约拿单告诉大卫说：「我父扫罗想要杀你，所以明日早晨你要小心，到一个僻静地方藏身。","notes":[]},{"n":3,"t":"我就出到你所藏的田里，站在我父亲旁边与他谈论。我看他情形怎样，我必告诉你。」","notes":[]},{"n":4,"t":"约拿单向他父亲扫罗替大卫说好话，说：「王不可得罪王的仆人大卫；因为他未曾得罪你，他所行的都与你大有益处。","notes":[]},{"n":5,"t":"他拚命杀那非利士人，耶和华为以色列众人大行拯救；那时你看见，甚是欢喜，现在为何无故要杀大卫，流无辜人的血，自己取罪呢？」","notes":[]},{"n":6,"t":"扫罗听了约拿单的话，就指着永生的耶和华起誓说：「我必不杀他。」","notes":[]},{"n":7,"t":"约拿单叫大卫来，把这一切事告诉他，带他去见扫罗。他就仍然侍立在扫罗面前。","notes":[]},{"n":8,"t":"此后又有争战的事。大卫出去与非利士人打仗，大大杀败他们，他们就在他面前逃跑。","notes":[]},{"n":9,"t":"从耶和华那里来的恶魔又降在扫罗身上（扫罗手里拿枪坐在屋里），大卫就用手弹琴。","notes":[]},{"n":10,"t":"扫罗用枪想要刺透大卫，钉在墙上，他却躲开，扫罗的枪刺入墙内。当夜大卫逃走，躲避了。","notes":[]},{"n":11,"t":"扫罗打发人到大卫的房屋那里窥探他，要等到天亮杀他。大卫的妻米甲对他说：「你今夜若不逃命，明日你要被杀。」","notes":[]},{"n":12,"t":"于是米甲将大卫从窗户里缒下去，大卫就逃走，躲避了。","notes":[]},{"n":13,"t":"米甲把家中的神像放在床上，头枕在山羊毛装的枕头上，用被遮盖。","notes":[]},{"n":14,"t":"扫罗打发人去捉拿大卫，米甲说：「他病了。」","notes":[]},{"n":15,"t":"扫罗又打发人去看大卫，说：「当连床将他抬来，我好杀他。」","notes":[]},{"n":16,"t":"使者进去，看见床上有神像，头枕在山羊毛装的枕头上。","notes":[]},{"n":17,"t":"扫罗对米甲说：「你为什么这样欺哄我，放我仇敌逃走呢？」米甲回答说：「他对我说：『你放我走，不然我要杀你。』」","notes":[]},{"n":18,"t":"大卫逃避，来到拉玛见撒母耳，将扫罗向他所行的事述说了一遍。他和撒母耳就往拿约去居住。","notes":[]},{"n":19,"t":"有人告诉扫罗，说大卫在拉玛的拿约。","notes":[]},{"n":20,"t":"扫罗打发人去捉拿大卫。去的人见有一班先知都受感说话，撒母耳站在其中监管他们；打发去的人也受神的灵感动说话。","notes":[]},{"n":21,"t":"有人将这事告诉扫罗，他又打发人去，他们也受感说话。扫罗第三次打发人去，他们也受感说话。","notes":[]},{"n":22,"t":"然后扫罗自己往拉玛去，到了西沽的大井，问人说：「撒母耳和大卫在哪里呢？」有人说：「在拉玛的拿约。」","notes":[]},{"n":23,"t":"他就往拉玛的拿约去。神的灵也感动他，一面走一面说话，直到拉玛的拿约。","notes":[]},{"n":24,"t":"他就脱了衣服，在撒母耳面前受感说话，一昼一夜露体躺卧。因此有句俗语说：「扫罗也列在先知中吗？」","notes":[]}]},"20":{"heading":"约拿单帮助大卫","verses":[{"n":1,"t":"大卫从拉玛的拿约逃跑，来到约拿单那里，对他说：「我做了什么？有什么罪孽呢？在你父亲面前犯了什么罪，他竟寻索我的性命呢？」","notes":[]},{"n":2,"t":"约拿单回答说：「断然不是！你必不致死。我父做事，无论大小，没有不叫我知道的。怎么独有这事隐瞒我呢？决不如此。」","notes":[]},{"n":3,"t":"大卫又起誓说：「你父亲准知我在你眼前蒙恩。他心里说，不如不叫约拿单知道，恐怕他愁烦。我指着永生的耶和华，又敢在你面前起誓，我离死不过一步。」","notes":[]},{"n":4,"t":"约拿单对大卫说：「你心里所求的，我必为你成就。」","notes":[]},{"n":5,"t":"大卫对约拿单说：「明日是初一，我当与王同席，求你容我去藏在田野，直到第三日晚上。","notes":[]},{"n":6,"t":"你父亲若见我不在席上，你就说：『大卫切求我许他回本城伯利恒去，因为他全家在那里献年祭。』","notes":[]},{"n":7,"t":"你父亲若说好，仆人就平安了；他若发怒，你就知道他决意要害我。","notes":[]},{"n":8,"t":"求你施恩与仆人，因你在耶和华面前曾与仆人结盟。我若有罪，不如你自己杀我，何必将我交给你父亲呢？」","notes":[]},{"n":9,"t":"约拿单说：「断无此事！我若知道我父亲决意害你，我岂不告诉你呢？」","notes":[]},{"n":10,"t":"大卫对约拿单说：「你父亲若用厉言回答你，谁来告诉我呢？」","notes":[]},{"n":11,"t":"约拿单对大卫说：「你我且往田野去。」二人就往田野去了。","notes":[]},{"n":12,"t":"约拿单对大卫说：「愿耶和华—以色列的神为证。明日约在这时候，或第三日，我探我父亲的意思，若向你有好意，我岂不打发人告诉你吗？","notes":[]},{"n":13,"t":"我父亲若有意害你，我不告诉你使你平平安安地走，愿耶和华重重地降罚与我。愿耶和华与你同在，如同从前与我父亲同在一样。","notes":[]},{"n":14,"t":"你要照耶和华的慈爱恩待我，不但我活着的时候免我死亡，","notes":[]},{"n":15,"t":"就是我死后，耶和华从地上剪除你仇敌的时候，你也永不可向我家绝了恩惠。」","notes":[]},{"n":16,"t":"于是约拿单与大卫家结盟，说：「愿耶和华借大卫的仇敌追讨背约的罪。」","notes":[]},{"n":17,"t":"约拿单因爱大卫如同爱自己的性命，就使他再起誓。","notes":[]},{"n":18,"t":"约拿单对他说：「明日是初一，你的座位空设，人必理会你不在那里。","notes":[]},{"n":19,"t":"你等三日，就要速速下去，到你从前遇事所藏的地方，在以色磐石那里等候。","notes":[]},{"n":20,"t":"我要向磐石旁边射三箭，如同射箭靶一样。","notes":[]},{"n":21,"t":"我要打发童子，说：『去把箭找来。』我若对童子说：『箭在后头，把箭拿来』，你就可以回来；我指着永生的耶和华起誓，你必平安无事。","notes":[]},{"n":22,"t":"我若对童子说：『箭在前头』，你就要去，因为是耶和华打发你去的。","notes":[]},{"n":23,"t":"至于你我今日所说的话，有耶和华在你我中间为证，直到永远。」","notes":[]},{"n":24,"t":"大卫就去藏在田野。到了初一日，王坐席要吃饭。","notes":[]},{"n":25,"t":"王照常坐在靠墙的位上，约拿单侍立，押尼珥坐在扫罗旁边，大卫的座位空设。","notes":[]},{"n":26,"t":"然而这日扫罗没有说什么，他想大卫遇事，偶染不洁，他必定是不洁。","notes":[]},{"n":27,"t":"初二日大卫的座位还空设。扫罗问他儿子约拿单说：「耶西的儿子为何昨日、今日没有来吃饭呢？」","notes":[]},{"n":28,"t":"约拿单回答扫罗说：「大卫切求我容他往伯利恒去。","notes":[]},{"n":29,"t":"他说：『求你容我去，因为我家在城里有献祭的事；我长兄吩咐我去。如今我若在你眼前蒙恩，求你容我去见我的弟兄』；所以大卫没有赴王的席。」","notes":[]},{"n":30,"t":"扫罗向约拿单发怒，对他说：「你这顽梗背逆之妇人所生的，我岂不知道你喜悦耶西的儿子，自取羞辱，以致你母亲露体蒙羞吗？","notes":[]},{"n":31,"t":"耶西的儿子若在世间活着，你和你的国位必站立不住。现在你要打发人去，将他捉拿交给我；他是该死的。」","notes":[]},{"n":32,"t":"约拿单对父亲扫罗说：「他为什么该死呢？他做了什么呢？」","notes":[]},{"n":33,"t":"扫罗向约拿单抡枪要刺他，约拿单就知道他父亲决意要杀大卫。","notes":[]},{"n":34,"t":"于是约拿单气忿忿地从席上起来，在这初二日没有吃饭。他因见父亲羞辱大卫，就为大卫愁烦。","notes":[]},{"n":35,"t":"次日早晨，约拿单按着与大卫约会的时候出到田野，有一个童子跟随。","notes":[]},{"n":36,"t":"约拿单对童子说：「你跑去，把我所射的箭找来。」童子跑去，约拿单就把箭射在童子前头。","notes":[]},{"n":37,"t":"童子到了约拿单落箭之地，约拿单呼叫童子说：「箭不是在你前头吗？」","notes":[]},{"n":38,"t":"约拿单又呼叫童子说：「速速地去，不要迟延！」童子就拾起箭来，回到主人那里。","notes":[]},{"n":39,"t":"童子却不知道这是什么意思，只有约拿单和大卫知道。","notes":[]},{"n":40,"t":"约拿单将弓箭交给童子，吩咐说：「你拿到城里去。」","notes":[]},{"n":41,"t":"童子一去，大卫就从磐石的南边出来，俯伏在地，拜了三拜；二人亲嘴，彼此哭泣，大卫哭得更恸。","notes":[]},{"n":42,"t":"约拿单对大卫说：「我们二人曾指着耶和华的名起誓说：『愿耶和华在你我中间，并你我后裔中间为证，直到永远。』如今你平平安安地去吧！」大卫就起身走了；约拿单也回城里去了。","notes":[]}]},"21":{"heading":"大卫逃离扫罗","verses":[{"n":1,"t":"大卫到了挪伯祭司亚希米勒那里，亚希米勒战战兢兢地出来迎接他，问他说：「你为什么独自来，没有人跟随呢？」","notes":[]},{"n":2,"t":"大卫回答祭司亚希米勒说：「王吩咐我一件事说：『我差遣你委托你的这件事，不要使人知道。』故此我已派定少年人在某处等候我。","notes":[]},{"n":3,"t":"现在你手下有什么？求你给我五个饼或是别样的食物。」","notes":[]},{"n":4,"t":"祭司对大卫说：「我手下没有寻常的饼，只有圣饼；若少年人没有亲近妇人才可以给。」","notes":[]},{"n":5,"t":"大卫对祭司说：「实在约有三日我们没有亲近妇人；我出来的时候，虽是寻常行路，少年人的器皿还是洁净的；何况今日不更是洁净吗？」","notes":[]},{"n":6,"t":"祭司就拿圣饼给他；因为在那里没有别样饼，只有更换新饼，从耶和华面前撤下来的陈设饼。（","notes":[]},{"n":7,"t":"当日有扫罗的一个臣子留在耶和华面前。他名叫多益，是以东人，作扫罗的司牧长。）","notes":[]},{"n":8,"t":"大卫问亚希米勒说：「你手下有枪有刀没有？因为王的事甚急，连刀剑器械我都没有带。」","notes":[]},{"n":9,"t":"祭司说：「你在以拉谷杀非利士人歌利亚的那刀在这里，裹在布中，放在以弗得后边，你要就可以拿去；除此以外，再没有别的。」大卫说：「这刀没有可比的！求你给我。」","notes":[]},{"n":10,"t":"那日大卫起来，躲避扫罗，逃到迦特王亚吉那里。","notes":[]},{"n":11,"t":"亚吉的臣仆对亚吉说：「这不是以色列国王大卫吗？那里的妇女跳舞唱和，不是指着他说『扫罗杀死千千，大卫杀死万万』吗？」","notes":[]},{"n":12,"t":"大卫将这话放在心里，甚惧怕迦特王亚吉，","notes":[]},{"n":13,"t":"就在众人面前改变了寻常的举动，在他们手下假装疯癫，在城门的门扇上胡写乱画，使唾沫流在胡子上。","notes":[]},{"n":14,"t":"亚吉对臣仆说：「你们看，这人是疯子。为什么带他到我这里来呢？","notes":[]},{"n":15,"t":"我岂缺少疯子，你们带这人来在我面前疯癫吗？这人岂可进我的家呢？」","notes":[]}]},"22":{"heading":"残杀祭司","verses":[{"n":1,"t":"大卫就离开那里，逃到亚杜兰洞。他的弟兄和他父亲的全家听见了，就都下到他那里。","notes":[]},{"n":2,"t":"凡受窘迫的、欠债的、心里苦恼的都聚集到大卫那里；大卫就作他们的头目，跟随他的约有四百人。","notes":[]},{"n":3,"t":"大卫从那里往摩押的米斯巴去，对摩押王说：「求你容我父母搬来，住在你们这里，等我知道神要为我怎样行。」","notes":[]},{"n":4,"t":"大卫领他父母到摩押王面前。大卫住山寨多少日子，他父母也住摩押王那里多少日子。","notes":[]},{"n":5,"t":"先知迦得对大卫说：「你不要住在山寨，要往犹大地去。」大卫就离开那里，进入哈列的树林。","notes":[]},{"n":6,"t":"扫罗在基比亚的拉玛，坐在垂丝柳树下，手里拿着枪，众臣仆侍立在左右。扫罗听见大卫和跟随他的人在何处，","notes":[]},{"n":7,"t":"就对左右侍立的臣仆说：「便雅悯人哪，你们要听我的话！耶西的儿子能将田地和葡萄园赐给你们各人吗？能立你们各人作千夫长百夫长吗？","notes":[]},{"n":8,"t":"你们竟都结党害我！我的儿子与耶西的儿子结盟的时候，无人告诉我；我的儿子挑唆我的臣子谋害我，就如今日的光景，也无人告诉我，为我忧虑。」","notes":[]},{"n":9,"t":"那时以东人多益站在扫罗的臣仆中，对他说：「我曾看见耶西的儿子到了挪伯，亚希突的儿子亚希米勒那里。","notes":[]},{"n":10,"t":"亚希米勒为他求问耶和华，又给他食物，并给他杀非利士人歌利亚的刀。」","notes":[]},{"n":11,"t":"王就打发人将祭司亚希突的儿子亚希米勒和他父亲的全家，就是住挪伯的祭司都召了来；他们就来见王。","notes":[]},{"n":12,"t":"扫罗说：「亚希突的儿子，要听我的话！」他回答说：「主啊，我在这里。」","notes":[]},{"n":13,"t":"扫罗对他说：「你为什么与耶西的儿子结党害我，将食物和刀给他，又为他求问神，使他起来谋害我，就如今日的光景？」","notes":[]},{"n":14,"t":"亚希米勒回答王说：「王的臣仆中有谁比大卫忠心呢？他是王的女婿，又是王的参谋，并且在王家中是尊贵的。","notes":[]},{"n":15,"t":"我岂是从今日才为他求问神呢？断不是这样！王不要将罪归我和我父的全家；因为这事，无论大小，仆人都不知道。」","notes":[]},{"n":16,"t":"王说：「亚希米勒啊，你和你父的全家都是该死的！」","notes":[]},{"n":17,"t":"王就吩咐左右的侍卫说：「你们去杀耶和华的祭司；因为他们帮助大卫，又知道大卫逃跑，竟没有告诉我。」扫罗的臣子却不肯伸手杀耶和华的祭司。","notes":[]},{"n":18,"t":"王吩咐多益说：「你去杀祭司吧！」以东人多益就去杀祭司，那日杀了穿细麻布以弗得的八十五人；","notes":[]},{"n":19,"t":"又用刀将祭司城挪伯中的男女、孩童、吃奶的，和牛、羊、驴尽都杀灭。","notes":[]},{"n":20,"t":"亚希突的儿子亚希米勒有一个儿子，名叫亚比亚他，逃到大卫那里。","notes":[]},{"n":21,"t":"亚比亚他将扫罗杀耶和华祭司的事告诉大卫。","notes":[]},{"n":22,"t":"大卫对亚比亚他说：「那日我见以东人多益在那里，就知道他必告诉扫罗。你父的全家丧命，都是因我的缘故。","notes":[]},{"n":23,"t":"你可以住在我这里，不要惧怕。因为寻索你命的就是寻索我的命；你在我这里可得保全。」","notes":[]}]},"23":{"heading":"大卫救基伊拉的居民","verses":[{"n":1,"t":"有人告诉大卫说：「非利士人攻击基伊拉，抢夺禾场。」","notes":[]},{"n":2,"t":"所以大卫求问耶和华说：「我去攻打那些非利士人可以不可以？」耶和华对大卫说：「你可以去攻打非利士人，拯救基伊拉。」","notes":[]},{"n":3,"t":"跟随大卫的人对他说：「我们在犹大地这里尚且惧怕，何况往基伊拉去攻打非利士人的军旅呢？」","notes":[]},{"n":4,"t":"大卫又求问耶和华。耶和华回答说：「你起身下基伊拉去，我必将非利士人交在你手里。」","notes":[]},{"n":5,"t":"大卫和跟随他的人往基伊拉去，与非利士人打仗，大大杀败他们，又夺获他们的牲畜。这样，大卫救了基伊拉的居民。","notes":[]},{"n":6,"t":"亚希米勒的儿子亚比亚他逃到基伊拉见大卫的时候，手里拿着以弗得。","notes":[]},{"n":7,"t":"有人告诉扫罗说：「大卫到了基伊拉。」扫罗说：「他进了有门有闩的城，困闭在里头；这是神将他交在我手里了。」","notes":[]},{"n":8,"t":"于是扫罗招聚众民，要下去攻打基伊拉城，围困大卫和跟随他的人。","notes":[]},{"n":9,"t":"大卫知道扫罗设计谋害他，就对祭司亚比亚他说：「将以弗得拿过来。」","notes":[]},{"n":10,"t":"大卫祷告说：「耶和华—以色列的神啊，你仆人听真了扫罗要往基伊拉来，为我的缘故灭城。","notes":[]},{"n":11,"t":"基伊拉人将我交在扫罗手里不交？扫罗照着你仆人所听的话下来不下来？耶和华—以色列的神啊，求你指示仆人！」耶和华说：「扫罗必下来。」","notes":[]},{"n":12,"t":"大卫又说：「基伊拉人将我和跟随我的人交在扫罗手里不交？」耶和华说：「必交出来。」","notes":[]},{"n":13,"t":"大卫和跟随他的约有六百人，就起身出了基伊拉，往他们所能往的地方去。有人告诉扫罗，大卫离开基伊拉逃走；于是扫罗不出来了。","notes":[]},{"n":14,"t":"大卫住在旷野的山寨里，常在西弗旷野的山地。扫罗天天寻索大卫，神却不将大卫交在他手里。","notes":[],"heads":["大卫在山地"]},{"n":15,"t":"大卫知道扫罗出来寻索他的命。那时，他住在西弗旷野的树林里；","notes":[]},{"n":16,"t":"扫罗的儿子约拿单起身，往那树林里去见大卫，使他倚靠神得以坚固，","notes":[]},{"n":17,"t":"对他说：「不要惧怕！我父扫罗的手必不加害于你；你必作以色列的王，我也作你的宰相。这事我父扫罗知道了。」","notes":[]},{"n":18,"t":"于是二人在耶和华面前立约。大卫仍住在树林里，约拿单回家去了。","notes":[]},{"n":19,"t":"西弗人上到基比亚见扫罗，说：「大卫不是在我们那里的树林里山寨中、旷野南边的哈基拉山藏着吗？","notes":[]},{"n":20,"t":"王啊，请你随你的心愿下来，我们必亲自将他交在王的手里。」","notes":[]},{"n":21,"t":"扫罗说：「愿耶和华赐福与你们，因你们顾恤我。","notes":[]},{"n":22,"t":"请你们回去，再确实查明他的住处和行踪，是谁看见他在那里，因为我听见人说他甚狡猾。","notes":[]},{"n":23,"t":"所以要看准他藏匿的地方，回来据实地告诉我，我就与你们同去。他若在犹大的境内，我必从千门万户中搜出他来。」","notes":[]},{"n":24,"t":"西弗人就起身，在扫罗以先往西弗去。 大卫和跟随他的人却在玛云旷野南边的亚拉巴。","notes":[]},{"n":25,"t":"扫罗和跟随他的人去寻找大卫；有人告诉大卫，他就下到磐石，住在玛云的旷野。扫罗听见，便在玛云的旷野追赶大卫。","notes":[]},{"n":26,"t":"扫罗在山这边走，大卫和跟随他的人在山那边走。大卫急忙躲避扫罗；因为扫罗和跟随他的人，四面围住大卫和跟随他的人，要拿获他们。","notes":[]},{"n":27,"t":"忽有使者来报告扫罗说：「非利士人犯境抢掠，请王快快回去！」","notes":[]},{"n":28,"t":"于是扫罗不追赶大卫，回去攻打非利士人。因此那地方名叫西拉·哈玛希罗结。","notes":[]},{"n":29,"t":"大卫从那里上去，住在隐·基底的山寨里。","notes":[]}]},"24":{"heading":"大卫饶扫罗的命","verses":[{"n":1,"t":"扫罗追赶非利士人回来，有人告诉他说：「大卫在隐·基底的旷野。」","notes":[]},{"n":2,"t":"扫罗就从以色列人中挑选三千精兵，率领他们往野羊的磐石去，寻索大卫和跟随他的人。","notes":[]},{"n":3,"t":"到了路旁的羊圈，在那里有洞，扫罗进去大解。大卫和跟随他的人正藏在洞里的深处。","notes":[]},{"n":4,"t":"跟随的人对大卫说：「耶和华曾应许你说：『我要将你的仇敌交在你手里，你可以任意待他。』如今时候到了！」大卫就起来，悄悄地割下扫罗外袍的衣襟。","notes":[]},{"n":5,"t":"随后大卫心中自责，因为割下扫罗的衣襟；","notes":[]},{"n":6,"t":"对跟随他的人说：「我的主乃是耶和华的受膏者，我在耶和华面前万不敢伸手害他，因他是耶和华的受膏者。」","notes":[]},{"n":7,"t":"大卫用这话拦住跟随他的人，不容他们起来害扫罗。扫罗起来，从洞里出去行路。","notes":[]},{"n":8,"t":"随后大卫也起来，从洞里出去，呼叫扫罗说：「我主，我王！」扫罗回头观看，大卫就屈身、脸伏于地下拜。","notes":[]},{"n":9,"t":"大卫对扫罗说：「你为何听信人的谗言，说大卫想要害你呢？","notes":[]},{"n":10,"t":"今日你亲眼看见在洞中，耶和华将你交在我手里；有人叫我杀你，我却爱惜你，说：『我不敢伸手害我的主，因为他是耶和华的受膏者。』","notes":[]},{"n":11,"t":"我父啊，看看你外袍的衣襟在我手中。我割下你的衣襟，没有杀你；你由此可以知道我没有恶意叛逆你。你虽然猎取我的命，我却没有得罪你。","notes":[]},{"n":12,"t":"愿耶和华在你我中间判断是非，在你身上为我伸冤，我却不亲手加害于你。","notes":[]},{"n":13,"t":"古人有句俗语说：『恶事出于恶人。』我却不亲手加害于你。","notes":[]},{"n":14,"t":"以色列王出来要寻找谁呢？追赶谁呢？不过追赶一条死狗，一个虼蚤就是了。","notes":[]},{"n":15,"t":"愿耶和华在你我中间施行审判，断定是非，并且鉴察，为我伸冤，救我脱离你的手。」","notes":[]},{"n":16,"t":"大卫向扫罗说完这话，扫罗说：「我儿大卫，这是你的声音吗？」就放声大哭，","notes":[]},{"n":17,"t":"对大卫说：「你比我公义；因为你以善待我，我却以恶待你。","notes":[]},{"n":18,"t":"你今日显明是以善待我；因为耶和华将我交在你手里，你却没有杀我。","notes":[]},{"n":19,"t":"人若遇见仇敌，岂肯放他平安无事地去呢？愿耶和华因你今日向我所行的，以善报你。","notes":[]},{"n":20,"t":"我也知道你必要作王，以色列的国必坚立在你手里。","notes":[]},{"n":21,"t":"现在你要指着耶和华向我起誓，不剪除我的后裔，在我父家不灭没我的名。」","notes":[]},{"n":22,"t":"于是大卫向扫罗起誓，扫罗就回家去；大卫和跟随他的人上山寨去了。","notes":[]}]},"25":{"heading":"撒母耳去世","verses":[{"n":1,"t":"撒母耳死了，以色列众人聚集，为他哀哭，将他葬在拉玛—他自己的坟墓里。大卫起身，下到巴兰的旷野。","notes":["原文是房屋"]},{"n":2,"t":"在玛云有一个人，他的产业在迦密，是一个大富户，有三千绵羊，一千山羊；他正在迦密剪羊毛。","notes":[]},{"n":3,"t":"那人名叫拿八，是迦勒族的人；他的妻名叫亚比该，是聪明俊美的妇人。拿八为人刚愎凶恶。","notes":[]},{"n":4,"t":"大卫在旷野听见说拿八剪羊毛，","notes":[]},{"n":5,"t":"大卫就打发十个仆人，吩咐他们说：「你们上迦密去见拿八，提我的名问他安。","notes":[]},{"n":6,"t":"要对那富户如此说：『愿你平安，愿你家平安，愿你一切所有的都平安。","notes":[]},{"n":7,"t":"现在我听说有人为你剪羊毛，你的牧人在迦密的时候和我们在一处，我们没有欺负他们，他们也未曾失落什么。","notes":[]},{"n":8,"t":"可以问你的仆人，他们必告诉你。所以愿我的仆人在你眼前蒙恩，因为是在好日子来的。求你随手取点赐与仆人和你儿子大卫。』」","notes":[]},{"n":9,"t":"大卫的仆人到了，将这话提大卫的名都告诉了拿八，就住了口。","notes":[]},{"n":10,"t":"拿八回答大卫的仆人说：「大卫是谁？耶西的儿子是谁？近来悖逆主人奔逃的仆人甚多，","notes":[]},{"n":11,"t":"我岂可将饮食和为我剪羊毛人所宰的肉给我不知道从哪里来的人呢？」","notes":[]},{"n":12,"t":"大卫的仆人就转身从原路回去，照这话告诉大卫。","notes":[]},{"n":13,"t":"大卫向跟随他的人说：「你们各人都要带上刀！」众人就都带上刀，大卫也带上刀。跟随大卫上去的约有四百人，留下二百人看守器具。","notes":[]},{"n":14,"t":"有拿八的一个仆人告诉拿八的妻亚比该说：「大卫从旷野打发使者来问我主人的安，主人却辱骂他们。","notes":[]},{"n":15,"t":"但是那些人待我们甚好；我们在田野与他们来往的时候，没有受他们的欺负，也未曾失落什么。","notes":[]},{"n":16,"t":"我们在他们那里牧羊的时候，他们昼夜作我们的保障。","notes":[]},{"n":17,"t":"所以你当筹划，看怎样行才好；不然，祸患定要临到我主人和他全家。他性情凶暴，无人敢与他说话。」","notes":[]},{"n":18,"t":"亚比该急忙将二百饼，两皮袋酒，五只收拾好了的羊，五细亚烘好了的穗子，一百葡萄饼，二百无花果饼，都驮在驴上，","notes":[]},{"n":19,"t":"对仆人说：「你们前头走，我随着你们去。」这事她却没有告诉丈夫拿八。","notes":[]},{"n":20,"t":"亚比该骑着驴，正下山坡，见大卫和跟随他的人从对面下来，亚比该就迎接他们。","notes":[]},{"n":21,"t":"大卫曾说：「我在旷野为那人看守所有的，以致他一样不失落，实在是徒然了！他向我以恶报善。","notes":[]},{"n":22,"t":"凡属拿八的男丁，我若留一个到明日早晨，愿神重重降罚与我！」","notes":[]},{"n":23,"t":"亚比该见大卫，便急忙下驴，在大卫面前脸伏于地叩拜，","notes":[]},{"n":24,"t":"俯伏在大卫的脚前，说：「我主啊，愿这罪归我！求你容婢女向你进言，更求你听婢女的话。","notes":[]},{"n":25,"t":"我主不要理这坏人拿八，他的性情与他的名相称；他名叫拿八，他为人果然愚顽。但我主所打发的仆人，婢女并没有看见。","notes":["就是愚顽的意思"]},{"n":26,"t":"我主啊，耶和华既然阻止你亲手报仇，取流血的罪，所以我指着永生的耶和华、又敢在你面前起誓说：『愿你的仇敌和谋害你的人都像拿八一样。』","notes":[]},{"n":27,"t":"如今求你将婢女送来的礼物给跟随你的仆人。","notes":[]},{"n":28,"t":"求你饶恕婢女的罪过。耶和华必为我主建立坚固的家，因我主为耶和华争战；并且在你平生的日子查不出有什么过来。","notes":[]},{"n":29,"t":"虽有人起来追逼你，寻索你的性命，你的性命却在耶和华—你的神那里蒙保护，如包裹宝器一样；你仇敌的性命，耶和华必抛去，如用机弦甩石一样。","notes":[]},{"n":30,"t":"我主现在若不亲手报仇流无辜人的血，到了耶和华照所应许你的话赐福与你，立你作以色列的王，那时我主必不至心里不安，觉得良心有亏。耶和华赐福与我主的时候，求你记念婢女。」","notes":[],"end":31},{"n":32,"t":"大卫对亚比该说：「耶和华—以色列的神是应当称颂的，因为他今日使你来迎接我。","notes":[]},{"n":33,"t":"你和你的见识也当称赞；因为你今日拦阻我亲手报仇、流人的血。","notes":[]},{"n":34,"t":"我指着阻止我加害于你的耶和华—以色列永生的神起誓，你若不速速地来迎接我，到明日早晨，凡属拿八的男丁必定不留一个。」","notes":[]},{"n":35,"t":"大卫受了亚比该送来的礼物，就对她说：「我听了你的话，准了你的情面，你可以平平安安地回家吧！」","notes":[]},{"n":36,"t":"亚比该到拿八那里，见他在家里设摆筵席，如同王的筵席；拿八快乐大醉。亚比该无论大小事都没有告诉他，就等到次日早晨。","notes":[]},{"n":37,"t":"到了早晨，拿八醒了酒，他的妻将这些事都告诉他，他就魂不附体，身僵如石头一般。","notes":[]},{"n":38,"t":"过了十天，耶和华击打拿八，他就死了。","notes":[]},{"n":39,"t":"大卫听见拿八死了，就说：「应当称颂耶和华，因他伸了拿八羞辱我的冤，又阻止仆人行恶；也使拿八的恶归到拿八的头上。」于是大卫打发人去，与亚比该说，要娶她为妻。","notes":[]},{"n":40,"t":"大卫的仆人到了迦密见亚比该，对她说：「大卫打发我们来见你，想要娶你为妻。」","notes":[]},{"n":41,"t":"亚比该就起来，俯伏在地，说：「我情愿作婢女，洗我主仆人的脚。」","notes":[]},{"n":42,"t":"亚比该立刻起身，骑上驴，带着五个使女，跟从大卫的使者去了，就作了大卫的妻。","notes":[]},{"n":43,"t":"大卫先娶了耶斯列人亚希暖，她们二人都作了他的妻。","notes":[]},{"n":44,"t":"扫罗已将他的女儿米甲，就是大卫的妻，给了迦琳人拉亿的儿子帕提为妻。","notes":[]}]},"26":{"heading":"大卫又饶扫罗的命","verses":[{"n":1,"t":"西弗人到基比亚见扫罗，说：「大卫不是在旷野前的哈基拉山藏着吗？」","notes":[]},{"n":2,"t":"扫罗就起身，带领以色列人中挑选的三千精兵下到西弗的旷野，要在那里寻索大卫。","notes":[]},{"n":3,"t":"扫罗在旷野前的哈基拉山，在道路上安营。大卫住在旷野，听说扫罗到旷野来追寻他，","notes":[]},{"n":4,"t":"就打发人去探听，便知道扫罗果然来到。","notes":[]},{"n":5,"t":"大卫起来，到扫罗安营的地方，看见扫罗和他的元帅尼珥的儿子押尼珥睡卧之处；扫罗睡在辎重营里，百姓安营在他周围。","notes":[]},{"n":6,"t":"大卫对赫人亚希米勒和洗鲁雅的儿子约押的兄弟亚比筛说：「谁同我下到扫罗营里去？」亚比筛说：「我同你下去。」","notes":[]},{"n":7,"t":"于是大卫和亚比筛夜间到了百姓那里，见扫罗睡在辎重营里；他的枪在头旁，插在地上。押尼珥和百姓睡在他周围。","notes":[]},{"n":8,"t":"亚比筛对大卫说：「现在神将你的仇敌交在你手里，求你容我拿枪将他刺透在地，一刺就成，不用再刺。」","notes":[]},{"n":9,"t":"大卫对亚比筛说：「不可害死他。有谁伸手害耶和华的受膏者而无罪呢？」","notes":[]},{"n":10,"t":"大卫又说：「我指着永生的耶和华起誓，他或被耶和华击打，或是死期到了，或是出战阵亡；","notes":[]},{"n":11,"t":"我在耶和华面前，万不敢伸手害耶和华的受膏者。现在你可以将他头旁的枪和水瓶拿来，我们就走。」","notes":[]},{"n":12,"t":"大卫从扫罗的头旁拿了枪和水瓶，二人就走了，没有人看见，没有人知道，也没有人醒起，都睡着了，因为耶和华使他们沉沉地睡了。","notes":[]},{"n":13,"t":"大卫过到那边去，远远地站在山顶上，与他们相离甚远。","notes":[]},{"n":14,"t":"大卫呼叫百姓和尼珥的儿子押尼珥说：「押尼珥啊，你为何不答应呢？」押尼珥说：「你是谁？竟敢呼叫王呢？」","notes":[]},{"n":15,"t":"大卫对押尼珥说：「你不是个勇士吗？以色列中谁能比你呢？民中有人进来要害死王—你的主，你为何没有保护王—你的主呢？","notes":[]},{"n":16,"t":"你这样是不好的！我指着永生的耶和华起誓，你们都是该死的；因为没有保护你们的主，就是耶和华的受膏者。现在你看看王头旁的枪和水瓶在哪里。」","notes":[]},{"n":17,"t":"扫罗听出是大卫的声音，就说：「我儿大卫，这是你的声音吗？」大卫说：「主—我的王啊，是我的声音」；","notes":[]},{"n":18,"t":"又说：「我做了什么？我手里有什么恶事？我主竟追赶仆人呢？","notes":[]},{"n":19,"t":"求我主我王听仆人的话：若是耶和华激发你攻击我，愿耶和华收纳祭物；若是人激发你，愿他在耶和华面前受咒诅；因为他现今赶逐我，不容我在耶和华的产业上有分，说：『你去事奉别神吧！』","notes":[]},{"n":20,"t":"现在求王不要使我的血流在离耶和华远的地方。以色列王出来是寻找一个虼蚤，如同人在山上猎取一个鹧鸪一般。」","notes":[]},{"n":21,"t":"扫罗说：「我有罪了！我儿大卫，你可以回来，因你今日看我的性命为宝贵；我必不再加害于你。我是糊涂人，大大错了。」","notes":[]},{"n":22,"t":"大卫说：「王的枪在这里，可以吩咐一个仆人过来拿去。","notes":[]},{"n":23,"t":"今日耶和华将王交在我手里，我却不肯伸手害耶和华的受膏者。耶和华必照各人的公义诚实报应他。","notes":[]},{"n":24,"t":"我今日重看你的性命，愿耶和华也重看我的性命，并且拯救我脱离一切患难。」","notes":[]},{"n":25,"t":"扫罗对大卫说：「我儿大卫，愿你得福！你必做大事，也必得胜。」于是大卫起行，扫罗回他的本处去了。","notes":[]}]},"27":{"heading":"大卫在非利士人中间","verses":[{"n":1,"t":"大卫心里说：「必有一日我死在扫罗手里，不如逃奔非利士地去。扫罗见我不在以色列的境内，就必绝望，不再寻索我；这样我可以脱离他的手。」","notes":[]},{"n":2,"t":"于是大卫起身，和跟随他的六百人投奔迦特王—玛俄的儿子亚吉去了。","notes":[]},{"n":3,"t":"大卫和他的两个妻，就是耶斯列人亚希暖和作过拿八妻的迦密人亚比该，并跟随他的人，连各人的眷属，都住在迦特的亚吉那里。","notes":[]},{"n":4,"t":"有人告诉扫罗说：「大卫逃到迦特。」扫罗就不再寻索他了。","notes":[]},{"n":5,"t":"大卫对亚吉说：「我若在你眼前蒙恩，求你在京外的城邑中赐我一个地方居住。仆人何必与王同住京都呢？」","notes":[]},{"n":6,"t":"当日亚吉将洗革拉赐给他，因此洗革拉属犹大王，直到今日。","notes":[]},{"n":7,"t":"大卫在非利士地住了一年零四个月。","notes":[]},{"n":8,"t":"大卫和跟随他的人上去，侵夺基述人、基色人、亚玛力人之地。这几族历来住在那地，从书珥直到埃及。","notes":[]},{"n":9,"t":"大卫击杀那地的人，无论男女都没有留下一个，又夺获牛、羊、骆驼、驴，并衣服，回来见亚吉。","notes":[]},{"n":10,"t":"亚吉说：「你们今日侵夺了什么地方呢？」大卫说：「侵夺了犹大的南方、耶拉篾的南方、基尼的南方。」","notes":[]},{"n":11,"t":"无论男女，大卫没有留下一个带到迦特来。他说：「恐怕他们将我们的事告诉人，说大卫住在非利士地的时候常常这样行。」","notes":[]},{"n":12,"t":"亚吉信了大卫，心里说：「大卫使本族以色列人憎恶他，所以他必永远作我的仆人了。」","notes":[]}]},"28":{"heading":"扫罗求问女巫","verses":[{"n":1,"t":"那时，非利士人聚集军旅，要与以色列人打仗。亚吉对大卫说：「你当知道，你和跟随你的人都要随我出战。」","notes":[]},{"n":2,"t":"大卫对亚吉说：「仆人所能做的事，王必知道。」亚吉对大卫说：「这样，我立你永远作我的护卫长。」","notes":[]},{"n":3,"t":"那时撒母耳已经死了，以色列众人为他哀哭，葬他在拉玛，就是在他本城里。扫罗曾在国内不容有交鬼的和行巫术的人。","notes":[]},{"n":4,"t":"非利士人聚集，来到书念安营；扫罗聚集以色列众人在基利波安营。","notes":[]},{"n":5,"t":"扫罗看见非利士的军旅就惧怕，心中发颤。","notes":[]},{"n":6,"t":"扫罗求问耶和华，耶和华却不借梦，或乌陵，或先知回答他。","notes":[]},{"n":7,"t":"扫罗吩咐臣仆说：「当为我找一个交鬼的妇人，我好去问她。」臣仆说：「在隐·多珥有一个交鬼的妇人。」","notes":[]},{"n":8,"t":"于是扫罗改了装，穿上别的衣服，带着两个人，夜里去见那妇人。扫罗说：「求你用交鬼的法术，将我所告诉你的死人，为我招上来。」","notes":[]},{"n":9,"t":"妇人对他说：「你知道扫罗从国中剪除交鬼的和行巫术的。你为何陷害我的性命，使我死呢？」","notes":[]},{"n":10,"t":"扫罗向妇人指着耶和华起誓说：「我指着永生的耶和华起誓，你必不因这事受刑。」","notes":[]},{"n":11,"t":"妇人说：「我为你招谁上来呢？」回答说：「为我招撒母耳上来。」","notes":[]},{"n":12,"t":"妇人看见撒母耳，就大声呼叫，对扫罗说：「你是扫罗，为什么欺哄我呢？」","notes":[]},{"n":13,"t":"王对妇人说：「不要惧怕，你看见了什么呢？」妇人对扫罗说：「我看见有神从地里上来。」","notes":[]},{"n":14,"t":"扫罗说：「他是怎样的形状？」妇人说：「有一个老人上来，身穿长衣。」扫罗知道是撒母耳，就屈身，脸伏于地下拜。","notes":[]},{"n":15,"t":"撒母耳对扫罗说：「你为什么搅扰我，招我上来呢？」扫罗回答说：「我甚窘急；因为非利士人攻击我，神也离开我，不再借先知或梦回答我。因此请你上来，好指示我应当怎样行。」","notes":[]},{"n":16,"t":"撒母耳说：「耶和华已经离开你，且与你为敌，你何必问我呢？","notes":[]},{"n":17,"t":"耶和华照他借我说的话，已经从你手里夺去国权，赐与别人，就是大卫。","notes":[]},{"n":18,"t":"因你没有听从耶和华的命令；他恼怒亚玛力人，你没有灭绝他们，所以今日耶和华向你这样行，","notes":[]},{"n":19,"t":"并且耶和华必将你和以色列人交在非利士人的手里。明日你和你众子必与我在一处了；耶和华必将以色列的军兵交在非利士人手里。」","notes":[]},{"n":20,"t":"扫罗猛然仆倒，挺身在地，因撒母耳的话甚是惧怕；那一昼一夜，没有吃什么，就毫无气力。","notes":[]},{"n":21,"t":"妇人到扫罗面前，见他极其惊恐，对他说：「婢女听从你的话，不顾惜自己的性命，遵从你所吩咐的。","notes":[]},{"n":22,"t":"现在求你听婢女的话，容我在你面前摆上一点食物，你吃了，可以有气力行路。」","notes":[]},{"n":23,"t":"扫罗不肯，说：「我不吃。」但他的仆人和妇人再三劝他，他才听了他们的话，从地上起来，坐在床上。","notes":[]},{"n":24,"t":"妇人急忙将家里的一只肥牛犊宰了，又拿面抟成无酵饼烤了，","notes":[]},{"n":25,"t":"摆在扫罗和他仆人面前。他们吃完，当夜就起身走了。","notes":[]}]},"29":{"heading":"非利士人不要大卫","verses":[{"n":1,"t":"非利士人将他们的军旅聚到亚弗；以色列人在耶斯列的泉旁安营。","notes":[]},{"n":2,"t":"非利士人的首领各率军队，或百或千，挨次前进；大卫和跟随他的人同着亚吉跟在后边。","notes":[]},{"n":3,"t":"非利士人的首领说：「这些希伯来人在这里做什么呢？」亚吉对他们说：「这不是以色列王扫罗的臣子大卫吗？他在我这里有些年日了。自从他投降我直到今日，我未曾见他有过错。」","notes":[]},{"n":4,"t":"非利士人的首领向亚吉发怒，对他说：「你要叫这人回你所安置他的地方，不可叫他同我们出战，恐怕他在阵上反为我们的敌人。他用什么与他主人复和呢？岂不是用我们这些人的首级吗？","notes":[]},{"n":5,"t":"从前以色列的妇女跳舞唱和说：『扫罗杀死千千，大卫杀死万万』，所说的不是这个大卫吗？」","notes":[]},{"n":6,"t":"亚吉叫大卫来，对他说：「我指着永生的耶和华起誓，你是正直人。你随我在军中出入，我看你甚好。自从你投奔我到如今，我未曾见你有什么过失；只是众首领不喜悦你。","notes":[]},{"n":7,"t":"现在你可以平平安安地回去，免得非利士人的首领不欢喜你。」","notes":[]},{"n":8,"t":"大卫对亚吉说：「我做了什么呢？自从仆人到你面前，直到今日，你查出我有什么过错，使我不去攻击主—我王的仇敌呢？」","notes":[]},{"n":9,"t":"亚吉说：「我知道你在我眼前是好人，如同神的使者一般；只是非利士人的首领说：『这人不可同我们出战。』","notes":[]},{"n":10,"t":"故此你和跟随你的人，就是你本主的仆人，要明日早晨起来，等到天亮回去吧！」","notes":[]},{"n":11,"t":"于是大卫和跟随他的人早晨起来，回往非利士地去。非利士人也上耶斯列去了。","notes":[]}]},"30":{"heading":"与亚玛力人争战","verses":[{"n":1,"t":"第三日，大卫和跟随他的人到了洗革拉。亚玛力人已经侵夺南地，攻破洗革拉，用火焚烧，","notes":[]},{"n":2,"t":"掳了城内的妇女和其中的大小人口，却没有杀一个，都带着走了。","notes":[]},{"n":3,"t":"大卫和跟随他的人到了那城，不料，城已烧毁，他们的妻子儿女都被掳去了。","notes":[]},{"n":4,"t":"大卫和跟随他的人就放声大哭，直哭得没有气力。","notes":[]},{"n":5,"t":"大卫的两个妻—耶斯列人亚希暖和作过拿八妻的迦密人亚比该，也被掳去了。","notes":[]},{"n":6,"t":"大卫甚是焦急，因众人为自己的儿女苦恼，说：「要用石头打死他。」大卫却倚靠耶和华—他的神，心里坚固。","notes":[]},{"n":7,"t":"大卫对亚希米勒的儿子祭司亚比亚他说：「请你将以弗得拿过来。」亚比亚他就将以弗得拿到大卫面前。","notes":[]},{"n":8,"t":"大卫求问耶和华说：「我追赶敌军，追得上追不上呢？」耶和华说：「你可以追，必追得上，都救得回来。」","notes":[]},{"n":9,"t":"于是，大卫和跟随他的六百人来到比梭溪；有不能前去的就留在那里。","notes":[]},{"n":10,"t":"大卫却带着四百人往前追赶，有二百人疲乏，不能过比梭溪，所以留在那里。","notes":[]},{"n":11,"t":"这四百人在田野遇见一个埃及人，就带他到大卫面前，给他饼吃，给他水喝，","notes":[]},{"n":12,"t":"又给他一块无花果饼，两个葡萄饼。他吃了，就精神复原；因为他三日三夜没有吃饼，没有喝水。","notes":[]},{"n":13,"t":"大卫问他说：「你是属谁的？你是哪里的人？」他回答说：「我是埃及的少年人，是亚玛力人的奴仆；因我三日前患病，我主人就把我撇弃了。","notes":[]},{"n":14,"t":"我们侵夺了基利提的南方和属犹大的地，并迦勒地的南方，又用火烧了洗革拉。」","notes":[]},{"n":15,"t":"大卫问他说：「你肯领我们到敌军那里不肯？」他回答说：「你要向我指着神起誓，不杀我，也不将我交在我主人手里，我就领你下到敌军那里。」","notes":[]},{"n":16,"t":"那人领大卫下去，见他们散在地上，吃喝跳舞，因为从非利士地和犹大地所掳来的财物甚多。","notes":[]},{"n":17,"t":"大卫从黎明直到次日晚上，击杀他们，除了四百骑骆驼的少年人之外，没有一个逃脱的。","notes":[]},{"n":18,"t":"亚玛力人所掳去的财物，大卫全都夺回，并救回他的两个妻来。","notes":[]},{"n":19,"t":"凡亚玛力人所掳去的，无论大小、儿女、财物，大卫都夺回来，没有失落一个。","notes":[]},{"n":20,"t":"大卫所夺来的牛群羊群，跟随他的人赶在原有的群畜前边，说：「这是大卫的掠物。」","notes":[]},{"n":21,"t":"大卫到了那疲乏不能跟随、留在比梭溪的二百人那里。他们出来迎接大卫并跟随的人。大卫前来问他们安。","notes":[]},{"n":22,"t":"跟随大卫人中的恶人和匪类说：「这些人既然没有和我们同去，我们所夺的财物就不分给他们，只将他们各人的妻子儿女给他们，使他们带去就是了。」","notes":[]},{"n":23,"t":"大卫说：「弟兄们，耶和华所赐给我们的，不可不分给他们；因为他保佑我们，将那攻击我们的敌军交在我们手里。","notes":[]},{"n":24,"t":"这事谁肯依从你们呢？上阵的得多少，看守器具的也得多少；应当大家平分。」","notes":[]},{"n":25,"t":"大卫定此为以色列的律例典章，从那日直到今日。","notes":[]},{"n":26,"t":"大卫到了洗革拉，从掠物中取些送给他朋友犹大的长老，说：「这是从耶和华仇敌那里夺来的，送你们为礼物。」","notes":[]},{"n":27,"t":"他送礼物给住伯特利的，南地拉末的，雅提珥的；","notes":[]},{"n":28,"t":"住亚罗珥的，息末的，以实提莫的；","notes":[]},{"n":29,"t":"住拉哈勒的，耶拉篾各城的，基尼各城的；","notes":[]},{"n":30,"t":"住何珥玛的，歌拉珊的，亚挞的；","notes":[]},{"n":31,"t":"住希伯仑的，并大卫和跟随他的人素来所到之处的人。","notes":[]}]},"31":{"heading":"扫罗和他儿子的死","verses":[{"n":1,"t":"非利士人与以色列人争战。以色列人在非利士人面前逃跑，在基利波有被杀仆倒的。","notes":[]},{"n":2,"t":"非利士人紧追扫罗和他儿子们，就杀了扫罗的儿子约拿单、亚比拿达、麦基舒亚。","notes":[]},{"n":3,"t":"势派甚大，扫罗被弓箭手追上，射伤甚重，","notes":[]},{"n":4,"t":"就吩咐拿他兵器的人说：「你拔出刀来，将我刺死，免得那些未受割礼的人来刺我，凌辱我。」但拿兵器的人甚惧怕，不肯刺他；扫罗就自己伏在刀上死了。","notes":[]},{"n":5,"t":"拿兵器的人见扫罗已死，也伏在刀上死了。","notes":[]},{"n":6,"t":"这样，扫罗和他三个儿子，与拿他兵器的人，以及跟随他的人，都一同死亡。","notes":[]},{"n":7,"t":"住平原那边并约旦河西的以色列人，见以色列军兵逃跑，扫罗和他儿子都死了，也就弃城逃跑。非利士人便来住在其中。","notes":[]},{"n":8,"t":"次日，非利士人来剥那被杀之人的衣服，看见扫罗和他三个儿子仆倒在基利波山，","notes":[]},{"n":9,"t":"就割下他的首级，剥了他的军装，打发人到非利士地的四境，报信与他们庙里的偶像和众民；","notes":["或译：送到"]},{"n":10,"t":"又将扫罗的军装放在亚斯她录庙里，将他的尸身钉在伯·珊的城墙上。","notes":[]},{"n":11,"t":"基列·雅比的居民听见非利士人向扫罗所行的事，","notes":[]},{"n":12,"t":"他们中间所有的勇士就起身，走了一夜，将扫罗和他儿子的尸身从伯·珊城墙上取下来，送到雅比那里，用火烧了；","notes":[]},{"n":13,"t":"将他们骸骨葬在雅比的垂丝柳树下，就禁食七日。","notes":[]}]}},"2SA":{"1":{"heading":"大卫听到扫罗的死讯","verses":[{"n":1,"t":"扫罗死后，大卫击杀亚玛力人回来，在洗革拉住了两天。","notes":[]},{"n":2,"t":"第三天，有一人从扫罗的营里出来，衣服撕裂，头蒙灰尘，到大卫面前伏地叩拜。","notes":[]},{"n":3,"t":"大卫问他说：「你从哪里来？」他说：「我从以色列的营里逃来。」","notes":[]},{"n":4,"t":"大卫又问他说：「事情怎样？请你告诉我。」他回答说：「百姓从阵上逃跑，也有许多人仆倒死亡；扫罗和他儿子约拿单也死了。」","notes":[]},{"n":5,"t":"大卫问报信的少年人说：「你怎么知道扫罗和他儿子约拿单死了呢？」","notes":[]},{"n":6,"t":"报信的少年人说：「我偶然到基利波山，看见扫罗伏在自己枪上，有战车、马兵紧紧地追他。","notes":[]},{"n":7,"t":"他回头看见我，就呼叫我。我说：『我在这里。』","notes":[]},{"n":8,"t":"他问我说：『你是什么人？』我说：『我是亚玛力人。』","notes":[]},{"n":9,"t":"他说：『请你来，将我杀死；因为痛苦抓住我，我的生命尚存。』","notes":[]},{"n":10,"t":"我准知他仆倒必不能活，就去将他杀死，把他头上的冠冕、臂上的镯子拿到我主这里。」","notes":[]},{"n":11,"t":"大卫就撕裂衣服，跟随他的人也是如此，","notes":[]},{"n":12,"t":"而且悲哀哭号，禁食到晚上，是因扫罗和他儿子约拿单，并耶和华的民以色列家的人，倒在刀下。","notes":[]},{"n":13,"t":"大卫问报信的少年人说：「你是哪里的人？」他说：「我是亚玛力客人的儿子。」","notes":[]},{"n":14,"t":"大卫说：「你伸手杀害耶和华的受膏者，怎么不畏惧呢？」","notes":[]},{"n":15,"t":"大卫叫了一个少年人来，说：「你去杀他吧！」","notes":[]},{"n":16,"t":"大卫对他说：「你流人血的罪归到自己的头上，因为你亲口作见证说：『我杀了耶和华的受膏者。』」少年人就把他杀了。","notes":[]},{"n":17,"t":"大卫作哀歌，吊扫罗和他儿子约拿单，","notes":[],"heads":["大卫为扫罗和约拿单作哀歌"]},{"n":18,"t":"且吩咐将这歌教导犹大人。这歌名叫「弓歌」，写在雅煞珥书上。","notes":[]},{"n":19,"t":"歌中说：以色列啊，你尊荣者在山上被杀！大英雄何竟死亡！","notes":[]},{"n":20,"t":"不要在迦特报告；不要在亚实基伦街上传扬；免得非利士的女子欢乐；免得未受割礼之人的女子矜夸。","notes":[]},{"n":21,"t":"基利波山哪，愿你那里没有雨露！愿你田地无土产可作供物！因为英雄的盾牌在那里被污丢弃；扫罗的盾牌仿佛未曾抹油。","notes":[]},{"n":22,"t":"约拿单的弓箭非流敌人的血不退缩；扫罗的刀剑非剖勇士的油不收回。","notes":[]},{"n":23,"t":"扫罗和约拿单—活时相悦相爱，死时也不分离—他们比鹰更快，比狮子还强。","notes":[]},{"n":24,"t":"以色列的女子啊，当为扫罗哭号！他曾使你们穿朱红色的美衣，使你们衣服有黄金的妆饰。","notes":[]},{"n":25,"t":"英雄何竟在阵上仆倒！约拿单何竟在山上被杀！","notes":[]},{"n":26,"t":"我兄约拿单哪，我为你悲伤！我甚喜悦你！你向我发的爱情奇妙非常，过于妇女的爱情。","notes":[]},{"n":27,"t":"英雄何竟仆倒！战具何竟灭没！","notes":[]}]},"2":{"heading":"大卫受膏作犹大王","verses":[{"n":1,"t":"此后，大卫问耶和华说：「我上犹大的一个城去可以吗？」耶和华说：「可以。」大卫说：「我上哪一个城去呢？」耶和华说：「上希伯仑去。」","notes":[]},{"n":2,"t":"于是大卫和他的两个妻—一个是耶斯列人亚希暖，一个是作过迦密人拿八妻的亚比该—都上那里去了。","notes":[]},{"n":3,"t":"大卫也将跟随他的人和他们各人的眷属一同带上去，住在希伯仑的城邑中。","notes":[]},{"n":4,"t":"犹大人来到希伯仑，在那里膏大卫作犹大家的王。有人告诉大卫说：「葬埋扫罗的是基列·雅比人。」","notes":[]},{"n":5,"t":"大卫就差人去见基列·雅比人，对他们说：「你们厚待你们的主—扫罗，将他葬埋。愿耶和华赐福与你们！","notes":[]},{"n":6,"t":"你们既行了这事，愿耶和华以慈爱诚实待你们，我也要为此厚待你们。","notes":[]},{"n":7,"t":"现在你们的主—扫罗死了，犹大家已经膏我作他们的王，所以你们要刚强奋勇。」","notes":[]},{"n":8,"t":"扫罗的元帅尼珥的儿子押尼珥，曾将扫罗的儿子伊施波设带过河，到玛哈念，","notes":[],"heads":["伊施波设作以色列王"]},{"n":9,"t":"立他作王，治理基列、亚书利、耶斯列、以法莲、便雅悯，和以色列众人。","notes":[]},{"n":10,"t":"扫罗的儿子伊施波设登基的时候年四十岁，作以色列王二年；惟独犹大家归从大卫。","notes":[]},{"n":11,"t":"大卫在希伯仑作犹大家的王，共七年零六个月。","notes":[]},{"n":12,"t":"尼珥的儿子押尼珥和扫罗的儿子伊施波设的仆人从玛哈念出来，往基遍去。","notes":[],"heads":["扫罗家和大卫家争战"]},{"n":13,"t":"洗鲁雅的儿子约押和大卫的仆人也出来，在基遍池旁与他们相遇；一班坐在池这边，一班坐在池那边。","notes":[]},{"n":14,"t":"押尼珥对约押说：「让少年人起来，在我们面前戏耍吧！」约押说：「可以。」","notes":[]},{"n":15,"t":"就按着定数起来：属扫罗儿子伊施波设的便雅悯人过去十二名，大卫的仆人也过去十二名，","notes":[]},{"n":16,"t":"彼此揪头，用刀刺肋，一同仆倒。所以，那地叫做希利甲·哈素林，就在基遍。","notes":[]},{"n":17,"t":"那日的战事凶猛，押尼珥和以色列人败在大卫的仆人面前。","notes":[]},{"n":18,"t":"在那里有洗鲁雅的三个儿子：约押、亚比筛、亚撒黑。亚撒黑脚快如野鹿一般；","notes":[]},{"n":19,"t":"亚撒黑追赶押尼珥，直追赶他不偏左右。","notes":[]},{"n":20,"t":"押尼珥回头说：「你是亚撒黑吗？」回答说：「是。」","notes":[]},{"n":21,"t":"押尼珥对他说：「你或转向左转向右，拿住一个少年人，剥去他的战衣。」亚撒黑却不肯转开不追赶他。","notes":[]},{"n":22,"t":"押尼珥又对亚撒黑说：「你转开不追赶我吧！我何必杀你呢？若杀你，有什么脸见你哥哥约押呢？」","notes":[]},{"n":23,"t":"亚撒黑仍不肯转开。故此，押尼珥就用枪鐏刺入他的肚腹，甚至枪从背后透出，亚撒黑就在那里仆倒而死。众人赶到亚撒黑仆倒而死的地方，就都站住。","notes":[]},{"n":24,"t":"约押和亚比筛追赶押尼珥，日落的时候，到了通基遍旷野的路旁，基亚对面的亚玛山。","notes":[]},{"n":25,"t":"便雅悯人聚集，跟随押尼珥站在一个山顶上。","notes":[]},{"n":26,"t":"押尼珥呼叫约押说：「刀剑岂可永远杀人吗？你岂不知终久必有苦楚吗？你要等何时才叫百姓回去、不追赶弟兄呢？」","notes":[]},{"n":27,"t":"约押说：「我指着永生的神起誓：你若不说戏耍的那句话，今日早晨百姓就回去，不追赶弟兄了。」","notes":[]},{"n":28,"t":"于是约押吹角，众民就站住，不再追赶以色列人，也不再打仗了。","notes":[]},{"n":29,"t":"押尼珥和跟随他的人整夜经过亚拉巴，过约旦河，走过毕伦，到了玛哈念。","notes":[]},{"n":30,"t":"约押追赶押尼珥回来，聚集众民，见大卫的仆人中缺少了十九个人和亚撒黑。","notes":[]},{"n":31,"t":"但大卫的仆人杀了便雅悯人和跟随押尼珥的人，共三百六十名。","notes":[]},{"n":32,"t":"众人将亚撒黑送到伯利恒，葬在他父亲的坟墓里。约押和跟随他的人走了一夜，天亮的时候到了希伯仑。","notes":[]}]},"3":{"heading":"大卫的儿子们","verses":[{"n":1,"t":"扫罗家和大卫家争战许久。大卫家日见强盛；扫罗家日见衰弱。","notes":[]},{"n":2,"t":"大卫在希伯仑得了几个儿子：长子暗嫩是耶斯列人亚希暖所生的；","notes":[]},{"n":3,"t":"次子基利押是作过迦密人拿八的妻亚比该所生的；三子押沙龙是基述王达买的女儿玛迦所生的；","notes":["在历代志上三章一节作但以利"]},{"n":4,"t":"四子亚多尼雅是哈及所生的；五子示法提雅是亚比她所生的；","notes":[]},{"n":5,"t":"六子以特念是大卫的妻以格拉所生的。大卫这六个儿子都是在希伯仑生的。","notes":[]},{"n":6,"t":"扫罗家和大卫家争战的时候，押尼珥在扫罗家大有权势。","notes":[],"heads":["押尼珥投效大卫"]},{"n":7,"t":"扫罗有一妃嫔，名叫利斯巴，是爱亚的女儿。一日，伊施波设对押尼珥说：「你为什么与我父的妃嫔同房呢？」","notes":[]},{"n":8,"t":"押尼珥因伊施波设的话就甚发怒，说：「我岂是犹大的狗头呢？我恩待你父扫罗的家和他的弟兄、朋友，不将你交在大卫手里，今日你竟为这妇人责备我吗？","notes":[]},{"n":9,"t":"我若不照着耶和华起誓应许大卫的话行，废去扫罗的位，建立大卫的位，使他治理以色列和犹大，从但直到别是巴，愿神重重地降罚与我！」","notes":[],"end":10},{"n":11,"t":"伊施波设惧怕押尼珥，不敢回答一句。","notes":[]},{"n":12,"t":"押尼珥打发人去见大卫，替他说：「这国归谁呢？」又说：「你与我立约，我必帮助你，使以色列人都归服你。」","notes":[]},{"n":13,"t":"大卫说：「好！我与你立约。但有一件，你来见我面的时候，若不将扫罗的女儿米甲带来，必不得见我的面。」","notes":[]},{"n":14,"t":"大卫就打发人去见扫罗的儿子伊施波设，说：「你要将我的妻米甲归还我；她是我从前用一百非利士人的阳皮所聘定的。」","notes":[]},{"n":15,"t":"伊施波设就打发人去，将米甲从拉亿的儿子、她丈夫帕铁那里接回来。","notes":[]},{"n":16,"t":"米甲的丈夫跟着她，一面走一面哭，直跟到巴户琳。押尼珥说：「你回去吧！」帕铁就回去了。","notes":[]},{"n":17,"t":"押尼珥对以色列长老说：「从前你们愿意大卫作王治理你们，","notes":[]},{"n":18,"t":"现在你们可以照心愿而行。因为耶和华曾论到大卫说：『我必借我仆人大卫的手，救我民以色列脱离非利士人和众仇敌的手。』」","notes":[]},{"n":19,"t":"押尼珥也用这话说给便雅悯人听，又到希伯仑，将以色列人和便雅悯全家一切所喜悦的事说给大卫听。","notes":[]},{"n":20,"t":"押尼珥带着二十个人来到希伯仑见大卫，大卫就为押尼珥和他带来的人设摆筵席。","notes":[]},{"n":21,"t":"押尼珥对大卫说：「我要起身去招聚以色列众人来见我主我王，与你立约，你就可以照着心愿作王。」于是大卫送押尼珥去，押尼珥就平平安安地去了。","notes":[]},{"n":22,"t":"约押和大卫的仆人攻击敌军，带回许多的掠物。那时押尼珥不在希伯仑大卫那里，因大卫已经送他去，他也平平安安地去了。","notes":[],"heads":["押尼珥被杀"]},{"n":23,"t":"约押和跟随他的全军到了，就有人告诉约押说：「尼珥的儿子押尼珥来见王，王送他去，他也平平安安地去了。」","notes":[]},{"n":24,"t":"约押去见王说：「你这是做什么呢？押尼珥来见你，你为何送他去，他就踪影不见了呢？","notes":[]},{"n":25,"t":"你当晓得，尼珥的儿子押尼珥来是要诓哄你，要知道你的出入和你一切所行的事。」","notes":[]},{"n":26,"t":"约押从大卫那里出来，就打发人去追赶押尼珥，在西拉井追上他，将他带回来，大卫却不知道。","notes":[]},{"n":27,"t":"押尼珥回到希伯仑，约押领他到城门的瓮洞，假作要与他说机密话，就在那里刺透他的肚腹，他便死了。这是报杀他兄弟亚撒黑的仇。","notes":[]},{"n":28,"t":"大卫听见了，就说：「流尼珥的儿子押尼珥的血，这罪在耶和华面前必永不归我和我的国。","notes":[]},{"n":29,"t":"愿流他血的罪归到约押头上和他父的全家；又愿约押家不断有患漏症的，长大麻风的，架拐而行的，被刀杀死的，缺乏饮食的。」","notes":[]},{"n":30,"t":"约押和他兄弟亚比筛杀了押尼珥，是因押尼珥在基遍争战的时候杀了他们的兄弟亚撒黑。","notes":[]},{"n":31,"t":"大卫吩咐约押和跟随他的众人说：「你们当撕裂衣服，腰束麻布，在押尼珥棺前哀哭。」大卫王也跟在棺后。","notes":[],"heads":["安葬押尼珥"]},{"n":32,"t":"他们将押尼珥葬在希伯仑。王在押尼珥的墓旁放声而哭，众民也都哭了。","notes":[]},{"n":33,"t":"王为押尼珥举哀，说：押尼珥何竟像愚顽人死呢？","notes":[]},{"n":34,"t":"你手未曾捆绑，脚未曾锁住。你死，如人死在罪孽之辈手下一样。于是众民又为押尼珥哀哭。","notes":[]},{"n":35,"t":"日头未落的时候，众民来劝大卫吃饭，但大卫起誓说：「我若在日头未落以前吃饭，或吃别物，愿神重重地降罚与我！」","notes":[]},{"n":36,"t":"众民知道了就都喜悦。凡王所行的，众民无不喜悦。","notes":[]},{"n":37,"t":"那日，以色列众民才知道杀尼珥的儿子押尼珥并非出于王意。","notes":[]},{"n":38,"t":"王对臣仆说：「你们岂不知今日以色列人中死了一个作元帅的大丈夫吗？","notes":[]},{"n":39,"t":"我虽然受膏为王，今日还是软弱；这洗鲁雅的两个儿子比我刚强。愿耶和华照着恶人所行的恶报应他。」","notes":[]}]},"4":{"heading":"伊施波设被杀","verses":[{"n":1,"t":"扫罗的儿子伊施波设听见押尼珥死在希伯仑，手就发软；以色列众人也都惊惶。","notes":[]},{"n":2,"t":"扫罗的儿子伊施波设有两个军长，一名巴拿，一名利甲，是便雅悯支派、比录人临门的儿子。比录也属便雅悯。","notes":[]},{"n":3,"t":"比录人早先逃到基他音，在那里寄居，直到今日。","notes":[]},{"n":4,"t":"扫罗的儿子约拿单有一个儿子名叫米非波设，是瘸腿的。扫罗和约拿单死亡的消息从耶斯列传到的时候，他才五岁。他乳母抱着他逃跑；因为跑得太急，孩子掉在地上，腿就瘸了。","notes":[]},{"n":5,"t":"一日，比录人临门的两个儿子利甲和巴拿出去，约在午热的时候到了伊施波设的家；伊施波设正睡午觉。","notes":[]},{"n":6,"t":"他们进了房子，假作要取麦子，就刺透伊施波设的肚腹，逃跑了。","notes":[]},{"n":7,"t":"他们进房子的时候，伊施波设正在卧房里躺在床上，他们将他杀死，割了他的首级，拿着首级在亚拉巴走了一夜，","notes":[]},{"n":8,"t":"将伊施波设的首级拿到希伯仑见大卫王，说：「王的仇敌扫罗曾寻索王的性命。看哪，这是他儿子伊施波设的首级；耶和华今日为我主我王在扫罗和他后裔的身上报了仇。」","notes":[]},{"n":9,"t":"大卫对比录人临门的儿子利甲和他兄弟巴拿说：「我指着救我性命脱离一切苦难、永生的耶和华起誓：","notes":[]},{"n":10,"t":"从前有人报告我说，扫罗死了，他自以为报好消息；我就拿住他，将他杀在洗革拉，这就作了他报消息的赏赐。","notes":[]},{"n":11,"t":"何况恶人将义人杀在他的床上，我岂不向你们讨流他血的罪、从世上除灭你们呢？」","notes":[]},{"n":12,"t":"于是大卫吩咐少年人将他们杀了，砍断他们的手脚，挂在希伯仑的池旁，却将伊施波设的首级葬在希伯仑、押尼珥的坟墓里。","notes":[]}]},"5":{"heading":"大卫作犹大和以色列王","verses":[{"n":1,"t":"以色列众支派来到希伯仑见大卫，说：「我们原是你的骨肉。","notes":[]},{"n":2,"t":"从前扫罗作我们王的时候，率领以色列人出入的是你；耶和华也曾应许你说：『你必牧养我的民以色列，作以色列的君。』」","notes":[]},{"n":3,"t":"于是以色列的长老都来到希伯仑见大卫王，大卫在希伯仑耶和华面前与他们立约，他们就膏大卫作以色列的王。","notes":[]},{"n":4,"t":"大卫登基的时候年三十岁，在位四十年；","notes":[]},{"n":5,"t":"在希伯仑作犹大王七年零六个月，在耶路撒冷作以色列和犹大王三十三年。","notes":[]},{"n":6,"t":"大卫和跟随他的人到了耶路撒冷，要攻打住那地方的耶布斯人。耶布斯人对大卫说：「你若不赶出瞎子、瘸子，必不能进这地方」；心里想大卫决不能进去。","notes":[]},{"n":7,"t":"然而大卫攻取锡安的保障，就是大卫的城。","notes":[]},{"n":8,"t":"当日，大卫说：「谁攻打耶布斯人，当上水沟攻打我心里所恨恶的瘸子、瞎子。」从此有俗语说：「在那里有瞎子、瘸子，他不能进屋去。」","notes":[]},{"n":9,"t":"大卫住在保障里，给保障起名叫大卫城。大卫又从米罗以里，周围筑墙。","notes":[]},{"n":10,"t":"大卫日见强盛，因为耶和华—万军之神与他同在。","notes":[]},{"n":11,"t":"泰尔王希兰将香柏木运到大卫那里，又差遣使者和木匠、石匠给大卫建造宫殿。","notes":[]},{"n":12,"t":"大卫就知道耶和华坚立他作以色列王，又为自己的民以色列使他的国兴旺。","notes":[]},{"n":13,"t":"大卫离开希伯仑之后，在耶路撒冷又立后妃，又生儿女。","notes":[]},{"n":14,"t":"在耶路撒冷所生的儿子是沙母亚、朔罢、拿单、所罗门、","notes":[]},{"n":15,"t":"益辖、以利书亚、尼斐、雅非亚、","notes":[]},{"n":16,"t":"以利沙玛、以利雅大、以利法列。","notes":[]},{"n":17,"t":"非利士人听见人膏大卫作以色列王，非利士众人就上来寻索大卫；大卫听见，就下到保障。","notes":[],"heads":["战胜非利士人"]},{"n":18,"t":"非利士人来了，布散在利乏音谷。","notes":[]},{"n":19,"t":"大卫求问耶和华说：「我可以上去攻打非利士人吗？你将他们交在我手里吗？」耶和华说：「你可以上去，我必将非利士人交在你手里。」","notes":[]},{"n":20,"t":"大卫来到巴力·毗拉心，在那里击杀非利士人，说：「耶和华在我面前冲破敌人，如同水冲去一般。」因此称那地方为巴力·毗拉心。","notes":[]},{"n":21,"t":"非利士人将偶像撇在那里，大卫和跟随他的人拿去了。","notes":[]},{"n":22,"t":"非利士人又上来，布散在利乏音谷。","notes":[]},{"n":23,"t":"大卫求问耶和华；耶和华说：「不要一直地上去，要转到他们后头，从桑林对面攻打他们。","notes":[]},{"n":24,"t":"你听见桑树梢上有脚步的声音，就要急速前去，因为那时耶和华已经在你前头去攻打非利士人的军队。」","notes":[]},{"n":25,"t":"大卫就遵着耶和华所吩咐的去行，攻打非利士人，从迦巴直到基色。","notes":[]}]},"6":{"heading":"运约柜到耶路撒冷","verses":[{"n":1,"t":"大卫又聚集以色列中所有挑选的人三万。","notes":[]},{"n":2,"t":"大卫起身，率领跟随他的众人前往，要从巴拉·犹大将神的约柜运来；这约柜就是坐在二基路伯上万军之耶和华留名的约柜。","notes":[]},{"n":3,"t":"他们将神的约柜从冈上亚比拿达的家里抬出来，放在新车上；亚比拿达的两个儿子乌撒和亚希约赶这新车。","notes":[]},{"n":4,"t":"他们将神的约柜从冈上亚比拿达家里抬出来的时候，亚希约在柜前行走。","notes":[]},{"n":5,"t":"大卫和以色列的全家在耶和华面前，用松木制造的各样乐器和琴、瑟、鼓、钹、锣，作乐跳舞。","notes":[]},{"n":6,"t":"到了拿艮的禾场，因为牛失前蹄，乌撒就伸手扶住神的约柜。","notes":["或译：惊跳"]},{"n":7,"t":"神耶和华向乌撒发怒，因这错误击杀他，他就死在神的约柜旁。","notes":[]},{"n":8,"t":"大卫因耶和华击杀乌撒，心里愁烦，就称那地方为毗列斯·乌撒，直到今日。","notes":["原文是闯杀"]},{"n":9,"t":"那日，大卫惧怕耶和华，说：「耶和华的约柜怎可运到我这里来？」","notes":[]},{"n":10,"t":"于是大卫不肯将耶和华的约柜运进大卫的城，却运到迦特人俄别·以东的家中。","notes":[]},{"n":11,"t":"耶和华的约柜在迦特人俄别·以东家中三个月；耶和华赐福给俄别·以东和他的全家。","notes":[]},{"n":12,"t":"有人告诉大卫王说：「耶和华因为约柜赐福给俄别·以东的家和一切属他的。」大卫就去，欢欢喜喜地将神的约柜从俄别·以东家中抬到大卫的城里。","notes":[]},{"n":13,"t":"抬耶和华约柜的人走了六步，大卫就献牛与肥羊为祭。","notes":[]},{"n":14,"t":"大卫穿着细麻布的以弗得，在耶和华面前极力跳舞。","notes":[]},{"n":15,"t":"这样，大卫和以色列的全家欢呼吹角，将耶和华的约柜抬上来。","notes":[]},{"n":16,"t":"耶和华的约柜进了大卫城的时候，扫罗的女儿米甲从窗户里观看，见大卫王在耶和华面前踊跃跳舞，心里就轻视他。","notes":[]},{"n":17,"t":"众人将耶和华的约柜请进去，安放在所预备的地方，就是在大卫所搭的帐幕里。大卫在耶和华面前献燔祭和平安祭。","notes":[]},{"n":18,"t":"大卫献完了燔祭和平安祭，就奉万军之耶和华的名给民祝福，","notes":[]},{"n":19,"t":"并且分给以色列众人，无论男女，每人一个饼，一块肉，一个葡萄饼；众人就各回各家去了。","notes":[]},{"n":20,"t":"大卫回家要给眷属祝福；扫罗的女儿米甲出来迎接他，说：「以色列王今日在臣仆的婢女眼前露体，如同一个轻贱人无耻露体一样，有好大的荣耀啊！」","notes":[]},{"n":21,"t":"大卫对米甲说：「这是在耶和华面前；耶和华已拣选我，废了你父和你父的全家，立我作耶和华民以色列的君，所以我必在耶和华面前跳舞。","notes":[]},{"n":22,"t":"我也必更加卑微，自己看为轻贱。你所说的那些婢女，她们倒要尊敬我。」","notes":[]},{"n":23,"t":"扫罗的女儿米甲，直到死日，没有生养儿女。","notes":[]}]},"7":{"heading":"拿单传信息给大卫","verses":[{"n":1,"t":"王住在自己宫中，耶和华使他安靖，不被四围的仇敌扰乱。","notes":[]},{"n":2,"t":"那时，王对先知拿单说：「看哪，我住在香柏木的宫中，神的约柜反在幔子里。」","notes":[]},{"n":3,"t":"拿单对王说：「你可以照你的心意而行，因为耶和华与你同在。」","notes":[]},{"n":4,"t":"当夜，耶和华的话临到拿单说：","notes":[]},{"n":5,"t":"「你去告诉我仆人大卫，说耶和华如此说：『你岂可建造殿宇给我居住呢？","notes":[]},{"n":6,"t":"自从我领以色列人出埃及直到今日，我未曾住过殿宇，常在会幕和帐幕中行走。","notes":[]},{"n":7,"t":"凡我同以色列人所走的地方，我何曾向以色列一支派的士师，就是我吩咐牧养我民以色列的说：你们为何不给我建造香柏木的殿宇呢？』","notes":[]},{"n":8,"t":"「现在，你要告诉我仆人大卫，说万军之耶和华如此说：『我从羊圈中将你召来，叫你不再跟从羊群，立你作我民以色列的君。","notes":[]},{"n":9,"t":"你无论往哪里去，我常与你同在，剪除你的一切仇敌。我必使你得大名，好像世上大大有名的人一样。","notes":[]},{"n":10,"t":"我必为我民以色列选定一个地方，栽培他们，使他们住自己的地方，不再迁移；凶恶之子也不像从前扰害他们，","notes":[]},{"n":11,"t":"并不像我命士师治理我民以色列的时候一样。我必使你安靖，不被一切仇敌扰乱，并且我—耶和华应许你，必为你建立家室。","notes":[]},{"n":12,"t":"你寿数满足、与你列祖同睡的时候，我必使你的后裔接续你的位；我也必坚定他的国。","notes":[]},{"n":13,"t":"他必为我的名建造殿宇；我必坚定他的国位，直到永远。","notes":[]},{"n":14,"t":"我要作他的父，他要作我的子；他若犯了罪，我必用人的杖责打他，用人的鞭责罚他。","notes":[]},{"n":15,"t":"但我的慈爱仍不离开他，像离开在你面前所废弃的扫罗一样。","notes":[]},{"n":16,"t":"你的家和你的国必在我面前永远坚立。你的国位也必坚定，直到永远。』」","notes":["原文是你"]},{"n":17,"t":"拿单就按这一切话，照这默示，告诉大卫。","notes":[]},{"n":18,"t":"于是大卫王进去，坐在耶和华面前，说：「主耶和华啊，我是谁？我的家算什么？你竟使我到这地步呢？","notes":[],"heads":["大卫的祈祷和感恩"]},{"n":19,"t":"主耶和华啊，这在你眼中还看为小，又应许你仆人的家至于久远。主耶和华啊，这岂是人所常遇的事吗？","notes":[]},{"n":20,"t":"主耶和华啊，我还有何言可以对你说呢？因为你知道你的仆人。","notes":[]},{"n":21,"t":"你行这大事使仆人知道，是因你所应许的话，也是照你的心意。","notes":[]},{"n":22,"t":"主耶和华啊，你本为大，照我们耳中听见，没有可比你的；除你以外再无神。","notes":[]},{"n":23,"t":"世上有何民能比你的民以色列呢？你从埃及救赎他们作自己的子民，又在你赎出来的民面前行大而可畏的事，驱逐列邦人和他们的神，显出你的大名。","notes":[]},{"n":24,"t":"你曾坚立你的民以色列作你的子民，直到永远；你—耶和华也作了他们的神。","notes":[]},{"n":25,"t":"「耶和华神啊，你所应许仆人和仆人家的话，求你坚定，直到永远；照你所说的而行。","notes":[]},{"n":26,"t":"愿人永远尊你的名为大，说：『万军之耶和华是治理以色列的神。』这样，你仆人大卫的家必在你面前坚立。","notes":[]},{"n":27,"t":"万军之耶和华—以色列的神啊，因你启示你的仆人说：『我必为你建立家室』，所以仆人大胆向你如此祈祷。","notes":[]},{"n":28,"t":"「主耶和华啊，惟有你是神。你的话是真实的；你也应许将这福气赐给仆人。","notes":[]},{"n":29,"t":"现在求你赐福与仆人的家，可以永存在你面前。主耶和华啊，这是你所应许的。愿你永远赐福与仆人的家！」","notes":[]}]},"8":{"heading":"耶和华使大卫得胜","verses":[{"n":1,"t":"此后，大卫攻打非利士人，把他们治服，从他们手下夺取了京城的权柄；","notes":["原文是母城的嚼环"]},{"n":2,"t":"又攻打摩押人，使他们躺卧在地上，用绳量一量：量二绳的杀了，量一绳的存留。摩押人就归服大卫，给他进贡。","notes":[]},{"n":3,"t":"琐巴王利合的儿子哈大底谢往大河去，要夺回他的国权。大卫就攻打他，","notes":[]},{"n":4,"t":"擒拿了他的马兵一千七百，步兵二万，将拉战车的马砍断蹄筋，但留下一百辆车的马。","notes":[]},{"n":5,"t":"大马士革的亚兰人来帮助琐巴王哈大底谢，大卫就杀了亚兰人二万二千。","notes":[]},{"n":6,"t":"于是大卫在大马士革的亚兰地设立防营，亚兰人就归服他，给他进贡。大卫无论往哪里去，耶和华都使他得胜。","notes":[]},{"n":7,"t":"他夺了哈大底谢臣仆所拿的金盾牌，带到耶路撒冷。","notes":[]},{"n":8,"t":"大卫王又从属哈大底谢的比他和比罗他城中夺取了许多的铜。","notes":[]},{"n":9,"t":"哈马王陀以听见大卫杀败哈大底谢的全军，","notes":[]},{"n":10,"t":"就打发他儿子约兰去见大卫王，问他的安，为他祝福，因为他杀败了哈大底谢（原来陀以与哈大底谢常常争战）。约兰带了金银铜的器皿来，","notes":[]},{"n":11,"t":"大卫王将这些器皿和他治服各国所得来的金银都分别为圣，献给耶和华，","notes":[]},{"n":12,"t":"就是从亚兰、摩押、亚扪、非利士、亚玛力人所得来的，以及从琐巴王利合的儿子哈大底谢所掠之物。","notes":[]},{"n":13,"t":"大卫在盐谷击杀了亚兰一万八千人回来，就得了大名；","notes":["或译：以东，见诗篇六十篇诗题"]},{"n":14,"t":"又在以东全地设立防营，以东人就都归服大卫。大卫无论往哪里去，耶和华都使他得胜。","notes":[]},{"n":15,"t":"大卫作以色列众人的王，又向众民秉公行义。","notes":[]},{"n":16,"t":"洗鲁雅的儿子约押作元帅；亚希律的儿子约沙法作史官；","notes":[]},{"n":17,"t":"亚希突的儿子撒督和亚比亚他的儿子亚希米勒作祭司长；西莱雅作书记；","notes":[]},{"n":18,"t":"耶何耶大的儿子比拿雅统辖基利提人和比利提人。大卫的众子都作领袖。","notes":[]}]},"9":{"heading":"大卫和米非波设","verses":[{"n":1,"t":"大卫问说：「扫罗家还有剩下的人没有？我要因约拿单的缘故向他施恩。」","notes":[]},{"n":2,"t":"扫罗家有一个仆人，名叫洗巴，有人叫他来见大卫，王问他说：「你是洗巴吗？」回答说：「仆人是。」","notes":[]},{"n":3,"t":"王说：「扫罗家还有人没有？我要照神的慈爱恩待他。」洗巴对王说：「还有约拿单的一个儿子，是瘸腿的。」","notes":[]},{"n":4,"t":"王说：「他在哪里？」洗巴对王说：「他在罗·底巴，亚米利的儿子玛吉家里。」","notes":[]},{"n":5,"t":"于是大卫王打发人去，从罗·底巴、亚米利的儿子玛吉家里召了他来。","notes":[]},{"n":6,"t":"扫罗的孙子、约拿单的儿子米非波设来见大卫，伏地叩拜。大卫说：「米非波设！」米非波设说：「仆人在此。」","notes":[]},{"n":7,"t":"大卫说：「你不要惧怕，我必因你父亲约拿单的缘故施恩与你，将你祖父扫罗的一切田地都归还你；你也可以常与我同席吃饭。」","notes":[]},{"n":8,"t":"米非波设又叩拜，说：「仆人算什么，不过如死狗一般，竟蒙王这样眷顾！」","notes":[]},{"n":9,"t":"王召了扫罗的仆人洗巴来，对他说：「我已将属扫罗和他的一切家产都赐给你主人的儿子了。","notes":[]},{"n":10,"t":"你和你的众子、仆人要为你主人的儿子米非波设耕种田地，把所产的拿来供他食用；他却要常与我同席吃饭。」洗巴有十五个儿子，二十个仆人。","notes":[]},{"n":11,"t":"洗巴对王说：「凡我主我王吩咐仆人的，仆人都必遵行。」王又说：「米非波设必与我同席吃饭，如王的儿子一样。」","notes":[]},{"n":12,"t":"米非波设有一个小儿子，名叫米迦。凡住在洗巴家里的人都作了米非波设的仆人。","notes":[]},{"n":13,"t":"于是米非波设住在耶路撒冷，常与王同席吃饭。他两腿都是瘸的。","notes":[]}]},"10":{"heading":"击败亚扪人和亚兰人","verses":[{"n":1,"t":"此后，亚扪人的王死了，他儿子哈嫩接续他作王。","notes":[]},{"n":2,"t":"大卫说：「我要照哈嫩的父亲拿辖厚待我的恩典厚待哈嫩。」于是大卫差遣臣仆，为他丧父安慰他。大卫的臣仆到了亚扪人的境内。","notes":[]},{"n":3,"t":"但亚扪人的首领对他们的主哈嫩说：「大卫差人来安慰你，你想他是尊敬你父亲吗？他差臣仆来不是详察窥探、要倾覆这城吗？」","notes":[]},{"n":4,"t":"哈嫩便将大卫臣仆的胡须剃去一半，又割断他们下半截的衣服，使他们露出下体，打发他们回去。","notes":[]},{"n":5,"t":"有人告诉大卫，他就差人去迎接他们，（因为他们甚觉羞耻），告诉他们说：「可以住在耶利哥，等到胡须长起再回来。」","notes":[]},{"n":6,"t":"亚扪人知道大卫憎恶他们，就打发人去，招募伯·利合的亚兰人和琐巴的亚兰人，步兵二万，与玛迦王的人一千、陀伯人一万二千。","notes":[]},{"n":7,"t":"大卫听见了，就差派约押统带勇猛的全军出去。","notes":[]},{"n":8,"t":"亚扪人出来，在城门前摆阵；琐巴与利合的亚兰人、陀伯人，并玛迦人，另在郊野摆阵。","notes":[]},{"n":9,"t":"约押看见敌人在他前后摆阵，就从以色列军中挑选精兵，使他们对着亚兰人摆阵。","notes":[]},{"n":10,"t":"其余的兵交与他兄弟亚比筛，对着亚扪人摆阵。","notes":[]},{"n":11,"t":"约押对亚比筛说：「亚兰人若强过我，你就来帮助我；亚扪人若强过你，我就去帮助你。","notes":[]},{"n":12,"t":"我们都当刚强，为本国的民和神的城邑作大丈夫。愿耶和华凭他的意旨而行！」","notes":[]},{"n":13,"t":"于是，约押和跟随他的人前进攻打亚兰人；亚兰人在约押面前逃跑。","notes":[]},{"n":14,"t":"亚扪人见亚兰人逃跑，他们也在亚比筛面前逃跑进城。约押就离开亚扪人那里，回耶路撒冷去了。","notes":[]},{"n":15,"t":"亚兰人见自己被以色列人打败，就又聚集。","notes":[]},{"n":16,"t":"哈大底谢差遣人，将大河那边的亚兰人调来；他们到了希兰，哈大底谢的将军朔法率领他们。","notes":[]},{"n":17,"t":"有人告诉大卫，他就聚集以色列众人，过约旦河，来到希兰。亚兰人迎着大卫摆阵，与他打仗。","notes":[]},{"n":18,"t":"亚兰人在以色列人面前逃跑；大卫杀了亚兰七百辆战车的人，四万马兵，又杀了亚兰的将军朔法。","notes":[]},{"n":19,"t":"属哈大底谢的诸王见自己被以色列人打败，就与以色列人和好，归服他们。于是亚兰人不敢再帮助亚扪人了。","notes":[]}]},"11":{"heading":"大卫和拔示巴","verses":[{"n":1,"t":"过了一年，到列王出战的时候，大卫又差派约押，率领臣仆和以色列众人出战。他们就打败亚扪人，围攻拉巴。大卫仍住在耶路撒冷。","notes":[]},{"n":2,"t":"一日，太阳平西，大卫从床上起来，在王宫的平顶上游行，看见一个妇人沐浴，容貌甚美，","notes":[]},{"n":3,"t":"大卫就差人打听那妇人是谁。有人说：「她是以连的女儿，赫人乌利亚的妻拔示巴。」","notes":[]},{"n":4,"t":"大卫差人去，将妇人接来；那时她的月经才得洁净。她来了，大卫与她同房，她就回家去了。","notes":[]},{"n":5,"t":"于是她怀了孕，打发人去告诉大卫说：「我怀了孕。」","notes":[]},{"n":6,"t":"大卫差人到约押那里，说：「你打发赫人乌利亚到我这里来。」约押就打发乌利亚去见大卫。","notes":[]},{"n":7,"t":"乌利亚来了，大卫问约押好，也问兵好，又问争战的事怎样。","notes":[]},{"n":8,"t":"大卫对乌利亚说：「你回家去，洗洗脚吧！」乌利亚出了王宫，随后王送他一分食物。","notes":[]},{"n":9,"t":"乌利亚却和他主人的仆人一同睡在宫门外，没有回家去。","notes":[]},{"n":10,"t":"有人告诉大卫说：「乌利亚没有回家去。」大卫就问乌利亚说：「你从远路上来，为什么不回家去呢？」","notes":[]},{"n":11,"t":"乌利亚对大卫说：「约柜和以色列与犹大兵都住在棚里，我主约押和我主的仆人都在田野安营，我岂可回家吃喝、与妻子同寝呢？我敢在王面前起誓：我决不行这事！」","notes":["或译：王","原文是我指着王和王的性命起誓"]},{"n":12,"t":"大卫吩咐乌利亚说：「你今日仍住在这里，明日我打发你去。」于是乌利亚那日和次日住在耶路撒冷。","notes":[]},{"n":13,"t":"大卫召了乌利亚来，叫他在自己面前吃喝，使他喝醉。到了晚上，乌利亚出去与他主的仆人一同住宿，还没有回到家里去。","notes":[]},{"n":14,"t":"次日早晨，大卫写信与约押，交乌利亚随手带去。","notes":[]},{"n":15,"t":"信内写着说：「要派乌利亚前进，到阵势极险之处，你们便退后，使他被杀。」","notes":[]},{"n":16,"t":"约押围城的时候，知道敌人那里有勇士，便将乌利亚派在那里。","notes":[]},{"n":17,"t":"城里的人出来和约押打仗；大卫的仆人中有几个被杀的，赫人乌利亚也死了。","notes":[]},{"n":18,"t":"于是，约押差人去将争战的一切事告诉大卫，","notes":[]},{"n":19,"t":"又嘱咐使者说：「你把争战的一切事对王说完了，","notes":[]},{"n":20,"t":"王若发怒，问你说：『你们打仗为什么挨近城墙呢？岂不知敌人必从城上射箭吗？","notes":[]},{"n":21,"t":"从前打死耶路·比设儿子亚比米勒的是谁呢？岂不是一个妇人从城上抛下一块上磨石来，打在他身上，他就死在提备斯吗？你们为什么挨近城墙呢？』你就说：『王的仆人—赫人乌利亚也死了。』」","notes":["就是耶路·巴力，见士师记九章一节"]},{"n":22,"t":"使者起身，来见大卫，照着约押所吩咐他的话奏告大卫。","notes":[]},{"n":23,"t":"使者对大卫说：「敌人强过我们，出到郊野与我们打仗，我们追杀他们，直到城门口。","notes":[]},{"n":24,"t":"射箭的从城上射王的仆人，射死几个，赫人乌利亚也死了。」","notes":[]},{"n":25,"t":"王向使者说：「你告诉约押说：『不要因这事愁闷，刀剑或吞灭这人或吞灭那人，没有一定的；你只管竭力攻城，将城倾覆。』可以用这话勉励约押。」","notes":[]},{"n":26,"t":"乌利亚的妻听见丈夫乌利亚死了，就为他哀哭。","notes":[]},{"n":27,"t":"哀哭的日子过了，大卫差人将她接到宫里，她就作了大卫的妻，给大卫生了一个儿子。但大卫所行的这事，耶和华甚不喜悦。","notes":[]}]},"12":{"heading":"拿单的信息和大卫的悔改","verses":[{"n":1,"t":"耶和华差遣拿单去见大卫。拿单到了大卫那里，对他说：「在一座城里有两个人：一个是富户，一个是穷人。","notes":[]},{"n":2,"t":"富户有许多牛群羊群；","notes":[]},{"n":3,"t":"穷人除了所买来养活的一只小母羊羔之外，别无所有。羊羔在他家里和他儿女一同长大，吃他所吃的，喝他所喝的，睡在他怀中，在他看来如同女儿一样。","notes":[]},{"n":4,"t":"有一客人来到这富户家里；富户舍不得从自己的牛群羊群中取一只预备给客人吃，却取了那穷人的羊羔，预备给客人吃。」","notes":[]},{"n":5,"t":"大卫就甚恼怒那人，对拿单说：「我指着永生的耶和华起誓，行这事的人该死！","notes":[]},{"n":6,"t":"他必偿还羊羔四倍；因为他行这事，没有怜恤的心。」","notes":[]},{"n":7,"t":"拿单对大卫说：「你就是那人！耶和华—以色列的神如此说：『我膏你作以色列的王，救你脱离扫罗的手。","notes":[]},{"n":8,"t":"我将你主人的家业赐给你，将你主人的妻交在你怀里，又将以色列和犹大家赐给你；你若还以为不足，我早就加倍地赐给你。","notes":[]},{"n":9,"t":"你为什么藐视耶和华的命令，行他眼中看为恶的事呢？你借亚扪人的刀杀害赫人乌利亚，又娶了他的妻为妻。","notes":[]},{"n":10,"t":"你既藐视我，娶了赫人乌利亚的妻为妻，所以刀剑必永不离开你的家。』","notes":[]},{"n":11,"t":"耶和华如此说：『我必从你家中兴起祸患攻击你；我必在你眼前把你的妃嫔赐给别人，他在日光之下就与她们同寝。","notes":[]},{"n":12,"t":"你在暗中行这事，我却要在以色列众人面前，日光之下，报应你。』」","notes":[]},{"n":13,"t":"大卫对拿单说：「我得罪耶和华了！」拿单说：「耶和华已经除掉你的罪，你必不至于死。","notes":[]},{"n":14,"t":"只是你行这事，叫耶和华的仇敌大得亵渎的机会，故此，你所得的孩子必定要死。」","notes":[]},{"n":15,"t":"拿单就回家去了。耶和华击打乌利亚妻给大卫所生的孩子，使他得重病。","notes":[]},{"n":16,"t":"所以大卫为这孩子恳求神，而且禁食，进入内室，终夜躺在地上。","notes":[]},{"n":17,"t":"他家中的老臣来到他旁边，要把他从地上扶起来，他却不肯起来，也不同他们吃饭。","notes":[]},{"n":18,"t":"到第七日，孩子死了。大卫的臣仆不敢告诉他孩子死了，因他们说：「孩子还活着的时候，我们劝他，他尚且不肯听我们的话，若告诉他孩子死了，岂不更加忧伤吗？」","notes":[]},{"n":19,"t":"大卫见臣仆彼此低声说话，就知道孩子死了，问臣仆说：「孩子死了吗？」他们说：「死了。」","notes":[]},{"n":20,"t":"大卫就从地上起来，沐浴，抹膏，换了衣裳，进耶和华的殿敬拜；然后回宫，吩咐人摆饭，他便吃了。","notes":[]},{"n":21,"t":"臣仆问他说：「你所行的是什么意思？孩子活着的时候，你禁食哭泣；孩子死了，你倒起来吃饭。」","notes":[]},{"n":22,"t":"大卫说：「孩子还活着，我禁食哭泣；因为我想，或者耶和华怜恤我，使孩子不死也未可知。","notes":[]},{"n":23,"t":"孩子死了，我何必禁食，我岂能使他返回呢？我必往他那里去，他却不能回我这里来。」","notes":[]},{"n":24,"t":"大卫安慰他的妻拔示巴，与她同寝，她就生了儿子，给他起名叫所罗门。耶和华也喜爱他，","notes":[],"heads":["所罗门出生"]},{"n":25,"t":"就借先知拿单赐他一个名字，叫耶底底亚，因为耶和华爱他。","notes":[]},{"n":26,"t":"约押攻取亚扪人的京城拉巴。","notes":[],"heads":["大卫攻取拉巴"]},{"n":27,"t":"约押打发使者去见大卫，说：「我攻打拉巴，取其水城。","notes":[]},{"n":28,"t":"现在你要聚集其余的军兵来，安营围攻这城，恐怕我取了这城，人就以我的名叫这城。」","notes":[]},{"n":29,"t":"于是大卫聚集众军，往拉巴去攻城，就取了这城，","notes":[]},{"n":30,"t":"夺了亚扪人之王所戴的金冠冕，其上的金子重一他连得，又嵌着宝石。人将这冠冕戴在大卫头上。大卫从城里夺了许多财物，","notes":["王：或译玛勒堪；玛勒堪就是米勒公，又名摩洛，亚扪族之神名"]},{"n":31,"t":"将城里的人拉出来，放在锯下，或铁耙下，或铁斧下，或叫他经过砖窑；大卫待亚扪各城的居民都是如此。其后，大卫和众军都回耶路撒冷去了。","notes":["或译：强他们用锯，或用打粮食的铁器，或用铁斧做工，或使在砖窑里服役"]}]},"13":{"heading":"暗嫩和她玛","verses":[{"n":1,"t":"大卫的儿子押沙龙有一个美貌的妹子，名叫她玛。大卫的儿子暗嫩爱她。","notes":[]},{"n":2,"t":"暗嫩为他妹子她玛忧急成病。她玛还是处女，暗嫩以为难向她行事。","notes":[]},{"n":3,"t":"暗嫩有一个朋友，名叫约拿达，是大卫长兄示米亚的儿子。这约拿达为人极其狡猾；","notes":[]},{"n":4,"t":"他问暗嫩说：「王的儿子啊，为何一天比一天瘦弱呢？请你告诉我。」暗嫩回答说：「我爱我兄弟押沙龙的妹子她玛。」","notes":[]},{"n":5,"t":"约拿达说：「你不如躺在床上装病；你父亲来看你，就对他说：『求父叫我妹子她玛来，在我眼前预备食物，递给我吃，使我看见，好从她手里接过来吃。』」","notes":[]},{"n":6,"t":"于是暗嫩躺卧装病。王来看他，他对王说：「求父叫我妹子她玛来，在我眼前为我做两个饼，我好从她手里接过来吃。」","notes":[]},{"n":7,"t":"大卫就打发人到宫里，对她玛说：「你往你哥哥暗嫩的屋里去，为他预备食物。」","notes":[]},{"n":8,"t":"她玛就到她哥哥暗嫩的屋里；暗嫩正躺卧。她玛抟面，在他眼前做饼，且烤熟了，","notes":[]},{"n":9,"t":"在他面前将饼从锅里倒出来，他却不肯吃，便说：「众人离开我出去吧！」众人就都离开他，出去了。","notes":[]},{"n":10,"t":"暗嫩对她玛说：「你把食物拿进卧房，我好从你手里接过来吃。」她玛就把所做的饼拿进卧房，到她哥哥暗嫩那里，","notes":[]},{"n":11,"t":"拿着饼上前给他吃，他便拉住她玛，说：「我妹妹，你来与我同寝。」","notes":[]},{"n":12,"t":"她玛说：「我哥哥，不要玷辱我。以色列人中不当这样行，你不要做这丑事；","notes":[]},{"n":13,"t":"你玷辱了我，我何以掩盖我的羞耻呢？你在以色列中也成了愚妄人。你可以求王，他必不禁止我归你。」","notes":[]},{"n":14,"t":"但暗嫩不肯听她的话，因比她力大，就玷辱她，与她同寝。","notes":[]},{"n":15,"t":"随后，暗嫩极其恨她，那恨她的心比先前爱她的心更甚，对她说：「你起来，去吧！」","notes":[]},{"n":16,"t":"她玛说：「不要这样！你赶出我去的这罪比你才行的更重！」但暗嫩不肯听她的话，","notes":[]},{"n":17,"t":"就叫伺候自己的仆人来，说：「将这个女子赶出去！她一出去，你就关门，上闩。」","notes":[]},{"n":18,"t":"那时她玛穿着彩衣，因为没有出嫁的公主都是这样穿。暗嫩的仆人就把她赶出去，关门上闩。","notes":[]},{"n":19,"t":"她玛把灰尘撒在头上，撕裂所穿的彩衣，以手抱头，一面行走，一面哭喊。","notes":[]},{"n":20,"t":"她胞兄押沙龙问她说：「莫非你哥哥暗嫩与你亲近了吗？我妹妹，暂且不要作声，他是你的哥哥，不要将这事放在心上。」她玛就孤孤单单地住在她胞兄押沙龙家里。","notes":[]},{"n":21,"t":"大卫王听见这事，就甚发怒。","notes":[]},{"n":22,"t":"押沙龙并不和他哥哥暗嫩说好说歹；因为暗嫩玷辱他妹妹她玛，所以押沙龙恨恶他。","notes":[]},{"n":23,"t":"过了二年，在靠近以法莲的巴力·夏琐有人为押沙龙剪羊毛；押沙龙请王的众子与他同去。","notes":[],"heads":["押沙龙为妹报仇"]},{"n":24,"t":"押沙龙来见王，说：「现在有人为仆人剪羊毛，请王和王的臣仆与仆人同去。」","notes":[]},{"n":25,"t":"王对押沙龙说：「我儿，我们不必都去，恐怕使你耗费太多。」押沙龙再三请王，王仍是不肯去，只为他祝福。","notes":[]},{"n":26,"t":"押沙龙说：「王若不去，求王许我哥哥暗嫩同去。」王说：「何必要他去呢？」","notes":[]},{"n":27,"t":"押沙龙再三求王，王就许暗嫩和王的众子与他同去。","notes":[]},{"n":28,"t":"押沙龙吩咐仆人说：「你们注意，看暗嫩饮酒畅快的时候，我对你们说杀暗嫩，你们便杀他，不要惧怕。这不是我吩咐你们的吗？你们只管壮胆奋勇！」","notes":[]},{"n":29,"t":"押沙龙的仆人就照押沙龙所吩咐的，向暗嫩行了。王的众子都起来，各人骑上骡子，逃跑了。","notes":[]},{"n":30,"t":"他们还在路上，有风声传到大卫那里，说：「押沙龙将王的众子都杀了，没有留下一个。」","notes":[]},{"n":31,"t":"王就起来，撕裂衣服，躺在地上。王的臣仆也都撕裂衣服，站在旁边。","notes":[]},{"n":32,"t":"大卫的长兄，示米亚的儿子约拿达说：「我主，不要以为王的众子—少年人都杀了，只有暗嫩一个人死了。自从暗嫩玷辱押沙龙妹子她玛的那日，押沙龙就定意杀暗嫩了。","notes":[]},{"n":33,"t":"现在，我主我王，不要把这事放在心上，以为王的众子都死了，只有暗嫩一个人死了。」","notes":[]},{"n":34,"t":"押沙龙逃跑了。守望的少年人举目观看，见有许多人从山坡的路上来。","notes":[]},{"n":35,"t":"约拿达对王说：「看哪，王的众子都来了，果然与你仆人所说的相合。」","notes":[]},{"n":36,"t":"话才说完，王的众子都到了，放声大哭；王和臣仆也都哭得甚恸。","notes":[]},{"n":37,"t":"押沙龙逃到基述王亚米忽的儿子达买那里去了。大卫天天为他儿子悲哀。","notes":[]},{"n":38,"t":"押沙龙逃到基述，在那里住了三年。","notes":[]},{"n":39,"t":"暗嫩死了以后，大卫王得了安慰，心里切切想念押沙龙。","notes":[]}]},"14":{"heading":"约押设法让押沙龙回来","verses":[{"n":1,"t":"洗鲁雅的儿子约押，知道王心里想念押沙龙，","notes":[]},{"n":2,"t":"就打发人往提哥亚去，从那里叫了一个聪明的妇人来，对她说：「请你假装居丧的，穿上孝衣，不要用膏抹身，要装作为死者许久悲哀的妇人；","notes":[]},{"n":3,"t":"进去见王，对王如此如此说。」于是约押将当说的话教导了妇人。","notes":[]},{"n":4,"t":"提哥亚妇人到王面前，伏地叩拜，说：「王啊，求你拯救！」","notes":[]},{"n":5,"t":"王问她说：「你有什么事呢？」回答说：「婢女实在是寡妇，我丈夫死了。","notes":[]},{"n":6,"t":"我有两个儿子，一日在田间争斗，没有人解劝，这个就打死那个。","notes":[]},{"n":7,"t":"现在全家的人都起来攻击婢女，说：『你将那打死兄弟的交出来，我们好治死他，偿他打死兄弟的命，灭绝那承受家业的。』这样，他们要将我剩下的炭火灭尽，不与我丈夫留名留后在世上。」","notes":[]},{"n":8,"t":"王对妇人说：「你回家去吧！我必为你下令。」","notes":[]},{"n":9,"t":"提哥亚妇人又对王说：「我主我王，愿这罪归我和我父家，与王和王的位无干。」","notes":[]},{"n":10,"t":"王说：「凡难为你的，你就带他到我这里来，他必不再搅扰你。」","notes":[]},{"n":11,"t":"妇人说：「愿王记念耶和华—你的神，不许报血仇的人施行灭绝，恐怕他们灭绝我的儿子。」王说：「我指着永生的耶和华起誓：你的儿子连一根头发也不致落在地上。」","notes":[]},{"n":12,"t":"妇人说：「求我主我王容婢女再说一句话。」王说：「你说吧！」","notes":[]},{"n":13,"t":"妇人说：「王为何也起意要害神的民呢？王不使那逃亡的人回来，王的这话就是自证己错了！","notes":[]},{"n":14,"t":"我们都是必死的，如同水泼在地上，不能收回。神并不夺取人的性命，乃设法使逃亡的人不致成为赶出、回不来的。","notes":[]},{"n":15,"t":"我来将这话告诉我主我王，是因百姓使我惧怕。婢女想，不如将这话告诉王，或者王成就婢女所求的。","notes":[]},{"n":16,"t":"人要将我和我儿子从神的地业上一同除灭，王必应允救我脱离他的手。","notes":[]},{"n":17,"t":"婢女又想，我主我王的话必安慰我；因为我主我王能辨别是非，如同神的使者一样。惟愿耶和华—你的神与你同在！」","notes":[]},{"n":18,"t":"王对妇人说：「我要问你一句话，你一点不要瞒我。」妇人说：「愿我主我王说。」","notes":[]},{"n":19,"t":"王说：「你这些话莫非是约押的主意吗？」妇人说：「我敢在我主我王面前起誓：王的话正对，不偏左右，是王的仆人约押吩咐我的，这些话是他教导我的。","notes":[]},{"n":20,"t":"王的仆人约押如此行，为要挽回这事。我主的智慧却如神使者的智慧，能知世上一切事。」","notes":[]},{"n":21,"t":"王对约押说：「我应允你这事。你可以去，把那少年人押沙龙带回来。」","notes":[]},{"n":22,"t":"约押就面伏于地叩拜，祝谢于王，又说：「王既应允仆人所求的，仆人今日知道在我主我王眼前蒙恩了。」","notes":[]},{"n":23,"t":"于是约押起身往基述去，将押沙龙带回耶路撒冷。","notes":[]},{"n":24,"t":"王说：「使他回自己家里去，不要见我的面。」押沙龙就回自己家里去，没有见王的面。","notes":[]},{"n":25,"t":"以色列全地之中，无人像押沙龙那样俊美，得人的称赞，从脚底到头顶毫无瑕疵。","notes":[],"heads":["大卫饶恕押沙龙"]},{"n":26,"t":"他的头发甚重，每到年底剪发一次；所剪下来的，按王的平称一称，重二百舍客勒。","notes":[]},{"n":27,"t":"押沙龙生了三个儿子，一个女儿。女儿名叫她玛，是个容貌俊美的女子。","notes":[]},{"n":28,"t":"押沙龙住在耶路撒冷足有二年，没有见王的面。","notes":[]},{"n":29,"t":"押沙龙打发人去叫约押来，要托他去见王，约押却不肯来。第二次打发人去叫他，他仍不肯来。","notes":[]},{"n":30,"t":"所以押沙龙对仆人说：「你们看，约押有一块田，与我的田相近，其中有大麦，你们去放火烧了。」押沙龙的仆人就去放火烧了那田。","notes":[]},{"n":31,"t":"于是约押起来，到了押沙龙家里，问他说：「你的仆人为何放火烧了我的田呢？」","notes":[]},{"n":32,"t":"押沙龙回答约押说：「我打发人去请你来，好托你去见王，替我说：『我为何从基述回来呢？不如仍在那里。』现在要许我见王的面；我若有罪，任凭王杀我就是了。」","notes":[]},{"n":33,"t":"于是约押去见王，将这话奏告王，王便叫押沙龙来。押沙龙来见王，在王面前俯伏于地，王就与押沙龙亲嘴。","notes":[]}]},"15":{"heading":"押沙龙阴谋造反","verses":[{"n":1,"t":"此后，押沙龙为自己预备车马，又派五十人在他前头奔走。","notes":[]},{"n":2,"t":"押沙龙常常早晨起来，站在城门的道旁，凡有争讼要去求王判断的，押沙龙就叫他过来，问他说：「你是哪一城的人？」回答说：「仆人是以色列某支派的人。」","notes":[]},{"n":3,"t":"押沙龙对他说：「你的事有情有理，无奈王没有委人听你伸诉。」","notes":[]},{"n":4,"t":"押沙龙又说：「恨不得我作国中的士师！凡有争讼求审判的到我这里来，我必秉公判断。」","notes":[]},{"n":5,"t":"若有人近前来要拜押沙龙，押沙龙就伸手拉住他，与他亲嘴。","notes":[]},{"n":6,"t":"以色列人中，凡去见王求判断的，押沙龙都是如此待他们。这样，押沙龙暗中得了以色列人的心。","notes":[]},{"n":7,"t":"满了四十年，押沙龙对王说：「求你准我往希伯仑去，还我向耶和华所许的愿。","notes":["有作四年的"]},{"n":8,"t":"因为仆人住在亚兰的基述，曾许愿说：『耶和华若使我再回耶路撒冷，我必事奉他。』」","notes":[]},{"n":9,"t":"王说：「你平平安安地去吧！」押沙龙就起身，往希伯仑去了。","notes":[]},{"n":10,"t":"押沙龙打发探子走遍以色列各支派，说：「你们一听见角声就说：『押沙龙在希伯仑作王了！』」","notes":[]},{"n":11,"t":"押沙龙在耶路撒冷请了二百人与他同去，都是诚诚实实去的，并不知道其中的真情。","notes":[]},{"n":12,"t":"押沙龙献祭的时候，打发人去将大卫的谋士、基罗人亚希多弗从他本城请了来。于是叛逆的势派甚大；因为随从押沙龙的人民，日渐增多。","notes":[]},{"n":13,"t":"有人报告大卫说：「以色列人的心都归向押沙龙了！」","notes":[],"heads":["大卫逃离耶路撒冷"]},{"n":14,"t":"大卫就对耶路撒冷跟随他的臣仆说：「我们要起来逃走，不然都不能躲避押沙龙了；要速速地去，恐怕他忽然来到，加害于我们，用刀杀尽合城的人。」","notes":[]},{"n":15,"t":"王的臣仆对王说：「我主我王所定的，仆人都愿遵行。」","notes":[]},{"n":16,"t":"于是王带着全家的人出去了，但留下十个妃嫔看守宫殿。","notes":[]},{"n":17,"t":"王出去，众民都跟随他，到伯·墨哈，就住下了。","notes":[]},{"n":18,"t":"王的臣仆都在他面前过去。基利提人、比利提人，就是从迦特跟随王来的六百人，也都在他面前过去。","notes":[]},{"n":19,"t":"王对迦特人以太说：「你是外邦逃来的人，为什么与我们同去呢？你可以回去与新王同住，或者回你本地去吧！","notes":[]},{"n":20,"t":"你来的日子不多，我今日怎好叫你与我们一同飘流、没有一定的住处呢？你不如带你的弟兄回去吧！愿耶和华用慈爱诚实待你。」","notes":[]},{"n":21,"t":"以太对王说：「我指着永生的耶和华起誓，又敢在王面前起誓：无论生死，王在哪里，仆人也必在那里。」","notes":[]},{"n":22,"t":"大卫对以太说：「你前去过河吧！」于是迦特人以太带着跟随他的人和所有的妇人孩子，就都过去了。","notes":[]},{"n":23,"t":"本地的人都放声大哭。众民尽都过去，王也过了汲沦溪；众民往旷野去了。","notes":[]},{"n":24,"t":"撒督和抬神约柜的利未人也一同来了，将神的约柜放下。亚比亚他上来，等着众民从城里出来过去。","notes":[]},{"n":25,"t":"王对撒督说：「你将神的约柜抬回城去。我若在耶和华眼前蒙恩，他必使我回来，再见约柜和他的居所。","notes":[]},{"n":26,"t":"倘若他说：『我不喜悦你』，看哪，我在这里，愿他凭自己的意旨待我！」","notes":[]},{"n":27,"t":"王又对祭司撒督说：「你不是先见吗？你可以安然回城；你儿子亚希玛斯和亚比亚他的儿子约拿单都可以与你同去。","notes":[]},{"n":28,"t":"我在旷野的渡口那里等你们报信给我。」","notes":[]},{"n":29,"t":"于是撒督和亚比亚他将神的约柜抬回耶路撒冷，他们就住在那里。","notes":[]},{"n":30,"t":"大卫蒙头赤脚上橄榄山，一面上一面哭。跟随他的人也都蒙头哭着上去；","notes":[]},{"n":31,"t":"有人告诉大卫说：「亚希多弗也在叛党之中，随从押沙龙。」大卫祷告说：「耶和华啊，求你使亚希多弗的计谋变为愚拙！」","notes":[]},{"n":32,"t":"大卫到了山顶、敬拜神的地方，见亚基人户筛，衣服撕裂，头蒙灰尘来迎接他。","notes":[]},{"n":33,"t":"大卫对他说：「你若与我同去，必累赘我；","notes":[]},{"n":34,"t":"你若回城去，对押沙龙说：『王啊，我愿作你的仆人；我向来作你父亲的仆人，现在我也照样作你的仆人。』这样，你就可以为我破坏亚希多弗的计谋。","notes":[]},{"n":35,"t":"祭司撒督和亚比亚他岂不都在那里吗？你在王宫里听见什么，就要告诉祭司撒督和亚比亚他。","notes":[]},{"n":36,"t":"撒督的儿子亚希玛斯，亚比亚他的儿子约拿单，也都在那里。凡你们所听见的可以托这二人来报告我。」","notes":[]},{"n":37,"t":"于是，大卫的朋友户筛进了城；押沙龙也进了耶路撒冷。","notes":[]}]},"16":{"heading":"大卫和洗巴","verses":[{"n":1,"t":"大卫刚过山顶，见米非波设的仆人洗巴拉着备好了的两匹驴，驴上驮着二百面饼，一百葡萄饼，一百个夏天的果饼，一皮袋酒来迎接他。","notes":[]},{"n":2,"t":"王问洗巴说：「你带这些来是什么意思呢？」洗巴说：「驴是给王的家眷骑的；面饼和夏天的果饼是给少年人吃的；酒是给在旷野疲乏人喝的。」","notes":[]},{"n":3,"t":"王问说：「你主人的儿子在哪里呢？」洗巴回答王说：「他仍在耶路撒冷，因他说：『以色列人今日必将我父的国归还我。』」","notes":[]},{"n":4,"t":"王对洗巴说：「凡属米非波设的都归你了。」洗巴说：「我叩拜我主我王，愿我在你眼前蒙恩。」","notes":[]},{"n":5,"t":"大卫王到了巴户琳，见有一个人出来，是扫罗族基拉的儿子，名叫示每。他一面走一面咒骂，","notes":[],"heads":["大卫和示每"]},{"n":6,"t":"又拿石头砍大卫王和王的臣仆；众民和勇士都在王的左右。","notes":[]},{"n":7,"t":"示每咒骂说：「你这流人血的坏人哪，去吧去吧！","notes":[]},{"n":8,"t":"你流扫罗全家的血，接续他作王；耶和华把这罪归在你身上，将这国交给你儿子押沙龙。现在你自取其祸，因为你是流人血的人。」","notes":[]},{"n":9,"t":"洗鲁雅的儿子亚比筛对王说：「这死狗岂可咒骂我主我王呢？求你容我过去，割下他的头来。」","notes":[]},{"n":10,"t":"王说：「洗鲁雅的儿子，我与你们有何关涉呢？他咒骂是因耶和华吩咐他说：『你要咒骂大卫。』如此，谁敢说你为什么这样行呢？」","notes":[]},{"n":11,"t":"大卫又对亚比筛和众臣仆说：「我亲生的儿子尚且寻索我的性命，何况这便雅悯人呢？由他咒骂吧！因为这是耶和华吩咐他的。","notes":[]},{"n":12,"t":"或者耶和华见我遭难，为我今日被这人咒骂，就施恩与我。」","notes":[]},{"n":13,"t":"于是大卫和跟随他的人往前行走。示每在大卫对面山坡，一面行走一面咒骂，又拿石头砍他，拿土扬他。","notes":[]},{"n":14,"t":"王和跟随他的众人疲疲乏乏地到了一个地方，就在那里歇息歇息。","notes":[]},{"n":15,"t":"押沙龙和以色列众人来到耶路撒冷；亚希多弗也与他同来。","notes":[],"heads":["押沙龙在耶路撒冷"]},{"n":16,"t":"大卫的朋友亚基人户筛去见押沙龙，对他说：「愿王万岁！愿王万岁！」","notes":[]},{"n":17,"t":"押沙龙问户筛说：「这是你恩待朋友吗？为什么不与你的朋友同去呢？」","notes":[]},{"n":18,"t":"户筛对押沙龙说：「不然，耶和华和这民，并以色列众人所拣选的，我必归顺他，与他同住。","notes":[]},{"n":19,"t":"再者，我当服事谁呢？岂不是前王的儿子吗？我怎样服事你父亲，也必照样服事你。」","notes":[]},{"n":20,"t":"押沙龙对亚希多弗说：「你们出个主意，我们怎样行才好？」","notes":[]},{"n":21,"t":"亚希多弗对押沙龙说：「你父所留下看守宫殿的妃嫔，你可以与她们亲近。以色列众人听见你父亲憎恶你，凡归顺你人的手就更坚强。」","notes":[]},{"n":22,"t":"于是人为押沙龙在宫殿的平顶上支搭帐棚；押沙龙在以色列众人眼前，与他父的妃嫔亲近。","notes":[]},{"n":23,"t":"那时亚希多弗所出的主意好像人问神的话一样；他昔日给大卫，今日给押沙龙所出的主意，都是这样。","notes":[]}]},"17":{"heading":"户筛破坏亚希多弗的计谋","verses":[{"n":1,"t":"亚希多弗又对押沙龙说：「求你准我挑选一万二千人，今夜我就起身追赶大卫，","notes":[]},{"n":2,"t":"趁他疲乏手软，我忽然追上他，使他惊惶；跟随他的民必都逃跑，我就单杀王一人，","notes":[]},{"n":3,"t":"使众民都归顺你。你所寻找的人既然死了，众民就如已经归顺你；这样，也都平安无事了。」","notes":[]},{"n":4,"t":"押沙龙和以色列的长老都以这话为美。","notes":[]},{"n":5,"t":"押沙龙说：「要召亚基人户筛来，我们也要听他怎样说。」","notes":[]},{"n":6,"t":"户筛到了押沙龙面前，押沙龙向他说：「亚希多弗是如此如此说的，我们照着他的话行可以不可以？若不可，你就说吧！」","notes":[]},{"n":7,"t":"户筛对押沙龙说：「亚希多弗这次所定的谋不善。」","notes":[]},{"n":8,"t":"户筛又说：「你知道，你父亲和跟随他的人都是勇士，现在他们心里恼怒，如同田野丢崽子的母熊一般，而且你父亲是个战士，必不和民一同住宿。","notes":[]},{"n":9,"t":"他现今或藏在坑中或在别处，若有人首先被杀，凡听见的必说：『跟随押沙龙的民被杀了。』","notes":[]},{"n":10,"t":"虽有人胆大如狮子，他的心也必消化；因为以色列人都知道你父亲是英雄，跟随他的人也都是勇士。","notes":[]},{"n":11,"t":"依我之计，不如将以色列众人—从但直到别是巴，如同海边的沙那样多—聚集到你这里来，你也亲自率领他们出战。","notes":[]},{"n":12,"t":"这样，我们在何处遇见他，就下到他那里，如同露水下在地上一般，连他带跟随他的人，一个也不留下。","notes":[]},{"n":13,"t":"他若进了哪一座城，以色列众人必带绳子去，将那城拉到河里，甚至连一块小石头都不剩下。」","notes":[]},{"n":14,"t":"押沙龙和以色列众人说：「亚基人户筛的计谋比亚希多弗的计谋更好！」这是因耶和华定意破坏亚希多弗的良谋，为要降祸与押沙龙。","notes":[]},{"n":15,"t":"户筛对祭司撒督和亚比亚他说： 「亚希多弗为押沙龙和以色列的长老所定的计谋是如此如此，我所定的计谋是如此如此。","notes":[],"heads":["大卫因接获警告而逃脱"]},{"n":16,"t":"现在你们要急速打发人去，告诉大卫说：『今夜不可住在旷野的渡口，务要过河，免得王和跟随他的人都被吞灭。』」","notes":[]},{"n":17,"t":"那时，约拿单和亚希玛斯在隐·罗结那里等候，不敢进城，恐怕被人看见。有一个使女出来，将这话告诉他们，他们就去报信给大卫王。","notes":[]},{"n":18,"t":"然而有一个童子看见他们，就去告诉押沙龙。他们急忙跑到巴户琳某人的家里；那人院中有一口井，他们就下到井里。","notes":[]},{"n":19,"t":"那家的妇人用盖盖上井口，又在上头铺上碎麦，事就没有泄漏。","notes":[]},{"n":20,"t":"押沙龙的仆人来到那家，问妇人说：「亚希玛斯和约拿单在哪里？」妇人说：「他们过了河了。」仆人找他们，找不着，就回耶路撒冷去了。","notes":[]},{"n":21,"t":"他们走后，二人从井里上来，去告诉大卫王说：「亚希多弗如此如此定计害你，你们务要起来，快快过河。」","notes":[]},{"n":22,"t":"于是大卫和跟随他的人都起来，过约旦河。到了天亮，无一人不过约旦河的。","notes":[]},{"n":23,"t":"亚希多弗见不依从他的计谋，就备上驴，归回本城；到了家，留下遗言，便吊死了，葬在他父亲的坟墓里。","notes":[]},{"n":24,"t":"大卫到了玛哈念，押沙龙和跟随他的以色列人也都过了约旦河。","notes":[]},{"n":25,"t":"押沙龙立亚玛撒作元帅，代替约押。亚玛撒是以实玛利人以特拉的儿子。以特拉曾与拿辖的女儿亚比该亲近；这亚比该与约押的母亲洗鲁雅是姊妹。","notes":["又作以色列人"]},{"n":26,"t":"押沙龙和以色列人都安营在基列地。","notes":[]},{"n":27,"t":"大卫到了玛哈念，亚扪族的拉巴人拿辖的儿子朔比，罗·底巴人亚米利的儿子玛吉，基列的罗基琳人巴西莱，","notes":[]},{"n":28,"t":"带着被、褥、盆、碗、瓦器、小麦、大麦、麦面、炒谷、豆子、红豆、炒豆、","notes":[]},{"n":29,"t":"蜂蜜、奶油、绵羊、奶饼，供给大卫和跟随他的人吃；他们说：「民在旷野，必饥渴困乏了。」","notes":[]}]},"18":{"heading":"押沙龙败亡","verses":[{"n":1,"t":"大卫数点跟随他的人，立千夫长、百夫长率领他们。","notes":[]},{"n":2,"t":"大卫打发军兵出战，分为三队：一队在约押手下，一队在洗鲁雅的儿子、约押兄弟亚比筛手下，一队在迦特人以太手下。大卫对军兵说：「我必与你们一同出战。」","notes":[]},{"n":3,"t":"军兵却说：「你不可出战。若是我们逃跑，敌人必不介意；我们阵亡一半，敌人也不介意。因为你一人强似我们万人，你不如在城里预备帮助我们。」","notes":[]},{"n":4,"t":"王向他们说：「你们以为怎样好，我就怎样行。」于是王站在城门旁，军兵或百或千地挨次出去了。","notes":[]},{"n":5,"t":"王嘱咐约押、亚比筛、以太说：「你们要为我的缘故宽待那少年人押沙龙。」王为押沙龙嘱咐众将的话，兵都听见了。","notes":[]},{"n":6,"t":"兵就出到田野迎着以色列人，在以法莲树林里交战。","notes":[]},{"n":7,"t":"以色列人败在大卫的仆人面前；那日阵亡的甚多，共有二万人。","notes":[]},{"n":8,"t":"因为在那里四面打仗，死于树林的比死于刀剑的更多。","notes":[]},{"n":9,"t":"押沙龙偶然遇见大卫的仆人。押沙龙骑着骡子，从大橡树密枝底下经过，他的头发被树枝绕住，就悬挂起来，所骑的骡子便离他去了。","notes":[]},{"n":10,"t":"有个人看见，就告诉约押说：「我看见押沙龙挂在橡树上了。」","notes":[]},{"n":11,"t":"约押对报信的人说：「你既看见他，为什么不将他打死落在地上呢？你若打死他，我就赏你十舍客勒银子，一条带子。」","notes":[]},{"n":12,"t":"那人对约押说：「我就是得你一千舍客勒银子，我也不敢伸手害王的儿子；因为我们听见王嘱咐你和亚比筛并以太说：『你们要谨慎，不可害那少年人押沙龙。』","notes":[]},{"n":13,"t":"我若妄为害了他的性命，就是你自己也必与我为敌（原来，无论何事都瞒不过王。）」","notes":[]},{"n":14,"t":"约押说：「我不能与你留连。」约押手拿三杆短枪，趁押沙龙在橡树上还活着，就刺透他的心。","notes":[]},{"n":15,"t":"给约押拿兵器的十个少年人围绕押沙龙，将他杀死。","notes":[]},{"n":16,"t":"约押吹角，拦阻众人，他们就回来，不再追赶以色列人。","notes":[]},{"n":17,"t":"他们将押沙龙丢在林中一个大坑里，上头堆起一大堆石头。以色列众人都逃跑，各回各家去了。","notes":[]},{"n":18,"t":"押沙龙活着的时候，在王谷立了一根石柱，因他说：「我没有儿子为我留名。」他就以自己的名称那石柱叫押沙龙柱，直到今日。","notes":[]},{"n":19,"t":"撒督的儿子亚希玛斯说：「容我跑去，将耶和华向仇敌给王报仇的信息报与王知。」","notes":[],"heads":["大卫听闻押沙龙死讯"]},{"n":20,"t":"约押对他说：「你今日不可去报信，改日可以报信；因为今日王的儿子死了，所以你不可去报信。」","notes":[]},{"n":21,"t":"约押对古示人说：「你去将你所看见的告诉王。」古示人在约押面前下拜，就跑去了。","notes":[]},{"n":22,"t":"撒督的儿子亚希玛斯又对约押说：「无论怎样，求你容我随着古示人跑去。」约押说：「我儿，你报这信息，既不得赏赐，何必要跑去呢？」","notes":[]},{"n":23,"t":"他又说：「无论怎样，我要跑去。」约押说：「你跑去吧！」亚希玛斯就从平原往前跑，跑过古示人去了。","notes":[]},{"n":24,"t":"大卫正坐在城瓮里。守望的人上城门楼的顶上，举目观看，见有一个人独自跑来。","notes":[]},{"n":25,"t":"守望的人就大声告诉王。王说：「他若独自来，必是报口信的。」那人跑得渐渐近了。","notes":[]},{"n":26,"t":"守望的人又见一人跑来，就对守城门的人说：「又有一人独自跑来。」王说：「这也必是报信的。」","notes":[]},{"n":27,"t":"守望的人说：「我看前头人的跑法，好像撒督的儿子亚希玛斯的跑法一样。」王说：「他是个好人，必是报好信息。」","notes":[]},{"n":28,"t":"亚希玛斯向王呼叫说：「平安了！」就在王面前脸伏于地叩拜，说：「耶和华—你的神是应当称颂的，因他已将那举手攻击我主我王的人交给王了。」","notes":[]},{"n":29,"t":"王问说：「少年人押沙龙平安不平安？」亚希玛斯回答说：「约押打发王的仆人，那时仆人听见众民大声喧哗，却不知道是什么事。」","notes":[]},{"n":30,"t":"王说：「你退去，站在旁边。」他就退去，站在旁边。","notes":[]},{"n":31,"t":"古示人也来到，说：「有信息报给我主我王！耶和华今日向一切兴起攻击你的人给你报仇了。」","notes":[]},{"n":32,"t":"王问古示人说：「少年人押沙龙平安不平安？」古示人回答说：「愿我主我王的仇敌，和一切兴起要杀害你的人，都与那少年人一样。」","notes":[]},{"n":33,"t":"王就心里伤恸，上城门楼去哀哭，一面走一面说：「我儿押沙龙啊！我儿，我儿押沙龙啊！我恨不得替你死，押沙龙啊，我儿！我儿！」","notes":[]}]},"19":{"heading":"约押劝谏王","verses":[{"n":1,"t":"有人告诉约押说：「王为押沙龙哭泣悲哀。」","notes":[]},{"n":2,"t":"众民听说王为他儿子忧愁，他们得胜的欢乐却变成悲哀。","notes":[]},{"n":3,"t":"那日众民暗暗地进城，就如败阵逃跑、惭愧的民一般。","notes":[]},{"n":4,"t":"王蒙着脸，大声哭号说：「我儿押沙龙啊！押沙龙，我儿，我儿啊！」","notes":[]},{"n":5,"t":"约押进去见王，说：「你今日使你一切仆人脸面惭愧了！他们今日救了你的性命和你儿女妻妾的性命，","notes":[]},{"n":6,"t":"你却爱那恨你的人，恨那爱你的人。你今日明明地不以将帅、仆人为念。我今日看明，若押沙龙活着，我们都死亡，你就喜悦了。","notes":[]},{"n":7,"t":"现在你当出去，安慰你仆人的心。我指着耶和华起誓：你若不出去，今夜必无一人与你同在一处；这祸患就比你从幼年到如今所遭的更甚！」","notes":[]},{"n":8,"t":"于是王起来，坐在城门口。众民听说王坐在城门口，就都到王面前。以色列人已经逃跑，各回各家去了。","notes":[]},{"n":9,"t":"以色列众支派的人纷纷议论说：「王曾救我们脱离仇敌的手，又救我们脱离非利士人的手，现在他躲避押沙龙逃走了。","notes":[]},{"n":10,"t":"我们膏押沙龙治理我们，他已经阵亡。现在为什么不出一言请王回来呢？」","notes":[]},{"n":11,"t":"大卫王差人去见祭司撒督和亚比亚他，说：「你们当向犹大长老说：『以色列众人已经有话请王回宫，你们为什么落在他们后头呢？","notes":[]},{"n":12,"t":"你们是我的弟兄，是我的骨肉，为什么在人后头请王回来呢？』","notes":[]},{"n":13,"t":"也要对亚玛撒说：『你不是我的骨肉吗？我若不立你替约押常作元帅，愿神重重地降罚与我！』」","notes":[]},{"n":14,"t":"如此就挽回犹大众人的心，如同一人的心。他们便打发人去见王，说：「请王和王的一切臣仆回来。」","notes":[]},{"n":15,"t":"王就回来，到了约旦河。犹大人来到吉甲，要去迎接王，请他过约旦河。","notes":[]},{"n":16,"t":"巴户琳的便雅悯人、基拉的儿子示每急忙与犹大人一同下去迎接大卫王。","notes":[]},{"n":17,"t":"跟从示每的有一千便雅悯人，还有扫罗家的仆人洗巴和他十五个儿子，二十个仆人；他们都趟过约旦河迎接王。","notes":[]},{"n":18,"t":"有摆渡船过去，渡王的家眷，任王使用。王要过约旦河的时候，基拉的儿子示每就俯伏在王面前，","notes":[]},{"n":19,"t":"对王说：「我主我王出耶路撒冷的时候，仆人行悖逆的事，现在求我主不要因此加罪与仆人，不要记念，也不要放在心上。","notes":[]},{"n":20,"t":"仆人明知自己有罪，所以约瑟全家之中，今日我首先下来迎接我主我王。」","notes":[]},{"n":21,"t":"洗鲁雅的儿子亚比筛说：「示每既咒骂耶和华的受膏者，不应当治死他吗？」","notes":[]},{"n":22,"t":"大卫说：「洗鲁雅的儿子，我与你们有何关涉，使你们今日与我反对呢？今日在以色列中岂可治死人呢？我岂不知今日我作以色列的王吗？」","notes":[]},{"n":23,"t":"于是王对示每说：「你必不死。」王就向他起誓。","notes":[]},{"n":24,"t":"扫罗的孙子米非波设也下去迎接王。他自从王去的日子，直到王平平安安地回来，没有修脚，没有剃胡须，也没有洗衣服。","notes":[],"heads":["大卫善待米非波设"]},{"n":25,"t":"他来到耶路撒冷迎接王的时候，王问他说：「米非波设，你为什么没有与我同去呢？」","notes":[]},{"n":26,"t":"他回答说：「我主我王，仆人是瘸腿的。那日我想要备驴骑上，与王同去，无奈我的仆人欺哄了我，","notes":[]},{"n":27,"t":"又在我主我王面前谗毁我。然而我主我王如同神的使者一般，你看怎样好，就怎样行吧！","notes":[]},{"n":28,"t":"因为我祖全家的人，在我主我王面前都算为死人，王却使仆人在王的席上同人吃饭，我现在向王还能辨理诉冤吗？」","notes":[]},{"n":29,"t":"王对他说：「你何必再提你的事呢？我说，你与洗巴均分地土。」","notes":[]},{"n":30,"t":"米非波设对王说：「我主我王既平平安安地回宫，就任凭洗巴都取了也可以。」","notes":[]},{"n":31,"t":"基列人巴西莱从罗基琳下来，要送王过约旦河，就与王一同过了约旦河。","notes":[],"heads":["大卫善待巴西莱"]},{"n":32,"t":"巴西莱年纪老迈，已经八十岁了。王住在玛哈念的时候，他就拿食物来供给王；他原是大富户。","notes":[]},{"n":33,"t":"王对巴西莱说：「你与我同去，我要在耶路撒冷那里养你的老。」","notes":[]},{"n":34,"t":"巴西莱对王说：「我在世的年日还能有多少，使我与王同上耶路撒冷呢？","notes":[]},{"n":35,"t":"仆人现在八十岁了，还能尝出饮食的滋味、辨别美恶吗？还能听男女歌唱的声音吗？仆人何必累赘我主我王呢？","notes":[]},{"n":36,"t":"仆人只要送王过约旦河，王何必赐我这样的恩典呢？","notes":[]},{"n":37,"t":"求你准我回去，好死在我本城，葬在我父母的墓旁。这里有王的仆人金罕，让他同我主我王过去，可以随意待他。」","notes":[]},{"n":38,"t":"王说：「金罕可以与我同去，我必照你的心愿待他。你向我求什么，我都必为你成就。」","notes":[]},{"n":39,"t":"于是众民过约旦河，王也过去。王与巴西莱亲嘴，为他祝福，巴西莱就回本地去了。","notes":[]},{"n":40,"t":"王过去，到了吉甲，金罕也跟他过去。犹大众民和以色列民的一半也都送王过去。","notes":[],"heads":["以色列人和犹大人为王起争论"]},{"n":41,"t":"以色列众人来见王，对他说：「我们弟兄犹大人为什么暗暗送王和王的家眷，并跟随王的人过约旦河？」","notes":[]},{"n":42,"t":"犹大众人回答以色列人说：「因为王与我们是亲属，你们为何因这事发怒呢？我们吃了王的什么呢？王赏赐了我们什么呢？」","notes":[]},{"n":43,"t":"以色列人回答犹大人说：「按支派，我们与王有十分的情分；在大卫身上，我们也比你们更有情分。你们为何藐视我们，请王回来不先与我们商量呢？」但犹大人的话比以色列人的话更硬。","notes":[]}]},"20":{"heading":"示巴反叛","verses":[{"n":1,"t":"在那里恰巧有一个匪徒，名叫示巴，是便雅悯人比基利的儿子。他吹角，说：「我们与大卫无分，与耶西的儿子无涉。以色列人哪，你们各回各家去吧！」","notes":[]},{"n":2,"t":"于是以色列人都离开大卫，跟随比基利的儿子示巴。但犹大人从约旦河直到耶路撒冷，都紧紧跟随他们的王。","notes":[]},{"n":3,"t":"大卫王来到耶路撒冷，进了宫殿，就把从前留下看守宫殿的十个妃嫔禁闭在冷宫，养活她们，不与她们亲近。她们如同寡妇被禁，直到死的日子。","notes":[]},{"n":4,"t":"王对亚玛撒说：「你要在三日之内将犹大人招聚了来，你也回到这里来。」","notes":[]},{"n":5,"t":"亚玛撒就去招聚犹大人，却耽延过了王所限的日期。","notes":[]},{"n":6,"t":"大卫对亚比筛说：「现在恐怕比基利的儿子示巴加害于我们比押沙龙更甚。你要带领你主的仆人追赶他，免得他得了坚固城，躲避我们。」","notes":[]},{"n":7,"t":"约押的人和基利提人、比利提人，并所有的勇士，都跟着亚比筛，从耶路撒冷出去追赶比基利的儿子示巴。","notes":[]},{"n":8,"t":"他们到了基遍的大磐石那里，亚玛撒来迎接他们。那时约押穿着战衣，腰束佩刀的带子，刀在鞘内；约押前行，刀从鞘内掉出来。","notes":[]},{"n":9,"t":"约押左手拾起刀来，对亚玛撒说：「我兄弟，你好啊！」就用右手抓住亚玛撒的胡子，要与他亲嘴。","notes":[]},{"n":10,"t":"亚玛撒没有防备约押手里所拿的刀；约押用刀刺入他的肚腹，他的肠子流在地上，没有再刺他，就死了。 约押和他兄弟亚比筛往前追赶比基利的儿子示巴。","notes":[]},{"n":11,"t":"有约押的一个少年人站在亚玛撒尸身旁边，对众人说：「谁喜悦约押，谁归顺大卫，就当跟随约押去。」","notes":[]},{"n":12,"t":"亚玛撒在道路上滚在自己的血里。那人见众民经过都站住，就把亚玛撒的尸身从路上挪到田间，用衣服遮盖。","notes":[]},{"n":13,"t":"尸身从路上挪移之后，众民就都跟随约押去追赶比基利的儿子示巴。","notes":[]},{"n":14,"t":"他走遍以色列各支派，直到伯·玛迦的亚比拉，并比利人的全地；那些地方的人也都聚集跟随他。","notes":[]},{"n":15,"t":"约押和跟随的人到了伯·玛迦的亚比拉，围困示巴，就对着城筑垒；跟随约押的众民用锤撞城，要使城塌陷。","notes":[]},{"n":16,"t":"有一个聪明妇人从城上呼叫说：「听啊，听啊，请约押近前来，我好与他说话。」","notes":[]},{"n":17,"t":"约押就近前来，妇人问他说：「你是约押不是？」他说：「我是。」妇人说：「求你听婢女的话。」约押说：「我听。」","notes":[]},{"n":18,"t":"妇人说：「古时有话说，当先在亚比拉求问，然后事就定妥。","notes":[]},{"n":19,"t":"我们这城的人在以色列人中是和平、忠厚的。你为何要毁坏以色列中的大城，吞灭耶和华的产业呢？」","notes":[]},{"n":20,"t":"约押回答说：「我决不吞灭毁坏，","notes":[]},{"n":21,"t":"乃因以法莲山地的一个人—比基利的儿子示巴—举手攻击大卫王，你们若将他一人交出来，我便离城而去。」妇人对约押说：「那人的首级必从城墙上丢给你。」","notes":[]},{"n":22,"t":"妇人就凭她的智慧去劝众人。他们便割下比基利的儿子示巴的首级，丢给约押。约押吹角，众人就离城而散，各归各家去了。约押回耶路撒冷，到王那里。","notes":[]},{"n":23,"t":"约押作以色列全军的元帅；耶何耶大的儿子比拿雅统辖基利提人和比利提人；","notes":[]},{"n":24,"t":"亚多兰掌管服苦的人；亚希律的儿子约沙法作史官；","notes":[]},{"n":25,"t":"示法作书记；撒督和亚比亚他作祭司长；","notes":[]},{"n":26,"t":"睚珥人以拉作大卫的宰相。","notes":[]}]},"21":{"heading":"扫罗的后代被处死","verses":[{"n":1,"t":"大卫年间有饥荒，一连三年，大卫就求问耶和华。耶和华说：「这饥荒是因扫罗和他流人血之家杀死基遍人。」","notes":[]},{"n":2,"t":"原来这基遍人不是以色列人，乃是亚摩利人中所剩的；以色列人曾向他们起誓，不杀灭他们，扫罗却为以色列人和犹大人发热心，想要杀灭他们。大卫王召了他们来，","notes":[]},{"n":3,"t":"问他们说：「我当为你们怎样行呢？可用什么赎这罪，使你们为耶和华的产业祝福呢？」","notes":[]},{"n":4,"t":"基遍人回答说：「我们和扫罗与他家的事并不关乎金银，也不要因我们的缘故杀一个以色列人。」大卫说：「你们怎样说，我就为你们怎样行。」","notes":[]},{"n":5,"t":"他们对王说：「那从前谋害我们、要灭我们、使我们不得再住以色列境内的人，","notes":[]},{"n":6,"t":"现在愿将他的子孙七人交给我们，我们好在耶和华面前，将他们悬挂在耶和华拣选扫罗的基比亚。」王说：「我必交给你们。」","notes":[]},{"n":7,"t":"王因为曾与扫罗的儿子约拿单指着耶和华起誓结盟，就爱惜扫罗的孙子、约拿单的儿子米非波设，不交出来，","notes":[]},{"n":8,"t":"却把爱雅的女儿利斯巴给扫罗所生的两个儿子亚摩尼、米非波设，和扫罗女儿米甲的姊姊给米何拉人巴西莱儿子亚得列所生的五个儿子","notes":[]},{"n":9,"t":"交在基遍人的手里。基遍人就把他们，在耶和华面前，悬挂在山上，这七人就一同死亡。被杀的时候正是收割的日子，就是动手割大麦的时候。","notes":[]},{"n":10,"t":"爱雅的女儿利斯巴用麻布在磐石上搭棚，从动手收割的时候直到天降雨在尸身上的时候，日间不容空中的雀鸟落在尸身上，夜间不让田野的走兽前来糟践。","notes":[]},{"n":11,"t":"有人将扫罗的妃嫔爱雅女儿利斯巴所行的这事告诉大卫。","notes":[]},{"n":12,"t":"大卫就去，从基列·雅比人那里将扫罗和他儿子约拿单的骸骨搬了来（是因非利士人从前在基利波杀扫罗，将尸身悬挂在伯·珊的街市上，基列·雅比人把尸身偷了去。）","notes":[]},{"n":13,"t":"大卫将扫罗和他儿子约拿单的骸骨从那里搬了来，又收殓被悬挂七人的骸骨，","notes":[]},{"n":14,"t":"将扫罗和他儿子约拿单的骸骨葬在便雅悯的洗拉，在扫罗父亲基士的坟墓里；众人行了王所吩咐的。此后神垂听国民所求的。","notes":[]},{"n":15,"t":"非利士人与以色列人打仗；大卫带领仆人下去，与非利士人接战，大卫就疲乏了。","notes":[],"heads":["攻打非利士巨人"]},{"n":16,"t":"伟人的一个儿子以实·比诺要杀大卫；他的铜枪重三百舍客勒，又佩着新刀。","notes":[]},{"n":17,"t":"但洗鲁雅的儿子亚比筛帮助大卫，攻打非利士人，将他杀死。当日，跟随大卫的人向大卫起誓说：「以后你不可再与我们一同出战，恐怕熄灭以色列的灯。」","notes":[]},{"n":18,"t":"后来，以色列人在歌伯与非利士人打仗，户沙人西比该杀了伟人的一个儿子撒弗。","notes":[]},{"n":19,"t":"又在歌伯与非利士人打仗，伯利恒人雅雷俄珥金的儿子伊勒哈难杀了迦特人歌利亚。这人的枪杆粗如织布的机轴。","notes":[]},{"n":20,"t":"又在迦特打仗，那里有一个身量高大的人，手脚都是六指，共有二十四个指头；他也是伟人的儿子。","notes":[]},{"n":21,"t":"这人向以色列人骂阵，大卫的哥哥示米亚的儿子约拿单就杀了他。","notes":[]},{"n":22,"t":"这四个人是迦特伟人的儿子，都死在大卫和他仆人的手下。","notes":[]}]},"22":{"heading":"大卫的凯歌","verses":[{"n":1,"t":"当耶和华救大卫脱离一切仇敌和扫罗之手的日子，他向耶和华念这诗，","notes":[]},{"n":2,"t":"说：耶和华是我的岩石，我的山寨，我的救主，","notes":[]},{"n":3,"t":"我的神，我的磐石，我所投靠的。他是我的盾牌，是拯救我的角，是我的高台，是我的避难所。我的救主啊，你是救我脱离强暴的。","notes":[]},{"n":4,"t":"我要求告当赞美的耶和华，这样，我必从仇敌手中被救出来。","notes":[]},{"n":5,"t":"曾有死亡的波浪环绕我，匪类的急流使我惊惧，","notes":[]},{"n":6,"t":"阴间的绳索缠绕我，死亡的网罗临到我。","notes":[]},{"n":7,"t":"我在急难中求告耶和华，向我的神呼求。他从殿中听了我的声音；我的呼求入了他的耳中。","notes":[]},{"n":8,"t":"那时因他发怒，地就摇撼战抖；天的根基也震动摇撼。","notes":[]},{"n":9,"t":"从他鼻孔冒烟上腾；从他口中发火焚烧，连炭也着了。","notes":[]},{"n":10,"t":"他又使天下垂，亲自降临；有黑云在他脚下。","notes":[]},{"n":11,"t":"他坐着基路伯飞行，在风的翅膀上显现。","notes":[]},{"n":12,"t":"他以黑暗和聚集的水、天空的厚云为他四围的行宫。","notes":[]},{"n":13,"t":"因他面前的光辉炭都着了。","notes":[]},{"n":14,"t":"耶和华从天上打雷；至高者发出声音。","notes":[]},{"n":15,"t":"他射出箭来，使仇敌四散，发出闪电，使他们扰乱。","notes":[]},{"n":16,"t":"耶和华的斥责一发，鼻孔的气一出，海底就出现，大地的根基也显露。","notes":[]},{"n":17,"t":"他从高天伸手抓住我，把我从大水中拉上来。","notes":[]},{"n":18,"t":"他救我脱离我的劲敌和那些恨我的人，因为他们比我强盛。","notes":[]},{"n":19,"t":"我遭遇灾难的日子，他们来攻击我；但耶和华是我的倚靠。","notes":[]},{"n":20,"t":"他又领我到宽阔之处；他救拔我，因他喜悦我。","notes":[]},{"n":21,"t":"耶和华按着我的公义报答我，按着我手中的清洁赏赐我。","notes":[]},{"n":22,"t":"因为我遵守了耶和华的道，未曾作恶离开我的神。","notes":[]},{"n":23,"t":"他的一切典章常在我面前；他的律例，我也未曾离弃。","notes":[]},{"n":24,"t":"我在他面前作了完全人；我也保守自己远离我的罪孽。","notes":[]},{"n":25,"t":"所以耶和华按我的公义，按我在他眼前的清洁赏赐我。","notes":[]},{"n":26,"t":"慈爱的人，你以慈爱待他；完全的人，你以完全待他；","notes":[]},{"n":27,"t":"清洁的人，你以清洁待他；乖僻的人，你以弯曲待他。","notes":[]},{"n":28,"t":"困苦的百姓，你必拯救；但你的眼目察看高傲的人，使他降卑。","notes":[]},{"n":29,"t":"耶和华啊，你是我的灯；耶和华必照明我的黑暗。","notes":[]},{"n":30,"t":"我借着你冲入敌军，借着我的神跳过墙垣。","notes":[]},{"n":31,"t":"至于神，他的道是完全的；耶和华的话是炼净的。凡投靠他的，他便作他们的盾牌。","notes":[]},{"n":32,"t":"除了耶和华，谁是神呢？除了我们的神，谁是磐石呢？","notes":[]},{"n":33,"t":"神是我坚固的保障；他引导完全人行他的路。","notes":[]},{"n":34,"t":"他使我的脚快如母鹿的蹄，又使我在高处安稳。","notes":[]},{"n":35,"t":"他教导我的手能以争战，甚至我的膀臂能开铜弓。","notes":[]},{"n":36,"t":"你把你的救恩给我作盾牌；你的温和使我为大。","notes":[]},{"n":37,"t":"你使我脚下的地步宽阔；我的脚未曾滑跌。","notes":[]},{"n":38,"t":"我追赶我的仇敌，灭绝了他们，未灭以先，我没有归回。","notes":[]},{"n":39,"t":"我灭绝了他们，打伤了他们，使他们不能起来；他们都倒在我的脚下。","notes":[]},{"n":40,"t":"因为你曾以力量束我的腰，使我能争战；你也使那起来攻击我的都服在我以下。","notes":[]},{"n":41,"t":"你又使我的仇敌在我面前转背逃跑，叫我能以剪除那恨我的人。","notes":[]},{"n":42,"t":"他们仰望，却无人拯救；就是呼求耶和华，他也不应允。","notes":[]},{"n":43,"t":"我捣碎他们，如同地上的灰尘，践踏他们，四散在地，如同街上的泥土。","notes":[]},{"n":44,"t":"你救我脱离我百姓的争竞，保护我作列国的元首；我素不认识的民必事奉我。","notes":[]},{"n":45,"t":"外邦人要投降我，一听见我的名声就必顺从我。","notes":[]},{"n":46,"t":"外邦人要衰残，战战兢兢地出他们的营寨。","notes":[]},{"n":47,"t":"耶和华是活神，愿我的磐石被人称颂！愿神—那拯救我的磐石被人尊崇！","notes":[]},{"n":48,"t":"这位神就是那为我伸冤、使众民服在我以下的。","notes":[]},{"n":49,"t":"你救我脱离仇敌，又把我举起，高过那些起来攻击我的；你救我脱离强暴的人。","notes":[]},{"n":50,"t":"耶和华啊，因此我要在外邦中称谢你，歌颂你的名。","notes":[]},{"n":51,"t":"耶和华赐极大的救恩给他所立的王，施慈爱给他的受膏者，就是给大卫和他的后裔，直到永远！","notes":[]}]},"23":{"heading":"大卫的遗言","verses":[{"n":1,"t":"以下是大卫末了的话。耶西的儿子大卫得居高位，是雅各神所膏的，作以色列的美歌者，说：","notes":[]},{"n":2,"t":"耶和华的灵借着我说：他的话在我口中。","notes":[]},{"n":3,"t":"以色列的神、以色列的磐石晓谕我说：那以公义治理人民的，敬畏神执掌权柄，","notes":[]},{"n":4,"t":"他必像日出的晨光，如无云的清晨，雨后的晴光，使地发生嫩草。","notes":[]},{"n":5,"t":"我家在神面前并非如此；神却与我立永远的约。这约凡事坚稳，关乎我的一切救恩和我一切所想望的，他岂不为我成就吗？","notes":[]},{"n":6,"t":"但匪类都必像荆棘被丢弃；人不敢用手拿它；","notes":[]},{"n":7,"t":"拿它的人必带铁器和枪杆，终久它必被火焚烧。","notes":[]},{"n":8,"t":"大卫勇士的名字记在下面：他革扪人约设·巴设，又称伊斯尼人亚底挪，他是军长的统领，一时击杀了八百人。","notes":[],"heads":["大卫的勇士"]},{"n":9,"t":"其次是亚合人朵多的儿子以利亚撒。从前非利士人聚集要打仗，以色列人迎着上去，有跟随大卫的三个勇士向非利士人骂阵，其中有以利亚撒。","notes":[]},{"n":10,"t":"他起来击杀非利士人，直到手臂疲乏，手黏住刀把。那日耶和华使以色列人大获全胜；众民在以利亚撒后头专夺财物。","notes":[]},{"n":11,"t":"其次是哈拉人亚基的儿子沙玛。一日，非利士人聚集成群，在一块长满红豆的田里，众民就在非利士人面前逃跑。","notes":[]},{"n":12,"t":"沙玛却站在那田间击杀非利士人，救护了那田。耶和华使以色列人大获全胜。","notes":[]},{"n":13,"t":"收割的时候，有三十个勇士中的三个人下到亚杜兰洞见大卫。非利士的军兵在利乏音谷安营。","notes":[]},{"n":14,"t":"那时大卫在山寨，非利士人的防营在伯利恒。","notes":[]},{"n":15,"t":"大卫渴想，说：「甚愿有人将伯利恒城门旁、井里的水打来给我喝。」","notes":[]},{"n":16,"t":"这三个勇士就闯过非利士人的营盘，从伯利恒城门旁的井里打水，拿来奉给大卫。他却不肯喝，将水奠在耶和华面前，","notes":[]},{"n":17,"t":"说：「耶和华啊，这三个人冒死去打水；这水好像他们的血一般，我断不敢喝。」如此，大卫不肯喝。这是三个勇士所做的事。","notes":[]},{"n":18,"t":"洗鲁雅的儿子、约押的兄弟亚比筛是这三个勇士的首领；他举枪杀了三百人，就在三个勇士里得了名。","notes":[]},{"n":19,"t":"他在这三个勇士里是最尊贵的，所以作他们的首领，只是不及前三个勇士。","notes":[]},{"n":20,"t":"有甲薛勇士耶何耶大的儿子比拿雅行过大能的事；他杀了摩押人亚利伊勒的两个儿子，又在下雪的时候下坑里去，杀了一个狮子，","notes":[]},{"n":21,"t":"又杀了一个强壮的埃及人；埃及人手里拿着枪，比拿雅只拿着棍子下去，从埃及人手里夺过枪来，用那枪将他杀死。","notes":[]},{"n":22,"t":"这是耶何耶大的儿子比拿雅所行的事，就在三个勇士里得了名。","notes":[]},{"n":23,"t":"他比那三十个勇士都尊贵，只是不及前三个勇士。大卫立他作护卫长。","notes":[]},{"n":24,"t":"三十个勇士里有约押的兄弟亚撒黑，伯利恒人朵多的儿子伊勒哈难，","notes":[]},{"n":25,"t":"哈律人沙玛，哈律人以利加，","notes":[]},{"n":26,"t":"帕勒提人希利斯，提哥亚人益吉的儿子以拉，","notes":[]},{"n":27,"t":"亚拿突人亚比以谢，户沙人米本乃，","notes":[]},{"n":28,"t":"亚合人撒们，尼陀法人玛哈莱，","notes":[]},{"n":29,"t":"尼陀法人巴拿的儿子希立，便雅悯族、基比亚人利拜的儿子以太，","notes":[]},{"n":30,"t":"比拉顿人比拿雅，迦实溪人希太，","notes":[]},{"n":31,"t":"伯·亚拉巴人亚比亚本，巴鲁米人押斯玛弗，","notes":[]},{"n":32,"t":"沙本人以利雅哈巴，雅善儿子中的约拿单，","notes":[]},{"n":33,"t":"哈拉人沙玛，哈拉人沙拉的儿子亚希暗，","notes":[]},{"n":34,"t":"玛迦人亚哈拜的儿子以利法列，基罗人亚希多弗的儿子以连，","notes":[]},{"n":35,"t":"迦密人希斯莱，亚巴人帕莱，","notes":[]},{"n":36,"t":"琐巴人拿单的儿子以甲，迦得人巴尼，","notes":[]},{"n":37,"t":"亚扪人洗勒，比录人拿哈莱（是给洗鲁雅的儿子约押拿兵器的），","notes":[]},{"n":38,"t":"以帖人以拉，以帖人迦立，","notes":[]},{"n":39,"t":"赫人乌利亚，共有三十七人。","notes":[]}]},"24":{"heading":"大卫调查人口","verses":[{"n":1,"t":"耶和华又向以色列人发怒，就激动大卫，使他吩咐人去数点以色列人和犹大人。","notes":[]},{"n":2,"t":"大卫就吩咐跟随他的元帅约押说：「你去走遍以色列众支派，从但直到别是巴，数点百姓，我好知道他们的数目。」","notes":[]},{"n":3,"t":"约押对王说：「无论百姓多少，愿耶和华—你的神再加增百倍，使我主我王亲眼得见。我主我王何必喜悦行这事呢？」","notes":[]},{"n":4,"t":"但王的命令胜过约押和众军长。约押和众军长就从王面前出去，数点以色列的百姓。","notes":[]},{"n":5,"t":"他们过了约旦河，在迦得谷中、城的右边亚罗珥安营，与雅谢相对，","notes":[]},{"n":6,"t":"又到了基列和他停·合示地，又到了但·雅安，绕到西顿，","notes":[]},{"n":7,"t":"来到泰尔的保障，并希未人和迦南人的各城，又到犹大南方的别是巴。","notes":[]},{"n":8,"t":"他们走遍全地，过了九个月零二十天，就回到耶路撒冷。","notes":[]},{"n":9,"t":"约押将百姓的总数奏告于王：以色列拿刀的勇士有八十万；犹大有五十万。","notes":[]},{"n":10,"t":"大卫数点百姓以后，就心中自责，祷告耶和华说：「我行这事大有罪了。耶和华啊，求你除掉仆人的罪孽，因我所行的甚是愚昧。」","notes":[]},{"n":11,"t":"大卫早晨起来，耶和华的话临到先知迦得，就是大卫的先见，说：","notes":[]},{"n":12,"t":"「你去告诉大卫，说耶和华如此说：『我有三样灾，随你选择一样，我好降与你。』」","notes":[]},{"n":13,"t":"于是迦得来见大卫，对他说：「你愿意国中有七年的饥荒呢？是在你敌人面前逃跑，被追赶三个月呢？是在你国中有三日的瘟疫呢？现在你要揣摩思想，我好回复那差我来的。」","notes":[]},{"n":14,"t":"大卫对迦得说：「我甚为难！我愿落在耶和华的手里，因为他有丰盛的怜悯。我不愿落在人的手里。」","notes":[]},{"n":15,"t":"于是，耶和华降瘟疫与以色列人，自早晨到所定的时候；从但直到别是巴，民间死了七万人。","notes":[]},{"n":16,"t":"天使向耶路撒冷伸手要灭城的时候，耶和华后悔，就不降这灾了，吩咐灭民的天使说：「够了！住手吧！」那时耶和华的使者在耶布斯人亚劳拿的禾场那里。","notes":[]},{"n":17,"t":"大卫看见灭民的天使，就祷告耶和华说：「我犯了罪，行了恶；但这群羊做了什么呢？愿你的手攻击我和我的父家。」","notes":[]},{"n":18,"t":"当日，迦得来见大卫，对他说：「你上去，在耶布斯人亚劳拿的禾场上为耶和华筑一座坛。」","notes":[]},{"n":19,"t":"大卫就照着迦得奉耶和华名所说的话上去了。","notes":[]},{"n":20,"t":"亚劳拿观看，见王和他臣仆前来，就迎接出去，脸伏于地，向王下拜，","notes":[]},{"n":21,"t":"说：「我主我王为何来到仆人这里呢？」大卫说：「我要买你这禾场，为耶和华筑一座坛，使民间的瘟疫止住。」","notes":[]},{"n":22,"t":"亚劳拿对大卫说：「我主我王，你喜悦用什么，就拿去献祭。看哪，这里有牛可以作燔祭，有打粮的器具和套牛的轭可以当柴烧。","notes":[]},{"n":23,"t":"王啊，这一切，我亚劳拿都奉给你」；又对王说：「愿耶和华—你的神悦纳你。」","notes":[]},{"n":24,"t":"王对亚劳拿说：「不然。我必要按着价值向你买；我不肯用白得之物作燔祭献给耶和华—我的神。」大卫就用五十舍客勒银子买了那禾场与牛。","notes":[]},{"n":25,"t":"大卫在那里为耶和华筑了一座坛，献燔祭和平安祭。如此，耶和华垂听国民所求的，瘟疫在以色列人中就止住了。","notes":[]}]}},"1KI":{"1":{"heading":"大卫王的晚年","verses":[{"n":1,"t":"大卫王年纪老迈，虽用被遮盖，仍不觉暖。","notes":[]},{"n":2,"t":"所以臣仆对他说：「不如为我主我王寻找一个处女，使她伺候王，奉养王，睡在王的怀中，好叫我主我王得暖。」","notes":[]},{"n":3,"t":"于是在以色列全境寻找美貌的童女，寻得书念的一个童女亚比煞，就带到王那里。","notes":[]},{"n":4,"t":"这童女极其美貌，她奉养王，伺候王，王却没有与她亲近。","notes":[]},{"n":5,"t":"那时，哈及的儿子亚多尼雅自尊，说：「我必作王」，就为自己预备车辆、马兵，又派五十人在他前头奔走。","notes":[],"heads":["亚多尼雅谋篡王位"]},{"n":6,"t":"他父亲素来没有使他忧闷，说：「你是做什么呢？」他甚俊美，生在押沙龙之后。","notes":[]},{"n":7,"t":"亚多尼雅与洗鲁雅的儿子约押，和祭司亚比亚他商议；二人就顺从他，帮助他。","notes":[]},{"n":8,"t":"但祭司撒督、耶何耶大的儿子比拿雅、先知拿单、示每、利以，并大卫的勇士都不顺从亚多尼雅。","notes":[]},{"n":9,"t":"一日，亚多尼雅在隐·罗结旁、琐希列磐石那里宰了牛羊、肥犊，请他的诸弟兄，就是王的众子，并所有作王臣仆的犹大人；","notes":[]},{"n":10,"t":"惟独先知拿单和比拿雅并勇士，与他的兄弟所罗门，他都没有请。","notes":[]},{"n":11,"t":"拿单对所罗门的母亲拔示巴说：「哈及的儿子亚多尼雅作王了，你没有听见吗？我们的主大卫却不知道。","notes":[],"heads":["所罗门被立为王"]},{"n":12,"t":"现在我可以给你出个主意，好保全你和你儿子所罗门的性命。","notes":[]},{"n":13,"t":"你进去见大卫王，对他说：『我主我王啊，你不曾向婢女起誓说：你儿子所罗门必接续我作王，坐在我的位上吗？现在亚多尼雅怎么作了王呢？』","notes":[]},{"n":14,"t":"你还与王说话的时候，我也随后进去，证实你的话。」","notes":[]},{"n":15,"t":"拔示巴进入内室见王，王甚老迈，书念的童女亚比煞正伺候王。","notes":[]},{"n":16,"t":"拔示巴向王屈身下拜；王说：「你要什么？」","notes":[]},{"n":17,"t":"她说：「我主啊，你曾向婢女指着耶和华—你的神起誓说：『你儿子所罗门必接续我作王，坐在我的位上。』","notes":[]},{"n":18,"t":"现在亚多尼雅作王了，我主我王却不知道。","notes":[]},{"n":19,"t":"他宰了许多牛羊、肥犊，请了王的众子和祭司亚比亚他，并元帅约押；惟独王的仆人所罗门，他没有请。","notes":[]},{"n":20,"t":"我主我王啊，以色列众人的眼目都仰望你，等你晓谕他们，在我主我王之后谁坐你的位。","notes":[]},{"n":21,"t":"若不然，到我主我王与列祖同睡以后，我和我儿子所罗门必算为罪人了。」","notes":[]},{"n":22,"t":"拔示巴还与王说话的时候，先知拿单也进来了。","notes":[]},{"n":23,"t":"有人奏告王说：「先知拿单来了。」拿单进到王前，脸伏于地。","notes":[]},{"n":24,"t":"拿单说：「我主我王果然应许亚多尼雅说『你必接续我作王，坐在我的位上』吗？","notes":[]},{"n":25,"t":"他今日下去，宰了许多牛羊、肥犊，请了王的众子和军长，并祭司亚比亚他；他们正在亚多尼雅面前吃喝，说：『愿亚多尼雅王万岁！』","notes":[]},{"n":26,"t":"惟独我，就是你的仆人和祭司撒督，耶何耶大的儿子比拿雅，并王的仆人所罗门，他都没有请。","notes":[]},{"n":27,"t":"这事果然出乎我主我王吗？王却没有告诉仆人们，在我主我王之后谁坐你的位。」","notes":[]},{"n":28,"t":"大卫王吩咐说：「叫拔示巴来。」拔示巴就进来，站在王面前。","notes":[]},{"n":29,"t":"王起誓说：「我指着救我性命脱离一切苦难、永生的耶和华起誓。","notes":[]},{"n":30,"t":"我既然指着耶和华—以色列的神向你起誓说：你儿子所罗门必接续我作王，坐在我的位上。我今日就必照这话而行。」","notes":[]},{"n":31,"t":"于是，拔示巴脸伏于地，向王下拜，说：「愿我主大卫王万岁！」","notes":[]},{"n":32,"t":"大卫王又吩咐说：「将祭司撒督、先知拿单、耶何耶大的儿子比拿雅召来！」他们就都来到王面前。","notes":[]},{"n":33,"t":"王对他们说：「要带领你们主的仆人，使我儿子所罗门骑我的骡子，送他下到基训；","notes":[]},{"n":34,"t":"在那里，祭司撒督和先知拿单要膏他作以色列的王；你们也要吹角，说：『愿所罗门王万岁！』","notes":[]},{"n":35,"t":"然后要跟随他上来，使他坐在我的位上，接续我作王。我已立他作以色列和犹大的君。」","notes":[]},{"n":36,"t":"耶何耶大的儿子比拿雅对王说：「阿们！愿耶和华—我主我王的神也这样命定。","notes":[]},{"n":37,"t":"耶和华怎样与我主我王同在，愿他照样与所罗门同在，使他的国位比我主大卫王的国位更大。」","notes":[]},{"n":38,"t":"于是，祭司撒督、先知拿单、耶何耶大的儿子比拿雅，和基利提人、比利提人都下去使所罗门骑大卫王的骡子，将他送到基训。","notes":[]},{"n":39,"t":"祭司撒督就从帐幕中取了盛膏油的角来，用膏膏所罗门。人就吹角，众民都说：「愿所罗门王万岁！」","notes":[]},{"n":40,"t":"众民跟随他上来，且吹笛，大大欢呼，声音震地。","notes":[]},{"n":41,"t":"亚多尼雅和所请的众客筵宴方毕，听见这声音；约押听见角声就说：「城中为何有这响声呢？」","notes":[]},{"n":42,"t":"他正说话的时候，祭司亚比亚他的儿子约拿单来了。亚多尼雅对他说：「进来吧！你是个忠义的人，必是报好信息。」","notes":[]},{"n":43,"t":"约拿单对亚多尼雅说：「我们的主大卫王诚然立所罗门为王了。","notes":[]},{"n":44,"t":"王差遣祭司撒督、先知拿单、耶何耶大的儿子比拿雅，和基利提人、比利提人都去使所罗门骑王的骡子。","notes":[]},{"n":45,"t":"祭司撒督和先知拿单在基训已经膏他作王。众人都从那里欢呼着上来，声音使城震动，这就是你们所听见的声音；","notes":[]},{"n":46,"t":"并且所罗门登了国位。","notes":[]},{"n":47,"t":"王的臣仆也来为我们的主大卫王祝福，说：『愿王的神使所罗门的名比王的名更尊荣；使他的国位比王的国位更大。』王就在床上屈身下拜。","notes":[]},{"n":48,"t":"王又说：『耶和华—以色列的神是应当称颂的；因他赐我一人今日坐在我的位上，我也亲眼看见了。』」","notes":[]},{"n":49,"t":"亚多尼雅的众客听见这话就都惊惧，起来四散。","notes":[]},{"n":50,"t":"亚多尼雅惧怕所罗门，就起来，去抓住祭坛的角。","notes":[]},{"n":51,"t":"有人告诉所罗门说：「亚多尼雅惧怕所罗门王，现在抓住祭坛的角，说：『愿所罗门王今日向我起誓，必不用刀杀仆人。』」","notes":[]},{"n":52,"t":"所罗门说：「他若作忠义的人，连一根头发也不致落在地上；他若行恶，必要死亡。」","notes":[]},{"n":53,"t":"于是所罗门王差遣人，使亚多尼雅从坛上下来，他就来，向所罗门王下拜；所罗门对他说：「你回家去吧！」","notes":[]}]},"2":{"heading":"大卫给所罗门的遗训","verses":[{"n":1,"t":"大卫的死期临近了，就嘱咐他儿子所罗门说：","notes":[]},{"n":2,"t":"「我现在要走世人必走的路。所以，你当刚强，作大丈夫，","notes":[]},{"n":3,"t":"遵守耶和华—你神所吩咐的，照着摩西律法上所写的行主的道，谨守他的律例、诫命、典章、法度。这样，你无论做什么事，不拘往何处去，尽都亨通。","notes":[]},{"n":4,"t":"耶和华必成就向我所应许的话说：『你的子孙若谨慎自己的行为，尽心尽意诚诚实实地行在我面前，就不断人坐以色列的国位。』","notes":[]},{"n":5,"t":"你知道洗鲁雅的儿子约押向我所行的，就是杀了以色列的两个元帅：尼珥的儿子押尼珥和益帖的儿子亚玛撒。他在太平之时流这二人的血，如在争战之时一样，将这血染了腰间束的带和脚上穿的鞋。","notes":[]},{"n":6,"t":"所以你要照你的智慧行，不容他白头安然下阴间。","notes":[]},{"n":7,"t":"你当恩待基列人巴西莱的众子，使他们常与你同席吃饭；因为我躲避你哥哥押沙龙的时候，他们拿食物来迎接我。","notes":[]},{"n":8,"t":"在你这里有巴户琳的便雅悯人，基拉的儿子示每；我往玛哈念去的那日，他用狠毒的言语咒骂我，后来却下约旦河迎接我，我就指着耶和华向他起誓说：『我必不用刀杀你。』","notes":[]},{"n":9,"t":"现在你不要以他为无罪。你是聪明人，必知道怎样待他，使他白头见杀，流血下到阴间。」","notes":[]},{"n":10,"t":"大卫与他列祖同睡，葬在大卫城。","notes":[],"heads":["大卫寿终"]},{"n":11,"t":"大卫作以色列王四十年：在希伯仑作王七年，在耶路撒冷作王三十三年。","notes":[]},{"n":12,"t":"所罗门坐他父亲大卫的位，他的国甚是坚固。","notes":[]},{"n":13,"t":"哈及的儿子亚多尼雅去见所罗门的母亲拔示巴，拔示巴问他说：「你来是为平安吗？」回答说：「是为平安」；","notes":[],"heads":["亚多尼雅的死"]},{"n":14,"t":"又说：「我有话对你说。」拔示巴说：「你说吧。」","notes":[]},{"n":15,"t":"亚多尼雅说：「你知道国原是归我的，以色列众人也都仰望我作王，不料，国反归了我兄弟，因他得国是出乎耶和华。","notes":[]},{"n":16,"t":"现在我有一件事求你，望你不要推辞。」拔示巴说：「你说吧。」","notes":[]},{"n":17,"t":"他说：「求你请所罗门王将书念的女子亚比煞赐我为妻，因他必不推辞你。」","notes":[]},{"n":18,"t":"拔示巴说：「好，我必为你对王提说。」","notes":[]},{"n":19,"t":"于是，拔示巴去见所罗门王，要为亚多尼雅提说；王起来迎接，向她下拜，就坐在位上，吩咐人为王母设一座位，她便坐在王的右边。","notes":[]},{"n":20,"t":"拔示巴说：「我有一件小事求你，望你不要推辞。」王说：「请母亲说，我必不推辞。」","notes":[]},{"n":21,"t":"拔示巴说：「求你将书念的女子亚比煞赐给你哥哥亚多尼雅为妻。」","notes":[]},{"n":22,"t":"所罗门王对他母亲说：「为何单替他求书念的女子亚比煞呢？也可以为他求国吧！他是我的哥哥，他有祭司亚比亚他和洗鲁雅的儿子约押为辅佐。」","notes":[]},{"n":23,"t":"所罗门王就指着耶和华起誓说：「亚多尼雅这话是自己送命，不然，愿神重重地降罚与我。","notes":[]},{"n":24,"t":"耶和华坚立我，使我坐在父亲大卫的位上，照着所应许的话为我建立家室；现在我指着永生的耶和华起誓，亚多尼雅今日必被治死。」","notes":[]},{"n":25,"t":"于是所罗门王差遣耶何耶大的儿子比拿雅，将亚多尼雅杀死。","notes":[]},{"n":26,"t":"王对祭司亚比亚他说：「你回亚拿突归自己的田地去吧！你本是该死的，但因你在我父亲大卫面前抬过主耶和华的约柜，又与我父亲同受一切苦难，所以我今日不将你杀死。」","notes":[],"heads":["亚比亚他被废和约押的死"]},{"n":27,"t":"所罗门就革除亚比亚他，不许他作耶和华的祭司。这样，便应验耶和华在示罗论以利家所说的话。","notes":[]},{"n":28,"t":"约押虽然没有归从押沙龙，却归从了亚多尼雅。他听见这风声，就逃到耶和华的帐幕，抓住祭坛的角。","notes":[]},{"n":29,"t":"有人告诉所罗门王说：「约押逃到耶和华的帐幕，现今在祭坛的旁边。」所罗门就差遣耶何耶大的儿子比拿雅，说：「你去将他杀死。」","notes":[]},{"n":30,"t":"比拿雅来到耶和华的帐幕，对约押说：「王吩咐说，你出来吧！」他说：「我不出去，我要死在这里。」比拿雅就去回复王，说约押如此如此回答我。","notes":[]},{"n":31,"t":"王说：「你可以照着他的话行，杀死他，将他葬埋，好叫约押流无辜人血的罪不归我和我的父家了。","notes":[]},{"n":32,"t":"耶和华必使约押流人血的罪归到他自己的头上；因为他用刀杀了两个比他又义又好的人，就是以色列元帅尼珥的儿子押尼珥和犹大元帅益帖的儿子亚玛撒，我父亲大卫却不知道。","notes":[]},{"n":33,"t":"故此，流这二人血的罪必归到约押和他后裔的头上，直到永远；惟有大卫和他的后裔，并他的家与国，必从耶和华那里得平安，直到永远。」","notes":[]},{"n":34,"t":"于是耶何耶大的儿子比拿雅上去，将约押杀死，葬在旷野约押自己的坟墓里。","notes":["原文是房屋"]},{"n":35,"t":"王就立耶何耶大的儿子比拿雅作元帅，代替约押，又使祭司撒督代替亚比亚他。","notes":[]},{"n":36,"t":"王差遣人将示每召来，对他说：「你要在耶路撒冷建造房屋居住，不可出来往别处去。","notes":[],"heads":["示每的死"]},{"n":37,"t":"你当确实地知道，你何日出来过汲沦溪，何日必死！你的罪必归到自己的头上。」","notes":["原文是血"]},{"n":38,"t":"示每对王说：「这话甚好！我主我王怎样说，仆人必怎样行。」于是示每多日住在耶路撒冷。","notes":[]},{"n":39,"t":"过了三年，示每的两个仆人逃到迦特王玛迦的儿子亚吉那里去。有人告诉示每说：「你的仆人在迦特。」","notes":[]},{"n":40,"t":"示每起来，备上驴，往迦特到亚吉那里去找他的仆人，就从迦特带他仆人回来。","notes":[]},{"n":41,"t":"有人告诉所罗门说：「示每出耶路撒冷往迦特去，回来了。」","notes":[]},{"n":42,"t":"王就差遣人将示每召了来，对他说：「我岂不是叫你指着耶和华起誓，并且警戒你说『你当确实地知道，你哪日出来往别处去，那日必死』吗？你也对我说：『这话甚好，我必听从。』","notes":[]},{"n":43,"t":"现在你为何不遵守你指着耶和华起的誓和我所吩咐你的命令呢？」","notes":[]},{"n":44,"t":"王又对示每说：「你向我父亲大卫所行的一切恶事，你自己心里也知道，所以耶和华必使你的罪恶归到自己的头上；","notes":[]},{"n":45,"t":"惟有所罗门王必得福，并且大卫的国位必在耶和华面前坚定，直到永远。」","notes":[]},{"n":46,"t":"于是王吩咐耶何耶大的儿子比拿雅，他就去杀死示每。这样，便坚定了所罗门的国位。","notes":[]}]},"3":{"heading":"所罗门祈祷求智慧","verses":[{"n":1,"t":"所罗门与埃及王法老结亲，娶了法老的女儿为妻，接她进入大卫城，直等到造完了自己的宫和耶和华的殿，并耶路撒冷周围的城墙。","notes":[]},{"n":2,"t":"当那些日子，百姓仍在邱坛献祭，因为还没有为耶和华的名建殿。","notes":[]},{"n":3,"t":"所罗门爱耶和华，遵行他父亲大卫的律例，只是还在邱坛献祭烧香。","notes":[]},{"n":4,"t":"所罗门王上基遍去献祭；因为在那里有极大的邱坛，他在那坛上献一千牺牲作燔祭。","notes":["或译：出名"]},{"n":5,"t":"在基遍，夜间梦中，耶和华向所罗门显现，对他说：「你愿我赐你什么？你可以求。」","notes":[]},{"n":6,"t":"所罗门说：「你仆人—我父亲大卫用诚实、公义、正直的心行在你面前，你就向他大施恩典，又为他存留大恩，赐他一个儿子坐在他的位上，正如今日一样。","notes":[]},{"n":7,"t":"耶和华—我的神啊，如今你使仆人接续我父亲大卫作王；但我是幼童，不知道应当怎样出入。","notes":[]},{"n":8,"t":"仆人住在你所拣选的民中，这民多得不可胜数。","notes":[]},{"n":9,"t":"所以求你赐我智慧，可以判断你的民，能辨别是非。不然，谁能判断这众多的民呢？」","notes":[]},{"n":10,"t":"所罗门因为求这事，就蒙主喜悦。","notes":[]},{"n":11,"t":"神对他说：「你既然求这事，不为自己求寿、求富，也不求灭绝你仇敌的性命，单求智慧可以听讼，","notes":[]},{"n":12,"t":"我就应允你所求的，赐你聪明智慧，甚至在你以前没有像你的，在你以后也没有像你的。","notes":[]},{"n":13,"t":"你所没有求的，我也赐给你，就是富足、尊荣，使你在世的日子，列王中没有一个能比你的。","notes":[]},{"n":14,"t":"你若效法你父亲大卫，遵行我的道，谨守我的律例、诫命，我必使你长寿。」","notes":[]},{"n":15,"t":"所罗门醒了，不料是个梦。他就回到耶路撒冷，站在耶和华的约柜前，献燔祭和平安祭，又为他众臣仆设摆筵席。","notes":[]},{"n":16,"t":"一日，有两个妓女来，站在王面前。","notes":[],"heads":["所罗门审断一件疑难的案件"]},{"n":17,"t":"一个说：「我主啊，我和这妇人同住一房；她在房中的时候，我生了一个男孩。","notes":[]},{"n":18,"t":"我生孩子后第三日，这妇人也生了孩子。我们是同住的，除了我们二人之外，房中再没有别人。","notes":[]},{"n":19,"t":"夜间，这妇人睡着的时候，压死了她的孩子。","notes":[]},{"n":20,"t":"她半夜起来，趁我睡着，从我旁边把我的孩子抱去，放在她怀里，将她的死孩子放在我怀里。","notes":[]},{"n":21,"t":"天要亮的时候，我起来要给我的孩子吃奶，不料，孩子死了；及至天亮，我细细地察看，不是我所生的孩子。」","notes":[]},{"n":22,"t":"那妇人说：「不然，活孩子是我的，死孩子是你的。」这妇人说：「不然，死孩子是你的，活孩子是我的。」她们在王面前如此争论。","notes":[]},{"n":23,"t":"王说：「这妇人说『活孩子是我的，死孩子是你的』，那妇人说『不然，死孩子是你的，活孩子是我的』」，","notes":[]},{"n":24,"t":"就吩咐说：「拿刀来！」人就拿刀来。","notes":[]},{"n":25,"t":"王说：「将活孩子劈成两半，一半给那妇人，一半给这妇人。」","notes":[]},{"n":26,"t":"活孩子的母亲为自己的孩子心里急痛，就说：「求我主将活孩子给那妇人吧，万不可杀他！」那妇人说：「这孩子也不归我，也不归你，把他劈了吧！」","notes":[]},{"n":27,"t":"王说：「将活孩子给这妇人，万不可杀他；这妇人实在是他的母亲。」","notes":[]},{"n":28,"t":"以色列众人听见王这样判断，就都敬畏他；因为见他心里有神的智慧，能以断案。","notes":[]}]},"4":{"heading":"所罗门的臣仆","verses":[{"n":1,"t":"所罗门作以色列众人的王。","notes":[]},{"n":2,"t":"他的臣子记在下面：撒督的儿子亚撒利雅作祭司，","notes":[]},{"n":3,"t":"示沙的两个儿子以利何烈、亚希亚作书记，亚希律的儿子约沙法作史官，","notes":[]},{"n":4,"t":"耶何耶大的儿子比拿雅作元帅，撒督和亚比亚他作祭司长，","notes":[]},{"n":5,"t":"拿单的儿子亚撒利雅作众吏长，王的朋友拿单的儿子撒布得作领袖，","notes":[]},{"n":6,"t":"亚希煞作家宰，亚比大的儿子亚多尼兰掌管服苦的人。","notes":[]},{"n":7,"t":"所罗门在以色列全地立了十二个官吏，使他们供给王和王家的食物，每年各人供给一月。","notes":[]},{"n":8,"t":"他们的名字记在下面：在以法莲山地有便·户珥；","notes":[]},{"n":9,"t":"在玛迦斯、沙宾、伯·示麦、以伦·伯·哈南有便·底甲；","notes":[]},{"n":10,"t":"在亚鲁泊有便·希悉，他管理梭哥和希弗全地；","notes":[]},{"n":11,"t":"在多珥山冈有便·亚比拿达，他娶了所罗门的女儿她法为妻；","notes":["或译：全境"]},{"n":12,"t":"在他纳和米吉多，并靠近撒拉他拿、耶斯列下边的伯·善全地，从伯·善到亚伯·米何拉直到约念之外，有亚希律的儿子巴拿；","notes":[]},{"n":13,"t":"在基列的拉末有便·基别，他管理在基列的玛拿西子孙睚珥的城邑，巴珊的亚珥歌伯地的大城六十座，都有城墙和铜闩；","notes":[]},{"n":14,"t":"在玛哈念有易多的儿子亚希拿达；","notes":[]},{"n":15,"t":"在拿弗他利有亚希玛斯，他也娶了所罗门的一个女儿巴实抹为妻；","notes":[]},{"n":16,"t":"在亚设和亚禄有户筛的儿子巴拿；","notes":[]},{"n":17,"t":"在以萨迦有帕路亚的儿子约沙法；","notes":[]},{"n":18,"t":"在便雅悯有以拉的儿子示每；","notes":[]},{"n":19,"t":"在基列地，就是从前属亚摩利王西宏和巴珊王噩之地，有乌利的儿子基别一人管理。","notes":[]},{"n":20,"t":"犹大人和以色列人如同海边的沙那样多，都吃喝快乐。","notes":[],"heads":["所罗门的富强"]},{"n":21,"t":"所罗门统管诸国，从大河到非利士地，直到埃及的边界。所罗门在世的日子，这些国都进贡服事他。","notes":[]},{"n":22,"t":"所罗门每日所用的食物：细面三十歌珥，粗面六十歌珥，","notes":[]},{"n":23,"t":"肥牛十只，草场的牛二十只，羊一百只，还有鹿、羚羊、狍子，并肥禽。","notes":[]},{"n":24,"t":"所罗门管理大河西边的诸王，以及从提弗萨直到迦萨的全地，四境尽都平安。","notes":[]},{"n":25,"t":"所罗门在世的日子，从但到别是巴的犹大人和以色列人都在自己的葡萄树下和无花果树下安然居住。","notes":[]},{"n":26,"t":"所罗门有套车的马四万，还有马兵一万二千。","notes":[]},{"n":27,"t":"那十二个官吏各按各月供给所罗门王，并一切与他同席之人的食物，一无所缺。","notes":[]},{"n":28,"t":"众人各按各分，将养马与快马的大麦和干草送到官吏那里。","notes":[]},{"n":29,"t":"神赐给所罗门极大的智慧聪明和广大的心，如同海沙不可测量。","notes":[],"heads":["所罗门的智慧"]},{"n":30,"t":"所罗门的智慧超过东方人和埃及人的一切智慧。","notes":[]},{"n":31,"t":"他的智慧胜过万人，胜过以斯拉人以探，并玛曷的儿子希幔、甲各、达大的智慧。他的名声传扬在四围的列国。","notes":[]},{"n":32,"t":"他作箴言三千句，诗歌一千零五首。","notes":[]},{"n":33,"t":"他讲论草木，自黎巴嫩的香柏树直到墙上长的牛膝草，又讲论飞禽走兽、昆虫水族。","notes":[]},{"n":34,"t":"天下列王听见所罗门的智慧，就都差人来听他的智慧话。","notes":[]}]},"5":{"heading":"所罗门准备建殿","verses":[{"n":1,"t":"泰尔王希兰，平素爱大卫；他听见以色列人膏所罗门，接续他父亲作王，就差遣臣仆来见他。","notes":[]},{"n":2,"t":"所罗门也差遣人去见希兰，说：","notes":[]},{"n":3,"t":"「你知道我父亲大卫因四围的争战，不能为耶和华—他神的名建殿，直等到耶和华使仇敌都服在他脚下。","notes":[]},{"n":4,"t":"现在耶和华—我的神使我四围平安，没有仇敌，没有灾祸。","notes":[]},{"n":5,"t":"我定意要为耶和华—我神的名建殿，是照耶和华应许我父亲大卫的话说：『我必使你儿子接续你坐你的位，他必为我的名建殿。』","notes":[]},{"n":6,"t":"所以求你吩咐你的仆人在黎巴嫩为我砍伐香柏木，我的仆人也必帮助他们，我必照你所定的，给你仆人的工价；因为你知道，在我们中间没有人像西顿人善于砍伐树木。」","notes":[]},{"n":7,"t":"希兰听见所罗门的话，就甚喜悦，说：「今日应当称颂耶和华；因他赐给大卫一个有智慧的儿子，治理这众多的民。」","notes":[]},{"n":8,"t":"希兰打发人去见所罗门，说：「你差遣人向我所提的那事，我都听见了；论到香柏木和松木，我必照你的心愿而行。","notes":[]},{"n":9,"t":"我的仆人必将这木料从黎巴嫩运到海里，扎成筏子，浮海运到你所指定我的地方，在那里拆开，你就可以收取；你也要成全我的心愿，将食物给我的家。」","notes":[]},{"n":10,"t":"于是希兰照着所罗门所要的，给他香柏木和松木；","notes":[]},{"n":11,"t":"所罗门给希兰麦子二万歌珥，清油二十歌珥，作他家的食物。所罗门每年都是这样给希兰。","notes":[]},{"n":12,"t":"耶和华照着所应许的赐智慧给所罗门。希兰与所罗门和好，彼此立约。","notes":[]},{"n":13,"t":"所罗门王从以色列人中挑取服苦的人共有三万，","notes":[]},{"n":14,"t":"派他们轮流每月一万人上黎巴嫩去；一个月在黎巴嫩，两个月在家里。亚多尼兰掌管他们。","notes":[]},{"n":15,"t":"所罗门用七万扛抬的，八万在山上凿石头的。","notes":[]},{"n":16,"t":"此外，所罗门用三千三百督工的，监管工人。","notes":[]},{"n":17,"t":"王下令，人就凿出又大又宝贵的石头来，用以立殿的根基。","notes":[]},{"n":18,"t":"所罗门的匠人和希兰的匠人，并迦巴勒人，都将石头凿好，预备木料和石头建殿。","notes":[]}]},"6":{"heading":"所罗门建造圣殿","verses":[{"n":1,"t":"以色列人出埃及地后四百八十年，所罗门作以色列王第四年西弗月，就是二月，开工建造耶和华的殿。","notes":[]},{"n":2,"t":"所罗门王为耶和华所建的殿，长六十肘，宽二十肘，高三十肘。","notes":[]},{"n":3,"t":"殿前的廊子长二十肘，与殿的宽窄一样，阔十肘；","notes":[]},{"n":4,"t":"又为殿做了严紧的窗棂。","notes":[]},{"n":5,"t":"靠着殿墙，围着外殿内殿，造了三层旁屋；","notes":[]},{"n":6,"t":"下层宽五肘，中层宽六肘，上层宽七肘。殿外旁屋的梁木搁在殿墙坎上，免得插入殿墙。","notes":[]},{"n":7,"t":"建殿是用山中凿成的石头。建殿的时候，锤子、斧子，和别样铁器的响声都没有听见。","notes":[]},{"n":8,"t":"在殿右边当中的旁屋有门，门内有旋螺的楼梯，可以上到第二层，从第二层可以上到第三层。","notes":[]},{"n":9,"t":"所罗门建殿，安置香柏木的栋梁，又用香柏木板遮盖。","notes":[]},{"n":10,"t":"靠着殿所造的旁屋，每层高五肘，香柏木的栋梁搁在殿墙坎上。","notes":[]},{"n":11,"t":"耶和华的话临到所罗门说：","notes":[],"heads":["耶和华的约"]},{"n":12,"t":"「论到你所建的这殿，你若遵行我的律例，谨守我的典章，遵从我的一切诫命，我必向你应验我所应许你父亲大卫的话。","notes":[]},{"n":13,"t":"我必住在以色列人中间，并不丢弃我民以色列。」","notes":[]},{"n":14,"t":"所罗门建造殿宇。","notes":[],"heads":["殿内的设备"]},{"n":15,"t":"殿里面用香柏木板贴墙，从地到棚顶都用木板遮蔽，又用松木板铺地。","notes":[]},{"n":16,"t":"内殿，就是至圣所，长二十肘，从地到棚顶用香柏木板遮蔽。","notes":["或译：隔断"]},{"n":17,"t":"内殿前的外殿，长四十肘。","notes":[]},{"n":18,"t":"殿里一点石头都不显露，一概用香柏木遮蔽；上面刻着野瓜和初开的花。","notes":[]},{"n":19,"t":"殿里预备了内殿，好安放耶和华的约柜。","notes":[]},{"n":20,"t":"内殿长二十肘，宽二十肘，高二十肘，墙面都贴上精金；又用香柏木做坛，包上精金。","notes":[]},{"n":21,"t":"所罗门用精金贴了殿内的墙，又用金链子挂在内殿前门扇，用金包裹。","notes":[]},{"n":22,"t":"全殿都贴上金子，直到贴完；内殿前的坛，也都用金包裹。","notes":[]},{"n":23,"t":"他用橄榄木做两个基路伯，各高十肘，安在内殿。","notes":[],"heads":["造二基路伯"]},{"n":24,"t":"这一个基路伯有两个翅膀，各长五肘，从这翅膀尖到那翅膀尖共有十肘；","notes":[]},{"n":25,"t":"那一个基路伯的两个翅膀也是十肘，两个基路伯的尺寸、形象都是一样。","notes":[]},{"n":26,"t":"这基路伯高十肘，那基路伯也是如此。","notes":[]},{"n":27,"t":"他将两个基路伯安在内殿里；基路伯的翅膀是张开的，这基路伯的一个翅膀挨着这边的墙，那基路伯的一个翅膀挨着那边的墙，里边的两个翅膀在殿中间彼此相接；","notes":[]},{"n":28,"t":"又用金子包裹二基路伯。","notes":[]},{"n":29,"t":"内殿、外殿周围的墙上都刻着基路伯、棕树，和初开的花。","notes":[],"heads":["殿的装饰"]},{"n":30,"t":"内殿、外殿的地板都贴上金子。","notes":[]},{"n":31,"t":"又用橄榄木制造内殿的门扇、门楣、门框；门口有墙的五分之一。","notes":[]},{"n":32,"t":"在橄榄木做的两门扇上刻着基路伯、棕树，和初开的花，都贴上金子。","notes":[]},{"n":33,"t":"又用橄榄木制造外殿的门框，门口有墙的四分之一。","notes":[]},{"n":34,"t":"用松木做门两扇。这扇分两扇，是折叠的；那扇分两扇，也是折叠的。","notes":[]},{"n":35,"t":"上面刻着基路伯、棕树，和初开的花，都用金子贴了。","notes":[]},{"n":36,"t":"他又用凿成的石头三层、香柏木一层建筑内院。","notes":[]},{"n":37,"t":"所罗门在位第四年西弗月，立了耶和华殿的根基。","notes":[]},{"n":38,"t":"到十一年布勒月，就是八月，殿和一切属殿的都按着样式造成。他建殿的工夫共有七年。","notes":[]}]},"7":{"heading":"所罗门的王宫","verses":[{"n":1,"t":"所罗门为自己建造宫室，十三年方才造成；","notes":[]},{"n":2,"t":"又建造黎巴嫩林宫，长一百肘，宽五十肘，高三十肘，有香柏木柱三行，柱上有香柏木柁梁。","notes":["原文是四"]},{"n":3,"t":"其上以香柏木为盖，每行柱子十五根，共有四十五根。","notes":[]},{"n":4,"t":"有窗户三层，窗与窗相对。","notes":[]},{"n":5,"t":"所有的门框都是厚木见方的，有窗户三层，窗与窗相对。","notes":[]},{"n":6,"t":"并建造有柱子的廊子，长五十肘，宽三十肘；在这廊前又有廊子，廊外有柱子和台阶。","notes":[]},{"n":7,"t":"又建造一廊，其中设立审判的座位，这廊从地到顶都用香柏木遮蔽。","notes":[]},{"n":8,"t":"廊后院内有所罗门住的宫室；工作与这工作相同。所罗门又为所娶法老的女儿建造一宫，做法与这廊子一样。","notes":[]},{"n":9,"t":"建造这一切所用的石头都是宝贵的，是按着尺寸凿成的，是用锯里外锯齐的；从根基直到檐石，从外头直到大院，都是如此。","notes":[]},{"n":10,"t":"根基是宝贵的大石头，有长十肘的，有长八肘的；","notes":[]},{"n":11,"t":"上面有香柏木和按着尺寸凿成宝贵的石头。","notes":[]},{"n":12,"t":"大院周围有凿成的石头三层、香柏木一层，都照耶和华殿的内院和殿廊的样式。","notes":[]},{"n":13,"t":"所罗门王差遣人往泰尔去，将户兰召了来。","notes":[],"heads":["户兰的工作"]},{"n":14,"t":"他是拿弗他利支派中一个寡妇的儿子，他父亲是泰尔人，作铜匠的。户兰满有智慧、聪明、技能，善于各样铜作。他来到所罗门王那里，做王一切所要做的。","notes":[]},{"n":15,"t":"他制造两根铜柱，每根高十八肘，围十二肘；","notes":[],"heads":["两支铜柱"]},{"n":16,"t":"又用铜铸了两个柱顶安在柱上，各高五肘。","notes":[]},{"n":17,"t":"柱顶上有装修的网子和拧成的链索，每顶七个。","notes":[]},{"n":18,"t":"网子周围有两行石榴遮盖柱顶，两个柱顶都是如此。","notes":[]},{"n":19,"t":"廊子的柱顶径四肘，刻着百合花。","notes":[]},{"n":20,"t":"两柱顶的鼓肚上挨着网子，各有两行石榴环绕，两行共有二百。","notes":[]},{"n":21,"t":"他将两根柱子立在殿廊前头：右边立一根，起名叫雅斤；左边立一根，起名叫波阿斯。","notes":[]},{"n":22,"t":"在柱顶上刻着百合花。这样，造柱子的工就完毕了。","notes":[]},{"n":23,"t":"他又铸一个铜海，样式是圆的，高五肘，径十肘，围三十肘。","notes":[],"heads":["铜海"]},{"n":24,"t":"在海边之下，周围有野瓜的样式；每肘十瓜，共有两行，是铸海的时候铸上的。","notes":[]},{"n":25,"t":"有十二只铜牛驮海：三只向北，三只向西，三只向南，三只向东；海在牛上，牛尾都向内。","notes":[]},{"n":26,"t":"海厚一掌，边如杯边，又如百合花，可容二千罢特。","notes":[]},{"n":27,"t":"他用铜制造十个盆座，每座长四肘，宽四肘，高三肘。","notes":[],"heads":["铜座"]},{"n":28,"t":"座的造法是这样：四面都有心子，心子在边子当中，","notes":[]},{"n":29,"t":"心子上有狮子和牛，并基路伯；边上有小座，狮子和牛以下有垂下的璎珞。","notes":[]},{"n":30,"t":"每盆座有四个铜轮和铜轴。小座的四角上在盆以下，有铸成的盆架，其旁都有璎珞。","notes":[]},{"n":31,"t":"小座高一肘，口是圆的，仿佛座的样式，径一肘半，在口上有雕工，心子是方的，不是圆的。","notes":[]},{"n":32,"t":"四个轮子在心子以下，轮轴与座相连，每轮高一肘半。","notes":[]},{"n":33,"t":"轮的样式如同车轮；轴、辋、辐、毂都是铸的。","notes":[]},{"n":34,"t":"每座四角上都有盆架，是与座一同铸成的。","notes":[]},{"n":35,"t":"座上有圆架，高半肘；座上有撑子和心子，是与座一同铸的。","notes":[]},{"n":36,"t":"在撑子和心子上刻着基路伯、狮子，和棕树，周围有璎珞。","notes":[]},{"n":37,"t":"十个盆座都是这样，铸法、尺寸、样式相同。","notes":[]},{"n":38,"t":"又用铜制造十个盆，每盆可容四十罢特。盆径四肘，在那十座上，每座安设一盆。","notes":[]},{"n":39,"t":"五个安在殿门的右边，五个放在殿门的左边；又将海放在殿门的右旁，就是南边。","notes":[]},{"n":40,"t":"户兰又造了盆、铲子，和盘子。这样，他为所罗门王做完了耶和华殿的一切工。","notes":[],"heads":["圣殿设备清单"]},{"n":41,"t":"所造的就是：两根柱子和柱上两个如球的顶；并两个盖柱顶的网子；","notes":[]},{"n":42,"t":"和四百石榴，安在两个网子上，每网两行，盖着两个柱上如球的顶；","notes":[]},{"n":43,"t":"十个座和其上的十个盆；","notes":[]},{"n":44,"t":"海和海下的十二只牛；","notes":[]},{"n":45,"t":"盆、铲子、盘子。这一切都是户兰给所罗门王用光亮的铜为耶和华的殿造成的，","notes":[]},{"n":46,"t":"是遵王命在约旦平原、疏割和撒拉但中间借胶泥铸成的。","notes":[]},{"n":47,"t":"这一切所罗门都没有过秤；因为甚多，铜的轻重也无法可查。","notes":[]},{"n":48,"t":"所罗门又造耶和华殿里的金坛和陈设饼的金桌子；","notes":[]},{"n":49,"t":"内殿前的精金灯台：右边五个，左边五个，并其上的金花、灯盏、蜡剪，","notes":[]},{"n":50,"t":"与精金的杯、盘、镊子、调羹、火鼎，以及至圣所、内殿的门枢，和外殿的门枢。","notes":[]},{"n":51,"t":"所罗门王做完了耶和华殿的一切工，就把他父大卫分别为圣的金银和器皿都带来放在耶和华殿的府库里。","notes":[],"heads":["殿工告竣"]}]},"8":{"heading":"运约柜入殿","verses":[{"n":1,"t":"那时，所罗门将以色列的长老和各支派的首领，并以色列的族长，招聚到耶路撒冷，要把耶和华的约柜从大卫城—就是锡安—运上来。","notes":[]},{"n":2,"t":"以他念月，就是七月，在节前，以色列人都聚集到所罗门王那里。","notes":[]},{"n":3,"t":"以色列长老来到，祭司便抬起约柜，","notes":[]},{"n":4,"t":"祭司和利未人将耶和华的约柜运上来，又将会幕和会幕的一切圣器具都带上来。","notes":[]},{"n":5,"t":"所罗门王和聚集到他那里的以色列全会众，一同在约柜前献牛羊为祭，多得不可胜数。","notes":[]},{"n":6,"t":"祭司将耶和华的约柜抬进内殿，就是至圣所，放在两个基路伯的翅膀底下。","notes":[]},{"n":7,"t":"基路伯张着翅膀在约柜之上，遮掩约柜和抬柜的杠。","notes":[]},{"n":8,"t":"这杠甚长，杠头在内殿前的圣所可以看见，在殿外却不能看见，直到如今还在那里。","notes":[]},{"n":9,"t":"约柜里惟有两块石版，就是以色列人出埃及地后，耶和华与他们立约的时候摩西在何烈山所放的。除此以外，并无别物。","notes":[]},{"n":10,"t":"祭司从圣所出来的时候，有云充满耶和华的殿；","notes":[]},{"n":11,"t":"甚至祭司不能站立供职，因为耶和华的荣光充满了殿。","notes":[]},{"n":12,"t":"那时所罗门说：耶和华曾说，他必住在幽暗之处。","notes":[]},{"n":13,"t":"我已经建造殿宇作你的居所，为你永远的住处。","notes":[]},{"n":14,"t":"王转脸为以色列会众祝福，以色列会众就都站立。","notes":[],"heads":["所罗门向百姓讲话"]},{"n":15,"t":"所罗门说：「耶和华—以色列的神是应当称颂的！因他亲口向我父大卫所应许的，也亲手成就了。","notes":[]},{"n":16,"t":"他说：『自从我领我民以色列出埃及以来，我未曾在以色列各支派中选择一城建造殿宇—为我名的居所，但拣选大卫治理我民以色列。』」","notes":[]},{"n":17,"t":"所罗门说：「我父大卫曾立意，要为耶和华—以色列神的名建殿。","notes":[]},{"n":18,"t":"耶和华却对我父大卫说：『你立意为我的名建殿，这意思甚好。","notes":[]},{"n":19,"t":"只是你不可建殿，惟你所生的儿子必为我名建殿。』","notes":[]},{"n":20,"t":"现在耶和华成就了他所应许的话，使我接续我父大卫坐以色列的国位，又为耶和华—以色列神的名建造了殿。","notes":[]},{"n":21,"t":"我也在其中为约柜预备一处。约柜内有耶和华的约，就是他领我们列祖出埃及地的时候，与他们所立的约。」","notes":[]},{"n":22,"t":"所罗门当着以色列会众，站在耶和华的坛前，向天举手说：","notes":[],"heads":["所罗门的祷告"]},{"n":23,"t":"「耶和华—以色列的神啊，天上地下没有神可比你的！你向那尽心行在你面前的仆人守约施慈爱；","notes":[]},{"n":24,"t":"向你仆人—我父大卫所应许的话现在应验了。你亲口应许，亲手成就，正如今日一样。","notes":[]},{"n":25,"t":"耶和华—以色列的神啊，你所应许你仆人—我父大卫的话说：『你的子孙若谨慎自己的行为，在我面前行事像你所行的一样，就不断人坐以色列的国位。』现在求你应验这话。","notes":[]},{"n":26,"t":"以色列的神啊，求你成就向你仆人—我父大卫所应许的话。","notes":[]},{"n":27,"t":"「神果真住在地上吗？看哪，天和天上的天尚且不足你居住的，何况我所建的这殿呢？","notes":[]},{"n":28,"t":"惟求耶和华—我的神垂顾仆人的祷告祈求，俯听仆人今日在你面前的祈祷呼吁。","notes":[]},{"n":29,"t":"愿你昼夜看顾这殿，就是你应许立为你名的居所；求你垂听仆人向此处祷告的话。","notes":[]},{"n":30,"t":"你仆人和你民以色列向此处祈祷的时候，求你在天上你的居所垂听，垂听而赦免。","notes":[]},{"n":31,"t":"「人若得罪邻舍，有人叫他起誓，他来到这殿在你的坛前起誓，","notes":[]},{"n":32,"t":"求你在天上垂听，判断你的仆人：定恶人有罪，照他所行的报应在他头上；定义人有理，照他的义赏赐他。","notes":[]},{"n":33,"t":"「你的民以色列若得罪你，败在仇敌面前，又归向你，承认你的名，在这殿里祈求祷告，","notes":[]},{"n":34,"t":"求你在天上垂听，赦免你民以色列的罪，使他们归回你赐给他们列祖之地。","notes":[]},{"n":35,"t":"「你的民因得罪你，你惩罚他们，使天闭塞不下雨；他们若向此处祷告，承认你的名，离开他们的罪，","notes":[]},{"n":36,"t":"求你在天上垂听，赦免你仆人以色列民的罪，将当行的善道指教他们，且降雨在你的地，就是你赐给你民为业之地。","notes":[]},{"n":37,"t":"「国中若有饥荒、瘟疫、旱风、霉烂、蝗虫、蚂蚱，或有仇敌犯境围困城邑，无论遭遇什么灾祸疾病，","notes":[]},{"n":38,"t":"你的民以色列，或是众人，或是一人，自觉有罪，向这殿举手，无论祈求什么，祷告什么，","notes":["原文是灾"]},{"n":39,"t":"求你在天上你的居所垂听赦免。你是知道人心的，要照各人所行的待他们（惟有你知道世人的心），","notes":[]},{"n":40,"t":"使他们在你赐给我们列祖之地上一生一世敬畏你。","notes":[]},{"n":41,"t":"「论到不属你民以色列的外邦人，为你名从远方而来，","notes":[]},{"n":42,"t":"（他们听人论说你的大名和大能的手，并伸出来的膀臂）向这殿祷告，","notes":[]},{"n":43,"t":"求你在天上你的居所垂听，照着外邦人所祈求的而行，使天下万民都认识你的名，敬畏你像你的民以色列一样；又使他们知道我建造的这殿是称为你名下的。","notes":[]},{"n":44,"t":"「你的民若奉你的差遣，无论往何处去与仇敌争战，向耶和华所选择的城与我为你名所建造的殿祷告，","notes":[]},{"n":45,"t":"求你在天上垂听他们的祷告祈求，使他们得胜。","notes":[]},{"n":46,"t":"「你的民若得罪你（世上没有不犯罪的人），你向他们发怒，将他们交给仇敌掳到仇敌之地，或远或近，","notes":[]},{"n":47,"t":"他们若在掳到之地想起罪来，回心转意，恳求你说：『我们有罪了，我们悖逆了，我们作恶了』；","notes":[]},{"n":48,"t":"他们若在掳到之地尽心尽性归服你，又向自己的地，就是你赐给他们列祖之地和你所选择的城，并我为你名所建造的殿祷告，","notes":[]},{"n":49,"t":"求你在天上你的居所垂听他们的祷告祈求，为他们伸冤；","notes":[]},{"n":50,"t":"饶恕得罪你的民，赦免他们的一切过犯，使他们在掳他们的人面前蒙怜恤。","notes":[]},{"n":51,"t":"因为他们是你的子民，你的产业，是你从埃及领出来脱离铁炉的。","notes":[]},{"n":52,"t":"愿你的眼目看顾仆人，听你民以色列的祈求，无论何时向你祈求，愿你垂听。","notes":[]},{"n":53,"t":"主耶和华啊，你将他们从地上的万民中分别出来作你的产业，是照你领我们列祖出埃及的时候，借你仆人摩西所应许的话。」","notes":[]},{"n":54,"t":"所罗门在耶和华的坛前屈膝跪着，向天举手，在耶和华面前祷告祈求已毕，就起来，","notes":[],"heads":["为民祝福"]},{"n":55,"t":"站着，大声为以色列全会众祝福，说：","notes":[]},{"n":56,"t":"「耶和华是应当称颂的！因为他照着一切所应许的赐平安给他的民以色列人，凡借他仆人摩西应许赐福的话，一句都没有落空。","notes":[]},{"n":57,"t":"愿耶和华—我们的神与我们同在，像与我们列祖同在一样，不撇下我们，不丢弃我们，","notes":[]},{"n":58,"t":"使我们的心归向他，遵行他的道，谨守他吩咐我们列祖的诫命、律例、典章。","notes":[]},{"n":59,"t":"我在耶和华面前祈求的这些话，愿耶和华—我们的神昼夜垂念，每日为他仆人与他民以色列伸冤，","notes":[]},{"n":60,"t":"使地上的万民都知道惟独耶和华是神，并无别神。","notes":[]},{"n":61,"t":"所以你们当向耶和华—我们的神存诚实的心，遵行他的律例，谨守他的诫命，至终如今日一样。」","notes":[]},{"n":62,"t":"王和以色列众民一同在耶和华面前献祭。","notes":[],"heads":["奉献圣殿"]},{"n":63,"t":"所罗门向耶和华献平安祭，用牛二万二千，羊十二万。这样，王和以色列众民为耶和华的殿行奉献之礼。","notes":[]},{"n":64,"t":"当日，王因耶和华殿前的铜坛太小，容不下燔祭、素祭，和平安祭牲的脂油，便将耶和华殿前院子当中分别为圣，在那里献燔祭、素祭，和平安祭牲的脂油。","notes":[]},{"n":65,"t":"那时，所罗门和以色列众人，就是从哈马口直到埃及小河所有的以色列人，都聚集成为大会，在耶和华—我们的神面前守节七日又七日，共十四日。","notes":[]},{"n":66,"t":"第八日，王遣散众民；他们都为王祝福。因见耶和华向他仆人大卫和他民以色列所施的一切恩惠，就都心中喜乐，各归各家去了。","notes":[]}]},"9":{"heading":"耶和华再向所罗门显现","verses":[{"n":1,"t":"所罗门建造耶和华殿和王宫，并一切所愿意建造的都完毕了，","notes":[]},{"n":2,"t":"耶和华就二次向所罗门显现，如先前在基遍向他显现一样，","notes":[]},{"n":3,"t":"对他说：「你向我所祷告祈求的，我都应允了。我已将你所建的这殿分别为圣，使我的名永远在其中；我的眼、我的心也必常在那里。","notes":[]},{"n":4,"t":"你若效法你父大卫，存诚实正直的心行在我面前，遵行我一切所吩咐你的，谨守我的律例典章，","notes":[]},{"n":5,"t":"我就必坚固你的国位在以色列中，直到永远，正如我应许你父大卫说：『你的子孙必不断人坐以色列的国位。』","notes":[]},{"n":6,"t":"倘若你们和你们的子孙转去不跟从我，不守我指示你们的诫命律例，去事奉敬拜别神，","notes":[]},{"n":7,"t":"我就必将以色列人从我赐给他们的地上剪除，并且我为己名所分别为圣的殿也必舍弃不顾，使以色列人在万民中作笑谈，被讥诮。","notes":[]},{"n":8,"t":"这殿虽然甚高，将来经过的人必惊讶、嗤笑，说：『耶和华为何向这地和这殿如此行呢？』","notes":[]},{"n":9,"t":"人必回答说：『是因此地的人离弃领他们列祖出埃及地之耶和华—他们的神，去亲近别神，事奉敬拜他，所以耶和华使这一切灾祸临到他们。』」","notes":[]},{"n":10,"t":"所罗门建造耶和华殿和王宫，这两所二十年才完毕了。","notes":[],"heads":["所罗门跟希兰订约"]},{"n":11,"t":"泰尔王希兰曾照所罗门所要的，资助他香柏木、松木，和金子；所罗门王就把加利利地的二十座城给了希兰。","notes":[]},{"n":12,"t":"希兰从泰尔出来，察看所罗门给他的城邑，就不喜悦，","notes":[]},{"n":13,"t":"说：「我兄啊，你给我的是什么城邑呢？」他就给这城邑之地起名叫迦步勒，直到今日。","notes":[]},{"n":14,"t":"希兰给所罗门一百二十他连得金子。","notes":[]},{"n":15,"t":"所罗门王挑取服苦的人，是为建造耶和华的殿、自己的宫、米罗、耶路撒冷的城墙、夏琐、米吉多，并基 色。","notes":[],"heads":["所罗门其他政绩"]},{"n":16,"t":"先前埃及王法老上来攻取基色，用火焚烧，杀了城内居住的迦南人，将城赐给他女儿所罗门的妻作妆奁。","notes":[]},{"n":17,"t":"所罗门建造基色、下伯·和仑、","notes":[]},{"n":18,"t":"巴拉，并国中旷野里的达莫，","notes":[]},{"n":19,"t":"又建造所有的积货城，并屯车和马兵的城，与耶路撒冷、黎巴嫩，以及自己治理的全国中所愿建造的。","notes":[]},{"n":20,"t":"至于国中所剩下不属以色列人的亚摩利人、赫人、比利洗人、希未人、耶布斯人，","notes":[]},{"n":21,"t":"就是以色列人不能灭尽的，所罗门挑取他们的后裔作服苦的奴仆，直到今日。","notes":[]},{"n":22,"t":"惟有以色列人，所罗门不使他们作奴仆，乃是作他的战士、臣仆、统领、军长、车兵长、马兵长。","notes":[]},{"n":23,"t":"所罗门有五百五十督工的，监管工人。","notes":[]},{"n":24,"t":"法老的女儿从大卫城搬到所罗门为她建造的宫里。那时，所罗门才建造米罗。","notes":[]},{"n":25,"t":"所罗门每年三次在他为耶和华所筑的坛上献燔祭和平安祭，又在耶和华面前的坛上烧香。这样，他建造殿的工程完毕了。","notes":[]},{"n":26,"t":"所罗门王在以东地红海边，靠近以禄的以旬·迦别制造船只。","notes":[]},{"n":27,"t":"希兰差遣他的仆人，就是熟悉泛海的船家，与所罗门的仆人一同坐船航海。","notes":[]},{"n":28,"t":"他们到了俄斐，从那里得了四百二十他连得金子，运到所罗门王那里。","notes":[]}]},"10":{"heading":"示巴女王拜访所罗门","verses":[{"n":1,"t":"示巴女王听见所罗门因耶和华之名所得的名声，就来要用难解的话试问所罗门。","notes":[]},{"n":2,"t":"跟随她到耶路撒冷的人甚多，又有骆驼驮着香料、宝石，和许多金子。她来见了所罗门王，就把心里所有的对所罗门都说出来。","notes":[]},{"n":3,"t":"所罗门王将她所问的都答上了，没有一句不明白、不能答的。","notes":[]},{"n":4,"t":"示巴女王见所罗门大有智慧，和他所建造的宫室，","notes":[]},{"n":5,"t":"席上的珍馐美味，群臣分列而坐，仆人两旁侍立，以及他们的衣服装饰和酒政的衣服装饰，又见他上耶和华殿的台阶，就诧异得神不守舍；","notes":["或译：他在耶和华殿里所献的燔祭"]},{"n":6,"t":"对王说：「我在本国里所听见论到你的事和你的智慧实在是真的！","notes":[]},{"n":7,"t":"我先不信那些话，及至我来亲眼见了才知道人所告诉我的还不到一半。你的智慧和你的福分越过我所听见的风声。","notes":[]},{"n":8,"t":"你的臣子、你的仆人常侍立在你面前听你智慧的话是有福的！","notes":[]},{"n":9,"t":"耶和华—你的神是应当称颂的！他喜悦你，使你坐以色列的国位；因为他永远爱以色列，所以立你作王，使你秉公行义。」","notes":[]},{"n":10,"t":"于是，示巴女王将一百二十他连得金子和宝石，与极多的香料，送给所罗门王。她送给王的香料，以后奉来的不再有这样多。","notes":[]},{"n":11,"t":"希兰的船只从俄斐运了金子来，又从俄斐运了许多檀香木和宝石来。","notes":["或译：乌木；下同"]},{"n":12,"t":"王用檀香木为耶和华殿和王宫做栏杆，又为歌唱的人做琴瑟。以后再没有这样的檀香木进国来，也没有人看见过，直到如今。","notes":[]},{"n":13,"t":"示巴女王一切所要所求的，所罗门王都送给她，另外照自己的厚意馈送她。于是女王和她臣仆转回本国去了。","notes":[]},{"n":14,"t":"所罗门每年所得的金子共有六百六十六他连得。","notes":[],"heads":["所罗门的财富"]},{"n":15,"t":"另外还有商人和杂族的诸王，与国中的省长所进的金子。","notes":["杂族在历代下九章十四节是阿拉伯"]},{"n":16,"t":"所罗门王用锤出来的金子打成挡牌二百面，每面用金子六百舍客勒；","notes":[]},{"n":17,"t":"又用锤出来的金子打成盾牌三百面，每面用金子三弥那，都放在黎巴嫩林宫里。","notes":[]},{"n":18,"t":"王用象牙制造一个宝座，用精金包裹。","notes":[]},{"n":19,"t":"宝座有六层台阶，座的后背是圆的，两旁有扶手，靠近扶手有两个狮子站立。","notes":[]},{"n":20,"t":"六层台阶上有十二个狮子站立，每层有两个：左边一个，右边一个；在列国中没有这样做的。","notes":[]},{"n":21,"t":"所罗门王一切的饮器都是金子的。黎巴嫩林宫里的一切器皿都是精金的。所罗门年间，银子算不了什么。","notes":[]},{"n":22,"t":"因为王有他施船只与希兰的船只一同航海，三年一次，装载金银、象牙、猿猴、孔雀回来。","notes":[]},{"n":23,"t":"所罗门王的财宝与智慧胜过天下的列王。","notes":[]},{"n":24,"t":"普天下的王都求见所罗门，要听神赐给他智慧的话。","notes":[]},{"n":25,"t":"他们各带贡物，就是金器、银器、衣服、军械、香料、骡马，每年有一定之例。","notes":[]},{"n":26,"t":"所罗门聚集战车马兵，有战车一千四百辆，马兵一万二千名，安置在屯车的城邑和耶路撒冷，就是王那里。","notes":[],"heads":["所罗门的车骑"]},{"n":27,"t":"王在耶路撒冷使银子多如石头，香柏木多如高原的桑树。","notes":[]},{"n":28,"t":"所罗门的马是从埃及带来的，是王的商人一群一群按着定价买来的。","notes":[]},{"n":29,"t":"从埃及买来的车，每辆价银六百舍客勒，马每匹一百五十舍客勒。赫人诸王和亚兰诸王所买的车马，也是按这价值经他们手买来的。","notes":[]}]},"11":{"heading":"所罗门离弃神","verses":[{"n":1,"t":"所罗门王在法老的女儿之外，又宠爱许多外邦女子，就是摩押女子、亚扪女子、以东女子、西顿女子、赫人女子。","notes":[]},{"n":2,"t":"论到这些国的人，耶和华曾晓谕以色列人说：「你们不可与她们往来相通，因为她们必诱惑你们的心去随从她们的神。」所罗门却恋爱这些女子。","notes":[]},{"n":3,"t":"所罗门有妃七百，都是公主；还有嫔三百。这些妃嫔诱惑他的心。","notes":[]},{"n":4,"t":"所罗门年老的时候，他的妃嫔诱惑他的心去随从别神，不效法他父亲大卫诚诚实实地顺服耶和华—他的神。","notes":[]},{"n":5,"t":"因为所罗门随从西顿人的女神亚斯她录和亚扪人可憎的神米勒公。","notes":[]},{"n":6,"t":"所罗门行耶和华眼中看为恶的事，不效法他父亲大卫专心顺从耶和华。","notes":[]},{"n":7,"t":"所罗门为摩押可憎的神基抹和亚扪人可憎的神摩洛，在耶路撒冷对面的山上建筑邱坛。","notes":[]},{"n":8,"t":"他为那些向自己的神烧香献祭的外邦女子，就是他娶来的妃嫔也是这样行。","notes":[]},{"n":9,"t":"耶和华向所罗门发怒，因为他的心偏离向他两次显现的耶和华—以色列的神。","notes":[]},{"n":10,"t":"耶和华曾吩咐他不可随从别神，他却没有遵守耶和华所吩咐的。","notes":[]},{"n":11,"t":"所以耶和华对他说：「你既行了这事，不遵守我所吩咐你守的约和律例，我必将你的国夺回，赐给你的臣子。","notes":[]},{"n":12,"t":"然而，因你父亲大卫的缘故，我不在你活着的日子行这事，必从你儿子的手中将国夺回。","notes":[]},{"n":13,"t":"只是我不将全国夺回，要因我仆人大卫和我所选择的耶路撒冷，还留一支派给你的儿子。」","notes":[]},{"n":14,"t":"耶和华使以东人哈达兴起，作所罗门的敌人；他是以东王的后裔。","notes":[],"heads":["所罗门的敌人"]},{"n":15,"t":"先前大卫攻击以东，元帅约押上去葬埋阵亡的人，将以东的男丁都杀了。","notes":[]},{"n":16,"t":"约押和以色列众人在以东住了六个月，直到将以东的男丁尽都剪除。","notes":[]},{"n":17,"t":"那时哈达还是幼童；他和他父亲的臣仆，几个以东人逃往埃及。","notes":[]},{"n":18,"t":"他们从米甸起行，到了巴兰；从巴兰带着几个人来到埃及见埃及王法老；法老为他派定粮食，又给他房屋田地。","notes":[]},{"n":19,"t":"哈达在法老面前大蒙恩惠，以致法老将王后答比匿的妹子赐他为妻。","notes":[]},{"n":20,"t":"答比匿的妹子给哈达生了一个儿子，名叫基努拔。答比匿使基努拔在法老的宫里断奶，基努拔就与法老的众子一同住在法老的宫里。","notes":[]},{"n":21,"t":"哈达在埃及听见大卫与他列祖同睡，元帅约押也死了，就对法老说：「求王容我回本国去。」","notes":[]},{"n":22,"t":"法老对他说：「你在我这里有什么缺乏，你竟要回你本国去呢？」他回答说：「我没有缺乏什么，只是求王容我回去。」","notes":[]},{"n":23,"t":"神又使以利亚大的儿子利逊兴起，作所罗门的敌人。他先前逃避主人琐巴王哈大底谢。","notes":[]},{"n":24,"t":"大卫击杀琐巴人的时候，利逊招聚了一群人，自己作他们的头目，往大马士革居住，在那里作王。","notes":[]},{"n":25,"t":"所罗门活着的时候，哈达为患之外，利逊也作以色列的敌人。他恨恶以色列人，且作了亚兰人的王。","notes":[]},{"n":26,"t":"所罗门的臣仆、尼八的儿子耶罗波安也举手攻击王。他是以法莲支派的洗利达人，他母亲是寡妇，名叫洗鲁阿。","notes":[],"heads":["神给耶罗波安的应许"]},{"n":27,"t":"他举手攻击王的缘故，乃由先前所罗门建造米罗，修补他父亲大卫城的破口。","notes":[]},{"n":28,"t":"耶罗波安是大有才能的人。所罗门见这少年人殷勤，就派他监管约瑟家的一切工程。","notes":[]},{"n":29,"t":"一日，耶罗波安出了耶路撒冷，示罗人先知亚希雅在路上遇见他；亚希雅身上穿着一件新衣。他们二人在田野，以外并无别人。","notes":[]},{"n":30,"t":"亚希雅将自己穿的那件新衣撕成十二片，","notes":[]},{"n":31,"t":"对耶罗波安说：「你可以拿十片。耶和华—以色列的神如此说：『我必将国从所罗门手里夺回，将十个支派赐给你。（","notes":[]},{"n":32,"t":"我因仆人大卫和我在以色列众支派中所选择的耶路撒冷城的缘故，仍给所罗门留一个支派。）","notes":[]},{"n":33,"t":"因为他离弃我，敬拜西顿人的女神亚斯她录、摩押的神基抹，和亚扪人的神米勒公，没有遵从我的道，行我眼中看为正的事，守我的律例典章，像他父亲大卫一样。","notes":[]},{"n":34,"t":"但我不从他手里将全国夺回；使他终身为君，是因我所拣选的仆人大卫谨守我的诫命律例。","notes":[]},{"n":35,"t":"我必从他儿子的手里将国夺回，以十个支派赐给你，","notes":[]},{"n":36,"t":"还留一个支派给他的儿子，使我仆人大卫在我所选择立我名的耶路撒冷城里，在我面前长有灯光。","notes":[]},{"n":37,"t":"我必拣选你，使你照心里一切所愿的，作王治理以色列。","notes":[]},{"n":38,"t":"你若听从我一切所吩咐你的，遵行我的道，行我眼中看为正的事，谨守我的律例诫命，像我仆人大卫所行的，我就与你同在，为你立坚固的家，像我为大卫所立的一样，将以色列人赐给你。","notes":[]},{"n":39,"t":"我必因所罗门所行的使大卫后裔受患难，但不至于永远。』」","notes":[]},{"n":40,"t":"所罗门因此想要杀耶罗波安。耶罗波安却起身逃往埃及；到了埃及王示撒那里，就住在埃及，直到所罗门死了。","notes":[]},{"n":41,"t":"所罗门其余的事，凡他所行的和他的智慧都写在所罗门记上。","notes":[],"heads":["所罗门去世"]},{"n":42,"t":"所罗门在耶路撒冷作以色列众人的王共四十年。","notes":[]},{"n":43,"t":"所罗门与他列祖同睡，葬在他父亲大卫的城里。他儿子罗波安接续他作王。","notes":[]}]},"12":{"heading":"北方的支派反叛","verses":[{"n":1,"t":"罗波安往示剑去；因为以色列人都到了示剑要立他作王。","notes":[]},{"n":2,"t":"尼八的儿子耶罗波安先前躲避所罗门王，逃往埃及，住在那里（他听见这事。）","notes":[]},{"n":3,"t":"以色列人打发人去请他来，他就和以色列会众都来见罗波安，对他说：","notes":[]},{"n":4,"t":"「你父亲使我们负重轭，做苦工，现在求你使我们做的苦工、负的重轭轻松些，我们就事奉你。」","notes":[]},{"n":5,"t":"罗波安对他们说：「你们暂且去，第三日再来见我。」民就去了。","notes":[]},{"n":6,"t":"罗波安之父所罗门在世的日子，有侍立在他面前的老年人，罗波安王和他们商议，说：「你们给我出个什么主意，我好回复这民。」","notes":[]},{"n":7,"t":"老年人对他说：「现在王若服事这民如仆人，用好话回答他们，他们就永远作王的仆人。」","notes":[]},{"n":8,"t":"王却不用老年人给他出的主意，就和那些与他一同长大、在他面前侍立的少年人商议，","notes":[]},{"n":9,"t":"说：「这民对我说：『你父亲使我们负重轭，求你使我们轻松些。』你们给我出个什么主意，我好回复他们。」","notes":[]},{"n":10,"t":"那同他长大的少年人说：「这民对王说：『你父亲使我们负重轭，求你使我们轻松些。』王要对他们如此说：『我的小拇指头比我父亲的腰还粗。","notes":[]},{"n":11,"t":"我父亲使你们负重轭，我必使你们负更重的轭！我父亲用鞭子责打你们，我要用蝎子鞭责打你们！』」","notes":[]},{"n":12,"t":"耶罗波安和众百姓遵着罗波安王所说「你们第三日再来见我」的那话，第三日他们果然来了。","notes":[]},{"n":13,"t":"王用严厉的话回答百姓，不用老年人给他所出的主意，","notes":[]},{"n":14,"t":"照着少年人所出的主意对民说：「我父亲使你们负重轭，我必使你们负更重的轭！我父亲用鞭子责打你们，我要用蝎子鞭责打你们！」","notes":[]},{"n":15,"t":"王不肯依从百姓，这事乃出于耶和华，为要应验他借示罗人亚希雅对尼八的儿子耶罗波安所说的话。","notes":[]},{"n":16,"t":"以色列众民见王不依从他们，就对王说：我们与大卫有什么分儿呢？与耶西的儿子并没有关涉。以色列人哪，各回各家去吧！大卫家啊，自己顾自己吧！于是，以色列人都回自己家里去了，","notes":[]},{"n":17,"t":"惟独住犹大城邑的以色列人，罗波安仍作他们的王。","notes":[]},{"n":18,"t":"罗波安王差遣掌管服苦之人的亚多兰往以色列人那里去，以色列人就用石头打死他。罗波安王急忙上车，逃回耶路撒冷去了。","notes":[]},{"n":19,"t":"这样，以色列人背叛大卫家，直到今日。","notes":[]},{"n":20,"t":"以色列众人听见耶罗波安回来了，就打发人去请他到会众面前，立他作以色列众人的王。除了犹大支派以外，没有顺从大卫家的。","notes":[]},{"n":21,"t":"罗波安来到耶路撒冷，招聚犹大全家和便雅悯支派的人共十八万，都是挑选的战士，要与以色列家争战，好将国夺回，再归所罗门的儿子罗波安。","notes":[],"heads":["示玛雅的预言"]},{"n":22,"t":"但神的话临到神人示玛雅，说：","notes":[]},{"n":23,"t":"「你去告诉所罗门的儿子犹大王罗波安和犹大、便雅悯全家，并其余的民说：","notes":[]},{"n":24,"t":"『耶和华如此说：你们不可上去与你们的弟兄以色列人争战。各归各家去吧！因为这事出于我。』」众人就听从耶和华的话，遵着耶和华的命回去了。","notes":[]},{"n":25,"t":"耶罗波安在以法莲山地建筑示剑，就住在其中；又从示剑出去，建筑毗努伊勒。","notes":[],"heads":["耶罗波安离弃神"]},{"n":26,"t":"耶罗波安心里说：「恐怕这国仍归大卫家；","notes":[]},{"n":27,"t":"这民若上耶路撒冷去，在耶和华的殿里献祭，他们的心必归向他们的主—犹大王罗波安，就把我杀了，仍归犹大王罗波安。」","notes":[]},{"n":28,"t":"耶罗波安王就筹划定妥，铸造了两个金牛犊，对众民说：「以色列人哪，你们上耶路撒冷去实在是难；这就是领你们出埃及地的神。」","notes":[]},{"n":29,"t":"他就把牛犊一只安在伯特利，一只安在但。","notes":[]},{"n":30,"t":"这事叫百姓陷在罪里，因为他们往但去拜那牛犊。","notes":[]},{"n":31,"t":"耶罗波安在邱坛那里建殿，将那不属利未人的凡民立为祭司。","notes":[]},{"n":32,"t":"耶罗波安定八月十五日为节期，像在犹大的节期一样，自己上坛献祭。他在伯特利也这样向他所铸的牛犊献祭，又将立为邱坛的祭司安置在伯特利。","notes":[],"heads":["在伯特利拜牛犊被定罪"]},{"n":33,"t":"他在八月十五日，就是他私自所定的月日，为以色列人立作节期的日子，在伯特利上坛烧香。","notes":[]}]},"13":{"heading":"伯特利的老先知","verses":[{"n":1,"t":"那时，有一个神人奉耶和华的命从犹大来到伯特利。耶罗波安正站在坛旁要烧香；","notes":[]},{"n":2,"t":"神人奉耶和华的命向坛呼叫，说：「坛哪，坛哪！耶和华如此说：大卫家里必生一个儿子，名叫约西亚，他必将邱坛的祭司，就是在你上面烧香的，杀在你上面，人的骨头也必烧在你上面。」","notes":[]},{"n":3,"t":"当日，神人设个预兆，说：「这坛必破裂，坛上的灰必倾撒，这是耶和华说的预兆。」","notes":[]},{"n":4,"t":"耶罗波安王听见神人向伯特利的坛所呼叫的话，就从坛上伸手，说：「拿住他吧！」王向神人所伸的手就枯干了，不能弯回；","notes":[]},{"n":5,"t":"坛也破裂了，坛上的灰倾撒了，正如神人奉耶和华的命所设的预兆。","notes":[]},{"n":6,"t":"王对神人说：「请你为我祷告，求耶和华—你神的恩典使我的手复原。」于是神人祈祷耶和华，王的手就复了原，仍如寻常一样。","notes":[]},{"n":7,"t":"王对神人说：「请你同我回去吃饭，加添心力，我也必给你赏赐。」","notes":[]},{"n":8,"t":"神人对王说：「你就是把你的宫一半给我，我也不同你进去，也不在这地方吃饭喝水；","notes":[]},{"n":9,"t":"因为有耶和华的话嘱咐我，说不可在伯特利吃饭喝水，也不可从你去的原路回来。」","notes":[]},{"n":10,"t":"于是神人从别的路回去，不从伯特利来的原路回去。","notes":[]},{"n":11,"t":"有一个老先知住在伯特利，他儿子们来，将神人当日在伯特利所行的一切事和向王所说的话都告诉了父亲。","notes":[]},{"n":12,"t":"父亲问他们说：「神人从哪条路去了呢？」儿子们就告诉他；原来他们看见那从犹大来的神人所去的路。","notes":[]},{"n":13,"t":"老先知就吩咐他儿子们说：「你们为我备驴。」他们备好了驴，他就骑上，","notes":[]},{"n":14,"t":"去追赶神人，遇见他坐在橡树底下，就问他说：「你是从犹大来的神人不是？」他说：「是。」","notes":[]},{"n":15,"t":"老先知对他说：「请你同我回家吃饭。」","notes":[]},{"n":16,"t":"神人说：「我不可同你回去进你的家，也不可在这里同你吃饭喝水；","notes":[]},{"n":17,"t":"因为有耶和华的话嘱咐我说：『你在那里不可吃饭喝水，也不可从你去的原路回来。』」","notes":[]},{"n":18,"t":"老先知对他说：「我也是先知，和你一样。有天使奉耶和华的命对我说：『你去把他带回你的家，叫他吃饭喝水。』」这都是老先知诓哄他。","notes":[]},{"n":19,"t":"于是神人同老先知回去，在他家里吃饭喝水。","notes":[]},{"n":20,"t":"二人坐席的时候，耶和华的话临到那带神人回来的先知，","notes":[]},{"n":21,"t":"他就对那从犹大来的神人说：「耶和华如此说：你既违背耶和华的话，不遵守耶和华—你神的命令，","notes":[]},{"n":22,"t":"反倒回来，在耶和华禁止你吃饭喝水的地方吃了喝了，因此你的尸身不得入你列祖的坟墓。」","notes":[]},{"n":23,"t":"吃喝完了，老先知为所带回来的先知备驴。","notes":[]},{"n":24,"t":"他就去了，在路上有个狮子遇见他，将他咬死，尸身倒在路上，驴站在尸身旁边，狮子也站在尸身旁边。","notes":[]},{"n":25,"t":"有人从那里经过，看见尸身倒在路上，狮子站在尸身旁边，就来到老先知所住的城里述说这事。","notes":[]},{"n":26,"t":"那带神人回来的先知听见这事，就说：「这是那违背了耶和华命令的神人，所以耶和华把他交给狮子；狮子抓伤他，咬死他，是应验耶和华对他说的话。」","notes":[]},{"n":27,"t":"老先知就吩咐他儿子们说：「你们为我备驴。」他们就备了驴。","notes":[]},{"n":28,"t":"他去了，看见神人的尸身倒在路上，驴和狮子站在尸身旁边，狮子却没有吃尸身，也没有抓伤驴。","notes":[]},{"n":29,"t":"老先知就把神人的尸身驮在驴上，带回自己的城里，要哀哭他，葬埋他；","notes":[]},{"n":30,"t":"就把他的尸身葬在自己的坟墓里，哀哭他，说：「哀哉！我兄啊。」","notes":[]},{"n":31,"t":"安葬之后，老先知对他儿子们说：「我死了，你们要葬我在神人的坟墓里，使我的尸骨靠近他的尸骨，","notes":[]},{"n":32,"t":"因为他奉耶和华的命指着伯特利的坛和撒马利亚各城有邱坛之殿所说的话必定应验。」","notes":[]},{"n":33,"t":"这事以后，耶罗波安仍不离开他的恶道，将凡民立为邱坛的祭司；凡愿意的，他都分别为圣，立为邱坛的祭司。","notes":[],"heads":["耶罗波安的严重罪行"]},{"n":34,"t":"这事叫耶罗波安的家陷在罪里，甚至他的家从地上除灭了。","notes":[]}]},"14":{"heading":"耶罗波安的儿子去世","verses":[{"n":1,"t":"那时，耶罗波安的儿子亚比雅病了。","notes":[]},{"n":2,"t":"耶罗波安对他的妻说：「你可以起来改装，使人不知道你是耶罗波安的妻，往示罗去，在那里有先知亚希雅。他曾告诉我说，你必作这民的王。","notes":[]},{"n":3,"t":"现在你要带十个饼，与几个薄饼，和一瓶蜜去见他，他必告诉你儿子将要怎样。」","notes":[]},{"n":4,"t":"耶罗波安的妻就这样行，起身往示罗去，到了亚希雅的家。亚希雅因年纪老迈，眼目发直，不能看见。","notes":[]},{"n":5,"t":"耶和华先晓谕亚希雅说：「耶罗波安的妻要来问你，因她儿子病了，你当如此如此告诉她。她进来的时候必装作别的妇人。」","notes":[]},{"n":6,"t":"她刚进门，亚希雅听见她脚步的响声，就说：「耶罗波安的妻，进来吧！你为何装作别的妇人呢？我奉差遣将凶事告诉你。","notes":[]},{"n":7,"t":"你回去告诉耶罗波安说：『耶和华—以色列的神如此说：我从民中将你高举，立你作我民以色列的君，","notes":[]},{"n":8,"t":"将国从大卫家夺回赐给你；你却不效法我仆人大卫，遵守我的诫命，一心顺从我，行我眼中看为正的事。","notes":[]},{"n":9,"t":"你竟行恶，比那在你以先的更甚，为自己立了别神，铸了偶像，惹我发怒，将我丢在背后。","notes":[]},{"n":10,"t":"因此，我必使灾祸临到耶罗波安的家，将属耶罗波安的男丁，无论困住的、自由的都从以色列中剪除，必除尽耶罗波安的家，如人除尽粪土一般。","notes":[]},{"n":11,"t":"凡属耶罗波安的人，死在城中的必被狗吃，死在田野的必被空中的鸟吃。这是耶和华说的。』","notes":[]},{"n":12,"t":"所以你起身回家去吧！你的脚一进城，你儿子就必死了。","notes":[]},{"n":13,"t":"以色列众人必为他哀哭，将他葬埋。凡属耶罗波安的人，惟有他得入坟墓；因为在耶罗波安的家中，只有他向耶和华—以色列的神显出善行。","notes":[]},{"n":14,"t":"耶和华必另立一王治理以色列。到了日期，他必剪除耶罗波安的家；那日期已经到了。","notes":[]},{"n":15,"t":"耶和华必击打以色列人，使他们摇动，像水中的芦苇一般；又将他们从耶和华赐给他们列祖的美地上拔出来，分散在大河那边；因为他们做木偶，惹耶和华发怒。","notes":[]},{"n":16,"t":"因耶罗波安所犯的罪，又使以色列人陷在罪里，耶和华必将以色列人交给仇敌。」","notes":[]},{"n":17,"t":"耶罗波安的妻起身回去，到了得撒，刚到门槛，儿子就死了。","notes":[]},{"n":18,"t":"以色列众人将他葬埋，为他哀哭，正如耶和华借他仆人先知亚希雅所说的话。","notes":[]},{"n":19,"t":"耶罗波安其余的事，他怎样争战，怎样作王，都写在以色列诸王记上。","notes":[],"heads":["耶罗波安去世"]},{"n":20,"t":"耶罗波安作王二十二年，就与他列祖同睡。他儿子拿答接续他作王。","notes":[]},{"n":21,"t":"所罗门的儿子罗波安作犹大王。他登基的时候年四十一岁，在耶路撒冷，就是耶和华从以色列众支派中所选择立他名的城，作王十七年。罗波安的母亲名叫拿玛，是亚扪人。","notes":[],"heads":["犹大王罗波安"]},{"n":22,"t":"犹大人行耶和华眼中看为恶的事，犯罪触动他的愤恨，比他们列祖更甚。","notes":[]},{"n":23,"t":"因为他们在各高冈上，各青翠树下筑坛，立柱像和木偶。","notes":[]},{"n":24,"t":"国中也有娈童。犹大人效法耶和华在以色列人面前所赶出的外邦人，行一切可憎恶的事。","notes":[]},{"n":25,"t":"罗波安王第五年，埃及王示撒上来攻取耶路撒冷，","notes":[]},{"n":26,"t":"夺了耶和华殿和王宫里的宝物，尽都带走，又夺去所罗门制造的金盾牌。","notes":[]},{"n":27,"t":"罗波安王制造铜盾牌代替那金盾牌，交给守王宫门的护卫长看守。","notes":[]},{"n":28,"t":"王每逢进耶和华的殿，护卫兵就拿这盾牌，随后仍将盾牌送回，放在护卫房。","notes":[]},{"n":29,"t":"罗波安其余的事，凡他所行的，都写在犹大列王记上。","notes":[]},{"n":30,"t":"罗波安与耶罗波安时常争战。","notes":[]},{"n":31,"t":"罗波安与他列祖同睡，葬在大卫城他列祖的坟地里。他母亲名叫拿玛，是亚扪人。他儿子亚比央接续他作王。","notes":["又名_亚比雅_"]}]},"15":{"heading":"犹大王亚比央","verses":[{"n":1,"t":"尼八的儿子耶罗波安王十八年，亚比央登基作犹大王，","notes":[]},{"n":2,"t":"在耶路撒冷作王三年。他母亲名叫玛迦，是押沙龙的女儿。","notes":[]},{"n":3,"t":"亚比央行他父亲在他以前所行的一切恶，他的心不像他祖大卫的心，诚诚实实地顺服耶和华—他的神。","notes":[]},{"n":4,"t":"然而耶和华—他的神因大卫的缘故，仍使他在耶路撒冷有灯光，叫他儿子接续他作王，坚立耶路撒冷。","notes":[]},{"n":5,"t":"因为大卫除 了赫人乌利亚那件事，都是行耶和 华眼中看为正的事，一生没有违背 耶和华一切所吩咐的。","notes":[]},{"n":6,"t":"罗波安在 世的日子常与耶罗波安争战。","notes":[]},{"n":7,"t":"亚 比央其余的事，凡他所行的，都写在犹大列王记上。亚比央常与耶罗波安争战。","notes":[]},{"n":8,"t":"亚比央与他列祖同睡， 葬在大卫的城里。他儿子亚撒接续他作王。","notes":[]},{"n":9,"t":"以色列王耶罗波安二十年，亚撒登基作犹大王，","notes":[],"heads":["犹大王亚撒"]},{"n":10,"t":"在耶路撒冷作王四十一年。他祖母名叫玛迦，是押沙龙的女儿。","notes":[]},{"n":11,"t":"亚撒效法他祖大卫行耶和华眼中看为正的事，","notes":[]},{"n":12,"t":"从国中除去娈童，又除掉他列祖所造的一切偶像；","notes":[]},{"n":13,"t":"并且贬了他祖母玛迦太后的位，因她造了可憎的偶像亚舍拉。亚撒砍下她的偶像，烧在汲沦溪边，","notes":[]},{"n":14,"t":"只是邱坛还没有废去。亚撒一生却向耶和华存诚实的心。","notes":[]},{"n":15,"t":"亚撒将他父亲所分别为圣与自己所分别为圣的金银和器皿都奉到耶和华的殿里。","notes":[]},{"n":16,"t":"亚撒和以色列王巴沙在世的日子常常争战。","notes":[]},{"n":17,"t":"以色列王巴沙上来要攻击犹大，修筑拉玛，不许人从犹大王亚撒那里出入。","notes":[]},{"n":18,"t":"于是亚撒将耶和华殿和王宫府库里所剩下的金银都交在他臣仆手中，打发他们往住大马士革的亚兰王—希旬的孙子、他伯利们的儿子便·哈达那里去，","notes":[]},{"n":19,"t":"说：「你父曾与我父立约，我与你也要立约。现在我将金银送你为礼物，求你废掉你与以色列王巴沙所立的约，使他离开我。」","notes":[]},{"n":20,"t":"便·哈达听从亚撒王的话，派军长去攻击以色列的城邑；他们就攻破以云、但、亚伯·伯·玛迦、基尼烈全境、拿弗他利全境。","notes":[]},{"n":21,"t":"巴沙听见，就停工不修筑拉玛了，仍住在得撒。","notes":[]},{"n":22,"t":"于是亚撒王宣告犹大众人，不准一个推辞，吩咐他们将巴沙修筑拉玛所用的石头、木头都运去，用以修筑便雅悯的迦巴和米斯巴。","notes":[]},{"n":23,"t":"亚撒其余的事，凡他所行的，并他的勇力与他所建筑的城邑，都写在犹大列王记上。亚撒年老的时候，脚上有病。","notes":[]},{"n":24,"t":"亚撒与他列祖同睡，葬在他祖大卫城他列祖的坟地里。他儿子约沙法接续他作王。","notes":[]},{"n":25,"t":"犹大王亚撒第二年，耶罗波安的儿子拿答登基作以色列王共二年，","notes":[],"heads":["以色列王拿答"]},{"n":26,"t":"拿答行耶和华眼中看为恶的事，行他父亲所行的，犯他父亲使以色列人陷在罪里的那罪。","notes":[]},{"n":27,"t":"以萨迦人亚希雅的儿子巴沙背叛拿答，在非利士的基比顿杀了他。那时拿答和以色列众人正围困基比顿。","notes":[]},{"n":28,"t":"在犹大王亚撒第三年巴沙杀了他，篡了他的位。","notes":[]},{"n":29,"t":"巴沙一作王就杀了耶罗波安的全家，凡有气息的没有留下一个，都灭尽了，正应验耶和华借他仆人示罗人亚希雅所说的话。","notes":[]},{"n":30,"t":"这是因为耶罗波安所犯的罪使以色列人陷在罪里，惹动耶和华—以色列神的怒气。","notes":[]},{"n":31,"t":"拿答其余的事，凡他所行的，都写在以色列诸王记上。","notes":[]},{"n":32,"t":"亚撒和以色列王巴沙在世的日子常常争战。","notes":[]},{"n":33,"t":"犹大王亚撒第三年，亚希雅的儿子巴沙在得撒登基作以色列众人的王共二十四年。","notes":[],"heads":["以色列王巴沙"]},{"n":34,"t":"他行耶和华眼中看为恶的事，行耶罗波安所行的道，犯他使以色列人陷在罪里的那罪。","notes":[]}]},"16":{"heading":"以色列王以拉","verses":[{"n":1,"t":"耶和华的话临到哈拿尼的儿子耶户，责备巴沙说：","notes":[]},{"n":2,"t":"「我既从尘埃中提拔你，立你作我民以色列的君，你竟行耶罗波安所行的道，使我民以色列陷在罪里，惹我发怒，","notes":[]},{"n":3,"t":"我必除尽你和你的家，使你的家像尼八的儿子耶罗波安的家一样。","notes":[]},{"n":4,"t":"凡属巴沙的人，死在城中的必被狗吃，死在田野的必被空中的鸟吃。」","notes":[]},{"n":5,"t":"巴沙其余的事，凡他所行的和他的勇力，都写在以色列诸王记上。","notes":[]},{"n":6,"t":"巴沙与他列祖同睡，葬在得撒。他儿子以拉接续他作王。","notes":[]},{"n":7,"t":"耶和华的话临到哈拿尼的儿子先知耶户，责备巴沙和他的家，因他行耶和华眼中看为恶的一切事，以他手所做的惹耶和华发怒，像耶罗波安的家一样，又因他杀了耶罗波安的全家。","notes":[]},{"n":8,"t":"犹大王亚撒二十六年，巴沙的儿子以拉在得撒登基作以色列王共二年。","notes":[]},{"n":9,"t":"有管理他一半战车的臣子心利背叛他。当他在得撒家宰亚杂家里喝醉的时候，","notes":[]},{"n":10,"t":"心利就进去杀了他，篡了他的位。这是犹大王亚撒二十七年的事。","notes":[]},{"n":11,"t":"心利一坐王位就杀了巴沙的全家，连他的亲属、朋友也没有留下一个男丁。","notes":[]},{"n":12,"t":"心利这样灭绝巴沙的全家，正如耶和华借先知耶户责备巴沙的话。","notes":[]},{"n":13,"t":"这是因巴沙和他儿子以拉的一切罪，就是他们使以色列人陷在罪里的那罪，以虚无的神惹耶和华—以色列神的怒气。","notes":[]},{"n":14,"t":"以拉其余的事，凡他所行的，都写在以色列诸王记上。","notes":[]},{"n":15,"t":"犹大王亚撒二十七年，心利在得撒作王七日。那时民正安营围攻非利士的基比顿。","notes":[],"heads":["以色列王心利"]},{"n":16,"t":"民在营中听说心利背叛，又杀了王，故此以色列众人当日在营中立元帅暗利作以色列王。","notes":[]},{"n":17,"t":"暗利率领以色列众人，从基比顿上去，围困得撒。","notes":[]},{"n":18,"t":"心利见城破失，就进了王宫的卫所，放火焚烧宫殿，自焚而死。","notes":[]},{"n":19,"t":"这是因他犯罪，行耶和华眼中看为恶的事，行耶罗波安所行的，犯他使以色列人陷在罪里的那罪。","notes":[]},{"n":20,"t":"心利其余的事和他背叛的情形都写在以色列诸王记上。","notes":[]},{"n":21,"t":"那时，以色列民分为两半：一半随从基纳的儿子提比尼，要立他作 王；一半随从暗利。","notes":[],"heads":["以色列王暗利"]},{"n":22,"t":"但随从暗利的民胜过随从基纳的儿子提比尼的民。提比尼死了，暗利就作了王。","notes":[]},{"n":23,"t":"犹大王亚撒三十一年，暗利登基作以色列王共十二年；在得撒作王六年。","notes":[]},{"n":24,"t":"暗利用二他连得银子向撒玛买了撒马利亚山，在山上造城，就按着山的原主撒玛的名，给所造的城起名叫撒马利亚。","notes":[]},{"n":25,"t":"暗利行耶和华眼中看为恶的事，比他以前的列王作恶更甚。","notes":[]},{"n":26,"t":"因他行了尼八的儿子耶罗波安所行的，犯他使以色列人陷在罪里的那罪，以虚无的神惹耶和华—以色列神的怒气。","notes":[]},{"n":27,"t":"暗利其余的事和他所显出的勇力都写在以色列诸王记上。","notes":[]},{"n":28,"t":"暗利与他列祖同睡，葬在撒马利亚。他儿子亚哈接续他作王。","notes":[]},{"n":29,"t":"犹大王亚撒三十八年，暗利的儿子亚哈登基作了以色列王。暗利的儿子亚哈在撒马利亚作以色列王二十二年。","notes":[],"heads":["以色列王亚哈"]},{"n":30,"t":"暗利的儿子亚哈行耶和华眼中看为恶的事，比他以前的列王更甚，","notes":[]},{"n":31,"t":"犯了尼八的儿子耶罗波安所犯的罪；他还以为轻，又娶了西顿王谒巴力的女儿耶洗别为妻，去事奉敬拜巴力，","notes":[]},{"n":32,"t":"在撒马利亚建造巴力的庙，在庙里为巴力筑坛。","notes":[]},{"n":33,"t":"亚哈又做亚舍拉，他所行的惹耶和华—以色列神的怒气，比他以前的以色列诸王更甚。","notes":[]},{"n":34,"t":"亚哈在位的时候，有伯特利人希伊勒重修耶利哥城；立根基的时候，丧了长子亚比兰；安门的时候，丧了幼子西割，正如耶和华借嫩的儿子约书亚所说的话。","notes":[]}]},"17":{"heading":"以利亚和旱灾","verses":[{"n":1,"t":"基列寄居的提斯比人以利亚对亚哈说：「我指着所事奉永生耶和华—以色列的神起誓，这几年我若不祷告，必不降露，不下雨。」","notes":[]},{"n":2,"t":"耶和华的话临到以利亚说：","notes":[]},{"n":3,"t":"「你离开这里往东去，藏在约旦河东边的基立溪旁。","notes":[]},{"n":4,"t":"你要喝那溪里的水，我已吩咐乌鸦在那里供养你。」","notes":[]},{"n":5,"t":"于是以利亚照着耶和华的话，去住在约旦河东的基立溪旁。","notes":[]},{"n":6,"t":"乌鸦早晚给他叼饼和肉来，他也喝那溪里的水。","notes":[]},{"n":7,"t":"过了些日子，溪水就干了，因为雨没有下在地上。","notes":[]},{"n":8,"t":"耶和华的话临到他说：","notes":[],"heads":["以利亚和撒勒法的寡妇"]},{"n":9,"t":"「你起身往西顿的撒勒法去，住在那里；我已吩咐那里的一个寡妇供养你。」","notes":["撒勒法与路加福音四章二十六节同"]},{"n":10,"t":"以利亚就起身往撒勒法去。到了城门，见有一个寡妇在那里捡柴，以利亚呼叫她说：「求你用器皿取点水来给我喝。」","notes":[]},{"n":11,"t":"她去取水的时候，以利亚又呼叫她说：「也求你拿点饼来给我！」","notes":[]},{"n":12,"t":"她说：「我指着永生耶和华—你的神起誓，我没有饼，坛内只有一把面，瓶里只有一点油；我现在找两根柴，回家要为我和我儿子做饼；我们吃了，死就死吧！」","notes":[]},{"n":13,"t":"以利亚对她说：「不要惧怕！可以照你所说的去做吧！只要先为我做一个小饼拿来给我，然后为你和你的儿子做饼。","notes":[]},{"n":14,"t":"因为耶和华—以色列的神如此说：坛内的面必不减少，瓶里的油必不缺短，直到耶和华使雨降在地上的日子。」","notes":[]},{"n":15,"t":"妇人就照以利亚的话去行。她和她家中的人，并以利亚，吃了许多日子。","notes":[]},{"n":16,"t":"坛内的面果不减少，瓶里的油也不缺短，正如耶和华借以利亚所说的话。","notes":[]},{"n":17,"t":"这事以后，作那家主母的妇人，她儿子病了；病得甚重，以致身无气息。","notes":[]},{"n":18,"t":"妇人对以利亚说：「神人哪，我与你何干？你竟到我这里来，使神想念我的罪，以致我的儿子死呢？」","notes":[]},{"n":19,"t":"以利亚对她说：「把你儿子交给我。」以利亚就从妇人怀中将孩子接过来，抱到他所住的楼中，放在自己的床上，","notes":[]},{"n":20,"t":"就求告耶和华说：「耶和华—我的神啊，我寄居在这寡妇的家里，你就降祸与她，使她的儿子死了吗？」","notes":[]},{"n":21,"t":"以利亚三次伏在孩子的身上，求告耶和华说：「耶和华—我的神啊，求你使这孩子的灵魂仍入他的身体！」","notes":[]},{"n":22,"t":"耶和华应允以利亚的话，孩子的灵魂仍入他的身体，他就活了。","notes":[]},{"n":23,"t":"以利亚将孩子从楼上抱下来，进屋子交给他母亲，说：「看哪，你的儿子活了！」","notes":[]},{"n":24,"t":"妇人对以利亚说：「现在我知道你是神人，耶和华借你口所说的话是真的。」","notes":[]}]},"18":{"heading":"以利亚和巴力的先知们","verses":[{"n":1,"t":"过了许久，到第三年，耶和华的话临到以利亚说：「你去，使亚哈得见你；我要降雨在地上。」","notes":[]},{"n":2,"t":"以利亚就去，要使亚哈得见他。那时，撒马利亚有大饥荒；","notes":[]},{"n":3,"t":"亚哈将他的家宰俄巴底召了来。（俄巴底甚是敬畏耶和华，","notes":[]},{"n":4,"t":"耶洗别杀耶和华众先知的时候，俄巴底将一百个先知藏了，每五十人藏在一个洞里，拿饼和水供养他们。）","notes":[]},{"n":5,"t":"亚哈对俄巴底说：「我们走遍这地，到一切水泉旁和一切溪边，或者找得着青草，可以救活骡马，免得绝了牲畜。」","notes":[]},{"n":6,"t":"于是二人分地游行，亚哈独走一路，俄巴底独走一路。","notes":[]},{"n":7,"t":"俄巴底在路上恰与以利亚相遇，俄巴底认出他来，就俯伏在地，说：「你是我主以利亚不是？」","notes":[]},{"n":8,"t":"回答说：「是。你去告诉你主人说，以利亚在这里。」","notes":[]},{"n":9,"t":"俄巴底说：「仆人有什么罪，你竟要将我交在亚哈手里，使他杀我呢？","notes":[]},{"n":10,"t":"我指着永生耶和华—你的神起誓，无论哪一邦哪一国，我主都打发人去找你。若说你没有在那里，就必使那邦那国的人起誓说，实在是找不着你。","notes":[]},{"n":11,"t":"现在你说，要去告诉你主人说，以利亚在这里；","notes":[]},{"n":12,"t":"恐怕我一离开你，耶和华的灵就提你到我所不知道的地方去。这样，我去告诉亚哈，他若找不着你，就必杀我；仆人却是自幼敬畏耶和华的。","notes":[]},{"n":13,"t":"耶洗别杀耶和华众先知的时候，我将耶和华的一百个先知藏了，每五十人藏在一个洞里，拿饼和水供养他们，岂没有人将这事告诉我主吗？","notes":[]},{"n":14,"t":"现在你说，要去告诉你主人说，以利亚在这里，他必杀我。」","notes":[]},{"n":15,"t":"以利亚说：「我指着所事奉永生的万军之耶和华起誓，我今日必使亚哈得见我。」","notes":[]},{"n":16,"t":"于是俄巴底去迎着亚哈，告诉他；亚哈就去迎着以利亚。","notes":[]},{"n":17,"t":"亚哈见了以利亚，便说：「使以色列遭灾的就是你吗？」","notes":[]},{"n":18,"t":"以利亚说：「使以色列遭灾的不是我，乃是你和你父家；因为你们离弃耶和华的诫命，去随从巴力。","notes":[]},{"n":19,"t":"现在你当差遣人，招聚以色列众人和事奉巴力的那四百五十个先知，并耶洗别所供养事奉亚舍拉的那四百个先知，使他们都上迦密山去见我。」","notes":[]},{"n":20,"t":"亚哈就差遣人招聚以色列众人和先知都上迦密山。","notes":[]},{"n":21,"t":"以利亚前来对众民说：「你们心持两意要到几时呢？若耶和华是神，就当顺从耶和华；若巴力是神，就当顺从巴力。」众民一言不答。","notes":[]},{"n":22,"t":"以利亚对众民说：「作耶和华先知的只剩下我一个人；巴力的先知却有四百五十个人。","notes":[]},{"n":23,"t":"当给我们两只牛犊，巴力的先知可以挑选一只，切成块子，放在柴上，不要点火；我也预备一只牛犊放在柴上，也不点火。","notes":[]},{"n":24,"t":"你们求告你们神的名，我也求告耶和华的名。那降火显应的神，就是神。」众民回答说：「这话甚好。」","notes":[]},{"n":25,"t":"以利亚对巴力的先知说：「你们既是人多，当先挑选一只牛犊，预备好了，就求告你们神的名，却不要点火。」","notes":[]},{"n":26,"t":"他们将所得的牛犊预备好了，从早晨到午间，求告巴力的名说：「巴力啊，求你应允我们！」却没有声音，没有应允的。他们在所筑的坛四围踊跳。","notes":[]},{"n":27,"t":"到了正午，以利亚嬉笑他们，说：「大声求告吧！因为他是神，他或默想，或走到一边，或行路，或睡觉，你们当叫醒他。」","notes":[]},{"n":28,"t":"他们大声求告，按着他们的规矩，用刀枪自割、自刺，直到身体流血。","notes":[]},{"n":29,"t":"从午后直到献晚祭的时候，他们狂呼乱叫，却没有声音，没有应允的，也没有理会的。","notes":[]},{"n":30,"t":"以利亚对众民说：「你们到我这里来。」众民就到他那里。他便重修已经毁坏耶和华的坛。","notes":[]},{"n":31,"t":"以利亚照雅各子孙支派的数目，取了十二块石头（耶和华的话曾临到雅各说：「你的名要叫以色列」），","notes":[]},{"n":32,"t":"用这些石头为耶和华的名筑一座坛，在坛的四围挖沟，可容谷种二细亚，","notes":[]},{"n":33,"t":"又在坛上摆好了柴，把牛犊切成块子放在柴上，对众人说：「你们用四个桶盛满水，倒在燔祭和柴上」；","notes":[]},{"n":34,"t":"又说：「倒第二次。」他们就倒第二次；又说：「倒第三次。」他们就倒第三次。","notes":[]},{"n":35,"t":"水流在坛的四围，沟里也满了水。","notes":[]},{"n":36,"t":"到了献晚祭的时候，先知以利亚近前来，说：「亚伯拉罕、以撒、以色列的神，耶和华啊，求你今日使人知道你是以色列的神，也知道我是你的仆人，又是奉你的命行这一切事。","notes":[]},{"n":37,"t":"耶和华啊，求你应允我，应允我！使这民知道你—耶和华是神，又知道是你叫这民的心回转。」","notes":[]},{"n":38,"t":"于是，耶和华降下火来，烧尽燔祭、木柴、石头、尘土，又烧干沟里的水。","notes":[]},{"n":39,"t":"众民看见了，就俯伏在地，说：「耶和华是神！耶和华是神！」","notes":[]},{"n":40,"t":"以利亚对他们说：「拿住巴力的先知，不容一人逃脱！」众人就拿住他们。以利亚带他们到基顺河边，在那里杀了他们。","notes":[]},{"n":41,"t":"以利亚对亚哈说：「你现在可以上去吃喝，因为有多雨的响声了。」","notes":[],"heads":["旱灾停止"]},{"n":42,"t":"亚哈就上去吃喝。以利亚上了迦密山顶，屈身在地，将脸伏在两膝之中；","notes":[]},{"n":43,"t":"对仆人说：「你上去，向海观看。」仆人就上去观看，说：「没有什么。」他说：「你再去观看。」如此七次。","notes":[]},{"n":44,"t":"第七次仆人说：「我看见有一小片云从海里上来，不过如人手那样大。」以利亚说：「你上去告诉亚哈，当套车下去，免得被雨阻挡。」","notes":[]},{"n":45,"t":"霎时间，天因风云黑暗，降下大雨。亚哈就坐车往耶斯列去了。","notes":[]},{"n":46,"t":"耶和华的灵降在以利亚身上，他就束上腰，奔在亚哈前头，直到耶斯列的城门。","notes":["原文是手"]}]},"19":{"heading":"以利亚在何烈山上","verses":[{"n":1,"t":"亚哈将以利亚一切所行的和他用刀杀众先知的事都告诉耶洗别。","notes":[]},{"n":2,"t":"耶洗别就差遣人去见以利亚，告诉他说：「明日约在这时候，我若不使你的性命像那些人的性命一样，愿神明重重地降罚与我。」","notes":[]},{"n":3,"t":"以利亚见这光景就起来逃命，到了犹大的别是巴，将仆人留在那里，","notes":[]},{"n":4,"t":"自己在旷野走了一日的路程，来到一棵罗腾树下，就坐在那里求死，说：「耶和华啊，罢了！求你取我的性命，因为我不胜于我的列祖。」","notes":["罗腾，小树名，松类；下同"]},{"n":5,"t":"他就躺在罗腾树下，睡着了。有一个天使拍他，说：「起来吃吧！」","notes":[]},{"n":6,"t":"他观看，见头旁有一瓶水与炭火烧的饼，他就吃了喝了，仍然躺下。","notes":[]},{"n":7,"t":"耶和华的使者第二次来拍他，说：「起来吃吧！因为你当走的路甚远。」","notes":[]},{"n":8,"t":"他就起来吃了喝了，仗着这饮食的力，走了四十昼夜，到了神的山，就是何烈山。","notes":[]},{"n":9,"t":"他在那里进了一个洞，就住在洞中。耶和华的话临到他说：「以利亚啊，你在这里做什么？」","notes":[]},{"n":10,"t":"他说：「我为耶和华—万军之神大发热心；因为以色列人背弃了你的约，毁坏了你的坛，用刀杀了你的先知，只剩下我一个人，他们还要寻索我的命。」","notes":[]},{"n":11,"t":"耶和华说：「你出来站在山上，在我面前。」那时耶和华从那里经过，在他面前有烈风大作，崩山碎石，耶和华却不在风中；风后地震，耶和华却不在其中；","notes":[]},{"n":12,"t":"地震后有火，耶和华也不在火中；火后有微小的声音。","notes":[]},{"n":13,"t":"以利亚听见，就用外衣蒙上脸，出来站在洞口。有声音向他说：「以利亚啊，你在这里做什么？」","notes":[]},{"n":14,"t":"他说：「我为耶和华—万军之神大发热心；因为以色列人背弃了你的约，毁坏了你的坛，用刀杀了你的先知，只剩下我一个人，他们还要寻索我的命。」","notes":[]},{"n":15,"t":"耶和华对他说：「你回去，从旷野往大马士革去。到了那里，就要膏哈薛作亚兰王，","notes":[]},{"n":16,"t":"又膏宁示的孙子耶户作以色列王，并膏亚伯·米何拉人沙法的儿子以利沙作先知接续你。","notes":[]},{"n":17,"t":"将来躲避哈薛之刀的，必被耶户所杀；躲避耶户之刀的，必被以利沙所杀。","notes":[]},{"n":18,"t":"但我在以色列人中为自己留下七千人，是未曾向巴力屈膝的，未曾与巴力亲嘴的。」","notes":[]},{"n":19,"t":"于是，以利亚离开那里走了，遇见沙法的儿子以利沙耕地；在他前头有十二对牛，自己赶着第十二对。以利亚到他那里去，将自己的外衣搭在他身上。","notes":[],"heads":["以利沙蒙选召"]},{"n":20,"t":"以利沙就离开牛，跑到以利亚那里，说：「求你容我先与父母亲嘴，然后我便跟随你。」以利亚对他说：「你回去吧，我向你做了什么呢？」","notes":[]},{"n":21,"t":"以利沙就离开他回去，宰了一对牛，用套牛的器具煮肉给民吃，随后就起身跟随以利亚，服事他。","notes":[]}]},"20":{"heading":"与亚兰人争战","verses":[{"n":1,"t":"亚兰王便·哈达聚集他的全军，率领三十二个王，带着车马上来围攻撒马利亚；","notes":[]},{"n":2,"t":"又差遣使者进城见以色列王亚哈，对他说：「便·哈达如此说：","notes":[]},{"n":3,"t":"你的金银都要归我，你妻子儿女中最美的也要归我。」","notes":[]},{"n":4,"t":"以色列王回答说：「我主我王啊，可以依着你的话，我与我所有的都归你。」","notes":[]},{"n":5,"t":"使者又来说：「便·哈达如此说：我已差遣人去见你，要你将你的金银、妻子、儿女都给我。","notes":[]},{"n":6,"t":"但明日约在这时候，我还要差遣臣仆到你那里，搜查你的家和你仆人的家，将你眼中一切所喜爱的都拿了去。」","notes":[]},{"n":7,"t":"以色列王召了国中的长老来，对他们说：「请你们看看，这人是怎样地谋害我，他先差遣人到我这里来，要我的妻子、儿女，和金银，我并没有推辞他。」","notes":[]},{"n":8,"t":"长老和百姓对王说：「不要听从他，也不要应允他。」","notes":[]},{"n":9,"t":"故此，以色列王对便·哈达的使者说：「你们告诉我主我王说：王头一次差遣人向仆人所要的，仆人都依从；但这次所要的，我不能依从。」使者就去回复便·哈达。","notes":[]},{"n":10,"t":"便·哈达又差遣人去见亚哈说：「撒马利亚的尘土若够跟从我的人每人捧一捧的，愿神明重重地降罚与我！」","notes":[]},{"n":11,"t":"以色列王说：「你告诉他说，才顶盔贯甲的，休要像摘盔卸甲的夸口。」","notes":[]},{"n":12,"t":"便·哈达和诸王正在帐幕里喝酒，听见这话，就对他臣仆说：「摆队吧！」他们就摆队攻城。","notes":[]},{"n":13,"t":"有一个先知来见以色列王亚哈，说：「耶和华如此说：『这一大群人你看见了吗？今日我必将他们交在你手里，你就知道我是耶和华。』」","notes":[]},{"n":14,"t":"亚哈说：「借着谁呢？」他回答说：「耶和华说，借着跟从省长的少年人。」亚哈说：「要谁率领呢？」他说：「要你亲自率领。」","notes":[]},{"n":15,"t":"于是亚哈数点跟从省长的少年人，共有二百三十二名，后又数点以色列的众兵，共有七千名。","notes":[]},{"n":16,"t":"午间，他们就出城；便·哈达和帮助他的三十二个王正在帐幕里痛饮。","notes":[]},{"n":17,"t":"跟从省长的少年人先出城；便·哈达差遣人去探望，他们回报说：「有人从撒马利亚出来了。」","notes":[]},{"n":18,"t":"他说：「他们若为讲和出来，要活捉他们；若为打仗出来，也要活捉他们。」","notes":[]},{"n":19,"t":"跟从省长的少年人出城，军兵跟随他们；","notes":[]},{"n":20,"t":"各人遇见敌人就杀。亚兰人逃跑，以色列人追赶他们；亚兰王便·哈达骑着马和马兵一同逃跑。","notes":[]},{"n":21,"t":"以色列王出城攻打车马，大大击杀亚兰人。","notes":[]},{"n":22,"t":"那先知来见以色列王，对他说：「你当自强，留心怎样防备；因为到明年这时候，亚兰王必上来攻击你。」","notes":[]},{"n":23,"t":"亚兰王的臣仆对亚兰王说：「以色列人的神是山神，所以他们胜过我们；但在平原与他们打仗，我们必定得胜。","notes":[],"heads":["亚兰人第二次来犯"]},{"n":24,"t":"王当这样行：把诸王革去，派军长代替他们，","notes":[]},{"n":25,"t":"又照着王丧失军兵之数，再招募一军，马补马，车补车，我们在平原与他们打仗，必定得胜。」王便听臣仆的话去行。","notes":[]},{"n":26,"t":"次年，便·哈达果然点齐亚兰人上亚弗去，要与以色列人打仗。","notes":[]},{"n":27,"t":"以色列人也点齐军兵，预备食物，迎着亚兰人出去，对着他们安营，好像两小群山羊羔；亚兰人却满了地面。","notes":[]},{"n":28,"t":"有神人来见以色列王，说：「耶和华如此说：『亚兰人既说我—耶和华是山神，不是平原的神，所以我必将这一大群人都交在你手中，你们就知道我是耶和华。』」","notes":[]},{"n":29,"t":"以色列人与亚兰人相对安营七日，到第七日两军交战；那一日以色列人杀了亚兰人步兵十万，","notes":[]},{"n":30,"t":"其余的逃入亚弗城；城墙塌倒，压死剩下的二万七千人。便·哈达也逃入城，藏在严密的屋子里。","notes":[]},{"n":31,"t":"他的臣仆对他说：「我们听说以色列王都是仁慈的王，现在我们不如腰束麻布，头套绳索，出去投降以色列王，或者他存留王的性命。」","notes":[]},{"n":32,"t":"于是他们腰束麻布，头套绳索，去见以色列王，说：「王的仆人便·哈达说，求王存留我的性命。」亚哈说：「他还活着吗？他是我的兄弟。」","notes":[]},{"n":33,"t":"这些人留心探出他的口气来，便急忙就着他的话说：「便·哈达是王的兄弟！」王说：「你们去请他来。」便·哈达出来见王，王就请他上车。","notes":[]},{"n":34,"t":"便·哈达对王说：「我父从你父那里所夺的城邑，我必归还。你可以在大马士革立街市，像我父在撒马利亚所立的一样。」亚哈说：「我照此立约，放你回去」，就与他立约，放他去了。","notes":[]},{"n":35,"t":"有先知的一个门徒奉耶和华的命对他的同伴说：「你打我吧！」那人不肯打他。","notes":[],"heads":["先知责亚哈纵敌"]},{"n":36,"t":"他就对那人说：「你既不听从耶和华的话，你一离开我，必有狮子咬死你。」那人一离开他，果然遇见狮子，把他咬死了。","notes":[]},{"n":37,"t":"先知的门徒又遇见一个人，对他说：「你打我吧！」那人就打他，将他打伤。","notes":[]},{"n":38,"t":"他就去了，用头巾蒙眼，改换面目，在路旁等候王。","notes":[]},{"n":39,"t":"王从那里经过，他向王呼叫说：「仆人在阵上的时候，有人带了一个人来，对我说：『你看守这人，若把他失了，你的性命必代替他的性命；不然，你必交出一他连得银子来。』","notes":[]},{"n":40,"t":"仆人正在忙乱之间，那人就不见了。」以色列王对他说：「你自己定妥了，必照样判断你。」","notes":[]},{"n":41,"t":"他急忙除掉蒙眼的头巾，以色列王就认出他是一个先知。","notes":[]},{"n":42,"t":"他对王说：「耶和华如此说：『因你将我定要灭绝的人放去，你的命就必代替他的命，你的民也必代替他的民。』」","notes":[]},{"n":43,"t":"于是以色列王闷闷不乐地回到撒马利亚，进了他的宫。","notes":[]}]},"21":{"heading":"拿伯的葡萄园","verses":[{"n":1,"t":"这事以后，又有一事。耶斯列人拿伯在耶斯列有一个葡萄园，靠近撒马利亚王亚哈的宫。","notes":[]},{"n":2,"t":"亚哈对拿伯说：「你将你的葡萄园给我作菜园，因为是靠近我的宫；我就把更好的葡萄园换给你，或是你要银子，我就按着价值给你。」","notes":[]},{"n":3,"t":"拿伯对亚哈说：「我敬畏耶和华，万不敢将我先人留下的产业给你。」","notes":[]},{"n":4,"t":"亚哈因耶斯列人拿伯说「我不敢将我先人留下的产业给你」，就闷闷不乐地回宫，躺在床上，转脸向内，也不吃饭。","notes":[]},{"n":5,"t":"王后耶洗别来问他说：「你为什么心里这样忧闷，不吃饭呢？」","notes":[]},{"n":6,"t":"他回答说：「因我向耶斯列人拿伯说：『你将你的葡萄园给我，我给你价银，或是你愿意，我就把别的葡萄园换给你』；他却说：『我不将我的葡萄园给你。』」","notes":[]},{"n":7,"t":"王后耶洗别对亚哈说：「你现在是治理以色列国不是？只管起来，心里畅畅快快地吃饭，我必将耶斯列人拿伯的葡萄园给你。」","notes":[]},{"n":8,"t":"于是托亚哈的名写信，用王的印印上，送给那些与拿伯同城居住的长老贵胄。","notes":[]},{"n":9,"t":"信上写着说：「你们当宣告禁食，叫拿伯坐在民间的高位上，","notes":[]},{"n":10,"t":"又叫两个匪徒坐在拿伯对面，作见证告他说：『你谤渎神和王了』；随后就把他拉出去用石头打死。」","notes":[]},{"n":11,"t":"那些与拿伯同城居住的长老贵胄得了耶洗别的信，就照信而行，","notes":[]},{"n":12,"t":"宣告禁食，叫拿伯坐在民间的高位上。","notes":[]},{"n":13,"t":"有两个匪徒来，坐在拿伯的对面，当着众民作见证告他说：「拿伯谤渎神和王了！」众人就把他拉到城外，用石头打死。","notes":[]},{"n":14,"t":"于是打发人去见耶洗别，说：「拿伯被石头打死了。」","notes":[]},{"n":15,"t":"耶洗别听见拿伯被石头打死，就对亚哈说：「你起来得耶斯列人拿伯不肯为价银给你的葡萄园吧！现在他已经死了。」","notes":[]},{"n":16,"t":"亚哈听见拿伯死了，就起来，下去要得耶斯列人拿伯的葡萄园。","notes":[]},{"n":17,"t":"耶和华的话临到提斯比人以利亚说：","notes":[]},{"n":18,"t":"「你起来，去见住撒马利亚的以色列王亚哈，他下去要得拿伯的葡萄园，现今正在那园里。","notes":[]},{"n":19,"t":"你要对他说：『耶和华如此说：你杀了人，又得他的产业吗？』又要对他说：『耶和华如此说：狗在何处舔拿伯的血，也必在何处舔你的血。』」","notes":[]},{"n":20,"t":"亚哈对以利亚说：「我仇敌啊，你找到我吗？」他回答说：「我找到你了；因为你卖了自己，行耶和华眼中看为恶的事。","notes":[]},{"n":21,"t":"耶和华说：『我必使灾祸临到你，将你除尽。凡属你的男丁，无论困住的、自由的，都从以色列中剪除。","notes":[]},{"n":22,"t":"我必使你的家像尼八的儿子耶罗波安的家，又像亚希雅的儿子巴沙的家；因为你惹我发怒，又使以色列人陷在罪里。』","notes":[]},{"n":23,"t":"论到耶洗别，耶和华也说：『狗在耶斯列的外郭必吃耶洗别的肉。","notes":[]},{"n":24,"t":"凡属亚哈的人，死在城中的必被狗吃，死在田野的必被空中的鸟吃。』」（","notes":[]},{"n":25,"t":"从来没有像亚哈的，因他自卖，行耶和华眼中看为恶的事，受了王后耶洗别的耸动；","notes":[]},{"n":26,"t":"就照耶和华在以色列人面前所赶出的亚摩利人，行了最可憎恶的事，信从偶像。）","notes":[]},{"n":27,"t":"亚哈听见这话，就撕裂衣服，禁食，身穿麻布，睡卧也穿着麻布，并且缓缓而行。","notes":[]},{"n":28,"t":"耶和华的话临到提斯比人以利亚说：","notes":[]},{"n":29,"t":"「亚哈在我面前这样自卑，你看见了吗？因他在我面前自卑，他还在世的时候，我不降这祸；到他儿子的时候，我必降这祸与他的家。」","notes":[]}]},"22":{"heading":"先知米该雅警告亚哈","verses":[{"n":1,"t":"亚兰国和以色列国三年没有争战。","notes":[]},{"n":2,"t":"到第三年，犹大王约沙法下去见以色列王。","notes":[]},{"n":3,"t":"以色列王对臣仆说：「你们不知道基列的拉末是属我们的吗？我们岂可静坐不动，不从亚兰王手里夺回来吗？」","notes":[]},{"n":4,"t":"亚哈问约沙法说：「你肯同我去攻取基列的拉末吗？」约沙法对以色列王说：「你我不分彼此，我的民与你的民一样，我的马与你的马一样。」","notes":[]},{"n":5,"t":"约沙法对以色列王说：「请你先求问耶和华。」","notes":[]},{"n":6,"t":"于是以色列王招聚先知，约有四百人，问他们说：「我上去攻取基列的拉末可以不可以？」他们说：「可以上去，因为主必将那城交在王的手里。」","notes":[]},{"n":7,"t":"约沙法说：「这里不是还有耶和华的先知，我们可以求问他吗？」","notes":[]},{"n":8,"t":"以色列王对约沙法说：「还有一个人，是音拉的儿子米该雅，我们可以托他求问耶和华。只是我恨他；因为他指着我所说的预言，不说吉语，单说凶言。」约沙法说：「王不必这样说。」","notes":[]},{"n":9,"t":"以色列王就召了一个太监来，说：「你快去，将音拉的儿子米该雅召来。」","notes":[]},{"n":10,"t":"以色列王和犹大王约沙法在撒马利亚城门前的空场上，各穿朝服，坐在位上，所有的先知都在他们面前说预言。","notes":[]},{"n":11,"t":"基拿拿的儿子西底家造了两个铁角，说：「耶和华如此说：『你要用这角抵触亚兰人，直到将他们灭尽。』」","notes":[]},{"n":12,"t":"所有的先知也都这样预言说：「可以上基列的拉末去，必然得胜，因为耶和华必将那城交在王的手中。」","notes":[]},{"n":13,"t":"那去召米该雅的使者对米该雅 说：「众先知一口同音地都向王说吉言，你不如与他们说一样的话，也说吉言。」","notes":[]},{"n":14,"t":"米该雅说：「我指着永生的耶和华起誓，耶和华对我说什么，我就说什么。」","notes":[]},{"n":15,"t":"米该雅到王面前，王问他说：「米该雅啊，我们上去攻取基列的拉末可以不可以？」他回答说：「可以上去，必然得胜，耶和华必将那城交在王的手中。」","notes":[]},{"n":16,"t":"王对他说：「我当嘱咐你几次，你才奉耶和华的名向我说实话呢？」","notes":[]},{"n":17,"t":"米该雅说：「我看见以色列众民散在山上，如同没有牧人的羊群一般。耶和华说：『这民没有主人，他们可以平平安安地各归各家去。』」","notes":[]},{"n":18,"t":"以色列王对约沙法说：「我岂没有告诉你，这人指着我所说的预言，不说吉语单说凶言吗？」","notes":[]},{"n":19,"t":"米该雅说：「你要听耶和华的话！我看见耶和华坐在宝座上，天上的万军侍立在他左右。","notes":[]},{"n":20,"t":"耶和华说：『谁去引诱亚哈上基列的拉末去阵亡呢？』这个就这样说，那个就那样说。","notes":[]},{"n":21,"t":"随后有一个神灵出来，站在耶和华面前，说：『我去引诱他。』","notes":[]},{"n":22,"t":"耶和华问他说：『你用何法呢？』他说：『我去，要在他众先知口中作谎言的灵。』耶和华说：『这样，你必能引诱他，你去如此行吧！』","notes":[]},{"n":23,"t":"现在耶和华使谎言的灵入了你这些先知的口，并且耶和华已经命定降祸与你。」","notes":[]},{"n":24,"t":"基拿拿的儿子西底家前来，打米该雅的脸，说：「耶和华的灵从哪里离开我与你说话呢？」","notes":[]},{"n":25,"t":"米该雅说：「你进严密的屋子藏躲的那日，就必看见了。」","notes":[]},{"n":26,"t":"以色列王说：「将米该雅带回，交给邑宰亚们和王的儿子约阿施，说","notes":[]},{"n":27,"t":"王如此说，把这个人下在监里，使他受苦，吃不饱喝不足，等候我平平安安地回来。」","notes":[]},{"n":28,"t":"米该雅说：「你若能平平安安地回来，那就是耶和华没有借我说这话了」；又说：「众民哪，你们都要听！」","notes":[]},{"n":29,"t":"以色列王和犹大王约沙法上基列的拉末去了。","notes":[],"heads":["亚哈阵亡"]},{"n":30,"t":"以色列王对约沙法说：「我要改装上阵，你可以仍穿王服。」以色列王就改装上阵。","notes":[]},{"n":31,"t":"先是亚兰王吩咐他的三十二个车兵长说：「他们的兵将，无论大小，你们都不可与他们争战，只要与以色列王争战。」","notes":[]},{"n":32,"t":"车兵长看见约沙法，便说：「这必是以色列王！」就转过去与他争战，约沙法便呼喊。","notes":[]},{"n":33,"t":"车兵长见不是以色列王，就转去不追他了。","notes":[]},{"n":34,"t":"有一人随便开弓，恰巧射入以色列王的甲缝里。王对赶车的说：「我受了重伤，你转过车来，拉我出阵吧！」","notes":[]},{"n":35,"t":"那日，阵势越战越猛，有人扶王站在车上，抵挡亚兰人。到晚上，王就死了，血从伤处流在车中。","notes":[]},{"n":36,"t":"约在日落的时候，有号令传遍军中，说：「各归本城，各归本地吧！」","notes":[]},{"n":37,"t":"王既死了，众人将他送到撒马利亚，就葬在那里；","notes":[]},{"n":38,"t":"又有人把他的车洗在撒马利亚的池旁（妓女在那里洗澡），狗来舔他的血，正如耶和华所说的话。","notes":[]},{"n":39,"t":"亚哈其余的事，凡他所行的和他所修造的象牙宫，并所建筑的一切城邑，都写在以色列诸王记上。","notes":[]},{"n":40,"t":"亚哈与他列祖同睡。他儿子亚哈谢接续他作王。","notes":[]},{"n":41,"t":"以色列王亚哈第四年，亚撒的儿子约沙法登基作了犹大王。","notes":[],"heads":["犹大王约沙法"]},{"n":42,"t":"约沙法登基的时候年三十五岁，在耶路撒冷作王二十五年。他母亲名叫阿苏巴，乃示利希的女儿。","notes":[]},{"n":43,"t":"约沙法行他父亲亚撒所行的道，不偏离左右，行耶和华眼中看为正的事；只是邱坛还没有废去，百姓仍在那里献祭烧香。","notes":[]},{"n":44,"t":"约沙法与以色列王和好。","notes":[]},{"n":45,"t":"约沙法其余的事和他所显出的勇力，并他怎样争战，都写在犹大列王记上。","notes":[]},{"n":46,"t":"约沙法将他父亲亚撒在世所剩下的娈童都从国中除去了。","notes":[]},{"n":47,"t":"那时以东没有王，有总督治理。","notes":[]},{"n":48,"t":"约沙法制造他施船只，要往俄斐去，将金子运来；只是没有去，因为船在以旬·迦别破坏了。","notes":[]},{"n":49,"t":"亚哈的儿子亚哈谢对约沙法说：「容我的仆人和你的仆人坐船同去吧！」约沙法却不肯。","notes":[]},{"n":50,"t":"约沙法与列祖同睡。葬在大卫城他列祖的坟地里。他儿子约兰接续他作王。","notes":[]},{"n":51,"t":"犹大王约沙法十七年，亚哈的儿子亚哈谢在撒马利亚登基，作以色列王共二年。","notes":[],"heads":["以色列王亚哈谢"]},{"n":52,"t":"他行耶和华眼中看为恶的事，效法他的父母，又行尼八的儿子耶罗波安使以色列人陷在罪里的 事。","notes":[]},{"n":53,"t":"他照他父亲一切所行的，事奉敬拜巴力，惹耶和华—以色列神的怒气。","notes":[]}]}},"2KI":{"1":{"heading":"以利亚和亚哈谢王","verses":[{"n":1,"t":"亚哈死后，摩押背叛以色列。","notes":[]},{"n":2,"t":"亚哈谢在撒马利亚，一日从楼上的栏杆里掉下来，就病了；于是差遣使者说：「你们去问以革伦的神巴力·西卜，我这病能好不能好。」","notes":[]},{"n":3,"t":"但耶和华的使者对提斯比人以利亚说：「你起来，去迎着撒马利亚王的使者，对他们说：『你们去问以革伦神巴力·西卜，岂因以色列中没有神吗？』","notes":[]},{"n":4,"t":"所以耶和华如此说：『你必不下你所上的床，必定要死！』」以利亚就去了。","notes":[]},{"n":5,"t":"使者回来见王，王问他们说：「你们为什么回来呢？」","notes":[]},{"n":6,"t":"使者回答说：「有一个人迎着我们来，对我们说：『你们回去见差你们来的王，对他说：耶和华如此说，你差人去问以革伦神巴力·西卜，岂因以色列中没有神吗？所以你必不下所上的床，必定要死。』」","notes":[]},{"n":7,"t":"王问他们说：「迎着你们来告诉你们这话的，是怎样的人？」","notes":[]},{"n":8,"t":"回答说：「他身穿毛衣，腰束皮带。」王说：「这必是提斯比人以利亚。」","notes":[]},{"n":9,"t":"于是，王差遣五十夫长，带领五十人去见以利亚，他就上到以利亚那里；以利亚正坐在山顶上。五十夫长对他说：「神人哪，王吩咐你下来！」","notes":[]},{"n":10,"t":"以利亚回答说：「我若是神人，愿火从天上降下来，烧灭你和你那五十人！」于是有火从天上降下来，烧灭五十夫长和他那五十人。","notes":[]},{"n":11,"t":"王第二次差遣一个五十夫长，带领五十人去见以利亚。五十夫长对以利亚说：「神人哪，王吩咐你快快下来！」","notes":[]},{"n":12,"t":"以利亚回答说：「我若是神人，愿火从天上降下来，烧灭你和你那五十人！」于是神的火从天上降下来，烧灭五十夫长和他那五十人。","notes":[]},{"n":13,"t":"王第三次差遣一个五十夫长，带领五十人去。这五十夫长上去，双膝跪在以利亚面前，哀求他说：「神人哪，愿我的性命和你这五十个仆人的性命在你眼前看为宝贵！","notes":[]},{"n":14,"t":"已经有火从天上降下来，烧灭前两次来的五十夫长和他们各自带的五十人；现在愿我的性命在你眼前看为宝贵！」","notes":[]},{"n":15,"t":"耶和华的使者对以利亚说：「你同着他下去，不要怕他！」以利亚就起来，同着他下去见王，","notes":[]},{"n":16,"t":"对王说：「耶和华如此说：『你差人去问以革伦神巴力·西卜，岂因以色列中没有神可以求问吗？所以你必不下所上的床，必定要死！』」","notes":[]},{"n":17,"t":"亚哈谢果然死了，正如耶和华借以利亚所说的话。因他没有儿子，他兄弟约兰接续他作王，正在犹大王约沙法的儿子约兰第二年。","notes":[],"heads":["亚哈谢死后约兰继位"]},{"n":18,"t":"亚哈谢其余所行的事都写在以色列诸王记上。","notes":[]}]},"2":{"heading":"以利亚被接升天","verses":[{"n":1,"t":"耶和华要用旋风接以利亚升天的时候，以利亚与以利沙从吉甲前往。","notes":[]},{"n":2,"t":"以利亚对以利沙说：「耶和华差我往伯特利去，你可以在这里等候。」以利沙说：「我指着永生的耶和华，又敢在你面前起誓，我必不离开你。」于是二人下到伯特利。","notes":[]},{"n":3,"t":"住伯特利的先知门徒出来见以利沙，对他说：「耶和华今日要接你的师傅离开你，你知道不知道？」他说：「我知道，你们不要作声。」","notes":[]},{"n":4,"t":"以利亚对以利沙说：「耶和华差遣我往耶利哥去，你可以在这里等候。」以利沙说：「我指着永生的耶和华，又敢在你面前起誓，我必不离开你。」于是二人到了耶利哥。","notes":[]},{"n":5,"t":"住耶利哥的先知门徒就近以利沙，对他说：「耶和华今日要接你的师傅离开你，你知道不知道？」他说：「我知道，你们不要作声。」","notes":[]},{"n":6,"t":"以利亚对以利沙说：「耶和华差遣我往约旦河去，你可以在这里等候。」以利沙说：「我指着永生的耶和华，又敢在你面前起誓，我必不离开你。」于是二人一同前往。","notes":[]},{"n":7,"t":"有先知门徒去了五十人，远远地站在他们对面；二人在约旦河边站住。","notes":[]},{"n":8,"t":"以利亚将自己的外衣卷起来，用以打水，水就左右分开，二人走干地而过。","notes":[]},{"n":9,"t":"过去之后，以利亚对以利沙说：「我未曾被接去离开你，你要我为你做什么，只管求我。」以利沙说：「愿感动你的灵加倍地感动我。」","notes":[]},{"n":10,"t":"以利亚说：「你所求的难得。虽然如此，我被接去离开你的时候，你若看见我，就必得着；不然，必得不着了。」","notes":[]},{"n":11,"t":"他们正走着说话，忽有火车火马将二人隔开，以利亚就乘旋风升天去了。","notes":[],"heads":["以利亚乘旋风升天"]},{"n":12,"t":"以利沙看见，就呼叫说：「我父啊！我父啊！以色列的战车马兵啊！」以后不再见他了。于是以利沙把自己的衣服撕为两片。","notes":[]},{"n":13,"t":"他拾起以利亚身上掉下来的外衣，回去站在约旦河边。","notes":[]},{"n":14,"t":"他用以利亚身上掉下来的外衣打水，说：「耶和华—以利亚的神在哪里呢？」打水之后，水也左右分开，以利沙就过来了。","notes":[]},{"n":15,"t":"住耶利哥的先知门徒从对面看见他，就说：「感动以利亚的灵感动以利沙了。」他们就来迎接他，在他面前俯伏于地，","notes":[]},{"n":16,"t":"对他说：「仆人们这里有五十个壮士，求你容他们去寻找你师傅，或者耶和华的灵将他提起来，投在某山某谷。」以利沙说：「你们不必打发人去。」","notes":[]},{"n":17,"t":"他们再三催促他，他难以推辞，就说：「你们打发人去吧！」他们便打发五十人去，寻找了三天，也没有找着。","notes":[]},{"n":18,"t":"以利沙仍然在耶利哥等候他们回到他那里；他对他们说：「我岂没有告诉你们不必去吗？」","notes":[]},{"n":19,"t":"耶利哥城的人对以利沙说：「这城的地势美好，我主看见了；只是水恶劣，土产不熟而落。」","notes":[],"heads":["以利沙行的神迹"]},{"n":20,"t":"以利沙说：「你们拿一个新瓶来，装盐给我」；他们就拿来给他。","notes":[]},{"n":21,"t":"他出到水源，将盐倒在水中，说：「耶和华如此说：『我治好了这水，从此必不再使人死，也不再使地土不生产。』」","notes":[]},{"n":22,"t":"于是那水治好了，直到今日，正如以利沙所说的。","notes":[]},{"n":23,"t":"以利沙从那里上伯特利去，正上去的时候，有些童子从城里出来，戏笑他说：「秃头的上去吧！秃头的上去吧！」","notes":[]},{"n":24,"t":"他回头看见，就奉耶和华的名咒诅他们。于是有两只母熊从林中出来，撕裂他们中间四十二个童子。","notes":[]},{"n":25,"t":"以利沙从伯特利上迦密山，又从迦密山回到撒马利亚。","notes":[]}]},"3":{"heading":"以色列与摩押争战","verses":[{"n":1,"t":"犹大王约沙法十八年，亚哈的儿子约兰在撒马利亚登基作了以色列王十二年。","notes":[]},{"n":2,"t":"他行耶和华眼中看为恶的事，但不至像他父母所行的，因为除掉他父所造巴力的柱像。","notes":[]},{"n":3,"t":"然而，他贴近尼八的儿子耶罗波安使以色列人陷在罪里的那罪，总不离开。","notes":[]},{"n":4,"t":"摩押王米沙牧养许多羊，每年将十万羊羔的毛和十万公绵羊的毛给以色列王进贡。","notes":[]},{"n":5,"t":"亚哈死后，摩押王背叛以色列王。","notes":[]},{"n":6,"t":"那时约兰王出撒马利亚，数点以色列众人。","notes":[]},{"n":7,"t":"前行的时候，差人去见犹大王约沙法，说：「摩押王背叛我，你肯同我去攻打摩押吗？」他说：「我肯上去，你我不分彼此，我的民与你的民一样，我的马与你的马一样。」","notes":[]},{"n":8,"t":"约兰说：「我们从哪条路上去呢？」回答说：「从以东旷野的路上去。」","notes":[]},{"n":9,"t":"于是，以色列王和犹大王，并以东王，都一同去绕行七日的路程；军队和所带的牲畜没有水喝。","notes":[]},{"n":10,"t":"以色列王说：「哀哉！耶和华招聚我们这三王，乃要交在摩押人的手里。」","notes":[]},{"n":11,"t":"约沙法说：「这里不是有耶和华的先知吗？我们可以托他求问耶和华。」以色列王的一个臣子回答说：「这里有沙法的儿子以利沙，就是从前服事以利亚的。」","notes":["原文是倒水在以利亚手上的"]},{"n":12,"t":"约沙法说：「他必有耶和华的话。」于是以色列王和约沙法，并以东王都下去见他。","notes":[]},{"n":13,"t":"以利沙对以色列王说：「我与你何干？去问你父亲的先知和你母亲的先知吧！」以色列王对他说：「不要这样说，耶和华招聚我们这三王，乃要交在摩押人的手里。」","notes":[]},{"n":14,"t":"以利沙说：「我指着所事奉永生的万军耶和华起誓，我若不看犹大王约沙法的情面，必不理你，不顾你。","notes":[]},{"n":15,"t":"现在你们给我找一个弹琴的来。」弹琴的时候，耶和华的灵就降在以利沙身上。","notes":["原文是手"]},{"n":16,"t":"他便说：「耶和华如此说：『你们要在这谷中满处挖沟；","notes":[]},{"n":17,"t":"因为耶和华如此说：你们虽不见风，不见雨，这谷必满了水，使你们和牲畜有水喝。』","notes":[]},{"n":18,"t":"在耶和华眼中这还算为小事，他也必将摩押人交在你们手中。","notes":[]},{"n":19,"t":"你们必攻破一切坚城美邑，砍伐各种佳树，塞住一切水泉，用石头糟踏一切美田。」","notes":[]},{"n":20,"t":"次日早晨，约在献祭的时候，有水从以东而来，遍地就满了水。","notes":[]},{"n":21,"t":"摩押众人听见这三王上来要与他们争战，凡能顶盔贯甲的，无论老少，尽都聚集站在边界上。","notes":[],"heads":["摩押人败遁"]},{"n":22,"t":"次日早晨，日光照在水上，摩押人起来，看见对面水红如血，","notes":[]},{"n":23,"t":"就说：「这是血啊！必是三王互相击杀，俱都灭亡。摩押人哪，我们现在去抢夺财物吧！」","notes":[]},{"n":24,"t":"摩押人到了以色列营，以色列人就起来攻打他们，以致他们在以色列人面前逃跑。以色列人往前追杀摩押人，直杀入摩押的境内，","notes":[]},{"n":25,"t":"拆毁摩押的城邑，各人抛石填满一切美田，塞住一切水泉，砍伐各种佳树，只剩下吉珥·哈列设的石墙；甩石的兵在四围攻打那城。","notes":[]},{"n":26,"t":"摩押王见阵势甚大，难以对敌，就率领七百拿刀的兵，要冲过阵去到以东王那里，却是不能；","notes":[]},{"n":27,"t":"便将那应当接续他作王的长子，在城上献为燔祭。以色列人遭遇耶和华的大怒，于是三王离开摩押王，各回本国去了。","notes":["或译：招人痛恨"]}]},"4":{"heading":"以利沙帮助一个穷寡妇","verses":[{"n":1,"t":"有一个先知门徒的妻哀求以利沙说：「你仆人—我丈夫死了，他敬畏耶和华是你所知道的。现在有债主来，要取我两个儿子作奴仆。」","notes":[]},{"n":2,"t":"以利沙问她说：「我可以为你做什么呢？你告诉我，你家里有什么？」她说：「婢女家中除了一瓶油之外，没有什么。」","notes":[]},{"n":3,"t":"以利沙说：「你去，向你众邻舍借空器皿，不要少借；","notes":[]},{"n":4,"t":"回到家里，关上门，你和你儿子在里面将油倒在所有的器皿里，倒满了的放在一边。」","notes":[]},{"n":5,"t":"于是，妇人离开以利沙去了，关上门，自己和儿子在里面；儿子把器皿拿来，她就倒油。","notes":[]},{"n":6,"t":"器皿都满了，她对儿子说：「再给我拿器皿来。」儿子说：「再没有器皿了。」油就止住了。","notes":[]},{"n":7,"t":"妇人去告诉神人，神人说：「你去卖油还债，所剩的你和你儿子可以靠着度日。」","notes":[]},{"n":8,"t":"一日，以利沙走到书念，在那里有一个大户的妇人强留他吃饭。此后，以利沙每从那里经过就进去吃饭。","notes":[],"heads":["书念妇人接待以利沙"]},{"n":9,"t":"妇人对丈夫说：「我看出那常从我们这里经过的是圣洁的神人。","notes":[]},{"n":10,"t":"我们可以为他在墙上盖一间小楼，在其中安放床榻、桌子、椅子、灯台，他来到我们这里，就可以住在其间。」","notes":[]},{"n":11,"t":"一日，以利沙来到那里，就进了那楼躺卧。","notes":[]},{"n":12,"t":"以利沙吩咐仆人基哈西说：「你叫这书念妇人来。」他就把妇人叫了来，妇人站在以利沙面前。","notes":[]},{"n":13,"t":"以利沙吩咐仆人说：「你对她说：你既为我们费了许多心思，可以为你做什么呢？你向王或元帅有所求的没有？」她回答说：「我在我本乡安居无事。」","notes":[]},{"n":14,"t":"以利沙对仆人说：「究竟当为她做什么呢？」基哈西说：「她没有儿子，她丈夫也老了。」","notes":[]},{"n":15,"t":"以利沙说：「再叫她来。」于是叫了她来，她就站在门口。","notes":[]},{"n":16,"t":"以利沙说：「明年到这时候，你必抱一个儿子。」她说：「神人，我主啊，不要那样欺哄婢女。」","notes":[]},{"n":17,"t":"妇人果然怀孕，到了那时候，生了一个儿子，正如以利沙所说的。","notes":[]},{"n":18,"t":"孩子渐渐长大，一日到他父亲和收割的人那里，","notes":[]},{"n":19,"t":"他对父亲说：「我的头啊，我的头啊！」他父亲对仆人说：「把他抱到他母亲那里。」","notes":[]},{"n":20,"t":"仆人抱去，交给他母亲；孩子坐在母亲的膝上，到晌午就死了。","notes":[]},{"n":21,"t":"他母亲抱他上了楼，将他放在神人的床上，关上门出来，","notes":[]},{"n":22,"t":"呼叫她丈夫说：「你叫一个仆人给我牵一匹驴来，我要快快地去见神人，就回来。」","notes":[]},{"n":23,"t":"丈夫说：「今日不是月朔，也不是安息日，你为何要去见他呢？」妇人说：「平安无事。」","notes":[]},{"n":24,"t":"于是备上驴，对仆人说：「你快快赶着走，我若不吩咐你，就不要迟慢。」","notes":[]},{"n":25,"t":"妇人就往迦密山去见神人。神人远远地看见她，对仆人基哈西说：「看哪，书念的妇人来了！","notes":[]},{"n":26,"t":"你跑去迎接她，问她说：你平安吗？你丈夫平安吗？孩子平安吗？」她说：「平安。」","notes":[]},{"n":27,"t":"妇人上了山，到神人那里，就抱住神人的脚。基哈西前来要推开她，神人说：「由她吧！因为她心里愁苦，耶和华向我隐瞒，没有指示我。」","notes":[]},{"n":28,"t":"妇人说：「我何尝向我主求过儿子呢？我岂没有说过，不要欺哄我吗？」","notes":[]},{"n":29,"t":"以利沙吩咐基哈西说：「你束上腰，手拿我的杖前去；若遇见人，不要向他问安；人若向你问安，也不要回答；要把我的杖放在孩子脸上。」","notes":[]},{"n":30,"t":"孩子的母亲说：「我指着永生的耶和华，又敢在你面前起誓，我必不离开你。」于是以利沙起身，随着她去了。","notes":[]},{"n":31,"t":"基哈西先去，把杖放在孩子脸上，却没有声音，也没有动静。基哈西就迎着以利沙回来，告诉他说：「孩子还没有醒过来。」","notes":[]},{"n":32,"t":"以利沙来到，进了屋子，看见孩子死了，放在自己的床上。","notes":[]},{"n":33,"t":"他就关上门，只有自己和孩子在里面，他便祈祷耶和华，","notes":[]},{"n":34,"t":"上床伏在孩子身上，口对口，眼对眼，手对手；既伏在孩子身上，孩子的身体就渐渐温和了。","notes":[]},{"n":35,"t":"然后他下来，在屋里来往走了一趟，又上去伏在孩子身上，孩子打了七个喷嚏，就睁开眼睛了。","notes":[]},{"n":36,"t":"以利沙叫基哈西说：「你叫这书念妇人来」；于是叫了她来。以利沙说：「将你儿子抱起来。」","notes":[]},{"n":37,"t":"妇人就进来，在以利沙脚前俯伏于地，抱起她儿子出去了。","notes":[]},{"n":38,"t":"以利沙又来到吉甲，那地正有饥荒。先知门徒坐在他面前，他吩咐仆人说：「你将大锅放在火上，给先知门徒熬汤。」","notes":[],"heads":["两件神迹"]},{"n":39,"t":"有一个人去到田野掐菜，遇见一棵野瓜藤，就摘了一兜野瓜回来，切了搁在熬汤的锅中，因为他们不知道是什么东西；","notes":[]},{"n":40,"t":"倒出来给众人吃，吃的时候，都喊叫说：「神人哪，锅中有致死的毒物！」所以众人不能吃了。","notes":[]},{"n":41,"t":"以利沙说：「拿点面来」，就把面撒在锅中，说：「倒出来，给众人吃吧！」锅中就没有毒了。","notes":[]},{"n":42,"t":"有一个人从巴力·沙利沙来，带着初熟大麦做的饼二十个，并新穗子，装在口袋里送给神人。神人说：「把这些给众人吃。」","notes":[]},{"n":43,"t":"仆人说：「这一点岂可摆给一百人吃呢？」以利沙说：「你只管给众人吃吧！因为耶和华如此说，众人必吃了，还剩下。」","notes":[]},{"n":44,"t":"仆人就摆在众人面前，他们吃了，果然还剩下，正如耶和华所说的。","notes":[]}]},"5":{"heading":"乃缦得医治","verses":[{"n":1,"t":"亚兰王的元帅乃缦在他主人面前为尊为大，因耶和华曾借他使亚兰人得胜；他又是大能的勇士，只是长了大麻风。","notes":[]},{"n":2,"t":"先前亚兰人成群地出去，从以色列国掳了一个小女子，这女子就服事乃缦的妻。","notes":[]},{"n":3,"t":"她对主母说：「巴不得我主人去见撒马利亚的先知，必能治好他的大麻风。」","notes":[]},{"n":4,"t":"乃缦进去，告诉他主人说，以色列国的女子如此如此说。","notes":[]},{"n":5,"t":"亚兰王说：「你可以去，我也达信于以色列王。」于是乃缦带银子十他连得，金子六千舍客勒，衣裳十套，就去了；","notes":[]},{"n":6,"t":"且带信给以色列王，信上说：「我打发臣仆乃缦去见你，你接到这信，就要治好他的大麻风。」","notes":[]},{"n":7,"t":"以色列王看了信就撕裂衣服，说：「我岂是神，能使人死使人活呢？这人竟打发人来，叫我治好他的大麻风。你们看一看，这人何以寻隙攻击我呢？」","notes":[]},{"n":8,"t":"神人以利沙听见以色列王撕裂衣服，就打发人去见王，说：「你为什么撕了衣服呢？可使那人到我这里来，他就知道以色列中有先知了。」","notes":[]},{"n":9,"t":"于是，乃缦带着车马到了以利沙的家，站在门前。","notes":[]},{"n":10,"t":"以利沙打发一个使者，对乃缦说：「你去在约旦河中沐浴七回，你的肉就必复原，而得洁净。」","notes":[]},{"n":11,"t":"乃缦却发怒走了，说：「我想他必定出来见我，站着求告耶和华—他神的名，在患处以上摇手，治好这大麻风。","notes":[]},{"n":12,"t":"大马士革的河亚罢拿和法珥法岂不比以色列的一切水更好吗？我在那里沐浴不得洁净吗？」于是气忿忿地转身去了。","notes":[]},{"n":13,"t":"他的仆人进前来，对他说：「我父啊，先知若吩咐你做一件大事，你岂不做吗？何况说你去沐浴而得洁净呢？」","notes":[]},{"n":14,"t":"于是乃缦下去，照着神人的话，在约旦河里沐浴七回；他的肉复原，好像小孩子的肉，他就洁净了。","notes":[]},{"n":15,"t":"乃缦带着一切跟随他的人，回到神人那里，站在他面前，说：「如今我知道，除了以色列之外，普天下没有神。现在求你收点仆人的礼物。」","notes":[]},{"n":16,"t":"以利沙说：「我指着所事奉永生的耶和华起誓，我必不受。」乃缦再三地求他，他却不受。","notes":[]},{"n":17,"t":"乃缦说：「你若不肯受，请将两骡子驮的土赐给仆人。从今以后，仆人必不再将燔祭或平安祭献与别神，只献给耶和华。","notes":[]},{"n":18,"t":"惟有一件事，愿耶和华饶恕你仆人：我主人进临门庙叩拜的时候，我用手搀他在临门庙，我也屈身。我在临门庙屈身的这事，愿耶和华饶恕我。」","notes":[]},{"n":19,"t":"以利沙对他说：「你可以平平安安地回去！」乃缦就离开他去了；走了不远，","notes":[]},{"n":20,"t":"神人以利沙的仆人基哈西心里说：「我主人不愿从这亚兰人乃缦手里受他带来的礼物，我指着永生的耶和华起誓，我必跑去追上他，向他要些。」","notes":[]},{"n":21,"t":"于是基哈西追赶乃缦。乃缦看见有人追赶，就急忙下车迎着他，说：「都平安吗？」","notes":[]},{"n":22,"t":"说：「都平安。我主人打发我来说：『刚才有两个少年人，是先知门徒，从以法莲山地来见我，请你赐他们一他连得银子，两套衣裳。』」","notes":[]},{"n":23,"t":"乃缦说：「请受二他连得」；再三地请受，便将二他连得银子装在两个口袋里，又将两套衣裳交给两个仆人；他们就在基哈西前头抬着走。","notes":[]},{"n":24,"t":"到了山冈，基哈西从他们手中接过来，放在屋里，打发他们回去。","notes":[]},{"n":25,"t":"基哈西进去，站在他主人面前。以利沙问他说：「基哈西你从哪里来？」回答说：「仆人没有往哪里去。」","notes":[]},{"n":26,"t":"以利沙对他说：「那人下车转回迎你的时候，我的心岂没有去呢？这岂是受银子、衣裳、买橄榄园、葡萄园、牛羊、仆婢的时候呢？","notes":[]},{"n":27,"t":"因此，乃缦的大麻风必沾染你和你的后裔，直到永远。」基哈西从以利沙面前退出去，就长了大麻风，像雪那样白。","notes":[]}]},"6":{"heading":"找回斧子的头","verses":[{"n":1,"t":"先知门徒对以利沙说：「看哪，我们同你所住的地方过于窄小，","notes":[]},{"n":2,"t":"求你容我们往约旦河去，各人从那里取一根木料建造房屋居住。」他说：「你们去吧！」","notes":[]},{"n":3,"t":"有一人说：「求你与仆人同去。」回答说：「我可以去。」","notes":[]},{"n":4,"t":"于是以利沙与他们同去。到了约旦河，就砍伐树木。","notes":[]},{"n":5,"t":"有一人砍树的时候，斧头掉在水里，他就呼叫说：「哀哉！我主啊，这斧子是借的。」","notes":[]},{"n":6,"t":"神人问说：「掉在哪里了？」他将那地方指给以利沙看。以利沙砍了一根木头，抛在水里，斧头就漂上来了。","notes":[]},{"n":7,"t":"以利沙说：「拿起来吧！」那人就伸手拿起来了。","notes":[]},{"n":8,"t":"亚兰王与以色列人争战，和他的臣仆商议说：「我要在某处某处安营。」","notes":[],"heads":["亚兰军败于以色列人"]},{"n":9,"t":"神人打发人去见以色列王，说：「你要谨慎，不要从某处经过，因为亚兰人从那里下来了。」","notes":[]},{"n":10,"t":"以色列王差人去窥探神人所告诉所警戒他去的地方，就防备未受其害，不止一两次。","notes":[]},{"n":11,"t":"亚兰王因这事心里惊疑，召了臣仆来，对他们说：「我们这里有谁帮助以色列王，你们不指给我吗？」","notes":[]},{"n":12,"t":"有一个臣仆说：「我主，我王！无人帮助他，只有以色列中的先知以利沙，将王在卧房所说的话告诉以色列王了。」","notes":[]},{"n":13,"t":"王说：「你们去探他在哪里，我好打发人去捉拿他。」有人告诉王说：「他在多坍。」","notes":[]},{"n":14,"t":"王就打发车马和大军往那里去，夜间到了，围困那城。","notes":[]},{"n":15,"t":"神人的仆人清早起来出去，看见车马军兵围困了城。仆人对神人说：「哀哉！我主啊，我们怎样行才好呢？」","notes":[]},{"n":16,"t":"神人说：「不要惧怕！与我们同在的比与他们同在的更多。」","notes":[]},{"n":17,"t":"以利沙祷告说：「耶和华啊，求你开这少年人的眼目，使他能看见。」耶和华开他的眼目，他就看见满山有火车火马围绕以利沙。","notes":[]},{"n":18,"t":"敌人下到以利沙那里，以利沙祷告耶和华说：「求你使这些人的眼目昏迷。」耶和华就照以利沙的话，使他们的眼目昏迷。","notes":[]},{"n":19,"t":"以利沙对他们说：「这不是那道，也不是那城；你们跟我去，我必领你们到所寻找的人那里。」于是领他们到了撒马利亚。","notes":[]},{"n":20,"t":"他们进了撒马利亚，以利沙祷告说：「耶和华啊，求你开这些人的眼目，使他们能看见。」耶和华开他们的眼目，他们就看见了，不料，是在撒马利亚的城中。","notes":[]},{"n":21,"t":"以色列王见了他们，就问以利沙说：「我父啊，我可以击杀他们吗？」","notes":[]},{"n":22,"t":"回答说：「不可击杀他们！就是你用刀用弓掳来的，岂可击杀他们吗？当在他们面前设摆饮食，使他们吃喝回到他们的主人那里。」","notes":["或译：也不可击杀，何况这些人呢"]},{"n":23,"t":"王就为他们预备了许多食物；他们吃喝完了，打发他们回到他们主人那里。从此，亚兰军不再犯以色列境了。","notes":[]},{"n":24,"t":"此后，亚兰王便·哈达聚集他的全军，上来围困撒马利亚。","notes":[],"heads":["围困撒马利亚"]},{"n":25,"t":"于是撒马利亚被围困，有饥荒，甚至一个驴头值银八十舍客勒，二升鸽子粪值银五舍客勒。","notes":[]},{"n":26,"t":"一日，以色列王在城上经过，有一个妇人向他呼叫说：「我主，我王啊！求你帮助。」","notes":[]},{"n":27,"t":"王说：「耶和华不帮助你，我从何处帮助你？是从禾场，是从酒榨呢？」","notes":[]},{"n":28,"t":"王问妇人说：「你有什么苦处？」她回答说：「这妇人对我说：『将你的儿子取来，我们今日可以吃，明日可以吃我的儿子。』","notes":[]},{"n":29,"t":"我们就煮了我的儿子吃了。次日我对她说：『要将你的儿子取来，我们可以吃。』她却将她的儿子藏起来了。」","notes":[]},{"n":30,"t":"王听见妇人的话，就撕裂衣服；（王在城上经过）百姓看见王贴身穿着麻衣。","notes":[]},{"n":31,"t":"王说：「我今日若容沙法的儿子以利沙的头仍在他项上，愿神重重地降罚与我！」","notes":[]},{"n":32,"t":"那时，以利沙正坐在家中，长老也与他同坐。王打发一个伺候他的人去；他还没有到，以利沙对长老说：「你们看这凶手之子，打发人来斩我的头；你们看着使者来到，就关上门，用门将他推出去。在他后头不是有他主人脚步的响声吗？」","notes":[]},{"n":33,"t":"正说话的时候，使者来到，王也到了，说：「这灾祸是从耶和华那里来的，我何必再仰望耶和华呢？」","notes":[]}]},"7":{"heading":"亚兰军弃营逃命","verses":[{"n":1,"t":"以利沙说：「你们要听耶和华的话，耶和华如此说：明日约到这时候，在撒马利亚城门口，一细亚细面要卖银一舍客勒，二细亚大麦也要卖银一舍客勒。」","notes":[]},{"n":2,"t":"有一个搀扶王的军长对神人说：「即便耶和华使天开了窗户，也不能有这事。」以利沙说：「你必亲眼看见，却不得吃。」","notes":[]},{"n":3,"t":"在城门那里有四个长大麻风的人，他们彼此说：「我们为何坐在这里等死呢？","notes":[]},{"n":4,"t":"我们若说，进城去吧！城里有饥荒，必死在那里；若在这里坐着不动，也必是死。来吧，我们去投降亚兰人的军队，他们若留我们的活命，就活着；若杀我们，就死了吧！」","notes":[]},{"n":5,"t":"黄昏的时候，他们起来往亚兰人的营盘去；到了营边，不见一人在那里。","notes":[]},{"n":6,"t":"因为主使亚兰人的军队听见车马的声音，是大军的声音；他们就彼此说：「这必是以色列王贿买赫人的诸王和埃及人的诸王来攻击我们。」","notes":[]},{"n":7,"t":"所以，在黄昏的时候他们起来逃跑，撇下帐棚、马、驴，营盘照旧，只顾逃命。","notes":[]},{"n":8,"t":"那些长大麻风的到了营边，进了帐棚，吃了喝了，且从其中拿出金银和衣服来，去收藏了；回来又进了一座帐棚，从其中拿出财物来去收藏了。","notes":[]},{"n":9,"t":"那时，他们彼此说：「我们所做的不好！今日是有好信息的日子，我们竟不作声！若等到天亮，罪必临到我们。来吧，我们与王家报信去！」","notes":[]},{"n":10,"t":"他们就去叫守城门的，告诉他们说：「我们到了亚兰人的营，不见一人在那里，也无人声，只有拴着的马和驴，帐棚都照旧。」","notes":[]},{"n":11,"t":"守城门的叫了众守门的人来，他们就进去与王家报信。","notes":[]},{"n":12,"t":"王夜间起来，对臣仆说：「我告诉你们亚兰人向我们如何行。他们知道我们饥饿，所以离营，埋伏在田野，说：『以色列人出城的时候，我们就活捉他们，得以进城。』」","notes":[]},{"n":13,"t":"有一个臣仆对王说：「我们不如用城里剩下之马中的五匹马（马和城里剩下的以色列人都是一样，快要灭绝），打发人去窥探。」","notes":[]},{"n":14,"t":"于是取了两辆车和马，王差人去追寻亚兰军，说：「你们去窥探窥探。」","notes":[]},{"n":15,"t":"他们就追寻到约旦河，看见满道上都是亚兰人急跑时丢弃的衣服器具，使者就回来报告王。","notes":[]},{"n":16,"t":"众人就出去，掳掠亚兰人的营盘。于是一细亚细面卖银一舍客勒，二细亚大麦也卖银一舍客勒，正如耶和华所说的。","notes":[]},{"n":17,"t":"王派搀扶他的那军长在城门口弹压，众人在那里将他践踏，他就死了，正如神人在王下来见他的时候所说的。","notes":[]},{"n":18,"t":"神人曾对王说：「明日约到这时候，在撒马利亚城门口，二细亚大麦要卖银一舍客勒，一细亚细面也要卖银一舍客勒。」","notes":[]},{"n":19,"t":"那军长对神人说：「即便耶和华使天开了窗户，也不能有这事。」神人说：「你必亲眼看见，却不得吃。」","notes":[]},{"n":20,"t":"这话果然应验在他身上；因为众人在城门口将他践踏，他就死了。","notes":[]}]},"8":{"heading":"书念的妇人回原住地","verses":[{"n":1,"t":"以利沙曾对所救活之子的那妇人说：「你和你的全家要起身往你可住的地方去住，因为耶和华命饥荒降在这地七年。」","notes":[]},{"n":2,"t":"妇人就起身，照神人的话带着全家往非利士地去，住了七年。","notes":[]},{"n":3,"t":"七年完了，那妇人从非利士地回来，就出去为自己的房屋田地哀告王。","notes":[]},{"n":4,"t":"那时王正与神人的仆人基哈西说：「请你将以利沙所行的一切大事告诉我。」","notes":[]},{"n":5,"t":"基哈西告诉王以利沙如何使死人复活，恰巧以利沙所救活、她儿子的那妇人为自己的房屋田地来哀告王。基哈西说：「我主我王，这就是那妇人，这是她的儿子，就是以利沙所救活的。」","notes":[]},{"n":6,"t":"王问那妇人，她就把那事告诉王。于是王为她派一个太监，说：「凡属这妇人的都还给她，自从她离开本地直到今日，她田地的出产也都还给她。」","notes":[]},{"n":7,"t":"以利沙来到大马士革，亚兰王便·哈达正患病。有人告诉王说：「神人来到这里了。」","notes":[],"heads":["以利沙和便·哈达王"]},{"n":8,"t":"王就吩咐哈薛说：「你带着礼物去见神人，托他求问耶和华，我这病能好不能好？」","notes":[]},{"n":9,"t":"于是哈薛用四十个骆驼，驮着大马士革的各样美物为礼物，去见以利沙。到了他那里，站在他面前，说：「你儿子亚兰王便·哈达打发我来见你，他问说：『我这病能好不能好？』」","notes":[]},{"n":10,"t":"以利沙对哈薛说：「你回去告诉他说，这病必能好；但耶和华指示我，他必要死。」","notes":[]},{"n":11,"t":"神人定睛看着哈薛，甚至他惭愧。神人就哭了；","notes":[]},{"n":12,"t":"哈薛说：「我主为什么哭？」回答说：「因为我知道你必苦害以色列人，用火焚烧他们的保障，用刀杀死他们的壮丁，摔死他们的婴孩，剖开他们的孕妇。」","notes":[]},{"n":13,"t":"哈薛说：「你仆人算什么，不过是一条狗，焉能行这大事呢？」以利沙回答说：「耶和华指示我，你必作亚兰王。」","notes":[]},{"n":14,"t":"哈薛离开以利沙，回去见他的主人。主人问他说：「以利沙对你说什么？」回答说：「他告诉我你必能好。」","notes":[]},{"n":15,"t":"次日，哈薛拿被窝浸在水中，蒙住王的脸，王就死了。于是哈薛篡了他的位。","notes":[]},{"n":16,"t":"以色列王亚哈的儿子约兰第五年，犹大王约沙法还在位的时候，约沙法的儿子约兰登基作了犹大王。","notes":[],"heads":["犹大王约兰"]},{"n":17,"t":"约兰登基的时候年三十二岁，在耶路撒冷作王八年。","notes":[]},{"n":18,"t":"他行以色列诸王所行的，与亚哈家一样；因为他娶了亚哈的女儿为妻，行耶和华眼中看为恶的事。","notes":[]},{"n":19,"t":"耶和华却因他仆人大卫的缘故，仍不肯灭绝犹大，照他所应许大卫的话，永远赐灯光与他的子孙。","notes":[]},{"n":20,"t":"约兰年间，以东人背叛犹大，脱离他的权下，自己立王。","notes":[]},{"n":21,"t":"约兰率领所有的战车往撒益去，夜间起来，攻打围困他的以东人和车兵长；犹大兵就逃跑，各回各家去了。","notes":[]},{"n":22,"t":"这样，以东人背叛犹大，脱离他的权下，直到今日。那时立拿人也背叛了。","notes":[]},{"n":23,"t":"约兰其余的事，凡他所行的，都写在犹大列王记上。","notes":[]},{"n":24,"t":"约兰与他列祖同睡，葬在大卫城他列祖的坟地里。他儿子亚哈谢接续他作王。","notes":[]},{"n":25,"t":"以色列王亚哈的儿子约兰十二年，犹大王约兰的儿子亚哈谢登基。","notes":[],"heads":["犹大王亚哈谢"]},{"n":26,"t":"他登基的时候年二十二岁，在耶路撒冷作王一年。他母亲名叫亚她利雅，是以色列王暗利的孙女。","notes":[]},{"n":27,"t":"亚哈谢效法亚哈家行耶和华眼中看为恶的事，与亚哈家一样，因为他是亚哈家的女婿。","notes":[]},{"n":28,"t":"他与亚哈的儿子约兰同往基列的拉末去，与亚兰王哈薛争战。亚兰人打伤了约兰，","notes":[]},{"n":29,"t":"约兰王回到耶斯列，医治在拉末与亚兰王哈薛打仗的时候所受的伤。犹大王约兰的儿子亚哈谢因为亚哈的儿子约兰病了，就下到耶斯列看望他。","notes":[]}]},"9":{"heading":"耶户被膏立为以色列王","verses":[{"n":1,"t":"先知以利沙叫了一个先知门徒来，吩咐他说：「你束上腰，手拿这瓶膏油往基列的拉末去。","notes":[]},{"n":2,"t":"到了那里，要寻找宁示的孙子、约沙法的儿子耶户，使他从同僚中起来，带他进严密的屋子，","notes":[]},{"n":3,"t":"将瓶里的膏油倒在他头上，说：『耶和华如此说：我膏你作以色列王。』说完了，就开门逃跑，不要迟延。」","notes":[]},{"n":4,"t":"于是那少年先知往基列的拉末去了。","notes":[]},{"n":5,"t":"到了那里，看见众军长都坐着，就说：「将军哪，我有话对你说。」耶户说：「我们众人里，你要对哪一个说呢？」回答说：「将军哪，我要对你说。」","notes":[]},{"n":6,"t":"耶户就起来，进了屋子，少年人将膏油倒在他头上，对他说：「耶和华—以色列的神如此说：『我膏你作耶和华民以色列的王。","notes":[]},{"n":7,"t":"你要击杀你主人亚哈的全家，我好在耶洗别身上伸我仆人众先知和耶和华一切仆人流血的冤。","notes":[]},{"n":8,"t":"亚哈全家必都灭亡，凡属亚哈的男丁，无论是困住的、自由的，我必从以色列中剪除，","notes":[]},{"n":9,"t":"使亚哈的家像尼八儿子耶罗波安的家，又像亚希雅儿子巴沙的家。","notes":[]},{"n":10,"t":"耶洗别必在耶斯列田里被狗所吃，无人葬埋。』」说完了，少年人就开门逃跑了。","notes":[]},{"n":11,"t":"耶户出来，回到他主人的臣仆那里，有一人问他说：「平安吗？这狂妄的人来见你有什么事呢？」回答说：「你们认得那人，也知道他说什么。」","notes":[]},{"n":12,"t":"他们说：「这是假话，你据实地告诉我们。」回答说：「他如此如此对我说。他说：『耶和华如此说：我膏你作以色列王。』」","notes":[]},{"n":13,"t":"他们就急忙各将自己的衣服铺在上层台阶，使耶户坐在其上；他们吹角，说：「耶户作王了！」","notes":[]},{"n":14,"t":"这样，宁示的孙子、约沙法的儿子耶户背叛约兰。先是约兰和以色列众人因为亚兰王哈薛的缘故，把守基列的拉末；","notes":[],"heads":["以色列王约兰被杀"]},{"n":15,"t":"但约兰王回到耶斯列，医治与亚兰王哈薛打仗所受的伤。耶户说：「若合你们的意思，就不容人逃出城往耶斯列报信去。」","notes":[]},{"n":16,"t":"于是耶户坐车往耶斯列去，因为约兰病卧在那里。犹大王亚哈谢已经下去看望他。","notes":[]},{"n":17,"t":"有一个守望的人站在耶斯列的楼上，看见耶户带着一群人来，就说：「我看见一群人。」约兰说：「打发一个骑马的去迎接他们，问说：平安不平安？」","notes":[]},{"n":18,"t":"骑马的就去迎接耶户，说：「王问说，平安不平安？」耶户说：「平安不平安与你何干？你转在我后头吧！」守望的人又说：「使者到了他们那里，却不回来。」","notes":[]},{"n":19,"t":"王又打发一个骑马的去。这人到了他们那里，说：「王问说，平安不平安？」耶户说：「平安不平安与你何干？你转在我后头吧！」","notes":[]},{"n":20,"t":"守望的人又说：「他到了他们那里，也不回来；车赶得甚猛，像宁示的孙子耶户的赶法。」","notes":[]},{"n":21,"t":"约兰吩咐说：「套车！」人就给他套车。以色列王约兰和犹大王亚哈谢各坐自己的车出去迎接耶户，在耶斯列人拿伯的田那里遇见他。","notes":[]},{"n":22,"t":"约兰见耶户就说：「耶户啊，平安吗？」耶户说：「你母亲耶洗别的淫行邪术这样多，焉能平安呢？」","notes":[]},{"n":23,"t":"约兰就转车逃跑，对亚哈谢说：「亚哈谢啊，反了！」","notes":[]},{"n":24,"t":"耶户开满了弓，射中约兰的脊背，箭从心窝穿出，约兰就仆倒在车上。","notes":[]},{"n":25,"t":"耶户对他的军长毕甲说：「你把他抛在耶斯列人拿伯的田间。你当追想，你我一同坐车跟随他父亚哈的时候，耶和华对亚哈所说的预言，","notes":[]},{"n":26,"t":"说：『我昨日看见拿伯的血和他众子的血，我必在这块田上报应你。』这是耶和华说的，现在你要照着耶和华的话，把他抛在这田间。」","notes":[]},{"n":27,"t":"犹大王亚哈谢见这光景，就从园亭之路逃跑。耶户追赶他，说：「把这人也杀在车上。」到了靠近以伯莲姑珥的坡上击伤了他。他逃到米吉多，就死在那里。","notes":[],"heads":["犹大王亚哈谢被杀"]},{"n":28,"t":"他的臣仆用车将他的尸首送到耶路撒冷，葬在大卫城他自己的坟墓里，与他列祖同葬。","notes":[]},{"n":29,"t":"亚哈谢登基作犹大王的时候，是在亚哈的儿子约兰第十一年。","notes":[]},{"n":30,"t":"耶户到了耶斯列；耶洗别听见就擦粉、梳头，从窗户里往外观看。","notes":[],"heads":["耶洗别王后被杀"]},{"n":31,"t":"耶户进门的时候，耶洗别说：「杀主人的心利啊，平安吗？」","notes":[]},{"n":32,"t":"耶户抬头向窗户观看，说：「谁顺从我？」有两三个太监从窗户往外看他。","notes":[]},{"n":33,"t":"耶户说：「把她扔下来！」他们就把她扔下来。她的血溅在墙上和马上；于是把她践踏了。","notes":[]},{"n":34,"t":"耶户进去，吃了喝了，吩咐说：「你们把这被咒诅的妇人葬埋了，因为她是王的女儿。」","notes":[]},{"n":35,"t":"他们就去葬埋她，只寻得她的头骨和脚，并手掌。","notes":[]},{"n":36,"t":"他们回去告诉耶户，耶户说：「这正应验耶和华借他仆人提斯比人以利亚所说的话，说：『在耶斯列田间，狗必吃耶洗别的肉；","notes":[]},{"n":37,"t":"耶洗别的尸首必在耶斯列田间如同粪土，甚至人不能说这是耶洗别。』」","notes":[]}]},"10":{"heading":"耶户写信給耶斯列首领","verses":[{"n":1,"t":"亚哈有七十个儿子在撒马利亚。耶户写信送到撒马利亚，通知耶斯列的首领，就是长老和教养亚哈众子的人，说：","notes":[]},{"n":2,"t":"「你们那里既有你们主人的众子和车马、器械、坚固城，","notes":[]},{"n":3,"t":"接了这信，就可以在你们主人的众子中选择一个贤能合宜的，使他坐他父亲的位，你们也可以为你们主人的家争战。」","notes":[]},{"n":4,"t":"他们却甚惧怕，彼此说：「二王在他面前尚且站立不住，我们怎能站得住呢？」","notes":[]},{"n":5,"t":"家宰、邑宰，和长老，并教养众子的人，打发人去见耶户，说：「我们是你的仆人，凡你所吩咐我们的都必遵行，我们不立谁作王，你看怎样好就怎样行。」","notes":[]},{"n":6,"t":"耶户又给他们写信说：「你们若归顺我，听从我的话，明日这时候，要将你们主人众子的首级带到耶斯列来见我。」那时王的儿子七十人都住在教养他们那城中的尊贵人家里。","notes":[],"heads":["亚哈众子被杀"]},{"n":7,"t":"信一到，他们就把王的七十个儿子杀了，将首级装在筐里，送到在耶斯列的耶户那里。","notes":[]},{"n":8,"t":"有使者来告诉耶户说：「他们将王众子的首级送来了。」耶户说：「将首级在城门口堆作两堆，搁到明日。」","notes":[]},{"n":9,"t":"次日早晨，耶户出来，站着对众民说：「你们都是公义的，我背叛我主人，将他杀了；这些人却是谁杀的呢？","notes":[]},{"n":10,"t":"由此可知，耶和华指着亚哈家所说的话一句没有落空，因为耶和华借他仆人以利亚所说的话都成就了。」","notes":[]},{"n":11,"t":"凡亚哈家在耶斯列所剩下的人和他的大臣、密友、祭司，耶户尽都杀了，没有留下一个。","notes":[]},{"n":12,"t":"耶户起身往撒马利亚去。在路上、牧人剪羊毛之处，","notes":[],"heads":["亚哈谢的兄弟被杀"]},{"n":13,"t":"遇见犹大王亚哈谢的弟兄，问他们说：「你们是谁？」回答说：「我们是亚哈谢的弟兄，现在下去要问王和太后的众子安。」","notes":[]},{"n":14,"t":"耶户吩咐说：「活捉他们！」跟从的人就活捉了他们，将他们杀在剪羊毛之处的坑边，共四十二人，没有留下一个。","notes":[]},{"n":15,"t":"耶户从那里前行，恰遇利甲的儿子约拿达来迎接他，耶户问他安，对他说：「你诚心待我像我诚心待你吗？」约拿达回答说：「是。」耶户说：「若是这样，你向我伸手」，他就伸手；耶户拉他上车。","notes":[],"heads":["亚哈家剩下的人被杀"]},{"n":16,"t":"耶户说：「你和我同去，看我为耶和华怎样热心」；于是请他坐在车上，","notes":[]},{"n":17,"t":"到了撒马利亚，就把撒马利亚的亚哈家剩下的人都杀了，直到灭尽，正如耶和华对以利亚所说的。","notes":[]},{"n":18,"t":"耶户招聚众民，对他们说：「亚哈事奉巴力还冷淡，耶户却更热心。","notes":[],"heads":["拜巴力的人被杀"]},{"n":19,"t":"现在我要给巴力献大祭。应当叫巴力的众先知和一切拜巴力的人，并巴力的众祭司，都到我这里来，不可缺少一个；凡不来的必不得活。」耶户这样行，是用诡计要杀尽拜巴力的人。","notes":[]},{"n":20,"t":"耶户说：「要为巴力宣告严肃会！」于是宣告了。","notes":[]},{"n":21,"t":"耶户差人走遍以色列地；凡拜巴力的人都来齐了，没有一个不来的。他们进了巴力庙，巴力庙中从前边直到后边都满了人。","notes":[]},{"n":22,"t":"耶户吩咐掌管礼服的人说：「拿出礼服来，给一切拜巴力的人穿。」他就拿出礼服来给了他们。","notes":[]},{"n":23,"t":"耶户和利甲的儿子约拿达进了巴力庙，对拜巴力的人说：「你们察看察看，在你们这里不可有耶和华的仆人，只可容留拜巴力的人。」","notes":[]},{"n":24,"t":"耶户和约拿达进去，献平安祭和燔祭。耶户先安派八十人在庙外，吩咐说：「我将这些人交在你们手中，若有一人脱逃，谁放的必叫他偿命！」","notes":[]},{"n":25,"t":"耶户献完了燔祭，就出来吩咐护卫兵和众军长说：「你们进去杀他们，不容一人出来！」护卫兵和军长就用刀杀他们，将尸首抛出去，便到巴力庙的城去了，","notes":[]},{"n":26,"t":"将巴力庙中的柱像都拿出来烧了；","notes":[]},{"n":27,"t":"毁坏了巴力柱像，拆毁了巴力庙作为厕所，直到今日。","notes":[]},{"n":28,"t":"这样，耶户在以色列中灭了巴力。","notes":[]},{"n":29,"t":"只是耶户不离开尼八的儿子耶罗波安使以色列人陷在罪里的那罪，就是拜伯特利和但的金牛犊。","notes":[]},{"n":30,"t":"耶和华对耶户说：「因你办好我眼中看为正的事，照我的心意待亚哈家，你的子孙必接续你坐以色列的国位，直到四代。」","notes":[]},{"n":31,"t":"只是耶户不尽心遵守耶和华—以色列神的律法，不离开耶罗波安使以色列人陷在罪里的那罪。","notes":[]},{"n":32,"t":"在那些日子，耶和华才割裂以色列国，使哈薛攻击以色列的境界，","notes":[],"heads":["耶户去世"]},{"n":33,"t":"乃是约旦河东、基列全地，从靠近亚嫩谷边的亚罗珥起，就是基列和巴珊的迦得人、吕便人、玛拿西人之地。","notes":[]},{"n":34,"t":"耶户其余的事，凡他所行的和他的勇力都写在以色列诸王记上。","notes":[]},{"n":35,"t":"耶户与他列祖同睡，葬在撒马利亚；他儿子约哈斯接续他作王。","notes":[]},{"n":36,"t":"耶户在撒马利亚作以色列王二十八年。","notes":[]}]},"11":{"heading":"犹大的王后亚她利雅","verses":[{"n":1,"t":"亚哈谢的母亲亚她利雅见她儿子死了，就起来剿灭王室。","notes":[]},{"n":2,"t":"但约兰王的女儿，亚哈谢的妹子约示巴，将亚哈谢的儿子约阿施从那被杀的王子中偷出来，把他和他的乳母都藏在卧房里，躲避亚她利雅，免得被杀。","notes":[]},{"n":3,"t":"约阿施和他的乳母藏在耶和华的殿里六年；亚她利雅篡了国位。","notes":[]},{"n":4,"t":"第七年，耶何耶大打发人叫迦利人和护卫兵的众百夫长来，领他们进了耶和华的殿，与他们立约，使他们在耶和华殿里起誓，又将王的儿子指给他们看，","notes":["或译：亲兵"]},{"n":5,"t":"吩咐他们说：「你们当这样行：凡安息日进班的三分之一要看守王宫，","notes":[]},{"n":6,"t":"三分之一要在苏珥门，三分之一要在护卫兵院的后门。这样把守王宫，拦阻闲人。","notes":[]},{"n":7,"t":"你们安息日所有出班的三分之二要在耶和华的殿里护卫王；","notes":[]},{"n":8,"t":"各人手拿兵器，四围护卫王。凡擅入你们班次的必当治死，王出入的时候，你们当跟随他。」","notes":[]},{"n":9,"t":"众百夫长就照着祭司耶何耶大一切所吩咐的去行，各带所管安息日进班出班的人来见祭司耶何耶大。","notes":[]},{"n":10,"t":"祭司便将耶和华殿里所藏大卫王的枪和盾牌交给百夫长。","notes":[]},{"n":11,"t":"护卫兵手中各拿兵器，在坛和殿那里，从殿右直到殿左，站在王子的四围。","notes":[]},{"n":12,"t":"祭司领王子出来，给他戴上冠冕，将律法书交给他，膏他作王；众人就拍掌说：「愿王万岁！」","notes":[]},{"n":13,"t":"亚她利雅听见护卫兵和民的声音，就到民那里，进耶和华的殿，","notes":[]},{"n":14,"t":"看见王照例站在柱旁，百夫长和吹号的人侍立在王左右，国中的众民欢乐吹号；亚她利雅就撕裂衣服，喊叫说：「反了！反了！」","notes":[]},{"n":15,"t":"祭司耶何耶大吩咐管辖军兵的百夫长说：「将她赶出班外，凡跟随她的必用刀杀死！」因为祭司说「不可在耶和华殿里杀她」，","notes":[]},{"n":16,"t":"众兵就闪开让她去；她从马路上王宫去，便在那里被杀。","notes":[]},{"n":17,"t":"耶何耶大使王和民与耶和华立约，作耶和华的民；又使王与民立约。","notes":[],"heads":["耶何耶大的改革"]},{"n":18,"t":"于是国民都到巴力庙，拆毁了庙，打碎坛和像，又在坛前将巴力的祭司玛坦杀了。祭司耶何耶大派官看守耶和华的殿，","notes":[]},{"n":19,"t":"又率领百夫长和迦利人与护卫兵，以及国中的众民，请王从耶和华殿下来，由护卫兵的门进入王宫，他就坐了王位。","notes":["或译：亲兵"]},{"n":20,"t":"国民都欢乐，合城都安静。众人已将亚她利雅在王宫那里用刀杀了。","notes":[]},{"n":21,"t":"约阿施登基的时候年方七岁。","notes":[]}]},"12":{"heading":"犹大王约阿施","verses":[{"n":1,"t":"耶户第七年，约阿施登基，在耶路撒冷作王四十年。他母亲名叫西比亚，是别是巴人。","notes":[]},{"n":2,"t":"约阿施在祭司耶何耶大教训他的时候，就行耶和华眼中看为正的事；","notes":[]},{"n":3,"t":"只是邱坛还没有废去，百姓仍在那里献祭烧香。","notes":[]},{"n":4,"t":"约阿施对众祭司说：「凡奉到耶和华殿分别为圣之物所值通用的银子，或各人当纳的身价，或乐意奉到耶和华殿的银子，","notes":[]},{"n":5,"t":"你们当从所认识的人收了来，修理殿的一切破坏之处。」","notes":[]},{"n":6,"t":"无奈到了约阿施王二十三年，祭司仍未修理殿的破坏之处。","notes":[]},{"n":7,"t":"所以约阿施王召了大祭司耶何耶大和众祭司来，对他们说：「你们怎么不修理殿的破坏之处呢？从今以后，你们不要从所认识的人再收银子，要将所收的交出来，修理殿的破坏之处。」","notes":[]},{"n":8,"t":"众祭司答应不再收百姓的银子，也不修理殿的破坏之处。","notes":[]},{"n":9,"t":"祭司耶何耶大取了一个柜子，在柜盖上钻了一个窟窿，放于坛旁，在进耶和华殿的右边；守门的祭司将奉到耶和华殿的一切银子投在柜里。","notes":[]},{"n":10,"t":"他们见柜里的银子多了，便叫王的书记和大祭司上来，将耶和华殿里的银子数算包起来。","notes":[]},{"n":11,"t":"把所平的银子交给督工的，就是耶和华殿里办事的人；他们把银子转交修理耶和华殿的木匠和工人，","notes":[]},{"n":12,"t":"并瓦匠、石匠，又买木料和凿成的石头，修理耶和华殿的破坏之处，以及修理殿的各样使用。","notes":[]},{"n":13,"t":"但那奉到耶和华殿的银子，没有用以做耶和华殿里的银杯、蜡剪、碗、号，和别样的金银器皿，","notes":[]},{"n":14,"t":"乃将那银子交给督工的人修理耶和华的殿；","notes":[]},{"n":15,"t":"且将银子交给办事的人转交做工的人，不与他们算账，因为他们办事诚实。","notes":[]},{"n":16,"t":"惟有赎愆祭、赎罪祭的银子没有奉到耶和华的殿，都归祭司。","notes":[]},{"n":17,"t":"那时，亚兰王哈薛上来攻打迦 特，攻取了，就定意上来攻打耶路撒冷。","notes":[]},{"n":18,"t":"犹大王约阿施将他列祖犹大王约沙法、约兰、亚哈谢所分别为圣的物和自己所分别为圣的物，并耶和华殿与王宫府库里所有的金子都送给亚兰王哈薛；哈薛就不上耶路撒冷来了。","notes":[]},{"n":19,"t":"约阿施其余的事，凡他所行的都写在犹大列王记上。","notes":[]},{"n":20,"t":"约阿施的臣仆起来背叛，在下悉拉的米罗宫那里将他杀了。","notes":[]},{"n":21,"t":"杀他的那臣仆就是示米押的儿子约撒甲和朔默的儿子约萨拔。众人将他葬在大卫城他列祖的坟地里。他儿子亚玛谢接续他作王。","notes":[]}]},"13":{"heading":"以色列王约哈斯","verses":[{"n":1,"t":"犹大王亚哈谢的儿子约阿施二十三年，耶户的儿子约哈斯在撒马利亚登基作以色列王十七年。","notes":[]},{"n":2,"t":"约哈斯行耶和华眼中看为恶的事，效法尼八的儿子耶罗波安使以色列人陷在罪里的那罪，总不离开。","notes":[]},{"n":3,"t":"于是，耶和华的怒气向以色列人发作，将他们屡次交在亚兰王哈薛和他儿子便哈达的手里。","notes":[]},{"n":4,"t":"约哈斯恳求耶和华，耶和华就应允他，因为见以色列人所受亚兰王的欺压。","notes":[]},{"n":5,"t":"耶和华赐给以色列人一位拯救者，使他们脱离亚兰人的手；于是以色列人仍旧安居在家里。","notes":[]},{"n":6,"t":"然而，他们不离开耶罗波安家使以色列人陷在罪里的那罪，仍然去行，并且在撒马利亚留下亚舍拉。","notes":[]},{"n":7,"t":"亚兰王灭绝约哈斯的民，践踏他们如禾场上的尘沙，只给约哈斯留下五十马兵，十辆战车，一万步兵。","notes":[]},{"n":8,"t":"约哈斯其余的事，凡他所行的和他的勇力都写在以色列诸王记上。","notes":[]},{"n":9,"t":"约哈斯与他列祖同睡，葬在撒马利亚。他儿子约阿施接续他作王。","notes":[]},{"n":10,"t":"犹大王约阿施三十七年，约哈斯的儿子约阿施在撒马利亚登基作以色列王十六年。","notes":[],"heads":["以色列王约阿施"]},{"n":11,"t":"他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列人陷在罪里的一切罪，仍然去行。","notes":[]},{"n":12,"t":"约阿施其余的事，凡他所行的和他与犹大王亚玛谢争战的勇力，都写在以色列诸王记上。","notes":[]},{"n":13,"t":"约阿施与他列祖同睡，耶罗波安坐了他的位。约阿施与以色列诸王一同葬在撒马利亚。","notes":[]},{"n":14,"t":"以利沙得了必死的病，以色列王约阿施下来看他，伏在他脸上哭泣，说：「我父啊！我父啊！以色列的战车马兵啊！」","notes":[],"heads":["以利沙去世"]},{"n":15,"t":"以利沙对他说：「你取弓箭来。」王就取了弓箭来；","notes":[]},{"n":16,"t":"又对以色列王说：「你用手拿弓。」王就用手拿弓。以利沙按手在王的手上，","notes":[]},{"n":17,"t":"说：「你开朝东的窗户。」他就开了。以利沙说：「射箭吧！」他就射箭。以利沙说：「这是耶和华的得胜箭，就是战胜亚兰人的箭；因为你必在亚弗攻打亚兰人，直到灭尽他们。」","notes":[]},{"n":18,"t":"以利沙又说：「取几枝箭来。」他就取了来。以利沙说：「打地吧！」他打了三次，便止住了。","notes":[]},{"n":19,"t":"神人向他发怒，说：「应当击打五六次，就能攻打亚兰人直到灭尽；现在只能打败亚兰人三次。」","notes":[]},{"n":20,"t":"以利沙死了，人将他葬埋。到了新年，有一群摩押人犯境，","notes":[]},{"n":21,"t":"有人正葬死人，忽然看见一群人，就把死人抛在以利沙的坟墓里，一碰着以利沙的骸骨，死人就复活，站起来了。","notes":[]},{"n":22,"t":"约哈斯年间，亚兰王哈薛屡次欺压以色列人。","notes":[],"heads":["以色列与亚兰争战"]},{"n":23,"t":"耶和华却因与亚伯拉罕、以撒、雅各所立的约，仍施恩给以色列人，怜恤他们，眷顾他们，不肯灭尽他们，尚未赶逐他们离开自己面前。","notes":[]},{"n":24,"t":"亚兰王哈薛死了，他儿子便·哈达接续他作王。","notes":[]},{"n":25,"t":"从前哈薛和约阿施的父亲约哈斯争战，攻取了些城邑，现在约哈斯的儿子约阿施三次打败哈薛的儿子便哈达，就收回了以色列的城邑。","notes":[]}]},"14":{"heading":"犹大王亚玛谢","verses":[{"n":1,"t":"以色列王约哈斯的儿子约阿施第二年，犹大王约阿施的儿子亚玛谢登基。","notes":[]},{"n":2,"t":"他登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫约耶但，是耶路撒冷人。","notes":[]},{"n":3,"t":"亚玛谢行耶和华眼中看为正的事，但不如他祖大卫，乃效法他父约阿施一切所行的；","notes":[]},{"n":4,"t":"只是邱坛还没有废去，百姓仍在那里献祭烧香。","notes":[]},{"n":5,"t":"国一坚定，就把杀他父王的臣仆杀了，","notes":[]},{"n":6,"t":"却没有治死杀王之人的儿子，是照摩西律法书上耶和华所吩咐的说：「不可因子杀父，也不可因父杀子，各人要为本身的罪而死。」","notes":[]},{"n":7,"t":"亚玛谢在盐谷杀了以东人一万，又攻取了西拉，改名叫约帖，直到今日。","notes":[]},{"n":8,"t":"那时，亚玛谢差遣使者去见耶户的孙子约哈斯的儿子以色列王约阿 施，说：「你来，我们二人相见于战场。」","notes":[]},{"n":9,"t":"以色列王约阿施差遣使者去见犹大王亚玛谢，说：「黎巴嫩的蒺藜差遣使者去见黎巴嫩的香柏树，说：将你的女儿给我儿子为妻。后来黎巴嫩有一只野兽经过，把蒺藜践踏了。","notes":[]},{"n":10,"t":"你打败了以东人就心高气傲，你以此为荣耀，在家里安居就罢了，为何要惹祸，使自己和犹大国一同败亡呢？」","notes":[]},{"n":11,"t":"亚玛谢却不肯听这话。于是以色列王约阿施上来，在犹大的伯·示麦与犹大王亚玛谢相见于战场。","notes":[]},{"n":12,"t":"犹大人败在以色列人面前，各自逃回家里去了。","notes":[]},{"n":13,"t":"以色列王约阿施在伯·示麦擒住亚哈谢的孙子、约阿施的儿子犹大王亚玛谢，就来到耶路撒冷，拆毁耶路撒冷的城墙，从以法莲门直到角门共四百肘，","notes":[]},{"n":14,"t":"又将耶和华殿里与王宫府库里所有的金银和器皿都拿了去，并带人去为质，就回撒马利亚去了。","notes":[]},{"n":15,"t":"约阿施其余所行的事和他的勇力，并与犹大王亚玛谢争战的事，都写在以色列诸王记上。","notes":[]},{"n":16,"t":"约阿施与他列祖同睡，葬在撒马利亚，以色列诸王的坟地里。他儿子耶罗波安接续他作王。","notes":[]},{"n":17,"t":"以色列王约哈斯的儿子约阿施死后，犹大王约阿施的儿子亚玛谢又活了十五年。","notes":[],"heads":["犹大王亚玛谢去世"]},{"n":18,"t":"亚玛谢其余的事都写在犹大列王记上。","notes":[]},{"n":19,"t":"耶路撒冷有人背叛亚玛谢，他就逃到拉吉；叛党却打发人到拉吉将他杀了。","notes":[]},{"n":20,"t":"人就用马将他的尸首驮到耶路撒冷，葬在大卫城他列祖的坟地里。","notes":[]},{"n":21,"t":"犹大众民立亚玛谢的儿子亚撒利雅接续他父作王，那时他年十六岁。","notes":["又名乌西雅"]},{"n":22,"t":"亚玛谢与他列祖同睡之后，亚撒利雅收回以拉他仍归犹大，又重新修理。","notes":[]},{"n":23,"t":"犹大王约阿施的儿子亚玛谢十五年，以色列王约阿施的儿子耶罗波安在撒马利亚登基，作王四十一年。","notes":[],"heads":["以色列王耶罗波安二世"]},{"n":24,"t":"他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列人陷在罪里的一切罪。","notes":[]},{"n":25,"t":"他收回以色列边界之地，从哈马口直到亚拉巴海，正如耶和华—以色列的神借他仆人迦特希弗人亚米太的儿子先知约拿所说的。","notes":[]},{"n":26,"t":"因为耶和华看见以色列人甚是艰苦，无论困住的、自由的都没有了，也无人帮助以色列人。","notes":[]},{"n":27,"t":"耶和华并没有说要将以色列的名从天下涂抹，乃借约阿施的儿子耶罗波安拯救他们。","notes":[]},{"n":28,"t":"耶罗波安其余的事，凡他所行的和他的勇力，他怎样争战，怎样收回大马士革和先前属犹大的哈马归以色列，都写在以色列诸王记上。","notes":[]},{"n":29,"t":"耶罗波安与他列祖以色列诸王同睡。他儿子撒迦利雅接续他作王。","notes":[]}]},"15":{"heading":"犹大王亚撒利雅","verses":[{"n":1,"t":"以色列王耶罗波安二十七年，犹大王亚玛谢的儿子亚撒利雅登基，","notes":[]},{"n":2,"t":"他登基的时候年十六岁，在耶路撒冷作王五十二年。他母亲名叫耶可利雅，是耶路撒冷人。","notes":[]},{"n":3,"t":"亚撒利雅行耶和华眼中看为正的事，效法他父亲亚玛谢一切所行的；","notes":[]},{"n":4,"t":"只是邱坛还没有废去，百姓仍在那里献祭烧香。","notes":[]},{"n":5,"t":"耶和华降灾与王，使他长大麻风，直到死日，他就住在别的宫里。他的儿子约坦管理家事，治理国民。","notes":[]},{"n":6,"t":"亚撒利雅其余的事，凡他所行的都写在犹大列王记上。","notes":[]},{"n":7,"t":"亚撒利雅与他列祖同睡，葬在大卫城他列祖的坟地里。他儿子约坦接续他作王。","notes":[]},{"n":8,"t":"犹大王亚撒利雅三十八年，耶罗波安的儿子撒迦利雅在撒马利亚作以色列王六个月。","notes":[],"heads":["以色列王撒迦利雅"]},{"n":9,"t":"他行耶和华眼中看为恶的事，效法他列祖所行的，不离开尼八的儿子耶罗波安使以色列人陷在罪里的那罪。","notes":[]},{"n":10,"t":"雅比的儿子沙龙背叛他，在百姓面前击杀他，篡了他的位。","notes":[]},{"n":11,"t":"撒迦利雅其余的事都写在以色列诸王记上。","notes":[]},{"n":12,"t":"这是从前耶和华应许耶户说：「你的子孙必坐以色列的国位直到四代。」这话果然应验了。","notes":[]},{"n":13,"t":"犹大王乌西雅三十九年，雅比的儿子沙龙登基在撒马利亚作王一个月。","notes":["就是亚撒利雅"],"heads":["以色列王沙龙"]},{"n":14,"t":"迦底的儿子米拿现从得撒上撒马利亚，杀了雅比的儿子沙龙，篡了他的位。","notes":[]},{"n":15,"t":"沙龙其余的事和他背叛的情形都写在以色列诸王记上。","notes":[]},{"n":16,"t":"那时米拿现从得撒起攻打提斐萨和其四境，击杀城中一切的人，剖开其中所有的孕妇，都因他们没有给他开城。","notes":[]},{"n":17,"t":"犹大王亚撒利雅三十九年，迦底的儿子米拿现登基，在撒马利亚作以色列王十年。","notes":[],"heads":["以色列王米拿现"]},{"n":18,"t":"他行耶和华眼中看为恶的事，终身不离开尼八的儿子耶罗波安使以色列人陷在罪里的那罪。","notes":[]},{"n":19,"t":"亚述王普勒来攻击以色列国，米拿现给他一千他连得银子，请普勒帮助他坚定国位。","notes":[]},{"n":20,"t":"米拿现向以色列一切大富户索要银子，使他们各出五十舍客勒，就给了亚述王。于是亚述王回去，不在国中停留。","notes":[]},{"n":21,"t":"米拿现其余的事，凡他所行的都写在以色列诸王记上。","notes":[]},{"n":22,"t":"米拿现与他列祖同睡。他儿子比加辖接续他作王。","notes":[]},{"n":23,"t":"犹大王亚撒利雅五十年，米拿现的儿子比加辖在撒马利亚登基作以色列王二年。","notes":[],"heads":["以色列王比加辖"]},{"n":24,"t":"他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列人陷在罪里的那罪。","notes":[]},{"n":25,"t":"比加辖的将军、利玛利的儿子比加背叛他，在撒马利亚王宫里的卫所杀了他。亚珥歌伯和亚利耶并基列的五十人帮助比加；比加击杀他，篡了他的位。","notes":[]},{"n":26,"t":"比加辖其余的事，凡他所行的都写在以色列诸王记上。","notes":[]},{"n":27,"t":"犹大王亚撒利雅五十二年，利玛利的儿子比加在撒马利亚登基作以色列王二十年。","notes":[],"heads":["以色列王比加"]},{"n":28,"t":"他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列人陷在罪里的那罪。","notes":[]},{"n":29,"t":"以色列王比加年间，亚述王提革拉·毗列色来夺了以云、亚伯·伯·玛迦、亚挪、基低斯、夏琐、基列、加利利，和拿弗他利全地，将这些地方的居民都掳到亚述去了。","notes":[]},{"n":30,"t":"乌西雅的儿子约坦二十年，以拉的儿子何细亚背叛利玛利的儿子比加，击杀他，篡了他的位。","notes":[]},{"n":31,"t":"比加其余的事，凡他所行的都写在以色列诸王记上。","notes":[]},{"n":32,"t":"以色列王利玛利的儿子比加第二年，犹大王乌西雅的儿子约坦登基。","notes":[],"heads":["犹大王约坦"]},{"n":33,"t":"他登基的时候年二十五岁，在耶路撒冷作王十六年。他母亲名叫耶路沙，是撒督的女儿。","notes":[]},{"n":34,"t":"约坦行耶和华眼中看为正的事，效法他父亲乌西雅一切所行的；","notes":[]},{"n":35,"t":"只是邱坛还没有废去，百姓仍在那里献祭烧香。约坦建立耶和华殿的上门。","notes":[]},{"n":36,"t":"约坦其余的事，凡他所行的都写在犹大列王记上。","notes":[]},{"n":37,"t":"在那些日子，耶和华才使亚兰王利汛和利玛利的儿子比加去攻击犹大。","notes":[]},{"n":38,"t":"约坦与他列祖同睡，葬在他祖大卫城他列祖的坟地里。他儿子亚哈斯接续他作王。","notes":[]}]},"16":{"heading":"犹大王亚哈斯","verses":[{"n":1,"t":"利玛利的儿子比加十七年，犹大王约坦的儿子亚哈斯登基。","notes":[]},{"n":2,"t":"他登基的时候年二十岁，在耶路撒冷作王十六年；不像他祖大卫行耶和华—他神眼中看为正的事，","notes":[]},{"n":3,"t":"却效法以色列诸王所行的，又照着耶和华从以色列人面前赶出的外邦人所行可憎的事，使他的儿子经火，","notes":[]},{"n":4,"t":"并在邱坛上、山冈上、各青翠树下献祭烧香。","notes":[]},{"n":5,"t":"亚兰王利汛和以色列王利玛利的儿子比加上来攻打耶路撒冷，围困亚哈斯，却不能胜他。","notes":[]},{"n":6,"t":"当时亚兰王利汛收回以拉他归与亚兰，将犹大人从以拉他赶出去。亚兰人就来到以拉他，住在那里，直到今日。","notes":["有译以东人的"]},{"n":7,"t":"亚哈斯差遣使者去见亚述王提革拉·毗列色，说：「我是你的仆人、你的儿子。现在亚兰王和以色列王攻击我，求你来救我脱离他们的手。」","notes":[]},{"n":8,"t":"亚哈斯将耶和华殿里和王宫府库里所有的金银都送给亚述王为礼物。","notes":[]},{"n":9,"t":"亚述王应允了他，就上去攻打大马士革，将城攻取，杀了利汛，把居民掳到吉珥。","notes":[]},{"n":10,"t":"亚哈斯王上大马士革去迎接亚述王提革拉·毗列色，在大马士革看见一座坛，就照坛的规模样式作法画了图样，送到祭司乌利亚那里。","notes":[]},{"n":11,"t":"祭司乌利亚照着亚哈斯王从大马士革送来的图样，在亚哈斯王没有从大马士革回来之先，建筑一座坛。","notes":[]},{"n":12,"t":"王从大马士革回来看见坛，就近前来，在坛上献祭；","notes":[]},{"n":13,"t":"烧燔祭、素祭、浇奠祭，将平安祭牲的血洒在坛上，","notes":[]},{"n":14,"t":"又将耶和华面前的铜坛从耶和华殿和新坛的中间搬到新坛的北边。","notes":[]},{"n":15,"t":"亚哈斯王吩咐祭司乌利亚说：「早晨的燔祭、晚上的素祭，王的燔祭、素祭，国内众民的燔祭、素祭、奠祭都要烧在大坛上。燔祭牲和平安祭牲的血也要洒在这坛上，只是铜坛我要用以求问耶和华。」","notes":[]},{"n":16,"t":"祭司乌利亚就照着亚哈斯王所吩咐的行了。","notes":[]},{"n":17,"t":"亚哈斯王打掉盆座四面镶着的心子，把盆从座上挪下来，又将铜海从驮海的铜牛上搬下来，放在铺石地；","notes":[]},{"n":18,"t":"又因亚述王的缘故，将耶和华殿为安息日所盖的廊子和王从外入殿的廊子挪移，围绕耶和华的殿。","notes":[]},{"n":19,"t":"亚哈斯其余所行的事都写在犹大列王记上。","notes":[]},{"n":20,"t":"亚哈斯与他列祖同睡，葬在大卫城他列祖的坟地里。他儿子希西家接续他作王。","notes":[]}]},"17":{"heading":"以色列王何细亚","verses":[{"n":1,"t":"犹大王亚哈斯十二年，以拉的儿子何细亚在撒马利亚登基作以色列王九年。","notes":[]},{"n":2,"t":"他行耶和华眼中看为恶的事，只是不像在他以前的以色列诸王。","notes":[]},{"n":3,"t":"亚述王撒缦以色上来攻击何细亚，何细亚就服事他，给他进贡。","notes":[]},{"n":4,"t":"何细亚背叛，差人去见埃及王梭，不照往年所行的与亚述王进贡。亚述王知道了，就把他锁禁，囚在监里。","notes":[]},{"n":5,"t":"亚述王上来攻击以色列遍地，上到撒马利亚，围困三年。","notes":[]},{"n":6,"t":"何细亚第九年亚述王攻取了撒马利亚，将以色列人掳到亚述，把他们安置在哈腊与歌散的哈博河边，并米底亚人的城邑。","notes":[]},{"n":7,"t":"这是因以色列人得罪那领他们出埃及地、脱离埃及王法老手的耶和华—他们的神，去敬畏别神，","notes":[]},{"n":8,"t":"随从耶和华在他们面前所赶出外邦人的风俗和以色列诸王所立的条规。","notes":[]},{"n":9,"t":"以色列人暗中行不正的事，违背耶和华—他们的神，在他们所有的城邑，从了望楼直到坚固城，建筑邱坛；","notes":[]},{"n":10,"t":"在各高冈上、各青翠树下立柱像和木偶；","notes":[]},{"n":11,"t":"在邱坛上烧香，效法耶和华在他们面前赶出的外邦人所行的，又行恶事惹动耶和华的怒气；","notes":[]},{"n":12,"t":"且事奉偶像，就是耶和华警戒他们不可行的。","notes":[]},{"n":13,"t":"但耶和华借众先知、先见劝戒以色列人和犹大人说：「当离开你们的恶行，谨守我的诫命律例，遵行我吩咐你们列祖，并借我仆人众先知所传给你们的律法。」","notes":[]},{"n":14,"t":"他们却不听从，竟硬着颈项，效法他们列祖，不信服耶和华—他们的神，","notes":[]},{"n":15,"t":"厌弃他的律例和他与他们列祖所立的约，并劝戒他们的话，随从虚无的神，自己成为虚妄，效法周围的外邦人，就是耶和华嘱咐他们不可效法的；","notes":[]},{"n":16,"t":"离弃耶和华—他们神的一切诫命，为自己铸了两个牛犊的像，立了亚舍拉，敬拜天上的万象，事奉巴力，","notes":[]},{"n":17,"t":"又使他们的儿女经火，用占卜，行法术卖了自己，行耶和华眼中看为恶的事，惹动他的怒气。","notes":[]},{"n":18,"t":"所以耶和华向以色列人大大发怒，从自己面前赶出他们，只剩下犹大一个支派。","notes":[]},{"n":19,"t":"犹大人也不遵守耶和华—他们神的诫命，随从以色列人所立的条规。","notes":[]},{"n":20,"t":"耶和华就厌弃以色列全族，使他们受苦，把他们交在抢夺他们的人手中，以致赶出他们离开自己面前，","notes":[]},{"n":21,"t":"将以色列国从大卫家夺回；他们就立尼八的儿子耶罗波安作王。耶罗波安引诱以色列人不随从耶和华，陷在大罪里。","notes":[]},{"n":22,"t":"以色列人犯耶罗波安所犯的一切罪，总不离开，","notes":[]},{"n":23,"t":"以致耶和华从自己面前赶出他们，正如借他仆人众先知所说的。这样，以色列人从本地被掳到亚述，直到今日。","notes":[]},{"n":24,"t":"亚述王从巴比伦、古他、亚瓦、哈马，和西法瓦音迁移人来，安置在撒马利亚的城邑，代替以色列人；他们就得了撒马利亚，住在其中。","notes":[],"heads":["亚述人定居于以色列人中"]},{"n":25,"t":"他们才住那里的时候，不敬畏耶和华，所以耶和华叫狮子进入他们中间，咬死了些人。","notes":[]},{"n":26,"t":"有人告诉亚述王说：「你所迁移安置在撒马利亚各城的那些民，不知道那地之神的规矩，所以那神叫狮子进入他们中间，咬死他们。」","notes":[]},{"n":27,"t":"亚述王就吩咐说：「叫所掳来的祭司回去一个，使他住在那里，将那地之神的规矩指教那些民。」","notes":[]},{"n":28,"t":"于是有一个从撒马利亚掳去的祭司回来，住在伯特利，指教他们怎样敬畏耶和华。","notes":[]},{"n":29,"t":"然而，各族之人在所住的城里各为自己制造神像，安置在撒马利亚人所造有邱坛的殿中。","notes":[]},{"n":30,"t":"巴比伦人造疏割·比讷像；古他人造匿甲像；哈马人造亚示玛像；","notes":[]},{"n":31,"t":"亚瓦人造匿哈和他珥他像；西法瓦音人用火焚烧儿女，献给西法瓦音的神亚得米勒和亚拿米勒。","notes":[]},{"n":32,"t":"他们惧怕耶和华，也从他们中间立邱坛的祭司，为他们在有邱坛的殿中献祭。","notes":[]},{"n":33,"t":"他们又惧怕耶和华，又事奉自己的神，从何邦迁移，就随何邦的风俗。","notes":[]},{"n":34,"t":"他们直到如今仍照先前的风俗去行，不专心敬畏耶和华，不全守自己的规矩、典章，也不遵守耶和华吩咐雅各后裔的律法、诫命。（雅各，就是从前耶和华起名叫以色列的。）","notes":[]},{"n":35,"t":"耶和华曾与他们立约，嘱咐他们说：「不可敬畏别神，不可跪拜事奉他，也不可向他献祭。","notes":[]},{"n":36,"t":"但那用大能和伸出来的膀臂领你们出埃及地的耶和华，你们当敬畏，跪拜，向他献祭。","notes":[]},{"n":37,"t":"他给你们写的律例、典章、律法、诫命，你们应当永远谨守遵行，不可敬畏别神。","notes":[]},{"n":38,"t":"我—耶和华与你们所立的约你们不可忘记，也不可敬畏别神。","notes":[]},{"n":39,"t":"但要敬畏耶和华—你们的神，他必救你们脱离一切仇敌的手。」","notes":[]},{"n":40,"t":"他们却不听从，仍照先前的风俗去行。","notes":[]},{"n":41,"t":"如此这些民又惧怕耶和华，又事奉他们的偶像。他们子子孙孙也都照样行，效法他们的祖宗，直到今日。","notes":[]}]},"18":{"heading":"犹大王希西家","verses":[{"n":1,"t":"以色列王以拉的儿子何细亚第三年，犹大王亚哈斯的儿子希西家登基。","notes":[]},{"n":2,"t":"他登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫亚比，是撒迦利雅的女儿。","notes":[]},{"n":3,"t":"希西家行耶和华眼中看为正的事，效法他祖大卫一切所行的。","notes":[]},{"n":4,"t":"他废去邱坛，毁坏柱像，砍下木偶，打碎摩西所造的铜蛇，因为到那时以色列人仍向铜蛇烧香。希西家叫铜蛇为铜块。","notes":["或译：人称铜蛇为铜像"]},{"n":5,"t":"希西家倚靠耶和华—以色列的神，在他前后的犹大列王中没有一个及他的。","notes":[]},{"n":6,"t":"因为他专靠耶和华，总不离开，谨守耶和华所吩咐摩西的诫命。","notes":[]},{"n":7,"t":"耶和华与他同在，他无论往何处去尽都亨通。他背叛、不肯事奉亚述王。","notes":[]},{"n":8,"t":"希西家攻击非利士人，直到迦萨，并迦萨的四境，从了望楼到坚固城。","notes":[]},{"n":9,"t":"希西家王第四年，就是以色列王以拉的儿子何细亚第七年，亚述王撒缦以色上来围困撒马利亚；","notes":[]},{"n":10,"t":"过了三年就攻取了城。希西家第六年，以色列王何细亚第九年，撒马利亚被攻取了。","notes":[]},{"n":11,"t":"亚述王将以色列人掳到亚述，把他们安置在哈腊与歌散的哈博河边，并米底亚人的城邑；","notes":[]},{"n":12,"t":"都因他们不听从耶和华—他们神的话，违背他的约，就是耶和华仆人摩西吩咐他们所当守的。","notes":[]},{"n":13,"t":"希西家王十四年，亚述王西拿基立上来攻击犹大的一切坚固城，将城攻取。","notes":[],"heads":["亚述人威胁耶路撒冷"]},{"n":14,"t":"犹大王希西家差人往拉吉去见亚述王，说：「我有罪了，求你离开我；凡你罚我的，我必承当。」于是亚述王罚犹大王希西家银子三百他连得，金子三十他连得。","notes":[]},{"n":15,"t":"希西家就把耶和华殿里和王宫府库里所有的银子都给了他。","notes":[]},{"n":16,"t":"那时，犹大王希西家将耶和华殿门上的金子和他自己包在柱上的金子都刮下来，给了亚述王。","notes":[]},{"n":17,"t":"亚述王从拉吉差遣他珥探、拉伯撒利，和拉伯沙基率领大军往耶路撒冷，到希西家王那里去。他们上到耶路撒冷，就站在上池的水沟旁，在漂布地的大路上。","notes":[]},{"n":18,"t":"他们呼叫王的时候，就有希勒家的儿子家宰以利亚敬，并书记舍伯那和亚萨的儿子史官约亚，出来见他们。","notes":[]},{"n":19,"t":"拉伯沙基说：「你们去告诉希西家说，亚述大王如此说：『你所倚靠的有什么可仗赖的呢？","notes":[]},{"n":20,"t":"你说有打仗的计谋和能力，我看不过是虚话。你到底倚靠谁才背叛我呢？","notes":[]},{"n":21,"t":"看哪，你所倚靠的埃及是那压伤的苇杖；人若靠这杖，就必刺透他的手。埃及王法老向一切倚靠他的人也是这样。","notes":[]},{"n":22,"t":"你们若对我说：我们倚靠耶和华—我们的神，希西家岂不是将神的邱坛和祭坛废去，且对犹大和耶路撒冷的人说：你们当在耶路撒冷这坛前敬拜吗？","notes":[]},{"n":23,"t":"现在你把当头给我主亚述王，我给你二千匹马，看你这一面骑马的人够不够。","notes":[]},{"n":24,"t":"若不然，怎能打败我主臣仆中最小的军长呢？你竟倚靠埃及的战车马兵吗？","notes":[]},{"n":25,"t":"现在我上来攻击毁灭这地，岂没有耶和华的意思吗？耶和华吩咐我说：你上去攻击毁灭这地吧！』」","notes":[]},{"n":26,"t":"希勒家的儿子以利亚敬和舍伯那，并约亚，对拉伯沙基说：「求你用亚兰言语和仆人说话，因为我们懂得；不要用犹大言语和我们说话，达到城上百姓的耳中。」","notes":[]},{"n":27,"t":"拉伯沙基说：「我主差遣我来，岂是单对你和你的主说这些话吗？不也是对这些坐在城上、要与你们一同吃自己粪、喝自己尿的人说吗？」","notes":[]},{"n":28,"t":"于是拉伯沙基站着，用犹大言语大声喊着说：「你们当听亚述大王的话！","notes":[]},{"n":29,"t":"王如此说：『你们不要被希西家欺哄了；因他不能救你们脱离我的手。","notes":[]},{"n":30,"t":"也不要听希西家使你们倚靠耶和华，说耶和华必要拯救我们，这城必不交在亚述王的手中。』","notes":[]},{"n":31,"t":"不要听希西家的话！因亚述王如此说：『你们要与我和好，出来投降我，各人就可以吃自己葡萄树和无花果树的果子，喝自己井里的水。","notes":[]},{"n":32,"t":"等我来领你们到一个地方与你们本地一样，就是有五谷和新酒之地，有粮食和葡萄园之地，有橄榄树和蜂蜜之地，好使你们存活，不至于死。希西家劝导你们，说耶和华必拯救我们；你们不要听他的话。","notes":[]},{"n":33,"t":"列国的神有哪一个救他本国脱离亚述王的手呢？","notes":[]},{"n":34,"t":"哈马、亚珥拔的神在哪里呢？西法瓦音、希拿、以瓦的神在哪里呢？他们曾救撒马利亚脱离我的手吗？","notes":[]},{"n":35,"t":"这些国的神有谁曾救自己的国脱离我的手呢？难道耶和华能救耶路撒冷脱离我的手吗？』」","notes":[]},{"n":36,"t":"百姓静默不言，并不回答一句，因为王曾吩咐说：「不要回答他。」","notes":[]},{"n":37,"t":"当下，希勒家的儿子家宰以利亚敬和书记舍伯那，并亚萨的儿子史官约亚，都撕裂衣服，来到希西家那里，将拉伯沙基的话告诉了他。","notes":[]}]},"19":{"heading":"希西家王派人求问以赛亚","verses":[{"n":1,"t":"希西家王听见，就撕裂衣服，披上麻布，进了耶和华的殿；","notes":[]},{"n":2,"t":"使家宰以利亚敬和书记舍伯那，并祭司中的长老，都披上麻布，去见亚摩斯的儿子先知以赛亚，","notes":[]},{"n":3,"t":"对他说：「希西家如此说：『今日是急难、责罚、凌辱的日子，就如妇人将要生产婴孩，却没有力量生产。","notes":[]},{"n":4,"t":"或者耶和华—你的神听见拉伯沙基的一切话，就是他主人亚述王打发他来辱骂永生神的话，耶和华—你的神听见这话，就发斥责。故此，求你为余剩的民扬声祷告。』」","notes":[]},{"n":5,"t":"希西家王的臣仆就去见以赛亚。","notes":[]},{"n":6,"t":"以赛亚对他们说：「要这样对你们的主人说，耶和华如此说：『你听见亚述王的仆人亵渎我的话，不要惧怕。","notes":[]},{"n":7,"t":"我必惊动他的心，他要听见风声就归回本地。我必使他在那里倒在刀下。』」","notes":["原文是使灵进入"]},{"n":8,"t":"拉伯沙基回去，正遇见亚述王攻打立拿，原来他早听见亚述王拔营离开拉吉。","notes":[],"heads":["亚述人再度威胁"]},{"n":9,"t":"亚述王听见人论古实王特哈加说：「他出来要与你争战。」于是亚述王又打发使者去见希西家，吩咐他们说：","notes":[]},{"n":10,"t":"「你们对犹大王希西家如此说：『不要听你所倚靠的神欺哄你，说耶路撒冷必不交在亚述王的手中。","notes":[]},{"n":11,"t":"你总听说亚述诸王向列国所行的，乃是尽行灭绝，难道你还能得救吗？","notes":[]},{"n":12,"t":"我列祖所毁灭的，就是歌散、哈兰、利色，和属提·拉撒的伊甸人，这些国的神何曾拯救这些国呢？","notes":[]},{"n":13,"t":"哈马的王、亚珥拔的王、西法瓦音城的王、希拿，和以瓦的王都在哪里呢？』」","notes":[]},{"n":14,"t":"希西家从使者手里接过书信来，看完了，就上耶和华的殿，将书信在耶和华面前展开。","notes":[]},{"n":15,"t":"希西家向耶和华祷告说：「坐在二基路伯上耶和华—以色列的神啊，你是天下万国的神，你曾创造天地。","notes":[]},{"n":16,"t":"耶和华啊，求你侧耳而听！耶和华啊，求你睁眼而看！要听西拿基立打发使者来辱骂永生神的话。","notes":[]},{"n":17,"t":"耶和华啊，亚述诸王果然使列国和列国之地变为荒凉，","notes":[]},{"n":18,"t":"将列国的神像都扔在火里；因为它本不是神，乃是人手所造的，是木头石头的，所以灭绝它。","notes":[]},{"n":19,"t":"耶和华—我们的神啊，现在求你救我们脱离亚述王的手，使天下万国都知道惟独你—耶和华是神！」","notes":[]},{"n":20,"t":"亚摩斯的儿子以赛亚就打发人去见希西家，说：「耶和华—以色列的神如此说：『你既然求我攻击亚述王西拿基立，我已听见了。』","notes":[],"heads":["以赛亚传给王的信息"]},{"n":21,"t":"耶和华论他这样说：锡安的处女藐视你，嗤笑你；耶路撒冷的女子向你摇头。","notes":[]},{"n":22,"t":"你辱骂谁？亵渎谁？扬起声来，高举眼目攻击谁呢？乃是攻击以色列的圣者！","notes":[]},{"n":23,"t":"你借你的使者辱骂主，并说：我率领许多战车上山顶，到黎巴嫩极深之处；我要砍伐其中高大的香柏树和佳美的松树；我必上极高之处，进入肥田的树林。","notes":[]},{"n":24,"t":"我已经在外邦挖井喝水；我必用脚掌踏干埃及的一切河。","notes":[]},{"n":25,"t":"耶和华说，我早先所做的，古时所立的，就是现在借你使坚固城荒废，变为乱堆，这事你岂没有听见吗？","notes":[]},{"n":26,"t":"所以其中的居民力量甚小，惊惶羞愧。他们像野草，像青菜，如房顶上的草，又如未长成而枯干的禾稼。","notes":[]},{"n":27,"t":"你坐下，你出去，你进来，你向我发烈怒，我都知道。","notes":[]},{"n":28,"t":"因你向我发烈怒，又因你狂傲的话达到我耳中，我就要用钩子钩上你的鼻子，把嚼环放在你口里，使你从你来的路转回去。","notes":[]},{"n":29,"t":"「以色列人哪，我赐你们一个证据：你们今年要吃自生的，明年也要吃自长的；至于后年，你们要耕种收割，栽植葡萄园，吃其中的果子。","notes":[]},{"n":30,"t":"犹大家所逃脱余剩的，仍要往下扎根，向上结果。","notes":[]},{"n":31,"t":"必有余剩的民从耶路撒冷而出；必有逃脱的人从锡安山而来。耶和华的热心必成就这事。","notes":[]},{"n":32,"t":"「所以，耶和华论亚述王如此说：『他必不得来到这城，也不在这里射箭，不得拿盾牌到城前，也不筑垒攻城。","notes":[]},{"n":33,"t":"他从哪条路来，必从那条路回去，必不得来到这城。这是耶和华说的。","notes":[]},{"n":34,"t":"因我为自己的缘故，又为我仆人大卫的缘故，必保护拯救这城。』」","notes":[]},{"n":35,"t":"当夜，耶和华的使者出去，在亚述营中杀了十八万五千人。清早有人起来，一看，都是死尸了。","notes":[]},{"n":36,"t":"亚述王西拿基立就拔营回去，住在尼尼微。","notes":[]},{"n":37,"t":"一日在他的神尼斯洛庙里叩拜，他儿子亚得米勒和沙利色用刀杀了他，就逃到亚拉腊地。他儿子以撒哈顿接续他作王。","notes":[]}]},"20":{"heading":"希西家病重康复","verses":[{"n":1,"t":"那时，希西家病得要死。亚摩斯的儿子先知以赛亚去见他，对他说：「耶和华如此说：『你当留遗命与你的家，因为你必死，不能活了。』」","notes":[]},{"n":2,"t":"希西家就转脸朝墙，祷告耶和华说：","notes":[]},{"n":3,"t":"「耶和华啊，求你记念我在你面前怎样存完全的心，按诚实行事，又做你眼中所看为善的。」希西家就痛哭了。","notes":[]},{"n":4,"t":"以赛亚出来，还没有到中院，耶和华的话就临到他，说：","notes":["院：或译城"]},{"n":5,"t":"「你回去告诉我民的君希西家说：耶和华—你祖大卫的神如此说：『我听见了你的祷告，看见了你的眼泪，我必医治你；到第三日，你必上到耶和华的殿。","notes":[]},{"n":6,"t":"我必加增你十五年的寿数，并且我要救你和这城脱离亚述王的手。我为自己和我仆人大卫的缘故，必保护这城。』」","notes":[]},{"n":7,"t":"以赛亚说：「当取一块无花果饼来。」人就取了来，贴在疮上，王便痊愈了。","notes":[]},{"n":8,"t":"希西家问以赛亚说：「耶和华必医治我，到第三日，我能上耶和华的殿，有什么兆头呢？」","notes":[]},{"n":9,"t":"以赛亚说：「耶和华必成就他所说的。这是他给你的兆头：你要日影向前进十度呢？是要往后退十度呢？」","notes":[]},{"n":10,"t":"希西家回答说：「日影向前进十度容易，我要日影往后退十度。」","notes":[]},{"n":11,"t":"先知以赛亚求告耶和华，耶和华就使亚哈斯的日晷向前进的日影，往后退了十度。","notes":[]},{"n":12,"t":"那时，巴比伦王巴拉但的儿子米罗达·巴拉但听见希西家病而痊愈，就送书信和礼物给他。","notes":[],"heads":["从巴比伦来的使者"]},{"n":13,"t":"希西家听从使者的话，就把他宝库的金子、银子、香料、贵重的膏油，和他武库的一切军器，并他所有的财宝，都给他们看。他家中和他全国之内，希西家没有一样不给他们看的。","notes":[]},{"n":14,"t":"于是先知以赛亚来见希西家王，问他说：「这些人说什么？他们从哪里来见你？」希西家说：「他们从远方的巴比伦来。」","notes":[]},{"n":15,"t":"以赛亚说：「他们在你家里看见了什么？」希西家说：「凡我家中所有的，他们都看见了；我财宝中没有一样不给他们看的。」","notes":[]},{"n":16,"t":"以赛亚对希西家说：「你要听耶和华的话，","notes":[]},{"n":17,"t":"日子必到，凡你家里所有的，并你列祖积蓄到如今的，都要被掳到巴比伦去，不留下一样。这是耶和华说的。","notes":[]},{"n":18,"t":"并且从你本身所生的众子，其中必有被掳去在巴比伦王宫里当太监的。」","notes":[]},{"n":19,"t":"希西家对以赛亚说：「你所说耶和华的话甚好！若在我的年日中有太平和稳固的景况，岂不是好吗？」","notes":[]},{"n":20,"t":"希西家其余的事和他的勇力，他怎样挖池、挖沟、引水入城，都写在犹大列王记上。","notes":[],"heads":["希西家逝世"]},{"n":21,"t":"希西家与他列祖同睡。他儿子玛拿西接续他作王。","notes":[]}]},"21":{"heading":"犹大王玛拿西","verses":[{"n":1,"t":"玛拿西登基的时候年十二岁，在耶路撒冷作王五十五年。他母亲名叫协西巴。","notes":[]},{"n":2,"t":"玛拿西行耶和华眼中看为恶的事，效法耶和华在以色列人面前赶出的外邦人所行可憎的事。","notes":[]},{"n":3,"t":"重新建筑他父希西家所毁坏的邱坛，又为巴力筑坛，做亚舍拉像，效法以色列王亚哈所行的，且敬拜事奉天上的万象；","notes":[]},{"n":4,"t":"在耶和华殿宇中筑坛。耶和华曾指着这殿说：「我必立我的名在耶路撒冷。」","notes":[]},{"n":5,"t":"他在耶和华殿的两院中为天上的万象筑坛，","notes":[]},{"n":6,"t":"并使他的儿子经火，又观兆，用法术，立交鬼的和行巫术的，多行耶和华眼中看为恶的事，惹动他的怒气；","notes":[]},{"n":7,"t":"又在殿内立雕刻的亚舍拉像。耶和华曾对大卫和他儿子所罗门说：「我在以色列众支派中所选择的耶路撒冷和这殿，必立我的名，直到永远。","notes":[]},{"n":8,"t":"以色列人若谨守遵行我一切所吩咐他们的和我仆人摩西所吩咐他们的一切律法，我就不再使他们挪移离开我所赐给他们列祖之地。」","notes":[]},{"n":9,"t":"他们却不听从。玛拿西引诱他们行恶，比耶和华在以色列人面前所灭的列国更甚。","notes":[]},{"n":10,"t":"耶和华借他仆人众先知说：","notes":[]},{"n":11,"t":"「因犹大王玛拿西行这些可憎的恶事比先前亚摩利人所行的更甚，使犹大人拜他的偶像，陷在罪里；","notes":[]},{"n":12,"t":"所以耶和华—以色列的神如此说：我必降祸与耶路撒冷和犹大，叫一切听见的人无不耳鸣。","notes":[]},{"n":13,"t":"我必用量撒马利亚的准绳和亚哈家的线铊拉在耶路撒冷上，必擦净耶路撒冷，如人擦盘，将盘倒扣。","notes":[]},{"n":14,"t":"我必弃掉所余剩的子民，把他们交在仇敌手中，使他们成为一切仇敌掳掠之物；","notes":["原文是产业"]},{"n":15,"t":"是因他们自从列祖出埃及直到如今，常行我眼中看为恶的事，惹动我的怒气。」","notes":[]},{"n":16,"t":"玛拿西行耶和华眼中看为恶的事，使犹大人陷在罪里，又流许多无辜人的血，充满了耶路撒冷，从这边直到那边。","notes":[]},{"n":17,"t":"玛拿西其余的事，凡他所行的和他所犯的罪都写在犹大列王记上。","notes":[]},{"n":18,"t":"玛拿西与他列祖同睡，葬在自己宫院乌撒的园内；他儿子亚们接续他作王。","notes":[]},{"n":19,"t":"亚们登基的时候年二十二岁，在耶路撒冷作王二年。他母亲名叫米舒利密，是约提巴人哈鲁斯的女儿。","notes":[],"heads":["犹大王亚们"]},{"n":20,"t":"亚们行耶和华眼中看为恶的事，与他父亲玛拿西所行的一样；","notes":[]},{"n":21,"t":"行他父亲一切所行的，敬奉他父亲所敬奉的偶像，","notes":[]},{"n":22,"t":"离弃耶和华—他列祖的神，不遵行耶和华的道。","notes":[]},{"n":23,"t":"亚们王的臣仆背叛他，在宫里杀了他。","notes":[]},{"n":24,"t":"但国民杀了那些背叛亚们王的人，立他儿子约西亚接续他作王。","notes":[]},{"n":25,"t":"亚们其余所行的事都写在犹大列王记上。","notes":[]},{"n":26,"t":"亚们葬在乌撒的园内自己的坟墓里。他儿子约西亚接续他作王。","notes":[]}]},"22":{"heading":"犹大王约西亚","verses":[{"n":1,"t":"约西亚登基的时候年八岁，在耶路撒冷作王三十一年。他母亲名叫耶底大，是波斯加人亚大雅的女儿。","notes":[]},{"n":2,"t":"约西亚行耶和华眼中看为正的事，行他祖大卫一切所行的，不偏左右。","notes":[]},{"n":3,"t":"约西亚王十八年，王差遣米书兰的孙子、亚萨利的儿子—书记沙番上耶和华殿去，吩咐他说：","notes":[],"heads":["发现律法书"]},{"n":4,"t":"「你去见大祭司希勒家，使他将奉到耶和华殿的银子，就是守门的从民中收聚的银子，数算数算，","notes":[]},{"n":5,"t":"交给耶和华殿里办事的人，使他们转交耶和华殿里做工的人，好修理殿的破坏之处，","notes":[]},{"n":6,"t":"就是转交木匠和工人，并瓦匠，又买木料和凿成的石头修理殿宇，","notes":[]},{"n":7,"t":"将银子交在办事的人手里，不与他们算帐，因为他们办事诚实。」","notes":[]},{"n":8,"t":"大祭司希勒家对书记沙番说：「我在耶和华殿里得了律法书。」希勒家将书递给沙番，沙番就看了。","notes":[]},{"n":9,"t":"书记沙番到王那里，回复王说：「你的仆人已将殿里的银子倒出数算，交给耶和华殿里办事的人了。」","notes":[]},{"n":10,"t":"书记沙番又对王说：「祭司希勒家递给我一卷书。」沙番就在王面前读那书。","notes":[]},{"n":11,"t":"王听见律法书上的话，便撕裂衣服，","notes":[]},{"n":12,"t":"吩咐祭司希勒家与沙番的儿子亚希甘、米该亚的儿子亚革波、书记沙番和王的臣仆亚撒雅，说：","notes":[]},{"n":13,"t":"「你们去为我、为民、为犹大众人，以这书上的话求问耶和华；因为我们列祖没有听从这书上的言语，没有遵着书上所吩咐我们的去行，耶和华就向我们大发烈怒。」","notes":[]},{"n":14,"t":"于是，祭司希勒家和亚希甘、亚革波、沙番、亚撒雅都去见女先知户勒大。户勒大是掌管礼服沙龙的妻；沙龙是哈珥哈斯的孙子、特瓦的儿子。户勒大住在耶路撒冷第二区。他们请问于她。","notes":[]},{"n":15,"t":"她对他们说：「耶和华—以色列的神如此说：『你们可以回复那差遣你们来见我的人说，","notes":[]},{"n":16,"t":"耶和华如此说：我必照着犹大王所读那书上的一切话，降祸与这地和其上的居民。","notes":[]},{"n":17,"t":"因为他们离弃我，向别神烧香，用他们手所做的惹我发怒，所以我的忿怒必向这地发作，总不止息。』","notes":[]},{"n":18,"t":"然而，差遣你们来求问耶和华的犹大王，你们要这样回复他说：『耶和华—以色列的神如此说：至于你所听见的话，","notes":[]},{"n":19,"t":"就是听见我指着这地和其上的居民所说、要使这地变为荒场、民受咒诅的话，你便心里敬服，在我面前自卑，撕裂衣服，向我哭泣，因此我应允了你。这是我—耶和华说的。","notes":[]},{"n":20,"t":"我必使你平平安安地归到坟墓到你列祖那里；我要降与这地的一切灾祸，你也不至亲眼看见。』」他们就回复王去了。","notes":[]}]},"23":{"heading":"约西亚废除异教崇拜","verses":[{"n":1,"t":"王差遣人招聚犹大和耶路撒冷的众长老来。","notes":[]},{"n":2,"t":"王和犹大众人与耶路撒冷的居民，并祭司、先知，和所有的百姓，无论大小，都一同上到耶和华的殿；王就把耶和华殿里所得的约书念给他们听。","notes":[]},{"n":3,"t":"王站在柱旁，在耶和华面前立约，要尽心尽性地顺从耶和华，遵守他的诫命、法度、律例，成就这书上所记的约言。众民都服从这约。","notes":[]},{"n":4,"t":"王吩咐大祭司希勒家和副祭司，并把门的，将那为巴力和亚舍拉，并天上万象所造的器皿，都从耶和华殿里搬出来，在耶路撒冷外汲沦溪旁的田间烧了，把灰拿到伯特利去。","notes":[]},{"n":5,"t":"从前犹大列王所立拜偶像的祭司，在犹大城邑的邱坛和耶路撒冷的周围烧香，现在王都废去，又废去向巴力和日、月、行星，并天上万象烧香的人；","notes":["或译：十二宫"]},{"n":6,"t":"又从耶和华殿里将亚舍拉搬到耶路撒冷外汲沦溪边焚烧，打碎成灰，将灰撒在平民的坟上；","notes":[]},{"n":7,"t":"又拆毁耶和华殿里娈童的屋子，就是妇女为亚舍拉织帐子的屋子，","notes":[]},{"n":8,"t":"并且从犹大的城邑带众祭司来，污秽祭司烧香的邱坛，从迦巴直到别是巴，又拆毁城门旁的邱坛，这邱坛在邑宰约书亚门前，进城门的左边。","notes":[]},{"n":9,"t":"但是邱坛的祭司不登耶路撒冷耶和华的坛，只在他们弟兄中间吃无酵饼。","notes":[]},{"n":10,"t":"又污秽欣嫩子谷的陀斐特，不许人在那里使儿女经火献给摩洛；","notes":[]},{"n":11,"t":"又将犹大列王在耶和华殿门旁、太监拿单·米勒靠近游廊的屋子、向日头所献的马废去，且用火焚烧日车。","notes":[]},{"n":12,"t":"犹大列王在亚哈斯楼顶上所筑的坛和玛拿西在耶和华殿两院中所筑的坛，王都拆毁打碎了，就把灰倒在汲沦溪中。","notes":[]},{"n":13,"t":"从前以色列王所罗门在耶路撒冷前、邪僻山右边为西顿人可憎的神亚斯她录、摩押人可憎的神基抹、亚扪人可憎的神米勒公所筑的邱坛，王都污秽了，","notes":[]},{"n":14,"t":"又打碎柱像，砍下木偶，将人的骨头充满了那地方。","notes":[]},{"n":15,"t":"他将伯特利的坛，就是叫以色列人陷在罪里、尼八的儿子耶罗波安所筑的那坛，都拆毁焚烧，打碎成灰，并焚烧了亚舍拉。","notes":[]},{"n":16,"t":"约西亚回头，看见山上的坟墓，就打发人将坟墓里的骸骨取出来，烧在坛上，污秽了坛，正如从前神人宣传耶和华的话。","notes":[]},{"n":17,"t":"约西亚问说：「我所看见的是什么碑？」那城里的人回答说：「先前有神人从犹大来，预先说王现在向伯特利坛所行的事，这就是他的墓碑。」","notes":[]},{"n":18,"t":"约西亚说：「由他吧！不要挪移他的骸骨。」他们就不动他的骸骨，也不动从撒马利亚来那先知的骸骨。","notes":[]},{"n":19,"t":"从前以色列诸王在撒马利亚的城邑建筑邱坛的殿，惹动耶和华的怒气，现在约西亚都废去了，就如他在伯特利所行的一般；","notes":[]},{"n":20,"t":"又将邱坛的祭司都杀在坛上，并在坛上烧人的骨头，就回耶路撒冷去了。","notes":[]},{"n":21,"t":"王吩咐众民说：「你们当照这约书上所写的，向耶和华—你们的神守逾越节。」","notes":[],"heads":["约西亚守逾越节"]},{"n":22,"t":"自从士师治理以色列人和以色列王、犹大王的时候，直到如今，实在没有守过这样的逾越节；","notes":[]},{"n":23,"t":"只有约西亚王十八年在耶路撒冷向耶和华守这逾越节。","notes":[]},{"n":24,"t":"凡犹大国和耶路撒冷所有交鬼的、行巫术的，与家中的神像和偶像，并一切可憎之物，约西亚尽都除掉，成就了祭司希勒家在耶和华殿里所得律法书上所写的话。","notes":[],"heads":["约西亚的其他改革"]},{"n":25,"t":"在约西亚以前没有王像他尽心、尽性、尽力地归向耶和华，遵行摩西的一切律法；在他以后也没有兴起一个王像他。","notes":[]},{"n":26,"t":"然而，耶和华向犹大所发猛烈的怒气仍不止息，是因玛拿西诸事惹动他。","notes":[]},{"n":27,"t":"耶和华说：「我必将犹大人从我面前赶出，如同赶出以色列人一般；我必弃掉我从前所选择的这城—耶路撒冷和我所说立我名的殿。」","notes":[]},{"n":28,"t":"约西亚其余的事，凡他所行的都写在犹大列王记上。","notes":[],"heads":["约西亚逝世"]},{"n":29,"t":"约西亚年间，埃及王法老尼哥上到幼发拉底河攻击亚述王；约西亚王去抵挡他。埃及王遇见约西亚在米吉多，就杀了他。","notes":[]},{"n":30,"t":"他的臣仆用车将他的尸首从米吉多送到耶路撒冷，葬在他自己的坟墓里。国民膏约西亚的儿子约哈斯接续他父亲作王。","notes":[]},{"n":31,"t":"约哈斯登基的时候年二十三岁，在耶路撒冷作王三个月。他母亲名叫哈慕她，是立拿人耶利米的女儿。","notes":[],"heads":["犹大王约哈斯"]},{"n":32,"t":"约哈斯行耶和华眼中看为恶的事，效法他列祖一切所行的。","notes":[]},{"n":33,"t":"法老尼哥将约哈斯锁禁在哈马地的利比拉，不许他在耶路撒冷作王，又罚犹大国银子一百他连得，金子一他连得。","notes":[]},{"n":34,"t":"法老尼哥立约西亚的儿子以利亚敬接续他父亲约西亚作王，给他改名叫约雅敬，却将约哈斯带到埃及，他就死在那里。","notes":[]},{"n":35,"t":"约雅敬将金银给法老，遵着法老的命向国民征取金银，按着各人的力量派定，索要金银，好给法老尼哥。","notes":[],"heads":["犹大王约雅敬"]},{"n":36,"t":"约雅敬登基的时候年二十五岁，在耶路撒冷作王十一年。他母亲名叫西布大，是鲁玛人毗大雅的女儿。","notes":[]},{"n":37,"t":"约雅敬行耶和华眼中看为恶的事，效法他列祖一切所行的。","notes":[]}]},"24":{"heading":"犹大王约雅斤","verses":[{"n":1,"t":"约雅敬年间，巴比伦王尼布甲尼撒上到犹大；约雅敬服事他三年，然后背叛他。","notes":[]},{"n":2,"t":"耶和华使迦勒底军、亚兰军、摩押军，和亚扪人的军来攻击约雅敬，毁灭犹大，正如耶和华借他仆人众先知所说的。","notes":[]},{"n":3,"t":"这祸临到犹大人，诚然是耶和华所命的，要将他们从自己面前赶出，是因玛拿西所犯的一切罪；","notes":[]},{"n":4,"t":"又因他流无辜人的血，充满了耶路撒冷；耶和华决不肯赦免。","notes":[]},{"n":5,"t":"约雅敬其余的事，凡他所行的都写在犹大列王记上。","notes":[]},{"n":6,"t":"约雅敬与他列祖同睡。他儿子约雅斤接续他作王。","notes":[]},{"n":7,"t":"埃及王不再从他国中出来；因为巴比伦王将埃及王所管之地，从埃及小河直到幼发拉底河都夺去了。","notes":[]},{"n":8,"t":"约雅斤登基的时候年十八岁，在耶路撒冷作王三个月。他母亲名叫尼护施她，是耶路撒冷人以利拿单的女儿。","notes":[]},{"n":9,"t":"约雅斤行耶和华眼中看为恶的事，效法他父亲一切所行的。","notes":[]},{"n":10,"t":"那时，巴比伦王尼布甲尼撒的军兵上到耶路撒冷，围困城。","notes":[]},{"n":11,"t":"当他军兵围困城的时候，巴比伦王尼布甲尼撒就亲自来了。","notes":[]},{"n":12,"t":"犹大王约雅斤和他母亲、臣仆、首领、太监一同出城，投降巴比伦王；巴比伦王便拿住他。那时是巴比伦王第八年。","notes":[]},{"n":13,"t":"巴比伦王将耶和华殿和王宫里的宝物都拿去了，将以色列王所罗门所造耶和华殿里的金器都毁坏了，正如耶和华所说的；","notes":[]},{"n":14,"t":"又将耶路撒冷的众民和众首领，并所有大能的勇士，共一万人，连一切木匠、铁匠都掳了去；除了国中极贫穷的人以外，没有剩下的；","notes":[]},{"n":15,"t":"并将约雅斤和王母、后妃、太监，与国中的大官，都从耶路撒冷掳到巴比伦去了；","notes":[]},{"n":16,"t":"又将一切勇士七千人和木匠、铁匠一千人，都是能上阵的勇士，全掳到巴比伦去了。","notes":[]},{"n":17,"t":"巴比伦王立约雅斤的叔叔玛探雅代替他作王，给玛探雅改名叫西底家。","notes":[]},{"n":18,"t":"西底家登基的时候年二十一岁，在耶路撒冷作王十一年。他母亲名叫哈慕她，是立拿人耶利米的女儿。","notes":[],"heads":["犹大王西底家"]},{"n":19,"t":"西底家行耶和华眼中看为恶的事，是照约雅敬一切所行的。","notes":[]},{"n":20,"t":"因此耶和华的怒气在耶路撒冷和犹大发作，以致将人民从自己面前赶出。","notes":[]}]},"25":{"heading":"耶路撒冷陷落","verses":[{"n":1,"t":"西底家背叛巴比伦王。他作王第九年十月初十日，巴比伦王尼布甲尼撒率领全军来攻击耶路撒冷，对城安营，四围筑垒攻城。","notes":[]},{"n":2,"t":"于是城被围困，直到西底家王十一年。","notes":[]},{"n":3,"t":"四月初九日，城里有大饥荒，甚至百姓都没有粮食。","notes":[]},{"n":4,"t":"城被攻破，一切兵丁就在夜间从靠近王园两城中间的门逃跑。迦勒底人正在四围攻城，王就向亚拉巴逃走。","notes":[]},{"n":5,"t":"迦勒底的军队追赶王，在耶利哥的平原追上他；他的全军都离开他四散了。","notes":[]},{"n":6,"t":"迦勒底人就拿住王，带他到在利比拉的巴比伦王那里审判他。","notes":[]},{"n":7,"t":"在西底家眼前杀了他的众子，并且剜了西底家的眼睛，用铜链锁着他，带到巴比伦去。","notes":[]},{"n":8,"t":"巴比伦王尼布甲尼撒十九年五月初七日，巴比伦王的臣仆、护卫长尼布撒拉旦来到耶路撒冷，","notes":[],"heads":["圣殿被毁"]},{"n":9,"t":"用火焚烧耶和华的殿和王宫，又焚烧耶路撒冷的房屋，就是各大户家的房屋。","notes":[]},{"n":10,"t":"跟从护卫长迦勒底的全军就拆毁耶路撒冷四围的城墙。","notes":[]},{"n":11,"t":"那时护卫长尼布撒拉旦将城里所剩下的百姓，并已经投降巴比伦王的人，以及大众所剩下的人，都掳去了。","notes":[]},{"n":12,"t":"但护卫长留下些民中最穷的，使他们修理葡萄园，耕种田地。","notes":[]},{"n":13,"t":"耶和华殿的铜柱，并耶和华殿的盆座和铜海，迦勒底人都打碎了，将那铜运到巴比伦去了，","notes":[]},{"n":14,"t":"又带去锅、铲子、蜡剪、调羹，并所用的一切铜器，","notes":[]},{"n":15,"t":"火鼎、碗，无论金的银的，护卫长也都带去了。","notes":[]},{"n":16,"t":"所罗门为耶和华殿所造的两根铜柱、一个铜海，和几个盆座，这一切的铜，多得无法可称。","notes":[]},{"n":17,"t":"这一根柱子高十八肘，柱上有铜顶，高三肘；铜顶的周围有网子和石榴，都是铜的。那一根柱子，照此一样，也有网子。","notes":[]},{"n":18,"t":"护卫长拿住大祭司西莱雅、副祭司西番亚，和三个把门的，","notes":[],"heads":["犹大人被掳"]},{"n":19,"t":"又从城中拿住一个管理兵丁的官，并在城里所遇常见王面的五个人和检点国民军长的书记，以及城里遇见的国民六十个人。","notes":["或译：太监"]},{"n":20,"t":"护卫长尼布撒拉旦将这些人带到在利比拉的巴比伦王那里。","notes":[]},{"n":21,"t":"巴比伦王就把他们击杀在哈马地的利比拉。这样，犹大人被掳去离开本地。","notes":[]},{"n":22,"t":"至于犹大国剩下的民，就是巴比伦王尼布甲尼撒所剩下的，巴比伦王立了沙番的孙子、亚希甘的儿子基大利作他们的省长。","notes":[],"heads":["立基大利作犹大省长"]},{"n":23,"t":"众军长和属他们的人听见巴比伦王立了基大利作省长，于是军长尼探雅的儿子以实玛利、加利亚的儿子约哈难、尼陀法人单户篾的儿子西莱雅、玛迦人的儿子雅撒尼亚，和属他们的人都到米斯巴见基大利。","notes":[]},{"n":24,"t":"基大利向他们和属他们的人起誓说：「你们不必惧怕迦勒底臣仆，只管住在这地服事巴比伦王，就可以得福。」","notes":[]},{"n":25,"t":"七月间，宗室以利沙玛的孙子、尼探雅的儿子以实玛利带着十个人来，杀了基大利和同他在米斯巴的犹大人与迦勒底人。","notes":[]},{"n":26,"t":"于是众民，无论大小，连众军长；因为惧怕迦勒底人，都起身往埃及去了。","notes":[]},{"n":27,"t":"犹大王约雅斤被掳后三十七年，巴比伦王以未·米罗达元年十二月二十七日，使犹大王约雅斤抬头，提他出监；","notes":[],"heads":["约雅斤被释"]},{"n":28,"t":"又对他说恩言，使他的位高过与他一同在巴比伦众王的位，","notes":[]},{"n":29,"t":"给他脱了囚服。他终身常在巴比伦王面前吃饭。","notes":[]},{"n":30,"t":"王赐他所需用的食物，日日赐他一分，终身都是这样。","notes":[]}]}},"1CH":{"1":{"heading":"从亚当到亚伯拉罕","verses":[{"n":1,"t":"亚当生塞特；塞特生以挪士；","notes":[]},{"n":2,"t":"以挪士生该南；该南生玛勒列；玛勒列生雅列；","notes":[]},{"n":3,"t":"雅列生以诺；以诺生玛土撒拉；玛土撒拉生拉麦；","notes":[]},{"n":4,"t":"拉麦生挪亚；挪亚生闪、含、雅弗。","notes":[]},{"n":5,"t":"雅弗的儿子是歌篾、玛各、玛代、雅完、土巴、米设、提拉。","notes":[]},{"n":6,"t":"歌篾的儿子是亚实基拿、低法、陀迦玛。","notes":["在创世记十章三节是利法"]},{"n":7,"t":"雅完的儿子是以利沙、他施、基提、多单。","notes":["有作罗单的"]},{"n":8,"t":"含的儿子是古实、麦西、弗、迦南。","notes":[]},{"n":9,"t":"古实的儿子是西巴、哈腓拉、撒弗他、拉玛、撒弗提迦。拉玛的儿子是示巴、底但。","notes":[]},{"n":10,"t":"古实生宁录；他为世上英雄之首。","notes":[]},{"n":11,"t":"麦西生路低人、亚拿米人、利哈比人、拿弗土希人、","notes":[]},{"n":12,"t":"帕斯鲁细人、迦斯路希人、迦斐托人；从迦斐托出来的有非利士人。","notes":[]},{"n":13,"t":"迦南生长子西顿，又生赫","notes":[]},{"n":14,"t":"和耶布斯人、亚摩利人、革迦撒人、","notes":[]},{"n":15,"t":"希未人、亚基人、西尼人、","notes":[]},{"n":16,"t":"亚瓦底人、洗玛利人，并哈马人。","notes":[]},{"n":17,"t":"闪的儿子是以拦、亚述、亚法 撒、路德、亚兰、乌斯、户勒、基帖、米设。","notes":["在创世记十章二十三节是玛施"]},{"n":18,"t":"亚法撒生沙拉；沙拉生希伯。","notes":[]},{"n":19,"t":"希伯生了两个儿子：一个名叫法勒，因为那时人就分地居住；法勒的兄弟名叫约坍。","notes":["就是分的意思"]},{"n":20,"t":"约坍生亚摩答、沙列、哈萨玛非、耶拉、","notes":[]},{"n":21,"t":"哈多兰、乌萨、德拉、","notes":[]},{"n":22,"t":"以巴录、亚比玛利、示巴、","notes":[]},{"n":23,"t":"阿斐、哈腓拉、约巴。这都是约坍的儿子。","notes":[]},{"n":24,"t":"闪生亚法撒；亚法撒生沙拉；","notes":[]},{"n":25,"t":"沙拉生希伯；希伯生法勒；法勒生拉吴；","notes":[]},{"n":26,"t":"拉吴生西鹿；西鹿生拿鹤；拿鹤生他拉；","notes":[]},{"n":27,"t":"他拉生亚伯兰，亚伯兰就是亚伯拉罕。","notes":[]},{"n":28,"t":"亚伯拉罕的儿子是以撒、以实玛利。","notes":[],"heads":["以实玛利的后裔"]},{"n":29,"t":"以实玛利的儿子记在下面：以实玛利的长子是尼拜约，其次是基达、押德别、米比衫、","notes":[]},{"n":30,"t":"米施玛、度玛、玛撒、哈达、提玛、","notes":[]},{"n":31,"t":"伊突、拿非施、基底玛。这都是以实玛利的儿子。","notes":[]},{"n":32,"t":"亚伯拉罕的妾基土拉所生的儿子，就是心兰、约珊、米但、米甸、伊施巴、书亚。约珊的儿子是示巴、底但。","notes":[]},{"n":33,"t":"米甸的儿子是以法、以弗、哈诺、亚比大、以勒大。这都是基土拉的子孙。","notes":[]},{"n":34,"t":"亚伯拉罕生以撒；以撒的儿子是以扫和以色列。","notes":[],"heads":["以扫的后裔"]},{"n":35,"t":"以扫的儿子是以利法、流珥、耶乌施、雅兰、可拉。","notes":[]},{"n":36,"t":"以利法的儿子是提幔、阿抹、洗玻、迦坦、基纳斯、亭纳、亚玛力。","notes":[]},{"n":37,"t":"流珥的儿子是拿哈、谢拉、沙玛、米撒。","notes":[]},{"n":38,"t":"西珥的儿子是罗坍、朔巴、祭便、亚拿、底顺、以察、底珊。","notes":[],"heads":["以东地的原住民"]},{"n":39,"t":"罗坍的儿子是何利、荷幔；罗坍的妹子是亭纳。","notes":[]},{"n":40,"t":"朔巴的儿子是亚勒文、玛拿辖、以巴录、示非、阿南。祭便的儿子是亚雅、亚拿。","notes":[]},{"n":41,"t":"亚拿的儿子是底顺。底顺的儿子是哈默兰、伊是班、益兰、基兰。","notes":[]},{"n":42,"t":"以察的儿子是辟罕、撒番、亚干。底珊的儿子是乌斯、亚兰。","notes":[]},{"n":43,"t":"以色列人未有君王治理之先，在以东地作王的记在下面：有比珥的儿子比拉，他的京城名叫亭哈巴。","notes":[],"heads":["以东诸王"]},{"n":44,"t":"比拉死了，波斯拉人谢拉的儿子约巴接续他作王。","notes":[]},{"n":45,"t":"约巴死了，提幔地的人户珊接续他作王。","notes":[]},{"n":46,"t":"户珊死了，比达的儿子哈达接续他作王。这哈达就是在摩押地杀败米甸人的，他的京城名叫亚未得。","notes":[]},{"n":47,"t":"哈达死了，玛士利加人桑拉接续他作王。","notes":[]},{"n":48,"t":"桑拉死了，大河边的利河伯人扫罗接续他作王。","notes":[]},{"n":49,"t":"扫罗死了，亚革波的儿子巴勒·哈南接续他作王。","notes":[]},{"n":50,"t":"巴勒·哈南死了，哈达接续他作王。他的京城名叫巴伊，他的妻子名叫米希她别，是米·萨合的孙女，玛特列的女儿。","notes":[]},{"n":51,"t":"哈达死了，以东人的族长有亭纳族长、亚勒瓦族长、耶帖族长、","notes":[]},{"n":52,"t":"亚何利巴玛族长、以拉族长、比嫩族长、","notes":[]},{"n":53,"t":"基纳斯族长、提幔族长、米比萨族长、","notes":[]},{"n":54,"t":"玛基叠族长、以兰族长。这都是以东人的族长。","notes":[]}]},"2":{"heading":"犹大的后裔","verses":[{"n":1,"t":"以色列的儿子是吕便、西缅、利未、犹大、以萨迦、西布伦、","notes":[]},{"n":2,"t":"但、约瑟、便雅悯、拿弗他利、迦得、亚设。","notes":[]},{"n":3,"t":"犹大的儿子是珥、俄南、示拉，这三人是迦南人书亚女儿所生的。犹大的长子珥在耶和华眼中看为恶，耶和华就使他死了。","notes":[]},{"n":4,"t":"犹大的儿妇她玛给犹大生法勒斯和谢拉。犹大共有五个儿子。","notes":[]},{"n":5,"t":"法勒斯的儿子是希斯仑、哈母勒。","notes":[]},{"n":6,"t":"谢拉的儿子是心利、以探、希幔、甲各、大拉，共五人。","notes":["就是达大"]},{"n":7,"t":"迦米的儿子是亚干，这亚干在当灭的物上犯了罪，连累了以色列人。","notes":[]},{"n":8,"t":"以探的儿子是亚撒利雅。","notes":[]},{"n":9,"t":"希斯仑所生的儿子是耶拉篾、兰、基路拜。","notes":[],"heads":["大卫王的家谱"]},{"n":10,"t":"兰生亚米拿达；亚米拿达生拿顺。拿顺作犹大人的首领。","notes":[]},{"n":11,"t":"拿顺生撒门；撒门生波阿斯；","notes":[]},{"n":12,"t":"波阿斯生俄备得；俄备得生耶西；","notes":[]},{"n":13,"t":"耶西生长子以利押，次子亚比拿达，三子示米亚，","notes":["示米亚就是沙玛，见撒母耳上十六章九节"]},{"n":14,"t":"四子拿坦业，五子拉代，","notes":[]},{"n":15,"t":"六子阿鲜，七子大卫。","notes":[]},{"n":16,"t":"他们的姊妹是洗鲁雅和亚比该。洗鲁雅的儿子是亚比筛、约押、亚撒黑，共三人。","notes":[]},{"n":17,"t":"亚比该生亚玛撒；亚玛撒的父亲是以实玛利人益帖。","notes":[]},{"n":18,"t":"希斯仑的儿子迦勒娶阿苏巴和耶略为妻，阿苏巴的儿子是耶设、朔罢、押墩。","notes":[],"heads":["希斯仑的后裔"]},{"n":19,"t":"阿苏巴死了，迦勒又娶以法她，生了户珥。","notes":[]},{"n":20,"t":"户珥生乌利；乌利生比撒列。","notes":[]},{"n":21,"t":"希斯仑正六十岁娶了基列父亲玛吉的女儿，与她同房；玛吉的女儿生了西割；","notes":[]},{"n":22,"t":"西割生睚珥。睚珥在基列地有二十三个城邑。","notes":[]},{"n":23,"t":"后来基述人和亚兰人夺了睚珥的城邑，并基纳和其乡村，共六十个。这都是基列父亲玛吉之子的。","notes":[]},{"n":24,"t":"希斯仑在迦勒·以法他死后，他的妻亚比雅给他生了亚施户；亚施户是提哥亚的父亲。","notes":[]},{"n":25,"t":"希斯仑的长子耶拉篾生长子兰，又生布拿、阿连、阿鲜、亚希雅。","notes":[],"heads":["耶拉篾的后裔"]},{"n":26,"t":"耶拉篾又娶一妻名叫亚她拉，是阿南的母亲。","notes":[]},{"n":27,"t":"耶拉篾长子兰的儿子是玛斯、雅悯、以结。","notes":[]},{"n":28,"t":"阿南的儿子是沙买、雅大。沙买的儿子是拿答、亚比述。","notes":[]},{"n":29,"t":"亚比述的妻名叫亚比孩，亚比孩给他生了亚办和摩利。","notes":[]},{"n":30,"t":"拿答的儿子是西列、亚遍；西列死了没有儿子。","notes":[]},{"n":31,"t":"亚遍的儿子是以示；以示的儿子是示珊；示珊的儿子是亚来。","notes":[]},{"n":32,"t":"沙买兄弟雅大的儿子是益帖、约拿单；益帖死了没有儿子。","notes":[]},{"n":33,"t":"约拿单的儿子是比勒、撒萨。这都是耶拉篾的子孙。","notes":[]},{"n":34,"t":"示珊没有儿子，只有女儿。示珊有一个仆人名叫耶哈，是埃及人。","notes":[]},{"n":35,"t":"示珊将女儿给了仆人耶哈为妻，给他生了亚太。","notes":[]},{"n":36,"t":"亚太生拿单；拿单生撒拔；","notes":[]},{"n":37,"t":"撒拔生以弗拉；以弗拉生俄备得；","notes":[]},{"n":38,"t":"俄备得生耶户；耶户生亚撒利雅；","notes":[]},{"n":39,"t":"亚撒利雅生希利斯；希利斯生以利亚萨；","notes":[]},{"n":40,"t":"以利亚萨生西斯买；西斯买生沙龙；","notes":[]},{"n":41,"t":"沙龙生耶加米雅；耶加米雅生以利沙玛。","notes":[]},{"n":42,"t":"耶拉篾兄弟迦勒的长子米沙，是西弗之祖玛利沙的儿子，是希伯仑之祖。","notes":[],"heads":["迦勒的其余后裔"]},{"n":43,"t":"希伯仑的儿子是可拉、他普亚、利肯、示玛。","notes":[]},{"n":44,"t":"示玛生拉含，是约干之祖。利肯生沙买。","notes":[]},{"n":45,"t":"沙买的儿子是玛云；玛云是伯·夙之祖。","notes":[]},{"n":46,"t":"迦勒的妾以法生哈兰、摩撒、迦谢；哈兰生迦卸。（","notes":[]},{"n":47,"t":"雅代的儿子是利健、约坦、基珊、毗力、以法、沙亚弗。）","notes":[]},{"n":48,"t":"迦勒的妾玛迦生示别、特哈拿，","notes":[]},{"n":49,"t":"又生麦玛拿之祖沙亚弗、抹比拿和基比亚之祖示法。迦勒的女儿是押撒。","notes":[]},{"n":50,"t":"迦勒的子孙就是以法她的长子、户珥的儿子，记在下面：基列·耶琳之祖朔巴，","notes":[]},{"n":51,"t":"伯利恒之祖萨玛，伯迦得之祖哈勒。","notes":[]},{"n":52,"t":"基列·耶琳之祖朔巴的子孙是哈罗以和一半米努·哈人。","notes":["米努·哈人就是玛拿哈人"]},{"n":53,"t":"基列·耶琳的诸族是以帖人、布特人、舒玛人、密来人，又从这些族中生出琐拉人和以实陶人来。","notes":[]},{"n":54,"t":"萨玛的子孙是伯利恒人、尼陀法人、亚他绿·伯·约押人、一半玛拿哈人、琐利人，","notes":[]},{"n":55,"t":"和住雅比斯众文士家的特拉人、示米押人、苏甲人。这都是基尼人利甲家之祖哈末所生的。","notes":[]}]},"3":{"heading":"大卫的儿女","verses":[{"n":1,"t":"大卫在希伯仑所生的儿子记在下面：长子暗嫩是耶斯列人亚希暖生的。次子但以利是迦密人亚比该生的。","notes":[]},{"n":2,"t":"三子押沙龙是基述王达买的女儿玛迦生的。四子亚多尼雅是哈及生的。","notes":[]},{"n":3,"t":"五子示法提雅是亚比她生的。六子以特念是大卫的妻以格拉生的。","notes":[]},{"n":4,"t":"这六人都是大卫在希伯仑生的。大卫在希伯仑作王七年零六个月，在耶路撒冷作王三十三年。","notes":[]},{"n":5,"t":"大卫在耶路撒冷所生的儿子是示米亚、朔罢、拿单、所罗门。这四人是亚米利的女儿拔·书亚生的。","notes":[]},{"n":6,"t":"还有益辖、以利沙玛、以利法列、","notes":[]},{"n":7,"t":"挪迦、尼斐、雅非亚、","notes":[]},{"n":8,"t":"以利沙玛、以利雅大、以利法列，共九人。","notes":[]},{"n":9,"t":"这都是大卫的儿子，还有他们的妹子她玛，妃嫔的儿子不在其内。","notes":[]},{"n":10,"t":"所罗门的儿子是罗波安；罗波安的儿子是亚比雅；亚比雅的儿子是亚撒；亚撒的儿子是约沙法；","notes":[],"heads":["所罗门的后裔"]},{"n":11,"t":"约沙法的儿子是约兰；约兰的儿子是亚哈谢；亚哈谢的儿子是约阿施；","notes":[]},{"n":12,"t":"约阿施的儿子是亚玛谢；亚玛谢的儿子是亚撒利雅；亚撒利雅的儿子是约坦；","notes":[]},{"n":13,"t":"约坦的儿子是亚哈斯；亚哈斯的儿子是希西家；希西家的儿子是玛拿西；","notes":[]},{"n":14,"t":"玛拿西的儿子是亚们；亚们的儿子是约西亚；","notes":[]},{"n":15,"t":"约西亚的长子是约哈难，次子是约雅敬，三子是西底家，四子是沙龙。","notes":[]},{"n":16,"t":"约雅敬的儿子是耶哥尼雅和西底家。","notes":[]},{"n":17,"t":"耶哥尼雅被掳。他的儿子是撒拉铁、","notes":[],"heads":["耶哥尼雅的后裔"]},{"n":18,"t":"玛基兰、毗大雅、示拿萨、耶加米、何沙玛、尼大比雅。","notes":[]},{"n":19,"t":"毗大雅的儿子是所罗巴伯、示每。所罗巴伯的儿子是米书兰、哈拿尼雅，他们的妹子名叫示罗密。","notes":[]},{"n":20,"t":"米书兰的儿子是哈舒巴、阿黑、比利家、哈撒底、于沙·希悉，共五人。","notes":[]},{"n":21,"t":"哈拿尼雅的儿子是毗拉提、耶筛亚。还有利法雅的众子，亚珥难的众子，俄巴底亚的众子，示迦尼的众子。","notes":[]},{"n":22,"t":"示迦尼的儿子是示玛雅；示玛雅的儿子是哈突、以甲、巴利亚、尼利雅、沙法，共六人。","notes":[]},{"n":23,"t":"尼利雅的儿子是以利约乃、希西家、亚斯利干，共三人。","notes":[]},{"n":24,"t":"以利约乃的儿子是何大雅、以利亚实、毗莱雅、阿谷、约哈难、第莱雅、阿拿尼，共七人。","notes":[]}]},"4":{"heading":"复记犹大的后裔","verses":[{"n":1,"t":"犹大的儿子是法勒斯、希斯仑、迦米、户珥、朔巴。","notes":[]},{"n":2,"t":"朔巴的儿子利亚雅生雅哈；雅哈生亚户买和拉哈。这是琐拉人的诸族。","notes":[]},{"n":3,"t":"以坦之祖的儿子是耶斯列、伊施玛、伊得巴；他们的妹子名叫哈悉勒玻尼。","notes":[]},{"n":4,"t":"基多之祖是毗努伊勒。户沙之祖是以谢珥。这都是伯利恒之祖以法她的长子户珥所生的。","notes":[]},{"n":5,"t":"提哥亚之祖亚施户有两个妻子：一名希拉，一名拿拉。","notes":[]},{"n":6,"t":"拿拉给亚施户生亚户撒、希弗、提米尼、哈辖斯他利。这都是拿拉的儿子。","notes":[]},{"n":7,"t":"希拉的儿子是洗列、琐辖、伊提南。","notes":[]},{"n":8,"t":"哥斯生亚诺、琐比巴，并哈仑儿子亚哈黑的诸族。","notes":[]},{"n":9,"t":"雅比斯比他众弟兄更尊贵，他母亲给他起名叫雅比斯，意思说：我生他甚是痛苦。","notes":[]},{"n":10,"t":"雅比斯求告以色列的神说：「甚愿你赐福与我，扩张我的境界，常与我同在，保佑我不遭患难，不受艰苦。」神就应允他所求的。","notes":[]},{"n":11,"t":"书哈的弟兄基绿生米黑，米黑是伊施屯之祖。","notes":[],"heads":["其他的家族"]},{"n":12,"t":"伊施屯生伯拉巴、巴西亚，并珥拿辖之祖提欣拿，这都是利迦人。","notes":[]},{"n":13,"t":"基纳斯的儿子是俄陀聂、西莱雅。俄陀聂的儿子是哈塔。","notes":[]},{"n":14,"t":"悯挪太生俄弗拉；西莱雅生革·夏纳欣人之祖约押。他们都是匠人。","notes":[]},{"n":15,"t":"耶孚尼的儿子是迦勒；迦勒的儿子是以路、以拉、拿安。以拉的儿子是基纳斯。","notes":[]},{"n":16,"t":"耶哈利勒的儿子是西弗、西法、提利、亚撒列。","notes":[]},{"n":17,"t":"以斯拉的儿子是益帖、米列、以弗、雅伦。米列娶法老女儿比提雅为妻，生米利暗、沙买，和以实提摩之祖益巴。米列又娶犹大女子为妻，生基多之祖雅列，梭哥之祖希伯，和撒挪亚之祖耶古铁。","notes":[],"end":18},{"n":19,"t":"荷第雅的妻是拿含的妹子，她所生的儿子是迦米人基伊拉和玛迦人以实提摩之祖。","notes":[]},{"n":20,"t":"示门的儿子是暗嫩、林拿、便·哈南、提伦。以示的儿子是梭黑与便·梭黑。","notes":[]},{"n":21,"t":"犹大的儿子是示拉；示拉的儿子是利迦之祖珥，玛利沙之祖拉大，和属亚实比族织细麻布的各家。","notes":[],"heads":["示拉的后裔"]},{"n":22,"t":"还有约敬、哥西巴人、约阿施、萨拉，就是在摩押地掌权的，又有雅叔比利恒。这都是古时所记载的。","notes":[]},{"n":23,"t":"这些人都是窑匠，是尼他应和基低拉的居民；与王同处，为王做工。","notes":[]},{"n":24,"t":"西缅的儿子是尼母利、雅悯、雅立、谢拉、扫罗。","notes":[],"heads":["西缅的后裔"]},{"n":25,"t":"扫罗的儿子是沙龙；沙龙的儿子是米比衫；米比衫的儿子是米施玛；","notes":[]},{"n":26,"t":"米施玛的儿子是哈母利；哈母利的儿子是撒刻；撒刻的儿子是示每。","notes":[]},{"n":27,"t":"示每有十六个儿子，六个女儿，他弟兄的儿女不多，他们各家不如犹大族的人丁增多。","notes":[]},{"n":28,"t":"西缅人住在别是巴、摩拉大、哈萨·书亚、","notes":[]},{"n":29,"t":"辟拉、以森、陀腊、","notes":[]},{"n":30,"t":"彼土利、何珥玛、洗革拉、","notes":[]},{"n":31,"t":"伯·玛嘉博、哈萨·苏撒、伯·比利、沙拉音，这些城邑直到大卫作王的时候都是属西缅人的。","notes":[]},{"n":32,"t":"他们的五个城邑是以坦、亚因、临门、陀健、亚珊；","notes":[]},{"n":33,"t":"还有属城的乡村，直到巴力。这是他们的住处，他们都有家谱。","notes":[]},{"n":34,"t":"还有米所巴、雅米勒、亚玛谢的儿子约沙、","notes":[]},{"n":35,"t":"约珥、约示比的儿子耶户；约示比是西莱雅的儿子；西莱雅是亚薛的儿子。","notes":[]},{"n":36,"t":"还有以利约乃、雅哥巴、约朔海、亚帅雅、亚底业、耶西篾、比拿雅、","notes":[]},{"n":37,"t":"示非的儿子细撒。示非是亚龙的儿子；亚龙是耶大雅的儿子；耶大雅是申利的儿子；申利是示玛雅的儿子。","notes":[]},{"n":38,"t":"以上所记的人名都是作族长的，他们宗族的人数增多。","notes":[]},{"n":39,"t":"他们往平原东边基多口去，寻找牧放羊群的草场，","notes":[]},{"n":40,"t":"寻得肥美的草场地，又宽阔又平静。从前住那里的是含族的人。","notes":[]},{"n":41,"t":"以上录名的人，在犹大王希西家年间，来攻击含族人的帐棚和那里所有的米乌尼人，将他们灭尽，就住在他们的地方，直到今日，因为那里有草场可以牧放羊群。","notes":[]},{"n":42,"t":"这西缅人中，有五百人上西珥山，率领他们的是以示的儿子毗拉提、尼利雅、利法雅，和乌薛，","notes":[]},{"n":43,"t":"杀了逃脱剩下的亚玛力人，就住在那里直到今日。","notes":[]}]},"5":{"heading":"吕便的后裔","verses":[{"n":1,"t":"以色列的长子原是吕便；因他污秽了父亲的床，他长子的名分就归了约瑟。只是按家谱他不算长子。","notes":[]},{"n":2,"t":"犹大胜过一切弟兄，君王也是从他而出；长子的名分却归约瑟。","notes":[]},{"n":3,"t":"以色列长子吕便的儿子是哈诺、法路、希斯伦、迦米。","notes":[]},{"n":4,"t":"约珥的儿子是示玛雅；示玛雅的儿子是歌革；歌革的儿子是示每；","notes":[]},{"n":5,"t":"示每的儿子是米迦；米迦的儿子是利亚雅；利亚雅的儿子是巴力；","notes":[]},{"n":6,"t":"巴力的儿子是备拉。这备拉作吕便支派的首领，被亚述王提革拉·毗列色掳去。","notes":[]},{"n":7,"t":"他的弟兄照着宗族，按着家谱作族长的是耶利、撒迦利雅、比拉。","notes":[]},{"n":8,"t":"比拉是亚撒的儿子；亚撒是示玛的儿子；示玛是约珥的儿子；约珥所住的地方是从亚罗珥直到尼波和巴力·免，","notes":[]},{"n":9,"t":"又向东延到幼发拉底河这边的旷野，因为他们在基列地牲畜增多。","notes":[]},{"n":10,"t":"扫罗年间，他们与夏甲人争战，夏甲人倒在他们手下，他们就在基列东边的全地，住在夏甲人的帐棚里。","notes":[]},{"n":11,"t":"迦得的子孙在吕便对面，住在巴珊地，延到撒迦。","notes":[],"heads":["迦得的后裔"]},{"n":12,"t":"他们中间有作族长的约珥，有作副族长的沙番，还有雅乃和住在巴珊的沙法。","notes":[]},{"n":13,"t":"他们族弟兄是米迦勒、米书兰、示巴、约赖、雅干、细亚、希伯，共七人。","notes":[]},{"n":14,"t":"这都是亚比孩的儿子。亚比孩是户利的儿子；户利是耶罗亚的儿子；耶罗亚是基列的儿子；基列是米迦勒的儿子；米迦勒是耶示筛的儿子；耶示筛是耶哈多的儿子；耶哈多是布斯的儿子。","notes":[]},{"n":15,"t":"还有古尼的孙子、押比叠的儿子亚希。这都是作族长的。","notes":[]},{"n":16,"t":"他们住在基列与巴珊和巴珊的乡村，并沙仑的郊野，直到四围的交界。","notes":[]},{"n":17,"t":"这些人在犹大王约坦并在以色列王耶罗波安年间，都载入家谱。","notes":[]},{"n":18,"t":"吕便人、迦得人，和玛拿西半支派的人，能拿盾牌和刀剑、拉弓射箭、出征善战的勇士共有四万四千七百六十名。","notes":[],"heads":["吕便迦得玛拿西族的军队"]},{"n":19,"t":"他们与夏甲人、伊突人、拿非施人、挪答人争战。","notes":[]},{"n":20,"t":"他们得了神的帮助，夏甲人和跟随夏甲的人都交在他们手中；因为他们在阵上呼求神，倚赖神，神就应允他们。","notes":[]},{"n":21,"t":"他们掳掠了夏甲人的牲畜，有骆驼五万，羊二十五万，驴二千；又有人十万。","notes":[]},{"n":22,"t":"敌人被杀仆倒的甚多，因为这争战是出乎神。他们就住在敌人的地上，直到被掳的时候。","notes":[]},{"n":23,"t":"玛拿西半支派的人住在那地。从巴珊延到巴力·黑们、示尼珥与黑门山。","notes":[],"heads":["玛拿西半支派"]},{"n":24,"t":"他们的族长是以弗、以示、以列、亚斯列、耶利米、何达威雅、雅叠，都是大能的勇士，是有名的人，也是作族长的。","notes":[]},{"n":25,"t":"他们得罪了他们列祖的神，随从那地之民的神行邪淫；这民就是神在他们面前所除灭的。","notes":[],"heads":["二支派半人叛逆神"]},{"n":26,"t":"故此，以色列的神激动亚述王普勒和亚述王提革拉·毗列色的心，他们就把吕便人、迦得人、玛拿西半支派的人掳到哈腊、哈博、哈拉与歌散河边，直到今日还在那里。","notes":[]}]},"6":{"heading":"利未的后裔","verses":[{"n":1,"t":"利未的儿子是革顺、哥辖、米拉利。","notes":[]},{"n":2,"t":"哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛。","notes":[]},{"n":3,"t":"暗兰的儿子是亚伦、摩西，还有女儿米利暗。亚伦的儿子是拿答、亚比户、以利亚撒、以他玛。","notes":[]},{"n":4,"t":"以利亚撒生非尼哈；非尼哈生亚比书；","notes":[]},{"n":5,"t":"亚比书生布基；布基生乌西；","notes":[]},{"n":6,"t":"乌西生西拉希雅；西拉希雅生米拉约；","notes":[]},{"n":7,"t":"米拉约生亚玛利雅；亚玛利雅生亚希突；","notes":[]},{"n":8,"t":"亚希突生撒督；撒督生亚希玛斯；","notes":[]},{"n":9,"t":"亚希玛斯生亚撒利雅；亚撒利雅生约哈难；","notes":[]},{"n":10,"t":"约哈难生亚撒利雅（这亚撒利雅在所罗门于耶路撒冷所建造的殿中，供祭司的职分）；","notes":[]},{"n":11,"t":"亚撒利雅生亚玛利雅；亚玛利雅生亚希突；","notes":[]},{"n":12,"t":"亚希突生撒督；撒督生沙龙；","notes":[]},{"n":13,"t":"沙龙生希勒家；希勒家生亚撒利雅；","notes":[]},{"n":14,"t":"亚撒利雅生西莱雅；西莱雅生约萨答。","notes":[]},{"n":15,"t":"当耶和华借尼布甲尼撒的手掳掠犹大和耶路撒冷人的时候，这约萨答也被掳去。","notes":[]},{"n":16,"t":"利未的儿子是革顺、哥辖、米拉利。","notes":[],"heads":["利未的其余后裔"]},{"n":17,"t":"革顺的儿子名叫立尼、示每。","notes":[]},{"n":18,"t":"哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛。","notes":[]},{"n":19,"t":"米拉利的儿子是抹利、母示。这是按着利未人宗族分的各家。","notes":[]},{"n":20,"t":"革顺的儿子是立尼；立尼的儿子是雅哈；雅哈的儿子是薪玛；","notes":[]},{"n":21,"t":"薪玛的儿子是约亚；约亚的儿子是易多；易多的儿子是谢拉；谢拉的儿子是耶特赖。","notes":[]},{"n":22,"t":"哥辖的儿子是亚米拿达；亚米拿达的儿子是可拉；可拉的儿子是亚惜；","notes":[]},{"n":23,"t":"亚惜的儿子是以利加拿；以利加拿的儿子是以比雅撒；以比雅撒的儿子是亚惜；","notes":[]},{"n":24,"t":"亚惜的儿子是他哈；他哈的儿子是乌列；乌列的儿子是乌西雅；乌西雅的儿子是少罗。","notes":[]},{"n":25,"t":"以利加拿的儿子是亚玛赛和亚希摩。","notes":[]},{"n":26,"t":"亚希摩的儿子是以利加拿；以利加拿的儿子是琐菲；琐菲的儿子是拿哈；","notes":[]},{"n":27,"t":"拿哈的儿子是以利押；以利押的儿子是耶罗罕；耶罗罕的儿子是以利加拿；以利加拿的儿子是撒母耳。","notes":[]},{"n":28,"t":"撒母耳的长子是约珥，次子是亚比亚。","notes":[]},{"n":29,"t":"米拉利的儿子是抹利；抹利的儿子是立尼；立尼的儿子是示每；示每的儿子是乌撒；","notes":[]},{"n":30,"t":"乌撒的儿子是示米亚；示米亚的儿子是哈基雅；哈基雅的儿子是亚帅雅。","notes":[]},{"n":31,"t":"约柜安设之后，大卫派人在耶和华殿中管理歌唱的事。","notes":[],"heads":["圣殿中的歌者"]},{"n":32,"t":"他们就在会幕前当歌唱的差，及至所罗门在耶路撒冷建造了耶和华的殿，他们便按着班次供职。","notes":[]},{"n":33,"t":"供职的人和他们的子孙记在下面：哥辖的子孙中有歌唱的希幔。希幔是约珥的儿子；约珥是撒母耳的儿子；","notes":[]},{"n":34,"t":"撒母耳是以利加拿的儿子；以利加拿是耶罗罕的儿子；耶罗罕是以列的儿子；以列是陀亚的儿子；","notes":[]},{"n":35,"t":"陀亚是苏弗的儿子；苏弗是以利加拿的儿子；以利加拿是玛哈的儿子；玛哈是亚玛赛的儿子；","notes":[]},{"n":36,"t":"亚玛赛是以利加拿的儿子；以利加拿是约珥的儿子；约珥是亚撒利雅的儿子；亚撒利雅是西番雅的儿子；","notes":[]},{"n":37,"t":"西番雅是他哈的儿子；他哈是亚惜的儿子；亚惜是以比雅撒的儿子；以比雅撒是可拉的儿子；","notes":[]},{"n":38,"t":"可拉是以斯哈的儿子；以斯哈是哥辖的儿子；哥辖是利未的儿子；利未是以色列的儿子。","notes":[]},{"n":39,"t":"希幔的族兄亚萨是比利家的儿子，亚萨在希幔右边供职。比利家是示米亚的儿子；","notes":[]},{"n":40,"t":"示米亚是米迦勒的儿子；米迦勒是巴西雅的儿子；巴西雅是玛基雅的儿子；","notes":[]},{"n":41,"t":"玛基雅是伊特尼的儿子；伊特尼是谢拉的儿子；谢拉是亚大雅的儿子；","notes":[]},{"n":42,"t":"亚大雅是以探的儿子；以探是薪玛的儿子；薪玛是示每的儿子；","notes":[]},{"n":43,"t":"示每是雅哈的儿子；雅哈是革顺的儿子。革顺是利未的儿子。","notes":[]},{"n":44,"t":"他们的族弟兄米拉利的子孙，在他们左边供职的有以探。以探是基示的儿子；基示是亚伯底的儿子；亚伯底是玛鹿的儿子；","notes":[]},{"n":45,"t":"玛鹿是哈沙比雅的儿子；哈沙比雅是亚玛谢的儿子；亚玛谢是希勒家的儿子；","notes":[]},{"n":46,"t":"希勒家是暗西的儿子；暗西是巴尼的儿子；巴尼是沙麦的儿子；","notes":[]},{"n":47,"t":"沙麦是末力的儿子；末力是母示的儿子；母示是米拉利的儿子；米拉利是利未的儿子。","notes":[]},{"n":48,"t":"他们的族弟兄利未人也被派办神殿中的一切事。","notes":[]},{"n":49,"t":"亚伦和他的子孙在燔祭坛和香坛上献祭烧香，又在至圣所办理一切的事，为以色列人赎罪，是照神仆人摩西所吩咐的。","notes":[],"heads":["亚伦的后裔"]},{"n":50,"t":"亚伦的儿子是以利亚撒；以利亚撒的儿子是非尼哈；非尼哈的儿子是亚比书；","notes":[]},{"n":51,"t":"亚比书的儿子是布基；布基的儿子是乌西；乌西的儿子是西拉希雅；","notes":[]},{"n":52,"t":"西拉希雅的儿子是米拉约；米拉约的儿子是亚玛利雅；亚玛利雅的儿子是亚希突；","notes":[]},{"n":53,"t":"亚希突的儿子是撒督；撒督的儿子是亚希玛斯。","notes":[]},{"n":54,"t":"他们的住处按着境内的营寨，记在下面：哥辖族亚伦的子孙先拈阄得地，","notes":[],"heads":["利未支派的居地"]},{"n":55,"t":"在犹大地中得了希伯仑和四围的郊野；","notes":[]},{"n":56,"t":"只是属城的田地和村庄都为耶孚尼的儿子迦勒所得。","notes":[]},{"n":57,"t":"亚伦的子孙得了逃城希伯仑，又得了立拿与其郊野，雅提珥、以实提莫与其郊野；","notes":[]},{"n":58,"t":"希仑与其郊野，底璧与其郊野，","notes":[]},{"n":59,"t":"亚珊与其郊野，伯·示麦与其郊野。","notes":[]},{"n":60,"t":"在便雅悯支派的地中，得了迦巴与其郊野，阿勒篾与其郊野，亚拿突与其郊野。他们诸家所得的城共十三座。","notes":[]},{"n":61,"t":"哥辖族其余的人又拈阄，在玛拿西半支派的地中得了十座城。","notes":[]},{"n":62,"t":"革顺族按着宗族，在以萨迦支派的地中，亚设支派的地中，拿弗他利支派的地中，巴珊内玛拿西支派的地中，得了十三座城。","notes":[]},{"n":63,"t":"米拉利族按着宗族拈阄，在吕便支派的地中，迦得支派的地中，西布伦支派的地中，得了十二座城。","notes":[]},{"n":64,"t":"以色列人将这些城与其郊野给了利未人。","notes":[]},{"n":65,"t":"这以上录名的城，在犹大、西缅、便雅悯三支派的地中，以色列人拈阄给了他们。","notes":[]},{"n":66,"t":"哥辖族中有几家在以法莲支派的地中也得了城邑，","notes":[]},{"n":67,"t":"在以法莲山地得了逃城示剑与其郊野，又得了基色与其郊野，","notes":[]},{"n":68,"t":"约缅与其郊野，伯·和仑与其郊野，","notes":[]},{"n":69,"t":"亚雅仑与其郊野，迦特·临门与其郊野。","notes":[]},{"n":70,"t":"哥辖族其余的人在玛拿西半支派的地中得了亚乃与其郊野，比连与其郊野。","notes":[]},{"n":71,"t":"革顺族在玛拿西半支派的地中得了巴珊的哥兰与其郊野，亚斯他录与其郊野；","notes":[]},{"n":72,"t":"又在以萨迦支派的地中得了基低斯与其郊野，大比拉与其郊野，","notes":[]},{"n":73,"t":"拉末与其郊野，亚年与其郊野；","notes":[]},{"n":74,"t":"在亚设支派的地中得了玛沙与其郊野，押顿与其郊野，","notes":[]},{"n":75,"t":"户割与其郊野，利合与其郊野；","notes":[]},{"n":76,"t":"在拿弗他利支派的地中得了加利利的基低斯与其郊野，哈们与其郊野，基列亭与其郊野。","notes":[]},{"n":77,"t":"还有米拉利族的人在西布伦支派的地中得了临摩挪与其郊野，他泊与其郊野；","notes":[]},{"n":78,"t":"又在耶利哥的约旦河东，在吕便支派的地中得了旷野的比悉与其郊野，雅哈撒与其郊野，","notes":[]},{"n":79,"t":"基底莫与其郊野，米法押与其郊野；","notes":[]},{"n":80,"t":"又在迦得支派的地中得了基列的拉末与其郊野，玛哈念与其郊野，","notes":[]},{"n":81,"t":"希实本与其郊野，雅谢与其郊野。","notes":[]}]},"7":{"heading":"以萨迦的后裔","verses":[{"n":1,"t":"以萨迦的儿子是陀拉、普瓦、雅述、伸仑，共四人。","notes":["在创世记第四十六章十三节是约伯"]},{"n":2,"t":"陀拉的儿子是乌西、利法雅、耶勒、雅买、易伯散、示母利，都是陀拉的族长，是大能的勇士。到大卫年间，他们的人数共有二万二千六百名。","notes":[]},{"n":3,"t":"乌西的儿子是伊斯拉希；伊斯拉希的儿子是米迦勒、俄巴底亚、约珥、伊示雅，共五人，都是族长。","notes":[]},{"n":4,"t":"他们所率领的，按着宗族出战的军队，共有三万六千人，因为他们的妻和子众多。","notes":[]},{"n":5,"t":"他们的族弟兄在以萨迦各族中都是大能的勇士，按着家谱计算共有八万七千人。","notes":[]},{"n":6,"t":"便雅悯的儿子是比拉、比结、耶叠，共三人。","notes":[],"heads":["便雅悯和但的后裔"]},{"n":7,"t":"比拉的儿子是以斯本、乌西、乌薛、耶利摩、以利，共五人，都是族长，是大能的勇士。按着家谱计算，他们的子孙共有二万二千零三十四人。","notes":[]},{"n":8,"t":"比结的儿子是细米拉、约阿施、以利以谢、以利约乃、暗利、耶利摩、亚比雅、亚拿突、亚拉篾。这都是比结的儿子。","notes":[]},{"n":9,"t":"他们都是族长，是大能的勇士。按着家谱计算，他们的子孙共有二万零二百人。","notes":[]},{"n":10,"t":"耶叠的儿子是比勒罕；比勒罕的儿子是耶乌施、便雅悯、以忽、基拿拿、细坦、他施、亚希沙哈。","notes":[]},{"n":11,"t":"这都是耶叠的儿子，都是族长，是大能的勇士；他们的子孙能上阵打仗的，共有一万七千二百人。","notes":[]},{"n":12,"t":"还有以珥的儿子书品、户品，并亚黑的儿子户伸。","notes":[]},{"n":13,"t":"拿弗他利的儿子是雅薛、沽尼、耶色、沙龙。这都是辟拉的子孙。","notes":[],"heads":["拿弗他利的后裔"]},{"n":14,"t":"玛拿西的儿子亚斯列是他妾亚兰人所生的，又生了基列之父玛吉。","notes":[],"heads":["玛拿西的后裔"]},{"n":15,"t":"玛吉娶的妻是户品、书品的妹子，名叫玛迦。玛拿西的次子名叫西罗非哈；西罗非哈但有几个女儿。","notes":[]},{"n":16,"t":"玛吉的妻玛迦生了一个儿子，起名叫毗利施。毗利施的兄弟名叫示利施；示利施的儿子是乌兰和利金。","notes":[]},{"n":17,"t":"乌兰的儿子是比但。这都是基列的子孙。基列是玛吉的儿子，玛吉是玛拿西的儿子。","notes":[]},{"n":18,"t":"基列的妹子哈摩利吉生了伊施荷、亚比以谢、玛拉。（","notes":[]},{"n":19,"t":"示米大的儿子是亚现、示剑、利克希、阿尼安。）","notes":[]},{"n":20,"t":"以法莲的儿子是书提拉；书提拉的儿子是比列；比列的儿子是他哈；他哈的儿子是以拉大；以拉大的儿子是他哈；","notes":[],"heads":["以法莲的后裔"]},{"n":21,"t":"他哈的儿子是撒拔；撒拔的儿子是书提拉。以法莲又生以谢、以列；这二人因为下去夺取迦特人的牲畜，被本地的迦特人杀了。","notes":[]},{"n":22,"t":"他们的父亲以法莲为他们悲哀了多日，他的弟兄都来安慰他。","notes":[]},{"n":23,"t":"以法莲与妻同房，他妻就怀孕生了一子，以法莲因为家里遭祸，就给这儿子起名叫比利亚。","notes":[]},{"n":24,"t":"他的女儿名叫舍伊拉，就是建筑上伯·和仑、下伯·和仑与乌羡·舍伊拉的。","notes":[]},{"n":25,"t":"比利阿的儿子是利法和利悉。利悉的儿子是他拉；他拉的儿子是他罕；","notes":[]},{"n":26,"t":"他罕的儿子是拉但；拉但的儿子是亚米忽；亚米忽的儿子是以利沙玛；","notes":[]},{"n":27,"t":"以利沙玛的儿子是嫩；嫩的儿子是约书亚。","notes":[]},{"n":28,"t":"以法莲人的地业和住处是伯特利与其村庄；东边拿兰，西边基色与其村庄；示剑与其村庄，直到迦萨与其村庄；","notes":[]},{"n":29,"t":"还有靠近玛拿西人的境界，伯·善与其村庄；他纳与其村庄；米吉多与其村庄；多珥与其村庄。以色列儿子约瑟的子孙住在这些地方。","notes":[]},{"n":30,"t":"亚设的儿子是音拿、亦施瓦、亦施韦、比利亚，还有他们的妹子西 拉。","notes":[],"heads":["亚设的后裔"]},{"n":31,"t":"比利亚的儿子是希别、玛结；玛结是比撒威的父亲。","notes":[]},{"n":32,"t":"希别生雅弗勒、朔默、何坦，和他们的妹子书雅。","notes":[]},{"n":33,"t":"雅弗勒的儿子是巴萨、宾哈、亚施法。这都是雅弗勒的儿子。","notes":[]},{"n":34,"t":"朔默的儿子是亚希、罗迦、耶户巴、亚兰。","notes":[]},{"n":35,"t":"朔默兄弟希连的儿子是琐法、音那、示利斯、亚抹。","notes":[]},{"n":36,"t":"琐法的儿子是书亚、哈尼弗、书阿勒、比利、音拉、","notes":[]},{"n":37,"t":"比悉、河得、珊玛、施沙、益兰、比拉。","notes":[]},{"n":38,"t":"益帖的儿子是耶孚尼、毗斯巴、亚拉。","notes":[]},{"n":39,"t":"乌拉的儿子是亚拉、汉尼业、利写。","notes":[]},{"n":40,"t":"这都是亚设的子孙，都是族长，是精壮大能的勇士，也是首领中的头目，按着家谱计算，他们的子孙能出战的共有二万六千人。","notes":[]}]},"8":{"heading":"便雅悯的后裔","verses":[{"n":1,"t":"便雅悯的长子比拉，次子亚实别，三子亚哈拉，","notes":[]},{"n":2,"t":"四子挪哈，五子拉法。","notes":[]},{"n":3,"t":"比拉的儿子是亚大、基拉、亚比忽、","notes":[]},{"n":4,"t":"亚比书、乃幔、亚何亚、","notes":[]},{"n":5,"t":"基拉、示孚汛、户兰。","notes":[]},{"n":6,"t":"以忽的儿子作迦巴居民的族长，被掳到玛拿辖；","notes":[]},{"n":7,"t":"以忽的儿子乃幔、亚希亚、基拉也被掳去。基拉生乌撒、亚希忽。","notes":[]},{"n":8,"t":"沙哈连休他二妻户伸和巴拉之后，在摩押地生了儿子。","notes":[]},{"n":9,"t":"他与妻贺得同房，生了约巴、洗比雅、米沙、玛拉干、","notes":[]},{"n":10,"t":"耶乌斯、沙迦、米玛。他这些儿子都是族长。","notes":[]},{"n":11,"t":"他的妻户伸给他生的儿子有亚比突、以利巴力。","notes":[]},{"n":12,"t":"以利巴力的儿子是希伯、米珊、沙麦。沙麦建立阿挪和罗德二城与其村庄。","notes":[]},{"n":13,"t":"又有比利亚和示玛是亚雅仑居民的族长，是驱逐迦特人的。","notes":[],"heads":["在亚雅仑的便雅悯人"]},{"n":14,"t":"亚希约、沙煞、耶利末、","notes":[]},{"n":15,"t":"西巴第雅、亚拉得、亚得、","notes":[]},{"n":16,"t":"米迦勒、伊施巴、约哈都是比利亚的儿子。","notes":[]},{"n":17,"t":"西巴第雅、米书兰、希西基、希伯、","notes":[],"heads":["在耶路撒冷的便雅悯人"]},{"n":18,"t":"伊施米莱、伊斯利亚、约巴都是以利巴力的儿子。","notes":[]},{"n":19,"t":"雅金、细基 利、撒底、","notes":[]},{"n":20,"t":"以利乃、洗勒太、以列、","notes":[]},{"n":21,"t":"亚大雅、比拉雅、申拉都是示每的儿子。","notes":[]},{"n":22,"t":"伊施班、希伯、以列、","notes":[]},{"n":23,"t":"亚伯顿、细基利、哈难、","notes":[]},{"n":24,"t":"哈拿尼雅、以拦、安陀提雅、","notes":[]},{"n":25,"t":"伊弗底雅、毗努伊勒都是沙煞的儿子。","notes":[]},{"n":26,"t":"珊示莱、示哈利、亚他利雅、","notes":[]},{"n":27,"t":"雅利西、以利亚、细基利都是耶罗罕的儿子。","notes":[]},{"n":28,"t":"这些人都是著名的族长，住在耶路撒冷。","notes":[]},{"n":29,"t":"在基遍住的有基遍的父亲耶利。他的妻名叫玛迦；","notes":[],"heads":["在基遍和耶路撒冷的便雅悯人"]},{"n":30,"t":"他长子是亚伯顿。他又生苏珥、基士、巴力、拿答、","notes":[]},{"n":31,"t":"基多、亚希约、撒迦、米基罗。","notes":[]},{"n":32,"t":"米基罗生示米暗。这些人和他们的弟兄在耶路撒冷对面居住。","notes":[]},{"n":33,"t":"尼珥生基士；基士生扫罗；扫罗生约拿单、麦基舒亚、亚比拿达、伊施·巴力。","notes":[],"heads":["扫罗王的家族"]},{"n":34,"t":"约拿单的儿子是米力·巴力；米力·巴力生米迦。","notes":["在撒母耳下四章四节是米非波设"]},{"n":35,"t":"米迦的儿子是毗敦、米勒、他利亚、亚哈斯；","notes":[]},{"n":36,"t":"亚哈斯生耶何阿达；耶何阿达生亚拉篾、亚斯玛威、心利；心利生摩撒；","notes":[]},{"n":37,"t":"摩撒生比尼亚；比尼亚的儿子是拉法；拉法的儿子是以利亚萨；以利亚萨的儿子是亚悉。","notes":[]},{"n":38,"t":"亚悉有六个儿子，他们的名字是亚斯利干、波基路、以实玛利、示亚利雅、俄巴底雅、哈难。这都是亚悉的儿子。","notes":[]},{"n":39,"t":"亚悉兄弟以设的长子是乌兰，次子耶乌施，三子是以利法列。","notes":[]},{"n":40,"t":"乌兰的儿子都是大能的勇士，是弓箭手，他们有许多的子孙，共一百五十名，都是便雅悯人。","notes":[]}]},"9":{"heading":"被掳归回的人","verses":[{"n":1,"t":"以色列人都按家谱计算，写在以色列诸王记上。犹大人因犯罪就被掳到巴比伦。","notes":[]},{"n":2,"t":"先从巴比伦回来，住在自己地业城邑中的有以色列人、祭司、利未人、尼提宁的首领。","notes":[]},{"n":3,"t":"住在耶路撒冷的有犹大人、便雅悯人、以法莲人、玛拿西人。","notes":[]},{"n":4,"t":"犹大儿子法勒斯的子孙中有乌太。乌太是亚米忽的儿子；亚米忽是暗利的儿子；暗利是音利的儿子；音利是巴尼的儿子。","notes":[]},{"n":5,"t":"示罗的子孙中有长子亚帅雅和他的众子。","notes":[]},{"n":6,"t":"谢拉的子孙中有耶乌利和他的弟兄，共六百九十人。","notes":[]},{"n":7,"t":"便雅悯人中有哈西努的曾孙、何达威雅的孙子、米书兰的儿子撒路，","notes":[]},{"n":8,"t":"又有耶罗罕的儿子伊比尼雅，米基立的孙子、乌西的儿子以拉，伊比尼雅的曾孙、流珥的孙子、示法提雅的儿子米书兰，","notes":[]},{"n":9,"t":"和他们的族弟兄，按着家谱计算共有九百五十六名。这些人都是他们的族长。","notes":[]},{"n":10,"t":"祭司中有耶大雅、耶何雅立、雅斤，","notes":[],"heads":["住在耶路撒冷的祭司"]},{"n":11,"t":"还有管理神殿希勒家的儿子亚萨利雅。希勒家是米书兰的儿子；米书兰是撒督的儿子；撒督是米拉约的儿子；米拉约是亚希突的儿子。","notes":[]},{"n":12,"t":"有玛基雅的曾孙、巴施户珥的孙子、耶罗罕的儿子亚大雅，又有亚第业的儿子玛赛；亚第业是雅希细拉的儿子；雅希细拉是米书兰的儿子；米书兰是米实利密的儿子；米实利密是音麦的儿子。","notes":[]},{"n":13,"t":"他们和众弟兄都是族长，共有一千七百六十人，是善于做神殿使用之工的。","notes":[]},{"n":14,"t":"利未人米拉利的子孙中，有哈沙比雅的曾孙、押利甘的孙子、哈述的儿子示玛雅。","notes":[],"heads":["住在耶路撒冷的利未人"]},{"n":15,"t":"有拔巴甲、黑勒施、迦拉，并亚萨的曾孙、细基利的孙子、米迦的儿子玛探雅，","notes":[]},{"n":16,"t":"又有耶杜顿的曾孙、迦拉的孙子、示玛雅的儿子俄巴底，还有以利加拿的孙子、亚撒的儿子比利家。他们都住在尼陀法人的村庄。","notes":[]},{"n":17,"t":"守门的是沙龙、亚谷、达们、亚希幔，和他们的弟兄；沙龙为长。","notes":[],"heads":["住在耶路撒冷的圣殿守卫"]},{"n":18,"t":"从前这些人看守朝东的王门，如今是利未营中守门的。","notes":[]},{"n":19,"t":"可拉的曾孙、以比雅撒的孙子、可利的儿子沙龙，和他的族弟兄可拉人都管理使用之工，并守会幕的门。他们的祖宗曾管理耶和华的营盘，又把守营门。","notes":[]},{"n":20,"t":"从前以利亚撒的儿子非尼哈管理他们，耶和华也与他同在。","notes":[]},{"n":21,"t":"米施利米雅的儿子撒迦利雅是看守会幕之门的。","notes":[]},{"n":22,"t":"被选守门的人共有二百一十二名。他们在自己的村庄，按着家谱计算，是大卫和先见撒母耳所派当这紧要职任的。","notes":[]},{"n":23,"t":"他们和他们的子孙按着班次看守耶和华殿的门，就是会幕的门。","notes":[]},{"n":24,"t":"在东西南北，四方都有守门的。","notes":[]},{"n":25,"t":"他们的族弟兄住在村庄，每七日来与他们换班。","notes":[]},{"n":26,"t":"这四个门领都是利未人，各有紧要的职任，看守神殿的仓库。","notes":[]},{"n":27,"t":"他们住在神殿的四围，是因委托他们守殿，要每日早晨开门。","notes":[]},{"n":28,"t":"利未人中有管理使用器皿的，按着数目拿出拿入；","notes":[],"heads":["其余的利未人"]},{"n":29,"t":"又有人管理器具和圣所的器皿，并细面、酒、油、乳香、香料。","notes":[]},{"n":30,"t":"祭司中有人用香料做膏油。","notes":[]},{"n":31,"t":"利未人玛他提雅是可拉族沙龙的长子，他紧要的职任是管理盘中烤的物。","notes":[]},{"n":32,"t":"他们族弟兄哥辖子孙中，有管理陈设饼的，每安息日预备摆列。","notes":[]},{"n":33,"t":"歌唱的有利未人的族长，住在属殿的房屋，昼夜供职，不做别样的工。","notes":[]},{"n":34,"t":"以上都是利未人著名的族长，住在耶路撒冷。","notes":[]},{"n":35,"t":"在基遍住的有基遍的父亲耶利。他的妻名叫玛迦；","notes":[],"heads":["扫罗王的祖先和后代"]},{"n":36,"t":"他长子是亚伯顿。他又生苏珥、基士、巴力、尼珥、拿答、","notes":[]},{"n":37,"t":"基多、亚希约、撒迦利雅、米基罗。","notes":[]},{"n":38,"t":"米基罗生示米暗。这些人和他们的弟兄在耶路撒冷对面居住。","notes":[]},{"n":39,"t":"尼珥生基士；基士生扫罗；扫罗生约拿单、麦基舒亚、亚比拿达、伊施·巴力。","notes":[]},{"n":40,"t":"约拿单的儿子是米力·巴力；米力·巴力生米迦。","notes":["就是米非波设"]},{"n":41,"t":"米迦的儿子是毗敦、米勒、他利亚、亚哈斯。","notes":[]},{"n":42,"t":"亚哈斯生雅拉；雅拉生亚拉篾、亚斯玛威、心利；心利生摩撒；","notes":[]},{"n":43,"t":"摩撒生比尼亚；比尼亚生利法雅；利法雅的儿子是以利亚萨；以利亚萨的儿子是亚悉。","notes":[]},{"n":44,"t":"亚悉有六个儿子，他们的名字是亚斯利干、波基路、以实玛利、示亚利雅、俄巴底雅、哈难。这都是亚悉的儿子。","notes":[]}]},"10":{"heading":"扫罗逝世","verses":[{"n":1,"t":"非利士人与以色列人争战，以色列人在非利士人面前逃跑，在基利波山有被杀仆倒的。","notes":[]},{"n":2,"t":"非利士人紧追扫罗和他儿子们，就杀了扫罗的儿子约拿单、亚比拿达、麦基舒亚。","notes":[]},{"n":3,"t":"势派甚大，扫罗被弓箭手追上，射伤甚重，","notes":[]},{"n":4,"t":"就吩咐拿他兵器的人说：「你拔出刀来，将我刺死，免得那些未受割礼的人来凌辱我。」但拿兵器的人甚惧怕，不肯刺他；","notes":[]},{"n":5,"t":"扫罗就自己伏在刀上死了。拿兵器的人见扫罗已死，也伏在刀上死了。","notes":[]},{"n":6,"t":"这样，扫罗和他三个儿子，并他的全家都一同死亡。","notes":[]},{"n":7,"t":"住平原的以色列众人见以色列军兵逃跑，扫罗和他儿子都死了，也就弃城逃跑，非利士人便来住在其中。","notes":[]},{"n":8,"t":"次日，非利士人来剥那被杀之人的衣服，看见扫罗和他儿子仆倒在基利波山，","notes":[]},{"n":9,"t":"就剥了他的军装，割下他的首级，打发人到非利士地的四境报信与他们的偶像和众民，","notes":["到：或译送到"]},{"n":10,"t":"又将扫罗的军装放在他们神的庙里，将他的首级钉在大衮庙中。","notes":[]},{"n":11,"t":"基列·雅比人听见非利士人向扫罗所行的一切事，","notes":[]},{"n":12,"t":"他们中间所有的勇士就起身前去，将扫罗和他儿子的尸身送到雅比，将他们的尸骨葬在雅比的橡树下，就禁食七日。","notes":[]},{"n":13,"t":"这样，扫罗死了。因为他干犯耶和华，没有遵守耶和华的命；又因他求问交鬼的妇人，","notes":[]},{"n":14,"t":"没有求问耶和华，所以耶和华使他被杀，把国归于耶西的儿子大卫。","notes":[]}]},"11":{"heading":"大卫作以色列和犹大的王","verses":[{"n":1,"t":"以色列众人聚集到希伯仑见大卫，说：「我们原是你的骨肉。","notes":[]},{"n":2,"t":"从前扫罗作王的时候，率领以色列人出入的是你；耶和华—你的神也曾应许你说：『你必牧养我的民以色列，作以色列的君。』」","notes":[]},{"n":3,"t":"于是以色列的长老都来到希伯仑见大卫王。大卫在希伯仑耶和华面前与他们立约，他们就膏大卫作以色列的王，是照耶和华借撒母耳所说的话。","notes":[]},{"n":4,"t":"大卫和以色列众人到了耶路撒冷，就是耶布斯；那时耶布斯人住在那里。","notes":[]},{"n":5,"t":"耶布斯人对大卫说：「你决不能进这地方。」然而大卫攻取锡安的保障，就是大卫的城。","notes":[]},{"n":6,"t":"大卫说：「谁先攻打耶布斯人，必作首领元帅。」洗鲁雅的儿子约押先上去，就作了元帅。","notes":[]},{"n":7,"t":"大卫住在保障里，所以那保障叫作大卫城。","notes":[]},{"n":8,"t":"大卫又从米罗起，四围建筑城墙，其余的是约押修理。","notes":[]},{"n":9,"t":"大卫日见强盛，因为万军之耶和华与他同在。","notes":[]},{"n":10,"t":"以下记录跟随大卫勇士的首领，就是奋勇帮助他得国、照着耶和华吩咐以色列人的话、与以色列人一同立他作王的。","notes":[],"heads":["大卫的有名将领"]},{"n":11,"t":"大卫勇士的数目记在下面：哈革摩尼的儿子雅朔班，他是军长的统领，一时举枪杀了三百人。","notes":[]},{"n":12,"t":"其次是亚合人朵多的儿子以利亚撒，他是三个勇士里的一个。","notes":[]},{"n":13,"t":"他从前与大卫在巴斯·达闵，非利士人聚集要打仗。那里有一块长满大麦的田，众民就在非利士人面前逃跑；","notes":[]},{"n":14,"t":"这勇士便站在那田间击杀非利士人，救护了那田。耶和华使以色列人大获全胜。","notes":[]},{"n":15,"t":"三十个勇士中的三个人下到磐石那里，进了亚杜兰洞见大卫；非利士的军队在利乏音谷安营。","notes":[]},{"n":16,"t":"那时大卫在山寨，非利士人的防营在伯利恒。","notes":[]},{"n":17,"t":"大卫渴想，说：「甚愿有人将伯利恒城门旁井里的水打来给我喝！」","notes":[]},{"n":18,"t":"这三个勇士就闯过非利士人的营盘，从伯利恒城门旁的井里打水，拿来奉给大卫。他却不肯喝，将水奠在耶和华面前，","notes":[]},{"n":19,"t":"说：「我的神啊，这三个人冒死去打水，这水好像他们的血一般，我断不敢喝！」如此，大卫不肯喝。这是三个勇士所做的事。","notes":[]},{"n":20,"t":"约押的兄弟亚比筛是这三个勇士的首领；他举枪杀了三百人，就在三个勇士里得了名。","notes":[]},{"n":21,"t":"他在这三个勇士里是最尊贵的，所以作他们的首领；只是不及前三个勇士。","notes":[]},{"n":22,"t":"有甲薛勇士耶何耶大的儿子比拿雅行过大能的事：他杀了摩押人亚利伊勒的两个儿子，又在下雪的时候下坑里去杀了一个狮子，","notes":[]},{"n":23,"t":"又杀了一个埃及人。埃及人身高五肘，手里拿着枪，枪杆粗如织布的机轴；比拿雅只拿着棍子下去，从埃及人手里夺过枪来，用那枪将他刺死。","notes":[]},{"n":24,"t":"这是耶何耶大的儿子比拿雅所行的事，就在三个勇士里得了名。","notes":[]},{"n":25,"t":"他比那三十个勇士都尊贵，只是不及前三个勇士。大卫立他作护卫长。","notes":[]},{"n":26,"t":"军中的勇士有约押的兄弟亚撒黑，伯利恒人朵多的儿子伊勒哈难，","notes":[]},{"n":27,"t":"哈律人沙玛，比伦人希利斯，","notes":[]},{"n":28,"t":"提哥亚人益吉的儿子以拉，亚拿突人亚比以谢，","notes":[]},{"n":29,"t":"户沙人西比该，亚合人以来，","notes":[]},{"n":30,"t":"尼陀法人玛哈莱，尼陀法人巴拿的儿子希立，","notes":[]},{"n":31,"t":"便雅悯族基比亚人利拜的儿子以太，比拉顿人比拿雅，","notes":[]},{"n":32,"t":"迦实溪人户莱，亚拉巴人亚比，","notes":[]},{"n":33,"t":"巴路米人押斯玛弗，沙本人以利雅哈巴，","notes":[]},{"n":34,"t":"基孙人哈深的众子，哈拉人沙基的儿子约拿单，","notes":[]},{"n":35,"t":"哈拉人沙甲的儿子亚希暗，吾珥的儿子以利法勒，","notes":[]},{"n":36,"t":"米基拉人希弗，比伦人亚希雅，","notes":[]},{"n":37,"t":"迦密人希斯罗，伊斯拜的儿子拿莱，","notes":[]},{"n":38,"t":"拿单的兄弟约珥，哈基利的儿子弥伯哈，","notes":[]},{"n":39,"t":"亚扪人洗勒，比录人拿哈莱（拿哈莱是给洗鲁雅的儿子约押拿兵器的），","notes":[]},{"n":40,"t":"以帖人以拉，以帖人迦立，","notes":[]},{"n":41,"t":"赫人乌利亚，亚莱的儿子撒拔，","notes":[]},{"n":42,"t":"吕便人示撒的儿子亚第拿（他是吕便支派中的一个族长，率领三十人），","notes":[]},{"n":43,"t":"玛迦的儿子哈难，弥特尼人约沙法，","notes":[]},{"n":44,"t":"亚施他拉人乌西亚，亚罗珥人何坦的儿子沙玛、耶利，","notes":[]},{"n":45,"t":"提洗人申利的儿子耶叠和他的兄弟约哈，","notes":[]},{"n":46,"t":"玛哈未人以利业，伊利拿安的儿子耶利拜、约沙未雅，摩押人伊特玛、","notes":[]},{"n":47,"t":"以利业、俄备得，并米琐八人雅西业。","notes":[]}]},"12":{"heading":"早期跟随大卫的便雅悯人","verses":[{"n":1,"t":"大卫因怕基士的儿子扫罗，躲在洗革拉的时候，有勇士到他那里帮助他打仗。","notes":[]},{"n":2,"t":"他们善于拉弓，能用左右两手甩石射箭，都是便雅悯人扫罗的族弟兄。","notes":[]},{"n":3,"t":"为首的是亚希以谢，其次是约阿施，都是基比亚人示玛的儿子。还有亚斯玛威的儿子耶薛和毗力，又有比拉迦，并亚拿突人耶户，","notes":[]},{"n":4,"t":"基遍人以实买雅（他在三十人中是勇士，管理他们），且有耶利米、雅哈悉、约哈难，和基得拉人约撒拔、","notes":[]},{"n":5,"t":"伊利乌赛、耶利摩、比亚利雅、示玛利雅，哈律弗人示法提雅，","notes":[]},{"n":6,"t":"可拉人以利加拿、耶西亚、亚萨列、约以谢、雅朔班，","notes":[]},{"n":7,"t":"基多人耶罗罕的儿子犹拉和西巴第雅。","notes":[]},{"n":8,"t":"迦得支派中有人到旷野的山寨投奔大卫，都是大能的勇士，能拿盾牌和枪的战士。他们的面貌好像狮子，快跑如同山上的鹿。","notes":[],"heads":["跟随大卫的迦得人"]},{"n":9,"t":"第一以薛，第二俄巴底雅，第三以利押，","notes":[]},{"n":10,"t":"第四弥施玛拿，第五耶利米，","notes":[]},{"n":11,"t":"第六亚太，第七以利业，","notes":[]},{"n":12,"t":"第八约哈难，第九以利萨巴，","notes":[]},{"n":13,"t":"第十耶利米，第十一末巴奈。","notes":[]},{"n":14,"t":"这都是迦得人中的军长，至小的能抵一百人，至大的能抵一千人。","notes":[]},{"n":15,"t":"正月，约旦河水涨过两岸的时候，他们过河，使一切住平原的人东奔西逃。","notes":[]},{"n":16,"t":"又有便雅悯和犹大人到山寨大卫那里。","notes":[],"heads":["跟随大卫的便雅悯人和犹大人"]},{"n":17,"t":"大卫出去迎接他们，对他们说：「你们若是和和平平地来帮助我，我心就与你们相契；你们若是将我这无罪的人卖在敌人手里，愿我们列祖的神察看责罚。」","notes":[]},{"n":18,"t":"那时神的灵感动那三十个勇士的首领亚玛撒，他就说：大卫啊，我们是归于你的！耶西的儿子啊，我们是帮助你的！愿你平平安安，愿帮助你的也都平安！因为你的神帮助你。大卫就收留他们，立他们作军长。","notes":[]},{"n":19,"t":"大卫从前与非利士人同去，要与扫罗争战，有些玛拿西人来投奔大卫，他们却没有帮助非利士人；因为非利士人的首领商议，打发他们回去，说：「恐怕大卫拿我们的首级，归降他的主人扫罗。」","notes":[],"heads":["跟随大卫的玛拿西人"]},{"n":20,"t":"大卫往洗革拉去的时候，有玛拿西人的千夫长押拿、约撒拔、耶叠、米迦勒、约撒拔、以利户、洗勒太都来投奔他。","notes":[]},{"n":21,"t":"这些人帮助大卫攻击群贼；他们都是大能的勇士，且作军长。","notes":[]},{"n":22,"t":"那时天天有人来帮助大卫，以致成了大军，如神的军一样。","notes":[]},{"n":23,"t":"预备打仗的兵来到希伯仑见大卫，要照着耶和华的话将扫罗的国位归与大卫。他们的数目如下：","notes":[],"heads":["大卫的军力"]},{"n":24,"t":"犹大支派，拿盾牌和枪预备打仗的有六千八百人。","notes":[]},{"n":25,"t":"西缅支派，能上阵大能的勇士有七千一百人。","notes":[]},{"n":26,"t":"利未支派有四千六百人。","notes":[]},{"n":27,"t":"耶何耶大是亚伦家的首领，跟从他的有三千七百人。","notes":[]},{"n":28,"t":"还有少年大能的勇士撒督，同着他的有族长二十二人。","notes":[]},{"n":29,"t":"便雅悯支派，扫罗的族弟兄也有三千人，他们向来大半归顺扫罗家。","notes":[]},{"n":30,"t":"以法莲支派大能的勇士，在本族著名的有二万零八百人。","notes":[]},{"n":31,"t":"玛拿西半支派，册上有名的共一万八千人，都来立大卫作王。","notes":[]},{"n":32,"t":"以萨迦支派，有二百族长都通达时务，知道以色列人所当行的；他们族弟兄都听从他们的命令。","notes":[]},{"n":33,"t":"西布伦支派，能上阵用各样兵器打仗、行伍整齐、不生二心的有五万人。","notes":[]},{"n":34,"t":"拿弗他利支派，有一千军长；跟从他们、拿盾牌和枪的有三万七千人。","notes":[]},{"n":35,"t":"但支派，能摆阵的有二万八千六百人。","notes":[]},{"n":36,"t":"亚设支派，能上阵打仗的有四万人。","notes":[]},{"n":37,"t":"约旦河东的吕便支派、迦得支派、玛拿西半支派，拿着各样兵器打仗的有十二万人。","notes":[]},{"n":38,"t":"以上都是能守行伍的战士，他们都诚心来到希伯仑，要立大卫作以色列的王。以色列其余的人也都一心要立大卫作王。","notes":[]},{"n":39,"t":"他们在那里三日，与大卫一同吃喝，因为他们的族弟兄给他们预备了。","notes":[]},{"n":40,"t":"靠近他们的人以及以萨迦、西布伦、拿弗他利人将许多面饼、无花果饼、干葡萄、酒、油，用驴、骆驼、骡子、牛驮来，又带了许多的牛和羊来，因为以色列人甚是欢乐。","notes":[]}]},"13":{"heading":"约柜迁出基列·耶琳","verses":[{"n":1,"t":"大卫与千夫长、百夫长，就是一切首领商议。","notes":[]},{"n":2,"t":"大卫对以色列全会众说：「你们若以为美，见这事是出于耶和华—我们的神，我们就差遣人走遍以色列地，见我们未来的弟兄，又见住在有郊野之城的祭司利未人，使他们都到这里来聚集。","notes":[]},{"n":3,"t":"我们要把神的约柜运到我们这里来；因为在扫罗年间，我们没有在约柜前求问神。」","notes":[]},{"n":4,"t":"全会众都说可以如此行；这事在众民眼中都看为好。","notes":[]},{"n":5,"t":"于是，大卫将以色列人从埃及的西曷河直到哈马口都招聚了来，要从基列·耶琳将神的约柜运来。","notes":[]},{"n":6,"t":"大卫率领以色列众人上到巴拉，就是属犹大的基列·耶琳，要从那里将约柜运来。这约柜就是坐在二基路伯上耶和华神留名的约柜。","notes":[]},{"n":7,"t":"他们将神的约柜从亚比拿达的家里抬出来，放在新车上。乌撒和亚希约赶车。","notes":[]},{"n":8,"t":"大卫和以色列众人在神前用琴、瑟、锣、鼓、号作乐，极力跳舞歌唱。","notes":[]},{"n":9,"t":"到了基顿的禾场；因为牛失前蹄，乌撒就伸手扶住约柜。","notes":["在撒母耳下六章六节是拿艮","或译：惊跳"]},{"n":10,"t":"耶和华向他发怒，因他伸手扶住约柜击杀他，他就死在神面前。","notes":[]},{"n":11,"t":"大卫因耶和华击杀乌撒，心里愁烦，就称那地方为毗列斯·乌撒，直到今日。","notes":["原文是闯杀"]},{"n":12,"t":"那日，大卫惧怕神，说：「神的约柜怎可运到我这里来？」","notes":[]},{"n":13,"t":"于是大卫不将约柜运进大卫的城，却运到迦特人俄别·以东的家中。","notes":[]},{"n":14,"t":"神的约柜在俄别·以东家中三个月，耶和华赐福给俄别·以东的家和他一切所有的。","notes":[]}]},"14":{"heading":"大卫在耶路撒冷的活动","verses":[{"n":1,"t":"泰尔王希兰将香柏木运到大卫那里，又差遣使者和石匠、木匠给大卫建造宫殿。","notes":[]},{"n":2,"t":"大卫就知道耶和华坚立他作以色列王，又为自己的民以色列，使他的国兴旺。","notes":[]},{"n":3,"t":"大卫在耶路撒冷又立后妃，又生儿女。","notes":[]},{"n":4,"t":"在耶路撒冷所生的众子是沙母亚、朔罢、拿单、所罗门、","notes":[]},{"n":5,"t":"益辖、以利书亚、以法列、","notes":[]},{"n":6,"t":"挪迦、尼斐、雅非亚、","notes":[]},{"n":7,"t":"以利沙玛、比利雅大、以利法列。","notes":[]},{"n":8,"t":"非利士人听见大卫受膏作以色列众人的王，非利士众人就上来寻索大卫。大卫听见，就出去迎敌。","notes":[],"heads":["战胜非利士人"]},{"n":9,"t":"非利士人来了，布散在利乏音谷。","notes":[]},{"n":10,"t":"大卫求问神，说：「我可以上去攻打非利士人吗？你将他们交在我手里吗？」耶和华说：「你可以上去，我必将他们交在你手里。」","notes":[]},{"n":11,"t":"非利士人来到巴力·毗拉心，大卫在那里杀败他们。大卫说：「神借我的手冲破敌人，如同水冲去一般」；因此称那地方为巴力·毗拉心。","notes":[]},{"n":12,"t":"非利士人将神像撇在那里，大卫吩咐人用火焚烧了。","notes":[]},{"n":13,"t":"非利士人又布散在利乏音谷。","notes":[]},{"n":14,"t":"大卫又求问神。神说：「不要一直地上去，要转到他们后头，从桑林对面攻打他们。","notes":[]},{"n":15,"t":"你听见桑树梢上有脚步的声音，就要出战，因为神已经在你前头去攻打非利士人的军队。」","notes":[]},{"n":16,"t":"大卫就遵着神所吩咐的，攻打非利士人的军队，从基遍直到基色。","notes":[]},{"n":17,"t":"于是大卫的名传扬到列国，耶和华使列国都惧怕他。","notes":[]}]},"15":{"heading":"准备搬运约柜","verses":[{"n":1,"t":"大卫在大卫城为自己建造宫殿，又为神的约柜预备地方，支搭帐幕。","notes":[]},{"n":2,"t":"那时大卫说：「除了利未人之外，无人可抬神的约柜；因为耶和华拣选他们抬神的约柜，且永远事奉他。」","notes":[]},{"n":3,"t":"大卫招聚以色列众人到耶路撒冷，要将耶和华的约柜抬到他所预备的地方。","notes":[]},{"n":4,"t":"大卫又聚集亚伦的子孙和利未人。","notes":[]},{"n":5,"t":"哥辖子孙中有族长乌列和他的弟兄一百二十人。","notes":[]},{"n":6,"t":"米拉利子孙中有族长亚帅雅和他的弟兄二百二十人。","notes":[]},{"n":7,"t":"革顺子孙中有族长约珥和他的弟兄一百三十人。","notes":[]},{"n":8,"t":"以利撒反子孙中有族长示玛雅和他的弟兄二百人。","notes":[]},{"n":9,"t":"希伯仑子孙中有族长以列和他的弟兄八十人。","notes":[]},{"n":10,"t":"乌薛子孙中有族长亚米拿达和他的弟兄一百一十二人。","notes":[]},{"n":11,"t":"大卫将祭司撒督和亚比亚他，并利未人乌列、亚帅雅、约珥、示玛雅、以列、亚米拿达召来，","notes":[]},{"n":12,"t":"对他们说：「你们是利未人的族长，你们和你们的弟兄应当自洁，好将耶和华—以色列神的约柜抬到我所预备的地方。","notes":[]},{"n":13,"t":"因你们先前没有抬这约柜，按定例求问耶和华—我们的神，所以他刑罚我们。」","notes":["原文是闯杀"]},{"n":14,"t":"于是祭司利未人自洁，好将耶和华—以色列神的约柜抬上来。","notes":[]},{"n":15,"t":"利未子孙就用杠，肩抬神的约柜，是照耶和华借摩西所吩咐的。","notes":[]},{"n":16,"t":"大卫吩咐利未人的族长，派他们歌唱的弟兄用琴瑟和钹作乐，欢欢喜喜地大声歌颂。","notes":[]},{"n":17,"t":"于是利未人派约珥的儿子希幔和他弟兄中比利家的儿子亚萨，并他们族弟兄米拉利子孙里古沙雅的儿子以探。","notes":[]},{"n":18,"t":"其次还有他们的弟兄撒迦利雅、便雅薛、示米拉末、耶歇、乌尼、以利押、比拿雅、玛西雅、玛他提雅、以利斐利户、弥克尼雅，并守门的俄别·以东和耶利。","notes":[]},{"n":19,"t":"这样，派歌唱的希幔、亚萨、以探敲铜钹，大发响声；","notes":[]},{"n":20,"t":"派撒迦利雅、雅薛、示米拉末、耶歇、乌尼、以利押、玛西雅、比拿雅鼓瑟，调用女音；","notes":[]},{"n":21,"t":"又派玛他提雅、以利斐利户、弥克尼雅、俄别·以东、耶利、亚撒西雅领首弹琴，调用第八。","notes":[]},{"n":22,"t":"利未人的族长基拿尼雅是歌唱人的首领，又教训人歌唱，因为他精通此事。","notes":[]},{"n":23,"t":"比利家、以利加拿是约柜前守门的。","notes":[]},{"n":24,"t":"祭司示巴尼、约沙法、拿坦业、亚玛赛、撒迦利雅、比拿亚、以利以谢在神的约柜前吹号。俄别·以东和耶希亚也是约柜前守门的。","notes":[]},{"n":25,"t":"于是，大卫和以色列的长老，并千夫长都去从俄别·以东的家欢欢喜喜地将耶和华的约柜抬上来。","notes":[],"heads":["约柜迁入耶路撒冷"]},{"n":26,"t":"神赐恩与抬耶和华约柜的利未人，他们就献上七只公牛，七只公羊。","notes":[]},{"n":27,"t":"大卫和抬约柜的利未人，并歌唱人的首领基拿尼雅，以及歌唱的人，都穿着细麻布的外袍；大卫另外穿着细麻布的以弗得。","notes":[]},{"n":28,"t":"这样，以色列众人欢呼吹角、吹号、敲钹、鼓瑟、弹琴，大发响声，将耶和华的约柜抬上来。","notes":[]},{"n":29,"t":"耶和华的约柜进了大卫城的时候，扫罗的女儿米甲从窗户里观看，见大卫王踊跃跳舞，心里就轻视他。","notes":[]}]},"16":{"heading":"颂赞之歌","verses":[{"n":1,"t":"众人将神的约柜请进去，安放在大卫所搭的帐幕里，就在神面前献燔祭和平安祭。","notes":[]},{"n":2,"t":"大卫献完了燔祭和平安祭，就奉耶和华的名给民祝福，","notes":[]},{"n":3,"t":"并且分给以色列人，无论男女，每人一个饼，一块肉，一个葡萄饼。","notes":[]},{"n":4,"t":"大卫派几个利未人在耶和华的约柜前事奉，颂扬，称谢，赞美耶和华—以色列的神：","notes":[]},{"n":5,"t":"为首的是亚萨，其次是撒迦利雅、雅薛、示米拉末、耶歇、玛他提雅、以利押、比拿雅、俄别·以东、耶利，鼓瑟弹琴；惟有亚萨敲钹，大发响声；","notes":[]},{"n":6,"t":"祭司比拿雅和雅哈悉常在神的约柜前吹号。","notes":[]},{"n":7,"t":"那日，大卫初次借亚萨和他的弟兄以诗歌称颂耶和华，说：","notes":[]},{"n":8,"t":"你们要称谢耶和华，求告他的名，在万民中传扬他的作为！","notes":[]},{"n":9,"t":"要向他唱诗、歌颂，谈论他一切奇妙的作为。","notes":[]},{"n":10,"t":"要以他的圣名夸耀；寻求耶和华的人，心中应当欢喜。","notes":[]},{"n":11,"t":"要寻求耶和华与他的能力，时常寻求他的面。","notes":[]},{"n":12,"t":"他仆人以色列的后裔，他所拣选雅各的子孙哪，你们要记念他奇妙的作为和他的奇事，并他口中的判语。","notes":[],"end":13},{"n":14,"t":"他是耶和华—我们的神，全地都有他的判断。","notes":[]},{"n":15,"t":"你们要记念他的约，直到永远；他所吩咐的话，直到千代，","notes":[]},{"n":16,"t":"就是与亚伯拉罕所立的约，向以撒所起的誓。","notes":[]},{"n":17,"t":"他又将这约向雅各定为律例，向以色列定为永远的约，","notes":[]},{"n":18,"t":"说：我必将迦南地赐给你，作你产业的分。","notes":[]},{"n":19,"t":"当时你们人丁有限，数目稀少，并且在那地为寄居的；","notes":[]},{"n":20,"t":"他们从这邦游到那邦，从这国行到那国。","notes":[]},{"n":21,"t":"耶和华不容什么人欺负他们，为他们的缘故责备君王，","notes":[]},{"n":22,"t":"说：不可难为我受膏的人，也不可恶待我的先知！","notes":[]},{"n":23,"t":"全地都要向耶和华歌唱！天天传扬他的救恩，","notes":[]},{"n":24,"t":"在列邦中述说他的荣耀，在万民中述说他的奇事。","notes":[]},{"n":25,"t":"因耶和华为大，当受极大的赞美；他在万神之上，当受敬畏。","notes":[]},{"n":26,"t":"外邦的神都属虚无，惟独耶和华创造诸天。","notes":[]},{"n":27,"t":"有尊荣和威严在他面前，有能力和喜乐在他圣所。","notes":[]},{"n":28,"t":"民中的万族啊，你们要将荣耀能力归给耶和华，都归给耶和华！","notes":[]},{"n":29,"t":"要将耶和华的名所当得的荣耀归给他，拿供物来奉到他面前；当以圣洁的妆饰敬拜耶和华。","notes":["的：或译为"]},{"n":30,"t":"全地要在他面前战抖，世界也坚定不得动摇。","notes":[]},{"n":31,"t":"愿天欢喜，愿地快乐；愿人在列邦中说：耶和华作王了！","notes":[]},{"n":32,"t":"愿海和其中所充满的澎湃；愿田和其中所有的都欢乐。","notes":[]},{"n":33,"t":"那时，林中的树木都要在耶和华面前欢呼，因为他来要审判全地。","notes":[]},{"n":34,"t":"应当称谢耶和华；因他本为善，他的慈爱永远长存！","notes":[]},{"n":35,"t":"要说：拯救我们的神啊，求你救我们，聚集我们，使我们脱离外邦，我们好称赞你的圣名，以赞美你为夸胜。","notes":[]},{"n":36,"t":"耶和华—以色列的神，从亘古直到永远，是应当称颂的！众民都说：「阿们！」并且赞美耶和华。","notes":[]},{"n":37,"t":"大卫派亚萨和他的弟兄在约柜前常常事奉耶和华，一日尽一日的职分；","notes":[],"heads":["在耶路撒冷和基遍的敬拜"]},{"n":38,"t":"又派俄别·以东和他的弟兄六十八人，与耶杜顿的儿子俄别·以东，并何萨作守门的；","notes":[]},{"n":39,"t":"且派祭司撒督和他弟兄众祭司在基遍的邱坛、耶和华的帐幕前燔祭坛上，每日早晚，照着耶和华律法书上所吩咐以色列人的，常给耶和华献燔祭。","notes":[],"end":40},{"n":41,"t":"与他们一同被派的有希幔、耶杜顿，和其余被选名字录在册上的，称谢耶和华，因他的慈爱永远长存。","notes":[]},{"n":42,"t":"希幔、耶杜顿同着他们吹号、敲钹，大发响声，并用别的乐器随着歌颂神。耶杜顿的子孙作守门的。","notes":[]},{"n":43,"t":"于是众民各归各家；大卫也回去为家眷祝福。","notes":[]}]},"17":{"heading":"拿单传给大卫的信息","verses":[{"n":1,"t":"大卫住在自己宫中，对先知拿单说：「看哪，我住在香柏木的宫中，耶和华的约柜反在幔子里。」","notes":[]},{"n":2,"t":"拿单对大卫说：「你可以照你的心意而行，因为神与你同在。」","notes":[]},{"n":3,"t":"当夜，神的话临到拿单，说：","notes":[]},{"n":4,"t":"「你去告诉我仆人大卫，说耶和华如此说：『你不可建造殿宇给我居住。","notes":[]},{"n":5,"t":"自从我领以色列人出埃及，直到今日，我未曾住过殿宇，乃从这会幕到那会幕，从这帐幕到那帐幕。","notes":[]},{"n":6,"t":"凡我同以色列人所走的地方，我何曾向以色列的一个士师，就是我吩咐牧养我民的说：你为何不给我建造香柏木的殿宇呢？』","notes":[]},{"n":7,"t":"现在你要告诉我仆人大卫，说万军之耶和华如此说：『我从羊圈中将你召来，叫你不再跟从羊群，立你作我民以色列的君。","notes":[]},{"n":8,"t":"你无论往哪里去，我常与你同在，剪除你的一切仇敌；我必使你得大名，好像世上大大有名的人一样。","notes":[]},{"n":9,"t":"我必为我民以色列选定一个地方，栽培他们，使他们住自己的地方，不再迁移；凶恶之子也不像从前扰害他们，","notes":[]},{"n":10,"t":"并不像我命士师治理我民以色列的时候一样。我必治服你的一切仇敌，并且我—耶和华应许你，必为你建立家室。","notes":[]},{"n":11,"t":"你寿数满足归你列祖的时候，我必使你的后裔接续你的位，我也必坚定他的国。","notes":[]},{"n":12,"t":"他必为我建造殿宇；我必坚定他的国位直到永远。","notes":[]},{"n":13,"t":"我要作他的父，他要作我的子；并不使我的慈爱离开他，像离开在你以前的扫罗一样。","notes":[]},{"n":14,"t":"我却要将他永远坚立在我家里和我国里；他的国位也必坚定，直到永远。』」","notes":[]},{"n":15,"t":"拿单就按这一切话，照这默示告诉大卫。","notes":[]},{"n":16,"t":"于是大卫王进去，坐在耶和华面前，说：「耶和华神啊，我是谁，我的家算什么，你竟使我到这地步呢？","notes":[],"heads":["感恩的祷告"]},{"n":17,"t":"神啊，这在你眼中还看为小，又应许你仆人的家至于久远。耶和华神啊，你看顾我好像看顾高贵的人。","notes":[]},{"n":18,"t":"你加于仆人的尊荣，我还有何言可说呢？因为你知道你的仆人。","notes":[]},{"n":19,"t":"耶和华啊，你行了这大事，并且显明出来，是因你仆人的缘故，也是照你的心意。","notes":[]},{"n":20,"t":"耶和华啊，照我们耳中听见，没有可比你的，除你以外再无神。","notes":[]},{"n":21,"t":"世上有何民能比你的民以色列呢？你神从埃及救赎他们作自己的子民，又在你赎出来的民面前行大而可畏的事，驱逐列邦人，显出你的大名。","notes":[]},{"n":22,"t":"你使以色列人作你的子民，直到永远；你—耶和华也作他们的神。","notes":[]},{"n":23,"t":"耶和华啊，你所应许仆人和仆人家的话，求你坚定，直到永远，照你所说的而行。","notes":[]},{"n":24,"t":"愿你的名永远坚立，被尊为大，说：『万军之耶和华是以色列的神，是治理以色列的神。』这样，你仆人大卫的家必在你面前坚立。","notes":[]},{"n":25,"t":"我的神啊，因你启示仆人说，我必为你建立家室，所以仆人大胆在你面前祈祷。","notes":[]},{"n":26,"t":"耶和华啊，惟有你是神，你也应许将这福气赐给仆人。","notes":[]},{"n":27,"t":"现在你喜悦赐福与仆人的家，可以永存在你面前。耶和华啊，你已经赐福，还要赐福到永远。」","notes":[]}]},"18":{"heading":"在军事上的胜利","verses":[{"n":1,"t":"此后，大卫攻打非利士人，把他们治服，从他们手下夺取了迦特和属迦特的村庄；","notes":[]},{"n":2,"t":"又攻打摩押，摩押人就归服大卫，给他进贡。","notes":[]},{"n":3,"t":"琐巴王哈大利谢往 幼发拉底河去，要坚定自己的国权，大卫就攻打他，直到哈马，","notes":["在撒母耳下八章三节是哈大底谢"]},{"n":4,"t":"夺了他的战车一千，马兵七千，步兵二万，将拉战车的马砍断蹄筋，但留下一百辆车的马。","notes":[]},{"n":5,"t":"大马士革的亚兰人来帮助琐巴王哈大利谢，大卫就杀了亚兰人二万二千。","notes":[]},{"n":6,"t":"于是大卫在大马士革的亚兰地设立防营，亚兰人就归服他，给他进贡。大卫无论往哪里去，耶和华都使他得胜。","notes":[]},{"n":7,"t":"他夺了哈大利谢臣仆所拿的金盾牌带到耶路撒冷。","notes":[]},{"n":8,"t":"大卫又从属哈大利谢的提巴和均二城中夺取了许多的铜。后来所罗门用此制造铜海、铜柱，和一切的铜器。","notes":["或译：比他"]},{"n":9,"t":"哈马王陀乌听见大卫杀败琐巴王哈大利谢的全军，","notes":[]},{"n":10,"t":"就打发他儿子哈多兰去见大卫王，问他的安，为他祝福，因为他杀败了哈大利谢（原来陀乌与哈大利谢常常争战）。哈多兰带了金银铜的各样器皿来。","notes":[]},{"n":11,"t":"大卫王将这些器皿，并从各国夺来的金银，就是从以东、摩押、亚扪、非利士、亚玛力人所夺来的，都分别为圣献给耶和华。","notes":[]},{"n":12,"t":"洗鲁雅的儿子亚比筛在盐谷击杀了以东一万八千人。","notes":[]},{"n":13,"t":"大卫在以东地设立防营，以东人就都归服他。大卫无论往哪里去，耶和华都使他得胜。","notes":[]},{"n":14,"t":"大卫作以色列众人的王，又向众民秉公行义。","notes":[]},{"n":15,"t":"洗鲁雅的儿子约押作元帅；亚希律的儿子约沙法作史官；","notes":[]},{"n":16,"t":"亚希突的儿子撒督和亚比亚他的儿子亚希米勒作祭司长；沙威沙作书记；","notes":[]},{"n":17,"t":"耶何耶大的儿子比拿雅统辖基利提人和比利提人。大卫的众子都在王的左右作领袖。","notes":[]}]},"19":{"heading":"大卫击败亚扪人和亚兰人","verses":[{"n":1,"t":"此后，亚扪人的王拿辖死了，他儿子接续他作王。","notes":[]},{"n":2,"t":"大卫说：「我要照哈嫩的父亲拿辖厚待我的恩典厚待哈嫩。」于是大卫差遣使者为他丧父安慰他。大卫的臣仆到了亚扪人的境内见哈嫩，要安慰他，","notes":[]},{"n":3,"t":"但亚扪人的首领对哈嫩说：「大卫差人来安慰你，你想他是尊敬你父亲吗？他的臣仆来见你不是为详察窥探、倾覆这地吗？」","notes":[]},{"n":4,"t":"哈嫩便将大卫臣仆的胡须剃去一半，又割断他们下半截的衣服，使他们露出下体，打发他们回去。","notes":[]},{"n":5,"t":"有人将臣仆所遇的事告诉大卫，他就差人去迎接他们，因为他们甚觉羞耻；告诉他们说：「可以住在耶利哥，等到胡须长起再回来。」","notes":[]},{"n":6,"t":"亚扪人知道大卫憎恶他们，哈嫩和亚扪人就打发人拿一千他连得银子，从美索不达米亚、亚兰、玛迦、琐巴雇战车和马兵，","notes":[]},{"n":7,"t":"于是雇了三万二千辆战车和玛迦王并他的军兵；他们来安营在米底巴前。亚扪人也从他们的城里出来，聚集交战。","notes":[]},{"n":8,"t":"大卫听见了，就差派约押统带勇猛的全军出去。","notes":[]},{"n":9,"t":"亚扪人出来在城门前摆阵，所来的诸王另在郊野摆阵。","notes":[]},{"n":10,"t":"约押看见敌人在他前后摆阵，就从以色列军中挑选精兵，使他们对着亚兰人摆阵；","notes":[]},{"n":11,"t":"其余的兵交与他兄弟亚比筛，对着亚扪人摆阵。","notes":[]},{"n":12,"t":"约押对亚比筛说：「亚兰人若强过我，你就来帮助我；亚扪人若强过你，我就去帮助你。","notes":[]},{"n":13,"t":"我们都当刚强，为本国的民和神的城邑作大丈夫，愿耶和华凭他的意旨而行。」","notes":[]},{"n":14,"t":"于是约押和跟随他的人前进攻打亚兰人；亚兰人在约押面前逃跑。","notes":[]},{"n":15,"t":"亚扪人见亚兰人逃跑，他们也在约押的兄弟亚比筛面前逃跑进城。约押就回耶路撒冷去了。","notes":[]},{"n":16,"t":"亚兰人见自己被以色列人打败，就打发使者将大河那边的亚兰人调来，哈大利谢的将军朔法率领他们。","notes":[]},{"n":17,"t":"有人告诉大卫，他就聚集以色列众人过约旦河，来到亚兰人那里，迎着他们摆阵。大卫既摆阵攻击亚兰人，亚兰人就与他打仗。","notes":[]},{"n":18,"t":"亚兰人在以色列人面前逃跑。大卫杀了亚兰七千辆战车的人，四万步兵，又杀了亚兰的将军朔法。","notes":[]},{"n":19,"t":"属哈大利谢的诸王见自己被以色列人打败，就与大卫和好，归服他。于是亚兰人不敢再帮助亚扪人了。","notes":[]}]},"20":{"heading":"大卫攻取拉巴城","verses":[{"n":1,"t":"过了一年，到列王出战的时候，约押率领军兵毁坏亚扪人的地，围攻拉巴；大卫仍住在耶路撒冷。约押攻打拉巴，将城倾覆。","notes":[]},{"n":2,"t":"大卫夺了亚扪人之王所戴的金冠冕，其上的金子重一他连得，又嵌着宝石；人将这冠冕戴在大卫头上。大卫从城里夺了许多财物，","notes":["王：或译玛勒堪。玛勒堪即米勒公，是亚扪族之神名"]},{"n":3,"t":"将城里的人拉出来，放在锯下，或铁耙下，或铁斧下，大卫待亚扪各城的居民都是如此。其后大卫和众军都回耶路撒冷去了。","notes":["或译：强他们用锯，或用打粮食的铁器，或用铁斧做工"]},{"n":4,"t":"后来，以色列人在基色与非利士人打仗。户沙人西比该杀了伟人的一个儿子细派，非利士人就被制伏了。","notes":[],"heads":["与非利士巨人争战"]},{"n":5,"t":"又与非利士人打仗。睚珥的儿子伊勒哈难杀了迦特人歌利亚的兄弟拉哈米；这人的枪杆粗如织布的机轴。","notes":[]},{"n":6,"t":"又在迦特打仗。那里有一个身量高大的人，手脚都是六指，共有二十四个指头，他也是伟人的儿子。","notes":[]},{"n":7,"t":"这人向以色列人骂阵，大卫的哥哥示米亚的儿子约拿单就杀了他。","notes":[]},{"n":8,"t":"这三个人是迦特伟人的儿子，都死在大卫和他仆人的手下。","notes":[]}]},"21":{"heading":"大卫数点以色列民","verses":[{"n":1,"t":"撒但起来攻击以色列人，激动大卫数点他们。","notes":[]},{"n":2,"t":"大卫就吩咐约押和民中的首领说：「你们去数点以色列人，从别是巴直到但，回来告诉我，我好知道他们的数目。」","notes":[]},{"n":3,"t":"约押说：「愿耶和华使他的百姓比现在加增百倍。我主我王啊，他们不都是你的仆人吗？我主为何吩咐行这事，为何使以色列人陷在罪里呢？」","notes":[]},{"n":4,"t":"但王的命令胜过约押。约押就出去，走遍以色列地，回到耶路撒冷，","notes":[]},{"n":5,"t":"将百姓的总数奏告大卫：以色列人拿刀的有一百一十万；犹大人拿刀的有四十七万。","notes":[]},{"n":6,"t":"惟有利未人和便雅悯人没有数在其中，因为约押厌恶王的这命令。","notes":[]},{"n":7,"t":"神不喜悦这数点百姓的事，便降灾给以色列人。","notes":[]},{"n":8,"t":"大卫祷告神说：「我行这事大有罪了！现在求你除掉仆人的罪孽，因我所行的甚是愚昧。」","notes":[]},{"n":9,"t":"耶和华吩咐大卫的先见迦得说：","notes":[]},{"n":10,"t":"「你去告诉大卫说，耶和华如此说：我有三样灾，随你选择一样，我好降与你。」","notes":[]},{"n":11,"t":"于是，迦得来见大卫，对他说：「耶和华如此说：『你可以随意选择：","notes":[]},{"n":12,"t":"或三年的饥荒；或败在你敌人面前，被敌人的刀追杀三个月；或在你国中有耶和华的刀，就是三日的瘟疫，耶和华的使者在以色列的四境施行毁灭。』现在你要想一想，我好回复那差我来的。」","notes":[]},{"n":13,"t":"大卫对迦得说：「我甚为难。我愿落在耶和华的手里，因为他有丰盛的怜悯；我不愿落在人的手里。」","notes":[]},{"n":14,"t":"于是，耶和华降瘟疫与以色列人，以色列人就死了七万。","notes":[]},{"n":15,"t":"神差遣使者去灭耶路撒冷，刚要灭的时候，耶和华看见后悔，就不降这灾了，吩咐灭城的天使说：「够了，住手吧！」那时，耶和华的使者站在耶布斯人阿珥楠的禾场那里。","notes":[]},{"n":16,"t":"大卫举目，看见耶和华的使者站在天地间，手里有拔出来的刀，伸在耶路撒冷以上。大卫和长老都身穿麻衣，面伏于地。","notes":[]},{"n":17,"t":"大卫祷告神说：「吩咐数点百姓的不是我吗？我犯了罪，行了恶，但这群羊做了什么呢？愿耶和华—我神的手攻击我和我的父家，不要攻击你的民，降瘟疫与他们。」","notes":[]},{"n":18,"t":"耶和华的使者吩咐迦得去告诉大卫，叫他上去，在耶布斯人阿珥楠的禾场上为耶和华筑一座坛；","notes":[]},{"n":19,"t":"大卫就照着迦得奉耶和华名所说的话上去了。","notes":[]},{"n":20,"t":"那时阿珥楠正打麦子，回头看见天使，就和他四个儿子都藏起来了。","notes":[]},{"n":21,"t":"大卫到了阿珥楠那里，阿珥楠看见大卫，就从禾场上出去，脸伏于地，向他下拜。","notes":[]},{"n":22,"t":"大卫对阿珥楠说：「你将这禾场与相连之地卖给我，我必给你足价，我好在其上为耶和华筑一座坛，使民间的瘟疫止住。」","notes":[]},{"n":23,"t":"阿珥楠对大卫说：「你可以用这禾场，愿我主我王照你所喜悦的去行。我也将牛给你作燔祭，把打粮的器具当柴烧，拿麦子作素祭。这些我都送给你。」","notes":[]},{"n":24,"t":"大卫王对阿珥楠说：「不然！我必要用足价向你买。我不用你的物献给耶和华，也不用白得之物献为燔祭。」","notes":[]},{"n":25,"t":"于是大卫为那块地平了六百舍客勒金子给阿珥楠。","notes":[]},{"n":26,"t":"大卫在那里为耶和华筑了一座坛，献燔祭和平安祭，求告耶和华。耶和华就应允他，使火从天降在燔祭坛上。","notes":[]},{"n":27,"t":"耶和华吩咐使者，他就收刀入鞘。","notes":[]},{"n":28,"t":"那时，大卫见耶和华在耶布斯人阿珥楠的禾场上应允了他，就在那里献祭。","notes":[]},{"n":29,"t":"摩西在旷野所造之耶和华的帐幕和燔祭坛都在基遍的高处；","notes":[]},{"n":30,"t":"只是大卫不敢前去求问神，因为惧怕耶和华使者的刀。","notes":[]}]},"22":{"heading":"筹备建殿","verses":[{"n":1,"t":"大卫说：「这就是耶和华神的殿，为以色列人献燔祭的坛。」","notes":[]},{"n":2,"t":"大卫吩咐聚集住以色列地的外邦人，从其中派石匠凿石头，要建造神的殿。","notes":[]},{"n":3,"t":"大卫预备许多铁做门上的钉子和钩子，又预备许多铜，多得无法可称；","notes":[]},{"n":4,"t":"又预备无数的香柏木，因为西顿人和泰尔人给大卫运了许多香柏木来。","notes":[]},{"n":5,"t":"大卫说：「我儿子所罗门还年幼娇嫩，要为耶和华建造的殿宇必须高大辉煌，使名誉荣耀传遍万国；所以我要为殿预备材料。」于是，大卫在未死之先预备的材料甚多。","notes":[]},{"n":6,"t":"大卫召了他儿子所罗门来，嘱咐他给耶和华—以色列的神建造殿宇，","notes":[]},{"n":7,"t":"对所罗门说：「我儿啊，我心里本想为耶和华—我神的名建造殿宇，","notes":[]},{"n":8,"t":"只是耶和华的话临到我说：『你流了多人的血，打了多次大仗，你不可为我的名建造殿宇，因为你在我眼前使多人的血流在地上。","notes":[]},{"n":9,"t":"你要生一个儿子，他必作太平的人；我必使他安静，不被四围的仇敌扰乱。他的名要叫所罗门。他在位的日子，我必使以色列人平安康泰。","notes":["就是太平的意思"]},{"n":10,"t":"他必为我的名建造殿宇。他要作我的子；我要作他的父。他作以色列王；我必坚定他的国位，直到永远。』","notes":[]},{"n":11,"t":"我儿啊，现今愿耶和华与你同在，使你亨通，照他指着你说的话，建造耶和华—你神的殿。","notes":[]},{"n":12,"t":"但愿耶和华赐你聪明智慧，好治理以色列国，遵行耶和华—你神的律法。","notes":[]},{"n":13,"t":"你若谨守遵行耶和华借摩西吩咐以色列的律例典章，就得亨通。你当刚强壮胆，不要惧怕，也不要惊惶。","notes":[]},{"n":14,"t":"我在困难之中为耶和华的殿预备了金子十万他连得，银子一百万他连得，铜和铁多得无法可称；我也预备了木头、石头，你还可以增添。","notes":[]},{"n":15,"t":"你有许多匠人，就是石匠、木匠，和一切能做各样工的巧匠，","notes":[]},{"n":16,"t":"并有无数的金银铜铁。你当起来办事，愿耶和华与你同在。」","notes":[]},{"n":17,"t":"大卫又吩咐以色列的众首领帮助他儿子所罗门，说：","notes":[]},{"n":18,"t":"「耶和华—你们的神不是与你们同在吗？不是叫你们四围都平安吗？因他已将这地的居民交在我手中，这地就在耶和华与他百姓面前制伏了。","notes":[]},{"n":19,"t":"现在你们应当立定心意，寻求耶和华—你们的神；也当起来建造耶和华神的圣所，好将耶和华的约柜和供奉神的圣器皿都搬进为耶和华名建造的殿里。」","notes":[]}]},"23":{"heading":"利未人的职务","verses":[{"n":1,"t":"大卫年纪老迈，日子满足，就立他儿子所罗门作以色列的王。","notes":[]},{"n":2,"t":"大卫招聚以色列的众首领和祭司利未人。","notes":[]},{"n":3,"t":"利未人从三十岁以外的都被数点，他们男丁的数目共有三万八千；","notes":[]},{"n":4,"t":"其中有二万四千人管理耶和华殿的事，有六千人作官长和士师，","notes":[]},{"n":5,"t":"有四千人作守门的，又有四千人用大卫所做的乐器颂赞耶和华。","notes":[]},{"n":6,"t":"大卫将利未人革顺、哥辖、米拉利的子孙分了班次。","notes":[]},{"n":7,"t":"革顺的子孙有拉但和示每。","notes":[]},{"n":8,"t":"拉但的长子是耶歇，还有细坦和约珥，共三人。","notes":[]},{"n":9,"t":"示每的儿子是示罗密、哈薛、哈兰三人。这是拉但族的族长。","notes":[]},{"n":10,"t":"示每的儿子是雅哈、细拿、耶乌施、比利亚共四人。","notes":[]},{"n":11,"t":"雅哈是长子，细撒是次子。但耶乌施和比利亚的子孙不多，所以算为一族。","notes":[]},{"n":12,"t":"哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛共四人。","notes":[]},{"n":13,"t":"暗兰的儿子是亚伦、摩西。亚伦和他的子孙分出来，好分别至圣的物，在耶和华面前烧香、事奉他，奉他的名祝福，直到永远。","notes":[]},{"n":14,"t":"至于神人摩西，他的子孙名字记在利未支派的册上。","notes":[]},{"n":15,"t":"摩西的儿子是革舜和以利以谢。","notes":[]},{"n":16,"t":"革舜的长子是细布业；","notes":[]},{"n":17,"t":"以利以谢的儿子是利哈比雅。以利以谢没有别的儿子，但利哈比雅的子孙甚多。","notes":[]},{"n":18,"t":"以斯哈的长子是示罗密。","notes":[]},{"n":19,"t":"希伯伦的长子是耶利雅，次子是亚玛利亚，三子是雅哈悉，四子是耶加面。","notes":[]},{"n":20,"t":"乌薛的长子是米迦，次子是耶西雅。","notes":[]},{"n":21,"t":"米拉利的儿子是抹利、母示。抹利的儿子是以利亚撒、基士。","notes":[]},{"n":22,"t":"以利亚撒死了，没有儿子，只有女儿，他们本族基士的儿子娶了她们为妻。","notes":[]},{"n":23,"t":"母示的儿子是末力、以得、耶利摩共三人。","notes":[]},{"n":24,"t":"以上利未子孙作族长的，照着男丁的数目，从二十岁以外，都办耶和华殿的事务。","notes":[]},{"n":25,"t":"大卫说：「耶和华—以色列的神已经使他的百姓平安，他永远住在耶路撒冷。","notes":[]},{"n":26,"t":"利未人不必再抬帐幕和其中所用的一切器皿了。」","notes":[]},{"n":27,"t":"照着大卫临终所吩咐的，利未人从二十岁以外的都被数点。","notes":[]},{"n":28,"t":"他们的职任是服事亚伦的子孙，在耶和华的殿和院子，并屋中办事，洁净一切圣物，就是办神殿的事务，","notes":[]},{"n":29,"t":"并管理陈设饼，素祭的细面，或无酵薄饼，或用盘烤，或用油调和的物，又管理各样的升斗尺度；","notes":[]},{"n":30,"t":"每日早晚，站立称谢赞美耶和华，","notes":[]},{"n":31,"t":"又在安息日、月朔，并节期，按数照例，将燔祭常常献给耶和华；","notes":[]},{"n":32,"t":"又看守会幕和圣所，并守耶和华吩咐他们弟兄亚伦子孙的，办耶和华殿的事。","notes":[]}]},"24":{"heading":"祭司的职务","verses":[{"n":1,"t":"亚伦子孙的班次记在下面：亚伦的儿子是拿答、亚比户、以利亚撒、以他玛。","notes":[]},{"n":2,"t":"拿答、亚比户死在他们父亲之先，没有留下儿子；故此，以利亚撒、以他玛供祭司的职分。","notes":[]},{"n":3,"t":"以利亚撒的子孙撒督和以他玛的子孙亚希米勒，同着大卫将他们的族弟兄分成班次。","notes":[]},{"n":4,"t":"以利亚撒子孙中为首的比以他玛子孙中为首的更多，分班如下：以利亚撒的子孙中有十六个族长，以他玛的子孙中有八个族长；","notes":[]},{"n":5,"t":"都掣签分立，彼此一样。在圣所和神面前作首领的有以利亚撒的子孙，也有以他玛的子孙。","notes":[]},{"n":6,"t":"作书记的利未人拿坦业的儿子示玛雅在王和首领，与祭司撒督、亚比亚他的儿子亚希米勒，并祭司利未人的族长面前记录他们的名字。在以利亚撒的子孙中取一族，在以他玛的子孙中取一族。","notes":[]},{"n":7,"t":"掣签的时候，第一掣出来的是耶何雅立，第二是耶大雅，","notes":[]},{"n":8,"t":"第三是哈琳，第四是梭琳，","notes":[]},{"n":9,"t":"第五是玛基雅，第六是米雅民，","notes":[]},{"n":10,"t":"第七是哈歌斯，第八是亚比雅，","notes":[]},{"n":11,"t":"第九是耶书亚，第十是示迦尼，","notes":[]},{"n":12,"t":"第十一是以利亚实，第十二是雅金，","notes":[]},{"n":13,"t":"第十三是胡巴，第十四是耶是比押，","notes":[]},{"n":14,"t":"第十五是璧迦，第十六是音麦，","notes":[]},{"n":15,"t":"第十七是希悉，第十八是哈辟悉，","notes":[]},{"n":16,"t":"第十九是毗他希雅，第二十是以西结，","notes":[]},{"n":17,"t":"第二十一是雅斤，第二十二是迦末，","notes":[]},{"n":18,"t":"第二十三是第来雅，第二十四是玛西亚。","notes":[]},{"n":19,"t":"这就是他们的班次，要照耶和华—以色列的神借他们祖宗亚伦所吩咐的条例进入耶和华的殿办理事务。","notes":[]},{"n":20,"t":"利未其余的子孙如下：暗兰的子孙里有书巴业；书巴业的子孙里有耶希底亚。","notes":[],"heads":["利未人名单"]},{"n":21,"t":"利哈比雅的子孙里有长子伊示雅。","notes":[]},{"n":22,"t":"以斯哈的子孙里有示罗摩；示罗摩的子孙里有雅哈。","notes":[]},{"n":23,"t":"希伯伦的子孙里有长子耶利雅，次子亚玛利亚，三子雅哈悉，四子耶加面。","notes":[]},{"n":24,"t":"乌薛的子孙里有米迦；米迦的子孙里有沙密。","notes":[]},{"n":25,"t":"米迦的兄弟是伊示雅；伊示雅的子孙里有撒迦利雅。","notes":[]},{"n":26,"t":"米拉利的儿子是抹利、母示、雅西雅；雅西雅的儿子有比挪；","notes":[]},{"n":27,"t":"米拉利的子孙里有雅西雅的儿子比挪、朔含、撒刻、伊比利。","notes":[]},{"n":28,"t":"抹利的儿子是以利亚撒；以利亚撒没有儿子。","notes":[]},{"n":29,"t":"基士的子孙里有耶拉篾。","notes":[]},{"n":30,"t":"母示的儿子是末力、以得、耶利摩。按着宗族这都是利未的子孙。","notes":[]},{"n":31,"t":"他们在大卫王和撒督，并亚希米勒与祭司利未人的族长面前掣签，正如他们弟兄亚伦的子孙一般。各族的长者与兄弟没有分别。","notes":[]}]},"25":{"heading":"圣殿中的圣乐人员","verses":[{"n":1,"t":"大卫和众首领分派亚萨、希幔，并耶杜顿的子孙弹琴、鼓瑟、敲钹、唱歌。他们供职的人数记在下面：","notes":["原文是说预言；本章同"]},{"n":2,"t":"亚萨的儿子撒刻、约瑟、尼探雅、亚萨利拉都归亚萨指教，遵王的旨意唱歌。","notes":[]},{"n":3,"t":"耶杜顿的儿子基大利、西利、耶筛亚、哈沙比雅、玛他提雅、示每共六人，都归他们父亲耶杜顿指教，弹琴，唱歌，称谢，颂赞耶和华。","notes":[]},{"n":4,"t":"希幔的儿子布基雅、玛探雅、乌薛、细布业、耶利摩、哈拿尼雅、哈拿尼、以利亚他、基大利提、罗幔提·以谢、约施比加沙、玛罗提、何提、玛哈秀；","notes":[]},{"n":5,"t":"这都是希幔的儿子，吹角颂赞。希幔奉神之命作王的先见。神赐给希幔十四个儿子，三个女儿，","notes":[]},{"n":6,"t":"都归他们父亲指教，在耶和华的殿唱歌、敲钹、弹琴、鼓瑟，办神殿的事务。亚萨、耶杜顿、希幔都是王所命定的。","notes":[]},{"n":7,"t":"他们和他们的弟兄学习颂赞耶和华；善于歌唱的共有二百八十八人。","notes":[]},{"n":8,"t":"这些人无论大小，为师的、为徒的，都一同掣签分了班次。","notes":[]},{"n":9,"t":"掣签的时候，第一掣出来的是亚萨的儿子约瑟。第二是基大利；他和他弟兄并儿子共十二人。","notes":[]},{"n":10,"t":"第三是撒刻；他和他儿子并弟兄共十二人。","notes":[]},{"n":11,"t":"第四是伊洗利；他和他儿子并弟兄共十二人。","notes":[]},{"n":12,"t":"第五是尼探雅；他和他儿子并弟兄共十二人。","notes":[]},{"n":13,"t":"第六是布基雅；他和他儿子并弟兄共十二人。","notes":[]},{"n":14,"t":"第七是耶萨利拉；他和他儿子并弟兄共十二人。","notes":[]},{"n":15,"t":"第八是耶筛亚；他和他儿子并弟兄共十二人。","notes":[]},{"n":16,"t":"第九是玛探雅；他和他儿子并弟兄共十二人。","notes":[]},{"n":17,"t":"第十是示每；他和他儿子并弟兄共十二人。","notes":[]},{"n":18,"t":"第十一是亚萨烈；他和他儿子并弟兄共十二人。","notes":[]},{"n":19,"t":"第十二是哈沙比雅；他和他儿子并弟兄共十二人。","notes":[]},{"n":20,"t":"第十三是书巴业；他和他儿子并弟兄共十二人。","notes":[]},{"n":21,"t":"第十四是玛他提雅；他和他儿子并弟兄共十二人。","notes":[]},{"n":22,"t":"第十五是耶利摩；他和他儿子并弟兄共十二人。","notes":[]},{"n":23,"t":"第十六是哈拿尼雅；他和他儿子并弟兄共十二人。","notes":[]},{"n":24,"t":"第十七是约施比加沙；他和他儿子并弟兄共十二人。","notes":[]},{"n":25,"t":"第十八是哈拿尼；他和他儿子并弟兄共十二人。","notes":[]},{"n":26,"t":"第十九是玛罗提；他和他儿子并弟兄共十二人。","notes":[]},{"n":27,"t":"第二十是以利亚他；他和他儿子并弟兄共十二人。","notes":[]},{"n":28,"t":"第二十一是何提；他和他儿子并弟兄共十二人。","notes":[]},{"n":29,"t":"第二十二是基大利提；他和他儿子并弟兄共十二人。","notes":[]},{"n":30,"t":"第二十三是玛哈秀；他和他儿子并弟兄共十二人。","notes":[]},{"n":31,"t":"第二十四是罗幔提·以谢；他和他儿子并弟兄共十二人。","notes":[]}]},"26":{"heading":"圣殿的卫队","verses":[{"n":1,"t":"守门的班次记在下面：可拉族亚萨的子孙中，有可利的儿子米施利米雅。","notes":[]},{"n":2,"t":"米施利米雅的长子是撒迦利亚，次子是耶叠，三子是西巴第雅，四子是耶提聂，","notes":[]},{"n":3,"t":"五子是以拦，六子是约哈难，七子是以利约乃。","notes":[]},{"n":4,"t":"俄别·以东的长子是示玛雅，次子是约萨拔，三子是约亚，四子是沙甲，五子是拿坦业，","notes":[]},{"n":5,"t":"六子是亚米利，七子是以萨迦，八子是毗乌利太，因为神赐福与俄别·以东。","notes":[]},{"n":6,"t":"他的儿子示玛雅有几个儿子，都是大能的壮士，掌管父亲的家。","notes":[]},{"n":7,"t":"示玛雅的儿子是俄得尼、利法益、俄备得、以利萨巴。以利萨巴的弟兄是壮士，还有以利户和西玛迦。","notes":[]},{"n":8,"t":"这都是俄别·以东的子孙，他们和他们的儿子并弟兄，都是善于办事的壮士。俄别·以东的子孙共六十二人。","notes":[]},{"n":9,"t":"米施利米雅的儿子和弟兄都是壮士，共十八人。","notes":[]},{"n":10,"t":"米拉利子孙何萨有几个儿子：长子是申利，他原不是长子，是他父亲立他作长子。","notes":[]},{"n":11,"t":"次子是希勒家，三子是底巴利雅，四子是撒迦利亚。何萨的儿子并弟兄共十三人。","notes":[]},{"n":12,"t":"这些人都是守门的班长，与他们的弟兄一同在耶和华殿里按班供职。","notes":[]},{"n":13,"t":"他们无论大小，都按着宗族掣签分守各门。","notes":[]},{"n":14,"t":"掣签守东门的是示利米雅；他的儿子撒迦利亚是精明的谋士，掣签守北门。","notes":[]},{"n":15,"t":"俄别·以东守南门，他的儿子守库房。","notes":[]},{"n":16,"t":"书聘与何萨守西门，在靠近沙利基门、通着往上去的街道上，班与班相对。","notes":[]},{"n":17,"t":"每日东门有六个利未人，北门有四个，南门有四个，库房有两个，又有两个轮班替换。","notes":[]},{"n":18,"t":"在西面街道上有四个，在游廊上有两个。","notes":[]},{"n":19,"t":"以上是可拉子孙和米拉利子孙守门的班次。","notes":[]},{"n":20,"t":"利未子孙中有亚希雅掌管神殿的府库和圣物的府库。","notes":[],"heads":["其他职守"]},{"n":21,"t":"革顺族、拉但子孙里，作族长的是革顺族拉但的子孙耶希伊利。","notes":[]},{"n":22,"t":"耶希伊利的儿子西坦和他兄弟约珥掌管耶和华殿里的府库。","notes":[]},{"n":23,"t":"暗兰族、以斯哈族、希伯伦族、乌泄族也有职分。","notes":[]},{"n":24,"t":"摩西的孙子、革舜的儿子细布业掌管府库。","notes":[]},{"n":25,"t":"还有他的弟兄以利以谢。以利以谢的儿子是利哈比雅；利哈比雅的儿子是耶筛亚；耶筛亚的儿子是约兰；约兰的儿子是细基利；细基利的儿子是示罗密。","notes":[]},{"n":26,"t":"这示罗密和他的弟兄掌管府库的圣物，就是大卫王和众族长、千夫长、百夫长，并军长所分别为圣的物。","notes":[]},{"n":27,"t":"他们将争战时所夺的财物分别为圣，以备修造耶和华的殿。","notes":[]},{"n":28,"t":"先见撒母耳、基士的儿子扫罗、尼珥的儿子押尼珥、洗鲁雅的儿子约押所分别为圣的物都归示罗密和他的弟兄掌管。","notes":[]},{"n":29,"t":"以斯哈族有基拿尼雅和他众子作官长和士师，管理以色列的外事。","notes":[],"heads":["其余利未人的职守"]},{"n":30,"t":"希伯伦族有哈沙比雅和他弟兄一千七百人，都是壮士，在约旦河西、以色列地办理耶和华与王的事。","notes":[]},{"n":31,"t":"希伯伦族中有耶利雅作族长。大卫作王第四十年，在基列的雅谢，从这族中寻得大能的勇士。","notes":[]},{"n":32,"t":"耶利雅的弟兄有二千七百人，都是壮士，且作族长；大卫王派他们在吕便支派、迦得支派、玛拿西半支派中办理神和王的事。","notes":[]}]},"27":{"heading":"军事长官名单","verses":[{"n":1,"t":"以色列人的族长、千夫长、百夫长，和官长都分定班次，每班是二万四千人，周年按月轮流，替换出入服事王。","notes":[]},{"n":2,"t":"正月第一班的班长是撒巴第业的儿子雅朔班；他班内有二万四千人。","notes":[]},{"n":3,"t":"他是法勒斯的子孙，统管正月班的一切军长。","notes":[]},{"n":4,"t":"二月的班长是亚哈希人朵代，还有副官密基罗；他班内有二万四千人。","notes":[]},{"n":5,"t":"三月第三班的班长是祭司耶何耶大的儿子比拿雅；他班内有二万四千人。","notes":["原文是军长；下同"]},{"n":6,"t":"这比拿雅是那三十人中的勇士，管理那三十人；他班内又有他儿子暗米萨拔。","notes":[]},{"n":7,"t":"四月第四班的班长是约押的兄弟亚撒黑。接续他的是他儿子西巴第雅；他班内有二万四千人。","notes":[]},{"n":8,"t":"五月第五班的班长是伊斯拉人珊合；他班内有二万四千人。","notes":[]},{"n":9,"t":"六月第六班的班长是提哥亚人益吉的儿子以拉；他班内有二万四千人。","notes":[]},{"n":10,"t":"七月第七班的班长是以法莲族比伦人希利斯；他班内有二万四千人。","notes":[]},{"n":11,"t":"八月第八班的班长是谢拉族户沙人西比该；他班内有二万四千人。","notes":[]},{"n":12,"t":"九月第九班的班长是便雅悯族亚拿突人亚比以谢；他班内有二万四千人。","notes":[]},{"n":13,"t":"十月第十班的班长是谢拉族尼陀法人玛哈莱；他班内有二万四千人。","notes":[]},{"n":14,"t":"十一月第十一班的班长是以法莲族比拉顿人比拿雅；他班内有二万四千人。","notes":[]},{"n":15,"t":"十二月第十二班的班长是俄陀聂族尼陀法人黑玳；他班内有二万四千人。","notes":[]},{"n":16,"t":"管理以色列众支派的记在下面：管吕便人的是细基利的儿子以利以谢；管西缅人的是玛迦的儿子示法提雅；","notes":[],"heads":["以色列各支派的行政长官"]},{"n":17,"t":"管利未人的是基母利的儿子哈沙比雅；管亚伦子孙的是撒督；","notes":[]},{"n":18,"t":"管犹大人的是大卫的一个哥哥以利户；管以萨迦人的是米迦勒的儿子暗利；","notes":[]},{"n":19,"t":"管西布伦人的是俄巴第雅的儿子伊施玛雅；管拿弗他利人的是亚斯列的儿子耶利摩；","notes":[]},{"n":20,"t":"管以法莲人的是阿撒细雅的儿子何细亚；管玛拿西半支派的是毗大雅的儿子约珥；","notes":[]},{"n":21,"t":"管基列地玛拿西那半支派的是撒迦利亚的儿子易多；管便雅悯人的是押尼珥的儿子雅西业；","notes":[]},{"n":22,"t":"管但人的是耶罗罕的儿子亚萨列。以上是以色列众支派的首领。","notes":[]},{"n":23,"t":"以色列人二十岁以内的，大卫没有记其数目；因耶和华曾应许说，必加增以色列人如天上的星那样多。","notes":[]},{"n":24,"t":"洗鲁雅的儿子约押动手数点，当时耶和华的烈怒临到以色列人；因此，没有点完，数目也没有写在大卫王记上。","notes":[]},{"n":25,"t":"掌管王府库的是亚叠的儿子押斯马威。掌管田野城邑村庄保障之仓库的是乌西雅的儿子约拿单。","notes":[],"heads":["管理王产的官员"]},{"n":26,"t":"掌管耕田种地的是基绿的儿子以斯利。","notes":[]},{"n":27,"t":"掌管葡萄园的是拉玛人示每。掌管葡萄园酒窖的是实弗米人撒巴底。","notes":[]},{"n":28,"t":"掌管高原橄榄树和桑树的是基第利人巴勒·哈南。掌管油库的是约阿施。","notes":[]},{"n":29,"t":"掌管沙仑牧放牛群的是沙仑人施提赉。掌管山谷牧养牛群的是亚第赉的儿子沙法。","notes":[]},{"n":30,"t":"掌管驼群的是以实玛利人阿比勒。掌管驴群的是米仑人耶希底亚。掌管羊群的是夏甲人雅悉。","notes":[]},{"n":31,"t":"这都是给大卫王掌管产业的。","notes":[]},{"n":32,"t":"大卫的叔叔约拿单作谋士；这人有智慧，又作书记。哈摩尼的儿子耶歇作王众子的师傅。","notes":[],"heads":["大卫的谋士"]},{"n":33,"t":"亚希多弗也作王的谋士。亚基人户筛作王的陪伴。","notes":[]},{"n":34,"t":"亚希多弗之后，有比拿雅的儿子耶何耶大和亚比亚他接续他作谋士。约押作王的元帅。","notes":[]}]},"28":{"heading":"大卫对建殿的指示","verses":[{"n":1,"t":"大卫招聚以色列各支派的首领和轮班服事王的军长，与千夫长、百夫长，掌管王和王子产业牲畜的，并太监，以及大能的勇士，都到耶路撒冷来。","notes":[]},{"n":2,"t":"大卫王就站起来，说：「我的弟兄，我的百姓啊，你们当听我言，我心里本想建造殿宇，安放耶和华的约柜，作为我神的脚凳；我已经预备建造的材料。","notes":[]},{"n":3,"t":"只是神对我说：『你不可为我的名建造殿宇；因你是战士，流了人的血。』","notes":[]},{"n":4,"t":"然而，耶和华—以色列的神在我父的全家拣选我作以色列的王，直到永远。因他拣选犹大为首领；在犹大支派中拣选我父家，在我父的众子里喜悦我，立我作以色列众人的王。","notes":[]},{"n":5,"t":"耶和华赐我许多儿子，在我儿子中拣选所罗门坐耶和华的国位，治理以色列人。","notes":[]},{"n":6,"t":"耶和华对我说：『你儿子所罗门必建造我的殿和院宇；因为我拣选他作我的子，我也必作他的父。","notes":[]},{"n":7,"t":"他若恒久遵行我的诫命典章如今日一样，我就必坚定他的国位，直到永远。』","notes":[]},{"n":8,"t":"现今在耶和华的会中，以色列众人眼前所说的，我们的神也听见了。你们应当寻求耶和华—你们神的一切诫命，谨守遵行，如此你们可以承受这美地，遗留给你们的子孙，永远为业。","notes":[]},{"n":9,"t":"「我儿所罗门哪，你当认识耶和华—你父的神，诚心乐意地事奉他；因为他鉴察众人的心，知道一切心思意念。你若寻求他，他必使你寻见；你若离弃他，他必永远丢弃你。","notes":[]},{"n":10,"t":"你当谨慎，因耶和华拣选你建造殿宇作为圣所。你当刚强去行。」","notes":[]},{"n":11,"t":"大卫将殿的游廊、旁屋、府库、楼房、内殿，和施恩所的样式指示他儿子所罗门，","notes":[]},{"n":12,"t":"又将被灵感动所得的样式，就是耶和华神殿的院子、周围的房屋、殿的府库，和圣物府库的一切样式都指示他；","notes":[]},{"n":13,"t":"又指示他祭司和利未人的班次与耶和华殿里各样的工作，并耶和华殿里一切器皿的样式，","notes":[]},{"n":14,"t":"以及各样应用金器的分两和各样应用银器的分两，","notes":[]},{"n":15,"t":"金灯台和金灯的分两，银灯台和银灯的分两，轻重各都合宜；","notes":[]},{"n":16,"t":"陈设饼金桌子的分两，银桌子的分两，","notes":[]},{"n":17,"t":"精金的肉叉子、盘子，和爵的分两，各金碗与各银碗的分两，","notes":[]},{"n":18,"t":"精金香坛的分两，并用金子做基路伯；基路伯张开翅膀，遮掩耶和华的约柜。","notes":["原文是用金子做车式的基路伯"]},{"n":19,"t":"大卫说：「这一切工作的样式都是耶和华用手划出来使我明白的。」","notes":[]},{"n":20,"t":"大卫又对他儿子所罗门说：「你当刚强壮胆去行！不要惧怕，也不要惊惶。因为耶和华神就是我的神，与你同在；他必不撇下你，也不丢弃你，直到耶和华殿的工作都完毕了。","notes":[]},{"n":21,"t":"有祭司和利未人的各班，为要办理神殿各样的事，又有灵巧的人在各样的工作上乐意帮助你；并有众首领和众民一心听从你的命令。」","notes":[]}]},"29":{"heading":"为建殿而献的礼物","verses":[{"n":1,"t":"大卫王对会众说：「我儿子所罗门是神特选的，还年幼娇嫩；这工程甚大，因这殿不是为人，乃是为耶和华神建造的。","notes":[]},{"n":2,"t":"我为我神的殿已经尽力，预备金子做金器，银子做银器，铜做铜器，铁做铁器，木做木器，还有红玛瑙可镶嵌的宝石，彩石和一切的宝石，并许多汉白玉。","notes":[]},{"n":3,"t":"且因我心中爱慕我神的殿，就在预备建造圣殿的材料之外，又将我自己积蓄的金银献上，建造我神的殿，","notes":[]},{"n":4,"t":"就是俄斐金三千他连得、精炼的银子七千他连得，以贴殿墙。","notes":[]},{"n":5,"t":"金子做金器，银子做银器，并借匠人的手制造一切。今日有谁乐意将自己献给耶和华呢？」","notes":[]},{"n":6,"t":"于是，众族长和以色列各支派的首领、千夫长、百夫长，并监管王工的官长，都乐意献上。","notes":[]},{"n":7,"t":"他们为神殿的使用献上金子五千他连得零一万达利克，银子一万他连得，铜一万八千他连得，铁十万他连得。","notes":[]},{"n":8,"t":"凡有宝石的都交给革顺人耶歇，送入耶和华殿的府库。","notes":[]},{"n":9,"t":"因这些人诚心乐意献给耶和华，百姓就欢喜，大卫王也大大欢喜。","notes":[]},{"n":10,"t":"所以，大卫在会众面前称颂耶和华说：「耶和华—我们的父，以色列的神是应当称颂，直到永永远远的！","notes":[],"heads":["大卫称颂耶和华"]},{"n":11,"t":"耶和华啊，尊大、能力、荣耀、强胜、威严都是你的；凡天上地下的都是你的；国度也是你的，并且你为至高，为万有之首。","notes":[]},{"n":12,"t":"丰富尊荣都从你而来，你也治理万物。在你手里有大能大力，使人尊大强盛都出于你。","notes":[]},{"n":13,"t":"我们的神啊，现在我们称谢你，赞美你荣耀之名！","notes":[]},{"n":14,"t":"「我算什么，我的民算什么，竟能如此乐意奉献？因为万物都从你而来，我们把从你而得的献给你。","notes":[]},{"n":15,"t":"我们在你面前是客旅，是寄居的，与我们列祖一样。我们在世的日子如影儿，不能长存。","notes":["或译：没有长存的指望"]},{"n":16,"t":"耶和华—我们的神啊，我们预备这许多材料，要为你的圣名建造殿宇，都是从你而来，都是属你的。","notes":[]},{"n":17,"t":"我的神啊，我知道你察验人心，喜悦正直；我以正直的心乐意献上这一切物。现在我喜欢见你的民在这里都乐意奉献与你。","notes":[]},{"n":18,"t":"耶和华—我们列祖亚伯拉罕、以撒、以色列的神啊，求你使你的民常存这样的心思意念，坚定他们的心归向你，","notes":[]},{"n":19,"t":"又求你赐我儿子所罗门诚实的心，遵守你的命令、法度、律例，成就这一切的事，用我所预备的建造殿宇。」","notes":[]},{"n":20,"t":"大卫对全会众说：「你们应当称颂耶和华—你们的神。」于是会众称颂耶和华—他们列祖的神，低头拜耶和华与王。","notes":[]},{"n":21,"t":"次日，他们向耶和华献平安祭和燔祭，就是献公牛一千只，公绵羊一千只，羊羔一千只，并同献的奠祭；又为以色列众人献许多的祭。那日，他们在耶和华面前吃喝，大大欢乐。","notes":[]},{"n":22,"t":"他们奉耶和华的命再膏大卫的儿子所罗门作王，又膏撒督作祭司。","notes":[]},{"n":23,"t":"于是所罗门坐在耶和华所赐的位上，接续他父亲大卫作王，万事亨通；以色列众人也都听从他。","notes":[]},{"n":24,"t":"众首领和勇士，并大卫王的众子，都顺服所罗门王。","notes":[]},{"n":25,"t":"耶和华使所罗门在以色列众人眼前甚为尊大，极其威严，胜过在他以前的以色列王。","notes":[]},{"n":26,"t":"耶西的儿子大卫作以色列众人的王，","notes":[],"heads":["大卫政绩简述"]},{"n":27,"t":"作王共四十年：在希伯仑作王七年，在耶路撒冷作王三十三年。","notes":[]},{"n":28,"t":"他年纪老迈，日子满足，享受丰富、尊荣，就死了。他儿子所罗门接续他作王。","notes":[]},{"n":29,"t":"大卫王始终的事都写在先见撒母耳的书上和先知拿单并先见迦得的书上。","notes":[]},{"n":30,"t":"他的国事和他的勇力，以及他和以色列并列国所经过的事都写在这书上。","notes":[]}]}},"2CH":{"1":{"heading":"所罗门王祈求智慧","verses":[{"n":1,"t":"大卫的儿子所罗门国位坚固；耶和华—他的神与他同在，使他甚为尊大。","notes":[]},{"n":2,"t":"所罗门吩咐以色列众人，就是千夫长、百夫长、审判官、首领与族长都来。","notes":[]},{"n":3,"t":"所罗门和会众都往基遍的邱坛去，因那里有神的会幕，就是耶和华仆人摩西在旷野所制造的。","notes":[]},{"n":4,"t":"只是神的约柜，大卫已经从基列·耶琳搬到他所预备的地方，因他曾在耶路撒冷为约柜支搭了帐幕，","notes":[]},{"n":5,"t":"并且户珥的孙子、乌利的儿子比撒列所造的铜坛也在基遍耶和华的会幕前。所罗门和会众都就近坛前。","notes":[]},{"n":6,"t":"所罗门上到耶和华面前会幕的铜坛那里，献一千牺牲为燔祭。","notes":[]},{"n":7,"t":"当夜，神向所罗门显现，对他说：「你愿我赐你什么，你可以求。」","notes":[]},{"n":8,"t":"所罗门对神说：「你曾向我父大卫大施慈爱，使我接续他作王。","notes":[]},{"n":9,"t":"耶和华神啊，现在求你成就向我父大卫所应许的话；因你立我作这民的王，他们如同地上尘沙那样多。","notes":[]},{"n":10,"t":"求你赐我智慧聪明，我好在这民前出入；不然，谁能判断这众多的民呢？」","notes":[]},{"n":11,"t":"神对所罗门说：「我已立你作我民的王。你既有这心意，并不求资财、丰富、尊荣，也不求灭绝那恨你之人的性命，又不求大寿数，只求智慧聪明好判断我的民；","notes":[]},{"n":12,"t":"我必赐你智慧聪明，也必赐你资财、丰富、尊荣。在你以前的列王都没有这样，在你以后也必没有这样的。」","notes":[]},{"n":13,"t":"于是，所罗门从基遍邱坛会幕前回到耶路撒冷，治理以色列人。","notes":[]},{"n":14,"t":"所罗门聚集战车马兵，有战车一千四百辆，马兵一万二千名，安置在屯车的城邑和耶路撒冷，就是王那里。","notes":[],"heads":["所罗门的权力和财力"]},{"n":15,"t":"王在耶路撒冷使金银多如石头，香柏木多如高原的桑树。","notes":[]},{"n":16,"t":"所罗门的马是从埃及带来的，是王的商人一群一群按着定价买来的。","notes":[]},{"n":17,"t":"他们从埃及买来的车，每辆价银六百舍客勒，马每匹一百五十舍客勒。赫人诸王和亚兰诸王所买的车马，也是按这价值经他们手买来的。","notes":[]}]},"2":{"heading":"筹备建造圣殿","verses":[{"n":1,"t":"所罗门定意要为耶和华的名建造殿宇，又为自己的国建造宫室。","notes":[]},{"n":2,"t":"所罗门就挑选七万扛抬的，八万在山上凿石头的，三千六百督工的。","notes":[]},{"n":3,"t":"所罗门差人去见泰尔王希兰，说：「你曾运香柏木与我父大卫建宫居住，求你也这样待我。","notes":[]},{"n":4,"t":"我要为耶和华—我神的名建造殿宇，分别为圣献给他，在他面前焚烧美香，常摆陈设饼，每早晚、安息日、月朔，并耶和华—我们神所定的节期献燔祭。这是以色列人永远的定例。","notes":[]},{"n":5,"t":"我所要建造的殿宇甚大；因为我们的神至大，超乎诸神。","notes":[]},{"n":6,"t":"天和天上的天，尚且不足他居住的，谁能为他建造殿宇呢？我是谁？能为他建造殿宇吗？不过在他面前烧香而已。","notes":[]},{"n":7,"t":"现在求你差一个巧匠来，就是善用金、银、铜、铁，和紫色、朱红色、蓝色线，并精于雕刻之工的巧匠，与我父大卫在犹大和耶路撒冷所预备的巧匠一同做工；","notes":[]},{"n":8,"t":"又求你从黎巴嫩运些香柏木、松木、檀香木到我这里来，因我知道你的仆人善于砍伐黎巴嫩的树木。我的仆人也必与你的仆人同工。","notes":[]},{"n":9,"t":"这样，可以给我预备许多的木料，因我要建造的殿宇高大出奇。","notes":[]},{"n":10,"t":"你的仆人砍伐树木，我必给他们打好了的小麦二万歌珥，大麦二万歌珥，酒二万罢特，油二万罢特。」","notes":[]},{"n":11,"t":"泰尔王希兰写信回答所罗门说：「耶和华因为爱他的子民，所以立你作他们的王」；","notes":[]},{"n":12,"t":"又说：「创造天地的耶和华—以色列的神是应当称颂的！他赐给大卫王一个有智慧的儿子，使他有谋略聪明，可以为耶和华建造殿宇，又为自己的国建造宫室。","notes":[]},{"n":13,"t":"「现在我打发一个精巧有聪明的人去，他是我父亲希兰所用的，","notes":[]},{"n":14,"t":"是但支派一个妇人的儿子。他父亲是泰尔人，他善用金、银、铜、铁、石、木，和紫色、蓝色、朱红色线与细麻制造各物，并精于雕刻，又能想出各样的巧工。请你派定这人，与你的巧匠和你父—我主大卫的巧匠一同做工。","notes":[]},{"n":15,"t":"我主所说的小麦、大麦、酒、油，愿我主运来给众仆人。","notes":[]},{"n":16,"t":"我们必照你所需用的，从黎巴嫩砍伐树木，扎成筏子，浮海运到约帕；你可以从那里运到耶路撒冷。」","notes":[]},{"n":17,"t":"所罗门仿照他父大卫数点住在以色列地所有寄居的外邦人，共有十五万三千六百名；","notes":[],"heads":["圣殿工程动工"]},{"n":18,"t":"使七万人扛抬材料，八万人在山上凿石头，三千六百人督理工作。","notes":[]}]},"3":{"heading":"两根铜柱","verses":[{"n":1,"t":"所罗门就在耶路撒冷、耶和华向他父大卫显现的摩利亚山上，就是耶布斯人阿珥楠的禾场上、大卫所指定的地方预备好了，开工建造耶和华的殿。","notes":[]},{"n":2,"t":"所罗门作王第四年二月初二日开工建造。","notes":[]},{"n":3,"t":"所罗门建筑神殿的根基，乃是这样：长六十肘，宽二十肘，都按着古时的尺寸。","notes":[]},{"n":4,"t":"殿前的廊子长二十肘，与殿的宽窄一样，高一百二十肘；里面贴上精金。","notes":[]},{"n":5,"t":"大殿的墙都用松木板遮蔽，又贴了精金，上面雕刻棕树和链子；","notes":[]},{"n":6,"t":"又用宝石装饰殿墙，使殿华美；所用的金子都是巴瓦音的金子。","notes":[]},{"n":7,"t":"又用金子贴殿和殿的栋梁、门槛、墙壁、门扇；墙上雕刻基路伯。","notes":[]},{"n":8,"t":"又建造至圣所，长二十肘，与殿的宽窄一样，宽也是二十肘；贴上精金，共用金子六百他连得。","notes":[]},{"n":9,"t":"金钉重五十舍客勒。楼房都贴上金子。","notes":[]},{"n":10,"t":"在至圣所按造像的法子造两个基路伯，用金子包裹。","notes":[]},{"n":11,"t":"两个基路伯的翅膀共长二十肘。这基路伯的一个翅膀长五肘，挨着殿这边的墙；那一个翅膀也长五肘，与那基路伯翅膀相接。","notes":[]},{"n":12,"t":"那基路伯的一个翅膀长五肘，挨着殿那边的墙；那一个翅膀也长五肘，与这基路伯的翅膀相接。","notes":[]},{"n":13,"t":"两个基路伯张开翅膀，共长二十肘，面向外殿而立。","notes":[]},{"n":14,"t":"又用蓝色、紫色、朱红色线和细麻织幔子，在其上绣出基路伯来。","notes":[]},{"n":15,"t":"在殿前造了两根柱子，高三十五肘；每柱顶高五肘。","notes":[]},{"n":16,"t":"又照圣所内链子的样式做链子，安在柱顶上；又做一百石榴，安在链子上。","notes":[]},{"n":17,"t":"将两根柱子立在殿前，一根在右边，一根在左边；右边的起名叫雅斤，左边的起名叫波阿斯。","notes":[]}]},"4":{"heading":"圣殿的设备","verses":[{"n":1,"t":"他又制造一座铜坛，长二十肘，宽二十肘，高十肘；","notes":[]},{"n":2,"t":"又铸一个铜海，样式是圆的，高五肘，径十肘，围三十肘；","notes":[]},{"n":3,"t":"海周围有野瓜的样式，每肘十瓜，共有两行，是铸海的时候铸上的；","notes":["野瓜：原文是牛"]},{"n":4,"t":"有十二只铜牛驮海：三只向北，三只向西，三只向南，三只向东；海在牛上，牛尾向内；","notes":[]},{"n":5,"t":"海厚一掌，边如杯边，又如百合花，可容三千罢特；","notes":[]},{"n":6,"t":"又制造十个盆：五个放在右边，五个放在左边，献燔祭所用之物都洗在其内；但海是为祭司沐浴的。","notes":[]},{"n":7,"t":"他又照所定的样式造十个金灯台放在殿里：五个在右边，五个在左边；","notes":[]},{"n":8,"t":"又造十张桌子放在殿里：五张在右边，五张在左边；又造一百个金碗；","notes":[]},{"n":9,"t":"又建立祭司院和大院，并院门，用铜包裹门扇；","notes":[]},{"n":10,"t":"将海安在殿门的右边，就是南边。","notes":[]},{"n":11,"t":"户兰又造了盆、铲、碗。这样，他为所罗门王做完了神殿的工。","notes":[]},{"n":12,"t":"所造的就是：两根柱子和柱上两个如球的顶，并两个盖柱顶的网子","notes":[]},{"n":13,"t":"和四百石榴，安在两个网子上（每网两行盖着两个柱上如球的顶）。","notes":[]},{"n":14,"t":"盆座和其上的盆，","notes":[]},{"n":15,"t":"海和海下的十二只牛，","notes":[]},{"n":16,"t":"盆、铲子、肉锸子，与耶和华殿里的一切器皿，都是巧匠户兰用光亮的铜为所罗门王造成的，","notes":[]},{"n":17,"t":"是在约旦平原疏割和撒利但中间借胶泥铸成的。","notes":[]},{"n":18,"t":"所罗门制造的这一切甚多，铜的轻重无法可查。","notes":[]},{"n":19,"t":"所罗门又造神殿里的金坛和陈设饼的桌子，","notes":[]},{"n":20,"t":"并精金的灯台和灯盏，可以照例点在内殿前。","notes":[]},{"n":21,"t":"灯台上的花和灯盏，并蜡剪都是金的，且是纯金的；","notes":[]},{"n":22,"t":"又用精金制造镊子、盘子、调羹、火鼎。至于殿门和至圣所的门扇，并殿的门扇，都是金子妆饰的。","notes":[]}]},"5":{"heading":"运约柜入殿","verses":[{"n":1,"t":"所罗门做完了耶和华殿的一切工，就把他父大卫分别为圣的金银和器皿都带来，放在神殿的府库里。","notes":[]},{"n":2,"t":"那时，所罗门将以色列的长老、各支派的首领，并以色列的族长招聚到耶路撒冷，要把耶和华的约柜从大卫城—就是锡安—运上来。","notes":[]},{"n":3,"t":"于是以色列众人在七月节前都聚集到王那里。","notes":[]},{"n":4,"t":"以色列众长老来到，利未人便抬起约柜。","notes":[]},{"n":5,"t":"祭司利未人将约柜运上来，又将会幕和会幕的一切圣器具都带上来。","notes":[]},{"n":6,"t":"所罗门王和聚集到他那里的以色列全会众都在约柜前献牛羊为祭，多得不可胜数。","notes":[]},{"n":7,"t":"祭司将耶和华的约柜抬进内殿，就是至圣所，放在两个基路伯的翅膀底下。","notes":[]},{"n":8,"t":"基路伯张着翅膀在约柜之上，遮掩约柜和抬柜的杠。","notes":[]},{"n":9,"t":"这杠甚长，杠头在内殿前可以看见，在殿外却不能看见，直到如今还在那里。","notes":[]},{"n":10,"t":"约柜里惟有两块石版，就是以色列人出埃及后，耶和华与他们立约的时候，摩西在何烈山所放的。除此以外，并无别物。","notes":[]},{"n":11,"t":"当时，在那里所有的祭司都已自洁，并不分班供职。","notes":[],"heads":["神的荣光"]},{"n":12,"t":"他们出圣所的时候，歌唱的利未人亚萨、希幔、耶杜顿，和他们的众子众弟兄都穿细麻布衣服，站在坛的东边，敲钹、鼓瑟、弹琴，同着他们有一百二十个祭司吹号。","notes":[]},{"n":13,"t":"吹号的、歌唱的都一齐发声，声合为一，赞美感谢耶和华。吹号、敲钹，用各种乐器，扬声赞美耶和华说：耶和华本为善，他的慈爱永远长存！那时，耶和华的殿有云充满，","notes":[]},{"n":14,"t":"甚至祭司不能站立供职，因为耶和华的荣光充满了神的殿。","notes":[]}]},"6":{"heading":"所罗门向人民宣告","verses":[{"n":1,"t":"那时，所罗门说：耶和华曾说他必住在幽暗之处。","notes":[]},{"n":2,"t":"但我已经建造殿宇作你的居所，为你永远的住处。","notes":[]},{"n":3,"t":"王转脸为以色列会众祝福，以色列会众就都站立。","notes":[]},{"n":4,"t":"所罗门说：「耶和华—以色列的神是应当称颂的！因他亲口向我父大卫所应许的，也亲手成就了。","notes":[]},{"n":5,"t":"他说：『自从我领我民出埃及地以来，我未曾在以色列众支派中选择一城建造殿宇为我名的居所，也未曾拣选一人作我民以色列的君；","notes":[]},{"n":6,"t":"但选择耶路撒冷为我名的居所，又拣选大卫治理我民以色列。』」","notes":[]},{"n":7,"t":"所罗门说：「我父大卫曾立意要为耶和华—以色列神的名建殿，","notes":[]},{"n":8,"t":"耶和华却对我父大卫说：『你立意要为我的名建殿，这意思甚好；","notes":[]},{"n":9,"t":"只是你不可建殿，惟你所生的儿子必为我名建殿。』","notes":[]},{"n":10,"t":"「现在耶和华成就了他所应许的话，使我接续我父大卫坐以色列的国位，是照耶和华所说的，又为耶和华—以色列神的名建造了殿。","notes":[]},{"n":11,"t":"我将约柜安置在其中，柜内有耶和华的约，就是他与以色列人所立的约。」","notes":[]},{"n":12,"t":"所罗门当着以色列会众，站在耶和华的坛前，举起手来，","notes":[],"heads":["所罗门的祷告"]},{"n":13,"t":"（所罗门曾造一个铜台，长五肘，宽五肘，高三肘，放在院中）就站在台上，当着以色列的会众跪下，向天举手，","notes":[]},{"n":14,"t":"说：「耶和华—以色列的神啊，天上地下没有神可比你的！你向那尽心行在你面前的仆人守约施慈爱；","notes":[]},{"n":15,"t":"向你仆人—我父大卫所应许的话现在应验了。你亲口应许，亲手成就，正如今日一样。","notes":[]},{"n":16,"t":"耶和华—以色列的神啊，你所应许你仆人—我父大卫的话说：『你的子孙若谨慎自己的行为，遵守我的律法，像你在我面前所行的一样，就不断人坐以色列的国位。』现在求你应验这话。","notes":[]},{"n":17,"t":"耶和华—以色列的神啊，求你成就向你仆人大卫所应许的话。","notes":[]},{"n":18,"t":"「神果真与世人同住在地上吗？看哪，天和天上的天尚且不足你居住的，何况我所建的这殿呢？","notes":[]},{"n":19,"t":"惟求耶和华—我的神垂顾仆人的祷告祈求，俯听仆人在你面前的祈祷呼吁。","notes":[]},{"n":20,"t":"愿你昼夜看顾这殿，就是你应许立为你名的居所；求你垂听仆人向此处祷告的话。","notes":[]},{"n":21,"t":"你仆人和你民以色列向此处祈祷的时候，求你从天上你的居所垂听，垂听而赦免。","notes":[]},{"n":22,"t":"「人若得罪邻舍，有人叫他起誓，他来到这殿，在你的坛前起誓，","notes":[]},{"n":23,"t":"求你从天上垂听，判断你的仆人，定恶人有罪，照他所行的报应在他头上；定义人有理，照他的义赏赐他。","notes":[]},{"n":24,"t":"「你的民以色列若得罪你，败在仇敌面前，又回心转意承认你的名，在这殿里向你祈求祷告，","notes":[]},{"n":25,"t":"求你从天上垂听，赦免你民以色列的罪，使他们归回你赐给他们和他们列祖之地。","notes":[]},{"n":26,"t":"「你的民因得罪你，你惩罚他们，使天闭塞不下雨，他们若向此处祷告，承认你的名，离开他们的罪，","notes":[]},{"n":27,"t":"求你在天上垂听，赦免你仆人和你民以色列的罪，将当行的善道指教他们，且降雨在你的地，就是你赐给你民为业之地。","notes":[]},{"n":28,"t":"「国中若有饥荒、瘟疫、旱风、霉烂、蝗虫、蚂蚱，或有仇敌犯境，围困城邑，无论遭遇什么灾祸疾病，","notes":[]},{"n":29,"t":"你的民以色列，或是众人，或是一人，自觉灾祸甚苦，向这殿举手，无论祈求什么，祷告什么，","notes":[]},{"n":30,"t":"求你从天上你的居所垂听赦免。你是知道人心的，要照各人所行的待他们（惟有你知道世人的心），","notes":[]},{"n":31,"t":"使他们在你赐给我们列祖之地上一生一世敬畏你，遵行你的道。","notes":[]},{"n":32,"t":"「论到不属你民以色列的外邦人，为你的大名和大能的手，并伸出来的膀臂，从远方而来，向这殿祷告，","notes":[]},{"n":33,"t":"求你从天上你的居所垂听，照着外邦人所祈求的而行，使天下万民都认识你的名，敬畏你，像你的民以色列一样，又使他们知道我建造的这殿是称为你名下的。","notes":[]},{"n":34,"t":"「你的民若奉你的差遣，无论往何处去与仇敌争战，向你所选择的城与我为你名所建造的殿祷告，","notes":[]},{"n":35,"t":"求你从天上垂听他们的祷告祈求，使他们得胜。","notes":[]},{"n":36,"t":"「你的民若得罪你（世上没有不犯罪的人），你向他们发怒，将他们交给仇敌掳到或远或近之地；","notes":[]},{"n":37,"t":"他们若在掳到之地想起罪来，回心转意，恳求你说：『我们有罪了，我们悖逆了，我们作恶了』；","notes":[]},{"n":38,"t":"他们若在掳到之地尽心尽性归服你，又向自己的地，就是你赐给他们列祖之地和你所选择的城，并我为你名所建造的殿祷告，","notes":[]},{"n":39,"t":"求你从天上你的居所垂听你民的祷告祈求，为他们伸冤，赦免他们的过犯。","notes":[]},{"n":40,"t":"「我的神啊，现在求你睁眼看，侧耳听在此处所献的祷告。","notes":[]},{"n":41,"t":"耶和华神啊，求你起来，和你有能力的约柜同入安息之所。耶和华神啊，愿你的祭司披上救恩；愿你的圣民蒙福欢乐。","notes":[]},{"n":42,"t":"耶和华神啊，求你不要厌弃你的受膏者，要记念向你仆人大卫所施的慈爱。」","notes":[]}]},"7":{"heading":"圣殿奉献礼","verses":[{"n":1,"t":"所罗门祈祷已毕，就有火从天上降下来，烧尽燔祭和别的祭。耶和华的荣光充满了殿；","notes":[]},{"n":2,"t":"因耶和华的荣光充满了耶和华殿，所以祭司不能进殿。","notes":[]},{"n":3,"t":"那火降下、耶和华的荣光在殿上的时候，以色列众人看见，就在铺石地俯伏叩拜，称谢耶和华说：耶和华本为善，他的慈爱永远长存！","notes":[]},{"n":4,"t":"王和众民在耶和华面前献祭。","notes":[]},{"n":5,"t":"所罗门王用牛二万二千，羊十二万献祭。这样，王和众民为神的殿行奉献之礼。","notes":[]},{"n":6,"t":"祭司侍立，各供其职；利未人也拿着耶和华的乐器，就是大卫王造出来、借利未人颂赞耶和华的。（他的慈爱永远长存！）祭司在众人面前吹号，以色列人都站立。","notes":[]},{"n":7,"t":"所罗门因他所造的铜坛容不下燔祭、素祭，和脂油，便将耶和华殿前院子当中分别为圣，在那里献燔祭和平安祭牲的脂油。","notes":[]},{"n":8,"t":"那时所罗门和以色列众人，就是从哈马口直到埃及小河，所有的以色列人都聚集成为大会，守节七日。","notes":[]},{"n":9,"t":"第八日设立严肃会，行奉献坛的礼七日，守节七日。","notes":[]},{"n":10,"t":"七月二十三日，王遣散众民；他们因见耶和华向大卫和所罗门与他民以色列所施的恩惠，就都心中喜乐，各归各家去了。","notes":[]},{"n":11,"t":"所罗门造成了耶和华殿和王宫；在耶和华殿和王宫凡他心中所要做的，都顺顺利利地做成了。","notes":[],"heads":["神再次向所罗门显现"]},{"n":12,"t":"夜间耶和华向所罗门显现，对他说：「我已听了你的祷告，也选择这地方作为祭祀我的殿宇。","notes":[]},{"n":13,"t":"我若使天闭塞不下雨，或使蝗虫吃这地的出产，或使瘟疫流行在我民中，","notes":[]},{"n":14,"t":"这称为我名下的子民，若是自卑、祷告，寻求我的面，转离他们的恶行，我必从天上垂听，赦免他们的罪，医治他们的地。","notes":[]},{"n":15,"t":"我必睁眼看、侧耳听在此处所献的祷告。","notes":[]},{"n":16,"t":"现在我已选择这殿，分别为圣，使我的名永在其中，我的眼、我的心也必常在那里。","notes":[]},{"n":17,"t":"你若在我面前效法你父大卫所行的，遵行我一切所吩咐你的，谨守我的律例典章，","notes":[]},{"n":18,"t":"我就必坚固你的国位，正如我与你父大卫所立的约，说：『你的子孙必不断人作以色列的王。』","notes":[]},{"n":19,"t":"「倘若你们转去丢弃我指示你们的律例诫命，去事奉敬拜别神，","notes":[]},{"n":20,"t":"我就必将以色列人从我赐给他们的地上拔出根来，并且我为己名所分别为圣的殿也必舍弃不顾，使他在万民中作笑谈，被讥诮。","notes":[]},{"n":21,"t":"这殿虽然甚高，将来经过的人必惊讶说：『耶和华为何向这地和这殿如此行呢？』","notes":[]},{"n":22,"t":"人必回答说：『是因此地的人离弃耶和华—他们列祖的神，就是领他们出埃及地的神，去亲近别神，敬拜事奉他，所以耶和华使这一切灾祸临到他们。』」","notes":[]}]},"8":{"heading":"所罗门的成就","verses":[{"n":1,"t":"所罗门建造耶和华殿和王宫，二十年才完毕了。","notes":[]},{"n":2,"t":"以后所罗门重新修筑希兰送给他的那些城邑，使以色列人住在那里。","notes":[]},{"n":3,"t":"所罗门往哈马琐巴去，攻取了那地方。","notes":[]},{"n":4,"t":"所罗门建造旷野里的达莫，又建造哈马所有的积货城，","notes":[]},{"n":5,"t":"又建造上伯·和仑、下伯·和仑作为保障，都有墙，有门，有闩；","notes":[]},{"n":6,"t":"又建造巴拉和所有的积货城，并屯车辆马兵的城，与耶路撒冷、黎巴嫩，以及自己治理的全国中所愿意建造的。","notes":[]},{"n":7,"t":"至于国中所剩下不属以色列人的赫人、亚摩利人、比利洗人、希未人、耶布斯人，","notes":[]},{"n":8,"t":"就是以色列人未曾灭绝的，所罗门挑取他们的后裔作服苦的奴仆，直到今日。","notes":[]},{"n":9,"t":"惟有以色列人，所罗门不使他们当奴仆做工，乃是作他的战士、军长的统领、车兵长、马兵长。","notes":[]},{"n":10,"t":"所罗门王有二百五十督工的，监管工人。","notes":[]},{"n":11,"t":"所罗门将法老的女儿带出大卫城，上到为她建造的宫里；因所罗门说：「耶和华约柜所到之处都为圣地，所以我的妻不可住在以色列王大卫的宫里。」","notes":[]},{"n":12,"t":"所罗门在耶和华的坛上，就是在廊子前他所筑的坛上，与耶和华献燔祭；","notes":[]},{"n":13,"t":"又遵着摩西的吩咐在安息日、月朔，并一年三节，就是除酵节、七七节、住棚节，献每日所当献的祭。","notes":[]},{"n":14,"t":"所罗门照着他父大卫所定的例，派定祭司的班次，使他们各供己事，又使利未人各尽其职，赞美耶和华，在祭司面前做每日所当做的；又派守门的按着班次看守各门，因为神人大卫是这样吩咐的。","notes":[]},{"n":15,"t":"王所吩咐众祭司和利未人的，无论是管府库或办别的事，他们都不违背。","notes":[]},{"n":16,"t":"所罗门建造耶和华的殿，从立根基直到成功的日子，工料俱备。这样，耶和华的殿全然完毕。","notes":[]},{"n":17,"t":"那时，所罗门往以东地靠海的以旬·迦别和以禄去。","notes":[]},{"n":18,"t":"希兰差遣他的臣仆，将船只和熟悉泛海的仆人送到所罗门那里。他们同着所罗门的仆人到了俄斐，得了四百五十他连得金子，运到所罗门王那里。","notes":[]}]},"9":{"heading":"示巴女王访问所罗门","verses":[{"n":1,"t":"示巴女王听见所罗门的名声，就来到耶路撒冷，要用难解的话试问所罗门；跟随她的人甚多，又有骆驼驮着香料、宝石，和许多金子。她来见了所罗门，就把心里所有的对所罗门都说出来。","notes":[]},{"n":2,"t":"所罗门将她所问的都答上了，没有一句不明白、不能答的。","notes":[]},{"n":3,"t":"示巴女王见所罗门的智慧和他所建造的宫室、","notes":[]},{"n":4,"t":"席上的珍馐美味、群臣分列而坐、仆人两旁侍立，以及他们的衣服装饰、酒政，和酒政的衣服装饰，又见他上耶和华殿的台阶，就诧异得神不守舍，","notes":[]},{"n":5,"t":"对王说：「我在本国里所听见论到你的事和你的智慧实在是真的！","notes":[]},{"n":6,"t":"我先不信那些话，及至我来亲眼见了，才知道你的大智慧；人所告诉我的，还不到一半；你的实迹越过我所听见的名声。","notes":[]},{"n":7,"t":"你的群臣、你的仆人常侍立在你面前听你智慧的话是有福的。","notes":[]},{"n":8,"t":"耶和华—你的神是应当称颂的！他喜悦你，使你坐他的国位，为耶和华—你的神作王；因为你的神爱以色列人，要永远坚立他们，所以立你作他们的王，使你秉公行义。」","notes":[]},{"n":9,"t":"于是示巴女王将一百二十他连得金子和宝石，与极多的香料送给所罗门王；她送给王的香料，以后再没有这样的。","notes":[]},{"n":10,"t":"希兰的仆人和所罗门的仆人从俄斐运了金子来，也运了檀香木和宝石来。","notes":["或译：乌木；下同"]},{"n":11,"t":"王用檀香木为耶和华殿和王宫做台，又为歌唱的人做琴瑟；犹大地从来没有见过这样的。","notes":[]},{"n":12,"t":"所罗门王按示巴女王所带来的，还她礼物，另外照她一切所要所求的，都送给她。于是女王和她臣仆转回本国去了。","notes":[]},{"n":13,"t":"所罗门每年所得的金子共有六百六十六他连得，","notes":[],"heads":["所罗门王的财富"]},{"n":14,"t":"另外还有商人所进的金子，并且阿拉伯诸王与属国的省长都带金银给所罗门。","notes":[]},{"n":15,"t":"所罗门王用锤出来的金子打成挡牌二百面，每面用金子六百舍客勒；","notes":[]},{"n":16,"t":"又用锤出来的金子打成盾牌三百面，每面用金子三百舍客勒，都放在黎巴嫩林宫里。","notes":[]},{"n":17,"t":"王用象牙制造一个大宝座，用精金包裹。","notes":[]},{"n":18,"t":"宝座有六层台阶，又有金脚凳，与宝座相连。宝座两旁有扶手，靠近扶手有两个狮子站立。","notes":[]},{"n":19,"t":"六层台阶上有十二个狮子站立，每层有两个：左边一个，右边一个；在列国中没有这样做的。","notes":[]},{"n":20,"t":"所罗门王一切的饮器都是金的，黎巴嫩林宫里的一切器皿都是精金的。所罗门年间，银子算不了什么。","notes":[]},{"n":21,"t":"因为王的船只与希兰的仆人一同往他施去；他施船只三年一次装载金、银、象牙、猿猴、孔雀回来。","notes":[]},{"n":22,"t":"所罗门王的财宝与智慧胜过天下的列王。","notes":[]},{"n":23,"t":"普天下的王都求见所罗门，要听神赐给他智慧的话。","notes":[]},{"n":24,"t":"他们各带贡物，就是金器、银器、衣服、军械、香料、骡马，每年有一定之例。","notes":[]},{"n":25,"t":"所罗门有套车的马四千棚，有马兵一万二千，安置在屯车的城邑和耶路撒冷，就是王那里。","notes":[]},{"n":26,"t":"所罗门统管诸王，从大河到非利士地，直到埃及的边界。","notes":[]},{"n":27,"t":"王在耶路撒冷使银子多如石头，香柏木多如高原的桑树。","notes":[]},{"n":28,"t":"有人从埃及和各国为所罗门赶马群来。","notes":[]},{"n":29,"t":"所罗门其余的事，自始至终，不都写在先知拿单的书上和示罗人亚希雅的预言书上，并先见易多论尼八儿子耶罗波安的默示书上吗？","notes":[],"heads":["所罗门政绩简述"]},{"n":30,"t":"所罗门在耶路撒冷作以色列众人的王共四十年。","notes":[]},{"n":31,"t":"所罗门与他列祖同睡，葬在他父大卫城里。他儿子罗波安接续他作王。","notes":[]}]},"10":{"heading":"北部支派的反叛","verses":[{"n":1,"t":"罗波安往示剑去，因为以色列人都到了示剑，要立他作王。","notes":[]},{"n":2,"t":"尼八的儿子耶罗波安先前躲避所罗门王，逃往埃及，住在那里；他听见这事，就从埃及回来。","notes":[]},{"n":3,"t":"以色列人打发人去请他，他就和以色列众人来见罗波安，对他说：","notes":[]},{"n":4,"t":"「你父亲使我们负重轭做苦工，现在求你使我们做的苦工负的重轭轻松些，我们就事奉你。」","notes":[]},{"n":5,"t":"罗波安对他们说：「第三日再来见我吧！」民就去了。","notes":[]},{"n":6,"t":"罗波安之父所罗门在世的日子，有侍立在他面前的老年人，罗波安王和他们商议，说：「你们给我出个什么主意，我好回复这民。」","notes":[]},{"n":7,"t":"老年人对他说：「王若恩待这民，使他们喜悦，用好话回复他们，他们就永远作王的仆人。」","notes":[]},{"n":8,"t":"王却不用老年人给他出的主意，就和那些与他一同长大、在他面前侍立的少年人商议，","notes":[]},{"n":9,"t":"说：「这民对我说：『你父亲使我们负重轭，求你使我们轻松些』；你们给我出个什么主意，我好回复他们。」","notes":[]},{"n":10,"t":"那同他长大的少年人说：「这民对王说：『你父亲使我们负重轭，求你使我们轻松些』；王要对他们如此说：『我的小拇指比我父亲的腰还粗；","notes":[]},{"n":11,"t":"我父亲使你们负重轭，我必使你们负更重的轭；我父亲用鞭子责打你们，我要用蝎子鞭责打你们。』」","notes":[]},{"n":12,"t":"耶罗波安和众百姓遵着罗波安王所说「你们第三日再来见我」的那话，第三日他们果然来了。","notes":[]},{"n":13,"t":"罗波安王用严厉的话回复他们，不用老年人所出的主意，","notes":[]},{"n":14,"t":"照着少年人所出的主意对他们说：「我父亲使你们负重轭，我必使你们负更重的轭；我父亲用鞭子责打你们，我要用蝎子鞭责打你们。」","notes":[]},{"n":15,"t":"王不肯依从百姓；这事乃出于神，为要应验耶和华借示罗人亚希雅对尼八儿子耶罗波安所说的话。","notes":[]},{"n":16,"t":"以色列众民见王不依从他们，就对王说：我们与大卫有什么分儿呢？与耶西的儿子并没有关涉！以色列人哪，各回各家去吧！大卫家啊，自己顾自己吧！于是，以色列众人都回自己家里去了。","notes":[]},{"n":17,"t":"惟独住在犹大城邑的以色列人，罗波安仍作他们的王。","notes":[]},{"n":18,"t":"罗波安王差遣掌管服苦之人的哈多兰往以色列人那里去，以色列人就用石头打死他。罗波安王急忙上车，逃回耶路撒冷去了。","notes":[]},{"n":19,"t":"这样，以色列人背叛大卫家，直到今日。","notes":[]}]},"11":{"heading":"示玛雅的预言","verses":[{"n":1,"t":"罗波安来到耶路撒冷，招聚犹大家和便雅悯家，共十八万人，都是挑选的战士，要与以色列人争战，好将国夺回再归自己。","notes":[]},{"n":2,"t":"但耶和华的话临到神人示玛雅说：","notes":[]},{"n":3,"t":"「你去告诉所罗门的儿子犹大王罗波安和住犹大、便雅悯的以色列众人说，","notes":[]},{"n":4,"t":"耶和华如此说：『你们不可上去与你们的弟兄争战，各归各家去吧！因为这事出于我。』」众人就听从耶和华的话归回，不去与耶罗波安争战。","notes":[]},{"n":5,"t":"罗波安住在耶路撒冷，在犹大地修筑城邑，","notes":[],"heads":["罗波安修筑诸城"]},{"n":6,"t":"为保障修筑伯利恒、以坦、提哥亚、","notes":[]},{"n":7,"t":"伯·夙、梭哥、亚杜兰、","notes":[]},{"n":8,"t":"迦特、玛利沙、西弗、","notes":[]},{"n":9,"t":"亚多莱音、拉吉、亚西加、","notes":[]},{"n":10,"t":"琐拉、亚雅仑、希伯仑。这都是犹大和便雅悯的坚固城。","notes":[]},{"n":11,"t":"罗波安又坚固各处的保障，在其中安置军长，又预备下粮食、油、酒。","notes":[]},{"n":12,"t":"他在各城里预备盾牌和枪，且使城极其坚固。犹大和便雅悯都归了他。","notes":[]},{"n":13,"t":"以色列全地的祭司和利未人都从四方来归罗波安。","notes":[],"heads":["祭司和利未人都归犹大"]},{"n":14,"t":"利未人撇下他们的郊野和产业，来到犹大与耶路撒 冷，是因耶罗波安和他的儿子拒绝他们，不许他们供祭司职分事奉耶和华。","notes":[]},{"n":15,"t":"耶罗波安为邱坛、为鬼魔、为自己所铸造的牛犊设立祭司。","notes":["原文是公山羊"]},{"n":16,"t":"以色列各支派中，凡立定心意寻求耶和华—以色列神的，都随从利未人，来到耶路撒冷祭祀耶和华—他们列祖的神。","notes":[]},{"n":17,"t":"这样，就坚固犹大国，使所罗门的儿子罗波安强盛三年，因为他们三年遵行大卫和所罗门的道。","notes":[]},{"n":18,"t":"罗波安娶大卫儿子耶利摩的女儿玛哈拉为妻，又娶耶西儿子以利押的女儿亚比孩为妻。","notes":[],"heads":["罗波安的家室"]},{"n":19,"t":"从她生了几个儿子，就是耶乌施、示玛利雅、撒罕。","notes":[]},{"n":20,"t":"后来又娶押沙龙的女儿玛迦，从她生了亚比雅、亚太、细撒、示罗密。","notes":["十三章二节是乌列的女儿米该雅"]},{"n":21,"t":"罗波安娶十八个妻，立六十个妾，生二十八个儿子，六十个女儿；他却爱押沙龙的女儿玛迦，比爱别的妻妾更甚。","notes":[]},{"n":22,"t":"罗波安立玛迦的儿子亚比雅作太子，在他弟兄中为首，因为想要立他接续作王。","notes":[]},{"n":23,"t":"罗波安办事精明，使他众子分散在犹大和便雅悯全地各坚固城里，又赐他们许多粮食，为他们多寻妻子。","notes":[]}]},"12":{"heading":"埃及侵犯犹大","verses":[{"n":1,"t":"罗波安的国坚立，他强盛的时候就离弃耶和华的律法，以色列人也都随从他。","notes":[]},{"n":2,"t":"罗波安王第五年，埃及王示撒上来攻打耶路撒冷，因为王和民得罪了耶和华。","notes":[]},{"n":3,"t":"示撒带战车一千二百辆，马兵六万，并且跟从他出埃及的路比人、苏基人，和古实人，多得不可胜数。","notes":[]},{"n":4,"t":"他攻取了犹大的坚固城，就来到耶路撒冷。","notes":[]},{"n":5,"t":"那时，犹大的首领因为示撒就聚集在耶路撒冷。有先知示玛雅去见罗波安和众首领，对他们说：「耶和华如此说：『你们离弃了我，所以我使你们落在示撒手里。』」","notes":[]},{"n":6,"t":"于是王和以色列的众首领都自卑说：「耶和华是公义的。」","notes":[]},{"n":7,"t":"耶和华见他们自卑，耶和华的话就临到示玛雅说：「他们既自卑，我必不灭绝他们；必使他们略得拯救，我不借着示撒的手将我的怒气倒在耶路撒冷。","notes":[]},{"n":8,"t":"然而他们必作示撒的仆人，好叫他们知道，服事我与服事外邦人有何分别。」","notes":[]},{"n":9,"t":"于是，埃及王示撒上来攻取耶路撒冷，夺了耶和华殿和王宫里的宝物，尽都带走，又夺去所罗门制造的金盾牌。","notes":[]},{"n":10,"t":"罗波安王制造铜盾牌代替那金盾牌，交给守王宫门的护卫长看守。","notes":[]},{"n":11,"t":"王每逢进耶和华的殿，护卫兵就拿这盾牌，随后仍将盾牌送回，放在护卫房。","notes":[]},{"n":12,"t":"王自卑的时候，耶和华的怒气就转消了，不将他灭尽，并且在犹大中间也有善益的事。","notes":[]},{"n":13,"t":"罗波安王自强，在耶路撒冷作王。他登基的时候年四十一岁，在耶路撒冷，就是耶和华从以色列众支派中所选择立他名的城，作王十七年。罗波安的母亲名叫拿玛，是亚扪人。","notes":[],"heads":["罗波安政绩简述"]},{"n":14,"t":"罗波安行恶，因他不立定心意寻求耶和华。","notes":[]},{"n":15,"t":"罗波安所行的事，自始至终不都写在先知示玛雅和先见易多的史记上吗？罗波安与耶罗波安时常争战。","notes":[]},{"n":16,"t":"罗波安与他列祖同睡，葬在大卫城里。他儿子亚比雅接续他作王。","notes":[]}]},"13":{"heading":"亚比雅与耶罗波安争战","verses":[{"n":1,"t":"耶罗波安王十八年，亚比雅登基作犹大王，","notes":[]},{"n":2,"t":"在耶路撒冷作王三年。他母亲名叫米该亚，是基比亚人乌列的女儿。亚比雅常与耶罗波安争战。","notes":["又作玛迦"]},{"n":3,"t":"有一次亚比雅率领挑选的兵四十万摆阵，都是勇敢的战士；耶罗波安也挑选大能的勇士八十万，对亚比雅摆阵。","notes":[]},{"n":4,"t":"亚比雅站在以法莲山地中的洗玛脸山上，说：「耶罗波安和以色列众人哪，要听我说！","notes":[]},{"n":5,"t":"耶和华—以色列的神曾立盐约，将以色列国永远赐给大卫和他的子孙，你们不知道吗？","notes":["盐就是不废坏的意思"]},{"n":6,"t":"无奈大卫儿子所罗门的臣仆、尼八儿子耶罗波安起来背叛他的主人。","notes":[]},{"n":7,"t":"有些无赖的匪徒聚集跟从他，逞强攻击所罗门的儿子罗波安；那时罗波安还幼弱，不能抵挡他们。","notes":[]},{"n":8,"t":"「现在你们有意抗拒大卫子孙手下所治耶和华的国，你们的人也甚多，你们那里又有耶罗波安为你们所造当作神的金牛犊。","notes":[]},{"n":9,"t":"你们不是驱逐耶和华的祭司亚伦的后裔和利未人吗？不是照着外邦人的恶俗为自己立祭司吗？无论何人牵一只公牛犊、七只公绵羊将自己分别出来，就可作虚无之神的祭司。","notes":[]},{"n":10,"t":"至于我们，耶和华是我们的神，我们并没有离弃他。我们有事奉耶和华的祭司，都是亚伦的后裔，并有利未人各尽其职，","notes":[]},{"n":11,"t":"每日早晚向耶和华献燔祭，烧美香，又在精金的桌子上摆陈设饼；又有金灯台和灯盏，每晚点起，因为我们遵守耶和华—我们神的命；惟有你们离弃了他。","notes":[]},{"n":12,"t":"率领我们的是神，我们这里也有神的祭司拿号向你们吹出大声。以色列人哪，不要与耶和华—你们列祖的神争战，因你们必不能亨通。」","notes":[]},{"n":13,"t":"耶罗波安却在犹大人的后头设伏兵。这样，以色列人在犹大人的前头，伏兵在犹大人的后头。","notes":[]},{"n":14,"t":"犹大人回头观看，见前后都有敌兵，就呼求耶和华，祭司也吹号。","notes":[]},{"n":15,"t":"于是犹大人呐喊；犹大人呐喊的时候，神就使耶罗波安和以色列众人败在亚比雅与犹大人面前。","notes":[]},{"n":16,"t":"以色列人在犹大人面前逃跑，神将他们交在犹大人手里。","notes":[]},{"n":17,"t":"亚比雅和他的军兵大大杀戮以色列人，以色列人仆倒死亡的精兵有五十万。","notes":[]},{"n":18,"t":"那时，以色列人被制伏了，犹大人得胜，是因倚靠耶和华—他们列祖的神。","notes":[]},{"n":19,"t":"亚比雅追赶耶罗波安，攻取了他的几座城，就是伯特利和属伯特利的镇市，耶沙拿和属耶沙拿的镇市，以法拉音和属以法拉音的镇市。","notes":["或译：以弗伦"]},{"n":20,"t":"亚比雅在世的时候，耶罗波安不能再强盛；耶和华攻击他，他就死了。","notes":[]},{"n":21,"t":"亚比雅却渐渐强盛，娶妻妾十四个，生了二十二个儿子，十六个女儿。","notes":[]},{"n":22,"t":"亚比雅其余的事和他的言行都写在先知易多的传上。","notes":[]}]},"14":{"heading":"亚撒王击败古实人","verses":[{"n":1,"t":"亚比雅与他列祖同睡，葬在大卫城里。他儿子亚撒接续他作王。亚撒年间，国中太平十年。","notes":[]},{"n":2,"t":"亚撒行耶和华—他神眼中看为善为正的事，","notes":[]},{"n":3,"t":"除掉外邦神的坛和邱坛，打碎柱像，砍下木偶，","notes":[]},{"n":4,"t":"吩咐犹大人寻求耶和华—他们列祖的神，遵行他的律法、诫命；","notes":[]},{"n":5,"t":"又在犹大各城邑除掉邱坛和日像，那时国享太平；","notes":[]},{"n":6,"t":"又在犹大建造了几座坚固城。国中太平数年，没有战争，因为耶和华赐他平安。","notes":[]},{"n":7,"t":"他对犹大人说：「我们要建造这些城邑，四围筑墙，盖楼，安门，做闩；地还属我们，是因寻求耶和华—我们的神；我们既寻求他，他就赐我们四境平安。」于是建造城邑，诸事亨通。","notes":[]},{"n":8,"t":"亚撒的军兵，出自犹大拿盾牌拿枪的三十万人；出自便雅悯拿盾牌拉弓的二十八万人。这都是大能的勇士。","notes":[]},{"n":9,"t":"有古实王谢拉率领军兵一百万，战车三百辆，出来攻击犹大人，到了玛利沙。","notes":[]},{"n":10,"t":"于是亚撒出去与他迎敌，就在玛利沙的洗法谷彼此摆阵。","notes":[]},{"n":11,"t":"亚撒呼求耶和华—他的神说：「耶和华啊，惟有你能帮助软弱的，胜过强盛的。耶和华—我们的神啊，求你帮助我们；因为我们仰赖你，奉你的名来攻击这大军。耶和华啊，你是我们的神，不要容人胜过你。」","notes":[]},{"n":12,"t":"于是耶和华使古实人败在亚撒和犹大人面前，古实人就逃跑了；","notes":[]},{"n":13,"t":"亚撒和跟随他的军兵追赶他们，直到基拉耳。古实人被杀的甚多，不能再强盛，因为败在耶和华与他军兵面前。犹大人就夺了许多财物，","notes":[]},{"n":14,"t":"又打破基拉耳四围的城邑；耶和华使其中的人都甚恐惧。犹大人又将所有的城掳掠一空，因其中的财物甚多，","notes":[]},{"n":15,"t":"又毁坏了群畜的圈，夺取许多的羊和骆驼，就回耶路撒冷去了。","notes":[]}]},"15":{"heading":"亚撒的改革","verses":[{"n":1,"t":"神的灵感动俄德的儿子亚撒利雅。","notes":[]},{"n":2,"t":"他出来迎接亚撒，对他说：「亚撒和犹大、便雅悯众人哪，要听我说：你们若顺从耶和华，耶和华必与你们同在；你们若寻求他，就必寻见；你们若离弃他，他必离弃你们。","notes":[]},{"n":3,"t":"以色列人不信真神，没有训诲的祭司，也没有律法，已经好久了；","notes":[]},{"n":4,"t":"但他们在急难的时候归向耶和华—以色列的神，寻求他，他就被他们寻见。","notes":[]},{"n":5,"t":"那时，出入的人不得平安，列国的居民都遭大乱；","notes":[]},{"n":6,"t":"这国攻击那国，这城攻击那城，互相破坏，因为神用各样灾难扰乱他们。","notes":[]},{"n":7,"t":"现在你们要刚强，不要手软，因你们所行的必得赏赐。」","notes":[]},{"n":8,"t":"亚撒听见这话和俄德儿子先知亚撒利雅的预言，就壮起胆来，在犹大、便雅悯全地，并以法莲山地所夺的各城，将可憎之物尽都除掉，又在耶和华殿的廊前重新修筑耶和华的坛；","notes":[]},{"n":9,"t":"又招聚犹大、便雅悯的众人，并他们中间寄居的以法莲人、玛拿西人、西缅人。有许多以色列人归降亚撒，因见耶和华—他的神与他同在。","notes":[]},{"n":10,"t":"亚撒十五年三月，他们都聚集在耶路撒冷。","notes":[]},{"n":11,"t":"当日他们从所取的掳物中，将牛七百只、羊七千只献给耶和华。","notes":[]},{"n":12,"t":"他们就立约，要尽心尽性地寻求耶和华—他们列祖的神。","notes":[]},{"n":13,"t":"凡不寻求耶和华—以色列神的，无论大小、男女，必被治死。","notes":[]},{"n":14,"t":"他们就大声欢呼，吹号吹角，向耶和华起誓。","notes":[]},{"n":15,"t":"犹大众人为所起的誓欢喜；因他们是尽心起誓，尽意寻求耶和华，耶和华就被他们寻见，且赐他们四境平安。","notes":[]},{"n":16,"t":"亚撒王贬了他祖母玛迦太后的位，因她造了可憎的偶像亚舍拉。亚撒砍下她的偶像，捣得粉碎，烧在汲沦溪边。","notes":[]},{"n":17,"t":"只是邱坛还没有从以色列中废去，然而亚撒的心一生诚实。","notes":[]},{"n":18,"t":"亚撒将他父所分别为圣、与自己所分别为圣的金银和器皿都奉到神的殿里。","notes":[]},{"n":19,"t":"从这时直到亚撒三十五年，都没有争战的事。","notes":[]}]},"16":{"heading":"犹大与以色列争战","verses":[{"n":1,"t":"亚撒三十六年，以色列王巴沙上来攻击犹大，修筑拉玛，不许人从犹大王亚撒那里出入。","notes":[]},{"n":2,"t":"于是亚撒从耶和华殿和王宫的府库里拿出金银来，送与住大马士革的亚兰王便哈达，说：","notes":[]},{"n":3,"t":"「你父曾与我父立约，我与你也要立约。现在我将金银送给你，求你废掉你与以色列王巴沙所立的约，使他离开我。」","notes":[]},{"n":4,"t":"便·哈达听从亚撒王的话，派军长去攻击以色列的城邑。他们就攻破以云、但、亚伯·玛音，和拿弗他利一切的积货城。","notes":[]},{"n":5,"t":"巴沙听见就停工，不修筑拉玛了。","notes":[]},{"n":6,"t":"于是亚撒王率领犹大众人，将巴沙修筑拉玛所用的石头、木头都运去，用以修筑迦巴和米斯巴。","notes":[]},{"n":7,"t":"那时，先见哈拿尼来见犹大王亚撒，对他说：「因你仰赖亚兰王，没有仰赖耶和华—你的神，所以亚兰王的军兵脱离了你的手。","notes":[],"heads":["先知哈拿尼"]},{"n":8,"t":"古实人、路比人的军队不是甚大吗？战车马兵不是极多吗？只因你仰赖耶和华，他便将他们交在你手里。","notes":[]},{"n":9,"t":"耶和华的眼目遍察全地，要显大能帮助向他心存诚实的人。你这事行得愚昧；此后，你必有争战的事。」","notes":[]},{"n":10,"t":"亚撒因此恼恨先见，将他囚在监里。那时亚撒也虐待一些人民。","notes":[]},{"n":11,"t":"亚撒所行的事，自始至终都写在犹大和以色列诸王记上。","notes":[],"heads":["亚撒逝世"]},{"n":12,"t":"亚撒作王三十九年，他脚上有病，而且甚重。病的时候没有求耶和华，只求医生。","notes":[]},{"n":13,"t":"他作王四十一年而死，与他列祖同睡，","notes":[]},{"n":14,"t":"葬在大卫城自己所凿的坟墓里，放在床上，其床堆满各样馨香的香料，就是按做香的作法调和的香料，又为他烧了许多的物件。","notes":[]}]},"17":{"heading":"犹大王约沙法","verses":[{"n":1,"t":"亚撒的儿子约沙法接续他作王，奋勇自强，防备以色列人，","notes":[]},{"n":2,"t":"安置军兵在犹大一切坚固城里，又安置防兵在犹大地和他父亚撒所得以法莲的城邑中。","notes":[]},{"n":3,"t":"耶和华与约沙法同在；因为他行他祖大卫初行的道，不寻求巴力，","notes":[]},{"n":4,"t":"只寻求他父亲的神，遵行他的诫命，不效法以色列人的行为。","notes":[]},{"n":5,"t":"所以耶和华坚定他的国，犹大众人给他进贡；约沙法大有尊荣资财。","notes":[]},{"n":6,"t":"他高兴遵行耶和华的道，并且从犹大除掉一切邱坛和木偶。","notes":[]},{"n":7,"t":"他作王第三年，就差遣臣子便·亥伊勒、俄巴底、撒迦利雅、拿坦业、米该亚往犹大各城去教训百姓。","notes":[]},{"n":8,"t":"同着他们有利未人示玛雅、尼探雅、西巴第雅、亚撒黑、示米拉末、约拿单、亚多尼雅、多比雅、驼·巴多尼雅，又有祭司以利沙玛、约兰同着他们。","notes":[]},{"n":9,"t":"他们带着耶和华的律法书，走遍犹大各城教训百姓。","notes":[]},{"n":10,"t":"耶和华使犹大四围的列国都甚恐惧，不敢与约沙法争战。","notes":[],"heads":["约沙法的功绩"]},{"n":11,"t":"有些非利士人与约沙法送礼物，纳贡银。阿 拉伯人也送他公绵羊七千七百只，公山羊七千七百只。","notes":[]},{"n":12,"t":"约沙法日渐强大，在犹大建造营寨和积货城。","notes":[]},{"n":13,"t":"他在犹大城邑中有许多工程，又在耶路撒冷有战士，就是大能的勇士。","notes":[]},{"n":14,"t":"他们的数目，按着宗族，记在下面：犹大族的，千夫长押拿为首率领大能的勇士—三十万；","notes":[]},{"n":15,"t":"其次是，千夫长约哈难率领大能的勇士—二十八万；","notes":[]},{"n":16,"t":"其次是，细基利的儿子亚玛斯雅（他为耶和华牺牲自己）率领大能的勇士—二十万。","notes":[]},{"n":17,"t":"便雅悯族，是大能的勇士以利雅大率领拿弓箭和盾牌的—二十万；","notes":[]},{"n":18,"t":"其次是，约萨拔率领预备打仗的—十八万。","notes":[]},{"n":19,"t":"这都是伺候王的，还有王在犹大全地坚固城所安置的不在其内。","notes":[]}]},"18":{"heading":"先知米该雅警告亚哈王","verses":[{"n":1,"t":"约沙法大有尊荣资财，就与亚哈结亲。","notes":[]},{"n":2,"t":"过了几年，他下到撒马利亚去见亚哈；亚哈为他和跟从他的人宰了许多牛羊，劝他与自己同去攻取基列的拉末。","notes":[]},{"n":3,"t":"以色列王亚哈问犹大王约沙法说：「你肯同我去攻取基列的拉末吗？」他回答说：「你我不分彼此，我的民与你的民一样，必与你同去争战。」","notes":[]},{"n":4,"t":"约沙法对以色列王说：「请你先求问耶和华。」","notes":[]},{"n":5,"t":"于是以色列王招聚先知四百人，问他们说：「我们上去攻取基列的拉末可以不可以？」他们说：「可以上去，因为神必将那城交在王的手里。」","notes":[]},{"n":6,"t":"约沙法说：「这里不是还有耶和华的先知，我们可以求问他吗？」","notes":[]},{"n":7,"t":"以色列王对约沙法说：「还有一个人，是音拉的儿子米该雅。我们可以托他求问耶和华，只是我恨他；因为他指着我所说的预言，不说吉语，常说凶言。」约沙法说：「王不必这样说。」","notes":[]},{"n":8,"t":"以色列王就召了一个太监来，说：「你快去将音拉的儿子米该雅召来。」","notes":[]},{"n":9,"t":"以色列王和犹大王约沙法在撒马利亚城门前的空场上，各穿朝服坐在位上，所有的先知都在他们面前说预言。","notes":[]},{"n":10,"t":"基拿拿的儿子西底家造了两个铁角，说：「耶和华如此说：『你要用这角抵触亚兰人，直到将他们灭尽。』」","notes":[]},{"n":11,"t":"所有的先知也都这样预言说：「可以上基列的拉末去，必然得胜，因为耶和华必将那城交在王的手中。」","notes":[]},{"n":12,"t":"那去召米该雅的使者对米该雅说：「众先知一口同音地都向王说吉言，你不如与他们说一样的话，也说吉言。」","notes":[]},{"n":13,"t":"米该雅说：「我指着永生的耶和华起誓，我的神说什么，我就说什么。」","notes":[]},{"n":14,"t":"米该雅到王面前，王问他说：「米该雅啊，我们上去攻取基列的拉末可以不可以？」他说：「可以上去，必然得胜，敌人必交在你们手里。」","notes":[]},{"n":15,"t":"王对他说：「我当嘱咐你几次，你才奉耶和华的名向我说实话呢？」","notes":[]},{"n":16,"t":"米该雅说：「我看见以色列众民散在山上，如同没有牧人的羊群一般。耶和华说：『这民没有主人，他们可以平平安安地各归各家去。』」","notes":[]},{"n":17,"t":"以色列王对约沙法说：「我岂没有告诉你，这人指着我所说的预言，不说吉语，单说凶言吗？」","notes":[]},{"n":18,"t":"米该雅说：「你们要听耶和华的话。我看见耶和华坐在宝座上，天上的万军侍立在他左右。","notes":[]},{"n":19,"t":"耶和华说：『谁去引诱以色列王亚哈上基列的拉末去阵亡呢？』这个就这样说，那个就那样说。","notes":[]},{"n":20,"t":"随后，有一个神灵出来，站在耶和华面前说：『我去引诱他。』耶和华问他说：『你用何法呢？』","notes":[]},{"n":21,"t":"他说：『我去，要在他众先知口中作谎言的灵。』耶和华说：『这样，你必能引诱他，你去如此行吧！』","notes":[]},{"n":22,"t":"现在耶和华使谎言的灵入了你这些先知的口，并且耶和华已经命定降祸与你。」","notes":[]},{"n":23,"t":"基拿拿的儿子西底家前来打米该雅的脸，说：「耶和华的灵从哪里离开我与你说话呢？」","notes":[]},{"n":24,"t":"米该雅说：「你进严密的屋子藏躲的那日，就必看见了。」","notes":[]},{"n":25,"t":"以色列王说：「将米该雅带回，交给邑宰亚们和王的儿子约阿施，说：","notes":[]},{"n":26,"t":"『王如此说：把这个人下在监里，使他受苦，吃不饱喝不足，等候我平平安安地回来。』」","notes":[]},{"n":27,"t":"米该雅说：「你若能平安回来，那就是耶和华没有借我说这话了」；又说：「众民哪，你们都要听！」","notes":[]},{"n":28,"t":"以色列王和犹大王约沙法上基列的拉末去了。","notes":[],"heads":["亚哈阵亡"]},{"n":29,"t":"以色列王对约沙法说：「我要改装上阵，你可以仍穿王服。」于是以色列王改装，他们就上阵去了。","notes":[]},{"n":30,"t":"先是亚兰王吩咐车兵长说：「他们的兵将，无论大小，你们都不可与他们争战，只要与以色列王争战。」","notes":[]},{"n":31,"t":"车兵长看见约沙法便说，这必是以色列王，就转过去与他争战。约沙法一呼喊，耶和华就帮助他，神又感动他们离开他。","notes":[]},{"n":32,"t":"车兵长见不是以色列王，就转去不追他了。","notes":[]},{"n":33,"t":"有一人随便开弓，恰巧射入以色列王的甲缝里。王对赶车的说：「我受了重伤，你转过车来，拉我出阵吧！」","notes":[]},{"n":34,"t":"那日阵势越战越猛，以色列王勉强站在车上抵挡亚兰人，直到晚上。约在日落的时候，王就死了。","notes":[]}]},"19":{"heading":"先知斥责约沙法","verses":[{"n":1,"t":"犹大王约沙法平平安安地回耶路撒冷，到宫里去了。","notes":[]},{"n":2,"t":"先见哈拿尼的儿子耶户出来迎接约沙法王，对他说：「你岂当帮助恶人，爱那恨恶耶和华的人呢？因此耶和华的忿怒临到你。","notes":[]},{"n":3,"t":"然而你还有善行，因你从国中除掉木偶，立定心意寻求神。」","notes":[]},{"n":4,"t":"约沙法住在耶路撒冷，以后又出巡民间，从别是巴直到以法莲山地，引导民归向耶和华—他们列祖的神；","notes":[],"heads":["约沙法的改革"]},{"n":5,"t":"又在犹大国中遍地的坚固城里设立审判官，","notes":[]},{"n":6,"t":"对他们说：「你们办事应当谨慎；因为你们判断不是为人，乃是为耶和华。判断的时候，他必与你们同在。","notes":[]},{"n":7,"t":"现在你们应当敬畏耶和华，谨慎办事；因为耶和华—我们的神没有不义，不偏待人，也不受贿赂。」","notes":[]},{"n":8,"t":"约沙法从利未人和祭司，并以色列族长中派定人，在耶路撒冷为耶和华判断，听民间的争讼，就回耶路撒冷去了。","notes":[]},{"n":9,"t":"约沙法嘱咐他们说：「你们当敬畏耶和华，忠心诚实办事。","notes":[]},{"n":10,"t":"住在各城里你们的弟兄，若有争讼的事来到你们这里，或为流血，或犯律法、诫命、律例、典章，你们要警戒他们，免得他们得罪耶和华，以致他的忿怒临到你们和你们的弟兄；这样行，你们就没有罪了。","notes":[]},{"n":11,"t":"凡属耶和华的事，有大祭司亚玛利雅管理你们；凡属王的事，有犹大支派的族长以实玛利的儿子西巴第雅管理你们；在你们面前有利未人作官长。你们应当壮胆办事，愿耶和华与善人同在。」","notes":[]}]},"20":{"heading":"与以东交战","verses":[{"n":1,"t":"此后，摩押人和亚扪人，又有米乌尼人，一同来攻击约沙法。","notes":[]},{"n":2,"t":"有人来报告约沙法说：「从海外亚兰那边有大军来攻击你，如今他们在哈洗逊·他玛，就是隐·基底。」","notes":["又作以东"]},{"n":3,"t":"约沙法便惧怕，定意寻求耶和华，在犹大全地宣告禁食。","notes":[]},{"n":4,"t":"于是犹大人聚会，求耶和华帮助。犹大各城都有人出来寻求耶和华。","notes":[]},{"n":5,"t":"约沙法就在犹大和耶路撒冷的会中，站在耶和华殿的新院前，","notes":[]},{"n":6,"t":"说：「耶和华—我们列祖的神啊，你不是天上的神吗？你不是万邦万国的主宰吗？在你手中有大能大力，无人能抵挡你。","notes":[]},{"n":7,"t":"我们的神啊，你不是曾在你民以色列人面前驱逐这地的居民，将这地赐给你朋友亚伯拉罕的后裔永远为业吗？","notes":[]},{"n":8,"t":"他们住在这地，又为你的名建造圣所，说：","notes":[]},{"n":9,"t":"『倘有祸患临到我们，或刀兵灾殃，或瘟疫饥荒，我们在急难的时候，站在这殿前向你呼求，你必垂听而拯救，因为你的名在这殿里。』","notes":[]},{"n":10,"t":"从前以色列人出埃及地的时候，你不容以色列人侵犯亚扪人、摩押人，和西珥山人，以色列人就离开他们，不灭绝他们。","notes":[]},{"n":11,"t":"看哪，他们怎样报复我们，要来驱逐我们出离你的地，就是你赐给我们为业之地。","notes":[]},{"n":12,"t":"我们的神啊，你不惩罚他们吗？因为我们无力抵挡这来攻击我们的大军，我们也不知道怎样行，我们的眼目单仰望你。」","notes":[]},{"n":13,"t":"犹大众人和他们的婴孩、妻子、儿女都站在耶和华面前。","notes":[]},{"n":14,"t":"那时，耶和华的灵在会中临到利未人亚萨的后裔—玛探雅的玄孙，耶利的曾孙，比拿雅的孙子，撒迦利雅的儿子雅哈悉。","notes":[]},{"n":15,"t":"他说：「犹大众人、耶路撒冷的居民，和约沙法王，你们请听。耶和华对你们如此说：『不要因这大军恐惧惊惶；因为胜败不在乎你们，乃在乎神。","notes":[]},{"n":16,"t":"明日你们要下去迎敌，他们是从洗斯坡上来，你们必在耶鲁伊勒旷野前的谷口遇见他们。","notes":[]},{"n":17,"t":"犹大和耶路撒冷人哪，这次你们不要争战，要摆阵站着，看耶和华为你们施行拯救。不要恐惧，也不要惊惶。明日当出去迎敌，因为耶和华与你们同在。』」","notes":[]},{"n":18,"t":"约沙法就面伏于地，犹大众人和耶路撒冷的居民也俯伏在耶和华面前，叩拜耶和华。","notes":[]},{"n":19,"t":"哥辖族和可拉族的利未人都起来，用极大的声音赞美耶和华以色列的神。","notes":[]},{"n":20,"t":"次日清早，众人起来往提哥亚的旷野去。出去的时候，约沙法站着说：「犹大人和耶路撒冷的居民哪，要听我说：信耶和华—你们的神就必立稳；信他的先知就必亨通。」","notes":[]},{"n":21,"t":"约沙法既与民商议了，就设立歌唱的人，颂赞耶和华，使他们穿上圣洁的礼服，走在军前赞美耶和华说：「当称谢耶和华，因他的慈爱永远长存！」","notes":[]},{"n":22,"t":"众人方唱歌赞美的时候，耶和华就派伏兵击杀那来攻击犹大人的亚扪人、摩押人，和西珥山人，他们就被打败了。","notes":[]},{"n":23,"t":"因为亚扪人和摩押人起来，击杀住西珥山的人，将他们灭尽；灭尽住西珥山的人之后，他们又彼此自相击杀。","notes":[]},{"n":24,"t":"犹大人来到旷野的望楼，向那大军观看，见尸横遍地，没有一个逃脱的。","notes":[]},{"n":25,"t":"约沙法和他的百姓就来收取敌人的财物，在尸首中见了许多财物、珍宝，他们剥脱下来的多得不可携带；因为甚多，直收取了三日。","notes":[]},{"n":26,"t":"第四日众人聚集在比拉迦谷，在那里称颂耶和华。因此那地方名叫比拉迦谷，直到今日。","notes":["就是称颂的意思"]},{"n":27,"t":"犹大人和耶路撒冷人都欢欢喜喜地回耶路撒冷，约沙法率领他们；因为耶和华使他们战胜仇敌，就欢喜快乐。","notes":[]},{"n":28,"t":"他们弹琴、鼓瑟、吹号来到耶路撒冷，进了耶和华的殿。","notes":[]},{"n":29,"t":"列邦诸国听见耶和华战败以色列的仇敌，就甚惧怕。","notes":[]},{"n":30,"t":"这样，约沙法的国得享太平，因为神赐他四境平安。","notes":[]},{"n":31,"t":"约沙法作犹大王，登基的时候年三十五岁，在耶路撒冷作王二十五年。他母亲名叫阿苏巴，乃示利希的女儿。","notes":[],"heads":["约沙法逝世"]},{"n":32,"t":"约沙法效法他父亚撒所行的，不偏左右，行耶和华眼中看为正的事。","notes":[]},{"n":33,"t":"只是邱坛还没有废去，百姓也没有立定心意归向他们列祖的神。","notes":[]},{"n":34,"t":"约沙法其余的事，自始至终都写在哈拿尼的儿子耶户的书上，也载入以色列诸王记上。","notes":[]},{"n":35,"t":"此后，犹大王约沙法与以色列王亚哈谢交好；亚哈谢行恶太甚。","notes":[]},{"n":36,"t":"二王合伙造船要往他施去，遂在以旬·迦别造船。","notes":[]},{"n":37,"t":"那时玛利沙人、多大瓦的儿子以利以谢向约沙法预言说：「因你与亚哈谢交好，耶和华必破坏你所造的。」后来那船果然破坏，不能往他施去了。","notes":[]}]},"21":{"heading":"犹大王约兰","verses":[{"n":1,"t":"约沙法与他列祖同睡，葬在大卫城他列祖的坟地里。他儿子约兰接续他作王。","notes":[]},{"n":2,"t":"约兰有几个兄弟，就是约沙法的儿子亚撒利雅、耶歇、撒迦利雅、亚撒利雅、米迦勒、示法提雅。这都是犹大王约沙法的儿子。","notes":[]},{"n":3,"t":"他们的父亲将许多金银、财宝，和犹大地的坚固城赐给他们；但将国赐给约兰，因为他是长子。","notes":[]},{"n":4,"t":"约兰兴起坐他父的位，奋勇自强，就用刀杀了他的众兄弟和以色列的几个首领。","notes":[]},{"n":5,"t":"约兰登基的时候年三十二岁，在耶路撒冷作王八年。","notes":[]},{"n":6,"t":"他行以色列诸王的道，与亚哈家一样；因他娶了亚哈的女儿为妻，行耶和华眼中看为恶的事。","notes":[]},{"n":7,"t":"耶和华却因自己与大卫所立的约，不肯灭大卫的家，照他所应许的，永远赐灯光与大卫和他的子孙。","notes":[]},{"n":8,"t":"约兰年间，以东人背叛犹大，脱离他的权下，自己立王。","notes":[]},{"n":9,"t":"约兰就率领军长和所有的战车，夜间起来，攻击围困他的以东人和车兵长。","notes":[]},{"n":10,"t":"这样，以东人背叛犹大，脱离他的权下，直到今日。那时，立拿人也背叛了，因为约兰离弃耶和华—他列祖的神。","notes":[]},{"n":11,"t":"他又在犹大诸山建筑邱坛，使耶路撒冷的居民行邪淫，诱惑犹大人。","notes":[]},{"n":12,"t":"先知以利亚达信与约兰说：「耶和华—你祖大卫的神如此说：『因为你不行你父约沙法和犹大王亚撒的道，","notes":[]},{"n":13,"t":"乃行以色列诸王的道，使犹大人和耶路撒冷的居民行邪淫，像亚哈家一样，又杀了你父家比你好的诸兄弟。","notes":[]},{"n":14,"t":"故此，耶和华降大灾与你的百姓和你的妻子、儿女，并你一切所有的。","notes":[]},{"n":15,"t":"你的肠子必患病，日加沉重，以致你的肠子坠落下来。』」","notes":[]},{"n":16,"t":"以后，耶和华激动非利士人和靠近古实的阿拉伯人来攻击约兰。","notes":[]},{"n":17,"t":"他们上来攻击犹大，侵入境内，掳掠了王宫里所有的财货和他的妻子、儿女，除了他小儿子约哈斯之外，没有留下一个儿子。","notes":["又名亚哈谢"]},{"n":18,"t":"这些事以后，耶和华使约兰的肠子患不能医治的病。","notes":[]},{"n":19,"t":"他患此病缠绵日久，过了二年，肠子坠落下来，病重而死。他的民没有为他烧什么物件，像从前为他列祖所烧的一样。","notes":[]},{"n":20,"t":"约兰登基的时候年三十二岁，在耶路撒冷作王八年。他去世无人思慕，众人葬他在大卫城，只是不在列王的坟墓里。","notes":[]}]},"22":{"heading":"犹大王亚哈谢","verses":[{"n":1,"t":"耶路撒冷的居民立约兰的小儿子亚哈谢接续他作王；因为跟随阿拉伯人来攻营的军兵曾杀了亚哈谢的众兄长。这样，犹大王约兰的儿子亚哈谢作了王。","notes":[]},{"n":2,"t":"亚哈谢登基的时候年四十二岁，在耶路撒冷作王一年。他母亲名叫亚她利雅，是暗利的孙女。","notes":["列王下八章二十六节是二十二岁"]},{"n":3,"t":"亚哈谢也行亚哈家的道；因为他母亲给他主谋，使他行恶。","notes":[]},{"n":4,"t":"他行耶和华眼中看为恶的事，像亚哈家一样；因他父亲死后有亚哈家的人给他主谋，以致败坏。","notes":[]},{"n":5,"t":"他听从亚哈家的计谋，同以色列王亚哈的儿子约兰往基列的拉末去，与亚兰王哈薛争战；亚兰人打伤了约兰。","notes":[]},{"n":6,"t":"约兰回到耶斯列，医治在拉末与亚兰王哈薛打仗所受的伤，犹大王约兰的儿子亚撒利雅因为亚哈的儿子约兰病了，就下到耶斯列看望他。","notes":["就是亚哈谢"]},{"n":7,"t":"亚哈谢去见约兰就被害了，这是出乎神；因为他到了，就同约兰出去攻击宁示的孙子耶户。这耶户是耶和华所膏、使他剪除亚哈家的。","notes":[]},{"n":8,"t":"耶户讨亚哈家罪的时候，遇见犹大的众首领和亚哈谢的众侄子服事亚哈谢，就把他们都杀了。","notes":[]},{"n":9,"t":"亚哈谢藏在撒马利亚，耶户寻找他，众人将他拿住，送到耶户那里，就杀了他，将他葬埋；因他们说，他是那尽心寻求耶和华之约沙法的儿子。这样，亚哈谢的家无力保守国权。","notes":[]},{"n":10,"t":"亚哈谢的母亲亚她利雅见她儿子死了，就起来剿灭犹大王室。","notes":[],"heads":["亚她利雅篡位"]},{"n":11,"t":"但王的女儿约示巴将亚哈谢的儿子约阿施从那被杀的王子中偷出来，把他和他的乳母都藏在卧房里。约示巴是约兰王的女儿，亚哈谢的妹子，祭司耶何耶大的妻。她收藏约阿施，躲避亚她利雅，免得被杀。","notes":[]},{"n":12,"t":"约阿施和她们一同藏在神殿里六年；亚她利雅篡了国位。","notes":[]}]},"23":{"heading":"推翻亚她利雅","verses":[{"n":1,"t":"第七年，耶何耶大奋勇自强，将百夫长耶罗罕的儿子亚撒利雅，约哈难的儿子以实玛利，俄备得的儿子亚撒利雅，亚大雅的儿子玛西雅，细基利的儿子以利沙法召来，与他们立约。","notes":[]},{"n":2,"t":"他们走遍犹大，从犹大各城里招聚利未人和以色列的众族长到耶路撒冷来。","notes":[]},{"n":3,"t":"会众在神殿里与王立约。耶何耶大对他们说：「看哪，王的儿子必当作王，正如耶和华指着大卫子孙所应许的话」；","notes":[]},{"n":4,"t":"又说：「你们当这样行：祭司和利未人凡安息日进班的，三分之一要把守各门，","notes":[]},{"n":5,"t":"三分之一要在王宫，三分之一要在基址门；众百姓要在耶和华殿的院内。","notes":[]},{"n":6,"t":"除了祭司和供职的利未人之外，不准别人进耶和华的殿；惟独他们可以进去，因为他们圣洁。众百姓要遵守耶和华所吩咐的。","notes":[]},{"n":7,"t":"利未人要手中各拿兵器，四围护卫王；凡擅入殿宇的，必当治死。王出入的时候，你们当跟随他。」","notes":[]},{"n":8,"t":"利未人和犹大众人都照着祭司耶何耶大一切所吩咐的去行，各带所管安息日进班出班的人来，因为祭司耶何耶大不许他们下班。","notes":[]},{"n":9,"t":"祭司耶何耶大便将神殿里所藏大卫王的枪、盾牌、挡牌交给百夫长，","notes":[]},{"n":10,"t":"又分派众民手中各拿兵器，在坛和殿那里，从殿右直到殿左，站在王子的四围；","notes":[]},{"n":11,"t":"于是领王子出来，给他戴上冠冕，将律法书交给他，立他作王。耶何耶大和众子膏他，众人说：「愿王万岁！」","notes":[]},{"n":12,"t":"亚她利雅听见民奔走赞美王的声音，就到民那里，进耶和华的殿，","notes":[]},{"n":13,"t":"看见王站在殿门的柱旁，百夫长和吹号的人侍立在王左右，国民都欢乐吹号，又有歌唱的，用各样的乐器领人歌唱赞美；亚她利雅就撕裂衣服，喊叫说：「反了！反了！」","notes":[]},{"n":14,"t":"祭司耶何耶大带管辖军兵的百夫长出来，吩咐他们说：「将她赶到班外，凡跟随她的必用刀杀死！」因为祭司说：「不可在耶和华殿里杀她。」","notes":[]},{"n":15,"t":"众兵就闪开，让她去；她走到王宫的马门，便在那里把她杀了。","notes":[]},{"n":16,"t":"耶何耶大与众民和王立约，都要作耶和华的民。","notes":[],"heads":["耶何耶大的改革"]},{"n":17,"t":"于是众民都到巴力庙，拆毁了庙，打碎坛和像，又在坛前将巴力的祭司玛坦杀了。","notes":[]},{"n":18,"t":"耶何耶大派官看守耶和华的殿，是在祭司利未人手下。这祭司利未人是大卫分派在耶和华殿中、照摩西律法上所写的，给耶和华献燔祭，又按大卫所定的例，欢乐歌唱；","notes":[]},{"n":19,"t":"且设立守门的把守耶和华殿的各门，无论为何事，不洁净的人都不准进去。","notes":[]},{"n":20,"t":"又率领百夫长和贵胄，与民间的官长，并国中的众民，请王从耶和华殿下来，由上门进入王宫，立王坐在国位上。","notes":[]},{"n":21,"t":"国民都欢乐，合城都安静。众人已将亚她利雅用刀杀了。","notes":[]}]},"24":{"heading":"犹大王约阿施","verses":[{"n":1,"t":"约阿施登基的时候年七岁，在耶路撒冷作王四十年。他母亲名叫西比亚，是别是巴人。","notes":[]},{"n":2,"t":"祭司耶何耶大在世的时候，约阿施行耶和华眼中看为正的事。","notes":[]},{"n":3,"t":"耶何耶大为他娶了两个妻，并且生儿养女。","notes":[]},{"n":4,"t":"此后，约阿施有意重修耶和华的殿，","notes":[]},{"n":5,"t":"便召聚众祭司和利未人，吩咐他们说：「你们要往犹大各城去，使以色列众人捐纳银子，每年可以修理你们神的殿；你们要急速办理这事。」只是利未人不急速办理。","notes":[]},{"n":6,"t":"王召了大祭司耶何耶大来，对他说：「从前耶和华的仆人摩西，为法柜的帐幕与以色列会众所定的捐项，你为何不叫利未人照这例从犹大和耶路撒冷带来作殿的费用呢？」（","notes":[]},{"n":7,"t":"因为那恶妇亚她利雅的众子曾拆毁神的殿，又用耶和华殿中分别为圣的物供奉巴力。）","notes":[]},{"n":8,"t":"于是王下令，众人做了一柜，放在耶和华殿的门外，","notes":[]},{"n":9,"t":"又通告犹大和耶路撒冷的百姓，要将神仆人摩西在旷野所吩咐以色列人的捐项给耶和华送来。","notes":[]},{"n":10,"t":"众首领和百姓都欢欢喜喜地将银子送来，投入柜中，直到捐完。","notes":[]},{"n":11,"t":"利未人见银子多了，就把柜抬到王所派的司事面前；王的书记和大祭司的属员来将柜倒空，仍放在原处。日日都是这样，积蓄的银子甚多。","notes":[]},{"n":12,"t":"王与耶何耶大将银子交给耶和华殿里办事的人，他们就雇了石匠、木匠重修耶和华的殿，又雇了铁匠、铜匠修理耶和华的殿。","notes":[]},{"n":13,"t":"工人操作，渐渐修成，将神殿修造得与从前一样，而且甚是坚固。","notes":[]},{"n":14,"t":"工程完了，他们就把其余的银子拿到王与耶何耶大面前，用以制造耶和华殿供奉所用的器皿和调羹，并金银的器皿。耶何耶大在世的时候，众人常在耶和华殿里献燔祭。","notes":[]},{"n":15,"t":"耶何耶大年纪老迈，日子满足而死。死的时候年一百三十岁，","notes":[]},{"n":16,"t":"葬在大卫城列王的坟墓里；因为他在以色列人中行善，又事奉神，修理神的殿。","notes":[]},{"n":17,"t":"耶何耶大死后，犹大的众首领来朝拜王；王就听从他们。","notes":[]},{"n":18,"t":"他们离弃耶和华—他们列祖神的殿，去事奉亚舍拉和偶像；因他们这罪，就有忿怒临到犹大和耶路撒冷。","notes":[]},{"n":19,"t":"但神仍遣先知到他们那里，引导他们归向耶和华。这先知警戒他们，他们却不肯听。","notes":[]},{"n":20,"t":"那时，神的灵感动祭司耶何耶大的儿子撒迦利亚，他就站在上面对民说：「神如此说：你们为何干犯耶和华的诫命，以致不得亨通呢？因为你们离弃耶和华，所以他也离弃你们。」","notes":[]},{"n":21,"t":"众民同心谋害撒迦利亚，就照王的吩咐，在耶和华殿的院内用石头打死他。","notes":[]},{"n":22,"t":"这样，约阿施王不想念撒迦利亚的父亲耶何耶大向自己所施的恩，杀了他的儿子。撒迦利亚临死的时候说：「愿耶和华鉴察伸冤！」","notes":[]},{"n":23,"t":"满了一年，亚兰的军兵上来攻击约阿施，来到犹大和耶路撒冷，杀了民中的众首领，将所掠的财货送到大马士革王那里。","notes":[],"heads":["约阿施被杀"]},{"n":24,"t":"亚兰的军兵虽来了一小队，耶和华却将大队的军兵交在他们手里，是因犹大人离弃耶和华—他们列祖的神，所以借亚兰人惩罚约阿施。","notes":[]},{"n":25,"t":"亚兰人离开约阿施的时候，他患重病；臣仆背叛他，要报祭司耶何耶大儿子流血之仇，杀他在床上，葬他在大卫城，只是不葬在列王的坟墓里。","notes":[]},{"n":26,"t":"背叛他的是亚扪妇人示米押的儿子撒拔和摩押妇人示米利的儿子约萨拔。","notes":[]},{"n":27,"t":"至于他的众子和他所受的警戒，并他重修神殿的事，都写在列王的传上。他儿子亚玛谢接续他作王。","notes":[]}]},"25":{"heading":"犹大王亚玛谢","verses":[{"n":1,"t":"亚玛谢登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫约耶但，是耶路撒冷人。","notes":[]},{"n":2,"t":"亚玛谢行耶和华眼中看为正的事，只是心不专诚。","notes":[]},{"n":3,"t":"国一坚定，就把杀他父王的臣仆杀了，","notes":[]},{"n":4,"t":"却没有治死他们的儿子，是照摩西律法书上耶和华所吩咐的说：「不可因子杀父，也不可因父杀子，各人要为本身的罪而死。」","notes":[]},{"n":5,"t":"亚玛谢招聚犹大人，按着犹大和便雅悯的宗族设立千夫长、百夫长，又数点人数，从二十岁以外，能拿枪拿盾牌出去打仗的精兵共有三十万；","notes":[],"heads":["与以东交战"]},{"n":6,"t":"又用银子一百他连得，从以色列招募了十万大能的勇士。","notes":[]},{"n":7,"t":"有一个神人来见亚玛谢，对他说：「王啊，不要使以色列的军兵与你同去，因为耶和华不与以色列人以法莲的后裔同在。","notes":[]},{"n":8,"t":"你若一定要去，就奋勇争战吧！但神必使你败在敌人面前；因为神能助人得胜，也能使人倾败。」","notes":[]},{"n":9,"t":"亚玛谢问神人说：「我给了以色列军的那一百他连得银子怎么样呢？」神人回答说：「耶和华能把更多的赐给你。」","notes":[]},{"n":10,"t":"于是亚玛谢将那从以法莲来的军兵分别出来，叫他们回家去。故此，他们甚恼怒犹大人，气忿忿地回家去了。","notes":[]},{"n":11,"t":"亚玛谢壮起胆来，率领他的民到盐谷，杀了西珥人一万。","notes":[]},{"n":12,"t":"犹大人又生擒了一万带到山崖上，从那里把他们扔下去，以致他们都摔碎了。","notes":[]},{"n":13,"t":"但亚玛谢所打发回去、不许一同出征的那些军兵攻打犹大各城，从撒马利亚直到伯·和仑，杀了三千人，抢了许多财物。","notes":[]},{"n":14,"t":"亚玛谢杀了以东人回来，就把西珥的神像带回，立为自己的神，在它面前叩拜烧香。","notes":[]},{"n":15,"t":"因此，耶和华的怒气向亚玛谢发作，就差一个先知去见他，说：「这些神不能救它的民脱离你的手，你为何寻求它呢？」","notes":[]},{"n":16,"t":"先知与王说话的时候，王对他说：「谁立你作王的谋士呢？你住口吧！为何找打呢？」先知就止住了，又说：「你行这事，不听从我的劝戒，我知道神定意要灭你。」","notes":[]},{"n":17,"t":"犹大王亚玛谢与群臣商议，就差遣使者去见耶户的孙子、约哈斯的儿子、以色列王约阿施，说：「你来，我们二人相见于战场。」","notes":[],"heads":["与以色列争战"]},{"n":18,"t":"以色列王约阿施差遣使者去见犹大王亚玛谢，说：「黎巴嫩的蒺藜差遣使者去见黎巴嫩的香柏树，说：『将你的女儿给我儿子为妻。』后来黎巴嫩有一个野兽经过，把蒺藜践踏了。","notes":[]},{"n":19,"t":"你说：『看哪，我打败了以东人』，你就心高气傲，以致矜夸。你在家里安居就罢了，为何要惹祸使自己和犹大国一同败亡呢？」","notes":[]},{"n":20,"t":"亚玛谢却不肯听从。这是出乎神，好将他们交在敌人手里，因为他们寻求以东的神。","notes":[]},{"n":21,"t":"于是以色列王约阿施上来，在犹大的伯·示麦与犹大王亚玛谢相见于战场。","notes":[]},{"n":22,"t":"犹大人败在以色列人面前，各自逃回家里去了。","notes":[]},{"n":23,"t":"以色列王约阿施在伯·示麦擒住约哈斯的孙子、约阿施的儿子、犹大王亚玛谢，将他带到耶路撒冷，又拆毁耶路撒冷的城墙，从以法莲门直到角门，共四百肘；","notes":["就是亚哈谢"]},{"n":24,"t":"又将俄别·以东所看守神殿里的一切金银和器皿，与王宫里的财宝都拿了去，并带人去为质，就回撒马利亚去了。","notes":[]},{"n":25,"t":"以色列王约哈斯的儿子约阿施死后，犹大王约阿施的儿子亚玛谢又活了十五年。","notes":[]},{"n":26,"t":"亚玛谢其余的事，自始至终不都写在犹大和以色列诸王记上吗？","notes":[]},{"n":27,"t":"自从亚玛谢离弃耶和华之后，在耶路撒冷有人背叛他，他就逃到拉吉；叛党却打发人到拉吉，将他杀了。","notes":[]},{"n":28,"t":"人就用马将他的尸首驮回，葬在犹大京城他列祖的坟地里。","notes":[]}]},"26":{"heading":"犹大王乌西雅","verses":[{"n":1,"t":"犹大众民立亚玛谢的儿子乌西雅接续他父作王，那时他年十六岁。（","notes":["又名亚撒利雅"]},{"n":2,"t":"亚玛谢与他列祖同睡之后，乌西雅收回以禄仍归犹大，又重新修理。）","notes":[]},{"n":3,"t":"乌西雅登基的时候年十六岁，在耶路撒冷作王五十二年。他母亲名叫耶可利雅，是耶路撒冷人。","notes":[]},{"n":4,"t":"乌西雅行耶和华眼中看为正的事，效法他父亚玛谢一切所行的；","notes":[]},{"n":5,"t":"通晓神默示，撒迦利亚在世的时候，乌西雅定意寻求神；他寻求耶和华，神就使他亨通。","notes":[]},{"n":6,"t":"他出去攻击非利士人，拆毁了迦特城、雅比尼城，和亚实突城；在非利士人中，在亚实突境内，又建筑了些城。","notes":[]},{"n":7,"t":"神帮助他攻击非利士人和住在姑珥·巴力的阿拉伯人，并米乌尼人。","notes":[]},{"n":8,"t":"亚扪人给乌西雅进贡。他的名声传到埃及，因他甚是强盛。","notes":[]},{"n":9,"t":"乌西雅在耶路撒冷的角门和谷门，并城墙转弯之处，建筑城楼，且甚坚固；","notes":[]},{"n":10,"t":"又在旷野与高原和平原，建筑望楼，挖了许多井，因他的牲畜甚多；又在山地和佳美之地，有农夫和修理葡萄园的人，因为他喜悦农事。","notes":[]},{"n":11,"t":"乌西雅又有军兵，照书记耶利和官长玛西雅所数点的，在王的一个将军哈拿尼雅手下，分队出战。","notes":[]},{"n":12,"t":"族长、大能勇士的总数共有二千六百人，","notes":[]},{"n":13,"t":"他们手下的军兵共有三十万七千五百人，都有大能，善于争战，帮助王攻击仇敌。","notes":[]},{"n":14,"t":"乌西雅为全军预备盾牌、枪、盔、甲、弓，和甩石的机弦，","notes":[]},{"n":15,"t":"又在耶路撒冷使巧匠做机器，安在城楼和角楼上，用以射箭发石。乌西雅的名声传到远方；因为他得了非常的帮助，甚是强盛。","notes":[]},{"n":16,"t":"他既强盛，就心高气傲，以致行事邪僻，干犯耶和华—他的神，进耶和华的殿，要在香坛上烧香。","notes":[],"heads":["乌西雅因骄傲受惩"]},{"n":17,"t":"祭司亚撒利雅率领耶和华勇敢的祭司八十人，跟随他进去。","notes":[]},{"n":18,"t":"他们就阻挡乌西雅王，对他说：「乌西雅啊，给耶和华烧香不是你的事，乃是亚伦子孙承接圣职祭司的事。你出圣殿吧！因为你犯了罪。你行这事，耶和华神必不使你得荣耀。」","notes":[]},{"n":19,"t":"乌西雅就发怒，手拿香炉要烧香。他向祭司发怒的时候，在耶和华殿中香坛旁众祭司面前，额上忽然发出大麻风。","notes":[]},{"n":20,"t":"大祭司亚撒利雅和众祭司观看，见他额上发出大麻风，就催他出殿；他自己也急速出去，因为耶和华降灾与他。","notes":[]},{"n":21,"t":"乌西雅王长大麻风直到死日，因此住在别的宫里，与耶和华的殿隔绝。他儿子约坦管理家事，治理国民。","notes":[]},{"n":22,"t":"乌西雅其余的事，自始至终都是亚摩斯的儿子先知以赛亚所记的。","notes":[]},{"n":23,"t":"乌西雅与他列祖同睡，葬在王陵的田间他列祖的坟地里；因为人说，他是长大麻风的。他儿子约坦接续他作王。","notes":[]}]},"27":{"heading":"犹大王约坦","verses":[{"n":1,"t":"约坦登基的时候年二十五岁，在耶路撒冷作王十六年，他母亲名叫耶路沙，是撒督的女儿。","notes":[]},{"n":2,"t":"约坦行耶和华眼中看为正的事，效法他父乌西雅一切所行的，只是不入耶和华的殿。百姓还行邪僻的事。","notes":[]},{"n":3,"t":"约坦建立耶和华殿的上门，在俄斐勒城上多有建造，","notes":[]},{"n":4,"t":"又在犹大山地建造城邑，在树林中建筑营寨和高楼。","notes":[]},{"n":5,"t":"约坦与亚扪人的王打仗胜了他们，当年他们进贡银一百他连得，小麦一万歌珥，大麦一万歌珥；第二年、第三年也是这样。","notes":[]},{"n":6,"t":"约坦在耶和华—他神面前行正道，以致日渐强盛。","notes":[]},{"n":7,"t":"约坦其余的事和一切争战，并他的行为，都写在以色列和犹大列王记上。","notes":[]},{"n":8,"t":"他登基的时候年二十五岁，在耶路撒冷作王十六年。","notes":[]},{"n":9,"t":"约坦与他列祖同睡，葬在大卫城里。他儿子亚哈斯接续他作王。","notes":[]}]},"28":{"heading":"犹大王亚哈斯","verses":[{"n":1,"t":"亚哈斯登基的时候年二十岁，在耶路撒冷作王十六年；不像他祖大卫行耶和华眼中看为正的事，","notes":[]},{"n":2,"t":"却行以色列诸王的道，又铸造巴力的像，","notes":[]},{"n":3,"t":"并且在欣嫩子谷烧香，用火焚烧他的儿女，行耶和华在以色列人面前所驱逐的外邦人那可憎的事；","notes":[]},{"n":4,"t":"并在邱坛上、山冈上、各青翠树下献祭烧香。","notes":[]},{"n":5,"t":"所以，耶和华—他的神将他交在亚兰王手里。亚兰王打败他，掳了他许多的民，带到大马士革去。神又将他交在以色列王手里，以色列王向他大行杀戮。","notes":[],"heads":["跟亚兰和以色列交战"]},{"n":6,"t":"利玛利的儿子比加一日杀了犹大人十二万，都是勇士，因为他们离弃了耶和华—他们列祖的神。","notes":[]},{"n":7,"t":"有一个以法莲中的勇士，名叫细基利，杀了王的儿子玛西雅和管理王宫的押斯利甘，并宰相以利加拿。","notes":[]},{"n":8,"t":"以色列人掳了他们的弟兄，连妇人带儿女共有二十万，又掠了许多的财物，带到撒马利亚去了。","notes":[]},{"n":9,"t":"但那里有耶和华的一个先知，名叫俄德，出来迎接往撒马利亚去的军兵，对他们说：「因为耶和华—你们列祖的神恼怒犹大人，所以将他们交在你们手里，你们竟怒气冲天，大行杀戮。","notes":[],"heads":["先知俄德"]},{"n":10,"t":"如今你们又有意强逼犹大人和耶路撒冷人作你们的奴婢，你们岂不也有得罪耶和华—你们神的事吗？","notes":[]},{"n":11,"t":"现在你们当听我说，要将掳来的弟兄释放回去，因为耶和华向你们已经大发烈怒。」","notes":[]},{"n":12,"t":"于是，以法莲人的几个族长—就是约哈难的儿子亚撒利雅、米实利末的儿子比利家、沙龙的儿子耶希西家、哈得莱的儿子亚玛撒—起来拦挡出兵回来的人，","notes":[]},{"n":13,"t":"对他们说：「你们不可带进这被掳的人来！你们想要使我们得罪耶和华，加增我们的罪恶过犯？因为我们的罪过甚大，已经有烈怒临到以色列人了。」","notes":[]},{"n":14,"t":"于是带兵器的人将掳来的人口和掠来的财物都留在众首领和会众的面前。","notes":[]},{"n":15,"t":"以上提名的那些人就站起，使被掳的人前来；其中有赤身的，就从所掠的财物中拿出衣服和鞋来，给他们穿，又给他们吃喝，用膏抹他们；其中有软弱的，就使他们骑驴，送到棕树城耶利哥他们弟兄那里；随后就回撒马利亚去了。","notes":[]},{"n":16,"t":"那时，亚哈斯王差遣人去见亚述诸王，求他们帮助；","notes":[],"heads":["亚哈斯向亚述王求援"]},{"n":17,"t":"因为以东人又来攻击犹大，掳掠子民。","notes":[]},{"n":18,"t":"非利士人也来侵占高原和犹大南方的城邑，取了伯·示麦、亚雅仑、基低罗，梭哥和属梭哥的乡村，亭纳和属亭纳的乡村，瑾锁和属瑾锁的乡村，就住在那里。","notes":[]},{"n":19,"t":"因为以色列王亚哈斯在犹大放肆，大大干犯耶和华，所以耶和华使犹大卑微。","notes":[]},{"n":20,"t":"亚述王提革拉·毗列色上来，却没有帮助他，反倒欺凌他。","notes":[]},{"n":21,"t":"亚哈斯从耶和华殿里和王宫中，并首领家内所取的财宝给了亚述王，这也无济于事。","notes":[]},{"n":22,"t":"这亚哈斯王在急难的时候，越发得罪耶和华。","notes":[],"heads":["亚哈斯的罪行"]},{"n":23,"t":"他祭祀攻击他的大马士革之神，说：「因为亚兰王的神帮助他们，我也献祭与他，他好帮助我。」但那些神使他和以色列众人败亡了。","notes":[]},{"n":24,"t":"亚哈斯将神殿里的器皿都聚了来，毁坏了，且封锁耶和华殿的门；在耶路撒冷各处的拐角建筑祭坛，","notes":[]},{"n":25,"t":"又在犹大各城建立邱坛，与别神烧香，惹动耶和华—他列祖神的怒气。","notes":[]},{"n":26,"t":"亚哈斯其余的事和他的行为，自始至终都写在犹大和以色列诸王记上。","notes":[]},{"n":27,"t":"亚哈斯与他列祖同睡，葬在耶路撒冷城里，没有送入以色列诸王的坟墓中。他儿子希西家接续他作王。","notes":[]}]},"29":{"heading":"犹大王希西家","verses":[{"n":1,"t":"希西家登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫亚比雅，是撒迦利雅的女儿。","notes":[]},{"n":2,"t":"希西家行耶和华眼中看为正的事，效法他祖大卫一切所行的。","notes":[]},{"n":3,"t":"元年正月，开了耶和华殿的门，重新修理。","notes":[],"heads":["洁净圣殿"]},{"n":4,"t":"他召众祭司和利未人来，聚集在东边的宽阔处，","notes":[]},{"n":5,"t":"对他们说：「利未人哪，当听我说：现在你们要洁净自己，又洁净耶和华—你们列祖神的殿，从圣所中除去污秽之物。","notes":[]},{"n":6,"t":"我们列祖犯了罪，行耶和华—我们神眼中看为恶的事，离弃他，转脸背向他的居所，","notes":[]},{"n":7,"t":"封锁廊门，吹灭灯火，不在圣所中向以色列神烧香，或献燔祭。","notes":[]},{"n":8,"t":"因此，耶和华的忿怒临到犹大和耶路撒冷，将其中的人抛来抛去，令人惊骇、嗤笑，正如你们亲眼所见的。","notes":[]},{"n":9,"t":"所以我们的祖宗倒在刀下，我们的妻子儿女也被掳掠。","notes":[]},{"n":10,"t":"现在我心中有意与耶和华—以色列的神立约，好使他的烈怒转离我们。","notes":[]},{"n":11,"t":"我的众子啊，现在不要懈怠；因为耶和华拣选你们站在他面前事奉他，与他烧香。」","notes":[]},{"n":12,"t":"于是，利未人哥辖的子孙、亚玛赛的儿子玛哈，亚撒利雅的儿子约珥；米拉利的子孙、亚伯底的儿子基士，耶哈利勒的儿子亚撒利雅；革顺的子孙、薪玛的儿子约亚，约亚的儿子伊甸；","notes":[]},{"n":13,"t":"以利撒反的子孙申利和耶利；亚萨的子孙撒迦利雅和玛探雅；","notes":[]},{"n":14,"t":"希幔的子孙耶歇和示每；耶杜顿的子孙示玛雅和乌薛；","notes":[]},{"n":15,"t":"起来聚集他们的弟兄，洁净自己，照着王的吩咐、耶和华的命令，进去洁净耶和华的殿。","notes":[]},{"n":16,"t":"祭司进入耶和华的殿要洁净殿，将殿中所有污秽之物搬到耶和华殿的院内，利未人接去，搬到外头汲沦溪边。","notes":[]},{"n":17,"t":"从正月初一日洁净起，初八日到了耶和华的殿廊，用八日的工夫洁净耶和华的殿，到正月十六日才洁净完了。","notes":[]},{"n":18,"t":"于是，他们晋见希西家王，说：「我们已将耶和华的全殿和燔祭坛，并坛的一切器皿、陈设饼的桌子，与桌子的一切器皿都洁净了；","notes":[],"heads":["重新奉献圣殿"]},{"n":19,"t":"并且亚哈斯王在位犯罪的时候所废弃的器皿，我们预备齐全，且洁净了，现今都在耶和华的坛前。」","notes":[]},{"n":20,"t":"希西家王清早起来，聚集城里的首领都上耶和华的殿；","notes":[]},{"n":21,"t":"牵了七只公牛，七只公羊，七只羊羔，七只公山羊，要为国、为殿、为犹大人作赎罪祭。王吩咐亚伦的子孙众祭司，献在耶和华的坛上，","notes":[]},{"n":22,"t":"就宰了公牛，祭司接血洒在坛上，宰了公羊，把血洒在坛上，又宰了羊羔，也把血洒在坛上；","notes":[]},{"n":23,"t":"把那作赎罪祭的公山羊牵到王和会众面前，他们就按手在其上。","notes":[]},{"n":24,"t":"祭司宰了羊，将血献在坛上作赎罪祭，为以色列众人赎罪，因为王吩咐将燔祭和赎罪祭为以色列众人献上。","notes":[]},{"n":25,"t":"王又派利未人在耶和华殿中敲钹，鼓瑟，弹琴，乃照大卫和他先见迦得，并先知拿单所吩咐的，就是耶和华借先知所吩咐的。","notes":[]},{"n":26,"t":"利未人拿大卫的乐器，祭司拿号，一同站立。","notes":[]},{"n":27,"t":"希西家吩咐在坛上献燔祭，燔祭一献，就唱赞美耶和华的歌，用号，并用以色列王大卫的乐器相和。","notes":[]},{"n":28,"t":"会众都敬拜，歌唱的歌唱，吹号的吹号，如此直到燔祭献完了。","notes":[]},{"n":29,"t":"献完了祭，王和一切跟随的人都俯伏敬拜。","notes":[]},{"n":30,"t":"希西家王与众首领又吩咐利未人用大卫和先见亚萨的诗词颂赞耶和华；他们就欢欢喜喜地颂赞耶和华，低头敬拜。","notes":[]},{"n":31,"t":"希西家说：「你们既然归耶和华为圣，就要前来把祭物和感谢祭奉到耶和华殿里。」会众就把祭物和感谢祭奉来，凡甘心乐意的也将燔祭奉来。","notes":[]},{"n":32,"t":"会众所奉的燔祭如下：公牛七十只，公羊一百只，羊羔二百只，这都是作燔祭献给耶和华的；","notes":[]},{"n":33,"t":"又有分别为圣之物，公牛六百只，绵羊三千只。","notes":[]},{"n":34,"t":"但祭司太少，不能剥尽燔祭牲的皮，所以他们的弟兄利未人帮助他们，直等燔祭的事完了，又等别的祭司自洁了；因为利未人诚心自洁，胜过祭司。","notes":[]},{"n":35,"t":"燔祭和平安祭牲的脂油，并燔祭同献的奠祭甚多。这样，耶和华殿中的事务俱都齐备了。","notes":["或译：就整顿了"]},{"n":36,"t":"这事办的甚速，希西家和众民都喜乐，是因神为众民所预备的。","notes":[]}]},"30":{"heading":"预备守逾越节","verses":[{"n":1,"t":"希西家差遣人去见以色列和犹大众人，又写信给以法莲和玛拿西人，叫他们到耶路撒冷耶和华的殿，向耶和华—以色列的神守逾越节；","notes":[]},{"n":2,"t":"因为王和众首领，并耶路撒冷全会众已经商议，要在二月内守逾越节。","notes":[]},{"n":3,"t":"正月间他们不能守；因为自洁的祭司尚不敷用，百姓也没有聚集在耶路撒冷；","notes":["原文是那时"]},{"n":4,"t":"王与全会众都以这事为善。","notes":[]},{"n":5,"t":"于是定了命令，传遍以色列，从别是巴直到但，使他们都来，在耶路撒冷向耶和华—以色列的神守逾越节；因为照所写的例，守这节的不多了。","notes":["或译：因为民许久没有照所写的例守节了"]},{"n":6,"t":"驿卒就把王和众首领的信，遵着王命传遍以色列和犹大。信内说：「以色列人哪，你们当转向耶和华—亚伯拉罕、以撒、以色列的神，好叫他转向你们这脱离亚述王手的余民。","notes":[]},{"n":7,"t":"你们不要效法你们列祖和你们的弟兄；他们干犯耶和华—他们列祖的神，以致耶和华丢弃他们，使他们败亡，正如你们所见的。","notes":["或译：令人惊骇"]},{"n":8,"t":"现在不要像你们列祖硬着颈项，只要归顺耶和华，进入他的圣所，就是永远成圣的居所；又要事奉耶和华—你们的神，好使他的烈怒转离你们。","notes":[]},{"n":9,"t":"你们若转向耶和华，你们的弟兄和儿女必在掳掠他们的人面前蒙怜恤，得以归回这地，因为耶和华—你们的神有恩典、施怜悯。你们若转向他，他必不转脸不顾你们。」","notes":[]},{"n":10,"t":"驿卒就由这城跑到那城，传遍了以法莲、玛拿西，直到西布伦。那里的人却戏笑他们，讥诮他们。","notes":[]},{"n":11,"t":"然而亚设、玛拿西、西布伦中也有人自卑，来到耶路撒冷。","notes":[]},{"n":12,"t":"神也感动犹大人，使他们一心遵行王与众首领凭耶和华之言所发的命令。","notes":[]},{"n":13,"t":"二月，有许多人在耶路撒冷聚集，成为大会，要守除酵节。","notes":[],"heads":["守逾越节"]},{"n":14,"t":"他们起来，把耶路撒冷的祭坛和烧香的坛尽都除去，抛在汲沦溪中。","notes":[]},{"n":15,"t":"二月十四日，宰了逾越节的羊羔。祭司与利未人觉得惭愧，就洁净自己，把燔祭奉到耶和华殿中，","notes":[]},{"n":16,"t":"遵着神人摩西的律法，照例站在自己的地方；祭司从利未人手里接过血来，洒在坛上。","notes":[]},{"n":17,"t":"会中有许多人尚未自洁，所以利未人为一切不洁之人宰逾越节的羊羔，使他们在耶和华面前成为圣洁。","notes":[]},{"n":18,"t":"以法莲、玛拿西、以萨迦、西布伦有许多人尚未自洁，他们却也吃逾越节的羊羔，不合所记录的定例。希西家为他们祷告说：「凡专心寻求神，就是耶和华—他列祖之神的，虽不照着圣所洁净之礼自洁，求至善的耶和华也饶恕他。」","notes":[],"end":19},{"n":20,"t":"耶和华垂听希西家的祷告，就饶恕百姓。","notes":["原文是医治"]},{"n":21,"t":"在耶路撒冷的以色列人大大喜乐，守除酵节七日。利未人和祭司用响亮的乐器，日日颂赞耶和华。","notes":[]},{"n":22,"t":"希西家慰劳一切善于事奉耶和华的利未人。于是众人吃节筵七日，又献平安祭，且向耶和华—他们列祖的神认罪。","notes":[]},{"n":23,"t":"全会众商议，要再守节七日；于是欢欢喜喜地又守节七日。","notes":[],"heads":["再度守节"]},{"n":24,"t":"犹大王希西家赐给会众公牛一千只，羊七千只为祭物；众首领也赐给会众公牛一千只，羊一万只，并有许多的祭司洁净自己。","notes":[]},{"n":25,"t":"犹大全会众、祭司、利未人，并那从以色列地来的会众和寄居的人，以及犹大寄居的人，尽都喜乐。","notes":[]},{"n":26,"t":"这样，在耶路撒冷大有喜乐，自从以色列王大卫儿子所罗门的时候，在耶路撒冷没有这样的喜乐。","notes":[]},{"n":27,"t":"那时，祭司、利未人起来，为民祝福。他们的声音蒙神垂听，他们的祷告达到天上的圣所。","notes":[]}]},"31":{"heading":"希西家的改革","verses":[{"n":1,"t":"这事既都完毕，在那里的以色列众人就到犹大的城邑，打碎柱像，砍断木偶，又在犹大、便雅悯、以法莲、玛拿西遍地将邱坛和祭坛拆毁净尽。于是以色列众人各回各城，各归各地。","notes":[]},{"n":2,"t":"希西家派定祭司利未人的班次，各按各职献燔祭和平安祭，又在耶和华殿门内事奉，称谢颂赞耶和华。","notes":["原文是营"]},{"n":3,"t":"王又从自己的产业中定出分来为燔祭，就是早晚的燔祭和安息日、月朔，并节期的燔祭，都是按耶和华律法上所载的；","notes":[]},{"n":4,"t":"又吩咐住耶路撒冷的百姓将祭司、利未人所应得的分给他们，使他们专心遵守耶和华的律法。","notes":[]},{"n":5,"t":"谕旨一出，以色列人就把初熟的五谷、新酒、油、蜜，和田地的出产多多送来，又把各物的十分之一送来的极多。","notes":[]},{"n":6,"t":"住犹大各城的以色列人和犹大人也将牛羊的十分之一，并分别为圣归耶和华—他们神之物，就是十分取一之物，尽都送来，积成堆垒；","notes":[]},{"n":7,"t":"从三月积起，到七月才完。","notes":[]},{"n":8,"t":"希西家和众首领来，看见堆垒，就称颂耶和华，又为耶和华的民以色列人祝福。","notes":[]},{"n":9,"t":"希西家向祭司、利未人查问这堆垒。","notes":[]},{"n":10,"t":"撒督家的大祭司亚撒利雅回答说：「自从民将供物送到耶和华殿以来，我们不但吃饱，且剩下的甚多；因为耶和华赐福给他的民，所剩下的才这样丰盛。」","notes":[]},{"n":11,"t":"希西家吩咐在耶和华殿里预备仓房，他们就预备了。","notes":[]},{"n":12,"t":"他们诚心将供物和十分取一之物，并分别为圣之物，都搬入仓内。利未人歌楠雅掌管这事，他兄弟示每为副管。","notes":[]},{"n":13,"t":"耶歇、亚撒细雅、拿哈、亚撒黑、耶利末、约撒拔、以列、伊斯玛基雅、玛哈、比拿雅都是督理，在歌楠雅和他兄弟示每的手下，是希西家王和管理神殿的亚撒利雅所派的。","notes":[]},{"n":14,"t":"守东门的利未人音拿的儿子可利，掌管乐意献与神的礼物，发放献与耶和华的供物和至圣的物。","notes":[]},{"n":15,"t":"在他手下有伊甸、珉雅珉、耶书亚、示玛雅、亚玛利雅、示迦尼雅，在祭司的各城里供紧要的职任，无论弟兄大小，都按着班次分给他们。","notes":[]},{"n":16,"t":"按家谱，三岁以外的男丁，凡每日进耶和华殿、按班次供职的，也分给他；","notes":[]},{"n":17,"t":"又按宗族家谱分给祭司，按班次职任分给二十岁以外的利未人，","notes":[]},{"n":18,"t":"又按家谱计算，分给他们会中的妻子、儿女；因他们身供要职，自洁成圣。","notes":[]},{"n":19,"t":"按名派定的人要把应得的分给亚伦子孙，住在各城郊野、祭司所有的男丁和一切载入家谱的利未人。","notes":[]},{"n":20,"t":"希西家在犹大遍地这样办理，行耶和华—他神眼中看为善为正为忠的事。","notes":[]},{"n":21,"t":"凡他所行的，无论是办神殿的事，是遵律法守诫命，是寻求他的神，都是尽心去行，无不亨通。","notes":[]}]},"32":{"heading":"亚述人恐吓耶路撒冷","verses":[{"n":1,"t":"这虔诚的事以后，亚述王西拿基立来侵入犹大，围困一切坚固城，想要攻破占据。","notes":[]},{"n":2,"t":"希西家见西拿基立来，定意要攻打耶路撒冷，","notes":[]},{"n":3,"t":"就与首领和勇士商议，塞住城外的泉源；他们就都帮助他。","notes":[]},{"n":4,"t":"于是有许多人聚集，塞了一切泉源，并通流国中的小河，说：「亚述王来，为何让他得着许多水呢？」","notes":[]},{"n":5,"t":"希西家力图自强，就修筑所有拆毁的城墙，高与城楼相齐；在城外又筑一城，坚固大卫城的米罗，制造了许多军器、盾牌；","notes":[]},{"n":6,"t":"设立军长管理百姓，将他们招聚在城门的宽阔处，用话勉励他们，说：","notes":[]},{"n":7,"t":"「你们当刚强壮胆，不要因亚述王和跟随他的大军恐惧、惊慌；因为与我们同在的，比与他们同在的更大。","notes":[]},{"n":8,"t":"与他们同在的是肉臂，与我们同在的是耶和华—我们的神，他必帮助我们，为我们争战。」百姓就靠犹大王希西家的话，安然无惧了。","notes":[]},{"n":9,"t":"此后，亚述王西拿基立和他的全军攻打拉吉，就差遣臣仆到耶路撒冷见犹大王希西家和一切在耶路撒冷的犹大人，说：","notes":[]},{"n":10,"t":"「亚述王西拿基立如此说：『你们倚靠什么，还在耶路撒冷受困呢？","notes":[]},{"n":11,"t":"希西家对你们说「耶和华—我们的神必救我们脱离亚述王的手」，这不是诱惑你们，使你们受饥渴而死吗？","notes":[]},{"n":12,"t":"这希西家岂不是废去耶和华的邱坛和祭坛，吩咐犹大与耶路撒冷的人说「你们当在一个坛前敬拜，在其上烧香」吗？","notes":[]},{"n":13,"t":"我与我列祖向列邦所行的，你们岂不知道吗？列邦的神何尝能救自己的国脱离我手呢？","notes":[]},{"n":14,"t":"我列祖所灭的国，那些神中谁能救自己的民脱离我手呢？难道你们的神能救你们脱离我手吗？","notes":[]},{"n":15,"t":"所以你们不要叫希西家这样欺哄诱惑你们，也不要信他；因为没有一国一邦的神能救自己的民脱离我手和我列祖的手，何况你们的神更不能救你们脱离我的手。』」","notes":[]},{"n":16,"t":"西拿基立的臣仆还有别的话毁谤耶和华神和他仆人希西家。","notes":[]},{"n":17,"t":"西拿基立也写信毁谤耶和华—以色列的神说：「列邦的神既不能救他的民脱离我手，希西家的神也不能救他的民脱离我手了。」","notes":[]},{"n":18,"t":"亚述王的臣仆用犹大言语向耶路撒冷城上的民大声呼叫，要惊吓他们，扰乱他们，以便取城。","notes":[]},{"n":19,"t":"他们论耶路撒冷的神，如同论世上人手所造的神一样。","notes":[]},{"n":20,"t":"希西家王和亚摩斯的儿子先知以赛亚因此祷告，向天呼求。","notes":[]},{"n":21,"t":"耶和华就差遣一个使者进入亚述王营中，把所有大能的勇士和官长、将帅尽都灭了。亚述王满面含羞地回到本国，进了他神的庙中，有他亲生的儿子在那里用刀杀了他。","notes":[]},{"n":22,"t":"这样，耶和华救希西家和耶路撒冷的居民脱离亚述王西拿基立的手，也脱离一切仇敌的手，又赐他们四境平安。","notes":[]},{"n":23,"t":"有许多人到耶路撒冷，将供物献与耶和华，又将宝物送给犹大王希西家。此后，希西家在列邦人的眼中看为尊大。","notes":[]},{"n":24,"t":"那时希西家病得要死，就祷告耶和华，耶和华应允他，赐他一个兆头。","notes":[],"heads":["希西家的疾病和骄傲"]},{"n":25,"t":"希西家却没有照他所蒙的恩报答耶和华；因他心里骄傲，所以忿怒要临到他和犹大并耶路撒冷。","notes":[]},{"n":26,"t":"但希西家和耶路撒冷的居民觉得心里骄傲，就一同自卑，以致耶和华的忿怒在希西家的日子没有临到他们。","notes":[]},{"n":27,"t":"希西家大有尊荣资财，建造府库，收藏金银、宝石、香料、盾牌，和各样的宝器，","notes":[],"heads":["希西家的财富和尊荣"]},{"n":28,"t":"又建造仓房，收藏五谷、新酒，和油，又为各类牲畜盖棚立圈；","notes":[]},{"n":29,"t":"并且建立城邑，还有许多的羊群牛群，因为神赐他极多的财产。","notes":[]},{"n":30,"t":"这希西家也塞住基训的上源，引水直下，流在大卫城的西边。希西家所行的事尽都亨通。","notes":[]},{"n":31,"t":"惟有一件事，就是巴比伦王差遣使者来见希西家，访问国中所现的奇事；这件事神离开他，要试验他，好知道他心内如何。","notes":[]},{"n":32,"t":"希西家其余的事和他的善行都写在亚摩斯的儿子先知以赛亚的默示书上和犹大、以色列的诸王记上。","notes":[],"heads":["希西家逝世"]},{"n":33,"t":"希西家与他列祖同睡，葬在大卫子孙的高陵上。他死的时候，犹大人和耶路撒冷的居民都尊敬他。他儿子玛拿西接续他作王。","notes":[]}]},"33":{"heading":"犹大王玛拿西","verses":[{"n":1,"t":"玛拿西登基的时候年十二岁，在耶路撒冷作王五十五年。","notes":[]},{"n":2,"t":"他行耶和华眼中看为恶的事，效法耶和华在以色列人面前赶出的外邦人那可憎的事，","notes":[]},{"n":3,"t":"重新建筑他父希西家所拆毁的邱坛，又为巴力筑坛，做木偶，且敬拜事奉天上的万象，","notes":[]},{"n":4,"t":"在耶和华的殿宇中筑坛—耶和华曾指着这殿说：「我的名必永远在耶路撒冷。」","notes":[]},{"n":5,"t":"他在耶和华殿的两院中为天上的万象筑坛，","notes":[]},{"n":6,"t":"并在欣嫩子谷使他的儿女经火，又观兆，用法术，行邪术，立交鬼的和行巫术的，多行耶和华眼中看为恶的事，惹动他的怒气，","notes":[]},{"n":7,"t":"又在神殿内立雕刻的偶像。神曾对大卫和他儿子所罗门说：「我在以色列各支派中所选择的耶路撒冷和这殿，必立我的名直到永远。","notes":[]},{"n":8,"t":"以色列人若谨守遵行我借摩西所吩咐他们的一切法度、律例、典章，我就不再使他们挪移离开我所赐给他们列祖之地。」","notes":[]},{"n":9,"t":"玛拿西引诱犹大和耶路撒冷的居民，以致他们行恶比耶和华在以色列人面前所灭的列国更甚。","notes":[]},{"n":10,"t":"耶和华警戒玛拿西和他的百姓，他们却是不听。","notes":[],"heads":["玛拿西悔改"]},{"n":11,"t":"所以耶和华使亚述王的将帅来攻击他们，用铙钩钩住玛拿西，用铜链锁住他，带到巴比伦去。","notes":[]},{"n":12,"t":"他在急难的时候，就恳求耶和华—他的神，且在他列祖的神面前极其自卑。","notes":[]},{"n":13,"t":"他祈祷耶和华，耶和华就允准他的祈求，垂听他的祷告，使他归回耶路撒冷，仍坐国位。玛拿西这才知道惟独耶和华是神。","notes":[]},{"n":14,"t":"此后，玛拿西在大卫城外，从谷内基训西边直到鱼门口，建筑城墙，环绕俄斐勒，这墙筑得甚高；又在犹大各坚固城内设立勇敢的军长；","notes":[]},{"n":15,"t":"并除掉外邦人的神像与耶和华殿中的偶像，又将他在耶和华殿的山上和耶路撒冷所筑的各坛都拆毁抛在城外；","notes":[]},{"n":16,"t":"重修耶和华的祭坛，在坛上献平安祭、感谢祭，吩咐犹大人事奉耶和华—以色列的神。","notes":[]},{"n":17,"t":"百姓却仍在邱坛上献祭，只献给耶和华—他们的神。","notes":[]},{"n":18,"t":"玛拿西其余的事和祷告他神的话，并先见奉耶和华—以色列神的名警戒他的言语，都写在以色列诸王记上。","notes":[],"heads":["玛拿西逝世"]},{"n":19,"t":"他的祷告，与神怎样应允他，他未自卑以前的罪愆过犯，并在何处建筑邱坛，设立亚舍拉和雕刻的偶像，都写在何赛的书上。","notes":[]},{"n":20,"t":"玛拿西与他列祖同睡，葬在自己的宫院里。他儿子亚们接续他作王。","notes":[]},{"n":21,"t":"亚们登基的时候年二十二岁，在耶路撒冷作王二年。","notes":[],"heads":["犹大王亚们"]},{"n":22,"t":"他行耶和华眼中看为恶的事，效法他父玛拿西所行的，祭祀事奉他父玛拿西所雕刻的偶像，","notes":[]},{"n":23,"t":"不在耶和华面前像他父玛拿西自卑。这亚们所犯的罪越犯越大。","notes":[]},{"n":24,"t":"他的臣仆背叛，在宫里杀了他。","notes":[]},{"n":25,"t":"但国民杀了那些背叛亚们王的人，立他儿子约西亚接续他作王。","notes":[]}]},"34":{"heading":"犹大王约西亚","verses":[{"n":1,"t":"约西亚登基的时候年八岁，在耶路撒冷作王三十一年。","notes":[]},{"n":2,"t":"他行耶和华眼中看为正的事，效法他祖大卫所行的，不偏左右。","notes":[]},{"n":3,"t":"他作王第八年，尚且年幼，就寻求他祖大卫的神。到了十二年才洁净犹大和耶路撒冷，除掉邱坛、木偶、雕刻的像，和铸造的像。","notes":[],"heads":["约西亚清除偶像"]},{"n":4,"t":"众人在他面前拆毁巴力的坛，砍断坛上高高的日像，又把木偶和雕刻的像，并铸造的像打碎成灰，撒在祭偶像人的坟上，","notes":[]},{"n":5,"t":"将他们祭司的骸骨烧在坛上，洁净了犹大和耶路撒冷；","notes":[]},{"n":6,"t":"又在玛拿西、以法莲、西缅、拿弗他利各城，和四围破坏之处，都这样行；","notes":[]},{"n":7,"t":"又拆毁祭坛，把木偶和雕刻的像打碎成灰，砍断以色列遍地所有的日像，就回耶路撒冷去了。","notes":[]},{"n":8,"t":"约西亚王十八年，净地净殿之后，就差遣亚萨利雅的儿子沙番、邑宰玛西雅、约哈斯的儿子史官约亚去修理耶和华—他神的殿。","notes":[],"heads":["发现律法书"]},{"n":9,"t":"他们就去见大祭司希勒家，将奉到神殿的银子交给他；这银子是看守殿门的利未人从玛拿西、以法莲，和一切以色列剩下的人，以及犹大、便雅悯众人，并耶路撒冷的居民收来的。","notes":[]},{"n":10,"t":"又将这银子交给耶和华殿里督工的，转交修理耶和华殿的工匠，","notes":[]},{"n":11,"t":"就是交给木匠、石匠，买凿成的石头和架木与栋梁，修犹大王所毁坏的殿。","notes":[]},{"n":12,"t":"这些人办事诚实，督工的是利未人米拉利的子孙雅哈、俄巴底；督催的是哥辖的子孙撒迦利亚、米书兰；还有善于作乐的利未人。","notes":[]},{"n":13,"t":"他们又监管扛抬的人，督催一切做工的。利未人中也有作书记、作司事、作守门的。","notes":[]},{"n":14,"t":"他们将奉到耶和华殿的银子运出来的时候，祭司希勒家偶然得了摩西所传耶和华的律法书。","notes":[]},{"n":15,"t":"希勒家对书记沙番说：「我在耶和华殿里得了律法书。」遂将书递给沙番。","notes":[]},{"n":16,"t":"沙番把书拿到王那里，回复王说：「凡交给仆人们办的都办理了。","notes":[]},{"n":17,"t":"耶和华殿里的银子倒出来，交给督工的和匠人的手里了。」","notes":[]},{"n":18,"t":"书记沙番又对王说：「祭司希勒家递给我一卷书。」沙番就在王面前读那书。","notes":[]},{"n":19,"t":"王听见律法上的话，就撕裂衣服，","notes":[]},{"n":20,"t":"吩咐希勒家与沙番的儿子亚希甘、米迦的儿子亚比顿、书记沙番，和王的臣仆亚撒雅说：","notes":[]},{"n":21,"t":"「你们去为我、为以色列和犹大剩下的人，以这书上的话求问耶和华；因我们列祖没有遵守耶和华的言语，没有照这书上所记的去行，耶和华的烈怒就倒在我们身上。」","notes":[]},{"n":22,"t":"于是，希勒家和王所派的众人都去见女先知户勒大。户勒大是掌管礼服沙龙的妻，沙龙是哈斯拉的孙子、特瓦的儿子。户勒大住在耶路撒冷第二区；他们请问于她。","notes":[]},{"n":23,"t":"她对他们说：「耶和华—以色列的神如此说：『你们可以回复那差遣你们来见我的人说，","notes":[]},{"n":24,"t":"耶和华如此说：我必照着在犹大王面前所读那书上的一切咒诅，降祸与这地和其上的居民；","notes":[]},{"n":25,"t":"因为他们离弃我，向别神烧香，用他们手所做的惹我发怒，所以我的忿怒如火倒在这地上，总不息灭。』","notes":[]},{"n":26,"t":"然而差遣你们来求问耶和华的犹大王，你们要这样回复他说：『耶和华—以色列的神如此说：至于你所听见的话，","notes":[]},{"n":27,"t":"就是听见我指着这地和其上居民所说的话，你便心里敬服，在我面前自卑，撕裂衣服，向我哭泣，因此我应允了你。这是我—耶和华说的。","notes":[]},{"n":28,"t":"我必使你平平安安地归到坟墓，到你列祖那里，我要降与这地和其上居民的一切灾祸，你也不至亲眼看见。』」他们就回复王去了。","notes":[]},{"n":29,"t":"王差遣人招聚犹大和耶路撒冷的众长老来。","notes":[],"heads":["约西亚立约顺从主"]},{"n":30,"t":"王和犹大众人，与耶路撒冷的居民，并祭司利未人，以及所有的百姓，无论大小，都一同上到耶和华的殿；王就把殿里所得的约书念给他们听。","notes":[]},{"n":31,"t":"王站在他的地位上，在耶和华面前立约，要尽心尽性地顺从耶和华，遵守他的诫命、法度、律例，成就这书上所记的约言；","notes":[]},{"n":32,"t":"又使住耶路撒冷和便雅悯的人都服从这约。于是耶路撒冷的居民都遵行他们列祖之神的约。","notes":[]},{"n":33,"t":"约西亚从以色列各处将一切可憎之物尽都除掉，使以色列境内的人都事奉耶和华—他们的神。约西亚在世的日子，就跟从耶和华—他们列祖的神，总不离开。","notes":[]}]},"35":{"heading":"约西亚守逾越节","verses":[{"n":1,"t":"约西亚在耶路撒冷向耶和华守逾越节。正月十四日，就宰了逾越节的羊羔。","notes":[]},{"n":2,"t":"王分派祭司各尽其职，又勉励他们办耶和华殿中的事；","notes":[]},{"n":3,"t":"又对那归耶和华为圣、教训以色列人的利未人说：「你们将圣约柜安放在以色列王大卫儿子所罗门建造的殿里，不必再用肩扛抬。现在要事奉耶和华—你们的神，服事他的民以色列。","notes":[]},{"n":4,"t":"你们应当按着宗族，照着班次，遵以色列王大卫和他儿子所罗门所写的，自己预备。","notes":[]},{"n":5,"t":"要按着你们的弟兄，这民宗族的班次，站在圣所，每班中要利未宗族的几个人。","notes":[]},{"n":6,"t":"要宰逾越节的羊羔，洁净自己，为你们的弟兄预备了，好遵守耶和华借摩西所吩咐的话。」","notes":[]},{"n":7,"t":"约西亚从群畜中赐给在那里所有的人民，绵羊羔和山羊羔三万只，牛三千只，作逾越节的祭物；这都是出自王的产业中。","notes":[]},{"n":8,"t":"约西亚的众首领也乐意将牺牲给百姓和祭司利未人；又有管理神殿的希勒家、撒迦利亚、耶歇将羊羔二千六百只，牛三百只，给祭司作逾越节的祭物。","notes":[]},{"n":9,"t":"利未人的族长歌楠雅和他两个兄弟示玛雅、拿坦业，与哈沙比雅、耶利、约撒拔将羊羔五千只，牛五百只，给利未人作逾越节的祭物。","notes":[]},{"n":10,"t":"这样，供献的事齐备了。祭司站在自己的地方，利未人按着班次站立，都是照王所吩咐的。","notes":[]},{"n":11,"t":"利未人宰了逾越节的羊羔，祭司从他们手里接过血来洒在坛上；利未人剥皮，","notes":[]},{"n":12,"t":"将燔祭搬来，按着宗族的班次分给众民，好照摩西书上所写的，献给耶和华；献牛也是这样。","notes":[]},{"n":13,"t":"他们按着常例，用火烤逾越节的羊羔。别的圣物用锅，用釜，用罐煮了，速速地送给众民。","notes":[]},{"n":14,"t":"然后为自己和祭司预备祭物；因为祭司亚伦的子孙献燔祭和脂油，直到晚上。所以利未人为自己和祭司亚伦的子孙，预备祭物。","notes":[]},{"n":15,"t":"歌唱的亚萨之子孙，照着大卫、亚萨、希幔，和王的先见耶杜顿所吩咐的，站在自己的地位上。守门的看守各门，不用离开他们的职事，因为他们的弟兄利未人给他们预备祭物。","notes":[]},{"n":16,"t":"当日，供奉耶和华的事齐备了，就照约西亚王的吩咐守逾越节，献燔祭在耶和华的坛上。","notes":[]},{"n":17,"t":"当时在耶路撒冷的以色列人守逾越节，又守除酵节七日。","notes":[]},{"n":18,"t":"自从先知撒母耳以来，在以色列中没有守过这样的逾越节，以色列诸王也没有守过，像约西亚、祭司、利未人、在那里的犹大人，和以色列人，以及耶路撒冷居民所守的逾越节。","notes":[]},{"n":19,"t":"这逾越节是约西亚作王十八年守的。","notes":[]},{"n":20,"t":"这事以后，约西亚修完了殿，有埃及王尼哥上来，要攻击靠近幼发拉底河的迦基米施；约西亚出去抵挡他。","notes":[],"heads":["约西亚逝世"]},{"n":21,"t":"他差遣使者来见约西亚，说：「犹大王啊，我与你何干？我今日来不是要攻击你，乃是要攻击与我争战之家，并且神吩咐我速行，你不要干预神的事，免得他毁灭你，因为神是与我同在。」","notes":[]},{"n":22,"t":"约西亚却不肯转去离开他，改装要与他打仗，不听从神借尼哥之口所说的话，便来到米吉多平原争战。","notes":[]},{"n":23,"t":"弓箭手射中约西亚王。王对他的臣仆说：「我受了重伤，你拉我出阵吧！」","notes":[]},{"n":24,"t":"他的臣仆扶他下了战车，上了次车，送他到耶路撒冷，他就死了，葬在他列祖的坟墓里。犹大人和耶路撒冷人都为他悲哀。","notes":[]},{"n":25,"t":"耶利米为约西亚作哀歌。所有歌唱的男女也唱哀歌，追悼约西亚，直到今日；而且在以色列中成了定例。这歌载在哀歌书上。","notes":[]},{"n":26,"t":"约西亚其余的事和他遵着耶和华律法上所记而行的善事，","notes":[]},{"n":27,"t":"并他自始至终所行的，都写在以色列和犹大列王记上。","notes":[]}]},"36":{"heading":"犹大王约哈斯","verses":[{"n":1,"t":"国民立约西亚的儿子约哈斯在耶路撒冷接续他父作王。","notes":[]},{"n":2,"t":"约哈斯登基的时候年二十三岁，在耶路撒冷作王三个月。","notes":[]},{"n":3,"t":"埃及王在耶路撒冷废了他，又罚犹大国银子一百他连得，金子一他连得。","notes":[]},{"n":4,"t":"埃及王尼哥立约哈斯的哥哥以利雅敬作犹大和耶路撒冷的王，改名叫约雅敬，又将约哈斯带到埃及去了。","notes":[]},{"n":5,"t":"约雅敬登基的时候年二十五岁，在耶路撒冷作王十一年，行耶和华—他神眼中看为恶的事。","notes":[],"heads":["犹大王约雅敬"]},{"n":6,"t":"巴比伦王尼布甲尼撒上来攻击他，用铜链锁着他，要将他带到巴比伦去。","notes":[]},{"n":7,"t":"尼布甲尼撒又将耶和华殿里的器皿带到巴比伦，放在他神的庙里。","notes":["或译：自己的宫里"]},{"n":8,"t":"约雅敬其余的事和他所行可憎的事，并他一切的行为，都写在以色列和犹大列王记上。他儿子约雅斤接续他作王。","notes":[]},{"n":9,"t":"约雅斤登基的时候年八岁，在耶路撒冷作王三个月零十天，行耶和华眼中看为恶的事。","notes":["在列王下二十四章八节是十八岁"],"heads":["犹大王约雅斤"]},{"n":10,"t":"过了一年，尼布甲尼撒差遣人将约雅斤和耶和华殿里各样宝贵的器皿带到巴比伦，就立约雅斤的叔叔西底家作犹大和耶路撒冷的王。","notes":["原文是兄"]},{"n":11,"t":"西底家登基的时候年二十一岁，在耶路撒冷作王十一年，","notes":[],"heads":["犹大王西底家"]},{"n":12,"t":"行耶和华—他神眼中看为恶的事。先知耶利米以耶和华的话劝他，他仍不在耶利米面前自卑。","notes":[]},{"n":13,"t":"尼布甲尼撒曾使他指着神起誓，他却背叛，强项硬心，不归服耶和华—以色列的神。","notes":[],"heads":["耶路撒冷陷落"]},{"n":14,"t":"众祭司长和百姓也大大犯罪，效法外邦人一切可憎的事，污秽耶和华在耶路撒冷分别为圣的殿。","notes":[]},{"n":15,"t":"耶和华—他们列祖的神因为爱惜自己的民和他的居所，从早起来差遣使者去警戒他们。","notes":[]},{"n":16,"t":"他们却嘻笑神的使者，藐视他的言语，讥诮他的先知，以致耶和华的忿怒向他的百姓发作，无法可救。","notes":[]},{"n":17,"t":"所以，耶和华使迦勒底人的王来攻击他们，在他们圣殿里用刀杀了他们的壮丁，不怜恤他们的少男处女、老人白叟。耶和华将他们都交在迦勒底王手里。","notes":[]},{"n":18,"t":"迦勒底王将神殿里的大小器皿与耶和华殿里的财宝，并王和众首领的财宝，都带到巴比伦去了。","notes":[]},{"n":19,"t":"迦勒底人焚烧神的殿，拆毁耶路撒冷的城墙，用火烧了城里的宫殿，毁坏了城里宝贵的器皿。","notes":[]},{"n":20,"t":"凡脱离刀剑的，迦勒底王都掳到巴比伦去，作他和他子孙的仆婢，直到波斯国兴起来。","notes":[]},{"n":21,"t":"这就应验耶和华借耶利米口所说的话：地享受安息；因为地土荒凉便守安息，直满了七十年。","notes":[]},{"n":22,"t":"波斯王塞鲁士元年，耶和华为要应验借耶利米口所说的话，就激动波斯王塞鲁士的心，使他下诏通告全国，说：","notes":[],"heads":["塞鲁士王下令犹大人返国"]},{"n":23,"t":"「波斯王塞鲁士如此说：耶和华—天上的神已将天下万国赐给我，又嘱咐我在犹大的耶路撒冷为他建造殿宇。你们中间凡作他子民的，可以上去，愿耶和华—他的神与他同在。」","notes":[]}]}},"EZR":{"1":{"heading":"塞鲁士下令犹太人返国","verses":[{"n":1,"t":"波斯王塞鲁士元年，耶和华为要应验借耶利米口所说的话，就激动波斯王塞鲁士的心，使他下诏通告全国说：","notes":[]},{"n":2,"t":"「波斯王塞鲁士如此说：『耶和华天上的神已将天下万国赐给我，又嘱咐我在犹大的耶路撒冷为他建造殿宇。","notes":[]},{"n":3,"t":"在你们中间凡作他子民的，可以上犹大的耶路撒冷，在耶路撒冷重建耶和华—以色列神的殿（只有他是神）。愿神与这人同在。","notes":[]},{"n":4,"t":"凡剩下的人，无论寄居何处，那地的人要用金银、财物、牲畜帮助他，另外也要为耶路撒冷神的殿甘心献上礼物。』」","notes":[]},{"n":5,"t":"于是，犹大和便雅悯的族长、祭司、利未人，就是一切被神激动他心的人，都起来要上耶路撒冷去建造耶和华的殿。","notes":[]},{"n":6,"t":"他们四围的人就拿银器、金子、财物、牲畜、珍宝帮助他们，另外还有甘心献的礼物。","notes":["原文是坚固他们的手"]},{"n":7,"t":"塞鲁士王也将耶和华殿的器皿拿出来，这器皿是尼布甲尼撒从耶路撒冷掠来、放在自己神之庙中的。","notes":[]},{"n":8,"t":"波斯王塞鲁士派库官米提利达将这器皿拿出来，按数交给犹大的首领设巴萨。","notes":[]},{"n":9,"t":"器皿的数目记在下面：金盘三十个，银盘一千个，刀二十九把，","notes":[]},{"n":10,"t":"金碗三十个，银碗之次的四百一十个，别样的器皿一千件。","notes":[]},{"n":11,"t":"金银器皿共有五千四百件。被掳的人从巴比伦上耶路撒冷的时候，设巴萨将这一切都带上来。","notes":[]}]},"2":{"heading":"被掳归回者的名单","verses":[{"n":1,"t":"巴比伦王尼布甲尼撒从前掳到巴比伦之犹大省的人，现在他们的子孙从被掳到之地回耶路撒冷和犹大，各归本城。","notes":[]},{"n":2,"t":"他们是同着所罗巴伯、耶书亚、尼希米、西莱雅、利来雅、末底改、必珊、米斯拔、比革瓦伊、利宏、巴拿回来的。","notes":[]},{"n":3,"t":"以色列人民的数目记在下面：巴录的子孙二千一百七十二名；","notes":[]},{"n":4,"t":"示法提雅的子孙三百七十二名；","notes":[]},{"n":5,"t":"亚拉的子孙七百七十五名；","notes":[]},{"n":6,"t":"巴哈·摩押的后裔，就是耶书亚和约押的子孙二千八百一十二名；","notes":[]},{"n":7,"t":"以拦的子孙一千二百五十四名；","notes":[]},{"n":8,"t":"萨土的子孙九百四十五名；","notes":[]},{"n":9,"t":"萨改的子孙七百六十名；","notes":[]},{"n":10,"t":"巴尼的子孙六百四十二名；","notes":[]},{"n":11,"t":"比拜的子孙六百二十三名；","notes":[]},{"n":12,"t":"押甲的子孙一千二百二十二名；","notes":[]},{"n":13,"t":"亚多尼干的子孙六百六十六名；","notes":[]},{"n":14,"t":"比革瓦伊的子孙二千零五十六名；","notes":[]},{"n":15,"t":"亚丁的子孙四百五十四名；","notes":[]},{"n":16,"t":"亚特的后裔，就是希西家的子孙九十八名；","notes":[]},{"n":17,"t":"比赛的子孙三百二十三名；","notes":[]},{"n":18,"t":"约拉的子孙一百一十二名；","notes":[]},{"n":19,"t":"哈顺的子孙二百二十三名；","notes":[]},{"n":20,"t":"吉罢珥人九十五名；","notes":[]},{"n":21,"t":"伯利恒人一百二十三名；","notes":[]},{"n":22,"t":"尼陀法人五十六名；","notes":[]},{"n":23,"t":"亚拿突人一百二十八名；","notes":[]},{"n":24,"t":"亚斯玛弗人四十二名；","notes":[]},{"n":25,"t":"基列·耶琳人、基非拉人、比录人共七百四十三名；","notes":[]},{"n":26,"t":"拉玛人、迦巴人共六百二十一名；","notes":[]},{"n":27,"t":"默玛人一百二十二名；","notes":[]},{"n":28,"t":"伯特利人、艾人共二百二十三名；","notes":[]},{"n":29,"t":"尼波人五十二名；","notes":[]},{"n":30,"t":"末必人一百五十六名；","notes":[]},{"n":31,"t":"别的以拦子孙一千二百五十四名；","notes":[]},{"n":32,"t":"哈琳的子孙三百二十名；","notes":[]},{"n":33,"t":"罗德人、哈第人、阿挪人共七百二十五名；","notes":[]},{"n":34,"t":"耶利哥人三百四十五名；","notes":[]},{"n":35,"t":"西拿人三千六百三十名。","notes":[]},{"n":36,"t":"祭司：耶书亚家耶大雅的子孙九百七十三名；","notes":[]},{"n":37,"t":"音麦的子孙一千零五十二名；","notes":[]},{"n":38,"t":"巴施户珥的子孙一千二百四十七名；","notes":[]},{"n":39,"t":"哈琳的子孙一千零一十七名。","notes":[]},{"n":40,"t":"利未人：何达威雅的后裔，就是耶书亚和甲篾的子孙七十四名。","notes":[]},{"n":41,"t":"歌唱的：亚萨的子孙一百二十八名。","notes":[]},{"n":42,"t":"守门的：沙龙的子孙、亚特的子孙、达们的子孙、亚谷的子孙、哈底大的子孙、朔拜的子孙，共一百三十九名。","notes":[]},{"n":43,"t":"尼提宁：西哈的子孙、哈苏巴的子孙、答巴俄的子孙、","notes":["就是殿役"]},{"n":44,"t":"基绿的子孙、西亚的子孙、巴顿的子孙、","notes":[]},{"n":45,"t":"利巴拿的子孙、哈迦巴的子孙、亚谷的子孙、","notes":[]},{"n":46,"t":"哈甲的子孙、萨买的子孙、哈难的子孙、","notes":[]},{"n":47,"t":"吉德的子孙、迦哈的子孙、利亚雅的子孙、","notes":[]},{"n":48,"t":"利汛的子孙、尼哥大的子孙、迦散的子孙、","notes":[]},{"n":49,"t":"乌撒的子孙、巴西亚的子孙、比赛的子孙、","notes":[]},{"n":50,"t":"押拿的子孙、米乌宁的子孙、尼普心的子孙、","notes":[]},{"n":51,"t":"巴卜的子孙、哈古巴的子孙、哈忽的子孙、","notes":[]},{"n":52,"t":"巴洗律的子孙、米希大的子孙、哈沙的子孙、","notes":[]},{"n":53,"t":"巴柯的子孙、西西拉的子孙、答玛的子孙、","notes":[]},{"n":54,"t":"尼细亚的子孙、哈提法的子孙。","notes":[]},{"n":55,"t":"所罗门仆人的后裔，就是琐太的子孙、琐斐列的子孙、比路大的子孙、","notes":[]},{"n":56,"t":"雅拉的子孙、达昆的子孙、吉德的子孙、","notes":[]},{"n":57,"t":"示法提雅的子孙、哈替的子孙、玻黑列·哈斯巴音的子孙、亚米的子孙。","notes":[]},{"n":58,"t":"尼提宁和所罗门仆人的后裔共三百九十二名。","notes":[]},{"n":59,"t":"从特·米拉、特·哈萨、基绿、押但、音麦上来的，不能指明他们的宗族谱系是以色列人不是；","notes":[]},{"n":60,"t":"他们是第来雅的子孙、多比雅的子孙、尼哥大的子孙，共六百五十二名。","notes":[]},{"n":61,"t":"祭司中，哈巴雅的子孙、哈哥斯的子孙、巴西莱的子孙；因为他们的先祖娶了基列人巴西莱的女儿为妻，所以起名叫巴西莱。","notes":[]},{"n":62,"t":"这三家的人在族谱之中寻查自己的谱系，却寻不着，因此算为不洁，不准供祭司的职任。","notes":[]},{"n":63,"t":"省长对他们说：「不可吃至圣的物，直到有用乌陵和土明决疑的祭司兴起来。」","notes":[]},{"n":64,"t":"会众共有四万二千三百六十名。","notes":[]},{"n":65,"t":"此外，还有他们的仆婢七千三百三十七名，又有歌唱的男女二百名。","notes":[]},{"n":66,"t":"他们有马七百三十六匹，骡子二百四十五匹，","notes":[]},{"n":67,"t":"骆驼四百三十五只，驴六千七百二十匹。","notes":[]},{"n":68,"t":"有些族长到了耶路撒冷耶和华殿的地方，便为神的殿甘心献上礼物，要重新建造。","notes":[]},{"n":69,"t":"他们量力捐入工程库的金子六万一千达利克，银子五千弥拿，并祭司的礼服一百件。","notes":[]},{"n":70,"t":"于是祭司、利未人、民中的一些人、歌唱的、守门的、尼提宁，并以色列众人，各住在自己的城里。","notes":[]}]},"3":{"heading":"恢复敬拜神的生活","verses":[{"n":1,"t":"到了七月，以色列人住在各城；那时他们如同一人，聚集在耶路撒冷。","notes":[]},{"n":2,"t":"约萨达的儿子耶书亚和他的弟兄众祭司，并撒拉铁的儿子所罗巴伯与他的弟兄，都起来建筑以色列神的坛，要照神人摩西律法书上所写的，在坛上献燔祭。","notes":[]},{"n":3,"t":"他们在原有的根基上筑坛，因惧怕邻国的民，又在其上向耶和华早晚献燔祭，","notes":[]},{"n":4,"t":"又照律法书上所写的守住棚节，按数照例献每日所当献的燔祭；","notes":[]},{"n":5,"t":"其后献常献的燔祭，并在月朔与耶和华的一切圣节献祭，又向耶和华献各人的甘心祭。","notes":[]},{"n":6,"t":"从七月初一日起，他们就向耶和华献燔祭。但耶和华殿的根基尚未立定。","notes":[]},{"n":7,"t":"他们又将银子给石匠、木匠，把粮食、酒、油给西顿人、泰尔人，使他们将香柏树从黎巴嫩运到海里，浮海运到约帕，是照波斯王塞鲁士所允准的。","notes":[]},{"n":8,"t":"百姓到了耶路撒冷神殿的地方。第二年二月，撒拉铁的儿子所罗巴伯，约萨达的儿子耶书亚和其余的弟兄，就是祭司、利未人，并一切被掳归回耶路撒冷的人，都兴工建造；又派利未人，从二十岁以外的，督理建造耶和华殿的工作。","notes":[],"heads":["开始重建圣殿"]},{"n":9,"t":"于是犹大的后裔，就是耶书亚和他的子孙与弟兄，甲篾和他的子孙，利未人希拿达的子孙与弟兄，都一同起来，督理那在神殿做工的人。","notes":["在二章四十节作何达威雅"]},{"n":10,"t":"匠人立耶和华殿根基的时候，祭司皆穿礼服吹号，亚萨的子孙利未人敲钹，照以色列王大卫所定的例，都站着赞美耶和华。","notes":[]},{"n":11,"t":"他们彼此唱和，赞美称谢耶和华说：他本为善，他向以色列人永发慈爱。他们赞美耶和华的时候，众民大声呼喊，因耶和华殿的根基已经立定。","notes":[]},{"n":12,"t":"然而有许多祭司、利未人、族长，就是见过旧殿的老年人，现在亲眼看见立这殿的根基，便大声哭号，也有许多人大声欢呼，","notes":[]},{"n":13,"t":"甚至百姓不能分辨欢呼的声音和哭号的声音；因为众人大声呼喊，声音听到远处。","notes":[]}]},"4":{"heading":"建殿之工受阻","verses":[{"n":1,"t":"犹大和便雅悯的敌人听说被掳归回的人为耶和华—以色列的神建造殿宇，","notes":[]},{"n":2,"t":"就去见所罗巴伯和以色列的族长，对他们说：「请容我们与你们一同建造；因为我们寻求你们的神，与你们一样。自从亚述王以撒哈顿带我们上这地以来，我们常祭祀神。」","notes":[]},{"n":3,"t":"但所罗巴伯、耶书亚，和其余以色列的族长对他们说：「我们建造神的殿与你们无干，我们自己为耶和华—以色列的神协力建造，是照波斯王塞鲁士所吩咐的。」","notes":[]},{"n":4,"t":"那地的民，就在犹大人建造的时候，使他们的手发软，扰乱他们；","notes":[]},{"n":5,"t":"从波斯王塞鲁士年间，直到波斯王大流士登基的时候，贿买谋士，要败坏他们的谋算。","notes":[]},{"n":6,"t":"在亚哈随鲁才登基的时候，上本控告犹大和耶路撒冷的居民。","notes":[],"heads":["阻扰重建耶路撒冷"]},{"n":7,"t":"亚达薛西年间，比施兰、米特利达、他别，和他们的同党上本奏告波斯王亚达薛西。本章是用亚兰文字，亚兰方言。","notes":[]},{"n":8,"t":"省长利宏、书记伸帅要控告耶路撒冷人，也上本奏告亚达薛西王。","notes":[]},{"n":9,"t":"省长利宏、书记伸帅，和同党的底拿人、亚法萨提迦人、他毗拉人、亚法撒人、亚基卫人、巴比伦人、书珊迦人、底亥人、以拦人，","notes":[]},{"n":10,"t":"和尊大的亚斯那巴所迁移、安置在撒马利亚城，并大河西一带地方的人等，","notes":[]},{"n":11,"t":"上奏亚达薛西王说：「河西的臣民云云：","notes":[]},{"n":12,"t":"王该知道，从王那里上到我们这里的犹大人，已经到耶路撒冷重建这反叛恶劣的城，筑立根基，建造城墙。","notes":[]},{"n":13,"t":"如今王该知道，他们若建造这城，城墙完毕就不再与王进贡，交课，纳税，终久王必受亏损。","notes":[]},{"n":14,"t":"我们既食御盐，不忍见王吃亏，因此奏告于王。","notes":[]},{"n":15,"t":"请王考察先王的实录，必在其上查知这城是反叛的城，与列王和各省有害；自古以来，其中常有悖逆的事，因此这城曾被拆毁。","notes":[]},{"n":16,"t":"我们谨奏王知，这城若再建造，城墙完毕，河西之地王就无分了。」","notes":[]},{"n":17,"t":"那时王谕复省长利宏、书记伸帅，和他们的同党，就是住撒马利亚并河西一带地方的人，说：「愿你们平安云云。","notes":[]},{"n":18,"t":"你们所上的本，已经明读在我面前。","notes":[]},{"n":19,"t":"我已命人考查，得知此城古来果然背叛列王，其中常有反叛悖逆的事。","notes":[]},{"n":20,"t":"从前耶路撒冷也有大君王统管河西全地，人就给他们进贡，交课，纳税。","notes":[]},{"n":21,"t":"现在你们要出告示命这些人停工，使这城不得建造，等我降旨。","notes":[]},{"n":22,"t":"你们当谨慎，不可迟延，为何容害加重，使王受亏损呢？」","notes":[]},{"n":23,"t":"亚达薛西王的上谕读在利宏和书记伸帅，并他们的同党面前，他们就急忙往耶路撒冷去见犹大人，用势力强迫他们停工。","notes":[]},{"n":24,"t":"于是，在耶路撒冷神殿的工程就停止了，直停到波斯王大流士第二年。","notes":[],"heads":["恢复重建圣殿工作"]}]},"5":{"heading":"","verses":[{"n":1,"t":"那时，先知哈该和易多的孙子撒迦利亚奉以色列神的名向犹大和耶路撒冷的犹大人说劝勉的话。","notes":[]},{"n":2,"t":"于是撒拉铁的儿子所罗巴伯和约萨达的儿子耶书亚都起来动手建造耶路撒冷神的殿，有神的先知在那里帮助他们。","notes":[]},{"n":3,"t":"当时河西的总督达乃和示他·波斯乃，并他们的同党来问说：「谁降旨让你们建造这殿，修成这墙呢？」","notes":[]},{"n":4,"t":"我们便告诉他们建造这殿的人叫什么名字。","notes":[]},{"n":5,"t":"神的眼目看顾犹大的长老，以致总督等没有叫他们停工，直到这事奏告大流士，得着他的回谕。","notes":[]},{"n":6,"t":"河西的总督达乃和示他·波斯乃，并他们的同党，就是住河西的亚法萨迦人，上本奏告大流士王。","notes":[]},{"n":7,"t":"本上写着说：「愿大流士王诸事平安。","notes":[]},{"n":8,"t":"王该知道，我们往犹大省去，到了至大神的殿，这殿是用大石建造的。梁木插入墙内，工作甚速，他们手下亨通。","notes":[]},{"n":9,"t":"我们就问那些长老说：『谁降旨让你们建造这殿，修成这墙呢？』","notes":[]},{"n":10,"t":"又问他们的名字，要记录他们首领的名字，奏告于王。","notes":[]},{"n":11,"t":"他们回答说：『我们是天地之神的仆人，重建前多年所建造的殿，就是以色列的一位大君王建造修成的。","notes":[]},{"n":12,"t":"只因我们列祖惹天上的神发怒，神把他们交在迦勒底人巴比伦王尼布甲尼撒的手中，他就拆毁这殿，又将百姓掳到巴比伦。","notes":[]},{"n":13,"t":"然而巴比伦王塞鲁士元年，他降旨允准建造神的这殿。","notes":[]},{"n":14,"t":"神殿中的金、银器皿，就是尼布甲尼撒从耶路撒冷的殿中掠去带到巴比伦庙里的，塞鲁士王从巴比伦庙里取出来，交给派为省长的，名叫设巴萨，","notes":[]},{"n":15,"t":"对他说可以将这些器皿带去，放在耶路撒冷的殿中，在原处建造神的殿。","notes":[]},{"n":16,"t":"于是这设巴萨来建立耶路撒冷神殿的根基。这殿从那时直到如今尚未造成。』","notes":[]},{"n":17,"t":"现在王若以为美，请察巴比伦王的府库，看塞鲁士王降旨允准在耶路撒冷建造神的殿没有，王的心意如何？请降旨晓谕我们。」","notes":[]}]},"6":{"heading":"发现塞鲁士王原有的诏令","verses":[{"n":1,"t":"于是大流士王降旨，要寻察典籍库内，就是在巴比伦藏宝物之处；","notes":[]},{"n":2,"t":"在米底亚省亚马他城的宫内寻得一卷，其中记着说：","notes":[]},{"n":3,"t":"「塞鲁士王元年，他降旨论到耶路撒冷神的殿，要建造这殿为献祭之处，坚立殿的根基。殿高六十肘，宽六十肘，","notes":[]},{"n":4,"t":"用三层大石头，一层新木头，经费要出于王库；","notes":[]},{"n":5,"t":"并且神殿的金银器皿，就是尼布甲尼撒从耶路撒冷的殿中掠到巴比伦的，要归还带到耶路撒冷的殿中，各按原处放在神的殿里。」","notes":[]},{"n":6,"t":"「现在河西的总督达乃和示他·波斯乃，并你们的同党，就是住河西的亚法萨迦人，你们当远离他们。","notes":[],"heads":["大流士王下令继续建殿"]},{"n":7,"t":"不要拦阻神殿的工作，任凭犹大人的省长和犹大人的长老在原处建造神的这殿。","notes":[]},{"n":8,"t":"我又降旨，吩咐你们向犹大人的长老为建造神的殿当怎样行，就是从河西的款项中，急速拨取贡银作他们的经费，免得耽误工作。","notes":[]},{"n":9,"t":"他们与天上的神献燔祭所需用的公牛犊、公绵羊、绵羊羔，并所用的麦子、盐、酒、油，都要照耶路撒冷祭司的话，每日供给他们，不得有误；","notes":[]},{"n":10,"t":"好叫他们献馨香的祭给天上的神，又为王和王众子的寿命祈祷。","notes":[]},{"n":11,"t":"我再降旨，无论谁更改这命令，必从他房屋中拆出一根梁来，把他举起，悬在其上，又使他的房屋成为粪堆。","notes":[]},{"n":12,"t":"若有王和民伸手更改这命令，拆毁这殿，愿那使耶路撒冷的殿作为他名居所的神将他们灭绝。我—大流士降这旨意，当速速遵行。」","notes":[]},{"n":13,"t":"于是，河西总督达乃和示他·波斯乃，并他们的同党，因大流士王所发的命令，就急速遵行。","notes":[],"heads":["圣殿奉献典礼"]},{"n":14,"t":"犹大长老因先知哈该和易多的孙子撒迦利亚所说劝勉的话就建造这殿，凡事亨通。他们遵着以色列神的命令和波斯王塞鲁士、大流士、亚达薛西的旨意，建造完毕。","notes":[]},{"n":15,"t":"大流士王第六年，亚达月初三日，这殿修成了。","notes":[]},{"n":16,"t":"以色列的祭司和利未人，并其余被掳归回的人都欢欢喜喜地行奉献神殿的礼。","notes":[]},{"n":17,"t":"行奉献神殿的礼就献公牛一百只，公绵羊二百只，绵羊羔四百只，又照以色列支派的数目献公山羊十二只，为以色列众人作赎罪祭；","notes":[]},{"n":18,"t":"且派祭司和利未人按着班次在耶路撒冷事奉神，是照摩西律法书上所写的。","notes":[]},{"n":19,"t":"正月十四日，被掳归回的人守逾越节。","notes":[],"heads":["守逾越节"]},{"n":20,"t":"原来，祭司和利未人一同自洁，无一人不洁净。利未人为被掳归回的众人和他们的弟兄众祭司，并为自己宰逾越节的羊羔。","notes":[]},{"n":21,"t":"从掳到之地归回的以色列人和一切除掉所染外邦人污秽、归附他们、要寻求耶和华—以色列神的人都吃这羊羔，","notes":[]},{"n":22,"t":"欢欢喜喜地守除酵节七日；因为耶和华使他们欢喜，又使亚述王的心转向他们，坚固他们的手，作以色列神殿的工程。","notes":[]}]},"7":{"heading":"以斯拉到达耶路撒冷","verses":[{"n":1,"t":"这事以后，波斯王亚达薛西年间，有个以斯拉，他是西莱雅的儿子，西莱雅是亚撒利雅的儿子，亚撒利雅是希勒家的儿子，","notes":[]},{"n":2,"t":"希勒家是沙龙的儿子，沙龙是撒督的儿子，撒督是亚希突的儿子，","notes":[]},{"n":3,"t":"亚希突是亚玛利雅的儿子，亚玛利雅是亚撒利雅的儿子，亚撒利雅是米拉约的儿子，","notes":[]},{"n":4,"t":"米拉约是西拉希雅的儿子，西拉希雅是乌西的儿子，乌西是布基的儿子，","notes":[]},{"n":5,"t":"布基是亚比书的儿子，亚比书是非尼哈的儿子，非尼哈是以利亚撒的儿子，以利亚撒是大祭司亚伦的儿子。","notes":[]},{"n":6,"t":"这以斯拉从巴比伦上来，他是敏捷的文士，通达耶和华—以色列神所赐摩西的律法书。王允准他一切所求的，是因耶和华—他神的手帮助他。","notes":[]},{"n":7,"t":"亚达薛西王第七年，以色列人、祭司、利未人、歌唱的、守门的、尼提宁，有上耶路撒冷的。","notes":[]},{"n":8,"t":"王第七年五月，以斯拉到了耶路撒冷。","notes":[]},{"n":9,"t":"正月初一日，他从巴比伦起程；因他神施恩的手帮助他，五月初一日就到了耶路撒冷。","notes":[]},{"n":10,"t":"以斯拉定志考究遵行耶和华的律法，又将律例典章教训以色列人。","notes":[]},{"n":11,"t":"祭司以斯拉是通达耶和华诫命和赐以色列之律例的文士。亚达薛西王赐给他们谕旨，上面写着说：","notes":[],"heads":["亚达薛西王给以斯拉的文件"]},{"n":12,"t":"「诸王之王亚达薛西，达于祭司以斯拉通达天上神律法大德的文士，云云。","notes":[]},{"n":13,"t":"住在我国中的以色列人、祭司、利未人，凡甘心上耶路撒冷去的，我降旨准他们与你同去。","notes":[]},{"n":14,"t":"王与七个谋士既然差你去，照你手中神的律法书察问犹大和耶路撒冷的景况；","notes":[]},{"n":15,"t":"又带金银，就是王和谋士甘心献给住耶路撒冷、以色列神的，","notes":[]},{"n":16,"t":"并带你在巴比伦全省所得的金银，和百姓、祭司乐意献给耶路撒冷—他们神殿的礼物。","notes":[]},{"n":17,"t":"所以你当用这金银，急速买公牛、公绵羊、绵羊羔，和同献的素祭奠祭之物，献在耶路撒冷—你们神殿的坛上。","notes":[]},{"n":18,"t":"剩下的金银，你和你的弟兄看着怎样好，就怎样用，总要遵着你们神的旨意。","notes":[]},{"n":19,"t":"所交给你神殿中使用的器皿，你要交在耶路撒冷神面前。","notes":[]},{"n":20,"t":"你神殿里若再有需用的经费，你可以从王的府库里支取。","notes":[]},{"n":21,"t":"「我—亚达薛西王又降旨与河西的一切库官，说：『通达天上神律法的文士祭司以斯拉，无论向你们要什么，你们要速速地备办，","notes":[]},{"n":22,"t":"就是银子直到一百他连得，麦子一百柯珥，酒一百罢特，油一百罢特，盐不计其数，也要给他。","notes":[]},{"n":23,"t":"凡天上之神所吩咐的，当为天上神的殿详细办理。为何使忿怒临到王和王众子的国呢？","notes":[]},{"n":24,"t":"我又晓谕你们，至于祭司、利未人、歌唱的、守门的，和尼提宁，并在神殿当差的人，不可叫他们进贡，交课，纳税。』","notes":[]},{"n":25,"t":"「以斯拉啊，要照着你神赐你的智慧，将所有明白你神律法的人立为士师、审判官，治理河西的百姓，使他们教训一切不明白神律法的人。","notes":[]},{"n":26,"t":"凡不遵行你神律法和王命令的人就当速速定他的罪，或治死，或充军，或抄家，或囚禁。」","notes":[]},{"n":27,"t":"以斯拉说：「耶和华—我们列祖的神是应当称颂的！因他使王起这心意修饰耶路撒冷耶和华的殿，","notes":[],"heads":["以斯拉称颂耶和华"]},{"n":28,"t":"又在王和谋士，并大能的军长面前施恩于我。因耶和华—我神的手帮助我，我就得以坚强，从以色列中招聚首领，与我一同上来。」","notes":[]}]},"8":{"heading":"从被掳之地回来的人","verses":[{"n":1,"t":"当亚达薛西王年间，同我从巴比伦上来的人，他们的族长和他们的家谱记在下面：","notes":[]},{"n":2,"t":"属非尼哈的子孙有革顺；属以他玛的子孙有但以理；属大卫的子孙有哈突；","notes":[]},{"n":3,"t":"属巴录的后裔，就是示迦尼的子孙有撒迦利亚，同着他，按家谱计算，男丁一百五十人；","notes":[]},{"n":4,"t":"属巴哈·摩押的子孙有西拉希雅的儿子以利约乃，同着他有男丁二百；","notes":[]},{"n":5,"t":"属示迦尼的子孙有雅哈悉的儿子，同着他有男丁三百；","notes":[]},{"n":6,"t":"属亚丁的子孙有约拿单的儿子以别，同着他有男丁五十；","notes":[]},{"n":7,"t":"属以拦的子孙有亚他利雅的儿子耶筛亚，同着他有男丁七十；","notes":[]},{"n":8,"t":"属示法提雅的子孙有米迦勒的儿子西巴第雅，同着他有男丁八十；","notes":[]},{"n":9,"t":"属约押的子孙有耶歇的儿子俄巴底亚，同着他有男丁二百一十八；","notes":[]},{"n":10,"t":"属示罗密的子孙有约细斐的儿子，同着他有男丁一百六十；","notes":[]},{"n":11,"t":"属比拜的子孙有比拜的儿子撒迦利亚，同着他有男丁二十八；","notes":[]},{"n":12,"t":"属押甲的子孙有哈加坦的儿子约哈难，同着他有男丁一百一十；","notes":[]},{"n":13,"t":"属亚多尼干的子孙，就是末尾的，他们的名字是以利法列、耶利、示玛雅，同着他们有男丁六十；","notes":[]},{"n":14,"t":"属比革瓦伊的子孙有乌太和撒布，同着他们有男丁七十。","notes":[]},{"n":15,"t":"我招聚这些人在流入亚哈瓦的河边，我们在那里住了三日。我查看百姓和祭司，见没有利未人在那里，","notes":[],"heads":["以斯拉为圣殿招集利未人"]},{"n":16,"t":"就召首领以利以谢、亚列、示玛雅、以利拿单、雅立、以利拿单、拿单、撒迦利亚、米书兰，又召教习约雅立和以利拿单。","notes":[]},{"n":17,"t":"我打发他们往迦西斐雅地方去见那里的首领易多，又告诉他们当向易多和他的弟兄尼提宁说什么话，叫他们为我们神的殿带使用的人来。","notes":[]},{"n":18,"t":"蒙我们神施恩的手帮助我们，他们在以色列的曾孙、利未的孙子、抹利的后裔中带一个通达人来；还有示利比和他的众子与弟兄共一十八人。","notes":[]},{"n":19,"t":"又有哈沙比雅，同着他有米拉利的子孙耶筛亚，并他的众子和弟兄共二十人。","notes":[]},{"n":20,"t":"从前大卫和众首领派尼提宁服事利未人，现在从这尼提宁中也带了二百二十人来，都是按名指定的。","notes":[]},{"n":21,"t":"那时，我在亚哈瓦河边宣告禁食，为要在我们神面前克苦己心，求他使我们和妇人孩子，并一切所有的，都得平坦的道路。","notes":[],"heads":["以斯拉领百姓禁食祷告"]},{"n":22,"t":"我求王拨步兵马兵帮助我们抵挡路上的仇敌，本以为羞耻；因我曾对王说：「我们神施恩的手必帮助一切寻求他的；但他的能力和忿怒必攻击一切离弃他的。」","notes":[]},{"n":23,"t":"所以我们禁食祈求我们的神，他就应允了我们。","notes":[]},{"n":24,"t":"我分派祭司长十二人，就是示利比、哈沙比雅，和他们的弟兄十人，","notes":[],"heads":["献给圣殿的礼物"]},{"n":25,"t":"将王和谋士、军长，并在那里的以色列众人为我们神殿所献的金银和器皿，都秤了交给他们。","notes":[]},{"n":26,"t":"我秤了交在他们手中的银子有六百五十他连得；银器重一百他连得；金子一百他连得；","notes":[]},{"n":27,"t":"金碗二十个，重一千达利克；上等光铜的器皿两个，宝贵如金。","notes":[]},{"n":28,"t":"我对他们说：「你们归耶和华为圣，器皿也为圣；金银是甘心献给耶和华—你们列祖之神的。","notes":[]},{"n":29,"t":"你们当警醒看守，直到你们在耶路撒冷耶和华殿的库内，在祭司长和利未族长，并以色列的各族长面前过了秤。」","notes":[]},{"n":30,"t":"于是，祭司、利未人按着分量接受金银和器皿，要带到耶路撒冷我们神的殿里。","notes":[]},{"n":31,"t":"正月十二日，我们从亚哈瓦河边起行，要往耶路撒冷去。我们神的手保佑我们，救我们脱离仇敌和路上埋伏之人的手。","notes":[],"heads":["返回耶路撒冷"]},{"n":32,"t":"我们到了耶路撒冷，在那里住了三日。","notes":[]},{"n":33,"t":"第四日，在我们神的殿里把金银和器皿都秤了，交在祭司乌利亚的儿子米利末的手中。同着他有非尼哈的儿子以利亚撒，还有利未人耶书亚的儿子约撒拔和宾内的儿子挪亚底。","notes":[]},{"n":34,"t":"当时都点了数目，按着分量写在册上。","notes":[]},{"n":35,"t":"从掳到之地归回的人向以色列的神献燔祭，就是为以色列众人献公牛十二只，公绵羊九十六只，绵羊羔七十七只，又献公山羊十二只作赎罪祭，这都是向耶和华焚献的。","notes":[]},{"n":36,"t":"他们将王的谕旨交给王所派的总督与河西的省长，他们就帮助百姓，又供给神殿里所需用的。","notes":[]}]},"9":{"heading":"谴责跟异族通婚","verses":[{"n":1,"t":"这事做完了，众首领来见我，说：「以色列民和祭司并利未人，没有离绝迦南人、赫人、比利洗人、耶布斯人、亚扪人、摩押人、埃及人、亚摩利人，仍效法这些国的民，行可憎的事。","notes":[]},{"n":2,"t":"因他们为自己和儿子娶了这些外邦女子为妻，以致圣洁的种类和这些国的民混杂；而且首领和官长在这事上为罪魁。」","notes":[]},{"n":3,"t":"我一听见这事，就撕裂衣服和外袍，拔了头发和胡须，惊惧忧闷而坐。","notes":[]},{"n":4,"t":"凡为以色列神言语战兢的，都因这被掳归回之人所犯的罪聚集到我这里来。我就惊惧忧闷而坐，直到献晚祭的时候。","notes":[]},{"n":5,"t":"献晚祭的时候我起来，心中愁苦，穿着撕裂的衣袍，双膝跪下向耶和华—我的神举手，","notes":[]},{"n":6,"t":"说：「我的神啊，我抱愧蒙羞，不敢向我神仰面；因为我们的罪孽灭顶，我们的罪恶滔天。","notes":[]},{"n":7,"t":"从我们列祖直到今日，我们的罪恶甚重；因我们的罪孽，我们和君王、祭司都交在外邦列王的手中，杀害、掳掠、抢夺、脸上蒙羞正如今日的光景。","notes":[]},{"n":8,"t":"现在耶和华—我们的神暂且施恩与我们，给我们留些逃脱的人，使我们安稳如钉子钉在他的圣所，我们的神好光照我们的眼目，使我们在受辖制之中稍微复兴。","notes":[]},{"n":9,"t":"我们是奴仆，然而在受辖制之中，我们的神仍没有丢弃我们，在波斯王眼前向我们施恩，叫我们复兴，能重建我们神的殿，修其毁坏之处，使我们在犹大和耶路撒冷有墙垣。","notes":[]},{"n":10,"t":"「我们的神啊，既是如此，我们还有什么话可说呢？因为我们已经离弃你的命令，","notes":[]},{"n":11,"t":"就是你借你仆人众先知所吩咐的说：『你们要去得为业之地是污秽之地；因列国之民的污秽和可憎的事，叫全地从这边直到那边满了污秽。","notes":[]},{"n":12,"t":"所以不可将你们的女儿嫁他们的儿子，也不可为你们的儿子娶他们的女儿，永不可求他们的平安和他们的利益，这样你们就可以强盛，吃这地的美物，并遗留这地给你们的子孙永远为业。』","notes":[]},{"n":13,"t":"神啊，我们因自己的恶行和大罪，遭遇了这一切的事，并且你刑罚我们轻于我们罪所当得的，又给我们留下这些人。","notes":[]},{"n":14,"t":"我们岂可再违背你的命令，与这行可憎之事的民结亲呢？若这样行，你岂不向我们发怒，将我们灭绝，以致没有一个剩下逃脱的人吗？","notes":[]},{"n":15,"t":"耶和华—以色列的神啊，因你是公义的，我们这剩下的人才得逃脱，正如今日的光景。看哪，我们在你面前有罪恶，因此无人在你面前站立得住。」","notes":[]}]},"10":{"heading":"终止与异族通婚的措施","verses":[{"n":1,"t":"以斯拉祷告，认罪，哭泣，俯伏在神殿前的时候，有以色列中的男女孩童聚集到以斯拉那里，成了大会，众民无不痛哭。","notes":[]},{"n":2,"t":"属以拦的子孙、耶歇的儿子示迦尼对以斯拉说：「我们在此地娶了外邦女子为妻，干犯了我们的神，然而以色列人还有指望。","notes":[]},{"n":3,"t":"现在当与我们的神立约，休这一切的妻，离绝她们所生的，照着我主和那因神命令战兢之人所议定的，按律法而行。","notes":[]},{"n":4,"t":"你起来，这是你当办的事，我们必帮助你，你当奋勉而行。」","notes":[]},{"n":5,"t":"以斯拉便起来，使祭司长和利未人，并以色列众人起誓说，必照这话去行；他们就起了誓。","notes":[]},{"n":6,"t":"以斯拉从神殿前起来，进入以利亚实的儿子约哈难的屋里，到了那里不吃饭，也不喝水；因为被掳归回之人所犯的罪，心里悲伤。","notes":[]},{"n":7,"t":"他们通告犹大和耶路撒冷被掳归回的人，叫他们在耶路撒冷聚集。","notes":[]},{"n":8,"t":"凡不遵首领和长老所议定、三日之内不来的，就必抄他的家，使他离开被掳归回之人的会。","notes":[]},{"n":9,"t":"于是，犹大和便雅悯众人，三日之内都聚集在耶路撒冷。那日正是九月二十日，众人都坐在神殿前的宽阔处；因这事，又因下大雨，就都战兢。","notes":[]},{"n":10,"t":"祭司以斯拉站起来，对他们说：「你们有罪了；因你们娶了外邦的女子为妻，增添以色列人的罪恶。","notes":[]},{"n":11,"t":"现在当向耶和华—你们列祖的神认罪，遵行他的旨意，离绝这些国的民和外邦的女子。」","notes":[]},{"n":12,"t":"会众都大声回答说：「我们必照着你的话行，","notes":[]},{"n":13,"t":"只是百姓众多，又逢大雨的时令，我们不能站在外头，这也不是一两天办完的事，因我们在这事上犯了大罪；","notes":[]},{"n":14,"t":"不如为全会众派首领办理。凡我们城邑中娶外邦女子为妻的，当按所定的日期，同着本城的长老和士师而来，直到办完这事，神的烈怒就转离我们了。」","notes":[]},{"n":15,"t":"惟有亚撒黑的儿子约拿单，特瓦的儿子雅哈谢阻挡这事，并有米书兰和利未人沙比太帮助他们。","notes":["或译：总办"]},{"n":16,"t":"被掳归回的人如此而行。祭司以斯拉和些族长按着宗族都指名见派；在十月初一日，一同在座查办这事，","notes":[]},{"n":17,"t":"到正月初一日，才查清娶外邦女子的人数。","notes":[]},{"n":18,"t":"在祭司中查出娶外邦女子为妻的，就是耶书亚的子孙约萨达的儿子，和他弟兄玛西雅、以利以谢、雅立、基大利；","notes":[],"heads":["娶外邦女子的人"]},{"n":19,"t":"他们便应许必休他们的妻。他们因有罪，就献群中的一只公绵羊赎罪。","notes":[]},{"n":20,"t":"音麦的子孙中，有哈拿尼、西巴第雅。","notes":[]},{"n":21,"t":"哈琳的子孙中，有玛西雅、以利雅、示玛雅、耶歇、乌西雅。","notes":[]},{"n":22,"t":"巴施户珥的子孙中，有以利约乃、玛西雅、以实玛利、拿坦业、约撒拔、以利亚撒。","notes":[]},{"n":23,"t":"利未人中，有约撒拔、示每、基拉雅（基拉雅就是基利他），还有毗他希雅、犹大、以利以谢。","notes":[]},{"n":24,"t":"歌唱的人中有以利亚实。守门的人中，有沙龙、提联、乌利。","notes":[]},{"n":25,"t":"以色列人巴录的子孙中，有拉米、耶西雅、玛基雅、米雅民、以利亚撒、玛基雅、比拿雅。","notes":[]},{"n":26,"t":"以拦的子孙中，有玛他尼、撒迦利亚、耶歇、押底、耶利末、以利雅。","notes":[]},{"n":27,"t":"萨土的子孙中，有以利约乃、以利亚实、玛他尼、耶利末、撒拔、亚西撒。","notes":[]},{"n":28,"t":"比拜的子孙中，有约哈难、哈拿尼雅、萨拜、亚勒。","notes":[]},{"n":29,"t":"巴尼的子孙中，有米书兰、玛鹿、亚大雅、雅述、示押、耶利末。","notes":[]},{"n":30,"t":"巴哈·摩押的子孙中，有阿底拿、基拉、比拿雅、玛西雅、玛他尼、比撒列、宾内、玛拿西。","notes":[]},{"n":31,"t":"哈琳的子孙中，有以利以谢、伊示雅、玛基雅、示玛雅、西缅、","notes":[]},{"n":32,"t":"便雅悯、玛鹿、示玛利雅。","notes":[]},{"n":33,"t":"哈顺的子孙中，有玛特乃、玛达他、撒拔、以利法列、耶利买、玛拿西、示每。","notes":[]},{"n":34,"t":"巴尼的子孙中，有玛玳、暗兰、乌益、","notes":[]},{"n":35,"t":"比拿雅、比底雅、基禄、","notes":[]},{"n":36,"t":"瓦尼雅、米利末、以利亚实、","notes":[]},{"n":37,"t":"玛他尼、玛特乃、雅扫、","notes":[]},{"n":38,"t":"巴尼、宾内、示每、","notes":[]},{"n":39,"t":"示利米雅、拿单、亚大雅、","notes":[]},{"n":40,"t":"玛拿底拜、沙赛、沙赖、","notes":[]},{"n":41,"t":"亚萨利、示利米雅、示玛利雅、","notes":[]},{"n":42,"t":"沙龙、亚玛利雅、约瑟。","notes":[]},{"n":43,"t":"尼波的子孙中，有耶利、玛他提雅、撒拔、西比拿、雅玳、约珥、比拿雅。","notes":[]},{"n":44,"t":"这些人都娶了外邦女子为妻，其中也有生了儿女的。","notes":[]}]}},"NEH":{"1":{"heading":"尼希米关心耶路撒冷","verses":[{"n":1,"t":"哈迦利亚的儿子尼希米的言语如下：亚达薛西王二十年基斯流月，我在书珊城的宫中。","notes":[]},{"n":2,"t":"那时，有我一个弟兄哈拿尼，同着几个人从犹大来。我问他们那些被掳归回、剩下逃脱的犹大人和耶路撒冷的光景。","notes":[]},{"n":3,"t":"他们对我说：「那些被掳归回剩下的人在犹大省遭大难，受凌辱；并且耶路撒冷的城墙拆毁，城门被火焚烧。」","notes":[]},{"n":4,"t":"我听见这话，就坐下哭泣，悲哀几日，在天上的神面前禁食祈祷，说：","notes":[]},{"n":5,"t":"「耶和华—天上的神，大而可畏的神啊，你向爱你、守你诫命的人守约施慈爱。","notes":[]},{"n":6,"t":"愿你睁眼看，侧耳听，你仆人昼夜在你面前为你众仆人以色列民的祈祷，承认我们以色列人向你所犯的罪；我与我父家都有罪了。","notes":[]},{"n":7,"t":"我们向你所行的甚是邪恶，没有遵守你借着仆人摩西所吩咐的诫命、律例、典章。","notes":[]},{"n":8,"t":"求你记念所吩咐你仆人摩西的话，说：『你们若犯罪，我就把你们分散在万民中；","notes":[]},{"n":9,"t":"但你们若归向我，谨守遵行我的诫命，你们被赶散的人虽在天涯，我也必从那里将他们招聚回来，带到我所选择立为我名的居所。』","notes":[]},{"n":10,"t":"这都是你的仆人、你的百姓，就是你用大力和大能的手所救赎的。","notes":[]},{"n":11,"t":"主啊，求你侧耳听你仆人的祈祷，和喜爱敬畏你名众仆人的祈祷，使你仆人现今亨通，在王面前蒙恩。」我是作王酒政的。","notes":[]}]},"2":{"heading":"尼希米返耶路撒冷","verses":[{"n":1,"t":"亚达薛西王二十年尼散月，在王面前摆酒，我拿起酒来奉给王。我素来在王面前没有愁容。","notes":[]},{"n":2,"t":"王对我说：「你既没有病，为什么面带愁容呢？这不是别的，必是你心中愁烦。」于是我甚惧怕。","notes":[]},{"n":3,"t":"我对王说：「愿王万岁！我列祖坟墓所在的那城荒凉，城门被火焚烧，我岂能面无愁容吗？」","notes":[]},{"n":4,"t":"王问我说：「你要求什么？」于是我默祷天上的神。","notes":[]},{"n":5,"t":"我对王说：「仆人若在王眼前蒙恩，王若喜欢，求王差遣我往犹大，到我列祖坟墓所在的那城去，我好重新建造。」","notes":[]},{"n":6,"t":"那时王后坐在王的旁边。王问我说：「你去要多少日子？几时回来？」我就定了日期。于是王喜欢差遣我去。","notes":[]},{"n":7,"t":"我又对王说：「王若喜欢，求王赐我诏书，通知大河西的省长准我经过，直到犹大；","notes":[]},{"n":8,"t":"又赐诏书，通知管理王园林的亚萨，使他给我木料，做属殿营楼之门的横梁和城墙，与我自己房屋使用的。」王就允准我，因我神施恩的手帮助我。","notes":[]},{"n":9,"t":"王派了军长和马兵护送我。我到了河西的省长那里，将王的诏书交给他们。","notes":[]},{"n":10,"t":"和伦人参巴拉，并为奴的亚扪人多比雅，听见有人来为以色列人求好处，就甚恼怒。","notes":[]},{"n":11,"t":"我到了耶路撒冷，在那里住了三日。","notes":[]},{"n":12,"t":"我夜间起来，有几个人也一同起来；但神使我心里要为耶路撒冷做什么事，我并没有告诉人。除了我骑的牲口以外，也没有别的牲口在我那里。","notes":[]},{"n":13,"t":"当夜我出了谷门，往野狗井去，到了粪厂门，察看耶路撒冷的城墙，见城墙拆毁，城门被火焚烧。","notes":["野狗：或译龙"]},{"n":14,"t":"我又往前，到了泉门和王池，但所骑的牲口没有地方过去。","notes":[]},{"n":15,"t":"于是夜间沿溪而上，察看城墙，又转身进入谷门，就回来了。","notes":[]},{"n":16,"t":"我往哪里去，我做什么事，官长都不知道。我还没有告诉犹大平民、祭司、贵胄、官长，和其余做工的人。","notes":[]},{"n":17,"t":"以后，我对他们说：「我们所遭的难，耶路撒冷怎样荒凉，城门被火焚烧，你们都看见了。来吧，我们重建耶路撒冷的城墙，免得再受凌辱！」","notes":[]},{"n":18,"t":"我告诉他们我神施恩的手怎样帮助我，并王对我所说的话。他们就说：「我们起来建造吧！」于是他们奋勇做这善工。","notes":[]},{"n":19,"t":"但和伦人参巴拉，并为奴的亚扪人多比雅和阿拉伯人基善听见就嗤笑我们，藐视我们，说：「你们做什么呢？要背叛王吗？」","notes":[]},{"n":20,"t":"我回答他们说：「天上的神必使我们亨通。我们作他仆人的，要起来建造；你们却在耶路撒冷无分、无权、无纪念。」","notes":[]}]},"3":{"heading":"重建耶路撒冷城墙","verses":[{"n":1,"t":"那时，大祭司以利亚实和他的弟兄众祭司起来建立羊门，分别为圣，安立门扇，又筑城墙到哈米亚楼，直到哈楠业楼，分别为圣。","notes":[]},{"n":2,"t":"其次是耶利哥人建造。其次是音利的儿子撒刻建造。","notes":[]},{"n":3,"t":"哈西拿的子孙建立鱼门，架横梁、安门扇，和闩锁。","notes":[]},{"n":4,"t":"其次是哈哥斯的孙子、乌利亚的儿子米利末修造。其次是米示萨别的孙子、比利迦的儿子米书兰修造。其次是巴拿的儿子撒督修造。","notes":[]},{"n":5,"t":"其次是提哥亚人修造；但是他们的贵胄不用肩担他们主的工作。","notes":["原文是颈项"]},{"n":6,"t":"巴西亚的儿子耶何耶大与比所玳的儿子米书兰修造古门，架横梁，安门扇和闩锁。","notes":[]},{"n":7,"t":"其次是基遍人米拉提，米伦人雅顿与基遍人，并属河西总督所管的米斯巴人修造。","notes":[]},{"n":8,"t":"其次是银匠哈海雅的儿子乌薛修造。其次是做香的哈拿尼雅修造。这些人修坚耶路撒冷，直到宽墙。","notes":[]},{"n":9,"t":"其次是管理耶路撒冷一半、户珥的儿子利法雅修造。","notes":[]},{"n":10,"t":"其次是哈路抹的儿子耶大雅对着自己的房屋修造。其次是哈沙尼的儿子哈突修造。","notes":[]},{"n":11,"t":"哈琳的儿子玛基雅和巴哈·摩押的儿子哈述修造一段，并修造炉楼。","notes":[]},{"n":12,"t":"其次是管理耶路撒冷那一半、哈罗黑的儿子沙龙和他的女儿们修造。","notes":[]},{"n":13,"t":"哈嫩和撒挪亚的居民修造谷门，立门，安门扇和闩锁，又建筑城墙一千肘，直到粪厂门。","notes":[]},{"n":14,"t":"管理伯·哈基琳、利甲的儿子玛基雅修造粪厂门，立门，安门扇和闩锁。","notes":[]},{"n":15,"t":"管理米斯巴、各荷西的儿子沙仑修造泉门，立门，盖门顶，安门扇和闩锁，又修造靠近王园西罗亚池的墙垣，直到那从大卫城下来的台阶。","notes":[]},{"n":16,"t":"其次是管理伯·夙一半、押卜的儿子尼希米修造，直到大卫坟地的对面，又到挖成的池子，并勇士的房屋。","notes":[]},{"n":17,"t":"其次是利未人巴尼的儿子利宏修造。其次是管理基伊拉一半、哈沙比雅为他所管的本境修造。","notes":[],"heads":["造城墙的利未人"]},{"n":18,"t":"其次是利未人弟兄中管理基伊拉那一半、希拿达的儿子巴瓦伊修造。","notes":[]},{"n":19,"t":"其次是管理米斯巴、耶书亚的儿子以谢修造一段，对着武库的上坡、城墙转弯之处。","notes":[]},{"n":20,"t":"其次是萨拜的儿子巴录竭力修造一段，从城墙转弯，直到大祭司以利亚实的府门。","notes":[]},{"n":21,"t":"其次是哈哥斯的孙子、乌利亚的儿子米利末修造一段，从以利亚实的府门，直到以利亚实府的尽头。","notes":[]},{"n":22,"t":"其次是住平原的祭司修造。","notes":[],"heads":["造城墙的祭司"]},{"n":23,"t":"其次是便雅悯与哈述对着自己的房屋修造。其次是亚难尼的孙子、玛西雅的儿子亚撒利雅在靠近自己的房屋修造。","notes":[]},{"n":24,"t":"其次是希拿达的儿子宾内修造一段，从亚撒利雅的房屋直到城墙转弯，又到城角。","notes":[]},{"n":25,"t":"乌赛的儿子巴拉修造对着城墙的转弯和王上宫凸出来的城楼，靠近护卫院的那一段。其次是巴录的儿子毗大雅修造。（","notes":[]},{"n":26,"t":"尼提宁住在俄斐勒，直到朝东水门的对面和凸出来的城楼。）","notes":[]},{"n":27,"t":"其次是提哥亚人又修一段，对着那凸出来的大楼，直到俄斐勒的墙。","notes":[],"heads":["其他建造的人"]},{"n":28,"t":"从马门往上，众祭司各对自己的房屋修造。","notes":[]},{"n":29,"t":"其次是音麦的儿子撒督对着自己的房屋修造。其次是守东门、示迦尼的儿子示玛雅修造。","notes":[]},{"n":30,"t":"其次是示利米雅的儿子哈拿尼雅和萨拉的第六子哈嫩又修一段。其次是比利迦的儿子米书兰对着自己的房屋修造。","notes":[]},{"n":31,"t":"其次是银匠玛基雅修造到尼提宁和商人的房屋，对着哈米弗甲门，直到城的角楼。","notes":[]},{"n":32,"t":"银匠与商人在城的角楼和羊门中间修造。","notes":[]}]},"4":{"heading":"尼希米胜过阻扰他工作的人","verses":[{"n":1,"t":"参巴拉听见我们修造城墙就发怒，大大恼恨，嗤笑犹大人，","notes":[]},{"n":2,"t":"对他弟兄和撒马利亚的军兵说：「这些软弱的犹大人做什么呢？要保护自己吗？要献祭吗？要一日成功吗？要从土堆里拿出火烧的石头再立墙吗？」","notes":[]},{"n":3,"t":"亚扪人多比雅站在旁边，说：「他们所修造的石墙，就是狐狸上去也必跐倒。」","notes":[]},{"n":4,"t":"我们的神啊，求你垂听，因为我们被藐视。求你使他们的毁谤归于他们的头上，使他们在掳到之地作为掠物。","notes":[]},{"n":5,"t":"不要遮掩他们的罪孽，不要使他们的罪恶从你面前涂抹，因为他们在修造的人眼前惹动你的怒气。","notes":[]},{"n":6,"t":"这样，我们修造城墙，城墙就都连络，高至一半，因为百姓专心做工。","notes":[]},{"n":7,"t":"参巴拉、多比雅、阿拉伯人、亚扪人、亚实突人听见修造耶路撒冷城墙，着手进行堵塞破裂的地方，就甚发怒。","notes":[]},{"n":8,"t":"大家同谋要来攻击耶路撒冷，使城内扰乱。","notes":[]},{"n":9,"t":"然而，我们祷告我们的神，又因他们的缘故，就派人看守，昼夜防备。","notes":[]},{"n":10,"t":"犹大人说：「灰土尚多，扛抬的人力气已经衰败，所以我们不能建造城墙。」","notes":[]},{"n":11,"t":"我们的敌人且说：「趁他们不知不见，我们进入他们中间，杀他们，使工作止住。」","notes":[]},{"n":12,"t":"那靠近敌人居住的犹大人十次从各处来见我们，说：「你们必要回到我们那里。」","notes":[]},{"n":13,"t":"所以我使百姓各按宗族拿刀、拿枪、拿弓站在城墙后边低洼的空处。","notes":[]},{"n":14,"t":"我察看了，就起来对贵胄、官长，和其余的人说：「不要怕他们！当记念主是大而可畏的。你们要为弟兄、儿女、妻子、家产争战。」","notes":[]},{"n":15,"t":"仇敌听见我们知道他们的心意，见神也破坏他们的计谋，就不来了。我们都回到城墙那里，各做各的工。","notes":[]},{"n":16,"t":"从那日起，我的仆人一半做工，一半拿枪、拿盾牌、拿弓、穿铠甲，官长都站在犹大众人的后边。","notes":["或译：拿"]},{"n":17,"t":"修造城墙的，扛抬材料的，都一手做工一手拿兵器。","notes":[]},{"n":18,"t":"修造的人都腰间佩刀修造，吹角的人在我旁边。","notes":[]},{"n":19,"t":"我对贵胄、官长，和其余的人说：「这工程浩大，我们在城墙上相离甚远；","notes":[]},{"n":20,"t":"你们听见角声在哪里，就聚集到我们那里去。我们的神必为我们争战。」","notes":[]},{"n":21,"t":"于是，我们做工，一半拿兵器，从天亮直到星宿出现的时候。","notes":[]},{"n":22,"t":"那时，我又对百姓说：「各人和他的仆人当在耶路撒冷住宿，好在夜间保守我们，白昼做工。」","notes":[]},{"n":23,"t":"这样，我和弟兄仆人，并跟从我的护兵都不脱衣服，出去打水也带兵器。","notes":[]}]},"5":{"heading":"尼希米处理官长们的剥削","verses":[{"n":1,"t":"百姓和他们的妻大大呼号，埋怨他们的弟兄犹大人。","notes":[]},{"n":2,"t":"有的说：「我们和儿女人口众多，要去得粮食度命」；","notes":[]},{"n":3,"t":"有的说：「我们典了田地、葡萄园、房屋，要得粮食充饥」；","notes":[]},{"n":4,"t":"有的说：「我们已经指着田地、葡萄园，借了钱给王纳税。","notes":[]},{"n":5,"t":"我们的身体与我们弟兄的身体一样；我们的儿女与他们的儿女一般。现在我们将要使儿女作人的仆婢，我们的女儿已有为婢的；我们并无力拯救，因为我们的田地、葡萄园已经归了别人。」","notes":[]},{"n":6,"t":"我听见他们呼号说这些话，便甚发怒。","notes":[]},{"n":7,"t":"我心里筹划，就斥责贵胄和官长说：「你们各人向弟兄取利！」于是我招聚大会攻击他们。","notes":[]},{"n":8,"t":"我对他们说：「我们尽力赎回我们弟兄，就是卖与外邦的犹大人；你们还要卖弟兄，使我们赎回来吗？」他们就静默不语，无话可答。","notes":[]},{"n":9,"t":"我又说：「你们所行的不善！你们行事不当敬畏我们的神吗？不然，难免我们的仇敌外邦人毁谤我们。","notes":[]},{"n":10,"t":"我和我的弟兄与仆人也将银钱粮食借给百姓；我们大家都当免去利息。","notes":[]},{"n":11,"t":"如今我劝你们将他们的田地、葡萄园、橄榄园、房屋，并向他们所取的银钱、粮食、新酒，和油，百分之一的利息都归还他们。」","notes":[]},{"n":12,"t":"众人说：「我们必归还，不再向他们索要，必照你的话行。」我就召了祭司来，叫众人起誓，必照着所应许的而行。","notes":[]},{"n":13,"t":"我也抖着胸前的衣襟，说：「凡不成就这应许的，愿神照样抖他离开家产和他劳碌得来的，直到抖空了。」会众都说：「阿们！」又赞美耶和华。百姓就照着所应许的去行。","notes":[]},{"n":14,"t":"自从我奉派作犹大地的省长，就是从亚达薛西王二十年直到三十二年，共十二年之久，我与我弟兄都没有吃省长的俸禄。","notes":[],"heads":["尼希米大公无私"]},{"n":15,"t":"在我以前的省长加重百姓的担子，每日索要粮食和酒，并银子四十舍客勒，就是他们的仆人也辖制百姓；但我因敬畏神不这样行。","notes":[]},{"n":16,"t":"并且我恒心修造城墙，并没有置买田地；我的仆人也都聚集在那里做工。","notes":[]},{"n":17,"t":"除了从四围外邦中来的犹大人以外，有犹大平民和官长一百五十人在我席上吃饭。","notes":[]},{"n":18,"t":"每日预备一只公牛，六只肥羊，又预备些飞禽；每十日一次，多预备各样的酒。虽然如此，我并不要省长的俸禄，因为百姓服役甚重。","notes":[]},{"n":19,"t":"我的神啊，求你记念我为这百姓所行的一切事，施恩与我。","notes":[]}]},"6":{"heading":"敌对尼希米的阴谋","verses":[{"n":1,"t":"参巴拉、多比雅、阿拉伯人基善和我们其余的仇敌听见我已经修完了城墙，其中没有破裂之处（那时我还没有安门扇），","notes":[]},{"n":2,"t":"参巴拉和基善就打发人来见我，说：「请你来，我们在阿挪平原的一个村庄相会。」他们却想害我。","notes":[]},{"n":3,"t":"于是我差遣人去见他们，说：「我现在办理大工，不能下去。焉能停工下去见你们呢？」","notes":[]},{"n":4,"t":"他们这样四次打发人来见我，我都如此回答他们。","notes":[]},{"n":5,"t":"参巴拉第五次打发仆人来见我，手里拿着未封的信，","notes":[]},{"n":6,"t":"信上写着说：「外邦人中有风声，迦施慕也说，你和犹大人谋反，修造城墙，你要作他们的王；","notes":["就是基善，见二章十九节"]},{"n":7,"t":"你又派先知在耶路撒冷指着你宣讲，说在犹大有王。现在这话必传与王知；所以请你来，与我们彼此商议。」","notes":[]},{"n":8,"t":"我就差遣人去见他，说：「你所说的这事，一概没有，是你心里捏造的。」","notes":[]},{"n":9,"t":"他们都要使我们惧怕，意思说，他们的手必软弱，以致工作不能成就。神啊，求你坚固我的手。","notes":[]},{"n":10,"t":"我到了米希大别的孙子、第来雅的儿子示玛雅家里；那时，他闭门不出。他说：「我们不如在神的殿里会面，将殿门关锁；因为他们要来杀你，就是夜里来杀你。」","notes":[]},{"n":11,"t":"我说：「像我这样的人岂要逃跑呢？像我这样的人岂能进入殿里保全生命呢？我不进去！」","notes":[]},{"n":12,"t":"我看明神没有差遣他，是他自己说这话攻击我，是多比雅和参巴拉贿买了他。","notes":[]},{"n":13,"t":"贿买他的缘故，是要叫我惧怕，依从他犯罪，他们好传扬恶言毁谤我。","notes":[]},{"n":14,"t":"我的神啊，多比雅、参巴拉、女先知挪亚底，和其余的先知要叫我惧怕，求你记念他们所行的这些事。","notes":[]},{"n":15,"t":"以禄月二十五日，城墙修完了，共修了五十二天。","notes":[],"heads":["工程结束"]},{"n":16,"t":"我们一切仇敌、四围的外邦人听见了便惧怕，愁眉不展；因为见这工作完成是出乎我们的神。","notes":[]},{"n":17,"t":"在那些日子，犹大的贵胄屡次寄信与多比雅，多比雅也来信与他们。","notes":[]},{"n":18,"t":"在犹大有许多人与多比雅结盟；因他是亚拉的儿子，示迦尼的女婿，并且他的儿子约哈难娶了比利迦儿子米书兰的女儿为妻。","notes":[]},{"n":19,"t":"他们常在我面前说多比雅的善行，也将我的话传与他。多比雅又常寄信来，要叫我惧怕。","notes":[]}]},"7":{"heading":"被掳归回者的名单","verses":[{"n":1,"t":"城墙修完，我安了门扇，守门的、歌唱的，和利未人都已派定。","notes":[]},{"n":2,"t":"我就派我的弟兄哈拿尼和营楼的宰官哈拿尼雅管理耶路撒冷；因为哈拿尼雅是忠信的，又敬畏神过于众人。","notes":[]},{"n":3,"t":"我吩咐他们说：「等到太阳上升才可开耶路撒冷的城门；人尚看守的时候就要关门上闩；也当派耶路撒冷的居民各按班次看守自己房屋对面之处。」","notes":[]},{"n":4,"t":"城是广大，其中的民却稀少，房屋还没有建造。","notes":[]},{"n":5,"t":"我的神感动我心，招聚贵胄、官长，和百姓，要照家谱计算。我找着第一次上来之人的家谱，其上写着：","notes":[]},{"n":6,"t":"巴比伦王尼布甲尼撒从前掳去犹大省的人，现在他们的子孙从被掳到之地回耶路撒冷和犹大，各归本城。","notes":[]},{"n":7,"t":"他们是同着所罗巴伯、耶书亚、尼希米、亚撒利雅、拉米、拿哈玛尼、末底改、必珊、米斯毗列、比革瓦伊、尼宏、巴拿回来的。","notes":[]},{"n":8,"t":"以色列人民的数目记在下面：巴录的子孙二千一百七十二名；","notes":[]},{"n":9,"t":"示法提雅的子孙三百七十二名；","notes":[]},{"n":10,"t":"亚拉的子孙六百五十二名；","notes":[]},{"n":11,"t":"巴哈·摩押的后裔，就是耶书亚和约押的子孙二千八百一十八名；","notes":[]},{"n":12,"t":"以拦的子孙一千二百五十四名；","notes":[]},{"n":13,"t":"萨土的子孙八百四十五名；","notes":[]},{"n":14,"t":"萨改的子孙七百六十名；","notes":[]},{"n":15,"t":"宾内的子孙六百四十八名；","notes":[]},{"n":16,"t":"比拜的子孙六百二十八名；","notes":[]},{"n":17,"t":"押甲的子孙二千三百二十二名；","notes":[]},{"n":18,"t":"亚多尼干的子孙六百六十七名；","notes":[]},{"n":19,"t":"比革瓦伊的子孙二千零六十七名；","notes":[]},{"n":20,"t":"亚丁的子孙六百五十五名；","notes":[]},{"n":21,"t":"亚特的后裔，就是希西家的子孙九十八名；","notes":[]},{"n":22,"t":"哈顺的子孙三百二十八名；","notes":[]},{"n":23,"t":"比赛的子孙三百二十四名；","notes":[]},{"n":24,"t":"哈拉的子孙一百一十二名；","notes":[]},{"n":25,"t":"基遍人九十五名；","notes":[]},{"n":26,"t":"伯利恒人和尼陀法人共一百八十八名；","notes":[]},{"n":27,"t":"亚拿突人一百二十八名；","notes":[]},{"n":28,"t":"伯·亚斯玛弗人四十二名；","notes":[]},{"n":29,"t":"基列·耶琳人、基非拉人、比录人共七百四十三名；","notes":[]},{"n":30,"t":"拉玛人和迦巴人共六百二十一名；","notes":[]},{"n":31,"t":"默玛人一百二十二名；","notes":[]},{"n":32,"t":"伯特利人和艾人共一百二十三名；","notes":[]},{"n":33,"t":"别的尼波人五十二名；","notes":[]},{"n":34,"t":"别的以拦子孙一千二百五十四名；","notes":[]},{"n":35,"t":"哈琳的子孙三百二十名；","notes":[]},{"n":36,"t":"耶利哥人三百四十五名；","notes":[]},{"n":37,"t":"罗德人、哈第人、阿挪人共七百二十一名；","notes":[]},{"n":38,"t":"西拿人三千九百三十名。","notes":[]},{"n":39,"t":"祭司：耶书亚家，耶大雅的子孙九百七十三名；","notes":[]},{"n":40,"t":"音麦的子孙一千零五十二名；","notes":[]},{"n":41,"t":"巴施户珥的子孙一千二百四十七名；","notes":[]},{"n":42,"t":"哈琳的子孙一千零一十七名。","notes":[]},{"n":43,"t":"利未人：何达威的后裔，就是耶书亚和甲篾的子孙七十四名。","notes":[]},{"n":44,"t":"歌唱的：亚萨的子孙一百四十八名。","notes":[]},{"n":45,"t":"守门的：沙龙的子孙、亚特的子孙、达们的子孙、亚谷的子孙、哈底大的子孙、朔拜的子孙，共一百三十八名。","notes":[]},{"n":46,"t":"尼提宁：西哈的子孙、哈苏巴的子孙、答巴俄的子孙、","notes":["就是殿役"]},{"n":47,"t":"基绿的子孙、西亚的子孙、巴顿的子孙、","notes":[]},{"n":48,"t":"利巴拿的子孙、哈迦巴的子孙、萨买的子孙、","notes":[]},{"n":49,"t":"哈难的子孙、吉德的子孙、迦哈的子孙、","notes":[]},{"n":50,"t":"利亚雅的子孙、利汛的子孙、尼哥大的子孙、","notes":[]},{"n":51,"t":"迦散的子孙、乌撒的子孙、巴西亚的子孙、","notes":[]},{"n":52,"t":"比赛的子孙、米乌宁的子孙、尼普心的子孙、","notes":[]},{"n":53,"t":"巴卜的子孙、哈古巴的子孙、哈忽的子孙、","notes":[]},{"n":54,"t":"巴洗律的子孙、米希大的子孙、哈沙的子孙、","notes":[]},{"n":55,"t":"巴柯的子孙、西西拉的子孙、答玛的子孙、","notes":[]},{"n":56,"t":"尼细亚的子孙、哈提法的子孙。","notes":[]},{"n":57,"t":"所罗门仆人的后裔，就是琐太的子孙、琐斐列的子孙、比路大的子孙、","notes":[]},{"n":58,"t":"雅拉的子孙、达昆的子孙、吉德的子孙、","notes":[]},{"n":59,"t":"示法提雅的子孙、哈替的子孙、玻黑列·哈斯巴音的子孙、亚们的子孙。","notes":[]},{"n":60,"t":"尼提宁和所罗门仆人的后裔共三百九十二名。","notes":[]},{"n":61,"t":"从特米拉、特哈萨、基绿、亚顿、音麦上来的，不能指明他们的宗族谱系是以色列人不是；","notes":[]},{"n":62,"t":"他们是第莱雅的子孙、多比雅的子孙、尼哥大的子孙，共六百四十二名。","notes":[]},{"n":63,"t":"祭司中，哈巴雅的子孙、哈哥斯的子孙、巴西莱的子孙；因为他们的先祖娶了基列人巴西莱的女儿为妻，所以起名叫巴西莱。","notes":[]},{"n":64,"t":"这三家的人在族谱之中寻查自己的谱系，却寻不着，因此算为不洁，不准供祭司的职任。","notes":[]},{"n":65,"t":"省长对他们说：「不可吃至圣的物，直到有用乌陵和土明决疑的祭司兴起来。」","notes":[]},{"n":66,"t":"会众共有四万二千三百六十名。","notes":[]},{"n":67,"t":"此外，还有他们的仆婢七千三百三十七名，又有歌唱的男女二百四十五名。","notes":[]},{"n":68,"t":"他们有马七百三十六匹，骡子二百四十五匹，","notes":[]},{"n":69,"t":"骆驼四百三十五只，驴六千七百二十匹。","notes":[]},{"n":70,"t":"有些族长为工程捐助。省长捐入库中的金子一千达利克，碗五十个，祭司的礼服五百三十件。","notes":[]},{"n":71,"t":"又有族长捐入工程库的金子二万达利克，银子二千二百弥拿。","notes":[]},{"n":72,"t":"其余百姓所捐的金子二万达利克，银子二千弥拿，祭司的礼服六十七件。","notes":[]},{"n":73,"t":"于是祭司、利未人、守门的、歌唱的、民中的一些人、尼提宁，并以色列众人，各住在自己的城里。","notes":[]}]},"8":{"heading":"以斯拉向民众宣读律法书","verses":[{"n":1,"t":"到了七月，以色列人住在自己的城里。那时，他们如同一人聚集在水门前的宽阔处，请文士以斯拉将耶和华借摩西传给以色列人的律法书带来。","notes":[]},{"n":2,"t":"七月初一日，祭司以斯拉将律法书带到听了能明白的男女会众面前。","notes":[]},{"n":3,"t":"在水门前的宽阔处，从清早到晌午，在众男女、一切听了能明白的人面前读这律法书。众民侧耳而听。","notes":[]},{"n":4,"t":"文士以斯拉站在为这事特备的木台上。玛他提雅、示玛、亚奈雅、乌利亚、希勒家，和玛西雅站在他的右边；毗大雅、米沙利、玛基雅、哈顺、哈拔大拿、撒迦利亚，和米书兰站在他的左边。","notes":[]},{"n":5,"t":"以斯拉站在众民以上，在众民眼前展开这书。他一展开，众民就都站起来。","notes":[]},{"n":6,"t":"以斯拉称颂耶和华至大的神；众民都举手应声说：「阿们！阿们！」就低头，面伏于地，敬拜耶和华。","notes":[]},{"n":7,"t":"耶书亚、巴尼、示利比、雅悯、亚谷、沙比太、荷第雅、玛西雅、基利他、亚撒利雅、约撒拔、哈难、毗莱雅，和利未人使百姓明白律法；百姓都站在自己的地方。","notes":[]},{"n":8,"t":"他们清清楚楚地念神的律法书，讲明意思，使百姓明白所念的。","notes":[]},{"n":9,"t":"省长尼希米和作祭司的文士以斯拉，并教训百姓的利未人，对众民说：「今日是耶和华—你们神的圣日，不要悲哀哭泣。」这是因为众民听见律法书上的话都哭了；","notes":[]},{"n":10,"t":"又对他们说：「你们去吃肥美的，喝甘甜的，有不能预备的就分给他，因为今日是我们主的圣日。你们不要忧愁，因靠耶和华而得的喜乐是你们的力量。」","notes":[]},{"n":11,"t":"于是利未人使众民静默，说：「今日是圣日；不要作声，也不要忧愁。」","notes":[]},{"n":12,"t":"众民都去吃喝，也分给人，大大快乐，因为他们明白所教训他们的话。","notes":[]},{"n":13,"t":"次日，众民的族长、祭司，和利未人都聚集到文士以斯拉那里，要留心听律法上的话。","notes":[],"heads":["住棚节"]},{"n":14,"t":"他们见律法上写着，耶和华借摩西吩咐以色列人要在七月节住棚，","notes":[]},{"n":15,"t":"并要在各城和耶路撒冷宣传报告说：「你们当上山，将橄榄树、野橄榄树、番石榴树、棕树，和各样茂密树的枝子取来，照着所写的搭棚。」","notes":[]},{"n":16,"t":"于是百姓出去，取了树枝来，各人在自己的房顶上，或院内，或神殿的院内，或水门的宽阔处，或以法莲门的宽阔处搭棚。","notes":[]},{"n":17,"t":"从掳到之地归回的全会众就搭棚，住在棚里。从嫩的儿子约书亚的时候直到这日，以色列人没有这样行。于是众人大大喜乐。","notes":[]},{"n":18,"t":"从头一天直到末一天，以斯拉每日念神的律法书。众人守节七日，第八日照例有严肃会。","notes":[]}]},"9":{"heading":"以色列人承认他们的罪","verses":[{"n":1,"t":"这月二十四日，以色列人聚集禁食，身穿麻衣，头蒙灰尘。","notes":[]},{"n":2,"t":"以色列人就与一切外邦人离绝，站着承认自己的罪恶和列祖的罪孽。","notes":["人：原文是种类"]},{"n":3,"t":"那日的四分之一站在自己的地方念耶和华—他们神的律法书，又四分之一认罪，敬拜耶和华—他们的神。","notes":[]},{"n":4,"t":"耶书亚、巴尼、甲篾、示巴尼、布尼、示利比、巴尼、基拿尼站在利未人的台上，大声哀求耶和华—他们的神。","notes":[]},{"n":5,"t":"利未人耶书亚、甲篾、巴尼、哈沙尼、示利比、荷第雅、示巴尼、毗他希雅说：「你们要站起来称颂耶和华—你们的神，永世无尽。耶和华啊，你荣耀之名是应当称颂的！超乎一切称颂和赞美。」","notes":[]},{"n":6,"t":"「你，惟独你是耶和华！你造了天和天上的天，并天上的万象，地和地上的万物，海和海中所有的；这一切都是你所保存的。天军也都敬拜你。","notes":[],"heads":["认罪的祷告"]},{"n":7,"t":"你是耶和华神，曾拣选亚伯兰，领他出迦勒底的吾珥，给他改名叫亚伯拉罕。","notes":[]},{"n":8,"t":"你见他在你面前心里诚实，就与他立约，应许把迦南人、赫人、亚摩利人、比利洗人、耶布斯人、革迦撒人之地赐给他的后裔，且应验了你的话，因为你是公义的。","notes":[]},{"n":9,"t":"「你曾看见我们列祖在埃及所受的困苦，垂听他们在红海边的哀求，","notes":[]},{"n":10,"t":"就施行神迹奇事在法老和他一切臣仆，并他国中的众民身上。你也得了名声，正如今日一样，因为你知道他们向我们列祖行事狂傲。","notes":[]},{"n":11,"t":"你又在我们列祖面前把海分开，使他们在海中行走干地，将追赶他们的人抛在深海，如石头抛在大水中；","notes":[]},{"n":12,"t":"并且白昼用云柱引导他们，黑夜用火柱照亮他们当行的路。","notes":[]},{"n":13,"t":"你也降临在西奈山，从天上与他们说话，赐给他们正直的典章、真实的律法、美好的条例与诫命，","notes":[]},{"n":14,"t":"又使他们知道你的安息圣日，并借你仆人摩西传给他们诫命、条例、律法。","notes":[]},{"n":15,"t":"从天上赐下粮食充他们的饥，从磐石使水流出解他们的渴，又吩咐他们进去得你起誓应许赐给他们的地。","notes":[]},{"n":16,"t":"「但我们的列祖行事狂傲，硬着颈项不听从你的诫命；","notes":[]},{"n":17,"t":"不肯顺从，也不记念你在他们中间所行的奇事，竟硬着颈项，居心背逆，自立首领，要回他们为奴之地。但你是乐意饶恕人，有恩典，有怜悯，不轻易发怒，有丰盛慈爱的神，并不丢弃他们。","notes":[]},{"n":18,"t":"他们虽然铸了一只牛犊，彼此说『这是领你出埃及的神』，因而大大惹动你的怒气；","notes":[]},{"n":19,"t":"你还是大施怜悯，在旷野不丢弃他们。白昼，云柱不离开他们，仍引导他们行路；黑夜，火柱也不离开他们，仍照亮他们当行的路。","notes":[]},{"n":20,"t":"你也赐下你良善的灵教训他们；未尝不赐吗哪使他们糊口，并赐水解他们的渴。","notes":[]},{"n":21,"t":"在旷野四十年，你养育他们，他们就一无所缺：衣服没有穿破，脚也没有肿。","notes":[]},{"n":22,"t":"并且你将列国之地照分赐给他们，他们就得了西宏之地、希实本王之地，和巴珊王噩之地。","notes":[]},{"n":23,"t":"你也使他们的子孙多如天上的星，带他们到你所应许他们列祖进入得为业之地。","notes":[]},{"n":24,"t":"这样，他们进去得了那地，你在他们面前制伏那地的居民，就是迦南人；将迦南人和其君王，并那地的居民，都交在他们手里，让他们任意而待。","notes":[]},{"n":25,"t":"他们得了坚固的城邑、肥美的地土、充满各样美物的房屋、凿成的水井、葡萄园、橄榄园，并许多果木树。他们就吃而得饱，身体肥胖，因你的大恩，心中快乐。","notes":[]},{"n":26,"t":"「然而，他们不顺从，竟背叛你，将你的律法丢在背后，杀害那劝他们归向你的众先知，大大惹动你的怒气。","notes":[]},{"n":27,"t":"所以你将他们交在敌人的手中，磨难他们。他们遭难的时候哀求你，你就从天上垂听，照你的大怜悯赐给他们拯救者，救他们脱离敌人的手。","notes":[]},{"n":28,"t":"但他们得平安之后，又在你面前行恶，所以你丢弃他们在仇敌的手中，使仇敌辖制他们。然而他们转回哀求你，你仍从天上垂听，屡次照你的怜悯拯救他们，","notes":[]},{"n":29,"t":"又警戒他们，要使他们归服你的律法。他们却行事狂傲，不听从你的诫命，干犯你的典章（人若遵行就必因此活着），扭转肩头，硬着颈项，不肯听从。","notes":[]},{"n":30,"t":"但你多年宽容他们，又用你的灵借众先知劝戒他们，他们仍不听从，所以你将他们交在列国之民的手中。","notes":[]},{"n":31,"t":"然而你大发怜悯，不全然灭绝他们，也不丢弃他们；因为你是有恩典、有怜悯的神。","notes":[]},{"n":32,"t":"「我们的神啊，你是至大、至能、至可畏、守约施慈爱的神。我们的君王、首领、祭司、先知、列祖，和你的众民，从亚述列王的时候直到今日所遭遇的苦难，现在求你不要以为小。","notes":[]},{"n":33,"t":"在一切临到我们的事上，你却是公义的；因你所行的是诚实，我们所做的是邪恶。","notes":[]},{"n":34,"t":"我们的君王、首领、祭司、列祖都不遵守你的律法，不听从你的诫命和你警戒他们的话。","notes":[]},{"n":35,"t":"他们在本国里沾你大恩的时候，在你所赐给他们这广大肥美之地上不事奉你，也不转离他们的恶行。","notes":[]},{"n":36,"t":"我们现今作了奴仆；至于你所赐给我们列祖享受其上的土产，并美物之地，看哪，我们在这地上作了奴仆！","notes":[]},{"n":37,"t":"这地许多出产归了列王，就是你因我们的罪所派辖制我们的。他们任意辖制我们的身体和牲畜，我们遭了大难。」","notes":[]},{"n":38,"t":"因这一切的事，我们立确实的约，写在册上。我们的首领、利未人，和祭司都签了名。","notes":[]}]},"10":{"heading":"在公约上签名的人","verses":[{"n":1,"t":"签名的是：哈迦利亚的儿子—省长尼希米，和西底家；","notes":[]},{"n":2,"t":"祭司：西莱雅、亚撒利雅、耶利米、","notes":[]},{"n":3,"t":"巴施户珥、亚玛利雅、玛基雅、","notes":[]},{"n":4,"t":"哈突、示巴尼、玛鹿、","notes":[]},{"n":5,"t":"哈琳、米利末、俄巴底亚、","notes":[]},{"n":6,"t":"但以理、近顿、巴录、","notes":[]},{"n":7,"t":"米书兰、亚比雅、米雅民、","notes":[]},{"n":8,"t":"玛西亚、璧该、示玛雅；","notes":[]},{"n":9,"t":"又有利未人，就是亚散尼的儿子耶书亚、希拿达的子孙宾内、甲篾；","notes":[]},{"n":10,"t":"还有他们的弟兄示巴尼、荷第雅、基利他、毗莱雅、哈难、","notes":[]},{"n":11,"t":"米迦、利合、哈沙比雅、","notes":[]},{"n":12,"t":"撒刻、示利比、示巴尼、","notes":[]},{"n":13,"t":"荷第雅、巴尼、比尼努；","notes":[]},{"n":14,"t":"又有民的首领，就是巴录、巴哈·摩押、以拦、萨土、巴尼、","notes":[]},{"n":15,"t":"布尼、押甲、比拜、","notes":[]},{"n":16,"t":"亚多尼雅、比革瓦伊、亚丁、","notes":[]},{"n":17,"t":"亚特、希西家、押朔、","notes":[]},{"n":18,"t":"荷第雅、哈顺、比赛、","notes":[]},{"n":19,"t":"哈拉、亚拿突、尼拜、","notes":[]},{"n":20,"t":"抹比押、米书兰、希悉、","notes":[]},{"n":21,"t":"米示萨别、撒督、押杜亚、","notes":[]},{"n":22,"t":"毗拉提、哈难、亚奈雅、","notes":[]},{"n":23,"t":"何细亚、哈拿尼雅、哈述、","notes":[]},{"n":24,"t":"哈罗黑、毗利哈、朔百、","notes":[]},{"n":25,"t":"利宏、哈沙拿、玛西雅、","notes":[]},{"n":26,"t":"亚希雅、哈难、亚难、","notes":[]},{"n":27,"t":"玛鹿、哈琳、巴拿。","notes":[]},{"n":28,"t":"其余的民、祭司、利未人、守门的、歌唱的、尼提宁，和一切离绝邻邦居民归服神律法的，并他们的妻子、儿女，凡有知识能明白的，","notes":[],"heads":["公约的内容"]},{"n":29,"t":"都随从他们贵胄的弟兄，发咒起誓，必遵行神借他仆人摩西所传的律法，谨守遵行耶和华—我们主的一切诫命、典章、律例；","notes":[]},{"n":30,"t":"并不将我们的女儿嫁给这地的居民，也不为我们的儿子娶他们的女儿。","notes":[]},{"n":31,"t":"这地的居民若在安息日，或什么圣日，带了货物或粮食来卖给我们，我们必不买。每逢第七年必不耕种，凡欠我们债的必不追讨。","notes":[]},{"n":32,"t":"我们又为自己定例，每年各人捐银一舍客勒三分之一，为我们神殿的使用，","notes":[]},{"n":33,"t":"就是为陈设饼、常献的素祭，和燔祭，安息日、月朔、节期所献的与圣物，并以色列人的赎罪祭，以及我们神殿里一切的费用。","notes":[]},{"n":34,"t":"我们的祭司、利未人，和百姓都掣签，看每年是哪一族按定期将献祭的柴奉到我们神的殿里，照着律法上所写的，烧在耶和华—我们神的坛上。","notes":[]},{"n":35,"t":"又定每年将我们地上初熟的土产和各样树上初熟的果子都奉到耶和华的殿里。","notes":[]},{"n":36,"t":"又照律法上所写的，将我们头胎的儿子和首生的牛羊都奉到我们神的殿，交给我们神殿里供职的祭司；","notes":[]},{"n":37,"t":"并将初熟之麦子所磨的面和举祭、各样树上初熟的果子、新酒与油奉给祭司，收在我们神殿的库房里，把我们地上所产的十分之一奉给利未人，因利未人在我们一切城邑的土产中当取十分之一。","notes":[]},{"n":38,"t":"利未人取十分之一的时候，亚伦的子孙中，当有一个祭司与利未人同在。利未人也当从十分之一中取十分之一，奉到我们神殿的屋子里，收在库房中。","notes":[]},{"n":39,"t":"以色列人和利未人要将五谷、新酒，和油为举祭，奉到收存圣所器皿的屋子里，就是供职的祭司、守门的、歌唱的所住的屋子。这样，我们就不离弃我们神的殿。","notes":[]}]},"11":{"heading":"住在耶路撒冷的人","verses":[{"n":1,"t":"百姓的首领住在耶路撒冷。其余的百姓掣签，每十人中使一人来住在圣城耶路撒冷，那九人住在别的城邑。","notes":[]},{"n":2,"t":"凡甘心乐意住在耶路撒冷的，百姓都为他们祝福。","notes":[]},{"n":3,"t":"以色列人、祭司、利未人、尼提宁，和所罗门仆人的后裔都住在犹大城邑，各在自己的地业中。本省的首领住在耶路撒冷的记在下面：","notes":[]},{"n":4,"t":"其中有些犹大人和便雅悯人。犹大人中有法勒斯的子孙、乌西雅的儿子亚他雅。乌西雅是撒迦利雅的儿子；撒迦利雅是亚玛利雅的儿子；亚玛利雅是示法提雅的儿子；示法提雅是玛勒列的儿子。","notes":[]},{"n":5,"t":"又有巴录的儿子玛西雅。巴录是谷何西的儿子；谷何西是哈赛雅的儿子；哈赛雅是亚大雅的儿子；亚大雅是约雅立的儿子；约雅立是撒迦利雅的儿子；撒迦利雅是示罗尼的儿子。","notes":[]},{"n":6,"t":"住在耶路撒冷、法勒斯的子孙共四百六十八名，都是勇士。","notes":[]},{"n":7,"t":"便雅悯人中有米书兰的儿子撒路。米书兰是约叶的儿子；约叶是毗大雅的儿子；毗大雅是哥赖雅的儿子；哥赖雅是玛西雅的儿子；玛西雅是以铁的儿子；以铁是耶筛亚的儿子。","notes":[]},{"n":8,"t":"其次有迦拜、撒来的子孙，共九百二十八名。","notes":[]},{"n":9,"t":"细基利的儿子约珥是他们的长官。哈西努亚的儿子犹大是耶路撒冷的副官。","notes":[]},{"n":10,"t":"祭司中有雅斤，又有约雅立的儿子耶大雅；","notes":[]},{"n":11,"t":"还有管理神殿的西莱雅。西莱雅是希勒家的儿子；希勒家是米书兰的儿子；米书兰是撒督的儿子；撒督是米拉约的儿子；米拉约是亚希突的儿子。","notes":[]},{"n":12,"t":"还有他们的弟兄在殿里供职的，共八百二十二名；又有耶罗罕的儿子亚大雅。耶罗罕是毗拉利的儿子；毗拉利是暗洗的儿子；暗洗是撒迦利亚的儿子；撒迦利亚是巴施户珥的儿子；巴施户珥是玛基雅的儿子。","notes":[]},{"n":13,"t":"还有他的弟兄作族长的，二百四十二名；又有亚萨列的儿子亚玛帅。亚萨列是亚哈赛的儿子；亚哈赛是米实利末的儿子；米实利末是音麦的儿子。","notes":[]},{"n":14,"t":"还有他们弟兄、大能的勇士共一百二十八名。哈基多琳的儿子撒巴第业是他们的长官。","notes":[]},{"n":15,"t":"利未人中有哈述的儿子示玛雅。哈述是押利甘的儿子；押利甘是哈沙比雅的儿子；哈沙比雅是布尼的儿子。","notes":[]},{"n":16,"t":"又有利未人的族长沙比太和约撒拔管理神殿的外事。","notes":[]},{"n":17,"t":"祈祷的时候，为称谢领首的是米迦的儿子玛他尼。米迦是撒底的儿子；撒底是亚萨的儿子；又有玛他尼弟兄中的八布迦为副。还有沙母亚的儿子押大。沙母亚是加拉的儿子；加拉是耶杜顿的儿子。","notes":[]},{"n":18,"t":"在圣城的利未人共二百八十四名。","notes":[]},{"n":19,"t":"守门的是亚谷和达们，并守门的弟兄，共一百七十二名。","notes":[]},{"n":20,"t":"其余的以色列人、祭司、利未人都住在犹大的一切城邑，各在自己的地业中。","notes":[]},{"n":21,"t":"尼提宁却住在俄斐勒；西哈和基斯帕管理他们。","notes":[]},{"n":22,"t":"在耶路撒冷、利未人的长官，管理神殿事务的是歌唱者亚萨的子孙、巴尼的儿子乌西。巴尼是哈沙比雅的儿子；哈沙比雅是玛他尼的儿子；玛他尼是米迦的儿子。","notes":[]},{"n":23,"t":"王为歌唱的出命令，每日供给他们必有一定之粮。","notes":[]},{"n":24,"t":"犹大儿子谢拉的子孙、米示萨别的儿子毗他希雅辅助王办理犹大民的事。","notes":[]},{"n":25,"t":"至于村庄和属村庄的田地，有犹大人住在基列·亚巴和属基列·亚巴的乡村；底本和属底本的乡村；叶甲薛和属叶甲薛的村庄；","notes":[],"heads":["居住其他城镇的人"]},{"n":26,"t":"耶书亚、摩拉大、伯·帕列、","notes":[]},{"n":27,"t":"哈萨·书亚、别是巴，和属别是巴的乡村；","notes":[]},{"n":28,"t":"洗革拉、米哥拿，和属米哥拿的乡村；","notes":[]},{"n":29,"t":"音·临门、琐拉、耶末、","notes":[]},{"n":30,"t":"撒挪亚、亚杜兰，和属这两处的村庄；拉吉和属拉吉的田地；亚西加和属亚西加的乡村。他们所住的地方是从别是巴直到欣嫩谷。","notes":[]},{"n":31,"t":"便雅悯人从迦巴起，住在密抹、亚雅、伯特利和属伯特利的乡村。","notes":[]},{"n":32,"t":"亚拿突、挪伯、亚难雅、","notes":[]},{"n":33,"t":"夏琐、拉玛、基他音、","notes":[]},{"n":34,"t":"哈叠、洗编、尼八拉、","notes":[]},{"n":35,"t":"罗德、阿挪、匠人之谷。","notes":[]},{"n":36,"t":"利未人中有几班曾住在犹大地归于便雅悯的。","notes":[]}]},"12":{"heading":"祭司和利未人的名单","verses":[{"n":1,"t":"同着撒拉铁的儿子所罗巴伯和耶书亚回来的祭司与利未人记在下面：祭司是西莱雅、耶利米、以斯拉、","notes":[]},{"n":2,"t":"亚玛利雅、玛鹿、哈突、","notes":[]},{"n":3,"t":"示迦尼、利宏、米利末、","notes":[]},{"n":4,"t":"易多、近顿、亚比雅、","notes":[]},{"n":5,"t":"米雅民、玛底雅、璧迦、","notes":[]},{"n":6,"t":"示玛雅、约雅立、耶大雅、","notes":[]},{"n":7,"t":"撒路、亚木、希勒家、耶大雅。这些人在耶书亚的时候作祭司和他们弟兄的首领。","notes":[]},{"n":8,"t":"利未人是耶书亚、宾内、甲篾、示利比、犹大、玛他尼。这玛他尼和他的弟兄管理称谢的事。","notes":[]},{"n":9,"t":"他们的弟兄八布迦和乌尼照自己的班次与他们相对。","notes":[]},{"n":10,"t":"耶书亚生约雅金；约雅金生以利亚实；以利亚实生耶何耶大；","notes":[],"heads":["大祭司耶书亚的后代"]},{"n":11,"t":"耶何耶大生约拿单；约拿单生押杜亚。","notes":[]},{"n":12,"t":"在约雅金的时候，祭司作族长的西莱雅族有米拉雅；耶利米族有哈拿尼雅；","notes":["或译：班；本段同"],"heads":["作族长的祭司"]},{"n":13,"t":"以斯拉族有米书兰；亚玛利雅族有约哈难；","notes":[]},{"n":14,"t":"米利古族有约拿单；示巴尼族有约瑟；","notes":[]},{"n":15,"t":"哈琳族有押拿；米拉约族有希勒恺；","notes":[]},{"n":16,"t":"易多族有撒迦利亚；近顿族有米书兰；","notes":[]},{"n":17,"t":"亚比雅族有细基利；米拿民族某；摩亚底族有毗勒太；","notes":[]},{"n":18,"t":"璧迦族有沙母亚；示玛雅族有约拿单；","notes":[]},{"n":19,"t":"约雅立族有玛特乃；耶大雅族有乌西；","notes":[]},{"n":20,"t":"撒来族有加莱；亚木族有希伯；","notes":[]},{"n":21,"t":"希勒家族有哈沙比雅；耶大雅族有拿坦业。","notes":[]},{"n":22,"t":"至于利未人，当以利亚实、耶何耶大、约哈难、押杜亚的时候，他们的族长记在册上。波斯王大流士在位的时候，作族长的祭司也记在册上。","notes":[],"heads":["祭司和利未家族的记录"]},{"n":23,"t":"利未人作族长的记在历史上，直到以利亚实的儿子约哈难的时候。","notes":[]},{"n":24,"t":"利未人的族长是哈沙比雅、示利比、甲篾的儿子耶书亚，与他们弟兄的班次相对，照着神人大卫的命令一班一班地赞美称谢。","notes":[],"heads":["圣殿供职的班次"]},{"n":25,"t":"玛他尼、八布迦、俄巴底亚、米书兰、达们、亚谷是守门的，就是在库房那里守门。","notes":[]},{"n":26,"t":"这都是在约撒达的孙子、耶书亚的儿子约雅金和省长尼希米，并祭司文士以斯拉的时候，有职任的。","notes":[]},{"n":27,"t":"耶路撒冷城墙告成的时候，众民就把各处的利未人招到耶路撒冷，要称谢、歌唱、敲钹、鼓瑟、弹琴，欢欢喜喜地行告成之礼。","notes":[],"heads":["城墙落成时尼希米行奉献之礼"]},{"n":28,"t":"歌唱的人从耶路撒冷的周围和尼陀法的村庄与伯·吉甲，又从迦巴和押玛弗的田地聚集，因为歌唱的人在耶路撒冷四围为自己立了村庄。","notes":[],"end":29},{"n":30,"t":"祭司和利未人就洁净自己，也洁净百姓和城门，并城墙。","notes":[]},{"n":31,"t":"我带犹大的首领上城，使称谢的人分为两大队，排列而行：第一队在城上往右边向粪厂门行走，","notes":[]},{"n":32,"t":"在他们后头的有何沙雅与犹大首领的一半，","notes":[]},{"n":33,"t":"又有亚撒利雅、以斯拉、米书兰、","notes":[]},{"n":34,"t":"犹大、便雅悯、示玛雅、耶利米。","notes":[]},{"n":35,"t":"还有些吹号之祭司的子孙，约拿单的儿子撒迦利亚。约拿单是示玛雅的儿子；示玛雅是玛他尼的儿子；玛他尼是米该亚的儿子；米该亚是撒刻的儿子；撒刻是亚萨的儿子；","notes":[]},{"n":36,"t":"又有撒迦利亚的弟兄示玛雅、亚撒利、米拉莱、基拉莱、玛艾、拿坦业、犹大、哈拿尼，都拿着神人大卫的乐器，文士以斯拉引领他们。","notes":[]},{"n":37,"t":"他们经过泉门往前，从大卫城的台阶随地势而上，在大卫宫殿以上，直行到朝东的水门。","notes":[]},{"n":38,"t":"第二队称谢的人要与那一队相迎而行。我和民的一半跟随他们，在城墙上过了炉楼，直到宽墙；","notes":[]},{"n":39,"t":"又过了以法莲门、古门、鱼门、哈楠业楼、哈米亚楼，直到羊门，就在护卫门站住。","notes":[]},{"n":40,"t":"于是，这两队称谢的人连我和官长的一半，站在神的殿里。","notes":[]},{"n":41,"t":"还有祭司以利亚金、玛西雅、米拿民、米该雅、以利约乃、撒迦利亚、哈楠尼亚吹号；","notes":[]},{"n":42,"t":"又有玛西雅、示玛雅、以利亚撒、乌西、约哈难、玛基雅、以拦，和以谢奏乐。歌唱的就大声歌唱，伊斯拉希雅管理他们。","notes":[]},{"n":43,"t":"那日，众人献大祭而欢乐；因为神使他们大大欢乐，连妇女带孩童也都欢乐，甚至耶路撒冷中的欢声听到远处。","notes":[]},{"n":44,"t":"当日，派人管理库房，将举祭、初熟之物和所取的十分之一，就是按各城田地，照律法所定归给祭司和利未人的分，都收在里头。犹大人因祭司和利未人供职，就欢乐了。","notes":[],"heads":["圣殿的各种职责"]},{"n":45,"t":"祭司利未人遵守神所吩咐的，并守洁净的礼。歌唱的、守门的，照着大卫和他儿子所罗门的命令也如此行。","notes":[]},{"n":46,"t":"古时，在大卫和亚萨的日子，有歌唱的伶长，并有赞美称谢神的诗歌。","notes":[]},{"n":47,"t":"当所罗巴伯和尼希米的时候，以色列众人将歌唱的、守门的，每日所当得的分供给他们，又给利未人当得的分；利未人又给亚伦的子孙当得的分。","notes":[]}]},"13":{"heading":"与外邦人隔离","verses":[{"n":1,"t":"当日，人念摩西的律法书给百姓听，遇见书上写着说，亚扪人和摩押人永不可入神的会；","notes":[]},{"n":2,"t":"因为他们没有拿食物和水来迎接以色列人，且雇了巴兰咒诅他们，但我们的神使那咒诅变为祝福。","notes":[]},{"n":3,"t":"以色列民听见这律法，就与一切闲杂人绝交。","notes":[]},{"n":4,"t":"先是蒙派管理我们神殿中库房的祭司以利亚实与多比雅结亲，","notes":[],"heads":["尼希米的改革"]},{"n":5,"t":"便为他预备一间大屋子，就是从前收存素祭、乳香、器皿，和照命令供给利未人、歌唱的、守门的五谷、新酒，和油的十分之一，并归祭司举祭的屋子。","notes":[]},{"n":6,"t":"那时我不在耶路撒冷；因为巴比伦王亚达薛西三十二年，我回到王那里。过了多日，我向王告假。","notes":[]},{"n":7,"t":"我来到耶路撒冷，就知道以利亚实为多比雅在神殿的院内预备屋子的那件恶事。","notes":[]},{"n":8,"t":"我甚恼怒，就把多比雅的一切家具从屋里都抛出去，","notes":[]},{"n":9,"t":"吩咐人洁净这屋子，遂将神殿的器皿和素祭、乳香又搬进去。","notes":[]},{"n":10,"t":"我见利未人所当得的分无人供给他们，甚至供职的利未人与歌唱的俱各奔回自己的田地去了。","notes":[]},{"n":11,"t":"我就斥责官长说：「为何离弃神的殿呢？」我便招聚利未人，使他们照旧供职。","notes":[]},{"n":12,"t":"犹大众人就把五谷、新酒，和油的十分之一送入库房。","notes":[]},{"n":13,"t":"我派祭司示利米雅、文士撒督，和利未人毗大雅作库官管理库房；副官是哈难。哈难是撒刻的儿子；撒刻是玛他尼的儿子。这些人都是忠信的，他们的职分是将所供给的分给他们的弟兄。","notes":[]},{"n":14,"t":"我的神啊，求你因这事记念我，不要涂抹我为神的殿与其中的礼节所行的善。","notes":[]},{"n":15,"t":"那些日子，我在犹大见有人在安息日榨酒，搬运禾捆驮在驴上，又把酒、葡萄、无花果，和各样的担子在安息日担入耶路撒冷，我就在他们卖食物的那日警戒他们。","notes":["原文是踹酒榨"]},{"n":16,"t":"又有泰尔人住在耶路撒冷；他们把鱼和各样货物运进来，在安息日卖给犹大人。","notes":[]},{"n":17,"t":"我就斥责犹大的贵胄说：「你们怎么行这恶事犯了安息日呢？","notes":[]},{"n":18,"t":"从前你们列祖岂不是这样行，以致我们神使一切灾祸临到我们和这城吗？现在你们还犯安息日，使忿怒越发临到以色列！」","notes":[]},{"n":19,"t":"在安息日的前一日，耶路撒冷城门有黑影的时候，我就吩咐人将门关锁，不过安息日不准开放。我又派我几个仆人管理城门，免得有人在安息日担什么担子进城。","notes":[]},{"n":20,"t":"于是商人和贩卖各样货物的，一两次住宿在耶路撒冷城外。","notes":[]},{"n":21,"t":"我就警戒他们说：「你们为何在城外住宿呢？若再这样，我必下手拿办你们。」从此以后，他们在安息日不再来了。","notes":[]},{"n":22,"t":"我吩咐利未人洁净自己，来守城门，使安息日为圣。我的神啊，求你因这事记念我，照你的大慈爱怜恤我。","notes":[]},{"n":23,"t":"那些日子，我也见犹大人娶了亚实突、亚扪、摩押的女子为妻。","notes":[]},{"n":24,"t":"他们的儿女说话，一半是亚实突的话，不会说犹大的话，所说的是照着各族的方言。","notes":[]},{"n":25,"t":"我就斥责他们，咒诅他们，打了他们几个人，拔下他们的头发，叫他们指着神起誓，必不将自己的女儿嫁给外邦人的儿子，也不为自己和儿子娶他们的女儿。","notes":[]},{"n":26,"t":"我又说：「以色列王所罗门不是在这样的事上犯罪吗？在多国中并没有一王像他，且蒙他神所爱，神立他作以色列全国的王；然而连他也被外邦女子引诱犯罪。","notes":[]},{"n":27,"t":"如此，我岂听你们行这大恶，娶外邦女子干犯我们的神呢？」","notes":[]},{"n":28,"t":"大祭司以利亚实的孙子、耶何耶大的一个儿子是和伦人参巴拉的女婿，我就从我这里把他赶出去。","notes":[]},{"n":29,"t":"我的神啊，求你记念他们的罪；因为他们玷污了祭司的职任，违背你与祭司利未人所立的约。","notes":[]},{"n":30,"t":"这样，我洁净他们，使他们离绝一切外邦人，派定祭司和利未人的班次，使他们各尽其职。","notes":[]},{"n":31,"t":"我又派百姓按定期献柴和初熟的土产。我的神啊，求你记念我，施恩与我。","notes":[]}]}},"EST":{"1":{"heading":"亚哈随鲁王废瓦实提王后","verses":[{"n":1,"t":"亚哈随鲁作王，从印度直到古实，统管一百二十七省。","notes":[]},{"n":2,"t":"亚哈随鲁王在书珊城的宫登基；","notes":[]},{"n":3,"t":"在位第三年，为他一切首领臣仆设摆筵席，有波斯和米底亚的权贵，就是各省的贵胄与首领，在他面前。","notes":[]},{"n":4,"t":"他把他荣耀之国的丰富和他美好威严的尊贵给他们看了许多日，就是一百八十日。","notes":[]},{"n":5,"t":"这日子满了，又为所有住书珊城的大小人民在御园的院子里设摆筵席七日。","notes":[]},{"n":6,"t":"有白色、绿色、蓝色的帐子，用细麻绳、紫色绳从银环内系在白玉石柱上；有金银的床榻摆在红、白、黄、黑玉石的铺石地上。","notes":[]},{"n":7,"t":"用金器皿赐酒，器皿各有不同。御酒甚多，足显王的厚意。","notes":[]},{"n":8,"t":"喝酒有例，不准勉强人，因王吩咐宫里的一切臣宰，让人各随己意。","notes":[]},{"n":9,"t":"王后瓦实提在亚哈随鲁王的宫内也为妇女设摆筵席。","notes":[]},{"n":10,"t":"第七日，亚哈随鲁王饮酒，心中快乐，就吩咐在他面前侍立的七个太监米户幔、比斯他、哈波拿、比革他、亚拔他、西达、甲迦，","notes":[]},{"n":11,"t":"请王后瓦实提头戴王后的冠冕到王面前，使各等臣民看她的美貌，因为她容貌甚美。","notes":[]},{"n":12,"t":"王后瓦实提却不肯遵太监所传的王命而来，所以王甚发怒，心如火烧。","notes":[]},{"n":13,"t":"那时，在王左右常见王面、国中坐高位的，有波斯和米底亚的七个大臣，就是甲示拿、示达、押玛他、他施斯、米力、玛西拿、米母干，都是达时务的明哲人。按王的常规，办事必先询问知例明法的人。王问他们说：","notes":[],"end":14},{"n":15,"t":"「王后瓦实提不遵太监所传的王命，照例应当怎样办理呢？」","notes":[]},{"n":16,"t":"米母干在王和众首领面前回答说：「王后瓦实提这事，不但得罪王，并且有害于王各省的臣民；","notes":[]},{"n":17,"t":"因为王后这事必传到众妇人的耳中，说：『亚哈随鲁王吩咐王后瓦实提到王面前，她却不来』，她们就藐视自己的丈夫。","notes":[]},{"n":18,"t":"今日波斯和米底亚的众夫人听见王后这事，必向王的大臣照样行；从此必大开藐视和忿怒之端。","notes":[]},{"n":19,"t":"王若以为美，就降旨写在波斯和米底亚人的例中，永不更改，不准瓦实提再到王面前，将她王后的位分赐给比她还好的人。","notes":[]},{"n":20,"t":"所降的旨意传遍通国（国度本来广大），所有的妇人，无论丈夫贵贱都必尊敬他。」","notes":[]},{"n":21,"t":"王和众首领都以米母干的话为美，王就照这话去行，","notes":[]},{"n":22,"t":"发诏书，用各省的文字、各族的方言通知各省，使为丈夫的在家中作主，各说本地的方言。","notes":[]}]},"2":{"heading":"以斯帖被立为王后","verses":[{"n":1,"t":"这事以后，亚哈随鲁王的忿怒止息，就想念瓦实提和她所行的，并怎样降旨办她。","notes":[]},{"n":2,"t":"于是王的侍臣对王说：「不如为王寻找美貌的处女。","notes":[]},{"n":3,"t":"王可以派官在国中的各省招聚美貌的处女到书珊城的女院，交给掌管女子的太监希该，给她们当用的香品。","notes":["或译：宫"]},{"n":4,"t":"王所喜爱的女子可以立为王后，代替瓦实提。」王以这事为美，就如此行。","notes":[]},{"n":5,"t":"书珊城有一个犹大人，名叫末底改，是便雅悯人基士的曾孙，示每的孙子，睚珥的儿子。","notes":[]},{"n":6,"t":"从前巴比伦王尼布甲尼撒将犹大王耶哥尼雅和百姓从耶路撒冷掳去，末底改也在其内。","notes":["又名约雅斤"]},{"n":7,"t":"末底改抚养他叔叔的女儿哈大沙（后名以斯帖），因为她没有父母。这女子又容貌俊美；她父母死了，末底改就收她为自己的女儿。","notes":[]},{"n":8,"t":"王的谕旨传出，就招聚许多女子到书珊城，交给掌管女子的希该；以斯帖也送入王宫，交付希该。","notes":[]},{"n":9,"t":"希该喜悦以斯帖，就恩待她，急忙给她需用的香品和她所当得的分，又派所当得的七个宫女服事她，使她和她的宫女搬入女院上好的房屋。","notes":[]},{"n":10,"t":"以斯帖未曾将籍贯宗族告诉人，因为末底改嘱咐她不可叫人知道。","notes":[]},{"n":11,"t":"末底改天天在女院前边行走，要知道以斯帖平安不平安，并后事如何。","notes":[]},{"n":12,"t":"众女子照例先洁净身体十二个月：六个月用没药油，六个月用香料和洁身之物。满了日期，然后挨次进去见亚哈随鲁王。","notes":[]},{"n":13,"t":"女子进去见王是这样：从女院到王宫的时候，凡她所要的都必给她。","notes":[]},{"n":14,"t":"晚上进去，次日回到女子第二院，交给掌管妃嫔的太监沙甲；除非王喜爱她，再提名召她，就不再进去见王。","notes":[]},{"n":15,"t":"末底改叔叔亚比孩的女儿，就是末底改收为自己女儿的以斯帖，按次序当进去见王的时候，除了掌管女子的太监希该所派定给她的，她别无所求。凡看见以斯帖的都喜悦她。","notes":[]},{"n":16,"t":"亚哈随鲁王第七年十月，就是提别月，以斯帖被引入宫见王。","notes":[]},{"n":17,"t":"王爱以斯帖过于爱众女，她在王眼前蒙宠爱比众处女更甚。王就把王后的冠冕戴在她头上，立她为王后，代替瓦实提。","notes":[]},{"n":18,"t":"王因以斯帖的缘故给众首领和臣仆设摆大筵席，又豁免各省的租税，并照王的厚意大颁赏赐。","notes":[]},{"n":19,"t":"第二次招聚处女的时候，末底改坐在朝门。","notes":[],"heads":["末底改救王的命"]},{"n":20,"t":"以斯帖照着末底改所嘱咐的，还没有将籍贯宗族告诉人；因为以斯帖遵末底改的命，如抚养她的时候一样。","notes":[]},{"n":21,"t":"当那时候，末底改坐在朝门，王的太监中有两个守门的，辟探和提列，恼恨亚哈随鲁王，想要下手害他。","notes":[]},{"n":22,"t":"末底改知道了，就告诉王后以斯帖。以斯帖奉末底改的名，报告于王；","notes":[]},{"n":23,"t":"究察这事，果然是实，就把二人挂在木头上，将这事在王面前写于历史上。","notes":[]}]},"3":{"heading":"哈曼阴谋除灭犹大人","verses":[{"n":1,"t":"这事以后，亚哈随鲁王抬举亚甲族哈米大他的儿子哈曼，使他高升，叫他的爵位超过与他同事的一切臣宰。","notes":[]},{"n":2,"t":"在朝门的一切臣仆都跪拜哈曼，因为王如此吩咐；惟独末底改不跪不拜。","notes":[]},{"n":3,"t":"在朝门的臣仆问末底改说：「你为何违背王的命令呢？」","notes":[]},{"n":4,"t":"他们天天劝他，他还是不听，他们就告诉哈曼，要看末底改的事站得住站不住，因他已经告诉他们自己是犹大人。","notes":[]},{"n":5,"t":"哈曼见末底改不跪不拜，他就怒气填胸。","notes":[]},{"n":6,"t":"他们已将末底改的本族告诉哈曼；他以为下手害末底改一人是小事，就要灭绝亚哈随鲁王通国所有的犹大人，就是末底改的本族。","notes":[]},{"n":7,"t":"亚哈随鲁王十二年正月，就是尼散月，人在哈曼面前，按日日月月掣普珥，就是掣签，要定何月何日为吉，择定了十二月，就是亚达月。","notes":[]},{"n":8,"t":"哈曼对亚哈随鲁王说：「有一种民散居在王国各省的民中；他们的律例与万民的律例不同，也不守王的律例，所以容留他们与王无益。","notes":[]},{"n":9,"t":"王若以为美，请下旨意灭绝他们；我就捐一万他连得银子交给掌管国帑的人，纳入王的府库。」","notes":[]},{"n":10,"t":"于是王从自己手上摘下戒指给犹大人的仇敌—亚甲族哈米大他的儿子哈曼。","notes":[]},{"n":11,"t":"王对哈曼说：「这银子仍赐给你，这民也交给你，你可以随意待他们。」","notes":[]},{"n":12,"t":"正月十三日，就召了王的书记来，照着哈曼一切所吩咐的，用各省的文字、各族的方言，奉亚哈随鲁王的名写旨意，传与总督和各省的省长，并各族的首领；又用王的戒指盖印，","notes":[]},{"n":13,"t":"交给驿卒传到王的各省，吩咐将犹大人，无论老少妇女孩子，在一日之间，十二月，就是亚达月十三日，全然剪除，杀戮灭绝，并夺他们的财为掠物。","notes":[]},{"n":14,"t":"抄录这旨意，颁行各省，宣告各族，使他们预备等候那日。","notes":[]},{"n":15,"t":"驿卒奉王命急忙起行，旨意也传遍书珊城。王同哈曼坐下饮酒，书珊城的民却都慌乱。","notes":[]}]},"4":{"heading":"末底改求以斯帖帮忙","verses":[{"n":1,"t":"末底改知道所做的这一切事，就撕裂衣服，穿麻衣，蒙灰尘，在城中行走，痛哭哀号。","notes":[]},{"n":2,"t":"到了朝门前停住脚步，因为穿麻衣的不可进朝门。","notes":[]},{"n":3,"t":"王的谕旨所到的各省各处，犹大人大大悲哀，禁食哭泣哀号，穿麻衣躺在灰中的甚多。","notes":[]},{"n":4,"t":"王后以斯帖的宫女和太监来把这事告诉以斯帖，她甚是忧愁，就送衣服给末底改穿，要他脱下麻衣，他却不受。","notes":[]},{"n":5,"t":"以斯帖就把王所派伺候她的一个太监，名叫哈他革召来，吩咐他去见末底改，要知道这是什么事，是什么缘故。","notes":[]},{"n":6,"t":"于是哈他革出到朝门前的宽阔处见末底改。","notes":[]},{"n":7,"t":"末底改将自己所遇的事，并哈曼为灭绝犹大人应许捐入王库的银数都告诉了他；","notes":[]},{"n":8,"t":"又将所抄写传遍书珊城要灭绝犹大人的旨意交给哈他革，要给以斯帖看，又要给她说明，并嘱咐她进去见王，为本族的人在王面前恳切祈求。","notes":[]},{"n":9,"t":"哈他革回来，将末底改的话告诉以斯帖；","notes":[]},{"n":10,"t":"以斯帖就吩咐哈他革去见末底改，说：","notes":[]},{"n":11,"t":"「王的一切臣仆和各省的人民都知道有一个定例：若不蒙召，擅入内院见王的，无论男女必被治死；除非王向他伸出金杖，不得存活。现在我没有蒙召进去见王已经三十日了。」","notes":[]},{"n":12,"t":"人就把以斯帖这话告诉末底改。","notes":[]},{"n":13,"t":"末底改托人回复以斯帖说：「你莫想在王宫里强过一切犹大人，得免这祸。","notes":[]},{"n":14,"t":"此时你若闭口不言，犹大人必从别处得解脱，蒙拯救；你和你父家必致灭亡。焉知你得了王后的位分不是为现今的机会吗？」","notes":[]},{"n":15,"t":"以斯帖就吩咐人回报末底改说：","notes":[]},{"n":16,"t":"「你当去招聚书珊城所有的犹大人，为我禁食三昼三夜，不吃不喝；我和我的宫女也要这样禁食。然后我违例进去见王，我若死就死吧！」","notes":[]},{"n":17,"t":"于是末底改照以斯帖一切所吩咐的去行。","notes":[]}]},"5":{"heading":"以斯帖为王和哈曼设筵席","verses":[{"n":1,"t":"第三日，以斯帖穿上朝服，进王宫的内院，对殿站立。王在殿里坐在宝座上，对着殿门。","notes":[]},{"n":2,"t":"王见王后以斯帖站在院内，就施恩于她，向她伸出手中的金杖；以斯帖便向前摸杖头。","notes":[]},{"n":3,"t":"王对她说：「王后以斯帖啊，你要什么？你求什么，就是国的一半也必赐给你。」","notes":[]},{"n":4,"t":"以斯帖说：「王若以为美，就请王带着哈曼今日赴我所预备的筵席。」","notes":[]},{"n":5,"t":"王说：「叫哈曼速速照以斯帖的话去行。」于是王带着哈曼赴以斯帖所预备的筵席。","notes":[]},{"n":6,"t":"在酒席筵前，王又问以斯帖说：「你要什么，我必赐给你；你求什么，就是国的一半也必为你成就。」","notes":[]},{"n":7,"t":"以斯帖回答说：「我有所要，我有所求。","notes":[]},{"n":8,"t":"我若在王眼前蒙恩，王若愿意赐我所要的，准我所求的，就请王带着哈曼再赴我所要预备的筵席。明日我必照王所问的说明。」","notes":[]},{"n":9,"t":"那日哈曼心中快乐，欢欢喜喜地出来；但见末底改在朝门不站起来，连身也不动，就满心恼怒末底改。","notes":[],"heads":["哈曼阴谋杀末底改"]},{"n":10,"t":"哈曼暂且忍耐回家，叫人请他朋友和他妻子细利斯来。","notes":[]},{"n":11,"t":"哈曼将他富厚的荣耀、众多的儿女，和王抬举他使他超乎首领臣仆之上，都述说给他们听。","notes":[]},{"n":12,"t":"哈曼又说：「王后以斯帖预备筵席，除了我之外不许别人随王赴席。明日王后又请我随王赴席；","notes":[]},{"n":13,"t":"只是我见犹大人末底改坐在朝门，虽有这一切荣耀，也与我无益。」","notes":[]},{"n":14,"t":"他的妻细利斯和他一切的朋友对他说：「不如立一个五丈高的木架，明早求王将末底改挂在其上，然后你可以欢欢喜喜地随王赴席。」哈曼以这话为美，就叫人做了木架。","notes":[]}]},"6":{"heading":"王赐末底改荣誉","verses":[{"n":1,"t":"那夜王睡不着觉，就吩咐人取历史来，念给他听。","notes":[]},{"n":2,"t":"正遇见书上写着说：王的太监中有两个守门的，辟探和提列，想要下手害亚哈随鲁王，末底改将这事告诉王后。","notes":[]},{"n":3,"t":"王说：「末底改行了这事，赐他什么尊荣爵位没有？」伺候王的臣仆回答说：「没有赐他什么。」","notes":[]},{"n":4,"t":"王说：「谁在院子里？」（那时哈曼正进王宫的外院，要求王将末底改挂在他所预备的木架上。）","notes":[]},{"n":5,"t":"臣仆说：「哈曼站在院内。」王说：「叫他进来。」","notes":[]},{"n":6,"t":"哈曼就进去。王问他说：「王所喜悦尊荣的人，当如何待他呢？」哈曼心里说：「王所喜悦尊荣的，不是我是谁呢？」","notes":[]},{"n":7,"t":"哈曼就回答说：「王所喜悦尊荣的，","notes":[]},{"n":8,"t":"当将王常穿的朝服和戴冠的御马，","notes":[]},{"n":9,"t":"都交给王极尊贵的一个大臣，命他将衣服给王所喜悦尊荣的人穿上，使他骑上马，走遍城里的街市，在他面前宣告说：王所喜悦尊荣的人，就如此待他。」","notes":[]},{"n":10,"t":"王对哈曼说：「你速速将这衣服和马，照你所说的，向坐在朝门的犹大人末底改去行。凡你所说的，一样不可缺。」","notes":[]},{"n":11,"t":"于是哈曼将朝服给末底改穿上，使他骑上马，走遍城里的街市，在他面前宣告说：「王所喜悦尊荣的人，就如此待他。」","notes":[]},{"n":12,"t":"末底改仍回到朝门，哈曼却忧忧闷闷地蒙着头，急忙回家去了，","notes":[]},{"n":13,"t":"将所遇的一切事详细说给他的妻细利斯和他的众朋友听。他的智慧人和他的妻细利斯对他说：「你在末底改面前始而败落，他如果是犹大人，你必不能胜他，终必在他面前败落。」","notes":[]},{"n":14,"t":"他们还与哈曼说话的时候，王的太监来催哈曼快去赴以斯帖所预备的筵席。","notes":[]}]},"7":{"heading":"哈曼被处死","verses":[{"n":1,"t":"王带着哈曼来赴王后以斯帖的筵席。","notes":[]},{"n":2,"t":"这第二次在酒席筵前，王又问以斯帖说：「王后以斯帖啊，你要什么，我必赐给你；你求什么，就是国的一半也必为你成就。」","notes":[]},{"n":3,"t":"王后以斯帖回答说：「我若在王眼前蒙恩，王若以为美，我所愿的，是愿王将我的性命赐给我；我所求的，是求王将我的本族赐给我。","notes":[]},{"n":4,"t":"因我和我的本族被卖了，要剪除杀戮灭绝我们。我们若被卖为奴为婢，我也闭口不言；但王的损失，敌人万不能补足。」","notes":[]},{"n":5,"t":"亚哈随鲁王问王后以斯帖说：「擅敢起意如此行的是谁？这人在哪里呢？」","notes":[]},{"n":6,"t":"以斯帖说：「仇人敌人就是这恶人哈曼！」哈曼在王和王后面前就甚惊惶。","notes":[]},{"n":7,"t":"王便大怒，起来离开酒席往御园去了。哈曼见王定意要加罪与他，就起来，求王后以斯帖救命。","notes":[]},{"n":8,"t":"王从御园回到酒席之处，见哈曼伏在以斯帖所靠的榻上；王说：「他竟敢在宫内、在我面前凌辱王后吗？」这话一出王口，人就蒙了哈曼的脸。","notes":[]},{"n":9,"t":"伺候王的一个太监名叫哈波拿，说：「哈曼为那救王有功的末底改做了五丈高的木架，现今立在哈曼家里。」王说：「把哈曼挂在其上。」","notes":[]},{"n":10,"t":"于是人将哈曼挂在他为末底改所预备的木架上。王的忿怒这才止息。","notes":[]}]},"8":{"heading":"犹大人的反击","verses":[{"n":1,"t":"当日，亚哈随鲁王把犹大人仇敌哈曼的家产赐给王后以斯帖。末底改也来到王面前，因为以斯帖已经告诉王，末底改是她的亲属。","notes":[]},{"n":2,"t":"王摘下自己的戒指，就是从哈曼追回的，给了末底改。以斯帖派末底改管理哈曼的家产。","notes":[]},{"n":3,"t":"以斯帖又俯伏在王脚前，流泪哀告，求他除掉亚甲族哈曼害犹大人的恶谋。","notes":[]},{"n":4,"t":"王向以斯帖伸出金杖；以斯帖就起来，站在王前，","notes":[]},{"n":5,"t":"说：「亚甲族哈米大他的儿子哈曼设谋传旨，要杀灭在王各省的犹大人。现今王若愿意，我若在王眼前蒙恩，王若以为美，若喜悦我，请王另下旨意，废除哈曼所传的那旨意。","notes":[]},{"n":6,"t":"我何忍见我本族的人受害？何忍见我同宗的人被灭呢？」","notes":[]},{"n":7,"t":"亚哈随鲁王对王后以斯帖和犹大人末底改说：「因哈曼要下手害犹大人，我已将他的家产赐给以斯帖，人也将哈曼挂在木架上。","notes":[]},{"n":8,"t":"现在你们可以随意奉王的名写谕旨给犹大人，用王的戒指盖印；因为奉王名所写、用王戒指盖印的谕旨，人都不能废除。」","notes":[]},{"n":9,"t":"三月，就是西弯月二十三日，将王的书记召来，按着末底改所吩咐的，用各省的文字、各族的方言，并犹大人的文字方言写谕旨，传给那从印度直到古实一百二十七省的犹大人和总督省长首领。","notes":[]},{"n":10,"t":"末底改奉亚哈随鲁王的名写谕旨，用王的戒指盖印，交给骑御马圈快马的驿卒，传到各处。","notes":[]},{"n":11,"t":"谕旨中，王准各省各城的犹大人在一日之间，十二月，就是亚达月十三日，聚集保护性命，剪除杀戮灭绝那要攻击犹大人的一切仇敌和他们的妻子儿女，夺取他们的财为掠物。","notes":[],"end":12},{"n":13,"t":"抄录这谕旨，颁行各省，宣告各族，使犹大人预备等候那日，在仇敌身上报仇。","notes":[]},{"n":14,"t":"于是骑快马的驿卒被王命催促，急忙起行；谕旨也传遍书珊城。","notes":[]},{"n":15,"t":"末底改穿着蓝色白色的朝服，头戴大金冠冕，又穿紫色细麻布的外袍，从王面前出来；书珊城的人民都欢呼快乐。","notes":[]},{"n":16,"t":"犹大人有光荣，欢喜快乐而得尊贵。","notes":[]},{"n":17,"t":"王的谕旨所到的各省各城，犹大人都欢喜快乐，设摆筵宴，以那日为吉日。那国的人民，有许多因惧怕犹大人，就入了犹大籍。","notes":[]}]},"9":{"heading":"犹大人除灭他们的仇敌","verses":[{"n":1,"t":"十二月，乃亚达月十三日，王的谕旨将要举行，就是犹大人的仇敌盼望辖制他们的日子，犹大人反倒辖制恨他们的人。","notes":[]},{"n":2,"t":"犹大人在亚哈随鲁王各省的城里聚集，下手击杀那要害他们的人。无人能敌挡他们，因为各族都惧怕他们。","notes":[]},{"n":3,"t":"各省的首领、总督、省长，和办理王事的人，因惧怕末底改，就都帮助犹大人。","notes":[]},{"n":4,"t":"末底改在朝中为大，名声传遍各省，日渐昌盛。","notes":[]},{"n":5,"t":"犹大人用刀击杀一切仇敌，任意杀灭恨他们的人。","notes":[]},{"n":6,"t":"在书珊城，犹大人杀灭了五百人；","notes":[]},{"n":7,"t":"又杀巴珊大他、达分、亚斯帕他、","notes":[]},{"n":8,"t":"破拉他、亚大利雅、亚利大他、","notes":[]},{"n":9,"t":"帕玛斯他、亚利赛、亚利代、瓦耶撒他；","notes":[]},{"n":10,"t":"这十人都是哈米大他的孙子、犹大人仇敌哈曼的儿子。犹大人却没有下手夺取财物。","notes":[]},{"n":11,"t":"当日，将书珊城被杀的人数呈在王前。","notes":[]},{"n":12,"t":"王对王后以斯帖说：「犹大人在书珊城杀灭了五百人，又杀了哈曼的十个儿子，在王的各省不知如何呢？现在你要什么，我必赐给你；你还求什么，也必为你成就。」","notes":[]},{"n":13,"t":"以斯帖说：「王若以为美，求你准书珊的犹大人，明日也照今日的旨意行，并将哈曼十个儿子的尸首挂在木架上。」","notes":[]},{"n":14,"t":"王便允准如此行。旨意传在书珊，人就把哈曼十个儿子的尸首挂起来了。","notes":[]},{"n":15,"t":"亚达月十四日，书珊的犹大人又聚集在书珊，杀了三百人，却没有下手夺取财物。","notes":[]},{"n":16,"t":"在王各省其余的犹大人也都聚集保护性命，杀了恨他们的人七万五千，却没有下手夺取财物。这样，就脱离仇敌，得享平安。","notes":[]},{"n":17,"t":"亚达月十三日，行了这事；十四日安息，以这日为设筵欢乐的日子。","notes":[]},{"n":18,"t":"但书珊的犹大人，这十三日、十四日聚集杀戮仇敌；十五日安息，以这日为设筵欢乐的日子。","notes":[]},{"n":19,"t":"所以住无城墙乡村的犹大人，如今都以亚达月十四日为设筵欢乐的吉日，彼此馈送礼物。","notes":[]},{"n":20,"t":"末底改记录这事，写信与亚哈随鲁王各省远近所有的犹大人，","notes":[],"heads":["普珥日"]},{"n":21,"t":"嘱咐他们每年守亚达月十四、十五两日，","notes":[]},{"n":22,"t":"以这月的两日为犹大人脱离仇敌得平安、转忧为喜、转悲为乐的吉日。在这两日设筵欢乐，彼此馈送礼物，周济穷人。","notes":[]},{"n":23,"t":"于是，犹大人按着末底改所写与他们的信，应承照初次所守的守为永例；","notes":[]},{"n":24,"t":"是因犹大人的仇敌亚甲族哈米大他的儿子哈曼设谋杀害犹大人，掣普珥，就是掣签，为要杀尽灭绝他们；","notes":[]},{"n":25,"t":"这事报告于王，王便降旨使哈曼谋害犹大人的恶事归到他自己的头上，并吩咐把他和他的众子都挂在木架上。","notes":[]},{"n":26,"t":"照着普珥的名字，犹大人就称这两日为「普珥日」。他们因这信上的话，又因所看见所遇见的事，","notes":[]},{"n":27,"t":"就应承自己与后裔，并归附他们的人，每年按时必守这两日，永远不废。","notes":[]},{"n":28,"t":"各省各城、家家户户、世世代代纪念遵守这两日，使这「普珥日」在犹大人中不可废掉，在他们后裔中也不可忘记。","notes":[]},{"n":29,"t":"亚比孩的女儿—王后以斯帖和犹大人末底改以全权写第二封信，坚嘱犹大人守这「普珥日」，","notes":[]},{"n":30,"t":"用和平诚实话写信给亚哈随鲁王国中一百二十七省所有的犹大人，","notes":[]},{"n":31,"t":"劝他们按时守这「普珥日」，禁食呼求，是照犹大人末底改和王后以斯帖所嘱咐的，也照犹大人为自己与后裔所应承的。","notes":[]},{"n":32,"t":"以斯帖命定守「普珥日」，这事也记录在书上。","notes":[]}]},"10":{"heading":"亚哈随鲁和末底改的功绩","verses":[{"n":1,"t":"亚哈随鲁王使旱地和海岛的人民都进贡。","notes":[]},{"n":2,"t":"他以权柄能力所行的，并他抬举末底改使他高升的事，岂不都写在米底亚和波斯王的历史上吗？","notes":[]},{"n":3,"t":"犹大人末底改作亚哈随鲁王的宰相，在犹大人中为大，得他众弟兄的喜悦，为本族的人求好处，向他们说和平的话。","notes":[]}]}},"JOB":{"1":{"heading":"撒但试探约伯","verses":[{"n":1,"t":"乌斯地有一个人名叫约伯；那人完全正直，敬畏神，远离恶事。","notes":[]},{"n":2,"t":"他生了七个儿子，三个女儿。","notes":[]},{"n":3,"t":"他的家产有七千羊，三千骆驼，五百对牛，五百母驴，并有许多仆婢。这人在东方人中就为至大。","notes":[]},{"n":4,"t":"他的儿子按着日子各在自己家里设摆筵宴，就打发人去，请了他们的三个姊妹来，与他们一同吃喝。","notes":[]},{"n":5,"t":"筵宴的日子过了，约伯打发人去叫他们自洁。他清早起来，按着他们众人的数目献燔祭；因为他说：「恐怕我儿子犯了罪，心中弃掉神。」约伯常常这样行。","notes":[]},{"n":6,"t":"有一天，神的众子来侍立在耶和华面前，撒但也来在其中。","notes":[]},{"n":7,"t":"耶和华问撒但说：「你从哪里来？」撒但回答说：「我从地上走来走去，往返而来。」","notes":[]},{"n":8,"t":"耶和华问撒但说：「你曾用心察看我的仆人约伯没有？地上再没有人像他完全正直，敬畏神，远离恶事。」","notes":[]},{"n":9,"t":"撒但回答耶和华说：「约伯敬畏神，岂是无故呢？","notes":[]},{"n":10,"t":"你岂不是四面圈上篱笆围护他和他的家，并他一切所有的吗？他手所做的都蒙你赐福；他的家产也在地上增多。","notes":[]},{"n":11,"t":"你且伸手毁他一切所有的；他必当面弃掉你。」","notes":[]},{"n":12,"t":"耶和华对撒但说：「凡他所有的都在你手中；只是不可伸手加害于他。」于是撒但从耶和华面前退去。","notes":[]},{"n":13,"t":"有一天，约伯的儿女正在他们长兄的家里吃饭喝酒，","notes":[],"heads":["约伯丧失儿女和财产"]},{"n":14,"t":"有报信的来见约伯，说：「牛正耕地，驴在旁边吃草，","notes":[]},{"n":15,"t":"示巴人忽然闯来，把牲畜掳去，并用刀杀了仆人；惟有我一人逃脱，来报信给你。」","notes":[]},{"n":16,"t":"他还说话的时候，又有人来说：「神从天上降下火来，将群羊和仆人都烧灭了；惟有我一人逃脱，来报信给你。」","notes":[]},{"n":17,"t":"他还说话的时候，又有人来说：「迦勒底人分作三队忽然闯来，把骆驼掳去，并用刀杀了仆人；惟有我一人逃脱，来报信给你。」","notes":[]},{"n":18,"t":"他还说话的时候，又有人来说：「你的儿女正在他们长兄的家里吃饭喝酒，","notes":[]},{"n":19,"t":"不料，有狂风从旷野刮来，击打房屋的四角，房屋倒塌在少年人身上，他们就都死了；惟有我一人逃脱，来报信给你。」","notes":[]},{"n":20,"t":"约伯便起来，撕裂外袍，剃了头，伏在地上下拜，","notes":[]},{"n":21,"t":"说：「我赤身出于母胎，也必赤身归回；赏赐的是耶和华，收取的也是耶和华。耶和华的名是应当称颂的。」","notes":[]},{"n":22,"t":"在这一切的事上约伯并不犯罪，也不以神为愚妄。","notes":["或译：也不妄评神"]}]},"2":{"heading":"撒但再试探约伯","verses":[{"n":1,"t":"又有一天，神的众子来侍立在耶和华面前，撒但也来在其中。","notes":[]},{"n":2,"t":"耶和华问撒但说：「你从哪里来？」撒但回答说：「我从地上走来走去，往返而来。」","notes":[]},{"n":3,"t":"耶和华问撒但说：「你曾用心察看我的仆人约伯没有？地上再没有人像他完全正直，敬畏神，远离恶事。你虽激动我攻击他，无故地毁灭他，他仍然持守他的纯正。」","notes":[]},{"n":4,"t":"撒但回答耶和华说：「人以皮代皮，情愿舍去一切所有的，保全性命。","notes":[]},{"n":5,"t":"你且伸手伤他的骨头和他的肉，他必当面弃掉你。」","notes":[]},{"n":6,"t":"耶和华对撒但说：「他在你手中，只要存留他的性命。」","notes":[]},{"n":7,"t":"于是撒但从耶和华面前退去，击打约伯，使他从脚掌到头顶长毒疮。","notes":[]},{"n":8,"t":"约伯就坐在炉灰中，拿瓦片刮身体。","notes":[]},{"n":9,"t":"他的妻子对他说：「你仍然持守你的纯正吗？你弃掉神，死了吧！」","notes":[]},{"n":10,"t":"约伯却对她说：「你说话像愚顽的妇人一样。嗳！难道我们从神手里得福，不也受祸吗？」在这一切的事上约伯并不以口犯罪。","notes":[]},{"n":11,"t":"约伯的三个朋友—提幔人以利法、书亚人比勒达、拿玛人琐法—听说有这一切的灾祸临到他身上，各人就从本处约会同来，为他悲伤，安慰他。","notes":[],"heads":["三个朋友来安慰约伯"]},{"n":12,"t":"他们远远地举目观看，认不出他来，就放声大哭。各人撕裂外袍，把尘土向天扬起来，落在自己的头上。","notes":[]},{"n":13,"t":"他们就同他七天七夜坐在地上，一个人也不向他说句话，因为他极其痛苦。","notes":[]}]},"3":{"heading":"约伯咒诅自己","verses":[{"n":1,"t":"此后，约伯开口咒诅自己的生日，","notes":[]},{"n":2,"t":"说：","notes":[]},{"n":3,"t":"愿我生的那日和说怀了男胎的那夜都灭没。","notes":[]},{"n":4,"t":"愿那日变为黑暗；愿神不从上面寻找它；愿亮光不照于其上。","notes":[]},{"n":5,"t":"愿黑暗和死荫索取那日；愿密云停在其上；愿日蚀恐吓它。","notes":[]},{"n":6,"t":"愿那夜被幽暗夺取，不在年中的日子同乐，也不入月中的数目。","notes":[]},{"n":7,"t":"愿那夜没有生育，其间也没有欢乐的声音。","notes":[]},{"n":8,"t":"愿那咒诅日子且能惹动鳄鱼的咒诅那夜。","notes":[]},{"n":9,"t":"愿那夜黎明的星宿变为黑暗，盼亮却不亮，也不见早晨的光线；","notes":["原文是眼皮"]},{"n":10,"t":"因没有把怀我胎的门关闭，也没有将患难对我的眼隐藏。","notes":[]},{"n":11,"t":"我为何不出母胎而死？为何不出母腹绝气？","notes":[]},{"n":12,"t":"为何有膝接收我？为何有奶哺养我？","notes":[]},{"n":13,"t":"不然，我就早已躺卧安睡，","notes":[]},{"n":14,"t":"和地上为自己重造荒邱的君王、谋士，","notes":[]},{"n":15,"t":"或与有金子、将银子装满了房屋的王子一同安息；","notes":[]},{"n":16,"t":"或像隐而未现、不到期而落的胎，归于无有，如同未见光的婴孩。","notes":[]},{"n":17,"t":"在那里恶人止息搅扰，困乏人得享安息，","notes":[]},{"n":18,"t":"被囚的人同得安逸，不听见督工的声音。","notes":[]},{"n":19,"t":"大小都在那里；奴仆脱离主人的辖制。","notes":[]},{"n":20,"t":"受患难的人为何有光赐给他呢？心中愁苦的人为何有生命赐给他呢？","notes":[]},{"n":21,"t":"他们切望死，却不得死；求死，胜于求隐藏的珍宝。","notes":[]},{"n":22,"t":"他们寻见坟墓就快乐，极其欢喜。","notes":[]},{"n":23,"t":"人的道路既然遮隐，神又把他四面围困，为何有光赐给他呢？","notes":[]},{"n":24,"t":"我未曾吃饭就发出叹息；我唉哼的声音涌出如水。","notes":[]},{"n":25,"t":"因我所恐惧的临到我身，我所惧怕的迎我而来。","notes":[]},{"n":26,"t":"我不得安逸，不得平静，也不得安息，却有患难来到。","notes":[]}]},"4":{"heading":"第一次对话","verses":[{"n":1,"t":"提幔人以利法回答说：","notes":[]},{"n":2,"t":"人若想与你说话，你就厌烦吗？但谁能忍住不说呢？","notes":[]},{"n":3,"t":"你素来教导许多的人，又坚固软弱的手。","notes":[]},{"n":4,"t":"你的言语曾扶助那将要跌倒的人；你又使软弱的膝稳固。","notes":[]},{"n":5,"t":"但现在祸患临到你，你就昏迷，挨近你，你便惊惶。","notes":[]},{"n":6,"t":"你的倚靠不是在你敬畏神吗？你的盼望不是在你行事纯正吗？","notes":[]},{"n":7,"t":"请你追想：无辜的人有谁灭亡？正直的人在何处剪除？","notes":[]},{"n":8,"t":"按我所见，耕罪孽、种毒害的人都照样收割。","notes":[]},{"n":9,"t":"神一出气，他们就灭亡；神一发怒，他们就消没。","notes":[]},{"n":10,"t":"狮子的吼叫和猛狮的声音尽都止息；少壮狮子的牙齿也都敲掉。","notes":[]},{"n":11,"t":"老狮子因绝食而死；母狮之子也都离散。","notes":[]},{"n":12,"t":"我暗暗地得了默示；我耳朵也听其细微的声音。","notes":[]},{"n":13,"t":"在思念夜中、异象之间，世人沉睡的时候，","notes":[]},{"n":14,"t":"恐惧、战兢临到我身，使我百骨打战。","notes":[]},{"n":15,"t":"有灵从我面前经过，我身上的毫毛直立。","notes":[]},{"n":16,"t":"那灵停住，我却不能辨其形状；有影像在我眼前。我在静默中听见有声音说：","notes":[]},{"n":17,"t":"必死的人岂能比神公义吗？人岂能比造他的主洁净吗？","notes":[]},{"n":18,"t":"主不信靠他的臣仆，并且指他的使者为愚昧；","notes":[]},{"n":19,"t":"何况那住在土房、根基在尘土里、被蠹虫所毁坏的人呢？","notes":[]},{"n":20,"t":"早晚之间，就被毁灭，永归无有，无人理会。","notes":[]},{"n":21,"t":"他帐棚的绳索岂不从中抽出来呢？他死，且是无智慧而死。","notes":[]}]},"5":{"heading":"","verses":[{"n":1,"t":"你且呼求，有谁答应你？诸圣者之中，你转向哪一位呢？","notes":[]},{"n":2,"t":"忿怒害死愚妄人；嫉妒杀死痴迷人。","notes":[]},{"n":3,"t":"我曾见愚妄人扎下根，但我忽然咒诅他的住处。","notes":[]},{"n":4,"t":"他的儿女远离稳妥的地步，在城门口被压，并无人搭救。","notes":[]},{"n":5,"t":"他的庄稼有饥饿的人吃尽了，就是在荆棘里的也抢去了；他的财宝有网罗张口吞灭了。","notes":[]},{"n":6,"t":"祸患原不是从土中出来；患难也不是从地里发生。","notes":[]},{"n":7,"t":"人生在世必遇患难，如同火星飞腾。","notes":[]},{"n":8,"t":"至于我，我必仰望神，把我的事情托付他。","notes":[]},{"n":9,"t":"他行大事不可测度，行奇事不可胜数：","notes":[]},{"n":10,"t":"降雨在地上，赐水于田里；","notes":[]},{"n":11,"t":"将卑微的安置在高处，将哀痛的举到稳妥之地；","notes":[]},{"n":12,"t":"破坏狡猾人的计谋，使他们所谋的不得成就。","notes":[]},{"n":13,"t":"他叫有智慧的中了自己的诡计，使狡诈人的计谋速速灭亡。","notes":[]},{"n":14,"t":"他们白昼遇见黑暗，午间摸索如在夜间。","notes":[]},{"n":15,"t":"神拯救穷乏人脱离他们口中的刀和强暴人的手。","notes":[]},{"n":16,"t":"这样，贫寒的人有指望，罪孽之辈必塞口无言。","notes":[]},{"n":17,"t":"神所惩治的人是有福的！所以你不可轻看全能者的管教。","notes":[]},{"n":18,"t":"因为他打破，又缠裹；他击伤，用手医治。","notes":[]},{"n":19,"t":"你六次遭难，他必救你；就是七次，灾祸也无法害你。","notes":[]},{"n":20,"t":"在饥荒中，他必救你脱离死亡；在争战中，他必救你脱离刀剑的权力。","notes":[]},{"n":21,"t":"你必被隐藏，不受口舌之害；灾殃临到，你也不惧怕。","notes":[]},{"n":22,"t":"你遇见灾害饥馑，就必嬉笑；地上的野兽，你也不惧怕。","notes":[]},{"n":23,"t":"因为你必与田间的石头立约；田里的野兽也必与你和好。","notes":[]},{"n":24,"t":"你必知道你帐棚平安，要查看你的羊圈，一无所失；","notes":[]},{"n":25,"t":"也必知道你的后裔将来发达，你的子孙像地上的青草。","notes":[]},{"n":26,"t":"你必寿高年迈才归坟墓，好像禾捆到时收藏。","notes":[]},{"n":27,"t":"这理，我们已经考察，本是如此。你须要听，要知道是与自己有益。","notes":[]}]},"6":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"惟愿我的烦恼称一称，我一切的灾害放在天平里；","notes":[]},{"n":3,"t":"现今都比海沙更重，所以我的言语急躁。","notes":[]},{"n":4,"t":"因全能者的箭射入我身；其毒，我的灵喝尽了；神的惊吓摆阵攻击我。","notes":[]},{"n":5,"t":"野驴有草岂能叫唤？牛有料岂能吼叫？","notes":[]},{"n":6,"t":"物淡而无盐岂可吃吗？蛋青有什么滋味呢？","notes":[]},{"n":7,"t":"看为可厌的食物，我心不肯挨近。","notes":[]},{"n":8,"t":"惟愿我得着所求的，愿神赐我所切望的；","notes":[]},{"n":9,"t":"就是愿神把我压碎，伸手将我剪除。","notes":[]},{"n":10,"t":"我因没有违弃那圣者的言语，就仍以此为安慰，在不止息的痛苦中还可踊跃。","notes":[]},{"n":11,"t":"我有什么气力使我等候？我有什么结局使我忍耐？","notes":[]},{"n":12,"t":"我的气力岂是石头的气力？我的肉身岂是铜的呢？","notes":[]},{"n":13,"t":"在我岂不是毫无帮助吗？智慧岂不是从我心中赶出净尽吗？","notes":[]},{"n":14,"t":"那将要灰心、离弃全能者、不敬畏神的人，他的朋友当以慈爱待他。","notes":[]},{"n":15,"t":"我的弟兄诡诈，好像溪水，又像溪水流干的河道。","notes":[]},{"n":16,"t":"这河因结冰发黑，有雪藏在其中；","notes":[]},{"n":17,"t":"天气渐暖就随时消化，日头炎热便从原处干涸。","notes":[]},{"n":18,"t":"结伴的客旅离弃大道，顺河偏行，到荒野之地死亡。","notes":[]},{"n":19,"t":"提玛结伴的客旅瞻望；示巴同伙的人等候。","notes":[]},{"n":20,"t":"他们因失了盼望就抱愧，来到那里便蒙羞。","notes":[]},{"n":21,"t":"现在你们正是这样，看见惊吓的事便惧怕。","notes":[]},{"n":22,"t":"我岂说：请你们供给我，从你们的财物中送礼物给我？","notes":[]},{"n":23,"t":"岂说：拯救我脱离敌人的手吗？救赎我脱离强暴人的手吗？","notes":[]},{"n":24,"t":"请你们教导我，我便不作声；使我明白在何事上有错。","notes":[]},{"n":25,"t":"正直的言语力量何其大！但你们责备是责备什么呢？","notes":[]},{"n":26,"t":"绝望人的讲论既然如风，你们还想要驳正言语吗？","notes":[]},{"n":27,"t":"你们想为孤儿拈阄，以朋友当货物。","notes":[]},{"n":28,"t":"现在请你们看看我，我决不当面说谎。","notes":[]},{"n":29,"t":"请你们转意，不要不公；请再转意，我的事有理。","notes":[]},{"n":30,"t":"我的舌上岂有不义吗？我的口里岂不辨奸恶吗？","notes":[]}]},"7":{"heading":"","verses":[{"n":1,"t":"人在世上岂无争战吗？他的日子不像雇工人的日子吗？","notes":[]},{"n":2,"t":"像奴仆切慕黑影，像雇工人盼望工价；","notes":[]},{"n":3,"t":"我也照样经过困苦的日月，夜间的疲乏为我而定。","notes":[]},{"n":4,"t":"我躺卧的时候便说：我何时起来，黑夜就过去呢？我尽是反来复去，直到天亮。","notes":[]},{"n":5,"t":"我的肉体以虫子和尘土为衣；我的皮肤才收了口又重新破裂。","notes":[]},{"n":6,"t":"我的日子比梭更快，都消耗在无指望之中。","notes":[]},{"n":7,"t":"求你想念，我的生命不过是一口气；我的眼睛必不再见福乐。","notes":[]},{"n":8,"t":"观看我的人，他的眼必不再见我；你的眼目要看我，我却不在了。","notes":[]},{"n":9,"t":"云彩消散而过；照样，人下阴间也不再上来。","notes":[]},{"n":10,"t":"他不再回自己的家；故土也不再认识他。","notes":[]},{"n":11,"t":"我不禁止我口；我灵愁苦，要发出言语；我心苦恼，要吐露哀情。","notes":[]},{"n":12,"t":"我对神说：我岂是洋海，岂是大鱼，你竟防守我呢？","notes":[]},{"n":13,"t":"若说：我的床必安慰我，我的榻必解释我的苦情，","notes":[]},{"n":14,"t":"你就用梦惊骇我，用异象恐吓我，","notes":[]},{"n":15,"t":"甚至我宁肯噎死，宁肯死亡，胜似留我这一身的骨头。","notes":[]},{"n":16,"t":"我厌弃性命，不愿永活。你任凭我吧，因我的日子都是虚空。","notes":[]},{"n":17,"t":"人算什么，你竟看他为大，将他放在心上？","notes":[]},{"n":18,"t":"每早鉴察他，时刻试验他？","notes":[]},{"n":19,"t":"你到何时才转眼不看我，才任凭我咽下唾沫呢？","notes":[]},{"n":20,"t":"鉴察人的主啊，我若有罪，于你何妨？为何以我当你的箭靶子，使我厌弃自己的性命？","notes":[]},{"n":21,"t":"为何不赦免我的过犯，除掉我的罪孽？我现今要躺卧在尘土中；你要殷勤地寻找我，我却不在了。","notes":[]}]},"8":{"heading":"","verses":[{"n":1,"t":"书亚人比勒达回答说：","notes":[]},{"n":2,"t":"这些话你要说到几时？口中的言语如狂风要到几时呢？","notes":[]},{"n":3,"t":"神岂能偏离公平？全能者岂能偏离公义？","notes":[]},{"n":4,"t":"或者你的儿女得罪了他；他使他们受报应。","notes":[]},{"n":5,"t":"你若殷勤地寻求神，向全能者恳求；","notes":[]},{"n":6,"t":"你若清洁正直，他必定为你起来，使你公义的居所兴旺。","notes":[]},{"n":7,"t":"你起初虽然微小，终久必甚发达。","notes":[]},{"n":8,"t":"请你考问前代，追念他们的列祖所查究的。","notes":[]},{"n":9,"t":"我们不过从昨日才有，一无所知；我们在世的日子好像影儿。","notes":[]},{"n":10,"t":"他们岂不指教你，告诉你，从心里发出言语来呢？","notes":[]},{"n":11,"t":"蒲草没有泥岂能发长？芦荻没有水岂能生发？","notes":[]},{"n":12,"t":"尚青的时候，还没有割下，比百样的草先枯槁。","notes":[]},{"n":13,"t":"凡忘记神的人，景况也是这样；不虔敬人的指望要灭没。","notes":[]},{"n":14,"t":"他所仰赖的必折断；他所倚靠的是蜘蛛网。","notes":[]},{"n":15,"t":"他要倚靠房屋，房屋却站立不住；他要抓住房屋，房屋却不能存留。","notes":[]},{"n":16,"t":"他在日光之下发青，蔓子爬满了园子；","notes":[]},{"n":17,"t":"他的根盘绕石堆，扎入石地。","notes":[]},{"n":18,"t":"他若从本地被拔出，那地就不认识他，说：我没有见过你。","notes":[]},{"n":19,"t":"看哪，这就是他道中之乐；以后必另有人从地而生。","notes":[]},{"n":20,"t":"神必不丢弃完全人，也不扶助邪恶人。","notes":[]},{"n":21,"t":"他还要以喜笑充满你的口，以欢呼充满你的嘴。","notes":[]},{"n":22,"t":"恨恶你的要披戴惭愧；恶人的帐棚必归于无有。","notes":[]}]},"9":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"我真知道是这样；但人在神面前怎能成为义呢？","notes":[]},{"n":3,"t":"若愿意与他争辩，千中之一也不能回答。","notes":[]},{"n":4,"t":"他心里有智慧，且大有能力。谁向神刚硬而得亨通呢？","notes":[]},{"n":5,"t":"他发怒，把山翻倒挪移，山并不知觉。","notes":[]},{"n":6,"t":"他使地震动，离其本位，地的柱子就摇撼。","notes":[]},{"n":7,"t":"他吩咐日头不出来，就不出来，又封闭众星。","notes":[]},{"n":8,"t":"他独自铺张苍天，步行在海浪之上。","notes":[]},{"n":9,"t":"他造北斗、参星、昴星，并南方的密宫；","notes":[]},{"n":10,"t":"他行大事，不可测度，行奇事，不可胜数。","notes":[]},{"n":11,"t":"他从我旁边经过，我却不看见；他在我面前行走，我倒不知觉。","notes":[]},{"n":12,"t":"他夺取，谁能阻挡？谁敢问他：你做什么？","notes":[]},{"n":13,"t":"神必不收回他的怒气；扶助拉哈伯的，屈身在他以下。","notes":[]},{"n":14,"t":"既是这样，我怎敢回答他，怎敢选择言语与他辩论呢？","notes":[]},{"n":15,"t":"我虽有义，也不回答他，只要向那审判我的恳求。","notes":[]},{"n":16,"t":"我若呼吁，他应允我；我仍不信他真听我的声音。","notes":[]},{"n":17,"t":"他用暴风折断我，无故地加增我的损伤。","notes":[]},{"n":18,"t":"我就是喘一口气，他都不容，倒使我满心苦恼。","notes":[]},{"n":19,"t":"若论力量，他真有能力！若论审判，他说谁能将我传来呢？","notes":[]},{"n":20,"t":"我虽有义，自己的口要定我为有罪；我虽完全，我口必显我为弯曲。","notes":[]},{"n":21,"t":"我本完全，不顾自己；我厌恶我的性命。","notes":[]},{"n":22,"t":"善恶无分，都是一样；所以我说，完全人和恶人，他都灭绝。","notes":[]},{"n":23,"t":"若忽然遭杀害之祸，他必戏笑无辜的人遇难。","notes":[]},{"n":24,"t":"世界交在恶人手中；蒙蔽世界审判官的脸，若不是他，是谁呢？","notes":[]},{"n":25,"t":"我的日子比跑信的更快，急速过去，不见福乐。","notes":[]},{"n":26,"t":"我的日子过去如快船，如急落抓食的鹰。","notes":[]},{"n":27,"t":"我若说：我要忘记我的哀情，除去我的愁容，心中畅快；","notes":[]},{"n":28,"t":"我因愁苦而惧怕，知道你必不以我为无辜。","notes":[]},{"n":29,"t":"我必被你定为有罪，我何必徒然劳苦呢？","notes":[]},{"n":30,"t":"我若用雪水洗身，用硷洁净我的手，","notes":[]},{"n":31,"t":"你还要扔我在坑里，我的衣服都憎恶我。","notes":[]},{"n":32,"t":"他本不像我是人，使我可以回答他，又使我们可以同听审判。","notes":[]},{"n":33,"t":"我们中间没有听讼的人可以向我们两造按手。","notes":[]},{"n":34,"t":"愿他把杖离开我，不使惊惶威吓我。","notes":[]},{"n":35,"t":"我就说话，也不惧怕他，现在我却不是那样。","notes":[]}]},"10":{"heading":"","verses":[{"n":1,"t":"我厌烦我的性命，必由着自己述说我的哀情；因心里苦恼，我要说话，","notes":[]},{"n":2,"t":"对神说：不要定我有罪，要指示我，你为何与我争辩？","notes":[]},{"n":3,"t":"你手所造的，你又欺压，又藐视，却光照恶人的计谋。这事你以为美吗？","notes":[]},{"n":4,"t":"你的眼岂是肉眼？你查看岂像人查看吗？","notes":[]},{"n":5,"t":"你的日子岂像人的日子，你的年岁岂像人的年岁，","notes":[]},{"n":6,"t":"就追问我的罪孽，寻察我的罪过吗？","notes":[]},{"n":7,"t":"其实，你知道我没有罪恶，并没有能救我脱离你手的。","notes":[]},{"n":8,"t":"你的手创造我，造就我的四肢百体，你还要毁灭我。","notes":[]},{"n":9,"t":"求你记念—制造我如抟泥一般，你还要使我归于尘土吗？","notes":[]},{"n":10,"t":"你不是倒出我来好像奶，使我凝结如同奶饼吗？","notes":[]},{"n":11,"t":"你以皮和肉为衣给我穿上，用骨与筋把我全体联络。","notes":[]},{"n":12,"t":"你将生命和慈爱赐给我；你也眷顾保全我的心灵。","notes":[]},{"n":13,"t":"然而，你待我的这些事早已藏在你心里；我知道你久有此意。","notes":[]},{"n":14,"t":"我若犯罪，你就察看我，并不赦免我的罪孽。","notes":[]},{"n":15,"t":"我若行恶，便有了祸；我若为义，也不敢抬头，正是满心羞愧，眼见我的苦情。","notes":[]},{"n":16,"t":"我若昂首自得，你就追捕我如狮子，又在我身上显出奇能。","notes":[]},{"n":17,"t":"你重立见证攻击我，向我加增恼怒，如军兵更换着攻击我。","notes":[]},{"n":18,"t":"你为何使我出母胎呢？不如我当时气绝，无人得见我；","notes":[]},{"n":19,"t":"这样，就如没有我一般，一出母胎就被送入坟墓。","notes":[]},{"n":20,"t":"我的日子不是甚少吗？求你停手宽容我，叫我在往而不返之先—就是往黑暗和死荫之地以先—可以稍得畅快。","notes":[],"end":21},{"n":22,"t":"那地甚是幽暗，是死荫混沌之地；那里的光好像幽暗。","notes":[]}]},"11":{"heading":"","verses":[{"n":1,"t":"拿玛人琐法回答说：","notes":[]},{"n":2,"t":"这许多的言语岂不该回答吗？多嘴多舌的人岂可称为义吗？","notes":[]},{"n":3,"t":"你夸大的话岂能使人不作声吗？你戏笑的时候岂没有人叫你害羞吗？","notes":[]},{"n":4,"t":"你说：我的道理纯全；我在你眼前洁净。","notes":[]},{"n":5,"t":"惟愿神说话；愿他开口攻击你，","notes":[]},{"n":6,"t":"并将智慧的奥秘指示你；他有诸般的智识。所以当知道神追讨你比你罪孽该得的还少。","notes":[]},{"n":7,"t":"你考察就能测透神吗？你岂能尽情测透全能者吗？","notes":[]},{"n":8,"t":"他的智慧高于天，你还能做什么？深于阴间，你还能知道什么？","notes":[]},{"n":9,"t":"其量比地长，比海宽。","notes":[]},{"n":10,"t":"他若经过，将人拘禁，招人受审，谁能阻挡他呢？","notes":[]},{"n":11,"t":"他本知道虚妄的人；人的罪孽，他虽不留意，还是无所不见。","notes":[]},{"n":12,"t":"空虚的人却毫无知识；人生在世好像野驴的驹子。","notes":[]},{"n":13,"t":"你若将心安正，又向主举手；","notes":[]},{"n":14,"t":"你手里若有罪孽，就当远远地除掉，也不容非义住在你帐棚之中。","notes":[]},{"n":15,"t":"那时，你必仰起脸来毫无斑点；你也必坚固，无所惧怕。","notes":[]},{"n":16,"t":"你必忘记你的苦楚，就是想起也如流过去的水一样。","notes":[]},{"n":17,"t":"你在世的日子要比正午更明，虽有黑暗仍像早晨。","notes":[]},{"n":18,"t":"你因有指望就必稳固，也必四围巡查，坦然安息。","notes":[]},{"n":19,"t":"你躺卧，无人惊吓，且有许多人向你求恩。","notes":[]},{"n":20,"t":"但恶人的眼目必要失明。他们无路可逃；他们的指望就是气绝。","notes":[]}]},"12":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"你们真是子民哪，你们死亡，智慧也就灭没了。","notes":[]},{"n":3,"t":"但我也有聪明，与你们一样，并非不及你们。你们所说的，谁不知道呢？","notes":[]},{"n":4,"t":"我这求告神、蒙他应允的人竟成了朋友所讥笑的；公义完全人竟受了人的讥笑。","notes":[]},{"n":5,"t":"安逸的人心里藐视灾祸；这灾祸常常等待滑脚的人。","notes":[]},{"n":6,"t":"强盗的帐棚兴旺，惹神的人稳固，神多将财物送到他们手中。","notes":[]},{"n":7,"t":"你且问走兽，走兽必指教你；又问空中的飞鸟，飞鸟必告诉你；","notes":[]},{"n":8,"t":"或与地说话，地必指教你；海中的鱼也必向你说明。","notes":[]},{"n":9,"t":"看这一切，谁不知道是耶和华的手做成的呢？","notes":[]},{"n":10,"t":"凡活物的生命和人类的气息都在他手中。","notes":[]},{"n":11,"t":"耳朵岂不试验言语，正如上膛尝食物吗？","notes":[]},{"n":12,"t":"年老的有智慧；寿高的有知识。","notes":[]},{"n":13,"t":"在神有智慧和能力；他有谋略和知识。","notes":[]},{"n":14,"t":"他拆毁的，就不能再建造；他捆住人，便不得开释。","notes":[]},{"n":15,"t":"他把水留住，水便枯干；他再发出水来，水就翻地。","notes":[]},{"n":16,"t":"在他有能力和智慧，被诱惑的与诱惑人的都是属他。","notes":[]},{"n":17,"t":"他把谋士剥衣掳去，又使审判官变成愚人。","notes":[]},{"n":18,"t":"他放松君王的绑，又用带子捆他们的腰。","notes":[]},{"n":19,"t":"他把祭司剥衣掳去，又使有能的人倾败。","notes":[]},{"n":20,"t":"他废去忠信人的讲论，又夺去老人的聪明。","notes":[]},{"n":21,"t":"他使君王蒙羞被辱，放松有力之人的腰带。","notes":[]},{"n":22,"t":"他将深奥的事从黑暗中彰显，使死荫显为光明。","notes":[]},{"n":23,"t":"他使邦国兴旺而又毁灭；他使邦国开广而又掳去。","notes":[]},{"n":24,"t":"他将地上民中首领的聪明夺去，使他们在荒废无路之地漂流；","notes":[]},{"n":25,"t":"他们无光，在黑暗中摸索，又使他们东倒西歪，像醉酒的人一样。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"这一切，我眼都见过；我耳都听过，而且明白。","notes":[]},{"n":2,"t":"你们所知道的，我也知道，并非不及你们。","notes":[]},{"n":3,"t":"我真要对全能者说话；我愿与神理论。","notes":[]},{"n":4,"t":"你们是编造谎言的，都是无用的医生。","notes":[]},{"n":5,"t":"惟愿你们全然不作声；这就算为你们的智慧！","notes":[]},{"n":6,"t":"请你们听我的辩论，留心听我口中的分诉。","notes":[]},{"n":7,"t":"你们要为神说不义的话吗？为他说诡诈的言语吗？","notes":[]},{"n":8,"t":"你们要为神徇情吗？要为他争论吗？","notes":[]},{"n":9,"t":"他查出你们来，这岂是好吗？人欺哄人，你们也要照样欺哄他吗？","notes":[]},{"n":10,"t":"你们若暗中徇情，他必要责备你们。","notes":[]},{"n":11,"t":"他的尊荣岂不叫你们惧怕吗？他的惊吓岂不临到你们吗？","notes":[]},{"n":12,"t":"你们以为可记念的箴言是炉灰的箴言；你们以为可靠的坚垒是淤泥的坚垒。","notes":[]},{"n":13,"t":"你们不要作声，任凭我吧！让我说话，无论如何我都承当。","notes":[]},{"n":14,"t":"我何必把我的肉挂在牙上，将我的命放在手中。","notes":[]},{"n":15,"t":"他必杀我；我虽无指望，然而我在他面前还要辩明我所行的。","notes":[]},{"n":16,"t":"这要成为我的拯救，因为不虔诚的人不得到他面前。","notes":[]},{"n":17,"t":"你们要细听我的言语，使我所辩论的入你们的耳中。","notes":[]},{"n":18,"t":"我已陈明我的案，知道自己有义。","notes":[]},{"n":19,"t":"有谁与我争论，我就情愿缄默不言，气绝而亡。","notes":[]},{"n":20,"t":"惟有两件不要向我施行，我就不躲开你的面：","notes":[]},{"n":21,"t":"就是把你的手缩回，远离我身；又不使你的惊惶威吓我。","notes":[]},{"n":22,"t":"这样，你呼叫，我就回答；或是让我说话，你回答我。","notes":[]},{"n":23,"t":"我的罪孽和罪过有多少呢？求你叫我知道我的过犯与罪愆。","notes":[]},{"n":24,"t":"你为何掩面、拿我当仇敌呢？","notes":[]},{"n":25,"t":"你要惊动被风吹的叶子吗？要追赶枯干的碎秸吗？","notes":[]},{"n":26,"t":"你按罪状刑罚我，又使我担当幼年的罪孽；","notes":[]},{"n":27,"t":"也把我的脚上了木狗，并窥察我一切的道路，为我的脚掌划定界限。","notes":[]},{"n":28,"t":"我已经像灭绝的烂物，像虫蛀的衣裳。","notes":[]}]},"14":{"heading":"","verses":[{"n":1,"t":"人为妇人所生，日子短少，多有患难；","notes":[]},{"n":2,"t":"出来如花，又被割下，飞去如影，不能存留。","notes":[]},{"n":3,"t":"这样的人你岂睁眼看他吗？又叫我来受审吗？","notes":[]},{"n":4,"t":"谁能使洁净之物出于污秽之中呢？无论谁也不能！","notes":[]},{"n":5,"t":"人的日子既然限定，他的月数在你那里，你也派定他的界限，使他不能越过，","notes":[]},{"n":6,"t":"便求你转眼不看他，使他得歇息，直等他像雇工人完毕他的日子。","notes":[]},{"n":7,"t":"树若被砍下，还可指望发芽，嫩枝生长不息；","notes":[]},{"n":8,"t":"其根虽然衰老在地里，干也死在土中，","notes":[]},{"n":9,"t":"及至得了水气，还要发芽，又长枝条，像新栽的树一样。","notes":[]},{"n":10,"t":"但人死亡而消灭；他气绝，竟在何处呢？","notes":[]},{"n":11,"t":"海中的水绝尽，江河消散干涸。","notes":[]},{"n":12,"t":"人也是如此，躺下不再起来，等到天没有了，仍不得复醒，也不得从睡中唤醒。","notes":[]},{"n":13,"t":"惟愿你把我藏在阴间，存于隐密处，等你的忿怒过去；愿你为我定了日期，记念我。","notes":[]},{"n":14,"t":"人若死了岂能再活呢？我只要在我一切争战的日子，等我被释放的时候来到。","notes":["或译：改变"]},{"n":15,"t":"你呼叫，我便回答；你手所做的，你必羡慕。","notes":[]},{"n":16,"t":"但如今你数点我的脚步，岂不窥察我的罪过吗？","notes":[]},{"n":17,"t":"我的过犯被你封在囊中，也缝严了我的罪孽。","notes":[]},{"n":18,"t":"山崩变为无有；磐石挪开原处。","notes":[]},{"n":19,"t":"水流消磨石头，所流溢的洗去地上的尘土；你也照样灭绝人的指望。","notes":[]},{"n":20,"t":"你攻击人常常得胜，使他去世；你改变他的容貌，叫他往而不回。","notes":[]},{"n":21,"t":"他儿子得尊荣，他也不知道，降为卑，他也不觉得。","notes":[]},{"n":22,"t":"但知身上疼痛，心中悲哀。","notes":[]}]},"15":{"heading":"第二次对话","verses":[{"n":1,"t":"提幔人以利法回答说：","notes":[]},{"n":2,"t":"智慧人岂可用虚空的知识回答，用东风充满肚腹呢？","notes":[]},{"n":3,"t":"他岂可用无益的话和无济于事的言语理论呢？","notes":[]},{"n":4,"t":"你是废弃敬畏的意，在神面前阻止敬虔的心。","notes":[]},{"n":5,"t":"你的罪孽指教你的口；你选用诡诈人的舌头。","notes":[]},{"n":6,"t":"你自己的口定你有罪，并非是我；你自己的嘴见证你的不是。","notes":[]},{"n":7,"t":"你岂是头一个被生的人吗？你受造在诸山之先吗？","notes":[]},{"n":8,"t":"你曾听见神的密旨吗？你还将智慧独自得尽吗？","notes":[]},{"n":9,"t":"你知道什么是我们不知道的呢？你明白什么是我们不明白的呢？","notes":[]},{"n":10,"t":"我们这里有白发的和年纪老迈的，比你父亲还老。","notes":[]},{"n":11,"t":"神用温和的话安慰你，你以为太小吗？","notes":[]},{"n":12,"t":"你的心为何将你逼去？你的眼为何冒出火星，","notes":[]},{"n":13,"t":"使你的灵反对神，也任你的口发这言语？","notes":[]},{"n":14,"t":"人是什么，竟算为洁净呢？妇人所生的是什么，竟算为义呢？","notes":[]},{"n":15,"t":"神不信靠他的众圣者；在他眼前，天也不洁净，","notes":[]},{"n":16,"t":"何况那污秽可憎、喝罪孽如水的世人呢！","notes":[]},{"n":17,"t":"我指示你，你要听；我要述说所看见的，","notes":[]},{"n":18,"t":"就是智慧人从列祖所受，传说而不隐瞒的。","notes":[]},{"n":19,"t":"这地惟独赐给他们，并没有外人从他们中间经过。","notes":[]},{"n":20,"t":"恶人一生之日劬劳痛苦；强暴人一生的年数也是如此。","notes":[]},{"n":21,"t":"惊吓的声音常在他耳中；在平安时，抢夺的必临到他那里。","notes":[]},{"n":22,"t":"他不信自己能从黑暗中转回；他被刀剑等候。","notes":[]},{"n":23,"t":"他漂流在外求食，说：哪里有食物呢？他知道黑暗的日子在他手边预备好了。","notes":[]},{"n":24,"t":"急难困苦叫他害怕，而且胜了他，好像君王预备上阵一样。","notes":[]},{"n":25,"t":"他伸手攻击神，以骄傲攻击全能者，","notes":[]},{"n":26,"t":"挺着颈项，用盾牌的厚凸面向全能者直闯；","notes":[]},{"n":27,"t":"是因他的脸蒙上脂油，腰积成肥肉。","notes":[]},{"n":28,"t":"他曾住在荒凉城邑，无人居住、将成乱堆的房屋。","notes":[]},{"n":29,"t":"他不得富足，财物不得常存，产业在地上也不加增。","notes":[]},{"n":30,"t":"他不得出离黑暗。火焰要将他的枝子烧干；因神口中的气，他要灭亡 。","notes":["原文是走去"]},{"n":31,"t":"他不用倚靠虚假欺哄自己，因虚假必成为他的报应。","notes":[]},{"n":32,"t":"他的日期未到之先，这事必成就；他的枝子不得青绿。","notes":[]},{"n":33,"t":"他必像葡萄树的葡萄，未熟而落；又像橄榄树的花，一开而谢。","notes":[]},{"n":34,"t":"原来不敬虔之辈必无生育；受贿赂之人的帐棚必被火烧。","notes":[]},{"n":35,"t":"他们所怀的是毒害，所生的是罪孽；心里所预备的是诡诈。","notes":[]}]},"16":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"这样的话我听了许多；你们安慰人，反叫人愁烦。","notes":[]},{"n":3,"t":"虚空的言语有穷尽吗？有什么话惹动你回答呢？","notes":[]},{"n":4,"t":"我也能说你们那样的话；你们若处在我的境遇，我也会联络言语攻击你们，又能向你们摇头。","notes":[]},{"n":5,"t":"但我必用口坚固你们，用嘴消解你们的忧愁。","notes":[]},{"n":6,"t":"我虽说话，忧愁仍不得消解；我虽停住不说，忧愁就离开我吗？","notes":[]},{"n":7,"t":"但现在神使我困倦，使亲友远离我，","notes":[]},{"n":8,"t":"又抓住我，作见证攻击我；我身体的枯瘦也当面见证我的不是。","notes":[]},{"n":9,"t":"主发怒撕裂我，逼迫我，向我切齿；我的敌人怒目看我。","notes":[]},{"n":10,"t":"他们向我开口，打我的脸羞辱我，聚会攻击我。","notes":[]},{"n":11,"t":"神把我交给不敬虔的人，把我扔到恶人的手中。","notes":[]},{"n":12,"t":"我素来安逸，他折断我，掐住我的颈项，把我摔碎，又立我为他的箭靶子。","notes":[]},{"n":13,"t":"他的弓箭手四面围绕我；他破裂我的肺腑，并不留情，把我的胆倾倒在地上，","notes":[]},{"n":14,"t":"将我破裂又破裂，如同勇士向我直闯。","notes":[]},{"n":15,"t":"我缝麻布在我皮肤上，把我的角放在尘土中。","notes":[]},{"n":16,"t":"我的脸因哭泣发紫，在我的眼皮上有死荫。","notes":[]},{"n":17,"t":"我的手中却无强暴；我的祈祷也是清洁。","notes":[]},{"n":18,"t":"地啊，不要遮盖我的血！不要阻挡我的哀求！","notes":[]},{"n":19,"t":"现今，在天有我的见证，在上有我的中保。","notes":[]},{"n":20,"t":"我的朋友讥诮我，我却向神眼泪汪汪。","notes":[]},{"n":21,"t":"愿人得与神辩白，如同人与朋友辩白一样；","notes":[]},{"n":22,"t":"因为再过几年，我必走那往而不返之路。","notes":[]}]},"17":{"heading":"","verses":[{"n":1,"t":"我的心灵消耗，我的日子灭尽；坟墓为我预备好了。","notes":[]},{"n":2,"t":"真有戏笑我的在我这里，我眼常见他们惹动我。","notes":[]},{"n":3,"t":"愿主拿凭据给我，自己为我作保。在你以外谁肯与我击掌呢？","notes":[]},{"n":4,"t":"因你使他们心不明理，所以你必不高举他们。","notes":[]},{"n":5,"t":"控告他的朋友、以朋友为可抢夺的，连他儿女的眼睛也要失明。","notes":[]},{"n":6,"t":"神使我作了民中的笑谈；他们也吐唾沫在我脸上。","notes":[]},{"n":7,"t":"我的眼睛因忧愁昏花；我的百体好像影儿。","notes":[]},{"n":8,"t":"正直人因此必惊奇；无辜的人要兴起攻击不敬虔之辈。","notes":[]},{"n":9,"t":"然而，义人要持守所行的道；手洁的人要力上加力。","notes":[]},{"n":10,"t":"至于你们众人，可以再来辩论吧！你们中间，我找不着一个智慧人。","notes":[]},{"n":11,"t":"我的日子已经过了；我的谋算、我心所想望的已经断绝。","notes":[]},{"n":12,"t":"他们以黑夜为白昼，说：亮光近乎黑暗。","notes":[]},{"n":13,"t":"我若盼望阴间为我的房屋，若下榻在黑暗中，","notes":[]},{"n":14,"t":"若对朽坏说：你是我的父；对虫说：你是我的母亲姊妹；","notes":[]},{"n":15,"t":"这样，我的指望在哪里呢？我所指望的谁能看见呢？","notes":[]},{"n":16,"t":"等到安息在尘土中，这指望必下到阴间的门闩那里了。","notes":[]}]},"18":{"heading":"","verses":[{"n":1,"t":"书亚人比勒达回答说：","notes":[]},{"n":2,"t":"你寻索言语要到几时呢？你可以揣摩思想，然后我们就说话。","notes":[]},{"n":3,"t":"我们为何算为畜生，在你眼中看作污秽呢？","notes":[]},{"n":4,"t":"你这恼怒将自己撕裂的，难道大地为你见弃、磐石挪开原处吗？","notes":[]},{"n":5,"t":"恶人的亮光必要熄灭；他的火焰必不照耀。","notes":[]},{"n":6,"t":"他帐棚中的亮光要变为黑暗；他以上的灯也必熄灭。","notes":[]},{"n":7,"t":"他坚强的脚步必见狭窄；自己的计谋必将他绊倒。","notes":[]},{"n":8,"t":"因为他被自己的脚陷入网中，走在缠人的网罗上。","notes":[]},{"n":9,"t":"圈套必抓住他的脚跟；机关必擒获他。","notes":[]},{"n":10,"t":"活扣为他藏在土内；羁绊为他藏在路上。","notes":[]},{"n":11,"t":"四面的惊吓要使他害怕，并且追赶他的脚跟。","notes":[]},{"n":12,"t":"他的力量必因饥饿衰败；祸患要在他旁边等候。","notes":[]},{"n":13,"t":"他本身的肢体要被吞吃；死亡的长子要吞吃他的肢体。","notes":[]},{"n":14,"t":"他要从所倚靠的帐棚被拔出来，带到惊吓的王那里。","notes":[]},{"n":15,"t":"不属他的必住在他的帐棚里；硫磺必撒在他所住之处。","notes":[]},{"n":16,"t":"下边，他的根本要枯干；上边，他的枝子要剪除。","notes":[]},{"n":17,"t":"他的记念在地上必然灭亡；他的名字在街上也不存留。","notes":[]},{"n":18,"t":"他必从光明中被撵到黑暗里，必被赶出世界。","notes":[]},{"n":19,"t":"在本民中必无子无孙；在寄居之地也无一人存留。","notes":[]},{"n":20,"t":"以后来的要惊奇他的日子，好像以前去的受了惊骇。","notes":[]},{"n":21,"t":"不义之人的住处总是这样；此乃不认识神之人的地步。","notes":[]}]},"19":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"你们搅扰我的心，用言语压碎我要到几时呢？","notes":[]},{"n":3,"t":"你们这十次羞辱我；你们苦待我也不以为耻。","notes":[]},{"n":4,"t":"果真我有错，这错乃是在我。","notes":[]},{"n":5,"t":"你们果然要向我夸大，以我的羞辱为证指责我，","notes":[]},{"n":6,"t":"就该知道是神倾覆我，用网罗围绕我。","notes":[]},{"n":7,"t":"我因委曲呼叫，却不蒙应允；我呼求，却不得公断。","notes":[]},{"n":8,"t":"神用篱笆拦住我的道路，使我不得经过；又使我的路径黑暗。","notes":[]},{"n":9,"t":"他剥去我的荣光，摘去我头上的冠冕。","notes":[]},{"n":10,"t":"他在四围攻击我，我便归于死亡，将我的指望如树拔出来。","notes":[]},{"n":11,"t":"他的忿怒向我发作，以我为敌人。","notes":[]},{"n":12,"t":"他的军旅一齐上来，修筑战路攻击我，在我帐棚的四围安营。","notes":[]},{"n":13,"t":"他把我的弟兄隔在远处，使我所认识的全然与我生疏。","notes":[]},{"n":14,"t":"我的亲戚与我断绝；我的密友都忘记我。","notes":[]},{"n":15,"t":"在我家寄居的，和我的使女都以我为外人；我在他们眼中看为外邦人。","notes":[]},{"n":16,"t":"我呼唤仆人，虽用口求他，他还是不回答。","notes":[]},{"n":17,"t":"我口的气味，我妻子厌恶；我的恳求，我同胞也憎嫌。","notes":[]},{"n":18,"t":"连小孩子也藐视我；我若起来，他们都嘲笑我。","notes":[]},{"n":19,"t":"我的密友都憎恶我；我平日所爱的人向我翻脸。","notes":[]},{"n":20,"t":"我的皮肉紧贴骨头；我只剩牙皮逃脱了。","notes":[]},{"n":21,"t":"我朋友啊，可怜我！可怜我！因为神的手攻击我。","notes":[]},{"n":22,"t":"你们为什么仿佛神逼迫我，吃我的肉还以为不足呢？","notes":[]},{"n":23,"t":"惟愿我的言语现在写上，都记录在书上；","notes":[]},{"n":24,"t":"用铁笔镌刻，用铅灌在磐石上，直存到永远。","notes":[]},{"n":25,"t":"我知道我的救赎主活着，末了必站立在地上。","notes":[]},{"n":26,"t":"我这皮肉灭绝之后，我必在肉体之外得见神。","notes":[]},{"n":27,"t":"我自己要见他，亲眼要看他，并不像外人。我的心肠在我里面消灭了！","notes":[]},{"n":28,"t":"你们若说：我们逼迫他要何等地重呢？惹事的根乃在乎他；","notes":[]},{"n":29,"t":"你们就当惧怕刀剑；因为忿怒惹动刀剑的刑罚，使你们知道有报应。","notes":["原文是审判"]}]},"20":{"heading":"","verses":[{"n":1,"t":"拿玛人琐法回答说：","notes":[]},{"n":2,"t":"我心中急躁，所以我的思念叫我回答。","notes":[]},{"n":3,"t":"我已听见那羞辱我，责备我的话；我的悟性叫我回答。","notes":[]},{"n":4,"t":"你岂不知亘古以来，自从人生在地，","notes":[]},{"n":5,"t":"恶人夸胜是暂时的，不敬虔人的喜乐不过转眼之间吗？","notes":[]},{"n":6,"t":"他的尊荣虽达到天上，头虽顶到云中，","notes":[]},{"n":7,"t":"他终必灭亡，像自己的粪一样；素来见他的人要说：他在哪里呢？","notes":[]},{"n":8,"t":"他必飞去如梦，不再寻见，速被赶去，如夜间的异象。","notes":[]},{"n":9,"t":"亲眼见过他的，必不再见他；他的本处也再见不着他。","notes":[]},{"n":10,"t":"他的儿女要求穷人的恩；他的手要赔还不义之财。","notes":[]},{"n":11,"t":"他的骨头虽然有青年之力，却要和他一同躺卧在尘土中。","notes":[]},{"n":12,"t":"他口内虽以恶为甘甜，藏在舌头底下，","notes":[]},{"n":13,"t":"爱恋不舍，含在口中；","notes":[]},{"n":14,"t":"他的食物在肚里却要化为酸，在他里面成为虺蛇的恶毒。","notes":[]},{"n":15,"t":"他吞了财宝，还要吐出；神要从他腹中掏出来。","notes":[]},{"n":16,"t":"他必吸饮虺蛇的毒气；蝮蛇的舌头也必杀他。","notes":[]},{"n":17,"t":"流奶与蜜之河，他不得再见。","notes":[]},{"n":18,"t":"他劳碌得来的要赔还，不得享用；不能照所得的财货欢乐。","notes":["原文是吞下"]},{"n":19,"t":"他欺压穷人，且又离弃；强取非自己所盖的房屋 。","notes":["或译：强取房屋不得再建造"]},{"n":20,"t":"他因贪而无厌，所喜悦的连一样也不能保守。","notes":[]},{"n":21,"t":"其余的没有一样他不吞灭，所以他的福乐不能长久。","notes":[]},{"n":22,"t":"他在满足有余的时候，必到狭窄的地步；凡受苦楚的人都必加手在他身上。","notes":[]},{"n":23,"t":"他正要充满肚腹的时候，神必将猛烈的忿怒降在他身上；正在他吃饭的时候，要将这忿怒像雨降在他身上。","notes":[]},{"n":24,"t":"他要躲避铁器；铜弓的箭要将他射透。","notes":[]},{"n":25,"t":"他把箭一抽，就从他身上出来；发光的箭头从他胆中出来，有惊惶临在他身上。","notes":[]},{"n":26,"t":"他的财宝归于黑暗；人所不吹的火要把他烧灭，要把他帐棚中所剩下的烧毁。","notes":[]},{"n":27,"t":"天要显明他的罪孽；地要兴起攻击他。","notes":[]},{"n":28,"t":"他的家产必然过去；神发怒的日子，他的货物都要消灭。","notes":[]},{"n":29,"t":"这是恶人从神所得的分，是神为他所定的产业。","notes":[]}]},"21":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"你们要细听我的言语，就算是你们安慰我。","notes":[]},{"n":3,"t":"请宽容我，我又要说话；说了以后，任凭你们嗤笑吧！","notes":[]},{"n":4,"t":"我岂是向人诉冤？为何不焦急呢？","notes":[]},{"n":5,"t":"你们要看着我而惊奇，用手捂口。","notes":[]},{"n":6,"t":"我每逢思想，心就惊惶，浑身战兢。","notes":[]},{"n":7,"t":"恶人为何存活，享大寿数，势力强盛呢？","notes":[]},{"n":8,"t":"他们眼见儿孙，和他们一同坚立。","notes":[]},{"n":9,"t":"他们的家宅平安无惧；神的杖也不加在他们身上。","notes":[]},{"n":10,"t":"他们的公牛孳生而不断绝；母牛下犊而不掉胎。","notes":[]},{"n":11,"t":"他们打发小孩子出去，多如羊群；他们的儿女踊跃跳舞。","notes":[]},{"n":12,"t":"他们随着琴鼓歌唱，又因箫声欢喜。","notes":[]},{"n":13,"t":"他们度日诸事亨通，转眼下入阴间。","notes":[]},{"n":14,"t":"他们对神说：离开我们吧！我们不愿晓得你的道。","notes":[]},{"n":15,"t":"全能者是谁，我们何必事奉他呢？求告他有什么益处呢？","notes":[]},{"n":16,"t":"看哪，他们亨通不在乎自己；恶人所谋定的离我好远。","notes":[]},{"n":17,"t":"恶人的灯何尝熄灭？患难何尝临到他们呢？神何尝发怒，向他们分散灾祸呢？","notes":[]},{"n":18,"t":"他们何尝像风前的碎秸，如暴风刮去的糠秕呢？","notes":[]},{"n":19,"t":"你们说：神为恶人的儿女积蓄罪孽；我说：不如本人受报，好使他亲自知道。","notes":[]},{"n":20,"t":"愿他亲眼看见自己败亡，亲自饮全能者的忿怒。","notes":[]},{"n":21,"t":"他的岁月既尽，他还顾他本家吗？","notes":[]},{"n":22,"t":"神既审判那在高位的，谁能将知识教训他呢？","notes":[]},{"n":23,"t":"有人至死身体强壮，尽得平靖安逸；","notes":[]},{"n":24,"t":"他的奶桶充满，他的骨髓滋润。","notes":[]},{"n":25,"t":"有人至死心中痛苦，终身未尝福乐的滋味；","notes":[]},{"n":26,"t":"他们一样躺卧在尘土中，都被虫子遮盖。","notes":[]},{"n":27,"t":"我知道你们的意思，并诬害我的计谋。","notes":[]},{"n":28,"t":"你们说：霸者的房屋在哪里？恶人住过的帐棚在哪里？","notes":[]},{"n":29,"t":"你们岂没有询问过路的人吗？不知道他们所引的证据吗？","notes":[]},{"n":30,"t":"就是恶人在祸患的日子得存留，在发怒的日子得逃脱。","notes":[]},{"n":31,"t":"他所行的，有谁当面给他说明？他所做的，有谁报应他呢？","notes":[]},{"n":32,"t":"然而他要被抬到茔地；并有人看守坟墓。","notes":[]},{"n":33,"t":"他要以谷中的土块为甘甜；在他以先去的无数，在他以后去的更多。","notes":[]},{"n":34,"t":"你们对答的话中既都错谬，怎么徒然安慰我呢？","notes":[]}]},"22":{"heading":"第三次对话","verses":[{"n":1,"t":"提幔人以利法回答说：","notes":[]},{"n":2,"t":"人岂能使神有益呢？智慧人但能有益于己。","notes":[]},{"n":3,"t":"你为人公义，岂叫全能者喜悦呢？你行为完全，岂能使他得利呢？","notes":[]},{"n":4,"t":"岂是因你敬畏他就责备你、审判你吗？","notes":[]},{"n":5,"t":"你的罪恶岂不是大吗？你的罪孽也没有穷尽；","notes":[]},{"n":6,"t":"因你无故强取弟兄的物为当头，剥去贫寒人的衣服。","notes":[]},{"n":7,"t":"困乏的人，你没有给他水喝；饥饿的人，你没有给他食物。","notes":[]},{"n":8,"t":"有能力的人就得地土；尊贵的人也住在其中。","notes":[]},{"n":9,"t":"你打发寡妇空手回去，折断孤儿的膀臂。","notes":[]},{"n":10,"t":"因此，有网罗环绕你，有恐惧忽然使你惊惶；","notes":[]},{"n":11,"t":"或有黑暗蒙蔽你，并有洪水淹没你。","notes":[]},{"n":12,"t":"神岂不是在高天吗？你看星宿何其高呢！","notes":[]},{"n":13,"t":"你说：神知道什么？他岂能看透幽暗施行审判呢？","notes":[]},{"n":14,"t":"密云将他遮盖，使他不能看见；他周游穹苍。","notes":[]},{"n":15,"t":"你要依从上古的道吗？这道是恶人所行的。","notes":[]},{"n":16,"t":"他们未到死期，忽然除灭；根基毁坏，好像被江河冲去。","notes":[]},{"n":17,"t":"他们向神说：离开我们吧！又说：全能者能把我们怎么样呢？","notes":[]},{"n":18,"t":"哪知神以美物充满他们的房屋；但恶人所谋定的离我好远。","notes":[]},{"n":19,"t":"义人看见他们的结局就欢喜；无辜的人嗤笑他们，","notes":[]},{"n":20,"t":"说：那起来攻击我们的果然被剪除，其余的都被火烧灭。","notes":[]},{"n":21,"t":"你要认识神，就得平安；福气也必临到你。","notes":[]},{"n":22,"t":"你当领受他口中的教训，将他的言语存在心里。","notes":[]},{"n":23,"t":"你若归向全能者，从你帐棚中远除不义，就必得建立。","notes":[]},{"n":24,"t":"要将你的珍宝丢在尘土里，将俄斐的黄金丢在溪河石头之间；","notes":[]},{"n":25,"t":"全能者就必为你的珍宝，作你的宝银。","notes":[]},{"n":26,"t":"你就要以全能者为喜乐，向神仰起脸来。","notes":[]},{"n":27,"t":"你要祷告他，他就听你；你也要还你的愿。","notes":[]},{"n":28,"t":"你定意要做何事，必然给你成就；亮光也必照耀你的路。","notes":[]},{"n":29,"t":"人使你降卑，你仍可说：必得高升；谦卑的人，神必然拯救。","notes":[]},{"n":30,"t":"人非无辜，神且要搭救他；他因你手中清洁，必蒙拯救。","notes":[]}]},"23":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"如今我的哀告还算为悖逆；我的责罚比我的唉哼还重。","notes":[]},{"n":3,"t":"惟愿我能知道在哪里可以寻见神，能到他的台前，","notes":[]},{"n":4,"t":"我就在他面前将我的案件陈明，满口辩白。","notes":[]},{"n":5,"t":"我必知道他回答我的言语，明白他向我所说的话。","notes":[]},{"n":6,"t":"他岂用大能与我争辩吗？必不这样！他必理会我。","notes":[]},{"n":7,"t":"在他那里正直人可以与他辩论；这样，我必永远脱离那审判我的。","notes":[]},{"n":8,"t":"只是，我往前行，他不在那里，往后退，也不能见他。","notes":[]},{"n":9,"t":"他在左边行事，我却不能看见，在右边隐藏，我也不能见他。","notes":[]},{"n":10,"t":"然而他知道我所行的路；他试炼我之后，我必如精金。","notes":[]},{"n":11,"t":"我脚追随他的步履；我谨守他的道，并不偏离。","notes":[]},{"n":12,"t":"他嘴唇的命令，我未曾背弃；我看重他口中的言语，过于我需用的饮食。","notes":[]},{"n":13,"t":"只是他心志已定，谁能使他转意呢？他心里所愿的，就行出来。","notes":[]},{"n":14,"t":"他向我所定的，就必做成；这类的事他还有许多。","notes":[]},{"n":15,"t":"所以我在他面前惊惶；我思念这事便惧怕他。","notes":[]},{"n":16,"t":"神使我丧胆；全能者使我惊惶。","notes":[]},{"n":17,"t":"我的恐惧不是因为黑暗，也不是因为幽暗蒙蔽我的脸。","notes":[]}]},"24":{"heading":"","verses":[{"n":1,"t":"全能者既定期罚恶，为何不使认识他的人看见那日子呢？","notes":[]},{"n":2,"t":"有人挪移地界，抢夺群畜而牧养。","notes":[]},{"n":3,"t":"他们拉去孤儿的驴，强取寡妇的牛为当头。","notes":[]},{"n":4,"t":"他们使穷人离开正道；世上的贫民尽都隐藏。","notes":[]},{"n":5,"t":"这些贫穷人如同野驴出到旷野，殷勤寻找食物；他们靠着野地给儿女糊口，","notes":[]},{"n":6,"t":"收割别人田间的禾稼，摘取恶人余剩的葡萄，","notes":[]},{"n":7,"t":"终夜赤身无衣，天气寒冷毫无遮盖，","notes":[]},{"n":8,"t":"在山上被大雨淋湿，因没有避身之处就挨近磐石。","notes":[]},{"n":9,"t":"又有人从母怀中抢夺孤儿，强取穷人的衣服为当头，","notes":[]},{"n":10,"t":"使人赤身无衣，到处流行，且因饥饿扛抬禾捆，","notes":[]},{"n":11,"t":"在那些人的围墙内造油，榨酒，自己还口渴。","notes":[]},{"n":12,"t":"在多民的城内有人唉哼，受伤的人哀号；神却不理会那恶人的愚妄。","notes":[]},{"n":13,"t":"又有人背弃光明，不认识光明的道，不住在光明的路上。","notes":[]},{"n":14,"t":"杀人的黎明起来，杀害困苦穷乏人，夜间又作盗贼。","notes":[]},{"n":15,"t":"奸夫等候黄昏，说：必无眼能见我，就把脸蒙蔽。","notes":[]},{"n":16,"t":"盗贼黑夜挖窟窿；白日躲藏，并不认识光明。","notes":[]},{"n":17,"t":"他们看早晨如幽暗，因为他们晓得幽暗的惊骇。","notes":[]},{"n":18,"t":"这些恶人犹如浮萍快快飘去。他们所得的分在世上被咒诅；他们不得再走葡萄园的路。","notes":[]},{"n":19,"t":"干旱炎热消没雪水；阴间也如此消没犯罪之辈。","notes":[]},{"n":20,"t":"怀他的母要忘记他；虫子要吃他，觉得甘甜；他不再被人记念。不义的人必如树折断。","notes":["原文是胎"]},{"n":21,"t":"他恶待不怀孕不生养的妇人，不善待寡妇。","notes":["或译：他吞灭"]},{"n":22,"t":"然而神用能力保全有势力的人；那性命难保的人仍然兴起。","notes":[]},{"n":23,"t":"神使他们安稳，他们就有所倚靠；神的眼目也看顾他们的道路。","notes":[]},{"n":24,"t":"他们被高举，不过片时就没有了；他们降为卑，被除灭，与众人一样，又如谷穗被割。","notes":[]},{"n":25,"t":"若不是这样，谁能证实我是说谎的，将我的言语驳为虚空呢？","notes":[]}]},"25":{"heading":"","verses":[{"n":1,"t":"书亚人比勒达回答说：","notes":[]},{"n":2,"t":"神有治理之权，有威严可畏；他在高处施行和平。","notes":[]},{"n":3,"t":"他的诸军岂能数算？他的光亮一发，谁不蒙照呢？","notes":[]},{"n":4,"t":"这样在神面前，人怎能称义？妇人所生的怎能洁净？","notes":[]},{"n":5,"t":"在神眼前，月亮也无光亮，星宿也不清洁。","notes":[]},{"n":6,"t":"何况如虫的人，如蛆的世人呢！","notes":[]}]},"26":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"无能的人蒙你何等的帮助！膀臂无力的人蒙你何等的拯救！","notes":[]},{"n":3,"t":"无智慧的人蒙你何等的指教！你向他多显大知识！","notes":[]},{"n":4,"t":"你向谁发出言语来？谁的灵从你而出？","notes":[]},{"n":5,"t":"在大水和水族以下的阴魂战兢。","notes":[]},{"n":6,"t":"在神面前，阴间显露；灭亡也不得遮掩。","notes":[]},{"n":7,"t":"神将北极铺在空中，将大地悬在虚空；","notes":[]},{"n":8,"t":"将水包在密云中，云却不破裂；","notes":[]},{"n":9,"t":"遮蔽他的宝座，将云铺在其上；","notes":[]},{"n":10,"t":"在水面的周围划出界限，直到光明黑暗的交界。","notes":[]},{"n":11,"t":"天的柱子因他的斥责震动惊奇。","notes":[]},{"n":12,"t":"他以能力搅动大海；他借知识打伤拉哈伯，","notes":["或译：平静"]},{"n":13,"t":"借他的灵使天有妆饰；他的手刺杀快蛇。","notes":[]},{"n":14,"t":"看哪，这不过是神工作的些微；我们所听于他的是何等细微的声音！他大能的雷声谁能明透呢？","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"约伯接着说：","notes":[]},{"n":2,"t":"神夺去我的理，全能者使我心中愁苦。我指着永生的神起誓：","notes":[]},{"n":3,"t":"我的生命尚在我里面；神所赐呼吸之气仍在我的鼻孔内。","notes":[]},{"n":4,"t":"我的嘴决不说非义之言；我的舌也不说诡诈之语。","notes":[]},{"n":5,"t":"我断不以你们为是；我至死必不以自己为不正！","notes":[]},{"n":6,"t":"我持定我的义，必不放松；在世的日子，我心必不责备我。","notes":[]},{"n":7,"t":"愿我的仇敌如恶人一样；愿那起来攻击我的，如不义之人一般。","notes":[]},{"n":8,"t":"不敬虔的人虽然得利，神夺取其命的时候还有什么指望呢？","notes":[]},{"n":9,"t":"患难临到他，神岂能听他的呼求？","notes":[]},{"n":10,"t":"他岂以全能者为乐，随时求告神呢？","notes":[]},{"n":11,"t":"神的作为，我要指教你们；全能者所行的，我也不隐瞒。","notes":[]},{"n":12,"t":"你们自己也都见过，为何全然变为虚妄呢？","notes":[]},{"n":13,"t":"神为恶人所定的分，强暴人从全能者所得的报乃是这样：","notes":["原文是产业"]},{"n":14,"t":"倘或他的儿女增多，还是被刀所杀；他的子孙必不得饱食。","notes":[]},{"n":15,"t":"他所遗留的人必死而埋葬；他的寡妇也不哀哭。","notes":[]},{"n":16,"t":"他虽积蓄银子如尘沙，预备衣服如泥土；","notes":[]},{"n":17,"t":"他只管预备，义人却要穿上；他的银子，无辜的人要分取。","notes":[]},{"n":18,"t":"他建造房屋如虫做窝，又如守望者所搭的棚。","notes":[]},{"n":19,"t":"他虽富足躺卧，却不得收殓，转眼之间就不在了。","notes":[]},{"n":20,"t":"惊恐如波涛将他追上；暴风在夜间将他刮去。","notes":[]},{"n":21,"t":"东风把他飘去，又刮他离开本处。","notes":[]},{"n":22,"t":"神要向他射箭，并不留情；他恨不得逃脱神的手。","notes":[]},{"n":23,"t":"人要向他拍掌，并要发叱声，使他离开本处。","notes":[]}]},"28":{"heading":"歌颂智慧","verses":[{"n":1,"t":"银子有矿；炼金有方。","notes":[]},{"n":2,"t":"铁从地里挖出；铜从石中熔化。","notes":[]},{"n":3,"t":"人为黑暗定界限，查究幽暗阴翳的石头，直到极处，","notes":[]},{"n":4,"t":"在无人居住之处刨开矿穴，过路的人也想不到他们；又与人远离，悬在空中摇来摇去。","notes":[]},{"n":5,"t":"至于地，能出粮食，地内好像被火翻起来。","notes":[]},{"n":6,"t":"地中的石头有蓝宝石，并有金沙。","notes":[]},{"n":7,"t":"矿中的路鸷鸟不得知道；鹰眼也未见过。","notes":[]},{"n":8,"t":"狂傲的野兽未曾行过；猛烈的狮子也未曾经过。","notes":[]},{"n":9,"t":"人伸手凿开坚石，倾倒山根，","notes":[]},{"n":10,"t":"在磐石中凿出水道，亲眼看见各样宝物。","notes":[]},{"n":11,"t":"他封闭水不得滴流，使隐藏的物显露出来。","notes":[]},{"n":12,"t":"然而，智慧有何处可寻？聪明之处在哪里呢？","notes":[]},{"n":13,"t":"智慧的价值无人能知，在活人之地也无处可寻。","notes":[]},{"n":14,"t":"深渊说：不在我内；沧海说：不在我中。","notes":[]},{"n":15,"t":"智慧非用黄金可得，也不能平白银为它的价值。","notes":[]},{"n":16,"t":"俄斐金和贵重的红玛瑙，并蓝宝石，不足与较量；","notes":[]},{"n":17,"t":"黄金和玻璃不足与比较；精金的器皿不足与兑换。","notes":[]},{"n":18,"t":"珊瑚、水晶都不足论；智慧的价值胜过珍珠。","notes":["或译：红宝石"]},{"n":19,"t":"古实的红璧玺不足与比较；精金也不足与较量。","notes":[]},{"n":20,"t":"智慧从何处来呢？聪明之处在哪里呢？","notes":[]},{"n":21,"t":"是向一切有生命的眼目隐藏，向空中的飞鸟掩蔽。","notes":[]},{"n":22,"t":"灭没和死亡说：我们风闻其名。","notes":[]},{"n":23,"t":"神明白智慧的道路，晓得智慧的所在。","notes":[]},{"n":24,"t":"因他鉴察直到地极，遍观普天之下，","notes":[]},{"n":25,"t":"要为风定轻重，又度量诸水；","notes":[]},{"n":26,"t":"他为雨露定命令，为雷电定道路。","notes":[]},{"n":27,"t":"那时他看见智慧，而且述说；他坚定，并且查究。","notes":[]},{"n":28,"t":"他对人说：敬畏主就是智慧；远离恶便是聪明。","notes":[]}]},"29":{"heading":"约伯最后的申诉","verses":[{"n":1,"t":"约伯又接着说：","notes":[]},{"n":2,"t":"惟愿我的景况如从前的月份，如神保守我的日子。","notes":[]},{"n":3,"t":"那时他的灯照在我头上；我借他的光行过黑暗。","notes":[]},{"n":4,"t":"我愿如壮年的时候：那时我在帐棚中，神待我有密友之情；","notes":[]},{"n":5,"t":"全能者仍与我同在；我的儿女都环绕我。","notes":[]},{"n":6,"t":"奶多可洗我的脚；磐石为我出油成河。","notes":[]},{"n":7,"t":"我出到城门，在街上设立座位；","notes":[]},{"n":8,"t":"少年人见我而回避，老年人也起身站立；","notes":[]},{"n":9,"t":"王子都停止说话，用手捂口；","notes":[]},{"n":10,"t":"首领静默无声，舌头贴住上膛。","notes":[]},{"n":11,"t":"耳朵听我的，就称我有福；眼睛看我的，便称赞我；","notes":[]},{"n":12,"t":"因我拯救哀求的困苦人和无人帮助的孤儿。","notes":[]},{"n":13,"t":"将要灭亡的为我祝福；我也使寡妇心中欢乐。","notes":[]},{"n":14,"t":"我以公义为衣服，以公平为外袍和冠冕。","notes":[]},{"n":15,"t":"我为瞎子的眼，瘸子的脚。","notes":[]},{"n":16,"t":"我为穷乏人的父；素不认识的人，我查明他的案件。","notes":[]},{"n":17,"t":"我打破不义之人的牙床，从他牙齿中夺了所抢的。","notes":[]},{"n":18,"t":"我便说：我必死在家中，必增添我的日子，多如尘沙。","notes":["原文是窝中"]},{"n":19,"t":"我的根长到水边；露水终夜沾在我的枝上。","notes":[]},{"n":20,"t":"我的荣耀在身上增新；我的弓在手中日强。","notes":[]},{"n":21,"t":"人听见我而仰望，静默等候我的指教。","notes":[]},{"n":22,"t":"我说话之后，他们就不再说；我的言语像雨露滴在他们身上。","notes":[]},{"n":23,"t":"他们仰望我如仰望雨，又张开口如切慕春雨。","notes":[]},{"n":24,"t":"他们不敢自信，我就向他们含笑；他们不使我脸上的光改变。","notes":[]},{"n":25,"t":"我为他们选择道路，又坐首位；我如君王在军队中居住，又如吊丧的安慰伤心的人。","notes":[]}]},"30":{"heading":"","verses":[{"n":1,"t":"但如今，比我年少的人戏笑我；其人之父我曾藐视，不肯安在看守我羊群的狗中。","notes":[]},{"n":2,"t":"他们壮年的气力既已衰败，其手之力与我何益呢？","notes":[]},{"n":3,"t":"他们因穷乏饥饿，身体枯瘦，在荒废凄凉的幽暗中啃干燥之地，","notes":[]},{"n":4,"t":"在草丛之中采咸草，罗腾的根为他们的食物。","notes":["小树名，松类"]},{"n":5,"t":"他们从人中被赶出；人追喊他们如贼一般，","notes":[]},{"n":6,"t":"以致他们住在荒谷之间，在地洞和岩穴中；","notes":[]},{"n":7,"t":"在草丛中叫唤，在荆棘下聚集。","notes":[]},{"n":8,"t":"这都是愚顽下贱人的儿女；他们被鞭打，赶出境外。","notes":[]},{"n":9,"t":"现在这些人以我为歌曲，以我为笑谈。","notes":[]},{"n":10,"t":"他们厌恶我，躲在旁边站着，不住地吐唾沫在我脸上。","notes":[]},{"n":11,"t":"松开他们的绳索苦待我，在我面前脱去辔头。","notes":[]},{"n":12,"t":"这等下流人在我右边起来，推开我的脚，筑成战路来攻击我。","notes":[]},{"n":13,"t":"这些无人帮助的，毁坏我的道，加增我的灾。","notes":[]},{"n":14,"t":"他们来如同闯进大破口，在毁坏之间滚在我身上。","notes":[]},{"n":15,"t":"惊恐临到我，驱逐我的尊荣如风；我的福禄如云过去。","notes":[]},{"n":16,"t":"现在我心极其悲伤；困苦的日子将我抓住。","notes":[]},{"n":17,"t":"夜间，我里面的骨头刺我，疼痛不止，好像啃我。","notes":[]},{"n":18,"t":"因神的大力，我的外衣污秽不堪，又如里衣的领子将我缠住。","notes":[]},{"n":19,"t":"神把我扔在淤泥中，我就像尘土和炉灰一般。","notes":[]},{"n":20,"t":"主啊，我呼求你，你不应允我；我站起来，你就定睛看我。","notes":[]},{"n":21,"t":"你向我变心，待我残忍，又用大能追逼我，","notes":[]},{"n":22,"t":"把我提在风中，使我驾风而行，又使我消灭在烈风中。","notes":[]},{"n":23,"t":"我知道要使我临到死地，到那为众生所定的阴宅。","notes":[]},{"n":24,"t":"然而，人仆倒岂不伸手？遇灾难岂不求救呢？","notes":[]},{"n":25,"t":"人遭难，我岂不为他哭泣呢？人穷乏，我岂不为他忧愁呢？","notes":[]},{"n":26,"t":"我仰望得好处，灾祸就到了；我等待光明，黑暗便来了。","notes":[]},{"n":27,"t":"我心里烦扰不安，困苦的日子临到我身。","notes":[]},{"n":28,"t":"我没有日光就哀哭行去 ；我在会中站着求救。","notes":["或译：我面发黑并非因日晒"]},{"n":29,"t":"我与野狗为弟兄，与鸵鸟为同伴。","notes":[]},{"n":30,"t":"我的皮肤黑而脱落；我的骨头因热烧焦。","notes":[]},{"n":31,"t":"所以，我的琴音变为悲音；我的箫声变为哭声。","notes":[]}]},"31":{"heading":"","verses":[{"n":1,"t":"我与眼睛立约，怎能恋恋瞻望处女呢？","notes":[]},{"n":2,"t":"从至上的神所得之分，从至高全能者所得之业是什么呢？","notes":[]},{"n":3,"t":"岂不是祸患临到不义的，灾害临到作孽的呢？","notes":[]},{"n":4,"t":"神岂不是察看我的道路，数点我的脚步呢？","notes":[]},{"n":5,"t":"我若与虚谎同行，脚若追随诡诈；","notes":[]},{"n":6,"t":"我若被公道的天平称度，使神可以知道我的纯正；）","notes":[]},{"n":7,"t":"我的脚步若偏离正路，我的心若随着我的眼目，若有玷污粘在我手上；","notes":[]},{"n":8,"t":"就愿我所种的有别人吃，我田所产的被拔出来。","notes":[]},{"n":9,"t":"我若受迷惑，向妇人起淫念，在邻舍的门外蹲伏，","notes":[]},{"n":10,"t":"就愿我的妻子给别人推磨，别人也与她同室。","notes":[]},{"n":11,"t":"因为这是大罪，是审判官当罚的罪孽。","notes":[]},{"n":12,"t":"这本是火焚烧，直到毁灭，必拔除我所有的家产。","notes":[]},{"n":13,"t":"我的仆婢与我争辩的时候，我若藐视不听他们的情节；","notes":[]},{"n":14,"t":"神兴起，我怎样行呢？他察问，我怎样回答呢？","notes":[]},{"n":15,"t":"造我在腹中的，不也是造他吗？将他与我抟在腹中的岂不是一位吗？","notes":[]},{"n":16,"t":"我若不容贫寒人得其所愿，或叫寡妇眼中失望，","notes":[]},{"n":17,"t":"或独自吃我一点食物，孤儿没有与我同吃；","notes":[]},{"n":18,"t":"从幼年时孤儿与我同长，好像父子一样；我从出母腹就扶助寡妇。）","notes":["原文是引领"]},{"n":19,"t":"我若见人因无衣死亡，或见穷乏人身无遮盖；","notes":[]},{"n":20,"t":"我若不使他因我羊的毛得暖，为我祝福；","notes":[]},{"n":21,"t":"我若在城门口见有帮助我的，举手攻击孤儿；","notes":[]},{"n":22,"t":"情愿我的肩头从缺盆骨脱落，我的膀臂从羊矢骨折断。","notes":[]},{"n":23,"t":"因神降的灾祸使我恐惧；因他的威严，我不能妄为。","notes":[]},{"n":24,"t":"我若以黄金为指望，对精金说：你是我的倚靠；","notes":[]},{"n":25,"t":"我若因财物丰裕，因我手多得资财而欢喜；","notes":[]},{"n":26,"t":"我若见太阳发光，明月行在空中，","notes":[]},{"n":27,"t":"心就暗暗被引诱，口便亲手；","notes":[]},{"n":28,"t":"这也是审判官当罚的罪孽，又是我背弃在上的神。","notes":[]},{"n":29,"t":"我若见恨我的遭报就欢喜，见他遭灾便高兴；","notes":[]},{"n":30,"t":"我没有容口犯罪，咒诅他的生命；）","notes":[]},{"n":31,"t":"若我帐棚的人未尝说，谁不以主人的食物吃饱呢？","notes":[]},{"n":32,"t":"从来我没有容客旅在街上住宿，却开门迎接行路的人；）","notes":[]},{"n":33,"t":"我若像亚当遮掩我的过犯，将罪孽藏在怀中；","notes":["或译：别人"]},{"n":34,"t":"因惧怕大众，又因宗族藐视我使我惊恐，以致闭口无言，杜门不出；","notes":[]},{"n":35,"t":"惟愿有一位肯听我！（看哪，在这里有我所划的押，愿全能者回答我！）","notes":[]},{"n":36,"t":"愿那敌我者所写的状词在我这里！我必带在肩上，又绑在头上为冠冕。","notes":[]},{"n":37,"t":"我必向他述说我脚步的数目，必如君王进到他面前。","notes":[]},{"n":38,"t":"我若夺取田地，这地向我喊冤，犁沟一同哭泣；","notes":[]},{"n":39,"t":"我若吃地的出产不给价值，或叫原主丧命；","notes":[]},{"n":40,"t":"愿这地长蒺藜代替麦子，长恶草代替大麦。约伯的话说完了。","notes":[]}]},"32":{"heading":"以利户的话","verses":[{"n":1,"t":"于是这三个人，因约伯自以为义就不再回答他。","notes":[]},{"n":2,"t":"那时有布西人兰族巴拉迦的儿子以利户向约伯发怒；因约伯自以为义，不以神为义。","notes":[]},{"n":3,"t":"他又向约伯的三个朋友发怒；因为他们想不出回答的话来，仍以约伯为有罪。","notes":[]},{"n":4,"t":"以利户要与约伯说话，就等候他们，因为他们比自己年老。","notes":[]},{"n":5,"t":"以利户见这三个人口中无话回答，就怒气发作。","notes":[]},{"n":6,"t":"布西人巴拉迦的儿子以利户回答说：我年轻，你们老迈；因此我退让，不敢向你们陈说我的意见。","notes":[]},{"n":7,"t":"我说，年老的当先说话；寿高的当以智慧教训人。","notes":[]},{"n":8,"t":"但在人里面有灵；全能者的气使人有聪明。","notes":[]},{"n":9,"t":"尊贵的不都有智慧；寿高的不都能明白公平。","notes":[]},{"n":10,"t":"因此我说：你们要听我言；我也要陈说我的意见。","notes":[]},{"n":11,"t":"你们查究所要说的话；那时我等候你们的话，侧耳听你们的辩论，","notes":[]},{"n":12,"t":"留心听你们；谁知你们中间无一人折服约伯，驳倒他的话。","notes":[]},{"n":13,"t":"你们切不可说：我们寻得智慧；神能胜他，人却不能。","notes":[]},{"n":14,"t":"约伯没有向我争辩；我也不用你们的话回答他。","notes":[]},{"n":15,"t":"他们惊奇不再回答，一言不发。","notes":[]},{"n":16,"t":"我岂因他们不说话，站住不再回答，仍旧等候呢？","notes":[]},{"n":17,"t":"我也要回答我的一分话，陈说我的意见。","notes":[]},{"n":18,"t":"因为我的言语满怀；我里面的灵激动我。","notes":[]},{"n":19,"t":"我的胸怀如盛酒之囊没有出气之缝，又如新皮袋快要破裂。","notes":[]},{"n":20,"t":"我要说话，使我舒畅；我要开口回答。","notes":[]},{"n":21,"t":"我必不看人的情面，也不奉承人。","notes":[]},{"n":22,"t":"我不晓得奉承；若奉承，造我的主必快快除灭我。","notes":[]}]},"33":{"heading":"","verses":[{"n":1,"t":"约伯啊，请听我的话，留心听我一切的言语。","notes":[]},{"n":2,"t":"我现在开口，用舌发言。","notes":[]},{"n":3,"t":"我的言语要发明心中所存的正直；我所知道的，我嘴唇要诚实地说出。","notes":[]},{"n":4,"t":"神的灵造我；全能者的气使我得生。","notes":[]},{"n":5,"t":"你若回答我，就站起来，在我面前陈明。","notes":[]},{"n":6,"t":"我在神面前与你一样，也是用土造成。","notes":[]},{"n":7,"t":"我不用威严惊吓你，也不用势力重压你。","notes":[]},{"n":8,"t":"你所说的，我听见了，也听见你的言语，说：","notes":[]},{"n":9,"t":"我是清洁无过的，我是无辜的；在我里面也没有罪孽。","notes":[]},{"n":10,"t":"神找机会攻击我，以我为仇敌，","notes":[]},{"n":11,"t":"把我的脚上了木狗，窥察我一切的道路。","notes":[]},{"n":12,"t":"我要回答你说：你这话无理，因神比世人更大。","notes":[]},{"n":13,"t":"你为何与他争论呢？因他的事都不对人解说？","notes":[]},{"n":14,"t":"神说一次、两次，世人却不理会。","notes":[]},{"n":15,"t":"人躺在床上沉睡的时候，神就用梦和夜间的异象，","notes":[]},{"n":16,"t":"开通他们的耳朵，将当受的教训印在他们心上，","notes":[]},{"n":17,"t":"好叫人不从自己的谋算，不行骄傲的事，","notes":["原文是将骄傲向人隐藏"]},{"n":18,"t":"拦阻人不陷于坑里，不死在刀下。","notes":[]},{"n":19,"t":"人在床上被惩治，骨头中不住地疼痛，","notes":[]},{"n":20,"t":"以致他的口厌弃食物，心厌恶美味。","notes":[]},{"n":21,"t":"他的肉消瘦，不得再见；先前不见的骨头都凸出来。","notes":[]},{"n":22,"t":"他的灵魂临近深坑；他的生命近于灭命的。","notes":[]},{"n":23,"t":"一千天使中，若有一个作传话的与神同在，指示人所当行的事，","notes":[]},{"n":24,"t":"神就给他开恩，说：救赎他免得下坑；我已经得了赎价。","notes":[]},{"n":25,"t":"他的肉要比孩童的肉更嫩；他就返老还童。","notes":[]},{"n":26,"t":"他祷告神，神就喜悦他，使他欢呼朝见神的面；神又看他为义。","notes":[]},{"n":27,"t":"他在人前歌唱说：我犯了罪，颠倒是非，这竟与我无益。","notes":[]},{"n":28,"t":"神救赎我的灵魂免入深坑；我的生命也必见光。","notes":[]},{"n":29,"t":"神两次、三次向人行这一切的事，","notes":[]},{"n":30,"t":"为要从深坑救回人的灵魂，使他被光照耀，与活人一样。","notes":[]},{"n":31,"t":"约伯啊，你当侧耳听我的话，不要作声，等我讲说。","notes":[]},{"n":32,"t":"你若有话说，就可以回答我；你只管说，因我愿以你为是。","notes":[]},{"n":33,"t":"若不然，你就听我说；你不要作声，我便将智慧教训你。","notes":[]}]},"34":{"heading":"","verses":[{"n":1,"t":"以利户又说：","notes":[]},{"n":2,"t":"你们智慧人要听我的话；有知识的人要留心听我说。","notes":[]},{"n":3,"t":"因为耳朵试验话语，好像上膛尝食物。","notes":[]},{"n":4,"t":"我们当选择何为是，彼此知道何为善。","notes":[]},{"n":5,"t":"约伯曾说：我是公义，神夺去我的理；","notes":[]},{"n":6,"t":"我虽有理，还算为说谎言的；我虽无过，受的伤还不能医治。","notes":[]},{"n":7,"t":"谁像约伯，喝讥诮如同喝水呢？","notes":[]},{"n":8,"t":"他与作孽的结伴，和恶人同行。","notes":[]},{"n":9,"t":"他说：人以神为乐，总是无益。","notes":[]},{"n":10,"t":"所以，你们明理的人要听我的话。神断不致行恶；全能者断不致作孽。","notes":[]},{"n":11,"t":"他必按人所做的报应人，使各人照所行的得报。","notes":[]},{"n":12,"t":"神必不作恶；全能者也不偏离公平。","notes":[]},{"n":13,"t":"谁派他治理地，安定全世界呢？","notes":[]},{"n":14,"t":"他若专心为己，将灵和气收归自己，","notes":[]},{"n":15,"t":"凡有血气的就必一同死亡；世人必仍归尘土。","notes":[]},{"n":16,"t":"你若明理，就当听我的话，留心听我言语的声音。","notes":[]},{"n":17,"t":"难道恨恶公平的可以掌权吗？那有公义的、有大能的，岂可定他有罪吗？","notes":[]},{"n":18,"t":"他对君王说：你是鄙陋的；对贵臣说：你是邪恶的。","notes":[]},{"n":19,"t":"他待王子不徇情面，也不看重富足的过于贫穷的，因为都是他手所造。","notes":[]},{"n":20,"t":"在转眼之间，半夜之中，他们就死亡。百姓被震动而去世；有权力的被夺去非借人手。","notes":[]},{"n":21,"t":"神注目观看人的道路，看明人的脚步。","notes":[]},{"n":22,"t":"没有黑暗、阴翳能给作孽的藏身。","notes":[]},{"n":23,"t":"神审判人，不必使人到他面前再三鉴察。","notes":[]},{"n":24,"t":"他用难测之法打破有能力的人，设立别人代替他们。","notes":[]},{"n":25,"t":"他原知道他们的行为，使他们在夜间倾倒灭亡。","notes":[]},{"n":26,"t":"他在众人眼前击打他们，如同击打恶人一样。","notes":[]},{"n":27,"t":"因为他们偏行不跟从他，也不留心他的道，","notes":[]},{"n":28,"t":"甚至使贫穷人的哀声达到他那里；他也听了困苦人的哀声。","notes":[]},{"n":29,"t":"他使人安静，谁能扰乱呢？他掩面，谁能见他呢？无论待一国或一人都是如此—","notes":["或译：定罪"]},{"n":30,"t":"使不虔敬的人不得作王，免得有人牢笼百姓。","notes":[]},{"n":31,"t":"有谁对神说：我受了责罚，不再犯罪；","notes":[]},{"n":32,"t":"我所看不明的，求你指教我；我若作了孽，必不再作？","notes":[]},{"n":33,"t":"他施行报应，岂要随你的心愿、叫你推辞不受吗？选定的是你，不是我。你所知道的只管说吧！","notes":[]},{"n":34,"t":"明理的人和听我话的智慧人必对我说：","notes":[]},{"n":35,"t":"约伯说话没有知识，言语中毫无智慧。","notes":[]},{"n":36,"t":"愿约伯被试验到底，因他回答像恶人一样。","notes":[]},{"n":37,"t":"他在罪上又加悖逆；在我们中间拍手，用许多言语轻慢神。","notes":[]}]},"35":{"heading":"","verses":[{"n":1,"t":"以利户又说：","notes":[]},{"n":2,"t":"你以为有理，或以为你的公义胜于神的公义，","notes":[]},{"n":3,"t":"才说这与我有什么益处？我不犯罪比犯罪有什么好处呢？","notes":[]},{"n":4,"t":"我要回答你和在你这里的朋友。","notes":[]},{"n":5,"t":"你要向天观看，瞻望那高于你的穹苍。","notes":[]},{"n":6,"t":"你若犯罪，能使神受何害呢？你的过犯加增，能使神受何损呢？","notes":[]},{"n":7,"t":"你若是公义，还能加增他什么呢？他从你手里还接受什么呢？","notes":[]},{"n":8,"t":"你的过恶或能害你这类的人；你的公义或能叫世人得益处。","notes":[]},{"n":9,"t":"人因多受欺压就哀求，因受能者的辖制便求救，","notes":["原文是膀臂"]},{"n":10,"t":"却无人说：造我的神在哪里？他使人夜间歌唱，","notes":[]},{"n":11,"t":"教训我们胜于地上的走兽，使我们有聪明胜于空中的飞鸟。","notes":[]},{"n":12,"t":"他们在那里，因恶人的骄傲呼求，却无人答应。","notes":[]},{"n":13,"t":"虚妄的呼求，神必不垂听；全能者也必不眷顾。","notes":[]},{"n":14,"t":"何况你说，你不得见他；你的案件在他面前，你等候他吧。","notes":[]},{"n":15,"t":"但如今因他未曾发怒降罚，也不甚理会狂傲，","notes":[]},{"n":16,"t":"所以约伯开口说虚妄的话，多发无知识的言语。","notes":[]}]},"36":{"heading":"","verses":[{"n":1,"t":"以利户又接着说：","notes":[]},{"n":2,"t":"你再容我片时，我就指示你，因我还有话为神说。","notes":[]},{"n":3,"t":"我要将所知道的从远处引来，将公义归给造我的主。","notes":[]},{"n":4,"t":"我的言语真不虚谎；有知识全备的与你同在。","notes":[]},{"n":5,"t":"神有大能，并不藐视人；他的智慧甚广。","notes":[]},{"n":6,"t":"他不保护恶人的性命，却为困苦人伸冤。","notes":[]},{"n":7,"t":"他时常看顾义人，使他们和君王同坐宝座，永远要被高举。","notes":[]},{"n":8,"t":"他们若被锁链捆住，被苦难的绳索缠住，","notes":[]},{"n":9,"t":"他就把他们的作为和过犯指示他们，叫他们知道有骄傲的行动。","notes":[]},{"n":10,"t":"他也开通他们的耳朵得受教训，吩咐他们离开罪孽转回。","notes":[]},{"n":11,"t":"他们若听从事奉他，就必度日亨通，历年福乐；","notes":[]},{"n":12,"t":"若不听从，就要被刀杀灭，无知无识而死。","notes":[]},{"n":13,"t":"那心中不敬虔的人积蓄怒气；神捆绑他们，他们竟不求救；","notes":[]},{"n":14,"t":"必在青年时死亡，与污秽人一样丧命。","notes":[]},{"n":15,"t":"神借着困苦救拔困苦人，趁他们受欺压开通他们的耳朵。","notes":[]},{"n":16,"t":"神也必引你出离患难，进入宽阔不狭窄之地；摆在你席上的必满有肥甘。","notes":[]},{"n":17,"t":"但你满口有恶人批评的言语；判断和刑罚抓住你。","notes":[]},{"n":18,"t":"不可容忿怒触动你，使你不服责罚；也不可因赎价大就偏行。","notes":[]},{"n":19,"t":"你的呼求，或是你一切的势力，果有灵验，叫你不受患难吗？","notes":["或译：资财"]},{"n":20,"t":"不要切慕黑夜，就是众民在本处被除灭的时候。","notes":[]},{"n":21,"t":"你要谨慎，不可重看罪孽，因你选择罪孽过于选择苦难。","notes":[]},{"n":22,"t":"神行事有高大的能力；教训人的有谁像他呢？","notes":[]},{"n":23,"t":"谁派定他的道路？谁能说：你所行的不义？","notes":[]},{"n":24,"t":"你不可忘记称赞他所行的为大，就是人所歌颂的。","notes":[]},{"n":25,"t":"他所行的，万人都看见；世人也从远处观看。","notes":[]},{"n":26,"t":"神为大，我们不能全知；他的年数不能测度。","notes":[]},{"n":27,"t":"他吸取水点，这水点从云雾中就变成雨；","notes":[]},{"n":28,"t":"云彩将雨落下，沛然降与世人。","notes":[]},{"n":29,"t":"谁能明白云彩如何铺张，和神行宫的雷声呢？","notes":[]},{"n":30,"t":"他将亮光普照在自己的四围；他又遮覆海底。","notes":[]},{"n":31,"t":"他用这些审判众民，且赐丰富的粮食。","notes":[]},{"n":32,"t":"他以电光遮手，命闪电击中敌人。","notes":["或译：中了靶子"]},{"n":33,"t":"所发的雷声显明他的作为，又向牲畜指明要起暴风。","notes":[]}]},"37":{"heading":"","verses":[{"n":1,"t":"因此我心战兢，从原处移动。","notes":[]},{"n":2,"t":"听啊，神轰轰的声音是他口中所发的响声。","notes":[]},{"n":3,"t":"他发响声震遍天下，发电光闪到地极。","notes":[]},{"n":4,"t":"随后人听见有雷声轰轰，大发威严，雷电接连不断。","notes":[]},{"n":5,"t":"神发出奇妙的雷声；他行大事，我们不能测透。","notes":[]},{"n":6,"t":"他对雪说：要降在地上；对大雨和暴雨也是这样说。","notes":[]},{"n":7,"t":"他封住各人的手，叫所造的万人都晓得他的作为。","notes":[]},{"n":8,"t":"百兽进入穴中，卧在洞内。","notes":[]},{"n":9,"t":"暴风出于南宫；寒冷出于北方。","notes":[]},{"n":10,"t":"神嘘气成冰；宽阔之水也都凝结。","notes":[]},{"n":11,"t":"他使密云盛满水气，布散电光之云；","notes":[]},{"n":12,"t":"这云是借他的指引游行旋转，得以在全地面上行他一切所吩咐的，","notes":[]},{"n":13,"t":"或为责罚，或为润地，或为施行慈爱。","notes":[]},{"n":14,"t":"约伯啊，你要留心听，要站立思想神奇妙的作为。","notes":[]},{"n":15,"t":"神如何吩咐这些，如何使云中的电光照耀，你知道吗？","notes":[]},{"n":16,"t":"云彩如何浮于空中，那知识全备者奇妙的作为，你知道吗？","notes":[]},{"n":17,"t":"南风使地寂静，你的衣服就如火热，你知道吗？","notes":[]},{"n":18,"t":"你岂能与神同铺穹苍吗？这穹苍坚硬，如同铸成的镜子。","notes":[]},{"n":19,"t":"我们愚昧不能陈说；请你指教我们该对他说什么话。","notes":[]},{"n":20,"t":"人岂可说：我愿与他说话？岂有人自愿灭亡吗？","notes":[]},{"n":21,"t":"现在有云遮蔽，人不得见穹苍的光亮；但风吹过，天又发晴。","notes":[]},{"n":22,"t":"金光出于北方，在神那里有可怕的威严。","notes":[]},{"n":23,"t":"论到全能者，我们不能测度；他大有能力，有公平和大义，必不苦待人。","notes":[]},{"n":24,"t":"所以，人敬畏他；凡自以为心中有智慧的人，他都不顾念。","notes":[]}]},"38":{"heading":"耶和华回答约伯","verses":[{"n":1,"t":"那时，耶和华从旋风中回答约伯说：","notes":[]},{"n":2,"t":"谁用无知的言语使我的旨意暗昧不明？","notes":[]},{"n":3,"t":"你要如勇士束腰；我问你，你可以指示我。","notes":[]},{"n":4,"t":"我立大地根基的时候，你在哪里呢？你若有聪明，只管说吧！","notes":[]},{"n":5,"t":"你若晓得就说，是谁定地的尺度？是谁把准绳拉在其上？","notes":[]},{"n":6,"t":"地的根基安置在何处？地的角石是谁安放的？","notes":[]},{"n":7,"t":"那时，晨星一同歌唱；神的众子也都欢呼。","notes":[]},{"n":8,"t":"海水冲出，如出胎胞，那时谁将它关闭呢？","notes":[]},{"n":9,"t":"是我用云彩当海的衣服，用幽暗当包裹它的布，","notes":[]},{"n":10,"t":"为它定界限，又安门和闩，","notes":[]},{"n":11,"t":"说：你只可到这里，不可越过；你狂傲的浪要到此止住。","notes":[]},{"n":12,"t":"你自生以来，曾命定晨光，使清晨的日光知道本位，","notes":[]},{"n":13,"t":"叫这光普照地的四极，将恶人从其中驱逐出来吗？","notes":[]},{"n":14,"t":"因这光，地面改变如泥上印印，万物出现如衣服一样。","notes":[]},{"n":15,"t":"亮光不照恶人；强横的膀臂也必折断。","notes":[]},{"n":16,"t":"你曾进到海源，或在深渊的隐密处行走吗？","notes":[]},{"n":17,"t":"死亡的门曾向你显露吗？死荫的门你曾见过吗？","notes":[]},{"n":18,"t":"地的广大你能明透吗？你若全知道，只管说吧！","notes":[]},{"n":19,"t":"光明的居所从何而至？黑暗的本位在于何处？","notes":[]},{"n":20,"t":"你能带到本境，能看明其室之路吗？","notes":[]},{"n":21,"t":"你总知道，因为你早已生在世上，你日子的数目也多。","notes":[]},{"n":22,"t":"你曾进入雪库，或见过雹仓吗？","notes":[]},{"n":23,"t":"这雪雹乃是我为降灾，并打仗和争战的日子所预备的。","notes":[]},{"n":24,"t":"光亮从何路分开？东风从何路分散遍地？","notes":[]},{"n":25,"t":"谁为雨水分道？谁为雷电开路？","notes":[]},{"n":26,"t":"使雨降在无人之地、无人居住的旷野？","notes":[]},{"n":27,"t":"使荒废凄凉之地得以丰足，青草得以发生？","notes":[]},{"n":28,"t":"雨有父吗？露水珠是谁生的呢？","notes":[]},{"n":29,"t":"冰出于谁的胎？天上的霜是谁生的呢？","notes":[]},{"n":30,"t":"诸水坚硬如石头；深渊之面凝结成冰。","notes":["或译：隐藏"]},{"n":31,"t":"你能系住昴星的结吗？能解开参星的带吗？","notes":[]},{"n":32,"t":"你能按时领出十二宫吗？能引导北斗和随它的众星吗？","notes":["星：原文是子"]},{"n":33,"t":"你知道天的定例吗？能使地归在天的权下吗？","notes":[]},{"n":34,"t":"你能向云彩扬起声来，使倾盆的雨遮盖你吗？","notes":[]},{"n":35,"t":"你能发出闪电，叫它行去，使它对你说：我们在这里？","notes":[]},{"n":36,"t":"谁将智慧放在怀中？谁将聪明赐于心内？","notes":[]},{"n":37,"t":"谁能用智慧数算云彩呢？尘土聚集成团，土块紧紧结连；那时，谁能倾倒天上的瓶呢？","notes":[],"end":38},{"n":39,"t":"母狮子在洞中蹲伏，少壮狮子在隐密处埋伏；你能为它们抓取食物，使它们饱足吗？","notes":[],"end":40},{"n":41,"t":"乌鸦之雏因无食物飞来飞去，哀告神；那时，谁为它预备食物呢？","notes":[]}]},"39":{"heading":"","verses":[{"n":1,"t":"山岩间的野山羊几时生产，你知道吗？母鹿下犊之期，你能察定吗？","notes":[]},{"n":2,"t":"它们怀胎的月数，你能数算吗？它们几时生产，你能晓得吗？","notes":[]},{"n":3,"t":"它们屈身，将子生下，就除掉疼痛。","notes":[]},{"n":4,"t":"这子渐渐肥壮，在荒野长大，去而不回。","notes":[]},{"n":5,"t":"谁放野驴出去自由？谁解开快驴的绳索？","notes":[]},{"n":6,"t":"我使旷野作它的住处，使咸地当它的居所。","notes":[]},{"n":7,"t":"它嗤笑城内的喧嚷，不听赶牲口的喝声。","notes":[]},{"n":8,"t":"遍山是它的草场；它寻找各样青绿之物。","notes":[]},{"n":9,"t":"野牛岂肯服事你？岂肯住在你的槽旁？","notes":[]},{"n":10,"t":"你岂能用套绳将野牛笼在犁沟之间？它岂肯随你耙山谷之地？","notes":[]},{"n":11,"t":"岂可因它的力大就倚靠它？岂可把你的工交给它做吗？","notes":[]},{"n":12,"t":"岂可信靠它把你的粮食运到家，又收聚你禾场上的谷吗？","notes":[]},{"n":13,"t":"鸵鸟的翅膀欢然搧展，岂是显慈爱的翎毛和羽毛吗？","notes":[]},{"n":14,"t":"因它把蛋留在地上，在尘土中使得温暖；","notes":[]},{"n":15,"t":"却想不到被脚踹碎，或被野兽践踏。","notes":[]},{"n":16,"t":"它忍心待雏，似乎不是自己的；虽然徒受劳苦，也不为雏惧怕；","notes":[]},{"n":17,"t":"因为神使它没有智慧，也未将悟性赐给它。","notes":[]},{"n":18,"t":"它几时挺身展开翅膀，就嗤笑马和骑马的人。","notes":[]},{"n":19,"t":"马的大力是你所赐的吗？它颈项上挓挲的鬃是你给它披上的吗？","notes":[]},{"n":20,"t":"是你叫它跳跃像蝗虫吗？它喷气之威使人惊惶。","notes":[]},{"n":21,"t":"它在谷中刨地，自喜其力；它出去迎接佩带兵器的人。","notes":[]},{"n":22,"t":"它嗤笑可怕的事并不惊惶，也不因刀剑退回。","notes":[]},{"n":23,"t":"箭袋和发亮的枪，并短枪在它身上铮铮有声。","notes":[]},{"n":24,"t":"它发猛烈的怒气将地吞下；一听角声就不耐站立。","notes":[]},{"n":25,"t":"角每发声，它说呵哈；它从远处闻着战气，又听见军长大发雷声和兵丁呐喊。","notes":[]},{"n":26,"t":"鹰雀飞翔，展开翅膀一直向南，岂是借你的智慧吗？","notes":[]},{"n":27,"t":"大鹰上腾在高处搭窝，岂是听你的吩咐吗？","notes":[]},{"n":28,"t":"它住在山岩，以山峰和坚固之所为家，","notes":[]},{"n":29,"t":"从那里窥看食物，眼睛远远观望。","notes":[]},{"n":30,"t":"它的雏也咂血；被杀的人在哪里，它也在那里。","notes":[]}]},"40":{"heading":"","verses":[{"n":1,"t":"耶和华又对约伯说：","notes":[]},{"n":2,"t":"强辩的岂可与全能者争论吗？与神辩驳的可以回答这些吧！","notes":[]},{"n":3,"t":"于是，约伯回答耶和华说：","notes":[]},{"n":4,"t":"我是卑贱的！我用什么回答你呢？只好用手捂口。","notes":[]},{"n":5,"t":"我说了一次，再不回答；说了两次，就不再说。","notes":[]},{"n":6,"t":"于是，耶和华从旋风中回答约伯说：","notes":[]},{"n":7,"t":"你要如勇士束腰；我问你，你可以指示我。","notes":[]},{"n":8,"t":"你岂可废弃我所拟定的？岂可定我有罪，好显自己为义吗？","notes":[]},{"n":9,"t":"你有神那样的膀臂吗？你能像他发雷声吗？","notes":[]},{"n":10,"t":"你要以荣耀庄严为妆饰，以尊荣威严为衣服；","notes":[]},{"n":11,"t":"要发出你满溢的怒气，见一切骄傲的人，使他降卑；","notes":[]},{"n":12,"t":"见一切骄傲的人，将他制伏，把恶人践踏在本处；","notes":[]},{"n":13,"t":"将他们一同隐藏在尘土中，把他们的脸蒙蔽在隐密处；","notes":[]},{"n":14,"t":"我就认你右手能以救自己。","notes":[]},{"n":15,"t":"你且观看河马；我造你也造它。它吃草与牛一样；","notes":[]},{"n":16,"t":"它的气力在腰间，能力在肚腹的筋上。","notes":[]},{"n":17,"t":"它摇动尾巴如香柏树；它大腿的筋互相联络。","notes":[]},{"n":18,"t":"它的骨头好像铜管；它的肢体仿佛铁棍。","notes":[]},{"n":19,"t":"它在神所造的物中为首；创造它的给它刀剑。","notes":[]},{"n":20,"t":"诸山给它出食物，也是百兽游玩之处。","notes":[]},{"n":21,"t":"它伏在莲叶之下，卧在芦苇隐密处和水洼子里。","notes":[]},{"n":22,"t":"莲叶的阴凉遮蔽它；溪旁的柳树环绕它。","notes":[]},{"n":23,"t":"河水泛滥，它不发战；就是约旦河的水涨到它口边，也是安然。","notes":[]},{"n":24,"t":"在它防备的时候，谁能捉拿它？谁能牢笼它穿它的鼻子呢？","notes":[]}]},"41":{"heading":"","verses":[{"n":1,"t":"你能用鱼钩钓上鳄鱼吗？能用绳子压下它的舌头吗？","notes":[]},{"n":2,"t":"你能用绳索穿它的鼻子吗？能用钩穿它的腮骨吗？","notes":[]},{"n":3,"t":"它岂向你连连恳求，说柔和的话吗？","notes":[]},{"n":4,"t":"岂肯与你立约，使你拿它永远作奴仆吗？","notes":[]},{"n":5,"t":"你岂可拿它当雀鸟玩耍吗？岂可为你的幼女将它拴住吗？","notes":[]},{"n":6,"t":"搭伙的渔夫岂可拿它当货物吗？能把它分给商人吗？","notes":[]},{"n":7,"t":"你能用倒钩枪扎满它的皮，能用鱼叉叉满它的头吗？","notes":[]},{"n":8,"t":"你按手在它身上，想与它争战，就不再这样行吧！","notes":[]},{"n":9,"t":"人指望捉拿它是徒然的；一见它，岂不丧胆吗？","notes":[]},{"n":10,"t":"没有那么凶猛的人敢惹它。这样，谁能在我面前站立得住呢？","notes":[]},{"n":11,"t":"谁先给我什么，使我偿还呢？天下万物都是我的。","notes":[]},{"n":12,"t":"论到鳄鱼的肢体和其大力，并美好的骨骼，我不能缄默不言。","notes":[]},{"n":13,"t":"谁能剥它的外衣？谁能进它上下牙骨之间呢？","notes":[]},{"n":14,"t":"谁能开它的腮颊？它牙齿四围是可畏的。","notes":[]},{"n":15,"t":"它以坚固的鳞甲为可夸，紧紧合闭，封得严密。","notes":[]},{"n":16,"t":"这鳞甲一一相连，甚至气不得透入其间，","notes":[]},{"n":17,"t":"都是互相联络、胶结，不能分离。","notes":[]},{"n":18,"t":"它打喷嚏就发出光来；它眼睛好像早晨的光线。","notes":["原文是眼皮"]},{"n":19,"t":"从它口中发出烧着的火把，与飞迸的火星；","notes":[]},{"n":20,"t":"从它鼻孔冒出烟来，如烧开的锅和点着的芦苇。","notes":[]},{"n":21,"t":"它的气点着煤炭，有火焰从它口中发出。","notes":[]},{"n":22,"t":"它颈项中存着劲力；在它面前的都恐吓蹦跳。","notes":[]},{"n":23,"t":"它的肉块互相联络，紧贴其身，不能摇动。","notes":[]},{"n":24,"t":"它的心结实如石头，如下磨石那样结实。","notes":[]},{"n":25,"t":"它一起来，勇士都惊恐，心里慌乱，便都昏迷。","notes":[]},{"n":26,"t":"人若用刀，用枪，用标枪，用尖枪扎它，都是无用。","notes":[]},{"n":27,"t":"它以铁为干草，以铜为烂木。","notes":[]},{"n":28,"t":"箭不能恐吓它使它逃避；弹石在它看为碎秸。","notes":[]},{"n":29,"t":"棍棒算为禾秸；它嗤笑短枪飕的响声。","notes":[]},{"n":30,"t":"它肚腹下如尖瓦片；它如钉耙经过淤泥。","notes":[]},{"n":31,"t":"它使深渊开滚如锅，使洋海如锅中的膏油。","notes":[]},{"n":32,"t":"它行的路随后发光，令人想深渊如同白发。","notes":[]},{"n":33,"t":"在地上没有像它造的那样，无所惧怕。","notes":[]},{"n":34,"t":"凡高大的，它无不藐视；它在骄傲的水族上作王。","notes":[]}]},"42":{"heading":"结尾","verses":[{"n":1,"t":"约伯回答耶和华说：","notes":[]},{"n":2,"t":"我知道，你万事都能做；你的旨意不能拦阻。","notes":[]},{"n":3,"t":"谁用无知的言语使你的旨意隐藏呢？我所说的是我不明白的；这些事太奇妙，是我不知道的。","notes":[]},{"n":4,"t":"求你听我，我要说话；我问你，求你指示我。","notes":[]},{"n":5,"t":"我从前风闻有你，现在亲眼看见你。","notes":[]},{"n":6,"t":"因此我厌恶自己，在尘土和炉灰中懊悔。","notes":["或译：我的言语"]},{"n":7,"t":"耶和华对约伯说话以后，就对提幔人以利法说：「我的怒气向你和你两个朋友发作，因为你们议论我不如我的仆人约伯说的是。","notes":[]},{"n":8,"t":"现在你们要取七只公牛，七只公羊，到我仆人约伯那里去，为自己献上燔祭，我的仆人约伯就为你们祈祷。我因悦纳他，就不按你们的愚妄办你们。你们议论我，不如我的仆人约伯说的是。」","notes":[]},{"n":9,"t":"于是提幔人以利法、书亚人比勒达、拿玛人琐法照着耶和华所吩咐的去行；耶和华就悦纳约伯。","notes":[]},{"n":10,"t":"约伯为他的朋友祈祷。耶和华就使约伯从苦境转回，并且耶和华赐给他的比他从前所有的加倍。","notes":["原文是掳掠"]},{"n":11,"t":"约伯的弟兄、姊妹，和以先所认识的人都来见他，在他家里一同吃饭；又论到耶和华所降与他的一切灾祸，都为他悲伤安慰他。每人也送他一块银子和一个金环。","notes":[]},{"n":12,"t":"这样，耶和华后来赐福给约伯比先前更多。他有一万四千羊，六千骆驼，一千对牛，一千母驴。","notes":[]},{"n":13,"t":"他也有七个儿子，三个女儿。","notes":[]},{"n":14,"t":"他给长女起名叫耶米玛，次女叫基洗亚，三女叫基连·哈朴。","notes":[]},{"n":15,"t":"在那全地的妇女中找不着像约伯的女儿那样美貌。她们的父亲使她们在弟兄中得产业。","notes":[]},{"n":16,"t":"此后，约伯又活了一百四十年，得见他的儿孙，直到四代。","notes":[]},{"n":17,"t":"这样，约伯年纪老迈，日子满足而死。","notes":[]}]}},"PSA":{"1":{"heading":"真福","verses":[{"n":1,"t":"不从恶人的计谋，不站罪人的道路，不坐亵慢人的座位，","notes":[]},{"n":2,"t":"惟喜爱耶和华的律法，昼夜思想，这人便为有福！","notes":[]},{"n":3,"t":"他要像一棵树栽在溪水旁，按时候结果子，叶子也不枯干。凡他所做的尽都顺利。","notes":[]},{"n":4,"t":"恶人并不是这样，乃像糠秕被风吹散。","notes":[]},{"n":5,"t":"因此，当审判的时候、恶人必站立不住；罪人在义人的会中也是如此。","notes":[]},{"n":6,"t":"因为耶和华知道义人的道路；恶人的道路却必灭亡。","notes":[]}]},"2":{"heading":"神所拣选的君王","verses":[{"n":1,"t":"外邦为什么争闹？万民为什么谋算虚妄的事？","notes":[]},{"n":2,"t":"世上的君王一齐起来，臣宰一同商议，要敌挡耶和华并他的受膏者，","notes":[]},{"n":3,"t":"说：我们要挣开他们的捆绑，脱去他们的绳索。","notes":[]},{"n":4,"t":"那坐在天上的必发笑；主必嗤笑他们。","notes":[]},{"n":5,"t":"那时，他要在怒中责备他们，在烈怒中惊吓他们，","notes":[]},{"n":6,"t":"说：我已经立我的君在锡安—我的圣山上了。","notes":[]},{"n":7,"t":"受膏者说：我要传圣旨。耶和华曾对我说：你是我的儿子，我今日生你。","notes":[]},{"n":8,"t":"你求我，我就将列国赐你为基业，将地极赐你为田产。","notes":[]},{"n":9,"t":"你必用铁杖打破他们；你必将他们如同窑匠的瓦器摔碎。","notes":[]},{"n":10,"t":"现在，你们君王应当省悟！你们世上的审判官该受管教！","notes":[]},{"n":11,"t":"当存畏惧事奉耶和华，又当存战兢而快乐。","notes":[]},{"n":12,"t":"当以嘴亲子，恐怕他发怒，你们便在道中灭亡，因为他的怒气快要发作。凡投靠他的，都是有福的。","notes":[]}]},"3":{"heading":"求助的晨祷","verses":[{"n":1,"t":"耶和华啊，我的敌人何其加增；有许多人起来攻击我。","notes":[]},{"n":2,"t":"有许多人议论我说：他得不着神的帮助。 （细拉）","notes":[]},{"n":3,"t":"但你—耶和华是我四围的盾牌，是我的荣耀，又是叫我抬起头来的。","notes":[]},{"n":4,"t":"我用我的声音求告耶和华，他就从他的圣山上应允我。 （细拉）","notes":[]},{"n":5,"t":"我躺下睡觉，我醒着，耶和华都保佑我。","notes":[]},{"n":6,"t":"虽有成万的百姓来周围攻击我，我也不怕。","notes":[]},{"n":7,"t":"耶和华啊，求你起来！我的神啊，求你救我！因为你打了我一切仇敌的腮骨，敲碎了恶人的牙齿。","notes":[]},{"n":8,"t":"救恩属乎耶和华；愿你赐福给你的百姓。 （细拉）","notes":[]}]},"4":{"heading":"求助的晚祷","verses":[{"n":1,"t":"显我为义的神啊，我呼吁的时候，求你应允我！我在困苦中，你曾使我宽广；现在求你怜恤我，听我的祷告！","notes":[]},{"n":2,"t":"你们这上流人哪，你们将我的尊荣变为羞辱要到几时呢？你们喜爱虚妄，寻找虚假，要到几时呢？ （细拉）","notes":[]},{"n":3,"t":"你们要知道，耶和华已经分别虔诚人归他自己；我求告耶和华，他必听我。","notes":[]},{"n":4,"t":"你们应当畏惧，不可犯罪；在床上的时候，要心里思想，并要肃静。 （细拉）","notes":[]},{"n":5,"t":"当献上公义的祭，又当倚靠耶和华。","notes":[]},{"n":6,"t":"有许多人说：谁能指示我们什么好处？耶和华啊，求你仰起脸来，光照我们。","notes":[]},{"n":7,"t":"你使我心里快乐，胜过那丰收五谷新酒的人。","notes":[]},{"n":8,"t":"我必安然躺下睡觉，因为独有你—耶和华使我安然居住。","notes":[]}]},"5":{"heading":"求主保护","verses":[{"n":1,"t":"耶和华啊，求你留心听我的言语，顾念我的心思！","notes":[]},{"n":2,"t":"我的王我的神啊，求你垂听我呼求的声音！因为我向你祈祷。","notes":[]},{"n":3,"t":"耶和华啊，早晨你必听我的声音；早晨我必向你陈明我的心意，并要警醒！","notes":[]},{"n":4,"t":"因为你不是喜悦恶事的神，恶人不能与你同居。","notes":[]},{"n":5,"t":"狂傲人不能站在你眼前；凡作孽的，都是你所恨恶的。","notes":[]},{"n":6,"t":"说谎言的，你必灭绝；好流人血弄诡诈的，都为耶和华所憎恶。","notes":[]},{"n":7,"t":"至于我，我必凭你丰盛的慈爱进入你的居所；我必存敬畏你的心向你的圣殿下拜。","notes":[]},{"n":8,"t":"耶和华啊，求你因我的仇敌，凭你的公义引领我，使你的道路在我面前正直。","notes":[]},{"n":9,"t":"因为，他们的口中没有诚实；他们的心里满有邪恶；他们的喉咙是敞开的坟墓；他们用舌头谄媚人。","notes":[]},{"n":10,"t":"神啊，求你定他们的罪！愿他们因自己的计谋跌倒；愿你在他们许多的过犯中把他们逐出，因为他们背叛了你。","notes":[]},{"n":11,"t":"凡投靠你的，愿他们喜乐，时常欢呼，因为你护庇他们；又愿那爱你名的人都靠你欢欣。","notes":[]},{"n":12,"t":"因为你必赐福与义人；耶和华啊，你必用恩惠如同盾牌四面护卫他。","notes":[]}]},"6":{"heading":"患难中求助的祈祷","verses":[{"n":1,"t":"耶和华啊，求你不要在怒中责备我，也不要在烈怒中惩罚我！","notes":[]},{"n":2,"t":"耶和华啊，求你可怜我，因为我软弱。耶和华啊，求你医治我，因为我的骨头发战。","notes":[]},{"n":3,"t":"我心也大大地惊惶。耶和华啊，你要到几时才救我呢？","notes":[]},{"n":4,"t":"耶和华啊，求你转回搭救我！因你的慈爱拯救我。","notes":[]},{"n":5,"t":"因为，在死地无人记念你，在阴间有谁称谢你？","notes":[]},{"n":6,"t":"我因唉哼而困乏；我每夜流泪，把床榻漂起，把褥子湿透。","notes":[]},{"n":7,"t":"我因忧愁眼睛干瘪，又因我一切的敌人眼睛昏花。","notes":[]},{"n":8,"t":"你们一切作孽的人，离开我吧！因为耶和华听了我哀哭的声音。","notes":[]},{"n":9,"t":"耶和华听了我的恳求；耶和华必收纳我的祷告。","notes":[]},{"n":10,"t":"我的一切仇敌都必羞愧，大大惊惶；他们必要退后，忽然羞愧。","notes":[]}]},"7":{"heading":"为公义而祈祷","verses":[{"n":1,"t":"耶和华—我的神啊，我投靠你！求你救我脱离一切追赶我的人，将我救拔出来！","notes":[]},{"n":2,"t":"恐怕他们像狮子撕裂我，甚至撕碎，无人搭救。","notes":[]},{"n":3,"t":"耶和华—我的神啊，我若行了这事，若有罪孽在我手里，","notes":[]},{"n":4,"t":"我若以恶报那与我交好的人—连那无故与我为敌的，我也救了他，","notes":[]},{"n":5,"t":"就任凭仇敌追赶我，直到追上，将我的性命踏在地下，使我的荣耀归于灰尘。 （细拉）","notes":[]},{"n":6,"t":"耶和华啊，求你在怒中起来，挺身而立，抵挡我敌人的暴怒！求你为我兴起！你已经命定施行审判！","notes":[]},{"n":7,"t":"愿众民的会环绕你！愿你从其上归于高位！","notes":[]},{"n":8,"t":"耶和华向众民施行审判；耶和华啊，求你按我的公义和我心中的纯正判断我。","notes":[]},{"n":9,"t":"愿恶人的恶断绝！愿你坚立义人！因为公义的神察验人的心肠肺腑。","notes":[]},{"n":10,"t":"神是我的盾牌；他拯救心里正直的人。","notes":[]},{"n":11,"t":"神是公义的审判者，又是天天向恶人发怒的神。","notes":[]},{"n":12,"t":"若有人不回头，他的刀必磨快，弓必上弦，预备妥当了。","notes":[]},{"n":13,"t":"他也预备了杀人的器械；他所射的是火箭。","notes":[]},{"n":14,"t":"试看恶人因奸恶而劬劳，所怀的是毒害，所生的是虚假。","notes":[]},{"n":15,"t":"他掘了坑，又挖深了，竟掉在自己所挖的阱里。","notes":[]},{"n":16,"t":"他的毒害必临到他自己的头上；他的强暴必落到他自己的脑袋上。","notes":[]},{"n":17,"t":"我要照着耶和华的公义称谢他，歌颂耶和华至高者的名。","notes":[]}]},"8":{"heading":"神的荣耀和人的尊贵","verses":[{"n":1,"t":"耶和华—我们的主啊，你的名在全地何其美！你将你的荣耀彰显于天。","notes":[]},{"n":2,"t":"你因敌人的缘故，从婴孩和吃奶的口中，建立了能力，使仇敌和报仇的闭口无言。","notes":[]},{"n":3,"t":"我观看你指头所造的天，并你所陈设的月亮星宿，","notes":[]},{"n":4,"t":"便说：人算什么，你竟顾念他！世人算什么，你竟眷顾他！","notes":[]},{"n":5,"t":"你叫他比天使微小一点，并赐他荣耀尊贵为冠冕。","notes":["或译：神"]},{"n":6,"t":"你派他管理你手所造的，使万物，就是一切的牛羊、田野的兽、空中的鸟、海里的鱼，凡经行海道的，都服在他的脚下。","notes":[],"end":8},{"n":9,"t":"耶和华—我们的主啊，你的名在全地何其美！","notes":[]}]},"9":{"heading":"称颂耶和华的公义","verses":[{"n":1,"t":"我要一心称谢耶和华；我要传扬你一切奇妙的作为。","notes":[]},{"n":2,"t":"我要因你欢喜快乐；至高者啊，我要歌颂你的名！","notes":[]},{"n":3,"t":"我的仇敌转身退去的时候，他们一见你的面就跌倒灭亡。","notes":[]},{"n":4,"t":"因你已经为我伸冤，为我辨屈；你坐在宝座上，按公义审判。","notes":[]},{"n":5,"t":"你曾斥责外邦，你曾灭绝恶人；你曾涂抹他们的名，直到永永远远。","notes":[]},{"n":6,"t":"仇敌到了尽头；他们被毁坏，直到永远。你拆毁他们的城邑，连他们的名号都归于无有。","notes":[]},{"n":7,"t":"惟耶和华坐着为王，直到永远；他已经为审判设摆他的宝座。","notes":[]},{"n":8,"t":"他要按公义审判世界，按正直判断万民。","notes":[]},{"n":9,"t":"耶和华又要给受欺压的人作高台，在患难的时候作高台。","notes":[]},{"n":10,"t":"耶和华啊，认识你名的人要倚靠你，因你没有离弃寻求你的人。","notes":[]},{"n":11,"t":"应当歌颂居锡安的耶和华，将他所行的传扬在众民中。","notes":[]},{"n":12,"t":"因为那追讨流人血之罪的—他记念受屈的人，不忘记困苦人的哀求。","notes":[]},{"n":13,"t":"耶和华啊，你是从死门把我提拔起来的；求你怜恤我，看那恨我的人所加给我的苦难，","notes":[]},{"n":14,"t":"好叫我述说你一切的美德；我必在锡安城的门因你的救恩欢乐。","notes":["原文是女子"]},{"n":15,"t":"外邦人陷在自己所掘的坑中；他们的脚在自己暗设的网罗里缠住了。","notes":[]},{"n":16,"t":"耶和华已将自己显明了，他已施行审判；恶人被自己手所做的缠住了。 （细拉）","notes":["或译：他叫恶人被自己手所做的累住了"]},{"n":17,"t":"恶人，就是忘记神的外邦人，都必归到阴间。","notes":[]},{"n":18,"t":"穷乏人必不永久被忘；困苦人的指望必不永远落空。","notes":[]},{"n":19,"t":"耶和华啊，求你起来，不容人得胜！愿外邦人在你面前受审判！","notes":[]},{"n":20,"t":"耶和华啊，求你使外邦人恐惧；愿他们知道自己不过是人。 （细拉）","notes":[]}]},"10":{"heading":"为公义而祈祷","verses":[{"n":1,"t":"耶和华啊，你为什么站在远处？在患难的时候为什么隐藏？","notes":[]},{"n":2,"t":"恶人在骄横中把困苦人追得火急；愿他们陷在自己所设的计谋里。","notes":[]},{"n":3,"t":"因为恶人以心愿自夸；贪财的背弃耶和华，并且轻慢他。","notes":["或译：他祝福贪财的，却轻慢耶和华"]},{"n":4,"t":"恶人面带骄傲，说：耶和华必不追究；他一切所想的都以为没有神。","notes":[]},{"n":5,"t":"凡他所做的，时常稳固；你的审判超过他的眼界。至于他一切的敌人，他都向他们喷气。","notes":[]},{"n":6,"t":"他心里说：我必不动摇，世世代代不遭灾难。","notes":[]},{"n":7,"t":"他满口是咒骂、诡诈、欺压，舌底是毒害、奸恶。","notes":[]},{"n":8,"t":"他在村庄埋伏等候；他在隐密处杀害无辜的人。他的眼睛窥探无倚无靠的人；","notes":[]},{"n":9,"t":"他埋伏在暗地，如狮子蹲在洞中。他埋伏，要掳去困苦人；他拉网，就把困苦人掳去。","notes":[]},{"n":10,"t":"他屈身蹲伏，无倚无靠的人就倒在他爪牙之下。","notes":["爪牙：或译强暴人"]},{"n":11,"t":"他心里说：神竟忘记了；他掩面永不观看。","notes":[]},{"n":12,"t":"耶和华啊，求你起来！神啊，求你举手，不要忘记困苦人！","notes":[]},{"n":13,"t":"恶人为何轻慢神，心里说：你必不追究？","notes":[]},{"n":14,"t":"其实你已经观看；因为奸恶毒害，你都看见了，为要以手施行报应。无倚无靠的人把自己交托你；你向来是帮助孤儿的。","notes":[]},{"n":15,"t":"愿你打断恶人的膀臂；至于坏人，愿你追究他的恶，直到净尽。","notes":[]},{"n":16,"t":"耶和华永永远远为王；外邦人从他的地已经灭绝了。","notes":[]},{"n":17,"t":"耶和华啊，谦卑人的心愿，你早已知道。你必预备他们的心，也必侧耳听他们的祈求，","notes":["原文是听见"]},{"n":18,"t":"为要给孤儿和受欺压的人伸冤，使强横的人不再威吓他们。","notes":[]}]},"11":{"heading":"在主里得安稳","verses":[{"n":1,"t":"我是投靠耶和华；你们怎么对我说：你当像鸟飞往你的山去。","notes":[]},{"n":2,"t":"看哪，恶人弯弓，把箭搭在弦上，要在暗中射那心里正直的人。","notes":[]},{"n":3,"t":"根基若毁坏，义人还能做什么呢？","notes":[]},{"n":4,"t":"耶和华在他的圣殿里；耶和华的宝座在天上；他的慧眼察看世人。","notes":[]},{"n":5,"t":"耶和华试验义人；惟有恶人和喜爱强暴的人，他心里恨恶。","notes":[]},{"n":6,"t":"他要向恶人密布网罗；有烈火、硫磺、热风，作他们杯中的分。","notes":[]},{"n":7,"t":"因为耶和华是公义的，他喜爱公义；正直人必得见他的面。","notes":[]}]},"12":{"heading":"求助的祈祷","verses":[{"n":1,"t":"耶和华啊，求你帮助，因虔诚人断绝了；世人中间的忠信人没有了。","notes":[]},{"n":2,"t":"人人向邻舍说谎；他们说话，是嘴唇油滑，心口不一。","notes":[]},{"n":3,"t":"凡油滑的嘴唇和夸大的舌头，耶和华必要剪除。","notes":[]},{"n":4,"t":"他们曾说：我们必能以舌头得胜；我们的嘴唇是我们自己的，谁能作我们的主呢？","notes":[]},{"n":5,"t":"耶和华说：因为困苦人的冤屈和贫穷人的叹息，我现在要起来，把他安置在他所切慕的稳妥之地。","notes":[]},{"n":6,"t":"耶和华的言语是纯净的言语，如同银子在泥炉中炼过七次。","notes":[]},{"n":7,"t":"耶和华啊，你必保护他们；你必保佑他们永远脱离这世代的人。","notes":[]},{"n":8,"t":"下流人在世人中升高，就有恶人到处游行。","notes":[]}]},"13":{"heading":"求耶和华看顾","verses":[{"n":1,"t":"耶和华啊，你忘记我要到几时呢？要到永远吗？你掩面不顾我要到几时呢？","notes":[]},{"n":2,"t":"我心里筹算，终日愁苦，要到几时呢？我的仇敌升高压制我，要到几时呢？","notes":[]},{"n":3,"t":"耶和华—我的神啊，求你看顾我，应允我！使我眼目光明，免得我沉睡至死；","notes":[]},{"n":4,"t":"免得我的仇敌说：我胜了他；免得我的敌人在我摇动的时候喜乐。","notes":[]},{"n":5,"t":"但我倚靠你的慈爱；我的心因你的救恩快乐。","notes":[]},{"n":6,"t":"我要向耶和华歌唱，因他用厚恩待我。","notes":[]}]},"14":{"heading":"人的邪恶","verses":[{"n":1,"t":"愚顽人心里说：没有神。他们都是邪恶，行了可憎恶的事；没有一个人行善。","notes":[]},{"n":2,"t":"耶和华从天上垂看世人，要看有明白的没有，有寻求神的没有。","notes":[]},{"n":3,"t":"他们都偏离正路，一同变为污秽；并没有行善的，连一个也没有。","notes":[]},{"n":4,"t":"作孽的都没有知识吗？他们吞吃我的百姓，如同吃饭一样，并不求告耶和华。","notes":[]},{"n":5,"t":"他们在那里大大地害怕，因为神在义人的族类中。","notes":[]},{"n":6,"t":"你们叫困苦人的谋算变为羞辱；然而耶和华是他的避难所。","notes":[]},{"n":7,"t":"但愿以色列的救恩从锡安而出。耶和华救回他被掳的子民那时，雅各要快乐，以色列要欢喜。","notes":[]}]},"15":{"heading":"得居圣山者的品行","verses":[{"n":1,"t":"耶和华啊，谁能寄居你的帐幕？谁能住在你的圣山？","notes":[]},{"n":2,"t":"就是行为正直、做事公义、心里说实话的人。","notes":[]},{"n":3,"t":"他不以舌头谗谤人，不恶待朋友，也不随伙毁谤邻里。","notes":[]},{"n":4,"t":"他眼中藐视匪类，却尊重那敬畏耶和华的人。他发了誓，虽然自己吃亏也不更改。","notes":[]},{"n":5,"t":"他不放债取利，不受贿赂以害无辜。行这些事的人必永不动摇。","notes":[]}]},"16":{"heading":"为信心稳固而祈祷","verses":[{"n":1,"t":"神啊，求你保佑我，因为我投靠你。","notes":[]},{"n":2,"t":"我的心哪，你曾对耶和华说：你是我的主；我的好处不在你以外。","notes":[]},{"n":3,"t":"论到世上的圣民，他们又美又善，是我最喜悦的。","notes":[]},{"n":4,"t":"以别神代替耶和华的，他们的愁苦必加增；他们所浇奠的血我不献上；我嘴唇也不提别神的名号。","notes":["或译：送礼物给别神的"]},{"n":5,"t":"耶和华是我的产业，是我杯中的分；我所得的，你为我持守。","notes":[]},{"n":6,"t":"用绳量给我的地界，坐落在佳美之处；我的产业实在美好。","notes":[]},{"n":7,"t":"我必称颂那指教我的耶和华；我的心肠在夜间也警戒我。","notes":[]},{"n":8,"t":"我将耶和华常摆在我面前，因他在我右边，我便不致摇动。","notes":[]},{"n":9,"t":"因此，我的心欢喜，我的灵快乐；我的肉身也要安然居住。","notes":["原文是荣耀"]},{"n":10,"t":"因为你必不将我的灵魂撇在阴间，也不叫你的圣者见朽坏。","notes":[]},{"n":11,"t":"你必将生命的道路指示我。在你面前有满足的喜乐；在你右手中有永远的福乐。","notes":[]}]},"17":{"heading":"无辜的人的祷告","verses":[{"n":1,"t":"耶和华啊，求你听闻公义，侧耳听我的呼吁！求你留心听我这不出于诡诈嘴唇的祈祷！","notes":[]},{"n":2,"t":"愿我的判语从你面前发出；愿你的眼睛观看公正。","notes":[]},{"n":3,"t":"你已经试验我的心；你在夜间鉴察我；你熬炼我，却找不着什么；我立志叫我口中没有过失。","notes":[]},{"n":4,"t":"论到人的行为，我借着你嘴唇的言语自己谨守，不行强暴人的道路。","notes":[]},{"n":5,"t":"我的脚踏定了你的路径；我的两脚未曾滑跌。","notes":[]},{"n":6,"t":"神啊，我曾求告你，因为你必应允我；求你向我侧耳，听我的言语。","notes":[]},{"n":7,"t":"求你显出你奇妙的慈爱来；你是那用右手拯救投靠你的脱离起来攻击他们的人。","notes":[]},{"n":8,"t":"求你保护我，如同保护眼中的瞳人；将我隐藏在你翅膀的荫下，","notes":[]},{"n":9,"t":"使我脱离那欺压我的恶人，就是围困我要害我命的仇敌。","notes":[]},{"n":10,"t":"他们的心被脂油包裹；他们用口说骄傲的话。","notes":[]},{"n":11,"t":"他们围困了我们的脚步；他们瞪着眼，要把我们推倒在地。","notes":[]},{"n":12,"t":"他像狮子急要抓食，又像少壮狮子蹲伏在暗处。","notes":[]},{"n":13,"t":"耶和华啊，求你起来，前去迎敌，将他打倒！用你的刀救护我命脱离恶人。","notes":[]},{"n":14,"t":"耶和华啊，求你用手救我脱离世人，脱离那只在今生有福分的世人！你把你的财宝充满他们的肚腹；他们因有儿女就心满意足，将其余的财物留给他们的婴孩。","notes":[]},{"n":15,"t":"至于我，我必在义中见你的面；我醒了的时候，得见你的形象就心满意足了。","notes":["或译：着"]}]},"18":{"heading":"大卫的胜利之歌","verses":[{"n":1,"t":"耶和华，我的力量啊，我爱你！","notes":[]},{"n":2,"t":"耶和华是我的岩石，我的山寨，我的救主，我的神，我的磐石，我所投靠的。他是我的盾牌，是拯救我的角，是我的高台。","notes":[]},{"n":3,"t":"我要求告当赞美的耶和华；这样我必从仇敌手中被救出来。","notes":[]},{"n":4,"t":"曾有死亡的绳索缠绕我，匪类的急流使我惊惧，","notes":[]},{"n":5,"t":"阴间的绳索缠绕我，死亡的网罗临到我。","notes":[]},{"n":6,"t":"我在急难中求告耶和华，向我的神呼求。他从殿中听了我的声音；我在他面前的呼求入了他的耳中。","notes":[]},{"n":7,"t":"那时，因他发怒，地就摇撼战抖；山的根基也震动摇撼。","notes":[]},{"n":8,"t":"从他鼻孔冒烟上腾；从他口中发火焚烧，连炭也着了。","notes":[]},{"n":9,"t":"他又使天下垂，亲自降临，有黑云在他脚下。","notes":[]},{"n":10,"t":"他坐着基路伯飞行；他借着风的翅膀快飞。","notes":[]},{"n":11,"t":"他以黑暗为藏身之处，以水的黑暗、天空的厚云为他四围的行宫。","notes":[]},{"n":12,"t":"因他面前的光辉，他的厚云行过便有冰雹火炭。","notes":[]},{"n":13,"t":"耶和华也在天上打雷；至高者发出声音便有冰雹火炭。","notes":[]},{"n":14,"t":"他射出箭来，使仇敌四散；多多发出闪电，使他们扰乱。","notes":[]},{"n":15,"t":"耶和华啊，你的斥责一发，你鼻孔的气一出，海底就出现，大地的根基也显露。","notes":[]},{"n":16,"t":"他从高天伸手抓住我，把我从大水中拉上来。","notes":[]},{"n":17,"t":"他救我脱离我的劲敌和那些恨我的人，因为他们比我强盛。","notes":[]},{"n":18,"t":"我遭遇灾难的日子，他们来攻击我；但耶和华是我的倚靠。","notes":[]},{"n":19,"t":"他又领我到宽阔之处；他救拔我，因他喜悦我。","notes":[]},{"n":20,"t":"耶和华按着我的公义报答我，按着我手中的清洁赏赐我。","notes":[]},{"n":21,"t":"因为我遵守了耶和华的道，未曾作恶离开我的神。","notes":[]},{"n":22,"t":"他的一切典章常在我面前；他的律例我也未曾丢弃。","notes":[]},{"n":23,"t":"我在他面前作了完全人；我也保守自己远离我的罪孽。","notes":[]},{"n":24,"t":"所以，耶和华按我的公义，按我在他眼前手中的清洁偿还我。","notes":[]},{"n":25,"t":"慈爱的人，你以慈爱待他；完全的人，你以完全待他。","notes":[]},{"n":26,"t":"清洁的人，你以清洁待他；乖僻的人，你以弯曲待他。","notes":[]},{"n":27,"t":"困苦的百姓，你必拯救；高傲的眼目，你必使他降卑。","notes":[]},{"n":28,"t":"你必点着我的灯；耶和华—我的神必照明我的黑暗。","notes":[]},{"n":29,"t":"我借着你冲入敌军，借着我的神跳过墙垣。","notes":[]},{"n":30,"t":"至于神，他的道是完全的；耶和华的话是炼净的。凡投靠他的，他便作他们的盾牌。","notes":[]},{"n":31,"t":"除了耶和华，谁是神呢？除了我们的神，谁是磐石呢？","notes":[]},{"n":32,"t":"惟有那以力量束我的腰、使我行为完全的，他是神。","notes":[]},{"n":33,"t":"他使我的脚快如母鹿的蹄，又使我在高处安稳。","notes":[]},{"n":34,"t":"他教导我的手能以争战，甚至我的膀臂能开铜弓。","notes":[]},{"n":35,"t":"你把你的救恩给我作盾牌；你的右手扶持我；你的温和使我为大。","notes":[]},{"n":36,"t":"你使我脚下的地步宽阔；我的脚未曾滑跌。","notes":[]},{"n":37,"t":"我要追赶我的仇敌，并要追上他们；不将他们灭绝，我总不归回。","notes":[]},{"n":38,"t":"我要打伤他们，使他们不能起来；他们必倒在我的脚下。","notes":[]},{"n":39,"t":"因为你曾以力量束我的腰，使我能争战；你也使那起来攻击我的都服在我以下。","notes":[]},{"n":40,"t":"你又使我的仇敌在我面前转背逃跑，叫我能以剪除那恨我的人。","notes":[]},{"n":41,"t":"他们呼求，却无人拯救；就是呼求耶和华，他也不应允。","notes":[]},{"n":42,"t":"我捣碎他们，如同风前的灰尘，倒出他们，如同街上的泥土。","notes":[]},{"n":43,"t":"你救我脱离百姓的争竞，立我作列国的元首；我素不认识的民必事奉我。","notes":[]},{"n":44,"t":"他们一听见我的名声就必顺从我；外邦人要投降我。","notes":[]},{"n":45,"t":"外邦人要衰残，战战兢兢地出他们的营寨。","notes":[]},{"n":46,"t":"耶和华是活神。愿我的磐石被人称颂；愿救我的神被人尊崇。","notes":[]},{"n":47,"t":"这位神，就是那为我伸冤、使众民服在我以下的。","notes":[]},{"n":48,"t":"你救我脱离仇敌，又把我举起，高过那些起来攻击我的；你救我脱离强暴的人。","notes":[]},{"n":49,"t":"耶和华啊，因此我要在外邦中称谢你，歌颂你的名。","notes":[]},{"n":50,"t":"耶和华赐极大的救恩给他所立的王，施慈爱给他的受膏者，就是给大卫和他的后裔，直到永远。","notes":[]}]},"19":{"heading":"造化的荣耀","verses":[{"n":1,"t":"诸天述说神的荣耀；穹苍传扬他的手段。","notes":[]},{"n":2,"t":"这日到那日发出言语；这夜到那夜传出知识。","notes":[]},{"n":3,"t":"无言无语，也无声音可听。","notes":[]},{"n":4,"t":"它的量带通遍天下，它的言语传到地极。神在其间为太阳安设帐幕；","notes":[]},{"n":5,"t":"太阳如同新郎出洞房，又如勇士欢然奔路。","notes":[]},{"n":6,"t":"它从天这边出来，绕到天那边，没有一物被隐藏不得它的热气。","notes":[]},{"n":7,"t":"耶和华的律法全备，能苏醒人心；耶和华的法度确定，能使愚人有智慧。","notes":[],"heads":["耶和华的律法"]},{"n":8,"t":"耶和华的训词正直，能快活人的心；耶和华的命令清洁，能明亮人的眼目。","notes":[]},{"n":9,"t":"耶和华的道理洁净，存到永远；耶和华的典章真实，全然公义—","notes":[]},{"n":10,"t":"都比金子可羡慕，且比极多的精金可羡慕；比蜜甘甜，且比蜂房下滴的蜜甘甜。","notes":[]},{"n":11,"t":"况且你的仆人因此受警戒，守着这些便有大赏。","notes":[]},{"n":12,"t":"谁能知道自己的错失呢？愿你赦免我隐而未现的过错。","notes":[]},{"n":13,"t":"求你拦阻仆人不犯任意妄为的罪，不容这罪辖制我，我便完全，免犯大罪。","notes":[]},{"n":14,"t":"耶和华—我的磐石，我的救赎主啊，愿我口中的言语、心里的意念在你面前蒙悦纳。","notes":[]}]},"20":{"heading":"祈求胜利","verses":[{"n":1,"t":"愿耶和华在你遭难的日子应允你；愿名为雅各神的高举你。","notes":[]},{"n":2,"t":"愿他从圣所救助你，从锡安坚固你，","notes":[]},{"n":3,"t":"记念你的一切供献，悦纳你的燔祭， （细拉）","notes":[]},{"n":4,"t":"将你心所愿的赐给你，成就你的一切筹算。","notes":[]},{"n":5,"t":"我们要因你的救恩夸胜，要奉我们神的名竖立旌旗。愿耶和华成就你一切所求的！","notes":[]},{"n":6,"t":"现在我知道耶和华救护他的受膏者，必从他的圣天上应允他，用右手的能力救护他。","notes":[]},{"n":7,"t":"有人靠车，有人靠马，但我们要提到耶和华—我们神的名。","notes":[]},{"n":8,"t":"他们都屈身仆倒，我们却起来，立得正直。","notes":[]},{"n":9,"t":"求耶和华施行拯救；我们呼求的时候，愿王应允我们！","notes":[]}]},"21":{"heading":"为胜利而歌颂","verses":[{"n":1,"t":"耶和华啊，王必因你的能力欢喜；因你的救恩，他的快乐何其大！","notes":[]},{"n":2,"t":"他心里所愿的，你已经赐给他；他嘴唇所求的，你未尝不应允。 （细拉）","notes":[]},{"n":3,"t":"你以美福迎接他，把精金的冠冕戴在他头上。","notes":[]},{"n":4,"t":"他向你求寿，你便赐给他，就是日子长久，直到永远。","notes":[]},{"n":5,"t":"他因你的救恩大有荣耀；你又将尊荣威严加在他身上。","notes":[]},{"n":6,"t":"你使他有洪福，直到永远，又使他在你面前欢喜快乐。","notes":[]},{"n":7,"t":"王倚靠耶和华，因至高者的慈爱必不摇动。","notes":[]},{"n":8,"t":"你的手要搜出你的一切仇敌；你的右手要搜出那些恨你的人。","notes":[]},{"n":9,"t":"你发怒的时候，要使他们如在炎热的火炉中。耶和华要在他的震怒中吞灭他们；那火要把他们烧尽了。","notes":[]},{"n":10,"t":"你必从世上灭绝他们的子孙，从人间灭绝他们的后裔。","notes":["原文是果子"]},{"n":11,"t":"因为他们有意加害于你；他们想出计谋，却不能作成。","notes":[]},{"n":12,"t":"你必使他们转背逃跑，向他们的脸搭箭在弦。","notes":[]},{"n":13,"t":"耶和华啊，愿你因自己的能力显为至高！这样，我们就唱诗，歌颂你的大能。","notes":[]}]},"22":{"heading":"痛苦中的祷告和赞美","verses":[{"n":1,"t":"我的神，我的神！为什么离弃我？为什么远离不救我？不听我唉哼的言语？","notes":[]},{"n":2,"t":"我的神啊，我白日呼求，你不应允，夜间呼求，并不住声。","notes":[]},{"n":3,"t":"但你是圣洁的，是用以色列的赞美为宝座的。","notes":["或译：居所"]},{"n":4,"t":"我们的祖宗倚靠你；他们倚靠你，你便解救他们。","notes":[]},{"n":5,"t":"他们哀求你，便蒙解救；他们倚靠你，就不羞愧。","notes":[]},{"n":6,"t":"但我是虫，不是人，被众人羞辱，被百姓藐视。","notes":[]},{"n":7,"t":"凡看见我的都嗤笑我；他们撇嘴摇头，说：","notes":[]},{"n":8,"t":"他把自己交托耶和华，耶和华可以救他吧！耶和华既喜悦他，可以搭救他吧！","notes":[]},{"n":9,"t":"但你是叫我出母腹的；我在母怀里，你就使我有倚靠的心。","notes":[]},{"n":10,"t":"我自出母胎就被交在你手里；从我母亲生我，你就是我的神。","notes":[]},{"n":11,"t":"求你不要远离我！因为急难临近了，没有人帮助我。","notes":[]},{"n":12,"t":"有许多公牛围绕我，巴珊大力的公牛四面困住我。","notes":[]},{"n":13,"t":"它们向我张口，好像抓撕吼叫的狮子。","notes":[]},{"n":14,"t":"我如水被倒出来；我的骨头都脱了节；我心在我里面如蜡熔化。","notes":[]},{"n":15,"t":"我的精力枯干，如同瓦片；我的舌头贴在我牙床上。你将我安置在死地的尘土中。","notes":[]},{"n":16,"t":"犬类围着我，恶党环绕我；他们扎了我的手，我的脚。","notes":[]},{"n":17,"t":"我的骨头，我都能数过；他们瞪着眼看我。","notes":[]},{"n":18,"t":"他们分我的外衣，为我的里衣拈阄。","notes":[]},{"n":19,"t":"耶和华啊，求你不要远离我！我的救主啊，求你快来帮助我！","notes":[]},{"n":20,"t":"求你救我的灵魂脱离刀剑，救我的生命脱离犬类，","notes":["生命：原文是独一者"]},{"n":21,"t":"救我脱离狮子的口；你已经应允我，使我脱离野牛的角。","notes":[]},{"n":22,"t":"我要将你的名传与我的弟兄，在会中我要赞美你。","notes":[]},{"n":23,"t":"你们敬畏耶和华的人要赞美他！雅各的后裔都要荣耀他！以色列的后裔都要惧怕他！","notes":[]},{"n":24,"t":"因为他没有藐视憎恶受苦的人，也没有向他掩面；那受苦之人呼吁的时候，他就垂听。","notes":[]},{"n":25,"t":"我在大会中赞美你的话是从你而来的；我要在敬畏耶和华的人面前还我的愿。","notes":[]},{"n":26,"t":"谦卑的人必吃得饱足；寻求耶和华的人必赞美他。愿你们的心永远活着！","notes":[]},{"n":27,"t":"地的四极都要想念耶和华，并且归顺他；列国的万族都要在你面前敬拜。","notes":[]},{"n":28,"t":"因为国权是耶和华的；他是管理万国的。","notes":[]},{"n":29,"t":"地上一切丰肥的人必吃喝而敬拜；凡下到尘土中—不能存活自己性命的人—都要在他面前下拜。","notes":[]},{"n":30,"t":"他必有后裔事奉他；主所行的事必传与后代。","notes":[]},{"n":31,"t":"他们必来把他的公义传给将要生的民，言明这事是他所行的。","notes":[]}]},"23":{"heading":"耶和华是我牧者","verses":[{"n":1,"t":"耶和华是我的牧者，我必不致缺乏。","notes":[]},{"n":2,"t":"他使我躺卧在青草地上，领我在可安歇的水边。","notes":[]},{"n":3,"t":"他使我的灵魂苏醒，为自己的名引导我走义路。","notes":[]},{"n":4,"t":"我虽然行过死荫的幽谷，也不怕遭害，因为你与我同在；你的杖，你的竿，都安慰我。","notes":[]},{"n":5,"t":"在我敌人面前，你为我摆设筵席；你用油膏了我的头，使我的福杯满溢。","notes":[]},{"n":6,"t":"我一生一世必有恩惠慈爱随着我；我且要住在耶和华的殿中，直到永远。","notes":[]}]},"24":{"heading":"伟大的君王","verses":[{"n":1,"t":"地和其中所充满的，世界和住在其间的，都属耶和华。","notes":[]},{"n":2,"t":"他把地建立在海上，安定在大水之上。","notes":[]},{"n":3,"t":"谁能登耶和华的山？谁能站在他的圣所？","notes":[]},{"n":4,"t":"就是手洁心清，不向虚妄，起誓不怀诡诈的人。","notes":[]},{"n":5,"t":"他必蒙耶和华赐福，又蒙救他的神使他成义。","notes":[]},{"n":6,"t":"这是寻求耶和华的族类，是寻求你面的雅各。 （细拉）","notes":[]},{"n":7,"t":"众城门哪，你们要抬起头来！永久的门户，你们要被举起！那荣耀的王将要进来！","notes":[]},{"n":8,"t":"荣耀的王是谁呢？就是有力有能的耶和华，在战场上有能的耶和华！","notes":[]},{"n":9,"t":"众城门哪，你们要抬起头来！永久的门户，你们要把头抬起！那荣耀的王将要进来！","notes":[]},{"n":10,"t":"荣耀的王是谁呢？万军之耶和华，他是荣耀的王！ （细拉）","notes":[]}]},"25":{"heading":"求主指引保护","verses":[{"n":1,"t":"耶和华啊，我的心仰望你。","notes":[]},{"n":2,"t":"我的神啊，我素来倚靠你；求你不要叫我羞愧，不要叫我的仇敌向我夸胜。","notes":[]},{"n":3,"t":"凡等候你的必不羞愧；惟有那无故行奸诈的必要羞愧。","notes":[]},{"n":4,"t":"耶和华啊，求你将你的道指示我，将你的路教训我！","notes":[]},{"n":5,"t":"求你以你的真理引导我，教训我，因为你是救我的神。我终日等候你。","notes":[]},{"n":6,"t":"耶和华啊，求你记念你的怜悯和慈爱，因为这是亘古以来所常有的。","notes":[]},{"n":7,"t":"求你不要记念我幼年的罪愆和我的过犯；耶和华啊，求你因你的恩惠，按你的慈爱记念我。","notes":[]},{"n":8,"t":"耶和华是良善正直的，所以他必指示罪人走正路。","notes":[]},{"n":9,"t":"他必按公平引领谦卑人，将他的道教训他们。","notes":[]},{"n":10,"t":"凡遵守他的约和他法度的人，耶和华都以慈爱诚实待他。","notes":[]},{"n":11,"t":"耶和华啊，求你因你的名赦免我的罪，因为我的罪重大。","notes":[]},{"n":12,"t":"谁敬畏耶和华，耶和华必指示他当选择的道路。","notes":[]},{"n":13,"t":"他必安然居住；他的后裔必承受地土。","notes":[]},{"n":14,"t":"耶和华与敬畏他的人亲密；他必将自己的约指示他们。","notes":[]},{"n":15,"t":"我的眼目时常仰望耶和华，因为他必将我的脚从网里拉出来。","notes":[]},{"n":16,"t":"求你转向我，怜恤我，因为我是孤独困苦。","notes":[]},{"n":17,"t":"我心里的愁苦甚多，求你救我脱离我的祸患。","notes":[]},{"n":18,"t":"求你看顾我的困苦，我的艰难，赦免我一切的罪。","notes":[]},{"n":19,"t":"求你察看我的仇敌，因为他们人多，并且痛痛地恨我。","notes":[]},{"n":20,"t":"求你保护我的性命，搭救我，使我不致羞愧，因为我投靠你。","notes":[]},{"n":21,"t":"愿纯全、正直保守我，因为我等候你。","notes":[]},{"n":22,"t":"神啊，求你救赎以色列脱离他一切的愁苦。","notes":[]}]},"26":{"heading":"义人的祈祷","verses":[{"n":1,"t":"耶和华啊，求你为我伸冤，因我向来行事纯全；我又倚靠耶和华，并不摇动。","notes":[]},{"n":2,"t":"耶和华啊，求你察看我，试验我，熬炼我的肺腑心肠。","notes":[]},{"n":3,"t":"因为你的慈爱常在我眼前，我也按你的真理而行。","notes":[]},{"n":4,"t":"我没有和虚谎人同坐，也不与瞒哄人的同群。","notes":[]},{"n":5,"t":"我恨恶恶人的会，必不与恶人同坐。","notes":[]},{"n":6,"t":"耶和华啊，我要洗手表明无辜，才环绕你的祭坛；","notes":[]},{"n":7,"t":"我好发称谢的声音，也要述说你一切奇妙的作为。","notes":[]},{"n":8,"t":"耶和华啊，我喜爱你所住的殿和你显荣耀的居所。","notes":[]},{"n":9,"t":"不要把我的灵魂和罪人一同除掉；不要把我的性命和流人血的一同除掉。","notes":[]},{"n":10,"t":"他们的手中有奸恶，右手满有贿赂。","notes":[]},{"n":11,"t":"至于我，却要行事纯全；求你救赎我，怜恤我！","notes":[]},{"n":12,"t":"我的脚站在平坦地方；在众会中我要称颂耶和华！","notes":[]}]},"27":{"heading":"赞美的祷告","verses":[{"n":1,"t":"耶和华是我的亮光，是我的拯救，我还怕谁呢？耶和华是我性命的保障，我还惧谁呢？","notes":["或译：力量"]},{"n":2,"t":"那作恶的就是我的仇敌，前来吃我肉的时候就绊跌仆倒。","notes":[]},{"n":3,"t":"虽有军兵安营攻击我，我的心也不害怕；虽然兴起刀兵攻击我，我必仍旧安稳。","notes":[]},{"n":4,"t":"有一件事，我曾求耶和华，我仍要寻求：就是一生一世住在耶和华的殿中，瞻仰他的荣美，在他的殿里求问。","notes":[]},{"n":5,"t":"因为我遭遇患难，他必暗暗地保守我；在他亭子里，把我藏在他帐幕的隐密处，将我高举在磐石上。","notes":[]},{"n":6,"t":"现在我得以昂首，高过四面的仇敌。我要在他的帐幕里欢然献祭；我要唱诗歌颂耶和华。","notes":[]},{"n":7,"t":"耶和华啊，我用声音呼吁的时候，求你垂听；并求你怜恤我，应允我。","notes":[]},{"n":8,"t":"你说：你们当寻求我的面。那时我心向你说：耶和华啊，你的面我正要寻求。","notes":[]},{"n":9,"t":"不要向我掩面。不要发怒赶逐仆人，你向来是帮助我的。救我的神啊，不要丢掉我，也不要离弃我。","notes":[]},{"n":10,"t":"我父母离弃我，耶和华必收留我。","notes":[]},{"n":11,"t":"耶和华啊，求你将你的道指教我，因我仇敌的缘故引导我走平坦的路。","notes":[]},{"n":12,"t":"求你不要把我交给敌人，遂其所愿；因为妄作见证的和口吐凶言的，起来攻击我。","notes":[]},{"n":13,"t":"我若不信在活人之地得见耶和华的恩惠，就早已丧胆了。","notes":[]},{"n":14,"t":"要等候耶和华！当壮胆，坚固你的心！我再说，要等候耶和华！","notes":[]}]},"28":{"heading":"求主帮助","verses":[{"n":1,"t":"耶和华啊，我要求告你！我的磐石啊，不要向我缄默！倘若你向我闭口，我就如将死的人一样。","notes":[]},{"n":2,"t":"我呼求你，向你至圣所举手的时候，求你垂听我恳求的声音！","notes":[]},{"n":3,"t":"不要把我和恶人并作孽的一同除掉；他们与邻舍说和平话，心里却是奸恶。","notes":[]},{"n":4,"t":"愿你按着他们所做的，并他们所行的恶事待他们。愿你照着他们手所做的待他们，将他们所应得的报应加给他们。","notes":[]},{"n":5,"t":"他们既然不留心耶和华所行的和他手所做的，他就必毁坏他们，不建立他们。","notes":[]},{"n":6,"t":"耶和华是应当称颂的，因为他听了我恳求的声音。","notes":[]},{"n":7,"t":"耶和华是我的力量，是我的盾牌；我心里倚靠他就得帮助。所以我心中欢乐，我必用诗歌颂赞他。","notes":[]},{"n":8,"t":"耶和华是他百姓的力量，又是他受膏者得救的保障。","notes":[]},{"n":9,"t":"求你拯救你的百姓，赐福给你的产业，牧养他们，扶持他们，直到永远。","notes":[]}]},"29":{"heading":"在暴风雨中耶和华的威声","verses":[{"n":1,"t":"神的众子啊，你们要将荣耀、能力归给耶和华，归给耶和华！","notes":[]},{"n":2,"t":"要将耶和华的名所当得的荣耀归给他，以圣洁的妆饰敬拜耶和华。","notes":["的：或译为"]},{"n":3,"t":"耶和华的声音发在水上；荣耀的神打雷，耶和华打雷在大水之上。","notes":[]},{"n":4,"t":"耶和华的声音大有能力；耶和华的声音满有威严。","notes":[]},{"n":5,"t":"耶和华的声音震破香柏树；耶和华震碎黎巴嫩的香柏树。","notes":[]},{"n":6,"t":"他也使之跳跃如牛犊，使黎巴嫩和西连跳跃如野牛犊。","notes":[]},{"n":7,"t":"耶和华的声音使火焰分岔。","notes":[]},{"n":8,"t":"耶和华的声音震动旷野；耶和华震动加低斯的旷野。","notes":[]},{"n":9,"t":"耶和华的声音惊动母鹿落胎，树木也脱落净光。凡在他殿中的，都称说他的荣耀。","notes":[]},{"n":10,"t":"洪水泛滥之时，耶和华坐着为王；耶和华坐着为王，直到永远。","notes":[]},{"n":11,"t":"耶和华必赐力量给他的百姓；耶和华必赐平安的福给他的百姓。","notes":[]}]},"30":{"heading":"感恩的祷告","verses":[{"n":1,"t":"耶和华啊，我要尊崇你，因为你曾提拔我，不叫仇敌向我夸耀。","notes":[]},{"n":2,"t":"耶和华—我的神啊，我曾呼求你，你医治了我。","notes":[]},{"n":3,"t":"耶和华啊，你曾把我的灵魂从阴间救上来，使我存活，不至于下坑。","notes":[]},{"n":4,"t":"耶和华的圣民哪，你们要歌颂他，称赞他可记念的圣名。","notes":[]},{"n":5,"t":"因为，他的怒气不过是转眼之间；他的恩典乃是一生之久。一宿虽然有哭泣，早晨便必欢呼。","notes":[]},{"n":6,"t":"至于我，我凡事平顺，便说：我永不动摇。","notes":[]},{"n":7,"t":"耶和华啊，你曾施恩，叫我的江山稳固；你掩了面，我就惊惶。","notes":[]},{"n":8,"t":"耶和华啊，我曾求告你；我向耶和华恳求，说：","notes":[]},{"n":9,"t":"我被害流血，下到坑中，有什么益处呢？尘土岂能称赞你，传说你的诚实吗？","notes":[]},{"n":10,"t":"耶和华啊，求你应允我，怜恤我！耶和华啊，求你帮助我！","notes":[]},{"n":11,"t":"你已将我的哀哭变为跳舞，将我的麻衣脱去，给我披上喜乐，","notes":[]},{"n":12,"t":"好叫我的灵歌颂你，并不住声。耶和华—我的神啊，我要称谢你，直到永远！","notes":["原文是荣耀"]}]},"31":{"heading":"信靠神的祈祷","verses":[{"n":1,"t":"耶和华啊，我投靠你；求你使我永不羞愧；凭你的公义搭救我！","notes":[]},{"n":2,"t":"求你侧耳而听，快快救我！作我坚固的磐石，拯救我的保障！","notes":[]},{"n":3,"t":"因为你是我的岩石，我的山寨；所以，求你为你名的缘故引导我，指点我。","notes":[]},{"n":4,"t":"求你救我脱离人为我暗设的网罗，因为你是我的保障。","notes":[]},{"n":5,"t":"我将我的灵魂交在你手里；耶和华诚实的神啊，你救赎了我。","notes":[]},{"n":6,"t":"我恨恶那信奉虚无之神的人；我却倚靠耶和华。","notes":[]},{"n":7,"t":"我要为你的慈爱高兴欢喜；因为你见过我的困苦，知道我心中的艰难。","notes":[]},{"n":8,"t":"你未曾把我交在仇敌手里；你使我的脚站在宽阔之处。","notes":[]},{"n":9,"t":"耶和华啊，求你怜恤我，因为我在急难之中；我的眼睛因忧愁而干瘪，连我的身心也不安舒。","notes":[]},{"n":10,"t":"我的生命为愁苦所消耗；我的年岁为叹息所旷废。我的力量因我的罪孽衰败；我的骨头也枯干。","notes":[]},{"n":11,"t":"我因一切敌人成了羞辱，在我的邻舍跟前更甚；那认识我的都惧怕我，在外头看见我的都躲避我。","notes":[]},{"n":12,"t":"我被人忘记，如同死人，无人记念；我好像破碎的器皿。","notes":[]},{"n":13,"t":"我听见了许多人的谗谤，四围都是惊吓；他们一同商议攻击我的时候，就图谋要害我的性命。","notes":[]},{"n":14,"t":"耶和华啊，我仍旧倚靠你；我说：你是我的神。","notes":[]},{"n":15,"t":"我终身的事在你手中；求你救我脱离仇敌的手和那些逼迫我的人。","notes":[]},{"n":16,"t":"求你使你的脸光照仆人，凭你的慈爱拯救我。","notes":[]},{"n":17,"t":"耶和华啊，求你叫我不致羞愧，因为我曾呼吁你；求你使恶人羞愧，使他们在阴间缄默无声。","notes":[]},{"n":18,"t":"那撒谎的人逞骄傲轻慢，出狂妄的话攻击义人；愿他的嘴哑而无言。","notes":[]},{"n":19,"t":"敬畏你、投靠你的人，你为他们所积存的，在世人面前所施行的恩惠是何等大呢！","notes":[]},{"n":20,"t":"你必把他们藏在你面前的隐密处，免得遇见人的计谋；你必暗暗地保守他们在亭子里，免受口舌的争闹。","notes":[]},{"n":21,"t":"耶和华是应当称颂的，因为他在坚固城里向我施展奇妙的慈爱。","notes":[]},{"n":22,"t":"至于我，我曾急促地说：我从你眼前被隔绝。然而，我呼求你的时候，你仍听我恳求的声音。","notes":[]},{"n":23,"t":"耶和华的圣民哪，你们都要爱他！耶和华保护诚实人，足足报应行事骄傲的人。","notes":[]},{"n":24,"t":"凡仰望耶和华的人，你们都要壮胆，坚固你们的心！","notes":[]}]},"32":{"heading":"认罪与蒙赦","verses":[{"n":1,"t":"得赦免其过、遮盖其罪的，这人是有福的！","notes":[]},{"n":2,"t":"凡心里没有诡诈、耶和华不算为有罪的，这人是有福的！","notes":[]},{"n":3,"t":"我闭口不认罪的时候，因终日唉哼而骨头枯干。","notes":[]},{"n":4,"t":"黑夜白日，你的手在我身上沉重；我的精液耗尽，如同夏天的干旱。 （细拉）","notes":[]},{"n":5,"t":"我向你陈明我的罪，不隐瞒我的恶。我说：我要向耶和华承认我的过犯，你就赦免我的罪恶。 （细拉）","notes":[]},{"n":6,"t":"为此，凡虔诚人都当趁你可寻找的时候祷告你；大水泛溢的时候，必不能到他那里。","notes":[]},{"n":7,"t":"你是我藏身之处；你必保佑我脱离苦难，以得救的乐歌四面环绕我。 （细拉）","notes":[]},{"n":8,"t":"我要教导你，指示你当行的路；我要定睛在你身上劝戒你。","notes":[]},{"n":9,"t":"你不可像那无知的骡马，必用嚼环辔头勒住它；不然，就不能驯服。","notes":[]},{"n":10,"t":"恶人必多受苦楚；惟独倚靠耶和华的必有慈爱四面环绕他。","notes":[]},{"n":11,"t":"你们义人应当靠耶和华欢喜快乐；你们心里正直的人都当欢呼。","notes":[]}]},"33":{"heading":"颂赞之歌","verses":[{"n":1,"t":"义人哪，你们应当靠耶和华欢乐；正直人的赞美是合宜的。","notes":[]},{"n":2,"t":"你们应当弹琴称谢耶和华，用十弦瑟歌颂他。","notes":[]},{"n":3,"t":"应当向他唱新歌，弹得巧妙，声音洪亮。","notes":[]},{"n":4,"t":"因为耶和华的言语正直；凡他所做的尽都诚实。","notes":[]},{"n":5,"t":"他喜爱仁义公平；遍地满了耶和华的慈爱。","notes":[]},{"n":6,"t":"诸天借耶和华的命而造；万象借他口中的气而成。","notes":[]},{"n":7,"t":"他聚集海水如垒，收藏深洋在库房。","notes":[]},{"n":8,"t":"愿全地都敬畏耶和华！愿世上的居民都惧怕他！","notes":[]},{"n":9,"t":"因为他说有，就有，命立，就立。","notes":[]},{"n":10,"t":"耶和华使列国的筹算归于无有，使众民的思念无有功效。","notes":[]},{"n":11,"t":"耶和华的筹算永远立定；他心中的思念万代常存。","notes":[]},{"n":12,"t":"以耶和华为神的，那国是有福的！他所拣选为自己产业的，那民是有福的！","notes":[]},{"n":13,"t":"耶和华从天上观看；他看见一切的世人。","notes":[]},{"n":14,"t":"从他的居所往外察看地上一切的居民—","notes":[]},{"n":15,"t":"他是那造成他们众人心的，留意他们一切作为的。","notes":[]},{"n":16,"t":"君王不能因兵多得胜；勇士不能因力大得救。","notes":[]},{"n":17,"t":"靠马得救是枉然的；马也不能因力大救人。","notes":[]},{"n":18,"t":"耶和华的眼目看顾敬畏他的人和仰望他慈爱的人，","notes":[]},{"n":19,"t":"要救他们的命脱离死亡，并使他们在饥荒中存活。","notes":[]},{"n":20,"t":"我们的心向来等候耶和华；他是我们的帮助，我们的盾牌。","notes":[]},{"n":21,"t":"我们的心必靠他欢喜，因为我们向来倚靠他的圣名。","notes":[]},{"n":22,"t":"耶和华啊，求你照着我们所仰望你的，向我们施行慈爱！","notes":[]}]},"34":{"heading":"颂赞神的美善","verses":[{"n":1,"t":"我要时时称颂耶和华；赞美他的话必常在我口中。","notes":[]},{"n":2,"t":"我的心必因耶和华夸耀；谦卑人听见就要喜乐。","notes":[]},{"n":3,"t":"你们和我当称耶和华为大，一同高举他的名。","notes":[]},{"n":4,"t":"我曾寻求耶和华，他就应允我，救我脱离了一切的恐惧。","notes":[]},{"n":5,"t":"凡仰望他的，便有光荣；他们的脸必不蒙羞。","notes":[]},{"n":6,"t":"我这困苦人呼求，耶和华便垂听，救我脱离一切患难。","notes":[]},{"n":7,"t":"耶和华的使者在敬畏他的人四围安营，搭救他们。","notes":[]},{"n":8,"t":"你们要尝尝主恩的滋味，便知道他是美善；投靠他的人有福了！","notes":[]},{"n":9,"t":"耶和华的圣民哪，你们当敬畏他，因敬畏他的一无所缺。","notes":[]},{"n":10,"t":"少壮狮子还缺食忍饿，但寻求耶和华的什么好处都不缺。","notes":[]},{"n":11,"t":"众弟子啊，你们当来听我的话！我要将敬畏耶和华的道教训你们。","notes":[]},{"n":12,"t":"有何人喜好存活，爱慕长寿，得享美福，","notes":[]},{"n":13,"t":"就要禁止舌头不出恶言，嘴唇不说诡诈的话。","notes":[]},{"n":14,"t":"要离恶行善，寻求和睦，一心追赶。","notes":[]},{"n":15,"t":"耶和华的眼目看顾义人；他的耳朵听他们的呼求。","notes":[]},{"n":16,"t":"耶和华向行恶的人变脸，要从世上除灭他们的名号。","notes":[]},{"n":17,"t":"义人呼求，耶和华听见了，便救他们脱离一切患难。","notes":[]},{"n":18,"t":"耶和华靠近伤心的人，拯救灵性痛悔的人。","notes":[]},{"n":19,"t":"义人多有苦难，但耶和华救他脱离这一切，","notes":[]},{"n":20,"t":"又保全他一身的骨头，连一根也不折断。","notes":[]},{"n":21,"t":"恶必害死恶人；恨恶义人的，必被定罪。","notes":[]},{"n":22,"t":"耶和华救赎他仆人的灵魂；凡投靠他的，必不致定罪。","notes":[]}]},"35":{"heading":"求助的祷告","verses":[{"n":1,"t":"耶和华啊，与我相争的，求你与他们相争！与我相战的，求你与他们相战！","notes":[]},{"n":2,"t":"拿着大小的盾牌，起来帮助我。","notes":[]},{"n":3,"t":"抽出枪来，挡住那追赶我的；求你对我的灵魂说：我是拯救你的。","notes":[]},{"n":4,"t":"愿那寻索我命的，蒙羞受辱！愿那谋害我的，退后羞愧！","notes":[]},{"n":5,"t":"愿他们像风前的糠，有耶和华的使者赶逐他们。","notes":[]},{"n":6,"t":"愿他们的道路又暗又滑，有耶和华的使者追赶他们。","notes":[]},{"n":7,"t":"因他们无故地为我暗设网罗，无故地挖坑，要害我的性命。","notes":[]},{"n":8,"t":"愿灾祸忽然临到他身上！愿他暗设的网缠住自己！愿他落在其中遭灾祸！","notes":[]},{"n":9,"t":"我的心必靠耶和华快乐，靠他的救恩高兴。","notes":[]},{"n":10,"t":"我的骨头都要说：耶和华啊，谁能像你救护困苦人脱离那比他强壮的，救护困苦穷乏人脱离那抢夺他的？","notes":[]},{"n":11,"t":"凶恶的见证人起来，盘问我所不知道的事。","notes":[]},{"n":12,"t":"他们向我以恶报善，使我的灵魂孤苦。","notes":[]},{"n":13,"t":"至于我，当他们有病的时候，我便穿麻衣，禁食，刻苦己心；我所求的都归到自己的怀中。","notes":[]},{"n":14,"t":"我这样行，好像他是我的朋友，我的弟兄；我屈身悲哀，如同人为母亲哀痛。","notes":[]},{"n":15,"t":"我在患难中，他们却欢喜，大家聚集。我所不认识的那些下流人聚集攻击我；他们不住地把我撕裂。","notes":[]},{"n":16,"t":"他们如同席上好嬉笑的狂妄人向我咬牙。","notes":[]},{"n":17,"t":"主啊，你看着不理要到几时呢？求你救我的灵魂脱离他们的残害！救我的生命脱离少壮狮子！","notes":["生命：原文是独一者"]},{"n":18,"t":"我在大会中要称谢你，在众民中要赞美你。","notes":[]},{"n":19,"t":"求你不容那无理与我为仇的向我夸耀！不容那无故恨我的向我挤眼！","notes":[]},{"n":20,"t":"因为他们不说和平话，倒想出诡诈的言语害地上的安静人。","notes":[]},{"n":21,"t":"他们大大张口攻击我，说：阿哈，阿哈，我们的眼已经看见了！","notes":[]},{"n":22,"t":"耶和华啊，你已经看见了，求你不要闭口！主啊，求你不要远离我！","notes":[]},{"n":23,"t":"我的神我的主啊，求你奋兴醒起，判清我的事，伸明我的冤！","notes":[]},{"n":24,"t":"耶和华—我的神啊，求你按你的公义判断我，不容他们向我夸耀！","notes":[]},{"n":25,"t":"不容他们心里说：阿哈，遂我们的心愿了！不容他们说：我们已经把他吞了！","notes":[]},{"n":26,"t":"愿那喜欢我遭难的一同抱愧蒙羞！愿那向我妄自尊大的披惭愧，蒙羞辱！","notes":[]},{"n":27,"t":"愿那喜悦我冤屈得伸的欢呼快乐；愿他们常说：当尊耶和华为大！耶和华喜悦他的仆人平安。","notes":["冤屈得伸：原文是公义"]},{"n":28,"t":"我的舌头要终日论说你的公义，时常赞美你。","notes":[]}]},"36":{"heading":"人的邪恶","verses":[{"n":1,"t":"恶人的罪过在他心里说：我眼中不怕神！","notes":[]},{"n":2,"t":"他自夸自媚，以为他的罪孽终不显露，不被恨恶。","notes":[]},{"n":3,"t":"他口中的言语尽是罪孽诡诈；他与智慧善行已经断绝。","notes":[]},{"n":4,"t":"他在床上图谋罪孽，定意行不善的道，不憎恶恶事。","notes":[]},{"n":5,"t":"耶和华啊，你的慈爱上及诸天；你的信实达到穹苍。","notes":[],"heads":["神的良善"]},{"n":6,"t":"你的公义好像高山；你的判断如同深渊。耶和华啊，人民、牲畜，你都救护。","notes":[]},{"n":7,"t":"神啊，你的慈爱何其宝贵！世人投靠在你翅膀的荫下。","notes":[]},{"n":8,"t":"他们必因你殿里的肥甘得以饱足；你也必叫他们喝你乐河的水。","notes":[]},{"n":9,"t":"因为，在你那里有生命的源头；在你的光中，我们必得见光。","notes":[]},{"n":10,"t":"愿你常施慈爱给认识你的人，常以公义待心里正直的人。","notes":[]},{"n":11,"t":"不容骄傲人的脚践踏我；不容凶恶人的手赶逐我。","notes":[]},{"n":12,"t":"在那里，作孽的人已经仆倒；他们被推倒，不能再起来。","notes":[]}]},"37":{"heading":"义人和恶人的结局","verses":[{"n":1,"t":"不要为作恶的心怀不平，也不要向那行不义的生出嫉妒。","notes":[]},{"n":2,"t":"因为他们如草快被割下，又如青菜快要枯干。","notes":[]},{"n":3,"t":"你当倚靠耶和华而行善，住在地上，以他的信实为粮；","notes":[]},{"n":4,"t":"又要以耶和华为乐，他就将你心里所求的赐给你。","notes":[]},{"n":5,"t":"当将你的事交托耶和华，并倚靠他，他就必成全。","notes":[]},{"n":6,"t":"他要使你的公义如光发出，使你的公平明如正午。","notes":[]},{"n":7,"t":"你当默然倚靠耶和华，耐性等候他；不要因那道路通达的和那恶谋成就的心怀不平。","notes":[]},{"n":8,"t":"当止住怒气，离弃忿怒；不要心怀不平，以致作恶。","notes":[]},{"n":9,"t":"因为作恶的必被剪除；惟有等候耶和华的必承受地土。","notes":[]},{"n":10,"t":"还有片时，恶人要归于无有；你就是细察他的住处也要归于无有。","notes":[]},{"n":11,"t":"但谦卑人必承受地土，以丰盛的平安为乐。","notes":[]},{"n":12,"t":"恶人设谋害义人，又向他咬牙。","notes":[]},{"n":13,"t":"主要笑他，因见他受罚的日子将要来到。","notes":[]},{"n":14,"t":"恶人已经弓上弦，刀出鞘，要打倒困苦穷乏的人，要杀害行动正直的人。","notes":[]},{"n":15,"t":"他们的刀必刺入自己的心；他们的弓必被折断。","notes":[]},{"n":16,"t":"一个义人所有的虽少，强过许多恶人的富余。","notes":[]},{"n":17,"t":"因为恶人的膀臂必被折断；但耶和华是扶持义人。","notes":[]},{"n":18,"t":"耶和华知道完全人的日子；他们的产业要存到永远。","notes":[]},{"n":19,"t":"他们在急难的时候不致羞愧，在饥荒的日子必得饱足。","notes":[]},{"n":20,"t":"恶人却要灭亡。耶和华的仇敌要像羊羔的脂油；他们要消灭，要如烟消灭。","notes":["或译：像草地的华美"]},{"n":21,"t":"恶人借贷而不偿还；义人却恩待人，并且施舍。","notes":[]},{"n":22,"t":"蒙耶和华赐福的必承受地土；被他咒诅的必被剪除。","notes":[]},{"n":23,"t":"义人的脚步被耶和华立定；他的道路，耶和华也喜爱。","notes":[]},{"n":24,"t":"他虽失脚也不至全身仆倒，因为耶和华用手搀扶他。","notes":["或译：搀扶他的手"]},{"n":25,"t":"我从前年幼，现在年老，却未见过义人被弃，也未见过他的后裔讨饭。","notes":[]},{"n":26,"t":"他终日恩待人，借给人；他的后裔也蒙福！","notes":[]},{"n":27,"t":"你当离恶行善，就可永远安居。","notes":[]},{"n":28,"t":"因为，耶和华喜爱公平，不撇弃他的圣民；他们永蒙保佑，但恶人的后裔必被剪除。","notes":[]},{"n":29,"t":"义人必承受地土，永居其上。","notes":[]},{"n":30,"t":"义人的口谈论智慧；他的舌头讲说公平。","notes":[]},{"n":31,"t":"神的律法在他心里；他的脚总不滑跌。","notes":[]},{"n":32,"t":"恶人窥探义人，想要杀他。","notes":[]},{"n":33,"t":"耶和华必不撇他在恶人手中；当审判的时候，也不定他的罪。","notes":[]},{"n":34,"t":"你当等候耶和华，遵守他的道，他就抬举你，使你承受地土；恶人被剪除的时候，你必看见。","notes":[]},{"n":35,"t":"我见过恶人大有势力，好像一棵青翠树在本土生发。","notes":[]},{"n":36,"t":"有人从那里经过，不料，他没有了；我也寻找他，却寻不着。","notes":[]},{"n":37,"t":"你要细察那完全人，观看那正直人，因为和平人有好结局。","notes":[]},{"n":38,"t":"至于犯法的人，必一同灭绝；恶人终必剪除。","notes":[]},{"n":39,"t":"但义人得救是由于耶和华；他在患难时作他们的营寨。","notes":[]},{"n":40,"t":"耶和华帮助他们，解救他们；他解救他们脱离恶人，把他们救出来，因为他们投靠他。","notes":[]}]},"38":{"heading":"受苦者的祈祷","verses":[{"n":1,"t":"耶和华啊，求你不要在怒中责备我，不要在烈怒中惩罚我！","notes":[]},{"n":2,"t":"因为，你的箭射入我身；你的手压住我。","notes":[]},{"n":3,"t":"因你的恼怒，我的肉无一完全；因我的罪过，我的骨头也不安宁。","notes":[]},{"n":4,"t":"我的罪孽高过我的头，如同重担叫我担当不起。","notes":[]},{"n":5,"t":"因我的愚昧，我的伤发臭流脓。","notes":[]},{"n":6,"t":"我疼痛，大大拳曲，终日哀痛。","notes":[]},{"n":7,"t":"我满腰是火；我的肉无一完全。","notes":[]},{"n":8,"t":"我被压伤，身体疲倦；因心里不安，我就唉哼。","notes":[]},{"n":9,"t":"主啊，我的心愿都在你面前；我的叹息不向你隐瞒。","notes":[]},{"n":10,"t":"我心跳动，我力衰微，连我眼中的光也没有了。","notes":[]},{"n":11,"t":"我的良朋密友因我的灾病都躲在旁边站着；我的亲戚本家也远远地站立。","notes":[]},{"n":12,"t":"那寻索我命的设下网罗；那想要害我的口出恶言，终日思想诡计。","notes":[]},{"n":13,"t":"但我如聋子不听，像哑巴不开口。","notes":[]},{"n":14,"t":"我如不听见的人，口中没有回话。","notes":[]},{"n":15,"t":"耶和华啊，我仰望你！主—我的神啊，你必应允我！","notes":[]},{"n":16,"t":"我曾说：恐怕他们向我夸耀；我失脚的时候，他们向我夸大。","notes":[]},{"n":17,"t":"我几乎跌倒；我的痛苦常在我面前。","notes":[]},{"n":18,"t":"我要承认我的罪孽；我要因我的罪忧愁。","notes":[]},{"n":19,"t":"但我的仇敌又活泼又强壮，无理恨我的增多了。","notes":[]},{"n":20,"t":"以恶报善的与我作对，因我是追求良善。","notes":[]},{"n":21,"t":"耶和华啊，求你不要撇弃我！我的神啊，求你不要远离我！","notes":[]},{"n":22,"t":"拯救我的主啊，求你快快帮助我！","notes":[]}]},"39":{"heading":"受苦者的认罪","verses":[{"n":1,"t":"我曾说：我要谨慎我的言行，免得我舌头犯罪；恶人在我面前的时候，我要用嚼环勒住我的口。","notes":[]},{"n":2,"t":"我默然无声，连好话也不出口；我的愁苦就发动了，","notes":[]},{"n":3,"t":"我的心在我里面发热。我默想的时候，火就烧起，我便用舌头说话。","notes":[]},{"n":4,"t":"耶和华啊，求你叫我晓得我身之终！我的寿数几何？叫我知道我的生命不长！","notes":[]},{"n":5,"t":"你使我的年日窄如手掌；我一生的年数，在你面前如同无有。各人最稳妥的时候，真是全然虚幻。 （细拉）","notes":[]},{"n":6,"t":"世人行动实系幻影。他们忙乱，真是枉然；积蓄财宝，不知将来有谁收取。","notes":[]},{"n":7,"t":"主啊，如今我等什么呢？我的指望在乎你！","notes":[]},{"n":8,"t":"求你救我脱离一切的过犯，不要使我受愚顽人的羞辱。","notes":[]},{"n":9,"t":"因我所遭遇的是出于你，我就默然不语。","notes":[]},{"n":10,"t":"求你把你的责罚从我身上免去；因你手的责打，我便消灭。","notes":[]},{"n":11,"t":"你因人的罪恶惩罚他的时候，叫他的笑容消灭，如衣被虫所咬。世人真是虚幻！ （细拉）","notes":["的笑容：或译所喜爱的"]},{"n":12,"t":"耶和华啊，求你听我的祷告，留心听我的呼求！我流泪，求你不要静默无声！因为我在你面前是客旅，是寄居的，像我列祖一般。","notes":[]},{"n":13,"t":"求你宽容我，使我在去而不返之先可以力量复原。","notes":[]}]},"40":{"heading":"颂赞之歌","verses":[{"n":1,"t":"我曾耐性等候耶和华；他垂听我的呼求。","notes":[]},{"n":2,"t":"他从祸坑里，从淤泥中，把我拉上来，使我的脚立在磐石上，使我脚步稳当。","notes":[]},{"n":3,"t":"他使我口唱新歌，就是赞美我们神的话。许多人必看见而惧怕，并要倚靠耶和华。","notes":[]},{"n":4,"t":"那倚靠耶和华、不理会狂傲和偏向虚假之辈的，这人便为有福！","notes":[]},{"n":5,"t":"耶和华—我的神啊，你所行的奇事，并你向我们所怀的意念甚多，不能向你陈明；若要陈明，其事不可胜数。","notes":[]},{"n":6,"t":"祭物和礼物，你不喜悦；你已经开通我的耳朵。燔祭和赎罪祭非你所要。","notes":[]},{"n":7,"t":"那时我说：看哪，我来了！我的事在经卷上已经记载了。","notes":[]},{"n":8,"t":"我的神啊，我乐意照你的旨意行；你的律法在我心里。","notes":[]},{"n":9,"t":"我在大会中宣传公义的佳音；我必不止住我的嘴唇。耶和华啊，这是你所知道的。","notes":[]},{"n":10,"t":"我未曾把你的公义藏在心里；我已陈明你的信实和你的救恩；我在大会中未曾隐瞒你的慈爱和诚实。","notes":[]},{"n":11,"t":"耶和华啊，求你不要向我止住你的慈悲！愿你的慈爱和诚实常常保佑我！","notes":[]},{"n":12,"t":"因有无数的祸患围困我，我的罪孽追上了我，使我不能昂首；这罪孽比我的头发还多，我就心寒胆战。","notes":[],"heads":["求助的祷告"]},{"n":13,"t":"耶和华啊，求你开恩搭救我！耶和华啊，求你速速帮助我！","notes":[]},{"n":14,"t":"愿那些寻找我、要灭我命的，一同抱愧蒙羞！愿那些喜悦我受害的，退后受辱！","notes":[]},{"n":15,"t":"愿那些对我说阿哈、阿哈的，因羞愧而败亡！","notes":[]},{"n":16,"t":"愿一切寻求你的，因你高兴欢喜！愿那些喜爱你救恩的，常说：当尊耶和华为大！","notes":[]},{"n":17,"t":"但我是困苦穷乏的，主仍顾念我；你是帮助我的，搭救我的。神啊，求你不要耽延！","notes":[]}]},"41":{"heading":"病中祈祷","verses":[{"n":1,"t":"眷顾贫穷的有福了！他遭难的日子，耶和华必搭救他。","notes":[]},{"n":2,"t":"耶和华必保全他，使他存活；他必在地上享福。求你不要把他交给仇敌，遂其所愿。","notes":[]},{"n":3,"t":"他病重在榻，耶和华必扶持他；他在病中，你必给他铺床。","notes":[]},{"n":4,"t":"我曾说：耶和华啊，求你怜恤我，医治我！因为我得罪了你。","notes":[]},{"n":5,"t":"我的仇敌用恶言议论我说：他几时死，他的名才灭亡呢？","notes":[]},{"n":6,"t":"他来看我就说假话；他心存奸恶，走到外边才说出来。","notes":[]},{"n":7,"t":"一切恨我的，都交头接耳地议论我；他们设计要害我。","notes":[]},{"n":8,"t":"他们说：有怪病贴在他身上；他已躺卧，必不能再起来。","notes":[]},{"n":9,"t":"连我知己的朋友，我所倚靠、吃过我饭的也用脚踢我。","notes":[]},{"n":10,"t":"耶和华啊，求你怜恤我，使我起来，好报复他们！","notes":[]},{"n":11,"t":"因我的仇敌不得向我夸胜，我从此便知道你喜爱我。","notes":[]},{"n":12,"t":"你因我纯正就扶持我，使我永远站在你的面前。","notes":[]},{"n":13,"t":"耶和华—以色列的神是应当称颂的，从亘古直到永远。阿们！阿们！","notes":[]}]},"42":{"heading":"流亡异乡者的祷告（一）","verses":[{"n":1,"t":"神啊，我的心切慕你，如鹿切慕溪水。","notes":[]},{"n":2,"t":"我的心渴想神，就是永生神；我几时得朝见神呢？","notes":[]},{"n":3,"t":"我昼夜以眼泪当饮食；人不住地对我说：你的神在哪里呢？","notes":[]},{"n":4,"t":"我从前与众人同往，用欢呼称赞的声音领他们到神的殿里，大家守节。我追想这些事，我的心极其悲伤。","notes":[]},{"n":5,"t":"我的心哪，你为何忧闷？为何在我里面烦躁？应当仰望神，因他笑脸帮助我；我还要称赞他。","notes":[]},{"n":6,"t":"我的神啊，我的心在我里面忧闷，所以我从约旦地，从黑门岭，从米萨山记念你。","notes":[]},{"n":7,"t":"你的瀑布发声，深渊就与深渊响应；你的波浪洪涛漫过我身。","notes":[]},{"n":8,"t":"白昼，耶和华必向我施慈爱；黑夜，我要歌颂祷告赐我生命的神。","notes":[]},{"n":9,"t":"我要对神—我的磐石说：你为何忘记我呢？我为何因仇敌的欺压时常哀痛呢？","notes":[]},{"n":10,"t":"我的敌人辱骂我，好像打碎我的骨头，不住地对我说：你的神在哪里呢？","notes":[]},{"n":11,"t":"我的心哪，你为何忧闷？为何在我里面烦躁？应当仰望神，因我还要称赞他。他是我脸上的光荣，是我的神。","notes":["原文是帮助"]}]},"43":{"heading":"流亡异乡者的祷告（二）","verses":[{"n":1,"t":"神啊，求你伸我的冤，向不虔诚的国为我辨屈；求你救我脱离诡诈不义的人。","notes":[]},{"n":2,"t":"因为你是赐我力量的神，为何丢弃我呢？我为何因仇敌的欺压时常哀痛呢？","notes":[]},{"n":3,"t":"求你发出你的亮光和真实，好引导我，带我到你的圣山，到你的居所！","notes":[]},{"n":4,"t":"我就走到神的祭坛，到我最喜乐的神那里。神啊，我的神，我要弹琴称赞你！","notes":[]},{"n":5,"t":"我的心哪，你为何忧闷？为何在我里面烦躁？应当仰望神，因我还要称赞他。他是我脸上的光荣，是我的神。","notes":["原文是帮助"]}]},"44":{"heading":"求主保护","verses":[{"n":1,"t":"神啊，你在古时，我们列祖的日子所行的事，我们亲耳听见了；我们的列祖也给我们述说过。","notes":[]},{"n":2,"t":"你曾用手赶出外邦人，却栽培了我们列祖；你苦待列邦，却叫我们列祖发达。","notes":[]},{"n":3,"t":"因为他们不是靠自己的刀剑得地土，也不是靠自己的膀臂得胜，乃是靠你的右手、你的膀臂，和你脸上的亮光，因为你喜悦他们。","notes":[]},{"n":4,"t":"神啊，你是我的王；求你出令使雅各得胜。","notes":[]},{"n":5,"t":"我们靠你要推倒我们的敌人，靠你的名要践踏那起来攻击我们的人。","notes":[]},{"n":6,"t":"因为，我必不靠我的弓；我的刀也不能使我得胜。","notes":[]},{"n":7,"t":"惟你救了我们脱离敌人，使恨我们的人羞愧。","notes":[]},{"n":8,"t":"我们终日因神夸耀，还要永远称谢你的名。 （细拉）","notes":[]},{"n":9,"t":"但如今你丢弃了我们，使我们受辱，不和我们的军兵同去。","notes":[]},{"n":10,"t":"你使我们向敌人转身退后；那恨我们的人任意抢夺。","notes":[]},{"n":11,"t":"你使我们当作快要被吃的羊，把我们分散在列邦中。","notes":[]},{"n":12,"t":"你卖了你的子民也不赚利，所得的价值并不加添你的资财。","notes":[]},{"n":13,"t":"你使我们受邻国的羞辱，被四围的人嗤笑讥刺。","notes":[]},{"n":14,"t":"你使我们在列邦中作了笑谈，使众民向我们摇头。","notes":[]},{"n":15,"t":"我的凌辱终日在我面前，我脸上的羞愧将我遮蔽，","notes":[]},{"n":16,"t":"都因那辱骂毁谤人的声音，又因仇敌和报仇人的缘故。","notes":[]},{"n":17,"t":"这都临到我们身上，我们却没有忘记你，也没有违背你的约。","notes":[]},{"n":18,"t":"我们的心没有退后；我们的脚也没有偏离你的路。","notes":[]},{"n":19,"t":"你在野狗之处压伤我们，用死荫遮蔽我们。","notes":[]},{"n":20,"t":"倘若我们忘了神的名，或向别神举手，","notes":[]},{"n":21,"t":"神岂不鉴察这事吗？因为他晓得人心里的隐秘。","notes":[]},{"n":22,"t":"我们为你的缘故终日被杀；人看我们如将宰的羊。","notes":[]},{"n":23,"t":"主啊，求你睡醒，为何尽睡呢？求你兴起，不要永远丢弃我们！","notes":[]},{"n":24,"t":"你为何掩面，不顾我们所遭的苦难和所受的欺压？","notes":[]},{"n":25,"t":"我们的性命伏于尘土；我们的肚腹紧贴地面。","notes":[]},{"n":26,"t":"求你起来帮助我们！凭你的慈爱救赎我们！","notes":[]}]},"45":{"heading":"王家婚礼诗歌","verses":[{"n":1,"t":"我心里涌出美辞；我论到我为王做的事，我的舌头是快手笔。","notes":[]},{"n":2,"t":"你比世人更美；在你嘴里满有恩惠；所以神赐福给你，直到永远。","notes":[]},{"n":3,"t":"大能者啊，愿你腰间佩刀，大有荣耀和威严！","notes":[]},{"n":4,"t":"为真理、谦卑、公义赫然坐车前往，无不得胜；你的右手必显明可畏的事。","notes":[]},{"n":5,"t":"你的箭锋快，射中王敌之心；万民仆倒在你以下。","notes":[]},{"n":6,"t":"神啊，你的宝座是永永远远的；你的国权是正直的。","notes":[]},{"n":7,"t":"你喜爱公义，恨恶罪恶；所以神—就是你的神—用喜乐油膏你，胜过膏你的同伴。","notes":[]},{"n":8,"t":"你的衣服都有没药、沉香、肉桂的香气；象牙宫中有丝弦乐器的声音使你欢喜。","notes":[]},{"n":9,"t":"有君王的女儿在你尊贵妇女之中；王后佩戴俄斐金饰站在你右边。","notes":[]},{"n":10,"t":"女子啊，你要听，要想，要侧耳而听！不要记念你的民和你的父家，","notes":[]},{"n":11,"t":"王就羡慕你的美貌；因为他是你的主，你当敬拜他。","notes":[]},{"n":12,"t":"泰尔的民必来送礼；民中的富足人也必向你求恩。","notes":["原文是女子"]},{"n":13,"t":"王女在宫里极其荣华；她的衣服是用金线绣的。","notes":[]},{"n":14,"t":"她要穿锦绣的衣服，被引到王前；随从她的陪伴童女也要被带到你面前。","notes":[]},{"n":15,"t":"她们要欢喜快乐被引导；她们要进入王宫。","notes":[]},{"n":16,"t":"你的子孙要接续你的列祖；你要立他们在全地作王。","notes":[]},{"n":17,"t":"我必叫你的名被万代记念，所以万民要永永远远称谢你。","notes":[]}]},"46":{"heading":"神与我们同在","verses":[{"n":1,"t":"神是我们的避难所，是我们的力量，是我们在患难中随时的帮助。","notes":[]},{"n":2,"t":"所以，地虽改变，山虽摇动到海心，","notes":[]},{"n":3,"t":"其中的水虽匉訇翻腾，山虽因海涨而战抖，我们也不害怕。 （细拉）","notes":[]},{"n":4,"t":"有一道河，这河的分汊使神的城欢喜；这城就是至高者居住的圣所。","notes":[]},{"n":5,"t":"神在其中，城必不动摇；到天一亮，神必帮助这城。","notes":[]},{"n":6,"t":"外邦喧嚷，列国动摇；神发声，地便熔化。","notes":[]},{"n":7,"t":"万军之耶和华与我们同在；雅各的神是我们的避难所！ （细拉）","notes":[]},{"n":8,"t":"你们来看耶和华的作为，看他使地怎样荒凉。","notes":[]},{"n":9,"t":"他止息刀兵，直到地极；他折弓、断枪，把战车焚烧在火中。","notes":[]},{"n":10,"t":"你们要休息，要知道我是神！我必在外邦中被尊崇，在遍地上也被尊崇。","notes":[]},{"n":11,"t":"万军之耶和华与我们同在；雅各的神是我们的避难所！","notes":[]}]},"47":{"heading":"至高的主宰","verses":[{"n":1,"t":"万民哪，你们都要拍掌！要用夸胜的声音向神呼喊！","notes":[]},{"n":2,"t":"因为耶和华至高者是可畏的；他是治理全地的大君王。","notes":[]},{"n":3,"t":"他叫万民服在我们以下，又叫列邦服在我们脚下。","notes":[]},{"n":4,"t":"他为我们选择产业，就是他所爱之雅各的荣耀。 （细拉）","notes":[]},{"n":5,"t":"神上升，有喊声相送；耶和华上升，有角声相送。","notes":[]},{"n":6,"t":"你们要向神歌颂，歌颂！向我们王歌颂，歌颂！","notes":[]},{"n":7,"t":"因为神是全地的王；你们要用悟性歌颂。","notes":[]},{"n":8,"t":"神作王治理万国；神坐在他的圣宝座上。","notes":[]},{"n":9,"t":"列邦的君王聚集要作亚伯拉罕之神的民。因为世界的盾牌是属神的；他为至高！","notes":[]}]},"48":{"heading":"锡安—神的城","verses":[{"n":1,"t":"耶和华本为大！在我们神的城中，在他的圣山上，该受大赞美。","notes":[]},{"n":2,"t":"锡安山—大君王的城，在北面居高华美，为全地所喜悦。","notes":[]},{"n":3,"t":"神在其宫中，自显为避难所。","notes":[]},{"n":4,"t":"看哪，众王会合，一同经过。","notes":[]},{"n":5,"t":"他们见了这城就惊奇丧胆，急忙逃跑。","notes":[]},{"n":6,"t":"他们在那里被战兢疼痛抓住，好像产难的妇人一样。","notes":[]},{"n":7,"t":"神啊，你用东风打破他施的船只。","notes":[]},{"n":8,"t":"我们在万军之耶和华的城中—就是我们神的城中—所看见的，正如我们所听见的。神必坚立这城，直到永远。 （细拉）","notes":[]},{"n":9,"t":"神啊，我们在你的殿中想念你的慈爱。","notes":[]},{"n":10,"t":"神啊，你受的赞美正与你的名相称，直到地极！你的右手满了公义。","notes":[]},{"n":11,"t":"因你的判断，锡安山应当欢喜，犹大的城邑应当快乐。","notes":["原文是女子"]},{"n":12,"t":"你们当周游锡安，四围旋绕，数点城楼，","notes":[]},{"n":13,"t":"细看她的外郭，察看她的宫殿，为要传说到后代。","notes":[]},{"n":14,"t":"因为这神永永远远为我们的神；他必作我们引路的，直到死时。","notes":[]}]},"49":{"heading":"恃财之愚","verses":[{"n":1,"t":"万民哪，你们都当听这话！世上一切的居民，","notes":[]},{"n":2,"t":"无论上流下流，富足贫穷，都当留心听！","notes":[]},{"n":3,"t":"我口要说智慧的言语；我心要想通达的道理。","notes":[]},{"n":4,"t":"我要侧耳听比喻，用琴解谜语。","notes":[]},{"n":5,"t":"在患难的日子，奸恶随我脚跟，四面环绕我，我何必惧怕？","notes":[]},{"n":6,"t":"那些倚仗财货自夸钱财多的人，","notes":[]},{"n":7,"t":"一个也无法赎自己的弟兄，也不能替他将赎价给神，","notes":[]},{"n":8,"t":"叫他长远活着，不见朽坏；因为赎他生命的价值极贵，只可永远罢休。","notes":[],"end":9},{"n":10,"t":"他必见智慧人死，又见愚顽人和畜类人一同灭亡，将他们的财货留给别人。","notes":[]},{"n":11,"t":"他们心里思想：他们的家室必永存，住宅必留到万代；他们以自己的名称自己的地。","notes":[]},{"n":12,"t":"但人居尊贵中不能长久，如同死亡的畜类一样。","notes":[]},{"n":13,"t":"他们行的这道本为自己的愚昧；但他们以后的人还佩服他们的话语。 （细拉）","notes":[]},{"n":14,"t":"他们如同羊群派定下阴间；死亡必作他们的牧者。到了早晨，正直人必管辖他们；他们的美容必被阴间所灭，以致无处可存。","notes":[]},{"n":15,"t":"只是神必救赎我的灵魂脱离阴间的权柄，因他必收纳我。 （细拉）","notes":[]},{"n":16,"t":"见人发财、家室增荣的时候，你不要惧怕；","notes":[]},{"n":17,"t":"因为，他死的时候什么也不能带去；他的荣耀不能随他下去。","notes":[]},{"n":18,"t":"他活着的时候，虽然自夸为有福（你若利己，人必夸奖你）；","notes":[]},{"n":19,"t":"他仍必归到他历代的祖宗那里，永不见光。","notes":[]},{"n":20,"t":"人在尊贵中而不醒悟，就如死亡的畜类一样。","notes":[]}]},"50":{"heading":"真实的敬拜","verses":[{"n":1,"t":"大能者神—耶和华已经发言招呼天下，从日出之地到日落之处。","notes":[]},{"n":2,"t":"从全美的锡安中，神已经发光了。","notes":[]},{"n":3,"t":"我们的神要来，决不闭口。有烈火在他面前吞灭；有暴风在他四围大刮。","notes":[]},{"n":4,"t":"他招呼上天下地，为要审判他的民，","notes":[]},{"n":5,"t":"说：招聚我的圣民到我这里来，就是那些用祭物与我立约的人。","notes":[]},{"n":6,"t":"诸天必表明他的公义，因为神是施行审判的。 （细拉）","notes":[]},{"n":7,"t":"我的民哪，你们当听我的话！以色列啊，我要劝戒你；我是神，是你的神！","notes":[]},{"n":8,"t":"我并不因你的祭物责备你；你的燔祭常在我面前。","notes":[]},{"n":9,"t":"我不从你家中取公牛，也不从你圈内取山羊；","notes":[]},{"n":10,"t":"因为，树林中的百兽是我的，千山上的牲畜也是我的。","notes":[]},{"n":11,"t":"山中的飞鸟，我都知道；野地的走兽也都属我。","notes":[]},{"n":12,"t":"我若是饥饿，我不用告诉你，因为世界和其中所充满的都是我的。","notes":[]},{"n":13,"t":"我岂吃公牛的肉呢？我岂喝山羊的血呢？","notes":[]},{"n":14,"t":"你们要以感谢为祭献与神，又要向至高者还你的愿，","notes":[]},{"n":15,"t":"并要在患难之日求告我；我必搭救你，你也要荣耀我。","notes":[]},{"n":16,"t":"但神对恶人说：你怎敢传说我的律例，口中提到我的约呢？","notes":[]},{"n":17,"t":"其实你恨恶管教，将我的言语丢在背后。","notes":[]},{"n":18,"t":"你见了盗贼就乐意与他同伙，又与行奸淫的人一同有分。","notes":[]},{"n":19,"t":"你口任说恶言；你舌编造诡诈。","notes":[]},{"n":20,"t":"你坐着毁谤你的兄弟，谗毁你亲母的儿子。","notes":[]},{"n":21,"t":"你行了这些事，我还闭口不言，你想我恰和你一样；其实我要责备你，将这些事摆在你眼前。","notes":[]},{"n":22,"t":"你们忘记神的，要思想这事，免得我把你们撕碎，无人搭救。","notes":[]},{"n":23,"t":"凡以感谢献上为祭的便是荣耀我；那按正路而行的，我必使他得着我的救恩。","notes":[]}]},"51":{"heading":"求主赦免","verses":[{"n":1,"t":"神啊，求你按你的慈爱怜恤我！按你丰盛的慈悲涂抹我的过犯！","notes":[]},{"n":2,"t":"求你将我的罪孽洗除净尽，并洁除我的罪！","notes":[]},{"n":3,"t":"因为，我知道我的过犯；我的罪常在我面前。","notes":[]},{"n":4,"t":"我向你犯罪，惟独得罪了你；在你眼前行了这恶，以致你责备我的时候显为公义，判断我的时候显为清正。","notes":[]},{"n":5,"t":"我是在罪孽里生的，在我母亲怀胎的时候就有了罪。","notes":[]},{"n":6,"t":"你所喜爱的是内里诚实；你在我隐密处，必使我得智慧。","notes":[]},{"n":7,"t":"求你用牛膝草洁净我，我就干净；求你洗涤我，我就比雪更白。","notes":[]},{"n":8,"t":"求你使我得听欢喜快乐的声音，使你所压伤的骨头可以踊跃。","notes":[]},{"n":9,"t":"求你掩面不看我的罪，涂抹我一切的罪孽。","notes":[]},{"n":10,"t":"神啊，求你为我造清洁的心，使我里面重新有正直的灵。","notes":["或译：坚定"]},{"n":11,"t":"不要丢弃我，使我离开你的面；不要从我收回你的圣灵。","notes":[]},{"n":12,"t":"求你使我仍得救恩之乐，赐我乐意的灵扶持我，","notes":[]},{"n":13,"t":"我就把你的道指教有过犯的人，罪人必归顺你。","notes":[]},{"n":14,"t":"神啊，你是拯救我的神；求你救我脱离流人血的罪！我的舌头就高声歌唱你的公义。","notes":[]},{"n":15,"t":"主啊，求你使我嘴唇张开，我的口便传扬赞美你的话！","notes":[]},{"n":16,"t":"你本不喜爱祭物，若喜爱，我就献上；燔祭，你也不喜悦。","notes":[]},{"n":17,"t":"神所要的祭就是忧伤的灵；神啊，忧伤痛悔的心，你必不轻看。","notes":[]},{"n":18,"t":"求你随你的美意善待锡安，建造耶路撒冷的城墙。","notes":[]},{"n":19,"t":"那时，你必喜爱公义的祭和燔祭并全牲的燔祭；那时，人必将公牛献在你坛上。","notes":[]}]},"52":{"heading":"神的审判和恩惠","verses":[{"n":1,"t":"勇士啊，你为何以作恶自夸？神的慈爱是常存的。","notes":[]},{"n":2,"t":"你的舌头邪恶诡诈，好像剃头刀，快利伤人。","notes":[]},{"n":3,"t":"你爱恶胜似爱善，又爱说谎，不爱说公义。 （细拉）","notes":[]},{"n":4,"t":"诡诈的舌头啊，你爱说一切毁灭的话！","notes":[]},{"n":5,"t":"神也要毁灭你，直到永远；他要把你拿去，从你的帐棚中抽出，从活人之地将你拔出。 （细拉）","notes":[]},{"n":6,"t":"义人要看见而惧怕，并要笑他，","notes":[]},{"n":7,"t":"说：看哪，这就是那不以神为他力量的人，只倚仗他丰富的财物，在邪恶上坚立自己。","notes":[]},{"n":8,"t":"至于我，就像神殿中的青橄榄树；我永永远远倚靠神的慈爱。","notes":[]},{"n":9,"t":"我要称谢你，直到永远，因为你行了这事。我也要在你圣民面前仰望你的名；这名本为美好。","notes":[]}]},"53":{"heading":"人的邪恶","verses":[{"n":1,"t":"愚顽人心里说：没有神。他们都是邪恶，行了可憎恶的罪孽；没有一个人行善。","notes":[]},{"n":2,"t":"神从天上垂看世人，要看有明白的没有？有寻求他的没有？","notes":[]},{"n":3,"t":"他们各人都退后，一同变为污秽；并没有行善的，连一个也没有。","notes":[]},{"n":4,"t":"作孽的没有知识吗？他们吞吃我的百姓如同吃饭一样，并不求告神。","notes":[]},{"n":5,"t":"他们在无可惧怕之处就大大害怕，因为神把那安营攻击你之人的骨头散开了。你使他们蒙羞，因为神弃绝了他们。","notes":[]},{"n":6,"t":"但愿以色列的救恩从锡安而出。神救回他被掳的子民那时，雅各要快乐，以色列要欢喜。","notes":[]}]},"54":{"heading":"遭敌迫害求主保护","verses":[{"n":1,"t":"神啊，求你以你的名救我，凭你的大能为我伸冤。","notes":[]},{"n":2,"t":"神啊，求你听我的祷告，留心听我口中的言语。","notes":[]},{"n":3,"t":"因为，外人起来攻击我，强暴人寻索我的命；他们眼中没有神。 （细拉）","notes":[]},{"n":4,"t":"神是帮助我的，是扶持我命的。","notes":[]},{"n":5,"t":"他要报应我仇敌所行的恶；求你凭你的诚实灭绝他们。","notes":[]},{"n":6,"t":"我要把甘心祭献给你。耶和华啊，我要称赞你的名；这名本为美好。","notes":[]},{"n":7,"t":"他从一切的急难中把我救出来；我的眼睛也看见了我仇敌遭报。","notes":[]}]},"55":{"heading":"被友出卖者的祷告","verses":[{"n":1,"t":"神啊，求你留心听我的祷告，不要隐藏不听我的恳求！","notes":[]},{"n":2,"t":"求你侧耳听我，应允我。我哀叹不安，发声唉哼，","notes":[]},{"n":3,"t":"都因仇敌的声音，恶人的欺压；因为他们将罪孽加在我身上，发怒气逼迫我。","notes":[]},{"n":4,"t":"我心在我里面甚是疼痛；死的惊惶临到我身。","notes":[]},{"n":5,"t":"恐惧战兢归到我身；惊恐漫过了我。","notes":[]},{"n":6,"t":"我说：但愿我有翅膀像鸽子，我就飞去，得享安息。","notes":[]},{"n":7,"t":"我必远游，宿在旷野。 （细拉）","notes":[]},{"n":8,"t":"我必速速逃到避所，脱离狂风暴雨。","notes":[]},{"n":9,"t":"主啊，求你吞灭他们，变乱他们的舌头！因为我在城中见了强暴争竞的事。","notes":[]},{"n":10,"t":"他们在城墙上昼夜绕行；在城内也有罪孽和奸恶。","notes":[]},{"n":11,"t":"邪恶在其中；欺压和诡诈不离街市。","notes":[]},{"n":12,"t":"原来不是仇敌辱骂我，若是仇敌，还可忍耐；也不是恨我的人向我狂大，若是恨我的人就必躲避他。","notes":[]},{"n":13,"t":"不料是你；你原与我平等，是我的同伴，是我知己的朋友！","notes":[]},{"n":14,"t":"我们素常彼此谈论，以为甘甜；我们与群众在神的殿中同行。","notes":[]},{"n":15,"t":"愿死亡忽然临到他们！愿他们活活地下入阴间！因为他们的住处，他们的心中，都是邪恶。","notes":[]},{"n":16,"t":"至于我，我要求告神；耶和华必拯救我。","notes":[]},{"n":17,"t":"我要晚上、早晨、晌午哀声悲叹；他也必听我的声音。","notes":[]},{"n":18,"t":"他救赎我命脱离攻击我的人，使我得享平安，因为与我相争的人甚多。","notes":[]},{"n":19,"t":"那没有更变、不敬畏神的人，从太古常存的神必听见而苦待他。","notes":[]},{"n":20,"t":"他背了约，伸手攻击与他和好的人。","notes":[]},{"n":21,"t":"他的口如奶油光滑，他的心却怀着争战；他的话比油柔和，其实是拔出来的刀。","notes":[]},{"n":22,"t":"你要把你的重担卸给耶和华，他必抚养你；他永不叫义人动摇。","notes":[]},{"n":23,"t":"神啊，你必使恶人下入灭亡的坑；流人血、行诡诈的人必活不到半世，但我要倚靠你。","notes":[]}]},"56":{"heading":"信靠神的祈祷","verses":[{"n":1,"t":"神啊，求你怜悯我，因为人要把我吞了，终日攻击欺压我。","notes":[]},{"n":2,"t":"我的仇敌终日要把我吞了，因逞骄傲攻击我的人甚多。","notes":[]},{"n":3,"t":"我惧怕的时候要倚靠你。","notes":[]},{"n":4,"t":"我倚靠神，我要赞美他的话；我倚靠神，必不惧怕。血气之辈能把我怎么样呢？","notes":[]},{"n":5,"t":"他们终日颠倒我的话；他们一切的心思都是要害我。","notes":[]},{"n":6,"t":"他们聚集，埋伏窥探我的脚踪，等候要害我的命。","notes":[]},{"n":7,"t":"他们岂能因罪孽逃脱吗？神啊，求你在怒中使众民堕落！","notes":[]},{"n":8,"t":"我几次流离，你都记数；求你把我眼泪装在你的皮袋里。这不都记在你册子上吗？","notes":[]},{"n":9,"t":"我呼求的日子，我的仇敌都要转身退后。神帮助我，这是我所知道的。","notes":[]},{"n":10,"t":"我倚靠神，我要赞美他的话；我倚靠耶和华，我要赞美他的话。","notes":[]},{"n":11,"t":"我倚靠神，必不惧怕。人能把我怎么样呢？","notes":[]},{"n":12,"t":"神啊，我向你所许的愿在我身上；我要将感谢祭献给你。","notes":[]},{"n":13,"t":"因为你救我的命脱离死亡。你岂不是救护我的脚不跌倒、使我在生命光中行在神面前吗？","notes":[]}]},"57":{"heading":"求主施援","verses":[{"n":1,"t":"神啊，求你怜悯我，怜悯我！因为我的心投靠你。我要投靠在你翅膀的荫下，等到灾害过去。","notes":[]},{"n":2,"t":"我要求告至高的神，就是为我成全诸事的神。","notes":[]},{"n":3,"t":"那要吞我的人辱骂我的时候，神从天上必施恩救我，也必向我发出慈爱和诚实。","notes":[]},{"n":4,"t":"我的性命在狮子中间；我躺卧在性如烈火的世人当中。他们的牙齿是枪、箭；他们的舌头是快刀。","notes":[]},{"n":5,"t":"神啊，愿你崇高过于诸天！愿你的荣耀高过全地！","notes":[]},{"n":6,"t":"他们为我的脚设下网罗，压制我的心；他们在我面前挖了坑，自己反掉在其中。 （细拉）","notes":[]},{"n":7,"t":"神啊，我心坚定，我心坚定；我要唱诗，我要歌颂！","notes":[]},{"n":8,"t":"我的灵啊，你当醒起！琴瑟啊，你们当醒起！我自己要极早醒起！","notes":["原文是荣耀"]},{"n":9,"t":"主啊，我要在万民中称谢你，在列邦中歌颂你！","notes":[]},{"n":10,"t":"因为，你的慈爱高及诸天；你的诚实达到穹苍。","notes":[]},{"n":11,"t":"神啊，愿你崇高过于诸天！愿你的荣耀高过全地！","notes":[]}]},"58":{"heading":"求神罚恶","verses":[{"n":1,"t":"世人哪，你们默然不语，真合公义吗？施行审判，岂按正直吗？","notes":[]},{"n":2,"t":"不然！你们是心中作恶；你们在地上秤出你们手所行的强暴。","notes":[]},{"n":3,"t":"恶人一出母胎就与神疏远，一离母腹便走错路，说谎话。","notes":[]},{"n":4,"t":"他们的毒气好像蛇的毒气；他们好像塞耳的聋虺，","notes":[]},{"n":5,"t":"不听行法术的声音，虽用极灵的咒语也是不听。","notes":[]},{"n":6,"t":"神啊，求你敲碎他们口中的牙！耶和华啊，求你敲掉少壮狮子的大牙！","notes":[]},{"n":7,"t":"愿他们消灭，如急流的水一般；他们瞅准射箭的时候，愿箭头仿佛砍断。","notes":[]},{"n":8,"t":"愿他们像蜗牛消化过去，又像妇人坠落未见天日的胎。","notes":[]},{"n":9,"t":"你们用荆棘烧火，锅还未热，他要用旋风把青的和烧着的一齐刮去。","notes":[]},{"n":10,"t":"义人见仇敌遭报就欢喜，要在恶人的血中洗脚。","notes":[]},{"n":11,"t":"因此，人必说：义人诚然有善报；在地上果有施行判断的神！","notes":[]}]},"59":{"heading":"为安全求主施助","verses":[{"n":1,"t":"我的神啊，求你救我脱离仇敌，把我安置在高处，得脱那些起来攻击我的人。","notes":[]},{"n":2,"t":"求你救我脱离作孽的人和喜爱流人血的人！","notes":[]},{"n":3,"t":"因为，他们埋伏要害我的命；有能力的人聚集来攻击我。耶和华啊，这不是为我的过犯，也不是为我的罪愆。","notes":[]},{"n":4,"t":"我虽然无过，他们预备整齐，跑来攻击我。求你兴起鉴察，帮助我！","notes":[]},{"n":5,"t":"万军之神—耶和华以色列的神啊！求你兴起，惩治万邦！不要怜悯行诡诈的恶人！ （细拉）","notes":[]},{"n":6,"t":"他们晚上转回，叫号如狗，围城绕行。","notes":[]},{"n":7,"t":"他们口中喷吐恶言，嘴里有刀；他们说：有谁听见？","notes":[]},{"n":8,"t":"但你—耶和华必笑话他们；你要嗤笑万邦。","notes":[]},{"n":9,"t":"我的力量啊，我必仰望你，因为神是我的高台。","notes":[]},{"n":10,"t":"我的神要以慈爱迎接我；神要叫我看见我仇敌遭报。","notes":[]},{"n":11,"t":"不要杀他们，恐怕我的民忘记。主啊，你是我们的盾牌；求你用你的能力使他们四散，且降为卑。","notes":[]},{"n":12,"t":"因他们口中的罪和嘴里的言语，并咒骂虚谎的话，愿他们在骄傲之中被缠住了。","notes":[]},{"n":13,"t":"求你发怒，使他们消灭，以致归于无有，叫他们知道神在雅各中间掌权，直到地极。 （细拉）","notes":[]},{"n":14,"t":"到了晚上，任凭他们转回；任凭他们叫号如狗，围城绕行。","notes":[]},{"n":15,"t":"他们必走来走去，寻找食物，若不得饱就终夜在外。","notes":[]},{"n":16,"t":"但我要歌颂你的力量，早晨要高唱你的慈爱；因为你作过我的高台，在我急难的日子作过我的避难所。","notes":[]},{"n":17,"t":"我的力量啊，我要歌颂你；因为神是我的高台，是赐恩与我的神。","notes":[]}]},"60":{"heading":"求主解救","verses":[{"n":1,"t":"神啊，你丢弃了我们，使我们破败；你向我们发怒，求你使我们复兴！","notes":[]},{"n":2,"t":"你使地震动，而且崩裂；求你将裂口医好，因为地摇动。","notes":[]},{"n":3,"t":"你叫你的民遇见艰难；你叫我们喝那使人东倒西歪的酒。","notes":[]},{"n":4,"t":"你把旌旗赐给敬畏你的人，可以为真理扬起来。 （细拉）","notes":[]},{"n":5,"t":"求你应允我们，用右手拯救我们，好叫你所亲爱的人得救。","notes":[]},{"n":6,"t":"神已经指着他的圣洁说：我要欢乐；我要分开示剑，丈量疏割谷。","notes":["说：或译应许我"]},{"n":7,"t":"基列是我的，玛拿西也是我的。以法莲是护卫我头的；犹大是我的杖。","notes":[]},{"n":8,"t":"摩押是我的沐浴盆；我要向以东抛鞋。非利士啊，你还能因我欢呼吗？","notes":[]},{"n":9,"t":"谁能领我进坚固城？谁能引我到以东地？","notes":[]},{"n":10,"t":"神啊，你不是丢弃了我们吗？神啊，你不和我们的军兵同去吗？","notes":[]},{"n":11,"t":"求你帮助我们攻击敌人，因为人的帮助是枉然的。","notes":[]},{"n":12,"t":"我们倚靠神才得施展大能，因为践踏我们敌人的就是他。","notes":[]}]},"61":{"heading":"求主保佑","verses":[{"n":1,"t":"神啊，求你听我的呼求，侧耳听我的祷告！","notes":[]},{"n":2,"t":"我心里发昏的时候，我要从地极求告你。求你领我到那比我更高的磐石！","notes":[]},{"n":3,"t":"因为你作过我的避难所，作过我的坚固台，脱离仇敌。","notes":[]},{"n":4,"t":"我要永远住在你的帐幕里！我要投靠在你翅膀下的隐密处！ （细拉）","notes":[]},{"n":5,"t":"神啊，你原是听了我所许的愿；你将产业赐给敬畏你名的人。","notes":[]},{"n":6,"t":"你要加添王的寿数；他的年岁必存到世世。","notes":[]},{"n":7,"t":"他必永远坐在神面前；愿你预备慈爱和诚实保佑他！","notes":[]},{"n":8,"t":"这样，我要歌颂你的名，直到永远，好天天还我所许的愿。","notes":[]}]},"62":{"heading":"在神保佑中安稳自在","verses":[{"n":1,"t":"我的心默默无声，专等候神；我的救恩是从他而来。","notes":[]},{"n":2,"t":"惟独他是我的磐石，我的拯救；他是我的高台，我必不很动摇。","notes":[]},{"n":3,"t":"你们大家攻击一人，把他毁坏，如同毁坏歪斜的墙、将倒的壁，要到几时呢？","notes":[]},{"n":4,"t":"他们彼此商议，专要从他的尊位上把他推下；他们喜爱谎话，口虽祝福，心却咒诅。 （细拉）","notes":[]},{"n":5,"t":"我的心哪，你当默默无声，专等候神，因为我的盼望是从他而来。","notes":[]},{"n":6,"t":"惟独他是我的磐石，我的拯救；他是我的高台，我必不动摇。","notes":[]},{"n":7,"t":"我的拯救、我的荣耀都在乎神；我力量的磐石、我的避难所都在乎神。","notes":[]},{"n":8,"t":"你们众民当时时倚靠他，在他面前倾心吐意；神是我们的避难所。 （细拉）","notes":[]},{"n":9,"t":"下流人真是虚空；上流人也是虚假；放在天平里就必浮起；他们一共比空气还轻。","notes":[]},{"n":10,"t":"不要仗势欺人，也不要因抢夺而骄傲；若财宝加增，不要放在心上。","notes":[]},{"n":11,"t":"神说了一次、两次，我都听见：就是能力都属乎神。","notes":[]},{"n":12,"t":"主啊，慈爱也是属乎你，因为你照着各人所行的报应他。","notes":[]}]},"63":{"heading":"渴慕神","verses":[{"n":1,"t":"神啊，你是我的神，我要切切地寻求你，在干旱疲乏无水之地，我渴想你；我的心切慕你。","notes":[]},{"n":2,"t":"我在圣所中曾如此瞻仰你，为要见你的能力和你的荣耀。","notes":[]},{"n":3,"t":"因你的慈爱比生命更好，我的嘴唇要颂赞你。","notes":[]},{"n":4,"t":"我还活的时候要这样称颂你；我要奉你的名举手。","notes":[]},{"n":5,"t":"我在床上记念你，在夜更的时候思想你；我的心就像饱足了骨髓肥油，我也要以欢乐的嘴唇赞美你。","notes":[],"end":6},{"n":7,"t":"因为你曾帮助我，我就在你翅膀的荫下欢呼。","notes":[]},{"n":8,"t":"我心紧紧地跟随你；你的右手扶持我。","notes":[]},{"n":9,"t":"但那些寻索要灭我命的人必往地底下去；","notes":[]},{"n":10,"t":"他们必被刀剑所杀，被野狗所吃。","notes":[]},{"n":11,"t":"但是王必因神欢喜。凡指着他发誓的必要夸口，因为说谎之人的口必被塞住。","notes":[]}]},"64":{"heading":"求主保护","verses":[{"n":1,"t":"神啊，我哀叹的时候，求你听我的声音！求你保护我的性命，不受仇敌的惊恐！","notes":[]},{"n":2,"t":"求你把我隐藏，使我脱离作恶之人的暗谋和作孽之人的扰乱。","notes":[]},{"n":3,"t":"他们磨舌如刀，发出苦毒的言语，好像比准了的箭，","notes":[]},{"n":4,"t":"要在暗地射完全人；他们忽然射他，并不惧怕。","notes":[]},{"n":5,"t":"他们彼此勉励设下恶计；他们商量暗设网罗，说：谁能看见？","notes":[]},{"n":6,"t":"他们图谋奸恶，说：我们是极力图谋的。他们各人的意念心思是深的。","notes":[]},{"n":7,"t":"但神要射他们；他们忽然被箭射伤。","notes":[]},{"n":8,"t":"他们必然绊跌，被自己的舌头所害；凡看见他们的必都摇头。","notes":[]},{"n":9,"t":"众人都要害怕，要传扬神的工作，并且明白他的作为。","notes":[]},{"n":10,"t":"义人必因耶和华欢喜，并要投靠他；凡心里正直的人都要夸口。","notes":[]}]},"65":{"heading":"颂赞主恩","verses":[{"n":1,"t":"神啊，锡安的人都等候赞美你；所许的愿也要向你偿还。","notes":[]},{"n":2,"t":"听祷告的主啊，凡有血气的都要来就你。","notes":[]},{"n":3,"t":"罪孽胜了我；至于我们的过犯，你都要赦免。","notes":[]},{"n":4,"t":"你所拣选、使他亲近你、住在你院中的，这人便为有福！我们必因你居所、你圣殿的美福知足了。","notes":[]},{"n":5,"t":"拯救我们的神啊，你必以威严秉公义应允我们；你本是一切地极和海上远处的人所倚靠的。","notes":[]},{"n":6,"t":"他既以大能束腰，就用力量安定诸山，","notes":[]},{"n":7,"t":"使诸海的响声和其中波浪的响声，并万民的喧哗，都平静了。","notes":[]},{"n":8,"t":"住在地极的人因你的神迹惧怕；你使日出日落之地都欢呼。","notes":[]},{"n":9,"t":"你眷顾地，降下透雨，使地大得肥美。神的河满了水；你这样浇灌了地，好为人预备五谷。","notes":[]},{"n":10,"t":"你浇透地的犁沟，润平犁脊，降甘霖，使地软和；其中发长的，蒙你赐福。","notes":[]},{"n":11,"t":"你以恩典为年岁的冠冕；你的路径都滴下脂油，","notes":[]},{"n":12,"t":"滴在旷野的草场上。小山以欢乐束腰；","notes":[]},{"n":13,"t":"草场以羊群为衣；谷中也长满了五谷。这一切都欢呼歌唱。","notes":[]}]},"66":{"heading":"颂赞感恩的诗","verses":[{"n":1,"t":"全地都当向神欢呼！","notes":[]},{"n":2,"t":"歌颂他名的荣耀！用赞美的言语将他的荣耀发明！","notes":[]},{"n":3,"t":"当对神说：你的作为何等可畏！因你的大能，仇敌要投降你。","notes":[]},{"n":4,"t":"全地要敬拜你，歌颂你，要歌颂你的名。 （细拉）","notes":[]},{"n":5,"t":"你们来看神所行的，他向世人所做之事是可畏的。","notes":[]},{"n":6,"t":"他将海变成干地，众民步行过河；我们在那里因他欢喜。","notes":[]},{"n":7,"t":"他用权能治理万民，直到永远。他的眼睛鉴察列邦；悖逆的人不可自高。 （细拉）","notes":[]},{"n":8,"t":"万民哪，你们当称颂我们的神，使人得听赞美他的声音。","notes":[]},{"n":9,"t":"他使我们的性命存活，也不叫我们的脚摇动。","notes":[]},{"n":10,"t":"神啊，你曾试验我们，熬炼我们，如熬炼银子一样。","notes":[]},{"n":11,"t":"你使我们进入网罗，把重担放在我们的身上。","notes":[]},{"n":12,"t":"你使人坐车轧我们的头；我们经过水火，你却使我们到丰富之地。","notes":[]},{"n":13,"t":"我要用燔祭进你的殿，向你还我的愿，","notes":[]},{"n":14,"t":"就是在急难时我嘴唇所发的、口中所许的。","notes":[]},{"n":15,"t":"我要把肥牛作燔祭，将公羊的香祭献给你，又把公牛和山羊献上。 （细拉）","notes":[]},{"n":16,"t":"凡敬畏神的人，你们都来听！我要述说他为我所行的事。","notes":[]},{"n":17,"t":"我曾用口求告他；我的舌头也称他为高。","notes":[]},{"n":18,"t":"我若心里注重罪孽，主必不听。","notes":[]},{"n":19,"t":"但神实在听见了；他侧耳听了我祷告的声音。","notes":[]},{"n":20,"t":"神是应当称颂的！他并没有推却我的祷告，也没有叫他的慈爱离开我。","notes":[]}]},"67":{"heading":"感恩的诗","verses":[{"n":1,"t":"愿神怜悯我们，赐福与我们，用脸光照我们， （细拉）","notes":[]},{"n":2,"t":"好叫世界得知你的道路，万国得知你的救恩。","notes":[]},{"n":3,"t":"神啊，愿列邦称赞你！愿万民都称赞你！","notes":[]},{"n":4,"t":"愿万国都快乐欢呼；因为你必按公正审判万民，引导世上的万国。 （细拉）","notes":[]},{"n":5,"t":"神啊，愿列邦称赞你！愿万民都称赞你！","notes":[]},{"n":6,"t":"地已经出了土产；神—就是我们的神要赐福与我们。","notes":[]},{"n":7,"t":"神要赐福与我们；地的四极都要敬畏他！","notes":[]}]},"68":{"heading":"胜利之歌","verses":[{"n":1,"t":"愿神兴起，使他的仇敌四散，叫那恨他的人从他面前逃跑。","notes":[]},{"n":2,"t":"他们被驱逐，如烟被风吹散；恶人见神之面而消灭，如蜡被火熔化。","notes":[]},{"n":3,"t":"惟有义人必然欢喜，在神面前高兴快乐。","notes":[]},{"n":4,"t":"你们当向神唱诗，歌颂他的名；为那坐车行过旷野的修平大路。他的名是耶和华，要在他面前欢乐！","notes":[]},{"n":5,"t":"神在他的圣所作孤儿的父，作寡妇的伸冤者。","notes":[]},{"n":6,"t":"神叫孤独的有家，使被囚的出来享福；惟有悖逆的住在干燥之地。","notes":[]},{"n":7,"t":"神啊，你曾在你百姓前头出来，在旷野行走。 （细拉）","notes":[]},{"n":8,"t":"那时，地见神的面而震动，天也落雨；西奈山见以色列神的面也震动。","notes":[]},{"n":9,"t":"神啊，你降下大雨；你产业以色列疲乏的时候，你使他坚固。","notes":[]},{"n":10,"t":"你的会众住在其中；神啊，你的恩惠是为困苦人预备的。","notes":[]},{"n":11,"t":"主发命令，传好信息的妇女成了大群。","notes":[]},{"n":12,"t":"统兵的君王逃跑了，逃跑了；在家等候的妇女分受所夺的。","notes":[]},{"n":13,"t":"你们安卧在羊圈的时候，好像鸽子的翅膀镀白银，翎毛镀黄金一般。","notes":[]},{"n":14,"t":"全能者在境内赶散列王的时候，势如飘雪在撒们。","notes":[]},{"n":15,"t":"巴珊山是神的山；巴珊山是多峰多岭的山。","notes":[]},{"n":16,"t":"你们多峰多岭的山哪，为何斜看神所愿居住的山？耶和华必住这山，直到永远！","notes":[]},{"n":17,"t":"神的车辇累万盈千；主在其中，好像在西奈圣山一样。","notes":[]},{"n":18,"t":"你已经升上高天，掳掠仇敌；你在人间，就是在悖逆的人间，受了供献，叫耶和华神可以与他们同住。","notes":[]},{"n":19,"t":"天天背负我们重担的主，就是拯救我们的神，是应当称颂的！ （细拉）","notes":[]},{"n":20,"t":"神是为我们施行诸般救恩的神；人能脱离死亡是在乎主耶和华。","notes":[]},{"n":21,"t":"但神要打破他仇敌的头，就是那常犯罪之人的发顶。","notes":[]},{"n":22,"t":"主说：我要使众民从巴珊而归，使他们从深海而回，","notes":[]},{"n":23,"t":"使你打碎仇敌，你的脚踹在血中，使你狗的舌头从其中得分。","notes":[]},{"n":24,"t":"神啊，你是我的神，我的王；人已经看见你行走，进入圣所。","notes":[]},{"n":25,"t":"歌唱的行在前，作乐的随在后，都在击鼓的童女中间。","notes":[]},{"n":26,"t":"从以色列源头而来的，当在各会中称颂主神！","notes":[]},{"n":27,"t":"在那里，有统管他们的小便雅悯，有犹大的首领和他们的群众，有西布伦的首领，有拿弗他利的首领。","notes":[]},{"n":28,"t":"以色列的能力是神所赐的；神啊，求你坚固你为我们所成全的事！","notes":[]},{"n":29,"t":"因你耶路撒冷的殿，列王必带贡物献给你。","notes":[]},{"n":30,"t":"求你叱喝芦苇中的野兽和群公牛，并列邦中的牛犊。把银块踹在脚下；神已经赶散好争战的列邦。","notes":[]},{"n":31,"t":"埃及的公侯要出来朝见神；古实人要急忙举手祷告。","notes":[]},{"n":32,"t":"世上的列国啊，你们要向神歌唱；愿你们歌颂主！","notes":[]},{"n":33,"t":"歌颂那自古驾行在诸天以上的主！他发出声音，是极大的声音。","notes":[]},{"n":34,"t":"你们要将能力归给神。他的威荣在以色列之上；他的能力是在穹苍。","notes":[]},{"n":35,"t":"神啊，你从圣所显为可畏；以色列的神是那将力量权能赐给他百姓的。神是应当称颂的！","notes":[]}]},"69":{"heading":"求助的祷告","verses":[{"n":1,"t":"神啊，求你救我！因为众水要淹没我。","notes":[]},{"n":2,"t":"我陷在深淤泥中，没有立脚之地；我到了深水中，大水漫过我身。","notes":[]},{"n":3,"t":"我因呼求困乏，喉咙发干；我因等候神，眼睛失明。","notes":[]},{"n":4,"t":"无故恨我的，比我头发还多；无理与我为仇、要把我剪除的，甚为强盛。我没有抢夺的，要叫我偿还。","notes":[]},{"n":5,"t":"神啊，我的愚昧，你原知道；我的罪愆不能隐瞒。","notes":[]},{"n":6,"t":"万军的主—耶和华啊，求你叫那等候你的，不要因我蒙羞！以色列的神啊，求你叫那寻求你的，不要因我受辱！","notes":[]},{"n":7,"t":"因我为你的缘故受了辱骂，满面羞愧。","notes":[]},{"n":8,"t":"我的弟兄看我为外路人；我的同胞看我为外邦人。","notes":[]},{"n":9,"t":"因我为你的殿心里焦急，如同火烧，并且辱骂你人的辱骂都落在我身上。","notes":[]},{"n":10,"t":"我哭泣，以禁食刻苦我心；这倒算为我的羞辱。","notes":[]},{"n":11,"t":"我拿麻布当衣裳，就成了他们的笑谈。","notes":[]},{"n":12,"t":"坐在城门口的谈论我；酒徒也以我为歌曲。","notes":[]},{"n":13,"t":"但我在悦纳的时候向你—耶和华祈祷。神啊，求你按你丰盛的慈爱，凭你拯救的诚实应允我！","notes":[]},{"n":14,"t":"求你搭救我出离淤泥，不叫我陷在其中；求你使我脱离那些恨我的人，使我出离深水。","notes":[]},{"n":15,"t":"求你不容大水漫过我，不容深渊吞灭我，不容坑坎在我以上合口。","notes":[]},{"n":16,"t":"耶和华啊，求你应允我！因为你的慈爱本为美好；求你按你丰盛的慈悲回转眷顾我！","notes":[]},{"n":17,"t":"不要掩面不顾你的仆人；我是在急难之中，求你速速地应允我！","notes":[]},{"n":18,"t":"求你亲近我，救赎我！求你因我的仇敌把我赎回！","notes":[]},{"n":19,"t":"你知道我受的辱骂、欺凌、羞辱；我的敌人都在你面前。","notes":[]},{"n":20,"t":"辱骂伤破了我的心，我又满了忧愁。我指望有人体恤，却没有一个；我指望有人安慰，却找不着一个。","notes":[]},{"n":21,"t":"他们拿苦胆给我当食物；我渴了，他们拿醋给我喝。","notes":[]},{"n":22,"t":"愿他们的筵席在他们面前变为网罗，在他们平安的时候变为机槛。","notes":[]},{"n":23,"t":"愿他们的眼睛昏蒙，不得看见；愿你使他们的腰常常战抖。","notes":[]},{"n":24,"t":"求你将你的恼恨倒在他们身上，叫你的烈怒追上他们。","notes":[]},{"n":25,"t":"愿他们的住处变为荒场；愿他们的帐棚无人居住。","notes":[]},{"n":26,"t":"因为，你所击打的，他们就逼迫；你所击伤的，他们戏说他的愁苦。","notes":[]},{"n":27,"t":"愿你在他们的罪上加罪，不容他们在你面前称义。","notes":[]},{"n":28,"t":"愿他们从生命册上被涂抹，不得记录在义人之中。","notes":[]},{"n":29,"t":"但我是困苦忧伤的；神啊，愿你的救恩将我安置在高处。","notes":[]},{"n":30,"t":"我要以诗歌赞美神的名，以感谢称他为大！","notes":[]},{"n":31,"t":"这便叫耶和华喜悦，胜似献牛，或是献有角有蹄的公牛。","notes":[]},{"n":32,"t":"谦卑的人看见了就喜乐；寻求神的人，愿你们的心苏醒。","notes":[]},{"n":33,"t":"因为耶和华听了穷乏人，不藐视被囚的人。","notes":[]},{"n":34,"t":"愿天和地、洋海和其中一切的动物都赞美他！","notes":[]},{"n":35,"t":"因为神要拯救锡安，建造犹大的城邑；他的民要在那里居住，得以为业。","notes":[]},{"n":36,"t":"他仆人的后裔要承受为业；爱他名的人也要住在其中。","notes":[]}]},"70":{"heading":"求助的祈祷","verses":[{"n":1,"t":"神啊，求你快快搭救我！耶和华啊，求你速速帮助我！","notes":[]},{"n":2,"t":"愿那些寻索我命的，抱愧蒙羞；愿那些喜悦我遭害的，退后受辱。","notes":[]},{"n":3,"t":"愿那些对我说阿哈、阿哈的，因羞愧退后。","notes":[]},{"n":4,"t":"愿一切寻求你的，因你高兴欢喜；愿那些喜爱你救恩的，常说：当尊神为大！","notes":[]},{"n":5,"t":"但我是困苦穷乏的；神啊，求你速速到我这里来！你是帮助我的，搭救我的。耶和华啊，求你不要耽延！","notes":[]}]},"71":{"heading":"老年人的祈祷","verses":[{"n":1,"t":"耶和华啊，我投靠你；求你叫我永不羞愧！","notes":[]},{"n":2,"t":"求你凭你的公义搭救我，救拔我；侧耳听我，拯救我！","notes":[]},{"n":3,"t":"求你作我常住的磐石；你已经命定要救我，因为你是我的岩石，我的山寨。","notes":[]},{"n":4,"t":"我的神啊，求你救我脱离恶人的手，脱离不义和残暴之人的手。","notes":[]},{"n":5,"t":"主—耶和华啊，你是我所盼望的；从我年幼，你是我所倚靠的。","notes":[]},{"n":6,"t":"我从出母胎被你扶持；使我出母腹的是你。我必常常赞美你！","notes":[]},{"n":7,"t":"许多人以我为怪，但你是我坚固的避难所。","notes":[]},{"n":8,"t":"你的赞美，你的荣耀终日必满了我的口。","notes":[]},{"n":9,"t":"我年老的时候，求你不要丢弃我！我力气衰弱的时候，求你不要离弃我！","notes":[]},{"n":10,"t":"我的仇敌议论我；那些窥探要害我命的彼此商议，","notes":[]},{"n":11,"t":"说：神已经离弃他；我们追赶他，捉拿他吧！因为没有人搭救。","notes":[]},{"n":12,"t":"神啊，求你不要远离我！我的神啊，求你速速帮助我！","notes":[]},{"n":13,"t":"愿那与我性命为敌的，羞愧被灭；愿那谋害我的，受辱蒙羞。","notes":[]},{"n":14,"t":"我却要常常盼望，并要越发赞美你。","notes":[]},{"n":15,"t":"我的口终日要述说你的公义和你的救恩，因我不计其数。","notes":[]},{"n":16,"t":"我要来说主—耶和华大能的事；我单要提说你的公义。","notes":[]},{"n":17,"t":"神啊，自我年幼时，你就教训我；直到如今，我传扬你奇妙的作为。","notes":[]},{"n":18,"t":"神啊，我到年老发白的时候，求你不要离弃我！等我将你的能力指示下代，将你的大能指示后世的人。","notes":[]},{"n":19,"t":"神啊，你的公义甚高；行过大事的神啊，谁能像你！","notes":[]},{"n":20,"t":"你是叫我们多经历重大急难的，必使我们复活，从地的深处救上来。","notes":[]},{"n":21,"t":"求你使我越发昌大，又转来安慰我。","notes":[]},{"n":22,"t":"我的神啊，我要鼓瑟称赞你，称赞你的诚实！以色列的圣者啊，我要弹琴歌颂你！","notes":[]},{"n":23,"t":"我歌颂你的时候，我的嘴唇和你所赎我的灵魂都必欢呼；","notes":[]},{"n":24,"t":"并且我的舌头必终日讲论你的公义，因为那些谋害我的人已经蒙羞受辱了。","notes":[]}]},"72":{"heading":"为王祈祷","verses":[{"n":1,"t":"神啊，求你将判断的权柄赐给王，将公义赐给王的儿子。","notes":[]},{"n":2,"t":"他要按公义审判你的民，按公平审判你的困苦人。","notes":[]},{"n":3,"t":"大山小山都要因公义使民得享平安。","notes":[]},{"n":4,"t":"他必为民中的困苦人伸冤，拯救穷乏之辈，压碎那欺压人的。","notes":[]},{"n":5,"t":"太阳还存，月亮还在，人要敬畏你，直到万代！","notes":[]},{"n":6,"t":"他必降临，像雨降在已割的草地上，如甘霖滋润田地。","notes":[]},{"n":7,"t":"在他的日子，义人要发旺，大有平安，好像月亮长存。","notes":[]},{"n":8,"t":"他要执掌权柄，从这海直到那海，从大河直到地极。","notes":[]},{"n":9,"t":"住在旷野的，必在他面前下拜；他的仇敌必要舔土。","notes":[]},{"n":10,"t":"他施和海岛的王要进贡；示巴和西巴的王要献礼物。","notes":[]},{"n":11,"t":"诸王都要叩拜他；万国都要事奉他。","notes":[]},{"n":12,"t":"因为，穷乏人呼求的时候，他要搭救；没有人帮助的困苦人，他也要搭救。","notes":[]},{"n":13,"t":"他要怜恤贫寒和穷乏的人，拯救穷苦人的性命。","notes":[]},{"n":14,"t":"他要救赎他们脱离欺压和强暴；他们的血在他眼中看为宝贵。","notes":[]},{"n":15,"t":"他们要存活。示巴的金子要奉给他；人要常常为他祷告，终日称颂他。","notes":[]},{"n":16,"t":"在地的山顶上，五谷必然茂盛；所结的谷实要响动，如黎巴嫩的树林；城里的人要发旺，如地上的草。","notes":["或译：有一把五谷"]},{"n":17,"t":"他的名要存到永远，要留传如日之久。人要因他蒙福；万国要称他有福。","notes":[]},{"n":18,"t":"独行奇事的耶和华—以色列的神是应当称颂的！","notes":[]},{"n":19,"t":"他荣耀的名也当称颂，直到永远。愿他的荣耀充满全地！阿们！阿们！","notes":[]},{"n":20,"t":"耶西的儿子—大卫的祈祷完毕。","notes":[]}]},"73":{"heading":"神的公正","verses":[{"n":1,"t":"神实在恩待以色列那些清心的人！","notes":[]},{"n":2,"t":"至于我，我的脚几乎失闪；我的脚险些滑跌。","notes":[]},{"n":3,"t":"我见恶人和狂傲人享平安就心怀不平。","notes":[]},{"n":4,"t":"他们死的时候没有疼痛；他们的力气却也壮实。","notes":[]},{"n":5,"t":"他们不像别人受苦，也不像别人遭灾。","notes":[]},{"n":6,"t":"所以，骄傲如链子戴在他们的项上；强暴像衣裳遮住他们的身体。","notes":[]},{"n":7,"t":"他们的眼睛因体胖而凸出；他们所得的，过于心里所想的。","notes":[]},{"n":8,"t":"他们讥笑人，凭恶意说欺压人的话；他们说话自高。","notes":[]},{"n":9,"t":"他们的口亵渎上天；他们的舌毁谤全地。","notes":[]},{"n":10,"t":"所以神的民归到这里，喝尽了满杯的苦水。","notes":[]},{"n":11,"t":"他们说：神怎能晓得？至高者岂有知识呢？","notes":[]},{"n":12,"t":"看哪，这就是恶人；他们既是常享安逸，财宝便加增。","notes":[]},{"n":13,"t":"我实在徒然洁净了我的心，徒然洗手表明无辜。","notes":[]},{"n":14,"t":"因为，我终日遭灾难；每早晨受惩治。","notes":[]},{"n":15,"t":"我若说，我要这样讲，这就是以奸诈待你的众子。","notes":[]},{"n":16,"t":"我思索怎能明白这事，眼看实系为难，","notes":[]},{"n":17,"t":"等我进了神的圣所，思想他们的结局。","notes":[]},{"n":18,"t":"你实在把他们安在滑地，使他们掉在沉沦之中。","notes":[]},{"n":19,"t":"他们转眼之间成了何等的荒凉！他们被惊恐灭尽了。","notes":[]},{"n":20,"t":"人睡醒了，怎样看梦；主啊，你醒了也必照样轻看他们的影像。","notes":[]},{"n":21,"t":"因而，我心里发酸，肺腑被刺。","notes":[]},{"n":22,"t":"我这样愚昧无知，在你面前如畜类一般。","notes":[]},{"n":23,"t":"然而，我常与你同在；你搀着我的右手。","notes":[]},{"n":24,"t":"你要以你的训言引导我，以后必接我到荣耀里。","notes":[]},{"n":25,"t":"除你以外，在天上我有谁呢？除你以外，在地上我也没有所爱慕的。","notes":[]},{"n":26,"t":"我的肉体和我的心肠衰残；但神是我心里的力量，又是我的福分，直到永远。","notes":[]},{"n":27,"t":"远离你的，必要死亡；凡离弃你行邪淫的，你都灭绝了。","notes":[]},{"n":28,"t":"但我亲近神是与我有益；我以主耶和华为我的避难所，好叫我述说你一切的作为。","notes":[]}]},"74":{"heading":"求主解救国家","verses":[{"n":1,"t":"神啊，你为何永远丢弃我们呢？你为何向你草场的羊发怒，如烟冒出呢？","notes":[]},{"n":2,"t":"求你记念你古时所得来的会众，就是你所赎、作你产业支派的，并记念你向来所居住的锡安山。","notes":[]},{"n":3,"t":"求你举步去看那日久荒凉之地，仇敌在圣所中所行的一切恶事。","notes":[]},{"n":4,"t":"你的敌人在你会中吼叫；他们竖了自己的旗为记号。","notes":[]},{"n":5,"t":"他们好像人扬起斧子，砍伐林中的树。","notes":[]},{"n":6,"t":"圣所中一切雕刻的，他们现在用斧子锤子打坏了。","notes":[]},{"n":7,"t":"他们用火焚烧你的圣所，亵渎你名的居所，拆毁到地。","notes":[]},{"n":8,"t":"他们心里说：我们要尽行毁灭；他们就在遍地把神的会所都烧毁了。","notes":[]},{"n":9,"t":"我们不见我们的标帜，不再有先知；我们内中也没有人知道这灾祸要到几时呢！","notes":[]},{"n":10,"t":"神啊，敌人辱骂要到几时呢？仇敌亵渎你的名要到永远吗？","notes":[]},{"n":11,"t":"你为什么缩回你的右手？求你从怀中伸出来，毁灭他们。","notes":[]},{"n":12,"t":"神自古以来为我的王，在地上施行拯救。","notes":[]},{"n":13,"t":"你曾用能力将海分开，将水中大鱼的头打破。","notes":[]},{"n":14,"t":"你曾砸碎鳄鱼的头，把它给旷野的禽兽为食物。","notes":["禽兽：原文是民"]},{"n":15,"t":"你曾分裂磐石，水便成了溪河；你使长流的江河干了。","notes":[]},{"n":16,"t":"白昼属你，黑夜也属你；亮光和日头是你所预备的。","notes":[]},{"n":17,"t":"地的一切疆界是你所立的；夏天和冬天是你所定的。","notes":[]},{"n":18,"t":"耶和华啊，仇敌辱骂，愚顽民亵渎了你的名，求你记念这事。","notes":[]},{"n":19,"t":"不要将你斑鸠的性命交给野兽；不要永远忘记你困苦人的性命。","notes":[]},{"n":20,"t":"求你顾念所立的约，因为地上黑暗之处都满了强暴的居所。","notes":[]},{"n":21,"t":"不要叫受欺压的人蒙羞回去；要叫困苦穷乏的人赞美你的名。","notes":[]},{"n":22,"t":"神啊，求你起来为自己伸诉！要记念愚顽人怎样终日辱骂你。","notes":[]},{"n":23,"t":"不要忘记你敌人的声音；那起来敌你之人的喧哗时常上升。","notes":[]}]},"75":{"heading":"神是审判者","verses":[{"n":1,"t":"神啊，我们称谢你，我们称谢你！因为你的名相近，人都述说你奇妙的作为。","notes":[]},{"n":2,"t":"我到了所定的日期，必按正直施行审判。","notes":[]},{"n":3,"t":"地和其上的居民都消化了；我曾立了地的柱子。 （细拉）","notes":[]},{"n":4,"t":"我对狂傲人说：不要行事狂傲！对凶恶人说：不要举角！","notes":[]},{"n":5,"t":"不要把你们的角高举；不要挺着颈项说话。","notes":[]},{"n":6,"t":"因为高举非从东，非从西，也非从南而来。","notes":[]},{"n":7,"t":"惟有神断定；他使这人降卑，使那人升高。","notes":[]},{"n":8,"t":"耶和华手里有杯，其中的酒起沫，杯内满了搀杂的酒；他倒出来，地上的恶人必都喝这酒的渣滓，而且喝尽。","notes":[]},{"n":9,"t":"但我要宣扬，直到永远！我要歌颂雅各的神！","notes":[]},{"n":10,"t":"恶人一切的角，我要砍断；惟有义人的角必被高举。","notes":[]}]},"76":{"heading":"神是胜利者","verses":[{"n":1,"t":"在犹大，神为人所认识；在以色列，他的名为大。","notes":[]},{"n":2,"t":"在撒冷有他的帐幕；在锡安有他的居所。","notes":[]},{"n":3,"t":"他在那里折断弓上的火箭，并盾牌、刀剑，和争战的兵器。 （细拉）","notes":[]},{"n":4,"t":"你从有野食之山而来，有光华和荣美。","notes":[]},{"n":5,"t":"心中勇敢的人都被抢夺；他们睡了长觉，没有一个英雄能措手。","notes":[]},{"n":6,"t":"雅各的神啊，你的斥责一发，坐车的、骑马的都沉睡了。","notes":[]},{"n":7,"t":"惟独你是可畏的！你怒气一发，谁能在你面前站得住呢？","notes":[]},{"n":8,"t":"你从天上使人听判断。神起来施行审判，要救地上一切谦卑的人；那时地就惧怕而静默。 （细拉）","notes":[],"end":9},{"n":10,"t":"人的忿怒要成全你的荣美；人的余怒，你要禁止。","notes":[]},{"n":11,"t":"你们许愿，当向耶和华—你们的神还愿；在他四面的人都当拿贡物献给那可畏的主。","notes":[]},{"n":12,"t":"他要挫折王子的骄气；他向地上的君王显威可畏。","notes":[]}]},"77":{"heading":"遇难时得安慰","verses":[{"n":1,"t":"我要向神发声呼求；我向神发声，他必留心听我。","notes":[]},{"n":2,"t":"我在患难之日寻求主；我在夜间不住地举手祷告；我的心不肯受安慰。","notes":[]},{"n":3,"t":"我想念神，就烦燥不安；我沉吟悲伤，心便发昏。 （细拉）","notes":[]},{"n":4,"t":"你叫我不能闭眼；我烦乱不安，甚至不能说话。","notes":[]},{"n":5,"t":"我追想古时之日，上古之年。","notes":[]},{"n":6,"t":"我想起我夜间的歌曲，扪心自问；我心里也仔细省察。","notes":[]},{"n":7,"t":"难道主要永远丢弃我，不再施恩吗？","notes":[]},{"n":8,"t":"难道他的慈爱永远穷尽，他的应许世世废弃吗？","notes":[]},{"n":9,"t":"难道神忘记开恩，因发怒就止住他的慈悲吗？ （细拉）","notes":[]},{"n":10,"t":"我便说：这是我的懦弱，但我要追念至高者显出右手之年代。","notes":[]},{"n":11,"t":"我要提说耶和华所行的；我要记念你古时的奇事。","notes":[]},{"n":12,"t":"我也要思想你的经营，默念你的作为。","notes":[]},{"n":13,"t":"神啊，你的作为是洁净的；有何神大如神呢？","notes":[]},{"n":14,"t":"你是行奇事的神；你曾在列邦中彰显你的能力。","notes":[]},{"n":15,"t":"你曾用你的膀臂赎了你的民，就是雅各和约瑟的子孙。 （细拉）","notes":[]},{"n":16,"t":"神啊，诸水见你，一见就都惊惶；深渊也都战抖。","notes":[]},{"n":17,"t":"云中倒出水来；天空发出响声；你的箭也飞行四方。","notes":[]},{"n":18,"t":"你的雷声在旋风中；电光照亮世界；大地战抖震动。","notes":[]},{"n":19,"t":"你的道在海中；你的路在大水中；你的脚踪无人知道。","notes":[]},{"n":20,"t":"你曾借摩西和亚伦的手引导你的百姓，好像羊群一般。","notes":[]}]},"78":{"heading":"神与他的子民","verses":[{"n":1,"t":"我的民哪，你们要留心听我的训诲，侧耳听我口中的话。","notes":[]},{"n":2,"t":"我要开口说比喻；我要说出古时的谜语，","notes":[]},{"n":3,"t":"是我们所听见、所知道的，也是我们的祖宗告诉我们的。","notes":[]},{"n":4,"t":"我们不将这些事向他们的子孙隐瞒，要将耶和华的美德和他的能力，并他奇妙的作为，述说给后代听。","notes":[]},{"n":5,"t":"因为，他在雅各中立法度，在以色列中设律法；是他吩咐我们祖宗要传给子孙的，","notes":[]},{"n":6,"t":"使将要生的后代子孙可以晓得；他们也要起来告诉他们的子孙，","notes":[]},{"n":7,"t":"好叫他们仰望神，不忘记神的作为，惟要守他的命令。","notes":[]},{"n":8,"t":"不要像他们的祖宗，是顽梗悖逆、居心不正之辈，向着神，心不诚实。","notes":[]},{"n":9,"t":"以法莲的子孙带着兵器，拿着弓，临阵之日转身退后。","notes":[]},{"n":10,"t":"他们不遵守神的约，不肯照他的律法行；","notes":[]},{"n":11,"t":"又忘记他所行的和他显给他们奇妙的作为。","notes":[]},{"n":12,"t":"他在埃及地，在琐安田，在他们祖宗的眼前施行奇事。","notes":[]},{"n":13,"t":"他将海分裂，使他们过去，又叫水立起如垒。","notes":[]},{"n":14,"t":"他白日用云彩，终夜用火光引导他们。","notes":[]},{"n":15,"t":"他在旷野分裂磐石，多多地给他们水喝，如从深渊而出。","notes":[]},{"n":16,"t":"他使水从磐石涌出，叫水如江河下流。","notes":[]},{"n":17,"t":"他们却仍旧得罪他，在干燥之地悖逆至高者。","notes":[]},{"n":18,"t":"他们心中试探神，随自己所欲的求食物，","notes":[]},{"n":19,"t":"并且妄论神说：神在旷野岂能摆设筵席吗？","notes":[]},{"n":20,"t":"他曾击打磐石，使水涌出，成了江河；他还能赐粮食吗？还能为他的百姓预备肉吗？","notes":[]},{"n":21,"t":"所以，耶和华听见就发怒；有烈火向雅各烧起；有怒气向以色列上腾；","notes":[]},{"n":22,"t":"因为他们不信服神，不倚赖他的救恩。","notes":[]},{"n":23,"t":"他却吩咐天空，又敞开天上的门，","notes":[]},{"n":24,"t":"降吗哪，像雨给他们吃，将天上的粮食赐给他们。","notes":[]},{"n":25,"t":"各人吃大能者的食物；他赐下粮食，使他们饱足。","notes":["或译：人"]},{"n":26,"t":"他领东风起在天空，又用能力引了南风来。","notes":[]},{"n":27,"t":"他降肉，像雨在他们当中，多如尘土，又降飞鸟，多如海沙，","notes":[]},{"n":28,"t":"落在他们的营中，在他们住处的四面。","notes":[]},{"n":29,"t":"他们吃了，而且饱足；这样就随了他们所欲的。","notes":[]},{"n":30,"t":"他们贪而无厌，食物还在他们口中的时候，","notes":[]},{"n":31,"t":"神的怒气就向他们上腾，杀了他们内中的肥壮人，打倒以色列的少年人。","notes":[]},{"n":32,"t":"虽是这样，他们仍旧犯罪，不信他奇妙的作为。","notes":[]},{"n":33,"t":"因此，他叫他们的日子全归虚空，叫他们的年岁尽属惊恐。","notes":[]},{"n":34,"t":"他杀他们的时候，他们才求问他，回心转意，切切地寻求神。","notes":[]},{"n":35,"t":"他们也追念神是他们的磐石，至高的神是他们的救赎主。","notes":[]},{"n":36,"t":"他们却用口谄媚他，用舌向他说谎。","notes":[]},{"n":37,"t":"因他们的心向他不正，在他的约上也不忠心。","notes":[]},{"n":38,"t":"但他有怜悯，赦免他们的罪孽，不灭绝他们，而且屡次消他的怒气，不发尽他的忿怒。","notes":[]},{"n":39,"t":"他想到他们不过是血气，是一阵去而不返的风。","notes":[]},{"n":40,"t":"他们在旷野悖逆他，在荒地叫他担忧，何其多呢！","notes":[]},{"n":41,"t":"他们再三试探神，惹动以色列的圣者。","notes":[]},{"n":42,"t":"他们不追念他的能力和赎他们脱离敌人的日子；","notes":["原文是手"]},{"n":43,"t":"他怎样在埃及地显神迹，在琐安田显奇事，","notes":[]},{"n":44,"t":"把他们的江河并河汊的水都变为血，使他们不能喝。","notes":[]},{"n":45,"t":"他叫苍蝇成群落在他们当中，嘬尽他们，又叫青蛙灭了他们，","notes":[]},{"n":46,"t":"把他们的土产交给蚂蚱，把他们辛苦得来的交给蝗虫。","notes":[]},{"n":47,"t":"他降冰雹打坏他们的葡萄树，下严霜打坏他们的桑树，","notes":[]},{"n":48,"t":"又把他们的牲畜交给冰雹，把他们的群畜交给闪电。","notes":[]},{"n":49,"t":"他使猛烈的怒气和忿怒、恼恨、苦难成了一群降灾的使者，临到他们。","notes":[]},{"n":50,"t":"他为自己的怒气修平了路，将他们交给瘟疫，使他们死亡，","notes":[]},{"n":51,"t":"在埃及击杀一切长子，在含的帐棚中击杀他们强壮时头生的。","notes":[]},{"n":52,"t":"他却领出自己的民如羊，在旷野引他们如羊群。","notes":[]},{"n":53,"t":"他领他们稳稳妥妥地，使他们不致害怕；海却淹没他们的仇敌。","notes":[]},{"n":54,"t":"他带他们到自己圣地的边界，到他右手所得的这山地。","notes":[]},{"n":55,"t":"他在他们面前赶出外邦人，用绳子将外邦的地量给他们为业，叫以色列支派的人住在他们的帐棚里。","notes":[]},{"n":56,"t":"他们仍旧试探、悖逆至高的神，不守他的法度，","notes":[]},{"n":57,"t":"反倒退后，行诡诈，像他们的祖宗一样；他们改变，如同翻背的弓。","notes":[]},{"n":58,"t":"因他们的邱坛惹了他的怒气；因他们雕刻的偶像触动他的愤恨。","notes":[]},{"n":59,"t":"神听见就发怒，极其憎恶以色列人。","notes":[]},{"n":60,"t":"甚至他离弃示罗的帐幕，就是他在人间所搭的帐棚；","notes":[]},{"n":61,"t":"又将他的约柜交与人掳去，将他的荣耀交在敌人手中；","notes":["原文是能力"]},{"n":62,"t":"并将他的百姓交与刀剑，向他的产业发怒。","notes":[]},{"n":63,"t":"少年人被火烧灭；处女也无喜歌。","notes":[]},{"n":64,"t":"祭司倒在刀下，寡妇却不哀哭。","notes":[]},{"n":65,"t":"那时，主像世人睡醒，像勇士饮酒呼喊。","notes":[]},{"n":66,"t":"他就打退了他的敌人，叫他们永蒙羞辱；","notes":[]},{"n":67,"t":"并且他弃掉约瑟的帐棚，不拣选以法莲支派，","notes":[]},{"n":68,"t":"却拣选犹大支派—他所喜爱的锡安山；","notes":[]},{"n":69,"t":"盖造他的圣所，好像高峰，又像他建立永存之地；","notes":[]},{"n":70,"t":"又拣选他的仆人大卫，从羊圈中将他召来，","notes":[]},{"n":71,"t":"叫他不再跟从那些带奶的母羊，为要牧养自己的百姓雅各和自己的产业以色列。","notes":[]},{"n":72,"t":"于是，他按心中的纯正牧养他们，用手中的巧妙引导他们。","notes":[]}]},"79":{"heading":"求主解救国家","verses":[{"n":1,"t":"神啊，外邦人进入你的产业，污秽你的圣殿，使耶路撒冷变成荒堆，","notes":[]},{"n":2,"t":"把你仆人的尸首交与天空的飞鸟为食，把你圣民的肉交与地上的野兽，","notes":[]},{"n":3,"t":"在耶路撒冷周围流他们的血如水，无人葬埋。","notes":[]},{"n":4,"t":"我们成为邻国的羞辱，成为我们四围人的嗤笑讥刺。","notes":[]},{"n":5,"t":"耶和华啊，这到几时呢？你要动怒到永远吗？你的愤恨要如火焚烧吗？","notes":[]},{"n":6,"t":"愿你将你的忿怒倒在那不认识你的外邦和那不求告你名的国度。","notes":[]},{"n":7,"t":"因为他们吞了雅各，把他的住处变为荒场。","notes":[]},{"n":8,"t":"求你不要记念我们先祖的罪孽，向我们追讨；愿你的慈悲快迎着我们，因为我们落到极卑微的地步。","notes":[]},{"n":9,"t":"拯救我们的神啊，求你因你名的荣耀帮助我们！为你名的缘故搭救我们，赦免我们的罪。","notes":[]},{"n":10,"t":"为何容外邦人说「他们的神在哪里」呢？愿你使外邦人知道你在我们眼前伸你仆人流血的冤。","notes":[]},{"n":11,"t":"愿被囚之人的叹息达到你面前；愿你按你的大能力存留那些将要死的人。","notes":[]},{"n":12,"t":"主啊，愿你将我们邻邦所羞辱你的羞辱加七倍归到他们身上。","notes":[]},{"n":13,"t":"这样，你的民，你草场的羊，要称谢你，直到永远；要述说赞美你的话，直到万代。","notes":[]}]},"80":{"heading":"求主复兴国家","verses":[{"n":1,"t":"领约瑟如领羊群之以色列的牧者啊，求你留心听！坐在二基路伯上的啊，求你发出光来！","notes":[]},{"n":2,"t":"在以法莲、便雅悯、玛拿西前面施展你的大能，来救我们。","notes":[]},{"n":3,"t":"神啊，求你使我们回转，使你的脸发光，我们便要得救！","notes":["或译：复兴"]},{"n":4,"t":"耶和华—万军之神啊，你向你百姓的祷告发怒，要到几时呢？","notes":[]},{"n":5,"t":"你以眼泪当食物给他们吃，又多量出眼泪给他们喝。","notes":[]},{"n":6,"t":"你使邻邦因我们纷争；我们的仇敌彼此戏笑。","notes":[]},{"n":7,"t":"万军之神啊，求你使我们回转，使你的脸发光，我们便要得救！","notes":[]},{"n":8,"t":"你从埃及挪出一棵葡萄树，赶出外邦人，把这树栽上。","notes":[]},{"n":9,"t":"你在这树根前预备了地方，它就深深扎根，爬满了地。","notes":[]},{"n":10,"t":"它的影子遮满了山，枝子好像佳美的香柏树。","notes":[]},{"n":11,"t":"它发出枝子，长到大海，发出蔓子，延到大河。","notes":[]},{"n":12,"t":"你为何拆毁这树的篱笆，任凭一切过路的人摘取？","notes":[]},{"n":13,"t":"林中出来的野猪把它糟踏；野地的走兽拿它当食物。","notes":[]},{"n":14,"t":"万军之神啊，求你回转！从天上垂看，眷顾这葡萄树，","notes":[]},{"n":15,"t":"保护你右手所栽的和你为自己所坚固的枝子。","notes":[]},{"n":16,"t":"这树已经被火焚烧，被刀砍伐；他们因你脸上的怒容就灭亡了。","notes":[]},{"n":17,"t":"愿你的手扶持你右边的人，就是你为自己所坚固的人子。","notes":[]},{"n":18,"t":"这样，我们便不退后离开你；求你救活我们，我们就要求告你的名。","notes":[]},{"n":19,"t":"耶和华—万军之神啊，求你使我们回转，使你的脸发光，我们便要得救！","notes":[]}]},"81":{"heading":"圣洁的诗","verses":[{"n":1,"t":"你们当向神—我们的力量大声欢呼，向雅各的神发声欢乐！","notes":[]},{"n":2,"t":"唱起诗歌，打手鼓，弹美琴与瑟。","notes":[]},{"n":3,"t":"当在月朔并月望—我们过节的日期吹角，","notes":[]},{"n":4,"t":"因这是为以色列定的律例，是雅各神的典章。","notes":[]},{"n":5,"t":"他去攻击埃及地的时候，在约瑟中间立此为证。我在那里听见我所不明白的言语：","notes":[]},{"n":6,"t":"神说：我使你的肩得脱重担，你的手放下筐子。","notes":[]},{"n":7,"t":"你在急难中呼求，我就搭救你；我在雷的隐密处应允你，在米利巴水那里试验你。 （细拉）","notes":[]},{"n":8,"t":"我的民哪，你当听，我要劝戒你；以色列啊，甚愿你肯听从我。","notes":[]},{"n":9,"t":"在你当中，不可有别的神；外邦的神，你也不可下拜。","notes":[]},{"n":10,"t":"我是耶和华—你的神，曾把你从埃及地领上来；你要大大张口，我就给你充满。","notes":[]},{"n":11,"t":"无奈，我的民不听我的声音；以色列全不理我。","notes":[]},{"n":12,"t":"我便任凭他们心里刚硬，随自己的计谋而行。","notes":[]},{"n":13,"t":"甚愿我的民肯听从我，以色列肯行我的道，","notes":[]},{"n":14,"t":"我便速速治服他们的仇敌，反手攻击他们的敌人。","notes":[]},{"n":15,"t":"恨耶和华的人必来投降，但他的百姓必永久长存。","notes":[]},{"n":16,"t":"他也必拿上好的麦子给他们吃，又拿从磐石出的蜂蜜叫他们饱足。","notes":[]}]},"82":{"heading":"神是最高的主宰","verses":[{"n":1,"t":"神站在有权力者的会中，在诸神中行审判，","notes":[]},{"n":2,"t":"说：你们审判不秉公义，徇恶人的情面，要到几时呢？ （细拉）","notes":[]},{"n":3,"t":"你们当为贫寒的人和孤儿伸冤；当为困苦和穷乏的人施行公义。","notes":[]},{"n":4,"t":"当保护贫寒和穷乏的人，救他们脱离恶人的手。","notes":[]},{"n":5,"t":"你们仍不知道，也不明白，在黑暗中走来走去；地的根基都摇动了。","notes":[]},{"n":6,"t":"我曾说：你们是神，都是至高者的儿子。","notes":[]},{"n":7,"t":"然而，你们要死，与世人一样，要仆倒，像王子中的一位。","notes":[]},{"n":8,"t":"神啊，求你起来审判世界，因为你要得万邦为业。","notes":[]}]},"83":{"heading":"求主败敌","verses":[{"n":1,"t":"神啊，求你不要静默！神啊，求你不要闭口，也不要不作声！","notes":[]},{"n":2,"t":"因为你的仇敌喧嚷，恨你的抬起头来。","notes":[]},{"n":3,"t":"他们同谋奸诈要害你的百姓，彼此商议要害你所隐藏的人。","notes":[]},{"n":4,"t":"他们说：来吧，我们将他们剪灭，使他们不再成国！使以色列的名不再被人记念！","notes":[]},{"n":5,"t":"他们同心商议，彼此结盟，要抵挡你，","notes":[]},{"n":6,"t":"就是住帐棚的以东人和以实玛利人，摩押和夏甲人，","notes":[]},{"n":7,"t":"迦巴勒、亚扪，和亚玛力、非利士并泰尔的居民。","notes":[]},{"n":8,"t":"亚述也与他们连合；他们作罗得子孙的帮手。 （细拉）","notes":[]},{"n":9,"t":"求你待他们，如待米甸，如在基顺河待西西拉和耶宾一样。","notes":[]},{"n":10,"t":"他们在隐·多珥灭亡，成了地上的粪土。","notes":[]},{"n":11,"t":"求你叫他们的首领像俄立和西伊伯，叫他们的王子都像西巴和撒慕拿。","notes":[]},{"n":12,"t":"他们说：我们要得神的住处，作为自己的产业。","notes":[]},{"n":13,"t":"我的神啊，求你叫他们像旋风的尘土，像风前的碎秸。","notes":[]},{"n":14,"t":"火怎样焚烧树林，火焰怎样烧着山岭，","notes":[]},{"n":15,"t":"求你也照样用狂风追赶他们，用暴雨恐吓他们。","notes":[]},{"n":16,"t":"愿你使他们满面羞耻，好叫他们寻求你—耶和华的名！","notes":[]},{"n":17,"t":"愿他们永远羞愧惊惶！愿他们惭愧灭亡！","notes":[]},{"n":18,"t":"使他们知道：惟独你—名为耶和华的—是全地以上的至高者！","notes":[]}]},"84":{"heading":"渴慕耶和华的殿宇","verses":[{"n":1,"t":"万军之耶和华啊，你的居所何等可爱！","notes":[]},{"n":2,"t":"我羡慕渴想耶和华的院宇；我的心肠，我的肉体向永生神呼吁。","notes":["或译：欢呼"]},{"n":3,"t":"万军之耶和华—我的王，我的神啊，在你祭坛那里，麻雀为自己找着房屋，燕子为自己找着抱雏之窝。","notes":[]},{"n":4,"t":"如此住在你殿中的便为有福！他们仍要赞美你。 （细拉）","notes":[]},{"n":5,"t":"靠你有力量、心中想往锡安大道的，这人便为有福！","notes":[]},{"n":6,"t":"他们经过「流泪谷」，叫这谷变为泉源之地；并有秋雨之福盖满了全谷。","notes":[]},{"n":7,"t":"他们行走，力上加力，各人到锡安朝见神。","notes":[]},{"n":8,"t":"耶和华—万军之神啊，求你听我的祷告！雅各的神啊，求你留心听！ （细拉）","notes":[]},{"n":9,"t":"神啊，你是我们的盾牌；求你垂顾观看你受膏者的面！","notes":[]},{"n":10,"t":"在你的院宇住一日，胜似在别处住千日；宁可在我神殿中看门，不愿住在恶人的帐棚里。","notes":[]},{"n":11,"t":"因为耶和华—神是日头，是盾牌，要赐下恩惠和荣耀。他未尝留下一样好处不给那些行动正直的人。","notes":[]},{"n":12,"t":"万军之耶和华啊，倚靠你的人便为有福！","notes":[]}]},"85":{"heading":"为国求福","verses":[{"n":1,"t":"耶和华啊，你已经向你的地施恩，救回被掳的雅各。","notes":[]},{"n":2,"t":"你赦免了你百姓的罪孽，遮盖了他们一切的过犯。 （细拉）","notes":[]},{"n":3,"t":"你收转了所发的忿怒和你猛烈的怒气。","notes":[]},{"n":4,"t":"拯救我们的神啊，求你使我们回转，叫你的恼恨向我们止息。","notes":[]},{"n":5,"t":"你要向我们发怒到永远吗？你要将你的怒气延留到万代吗？","notes":[]},{"n":6,"t":"你不再将我们救活，使你的百姓靠你欢喜吗？","notes":[]},{"n":7,"t":"耶和华啊，求你使我们得见你的慈爱，又将你的救恩赐给我们。","notes":[]},{"n":8,"t":"我要听神—耶和华所说的话；因为他必应许将平安赐给他的百姓—他的圣民；他们却不可再转去妄行。","notes":[]},{"n":9,"t":"他的救恩诚然与敬畏他的人相近，叫荣耀住在我们的地上。","notes":[]},{"n":10,"t":"慈爱和诚实彼此相遇；公义和平安彼此相亲。","notes":[]},{"n":11,"t":"诚实从地而生；公义从天而现。","notes":[]},{"n":12,"t":"耶和华必将好处赐给我们；我们的地也要多出土产。","notes":[]},{"n":13,"t":"公义要行在他面前，叫他的脚踪成为可走的路。","notes":[]}]},"86":{"heading":"求主恩助","verses":[{"n":1,"t":"耶和华啊，求你侧耳应允我，因我是困苦穷乏的。","notes":[]},{"n":2,"t":"求你保存我的性命，因我是虔诚人。我的神啊，求你拯救这倚靠你的仆人！","notes":[]},{"n":3,"t":"主啊，求你怜悯我，因我终日求告你。","notes":[]},{"n":4,"t":"主啊，求你使仆人心里欢喜，因为我的心仰望你。","notes":[]},{"n":5,"t":"主啊，你本为良善，乐意饶恕人，有丰盛的慈爱赐给凡求告你的人。","notes":[]},{"n":6,"t":"耶和华啊，求你留心听我的祷告，垂听我恳求的声音。","notes":[]},{"n":7,"t":"我在患难之日要求告你，因为你必应允我。","notes":[]},{"n":8,"t":"主啊，诸神之中没有可比你的；你的作为也无可比。","notes":[]},{"n":9,"t":"主啊，你所造的万民都要来敬拜你；他们也要荣耀你的名。","notes":[]},{"n":10,"t":"因你为大，且行奇妙的事；惟独你是神。","notes":[]},{"n":11,"t":"耶和华啊，求你将你的道指教我；我要照你的真理行；求你使我专心敬畏你的名！","notes":[]},{"n":12,"t":"主—我的神啊，我要一心称赞你；我要荣耀你的名，直到永远。","notes":[]},{"n":13,"t":"因为，你向我发的慈爱是大的；你救了我的灵魂免入极深的阴间。","notes":[]},{"n":14,"t":"神啊，骄傲的人起来攻击我，又有一党强横的人寻索我的命；他们没有将你放在眼中。","notes":[]},{"n":15,"t":"主啊，你是有怜悯有恩典的神，不轻易发怒，并有丰盛的慈爱和诚实。","notes":[]},{"n":16,"t":"求你向我转脸，怜恤我，将你的力量赐给仆人，救你婢女的儿子。","notes":[]},{"n":17,"t":"求你向我显出恩待我的凭据，叫恨我的人看见便羞愧，因为你—耶和华帮助我，安慰我。","notes":[]}]},"87":{"heading":"锡安颂","verses":[{"n":1,"t":"耶和华所立的根基在圣山上。","notes":[]},{"n":2,"t":"他爱锡安的门，胜于爱雅各一切的住处。","notes":[]},{"n":3,"t":"神的城啊，有荣耀的事乃指着你说的。 （细拉）","notes":[]},{"n":4,"t":"我要提起拉哈伯和巴比伦人，是在认识我之中的；看哪，非利士和泰尔并古实人，个个生在那里。","notes":[]},{"n":5,"t":"论到锡安，必说：这一个、那一个都生在其中，而且至高者必亲自坚立这城。","notes":[]},{"n":6,"t":"当耶和华记录万民的时候，他要点出这一个生在那里。 （细拉）","notes":[]},{"n":7,"t":"歌唱的，跳舞的，都要说：我的泉源都在你里面。","notes":[]}]},"88":{"heading":"求主眷顾","verses":[{"n":1,"t":"耶和华—拯救我的神啊，我昼夜在你面前呼吁。","notes":[]},{"n":2,"t":"愿我的祷告达到你面前；求你侧耳听我的呼求！","notes":[]},{"n":3,"t":"因为我心里满了患难；我的性命临近阴间。","notes":[]},{"n":4,"t":"我算和下坑的人同列，如同无力的人一样。","notes":["或译：没有帮助"]},{"n":5,"t":"我被丢在死人中，好像被杀的人躺在坟墓里。他们是你不再记念的，与你隔绝了。","notes":[]},{"n":6,"t":"你把我放在极深的坑里，在黑暗地方，在深处。","notes":[]},{"n":7,"t":"你的忿怒重压我身；你用一切的波浪困住我。 （细拉）","notes":[]},{"n":8,"t":"你把我所认识的隔在远处，使我为他们所憎恶；我被拘困，不得出来。","notes":[]},{"n":9,"t":"我的眼睛因困苦而干瘪。耶和华啊，我天天求告你，向你举手。","notes":[]},{"n":10,"t":"你岂要行奇事给死人看吗？难道阴魂还能起来称赞你吗？ （细拉）","notes":[]},{"n":11,"t":"岂能在坟墓里述说你的慈爱吗？岂能在灭亡中述说你的信实吗？","notes":[]},{"n":12,"t":"你的奇事岂能在幽暗里被知道吗？你的公义岂能在忘记之地被知道吗？","notes":[]},{"n":13,"t":"耶和华啊，我呼求你；我早晨的祷告要达到你面前。","notes":[]},{"n":14,"t":"耶和华啊，你为何丢弃我？为何掩面不顾我？","notes":[]},{"n":15,"t":"我自幼受苦，几乎死亡；我受你的惊恐，甚至慌张。","notes":[]},{"n":16,"t":"你的烈怒漫过我身；你的惊吓把我剪除。","notes":[]},{"n":17,"t":"这些终日如水环绕我，一齐都来围困我。","notes":[]},{"n":18,"t":"你把我的良朋密友隔在远处，使我所认识的人进入黑暗里。","notes":[]}]},"89":{"heading":"困难中的圣诗","verses":[{"n":1,"t":"我要歌唱耶和华的慈爱，直到永远；我要用口将你的信实传与万代。","notes":[]},{"n":2,"t":"因我曾说：你的慈悲必建立到永远；你的信实必坚立在天上。","notes":[]},{"n":3,"t":"我与我所拣选的人立了约，向我的仆人大卫起了誓：","notes":[]},{"n":4,"t":"我要建立你的后裔，直到永远；要建立你的宝座，直到万代。 （细拉）","notes":[]},{"n":5,"t":"耶和华啊，诸天要称赞你的奇事；在圣者的会中，要称赞你的信实。","notes":[]},{"n":6,"t":"在天空谁能比耶和华呢？神的众子中，谁能像耶和华呢？","notes":[]},{"n":7,"t":"他在圣者的会中，是大有威严的神，比一切在他四围的更可畏惧。","notes":[]},{"n":8,"t":"耶和华—万军之神啊，哪一个大能者像你耶和华？你的信实是在你的四围。","notes":[]},{"n":9,"t":"你管辖海的狂傲；波浪翻腾，你就使它平静了。","notes":[]},{"n":10,"t":"你打碎了拉哈伯，似乎是已杀的人；你用有能的膀臂打散了你的仇敌。","notes":[]},{"n":11,"t":"天属你，地也属你；世界和其中所充满的都为你所建立。","notes":[]},{"n":12,"t":"南北为你所创造；他泊和黑门都因你的名欢呼。","notes":[]},{"n":13,"t":"你有大能的膀臂；你的手有力，你的右手也高举。","notes":[]},{"n":14,"t":"公义和公平是你宝座的根基；慈爱和诚实行在你前面。","notes":[]},{"n":15,"t":"知道向你欢呼的，那民是有福的！耶和华啊，他们在你脸上的光里行走。","notes":[]},{"n":16,"t":"他们因你的名终日欢乐，因你的公义得以高举。","notes":[]},{"n":17,"t":"你是他们力量的荣耀；因为你喜悦我们，我们的角必被高举。","notes":[]},{"n":18,"t":"我们的盾牌属耶和华；我们的王属以色列的圣者。","notes":[]},{"n":19,"t":"当时，你在异象中晓谕你的圣民，说：我已把救助之力加在那有能者的身上；我高举那从民中所拣选的。","notes":[],"heads":["神对大卫的应许"]},{"n":20,"t":"我寻得我的仆人大卫，用我的圣膏膏他。","notes":[]},{"n":21,"t":"我的手必使他坚立；我的膀臂也必坚固他。","notes":[]},{"n":22,"t":"仇敌必不勒索他；凶恶之子也不苦害他。","notes":[]},{"n":23,"t":"我要在他面前打碎他的敌人，击杀那恨他的人。","notes":[]},{"n":24,"t":"只是我的信实和我的慈爱要与他同在；因我的名，他的角必被高举。","notes":[]},{"n":25,"t":"我要使他的左手伸到海上，右手伸到河上。","notes":[]},{"n":26,"t":"他要称呼我说：你是我的父，是我的神，是拯救我的磐石。","notes":[]},{"n":27,"t":"我也要立他为长子，为世上最高的君王。","notes":[]},{"n":28,"t":"我要为他存留我的慈爱，直到永远；我与他立的约必要坚定。","notes":[]},{"n":29,"t":"我也要使他的后裔存到永远，使他的宝座如天之久。","notes":[]},{"n":30,"t":"倘若他的子孙离弃我的律法，不照我的典章行，","notes":[]},{"n":31,"t":"背弃我的律例，不遵守我的诫命，","notes":[]},{"n":32,"t":"我就要用杖责罚他们的过犯，用鞭责罚他们的罪孽。","notes":[]},{"n":33,"t":"只是我必不将我的慈爱全然收回，也必不叫我的信实废弃。","notes":[]},{"n":34,"t":"我必不背弃我的约，也不改变我口中所出的。","notes":[]},{"n":35,"t":"我一次指着自己的圣洁起誓：我决不向大卫说谎！","notes":[]},{"n":36,"t":"他的后裔要存到永远；他的宝座在我面前如日之恒一般，","notes":[]},{"n":37,"t":"又如月亮永远坚立，如天上确实的见证。 （细拉）","notes":[]},{"n":38,"t":"但你恼怒你的受膏者，就丢掉弃绝他。","notes":[],"heads":["君主惨败的哀歌"]},{"n":39,"t":"你厌恶了与仆人所立的约，将他的冠冕践踏于地。","notes":[]},{"n":40,"t":"你拆毁了他一切的篱笆，使他的保障变为荒场。","notes":[]},{"n":41,"t":"凡过路的人都抢夺他；他成为邻邦的羞辱。","notes":[]},{"n":42,"t":"你高举了他敌人的右手；你叫他一切的仇敌欢喜。","notes":[]},{"n":43,"t":"你叫他的刀剑卷刃，叫他在争战之中站立不住。","notes":[]},{"n":44,"t":"你使他的光辉止息，将他的宝座推倒于地。","notes":[]},{"n":45,"t":"你减少他青年的日子，又使他蒙羞。 （细拉）","notes":[]},{"n":46,"t":"耶和华啊，这要到几时呢？你要将自己隐藏到永远吗？你的忿怒如火焚烧要到几时呢？","notes":[],"heads":["求救的祷告"]},{"n":47,"t":"求你想念我的时候是何等的短少；你创造世人，要使他们归何等的虚空呢？","notes":[]},{"n":48,"t":"谁能常活免死、救他的灵魂脱离阴间的权柄呢？ （细拉）","notes":[]},{"n":49,"t":"主啊，你从前凭你的信实向大卫立誓要施行的慈爱在哪里呢？","notes":[]},{"n":50,"t":"主啊，求你记念仆人们所受的羞辱，记念我怎样将一切强盛民的羞辱存在我怀里。","notes":[]},{"n":51,"t":"耶和华啊，你的仇敌用这羞辱羞辱了你的仆人，羞辱了你受膏者的脚踪。","notes":[]},{"n":52,"t":"耶和华是应当称颂的，直到永远。阿们！阿们！","notes":[]}]},"90":{"heading":"神与人","verses":[{"n":1,"t":"主啊，你世世代代作我们的居所。","notes":[]},{"n":2,"t":"诸山未曾生出，地与世界你未曾造成，从亘古到永远，你是神。","notes":[]},{"n":3,"t":"你使人归于尘土，说：你们世人要归回。","notes":[]},{"n":4,"t":"在你看来，千年如已过的昨日，又如夜间的一更。","notes":[]},{"n":5,"t":"你叫他们如水冲去；他们如睡一觉。早晨，他们如生长的草，","notes":[]},{"n":6,"t":"早晨发芽生长，晚上割下枯干。","notes":[]},{"n":7,"t":"我们因你的怒气而消灭，因你的忿怒而惊惶。","notes":[]},{"n":8,"t":"你将我们的罪孽摆在你面前，将我们的隐恶摆在你面光之中。","notes":[]},{"n":9,"t":"我们经过的日子都在你震怒之下；我们度尽的年岁好像一声叹息。","notes":[]},{"n":10,"t":"我们一生的年日是七十岁，若是强壮可到八十岁；但其中所矜夸的不过是劳苦愁烦，转眼成空，我们便如飞而去。","notes":[]},{"n":11,"t":"谁晓得你怒气的权势？谁按着你该受的敬畏晓得你的忿怒呢？","notes":[]},{"n":12,"t":"求你指教我们怎样数算自己的日子，好叫我们得着智慧的心。","notes":[]},{"n":13,"t":"耶和华啊，我们要等到几时呢？求你转回，为你的仆人后悔。","notes":[]},{"n":14,"t":"求你使我们早早饱得你的慈爱，好叫我们一生一世欢呼喜乐。","notes":[]},{"n":15,"t":"求你照着你使我们受苦的日子，和我们遭难的年岁，叫我们喜乐。","notes":[]},{"n":16,"t":"愿你的作为向你仆人显现；愿你的荣耀向他们子孙显明。","notes":[]},{"n":17,"t":"愿主—我们神的荣美归于我们身上。愿你坚立我们手所做的工；我们手所做的工，愿你坚立。","notes":[]}]},"91":{"heading":"神是我们的保护者","verses":[{"n":1,"t":"住在至高者隐密处的，必住在全能者的荫下。","notes":[]},{"n":2,"t":"我要论到耶和华说：他是我的避难所，是我的山寨，是我的神，是我所倚靠的。","notes":[]},{"n":3,"t":"他必救你脱离捕鸟人的网罗和毒害的瘟疫。","notes":[]},{"n":4,"t":"他必用自己的翎毛遮蔽你；你要投靠在他的翅膀底下；他的诚实是大小的盾牌。","notes":[]},{"n":5,"t":"你必不怕黑夜的惊骇，或是白日飞的箭，","notes":[]},{"n":6,"t":"也不怕黑夜行的瘟疫，或是午间灭人的毒病。","notes":[]},{"n":7,"t":"虽有千人仆倒在你旁边，万人仆倒在你右边，这灾却不得临近你。","notes":[]},{"n":8,"t":"你惟亲眼观看，见恶人遭报。","notes":[]},{"n":9,"t":"耶和华是我的避难所；你已将至高者当你的居所，","notes":[]},{"n":10,"t":"祸患必不临到你，灾害也不挨近你的帐棚。","notes":[]},{"n":11,"t":"因他要为你吩咐他的使者，在你行的一切道路上保护你。","notes":[]},{"n":12,"t":"他们要用手托着你，免得你的脚碰在石头上。","notes":[]},{"n":13,"t":"你要踹在狮子和虺蛇的身上，践踏少壮狮子和大蛇。","notes":[]},{"n":14,"t":"神说：因为他专心爱我，我就要搭救他；因为他知道我的名，我要把他安置在高处。","notes":[]},{"n":15,"t":"他若求告我，我就应允他；他在急难中，我要与他同在；我要搭救他，使他尊贵。","notes":[]},{"n":16,"t":"我要使他足享长寿，将我的救恩显明给他。","notes":[]}]},"92":{"heading":"颂赞之诗","verses":[{"n":1,"t":"称谢耶和华！歌颂你至高者的名！","notes":[]},{"n":2,"t":"用十弦的乐器和瑟，用琴弹幽雅的声音，早晨传扬你的慈爱；每夜传扬你的信实。这本为美事。","notes":[],"end":3},{"n":4,"t":"因你—耶和华借着你的作为叫我高兴，我要因你手的工作欢呼。","notes":[]},{"n":5,"t":"耶和华啊，你的工作何其大！你的心思极其深！","notes":[]},{"n":6,"t":"畜类人不晓得；愚顽人也不明白。","notes":[]},{"n":7,"t":"恶人茂盛如草，一切作孽之人发旺的时候，正是他们要灭亡，直到永远。","notes":[]},{"n":8,"t":"惟你—耶和华是至高，直到永远。","notes":[]},{"n":9,"t":"耶和华啊，你的仇敌都要灭亡；一切作孽的也要离散。","notes":[]},{"n":10,"t":"你却高举了我的角，如野牛的角；我是被新油膏了的。","notes":[]},{"n":11,"t":"我眼睛看见仇敌遭报；我耳朵听见那些起来攻击我的恶人受罚。","notes":[]},{"n":12,"t":"义人要发旺如棕树，生长如黎巴嫩的香柏树。","notes":[]},{"n":13,"t":"他们栽于耶和华的殿中，发旺在我们神的院里。","notes":[]},{"n":14,"t":"他们年老的时候仍要结果子，要满了汁浆而常发青，","notes":[]},{"n":15,"t":"好显明耶和华是正直的。他是我的磐石，在他毫无不义。","notes":[]}]},"93":{"heading":"神是王","verses":[{"n":1,"t":"耶和华作王！他以威严为衣穿上；耶和华以能力为衣，以能力束腰，世界就坚定，不得动摇。","notes":[]},{"n":2,"t":"你的宝座从太初立定；你从亘古就有。","notes":[]},{"n":3,"t":"耶和华啊，大水扬起，大水发声，波浪澎湃。","notes":[]},{"n":4,"t":"耶和华在高处大有能力，胜过诸水的响声，洋海的大浪。","notes":[]},{"n":5,"t":"耶和华啊，你的法度最的确；你的殿永称为圣，是合宜的。","notes":[]}]},"94":{"heading":"神审判万人","verses":[{"n":1,"t":"耶和华啊，你是伸冤的神；伸冤的神啊，求你发出光来！","notes":[]},{"n":2,"t":"审判世界的主啊，求你挺身而立，使骄傲人受应得的报应！","notes":[]},{"n":3,"t":"耶和华啊，恶人夸胜要到几时呢？要到几时呢？","notes":[]},{"n":4,"t":"他们絮絮叨叨说傲慢的话；一切作孽的人都自己夸张。","notes":[]},{"n":5,"t":"耶和华啊，他们强压你的百姓，苦害你的产业。","notes":[]},{"n":6,"t":"他们杀死寡妇和寄居的，又杀害孤儿。","notes":[]},{"n":7,"t":"他们说：耶和华必不看见；雅各的神必不思念。","notes":[]},{"n":8,"t":"你们民间的畜类人当思想；你们愚顽人到几时才有智慧呢？","notes":[]},{"n":9,"t":"造耳朵的，难道自己不听见吗？造眼睛的，难道自己不看见吗？","notes":[]},{"n":10,"t":"管教列邦的，就是叫人得知识的，难道自己不惩治人吗？","notes":[]},{"n":11,"t":"耶和华知道人的意念是虚妄的。","notes":[]},{"n":12,"t":"耶和华啊，你所管教、用律法所教训的人是有福的！","notes":[]},{"n":13,"t":"你使他在遭难的日子得享平安；惟有恶人陷在所挖的坑中。","notes":[]},{"n":14,"t":"因为耶和华必不丢弃他的百姓，也不离弃他的产业。","notes":[]},{"n":15,"t":"审判要转向公义；心里正直的，必都随从。","notes":[]},{"n":16,"t":"谁肯为我起来攻击作恶的？谁肯为我站起抵挡作孽的？","notes":[]},{"n":17,"t":"若不是耶和华帮助我，我就住在寂静之中了。","notes":[]},{"n":18,"t":"我正说我失了脚，耶和华啊，那时你的慈爱扶助我。","notes":[]},{"n":19,"t":"我心里多忧多疑，你安慰我，就使我欢乐。","notes":[]},{"n":20,"t":"那借着律例架弄残害、在位上行奸恶的，岂能与你相交吗？","notes":[]},{"n":21,"t":"他们大家聚集攻击义人，将无辜的人定为死罪。","notes":[]},{"n":22,"t":"但耶和华向来作了我的高台；我的神作了我投靠的磐石。","notes":[]},{"n":23,"t":"他叫他们的罪孽归到他们身上。他们正在行恶之中，他要剪除他们；耶和华—我们的神要把他们剪除。","notes":[]}]},"95":{"heading":"颂赞之诗","verses":[{"n":1,"t":"来啊，我们要向耶和华歌唱，向拯救我们的磐石欢呼！","notes":[]},{"n":2,"t":"我们要来感谢他，用诗歌向他欢呼！","notes":[]},{"n":3,"t":"因耶和华为大神，为大王，超乎万神之上。","notes":[]},{"n":4,"t":"地的深处在他手中；山的高峰也属他。","notes":[]},{"n":5,"t":"海洋属他，是他造的；旱地也是他手造成的。","notes":[]},{"n":6,"t":"来啊，我们要屈身敬拜，在造我们的耶和华面前跪下。","notes":[]},{"n":7,"t":"因为他是我们的神；我们是他草场的羊，是他手下的民。惟愿你们今天听他的话：","notes":[]},{"n":8,"t":"你们不可硬着心，像当日在米利巴，就是在旷野的玛撒。","notes":[]},{"n":9,"t":"那时，你们的祖宗试我探我，并且观看我的作为。","notes":[]},{"n":10,"t":"四十年之久，我厌烦那世代，说：这是心里迷糊的百姓，竟不晓得我的作为！","notes":[]},{"n":11,"t":"所以，我在怒中起誓，说：他们断不可进入我的安息！","notes":[]}]},"96":{"heading":"神是最高的君王","verses":[{"n":1,"t":"你们要向耶和华唱新歌！全地都要向耶和华歌唱！","notes":[]},{"n":2,"t":"要向耶和华歌唱，称颂他的名！天天传扬他的救恩！","notes":[]},{"n":3,"t":"在列邦中述说他的荣耀！在万民中述说他的奇事！","notes":[]},{"n":4,"t":"因耶和华为大，当受极大的赞美；他在万神之上，当受敬畏。","notes":[]},{"n":5,"t":"外邦的神都属虚无；惟独耶和华创造诸天。","notes":[]},{"n":6,"t":"有尊荣和威严在他面前；有能力与华美在他圣所。","notes":[]},{"n":7,"t":"民中的万族啊，你们要将荣耀、能力归给耶和华，都归给耶和华！","notes":[]},{"n":8,"t":"要将耶和华的名所当得的荣耀归给他，拿供物来进入他的院宇。","notes":[]},{"n":9,"t":"当以圣洁的妆饰敬拜耶和华；全地要在他面前战抖！","notes":["的：或译为"]},{"n":10,"t":"人在列邦中要说：耶和华作王！世界就坚定，不得动摇；他要按公正审判众民。","notes":[]},{"n":11,"t":"愿天欢喜，愿地快乐！愿海和其中所充满的澎湃！","notes":[]},{"n":12,"t":"愿田和其中所有的都欢乐！那时，林中的树木都要在耶和华面前欢呼。","notes":[]},{"n":13,"t":"因为他来了，他来要审判全地。他要按公义审判世界，按他的信实审判万民。","notes":[]}]},"97":{"heading":"神是最高的统治者","verses":[{"n":1,"t":"耶和华作王！愿地快乐！愿众海岛欢喜！","notes":[]},{"n":2,"t":"密云和幽暗在他的四围；公义和公平是他宝座的根基。","notes":[]},{"n":3,"t":"有烈火在他前头行，烧灭他四围的敌人。","notes":[]},{"n":4,"t":"他的闪电光照世界，大地看见便震动。","notes":[]},{"n":5,"t":"诸山见耶和华的面，就是全地之主的面，便消化如蜡。","notes":[]},{"n":6,"t":"诸天表明他的公义；万民看见他的荣耀。","notes":[]},{"n":7,"t":"愿一切事奉雕刻的偶像、靠虚无之神自夸的，都蒙羞愧。万神哪，你们都当拜他。","notes":[]},{"n":8,"t":"耶和华啊，锡安听见你的判断就欢喜；犹大的城邑也都快乐。","notes":["原文是女子"]},{"n":9,"t":"因为你—耶和华至高，超乎全地；你被尊崇，远超万神之上。","notes":[]},{"n":10,"t":"你们爱耶和华的，都当恨恶罪恶；他保护圣民的性命，搭救他们脱离恶人的手。","notes":[]},{"n":11,"t":"散布亮光是为义人；预备喜乐是为正直人。","notes":[]},{"n":12,"t":"你们义人当靠耶和华欢喜，称谢他可记念的圣名。","notes":[]}]},"98":{"heading":"神掌管世界","verses":[{"n":1,"t":"你们要向耶和华唱新歌！因为他行过奇妙的事；他的右手和圣臂施行救恩。","notes":[]},{"n":2,"t":"耶和华发明了他的救恩，在列邦人眼前显出公义；","notes":[]},{"n":3,"t":"记念他向以色列家所发的慈爱，所凭的信实。地的四极都看见我们神的救恩。","notes":[]},{"n":4,"t":"全地都要向耶和华欢乐；要发起大声，欢呼歌颂！","notes":[]},{"n":5,"t":"要用琴歌颂耶和华，用琴和诗歌的声音歌颂他！","notes":[]},{"n":6,"t":"用号和角声，在大君王耶和华面前欢呼！","notes":[]},{"n":7,"t":"愿海和其中所充满的澎湃；世界和住在其间的也要发声。","notes":[]},{"n":8,"t":"愿大水拍手；愿诸山在耶和华面前一同欢呼；","notes":[]},{"n":9,"t":"因为他来要审判遍地。他要按公义审判世界，按公正审判万民。","notes":[]}]},"99":{"heading":"神是至高之王","verses":[{"n":1,"t":"耶和华作王；万民当战抖！他坐在二基路伯上，地当动摇。","notes":[]},{"n":2,"t":"耶和华在锡安为大；他超乎万民之上。","notes":[]},{"n":3,"t":"他们当称赞他大而可畏的名；他本为圣！","notes":[]},{"n":4,"t":"王有能力，喜爱公平，坚立公正，在雅各中施行公平和公义。","notes":[]},{"n":5,"t":"你们当尊崇耶和华—我们的神，在他脚凳前下拜。他本为圣！","notes":[]},{"n":6,"t":"在他的祭司中有摩西和亚伦；在求告他名的人中有撒母耳。他们求告耶和华，他就应允他们。","notes":[]},{"n":7,"t":"他在云柱中对他们说话；他们遵守他的法度和他所赐给他们的律例。","notes":[]},{"n":8,"t":"耶和华—我们的神啊，你应允他们；你是赦免他们的神，却按他们所行的报应他们。","notes":[]},{"n":9,"t":"你们要尊崇耶和华—我们的神，在他的圣山下拜，因为耶和华—我们的神本为圣！","notes":[]}]},"100":{"heading":"颂赞之诗","verses":[{"n":1,"t":"普天下当向耶和华欢呼！","notes":[]},{"n":2,"t":"你们当乐意事奉耶和华，当来向他歌唱！","notes":[]},{"n":3,"t":"你们当晓得耶和华是神！我们是他造的，也是属他的；我们是他的民，也是他草场的羊。","notes":[]},{"n":4,"t":"当称谢进入他的门；当赞美进入他的院。当感谢他，称颂他的名！","notes":[]},{"n":5,"t":"因为耶和华本为善。他的慈爱存到永远；他的信实直到万代。","notes":[]}]},"101":{"heading":"王的诺言","verses":[{"n":1,"t":"我要歌唱慈爱和公平；耶和华啊，我要向你歌颂！","notes":[]},{"n":2,"t":"我要用智慧行完全的道。你几时到我这里来呢？我要存完全的心行在我家中。","notes":[]},{"n":3,"t":"邪僻的事，我都不摆在我眼前；悖逆人所做的事，我甚恨恶，不容沾在我身上。","notes":[]},{"n":4,"t":"弯曲的心思，我必远离；一切的恶人，我不认识。","notes":["或译：恶事"]},{"n":5,"t":"在暗中谗谤他邻居的，我必将他灭绝；眼目高傲、心里骄纵的，我必不容他。","notes":[]},{"n":6,"t":"我眼要看国中的诚实人，叫他们与我同住；行为完全的，他要伺候我。","notes":[]},{"n":7,"t":"行诡诈的，必不得住在我家里；说谎话的，必不得立在我眼前。","notes":[]},{"n":8,"t":"我每日早晨要灭绝国中所有的恶人，好把一切作孽的从耶和华的城里剪除。","notes":[]}]},"102":{"heading":"遭难中的祈祷","verses":[{"n":1,"t":"耶和华啊，求你听我的祷告，容我的呼求达到你面前！","notes":[]},{"n":2,"t":"我在急难的日子，求你向我侧耳；不要向我掩面！我呼求的日子，求你快快应允我！","notes":[]},{"n":3,"t":"因为，我的年日如烟云消灭；我的骨头如火把烧着。","notes":[]},{"n":4,"t":"我的心被伤，如草枯干，甚至我忘记吃饭。","notes":[]},{"n":5,"t":"因我唉哼的声音，我的肉紧贴骨头。","notes":[]},{"n":6,"t":"我如同旷野的鹈鹕；我好像荒场的鸮鸟。","notes":[]},{"n":7,"t":"我警醒不睡；我像房顶上孤单的麻雀。","notes":[]},{"n":8,"t":"我的仇敌终日辱骂我；向我猖狂的人指着我赌咒。","notes":[]},{"n":9,"t":"我吃过炉灰，如同吃饭；我所喝的与眼泪搀杂。","notes":[]},{"n":10,"t":"这都因你的恼恨和忿怒；你把我拾起来，又把我摔下去。","notes":[]},{"n":11,"t":"我的年日如日影偏斜；我也如草枯干。","notes":[]},{"n":12,"t":"惟你—耶和华必存到永远；你可记念的名也存到万代。","notes":[]},{"n":13,"t":"你必起来怜恤锡安，因现在是可怜她的时候，日期已经到了。","notes":[]},{"n":14,"t":"你的仆人原来喜悦她的石头，可怜她的尘土。","notes":[]},{"n":15,"t":"列国要敬畏耶和华的名；世上诸王都敬畏你的荣耀。","notes":[]},{"n":16,"t":"因为耶和华建造了锡安，在他荣耀里显现。","notes":[]},{"n":17,"t":"他垂听穷人的祷告，并不藐视他们的祈求。","notes":[]},{"n":18,"t":"这必为后代的人记下，将来受造的民要赞美耶和华。","notes":[]},{"n":19,"t":"因为，他从至高的圣所垂看；耶和华从天向地观察，","notes":[]},{"n":20,"t":"要垂听被囚之人的叹息，要释放将要死的人，","notes":[]},{"n":21,"t":"使人在锡安传扬耶和华的名，在耶路撒冷传扬赞美他的话，","notes":[]},{"n":22,"t":"就是在万民和列国聚会事奉耶和华的时候。","notes":[]},{"n":23,"t":"他使我的力量中道衰弱，使我的年日短少。","notes":[]},{"n":24,"t":"我说：我的神啊，不要使我中年去世。你的年数世世无穷！","notes":[]},{"n":25,"t":"你起初立了地的根基；天也是你手所造的。","notes":[]},{"n":26,"t":"天地都要灭没，你却要长存；天地都要如外衣渐渐旧了。你要将天地如里衣更换，天地就都改变了。","notes":[]},{"n":27,"t":"惟有你永不改变；你的年数没有穷尽。","notes":[]},{"n":28,"t":"你仆人的子孙要长存；他们的后裔要坚立在你面前。","notes":[]}]},"103":{"heading":"耶和华的慈爱","verses":[{"n":1,"t":"我的心哪，你要称颂耶和华！凡在我里面的，也要称颂他的圣名！","notes":[]},{"n":2,"t":"我的心哪，你要称颂耶和华！不可忘记他的一切恩惠！","notes":[]},{"n":3,"t":"他赦免你的一切罪孽，医治你的一切疾病。","notes":[]},{"n":4,"t":"他救赎你的命脱离死亡，以仁爱和慈悲为你的冠冕。","notes":[]},{"n":5,"t":"他用美物使你所愿的得以知足，以致你如鹰返老还童。","notes":[]},{"n":6,"t":"耶和华施行公义，为一切受屈的人伸冤。","notes":[]},{"n":7,"t":"他使摩西知道他的法则，叫以色列人晓得他的作为。","notes":[]},{"n":8,"t":"耶和华有怜悯，有恩典，不轻易发怒，且有丰盛的慈爱。","notes":[]},{"n":9,"t":"他不长久责备，也不永远怀怒。","notes":[]},{"n":10,"t":"他没有按我们的罪过待我们，也没有照我们的罪孽报应我们。","notes":[]},{"n":11,"t":"天离地何等的高，他的慈爱向敬畏他的人也是何等的大！","notes":[]},{"n":12,"t":"东离西有多远，他叫我们的过犯离我们也有多远！","notes":[]},{"n":13,"t":"父亲怎样怜恤他的儿女，耶和华也怎样怜恤敬畏他的人！","notes":[]},{"n":14,"t":"因为他知道我们的本体，思念我们不过是尘土。","notes":[]},{"n":15,"t":"至于世人，他的年日如草一样。他发旺如野地的花，","notes":[]},{"n":16,"t":"经风一吹，便归无有；它的原处也不再认识它。","notes":[]},{"n":17,"t":"但耶和华的慈爱归于敬畏他的人，从亘古到永远；他的公义也归于子子孙孙—","notes":[]},{"n":18,"t":"就是那些遵守他的约、记念他的训词而遵行的人。","notes":[]},{"n":19,"t":"耶和华在天上立定宝座；他的权柄统管万有。","notes":["原文是国"]},{"n":20,"t":"听从他命令、成全他旨意、有大能的天使，都要称颂耶和华！","notes":[]},{"n":21,"t":"你们作他的诸军，作他的仆役，行他所喜悦的，都要称颂耶和华！","notes":[]},{"n":22,"t":"你们一切被他造的，在他所治理的各处，都要称颂耶和华！我的心哪，你要称颂耶和华！","notes":[]}]},"104":{"heading":"造化主颂","verses":[{"n":1,"t":"我的心哪，你要称颂耶和华！耶和华—我的神啊，你为至大！你以尊荣威严为衣服，","notes":[]},{"n":2,"t":"披上亮光，如披外袍，铺张穹苍，如铺幔子，","notes":[]},{"n":3,"t":"在水中立楼阁的栋梁，用云彩为车辇，借着风的翅膀而行，","notes":[]},{"n":4,"t":"以风为使者，以火焰为仆役，","notes":[]},{"n":5,"t":"将地立在根基上，使地永不动摇。","notes":[]},{"n":6,"t":"你用深水遮盖地面，犹如衣裳；诸水高过山岭。","notes":[]},{"n":7,"t":"你的斥责一发，水便奔逃；你的雷声一发，水便奔流。","notes":[]},{"n":8,"t":"诸山升上，诸谷沉下，归你为它所安定之地。","notes":["或译：随山上翻，随谷下流"]},{"n":9,"t":"你定了界限，使水不能过去，不再转回遮盖地面。","notes":[]},{"n":10,"t":"耶和华使泉源涌在山谷，流在山间，","notes":[]},{"n":11,"t":"使野地的走兽有水喝，野驴得解其渴。","notes":[]},{"n":12,"t":"天上的飞鸟在水旁住宿，在树枝上啼叫。","notes":[]},{"n":13,"t":"他从楼阁中浇灌山岭；因他作为的功效，地就丰足。","notes":[]},{"n":14,"t":"他使草生长，给六畜吃，使菜蔬发长，供给人用，使人从地里能得食物，","notes":[]},{"n":15,"t":"又得酒能悦人心，得油能润人面，得粮能养人心。","notes":[]},{"n":16,"t":"佳美的树木，就是黎巴嫩的香柏树，是耶和华所栽种的，都满了汁浆。","notes":[]},{"n":17,"t":"雀鸟在其上搭窝；至于鹤，松树是它的房屋。","notes":[]},{"n":18,"t":"高山为野山羊的住所；岩石为沙番的藏处。","notes":[]},{"n":19,"t":"你安置月亮为定节令；日头自知沉落。","notes":[]},{"n":20,"t":"你造黑暗为夜，林中的百兽就都爬出来。","notes":[]},{"n":21,"t":"少壮狮子吼叫，要抓食，向神寻求食物。","notes":[]},{"n":22,"t":"日头一出，兽便躲避，卧在洞里。","notes":[]},{"n":23,"t":"人出去做工，劳碌直到晚上。","notes":[]},{"n":24,"t":"耶和华啊，你所造的何其多！都是你用智慧造成的；遍地满了你的丰富。","notes":[]},{"n":25,"t":"那里有海，又大又广；其中有无数的动物，大小活物都有。","notes":[]},{"n":26,"t":"那里有船行走，有你所造的鳄鱼游泳在其中。","notes":[]},{"n":27,"t":"这都仰望你按时给它食物。","notes":[]},{"n":28,"t":"你给它们，它们便拾起来；你张手，它们饱得美食。","notes":[]},{"n":29,"t":"你掩面，它们便惊惶；你收回它们的气，它们就死亡，归于尘土。","notes":[]},{"n":30,"t":"你发出你的灵，它们便受造；你使地面更换为新。","notes":[]},{"n":31,"t":"愿耶和华的荣耀存到永远！愿耶和华喜悦自己所造的！","notes":[]},{"n":32,"t":"他看地，地便震动；他摸山，山就冒烟。","notes":[]},{"n":33,"t":"我要一生向耶和华唱诗！我还活的时候，要向我神歌颂！","notes":[]},{"n":34,"t":"愿他以我的默念为甘甜！我要因耶和华欢喜！","notes":[]},{"n":35,"t":"愿罪人从世上消灭！愿恶人归于无有！我的心哪，要称颂耶和华！你们要赞美耶和华！","notes":["原文是哈利路亚；下同"]}]},"105":{"heading":"神和他的子民","verses":[{"n":1,"t":"你们要称谢耶和华，求告他的名，在万民中传扬他的作为！","notes":[]},{"n":2,"t":"要向他唱诗歌颂，谈论他一切奇妙的作为！","notes":[]},{"n":3,"t":"要以他的圣名夸耀！寻求耶和华的人，心中应当欢喜！","notes":[]},{"n":4,"t":"要寻求耶和华与他的能力，时常寻求他的面。","notes":[]},{"n":5,"t":"他仆人亚伯拉罕的后裔，他所拣选雅各的子孙哪，你们要记念他奇妙的作为和他的奇事，并他口中的判语。","notes":[],"end":6},{"n":7,"t":"他是耶和华—我们的神；全地都有他的判断。","notes":[]},{"n":8,"t":"他记念他的约，直到永远；他所吩咐的话，直到千代—","notes":[]},{"n":9,"t":"就是与亚伯拉罕所立的约，向以撒所起的誓。","notes":[]},{"n":10,"t":"他又将这约向雅各定为律例，向以色列定为永远的约，","notes":[]},{"n":11,"t":"说：我必将迦南地赐给你，作你产业的分。","notes":[]},{"n":12,"t":"当时，他们人丁有限，数目稀少，并且在那地为寄居的。","notes":[]},{"n":13,"t":"他们从这邦游到那邦，从这国行到那国。","notes":[]},{"n":14,"t":"他不容什么人欺负他们，为他们的缘故责备君王，","notes":[]},{"n":15,"t":"说：不可难为我受膏的人，也不可恶待我的先知。","notes":[]},{"n":16,"t":"他命饥荒降在那地上，将所倚靠的粮食全行断绝，","notes":[]},{"n":17,"t":"在他们以先打发一个人去—约瑟被卖为奴仆。","notes":[]},{"n":18,"t":"人用脚镣伤他的脚；他被铁链捆拘。","notes":[]},{"n":19,"t":"耶和华的话试炼他，直等到他所说的应验了。","notes":[]},{"n":20,"t":"王打发人把他解开，就是治理众民的，把他释放，","notes":[]},{"n":21,"t":"立他作王家之主，掌管他一切所有的，","notes":[]},{"n":22,"t":"使他随意捆绑他的臣宰，将智慧教导他的长老。","notes":[]},{"n":23,"t":"以色列也到了埃及；雅各在含地寄居。","notes":[]},{"n":24,"t":"耶和华使他的百姓生养众多，使他们比敌人强盛，","notes":[]},{"n":25,"t":"使敌人的心转去恨他的百姓，并用诡计待他的仆人。","notes":[]},{"n":26,"t":"他打发他的仆人摩西和他所拣选的亚伦，","notes":[]},{"n":27,"t":"在敌人中间显他的神迹，在含地显他的奇事。","notes":[]},{"n":28,"t":"他命黑暗，就有黑暗；没有违背他话的。","notes":[]},{"n":29,"t":"他叫埃及的水变为血，叫他们的鱼死了。","notes":[]},{"n":30,"t":"在他们的地上以及王宫的内室，青蛙多多滋生。","notes":[]},{"n":31,"t":"他说一声，苍蝇就成群而来，并有虱子进入他们四境。","notes":[]},{"n":32,"t":"他给他们降下冰雹为雨，在他们的地上降下火焰。","notes":[]},{"n":33,"t":"他也击打他们的葡萄树和无花果树，毁坏他们境内的树木。","notes":[]},{"n":34,"t":"他说一声，就有蝗虫蚂蚱上来，不计其数，","notes":[]},{"n":35,"t":"吃尽了他们地上各样的菜蔬和田地的出产。","notes":[]},{"n":36,"t":"他又击杀他们国内一切的长子，就是他们强壮时头生的。","notes":[]},{"n":37,"t":"他领自己的百姓带银子金子出来；他支派中没有一个软弱的。","notes":[]},{"n":38,"t":"他们出来的时候，埃及人便欢喜；原来埃及人惧怕他们。","notes":[]},{"n":39,"t":"他铺张云彩当遮盖，夜间使火光照。","notes":[]},{"n":40,"t":"他们一求，他就使鹌鹑飞来，并用天上的粮食叫他们饱足。","notes":[]},{"n":41,"t":"他打开磐石，水就涌出；在干旱之处，水流成河。","notes":[]},{"n":42,"t":"这都因他记念他的圣言和他的仆人亚伯拉罕。","notes":[]},{"n":43,"t":"他带领百姓欢乐而出，带领选民欢呼前往。","notes":[]},{"n":44,"t":"他将列国的地赐给他们，他们便承受众民劳碌得来的，","notes":[]},{"n":45,"t":"好使他们遵他的律例，守他的律法。你们要赞美耶和华！","notes":[]}]},"106":{"heading":"神对他子民的良善","verses":[{"n":1,"t":"你们要赞美耶和华！要称谢耶和华，因他本为善；他的慈爱永远长存！","notes":[]},{"n":2,"t":"谁能传说耶和华的大能？谁能表明他一切的美德？","notes":[]},{"n":3,"t":"凡遵守公平、常行公义的，这人便为有福！","notes":[]},{"n":4,"t":"耶和华啊，你用恩惠待你的百姓；求你也用这恩惠记念我，开你的救恩眷顾我，","notes":[]},{"n":5,"t":"使我见你选民的福，乐你国民的乐，与你的产业一同夸耀。","notes":[]},{"n":6,"t":"我们与我们的祖宗一同犯罪；我们作了孽，行了恶。","notes":[]},{"n":7,"t":"我们的祖宗在埃及不明白你的奇事，不记念你丰盛的慈爱，反倒在红海行了悖逆。","notes":[]},{"n":8,"t":"然而，他因自己的名拯救他们，为要彰显他的大能，","notes":[]},{"n":9,"t":"并且斥责红海，海便干了；他带领他们经过深处，如同经过旷野。","notes":[]},{"n":10,"t":"他拯救他们脱离恨他们人的手，从仇敌手中救赎他们。","notes":[]},{"n":11,"t":"水淹没他们的敌人，没有一个存留。","notes":[]},{"n":12,"t":"那时，他们才信了他的话，歌唱赞美他。","notes":[]},{"n":13,"t":"等不多时，他们就忘了他的作为，不仰望他的指教，","notes":[]},{"n":14,"t":"反倒在旷野大起欲心，在荒地试探神。","notes":[]},{"n":15,"t":"他将他们所求的赐给他们，却使他们的心灵软弱。","notes":[]},{"n":16,"t":"他们又在营中嫉妒摩西和耶和华的圣者亚伦。","notes":[]},{"n":17,"t":"地裂开，吞下大坍，掩盖亚比兰一党的人。","notes":[]},{"n":18,"t":"有火在他们的党中发起；有火焰烧毁了恶人。","notes":[]},{"n":19,"t":"他们在何烈山造了牛犊，叩拜铸成的像。","notes":[]},{"n":20,"t":"如此将他们荣耀的主换为吃草之牛的像，","notes":[]},{"n":21,"t":"忘了神—他们的救主；他曾在埃及行大事，","notes":[]},{"n":22,"t":"在含地行奇事，在红海行可畏的事。","notes":[]},{"n":23,"t":"所以，他说要灭绝他们；若非有他所拣选的摩西站在当中，使他的忿怒转消，恐怕他就灭绝他们。","notes":["原文是破口"]},{"n":24,"t":"他们又藐视那美地，不信他的话，","notes":[]},{"n":25,"t":"在自己帐棚内发怨言，不听耶和华的声音。","notes":[]},{"n":26,"t":"所以，他对他们起誓：必叫他们倒在旷野，","notes":[]},{"n":27,"t":"叫他们的后裔倒在列国之中，分散在各地。","notes":[]},{"n":28,"t":"他们又与巴力·毗珥连合，且吃了祭死神的物。","notes":["或译：人"]},{"n":29,"t":"他们这样行，惹耶和华发怒，便有瘟疫流行在他们中间。","notes":[]},{"n":30,"t":"那时，非尼哈站起，刑罚恶人，瘟疫这才止息。","notes":[]},{"n":31,"t":"那就算为他的义，世世代代，直到永远。","notes":[]},{"n":32,"t":"他们在米利巴水又叫耶和华发怒，甚至摩西也受了亏损，","notes":[]},{"n":33,"t":"是因他们惹动他的灵，摩西用嘴说了急躁的话。","notes":["原文是他"]},{"n":34,"t":"他们不照耶和华所吩咐的灭绝外邦人，","notes":[]},{"n":35,"t":"反与他们混杂相合，学习他们的行为，","notes":[]},{"n":36,"t":"事奉他们的偶像，这就成了自己的网罗，","notes":[]},{"n":37,"t":"把自己的儿女祭祀鬼魔，","notes":[]},{"n":38,"t":"流无辜人的血，就是自己儿女的血，把他们祭祀迦南的偶像，那地就被血污秽了。","notes":[]},{"n":39,"t":"这样，他们被自己所做的污秽了，在行为上犯了邪淫。","notes":[]},{"n":40,"t":"所以，耶和华的怒气向他的百姓发作，憎恶他的产业，","notes":[]},{"n":41,"t":"将他们交在外邦人的手里；恨他们的人就辖制他们。","notes":[]},{"n":42,"t":"他们的仇敌也欺压他们，他们就伏在敌人手下。","notes":[]},{"n":43,"t":"他屡次搭救他们，他们却设谋背逆，因自己的罪孽降为卑下。","notes":[]},{"n":44,"t":"然而，他听见他们哀告的时候，就眷顾他们的急难，","notes":[]},{"n":45,"t":"为他们记念他的约，照他丰盛的慈爱后悔。","notes":[]},{"n":46,"t":"他也使他们在凡掳掠他们的人面前蒙怜恤。","notes":[]},{"n":47,"t":"耶和华—我们的神啊，求你拯救我们，从外邦中招聚我们，我们好称赞你的圣名，以赞美你为夸胜。","notes":[]},{"n":48,"t":"耶和华—以色列的神是应当称颂的，从亘古直到永远。愿众民都说：阿们！你们要赞美耶和华！","notes":[]}]},"107":{"heading":"颂赞神的良善","verses":[{"n":1,"t":"你们要称谢耶和华，因他本为善；他的慈爱永远长存！","notes":[]},{"n":2,"t":"愿耶和华的赎民说这话，就是他从敌人手中所救赎的，","notes":[]},{"n":3,"t":"从各地，从东从西，从南从北，所招聚来的。","notes":[]},{"n":4,"t":"他们在旷野荒地漂流，寻不见可住的城邑，","notes":[]},{"n":5,"t":"又饥又渴，心里发昏。","notes":[]},{"n":6,"t":"于是，他们在苦难中哀求耶和华；他从他们的祸患中搭救他们，","notes":[]},{"n":7,"t":"又领他们行走直路，使他们往可居住的城邑。","notes":[]},{"n":8,"t":"但愿人因耶和华的慈爱和他向人所行的奇事都称赞他；","notes":[]},{"n":9,"t":"因他使心里渴慕的人得以知足，使心里饥饿的人得饱美物。","notes":[]},{"n":10,"t":"那些坐在黑暗中、死荫里的人被困苦和铁链捆锁，","notes":[]},{"n":11,"t":"是因他们违背神的话语，藐视至高者的旨意。","notes":[]},{"n":12,"t":"所以，他用劳苦治服他们的心；他们仆倒，无人扶助。","notes":[]},{"n":13,"t":"于是，他们在苦难中哀求耶和华；他从他们的祸患中拯救他们。","notes":[]},{"n":14,"t":"他从黑暗中和死荫里领他们出来，折断他们的绑索。","notes":[]},{"n":15,"t":"但愿人因耶和华的慈爱和他向人所行的奇事都称赞他；","notes":[]},{"n":16,"t":"因为他打破了铜门，砍断了铁闩。","notes":[]},{"n":17,"t":"愚妄人因自己的过犯和自己的罪孽便受苦楚。","notes":[]},{"n":18,"t":"他们心里厌恶各样的食物，就临近死门。","notes":[]},{"n":19,"t":"于是，他们在苦难中哀求耶和华；他从他们的祸患中拯救他们。","notes":[]},{"n":20,"t":"他发命医治他们，救他们脱离死亡。","notes":[]},{"n":21,"t":"但愿人因耶和华的慈爱和他向人所行的奇事都称赞他。","notes":[]},{"n":22,"t":"愿他们以感谢为祭献给他，欢呼述说他的作为！","notes":[]},{"n":23,"t":"在海上坐船，在大水中经理事务的，","notes":[]},{"n":24,"t":"他们看见耶和华的作为，并他在深水中的奇事。","notes":[]},{"n":25,"t":"因他一吩咐，狂风就起来，海中的波浪也扬起。","notes":[]},{"n":26,"t":"他们上到天空，下到海底；他们的心因患难便消化。","notes":[]},{"n":27,"t":"他们摇摇晃晃，东倒西歪，好像醉酒的人；他们的智慧无法可施。","notes":[]},{"n":28,"t":"于是，他们在苦难中哀求耶和华，他从他们的祸患中领出他们来。","notes":[]},{"n":29,"t":"他使狂风止息，波浪就平静。","notes":[]},{"n":30,"t":"风息浪静，他们便欢喜；他就引他们到所愿去的海口。","notes":[]},{"n":31,"t":"但愿人因耶和华的慈爱和他向人所行的奇事都称赞他。","notes":[]},{"n":32,"t":"愿他们在民的会中尊崇他，在长老的位上赞美他！","notes":[]},{"n":33,"t":"他使江河变为旷野，叫水泉变为干渴之地，","notes":[]},{"n":34,"t":"使肥地变为硷地；这都因其间居民的罪恶。","notes":[]},{"n":35,"t":"他使旷野变为水潭，叫旱地变为水泉。","notes":[]},{"n":36,"t":"他使饥饿的人住在那里，好建造可住的城邑，","notes":[]},{"n":37,"t":"又种田地，栽葡萄园，得享所出的土产。","notes":[]},{"n":38,"t":"他又赐福给他们，叫他们生养众多，也不叫他们的牲畜减少。","notes":[]},{"n":39,"t":"他们又因暴虐、患难、愁苦，就减少且卑下。","notes":[]},{"n":40,"t":"他使君王蒙羞被辱，使他们在荒废无路之地漂流。","notes":[]},{"n":41,"t":"他却将穷乏人安置在高处，脱离苦难，使他的家属多如羊群。","notes":[]},{"n":42,"t":"正直人看见就欢喜；罪孽之辈必塞口无言。","notes":[]},{"n":43,"t":"凡有智慧的，必在这些事上留心，也必思想耶和华的慈爱。","notes":[]}]},"108":{"heading":"抗敌求助","verses":[{"n":1,"t":"神啊，我心坚定；我口要唱诗歌颂！","notes":["原文是荣耀"]},{"n":2,"t":"琴瑟啊，你们当醒起！我自己要极早醒起！","notes":[]},{"n":3,"t":"耶和华啊，我要在万民中称谢你，在列邦中歌颂你！","notes":[]},{"n":4,"t":"因为，你的慈爱大过诸天；你的诚实达到穹苍。","notes":[]},{"n":5,"t":"神啊，愿你崇高过于诸天！愿你的荣耀高过全地！","notes":[]},{"n":6,"t":"求你应允我们，用右手拯救我们，好叫你所亲爱的人得救。","notes":[]},{"n":7,"t":"神已经指着他的圣洁说：我要欢乐；我要分开示剑，丈量疏割谷。","notes":["说：或译应许我"]},{"n":8,"t":"基列是我的；玛拿西是我的；以法莲是护卫我头的；犹大是我的杖；","notes":[]},{"n":9,"t":"摩押是我的沐浴盆；我要向以东抛鞋；我必因胜非利士呼喊。","notes":[]},{"n":10,"t":"谁能领我进坚固城？谁能引我到以东地？","notes":[]},{"n":11,"t":"神啊，你不是丢弃了我们吗？神啊，你不和我们的军兵同去吗？","notes":[]},{"n":12,"t":"求你帮助我们攻击敌人，因为人的帮助是枉然的。","notes":[]},{"n":13,"t":"我们倚靠神才得施展大能，因为践踏我们敌人的就是他。","notes":[]}]},"109":{"heading":"遭难者的苦诉","verses":[{"n":1,"t":"我所赞美的神啊，求你不要闭口不言。","notes":[]},{"n":2,"t":"因为恶人的嘴和诡诈人的口已经张开攻击我；他们用撒谎的舌头对我说话。","notes":[]},{"n":3,"t":"他们围绕我，说怨恨的话，又无故地攻打我。","notes":[]},{"n":4,"t":"他们与我为敌以报我爱，但我专心祈祷。","notes":[]},{"n":5,"t":"他们向我以恶报善，以恨报爱。","notes":[]},{"n":6,"t":"愿你派一个恶人辖制他，派一个对头站在他右边！","notes":[]},{"n":7,"t":"他受审判的时候，愿他出来担当罪名！愿他的祈祷反成为罪！","notes":[]},{"n":8,"t":"愿他的年日短少！愿别人得他的职分！","notes":[]},{"n":9,"t":"愿他的儿女为孤儿，他的妻子为寡妇！","notes":[]},{"n":10,"t":"愿他的儿女漂流讨饭，从他们荒凉之处出来求食！","notes":[]},{"n":11,"t":"愿强暴的债主牢笼他一切所有的！愿外人抢他劳碌得来的！","notes":[]},{"n":12,"t":"愿无人向他延绵施恩！愿无人可怜他的孤儿！","notes":[]},{"n":13,"t":"愿他的后人断绝，名字被涂抹，不传于下代！","notes":[]},{"n":14,"t":"愿他祖宗的罪孽被耶和华记念！愿他母亲的罪过不被涂抹！","notes":[]},{"n":15,"t":"愿这些罪常在耶和华面前，使他的名号断绝于世！","notes":[]},{"n":16,"t":"因为他不想施恩，却逼迫困苦穷乏的和伤心的人，要把他们治死。","notes":[]},{"n":17,"t":"他爱咒骂，咒骂就临到他；他不喜爱福乐，福乐就与他远离！","notes":[]},{"n":18,"t":"他拿咒骂当衣服穿上；这咒骂就如水进他里面，像油入他的骨头。","notes":[]},{"n":19,"t":"愿这咒骂当他遮身的衣服，当他常束的腰带！","notes":[]},{"n":20,"t":"这就是我对头和用恶言议论我的人从耶和华那里所受的报应。","notes":[]},{"n":21,"t":"主—耶和华啊，求你为你的名恩待我；因你的慈爱美好，求你搭救我！","notes":[]},{"n":22,"t":"因为我困苦穷乏，内心受伤。","notes":[]},{"n":23,"t":"我如日影渐渐偏斜而去；我如蝗虫被抖出来。","notes":[]},{"n":24,"t":"我因禁食，膝骨软弱；我身上的肉也渐渐瘦了。","notes":[]},{"n":25,"t":"我受他们的羞辱，他们看见我便摇头。","notes":[]},{"n":26,"t":"耶和华—我的神啊，求你帮助我，照你的慈爱拯救我，","notes":[]},{"n":27,"t":"使他们知道这是你的手，是你—耶和华所行的事。","notes":[]},{"n":28,"t":"任凭他们咒骂，惟愿你赐福；他们几时起来就必蒙羞，你的仆人却要欢喜。","notes":[]},{"n":29,"t":"愿我的对头披戴羞辱！愿他们以自己的羞愧为外袍遮身！","notes":[]},{"n":30,"t":"我要用口极力称谢耶和华；我要在众人中间赞美他；","notes":[]},{"n":31,"t":"因为他必站在穷乏人的右边，要救他脱离审判他灵魂的人。","notes":[]}]},"110":{"heading":"耶和华及其所选之王","verses":[{"n":1,"t":"耶和华对我主说：你坐在我的右边，等我使你仇敌作你的脚凳。","notes":[]},{"n":2,"t":"耶和华必使你从锡安伸出能力的杖来；你要在你仇敌中掌权。","notes":[]},{"n":3,"t":"当你掌权的日子，你的民要以圣洁的妆饰为衣，甘心牺牲自己；你的民多如清晨的甘露。","notes":["或译：行军的日子","或译：以圣洁为妆饰","或译：你少年时光耀如清晨的甘露"]},{"n":4,"t":"耶和华起了誓，决不后悔，说：你是照着麦基洗德的等次永远为祭司。","notes":[]},{"n":5,"t":"在你右边的主，当他发怒的日子，必打伤列王。","notes":[]},{"n":6,"t":"他要在列邦中刑罚恶人，尸首就遍满各处；他要在许多国中打破仇敌的头。","notes":[]},{"n":7,"t":"他要喝路旁的河水，因此必抬起头来。","notes":[]}]},"111":{"heading":"赞美耶和华","verses":[{"n":1,"t":"你们要赞美耶和华！我要在正直人的大会中，并公会中，一心称谢耶和华。","notes":[]},{"n":2,"t":"耶和华的作为本为大；凡喜爱的都必考察。","notes":[]},{"n":3,"t":"他所行的是尊荣和威严；他的公义存到永远。","notes":[]},{"n":4,"t":"他行了奇事，使人记念；耶和华有恩惠，有怜悯。","notes":[]},{"n":5,"t":"他赐粮食给敬畏他的人；他必永远记念他的约。","notes":[]},{"n":6,"t":"他向百姓显出大能的作为，把外邦的地赐给他们为业。","notes":[]},{"n":7,"t":"他手所行的是诚实公平；他的训词都是确实的，","notes":[]},{"n":8,"t":"是永永远远坚定的，是按诚实正直设立的。","notes":[]},{"n":9,"t":"他向百姓施行救赎，命定他的约，直到永远；他的名圣而可畏。","notes":[]},{"n":10,"t":"敬畏耶和华是智慧的开端；凡遵行他命令的是聪明人。耶和华是永远当赞美的！","notes":[]}]},"112":{"heading":"义人之福","verses":[{"n":1,"t":"你们要赞美耶和华！敬畏耶和华，甚喜爱他命令的，这人便为有福！","notes":[]},{"n":2,"t":"他的后裔在世必强盛；正直人的后代必要蒙福。","notes":[]},{"n":3,"t":"他家中有货物，有钱财；他的公义存到永远。","notes":[]},{"n":4,"t":"正直人在黑暗中，有光向他发现；他有恩惠，有怜悯，有公义。","notes":[]},{"n":5,"t":"施恩与人、借贷与人的，这人事情顺利；他被审判的时候要诉明自己的冤。","notes":[]},{"n":6,"t":"他永不动摇；义人被记念，直到永远。","notes":[]},{"n":7,"t":"他必不怕凶恶的信息；他心坚定，倚靠耶和华。","notes":[]},{"n":8,"t":"他心确定，总不惧怕，直到他看见敌人遭报。","notes":[]},{"n":9,"t":"他施舍钱财，周济贫穷；他的仁义存到永远。他的角必被高举，大有荣耀。","notes":[]},{"n":10,"t":"恶人看见便恼恨，必咬牙而消化；恶人的心愿要归灭绝。","notes":[]}]},"113":{"heading":"赞美耶和华的良善","verses":[{"n":1,"t":"你们要赞美耶和华！耶和华的仆人哪，你们要赞美，赞美耶和华的名！","notes":[]},{"n":2,"t":"耶和华的名是应当称颂的，从今时直到永远！","notes":[]},{"n":3,"t":"从日出之地到日落之处，耶和华的名是应当赞美的！","notes":[]},{"n":4,"t":"耶和华超乎万民之上；他的荣耀高过诸天。","notes":[]},{"n":5,"t":"谁像耶和华—我们的神呢？他坐在至高之处，","notes":[]},{"n":6,"t":"自己谦卑，观看天上地下的事。","notes":[]},{"n":7,"t":"他从灰尘里抬举贫寒人，从粪堆中提拔穷乏人，","notes":[]},{"n":8,"t":"使他们与王子同坐，就是与本国的王子同坐。","notes":[]},{"n":9,"t":"他使不能生育的妇人安居家中，为多子的乐母。你们要赞美耶和华！","notes":[]}]},"114":{"heading":"逾越节之歌","verses":[{"n":1,"t":"以色列出了埃及，雅各家离开说异言之民；","notes":[]},{"n":2,"t":"那时，犹大为主的圣所，以色列为他所治理的国度。","notes":[]},{"n":3,"t":"沧海看见就奔逃；约旦河也倒流。","notes":[]},{"n":4,"t":"大山踊跃，如公羊；小山跳舞，如羊羔。","notes":[]},{"n":5,"t":"沧海啊，你为何奔逃？约旦哪，你为何倒流？","notes":[]},{"n":6,"t":"大山哪，你为何踊跃，如公羊？小山哪，你为何跳舞，如羊羔？","notes":[]},{"n":7,"t":"大地啊，你因见主的面，就是雅各神的面，便要震动。","notes":[]},{"n":8,"t":"他叫磐石变为水池，叫坚石变为泉源。","notes":[]}]},"115":{"heading":"独一真神","verses":[{"n":1,"t":"耶和华啊，荣耀不要归与我们，不要归与我们；要因你的慈爱和诚实归在你的名下！","notes":[]},{"n":2,"t":"为何容外邦人说：他们的神在哪里呢？","notes":[]},{"n":3,"t":"然而，我们的神在天上，都随自己的意旨行事。","notes":[]},{"n":4,"t":"他们的偶像是金的，银的，是人手所造的，","notes":[]},{"n":5,"t":"有口却不能言，有眼却不能看，","notes":[]},{"n":6,"t":"有耳却不能听，有鼻却不能闻，","notes":[]},{"n":7,"t":"有手却不能摸，有脚却不能走，有喉咙也不能出声。","notes":[]},{"n":8,"t":"造他的要和他一样；凡靠他的也要如此。","notes":[]},{"n":9,"t":"以色列啊，你要倚靠耶和华！他是你的帮助和你的盾牌。","notes":[]},{"n":10,"t":"亚伦家啊，你们要倚靠耶和华！他是你们的帮助和你们的盾牌。","notes":[]},{"n":11,"t":"你们敬畏耶和华的，要倚靠耶和华！他是你们的帮助和你们的盾牌。","notes":[]},{"n":12,"t":"耶和华向来眷念我们；他还要赐福给我们：要赐福给以色列的家，赐福给亚伦的家。","notes":[]},{"n":13,"t":"凡敬畏耶和华的，无论大小，主必赐福给他。","notes":[]},{"n":14,"t":"愿耶和华叫你们和你们的子孙日见加增。","notes":[]},{"n":15,"t":"你们蒙了造天地之耶和华的福！","notes":[]},{"n":16,"t":"天，是耶和华的天；地，他却给了世人。","notes":[]},{"n":17,"t":"死人不能赞美耶和华；下到寂静中的也都不能。","notes":[]},{"n":18,"t":"但我们要称颂耶和华，从今时直到永远。你们要赞美耶和华！","notes":[]}]},"116":{"heading":"为出死入生而赞美神","verses":[{"n":1,"t":"我爱耶和华，因为他听了我的声音和我的恳求。","notes":[]},{"n":2,"t":"他既向我侧耳，我一生要求告他。","notes":[]},{"n":3,"t":"死亡的绳索缠绕我；阴间的痛苦抓住我；我遭遇患难愁苦。","notes":[]},{"n":4,"t":"那时，我便求告耶和华的名，说：耶和华啊，求你救我的灵魂！","notes":[]},{"n":5,"t":"耶和华有恩惠，有公义；我们的神以怜悯为怀。","notes":[]},{"n":6,"t":"耶和华保护愚人；我落到卑微的地步，他救了我。","notes":[]},{"n":7,"t":"我的心哪！你要仍归安乐，因为耶和华用厚恩待你。","notes":[]},{"n":8,"t":"主啊，你救我的命免了死亡，救我的眼免了流泪，救我的脚免了跌倒。","notes":[]},{"n":9,"t":"我要在耶和华面前行活人之路。","notes":[]},{"n":10,"t":"我因信，所以如此说话；我受了极大的困苦。","notes":[]},{"n":11,"t":"我曾急促地说：人都是说谎的！","notes":[]},{"n":12,"t":"我拿什么报答耶和华向我所赐的一切厚恩？","notes":[]},{"n":13,"t":"我要举起救恩的杯，称扬耶和华的名。","notes":[]},{"n":14,"t":"我要在他众民面前向耶和华还我的愿。","notes":[]},{"n":15,"t":"在耶和华眼中，看圣民之死极为宝贵。","notes":[]},{"n":16,"t":"耶和华啊，我真是你的仆人；我是你的仆人，是你婢女的儿子。你已经解开我的绑索。","notes":[]},{"n":17,"t":"我要以感谢为祭献给你，又要求告耶和华的名。","notes":[]},{"n":18,"t":"我要在他众民面前，在耶和华殿的院内，在耶路撒冷当中，向耶和华还我的愿。你们要赞美耶和华！","notes":[],"end":19}]},"117":{"heading":"赞美耶和华","verses":[{"n":1,"t":"万国啊，你们都当赞美耶和华！万民哪，你们都当颂赞他！","notes":[]},{"n":2,"t":"因为他向我们大施慈爱；耶和华的诚实存到永远。你们要赞美耶和华！","notes":[]}]},"118":{"heading":"因胜利而称谢耶和华","verses":[{"n":1,"t":"你们要称谢耶和华，因他本为善；他的慈爱永远长存！","notes":[]},{"n":2,"t":"愿以色列说：他的慈爱永远长存！","notes":[]},{"n":3,"t":"愿亚伦的家说：他的慈爱永远长存！","notes":[]},{"n":4,"t":"愿敬畏耶和华的说：他的慈爱永远长存！","notes":[]},{"n":5,"t":"我在急难中求告耶和华，他就应允我，把我安置在宽阔之地。","notes":[]},{"n":6,"t":"有耶和华帮助我，我必不惧怕，人能把我怎么样呢？","notes":[]},{"n":7,"t":"在那帮助我的人中，有耶和华帮助我，所以我要看见那恨我的人遭报。","notes":[]},{"n":8,"t":"投靠耶和华，强似倚赖人；","notes":[]},{"n":9,"t":"投靠耶和华，强似倚赖王子。","notes":[]},{"n":10,"t":"万民围绕我，我靠耶和华的名必剿灭他们。","notes":[]},{"n":11,"t":"他们环绕我，围困我，我靠耶和华的名必剿灭他们。","notes":[]},{"n":12,"t":"他们如同蜂子围绕我，好像烧荆棘的火，必被熄灭；我靠耶和华的名，必剿灭他们。","notes":[]},{"n":13,"t":"你推我，要叫我跌倒，但耶和华帮助了我。","notes":[]},{"n":14,"t":"耶和华是我的力量，是我的诗歌；他也成了我的拯救。","notes":[]},{"n":15,"t":"在义人的帐棚里，有欢呼拯救的声音；耶和华的右手施展大能。","notes":[]},{"n":16,"t":"耶和华的右手高举；耶和华的右手施展大能。","notes":[]},{"n":17,"t":"我必不致死，仍要存活，并要传扬耶和华的作为。","notes":[]},{"n":18,"t":"耶和华虽严严地惩治我，却未曾将我交于死亡。","notes":[]},{"n":19,"t":"给我敞开义门；我要进去称谢耶和华！","notes":[]},{"n":20,"t":"这是耶和华的门；义人要进去！","notes":[]},{"n":21,"t":"我要称谢你，因为你已经应允我，又成了我的拯救！","notes":[]},{"n":22,"t":"匠人所弃的石头已成了房角的头块石头。","notes":[]},{"n":23,"t":"这是耶和华所做的，在我们眼中看为希奇。","notes":[]},{"n":24,"t":"这是耶和华所定的日子，我们在其中要高兴欢喜！","notes":[]},{"n":25,"t":"耶和华啊，求你拯救！耶和华啊，求你使我们亨通！","notes":[]},{"n":26,"t":"奉耶和华名来的是应当称颂的！我们从耶和华的殿中为你们祝福！","notes":[]},{"n":27,"t":"耶和华是神；他光照了我们。理当用绳索把祭牲拴住，牵到坛角那里。","notes":[]},{"n":28,"t":"你是我的神，我要称谢你！你是我的神，我要尊崇你！","notes":[]},{"n":29,"t":"你们要称谢耶和华，因他本为善；他的慈爱永远长存！","notes":[]}]},"119":{"heading":"耶和华的律法","verses":[{"n":1,"t":"行为完全、遵行耶和华律法的，这人便为有福！","notes":[]},{"n":2,"t":"遵守他的法度、一心寻求他的，这人便为有福！","notes":[]},{"n":3,"t":"这人不做非义的事，但遵行他的道。","notes":[]},{"n":4,"t":"耶和华啊，你曾将你的训词吩咐我们，为要我们殷勤遵守。","notes":[]},{"n":5,"t":"但愿我行事坚定，得以遵守你的律例。","notes":[]},{"n":6,"t":"我看重你的一切命令，就不至于羞愧。","notes":[]},{"n":7,"t":"我学了你公义的判语，就要以正直的心称谢你。","notes":[]},{"n":8,"t":"我必守你的律例；求你总不要丢弃我！","notes":[]},{"n":9,"t":"少年人用什么洁净他的行为呢？是要遵行你的话！","notes":[],"heads":["顺从耶和华的律法"]},{"n":10,"t":"我一心寻求了你；求你不要叫我偏离你的命令。","notes":[]},{"n":11,"t":"我将你的话藏在心里，免得我得罪你。","notes":[]},{"n":12,"t":"耶和华啊，你是应当称颂的！求你将你的律例教训我！","notes":[]},{"n":13,"t":"我用嘴唇传扬你口中的一切典章。","notes":[]},{"n":14,"t":"我喜悦你的法度，如同喜悦一切的财物。","notes":[]},{"n":15,"t":"我要默想你的训词，看重你的道路。","notes":[]},{"n":16,"t":"我要在你的律例中自乐；我不忘记你的话。","notes":[]},{"n":17,"t":"求你用厚恩待你的仆人，使我存活，我就遵守你的话。","notes":[],"heads":["因耶和华律法而蒙福"]},{"n":18,"t":"求你开我的眼睛，使我看出你律法中的奇妙。","notes":[]},{"n":19,"t":"我是在地上作寄居的；求你不要向我隐瞒你的命令！","notes":[]},{"n":20,"t":"我时常切慕你的典章，甚至心碎。","notes":[]},{"n":21,"t":"受咒诅、偏离你命令的骄傲人，你已经责备他们。","notes":[]},{"n":22,"t":"求你除掉我所受的羞辱和藐视，因我遵守你的法度。","notes":[]},{"n":23,"t":"虽有首领坐着妄论我，你仆人却思想你的律例。","notes":[]},{"n":24,"t":"你的法度是我所喜乐的，是我的谋士。","notes":[]},{"n":25,"t":"我的性命几乎归于尘土；求你照你的话将我救活！","notes":[],"heads":["决定遵行耶和华的律法"]},{"n":26,"t":"我述说我所行的，你应允了我；求你将你的律例教训我！","notes":[]},{"n":27,"t":"求你使我明白你的训词，我就思想你的奇事。","notes":[]},{"n":28,"t":"我的心因愁苦而消化；求你照你的话使我坚立！","notes":[]},{"n":29,"t":"求你使我离开奸诈的道，开恩将你的律法赐给我！","notes":[]},{"n":30,"t":"我拣选了忠信的道，将你的典章摆在我面前。","notes":[]},{"n":31,"t":"我持守你的法度；耶和华啊，求你不要叫我羞愧！","notes":[]},{"n":32,"t":"你开广我心的时候，我就往你命令的道上直奔。","notes":[]},{"n":33,"t":"耶和华啊，求你将你的律例指教我，我必遵守到底！","notes":[],"heads":["求主赐悟性"]},{"n":34,"t":"求你赐我悟性，我便遵守你的律法，且要一心遵守。","notes":[]},{"n":35,"t":"求你叫我遵行你的命令，因为这是我所喜乐的。","notes":[]},{"n":36,"t":"求你使我的心趋向你的法度，不趋向非义之财。","notes":[]},{"n":37,"t":"求你叫我转眼不看虚假，又叫我在你的道中生活。","notes":[]},{"n":38,"t":"你向敬畏你的人所应许的话，求你向仆人坚定！","notes":[]},{"n":39,"t":"求你使我所怕的羞辱远离我，因你的典章本为美。","notes":[]},{"n":40,"t":"我羡慕你的训词；求你使我在你的公义上生活！","notes":[]},{"n":41,"t":"耶和华啊，愿你照你的话，使你的慈爱，就是你的救恩，临到我身上，","notes":[],"heads":["倚靠耶和华的律法"]},{"n":42,"t":"我就有话回答那羞辱我的，因我倚靠你的话。","notes":[]},{"n":43,"t":"求你叫真理的话总不离开我口，因我仰望你的典章。","notes":[]},{"n":44,"t":"我要常守你的律法，直到永永远远。","notes":[]},{"n":45,"t":"我要自由而行，因我素来考究你的训词。","notes":["或译：我要行在宽阔之地"]},{"n":46,"t":"我也要在君王面前论说你的法度，并不至于羞愧。","notes":[]},{"n":47,"t":"我要在你的命令中自乐；这命令素来是我所爱的。","notes":[]},{"n":48,"t":"我又要遵行你的命令，这命令素来是我所爱的；我也要思想你的律例。","notes":["原文是举手"]},{"n":49,"t":"求你记念向你仆人所应许的话，叫我有盼望。","notes":[],"heads":["因耶和华的律法而安稳"]},{"n":50,"t":"这话将我救活了；我在患难中，因此得安慰。","notes":[]},{"n":51,"t":"骄傲的人甚侮慢我，我却未曾偏离你的律法。","notes":[]},{"n":52,"t":"耶和华啊，我记念你从古以来的典章，就得了安慰。","notes":[]},{"n":53,"t":"我见恶人离弃你的律法，就怒气发作，犹如火烧。","notes":[]},{"n":54,"t":"我在世寄居，素来以你的律例为诗歌。","notes":[]},{"n":55,"t":"耶和华啊，我夜间记念你的名，遵守你的律法。","notes":[]},{"n":56,"t":"我所以如此，是因我守你的训词。","notes":[]},{"n":57,"t":"耶和华是我的福分；我曾说，我要遵守你的言语。","notes":[],"heads":["深爱耶和华的律法"]},{"n":58,"t":"我一心求过你的恩；愿你照你的话怜悯我！","notes":[]},{"n":59,"t":"我思想我所行的道，就转步归向你的法度。","notes":[]},{"n":60,"t":"我急忙遵守你的命令，并不迟延。","notes":[]},{"n":61,"t":"恶人的绳索缠绕我，我却没有忘记你的律法。","notes":[]},{"n":62,"t":"我因你公义的典章，半夜必起来称谢你。","notes":[]},{"n":63,"t":"凡敬畏你、守你训词的人，我都与他作伴。","notes":[]},{"n":64,"t":"耶和华啊，你的慈爱遍满大地；求你将你的律例教训我！","notes":[]},{"n":65,"t":"耶和华啊，你向来是照你的话善待仆人。","notes":[],"heads":["耶和华律法的宝贵"]},{"n":66,"t":"求你将精明和知识赐给我，因我信了你的命令。","notes":[]},{"n":67,"t":"我未受苦以先走迷了路，现在却遵守你的话。","notes":[]},{"n":68,"t":"你本为善，所行的也善；求你将你的律例教训我！","notes":[]},{"n":69,"t":"骄傲人编造谎言攻击我，我却要一心守你的训词。","notes":[]},{"n":70,"t":"他们心蒙脂油，我却喜爱你的律法。","notes":[]},{"n":71,"t":"我受苦是与我有益，为要使我学习你的律例。","notes":[]},{"n":72,"t":"你口中的训言与我有益，胜于千万的金银。","notes":["或译：律法"]},{"n":73,"t":"你的手制造我，建立我；求你赐我悟性，可以学习你的命令！","notes":[],"heads":["耶和华律法的公正"]},{"n":74,"t":"敬畏你的人见我就要欢喜，因我仰望你的话。","notes":[]},{"n":75,"t":"耶和华啊，我知道你的判语是公义的；你使我受苦是以诚实待我。","notes":[]},{"n":76,"t":"求你照着应许仆人的话，以慈爱安慰我。","notes":[]},{"n":77,"t":"愿你的慈悲临到我，使我存活，因你的律法是我所喜爱的。","notes":[]},{"n":78,"t":"愿骄傲人蒙羞，因为他们无理地倾覆我；但我要思想你的训词。","notes":[]},{"n":79,"t":"愿敬畏你的人归向我，他们就知道你的法度。","notes":[]},{"n":80,"t":"愿我的心在你的律例上完全，使我不致蒙羞。","notes":[]},{"n":81,"t":"我心渴想你的救恩，仰望你的应许。","notes":[],"heads":["求主解救"]},{"n":82,"t":"我因盼望你的应许眼睛失明，说：你何时安慰我？","notes":[]},{"n":83,"t":"我好像烟薰的皮袋，却不忘记你的律例。","notes":[]},{"n":84,"t":"你仆人的年日有多少呢？你几时向逼迫我的人施行审判呢？","notes":[]},{"n":85,"t":"不从你律法的骄傲人为我掘了坑。","notes":[]},{"n":86,"t":"你的命令尽都诚实；他们无理地逼迫我，求你帮助我！","notes":[]},{"n":87,"t":"他们几乎把我从世上灭绝，但我没有离弃你的训词。","notes":[]},{"n":88,"t":"求你照你的慈爱将我救活，我就遵守你口中的法度。","notes":[]},{"n":89,"t":"耶和华啊，你的话安定在天，直到永远。","notes":[],"heads":["信赖耶和华的律法"]},{"n":90,"t":"你的诚实存到万代；你坚定了地，地就长存。","notes":[]},{"n":91,"t":"天地照你的安排存到今日；万物都是你的仆役。","notes":[]},{"n":92,"t":"我若不是喜爱你的律法，早就在苦难中灭绝了！","notes":[]},{"n":93,"t":"我永不忘记你的训词，因你用这训词将我救活了。","notes":[]},{"n":94,"t":"我是属你的，求你救我，因我寻求了你的训词。","notes":[]},{"n":95,"t":"恶人等待我，要灭绝我，我却要揣摩你的法度。","notes":[]},{"n":96,"t":"我看万事尽都有限，惟有你的命令极其宽广。","notes":[]},{"n":97,"t":"我何等爱慕你的律法，终日不住地思想。","notes":[],"heads":["喜爱耶和华的律法"]},{"n":98,"t":"你的命令常存在我心里，使我比仇敌有智慧。","notes":[]},{"n":99,"t":"我比我的师傅更通达，因我思想你的法度。","notes":[]},{"n":100,"t":"我比年老的更明白，因我守了你的训词。","notes":[]},{"n":101,"t":"我禁止我脚走一切的邪路，为要遵守你的话。","notes":[]},{"n":102,"t":"我没有偏离你的典章，因为你教训了我。","notes":[]},{"n":103,"t":"你的言语在我上膛何等甘美，在我口中比蜜更甜！","notes":[]},{"n":104,"t":"我借着你的训词得以明白，所以我恨一切的假道。","notes":[]},{"n":105,"t":"你的话是我脚前的灯，是我路上的光。","notes":[],"heads":["耶和华律法的亮光"]},{"n":106,"t":"你公义的典章，我曾起誓遵守，我必按誓而行。","notes":[]},{"n":107,"t":"我甚是受苦；耶和华啊，求你照你的话将我救活！","notes":[]},{"n":108,"t":"耶和华啊，求你悦纳我口中的赞美为供物，又将你的典章教训我！","notes":[]},{"n":109,"t":"我的性命常在危险之中，我却不忘记你的律法。","notes":[]},{"n":110,"t":"恶人为我设下网罗，我却没有偏离你的训词。","notes":[]},{"n":111,"t":"我以你的法度为永远的产业，因这是我心中所喜爱的。","notes":[]},{"n":112,"t":"我的心专向你的律例，永远遵行，一直到底。","notes":[]},{"n":113,"t":"心怀二意的人为我所恨；但你的律法为我所爱。","notes":[],"heads":["因耶和华律法得安全"]},{"n":114,"t":"你是我藏身之处，又是我的盾牌；我甚仰望你的话语。","notes":[]},{"n":115,"t":"作恶的人哪，你们离开我吧！我好遵守我神的命令。","notes":[]},{"n":116,"t":"求你照你的话扶持我，使我存活，也不叫我因失望而害羞。","notes":[]},{"n":117,"t":"求你扶持我，我便得救，时常看重你的律例。","notes":[]},{"n":118,"t":"凡偏离你律例的人，你都轻弃他们，因为他们的诡诈必归虚空。","notes":[]},{"n":119,"t":"凡地上的恶人，你除掉他，好像除掉渣滓；因此我爱你的法度。","notes":[]},{"n":120,"t":"我因惧怕你，肉就发抖；我也怕你的判语。","notes":[]},{"n":121,"t":"我行过公平和公义，求你不要撇下我给欺压我的人！","notes":[],"heads":["遵从耶和华的律法"]},{"n":122,"t":"求你为仆人作保，使我得好处，不容骄傲人欺压我！","notes":[]},{"n":123,"t":"我因盼望你的救恩和你公义的话眼睛失明。","notes":[]},{"n":124,"t":"求你照你的慈爱待仆人，将你的律例教训我。","notes":[]},{"n":125,"t":"我是你的仆人，求你赐我悟性，使我得知你的法度。","notes":[]},{"n":126,"t":"这是耶和华降罚的时候，因人废了你的律法。","notes":[]},{"n":127,"t":"所以，我爱你的命令胜于金子，更胜于精金。","notes":[]},{"n":128,"t":"你一切的训词，在万事上我都以为正直；我却恨恶一切假道。","notes":[]},{"n":129,"t":"你的法度奇妙，所以我一心谨守。","notes":[],"heads":["渴慕遵行耶和华的律法"]},{"n":130,"t":"你的言语一解开就发出亮光，使愚人通达。","notes":[]},{"n":131,"t":"我张口而气喘，因我切慕你的命令。","notes":[]},{"n":132,"t":"求你转向我，怜悯我，好像你素常待那些爱你名的人。","notes":[]},{"n":133,"t":"求你用你的话使我脚步稳当，不许什么罪孽辖制我。","notes":[]},{"n":134,"t":"求你救我脱离人的欺压，我要遵守你的训词。","notes":[]},{"n":135,"t":"求你用脸光照仆人，又将你的律例教训我。","notes":[]},{"n":136,"t":"我的眼泪下流成河，因为他们不守你的律法。","notes":[]},{"n":137,"t":"耶和华啊，你是公义的；你的判语也是正直的！","notes":[],"heads":["耶和华律法的公正"]},{"n":138,"t":"你所命定的法度是凭公义和至诚。","notes":[]},{"n":139,"t":"我心焦急，如同火烧，因我敌人忘记你的言语。","notes":[]},{"n":140,"t":"你的话极其精炼，所以你的仆人喜爱。","notes":[]},{"n":141,"t":"我微小，被人藐视，却不忘记你的训词。","notes":[]},{"n":142,"t":"你的公义永远长存；你的律法尽都真实。","notes":[]},{"n":143,"t":"我遭遇患难愁苦，你的命令却是我所喜爱的。","notes":[]},{"n":144,"t":"你的法度永远是公义的；求你赐我悟性，我就活了。","notes":[]},{"n":145,"t":"耶和华啊，我一心呼吁你；求你应允我，我必谨守你的律例！","notes":[],"heads":["求主解救"]},{"n":146,"t":"我向你呼吁，求你救我！我要遵守你的法度。","notes":[]},{"n":147,"t":"我趁天未亮呼求；我仰望了你的言语。","notes":[]},{"n":148,"t":"我趁夜更未换将眼睁开，为要思想你的话语。","notes":[]},{"n":149,"t":"求你照你的慈爱听我的声音；耶和华啊，求你照你的典章将我救活！","notes":[]},{"n":150,"t":"追求奸恶的人临近了；他们远离你的律法。","notes":[]},{"n":151,"t":"耶和华啊，你与我相近；你一切的命令尽都真实！","notes":[]},{"n":152,"t":"我因学你的法度，久已知道是你永远立定的。","notes":[]},{"n":153,"t":"求你看顾我的苦难，搭救我，因我不忘记你的律法。","notes":[],"heads":["请求恩助"]},{"n":154,"t":"求你为我辨屈，救赎我，照你的话将我救活。","notes":[]},{"n":155,"t":"救恩远离恶人，因为他们不寻求你的律例。","notes":[]},{"n":156,"t":"耶和华啊，你的慈悲本为大；求你照你的典章将我救活。","notes":[]},{"n":157,"t":"逼迫我的，抵挡我的，很多，我却没有偏离你的法度。","notes":[]},{"n":158,"t":"我看见奸恶的人就甚憎恶，因为他们不遵守你的话。","notes":[]},{"n":159,"t":"你看我怎样爱你的训词！耶和华啊，求你照你的慈爱将我救活！","notes":[]},{"n":160,"t":"你话的总纲是真实；你一切公义的典章是永远长存。","notes":[]},{"n":161,"t":"首领无故地逼迫我，但我的心畏惧你的言语。","notes":[],"heads":["热爱耶和华的律法"]},{"n":162,"t":"我喜爱你的话，好像人得了许多掳物。","notes":[]},{"n":163,"t":"谎话是我所恨恶所憎嫌的；惟你的律法是我所爱的。","notes":[]},{"n":164,"t":"我因你公义的典章一天七次赞美你。","notes":[]},{"n":165,"t":"爱你律法的人有大平安，什么都不能使他们绊脚。","notes":[]},{"n":166,"t":"耶和华啊，我仰望了你的救恩，遵行了你的命令。","notes":[]},{"n":167,"t":"我心里守了你的法度；这法度我甚喜爱。","notes":[]},{"n":168,"t":"我遵守了你的训词和法度，因我一切所行的都在你面前。","notes":[]},{"n":169,"t":"耶和华啊，愿我的呼吁达到你面前，照你的话赐我悟性。","notes":[],"heads":["求主帮助"]},{"n":170,"t":"愿我的恳求达到你面前，照你的话搭救我。","notes":[]},{"n":171,"t":"愿我的嘴发出赞美的话，因为你将律例教训我。","notes":[]},{"n":172,"t":"愿我的舌头歌唱你的话，因你一切的命令尽都公义。","notes":[]},{"n":173,"t":"愿你用手帮助我，因我拣选了你的训词。","notes":[]},{"n":174,"t":"耶和华啊，我切慕你的救恩！你的律法也是我所喜爱的。","notes":[]},{"n":175,"t":"愿我的性命存活，得以赞美你！愿你的典章帮助我！","notes":[]},{"n":176,"t":"我如亡羊走迷了路，求你寻找仆人，因我不忘记你的命令。","notes":[]}]},"120":{"heading":"求主恩助","verses":[{"n":1,"t":"我在急难中求告耶和华，他就应允我。","notes":[]},{"n":2,"t":"耶和华啊，求你救我脱离说谎的嘴唇和诡诈的舌头！","notes":[]},{"n":3,"t":"诡诈的舌头啊，要给你什么呢？要拿什么加给你呢？","notes":[]},{"n":4,"t":"就是勇士的利箭和罗腾木 的炭火。","notes":["小树名，松类"]},{"n":5,"t":"我寄居在米设，住在基达帐棚之中，有祸了！","notes":[]},{"n":6,"t":"我与那恨恶和睦的人许久同住。","notes":[]},{"n":7,"t":"我愿和睦，但我发言，他们就要争战。","notes":[]}]},"121":{"heading":"耶和华是我们的保护者","verses":[{"n":1,"t":"我要向山举目；我的帮助从何而来？","notes":[]},{"n":2,"t":"我的帮助从造天地的耶和华而来。","notes":[]},{"n":3,"t":"他必不叫你的脚摇动；保护你的必不打盹！","notes":[]},{"n":4,"t":"保护以色列的，也不打盹也不睡觉。","notes":[]},{"n":5,"t":"保护你的是耶和华；耶和华在你右边荫庇你。","notes":[]},{"n":6,"t":"白日，太阳必不伤你；夜间，月亮必不害你。","notes":[]},{"n":7,"t":"耶和华要保护你，免受一切的灾害；他要保护你的性命。","notes":[]},{"n":8,"t":"你出你入，耶和华要保护你，从今时直到永远。","notes":[]}]},"122":{"heading":"耶路撒冷颂","verses":[{"n":1,"t":"人对我说：我们往耶和华的殿去，我就欢喜。","notes":[]},{"n":2,"t":"耶路撒冷啊，我们的脚站在你的门内。","notes":[]},{"n":3,"t":"耶路撒冷被建造，如同连络整齐的一座城。","notes":[]},{"n":4,"t":"众支派，就是耶和华的支派，上那里去，按以色列的常例称赞耶和华的名。","notes":["或译：作以色列的证据"]},{"n":5,"t":"因为在那里设立审判的宝座，就是大卫家的宝座。","notes":[]},{"n":6,"t":"你们要为耶路撒冷求平安！耶路撒冷啊，爱你的人必然兴旺！","notes":[]},{"n":7,"t":"愿你城中平安！愿你宫内兴旺！","notes":[]},{"n":8,"t":"因我弟兄和同伴的缘故，我要说：愿平安在你中间！","notes":[]},{"n":9,"t":"因耶和华—我们神殿的缘故，我要为你求福！","notes":[]}]},"123":{"heading":"求主怜悯","verses":[{"n":1,"t":"坐在天上的主啊，我向你举目。","notes":[]},{"n":2,"t":"看哪，仆人的眼睛怎样望主人的手，使女的眼睛怎样望主母的手，我们的眼睛也照样望耶和华—我们的神，直到他怜悯我们。","notes":[]},{"n":3,"t":"耶和华啊，求你怜悯我们，怜悯我们！因为我们被藐视，已到极处。","notes":[]},{"n":4,"t":"我们被那些安逸人的讥诮和骄傲人的藐视，已到极处。","notes":[]}]},"124":{"heading":"神是他子民的保护者","verses":[{"n":1,"t":"以色列人要说：若不是耶和华帮助我们，","notes":[]},{"n":2,"t":"若不是耶和华帮助我们，当人起来攻击我们、","notes":[]},{"n":3,"t":"向我们发怒的时候，就把我们活活地吞了。","notes":[]},{"n":4,"t":"那时，波涛必漫过我们，河水必淹没我们，","notes":[]},{"n":5,"t":"狂傲的水必淹没我们。","notes":[]},{"n":6,"t":"耶和华是应当称颂的！他没有把我们当野食交给他们吞吃。","notes":["原文是牙齿"]},{"n":7,"t":"我们好像雀鸟，从捕鸟人的网罗里逃脱；网罗破裂，我们逃脱了。","notes":[]},{"n":8,"t":"我们得帮助，是在乎倚靠造天地之耶和华的名。","notes":[]}]},"125":{"heading":"耶和华子民的安全","verses":[{"n":1,"t":"倚靠耶和华的人好像锡安山，永不动摇。","notes":[]},{"n":2,"t":"众山怎样围绕耶路撒冷，耶和华也照样围绕他的百姓，从今时直到永远。","notes":[]},{"n":3,"t":"恶人的杖不常落在义人的分上，免得义人伸手作恶。","notes":[]},{"n":4,"t":"耶和华啊，求你善待那些为善和心里正直的人。","notes":[]},{"n":5,"t":"至于那偏行弯曲道路的人，耶和华必使他和作恶的人一同出去受刑。愿平安归于以色列！","notes":[]}]},"126":{"heading":"被掳归回者的欢乐","verses":[{"n":1,"t":"当耶和华将那些被掳的带回锡安的时候，我们好像做梦的人。","notes":[]},{"n":2,"t":"我们满口喜笑、满舌欢呼的时候，外邦中就有人说：耶和华为他们行了大事！","notes":[]},{"n":3,"t":"耶和华果然为我们行了大事，我们就欢喜。","notes":[]},{"n":4,"t":"耶和华啊，求你使我们被掳的人归回，好像南地的河水复流。","notes":[]},{"n":5,"t":"流泪撒种的，必欢呼收割！","notes":[]},{"n":6,"t":"那带种流泪出去的，必要欢欢乐乐地带禾捆回来！","notes":[]}]},"127":{"heading":"称颂神的良善","verses":[{"n":1,"t":"若不是耶和华建造房屋，建造的人就枉然劳力；若不是耶和华看守城池，看守的人就枉然警醒。","notes":[]},{"n":2,"t":"你们清晨早起，夜晚安歇，吃劳碌得来的饭，本是枉然；惟有耶和华所亲爱的，必叫他安然睡觉。","notes":[]},{"n":3,"t":"儿女是耶和华所赐的产业；所怀的胎是他所给的赏赐。","notes":[]},{"n":4,"t":"少年时所生的儿女好像勇士手中的箭。","notes":[]},{"n":5,"t":"箭袋充满的人便为有福；他们在城门口和仇敌说话的时候，必不至于羞愧。","notes":[]}]},"128":{"heading":"顺从耶和华的赏报","verses":[{"n":1,"t":"凡敬畏耶和华、遵行他道的人便为有福！","notes":[]},{"n":2,"t":"你要吃劳碌得来的；你要享福，事情顺利。","notes":[]},{"n":3,"t":"你妻子在你的内室，好像多结果子的葡萄树；你儿女围绕你的桌子，好像橄榄栽子。","notes":[]},{"n":4,"t":"看哪，敬畏耶和华的人必要这样蒙福！","notes":[]},{"n":5,"t":"愿耶和华从锡安赐福给你！愿你一生一世看见耶路撒冷的好处！","notes":[]},{"n":6,"t":"愿你看见你儿女的儿女！愿平安归于以色列！","notes":[]}]},"129":{"heading":"求耶和华退敌","verses":[{"n":1,"t":"以色列当说：从我幼年以来，敌人屡次苦害我，","notes":[]},{"n":2,"t":"从我幼年以来，敌人屡次苦害我，却没有胜了我。","notes":[]},{"n":3,"t":"如同扶犁的在我背上扶犁而耕，耕的犁沟甚长。","notes":[]},{"n":4,"t":"耶和华是公义的；他砍断了恶人的绳索。","notes":[]},{"n":5,"t":"愿恨恶锡安的都蒙羞退后！","notes":[]},{"n":6,"t":"愿他们像房顶上的草，未长成而枯干，","notes":[]},{"n":7,"t":"收割的不够一把，捆禾的也不满怀。","notes":[]},{"n":8,"t":"过路的也不说：愿耶和华所赐的福归与你们！我们奉耶和华的名给你们祝福！","notes":[]}]},"130":{"heading":"求助的祈祷","verses":[{"n":1,"t":"耶和华啊，我从深处向你求告！","notes":[]},{"n":2,"t":"主啊，求你听我的声音！愿你侧耳听我恳求的声音！","notes":[]},{"n":3,"t":"主—耶和华啊，你若究察罪孽，谁能站得住呢？","notes":[]},{"n":4,"t":"但在你有赦免之恩，要叫人敬畏你。","notes":[]},{"n":5,"t":"我等候耶和华，我的心等候；我也仰望他的话。","notes":[]},{"n":6,"t":"我的心等候主，胜于守夜的，等候天亮，胜于守夜的，等候天亮。","notes":[]},{"n":7,"t":"以色列啊，你当仰望耶和华！因他有慈爱，有丰盛的救恩。","notes":[]},{"n":8,"t":"他必救赎以色列脱离一切的罪孽。","notes":[]}]},"131":{"heading":"谦卑靠主","verses":[{"n":1,"t":"耶和华啊，我的心不狂傲，我的眼不高大；重大和测不透的事，我也不敢行。","notes":[]},{"n":2,"t":"我的心平稳安静，好像断过奶的孩子在他母亲的怀中；我的心在我里面真像断过奶的孩子。","notes":[]},{"n":3,"t":"以色列啊，你当仰望耶和华，从今时直到永远！","notes":[]}]},"132":{"heading":"圣殿颂","verses":[{"n":1,"t":"耶和华啊，求你记念大卫所受的一切苦难！","notes":[]},{"n":2,"t":"他怎样向耶和华起誓，向雅各的大能者许愿，","notes":[]},{"n":3,"t":"说：我必不进我的帐幕，也不上我的床榻；","notes":[]},{"n":4,"t":"我不容我的眼睛睡觉，也不容我的眼目打盹；","notes":[]},{"n":5,"t":"直等我为耶和华寻得所在，为雅各的大能者寻得居所。","notes":[]},{"n":6,"t":"我们听说约柜在以法他，我们在基列·耶琳就寻见了。","notes":[]},{"n":7,"t":"我们要进他的居所，在他脚凳前下拜。","notes":[]},{"n":8,"t":"耶和华啊，求你兴起，和你有能力的约柜同入安息之所！","notes":[]},{"n":9,"t":"愿你的祭司披上公义！愿你的圣民欢呼！","notes":[]},{"n":10,"t":"求你因你仆人大卫的缘故，不要厌弃你的受膏者！","notes":[]},{"n":11,"t":"耶和华向大卫、凭诚实起了誓，必不反复，说：我要使你所生的坐在你的宝座上。","notes":[]},{"n":12,"t":"你的众子若守我的约和我所教训他们的法度，他们的子孙必永远坐在你的宝座上。","notes":[]},{"n":13,"t":"因为耶和华拣选了锡安，愿意当作自己的居所，","notes":[]},{"n":14,"t":"说：这是我永远安息之所；我要住在这里，因为是我所愿意的。","notes":[]},{"n":15,"t":"我要使其中的粮食丰满，使其中的穷人饱足。","notes":[]},{"n":16,"t":"我要使祭司披上救恩，圣民大声欢呼！","notes":[]},{"n":17,"t":"我要叫大卫的角在那里发生；我为我的受膏者预备明灯。","notes":[]},{"n":18,"t":"我要使他的仇敌披上羞耻；但他的冠冕要在头上发光。","notes":[]}]},"133":{"heading":"兄弟相爱颂","verses":[{"n":1,"t":"看哪，弟兄和睦同居是何等地善，何等地美！","notes":[]},{"n":2,"t":"这好比那贵重的油浇在亚伦的头上，流到胡须，又流到他的衣襟；","notes":[]},{"n":3,"t":"又好比黑门的甘露降在锡安山；因为在那里有耶和华所命定的福，就是永远的生命。","notes":[]}]},"134":{"heading":"宣召称颂","verses":[{"n":1,"t":"耶和华的仆人夜间站在耶和华殿中的，你们当称颂耶和华！","notes":[]},{"n":2,"t":"你们当向圣所举手，称颂耶和华！","notes":[]},{"n":3,"t":"愿造天地的耶和华，从锡安赐福给你们！","notes":[]}]},"135":{"heading":"称颂的圣诗","verses":[{"n":1,"t":"你们要赞美耶和华！你们要赞美耶和华的名！耶和华的仆人站在耶和华殿中；站在我们神殿院中的，你们要赞美他！","notes":[],"end":2},{"n":3,"t":"你们要赞美耶和华！耶和华本为善；要歌颂他的名，因为这是美好的。","notes":[]},{"n":4,"t":"耶和华拣选雅各归自己，拣选以色列特作自己的子民。","notes":[]},{"n":5,"t":"原来我知道耶和华为大，也知道我们的主超乎万神之上。","notes":[]},{"n":6,"t":"耶和华在天上，在地下，在海中，在一切的深处，都随自己的意旨而行。","notes":[]},{"n":7,"t":"他使云雾从地极上腾，造电随雨而闪，从府库中带出风来。","notes":[]},{"n":8,"t":"他将埃及头生的，连人带牲畜都击杀了。","notes":[]},{"n":9,"t":"埃及啊，他施行神迹奇事，在你当中，在法老和他一切臣仆身上。","notes":[]},{"n":10,"t":"他击杀许多的民，又杀戮大能的王，","notes":[]},{"n":11,"t":"就是亚摩利王西宏和巴珊王噩，并迦南一切的国王，","notes":[]},{"n":12,"t":"将他们的地赏赐他的百姓以色列为业。","notes":[]},{"n":13,"t":"耶和华啊，你的名存到永远！耶和华啊，你可记念的名存到万代！","notes":[]},{"n":14,"t":"耶和华要为他的百姓伸冤，为他的仆人后悔。","notes":[]},{"n":15,"t":"外邦的偶像是金的，银的，是人手所造的；","notes":[]},{"n":16,"t":"有口却不能言，有眼却不能看，","notes":[]},{"n":17,"t":"有耳却不能听，口中也没有气息。","notes":[]},{"n":18,"t":"造他的要和他一样，凡靠他的也要如此。","notes":[]},{"n":19,"t":"以色列家啊，你们要称颂耶和华！亚伦家啊，你们要称颂耶和华！","notes":[]},{"n":20,"t":"利未家啊，你们要称颂耶和华！你们敬畏耶和华的，要称颂耶和华！","notes":[]},{"n":21,"t":"住在耶路撒冷的耶和华该从锡安受称颂。你们要赞美耶和华！","notes":[]}]},"136":{"heading":"感恩的圣诗","verses":[{"n":1,"t":"你们要称谢耶和华，因他本为善；他的慈爱永远长存。","notes":[]},{"n":2,"t":"你们要称谢万神之神，因他的慈爱永远长存。","notes":[]},{"n":3,"t":"你们要称谢万主之主，因他的慈爱永远长存。","notes":[]},{"n":4,"t":"称谢那独行大奇事的，因他的慈爱永远长存。","notes":[]},{"n":5,"t":"称谢那用智慧造天的，因他的慈爱永远长存。","notes":[]},{"n":6,"t":"称谢那铺地在水以上的，因他的慈爱永远长存。","notes":[]},{"n":7,"t":"称谢那造成大光的，因他的慈爱永远长存。","notes":[]},{"n":8,"t":"他造日头管白昼，因他的慈爱永远长存。","notes":[]},{"n":9,"t":"他造月亮星宿管黑夜，因他的慈爱永远长存。","notes":[]},{"n":10,"t":"称谢那击杀埃及人之长子的，因他的慈爱永远长存。","notes":[]},{"n":11,"t":"他领以色列人从他们中间出来，因他的慈爱永远长存。","notes":[]},{"n":12,"t":"他施展大能的手和伸出来的膀臂，因他的慈爱永远长存。","notes":[]},{"n":13,"t":"称谢那分裂红海的，因他的慈爱永远长存。","notes":[]},{"n":14,"t":"他领以色列从其中经过，因他的慈爱永远长存；","notes":[]},{"n":15,"t":"却把法老和他的军兵推翻在红海里，因他的慈爱永远长存。","notes":[]},{"n":16,"t":"称谢那引导自己的民行走旷野的，因他的慈爱永远长存。","notes":[]},{"n":17,"t":"称谢那击杀大君王的，因他的慈爱永远长存。","notes":[]},{"n":18,"t":"他杀戮有名的君王，因他的慈爱永远长存；","notes":[]},{"n":19,"t":"就是杀戮亚摩利王西宏，因他的慈爱永远长存；","notes":[]},{"n":20,"t":"又杀巴珊王噩，因他的慈爱永远长存。","notes":[]},{"n":21,"t":"他将他们的地赐他的百姓为业，因他的慈爱永远长存；","notes":[]},{"n":22,"t":"就是赐他的仆人以色列为业，因他的慈爱永远长存。","notes":[]},{"n":23,"t":"他顾念我们在卑微的地步，因他的慈爱永远长存。","notes":[]},{"n":24,"t":"他救拔我们脱离敌人，因他的慈爱永远长存。","notes":[]},{"n":25,"t":"他赐粮食给凡有血气的，因他的慈爱永远长存。","notes":[]},{"n":26,"t":"你们要称谢天上的神，因他的慈爱永远长存。","notes":[]}]},"137":{"heading":"以色列人被掳的哀歌","verses":[{"n":1,"t":"我们曾在巴比伦的河边坐下，一追想锡安就哭了。","notes":[]},{"n":2,"t":"我们把琴挂在那里的柳树上；","notes":[]},{"n":3,"t":"因为在那里，掳掠我们的要我们唱歌，抢夺我们的要我们作乐，说：给我们唱一首锡安歌吧！","notes":[]},{"n":4,"t":"我们怎能在外邦唱耶和华的歌呢？","notes":[]},{"n":5,"t":"耶路撒冷啊，我若忘记你，情愿我的右手忘记技巧！","notes":[]},{"n":6,"t":"我若不记念你，若不看耶路撒冷过于我所最喜乐的，情愿我的舌头贴于上膛！","notes":[]},{"n":7,"t":"耶路撒冷遭难的日子，以东人说：拆毁！拆毁！直拆到根基！耶和华啊，求你记念这仇！","notes":[]},{"n":8,"t":"将要被灭的巴比伦城啊，报复你像你待我们的，那人便为有福！","notes":["城：原文是女子"]},{"n":9,"t":"拿你的婴孩摔在磐石上的，那人便为有福！","notes":[]}]},"138":{"heading":"感恩之祷","verses":[{"n":1,"t":"我要一心称谢你，在诸神面前歌颂你。","notes":[]},{"n":2,"t":"我要向你的圣殿下拜，为你的慈爱和诚实称赞你的名；因你使你的话显为大，过于你所应许的。","notes":["或译：超乎你的名声"]},{"n":3,"t":"我呼求的日子，你就应允我，鼓励我，使我心里有能力。","notes":[]},{"n":4,"t":"耶和华啊，地上的君王都要称谢你，因他们听见了你口中的言语。","notes":[]},{"n":5,"t":"他们要歌颂耶和华的作为，因耶和华大有荣耀。","notes":[]},{"n":6,"t":"耶和华虽高，仍看顾低微的人；他却从远处看出骄傲的人。","notes":[]},{"n":7,"t":"我虽行在患难中，你必将我救活；我的仇敌发怒，你必伸手抵挡他们；你的右手也必救我。","notes":[]},{"n":8,"t":"耶和华必成全关乎我的事；耶和华啊，你的慈爱永远长存！求你不要离弃你手所造的。","notes":[]}]},"139":{"heading":"耶和华的全知和眷顾","verses":[{"n":1,"t":"耶和华啊，你已经鉴察我，认识我。","notes":[]},{"n":2,"t":"我坐下，我起来，你都晓得；你从远处知道我的意念。","notes":[]},{"n":3,"t":"我行路，我躺卧，你都细察；你也深知我一切所行的。","notes":[]},{"n":4,"t":"耶和华啊，我舌头上的话，你没有一句不知道的。","notes":[]},{"n":5,"t":"你在我前后环绕我，按手在我身上。","notes":[]},{"n":6,"t":"这样的知识奇妙，是我不能测的，至高，是我不能及的。","notes":[]},{"n":7,"t":"我往哪里去躲避你的灵？我往哪里逃、躲避你的面？","notes":[]},{"n":8,"t":"我若升到天上，你在那里；我若在阴间下榻，你也在那里。","notes":[]},{"n":9,"t":"我若展开清晨的翅膀，飞到海极居住，","notes":[]},{"n":10,"t":"就是在那里，你的手必引导我；你的右手也必扶持我。","notes":[]},{"n":11,"t":"我若说：黑暗必定遮蔽我，我周围的亮光必成为黑夜；","notes":[]},{"n":12,"t":"黑暗也不能遮蔽我，使你不见，黑夜却如白昼发亮。黑暗和光明，在你看都是一样。","notes":[]},{"n":13,"t":"我的肺腑是你所造的；我在母腹中，你已覆庇我。","notes":[]},{"n":14,"t":"我要称谢你，因我受造，奇妙可畏；你的作为奇妙，这是我心深知道的。","notes":[]},{"n":15,"t":"我在暗中受造，在地的深处被联络；那时，我的形体并不向你隐藏。","notes":[]},{"n":16,"t":"我未成形的体质，你的眼早已看见了；你所定的日子，我尚未度一日，你都写在你的册上了。","notes":["或译：我被造的肢体尚未有其一"]},{"n":17,"t":"神啊，你的意念向我何等宝贵！其数何等众多！","notes":[]},{"n":18,"t":"我若数点，比海沙更多；我睡醒的时候，仍和你同在。","notes":[]},{"n":19,"t":"神啊，你必要杀戮恶人；所以，你们好流人血的，离开我去吧！","notes":[]},{"n":20,"t":"因为他们说恶言顶撞你；你的仇敌也妄称你的名。","notes":[]},{"n":21,"t":"耶和华啊，恨恶你的，我岂不恨恶他们吗？攻击你的，我岂不憎嫌他们吗？","notes":[]},{"n":22,"t":"我切切地恨恶他们，以他们为仇敌。","notes":[]},{"n":23,"t":"神啊，求你鉴察我，知道我的心思，试炼我，知道我的意念，","notes":[]},{"n":24,"t":"看在我里面有什么恶行没有，引导我走永生的道路。","notes":[]}]},"140":{"heading":"求耶和华护佑","verses":[{"n":1,"t":"耶和华啊，求你拯救我脱离凶恶的人，保护我脱离强暴的人！","notes":[]},{"n":2,"t":"他们心中图谋奸恶，常常聚集要争战。","notes":[]},{"n":3,"t":"他们使舌头尖利如蛇，嘴里有虺蛇的毒气。 （细拉）","notes":[]},{"n":4,"t":"耶和华啊，求你拯救我脱离恶人的手，保护我脱离强暴的人！他们图谋推我跌倒。","notes":[]},{"n":5,"t":"骄傲人为我暗设网罗和绳索；他们在路旁铺下网，设下圈套。 （细拉）","notes":[]},{"n":6,"t":"我曾对耶和华说：你是我的神。耶和华啊，求你留心听我恳求的声音！","notes":[]},{"n":7,"t":"主—耶和华、我救恩的力量啊，在争战的日子，你遮蔽了我的头。","notes":[]},{"n":8,"t":"耶和华啊，求你不要遂恶人的心愿；不要成就他们的计谋，恐怕他们自高。 （细拉）","notes":[]},{"n":9,"t":"至于那些昂首围困我的人，愿他们嘴唇的奸恶陷害自己！","notes":["原文是遮蔽"]},{"n":10,"t":"愿火炭落在他们身上！愿他们被丢在火中，抛在深坑里，不能再起来。","notes":[]},{"n":11,"t":"说恶言的人在地上必坚立不住；祸患必猎取强暴的人，将他打倒。","notes":[]},{"n":12,"t":"我知道耶和华必为困苦人伸冤，必为穷乏人辨屈。","notes":[]},{"n":13,"t":"义人必要称赞你的名；正直人必住在你面前。","notes":[]}]},"141":{"heading":"晚 祷","verses":[{"n":1,"t":"耶和华啊，我曾求告你，求你快快临到我这里！我求告你的时候，愿你留心听我的声音！","notes":[]},{"n":2,"t":"愿我的祷告如香陈列在你面前！愿我举手祈求，如献晚祭！","notes":[]},{"n":3,"t":"耶和华啊，求你禁止我的口，把守我的嘴！","notes":[]},{"n":4,"t":"求你不叫我的心偏向邪恶，以致我和作孽的人同行恶事；也不叫我吃他们的美食。","notes":[]},{"n":5,"t":"任凭义人击打我，这算为仁慈；任凭他责备我，这算为头上的膏油；我的头不要躲闪。正在他们行恶的时候，我仍要祈祷。","notes":[]},{"n":6,"t":"他们的审判官被扔在岩下；众人要听我的话，因为这话甘甜。","notes":[]},{"n":7,"t":"我们的骨头散在墓旁，好像人耕田、刨地的土块。","notes":[]},{"n":8,"t":"主—耶和华啊，我的眼目仰望你；我投靠你，求你不要将我撇得孤苦！","notes":[]},{"n":9,"t":"求你保护我脱离恶人为我设的网罗和作孽之人的圈套！","notes":[]},{"n":10,"t":"愿恶人落在自己的网里，我却得以逃脱。","notes":[]}]},"142":{"heading":"求主眷顾","verses":[{"n":1,"t":"我发声哀告耶和华，发声恳求耶和华。","notes":[]},{"n":2,"t":"我在他面前吐露我的苦情，陈说我的患难。","notes":[]},{"n":3,"t":"我的灵在我里面发昏的时候，你知道我的道路。在我行的路上，敌人为我暗设网罗。","notes":[]},{"n":4,"t":"求你向我右边观看，因为没有人认识我；我无处避难，也没有人眷顾我。","notes":[]},{"n":5,"t":"耶和华啊，我曾向你哀求。我说：你是我的避难所；在活人之地，你是我的福分。","notes":[]},{"n":6,"t":"求你侧耳听我的呼求，因我落到极卑之地；求你救我脱离逼迫我的人，因为他们比我强盛。","notes":[]},{"n":7,"t":"求你领我出离被囚之地，我好称赞你的名。义人必环绕我，因为你是用厚恩待我。","notes":[]}]},"143":{"heading":"求主拯救","verses":[{"n":1,"t":"耶和华啊，求你听我的祷告，留心听我的恳求，凭你的信实和公义应允我。","notes":[]},{"n":2,"t":"求你不要审问仆人；因为在你面前，凡活着的人没有一个是义的。","notes":[]},{"n":3,"t":"原来仇敌逼迫我，将我打倒在地，使我住在幽暗之处，像死了许久的人一样。","notes":[]},{"n":4,"t":"所以，我的灵在我里面发昏；我的心在我里面凄惨。","notes":[]},{"n":5,"t":"我追想古时之日，思想你的一切作为，默念你手的工作。","notes":[]},{"n":6,"t":"我向你举手；我的心渴想你，如干旱之地盼雨一样。 （细拉）","notes":[]},{"n":7,"t":"耶和华啊，求你速速应允我！我心神耗尽！不要向我掩面，免得我像那些下坑的人一样。","notes":[]},{"n":8,"t":"求你使我清晨得听你慈爱之言，因我倚靠你；求你使我知道当行的路，因我的心仰望你。","notes":[]},{"n":9,"t":"耶和华啊，求你救我脱离我的仇敌！我往你那里藏身。","notes":[]},{"n":10,"t":"求你指教我遵行你的旨意，因你是我的神。你的灵本为善；求你引我到平坦之地。","notes":[]},{"n":11,"t":"耶和华啊，求你为你的名将我救活，凭你的公义，将我从患难中领出来，","notes":[]},{"n":12,"t":"凭你的慈爱剪除我的仇敌，灭绝一切苦待我的人，因我是你的仆人。","notes":[]}]},"144":{"heading":"君王为胜利感恩","verses":[{"n":1,"t":"耶和华—我的磐石是应当称颂的！他教导我的手争战，教导我的指头打仗。","notes":[]},{"n":2,"t":"他是我慈爱的主，我的山寨，我的高台，我的救主，我的盾牌，是我所投靠的；他使我的百姓服在我以下。","notes":[]},{"n":3,"t":"耶和华啊，人算什么，你竟认识他！世人算什么，你竟顾念他！","notes":[]},{"n":4,"t":"人好像一口气；他的年日如同影儿快快过去。","notes":[]},{"n":5,"t":"耶和华啊，求你使天下垂，亲自降临，摸山，山就冒烟。","notes":[]},{"n":6,"t":"求你发出闪电，使他们四散，射出你的箭，使他们扰乱。","notes":[]},{"n":7,"t":"求你从上伸手救拔我，救我出离大水，救我脱离外邦人的手。","notes":[]},{"n":8,"t":"他们的口说谎话；他们的右手起假誓。","notes":[]},{"n":9,"t":"神啊，我要向你唱新歌，用十弦瑟向你歌颂。","notes":[]},{"n":10,"t":"你是那拯救君王的；你是那救仆人大卫脱离害命之刀的。","notes":[]},{"n":11,"t":"求你救拔我，救我脱离外邦人的手。他们的口说谎话；他们的右手起假誓。","notes":[]},{"n":12,"t":"我们的儿子从幼年好像树栽子长大；我们的女儿如同殿角石，是按建宫的样式凿成的。","notes":[]},{"n":13,"t":"我们的仓盈满，能出各样的粮食；我们的羊在田间孳生千万。","notes":[]},{"n":14,"t":"我们的牛驮着满驮，没有人闯进来抢夺，也没有人出去争战；我们的街市上也没有哭号的声音。","notes":[]},{"n":15,"t":"遇见这光景的百姓便为有福！有耶和华为他们的神，这百姓便为有福！","notes":[]}]},"145":{"heading":"称颂的圣诗","verses":[{"n":1,"t":"我的神我的王啊，我要尊崇你！我要永永远远称颂你的名！","notes":[]},{"n":2,"t":"我要天天称颂你，也要永永远远赞美你的名！","notes":[]},{"n":3,"t":"耶和华本为大，该受大赞美；其大无法测度。","notes":[]},{"n":4,"t":"这代要对那代颂赞你的作为，也要传扬你的大能。","notes":[]},{"n":5,"t":"我要默念你威严的尊荣和你奇妙的作为。","notes":[]},{"n":6,"t":"人要传说你可畏之事的能力；我也要传扬你的大德。","notes":[]},{"n":7,"t":"他们记念你的大恩就要传出来，并要歌唱你的公义。","notes":[]},{"n":8,"t":"耶和华有恩惠，有怜悯，不轻易发怒，大有慈爱。","notes":[]},{"n":9,"t":"耶和华善待万民；他的慈悲覆庇他一切所造的。","notes":[]},{"n":10,"t":"耶和华啊，你一切所造的都要称谢你；你的圣民也要称颂你，","notes":[]},{"n":11,"t":"传说你国的荣耀，谈论你的大能，","notes":[]},{"n":12,"t":"好叫世人知道你大能的作为，并你国度威严的荣耀。","notes":[]},{"n":13,"t":"你的国是永远的国！你执掌的权柄存到万代！","notes":[]},{"n":14,"t":"凡跌倒的，耶和华将他们扶持；凡被压下的，将他们扶起。","notes":[]},{"n":15,"t":"万民都举目仰望你；你随时给他们食物。","notes":[]},{"n":16,"t":"你张手，使有生气的都随愿饱足。","notes":[]},{"n":17,"t":"耶和华在他一切所行的，无不公义；在他一切所做的都有慈爱。","notes":[]},{"n":18,"t":"凡求告耶和华的，就是诚心求告他的，耶和华便与他们相近。","notes":[]},{"n":19,"t":"敬畏他的，他必成就他们的心愿，也必听他们的呼求，拯救他们。","notes":[]},{"n":20,"t":"耶和华保护一切爱他的人，却要灭绝一切的恶人。","notes":[]},{"n":21,"t":"我的口要说出赞美耶和华的话；惟愿凡有血气的都永永远远称颂他的圣名。","notes":[]}]},"146":{"heading":"赞美耶和华的救助","verses":[{"n":1,"t":"你们要赞美耶和华！我的心哪，你要赞美耶和华！","notes":[]},{"n":2,"t":"我一生要赞美耶和华！我还活的时候要歌颂我的神！","notes":[]},{"n":3,"t":"你们不要倚靠君王，不要倚靠世人；他一点不能帮助。","notes":[]},{"n":4,"t":"他的气一断，就归回尘土；他所打算的，当日就消灭了。","notes":[]},{"n":5,"t":"以雅各的神为帮助、仰望耶和华—他神的，这人便为有福！","notes":[]},{"n":6,"t":"耶和华造天、地、海，和其中的万物；他守诚实，直到永远。","notes":[]},{"n":7,"t":"他为受屈的伸冤，赐食物与饥饿的。耶和华释放被囚的；","notes":[]},{"n":8,"t":"耶和华开了瞎子的眼睛；耶和华扶起被压下的人。耶和华喜爱义人。","notes":[]},{"n":9,"t":"耶和华保护寄居的，扶持孤儿和寡妇，却使恶人的道路弯曲。","notes":[]},{"n":10,"t":"耶和华要作王，直到永远！锡安哪，你的神要作王，直到万代！你们要赞美耶和华！","notes":[]}]},"147":{"heading":"赞美神的全能","verses":[{"n":1,"t":"你们要赞美耶和华！因歌颂我们的神为善为美；赞美的话是合宜的。","notes":[]},{"n":2,"t":"耶和华建造耶路撒冷，聚集以色列中被赶散的人。","notes":[]},{"n":3,"t":"他医好伤心的人，裹好他们的伤处。","notes":[]},{"n":4,"t":"他数点星宿的数目，一一称它的名。","notes":[]},{"n":5,"t":"我们的主为大，最有能力；他的智慧无法测度。","notes":[]},{"n":6,"t":"耶和华扶持谦卑人，将恶人倾覆于地。","notes":[]},{"n":7,"t":"你们要以感谢向耶和华歌唱，用琴向我们的神歌颂。","notes":[]},{"n":8,"t":"他用云遮天，为地降雨，使草生长在山上。","notes":[]},{"n":9,"t":"他赐食给走兽和啼叫的小乌鸦。","notes":[]},{"n":10,"t":"他不喜悦马的力大，不喜爱人的腿快。","notes":[]},{"n":11,"t":"耶和华喜爱敬畏他和盼望他慈爱的人。","notes":[]},{"n":12,"t":"耶路撒冷啊，你要颂赞耶和华！锡安哪，你要赞美你的神！","notes":[]},{"n":13,"t":"因为他坚固了你的门闩，赐福给你中间的儿女。","notes":[]},{"n":14,"t":"他使你境内平安，用上好的麦子使你满足。","notes":[]},{"n":15,"t":"他发命在地；他的话颁行最快。","notes":[]},{"n":16,"t":"他降雪如羊毛，撒霜如炉灰。","notes":[]},{"n":17,"t":"他掷下冰雹如碎渣；他发出寒冷，谁能当得起呢？","notes":[]},{"n":18,"t":"他一出令，这些就都消化；他使风刮起，水便流动。","notes":[]},{"n":19,"t":"他将他的道指示雅各，将他的律例典章指示以色列。","notes":[]},{"n":20,"t":"别国他都没有这样待过；至于他的典章，他们向来没有知道。你们要赞美耶和华！","notes":[]}]},"148":{"heading":"宣召万有赞美耶和华","verses":[{"n":1,"t":"你们要赞美耶和华！从天上赞美耶和华，在高处赞美他！","notes":[]},{"n":2,"t":"他的众使者都要赞美他！他的诸军都要赞美他！","notes":[]},{"n":3,"t":"日头月亮，你们要赞美他！放光的星宿，你们都要赞美他！","notes":[]},{"n":4,"t":"天上的天和天上的水，你们都要赞美他！","notes":[]},{"n":5,"t":"愿这些都赞美耶和华的名！因他一吩咐便都造成。","notes":[]},{"n":6,"t":"他将这些立定，直到永永远远；他定了命，不能废去。","notes":["或译：越过"]},{"n":7,"t":"所有在地上的，大鱼和一切深洋，","notes":[]},{"n":8,"t":"火与冰雹，雪和雾气，成就他命的狂风，","notes":[]},{"n":9,"t":"大山和小山，结果的树木和一切香柏树，","notes":[]},{"n":10,"t":"野兽和一切牲畜，昆虫和飞鸟，","notes":[]},{"n":11,"t":"世上的君王和万民，首领和世上一切审判官，","notes":[]},{"n":12,"t":"少年人和处女，老年人和孩童，都当赞美耶和华！","notes":[]},{"n":13,"t":"愿这些都赞美耶和华的名！因为独有他的名被尊崇；他的荣耀在天地之上。","notes":[]},{"n":14,"t":"他将他百姓的角高举，因此他一切圣民以色列人，就是与他相近的百姓，都赞美他！你们要赞美耶和华！","notes":["或译：他使"]}]},"149":{"heading":"赞美的圣诗","verses":[{"n":1,"t":"你们要赞美耶和华！向耶和华唱新歌，在圣民的会中赞美他！","notes":[]},{"n":2,"t":"愿以色列因造他的主欢喜！愿锡安的民因他们的王快乐！","notes":[]},{"n":3,"t":"愿他们跳舞赞美他的名，击鼓弹琴歌颂他！","notes":[]},{"n":4,"t":"因为耶和华喜爱他的百姓；他要用救恩当作谦卑人的妆饰。","notes":[]},{"n":5,"t":"愿圣民因所得的荣耀高兴！愿他们在床上欢呼！","notes":[]},{"n":6,"t":"愿他们口中称赞神为高，手里有两刃的刀，","notes":[]},{"n":7,"t":"为要报复列邦，刑罚万民。","notes":[]},{"n":8,"t":"要用链子捆他们的君王，用铁镣锁他们的大臣；","notes":[]},{"n":9,"t":"要在他们身上施行所记录的审判。他的圣民都有这荣耀。你们要赞美耶和华！","notes":[]}]},"150":{"heading":"赞美耶和华","verses":[{"n":1,"t":"你们要赞美耶和华！在神的圣所赞美他！在他显能力的穹苍赞美他！","notes":[]},{"n":2,"t":"要因他大能的作为赞美他，按着他极美的大德赞美他！","notes":[]},{"n":3,"t":"要用角声赞美他，鼓瑟弹琴赞美他！","notes":[]},{"n":4,"t":"击鼓跳舞赞美他！用丝弦的乐器和箫的声音赞美他！","notes":[]},{"n":5,"t":"用大响的钹赞美他！用高声的钹赞美他！","notes":[]},{"n":6,"t":"凡有气息的都要赞美耶和华！你们要赞美耶和华！","notes":[]}]}},"PRO":{"1":{"heading":"箴言的价值","verses":[{"n":1,"t":"以色列王大卫儿子所罗门的箴言：","notes":[]},{"n":2,"t":"要使人晓得智慧和训诲，分辨通达的言语，","notes":[]},{"n":3,"t":"使人处事领受智慧、仁义、公平、正直的训诲，","notes":[]},{"n":4,"t":"使愚人灵明，使少年人有知识和谋略，","notes":[]},{"n":5,"t":"使智慧人听见，增长学问，使聪明人得着智谋，","notes":[]},{"n":6,"t":"使人明白箴言和譬喻，懂得智慧人的言词和谜语。","notes":[]},{"n":7,"t":"敬畏耶和华是知识的开端；愚妄人藐视智慧和训诲。","notes":[],"heads":["给年青人的忠告"]},{"n":8,"t":"我儿，要听你父亲的训诲，不可离弃你母亲的法则；","notes":["或译：指教"]},{"n":9,"t":"因为这要作你头上的华冠，你项上的金链。","notes":[]},{"n":10,"t":"我儿，恶人若引诱你，你不可随从。","notes":[]},{"n":11,"t":"他们若说：你与我们同去，我们要埋伏流人之血，要蹲伏害无罪之人；","notes":[]},{"n":12,"t":"我们好像阴间，把他们活活吞下；他们如同下坑的人，被我们囫囵吞了；","notes":[]},{"n":13,"t":"我们必得各样宝物，将所掳来的，装满房屋；","notes":[]},{"n":14,"t":"你与我们大家同分，我们共用一个囊袋；","notes":[]},{"n":15,"t":"我儿，不要与他们同行一道，禁止你脚走他们的路。","notes":[]},{"n":16,"t":"因为，他们的脚奔跑行恶；他们急速流人的血，","notes":[]},{"n":17,"t":"好像飞鸟，网罗设在眼前仍不躲避。","notes":[]},{"n":18,"t":"这些人埋伏，是为自流己血；蹲伏，是为自害己命。","notes":[]},{"n":19,"t":"凡贪恋财利的，所行之路都是如此；这贪恋之心乃夺去得财者之命。","notes":[]},{"n":20,"t":"智慧在街市上呼喊，在宽阔处发声，","notes":[],"heads":["智慧呼唤人"]},{"n":21,"t":"在热闹街头喊叫，在城门口，在城中发出言语，","notes":[]},{"n":22,"t":"说：你们愚昧人喜爱愚昧，亵慢人喜欢亵慢，愚顽人恨恶知识，要到几时呢？","notes":[]},{"n":23,"t":"你们当因我的责备回转；我要将我的灵浇灌你们，将我的话指示你们。","notes":[]},{"n":24,"t":"我呼唤，你们不肯听从；我伸手，无人理会；","notes":[]},{"n":25,"t":"反轻弃我一切的劝戒，不肯受我的责备。","notes":[]},{"n":26,"t":"你们遭灾难，我就发笑；惊恐临到你们，我必嗤笑。","notes":[]},{"n":27,"t":"惊恐临到你们，好像狂风；灾难来到，如同暴风；急难痛苦临到你们身上。","notes":[]},{"n":28,"t":"那时，你们必呼求我，我却不答应，恳切地寻找我，却寻不见。","notes":[]},{"n":29,"t":"因为，你们恨恶知识，不喜爱敬畏耶和华，","notes":[]},{"n":30,"t":"不听我的劝戒，藐视我一切的责备，","notes":[]},{"n":31,"t":"所以必吃自结的果子，充满自设的计谋。","notes":[]},{"n":32,"t":"愚昧人背道，必杀己身；愚顽人安逸，必害己命。","notes":[]},{"n":33,"t":"惟有听从我的，必安然居住，得享安静，不怕灾祸。","notes":[]}]},"2":{"heading":"智慧的赏赐","verses":[{"n":1,"t":"我儿，你若领受我的言语，存记我的命令，","notes":[]},{"n":2,"t":"侧耳听智慧，专心求聪明，","notes":[]},{"n":3,"t":"呼求明哲，扬声求聪明，","notes":[]},{"n":4,"t":"寻找它，如寻找银子，搜求它，如搜求隐藏的珍宝，","notes":[]},{"n":5,"t":"你就明白敬畏耶和华，得以认识神。","notes":[]},{"n":6,"t":"因为，耶和华赐人智慧；知识和聪明都由他口而出。","notes":[]},{"n":7,"t":"他给正直人存留真智慧，给行为纯正的人作盾牌，","notes":[]},{"n":8,"t":"为要保守公平人的路，护庇虔敬人的道。","notes":[]},{"n":9,"t":"你也必明白仁义、公平、正直、一切的善道。","notes":[]},{"n":10,"t":"智慧必入你心；你的灵要以知识为美。","notes":[]},{"n":11,"t":"谋略必护卫你；聪明必保守你，","notes":[]},{"n":12,"t":"要救你脱离恶道，脱离说乖谬话的人。","notes":["或译：恶人的道"]},{"n":13,"t":"那等人舍弃正直的路，行走黑暗的道，","notes":[]},{"n":14,"t":"欢喜作恶，喜爱恶人的乖僻，","notes":[]},{"n":15,"t":"在他们的道中弯曲，在他们的路上偏僻。","notes":[]},{"n":16,"t":"智慧要救你脱离淫妇，就是那油嘴滑舌的外女。","notes":[]},{"n":17,"t":"她离弃幼年的配偶，忘了神的盟约。","notes":[]},{"n":18,"t":"她的家陷入死地；她的路偏向阴间。","notes":[]},{"n":19,"t":"凡到她那里去的，不得转回，也得不着生命的路。","notes":[]},{"n":20,"t":"智慧必使你行善人的道，守义人的路。","notes":[]},{"n":21,"t":"正直人必在世上居住；完全人必在地上存留。","notes":[]},{"n":22,"t":"惟有恶人必然剪除；奸诈的，必然拔出。","notes":[]}]},"3":{"heading":"给青年人的忠告","verses":[{"n":1,"t":"我儿，不要忘记我的法则；你心要谨守我的诫命；","notes":["或译：指教"]},{"n":2,"t":"因为它必将长久的日子，生命的年数与平安，加给你。","notes":[]},{"n":3,"t":"不可使慈爱、诚实离开你，要系在你颈项上，刻在你心版上。","notes":[]},{"n":4,"t":"这样，你必在神和世人眼前蒙恩宠，有聪明。","notes":[]},{"n":5,"t":"你要专心仰赖耶和华，不可倚靠自己的聪明，","notes":[]},{"n":6,"t":"在你一切所行的事上都要认定他，他必指引你的路。","notes":[]},{"n":7,"t":"不要自以为有智慧；要敬畏耶和华，远离恶事。","notes":[]},{"n":8,"t":"这便医治你的肚脐，滋润你的百骨。","notes":[]},{"n":9,"t":"你要以财物和一切初熟的土产尊荣耶和华。","notes":[]},{"n":10,"t":"这样，你的仓房必充满有余；你的酒榨有新酒盈溢。","notes":[]},{"n":11,"t":"我儿，你不可轻看耶和华的管教，也不可厌烦他的责备；","notes":["或译：惩治"]},{"n":12,"t":"因为耶和华所爱的，他必责备，正如父亲责备所喜爱的儿子。","notes":[]},{"n":13,"t":"得智慧，得聪明的，这人便为有福。","notes":[]},{"n":14,"t":"因为得智慧胜过得银子，其利益强如精金，","notes":[]},{"n":15,"t":"比珍珠宝贵；你一切所喜爱的，都不足与比较。","notes":["或译：红宝石"]},{"n":16,"t":"她右手有长寿，左手有富贵。","notes":[]},{"n":17,"t":"她的道是安乐；她的路全是平安。","notes":[]},{"n":18,"t":"她与持守她的作生命树；持定她的，俱各有福。","notes":[]},{"n":19,"t":"耶和华以智慧立地，以聪明定天，","notes":[]},{"n":20,"t":"以知识使深渊裂开，使天空滴下甘露。","notes":[]},{"n":21,"t":"我儿，要谨守真智慧和谋略，不可使她离开你的眼目。","notes":[]},{"n":22,"t":"这样，她必作你的生命，颈项的美饰。","notes":[]},{"n":23,"t":"你就坦然行路，不致碰脚。","notes":[]},{"n":24,"t":"你躺下，必不惧怕；你躺卧，睡得香甜。","notes":[]},{"n":25,"t":"忽然来的惊恐，不要害怕；恶人遭毁灭，也不要恐惧。","notes":[]},{"n":26,"t":"因为耶和华是你所倚靠的；他必保守你的脚不陷入网罗。","notes":[]},{"n":27,"t":"你手若有行善的力量，不可推辞，就当向那应得的人施行。","notes":[]},{"n":28,"t":"你那里若有现成的，不可对邻舍说：去吧，明天再来，我必给你。","notes":[]},{"n":29,"t":"你的邻舍既在你附近安居，你不可设计害他。","notes":[]},{"n":30,"t":"人未曾加害与你，不可无故与他相争。","notes":[]},{"n":31,"t":"不可嫉妒强暴的人，也不可选择他所行的路。","notes":[]},{"n":32,"t":"因为，乖僻人为耶和华所憎恶；正直人为他所亲密。","notes":[]},{"n":33,"t":"耶和华咒诅恶人的家庭，赐福与义人的居所。","notes":[]},{"n":34,"t":"他讥诮那好讥诮的人，赐恩给谦卑的人。","notes":[]},{"n":35,"t":"智慧人必承受尊荣；愚昧人高升也成为羞辱。","notes":[]}]},"4":{"heading":"智慧的益处","verses":[{"n":1,"t":"众子啊，要听父亲的教训，留心得知聪明。","notes":[]},{"n":2,"t":"因我所给你们的是好教训；不可离弃我的法则。","notes":["或译：指教"]},{"n":3,"t":"我在父亲面前为孝子，在母亲眼中为独一的娇儿。","notes":[]},{"n":4,"t":"父亲教训我说：你心要存记我的言语，遵守我的命令，便得存活。","notes":[]},{"n":5,"t":"要得智慧，要得聪明，不可忘记，也不可偏离我口中的言语。","notes":[]},{"n":6,"t":"不可离弃智慧，智慧就护卫你；要爱她，她就保守你。","notes":[]},{"n":7,"t":"智慧为首；所以，要得智慧。在你一切所得之内必得聪明 。","notes":["或译：用你一切所得的去换聪明"]},{"n":8,"t":"高举智慧，她就使你高升；怀抱智慧，她就使你尊荣。","notes":[]},{"n":9,"t":"她必将华冠加在你头上，把荣冕交给你。","notes":[]},{"n":10,"t":"我儿，你要听受我的言语，就必延年益寿。","notes":[]},{"n":11,"t":"我已指教你走智慧的道，引导你行正直的路。","notes":[]},{"n":12,"t":"你行走，脚步必不致狭窄；你奔跑，也不致跌倒。","notes":[]},{"n":13,"t":"要持定训诲，不可放松；必当谨守，因为它是你的生命。","notes":[]},{"n":14,"t":"不可行恶人的路；不要走坏人的道。","notes":[]},{"n":15,"t":"要躲避，不可经过；要转身而去。","notes":[]},{"n":16,"t":"这等人若不行恶，不得睡觉；不使人跌倒，睡卧不安；","notes":[]},{"n":17,"t":"因为他们以奸恶吃饼，以强暴喝酒。","notes":[]},{"n":18,"t":"但义人的路好像黎明的光，越照越明，直到日午。","notes":[]},{"n":19,"t":"恶人的道好像幽暗，自己不知因什么跌倒。","notes":[]},{"n":20,"t":"我儿，要留心听我的言词，侧耳听我的话语，","notes":[]},{"n":21,"t":"都不可离你的眼目，要存记在你心中。","notes":[]},{"n":22,"t":"因为得着它的，就得了生命，又得了医全体的良药。","notes":[]},{"n":23,"t":"你要保守你心，胜过保守一切，因为一生的果效是由心发出。","notes":["或译：你要切切保守你心"]},{"n":24,"t":"你要除掉邪僻的口，弃绝乖谬的嘴。","notes":[]},{"n":25,"t":"你的眼目要向前正看；你的眼睛当向前直观。","notes":["原文是皮"]},{"n":26,"t":"要修平你脚下的路，坚定你一切的道。","notes":[]},{"n":27,"t":"不可偏向左右；要使你的脚离开邪恶。","notes":[]}]},"5":{"heading":"警告勿犯淫乱","verses":[{"n":1,"t":"我儿，要留心我智慧的话语，侧耳听我聪明的言词，","notes":[]},{"n":2,"t":"为要使你谨守谋略，嘴唇保存知识。","notes":[]},{"n":3,"t":"因为淫妇的嘴滴下蜂蜜；她的口比油更滑，","notes":[]},{"n":4,"t":"至终却苦似茵陈，快如两刃的刀。","notes":[]},{"n":5,"t":"她的脚下入死地；她脚步踏住阴间，","notes":[]},{"n":6,"t":"以致她找不着生命平坦的道。她的路变迁不定，自己还不知道。","notes":[]},{"n":7,"t":"众子啊，现在要听从我；不可离弃我口中的话。","notes":[]},{"n":8,"t":"你所行的道要离她远，不可就近她的房门，","notes":[]},{"n":9,"t":"恐怕将你的尊荣给别人，将你的岁月给残忍的人；","notes":[]},{"n":10,"t":"恐怕外人满得你的力量，你劳碌得来的，归入外人的家；","notes":[]},{"n":11,"t":"终久，你皮肉和身体消毁，你就悲叹，","notes":[]},{"n":12,"t":"说：我怎么恨恶训诲，心中藐视责备，","notes":[]},{"n":13,"t":"也不听从我师傅的话，又不侧耳听那教训我的人？","notes":[]},{"n":14,"t":"我在圣会里，几乎落在诸般恶中。","notes":[]},{"n":15,"t":"你要喝自己池中的水，饮自己井里的活水。","notes":[]},{"n":16,"t":"你的泉源岂可涨溢在外？你的河水岂可流在街上？","notes":[]},{"n":17,"t":"惟独归你一人，不可与外人同用。","notes":[]},{"n":18,"t":"要使你的泉源蒙福；要喜悦你幼年所娶的妻。","notes":[]},{"n":19,"t":"她如可爱的麀鹿，可喜的母鹿；愿她的胸怀使你时时知足，她的爱情使你常常恋慕。","notes":[]},{"n":20,"t":"我儿，你为何恋慕淫妇？为何抱外女的胸怀？","notes":[]},{"n":21,"t":"因为，人所行的道都在耶和华眼前；他也修平人一切的路。","notes":[]},{"n":22,"t":"恶人必被自己的罪孽捉住；他必被自己的罪恶如绳索缠绕。","notes":[]},{"n":23,"t":"他因不受训诲就必死亡；又因愚昧过甚，必走差了路。","notes":[]}]},"6":{"heading":"更多的警告","verses":[{"n":1,"t":"我儿，你若为朋友作保，替外人击掌，","notes":[]},{"n":2,"t":"你就被口中的话语缠住，被嘴里的言语捉住。","notes":[]},{"n":3,"t":"我儿，你既落在朋友手中，就当这样行才可救自己：你要自卑，去恳求你的朋友。","notes":[]},{"n":4,"t":"不要容你的眼睛睡觉；不要容你的眼皮打盹。","notes":[]},{"n":5,"t":"要救自己，如鹿脱离猎户的手，如鸟脱离捕鸟人的手。","notes":[]},{"n":6,"t":"懒惰人哪，你去察看蚂蚁的动作就可得智慧。","notes":[]},{"n":7,"t":"蚂蚁没有元帅，没有官长，没有君王，","notes":[]},{"n":8,"t":"尚且在夏天预备食物，在收割时聚敛粮食。","notes":[]},{"n":9,"t":"懒惰人哪，你要睡到几时呢？你何时睡醒呢？","notes":[]},{"n":10,"t":"再睡片时，打盹片时，抱着手躺卧片时，","notes":[]},{"n":11,"t":"你的贫穷就必如强盗速来，你的缺乏仿佛拿兵器的人来到。","notes":[]},{"n":12,"t":"无赖的恶徒，行动就用乖僻的口，","notes":[]},{"n":13,"t":"用眼传神，用脚示意，用指点划，","notes":[]},{"n":14,"t":"心中乖僻，常设恶谋，布散纷争。","notes":[]},{"n":15,"t":"所以，灾难必忽然临到他身；他必顷刻败坏，无法可治。","notes":[]},{"n":16,"t":"耶和华所恨恶的有六样，连他心所憎恶的共有七样：","notes":[]},{"n":17,"t":"就是高傲的眼，撒谎的舌，流无辜人血的手，","notes":[]},{"n":18,"t":"图谋恶计的心，飞跑行恶的脚，","notes":[]},{"n":19,"t":"吐谎言的假见证，并弟兄中布散纷争的人。","notes":[]},{"n":20,"t":"我儿，要谨守你父亲的诫命；不可离弃你母亲的法则，","notes":["或译：指教"],"heads":["警告勿犯淫乱"]},{"n":21,"t":"要常系在你心上，挂在你项上。","notes":[]},{"n":22,"t":"你行走，它必引导你；你躺卧，它必保守你；你睡醒，它必与你谈论。","notes":[]},{"n":23,"t":"因为诫命是灯，法则是光，训诲的责备是生命的道，","notes":["或译：指教"]},{"n":24,"t":"能保你远离恶妇，远离外女谄媚的舌头。","notes":[]},{"n":25,"t":"你心中不要恋慕她的美色，也不要被她眼皮勾引。","notes":[]},{"n":26,"t":"因为，妓女能使人只剩一块饼；淫妇猎取人宝贵的生命。","notes":[]},{"n":27,"t":"人若怀里搋火，衣服岂能不烧呢？","notes":[]},{"n":28,"t":"人若在火炭上走，脚岂能不烫呢？","notes":[]},{"n":29,"t":"亲近邻舍之妻的，也是如此；凡挨近她的，不免受罚。","notes":[]},{"n":30,"t":"贼因饥饿偷窃充饥，人不藐视他，","notes":[]},{"n":31,"t":"若被找着，他必赔还七倍，必将家中所有的尽都偿还。","notes":[]},{"n":32,"t":"与妇人行淫的，便是无知；行这事的，必丧掉生命。","notes":[]},{"n":33,"t":"他必受伤损，必被凌辱；他的羞耻不得涂抹。","notes":[]},{"n":34,"t":"因为人的嫉恨成了烈怒，报仇的时候决不留情。","notes":[]},{"n":35,"t":"什么赎价，他都不顾；你虽送许多礼物，他也不肯干休。","notes":[]}]},"7":{"heading":"淫乱的妇人","verses":[{"n":1,"t":"我儿，你要遵守我的言语，将我的命令存记在心。","notes":[]},{"n":2,"t":"遵守我的命令就得存活；保守我的法则，好像保守眼中的瞳人，","notes":["或译：指教"]},{"n":3,"t":"系在你指头上，刻在你心版上。","notes":[]},{"n":4,"t":"对智慧说：你是我的姊妹，称呼聪明为你的亲人，","notes":[]},{"n":5,"t":"她就保你远离淫妇，远离说谄媚话的外女。","notes":[]},{"n":6,"t":"我曾在我房屋的窗户内，从我窗棂之间往外观看：","notes":[]},{"n":7,"t":"见愚蒙人内，少年人中，分明有一个无知的少年人，","notes":[]},{"n":8,"t":"从街上经过，走近淫妇的巷口，直往通她家的路去，","notes":[]},{"n":9,"t":"在黄昏，或晚上，或半夜，或黑暗之中。","notes":[]},{"n":10,"t":"看哪，有一个妇人来迎接他，是妓女的打扮，有诡诈的心思。","notes":[]},{"n":11,"t":"这妇人喧嚷，不守约束，在家里停不住脚，","notes":[]},{"n":12,"t":"有时在街市上，有时在宽阔处，或在各巷口蹲伏，","notes":[]},{"n":13,"t":"拉住那少年人，与他亲嘴，脸无羞耻对他说：","notes":[]},{"n":14,"t":"平安祭在我这里，今日才还了我所许的愿。","notes":[]},{"n":15,"t":"因此，我出来迎接你，恳切求见你的面，恰巧遇见了你。","notes":[]},{"n":16,"t":"我已经用绣花毯子和埃及线织的花纹布铺了我的床。","notes":[]},{"n":17,"t":"我又用没药、沉香、桂皮薰了我的榻。","notes":[]},{"n":18,"t":"你来，我们可以饱享爱情，直到早晨；我们可以彼此亲爱欢乐。","notes":[]},{"n":19,"t":"因为我丈夫不在家，出门行远路；","notes":[]},{"n":20,"t":"他手拿银囊，必到月望才回家。","notes":[]},{"n":21,"t":"淫妇用许多巧言诱他随从，用谄媚的嘴逼他同行。","notes":[]},{"n":22,"t":"少年人立刻跟随她，好像牛往宰杀之地；又像愚昧人带锁链去受刑罚，","notes":[]},{"n":23,"t":"直等箭穿他的肝；如同雀鸟急入网罗，却不知是自丧己命。","notes":[]},{"n":24,"t":"众子啊，现在要听从我，留心听我口中的话。","notes":[]},{"n":25,"t":"你的心不可偏向淫妇的道，不要入她的迷途。","notes":[]},{"n":26,"t":"因为，被她伤害仆倒的不少；被她杀戮的而且甚多。","notes":[]},{"n":27,"t":"她的家是在阴间之路，下到死亡之宫。","notes":[]}]},"8":{"heading":"智慧颂","verses":[{"n":1,"t":"智慧岂不呼叫？聪明岂不发声？","notes":[]},{"n":2,"t":"她在道旁高处的顶上，在十字路口站立，","notes":[]},{"n":3,"t":"在城门旁，在城门口，在城门洞，大声说：","notes":[]},{"n":4,"t":"众人哪，我呼叫你们，我向世人发声。","notes":[]},{"n":5,"t":"说：愚蒙人哪，你们要会悟灵明；愚昧人哪，你们当心里明白。","notes":[]},{"n":6,"t":"你们当听，因我要说极美的话；我张嘴要论正直的事。","notes":[]},{"n":7,"t":"我的口要发出真理；我的嘴憎恶邪恶。","notes":[]},{"n":8,"t":"我口中的言语都是公义，并无弯曲乖僻。","notes":[]},{"n":9,"t":"有聪明的，以为明显，得知识的，以为正直。","notes":[]},{"n":10,"t":"你们当受我的教训，不受白银；宁得知识，胜过黄金。","notes":[]},{"n":11,"t":"因为智慧比珍珠更美；一切可喜爱的都不足与比较。","notes":["或译：红宝石"]},{"n":12,"t":"我—智慧以灵明为居所，又寻得知识和谋略。","notes":[]},{"n":13,"t":"敬畏耶和华在乎恨恶邪恶；那骄傲、狂妄，并恶道，以及乖谬的口，都为我所恨恶。","notes":[]},{"n":14,"t":"我有谋略和真知识；我乃聪明，我有能力。","notes":[]},{"n":15,"t":"帝王借我坐国位；君王借我定公平。","notes":[]},{"n":16,"t":"王子和首领，世上一切的审判官，都是借我掌权。","notes":[]},{"n":17,"t":"爱我的，我也爱他；恳切寻求我的，必寻得见。","notes":[]},{"n":18,"t":"丰富尊荣在我；恒久的财并公义也在我。","notes":[]},{"n":19,"t":"我的果实胜过黄金，强如精金；我的出产超乎高银。","notes":[]},{"n":20,"t":"我在公义的道上走，在公平的路中行，","notes":[]},{"n":21,"t":"使爱我的，承受货财，并充满他们的府库。","notes":[]},{"n":22,"t":"在耶和华造化的起头，在太初创造万物之先，就有了我。","notes":[]},{"n":23,"t":"从亘古，从太初，未有世界以前，我已被立。","notes":[]},{"n":24,"t":"没有深渊，没有大水的泉源，我已生出。","notes":[]},{"n":25,"t":"大山未曾奠定，小山未有之先，我已生出。","notes":[]},{"n":26,"t":"耶和华还没有创造大地和田野，并世上的土质，我已生出。","notes":[]},{"n":27,"t":"他立高天，我在那里；他在渊面的周围，划出圆圈。","notes":[]},{"n":28,"t":"上使穹苍坚硬，下使渊源稳固，","notes":[]},{"n":29,"t":"为沧海定出界限，使水不越过他的命令，立定大地的根基。","notes":[]},{"n":30,"t":"那时，我在他那里为工师，日日为他所喜爱，常常在他面前踊跃，","notes":[]},{"n":31,"t":"踊跃在他为人预备可住之地，也喜悦住在世人之间。","notes":[]},{"n":32,"t":"众子啊，现在要听从我，因为谨守我道的，便为有福。","notes":[]},{"n":33,"t":"要听教训就得智慧，不可弃绝。","notes":[]},{"n":34,"t":"听从我、日日在我门口仰望、在我门框旁边等候的，那人便为有福。","notes":[]},{"n":35,"t":"因为寻得我的，就寻得生命，也必蒙耶和华的恩惠。","notes":[]},{"n":36,"t":"得罪我的，却害了自己的性命；恨恶我的，都喜爱死亡。","notes":[]}]},"9":{"heading":"智慧和愚蠢","verses":[{"n":1,"t":"智慧建造房屋，凿成七根柱子，","notes":[]},{"n":2,"t":"宰杀牲畜，调和旨酒，设摆筵席；","notes":[]},{"n":3,"t":"打发使女出去，自己在城中至高处呼叫，","notes":[]},{"n":4,"t":"说：谁是愚蒙人，可以转到这里来！又对那无知的人说：","notes":[]},{"n":5,"t":"你们来，吃我的饼，喝我调和的酒。","notes":[]},{"n":6,"t":"你们愚蒙人，要舍弃愚蒙，就得存活，并要走光明的道。","notes":[]},{"n":7,"t":"指斥亵慢人的，必受辱骂；责备恶人的，必被玷污。","notes":[]},{"n":8,"t":"不要责备亵慢人，恐怕他恨你；要责备智慧人，他必爱你。","notes":[]},{"n":9,"t":"教导智慧人，他就越发有智慧；指示义人，他就增长学问。","notes":[]},{"n":10,"t":"敬畏耶和华是智慧的开端；认识至圣者便是聪明。","notes":[]},{"n":11,"t":"你借着我，日子必增多，年岁也必加添。","notes":[]},{"n":12,"t":"你若有智慧，是与自己有益；你若亵慢，就必独自担当。","notes":[]},{"n":13,"t":"愚昧的妇人喧嚷；她是愚蒙，一无所知。","notes":[]},{"n":14,"t":"她坐在自己的家门口，坐在城中高处的座位上，","notes":[]},{"n":15,"t":"呼叫过路的，就是直行其道的人，","notes":[]},{"n":16,"t":"说：谁是愚蒙人，可以转到这里来！又对那无知的人说：","notes":[]},{"n":17,"t":"偷来的水是甜的，暗吃的饼是好的。","notes":[]},{"n":18,"t":"人却不知有阴魂在她那里；她的客在阴间的深处。","notes":[]}]},"10":{"heading":"所罗门的箴言","verses":[{"n":1,"t":"所罗门的箴言：智慧之子使父亲欢乐；愚昧之子叫母亲担忧。","notes":[]},{"n":2,"t":"不义之财毫无益处；惟有公义能救人脱离死亡。","notes":[]},{"n":3,"t":"耶和华不使义人受饥饿；恶人所欲的，他必推开。","notes":[]},{"n":4,"t":"手懒的，要受贫穷；手勤的，却要富足。","notes":[]},{"n":5,"t":"夏天聚敛的，是智慧之子；收割时沉睡的，是贻羞之子。","notes":[]},{"n":6,"t":"福祉临到义人的头；强暴蒙蔽恶人的口。","notes":[]},{"n":7,"t":"义人的纪念被称赞；恶人的名字必朽烂。","notes":[]},{"n":8,"t":"心中智慧的，必受命令；口里愚妄的，必致倾倒。","notes":[]},{"n":9,"t":"行正直路的，步步安稳；走弯曲道的，必致败露。","notes":[]},{"n":10,"t":"以眼传神的，使人忧患；口里愚妄的，必致倾倒。","notes":[]},{"n":11,"t":"义人的口是生命的泉源；强暴蒙蔽恶人的口。","notes":[]},{"n":12,"t":"恨能挑启争端；爱能遮掩一切过错。","notes":[]},{"n":13,"t":"明哲人嘴里有智慧；无知人背上受刑杖。","notes":[]},{"n":14,"t":"智慧人积存知识；愚妄人的口速致败坏。","notes":[]},{"n":15,"t":"富户的财物是他的坚城；穷人的贫乏是他的败坏。","notes":[]},{"n":16,"t":"义人的勤劳致生；恶人的进项致死。","notes":["死：原文是罪"]},{"n":17,"t":"谨守训诲的，乃在生命的道上；违弃责备的，便失迷了路。","notes":[]},{"n":18,"t":"隐藏怨恨的，有说谎的嘴；口出谗谤的，是愚妄的人。","notes":[]},{"n":19,"t":"多言多语难免有过；禁止嘴唇是有智慧。","notes":[]},{"n":20,"t":"义人的舌乃似高银；恶人的心所值无几。","notes":[]},{"n":21,"t":"义人的口教养多人；愚昧人因无知而死亡。","notes":[]},{"n":22,"t":"耶和华所赐的福使人富足，并不加上忧虑。","notes":[]},{"n":23,"t":"愚妄人以行恶为戏耍；明哲人却以智慧为乐。","notes":[]},{"n":24,"t":"恶人所怕的，必临到他；义人所愿的，必蒙应允。","notes":[]},{"n":25,"t":"暴风一过，恶人归于无有；义人的根基却是永久。","notes":[]},{"n":26,"t":"懒惰人叫差他的人如醋倒牙，如烟薰目。","notes":[]},{"n":27,"t":"敬畏耶和华使人日子加多；但恶人的年岁必被减少。","notes":[]},{"n":28,"t":"义人的盼望必得喜乐；恶人的指望必致灭没。","notes":[]},{"n":29,"t":"耶和华的道是正直人的保障，却成了作孽人的败坏。","notes":[]},{"n":30,"t":"义人永不挪移；恶人不得住在地上。","notes":[]},{"n":31,"t":"义人的口滋生智慧；乖谬的舌必被割断。","notes":[]},{"n":32,"t":"义人的嘴能令人喜悦；恶人的口说乖谬的话。","notes":[]}]},"11":{"heading":"","verses":[{"n":1,"t":"诡诈的天平为耶和华所憎恶；公平的法码为他所喜悦。","notes":[]},{"n":2,"t":"骄傲来，羞耻也来；谦逊人却有智慧。","notes":[]},{"n":3,"t":"正直人的纯正必引导自己；奸诈人的乖僻必毁灭自己。","notes":[]},{"n":4,"t":"发怒的日子资财无益；惟有公义能救人脱离死亡。","notes":[]},{"n":5,"t":"完全人的义必指引他的路；但恶人必因自己的恶跌倒。","notes":[]},{"n":6,"t":"正直人的义必拯救自己；奸诈人必陷在自己的罪孽中。","notes":[]},{"n":7,"t":"恶人一死，他的指望必灭绝；罪人的盼望也必灭没。","notes":[]},{"n":8,"t":"义人得脱离患难，有恶人来代替他。","notes":[]},{"n":9,"t":"不虔敬的人用口败坏邻舍；义人却因知识得救。","notes":[]},{"n":10,"t":"义人享福，合城喜乐；恶人灭亡，人都欢呼。","notes":[]},{"n":11,"t":"城因正直人祝福便高举，却因邪恶人的口就倾覆。","notes":[]},{"n":12,"t":"藐视邻舍的，毫无智慧；明哲人却静默不言。","notes":[]},{"n":13,"t":"往来传舌的，泄漏密事；心中诚实的，遮隐事情。","notes":[]},{"n":14,"t":"无智谋，民就败落；谋士多，人便安居。","notes":[]},{"n":15,"t":"为外人作保的，必受亏损；恨恶击掌的，却得安稳。","notes":[]},{"n":16,"t":"恩德的妇女得尊荣；强暴的男子得资财。","notes":[]},{"n":17,"t":"仁慈的人善待自己；残忍的人扰害己身。","notes":[]},{"n":18,"t":"恶人经营，得虚浮的工价；撒义种的，得实在的果效。","notes":[]},{"n":19,"t":"恒心为义的，必得生命；追求邪恶的，必致死亡。","notes":[]},{"n":20,"t":"心中乖僻的，为耶和华所憎恶；行事完全的，为他所喜悦。","notes":[]},{"n":21,"t":"恶人虽然连手，必不免受罚；义人的后裔必得拯救。","notes":[]},{"n":22,"t":"妇女美貌而无见识，如同金环带在猪鼻上。","notes":[]},{"n":23,"t":"义人的心愿尽得好处；恶人的指望致干忿怒。","notes":[]},{"n":24,"t":"有施散的，却更增添；有吝惜过度的，反致穷乏。","notes":[]},{"n":25,"t":"好施舍的，必得丰裕；滋润人的，必得滋润。","notes":[]},{"n":26,"t":"屯粮不卖的，民必咒诅他；情愿出卖的，人必为他祝福。","notes":[]},{"n":27,"t":"恳切求善的，就求得恩惠；惟独求恶的，恶必临到他身。","notes":[]},{"n":28,"t":"倚仗自己财物的，必跌倒；义人必发旺，如青叶。","notes":[]},{"n":29,"t":"扰害己家的，必承受清风；愚昧人必作慧心人的仆人。","notes":[]},{"n":30,"t":"义人所结的果子就是生命树；有智慧的，必能得人。","notes":[]},{"n":31,"t":"看哪，义人在世尚且受报，何况恶人和罪人呢？","notes":[]}]},"12":{"heading":"","verses":[{"n":1,"t":"喜爱管教的，就是喜爱知识；恨恶责备的，却是畜类。","notes":[]},{"n":2,"t":"善人必蒙耶和华的恩惠；设诡计的人，耶和华必定他的罪。","notes":[]},{"n":3,"t":"人靠恶行不能坚立；义人的根必不动摇。","notes":[]},{"n":4,"t":"才德的妇人是丈夫的冠冕；贻羞的妇人如同朽烂在她丈夫的骨中。","notes":[]},{"n":5,"t":"义人的思念是公平；恶人的计谋是诡诈。","notes":[]},{"n":6,"t":"恶人的言论是埋伏流人的血；正直人的口必拯救人。","notes":[]},{"n":7,"t":"恶人倾覆，归于无有；义人的家必站得住。","notes":[]},{"n":8,"t":"人必按自己的智慧被称赞；心中乖谬的，必被藐视。","notes":[]},{"n":9,"t":"被人轻贱，却有仆人，强如自尊，缺少食物。","notes":[]},{"n":10,"t":"义人顾惜他牲畜的命；恶人的怜悯也是残忍。","notes":[]},{"n":11,"t":"耕种自己田地的，必得饱食；追随虚浮的，却是无知。","notes":[]},{"n":12,"t":"恶人想得坏人的网罗；义人的根得以结实。","notes":[]},{"n":13,"t":"恶人嘴中的过错是自己的网罗；但义人必脱离患难。","notes":[]},{"n":14,"t":"人因口所结的果子，必饱得美福；人手所做的，必为自己的报应。","notes":[]},{"n":15,"t":"愚妄人所行的，在自己眼中看为正直；惟智慧人肯听人的劝教。","notes":[]},{"n":16,"t":"愚妄人的恼怒立时显露；通达人能忍辱藏羞。","notes":[]},{"n":17,"t":"说出真话的，显明公义；作假见证的，显出诡诈。","notes":[]},{"n":18,"t":"说话浮躁的，如刀刺人；智慧人的舌头却为医人的良药。","notes":[]},{"n":19,"t":"口吐真言，永远坚立；舌说谎话，只存片时。","notes":[]},{"n":20,"t":"图谋恶事的，心存诡诈；劝人和睦的，便得喜乐。","notes":[]},{"n":21,"t":"义人不遭灾害；恶人满受祸患。","notes":[]},{"n":22,"t":"说谎言的嘴为耶和华所憎恶；行事诚实的，为他所喜悦。","notes":[]},{"n":23,"t":"通达人隐藏知识；愚昧人的心彰显愚昧。","notes":[]},{"n":24,"t":"殷勤人的手必掌权；懒惰的人必服苦。","notes":[]},{"n":25,"t":"人心忧虑，屈而不伸；一句良言，使心欢乐。","notes":[]},{"n":26,"t":"义人引导他的邻舍；恶人的道叫人失迷。","notes":[]},{"n":27,"t":"懒惰的人不烤打猎所得的；殷勤的人却得宝贵的财物。","notes":[]},{"n":28,"t":"在公义的道上有生命；其路之中并无死亡。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"智慧子听父亲的教训；亵慢人不听责备。","notes":[]},{"n":2,"t":"人因口所结的果子，必享美福；奸诈人必遭强暴。","notes":[]},{"n":3,"t":"谨守口的，得保生命；大张嘴的，必致败亡。","notes":[]},{"n":4,"t":"懒惰人羡慕，却无所得；殷勤人必得丰裕。","notes":[]},{"n":5,"t":"义人恨恶谎言；恶人有臭名，且致惭愧。","notes":[]},{"n":6,"t":"行为正直的，有公义保守；犯罪的，被邪恶倾覆。","notes":[]},{"n":7,"t":"假作富足的，却一无所有；装作穷乏的，却广有财物。","notes":[]},{"n":8,"t":"人的资财是他生命的赎价；穷乏人却听不见威吓的话。","notes":[]},{"n":9,"t":"义人的光明亮；恶人的灯要熄灭。","notes":["原文是欢喜"]},{"n":10,"t":"骄傲只启争竞；听劝言的，却有智慧。","notes":[]},{"n":11,"t":"不劳而得之财必然消耗；勤劳积蓄的，必见加增。","notes":[]},{"n":12,"t":"所盼望的迟延未得，令人心忧；所愿意的临到，却是生命树。","notes":[]},{"n":13,"t":"藐视训言的，自取灭亡；敬畏诫命的，必得善报。","notes":[]},{"n":14,"t":"智慧人的法则是生命的泉源，可以使人离开死亡的网罗。","notes":["或译：指教"]},{"n":15,"t":"美好的聪明使人蒙恩；奸诈人的道路崎岖难行。","notes":[]},{"n":16,"t":"凡通达人都凭知识行事；愚昧人张扬自己的愚昧。","notes":[]},{"n":17,"t":"奸恶的使者必陷在祸患里；忠信的使臣乃医人的良药。","notes":[]},{"n":18,"t":"弃绝管教的，必致贫受辱；领受责备的，必得尊荣。","notes":[]},{"n":19,"t":"所欲的成就，心觉甘甜；远离恶事，为愚昧人所憎恶。","notes":[]},{"n":20,"t":"与智慧人同行的，必得智慧；和愚昧人作伴的，必受亏损。","notes":[]},{"n":21,"t":"祸患追赶罪人；义人必得善报。","notes":[]},{"n":22,"t":"善人给子孙遗留产业；罪人为义人积存资财。","notes":[]},{"n":23,"t":"穷人耕种多得粮食，但因不义，有消灭的。","notes":[]},{"n":24,"t":"不忍用杖打儿子的，是恨恶他；疼爱儿子的，随时管教。","notes":[]},{"n":25,"t":"义人吃得饱足；恶人肚腹缺粮。","notes":[]}]},"14":{"heading":"","verses":[{"n":1,"t":"智慧妇人建立家室；愚妄妇人亲手拆毁。","notes":[]},{"n":2,"t":"行动正直的，敬畏耶和华；行事乖僻的，却藐视他。","notes":[]},{"n":3,"t":"愚妄人口中骄傲，如杖责打己身；智慧人的嘴必保守自己。","notes":[]},{"n":4,"t":"家里无牛，槽头干净；土产加多乃凭牛力。","notes":[]},{"n":5,"t":"诚实见证人不说谎话；假见证人吐出谎言。","notes":[]},{"n":6,"t":"亵慢人寻智慧，却寻不着；聪明人易得知识。","notes":[]},{"n":7,"t":"到愚昧人面前，不见他嘴中有知识。","notes":[]},{"n":8,"t":"通达人的智慧在乎明白己道；愚昧人的愚妄乃是诡诈。","notes":["或译：自叹"]},{"n":9,"t":"愚妄人犯罪，以为戏耍；正直人互相喜悦。","notes":["或译：赎愆祭愚弄愚妄人"]},{"n":10,"t":"心中的苦楚，自己知道；心里的喜乐，外人无干。","notes":[]},{"n":11,"t":"奸恶人的房屋必倾倒；正直人的帐棚必兴盛。","notes":[]},{"n":12,"t":"有一条路，人以为正，至终成为死亡之路。","notes":[]},{"n":13,"t":"人在喜笑中，心也忧愁；快乐至极就生愁苦。","notes":[]},{"n":14,"t":"心中背道的，必满得自己的结果；善人必从自己的行为得以知足。","notes":[]},{"n":15,"t":"愚蒙人是话都信；通达人步步谨慎。","notes":[]},{"n":16,"t":"智慧人惧怕，就远离恶事；愚妄人却狂傲自恃。","notes":[]},{"n":17,"t":"轻易发怒的，行事愚妄；设立诡计的，被人恨恶。","notes":[]},{"n":18,"t":"愚蒙人得愚昧为产业；通达人得知识为冠冕。","notes":[]},{"n":19,"t":"坏人俯伏在善人面前；恶人俯伏在义人门口。","notes":[]},{"n":20,"t":"贫穷人连邻舍也恨他；富足人朋友最多。","notes":[]},{"n":21,"t":"藐视邻舍的，这人有罪；怜悯贫穷的，这人有福。","notes":[]},{"n":22,"t":"谋恶的，岂非走入迷途吗？谋善的，必得慈爱和诚实。","notes":[]},{"n":23,"t":"诸般勤劳都有益处；嘴上多言乃致穷乏。","notes":[]},{"n":24,"t":"智慧人的财为自己的冠冕；愚妄人的愚昧终是愚昧。","notes":[]},{"n":25,"t":"作真见证的，救人性命；吐出谎言的，施行诡诈。","notes":[]},{"n":26,"t":"敬畏耶和华的，大有倚靠；他的儿女也有避难所。","notes":[]},{"n":27,"t":"敬畏耶和华就是生命的泉源，可以使人离开死亡的网罗。","notes":[]},{"n":28,"t":"帝王荣耀在乎民多；君王衰败在乎民少。","notes":[]},{"n":29,"t":"不轻易发怒的，大有聪明；性情暴躁的，大显愚妄。","notes":[]},{"n":30,"t":"心中安静是肉体的生命；嫉妒是骨中的朽烂。","notes":[]},{"n":31,"t":"欺压贫寒的，是辱没造他的主；怜悯穷乏的，乃是尊敬主。","notes":[]},{"n":32,"t":"恶人在所行的恶上必被推倒；义人临死，有所投靠。","notes":[]},{"n":33,"t":"智慧存在聪明人心中；愚昧人心里所存的，显而易见。","notes":[]},{"n":34,"t":"公义使邦国高举；罪恶是人民的羞辱。","notes":[]},{"n":35,"t":"智慧的臣子蒙王恩惠；贻羞的仆人遭其震怒。","notes":[]}]},"15":{"heading":"","verses":[{"n":1,"t":"回答柔和，使怒消退；言语暴戾，触动怒气。","notes":[]},{"n":2,"t":"智慧人的舌善发知识；愚昧人的口吐出愚昧。","notes":[]},{"n":3,"t":"耶和华的眼目无处不在；恶人善人，他都鉴察。","notes":[]},{"n":4,"t":"温良的舌是生命树；乖谬的嘴使人心碎。","notes":[]},{"n":5,"t":"愚妄人藐视父亲的管教；领受责备的，得着见识。","notes":[]},{"n":6,"t":"义人家中多有财宝；恶人得利反受扰害。","notes":[]},{"n":7,"t":"智慧人的嘴播扬知识；愚昧人的心并不如此。","notes":[]},{"n":8,"t":"恶人献祭，为耶和华所憎恶；正直人祈祷，为他所喜悦。","notes":[]},{"n":9,"t":"恶人的道路，为耶和华所憎恶；追求公义的，为他所喜爱。","notes":[]},{"n":10,"t":"舍弃正路的，必受严刑；恨恶责备的，必致死亡。","notes":[]},{"n":11,"t":"阴间和灭亡尚在耶和华眼前，何况世人的心呢？","notes":[]},{"n":12,"t":"亵慢人不爱受责备；他也不就近智慧人。","notes":[]},{"n":13,"t":"心中喜乐，面带笑容；心里忧愁，灵被损伤。","notes":[]},{"n":14,"t":"聪明人心求知识；愚昧人口吃愚昧。","notes":[]},{"n":15,"t":"困苦人的日子都是愁苦；心中欢畅的，常享丰筵。","notes":[]},{"n":16,"t":"少有财宝，敬畏耶和华，强如多有财宝，烦乱不安。","notes":[]},{"n":17,"t":"吃素菜，彼此相爱，强如吃肥牛，彼此相恨。","notes":[]},{"n":18,"t":"暴怒的人挑启争端；忍怒的人止息纷争。","notes":[]},{"n":19,"t":"懒惰人的道像荆棘的篱笆；正直人的路是平坦的大道。","notes":[]},{"n":20,"t":"智慧子使父亲喜乐；愚昧人藐视母亲。","notes":[]},{"n":21,"t":"无知的人以愚妄为乐；聪明的人按正直而行。","notes":[]},{"n":22,"t":"不先商议，所谋无效；谋士众多，所谋乃成。","notes":[]},{"n":23,"t":"口善应对，自觉喜乐；话合其时，何等美好。","notes":[]},{"n":24,"t":"智慧人从生命的道上升，使他远离在下的阴间。","notes":[]},{"n":25,"t":"耶和华必拆毁骄傲人的家，却要立定寡妇的地界。","notes":[]},{"n":26,"t":"恶谋为耶和华所憎恶；良言乃为纯净。","notes":[]},{"n":27,"t":"贪恋财利的，扰害己家；恨恶贿赂的，必得存活。","notes":[]},{"n":28,"t":"义人的心，思量如何回答；恶人的口吐出恶言。","notes":[]},{"n":29,"t":"耶和华远离恶人，却听义人的祷告。","notes":[]},{"n":30,"t":"眼有光，使心喜乐；好信息，使骨滋润。","notes":[]},{"n":31,"t":"听从生命责备的，必常在智慧人中。","notes":[]},{"n":32,"t":"弃绝管教的，轻看自己的生命；听从责备的，却得智慧。","notes":[]},{"n":33,"t":"敬畏耶和华是智慧的训诲；尊荣以前，必有谦卑。","notes":[]}]},"16":{"heading":"","verses":[{"n":1,"t":"心中的谋算在乎人；舌头的应对由于耶和华。","notes":[]},{"n":2,"t":"人一切所行的，在自己眼中看为清洁；惟有耶和华衡量人心。","notes":[]},{"n":3,"t":"你所做的，要交托耶和华，你所谋的，就必成立。","notes":[]},{"n":4,"t":"耶和华所造的，各适其用；就是恶人也为祸患的日子所造。","notes":[]},{"n":5,"t":"凡心里骄傲的，为耶和华所憎恶；虽然连手，他必不免受罚。","notes":[]},{"n":6,"t":"因怜悯诚实，罪孽得赎；敬畏耶和华的，远离恶事。","notes":[]},{"n":7,"t":"人所行的，若蒙耶和华喜悦，耶和华也使他的仇敌与他和好。","notes":[]},{"n":8,"t":"多有财利，行事不义，不如少有财利，行事公义。","notes":[]},{"n":9,"t":"人心筹算自己的道路；惟耶和华指引他的脚步。","notes":[]},{"n":10,"t":"王的嘴中有神语，审判之时，他的口必不差错。","notes":[]},{"n":11,"t":"公道的天平和秤都属耶和华；囊中一切法码都为他所定。","notes":[]},{"n":12,"t":"作恶，为王所憎恶，因国位是靠公义坚立。","notes":[]},{"n":13,"t":"公义的嘴为王所喜悦；说正直话的，为王所喜爱。","notes":[]},{"n":14,"t":"王的震怒如杀人的使者；但智慧人能止息王怒。","notes":[]},{"n":15,"t":"王的脸光使人有生命；王的恩典好像春云时雨。","notes":[]},{"n":16,"t":"得智慧胜似得金子；选聪明强如选银子。","notes":[]},{"n":17,"t":"正直人的道是远离恶事；谨守己路的，是保全性命。","notes":[]},{"n":18,"t":"骄傲在败坏以先；狂心在跌倒之前。","notes":[]},{"n":19,"t":"心里谦卑与穷乏人来往，强如将掳物与骄傲人同分。","notes":[]},{"n":20,"t":"谨守训言的，必得好处；倚靠耶和华的，便为有福。","notes":[]},{"n":21,"t":"心中有智慧，必称为通达人；嘴中的甜言，加增人的学问。","notes":[]},{"n":22,"t":"人有智慧就有生命的泉源；愚昧人必被愚昧惩治。","notes":[]},{"n":23,"t":"智慧人的心教训他的口，又使他的嘴增长学问。","notes":[]},{"n":24,"t":"良言如同蜂房，使心觉甘甜，使骨得医治。","notes":[]},{"n":25,"t":"有一条路，人以为正，至终成为死亡之路。","notes":[]},{"n":26,"t":"劳力人的胃口使他劳力，因为他的口腹催逼他。","notes":[]},{"n":27,"t":"匪徒图谋奸恶，嘴上仿佛有烧焦的火。","notes":[]},{"n":28,"t":"乖僻人播散纷争；传舌的，离间密友。","notes":[]},{"n":29,"t":"强暴人诱惑邻舍，领他走不善之道。","notes":[]},{"n":30,"t":"眼目紧合的，图谋乖僻；嘴唇紧闭的，成就邪恶。","notes":[]},{"n":31,"t":"白发是荣耀的冠冕，在公义的道上必能得着。","notes":[]},{"n":32,"t":"不轻易发怒的，胜过勇士；治服己心的，强如取城。","notes":[]},{"n":33,"t":"签放在怀里，定事由耶和华。","notes":[]}]},"17":{"heading":"","verses":[{"n":1,"t":"设筵满屋，大家相争，不如有块干饼，大家相安。","notes":[]},{"n":2,"t":"仆人办事聪明，必管辖贻羞之子，又在众子中同分产业。","notes":[]},{"n":3,"t":"鼎为炼银，炉为炼金；惟有耶和华熬炼人心。","notes":[]},{"n":4,"t":"行恶的，留心听奸诈之言；说谎的，侧耳听邪恶之语。","notes":[]},{"n":5,"t":"戏笑穷人的，是辱没造他的主；幸灾乐祸的，必不免受罚。","notes":[]},{"n":6,"t":"子孙为老人的冠冕；父亲是儿女的荣耀。","notes":[]},{"n":7,"t":"愚顽人说美言本不相宜，何况君王说谎话呢？","notes":[]},{"n":8,"t":"贿赂在馈送的人眼中看为宝玉，随处运动都得顺利。","notes":[]},{"n":9,"t":"遮掩人过的，寻求人爱；屡次挑错的，离间密友。","notes":[]},{"n":10,"t":"一句责备话深入聪明人的心，强如责打愚昧人一百下。","notes":[]},{"n":11,"t":"恶人只寻背叛，所以必有严厉的使者奉差攻击他。","notes":[]},{"n":12,"t":"宁可遇见丢崽子的母熊，不可遇见正行愚妄的愚昧人。","notes":[]},{"n":13,"t":"以恶报善的，祸患必不离他的家。","notes":[]},{"n":14,"t":"纷争的起头如水放开，所以，在争闹之先必当止息争竞。","notes":[]},{"n":15,"t":"定恶人为义的，定义人为恶的，这都为耶和华所憎恶。","notes":[]},{"n":16,"t":"愚昧人既无聪明，为何手拿价银买智慧呢？","notes":[]},{"n":17,"t":"朋友乃时常亲爱，弟兄为患难而生。","notes":[]},{"n":18,"t":"在邻舍面前击掌作保乃是无知的人。","notes":[]},{"n":19,"t":"喜爱争竞的，是喜爱过犯；高立家门的，乃自取败坏。","notes":[]},{"n":20,"t":"心存邪僻的，寻不着好处；舌弄是非的，陷在祸患中。","notes":[]},{"n":21,"t":"生愚昧子的，必自愁苦；愚顽人的父毫无喜乐。","notes":[]},{"n":22,"t":"喜乐的心乃是良药；忧伤的灵使骨枯干。","notes":[]},{"n":23,"t":"恶人暗中受贿赂，为要颠倒判断。","notes":[]},{"n":24,"t":"明哲人眼前有智慧；愚昧人眼望地极。","notes":[]},{"n":25,"t":"愚昧子使父亲愁烦，使母亲忧苦。","notes":[]},{"n":26,"t":"刑罚义人为不善；责打君子为不义。","notes":[]},{"n":27,"t":"寡少言语的，有知识；性情温良的，有聪明。","notes":[]},{"n":28,"t":"愚昧人若静默不言也可算为智慧；闭口不说也可算为聪明。","notes":[]}]},"18":{"heading":"","verses":[{"n":1,"t":"与众寡合的，独自寻求心愿，并恼恨一切真智慧。","notes":[]},{"n":2,"t":"愚昧人不喜爱明哲，只喜爱显露心意。","notes":[]},{"n":3,"t":"恶人来，藐视随来；羞耻到，辱骂同到。","notes":[]},{"n":4,"t":"人口中的言语如同深水；智慧的泉源好像涌流的河水。","notes":[]},{"n":5,"t":"瞻徇恶人的情面，偏断义人的案件，都为不善。","notes":[]},{"n":6,"t":"愚昧人张嘴启争端，开口招鞭打。","notes":[]},{"n":7,"t":"愚昧人的口自取败坏；他的嘴是他生命的网罗。","notes":[]},{"n":8,"t":"传舌人的言语如同美食，深入人的心腹。","notes":[]},{"n":9,"t":"做工懈怠的，与浪费人为弟兄。","notes":[]},{"n":10,"t":"耶和华的名是坚固台；义人奔入便得安稳。","notes":[]},{"n":11,"t":"富足人的财物是他的坚城，在他心想，犹如高墙。","notes":[]},{"n":12,"t":"败坏之先，人心骄傲；尊荣以前，必有谦卑。","notes":[]},{"n":13,"t":"未曾听完先回答的，便是他的愚昧和羞辱。","notes":[]},{"n":14,"t":"人有疾病，心能忍耐；心灵忧伤，谁能承当呢？","notes":[]},{"n":15,"t":"聪明人的心得知识；智慧人的耳求知识。","notes":[]},{"n":16,"t":"人的礼物为他开路，引他到高位的人面前。","notes":[]},{"n":17,"t":"先诉情由的，似乎有理；但邻舍来到，就察出实情。","notes":[]},{"n":18,"t":"掣签能止息争竞，也能解散强胜的人。","notes":[]},{"n":19,"t":"弟兄结怨，劝他和好，比取坚固城还难；这样的争竞如同坚寨的门闩。","notes":[]},{"n":20,"t":"人口中所结的果子，必充满肚腹；他嘴所出的，必使他饱足。","notes":[]},{"n":21,"t":"生死在舌头的权下，喜爱它的，必吃它所结的果子。","notes":[]},{"n":22,"t":"得着贤妻的，是得着好处，也是蒙了耶和华的恩惠。","notes":[]},{"n":23,"t":"贫穷人说哀求的话；富足人用威吓的话回答。","notes":[]},{"n":24,"t":"滥交朋友的，自取败坏；但有一朋友比弟兄更亲密。","notes":[]}]},"19":{"heading":"","verses":[{"n":1,"t":"行为纯正的贫穷人胜过乖谬愚妄的富足人。","notes":[]},{"n":2,"t":"心无知识的，乃为不善；脚步急快的，难免犯罪。","notes":[]},{"n":3,"t":"人的愚昧倾败他的道；他的心也抱怨耶和华。","notes":[]},{"n":4,"t":"财物使朋友增多；但穷人朋友远离。","notes":[]},{"n":5,"t":"作假见证的，必不免受罚；吐出谎言的，终不能逃脱。","notes":[]},{"n":6,"t":"好施散的，有多人求他的恩情；爱送礼的，人都为他的朋友。","notes":[]},{"n":7,"t":"贫穷人，弟兄都恨他；何况他的朋友，更远离他！他用言语追随，他们却走了。","notes":[]},{"n":8,"t":"得着智慧的，爱惜生命；保守聪明的，必得好处。","notes":[]},{"n":9,"t":"作假见证的，不免受罚；吐出谎言的，也必灭亡。","notes":[]},{"n":10,"t":"愚昧人宴乐度日是不合宜的；何况仆人管辖王子呢？","notes":[]},{"n":11,"t":"人有见识就不轻易发怒；宽恕人的过失便是自己的荣耀。","notes":[]},{"n":12,"t":"王的忿怒好像狮子吼叫；他的恩典却如草上的甘露。","notes":[]},{"n":13,"t":"愚昧的儿子是父亲的祸患；妻子的争吵如雨连连滴漏。","notes":[]},{"n":14,"t":"房屋钱财是祖宗所遗留的；惟有贤慧的妻是耶和华所赐的。","notes":[]},{"n":15,"t":"懒惰使人沉睡；懈怠的人必受饥饿。","notes":[]},{"n":16,"t":"谨守诫命的，保全生命；轻忽己路的，必致死亡。","notes":[]},{"n":17,"t":"怜悯贫穷的，就是借给耶和华；他的善行，耶和华必偿还。","notes":[]},{"n":18,"t":"趁有指望，管教你的儿子；你的心不可任他死亡。","notes":[]},{"n":19,"t":"暴怒的人必受刑罚；你若救他，必须再救。","notes":[]},{"n":20,"t":"你要听劝教，受训诲，使你终久有智慧。","notes":[]},{"n":21,"t":"人心多有计谋；惟有耶和华的筹算才能立定。","notes":[]},{"n":22,"t":"施行仁慈的，令人爱慕；穷人强如说谎言的。","notes":[]},{"n":23,"t":"敬畏耶和华的，得着生命；他必恒久知足，不遭祸患。","notes":[]},{"n":24,"t":"懒惰人放手在盘子里，就是向口撤回，他也不肯。","notes":[]},{"n":25,"t":"鞭打亵慢人，愚蒙人必长见识；责备明哲人，他就明白知识。","notes":[]},{"n":26,"t":"虐待父亲、撵出母亲的，是贻羞致辱之子。","notes":[]},{"n":27,"t":"我儿，不可听了教训而又偏离知识的言语。","notes":[]},{"n":28,"t":"匪徒作见证戏笑公平；恶人的口吞下罪孽。","notes":[]},{"n":29,"t":"刑罚是为亵慢人预备的；鞭打是为愚昧人的背预备的。","notes":[]}]},"20":{"heading":"","verses":[{"n":1,"t":"酒能使人亵慢，浓酒使人喧嚷；凡因酒错误的，就无智慧。","notes":[]},{"n":2,"t":"王的威吓如同狮子吼叫；惹动他怒的，是自害己命。","notes":[]},{"n":3,"t":"远离纷争是人的尊荣；愚妄人都爱争闹。","notes":[]},{"n":4,"t":"懒惰人因冬寒不肯耕种，到收割的时候，他必讨饭而无所得。","notes":[]},{"n":5,"t":"人心怀藏谋略，好像深水，惟明哲人才能汲引出来。","notes":[]},{"n":6,"t":"人多述说自己的仁慈，但忠信人谁能遇着呢？","notes":[]},{"n":7,"t":"行为纯正的义人，他的子孙是有福的！","notes":[]},{"n":8,"t":"王坐在审判的位上，以眼目驱散诸恶。","notes":[]},{"n":9,"t":"谁能说，我洁净了我的心，我脱净了我的罪？","notes":[]},{"n":10,"t":"两样的法码，两样的升斗，都为耶和华所憎恶。","notes":[]},{"n":11,"t":"孩童的动作是清洁，是正直，都显明他的本性。","notes":[]},{"n":12,"t":"能听的耳，能看的眼，都是耶和华所造的。","notes":[]},{"n":13,"t":"不要贪睡，免致贫穷；眼要睁开，你就吃饱。","notes":[]},{"n":14,"t":"买物的说：不好，不好；及至买去，他便自夸。","notes":[]},{"n":15,"t":"有金子和许多珍珠，惟有知识的嘴乃为贵重的珍宝。","notes":["或译：红宝石"]},{"n":16,"t":"谁为生人作保，就拿谁的衣服；谁为外人作保，谁就要承当。","notes":[]},{"n":17,"t":"以虚谎而得的食物，人觉甘甜；但后来，他的口必充满尘沙。","notes":[]},{"n":18,"t":"计谋都凭筹算立定；打仗要凭智谋。","notes":[]},{"n":19,"t":"往来传舌的，泄漏密事；大张嘴的，不可与他结交。","notes":[]},{"n":20,"t":"咒骂父母的，他的灯必灭，变为漆黑的黑暗。","notes":[]},{"n":21,"t":"起初速得的产业，终久却不为福。","notes":[]},{"n":22,"t":"你不要说，我要以恶报恶；要等候耶和华，他必拯救你。","notes":[]},{"n":23,"t":"两样的法码为耶和华所憎恶；诡诈的天平也为不善。","notes":[]},{"n":24,"t":"人的脚步为耶和华所定；人岂能明白自己的路呢？","notes":[]},{"n":25,"t":"人冒失说，这是圣物，许愿之后才查问，就是自陷网罗。","notes":[]},{"n":26,"t":"智慧的王簸散恶人，用碌碡滚轧他们。","notes":[]},{"n":27,"t":"人的灵是耶和华的灯，鉴察人的心腹。","notes":[]},{"n":28,"t":"王因仁慈和诚实得以保全他的国位，也因仁慈立稳。","notes":[]},{"n":29,"t":"强壮乃少年人的荣耀；白发为老年人的尊荣。","notes":[]},{"n":30,"t":"鞭伤除净人的罪恶；责打能入人的心腹。","notes":[]}]},"21":{"heading":"","verses":[{"n":1,"t":"王的心在耶和华手中，好像陇沟的水随意流转。","notes":[]},{"n":2,"t":"人所行的，在自己眼中都看为正；惟有耶和华衡量人心。","notes":[]},{"n":3,"t":"行仁义公平比献祭更蒙耶和华悦纳。","notes":[]},{"n":4,"t":"恶人发达，眼高心傲，这乃是罪。","notes":["发达：原文是灯"]},{"n":5,"t":"殷勤筹划的，足致丰裕；行事急躁的，都必缺乏。","notes":[]},{"n":6,"t":"用诡诈之舌求财的，就是自己取死；所得之财乃是吹来吹去的浮云。","notes":[]},{"n":7,"t":"恶人的强暴必将自己扫除，因他们不肯按公平行事。","notes":[]},{"n":8,"t":"负罪之人的路甚是弯曲；至于清洁的人，他所行的乃是正直。","notes":[]},{"n":9,"t":"宁可住在房顶的角上，不在宽阔的房屋与争吵的妇人同住。","notes":[]},{"n":10,"t":"恶人的心乐人受祸；他眼并不怜恤邻舍。","notes":[]},{"n":11,"t":"亵慢的人受刑罚，愚蒙的人就得智慧；智慧人受训诲，便得知识。","notes":[]},{"n":12,"t":"义人思想恶人的家，知道恶人倾倒，必致灭亡。","notes":[]},{"n":13,"t":"塞耳不听穷人哀求的，他将来呼吁也不蒙应允。","notes":[]},{"n":14,"t":"暗中送的礼物挽回怒气；怀中搋的贿赂止息暴怒。","notes":[]},{"n":15,"t":"秉公行义使义人喜乐，使作孽的人败坏。","notes":[]},{"n":16,"t":"迷离通达道路的，必住在阴魂的会中。","notes":[]},{"n":17,"t":"爱宴乐的，必致穷乏；好酒，爱膏油的，必不富足。","notes":[]},{"n":18,"t":"恶人作了义人的赎价；奸诈人代替正直人。","notes":[]},{"n":19,"t":"宁可住在旷野，不与争吵使气的妇人同住。","notes":[]},{"n":20,"t":"智慧人家中积蓄宝物膏油；愚昧人随得来随吞下。","notes":[]},{"n":21,"t":"追求公义仁慈的，就寻得生命、公义，和尊荣。","notes":[]},{"n":22,"t":"智慧人爬上勇士的城墙，倾覆他所倚靠的坚垒。","notes":[]},{"n":23,"t":"谨守口与舌的，就保守自己免受灾难。","notes":[]},{"n":24,"t":"心骄气傲的人名叫亵慢；他行事狂妄，都出于骄傲。","notes":[]},{"n":25,"t":"懒惰人的心愿将他杀害，因为他手不肯做工。","notes":[]},{"n":26,"t":"有终日贪得无厌的；义人施舍而不吝惜。","notes":[]},{"n":27,"t":"恶人的祭物是可憎的；何况他存恶意来献呢？","notes":[]},{"n":28,"t":"作假见证的必灭亡；惟有听真情而言的，其言长存。","notes":[]},{"n":29,"t":"恶人脸无羞耻；正直人行事坚定。","notes":[]},{"n":30,"t":"没有人能以智慧、聪明、谋略敌挡耶和华。","notes":[]},{"n":31,"t":"马是为打仗之日预备的；得胜乃在乎耶和华。","notes":[]}]},"22":{"heading":"智言三十则","verses":[{"n":1,"t":"美名胜过大财；恩宠强如金银。","notes":[]},{"n":2,"t":"富户穷人在世相遇，都为耶和华所造。","notes":[]},{"n":3,"t":"通达人见祸藏躲；愚蒙人前往受害。","notes":[]},{"n":4,"t":"敬畏耶和华心存谦卑，就得富有、尊荣、生命为赏赐。","notes":[]},{"n":5,"t":"乖僻人的路上有荆棘和网罗；保守自己生命的，必要远离。","notes":[]},{"n":6,"t":"教养孩童，使他走当行的道，就是到老他也不偏离。","notes":[]},{"n":7,"t":"富户管辖穷人；欠债的是债主的仆人。","notes":[]},{"n":8,"t":"撒罪孽的，必收灾祸；他逞怒的杖也必废掉。","notes":[]},{"n":9,"t":"眼目慈善的，就必蒙福，因他将食物分给穷人。","notes":[]},{"n":10,"t":"赶出亵慢人，争端就消除；纷争和羞辱也必止息。","notes":[]},{"n":11,"t":"喜爱清心的人因他嘴上的恩言，王必与他为友。","notes":[]},{"n":12,"t":"耶和华的眼目眷顾聪明人，却倾败奸诈人的言语。","notes":[]},{"n":13,"t":"懒惰人说：外头有狮子；我在街上就必被杀。","notes":[]},{"n":14,"t":"淫妇的口为深坑；耶和华所憎恶的，必陷在其中。","notes":[]},{"n":15,"t":"愚蒙迷住孩童的心，用管教的杖可以远远赶除。","notes":[]},{"n":16,"t":"欺压贫穷为要利己的，并送礼与富户的，都必缺乏。","notes":[]},{"n":17,"t":"你须侧耳听受智慧人的言语，留心领会我的知识。","notes":[]},{"n":18,"t":"你若心中存记，嘴上咬定，这便为美。","notes":[]},{"n":19,"t":"我今日以此特特指教你，为要使你倚靠耶和华。","notes":[]},{"n":20,"t":"谋略和知识的美事，我岂没有写给你吗？","notes":[]},{"n":21,"t":"要使你知道真言的实理，你好将真言回复那打发你来的人。","notes":[]},{"n":22,"t":"贫穷人，你不可因他贫穷就抢夺他的物，也不可在城门口欺压困苦人；","notes":[]},{"n":23,"t":"因耶和华必为他辨屈；抢夺他的，耶和华必夺取那人的命。","notes":[]},{"n":24,"t":"好生气的人，不可与他结交；暴怒的人，不可与他来往；","notes":[]},{"n":25,"t":"恐怕你效法他的行为，自己就陷在网罗里。","notes":[]},{"n":26,"t":"不要与人击掌，不要为欠债的作保。","notes":[]},{"n":27,"t":"你若没有什么偿还，何必使人夺去你睡卧的床呢？","notes":[]},{"n":28,"t":"你先祖所立的地界，你不可挪移。","notes":[]},{"n":29,"t":"你看见办事殷勤的人吗？他必站在君王面前，必不站在下贱人面前。","notes":[]}]},"23":{"heading":"","verses":[{"n":1,"t":"你若与官长坐席，要留意在你面前的是谁。","notes":[]},{"n":2,"t":"你若是贪食的，就当拿刀放在喉咙上。","notes":[]},{"n":3,"t":"不可贪恋他的美食，因为是哄人的食物。","notes":[]},{"n":4,"t":"不要劳碌求富，休仗自己的聪明。","notes":[]},{"n":5,"t":"你岂要定睛在虚无的钱财上吗？因钱财必长翅膀，如鹰向天飞去。","notes":[]},{"n":6,"t":"不要吃恶眼人的饭，也不要贪他的美味；","notes":[]},{"n":7,"t":"因为他心怎样思量，他为人就是怎样。他虽对你说，请吃，请喝，他的心却与你相背。","notes":[]},{"n":8,"t":"你所吃的那点食物必吐出来；你所说的甘美言语也必落空。","notes":[]},{"n":9,"t":"你不要说话给愚昧人听，因他必藐视你智慧的言语。","notes":[]},{"n":10,"t":"不可挪移古时的地界，也不可侵入孤儿的田地；","notes":[]},{"n":11,"t":"因他们的救赎主大有能力，他必向你为他们辨屈。","notes":[]},{"n":12,"t":"你要留心领受训诲，侧耳听从知识的言语。","notes":[]},{"n":13,"t":"不可不管教孩童；你用杖打他，他必不至于死。","notes":[]},{"n":14,"t":"你要用杖打他，就可以救他的灵魂免下阴间。","notes":[]},{"n":15,"t":"我儿，你心若存智慧，我的心也甚欢喜。","notes":[]},{"n":16,"t":"你的嘴若说正直话，我的心肠也必快乐。","notes":[]},{"n":17,"t":"你心中不要嫉妒罪人，只要终日敬畏耶和华；","notes":[]},{"n":18,"t":"因为至终必有善报，你的指望也不致断绝。","notes":[]},{"n":19,"t":"我儿，你当听，当存智慧，好在正道上引导你的心。","notes":[]},{"n":20,"t":"好饮酒的，好吃肉的，不要与他们来往；","notes":[]},{"n":21,"t":"因为好酒贪食的，必致贫穷；好睡觉的，必穿破烂衣服。","notes":[]},{"n":22,"t":"你要听从生你的父亲；你母亲老了，也不可藐视她。","notes":[]},{"n":23,"t":"你当买真理；就是智慧、训诲，和聪明也都不可卖。","notes":[]},{"n":24,"t":"义人的父亲必大得快乐；人生智慧的儿子，必因他欢喜。","notes":[]},{"n":25,"t":"你要使父母欢喜，使生你的快乐。","notes":[]},{"n":26,"t":"我儿，要将你的心归我；你的眼目也要喜悦我的道路。","notes":[]},{"n":27,"t":"妓女是深坑；外女是窄阱。","notes":[]},{"n":28,"t":"她埋伏好像强盗；她使人中多有奸诈的。","notes":[]},{"n":29,"t":"谁有祸患？谁有忧愁？谁有争斗？谁有哀叹？谁无故受伤？谁眼目红赤？","notes":["或译：怨言"]},{"n":30,"t":"就是那流连饮酒、常去寻找调和酒的人。","notes":[]},{"n":31,"t":"酒发红，在杯中闪烁，你不可观看，虽然下咽舒畅，终久是咬你如蛇，刺你如毒蛇。","notes":[],"end":32},{"n":33,"t":"你眼必看见异怪的事；你心必发出乖谬的话。","notes":["或译：淫妇"]},{"n":34,"t":"你必像躺在海中，或像卧在桅杆上。","notes":[]},{"n":35,"t":"你必说：人打我，我却未受伤；人鞭打我，我竟不觉得。我几时清醒，我仍去寻酒。","notes":[]}]},"24":{"heading":"其他智言","verses":[{"n":1,"t":"你不要嫉妒恶人，也不要起意与他们相处；","notes":[]},{"n":2,"t":"因为，他们的心图谋强暴，他们的口谈论奸恶。","notes":[]},{"n":3,"t":"房屋因智慧建造，又因聪明立稳；","notes":[]},{"n":4,"t":"其中因知识充满各样美好宝贵的财物。","notes":[]},{"n":5,"t":"智慧人大有能力；有知识的人力上加力。","notes":[]},{"n":6,"t":"你去打仗，要凭智谋；谋士众多，人便得胜。","notes":[]},{"n":7,"t":"智慧极高，非愚昧人所能及，所以在城门内不敢开口。","notes":[]},{"n":8,"t":"设计作恶的，必称为奸人。","notes":[]},{"n":9,"t":"愚妄人的思念乃是罪恶；亵慢者为人所憎恶。","notes":[]},{"n":10,"t":"你在患难之日若胆怯，你的力量就微小。","notes":[]},{"n":11,"t":"人被拉到死地，你要解救；人将被杀，你须拦阻。","notes":[]},{"n":12,"t":"你若说：这事我未曾知道，那衡量人心的岂不明白吗？保守你命的岂不知道吗？他岂不按各人所行的报应各人吗？","notes":[]},{"n":13,"t":"我儿，你要吃蜜，因为是好的；吃蜂房下滴的蜜便觉甘甜。","notes":[]},{"n":14,"t":"你心得了智慧，也必觉得如此。你若找着，至终必有善报；你的指望也不致断绝。","notes":[]},{"n":15,"t":"你这恶人，不要埋伏攻击义人的家；不要毁坏他安居之所。","notes":[]},{"n":16,"t":"因为，义人虽七次跌倒，仍必兴起；恶人却被祸患倾倒。","notes":[]},{"n":17,"t":"你仇敌跌倒，你不要欢喜；他倾倒，你心不要快乐；","notes":[]},{"n":18,"t":"恐怕耶和华看见就不喜悦，将怒气从仇敌身上转过来。","notes":[]},{"n":19,"t":"不要为作恶的心怀不平，也不要嫉妒恶人；","notes":[]},{"n":20,"t":"因为，恶人终不得善报；恶人的灯也必熄灭。","notes":[]},{"n":21,"t":"我儿，你要敬畏耶和华与君王，不要与反复无常的人结交，","notes":[]},{"n":22,"t":"因为他们的灾难必忽然而起。耶和华与君王所施行的毁灭，谁能知道呢？","notes":[]},{"n":23,"t":"以下也是智慧人的箴言：审判时看人情面是不好的。","notes":[]},{"n":24,"t":"对恶人说「你是义人」的，这人万民必咒诅，列邦必憎恶。","notes":[]},{"n":25,"t":"责备恶人的，必得喜悦；美好的福也必临到他。","notes":[]},{"n":26,"t":"应对正直的，犹如与人亲嘴。","notes":[]},{"n":27,"t":"你要在外头预备工料，在田间办理整齐，然后建造房屋。","notes":[]},{"n":28,"t":"不可无故作见证陷害邻舍，也不可用嘴欺骗人。","notes":[]},{"n":29,"t":"不可说：人怎样待我，我也怎样待他；我必照他所行的报复他。","notes":[]},{"n":30,"t":"我经过懒惰人的田地、无知人的葡萄园，","notes":[]},{"n":31,"t":"荆棘长满了地皮，刺草遮盖了田面，石墙也坍塌了。","notes":[]},{"n":32,"t":"我看见就留心思想；我看着就领了训诲。","notes":[]},{"n":33,"t":"再睡片时，打盹片时，抱着手躺卧片时，","notes":[]},{"n":34,"t":"你的贫穷就必如强盗速来，你的缺乏仿佛拿兵器的人来到。","notes":[]}]},"25":{"heading":"所罗门的另一些箴言","verses":[{"n":1,"t":"以下也是所罗门的箴言，是犹大王希西家的人所誊录的。","notes":[]},{"n":2,"t":"将事隐秘乃神的荣耀；将事察清乃君王的荣耀。","notes":[]},{"n":3,"t":"天之高，地之厚，君王之心也测不透。","notes":[]},{"n":4,"t":"除去银子的渣滓就有银子出来，银匠能以做器皿。","notes":[]},{"n":5,"t":"除去王面前的恶人，国位就靠公义坚立。","notes":[]},{"n":6,"t":"不要在王面前妄自尊大；不要在大人的位上站立。","notes":[]},{"n":7,"t":"宁可有人说：请你上来，强如在你觐见的王子面前叫你退下。","notes":[]},{"n":8,"t":"不要冒失出去与人争竞，免得至终被他羞辱，你就不知道怎样行了。","notes":[]},{"n":9,"t":"你与邻舍争讼，要与他一人辩论，不可泄漏人的密事，","notes":[]},{"n":10,"t":"恐怕听见的人骂你，你的臭名就难以脱离。","notes":[]},{"n":11,"t":"一句话说得合宜，就如金苹果在银网子里。","notes":[]},{"n":12,"t":"智慧人的劝戒，在顺从的人耳中，好像金耳环和精金的妆饰。","notes":[]},{"n":13,"t":"忠信的使者叫差他的人心里舒畅，就如在收割时有冰雪的凉气。","notes":[]},{"n":14,"t":"空夸赠送礼物的，好像无雨的风云。","notes":[]},{"n":15,"t":"恒常忍耐可以劝动君王；柔和的舌头能折断骨头。","notes":[]},{"n":16,"t":"你得了蜜吗？只可吃够而已，恐怕你过饱就呕吐出来。","notes":[]},{"n":17,"t":"你的脚要少进邻舍的家，恐怕他厌烦你，恨恶你。","notes":[]},{"n":18,"t":"作假见证陷害邻舍的，就是大槌，是利刀，是快箭。","notes":[]},{"n":19,"t":"患难时倚靠不忠诚的人，好像破坏的牙，错骨缝的脚。","notes":[]},{"n":20,"t":"对伤心的人唱歌，就如冷天脱衣服，又如硷上倒醋。","notes":[]},{"n":21,"t":"你的仇敌若饿了，就给他饭吃；若渴了，就给他水喝；","notes":[]},{"n":22,"t":"因为，你这样行就是把炭火堆在他的头上；耶和华也必赏赐你。","notes":[]},{"n":23,"t":"北风生雨，谗谤人的舌头也生怒容。","notes":[]},{"n":24,"t":"宁可住在房顶的角上，不在宽阔的房屋与争吵的妇人同住。","notes":[]},{"n":25,"t":"有好消息从远方来，就如拿凉水给口渴的人喝。","notes":[]},{"n":26,"t":"义人在恶人面前退缩，好像趟浑之泉，弄浊之井。","notes":[]},{"n":27,"t":"吃蜜过多是不好的；考究自己的荣耀也是可厌的。","notes":[]},{"n":28,"t":"人不制伏自己的心，好像毁坏的城邑没有墙垣。","notes":[]}]},"26":{"heading":"","verses":[{"n":1,"t":"夏天落雪，收割时下雨，都不相宜；愚昧人得尊荣也是如此。","notes":[]},{"n":2,"t":"麻雀往来，燕子翻飞；这样，无故的咒诅也必不临到。","notes":[]},{"n":3,"t":"鞭子是为打马，辔头是为勒驴；刑杖是为打愚昧人的背。","notes":[]},{"n":4,"t":"不要照愚昧人的愚妄话回答他，恐怕你与他一样。","notes":[]},{"n":5,"t":"要照愚昧人的愚妄话回答他，免得他自以为有智慧。","notes":[]},{"n":6,"t":"借愚昧人手寄信的，是砍断自己的脚，自受损害。","notes":["原文是：喝"]},{"n":7,"t":"瘸子的脚空存无用；箴言在愚昧人的口中也是如此。","notes":[]},{"n":8,"t":"将尊荣给愚昧人的，好像人把石子包在机弦里。","notes":[]},{"n":9,"t":"箴言在愚昧人的口中，好像荆棘刺入醉汉的手。","notes":[]},{"n":10,"t":"雇愚昧人的，与雇过路人的，就像射伤众人的弓箭手。","notes":[]},{"n":11,"t":"愚昧人行愚妄事，行了又行，就如狗转过来吃它所吐的。","notes":[]},{"n":12,"t":"你见自以为有智慧的人吗？愚昧人比他更有指望。","notes":[]},{"n":13,"t":"懒惰人说：道上有猛狮，街上有壮狮。","notes":[]},{"n":14,"t":"门在枢纽转动，懒惰人在床上也是如此。","notes":[]},{"n":15,"t":"懒惰人放手在盘子里，就是向口撤回也以为劳乏。","notes":[]},{"n":16,"t":"懒惰人看自己比七个善于应对的人更有智慧。","notes":[]},{"n":17,"t":"过路被事激动，管理不干己的争竞，好像人揪住狗耳。","notes":[]},{"n":18,"t":"人欺凌邻舍，却说：我岂不是戏耍吗？他就像疯狂的人抛掷火把、利箭，与杀人的兵器。","notes":["原文是死亡"],"end":19},{"n":20,"t":"火缺了柴就必熄灭；无人传舌，争竞便止息。","notes":[]},{"n":21,"t":"好争竞的人煽惑争端，就如余火加炭，火上加柴一样。","notes":[]},{"n":22,"t":"传舌人的言语，如同美食，深入人的心腹。","notes":[]},{"n":23,"t":"火热的嘴，奸恶的心，好像银渣包的瓦器。","notes":[]},{"n":24,"t":"怨恨人的，用嘴粉饰，心里却藏着诡诈；","notes":[]},{"n":25,"t":"他用甜言蜜语，你不可信他，因为他心中有七样可憎恶的。","notes":[]},{"n":26,"t":"他虽用诡诈遮掩自己的怨恨，他的邪恶必在会中显露。","notes":[]},{"n":27,"t":"挖陷坑的，自己必掉在其中；滚石头的，石头必反滚在他身上。","notes":[]},{"n":28,"t":"虚谎的舌恨他所压伤的人；谄媚的口败坏人的事。","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"不要为明日自夸，因为一日要生何事，你尚且不能知道。","notes":[]},{"n":2,"t":"要别人夸奖你，不可用口自夸；等外人称赞你，不可用嘴自称。","notes":[]},{"n":3,"t":"石头重，沙土沉，愚妄人的恼怒比这两样更重。","notes":[]},{"n":4,"t":"忿怒为残忍，怒气为狂澜，惟有嫉妒，谁能敌得住呢？","notes":[]},{"n":5,"t":"当面的责备强如背地的爱情。","notes":[]},{"n":6,"t":"朋友加的伤痕出于忠诚；仇敌连连亲嘴却是多余。","notes":[]},{"n":7,"t":"人吃饱了，厌恶蜂房的蜜；人饥饿了，一切苦物都觉甘甜。","notes":[]},{"n":8,"t":"人离本处飘流，好像雀鸟离窝游飞。","notes":[]},{"n":9,"t":"膏油与香料使人心喜悦；朋友诚实的劝教也是如此甘美。","notes":[]},{"n":10,"t":"你的朋友和父亲的朋友，你都不可离弃。你遭难的日子，不要上弟兄的家去；相近的邻舍强如远方的弟兄。","notes":[]},{"n":11,"t":"我儿，你要作智慧人，好叫我的心欢喜，使我可以回答那讥诮我的人。","notes":[]},{"n":12,"t":"通达人见祸藏躲；愚蒙人前往受害。","notes":[]},{"n":13,"t":"谁为生人作保，就拿谁的衣服；谁为外女作保，谁就承当。","notes":[]},{"n":14,"t":"清晨起来，大声给朋友祝福的，就算是咒诅他。","notes":[]},{"n":15,"t":"大雨之日连连滴漏，和争吵的妇人一样；","notes":[]},{"n":16,"t":"想拦阻她的，便是拦阻风，也是右手抓油。","notes":[]},{"n":17,"t":"铁磨铁，磨出刃来；朋友相感也是如此。","notes":["原文是磨朋友的脸"]},{"n":18,"t":"看守无花果树的，必吃树上的果子；敬奉主人的，必得尊荣。","notes":[]},{"n":19,"t":"水中照脸，彼此相符；人与人，心也相对。","notes":[]},{"n":20,"t":"阴间和灭亡永不满足；人的眼目也是如此。","notes":[]},{"n":21,"t":"鼎为炼银，炉为炼金，人的称赞也试炼人。","notes":[]},{"n":22,"t":"你虽用杵将愚妄人与打碎的麦子一同捣在臼中，他的愚妄还是离不了他。","notes":[]},{"n":23,"t":"你要详细知道你羊群的景况，留心料理你的牛群；","notes":[]},{"n":24,"t":"因为资财不能永有，冠冕岂能存到万代？","notes":[]},{"n":25,"t":"干草割去，嫩草发现，山上的菜蔬也被收敛。","notes":[]},{"n":26,"t":"羊羔之毛是为你作衣服；山羊是为作田地的价值，","notes":[]},{"n":27,"t":"并有母山羊奶够你吃，也够你的家眷吃，且够养你的婢女。","notes":[]}]},"28":{"heading":"","verses":[{"n":1,"t":"恶人虽无人追赶也逃跑；义人却胆壮像狮子。","notes":[]},{"n":2,"t":"邦国因有罪过，君王就多更换；因有聪明知识的人，国必长存。","notes":[]},{"n":3,"t":"穷人欺压贫民，好像暴雨冲没粮食。","notes":[]},{"n":4,"t":"违弃律法的，夸奖恶人；遵守律法的，却与恶人相争。","notes":[]},{"n":5,"t":"坏人不明白公义；惟有寻求耶和华的，无不明白。","notes":[]},{"n":6,"t":"行为纯正的穷乏人胜过行事乖僻的富足人。","notes":[]},{"n":7,"t":"谨守律法的，是智慧之子；与贪食人作伴的，却羞辱其父。","notes":[]},{"n":8,"t":"人以厚利加增财物，是给那怜悯穷人者积蓄的。","notes":[]},{"n":9,"t":"转耳不听律法的，他的祈祷也为可憎。","notes":[]},{"n":10,"t":"诱惑正直人行恶道的，必掉在自己的坑里；惟有完全人必承受福分。","notes":[]},{"n":11,"t":"富足人自以为有智慧，但聪明的贫穷人能将他查透。","notes":[]},{"n":12,"t":"义人得志，有大荣耀；恶人兴起，人就躲藏。","notes":[]},{"n":13,"t":"遮掩自己罪过的，必不亨通；承认离弃罪过的，必蒙怜恤。","notes":[]},{"n":14,"t":"常存敬畏的，便为有福；心存刚硬的，必陷在祸患里。","notes":[]},{"n":15,"t":"暴虐的君王辖制贫民，好像吼叫的狮子、觅食的熊。","notes":[]},{"n":16,"t":"无知的君多行暴虐；以贪财为可恨的，必年长日久。","notes":[]},{"n":17,"t":"背负流人血之罪的，必往坑里奔跑，谁也不可拦阻他。","notes":[]},{"n":18,"t":"行动正直的，必蒙拯救；行事弯曲的，立时跌倒。","notes":[]},{"n":19,"t":"耕种自己田地的，必得饱食；追随虚浮的，足受穷乏。","notes":[]},{"n":20,"t":"诚实人必多得福；想要急速发财的，不免受罚。","notes":[]},{"n":21,"t":"看人的情面乃为不好；人因一块饼枉法也为不好。","notes":[]},{"n":22,"t":"人有恶眼想要急速发财，却不知穷乏必临到他身。","notes":[]},{"n":23,"t":"责备人的，后来蒙人喜悦，多于那用舌头谄媚人的。","notes":[]},{"n":24,"t":"偷窃父母的，说：这不是罪，此人就是与强盗同类。","notes":[]},{"n":25,"t":"心中贪婪的，挑起争端；倚靠耶和华的，必得丰裕。","notes":[]},{"n":26,"t":"心中自是的，便是愚昧人；凭智慧行事的，必蒙拯救。","notes":[]},{"n":27,"t":"周济贫穷的，不致缺乏；佯为不见的，必多受咒诅。","notes":[]},{"n":28,"t":"恶人兴起，人就躲藏；恶人败亡，义人增多。","notes":[]}]},"29":{"heading":"","verses":[{"n":1,"t":"人屡次受责罚，仍然硬着颈项；他必顷刻败坏，无法可治。","notes":[]},{"n":2,"t":"义人增多，民就喜乐；恶人掌权，民就叹息。","notes":[]},{"n":3,"t":"爱慕智慧的，使父亲喜乐；与妓女结交的，却浪费钱财。","notes":[]},{"n":4,"t":"王借公平，使国坚定；索要贿赂，使国倾败。","notes":[]},{"n":5,"t":"谄媚邻舍的，就是设网罗绊他的脚。","notes":[]},{"n":6,"t":"恶人犯罪，自陷网罗；惟独义人欢呼喜乐。","notes":[]},{"n":7,"t":"义人知道查明穷人的案；恶人没有聪明，就不得而知。","notes":[]},{"n":8,"t":"亵慢人煽惑通城；智慧人止息众怒。","notes":[]},{"n":9,"t":"智慧人与愚妄人相争，或怒或笑，总不能使他止息。","notes":[]},{"n":10,"t":"好流人血的，恨恶完全人，索取正直人的性命。","notes":[]},{"n":11,"t":"愚妄人怒气全发；智慧人忍气含怒。","notes":[]},{"n":12,"t":"君王若听谎言，他一切臣仆都是奸恶。","notes":[]},{"n":13,"t":"贫穷人、强暴人在世相遇；他们的眼目都蒙耶和华光照。","notes":[]},{"n":14,"t":"君王凭诚实判断穷人；他的国位必永远坚立。","notes":[]},{"n":15,"t":"杖打和责备能加增智慧；放纵的儿子使母亲羞愧。","notes":[]},{"n":16,"t":"恶人加多，过犯也加多，义人必看见他们跌倒。","notes":[]},{"n":17,"t":"管教你的儿子，他就使你得安息，也必使你心里喜乐。","notes":[]},{"n":18,"t":"没有异象，民就放肆；惟遵守律法的，便为有福。","notes":["或译：默示"]},{"n":19,"t":"只用言语，仆人不肯受管教；他虽然明白，也不留意。","notes":[]},{"n":20,"t":"你见言语急躁的人吗？愚昧人比他更有指望。","notes":[]},{"n":21,"t":"人将仆人从小娇养，这仆人终久必成了他的儿子。","notes":[]},{"n":22,"t":"好气的人挑启争端；暴怒的人多多犯罪。","notes":[]},{"n":23,"t":"人的高傲必使他卑下；心里谦逊的，必得尊荣。","notes":[]},{"n":24,"t":"人与盗贼分赃，是恨恶自己的性命；他听见叫人发誓的声音，却不言语。","notes":[]},{"n":25,"t":"惧怕人的，陷入网罗；惟有倚靠耶和华的，必得安稳。","notes":[]},{"n":26,"t":"求王恩的人多；定人事乃在耶和华。","notes":[]},{"n":27,"t":"为非作歹的，被义人憎嫌；行事正直的，被恶人憎恶。","notes":[]}]},"30":{"heading":"亚古珥语录","verses":[{"n":1,"t":"雅基的儿子亚古珥的言语就是真言。这人对以铁和乌甲说：","notes":[]},{"n":2,"t":"我比众人更蠢笨，也没有人的聪明。","notes":[]},{"n":3,"t":"我没有学好智慧，也不认识至圣者。","notes":[]},{"n":4,"t":"谁升天又降下来？谁聚风在掌握中？谁包水在衣服里？谁立定地的四极？他名叫什么？他儿子名叫什么？你知道吗？","notes":[]},{"n":5,"t":"神的言语句句都是炼净的；投靠他的，他便作他们的盾牌。","notes":[]},{"n":6,"t":"他的言语，你不可加添，恐怕他责备你，你就显为说谎言的。","notes":[]},{"n":7,"t":"我求你两件事，在我未死之先，不要不赐给我：","notes":[],"heads":["其他箴言"]},{"n":8,"t":"求你使虚假和谎言远离我；使我也不贫穷也不富足；赐给我需用的饮食，","notes":[]},{"n":9,"t":"恐怕我饱足不认你，说：耶和华是谁呢？又恐怕我贫穷就偷窃，以致亵渎我神的名。","notes":[]},{"n":10,"t":"你不要向主人谗谤仆人，恐怕他咒诅你，你便算为有罪。","notes":[]},{"n":11,"t":"有一宗人，咒诅父亲，不给母亲祝福。","notes":["宗：原文是代；下同"]},{"n":12,"t":"有一宗人，自以为清洁，却没有洗去自己的污秽。","notes":[]},{"n":13,"t":"有一宗人，眼目何其高傲，眼皮也是高举。","notes":[]},{"n":14,"t":"有一宗人，牙如剑，齿如刀，要吞灭地上的困苦人和世间的穷乏人。","notes":[]},{"n":15,"t":"蚂蟥有两个女儿，常说：给呀，给呀！有三样不知足的，连不说「够的」共有四样：","notes":[]},{"n":16,"t":"就是阴间和石胎，浸水不足的地，并火。","notes":[]},{"n":17,"t":"戏笑父亲、藐视而不听从母亲的，他的眼睛必为谷中的乌鸦啄出来，为鹰雏所吃。","notes":[]},{"n":18,"t":"我所测不透的奇妙有三样，连我所不知道的共有四样：","notes":[]},{"n":19,"t":"就是鹰在空中飞的道；蛇在磐石上爬的道；船在海中行的道；男与女交合的道。","notes":[]},{"n":20,"t":"淫妇的道也是这样：她吃了，把嘴一擦就说：我没有行恶。","notes":[]},{"n":21,"t":"使地震动的有三样，连地担不起的共有四样：","notes":[]},{"n":22,"t":"就是仆人作王；愚顽人吃饱；","notes":[]},{"n":23,"t":"丑恶的女子出嫁；婢女接续主母。","notes":[]},{"n":24,"t":"地上有四样小物，却甚聪明：","notes":[]},{"n":25,"t":"蚂蚁是无力之类，却在夏天预备粮食。","notes":[]},{"n":26,"t":"沙番是软弱之类，却在磐石中造房。","notes":[]},{"n":27,"t":"蝗虫没有君王，却分队而出。","notes":[]},{"n":28,"t":"守宫用爪抓墙，却住在王宫。","notes":[]},{"n":29,"t":"步行威武的有三样，连行走威武的共有四样：","notes":[]},{"n":30,"t":"就是狮子—乃百兽中最为猛烈、无所躲避的，","notes":[]},{"n":31,"t":"猎狗，公山羊，和无人能敌的君王。","notes":[]},{"n":32,"t":"你若行事愚顽，自高自傲，或是怀了恶念，就当用手捂口。","notes":[]},{"n":33,"t":"摇牛奶必成奶油；扭鼻子必出血。照样，激动怒气必起争端。","notes":[]}]},"31":{"heading":"给一君王的忠告","verses":[{"n":1,"t":"利慕伊勒王的言语，是他母亲教训他的真言。","notes":[]},{"n":2,"t":"我的儿啊，我腹中生的儿啊，我许愿得的儿啊！我当怎样教训你呢？","notes":[]},{"n":3,"t":"不要将你的精力给妇女；也不要有败坏君王的行为。","notes":[]},{"n":4,"t":"利慕伊勒啊，君王喝酒，君王喝酒不相宜；王子说浓酒在那里也不相宜；","notes":[]},{"n":5,"t":"恐怕喝了就忘记律例，颠倒一切困苦人的是非。","notes":[]},{"n":6,"t":"可以把浓酒给将亡的人喝，把清酒给苦心的人喝，","notes":[]},{"n":7,"t":"让他喝了，就忘记他的贫穷，不再记念他的苦楚。","notes":[]},{"n":8,"t":"你当为哑巴开口，为一切孤独的伸冤。","notes":["或译：不能自辩的"]},{"n":9,"t":"你当开口按公义判断，为困苦和穷乏的辨屈。","notes":[]},{"n":10,"t":"才德的妇人谁能得着呢？她的价值远胜过珍珠。","notes":[],"heads":["论贤妻"]},{"n":11,"t":"她丈夫心里倚靠她，必不缺少利益；","notes":[]},{"n":12,"t":"她一生使丈夫有益无损。","notes":[]},{"n":13,"t":"她寻找羊绒和麻，甘心用手做工。","notes":[]},{"n":14,"t":"她好像商船从远方运粮来，","notes":[]},{"n":15,"t":"未到黎明她就起来，把食物分给家中的人，将当做的工分派婢女。","notes":[]},{"n":16,"t":"她想得田地就买来；用手所得之利栽种葡萄园。","notes":[]},{"n":17,"t":"她以能力束腰，使膀臂有力。","notes":[]},{"n":18,"t":"她觉得所经营的有利；她的灯终夜不灭。","notes":[]},{"n":19,"t":"她手拿捻线竿，手把纺线车。","notes":[]},{"n":20,"t":"她张手周济困苦人，伸手帮补穷乏人。","notes":[]},{"n":21,"t":"她不因下雪为家里的人担心，因为全家都穿着朱红衣服。","notes":[]},{"n":22,"t":"她为自己制作绣花毯子；她的衣服是细麻和紫色布做的。","notes":[]},{"n":23,"t":"她丈夫在城门口与本地的长老同坐，为众人所认识。","notes":[]},{"n":24,"t":"她做细麻布衣裳出卖，又将腰带卖与商家。","notes":[]},{"n":25,"t":"能力和威仪是她的衣服；她想到日后的景况就喜笑。","notes":[]},{"n":26,"t":"她开口就发智慧；她舌上有仁慈的法则。","notes":[]},{"n":27,"t":"她观察家务，并不吃闲饭。","notes":[]},{"n":28,"t":"她的儿女起来称她有福；她的丈夫也称赞她，","notes":[]},{"n":29,"t":"说：才德的女子很多，惟独你超过一切。","notes":[]},{"n":30,"t":"艳丽是虚假的，美容是虚浮的；惟敬畏耶和华的妇女必得称赞。","notes":[]},{"n":31,"t":"愿她享受操作所得的；愿她的工作在城门口荣耀她。","notes":[]}]}},"ECC":{"1":{"heading":"人生的虚空","verses":[{"n":1,"t":"在耶路撒冷作王、大卫的儿子、传道者的言语。","notes":[]},{"n":2,"t":"传道者说：虚空的虚空，虚空的虚空，凡事都是虚空。","notes":[]},{"n":3,"t":"人一切的劳碌，就是他在日光之下的劳碌，有什么益处呢？","notes":[]},{"n":4,"t":"一代过去，一代又来，地却永远长存。","notes":[]},{"n":5,"t":"日头出来，日头落下，急归所出之地。","notes":[]},{"n":6,"t":"风往南刮，又向北转，不住地旋转，而且返回转行原道。","notes":[]},{"n":7,"t":"江河都往海里流，海却不满；江河从何处流，仍归还何处。","notes":[]},{"n":8,"t":"万事令人厌烦，人不能说尽。眼看，看不饱；耳听，听不足。","notes":["或译：万物满有困乏"]},{"n":9,"t":"已有的事后必再有；已行的事后必再行。日光之下并无新事。","notes":[]},{"n":10,"t":"岂有一件事人能指着说这是新的？哪知，在我们以前的世代早已有了。","notes":[]},{"n":11,"t":"已过的世代，无人记念；将来的世代，后来的人也不记念。","notes":[]},{"n":12,"t":"我传道者在耶路撒冷作过以色列的王。","notes":[],"heads":["传道者的经验"]},{"n":13,"t":"我专心用智慧寻求、查究天下所做的一切事，乃知神叫世人所经练的是极重的劳苦。","notes":[]},{"n":14,"t":"我见日光之下所做的一切事，都是虚空，都是捕风。","notes":[]},{"n":15,"t":"弯曲的，不能变直；缺少的，不能足数。","notes":[]},{"n":16,"t":"我心里议论说：我得了大智慧，胜过我以前在耶路撒冷的众人，而且我心中多经历智慧和知识的事。","notes":[]},{"n":17,"t":"我又专心察明智慧、狂妄，和愚昧，乃知这也是捕风。","notes":[]},{"n":18,"t":"因为多有智慧，就多有愁烦；加增知识的，就加增忧伤。","notes":[]}]},"2":{"heading":"","verses":[{"n":1,"t":"我心里说：「来吧，我以喜乐试试你，你好享福！」谁知，这也是虚空。","notes":[]},{"n":2,"t":"我指嬉笑说：「这是狂妄。」论喜乐说：「有何功效呢？」","notes":[]},{"n":3,"t":"我心里察究，如何用酒使我肉体舒畅，我心却仍以智慧引导我；又如何持住愚昧，等我看明世人，在天下一生当行何事为美。","notes":[]},{"n":4,"t":"我为自己动大工程，建造房屋，栽种葡萄园，","notes":[]},{"n":5,"t":"修造园囿，在其中栽种各样果木树；","notes":[]},{"n":6,"t":"挖造水池，用以浇灌嫩小的树木。","notes":[]},{"n":7,"t":"我买了仆婢，也有生在家中的仆婢；又有许多牛群羊群，胜过以前在耶路撒冷众人所有的。","notes":[]},{"n":8,"t":"我又为自己积蓄金银和君王的财宝，并各省的财宝；又得唱歌的男女和世人所喜爱的物，并许多的妃嫔。","notes":[]},{"n":9,"t":"这样，我就日见昌盛，胜过以前在耶路撒冷的众人。我的智慧仍然存留。","notes":[]},{"n":10,"t":"凡我眼所求的，我没有留下不给它的；我心所乐的，我没有禁止不享受的；因我的心为我一切所劳碌的快乐，这就是我从劳碌中所得的分。","notes":[]},{"n":11,"t":"后来，我察看我手所经营的一切事和我劳碌所成的功。谁知都是虚空，都是捕风；在日光之下毫无益处。","notes":[]},{"n":12,"t":"我转念观看智慧、狂妄，和愚昧。在王以后而来的人还能做什么呢？也不过行早先所行的就是了。","notes":[]},{"n":13,"t":"我便看出智慧胜过愚昧，如同光明胜过黑暗。","notes":[]},{"n":14,"t":"智慧人的眼目光明，愚昧人在黑暗里行。我却看明有一件事，这两等人都必遇见。","notes":["光明：原文是在他头上"]},{"n":15,"t":"我就心里说：「愚昧人所遇见的，我也必遇见，我为何更有智慧呢？」我心里说，这也是虚空。","notes":[]},{"n":16,"t":"智慧人和愚昧人一样，永远无人记念，因为日后都被忘记；可叹智慧人死亡，与愚昧人无异。","notes":[]},{"n":17,"t":"我所以恨恶生命；因为在日光之下所行的事我都以为烦恼，都是虚空，都是捕风。","notes":[]},{"n":18,"t":"我恨恶一切的劳碌，就是我在日光之下的劳碌，因为我得来的必留给我以后的人。","notes":[]},{"n":19,"t":"那人是智慧是愚昧，谁能知道？他竟要管理我劳碌所得的，就是我在日光之下用智慧所得的。这也是虚空。","notes":[]},{"n":20,"t":"故此，我转想我在日光之下所劳碌的一切工作，心便绝望。","notes":[]},{"n":21,"t":"因为有人用智慧、知识、灵巧所劳碌得来的，却要留给未曾劳碌的人为分。这也是虚空，也是大患。","notes":[]},{"n":22,"t":"人在日光之下劳碌累心，在他一切的劳碌上得着什么呢？","notes":[]},{"n":23,"t":"因为他日日忧虑，他的劳苦成为愁烦，连夜间心也不安。这也是虚空。","notes":[]},{"n":24,"t":"人莫强如吃喝，且在劳碌中享福，我看这也是出于神的手。","notes":[]},{"n":25,"t":"论到吃用、享福，谁能胜过我呢？","notes":[]},{"n":26,"t":"神喜悦谁，就给谁智慧、知识，和喜乐；惟有罪人，神使他劳苦，叫他将所收聚的、所堆积的归给神所喜悦的人。这也是虚空，也是捕风。","notes":[]}]},"3":{"heading":"万事均有定时","verses":[{"n":1,"t":"凡事都有定期，天下万务都有定时。","notes":[]},{"n":2,"t":"生有时，死有时；栽种有时，拔出所栽种的也有时；","notes":[]},{"n":3,"t":"杀戮有时，医治有时；拆毁有时，建造有时；","notes":[]},{"n":4,"t":"哭有时，笑有时；哀恸有时，跳舞有时；","notes":[]},{"n":5,"t":"抛掷石头有时，堆聚石头有时；怀抱有时，不怀抱有时；","notes":[]},{"n":6,"t":"寻找有时，失落有时；保守有时，舍弃有时；","notes":[]},{"n":7,"t":"撕裂有时，缝补有时；静默有时，言语有时；","notes":[]},{"n":8,"t":"喜爱有时，恨恶有时；争战有时，和好有时。","notes":[]},{"n":9,"t":"这样看来，做事的人在他的劳碌上有什么益处呢？","notes":[]},{"n":10,"t":"我见神叫世人劳苦，使他们在其中受经练。","notes":[]},{"n":11,"t":"神造万物，各按其时成为美好，又将永生安置在世人心里。然而神从始至终的作为，人不能参透。","notes":["原文是永远"]},{"n":12,"t":"我知道世人，莫强如终身喜乐行善；","notes":[]},{"n":13,"t":"并且人人吃喝，在他一切劳碌中享福，这也是神的恩赐。","notes":[]},{"n":14,"t":"我知道神一切所做的都必永存；无所增添，无所减少。神这样行，是要人在他面前存敬畏的心。","notes":[]},{"n":15,"t":"现今的事早先就有了，将来的事早已也有了，并且神使已过的事重新再来。","notes":["或译：并且神再寻回已过的事"]},{"n":16,"t":"我又见日光之下，在审判之处有奸恶，在公义之处也有奸恶。","notes":[],"heads":["世上的不公平"]},{"n":17,"t":"我心里说，神必审判义人和恶人；因为在那里，各样事务，一切工作，都有定时。","notes":[]},{"n":18,"t":"我心里说，这乃为世人的缘故，是神要试验他们，使他们觉得自己不过像兽一样。","notes":[]},{"n":19,"t":"因为世人遭遇的，兽也遭遇，所遭遇的都是一样：这个怎样死，那个也怎样死，气息都是一样。人不能强于兽，都是虚空。","notes":[]},{"n":20,"t":"都归一处，都是出于尘土，也都归于尘土。","notes":[]},{"n":21,"t":"谁知道人的灵是往上升，兽的魂是下入地呢？","notes":[]},{"n":22,"t":"故此，我见人莫强如在他经营的事上喜乐，因为这是他的分。他身后的事谁能使他回来得见呢？","notes":[]}]},"4":{"heading":"","verses":[{"n":1,"t":"我又转念，见日光之下所行的一切欺压。看哪，受欺压的流泪，且无人安慰；欺压他们的有势力，也无人安慰他们。","notes":[]},{"n":2,"t":"因此，我赞叹那早已死的死人，胜过那还活着的活人。","notes":[]},{"n":3,"t":"并且我以为那未曾生的，就是未见过日光之下恶事的，比这两等人更强。","notes":[]},{"n":4,"t":"我又见人为一切的劳碌和各样灵巧的工作就被邻舍嫉妒。这也是虚空，也是捕风。","notes":[]},{"n":5,"t":"愚昧人抱着手，吃自己的肉。","notes":[]},{"n":6,"t":"满了一把，得享安静，强如满了两把，劳碌捕风。","notes":[]},{"n":7,"t":"我又转念，见日光之下有一件虚空的事：","notes":[]},{"n":8,"t":"有人孤单无二，无子无兄，竟劳碌不息，眼目也不以钱财为足。他说：「我劳劳碌碌，刻苦自己，不享福乐，到底是为谁呢？」这也是虚空，是极重的劳苦。","notes":[]},{"n":9,"t":"两个人总比一个人好，因为二人劳碌同得美好的果效。","notes":[]},{"n":10,"t":"若是跌倒，这人可以扶起他的同伴；若是孤身跌倒，没有别人扶起他来，这人就有祸了。","notes":[]},{"n":11,"t":"再者，二人同睡就都暖和，一人独睡怎能暖和呢？","notes":[]},{"n":12,"t":"有人攻胜孤身一人，若有二人便能敌挡他；三股合成的绳子不容易折断。","notes":[]},{"n":13,"t":"贫穷而有智慧的少年人胜过年老不肯纳谏的愚昧王。","notes":[]},{"n":14,"t":"这人是从监牢中出来作王，在他国中，生来原是贫穷的。","notes":[]},{"n":15,"t":"我见日光之下一切行动的活人都随从那第二位，就是起来代替老王的少年人。","notes":[]},{"n":16,"t":"他所治理的众人就是他的百姓，多得无数；在他后来的人尚且不喜悦他。这真是虚空，也是捕风。","notes":[]}]},"5":{"heading":"不可随便许愿","verses":[{"n":1,"t":"你到神的殿要谨慎脚步；因为近前听，胜过愚昧人献祭，他们本不知道所做的是恶。","notes":["或译：胜过献愚昧人的祭"]},{"n":2,"t":"你在神面前不可冒失开口，也不可心急发言；因为神在天上，你在地下，所以你的言语要寡少。","notes":[]},{"n":3,"t":"事务多，就令人做梦；言语多，就显出愚昧。","notes":[]},{"n":4,"t":"你向神许愿，偿还不可迟延，因他不喜悦愚昧人，所以你许的愿应当偿还。","notes":[]},{"n":5,"t":"你许愿不还，不如不许。","notes":[]},{"n":6,"t":"不可任你的口使肉体犯罪，也不可在祭司面前说是错许了。为何使神因你的声音发怒，败坏你手所做的呢？","notes":["原文是使者"]},{"n":7,"t":"多梦和多言，其中多有虚幻，你只要敬畏神。","notes":[]},{"n":8,"t":"你若在一省之中见穷人受欺压，并夺去公义公平的事，不要因此诧异；因有一位高过居高位的鉴察，在他们以上还有更高的。","notes":[],"heads":["人生是虚空的"]},{"n":9,"t":"况且地的益处归众人，就是君王也受田地的供应。","notes":[]},{"n":10,"t":"贪爱银子的，不因得银子知足；贪爱丰富的，也不因得利益知足。这也是虚空。","notes":[]},{"n":11,"t":"货物增添，吃的人也增添，物主得什么益处呢？不过眼看而已！","notes":[]},{"n":12,"t":"劳碌的人不拘吃多吃少，睡得香甜；富足人的丰满却不容他睡觉。","notes":[]},{"n":13,"t":"我见日光之下有一宗大祸患，就是财主积存资财，反害自己。","notes":[]},{"n":14,"t":"因遭遇祸患，这些资财就消灭；那人若生了儿子，手里也一无所有。","notes":[]},{"n":15,"t":"他怎样从母胎赤身而来，也必照样赤身而去；他所劳碌得来的，手中分毫不能带去。","notes":[]},{"n":16,"t":"他来的情形怎样，他去的情形也怎样。这也是一宗大祸患。他为风劳碌有什么益处呢？","notes":[]},{"n":17,"t":"并且他终身在黑暗中吃喝，多有烦恼，又有病患呕气。","notes":[]},{"n":18,"t":"我所见为善为美的，就是人在神赐他一生的日子吃喝，享受日光之下劳碌得来的好处，因为这是他的分。","notes":[]},{"n":19,"t":"神赐人资财丰富，使他能以吃用，能取自己的分，在他劳碌中喜乐，这乃是神的恩赐。","notes":[]},{"n":20,"t":"他不多思念自己一生的年日，因为神应他的心使他喜乐。","notes":[]}]},"6":{"heading":"","verses":[{"n":1,"t":"我见日光之下有一宗祸患重压在人身上，","notes":[]},{"n":2,"t":"就是人蒙神赐他资财、丰富、尊荣，以致他心里所愿的一样都不缺，只是神使他不能吃用，反有外人来吃用。这是虚空，也是祸患。","notes":[]},{"n":3,"t":"人若生一百个儿子，活许多岁数，以致他的年日甚多，心里却不得满享福乐，又不得埋葬；据我说，那不到期而落的胎比他倒好。","notes":[]},{"n":4,"t":"因为虚虚而来，暗暗而去，名字被黑暗遮蔽，","notes":[]},{"n":5,"t":"并且没有见过天日，也毫无知觉；这胎，比那人倒享安息。","notes":[]},{"n":6,"t":"那人虽然活千年，再活千年，却不享福，众人岂不都归一个地方去吗？","notes":[]},{"n":7,"t":"人的劳碌都为口腹，心里却不知足。","notes":[]},{"n":8,"t":"这样看来，智慧人比愚昧人有什么长处呢？穷人在众人面前知道如何行，有什么长处呢？","notes":[]},{"n":9,"t":"眼睛所看的比心里妄想的倒好。这也是虚空，也是捕风。","notes":[]},{"n":10,"t":"先前所有的，早已起了名，并知道何为人，他也不能与那比自己力大的相争。","notes":[]},{"n":11,"t":"加增虚浮的事既多，这与人有什么益处呢？","notes":[]},{"n":12,"t":"人一生虚度的日子，就如影儿经过，谁知道什么与他有益呢？谁能告诉他身后在日光之下有什么事呢？","notes":[]}]},"7":{"heading":"智愚之别","verses":[{"n":1,"t":"名誉强如美好的膏油；人死的日子胜过人生的日子。","notes":[]},{"n":2,"t":"往遭丧的家去，强如往宴乐的家去；因为死是众人的结局，活人也必将这事放在心上。","notes":[]},{"n":3,"t":"忧愁强如喜笑；因为面带愁容，终必使心喜乐。","notes":[]},{"n":4,"t":"智慧人的心在遭丧之家；愚昧人的心在快乐之家。","notes":[]},{"n":5,"t":"听智慧人的责备，强如听愚昧人的歌唱。","notes":[]},{"n":6,"t":"愚昧人的笑声，好像锅下烧荆棘的爆声；这也是虚空。","notes":[]},{"n":7,"t":"勒索使智慧人变为愚妄；贿赂能败坏人的慧心。","notes":[]},{"n":8,"t":"事情的终局强如事情的起头；存心忍耐的，胜过居心骄傲的。","notes":[]},{"n":9,"t":"你不要心里急躁恼怒，因为恼怒存在愚昧人的怀中。","notes":[]},{"n":10,"t":"不要说：先前的日子强过如今的日子，是什么缘故呢？你这样问，不是出于智慧。","notes":[]},{"n":11,"t":"智慧和产业并好，而且见天日的人得智慧更为有益。","notes":[]},{"n":12,"t":"因为智慧护庇人，好像银钱护庇人一样。惟独智慧能保全智慧人的生命。这就是知识的益处。","notes":[]},{"n":13,"t":"你要察看神的作为；因神使为曲的，谁能变为直呢？","notes":[]},{"n":14,"t":"遇亨通的日子你当喜乐；遭患难的日子你当思想；因为神使这两样并列，为的是叫人查不出身后有什么事。","notes":[]},{"n":15,"t":"有义人行义，反致灭亡；有恶人行恶，倒享长寿。这都是我在虚度之日中所见过的。","notes":[]},{"n":16,"t":"不要行义过分，也不要过于自逞智慧，何必自取败亡呢？","notes":[]},{"n":17,"t":"不要行恶过分，也不要为人愚昧，何必不到期而死呢？","notes":[]},{"n":18,"t":"你持守这个为美，那个也不要松手；因为敬畏神的人，必从这两样出来。","notes":[]},{"n":19,"t":"智慧使有智慧的人比城中十个官长更有能力。","notes":[]},{"n":20,"t":"时常行善而不犯罪的义人，世上实在没有。","notes":[]},{"n":21,"t":"人所说的一切话，你不要放在心上，恐怕听见你的仆人咒诅你。","notes":[]},{"n":22,"t":"因为你心里知道，自己也曾屡次咒诅别人。","notes":[]},{"n":23,"t":"我曾用智慧试验这一切事；我说，要得智慧，智慧却离我远。","notes":[]},{"n":24,"t":"万事之理，离我甚远，而且最深，谁能测透呢？","notes":[]},{"n":25,"t":"我转念，一心要知道，要考察，要寻求智慧和万事的理由；又要知道邪恶为愚昧，愚昧为狂妄。","notes":[]},{"n":26,"t":"我得知有等妇人比死还苦：她的心是网罗，手是锁链。凡蒙神喜悦的人必能躲避她；有罪的人却被她缠住了。","notes":[]},{"n":27,"t":"传道者说：「看哪，一千男子中，我找到一个正直人，但众女子中，没有找到一个。」我将这事一一比较，要寻求其理，我心仍要寻找，却未曾找到。","notes":[],"end":28},{"n":29,"t":"我所找到的只有一件，就是神造人原是正直，但他们寻出许多巧计。","notes":[]}]},"8":{"heading":"服从君王","verses":[{"n":1,"t":"谁如智慧人呢？谁知道事情的解释呢？人的智慧使他的脸发光，并使他脸上的暴气改变。","notes":[]},{"n":2,"t":"我劝你遵守王的命令；既指神起誓，理当如此。","notes":[]},{"n":3,"t":"不要急躁离开王的面前，不要固执行恶，因为他凡事都随自己的心意而行。","notes":[]},{"n":4,"t":"王的话本有权力，谁敢问他说「你做什么」呢？","notes":[]},{"n":5,"t":"凡遵守命令的，必不经历祸患；智慧人的心能辨明时候和定理。","notes":["原文是审判；下节同"]},{"n":6,"t":"各样事务成就都有时候和定理，因为人的苦难重压在他身上。","notes":[]},{"n":7,"t":"他不知道将来的事，因为将来如何，谁能告诉他呢？","notes":[]},{"n":8,"t":"无人有权力掌管生命，将生命留住；也无人有权力掌管死期；这场争战，无人能免；邪恶也不能救那好行邪恶的人。","notes":[]},{"n":9,"t":"这一切我都见过，也专心查考日光之下所做的一切事。有时这人管辖那人，令人受害。","notes":[]},{"n":10,"t":"我见恶人埋葬，归入坟墓；又见行正直事的离开圣地，在城中被人忘记。这也是虚空。","notes":[],"heads":["恶人和义人"]},{"n":11,"t":"因为断定罪名不立刻施刑，所以世人满心作恶。","notes":[]},{"n":12,"t":"罪人虽然作恶百次，倒享长久的年日；然而我准知道，敬畏神的，就是在他面前敬畏的人，终久必得福乐。","notes":[]},{"n":13,"t":"恶人却不得福乐，也不得长久的年日；这年日好像影儿，因他不敬畏神。","notes":[]},{"n":14,"t":"世上有一件虚空的事，就是义人所遭遇的，反照恶人所行的；又有恶人所遭遇的，反照义人所行的。我说，这也是虚空。","notes":[]},{"n":15,"t":"我就称赞快乐，原来人在日光之下，莫强如吃喝快乐；因为他在日光之下，神赐他一生的年日，要从劳碌中，时常享受所得的。","notes":[]},{"n":16,"t":"我专心求智慧，要看世上所做的事。（有昼夜不睡觉不合眼的。）","notes":[]},{"n":17,"t":"我就看明神一切的作为，知道人查不出日光之下所做的事；任凭他费多少力寻查，都查不出来，就是智慧人虽想知道，也是查不出来。","notes":[]}]},"9":{"heading":"智慧胜过武力","verses":[{"n":1,"t":"我将这一切事放在心上，详细考究，就知道义人和智慧人，并他们的作为都在神手中；或是爱，或是恨，都在他们的前面，人不能知道。","notes":[]},{"n":2,"t":"凡临到众人的事都是一样：义人和恶人都遭遇一样的事；好人，洁净人和不洁净人，献祭的与不献祭的，也是一样。好人如何，罪人也如何；起誓的如何，怕起誓的也如何。","notes":[]},{"n":3,"t":"在日光之下所行的一切事上有一件祸患，就是众人所遭遇的都是一样，并且世人的心充满了恶；活着的时候心里狂妄，后来就归死人那里去了。","notes":[]},{"n":4,"t":"与一切活人相连的，那人还有指望，因为活着的狗比死了的狮子更强。","notes":[]},{"n":5,"t":"活着的人知道必死；死了的人毫无所知，也不再得赏赐；他们的名无人记念。","notes":[]},{"n":6,"t":"他们的爱，他们的恨，他们的嫉妒，早都消灭了。在日光之下所行的一切事上，他们永不再有分了。","notes":[]},{"n":7,"t":"你只管去欢欢喜喜吃你的饭，心中快乐喝你的酒，因为神已经悦纳你的作为。","notes":[]},{"n":8,"t":"你的衣服当时常洁白，你头上也不要缺少膏油。","notes":[]},{"n":9,"t":"在你一生虚空的年日，就是神赐你在日光之下虚空的年日，当同你所爱的妻，快活度日，因为那是你生前在日光之下劳碌的事上所得的分。","notes":[]},{"n":10,"t":"凡你手所当做的事要尽力去做；因为在你所必去的阴间没有工作，没有谋算，没有知识，也没有智慧。","notes":[]},{"n":11,"t":"我又转念：见日光之下，快跑的未必能赢；力战的未必得胜；智慧的未必得粮食；明哲的未必得资财；灵巧的未必得喜悦。所临到众人的是在乎当时的机会。","notes":[]},{"n":12,"t":"原来人也不知道自己的定期。鱼被恶网圈住，鸟被网罗捉住，祸患忽然临到的时候，世人陷在其中也是如此。","notes":[]},{"n":13,"t":"我见日光之下有一样智慧，据我看乃是广大，","notes":[]},{"n":14,"t":"就是有一小城，其中的人数稀少，有大君王来攻击，修筑营垒，将城围困。","notes":[]},{"n":15,"t":"城中有一个贫穷的智慧人，他用智慧救了那城，却没有人记念那穷人。","notes":[]},{"n":16,"t":"我就说，智慧胜过勇力；然而那贫穷人的智慧被人藐视，他的话也无人听从。","notes":[]},{"n":17,"t":"宁可在安静之中听智慧人的言语，不听掌管愚昧人的喊声。","notes":[]},{"n":18,"t":"智慧胜过打仗的兵器；但一个罪人能败坏许多善事。","notes":[]}]},"10":{"heading":"","verses":[{"n":1,"t":"死苍蝇使做香的膏油发出臭气；这样，一点愚昧也能败坏智慧和尊荣。","notes":[]},{"n":2,"t":"智慧人的心居右；愚昧人的心居左。","notes":[]},{"n":3,"t":"并且愚昧人行路显出无知，对众人说，他是愚昧人。","notes":[]},{"n":4,"t":"掌权者的心若向你发怒，不要离开你的本位，因为柔和能免大过。","notes":[]},{"n":5,"t":"我见日光之下有一件祸患，似乎出于掌权的错误，","notes":[]},{"n":6,"t":"就是愚昧人立在高位；富足人坐在低位。","notes":[]},{"n":7,"t":"我见过仆人骑马，王子像仆人在地上步行。","notes":[]},{"n":8,"t":"挖陷坑的，自己必掉在其中；拆墙垣的，必为蛇所咬。","notes":[]},{"n":9,"t":"凿开石头的，必受损伤；劈开木头的，必遭危险。","notes":["或译：挪移"]},{"n":10,"t":"铁器钝了，若不将刃磨快，就必多费气力；但得智慧指教，便有益处。","notes":[]},{"n":11,"t":"未行法术以先，蛇若咬人，后行法术也是无益。","notes":[]},{"n":12,"t":"智慧人的口说出恩言；愚昧人的嘴吞灭自己。","notes":[]},{"n":13,"t":"他口中的言语起头是愚昧；他话的末尾是奸恶的狂妄。","notes":[]},{"n":14,"t":"愚昧人多有言语，人却不知将来有什么事；他身后的事谁能告诉他呢？","notes":[]},{"n":15,"t":"凡愚昧人，他的劳碌使自己困乏，因为连进城的路，他也不知道。","notes":[]},{"n":16,"t":"邦国啊，你的王若是孩童，你的群臣早晨宴乐，你就有祸了！","notes":[]},{"n":17,"t":"邦国啊，你的王若是贵胄之子，你的群臣按时吃喝，为要补力，不为酒醉，你就有福了！","notes":[]},{"n":18,"t":"因人懒惰，房顶塌下；因人手懒，房屋滴漏。","notes":[]},{"n":19,"t":"设摆筵席是为喜笑。酒能使人快活；钱能叫万事应心。","notes":[]},{"n":20,"t":"你不可咒诅君王，也不可心怀此念；在你卧房也不可咒诅富户。因为空中的鸟必传扬这声音，有翅膀的也必述说这事。","notes":[]}]},"11":{"heading":"智慧人的作为","verses":[{"n":1,"t":"当将你的粮食撒在水面，因为日久必能得着。","notes":[]},{"n":2,"t":"你要分给七人，或分给八人，因为你不知道将来有什么灾祸临到地上。","notes":[]},{"n":3,"t":"云若满了雨，就必倾倒在地上。树若向南倒，或向北倒，树倒在何处，就存在何处。","notes":[]},{"n":4,"t":"看风的，必不撒种；望云的，必不收割。","notes":[]},{"n":5,"t":"风从何道来，骨头在怀孕妇人的胎中如何长成，你尚且不得知道；这样，行万事之神的作为，你更不得知道。","notes":[]},{"n":6,"t":"早晨要撒你的种，晚上也不要歇你的手，因为你不知道哪一样发旺；或是早撒的，或是晚撒的，或是两样都好。","notes":[]},{"n":7,"t":"光本是佳美的，眼见日光也是可悦的。","notes":[]},{"n":8,"t":"人活多年，就当快乐多年；然而也当想到黑暗的日子。因为这日子必多，所要来的都是虚空。","notes":[]},{"n":9,"t":"少年人哪，你在幼年时当快乐。在幼年的日子，使你的心欢畅，行你心所愿行的，看你眼所爱看的；却要知道，为这一切的事，神必审问你。","notes":[],"heads":["对年轻人的忠告"]},{"n":10,"t":"所以，你当从心中除掉愁烦，从肉体克去邪恶；因为一生的开端和幼年之时，都是虚空的。","notes":[]}]},"12":{"heading":"结论","verses":[{"n":1,"t":"你趁着年幼、衰败的日子尚未来到，就是你所说，我毫无喜乐的那些年日未曾临近之先，当记念造你的主。","notes":[]},{"n":2,"t":"不要等到日头、光明、月亮、星宿变为黑暗，雨后云彩反回，","notes":[]},{"n":3,"t":"看守房屋的发颤，有力的屈身，推磨的稀少就止息，从窗户往外看的都昏暗；","notes":[]},{"n":4,"t":"街门关闭，推磨的响声微小，雀鸟一叫，人就起来，唱歌的女子也都衰微。","notes":[]},{"n":5,"t":"人怕高处，路上有惊慌，杏树开花，蚱蜢成为重担，人所愿的也都废掉；因为人归他永远的家，吊丧的在街上往来。","notes":[]},{"n":6,"t":"银链折断，金罐破裂，瓶子在泉旁损坏，水轮在井口破烂，","notes":[]},{"n":7,"t":"尘土仍归于地，灵仍归于赐灵的神。","notes":[]},{"n":8,"t":"传道者说：「虚空的虚空，凡事都是虚空。」","notes":[]},{"n":9,"t":"再者，传道者因有智慧，仍将知识教训众人；又默想，又考查，又陈说许多箴言。","notes":[]},{"n":10,"t":"传道者专心寻求可喜悦的言语，是凭正直写的诚实话。","notes":[]},{"n":11,"t":"智慧人的言语好像刺棍；会中之师的言语又像钉稳的钉子，都是一个牧者所赐的。","notes":[]},{"n":12,"t":"我儿，还有一层，你当受劝戒：著书多，没有穷尽；读书多，身体疲倦。","notes":[]},{"n":13,"t":"这些事都已听见了，总意就是：敬畏神，谨守他的诫命，这是人所当尽的本分。","notes":["或译：这是众人的本分"]},{"n":14,"t":"因为人所做的事，连一切隐藏的事，无论是善是恶，神都必审问。","notes":[]}]}},"SNG":{"1":{"heading":"第一首","verses":[{"n":1,"t":"所罗门的歌，是歌中的雅歌。","notes":[]},{"n":2,"t":"愿他用口与我亲嘴；因你的爱情比酒更美。","notes":[]},{"n":3,"t":"你的膏油馨香；你的名如同倒出来的香膏，所以众童女都爱你。","notes":[]},{"n":4,"t":"愿你吸引我，我们就快跑跟随你。王带我进了内室，我们必因你欢喜快乐。我们要称赞你的爱情，胜似称赞美酒。他们爱你是理所当然的。","notes":[]},{"n":5,"t":"耶路撒冷的众女子啊，我虽然黑，却是秀美，如同基达的帐棚，好像所罗门的幔子。","notes":[]},{"n":6,"t":"不要因日头把我晒黑了就轻看我。我同母的弟兄向我发怒，他们使我看守葡萄园；我自己的葡萄园却没有看守。","notes":[]},{"n":7,"t":"我心所爱的啊，求你告诉我，你在何处牧羊？晌午在何处使羊歇卧？我何必在你同伴的羊群旁边好像蒙着脸的人呢？","notes":[]},{"n":8,"t":"你这女子中极美丽的，你若不知道，只管跟随羊群的脚踪去，把你的山羊羔牧放在牧人帐棚的旁边。","notes":[]},{"n":9,"t":"我的佳偶，我将你比法老车上套的骏马。","notes":[]},{"n":10,"t":"你的两腮因发辫而秀美；你的颈项因珠串而华丽。","notes":[]},{"n":11,"t":"我们要为你编上金辫，镶上银钉。","notes":[]},{"n":12,"t":"王正坐席的时候，我的哪哒香膏发出香味。","notes":[]},{"n":13,"t":"我以我的良人为一袋没药，常在我怀中。","notes":[]},{"n":14,"t":"我以我的良人为一棵凤仙花，在隐·基底葡萄园中。","notes":[]},{"n":15,"t":"我的佳偶，你甚美丽！你甚美丽！你的眼好像鸽子眼。","notes":[]},{"n":16,"t":"我的良人哪，你甚美丽可爱！我们以青草为床榻，","notes":[]},{"n":17,"t":"以香柏树为房屋的栋梁，以松树为椽子。","notes":[]}]},"2":{"heading":"第二首","verses":[{"n":1,"t":"我是沙仑的玫瑰花，是谷中的百合花。","notes":["或译：水仙花"]},{"n":2,"t":"我的佳偶在女子中，好像百合花在荆棘内。","notes":[]},{"n":3,"t":"我的良人在男子中，如同苹果树在树林中。我欢欢喜喜坐在他的荫下，尝他果子的滋味，觉得甘甜。","notes":[]},{"n":4,"t":"他带我入筵宴所，以爱为旗在我以上。","notes":[]},{"n":5,"t":"求你们给我葡萄干增补我力，给我苹果畅快我心，因我思爱成病。","notes":[]},{"n":6,"t":"他的左手在我头下；他的右手将我抱住。","notes":[]},{"n":7,"t":"耶路撒冷的众女子啊，我指着羚羊或田野的母鹿嘱咐你们：不要惊动、不要叫醒我所亲爱的，等他自己情愿。","notes":["不要叫醒<ins>.</ins>.情愿：或译不要激动爱情，等它自发"]},{"n":8,"t":"听啊！是我良人的声音；看哪！他蹿山越岭而来。","notes":[]},{"n":9,"t":"我的良人好像羚羊，或像小鹿。他站在我们墙壁后，从窗户往里观看，从窗棂往里窥探。","notes":[]},{"n":10,"t":"我良人对我说：我的佳偶，我的美人，起来，与我同去！","notes":[]},{"n":11,"t":"因为冬天已往，雨水止住过去了。","notes":[]},{"n":12,"t":"地上百花开放，百鸟鸣叫的时候已经来到；斑鸠的声音在我们境内也听见了。","notes":["或译：修理葡萄树的时候"]},{"n":13,"t":"无花果树的果子渐渐成熟；葡萄树开花放香。我的佳偶，我的美人，起来，与我同去！","notes":[]},{"n":14,"t":"我的鸽子啊，你在磐石穴中，在陡岩的隐密处。求你容我得见你的面貌，得听你的声音；因为你的声音柔和，你的面貌秀美。","notes":[]},{"n":15,"t":"要给我们擒拿狐狸，就是毁坏葡萄园的小狐狸，因为我们的葡萄正在开花。","notes":[]},{"n":16,"t":"良人属我，我也属他；他在百合花中牧放群羊。","notes":[]},{"n":17,"t":"我的良人哪，求你等到天起凉风、日影飞去的时候，你要转回，好像羚羊，或像小鹿在比特山上。","notes":[]}]},"3":{"heading":"第三首","verses":[{"n":1,"t":"我夜间躺卧在床上，寻找我心所爱的；我寻找他，却寻不见。","notes":[]},{"n":2,"t":"我说：我要起来，游行城中，在街市上，在宽阔处，寻找我心所爱的。我寻找他，却寻不见。","notes":[]},{"n":3,"t":"城中巡逻看守的人遇见我；我问他们：你们看见我心所爱的没有？","notes":[]},{"n":4,"t":"我刚离开他们就遇见我心所爱的。我拉住他，不容他走，领他入我母家，到怀我者的内室。","notes":[]},{"n":5,"t":"耶路撒冷的众女子啊，我指着羚羊或田野的母鹿嘱咐你们：不要惊动、不要叫醒我所亲爱的，等他自己情愿。","notes":["不要叫醒<ins>.</ins>.情愿：或译不要激动爱情，等它自发"]},{"n":6,"t":"那从旷野上来、形状如烟柱、以没药和乳香并商人各样香粉薰的是谁呢？","notes":[]},{"n":7,"t":"看哪，是所罗门的轿；四围有六十个勇士，都是以色列中的勇士；","notes":[]},{"n":8,"t":"手都持刀，善于争战，腰间佩刀，防备夜间有惊慌。","notes":[]},{"n":9,"t":"所罗门王用黎巴嫩木为自己制造一乘华轿。","notes":[]},{"n":10,"t":"轿柱是用银做的，轿底是用金做的；坐垫是紫色的，其中所铺的乃耶路撒冷众女子的爱情。","notes":[]},{"n":11,"t":"锡安的众女子啊，你们出去观看所罗门王！头戴冠冕，就是在他婚筵的日子、心中喜乐的时候，他母亲给他戴上的。","notes":[]}]},"4":{"heading":"","verses":[{"n":1,"t":"我的佳偶，你甚美丽！你甚美丽！你的眼在帕子内好像鸽子眼。你的头发如同山羊群卧在基列山旁。","notes":[]},{"n":2,"t":"你的牙齿如新剪毛的一群母羊，洗净上来，个个都有双生，没有一只丧掉子的。","notes":[]},{"n":3,"t":"你的唇好像一条朱红线；你的嘴也秀美。你的两太阳在帕子内，如同一块石榴。","notes":[]},{"n":4,"t":"你的颈项好像大卫建造收藏军器的高台，其上悬挂一千盾牌，都是勇士的藤牌。","notes":[]},{"n":5,"t":"你的两乳好像百合花中吃草的一对小鹿，就是母鹿双生的。","notes":[]},{"n":6,"t":"我要往没药山和乳香冈去，直等到天起凉风、日影飞去的时候回来。","notes":[]},{"n":7,"t":"我的佳偶，你全然美丽，毫无瑕疵！","notes":[]},{"n":8,"t":"我的新妇，求你与我一同离开黎巴嫩，与我一同离开黎巴嫩。从亚玛拿顶，从示尼珥与黑门顶，从有狮子的洞，从有豹子的山往下观看。","notes":[]},{"n":9,"t":"我妹子，我新妇，你夺了我的心。你用眼一看，用你项上的一条金链，夺了我的心！","notes":[]},{"n":10,"t":"我妹子，我新妇，你的爱情何其美！你的爱情比酒更美！你膏油的香气胜过一切香品！","notes":[]},{"n":11,"t":"我新妇，你的嘴唇滴蜜，好像蜂房滴蜜；你的舌下有蜜，有奶。你衣服的香气如黎巴嫩的香气。","notes":[]},{"n":12,"t":"我妹子，我新妇，乃是关锁的园，禁闭的井，封闭的泉源。","notes":[]},{"n":13,"t":"你园内所种的结了石榴，有佳美的果子，并凤仙花与哪哒树。","notes":[]},{"n":14,"t":"有哪哒和番红花，菖蒲和桂树，并各样乳香木、没药、沉香，与一切上等的果品。","notes":[]},{"n":15,"t":"你是园中的泉，活水的井，从黎巴嫩流下来的溪水。","notes":[]},{"n":16,"t":"北风啊，兴起！南风啊，吹来！吹在我的园内，使其中的香气发出来。愿我的良人进入自己园里，吃他佳美的果子。","notes":[]}]},"5":{"heading":"第四首","verses":[{"n":1,"t":"我妹子，我新妇，我进了我的园中，采了我的没药和香料，吃了我的蜜房和蜂蜜，喝了我的酒和奶。我的朋友们，请吃！我所亲爱的，请喝，且多多地喝！","notes":[]},{"n":2,"t":"我身睡卧，我心却醒。这是我良人的声音；他敲门说：我的妹子，我的佳偶，我的鸽子，我的完全人，求你给我开门；因我的头满了露水，我的头发被夜露滴湿。","notes":[]},{"n":3,"t":"我回答说：我脱了衣裳，怎能再穿上呢？我洗了脚，怎能再玷污呢？","notes":[]},{"n":4,"t":"我的良人从门孔里伸进手来，我便因他动了心。","notes":[]},{"n":5,"t":"我起来，要给我良人开门。我的两手滴下没药；我的指头有没药汁滴在门闩上。","notes":[]},{"n":6,"t":"我给我的良人开了门；我的良人却已转身走了。他说话的时候，我神不守舍；我寻找他，竟寻不见；我呼叫他，他却不回答。","notes":[]},{"n":7,"t":"城中巡逻看守的人遇见我，打了我，伤了我；看守城墙的人夺去我的披肩。","notes":[]},{"n":8,"t":"耶路撒冷的众女子啊，我嘱咐你们：若遇见我的良人，要告诉他，我因思爱成病。","notes":[]},{"n":9,"t":"你这女子中极美丽的，你的良人比别人的良人有何强处？你的良人比别人的良人有何强处，你就这样嘱咐我们？","notes":[]},{"n":10,"t":"我的良人白而且红，超乎万人之上。","notes":[]},{"n":11,"t":"他的头像至精的金子；他的头发厚密累垂，黑如乌鸦。","notes":[]},{"n":12,"t":"他的眼如溪水旁的鸽子眼，用奶洗净，安得合式。","notes":[]},{"n":13,"t":"他的两腮如香花畦，如香草台；他的嘴唇像百合花，且滴下没药汁。","notes":[]},{"n":14,"t":"他的两手好像金管，镶嵌水苍玉；他的身体如同雕刻的象牙，周围镶嵌蓝宝石。","notes":[]},{"n":15,"t":"他的腿好像白玉石柱，安在精金座上；他的形状如黎巴嫩，且佳美如香柏树。","notes":[]},{"n":16,"t":"他的口极其甘甜；他全然可爱。耶路撒冷的众女子啊，这是我的良人；这是我的朋友。","notes":[]}]},"6":{"heading":"第五首","verses":[{"n":1,"t":"你这女子中极美丽的，你的良人往何处去了？你的良人转向何处去了，我们好与你同去寻找他。","notes":[]},{"n":2,"t":"我的良人下入自己园中，到香花畦，在园内牧放群羊，采百合花。","notes":[]},{"n":3,"t":"我属我的良人，我的良人也属我；他在百合花中牧放群羊。","notes":[]},{"n":4,"t":"我的佳偶啊，你美丽如得撒，秀美如耶路撒冷，威武如展开旌旗的军队。","notes":[]},{"n":5,"t":"求你掉转眼目不看我，因你的眼目使我惊乱。你的头发如同山羊群卧在基列山旁。","notes":[]},{"n":6,"t":"你的牙齿如一群母羊洗净上来，个个都有双生，没有一只丧掉子的。","notes":[]},{"n":7,"t":"你的两太阳在帕子内，如同一块石榴。","notes":[]},{"n":8,"t":"有六十王后八十妃嫔，并有无数的童女。","notes":[]},{"n":9,"t":"我的鸽子，我的完全人，只有这一个是她母亲独生的，是生养她者所宝爱的。众女子见了就称她有福；王后妃嫔见了也赞美她。","notes":[]},{"n":10,"t":"那向外观看、如晨光发现、美丽如月亮、皎洁如日头、威武如展开旌旗军队的是谁呢？","notes":[]},{"n":11,"t":"我下入核桃园，要看谷中青绿的植物，要看葡萄发芽没有，石榴开花没有。","notes":[]},{"n":12,"t":"不知不觉，我的心将我安置在我尊长的车中。","notes":[]},{"n":13,"t":"回来，回来，书拉密女；你回来，你回来，使我们得观看你。你们为何要观看书拉密女，像观看玛哈念跳舞的呢？","notes":[]}]},"7":{"heading":"","verses":[{"n":1,"t":"王女啊，你的脚在鞋中何其美好！你的大腿圆润，好像美玉，是巧匠的手做成的。","notes":[]},{"n":2,"t":"你的肚脐如圆杯，不缺调和的酒；你的腰如一堆麦子，周围有百合花。","notes":[]},{"n":3,"t":"你的两乳好像一对小鹿，就是母鹿双生的。","notes":[]},{"n":4,"t":"你的颈项如象牙台；你的眼目像希实本、巴特·拉并门旁的水池；你的鼻子仿佛朝大马士革的黎巴嫩塔。","notes":[]},{"n":5,"t":"你的头在你身上好像迦密山；你头上的发是紫黑色；王的心因这下垂的发绺系住了。","notes":[]},{"n":6,"t":"我所爱的，你何其美好！何其可悦，使人欢畅喜乐！","notes":[]},{"n":7,"t":"你的身量好像棕树；你的两乳如同其上的果子，累累下垂。","notes":[]},{"n":8,"t":"我说：我要上这棕树，抓住枝子。愿你的两乳好像葡萄累累下垂，你鼻子的气味香如苹果；","notes":[]},{"n":9,"t":"你的口如上好的酒。女子说：为我的良人下咽舒畅，流入睡觉人的嘴中。","notes":[]},{"n":10,"t":"我属我的良人，他也恋慕我。","notes":[]},{"n":11,"t":"我的良人，来吧！你我可以往田间去；你我可以在村庄住宿。","notes":[]},{"n":12,"t":"我们早晨起来往葡萄园去，看看葡萄发芽开花没有，石榴放蕊没有；我在那里要将我的爱情给你。","notes":[]},{"n":13,"t":"风茄放香，在我们的门内有各样新陈佳美的果子；我的良人，这都是我为你存留的。","notes":[]}]},"8":{"heading":"第六首","verses":[{"n":1,"t":"巴不得你像我的兄弟，像吃我母亲奶的兄弟；我在外头遇见你就与你亲嘴，谁也不轻看我。","notes":[]},{"n":2,"t":"我必引导你，领你进我母亲的家；我可以领受教训，也就使你喝石榴汁酿的香酒。","notes":[]},{"n":3,"t":"他的左手必在我头下；他的右手必将我抱住。","notes":[]},{"n":4,"t":"耶路撒冷的众女子啊，我嘱咐你们：不要惊动、不要叫醒我所亲爱的，等他自己情愿。","notes":["不要叫醒<ins>.</ins>.情愿：或译不要激动爱情，等它自发"]},{"n":5,"t":"那靠着良人从旷野上来的是谁呢？我在苹果树下叫醒你。你母亲在那里为你劬劳；生养你的在那里为你劬劳。","notes":[]},{"n":6,"t":"求你将我放在你心上如印记，带在你臂上如戳记。因为爱情如死之坚强，嫉恨如阴间之残忍；所发的电光是火焰的电光，是耶和华的烈焰。","notes":[]},{"n":7,"t":"爱情，众水不能息灭，大水也不能淹没。若有人拿家中所有的财宝要换爱情，就全被藐视。","notes":[]},{"n":8,"t":"我们有一小妹；她的两乳尚未长成，人来提亲的日子，我们当为她怎样办理？","notes":[]},{"n":9,"t":"她若是墙，我们要在其上建造银塔；她若是门，我们要用香柏木板围护她。","notes":[]},{"n":10,"t":"我是墙；我两乳像其上的楼。那时，我在他眼中像得平安的人。","notes":[]},{"n":11,"t":"所罗门在巴力·哈们有一葡萄园；他将这葡萄园交给看守的人，为其中的果子必交一千舍客勒银子。","notes":[]},{"n":12,"t":"我自己的葡萄园在我面前。所罗门哪，一千舍客勒归你，二百舍客勒归看守果子的人。","notes":[]},{"n":13,"t":"你这住在园中的，同伴都要听你的声音，求你使我也得听见。","notes":[]},{"n":14,"t":"我的良人哪，求你快来！如羚羊或小鹿在香草山上。","notes":[]}]}},"ISA":{"1":{"heading":"神责备以色列","verses":[{"n":1,"t":"当乌西雅、约坦、亚哈斯、希西家作犹大王的时候，亚摩斯的儿子以赛亚得默示，论到犹大和耶路撒冷。","notes":[]},{"n":2,"t":"天哪，要听！地啊，侧耳而听！因为耶和华说：我养育儿女，将他们养大，他们竟悖逆我。","notes":[]},{"n":3,"t":"牛认识主人，驴认识主人的槽，以色列却不认识；我的民却不留意。","notes":[]},{"n":4,"t":"嗐！犯罪的国民，担着罪孽的百姓；行恶的种类，败坏的儿女！他们离弃耶和华，藐视以色列的圣者，与他生疏，往后退步。","notes":[]},{"n":5,"t":"你们为什么屡次悖逆，还要受责打吗？你们已经满头疼痛，全心发昏。","notes":[]},{"n":6,"t":"从脚掌到头顶，没有一处完全的，尽是伤口、青肿，与新打的伤痕，都没有收口，没有缠裹，也没有用膏滋润。","notes":[]},{"n":7,"t":"你们的地土已经荒凉；你们的城邑被火焚毁。你们的田地在你们眼前为外邦人所侵吞，既被外邦人倾覆就成为荒凉。","notes":[]},{"n":8,"t":"仅存锡安城，好像葡萄园的草棚，瓜田的茅屋，被围困的城邑。","notes":["原文是女子"]},{"n":9,"t":"若不是万军之耶和华给我们稍留余种，我们早已像所多玛、蛾摩拉的样子了。","notes":[]},{"n":10,"t":"你们这所多玛的官长啊，要听耶和华的话！你们这蛾摩拉的百姓啊，要侧耳听我们神的训诲！","notes":[]},{"n":11,"t":"耶和华说：你们所献的许多祭物与我何益呢？公绵羊的燔祭和肥畜的脂油，我已经够了；公牛的血，羊羔的血，公山羊的血，我都不喜悦。","notes":[]},{"n":12,"t":"你们来朝见我，谁向你们讨这些，使你们践踏我的院宇呢？","notes":[]},{"n":13,"t":"你们不要再献虚浮的供物。香品是我所憎恶的；月朔和安息日，并宣召的大会，也是我所憎恶的；作罪孽，又守严肃会，我也不能容忍。","notes":[]},{"n":14,"t":"你们的月朔和节期，我心里恨恶，我都以为麻烦；我担当，便不耐烦。","notes":[]},{"n":15,"t":"你们举手祷告，我必遮眼不看；就是你们多多地祈祷，我也不听。你们的手都满了杀人的血。","notes":[]},{"n":16,"t":"你们要洗濯、自洁，从我眼前除掉你们的恶行，要止住作恶，","notes":[]},{"n":17,"t":"学习行善，寻求公平，解救受欺压的；给孤儿伸冤，为寡妇辨屈。","notes":[]},{"n":18,"t":"耶和华说：你们来，我们彼此辩论。你们的罪虽像朱红，必变成雪白；虽红如丹颜，必白如羊毛。","notes":[]},{"n":19,"t":"你们若甘心听从，必吃地上的美物，","notes":[]},{"n":20,"t":"若不听从，反倒悖逆，必被刀剑吞灭。这是耶和华亲口说的。","notes":[]},{"n":21,"t":"可叹，忠信的城变为妓女！从前充满了公平，公义居在其中，现今却有凶手居住。","notes":[],"heads":["罪大恶极的城"]},{"n":22,"t":"你的银子变为渣滓；你的酒用水搀对。","notes":[]},{"n":23,"t":"你的官长居心悖逆，与盗贼作伴，各都喜爱贿赂，追求赃私。他们不为孤儿伸冤；寡妇的案件也不得呈到他们面前。","notes":[]},{"n":24,"t":"因此，主—万军之耶和华、以色列的大能者说：哎！我要向我的对头雪恨，向我的敌人报仇。","notes":[]},{"n":25,"t":"我必反手加在你身上，炼尽你的渣滓，除净你的杂质。","notes":[]},{"n":26,"t":"我也必复还你的审判官，像起初一样，复还你的谋士，像起先一般。然后，你必称为公义之城，忠信之邑。","notes":[]},{"n":27,"t":"锡安必因公平得蒙救赎；其中归正的人必因公义得蒙救赎。","notes":[]},{"n":28,"t":"但悖逆的和犯罪的必一同败亡；离弃耶和华的必致消灭。","notes":[]},{"n":29,"t":"那等人必因你们所喜爱的橡树抱愧；你们必因所选择的园子蒙羞。","notes":[]},{"n":30,"t":"因为，你们必如叶子枯干的橡树，好像无水浇灌的园子。","notes":[]},{"n":31,"t":"有权势的必如麻瓤；他的工作好像火星，都要一同焚毁，无人扑灭。","notes":[]}]},"2":{"heading":"永恒的和平","verses":[{"n":1,"t":"亚摩斯的儿子以赛亚得默示，论到犹大和耶路撒冷。","notes":[]},{"n":2,"t":"末后的日子，耶和华殿的山必坚立，超乎诸山，高举过于万岭；万民都要流归这山。","notes":[]},{"n":3,"t":"必有许多国的民前往，说：来吧，我们登耶和华的山，奔雅各神的殿。主必将他的道教训我们；我们也要行他的路。因为训诲必出于锡安；耶和华的言语必出于耶路撒冷。","notes":[]},{"n":4,"t":"他必在列国中施行审判，为许多国民断定是非。他们要将刀打成犁头，把枪打成镰刀。这国不举刀攻击那国；他们也不再学习战事。","notes":[]},{"n":5,"t":"雅各家啊，来吧！我们在耶和华的光明中行走。","notes":[]},{"n":6,"t":"耶和华，你离弃了你百姓雅各家，是因他们充满了东方的风俗，作观兆的，像非利士人一样，并与外邦人击掌。","notes":[],"heads":["骄者必败"]},{"n":7,"t":"他们的国满了金银，财宝也无穷；他们的地满了马匹，车辆也无数。","notes":[]},{"n":8,"t":"他们的地满了偶像；他们跪拜自己手所造的，就是自己指头所做的。","notes":[]},{"n":9,"t":"卑贱人屈膝；尊贵人下跪；所以不可饶恕他们。","notes":[]},{"n":10,"t":"你当进入岩穴，藏在土中，躲避耶和华的惊吓和他威严的荣光。","notes":[]},{"n":11,"t":"到那日，眼目高傲的必降为卑；性情狂傲的都必屈膝；惟独耶和华被尊崇。","notes":[]},{"n":12,"t":"必有万军耶和华降罚的一个日子，要临到骄傲狂妄的；一切自高的都必降为卑；","notes":[]},{"n":13,"t":"又临到黎巴嫩高大的香柏树和巴珊的橡树；","notes":[]},{"n":14,"t":"又临到一切高山的峻岭；","notes":[]},{"n":15,"t":"又临到高台和坚固城墙；","notes":[]},{"n":16,"t":"又临到他施的船只并一切可爱的美物。","notes":[]},{"n":17,"t":"骄傲的必屈膝；狂妄的必降卑。在那日，惟独耶和华被尊崇；","notes":[]},{"n":18,"t":"偶像必全然废弃。","notes":[]},{"n":19,"t":"耶和华兴起，使地大震动的时候，人就进入石洞，进入土穴，躲避耶和华的惊吓和他威严的荣光。","notes":[]},{"n":20,"t":"到那日，人必将为拜而造的金偶像、银偶像抛给田鼠和蝙蝠。","notes":[]},{"n":21,"t":"到耶和华兴起，使地大震动的时候，人好进入磐石洞中和岩石穴里，躲避耶和华的惊吓和他威严的荣光。","notes":[]},{"n":22,"t":"你们休要倚靠世人。他鼻孔里不过有气息；他在一切事上可算什么呢？","notes":[]}]},"3":{"heading":"耶路撒冷的混乱","verses":[{"n":1,"t":"主—万军之耶和华从耶路撒冷和犹大，除掉众人所倚靠的，所仗赖的，就是所倚靠的粮，所仗赖的水；","notes":[]},{"n":2,"t":"除掉勇士和战士，审判官和先知，占卜的和长老，","notes":[]},{"n":3,"t":"五十夫长和尊贵人，谋士和有巧艺的，以及妙行法术的。","notes":[]},{"n":4,"t":"主说：我必使孩童作他们的首领，使婴孩辖管他们。","notes":[]},{"n":5,"t":"百姓要彼此欺压；各人受邻舍的欺压。少年人必侮慢老年人；卑贱人必侮慢尊贵人。","notes":[]},{"n":6,"t":"人在父家拉住弟兄，说：你有衣服，可以作我们的官长。这败落的事归在你手下吧！","notes":[]},{"n":7,"t":"那时，他必扬声说：我不作医治你们的人；因我家中没有粮食，也没有衣服，你们不可立我作百姓的官长。","notes":[]},{"n":8,"t":"耶路撒冷败落，犹大倾倒；因为他们的舌头和行为与耶和华反对，惹了他荣光的眼目。","notes":[]},{"n":9,"t":"他们的面色证明自己的不正；他们述说自己的罪恶，并不隐瞒，好像所多玛一样。他们有祸了！因为作恶自害。","notes":[]},{"n":10,"t":"你们要论义人说：他必享福乐，因为要吃自己行为所结的果子。","notes":[]},{"n":11,"t":"恶人有祸了！他必遭灾难！因为要照自己手所行的受报应。","notes":[]},{"n":12,"t":"至于我的百姓，孩童欺压他们，妇女辖管他们。我的百姓啊，引导你的使你走错，并毁坏你所行的道路。","notes":[]},{"n":13,"t":"耶和华起来辩论，站着审判众民。","notes":[],"heads":["耶和华审判他的人民"]},{"n":14,"t":"耶和华必审问他民中的长老和首领，说：吃尽葡萄园果子的就是你们；向贫穷人所夺的都在你们家中。","notes":[]},{"n":15,"t":"主—万军之耶和华说：你们为何压制我的百姓，搓磨贫穷人的脸呢？","notes":[]},{"n":16,"t":"耶和华又说：因为锡安的女子狂傲，行走挺项，卖弄眼目，俏步徐行，脚下玎珰，","notes":[],"heads":["对耶路撒冷女子的警告"]},{"n":17,"t":"所以，主必使锡安的女子头长秃疮；耶和华又使她们赤露下体。","notes":[]},{"n":18,"t":"到那日，主必除掉她们华美的脚钏、发网、月牙圈、","notes":[]},{"n":19,"t":"耳环、手镯、蒙脸的帕子、","notes":[]},{"n":20,"t":"华冠、足链、华带、香盒、符囊、","notes":[]},{"n":21,"t":"戒指、鼻环、","notes":[]},{"n":22,"t":"吉服、外套、云肩、荷包、","notes":[]},{"n":23,"t":"手镜、细麻衣、裹头巾、蒙身的帕子。","notes":[]},{"n":24,"t":"必有臭烂代替馨香，绳子代替腰带，光秃代替美发，麻衣系腰代替华服，烙伤代替美容。","notes":[]},{"n":25,"t":"你的男丁必倒在刀下；你的勇士必死在阵上。","notes":[]},{"n":26,"t":"锡安的城门必悲伤、哀号；她必荒凉坐在地上。","notes":["原文是她"]}]},"4":{"heading":"耶路撒冷的重建","verses":[{"n":1,"t":"在那日，七个女人必拉住一个男人，说：「我们吃自己的食物，穿自己的衣服，但求你许我们归你名下；求你除掉我们的羞耻。」","notes":[]},{"n":2,"t":"到那日，耶和华发生的苗必华美尊荣，地的出产必为以色列逃脱的人显为荣华茂盛。","notes":[]},{"n":3,"t":"主以公义的灵和焚烧的灵，将锡安女子的污秽洗去，又将耶路撒冷中杀人的血除净。那时，剩在锡安、留在耶路撒冷的，就是一切住耶路撒冷、在生命册上记名的，必称为圣。","notes":[],"end":4},{"n":5,"t":"耶和华也必在锡安全山，并各会众以上，使白日有烟云，黑夜有火焰的光。因为在全荣耀之上必有遮蔽。","notes":[]},{"n":6,"t":"必有亭子，白日可以得荫避暑，也可以作为藏身之处，躲避狂风暴雨。","notes":[]}]},"5":{"heading":"葡萄园之歌","verses":[{"n":1,"t":"我要为我所亲爱的唱歌，是我所爱者的歌，论他葡萄园的事：我所亲爱的有葡萄园在肥美的山冈上。","notes":[]},{"n":2,"t":"他刨挖园子，捡去石头，栽种上等的葡萄树，在园中盖了一座楼，又凿出压酒池；指望结好葡萄，反倒结了野葡萄。","notes":[]},{"n":3,"t":"耶路撒冷的居民和犹大人哪，请你们现今在我与我的葡萄园中，断定是非。","notes":[]},{"n":4,"t":"我为我葡萄园所做之外，还有什么可做的呢？我指望结好葡萄，怎么倒结了野葡萄呢？","notes":[]},{"n":5,"t":"现在我告诉你们，我要向我葡萄园怎样行：我必撤去篱笆，使它被吞灭，拆毁墙垣，使它被践踏。","notes":[]},{"n":6,"t":"我必使它荒废，不再修理，不再锄刨，荆棘蒺藜倒要生长。我也必命云不降雨在其上。","notes":[]},{"n":7,"t":"万军之耶和华的葡萄园就是以色列家；他所喜爱的树就是犹大人。他指望的是公平，谁知倒有暴虐；指望的是公义，谁知倒有冤声。","notes":["或译：倒流人血"]},{"n":8,"t":"祸哉！那些以房接房，以地连地，以致不留余地的，只顾自己独居境内。","notes":[],"heads":["人的恶行"]},{"n":9,"t":"我耳闻万军之耶和华说：必有许多又大又美的房屋成为荒凉，无人居住。","notes":[]},{"n":10,"t":"三十亩葡萄园只出一罢特酒；一贺梅珥谷种只结一伊法粮食。","notes":[]},{"n":11,"t":"祸哉！那些清早起来追求浓酒，留连到夜深，甚至因酒发烧的人。","notes":[]},{"n":12,"t":"他们在筵席上弹琴，鼓瑟，击鼓，吹笛，饮酒，却不顾念耶和华的作为，也不留心他手所做的。","notes":[]},{"n":13,"t":"所以，我的百姓因无知就被掳去；他们的尊贵人甚是饥饿，群众极其干渴。","notes":[]},{"n":14,"t":"故此，阴间扩张其欲，开了无限量的口；他们的荣耀、群众、繁华，并快乐的人都落在其中。","notes":[]},{"n":15,"t":"卑贱人被压服；尊贵人降为卑；眼目高傲的人也降为卑。","notes":[]},{"n":16,"t":"惟有万军之耶和华因公平而崇高；圣者神因公义显为圣。","notes":[]},{"n":17,"t":"那时，羊羔必来吃草，如同在自己的草场；丰肥人的荒场被游行的人吃尽。","notes":[]},{"n":18,"t":"祸哉！那些以虚假之细绳牵罪孽的人！他们又像以套绳拉罪恶，","notes":[]},{"n":19,"t":"说：任他急速行，赶快成就他的作为，使我们看看；任以色列圣者所谋划的临近成就，使我们知道。","notes":[]},{"n":20,"t":"祸哉！那些称恶为善，称善为恶，以暗为光，以光为暗，以苦为甜，以甜为苦的人。","notes":[]},{"n":21,"t":"祸哉！那些自以为有智慧，自看为通达的人。","notes":[]},{"n":22,"t":"祸哉！那些勇于饮酒，以能力调浓酒的人。","notes":[]},{"n":23,"t":"他们因受贿赂，就称恶人为义，将义人的义夺去。","notes":[]},{"n":24,"t":"火苗怎样吞灭碎秸，干草怎样落在火焰之中，照样，他们的根必像朽物，他们的花必像灰尘飞腾；因为他们厌弃万军之耶和华的训诲，藐视以色列圣者的言语。","notes":[]},{"n":25,"t":"所以，耶和华的怒气向他的百姓发作。他的手伸出攻击他们，山岭就震动；他们的尸首在街市上好像粪土。虽然如此，他的怒气还未转消；他的手仍伸不缩。","notes":[]},{"n":26,"t":"他必竖立大旗，招远方的国民，发嘶声叫他们从地极而来；看哪，他们必急速奔来。","notes":[]},{"n":27,"t":"其中没有疲倦的，绊跌的；没有打盹的，睡觉的；腰带并不放松，鞋带也不折断。","notes":[]},{"n":28,"t":"他们的箭快利，弓也上了弦。马蹄算如坚石，车轮好像旋风。","notes":[]},{"n":29,"t":"他们要吼叫，像母狮子，咆哮，像少壮狮子；他们要咆哮抓食，坦然叼去，无人救回。","notes":[]},{"n":30,"t":"那日，他们要向以色列人吼叫，像海浪匉訇；人若望地，只见黑暗艰难，光明在云中变为昏暗。","notes":[]}]},"6":{"heading":"主呼召以赛亚作先知","verses":[{"n":1,"t":"当乌西雅王崩的那年，我见主坐在高高的宝座上。他的衣裳垂下，遮满圣殿。","notes":[]},{"n":2,"t":"其上有撒拉弗侍立，各有六个翅膀：用两个翅膀遮脸，两个翅膀遮脚，两个翅膀飞翔；","notes":[]},{"n":3,"t":"彼此呼喊说：圣哉！圣哉！圣哉！万军之耶和华；他的荣光充满全地！","notes":[]},{"n":4,"t":"因呼喊者的声音，门槛的根基震动，殿充满了烟云。","notes":[]},{"n":5,"t":"那时我说：「祸哉！我灭亡了！因为我是嘴唇不洁的人，又住在嘴唇不洁的民中，又因我眼见大君王—万军之耶和华。」","notes":[]},{"n":6,"t":"有一撒拉弗飞到我跟前，手里拿着红炭，是用火剪从坛上取下来的，","notes":[]},{"n":7,"t":"将炭沾我的口，说：「看哪，这炭沾了你的嘴，你的罪孽便除掉，你的罪恶就赦免了。」","notes":[]},{"n":8,"t":"我又听见主的声音说：「我可以差遣谁呢？谁肯为我们去呢？」我说：「我在这里，请差遣我！」","notes":[]},{"n":9,"t":"他说：「你去告诉这百姓说：你们听是要听见，却不明白；看是要看见，却不晓得。","notes":[]},{"n":10,"t":"要使这百姓心蒙脂油，耳朵发沉，眼睛昏迷；恐怕眼睛看见，耳朵听见，心里明白，回转过来，便得医治。」","notes":[]},{"n":11,"t":"我就说：「主啊，这到几时为止呢？」他说：直到城邑荒凉，无人居住，房屋空闲无人，地土极其荒凉。","notes":[]},{"n":12,"t":"并且耶和华将人迁到远方，在这境内撇下的地土很多。","notes":[]},{"n":13,"t":"境内剩下的人若还有十分之一，也必被吞灭，像栗树、橡树虽被砍伐，树墩子却仍存留。这圣洁的种类在国中也是如此。","notes":[]}]},"7":{"heading":"传给亚哈斯王的信息","verses":[{"n":1,"t":"乌西雅的孙子、约坦的儿子、犹大王亚哈斯在位的时候，亚兰王利汛和利玛利的儿子、以色列王比加上来攻打耶路撒冷，却不能攻取。","notes":[]},{"n":2,"t":"有人告诉大卫家说：「亚兰与以法莲已经同盟。」王的心和百姓的心就都跳动，好像林中的树被风吹动一样。","notes":[]},{"n":3,"t":"耶和华对以赛亚说：「你和你的儿子施亚雅述出去，到上池的水沟头，在漂布地的大路上，去迎接亚哈斯，","notes":[]},{"n":4,"t":"对他说：『你要谨慎安静，不要因亚兰王利汛和利玛利的儿子这两个冒烟的火把头所发的烈怒害怕，也不要心里胆怯。","notes":[]},{"n":5,"t":"因为亚兰和以法莲，并利玛利的儿子，设恶谋害你，","notes":[]},{"n":6,"t":"说：我们可以上去攻击犹大，扰乱它，攻破它，在其中立他比勒的儿子为王。","notes":[]},{"n":7,"t":"所以主耶和华如此说：这所谋的必立不住，也不得成就。","notes":[]},{"n":8,"t":"原来亚兰的首城是大马士革；大马士革的首领是利汛。（六十五年之内，以法莲必然破坏，不再成为国民。）","notes":[]},{"n":9,"t":"以法莲的首城是撒马利亚；撒马利亚的首领是利玛利的儿子。你们若是不信，定然不得立稳。』」","notes":[]},{"n":10,"t":"耶和华又晓谕亚哈斯说：","notes":[],"heads":["以马内利的记号"]},{"n":11,"t":"「你向耶和华—你的神求一个兆头：或求显在深处，或求显在高处。」","notes":[]},{"n":12,"t":"亚哈斯说：「我不求；我不试探耶和华。」","notes":[]},{"n":13,"t":"以赛亚说：「大卫家啊，你们当听！你们使人厌烦岂算小事，还要使我的神厌烦吗？","notes":[]},{"n":14,"t":"因此，主自己要给你们一个兆头，必有童女怀孕生子，给他起名叫以马内利。","notes":["就是神与我们同在的意思"]},{"n":15,"t":"到他晓得弃恶择善的时候，他必吃奶油与蜂蜜。","notes":[]},{"n":16,"t":"因为在这孩子还不晓得弃恶择善之先，你所憎恶的那二王之地必致见弃。","notes":[]},{"n":17,"t":"耶和华必使亚述王攻击你的日子临到你和你的百姓，并你的父家，自从以法莲离开犹大以来，未曾有这样的日子。","notes":[]},{"n":18,"t":"「那时，耶和华要发嘶声，使埃及江河源头的苍蝇和亚述地的蜂子飞来；","notes":[]},{"n":19,"t":"都必飞来，落在荒凉的谷内、磐石的穴里，和一切荆棘篱笆中，并一切的草场上。","notes":[]},{"n":20,"t":"「那时，主必用大河外赁的剃头刀，就是亚述王，剃去头发和脚上的毛，并要剃净胡须。","notes":[]},{"n":21,"t":"「那时，一个人要养活一只母牛犊，两只母绵羊；","notes":[]},{"n":22,"t":"因为出的奶多，他就得吃奶油，在境内所剩的人都要吃奶油与蜂蜜。","notes":[]},{"n":23,"t":"「从前，凡种一千棵葡萄树、值银一千舍客勒的地方，到那时必长荆棘和蒺藜。","notes":[]},{"n":24,"t":"人上那里去，必带弓箭，因为遍地满了荆棘和蒺藜。","notes":[]},{"n":25,"t":"所有用锄刨挖的山地，你因怕荆棘和蒺藜，不敢上那里去；只可成了放牛之处，为羊践踏之地。」","notes":[]}]},"8":{"heading":"用以赛亚的儿子作为记号","verses":[{"n":1,"t":"耶和华对我说：「你取一个大牌，拿人所用的笔，写上『玛黑珥·沙拉勒·哈施·罢斯』。","notes":["或译：人常用的字","就是掳掠速临、抢夺快到的意思"]},{"n":2,"t":"我要用诚实的见证人，祭司乌利亚和耶比利家的儿子撒迦利亚记录这事。」","notes":[]},{"n":3,"t":"我—以赛亚与妻子同室；她怀孕生子，耶和华就对我说：「给他起名叫玛黑珥·沙拉勒·哈施·罢斯；","notes":["原文是女先知"]},{"n":4,"t":"因为在这小孩子不晓得叫父叫母之先，大马士革的财宝和撒马利亚的掳物必在亚述王面前搬了去。」","notes":[]},{"n":5,"t":"耶和华又晓谕我说：","notes":[],"heads":["亚述王快来了"]},{"n":6,"t":"「这百姓既厌弃西罗亚缓流的水，喜悦利汛和利玛利的儿子；","notes":[]},{"n":7,"t":"因此，主必使大河翻腾的水猛然冲来，就是亚述王和他所有的威势，必漫过一切的水道，涨过两岸；","notes":[]},{"n":8,"t":"必冲入犹大，涨溢泛滥，直到颈项。以马内利啊，他展开翅膀，遍满你的地。」","notes":[]},{"n":9,"t":"列国的人民哪，任凭你们喧嚷，终必破坏；远方的众人哪，当侧耳而听！任凭你们束起腰来，终必破坏；你们束起腰来，终必破坏。","notes":[]},{"n":10,"t":"任凭你们同谋，终归无有；任凭你们言定，终不成立；因为神与我们同在。","notes":[]},{"n":11,"t":"耶和华以大能的手，指教我不可行这百姓所行的道，对我这样说：","notes":[],"heads":["耶和华警告先知"]},{"n":12,"t":"「这百姓说同谋背叛，你们不要说同谋背叛。他们所怕的，你们不要怕，也不要畏惧。","notes":[]},{"n":13,"t":"但要尊万军之耶和华为圣，以他为你们所当怕的，所当畏惧的。","notes":[]},{"n":14,"t":"他必作为圣所，却向以色列两家作绊脚的石头，跌人的磐石；向耶路撒冷的居民作为圈套和网罗。","notes":[]},{"n":15,"t":"许多人必在其上绊脚跌倒，而且跌碎，并陷入网罗，被缠住。」","notes":[]},{"n":16,"t":"你要卷起律法书，在我门徒中间封住训诲。","notes":[],"heads":["不可求问死人"]},{"n":17,"t":"我要等候那掩面不顾雅各家的耶和华；我也要仰望他。","notes":[]},{"n":18,"t":"看哪，我与耶和华所给我的儿女，就是从住在锡安山万军之耶和华来的，在以色列中作为预兆和奇迹。","notes":[]},{"n":19,"t":"有人对你们说：「当求问那些交鬼的和行巫术的，就是声音绵蛮，言语微细的。」你们便回答说：「百姓不当求问自己的神吗？岂可为活人求问死人呢？」","notes":[]},{"n":20,"t":"人当以训诲和法度为标准；他们所说的，若不与此相符，必不得见晨光。","notes":[]},{"n":21,"t":"他们必经过这地，受艰难，受饥饿；饥饿的时候，心中焦躁，咒骂自己的君王和自己的神。","notes":[],"heads":["遭难的时候"]},{"n":22,"t":"仰观上天，俯察下地，不料，尽是艰难、黑暗，和幽暗的痛苦。他们必被赶入乌黑的黑暗中去。","notes":[]}]},"9":{"heading":"未来的君王","verses":[{"n":1,"t":"但那受过痛苦的必不再见幽暗。从前神使西布伦地和拿弗他利地被藐视，末后却使这沿海的路，约旦河外，外邦人的加利利地得着荣耀。","notes":[]},{"n":2,"t":"在黑暗中行走的百姓看见了大光；住在死荫之地的人有光照耀他们。","notes":[]},{"n":3,"t":"你使这国民繁多，加增他们的喜乐；他们在你面前欢喜，好像收割的欢喜，像人分掳物那样的快乐。","notes":[]},{"n":4,"t":"因为他们所负的重轭和肩头上的杖，并欺压他们人的棍，你都已经折断，好像在米甸的日子一样。","notes":[]},{"n":5,"t":"战士在乱杀之间所穿戴的盔甲，并那滚在血中的衣服，都必作为可烧的，当作火柴。","notes":[]},{"n":6,"t":"因有一婴孩为我们而生；有一子赐给我们。政权必担在他的肩头上；他名称为「奇妙策士、全能的神、永在的父、和平的君」。","notes":[]},{"n":7,"t":"他的政权与平安必加增无穷。他必在大卫的宝座上治理他的国，以公平公义使国坚定稳固，从今直到永远。万军之耶和华的热心必成就这事。","notes":[]},{"n":8,"t":"主使一言入于雅各家，落于以色列家。","notes":[],"heads":["耶和华要惩罚以色列"]},{"n":9,"t":"这众百姓，就是以法莲和撒马利亚的居民，都要知道；他们凭骄傲自大的心说：","notes":[]},{"n":10,"t":"砖墙塌了，我们却要凿石头建筑；桑树砍了，我们却要换香柏树。","notes":[]},{"n":11,"t":"因此，耶和华要高举利汛的敌人来攻击以色列，并要激动以色列的仇敌。","notes":[]},{"n":12,"t":"东有亚兰人，西有非利士人；他们张口要吞吃以色列。虽然如此，耶和华的怒气还未转消；他的手仍伸不缩。","notes":[]},{"n":13,"t":"这百姓还没有归向击打他们的主，也没有寻求万军之耶和华。","notes":[]},{"n":14,"t":"因此，耶和华一日之间必从以色列中剪除头与尾，棕枝与芦苇—","notes":[]},{"n":15,"t":"长老和尊贵人就是头，以谎言教人的先知就是尾。","notes":[]},{"n":16,"t":"因为，引导这百姓的使他们走错了路；被引导的都必败亡。","notes":[]},{"n":17,"t":"所以，主必不喜悦他们的少年人，也不怜恤他们的孤儿寡妇；因为，各人是亵渎的，是行恶的，并且各人的口都说愚妄的话。虽然如此，耶和华的怒气还未转消；他的手仍伸不缩。","notes":[]},{"n":18,"t":"邪恶像火焚烧，烧灭荆棘和蒺藜，在稠密的树林中着起来，就成为烟柱，旋转上腾。","notes":[]},{"n":19,"t":"因万军之耶和华的烈怒，地都烧遍；百姓成为火柴；无人怜爱弟兄。","notes":[]},{"n":20,"t":"有人右边抢夺，仍受饥饿，左边吞吃，仍不饱足；各人吃自己膀臂上的肉。","notes":[]},{"n":21,"t":"玛拿西吞吃以法莲；以法莲吞吃玛拿西，又一同攻击犹大。虽然如此，耶和华的怒气还未转消；他的手仍伸不缩。","notes":["或译：攻击；下同"]}]},"10":{"heading":"神用亚述王为工具","verses":[{"n":1,"t":"祸哉！那些设立不义之律例的和记录奸诈之判语的，","notes":[]},{"n":2,"t":"为要屈枉穷乏人，夺去我民中困苦人的理，以寡妇当作掳物，以孤儿当作掠物。","notes":[]},{"n":3,"t":"到降罚的日子，有灾祸从远方临到，那时，你们怎样行呢？你们向谁逃奔求救呢？你们的荣耀存留何处呢？","notes":["或译：财宝"]},{"n":4,"t":"他们只得屈身在被掳的人以下，仆倒在被杀的人以下。虽然如此，耶和华的怒气还未转消；他的手仍伸不缩。","notes":[]},{"n":5,"t":"亚述是我怒气的棍，手中拿我恼恨的杖。","notes":[]},{"n":6,"t":"我要打发他攻击亵渎的国民，吩咐他攻击我所恼怒的百姓，抢财为掳物，夺货为掠物，将他们践踏，像街上的泥土一样。","notes":[]},{"n":7,"t":"然而，他不是这样的意思；他心也不这样打算。他心里倒想毁灭，剪除不少的国。","notes":[]},{"n":8,"t":"他说：我的臣仆岂不都是王吗？","notes":[]},{"n":9,"t":"迦勒挪岂不像迦基米施吗？哈马岂不像亚珥拔吗？撒马利亚岂不像大马士革吗？","notes":[]},{"n":10,"t":"我手已经搆到有偶像的国；这些国雕刻的偶像过于耶路撒冷和撒马利亚的偶像。","notes":[]},{"n":11,"t":"我怎样待撒马利亚和其中的偶像，岂不照样待耶路撒冷和其中的偶像吗？","notes":[]},{"n":12,"t":"主在锡安山和耶路撒冷成就他一切工作的时候，主说：「我必罚亚述王自大的心和他高傲眼目的荣耀。」","notes":[]},{"n":13,"t":"因为他说：我所成就的事是靠我手的能力和我的智慧，我本有聪明。我挪移列国的地界，抢夺他们所积蓄的财宝；并且我像勇士，使坐宝座的降为卑。","notes":[]},{"n":14,"t":"我的手搆到列国的财宝，好像人搆到鸟窝；我也得了全地，好像人拾起所弃的雀蛋。没有动翅膀的；没有张嘴的，也没有鸣叫的。","notes":[]},{"n":15,"t":"斧岂可向用斧砍木的自夸呢？锯岂可向用锯的自大呢？好比棍抡起那举棍的，好比杖举起那非木的人。","notes":[]},{"n":16,"t":"因此，主—万军之耶和华必使亚述王的肥壮人变为瘦弱，在他的荣华之下必有火着起，如同焚烧一样。","notes":[]},{"n":17,"t":"以色列的光必如火；他的圣者必如火焰。在一日之间，将亚述王的荆棘和蒺藜焚烧净尽；","notes":[]},{"n":18,"t":"又将他树林和肥田的荣耀全然烧尽，好像拿军旗的昏过去一样。","notes":[]},{"n":19,"t":"他林中剩下的树必稀少，就是孩子也能写其数。","notes":[]},{"n":20,"t":"到那日，以色列所剩下的和雅各家所逃脱的，不再倚靠那击打他们的，却要诚实倚靠耶和华—以色列的圣者。","notes":[],"heads":["残存之民归回"]},{"n":21,"t":"所剩下的，就是雅各家所剩下的，必归回全能的神。","notes":[]},{"n":22,"t":"以色列啊，你的百姓虽多如海沙，惟有剩下的归回。原来灭绝的事已定，必有公义施行，如水涨溢。","notes":[]},{"n":23,"t":"因为主—万军之耶和华在全地之中必成就所定规的结局。","notes":[]},{"n":24,"t":"所以，主—万军之耶和华如此说：「住锡安我的百姓啊，亚述王虽然用棍击打你，又照埃及的样子举杖攻击你，你却不要怕他。","notes":[],"heads":["耶和华要惩罚亚述"]},{"n":25,"t":"因为还有一点点时候，向你们发的忿恨就要完毕，我的怒气要向他发作，使他灭亡。","notes":[]},{"n":26,"t":"万军之耶和华要兴起鞭来攻击他，好像在俄立磐石那里杀戮米甸人一样。耶和华的杖要向海伸出，把杖举起，像在埃及一样。","notes":[]},{"n":27,"t":"到那日，亚述王的重担必离开你的肩头；他的轭必离开你的颈项；那轭也必因肥壮的缘故撑断。」","notes":["或译：因膏油的缘故毁坏"]},{"n":28,"t":"亚述王来到亚叶，经过米矶仑，在密抹安放辎重。","notes":[],"heads":["侵略者进攻"]},{"n":29,"t":"他们过了隘口，在迦巴住宿。拉玛人战兢；扫罗的基比亚人逃跑。","notes":[]},{"n":30,"t":"迦琳的居民哪，要高声呼喊！莱煞人哪，须听！哀哉！困苦的亚拿突啊。","notes":["原文是女子"]},{"n":31,"t":"玛得米那人躲避；基柄的居民逃遁。","notes":[]},{"n":32,"t":"当那日，亚述王要在挪伯歇兵，向锡安女子的山—就是耶路撒冷的山—抡手攻他。","notes":[]},{"n":33,"t":"看哪，主—万军之耶和华以惊吓削去树枝；长高的必被砍下，高大的必被伐倒。","notes":[]},{"n":34,"t":"稠密的树林，他要用铁器砍下；黎巴嫩的树木必被大能者伐倒。","notes":[]}]},"11":{"heading":"和平的国度","verses":[{"n":1,"t":"从耶西的本必发一条；从他根生的枝子必结果实。","notes":["原文是墩"]},{"n":2,"t":"耶和华的灵必住在他身上，就是使他有智慧和聪明的灵，谋略和能力的灵，知识和敬畏耶和华的灵。","notes":[]},{"n":3,"t":"他必以敬畏耶和华为乐；行审判不凭眼见，断是非也不凭耳闻；","notes":[]},{"n":4,"t":"却要以公义审判贫穷人，以正直判断世上的谦卑人，以口中的杖击打世界，以嘴里的气杀戮恶人。","notes":[]},{"n":5,"t":"公义必当他的腰带；信实必当他胁下的带子。","notes":[]},{"n":6,"t":"豺狼必与绵羊羔同居，豹子与山羊羔同卧；少壮狮子与牛犊并肥畜同群；小孩子要牵引它们。","notes":[]},{"n":7,"t":"牛必与熊同食；牛犊必与小熊同卧；狮子必吃草，与牛一样。","notes":[]},{"n":8,"t":"吃奶的孩子必玩耍在虺蛇的洞口；断奶的婴儿必按手在毒蛇的穴上。","notes":[]},{"n":9,"t":"在我圣山的遍处，这一切都不伤人，不害物；因为认识耶和华的知识要充满遍地，好像水充满洋海一般。","notes":[]},{"n":10,"t":"到那日，耶西的根立作万民的大旗；外邦人必寻求他，他安息之所大有荣耀。","notes":[],"heads":["流亡的人回乡"]},{"n":11,"t":"当那日，主必二次伸手救回自己百姓中所余剩的，就是在亚述、埃及、巴忒罗、古实、以拦、示拿、哈马，并众海岛所剩下的。","notes":[]},{"n":12,"t":"他必向列国竖立大旗，招回以色列被赶散的人，又从地的四方聚集分散的犹大人。","notes":[]},{"n":13,"t":"以法莲的嫉妒就必消散；扰害犹大的必被剪除。以法莲必不嫉妒犹大，犹大也不扰害以法莲。","notes":[]},{"n":14,"t":"他们要向西飞，扑在非利士人的肩头上，一同掳掠东方人，伸手按住以东和摩押；亚扪人也必顺服他们。","notes":["肩头上：或译西界"]},{"n":15,"t":"耶和华必使埃及海汊枯干，抡手用暴热的风使大河分为七条，令人过去不致湿脚。","notes":[]},{"n":16,"t":"为主余剩的百姓，就是从亚述剩下回来的，必有一条大道，如当日以色列从埃及地上来一样。","notes":[]}]},"12":{"heading":"感恩的诗歌","verses":[{"n":1,"t":"到那日，你必说：耶和华啊，我要称谢你！因为你虽然向我发怒，你的怒气却已转消；你又安慰了我。","notes":[]},{"n":2,"t":"看哪！神是我的拯救；我要倚靠他，并不惧怕。因为主耶和华是我的力量，是我的诗歌，他也成了我的拯救。","notes":[]},{"n":3,"t":"所以，你们必从救恩的泉源欢然取水。","notes":[]},{"n":4,"t":"在那日，你们要说：当称谢耶和华，求告他的名；将他所行的传扬在万民中，提说他的名已被尊崇。","notes":[]},{"n":5,"t":"你们要向耶和华唱歌，因他所行的甚是美好；但愿这事普传天下。","notes":[]},{"n":6,"t":"锡安的居民哪，当扬声欢呼，因为在你们中间的以色列圣者乃为至大。","notes":[]}]},"13":{"heading":"神要惩罚巴比伦","verses":[{"n":1,"t":"亚摩斯的儿子以赛亚得默示，论巴比伦。","notes":[]},{"n":2,"t":"应当在净光的山竖立大旗，向群众扬声招手，使他们进入贵胄的门。","notes":[]},{"n":3,"t":"我吩咐我所挑出来的人；我招呼我的勇士—就是那矜夸高傲之辈，为要成就我怒中所定的。","notes":[]},{"n":4,"t":"山间有多人的声音，好像是大国人民。有许多国的民聚集哄嚷的声音；这是万军之耶和华点齐军队，预备打仗。","notes":[]},{"n":5,"t":"他们从远方来，从天边来，就是耶和华并他恼恨的兵器要毁灭这全地。","notes":[]},{"n":6,"t":"你们要哀号，因为耶和华的日子临近了！这日来到，好像毁灭从全能者来到。","notes":[]},{"n":7,"t":"所以，人手都必软弱；人心都必消化。","notes":[]},{"n":8,"t":"他们必惊惶悲痛；愁苦必将他们抓住。他们疼痛，好像产难的妇人一样，彼此惊奇相看，脸如火焰。","notes":[]},{"n":9,"t":"耶和华的日子临到，必有残忍、忿恨、烈怒，使这地荒凉，从其中除灭罪人。","notes":[]},{"n":10,"t":"天上的众星群宿都不发光；日头一出就变黑暗；月亮也不放光。","notes":[]},{"n":11,"t":"我必因邪恶刑罚世界，因罪孽刑罚恶人，使骄傲人的狂妄止息，制伏强暴人的狂傲。","notes":[]},{"n":12,"t":"我必使人比精金还少，使人比俄斐纯金更少。","notes":[]},{"n":13,"t":"我—万军之耶和华在忿恨中发烈怒的日子，必使天震动，使地摇撼，离其本位。","notes":[]},{"n":14,"t":"人必像被追赶的鹿，像无人收聚的羊，各归回本族，各逃到本土。","notes":[]},{"n":15,"t":"凡被仇敌追上的必被刺死；凡被捉住的必被刀杀。","notes":[]},{"n":16,"t":"他们的婴孩必在他们眼前摔碎；他们的房屋必被抢夺；他们的妻子必被玷污。","notes":[]},{"n":17,"t":"我必激动米底亚人来攻击他们。米底亚人不注重银子，也不喜爱金子。","notes":[]},{"n":18,"t":"他们必用弓击碎少年人，不怜悯妇人所生的，眼也不顾惜孩子。","notes":[]},{"n":19,"t":"巴比伦素来为列国的荣耀，为迦勒底人所矜夸的华美，必像神所倾覆的所多玛、蛾摩拉一样。","notes":[]},{"n":20,"t":"其内必永无人烟，世世代代无人居住。阿拉伯人也不在那里支搭帐棚；牧羊的人也不使羊群卧在那里。","notes":[]},{"n":21,"t":"只有旷野的走兽卧在那里；咆哮的兽满了房屋。鸵鸟住在那里；野山羊在那里跳舞。","notes":[]},{"n":22,"t":"豺狼必在它宫中呼号；野狗必在它华美殿内吼叫。巴比伦受罚的时候临近；它的日子必不长久。","notes":[]}]},"14":{"heading":"从流亡中归回","verses":[{"n":1,"t":"耶和华要怜恤雅各，必再拣选以色列，将他们安置在本地。寄居的必与他们联合，紧贴雅各家。","notes":[]},{"n":2,"t":"外邦人必将他们带回本土；以色列家必在耶和华的地上得外邦人为仆婢，也要掳掠先前掳掠他们的，辖制先前欺压他们的。","notes":[]},{"n":3,"t":"当耶和华使你脱离愁苦、烦恼，并人勉强你做的苦工，得享安息的日子，","notes":[],"heads":["巴比伦王下到阴间"]},{"n":4,"t":"你必题这诗歌论巴比伦王说：欺压人的何竟息灭？强暴的何竟止息？","notes":[]},{"n":5,"t":"耶和华折断了恶人的杖，辖制人的圭，","notes":[]},{"n":6,"t":"就是在忿怒中连连攻击众民的，在怒气中辖制列国，行逼迫无人阻止的。","notes":[]},{"n":7,"t":"现在全地得安息，享平静；人皆发声欢呼。","notes":[]},{"n":8,"t":"松树和黎巴嫩的香柏树都因你欢乐，说：自从你仆倒，再无人上来砍伐我们。","notes":[]},{"n":9,"t":"你下到阴间，阴间就因你震动来迎接你，又因你惊动在世曾为首领的阴魂，并使那曾为列国君王的，都离位站起。","notes":[]},{"n":10,"t":"他们都要发言对你说：你也变为软弱像我们一样吗？你也成了我们的样子吗？","notes":[]},{"n":11,"t":"你的威势和你琴瑟的声音都下到阴间。你下铺的是虫，上盖的是蛆。","notes":[]},{"n":12,"t":"明亮之星，早晨之子啊，你何竟从天坠落？你这攻败列国的何竟被砍倒在地上？","notes":[]},{"n":13,"t":"你心里曾说：我要升到天上；我要高举我的宝座在神众星以上；我要坐在聚会的山上，在北方的极处。","notes":[]},{"n":14,"t":"我要升到高云之上；我要与至上者同等。","notes":[]},{"n":15,"t":"然而，你必坠落阴间，到坑中极深之处。","notes":[]},{"n":16,"t":"凡看见你的都要定睛看你，留意看你，说：使大地战抖，使列国震动，","notes":[]},{"n":17,"t":"使世界如同荒野，使城邑倾覆，不释放被掳的人归家，是这个人吗？","notes":[]},{"n":18,"t":"列国的君王俱各在自己阴宅的荣耀中安睡。","notes":[]},{"n":19,"t":"惟独你被抛弃，不得入你的坟墓，好像可憎的枝子，以被杀的人为衣，就是被刀刺透，坠落坑中石头那里的；你又像被践踏的尸首一样。","notes":[]},{"n":20,"t":"你不得与君王同葬；因为你败坏你的国，杀戮你的民。恶人后裔的名，必永不提说。","notes":[]},{"n":21,"t":"先人既有罪孽，就要预备杀戮他的子孙，免得他们兴起来，得了遍地，在世上修满城邑。","notes":[]},{"n":22,"t":"万军之耶和华说：我必兴起攻击他们，将巴比伦的名号和所余剩的人，连子带孙一并剪除。这是耶和华说的。","notes":[],"heads":["神要毁灭巴比伦"]},{"n":23,"t":"我必使巴比伦为箭猪所得，又变为水池；我要用灭亡的扫帚扫净它。这是万军之耶和华说的。","notes":[]},{"n":24,"t":"万军之耶和华起誓说：我怎样思想，必照样成就；我怎样定意，必照样成立，","notes":[],"heads":["神要毁灭亚述"]},{"n":25,"t":"就是在我地上打折亚述人，在我山上将他践踏。他加的轭必离开以色列人；他加的重担必离开他们的肩头。","notes":[]},{"n":26,"t":"这是向全地所定的旨意；这是向万国所伸出的手。","notes":[]},{"n":27,"t":"万军之耶和华既然定意，谁能废弃呢？他的手已经伸出，谁能转回呢？","notes":[]},{"n":28,"t":"亚哈斯王崩的那年，就有以下的默示：","notes":[],"heads":["神要毁灭非利士"]},{"n":29,"t":"非利士全地啊，不要因击打你的杖折断就喜乐。因为从蛇的根必生出毒蛇；它所生的是火焰的飞龙。","notes":[]},{"n":30,"t":"贫寒人的长子必有所食；穷乏人必安然躺卧。我必以饥荒治死你的根；你所余剩的人必被杀戮。","notes":[]},{"n":31,"t":"门哪，应当哀号！城啊，应当呼喊！非利士全地啊，你都消化了！因为有烟从北方出来，他行伍中并无乱队的。","notes":[]},{"n":32,"t":"可怎样回答外邦的使者呢？必说：耶和华建立了锡安；他百姓中的困苦人必投奔在其中。","notes":["或指非利士"]}]},"15":{"heading":"神要毁灭摩押","verses":[{"n":1,"t":"论摩押的默示：一夜之间，摩押的亚珥变为荒废，归于无有；一夜之间，摩押的基珥变为荒废，归于无有。","notes":[]},{"n":2,"t":"他们上巴益，又往底本，到高处去哭泣。摩押人因尼波和米底巴哀号，各人头上光秃，胡须剃净。","notes":[]},{"n":3,"t":"他们在街市上都腰束麻布，在房顶上和宽阔处俱各哀号，眼泪汪汪。","notes":[]},{"n":4,"t":"希实本和以利亚利悲哀的声音达到雅杂，所以摩押带兵器的高声喊嚷，人心战兢。","notes":[]},{"n":5,"t":"我心为摩押悲哀；他的贵胄逃到琐珥，到伊基拉·施利施亚。他们上鲁希坡，随走随哭；在何罗念的路上，因毁灭举起哀声。","notes":["或译：逃民"]},{"n":6,"t":"因为宁林的水成为干涸，青草枯干，嫩草灭没，青绿之物，一无所有。","notes":[]},{"n":7,"t":"因此，摩押人所得的财物和所积蓄的都要运过柳树河。","notes":[]},{"n":8,"t":"哀声遍闻摩押的四境；哀号的声音达到以基莲；哀号的声音达到比珥·以琳。","notes":[]},{"n":9,"t":"底们的水充满了血；我还要加增底们的灾难，叫狮子来追上摩押逃脱的民和那地上所余剩的人。","notes":[]}]},"16":{"heading":"摩押的难民逃到犹大","verses":[{"n":1,"t":"你们当将羊羔奉给那地掌权的，从西拉往旷野，送到锡安城的山。","notes":["原文是女子"]},{"n":2,"t":"摩押的居民在亚嫩渡口，必像游飞的鸟，如拆窝的雏。","notes":["原文是女子"]},{"n":3,"t":"求你献谋略，行公平，使你的影子在午间如黑夜，隐藏被赶散的人，不可显露逃民。","notes":[]},{"n":4,"t":"求你容我这被赶散的人和你同居。至于摩押，求你作他的隐密处，脱离灭命者的面。勒索人的归于无有，毁灭的事止息了，欺压人的从国中除灭了，","notes":[]},{"n":5,"t":"必有宝座因慈爱坚立；必有一位诚诚实实坐在其上，在大卫帐幕中施行审判，寻求公平，速行公义。","notes":[]},{"n":6,"t":"我们听说摩押人骄傲，是极其骄傲；听说他狂妄、骄傲、忿怒；他夸大的话是虚空的。","notes":[]},{"n":7,"t":"因此，摩押人必为摩押哀号；人人都要哀号。你们摩押人要为吉珥·哈列设的葡萄饼哀叹，极其忧伤。","notes":[]},{"n":8,"t":"因为希实本的田地和西比玛的葡萄树都衰残了。列国的君主折断其上美好的枝子；这枝子长到雅谢延到旷野，嫩枝向外探出，直探过盐海。","notes":[]},{"n":9,"t":"因此，我要为西比玛的葡萄树哀哭，与雅谢人哀哭一样。希实本、以利亚利啊，我要以眼泪浇灌你；因为有交战呐喊的声音临到你夏天的果子，并你收割的庄稼。","notes":[]},{"n":10,"t":"从肥美的田中夺去了欢喜快乐；在葡萄园里必无歌唱，也无欢呼的声音。踹酒的在酒榨中不得踹出酒来；我使他欢呼的声音止息。","notes":[]},{"n":11,"t":"因此，我心腹为摩押哀鸣如琴；我心肠为吉珥·哈列设也是如此。","notes":[]},{"n":12,"t":"摩押人朝见的时候，在高处疲乏，又到他圣所祈祷，也不蒙应允。","notes":[]},{"n":13,"t":"这是耶和华从前论摩押的话。","notes":[]},{"n":14,"t":"但现在耶和华说：「三年之内，照雇工的年数，摩押的荣耀与他的群众必被藐视，余剩的人甚少无几。」","notes":[]}]},"17":{"heading":"神要刑罚亚兰和以色列","verses":[{"n":1,"t":"论大马士革的默示：看哪，大马士革已被废弃，不再为城，必变作乱堆。","notes":[]},{"n":2,"t":"亚罗珥的城邑已被撇弃，必成为牧羊之处；羊在那里躺卧，无人惊吓。","notes":[]},{"n":3,"t":"以法莲不再有保障；大马士革不再有国权；亚兰所剩下的必像以色列人的荣耀消灭一样。这是万军之耶和华说的。","notes":[]},{"n":4,"t":"到那日，雅各的荣耀必至枵薄；他肥胖的身体必渐瘦弱。","notes":[]},{"n":5,"t":"就必像收割的人收敛禾稼，用手割取穗子，又像人在利乏音谷拾取遗落的穗子。","notes":[]},{"n":6,"t":"其间所剩下的不多，好像人打橄榄树—在尽上的枝梢上只剩两三个果子；在多果树的旁枝上只剩四五个果子。这是耶和华—以色列的神说的。","notes":[]},{"n":7,"t":"当那日，人必仰望造他们的主，眼目重看以色列的圣者。","notes":[]},{"n":8,"t":"他们必不仰望祭坛，就是自己手所筑的，也不重看自己指头所做的，无论是木偶是日像。","notes":[]},{"n":9,"t":"在那日，他们的坚固城必像树林中和山顶上所撇弃的地方，就是从前在以色列人面前被人撇弃的。这样，地就荒凉了。","notes":[]},{"n":10,"t":"因你忘记救你的神，不记念你能力的磐石；所以，你栽上佳美的树秧子，插上异样的栽子。","notes":[]},{"n":11,"t":"栽种的日子，你周围圈上篱笆，又到早晨使你所种的开花；但在愁苦极其伤痛的日子，所收割的都飞去了。","notes":[]},{"n":12,"t":"唉！多民哄嚷，好像海浪匉訇；列邦奔腾，好像猛水滔滔；","notes":[],"heads":["敌国都被击败"]},{"n":13,"t":"列邦奔腾，好像多水滔滔；但神斥责他们，他们就远远逃避，又被追赶，如同山上的风前糠，又如暴风前的旋风土。","notes":[]},{"n":14,"t":"到晚上有惊吓，未到早晨他们就没有了。这是掳掠我们之人所得的分，是抢夺我们之人的报应。","notes":[]}]},"18":{"heading":"神要责罚古实","verses":[{"n":1,"t":"唉！古实河外翅膀刷刷响声之地，","notes":[]},{"n":2,"t":"差遣使者在水面上，坐蒲草船过海。先知说：你们快行的使者，要到高大光滑的民那里去。自从开国以来，那民极其可畏，是分地界践踏人的；他们的地有江河分开。","notes":[]},{"n":3,"t":"世上一切的居民和地上所住的人哪，山上竖立大旗的时候你们要看；吹角的时候你们要听。","notes":[]},{"n":4,"t":"耶和华对我这样说：我要安静，在我的居所观看，如同日光中的清热，又如露水的云雾在收割的热天。","notes":[]},{"n":5,"t":"收割之先，花开已谢，花也成了将熟的葡萄；他必用镰刀削去嫩枝，又砍掉蔓延的枝条，","notes":[]},{"n":6,"t":"都要撇给山间的鸷鸟和地上的野兽。夏天，鸷鸟要宿在其上；冬天，野兽都卧在其中。","notes":[]},{"n":7,"t":"到那时，这高大光滑的民，就是从开国以来极其可畏、分地界践踏人的，他们的地有江河分开；他们必将礼物奉给万军之耶和华，就是奉到锡安山—耶和华安置他名的地方。","notes":[]}]},"19":{"heading":"神要惩罚埃及","verses":[{"n":1,"t":"论埃及的默示：看哪，耶和华乘驾快云，临到埃及。埃及的偶像在他面前战兢；埃及人的心在里面消化。","notes":[]},{"n":2,"t":"我必激动埃及人攻击埃及人—弟兄攻击弟兄，邻舍攻击邻舍；这城攻击那城，这国攻击那国。","notes":[]},{"n":3,"t":"埃及人的心神必在里面耗尽；我必败坏他们的谋略。他们必求问偶像和念咒的、交鬼的、行巫术的。","notes":[]},{"n":4,"t":"我必将埃及人交在残忍主的手中；强暴王必辖制他们。这是主—万军之耶和华说的。","notes":[]},{"n":5,"t":"海中的水必绝尽，河也消没干涸。","notes":[]},{"n":6,"t":"江河要变臭；埃及的河水都必减少枯干。苇子和芦荻都必衰残；","notes":[]},{"n":7,"t":"靠尼罗河旁的草田，并沿尼罗河所种的田，都必枯干。庄稼被风吹去，归于无有。","notes":[]},{"n":8,"t":"打鱼的必哀哭。在尼罗河一切钓鱼的必悲伤；在水上撒网的必都衰弱。","notes":[]},{"n":9,"t":"用梳好的麻造物的和织白布的都必羞愧；","notes":[]},{"n":10,"t":"国柱必被打碎，所有佣工的，心必愁烦。","notes":[]},{"n":11,"t":"琐安的首领极其愚昧；法老大有智慧的谋士，所筹划的成为愚谋。你们怎敢对法老说：我是智慧人的子孙，我是古王的后裔？","notes":[]},{"n":12,"t":"你的智慧人在哪里呢？万军之耶和华向埃及所定的旨意，他们可以知道，可以告诉你吧！","notes":[]},{"n":13,"t":"琐安的首领都变为愚昧；挪弗的首领都受了迷惑。当埃及支派房角石的，使埃及人走错了路。","notes":[]},{"n":14,"t":"耶和华使乖谬的灵搀入埃及中间；首领使埃及一切所做的都有差错，好像醉酒之人呕吐的时候东倒西歪一样。","notes":[]},{"n":15,"t":"埃及中，无论是头与尾，棕枝与芦苇，所做之工都不成就。","notes":[]},{"n":16,"t":"到那日，埃及人必像妇人一样，他们必因万军之耶和华在埃及以上所抡的手，战兢惧怕。","notes":[]},{"n":17,"t":"犹大地必使埃及惊恐，向谁提起犹大地，谁就惧怕。这是因万军之耶和华向埃及所定的旨意。","notes":[]},{"n":18,"t":"当那日，埃及地必有五城的人说迦南的方言，又指着万军之耶和华起誓。有一城必称为「灭亡城」。","notes":[]},{"n":19,"t":"当那日，在埃及地中必有为耶和华筑的一座坛；在埃及的边界上必有为耶和华立的一根柱。","notes":[]},{"n":20,"t":"这都要在埃及地为万军之耶和华作记号和证据。埃及人因为受人的欺压哀求耶和华，他就差遣一位救主作护卫者，拯救他们。","notes":[]},{"n":21,"t":"耶和华必被埃及人所认识。在那日，埃及人必认识耶和华，也要献祭物和供物敬拜他，并向耶和华许愿还愿。","notes":[]},{"n":22,"t":"耶和华必击打埃及，又击打又医治，埃及人就归向耶和华。他必应允他们的祷告，医治他们。","notes":[]},{"n":23,"t":"当那日，必有从埃及通亚述去的大道。亚述人要进入埃及，埃及人也进入亚述；埃及人要与亚述人一同敬拜耶和华。","notes":[]},{"n":24,"t":"当那日，以色列必与埃及、亚述三国一律，使地上的人得福；","notes":[]},{"n":25,"t":"因为万军之耶和华赐福给他们，说：「埃及—我的百姓，亚述—我手的工作，以色列—我的产业，都有福了！」","notes":[]}]},"20":{"heading":"露身赤脚的先知","verses":[{"n":1,"t":"亚述王撒珥根打发他珥探到亚实突的那年，他珥探就攻打亚实突，将城攻取。","notes":[]},{"n":2,"t":"那时，耶和华晓谕亚摩斯的儿子以赛亚说：「你去解掉你腰间的麻布，脱下你脚上的鞋。」以赛亚就这样做，露身赤脚行走。","notes":[]},{"n":3,"t":"耶和华说：「我仆人以赛亚怎样露身赤脚行走三年，作为关乎埃及和古实的预兆奇迹。","notes":[]},{"n":4,"t":"照样，亚述王也必掳去埃及人，掠去古实人，无论老少，都露身赤脚，现出下体，使埃及蒙羞。","notes":[]},{"n":5,"t":"以色列人必因所仰望的古实，所夸耀的埃及，惊惶羞愧。","notes":[]},{"n":6,"t":"「那时，这沿海一带的居民必说：『看哪，我们素所仰望的，就是我们为脱离亚述王逃往求救的，不过是如此！我们怎能逃脱呢？』」","notes":[]}]},"21":{"heading":"巴比伦的覆灭","verses":[{"n":1,"t":"论海旁旷野的默示：有仇敌从旷野，从可怕之地而来，好像南方的旋风，猛然扫过。","notes":[]},{"n":2,"t":"令人凄惨的异象已默示于我。诡诈的行诡诈，毁灭的行毁灭。以拦哪，你要上去！米底亚啊，你要围困！主说：我使一切叹息止住。","notes":[]},{"n":3,"t":"所以，我满腰疼痛；痛苦将我抓住，好像产难的妇人一样。我疼痛甚至不能听；我惊惶甚至不能看。","notes":[]},{"n":4,"t":"我心慌张，惊恐威吓我。我所羡慕的黄昏，变为我的战兢。","notes":[]},{"n":5,"t":"他们摆设筵席，派人守望，又吃又喝。首领啊，你们起来，用油抹盾牌。","notes":[]},{"n":6,"t":"主对我如此说：你去设立守望的，使他将所看见的述说。","notes":[]},{"n":7,"t":"他看见军队，就是骑马的一对一对地来，又看见驴队，骆驼队，就要侧耳细听。","notes":[]},{"n":8,"t":"他像狮子吼叫，说：主啊，我白日常站在望楼上，整夜立在我守望所。","notes":[]},{"n":9,"t":"看哪，有一队军兵骑着马，一对一对地来。他就说：巴比伦倾倒了！倾倒了！他一切雕刻的神像都打碎于地。","notes":[]},{"n":10,"t":"我被打的禾稼，我场上的谷啊，我从万军之耶和华—以色列的神那里所听见的，都告诉你们了。","notes":[]},{"n":11,"t":"论度玛的默示：有人声从西珥呼问我说：守望的啊，夜里如何？守望的啊，夜里如何？","notes":[],"heads":["论以东的信息"]},{"n":12,"t":"守望的说：早晨将到，黑夜也来。你们若要问就可以问，可以回头再来。","notes":[]},{"n":13,"t":"论阿拉伯的默示：底但结伴的客旅啊，你们必在阿拉伯的树林中住宿。","notes":[],"heads":["论阿拉伯的信息"]},{"n":14,"t":"提玛地的居民拿水来，送给口渴的，拿饼来迎接逃避的。","notes":[]},{"n":15,"t":"因为他们逃避刀剑和出了鞘的刀，并上了弦的弓与刀兵的重灾。","notes":[]},{"n":16,"t":"主对我这样说：「一年之内，照雇工的年数，基达的一切荣耀必归于无有。","notes":[]},{"n":17,"t":"弓箭手所余剩的，就是基达人的勇士，必然稀少，因为这是耶和华—以色列的神说的。」","notes":[]}]},"22":{"heading":"论耶路撒冷的信息","verses":[{"n":1,"t":"论异象谷的默示：有什么事使你这满城的人都上房顶呢？","notes":[]},{"n":2,"t":"你这满处呐喊、大有喧哗的城，欢乐的邑啊，你中间被杀的并不是被刀杀，也不是因打仗死亡。","notes":[]},{"n":3,"t":"你所有的官长一同逃跑，都为弓箭手所捆绑。你中间一切被找到的都一同被捆绑；他们本是逃往远方的。","notes":[]},{"n":4,"t":"所以我说：你们转眼不看我，我要痛哭。不要因我众民的毁灭，就竭力安慰我。","notes":["原文是民女"]},{"n":5,"t":"因为主—万军之耶和华使「异象谷」有溃乱、践踏、烦扰的日子。城被攻破，哀声达到山间。","notes":[]},{"n":6,"t":"以拦带着箭袋，还有坐战车的和马兵；吉珥揭开盾牌。","notes":[]},{"n":7,"t":"你嘉美的谷遍满战车，也有马兵在城门前排列。","notes":[]},{"n":8,"t":"他去掉犹大的遮盖。那日，你就仰望林库内的军器。","notes":[]},{"n":9,"t":"你们看见大卫城的破口很多，便聚积下池的水，","notes":[]},{"n":10,"t":"又数点耶路撒冷的房屋，将房屋拆毁，修补城墙，","notes":[]},{"n":11,"t":"又在两道城墙中间挖一个聚水池可盛旧池的水，却不仰望做这事的主，也不顾念从古定这事的。","notes":[]},{"n":12,"t":"当那日，主—万军之耶和华叫人哭泣哀号，头上光秃，身披麻布。","notes":[]},{"n":13,"t":"谁知，人倒欢喜快乐，宰牛杀羊，吃肉喝酒，说：我们吃喝吧！因为明天要死了。","notes":[]},{"n":14,"t":"万军之耶和华亲自默示我说：这罪孽直到你们死，断不得赦免！这是主—万军之耶和华说的。","notes":[]},{"n":15,"t":"主—万军之耶和华这样说：「你去见掌银库的，就是家宰舍伯那，对他说：","notes":[],"heads":["对舍伯那的警告"]},{"n":16,"t":"『你在这里做什么呢？有什么人竟在这里凿坟墓，就是在高处为自己凿坟墓，在磐石中为自己凿出安身之所？","notes":[]},{"n":17,"t":"看哪，耶和华必像大有力的人，将你紧紧缠裹，竭力抛去。","notes":[]},{"n":18,"t":"他必将你滚成一团，抛在宽阔之地，好像抛球一样。你这主人家的羞辱，必在那里坐你荣耀的车，也必在那里死亡。","notes":[]},{"n":19,"t":"我必赶逐你离开官职；你必从你的原位撤下。』","notes":[]},{"n":20,"t":"「到那日，我必召我仆人希勒家的儿子以利亚敬来，","notes":[]},{"n":21,"t":"将你的外袍给他穿上，将你的腰带给他系紧，将你的政权交在他手中。他必作耶路撒冷居民和犹大家的父。","notes":[]},{"n":22,"t":"我必将大卫家的钥匙放在他肩头上。他开，无人能关；他关，无人能开。","notes":[]},{"n":23,"t":"我必将他安稳，像钉子钉在坚固处；他必作为他父家荣耀的宝座。","notes":[]},{"n":24,"t":"他父家所有的荣耀，连儿女带子孙，都挂在他身上，好像一切小器皿，从杯子到酒瓶挂上一样。","notes":[]},{"n":25,"t":"万军之耶和华说：当那日，钉在坚固处的钉子必压斜，被砍断落地；挂在其上的重担必被剪断。因为这是耶和华说的。」","notes":[]}]},"23":{"heading":"神要责罚泰尔的海港","verses":[{"n":1,"t":"论泰尔的默示：他施的船只都要哀号；因为泰尔变为荒场，甚至没有房屋，没有可进之路。这消息是从基提地得来的。","notes":[]},{"n":2,"t":"沿海的居民，就是素来靠航海西顿的商家得丰盛的，你们当静默无言。","notes":[]},{"n":3,"t":"在大水之上，西曷的粮食、尼罗河的庄稼是泰尔的进项；她作列国的大码头。","notes":[]},{"n":4,"t":"西顿哪，你当惭愧；因为大海说，就是海中的保障说：我没有劬劳，也没有生产，没有养育男子，也没有抚养童女。","notes":[]},{"n":5,"t":"这风声传到埃及；埃及人为泰尔的风声极其疼痛。","notes":[]},{"n":6,"t":"泰尔人哪，你们当过到他施去；沿海的居民哪，你们都当哀号。","notes":[]},{"n":7,"t":"这是你们欢乐的城，从上古而有的吗？其中的居民往远方寄居。","notes":[]},{"n":8,"t":"泰尔本是赐冠冕的。她的商家是王子；她的买卖人是世上的尊贵人。遭遇如此是谁定的呢？","notes":[]},{"n":9,"t":"是万军之耶和华所定的！为要污辱一切高傲的荣耀，使地上一切的尊贵人被藐视。","notes":[]},{"n":10,"t":"他施的民哪，可以流行你的地，好像尼罗河；不再有腰带拘紧你。","notes":["原文是女"]},{"n":11,"t":"耶和华已经向海伸手，震动列国。至于迦南，他已经吩咐拆毁其中的保障。","notes":[]},{"n":12,"t":"他又说：受欺压西顿的居民哪，你必不得再欢乐。起来！过到基提去；就是在那里也不得安歇。（","notes":["原文是处女"]},{"n":13,"t":"看哪，迦勒底人之地向来没有这民，这国是亚述人为住旷野的人所立的。现在他们建筑戍楼，拆毁泰尔的宫殿，使她成为荒凉。）","notes":[]},{"n":14,"t":"他施的船只都要哀号，因为你们的保障变为荒场。","notes":[]},{"n":15,"t":"到那时，泰尔必被忘记七十年，照着一王的年日。七十年后，泰尔的景况必像妓女所唱的歌：","notes":[]},{"n":16,"t":"你这被忘记的妓女啊，拿琴周流城内，巧弹多唱，使人再想念你。","notes":[]},{"n":17,"t":"七十年后，耶和华必眷顾泰尔，她就仍得利息，与地上的万国交易。","notes":["原文是雇价；下同","原文是行淫"]},{"n":18,"t":"她的货财和利息要归耶和华为圣，必不积攒存留；因为她的货财必为住在耶和华面前的人所得，使他们吃饱，穿耐久的衣服。","notes":[]}]},"24":{"heading":"耶和华要责罚世界","verses":[{"n":1,"t":"看哪，耶和华使地空虚，变为荒凉；又翻转大地，将居民分散。","notes":[]},{"n":2,"t":"那时百姓怎样，祭司也怎样；仆人怎样，主人也怎样；婢女怎样，主母也怎样；买物的怎样，卖物的也怎样；放债的怎样，借债的也怎样；取利的怎样，出利的也怎样。","notes":[]},{"n":3,"t":"地必全然空虚，尽都荒凉；因为这话是耶和华说的。","notes":[]},{"n":4,"t":"地上悲哀衰残，世界败落衰残；地上居高位的人也败落了。","notes":[]},{"n":5,"t":"地被其上的居民污秽；因为他们犯了律法，废了律例，背了永约。","notes":[]},{"n":6,"t":"所以，地被咒诅吞灭；住在其上的显为有罪。地上的居民被火焚烧，剩下的人稀少。","notes":[]},{"n":7,"t":"新酒悲哀，葡萄树衰残；心中欢乐的俱都叹息。","notes":[]},{"n":8,"t":"击鼓之乐止息；宴乐人的声音完毕，弹琴之乐也止息了。","notes":[]},{"n":9,"t":"人必不得饮酒唱歌；喝浓酒的，必以为苦。","notes":[]},{"n":10,"t":"荒凉的城拆毁了；各家关门闭户，使人都不得进去。","notes":[]},{"n":11,"t":"在街上因酒有悲叹的声音；一切喜乐变为昏暗；地上的欢乐归于无有。","notes":[]},{"n":12,"t":"城中只有荒凉；城门拆毁净尽。","notes":[]},{"n":13,"t":"在地上的万民中，必像打过的橄榄树，又像已摘的葡萄所剩无几。","notes":[]},{"n":14,"t":"这些人要高声欢呼；他们为耶和华的威严，从海那里扬起声来。","notes":[]},{"n":15,"t":"因此，你们要在东方荣耀耶和华，在众海岛荣耀耶和华—以色列神的名。","notes":[]},{"n":16,"t":"我们听见从地极有人歌唱，说：荣耀归于义人。我却说：我消灭了！我消灭了，我有祸了！诡诈的行诡诈；诡诈的大行诡诈。","notes":[]},{"n":17,"t":"地上的居民哪，恐惧、陷坑、网罗都临近你。","notes":[]},{"n":18,"t":"躲避恐惧声音的必坠入陷坑；从陷坑上来的必被网罗缠住；因为天上的窗户都开了，地的根基也震动了。","notes":[]},{"n":19,"t":"地全然破坏，尽都崩裂，大大地震动了。","notes":[]},{"n":20,"t":"地要东倒西歪，好像醉酒的人；又摇来摇去，好像吊床。罪过在其上沉重，必然塌陷，不能复起。","notes":[]},{"n":21,"t":"到那日，耶和华在高处必惩罚高处的众军，在地上必惩罚地上的列王。","notes":[]},{"n":22,"t":"他们必被聚集，像囚犯被聚在牢狱中，并要囚在监牢里，多日之后便被讨罪。","notes":["或译：眷顾"]},{"n":23,"t":"那时，月亮要蒙羞，日头要惭愧；因为万军之耶和华必在锡安山，在耶路撒冷作王；在敬畏他的长老面前，必有荣耀。","notes":[]}]},"25":{"heading":"一首赞美诗","verses":[{"n":1,"t":"耶和华啊，你是我的神；我要尊崇你，我要称赞你的名。因为你以忠信诚实行过奇妙的事，成就你古时所定的。","notes":[]},{"n":2,"t":"你使城变为乱堆，使坚固城变为荒场，使外邦人宫殿的城不再为城，永远不再建造。","notes":[]},{"n":3,"t":"所以，刚强的民必荣耀你；强暴之国的城必敬畏你。","notes":[]},{"n":4,"t":"因为当强暴人催逼人的时候，如同暴风直吹墙壁，你就作贫穷人的保障，作困乏人急难中的保障，作躲暴风之处，作避炎热的阴凉。","notes":[]},{"n":5,"t":"你要压制外邦人的喧哗，好像干燥地的热气下落；禁止强暴人的凯歌，好像热气被云影消化。","notes":[]},{"n":6,"t":"在这山上，万军之耶和华必为万民用肥甘设摆筵席，用陈酒和满髓的肥甘，并澄清的陈酒，设摆筵席。","notes":[],"heads":["神为万民设摆筵席"]},{"n":7,"t":"他又必在这山上除灭遮盖万民之物和遮蔽万国蒙脸的帕子。","notes":[]},{"n":8,"t":"他已经吞灭死亡直到永远。主耶和华必擦去各人脸上的眼泪，又除掉普天下他百姓的羞辱，因为这是耶和华说的。","notes":[]},{"n":9,"t":"到那日，人必说：「看哪，这是我们的神；我们素来等候他，他必拯救我们。这是耶和华，我们素来等候他，我们必因他的救恩欢喜快乐。」","notes":[]},{"n":10,"t":"耶和华的手必按在这山上；摩押人在所居之地必被践踏，好像干草被践踏在粪池的水中。","notes":[],"heads":["神要刑罚摩押"]},{"n":11,"t":"他必在其中伸开手，好像洑水的伸开手洑水一样；但耶和华必使他的骄傲和他手所行的诡计一并败落。","notes":[]},{"n":12,"t":"耶和华使你城上的坚固高台倾倒，拆平，直到尘埃。","notes":[]}]},"26":{"heading":"神使他的百姓得胜","verses":[{"n":1,"t":"当那日，在犹大地人必唱这歌说：我们有坚固的城。耶和华要将救恩定为城墙，为外郭。","notes":[]},{"n":2,"t":"敞开城门，使守信的义民得以进入。","notes":[]},{"n":3,"t":"坚心倚赖你的，你必保守他十分平安，因为他倚靠你。","notes":[]},{"n":4,"t":"你们当倚靠耶和华直到永远，因为耶和华是永久的磐石。","notes":[]},{"n":5,"t":"他使住高处的与高城一并败落，将城拆毁，拆平，直到尘埃，","notes":[]},{"n":6,"t":"要被脚践踏，就是被困苦人的脚和穷乏人的脚践踏。","notes":[]},{"n":7,"t":"义人的道是正直的；你为正直的主，必修平义人的路。","notes":[]},{"n":8,"t":"耶和华啊，我们在你行审判的路上等候你；我们心里所羡慕的是你的名，就是你那可记念的名。","notes":[]},{"n":9,"t":"夜间，我心中羡慕你；我里面的灵切切寻求你。因为你在世上行审判的时候，地上的居民就学习公义。","notes":[]},{"n":10,"t":"以恩惠待恶人，他仍不学习公义；在正直的地上，他必行事不义，也不注意耶和华的威严。","notes":[]},{"n":11,"t":"耶和华啊，你的手高举，他们仍然不看；却要看你为百姓发的热心，因而抱愧，并且有火烧灭你的敌人。","notes":[]},{"n":12,"t":"耶和华啊，你必派定我们得平安，因为我们所做的事都是你给我们成就的。","notes":[]},{"n":13,"t":"耶和华—我们的神啊，在你以外曾有别的主管辖我们，但我们专要倚靠你，提你的名。","notes":[]},{"n":14,"t":"他们死了，必不能再活；他们去世，必不能再起；因为你刑罚他们，毁灭他们，他们的名号就全然消灭。","notes":[]},{"n":15,"t":"耶和华啊，你增添国民，你增添国民；你得了荣耀，又扩张地的四境。","notes":[]},{"n":16,"t":"耶和华啊，他们在急难中寻求你；你的惩罚临到他们身上，他们就倾心吐胆祷告你。","notes":[]},{"n":17,"t":"妇人怀孕，临产疼痛，在痛苦之中喊叫；耶和华啊，我们在你面前也是如此。","notes":[]},{"n":18,"t":"我们也曾怀孕疼痛，所产的竟像风一样。我们在地上未曾行什么拯救的事；世上的居民也未曾败落。","notes":[]},{"n":19,"t":"死人要复活，尸首要兴起。睡在尘埃的啊，要醒起歌唱！因你的甘露好像菜蔬上的甘露，地也要交出死人来。","notes":["原文是你的死人","原文是我的尸首"]},{"n":20,"t":"我的百姓啊，你们要来进入内室，关上门，隐藏片时，等到忿怒过去。","notes":[],"heads":["审判和复兴"]},{"n":21,"t":"因为耶和华从他的居所出来，要刑罚地上居民的罪孽。地也必露出其中的血，不再掩盖被杀的人。","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"到那日，耶和华必用他刚硬有力的大刀刑罚鳄鱼—就是那快行的蛇，刑罚鳄鱼—就是那曲行的蛇，并杀海中的大鱼。","notes":[]},{"n":2,"t":"当那日，有出酒的葡萄园，你们要指这园唱歌说：","notes":[]},{"n":3,"t":"我—耶和华是看守葡萄园的；我必时刻浇灌，昼夜看守，免得有人损害。","notes":[]},{"n":4,"t":"我心中不存忿怒。惟愿荆棘蒺藜与我交战，我就勇往直前，把它一同焚烧。","notes":[]},{"n":5,"t":"不然，让它持住我的能力，使它与我和好，愿它与我和好。","notes":[]},{"n":6,"t":"将来雅各要扎根，以色列要发芽开花；他们的果实必充满世界。","notes":[]},{"n":7,"t":"主击打他们，岂像击打那些击打他们的人吗？他们被杀戮，岂像被他们所杀戮的吗？","notes":[]},{"n":8,"t":"你打发他们去，是相机宜与他们相争；刮东风的日子，就用暴风将他们逐去。","notes":[]},{"n":9,"t":"所以，雅各的罪孽得赦免，他的罪过得除掉的果效，全在乎此：就是他叫祭坛的石头变为打碎的灰石，以致木偶和日像不再立起。","notes":[]},{"n":10,"t":"因为坚固城变为凄凉，成了撇下离弃的居所，像旷野一样；牛犊必在那里吃草，在那里躺卧，并吃尽其中的树枝。","notes":[]},{"n":11,"t":"枝条枯干，必被折断；妇女要来点火烧着。因为这百姓蒙昧无知，所以，创造他们的必不怜恤他们；造成他们的也不施恩与他们。","notes":[]},{"n":12,"t":"以色列人哪，到那日，耶和华必从大河，直到埃及小河，将你们一一地收集，如同人打树拾果一样。","notes":[]},{"n":13,"t":"当那日，必大发角声，在亚述地将要灭亡的，并在埃及地被赶散的，都要来，他们就在耶路撒冷圣山上敬拜耶和华。","notes":[]}]},"28":{"heading":"对北国的警告","verses":[{"n":1,"t":"祸哉！以法莲的酒徒，住在肥美谷的山上，他们心里高傲，以所夸的为冠冕，犹如将残之花。","notes":[]},{"n":2,"t":"看哪，主有一大能大力者，像一阵冰雹，像毁灭的暴风，像涨溢的大水，他必用手将冠冕摔落于地。","notes":[]},{"n":3,"t":"以法莲高傲的酒徒，他的冠冕必被踏在脚下。","notes":[]},{"n":4,"t":"那荣美将残之花，就是在肥美谷山上的，必像夏令以前初熟的无花果；看见这果的就注意，一到手中就吞吃了。","notes":[]},{"n":5,"t":"到那日，万军之耶和华必作他余剩之民的荣冠华冕，","notes":[]},{"n":6,"t":"也作了在位上行审判者公平之灵，并城门口打退仇敌者的力量。","notes":[]},{"n":7,"t":"就是这地的人也因酒摇摇晃晃，因浓酒东倒西歪。祭司和先知因浓酒摇摇晃晃，被酒所困，因浓酒东倒西歪。他们错解默示，谬行审判。","notes":[],"heads":["以赛亚和犹大酒醉的先知"]},{"n":8,"t":"因为各席上满了呕吐的污秽，无一处干净。","notes":[]},{"n":9,"t":"讥诮先知的说：他要将知识指教谁呢？要使谁明白传言呢？是那刚断奶离怀的吗？","notes":[]},{"n":10,"t":"他竟命上加命，令上加令，律上加律，例上加例，这里一点，那里一点。","notes":[]},{"n":11,"t":"先知说：不然，主要借异邦人的嘴唇和外邦人的舌头对这百姓说话。","notes":[]},{"n":12,"t":"他曾对他们说：你们要使疲乏人得安息，这样才得安息，才得舒畅，他们却不肯听。","notes":[]},{"n":13,"t":"所以，耶和华向他们说的话是命上加命，令上加令，律上加律，例上加例，这里一点，那里一点，以致他们前行仰面跌倒，而且跌碎，并陷入网罗被缠住。","notes":[]},{"n":14,"t":"所以，你们这些亵慢的人，就是辖管住在耶路撒冷这百姓的，要听耶和华的话。","notes":[],"heads":["锡安的房角石"]},{"n":15,"t":"你们曾说：我们与死亡立约，与阴间结盟；敌军如水涨漫经过的时候，必不临到我们；因我们以谎言为避所，在虚假以下藏身。","notes":["原文是鞭子"]},{"n":16,"t":"所以，主耶和华如此说：看哪，我在锡安放一块石头作为根基，是试验过的石头，是稳固根基，宝贵的房角石；信靠的人必不着急。","notes":[]},{"n":17,"t":"我必以公平为准绳，以公义为线铊。冰雹必冲去谎言的避所；大水必漫过藏身之处。","notes":[]},{"n":18,"t":"你们与死亡所立的约必然废掉，与阴间所结的盟必立不住。敌军如水涨漫经过的时候，你们必被他践踏；","notes":["原文是鞭子"]},{"n":19,"t":"每逢经过必将你们掳去。因为每早晨他必经过，白昼黑夜都必如此。明白传言的必受惊恐。","notes":[]},{"n":20,"t":"原来，床榻短，使人不能舒身；被窝窄，使人不能遮体。","notes":[]},{"n":21,"t":"耶和华必兴起，像在毗拉心山；他必发怒，像在基遍谷，好做成他的工，就是非常的工；成就他的事，就是奇异的事。","notes":[]},{"n":22,"t":"现在你们不可亵慢，恐怕捆你们的绑索更结实了；因为我从主—万军之耶和华那里听见，已经决定在全地上施行灭绝的事。","notes":[]},{"n":23,"t":"你们当侧耳听我的声音，留心听我的言语。","notes":[],"heads":["神的智慧"]},{"n":24,"t":"那耕地为要撒种的，岂是常常耕地呢？岂是常常开垦耙地呢？","notes":[]},{"n":25,"t":"他拉平了地面，岂不就撒种小茴香，播种大茴香，按行列种小麦，在定处种大麦，在田边种粗麦呢？","notes":[]},{"n":26,"t":"因为他的神教导他务农相宜，并且指教他。","notes":[]},{"n":27,"t":"原来打小茴香，不用尖利的器具，轧大茴香，也不用碌碡；但用杖打小茴香，用棍打大茴香。","notes":["原文是车轮；下同"]},{"n":28,"t":"做饼的粮食是用磨磨碎，因它不必常打；虽用碌碡和马打散，却不磨它。","notes":[]},{"n":29,"t":"这也是出于万军之耶和华—他的谋略奇妙；他的智慧广大。","notes":[]}]},"29":{"heading":"耶路撒冷的命运","verses":[{"n":1,"t":"唉！亚利伊勒，亚利伊勒，大卫安营的城，任凭你年上加年，节期照常周流。","notes":[]},{"n":2,"t":"我终必使亚利伊勒困难；她必悲伤哀号，我却仍以她为亚利伊勒。","notes":[]},{"n":3,"t":"我必四围安营攻击你，屯兵围困你，筑垒攻击你。","notes":[]},{"n":4,"t":"你必败落，从地中说话；你的言语必微细出于尘埃。你的声音必像那交鬼者的声音出于地；你的言语低低微微出于尘埃。","notes":[]},{"n":5,"t":"你仇敌的群众，却要像细尘；强暴人的群众，也要像飞糠。这事必顷刻之间忽然临到。","notes":[]},{"n":6,"t":"万军之耶和华必用雷轰、地震、大声、旋风、暴风，并吞灭的火焰，向她讨罪。","notes":[]},{"n":7,"t":"那时，攻击亚利伊勒列国的群众，就是一切攻击亚利伊勒和她的保障，并使她困难的，必如梦景，如夜间的异象；","notes":[]},{"n":8,"t":"又必像饥饿的人梦中吃饭，醒了仍觉腹空；或像口渴的人梦中喝水，醒了仍觉发昏，心里想喝。攻击锡安山列国的群众也必如此。","notes":[]},{"n":9,"t":"你们等候惊奇吧！你们宴乐昏迷吧！他们醉了，却非因酒；他们东倒西歪，却非因浓酒。","notes":[],"heads":["没有人听警告"]},{"n":10,"t":"因为耶和华将沉睡的灵浇灌你们，封闭你们的眼，蒙盖你们的头。你们的眼就是先知；你们的头就是先见。","notes":[]},{"n":11,"t":"所有的默示，你们看如封住的书卷，人将这书卷交给识字的，说：「请念吧！」他说：「我不能念，因为是封住了。」","notes":[]},{"n":12,"t":"又将这书卷交给不识字的人，说：「请念吧！」他说：「我不识字。」","notes":[]},{"n":13,"t":"主说：因为这百姓亲近我，用嘴唇尊敬我，心却远离我；他们敬畏我，不过是领受人的吩咐。","notes":[]},{"n":14,"t":"所以，我在这百姓中要行奇妙的事，就是奇妙又奇妙的事。他们智慧人的智慧必然消灭，聪明人的聪明必然隐藏。","notes":[]},{"n":15,"t":"祸哉！那些向耶和华深藏谋略的，又在暗中行事，说：谁看见我们呢？谁知道我们呢？","notes":[],"heads":["将来的希望"]},{"n":16,"t":"你们把事颠倒了，岂可看窑匠如泥吗？被制作的物岂可论制作物的说：他没有制作我？或是被创造的物论造物的说：他没有聪明？","notes":[]},{"n":17,"t":"黎巴嫩变为肥田，肥田看如树林，不是只有一点点时候吗？","notes":[]},{"n":18,"t":"那时，聋子必听见这书上的话；瞎子的眼必从迷蒙黑暗中得以看见。","notes":[]},{"n":19,"t":"谦卑人必因耶和华增添欢喜；人间贫穷的必因以色列的圣者快乐。","notes":[]},{"n":20,"t":"因为，强暴人已归无有，亵慢人已经灭绝，一切找机会作孽的都被剪除。","notes":[]},{"n":21,"t":"他们在争讼的事上定无罪的为有罪，为城门口责备人的设下网罗，用虚无的事屈枉义人。","notes":[]},{"n":22,"t":"所以，救赎亚伯拉罕的耶和华论雅各家如此说：雅各必不再羞愧，面容也不致变色。","notes":[]},{"n":23,"t":"但他看见他的众子，就是我手的工作在他那里，他们必尊我的名为圣，必尊雅各的圣者为圣，必敬畏以色列的神。","notes":[]},{"n":24,"t":"心中迷糊的必得明白；发怨言的必受训诲。","notes":[]}]},"30":{"heading":"跟埃及订立无用的条约","verses":[{"n":1,"t":"耶和华说：祸哉！这悖逆的儿女。他们同谋，却不由于我，结盟，却不由于我的灵，以致罪上加罪；","notes":[]},{"n":2,"t":"起身下埃及去，并没有求问我；要靠法老的力量加添自己的力量，并投在埃及的荫下。","notes":[]},{"n":3,"t":"所以，法老的力量必作你们的羞辱；投在埃及的荫下，要为你们的惭愧。","notes":[]},{"n":4,"t":"他们的首领已在琐安；他们的使臣到了哈内斯。","notes":[]},{"n":5,"t":"他们必因那不利于他们的民蒙羞。那民并非帮助，也非利益，只作羞耻凌辱。","notes":[]},{"n":6,"t":"论南方牲畜的默示：他们把财物驮在驴驹的脊背上，将宝物驮在骆驼的肉鞍上，经过艰难困苦之地，就是公狮、母狮、蝮蛇、火焰的飞龙之地，往那不利于他们的民那里去。","notes":[]},{"n":7,"t":"埃及的帮助是徒然无益的；所以我称她为「坐而不动的拉哈伯」。","notes":[]},{"n":8,"t":"现今你去，在他们面前将这话刻在版上，写在书上，以便传留后世，直到永永远远。","notes":[],"heads":["不顺服的百姓"]},{"n":9,"t":"因为他们是悖逆的百姓、说谎的儿女，不肯听从耶和华训诲的儿女。","notes":[]},{"n":10,"t":"他们对先见说：不要望见不吉利的事，对先知说：不要向我们讲正直的话；要向我们说柔和的话，言虚幻的事。","notes":[]},{"n":11,"t":"你们要离弃正道，偏离直路，不要在我们面前再提说以色列的圣者。","notes":[]},{"n":12,"t":"所以，以色列的圣者如此说：因为你们藐视这训诲的话，倚赖欺压和乖僻，以此为可靠的，","notes":[]},{"n":13,"t":"故此，这罪孽在你们身上，好像将要破裂凸出来的高墙，顷刻之间忽然坍塌；","notes":[]},{"n":14,"t":"要被打碎，好像把窑匠的瓦器打碎，毫不顾惜，甚至碎块中找不到一片可用以从炉内取火，从池中舀水。","notes":[]},{"n":15,"t":"主耶和华—以色列的圣者曾如此说：你们得救在乎归回安息；你们得力在乎平静安稳；你们竟自不肯。","notes":[]},{"n":16,"t":"你们却说：不然，我们要骑马奔走。所以你们必然奔走；又说：我们要骑飞快的牲口。所以追赶你们的，也必飞快。","notes":[]},{"n":17,"t":"一人叱喝，必令千人逃跑；五人叱喝，你们都必逃跑；以致剩下的，好像山顶的旗杆，冈上的大旗。","notes":[]},{"n":18,"t":"耶和华必然等候，要施恩给你们；必然兴起，好怜悯你们。因为耶和华是公平的神；凡等候他的都是有福的！","notes":[]},{"n":19,"t":"百姓必在锡安、在耶路撒冷居住；你不再哭泣。主必因你哀求的声音施恩给你；他听见的时候就必应允你。","notes":[],"heads":["主要赐福给他的子民"]},{"n":20,"t":"主虽然以艰难给你当饼，以困苦给你当水，你的教师却不再隐藏；你眼必看见你的教师。","notes":[]},{"n":21,"t":"你或向左或向右，你必听见后边有声音说：「这是正路，要行在其间。」","notes":[]},{"n":22,"t":"你雕刻偶像所包的银子和铸造偶像所镀的金子，你要玷污，要抛弃，好像污秽之物，对偶像说：「去吧！」","notes":[]},{"n":23,"t":"你将种子撒在地里，主必降雨在其上，并使地所出的粮肥美丰盛。到那时，你的牲畜必在宽阔的草场吃草。","notes":[]},{"n":24,"t":"耕地的牛和驴驹必吃加盐的料；这料是用木杴和杈子扬净的。","notes":[]},{"n":25,"t":"在大行杀戮的日子，高台倒塌的时候，各高山冈陵必有川流河涌。","notes":[]},{"n":26,"t":"当耶和华缠裹他百姓的损处，医治他民鞭伤的日子，月光必像日光，日光必加七倍，像七日的光一样。","notes":[]},{"n":27,"t":"看哪，耶和华的名从远方来，怒气烧起，密烟上腾。他的嘴唇满有忿恨；他的舌头像吞灭的火。","notes":[],"heads":["神要惩罚亚述"]},{"n":28,"t":"他的气如涨溢的河水，直涨到颈项，要用毁灭的筛箩筛净列国，并且在众民的口中必有使人错行的嚼环。","notes":[]},{"n":29,"t":"你们必唱歌，像守圣节的夜间一样，并且心中喜乐，像人吹笛，上耶和华的山，到以色列的磐石那里。","notes":[]},{"n":30,"t":"耶和华必使人听他威严的声音，又显他降罚的膀臂和他怒中的忿恨，并吞灭的火焰与霹雷、暴风、冰雹。","notes":[]},{"n":31,"t":"亚述人必因耶和华的声音惊惶；耶和华必用杖击打他。","notes":[]},{"n":32,"t":"耶和华必将命定的杖加在他身上；每打一下，人必击鼓弹琴。打杖的时候，耶和华必抡起手来，与他交战。","notes":[]},{"n":33,"t":"原来陀斐特又深又宽，早已为王预备好了；其中堆的是火与许多木柴。耶和华的气如一股硫磺火使他着起来。","notes":[]}]},"31":{"heading":"神要保护耶路撒冷","verses":[{"n":1,"t":"祸哉！那些下埃及求帮助的，是因仗赖马匹，倚靠甚多的车辆，并倚靠强壮的马兵，却不仰望以色列的圣者，也不求问耶和华。","notes":[]},{"n":2,"t":"其实，耶和华有智慧；他必降灾祸，并不反悔自己的话，却要兴起攻击那作恶之家，又攻击那作孽帮助人的。","notes":[]},{"n":3,"t":"埃及人不过是人，并不是神；他们的马不过是血肉，并不是灵。耶和华一伸手，那帮助人的必绊跌，那受帮助的也必跌倒，都一同灭亡。","notes":[]},{"n":4,"t":"耶和华对我如此说：狮子和少壮狮子护食咆哮，就是喊许多牧人来攻击它，它总不因他们的声音惊惶，也不因他们的喧哗缩伏。如此，万军之耶和华也必降临在锡安山冈上争战。","notes":[]},{"n":5,"t":"雀鸟怎样搧翅覆雏，万军之耶和华也要照样保护耶路撒冷。他必保护拯救，要越门保守。","notes":[]},{"n":6,"t":"以色列人哪，你们深深地悖逆耶和华，现今要归向他。","notes":[]},{"n":7,"t":"到那日，各人必将他金偶像银偶像，就是亲手所造、陷自己在罪中的，都抛弃了。","notes":[]},{"n":8,"t":"亚述人必倒在刀下，并非人的刀；有刀要将他吞灭，并非人的刀。他必逃避这刀；他的少年人必成为服苦的。","notes":[]},{"n":9,"t":"他的磐石必因惊吓挪去；他的首领必因大旗惊惶。这是那有火在锡安、有炉在耶路撒冷的耶和华说的。","notes":[]}]},"32":{"heading":"公正的王","verses":[{"n":1,"t":"看哪，必有一王凭公义行政；必有首领借公平掌权。","notes":[]},{"n":2,"t":"必有一人像避风所和避暴雨的隐密处，又像河流在干旱之地，像大磐石的影子在疲乏之地。","notes":[]},{"n":3,"t":"那能看的人，眼不再昏迷；能听的人，耳必得听闻。","notes":[]},{"n":4,"t":"冒失人的心必明白知识；结巴人的舌必说话通快。","notes":[]},{"n":5,"t":"愚顽人不再称为高明；吝啬人不再称为大方。","notes":[]},{"n":6,"t":"因为愚顽人必说愚顽话，心里想作罪孽，惯行亵渎的事，说错谬的话攻击耶和华，使饥饿的人无食可吃，使口渴的人无水可喝。","notes":[]},{"n":7,"t":"吝啬人所用的法子是恶的；他图谋恶计，用谎言毁灭谦卑人；穷乏人讲公理的时候，他也是这样行。","notes":[]},{"n":8,"t":"高明人却谋高明事，在高明事上也必永存。","notes":[]},{"n":9,"t":"安逸的妇女啊，起来听我的声音！无虑的女子啊，侧耳听我的言语！","notes":[],"heads":["审判和复兴"]},{"n":10,"t":"无虑的女子啊，再过一年多，必受骚扰；因为无葡萄可摘，无果子可收。","notes":["或译：禾稼"]},{"n":11,"t":"安逸的妇女啊，要战兢；无虑的女子啊，要受骚扰。脱去衣服，赤着身体，腰束麻布。","notes":[]},{"n":12,"t":"她们必为美好的田地和多结果的葡萄树，捶胸哀哭。","notes":[]},{"n":13,"t":"荆棘蒺藜必长在我百姓的地上，又长在欢乐的城中和一切快乐的房屋上。","notes":[]},{"n":14,"t":"因为宫殿必被撇下，多民的城必被离弃；山冈望楼永为洞穴，作野驴所喜乐的，为羊群的草场。","notes":[]},{"n":15,"t":"等到圣灵从上浇灌我们，旷野就变为肥田，肥田看如树林。","notes":[]},{"n":16,"t":"那时，公平要居在旷野；公义要居在肥田。","notes":[]},{"n":17,"t":"公义的果效必是平安；公义的效验必是平稳，直到永远。","notes":[]},{"n":18,"t":"我的百姓必住在平安的居所，安稳的住处，平静的安歇所。","notes":[]},{"n":19,"t":"（但要降冰雹打倒树林；城必全然拆平。）","notes":[]},{"n":20,"t":"你们在各水边撒种、牧放牛驴的有福了！","notes":[]}]},"33":{"heading":"求救的祈祷","verses":[{"n":1,"t":"祸哉！你这毁灭人的，自己倒不被毁灭；行事诡诈的，人倒不以诡诈待你。你毁灭罢休了，自己必被毁灭；你行完了诡诈，人必以诡诈待你。","notes":[]},{"n":2,"t":"耶和华啊，求你施恩于我们；我们等候你。求你每早晨作我们的膀臂，遭难的时候为我们的拯救。","notes":[]},{"n":3,"t":"喧嚷的响声一发，众民奔逃；你一兴起，列国四散。","notes":[]},{"n":4,"t":"你们所掳的必被敛尽，好像蚂蚱吃尽禾稼。人要蹦在其上，好像蝗虫一样。","notes":["原文是敛"]},{"n":5,"t":"耶和华被尊崇，因他居在高处；他以公平公义充满锡安。","notes":[]},{"n":6,"t":"你一生一世必得安稳—有丰盛的救恩，并智慧和知识；你以敬畏耶和华为至宝。","notes":[]},{"n":7,"t":"看哪，他们的豪杰在外头哀号；求和的使臣痛痛哭泣。","notes":[]},{"n":8,"t":"大路荒凉，行人止息；敌人背约，藐视城邑，不顾人民。","notes":[]},{"n":9,"t":"地上悲哀衰残；黎巴嫩羞愧枯干；沙仑像旷野；巴珊和迦密的树林凋残。","notes":[]},{"n":10,"t":"耶和华说：现在我要起来；我要兴起；我要勃然而兴。","notes":[],"heads":["耶和华对敌人的警告"]},{"n":11,"t":"你们要怀的是糠秕，要生的是碎秸；你们的气就是吞灭自己的火。","notes":[]},{"n":12,"t":"列邦必像已烧的石灰，像已割的荆棘在火中焚烧。","notes":[]},{"n":13,"t":"你们远方的人当听我所行的；你们近处的人当承认我的大能。","notes":[]},{"n":14,"t":"锡安中的罪人都惧怕；不敬虔的人被战兢抓住。我们中间谁能与吞灭的火同住？我们中间谁能与永火同住呢？","notes":[]},{"n":15,"t":"行事公义、说话正直、憎恶欺压的财利、摆手不受贿赂、塞耳不听流血的话，闭眼不看邪恶事的，","notes":[]},{"n":16,"t":"他必居高处；他的保障是磐石的坚垒；他的粮必不缺乏；他的水必不断绝。","notes":["原文是赐给"]},{"n":17,"t":"你的眼必见王的荣美，必见辽阔之地。","notes":[],"heads":["光荣的将来"]},{"n":18,"t":"你的心必思想那惊吓的事，自问说：记数目的在哪里呢？平贡银的在哪里呢？数戍楼的在哪里呢？","notes":[]},{"n":19,"t":"你必不见那强暴的民，就是说话深奥，你不能明白，言语呢喃，你不能懂得的。","notes":[]},{"n":20,"t":"你要看锡安—我们守圣节的城！你的眼必见耶路撒冷为安静的居所，为不挪移的帐幕，橛子永不拔出，绳索一根也不折断。","notes":[]},{"n":21,"t":"在那里，耶和华必显威严与我们同在，当作江河宽阔之地；其中必没有荡桨摇橹的船来往，也没有威武的船经过。","notes":[]},{"n":22,"t":"因为，耶和华是审判我们的；耶和华是给我们设律法的；耶和华是我们的王；他必拯救我们。","notes":[]},{"n":23,"t":"你的绳索松开：不能栽稳桅杆，也不能扬起篷来。那时许多掳来的物被分了；瘸腿的把掠物夺去了。","notes":[]},{"n":24,"t":"城内居民必不说：我病了；其中居住的百姓，罪孽都赦免了。","notes":[]}]},"34":{"heading":"神要惩罚仇敌","verses":[{"n":1,"t":"列国啊，要近前来听！众民哪，要侧耳而听！地和其上所充满的，世界和其中一切所出的都应当听！","notes":[]},{"n":2,"t":"因为耶和华向万国发忿恨，向他们的全军发烈怒，将他们灭尽，交出他们受杀戮。","notes":[]},{"n":3,"t":"被杀的必然抛弃，尸首臭气上腾；诸山被他们的血融化。","notes":[]},{"n":4,"t":"天上的万象都要消没；天被卷起，好像书卷。其上的万象要残败，像葡萄树的叶子残败，又像无花果树的叶子残败一样。","notes":[]},{"n":5,"t":"因为我的刀在天上已经喝足；这刀必临到以东和我所咒诅的民，要施行审判。","notes":[]},{"n":6,"t":"耶和华的刀满了血，用脂油和羊羔、公山羊的血，并公绵羊腰子的脂油滋润的；因为耶和华在波斯拉有献祭的事，在以东地大行杀戮。","notes":[]},{"n":7,"t":"野牛、牛犊，和公牛要一同下来。他们的地喝醉了血；他们的尘土因脂油肥润。","notes":[]},{"n":8,"t":"因耶和华有报仇之日，为锡安的争辩有报应之年。","notes":[]},{"n":9,"t":"以东的河水要变为石油，尘埃要变为硫磺；地土成为烧着的石油，","notes":[]},{"n":10,"t":"昼夜总不熄灭，烟气永远上腾，必世世代代成为荒废，永永远远无人经过。","notes":[]},{"n":11,"t":"鹈鹕、箭猪却要得为业；猫头鹰、乌鸦要住在其间。耶和华必将空虚的准绳，混沌的线铊，拉在其上。","notes":[]},{"n":12,"t":"以东人要召贵胄来治国；那里却无一个，首领也都归于无有。","notes":[]},{"n":13,"t":"以东的宫殿要长荆棘；保障要长蒺藜和刺草；要作野狗的住处，鸵鸟的居所。","notes":[]},{"n":14,"t":"旷野的走兽要和豺狼相遇；野山羊要与伴偶对叫。夜间的怪物必在那里栖身，自找安歇之处。","notes":[]},{"n":15,"t":"箭蛇要在那里做窝，下蛋，抱蛋，生子，聚子在其影下；鹞鹰各与伴偶聚集在那里。","notes":[]},{"n":16,"t":"你们要查考宣读耶和华的书。这都无一缺少，无一没有伴偶；因为我的口已经吩咐，他的灵将它们聚集。","notes":[]},{"n":17,"t":"他也为它们拈阄，又亲手用准绳给它们分地；它们必永得为业，世世代代住在其间。","notes":[]}]},"35":{"heading":"神圣之路","verses":[{"n":1,"t":"旷野和干旱之地必然欢喜；沙漠也必快乐；又像玫瑰开花，","notes":[]},{"n":2,"t":"必开花繁盛，乐上加乐，而且欢呼。黎巴嫩的荣耀，并迦密与沙仑的华美，必赐给它。人必看见耶和华的荣耀，我们神的华美。","notes":[]},{"n":3,"t":"你们要使软弱的手坚壮，无力的膝稳固。","notes":[]},{"n":4,"t":"对胆怯的人说：你们要刚强，不要惧怕。看哪，你们的神必来报仇，必来施行极大的报应；他必来拯救你们。","notes":[]},{"n":5,"t":"那时，瞎子的眼必睁开；聋子的耳必开通。","notes":[]},{"n":6,"t":"那时，瘸子必跳跃像鹿；哑巴的舌头必能歌唱。在旷野必有水发出；在沙漠必有河涌流。","notes":[]},{"n":7,"t":"发光的沙要变为水池；干渴之地要变为泉源。在野狗躺卧之处，必有青草、芦苇，和蒲草。","notes":["或译：蜃楼"]},{"n":8,"t":"在那里必有一条大道，称为圣路。污秽人不得经过，必专为赎民行走；行路的人虽愚昧，也不致失迷。","notes":[]},{"n":9,"t":"在那里必没有狮子，猛兽也不登这路；在那里都遇不见，只有赎民在那里行走。","notes":[]},{"n":10,"t":"并且耶和华救赎的民必归回，歌唱来到锡安；永乐必归到他们的头上；他们必得着欢喜快乐，忧愁叹息尽都逃避。","notes":[]}]},"36":{"heading":"亚述人威胁耶路撒冷","verses":[{"n":1,"t":"希西家王十四年，亚述王西拿基立上来攻击犹大的一切坚固城，将城攻取。","notes":[]},{"n":2,"t":"亚述王从拉吉差遣拉伯沙基率领大军往耶路撒冷，到希西家王那里去。他就站在上池的水沟旁，在漂布地的大路上。","notes":[]},{"n":3,"t":"于是希勒家的儿子家宰以利亚敬，并书记舍伯那和亚萨的儿子史官约亚，出来见拉伯沙基。","notes":[]},{"n":4,"t":"拉伯沙基对他们说：「你们去告诉希西家说，亚述大王如此说：『你所倚靠的有什么可仗赖的呢？","notes":[]},{"n":5,"t":"你说，有打仗的计谋和能力，我看不过是虚话。你到底倚靠谁才背叛我呢？","notes":[]},{"n":6,"t":"看哪，你所倚靠的埃及是那压伤的苇杖，人若靠这杖，就必刺透他的手。埃及王法老向一切倚靠他的人也是这样。","notes":[]},{"n":7,"t":"你若对我说：我们倚靠耶和华—我们的神。希西家岂不是将神的邱坛和祭坛废去，且对犹大和耶路撒冷的人说：你们当在这坛前敬拜吗？","notes":[]},{"n":8,"t":"现在你把当头给我主亚述王，我给你二千匹马，看你这一面骑马的人够不够。","notes":[]},{"n":9,"t":"若不然，怎能打败我主臣仆中最小的军长呢？你竟倚靠埃及的战车马兵吗？","notes":[]},{"n":10,"t":"现在我上来攻击毁灭这地，岂没有耶和华的意思吗？耶和华吩咐我说，你上去攻击毁灭这地吧！』」","notes":[]},{"n":11,"t":"以利亚敬、舍伯那、约亚对拉伯沙基说：「求你用亚兰言语和仆人说话，因为我们懂得；不要用犹大言语和我们说话，达到城上百姓的耳中。」","notes":[]},{"n":12,"t":"拉伯沙基说：「我主差遣我来，岂是单对你和你的主说这些话吗？不也是对这些坐在城上、要与你们一同吃自己粪喝自己尿的人说吗？」","notes":[]},{"n":13,"t":"于是，拉伯沙基站着，用犹大言语大声喊着说：「你们当听亚述大王的话。","notes":[]},{"n":14,"t":"王如此说：『你们不要被希西家欺哄了，因他不能拯救你们。","notes":[]},{"n":15,"t":"也不要听希西家使你们倚靠耶和华说：耶和华必要拯救我们，这城必不交在亚述王的手中。","notes":[]},{"n":16,"t":"不要听希西家的话，因亚述王如此说：你们要与我和好。出来投降我，各人就可以吃自己葡萄树和无花果树的果子，喝自己井里的水。","notes":[]},{"n":17,"t":"等我来领你们到一个地方，与你们本地一样，就是有五谷和新酒之地，有粮食和葡萄园之地。","notes":[]},{"n":18,"t":"你们要谨防，恐怕希西家劝导你们说：耶和华必拯救我们。列国的神有哪一个救他本国脱离亚述王的手呢？","notes":[]},{"n":19,"t":"哈马和亚珥拔的神在哪里呢？西法瓦音的神在哪里呢？他们曾救撒马利亚脱离我的手吗？","notes":[]},{"n":20,"t":"这些国的神有谁曾救自己的国脱离我的手呢？难道耶和华能救耶路撒冷脱离我的手吗？』」","notes":[]},{"n":21,"t":"百姓静默不言，并不回答一句，因为王曾吩咐说：「不要回答他。」","notes":[]},{"n":22,"t":"当下希勒家的儿子家宰以利亚敬和书记舍伯那，并亚萨的儿子史官约亚，都撕裂衣服，来到希西家那里，将拉伯沙基的话告诉了他。","notes":[]}]},"37":{"heading":"国王下令征求以赛亚的意见","verses":[{"n":1,"t":"希西家王听见就撕裂衣服，披上麻布，进了耶和华的殿，","notes":[]},{"n":2,"t":"使家宰以利亚敬和书记舍伯那，并祭司中的长老，都披上麻布，去见亚摩斯的儿子先知以赛亚，","notes":[]},{"n":3,"t":"对他说：「希西家如此说：『今日是急难、责罚、凌辱的日子，就如妇人将要生产婴孩，却没有力量生产。","notes":[]},{"n":4,"t":"或者耶和华—你的神听见拉伯沙基的话，就是他主人亚述王打发他来辱骂永生神的话；耶和华—你的神听见这话就发斥责。故此，求你为余剩的民扬声祷告。』」","notes":[]},{"n":5,"t":"希西家王的臣仆就去见以赛亚。","notes":[]},{"n":6,"t":"以赛亚对他们说：「要这样对你们的主人说，耶和华如此说：『你听见亚述王的仆人亵渎我的话，不要惧怕。","notes":[]},{"n":7,"t":"我必惊动他的心；他要听见风声就归回本地，我必使他在那里倒在刀下。』」","notes":["原文是使灵进入"]},{"n":8,"t":"拉伯沙基回去，正遇见亚述王攻打立拿；原来他早听见亚述王拔营离开拉吉。","notes":[],"heads":["亚述人再来威胁"]},{"n":9,"t":"亚述王听见人论古实王特哈加说：「他出来要与你争战。」亚述王一听见，就打发使者去见希西家，吩咐他们说：","notes":[]},{"n":10,"t":"「你们对犹大王希西家如此说：『不要听你所倚靠的神欺哄你说：耶路撒冷必不交在亚述王的手中。","notes":[]},{"n":11,"t":"你总听说亚述诸王向列国所行的乃是尽行灭绝，难道你还能得救吗？","notes":[]},{"n":12,"t":"我列祖所毁灭的，就是歌散、哈兰、利色，和属提·拉撒的伊甸人；这些国的神何曾拯救这些国呢？","notes":[]},{"n":13,"t":"哈马的王，亚珥拔的王，西法瓦音城的王，希拿和以瓦的王，都在哪里呢？』」","notes":[]},{"n":14,"t":"希西家从使者手里接过书信来，看完了，就上耶和华的殿，将书信在耶和华面前展开。","notes":[]},{"n":15,"t":"希西家向耶和华祷告说：","notes":[]},{"n":16,"t":"「坐在二基路伯上万军之耶和华—以色列的神啊，你—惟有你是天下万国的神，你曾创造天地。","notes":[]},{"n":17,"t":"耶和华啊，求你侧耳而听；耶和华啊，求你睁眼而看，要听西拿基立的一切话，他是打发使者来辱骂永生神的。","notes":[]},{"n":18,"t":"耶和华啊，亚述诸王果然使列国和列国之地变为荒凉，","notes":[]},{"n":19,"t":"将列国的神像都扔在火里；因为他本不是神，乃是人手所造的，是木头、石头的，所以灭绝他。","notes":[]},{"n":20,"t":"耶和华—我们的神啊，现在求你救我们脱离亚述王的手，使天下万国都知道惟有你是耶和华。」","notes":[]},{"n":21,"t":"亚摩斯的儿子以赛亚就打发人去见希西家，说：「耶和华—以色列的神如此说，你既然求我攻击亚述王西拿基立，","notes":[],"heads":["以赛亚给王的信息"]},{"n":22,"t":"所以耶和华论他这样说：锡安的处女藐视你，嗤笑你；耶路撒冷的女子向你摇头。","notes":[]},{"n":23,"t":"你辱骂谁，亵渎谁？扬起声来，高举眼目攻击谁呢？乃是攻击以色列的圣者。","notes":[]},{"n":24,"t":"你借你的臣仆辱骂主说：我率领许多战车上山顶，到黎巴嫩极深之处；我要砍伐其中高大的香柏树和佳美的松树。我必上极高之处，进入肥田的树林。","notes":[]},{"n":25,"t":"我已经挖井喝水；我必用脚掌踏干埃及的一切河。","notes":[]},{"n":26,"t":"耶和华说：你岂没有听见我早先所做的、古时所立的吗？现在借你使坚固城荒废，变为乱堆。","notes":[]},{"n":27,"t":"所以其中的居民力量甚小，惊惶羞愧。他们像野草，像青菜，如房顶上的草，又如田间未长成的禾稼。","notes":[]},{"n":28,"t":"你坐下，你出去，你进来，你向我发烈怒，我都知道。","notes":[]},{"n":29,"t":"因你向我发烈怒，又因你狂傲的话达到我耳中，我就要用钩子钩上你的鼻子，把嚼环放在你口里，使你从原路转回去。","notes":[]},{"n":30,"t":"「以色列人哪，我赐你们一个证据：你们今年要吃自生的，明年也要吃自长的，至于后年，你们要耕种收割，栽植葡萄园，吃其中的果子。","notes":[]},{"n":31,"t":"犹大家所逃脱余剩的，仍要往下扎根，向上结果。","notes":[]},{"n":32,"t":"必有余剩的民从耶路撒冷而出；必有逃脱的人从锡安山而来。万军之耶和华的热心必成就这事。","notes":[]},{"n":33,"t":"「所以耶和华论亚述王如此说：他必不得来到这城，也不在这里射箭，不得拿盾牌到城前，也不筑垒攻城。","notes":[]},{"n":34,"t":"他从哪条路来，必从那条路回去，必不得来到这城。这是耶和华说的。","notes":[]},{"n":35,"t":"因我为自己的缘故，又为我仆人大卫的缘故，必保护拯救这城。」","notes":[]},{"n":36,"t":"耶和华的使者出去，在亚述营中杀了十八万五千人。清早有人起来一看，都是死尸了。","notes":[]},{"n":37,"t":"亚述王西拿基立就拔营回去，住在尼尼微。","notes":[]},{"n":38,"t":"一日在他的神—尼斯洛庙里叩拜，他儿子亚得米勒和沙利色用刀杀了他，就逃到亚拉腊地。他儿子以撒哈顿接续他作王。","notes":[]}]},"38":{"heading":"希西家王的疾病和痊愈","verses":[{"n":1,"t":"那时希西家病得要死，亚摩斯的儿子先知以赛亚去见他，对他说：「耶和华如此说：你当留遗命与你的家，因为你必死不能活了。」","notes":[]},{"n":2,"t":"希西家就转脸朝墙，祷告耶和华说：","notes":[]},{"n":3,"t":"「耶和华啊，求你记念我在你面前怎样存完全的心，按诚实行事，又做你眼中所看为善的。」希西家就痛哭了。","notes":[]},{"n":4,"t":"耶和华的话临到以赛亚说：","notes":[]},{"n":5,"t":"「你去告诉希西家说，耶和华—你祖大卫的神如此说：我听见了你的祷告，看见了你的眼泪。我必加增你十五年的寿数；","notes":[]},{"n":6,"t":"并且我要救你和这城脱离亚述王的手，也要保护这城。","notes":[]},{"n":7,"t":"「我—耶和华必成就我所说的。我先给你一个兆头，","notes":[]},{"n":8,"t":"就是叫亚哈斯的日晷，向前进的日影往后退十度。」于是，前进的日影果然在日晷上往后退了十度。","notes":[]},{"n":9,"t":"犹大王希西家患病已经痊愈，就作诗说：","notes":[]},{"n":10,"t":"我说：正在我中年之日必进入阴间的门；我余剩的年岁不得享受。","notes":["或译：晌午"]},{"n":11,"t":"我说：我必不得见耶和华，就是在活人之地不见耶和华；我与世上的居民不再见面。","notes":[]},{"n":12,"t":"我的住处被迁去离开我，好像牧人的帐棚一样；我将性命卷起，像织布的卷布一样。耶和华必将我从机头剪断，从早到晚，他要使我完结。","notes":[]},{"n":13,"t":"我使自己安静直到天亮；他像狮子折断我一切的骨头，从早到晚，他要使我完结。","notes":[]},{"n":14,"t":"我像燕子呢喃，像白鹤鸣叫，又像鸽子哀鸣；我因仰观，眼睛困倦。耶和华啊，我受欺压，求你为我作保。","notes":[]},{"n":15,"t":"我可说什么呢？他应许我的，也给我成就了。我因心里的苦楚，在一生的年日必悄悄而行。","notes":[]},{"n":16,"t":"主啊，人得存活乃在乎此。我灵存活也全在此。所以求你使我痊愈，仍然存活。","notes":[]},{"n":17,"t":"看哪，我受大苦，本为使我得平安；你因爱我的灵魂便救我脱离败坏的坑，因为你将我一切的罪扔在你的背后。","notes":["或译：生命"]},{"n":18,"t":"原来，阴间不能称谢你，死亡不能颂扬你；下坑的人不能盼望你的诚实。","notes":[]},{"n":19,"t":"只有活人，活人必称谢你，像我今日称谢你一样。为父的，必使儿女知道你的诚实。","notes":[]},{"n":20,"t":"耶和华肯救我，所以，我们要一生一世在耶和华殿中用丝弦的乐器唱我的诗歌。","notes":[]},{"n":21,"t":"以赛亚说：「当取一块无花果饼来，贴在疮上，王必痊愈。」","notes":[]},{"n":22,"t":"希西家问说：「我能上耶和华的殿，有什么兆头呢？」","notes":[]}]},"39":{"heading":"巴比伦王的使节","verses":[{"n":1,"t":"那时，巴比伦王巴拉但的儿子米罗达·巴拉但听见希西家病而痊愈，就送书信和礼物给他。","notes":[]},{"n":2,"t":"希西家喜欢见使者，就把自己宝库的金子、银子、香料、贵重的膏油，和他武库的一切军器，并所有的财宝都给他们看；他家中和全国之内，希西家没有一样不给他们看的。","notes":[]},{"n":3,"t":"于是先知以赛亚来见希西家王，问他说：「这些人说什么？他们从哪里来见你？」希西家说：「他们从远方的巴比伦来见我。」","notes":[]},{"n":4,"t":"以赛亚说：「他们在你家里看见了什么？」希西家说：「凡我家中所有的，他们都看见了；我财宝中没有一样不给他们看的。」","notes":[]},{"n":5,"t":"以赛亚对希西家说：「你要听万军之耶和华的话：","notes":[]},{"n":6,"t":"日子必到，凡你家里所有的，并你列祖积蓄到如今的，都要被掳到巴比伦去，不留下一样；这是耶和华说的。","notes":[]},{"n":7,"t":"并且从你本身所生的众子，其中必有被掳去、在巴比伦王宫里当太监的。」","notes":[]},{"n":8,"t":"希西家对以赛亚说：「你所说耶和华的话甚好，因为在我的年日中必有太平和稳固的景况。」","notes":[]}]},"40":{"heading":"安慰的话","verses":[{"n":1,"t":"你们的神说：你们要安慰，安慰我的百姓。","notes":[]},{"n":2,"t":"要对耶路撒冷说安慰的话，又向她宣告说，她争战的日子已满了；她的罪孽赦免了；她为自己的一切罪，从耶和华手中加倍受罚。","notes":[]},{"n":3,"t":"有人声喊着说：在旷野预备耶和华的路，在沙漠地修平我们神的道。","notes":["或译：在旷野，有人声喊着说：当预备耶和华的路"]},{"n":4,"t":"一切山洼都要填满，大小山冈都要削平；高高低低的要改为平坦，崎崎岖岖的必成为平原。","notes":[]},{"n":5,"t":"耶和华的荣耀必然显现；凡有血气的必一同看见；因为这是耶和华亲口说的。","notes":[]},{"n":6,"t":"有人声说：你喊叫吧！有一个说：我喊叫什么呢？说：凡有血气的尽都如草；他的美容都像野地的花。","notes":[]},{"n":7,"t":"草必枯干，花必凋残，因为耶和华的气吹在其上；百姓诚然是草。","notes":[]},{"n":8,"t":"草必枯干，花必凋残，惟有我们神的话必永远立定。","notes":[]},{"n":9,"t":"报好信息给锡安的啊，你要登高山；报好信息给耶路撒冷的啊，你要极力扬声。扬声不要惧怕，对犹大的城邑说：看哪，你们的神！","notes":[]},{"n":10,"t":"主耶和华必像大能者临到；他的膀臂必为他掌权。他的赏赐在他那里；他的报应在他面前。","notes":[]},{"n":11,"t":"他必像牧人牧养自己的羊群，用膀臂聚集羊羔抱在怀中，慢慢引导那乳养小羊的。","notes":[]},{"n":12,"t":"谁曾用手心量诸水，用手虎口量苍天，用升斗盛大地的尘土，用秤称山岭，用天平平冈陵呢？","notes":[],"heads":["以色列的神无可比拟"]},{"n":13,"t":"谁曾测度耶和华的心，或作他的谋士指教他呢？","notes":["或译：谁曾指示耶和华的灵"]},{"n":14,"t":"他与谁商议，谁教导他，谁将公平的路指示他，又将知识教训他，将通达的道指教他呢？","notes":[]},{"n":15,"t":"看哪，万民都像水桶的一滴，又算如天平上的微尘；他举起众海岛，好像极微之物。","notes":[]},{"n":16,"t":"黎巴嫩的树林不够当柴烧；其中的走兽也不够作燔祭。","notes":[]},{"n":17,"t":"万民在他面前好像虚无，被他看为不及虚无，乃为虚空。","notes":[]},{"n":18,"t":"你们究竟将谁比神，用什么形象与神比较呢？","notes":[]},{"n":19,"t":"偶像是匠人铸造，银匠用金包裹，为它铸造银链。","notes":[]},{"n":20,"t":"穷乏献不起这样供物的，就拣选不能朽坏的树木，为自己寻找巧匠，立起不能摇动的偶像。","notes":[]},{"n":21,"t":"你们岂不曾知道吗？你们岂不曾听见吗？从起初岂没有人告诉你们吗？自从立地的根基，你们岂没有明白吗？","notes":[]},{"n":22,"t":"神坐在地球大圈之上；地上的居民好像蝗虫。他铺张穹苍如幔子，展开诸天如可住的帐棚。","notes":[]},{"n":23,"t":"他使君王归于虚无，使地上的审判官成为虚空。","notes":[]},{"n":24,"t":"他们是刚才栽上，刚才种上，根也刚才扎在地里，他一吹在其上，便都枯干；旋风将他们吹去，像碎秸一样。","notes":["或译：不曾；下同"]},{"n":25,"t":"那圣者说：你们将谁比我，叫他与我相等呢？","notes":[]},{"n":26,"t":"你们向上举目，看谁创造这万象，按数目领出，他一一称其名；因他的权能，又因他的大能大力，连一个都不缺。","notes":[]},{"n":27,"t":"雅各啊，你为何说，我的道路向耶和华隐藏？以色列啊，你为何言，我的冤屈神并不查问？","notes":[]},{"n":28,"t":"你岂不曾知道吗？你岂不曾听见吗？永在的神耶和华，创造地极的主，并不疲乏，也不困倦；他的智慧无法测度。","notes":[]},{"n":29,"t":"疲乏的，他赐能力；软弱的，他加力量。","notes":[]},{"n":30,"t":"就是少年人也要疲乏困倦；强壮的也必全然跌倒。","notes":[]},{"n":31,"t":"但那等候耶和华的必从新得力。他们必如鹰展翅上腾；他们奔跑却不困倦，行走却不疲乏。","notes":[]}]},"41":{"heading":"神对以色列的保证","verses":[{"n":1,"t":"众海岛啊，当在我面前静默；众民当从新得力，都要近前来才可以说话，我们可以彼此辩论。","notes":[]},{"n":2,"t":"谁从东方兴起一人，凭公义召他来到脚前呢？耶和华将列国交给他，使他管辖君王，把他们如灰尘交与他的刀，如风吹的碎秸交与他的弓。","notes":[]},{"n":3,"t":"他追赶他们，走他所未走的道，坦然前行。","notes":[]},{"n":4,"t":"谁行做成就这事，从起初宣召历代呢？就是我—耶和华！我是首先的，也与末后的同在。","notes":[]},{"n":5,"t":"海岛看见就都害怕；地极也都战兢，就近前来。","notes":[]},{"n":6,"t":"他们各人帮助邻舍，各人对弟兄说：壮胆吧！","notes":[]},{"n":7,"t":"木匠勉励银匠，用锤打光的勉励打砧的，论焊工说，焊得好；又用钉子钉稳，免得偶像动摇。","notes":[]},{"n":8,"t":"惟你以色列—我的仆人，雅各—我所拣选的，我朋友亚伯拉罕的后裔，","notes":[]},{"n":9,"t":"你是我从地极所领来的，从地角所召来的，且对你说：你是我的仆人；我拣选你，并不弃绝你。","notes":["原文是抓"]},{"n":10,"t":"你不要害怕，因为我与你同在；不要惊惶，因为我是你的神。我必坚固你，我必帮助你；我必用我公义的右手扶持你。","notes":[]},{"n":11,"t":"凡向你发怒的必都抱愧蒙羞；与你相争的必如无有，并要灭亡。","notes":[]},{"n":12,"t":"与你争竞的，你要找他们也找不着；与你争战的必如无有，成为虚无。","notes":[]},{"n":13,"t":"因为我耶和华—你的神必搀扶你的右手，对你说：不要害怕！我必帮助你。","notes":[]},{"n":14,"t":"你这虫雅各和你们以色列人，不要害怕！耶和华说：我必帮助你。你的救赎主就是以色列的圣者。","notes":[]},{"n":15,"t":"看哪，我已使你成为有快齿打粮的新器具；你要把山岭打得粉碎，使冈陵如同糠秕。","notes":[]},{"n":16,"t":"你要把它簸扬，风要吹去；旋风要把它刮散。你倒要以耶和华为喜乐，以以色列的圣者为夸耀。","notes":[]},{"n":17,"t":"困苦穷乏人寻求水却没有；他们因口渴，舌头干燥。我—耶和华必应允他们；我—以色列的神必不离弃他们。","notes":[]},{"n":18,"t":"我要在净光的高处开江河，在谷中开泉源；我要使沙漠变为水池，使干地变为涌泉。","notes":[]},{"n":19,"t":"我要在旷野种上香柏树、皂荚树、番石榴树，和野橄榄树。我在沙漠要把松树、杉树，并黄杨树一同栽植；","notes":[]},{"n":20,"t":"好叫人看见、知道、思想、明白；这是耶和华的手所做的，是以色列的圣者所造的。","notes":[]},{"n":21,"t":"耶和华对假神说：你们要呈上你们的案件；雅各的君说：你们要声明你们确实的理由。","notes":[],"heads":["耶和华向假神挑战"]},{"n":22,"t":"可以声明，指示我们将来必遇的事，说明先前的是什么事，好叫我们思索，得知事的结局，或者把将来的事指示我们。","notes":[]},{"n":23,"t":"要说明后来的事，好叫我们知道你们是神。你们或降福，或降祸，使我们惊奇，一同观看。","notes":[]},{"n":24,"t":"看哪，你们属乎虚无；你们的作为也属乎虚空。那选择你们的是可憎恶的。","notes":[]},{"n":25,"t":"我从北方兴起一人；他是求告我名的，从日出之地而来。他必临到掌权的，好像临到灰泥，仿佛窑匠踹泥一样。","notes":[]},{"n":26,"t":"谁从起初指明这事，使我们知道呢？谁从先前说明，使我们说他不错呢？谁也没有指明；谁也没有说明；谁也没有听见你们的话。","notes":[]},{"n":27,"t":"我首先对锡安说：看哪，我要将一位报好信息的赐给耶路撒冷。","notes":[]},{"n":28,"t":"我看的时候并没有人；我问的时候，他们中间也没有谋士可以回答一句。","notes":[]},{"n":29,"t":"看哪，他们和他们的工作都是虚空，且是虚无。他们所铸的偶像都是风，都是虚的。","notes":[]}]},"42":{"heading":"耶和华的仆人","verses":[{"n":1,"t":"看哪，我的仆人—我所扶持所拣选、心里所喜悦的！我已将我的灵赐给他；他必将公理传给外邦。","notes":[]},{"n":2,"t":"他不喧嚷，不扬声，也不使街上听见他的声音。","notes":[]},{"n":3,"t":"压伤的芦苇，他不折断；将残的灯火，他不吹灭。他凭真实将公理传开。","notes":[]},{"n":4,"t":"他不灰心，也不丧胆，直到他在地上设立公理；海岛都等候他的训诲。","notes":[]},{"n":5,"t":"创造诸天，铺张穹苍，将地和地所出的一并铺开，赐气息给地上的众人，又赐灵性给行在其上之人的神耶和华，他如此说：","notes":[]},{"n":6,"t":"我—耶和华凭公义召你，必搀扶你的手，保守你，使你作众民的中保，作外邦人的光，","notes":["中保：原文是约"]},{"n":7,"t":"开瞎子的眼，领被囚的出牢狱，领坐黑暗的出监牢。","notes":[]},{"n":8,"t":"我是耶和华，这是我的名；我必不将我的荣耀归给假神，也不将我的称赞归给雕刻的偶像。","notes":[]},{"n":9,"t":"看哪，先前的事已经成就，现在我将新事说明，这事未发以先，我就说给你们听。","notes":[]},{"n":10,"t":"航海的和海中所有的，海岛和其上的居民，都当向耶和华唱新歌，从地极赞美他。","notes":[],"heads":["颂赞之歌"]},{"n":11,"t":"旷野和其中的城邑，并基达人居住的村庄都当扬声；西拉的居民当欢呼，在山顶上呐喊。","notes":[]},{"n":12,"t":"他们当将荣耀归给耶和华，在海岛中传扬他的颂赞。","notes":[]},{"n":13,"t":"耶和华必像勇士出去，必像战士激动热心，要喊叫，大声呐喊，要用大力攻击仇敌。","notes":[]},{"n":14,"t":"我许久闭口不言，静默不语；现在我要喊叫，像产难的妇人；我要急气而喘哮。","notes":[],"heads":["神应许帮助他的子民"]},{"n":15,"t":"我要使大山小冈变为荒场，使其上的花草都枯干；我要使江河变为洲岛，使水池都干涸。","notes":[]},{"n":16,"t":"我要引瞎子行不认识的道，领他们走不知道的路；在他们面前使黑暗变为光明，使弯曲变为平直。这些事我都要行，并不离弃他们。","notes":[]},{"n":17,"t":"倚靠雕刻的偶像，对铸造的偶像说：你是我们的神；这等人要退后，全然蒙羞。","notes":[]},{"n":18,"t":"你们这耳聋的，听吧！你们这眼瞎的，看吧！使你们能看见。","notes":[],"heads":["以色列人不受教益"]},{"n":19,"t":"谁比我的仆人眼瞎呢？谁比我差遣的使者耳聋呢？谁瞎眼像那与我和好的？谁瞎眼像耶和华的仆人呢？","notes":[]},{"n":20,"t":"你看见许多事却不领会，耳朵开通却不听见。","notes":[]},{"n":21,"t":"耶和华因自己公义的缘故，喜欢使律法为大，为尊。","notes":["或译：训诲"]},{"n":22,"t":"但这百姓是被抢被夺的，都牢笼在坑中，隐藏在狱里；他们作掠物，无人拯救，作掳物，无人说交还。","notes":[]},{"n":23,"t":"你们中间谁肯侧耳听此，谁肯留心而听，以防将来呢？","notes":[]},{"n":24,"t":"谁将雅各交出当作掳物，将以色列交给抢夺的呢？岂不是耶和华吗？就是我们所得罪的那位。他们不肯遵行他的道，也不听从他的训诲。","notes":[]},{"n":25,"t":"所以，他将猛烈的怒气和争战的勇力倾倒在以色列的身上。在他四围如火着起，他还不知道，烧着他，他也不介意。","notes":[]}]},"43":{"heading":"神应许拯救他的子民","verses":[{"n":1,"t":"雅各啊，创造你的耶和华，以色列啊，造成你的那位，现在如此说：你不要害怕！因为我救赎了你。我曾提你的名召你，你是属我的。","notes":[]},{"n":2,"t":"你从水中经过，我必与你同在；你趟过江河，水必不漫过你；你从火中行过，必不被烧，火焰也不着在你身上。","notes":[]},{"n":3,"t":"因为我是耶和华—你的神，是以色列的圣者—你的救主；我已经使埃及作你的赎价，使古实和西巴代替你。","notes":[]},{"n":4,"t":"因我看你为宝为尊；又因我爱你，所以我使人代替你，使列邦人替换你的生命。","notes":[]},{"n":5,"t":"不要害怕，因我与你同在；我必领你的后裔从东方来，又从西方招聚你。","notes":[]},{"n":6,"t":"我要对北方说，交出来！对南方说，不要拘留！将我的众子从远方带来，将我的众女从地极领回，","notes":[]},{"n":7,"t":"就是凡称为我名下的人，是我为自己的荣耀创造的，是我所做成，所造作的。","notes":[]},{"n":8,"t":"你要将有眼而瞎、有耳而聋的民都带出来！","notes":[],"heads":["以色列是耶和华的见证人"]},{"n":9,"t":"任凭万国聚集；任凭众民会合。其中谁能将此声明，并将先前的事说给我们听呢？他们可以带出见证来，自显为是；或者他们听见便说：这是真的。","notes":[]},{"n":10,"t":"耶和华说：你们是我的见证，我所拣选的仆人。既是这样，便可以知道，且信服我，又明白我就是耶和华。在我以前没有真神；在我以后也必没有。","notes":["真：原文是造作的"]},{"n":11,"t":"惟有我是耶和华；除我以外没有救主。","notes":[]},{"n":12,"t":"我曾指示，我曾拯救，我曾说明，并且在你们中间没有别神。所以耶和华说：你们是我的见证。我也是神；","notes":[]},{"n":13,"t":"自从有日子以来，我就是神；谁也不能救人脱离我手。我要行事谁能阻止呢？","notes":[]},{"n":14,"t":"耶和华—你们的救赎主、以色列的圣者如此说：因你们的缘故，我已经打发人到巴比伦去；并且我要使迦勒底人如逃民，都坐自己喜乐的船下来。","notes":[],"heads":["逃离巴比伦"]},{"n":15,"t":"我是耶和华—你们的圣者，是创造以色列的，是你们的君王。","notes":[]},{"n":16,"t":"耶和华在沧海中开道，在大水中开路，","notes":[]},{"n":17,"t":"使车辆、马匹、军兵、勇士都出来，一同躺下，不再起来；他们灭没，好像熄灭的灯火。","notes":[]},{"n":18,"t":"耶和华如此说：你们不要记念从前的事，也不要思想古时的事。","notes":[]},{"n":19,"t":"看哪，我要做一件新事；如今要发现，你们岂不知道吗？我必在旷野开道路，在沙漠开江河。","notes":[]},{"n":20,"t":"野地的走兽必尊重我；野狗和鸵鸟也必如此。因我使旷野有水，使沙漠有河，好赐给我的百姓、我的选民喝。","notes":[]},{"n":21,"t":"这百姓是我为自己所造的，好述说我的美德。","notes":[]},{"n":22,"t":"雅各啊，你并没有求告我；以色列啊，你倒厌烦我。","notes":[],"heads":["以色列人的罪恶"]},{"n":23,"t":"你没有将你的羊带来给我作燔祭，也没有用祭物尊敬我；我没有因供物使你服劳，也没有因乳香使你厌烦。","notes":[]},{"n":24,"t":"你没有用银子为我买菖蒲，也没有用祭物的脂油使我饱足；倒使我因你的罪恶服劳，使我因你的罪孽厌烦。","notes":[]},{"n":25,"t":"惟有我为自己的缘故涂抹你的过犯；我也不记念你的罪恶。","notes":[]},{"n":26,"t":"你要提醒我，你我可以一同辩论；你可以将你的理陈明，自显为义。","notes":[]},{"n":27,"t":"你的始祖犯罪；你的师傅违背我。","notes":[]},{"n":28,"t":"所以，我要辱没圣所的首领，使雅各成为咒诅，使以色列成为辱骂。","notes":[]}]},"44":{"heading":"耶和华是独一的神","verses":[{"n":1,"t":"我的仆人雅各，我所拣选的以色列啊，现在你当听。","notes":[]},{"n":2,"t":"造作你，又从你出胎造就你，并要帮助你的耶和华如此说：我的仆人雅各，我所拣选的耶书仑哪，不要害怕！","notes":[]},{"n":3,"t":"因为我要将水浇灌口渴的人，将河浇灌干旱之地。我要将我的灵浇灌你的后裔，将我的福浇灌你的子孙。","notes":[]},{"n":4,"t":"他们要发生在草中，像溪水旁的柳树。","notes":[]},{"n":5,"t":"这个要说：我是属耶和华的；那个要以雅各的名自称；又一个要亲手写：归耶和华的，并自称为以色列。","notes":["或译：在手上写归耶和华"]},{"n":6,"t":"耶和华—以色列的君，以色列的救赎主—万军之耶和华如此说：我是首先的，我是末后的；除我以外再没有真神。","notes":[]},{"n":7,"t":"自从我设立古时的民，谁能像我宣告，并且指明，又为自己陈说呢？让他将未来的事和必成的事说明。","notes":[]},{"n":8,"t":"你们不要恐惧，也不要害怕。我岂不是从上古就说明指示你们吗？并且你们是我的见证！除我以外，岂有真神吗？诚然没有磐石，我不知道一个！","notes":[]},{"n":9,"t":"制造雕刻偶像的尽都虚空；他们所喜悦的都无益处；他们的见证无所看见，无所知晓，他们便觉羞愧。","notes":[],"heads":["虚无的偶像"]},{"n":10,"t":"谁制造神像，铸造无益的偶像？","notes":[]},{"n":11,"t":"看哪，他的同伴都必羞愧。工匠也不过是人，任他们聚会，任他们站立，都必惧怕，一同羞愧。","notes":[]},{"n":12,"t":"铁匠把铁在火炭中烧热，用锤打铁器，用他有力的膀臂锤成；他饥饿而无力，不喝水而发倦。","notes":[]},{"n":13,"t":"木匠拉线，用笔划出样子，用刨子刨成形状，用圆尺划了模样，仿照人的体态，做成人形，好住在房屋中。","notes":[]},{"n":14,"t":"他砍伐香柏树，又取柞树和橡树，在树林中选定了一棵。他栽种松树，得雨长养。","notes":["或译：青桐"]},{"n":15,"t":"这树，人可用以烧火；他自己取些烤火，又烧着烤饼，而且做神像跪拜，做雕刻的偶像向它叩拜。","notes":[]},{"n":16,"t":"他把一分烧在火中，把一分烤肉吃饱。自己烤火说：「啊哈，我暖和了，我见火了。」","notes":[]},{"n":17,"t":"他用剩下的做了一神，就是雕刻的偶像。他向这偶像俯伏叩拜，祷告它说：「求你拯救我，因你是我的神。」","notes":[]},{"n":18,"t":"他们不知道，也不思想；因为耶和华闭住他们的眼，不能看见，塞住他们的心，不能明白。","notes":[]},{"n":19,"t":"谁心里也不醒悟，也没有知识，没有聪明，能说：「我曾拿一分在火中烧了，在炭火上烤过饼；我也烤过肉吃。这剩下的，我岂要作可憎的物吗？我岂可向木墩子叩拜呢？」","notes":[]},{"n":20,"t":"他以灰为食，心中昏迷，使他偏邪，他不能自救，也不能说：「我右手中岂不是有虚谎吗？」","notes":[]},{"n":21,"t":"雅各，以色列啊，你是我的仆人，要记念这些事。以色列啊，你是我的仆人，我造就你必不忘记你。","notes":[],"heads":["耶和华是创造主也是救赎主"]},{"n":22,"t":"我涂抹了你的过犯，像厚云消散；我涂抹了你的罪恶，如薄云灭没。你当归向我，因我救赎了你。","notes":[]},{"n":23,"t":"诸天哪，应当歌唱，因为耶和华做成这事。地的深处啊，应当欢呼；众山应当发声歌唱；树林和其中所有的树都当如此！因为耶和华救赎了雅各，并要因以色列荣耀自己。","notes":[]},{"n":24,"t":"从你出胎，造就你的救赎主—耶和华如此说：我—耶和华是创造万物的，是独自铺张诸天、铺开大地的。谁与我同在呢？","notes":[]},{"n":25,"t":"使说假话的兆头失效，使占卜的癫狂，使智慧人退后，使他的知识变为愚拙；","notes":[]},{"n":26,"t":"使我仆人的话语立定，我使者的谋算成就。论到耶路撒冷说：必有人居住；论到犹大的城邑说：必被建造，其中的荒场我也必兴起。","notes":[]},{"n":27,"t":"对深渊说：你干了吧！我也要使你的江河干涸。","notes":[]},{"n":28,"t":"论塞鲁士说：他是我的牧人，必成就我所喜悦的，必下令建造耶路撒冷，发命立稳圣殿的根基。","notes":[]}]},"45":{"heading":"耶和华立塞鲁士为王","verses":[{"n":1,"t":"我—耶和华所膏的塞鲁士；我搀扶他的右手，使列国降伏在他面前。我也要放松列王的腰带，使城门在他面前敞开，不得关闭。我对他如此说：","notes":[]},{"n":2,"t":"我必在你前面行，修平崎岖之地。我必打破铜门，砍断铁闩。","notes":[]},{"n":3,"t":"我要将暗中的宝物和隐密的财宝赐给你，使你知道提名召你的，就是我—耶和华、以色列的神。","notes":[]},{"n":4,"t":"因我仆人雅各，我所拣选以色列的缘故，我就提名召你；你虽不认识我，我也加给你名号。","notes":[]},{"n":5,"t":"我是耶和华，在我以外并没有别神；除了我以外再没有神。你虽不认识我，我必给你束腰。","notes":[]},{"n":6,"t":"从日出之地到日落之处使人都知道除了我以外，没有别神。我是耶和华；在我以外并没有别神。","notes":[]},{"n":7,"t":"我造光，又造暗；我施平安，又降灾祸；造作这一切的是我—耶和华。","notes":[]},{"n":8,"t":"诸天哪，自上而滴，穹苍降下公义；地面开裂，产出救恩，使公义一同发生；这都是我—耶和华所造的。","notes":[]},{"n":9,"t":"祸哉，那与造他的主争论的！他不过是地上瓦片中的一块瓦片。泥土岂可对抟弄他的说：你做什么呢？所做的物岂可说：你没有手呢？","notes":[],"heads":["创造和历史的主宰"]},{"n":10,"t":"祸哉，那对父亲说：你生的是什么呢？或对母亲说：你产的是什么呢？","notes":["原文是妇人"]},{"n":11,"t":"耶和华—以色列的圣者，就是造就以色列的如此说：将来的事，你们可以问我；至于我的众子，并我手的工作，你们可以求我命定。","notes":["原文是吩咐我"]},{"n":12,"t":"我造地，又造人在地上。我亲手铺张诸天；天上万象也是我所命定的。","notes":[]},{"n":13,"t":"我凭公义兴起塞鲁士，又要修直他一切道路。他必建造我的城，释放我被掳的民；不是为工价，也不是为赏赐。这是万军之耶和华说的。","notes":["原文是他"]},{"n":14,"t":"耶和华如此说：埃及劳碌得来的和古实的货物必归你；身量高大的西巴人必投降你，也要属你。他们必带着锁链过来随从你，又向你下拜，祈求你说：神真在你们中间，此外再没有别神；再没有别的神。","notes":[]},{"n":15,"t":"救主—以色列的神啊，你实在是自隐的神。","notes":[]},{"n":16,"t":"凡制造偶像的都必抱愧蒙羞，都要一同归于惭愧。","notes":[]},{"n":17,"t":"惟有以色列必蒙耶和华的拯救，得永远的救恩。你们必不蒙羞，也不抱愧，直到永世无尽。","notes":[]},{"n":18,"t":"创造诸天的耶和华，制造成全大地的神，他创造坚定大地，并非使地荒凉，是要给人居住。他如此说：我是耶和华，再没有别神。","notes":[]},{"n":19,"t":"我没有在隐密黑暗之地说话；我没有对雅各的后裔说：你们寻求我是徒然的。我—耶和华所讲的是公义，所说的是正直。","notes":[]},{"n":20,"t":"你们从列国逃脱的人，要一同聚集前来。那些抬着雕刻木偶、祷告不能救人之神的，毫无知识。","notes":[],"heads":["天地之主和巴比伦的偶像"]},{"n":21,"t":"你们要述说陈明你们的理，让他们彼此商议。谁从古时指明？谁从上古述说？不是我—耶和华吗？除了我以外，再没有神；我是公义的神，又是救主；除了我以外，再没有别神。","notes":[]},{"n":22,"t":"地极的人都当仰望我，就必得救；因为我是神，再没有别神。","notes":[]},{"n":23,"t":"我指着自己起誓，我口所出的话是凭公义，并不反回：万膝必向我跪拜；万口必凭我起誓。","notes":[]},{"n":24,"t":"人论我说，公义、能力，惟独在乎耶和华；人都必归向他。凡向他发怒的必至蒙羞。","notes":[]},{"n":25,"t":"以色列的后裔都必因耶和华得称为义，并要夸耀。","notes":[]}]},"46":{"heading":"","verses":[{"n":1,"t":"彼勒屈身，尼波弯腰；巴比伦的偶像驮在兽和牲畜上。他们所抬的如今成了重驮，使牲畜疲乏，","notes":[]},{"n":2,"t":"都一同弯腰屈身，不能保全重驮，自己倒被掳去。","notes":[]},{"n":3,"t":"雅各家，以色列家一切余剩的要听我言：你们自从生下，就蒙我保抱，自从出胎，便蒙我怀搋。","notes":[]},{"n":4,"t":"直到你们年老，我仍这样；直到你们发白，我仍怀搋。我已造作，也必保抱；我必怀抱，也必拯救。","notes":[]},{"n":5,"t":"你们将谁与我相比，与我同等，可以与我比较，使我们相同呢？","notes":[]},{"n":6,"t":"那从囊中抓金子，用天平平银子的人，雇银匠制造神像，他们又俯伏，又叩拜。","notes":[]},{"n":7,"t":"他们将神像抬起，扛在肩上，安置在定处，它就站立，不离本位；人呼求它，它不能答应，也不能救人脱离患难。","notes":[]},{"n":8,"t":"你们当想念这事，自己作大丈夫。悖逆的人哪，要心里思想。","notes":[]},{"n":9,"t":"你们要追念上古的事。因为我是神，并无别神；我是神，再没有能比我的。","notes":[]},{"n":10,"t":"我从起初指明末后的事，从古时言明未成的事，说：我的筹算必立定；凡我所喜悦的，我必成就。","notes":[]},{"n":11,"t":"我召鸷鸟从东方来，召那成就我筹算的人从远方来。我已说出，也必成就；我已谋定，也必做成。","notes":[]},{"n":12,"t":"你们这些心中顽梗、远离公义的，当听我言。","notes":[]},{"n":13,"t":"我使我的公义临近，必不远离。我的救恩必不迟延；我要为以色列—我的荣耀，在锡安施行救恩。","notes":[]}]},"47":{"heading":"审判巴比伦","verses":[{"n":1,"t":"巴比伦的处女啊，下来坐在尘埃；迦勒底的闺女啊，没有宝座，要坐在地上；因为你不再称为柔弱娇嫩的。","notes":[]},{"n":2,"t":"要用磨磨面，揭去帕子，脱去长衣，露腿趟河。","notes":[]},{"n":3,"t":"你的下体必被露出；你的丑陋必被看见。我要报仇，谁也不宽容。","notes":[]},{"n":4,"t":"我们救赎主的名是万军之耶和华—以色列的圣者。","notes":[]},{"n":5,"t":"迦勒底的闺女啊，你要默然静坐，进入暗中，因为你不再称为列国的主母。","notes":[]},{"n":6,"t":"我向我的百姓发怒，使我的产业被亵渎，将他们交在你手中，你毫不怜悯他们，把极重的轭加在老年人身上。","notes":[]},{"n":7,"t":"你自己说：我必永为主母，所以你不将这事放在心上，也不思想这事的结局。","notes":[]},{"n":8,"t":"你这专好宴乐、安然居住的，现在当听这话。你心中说：惟有我，除我以外再没有别的。我必不致寡居，也不遭丧子之事。","notes":[]},{"n":9,"t":"哪知，丧子、寡居这两件事在一日转眼之间必临到你；正在你多行邪术、广施符咒的时候，这两件事必全然临到你身上。","notes":[]},{"n":10,"t":"你素来倚仗自己的恶行，说：无人看见我。你的智慧聪明使你偏邪，并且你心里说：惟有我，除我以外再没有别的。","notes":[]},{"n":11,"t":"因此，祸患要临到你身；你不知何时发现灾害落在你身上，你也不能除掉；所不知道的毁灭也必忽然临到你身。","notes":["或译：如何驱逐"]},{"n":12,"t":"站起来吧！用你从幼年劳神施行的符咒和你许多的邪术；或者可得益处，或者可得强胜。","notes":[]},{"n":13,"t":"你筹划太多，以致疲倦。让那些观天象的，看星宿的，在月朔说预言的，都站起来，救你脱离所要临到你的事。","notes":[]},{"n":14,"t":"他们要像碎秸被火焚烧，不能救自己脱离火焰之力；这火并非可烤的炭火，也不是可以坐在其前的火。","notes":[]},{"n":15,"t":"你所劳神的事都要这样与你无益；从幼年与你贸易的也都各奔各乡，无人救你。","notes":[]}]},"48":{"heading":"神掌管未来","verses":[{"n":1,"t":"雅各家，称为以色列名下，从犹大水源出来的，当听我言！你们指着耶和华的名起誓，提说以色列的神，却不凭诚实，不凭公义。","notes":[]},{"n":2,"t":"他们自称为圣城的人，所倚靠的是名为万军之耶和华—以色列的神。","notes":[]},{"n":3,"t":"主说：早先的事，我从古时说明，已经出了我的口，也是我所指示的；我忽然行做，事便成就。","notes":[]},{"n":4,"t":"因为我素来知道你是顽梗的—你的颈项是铁的；你的额是铜的。","notes":[]},{"n":5,"t":"所以，我从古时将这事给你说明，在未成以先指示你，免得你说：这些事是我的偶像所行的，是我雕刻的偶像和我铸造的偶像所命定的。","notes":[]},{"n":6,"t":"你已经听见，现在要看见这一切；你不说明吗？从今以后，我将新事，就是你所不知道的隐密事指示你。","notes":[]},{"n":7,"t":"这事是现今造的，并非从古就有；在今日以先，你也未曾听见，免得你说：这事我早已知道了。","notes":[]},{"n":8,"t":"你未曾听见，未曾知道；你的耳朵从来未曾开通。我原知道你行事极其诡诈，你自从出胎以来，便称为悖逆的。","notes":[]},{"n":9,"t":"我为我的名暂且忍怒，为我的颂赞向你容忍，不将你剪除。","notes":[]},{"n":10,"t":"我熬炼你，却不像熬炼银子；你在苦难的炉中，我拣选你。","notes":[]},{"n":11,"t":"我为自己的缘故必行这事，我焉能使我的名被亵渎？我必不将我的荣耀归给假神。","notes":[]},{"n":12,"t":"雅各—我所选召的以色列啊，当听我言：我是耶和华，我是首先的，也是末后的。","notes":[],"heads":["耶和华拣选塞鲁士为领导者"]},{"n":13,"t":"我手立了地的根基；我右手铺张诸天；我一招呼便都立住。","notes":[]},{"n":14,"t":"你们都当聚集而听，他们内中谁说过这些事？耶和华所爱的人必向巴比伦行他所喜悦的事；他的膀臂也要加在迦勒底人身上。","notes":["或译：偶像"]},{"n":15,"t":"惟有我曾说过，我又选召他，领他来，他的道路就必亨通。","notes":[]},{"n":16,"t":"你们要就近我来听这话：我从起头并未曾在隐密处说话；自从有这事，我就在那里。现在，主耶和华差遣我和他的灵来。","notes":["或译：耶和华和他的灵差遣我来"]},{"n":17,"t":"耶和华—你的救赎主，以色列的圣者如此说：我是耶和华—你的神，教训你，使你得益处，引导你所当行的路。","notes":[],"heads":["耶和华对他子民的计划"]},{"n":18,"t":"甚愿你素来听从我的命令！你的平安就如河水；你的公义就如海浪。","notes":[]},{"n":19,"t":"你的后裔也必多如海沙；你腹中所生的也必多如沙粒。他的名在我面前必不剪除，也不灭绝。","notes":[]},{"n":20,"t":"你们要从巴比伦出来，从迦勒底人中逃脱，以欢呼的声音传扬说：耶和华救赎了他的仆人雅各！你们要将这事宣扬到地极。","notes":[]},{"n":21,"t":"耶和华引导他们经过沙漠。他们并不干渴；他为他们使水从磐石而流，分裂磐石，水就涌出。","notes":[]},{"n":22,"t":"耶和华说：恶人必不得平安！","notes":[]}]},"49":{"heading":"外邦之光","verses":[{"n":1,"t":"众海岛啊，当听我言！远方的众民哪，留心而听！自我出胎，耶和华就选召我；自出母腹，他就提我的名。","notes":[]},{"n":2,"t":"他使我的口如快刀，将我藏在他手荫之下；又使我成为磨亮的箭，将我藏在他箭袋之中；","notes":[]},{"n":3,"t":"对我说：你是我的仆人以色列；我必因你得荣耀。","notes":[]},{"n":4,"t":"我却说：我劳碌是徒然；我尽力是虚无虚空。然而，我当得的理必在耶和华那里；我的赏赐必在我神那里。","notes":[]},{"n":5,"t":"耶和华从我出胎，造就我作他的仆人，要使雅各归向他，使以色列到他那里聚集。原来耶和华看我为尊贵；我的神也成为我的力量。","notes":[]},{"n":6,"t":"现在他说：你作我的仆人，使雅各众支派复兴，使以色列中得保全的归回尚为小事，我还要使你作外邦人的光，叫你施行我的救恩，直到地极。","notes":[]},{"n":7,"t":"救赎主—以色列的圣者耶和华对那被人所藐视、本国所憎恶、官长所虐待的如此说：君王要看见就站起，首领也要下拜；都因信实的耶和华，就是拣选你—以色列的圣者。","notes":[]},{"n":8,"t":"耶和华如此说：在悦纳的时候，我应允了你；在拯救的日子，我济助了你。我要保护你，使你作众民的中保；复兴遍地，使人承受荒凉之地为业。","notes":["中保：原文是约"],"heads":["耶路撒冷的复兴"]},{"n":9,"t":"对那被捆绑的人说：出来吧！对那在黑暗的人说：显露吧！他们在路上必得饮食，在一切净光的高处必有食物。","notes":[]},{"n":10,"t":"不饥不渴，炎热和烈日必不伤害他们；因为怜恤他们的必引导他们，领他们到水泉旁边。","notes":[]},{"n":11,"t":"我必使我的众山成为大道；我的大路也被修高。","notes":[]},{"n":12,"t":"看哪，这些从远方来；这些从北方、从西方来；这些从秦国来。","notes":["原文是希尼"]},{"n":13,"t":"诸天哪，应当欢呼！大地啊，应当快乐！众山哪，应当发声歌唱！因为耶和华已经安慰他的百姓，也要怜恤他困苦之民。","notes":[]},{"n":14,"t":"锡安说：耶和华离弃了我；主忘记了我。","notes":[]},{"n":15,"t":"妇人焉能忘记她吃奶的婴孩，不怜恤她所生的儿子？即或有忘记的，我却不忘记你。","notes":[]},{"n":16,"t":"看哪，我将你铭刻在我掌上；你的墙垣常在我眼前。","notes":[]},{"n":17,"t":"你的儿女必急速归回；毁坏你的，使你荒废的，必都离你出去，","notes":[]},{"n":18,"t":"你举目向四方观看；他们都聚集来到你这里。耶和华说：我指着我的永生起誓：你必要以他们为妆饰佩戴，以他们为华带束腰，像新妇一样。","notes":[]},{"n":19,"t":"至于你荒废凄凉之处，并你被毁坏之地，现今众民居住必显为太窄；吞灭你的必离你遥远。","notes":[]},{"n":20,"t":"你必听见丧子之后所生的儿女说：这地方我居住太窄，求你给我地方居住。","notes":[]},{"n":21,"t":"那时你心里必说：我既丧子独居，是被掳的，漂流在外。谁给我生这些？谁将这些养大呢？撇下我一人独居的时候，这些在哪里呢？","notes":[]},{"n":22,"t":"主耶和华如此说：我必向列国举手，向万民竖立大旗；他们必将你的众子怀中抱来，将你的众女肩上扛来。","notes":[]},{"n":23,"t":"列王必作你的养父；王后必作你的乳母。他们必将脸伏地，向你下拜，并舔你脚上的尘土。你便知道我是耶和华；等候我的必不致羞愧。","notes":[]},{"n":24,"t":"勇士抢去的岂能夺回？该掳掠的岂能解救吗？","notes":[]},{"n":25,"t":"但耶和华如此说：就是勇士所掳掠的，也可以夺回；强暴人所抢的，也可以解救。与你相争的，我必与他相争；我要拯救你的儿女。","notes":[]},{"n":26,"t":"并且我必使那欺压你的吃自己的肉，也要以自己的血喝醉，好像喝甜酒一样。凡有血气的必都知道我—耶和华是你的救主，是你的救赎主，是雅各的大能者。","notes":[]}]},"50":{"heading":"耶和华仆人的顺服","verses":[{"n":1,"t":"耶和华如此说：我休你们的母亲，休书在哪里呢？我将你们卖给我哪一个债主呢？你们被卖，是因你们的罪孽；你们的母亲被休，是因你们的过犯。","notes":[]},{"n":2,"t":"我来的时候，为何无人等候呢？我呼唤的时候，为何无人答应呢？我的膀臂岂是缩短、不能救赎吗？我岂无拯救之力吗？看哪，我一斥责，海就干了；我使江河变为旷野；其中的鱼因无水腥臭，干渴而死。","notes":[]},{"n":3,"t":"我使诸天以黑暗为衣服，以麻布为遮盖。","notes":[]},{"n":4,"t":"主耶和华赐我受教者的舌头，使我知道怎样用言语扶助疲乏的人。主每早晨提醒，提醒我的耳朵，使我能听，像受教者一样。","notes":[]},{"n":5,"t":"主耶和华开通我的耳朵；我并没有违背，也没有退后。","notes":[]},{"n":6,"t":"人打我的背，我任他打；人拔我腮颊的胡须，我由他拔；人辱我，吐我，我并不掩面。","notes":[]},{"n":7,"t":"主耶和华必帮助我，所以我不抱愧。我硬着脸面好像坚石；我也知道我必不致蒙羞。","notes":[]},{"n":8,"t":"称我为义的与我相近；谁与我争论，可以与我一同站立；谁与我作对，可以就近我来。","notes":[]},{"n":9,"t":"主耶和华要帮助我；谁能定我有罪呢？他们都像衣服渐渐旧了，为蛀虫所咬。","notes":[]},{"n":10,"t":"你们中间谁是敬畏耶和华、听从他仆人之话的？这人行在暗中，没有亮光。当倚靠耶和华的名，仗赖自己的神。","notes":[]},{"n":11,"t":"凡你们点火，用火把围绕自己的可以行在你们的火焰里，并你们所点的火把中。这是我手所定的：你们必躺在悲惨之中。","notes":[]}]},"51":{"heading":"安慰耶路撒冷的话","verses":[{"n":1,"t":"你们这追求公义、寻求耶和华的，当听我言！你们要追想被凿而出的磐石，被挖而出的岩穴。","notes":[]},{"n":2,"t":"要追想你们的祖宗亚伯拉罕和生养你们的撒拉；因为亚伯拉罕独自一人的时候，我选召他，赐福与他，使他人数增多。","notes":[]},{"n":3,"t":"耶和华已经安慰锡安和锡安一切的荒场，使旷野像伊甸，使沙漠像耶和华的园囿；在其中必有欢喜、快乐、感谢，和歌唱的声音。","notes":[]},{"n":4,"t":"我的百姓啊，要向我留心；我的国民哪，要向我侧耳；因为训诲必从我而出；我必坚定我的公理为万民之光。","notes":[]},{"n":5,"t":"我的公义临近；我的救恩发出。我的膀臂要审判万民；海岛都要等候我，倚赖我的膀臂。","notes":[]},{"n":6,"t":"你们要向天举目，观看下地；因为天必像烟云消散，地必如衣服渐渐旧了；其上的居民也要如此死亡。惟有我的救恩永远长存；我的公义也不废掉。","notes":["如此死亡：或译像蠓虫死亡"]},{"n":7,"t":"知道公义、将我训诲存在心中的民，要听我言！不要怕人的辱骂，也不要因人的毁谤惊惶。","notes":[]},{"n":8,"t":"因为蛀虫必咬他们，好像咬衣服；虫子必咬他们，如同咬羊绒。惟有我的公义永远长存，我的救恩直到万代。","notes":[]},{"n":9,"t":"耶和华的膀臂啊，兴起！兴起！以能力为衣穿上，像古时的年日、上古的世代兴起一样。从前砍碎拉哈伯、刺透大鱼的，不是你吗？","notes":[]},{"n":10,"t":"使海与深渊的水干涸、使海的深处变为赎民经过之路的，不是你吗？","notes":[]},{"n":11,"t":"耶和华救赎的民必归回，歌唱来到锡安；永乐必归到他们的头上。他们必得着欢喜快乐；忧愁叹息尽都逃避。","notes":[]},{"n":12,"t":"惟有我，是安慰你们的。你是谁，竟怕那必死的人？怕那要变如草的世人？","notes":[]},{"n":13,"t":"却忘记铺张诸天、立定地基、创造你的耶和华？又因欺压者图谋毁灭要发的暴怒，整天害怕，其实那欺压者的暴怒在哪里呢？","notes":[]},{"n":14,"t":"被掳去的快得释放，必不死而下坑；他的食物也不致缺乏。","notes":[]},{"n":15,"t":"我是耶和华—你的神—搅动大海，使海中的波浪匉訇—万军之耶和华是我的名。","notes":[]},{"n":16,"t":"我将我的话传给你，用我的手影遮蔽你，为要栽定诸天，立定地基，又对锡安说：你是我的百姓。","notes":[]},{"n":17,"t":"耶路撒冷啊，兴起！兴起！站起来！你从耶和华手中喝了他忿怒之杯，喝了那使人东倒西歪的爵，以致喝尽。","notes":[],"heads":["耶路撒冷苦难的终结"]},{"n":18,"t":"她所生育的诸子中，没有一个引导她的；她所养大的诸子中，没有一个搀扶她的。","notes":[]},{"n":19,"t":"荒凉、毁灭、饥荒、刀兵，这几样临到你，谁为你举哀？我如何能安慰你呢？","notes":[]},{"n":20,"t":"你的众子发昏，在各市口上躺卧，好像黄羊在网罗之中，都满了耶和华的忿怒—你神的斥责。","notes":[]},{"n":21,"t":"因此，你这困苦却非因酒而醉的，要听我言。","notes":[]},{"n":22,"t":"你的主耶和华—就是为他百姓辨屈的神如此说：看哪，我已将那使人东倒西歪的杯，就是我忿怒的爵，从你手中接过来；你必不致再喝。","notes":[]},{"n":23,"t":"我必将这杯递在苦待你的人手中；他们曾对你说：你屈身，由我们践踏过去吧！你便以背为地，好像街市，任人经过。","notes":[]}]},"52":{"heading":"神要拯救耶路撒冷","verses":[{"n":1,"t":"锡安哪，兴起！兴起！披上你的能力！圣城耶路撒冷啊，穿上你华美的衣服！因为从今以后，未受割礼、不洁净的必不再进入你中间。","notes":[]},{"n":2,"t":"耶路撒冷啊，要抖下尘土！起来坐在位上！锡安被掳的居民哪，要解开你颈项的锁链！","notes":["原文是女子"]},{"n":3,"t":"耶和华如此说：「你们是无价被卖的，也必无银被赎。","notes":[]},{"n":4,"t":"主耶和华如此说：起先我的百姓下到埃及，在那里寄居，又有亚述人无故欺压他们。","notes":[]},{"n":5,"t":"耶和华说：我的百姓既是无价被掳去，如今我在这里做什么呢？耶和华说：辖制他们的人呼叫，我的名整天受亵渎。","notes":[]},{"n":6,"t":"所以，我的百姓必知道我的名；到那日他们必知道说这话的就是我。看哪，是我！」","notes":[]},{"n":7,"t":"那报佳音，传平安，报好信，传救恩的，对锡安说：你的神作王了！这人的脚登山何等佳美！","notes":[]},{"n":8,"t":"听啊，你守望之人的声音，他们扬起声来，一同歌唱；因为耶和华归回锡安的时候，他们必亲眼看见。","notes":[]},{"n":9,"t":"耶路撒冷的荒场啊，要发起欢声，一同歌唱；因为耶和华安慰了他的百姓，救赎了耶路撒冷。","notes":[]},{"n":10,"t":"耶和华在万国眼前露出圣臂；地极的人都看见我们神的救恩了。","notes":[]},{"n":11,"t":"你们离开吧！离开吧！从巴比伦出来。不要沾不洁净的物；要从其中出来。你们扛抬耶和华器皿的人哪，务要自洁。","notes":[]},{"n":12,"t":"你们出来必不致急忙，也不致奔逃。因为，耶和华必在你们前头行；以色列的神必作你们的后盾。","notes":[]},{"n":13,"t":"我的仆人行事必有智慧，必被高举上升，且成为至高。","notes":["或译：行事通达"],"heads":["受苦的仆人"]},{"n":14,"t":"许多人因他惊奇；他的面貌比别人憔悴；他的形容比世人枯槁。","notes":["原文是你"]},{"n":15,"t":"这样，他必洗净许多国民；君王要向他闭口。因所未曾传与他们的，他们必看见；未曾听见的，他们要明白。","notes":["或译：鼓动"]}]},"53":{"heading":"","verses":[{"n":1,"t":"我们所传的有谁信呢？耶和华的膀臂向谁显露呢？","notes":["或译：所传与我们的"]},{"n":2,"t":"他在耶和华面前生长如嫩芽，像根出于干地。他无佳形美容；我们看见他的时候，也无美貌使我们羡慕他。","notes":[]},{"n":3,"t":"他被藐视，被人厌弃；多受痛苦，常经忧患。他被藐视，好像被人掩面不看的一样；我们也不尊重他。","notes":[]},{"n":4,"t":"他诚然担当我们的忧患，背负我们的痛苦；我们却以为他受责罚，被神击打苦待了。","notes":[]},{"n":5,"t":"哪知他为我们的过犯受害，为我们的罪孽压伤。因他受的刑罚，我们得平安；因他受的鞭伤，我们得医治。","notes":[]},{"n":6,"t":"我们都如羊走迷；各人偏行己路；耶和华使我们众人的罪孽都归在他身上。","notes":[]},{"n":7,"t":"他被欺压，在受苦的时候却不开口 ；他像羊羔被牵到宰杀之地，又像羊在剪毛的人手下无声，他也是这样不开口。","notes":["或译：他受欺压，却自卑不开口"]},{"n":8,"t":"因受欺压和审判，他被夺去，至于他同世的人，谁想他受鞭打、从活人之地被剪除，是因我百姓的罪过呢？","notes":[]},{"n":9,"t":"他虽然未行强暴，口中也没有诡诈，人还使他与恶人同埋；谁知死的时候与财主同葬。","notes":[]},{"n":10,"t":"耶和华却定意将他压伤，使他受痛苦。耶和华以他为赎罪祭。他必看见后裔，并且延长年日。耶和华所喜悦的事必在他手中亨通。","notes":["或译：喜悦","或译：他献本身为赎罪祭"]},{"n":11,"t":"他必看见自己劳苦的功效，便心满意足。有许多人因认识我的义仆得称为义；并且他要担当他们的罪孽。","notes":[]},{"n":12,"t":"所以，我要使他与位大的同分，与强盛的均分掳物。因为他将命倾倒，以致于死；他也被列在罪犯之中。他却担当多人的罪，又为罪犯代求。","notes":[]}]},"54":{"heading":"耶和华对以色列的爱","verses":[{"n":1,"t":"你这不怀孕、不生养的要歌唱；你这未曾经过产难的要发声歌唱，扬声欢呼；因为没有丈夫的比有丈夫的儿女更多。这是耶和华说的。","notes":[]},{"n":2,"t":"要扩张你帐幕之地，张大你居所的幔子，不要限止；要放长你的绳子，坚固你的橛子。","notes":[]},{"n":3,"t":"因为你要向左向右开展；你的后裔必得多国为业，又使荒凉的城邑有人居住。","notes":[]},{"n":4,"t":"不要惧怕，因你必不致蒙羞；也不要抱愧，因你必不致受辱。你必忘记幼年的羞愧，不再记念你寡居的羞辱。","notes":[]},{"n":5,"t":"因为造你的是你的丈夫；万军之耶和华是他的名。救赎你的是以色列的圣者；他必称为全地之神。","notes":[]},{"n":6,"t":"耶和华召你，如召被离弃心中忧伤的妻，就是幼年所娶被弃的妻。这是你神所说的。","notes":[]},{"n":7,"t":"我离弃你不过片时，却要施大恩将你收回。","notes":[]},{"n":8,"t":"我的怒气涨溢，顷刻之间向你掩面，却要以永远的慈爱怜恤你。这是耶和华—你的救赎主说的。","notes":[]},{"n":9,"t":"这事在我好像挪亚的洪水。我怎样起誓不再使挪亚的洪水漫过遍地，我也照样起誓不再向你发怒，也不斥责你。","notes":[]},{"n":10,"t":"大山可以挪开，小山可以迁移；但我的慈爱必不离开你；我平安的约也不迁移。这是怜恤你的耶和华说的。","notes":[]},{"n":11,"t":"你这受困苦、被风飘荡不得安慰的人哪，我必以彩色安置你的石头，以蓝宝石立定你的根基；","notes":[],"heads":["耶路撒冷的将来"]},{"n":12,"t":"又以红宝石造你的女墙，以红玉造你的城门，以宝石造你四围的边界。","notes":["或译：外郭"]},{"n":13,"t":"你的儿女都要受耶和华的教训；你的儿女必大享平安。","notes":[]},{"n":14,"t":"你必因公义得坚立，必远离欺压，不致害怕；你必远离惊吓，惊吓必不临近你。","notes":[]},{"n":15,"t":"即或有人聚集，却不由于我；凡聚集攻击你的，必因你仆倒。","notes":["或译：投降你"]},{"n":16,"t":"吹嘘炭火、打造合用器械的铁匠是我所造；残害人、行毁灭的也是我所造。","notes":[]},{"n":17,"t":"凡为攻击你造成的器械必不利用；凡在审判时兴起用舌攻击你的，你必定他为有罪。这是耶和华仆人的产业，是他们从我所得的义。这是耶和华说的。","notes":[]}]},"55":{"heading":"神要施怜悯","verses":[{"n":1,"t":"你们一切干渴的都当就近水来；没有银钱的也可以来。你们都来，买了吃；不用银钱，不用价值，也来买酒和奶。","notes":[]},{"n":2,"t":"你们为何花钱买那不足为食物的？用劳碌得来的买那不使人饱足的呢？你们要留意听我的话就能吃那美物，得享肥甘，心中喜乐。","notes":["原文是平银"]},{"n":3,"t":"你们当就近我来；侧耳而听，就必得活。我必与你们立永约，就是应许大卫那可靠的恩典。","notes":[]},{"n":4,"t":"我已立他作万民的见证，为万民的君王和司令。","notes":[]},{"n":5,"t":"你素不认识的国民，你也必召来；素不认识你的国民也必向你奔跑，都因耶和华—你的神以色列的圣者，因为他已经荣耀你。","notes":[]},{"n":6,"t":"当趁耶和华可寻找的时候寻找他，相近的时候求告他。","notes":[]},{"n":7,"t":"恶人当离弃自己的道路；不义的人当除掉自己的意念。归向耶和华，耶和华就必怜恤他；当归向我们的神，因为神必广行赦免。","notes":[]},{"n":8,"t":"耶和华说：我的意念非同你们的意念；我的道路非同你们的道路。","notes":[]},{"n":9,"t":"天怎样高过地，照样，我的道路高过你们的道路；我的意念高过你们的意念。","notes":[]},{"n":10,"t":"雨雪从天而降，并不返回，却滋润地土，使地上发芽结实，使撒种的有种，使要吃的有粮。","notes":[]},{"n":11,"t":"我口所出的话也必如此，决不徒然返回，却要成就我所喜悦的，在我发他去成就的事上必然亨通。","notes":["发他去成就：或译所命定"]},{"n":12,"t":"你们必欢欢喜喜而出来，平平安安蒙引导。大山小山必在你们面前发声歌唱；田野的树木也都拍掌。","notes":[]},{"n":13,"t":"松树长出，代替荆棘；番石榴长出，代替蒺藜。这要为耶和华留名，作为永远的证据，不能剪除。","notes":[]}]},"56":{"heading":"神的子民将包括各国的百姓","verses":[{"n":1,"t":"耶和华如此说：你们当守公平，行公义；因我的救恩临近，我的公义将要显现。","notes":[]},{"n":2,"t":"谨守安息日而不干犯，禁止己手而不作恶；如此行、如此持守的人便为有福。","notes":[]},{"n":3,"t":"与耶和华联合的外邦人不要说：耶和华必定将我从他民中分别出来。太监也不要说：我是枯树。","notes":[]},{"n":4,"t":"因为耶和华如此说：那些谨守我的安息日，拣选我所喜悦的事，持守我约的太监，","notes":[]},{"n":5,"t":"我必使他们在我殿中，在我墙内，有记念，有名号，比有儿女的更美。我必赐他们永远的名，不能剪除。","notes":[]},{"n":6,"t":"还有那些与耶和华联合的外邦人，要事奉他，要爱耶和华的名，要作他的仆人—就是凡守安息日不干犯，又持守他约的人。","notes":["原文是我"]},{"n":7,"t":"我必领他们到我的圣山，使他们在祷告我的殿中喜乐。他们的燔祭和平安祭，在我坛上必蒙悦纳，因我的殿必称为万民祷告的殿。","notes":[]},{"n":8,"t":"主耶和华，就是招聚以色列被赶散的，说：在这被招聚的人以外，我还要招聚别人归并他们。","notes":[]},{"n":9,"t":"田野的诸兽都来吞吃吧！林中的诸兽也要如此。","notes":[],"heads":["以色列的领袖被定罪"]},{"n":10,"t":"他看守的人是瞎眼的，都没有知识，都是哑巴狗，不能叫唤；但知做梦，躺卧，贪睡，","notes":[]},{"n":11,"t":"这些狗贪食，不知饱足。这些牧人不能明白—各人偏行己路，各从各方求自己的利益。","notes":[]},{"n":12,"t":"他们说：来吧！我去拿酒，我们饱饮浓酒；明日必和今日一样，就是宴乐无量极大之日。","notes":[]}]},"57":{"heading":"以色列拜偶像被定罪","verses":[{"n":1,"t":"义人死亡，无人放在心上；虔诚人被收去，无人思念。这义人被收去是免了将来的祸患；","notes":[]},{"n":2,"t":"他们得享平安。素行正直的，各人在坟里安歇。","notes":["原文是进入","原文是床上"]},{"n":3,"t":"你们这些巫婆的儿子，奸夫和妓女的种子，都要前来！","notes":[]},{"n":4,"t":"你们向谁戏笑？向谁张口吐舌呢？你们岂不是悖逆的儿女，虚谎的种类呢？","notes":[]},{"n":5,"t":"你们在橡树中间，在各青翠树下欲火攻心；在山谷间，在石穴下杀了儿女；","notes":[]},{"n":6,"t":"在谷中光滑石头里有你的分。这些就是你所得的分；你也向他浇了奠祭，献了供物，因这事我岂能容忍吗？","notes":[]},{"n":7,"t":"你在高而又高的山上安设床榻，也上那里去献祭。","notes":[]},{"n":8,"t":"你在门后，在门框后，立起你的纪念；向外人赤露，又上去扩张床榻，与他们立约；你在那里看见他们的床就甚喜爱。","notes":[]},{"n":9,"t":"你把油带到王那里，又多加香料，打发使者往远方去，自卑自贱直到阴间，","notes":[]},{"n":10,"t":"你因路远疲倦，却不说这是枉然；你以为有复兴之力，所以不觉疲惫。","notes":[]},{"n":11,"t":"你怕谁？因谁恐惧？竟说谎，不记念我，又不将这事放在心上。我不是许久闭口不言，你仍不怕我吗？","notes":[]},{"n":12,"t":"我要指明你的公义；至于你所行的都必与你无益。","notes":[]},{"n":13,"t":"你哀求的时候，让你所聚集的拯救你吧！风要把他们刮散，一口气要把他们都吹去。但那投靠我的必得地土，必承受我的圣山为业。","notes":[]},{"n":14,"t":"耶和华要说：你们修筑修筑，预备道路，将绊脚石从我百姓的路中除掉。","notes":[],"heads":["神应许帮助和医治"]},{"n":15,"t":"因为那至高至上、永远长存名为圣者的如此说：我住在至高至圣的所在，也与心灵痛悔谦卑的人同居；要使谦卑人的灵苏醒，也使痛悔人的心苏醒。","notes":["原文是住在永远"]},{"n":16,"t":"我必不永远相争，也不长久发怒，恐怕我所造的人与灵性都必发昏。","notes":[]},{"n":17,"t":"因他贪婪的罪孽，我就发怒击打他；我向他掩面发怒，他却仍然随心背道。","notes":[]},{"n":18,"t":"我看见他所行的道，也要医治他；又要引导他，使他和那一同伤心的人再得安慰。","notes":[]},{"n":19,"t":"我造就嘴唇的果子；愿平安康泰归与远处的人，也归与近处的人；并且我要医治他。这是耶和华说的。","notes":[]},{"n":20,"t":"惟独恶人，好像翻腾的海，不得平静；其中的水常涌出污秽和淤泥来。","notes":[]},{"n":21,"t":"我的神说：恶人必不得平安！","notes":[]}]},"58":{"heading":"真正的禁食","verses":[{"n":1,"t":"你要大声喊叫，不可止息；扬起声来，好像吹角。向我百姓说明他们的过犯；向雅各家说明他们的罪恶。","notes":[]},{"n":2,"t":"他们天天寻求我，乐意明白我的道，好像行义的国民，不离弃他们神的典章，向我求问公义的判语，喜悦亲近神。","notes":[]},{"n":3,"t":"他们说：我们禁食，你为何不看见呢？我们刻苦己心，你为何不理会呢？看哪，你们禁食的日子仍求利益，勒逼人为你们做苦工。","notes":[]},{"n":4,"t":"你们禁食，却互相争竞，以凶恶的拳头打人。你们今日禁食，不得使你们的声音听闻于上。","notes":[]},{"n":5,"t":"这样禁食岂是我所拣选、使人刻苦己心的日子吗？岂是叫人垂头像苇子，用麻布和炉灰铺在他以下吗？你这可称为禁食、为耶和华所悦纳的日子吗？","notes":[]},{"n":6,"t":"我所拣选的禁食不是要松开凶恶的绳，解下轭上的索，使被欺压的得自由，折断一切的轭吗？","notes":[]},{"n":7,"t":"不是要把你的饼分给饥饿的人，将飘流的穷人接到你家中，见赤身的给他衣服遮体，顾恤自己的骨肉而不掩藏吗？","notes":[]},{"n":8,"t":"这样，你的光就必发现如早晨的光；你所得的医治要速速发明。你的公义必在你前面行；耶和华的荣光必作你的后盾。","notes":[]},{"n":9,"t":"那时你求告，耶和华必应允；你呼求，他必说：我在这里。你若从你中间除掉重轭和指摘人的指头，并发恶言的事，","notes":[]},{"n":10,"t":"你心若向饥饿的人发怜悯，使困苦的人得满足，你的光就必在黑暗中发现；你的幽暗必变如正午。","notes":[]},{"n":11,"t":"耶和华也必时常引导你，在干旱之地使你心满意足，骨头强壮。你必像浇灌的园子，又像水流不绝的泉源。","notes":[]},{"n":12,"t":"那些出于你的人必修造久已荒废之处；你要建立拆毁累代的根基。你必称为补破口的，和重修路径与人居住的。","notes":[]},{"n":13,"t":"你若在安息日掉转你的脚步，在我圣日不以操作为喜乐，称安息日为可喜乐的，称耶和华的圣日为可尊重的；而且尊敬这日，不办自己的私事，不随自己的私意，不说自己的私话，","notes":["或译：谨慎"],"heads":["守安息日者的报赏"]},{"n":14,"t":"你就以耶和华为乐。耶和华要使你乘驾地的高处，又以你祖雅各的产业养育你。这是耶和华亲口说的。","notes":[]}]},"59":{"heading":"先知指责百姓的罪恶","verses":[{"n":1,"t":"耶和华的膀臂并非缩短，不能拯救，耳朵并非发沉，不能听见，","notes":[]},{"n":2,"t":"但你们的罪孽使你们与神隔绝；你们的罪恶使他掩面不听你们。","notes":[]},{"n":3,"t":"因你们的手被血沾染，你们的指头被罪孽沾污，你们的嘴唇说谎言，你们的舌头出恶语。","notes":[]},{"n":4,"t":"无一人按公义告状，无一人凭诚实辨白；都倚靠虚妄，说谎言。所怀的是毒害；所生的是罪孽。","notes":[]},{"n":5,"t":"他们抱毒蛇蛋，结蜘蛛网；人吃这蛋必死。这蛋被踏，必出蝮蛇。","notes":[]},{"n":6,"t":"所结的网不能成为衣服；所做的也不能遮盖自己。他们的行为都是罪孽；手所做的都是强暴。","notes":[]},{"n":7,"t":"他们的脚奔跑行恶；他们急速流无辜人的血；意念都是罪孽，所经过的路都荒凉毁灭。","notes":[]},{"n":8,"t":"平安的路，他们不知道；所行的事没有公平。他们为自己修弯曲的路；凡行此路的都不知道平安。","notes":[]},{"n":9,"t":"因此，公平离我们远，公义追不上我们。我们指望光亮，却是黑暗，指望光明，却行幽暗。","notes":[],"heads":["百姓悔罪"]},{"n":10,"t":"我们摸索墙壁，好像瞎子；我们摸索，如同无目之人。我们晌午绊脚，如在黄昏一样；我们在肥壮人中，像死人一般。","notes":[]},{"n":11,"t":"我们咆哮如熊，哀鸣如鸽；指望公平，却是没有；指望救恩，却远离我们。","notes":[]},{"n":12,"t":"我们的过犯在你面前增多，罪恶作见证告我们；过犯与我们同在。至于我们的罪孽，我们都知道：","notes":[]},{"n":13,"t":"就是悖逆、不认识耶和华，转去不跟从我们的神，说欺压和叛逆的话，心怀谎言，随即说出。","notes":[]},{"n":14,"t":"并且公平转而退后，公义站在远处；诚实在街上仆倒，正直也不得进入。","notes":[]},{"n":15,"t":"诚实少见；离恶的人反成掠物。那时，耶和华看见没有公平，甚不喜悦。","notes":[]},{"n":16,"t":"他见无人拯救，无人代求，甚为诧异，就用自己的膀臂施行拯救，以公义扶持自己。","notes":[]},{"n":17,"t":"他以公义为铠甲，以拯救为头盔，以报仇为衣服，以热心为外袍。","notes":["或译：护心镜"]},{"n":18,"t":"他必按人的行为施报，恼怒他的敌人，报复他的仇敌向众海岛施行报应。","notes":[]},{"n":19,"t":"如此，人从日落之处必敬畏耶和华的名，从日出之地也必敬畏他的荣耀；因为仇敌好像急流的河水冲来，是耶和华之气所驱逐的。","notes":[]},{"n":20,"t":"必有一位救赎主来到锡安—雅各族中转离过犯的人那里。这是耶和华说的。","notes":[]},{"n":21,"t":"耶和华说：「至于我与他们所立的约乃是这样：我加给你的灵，传给你的话，必不离你的口，也不离你后裔与你后裔之后裔的口，从今直到永远；这是耶和华说的。」","notes":[]}]},"60":{"heading":"耶路撒冷未来的荣耀","verses":[{"n":1,"t":"兴起，发光！因为你的光已经来到！耶和华的荣耀发现照耀你。","notes":[]},{"n":2,"t":"看哪，黑暗遮盖大地，幽暗遮盖万民，耶和华却要显现照耀你；他的荣耀要现在你身上。","notes":[]},{"n":3,"t":"万国要来就你的光；君王要来就你发现的光辉。","notes":[]},{"n":4,"t":"你举目向四方观看；众人都聚集来到你这里。你的众子从远方而来；你的众女也被怀抱而来。","notes":[]},{"n":5,"t":"那时，你看见就有光荣；你心又跳动又宽畅；因为大海丰盛的货物必转来归你；列国的财宝也必来归你。","notes":[]},{"n":6,"t":"成群的骆驼，并米甸和以法的独峰驼必遮满你；示巴的众人都必来到；要奉上黄金乳香，又要传说耶和华的赞美。","notes":[]},{"n":7,"t":"基达的羊群都必聚集到你这里，尼拜约的公羊要供你使用，在我坛上必蒙悦纳；我必荣耀我荣耀的殿。","notes":[]},{"n":8,"t":"那些飞来如云、又如鸽子向窗户飞回的是谁呢？","notes":[]},{"n":9,"t":"众海岛必等候我，首先是他施的船只，将你的众子连他们的金银从远方一同带来，都为耶和华—你神的名，又为以色列的圣者，因为他已经荣耀了你。","notes":[]},{"n":10,"t":"外邦人必建筑你的城墙；他们的王必服事你。我曾发怒击打你，现今却施恩怜恤你。","notes":[]},{"n":11,"t":"你的城门必时常开放，昼夜不关；使人把列国的财物带来归你，并将他们的君王牵引而来。","notes":[]},{"n":12,"t":"哪一邦哪一国不事奉你，就必灭亡，也必全然荒废。","notes":[]},{"n":13,"t":"黎巴嫩的荣耀，就是松树、杉树、黄杨树，都必一同归你，为要修饰我圣所之地；我也要使我脚踏之处得荣耀。","notes":[]},{"n":14,"t":"素来苦待你的，他的子孙都必屈身来就你；藐视你的，都要在你脚下跪拜。他们要称你为「耶和华的城」，为「以色列圣者的锡安」。","notes":[]},{"n":15,"t":"你虽然被撇弃被厌恶，甚至无人经过，我却使你变为永远的荣华，成为累代的喜乐。","notes":[]},{"n":16,"t":"你也必吃万国的奶，又吃君王的奶。你便知道我—耶和华是你的救主，是你的救赎主，雅各的大能者。","notes":[]},{"n":17,"t":"我要拿金子代替铜，拿银子代替铁，拿铜代替木头，拿铁代替石头；并要以和平为你的官长，以公义为你的监督。","notes":[]},{"n":18,"t":"你地上不再听见强暴的事，境内不再听见荒凉毁灭的事。你必称你的墙为「拯救」，称你的门为「赞美」。","notes":[]},{"n":19,"t":"日头不再作你白昼的光；月亮也不再发光照耀你。耶和华却要作你永远的光；你神要为你的荣耀。","notes":[]},{"n":20,"t":"你的日头不再下落；你的月亮也不退缩；因为耶和华必作你永远的光。你悲哀的日子也完毕了。","notes":[]},{"n":21,"t":"你的居民都成为义人，永远得地为业；是我种的栽子，我手的工作，使我得荣耀。","notes":[]},{"n":22,"t":"至小的族要加增千倍；微弱的国必成为强盛。我—耶和华要按定期速成这事。","notes":[]}]},"61":{"heading":"拯救的好消息","verses":[{"n":1,"t":"主耶和华的灵在我身上；因为耶和华用膏膏我，叫我传好信息给谦卑的人，差遣我医好伤心的人，报告被掳的得释放，被囚的出监牢；","notes":["或译：传福音给贫穷的人"]},{"n":2,"t":"报告耶和华的恩年，和我们神报仇的日子；安慰一切悲哀的人，","notes":[]},{"n":3,"t":"赐华冠与锡安悲哀的人，代替灰尘；喜乐油代替悲哀；赞美衣代替忧伤之灵；使他们称为「公义树」，是耶和华所栽的，叫他得荣耀。","notes":[]},{"n":4,"t":"他们必修造已久的荒场，建立先前凄凉之处，重修历代荒凉之城。","notes":[]},{"n":5,"t":"那时，外人必起来牧放你们的羊群；外邦人必作你们耕种田地的，修理葡萄园的。","notes":[]},{"n":6,"t":"你们倒要称为耶和华的祭司；人必称你们为我们神的仆役。你们必吃用列国的财物，因得他们的荣耀自夸。","notes":[]},{"n":7,"t":"你们必得加倍的好处，代替所受的羞辱；分中所得的喜乐，必代替所受的凌辱。在境内必得加倍的产业；永远之乐必归与你们。","notes":["原文是他们"]},{"n":8,"t":"因为我—耶和华喜爱公平，恨恶抢夺和罪孽；我要凭诚实施行报应，并要与我的百姓立永约。","notes":[]},{"n":9,"t":"他们的后裔必在列国中被人认识；他们的子孙在众民中也是如此。凡看见他们的必认他们是耶和华赐福的后裔。","notes":[]},{"n":10,"t":"我因耶和华大大欢喜；我的心靠神快乐。因他以拯救为衣给我穿上，以公义为袍给我披上，好像新郎戴上华冠，又像新妇佩戴妆饰。","notes":[]},{"n":11,"t":"田地怎样使百谷发芽，园子怎样使所种的发生，主耶和华必照样使公义和赞美在万民中发出。","notes":[]}]},"62":{"heading":"","verses":[{"n":1,"t":"我因锡安必不静默，为耶路撒冷必不息声，直到他的公义如光辉发出，他的救恩如明灯发亮。","notes":[]},{"n":2,"t":"列国必见你的公义；列王必见你的荣耀。你必得新名的称呼，是耶和华亲口所起的。","notes":[]},{"n":3,"t":"你在耶和华的手中要作为华冠，在你神的掌上必作为冕旒。","notes":[]},{"n":4,"t":"你必不再称为「撇弃的」；你的地也不再称为「荒凉的」。你却要称为「我所喜悦的」；你的地也必称为「有夫之妇」。因为耶和华喜悦你，你的地也必归他。","notes":[]},{"n":5,"t":"少年人怎样娶处女，你的众民也要照样娶你；新郎怎样喜悦新妇，你的神也要照样喜悦你。","notes":["民：原文是子"]},{"n":6,"t":"耶路撒冷啊，我在你城上设立守望的，他们昼夜必不静默。呼吁耶和华的，你们不要歇息，","notes":[]},{"n":7,"t":"也不要使他歇息，直等他建立耶路撒冷，使耶路撒冷在地上成为可赞美的。","notes":[]},{"n":8,"t":"耶和华指着自己的右手和大能的膀臂起誓说：我必不再将你的五谷给你仇敌作食物；外邦人也不再喝你劳碌得来的新酒。","notes":[]},{"n":9,"t":"惟有那收割的要吃，并赞美耶和华；那聚敛的要在我圣所的院内喝。","notes":[]},{"n":10,"t":"你们当从门经过经过，预备百姓的路；修筑修筑大道，捡去石头，为万民竖立大旗，","notes":[]},{"n":11,"t":"看哪，耶和华曾宣告到地极，对锡安的居民说：你的拯救者来到。他的赏赐在他那里；他的报应在他面前。","notes":["原文是女子"]},{"n":12,"t":"人必称他们为「圣民」，为「耶和华的赎民」；你也必称为「被眷顾、不撇弃的城」。","notes":[]}]},"63":{"heading":"耶和华恩待以色列","verses":[{"n":1,"t":"这从以东的波斯拉来，穿红衣服，装扮华美，能力广大，大步行走的是谁呢？就是我，是凭公义说话，以大能施行拯救。","notes":[]},{"n":2,"t":"你的装扮为何有红色？你的衣服为何像踹酒榨的呢？","notes":[]},{"n":3,"t":"我独自踹酒榨；众民中无一人与我同在。我发怒将他们踹下，发烈怒将他们践踏。他们的血溅在我衣服上，并且污染了我一切的衣裳。","notes":[]},{"n":4,"t":"因为，报仇之日在我心中；救赎我民之年已经来到。","notes":[]},{"n":5,"t":"我仰望，见无人帮助；我诧异，没有人扶持。所以，我自己的膀臂为我施行拯救；我的烈怒将我扶持。","notes":[]},{"n":6,"t":"我发怒，踹下众民；发烈怒，使他们沉醉，又将他们的血倒在地上。","notes":[]},{"n":7,"t":"我要照耶和华一切所赐给我们的，提起他的慈爱和美德，并他向以色列家所施的大恩；这恩是照他的怜恤和丰盛的慈爱赐给他们的。","notes":[],"heads":["耶和华对以色列的良善"]},{"n":8,"t":"他说：他们诚然是我的百姓，不行虚假的子民；这样，他就作了他们的救主。","notes":[]},{"n":9,"t":"他们在一切苦难中，他也同受苦难；并且他面前的使者拯救他们；他以慈爱和怜悯救赎他们；在古时的日子常保抱他们，怀搋他们。","notes":[]},{"n":10,"t":"他们竟悖逆，使主的圣灵担忧。他就转作他们的仇敌，亲自攻击他们。","notes":[]},{"n":11,"t":"那时，他们想起古时的日子—摩西和他百姓，说：将百姓和牧养他全群的人从海里领上来的在哪里呢？将他的圣灵降在他们中间的在哪里呢？","notes":["原文是他"]},{"n":12,"t":"使他荣耀的膀臂在摩西的右手边行动，在他们前面将水分开，要建立自己永远的名，","notes":[]},{"n":13,"t":"带领他们经过深处，如马行走旷野，使他们不致绊跌的在哪里呢？","notes":[]},{"n":14,"t":"耶和华的灵使他们得安息，仿佛牲畜下到山谷；照样，你也引导你的百姓，要建立自己荣耀的名。","notes":[]},{"n":15,"t":"求你从天上垂顾，从你圣洁荣耀的居所观看。你的热心和你大能的作为在哪里呢？你爱慕的心肠和怜悯向我们止住了。","notes":[],"heads":["求主怜悯帮助"]},{"n":16,"t":"亚伯拉罕虽然不认识我们，以色列也不承认我们，你却是我们的父。耶和华啊，你是我们的父；从万古以来，你名称为「我们的救赎主」。","notes":[]},{"n":17,"t":"耶和华啊，你为何使我们走差离开你的道，使我们心里刚硬、不敬畏你呢？求你为你仆人，为你产业支派的缘故，转回来。","notes":[]},{"n":18,"t":"你的圣民不过暂时得这产业；我们的敌人已经践踏你的圣所。","notes":[]},{"n":19,"t":"我们好像你未曾治理的人，又像未曾得称你名下的人。","notes":[]}]},"64":{"heading":"","verses":[{"n":1,"t":"愿你裂天而降；愿山在你面前震动—","notes":[]},{"n":2,"t":"好像火烧干柴，又像火将水烧开，使你敌人知道你的名，使列国在你面前发颤！","notes":[]},{"n":3,"t":"你曾行我们不能逆料可畏的事。那时你降临，山岭在你面前震动。","notes":[]},{"n":4,"t":"从古以来，人未曾听见、未曾耳闻、未曾眼见在你以外有什么神为等候他的人行事。","notes":[]},{"n":5,"t":"你迎接那欢喜行义、记念你道的人；你曾发怒，我们仍犯罪；这景况已久，我们还能得救吗？","notes":[]},{"n":6,"t":"我们都像不洁净的人；所有的义都像污秽的衣服。我们都像叶子渐渐枯干；我们的罪孽好像风把我们吹去。","notes":[]},{"n":7,"t":"并且无人求告你的名；无人奋力抓住你。原来你掩面不顾我们，使我们因罪孽消化。","notes":[]},{"n":8,"t":"耶和华啊，现在你仍是我们的父！我们是泥，你是窑匠；我们都是你手的工作。","notes":[]},{"n":9,"t":"耶和华啊，求你不要大发震怒，也不要永远记念罪孽。求你垂顾我们，我们都是你的百姓。","notes":[]},{"n":10,"t":"你的圣邑变为旷野。锡安变为旷野；耶路撒冷成为荒场。","notes":[]},{"n":11,"t":"我们圣洁华美的殿—就是我们列祖赞美你的所在被火焚烧；我们所羡慕的美地尽都荒废。","notes":[]},{"n":12,"t":"耶和华啊，有这些事，你还忍得住吗？你仍静默使我们深受苦难吗？","notes":[]}]},"65":{"heading":"神对悖逆者的惩罚","verses":[{"n":1,"t":"素来没有访问我的，现在求问我；没有寻找我的，我叫他们遇见；没有称为我名下的，我对他们说：我在这里！我在这里！","notes":[]},{"n":2,"t":"我整天伸手招呼那悖逆的百姓；他们随自己的意念行不善之道。","notes":[]},{"n":3,"t":"这百姓时常当面惹我发怒；在园中献祭，在坛上烧香；","notes":["原文是砖"]},{"n":4,"t":"在坟墓间坐着，在隐密处住宿，吃猪肉；他们器皿中有可憎之物做的汤；","notes":[]},{"n":5,"t":"且对人说：你站开吧！不要挨近我，因为我比你圣洁。主说：这些人是我鼻中的烟，是整天烧着的火。","notes":[]},{"n":6,"t":"看哪，这都写在我面前。我必不静默，必施行报应，必将你们的罪孽和你们列祖的罪孽，就是在山上烧香，在冈上亵渎我的罪孽，一同报应在他们后人怀中，我先要把他们所行的量给他们；这是耶和华说的。","notes":[],"end":7},{"n":8,"t":"耶和华如此说：葡萄中寻得新酒，人就说：不要毁坏，因为福在其中。我因我仆人的缘故也必照样而行，不将他们全然毁灭。","notes":[]},{"n":9,"t":"我必从雅各中领出后裔，从犹大中领出承受我众山的。我的选民必承受；我的仆人要在那里居住。","notes":[]},{"n":10,"t":"沙仑平原必成为羊群的圈；亚割谷必成为牛群躺卧之处，都为寻求我的民所得。","notes":[]},{"n":11,"t":"但你们这些离弃耶和华、忘记我的圣山、给时运摆筵席、给天命盛满调和酒的，","notes":["原文是桌子"]},{"n":12,"t":"我要命定你们归在刀下，都必屈身被杀；因为我呼唤，你们没有答应；我说话，你们没有听从；反倒行我眼中看为恶的，拣选我所不喜悦的。","notes":[]},{"n":13,"t":"所以，主耶和华如此说：我的仆人必得吃，你们却饥饿；我的仆人必得喝，你们却干渴；我的仆人必欢喜，你们却蒙羞。","notes":[]},{"n":14,"t":"我的仆人因心中高兴欢呼，你们却因心中忧愁哀哭，又因心里忧伤哀号。","notes":[]},{"n":15,"t":"你们必留下自己的名，为我选民指着赌咒。主耶和华必杀你们，另起别名称呼他的仆人。","notes":[]},{"n":16,"t":"这样，在地上为自己求福的，必凭真实的神求福；在地上起誓的，必指真实的神起誓。因为，从前的患难已经忘记，也从我眼前隐藏了。","notes":[]},{"n":17,"t":"看哪！我造新天新地；从前的事不再被记念，也不再追想。","notes":[],"heads":["新天新地"]},{"n":18,"t":"你们当因我所造的永远欢喜快乐；因我造耶路撒冷为人所喜，造其中的居民为人所乐。","notes":[]},{"n":19,"t":"我必因耶路撒冷欢喜，因我的百姓快乐；其中必不再听见哭泣的声音和哀号的声音。","notes":[]},{"n":20,"t":"其中必没有数日夭亡的婴孩，也没有寿数不满的老者；因为百岁死的仍算孩童，有百岁死的罪人算被咒诅。","notes":[]},{"n":21,"t":"他们要建造房屋，自己居住；栽种葡萄园，吃其中的果子。","notes":[]},{"n":22,"t":"他们建造的，别人不得住；他们栽种的，别人不得吃；因为我民的日子必像树木的日子；我选民亲手劳碌得来的必长久享用。","notes":[]},{"n":23,"t":"他们必不徒然劳碌，所生产的，也不遭灾害，因为都是蒙耶和华赐福的后裔；他们的子孙也是如此。","notes":[]},{"n":24,"t":"他们尚未求告，我就应允；正说话的时候，我就垂听。","notes":[]},{"n":25,"t":"豺狼必与羊羔同食；狮子必吃草与牛一样；尘土必作蛇的食物。在我圣山的遍处，这一切都不伤人，不害物。这是耶和华说的。","notes":[]}]},"66":{"heading":"耶和华审判万民","verses":[{"n":1,"t":"耶和华如此说：天是我的座位；地是我的脚凳。你们要为我造何等的殿宇？哪里是我安息的地方呢？","notes":[]},{"n":2,"t":"耶和华说：这一切都是我手所造的，所以就都有了。但我所看顾的，就是虚心痛悔、因我话而战兢的人。","notes":["原文是贫穷"]},{"n":3,"t":"假冒为善的宰牛，好像杀人，献羊羔，好像打折狗项，献供物，好像献猪血，烧乳香，好像称颂偶像。这等人拣选自己的道路，心里喜悦行可憎恶的事。","notes":[]},{"n":4,"t":"我也必拣选迷惑他们的事，使他们所惧怕的临到他们；因为我呼唤，无人答应；我说话，他们不听从；反倒行我眼中看为恶的，拣选我所不喜悦的。","notes":[]},{"n":5,"t":"你们因耶和华言语战兢的人当听他的话：你们的弟兄—就是恨恶你们，因我名赶出你们的，曾说：愿耶和华得荣耀，使我们得见你们的喜乐；但蒙羞的究竟是他们！","notes":[]},{"n":6,"t":"有喧哗的声音出自城中！有声音出于殿中！是耶和华向仇敌施行报应的声音！","notes":[]},{"n":7,"t":"锡安未曾劬劳就生产，未觉疼痛就生出男孩。","notes":[]},{"n":8,"t":"国岂能一日而生？民岂能一时而产？因为锡安一劬劳便生下儿女，这样的事谁曾听见？谁曾看见呢？","notes":[]},{"n":9,"t":"耶和华说：我既使她临产，岂不使她生产呢？你的神说：我既使她生产，岂能使她闭胎不生呢？","notes":[]},{"n":10,"t":"你们爱慕耶路撒冷的都要与她一同欢喜快乐；你们为她悲哀的都要与她一同乐上加乐；","notes":[]},{"n":11,"t":"使你们在她安慰的怀中吃奶得饱，使他们得她丰盛的荣耀，犹如挤奶，满心喜乐。","notes":[]},{"n":12,"t":"耶和华如此说：我要使平安延及她，好像江河，使列国的荣耀延及她，如同涨溢的河。你们要从中享受；你们必蒙抱在肋旁，摇弄在膝上。","notes":["原文是咂"]},{"n":13,"t":"母亲怎样安慰儿子，我就照样安慰你们；你们也必因耶路撒冷得安慰。","notes":["或译：在"]},{"n":14,"t":"你们看见，就心中快乐；你们的骨头必得滋润像嫩草一样；而且耶和华的手向他仆人所行的必被人知道；他也要向仇敌发恼恨。","notes":[]},{"n":15,"t":"看哪，耶和华必在火中降临；他的车辇像旋风，以烈怒施行报应，以火焰施行责罚；","notes":[]},{"n":16,"t":"因为耶和华在一切有血气的人身上，必以火与刀施行审判；被耶和华所杀的必多。","notes":[]},{"n":17,"t":"「那些分别为圣、洁净自己的，进入园内跟在其中一个人的后头，吃猪肉和仓鼠并可憎之物，他们必一同灭绝；这是耶和华说的。","notes":[]},{"n":18,"t":"「我知道他们的行为和他们的意念。时候将到，我必将万民万族聚来，看见我的荣耀，","notes":["族：原文是舌"]},{"n":19,"t":"我要显神迹在他们中间。逃脱的，我要差到列国去，就是到他施、普勒、拉弓的路德和土巴、雅完，并素来没有听见我名声、没有看见我荣耀辽远的海岛；他们必将我的荣耀传扬在列国中。","notes":["或译：记号"]},{"n":20,"t":"他们必将你们的弟兄从列国中送回，使他们或骑马，或坐车，坐轿，骑骡子，骑独峰驼，到我的圣山耶路撒冷，作为供物献给耶和华，好像以色列人用洁净的器皿盛供物奉到耶和华的殿中；这是耶和华说的。","notes":[]},{"n":21,"t":"耶和华说：我也必从他们中间取人为祭司，为利未人。」","notes":[]},{"n":22,"t":"耶和华说：我所要造的新天新地，怎样在我面前长存；你们的后裔和你们的名字也必照样长存。","notes":[]},{"n":23,"t":"每逢月朔、安息日，凡有血气的必来在我面前下拜。这是耶和华说的。","notes":[]},{"n":24,"t":"他们必出去观看那些违背我人的尸首；因为他们的虫是不死的；他们的火是不灭的；凡有血气的都必憎恶他们。","notes":[]}]}},"JER":{"1":{"heading":"耶利米蒙选召","verses":[{"n":1,"t":"便雅悯地亚拿突城的祭司中，希勒家的儿子耶利米的话记在下面。","notes":[]},{"n":2,"t":"犹大王亚们的儿子约西亚在位十三年，耶和华的话临到耶利米。","notes":[]},{"n":3,"t":"从犹大王约西亚的儿子约雅敬在位的时候，直到犹大王约西亚的儿子西底家在位的末年，就是十一年五月间耶路撒冷人被掳的时候，耶和华的话也常临到耶利米。","notes":[]},{"n":4,"t":"耶利米说，耶和华的话临到我说：","notes":[]},{"n":5,"t":"我未将你造在腹中，我已晓得你；你未出母胎，我已分别你为圣；我已派你作列国的先知。","notes":[]},{"n":6,"t":"我就说：主耶和华啊，我不知怎样说，因为我是年幼的。","notes":[]},{"n":7,"t":"耶和华对我说：你不要说我是年幼的，因为我差遣你到谁那里去，你都要去；我吩咐你说什么话，你都要说。","notes":[]},{"n":8,"t":"你不要惧怕他们，因为我与你同在，要拯救你。这是耶和华说的。","notes":[]},{"n":9,"t":"于是耶和华伸手按我的口，对我说：我已将当说的话传给你。","notes":[]},{"n":10,"t":"看哪，我今日立你在列邦列国之上，为要施行拔出、拆毁、毁坏、倾覆，又要建立、栽植。","notes":[]},{"n":11,"t":"耶和华的话又临到我说：「耶利米，你看见什么？」我说：「我看见一根杏树枝。」","notes":[],"heads":["两个异象"]},{"n":12,"t":"耶和华对我说：「你看得不错；因为我留意保守我的话，使得成就。」","notes":[]},{"n":13,"t":"耶和华的话第二次临到我说：「你看见什么？」我说：「我看见一个烧开的锅，从北而倾。」","notes":[]},{"n":14,"t":"耶和华对我说：「必有灾祸从北方发出，临到这地的一切居民。」","notes":[]},{"n":15,"t":"耶和华说：「看哪，我要召北方列国的众族；他们要来，各安座位在耶路撒冷的城门口，周围攻击城墙，又要攻击犹大的一切城邑。","notes":[]},{"n":16,"t":"至于这民的一切恶，就是离弃我、向别神烧香、跪拜自己手所造的，我要发出我的判语，攻击他们。","notes":[]},{"n":17,"t":"所以你当束腰，起来将我所吩咐你的一切话告诉他们；不要因他们惊惶，免得我使你在他们面前惊惶。","notes":[]},{"n":18,"t":"看哪，我今日使你成为坚城、铁柱、铜墙，与全地和犹大的君王、首领、祭司，并地上的众民反对。","notes":[]},{"n":19,"t":"他们要攻击你，却不能胜你；因为我与你同在，要拯救你。这是耶和华说的。」","notes":[]}]},"2":{"heading":"神眷顾以色列","verses":[{"n":1,"t":"耶和华的话临到我说：","notes":[]},{"n":2,"t":"「你去向耶路撒冷人的耳中喊叫说，耶和华如此说：你幼年的恩爱，婚姻的爱情，你怎样在旷野，在未曾耕种之地跟随我，我都记得。","notes":[]},{"n":3,"t":"那时以色列归耶和华为圣，作为土产初熟的果子；凡吞吃它的必算为有罪，灾祸必临到他们。这是耶和华说的。","notes":[]},{"n":4,"t":"雅各家、以色列家的各族啊，你们当听耶和华的话。","notes":[],"heads":["以色列祖先的罪恶"]},{"n":5,"t":"耶和华如此说：你们的列祖见我有什么不义，竟远离我，随从虚无的神，自己成为虚妄的呢？","notes":[]},{"n":6,"t":"他们也不说：那领我们从埃及地上来，引导我们经过旷野，沙漠有深坑之地，和干旱死荫、无人经过、无人居住之地的耶和华在哪里呢？","notes":[]},{"n":7,"t":"我领你们进入肥美之地，使你们得吃其中的果子和美物；但你们进入的时候就玷污我的地，使我的产业成为可憎的。","notes":[]},{"n":8,"t":"祭司都不说，耶和华在哪里呢？传讲律法的都不认识我。官长违背我；先知借巴力说预言，随从无益的神。","notes":[]},{"n":9,"t":"耶和华说：我因此必与你们争辩，也必与你们的子孙争辩。","notes":[],"heads":["神谴责他的子民"]},{"n":10,"t":"你们且过到基提海岛去察看，打发人往基达去留心查考，看曾有这样的事没有。","notes":[]},{"n":11,"t":"岂有一国换了他的神吗？其实这不是神！但我的百姓将他们的荣耀换了那无益的神。","notes":[]},{"n":12,"t":"诸天哪，要因此惊奇，极其恐慌，甚为凄凉！这是耶和华说的。","notes":[]},{"n":13,"t":"因为我的百姓做了两件恶事，就是离弃我这活水的泉源，为自己凿出池子，是破裂不能存水的池子。","notes":[]},{"n":14,"t":"以色列是仆人吗？是家中生的奴仆吗？为何成为掠物呢？","notes":[],"heads":["以色列不忠的结局"]},{"n":15,"t":"少壮狮子向他咆哮，大声吼叫，使他的地荒凉；城邑也都焚烧，无人居住。","notes":[]},{"n":16,"t":"挪弗人和答比匿人也打破你的头顶。","notes":[]},{"n":17,"t":"这事临到你身上，不是你自招的吗？不是因耶和华—你神引你行路的时候，你离弃他吗？","notes":[]},{"n":18,"t":"现今你为何在埃及路上要喝西曷的水呢？你为何在亚述路上要喝大河的水呢？","notes":[]},{"n":19,"t":"你自己的恶必惩治你；你背道的事必责备你。由此可知可见，你离弃耶和华—你的神，不存敬畏我的心，乃为恶事，为苦事。这是主—万军之耶和华说的。","notes":[]},{"n":20,"t":"我在古时折断你的轭，解开你的绳索。你说：我必不事奉耶和华；因为你在各高冈上、各青翠树下屈身行淫。","notes":["或译：我在古时折断你的轭，解开你的绳索，你就说：我必不事奉别神。谁知你在各高冈上、各青翠树下仍屈身行淫"],"heads":["以色列拒绝敬拜耶和华"]},{"n":21,"t":"然而，我栽你是上等的葡萄树，全然是真种子；你怎么向我变为外邦葡萄树的坏枝子呢？","notes":[]},{"n":22,"t":"你虽用硷、多用肥皂洗濯，你罪孽的痕迹仍然在我面前显出。这是主耶和华说的。","notes":[]},{"n":23,"t":"你怎能说：我没有玷污、没有随从众巴力？你看你谷中的路，就知道你所行的如何。你是快行的独峰驼，狂奔乱走。","notes":[]},{"n":24,"t":"你是野驴，惯在旷野，欲心发动就吸风；起性的时候谁能使它转去呢？凡寻找它的必不致疲乏；在它的月分必能寻见。","notes":[]},{"n":25,"t":"我说：你不要使脚上无鞋，喉咙干渴。你倒说：这是枉然。我喜爱别神，我必随从他们。","notes":[]},{"n":26,"t":"贼被捉拿，怎样羞愧，以色列家和他们的君王、首领、祭司、先知也都照样羞愧。","notes":[],"heads":["以色列该受惩罚"]},{"n":27,"t":"他们向木头说：你是我的父；向石头说：你是生我的。他们以背向我，不以面向我；及至遭遇患难的时候却说：起来拯救我们。","notes":[]},{"n":28,"t":"你为自己做的神在哪里呢？你遭遇患难的时候，叫他们起来拯救你吧！犹大啊，你神的数目与你城的数目相等。","notes":[]},{"n":29,"t":"耶和华说：你们为何与我争辩呢？你们都违背了我。","notes":[]},{"n":30,"t":"我责打你们的儿女是徒然的，他们不受惩治。你们自己的刀吞灭你们的先知，好像残害的狮子。","notes":[]},{"n":31,"t":"这世代的人哪，你们要看明耶和华的话。我岂向以色列作旷野呢？或作幽暗之地呢？我的百姓为何说：我们脱离约束，再不归向你了？","notes":[]},{"n":32,"t":"处女岂能忘记她的妆饰呢？新妇岂能忘记她的美衣呢？我的百姓却忘记了我无数的日子！","notes":[]},{"n":33,"t":"你怎么修饰你的道路要求爱情呢？就是恶劣的妇人你也叫她们行你的路。","notes":[]},{"n":34,"t":"并且你的衣襟上有无辜穷人的血；你杀他们并不是遇见他们挖窟窿，乃是因这一切的事。","notes":[]},{"n":35,"t":"你还说：我无辜；耶和华的怒气必定向我消了。看哪，我必审问你；因你自说：我没有犯罪。","notes":[]},{"n":36,"t":"你为何东跑西奔要更换你的路呢？你必因埃及蒙羞，像从前因亚述蒙羞一样。","notes":[]},{"n":37,"t":"你也必两手抱头从埃及出来；因为耶和华已经弃绝你所倚靠的，你必不因他们得顺利。","notes":[]}]},"3":{"heading":"不忠心的以色列","verses":[{"n":1,"t":"有话说：人若休妻，妻离他而去，作了别人的妻，前夫岂能再收回她来？若收回她来，那地岂不是大大玷污了吗？但你和许多亲爱的行邪淫，还可以归向我。这是耶和华说的。","notes":[]},{"n":2,"t":"你向净光的高处举目观看，你在何处没有淫行呢？你坐在道旁等候，好像阿拉伯人在旷野埋伏一样，并且你的淫行邪恶玷污了全地。","notes":[]},{"n":3,"t":"因此甘霖停止，春雨不降。你还是有娼妓之脸，不顾羞耻。","notes":["原文是晚"]},{"n":4,"t":"从今以后，你岂不向我呼叫说：我父啊，你是我幼年的恩主。","notes":[]},{"n":5,"t":"耶和华岂永远怀怒，存留到底吗？看哪，你又发恶言又行坏事，随自己的私意而行。」","notes":["或译：你虽这样说，还是行恶放纵欲心"]},{"n":6,"t":"约西亚王在位的时候，耶和华又对我说：「背道的以色列所行的，你看见没有？她上各高山，在各青翠树下行淫。","notes":[],"heads":["以色列和犹大应当悔改"]},{"n":7,"t":"她行这些事以后，我说她必归向我，她却不归向我。她奸诈的妹妹犹大也看见了。","notes":[]},{"n":8,"t":"背道的以色列行淫，我为这缘故给她休书休她；我看见她奸诈的妹妹犹大，还不惧怕，也去行淫。","notes":[]},{"n":9,"t":"因以色列轻忽了她的淫乱，和石头木头行淫，地就被玷污了。","notes":[]},{"n":10,"t":"虽有这一切的事，她奸诈的妹妹犹大还不一心归向我，不过是假意归我。这是耶和华说的。」","notes":[]},{"n":11,"t":"耶和华对我说：「背道的以色列比奸诈的犹大还显为义。","notes":[]},{"n":12,"t":"你去向北方宣告说：耶和华说：背道的以色列啊，回来吧！我必不怒目看你们；因为我是慈爱的，我必不永远存怒。这是耶和华说的。","notes":[]},{"n":13,"t":"只要承认你的罪孽，就是你违背耶和华—你的神，在各青翠树下向别神东奔西跑，没有听从我的话。这是耶和华说的。","notes":[]},{"n":14,"t":"耶和华说：背道的儿女啊，回来吧！因为我作你们的丈夫，并且我必将你们从一城取一人，从一族取两人，带到锡安。","notes":[]},{"n":15,"t":"我也必将合我心的牧者赐给你们。他们必以知识和智慧牧养你们。」","notes":[]},{"n":16,"t":"耶和华说：「你们在国中生养众多；当那些日子，人必不再提说耶和华的约柜，不追想，不记念，不觉缺少，也不再制造。","notes":[]},{"n":17,"t":"那时，人必称耶路撒冷为耶和华的宝座；万国必到耶路撒冷，在耶和华立名的地方聚集。他们必不再随从自己顽梗的恶心行事。","notes":[]},{"n":18,"t":"当那些日子，犹大家要和以色列家同行，从北方之地一同来到我赐给你们列祖为业之地。」","notes":[]},{"n":19,"t":"我说：我怎样将你安置在儿女之中，赐给你美地，就是万国中肥美的产业。我又说：你们必称我为父，也不再转去不跟从我。","notes":[],"heads":["神的子民拜偶像"]},{"n":20,"t":"以色列家，你们向我行诡诈，真像妻子行诡诈离开她丈夫一样。这是耶和华说的。","notes":[]},{"n":21,"t":"在净光的高处听见人声，就是以色列人哭泣恳求之声，乃因他们走弯曲之道，忘记耶和华—他们的神。","notes":[]},{"n":22,"t":"你们这背道的儿女啊，回来吧！我要医治你们背道的病。看哪，我们来到你这里，因你是耶和华—我们的神。","notes":[]},{"n":23,"t":"仰望从小山或从大山的喧嚷中得帮助，真是枉然的。以色列得救，诚然在乎耶和华—我们的神。","notes":[]},{"n":24,"t":"从我们幼年以来，那可耻的偶像将我们列祖所劳碌得来的羊群、牛群，和他们的儿女都吞吃了。","notes":[]},{"n":25,"t":"我们在羞耻中躺卧吧！愿惭愧将我们遮盖；因为从立国以来，我们和我们的列祖常常得罪耶和华—我们的神，没有听从耶和华—我们神的话。","notes":["原文是幼年"]}]},"4":{"heading":"呼召以色列悔改","verses":[{"n":1,"t":"耶和华说：以色列啊，你若回来归向我，若从我眼前除掉你可憎的偶像，你就不被迁移。","notes":[]},{"n":2,"t":"你必凭诚实、公平、公义，指着永生的耶和华起誓；列国必因耶和华称自己为有福，也必因他夸耀。","notes":[]},{"n":3,"t":"耶和华对犹大和耶路撒冷人如此说：要开垦你们的荒地，不要撒种在荆棘中。","notes":[]},{"n":4,"t":"犹大人和耶路撒冷的居民哪，你们当自行割礼，归耶和华，将心里的污秽除掉；恐怕我的忿怒因你们的恶行发作，如火着起，甚至无人能以熄灭！","notes":[]},{"n":5,"t":"你们当传扬在犹大，宣告在耶路撒冷说：你们当在国中吹角，高声呼叫说：你们当聚集！我们好进入坚固城！","notes":[],"heads":["外患威胁犹大"]},{"n":6,"t":"应当向锡安竖立大旗。要逃避，不要迟延，因我必使灾祸与大毁灭从北方来到。","notes":[]},{"n":7,"t":"有狮子从密林中上来，是毁坏列国的。它已经动身出离本处，要使你的地荒凉，使你的城邑变为荒场无人居住。","notes":[]},{"n":8,"t":"因此，你们当腰束麻布，大声哀号，因为耶和华的烈怒没有向我们转消。","notes":[]},{"n":9,"t":"耶和华说：「到那时，君王和首领的心都要消灭；祭司都要惊奇，先知都要诧异。」","notes":[]},{"n":10,"t":"我说：「哀哉！主耶和华啊，你真是大大地欺哄这百姓和耶路撒冷，说：『你们必得平安。』其实刀剑害及性命了。」","notes":[]},{"n":11,"t":"那时，必有话对这百姓和耶路撒冷说：「有一阵热风从旷野净光的高处向我的众民刮来，不是为簸扬，也不是为扬净。","notes":["原文是民女"]},{"n":12,"t":"必有一阵更大的风从这些地方为我刮来；现在我又必发出判语，攻击他们。」","notes":[]},{"n":13,"t":"看哪，仇敌必如云上来；他的战车如旋风，他的马匹比鹰更快。我们有祸了！我们败落了！","notes":[],"heads":["犹大被敌人围困"]},{"n":14,"t":"耶路撒冷啊，你当洗去心中的恶，使你可以得救。恶念存在你心里要到几时呢？","notes":[]},{"n":15,"t":"有声音从但传扬，从以法莲山报祸患。","notes":[]},{"n":16,"t":"你们当传给列国，报告攻击耶路撒冷的事说：有探望的人从远方来到，向犹大的城邑大声呐喊。","notes":[]},{"n":17,"t":"他们周围攻击耶路撒冷，好像看守田园的，因为她背叛了我。这是耶和华说的。","notes":[]},{"n":18,"t":"你的行动，你的作为，招惹这事；这是你罪恶的结果，实在是苦，是害及你心了！","notes":[]},{"n":19,"t":"我的肺腑啊，我的肺腑啊，我心疼痛！我心在我里面烦躁不安。我不能静默不言，因为我已经听见角声和打仗的喊声。","notes":[],"heads":["耶利米为同胞担忧"]},{"n":20,"t":"毁坏的信息连络不绝，因为全地荒废。我的帐棚忽然毁坏；我的幔子顷刻破裂。","notes":[]},{"n":21,"t":"我看见大旗，听见角声，要到几时呢？","notes":[]},{"n":22,"t":"耶和华说：我的百姓愚顽，不认识我；他们是愚昧无知的儿女，有智慧行恶，没有知识行善。","notes":[]},{"n":23,"t":"先知说：我观看地，不料，地是空虚混沌；我观看天，天也无光。","notes":[],"heads":["耶利米的异象—将要来临的毁灭"]},{"n":24,"t":"我观看大山，不料，尽都震动，小山也都摇来摇去。","notes":[]},{"n":25,"t":"我观看，不料，无人；空中的飞鸟也都躲避。","notes":[]},{"n":26,"t":"我观看，不料，肥田变为荒地；一切城邑在耶和华面前，因他的烈怒都被拆毁。","notes":[]},{"n":27,"t":"耶和华如此说：全地必然荒凉，我却不毁灭净尽。","notes":[]},{"n":28,"t":"因此，地要悲哀，在上的天也必黑暗；因为我言已出，我意已定，必不后悔，也不转意不做。","notes":[]},{"n":29,"t":"各城的人因马兵和弓箭手的响声就都逃跑，进入密林，爬上磐石；各城被撇下，无人住在其中。","notes":[]},{"n":30,"t":"你凄凉的时候要怎样行呢？你虽穿上朱红衣服，佩戴黄金装饰，用颜料修饰眼目，这样标致是枉然的！恋爱你的藐视你，并且寻索你的性命。","notes":[]},{"n":31,"t":"我听见有声音，仿佛妇人产难的声音，好像生头胎疼痛的声音，是锡安女子的声音；她喘着气、挓挲手，说：我有祸了！在杀人的跟前，我的心发昏了。","notes":["就是指民的意思"]}]},"5":{"heading":"耶路撒冷的罪","verses":[{"n":1,"t":"你们当在耶路撒冷的街上跑来跑去，在宽阔处寻找，看看有一人行公义求诚实没有？若有，我就赦免这城。","notes":[]},{"n":2,"t":"其中的人虽然指着永生的耶和华起誓，所起的誓实在是假的。","notes":[]},{"n":3,"t":"耶和华啊，你的眼目不是看顾诚实吗？你击打他们，他们却不伤恸；你毁灭他们，他们仍不受惩治。他们使脸刚硬过于磐石，不肯回头。","notes":[]},{"n":4,"t":"我说：这些人实在是贫穷的，是愚昧的，因为不晓得耶和华的作为和他们神的法则。","notes":[]},{"n":5,"t":"我要去见尊大的人，对他们说话，因为他们晓得耶和华的作为和他们神的法则。哪知，这些人齐心将轭折断，挣开绳索。","notes":[]},{"n":6,"t":"因此，林中的狮子必害死他们；晚上的豺狼必灭绝他们；豹子要在城外窥伺他们。凡出城的必被撕碎；因为他们的罪过极多，背道的事也加增了。","notes":["或译：野地"]},{"n":7,"t":"我怎能赦免你呢？你的儿女离弃我，又指着那不是神的起誓。我使他们饱足，他们就行奸淫，成群地聚集在娼妓家里。","notes":[]},{"n":8,"t":"他们像喂饱的马到处乱跑，各向他邻舍的妻发嘶声。","notes":[]},{"n":9,"t":"耶和华说：我岂不因这些事讨罪呢？岂不报复这样的国民呢？","notes":[]},{"n":10,"t":"你们要上她葡萄园的墙施行毁坏，但不可毁坏净尽，只可除掉她的枝子，因为不属耶和华。","notes":[]},{"n":11,"t":"原来以色列家和犹大家大行诡诈攻击我。这是耶和华说的。","notes":[]},{"n":12,"t":"他们不认耶和华，说：这并不是他，灾祸必不临到我们；刀剑和饥荒，我们也看不见。","notes":[],"heads":["耶和华丢弃以色列"]},{"n":13,"t":"先知的话必成为风；道也不在他们里面。这灾必临到他们身上。","notes":[]},{"n":14,"t":"所以耶和华—万军之神如此说：因为百姓说这话，我必使我的话在你口中为火，使他们为柴；这火便将他们烧灭。","notes":[]},{"n":15,"t":"耶和华说：以色列家啊，我必使一国的民从远方来攻击你，是强盛的国，是从古而有的国。他们的言语你不晓得，他们的话你不明白。","notes":[]},{"n":16,"t":"他们的箭袋是敞开的坟墓；他们都是勇士。","notes":[]},{"n":17,"t":"他们必吃尽你的庄稼和你的粮食，是你儿女该吃的；必吃尽你的牛羊，吃尽你的葡萄和无花果；又必用刀毁坏你所倚靠的坚固城。","notes":[]},{"n":18,"t":"耶和华说：「就是到那时，我也不将你们毁灭净尽。","notes":[]},{"n":19,"t":"百姓若说：『耶和华—我们的神为什么向我们行这一切事呢？』你就对他们说：『你们怎样离弃耶和华，在你们的地上事奉外邦神，也必照样在不属你们的地上事奉外邦人。』」","notes":["原文是我"]},{"n":20,"t":"当传扬在雅各家，报告在犹大说：","notes":[],"heads":["神警告他的子民"]},{"n":21,"t":"愚昧无知的百姓啊，你们有眼不看，有耳不听，现在当听这话。","notes":[]},{"n":22,"t":"耶和华说：你们怎么不惧怕我呢？我以永远的定例，用沙为海的界限，水不得越过。因此，你们在我面前还不战兢吗？波浪虽然翻腾，却不能逾越；虽然匉訇，却不能过去。","notes":[]},{"n":23,"t":"但这百姓有背叛忤逆的心；他们叛我而去，","notes":[]},{"n":24,"t":"心内也不说：我们应当敬畏耶和华—我们的神；他按时赐雨，就是秋雨春雨，又为我们定收割的节令，永存不废。","notes":[]},{"n":25,"t":"你们的罪孽使这些事转离你们；你们的罪恶使你们不能得福。","notes":[]},{"n":26,"t":"因为在我民中有恶人。他们埋伏窥探，好像捕鸟的人；他们设立圈套陷害人。","notes":[]},{"n":27,"t":"笼内怎样满了雀鸟，他们的房中也照样充满诡诈；所以他们得成为大，而且富足。","notes":[]},{"n":28,"t":"他们肥胖光润，作恶过甚，不为人伸冤！就是不为孤儿伸冤，不使他亨通，也不为穷人辨屈。","notes":[]},{"n":29,"t":"耶和华说：我岂不因这些事讨罪呢？岂不报复这样的国民呢？","notes":[]},{"n":30,"t":"国中有可惊骇、可憎恶的事：","notes":[]},{"n":31,"t":"就是先知说假预言，祭司借他们把持权柄；我的百姓也喜爱这些事，到了结局你们怎样行呢？","notes":[]}]},"6":{"heading":"耶路撒冷受敌人围攻","verses":[{"n":1,"t":"便雅悯人哪，你们要逃出耶路撒冷，在提哥亚吹角，在伯·哈基琳立号旗；因为有灾祸与大毁灭从北方张望。","notes":[]},{"n":2,"t":"那秀美娇嫩的锡安女子，我必剪除。","notes":["就是指民的意思"]},{"n":3,"t":"牧人必引他们的羊群到她那里，在她周围支搭帐棚，各在自己所占之地使羊吃草。","notes":[]},{"n":4,"t":"你们要准备攻击她。起来吧，我们可以趁午时上去。哀哉！日已渐斜，晚影拖长了。","notes":[]},{"n":5,"t":"起来吧，我们夜间上去，毁坏她的宫殿。","notes":[]},{"n":6,"t":"因为万军之耶和华如此说：你们要砍伐树木，筑垒攻打耶路撒冷。这就是那该罚的城，其中尽是欺压。","notes":[]},{"n":7,"t":"井怎样涌出水来，这城也照样涌出恶来；在其间常听见有强暴毁灭的事，病患损伤也常在我面前。","notes":[]},{"n":8,"t":"耶路撒冷啊，你当受教，免得我心与你生疏，免得我使你荒凉，成为无人居住之地。","notes":[]},{"n":9,"t":"万军之耶和华曾如此说：敌人必掳尽以色列剩下的民，如同摘净葡萄一样。你要像摘葡萄的人摘了又摘，回手放在筐子里。","notes":[],"heads":["叛逆的以色列"]},{"n":10,"t":"现在我可以向谁说话作见证，使他们听呢？他们的耳朵未受割礼，不能听见。看哪，耶和华的话他们以为羞辱，不以为喜悦。","notes":[]},{"n":11,"t":"因此我被耶和华的忿怒充满，难以含忍。我要倾在街中的孩童和聚会的少年人身上，连夫带妻，并年老的与日子满足的都必被擒拿。","notes":[]},{"n":12,"t":"他们的房屋、田地，和妻子都必转归别人；我要伸手攻击这地的居民。这是耶和华说的。","notes":[]},{"n":13,"t":"因为他们从最小的到至大的都一味地贪婪，从先知到祭司都行事虚谎。","notes":[]},{"n":14,"t":"他们轻轻忽忽地医治我百姓的损伤，说：平安了！平安了！其实没有平安。","notes":[]},{"n":15,"t":"他们行可憎的事知道惭愧吗？不然，他们毫不惭愧，也不知羞耻。因此，他们必在仆倒的人中仆倒；我向他们讨罪的时候，他们必致跌倒。这是耶和华说的。","notes":[]},{"n":16,"t":"耶和华如此说：你们当站在路上察看，访问古道，哪是善道，便行在其间；这样，你们心里必得安息。他们却说：我们不行在其间。","notes":[],"heads":["以色列拒绝神的道路"]},{"n":17,"t":"我设立守望的人照管你们，说：要听角声。他们却说：我们不听。","notes":[]},{"n":18,"t":"列国啊，因此你们当听！会众啊，要知道他们必遭遇的事。","notes":[]},{"n":19,"t":"地啊，当听！我必使灾祸临到这百姓，就是他们意念所结的果子；因为他们不听从我的言语，至于我的训诲，他们也厌弃了。","notes":["或译：律法"]},{"n":20,"t":"从示巴出的乳香，从远方出的菖蒲奉来给我有何益呢？你们的燔祭不蒙悦纳；你们的平安祭，我也不喜悦。","notes":["或译：甘蔗"]},{"n":21,"t":"所以耶和华如此说：我要将绊脚石放在这百姓前面。父亲和儿子要一同跌在其上；邻舍与朋友也都灭亡。","notes":[]},{"n":22,"t":"耶和华如此说：看哪，有一种民从北方而来，并有一大国被激动，从地极来到。","notes":[],"heads":["北方来的侵略者"]},{"n":23,"t":"他们拿弓和枪，性情残忍，不施怜悯；他们的声音像海浪匉訇。锡安城啊，他们骑马都摆队伍，如上战场的人要攻击你。","notes":["原文是女子"]},{"n":24,"t":"我们听见他们的风声，手就发软；痛苦将我们抓住，疼痛仿佛产难的妇人。","notes":[]},{"n":25,"t":"你们不要往田野去，也不要行在路上，因四围有仇敌的刀剑和惊吓。","notes":[]},{"n":26,"t":"我民哪，应当腰束麻布，滚在灰中。你要悲伤，如丧独生子痛痛哭号，因为灭命的要忽然临到我们。","notes":["原文是民女"]},{"n":27,"t":"我使你在我民中为高台，为保障，使你知道试验他们的行动。","notes":["或译：试验人的"]},{"n":28,"t":"他们都是极悖逆的，往来谗谤人。他们是铜是铁，都行坏事。","notes":[]},{"n":29,"t":"风箱吹火，铅被烧毁；他们炼而又炼，终是徒然；因为恶劣的还未除掉。","notes":[]},{"n":30,"t":"人必称他们为被弃的银渣，因为耶和华已经弃掉他们。","notes":[]}]},"7":{"heading":"耶利米在圣殿讲道","verses":[{"n":1,"t":"耶和华的话临到耶利米说：","notes":[]},{"n":2,"t":"「你当站在耶和华殿的门口，在那里宣传这话说：你们进这些门敬拜耶和华的一切犹大人，当听耶和华的话。","notes":[]},{"n":3,"t":"万军之耶和华—以色列的神如此说：你们改正行动作为，我就使你们在这地方仍然居住。","notes":[]},{"n":4,"t":"你们不要倚靠虚谎的话，说：『这些是耶和华的殿，是耶和华的殿，是耶和华的殿！』","notes":[]},{"n":5,"t":"「你们若实在改正行动作为，在人和邻舍中间诚然施行公平，","notes":[]},{"n":6,"t":"不欺压寄居的和孤儿寡妇，在这地方不流无辜人的血，也不随从别神陷害自己，","notes":[]},{"n":7,"t":"我就使你们在这地方仍然居住，就是我古时所赐给你们列祖的地，直到永远。","notes":[]},{"n":8,"t":"「看哪，你们倚靠虚谎无益的话。","notes":[]},{"n":9,"t":"你们偷盗，杀害，奸淫，起假誓，向巴力烧香，并随从素不认识的别神，","notes":[]},{"n":10,"t":"且来到这称为我名下的殿，在我面前敬拜；又说：『我们可以自由了。』你们这样的举动是要行那些可憎的事吗？","notes":[]},{"n":11,"t":"这称为我名下的殿在你们眼中岂可看为贼窝吗？我都看见了。这是耶和华说的。","notes":[]},{"n":12,"t":"你们且往示罗去，就是我先前立为我名的居所，察看我因这百姓以色列的罪恶向那地所行的如何。」","notes":[]},{"n":13,"t":"耶和华说：「现在因你们行了这一切的事，我也从早起来警戒你们，你们却不听从；呼唤你们，你们却不答应。","notes":[]},{"n":14,"t":"所以我要向这称为我名下、你们所倚靠的殿，与我所赐给你们和你们列祖的地施行，照我从前向示罗所行的一样。","notes":[]},{"n":15,"t":"我必将你们从我眼前赶出，正如赶出你们的众弟兄，就是以法莲的一切后裔。」","notes":[]},{"n":16,"t":"「所以，你不要为这百姓祈祷；不要为他们呼求祷告；也不要向我为他们祈求，因我不听允你。","notes":[],"heads":["人民违背命令"]},{"n":17,"t":"他们在犹大城邑中和耶路撒冷街上所行的，你没有看见吗？","notes":[]},{"n":18,"t":"孩子捡柴，父亲烧火，妇女抟面做饼，献给天后，又向别神浇奠祭，惹我发怒。」","notes":[]},{"n":19,"t":"耶和华说：「他们岂是惹我发怒呢？不是自己惹祸，以致脸上惭愧吗？」","notes":[]},{"n":20,"t":"所以主耶和华如此说：「看哪，我必将我的怒气和忿怒倾在这地方的人和牲畜身上，并田野的树木和地里的出产上，必如火着起，不能熄灭。」","notes":[]},{"n":21,"t":"万军之耶和华—以色列的神如此说：「你们将燔祭加在平安祭上，吃肉吧！","notes":[]},{"n":22,"t":"因为我将你们列祖从埃及地领出来的那日，燔祭平安祭的事我并没有提说，也没有吩咐他们。","notes":[]},{"n":23,"t":"我只吩咐他们这一件说：『你们当听从我的话，我就作你们的神，你们也作我的子民。你们行我所吩咐的一切道，就可以得福。』","notes":[]},{"n":24,"t":"他们却不听从，不侧耳而听，竟随从自己的计谋和顽梗的恶心，向后不向前。","notes":[]},{"n":25,"t":"自从你们列祖出埃及地的那日，直到今日，我差遣我的仆人众先知到你们那里去，每日从早起来差遣他们。","notes":[]},{"n":26,"t":"你们却不听从，不侧耳而听，竟硬着颈项行恶，比你们列祖更甚。","notes":[]},{"n":27,"t":"「你要将这一切的话告诉他们，他们却不听从；呼唤他们，他们却不答应。","notes":[]},{"n":28,"t":"你要对他们说：这就是不听从耶和华—他们神的话、不受教训的国民；从他们的口中，诚实灭绝了。」","notes":[]},{"n":29,"t":"耶路撒冷啊，要剪发抛弃，在净光的高处举哀；因为耶和华丢掉离弃了惹他忿怒的世代。","notes":[],"heads":["在欣嫩子谷的罪行"]},{"n":30,"t":"耶和华说：「犹大人行我眼中看为恶的事，将可憎之物设立在称为我名下的殿中，污秽这殿。","notes":[]},{"n":31,"t":"他们在欣嫩子谷建筑陀斐特的邱坛，好在火中焚烧自己的儿女。这并不是我所吩咐的，也不是我心所起的意。」","notes":[]},{"n":32,"t":"耶和华说：「因此，日子将到，这地方不再称为陀斐特和欣嫩子谷，反倒称为杀戮谷。因为要在陀斐特葬埋尸首，甚至无处可葬；","notes":[]},{"n":33,"t":"并且这百姓的尸首必给空中的飞鸟和地上的野兽作食物，并无人哄赶。","notes":[]},{"n":34,"t":"那时，我必使犹大城邑中和耶路撒冷街上，欢喜和快乐的声音，新郎和新妇的声音，都止息了，因为地必成为荒场。」","notes":[]}]},"8":{"heading":"罪与罚","verses":[{"n":1,"t":"耶和华说：「到那时，人必将犹大王的骸骨和他首领的骸骨、祭司的骸骨、先知的骸骨，并耶路撒冷居民的骸骨，都从坟墓中取出来，","notes":[]},{"n":2,"t":"抛散在日头、月亮，和天上众星之下，就是他们从前所喜爱、所事奉、所随从、所求问、所敬拜的。这些骸骨不再收殓，不再葬埋，必在地面上成为粪土；","notes":[]},{"n":3,"t":"并且这恶族所剩下的民在我所赶他们到的各处，宁可拣死不拣生。这是万军之耶和华说的。」","notes":[]},{"n":4,"t":"你要对他们说，耶和华如此说：人跌倒，不再起来吗？人转去，不再转来吗？","notes":[]},{"n":5,"t":"这耶路撒冷的民，为何恒久背道呢？他们守定诡诈，不肯回头。","notes":[]},{"n":6,"t":"我留心听，听见他们说不正直的话。无人悔改恶行，说：我做的是什么呢？他们各人转奔己路，如马直闯战场。","notes":[]},{"n":7,"t":"空中的鹳鸟知道来去的定期；斑鸠燕子与白鹤也守候当来的时令；我的百姓却不知道耶和华的法则。","notes":[]},{"n":8,"t":"你们怎么说：我们有智慧，耶和华的律法在我们这里？看哪，文士的假笔舞弄虚假。","notes":[]},{"n":9,"t":"智慧人惭愧，惊惶，被擒拿；他们弃掉耶和华的话，心里还有什么智慧呢？","notes":[]},{"n":10,"t":"所以我必将他们的妻子给别人，将他们的田地给别人为业；因为他们从最小的到至大的都一味地贪婪，从先知到祭司都行事虚谎。","notes":[]},{"n":11,"t":"他们轻轻忽忽地医治我百姓的损伤，说：平安了！平安了！其实没有平安。","notes":[]},{"n":12,"t":"他们行可憎的事知道惭愧吗？不然，他们毫不惭愧，也不知羞耻。因此他们必在仆倒的人中仆倒；我向他们讨罪的时候，他们必致跌倒。这是耶和华说的。","notes":[]},{"n":13,"t":"耶和华说：我必使他们全然灭绝；葡萄树上必没有葡萄，无花果树上必没有果子，叶子也必枯干。我所赐给他们的，必离开他们过去。","notes":[]},{"n":14,"t":"我们为何静坐不动呢？我们当聚集，进入坚固城，在那里静默不言；因为耶和华—我们的神使我们静默不言，又将苦胆水给我们喝，都因我们得罪了耶和华。","notes":[]},{"n":15,"t":"我们指望平安，却得不着好处；指望痊愈的时候，不料，受了惊惶。","notes":[]},{"n":16,"t":"听见从但那里敌人的马喷鼻气，他的壮马发嘶声，全地就都震动；因为他们来吞灭这地和其上所有的，吞灭这城与其中的居民。","notes":[]},{"n":17,"t":"看哪，我必使毒蛇到你们中间，是不服法术的，必咬你们。这是耶和华说的。","notes":[]},{"n":18,"t":"我有忧愁，愿能自慰；我心在我里面发昏。","notes":[],"heads":["耶利米为同胞悲伤"]},{"n":19,"t":"听啊，是我百姓的哀声从极远之地而来，说：耶和华不在锡安吗？锡安的王不在其中吗？耶和华说：他们为什么以雕刻的偶像和外邦虚无的神惹我发怒呢？","notes":[]},{"n":20,"t":"麦秋已过，夏令已完，我们还未得救！","notes":[]},{"n":21,"t":"先知说：因我百姓的损伤，我也受了损伤。我哀痛，惊惶将我抓住。","notes":[]},{"n":22,"t":"在基列岂没有乳香呢？在那里岂没有医生呢？我百姓为何不得痊愈呢？","notes":[]}]},"9":{"heading":"耶路撒冷哀求援助","verses":[{"n":1,"t":"但愿我的头为水，我的眼为泪的泉源，我好为我百姓中被杀的人昼夜哭泣。","notes":["原文是民女；七节同"]},{"n":2,"t":"惟愿我在旷野有行路人住宿之处，使我可以离开我的民出去；因他们都是行奸淫的，是行诡诈的一党。","notes":[]},{"n":3,"t":"他们弯起舌头像弓一样，为要说谎话。他们在国中增长势力，不是为行诚实，乃是恶上加恶，并不认识我。这是耶和华说的。","notes":[]},{"n":4,"t":"你们各人当谨防邻舍，不可信靠弟兄；因为弟兄尽行欺骗，邻舍都往来谗谤人。","notes":[]},{"n":5,"t":"他们各人欺哄邻舍，不说真话；他们教舌头学习说谎，劳劳碌碌地作孽。","notes":[]},{"n":6,"t":"你的住处在诡诈的人中；他们因行诡诈，不肯认识我。这是耶和华说的。","notes":[]},{"n":7,"t":"所以万军之耶和华如此说：看哪，我要将他们熔化熬炼；不然，我因我百姓的罪该怎样行呢？","notes":[]},{"n":8,"t":"他们的舌头是毒箭，说话诡诈；人与邻舍口说和平话，心却谋害他。","notes":[]},{"n":9,"t":"耶和华说：我岂不因这些事讨他们的罪呢？岂不报复这样的国民呢？","notes":[]},{"n":10,"t":"我要为山岭哭泣悲哀，为旷野的草场扬声哀号；因为都已干焦，甚至无人经过。人也听不见牲畜鸣叫，空中的飞鸟和地上的野兽都已逃去。","notes":[]},{"n":11,"t":"我必使耶路撒冷变为乱堆，为野狗的住处，也必使犹大的城邑变为荒场，无人居住。","notes":[]},{"n":12,"t":"谁是智慧人，可以明白这事？耶和华的口向谁说过，使他可以传说？遍地为何灭亡，干焦好像旷野，甚至无人经过呢？","notes":[]},{"n":13,"t":"耶和华说：「因为这百姓离弃我在他们面前所设立的律法，没有遵行，也没有听从我的话；","notes":[]},{"n":14,"t":"只随从自己顽梗的心行事，照他们列祖所教训的随从众巴力。」","notes":[]},{"n":15,"t":"所以万军之耶和华—以色列的神如此说：「看哪，我必将茵陈给这百姓吃，又将苦胆水给他们喝。","notes":[]},{"n":16,"t":"我要把他们散在列邦中，就是他们和他们列祖素不认识的列邦。我也要使刀剑追杀他们，直到将他们灭尽。」","notes":[]},{"n":17,"t":"万军之耶和华如此说：你们应当思想，将善唱哀歌的妇女召来，又打发人召善哭的妇女来，","notes":[]},{"n":18,"t":"叫她们速速为我们举哀，使我们眼泪汪汪，使我们的眼皮涌出水来。","notes":[]},{"n":19,"t":"因为听见哀声出于锡安，说：我们怎样败落了！我们大大地惭愧！我们撇下地土；人也拆毁了我们的房屋。","notes":[]},{"n":20,"t":"妇女们哪，你们当听耶和华的话，领受他口中的言语；又当教导你们的儿女举哀，各人教导邻舍唱哀歌。","notes":[]},{"n":21,"t":"因为死亡上来，进了我们的窗户，入了我们的宫殿；要从外边剪除孩童，从街上剪除少年人。","notes":[]},{"n":22,"t":"你当说，耶和华如此说：人的尸首必倒在田野像粪土，又像收割的人遗落的一把禾稼，无人收取。","notes":[]},{"n":23,"t":"耶和华如此说：「智慧人不要因他的智慧夸口，勇士不要因他的勇力夸口，财主不要因他的财物夸口。","notes":[]},{"n":24,"t":"夸口的却因他有聪明，认识我是耶和华，又知道我喜悦在世上施行慈爱、公平，和公义，以此夸口。这是耶和华说的。」","notes":[]},{"n":25,"t":"耶和华说：「看哪，日子将到，我要刑罚一切受过割礼、心却未受割礼的，","notes":[]},{"n":26,"t":"就是埃及、犹大、以东、亚扪人、摩押人，和一切住在旷野剃周围头发的；因为列国人都没有受割礼，以色列人心中也没有受割礼。」","notes":[]}]},"10":{"heading":"拜偶像和真敬拜","verses":[{"n":1,"t":"以色列家啊，要听耶和华对你们所说的话。","notes":[]},{"n":2,"t":"耶和华如此说：你们不要效法列国的行为，也不要为天象惊惶，因列国为此事惊惶。","notes":[]},{"n":3,"t":"众民的风俗是虚空的；他们在树林中用斧子砍伐一棵树，匠人用手工造成偶像。","notes":[]},{"n":4,"t":"他们用金银妆饰它，用钉子和锤子钉稳，使它不动摇。","notes":[]},{"n":5,"t":"它好像棕树，是旋成的，不能说话，不能行走，必须有人抬着。你们不要怕它；它不能降祸，也无力降福。","notes":[]},{"n":6,"t":"耶和华啊，没有能比你的！你本为大，有大能大力的名。","notes":[]},{"n":7,"t":"万国的王啊，谁不敬畏你？敬畏你本是合宜的；因为在列国的智慧人中，虽有政权的尊荣，也不能比你。","notes":[]},{"n":8,"t":"他们尽都是畜类，是愚昧的。偶像的训诲算什么呢？偶像不过是木头。","notes":[]},{"n":9,"t":"有银子打成片，是从他施带来的，并有从乌法来的金子，都是匠人和银匠的手工，又有蓝色紫色料的衣服，都是巧匠的工作。","notes":[]},{"n":10,"t":"惟耶和华是真神，是活神，是永远的王。他一发怒，大地震动；他一恼恨，列国都担当不起。（","notes":[]},{"n":11,"t":"你们要对他们如此说：不是那创造天地的神，必从地上从天下被除灭！）","notes":[]},{"n":12,"t":"耶和华用能力创造大地，用智慧建立世界，用聪明铺张穹苍。","notes":[],"heads":["颂赞神的诗"]},{"n":13,"t":"他一发声，空中便有多水激动；他使云雾从地极上腾；他造电随雨而闪，从他府库中带出风来。","notes":[]},{"n":14,"t":"各人都成了畜类，毫无知识；各银匠都因他雕刻的偶像羞愧。他所铸的偶像本是虚假的，其中并无气息，","notes":[]},{"n":15,"t":"都是虚无的，是迷惑人的工作；到追讨的时候必被除灭。","notes":[]},{"n":16,"t":"雅各的分不像这些，因他是造作万有的主。以色列也是他产业的支派，万军之耶和华是他的名。","notes":[]},{"n":17,"t":"受围困的人哪，当收拾你的财物，从国中带出去。","notes":[],"heads":["预告被掳"]},{"n":18,"t":"因为耶和华如此说：这时候，我必将此地的居民，好像用机弦甩出去，又必加害在他们身上，使他们觉悟。","notes":[]},{"n":19,"t":"民说：祸哉！我受损伤；我的伤痕极其重大。我却说：这真是我的痛苦，必须忍受。","notes":[]},{"n":20,"t":"我的帐棚毁坏；我的绳索折断。我的儿女离我出去，没有了。无人再支搭我的帐棚，挂起我的幔子。","notes":[]},{"n":21,"t":"因为牧人都成为畜类，没有求问耶和华，所以不得顺利；他们的羊群也都分散。","notes":[]},{"n":22,"t":"有风声！看哪，敌人来了！有大扰乱从北方出来，要使犹大城邑变为荒凉，成为野狗的住处。","notes":[]},{"n":23,"t":"耶和华啊，我晓得人的道路不由自己，行路的人也不能定自己的脚步。","notes":[]},{"n":24,"t":"耶和华啊，求你从宽惩治我，不要在你的怒中惩治我，恐怕使我归于无有。","notes":[]},{"n":25,"t":"愿你将忿怒倾在不认识你的列国中，和不求告你名的各族上；因为他们吞了雅各，不但吞了，而且灭绝，把他的住处变为荒场。","notes":[]}]},"11":{"heading":"耶利米和约","verses":[{"n":1,"t":"耶和华的话临到耶利米说：","notes":[]},{"n":2,"t":"「当听这约的话，告诉犹大人和耶路撒冷的居民，","notes":[]},{"n":3,"t":"对他们说，耶和华—以色列的神如此说：不听从这约之话的人必受咒诅。","notes":[]},{"n":4,"t":"这约是我将你们列祖从埃及地领出来、脱离铁炉的那日所吩咐他们的，说：『你们要听从我的话，照我一切所吩咐的去行。』这样，你们就作我的子民，我也作你们的神；","notes":[]},{"n":5,"t":"我好坚定向你们列祖所起的誓，给他们流奶与蜜之地，正如今日一样。」我就回答说：「耶和华啊，阿们！」","notes":[]},{"n":6,"t":"耶和华对我说：「你要在犹大城邑中和耶路撒冷街市上，宣告这一切话说：你们当听从遵行这约的话。","notes":[]},{"n":7,"t":"因为我将你们列祖从埃及地领出来的那日，直到今日，都是从早起来，切切告诫他们说：『你们当听从我的话。』","notes":[]},{"n":8,"t":"他们却不听从，不侧耳而听，竟随从自己顽梗的恶心去行。所以我使这约中一切咒诅的话临到他们身上；这约是我吩咐他们行的，他们却不去行。」","notes":[]},{"n":9,"t":"耶和华对我说：「在犹大人和耶路撒冷居民中有同谋背叛的事。","notes":[]},{"n":10,"t":"他们转去效法他们的先祖，不肯听我的话，犯罪作孽，又随从别神，事奉它。以色列家和犹大家背了我与他们列祖所立的约。」","notes":[]},{"n":11,"t":"所以耶和华如此说：「我必使灾祸临到他们，是他们不能逃脱的。他们必向我哀求，我却不听。","notes":[]},{"n":12,"t":"那时，犹大城邑的人和耶路撒冷的居民要去哀求他们烧香所供奉的神；只是遭难的时候，这些神毫不拯救他们。","notes":[]},{"n":13,"t":"犹大啊，你神的数目与你城的数目相等；你为那可耻的巴力所筑烧香的坛也与耶路撒冷街道的数目相等。","notes":[]},{"n":14,"t":"「所以你不要为这百姓祈祷，不要为他们呼求祷告；因为他们遭难向我哀求的时候，我必不应允。","notes":[]},{"n":15,"t":"我所亲爱的，既行许多淫乱，圣肉也离了你，你在我殿中做什么呢？你作恶就喜乐。","notes":[]},{"n":16,"t":"从前耶和华给你起名叫青橄榄树，又华美又结好果子；如今他用哄嚷之声，点火在其上，枝子也被折断。","notes":[]},{"n":17,"t":"原来栽培你的万军之耶和华已经说，要降祸攻击你，是因以色列家和犹大家行恶，向巴力烧香，惹我发怒，是自作自受。」","notes":[]},{"n":18,"t":"耶和华指示我，我就知道；你将他们所行的给我指明。","notes":[],"heads":["杀害耶利米的阴谋"]},{"n":19,"t":"我却像柔顺的羊羔被牵到宰杀之地；我并不知道他们设计谋害我，说：我们把树连果子都灭了吧！将他从活人之地剪除，使他的名不再被纪念。","notes":[]},{"n":20,"t":"按公义判断、察验人肺腑心肠的万军之耶和华啊，我却要见你在他们身上报仇，因我将我的案件向你禀明了。","notes":[]},{"n":21,"t":"所以，耶和华论到寻索你命的亚拿突人如此说：「他们说：你不要奉耶和华的名说预言，免得你死在我们手中。","notes":[]},{"n":22,"t":"所以万军之耶和华如此说：看哪，我必刑罚他们；他们的少年人必被刀剑杀死，他们的儿女必因饥荒灭亡，","notes":[]},{"n":23,"t":"并且没有余剩的人留给他们；因为在追讨之年，我必使灾祸临到亚拿突人。」","notes":[]}]},"12":{"heading":"耶利米询问耶和华","verses":[{"n":1,"t":"耶和华啊，我与你争辩的时候，你显为义；但有一件，我还要与你理论：恶人的道路为何亨通呢？大行诡诈的为何得安逸呢？","notes":[]},{"n":2,"t":"你栽培了他们，他们也扎了根，长大，而且结果。他们的口是与你相近，心却与你远离。","notes":[]},{"n":3,"t":"耶和华啊，你晓得我，看见我，察验我向你是怎样的心。求你将他们拉出来，好像将宰的羊，叫他们等候杀戮的日子。","notes":[]},{"n":4,"t":"这地悲哀，通国的青草枯干，要到几时呢？因其上居民的恶行，牲畜和飞鸟都灭绝了。他们曾说：他看不见我们的结局。","notes":[]},{"n":5,"t":"耶和华说：你若与步行的人同跑，尚且觉累，怎能与马赛跑呢？你在平安之地，虽然安稳，在约旦河边的丛林要怎样行呢？","notes":[]},{"n":6,"t":"因为连你弟兄和你父家都用奸诈待你。他们也在你后边大声喊叫，虽向你说好话，你也不要信他们。","notes":[]},{"n":7,"t":"我离了我的殿宇，撇弃我的产业，将我心里所亲爱的交在她仇敌的手中。","notes":[],"heads":["耶和华为他的子民忧伤"]},{"n":8,"t":"我的产业向我如林中的狮子，她发声攻击我，因此我恨恶她。","notes":[]},{"n":9,"t":"我的产业向我岂如斑点的鸷鸟呢？鸷鸟岂在她四围攻击她呢？你们要去聚集田野的百兽，带来吞吃吧！","notes":[]},{"n":10,"t":"许多牧人毁坏我的葡萄园，践踏我的分，使我美好的分变为荒凉的旷野。","notes":[]},{"n":11,"t":"他们使地荒凉；地既荒凉，便向我悲哀。全地荒凉，因无人介意。","notes":[]},{"n":12,"t":"灭命的都来到旷野中一切净光的高处；耶和华的刀从地这边直到地那边尽行杀灭。凡有血气的都不得平安。","notes":[]},{"n":13,"t":"他们种的是麦子，收的是荆棘；劳劳苦苦却毫无益处。因耶和华的烈怒，你们必为自己的土产羞愧。","notes":[]},{"n":14,"t":"耶和华如此说：「一切恶邻，就是占据我使百姓以色列所承受产业的，我要将他们拔出本地，又要将犹大家从他们中间拔出来。","notes":[],"heads":["耶和华对以色列邻国的许诺"]},{"n":15,"t":"我拔出他们以后，我必转过来怜悯他们，把他们再带回来，各归本业，各归故土。","notes":[]},{"n":16,"t":"他们若殷勤学习我百姓的道，指着我的名起誓说：『我指着永生的耶和华起誓』，正如他们从前教我百姓指着巴力起誓，他们就必建立在我百姓中间。","notes":[]},{"n":17,"t":"他们若是不听，我必拔出那国，拔出而且毁灭。这是耶和华说的。」","notes":[]}]},"13":{"heading":"腰带的比喻","verses":[{"n":1,"t":"耶和华对我如此说：「你去买一根麻布带子束腰，不可放在水中。」","notes":[]},{"n":2,"t":"我就照着耶和华的话，买了一根带子束腰。","notes":[]},{"n":3,"t":"耶和华的话第二次临到我说：","notes":[]},{"n":4,"t":"「要拿着你所买的腰带，就是你腰上的带子，起来往幼发拉底河去，将腰带藏在那里的磐石穴中。」","notes":[]},{"n":5,"t":"我就去，照着耶和华所吩咐我的，将腰带藏在幼发拉底河边。","notes":[]},{"n":6,"t":"过了多日，耶和华对我说：「你起来往幼发拉底河去，将我吩咐你藏在那里的腰带取出来。」","notes":[]},{"n":7,"t":"我就往幼发拉底河去，将腰带从我所藏的地方刨出来，见腰带已经变坏，毫无用了。","notes":[]},{"n":8,"t":"耶和华的话临到我说：","notes":[]},{"n":9,"t":"「耶和华如此说：我必照样败坏犹大的骄傲和耶路撒冷的大骄傲。","notes":[]},{"n":10,"t":"这恶民不肯听我的话，按自己顽梗的心而行，随从别神，事奉敬拜，他们也必像这腰带变为无用。」","notes":[]},{"n":11,"t":"耶和华说：「腰带怎样紧贴人腰，照样，我也使以色列全家和犹大全家紧贴我，好叫他们属我为子民，使我得名声，得颂赞，得荣耀；他们却不肯听。」","notes":[]},{"n":12,"t":"「所以你要对他们说：『耶和华—以色列的神如此说：各坛都要盛满了酒。』他们必对你说：『我们岂不确知各坛都要盛满了酒呢？』","notes":[],"heads":["酒坛的比喻"]},{"n":13,"t":"你就要对他们说：『耶和华如此说：我必使这地的一切居民，就是坐大卫宝座的君王和祭司，与先知，并耶路撒冷的一切居民，都酩酊大醉。』」","notes":[]},{"n":14,"t":"耶和华说：「我要使他们彼此相碰，就是父与子彼此相碰；我必不可怜，不顾惜，不怜悯，以致灭绝他们。」","notes":[]},{"n":15,"t":"你们当听，当侧耳而听。不要骄傲，因为耶和华已经说了。","notes":[],"heads":["耶利米警告狂傲的行为"]},{"n":16,"t":"耶和华—你们的神未使黑暗来到，你们的脚未在昏暗山上绊跌之先，当将荣耀归给他；免得你们盼望光明，他使光明变为死荫，成为幽暗。","notes":[]},{"n":17,"t":"你们若不听这话，我必因你们的骄傲在暗地哭泣；我眼必痛哭流泪，因为耶和华的群众被掳去了。","notes":[]},{"n":18,"t":"你要对君王和太后说：你们当自卑，坐在下边；因你们的头巾，就是你们的华冠，已经脱落了。","notes":[]},{"n":19,"t":"南方的城尽都关闭，无人开放；犹大全被掳掠，且掳掠净尽。","notes":[]},{"n":20,"t":"你们要举目观看从北方来的人。先前赐给你的群众，就是你佳美的群众，如今在哪里呢？","notes":[]},{"n":21,"t":"耶和华立你自己所交的朋友为首，辖制你，那时你还有什么话说呢？痛苦岂不将你抓住像产难的妇人吗？","notes":[]},{"n":22,"t":"你若心里说：这一切事为何临到我呢？你的衣襟揭起，你的脚跟受伤，是因你的罪孽甚多。","notes":[]},{"n":23,"t":"古实人岂能改变皮肤呢？豹岂能改变斑点呢？若能，你们这习惯行恶的便能行善了。","notes":[]},{"n":24,"t":"所以我必用旷野的风吹散他们，像吹过的碎秸一样。","notes":[]},{"n":25,"t":"耶和华说：这是你所当得的，是我量给你的分；因为你忘记我，倚靠虚假。","notes":["或译：偶像"]},{"n":26,"t":"所以我要揭起你的衣襟，蒙在你脸上，显出你的丑陋。","notes":[]},{"n":27,"t":"你那些可憎恶之事—就是在田野的山上行奸淫，发嘶声，做淫乱的事—我都看见了。耶路撒冷啊，你有祸了！你不肯洁净，还要到几时呢？","notes":[]}]},"14":{"heading":"可怕的旱灾","verses":[{"n":1,"t":"耶和华论到干旱之灾的话临到耶利米：","notes":[]},{"n":2,"t":"犹大悲哀，城门衰败。众人披上黑衣坐在地上；耶路撒冷的哀声上达。","notes":[]},{"n":3,"t":"他们的贵胄打发家僮打水；他们来到水池，见没有水，就拿着空器皿，蒙羞惭愧，抱头而回。","notes":[]},{"n":4,"t":"耕地的也蒙羞抱头；因为无雨降在地上，地都干裂。","notes":[]},{"n":5,"t":"田野的母鹿生下小鹿，就撇弃，因为无草。","notes":[]},{"n":6,"t":"野驴站在净光的高处，喘气好像野狗；因为无草，眼目失明。","notes":[]},{"n":7,"t":"耶和华啊，我们的罪孽虽然作见证告我们，还求你为你名的缘故行事。我们本是多次背道，得罪了你。","notes":[]},{"n":8,"t":"以色列所盼望、在患难时作他救主的啊，你为何在这地像寄居的，又像行路的只住一宵呢？","notes":[]},{"n":9,"t":"你为何像受惊的人，像不能救人的勇士呢？耶和华啊，你仍在我们中间；我们也称为你名下的人，求你不要离开我们。","notes":[]},{"n":10,"t":"耶和华对这百姓如此说：这百姓喜爱妄行，不禁止脚步，所以耶和华不悦纳他们。现今要记念他们的罪孽，追讨他们的罪恶。","notes":["原文是飘流"]},{"n":11,"t":"耶和华又对我说：「不要为这百姓祈祷求好处。","notes":[]},{"n":12,"t":"他们禁食的时候，我不听他们的呼求；他们献燔祭和素祭，我也不悦纳；我却要用刀剑、饥荒、瘟疫灭绝他们。」","notes":[]},{"n":13,"t":"我就说：「唉！主耶和华啊，那些先知常对他们说：『你们必不看见刀剑，也不遭遇饥荒；耶和华要在这地方赐你们长久的平安。』」","notes":[]},{"n":14,"t":"耶和华对我说：「那些先知托我的名说假预言，我并没有打发他们，没有吩咐他们，也没有对他们说话；他们向你们预言的，乃是虚假的异象和占卜，并虚无的事，以及本心的诡诈。","notes":[]},{"n":15,"t":"所以耶和华如此说：论到托我名说预言的那些先知，我并没有打发他们；他们还说这地不能有刀剑饥荒，其实那些先知必被刀剑饥荒灭绝。","notes":[]},{"n":16,"t":"听他们说预言的百姓必因饥荒刀剑抛在耶路撒冷的街道上，无人葬埋。他们连妻子带儿女，都是如此。我必将他们的恶倒在他们身上。」","notes":["或译：我必使他们罪恶的报应临到他们身上"]},{"n":17,"t":"你要将这话对他们说：愿我眼泪汪汪，昼夜不息，因为我百姓受了裂口破坏的大伤。","notes":["原文是民的处女"]},{"n":18,"t":"我若出往田间，就见有被刀杀的；我若进入城内，就见有因饥荒患病的；连先知带祭司在国中往来，也是毫无知识。","notes":["或译：不知怎样才好"]},{"n":19,"t":"你全然弃掉犹大吗？你心厌恶锡安吗？为何击打我们，以致无法医治呢？我们指望平安，却得不着好处；指望痊愈，不料，受了惊惶。","notes":[],"heads":["百姓恳求耶和华怜悯"]},{"n":20,"t":"耶和华啊，我们承认自己的罪恶，和我们列祖的罪孽，因我们得罪了你。","notes":[]},{"n":21,"t":"求你为你名的缘故，不厌恶我们，不辱没你荣耀的宝座。求你追念，不要背了与我们所立的约。","notes":[]},{"n":22,"t":"外邦人虚无的神中有能降雨的吗？天能自降甘霖吗？耶和华—我们的神啊，能如此的不是你吗？所以，我们仍要等候你，因为这一切都是你所造的。","notes":[]}]},"15":{"heading":"犹大百姓的厄运","verses":[{"n":1,"t":"耶和华对我说：「虽有摩西和撒母耳站在我面前代求，我的心也不顾惜这百姓。你将他们从我眼前赶出，叫他们去吧！","notes":[]},{"n":2,"t":"他们问你说：『我们往哪里去呢？』你便告诉他们，耶和华如此说：定为死亡的，必致死亡；定为刀杀的，必交刀杀；定为饥荒的，必遭饥荒；定为掳掠的，必被掳掠。」","notes":[]},{"n":3,"t":"耶和华说：「我命定四样害他们，就是刀剑杀戮、狗类撕裂、空中的飞鸟，和地上的野兽吞吃毁灭；","notes":[]},{"n":4,"t":"又必使他们在天下万国中抛来抛去，都因犹大王希西家的儿子玛拿西在耶路撒冷所行的事。」","notes":[]},{"n":5,"t":"耶路撒冷啊，谁可怜你呢？谁为你悲伤呢？谁转身问你的安呢？","notes":[]},{"n":6,"t":"耶和华说：你弃绝了我，转身退后；因此我伸手攻击你，毁坏你。我后悔甚不耐烦。","notes":[]},{"n":7,"t":"我在境内各城门口，用簸箕簸了我的百姓，使他们丧掉儿女。我毁灭他们，他们仍不转离所行的道。","notes":["或译：我在这地边界的关口"]},{"n":8,"t":"他们的寡妇在我面前比海沙更多；我使灭命的午间来，攻击少年人的母亲，使痛苦惊吓忽然临到她身上。","notes":[]},{"n":9,"t":"生过七子的妇人力衰气绝；尚在白昼，日头忽落；她抱愧蒙羞。其余的人，我必在他们敌人跟前，交与刀剑。这是耶和华说的。","notes":[]},{"n":10,"t":"我的母亲哪，我有祸了！因你生我作为遍地相争相竞的人。我素来没有借贷与人，人也没有借贷与我，人人却都咒骂我。","notes":[],"heads":["耶利米向耶和华诉苦"]},{"n":11,"t":"耶和华说：「我必要坚固你，使你得好处。灾祸苦难临到的时候，我必要使仇敌央求你。（","notes":[]},{"n":12,"t":"人岂能将铜与铁，就是北方的铁折断呢？）","notes":[]},{"n":13,"t":"「我必因你在四境之内所犯的一切罪，把你的货物财宝当掠物，白白地交给仇敌。","notes":[]},{"n":14,"t":"我也必使仇敌带这掠物到你所不认识的地去，因我怒中起的火要将你们焚烧。」","notes":[]},{"n":15,"t":"耶和华啊，你是知道的；求你记念我，眷顾我，向逼迫我的人为我报仇；不要向他们忍怒取我的命，要知道我为你的缘故受了凌辱。","notes":[]},{"n":16,"t":"耶和华—万军之神啊，我得着你的言语就当食物吃了；你的言语是我心中的欢喜快乐，因我是称为你名下的人。","notes":[]},{"n":17,"t":"我没有坐在宴乐人的会中，也没有欢乐；我因你的感动独自静坐，因你使我满心愤恨。","notes":["原文是手"]},{"n":18,"t":"我的痛苦为何长久不止呢？我的伤痕为何无法医治、不能痊愈呢？难道你待我有诡诈，像流干的河道吗？","notes":[]},{"n":19,"t":"耶和华如此说：你若归回，我就将你再带来，使你站在我面前；你若将宝贵的和下贱的分别出来，你就可以当作我的口。他们必归向你，你却不可归向他们。","notes":[]},{"n":20,"t":"我必使你向这百姓成为坚固的铜墙；他们必攻击你，却不能胜你；因我与你同在，要拯救你，搭救你。这是耶和华说的。","notes":[]},{"n":21,"t":"我必搭救你脱离恶人的手，救赎你脱离强暴人的手。","notes":[]}]},"16":{"heading":"耶和华要耶利米过孤独的生活","verses":[{"n":1,"t":"耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「你在这地方不可娶妻，生儿养女。","notes":[]},{"n":3,"t":"因为论到在这地方所生的儿女，又论到在这国中生养他们的父母，耶和华如此说：","notes":[]},{"n":4,"t":"他们必死得甚苦，无人哀哭，必不得葬埋，必在地上像粪土，必被刀剑和饥荒灭绝；他们的尸首必给空中的飞鸟和地上的野兽作食物。」","notes":[]},{"n":5,"t":"耶和华如此说：「不要进入丧家，不要去哀哭，也不要为他们悲伤，因我已将我的平安、慈爱、怜悯从这百姓夺去了。这是耶和华说的。","notes":[]},{"n":6,"t":"连大带小，都必在这地死亡，不得葬埋。人必不为他们哀哭，不用刀划身，也不使头光秃。","notes":[]},{"n":7,"t":"他们有丧事，人必不为他们擘饼，因死人安慰他们；他们丧父丧母，人也不给他们一杯酒安慰他们。","notes":[]},{"n":8,"t":"你不可进入宴乐的家，与他们同坐吃喝。","notes":[]},{"n":9,"t":"因为万军之耶和华—以色列的神如此说：你们还活着的日子在你们眼前，我必使欢喜和快乐的声音，新郎和新妇的声音，从这地方止息了。","notes":[]},{"n":10,"t":"「你将这一切的话指示这百姓。他们问你说：『耶和华为什么说，要降这大灾祸攻击我们呢？我们有什么罪孽呢？我们向耶和华—我们的神犯了什么罪呢？』","notes":[]},{"n":11,"t":"你就对他们说：『耶和华说：因为你们列祖离弃我，随从别神，事奉敬拜，不遵守我的律法，","notes":[]},{"n":12,"t":"而且你们行恶比你们列祖更甚；因为各人随从自己顽梗的恶心行事，甚至不听从我，","notes":[]},{"n":13,"t":"所以我必将你们从这地赶出，直赶到你们和你们列祖素不认识的地。你们在那里必昼夜事奉别神，因为我必不向你们施恩。』」","notes":[]},{"n":14,"t":"耶和华说：「日子将到，人必不再指着那领以色列人从埃及地上来之永生的耶和华起誓，","notes":[],"heads":["从流亡中回国"]},{"n":15,"t":"却要指着那领以色列人从北方之地，并赶他们到的各国上来之永生的耶和华起誓，并且我要领他们再入我从前赐给他们列祖之地。」","notes":[]},{"n":16,"t":"耶和华说：「我要召许多打鱼的把以色列人打上来，然后我要召许多打猎的，从各山上、各冈上、各石穴中猎取他们。","notes":[],"heads":["将要临到的惩罚"]},{"n":17,"t":"因我的眼目察看他们的一切行为；他们不能在我面前遮掩，他们的罪孽也不能在我眼前隐藏。","notes":[]},{"n":18,"t":"我先要加倍报应他们的罪孽和罪恶；因为他们用可憎之尸玷污我的地土，又用可厌之物充满我的产业。」","notes":[]},{"n":19,"t":"耶和华啊，你是我的力量，是我的保障；在苦难之日是我的避难所。列国人必从地极来到你这里，说：我们列祖所承受的，不过是虚假，是虚空无益之物。","notes":[],"heads":["耶利米的信心祈祷"]},{"n":20,"t":"人岂可为自己制造神呢？其实这不是神。","notes":[]},{"n":21,"t":"耶和华说：「我要使他们知道，就是这一次使他们知道我的手和我的能力。他们就知道我的名是耶和华了。」","notes":[]}]},"17":{"heading":"犹大的罪和惩罚","verses":[{"n":1,"t":"犹大的罪是用铁笔、用金钢钻记录的，铭刻在他们的心版上和坛角上。","notes":[]},{"n":2,"t":"他们的儿女记念他们高冈上、青翠树旁的坛和木偶。","notes":[]},{"n":3,"t":"我田野的山哪，我必因你在四境之内所犯的罪，把你的货物、财宝，并邱坛当掠物交给仇敌；","notes":[]},{"n":4,"t":"并且你因自己的罪必失去我所赐给你的产业。我也必使你在你所不认识的地上服事你的仇敌；因为你使我怒中起火，直烧到永远。","notes":[]},{"n":5,"t":"耶和华如此说：倚靠人血肉的膀臂，心中离弃耶和华的，那人有祸了！","notes":[],"heads":["训诲集"]},{"n":6,"t":"因他必像沙漠的杜松，不见福乐来到，却要住旷野干旱之处，无人居住的硷地。","notes":[]},{"n":7,"t":"倚靠耶和华、以耶和华为可靠的，那人有福了！","notes":[]},{"n":8,"t":"他必像树栽于水旁，在河边扎根，炎热来到，并不惧怕，叶子仍必青翠，在干旱之年毫无挂虑，而且结果不止。","notes":[]},{"n":9,"t":"人心比万物都诡诈，坏到极处，谁能识透呢？","notes":[]},{"n":10,"t":"我—耶和华是鉴察人心、试验人肺腑的，要照各人所行的和他做事的结果报应他。","notes":[]},{"n":11,"t":"那不按正道得财的，好像鹧鸪抱不是自己下的蛋；到了中年，那财都必离开他，他终久成为愚顽人。","notes":[]},{"n":12,"t":"我们的圣所是荣耀的宝座，从太初安置在高处。","notes":[]},{"n":13,"t":"耶和华—以色列的盼望啊，凡离弃你的必致蒙羞。耶和华说：离开我的，他们的名字必写在土里，因为他们离弃我这活水的泉源。","notes":[]},{"n":14,"t":"耶和华啊，求你医治我，我便痊愈，拯救我，我便得救；因你是我所赞美的。","notes":[],"heads":["耶利米求耶和华帮助"]},{"n":15,"t":"他们对我说：耶和华的话在哪里呢？叫这话应验吧！","notes":[]},{"n":16,"t":"至于我，那跟从你作牧人的职分，我并没有急忙离弃，也没有想那灾殃的日子；这是你知道的。我口中所出的言语都在你面前。","notes":[]},{"n":17,"t":"不要使我因你惊恐；当灾祸的日子，你是我的避难所。","notes":[]},{"n":18,"t":"愿那些逼迫我的蒙羞，却不要使我蒙羞；使他们惊惶，却不要使我惊惶；使灾祸的日子临到他们，以加倍的毁坏毁坏他们。","notes":[]},{"n":19,"t":"耶和华对我如此说：「你去站在平民的门口，就是犹大君王出入的门，又站在耶路撒冷的各门口，","notes":[],"heads":["关于遵守安息日"]},{"n":20,"t":"对他们说：『你们这犹大君王和犹大众人，并耶路撒冷的一切居民，凡从这些门进入的都当听耶和华的话。","notes":[]},{"n":21,"t":"耶和华如此说：你们要谨慎，不要在安息日担什么担子进入耶路撒冷的各门；","notes":[]},{"n":22,"t":"也不要在安息日从家中担出担子去。无论何工都不可做，只要以安息日为圣日，正如我所吩咐你们列祖的。』","notes":[]},{"n":23,"t":"他们却不听从，不侧耳而听，竟硬着颈项不听，不受教训。」","notes":[]},{"n":24,"t":"耶和华说：「你们若留意听从我，在安息日不担什么担子进入这城的各门，只以安息日为圣日，在那日无论何工都不做；","notes":[]},{"n":25,"t":"那时就有坐大卫宝座的君王和首领，他们与犹大人，并耶路撒冷的居民，或坐车，或骑马，进入这城的各门，而且这城必存到永远。","notes":[]},{"n":26,"t":"也必有人从犹大城邑和耶路撒冷四围的各处，从便雅悯地、高原、山地，并南地而来，都带燔祭、平安祭、素祭，和乳香，并感谢祭，到耶和华的殿去。","notes":[]},{"n":27,"t":"你们若不听从我，不以安息日为圣日，仍在安息日担担子，进入耶路撒冷的各门，我必在各门中点火；这火也必烧毁耶路撒冷的宫殿，不能熄灭。」","notes":[]}]},"18":{"heading":"耶利米在陶匠的家","verses":[{"n":1,"t":"耶和华的话临到耶利米说：","notes":[]},{"n":2,"t":"「你起来，下到窑匠的家里去，我在那里要使你听我的话。」","notes":[]},{"n":3,"t":"我就下到窑匠的家里去，正遇他转轮做器皿。","notes":[]},{"n":4,"t":"窑匠用泥做的器皿，在他手中做坏了，他又用这泥另做别的器皿；窑匠看怎样好，就怎样做。","notes":[]},{"n":5,"t":"耶和华的话就临到我说：","notes":[]},{"n":6,"t":"「耶和华说：以色列家啊，我待你们，岂不能照这窑匠弄泥吗？以色列家啊，泥在窑匠的手中怎样，你们在我的手中也怎样。","notes":[]},{"n":7,"t":"我何时论到一邦或一国说，要拔出、拆毁、毁坏；","notes":[]},{"n":8,"t":"我所说的那一邦，若是转意离开他们的恶，我就必后悔，不将我想要施行的灾祸降与他们。","notes":[]},{"n":9,"t":"我何时论到一邦或一国说，要建立、栽植；","notes":[]},{"n":10,"t":"他们若行我眼中看为恶的事，不听从我的话，我就必后悔，不将我所说的福气赐给他们。","notes":[]},{"n":11,"t":"现在你要对犹大人和耶路撒冷的居民说：『耶和华如此说：我造出灾祸攻击你们，定意刑罚你们。你们各人当回头离开所行的恶道，改正你们的行动作为。』","notes":[]},{"n":12,"t":"「他们却说：『这是枉然。我们要照自己的计谋去行。』各人随自己顽梗的恶心做事。」","notes":[]},{"n":13,"t":"所以，耶和华如此说：你们且往各国访问，有谁听见这样的事？以色列民行了一件极可憎恶的事。","notes":["原文是处女"],"heads":["百姓忘记耶和华"]},{"n":14,"t":"黎巴嫩的雪从田野的磐石上岂能断绝呢？从远处流下的凉水岂能干涸呢？","notes":[]},{"n":15,"t":"我的百姓竟忘记我，向假神烧香，使他们在所行的路上，在古道上绊跌，使他们行没有修筑的斜路，","notes":[]},{"n":16,"t":"以致他们的地令人惊骇，常常嗤笑；凡经过这地的必惊骇摇头。","notes":[]},{"n":17,"t":"我必在仇敌面前分散他们，好像用东风吹散一样。遭难的日子，我必以背向他们，不以面向他们。","notes":[]},{"n":18,"t":"他们就说：「来吧！我们可以设计谋害耶利米；因为我们有祭司讲律法，智慧人设谋略，先知说预言，都不能断绝。来吧！我们可以用舌头击打他，不要理会他的一切话。」","notes":[],"heads":["谋害耶利米"]},{"n":19,"t":"耶和华啊，求你理会我，且听那些与我争竞之人的话。","notes":[]},{"n":20,"t":"岂可以恶报善呢？他们竟挖坑要害我的性命！求你记念我怎样站在你面前为他们代求，要使你的忿怒向他们转消。","notes":[]},{"n":21,"t":"故此，愿你将他们的儿女交与饥荒和刀剑；愿他们的妻无子，且作寡妇；又愿他们的男人被死亡所灭，他们的少年人在阵上被刀击杀。","notes":[]},{"n":22,"t":"你使敌军忽然临到他们的时候，愿人听见哀声从他们的屋内发出；因他们挖坑要捉拿我，暗设网罗要绊我的脚。","notes":[]},{"n":23,"t":"耶和华啊，他们要杀我的那一切计谋，你都知道。不要赦免他们的罪孽，也不要从你面前涂抹他们的罪恶，要叫他们在你面前跌倒；愿你发怒的时候罚办他们。","notes":[]}]},"19":{"heading":"破碎的瓶","verses":[{"n":1,"t":"耶和华如此说：「你去买窑匠的瓦瓶，又带百姓中的长老和祭司中的长老，","notes":[]},{"n":2,"t":"出去到欣嫩子谷、哈珥西的门口那里，宣告我所吩咐你的话，","notes":["就是瓦片的意思"]},{"n":3,"t":"说：『犹大君王和耶路撒冷的居民哪，当听耶和华的话。万军之耶和华—以色列的神如此说：我必使灾祸临到这地方，凡听见的人都必耳鸣；","notes":[]},{"n":4,"t":"因为他们和他们列祖，并犹大君王离弃我，将这地方看为平常，在这里向素不认识的别神烧香，又使这地方满了无辜人的血，","notes":[]},{"n":5,"t":"又建筑巴力的邱坛，好在火中焚烧自己的儿子，作为燔祭献给巴力。这不是我所吩咐的，不是我所提说的，也不是我心所起的意。","notes":[]},{"n":6,"t":"耶和华说：因此，日子将到，这地方不再称为陀斐特和欣嫩子谷，反倒称为杀戮谷。","notes":[]},{"n":7,"t":"我必在这地方使犹大和耶路撒冷的计谋落空，也必使他们在仇敌面前倒于刀下，并寻索其命的人手下。他们的尸首，我必给空中的飞鸟和地上的野兽作食物。","notes":[]},{"n":8,"t":"我必使这城令人惊骇嗤笑；凡经过的人，必因这城所遭的灾惊骇嗤笑。","notes":[]},{"n":9,"t":"我必使他们在围困窘迫之中，就是仇敌和寻索其命的人窘迫他们的时候，各人吃自己儿女的肉和朋友的肉。』","notes":[]},{"n":10,"t":"「你要在同去的人眼前打碎那瓶，","notes":[]},{"n":11,"t":"对他们说：『万军之耶和华如此说：我要照样打碎这民和这城，正如人打碎窑匠的瓦器，以致不能再囫囵。并且人要在陀斐特葬埋尸首，甚至无处可葬。","notes":[]},{"n":12,"t":"耶和华说：我必向这地方和其中的居民如此行，使这城与陀斐特一样。","notes":[]},{"n":13,"t":"耶路撒冷的房屋和犹大君王的宫殿是已经被玷污的，就是他们在其上向天上的万象烧香、向别神浇奠祭的宫殿房屋，都必与陀斐特一样。』」","notes":[]},{"n":14,"t":"耶利米从陀斐特—就是耶和华差他去说预言的地方—回来，站在耶和华殿的院中，对众人说：","notes":[]},{"n":15,"t":"「万军之耶和华—以色列的神如此说：我必使我所说的一切灾祸临到这城和属城的一切城邑，因为他们硬着颈项不听我的话。」","notes":[]}]},"20":{"heading":"耶利米跟祭司巴施户珥冲突","verses":[{"n":1,"t":"祭司音麦的儿子巴施户珥作耶和华殿的总管，听见耶利米预言这些事，","notes":[]},{"n":2,"t":"他就打先知耶利米，用耶和华殿里便雅悯高门内的枷，将他枷在那里。","notes":[]},{"n":3,"t":"次日，巴施户珥将耶利米开枷释放。于是耶利米对他说：「耶和华不是叫你的名为巴施户珥，乃是叫你玛歌珥·米撒毕，","notes":["就是四面惊吓的意思"]},{"n":4,"t":"因耶和华如此说：『我必使你自觉惊吓，你也必使众朋友惊吓；他们必倒在仇敌的刀下，你也必亲眼看见；我必将犹大人全交在巴比伦王的手中，他要将他们掳到巴比伦去，也要用刀将他们杀戮。","notes":[]},{"n":5,"t":"并且我要将这城中的一切货财和劳碌得来的，并一切珍宝，以及犹大君王所有的宝物，都交在他们仇敌的手中；仇敌要当作掠物带到巴比伦去。","notes":[]},{"n":6,"t":"你这巴施户珥和一切住在你家中的人都必被掳去；你和你的众朋友，就是你向他们说假预言的，都必到巴比伦去，要死在那里，葬在那里。』」","notes":[]},{"n":7,"t":"耶和华啊，你曾劝导我，我也听了你的劝导。你比我有力量，且胜了我。我终日成为笑话，人人都戏弄我。","notes":[],"heads":["耶利米埋怨耶和华"]},{"n":8,"t":"我每逢讲论的时候，就发出哀声，我喊叫说：有强暴和毁灭！因为耶和华的话终日成了我的凌辱、讥刺。","notes":[]},{"n":9,"t":"我若说：我不再提耶和华，也不再奉他的名讲论，我便心里觉得似乎有烧着的火闭塞在我骨中，我就含忍不住，不能自禁。","notes":[]},{"n":10,"t":"我听见了许多人的谗谤，四围都是惊吓；就是我知己的朋友也都窥探我，愿我跌倒，说：告他吧，我们也要告他！或者他被引诱，我们就能胜他，在他身上报仇。","notes":[]},{"n":11,"t":"然而，耶和华与我同在，好像甚可怕的勇士。因此，逼迫我的必都绊跌，不能得胜；他们必大大蒙羞，就是受永不忘记的羞辱，因为他们行事没有智慧。","notes":[]},{"n":12,"t":"试验义人、察看人肺腑心肠的万军之耶和华啊，求你容我见你在他们身上报仇，因我将我的案件向你禀明了。","notes":[]},{"n":13,"t":"你们要向耶和华唱歌；赞美耶和华！因他救了穷人的性命脱离恶人的手。","notes":[]},{"n":14,"t":"愿我生的那日受咒诅；愿我母亲产我的那日不蒙福！","notes":[]},{"n":15,"t":"给我父亲报信说「你得了儿子」，使我父亲甚欢喜的，愿那人受咒诅。","notes":[]},{"n":16,"t":"愿那人像耶和华所倾覆而不后悔的城邑；愿他早晨听见哀声，晌午听见呐喊；","notes":[]},{"n":17,"t":"因他在我未出胎的时候不杀我，使我母亲成了我的坟墓，胎就时常重大。","notes":[]},{"n":18,"t":"我为何出胎见劳碌愁苦，使我的年日因羞愧消灭呢？","notes":[]}]},"21":{"heading":"预言耶路撒冷灭亡","verses":[{"n":1,"t":"耶和华的话临到耶利米。那时，西底家王打发玛基雅的儿子巴施户珥和玛西雅的儿子祭司西番雅去见耶利米，说：","notes":[]},{"n":2,"t":"「请你为我们求问耶和华；因为巴比伦王尼布甲尼撒来攻击我们，或者耶和华照他一切奇妙的作为待我们，使巴比伦王离开我们上去。」","notes":[]},{"n":3,"t":"耶利米对他们说：「你们当对西底家这样说：","notes":[]},{"n":4,"t":"『耶和华—以色列的神如此说：我要使你们手中的兵器，就是你们在城外与巴比伦王和围困你们的迦勒底人打仗的兵器翻转过来，又要使这些都聚集在这城中。","notes":[]},{"n":5,"t":"并且我要在怒气、忿怒，和大恼恨中，用伸出来的手，并大能的膀臂，亲自攻击你们；","notes":[]},{"n":6,"t":"又要击打这城的居民，连人带牲畜都必遭遇大瘟疫死亡。","notes":[]},{"n":7,"t":"以后我要将犹大王西底家和他的臣仆百姓，就是在城内，从瘟疫、刀剑、饥荒中剩下的人，都交在巴比伦王尼布甲尼撒的手中和他们仇敌，并寻索其命的人手中。巴比伦王必用刀击杀他们，不顾惜，不可怜，不怜悯。这是耶和华说的。』","notes":[]},{"n":8,"t":"「你要对这百姓说：『耶和华如此说：看哪，我将生命的路和死亡的路摆在你们面前。","notes":[]},{"n":9,"t":"住在这城里的必遭刀剑、饥荒、瘟疫而死；但出去归降围困你们迦勒底人的必得存活，要以自己的命为掠物。","notes":[]},{"n":10,"t":"耶和华说：我向这城变脸，降祸不降福；这城必交在巴比伦王的手中，他必用火焚烧。』」","notes":[]},{"n":11,"t":"「至于犹大王的家，你们当听耶和华的话。","notes":[],"heads":["审判犹大王室"]},{"n":12,"t":"大卫家啊，耶和华如此说：你们每早晨要施行公平，拯救被抢夺的脱离欺压人的手，恐怕我的忿怒因你们的恶行发作，如火着起，甚至无人能以熄灭。","notes":[]},{"n":13,"t":"耶和华说：住山谷和平原磐石上的居民，你们说：谁能下来攻击我们？谁能进入我们的住处呢？看哪，我与你们为敌。","notes":[]},{"n":14,"t":"耶和华又说：我必按你们做事的结果刑罚你们；我也必使火在耶路撒冷的林中着起，将她四围所有的尽行烧灭。」","notes":[]}]},"22":{"heading":"耶利米给犹大王的警告","verses":[{"n":1,"t":"耶和华如此说：「你下到犹大王的宫中，在那里说这话，","notes":[]},{"n":2,"t":"说：『坐大卫宝座的犹大王啊，你和你的臣仆，并进入城门的百姓，都当听耶和华的话。","notes":[]},{"n":3,"t":"耶和华如此说：你们要施行公平和公义，拯救被抢夺的脱离欺压人的手，不可亏负寄居的和孤儿寡妇，不可以强暴待他们，在这地方也不可流无辜人的血。","notes":[]},{"n":4,"t":"你们若认真行这事，就必有坐大卫宝座的君王和他的臣仆百姓，或坐车或骑马，从这城的各门进入。","notes":[]},{"n":5,"t":"你们若不听这些话，耶和华说：我指着自己起誓，这城必变为荒场。』","notes":[]},{"n":6,"t":"耶和华论到犹大王的家如此说：我看你如基列，如黎巴嫩顶；然而，我必使你变为旷野，为无人居住的城邑。","notes":[]},{"n":7,"t":"我要预备行毁灭的人，各拿器械攻击你；他们要砍下你佳美的香柏树，扔在火中。","notes":[]},{"n":8,"t":"「许多国的民要经过这城，各人对邻舍说：『耶和华为何向这大城如此行呢？』","notes":[]},{"n":9,"t":"他们必回答说：『是因离弃了耶和华—他们神的约，事奉敬拜别神。』」","notes":[]},{"n":10,"t":"不要为死人哭号；不要为他悲伤，却要为离家出外的人大大哭号；因为他不得再回来，也不得再见他的本国。","notes":[],"heads":["关于约哈斯"]},{"n":11,"t":"因为耶和华论到从这地方出去的犹大王约西亚的儿子沙龙，就是接续他父亲约西亚作王的，这样说：「他必不得再回到这里来，","notes":["在列王下二十三章三十节名约哈斯"]},{"n":12,"t":"却要死在被掳去的地方，必不得再见这地。」","notes":[]},{"n":13,"t":"那行不义盖房、行不公造楼、白白使用人的手工不给工价的有祸了！","notes":[],"heads":["关于约雅敬"]},{"n":14,"t":"他说：我要为自己盖广大的房、宽敞的楼，为自己开窗户。这楼房的护墙板是香柏木的，楼房是丹色油漆的。","notes":[]},{"n":15,"t":"难道你作王是在乎造香柏木楼房争胜吗？你的父亲岂不是也吃也喝、也施行公平和公义吗？那时他得了福乐。","notes":[]},{"n":16,"t":"他为困苦和穷乏人伸冤，那时就得了福乐。认识我不在乎此吗？这是耶和华说的。","notes":[]},{"n":17,"t":"惟有你的眼和你的心专顾贪婪，流无辜人的血，行欺压和强暴。","notes":[]},{"n":18,"t":"所以，耶和华论到犹大王约西亚的儿子约雅敬如此说：人必不为他举哀说：哀哉！我的哥哥；或说：哀哉！我的姐姐；也不为他举哀说：哀哉！我的主；或说：哀哉！我主的荣华。","notes":[]},{"n":19,"t":"他被埋葬，好像埋驴一样，要拉出去扔在耶路撒冷的城门之外。","notes":[]},{"n":20,"t":"你要上黎巴嫩哀号，在巴珊扬声，从亚巴琳哀号，因为你所亲爱的都毁灭了。","notes":[],"heads":["关于耶路撒冷百姓的命运"]},{"n":21,"t":"你兴盛的时候，我对你说话；你却说：我不听。你自幼年以来总是这样，不听从我的话。","notes":[]},{"n":22,"t":"你的牧人要被风吞吃，你所亲爱的必被掳去；那时你必因你一切的恶抱愧蒙羞。","notes":[]},{"n":23,"t":"你这住黎巴嫩、在香柏树上搭窝的，有痛苦临到你，好像疼痛临到产难的妇人，那时你何等可怜！","notes":[]},{"n":24,"t":"耶和华说：「犹大王约雅敬的儿子哥尼雅，虽是我右手上带印的戒指，我凭我的永生起誓，也必将你从其上摘下来，","notes":["又名耶哥尼雅；下同"],"heads":["神审判哥尼雅"]},{"n":25,"t":"并且我必将你交给寻索你命的人和你所惧怕的人手中，就是巴比伦王尼布甲尼撒和迦勒底人的手中。","notes":[]},{"n":26,"t":"我也必将你和生你的母亲赶到别国，并不是你们生的地方；你们必死在那里，","notes":[]},{"n":27,"t":"但心中甚想归回之地，必不得归回。」","notes":[]},{"n":28,"t":"哥尼雅这人是被轻看、破坏的器皿吗？是无人喜爱的器皿吗？他和他的后裔为何被赶到不认识之地呢？","notes":[]},{"n":29,"t":"地啊，地啊，地啊，当听耶和华的话！","notes":[]},{"n":30,"t":"耶和华如此说：要写明这人算为无子，是平生不得亨通的；因为他后裔中再无一人得亨通，能坐在大卫的宝座上治理犹大。","notes":[]}]},"23":{"heading":"对将来的希望","verses":[{"n":1,"t":"耶和华说：「那些残害、赶散我草场之羊的牧人有祸了！」","notes":[]},{"n":2,"t":"耶和华—以色列的神斥责那些牧养他百姓的牧人，如此说：「你们赶散我的羊群，并没有看顾他们；我必讨你们这行恶的罪。这是耶和华说的。","notes":[]},{"n":3,"t":"我要将我羊群中所余剩的，从我赶他们到的各国内招聚出来，领他们归回本圈；他们也必生养众多。","notes":[]},{"n":4,"t":"我必设立照管他们的牧人，牧养他们。他们不再惧怕，不再惊惶，也不缺少一个；这是耶和华说的。」","notes":[]},{"n":5,"t":"耶和华说：「日子将到，我要给大卫兴起一个公义的苗裔；他必掌王权，行事有智慧，在地上施行公平和公义。","notes":[]},{"n":6,"t":"在他的日子，犹大必得救，以色列也安然居住。他的名必称为『耶和华—我们的义』。」","notes":[]},{"n":7,"t":"耶和华说：「日子将到，人必不再指着那领以色列人从埃及地上来永生的耶和华起誓，","notes":[]},{"n":8,"t":"却要指着那领以色列家的后裔从北方和赶他们到的各国中上来、永生的耶和华起誓。他们必住在本地。」","notes":[]},{"n":9,"t":"论到那些先知，我心在我里面忧伤，我骨头都发颤；因耶和华和他的圣言，我像醉酒的人，像被酒所胜的人。","notes":[],"heads":["对先知们的警告"]},{"n":10,"t":"地满了行淫的人！因妄自赌咒，地就悲哀；旷野的草场都枯干了。他们所行的道乃是恶的；他们的勇力使得不正。","notes":[]},{"n":11,"t":"连先知带祭司都是亵渎的，就是在我殿中我也看见他们的恶。这是耶和华说的。","notes":[]},{"n":12,"t":"因此，他们的道路必像黑暗中的滑地，他们必被追赶，在这路中仆倒；因为当追讨之年，我必使灾祸临到他们。这是耶和华说的。","notes":[]},{"n":13,"t":"我在撒马利亚的先知中曾见愚妄；他们借巴力说预言，使我的百姓以色列走错了路。","notes":[]},{"n":14,"t":"我在耶路撒冷的先知中曾见可憎恶的事；他们行奸淫，做事虚妄，又坚固恶人的手，甚至无人回头离开他的恶。他们在我面前都像所多玛；耶路撒冷的居民都像蛾摩拉。","notes":[]},{"n":15,"t":"所以万军之耶和华论到先知如此说：我必将茵陈给他们吃，又将苦胆水给他们喝；因为亵渎的事出于耶路撒冷的先知，流行遍地。","notes":[]},{"n":16,"t":"万军之耶和华如此说：「这些先知向你们说预言，你们不要听他们的话。他们以虚空教训你们，所说的异象是出于自己的心，不是出于耶和华的口。","notes":[]},{"n":17,"t":"他们常对藐视我的人说：『耶和华说：你们必享平安』；又对一切按自己顽梗之心而行的人说：『必没有灾祸临到你们。』」","notes":[]},{"n":18,"t":"有谁站在耶和华的会中得以听见并会悟他的话呢？有谁留心听他的话呢？","notes":[]},{"n":19,"t":"看哪！耶和华的忿怒好像暴风，已经发出；是暴烈的旋风，必转到恶人的头上。","notes":[]},{"n":20,"t":"耶和华的怒气必不转消，直到他心中所拟定的成就了。末后的日子你们要全然明白。","notes":[]},{"n":21,"t":"我没有打发那些先知，他们竟自奔跑；我没有对他们说话，他们竟自预言。","notes":[]},{"n":22,"t":"他们若是站在我的会中，就必使我的百姓听我的话，又使他们回头离开恶道和他们所行的恶。","notes":[]},{"n":23,"t":"耶和华说：「我岂为近处的神呢？不也为远处的神吗？」","notes":[]},{"n":24,"t":"耶和华说：「人岂能在隐密处藏身，使我看不见他呢？」耶和华说：「我岂不充满天地吗？","notes":[]},{"n":25,"t":"我已听见那些先知所说的，就是托我名说的假预言，他们说：『我做了梦！我做了梦！』","notes":[]},{"n":26,"t":"说假预言的先知，就是预言本心诡诈的先知，他们这样存心要到几时呢？","notes":[]},{"n":27,"t":"他们各人将所做的梦对邻舍述说，想要使我的百姓忘记我的名，正如他们列祖因巴力忘记我的名一样。","notes":[]},{"n":28,"t":"得梦的先知可以述说那梦；得我话的人可以诚实讲说我的话。糠秕怎能与麦子比较呢？这是耶和华说的。」","notes":[]},{"n":29,"t":"耶和华说：「我的话岂不像火，又像能打碎磐石的大锤吗？」","notes":[]},{"n":30,"t":"耶和华说：「那些先知各从邻舍偷窃我的言语，因此我必与他们反对。」","notes":[]},{"n":31,"t":"耶和华说：「那些先知用舌头，说是耶和华说的；我必与他们反对。」","notes":[]},{"n":32,"t":"耶和华说：「那些以幻梦为预言，又述说这梦，以谎言和矜夸使我百姓走错了路的，我必与他们反对。我没有打发他们，也没有吩咐他们。他们与这百姓毫无益处。这是耶和华说的。」","notes":[]},{"n":33,"t":"「无论是百姓，是先知，是祭司，问你说：『耶和华有什么默示呢？』你就对他们说：『什么默示啊？耶和华说：我要撇弃你们。』","notes":[],"heads":["耶和华的重担"]},{"n":34,"t":"无论是先知，是祭司，是百姓，说『耶和华的默示』，我必刑罚那人和他的家。","notes":[]},{"n":35,"t":"你们各人要对邻舍，各人要对弟兄如此说：『耶和华回答什么？』『耶和华说了什么呢？』","notes":[]},{"n":36,"t":"『耶和华的默示』你们不可再提，各人所说的话必作自己的重担，因为你们谬用永生神、万军之耶和华—我们神的言语。","notes":["重担和默示原文同"]},{"n":37,"t":"你们要对先知如此说：『耶和华回答你什么？』『耶和华说了什么呢？』","notes":[]},{"n":38,"t":"你们若说『耶和华的默示』，耶和华就如此说：『因你们说「耶和华的默示」这句话，我也打发人到你们那里去，告诉你们不可说「耶和华的默示」。』","notes":[]},{"n":39,"t":"所以我必全然忘记你们，将你们和我所赐给你们并你们列祖的城撇弃了；","notes":[]},{"n":40,"t":"又必使永远的凌辱和长久的羞耻临到你们，是不能忘记的。」","notes":[]}]},"24":{"heading":"两筐无花果","verses":[{"n":1,"t":"巴比伦王尼布甲尼撒将犹大王约雅敬的儿子耶哥尼雅和犹大的首领，并工匠、铁匠从耶路撒冷掳去，带到巴比伦。这事以后，耶和华指给我看，有两筐无花果放在耶和华的殿前。","notes":[]},{"n":2,"t":"一筐是极好的无花果，好像是初熟的；一筐是极坏的无花果，坏得不可吃。","notes":[]},{"n":3,"t":"于是耶和华问我说：「耶利米你看见什么？」我说：「我看见无花果，好的极好，坏的极坏，坏得不可吃。」","notes":[]},{"n":4,"t":"耶和华的话临到我说：","notes":[]},{"n":5,"t":"「耶和华—以色列的神如此说：被掳去的犹大人，就是我打发离开这地到迦勒底人之地去的，我必看顾他们如这好无花果，使他们得好处。","notes":[]},{"n":6,"t":"我要眷顾他们，使他们得好处，领他们归回这地。我也要建立他们，必不拆毁；栽植他们，并不拔出。","notes":[]},{"n":7,"t":"我要赐他们认识我的心，知道我是耶和华。他们要作我的子民，我要作他们的神，因为他们要一心归向我。」","notes":[]},{"n":8,"t":"耶和华如此说：「我必将犹大王西底家和他的首领，以及剩在这地耶路撒冷的余民，并住在埃及地的犹大人都交出来，好像那极坏、坏得不可吃的无花果。","notes":[]},{"n":9,"t":"我必使他们交出来，在天下万国中抛来抛去，遭遇灾祸；在我赶逐他们到的各处成为凌辱、笑谈、讥刺、咒诅。","notes":[]},{"n":10,"t":"我必使刀剑、饥荒、瘟疫临到他们，直到他们从我所赐给他们和他们列祖之地灭绝。」","notes":[]}]},"25":{"heading":"从北方来的敌人","verses":[{"n":1,"t":"犹大王约西亚的儿子约雅敬第四年，就是巴比伦王尼布甲尼撒的元年，耶和华论犹大众民的话临到耶利米。","notes":[]},{"n":2,"t":"先知耶利米就将这话对犹大众人和耶路撒冷的一切居民说：","notes":[]},{"n":3,"t":"「从犹大王亚们的儿子约西亚十三年直到今日，这二十三年之内，常有耶和华的话临到我；我也对你们传说，就是从早起来传说，只是你们没有听从。","notes":[]},{"n":4,"t":"耶和华也从早起来，差遣他的仆人众先知到你们这里来（只是你们没有听从，也没有侧耳而听），","notes":[]},{"n":5,"t":"说：『你们各人当回头，离开恶道和所作的恶，便可居住耶和华古时所赐给你们和你们列祖之地，直到永远。","notes":[]},{"n":6,"t":"不可随从别神事奉敬拜，以你们手所做的惹我发怒；这样，我就不加害与你们。","notes":[]},{"n":7,"t":"然而你们没有听从我，竟以手所做的惹我发怒，陷害自己。这是耶和华说的。』」","notes":[]},{"n":8,"t":"所以万军之耶和华如此说：「因为你们没有听从我的话，","notes":[]},{"n":9,"t":"我必召北方的众族和我仆人巴比伦王尼布甲尼撒来攻击这地和这地的居民，并四围一切的国民。我要将他们尽行灭绝，以致他们令人惊骇、嗤笑，并且永久荒凉。这是耶和华说的。","notes":[]},{"n":10,"t":"我又要使欢喜和快乐的声音，新郎和新妇的声音，推磨的声音和灯的亮光，从他们中间止息。","notes":[]},{"n":11,"t":"这全地必然荒凉，令人惊骇。这些国民要服事巴比伦王七十年。","notes":[]},{"n":12,"t":"七十年满了以后，我必刑罚巴比伦王和那国民，并迦勒底人之地，因他们的罪孽使那地永远荒凉。这是耶和华说的。","notes":[]},{"n":13,"t":"我也必使我向那地所说的话，就是记在这书上的话，是耶利米向这些国民说的预言，都临到那地。","notes":[]},{"n":14,"t":"因为有多国和大君王必使迦勒底人作奴仆；我也必照他们的行为，按他们手所做的报应他们。」","notes":[]},{"n":15,"t":"耶和华—以色列的神对我如此说：「你从我手中接这杯忿怒的酒，使我所差遣你去的各国的民喝。","notes":[],"heads":["神审判列国"]},{"n":16,"t":"他们喝了就要东倒西歪，并要发狂，因我使刀剑临到他们中间。」","notes":[]},{"n":17,"t":"我就从耶和华的手中接了这杯，给耶和华所差遣我去的各国的民喝，","notes":[]},{"n":18,"t":"就是耶路撒冷和犹大的城邑，并耶路撒冷的君王与首领，使这城邑荒凉，令人惊骇、嗤笑、咒诅，正如今日一样。","notes":[]},{"n":19,"t":"又有埃及王法老和他的臣仆、首领，以及他的众民，","notes":[]},{"n":20,"t":"并杂族的人民和乌斯地的诸王，与非利士地的诸王（亚实基伦、迦萨、以革伦，以及亚实突剩下的人）；","notes":[]},{"n":21,"t":"以东、摩押、亚扪人、","notes":[]},{"n":22,"t":"泰尔的诸王、西顿的诸王、海岛的诸王、","notes":[]},{"n":23,"t":"底但、提玛、布斯，和一切剃周围头发的；","notes":[]},{"n":24,"t":"阿拉伯的诸王、住旷野杂族人民的诸王、","notes":[]},{"n":25,"t":"心利的诸王、以拦的诸王、米底亚的诸王、","notes":[]},{"n":26,"t":"北方远近的诸王，以及天下地上的万国喝了，以后示沙克王也要喝。","notes":["就是巴比伦"]},{"n":27,"t":"「你要对他们说：『万军之耶和华—以色列的神如此说：你们要喝，且要喝醉，要呕吐，且要跌倒，不得再起来，都因我使刀剑临到你们中间。』","notes":[]},{"n":28,"t":"「他们若不肯从你手接这杯喝，你就要对他们说：『万军之耶和华如此说：你们一定要喝！","notes":[]},{"n":29,"t":"我既从称为我名下的城起首施行灾祸，你们能尽免刑罚吗？你们必不能免，因为我要命刀剑临到地上一切的居民。这是万军之耶和华说的。』","notes":[]},{"n":30,"t":"「所以你要向他们预言这一切的话，攻击他们，说：耶和华必从高天吼叫，从圣所发声，向自己的羊群大声吼叫；他要向地上一切的居民呐喊，像踹葡萄的一样。","notes":[]},{"n":31,"t":"必有响声达到地极，因为耶和华与列国相争；凡有血气的，他必审问；至于恶人，他必交给刀剑。这是耶和华说的。","notes":[]},{"n":32,"t":"万军之耶和华如此说：看哪，必有灾祸从这国发到那国，并有大暴风从地极刮起。","notes":[]},{"n":33,"t":"「到那日，从地这边直到地那边都有耶和华所杀戮的。必无人哀哭，不得收殓，不得葬埋，必在地上成为粪土。","notes":[]},{"n":34,"t":"牧人哪，你们当哀号，呼喊；群众的头目啊，你们要滚在灰中；因为你们被杀戮分散的日子足足来到。你们要跌碎，好像美器打碎一样。","notes":[]},{"n":35,"t":"牧人无路逃跑；群众的头目也无法逃脱。","notes":[]},{"n":36,"t":"听啊，有牧人呼喊，有群众头目哀号的声音，因为耶和华使他们的草场变为荒场。","notes":[]},{"n":37,"t":"耶和华发出猛烈的怒气，平安的羊圈就都寂静无声。","notes":[]},{"n":38,"t":"他离了隐密处像狮子一样，他们的地，因刀剑凶猛的欺压，又因他猛烈的怒气都成为可惊骇的。」","notes":[]}]},"26":{"heading":"耶利米受审","verses":[{"n":1,"t":"犹大王约西亚的儿子约雅敬登基的时候，有这话从耶和华临到耶利米说：","notes":[]},{"n":2,"t":"「耶和华如此说：你站在耶和华殿的院内，对犹大众城邑的人，就是到耶和华殿来礼拜的，说我所吩咐你的一切话，一字不可删减。","notes":[]},{"n":3,"t":"或者他们肯听从，各人回头离开恶道，使我后悔不将我因他们所行的恶，想要施行的灾祸降与他们。","notes":[]},{"n":4,"t":"你要对他们说，耶和华如此说：『你们若不听从我，不遵行我设立在你们面前的律法，","notes":[]},{"n":5,"t":"不听我从早起来差遣到你们那里去我仆人众先知的话（你们还是没有听从），","notes":[]},{"n":6,"t":"我就必使这殿如示罗，使这城为地上万国所咒诅的。』」","notes":[]},{"n":7,"t":"耶利米在耶和华殿中说的这些话，祭司、先知与众民都听见了。","notes":[]},{"n":8,"t":"耶利米说完了耶和华所吩咐他对众人说的一切话，祭司、先知与众民都来抓住他，说：「你必要死！","notes":[]},{"n":9,"t":"你为何托耶和华的名预言，说这殿必如示罗，这城必变为荒场无人居住呢？」于是众民都在耶和华的殿中聚集到耶利米那里。","notes":[]},{"n":10,"t":"犹大的首领听见这事，就从王宫上到耶和华的殿，坐在耶和华殿的新门口。","notes":[]},{"n":11,"t":"祭司、先知对首领和众民说：「这人是该死的；因为他说预言攻击这城，正如你们亲耳所听见的。」","notes":[]},{"n":12,"t":"耶利米就对众首领和众民说：「耶和华差遣我预言，攻击这殿和这城，说你们所听见的这一切话。","notes":[]},{"n":13,"t":"现在要改正你们的行动作为，听从耶和华—你们神的话，他就必后悔，不将所说的灾祸降与你们。","notes":[]},{"n":14,"t":"至于我，我在你们手中，你们眼看何为善，何为正，就那样待我吧！","notes":[]},{"n":15,"t":"但你们要确实地知道，若把我治死，就使无辜人的血归到你们和这城，并其中的居民了；因为耶和华实在差遣我到你们这里来，将这一切话传与你们耳中。」","notes":[]},{"n":16,"t":"首领和众民就对祭司、先知说：「这人是不该死的，因为他是奉耶和华—我们神的名向我们说话。」","notes":[]},{"n":17,"t":"国中的长老就有几个人起来，对聚会的众民说：","notes":[]},{"n":18,"t":"「当犹大王希西家的日子，有摩利沙人弥迦对犹大众人预言说：万军之耶和华如此说：锡安必被耕种像一块田；耶路撒冷必变为乱堆；这殿的山必像丛林的高处。","notes":[]},{"n":19,"t":"犹大王希西家和犹大众人岂是把他治死呢？希西家岂不是敬畏耶和华、恳求他的恩吗？耶和华就后悔，不把自己所说的灾祸降与他们。若治死这人，我们就作了大恶，自害己命。」（","notes":[]},{"n":20,"t":"又有一个人奉耶和华的名说预言，是基列·耶琳人示玛雅的儿子乌利亚，他照耶利米的一切话说预言，攻击这城和这地。","notes":[]},{"n":21,"t":"约雅敬王和他众勇士、众首领听见了乌利亚的话，王就想要把他治死。乌利亚听见就惧怕，逃往埃及去了。","notes":[]},{"n":22,"t":"约雅敬王便打发亚革波的儿子以利拿单，带领几个人往埃及去。","notes":[]},{"n":23,"t":"他们就从埃及将乌利亚带出来，送到约雅敬王那里；王用刀杀了他，把他的尸首抛在平民的坟地中。）","notes":[]},{"n":24,"t":"然而，沙番的儿子亚希甘保护耶利米，不交在百姓的手中治死他。","notes":[]}]},"27":{"heading":"耶利米负轭","verses":[{"n":1,"t":"犹大王约西亚的儿子约雅敬登基的时候，有这话从耶和华临到耶利米说：","notes":["约雅敬是西底家的别名，看第三节"]},{"n":2,"t":"「耶和华对我如此说：你做绳索与轭，加在自己的颈项上，","notes":[]},{"n":3,"t":"借那些来到耶路撒冷见犹大王西底家的使臣之手，把绳索与轭送到以东王、摩押王、亚扪王、泰尔王、西顿王那里，","notes":[]},{"n":4,"t":"且嘱咐使臣，传与他们的主人说，万军之耶和华—以色列的神如此说：","notes":[]},{"n":5,"t":"我用大能和伸出来的膀臂，创造大地和地上的人民、牲畜。我看给谁相宜，就把地给谁。","notes":[]},{"n":6,"t":"现在我将这些地都交给我仆人巴比伦王尼布甲尼撒的手，我也将田野的走兽给他使用。","notes":[]},{"n":7,"t":"列国都必服事他和他的儿孙，直到他本国遭报的日期来到。那时，多国和大君王要使他作他们的奴仆。","notes":[]},{"n":8,"t":"「无论哪一邦哪一国，不肯服事这巴比伦王尼布甲尼撒，也不把颈项放在巴比伦王的轭下，我必用刀剑、饥荒、瘟疫刑罚那邦，直到我借巴比伦王的手将他们毁灭。这是耶和华说的。","notes":[]},{"n":9,"t":"至于你们，不可听从你们的先知和占卜的、圆梦的、观兆的，以及行邪术的；他们告诉你们说：『你们不致服事巴比伦王。』","notes":[]},{"n":10,"t":"他们向你们说假预言，要叫你们迁移，远离本地，以致我将你们赶出去，使你们灭亡。","notes":[]},{"n":11,"t":"但哪一邦肯把颈项放在巴比伦王的轭下服事他，我必使那邦仍在本地存留，得以耕种居住。这是耶和华说的。」","notes":[]},{"n":12,"t":"我就照这一切的话对犹大王西底家说：「要把你们的颈项放在巴比伦王的轭下，服事他和他的百姓，便得存活。","notes":[]},{"n":13,"t":"你和你的百姓为何要因刀剑、饥荒、瘟疫死亡，正如耶和华论到不服事巴比伦王的那国说的话呢？","notes":[]},{"n":14,"t":"不可听那些先知对你们所说的话；他们说：『你们不致服事巴比伦王』，其实他们向你们说假预言。","notes":[]},{"n":15,"t":"耶和华说：『我并没有打发他们，他们却托我的名说假预言，好使我将你们和向你们说预言的那些先知赶出去，一同灭亡。』」","notes":[]},{"n":16,"t":"我又对祭司和这众民说：「耶和华如此说：你们不可听那先知对你们所说的预言。他们说：『耶和华殿中的器皿快要从巴比伦带回来』；其实他们向你们说假预言。","notes":[]},{"n":17,"t":"不可听从他们，只管服事巴比伦王便得存活。这城何致变为荒场呢？","notes":[]},{"n":18,"t":"他们若果是先知，有耶和华的话临到他们，让他们祈求万军之耶和华，使那在耶和华殿中和犹大王宫内，并耶路撒冷剩下的器皿，不被带到巴比伦去。（","notes":[]},{"n":19,"t":"因为万军之耶和华论到柱子、铜海、盆座，并剩在这城里的器皿，","notes":[]},{"n":20,"t":"就是巴比伦王尼布甲尼撒掳掠犹大王约雅敬的儿子耶哥尼雅，和犹大、耶路撒冷一切贵胄的时候所没有掠去的器皿。）","notes":[]},{"n":21,"t":"论到那在耶和华殿中和犹大王宫内，并耶路撒冷剩下的器皿，万军之耶和华—以色列的神如此说：","notes":[]},{"n":22,"t":"必被带到巴比伦存在那里，直到我眷顾以色列人的日子。那时，我必将这器皿带回来，交还此地。这是耶和华说的。」","notes":[]}]},"28":{"heading":"耶利米和先知哈拿尼雅","verses":[{"n":1,"t":"当年，就是犹大王西底家登基第四年五月，基遍人押朔的儿子，先知哈拿尼雅，在耶和华的殿中当着祭司和众民对我说：","notes":[]},{"n":2,"t":"「万军之耶和华—以色列的神如此说：我已经折断巴比伦王的轭。","notes":[]},{"n":3,"t":"二年之内，我要将巴比伦王尼布甲尼撒从这地掠到巴比伦的器皿，就是耶和华殿中的一切器皿都带回此地。","notes":[]},{"n":4,"t":"我又要将犹大王约雅敬的儿子耶哥尼雅和被掳到巴比伦去的一切犹大人带回此地，因为我要折断巴比伦王的轭。这是耶和华说的。」","notes":[]},{"n":5,"t":"先知耶利米当着祭司和站在耶和华殿里的众民对先知哈拿尼雅说：","notes":[]},{"n":6,"t":"「阿们！愿耶和华如此行，愿耶和华成就你所预言的话，将耶和华殿中的器皿和一切被掳去的人从巴比伦带回此地。","notes":[]},{"n":7,"t":"然而我向你和众民耳中所要说的话，你应当听。","notes":[]},{"n":8,"t":"从古以来，在你我以前的先知，向多国和大邦说预言，论到争战、灾祸、瘟疫的事。","notes":[]},{"n":9,"t":"先知预言的平安，到话语成就的时候，人便知道他真是耶和华所差来的。」","notes":[]},{"n":10,"t":"于是，先知哈拿尼雅将先知耶利米颈项上的轭取下来，折断了。","notes":[]},{"n":11,"t":"哈拿尼雅又当着众民说：「耶和华如此说：二年之内我必照样从列国人的颈项上折断巴比伦王尼布甲尼撒的轭。」于是先知耶利米就走了。","notes":[]},{"n":12,"t":"先知哈拿尼雅把先知耶利米颈项上的轭折断以后，耶和华的话临到耶利米说：","notes":[]},{"n":13,"t":"「你去告诉哈拿尼雅说，耶和华如此说：你折断木轭，却换了铁轭！","notes":[]},{"n":14,"t":"因为万军之耶和华—以色列的神如此说：我已将铁轭加在这些国的颈项上，使他们服事巴比伦王尼布甲尼撒，他们总要服事他；我也把田野的走兽给了他。」","notes":[]},{"n":15,"t":"于是先知耶利米对先知哈拿尼雅说：「哈拿尼雅啊，你应当听！耶和华并没有差遣你，你竟使这百姓倚靠谎言。","notes":[]},{"n":16,"t":"所以耶和华如此说：看哪，我要叫你去世，你今年必死，因为你向耶和华说了叛逆的话。」","notes":[]},{"n":17,"t":"这样，先知哈拿尼雅当年七月间就死了。","notes":[]}]},"29":{"heading":"耶利米写信给巴比伦的犹大人","verses":[{"n":1,"t":"先知耶利米从耶路撒冷寄信与被掳的祭司、先知，和众民，并生存的长老，就是尼布甲尼撒从耶路撒冷掳到巴比伦去的。（","notes":[]},{"n":2,"t":"这在耶哥尼雅王和太后、太监，并犹大、耶路撒冷的首领，以及工匠、铁匠都离了耶路撒冷以后。）","notes":[]},{"n":3,"t":"他借沙番的儿子以利亚萨和希勒家的儿子基玛利的手寄去。他们二人是犹大王西底家打发往巴比伦去见尼布甲尼撒王的。","notes":[]},{"n":4,"t":"信上说：「万军之耶和华—以色列的神对一切被掳去的（就是我使他们从耶路撒冷被掳到巴比伦的人）如此说：","notes":[]},{"n":5,"t":"你们要盖造房屋，住在其中；栽种田园，吃其中所产的；","notes":[]},{"n":6,"t":"娶妻生儿女，为你们的儿子娶妻，使你们的女儿嫁人，生儿养女。在那里生养众多，不致减少。","notes":[]},{"n":7,"t":"我所使你们被掳到的那城，你们要为那城求平安，为那城祷告耶和华；因为那城得平安，你们也随着得平安。","notes":[]},{"n":8,"t":"万军之耶和华—以色列的神如此说：不要被你们中间的先知和占卜的诱惑，也不要听信自己所做的梦；","notes":[]},{"n":9,"t":"因为他们托我的名对你们说假预言，我并没有差遣他们。这是耶和华说的。","notes":[]},{"n":10,"t":"「耶和华如此说：为巴比伦所定的七十年满了以后，我要眷顾你们，向你们成就我的恩言，使你们仍回此地。","notes":[]},{"n":11,"t":"耶和华说：我知道我向你们所怀的意念是赐平安的意念，不是降灾祸的意念，要叫你们末后有指望。","notes":[]},{"n":12,"t":"你们要呼求我，祷告我，我就应允你们。","notes":[]},{"n":13,"t":"你们寻求我，若专心寻求我，就必寻见。","notes":[]},{"n":14,"t":"耶和华说：我必被你们寻见，我也必使你们被掳的人归回，将你们从各国中和我所赶你们到的各处招聚了来，又将你们带回我使你们被掳掠离开的地方。这是耶和华说的。","notes":[]},{"n":15,"t":"「你们说：『耶和华在巴比伦为我们兴起先知』；","notes":[]},{"n":16,"t":"所以耶和华论到坐大卫宝座的王和住在这城里的一切百姓，就是未曾与你们一同被掳的弟兄，","notes":[]},{"n":17,"t":"万军之耶和华如此说：『看哪，我必使刀剑、饥荒、瘟疫临到他们，使他们像极坏的无花果，坏得不可吃。","notes":[]},{"n":18,"t":"我必用刀剑、饥荒、瘟疫追赶他们，使他们在天下万国抛来抛去，在我所赶他们到的各国中，令人咒诅、惊骇、嗤笑、羞辱。","notes":[]},{"n":19,"t":"耶和华说：这是因为他们没有听从我的话，就是我从早起来差遣我仆人众先知去说的，无奈他们不听。这是耶和华说的。","notes":[]},{"n":20,"t":"所以你们一切被掳去的，就是我从耶路撒冷打发到巴比伦去的，当听耶和华的话。』」","notes":[]},{"n":21,"t":"万军之耶和华—以色列的神论到哥赖雅的儿子亚哈，并玛西雅的儿子西底家，如此说：「他们是托我名向你们说假预言的，我必将他们交在巴比伦王尼布甲尼撒的手中；他要在你们眼前杀害他们。","notes":[]},{"n":22,"t":"住巴比伦一切被掳的犹大人必借这二人赌咒说：『愿耶和华使你像巴比伦王在火中烧的西底家和亚哈一样。』","notes":[]},{"n":23,"t":"这二人是在以色列中行了丑事，与邻舍的妻行淫，又假托我名说我未曾吩咐他们的话。知道的是我，作见证的也是我。这是耶和华说的。」","notes":[]},{"n":24,"t":"「论到尼希兰人示玛雅，你当说，","notes":[],"heads":["示玛雅的信件"]},{"n":25,"t":"万军之耶和华—以色列的神如此说：你曾用自己的名寄信给耶路撒冷的众民和祭司玛西雅的儿子西番雅，并众祭司，说：","notes":[]},{"n":26,"t":"『耶和华已经立你西番雅为祭司，代替祭司耶何耶大，使耶和华殿中有官长，好将一切狂妄自称为先知的人用枷枷住，用锁锁住。","notes":[]},{"n":27,"t":"现在亚拿突人耶利米向你们自称为先知，你们为何没有责备他呢？","notes":[]},{"n":28,"t":"因为他寄信给我们在巴比伦的人说：被掳的事必长久。你们要盖造房屋，住在其中；栽种田园，吃其中所产的。』」","notes":[]},{"n":29,"t":"祭司西番雅就把这信念给先知耶利米听。","notes":[]},{"n":30,"t":"于是耶和华的话临到耶利米说：","notes":[]},{"n":31,"t":"「你当寄信给一切被掳的人说：『耶和华论到尼希兰人示玛雅说：因为示玛雅向你们说预言，我并没有差遣他，他使你们倚靠谎言；","notes":[]},{"n":32,"t":"所以耶和华如此说：我必刑罚尼希兰人示玛雅和他的后裔，他必无一人存留住在这民中，也不得见我所要赐与我百姓的福乐，因为他向耶和华说了叛逆的话。这是耶和华说的。』」","notes":[]}]},"30":{"heading":"耶和华给他子民的应许","verses":[{"n":1,"t":"耶和华的话临到耶利米说：","notes":[]},{"n":2,"t":"「耶和华—以色列的神如此说：你将我对你说过的一切话都写在书上。","notes":[]},{"n":3,"t":"耶和华说：日子将到，我要使我的百姓以色列和犹大被掳的人归回；我也要使他们回到我所赐给他们列祖之地，他们就得这地为业。这是耶和华说的。」","notes":[]},{"n":4,"t":"以下是耶和华论到以色列和犹大所说的话：","notes":[]},{"n":5,"t":"耶和华如此说：我们听见声音，是战抖惧怕而不平安的声音。","notes":[]},{"n":6,"t":"你们且访问看看，男人有产难吗？我怎么看见人人用手掐腰，像产难的妇人，脸面都变青了呢？","notes":[]},{"n":7,"t":"哀哉！那日为大，无日可比；这是雅各遭难的时候，但他必被救出来。","notes":[]},{"n":8,"t":"万军之耶和华说：「到那日，我必从你颈项上折断仇敌的轭，扭开他的绳索；外邦人不得再使你作他们的奴仆。","notes":[]},{"n":9,"t":"你们却要事奉耶和华—你们的神和我为你们所要兴起的王大卫。」","notes":[]},{"n":10,"t":"故此，耶和华说：我的仆人雅各啊，不要惧怕；以色列啊，不要惊惶；因我要从远方拯救你，从被掳到之地拯救你的后裔；雅各必回来得享平靖安逸，无人使他害怕。","notes":[]},{"n":11,"t":"因我与你同在，要拯救你，也要将所赶散你到的那些国灭绝净尽，却不将你灭绝净尽，倒要从宽惩治你，万不能不罚你。这是耶和华说的。","notes":["不罚你：或译以你为无罪"]},{"n":12,"t":"耶和华如此说：你的损伤无法医治；你的伤痕极其重大。","notes":[]},{"n":13,"t":"无人为你分诉，使你的伤痕得以缠裹；你没有医治的良药。","notes":[]},{"n":14,"t":"你所亲爱的都忘记你，不来探问你。我因你的罪孽甚大，罪恶众多，曾用仇敌加的伤害伤害你，用残忍者的惩治惩治你。","notes":["或译：理会"]},{"n":15,"t":"你为何因损伤哀号呢？你的痛苦无法医治。我因你的罪孽甚大，罪恶众多，曾将这些加在你身上。","notes":[]},{"n":16,"t":"故此，凡吞吃你的必被吞吃；你的敌人个个都被掳去；掳掠你的必成为掳物；抢夺你的必成为掠物。","notes":[]},{"n":17,"t":"耶和华说：我必使你痊愈，医好你的伤痕，都因人称你为被赶散的，说：这是锡安，无人来探问的！","notes":["或译：理会"]},{"n":18,"t":"耶和华如此说：我必使雅各被掳去的帐棚归回，也必顾惜他的住处。城必建造在原旧的山冈；宫殿也照旧有人居住。","notes":[]},{"n":19,"t":"必有感谢和欢乐的声音从其中发出，我要使他们增多，不致减少；使他们尊荣，不致卑微。","notes":[]},{"n":20,"t":"他们的儿女要如往日；他们的会众坚立在我面前；凡欺压他们的，我必刑罚他。","notes":[]},{"n":21,"t":"他们的君王必是属乎他们的；掌权的必从他们中间而出。我要使他就近我，他也要亲近我；不然，谁有胆量亲近我呢？这是耶和华说的。","notes":[]},{"n":22,"t":"你们要作我的子民，我要作你们的神。","notes":[]},{"n":23,"t":"看哪，耶和华的忿怒好像暴风已经发出；是扫灭的暴风，必转到恶人的头上。","notes":[]},{"n":24,"t":"耶和华的烈怒必不转消，直到他心中所拟定的成就了；末后的日子你们要明白。","notes":[]}]},"31":{"heading":"以色列人还乡","verses":[{"n":1,"t":"耶和华说：「那时，我必作以色列各家的神；他们必作我的子民。」","notes":[]},{"n":2,"t":"耶和华如此说：脱离刀剑的就是以色列人。我使他享安息的时候，他曾在旷野蒙恩。","notes":[]},{"n":3,"t":"古时耶和华向以色列显现，说：我以永远的爱爱你，因此我以慈爱吸引你。","notes":["或译：从远方","原文是我"]},{"n":4,"t":"以色列的民哪，我要再建立你，你就被建立；你必再以击鼓为美，与欢乐的人一同跳舞而出；","notes":["原文是处女"]},{"n":5,"t":"又必在撒马利亚的山上栽种葡萄园，栽种的人要享用所结的果子。","notes":[]},{"n":6,"t":"日子必到，以法莲山上守望的人必呼叫说：起来吧！我们可以上锡安，到耶和华—我们的神那里去。","notes":[]},{"n":7,"t":"耶和华如此说：你们当为雅各欢乐歌唱，因万国中为首的欢呼。当传扬颂赞说：耶和华啊，求你拯救你的百姓以色列所剩下的人。","notes":[]},{"n":8,"t":"我必将他们从北方领来，从地极招聚；同着他们来的有瞎子、瘸子、孕妇、产妇；他们必成为大帮回到这里来。","notes":[]},{"n":9,"t":"他们要哭泣而来。我要照他们恳求的引导他们，使他们在河水旁走正直的路，在其上不致绊跌；因为我是以色列的父，以法莲是我的长子。","notes":[]},{"n":10,"t":"列国啊，要听耶和华的话，传扬在远处的海岛说：赶散以色列的必招聚他，又看守他，好像牧人看守羊群。","notes":[]},{"n":11,"t":"因耶和华救赎了雅各，救赎他脱离比他更强之人的手。","notes":[]},{"n":12,"t":"他们要来到锡安的高处歌唱，又流归耶和华施恩之地，就是有五谷、新酒，和油，并羊羔、牛犊之地。他们的心必像浇灌的园子；他们也不再有一点愁烦。","notes":[]},{"n":13,"t":"那时，处女必欢乐跳舞；年少的、年老的，也必一同欢乐；因为我要使他们的悲哀变为欢喜，并要安慰他们，使他们的愁烦转为快乐。","notes":[]},{"n":14,"t":"我必以肥油使祭司的心满足；我的百姓也要因我的恩惠知足。这是耶和华说的。","notes":[]},{"n":15,"t":"耶和华如此说：在拉玛听见号咷痛哭的声音，是拉结哭她儿女，不肯受安慰，因为他们都不在了。","notes":[],"heads":["耶和华怜悯以色列"]},{"n":16,"t":"耶和华如此说：你禁止声音不要哀哭，禁止眼目不要流泪，因你所做之工必有赏赐；他们必从敌国归回。这是耶和华说的。","notes":[]},{"n":17,"t":"耶和华说：你末后必有指望；你的儿女必回到自己的境界。","notes":[]},{"n":18,"t":"我听见以法莲为自己悲叹说：你责罚我，我便受责罚，像不惯负轭的牛犊一样。求你使我回转，我便回转，因为你是耶和华—我的神。","notes":[]},{"n":19,"t":"我回转以后就真正懊悔；受教以后就拍腿叹息；我因担当幼年的凌辱就抱愧蒙羞。","notes":[]},{"n":20,"t":"耶和华说：以法莲是我的爱子吗？是可喜悦的孩子吗？我每逢责备他，仍深顾念他；所以我的心肠恋慕他；我必要怜悯他。","notes":[]},{"n":21,"t":"以色列民哪，你当为自己设立指路碑，竖起引路柱。你要留心向大路，就是你所去的原路；你当回转，回转到你这些城邑。","notes":["原文是处女"]},{"n":22,"t":"背道的民哪，你反来复去要到几时呢？耶和华在地上造了一件新事，就是女子护卫男子。","notes":["原文是女子"]},{"n":23,"t":"万军之耶和华—以色列的神如此说：「我使被掳之人归回的时候，他们在犹大地和其中的城邑必再这样说：公义的居所啊，圣山哪，愿耶和华赐福给你。","notes":[],"heads":["神子民的光明前途"]},{"n":24,"t":"犹大和属犹大城邑的人，农夫和放羊的人，要一同住在其中。","notes":[]},{"n":25,"t":"疲乏的人，我使他饱饫；愁烦的人，我使他知足。」","notes":[]},{"n":26,"t":"先知说：「我醒了，觉着睡得香甜！」","notes":[]},{"n":27,"t":"耶和华说：「日子将到，我要把人的种和牲畜的种播种在以色列家和犹大家。","notes":[]},{"n":28,"t":"我先前怎样留意将他们拔出、拆毁、毁坏、倾覆、苦害，也必照样留意将他们建立、栽植。这是耶和华说的。","notes":[]},{"n":29,"t":"当那些日子，人不再说：父亲吃了酸葡萄，儿子的牙酸倒了。","notes":[]},{"n":30,"t":"但各人必因自己的罪死亡；凡吃酸葡萄的，自己的牙必酸倒。」","notes":[]},{"n":31,"t":"耶和华说：「日子将到，我要与以色列家和犹大家另立新约，","notes":[]},{"n":32,"t":"不像我拉着他们祖宗的手，领他们出埃及地的时候，与他们所立的约。我虽作他们的丈夫，他们却背了我的约。这是耶和华说的。」","notes":[]},{"n":33,"t":"耶和华说：「那些日子以后，我与以色列家所立的约乃是这样：我要将我的律法放在他们里面，写在他们心上。我要作他们的神，他们要作我的子民。","notes":[]},{"n":34,"t":"他们各人不再教导自己的邻舍和自己的弟兄说：『你该认识耶和华』，因为他们从最小的到至大的都必认识我。我要赦免他们的罪孽，不再记念他们的罪恶。这是耶和华说的。」","notes":[]},{"n":35,"t":"那使太阳白日发光，使星月有定例，黑夜发亮，又搅动大海，使海中波浪匉訇的，万军之耶和华是他的名。他如此说：","notes":[]},{"n":36,"t":"这些定例若能在我面前废掉，以色列的后裔也就在我面前断绝，永远不再成国。这是耶和华说的。","notes":[]},{"n":37,"t":"耶和华如此说：若能量度上天，寻察下地的根基，我就因以色列后裔一切所行的弃绝他们。这是耶和华说的。","notes":[]},{"n":38,"t":"耶和华说：「日子将到，这城必为耶和华建造，从哈楠业楼直到角门。","notes":[]},{"n":39,"t":"准绳要往外量出，直到迦立山，又转到歌亚。","notes":[]},{"n":40,"t":"抛尸的全谷和倒灰之处，并一切田地，直到汲沦溪，又直到东方马门的拐角，都要归耶和华为圣，不再拔出，不再倾覆，直到永远。」","notes":[]}]},"32":{"heading":"耶利米购置田地","verses":[{"n":1,"t":"犹大王西底家第十年，就是尼布甲尼撒十八年，耶和华的话临到耶利米。","notes":[]},{"n":2,"t":"那时巴比伦王的军队围困耶路撒冷，先知耶利米囚在护卫兵的院内，在犹大王的宫中；","notes":[]},{"n":3,"t":"因为犹大王西底家已将他囚禁，说：「你为什么预言说，耶和华如此说：『我必将这城交在巴比伦王的手中，他必攻取这城。","notes":[]},{"n":4,"t":"犹大王西底家必不能逃脱迦勒底人的手，定要交在巴比伦王的手中，要口对口彼此说话，眼对眼彼此相看。","notes":[]},{"n":5,"t":"巴比伦王必将西底家带到巴比伦；西底家必住在那里，直到我眷顾他的时候。你们虽与迦勒底人争战，却不顺利。这是耶和华说的。』」","notes":[]},{"n":6,"t":"耶利米说：「耶和华的话临到我说：","notes":[]},{"n":7,"t":"『你叔叔沙龙的儿子哈拿篾必来见你，说：我在亚拿突的那块地，求你买来；因你买这地是合乎赎回之理。』」","notes":[]},{"n":8,"t":"我叔叔的儿子哈拿篾果然照耶和华的话来到护卫兵的院内，对我说：「我在便雅悯境内、亚拿突的那块地，求你买来；因你买来是合乎承受之理，是你当赎的。你为自己买来吧！」我—耶利米就知道这是耶和华的话。","notes":[]},{"n":9,"t":"我便向我叔叔的儿子哈拿篾买了亚拿突的那块地，平了十七舍客勒银子给他。","notes":[]},{"n":10,"t":"我在契上画押，将契封缄，又请见证人来，并用天平将银子平给他。","notes":[]},{"n":11,"t":"我便将照例按规所立的买契，就是封缄的那一张和敞着的那一张，","notes":[]},{"n":12,"t":"当着我叔叔的儿子哈拿篾和画押作见证的人，并坐在护卫兵院内的一切犹大人眼前，交给玛西雅的孙子尼利亚的儿子巴录。","notes":[]},{"n":13,"t":"当着他们众人眼前，我嘱咐巴录说：","notes":[]},{"n":14,"t":"「万军之耶和华—以色列的神如此说：要将这封缄的和敞着的两张契放在瓦器里，可以存留多日。","notes":[]},{"n":15,"t":"因为万军之耶和华—以色列的神如此说：将来在这地必有人再买房屋、田地，和葡萄园。」","notes":[]},{"n":16,"t":"我将买契交给尼利亚的儿子巴录以后，便祷告耶和华说：","notes":[],"heads":["耶利米的祈祷"]},{"n":17,"t":"「主耶和华啊，你曾用大能和伸出来的膀臂创造天地，在你没有难成的事。","notes":[]},{"n":18,"t":"你施慈爱与千万人，又将父亲的罪孽报应在他后世子孙的怀中，是至大全能的神，万军之耶和华是你的名。","notes":[]},{"n":19,"t":"谋事有大略，行事有大能，注目观看世人一切的举动，为要照各人所行的和他做事的结果报应他。","notes":[]},{"n":20,"t":"在埃及地显神迹奇事，直到今日在以色列和别人中间也是如此，使自己得了名声，正如今日一样。","notes":[]},{"n":21,"t":"用神迹奇事和大能的手，并伸出来的膀臂与大可畏的事，领你的百姓以色列出了埃及。","notes":[]},{"n":22,"t":"将这地赐给他们，就是你向他们列祖起誓应许赐给他们流奶与蜜之地。","notes":[]},{"n":23,"t":"他们进入这地得了为业，却不听从你的话，也不遵行你的律法；你一切所吩咐他们行的，他们一无所行，因此你使这一切的灾祸临到他们。","notes":[]},{"n":24,"t":"看哪，敌人已经来到，筑垒要攻取这城；城也因刀剑、饥荒、瘟疫交在攻城的迦勒底人手中。你所说的话都成就了，你也看见了。","notes":[]},{"n":25,"t":"主耶和华啊，你对我说：要用银子为自己买那块地，又请见证人。其实这城已交在迦勒底人的手中了。」","notes":[]},{"n":26,"t":"耶和华的话临到耶利米说：","notes":[]},{"n":27,"t":"「我是耶和华，是凡有血气者的神，岂有我难成的事吗？","notes":[]},{"n":28,"t":"耶和华如此说：我必将这城交付迦勒底人的手和巴比伦王尼布甲尼撒的手，他必攻取这城。","notes":[]},{"n":29,"t":"攻城的迦勒底人必来放火焚烧这城和其中的房屋。在这房屋上，人曾向巴力烧香，向别神浇奠，惹我发怒。","notes":[]},{"n":30,"t":"以色列人和犹大人自从幼年以来，专行我眼中看为恶的事；以色列人尽以手所做的惹我发怒。这是耶和华说的。","notes":[]},{"n":31,"t":"这城自从建造的那日直到今日，常惹我的怒气和忿怒，使我将这城从我面前除掉；","notes":[]},{"n":32,"t":"是因以色列人和犹大人一切的邪恶，就是他们和他们的君王、首领、祭司、先知，并犹大的众人，以及耶路撒冷的居民所行的，惹我发怒。","notes":[]},{"n":33,"t":"他们以背向我，不以面向我；我虽从早起来教训他们，他们却不听从，不受教训，","notes":[]},{"n":34,"t":"竟把可憎之物设立在称为我名下的殿中，污秽了这殿。","notes":[]},{"n":35,"t":"他们在欣嫩子谷建筑巴力的邱坛，好使自己的儿女经火归摩洛；他们行这可憎的事，使犹大陷在罪里，这并不是我所吩咐的，也不是我心所起的意。」","notes":[]},{"n":36,"t":"现在论到这城，就是你们所说、已经因刀剑、饥荒、瘟疫交在巴比伦王手中的，耶和华—以色列的神如此说：","notes":[],"heads":["复国的应许"]},{"n":37,"t":"「我在怒气、忿怒，和大恼恨中，将以色列人赶到各国。日后我必从那里将他们招聚出来，领他们回到此地，使他们安然居住。","notes":[]},{"n":38,"t":"他们要作我的子民，我要作他们的神。","notes":[]},{"n":39,"t":"我要使他们彼此同心同道，好叫他们永远敬畏我，使他们和他们后世的子孙得福乐，","notes":[]},{"n":40,"t":"又要与他们立永远的约，必随着他们施恩，并不离开他们，且使他们有敬畏我的心，不离开我。","notes":[]},{"n":41,"t":"我必欢喜施恩与他们，要尽心尽意、诚诚实实将他们栽于此地。","notes":[]},{"n":42,"t":"「因为耶和华如此说：我怎样使这一切大祸临到这百姓，我也要照样使我所应许他们的一切福乐都临到他们。","notes":[]},{"n":43,"t":"你们说，这地是荒凉、无人民、无牲畜，是交付迦勒底人手之地。日后在这境内，必有人置买田地。","notes":[]},{"n":44,"t":"在便雅悯地、耶路撒冷四围的各处、犹大的城邑、山地的城邑、高原的城邑，并南地的城邑，人必用银子买田地，在契上画押，将契封缄，请出见证人，因为我必使被掳的人归回。这是耶和华说的。」","notes":[]}]},"33":{"heading":"重申复国的应许","verses":[{"n":1,"t":"耶利米还囚在护卫兵的院内，耶和华的话第二次临到他说：","notes":[]},{"n":2,"t":"「成就的是耶和华，造作、为要建立的也是耶和华；耶和华是他的名。他如此说：","notes":[]},{"n":3,"t":"你求告我，我就应允你，并将你所不知道、又大又难的事指示你。","notes":[]},{"n":4,"t":"论到这城中的房屋和犹大王的宫室，就是拆毁为挡敌人高垒和刀剑的，耶和华—以色列的神如此说：","notes":[]},{"n":5,"t":"人要与迦勒底人争战，正是拿死尸充满这房屋，就是我在怒气和忿怒中所杀的人，因他们的一切恶，我就掩面不顾这城。","notes":[]},{"n":6,"t":"看哪，我要使这城得以痊愈安舒，使城中的人得医治，又将丰盛的平安和诚实显明与他们。","notes":[]},{"n":7,"t":"我也要使犹大被掳的和以色列被掳的归回，并建立他们和起初一样。","notes":[]},{"n":8,"t":"我要除净他们的一切罪，就是向我所犯的罪；又要赦免他们的一切罪，就是干犯我、违背我的罪。","notes":[]},{"n":9,"t":"这城要在地上万国人面前使我得颂赞，得荣耀，名为可喜可乐之城。万国人因听见我向这城所赐的福乐、所施的恩惠平安，就惧怕战兢。」","notes":[]},{"n":10,"t":"耶和华如此说：「你们论这地方，说是荒废无人民无牲畜之地，但在这荒凉无人民无牲畜的犹大城邑和耶路撒冷的街上，","notes":[]},{"n":11,"t":"必再听见有欢喜和快乐的声音、新郎和新妇的声音，并听见有人说：要称谢万军之耶和华，因耶和华本为善；他的慈爱永远长存！又有奉感谢祭到耶和华殿中之人的声音；因为我必使这地被掳的人归回，和起初一样。这是耶和华说的。」","notes":[]},{"n":12,"t":"万军之耶和华如此说：「在这荒废无人民无牲畜之地，并其中所有的城邑，必再有牧人的住处；他们要使羊群躺卧在那里。","notes":[]},{"n":13,"t":"在山地的城邑、高原的城邑、南地的城邑、便雅悯地、耶路撒冷四围的各处，和犹大的城邑必再有羊群从数点的人手下经过。这是耶和华说的。」","notes":[]},{"n":14,"t":"耶和华说：「日子将到，我应许以色列家和犹大家的恩言必然成就。","notes":[]},{"n":15,"t":"当那日子，那时候，我必使大卫公义的苗裔长起来；他必在地上施行公平和公义。","notes":[]},{"n":16,"t":"在那日子犹大必得救，耶路撒冷必安然居住，他的名必称为『耶和华—我们的义』。","notes":[]},{"n":17,"t":"「因为耶和华如此说：大卫必永不断人坐在以色列家的宝座上；","notes":[]},{"n":18,"t":"祭司、利未人在我面前也不断人献燔祭、烧素祭，时常办理献祭的事。」","notes":[]},{"n":19,"t":"耶和华的话临到耶利米说：","notes":[]},{"n":20,"t":"「耶和华如此说：你们若能废弃我所立白日黑夜的约，使白日黑夜不按时轮转，","notes":[]},{"n":21,"t":"就能废弃我与我仆人大卫所立的约，使他没有儿子在他的宝座上为王，并能废弃我与事奉我的祭司、利未人所立的约。","notes":[]},{"n":22,"t":"天上的万象不能数算，海边的尘沙也不能斗量；我必照样使我仆人大卫的后裔和事奉我的利未人多起来。」","notes":[]},{"n":23,"t":"耶和华的话临到耶利米说：","notes":[]},{"n":24,"t":"「你没有揣摩这百姓的话吗？他们说：『耶和华所拣选的二族，他已经弃绝了。』他们这样藐视我的百姓，以为不再成国。","notes":[]},{"n":25,"t":"耶和华如此说：若是我立白日黑夜的约不能存住，若是我未曾安排天地的定例，","notes":[]},{"n":26,"t":"我就弃绝雅各的后裔和我仆人大卫的后裔，不使大卫的后裔治理亚伯拉罕、以撒、雅各的后裔；因为我必使他们被掳的人归回，也必怜悯他们。」","notes":[]}]},"34":{"heading":"给西底家的信息","verses":[{"n":1,"t":"巴比伦王尼布甲尼撒率领他的全军和地上属他的各国各邦，攻打耶路撒冷和属耶路撒冷所有的城邑。那时，耶和华的话临到耶利米说：","notes":[]},{"n":2,"t":"「耶和华—以色列的神说，你去告诉犹大王西底家，耶和华如此说：我要将这城交付巴比伦王的手，他必用火焚烧。","notes":[]},{"n":3,"t":"你必不能逃脱他的手，定被拿住，交在他的手中。你的眼要见巴比伦王的眼，他要口对口和你说话，你也必到巴比伦去。","notes":[]},{"n":4,"t":"犹大王西底家啊，你还要听耶和华的话。耶和华论到你如此说：你必不被刀剑杀死，","notes":[]},{"n":5,"t":"你必平安而死，人必为你焚烧物件，好像为你列祖，就是在你以前的先王焚烧一般。人必为你举哀说：『哀哉！我主啊。』耶和华说：这话是我说的。」","notes":[]},{"n":6,"t":"于是，先知耶利米在耶路撒冷将这一切话告诉犹大王西底家。","notes":[]},{"n":7,"t":"那时，巴比伦王的军队正攻打耶路撒冷，又攻打犹大所剩下的城邑，就是拉吉和亚西加。原来犹大的坚固城只剩下这两座。","notes":[]},{"n":8,"t":"西底家王与耶路撒冷的众民立约，要向他们宣告自由，叫各人任他希伯来的仆人和婢女自由出去，谁也不可使他的一个犹大弟兄作奴仆。（此后，有耶和华的话临到耶利米。）","notes":[],"end":9,"heads":["违背释放奴隶的约"]},{"n":10,"t":"所有立约的首领和众民就任他的仆人婢女自由出去，谁也不再叫他们作奴仆。大家都顺从，将他们释放了；","notes":[]},{"n":11,"t":"后来却又反悔，叫所任去自由的仆人婢女回来，勉强他们仍为仆婢。","notes":[]},{"n":12,"t":"因此耶和华的话临到耶利米说：","notes":[]},{"n":13,"t":"「耶和华—以色列的神如此说：我将你们的列祖从埃及地为奴之家领出来的时候，与他们立约说：","notes":[]},{"n":14,"t":"『你的一个希伯来弟兄若卖给你，服事你六年，到第七年你们各人就要任他自由出去。』只是你们列祖不听从我，也不侧耳而听。","notes":[]},{"n":15,"t":"如今你们回转，行我眼中看为正的事，各人向邻舍宣告自由，并且在称为我名下的殿中、在我面前立约。","notes":[]},{"n":16,"t":"你们却又反悔，亵渎我的名，各人叫所任去随意自由的仆人婢女回来，勉强他们仍为仆婢。","notes":[]},{"n":17,"t":"所以耶和华如此说：你们没有听从我，各人向弟兄邻舍宣告自由。看哪！我向你们宣告一样自由，就是使你们自由于刀剑、饥荒、瘟疫之下，并且使你们在天下万国中抛来抛去。这是耶和华说的。","notes":[]},{"n":18,"t":"犹大的首领、耶路撒冷的首领、太监、祭司，和国中的众民曾将牛犊劈开，分成两半，从其中经过，在我面前立约。后来又违背我的约，不遵行这约上的话。","notes":[],"end":19},{"n":20,"t":"我必将他们交在仇敌和寻索其命的人手中；他们的尸首必给空中的飞鸟和地上的野兽作食物。","notes":[]},{"n":21,"t":"并且我必将犹大王西底家和他的首领交在他们仇敌和寻索其命的人，与那暂离你们而去巴比伦王军队的手中。","notes":[]},{"n":22,"t":"耶和华说：我必吩咐他们回到这城，攻打这城，将城攻取，用火焚烧。我也要使犹大的城邑变为荒场，无人居住。」","notes":[]}]},"35":{"heading":"耶利米和利甲族","verses":[{"n":1,"t":"当犹大王约西亚之子约雅敬的时候，耶和华的话临到耶利米说：","notes":[]},{"n":2,"t":"「你去见利甲族的人，和他们说话，领他们进入耶和华殿的一间屋子，给他们酒喝。」","notes":[]},{"n":3,"t":"我就将哈巴洗尼雅的孙子雅利米雅的儿子雅撒尼亚和他弟兄，并他众子，以及利甲全族的人，","notes":[]},{"n":4,"t":"领到耶和华的殿，进入神人伊基大利的儿子哈难众子的屋子。那屋子在首领的屋子旁边，在沙龙之子把门的玛西雅屋子以上。","notes":[]},{"n":5,"t":"于是我在利甲族人面前设摆盛满酒的碗和杯，对他们说：「请你们喝酒。」","notes":[]},{"n":6,"t":"他们却说：「我们不喝酒；因为我们先祖利甲的儿子约拿达曾吩咐我们说：『你们与你们的子孙永不可喝酒，","notes":[]},{"n":7,"t":"也不可盖房、撒种、栽种葡萄园，但一生的年日要住帐棚，使你们的日子在寄居之地得以延长。』","notes":[]},{"n":8,"t":"凡我们先祖利甲的儿子约拿达所吩咐我们的话，我们都听从了。我们和我们的妻子儿女一生的年日都不喝酒，","notes":[]},{"n":9,"t":"也不盖房居住，也没有葡萄园、田地，和种子，","notes":[]},{"n":10,"t":"但住帐棚，听从我们先祖约拿达的话，照他所吩咐我们的去行。","notes":[]},{"n":11,"t":"巴比伦王尼布甲尼撒上此地来，我们因怕迦勒底的军队和亚兰的军队，就说：『来吧，我们到耶路撒冷去。』这样，我们才住在耶路撒冷。」","notes":[]},{"n":12,"t":"耶和华的话临到耶利米说：","notes":[]},{"n":13,"t":"「万军之耶和华—以色列的神如此说：你去对犹大人和耶路撒冷的居民说，耶和华说：你们不受教训，不听从我的话吗？","notes":[]},{"n":14,"t":"利甲的儿子约拿达所吩咐他子孙不可喝酒的话，他们已经遵守，直到今日也不喝酒，因为他们听从先祖的吩咐。我从早起来警戒你们，你们却不听从我。","notes":[]},{"n":15,"t":"我从早起来，差遣我的仆人众先知去，说：『你们各人当回头，离开恶道，改正行为，不随从事奉别神，就必住在我所赐给你们和你们列祖的地上。』只是你们没有听从我，也没有侧耳而听。","notes":[]},{"n":16,"t":"利甲的儿子约拿达的子孙能遵守先人所吩咐他们的命，这百姓却没有听从我！","notes":[]},{"n":17,"t":"因此，耶和华—万军之神、以色列的神如此说：我要使我所说的一切灾祸临到犹大人和耶路撒冷的一切居民。因为我对他们说话，他们没有听从；我呼唤他们，他们没有答应。」","notes":[]},{"n":18,"t":"耶利米对利甲族的人说：「万军之耶和华—以色列的神如此说：因你们听从你们先祖约拿达的吩咐，谨守他的一切诫命，照他所吩咐你们的去行，","notes":[]},{"n":19,"t":"所以万军之耶和华—以色列的神如此说：利甲的儿子约拿达必永不缺人侍立在我面前。」","notes":[]}]},"36":{"heading":"巴录在圣殿里宣读书卷","verses":[{"n":1,"t":"犹大王约西亚的儿子约雅敬第四年，耶和华的话临到耶利米说：","notes":[]},{"n":2,"t":"「你取一书卷，将我对你说攻击以色列和犹大，并各国的一切话，从我对你说话的那日，就是从约西亚的日子起直到今日，都写在其上。","notes":[]},{"n":3,"t":"或者犹大家听见我想要降与他们的一切灾祸，各人就回头，离开恶道，我好赦免他们的罪孽和罪恶。」","notes":[]},{"n":4,"t":"所以，耶利米召了尼利亚的儿子巴录来；巴录就从耶利米口中，将耶和华对耶利米所说的一切话写在书卷上。","notes":[]},{"n":5,"t":"耶利米吩咐巴录说：「我被拘管，不能进耶和华的殿。","notes":[]},{"n":6,"t":"所以你要去趁禁食的日子，在耶和华殿中将耶和华的话，就是你从我口中所写在书卷上的话，念给百姓和一切从犹大城邑出来的人听。","notes":[]},{"n":7,"t":"或者他们在耶和华面前恳求各人回头，离开恶道，因为耶和华向这百姓所说要发的怒气和忿怒是大的。」","notes":[]},{"n":8,"t":"尼利亚的儿子巴录就照先知耶利米一切所吩咐的去行，在耶和华的殿中从书上念耶和华的话。","notes":[]},{"n":9,"t":"犹大王约西亚的儿子约雅敬第五年九月，耶路撒冷的众民和那从犹大城邑来到耶路撒冷的众民，在耶和华面前宣告禁食的日子，","notes":[]},{"n":10,"t":"巴录就在耶和华殿的上院，耶和华殿的新门口，沙番的儿子文士基玛利雅的屋内，念书上耶利米的话给众民听。","notes":[]},{"n":11,"t":"沙番的孙子、基玛利雅的儿子米该亚听见书上耶和华的一切话，","notes":[],"heads":["向官员宣读书卷"]},{"n":12,"t":"他就下到王宫，进入文士的屋子。众首领，就是文士以利沙玛、示玛雅的儿子第莱雅、亚革波的儿子以利拿单、沙番的儿子基玛利雅、哈拿尼雅的儿子西底家，和其余的首领都坐在那里。","notes":[]},{"n":13,"t":"于是米该亚对他们述说他所听见的一切话，就是巴录向百姓念那书的时候所听见的。","notes":[]},{"n":14,"t":"众首领就打发古示的曾孙、示利米雅的孙子、尼探雅的儿子犹底到巴录那里，对他说：「你将所念给百姓听的书卷拿在手中到我们这里来。」尼利亚的儿子巴录就手拿书卷来到他们那里。","notes":[]},{"n":15,"t":"他们对他说：「请你坐下，念给我们听。」巴录就念给他们听。","notes":[]},{"n":16,"t":"他们听见这一切话就害怕，面面相观，对巴录说：「我们必须将这一切话告诉王。」","notes":[]},{"n":17,"t":"他们问巴录说：「请你告诉我们，你怎样从他口中写这一切话呢？」","notes":[]},{"n":18,"t":"巴录回答说：「他用口向我说这一切话，我就用笔墨写在书上。」","notes":[]},{"n":19,"t":"众首领对巴录说：「你和耶利米要去藏起来，不可叫人知道你们在哪里。」","notes":[]},{"n":20,"t":"众首领进院见王，却先把书卷存在文士以利沙玛的屋内，以后将这一切话说给王听。","notes":[],"heads":["约雅敬焚烧书卷"]},{"n":21,"t":"王就打发犹底去拿这书卷来，他便从文士以利沙玛的屋内取来，念给王和王左右侍立的众首领听。","notes":[]},{"n":22,"t":"那时正是九月，王坐在过冬的房屋里，王的前面火盆中有烧着的火。","notes":[]},{"n":23,"t":"犹底念了三四篇，王就用文士的刀将书卷割破，扔在火盆中，直到全卷在火中烧尽了。","notes":["或译：行"]},{"n":24,"t":"王和听见这一切话的臣仆都不惧怕，也不撕裂衣服。","notes":[]},{"n":25,"t":"以利拿单和第莱雅，并基玛利雅恳求王不要烧这书卷，他却不听。","notes":[]},{"n":26,"t":"王就吩咐哈米勒的儿子耶拉篾和亚斯列的儿子西莱雅，并亚伯叠的儿子示利米雅，去捉拿文士巴录和先知耶利米。耶和华却将他们隐藏。","notes":["或译：王的儿子"]},{"n":27,"t":"王烧了书卷（其上有巴录从耶利米口中所写的话）以后，耶和华的话临到耶利米说：","notes":[],"heads":["耶利米另写一书卷"]},{"n":28,"t":"「你再取一卷，将犹大王约雅敬所烧第一卷上的一切话写在其上。","notes":[]},{"n":29,"t":"论到犹大王约雅敬你要说，耶和华如此说：你烧了书卷，说：『你为什么在其上写着，说巴比伦王必要来毁灭这地，使这地上绝了人民牲畜呢？』","notes":[]},{"n":30,"t":"所以耶和华论到犹大王约雅敬说：他后裔中必没有人坐在大卫的宝座上；他的尸首必被抛弃，白日受炎热，黑夜受寒霜。","notes":[]},{"n":31,"t":"我必因他和他后裔，并他臣仆的罪孽刑罚他们。我要使我所说的一切灾祸临到他们和耶路撒冷的居民，并犹大人；只是他们不听。」","notes":[]},{"n":32,"t":"于是，耶利米又取一书卷交给尼利亚的儿子文士巴录，他就从耶利米的口中写了犹大王约雅敬所烧前卷上的一切话，另外又添了许多相仿的话。","notes":[]}]},"37":{"heading":"西底家求耶利米代祷","verses":[{"n":1,"t":"约西亚的儿子西底家代替约雅敬的儿子哥尼雅为王，是巴比伦王尼布甲尼撒立在犹大地作王的。","notes":[]},{"n":2,"t":"但西底家和他的臣仆，并国中的百姓，都不听从耶和华借先知耶利米所说的话。","notes":[]},{"n":3,"t":"西底家王打发示利米雅的儿子犹甲和祭司玛西雅的儿子西番雅去见先知耶利米，说：「求你为我们祷告耶和华—我们的神。」","notes":[]},{"n":4,"t":"那时耶利米在民中出入，因为他们还没有把他囚在监里。","notes":[]},{"n":5,"t":"法老的军队已经从埃及出来，那围困耶路撒冷的迦勒底人听见他们的风声，就拔营离开耶路撒冷去了。","notes":[]},{"n":6,"t":"耶和华的话临到先知耶利米说：","notes":[]},{"n":7,"t":"「耶和华—以色列的神如此说：犹大王打发你们来求问我，你们要如此对他说：『那出来帮助你们法老的军队必回埃及本国去。","notes":[]},{"n":8,"t":"迦勒底人必再来攻打这城，并要攻取，用火焚烧。","notes":[]},{"n":9,"t":"耶和华如此说：你们不要自欺说「迦勒底人必定离开我们」，因为他们必不离开。","notes":[]},{"n":10,"t":"你们即便杀败了与你们争战的迦勒底全军，但剩下受伤的人也必各人从帐棚里起来，用火焚烧这城。』」","notes":[]},{"n":11,"t":"迦勒底的军队因怕法老的军队，拔营离开耶路撒冷的时候，","notes":[],"heads":["耶利米被捕入狱"]},{"n":12,"t":"耶利米就杂在民中出离耶路撒冷，要往便雅悯地去，在那里得自己的地业。","notes":[]},{"n":13,"t":"他到了便雅悯门那里，有守门官名叫伊利雅，是哈拿尼亚的孙子、示利米雅的儿子，他就拿住先知耶利米，说：「你是投降迦勒底人哪！」","notes":[]},{"n":14,"t":"耶利米说：「你这是谎话，我并不是投降迦勒底人。」伊利雅不听他的话，就拿住他，解到首领那里。","notes":[]},{"n":15,"t":"首领恼怒耶利米，就打了他，将他囚在文士约拿单的房屋中，因为他们以这房屋当作监牢。","notes":[]},{"n":16,"t":"耶利米来到狱中，进入牢房，在那里囚了多日。","notes":[]},{"n":17,"t":"西底家王打发人提出他来，在自己的宫内私下问他说：「从耶和华有什么话临到没有？」耶利米说：「有！」又说：「你必交在巴比伦王手中。」","notes":[]},{"n":18,"t":"耶利米又对西底家王说：「我在什么事上得罪你，或你的臣仆，或这百姓，你竟将我囚在监里呢？","notes":[]},{"n":19,"t":"对你们预言巴比伦王必不来攻击你们和这地的先知，现今在哪里呢？","notes":[]},{"n":20,"t":"主—我的王啊，求你现在垂听，准我在你面前的恳求：不要使我回到文士约拿单的房屋中，免得我死在那里。」","notes":[]},{"n":21,"t":"于是，西底家王下令，他们就把耶利米交在护卫兵的院中，每天从饼铺街取一个饼给他，直到城中的饼用尽了。这样，耶利米仍在护卫兵的院中。","notes":[]}]},"38":{"heading":"耶利米在枯井里","verses":[{"n":1,"t":"玛坦的儿子示法提雅、巴施户珥的儿子基大利、示利米雅的儿子犹甲、玛基雅的儿子巴施户珥听见耶利米对众人所说的话，说：","notes":[]},{"n":2,"t":"「耶和华如此说：住在这城里的必遭刀剑、饥荒、瘟疫而死；但出去归降迦勒底人的必得存活，就是以自己命为掠物的，必得存活。","notes":[]},{"n":3,"t":"耶和华如此说：这城必要交在巴比伦王军队的手中，他必攻取这城。」","notes":[]},{"n":4,"t":"于是首领对王说：「求你将这人治死；因他向城里剩下的兵丁和众民说这样的话，使他们的手发软。这人不是求这百姓得平安，乃是叫他们受灾祸。」","notes":[]},{"n":5,"t":"西底家王说：「他在你们手中，无论何事，王也不能与你们反对。」","notes":[]},{"n":6,"t":"他们就拿住耶利米，下在哈米勒的儿子玛基雅的牢狱里；那牢狱在护卫兵的院中。他们用绳子将耶利米系下去。牢狱里没有水，只有淤泥，耶利米就陷在淤泥中。","notes":["或译：王的儿子"]},{"n":7,"t":"在王宫的太监古实人以伯·米勒，听见他们将耶利米下了牢狱（那时王坐在便雅悯门口），","notes":[]},{"n":8,"t":"以伯·米勒就从王宫里出来，对王说：","notes":[]},{"n":9,"t":"「主—我的王啊，这些人向先知耶利米一味地行恶，将他下在牢狱中；他在那里必因饥饿而死，因为城中再没有粮食。」","notes":[]},{"n":10,"t":"王就吩咐古实人以伯·米勒说：「你从这里带领三十人，趁着先知耶利米未死以前，将他从牢狱中提上来。」","notes":[]},{"n":11,"t":"于是以伯·米勒带领这些人同去，进入王宫，到库房以下，从那里取了些碎布和破烂的衣服，用绳子缒下牢狱去到耶利米那里。","notes":[]},{"n":12,"t":"古实人以伯·米勒对耶利米说：「你用这些碎布和破烂的衣服放在绳子上，垫你的胳肢窝。」耶利米就照样行了。","notes":[]},{"n":13,"t":"这样，他们用绳子将耶利米从牢狱里拉上来。耶利米仍在护卫兵的院中。","notes":[]},{"n":14,"t":"西底家王打发人带领先知耶利米，进耶和华殿中第三门里见王。王就对耶利米说：「我要问你一件事，你丝毫不可向我隐瞒。」","notes":[],"heads":["西底家问计于耶利米"]},{"n":15,"t":"耶利米对西底家说：「我若告诉你，你岂不定要杀我吗？我若劝戒你，你必不听从我。」","notes":[]},{"n":16,"t":"西底家王就私下向耶利米说：「我指着那造我们生命之永生的耶和华起誓：我必不杀你，也不将你交在寻索你命的人手中。」","notes":[]},{"n":17,"t":"耶利米对西底家说：「耶和华—万军之神、以色列的神如此说：你若出去归降巴比伦王的首领，你的命就必存活，这城也不致被火焚烧，你和你的全家都必存活。","notes":[]},{"n":18,"t":"你若不出去归降巴比伦王的首领，这城必交在迦勒底人手中。他们必用火焚烧，你也不得脱离他们的手。」","notes":[]},{"n":19,"t":"西底家王对耶利米说：「我怕那些投降迦勒底人的犹大人，恐怕迦勒底人将我交在他们手中，他们戏弄我。」","notes":[]},{"n":20,"t":"耶利米说：「迦勒底人必不将你交出。求你听从我对你所说耶和华的话，这样你必得好处，你的命也必存活。","notes":[]},{"n":21,"t":"你若不肯出去，耶和华指示我的话乃是这样：","notes":[]},{"n":22,"t":"犹大王宫里所剩的妇女必都带到巴比伦王的首领那里。这些妇女必说：你知己的朋友催逼你，胜过你；见你的脚陷入淤泥中，就转身退后了。","notes":[]},{"n":23,"t":"「人必将你的后妃和你的儿女带到迦勒底人那里；你也不得脱离他们的手，必被巴比伦王的手捉住；你也必使这城被火焚烧。」","notes":[]},{"n":24,"t":"西底家对耶利米说：「不要使人知道这些话，你就不至于死。","notes":[]},{"n":25,"t":"首领若听见了我与你说话，就来见你，问你说：『你对王说什么话不要向我们隐瞒，我们就不杀你。王向你说什么话也要告诉我们。』","notes":[]},{"n":26,"t":"你就对他们说：『我在王面前恳求不要叫我回到约拿单的房屋死在那里。』」","notes":[]},{"n":27,"t":"随后众首领来见耶利米，问他，他就照王所吩咐的一切话回答他们。他们不再与他说话，因为事情没有泄漏。","notes":[]},{"n":28,"t":"于是耶利米仍在护卫兵的院中，直到耶路撒冷被攻取的日子。","notes":[]}]},"39":{"heading":"耶路撒冷陷落","verses":[{"n":1,"t":"犹大王西底家第九年十月，巴比伦王尼布甲尼撒率领全军来围困耶路撒冷。","notes":[]},{"n":2,"t":"西底家十一年四月初九日，城被攻破。","notes":[]},{"n":3,"t":"耶路撒冷被攻取的时候，巴比伦王的首领尼甲·沙利薛、三甲·尼波、撒西金—拉撒力、尼甲·沙利薛—拉墨，并巴比伦王其余的一切首领都来坐在中门。","notes":[]},{"n":4,"t":"犹大王西底家和一切兵丁看见他们，就在夜间从靠近王园两城中间的门出城逃跑，往亚拉巴逃去。","notes":[]},{"n":5,"t":"迦勒底的军队追赶他们，在耶利哥的平原追上西底家，将他拿住，带到哈马地的利比拉、巴比伦王尼布甲尼撒那里；尼布甲尼撒就审判他。","notes":[]},{"n":6,"t":"巴比伦王在利比拉、西底家眼前杀了他的众子，又杀了犹大的一切贵胄，","notes":[]},{"n":7,"t":"并且剜西底家的眼睛，用铜链锁着他，要带到巴比伦去。","notes":[]},{"n":8,"t":"迦勒底人用火焚烧王宫和百姓的房屋，又拆毁耶路撒冷的城墙。","notes":[]},{"n":9,"t":"那时，护卫长尼布撒拉旦将城里所剩下的百姓和投降他的逃民，以及其余的民都掳到巴比伦去了。","notes":[]},{"n":10,"t":"护卫长尼布撒拉旦却将民中毫无所有的穷人留在犹大地，当时给他们葡萄园和田地。","notes":[]},{"n":11,"t":"巴比伦王尼布甲尼撒提到耶利米，嘱咐护卫长尼布撒拉旦说：","notes":[],"heads":["耶利米被释放"]},{"n":12,"t":"「你领他去，好好地看待他，切不可害他；他对你怎么说，你就向他怎么行。」","notes":[]},{"n":13,"t":"护卫长尼布撒拉旦和尼布沙斯班—拉撒力、尼甲·沙利薛—拉墨，并巴比伦王的一切官长，","notes":[]},{"n":14,"t":"打发人去，将耶利米从护卫兵院中提出来，交与沙番的孙子亚希甘的儿子基大利，带回家去。于是耶利米住在民中。","notes":[]},{"n":15,"t":"耶利米还囚在护卫兵院中的时候，耶和华的话临到他说：","notes":[],"heads":["以伯·米勒的希望"]},{"n":16,"t":"「你去告诉古实人以伯·米勒说，万军之耶和华—以色列的神如此说：我说降祸不降福的话必临到这城，到那时必在你面前成就了。","notes":[]},{"n":17,"t":"耶和华说：到那日我必拯救你，你必不致交在你所怕的人手中。","notes":[]},{"n":18,"t":"我定要搭救你，你不致倒在刀下，却要以自己的命为掠物，因你倚靠我。这是耶和华说的。」","notes":[]}]},"40":{"heading":"耶利米跟基大利同住","verses":[{"n":1,"t":"耶利米锁在耶路撒冷和犹大被掳到巴比伦的人中，护卫长尼布撒拉旦将他从拉玛释放以后，耶和华的话临到耶利米。","notes":[]},{"n":2,"t":"护卫长将耶利米叫来，对他说：「耶和华—你的神曾说要降这祸与此地。","notes":[]},{"n":3,"t":"耶和华使这祸临到，照他所说的行了；因为你们得罪耶和华，没有听从他的话，所以这事临到你们。","notes":[]},{"n":4,"t":"现在我解开你手上的链子，你若看与我同往巴比伦去好，就可以去，我必厚待你；你若看与我同往巴比伦去不好，就不必去。看哪，全地在你面前，你以为哪里美好，哪里合宜，只管上那里去吧！」","notes":[]},{"n":5,"t":"耶利米还没有回去，护卫长说：「你可以回到沙番的孙子亚希甘的儿子基大利那里去；现在巴比伦王立他作犹大城邑的省长。你可以在他那里住在民中，不然，你看哪里合宜就可以上那里去。」于是护卫长送他粮食和礼物，释放他去了。","notes":[]},{"n":6,"t":"耶利米就到米斯巴见亚希甘的儿子基大利，在他那里住在境内剩下的民中。","notes":[]},{"n":7,"t":"在田野的一切军长和属他们的人听见巴比伦王立了亚希甘的儿子基大利作境内的省长，并将没有掳到巴比伦的男人、妇女、孩童，和境内极穷的人全交给他。","notes":[],"heads":["基大利被委派为总督"]},{"n":8,"t":"于是军长尼探雅的儿子以实玛利，加利亚的两个儿子约哈难和约拿单，单户篾的儿子西莱雅，并尼陀法人以斐的众子，玛迦人的儿子耶撒尼亚和属他们的人，都到米斯巴见基大利。","notes":[]},{"n":9,"t":"沙番的孙子亚希甘的儿子基大利向他们和属他们的人起誓说：「不要怕服事迦勒底人，只管住在这地，服事巴比伦王，就可以得福。","notes":[]},{"n":10,"t":"至于我，我要住在米斯巴，伺候那到我们这里来的迦勒底人；只是你们当积蓄酒、油，和夏天的果子，收在器皿里，住在你们所占的城邑中。」","notes":[]},{"n":11,"t":"在摩押地和亚扪人中，在以东地和各国的一切犹大人，听见巴比伦王留下些犹大人，并立沙番的孙子亚希甘的儿子基大利管理他们。","notes":[]},{"n":12,"t":"这一切犹大人就从所赶到的各处回来，到犹大地的米斯巴基大利那里，又积蓄了许多的酒，并夏天的果子。","notes":[]},{"n":13,"t":"加利亚的儿子约哈难和在田野的一切军长来到米斯巴见基大利，","notes":[],"heads":["基大利被暗杀"]},{"n":14,"t":"对他说：「亚扪人的王巴利斯打发尼探雅的儿子以实玛利来要你的命，你知道吗？」亚希甘的儿子基大利却不信他们的话。","notes":[]},{"n":15,"t":"加利亚的儿子约哈难在米斯巴私下对基大利说：「求你容我去杀尼探雅的儿子以实玛利，必无人知道。何必让他要你的命，使聚集到你这里来的犹大人都分散，以致犹大剩下的人都灭亡呢？」","notes":[]},{"n":16,"t":"亚希甘的儿子基大利对加利亚的儿子约哈难说：「你不可行这事，你所论以实玛利的话是假的。」","notes":[]}]},"41":{"heading":"","verses":[{"n":1,"t":"七月间，王的大臣宗室以利沙玛的孙子、尼探雅的儿子以实玛利带着十个人，来到米斯巴见亚希甘的儿子基大利。他们在米斯巴一同吃饭。","notes":[]},{"n":2,"t":"尼探雅的儿子以实玛利和同他来的那十个人起来，用刀杀了沙番的孙子亚希甘的儿子基大利，就是巴比伦王所立为全地省长的。","notes":[]},{"n":3,"t":"以实玛利又杀了在米斯巴、基大利那里的一切犹大人和所遇见的迦勒底兵丁。","notes":[]},{"n":4,"t":"他杀了基大利，无人知道。","notes":[]},{"n":5,"t":"第二天，有八十人从示剑和示罗，并撒马利亚来，胡须剃去，衣服撕裂，身体划破，手拿素祭和乳香，要奉到耶和华的殿。","notes":[]},{"n":6,"t":"尼探雅的儿子以实玛利出米斯巴迎接他们，随走随哭；遇见了他们，就对他们说：「你们可以来见亚希甘的儿子基大利。」","notes":[]},{"n":7,"t":"他们到了城中，尼探雅的儿子以实玛利和同着他的人就将他们杀了，抛在坑中。","notes":[]},{"n":8,"t":"只是他们中间有十个人对以实玛利说：「不要杀我们，因为我们有许多大麦、小麦、油、蜜藏在田间。」于是他住了手，没有将他们杀在弟兄中间。","notes":[]},{"n":9,"t":"以实玛利将所杀之人的尸首都抛在坑里基大利的旁边；这坑是从前亚撒王因怕以色列王巴沙所挖的。尼探雅的儿子以实玛利将那些被杀的人填满了坑。","notes":[]},{"n":10,"t":"以实玛利将米斯巴剩下的人，就是众公主和仍住在米斯巴所有的百姓，原是护卫长尼布撒拉旦交给亚希甘的儿子基大利的，都掳去了。尼探雅的儿子以实玛利掳了他们，要往亚扪人那里去。","notes":[]},{"n":11,"t":"加利亚的儿子约哈难和同着他的众军长听见尼探雅的儿子以实玛利所行的一切恶，","notes":[]},{"n":12,"t":"就带领众人前往，要和尼探雅的儿子以实玛利争战，在基遍的大水旁遇见他。","notes":["或译：大水池旁"]},{"n":13,"t":"以实玛利那里的众人看见加利亚的儿子约哈难和同着他的众军长，就都欢喜。","notes":[]},{"n":14,"t":"这样，以实玛利从米斯巴所掳去的众人都转身归加利亚的儿子约哈难去了。","notes":[]},{"n":15,"t":"尼探雅的儿子以实玛利和八个人脱离约哈难的手，逃往亚扪人那里去了。","notes":[]},{"n":16,"t":"尼探雅的儿子以实玛利杀了亚希甘的儿子基大利，从米斯巴将剩下的一切百姓、兵丁、妇女、孩童、太监掳到基遍之后，加利亚的儿子约哈难和同着他的众军长将他们都夺回来，","notes":[]},{"n":17,"t":"带到靠近伯利恒的金罕寓住下，要进入埃及去；","notes":["或译：基罗特金罕"]},{"n":18,"t":"因为尼探雅的儿子以实玛利杀了巴比伦王所立为省长的亚希甘的儿子基大利，约哈难惧怕迦勒底人。","notes":[]}]},"42":{"heading":"百姓求耶利米代祷","verses":[{"n":1,"t":"众军长和加利亚的儿子约哈难，并何沙雅的儿子耶撒尼亚以及众百姓，从最小的到至大的都进前来，","notes":["又名亚撒利雅，见四十三章二节"]},{"n":2,"t":"对先知耶利米说：「求你准我们在你面前祈求，为我们这剩下的人祷告耶和华—你的神。我们本来众多，现在剩下的极少，这是你亲眼所见的。","notes":[]},{"n":3,"t":"愿耶和华—你的神指示我们所当走的路，所当做的事。」","notes":[]},{"n":4,"t":"先知耶利米对他们说：「我已经听见你们了，我必照着你们的话祷告耶和华—你们的神。耶和华无论回答什么，我必都告诉你们，毫不隐瞒。」","notes":[]},{"n":5,"t":"于是他们对耶利米说：「我们若不照耶和华—你的神差遣你来说的一切话行，愿耶和华在我们中间作真实诚信的见证。","notes":[]},{"n":6,"t":"我们现在请你到耶和华—我们的神面前，他说的无论是好是歹，我们都必听从；我们听从耶和华—我们神的话，就可以得福。」","notes":[]},{"n":7,"t":"过了十天，耶和华的话临到耶利米。","notes":[],"heads":["耶和华回答耶利米的祷告"]},{"n":8,"t":"他就将加利亚的儿子约哈难和同着他的众军长，并众百姓，从最小的到至大的都叫了来，","notes":[]},{"n":9,"t":"对他们说：「耶和华—以色列的神，就是你们请我在他面前为你们祈求的主，如此说：","notes":[]},{"n":10,"t":"『你们若仍住在这地，我就建立你们，必不拆毁，栽植你们，并不拔出，因我为降与你们的灾祸后悔了。","notes":[]},{"n":11,"t":"不要怕你们所怕的巴比伦王。』」耶和华说：「不要怕他！因为我与你们同在，要拯救你们脱离他的手。","notes":[]},{"n":12,"t":"我也要使他发怜悯，好怜悯你们，叫你们归回本地。","notes":[]},{"n":13,"t":"倘若你们说：『我们不住在这地』，以致不听从耶和华—你们神的话，","notes":[]},{"n":14,"t":"说：『我们不住这地，却要进入埃及地，在那里看不见争战，听不见角声，也不致无食饥饿。我们必住在那里。』","notes":[]},{"n":15,"t":"你们所剩下的犹大人哪，现在要听耶和华的话。万军之耶和华—以色列的神如此说：『你们若定意要进入埃及，在那里寄居，","notes":[]},{"n":16,"t":"你们所惧怕的刀剑在埃及地必追上你们！你们所惧怕的饥荒在埃及要紧紧地跟随你们！你们必死在那里！","notes":[]},{"n":17,"t":"凡定意要进入埃及在那里寄居的必遭刀剑、饥荒、瘟疫而死，无一人存留，逃脱我所降与他们的灾祸。』","notes":[]},{"n":18,"t":"「万军之耶和华—以色列的神如此说：『我怎样将我的怒气和忿怒倾在耶路撒冷的居民身上，你们进入埃及的时候，我也必照样将我的忿怒倾在你们身上，以致你们令人辱骂、惊骇、咒诅、羞辱，你们不得再见这地方。』","notes":[]},{"n":19,"t":"所剩下的犹大人哪，耶和华论到你们说：『不要进入埃及去。』你们要确实地知道我今日警教你们了。","notes":[]},{"n":20,"t":"你们行诡诈自害；因为你们请我到耶和华—你们的神那里，说：『求你为我们祷告耶和华—我们神，照耶和华—我们的神一切所说的告诉我们，我们就必遵行。』","notes":[]},{"n":21,"t":"我今日将这话告诉你们，耶和华—你们的神为你们的事差遣我到你们那里说的，你们却一样没有听从。","notes":[]},{"n":22,"t":"现在你们要确实地知道，你们在所要去寄居之地必遭刀剑、饥荒、瘟疫而死。」","notes":[]}]},"43":{"heading":"耶利米被带到埃及","verses":[{"n":1,"t":"耶利米向众百姓说完了耶和华—他们神的一切话，就是耶和华—他们神差遣他去所说的一切话。","notes":[]},{"n":2,"t":"何沙雅的儿子亚撒利雅和加利亚的儿子约哈难，并一切狂傲的人，就对耶利米说：「你说谎言！耶和华—我们的神并没有差遣你来说：『你们不可进入埃及，在那里寄居。』","notes":[]},{"n":3,"t":"这是尼利亚的儿子巴录挑唆你害我们，要将我们交在迦勒底人的手中，使我们有被杀的，有被掳到巴比伦去的。」","notes":[]},{"n":4,"t":"于是加利亚的儿子约哈难和一切军长，并众百姓，不听从耶和华的话住在犹大地。","notes":[]},{"n":5,"t":"加利亚的儿子约哈难和一切军长却将所剩下的犹大人，就是从被赶到各国回来在犹大地寄居的男人、妇女、孩童，和众公主，并护卫长尼布撒拉旦所留在沙番的孙子亚希甘的儿子基大利那里的众人，与先知耶利米，以及尼利亚的儿子巴录，","notes":[],"end":6},{"n":7,"t":"都带入埃及地，到了答比匿。这是因他们不听从耶和华的话。","notes":[]},{"n":8,"t":"在答比匿，耶和华的话临到耶利米说：","notes":[]},{"n":9,"t":"「你在犹大人眼前要用手拿几块大石头，藏在砌砖的灰泥中，就是在答比匿法老的宫门那里，","notes":[]},{"n":10,"t":"对他们说：『万军之耶和华—以色列的神如此说：我必召我的仆人巴比伦王尼布甲尼撒来。在所藏的石头上我要安置他的宝座；他必将光华的宝帐支搭在其上。","notes":[]},{"n":11,"t":"他要来攻击埃及地，定为死亡的，必致死亡；定为掳掠的，必被掳掠；定为刀杀的，必交刀杀。","notes":[]},{"n":12,"t":"我要在埃及神的庙中使火着起，巴比伦王要将庙宇焚烧，神像掳去；他要得埃及地，好像牧人披上外衣，从那里安然而去。","notes":["原文是披上"]},{"n":13,"t":"他必打碎埃及地伯·示麦的柱像，用火焚烧埃及神的庙宇。』」","notes":[]}]},"44":{"heading":"耶和华给流亡埃及的以色列人的信息","verses":[{"n":1,"t":"有临到耶利米的话，论及一切住在埃及地的犹大人，就是住在密夺、答比匿、挪弗、巴忒罗境内的犹大人，说：","notes":[]},{"n":2,"t":"「万军之耶和华—以色列的神如此说：我所降与耶路撒冷和犹大各城的一切灾祸你们都看见了。那些城邑今日荒凉，无人居住；","notes":[]},{"n":3,"t":"这是因居民所行的恶，去烧香事奉别神，就是他们和你们，并你们列祖所不认识的神，惹我发怒。","notes":[]},{"n":4,"t":"我从早起来差遣我的仆人众先知去说，你们切不要行我所厌恶这可憎之事。","notes":[]},{"n":5,"t":"他们却不听从，不侧耳而听，不转离恶事，仍向别神烧香。","notes":[]},{"n":6,"t":"因此，我的怒气和忿怒都倒出来，在犹大城邑中和耶路撒冷的街市上，如火着起，以致都荒废凄凉，正如今日一样。","notes":[]},{"n":7,"t":"现在耶和华—万军之神、以色列的神如此说：你们为何作这大恶自害己命，使你们的男人、妇女、婴孩，和吃奶的都从犹大中剪除、不留一人呢？","notes":[]},{"n":8,"t":"就是因你们手所做的，在所去寄居的埃及地向别神烧香惹我发怒，使你们被剪除，在天下万国中令人咒诅羞辱。","notes":[]},{"n":9,"t":"你们列祖的恶行，犹大列王和他们后妃的恶行，你们自己和你们妻子的恶行，就是在犹大地、耶路撒冷街上所行的，你们都忘了吗？","notes":[]},{"n":10,"t":"到如今还没有懊悔，没有惧怕，没有遵行我在你们和你们列祖面前所设立的法度律例。","notes":[]},{"n":11,"t":"「所以万军之耶和华—以色列的神如此说：我必向你们变脸降灾，以致剪除犹大众人。","notes":[]},{"n":12,"t":"那定意进入埃及地、在那里寄居的，就是所剩下的犹大人，我必使他们尽都灭绝，必在埃及地仆倒，必因刀剑饥荒灭绝；从最小的到至大的都必遭刀剑饥荒而死，以致令人辱骂、惊骇、咒诅、羞辱。","notes":[]},{"n":13,"t":"我怎样用刀剑、饥荒、瘟疫刑罚耶路撒冷，也必照样刑罚那些住在埃及地的犹大人；","notes":[]},{"n":14,"t":"甚至那进入埃及地寄居的，就是所剩下的犹大人，都不得逃脱，也不得存留归回犹大地。他们心中甚想归回居住之地；除了逃脱的以外，一个都不能归回。」","notes":[]},{"n":15,"t":"那些住在埃及地巴忒罗知道自己妻子向别神烧香的，与旁边站立的众妇女，聚集成群，回答耶利米说：","notes":[]},{"n":16,"t":"「论到你奉耶和华的名向我们所说的话，我们必不听从。","notes":[]},{"n":17,"t":"我们定要成就我们口中所出的一切话，向天后烧香、浇奠祭，按着我们与我们列祖、君王、首领在犹大的城邑中和耶路撒冷的街市上素常所行的一样；因为那时我们吃饱饭、享福乐，并不见灾祸。","notes":[]},{"n":18,"t":"自从我们停止向天后烧香、浇奠祭，我们倒缺乏一切，又因刀剑饥荒灭绝。」","notes":[]},{"n":19,"t":"妇女说：「我们向天后烧香、浇奠祭，做天后像的饼供奉她，向她浇奠祭，是外乎我们的丈夫吗？」","notes":[]},{"n":20,"t":"耶利米对一切那样回答他的男人妇女说：","notes":[]},{"n":21,"t":"「你们与你们列祖、君王、首领，并国内的百姓，在犹大城邑中和耶路撒冷街市上所烧的香，耶和华岂不记念，心中岂不思想吗？","notes":[]},{"n":22,"t":"耶和华因你们所作的恶、所行可憎的事，不能再容忍，所以你们的地荒凉，令人惊骇咒诅，无人居住，正如今日一样。","notes":[]},{"n":23,"t":"你们烧香，得罪耶和华，没有听从他的话，没有遵行他的律法、条例、法度，所以你们遭遇这灾祸，正如今日一样。」","notes":[]},{"n":24,"t":"耶利米又对众民和众妇女说：「你们在埃及地的一切犹大人当听耶和华的话。","notes":[]},{"n":25,"t":"万军之耶和华—以色列的神如此说：你们和你们的妻都口中说、手里做，说：『我们定要偿还所许的愿，向天后烧香、浇奠祭。』现在你们只管坚定所许的愿而偿还吧！","notes":[]},{"n":26,"t":"所以你们住在埃及地的一切犹大人当听耶和华的话。耶和华说：我指着我的大名起誓，在埃及全地，我的名不再被犹大一个人的口称呼说：『我指着主—永生的耶和华起誓。』","notes":[]},{"n":27,"t":"我向他们留意降祸不降福；在埃及地的一切犹大人必因刀剑、饥荒所灭，直到灭尽。","notes":[]},{"n":28,"t":"脱离刀剑、从埃及地归回犹大地的人数很少；那进入埃及地要在那里寄居的，就是所剩下的犹大人，必知道是谁的话立得住，是我的话呢？是他们的话呢？","notes":[]},{"n":29,"t":"耶和华说：我在这地方刑罚你们，必有预兆，使你们知道我降祸与你们的话必要立得住。","notes":[]},{"n":30,"t":"耶和华如此说：我必将埃及王法老合弗拉交在他仇敌和寻索其命的人手中，像我将犹大王西底家交在他仇敌和寻索其命的巴比伦王尼布甲尼撒手中一样。」","notes":[]}]},"45":{"heading":"耶和华给巴录的许诺","verses":[{"n":1,"t":"犹大王约西亚的儿子约雅敬第四年，尼利亚的儿子巴录将先知耶利米口中所说的话写在书上。耶利米说：","notes":[]},{"n":2,"t":"「巴录啊，耶和华—以色列的神说：","notes":[]},{"n":3,"t":"巴录曾说：『哀哉！耶和华将忧愁加在我的痛苦上，我因唉哼而困乏，不得安歇。』","notes":["原文是你"]},{"n":4,"t":"你要这样告诉他，耶和华如此说：我所建立的，我必拆毁；我所栽植的，我必拔出；在全地我都如此行。","notes":[]},{"n":5,"t":"你为自己图谋大事吗？不要图谋！我必使灾祸临到凡有血气的。但你无论往哪里去，我必使你以自己的命为掠物。这是耶和华说的。」","notes":[]}]},"46":{"heading":"埃及在迦基米施受挫","verses":[{"n":1,"t":"耶和华论列国的话临到先知耶利米。","notes":[]},{"n":2,"t":"论到关乎埃及王法老尼哥的军队：这军队安营在幼发拉底河边的迦基米施，是巴比伦王尼布甲尼撒在犹大王约西亚的儿子约雅敬第四年所打败的。","notes":[]},{"n":3,"t":"你们要预备大小盾牌，往前上阵。","notes":[]},{"n":4,"t":"你们套上车，骑上马！顶盔站立，磨枪贯甲！","notes":[]},{"n":5,"t":"我为何看见他们惊惶转身退后呢？他们的勇士打败了，急忙逃跑，并不回头；惊吓四围都有！这是耶和华说的。","notes":[]},{"n":6,"t":"不要容快跑的逃避；不要容勇士逃脱；他们在北方幼发拉底河边绊跌仆倒。","notes":["或译：快跑的不能逃避；勇士不能逃脱"]},{"n":7,"t":"像尼罗河涨发，像江河之水翻腾的是谁呢？","notes":[]},{"n":8,"t":"埃及像尼罗河涨发，像江河的水翻腾。他说：我要涨发遮盖遍地；我要毁灭城邑和其中的居民。","notes":[]},{"n":9,"t":"马匹上去吧！车辆急行吧！勇士，就是手拿盾牌的古实人和弗人，并拉弓的路德族，都出去吧！","notes":["又作利比亚人"]},{"n":10,"t":"那日是主—万军之耶和华报仇的日子，要向敌人报仇。刀剑必吞吃得饱，饮血饮足；因为主—万军之耶和华在北方幼发拉底河边有献祭的事。","notes":[]},{"n":11,"t":"埃及的民哪，可以上基列取乳香去；你虽多服良药，总是徒然，不得治好。","notes":["原文是处女"]},{"n":12,"t":"列国听见你的羞辱，遍地满了你的哀声；勇士与勇士彼此相碰，一齐跌倒。","notes":[]},{"n":13,"t":"耶和华对先知耶利米所说的话，论到巴比伦王尼布甲尼撒要来攻击埃及地：","notes":[],"heads":["尼布甲尼撒来犯"]},{"n":14,"t":"你们要传扬在埃及，宣告在密夺，报告在挪弗、答比匿说：要站起出队，自作准备，因为刀剑在你四围施行吞灭的事。","notes":[]},{"n":15,"t":"你的壮士为何被冲去呢？他们站立不住；因为耶和华驱逐他们，","notes":[]},{"n":16,"t":"使多人绊跌；他们也彼此撞倒，说：起来吧！我们再往本民本地去，好躲避欺压的刀剑。","notes":[]},{"n":17,"t":"他们在那里喊叫说：埃及王法老不过是个声音；他已错过所定的时候了。","notes":["或译：已经败亡"]},{"n":18,"t":"君王—名为万军之耶和华的说：我指着我的永生起誓：尼布甲尼撒来的势派必像他泊在众山之中，像迦密在海边一样。","notes":["原文是他"]},{"n":19,"t":"住在埃及的民哪，要预备掳去时所用的物件；因为挪弗必成为荒场，且被烧毁，无人居住。","notes":["原文是女子"]},{"n":20,"t":"埃及是肥美的母牛犊；但出于北方的毁灭来到了！来到了！","notes":["或译：牛虻"]},{"n":21,"t":"其中的雇勇好像圈里的肥牛犊，他们转身退后，一齐逃跑，站立不住；因为他们遭难的日子、追讨的时候已经临到。","notes":[]},{"n":22,"t":"其中的声音好像蛇行一样。敌人要成队而来，如砍伐树木的手拿斧子攻击他。","notes":[]},{"n":23,"t":"耶和华说：埃及的树林虽然不能寻察，敌人却要砍伐，因他们多于蝗虫，不可胜数。","notes":["或译：穿不过"]},{"n":24,"t":"埃及的民必然蒙羞，必交在北方人的手中。","notes":["原文是女子"]},{"n":25,"t":"万军之耶和华—以色列的神说：「我必刑罚挪的亚扪和法老，并埃及与埃及的神，以及君王，也必刑罚法老和倚靠他的人。","notes":["埃及尊大之神"]},{"n":26,"t":"我要将他们交付寻索其命之人的手和巴比伦王尼布甲尼撒与他臣仆的手；以后埃及必再有人居住，与从前一样。这是耶和华说的。」","notes":[]},{"n":27,"t":"我的仆人雅各啊，不要惧怕！以色列啊，不要惊惶！因我要从远方拯救你，从被掳到之地拯救你的后裔。雅各必回来，得享平靖安逸，无人使他害怕。","notes":[],"heads":["耶和华要救他的子民"]},{"n":28,"t":"我的仆人雅各啊，不要惧怕！因我与你同在。我要将我所赶你到的那些国灭绝净尽，却不将你灭绝净尽，倒要从宽惩治你，万不能不罚你。这是耶和华说的。","notes":["不罚你：或译以你为无罪"]}]},"47":{"heading":"有关非利士的话","verses":[{"n":1,"t":"法老攻击迦萨之先，有耶和华论非利士人的话临到先知耶利米。","notes":[]},{"n":2,"t":"耶和华如此说：有水从北方发起，成为涨溢的河，要涨过遍地和其中所有的，并城和其中所住的。人必呼喊；境内的居民都必哀号。","notes":[]},{"n":3,"t":"听见敌人壮马蹄跳的响声和战车隆隆、车轮轰轰；为父的手就发软，不回头看顾儿女。","notes":[]},{"n":4,"t":"因为日子将到，要毁灭一切非利士人，剪除帮助泰尔、西顿所剩下的人。原来耶和华必毁灭非利士人，就是迦斐托海岛余剩的人。","notes":[]},{"n":5,"t":"迦萨成了光秃；平原中所剩的亚实基伦归于无有。你用刀划身，要到几时呢？","notes":[]},{"n":6,"t":"耶和华的刀剑哪，你到几时才止息呢？你要入鞘，安靖不动。","notes":[]},{"n":7,"t":"耶和华既吩咐你攻击亚实基伦和海边之地，他已经派定你，焉能止息呢？","notes":[]}]},"48":{"heading":"摩押的毁灭","verses":[{"n":1,"t":"论摩押。万军之耶和华—以色列的神如此说：尼波有祸了！因变为荒场。基列亭蒙羞被攻取；米斯迦蒙羞被毁坏；","notes":[]},{"n":2,"t":"摩押不再被称赞。有人在希实本设计谋害她，说：来吧！我们将她剪除，不再成国。玛得缅哪，你也必默默无声；刀剑必追赶你。","notes":[]},{"n":3,"t":"从何罗念有喊荒凉大毁灭的哀声：","notes":[]},{"n":4,"t":"摩押毁灭了！她的孩童发哀声，使人听见。","notes":["或译：家僮"]},{"n":5,"t":"人上鲁希坡随走随哭，因为在何罗念的下坡听见毁灭的哀声。","notes":[]},{"n":6,"t":"你们要奔逃，自救性命，独自居住，好像旷野的杜松。","notes":[]},{"n":7,"t":"你因倚靠自己所做的和自己的财宝必被攻取。基抹和属他的祭司、首领也要一同被掳去。","notes":[]},{"n":8,"t":"行毁灭的必来到各城，并无一城得免。山谷必致败落，平原必被毁坏；正如耶和华所说的。","notes":[]},{"n":9,"t":"要将翅膀给摩押，使她可以飞去。她的城邑必致荒凉，无人居住。（","notes":[]},{"n":10,"t":"懒惰为耶和华行事的，必受咒诅；禁止刀剑不经血的，必受咒诅。）","notes":[]},{"n":11,"t":"摩押自幼年以来常享安逸，如酒在渣滓上澄清，没有从这器皿倒在那器皿里，也未曾被掳去。因此，它的原味尚存，香气未变。","notes":[],"heads":["摩押的城镇被毁灭"]},{"n":12,"t":"耶和华说：「日子将到，我必打发倒酒的往她那里去，将她倒出来，倒空她的器皿，打碎她的坛子。","notes":[]},{"n":13,"t":"摩押必因基抹羞愧，像以色列家从前倚靠伯特利的神羞愧一样。","notes":[]},{"n":14,"t":"你们怎么说：我们是勇士，是有勇力打仗的呢？","notes":[]},{"n":15,"t":"摩押变为荒场，敌人上去进了她的城邑。她所特选的少年人下去遭了杀戮；这是君王—名为万军之耶和华说的。","notes":[]},{"n":16,"t":"摩押的灾殃临近；她的苦难速速来到。","notes":[]},{"n":17,"t":"凡在她四围的和认识她名的，你们都要为她悲伤，说：那结实的杖和那美好的棍，何竟折断了呢？","notes":[]},{"n":18,"t":"住在底本的民哪，要从你荣耀的位上下来，坐受干渴；因毁灭摩押的上来攻击你，毁坏了你的保障。","notes":["原文是女子"]},{"n":19,"t":"住亚罗珥的啊，要站在道旁观望，问逃避的男人和逃脱的女人说：是什么事呢？","notes":[]},{"n":20,"t":"摩押因毁坏蒙羞；你们要哀号呼喊，要在亚嫩旁报告说：摩押变为荒场！","notes":[]},{"n":21,"t":"「刑罚临到平原之地的何伦、雅杂、米法押、","notes":[]},{"n":22,"t":"底本、尼波、伯·低比拉太音、","notes":[]},{"n":23,"t":"基列亭、伯·迦末、伯·米恩、","notes":[]},{"n":24,"t":"加略、波斯拉，和摩押地远近所有的城邑。","notes":[]},{"n":25,"t":"摩押的角砍断了，摩押的膀臂折断了。这是耶和华说的。」","notes":[]},{"n":26,"t":"「你们要使摩押沉醉，因她向耶和华夸大。她要在自己所吐之中打滚，又要被人嗤笑。","notes":[],"heads":["摩押要受凌辱"]},{"n":27,"t":"摩押啊，你不曾嗤笑以色列吗？她岂是在贼中查出来的呢？你每逢提到她便摇头。","notes":[]},{"n":28,"t":"摩押的居民哪，要离开城邑，住在山崖里，像鸽子在深渊口上搭窝。","notes":[]},{"n":29,"t":"我们听说摩押人骄傲，是极其骄傲；听说他自高自傲，并且狂妄，居心自大。","notes":[]},{"n":30,"t":"耶和华说：我知道他的忿怒是虚空的；他夸大的话一无所成。","notes":[]},{"n":31,"t":"因此，我要为摩押哀号，为摩押全地呼喊；人必为吉珥·哈列设人叹息。","notes":[]},{"n":32,"t":"西比玛的葡萄树啊，我为你哀哭，甚于雅谢人哀哭。你的枝子蔓延过海，直长到雅谢海。那行毁灭的已经临到你夏天的果子和你所摘的葡萄。","notes":[]},{"n":33,"t":"肥田和摩押地的欢喜快乐都被夺去；我使酒榨的酒绝流，无人踹酒欢呼；那欢呼却变为仇敌的呐喊。","notes":["原文是那欢呼却不是欢呼"]},{"n":34,"t":"「希实本人发的哀声达到以利亚利，直达到雅杂；从琐珥达到何罗念，直到伊基拉·施利施亚，因为宁林的水必然干涸。」","notes":[]},{"n":35,"t":"耶和华说：「我必在摩押地使那在邱坛献祭的，和那向他的神烧香的都断绝了。","notes":[]},{"n":36,"t":"我心腹为摩押哀鸣如箫，我心肠为吉珥·哈列设人也是如此，因摩押人所得的财物都灭没了。","notes":[]},{"n":37,"t":"「各人头上光秃，胡须剪短，手有划伤，腰束麻布。","notes":[]},{"n":38,"t":"在摩押的各房顶上和街市上处处有人哀哭；因我打碎摩押，好像打碎无人喜悦的器皿。这是耶和华说的。","notes":[]},{"n":39,"t":"摩押何等毁坏！何等哀号！何等羞愧转背！这样，摩押必令四围的人嗤笑惊骇。」","notes":[]},{"n":40,"t":"耶和华如此说：仇敌必如大鹰飞起，展开翅膀，攻击摩押。","notes":[],"heads":["摩押无路可逃"]},{"n":41,"t":"加略被攻取，保障也被占据。到那日，摩押的勇士心中疼痛如临产的妇人。","notes":[]},{"n":42,"t":"摩押必被毁灭，不再成国，因她向耶和华夸大。","notes":[]},{"n":43,"t":"耶和华说：摩押的居民哪，恐惧、陷坑、网罗都临近你。","notes":[]},{"n":44,"t":"躲避恐惧的必坠入陷坑；从陷坑上来的必被网罗缠住；因我必使追讨之年临到摩押。这是耶和华说的。","notes":[]},{"n":45,"t":"躲避的人无力站在希实本的影下；因为有火从希实本发出，有火焰出于西宏的城，烧尽摩押的角和哄嚷人的头顶。","notes":[]},{"n":46,"t":"摩押啊，你有祸了！属基抹的民灭亡了！因你的众子都被掳去，你的众女也被掳去。","notes":[]},{"n":47,"t":"耶和华说：到末后，我还要使被掳的摩押人归回。摩押受审判的话到此为止。","notes":[]}]},"49":{"heading":"耶和华审判亚扪","verses":[{"n":1,"t":"论亚扪人。耶和华如此说：以色列没有儿子吗？没有后嗣吗？玛勒堪为何得迦得之地为业呢？属他的民为何住其中的城邑呢？","notes":[]},{"n":2,"t":"耶和华说：日子将到，我必使人听见打仗的喊声，是攻击亚扪人拉巴的喊声。拉巴要成为乱堆；属她的乡村要被火焚烧。先前得以色列地为业的，此时以色列倒要得他们的地为业。这是耶和华说的。","notes":["原文是女子"]},{"n":3,"t":"希实本哪，你要哀号，因为爱地变为荒场。拉巴的居民哪，要呼喊，以麻布束腰；要哭号，在篱笆中跑来跑去；因玛勒堪和属他的祭司、首领要一同被掳去。","notes":["原文是女子"]},{"n":4,"t":"背道的民哪，你们为何因有山谷，就是水流的山谷夸张呢？为何倚靠财宝说：谁能来到我们这里呢？","notes":["原文是女子"]},{"n":5,"t":"主—万军之耶和华说：我要使恐吓从四围的人中临到你们；你们必被赶出，各人一直前往，没有人收聚逃民。","notes":[]},{"n":6,"t":"后来我还要使被掳的亚扪人归回。这是耶和华说的。","notes":[]},{"n":7,"t":"论以东。万军之耶和华如此说：提幔中再没有智慧吗？明哲人不再有谋略吗？他们的智慧尽归无有吗？","notes":[],"heads":["耶和华审判以东"]},{"n":8,"t":"底但的居民哪，要转身逃跑，住在深密处；因为我向以扫追讨的时候，必使灾殃临到他。","notes":[]},{"n":9,"t":"摘葡萄的若来到他那里，岂不剩下些葡萄呢？盗贼若夜间而来，岂不毁坏直到够了呢？","notes":[]},{"n":10,"t":"我却使以扫赤露，显出他的隐密处；他不能自藏。他的后裔、弟兄、邻舍尽都灭绝；他也归于无有。","notes":[]},{"n":11,"t":"你撇下孤儿，我必保全他们的命；你的寡妇可以倚靠我。","notes":[]},{"n":12,"t":"耶和华如此说：「原不该喝那杯的一定要喝。你能尽免刑罚吗？你必不能免，一定要喝！」","notes":[]},{"n":13,"t":"耶和华说：「我指着自己起誓，波斯拉必令人惊骇、羞辱、咒诅，并且荒凉。她的一切城邑必变为永远的荒场。」","notes":[]},{"n":14,"t":"我从耶和华那里听见信息，并有使者被差往列国去，说：你们聚集来攻击以东，要起来争战。","notes":[]},{"n":15,"t":"我使你在列国中为最小，在世人中被藐视。","notes":[]},{"n":16,"t":"住在山穴中据守山顶的啊，论到你的威吓，你因心中的狂傲自欺；你虽如大鹰高高搭窝，我却从那里拉下你来。这是耶和华说的。","notes":[]},{"n":17,"t":"「以东必令人惊骇；凡经过的人就受惊骇，又因她一切的灾祸嗤笑。","notes":[]},{"n":18,"t":"耶和华说：必无人住在那里，也无人在其中寄居，要像所多玛、蛾摩拉，和邻近的城邑倾覆的时候一样。","notes":[]},{"n":19,"t":"仇敌必像狮子从约旦河边的丛林上来，攻击坚固的居所。转眼之间，我要使以东人逃跑，离开这地。谁蒙拣选，我就派谁治理这地。谁能比我呢？谁能给我定规日期呢？有何牧人能在我面前站立得住呢？","notes":[]},{"n":20,"t":"你们要听耶和华攻击以东所说的谋略和他攻击提幔居民所定的旨意。仇敌定要将他们群众微弱的拉去，定要使他们的居所荒凉。","notes":[]},{"n":21,"t":"因他们仆倒的声音，地就震动。人在红海那里必听见呼喊的声音。","notes":[]},{"n":22,"t":"仇敌必如大鹰飞起，展开翅膀攻击波斯拉。到那日，以东的勇士心中疼痛如临产的妇人。」","notes":[]},{"n":23,"t":"论大马士革。哈马和亚珥拔蒙羞，因他们听见凶恶的信息就消化了。海上有忧愁，不得平静。","notes":[],"heads":["耶和华审判大马士革"]},{"n":24,"t":"大马士革发软，转身逃跑。战兢将她捉住；痛苦忧愁将她抓住，如产难的妇人一样。","notes":[]},{"n":25,"t":"我所喜乐可称赞的城，为何被撇弃了呢？","notes":[]},{"n":26,"t":"她的少年人必仆倒在街上；当那日，一切兵丁必默默无声。这是万军之耶和华说的。","notes":[]},{"n":27,"t":"我必在大马士革城中使火着起，烧灭便·哈达的宫殿。","notes":[]},{"n":28,"t":"论巴比伦王尼布甲尼撒所攻打的基达和夏琐的诸国。耶和华如此说：迦勒底人哪，起来上基达去，毁灭东方人。","notes":[],"heads":["审判基达和夏琐城"]},{"n":29,"t":"他们的帐棚和羊群都要夺去，将幔子和一切器皿，并骆驼为自己掠去。人向他们喊着说：四围都有惊吓。","notes":[]},{"n":30,"t":"耶和华说：夏琐的居民哪，要逃奔远方，住在深密处；因为巴比伦王尼布甲尼撒设计谋害你们，起意攻击你们。","notes":[]},{"n":31,"t":"耶和华说：迦勒底人哪，起来！上安逸无虑的居民那里去；他们是无门无闩、独自居住的。","notes":[]},{"n":32,"t":"他们的骆驼必成为掠物；他们众多的牲畜必成为掳物。我必将剃周围头发的人分散四方，使灾殃从四围临到他们。这是耶和华说的。","notes":["原文是风"]},{"n":33,"t":"夏琐必成为野狗的住处，永远凄凉；必无人住在那里，也无人在其中寄居。","notes":[]},{"n":34,"t":"犹大王西底家登基的时候，耶和华论以拦的话临到先知耶利米说：","notes":[],"heads":["耶和华审判以拦"]},{"n":35,"t":"「万军之耶和华如此说：我必折断以拦人的弓，就是他们为首的权力。","notes":[]},{"n":36,"t":"我要使四风从天的四方刮来，临到以拦人，将他们分散四方。这被赶散的人没有一国不到的。」","notes":["原文是风"]},{"n":37,"t":"耶和华说：「我必使以拦人在仇敌和寻索其命的人面前惊惶；我也必使灾祸，就是我的烈怒临到他们，又必使刀剑追杀他们，直到将他们灭尽。","notes":[]},{"n":38,"t":"我要在以拦设立我的宝座，从那里除灭君王和首领。这是耶和华说的。","notes":[]},{"n":39,"t":"「到末后，我还要使被掳的以拦人归回。这是耶和华说的。」","notes":[]}]},"50":{"heading":"巴比伦被占领","verses":[{"n":1,"t":"耶和华借先知耶利米论巴比伦和迦勒底人之地所说的话。","notes":[]},{"n":2,"t":"你们要在万国中传扬报告，竖立大旗；要报告，不可隐瞒，说：巴比伦被攻取，彼勒蒙羞，米罗达惊惶。巴比伦的神像都蒙羞；她的偶像都惊惶。","notes":[]},{"n":3,"t":"「因有一国从北方上来攻击她，使她的地荒凉，无人居住，连人带牲畜都逃走了。」","notes":[]},{"n":4,"t":"耶和华说：「当那日子、那时候，以色列人要和犹大人同来，随走随哭，寻求耶和华—他们的神。","notes":[],"heads":["以色列人还乡"]},{"n":5,"t":"他们必访问锡安，又面向这里，说：『来吧，你们要与耶和华联合为永远不忘的约。』","notes":[]},{"n":6,"t":"「我的百姓作了迷失的羊，牧人使他们走差路，使他们转到山上。他们从大山走到小山，竟忘了安歇之处。","notes":[]},{"n":7,"t":"凡遇见他们的，就把他们吞灭。敌人说：『我们没有罪；因他们得罪那作公义居所的耶和华，就是他们列祖所仰望的耶和华。』","notes":[]},{"n":8,"t":"「我民哪，你们要从巴比伦中逃走，从迦勒底人之地出去，要像羊群前面走的公山羊。","notes":[]},{"n":9,"t":"因我必激动联合的大国从北方上来攻击巴比伦，他们要摆阵攻击她；她必从那里被攻取。他们的箭好像善射之勇士的箭，一枝也不徒然返回。","notes":[]},{"n":10,"t":"迦勒底必成为掠物；凡掳掠她的都必心满意足。这是耶和华说的。」","notes":[]},{"n":11,"t":"抢夺我产业的啊，你们因欢喜快乐，且像踹谷撒欢的母牛犊，又像发嘶声的壮马。","notes":[],"heads":["巴比伦陷落"]},{"n":12,"t":"你们的母巴比伦就极其抱愧，生你们的必然蒙羞。她要列在诸国之末，成为旷野、旱地、沙漠。","notes":[]},{"n":13,"t":"因耶和华的忿怒，必无人居住，要全然荒凉。凡经过巴比伦的要受惊骇，又因她所遭的灾殃嗤笑。","notes":[]},{"n":14,"t":"所有拉弓的，你们要在巴比伦的四围摆阵，射箭攻击她。不要爱惜箭枝，因她得罪了耶和华。","notes":[]},{"n":15,"t":"你们要在她四围呐喊；她已经投降。外郭坍塌了，城墙拆毁了，因为这是耶和华报仇的事。你们要向巴比伦报仇；她怎样待人，也要怎样待她。","notes":[]},{"n":16,"t":"你们要将巴比伦撒种的和收割时拿镰刀的都剪除了。他们各人因怕欺压的刀剑，必归回本族，逃到本土。","notes":[]},{"n":17,"t":"「以色列是打散的羊，是被狮子赶出的。首先是亚述王将他吞灭，末后是巴比伦王尼布甲尼撒将他的骨头折断。」","notes":[],"heads":["以色列人还乡"]},{"n":18,"t":"所以万军之耶和华—以色列的神如此说：「我必罚巴比伦王和他的地，像我从前罚亚述王一样。","notes":[]},{"n":19,"t":"我必再领以色列回他的草场，他必在迦密和巴珊吃草，又在以法莲山上和基列境内得以饱足。」","notes":[]},{"n":20,"t":"耶和华说：「当那日子、那时候，虽寻以色列的罪孽，一无所有；虽寻犹大的罪恶，也无所见；因为我所留下的人，我必赦免。」","notes":[]},{"n":21,"t":"耶和华说：上去攻击米拉大翁之地，又攻击比割的居民。要追杀灭尽，照我一切所吩咐你的去行。","notes":[],"heads":["神审判巴比伦"]},{"n":22,"t":"境内有打仗和大毁灭的响声。","notes":[]},{"n":23,"t":"全地的大锤何竟砍断破坏？巴比伦在列国中何竟荒凉？","notes":[]},{"n":24,"t":"巴比伦哪，我为你设下网罗，你不知不觉被缠住。你被寻着，也被捉住；因为你与耶和华争竞。","notes":[]},{"n":25,"t":"耶和华已经开了武库，拿出他恼恨的兵器；因为主—万军之耶和华在迦勒底人之地有当做的事。","notes":[]},{"n":26,"t":"你们要从极远的边界来攻击她，开她的仓廪，将她堆如高堆，毁灭净尽，丝毫不留。","notes":[]},{"n":27,"t":"要杀她的一切牛犊，使他们下去遭遇杀戮。他们有祸了，因为追讨他们的日子已经来到。（","notes":[]},{"n":28,"t":"有从巴比伦之地逃避出来的人，在锡安扬声报告耶和华—我们的神报仇，就是为他的殿报仇。）","notes":[]},{"n":29,"t":"「招集一切弓箭手来攻击巴比伦。要在巴比伦四围安营，不要容一人逃脱，照着她所做的报应她；她怎样待人，也要怎样待她，因为她向耶和华—以色列的圣者发了狂傲。","notes":[]},{"n":30,"t":"所以她的少年人必仆倒在街上。当那日，一切兵丁必默默无声。这是耶和华说的。」","notes":[]},{"n":31,"t":"主—万军之耶和华说：你这狂傲的啊，我与你反对，因为我追讨你的日子已经来到。","notes":[]},{"n":32,"t":"狂傲的必绊跌仆倒，无人扶起。我也必使火在他的城邑中着起来，将他四围所有的尽行烧灭。","notes":[]},{"n":33,"t":"万军之耶和华如此说：「以色列人和犹大人一同受欺压；凡掳掠他们的都紧紧抓住他们，不肯释放。","notes":[]},{"n":34,"t":"他们的救赎主大有能力，万军之耶和华是他的名。他必伸清他们的冤，好使全地得平安，并搅扰巴比伦的居民。」","notes":[]},{"n":35,"t":"耶和华说：「有刀剑临到迦勒底人和巴比伦的居民，并她的首领与智慧人。","notes":[]},{"n":36,"t":"有刀剑临到矜夸的人，他们就成为愚昧；有刀剑临到她的勇士，他们就惊惶。","notes":[]},{"n":37,"t":"有刀剑临到她的马匹、车辆，和其中杂族的人民；他们必像妇女一样。有刀剑临到她的宝物，就被抢夺。","notes":[]},{"n":38,"t":"有干旱临到她的众水，就必干涸；因为这是有雕刻偶像之地，人因偶像而颠狂。","notes":[]},{"n":39,"t":"所以旷野的走兽和豺狼必住在那里，鸵鸟也住在其中，永无人烟，世世代代无人居住。」","notes":[]},{"n":40,"t":"耶和华说：「必无人住在那里，也无人在其中寄居，要像我倾覆所多玛、蛾摩拉，和邻近的城邑一样。","notes":[]},{"n":41,"t":"看哪，有一种民从北方而来，并有一大国和许多君王被激动，从地极来到。","notes":[]},{"n":42,"t":"他们拿弓和枪，性情残忍，不施怜悯；他们的声音像海浪匉訇。巴比伦城啊，他们骑马，都摆队伍如上战场的人，要攻击你。","notes":["原文是女子"]},{"n":43,"t":"巴比伦王听见他们的风声，手就发软，痛苦将他抓住，疼痛仿佛产难的妇人。","notes":[]},{"n":44,"t":"「仇敌必像狮子从约旦河边的丛林上来，攻击坚固的居所。转眼之间，我要使他们逃跑，离开这地。谁蒙拣选，我就派谁治理这地。谁能比我呢？谁能给我定规日期呢？有何牧人能在我面前站立得住呢？","notes":[]},{"n":45,"t":"你们要听耶和华攻击巴比伦所说的谋略和他攻击迦勒底人之地所定的旨意。仇敌定要将他们群众微弱的拉去，定要使他们的居所荒凉。","notes":[]},{"n":46,"t":"因巴比伦被取的声音，地就震动，人在列邦都听见呼喊的声音。」","notes":[]}]},"51":{"heading":"再审判巴比伦","verses":[{"n":1,"t":"耶和华如此说：我必使毁灭的风刮起，攻击巴比伦和住在立加米的人。","notes":[]},{"n":2,"t":"我要打发外邦人来到巴比伦，簸扬她，使她的地空虚。在她遭祸的日子，他们要周围攻击她。","notes":[]},{"n":3,"t":"拉弓的，要向拉弓的和贯甲挺身的射箭。不要怜惜她的少年人；要灭尽她的全军。","notes":[]},{"n":4,"t":"他们必在迦勒底人之地被杀仆倒，在巴比伦的街上被刺透。","notes":[]},{"n":5,"t":"以色列和犹大虽然境内充满违背以色列圣者的罪，却没有被他的神—万军之耶和华丢弃。","notes":[]},{"n":6,"t":"你们要从巴比伦中逃奔，各救自己的性命！不要陷在她的罪孽中一同灭亡；因为这是耶和华报仇的时候，他必向巴比伦施行报应。","notes":[]},{"n":7,"t":"巴比伦素来是耶和华手中的金杯，使天下沉醉；万国喝了她的酒就颠狂了。","notes":[]},{"n":8,"t":"巴比伦忽然倾覆毁坏；要为她哀号；为止她的疼痛，拿乳香或者可以治好。","notes":[]},{"n":9,"t":"我们想医治巴比伦，她却没有治好。离开她吧！我们各人归回本国；因为她受的审判通于上天，达到穹苍。","notes":[]},{"n":10,"t":"耶和华已经彰显我们的公义。来吧！我们可以在锡安报告耶和华—我们神的作为。","notes":[]},{"n":11,"t":"你们要磨尖了箭头，抓住盾牌。耶和华定意攻击巴比伦，将她毁灭，所以激动了米底亚君王的心；因这是耶和华报仇，就是为自己的殿报仇。","notes":[]},{"n":12,"t":"你们要竖立大旗，攻击巴比伦的城墙；要坚固了望台，派定守望的设下埋伏；因为耶和华指着巴比伦居民所说的话、所定的意，他已经作成。","notes":[]},{"n":13,"t":"住在众水之上多有财宝的啊，你的结局到了！你贪婪之量满了！","notes":[]},{"n":14,"t":"万军之耶和华指着自己起誓说：我必使敌人充满你，像蚂蚱一样；他们必呐喊攻击你。","notes":[]},{"n":15,"t":"耶和华用能力创造大地，用智慧建立世界，用聪明铺张穹苍。","notes":[],"heads":["颂赞神的诗歌"]},{"n":16,"t":"他一发声，空中便有多水激动；他使云雾从地极上腾。他造电随雨而闪，从他府库中带出风来。","notes":[]},{"n":17,"t":"各人都成了畜类，毫无知识。各银匠都因他的偶像羞愧；他所铸的偶像本是虚假的，其中并无气息，","notes":[]},{"n":18,"t":"都是虚无的，是迷惑人的工作，到追讨的时候，必被除灭。","notes":[]},{"n":19,"t":"雅各的分不像这些，因他是造作万有的主；以色列也是他产业的支派。万军之耶和华是他的名。","notes":[]},{"n":20,"t":"你是我争战的斧子和打仗的兵器；我要用你打碎列国，用你毁灭列邦；","notes":[],"heads":["耶和华的铁锤"]},{"n":21,"t":"用你打碎马和骑马的；用你打碎战车和坐在其上的；","notes":[]},{"n":22,"t":"用你打碎男人和女人；用你打碎老年人和少年人；用你打碎壮丁和处女；","notes":[]},{"n":23,"t":"用你打碎牧人和他的群畜；用你打碎农夫和他一对牛；用你打碎省长和副省长。","notes":[]},{"n":24,"t":"耶和华说：「我必在你们眼前报复巴比伦人和迦勒底居民在锡安所行的诸恶。」","notes":[],"heads":["惩罚巴比伦"]},{"n":25,"t":"耶和华说：你这行毁灭的山哪，就是毁灭天下的山，我与你反对。我必向你伸手，将你从山岩滚下去，使你成为烧毁的山。","notes":[]},{"n":26,"t":"人必不从你那里取石头为房角石，也不取石头为根基石；你必永远荒凉。这是耶和华说的。","notes":[]},{"n":27,"t":"要在境内竖立大旗，在各国中吹角，使列国预备攻击巴比伦，将亚拉腊、米尼、亚实基拿各国招来攻击她；又派军长来攻击她，使马匹上来如蚂蚱，","notes":[]},{"n":28,"t":"使列国和米底亚君王，与省长和副省长，并他们所管全地之人，都预备攻击她。","notes":[]},{"n":29,"t":"地必震动而瘠苦；因耶和华向巴比伦所定的旨意成立了，使巴比伦之地荒凉，无人居住。","notes":[]},{"n":30,"t":"巴比伦的勇士止息争战，藏在坚垒之中。他们的勇力衰尽，好像妇女一样。巴比伦的住处有火着起，门闩都折断了。","notes":[]},{"n":31,"t":"跑报的要彼此相遇，送信的要互相迎接，报告巴比伦王说：城的四方被攻取了，","notes":[]},{"n":32,"t":"渡口被占据了，苇塘被火烧了，兵丁也惊慌了。","notes":[]},{"n":33,"t":"万军之耶和华—以色列的神如此说：巴比伦城好像踹谷的禾场；再过片时，收割她的时候就到了。","notes":["原文是女子"]},{"n":34,"t":"以色列人说：巴比伦王尼布甲尼撒吞灭我，压碎我，使我成为空虚的器皿。他像大鱼将我吞下，用我的美物充满他的肚腹，又将我赶出去。","notes":[]},{"n":35,"t":"锡安的居民要说：巴比伦以强暴待我，损害我的身体，愿这罪归给她。耶路撒冷人要说：愿流我们血的罪归到迦勒底的居民。","notes":[]},{"n":36,"t":"所以，耶和华如此说：我必为你伸冤，为你报仇；我必使巴比伦的海枯竭，使她的泉源干涸。","notes":[],"heads":["耶和华要帮助以色列"]},{"n":37,"t":"巴比伦必成为乱堆，为野狗的住处，令人惊骇、嗤笑，并且无人居住。","notes":[]},{"n":38,"t":"他们要像少壮狮子咆哮，像小狮子吼叫。","notes":[]},{"n":39,"t":"他们火热的时候，我必为他们设摆酒席，使他们沉醉，好叫他们快乐，睡了长觉，永不醒起。这是耶和华说的。","notes":[]},{"n":40,"t":"我必使他们像羊羔、像公绵羊和公山羊下到宰杀之地。","notes":[]},{"n":41,"t":"示沙克何竟被攻取？天下所称赞的何竟被占据？巴比伦在列国中何竟变为荒场？","notes":["就是巴比伦"],"heads":["巴比伦的命运"]},{"n":42,"t":"海水涨起，漫过巴比伦；她被许多海浪遮盖。","notes":[]},{"n":43,"t":"她的城邑变为荒场、旱地、沙漠，无人居住，无人经过之地。","notes":[]},{"n":44,"t":"我必刑罚巴比伦的彼勒，使他吐出所吞的。万民必不再流归他那里；巴比伦的城墙也必坍塌了。","notes":[]},{"n":45,"t":"我的民哪，你们要从其中出去！各人拯救自己，躲避耶和华的烈怒。","notes":[]},{"n":46,"t":"你们不要心惊胆怯，也不要因境内所听见的风声惧怕；因为这年有风声传来；那年也有风声传来，境内有强暴的事，官长攻击官长。","notes":[]},{"n":47,"t":"日子将到，我必刑罚巴比伦雕刻的偶像。她全地必然抱愧；她被杀的人必在其中仆倒。","notes":[]},{"n":48,"t":"那时，天地和其中所有的，必因巴比伦欢呼，因为行毁灭的要从北方来到她那里。这是耶和华说的。","notes":[]},{"n":49,"t":"巴比伦怎样使以色列被杀的人仆倒，照样她全地被杀的人也必在巴比伦仆倒。","notes":[]},{"n":50,"t":"你们躲避刀剑的要快走，不要站住！要在远方记念耶和华，心中追想耶路撒冷。","notes":[],"heads":["给在巴比伦的以色列人的信息"]},{"n":51,"t":"我们听见辱骂就蒙羞，满面惭愧，因为外邦人进入耶和华殿的圣所。","notes":[]},{"n":52,"t":"耶和华说：日子将到，我必刑罚巴比伦雕刻的偶像，通国受伤的人必唉哼。","notes":[]},{"n":53,"t":"巴比伦虽升到天上，虽使她坚固的高处更坚固，还有行毁灭的从我这里到她那里。这是耶和华说的。","notes":[]},{"n":54,"t":"有哀号的声音从巴比伦出来；有大毁灭的响声从迦勒底人之地发出。","notes":[],"heads":["巴比伦灭亡"]},{"n":55,"t":"因耶和华使巴比伦变为荒场，使其中的大声灭绝。仇敌仿佛众水，波浪匉訇，响声已经发出。","notes":[]},{"n":56,"t":"这是行毁灭的临到巴比伦。巴比伦的勇士被捉住，他们的弓折断了；因为耶和华是施行报应的神，必定施行报应。","notes":[]},{"n":57,"t":"君王—名为万军之耶和华的说：我必使巴比伦的首领、智慧人、省长、副省长，和勇士都沉醉，使他们睡了长觉，永不醒起。","notes":[]},{"n":58,"t":"万军之耶和华如此说：巴比伦宽阔的城墙必全然倾倒；她高大的城门必被火焚烧。众民所劳碌的必致虚空；列国所劳碌的被火焚烧，他们都必困乏。","notes":[]},{"n":59,"t":"犹大王西底家在位第四年，上巴比伦去的时候，玛西雅的孙子、尼利亚的儿子西莱雅与王同去（西莱雅是王宫的大臣），先知耶利米有话吩咐他。","notes":[],"heads":["耶利米的信息传到巴比伦"]},{"n":60,"t":"耶利米将一切要临到巴比伦的灾祸，就是论到巴比伦的一切话，写在书上。","notes":[]},{"n":61,"t":"耶利米对西莱雅说：「你到了巴比伦务要念这书上的话；","notes":[]},{"n":62,"t":"又说：『耶和华啊，你曾论到这地方说：要剪除，甚至连人带牲畜没有在这里居住的，必永远荒凉。』","notes":[]},{"n":63,"t":"你念完了这书，就把一块石头拴在书上，扔在幼发拉底河中，","notes":[]},{"n":64,"t":"说：『巴比伦因耶和华所要降与她的灾祸，必如此沉下去，不再兴起，人民也必困乏。』」耶利米的话到此为止。","notes":[]}]},"52":{"heading":"耶路撒冷的陷落","verses":[{"n":1,"t":"西底家登基的时候年二十一岁，在耶路撒冷作王十一年。他母亲名叫哈慕她，是立拿人耶利米的女儿。","notes":[]},{"n":2,"t":"西底家行耶和华眼中看为恶的事，是照约雅敬一切所行的。","notes":[]},{"n":3,"t":"因此耶和华的怒气在耶路撒冷和犹大发作，以致将人民从自己的面前赶出。","notes":[]},{"n":4,"t":"西底家背叛巴比伦王。他作王第九年十月初十日，巴比伦王尼布甲尼撒率领全军来攻击耶路撒冷，对城安营，四围筑垒攻城。","notes":[]},{"n":5,"t":"于是城被围困直到西底家王十一年。","notes":[]},{"n":6,"t":"四月初九日，城里有大饥荒，甚至百姓都没有粮食。","notes":[]},{"n":7,"t":"城被攻破，一切兵丁就在夜间从靠近王园两城中间的门，出城逃跑；迦勒底人正在四围攻城。他们就往亚拉巴逃去。","notes":[]},{"n":8,"t":"迦勒底的军队追赶西底家王，在耶利哥的平原追上他。他的全军都离开他四散了。","notes":[]},{"n":9,"t":"迦勒底人就拿住王，带他到在哈马地利比拉的巴比伦王那里；巴比伦王便审判他。","notes":[]},{"n":10,"t":"巴比伦王在西底家眼前杀了他的众子，又在利比拉杀了犹大的一切首领，","notes":[]},{"n":11,"t":"并且剜了西底家的眼睛，用铜链锁着他，带到巴比伦去，将他囚在监里，直到他死的日子。","notes":[]},{"n":12,"t":"巴比伦王尼布甲尼撒十九年五月初十日，在巴比伦王面前侍立的护卫长尼布撒拉旦进入耶路撒冷，","notes":[],"heads":["圣殿毁灭"]},{"n":13,"t":"用火焚烧耶和华的殿和王宫，又焚烧耶路撒冷的房屋，就是各大户家的房屋。","notes":[]},{"n":14,"t":"跟从护卫长迦勒底的全军就拆毁耶路撒冷四围的城墙。","notes":[]},{"n":15,"t":"那时护卫长尼布撒拉旦将民中最穷的和城里所剩下的百姓，并已经投降巴比伦王的人，以及大众所剩下的人，都掳去了。","notes":[]},{"n":16,"t":"但护卫长尼布撒拉旦留下些民中最穷的，使他们修理葡萄园，耕种田地。","notes":[]},{"n":17,"t":"耶和华殿的铜柱并殿内的盆座和铜海，迦勒底人都打碎了，将那铜运到巴比伦去了，","notes":[]},{"n":18,"t":"又带去锅、铲子、蜡剪、盘子、调羹，并所用的一切铜器、","notes":[]},{"n":19,"t":"杯、火鼎、碗、盆、灯台、调羹、爵，无论金的银的，护卫长也都带去了。","notes":[]},{"n":20,"t":"所罗门为耶和华殿所造的两根铜柱、一个铜海，并座下的十二只铜牛，这一切的铜多得无法可称。","notes":[]},{"n":21,"t":"这一根柱子高十八肘，厚四指，是空的，围十二肘。","notes":[]},{"n":22,"t":"柱上有铜顶，高五肘；铜顶的周围有网子和石榴，都是铜的。那一根柱子照此一样，也有石榴。","notes":[]},{"n":23,"t":"柱子四面有九十六个石榴，在网子周围，共有一百石榴。","notes":[]},{"n":24,"t":"护卫长拿住大祭司西莱雅、副祭司西番亚，和三个把门的，","notes":[],"heads":["犹大人被掳到巴比伦"]},{"n":25,"t":"又从城中拿住一个管理兵丁的官，并在城里所遇常见王面的七个人和检点国民军长的书记，以及城里所遇见的国民六十个人。","notes":["或译：太监"]},{"n":26,"t":"护卫长尼布撒拉旦将这些人带到利比拉的巴比伦王那里。","notes":[]},{"n":27,"t":"巴比伦王就把他们击杀在哈马地的利比拉。这样，犹大人被掳去离开本地。","notes":[]},{"n":28,"t":"尼布甲尼撒所掳的民数记在下面：在他第七年掳去犹大人三千零二十三名；","notes":[]},{"n":29,"t":"尼布甲尼撒十八年从耶路撒冷掳去八百三十二人；","notes":[]},{"n":30,"t":"尼布甲尼撒二十三年，护卫长尼布撒拉旦掳去犹大人七百四十五名；共有四千六百人。","notes":[]},{"n":31,"t":"犹大王约雅斤被掳后三十七年，巴比伦王以未·米罗达元年十二月二十五日，使犹大王约雅斤抬头，提他出监，","notes":[]},{"n":32,"t":"又对他说恩言，使他的位高过与他一同在巴比伦众王的位，","notes":[]},{"n":33,"t":"给他脱了囚服。他终身在巴比伦王面前吃饭。","notes":[]},{"n":34,"t":"巴比伦王赐他所需用的食物，日日赐他一分，终身是这样，直到他死的日子。","notes":[]}]}},"LAM":{"1":{"heading":"耶路撒冷的忧患","verses":[{"n":1,"t":"先前满有人民的城，现在何竟独坐！先前在列国中为大的，现在竟如寡妇；先前在诸省中为王后的，现在成为进贡的。","notes":[]},{"n":2,"t":"她夜间痛哭，泪流满腮；在一切所亲爱的中间没有一个安慰她的。她的朋友都以诡诈待她，成为她的仇敌。","notes":[]},{"n":3,"t":"犹大因遭遇苦难，又因多服劳苦就迁到外邦。她住在列国中，寻不着安息；追逼她的都在狭窄之地将她追上。","notes":[]},{"n":4,"t":"锡安的路径因无人来守圣节就悲伤；她的城门凄凉；她的祭司叹息；她的处女受艰难，自己也愁苦。","notes":[]},{"n":5,"t":"她的敌人为首；她的仇敌亨通；因耶和华为她许多的罪过使她受苦；她的孩童被敌人掳去。","notes":[]},{"n":6,"t":"锡安城的威荣全都失去。她的首领像找不着草场的鹿；在追赶的人前无力行走。","notes":["原文是女子；下同"]},{"n":7,"t":"耶路撒冷在困苦窘迫之时，就追想古时一切的乐境。她百姓落在敌人手中，无人救济；敌人看见，就因她的荒凉嗤笑。","notes":[]},{"n":8,"t":"耶路撒冷大大犯罪，所以成为不洁之物；素来尊敬她的，见她赤露就都藐视她；她自己也叹息退后。","notes":[]},{"n":9,"t":"她的污秽是在衣襟上；她不思想自己的结局，所以非常地败落，无人安慰她。她说：耶和华啊，求你看我的苦难，因为仇敌夸大。","notes":[]},{"n":10,"t":"敌人伸手，夺取她的美物；她眼见外邦人进入她的圣所—论这外邦人，你曾吩咐不可入你的会中。","notes":[]},{"n":11,"t":"她的民都叹息，寻求食物；他们用美物换粮食，要救性命。他们说：耶和华啊，求你观看，因为我甚是卑贱。","notes":[]},{"n":12,"t":"你们一切过路的人哪，这事你们不介意吗？你们要观看：有像这临到我的痛苦没有—就是耶和华在他发烈怒的日子使我所受的苦？","notes":[]},{"n":13,"t":"他从高天使火进入我的骨头，克制了我；他铺下网罗，绊我的脚，使我转回；他使我终日凄凉发昏。","notes":[]},{"n":14,"t":"我罪过的轭是他手所绑的，犹如轭绳缚在我颈项上；他使我的力量衰败。主将我交在我所不能敌挡的人手中。","notes":[]},{"n":15,"t":"主轻弃我中间的一切勇士，招聚多人攻击我，要压碎我的少年人。主将犹大居民踹下，像在酒榨中一样。","notes":["原文是大会"]},{"n":16,"t":"我因这些事哭泣；我眼泪汪汪；因为那当安慰我、救我性命的，离我甚远。我的儿女孤苦，因为仇敌得了胜。","notes":[]},{"n":17,"t":"锡安举手，无人安慰。耶和华论雅各已经出令，使四围的人作他仇敌；耶路撒冷在他们中间像不洁之物。","notes":[]},{"n":18,"t":"耶和华是公义的！他这样待我，是因我违背他的命令。众民哪，请听我的话，看我的痛苦；我的处女和少年人都被掳去。","notes":[]},{"n":19,"t":"我招呼我所亲爱的，他们却愚弄我。我的祭司和长老正寻求食物、救性命的时候，就在城中绝气。","notes":[]},{"n":20,"t":"耶和华啊，求你观看，因为我在急难中。我心肠扰乱；我心在我里面翻转，因我大大悖逆。在外，刀剑使人丧子；在家，犹如死亡。","notes":[]},{"n":21,"t":"听见我叹息的有人；安慰我的却无人！我的仇敌都听见我所遭的患难；因你做这事，他们都喜乐。你必使你报告的日子来到，他们就像我一样。","notes":[]},{"n":22,"t":"愿他们的恶行都呈在你面前；你怎样因我的一切罪过待我，求你照样待他们；因我叹息甚多，心中发昏。","notes":[]}]},"2":{"heading":"耶和华刑罚耶路撒冷","verses":[{"n":1,"t":"主何竟发怒，使黑云遮蔽锡安城！他将以色列的华美从天扔在地上；在他发怒的日子并不记念自己的脚凳。","notes":[]},{"n":2,"t":"主吞灭雅各一切的住处，并不顾惜。他发怒倾覆犹大民的保障，使这保障坍倒在地；他辱没这国和其中的首领。","notes":[]},{"n":3,"t":"他发烈怒，把以色列的角全然砍断，在仇敌面前收回右手。他像火焰四围吞灭，将雅各烧毁。","notes":[]},{"n":4,"t":"他张弓好像仇敌；他站着举起右手，如同敌人将悦人眼目的，尽行杀戮。在锡安百姓的帐棚上倒出他的忿怒，像火一样。","notes":[]},{"n":5,"t":"主如仇敌吞灭以色列和锡安的一切宫殿，拆毁百姓的保障；在犹大民中加增悲伤哭号。","notes":[]},{"n":6,"t":"他强取自己的帐幕，好像是园中的窝棚，毁坏他的聚会之处。耶和华使圣节和安息日在锡安都被忘记，又在怒气的愤恨中藐视君王和祭司。","notes":[]},{"n":7,"t":"耶和华丢弃自己的祭坛，憎恶自己的圣所，将宫殿的墙垣交付仇敌。他们在耶和华的殿中喧嚷，像在圣会之日一样。","notes":[]},{"n":8,"t":"耶和华定意拆毁锡安的城墙；他拉了准绳，不将手收回，定要毁灭。他使外郭和城墙都悲哀，一同衰败。","notes":[]},{"n":9,"t":"锡安的门都陷入地内；主将她的门闩毁坏，折断。她的君王和首领落在没有律法的列国中；她的先知不得见耶和华的异象。","notes":[]},{"n":10,"t":"锡安城的长老坐在地上默默无声；他们扬起尘土落在头上，腰束麻布；耶路撒冷的处女垂头至地。","notes":[]},{"n":11,"t":"我眼中流泪，以致失明；我的心肠扰乱，肝胆涂地，都因我众民遭毁灭，又因孩童和吃奶的在城内街上发昏。","notes":[]},{"n":12,"t":"那时，他们在城内街上发昏，好像受伤的，在母亲的怀里，将要丧命；对母亲说：谷、酒在哪里呢？","notes":[]},{"n":13,"t":"耶路撒冷的民哪，我可用什么向你证明呢？我可用什么与你相比呢？锡安的民哪，我可拿什么和你比较，好安慰你呢？因为你的裂口大如海，谁能医治你呢？","notes":[]},{"n":14,"t":"你的先知为你见虚假和愚昧的异象，并没有显露你的罪孽，使你被掳的归回；却为你见虚假的默示和使你被赶出本境的缘故。","notes":[]},{"n":15,"t":"凡过路的都向你拍掌。他们向耶路撒冷城嗤笑，摇头，说：难道人所称为全美的，称为全地所喜悦的，就是这城吗？","notes":[]},{"n":16,"t":"你的仇敌都向你大大张口；他们嗤笑，又切齿说：我们吞灭她。这真是我们所盼望的日子临到了！我们亲眼看见了！","notes":[]},{"n":17,"t":"耶和华成就了他所定的，应验了他古时所命定的。他倾覆了，并不顾惜，使你的仇敌向你夸耀；使你敌人的角也被高举。","notes":[]},{"n":18,"t":"锡安民的心哀求主。锡安的城墙啊，愿你流泪如河，昼夜不息；愿你眼中的瞳人泪流不止。","notes":[]},{"n":19,"t":"夜间，每逢交更的时候要起来呼喊，在主面前倾心如水。你的孩童在各市口上受饿发昏；你要为他们的性命向主举手祷告。","notes":[]},{"n":20,"t":"耶和华啊，求你观看！见你向谁这样行？妇人岂可吃自己所生育手里所摇弄的婴孩吗？祭司和先知岂可在主的圣所中被杀戮吗？","notes":[]},{"n":21,"t":"少年人和老年人都在街上躺卧；我的处女和壮丁都倒在刀下；你发怒的日子杀死他们。你杀了，并不顾惜。","notes":[]},{"n":22,"t":"你招聚四围惊吓我的，像在大会的日子招聚人一样。耶和华发怒的日子，无人逃脱，无人存留。我所摇弄所养育的婴孩，仇敌都杀净了。","notes":[]}]},"3":{"heading":"刑罚、悔改、希望","verses":[{"n":1,"t":"我是因耶和华忿怒的杖，遭遇困苦的人。","notes":[]},{"n":2,"t":"他引导我，使我行在黑暗中，不行在光明里。","notes":[]},{"n":3,"t":"他真是终日再三反手攻击我。","notes":[]},{"n":4,"t":"他使我的皮肉枯干；他折断我的骨头。","notes":["或译：压伤"]},{"n":5,"t":"他筑垒攻击我，用苦楚和艰难围困我。","notes":["原文是苦胆"]},{"n":6,"t":"他使我住在幽暗之处，像死了许久的人一样。","notes":[]},{"n":7,"t":"他用篱笆围住我，使我不能出去；他使我的铜链沉重。","notes":[]},{"n":8,"t":"我哀号求救；他使我的祷告不得上达。","notes":[]},{"n":9,"t":"他用凿过的石头挡住我的道；他使我的路弯曲。","notes":[]},{"n":10,"t":"他向我如熊埋伏，如狮子在隐密处。","notes":[]},{"n":11,"t":"他使我转离正路，将我撕碎，使我凄凉。","notes":[]},{"n":12,"t":"他张弓将我当作箭靶子。","notes":[]},{"n":13,"t":"他把箭袋中的箭射入我的肺腑。","notes":[]},{"n":14,"t":"我成了众民的笑话；他们终日以我为歌曲。","notes":[]},{"n":15,"t":"他用苦楚充满我，使我饱用茵陈。","notes":[]},{"n":16,"t":"他又用沙石碜断我的牙，用灰尘将我蒙蔽。","notes":[]},{"n":17,"t":"你使我远离平安，我忘记好处。","notes":[]},{"n":18,"t":"我就说：我的力量衰败；我在耶和华那里毫无指望！","notes":[]},{"n":19,"t":"耶和华啊，求你记念我如茵陈和苦胆的困苦窘迫。","notes":[]},{"n":20,"t":"我心想念这些，就在里面忧闷。","notes":[]},{"n":21,"t":"我想起这事，心里就有指望。","notes":[]},{"n":22,"t":"我们不致消灭，是出于耶和华诸般的慈爱；是因他的怜悯不致断绝。","notes":[]},{"n":23,"t":"每早晨，这都是新的；你的诚实极其广大！","notes":[]},{"n":24,"t":"我心里说：耶和华是我的分，因此，我要仰望他。","notes":[]},{"n":25,"t":"凡等候耶和华，心里寻求他的，耶和华必施恩给他。","notes":[]},{"n":26,"t":"人仰望耶和华，静默等候他的救恩，这原是好的。","notes":[]},{"n":27,"t":"人在幼年负轭，这原是好的。","notes":[]},{"n":28,"t":"他当独坐无言，因为这是耶和华加在他身上的。","notes":[]},{"n":29,"t":"他当口贴尘埃，或者有指望。","notes":[]},{"n":30,"t":"他当由人打他的腮颊，要满受凌辱。","notes":[]},{"n":31,"t":"因为主必不永远丢弃人。","notes":[]},{"n":32,"t":"主虽使人忧愁，还要照他诸般的慈爱发怜悯。","notes":[]},{"n":33,"t":"因他并不甘心使人受苦，使人忧愁。","notes":[]},{"n":34,"t":"人将世上被囚的踹在脚下，","notes":["原文是压"]},{"n":35,"t":"或在至高者面前屈枉人，","notes":[]},{"n":36,"t":"或在人的讼事上颠倒是非，这都是主看不上的。","notes":[]},{"n":37,"t":"除非主命定，谁能说成就成呢？","notes":[]},{"n":38,"t":"祸福不都出于至高者的口吗？","notes":[]},{"n":39,"t":"活人因自己的罪受罚，为何发怨言呢？","notes":[]},{"n":40,"t":"我们当深深考察自己的行为，再归向耶和华。","notes":[]},{"n":41,"t":"我们当诚心向天上的神举手祷告。","notes":[]},{"n":42,"t":"我们犯罪背逆，你并不赦免。","notes":[]},{"n":43,"t":"你自被怒气遮蔽，追赶我们；你施行杀戮，并不顾惜。","notes":[]},{"n":44,"t":"你以黑云遮蔽自己，以致祷告不得透入。","notes":[]},{"n":45,"t":"你使我们在万民中成为污秽和渣滓。","notes":[]},{"n":46,"t":"我们的仇敌都向我们大大张口。","notes":[]},{"n":47,"t":"恐惧和陷坑，残害和毁灭，都临近我们。","notes":[]},{"n":48,"t":"因我众民遭的毁灭，我就眼泪下流如河。","notes":[]},{"n":49,"t":"我的眼多多流泪，总不止息，","notes":[]},{"n":50,"t":"直等耶和华垂顾，从天观看。","notes":[]},{"n":51,"t":"因我本城的众民，我的眼，使我的心伤痛。","notes":[]},{"n":52,"t":"无故与我为仇的追逼我，像追雀鸟一样。","notes":[]},{"n":53,"t":"他们使我的命在牢狱中断绝，并将一块石头抛在我身上。","notes":[]},{"n":54,"t":"众水流过我头，我说：我命断绝了！","notes":[]},{"n":55,"t":"耶和华啊，我从深牢中求告你的名。","notes":[]},{"n":56,"t":"你曾听见我的声音；我求你解救，你不要掩耳不听。","notes":[]},{"n":57,"t":"我求告你的日子，你临近我，说：不要惧怕！","notes":[]},{"n":58,"t":"主啊，你伸明了我的冤；你救赎了我的命。","notes":[]},{"n":59,"t":"耶和华啊，你见了我受的委屈；求你为我伸冤。","notes":[]},{"n":60,"t":"他们仇恨我，谋害我，你都看见了。","notes":[]},{"n":61,"t":"耶和华啊，你听见他们辱骂我的话，知道他们向我所设的计，","notes":[]},{"n":62,"t":"并那些起来攻击我的人口中所说的话，以及终日向我所设的计谋。","notes":[]},{"n":63,"t":"求你观看，他们坐下，起来，都以我为歌曲。","notes":[]},{"n":64,"t":"耶和华啊，你要按着他们手所做的向他们施行报应。","notes":[]},{"n":65,"t":"你要使他们心里刚硬，使你的咒诅临到他们。","notes":[]},{"n":66,"t":"你要发怒追赶他们，从耶和华的天下除灭他们。","notes":[]}]},"4":{"heading":"耶路撒冷陷落之后","verses":[{"n":1,"t":"黄金何其失光！纯金何其变色！圣所的石头倒在各市口上。","notes":[]},{"n":2,"t":"锡安宝贵的众子好比精金，现在何竟算为窑匠手所做的瓦瓶？","notes":[]},{"n":3,"t":"野狗尚且把奶乳哺其子，我民的妇人倒成为残忍，好像旷野的鸵鸟一般。","notes":[]},{"n":4,"t":"吃奶孩子的舌头因干渴贴住上膛；孩童求饼，无人擘给他们。","notes":[]},{"n":5,"t":"素来吃美好食物的，现今在街上变为孤寒；素来卧朱红褥子的，现今躺卧粪堆。","notes":[]},{"n":6,"t":"都因我众民的罪孽比所多玛的罪还大；所多玛虽然无人加手于她，还是转眼之间被倾覆。","notes":[]},{"n":7,"t":"锡安的贵胄素来比雪纯净，比奶更白；他们的身体比红宝玉更红，像光润的蓝宝石一样。","notes":["或译：珊瑚"]},{"n":8,"t":"现在他们的面貌比煤炭更黑，以致在街上无人认识；他们的皮肤紧贴骨头，枯干如同槁木。","notes":[]},{"n":9,"t":"饿死的不如被刀杀的，因为这是缺了田间的土产，就身体衰弱，渐渐消灭。","notes":[]},{"n":10,"t":"慈心的妇人，当我众民被毁灭的时候，亲手煮自己的儿女作为食物。","notes":[]},{"n":11,"t":"耶和华发怒成就他所定的，倒出他的烈怒；在锡安使火着起，烧毁锡安的根基。","notes":[]},{"n":12,"t":"地上的君王和世上的居民都不信敌人和仇敌能进耶路撒冷的城门。","notes":[]},{"n":13,"t":"这都因她先知的罪恶和祭司的罪孽；他们在城中流了义人的血。","notes":[]},{"n":14,"t":"他们在街上如瞎子乱走，又被血玷污，以致人不能摸他们的衣服。","notes":[]},{"n":15,"t":"人向他们喊着说：不洁净的，躲开，躲开！不要挨近我！他们逃走飘流的时候，列国中有人说：他们不可仍在这里寄居。","notes":[]},{"n":16,"t":"耶和华发怒，将他们分散，不再眷顾他们；人不重看祭司，也不厚待长老。","notes":[]},{"n":17,"t":"我们仰望人来帮助，以致眼目失明，还是枉然；我们所盼望的，竟盼望一个不能救人的国！","notes":[]},{"n":18,"t":"仇敌追赶我们的脚步像打猎的，以致我们不敢在自己的街上行走。我们的结局临近；我们的日子满足；我们的结局来到了。","notes":[]},{"n":19,"t":"追赶我们的比空中的鹰更快；他们在山上追逼我们，在旷野埋伏，等候我们。","notes":[]},{"n":20,"t":"耶和华的受膏者好比我们鼻中的气，在他们的坑中被捉住；我们曾论到他说：我们必在他荫下，在列国中存活。","notes":[]},{"n":21,"t":"住乌斯地的以东民哪，只管欢喜快乐；苦杯也必传到你那里；你必喝醉，以致露体。","notes":[]},{"n":22,"t":"锡安的民哪，你罪孽的刑罚受足了，耶和华必不使你再被掳去。以东的民哪，他必追讨你的罪孽，显露你的罪恶。","notes":[]}]},"5":{"heading":"求耶和华垂怜","verses":[{"n":1,"t":"耶和华啊，求你记念我们所遭遇的事，观看我们所受的凌辱。","notes":[]},{"n":2,"t":"我们的产业归与外邦人；我们的房屋归与外路人。","notes":[]},{"n":3,"t":"我们是无父的孤儿；我们的母亲好像寡妇。","notes":[]},{"n":4,"t":"我们出钱才得水喝；我们的柴是人卖给我们的。","notes":[]},{"n":5,"t":"追赶我们的，到了我们的颈项上；我们疲乏不得歇息。","notes":[]},{"n":6,"t":"我们投降埃及人和亚述人，为要得粮吃饱。","notes":[]},{"n":7,"t":"我们列祖犯罪，而今不在了；我们担当他们的罪孽。","notes":[]},{"n":8,"t":"奴仆辖制我们，无人救我们脱离他们的手。","notes":[]},{"n":9,"t":"因为旷野的刀剑，我们冒着险才得粮食。","notes":[]},{"n":10,"t":"因饥饿燥热，我们的皮肤就黑如炉。","notes":[]},{"n":11,"t":"敌人在锡安玷污妇人，在犹大的城邑玷污处女。","notes":[]},{"n":12,"t":"他们吊起首领的手，也不尊敬老人的面。","notes":[]},{"n":13,"t":"少年人扛磨石，孩童背木柴，都绊跌了。","notes":[]},{"n":14,"t":"老年人在城门口断绝；少年人不再作乐。","notes":[]},{"n":15,"t":"我们心中的快乐止息，跳舞变为悲哀。","notes":[]},{"n":16,"t":"冠冕从我们的头上落下；我们犯罪了，我们有祸了！","notes":[]},{"n":17,"t":"这些事我们心里发昏，我们的眼睛昏花。","notes":[]},{"n":18,"t":"锡安山荒凉，野狗行在其上。","notes":["或译：狐狸"]},{"n":19,"t":"耶和华啊，你存到永远；你的宝座存到万代。","notes":[]},{"n":20,"t":"你为何永远忘记我们？为何许久离弃我们？","notes":[]},{"n":21,"t":"耶和华啊，求你使我们向你回转，我们便得回转。求你复新我们的日子，像古时一样。","notes":[]},{"n":22,"t":"你竟全然弃绝我们，向我们大发烈怒？","notes":[]}]}},"EZK":{"1":{"heading":"以西结所见的第一个异象","verses":[{"n":1,"t":"当三十年四月初五日，以西结在迦巴鲁河边被掳的人中，天就开了，得见神的异象。","notes":["原文是我"],"heads":["神的宝座"]},{"n":2,"t":"正是约雅斤王被掳去第五年四月初五日，","notes":[]},{"n":3,"t":"在迦勒底人之地、迦巴鲁河边，耶和华的话特特临到布西的儿子祭司以西结；耶和华的灵降在他身上。","notes":["原文是手"]},{"n":4,"t":"我观看，见狂风从北方刮来，随着有一朵包括闪烁火的大云，周围有光辉；从其中的火内发出好像光耀的精金；","notes":[]},{"n":5,"t":"又从其中显出四个活物的形象来。他们的形状是这样：有人的形象，","notes":[]},{"n":6,"t":"各有四个脸面，四个翅膀。","notes":[]},{"n":7,"t":"他们的腿是直的，脚掌好像牛犊之蹄，都灿烂如光明的铜。","notes":[]},{"n":8,"t":"在四面的翅膀以下有人的手。这四个活物的脸和翅膀乃是这样：","notes":[]},{"n":9,"t":"翅膀彼此相接，行走并不转身，俱各直往前行。","notes":[]},{"n":10,"t":"至于脸的形象：前面各有人的脸，右面各有狮子的脸，左面各有牛的脸，后面各有鹰的脸。","notes":[]},{"n":11,"t":"各展开上边的两个翅膀相接，各以下边的两个翅膀遮体。","notes":[]},{"n":12,"t":"他们俱各直往前行。灵往哪里去，他们就往那里去，行走并不转身。","notes":[]},{"n":13,"t":"至于四活物的形象，就如烧着火炭的形状，又如火把的形状。火在四活物中间上去下来，这火有光辉，从火中发出闪电。","notes":[]},{"n":14,"t":"这活物往来奔走，好像电光一闪。","notes":[]},{"n":15,"t":"我正观看活物的时候，见活物的脸旁各有一轮在地上。","notes":[]},{"n":16,"t":"轮的形状和颜色好像水苍玉。四轮都是一个样式，形状和作法好像轮中套轮。","notes":["原文是作法"]},{"n":17,"t":"轮行走的时候，向四方都能直行，并不掉转。","notes":[]},{"n":18,"t":"至于轮辋，高而可畏；四个轮辋周围满有眼睛。","notes":[]},{"n":19,"t":"活物行走，轮也在旁边行走；活物从地上升，轮也都上升。","notes":[]},{"n":20,"t":"灵往哪里去，活物就往那里去；活物上升，轮也在活物旁边上升，因为活物的灵在轮中。","notes":[]},{"n":21,"t":"那些行走，这些也行走；那些站住，这些也站住；那些从地上升，轮也在旁边上升，因为活物的灵在轮中。","notes":[]},{"n":22,"t":"活物的头以上有穹苍的形象，看着像可畏的水晶，铺张在活物的头以上。","notes":[]},{"n":23,"t":"穹苍以下，活物的翅膀直张，彼此相对；每活物有两个翅膀遮体。","notes":[]},{"n":24,"t":"活物行走的时候，我听见翅膀的响声，像大水的声音，像全能者的声音，也像军队哄嚷的声音。活物站住的时候，便将翅膀垂下。","notes":[]},{"n":25,"t":"在他们头以上的穹苍之上有声音。他们站住的时候，便将翅膀垂下。","notes":[]},{"n":26,"t":"在他们头以上的穹苍之上有宝座的形象，仿佛蓝宝石；在宝座形象以上有仿佛人的形状。","notes":[]},{"n":27,"t":"我见从他腰以上有仿佛光耀的精金，周围都有火的形状，又见从他腰以下有仿佛火的形状，周围也有光辉。","notes":[]},{"n":28,"t":"下雨的日子，云中虹的形状怎样，周围光辉的形状也是怎样。这就是耶和华荣耀的形象。我一看见就俯伏在地，又听见一位说话的声音。","notes":[]}]},"2":{"heading":"神选召以西结作先知","verses":[{"n":1,"t":"他对我说：「人子啊，你站起来，我要和你说话。」","notes":[]},{"n":2,"t":"他对我说话的时候，灵就进入我里面，使我站起来，我便听见那位对我说话的声音。","notes":[]},{"n":3,"t":"他对我说：「人子啊，我差你往悖逆的国民以色列人那里去。他们是悖逆我的，他们和他们的列祖违背我，直到今日。","notes":[]},{"n":4,"t":"这众子面无羞耻，心里刚硬。我差你往他们那里去，你要对他们说：主耶和华如此说。","notes":[]},{"n":5,"t":"他们或听，或不听，（他们是悖逆之家），必知道在他们中间有了先知。","notes":[]},{"n":6,"t":"人子啊，虽有荆棘和蒺藜在你那里，你又住在蝎子中间，总不要怕他们，也不要怕他们的话；他们虽是悖逆之家，还不要怕他们的话，也不要因他们的脸色惊惶。","notes":[]},{"n":7,"t":"他们或听，或不听，你只管将我的话告诉他们；他们是极其悖逆的。","notes":[]},{"n":8,"t":"「人子啊，要听我对你所说的话，不要悖逆像那悖逆之家，你要开口吃我所赐给你的。」","notes":[]},{"n":9,"t":"我观看，见有一只手向我伸出来，手中有一书卷。","notes":[]},{"n":10,"t":"他将书卷在我面前展开，内外都写着字，其上所写的有哀号、叹息、悲痛的话。","notes":[]}]},"3":{"heading":"耶和华派以西结作守望者","verses":[{"n":1,"t":"他对我说：「人子啊，要吃你所得的，要吃这书卷，好去对以色列家讲说。」","notes":[]},{"n":2,"t":"于是我开口，他就使我吃这书卷，","notes":[]},{"n":3,"t":"又对我说：「人子啊，要吃我所赐给你的这书卷，充满你的肚腹。」我就吃了，口中觉得其甜如蜜。","notes":[]},{"n":4,"t":"他对我说：「人子啊，你往以色列家那里去，将我的话对他们讲说。","notes":[]},{"n":5,"t":"你奉差遣不是往那说话深奥、言语难懂的民那里去，乃是往以色列家去；","notes":[]},{"n":6,"t":"不是往那说话深奥、言语难懂的多国去，他们的话语是你不懂得的。我若差你往他们那里去，他们必听从你。","notes":[]},{"n":7,"t":"以色列家却不肯听从你，因为他们不肯听从我；原来以色列全家是额坚心硬的人。","notes":[]},{"n":8,"t":"看哪，我使你的脸硬过他们的脸，使你的额硬过他们的额。","notes":[]},{"n":9,"t":"我使你的额像金钢钻，比火石更硬。他们虽是悖逆之家，你不要怕他们，也不要因他们的脸色惊惶。」","notes":[]},{"n":10,"t":"他又对我说：「人子啊，我对你所说的一切话，要心里领会，耳中听闻。","notes":[]},{"n":11,"t":"你往你本国被掳的子民那里去，他们或听，或不听，你要对他们讲说，告诉他们这是主耶和华说的。」","notes":[]},{"n":12,"t":"那时，灵将我举起，我就听见在我身后有震动轰轰的声音，说：「从耶和华的所在显出来的荣耀是该称颂的！」","notes":[]},{"n":13,"t":"我又听见那活物翅膀相碰，与活物旁边轮子旋转震动轰轰的响声。","notes":[]},{"n":14,"t":"于是灵将我举起，带我而去。我心中甚苦，灵性忿激，并且耶和华的灵在我身上大有能力。","notes":["原文是手"]},{"n":15,"t":"我就来到提勒·亚毕，住在迦巴鲁河边被掳的人那里，到他们所住的地方，在他们中间忧忧闷闷地坐了七日。","notes":[]},{"n":16,"t":"过了七日，耶和华的话临到我说：","notes":[]},{"n":17,"t":"「人子啊，我立你作以色列家守望的人，所以你要听我口中的话，替我警戒他们。","notes":[]},{"n":18,"t":"我何时指着恶人说：他必要死；你若不警戒他，也不劝戒他，使他离开恶行，拯救他的性命，这恶人必死在罪孽之中；我却要向你讨他丧命的罪。","notes":["原文是血"]},{"n":19,"t":"倘若你警戒恶人，他仍不转离罪恶，也不离开恶行，他必死在罪孽之中，你却救自己脱离了罪。","notes":[]},{"n":20,"t":"再者，义人何时离义而犯罪，我将绊脚石放在他面前，他就必死；因你没有警戒他，他必死在罪中，他素来所行的义不被记念；我却要向你讨他丧命的罪。","notes":["原文是血"]},{"n":21,"t":"倘若你警戒义人，使他不犯罪，他就不犯罪；他因受警戒就必存活，你也救自己脱离了罪。」","notes":[]},{"n":22,"t":"耶和华的灵在那里降在我身上。他对我说：「你起来往平原去，我要在那里和你说话。」","notes":["原文是手"],"heads":["以西结暂成哑巴"]},{"n":23,"t":"于是我起来往平原去，不料，耶和华的荣耀正如我在迦巴鲁河边所见的一样，停在那里，我就俯伏于地。","notes":[]},{"n":24,"t":"灵就进入我里面，使我站起来。耶和华对我说：「你进房屋去，将门关上。","notes":[]},{"n":25,"t":"人子啊，人必用绳索捆绑你，你就不能出去在他们中间来往。","notes":[]},{"n":26,"t":"我必使你的舌头贴住上膛，以致你哑口，不能作责备他们的人；他们原是悖逆之家。","notes":[]},{"n":27,"t":"但我对你说话的时候，必使你开口，你就要对他们说：『主耶和华如此说。』听的可以听，不听的任他不听，因为他们是悖逆之家。」","notes":[]}]},"4":{"heading":"表演耶路撒冷被困","verses":[{"n":1,"t":"「人子啊，你要拿一块砖，摆在你面前，将一座耶路撒冷城画在其上，","notes":[]},{"n":2,"t":"又围困这城，造台筑垒，安营攻击，在四围安设撞锤攻城，","notes":[]},{"n":3,"t":"又要拿个铁鏊，放在你和城的中间，作为铁墙。你要对面攻击这城，使城被困；这样，好作以色列家的预兆。","notes":[]},{"n":4,"t":"「你要向左侧卧，承当以色列家的罪孽；要按你向左侧卧的日数，担当他们的罪孽。","notes":[]},{"n":5,"t":"因为我已将他们作孽的年数定为你向左侧卧的日数，就是三百九十日，你要这样担当以色列家的罪孽。","notes":[]},{"n":6,"t":"再者，你满了这些日子，还要向右侧卧，担当犹大家的罪孽。我给你定规侧卧四十日，一日顶一年。","notes":[]},{"n":7,"t":"你要露出膀臂，面向被困的耶路撒冷，说预言攻击这城。","notes":[]},{"n":8,"t":"我用绳索捆绑你，使你不能辗转，直等你满了困城的日子。","notes":[]},{"n":9,"t":"「你要取小麦、大麦、豆子、红豆、小米、粗麦，装在一个器皿中，用以为自己做饼；要按你侧卧的三百九十日吃这饼。","notes":[]},{"n":10,"t":"你所吃的要按分两吃，每日二十舍客勒，按时而吃。","notes":[]},{"n":11,"t":"你喝水也要按制子，每日喝一欣六分之一，按时而喝。","notes":[]},{"n":12,"t":"你吃这饼像吃大麦饼一样，要用人粪在众人眼前烧烤。」","notes":[]},{"n":13,"t":"耶和华说：「以色列人在我所赶他们到的各国中，也必这样吃不洁净的食物。」","notes":[]},{"n":14,"t":"我说：「哎！主耶和华啊，我素来未曾被玷污，从幼年到如今没有吃过自死的，或被野兽撕裂的，那可憎的肉也未曾入我的口。」","notes":[]},{"n":15,"t":"于是他对我说：「看哪，我给你牛粪代替人粪，你要将你的饼烤在其上。」","notes":[]},{"n":16,"t":"他又对我说：「人子啊，我必在耶路撒冷折断他们的杖，就是断绝他们的粮。他们吃饼要按分两，忧虑而吃；喝水也要按制子，惊惶而喝；","notes":[]},{"n":17,"t":"使他们缺粮缺水，彼此惊惶，因自己的罪孽消灭。」","notes":[]}]},"5":{"heading":"以西结剃发","verses":[{"n":1,"t":"「人子啊，你要拿一把快刀，当作剃头刀，用这刀剃你的头发和你的胡须，用天平将须发平分。","notes":[]},{"n":2,"t":"围困城的日子满了，你要将三分之一在城中用火焚烧，将三分之一在城的四围用刀砍碎，将三分之一任风吹散；我也要拔刀追赶。","notes":[]},{"n":3,"t":"你要从其中取几根包在衣襟里，","notes":[]},{"n":4,"t":"再从这几根中取些扔在火中焚烧，从里面必有火出来烧入以色列全家。","notes":[]},{"n":5,"t":"主耶和华如此说：这就是耶路撒冷。我曾将她安置在列邦之中；列国都在她的四围。","notes":[]},{"n":6,"t":"她行恶，违背我的典章，过于列国；干犯我的律例，过于四围的列邦，因为她弃掉我的典章。至于我的律例，她并没有遵行。","notes":[]},{"n":7,"t":"所以主耶和华如此说：因为你们纷争过于四围的列国，也不遵行我的律例，不谨守我的典章，并以遵从四围列国的恶规尚不满意，","notes":[]},{"n":8,"t":"所以主耶和华如此说：看哪，我与你反对，必在列国的眼前，在你中间，施行审判；","notes":[]},{"n":9,"t":"并且因你一切可憎的事，我要在你中间行我所未曾行的，以后我也不再照着行。","notes":[]},{"n":10,"t":"在你中间父亲要吃儿子，儿子要吃父亲。我必向你施行审判，我必将你所剩下的分散四方。」","notes":["方：原文是风"]},{"n":11,"t":"主耶和华说：「我指着我的永生起誓，因你用一切可憎的物、可厌的事玷污了我的圣所，故此，我定要使你人数减少，我眼必不顾惜你，也不可怜你。","notes":[]},{"n":12,"t":"你的民三分之一必遭瘟疫而死，在你中间必因饥荒消灭；三分之一必在你四围倒在刀下；我必将三分之一分散四方，并要拔刀追赶他们。","notes":["方：原文是风"]},{"n":13,"t":"「我要这样成就怒中所定的；我向他们发的忿怒止息了，自己就得着安慰。我在他们身上成就怒中所定的那时，他们就知道我—耶和华所说的是出于热心；","notes":[]},{"n":14,"t":"并且我必使你在四围的列国中，在经过的众人眼前，成了荒凉和羞辱。","notes":[]},{"n":15,"t":"这样，我必以怒气和忿怒，并烈怒的责备，向你施行审判。那时，你就在四围的列国中成为羞辱、讥刺、警戒、惊骇。这是我—耶和华说的。","notes":[]},{"n":16,"t":"那时，我要将灭人、使人饥荒的恶箭，就是射去灭人的，射在你们身上，并要加增你们的饥荒，断绝你们所倚靠的粮食；","notes":[]},{"n":17,"t":"又要使饥荒和恶兽到你那里，叫你丧子，瘟疫和流血的事也必盛行在你那里；我也要使刀剑临到你。这是我—耶和华说的。」","notes":[]}]},"6":{"heading":"谴责拜偶像的罪","verses":[{"n":1,"t":"耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要面向以色列的众山说预言，","notes":[]},{"n":3,"t":"说：以色列的众山哪，要听主耶和华的话。主耶和华对大山、小冈、水沟、山谷如此说：我必使刀剑临到你们，也必毁灭你们的邱坛。","notes":[]},{"n":4,"t":"你们的祭坛必然荒凉，你们的日像必被打碎。我要使你们被杀的人倒在你们的偶像面前；","notes":[]},{"n":5,"t":"我也要将以色列人的尸首放在他们的偶像面前，将你们的骸骨抛散在你们祭坛的四围。","notes":[]},{"n":6,"t":"在你们一切的住处，城邑要变为荒场，邱坛必然凄凉，使你们的祭坛荒废，将你们的偶像打碎。你们的日像被砍倒，你们的工作被毁灭。","notes":[]},{"n":7,"t":"被杀的人必倒在你们中间，你们就知道我是耶和华。","notes":[]},{"n":8,"t":"「你们分散在各国的时候，我必在列邦中使你们有剩下脱离刀剑的人。","notes":[]},{"n":9,"t":"那脱离刀剑的人必在所掳到的各国中记念我，为他们心中何等伤破，是因他们起淫心，远离我，眼对偶像行邪淫。他们因行一切可憎的恶事，必厌恶自己。","notes":[]},{"n":10,"t":"他们必知道我是耶和华；我说要使这灾祸临到他们身上，并非空话。","notes":[]},{"n":11,"t":"「主耶和华如此说：你当拍手顿足，说：哀哉！以色列家行这一切可憎的恶事，他们必倒在刀剑、饥荒、瘟疫之下。","notes":[]},{"n":12,"t":"在远处的，必遭瘟疫而死；在近处的，必倒在刀剑之下；那存留被围困的，必因饥荒而死；我必这样在他们身上成就我怒中所定的。","notes":[]},{"n":13,"t":"他们被杀的人倒在他们祭坛四围的偶像中，就是各高冈、各山顶、各青翠树下、各茂密的橡树下，乃是他们献馨香的祭牲给一切偶像的地方。那时，他们就知道我是耶和华。","notes":[]},{"n":14,"t":"我必伸手攻击他们，使他们的地从旷野到第伯拉他一切住处极其荒凉，他们就知道我是耶和华。」","notes":[]}]},"7":{"heading":"以色列的终局近了","verses":[{"n":1,"t":"耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「人子啊，主耶和华对以色列地如此说：结局到了，结局到了地的四境！","notes":[]},{"n":3,"t":"现在你的结局已经临到，我必使我的怒气归与你，也必按你的行为审判你，照你一切可憎的事刑罚你。","notes":[]},{"n":4,"t":"我眼必不顾惜你，也不可怜你，却要按你所行的报应你，照你中间可憎的事刑罚你。你就知道我是耶和华。","notes":[]},{"n":5,"t":"「主耶和华如此说：有一灾，独有一灾；看哪，临近了！","notes":[]},{"n":6,"t":"结局来了，结局来了，向你兴起。看哪，来到了！","notes":[]},{"n":7,"t":"境内的居民哪，所定的灾临到你，时候到了，日子近了，乃是哄嚷并非在山上欢呼的日子。","notes":[]},{"n":8,"t":"我快要将我的忿怒倾在你身上，向你成就我怒中所定的，按你的行为审判你，照你一切可憎的事刑罚你。","notes":[]},{"n":9,"t":"我眼必不顾惜你，也不可怜你，必按你所行的报应你，照你中间可憎的事刑罚你。你就知道击打你的是我耶和华。","notes":[]},{"n":10,"t":"「看哪，看哪，日子快到了；所定的灾已经发出！杖已经开花，骄傲已经发芽。","notes":[]},{"n":11,"t":"强暴兴起，成了罚恶的杖。以色列人，或是他们的群众，或是他们的财宝，无一存留；他们中间也没有得尊荣的。","notes":[]},{"n":12,"t":"时候到了，日子近了，买主不可欢喜，卖主不可愁烦，因为烈怒已经临到他们众人身上。","notes":[]},{"n":13,"t":"卖主虽然存活，却不能归回再得所卖的，因为这异象关乎他们众人。谁都不得归回，也没有人在他的罪孽中坚立自己。」","notes":[]},{"n":14,"t":"「他们已经吹角，预备齐全，却无一人出战，因为我的烈怒临到他们众人身上。","notes":[],"heads":["惩罚以色列的罪恶"]},{"n":15,"t":"在外有刀剑；在内有瘟疫、饥荒。在田野的，必遭刀剑而死；在城中的，必有饥荒、瘟疫吞灭他。","notes":[]},{"n":16,"t":"其中所逃脱的就必逃脱，各人因自己的罪孽在山上发出悲声，好像谷中的鸽子哀鸣。","notes":[]},{"n":17,"t":"手都发软，膝弱如水。","notes":[]},{"n":18,"t":"要用麻布束腰，被战兢所盖；各人脸上羞愧，头上光秃。","notes":[]},{"n":19,"t":"他们要将银子抛在街上，金子看如污秽之物。当耶和华发怒的日子，他们的金银不能救他们，不能使心里知足，也不能使肚腹饱满，因为这金银作了他们罪孽的绊脚石。","notes":[]},{"n":20,"t":"论到耶和华妆饰华美的殿，他建立得威严，他们却在其中制造可憎可厌的偶像，所以这殿我使他们看如污秽之物。","notes":[]},{"n":21,"t":"我必将这殿交付外邦人为掠物，交付地上的恶人为掳物；他们也必亵渎这殿。","notes":[]},{"n":22,"t":"我必转脸不顾以色列人，他们亵渎我隐密之所，强盗也必进去亵渎。","notes":[]},{"n":23,"t":"「要制造锁链；因为这地遍满流血的罪，城邑充满强暴的事。","notes":[]},{"n":24,"t":"所以，我必使列国中最恶的人来占据他们的房屋；我必使强暴人的骄傲止息，他们的圣所都要被亵渎。","notes":[]},{"n":25,"t":"毁灭临近了；他们要求平安，却无平安可得。","notes":[]},{"n":26,"t":"灾害加上灾害，风声接连风声；他们必向先知求异象，但祭司讲的律法、长老设的谋略都必断绝。","notes":[]},{"n":27,"t":"君要悲哀，王要披凄凉为衣，国民的手都发颤。我必照他们的行为待他们，按他们应得的审判他们，他们就知道我是耶和华。」","notes":[]}]},"8":{"heading":"以西结所见的第二个异象","verses":[{"n":1,"t":"第六年六月初五日，我坐在家中；犹大的众长老坐在我面前。在那里主耶和华的灵降在我身上。","notes":["原文是手"],"heads":["耶路撒冷城里的偶像崇拜"]},{"n":2,"t":"我观看，见有形象仿佛火的形状，从他腰以下的形状有火，从他腰以上有光辉的形状，仿佛光耀的精金。","notes":[]},{"n":3,"t":"他伸出仿佛一只手的样式，抓住我的一绺头发，灵就将我举到天地中间，在神的异象中，带我到耶路撒冷朝北的内院门口，在那里有触动主怒偶像的坐位，就是惹动忌邪的。","notes":[]},{"n":4,"t":"谁知，在那里有以色列神的荣耀，形状与我在平原所见的一样。","notes":[]},{"n":5,"t":"神对我说：「人子啊，你举目向北观看。」我就举目向北观看，见祭坛门的北边，在门口有这惹忌邪的偶像；","notes":[]},{"n":6,"t":"又对我说：「人子啊，以色列家所行的，就是在此行这大可憎的事，使我远离我的圣所，你看见了吗？你还要看见另有大可憎的事。」","notes":[]},{"n":7,"t":"他领我到院门口。我观看，见墙上有个窟窿。","notes":[]},{"n":8,"t":"他对我说：「人子啊，你要挖墙。」我一挖墙，见有一门。","notes":[]},{"n":9,"t":"他说：「你进去，看他们在这里所行可憎的恶事。」","notes":[]},{"n":10,"t":"我进去一看，谁知，在四面墙上画着各样爬物和可憎的走兽，并以色列家一切的偶像。","notes":[]},{"n":11,"t":"在这些像前有以色列家的七十个长老站立，沙番的儿子雅撒尼亚也站在其中。各人手拿香炉，烟云的香气上腾。","notes":[]},{"n":12,"t":"他对我说：「人子啊，以色列家的长老暗中在各人画像屋里所行的，你看见了吗？他们常说：『耶和华看不见我们；耶和华已经离弃这地。』」","notes":[]},{"n":13,"t":"他又说：「你还要看见他们另外行大可憎的事。」","notes":[]},{"n":14,"t":"他领我到耶和华殿外院朝北的门口。谁知，在那里有妇女坐着，为搭模斯哭泣。","notes":[]},{"n":15,"t":"他对我说：「人子啊，你看见了吗？你还要看见比这更可憎的事。」","notes":[]},{"n":16,"t":"他又领我到耶和华殿的内院。谁知，在耶和华的殿门口、廊子和祭坛中间，约有二十五个人背向耶和华的殿，面向东方拜日头。","notes":[]},{"n":17,"t":"他对我说：「人子啊，你看见了吗？犹大家在此行这可憎的事还算为小吗？他们在这地遍行强暴，再三惹我发怒，他们手拿枝条举向鼻前。","notes":[]},{"n":18,"t":"因此，我也要以忿怒行事，我眼必不顾惜，也不可怜他们；他们虽向我耳中大声呼求，我还是不听。」","notes":[]}]},"9":{"heading":"耶路撒冷受惩罚","verses":[{"n":1,"t":"他向我耳中大声喊叫说：「要使那监管这城的人手中各拿灭命的兵器前来。」","notes":[]},{"n":2,"t":"忽然有六个人从朝北的上门而来，各人手拿杀人的兵器；内中有一人身穿细麻衣，腰间带着墨盒子。他们进来，站在铜祭坛旁。","notes":[]},{"n":3,"t":"以色列神的荣耀本在基路伯上，现今从那里升到殿的门槛。神将那身穿细麻衣、腰间带着墨盒子的人召来。","notes":[]},{"n":4,"t":"耶和华对他说：「你去走遍耶路撒冷全城，那些因城中所行可憎之事叹息哀哭的人，画记号在额上。」","notes":[]},{"n":5,"t":"我耳中听见他对其余的人说：「要跟随他走遍全城，以行击杀。你们的眼不要顾惜，也不要可怜他们。","notes":[]},{"n":6,"t":"要将年老的、年少的，并处女、婴孩，和妇女，从圣所起全都杀尽，只是凡有记号的人不要挨近他。」于是他们从殿前的长老杀起。","notes":[]},{"n":7,"t":"他对他们说：「要污秽这殿，使院中充满被杀的人。你们出去吧！」他们就出去，在城中击杀。","notes":[]},{"n":8,"t":"他们击杀的时候，我被留下，我就俯伏在地，说：「哎！主耶和华啊，你将忿怒倾在耶路撒冷，岂要将以色列所剩下的人都灭绝吗？」","notes":[]},{"n":9,"t":"他对我说：「以色列家和犹大家的罪孽极其重大。遍地有流血的事，满城有冤屈，因为他们说：『耶和华已经离弃这地，他看不见我们。』","notes":[]},{"n":10,"t":"故此，我眼必不顾惜，也不可怜他们，要照他们所行的报应在他们头上。」","notes":[]},{"n":11,"t":"那穿细麻衣、腰间带着墨盒子的人将这事回复说：「我已经照你所吩咐的行了。」","notes":[]}]},"10":{"heading":"耶和华的荣耀离开圣城","verses":[{"n":1,"t":"我观看，见基路伯头上的穹苍之中，显出蓝宝石的形状，仿佛宝座的形象。","notes":[]},{"n":2,"t":"主对那穿细麻衣的人说：「你进去，在旋转的轮内基路伯以下，从基路伯中间将火炭取满两手，撒在城上。」我就见他进去。","notes":[]},{"n":3,"t":"那人进去的时候，基路伯站在殿的右边，云彩充满了内院。","notes":[]},{"n":4,"t":"耶和华的荣耀从基路伯那里上升，停在门槛以上；殿内满了云彩，院宇也被耶和华荣耀的光辉充满。","notes":[]},{"n":5,"t":"基路伯翅膀的响声听到外院，好像全能神说话的声音。","notes":[]},{"n":6,"t":"他吩咐那穿细麻衣的人说：「要从旋转的轮内基路伯中间取火。」那人就进去站在一个轮子旁边。","notes":[]},{"n":7,"t":"有一个基路伯从基路伯中伸手到基路伯中间的火那里，取些放在那穿细麻衣的人两手中，那人就拿出去了。","notes":[]},{"n":8,"t":"在基路伯翅膀之下，显出有人手的样式。","notes":[]},{"n":9,"t":"我又观看，见基路伯旁边有四个轮子。这基路伯旁有一个轮子，那基路伯旁有一个轮子，每基路伯都是如此；轮子的颜色仿佛水苍玉。","notes":["原文是形状"]},{"n":10,"t":"至于四轮的形状，都是一个样式，仿佛轮中套轮。","notes":[]},{"n":11,"t":"轮行走的时候，向四方都能直行，并不掉转。头向何方，他们也随向何方，行走的时候并不掉转。","notes":[]},{"n":12,"t":"他们全身，连背带手和翅膀，并轮周围都满了眼睛。这四个基路伯的轮子都是如此。","notes":[]},{"n":13,"t":"至于这些轮子，我耳中听见说是旋转的。","notes":[]},{"n":14,"t":"基路伯各有四脸：第一是基路伯的脸，第二是人的脸，第三是狮子的脸，第四是鹰的脸。","notes":[]},{"n":15,"t":"基路伯升上去了；这是我在迦巴鲁河边所见的活物。","notes":[]},{"n":16,"t":"基路伯行走，轮也在旁边行走。基路伯展开翅膀，离地上升，轮也不转离他们旁边。","notes":[]},{"n":17,"t":"那些站住，这些也站住；那些上升，这些也一同上升，因为活物的灵在轮中。","notes":[]},{"n":18,"t":"耶和华的荣耀从殿的门槛那里出去，停在基路伯以上。","notes":[]},{"n":19,"t":"基路伯出去的时候，就展开翅膀，在我眼前离地上升。轮也在他们的旁边，都停在耶和华殿的东门口。在他们以上有以色列神的荣耀。","notes":[]},{"n":20,"t":"这是我在迦巴鲁河边所见、以色列神荣耀以下的活物，我就知道他们是基路伯。","notes":[]},{"n":21,"t":"各有四个脸面，四个翅膀，翅膀以下有人手的样式。","notes":[]},{"n":22,"t":"至于他们脸的模样，并身体的形象，是我从前在迦巴鲁河边所看见的。他们俱各直往前行。","notes":[]}]},"11":{"heading":"耶路撒冷被判罪","verses":[{"n":1,"t":"灵将我举起，带到耶和华殿向东的东门。谁知，在门口有二十五个人，我见其中有民间的首领押朔的儿子雅撒尼亚和比拿雅的儿子毗拉提。","notes":[]},{"n":2,"t":"耶和华对我说：「人子啊，这就是图谋罪孽的人，在这城中给人设恶谋。","notes":[]},{"n":3,"t":"他们说：『盖房屋的时候尚未临近；这城是锅，我们是肉。』","notes":[]},{"n":4,"t":"人子啊，因此你当说预言，说预言攻击他们。」","notes":[]},{"n":5,"t":"耶和华的灵降在我身上，对我说：「你当说，耶和华如此说：以色列家啊，你们口中所说的，心里所想的，我都知道。","notes":[]},{"n":6,"t":"你们在这城中杀人增多，使被杀的人充满街道。","notes":[]},{"n":7,"t":"所以主耶和华如此说：你们杀在城中的人就是肉，这城就是锅；你们却要从其中被带出去。","notes":[]},{"n":8,"t":"你们怕刀剑，我必使刀剑临到你们。这是主耶和华说的。","notes":[]},{"n":9,"t":"我必从这城中带出你们去，交在外邦人的手中，且要在你们中间施行审判。","notes":[]},{"n":10,"t":"你们必倒在刀下；我必在以色列的境界审判你们，你们就知道我是耶和华。","notes":[]},{"n":11,"t":"这城必不作你们的锅，你们也不作其中的肉。我必在以色列的境界审判你们，","notes":[]},{"n":12,"t":"你们就知道我是耶和华；因为你们没有遵行我的律例，也没有顺从我的典章，却随从你们四围列国的恶规。」","notes":[]},{"n":13,"t":"我正说预言的时候，比拿雅的儿子毗拉提死了。于是我俯伏在地，大声呼叫说：「哎！主耶和华啊，你要将以色列剩下的人灭绝净尽吗？」","notes":[]},{"n":14,"t":"耶和华的话临到我说：","notes":[],"heads":["神对流亡者的应许"]},{"n":15,"t":"「人子啊，耶路撒冷的居民对你的弟兄、你的本族、你的亲属、以色列全家，就是对大众说：『你们远离耶和华吧！这地是赐给我们为业的。』","notes":[]},{"n":16,"t":"所以你当说：『耶和华如此说：我虽将以色列全家远远迁移到列国中，将他们分散在列邦内，我还要在他们所到的列邦，暂作他们的圣所。』","notes":[]},{"n":17,"t":"你当说：『主耶和华如此说：我必从万民中招聚你们，从分散的列国内聚集你们，又要将以色列地赐给你们。』","notes":[]},{"n":18,"t":"他们必到那里，也必从其中除掉一切可憎可厌的物。","notes":[]},{"n":19,"t":"我要使他们有合一的心，也要将新灵放在他们里面，又从他们肉体中除掉石心，赐给他们肉心，","notes":[]},{"n":20,"t":"使他们顺从我的律例，谨守遵行我的典章。他们要作我的子民，我要作他们的神。","notes":[]},{"n":21,"t":"至于那些心中随从可憎可厌之物的，我必照他们所行的报应在他们头上。这是主耶和华说的。」","notes":[]},{"n":22,"t":"于是，基路伯展开翅膀，轮子都在他们旁边；在他们以上有以色列神的荣耀。","notes":[],"heads":["神的荣耀离开耶路撒冷"]},{"n":23,"t":"耶和华的荣耀从城中上升，停在城东的那座山上。","notes":[]},{"n":24,"t":"灵将我举起，在异象中借着神的灵将我带进迦勒底地，到被掳的人那里；我所见的异象就离我上升去了。","notes":[]},{"n":25,"t":"我便将耶和华所指示我的一切事都说给被掳的人听。","notes":[]}]},"12":{"heading":"先知扮演难民","verses":[{"n":1,"t":"耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「人子啊，你住在悖逆的家中。他们有眼睛看不见，有耳朵听不见，因为他们是悖逆之家。","notes":[]},{"n":3,"t":"所以人子啊，你要预备掳去使用的物件，在白日当他们眼前从你所住的地方移到别处去；他们虽是悖逆之家，或者可以揣摩思想。","notes":[]},{"n":4,"t":"你要在白日当他们眼前带出你的物件去，好像预备掳去使用的物件。到了晚上，你要在他们眼前亲自出去，像被掳的人出去一样。","notes":[]},{"n":5,"t":"你要在他们眼前挖通了墙，从其中将物件带出去。","notes":[]},{"n":6,"t":"到天黑时，你要当他们眼前搭在肩头上带出去，并要蒙住脸看不见地，因为我立你作以色列家的预兆。」","notes":[]},{"n":7,"t":"我就照着所吩咐的去行，白日带出我的物件，好像预备掳去使用的物件。到了晚上，我用手挖通了墙。天黑的时候，就当他们眼前搭在肩头上带出去。","notes":[]},{"n":8,"t":"次日早晨，耶和华的话临到我说：","notes":[]},{"n":9,"t":"「人子啊，以色列家，就是那悖逆之家，岂不是问你说：『你做什么呢？』","notes":[]},{"n":10,"t":"你要对他们说：『主耶和华如此说：这是关乎耶路撒冷的君王和他周围以色列全家的预表。』","notes":["原文是担子"]},{"n":11,"t":"你要说：『我作你们的预兆：我怎样行，他们所遭遇的也必怎样，他们必被掳去。』","notes":[]},{"n":12,"t":"他们中间的君王也必在天黑的时候将物件搭在肩头上带出去。他们要挖通了墙，从其中带出去。他必蒙住脸，眼看不见地。","notes":[]},{"n":13,"t":"我必将我的网撒在他身上，他必在我的网罗中缠住。我必带他到迦勒底人之地的巴比伦；他虽死在那里，却看不见那地。","notes":[]},{"n":14,"t":"周围一切帮助他的和他所有的军队，我必分散四方，也要拔刀追赶他们。","notes":["方：原文是风"]},{"n":15,"t":"我将他们四散在列国、分散在列邦的时候，他们就知道我是耶和华。","notes":[]},{"n":16,"t":"我却要留下他们几个人得免刀剑、饥荒、瘟疫，使他们在所到的各国中述说他们一切可憎的事，人就知道我是耶和华。」","notes":[]},{"n":17,"t":"耶和华的话又临到我说：","notes":[],"heads":["忧虑惊惶的预兆"]},{"n":18,"t":"「人子啊，你吃饭必胆战，喝水必惶惶忧虑。","notes":[]},{"n":19,"t":"你要对这地的百姓说：主耶和华论耶路撒冷和以色列地的居民如此说，他们吃饭必忧虑，喝水必惊惶。因其中居住的众人所行强暴的事，这地必然荒废，一无所存。","notes":[]},{"n":20,"t":"有居民的城邑必变为荒场，地也必变为荒废；你们就知道我是耶和华。」","notes":[]},{"n":21,"t":"耶和华的话临到我说：","notes":[],"heads":["平凡的俗语和非凡的信息"]},{"n":22,"t":"「人子啊，在你们以色列地怎么有这俗语，说『日子迟延，一切异象都落了空』呢？","notes":[]},{"n":23,"t":"你要告诉他们说：『主耶和华如此说：我必使这俗语止息，以色列中不再用这俗语。』你却要对他们说：『日子临近，一切的异象必都应验。』","notes":[]},{"n":24,"t":"从此，在以色列家中必不再有虚假的异象和奉承的占卜。","notes":[]},{"n":25,"t":"我—耶和华说话，所说的必定成就，不再耽延。你们这悖逆之家，我所说的话必趁你们在世的日子成就。这是主耶和华说的。」","notes":[]},{"n":26,"t":"耶和华的话又临到我说：","notes":[]},{"n":27,"t":"「人子啊，以色列家的人说：『他所见的异象是关乎后来许多的日子，所说的预言是指着极远的时候。』","notes":[]},{"n":28,"t":"所以你要对他们说：『主耶和华如此说：我的话没有一句再耽延的，我所说的必定成就。这是主耶和华说的。』」","notes":[]}]},"13":{"heading":"斥责假先知","verses":[{"n":1,"t":"耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要说预言攻击以色列中说预言的先知，对那些本己心发预言的说：『你们当听耶和华的话。』」","notes":[]},{"n":3,"t":"主耶和华如此说：「愚顽的先知有祸了，他们随从自己的心意，却一无所见。","notes":[]},{"n":4,"t":"以色列啊，你的先知好像荒场中的狐狸，","notes":[]},{"n":5,"t":"没有上去堵挡破口，也没有为以色列家重修墙垣，使他们当耶和华的日子在阵上站立得住。","notes":[]},{"n":6,"t":"这些人所见的是虚假，是谎诈的占卜。他们说是耶和华说的，其实耶和华并没有差遣他们，他们倒使人指望那话必然立定。","notes":[]},{"n":7,"t":"你们岂不是见了虚假的异象吗？岂不是说了谎诈的占卜吗？你们说，这是耶和华说的，其实我没有说。」","notes":[]},{"n":8,"t":"所以主耶和华如此说：「因你们说的是虚假，见的是谎诈，我就与你们反对。这是主耶和华说的。","notes":[]},{"n":9,"t":"我的手必攻击那见虚假异象、用谎诈占卜的先知，他们必不列在我百姓的会中，不录在以色列家的册上，也不进入以色列地；你们就知道我是主耶和华。","notes":[]},{"n":10,"t":"因为他们诱惑我的百姓，说：『平安！』其实没有平安，就像有人立起墙壁，他们倒用未泡透的灰抹上。","notes":[]},{"n":11,"t":"所以你要对那些抹上未泡透灰的人说：『墙要倒塌，必有暴雨漫过。大冰雹啊，你们要降下，狂风也要吹裂这墙。』","notes":[]},{"n":12,"t":"这墙倒塌之后，人岂不问你们说：『你们抹上未泡透的灰在哪里呢？』」","notes":[]},{"n":13,"t":"所以主耶和华如此说：「我要发怒，使狂风吹裂这墙，在怒中使暴雨漫过，又发怒降下大冰雹，毁灭这墙。","notes":[]},{"n":14,"t":"我要这样拆毁你们那未泡透灰所抹的墙，拆平到地，以致根基露出，墙必倒塌，你们也必在其中灭亡；你们就知道我是耶和华。","notes":[]},{"n":15,"t":"我要这样向墙和用未泡透灰抹墙的人成就我怒中所定的，并要对你们说：『墙和抹墙的人都没有了。』","notes":[]},{"n":16,"t":"这抹墙的就是以色列的先知，他们指着耶路撒冷说预言，为这城见了平安的异象，其实没有平安。这是主耶和华说的。」","notes":[]},{"n":17,"t":"「人子啊，你要面向本民中、从己心发预言的女子说预言，攻击她们，","notes":[],"heads":["斥责假的女先知"]},{"n":18,"t":"说主耶和华如此说：『这些妇女有祸了！她们为众人的膀臂缝靠枕，给高矮之人做下垂的头巾，为要猎取人的性命。难道你们要猎取我百姓的性命，为利己将人救活吗？","notes":[]},{"n":19,"t":"你们为两把大麦，为几块饼，在我民中亵渎我，对肯听谎言的民说谎，杀死不该死的人，救活不该活的人。』」","notes":[]},{"n":20,"t":"所以主耶和华如此说：「看哪，我与你们的靠枕反对，就是你们用以猎取人、使人的性命如鸟飞的。我要将靠枕从你们的膀臂上扯去，释放你们猎取如鸟飞的人。","notes":[]},{"n":21,"t":"我也必撕裂你们下垂的头巾，救我百姓脱离你们的手，不再被猎取，落在你们手中。你们就知道我是耶和华。","notes":[]},{"n":22,"t":"我不使义人伤心，你们却以谎话使他伤心，又坚固恶人的手，使他不回头离开恶道得以救活。","notes":[]},{"n":23,"t":"你们就不再见虚假的异象，也不再行占卜的事；我必救我的百姓脱离你们的手；你们就知道我是耶和华。」","notes":[]}]},"14":{"heading":"神斥责拜偶像的罪","verses":[{"n":1,"t":"有几个以色列长老到我这里来，坐在我面前。","notes":[]},{"n":2,"t":"耶和华的话就临到我说：","notes":[]},{"n":3,"t":"「人子啊，这些人已将他们的假神接到心里，把陷于罪的绊脚石放在面前，我岂能丝毫被他们求问吗？","notes":[]},{"n":4,"t":"所以你要告诉他们：『主耶和华如此说：以色列家的人中，凡将他的假神接到心里，把陷于罪的绊脚石放在面前，又就了先知来的，我—耶和华在他所求的事上，必按他众多的假神回答他，","notes":["或译：必按他拜许多假神的罪报应他"]},{"n":5,"t":"好在以色列家的心事上捉住他们，因为他们都借着假神与我生疏。』","notes":[]},{"n":6,"t":"「所以你要告诉以色列家说：『主耶和华如此说：回头吧！离开你们的偶像，转脸莫从你们一切可憎的事。』","notes":[]},{"n":7,"t":"因为以色列家的人，或在以色列中寄居的外人，凡与我隔绝，将他的假神接到心里，把陷于罪的绊脚石放在面前，又就了先知来要为自己的事求问我的，我—耶和华必亲自回答他。","notes":[]},{"n":8,"t":"我必向那人变脸，使他作了警戒，笑谈，令人惊骇，并且我要将他从我民中剪除；你们就知道我是耶和华。","notes":[]},{"n":9,"t":"先知若被迷惑说一句预言，是我—耶和华任那先知受迷惑，我也必向他伸手，将他从我民以色列中除灭。","notes":[]},{"n":10,"t":"他们必担当自己的罪孽。先知的罪孽和求问之人的罪孽都是一样，","notes":[]},{"n":11,"t":"好使以色列家不再走迷离开我，不再因各样的罪过玷污自己，只要作我的子民，我作他们的神。这是主耶和华说的。」","notes":[]},{"n":12,"t":"耶和华的话临到我说：","notes":[],"heads":["挪亚、但以理、约伯"]},{"n":13,"t":"「人子啊，若有一国犯罪干犯我，我也向他伸手折断他们的杖，就是断绝他们的粮，使饥荒临到那地，将人与牲畜从其中剪除；","notes":[]},{"n":14,"t":"其中虽有挪亚、但以理、约伯这三人，他们只能因他们的义救自己的性命。这是主耶和华说的。","notes":[]},{"n":15,"t":"我若使恶兽经过糟践那地，使地荒凉，以致因这些兽，人都不得经过；","notes":[]},{"n":16,"t":"虽有这三人在其中，主耶和华说：我指着我的永生起誓，他们连儿带女都不能得救，只能自己得救，那地仍然荒凉。","notes":[]},{"n":17,"t":"或者我使刀剑临到那地，说：刀剑哪，要经过那地，以致我将人与牲畜从其中剪除；","notes":[]},{"n":18,"t":"虽有这三人在其中，主耶和华说：我指着我的永生起誓，他们连儿带女都不能得救，只能自己得救。","notes":[]},{"n":19,"t":"或者我叫瘟疫流行那地，使我灭命的忿怒倾在其上，好将人与牲畜从其中剪除；","notes":["原文是带血"]},{"n":20,"t":"虽有挪亚、但以理、约伯在其中，主耶和华说：我指着我的永生起誓，他们连儿带女都不能救，只能因他们的义救自己的性命。」","notes":[]},{"n":21,"t":"主耶和华如此说：「我将这四样大灾—就是刀剑、饥荒、恶兽、瘟疫降在耶路撒冷，将人与牲畜从其中剪除，岂不更重吗？","notes":[]},{"n":22,"t":"然而其中必有剩下的人，他们连儿带女必带到你们这里来，你们看见他们所行所为的，要因我降给耶路撒冷的一切灾祸，便得了安慰。","notes":[]},{"n":23,"t":"你们看见他们所行所为的，得了安慰，就知道我在耶路撒冷中所行的并非无故。这是主耶和华说的。」","notes":[]}]},"15":{"heading":"葡萄树的比喻","verses":[{"n":1,"t":"耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，葡萄树比别样树有什么强处？葡萄枝比众树枝有什么好处？","notes":[]},{"n":3,"t":"其上可以取木料做什么工用，可以取来做钉子挂什么器皿吗？","notes":[]},{"n":4,"t":"看哪，已经抛在火中当作柴烧，火既烧了两头，中间也被烧了，还有益于工用吗？","notes":[]},{"n":5,"t":"完全的时候尚且不合乎什么工用，何况被火烧坏，还能合乎什么工用吗？」","notes":[]},{"n":6,"t":"所以，主耶和华如此说：「众树以内的葡萄树，我怎样使它在火中当柴，也必照样待耶路撒冷的居民。","notes":[]},{"n":7,"t":"我必向他们变脸；他们虽从火中出来，火却要烧灭他们。我向他们变脸的时候，你们就知道我是耶和华。","notes":[]},{"n":8,"t":"我必使地土荒凉，因为他们行事干犯我。这是主耶和华说的。」","notes":[]}]},"16":{"heading":"不忠实的耶路撒冷","verses":[{"n":1,"t":"耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要使耶路撒冷知道她那些可憎的事，","notes":[]},{"n":3,"t":"说主耶和华对耶路撒冷如此说：你根本，你出世，是在迦南地；你父亲是亚摩利人，你母亲是赫人。","notes":[]},{"n":4,"t":"论到你出世的景况，在你初生的日子没有为你断脐带，也没有用水洗你，使你洁净，丝毫没有撒盐在你身上，也没有用布裹你。","notes":[]},{"n":5,"t":"谁的眼也不可怜你，为你做一件这样的事怜恤你；但你初生的日子扔在田野，是因你被厌恶。","notes":[]},{"n":6,"t":"「我从你旁边经过，见你滚在血中，就对你说：你虽在血中，仍可存活；你虽在血中，仍可存活。","notes":[]},{"n":7,"t":"我使你生长好像田间所长的，你就渐渐长大，以致极其俊美，两乳成形，头发长成，你却仍然赤身露体。","notes":[]},{"n":8,"t":"「我从你旁边经过，看见你的时候正动爱情，便用衣襟搭在你身上，遮盖你的赤体；又向你起誓，与你结盟，你就归于我。这是主耶和华说的。","notes":[]},{"n":9,"t":"那时我用水洗你，洗净你身上的血，又用油抹你。","notes":[]},{"n":10,"t":"我也使你身穿绣花衣服，脚穿海狗皮鞋，并用细麻布给你束腰，用丝绸为衣披在你身上，","notes":[]},{"n":11,"t":"又用妆饰打扮你，将镯子戴在你手上，将金链戴在你项上。","notes":[]},{"n":12,"t":"我也将环子戴在你鼻子上，将耳环戴在你耳朵上，将华冠戴在你头上。","notes":[]},{"n":13,"t":"这样，你就有金银的妆饰，穿的是细麻衣和丝绸，并绣花衣；吃的是细面、蜂蜜，并油。你也极其美貌，发达到王后的尊荣。","notes":[]},{"n":14,"t":"你美貌的名声传在列邦中，你十分美貌，是因我加在你身上的威荣。这是主耶和华说的。","notes":[]},{"n":15,"t":"「只是你仗着自己的美貌，又因你的名声就行邪淫。你纵情淫乱，使过路的任意而行。","notes":[]},{"n":16,"t":"你用衣服为自己在高处结彩，在其上行邪淫。这样的事将来必没有，也必不再行了。","notes":[]},{"n":17,"t":"你又将我所给你那华美的金银、宝器为自己制造人像，与他行邪淫；","notes":[]},{"n":18,"t":"又用你的绣花衣服给他披上，并将我的膏油和香料摆在他跟前；","notes":[]},{"n":19,"t":"又将我赐给你的食物，就是我赐给你吃的细面、油，和蜂蜜，都摆在他跟前为馨香的供物。这是主耶和华说的。","notes":[]},{"n":20,"t":"并且你将给我所生的儿女焚献给他。","notes":[]},{"n":21,"t":"你行淫乱岂是小事，竟将我的儿女杀了，使他们经火归与他吗？","notes":[]},{"n":22,"t":"你行这一切可憎和淫乱的事，并未追念你幼年赤身露体滚在血中的日子。」","notes":[]},{"n":23,"t":"「你行这一切恶事之后（主耶和华说：你有祸了！有祸了！）","notes":[],"heads":["耶路撒冷像淫妇"]},{"n":24,"t":"又为自己建造圆顶花楼，在各街上做了高台。","notes":[]},{"n":25,"t":"你在一切市口上建造高台，使你的美貌变为可憎的，又与一切过路的多行淫乱。","notes":[]},{"n":26,"t":"你也和你邻邦放纵情欲的埃及人行淫，加增你的淫乱，惹我发怒。","notes":[]},{"n":27,"t":"因此我伸手攻击你，减少你应用的粮食，又将你交给恨你的非利士众女，使她们任意待你。她们见你的淫行，为你羞耻。","notes":["众女是城邑的意思；本章下同"]},{"n":28,"t":"你因贪色无厌，又与亚述人行淫，与他们行淫之后，仍不满意，","notes":[]},{"n":29,"t":"并且多行淫乱，直到那贸易之地，就是迦勒底，你仍不满意。","notes":[]},{"n":30,"t":"「主耶和华说：你行这一切事，都是不知羞耻妓女所行的，可见你的心是何等懦弱！","notes":[]},{"n":31,"t":"因你在一切市口上建造圆顶花楼，在各街上做了高台，你却藐视赏赐，不像妓女。","notes":[]},{"n":32,"t":"哎！你这行淫的妻啊，宁肯接外人，不接丈夫。","notes":[]},{"n":33,"t":"凡妓女是得人赠送，你反倒赠送你所爱的人，贿赂他们从四围来与你行淫。","notes":[]},{"n":34,"t":"你行淫与别的妇女相反，因为不是人从你行淫；你既赠送人，人并不赠送你；所以你与别的妇女相反。」","notes":[]},{"n":35,"t":"「你这妓女啊，要听耶和华的话。","notes":[],"heads":["神审判耶路撒冷"]},{"n":36,"t":"主耶和华如此说：因你的污秽倾泄了，你与你所爱的行淫露出下体，又因你拜一切可憎的偶像，流儿女的血献给他，","notes":[]},{"n":37,"t":"我就要将你一切相欢相爱的和你一切所恨的都聚集来，从四围攻击你；又将你的下体露出，使他们看尽了。","notes":[]},{"n":38,"t":"我也要审判你，好像官长审判淫妇和流人血的妇女一样。我因忿怒忌恨，使流血的罪归到你身上。","notes":[]},{"n":39,"t":"我又要将你交在他们手中；他们必拆毁你的圆顶花楼，毁坏你的高台，剥去你的衣服，夺取你的华美宝器，留下你赤身露体。","notes":[]},{"n":40,"t":"他们也必带多人来攻击你，用石头打死你，用刀剑刺透你，","notes":[]},{"n":41,"t":"用火焚烧你的房屋，在许多妇人眼前向你施行审判。我必使你不再行淫，也不再赠送与人。","notes":[]},{"n":42,"t":"这样，我就止息向你发的忿怒，我的忌恨也要离开你，我要安静不再恼怒。","notes":[]},{"n":43,"t":"因你不追念你幼年的日子，在这一切的事上向我发烈怒，所以我必照你所行的报应在你头上，你就不再贪淫，行那一切可憎的事。这是主耶和华说的。」","notes":[]},{"n":44,"t":"「凡说俗语的必用俗语攻击你，说：『母亲怎样，女儿也怎样。』","notes":[],"heads":["有其母必有其女"]},{"n":45,"t":"你正是你母亲的女儿，厌弃丈夫和儿女；你正是你姊妹的姊妹，厌弃丈夫和儿女。你母亲是赫人，你父亲是亚摩利人。","notes":[]},{"n":46,"t":"你的姊姊是撒马利亚，她和她的众女住在你左边；你的妹妹是所多玛，她和她的众女住在你右边。","notes":[]},{"n":47,"t":"你没有效法她们的行为，也没有照她们可憎的事去做，你以那为小事，你一切所行的倒比她们更坏。","notes":[]},{"n":48,"t":"主耶和华说：我指着我的永生起誓，你妹妹所多玛与她的众女尚未行你和你众女所行的事。","notes":[]},{"n":49,"t":"看哪，你妹妹所多玛的罪孽是这样：她和她的众女都心骄气傲，粮食饱足，大享安逸，并没有扶助困苦和穷乏人的手。","notes":[]},{"n":50,"t":"她们狂傲，在我面前行可憎的事，我看见便将她们除掉。","notes":[]},{"n":51,"t":"撒马利亚没有犯你一半的罪，你行可憎的事比她更多，使你的姊妹因你所行一切可憎的事，倒显为义。","notes":[]},{"n":52,"t":"你既断定你姊妹为义，就要担当自己的羞辱；因你所犯的罪比她们更为可憎，她们就比你更显为义；你既使你的姊妹显为义，你就要抱愧担当自己的羞辱。」","notes":["为义：或译当受羞辱"]},{"n":53,"t":"「我必叫她们被掳的归回，就是叫所多玛和她的众女，撒马利亚和她的众女，并你们中间被掳的，都要归回，","notes":[],"heads":["所多玛、撒马利亚要复兴"]},{"n":54,"t":"好使你担当自己的羞辱，并因你一切所行的使她们得安慰，你就抱愧。","notes":[]},{"n":55,"t":"你的妹妹所多玛和她的众女必归回原位；撒马利亚和她的众女，你和你的众女，也必归回原位。","notes":[]},{"n":56,"t":"在你骄傲的日子，你的恶行没有显露以先，你的口就不提你的妹妹所多玛。那受了凌辱的亚兰众女和亚兰四围非利士的众女都恨恶你，藐视你。","notes":[],"end":57},{"n":58,"t":"耶和华说：你贪淫和可憎的事，你已经担当了。」","notes":[]},{"n":59,"t":"「主耶和华如此说：你这轻看誓言、背弃盟约的，我必照你所行的待你。","notes":[],"heads":["永远的约"]},{"n":60,"t":"然而我要追念在你幼年时与你所立的约，也要与你立定永约。","notes":[]},{"n":61,"t":"你接待你姊姊和你妹妹的时候，你要追念你所行的，自觉惭愧；并且我要将她们赐你为女儿，却不是按着前约。","notes":[]},{"n":62,"t":"我要坚定与你所立的约（你就知道我是耶和华），","notes":[]},{"n":63,"t":"好使你在我赦免你一切所行的时候，心里追念，自觉抱愧，又因你的羞辱就不再开口。这是主耶和华说的。」","notes":[]}]},"17":{"heading":"老鹰和葡萄树的比喻","verses":[{"n":1,"t":"耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要向以色列家出谜语，设比喻，","notes":[]},{"n":3,"t":"说主耶和华如此说：有一大鹰，翅膀大，翎毛长，羽毛丰满，彩色俱备，来到黎巴嫩，将香柏树梢拧去，","notes":[]},{"n":4,"t":"就是折去香柏树尽尖的嫩枝，叼到贸易之地，放在买卖城中；","notes":[]},{"n":5,"t":"又将以色列地的枝子栽于肥田里，插在大水旁，如插柳树，","notes":[]},{"n":6,"t":"就渐渐生长，成为蔓延矮小的葡萄树。其枝转向那鹰，其根在鹰以下，于是成了葡萄树，生出枝子，发出小枝。","notes":[]},{"n":7,"t":"「又有一大鹰，翅膀大，羽毛多。这葡萄树从栽种的畦中向这鹰弯过根来，发出枝子，好得它的浇灌。","notes":[]},{"n":8,"t":"这树栽于肥田多水的旁边，好生枝子，结果子，成为佳美的葡萄树。","notes":[]},{"n":9,"t":"你要说，主耶和华如此说：这葡萄树岂能发旺呢？鹰岂不拔出它的根来，芟除它的果子，使它枯干，使它发的嫩叶都枯干了吗？也不用大力和多民，就拔出它的根来。","notes":[]},{"n":10,"t":"葡萄树虽然栽种，岂能发旺呢？一经东风，岂不全然枯干吗？必在生长的畦中枯干了。」","notes":[]},{"n":11,"t":"耶和华的话临到我说：","notes":[],"heads":["解释比喻"]},{"n":12,"t":"「你对那悖逆之家说：你们不知道这些事是什么意思吗？你要告诉他们说，巴比伦王曾到耶路撒冷，将其中的君王和首领带到巴比伦自己那里去。","notes":[]},{"n":13,"t":"从以色列的宗室中取一人与他立约，使他发誓，并将国中有势力的人掳去，","notes":[]},{"n":14,"t":"使国低微不能自强，惟因守盟约得以存立。","notes":[]},{"n":15,"t":"他却背叛巴比伦王，打发使者往埃及去，要他们给他马匹和多民。他岂能亨通呢？行这样事的人岂能逃脱呢？他背约岂能逃脱呢？","notes":[]},{"n":16,"t":"他轻看向王所起的誓，背弃王与他所立的约。主耶和华说：我指着我的永生起誓，他定要死在立他作王、巴比伦王的京都。","notes":[]},{"n":17,"t":"敌人筑垒造台，与他打仗的时候，为要剪除多人，法老虽领大军队和大群众，还是不能帮助他。","notes":[]},{"n":18,"t":"他轻看誓言，背弃盟约，已经投降，却又做这一切的事，他必不能逃脱。」","notes":[]},{"n":19,"t":"所以主耶和华如此说：「我指着我的永生起誓，他既轻看指我所起的誓，背弃指我所立的约，我必要使这罪归在他头上。","notes":[]},{"n":20,"t":"我必将我的网撒在他身上，他必在我的网罗中缠住。我必带他到巴比伦，并要在那里因他干犯我的罪刑罚他。","notes":[]},{"n":21,"t":"他的一切军队，凡逃跑的，都必倒在刀下；所剩下的，也必分散四方。你们就知道说这话的是我—耶和华。」","notes":["方：原文是风"]},{"n":22,"t":"主耶和华如此说：「我要将香柏树梢拧去栽上，就是从尽尖的嫩枝中折一嫩枝，栽于极高的山上；","notes":[],"heads":["神对将来的应许"]},{"n":23,"t":"在以色列高处的山栽上。它就生枝子，结果子，成为佳美的香柏树，各类飞鸟都必宿在其下，就是宿在枝子的荫下。","notes":[]},{"n":24,"t":"田野的树木都必知道我—耶和华使高树矮小，矮树高大；青树枯干，枯树发旺。我—耶和华如此说，也如此行了。」","notes":[]}]},"18":{"heading":"","verses":[{"n":1,"t":"耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「你们在以色列地怎么用这俗语说『父亲吃了酸葡萄，儿子的牙酸倒了』呢？」","notes":[]},{"n":3,"t":"主耶和华说：「我指着我的永生起誓，你们在以色列中，必不再有用这俗语的因由。","notes":[]},{"n":4,"t":"看哪，世人都是属我的；为父的怎样属我，为子的也照样属我；犯罪的，他必死亡。","notes":[]},{"n":5,"t":"「人若是公义，且行正直与合理的事：","notes":[]},{"n":6,"t":"未曾在山上吃过祭偶像之物，未曾仰望以色列家的偶像，未曾玷污邻舍的妻，未曾在妇人的经期内亲近她，","notes":[]},{"n":7,"t":"未曾亏负人，乃将欠债之人的当头还给他；未曾抢夺人的物件，却将食物给饥饿的人吃，将衣服给赤身的人穿；","notes":[]},{"n":8,"t":"未曾向借钱的弟兄取利，也未曾向借粮的弟兄多要，缩手不作罪孽，在两人之间，按至理判断；","notes":[]},{"n":9,"t":"遵行我的律例，谨守我的典章，按诚实行事—这人是公义的，必定存活。这是主耶和华说的。","notes":[]},{"n":10,"t":"「他若生一个儿子，作强盗，是流人血的，不行以上所说之善，反行其中之恶，乃在山上吃过祭偶像之物，并玷污邻舍的妻，","notes":[],"end":11},{"n":12,"t":"亏负困苦和穷乏的人，抢夺人的物，未曾将当头还给人，仰望偶像，并行可憎的事，","notes":[]},{"n":13,"t":"向借钱的弟兄取利，向借粮的弟兄多要—这人岂能存活呢？他必不能存活。他行这一切可憎的事，必要死亡，他的罪必归到他身上。","notes":["原文是血"]},{"n":14,"t":"「他若生一个儿子，见父亲所犯的一切罪便惧怕，不照样去做；","notes":["有古卷：思量"]},{"n":15,"t":"未曾在山上吃过祭偶像之物，未曾仰望以色列家的偶像，未曾玷污邻舍的妻，","notes":[]},{"n":16,"t":"未曾亏负人，未曾取人的当头，未曾抢夺人的物件，却将食物给饥饿的人吃，将衣服给赤身的人穿，","notes":[]},{"n":17,"t":"缩手不害贫穷人，未曾向借钱的弟兄取利，也未曾向借粮的弟兄多要；他顺从我的典章，遵行我的律例，就不因父亲的罪孽死亡，定要存活。","notes":[]},{"n":18,"t":"至于他父亲；因为欺人太甚，抢夺弟兄，在本国的民中行不善，他必因自己的罪孽死亡。","notes":[]},{"n":19,"t":"「你们还说：『儿子为何不担当父亲的罪孽呢？』儿子行正直与合理的事，谨守遵行我的一切律例，他必定存活。","notes":[]},{"n":20,"t":"惟有犯罪的，他必死亡。儿子必不担当父亲的罪孽，父亲也不担当儿子的罪孽。义人的善果必归自己，恶人的恶报也必归自己。","notes":[]},{"n":21,"t":"「恶人若回头离开所做的一切罪恶，谨守我一切的律例，行正直与合理的事，他必定存活，不致死亡。","notes":[]},{"n":22,"t":"他所犯的一切罪过都不被记念，因所行的义，他必存活。","notes":[]},{"n":23,"t":"主耶和华说：恶人死亡，岂是我喜悦的吗？不是喜悦他回头离开所行的道存活吗？","notes":[]},{"n":24,"t":"义人若转离义行而作罪孽，照着恶人所行一切可憎的事而行，他岂能存活吗？他所行的一切义都不被记念；他必因所犯的罪、所行的恶死亡。","notes":[]},{"n":25,"t":"「你们还说：『主的道不公平！』以色列家啊，你们当听，我的道岂不公平吗？你们的道岂不是不公平吗？","notes":[]},{"n":26,"t":"义人若转离义行而作罪孽死亡，他是因所作的罪孽死亡。","notes":[]},{"n":27,"t":"再者，恶人若回头离开所行的恶，行正直与合理的事，他必将性命救活了。","notes":[]},{"n":28,"t":"因为他思量，回头离开所犯的一切罪过，必定存活，不致死亡。","notes":[]},{"n":29,"t":"以色列家还说：『主的道不公平！』以色列家啊，我的道岂不公平吗？你们的道岂不是不公平吗？」","notes":[]},{"n":30,"t":"所以主耶和华说：「以色列家啊，我必按你们各人所行的审判你们。你们当回头离开所犯的一切罪过。这样，罪孽必不使你们败亡。","notes":[]},{"n":31,"t":"你们要将所犯的一切罪过尽行抛弃，自做一个新心和新灵。以色列家啊，你们何必死亡呢？","notes":[]},{"n":32,"t":"主耶和华说：我不喜悦那死人之死，所以你们当回头而存活。」","notes":[]}]},"19":{"heading":"挽歌","verses":[{"n":1,"t":"你当为以色列的王作起哀歌，","notes":[]},{"n":2,"t":"说：你的母亲是什么呢？是个母狮子，蹲伏在狮子中间，在少壮狮子中养育小狮子。","notes":[]},{"n":3,"t":"在它小狮子中养大一个，成了少壮狮子，学会抓食而吃人。","notes":[]},{"n":4,"t":"列国听见了就把它捉在他们的坑中，用钩子拉到埃及地去。","notes":[]},{"n":5,"t":"母狮见自己等候失了指望，就从它小狮子中又将一个养为少壮狮子。","notes":[]},{"n":6,"t":"它在众狮子中走来走去，成了少壮狮子，学会抓食而吃人。","notes":[]},{"n":7,"t":"它知道列国的宫殿，又使他们的城邑变为荒场；因它咆哮的声音，遍地和其中所有的就都荒废。","notes":[]},{"n":8,"t":"于是四围邦国各省的人来攻击它，将网撒在它身上，捉在他们的坑中。","notes":[]},{"n":9,"t":"他们用钩子钩住它，将它放在笼中，带到巴比伦王那里，将它放入坚固之所，使它的声音在以色列山上不再听见。","notes":[]},{"n":10,"t":"你的母亲先前如葡萄树，极其茂盛，栽于水旁。因为水多，就多结果子，满生枝子；","notes":["原文是在你血中"]},{"n":11,"t":"生出坚固的枝干，可作掌权者的杖。这枝干高举在茂密的枝中，而且它生长高大，枝子繁多，远远可见。","notes":[]},{"n":12,"t":"但这葡萄树因忿怒被拔出摔在地上；东风吹干其上的果子，坚固的枝干折断枯干，被火烧毁了；","notes":[]},{"n":13,"t":"如今栽于旷野干旱无水之地。","notes":[]},{"n":14,"t":"火也从它枝干中发出，烧灭果子，以致没有坚固的枝干可做掌权者的杖。这是哀歌，也必用以作哀歌。","notes":[]}]},"20":{"heading":"神的旨意，人的抗命","verses":[{"n":1,"t":"第七年五月初十日，有以色列的几个长老来求问耶和华，坐在我面前。","notes":[]},{"n":2,"t":"耶和华的话临到我说：","notes":[]},{"n":3,"t":"「人子啊，你要告诉以色列的长老说，主耶和华如此说：你们来是求问我吗？主耶和华说：我指着我的永生起誓，我必不被你们求问。","notes":[]},{"n":4,"t":"人子啊，你要审问审问他们吗？你当使他们知道他们列祖那些可憎的事，","notes":[]},{"n":5,"t":"对他们说，主耶和华如此说：当日我拣选以色列，向雅各家的后裔起誓，在埃及地将自己向他们显现，说：我是耶和华—你们的神。","notes":[]},{"n":6,"t":"那日我向他们起誓，必领他们出埃及地，到我为他们察看的流奶与蜜之地；那地在万国中是有荣耀的。","notes":[]},{"n":7,"t":"我对他们说，你们各人要抛弃眼所喜爱那可憎之物，不可因埃及的偶像玷污自己。我是耶和华—你们的神。","notes":[]},{"n":8,"t":"他们却悖逆我，不肯听从我，不抛弃他们眼所喜爱那可憎之物，不离弃埃及的偶像。「我就说，我要将我的忿怒倾在他们身上，在埃及地向他们成就我怒中所定的。","notes":[]},{"n":9,"t":"我却为我名的缘故没有这样行，免得我名在他们所住的列国人眼前被亵渎；我领他们出埃及地，在这列国人的眼前将自己向他们显现。","notes":[]},{"n":10,"t":"这样，我就使他们出埃及地，领他们到旷野，","notes":[]},{"n":11,"t":"将我的律例赐给他们，将我的典章指示他们；人若遵行就必因此活着。","notes":[]},{"n":12,"t":"又将我的安息日赐给他们，好在我与他们中间为证据，使他们知道我—耶和华是叫他们成为圣的。","notes":[]},{"n":13,"t":"以色列家却在旷野悖逆我，不顺从我的律例，厌弃我的典章（人若遵行就必因此活着），大大干犯我的安息日。「我就说，要在旷野将我的忿怒倾在他们身上，灭绝他们。","notes":[]},{"n":14,"t":"我却为我名的缘故，没有这样行，免得我的名在我领他们出埃及的列国人眼前被亵渎。","notes":[]},{"n":15,"t":"并且我在旷野向他们起誓，必不领他们进入我所赐给他们流奶与蜜之地（那地在万国中是有荣耀的）；","notes":[]},{"n":16,"t":"因为他们厌弃我的典章，不顺从我的律例，干犯我的安息日，他们的心随从自己的偶像。","notes":[]},{"n":17,"t":"虽然如此，我眼仍顾惜他们，不毁灭他们，不在旷野将他们灭绝净尽。","notes":[]},{"n":18,"t":"「我在旷野对他们的儿女说：不要遵行你们父亲的律例，不要谨守他们的恶规，也不要因他们的偶像玷污自己。","notes":[]},{"n":19,"t":"我是耶和华—你们的神，你们要顺从我的律例，谨守遵行我的典章，","notes":[]},{"n":20,"t":"且以我的安息日为圣。这日在我与你们中间为证据，使你们知道我是耶和华—你们的神。","notes":[]},{"n":21,"t":"只是他们的儿女悖逆我，不顺从我的律例，也不谨守遵行我的典章（人若遵行就必因此活着），干犯我的安息日。「我就说，要将我的忿怒倾在他们身上，在旷野向他们成就我怒中所定的。","notes":[]},{"n":22,"t":"虽然如此，我却为我名的缘故缩手没有这样行，免得我的名在我领他们出埃及的列国人眼前被亵渎。","notes":[]},{"n":23,"t":"并且我在旷野向他们起誓，必将他们分散在列国，四散在列邦；","notes":[]},{"n":24,"t":"因为他们不遵行我的典章，竟厌弃我的律例，干犯我的安息日，眼目仰望他们父亲的偶像。","notes":[]},{"n":25,"t":"我也任他们遵行不美的律例，谨守不能使人活着的恶规。","notes":[]},{"n":26,"t":"因他们将一切头生的经火，我就任凭他们在这供献的事上玷污自己，好叫他们凄凉，使他们知道我是耶和华。","notes":[]},{"n":27,"t":"「人子啊，你要告诉以色列家说，主耶和华如此说：你们的列祖在得罪我的事上亵渎我；","notes":[]},{"n":28,"t":"因为我领他们到了我起誓应许赐给他们的地，他们看见各高山、各茂密树，就在那里献祭，奉上惹我发怒的供物，也在那里焚烧馨香的祭牲，并浇上奠祭。","notes":[]},{"n":29,"t":"我就对他们说：你们所上的那高处叫什么呢？（那高处的名字叫巴麻直到今日。）","notes":[]},{"n":30,"t":"所以你要对以色列家说，主耶和华如此说：你们仍照你们列祖所行的玷污自己吗？仍照他们可憎的事行邪淫吗？","notes":[]},{"n":31,"t":"你们奉上供物使你们儿子经火的时候，仍将一切偶像玷污自己，直到今日吗？以色列家啊，我岂被你们求问吗？主耶和华说：我指着我的永生起誓，我必不被你们求问。","notes":[]},{"n":32,"t":"「你们说：我们要像外邦人和列国的宗族一样，去事奉木头与石头。你们所起的这心意万不能成就。」","notes":[]},{"n":33,"t":"主耶和华说：「我指着我的永生起誓，我总要作王，用大能的手和伸出来的膀臂，并倾出来的忿怒，治理你们。","notes":[],"heads":["神的惩罚和赦免"]},{"n":34,"t":"我必用大能的手和伸出来的膀臂，并倾出来的忿怒，将你们从万民中领出来，从分散的列国内聚集你们。","notes":[]},{"n":35,"t":"我必带你们到外邦人的旷野，在那里当面刑罚你们。","notes":[]},{"n":36,"t":"我怎样在埃及地的旷野刑罚你们的列祖，也必照样刑罚你们。这是主耶和华说的。","notes":[]},{"n":37,"t":"我必使你们从杖下经过，使你们被约拘束。","notes":[]},{"n":38,"t":"我必从你们中间除净叛逆和得罪我的人，将他们从所寄居的地方领出来，他们却不得入以色列地。你们就知道我是耶和华。","notes":[]},{"n":39,"t":"「以色列家啊，至于你们，主耶和华如此说：从此以后若不听从我，就任凭你们去事奉偶像，只是不可再因你们的供物和偶像亵渎我的圣名。","notes":[]},{"n":40,"t":"「主耶和华说：在我的圣山，就是以色列高处的山，所有以色列的全家都要事奉我。我要在那里悦纳你们，向你们要供物和初熟的土产，并一切的圣物。","notes":[]},{"n":41,"t":"我从万民中领你们出来，从分散的列国内聚集你们，那时我必悦纳你们好像馨香之祭，要在外邦人眼前在你们身上显为圣。","notes":[]},{"n":42,"t":"我领你们进入以色列地，就是我起誓应许赐给你们列祖之地，那时你们就知道我是耶和华。","notes":[]},{"n":43,"t":"你们在那里要追念玷污自己的行动作为，又要因所做的一切恶事厌恶自己。","notes":[]},{"n":44,"t":"主耶和华说：以色列家啊，我为我名的缘故，不照着你们的恶行和你们的坏事待你们；你们就知道我是耶和华。」","notes":[]},{"n":45,"t":"耶和华的话临到我说：","notes":[],"heads":["南方大火"]},{"n":46,"t":"「人子啊，你要面向南方，向南滴下预言攻击南方田野的树林。","notes":[]},{"n":47,"t":"对南方的树林说，要听耶和华的话。主耶和华如此说：我必使火在你中间着起，烧灭你中间的一切青树和枯树，猛烈的火焰必不熄灭。从南到北，人的脸面都被烧焦。","notes":[]},{"n":48,"t":"凡有血气的都必知道是我—耶和华使火着起，这火必不熄灭。」","notes":[]},{"n":49,"t":"于是我说：「哎！主耶和华啊，人都指着我说：他岂不是说比喻的吗？」","notes":[]}]},"21":{"heading":"耶和华的刀","verses":[{"n":1,"t":"耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要面向耶路撒冷和圣所滴下预言，攻击以色列地。","notes":[]},{"n":3,"t":"对以色列地说，耶和华如此说：我与你为敌，并要拔刀出鞘，从你中间将义人和恶人一并剪除。","notes":[]},{"n":4,"t":"我既要从你中间剪除义人和恶人，所以我的刀要出鞘，自南至北攻击一切有血气的；","notes":[]},{"n":5,"t":"一切有血气的就知道我—耶和华已经拔刀出鞘，必不再入鞘。","notes":[]},{"n":6,"t":"人子啊，你要叹息，在他们眼前弯着腰，苦苦地叹息。","notes":[]},{"n":7,"t":"他们问你说：『为何叹息呢？』你就说：『因为有风声、灾祸要来。人心都必消化，手都发软，精神衰败，膝弱如水。看哪，这灾祸临近，必然成就。这是主耶和华说的。』」","notes":[]},{"n":8,"t":"耶和华的话临到我说：","notes":[]},{"n":9,"t":"「人子啊，你要预言。耶和华吩咐我如此说：有刀、有刀，是磨快擦亮的；","notes":[]},{"n":10,"t":"磨快为要行杀戮，擦亮为要像闪电。我们岂可快乐吗？罚我子的杖藐视各树。","notes":[]},{"n":11,"t":"这刀已经交给人擦亮，为要应手使用。这刀已经磨快擦亮，好交在行杀戮的人手中。","notes":[]},{"n":12,"t":"人子啊，你要呼喊哀号，因为这刀临到我的百姓和以色列一切的首领。他们和我的百姓都交在刀下，所以你要拍腿叹息。","notes":[]},{"n":13,"t":"有试验的事；若那藐视的杖归于无有，怎么样呢？这是主耶和华说的。","notes":[]},{"n":14,"t":"「人子啊，你要拍掌预言。我—耶和华要使这刀，就是致死伤的刀，一连三次加倍刺人，进入他们的内屋，使大人受死伤的就是这刀。","notes":[]},{"n":15,"t":"我设立这恐吓人的刀，攻击他们的一切城门，使他们的心消化，加增他们跌倒的事。哎！这刀造得像闪电，磨得尖利，要行杀戮。","notes":[]},{"n":16,"t":"刀啊，你归在右边，摆在左边；你面向哪方，就向那方杀戮。","notes":[]},{"n":17,"t":"我也要拍掌，并要使我的忿怒止息。这是我—耶和华说的。」","notes":[]},{"n":18,"t":"耶和华的话又临到我说：","notes":[],"heads":["巴比伦王的刀"]},{"n":19,"t":"「人子啊，你要定出两条路，好使巴比伦王的刀来。这两条路必从一地分出来，又要在通城的路口上画出一只手来。","notes":[]},{"n":20,"t":"你要定出一条路，使刀来到亚扪人的拉巴；又要定出一条路，使刀来到犹大的坚固城耶路撒冷。","notes":[]},{"n":21,"t":"因为巴比伦王站在岔路那里，在两条路口上要占卜。他摇签求问神像，察看牺牲的肝；","notes":["原文是箭"]},{"n":22,"t":"在右手中拿着为耶路撒冷占卜的签，使他安设撞城锤，张口叫杀，扬声呐喊，筑垒造台，以撞城锤，攻打城门。","notes":[]},{"n":23,"t":"据那些曾起誓的犹大人看来，这是虚假的占卜；但巴比伦王要使他们想起罪孽，以致将他们捉住。」","notes":[]},{"n":24,"t":"主耶和华如此说：「因你们的过犯显露，使你们的罪孽被记念，以致你们的罪恶在行为上都彰显出来；又因你们被记念，就被捉住。","notes":[]},{"n":25,"t":"你这受死伤行恶的以色列王啊，罪孽的尽头到了，受报的日子已到。","notes":[]},{"n":26,"t":"主耶和华如此说：当除掉冠，摘下冕，景况必不再像先前；要使卑者升为高，使高者降为卑。","notes":[]},{"n":27,"t":"我要将这国倾覆，倾覆，而又倾覆；这国也必不再有，直等到那应得的人来到，我就赐给他。」","notes":[]},{"n":28,"t":"「人子啊，要发预言说：主耶和华论到亚扪人和他们的凌辱，吩咐我如此说：有刀，有拔出来的刀，已经擦亮，为行杀戮，使他像闪电以行吞灭。","notes":[],"heads":["刀和亚扪人"]},{"n":29,"t":"人为你见虚假的异象，行谎诈的占卜，使你倒在受死伤之恶人的颈项上。他们罪孽到了尽头，受报的日子已到。","notes":[]},{"n":30,"t":"你将刀收入鞘吧！在你受造之处、生长之地，我必刑罚你。","notes":[]},{"n":31,"t":"我必将我的恼恨倒在你身上，将我烈怒的火喷在你身上；又将你交在善于杀灭的畜类人手中。","notes":[]},{"n":32,"t":"你必当柴被火焚烧；你的血必流在国中。你必不再被记念，因为这是我—耶和华说的。」","notes":[]}]},"22":{"heading":"耶路撒冷的过犯","verses":[{"n":1,"t":"耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要审问审问这流人血的城吗？当使她知道她一切可憎的事。","notes":[]},{"n":3,"t":"你要说，主耶和华如此说：哎！这城有流人血的事在其中，叫她受报的日期来到，又做偶像玷污自己，陷害自己。","notes":[]},{"n":4,"t":"你因流了人的血，就为有罪；你做了偶像，就玷污自己，使你受报之日临近，报应之年来到。所以我叫你受列国的凌辱和列邦的讥诮。","notes":[]},{"n":5,"t":"你这名臭、多乱的城啊，那些离你近、离你远的都必讥诮你。","notes":[]},{"n":6,"t":"「看哪，以色列的首领各逞其能，在你中间流人之血。","notes":[]},{"n":7,"t":"在你中间有轻慢父母的，有欺压寄居的，有亏负孤儿寡妇的。","notes":[]},{"n":8,"t":"你藐视了我的圣物，干犯了我的安息日。","notes":[]},{"n":9,"t":"在你中间有谗谤人、流人血的；有在山上吃过祭偶像之物的，有行淫乱的。","notes":[]},{"n":10,"t":"在你中间有露继母下体羞辱父亲的，有玷辱月经不洁净之妇人的。","notes":[]},{"n":11,"t":"这人与邻舍的妻行可憎的事；那人贪淫玷污儿妇；还有玷辱同父之姊妹的。","notes":[]},{"n":12,"t":"在你中间有为流人血受贿赂的；有向借钱的弟兄取利，向借粮的弟兄多要的。且因贪得无厌，欺压邻舍夺取财物，竟忘了我。这是主耶和华说的。","notes":[]},{"n":13,"t":"「看哪，我因你所得不义之财和你中间所流的血，就拍掌叹息。","notes":[]},{"n":14,"t":"到了我惩罚你的日子，你的心还能忍受吗？你的手还能有力吗？我—耶和华说了这话，就必照着行。","notes":[]},{"n":15,"t":"我必将你分散在列国，四散在列邦。我也必从你中间除掉你的污秽。","notes":[]},{"n":16,"t":"你必在列国人的眼前因自己所行的被亵渎，你就知道我是耶和华。」","notes":[]},{"n":17,"t":"耶和华的话临到我说：","notes":[],"heads":["神的大炼炉"]},{"n":18,"t":"「人子啊，以色列家在我看为渣滓。他们都是炉中的铜、锡、铁、铅，都是银渣滓。","notes":[]},{"n":19,"t":"所以主耶和华如此说：因你们都成为渣滓，我必聚集你们在耶路撒冷中。","notes":[]},{"n":20,"t":"人怎样将银、铜、铁、铅、锡聚在炉中，吹火熔化；照样，我也要发怒气和忿怒，将你们聚集放在城中，熔化你们。","notes":[]},{"n":21,"t":"我必聚集你们，把我烈怒的火吹在你们身上，你们就在其中熔化。","notes":[]},{"n":22,"t":"银子怎样熔化在炉中，你们也必照样熔化在城中，你们就知道我—耶和华是将忿怒倒在你们身上了。」","notes":[]},{"n":23,"t":"耶和华的话临到我说：","notes":[],"heads":["以色列领袖们的罪恶"]},{"n":24,"t":"「人子啊，你要对这地说：你是未得洁净之地，在恼恨的日子也没有雨下在你以上。","notes":[]},{"n":25,"t":"其中的先知同谋背叛，如咆哮的狮子抓撕掠物。他们吞灭人民，抢夺财宝，使这地多有寡妇。","notes":[]},{"n":26,"t":"其中的祭司强解我的律法，亵渎我的圣物，不分别圣的和俗的，也不使人分辨洁净的和不洁净的，又遮眼不顾我的安息日；我也在他们中间被亵慢。","notes":[]},{"n":27,"t":"其中的首领仿佛豺狼抓撕掠物，杀人流血，伤害人命，要得不义之财。","notes":[]},{"n":28,"t":"其中的先知为百姓用未泡透的灰抹墙，就是为他们见虚假的异象，用谎诈的占卜，说：『主耶和华如此说』，其实耶和华没有说。","notes":[]},{"n":29,"t":"国内众民一味地欺压，惯行抢夺，亏负困苦穷乏的，背理欺压寄居的。","notes":[]},{"n":30,"t":"我在他们中间寻找一人重修墙垣，在我面前为这国站在破口防堵，使我不灭绝这国，却找不着一个。","notes":[]},{"n":31,"t":"所以我将恼恨倒在他们身上，用烈怒的火灭了他们，照他们所行的报应在他们头上。这是主耶和华说的。」","notes":[]}]},"23":{"heading":"两个犯罪的姊妹","verses":[{"n":1,"t":"耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「人子啊，有两个女子，是一母所生，","notes":[]},{"n":3,"t":"她们在埃及行邪淫，在幼年时行邪淫。她们在那里作处女的时候，有人拥抱她们的怀，抚摸她们的乳。","notes":[]},{"n":4,"t":"她们的名字，姊姊名叫阿荷拉，妹妹名叫阿荷利巴。她们都归于我，生了儿女。论到她们的名字，阿荷拉就是撒马利亚，阿荷利巴就是耶路撒冷。","notes":[]},{"n":5,"t":"「阿荷拉归我之后行邪淫，贪恋所爱的人，就是她的邻邦亚述人。","notes":[]},{"n":6,"t":"这些人都穿蓝衣，作省长、副省长，都骑着马，是可爱的少年人。","notes":[]},{"n":7,"t":"阿荷拉就与亚述人中最美的男子放纵淫行，她因所恋爱之人的一切偶像，玷污自己。","notes":[]},{"n":8,"t":"自从在埃及的时候，她就没有离开淫乱，因为她年幼作处女的时候，埃及人与她行淫，抚摸她的乳，纵欲与她行淫。","notes":[]},{"n":9,"t":"因此，我将她交在她所爱的人手中，就是她所恋爱的亚述人手中。","notes":[]},{"n":10,"t":"他们就露了她的下体，掳掠她的儿女，用刀杀了她，使她在妇女中留下臭名，因他们向她施行审判。","notes":[]},{"n":11,"t":"「她妹妹阿荷利巴虽然看见了，却还贪恋，比她姊姊更丑；行淫乱比她姊姊更多。","notes":[]},{"n":12,"t":"她贪恋邻邦的亚述人，就是穿极华美的衣服，骑着马的省长、副省长，都是可爱的少年人。","notes":[]},{"n":13,"t":"我看见她被玷污了，她姊妹二人同行一路。","notes":[]},{"n":14,"t":"阿荷利巴又加增淫行，因她看见人像画在墙上，就是用丹色所画迦勒底人的像，","notes":[]},{"n":15,"t":"腰间系着带子，头上有下垂的裹头巾，都是军长的形状，仿照巴比伦人的形象；他们的故土就是迦勒底。","notes":[]},{"n":16,"t":"阿荷利巴一看见就贪恋他们，打发使者往迦勒底去见他们。","notes":[]},{"n":17,"t":"巴比伦人就来登她爱情的床，与她行淫玷污她。她被玷污，随后心里与他们生疏。","notes":[]},{"n":18,"t":"这样，她显露淫行，又显露下体；我心就与她生疏，像先前与她姊姊生疏一样。","notes":[]},{"n":19,"t":"她还加增她的淫行，追念她幼年在埃及地行邪淫的日子，","notes":[]},{"n":20,"t":"贪恋情人身壮精足，如驴如马。","notes":[]},{"n":21,"t":"这样，你就想起你幼年的淫行。那时，埃及人拥抱你的怀，抚摸你的乳。」","notes":[]},{"n":22,"t":"阿荷利巴啊，主耶和华如此说：「我必激动你先爱而后生疏的人来攻击你。我必使他们来，在你四围攻击你。","notes":[],"heads":["神审判妹妹"]},{"n":23,"t":"所来的就是巴比伦人、迦勒底的众人、比割人、书亚人、哥亚人，同着他们的还有亚述众人，乃是作省长、副省长、作军长有名声的，都骑着马，是可爱的少年人。","notes":[]},{"n":24,"t":"他们必带兵器、战车、辎重车，率领大众来攻击你。他们要拿大小盾牌，顶盔摆阵，在你四围攻击你。我要将审判的事交给他们，他们必按着自己的条例审判你。","notes":[]},{"n":25,"t":"我必以忌恨攻击你；他们必以忿怒办你。他们必割去你的鼻子和耳朵；你遗留的人必倒在刀下。他们必掳去你的儿女；你所遗留的必被火焚烧。","notes":["或译：余剩；下同"]},{"n":26,"t":"他们必剥去你的衣服，夺取你华美的宝器。","notes":[]},{"n":27,"t":"这样，我必使你的淫行和你从埃及地染来的淫乱止息了，使你不再仰望亚述，也不再追念埃及。","notes":[]},{"n":28,"t":"主耶和华如此说：我必将你交在你所恨恶的人手中，就是你心与他生疏的人手中。","notes":[]},{"n":29,"t":"他们必以恨恶办你，夺取你一切劳碌得来的，留下你赤身露体。你淫乱的下体，连你的淫行，带你的淫乱，都被显露。","notes":[]},{"n":30,"t":"人必向你行这些事；因为你随从外邦人行邪淫，被他们的偶像玷污了。","notes":[]},{"n":31,"t":"你走了你姊姊所走的路，所以我必将她的杯交在你手中。」","notes":[]},{"n":32,"t":"主耶和华如此说：你必喝你姊姊所喝的杯；那杯又深又广，盛得甚多，使你被人嗤笑讥刺。","notes":[]},{"n":33,"t":"你必酩酊大醉，满有愁苦，喝干你姊姊撒马利亚的杯，就是令人惊骇凄凉的杯。","notes":[]},{"n":34,"t":"你必喝这杯，以致喝尽。杯破又啃杯片，撕裂自己的乳；因为这事我曾说过。这是主耶和华说的。","notes":[]},{"n":35,"t":"主耶和华如此说：「因你忘记我，将我丢在背后，所以你要担当你淫行和淫乱的报应。」","notes":[]},{"n":36,"t":"耶和华又对我说：「人子啊，你要审问阿荷拉与阿荷利巴吗？当指出她们所行可憎的事。","notes":[],"heads":["神审判两姊妹"]},{"n":37,"t":"她们行淫，手中有杀人的血，又与偶像行淫，并使她们为我所生的儿女经火烧给偶像。","notes":[]},{"n":38,"t":"此外，她们还有向我所行的，就是同日玷污我的圣所，干犯我的安息日。","notes":[]},{"n":39,"t":"她们杀了儿女献与偶像，当天又入我的圣所，将圣所亵渎了。她们在我殿中所行的乃是如此。","notes":[]},{"n":40,"t":"「况且你们二妇打发使者去请远方人。使者到他们那里，他们就来了。你们为他们沐浴己身，粉饰眼目，佩戴妆饰，","notes":[]},{"n":41,"t":"坐在华美的床上，前面摆设桌案，将我的香料膏油摆在其上。","notes":[]},{"n":42,"t":"在那里有群众安逸欢乐的声音，并有粗俗的人和酒徒从旷野同来，把镯子戴在二妇的手上，把华冠戴在她们的头上。","notes":[]},{"n":43,"t":"「我论这行淫衰老的妇人说：现在人还要与她行淫，她也要与人行淫。","notes":[]},{"n":44,"t":"人与阿荷拉，并阿荷利巴二淫妇苟合，好像与妓女苟合。","notes":[]},{"n":45,"t":"必有义人，照审判淫妇和流人血的妇人之例，审判她们；因为她们是淫妇，手中有杀人的血。」","notes":[]},{"n":46,"t":"主耶和华如此说：「我必使多人来攻击她们，使她们抛来抛去，被人抢夺。","notes":[]},{"n":47,"t":"这些人必用石头打死她们，用刀剑杀害她们，又杀戮她们的儿女，用火焚烧她们的房屋。","notes":[]},{"n":48,"t":"这样，我必使淫行从境内止息，好叫一切妇人都受警戒，不效法你们的淫行。","notes":[]},{"n":49,"t":"人必照着你们的淫行报应你们；你们要担当拜偶像的罪，就知道我是主耶和华。」","notes":[]}]},"24":{"heading":"生锈的锅","verses":[{"n":1,"t":"第九年十月初十日，耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「人子啊，今日正是巴比伦王就近耶路撒冷的日子，你要将这日记下，","notes":[]},{"n":3,"t":"要向这悖逆之家设比喻说，主耶和华如此说：将锅放在火上，放好了，就倒水在其中；","notes":[]},{"n":4,"t":"将肉块，就是一切肥美的肉块、腿，和肩都聚在其中，拿美好的骨头把锅装满；","notes":[]},{"n":5,"t":"取羊群中最好的，将柴堆在锅下，使锅开滚，好把骨头煮在其中。","notes":[]},{"n":6,"t":"「主耶和华如此说：祸哉！这流人血的城，就是长锈的锅。其中的锈未曾除掉，须要将肉块从其中一一取出来，不必为它拈阄。","notes":[]},{"n":7,"t":"城中所流的血倒在净光的磐石上，不倒在地上，用土掩盖。","notes":[]},{"n":8,"t":"这城中所流的血倒在净光的磐石上，不得掩盖，乃是出于我，为要发忿怒施行报应。","notes":[]},{"n":9,"t":"所以主耶和华如此说：祸哉！这流人血的城，我也必大堆火柴，","notes":[]},{"n":10,"t":"添上木柴，使火着旺，将肉煮烂，把汤熬浓，使骨头烤焦；","notes":[]},{"n":11,"t":"把锅倒空坐在炭火上，使锅烧热，使铜烧红，熔化其中的污秽，除净其上的锈。","notes":[]},{"n":12,"t":"这锅劳碌疲乏，所长的大锈仍未除掉；这锈就是用火也不能除掉。","notes":[]},{"n":13,"t":"在你污秽中有淫行，我洁净你，你却不洁净。你的污秽再不能洁净，直等我向你发的忿怒止息。","notes":[]},{"n":14,"t":"我—耶和华说过的必定成就，必照话而行，必不返回，必不顾惜，也不后悔。人必照你的举动行为审判你。这是主耶和华说的。」","notes":[]},{"n":15,"t":"耶和华的话又临到我说：","notes":[],"heads":["先知妻子的死"]},{"n":16,"t":"「人子啊，我要将你眼目所喜爱的忽然取去，你却不可悲哀哭泣，也不可流泪，","notes":[]},{"n":17,"t":"只可叹息，不可出声，不可办理丧事；头上仍勒裹头巾，脚上仍穿鞋，不可蒙着嘴唇，也不可吃吊丧的食物。」","notes":[]},{"n":18,"t":"于是我将这事早晨告诉百姓，晚上我的妻就死了。次日早晨我便遵命而行。","notes":[]},{"n":19,"t":"百姓问我说：「你这样行与我们有什么关系，你不告诉我们吗？」","notes":[]},{"n":20,"t":"我回答他们：「耶和华的话临到我说：","notes":[]},{"n":21,"t":"『你告诉以色列家，主耶和华如此说：我必使我的圣所，就是你们势力所夸耀、眼里所喜爱、心中所爱惜的被亵渎，并且你们所遗留的儿女必倒在刀下。","notes":[]},{"n":22,"t":"那时，你们必行我仆人所行的，不蒙着嘴唇，也不吃吊丧的食物。","notes":[]},{"n":23,"t":"你们仍要头上勒裹头巾，脚上穿鞋；不可悲哀哭泣。你们必因自己的罪孽相对叹息，渐渐消灭。","notes":[]},{"n":24,"t":"以西结必这样为你们作预兆；凡他所行的，你们也必照样行。那事来到，你们就知道我是主耶和华。』","notes":[]},{"n":25,"t":"「人子啊，我除掉他们所倚靠、所欢喜的荣耀，并眼中所喜爱、心里所重看的儿女。","notes":[]},{"n":26,"t":"那日逃脱的人岂不来到你这里，使你耳闻这事吗？","notes":[]},{"n":27,"t":"你必向逃脱的人开口说话，不再哑口。你必这样为他们作预兆，他们就知道我是耶和华。」","notes":[]}]},"25":{"heading":"预言亚扪受惩罚","verses":[{"n":1,"t":"耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要面向亚扪人说预言，攻击他们，","notes":[]},{"n":3,"t":"说：你们当听主耶和华的话。主耶和华如此说：我的圣所被亵渎，以色列地变荒凉，犹大家被掳掠；那时，你便因这些事说：『阿哈！』","notes":[]},{"n":4,"t":"所以我必将你的地交给东方人为业；他们必在你的地上安营居住，吃你的果子，喝你的奶。","notes":[]},{"n":5,"t":"我必使拉巴为骆驼场，使亚扪人的地为羊群躺卧之处，你们就知道我是耶和华。」","notes":[]},{"n":6,"t":"主耶和华如此说：「因你拍手顿足，以满心的恨恶向以色列地欢喜，","notes":[]},{"n":7,"t":"所以我伸手攻击你，将你交给列国作为掳物。我必从万民中剪除你，使你从万国中败亡。我必除灭你，你就知道我是耶和华。」","notes":[]},{"n":8,"t":"主耶和华如此说：「因摩押和西珥人说：『看哪，犹大家与列国无异』，","notes":[],"heads":["斥责摩押"]},{"n":9,"t":"所以我要破开摩押边界上的城邑，就是摩押人看为本国之荣耀的伯·耶西末、巴力·免、基列亭，","notes":[]},{"n":10,"t":"好使东方人来攻击亚扪人。我必将亚扪人之地交给他们为业，使亚扪人在列国中不再被记念。","notes":[]},{"n":11,"t":"我必向摩押施行审判，他们就知道我是耶和华。」","notes":[]},{"n":12,"t":"主耶和华如此说：「因为以东报仇雪恨，攻击犹大家，向他们报仇，大大有罪，","notes":[],"heads":["斥责以东"]},{"n":13,"t":"所以主耶和华如此说：我必伸手攻击以东，剪除人与牲畜，使以东从提幔起，人必倒在刀下，地要变为荒凉，直到底但。","notes":[]},{"n":14,"t":"我必借我民以色列的手报复以东；以色列民必照我的怒气，按我的忿怒在以东施报，以东人就知道是我施报。这是主耶和华说的。」","notes":[]},{"n":15,"t":"主耶和华如此说：「因非利士人向犹大人报仇，就是以恨恶的心报仇雪恨，永怀仇恨，要毁灭他们，","notes":[],"heads":["斥责非利士"]},{"n":16,"t":"所以主耶和华如此说：我必伸手攻击非利士人，剪除基利提人，灭绝沿海剩下的居民。","notes":[]},{"n":17,"t":"我向他们大施报应，发怒斥责他们。我报复他们的时候，他们就知道我是耶和华。」","notes":[]}]},"26":{"heading":"斥责泰尔","verses":[{"n":1,"t":"第十一年十一月初一日，耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，因泰尔向耶路撒冷说：『阿哈，那作众民之门的已经破坏，向我开放；她既变为荒场，我必丰盛。』","notes":[]},{"n":3,"t":"所以，主耶和华如此说：泰尔啊，我必与你为敌，使许多国民上来攻击你，如同海使波浪涌上来一样。","notes":[]},{"n":4,"t":"他们必破坏泰尔的墙垣，拆毁她的城楼。我也要刮净尘土，使她成为净光的磐石。","notes":[]},{"n":5,"t":"她必在海中作晒网的地方，也必成为列国的掳物。这是主耶和华说的。","notes":[]},{"n":6,"t":"属泰尔城邑的居民必被刀剑杀灭，他们就知道我是耶和华。」","notes":["原文是田间的众女；八节同"]},{"n":7,"t":"主耶和华如此说：「我必使诸王之王的巴比伦王尼布甲尼撒率领马匹车辆、马兵、军队，和许多人民从北方来攻击你泰尔。","notes":[]},{"n":8,"t":"他必用刀剑杀灭属你城邑的居民，也必造台筑垒举盾牌攻击你。","notes":[]},{"n":9,"t":"他必安设撞城锤攻破你的墙垣，用铁器拆毁你的城楼。","notes":[]},{"n":10,"t":"因他的马匹众多，尘土扬起遮蔽你。他进入你的城门，好像人进入已有破口之城。那时，你的墙垣必因骑马的和战车、辎重车的响声震动。","notes":[]},{"n":11,"t":"他的马蹄必践踏你一切的街道；他必用刀杀戮你的居民。你坚固的柱子必倒在地上。","notes":["或译：柱像"]},{"n":12,"t":"人必以你的财宝为掳物，以你的货财为掠物，破坏你的墙垣，拆毁你华美的房屋，将你的石头、木头、尘土都抛在水中。","notes":[]},{"n":13,"t":"我必使你唱歌的声音止息；人也不再听见你弹琴的声音。","notes":[]},{"n":14,"t":"我必使你成为净光的磐石，作晒网的地方。你不得再被建造，因为这是主耶和华说的。」","notes":[]},{"n":15,"t":"主耶和华对泰尔如此说：「在你中间行杀戮，受伤之人唉哼的时候，因你倾倒的响声，海岛岂不都震动吗？","notes":[]},{"n":16,"t":"那时靠海的君王必都下位，除去朝服，脱下花衣，披上战兢，坐在地上，时刻发抖，为你惊骇。","notes":[]},{"n":17,"t":"他们必为你作起哀歌说：你这有名之城，素为航海之人居住，在海上为最坚固的；平日你和居民使一切住在那里的人无不惊恐；现在何竟毁灭了？","notes":[]},{"n":18,"t":"如今在你这倾覆的日子，海岛都必战兢；海中的群岛见你归于无有就都惊惶。」","notes":[]},{"n":19,"t":"主耶和华如此说：「泰尔啊，我使你变为荒凉，如无人居住的城邑；又使深水漫过你，大水淹没你。","notes":[]},{"n":20,"t":"那时，我要叫你下入阴府，与古时的人一同在地的深处、久已荒凉之地居住，使你不再有居民。我也要在活人之地显荣耀。","notes":["我也<ins>.</ins>.荣耀：或译在活人之地不再有荣耀"]},{"n":21,"t":"我必叫你令人惊恐，不再存留于世；人虽寻找你，却永寻不见。这是主耶和华说的。」","notes":[]}]},"27":{"heading":"哀悼泰尔的挽歌","verses":[{"n":1,"t":"耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「人子啊，要为泰尔作起哀歌，","notes":[]},{"n":3,"t":"说：你居住海口，是众民的商埠；你的交易通到许多的海岛。主耶和华如此说：泰尔啊，你曾说：我是全然美丽的。","notes":[]},{"n":4,"t":"你的境界在海中，造你的使你全然美丽。","notes":[]},{"n":5,"t":"他们用示尼珥的松树做你的一切板，用黎巴嫩的香柏树做桅杆，","notes":[]},{"n":6,"t":"用巴珊的橡树做你的桨，用象牙镶嵌基提海岛的黄杨木为坐板。","notes":["或译：舱板"]},{"n":7,"t":"你的篷帆是用埃及绣花细麻布做的，可以做你的大旗；你的凉棚是用以利沙岛的蓝色、紫色布做的。","notes":[]},{"n":8,"t":"西顿和亚发的居民作你荡桨的。泰尔啊，你中间的智慧人作掌舵的。","notes":[]},{"n":9,"t":"迦巴勒的老者和聪明人都在你中间作补缝的；一切泛海的船只和水手都在你中间经营交易的事。","notes":[]},{"n":10,"t":"「波斯人、路德人、弗人在你军营中作战士；他们在你中间悬挂盾牌和头盔，彰显你的尊荣。","notes":[]},{"n":11,"t":"亚发人和你的军队都在你四围的墙上，你的望楼也有勇士；他们悬挂盾牌，成全你的美丽。","notes":[]},{"n":12,"t":"「他施人因你多有各类的财物，就作你的客商，拿银、铁、锡、铅兑换你的货物。","notes":[]},{"n":13,"t":"雅完人、土巴人、米设人都与你交易；他们用人口和铜器兑换你的货物。","notes":[]},{"n":14,"t":"陀迦玛族用马和战马并骡子兑换你的货物。","notes":[]},{"n":15,"t":"底但人与你交易，许多海岛作你的码头；他们拿象牙、乌木与你兑换。","notes":["或译：进贡"]},{"n":16,"t":"亚兰人因你的工作很多，就作你的客商；他们用绿宝石、紫色布绣货、细麻布、珊瑚、红宝石兑换你的货物。","notes":[]},{"n":17,"t":"犹大和以色列地的人都与你交易；他们用米匿的麦子、饼、蜜、油、乳香兑换你的货物。","notes":[]},{"n":18,"t":"大马士革人因你的工作很多，又因你多有各类的财物，就拿黑本酒和白羊毛与你交易。","notes":[]},{"n":19,"t":"威但人和雅完人拿纺成的线、亮铁、桂皮、菖蒲兑换你的货物。","notes":[]},{"n":20,"t":"底但人用高贵的毯子、鞍、屉与你交易。","notes":[]},{"n":21,"t":"阿拉伯人和基达的一切首领都作你的客商，用羊羔、公绵羊、公山羊与你交易。","notes":[]},{"n":22,"t":"示巴和拉玛的商人与你交易，他们用各类上好的香料、各类的宝石，和黄金兑换你的货物。","notes":[]},{"n":23,"t":"哈兰人、干尼人、伊甸人、示巴的商人，和亚述人、基抹人与你交易。","notes":[]},{"n":24,"t":"这些商人以美好的货物包在绣花蓝色包袱内，又有华丽的衣服装在香柏木的箱子里，用绳捆着与你交易。","notes":[]},{"n":25,"t":"他施的船只接连成帮为你运货，你便在海中丰富极其荣华。","notes":[]},{"n":26,"t":"荡桨的已经把你荡到大水之处，东风在海中将你打破。","notes":[]},{"n":27,"t":"你的资财、物件、货物、水手、掌舵的、补缝的、经营交易的，并你中间的战士和人民，在你破坏的日子必都沉在海中。","notes":[]},{"n":28,"t":"你掌舵的呼号之声一发，郊野都必震动。","notes":[]},{"n":29,"t":"凡荡桨的和水手，并一切泛海掌舵的，都必下船登岸。","notes":[]},{"n":30,"t":"他们必为你放声痛哭，把尘土撒在头上，在灰中打滚；","notes":[]},{"n":31,"t":"又为你使头上光秃，用麻布束腰，号咷痛哭，苦苦悲哀。","notes":[]},{"n":32,"t":"他们哀号的时候，为你作起哀歌哀哭，说：有何城如泰尔？有何城如她在海中成为寂寞的呢？","notes":[]},{"n":33,"t":"你由海上运出货物，就使许多国民充足；你以许多资财、货物使地上的君王丰富。","notes":[]},{"n":34,"t":"你在深水中被海浪打破的时候，你的货物和你中间的一切人民，就都沉下去了。","notes":[]},{"n":35,"t":"海岛的居民为你惊奇；他们的君王都甚恐慌，面带愁容。","notes":[]},{"n":36,"t":"各国民中的客商都向你发嘶声；你令人惊恐，不再存留于世，直到永远。」","notes":[]}]},"28":{"heading":"斥责泰尔王","verses":[{"n":1,"t":"耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「人子啊，你对泰尔君王说，主耶和华如此说：因你心里高傲，说：我是神；我在海中坐神之位。你虽然居心自比神，也不过是人，并不是神！","notes":[]},{"n":3,"t":"看哪，你比但以理更有智慧，什么秘事都不能向你隐藏。","notes":[]},{"n":4,"t":"你靠自己的智慧聪明得了金银财宝，收入库中。","notes":[]},{"n":5,"t":"你靠自己的大智慧和贸易增添资财，又因资财心里高傲。","notes":[]},{"n":6,"t":"所以主耶和华如此说：因你居心自比神，","notes":[]},{"n":7,"t":"我必使外邦人，就是列国中的强暴人临到你这里；他们必拔刀砍坏你用智慧得来的美物，亵渎你的荣光。","notes":[]},{"n":8,"t":"他们必使你下坑；你必死在海中，与被杀的人一样。","notes":[]},{"n":9,"t":"在杀你的人面前你还能说「我是神」吗？其实你在杀害你的人手中，不过是人，并不是神。","notes":[]},{"n":10,"t":"你必死在外邦人手中，与未受割礼的人一样，因为这是主耶和华说的。」","notes":["或译：不洁；下同"]},{"n":11,"t":"耶和华的话临到我说：","notes":[],"heads":["泰尔王的终局"]},{"n":12,"t":"「人子啊，你为泰尔王作起哀歌，说主耶和华如此说：你无所不备，智慧充足，全然美丽。","notes":[]},{"n":13,"t":"你曾在伊甸神的园中，佩戴各样宝石，就是红宝石、红璧玺、金钢石、水苍玉、红玛瑙、碧玉、蓝宝石、绿宝石、红玉，和黄金；又有精美的鼓笛在你那里，都是在你受造之日预备齐全的。","notes":[]},{"n":14,"t":"你是那受膏遮掩约柜的基路伯；我将你安置在神的圣山上；你在发光如火的宝石中间往来。","notes":[]},{"n":15,"t":"你从受造之日所行的都完全，后来在你中间又察出不义。","notes":[]},{"n":16,"t":"因你贸易很多，就被强暴的事充满，以致犯罪，所以我因你亵渎圣地，就从神的山驱逐你。遮掩约柜的基路伯啊，我已将你从发光如火的宝石中除灭。","notes":[]},{"n":17,"t":"你因美丽心中高傲，又因荣光败坏智慧，我已将你摔倒在地，使你倒在君王面前，好叫他们目睹眼见。","notes":[]},{"n":18,"t":"你因罪孽众多，贸易不公，就亵渎你那里的圣所。故此，我使火从你中间发出，烧灭你，使你在所有观看的人眼前变为地上的炉灰。","notes":[]},{"n":19,"t":"各国民中，凡认识你的，都必为你惊奇。你令人惊恐，不再存留于世，直到永远。」","notes":[]},{"n":20,"t":"耶和华的话临到我说：","notes":[],"heads":["斥责西顿"]},{"n":21,"t":"「人子啊，你要向西顿预言攻击她，","notes":[]},{"n":22,"t":"说主耶和华如此说：西顿哪，我与你为敌，我必在你中间得荣耀。我在你中间施行审判、显为圣的时候，人就知道我是耶和华。","notes":[]},{"n":23,"t":"我必使瘟疫进入西顿，使血流在她街上。被杀的必在其中仆倒，四围有刀剑临到她，人就知道我是耶和华。」","notes":[]},{"n":24,"t":"「四围恨恶以色列家的人，必不再向他们作刺人的荆棘，伤人的蒺藜，人就知道我是主耶和华。」","notes":[],"heads":["以色列要蒙福"]},{"n":25,"t":"主耶和华如此说：「我将分散在万民中的以色列家招聚回来，向他们在列邦人眼前显为圣的时候，他们就在我赐给我仆人雅各之地，仍然居住。","notes":[]},{"n":26,"t":"他们要在这地上安然居住。我向四围恨恶他们的众人施行审判以后，他们要盖造房屋，栽种葡萄园，安然居住，就知道我是耶和华—他们的神。」","notes":[]}]},"29":{"heading":"斥责埃及","verses":[{"n":1,"t":"第十年十月十二日，耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要向埃及王法老预言攻击他和埃及全地，","notes":[]},{"n":3,"t":"说主耶和华如此说：埃及王法老啊，我与你这卧在自己河中的大鱼为敌。你曾说：这河是我的，是我为自己造的。","notes":[]},{"n":4,"t":"我—耶和华必用钩子钩住你的腮颊，又使江河中的鱼贴住你的鳞甲；我必将你和所有贴住你鳞甲的鱼，从江河中拉上来，","notes":[]},{"n":5,"t":"把你并江河中的鱼都抛在旷野；你必倒在田间，不被收殓，不被掩埋。我已将你给地上野兽、空中飞鸟作食物。","notes":[]},{"n":6,"t":"「埃及一切的居民，因向以色列家成了芦苇的杖，就知道我是耶和华。","notes":[]},{"n":7,"t":"他们用手持住你，你就断折，伤了他们的肩；他们倚靠你，你就断折，闪了他们的腰。","notes":[]},{"n":8,"t":"所以主耶和华如此说：我必使刀剑临到你，从你中间将人与牲畜剪除。","notes":[]},{"n":9,"t":"埃及地必荒废凄凉，他们就知道我是耶和华。「因为法老说：『这河是我的，是我所造的』，","notes":[]},{"n":10,"t":"所以我必与你并你的江河为敌，使埃及地，从色弗尼塔直到古实境界，全然荒废凄凉。","notes":[]},{"n":11,"t":"人的脚、兽的蹄都不经过，四十年之久并无人居住。","notes":[]},{"n":12,"t":"我必使埃及地在荒凉的国中成为荒凉，使埃及城在荒废的城中变为荒废，共有四十年。我必将埃及人分散在列国，四散在列邦。」","notes":[]},{"n":13,"t":"主耶和华如此说：「满了四十年，我必招聚分散在各国民中的埃及人。","notes":[]},{"n":14,"t":"我必叫埃及被掳的人回来，使他们归回本地巴忒罗。在那里必成为低微的国，","notes":[]},{"n":15,"t":"必为列国中最低微的，也不再自高于列国之上。我必减少他们，以致不再辖制列国。","notes":[]},{"n":16,"t":"埃及必不再作以色列家所倚靠的；以色列家仰望埃及人的时候，便思念罪孽。他们就知道我是主耶和华。」","notes":[]},{"n":17,"t":"二十七年正月初一日，耶和华的话临到我说：","notes":[],"heads":["尼布甲尼撒要征服埃及"]},{"n":18,"t":"「人子啊，巴比伦王尼布甲尼撒使他的军兵大大效劳，攻打泰尔，以致头都光秃，肩都磨破；然而他和他的军兵攻打泰尔，并没有从那里得什么酬劳。","notes":[]},{"n":19,"t":"所以主耶和华如此说：我必将埃及地赐给巴比伦王尼布甲尼撒；他必掳掠埃及群众，抢其中的财为掳物，夺其中的货为掠物，这就可以作他军兵的酬劳。","notes":[]},{"n":20,"t":"我将埃及地赐给他，酬他所效的劳，因王与军兵是为我勤劳。这是主耶和华说的。","notes":[]},{"n":21,"t":"「当那日，我必使以色列家的角发生，又必使你—以西结在他们中间得以开口；他们就知道我是耶和华。」","notes":[]}]},"30":{"heading":"耶和华要惩罚埃及","verses":[{"n":1,"t":"耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要发预言说，主耶和华如此说：哀哉这日！你们应当哭号。","notes":[]},{"n":3,"t":"因为耶和华的日子临近，就是密云之日，列国受罚之期。","notes":[]},{"n":4,"t":"必有刀剑临到埃及；在埃及被杀之人仆倒的时候，古实人就有痛苦，人民必被掳掠，基址必被拆毁。","notes":[]},{"n":5,"t":"古实人、弗人、路德人、杂族的人民，并古巴人，以及同盟之地的人都要与埃及人一同倒在刀下。」","notes":["或译：利比亚"]},{"n":6,"t":"耶和华如此说：扶助埃及的也必倾倒。埃及因势力而有的骄傲必降低微；其中的人民，从色弗尼塔起必倒在刀下。这是主耶和华说的。","notes":["见二十九章十节"]},{"n":7,"t":"埃及地在荒凉的国中必成为荒凉；埃及城在荒废的城中也变为荒废。","notes":[]},{"n":8,"t":"我在埃及中使火着起；帮助埃及的，都被灭绝。那时，他们就知道我是耶和华。","notes":[]},{"n":9,"t":"「到那日，必有使者坐船，从我面前出去，使安逸无虑的古实人惊惧；必有痛苦临到他们，好像埃及遭灾的日子一样。看哪，这事临近了！","notes":[]},{"n":10,"t":"主耶和华如此说：我必借巴比伦王尼布甲尼撒的手，除灭埃及众人。","notes":[]},{"n":11,"t":"他和随从他的人，就是列国中强暴的，必进来毁灭这地。他们必拔刀攻击埃及，使遍地有被杀的人。","notes":[]},{"n":12,"t":"我必使江河干涸，将地卖在恶人的手中；我必借外邦人的手，使这地和其中所有的变为凄凉。这是我—耶和华说的。","notes":[]},{"n":13,"t":"主耶和华如此说：我必毁灭偶像，从挪弗除灭神像；必不再有君王出自埃及地。我要使埃及地的人惧怕。","notes":[]},{"n":14,"t":"我必使巴忒罗荒凉，在琐安中使火着起，向挪施行审判。","notes":[]},{"n":15,"t":"我必将我的忿怒倒在埃及的保障上，就是训上，并要剪除挪的众人。","notes":[]},{"n":16,"t":"我必在埃及中使火着起；训必大大痛苦；挪必被攻破；挪弗白日见仇敌。","notes":["或译：终日"]},{"n":17,"t":"亚文和比伯实的少年人必倒在刀下；这些城的人必被掳掠。","notes":[]},{"n":18,"t":"我在答比匿折断埃及的诸轭，使她因势力而有的骄傲在其中止息。那时，日光必退去；至于这城，必有密云遮蔽，其中的女子必被掳掠。","notes":[]},{"n":19,"t":"我必这样向埃及施行审判，他们就知道我是耶和华。」","notes":[]},{"n":20,"t":"十一年正月初七日，耶和华的话临到我说：","notes":[],"heads":["埃及王破碎的力量"]},{"n":21,"t":"「人子啊，我已打折埃及王法老的膀臂；没有敷药，也没有用布缠好，使他有力持刀。","notes":[]},{"n":22,"t":"所以主耶和华如此说：看哪，我与埃及王法老为敌，必将他有力的膀臂和已打折的膀臂全行打断，使刀从他手中坠落。","notes":[]},{"n":23,"t":"我必将埃及人分散在列国，四散在列邦。","notes":[]},{"n":24,"t":"我必使巴比伦王的膀臂有力，将我的刀交在他手中；却要打断法老的膀臂，他就在巴比伦王面前唉哼，如同受死伤的人一样。","notes":[]},{"n":25,"t":"我必扶持巴比伦王的膀臂，法老的膀臂却要下垂；我将我的刀交在巴比伦王手中，他必举刀攻击埃及地，他们就知道我是耶和华。","notes":[]},{"n":26,"t":"我必将埃及人分散在列国，四散在列邦；他们就知道我是耶和华。」","notes":[]}]},"31":{"heading":"以香柏树比拟埃及","verses":[{"n":1,"t":"十一年三月初一日，耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要向埃及王法老和他的众人说：在威势上谁能与你相比呢？","notes":[]},{"n":3,"t":"亚述王曾如黎巴嫩中的香柏树，枝条荣美，影密如林，极其高大，树尖插入云中。","notes":[]},{"n":4,"t":"众水使它生长；深水使它长大。所栽之地有江河围流，汊出的水道延到田野诸树。","notes":[]},{"n":5,"t":"所以它高大超过田野诸树；发旺的时候，枝子繁多，因得大水之力枝条长长。","notes":[]},{"n":6,"t":"空中的飞鸟都在枝子上搭窝；田野的走兽都在枝条下生子；所有大国的人民都在它荫下居住。","notes":[]},{"n":7,"t":"树大条长，成为荣美，因为根在众水之旁。","notes":[]},{"n":8,"t":"神园中的香柏树不能遮蔽它；松树不及它的枝子；枫树不及它的枝条；神园中的树都没有它荣美。","notes":[]},{"n":9,"t":"我使它的枝条蕃多，成为荣美，以致神伊甸园中的树都嫉妒它。」","notes":[]},{"n":10,"t":"所以主耶和华如此说：「因它高大，树尖插入云中，心骄气傲，","notes":[]},{"n":11,"t":"我就必将它交给列国中大有威势的人；他必定办它。我因它的罪恶，已经驱逐它。","notes":[]},{"n":12,"t":"外邦人，就是列邦中强暴的，将它砍断弃掉。它的枝条落在山间和一切谷中，它的枝子折断，落在地的一切河旁。地上的众民已经走去，离开它的荫下。","notes":[]},{"n":13,"t":"空中的飞鸟都要宿在这败落的树上，田野的走兽都要卧在它的枝条下，","notes":[]},{"n":14,"t":"好使水旁的诸树不因高大而自尊，也不将树尖插入云中，并且那些得水滋润、有势力的，也不得高大自立。因为它们在世人中，和下坑的人都被交与死亡，到阴府去了。」","notes":[]},{"n":15,"t":"主耶和华如此说：「它下阴间的那日，我便使人悲哀。我为它遮盖深渊，使江河凝结，大水停流；我也使黎巴嫩为它凄惨，田野的诸树都因它发昏。","notes":[]},{"n":16,"t":"我将它扔到阴间，与下坑的人一同下去。那时，列国听见它坠落的响声就都震动，并且伊甸的一切树—就是黎巴嫩得水滋润、最佳最美的树—都在阴府受了安慰。","notes":[]},{"n":17,"t":"它们也与它同下阴间，到被杀的人那里。它们曾作它的膀臂，在列国中它的荫下居住。","notes":[]},{"n":18,"t":"在这样荣耀威势上，在伊甸园诸树中，谁能与你相比呢？然而你要与伊甸的诸树一同下到阴府，在未受割礼的人中，与被杀的人一同躺卧。「法老和他的群众乃是如此。这是主耶和华说的。」","notes":[]}]},"32":{"heading":"以鳄鱼比拟埃及王","verses":[{"n":1,"t":"十二年十二月初一日，耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要为埃及王法老作哀歌，说：从前你在列国中，如同少壮狮子；现在你却像海中的大鱼。你冲出江河，用爪搅动诸水，使江河浑浊。","notes":[]},{"n":3,"t":"主耶和华如此说：我必用多国的人民，将我的网撒在你身上，把你拉上来。","notes":[]},{"n":4,"t":"我必将你丢在地上，抛在田野，使空中的飞鸟都落在你身上，使遍地的野兽吃你得饱。","notes":[]},{"n":5,"t":"我必将你的肉丢在山间，用你高大的尸首填满山谷。","notes":[]},{"n":6,"t":"我又必用你的血浇灌你所游泳之地，漫过山顶；河道都必充满。","notes":[]},{"n":7,"t":"我将你扑灭的时候，要把天遮蔽，使众星昏暗，以密云遮掩太阳，月亮也不放光。","notes":[]},{"n":8,"t":"我必使天上的亮光都在你以上变为昏暗，使你的地上黑暗。这是主耶和华说的。","notes":[]},{"n":9,"t":"「我使你败亡的风声传到你所不认识的各国。那时，我必使多民的心因你愁烦。","notes":[]},{"n":10,"t":"我在许多国民和君王面前向你抡我的刀，国民就必因你惊奇，君王也必因你极其恐慌。在你仆倒的日子，他们各人为自己的性命时刻战兢。」","notes":[]},{"n":11,"t":"主耶和华如此说：「巴比伦王的刀必临到你。","notes":[]},{"n":12,"t":"我必借勇士的刀使你的众民仆倒；这勇士都是列国中强暴的。他们必使埃及的骄傲归于无有；埃及的众民必被灭绝。","notes":[]},{"n":13,"t":"我必从埃及多水旁除灭所有的走兽；人脚兽蹄必不再搅浑这水。","notes":[]},{"n":14,"t":"那时，我必使埃及河澄清，江河像油缓流。这是主耶和华说的。","notes":[]},{"n":15,"t":"我使埃及地变为荒废凄凉；这地缺少从前所充满的，又击杀其中一切的居民。那时，他们就知道我是耶和华。","notes":[]},{"n":16,"t":"「人必用这哀歌去哀哭，列国的女子为埃及和她的群众也必以此悲哀。这是主耶和华说的。」","notes":[]},{"n":17,"t":"十二年十二月十五日，耶和华的话临到我说：","notes":[],"heads":["为埃及哀号"]},{"n":18,"t":"「人子啊，你要为埃及群众哀号，又要将埃及和有名之国的女子，并下坑的人，一同扔到阴府去。","notes":[]},{"n":19,"t":"你埃及的美丽胜过谁呢？你下去与未受割礼的人一同躺卧吧！","notes":[]},{"n":20,"t":"他们必在被杀的人中仆到。她被交给刀剑，要把她和她的群众拉去。","notes":[]},{"n":21,"t":"强盛的勇士要在阴间对埃及王和帮助他的说话；他们是未受割礼被杀的人，已经下去，躺卧不动。","notes":[]},{"n":22,"t":"「亚述和她的众民都在那里，她民的坟墓在她四围；他们都是被杀倒在刀下的。","notes":[]},{"n":23,"t":"他们的坟墓在坑中极深之处。她的众民在她坟墓的四围，都是被杀倒在刀下的；他们曾在活人之地使人惊恐。","notes":[]},{"n":24,"t":"「以拦也在那里，她的群众在她坟墓的四围，都是被杀倒在刀下、未受割礼而下阴府的；他们曾在活人之地使人惊恐，并且与下坑的人一同担当羞辱。","notes":[]},{"n":25,"t":"人给她和她的群众在被杀的人中设立床榻。她民的坟墓在她四围，他们都是未受割礼被刀杀的；他们曾在活人之地使人惊恐，并且与下坑的人一同担当羞辱。以拦已经放在被杀的人中。","notes":[]},{"n":26,"t":"「米设、土巴，和她们的群众都在那里。她民的坟墓在她四围，他们都是未受割礼被刀杀的；他们曾在活人之地使人惊恐。","notes":[]},{"n":27,"t":"他们不得与那未受割礼仆倒的勇士一同躺卧；这些勇士带着兵器下阴间，头枕刀剑，骨头上有本身的罪孽；他们曾在活人之地使勇士惊恐。","notes":[]},{"n":28,"t":"「法老啊，你必在未受割礼的人中败坏，与那些被杀的人一同躺卧。","notes":[]},{"n":29,"t":"「以东也在那里。她君王和一切首领虽然仗着势力，还是放在被杀的人中；他们必与未受割礼的和下坑的人一同躺卧。","notes":[]},{"n":30,"t":"「在那里有北方的众王子和一切西顿人，都与被杀的人下去。他们虽然仗着势力使人惊恐，还是蒙羞。他们未受割礼，和被刀杀的一同躺卧，与下坑的人一同担当羞辱。","notes":[]},{"n":31,"t":"「法老看见他们，便为他被杀的军队受安慰。这是主耶和华说的。","notes":[]},{"n":32,"t":"我任凭法老在活人之地使人惊恐，法老和他的群众必放在未受割礼和被杀的人中。这是主耶和华说的。」","notes":[]}]},"33":{"heading":"神指派以西结作守望者","verses":[{"n":1,"t":"耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要告诉本国的子民说：我使刀剑临到哪一国，那一国的民从他们中间选立一人为守望的。","notes":[]},{"n":3,"t":"他见刀剑临到那地，若吹角警戒众民，","notes":[]},{"n":4,"t":"凡听见角声不受警戒的，刀剑若来除灭了他，他的罪就必归到自己的头上。","notes":["原文是血"]},{"n":5,"t":"他听见角声，不受警戒，他的罪必归到自己的身上；他若受警戒，便是救了自己的性命。","notes":[]},{"n":6,"t":"倘若守望的人见刀剑临到，不吹角，以致民不受警戒，刀剑来杀了他们中间的一个人，他虽然死在罪孽之中，我却要向守望的人讨他丧命的罪。","notes":["原文是血"]},{"n":7,"t":"「人子啊，我照样立你作以色列家守望的人。所以你要听我口中的话，替我警戒他们。","notes":[]},{"n":8,"t":"我对恶人说：『恶人哪，你必要死！』你—以西结若不开口警戒恶人，使他离开所行的道，这恶人必死在罪孽之中，我却要向你讨他丧命的罪。","notes":["原文是血"]},{"n":9,"t":"倘若你警戒恶人转离所行的道，他仍不转离，他必死在罪孽之中，你却救自己脱离了罪。」","notes":[]},{"n":10,"t":"「人子啊，你要对以色列家说：『你们常说：我们的过犯罪恶在我们身上，我们必因此消灭，怎能存活呢？』","notes":[],"heads":["个人的责任"]},{"n":11,"t":"你对他们说，主耶和华说：我指着我的永生起誓，我断不喜悦恶人死亡，惟喜悦恶人转离所行的道而活。以色列家啊，你们转回，转回吧！离开恶道，何必死亡呢？","notes":[]},{"n":12,"t":"人子啊，你要对本国的人民说：义人的义，在犯罪之日不能救他；至于恶人的恶，在他转离恶行之日也不能使他倾倒；义人在犯罪之日也不能因他的义存活。","notes":[]},{"n":13,"t":"我对义人说：『你必定存活！』他若倚靠他的义而作罪孽，他所行的义都不被记念。他必因所作的罪孽死亡。","notes":[]},{"n":14,"t":"再者，我对恶人说：『你必定死亡！』他若转离他的罪，行正直与合理的事：","notes":[]},{"n":15,"t":"还人的当头和所抢夺的，遵行生命的律例，不作罪孽，他必定存活，不致死亡。","notes":[]},{"n":16,"t":"他所犯的一切罪必不被记念。他行了正直与合理的事，必定存活。","notes":[]},{"n":17,"t":"「你本国的子民还说：『主的道不公平。』其实他们的道不公平。","notes":[]},{"n":18,"t":"义人转离他的义而作罪孽，就必因此死亡。","notes":[]},{"n":19,"t":"恶人转离他的恶，行正直与合理的事，就必因此存活。","notes":[]},{"n":20,"t":"你们还说：『主的道不公平。』以色列家啊，我必按你们各人所行的审判你们。」","notes":[]},{"n":21,"t":"我们被掳之后十二年十月初五日，有人从耶路撒冷逃到我这里，说：「城已攻破。」","notes":[],"heads":["耶路撒冷陷落的消息"]},{"n":22,"t":"逃来的人未到前一日的晚上，耶和华的灵降在我身上，开我的口。到第二日早晨，那人来到我这里，我口就开了，不再缄默。","notes":["原文是手"]},{"n":23,"t":"耶和华的话临到我说：","notes":[],"heads":["百姓的罪"]},{"n":24,"t":"「人子啊，住在以色列荒废之地的人说：『亚伯拉罕独自一人能得这地为业，我们人数众多，这地更是给我们为业的。』","notes":[]},{"n":25,"t":"所以你要对他们说，主耶和华如此说：你们吃带血的物，仰望偶像，并且杀人流血，你们还能得这地为业吗？","notes":[]},{"n":26,"t":"你们倚仗自己的刀剑行可憎的事，人人玷污邻舍的妻，你们还能得这地为业吗？","notes":[]},{"n":27,"t":"你要对他们这样说，主耶和华如此说：我指着我的永生起誓，在荒场中的，必倒在刀下；在田野间的，必交给野兽吞吃；在保障和洞里的，必遭瘟疫而死。","notes":[]},{"n":28,"t":"我必使这地荒凉，令人惊骇；她因势力而有的骄傲也必止息。以色列的山都必荒凉，无人经过。","notes":[]},{"n":29,"t":"我因他们所行一切可憎的事使地荒凉，令人惊骇。那时，他们就知道我是耶和华。」","notes":[]},{"n":30,"t":"「人子啊，你本国的子民在墙垣旁边、在房屋门口谈论你。弟兄对弟兄彼此说：『来吧！听听有什么话从耶和华而出。』","notes":[],"heads":["先知传讲信息的结果"]},{"n":31,"t":"他们来到你这里如同民来聚会，坐在你面前仿佛是我的民。他们听你的话却不去行；因为他们的口多显爱情，心却追随财利。","notes":[]},{"n":32,"t":"他们看你如善于奏乐、声音幽雅之人所唱的雅歌，他们听你的话却不去行。","notes":[]},{"n":33,"t":"看哪，所说的快要应验；应验了，他们就知道在他们中间有了先知。」","notes":[]}]},"34":{"heading":"以色列的牧人","verses":[{"n":1,"t":"耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要向以色列的牧人发预言，攻击他们，说，主耶和华如此说：祸哉！以色列的牧人只知牧养自己。牧人岂不当牧养群羊吗？","notes":[]},{"n":3,"t":"你们吃脂油、穿羊毛、宰肥壮的，却不牧养群羊。","notes":[]},{"n":4,"t":"瘦弱的，你们没有养壮；有病的，你们没有医治；受伤的，你们没有缠裹；被逐的，你们没有领回；失丧的，你们没有寻找；但用强暴严严地辖制。","notes":[]},{"n":5,"t":"因无牧人，羊就分散；既分散，便作了一切野兽的食物。","notes":[]},{"n":6,"t":"我的羊在诸山间、在各高冈上流离，在全地上分散，无人去寻，无人去找。","notes":[]},{"n":7,"t":"「所以，你们这些牧人要听耶和华的话。","notes":[]},{"n":8,"t":"主耶和华说：我指着我的永生起誓，我的羊因无牧人就成为掠物，也作了一切野兽的食物。我的牧人不寻找我的羊；这些牧人只知牧养自己，并不牧养我的羊。","notes":[]},{"n":9,"t":"所以你们这些牧人要听耶和华的话。","notes":[]},{"n":10,"t":"主耶和华如此说：我必与牧人为敌，必向他们的手追讨我的羊，使他们不再牧放群羊；牧人也不再牧养自己。我必救我的羊脱离他们的口，不再作他们的食物。」","notes":[]},{"n":11,"t":"「主耶和华如此说：看哪，我必亲自寻找我的羊，将它们寻见。","notes":[],"heads":["好牧人"]},{"n":12,"t":"牧人在羊群四散的日子怎样寻找他的羊，我必照样寻找我的羊。这些羊在密云黑暗的日子散到各处，我必从那里救回它们来。","notes":[]},{"n":13,"t":"我必从万民中领出它们，从各国内聚集它们，引导它们归回故土，也必在以色列山上—一切溪水旁边、境内一切可居之处—牧养它们。","notes":[]},{"n":14,"t":"我必在美好的草场牧养它们。它们的圈必在以色列高处的山上，它们必在佳美之圈中躺卧，也在以色列山肥美的草场吃草。","notes":[]},{"n":15,"t":"主耶和华说：我必亲自作我羊的牧人，使它们得以躺卧。","notes":[]},{"n":16,"t":"失丧的，我必寻找；被逐的，我必领回；受伤的，我必缠裹；有病的，我必医治；只是肥的壮的，我必除灭，也要秉公牧养它们。","notes":[]},{"n":17,"t":"「我的羊群哪，论到你们，主耶和华如此说：我必在羊与羊中间、公绵羊与公山羊中间施行判断。","notes":[]},{"n":18,"t":"你们这些肥壮的羊，在美好的草场吃草还以为小事吗？剩下的草，你们竟用蹄践踏了；你们喝清水，剩下的水，你们竟用蹄搅浑了。","notes":[]},{"n":19,"t":"至于我的羊，只得吃你们所践踏的，喝你们所搅浑的。","notes":[]},{"n":20,"t":"「所以，主耶和华如此说：我必在肥羊和瘦羊中间施行判断。","notes":[]},{"n":21,"t":"因为你们用胁用肩拥挤一切瘦弱的，又用角抵触，以致使它们四散。","notes":[]},{"n":22,"t":"所以，我必拯救我的群羊不再作掠物；我也必在羊和羊中间施行判断。","notes":[]},{"n":23,"t":"我必立一牧人照管他们，牧养他们，就是我的仆人大卫。他必牧养他们，作他们的牧人。","notes":[]},{"n":24,"t":"我—耶和华必作他们的神，我的仆人大卫必在他们中间作王。这是耶和华说的。","notes":[]},{"n":25,"t":"「我必与他们立平安的约，使恶兽从境内断绝，他们就必安居在旷野，躺卧在林中。","notes":[]},{"n":26,"t":"我必使他们与我山的四围成为福源，我也必叫时雨落下，必有福如甘霖而降。","notes":[]},{"n":27,"t":"田野的树必结果，地也必有出产；他们必在故土安然居住。我折断他们所负的轭，救他们脱离那以他们为奴之人的手；那时，他们就知道我是耶和华。","notes":[]},{"n":28,"t":"他们必不再作外邦人的掠物，地上的野兽也不再吞吃他们；却要安然居住，无人惊吓。","notes":[]},{"n":29,"t":"我必给他们兴起有名的植物；他们在境内不再为饥荒所灭，也不再受外邦人的羞辱，","notes":[]},{"n":30,"t":"必知道我、耶和华—他们的神是与他们同在的，并知道他们—以色列家是我的民。这是主耶和华说的。","notes":[]},{"n":31,"t":"你们作我的羊，我草场上的羊，乃是以色列人，我也是你们的神。这是主耶和华说的。」","notes":[]}]},"35":{"heading":"神惩罚以东","verses":[{"n":1,"t":"耶和华的话又临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要面向西珥山发预言，攻击它，","notes":[]},{"n":3,"t":"对它说，主耶和华如此说：西珥山哪，我与你为敌，必向你伸手攻击你，使你荒凉，令人惊骇。","notes":[]},{"n":4,"t":"我必使你的城邑变为荒场，成为凄凉。你就知道我是耶和华。","notes":[]},{"n":5,"t":"因为你永怀仇恨，在以色列人遭灾、罪孽到了尽头的时候，将他们交与刀剑，","notes":[]},{"n":6,"t":"所以主耶和华说：我指着我的永生起誓，我必使你遭遇流血的报应，罪必追赶你；你既不恨恶杀人流血，所以这罪必追赶你。","notes":["原文是血；本节同"]},{"n":7,"t":"我必使西珥山荒凉，令人惊骇，来往经过的人我必剪除。","notes":[]},{"n":8,"t":"我必使西珥山满有被杀的人。被刀杀的，必倒在你小山和山谷，并一切的溪水中。","notes":[]},{"n":9,"t":"我必使你永远荒凉，使你的城邑无人居住，你的民就知道我是耶和华。","notes":[]},{"n":10,"t":"「因为你曾说：『这二国这二邦必归于我，我必得为业』（其实耶和华仍在那里），","notes":[]},{"n":11,"t":"所以主耶和华说：我指着我的永生起誓，我必照你的怒气和你从仇恨中向他们所发的嫉妒待你。我审判你的时候，必将自己显明在他们中间。","notes":[]},{"n":12,"t":"你也必知道我—耶和华听见了你的一切毁谤，就是你攻击以色列山的话，说：『这些山荒凉，是归我们吞灭的。』","notes":[]},{"n":13,"t":"你们也用口向我夸大，增添与我反对的话，我都听见了。","notes":[]},{"n":14,"t":"主耶和华如此说：全地欢乐的时候，我必使你荒凉。","notes":[]},{"n":15,"t":"你怎样因以色列家的地业荒凉而喜乐，我必照你所行的待你。西珥山哪，你和以东全地必都荒凉。你们就知道我是耶和华。」","notes":[]}]},"36":{"heading":"神赐福给以色列","verses":[{"n":1,"t":"「人子啊，你要对以色列山发预言说：以色列山哪，要听耶和华的话。","notes":[]},{"n":2,"t":"主耶和华如此说：因仇敌说：『阿哈！这永久的山冈都归我们为业了！』","notes":[]},{"n":3,"t":"所以要发预言说，主耶和华如此说：因为敌人使你荒凉，四围吞吃，好叫你归与其余的外邦人为业，并且多嘴多舌的人提起你来，百姓也说你有臭名。","notes":[]},{"n":4,"t":"故此，以色列山要听主耶和华的话。大山小冈、水沟山谷、荒废之地、被弃之城，为四围其余的外邦人所占据、所讥刺的，","notes":[]},{"n":5,"t":"主耶和华对你们如此说：我真发愤恨如火，责备那其余的外邦人和以东的众人。他们快乐满怀，心存恨恶，将我的地归自己为业，又看为被弃的掠物。","notes":[]},{"n":6,"t":"所以，你要指着以色列地说预言，对大山小冈、水沟山谷说，主耶和华如此说：我发愤恨和忿怒说，因你们曾受外邦人的羞辱，","notes":[]},{"n":7,"t":"所以我起誓说：你们四围的外邦人总要担当自己的羞辱。这是主耶和华说的。","notes":[]},{"n":8,"t":"「以色列山哪，你必发枝条，为我的民以色列结果子，因为他们快要来到。","notes":[]},{"n":9,"t":"看哪，我是帮助你的，也必向你转意，使你得以耕种。","notes":[]},{"n":10,"t":"我必使以色列全家的人数在你上面增多，城邑有人居住，荒场再被建造。","notes":[]},{"n":11,"t":"我必使人和牲畜在你上面加增；他们必生养众多。我要使你照旧有人居住，并要赐福与你比先前更多，你就知道我是耶和华。","notes":[]},{"n":12,"t":"我必使人，就是我的民以色列，行在你上面。他们必得你为业；你也不再使他们丧子。","notes":[]},{"n":13,"t":"主耶和华如此说：因为人对你说：『你是吞吃人的，又使国民丧子』，","notes":[]},{"n":14,"t":"所以主耶和华说：你必不再吞吃人，也不再使国民丧子。","notes":[]},{"n":15,"t":"我使你不再听见各国的羞辱，不再受万民的辱骂，也不再使国民绊跌。这是主耶和华说的。」","notes":[]},{"n":16,"t":"耶和华的话又临到我说：","notes":[],"heads":["以色列的新生活"]},{"n":17,"t":"「人子啊，以色列家住在本地的时候，在行动作为上玷污那地。他们的行为在我面前，好像正在经期的妇人那样污秽。","notes":[]},{"n":18,"t":"所以我因他们在那地上流人的血，又因他们以偶像玷污那地，就把我的忿怒倾在他们身上。","notes":[]},{"n":19,"t":"我将他们分散在列国，四散在列邦，按他们的行动作为惩罚他们。","notes":[]},{"n":20,"t":"他们到了所去的列国，就使我的圣名被亵渎；因为人谈论他们说，这是耶和华的民，是从耶和华的地出来的。","notes":[]},{"n":21,"t":"我却顾惜我的圣名，就是以色列家在所到的列国中所亵渎的。","notes":[]},{"n":22,"t":"「所以，你要对以色列家说，主耶和华如此说：以色列家啊，我行这事不是为你们，乃是为我的圣名，就是在你们到的列国中所亵渎的。","notes":[]},{"n":23,"t":"我要使我的大名显为圣；这名在列国中已被亵渎，就是你们在他们中间所亵渎的。我在他们眼前，在你们身上显为圣的时候，他们就知道我是耶和华。这是主耶和华说的。","notes":[]},{"n":24,"t":"我必从各国收取你们，从列邦聚集你们，引导你们归回本地。","notes":[]},{"n":25,"t":"我必用清水洒在你们身上，你们就洁净了。我要洁净你们，使你们脱离一切的污秽，弃掉一切的偶像。","notes":[]},{"n":26,"t":"我也要赐给你们一个新心，将新灵放在你们里面，又从你们的肉体中除掉石心，赐给你们肉心。","notes":[]},{"n":27,"t":"我必将我的灵放在你们里面，使你们顺从我的律例，谨守遵行我的典章。","notes":[]},{"n":28,"t":"你们必住在我所赐给你们列祖之地。你们要作我的子民，我要作你们的神。","notes":[]},{"n":29,"t":"我必救你们脱离一切的污秽，也必命五谷丰登，不使你们遭遇饥荒。","notes":[]},{"n":30,"t":"我必使树木多结果子，田地多出土产，好叫你们不再因饥荒受外邦人的讥诮。","notes":[]},{"n":31,"t":"那时，你们必追想你们的恶行和你们不善的作为，就因你们的罪孽和可憎的事厌恶自己。","notes":[]},{"n":32,"t":"主耶和华说：你们要知道，我这样行不是为你们。以色列家啊，当为自己的行为抱愧蒙羞。","notes":[]},{"n":33,"t":"「主耶和华如此说：我洁净你们，使你们脱离一切罪孽的日子，必使城邑有人居住，荒场再被建造。","notes":[]},{"n":34,"t":"过路的人虽看为荒废之地，现今这荒废之地仍得耕种。","notes":[]},{"n":35,"t":"他们必说：『这先前为荒废之地，现在成如伊甸园；这荒废凄凉、毁坏的城邑现在坚固有人居住。』","notes":[]},{"n":36,"t":"那时，在你们四围其余的外邦人必知道我—耶和华修造那毁坏之处，培植那荒废之地。我—耶和华说过，也必成就。","notes":[]},{"n":37,"t":"「主耶和华如此说：我要加增以色列家的人数，多如羊群。他们必为这事向我求问，我要给他们成就。","notes":[]},{"n":38,"t":"耶路撒冷在守节作祭物所献的羊群怎样多，照样，荒凉的城邑必被人群充满。他们就知道我是耶和华。」","notes":[]}]},"37":{"heading":"枯骨的复苏","verses":[{"n":1,"t":"耶和华的灵降在我身上。耶和华借他的灵带我出去，将我放在平原中；这平原遍满骸骨。","notes":["原文是手"]},{"n":2,"t":"他使我从骸骨的四围经过，谁知在平原的骸骨甚多，而且极其枯干。","notes":[]},{"n":3,"t":"他对我说：「人子啊，这些骸骨能复活吗？」我说：「主耶和华啊，你是知道的。」","notes":[]},{"n":4,"t":"他又对我说：「你向这些骸骨发预言说：枯干的骸骨啊，要听耶和华的话。","notes":[]},{"n":5,"t":"主耶和华对这些骸骨如此说：『我必使气息进入你们里面，你们就要活了。","notes":[]},{"n":6,"t":"我必给你们加上筋，使你们长肉，又将皮遮蔽你们，使气息进入你们里面，你们就要活了；你们便知道我是耶和华。』」","notes":[]},{"n":7,"t":"于是，我遵命说预言。正说预言的时候，不料，有响声，有地震；骨与骨互相联络。","notes":[]},{"n":8,"t":"我观看，见骸骨上有筋，也长了肉，又有皮遮蔽其上，只是还没有气息。","notes":[]},{"n":9,"t":"主对我说：「人子啊，你要发预言，向风发预言，说主耶和华如此说：气息啊，要从四方而来，吹在这些被杀的人身上，使他们活了。」","notes":["原文是风"]},{"n":10,"t":"于是我遵命说预言，气息就进入骸骨，骸骨便活了，并且站起来，成为极大的军队。","notes":[]},{"n":11,"t":"主对我说：「人子啊，这些骸骨就是以色列全家。他们说：『我们的骨头枯干了，我们的指望失去了，我们灭绝净尽了。』","notes":[]},{"n":12,"t":"所以你要发预言对他们说，主耶和华如此说：『我的民哪，我必开你们的坟墓，使你们从坟墓中出来，领你们进入以色列地。","notes":[]},{"n":13,"t":"我的民哪，我开你们的坟墓，使你们从坟墓中出来，你们就知道我是耶和华。","notes":[]},{"n":14,"t":"我必将我的灵放在你们里面，你们就要活了。我将你们安置在本地，你们就知道我—耶和华如此说，也如此成就了。这是耶和华说的。』」","notes":[]},{"n":15,"t":"耶和华的话又临到我说：","notes":[],"heads":["犹大和以色列组成联合王国"]},{"n":16,"t":"「人子啊，你要取一根木杖，在其上写『为犹大和他的同伴以色列人』；又取一根木杖，在其上写『为约瑟，就是为以法莲，又为他的同伴以色列全家』。","notes":[]},{"n":17,"t":"你要使这两根木杖接连为一，在你手中成为一根。","notes":[]},{"n":18,"t":"你本国的子民问你说：『这是什么意思？你不指示我们吗？』","notes":[]},{"n":19,"t":"你就对他们说：『主耶和华如此说：我要将约瑟和他同伴以色列支派的杖，就是那在以法莲手中的，与犹大的杖一同接连为一，在我手中成为一根。』","notes":[]},{"n":20,"t":"你所写的那两根杖要在他们眼前拿在手中，","notes":[]},{"n":21,"t":"要对他们说，主耶和华如此说：我要将以色列人从他们所到的各国收取，又从四围聚集他们，引导他们归回本地。","notes":[]},{"n":22,"t":"我要使他们在那地，在以色列山上成为一国，有一王作他们众民的王。他们不再为二国，决不再分为二国；","notes":[]},{"n":23,"t":"也不再因偶像和可憎的物，并一切的罪过玷污自己。我却要救他们出离一切的住处，就是他们犯罪的地方；我要洁净他们，如此，他们要作我的子民，我要作他们的神。","notes":[]},{"n":24,"t":"「我的仆人大卫必作他们的王；众民必归一个牧人。他们必顺从我的典章，谨守遵行我的律例。","notes":[]},{"n":25,"t":"他们必住在我赐给我仆人雅各的地上，就是你们列祖所住之地。他们和他们的子孙，并子孙的子孙，都永远住在那里。我的仆人大卫必作他们的王，直到永远。","notes":[]},{"n":26,"t":"并且我要与他们立平安的约，作为永约。我也要将他们安置在本地，使他们的人数增多，又在他们中间设立我的圣所，直到永远。","notes":[]},{"n":27,"t":"我的居所必在他们中间；我要作他们的神，他们要作我的子民。","notes":[]},{"n":28,"t":"我的圣所在以色列人中间直到永远，外邦人就必知道我是叫以色列成为圣的耶和华。」","notes":[]}]},"38":{"heading":"歌革—耶和华的工具","verses":[{"n":1,"t":"耶和华的话临到我说：","notes":[]},{"n":2,"t":"「人子啊，你要面向玛各地的歌革，就是罗施、米设、土巴的王发预言攻击他，","notes":[]},{"n":3,"t":"说主耶和华如此说：罗施、米设、土巴的王歌革啊，我与你为敌。","notes":[]},{"n":4,"t":"我必用钩子钩住你的腮颊，调转你，将你和你的军兵、马匹、马兵带出来，都披挂整齐，成了大队，有大小盾牌，各拿刀剑。","notes":[]},{"n":5,"t":"波斯人、古实人，和弗人，各拿盾牌，头上戴盔；","notes":["又作利比亚人"]},{"n":6,"t":"歌篾人和他的军队，北方极处的陀迦玛族和他的军队，这许多国的民都同着你。","notes":[]},{"n":7,"t":"「那聚集到你这里的各队都当准备；你自己也要准备，作他们的大帅。","notes":[]},{"n":8,"t":"过了多日，你必被差派。到末后之年，你必来到脱离刀剑从列国收回之地，到以色列常久荒凉的山上；但那从列国中招聚出来的必在其上安然居住。","notes":[]},{"n":9,"t":"你和你的军队，并同着你许多国的民，必如暴风上来，如密云遮盖地面。」","notes":[]},{"n":10,"t":"主耶和华如此说：「到那时，你心必起意念，图谋恶计，","notes":[]},{"n":11,"t":"说：『我要上那无城墙的乡村，我要到那安静的民那里，他们都没有城墙，无门、无闩，安然居住。","notes":[]},{"n":12,"t":"我去要抢财为掳物，夺货为掠物，反手攻击那从前荒凉、现在有人居住之地，又攻击那住世界中间、从列国招聚、得了牲畜财货的民。』","notes":[]},{"n":13,"t":"示巴人、底但人、他施的客商，和其间的少壮狮子都必问你说：『你来要抢财为掳物吗？你聚集军队要夺货为掠物吗？要夺取金银，掳去牲畜、财货吗？要抢夺许多财宝为掳物吗？』","notes":[]},{"n":14,"t":"「人子啊，你要因此发预言，对歌革说，主耶和华如此说：到我民以色列安然居住之日，你岂不知道吗？","notes":[]},{"n":15,"t":"你必从本地，从北方的极处率领许多国的民来，都骑着马，乃一大队极多的军兵。","notes":[]},{"n":16,"t":"歌革啊，你必上来攻击我的民以色列，如密云遮盖地面。末后的日子，我必带你来攻击我的地，到我在外邦人眼前，在你身上显为圣的时候，好叫他们认识我。","notes":[]},{"n":17,"t":"主耶和华如此说：我在古时借我的仆人以色列的先知所说的，就是你吗？当日他们多年预言我必带你来攻击以色列人。」","notes":[]},{"n":18,"t":"主耶和华说：「歌革上来攻击以色列地的时候，我的怒气要从鼻孔里发出。","notes":[],"heads":["神惩罚歌革"]},{"n":19,"t":"我发愤恨和烈怒如火说：那日在以色列地必有大震动，","notes":[]},{"n":20,"t":"甚至海中的鱼、天空的鸟、田野的兽，并地上的一切昆虫，和其上的众人，因见我的面就都震动；山岭必崩裂，陡岩必塌陷，墙垣都必坍倒。」","notes":[]},{"n":21,"t":"主耶和华说：「我必命我的诸山发刀剑来攻击歌革；人都要用刀剑杀害弟兄。","notes":[]},{"n":22,"t":"我必用瘟疫和流血的事刑罚他。我也必将暴雨、大雹与火，并硫磺降与他和他的军队，并他所率领的众民。","notes":[]},{"n":23,"t":"我必显为大，显为圣，在多国人的眼前显现；他们就知道我是耶和华。」","notes":[]}]},"39":{"heading":"歌革被击败","verses":[{"n":1,"t":"「人子啊，你要向歌革发预言攻击他，说主耶和华如此说：罗施、米设、土巴的王歌革啊，我与你为敌。","notes":[]},{"n":2,"t":"我必调转你，领你前往，使你从北方的极处上来，带你到以色列的山上。","notes":[]},{"n":3,"t":"我必从你左手打落你的弓，从你右手打掉你的箭。","notes":[]},{"n":4,"t":"你和你的军队，并同着你的列国人，都必倒在以色列的山上。我必将你给各类的鸷鸟和田野的走兽作食物。","notes":[]},{"n":5,"t":"你必倒在田野，因为我曾说过。这是主耶和华说的。","notes":[]},{"n":6,"t":"我要降火在玛各和海岛安然居住的人身上，他们就知道我是耶和华。","notes":[]},{"n":7,"t":"「我要在我民以色列中显出我的圣名，也不容我的圣名再被亵渎，列国人就知道我是耶和华—以色列中的圣者。","notes":[]},{"n":8,"t":"主耶和华说：这日事情临近，也必成就，乃是我所说的日子。","notes":[]},{"n":9,"t":"「住以色列城邑的人必出去和捡器械，就是大小盾牌、弓箭、梃杖、枪矛，都当柴烧火，直烧七年，","notes":[]},{"n":10,"t":"甚至他们不必从田野捡柴，也不必从树林伐木；因为他们要用器械烧火，并且抢夺那抢夺他们的人，掳掠那掳掠他们的人。这是主耶和华说的。」","notes":[]},{"n":11,"t":"「当那日，我必将以色列地的谷，就是海东人所经过的谷，赐给歌革为坟地，使经过的人到此停步。在那里人必葬埋歌革和他的群众，就称那地为哈们·歌革谷。","notes":[],"heads":["歌革的埋葬"]},{"n":12,"t":"以色列家的人必用七个月葬埋他们，为要洁净全地。","notes":[]},{"n":13,"t":"全地的居民都必葬埋他们。当我得荣耀的日子，这事必叫他们得名声。这是主耶和华说的。","notes":[]},{"n":14,"t":"他们必分派人时常巡查遍地，与过路的人一同葬埋那剩在地面上的尸首，好洁净全地。过了七个月，他们还要巡查。","notes":[]},{"n":15,"t":"巡查遍地的人要经过全地，见有人的骸骨，就在旁边立一标记，等葬埋的人来将骸骨葬在哈们·歌革谷。","notes":[]},{"n":16,"t":"他们必这样洁净那地，并有一城名叫哈摩那。","notes":[]},{"n":17,"t":"「人子啊，主耶和华如此说：你要对各类的飞鸟和田野的走兽说：你们聚集来吧，要从四方聚到我为你们献祭之地，就是在以色列山上献大祭之地，好叫你们吃肉、喝血。","notes":[]},{"n":18,"t":"你们必吃勇士的肉，喝地上首领的血，就如吃公绵羊、羊羔、公山羊、公牛，都是巴珊的肥畜。","notes":[]},{"n":19,"t":"你们吃我为你们所献的祭，必吃饱了脂油，喝醉了血。","notes":[]},{"n":20,"t":"你们必在我席上饱吃马匹和坐车的人，并勇士和一切的战士。这是主耶和华说的。」","notes":[]},{"n":21,"t":"「我必显我的荣耀在列国中；万民就必看见我所行的审判与我在他们身上所加的手。","notes":[],"heads":["以色列的复兴"]},{"n":22,"t":"这样，从那日以后，以色列家必知道我是耶和华—他们的神。","notes":[]},{"n":23,"t":"列国人也必知道以色列家被掳掠是因他们的罪孽。他们得罪我，我就掩面不顾，将他们交在敌人手中，他们便都倒在刀下。","notes":[]},{"n":24,"t":"我是照他们的污秽和罪过待他们，并且我掩面不顾他们。」","notes":[]},{"n":25,"t":"主耶和华如此说：「我要使雅各被掳的人归回，要怜悯以色列全家，又为我的圣名发热心。","notes":[]},{"n":26,"t":"他们在本地安然居住，无人惊吓，是我将他们从万民中领回，从仇敌之地召来。我在许多国的民眼前，在他们身上显为圣的时候，他们要担当自己的羞辱和干犯我的一切罪。","notes":[],"end":27},{"n":28,"t":"因我使他们被掳到外邦人中，后又聚集他们归回本地，他们就知道我是耶和华—他们的神；我必不再留他们一人在外邦。","notes":[]},{"n":29,"t":"我也不再掩面不顾他们，因我已将我的灵浇灌以色列家。这是主耶和华说的。」","notes":[]}]},"40":{"heading":"新圣殿的异象","verses":[{"n":1,"t":"我们被掳掠第二十五年，耶路撒冷城攻破后十四年，正在年初，月之初十日，耶和华的灵降在我身上，他把我带到以色列地。","notes":["原文是手"],"heads":["以西结被带到耶路撒冷"]},{"n":2,"t":"在神的异象中带我到以色列地，安置在至高的山上；在山上的南边有仿佛一座城建立。","notes":[]},{"n":3,"t":"他带我到那里，见有一人，颜色如铜，手拿麻绳和量度的竿，站在门口。","notes":["原文是形状"]},{"n":4,"t":"那人对我说：「人子啊，凡我所指示你的，你都要用眼看，用耳听，并要放在心上。我带你到这里来，特为要指示你；凡你所见的，你都要告诉以色列家。」","notes":[]},{"n":5,"t":"我见殿四围有墙。那人手拿量度的竿，长六肘，每肘是一肘零一掌。他用竿量墙，厚一竿，高一竿。","notes":[],"heads":["东门"]},{"n":6,"t":"他到了朝东的门，就上门的台阶，量门的这槛，宽一竿；又量门的那槛，宽一竿。","notes":[]},{"n":7,"t":"又有卫房，每房长一竿，宽一竿，相隔五肘。门槛，就是挨着向殿的廊门槛，宽一竿。","notes":[]},{"n":8,"t":"他又量向殿门的廊子，宽一竿。","notes":[]},{"n":9,"t":"又量门廊，宽八肘，墙柱厚二肘；那门的廊子向着殿。","notes":[]},{"n":10,"t":"东门洞有卫房：这旁三间，那旁三间，都是一样的尺寸；这边的柱子和那边的柱子，也是一样的尺寸。","notes":[]},{"n":11,"t":"他量门口，宽十肘，长十三肘。","notes":[]},{"n":12,"t":"卫房前展出的境界：这边一肘，那边一肘；卫房这边六肘，那边六肘。","notes":[]},{"n":13,"t":"又量门洞，从这卫房顶的后檐到那卫房顶的后檐，宽二十五肘；卫房门与门相对。","notes":[]},{"n":14,"t":"又量廊子六十肘，墙柱外是院子，有廊为界，在门洞两边。","notes":["原文是造","七十士译本是二十肘"]},{"n":15,"t":"从大门口到内廊前，共五十肘。","notes":[]},{"n":16,"t":"卫房和门洞两旁柱间并廊子，都有严紧的窗棂；里边都有窗棂，柱上有雕刻的棕树。","notes":[]},{"n":17,"t":"他带我到外院，见院的四围有铺石地；铺石地上有屋子三十间。","notes":[],"heads":["外院"]},{"n":18,"t":"铺石地，就是矮铺石地在各门洞两旁，以门洞的长短为度。","notes":[]},{"n":19,"t":"他从下门量到内院外，共宽一百肘，东面北面都是如此。","notes":[]},{"n":20,"t":"他量外院朝北的门，长宽若干。","notes":[],"heads":["北门"]},{"n":21,"t":"门洞的卫房，这旁三间，那旁三间。门洞的柱子和廊子，与第一门的尺寸一样。门洞长五十肘，宽二十五肘。","notes":[]},{"n":22,"t":"其窗棂和廊子，并雕刻的棕树，与朝东的门尺寸一样。登七层台阶上到这门，前面有廊子。","notes":[]},{"n":23,"t":"内院有门与这门相对，北面东面都是如此。他从这门量到那门，共一百肘。","notes":[]},{"n":24,"t":"他带我往南去，见朝南有门，又照先前的尺寸量门洞的柱子和廊子。","notes":[],"heads":["南门"]},{"n":25,"t":"门洞两旁与廊子的周围都有窗棂，和先量的窗棂一样。门洞长五十肘，宽二十五肘。","notes":[]},{"n":26,"t":"登七层台阶上到这门，前面有廊子；柱上有雕刻的棕树，这边一棵，那边一棵。","notes":[]},{"n":27,"t":"内院朝南有门。从这门量到朝南的那门，共一百肘。","notes":[]},{"n":28,"t":"他带我从南门到内院，就照先前的尺寸量南门。","notes":[],"heads":["内院的南门"]},{"n":29,"t":"卫房和柱子，并廊子都照先前的尺寸。门洞两旁与廊子的周围都有窗棂。门洞长五十肘，宽二十五肘。","notes":[]},{"n":30,"t":"周围有廊子，长二十五肘，宽五肘。","notes":[]},{"n":31,"t":"廊子朝着外院，柱上有雕刻的棕树。登八层台阶上到这门。","notes":[]},{"n":32,"t":"他带我到内院的东面，就照先前的尺寸量东门。","notes":[],"heads":["内院的东门"]},{"n":33,"t":"卫房和柱子，并廊子都照先前的尺寸。门洞两旁与廊子的周围都有窗棂。门洞长五十肘，宽二十五肘。","notes":[]},{"n":34,"t":"廊子朝着外院。门洞两旁的柱子都有雕刻的棕树。登八层台阶上到这门。","notes":[]},{"n":35,"t":"他带我到北门，就照先前的尺寸量那门，","notes":[],"heads":["内院的北门"]},{"n":36,"t":"就是量卫房和柱子，并廊子。门洞周围都有窗棂；门洞长五十肘，宽二十五肘。","notes":[]},{"n":37,"t":"廊柱朝着外院。门洞两旁的柱子都有雕刻的棕树。登八层台阶上到这门。","notes":[]},{"n":38,"t":"门洞的柱旁有屋子和门；祭司在那里洗燔祭牲。","notes":["原文是他们"],"heads":["厢房"]},{"n":39,"t":"在门廊内，这边有两张桌子，那边有两张桌子，在其上可以宰杀燔祭牲、赎罪祭牲，和赎愆祭牲。","notes":[]},{"n":40,"t":"上到朝北的门口，这边有两张桌子，门廊那边也有两张桌子。","notes":[]},{"n":41,"t":"门这边有四张桌子，那边有四张桌子，共八张；在其上祭司宰杀牺牲。","notes":[]},{"n":42,"t":"为燔祭牲有四张桌子，是凿过的石头做成的，长一肘半，宽一肘半，高一肘。祭司将宰杀燔祭牲和平安祭牲所用的器皿放在其上。","notes":[]},{"n":43,"t":"有钩子，宽一掌，钉在廊内的四围。桌子上有牺牲的肉。","notes":[]},{"n":44,"t":"在北门旁，内院里有屋子，为歌唱的人而设。这屋子朝南；在南门旁，又有一间朝北。","notes":["南：原文是东"]},{"n":45,"t":"他对我说：「这朝南的屋子是为看守殿宇的祭司；","notes":[]},{"n":46,"t":"那朝北的屋子是为看守祭坛的祭司。这些祭司是利未人中撒督的子孙，近前来事奉耶和华的。」","notes":[]},{"n":47,"t":"他又量内院，长一百肘，宽一百肘，是见方的。祭坛在殿前。","notes":[],"heads":["内院和圣殿"]},{"n":48,"t":"于是他带我到殿前的廊子，量廊子的墙柱。这面厚五肘，那面厚五肘。门两旁，这边三肘，那边三肘。","notes":[]},{"n":49,"t":"廊子长二十肘，宽十一肘。上廊子有台阶。靠近墙柱又有柱子，这边一根，那边一根。","notes":[]}]},"41":{"heading":"靠圣殿墙边的厢房","verses":[{"n":1,"t":"他带我到殿那里量墙柱：这面厚六肘，那面厚六肘，宽窄与会幕相同。","notes":[]},{"n":2,"t":"门口宽十肘。门两旁，这边五肘，那边五肘。他量殿长四十肘，宽二十肘。","notes":[]},{"n":3,"t":"他到内殿量墙柱，各厚二肘。门口宽六肘，门两旁各宽七肘。","notes":[]},{"n":4,"t":"他量内殿，长二十肘，宽二十肘。他对我说：「这是至圣所。」","notes":[]},{"n":5,"t":"他又量殿墙，厚六肘；围着殿有旁屋，各宽四肘。","notes":[]},{"n":6,"t":"旁屋有三层，层叠而上，每层排列三十间。旁屋的梁木搁在殿墙坎上，免得插入殿墙。","notes":[]},{"n":7,"t":"这围殿的旁屋越高越宽；因旁屋围殿悬叠而上，所以越上越宽，从下一层，由中一层，到上一层。","notes":[]},{"n":8,"t":"我又见围着殿有高月台。旁屋的根基，高足一竿，就是六大肘。","notes":[]},{"n":9,"t":"旁屋的外墙厚五肘。旁屋之外还有余地。","notes":[]},{"n":10,"t":"在旁屋与对面的房屋中间有空地，宽二十肘。","notes":[]},{"n":11,"t":"旁屋的门都向余地：一门向北，一门向南。周围的余地宽五肘。","notes":[]},{"n":12,"t":"在西面空地之后有房子，宽七十肘，长九十肘，墙四围厚五肘。","notes":[],"heads":["西边的屋子"]},{"n":13,"t":"这样，他量殿，长一百肘，又量空地和那房子并墙，共长一百肘。","notes":[],"heads":["圣殿的尺寸"]},{"n":14,"t":"殿的前面和两旁的空地，宽一百肘。","notes":[]},{"n":15,"t":"他量空地后面的那房子，并两旁的楼廊，共长一百肘。","notes":[]},{"n":16,"t":"内殿、院廊、门槛、严紧的窗棂，并对着门槛的三层楼廊，从地到窗棂（窗棂都有蔽子），","notes":[],"heads":["圣殿的内部"]},{"n":17,"t":"直到门以上，就是到内殿和外殿内外四围墙壁，都按尺寸用木板遮蔽。","notes":[]},{"n":18,"t":"墙上雕刻基路伯和棕树。每二基路伯中间有一棵棕树，每基路伯有二脸。","notes":[]},{"n":19,"t":"这边有人脸向着棕树，那边有狮子脸向着棕树，殿内周围都是如此。","notes":[]},{"n":20,"t":"从地至门以上，都有基路伯和棕树。殿墙就是这样。","notes":[]},{"n":21,"t":"殿的门柱是方的。至圣所的前面，形状和殿的形状一样。","notes":[]},{"n":22,"t":"坛是木头做的，高三肘，长二肘。坛角和坛面，并四旁，都是木头做的。他对我说：「这是耶和华面前的桌子。」","notes":[]},{"n":23,"t":"殿和至圣所的门各有两扇。","notes":[],"heads":["门"]},{"n":24,"t":"每扇分两扇，这两扇是折叠的。这边门分两扇，那边门也分两扇。","notes":[]},{"n":25,"t":"殿的门扇上雕刻基路伯和棕树，与刻在墙上的一般。在外头廊前有木槛。","notes":[]},{"n":26,"t":"廊这边那边都有严紧的窗棂和棕树；殿的旁屋和槛就是这样。","notes":[]}]},"42":{"heading":"圣殿附近的两座屋子","verses":[{"n":1,"t":"他带我出来向北，到外院，又带我进入圣屋；这圣屋一排顺着空地，一排与北边铺石地之屋相对。","notes":[]},{"n":2,"t":"这圣屋长一百肘，宽五十肘，有向北的门。","notes":[]},{"n":3,"t":"对着内院那二十肘宽之空地，又对着外院的铺石地，在第三层楼上有楼廊对着楼廊。","notes":[]},{"n":4,"t":"在圣屋前有一条夹道，宽十肘，长一百肘。房门都向北。","notes":[]},{"n":5,"t":"圣屋因为楼廊占去些地方，所以上层比中下两层窄些。","notes":[]},{"n":6,"t":"圣屋有三层，却无柱子，不像外院的屋子有柱子；所以上层比中下两层更窄。","notes":[]},{"n":7,"t":"圣屋外，东边有墙，靠着外院，长五十肘。","notes":[]},{"n":8,"t":"靠着外院的圣屋长五十肘。殿北面的圣屋长一百肘。","notes":[]},{"n":9,"t":"在圣屋以下，东头有进入之处，就是从外院进入之处。","notes":[]},{"n":10,"t":"向南在内院墙里有圣屋，一排与铺石地之屋相对，一排顺着空地。","notes":["原文是东"]},{"n":11,"t":"这圣屋前的夹道与北边圣屋的夹道长宽一样；出入之处与北屋门的样式相同。","notes":[]},{"n":12,"t":"正在墙前、夹道的东头，有门可以进入，与向南圣屋的门一样。","notes":[]},{"n":13,"t":"他对我说：「顺着空地的南屋北屋，都是圣屋；亲近耶和华的祭司当在那里吃至圣的物，也当在那里放至圣的物，就是素祭、赎罪祭，和赎愆祭，因此处为圣。","notes":[]},{"n":14,"t":"祭司进去出了圣所的时候，不可直到外院，但要在圣屋放下他们供职的衣服，因为是圣衣；要穿上别的衣服才可以到属民的外院。」","notes":[]},{"n":15,"t":"他量完了内殿，就带我出朝东的门，量院的四围。","notes":[],"heads":["圣殿周围的尺寸"]},{"n":16,"t":"他用量度的竿量四围，量东面五百肘，","notes":["原文是竿；本章下同"]},{"n":17,"t":"用竿量北面五百肘，","notes":[]},{"n":18,"t":"用竿量南面五百肘，","notes":[]},{"n":19,"t":"又转到西面，用竿量五百肘。","notes":[]},{"n":20,"t":"他量四面，四围有墙，长五百肘，宽五百肘，为要分别圣地与俗地。","notes":[]}]},"43":{"heading":"耶和华回到圣殿","verses":[{"n":1,"t":"以后，他带我到一座门，就是朝东的门。","notes":[]},{"n":2,"t":"以色列神的荣光从东而来。他的声音如同多水的声音；地就因他的荣耀发光。","notes":[]},{"n":3,"t":"其状如从前他来灭城的时候我所见的异象，那异象如我在迦巴鲁河边所见的异象，我就俯伏在地。","notes":[]},{"n":4,"t":"耶和华的荣光从朝东的门照入殿中。","notes":[]},{"n":5,"t":"灵将我举起，带入内院，不料，耶和华的荣光充满了殿。","notes":[]},{"n":6,"t":"我听见有一位从殿中对我说话。有一人站在我旁边。","notes":[]},{"n":7,"t":"他对我说：「人子啊，这是我宝座之地，是我脚掌所踏之地。我要在这里住，在以色列人中直到永远。以色列家和他们的君王必不再玷污我的圣名，就是行邪淫、在锡安的高处葬埋他们君王的尸首，","notes":[]},{"n":8,"t":"使他们的门槛挨近我的门槛，他们的门框挨近我的门框；他们与我中间仅隔一墙，并且行可憎的事，玷污了我的圣名，所以我发怒灭绝他们。","notes":[]},{"n":9,"t":"现在他们当从我面前远除邪淫和他们君王的尸首，我就住在他们中间直到永远。","notes":[]},{"n":10,"t":"「人子啊，你要将这殿指示以色列家，使他们因自己的罪孽惭愧，也要他们量殿的尺寸。","notes":[]},{"n":11,"t":"他们若因自己所行的一切事惭愧，你就将殿的规模、样式、出入之处，和一切形状、典章、礼仪、法则指示他们，在他们眼前写上，使他们遵照殿的一切规模典章去做。","notes":[]},{"n":12,"t":"殿的法则乃是如此：殿在山顶上，四围的全界要称为至圣。这就是殿的法则。」","notes":[]},{"n":13,"t":"以下量祭坛，是以肘为度（这肘是一肘零一掌）。底座高一肘，边宽一肘，四围起边高一掌，这是坛的座。","notes":[],"heads":["祭坛"]},{"n":14,"t":"从底座到下层磴台，高二肘，边宽一肘。从小磴台到大磴台，高四肘，边宽一肘。","notes":[]},{"n":15,"t":"坛上的供台，高四肘。供台的四拐角上都有角。","notes":[]},{"n":16,"t":"供台长十二肘，宽十二肘，四面见方。","notes":[]},{"n":17,"t":"磴台长十四肘，宽十四肘，四面见方。四围起边高半肘，底座四围的边宽一肘。台阶朝东。","notes":[]},{"n":18,"t":"他对我说：「人子啊，主耶和华如此说：建造祭坛，为要在其上献燔祭洒血，造成的时候典章如下：","notes":[],"heads":["奉献祭坛"]},{"n":19,"t":"主耶和华说，你要将一只公牛犊作为赎罪祭，给祭司利未人撒督的后裔，就是那亲近我、事奉我的。","notes":[]},{"n":20,"t":"你要取些公牛的血，抹在坛的四角和磴台的四拐角，并四围所起的边上。你这样洁净坛，坛就洁净了。","notes":[]},{"n":21,"t":"你又要将那作赎罪祭的公牛犊烧在殿外、圣地之外预定之处。","notes":[]},{"n":22,"t":"次日，要将无残疾的公山羊献为赎罪祭；要洁净坛，像用公牛犊洁净的一样。","notes":[]},{"n":23,"t":"洁净了坛，就要将一只无残疾的公牛犊和羊群中一只无残疾的公绵羊","notes":[]},{"n":24,"t":"奉到耶和华前。祭司要撒盐在其上，献与耶和华为燔祭。","notes":[]},{"n":25,"t":"七日内，每日要预备一只公山羊为赎罪祭，也要预备一只公牛犊和羊群中的一只公绵羊，都要没有残疾的。","notes":[]},{"n":26,"t":"七日祭司洁净坛，坛就洁净了；要这样把坛分别为圣。","notes":[]},{"n":27,"t":"满了七日，自八日以后，祭司要在坛上献你们的燔祭和平安祭；我必悦纳你们。这是主耶和华说的。」","notes":[]}]},"44":{"heading":"东门的使用","verses":[{"n":1,"t":"他又带我回到圣地朝东的外门；那门关闭了。","notes":[]},{"n":2,"t":"耶和华对我说：「这门必须关闭，不可敞开，谁也不可由其中进入；因为耶和华—以色列的神已经由其中进入，所以必须关闭。","notes":[]},{"n":3,"t":"至于王，他必按王的位分，坐在其内，在耶和华面前吃饼。他必由这门的廊而入，也必由此而出。」","notes":[]},{"n":4,"t":"他又带我由北门来到殿前。我观看，见耶和华的荣光充满耶和华的殿，我就俯伏在地。","notes":[],"heads":["进入圣殿的规则"]},{"n":5,"t":"耶和华对我说：「人子啊，我对你所说耶和华殿中的一切典章法则，你要放在心上，用眼看，用耳听，并要留心殿宇和圣地一切出入之处。","notes":[]},{"n":6,"t":"你要对那悖逆的以色列家说，主耶和华如此说：以色列家啊，你们行一切可憎的事，当够了吧！","notes":[]},{"n":7,"t":"你们把我的食物，就是脂油和血献上的时候，将身心未受割礼的外邦人领进我的圣地，玷污了我的殿；又背了我的约，在你们一切可憎的事上，加上这一层。","notes":[]},{"n":8,"t":"你们也没有看守我的圣物，却派别人在圣地替你们看守我所吩咐你们的。","notes":[]},{"n":9,"t":"「主耶和华如此说：以色列中的外邦人，就是身心未受割礼的，都不可入我的圣地。」","notes":[]},{"n":10,"t":"「当以色列人走迷的时候，有利未人远离我，就是走迷离开我、随从他们的偶像，他们必担当自己的罪孽。","notes":[],"heads":["不准当祭司的利未人"]},{"n":11,"t":"然而他们必在我的圣地当仆役，照管殿门，在殿中供职；必为民宰杀燔祭牲和平安祭牲，必站在民前伺候他们。","notes":[]},{"n":12,"t":"因为这些利未人曾在偶像前伺候这民，成了以色列家罪孽的绊脚石，所以我向他们起誓：他们必担当自己的罪孽。这是主耶和华说的。","notes":[]},{"n":13,"t":"他们不可亲近我，给我供祭司的职分，也不可挨近我的一件圣物，就是至圣的物；他们却要担当自己的羞辱和所行可憎之事的报应。","notes":[]},{"n":14,"t":"然而我要使他们看守殿宇，办理其中的一切事，并做其内一切当做之工。」","notes":[]},{"n":15,"t":"「以色列人走迷离开我的时候，祭司利未人撒督的子孙仍看守我的圣所。他们必亲近我，事奉我，并且侍立在我面前，将脂油与血献给我。这是主耶和华说的。","notes":[],"heads":["祭司"]},{"n":16,"t":"他们必进入我的圣所，就近我的桌前事奉我，守我所吩咐的。","notes":[]},{"n":17,"t":"他们进内院门必穿细麻衣。在内院门和殿内供职的时候不可穿羊毛衣服。","notes":[]},{"n":18,"t":"他们头上要戴细麻布裹头巾，腰穿细麻布裤子；不可穿使身体出汗的衣服。","notes":[]},{"n":19,"t":"他们出到外院的民那里，当脱下供职的衣服，放在圣屋内，穿上别的衣服，免得因圣衣使民成圣。","notes":[]},{"n":20,"t":"不可剃头，也不可容发绺长长，只可剪发。","notes":[]},{"n":21,"t":"祭司进内院的时候都不可喝酒。","notes":[]},{"n":22,"t":"不可娶寡妇和被休的妇人为妻，只可娶以色列后裔中的处女，或是祭司遗留的寡妇。","notes":[]},{"n":23,"t":"他们要使我的民知道圣俗的分别，又使他们分辨洁净的和不洁净的。","notes":[]},{"n":24,"t":"有争讼的事，他们应当站立判断，要按我的典章判断。在我一切的节期必守我的律法、条例，也必以我的安息日为圣日。","notes":[]},{"n":25,"t":"他们不可挨近死尸沾染自己，只可为父亲、母亲、儿子、女儿、弟兄，和未嫁人的姊妹沾染自己。","notes":[]},{"n":26,"t":"祭司洁净之后，必再计算七日。","notes":[]},{"n":27,"t":"当他进内院，进圣所，在圣所中事奉的日子，要为自己献赎罪祭。这是主耶和华说的。","notes":[]},{"n":28,"t":"「祭司必有产业，我是他们的产业。不可在以色列中给他们基业；我是他们的基业。","notes":[]},{"n":29,"t":"素祭、赎罪祭，和赎愆祭他们都可以吃，以色列中一切永献的物都要归他们。","notes":[]},{"n":30,"t":"首先初熟之物和一切所献的供物都要归给祭司。你们也要用初熟的麦子磨面给祭司；这样，福气就必临到你们的家了。","notes":[]},{"n":31,"t":"无论是鸟是兽，凡自死的，或是撕裂的，祭司都不可吃。」","notes":[]}]},"45":{"heading":"归给耶和华的土地","verses":[{"n":1,"t":"你们拈阄分地为业，要献上一分给耶和华为圣供地，长二万五千肘，宽一万肘。这分以内，四围都为圣地。","notes":[]},{"n":2,"t":"其中有作为圣所之地，长五百肘，宽五百肘，四面见方。四围再有五十肘为郊野之地。","notes":[]},{"n":3,"t":"要以肘为度量地，长二万五千肘，宽一万肘。其中有圣所，是至圣的。","notes":[]},{"n":4,"t":"这是全地的一分圣地，要归与供圣所职事的祭司，就是亲近事奉耶和华的，作为他们房屋之地与圣所之圣地。","notes":[]},{"n":5,"t":"又有一分，长二万五千肘，宽一万肘，要归与在殿中供职的利未人，作为二十间房屋之业。","notes":[]},{"n":6,"t":"也要分定属城的地业，宽五千肘，长二万五千肘，挨着那分圣供地，要归以色列全家。","notes":[]},{"n":7,"t":"归王之地要在圣供地和属城之地的两旁，就是圣供地和属城之地的旁边，西至西头，东至东头，从西到东，其长与每支派的分一样。","notes":[],"heads":["君王的土地"]},{"n":8,"t":"这地在以色列中必归王为业。我所立的王必不再欺压我的民，却要按支派将地分给以色列家。","notes":[]},{"n":9,"t":"主耶和华如此说：「以色列的王啊，你们应当知足，要除掉强暴和抢夺的事，施行公平和公义，不再勒索我的民。这是主耶和华说的。","notes":[],"heads":["君王应守的规例"]},{"n":10,"t":"「你们要用公道天平、公道伊法、公道罢特。","notes":[]},{"n":11,"t":"伊法与罢特大小要一样。罢特可盛贺梅珥十分之一，伊法也可盛贺梅珥十分之一，都以贺梅珥的大小为准。","notes":[]},{"n":12,"t":"舍客勒是二十季拉；二十舍客勒，二十五舍客勒，十五舍客勒，为你们的弥那。","notes":[]},{"n":13,"t":"「你们当献的供物乃是这样：一贺梅珥麦子要献伊法六分之一；一贺梅珥大麦要献伊法六分之一。","notes":[]},{"n":14,"t":"你们献所分定的油，按油的罢特，一柯珥油要献罢特十分之一（原来十罢特就是一贺梅珥）。","notes":[]},{"n":15,"t":"从以色列滋润的草场上每二百羊中，要献一只羊羔。这都可作素祭、燔祭、平安祭，为民赎罪。这是主耶和华说的。","notes":[]},{"n":16,"t":"此地的民都要奉上这供物给以色列中的王。","notes":[]},{"n":17,"t":"王的本分是在节期、月朔、安息日，就是以色列家一切的节期，奉上燔祭、素祭、奠祭。他要预备赎罪祭、素祭、燔祭，和平安祭，为以色列家赎罪。」","notes":[]},{"n":18,"t":"主耶和华如此说：「正月初一日，你要取无残疾的公牛犊，洁净圣所。","notes":[],"heads":["节期"]},{"n":19,"t":"祭司要取些赎罪祭牲的血，抹在殿的门柱上和坛磴台的四角上，并内院的门框上。","notes":[]},{"n":20,"t":"本月初七日也要为误犯罪的和愚蒙犯罪的如此行，为殿赎罪。","notes":["七十士译本是七月初一日"]},{"n":21,"t":"「正月十四日，你们要守逾越节，守节七日，要吃无酵饼。","notes":[]},{"n":22,"t":"当日，王要为自己和国内的众民预备一只公牛作赎罪祭。","notes":[]},{"n":23,"t":"这节的七日，每日他要为耶和华预备无残疾的公牛七只、公绵羊七只为燔祭。每日又要预备公山羊一只为赎罪祭。","notes":[]},{"n":24,"t":"他也要预备素祭，就是为一只公牛同献一伊法细面，为一只公绵羊同献一伊法细面，每一伊法细面加油一欣。","notes":[]},{"n":25,"t":"七月十五日守节的时候，七日他都要如此行，照逾越节的赎罪祭、燔祭、素祭，和油的条例一样。」","notes":[]}]},"46":{"heading":"君王和节期","verses":[{"n":1,"t":"主耶和华如此说：「内院朝东的门，在办理事务的六日内必须关闭；惟有安息日和月朔必须敞开。","notes":[]},{"n":2,"t":"王要从这门的廊进入，站在门框旁边。祭司要为他预备燔祭和平安祭，他就要在门槛那里敬拜，然后出去。这门直到晚上不可关闭。","notes":[]},{"n":3,"t":"在安息日和月朔，国内的居民要在这门口，耶和华面前敬拜。","notes":[]},{"n":4,"t":"安息日，王所献与耶和华的燔祭要用无残疾的羊羔六只，无残疾的公绵羊一只；","notes":[]},{"n":5,"t":"同献的素祭要为公绵羊献一伊法细面，为羊羔照他的力量而献，一伊法细面加油一欣。","notes":[]},{"n":6,"t":"当月朔，要献无残疾的公牛犊一只，羊羔六只，公绵羊一只，都要无残疾的。","notes":[]},{"n":7,"t":"他也要预备素祭，为公牛献一伊法细面，为公绵羊献一伊法细面，为羊羔照他的力量而献，一伊法细面加油一欣。","notes":[]},{"n":8,"t":"王进入的时候必由这门的廊而入，也必由此而出。","notes":[]},{"n":9,"t":"「在各节期，国内居民朝见耶和华的时候，从北门进入敬拜的，必由南门而出；从南门进入的，必由北门而出。不可从所入的门而出，必要直往前行，由对门而出。","notes":[]},{"n":10,"t":"民进入，王也要在民中进入；民出去，王也要一同出去。","notes":[]},{"n":11,"t":"「在节期和圣会的日子同献的素祭，要为一只公牛献一伊法细面，为一只公绵羊献一伊法细面，为羊羔照他的力量而献，一伊法细面加油一欣。","notes":[]},{"n":12,"t":"王预备甘心献的燔祭或平安祭，就是向耶和华甘心献的，当有人为他开朝东的门。他就预备燔祭和平安祭，与安息日预备的一样，献毕就出去。他出去之后，当有人将门关闭。」","notes":[]},{"n":13,"t":"「每日，你要预备无残疾一岁的羊羔一只，献与耶和华为燔祭；要每早晨预备。","notes":[],"heads":["每日的祭"]},{"n":14,"t":"每早晨也要预备同献的素祭，细面一伊法六分之一，并油一欣三分之一，调和细面。这素祭要常献与耶和华为永远的定例。","notes":[]},{"n":15,"t":"每早晨要这样预备羊羔、素祭，并油为常献的燔祭。」","notes":[]},{"n":16,"t":"主耶和华如此说：「王若将产业赐给他的儿子，就成了他儿子的产业，那是他们承受为业的。","notes":[],"heads":["王和土地"]},{"n":17,"t":"倘若王将一分产业赐给他的臣仆，就成了他臣仆的产业；到自由之年仍要归与王。至于王的产业，必归与他的儿子。","notes":[]},{"n":18,"t":"王不可夺取民的产业，以致驱逐他们离开所承受的；他要从自己的地业中，将产业赐给他儿子，免得我的民分散，各人离开所承受的。」","notes":[]},{"n":19,"t":"那带我的，将我从门旁进入之处、领进为祭司预备的圣屋，是朝北的，见后头西边有一块地。","notes":[],"heads":["圣殿的厨房"]},{"n":20,"t":"他对我说：「这是祭司煮赎愆祭、赎罪祭，烤素祭之地，免得带到外院，使民成圣。」","notes":[]},{"n":21,"t":"他又带我到外院，使我经过院子的四拐角，见每拐角各有一个院子。","notes":[]},{"n":22,"t":"院子四拐角的院子，周围有墙，每院长四十肘，宽三十肘。四拐角院子的尺寸都是一样，","notes":[]},{"n":23,"t":"其中周围有一排房子，房子内有煮肉的地方。","notes":[]},{"n":24,"t":"他对我说：「这都是煮肉的房子，殿内的仆役要在这里煮民的祭物。」","notes":[]}]},"47":{"heading":"从圣殿流出的水","verses":[{"n":1,"t":"他带我回到殿门，见殿的门槛下有水往东流出（原来殿面朝东）。这水从槛下，由殿的右边，在祭坛的南边往下流。","notes":[]},{"n":2,"t":"他带我出北门，又领我从外边转到朝东的外门，见水从右边流出。","notes":[]},{"n":3,"t":"他手拿准绳往东出去的时候，量了一千肘，使我趟过水，水到踝子骨。","notes":[]},{"n":4,"t":"他又量了一千肘，使我趟过水，水就到膝；再量了一千肘，使我趟过水，水便到腰；","notes":[]},{"n":5,"t":"又量了一千肘，水便成了河，使我不能趟过。因为水势涨起，成为可洑的水，不可趟的河。","notes":[]},{"n":6,"t":"他对我说：「人子啊，你看见了什么？」他就带我回到河边。","notes":[]},{"n":7,"t":"我回到河边的时候，见在河这边与那边的岸上有极多的树木。","notes":[]},{"n":8,"t":"他对我说：「这水往东方流去，必下到亚拉巴，直到海。所发出来的水必流入盐海，使水变甜。","notes":["原文是得医治；下同"]},{"n":9,"t":"这河水所到之处，凡滋生的动物都必生活，并且因这流来的水必有极多的鱼，海水也变甜了。这河水所到之处，百物都必生活。","notes":[]},{"n":10,"t":"必有渔夫站在河边，从隐·基底直到隐·以革莲，都作晒网之处。那鱼各从其类，好像大海的鱼甚多。","notes":["或译：张"]},{"n":11,"t":"只是泥泞之地与洼湿之处不得治好，必为盐地。","notes":[]},{"n":12,"t":"在河这边与那边的岸上必生长各类的树木；其果可作食物，叶子不枯干，果子不断绝。每月必结新果子，因为这水是从圣所流出来的。树上的果子必作食物，叶子乃为治病。」","notes":[]},{"n":13,"t":"主耶和华如此说：「你们要照地的境界，按以色列十二支派分地为业。约瑟必得两分。","notes":[],"heads":["地界"]},{"n":14,"t":"你们承受这地为业，要彼此均分；因为我曾起誓应许将这地赐与你们的列祖；这地必归你们为业。","notes":[]},{"n":15,"t":"「地的四界乃是如此：北界从大海往希特伦，直到西达达口。","notes":[]},{"n":16,"t":"又往哈马、比罗他、西伯莲（西伯莲在大马士革与哈马两界中间），到浩兰边界的哈撒·哈提干。","notes":[]},{"n":17,"t":"这样，境界从海边往大马士革地界上的哈萨·以难，北边以哈马地为界。这是北界。","notes":[]},{"n":18,"t":"「东界在浩兰、大马士革、基列，和以色列地的中间，就是约旦河。你们要从北界量到东海。这是东界。","notes":[]},{"n":19,"t":"「南界是从他玛到米利巴·加低斯的水，延到埃及小河，直到大海。这是南界。","notes":[]},{"n":20,"t":"「西界就是大海，从南界直到哈马口对面之地。这是西界。","notes":[]},{"n":21,"t":"「你们要按着以色列的支派彼此分这地。","notes":[]},{"n":22,"t":"要拈阄分这地为业，归与自己和你们中间寄居的外人，就是在你们中间生养儿女的外人。你们要看他们如同以色列人中所生的一样；他们在以色列支派中要与你们同得地业。","notes":[]},{"n":23,"t":"外人寄居在哪支派中，你们就在那里分给他地业。这是主耶和华说的。」","notes":[]}]},"48":{"heading":"各支派分配土地","verses":[{"n":1,"t":"众支派按名所得之地记在下面：从北头，由希特伦往哈马口，到大马士革地界上的哈萨·以难。北边靠着哈马地（各支派的地都有东西的边界），是但的一分。","notes":[]},{"n":2,"t":"挨着但的地界，从东到西，是亚设的一分。","notes":[]},{"n":3,"t":"挨着亚设的地界，从东到西，是拿弗他利的一分。","notes":[]},{"n":4,"t":"挨着拿弗他利的地界，从东到西，是玛拿西的一分。","notes":[]},{"n":5,"t":"挨着玛拿西的地界，从东到西，是以法莲的一分。","notes":[]},{"n":6,"t":"挨着以法莲的地界，从东到西，是吕便的一分。","notes":[]},{"n":7,"t":"挨着吕便的地界，从东到西，是犹大的一分。","notes":[]},{"n":8,"t":"挨着犹大的地界，从东到西，必有你们所当献的供地，宽二万五千肘。从东界到西界，长短与各分之地相同，圣地当在其中。","notes":[],"heads":["中部特区"]},{"n":9,"t":"你们献与耶和华的供地要长二万五千肘，宽一万肘。","notes":[]},{"n":10,"t":"这圣供地要归与祭司，北长二万五千肘，西宽一万肘，东宽一万肘，南长二万五千肘。耶和华的圣地当在其中。","notes":[]},{"n":11,"t":"这地要归与撒督的子孙中成为圣的祭司，就是那守我所吩咐的。当以色列人走迷的时候，他们不像那些利未人走迷了。","notes":[]},{"n":12,"t":"这要归与他们为供地，是全地中至圣的。供地挨着利未人的地界。","notes":[]},{"n":13,"t":"利未人所得的地要长二万五千肘，宽一万肘，与祭司的地界相等，都长二万五千肘，宽一万肘。","notes":[]},{"n":14,"t":"这地不可卖，不可换，初熟之物也不可归与别人，因为是归耶和华为圣的。","notes":[]},{"n":15,"t":"这二万五千肘前面所剩下五千肘宽之地要作俗用，作为造城盖房郊野之地。城要在当中。","notes":[]},{"n":16,"t":"城的尺寸乃是如此：北面四千五百肘，南面四千五百肘，东面四千五百肘，西面四千五百肘。","notes":[]},{"n":17,"t":"城必有郊野，向北二百五十肘，向南二百五十肘，向东二百五十肘，向西二百五十肘。","notes":[]},{"n":18,"t":"靠着圣供地的余地，东长一万肘，西长一万肘，要与圣供地相等；其中的土产要作城内工人的食物。","notes":[]},{"n":19,"t":"所有以色列支派中，在城内做工的，都要耕种这地。","notes":[]},{"n":20,"t":"你们所献的圣供地连归城之地，是四方的：长二万五千肘，宽二万五千肘。","notes":[]},{"n":21,"t":"圣供地连归城之地，两边的余地要归与王。供地东边，南北二万五千肘，东至东界，西边南北二万五千肘，西至西界，与各分之地相同，都要归王。圣供地和殿的圣地要在其中，","notes":[]},{"n":22,"t":"并且利未人之地，与归城之地的东西两边延长之地（这两地在王地中间），就是在犹大和便雅悯两界中间，要归与王。","notes":[]},{"n":23,"t":"论到其余的支派，从东到西，是便雅悯的一分。","notes":[],"heads":["其他支派的土地"]},{"n":24,"t":"挨着便雅悯的地界，从东到西，是西缅的一分。","notes":[]},{"n":25,"t":"挨着西缅的地界，从东到西，是以萨迦的一分。","notes":[]},{"n":26,"t":"挨着以萨迦的地界，从东到西，是西布伦的一分。","notes":[]},{"n":27,"t":"挨着西布伦的地界，从东到西，是迦得的一分。","notes":[]},{"n":28,"t":"迦得地的南界是从他玛到米利巴·加低斯的水，延到埃及小河，直到大海。","notes":[]},{"n":29,"t":"这就是你们要拈阄分给以色列支派为业之地，乃是他们各支派所得之分。这是主耶和华说的。","notes":[]},{"n":30,"t":"城的北面四千五百肘。出城之处如下；","notes":[],"heads":["耶路撒冷的城门"]},{"n":31,"t":"城的各门要按以色列支派的名字。北面有三门，一为吕便门，一为犹大门，一为利未门；","notes":[]},{"n":32,"t":"东面四千五百肘，有三门，一为约瑟门，一为便雅悯门，一为但门；","notes":[]},{"n":33,"t":"南面四千五百肘，有三门，一为西缅门，一为以萨迦门，一为西布伦门；","notes":[]},{"n":34,"t":"西面四千五百肘，有三门，一为迦得门，一为亚设门，一为拿弗他利门。","notes":[]},{"n":35,"t":"城四围共一万八千肘。从此以后，这城的名字必称为「耶和华的所在」。","notes":[]}]}},"DAN":{"1":{"heading":"但以理和他的朋友们","verses":[{"n":1,"t":"犹大王约雅敬在位第三年，巴比伦王尼布甲尼撒来到耶路撒冷，将城围困。","notes":[],"heads":["但以理在尼布甲尼撒的宫廷里"]},{"n":2,"t":"主将犹大王约雅敬，并神殿中器皿的几分交付他手。他就把这器皿带到示拿地，收入他神的庙里，放在他神的库中。","notes":[]},{"n":3,"t":"王吩咐太监长亚施毗拿，从以色列人的宗室和贵胄中带进几个人来，","notes":[]},{"n":4,"t":"就是年少没有残疾、相貌俊美、通达各样学问、知识聪明俱备、足能侍立在王宫里的，要教他们迦勒底的文字言语。","notes":[]},{"n":5,"t":"王派定将自己所用的膳和所饮的酒，每日赐他们一分，养他们三年。满了三年，好叫他们在王面前侍立。","notes":[]},{"n":6,"t":"他们中间有犹大族的人：但以理、哈拿尼雅、米沙利、亚撒利雅。","notes":[]},{"n":7,"t":"太监长给他们起名：称但以理为伯提沙撒，称哈拿尼雅为沙得拉，称米沙利为米煞，称亚撒利雅为亚伯尼歌。","notes":[]},{"n":8,"t":"但以理却立志不以王的膳和王所饮的酒玷污自己，所以求太监长容他不玷污自己。","notes":[]},{"n":9,"t":"神使但以理在太监长眼前蒙恩惠，受怜悯。","notes":[]},{"n":10,"t":"太监长对但以理说：「我惧怕我主我王，他已经派定你们的饮食，倘若他见你们的面貌比你们同岁的少年人肌瘦，怎么好呢？这样，你们就使我的头在王那里难保。」","notes":[]},{"n":11,"t":"但以理对太监长所派管理但以理、哈拿尼雅、米沙利、亚撒利雅的委办说：","notes":[]},{"n":12,"t":"「求你试试仆人们十天，给我们素菜吃，白水喝，","notes":[]},{"n":13,"t":"然后看看我们的面貌和用王膳那少年人的面貌，就照你所看的待仆人吧！」","notes":[]},{"n":14,"t":"委办便允准他们这件事，试看他们十天。","notes":[]},{"n":15,"t":"过了十天，见他们的面貌比用王膳的一切少年人更加俊美肥胖。","notes":[]},{"n":16,"t":"于是委办撤去派他们用的膳，饮的酒，给他们素菜吃。","notes":[]},{"n":17,"t":"这四个少年人，神在各样文字学问上赐给他们聪明知识；但以理又明白各样的异象和梦兆。","notes":["学问：原文是智慧"]},{"n":18,"t":"尼布甲尼撒王预定带进少年人来的日期满了，太监长就把他们带到王面前。","notes":[]},{"n":19,"t":"王与他们谈论，见少年人中无一人能比但以理、哈拿尼雅、米沙利、亚撒利雅，所以留他们在王面前侍立。","notes":[]},{"n":20,"t":"王考问他们一切事，就见他们的智慧聪明比通国的术士和用法术的胜过十倍。","notes":[]},{"n":21,"t":"到塞鲁士王元年，但以理还在。","notes":[]}]},"2":{"heading":"神把梦的意思指示但以理","verses":[{"n":1,"t":"尼布甲尼撒在位第二年，他做了梦，心里烦乱，不能睡觉。","notes":[]},{"n":2,"t":"王吩咐人将术士、用法术的、行邪术的，和迦勒底人召来，要他们将王的梦告诉王，他们就来站在王前。","notes":[]},{"n":3,"t":"王对他们说：「我做了一梦，心里烦乱，要知道这是什么梦。」","notes":[]},{"n":4,"t":"迦勒底人用亚兰的言语对王说：「愿王万岁！请将那梦告诉仆人，仆人就可以讲解。」","notes":[]},{"n":5,"t":"王回答迦勒底人说：「梦我已经忘了，你们若不将梦和梦的讲解告诉我，就必被凌迟，你们的房屋必成为粪堆；","notes":["或译：我已定命；八节同"]},{"n":6,"t":"你们若将梦和梦的讲解告诉我，就必从我这里得赠品和赏赐，并大尊荣。现在你们要将梦和梦的讲解告诉我。」","notes":[]},{"n":7,"t":"他们第二次对王说：「请王将梦告诉仆人，仆人就可以讲解。」","notes":[]},{"n":8,"t":"王回答说：「我准知道你们是故意迟延，因为你们知道那梦我已经忘了。","notes":[]},{"n":9,"t":"你们若不将梦告诉我，只有一法待你们；因为你们预备了谎言乱语向我说，要等候时势改变。现在你们要将梦告诉我，因我知道你们能将梦的讲解告诉我。」","notes":[]},{"n":10,"t":"迦勒底人在王面前回答说：「世上没有人能将王所问的事说出来；因为没有君王、大臣、掌权的向术士，或用法术的，或迦勒底人问过这样的事。","notes":[]},{"n":11,"t":"王所问的事甚难。除了不与世人同居的神明，没有人在王面前能说出来。」","notes":[]},{"n":12,"t":"因此，王气忿忿地大发烈怒，吩咐灭绝巴比伦所有的哲士。","notes":[]},{"n":13,"t":"于是命令发出，哲士将要见杀，人就寻找但以理和他的同伴，要杀他们。","notes":[]},{"n":14,"t":"王的护卫长亚略出来，要杀巴比伦的哲士，但以理就用婉言回答他，","notes":[]},{"n":15,"t":"向王的护卫长亚略说：「王的命令为何这样紧急呢？」亚略就将情节告诉但以理。","notes":[]},{"n":16,"t":"但以理遂进去求王宽限，就可以将梦的讲解告诉王。","notes":[]},{"n":17,"t":"但以理回到他的居所，将这事告诉他的同伴哈拿尼雅、米沙利、亚撒利雅，","notes":[]},{"n":18,"t":"要他们祈求天上的神施怜悯，将这奥秘的事指明，免得但以理和他的同伴与巴比伦其余的哲士一同灭亡。","notes":[]},{"n":19,"t":"这奥秘的事就在夜间异象中给但以理显明，但以理便称颂天上的神。","notes":[]},{"n":20,"t":"但以理说：「神的名是应当称颂的！从亘古直到永远，因为智慧能力都属乎他。","notes":[]},{"n":21,"t":"他改变时候、日期，废王，立王，将智慧赐与智慧人，将知识赐与聪明人。","notes":[]},{"n":22,"t":"他显明深奥隐秘的事，知道暗中所有的，光明也与他同居。","notes":[]},{"n":23,"t":"我列祖的神啊，我感谢你，赞美你；因你将智慧才能赐给我，允准我们所求的，把王的事给我们指明。」","notes":[]},{"n":24,"t":"于是，但以理进去见亚略，就是王所派灭绝巴比伦哲士的，对他说：「不要灭绝巴比伦的哲士，求你领我到王面前，我要将梦的讲解告诉王。」","notes":[],"heads":["但以理为王解梦"]},{"n":25,"t":"亚略就急忙将但以理领到王面前，对王说：「我在被掳的犹大人中遇见一人，他能将梦的讲解告诉王。」","notes":[]},{"n":26,"t":"王问称为伯提沙撒的但以理说：「你能将我所做的梦和梦的讲解告诉我吗？」","notes":[]},{"n":27,"t":"但以理在王面前回答说：「王所问的那奥秘事，哲士、用法术的、术士、观兆的都不能告诉王，","notes":[]},{"n":28,"t":"只有一位在天上的神能显明奥秘的事。他已将日后必有的事指示尼布甲尼撒王。你的梦和你在床上脑中的异象是这样：","notes":[]},{"n":29,"t":"王啊，你在床上想到后来的事，那显明奥秘事的主把将来必有的事指示你。","notes":[]},{"n":30,"t":"至于那奥秘的事显明给我，并非因我的智慧胜过一切活人，乃为使王知道梦的讲解和心里的思念。","notes":[]},{"n":31,"t":"「王啊，你梦见一个大像，这像甚高，极其光耀，站在你面前，形状甚是可怕。","notes":[]},{"n":32,"t":"这像的头是精金的，胸膛和膀臂是银的，肚腹和腰是铜的，","notes":[]},{"n":33,"t":"腿是铁的，脚是半铁半泥的。","notes":[]},{"n":34,"t":"你观看，见有一块非人手凿出来的石头打在这像半铁半泥的脚上，把脚砸碎；","notes":[]},{"n":35,"t":"于是金、银、铜、铁、泥都一同砸得粉碎，成如夏天禾场上的糠秕，被风吹散，无处可寻。打碎这像的石头变成一座大山，充满天下。","notes":[]},{"n":36,"t":"「这就是那梦；我们在王面前要讲解那梦。","notes":[]},{"n":37,"t":"王啊，你是诸王之王。天上的神已将国度、权柄、能力、尊荣都赐给你。","notes":[]},{"n":38,"t":"凡世人所住之地的走兽，并天空的飞鸟，他都交付你手，使你掌管这一切。你就是那金头。","notes":[]},{"n":39,"t":"在你以后必另兴一国，不及于你；又有第三国，就是铜的，必掌管天下。","notes":[]},{"n":40,"t":"第四国，必坚壮如铁，铁能打碎克制百物，又能压碎一切，那国也必打碎压制列国。","notes":[]},{"n":41,"t":"你既见像的脚和脚指头，一半是窑匠的泥，一半是铁，那国将来也必分开。你既见铁与泥搀杂，那国也必有铁的力量。","notes":[]},{"n":42,"t":"那脚指头，既是半铁半泥，那国也必半强半弱。","notes":[]},{"n":43,"t":"你既见铁与泥搀杂，那国民也必与各种人搀杂，却不能彼此相合，正如铁与泥不能相合一样。","notes":[]},{"n":44,"t":"当那列王在位的时候，天上的神必另立一国，永不败坏，也不归别国的人，却要打碎灭绝那一切国，这国必存到永远。","notes":[]},{"n":45,"t":"你既看见非人手凿出来的一块石头从山而出，打碎金、银、铜、铁、泥，那就是至大的神把后来必有的事给王指明。这梦准是这样，这讲解也是确实的。」","notes":[]},{"n":46,"t":"当时，尼布甲尼撒王俯伏在地，向但以理下拜，并且吩咐人给他奉上供物和香品。","notes":[],"heads":["王奖赏但以理"]},{"n":47,"t":"王对但以理说：「你既能显明这奥秘的事，你们的神诚然是万神之神、万王之主，又是显明奥秘事的。」","notes":[]},{"n":48,"t":"于是王高抬但以理，赏赐他许多上等礼物，派他管理巴比伦全省，又立他为总理，掌管巴比伦的一切哲士。","notes":[]},{"n":49,"t":"但以理求王，王就派沙得拉、米煞、亚伯尼歌管理巴比伦省的事务，只是但以理常在朝中侍立。","notes":[]}]},"3":{"heading":"尼布甲尼撒下令拜金像","verses":[{"n":1,"t":"尼布甲尼撒王造了一个金像，高六十肘，宽六肘，立在巴比伦省杜拉平原。","notes":[]},{"n":2,"t":"尼布甲尼撒王差人将总督、钦差、巡抚、臬司、藩司、谋士、法官，和各省的官员都召了来，为尼布甲尼撒王所立的像行开光之礼。","notes":[]},{"n":3,"t":"于是总督、钦差、巡抚、臬司、藩司、谋士、法官，和各省的官员都聚集了来，要为尼布甲尼撒王所立的像行开光之礼，就站在尼布甲尼撒所立的像前。","notes":[]},{"n":4,"t":"那时传令的大声呼叫说：「各方、各国、各族的人哪，有令传与你们：","notes":["原文是舌；下同"]},{"n":5,"t":"你们一听见角、笛、琵琶、琴、瑟、笙，和各样乐器的声音，就当俯伏敬拜尼布甲尼撒王所立的金像。","notes":[]},{"n":6,"t":"凡不俯伏敬拜的，必立时扔在烈火的窑中。」","notes":[]},{"n":7,"t":"因此各方、各国、各族的人民一听见角、笛、琵琶、琴、瑟，和各样乐器的声音，就都俯伏敬拜尼布甲尼撒王所立的金像。","notes":[]},{"n":8,"t":"那时，有几个迦勒底人进前来控告犹大人。","notes":[],"heads":["但以理的三个朋友被控违令"]},{"n":9,"t":"他们对尼布甲尼撒王说：「愿王万岁！","notes":[]},{"n":10,"t":"王啊，你曾降旨说，凡听见角、笛、琵琶、琴、瑟、笙，和各样乐器声音的都当俯伏敬拜金像。","notes":[]},{"n":11,"t":"凡不俯伏敬拜的，必扔在烈火的窑中。","notes":[]},{"n":12,"t":"现在有几个犹大人，就是王所派管理巴比伦省事务的沙得拉、米煞、亚伯尼歌；王啊，这些人不理你，不事奉你的神，也不敬拜你所立的金像。」","notes":[]},{"n":13,"t":"当时，尼布甲尼撒冲冲大怒，吩咐人把沙得拉、米煞、亚伯尼歌带过来，他们就把那些人带到王面前。","notes":[]},{"n":14,"t":"尼布甲尼撒问他们说：「沙得拉、米煞、亚伯尼歌，你们不事奉我的神，也不敬拜我所立的金像，是故意的吗？","notes":[]},{"n":15,"t":"你们再听见角、笛、琵琶、琴、瑟、笙，和各样乐器的声音，若俯伏敬拜我所造的像，却还可以；若不敬拜，必立时扔在烈火的窑中，有何神能救你们脱离我手呢？」","notes":[]},{"n":16,"t":"沙得拉、米煞、亚伯尼歌对王说：「尼布甲尼撒啊，这件事我们不必回答你，","notes":[]},{"n":17,"t":"即便如此，我们所事奉的神能将我们从烈火的窑中救出来。王啊，他也必救我们脱离你的手；","notes":[]},{"n":18,"t":"即或不然，王啊，你当知道我们决不事奉你的神，也不敬拜你所立的金像。」","notes":[]},{"n":19,"t":"当时，尼布甲尼撒怒气填胸，向沙得拉、米煞、亚伯尼歌变了脸色，吩咐人把窑烧热，比寻常更加七倍；","notes":[],"heads":["但以理的三个朋友被扔进火窑"]},{"n":20,"t":"又吩咐他军中的几个壮士，将沙得拉、米煞、亚伯尼歌捆起来，扔在烈火的窑中。","notes":[]},{"n":21,"t":"这三人穿着裤子、内袍、外衣，和别的衣服，被捆起来扔在烈火的窑中。","notes":[]},{"n":22,"t":"因为王命紧急，窑又甚热，那抬沙得拉、米煞、亚伯尼歌的人都被火焰烧死。","notes":[]},{"n":23,"t":"沙得拉、米煞、亚伯尼歌这三个人都被捆着落在烈火的窑中。","notes":[]},{"n":24,"t":"那时，尼布甲尼撒王惊奇，急忙起来，对谋士说：「我们捆起来扔在火里的不是三个人吗？」他们回答王说：「王啊，是。」","notes":[]},{"n":25,"t":"王说：「看哪，我见有四个人，并没有捆绑，在火中游行，也没有受伤；那第四个的相貌好像神子。」","notes":[]},{"n":26,"t":"于是，尼布甲尼撒就近烈火窑门，说：「至高神的仆人沙得拉、米煞、亚伯尼歌出来，上这里来吧！」沙得拉、米煞、亚伯尼歌就从火中出来了。","notes":[],"heads":["三人获释且得高升"]},{"n":27,"t":"那些总督、钦差、巡抚，和王的谋士一同聚集看这三个人，见火无力伤他们的身体，头发也没有烧焦，衣裳也没有变色，并没有火燎的气味。","notes":[]},{"n":28,"t":"尼布甲尼撒说：「沙得拉、米煞、亚伯尼歌的神是应当称颂的！他差遣使者救护倚靠他的仆人，他们不遵王命，舍去己身，在他们神以外不肯事奉敬拜别神。","notes":[]},{"n":29,"t":"现在我降旨，无论何方、何国、何族的人，谤讟沙得拉、米煞、亚伯尼歌之神的，必被凌迟，他的房屋必成粪堆，因为没有别神能这样施行拯救。」","notes":[]},{"n":30,"t":"那时王在巴比伦省，高升了沙得拉、米煞、亚伯尼歌。","notes":[]}]},"4":{"heading":"尼布甲尼撒的第二个梦","verses":[{"n":1,"t":"尼布甲尼撒王晓谕住在全地各方、各国、各族的人说：「愿你们大享平安！","notes":[]},{"n":2,"t":"我乐意将至高的神向我所行的神迹奇事宣扬出来。","notes":[]},{"n":3,"t":"他的神迹何其大！他的奇事何其盛！他的国是永远的；他的权柄存到万代！","notes":[]},{"n":4,"t":"「我—尼布甲尼撒安居在宫中，平顺在殿内。","notes":[]},{"n":5,"t":"我做了一梦，使我惧怕。我在床上的思念，并脑中的异象，使我惊惶。","notes":[]},{"n":6,"t":"所以我降旨召巴比伦的一切哲士到我面前，叫他们把梦的讲解告诉我。","notes":[]},{"n":7,"t":"于是那些术士、用法术的、迦勒底人、观兆的都进来，我将那梦告诉了他们，他们却不能把梦的讲解告诉我。","notes":[]},{"n":8,"t":"末后那照我神的名，称为伯提沙撒的但以理来到我面前，他里头有圣神的灵，我将梦告诉他说：","notes":[]},{"n":9,"t":"『术士的领袖伯提沙撒啊，因我知道你里头有圣神的灵，什么奥秘的事都不能使你为难。现在要把我梦中所见的异象和梦的讲解告诉我。』","notes":[]},{"n":10,"t":"「我在床上脑中的异象是这样：我看见地当中有一棵树，极其高大。","notes":[]},{"n":11,"t":"那树渐长，而且坚固，高得顶天，从地极都能看见，","notes":[]},{"n":12,"t":"叶子华美，果子甚多，可作众生的食物；田野的走兽卧在荫下，天空的飞鸟宿在枝上；凡有血气的都从这树得食。","notes":[]},{"n":13,"t":"「我在床上脑中的异象，见有一位守望的圣者从天而降。","notes":[]},{"n":14,"t":"大声呼叫说：『伐倒这树！砍下枝子！摇掉叶子！抛散果子！使走兽离开树下，飞鸟躲开树枝。","notes":[]},{"n":15,"t":"树丕却要留在地内，用铁圈和铜圈箍住，在田野的青草中让天露滴湿，使他与地上的兽一同吃草，","notes":[]},{"n":16,"t":"使他的心改变，不如人心，给他一个兽心，使他经过七期。","notes":["期：或译年；本章同"]},{"n":17,"t":"这是守望者所发的命，圣者所出的令，好叫世人知道至高者在人的国中掌权，要将国赐与谁就赐与谁，或立极卑微的人执掌国权。』","notes":[]},{"n":18,"t":"「这是我—尼布甲尼撒王所做的梦。伯提沙撒啊，你要说明这梦的讲解；因为我国中的一切哲士都不能将梦的讲解告诉我，惟独你能，因你里头有圣神的灵。」","notes":[]},{"n":19,"t":"于是称为伯提沙撒的但以理惊讶片时，心意惊惶。王说：「伯提沙撒啊，不要因梦和梦的讲解惊惶。」伯提沙撒回答说：「我主啊，愿这梦归与恨恶你的人，讲解归与你的敌人。","notes":[],"heads":["但以理解梦"]},{"n":20,"t":"你所见的树渐长，而且坚固，高得顶天，从地极都能看见；","notes":[]},{"n":21,"t":"叶子华美，果子甚多，可作众生的食物；田野的走兽住在其下；天空的飞鸟宿在枝上。","notes":[]},{"n":22,"t":"「王啊，这渐长又坚固的树就是你。你的威势渐长及天，你的权柄管到地极。","notes":[]},{"n":23,"t":"王既看见一位守望的圣者从天而降，说：『将这树砍伐毁坏，树丕却要留在地内，用铁圈和铜圈箍住；在田野的青草中，让天露滴湿，使他与地上的兽一同吃草，直到经过七期。』","notes":[]},{"n":24,"t":"「王啊，讲解就是这样：临到我主我王的事是出于至高者的命。","notes":[]},{"n":25,"t":"你必被赶出离开世人，与野地的兽同居，吃草如牛，被天露滴湿，且要经过七期。等你知道至高者在人的国中掌权，要将国赐与谁就赐与谁。","notes":[]},{"n":26,"t":"守望者既吩咐存留树丕，等你知道诸天掌权，以后你的国必定归你。","notes":[]},{"n":27,"t":"王啊，求你悦纳我的谏言，以施行公义断绝罪过，以怜悯穷人除掉罪孽，或者你的平安可以延长。」","notes":[]},{"n":28,"t":"这事都临到尼布甲尼撒王。","notes":[]},{"n":29,"t":"过了十二个月，他游行在巴比伦王宫里。","notes":["原文是上"]},{"n":30,"t":"他说：「这大巴比伦不是我用大能大力建为京都，要显我威严的荣耀吗？」","notes":[]},{"n":31,"t":"这话在王口中尚未说完，有声音从天降下，说：「尼布甲尼撒王啊，有话对你说，你的国位离开你了。","notes":[]},{"n":32,"t":"你必被赶出离开世人，与野地的兽同居，吃草如牛，且要经过七期。等你知道至高者在人的国中掌权，要将国赐与谁就赐与谁。」","notes":[]},{"n":33,"t":"当时这话就应验在尼布甲尼撒的身上，他被赶出离开世人，吃草如牛，身被天露滴湿，头发长长，好像鹰毛；指甲长长，如同鸟爪。","notes":[]},{"n":34,"t":"日子满足，我—尼布甲尼撒举目望天，我的聪明复归于我，我便称颂至高者，赞美尊敬活到永远的神。他的权柄是永有的；他的国存到万代。","notes":[],"heads":["尼布甲尼撒颂赞神"]},{"n":35,"t":"世上所有的居民都算为虚无；在天上的万军和世上的居民中，他都凭自己的意旨行事。无人能拦住他手，或问他说，你做什么呢？","notes":[]},{"n":36,"t":"那时，我的聪明复归于我，为我国的荣耀、威严，和光耀也都复归于我；并且我的谋士和大臣也来朝见我。我又得坚立在国位上，至大的权柄加增于我。","notes":[]},{"n":37,"t":"现在我—尼布甲尼撒赞美、尊崇、恭敬天上的王；因为他所做的全都诚实，他所行的也都公平。那行动骄傲的，他能降为卑。","notes":[]}]},"5":{"heading":"伯沙撒王的宴会","verses":[{"n":1,"t":"伯沙撒王为他的一千大臣设摆盛筵，与这一千人对面饮酒。","notes":[]},{"n":2,"t":"伯沙撒欢饮之间，吩咐人将他父尼布甲尼撒从耶路撒冷殿中所掠的金银器皿拿来，王与大臣、皇后、妃嫔好用这器皿饮酒。","notes":["或译：祖；下同"]},{"n":3,"t":"于是他们把耶路撒冷神殿库房中所掠的金器皿拿来，王和大臣、皇后、妃嫔就用这器皿饮酒。","notes":[]},{"n":4,"t":"他们饮酒，赞美金、银、铜、铁、木、石所造的神。","notes":[]},{"n":5,"t":"当时，忽有人的指头显出，在王宫与灯台相对的粉墙上写字。王看见写字的指头","notes":[]},{"n":6,"t":"就变了脸色，心意惊惶，腰骨好像脱节，双膝彼此相碰，","notes":[]},{"n":7,"t":"大声吩咐将用法术的和迦勒底人并观兆的领进来，对巴比伦的哲士说，谁能读这文字，把讲解告诉我，他必身穿紫袍，项带金链，在我国中位列第三。","notes":[]},{"n":8,"t":"于是王的一切哲士都进来，却不能读那文字，也不能把讲解告诉王。","notes":[]},{"n":9,"t":"伯沙撒王就甚惊惶，脸色改变，他的大臣也都惊奇。","notes":[]},{"n":10,"t":"太后因王和他大臣所说的话，就进入宴宫，说：「愿王万岁！你心意不要惊惶，脸面不要变色。","notes":["或译：皇后；下同"]},{"n":11,"t":"在你国中有一人，他里头有圣神的灵，你父在世的日子，这人心中光明，又有聪明智慧，好像神的智慧。你父尼布甲尼撒王，就是王的父，立他为术士、用法术的，和迦勒底人，并观兆的领袖。","notes":[]},{"n":12,"t":"在他里头有美好的灵性，又有知识聪明，能圆梦，释谜语，解疑惑。这人名叫但以理，尼布甲尼撒王又称他为伯提沙撒，现在可以召他来，他必解明这意思。」","notes":[]},{"n":13,"t":"但以理就被领到王前。王问但以理说：「你是被掳之犹大人中的但以理吗？就是我父王从犹大掳来的吗？","notes":[],"heads":["但以理解释墙上的字"]},{"n":14,"t":"我听说你里头有神的灵，心中光明，又有聪明和美好的智慧。","notes":[]},{"n":15,"t":"现在哲士和用法术的都领到我面前，为叫他们读这文字，把讲解告诉我，无奈他们都不能把讲解说出来。","notes":[]},{"n":16,"t":"我听说你善于讲解，能解疑惑；现在你若能读这文字，把讲解告诉我，就必身穿紫袍，项戴金链，在我国中位列第三。」","notes":[]},{"n":17,"t":"但以理在王面前回答说：「你的赠品可以归你自己，你的赏赐可以归给别人；我却要为王读这文字，把讲解告诉王。","notes":[]},{"n":18,"t":"王啊，至高的神曾将国位、大权、荣耀、威严赐与你父尼布甲尼撒；","notes":[]},{"n":19,"t":"因神所赐他的大权，各方、各国、各族的人都在他面前战兢恐惧。他可以随意生杀，随意升降。","notes":[]},{"n":20,"t":"但他心高气傲，灵也刚愎，甚至行事狂傲，就被革去王位，夺去荣耀。","notes":[]},{"n":21,"t":"他被赶出离开世人，他的心变如兽心，与野驴同居，吃草如牛，身被天露滴湿，等他知道至高的神在人的国中掌权，凭自己的意旨立人治国。","notes":[]},{"n":22,"t":"伯沙撒啊，你是他的儿子，你虽知道这一切，你心仍不自卑，","notes":["或译：孙子"]},{"n":23,"t":"竟向天上的主自高，使人将他殿中的器皿拿到你面前，你和大臣、皇后、妃嫔用这器皿饮酒。你又赞美那不能看、不能听、无知无识、金、银、铜、铁、木、石所造的神，却没有将荣耀归与那手中有你气息，管理你一切行动的神。","notes":[]},{"n":24,"t":"因此从神那里显出指头来写这文字。","notes":[]},{"n":25,"t":"「所写的文字是：『弥尼，弥尼，提客勒，乌法珥新。』","notes":[]},{"n":26,"t":"讲解是这样：弥尼，就是神已经数算你国的年日到此完毕。","notes":[]},{"n":27,"t":"提客勒，就是你被称在天平里，显出你的亏欠。","notes":[]},{"n":28,"t":"毗勒斯，就是你的国分裂，归与米底亚人和波斯人。」","notes":["与乌法珥新同义"]},{"n":29,"t":"伯沙撒下令，人就把紫袍给但以理穿上，把金链给他戴在颈项上，又传令使他在国中位列第三。","notes":[]},{"n":30,"t":"当夜，迦勒底王伯沙撒被杀。","notes":[]},{"n":31,"t":"米底亚人大流士年六十二岁，取了迦勒底国。","notes":[]}]},"6":{"heading":"但以理在狮子坑中","verses":[{"n":1,"t":"大流士随心所愿，立一百二十个总督，治理通国。","notes":[]},{"n":2,"t":"又在他们以上立总长三人（但以理在其中），使总督在他们三人面前回复事务，免得王受亏损。","notes":[]},{"n":3,"t":"因这但以理有美好的灵性，所以显然超乎其余的总长和总督，王又想立他治理通国。","notes":[]},{"n":4,"t":"那时，总长和总督寻找但以理误国的把柄，为要参他；只是找不着他的错误过失，因他忠心办事，毫无错误过失。","notes":[]},{"n":5,"t":"那些人便说：「我们要找参这但以理的把柄，除非在他神的律法中就寻不着。」","notes":[]},{"n":6,"t":"于是，总长和总督纷纷聚集来见王，说：「愿大流士王万岁！","notes":[]},{"n":7,"t":"国中的总长、钦差、总督、谋士，和巡抚彼此商议，要立一条坚定的禁令，三十日内，不拘何人，若在王以外，或向神或向人求什么，就必扔在狮子坑中。","notes":["或译：求王下旨要立一条<ins>.</ins>."]},{"n":8,"t":"王啊，现在求你立这禁令，加盖玉玺，使禁令决不更改；照米底亚和波斯人的例是不可更改的。」","notes":[]},{"n":9,"t":"于是大流士王立这禁令，加盖玉玺。","notes":[]},{"n":10,"t":"但以理知道这禁令盖了玉玺，就到自己家里（他楼上的窗户开向耶路撒冷），一日三次，双膝跪在他神面前，祷告感谢，与素常一样。","notes":[]},{"n":11,"t":"那些人就纷纷聚集，见但以理在他神面前祈祷恳求。","notes":[]},{"n":12,"t":"他们便进到王前，提王的禁令，说：「王啊，三十日内不拘何人，若在王以外，或向神或向人求什么，必被扔在狮子坑中。王不是在这禁令上盖了玉玺吗？」王回答说：「实有这事，照米底亚和波斯人的例是不可更改的。」","notes":[]},{"n":13,"t":"他们对王说：「王啊，那被掳之犹大人中的但以理不理你，也不遵你盖了玉玺的禁令，他竟一日三次祈祷。」","notes":[]},{"n":14,"t":"王听见这话，就甚愁烦，一心要救但以理，筹划解救他，直到日落的时候。","notes":[]},{"n":15,"t":"那些人就纷纷聚集来见王，说：「王啊，当知道米底亚人和波斯人有例，凡王所立的禁令和律例都不可更改。」","notes":[]},{"n":16,"t":"王下令，人就把但以理带来，扔在狮子坑中。王对但以理说：「你所常事奉的神，他必救你。」","notes":[]},{"n":17,"t":"有人搬石头放在坑口，王用自己的玺和大臣的印，封闭那坑，使惩办但以理的事毫无更改。","notes":[]},{"n":18,"t":"王回宫，终夜禁食，无人拿乐器到他面前，并且睡不着觉。","notes":[]},{"n":19,"t":"次日黎明，王就起来，急忙往狮子坑那里去。","notes":[]},{"n":20,"t":"临近坑边，哀声呼叫但以理，对但以理说：「永生神的仆人但以理啊，你所常事奉的神能救你脱离狮子吗？」","notes":[]},{"n":21,"t":"但以理对王说：「愿王万岁！","notes":[]},{"n":22,"t":"我的神差遣使者，封住狮子的口，叫狮子不伤我；因我在神面前无辜，我在王面前也没有行过亏损的事。」","notes":[]},{"n":23,"t":"王就甚喜乐，吩咐人将但以理从坑里系上来。于是但以理从坑里被系上来，身上毫无伤损，因为信靠他的神。","notes":[]},{"n":24,"t":"王下令，人就把那些控告但以理的人，连他们的妻子儿女都带来，扔在狮子坑中。他们还没有到坑底，狮子就抓住他们，咬碎他们的骨头。","notes":["原文是胜了"]},{"n":25,"t":"那时，大流士王传旨，晓谕住在全地各方、各国、各族的人说：「愿你们大享平安！","notes":[]},{"n":26,"t":"现在我降旨晓谕我所统辖的全国人民，要在但以理的神面前，战兢恐惧。因为他是永远长存的活神，他的国永不败坏；他的权柄永存无极！","notes":[]},{"n":27,"t":"他护庇人，搭救人，在天上地下施行神迹奇事，救了但以理脱离狮子的口。」","notes":[]},{"n":28,"t":"如此，这但以理，当大流士王在位的时候和波斯王塞鲁士在位的时候，大享亨通。","notes":[]}]},"7":{"heading":"但以理叙述异象","verses":[{"n":1,"t":"巴比伦王伯沙撒元年，但以理在床上做梦，见了脑中的异象，就记录这梦，述说其中的大意。","notes":[],"heads":["四兽的异象"]},{"n":2,"t":"但以理说：我夜里见异象，看见天的四风陡起，刮在大海之上。","notes":[]},{"n":3,"t":"有四个大兽从海中上来，形状各有不同：","notes":[]},{"n":4,"t":"头一个像狮子，有鹰的翅膀；我正观看的时候，兽的翅膀被拔去，兽从地上得立起来，用两脚站立，像人一样，又得了人心。","notes":[]},{"n":5,"t":"又有一兽如熊，就是第二兽，旁跨而坐，口齿内衔着三根肋骨。有吩咐这兽的说：「起来吞吃多肉。」","notes":[]},{"n":6,"t":"此后我观看，又有一兽如豹，背上有鸟的四个翅膀；这兽有四个头，又得了权柄。","notes":[]},{"n":7,"t":"其后我在夜间的异象中观看，见第四兽甚是可怕，极其强壮，大有力量，有大铁牙，吞吃嚼碎，所剩下的用脚践踏。这兽与前三兽大不相同，头有十角。","notes":[]},{"n":8,"t":"我正观看这些角，见其中又长起一个小角；先前的角中有三角在这角前，连根被它拔出来。这角有眼，像人的眼，有口说夸大的话。","notes":[]},{"n":9,"t":"我观看，见有宝座设立，上头坐着亘古常在者。他的衣服洁白如雪，头发如纯净的羊毛。宝座乃火焰，其轮乃烈火。","notes":[],"heads":["永存者的异象"]},{"n":10,"t":"从他面前有火，像河发出；事奉他的有千千，在他面前侍立的有万万；他坐着要行审判，案卷都展开了。","notes":[]},{"n":11,"t":"那时我观看，见那兽因小角说夸大话的声音被杀，身体损坏，扔在火中焚烧。","notes":[]},{"n":12,"t":"其余的兽，权柄都被夺去，生命却仍存留，直到所定的时候和日期。","notes":[]},{"n":13,"t":"我在夜间的异象中观看，见有一位像人子的，驾着天云而来，被领到亘古常在者面前，","notes":[]},{"n":14,"t":"得了权柄、荣耀、国度，使各方、各国、各族的人都事奉他。他的权柄是永远的，不能废去；他的国必不败坏。","notes":[]},{"n":15,"t":"至于我—但以理，我的灵在我里面愁烦，我脑中的异象使我惊惶。","notes":[],"heads":["解释异象"]},{"n":16,"t":"我就近一位侍立者，问他这一切的真情。他就告诉我，将那事的讲解给我说明：","notes":[]},{"n":17,"t":"这四个大兽就是四王将要在世上兴起。","notes":[]},{"n":18,"t":"然而，至高者的圣民，必要得国享受，直到永永远远。","notes":[]},{"n":19,"t":"那时我愿知道第四兽的真情，它为何与那三兽的真情大不相同，甚是可怕，有铁牙铜爪，吞吃嚼碎，所剩下的用脚践踏；","notes":[]},{"n":20,"t":"头有十角和那另长的一角，在这角前有三角被它打落。这角有眼，有说夸大话的口，形状强横，过于它的同类。","notes":[]},{"n":21,"t":"我观看，见这角与圣民争战，胜了他们。","notes":[]},{"n":22,"t":"直到亘古常在者来给至高者的圣民伸冤，圣民得国的时候就到了。","notes":[]},{"n":23,"t":"那侍立者这样说：第四兽就是世上必有的第四国，与一切国大不相同，必吞吃全地，并且践踏嚼碎。","notes":[]},{"n":24,"t":"至于那十角，就是从这国中必兴起的十王，后来又兴起一王，与先前的不同；他必制伏三王。","notes":[]},{"n":25,"t":"他必向至高者说夸大的话，必折磨至高者的圣民，必想改变节期和律法。圣民必交付他手一载、二载、半载。","notes":[]},{"n":26,"t":"然而，审判者必坐着行审判；他的权柄必被夺去，毁坏，灭绝，一直到底。","notes":[]},{"n":27,"t":"国度、权柄，和天下诸国的大权必赐给至高者的圣民。他的国是永远的；一切掌权的都必事奉他，顺从他。","notes":[]},{"n":28,"t":"那事至此完毕。至于我—但以理，心中甚是惊惶，脸色也改变了，却将那事存记在心。","notes":[]}]},"8":{"heading":"公绵羊、公山羊的异象","verses":[{"n":1,"t":"伯沙撒王在位第三年，有异象现与我—但以理，是在先前所见的异象之后。","notes":[]},{"n":2,"t":"我见了异象的时候，我以为在以拦省书珊城中；我见异象又如在乌莱河边。","notes":["或译：宫"]},{"n":3,"t":"我举目观看，见有双角的公绵羊站在河边，两角都高。这角高过那角，更高的是后长的。","notes":[]},{"n":4,"t":"我见那公绵羊往西、往北、往南抵触。兽在它面前都站立不住，也没有能救护脱离它手的；但它任意而行，自高自大。","notes":[]},{"n":5,"t":"我正思想的时候，见有一只公山羊从西而来，遍行全地，脚不沾尘。这山羊两眼当中有一非常的角。","notes":[]},{"n":6,"t":"它往我所看见、站在河边有双角的公绵羊那里去，大发忿怒，向它直闯。","notes":[]},{"n":7,"t":"我见公山羊就近公绵羊，向它发烈怒，抵触它，折断它的两角。绵羊在它面前站立不住；它将绵羊触倒在地，用脚践踏，没有能救绵羊脱离它手的。","notes":[]},{"n":8,"t":"这山羊极其自高自大，正强盛的时候，那大角折断了，又在角根上向天的四方长出四个非常的角来。","notes":["原文是风"]},{"n":9,"t":"四角之中有一角长出一个小角，向南、向东、向荣美之地，渐渐成为强大。","notes":[]},{"n":10,"t":"它渐渐强大，高及天象，将些天象和星宿抛落在地，用脚践踏。","notes":[]},{"n":11,"t":"并且它自高自大，以为高及天象之君；除掉常献给君的燔祭，毁坏君的圣所。","notes":[]},{"n":12,"t":"因罪过的缘故，有军旅和常献的燔祭交付它。它将真理抛在地上，任意而行，无不顺利。","notes":[]},{"n":13,"t":"我听见有一位圣者说话，又有一位圣者问那说话的圣者说：「这除掉常献的燔祭和施行毁坏的罪过，将圣所与军旅践踏的异象，要到几时才应验呢？」","notes":["或译：以色列的军"]},{"n":14,"t":"他对我说：「到二千三百日，圣所就必洁净。」","notes":[]},{"n":15,"t":"我—但以理见了这异象，愿意明白其中的意思。忽有一位形状像人的站在我面前。","notes":[],"heads":["天使加百列解释异象"]},{"n":16,"t":"我又听见乌莱河两岸中有人声呼叫说：「加百列啊，要使此人明白这异象。」","notes":[]},{"n":17,"t":"他便来到我所站的地方。他一来，我就惊慌俯伏在地；他对我说：「人子啊，你要明白，因为这是关乎末后的异象。」","notes":[]},{"n":18,"t":"他与我说话的时候，我面伏在地沉睡；他就摸我，扶我站起来，","notes":[]},{"n":19,"t":"说：「我要指示你恼怒临完必有的事，因为这是关乎末后的定期。","notes":[]},{"n":20,"t":"你所看见双角的公绵羊，就是米底亚和波斯王。","notes":[]},{"n":21,"t":"那公山羊就是希腊王；两眼当中的大角就是头一王。","notes":["希腊：原文是雅完；下同"]},{"n":22,"t":"至于那折断了的角，在其根上又长出四角，这四角就是四国，必从这国里兴起来，只是权势都不及他。","notes":[]},{"n":23,"t":"这四国末时，犯法的人罪恶满盈，必有一王兴起，面貌凶恶，能用双关的诈语。","notes":[]},{"n":24,"t":"他的权柄必大，却不是因自己的能力；他必行非常的毁灭，事情顺利，任意而行；又必毁灭有能力的和圣民。","notes":[]},{"n":25,"t":"他用权术成就手中的诡计，心里自高自大，在人坦然无备的时候，毁灭多人；又要站起来攻击万君之君，至终却非因人手而灭亡。","notes":[]},{"n":26,"t":"所说二千三百日的异象是真的，但你要将这异象封住，因为关乎后来许多的日子。」","notes":[]},{"n":27,"t":"于是我—但以理昏迷不醒，病了数日，然后起来办理王的事务。我因这异象惊奇，却无人能明白其中的意思。","notes":[]}]},"9":{"heading":"但以理为同胞祷告","verses":[{"n":1,"t":"米底亚族亚哈随鲁的儿子大流士立为迦勒底国的王元年，","notes":[]},{"n":2,"t":"就是他在位第一年，我—但以理从书上得知耶和华的话临到先知耶利米，论耶路撒冷荒凉的年数，七十年为满。","notes":[]},{"n":3,"t":"我便禁食，披麻蒙灰，定意向主神祈祷恳求。","notes":[]},{"n":4,"t":"我向耶和华—我的神祈祷、认罪，说：「主啊，大而可畏的神，向爱主、守主诫命的人守约施慈爱。","notes":[]},{"n":5,"t":"我们犯罪作孽，行恶叛逆，偏离你的诫命典章，","notes":[]},{"n":6,"t":"没有听从你仆人众先知奉你名向我们君王、首领、列祖，和国中一切百姓所说的话。","notes":[]},{"n":7,"t":"主啊，你是公义的，我们是脸上蒙羞的；因我们犹大人和耶路撒冷的居民，并以色列众人，或在近处，或在远处，被你赶到各国的人，都得罪了你，正如今日一样。","notes":[]},{"n":8,"t":"主啊，我们和我们的君王、首领、列祖因得罪了你，就都脸上蒙羞。","notes":[]},{"n":9,"t":"主—我们的神是怜悯饶恕人的，我们却违背了他，","notes":[]},{"n":10,"t":"也没有听从耶和华—我们神的话，没有遵行他借仆人众先知向我们所陈明的律法。","notes":[]},{"n":11,"t":"以色列众人都犯了你的律法，偏行，不听从你的话；因此，在你仆人摩西律法上所写的咒诅和誓言都倾在我们身上，因我们得罪了神。","notes":[]},{"n":12,"t":"他使大灾祸临到我们，成就了警戒我们和审判我们官长的话；原来在普天之下未曾行过像在耶路撒冷所行的。","notes":[]},{"n":13,"t":"这一切灾祸临到我们身上是照摩西律法上所写的，我们却没有求耶和华—我们神的恩典，使我们回头离开罪孽，明白你的真理。","notes":[]},{"n":14,"t":"所以耶和华留意使这灾祸临到我们身上，因为耶和华—我们的神在他所行的事上都是公义；我们并没有听从他的话。","notes":[]},{"n":15,"t":"主—我们的神啊，你曾用大能的手领你的子民出埃及地，使自己得了名，正如今日一样。我们犯了罪，作了恶。","notes":[]},{"n":16,"t":"主啊，求你按你的大仁大义，使你的怒气和忿怒转离你的城耶路撒冷，就是你的圣山。耶路撒冷和你的子民，因我们的罪恶和我们列祖的罪孽被四围的人羞辱。","notes":[]},{"n":17,"t":"我们的神啊，现在求你垂听仆人的祈祷恳求，为自己使脸光照你荒凉的圣所。","notes":[]},{"n":18,"t":"我的神啊，求你侧耳而听，睁眼而看，眷顾我们荒凉之地和称为你名下的城。我们在你面前恳求，原不是因自己的义，乃因你的大怜悯。","notes":[]},{"n":19,"t":"求主垂听，求主赦免，求主应允而行，为你自己不要迟延。我的神啊，因这城和这民都是称为你名下的。」","notes":[]},{"n":20,"t":"我说话，祷告，承认我的罪和本国之民以色列的罪，为我神的圣山，在耶和华—我神面前恳求。","notes":[],"heads":["加百列解释预言"]},{"n":21,"t":"我正祷告的时候，先前在异象中所见的那位加百列，奉命迅速飞来，约在献晚祭的时候，按手在我身上。","notes":[]},{"n":22,"t":"他指教我说：「但以理啊，现在我出来要使你有智慧，有聪明。","notes":[]},{"n":23,"t":"你初恳求的时候，就发出命令，我来告诉你，因你大蒙眷爱；所以你要思想明白这以下的事和异象。","notes":[]},{"n":24,"t":"「为你本国之民和你圣城，已经定了七十个七。要止住罪过，除净罪恶，赎尽罪孽，引进永义，封住异象和预言，并膏至圣者。","notes":["或译：彰显","者：或译所"]},{"n":25,"t":"你当知道，当明白，从出令重新建造耶路撒冷，直到有受膏君的时候，必有七个七和六十二个七。正在艰难的时候，耶路撒冷城连街带濠都必重新建造。","notes":[]},{"n":26,"t":"过了六十二个七，那受膏者必被剪除，一无所有；必有一王的民来毁灭这城和圣所，至终必如洪水冲没。必有争战，一直到底，荒凉的事已经定了。","notes":["或译：有"]},{"n":27,"t":"一七之内，他必与许多人坚定盟约；一七之半，他必使祭祀与供献止息。那行毁坏可憎的如飞而来，并且有忿怒倾在那行毁坏的身上，直到所定的结局。」","notes":["或译：使地荒凉的","或译：倾在那荒凉之地"]}]},"10":{"heading":"底格里斯大河边的异象","verses":[{"n":1,"t":"波斯王塞鲁士第三年，有事显给称为伯提沙撒的但以理。这事是真的，是指着大争战；但以理通达这事，明白这异象。","notes":[]},{"n":2,"t":"当那时，我—但以理悲伤了三个七日。","notes":[]},{"n":3,"t":"美味我没有吃，酒肉没有入我的口，也没有用油抹我的身，直到满了三个七日。","notes":[]},{"n":4,"t":"正月二十四日，我在底格里斯大河边，","notes":[]},{"n":5,"t":"举目观看，见有一人身穿细麻衣，腰束乌法精金带。","notes":[]},{"n":6,"t":"他身体如水苍玉，面貌如闪电，眼目如火把，手和脚如光明的铜，说话的声音如大众的声音。","notes":[]},{"n":7,"t":"这异象惟有我—但以理一人看见，同着我的人没有看见。他们却大大战兢，逃跑隐藏，","notes":[]},{"n":8,"t":"只剩下我一人。我见了这大异象便浑身无力，面貌失色，毫无气力。","notes":[]},{"n":9,"t":"我却听见他说话的声音，一听见就面伏在地沉睡了。","notes":[]},{"n":10,"t":"忽然，有一手按在我身上，使我用膝和手掌支持微起。","notes":[]},{"n":11,"t":"他对我说：「大蒙眷爱的但以理啊，要明白我与你所说的话，只管站起来，因为我现在奉差遣来到你这里。」他对我说这话，我便战战兢兢地立起来。","notes":[]},{"n":12,"t":"他就说：「但以理啊，不要惧怕！因为从你第一日专心求明白将来的事，又在你神面前刻苦己心，你的言语已蒙应允；我是因你的言语而来。","notes":[]},{"n":13,"t":"但波斯国的魔君拦阻我二十一日。忽然有大君中的一位米迦勒来帮助我，我就停留在波斯诸王那里。","notes":["就是天使长；二十一节同"]},{"n":14,"t":"现在我来，要使你明白本国之民日后必遭遇的事，因为这异象关乎后来许多的日子。」","notes":[]},{"n":15,"t":"他向我这样说，我就脸面朝地，哑口无声。","notes":[]},{"n":16,"t":"不料，有一位像人的，摸我的嘴唇，我便开口向那站在我面前的说：「我主啊，因见这异象，我大大愁苦，毫无气力。","notes":[]},{"n":17,"t":"我主的仆人怎能与我主说话呢？我一见异象就浑身无力，毫无气息。」","notes":[]},{"n":18,"t":"有一位形状像人的又摸我，使我有力量。","notes":[]},{"n":19,"t":"他说：「大蒙眷爱的人哪，不要惧怕，愿你平安！你总要坚强。」他一向我说话，我便觉得有力量，说：「我主请说，因你使我有力量。」","notes":[]},{"n":20,"t":"他就说：「你知道我为何来见你吗？现在我要回去与波斯的魔君争战，我去后，希腊的魔君必来。","notes":["原文是雅完"]},{"n":21,"t":"但我要将那录在真确书上的事告诉你。除了你们的大君米迦勒之外，没有帮助我抵挡这两魔君的。」","notes":[]}]},"11":{"heading":"南方王和北方王","verses":[{"n":1,"t":"又说：「当米底亚王大流士元年，我曾起来扶助米迦勒，使他坚强。」","notes":[]},{"n":2,"t":"现在我将真事指示你：「波斯还有三王兴起，第四王必富足远胜诸王。他因富足成为强盛，就必激动大众攻击希腊国。","notes":[]},{"n":3,"t":"必有一个勇敢的王兴起，执掌大权，随意而行。","notes":[]},{"n":4,"t":"他兴起的时候，他的国必破裂，向天的四方分开，却不归他的后裔，治国的权势也都不及他；因为他的国必被拔出，归与他后裔之外的人。","notes":["方：原文是风"]},{"n":5,"t":"「南方的王必强盛，他将帅中必有一个比他更强盛，执掌权柄，他的权柄甚大。","notes":[]},{"n":6,"t":"过些年后，他们必互相连合，南方王的女儿必就了北方王来立约；但这女子帮助之力存立不住，王和他所倚靠之力也不能存立。这女子和引导她来的，并生她的，以及当时扶助她的，都必交与死地。","notes":[]},{"n":7,"t":"但这女子的本家必另生一子继续王位，他必率领军队进入北方王的保障，攻击他们，而且得胜；","notes":["原文是根","子：原文是枝"]},{"n":8,"t":"并将他们的神像和铸成的偶像，与金银的宝器掠到埃及去。数年之内，他不去攻击北方的王。","notes":[]},{"n":9,"t":"北方的王必入南方王的国，却要仍回本地。","notes":["原文是他"]},{"n":10,"t":"「北方王的二子必动干戈，招聚许多军兵。这军兵前去，如洪水泛滥，又必再去争战，直到南方王的保障。","notes":["原文是他"]},{"n":11,"t":"南方王必发烈怒，出来与北方王争战，摆列大军；北方王的军兵必交付他手。","notes":[]},{"n":12,"t":"他的众军高傲，他的心也必自高；他虽使数万人仆倒，却不得常胜。","notes":[]},{"n":13,"t":"「北方王必回来摆列大军，比先前的更多。满了所定的年数，他必率领大军，带极多的军装来。","notes":[]},{"n":14,"t":"那时，必有许多人起来攻击南方王，并且你本国的强暴人必兴起，要应验那异象，他们却要败亡。","notes":[]},{"n":15,"t":"北方王必来筑垒攻取坚固城；南方的军兵必站立不住，就是选择的精兵也无力站住。","notes":["原文是民"]},{"n":16,"t":"来攻击他的，必任意而行，无人在北方王面前站立得住。他必站在那荣美之地，用手施行毁灭。","notes":["原文是他"]},{"n":17,"t":"「他必定意用全国之力而来，立公正的约，照约而行，将自己的女儿给南方王为妻，想要败坏他，这计却不得成就，与自己毫无益处。","notes":["或译：埃及"]},{"n":18,"t":"其后他必转回夺取了许多海岛。但有一大帅，除掉他令人受的羞辱，并且使这羞辱归他本身。","notes":[]},{"n":19,"t":"他就必转向本地的保障，却要绊跌仆倒，归于无有。","notes":[]},{"n":20,"t":"「那时，必有一人兴起接续他为王，使横征暴敛的人通行国中的荣美地。这王不多日就必灭亡，却不因忿怒，也不因争战。」","notes":[]},{"n":21,"t":"「必有一个卑鄙的人兴起接续为王，人未曾将国的尊荣给他，他却趁人坦然无备的时候，用谄媚的话得国。","notes":[],"heads":["北方的恶王"]},{"n":22,"t":"必有无数的军兵势如洪水，在他面前冲没败坏；同盟的君也必如此。","notes":[]},{"n":23,"t":"与那君结盟之后，他必行诡诈，因为他必上来以微小的军成为强盛。","notes":["原文是民"]},{"n":24,"t":"趁人坦然无备的时候，他必来到国中极肥美之地，行他列祖和他列祖之祖所未曾行的，将掳物、掠物，和财宝散给众人，又要设计攻打保障，然而这都是暂时的。","notes":[]},{"n":25,"t":"「他必奋勇向前，率领大军攻击南方王；南方王也必以极大极强的军兵与他争战，却站立不住，因为有人设计谋害南方王。","notes":[]},{"n":26,"t":"吃王膳的，必败坏他；他的军队必被冲没，而且被杀的甚多。","notes":[]},{"n":27,"t":"至于这二王，他们心怀恶计，同席说谎，计谋却不成就；因为到了定期，事就了结。","notes":[]},{"n":28,"t":"北方王必带许多财宝回往本国，他的心反对圣约，任意而行，回到本地。","notes":["原文是他"]},{"n":29,"t":"「到了定期，他必返回，来到南方。后一次却不如前一次，","notes":[]},{"n":30,"t":"因为基提战船必来攻击他，他就丧胆而回，又要恼恨圣约，任意而行；他必回来联络背弃圣约的人。","notes":[]},{"n":31,"t":"他必兴兵，这兵必亵渎圣地，就是保障，除掉常献的燔祭，设立那行毁坏可憎的。","notes":[]},{"n":32,"t":"作恶违背圣约的人，他必用巧言勾引；惟独认识神的子民必刚强行事。","notes":[]},{"n":33,"t":"民间的智慧人必训诲多人；然而他们多日必倒在刀下，或被火烧，或被掳掠抢夺。","notes":[]},{"n":34,"t":"他们仆倒的时候，稍得扶助，却有许多人用谄媚的话亲近他们。","notes":[]},{"n":35,"t":"智慧人中有些仆倒的，为要熬炼其余的人，使他们清净洁白，直到末了；因为到了定期，事就了结。","notes":[]},{"n":36,"t":"「王必任意而行，自高自大，超过所有的神，又用奇异的话攻击万神之神。他必行事亨通，直到主的忿怒完毕，因为所定的事必然成就。","notes":[]},{"n":37,"t":"他必不顾他列祖的神，也不顾妇女所羡慕的神，无论何神他都不顾；因为他必自大，高过一切。","notes":[]},{"n":38,"t":"他倒要敬拜保障的神，用金、银、宝石和可爱之物敬奉他列祖所不认识的神。","notes":[]},{"n":39,"t":"他必靠外邦神的帮助，攻破最坚固的保障。凡承认他的，他必将荣耀加给他们，使他们管辖许多人，又为贿赂分地与他们。","notes":[]},{"n":40,"t":"「到末了，南方王要与他交战。北方王必用战车、马兵，和许多战船，势如暴风来攻击他，也必进入列国，如洪水泛滥。","notes":[]},{"n":41,"t":"又必进入那荣美之地，有许多国就被倾覆，但以东人、摩押人，和一大半亚扪人必脱离他的手。","notes":[]},{"n":42,"t":"他必伸手攻击列国；埃及地也不得脱离。","notes":[]},{"n":43,"t":"他必把持埃及的金银财宝和各样的宝物。利比亚人和古实人都必跟从他。","notes":[]},{"n":44,"t":"但从东方和北方必有消息扰乱他，他就大发烈怒出去，要将多人杀灭净尽。","notes":[]},{"n":45,"t":"他必在海和荣美的圣山中间设立他如宫殿的帐幕；然而到了他的结局，必无人能帮助他。」","notes":[]}]},"12":{"heading":"末日","verses":[{"n":1,"t":"「那时，保佑你本国之民的天使长米迦勒必站起来，并且有大艰难，从有国以来直到此时，没有这样的。你本国的民中，凡名录在册上的，必得拯救。","notes":["原文是大君"]},{"n":2,"t":"睡在尘埃中的，必有多人复醒。其中有得永生的，有受羞辱永远被憎恶的。","notes":[]},{"n":3,"t":"智慧人必发光如同天上的光；那使多人归义的，必发光如星，直到永永远远。","notes":[]},{"n":4,"t":"但以理啊，你要隐藏这话，封闭这书，直到末时。必有多人来往奔跑，知识就必增长。」","notes":["或译：切心研究"]},{"n":5,"t":"我—但以理观看，见另有两个人站立：一个在河这边，一个在河那边。","notes":[]},{"n":6,"t":"有一个问那站在河水以上、穿细麻衣的说：「这奇异的事到几时才应验呢？」","notes":[]},{"n":7,"t":"我听见那站在河水以上、穿细麻衣的，向天举起左右手，指着活到永远的主起誓说：「要到一载、二载、半载，打破圣民权力的时候，这一切事就都应验了。」","notes":[]},{"n":8,"t":"我听见这话，却不明白，就说：「我主啊，这些事的结局是怎样呢？」","notes":[]},{"n":9,"t":"他说：「但以理啊，你只管去；因为这话已经隐藏封闭，直到末时。","notes":[]},{"n":10,"t":"必有许多人使自己清净洁白，且被熬炼；但恶人仍必行恶，一切恶人都不明白，惟独智慧人能明白。","notes":[]},{"n":11,"t":"从除掉常献的燔祭，并设立那行毁坏可憎之物的时候，必有一千二百九十日。","notes":[]},{"n":12,"t":"等到一千三百三十五日的，那人便为有福。","notes":[]},{"n":13,"t":"「你且去等候结局，因为你必安歇。到了末期，你必起来，享受你的福分。」","notes":[]}]}},"HOS":{"1":{"heading":"何西阿的妻子和儿女","verses":[{"n":1,"t":"当乌西雅、约坦、亚哈斯、希西家作犹大王，约阿施的儿子耶罗波安作以色列王的时候，耶和华的话临到备利的儿子何西阿。","notes":[]},{"n":2,"t":"耶和华初次与何西阿说话，对他说：「你去娶淫妇为妻，也收那从淫乱所生的儿女；因为这地大行淫乱，离弃耶和华。」","notes":[]},{"n":3,"t":"于是，何西阿去娶了滴拉音的女儿歌篾。这妇人怀孕，给他生了一个儿子。","notes":[]},{"n":4,"t":"耶和华对何西阿说：「给他起名叫耶斯列；因为再过片时，我必讨耶户家在耶斯列杀人流血的罪，也必使以色列家的国灭绝。","notes":[]},{"n":5,"t":"到那日，我必在耶斯列平原折断以色列的弓。」","notes":[]},{"n":6,"t":"歌篾又怀孕生了一个女儿，耶和华对何西阿说：「给她起名叫罗·路哈玛；因为我必不再怜悯以色列家，决不赦免他们。","notes":["就是不蒙怜悯的意思"]},{"n":7,"t":"我却要怜悯犹大家，使他们靠耶和华—他们的神得救，不使他们靠弓、刀、争战、马匹，与马兵得救。」","notes":[]},{"n":8,"t":"歌篾给罗·路哈玛断奶以后，又怀孕生了一个儿子。","notes":[]},{"n":9,"t":"耶和华说：「给他起名叫罗·阿米；因为你们不作我的子民，我也不作你们的神。」","notes":["就是非我民的意思"]},{"n":10,"t":"然而，以色列的人数必如海沙，不可量，不可数。从前在什么地方对他们说「你们不是我的子民」，将来在那里必对他们说「你们是永生神的儿子」。","notes":[],"heads":["以色列将要复兴"]},{"n":11,"t":"犹大人和以色列人必一同聚集，为自己立一个首领，从这地上去，因为耶斯列的日子必为大日。","notes":["或译：从被掳之地上来"]}]},"2":{"heading":"不贞的歌篾—不忠的以色列","verses":[{"n":1,"t":"你们要称你们的弟兄为阿米，称你们的姊妹为路哈玛。","notes":["就是我民的意思","就是蒙怜悯的意思"]},{"n":2,"t":"你们要与你们的母亲大大争辩；因为她不是我的妻子，我也不是她的丈夫。叫她除掉脸上的淫像和胸间的淫态，","notes":[]},{"n":3,"t":"免得我剥她的衣服，使她赤体，与才生的时候一样，使她如旷野，如干旱之地，因渴而死。","notes":[]},{"n":4,"t":"我必不怜悯她的儿女，因为他们是从淫乱而生的。","notes":[]},{"n":5,"t":"他们的母亲行了淫乱，怀他们的母做了可羞耻的事，因为她说：我要随从所爱的；我的饼、水、羊毛、麻、油、酒都是他们给的。","notes":[]},{"n":6,"t":"因此，我必用荆棘堵塞她的道，筑墙挡住她，使她找不着路。","notes":[]},{"n":7,"t":"她必追随所爱的，却追不上；她必寻找他们，却寻不见，便说：我要归回前夫，因我那时的光景比如今还好。","notes":[]},{"n":8,"t":"她不知道是我给她五谷、新酒，和油，又加增她的金银；她却以此供奉巴力。","notes":["或译：制造"]},{"n":9,"t":"因此到了收割的日子，出酒的时候，我必将我的五谷、新酒收回，也必将她应当遮体的羊毛和麻夺回来。","notes":[]},{"n":10,"t":"如今我必在她所爱的眼前显露她的丑态；必无人能救她脱离我的手。","notes":[]},{"n":11,"t":"我也必使她的宴乐、节期、月朔、安息日，并她的一切大会都止息了。","notes":[]},{"n":12,"t":"我也必毁坏她的葡萄树和无花果树，就是她说「这是我所爱的给我为赏赐」的。我必使这些树变为荒林，为田野的走兽所吃。","notes":[]},{"n":13,"t":"我必追讨她素日给诸巴力烧香的罪；那时她佩带耳环和别样妆饰，随从她所爱的，却忘记我。这是耶和华说的。","notes":[]},{"n":14,"t":"后来我必劝导她，领她到旷野，对她说安慰的话。","notes":[],"heads":["神对他子民的爱"]},{"n":15,"t":"她从那里出来，我必赐她葡萄园，又赐她亚割谷作为指望的门。她必在那里应声，与幼年的日子一样，与从埃及地上来的时候相同。","notes":["或译：歌唱"]},{"n":16,"t":"耶和华说：「那日你必称呼我伊施，不再称呼我巴力；","notes":["就是我夫的意思","就是我主的意思"]},{"n":17,"t":"因为我必从我民的口中除掉诸巴力的名号，这名号不再提起。","notes":[]},{"n":18,"t":"当那日，我必为我的民，与田野的走兽和空中的飞鸟，并地上的昆虫立约；又必在国中折断弓刀，止息争战，使他们安然躺卧。","notes":[]},{"n":19,"t":"我必聘你永远归我为妻，以仁义、公平、慈爱、怜悯聘你归我；","notes":[]},{"n":20,"t":"也以诚实聘你归我，你就必认识我—耶和华。","notes":[]},{"n":21,"t":"耶和华说：那日我必应允，我必应允天，天必应允地；","notes":[]},{"n":22,"t":"地必应允五谷、新酒，和油，这些必应允耶斯列民。","notes":["耶斯列就是神栽种的意思"]},{"n":23,"t":"我必将她种在这地。素不蒙怜悯的，我必怜悯；本非我民的，我必对他说：你是我的民；他必说：你是我的神。」","notes":[]}]},"3":{"heading":"何西阿和那不贞的妇人","verses":[{"n":1,"t":"耶和华对我说：「你再去爱一个淫妇，就是她情人所爱的；好像以色列人，虽然偏向别神，喜爱葡萄饼，耶和华还是爱他们。」","notes":[]},{"n":2,"t":"我便用银子十五舍客勒，大麦一贺梅珥半，买她归我。","notes":[]},{"n":3,"t":"我对她说：「你当多日为我独居，不可行淫，不可归别人为妻，我向你也必这样。」","notes":[]},{"n":4,"t":"以色列人也必多日独居，无君王，无首领，无祭祀，无柱像，无以弗得，无家中的神像。","notes":[]},{"n":5,"t":"后来以色列人必归回，寻求他们的神—耶和华和他们的王大卫。在末后的日子，必以敬畏的心归向耶和华，领受他的恩惠。","notes":["或译：回心转意"]}]},"4":{"heading":"耶和华谴责以色列","verses":[{"n":1,"t":"以色列人哪，你们当听耶和华的话。耶和华与这地的居民争辩，因这地上无诚实，无良善，无人认识神。","notes":[]},{"n":2,"t":"但起假誓，不践前言，杀害，偷盗，奸淫，行强暴，杀人流血，接连不断。","notes":[]},{"n":3,"t":"因此，这地悲哀，其上的民、田野的兽、空中的鸟必都衰微，海中的鱼也必消灭。","notes":[]},{"n":4,"t":"然而，人都不必争辩，也不必指责，因为这民与抗拒祭司的人一样。","notes":[],"heads":["谴责祭司"]},{"n":5,"t":"你这祭司必日间跌倒；先知也必夜间与你一同跌倒；我必灭绝你的母亲。","notes":[]},{"n":6,"t":"我的民因无知识而灭亡。你弃掉知识，我也必弃掉你，使你不再给我作祭司。你既忘了你神的律法，我也必忘记你的儿女。","notes":[]},{"n":7,"t":"祭司越发增多，就越发得罪我；我必使他们的荣耀变为羞辱。","notes":[]},{"n":8,"t":"他们吃我民的赎罪祭，满心愿意我民犯罪。","notes":[]},{"n":9,"t":"将来民如何，祭司也必如何；我必因他们所行的惩罚他们，照他们所做的报应他们。","notes":[]},{"n":10,"t":"他们吃，却不得饱；行淫，而不得立后；因为他们离弃耶和华，不遵他的命。","notes":[]},{"n":11,"t":"奸淫和酒，并新酒，夺去人的心。","notes":[],"heads":["谴责拜偶像的罪"]},{"n":12,"t":"我的民求问木偶，以为木杖能指示他们；因为他们的淫心使他们失迷，他们就行淫离弃神，不守约束，","notes":[]},{"n":13,"t":"在各山顶，各高冈的橡树、杨树、栗树之下，献祭烧香，因为树影美好。所以，你们的女儿淫乱，你们的新妇行淫。","notes":["或译：儿妇；下同"]},{"n":14,"t":"你们的女儿淫乱，你们的新妇行淫，我却不惩罚她们；因为你们自己离群与娼妓同居，与妓女一同献祭。这无知的民必致倾倒。","notes":[]},{"n":15,"t":"以色列啊，你虽然行淫，犹大却不可犯罪。不要往吉甲去，不要上到伯·亚文，也不要指着永生的耶和华起誓。","notes":[]},{"n":16,"t":"以色列倔强，犹如倔强的母牛；现在耶和华要放他们，如同放羊羔在宽阔之地。","notes":[]},{"n":17,"t":"以法莲亲近偶像，任凭他吧！","notes":[]},{"n":18,"t":"他们所喝的已经发酸，他们时常行淫，他们的官长最爱羞耻的事。","notes":[]},{"n":19,"t":"风把他们裹在翅膀里；他们因所献的祭必致蒙羞。","notes":[]}]},"5":{"heading":"何西阿警告拜偶像的人","verses":[{"n":1,"t":"众祭司啊，要听我的话！以色列家啊，要留心听！王家啊，要侧耳而听！审判要临到你们，因你们在米斯巴如网罗，在他泊山如铺张的网。","notes":[]},{"n":2,"t":"这些悖逆的人肆行杀戮，罪孽极深；我却斥责他们众人。","notes":[]},{"n":3,"t":"以法莲为我所知；以色列不能向我隐藏。以法莲哪，现在你行淫了，以色列被玷污了。","notes":[]},{"n":4,"t":"他们所行的使他们不能归向神；因有淫心在他们里面，他们也不认识耶和华。","notes":[]},{"n":5,"t":"以色列的骄傲当面见证自己。故此，以色列和以法莲必因自己的罪孽跌倒；犹大也必与他们一同跌倒。","notes":[]},{"n":6,"t":"他们必牵着牛羊去寻求耶和华，却寻不见；他已经转去离开他们。","notes":[]},{"n":7,"t":"他们向耶和华行事诡诈，生了私子。到了月朔，他们与他们的地业必被吞灭。","notes":[]},{"n":8,"t":"你们当在基比亚吹角，在拉玛吹号，在伯·亚文吹出大声，说：便雅悯哪，有仇敌在你后头！","notes":[],"heads":["犹大和以色列的战争"]},{"n":9,"t":"在责罚的日子，以法莲必变为荒场；我在以色列支派中，指示将来必成的事。","notes":[]},{"n":10,"t":"犹大的首领如同挪移地界的人，我必将忿怒倒在他们身上，如水一般。","notes":[]},{"n":11,"t":"以法莲因乐从人的命令，就受欺压，被审判压碎。","notes":[]},{"n":12,"t":"我使以法莲如虫蛀之物，使犹大家如朽烂之木。","notes":[]},{"n":13,"t":"以法莲见自己有病，犹大见自己有伤，他们就打发人往亚述去见耶雷布王，他却不能医治你们，不能治好你们的伤。","notes":[]},{"n":14,"t":"我必向以法莲如狮子，向犹大家如少壮狮子。我必撕裂而去，我要夺去，无人搭救。","notes":[]},{"n":15,"t":"我要回到原处，等他们自觉有罪，寻求我面；他们在急难的时候必切切寻求我。","notes":["或译：承认己罪"]}]},"6":{"heading":"以色列无悔改诚意","verses":[{"n":1,"t":"来吧，我们归向耶和华！他撕裂我们，也必医治；他打伤我们，也必缠裹。","notes":[]},{"n":2,"t":"过两天他必使我们苏醒，第三天他必使我们兴起，我们就在他面前得以存活。","notes":[]},{"n":3,"t":"我们务要认识耶和华，竭力追求认识他。他出现确如晨光；他必临到我们像甘雨，像滋润田地的春雨。","notes":[]},{"n":4,"t":"主说：以法莲哪，我可向你怎样行呢？犹大啊，我可向你怎样做呢？因为你们的良善如同早晨的云雾，又如速散的甘露。","notes":[]},{"n":5,"t":"因此，我借先知砍伐他们，以我口中的话杀戮他们；我施行的审判如光发出。","notes":[]},{"n":6,"t":"我喜爱良善，不喜爱祭祀；喜爱认识神，胜于燔祭。","notes":["或译：怜恤"]},{"n":7,"t":"他们却如亚当背约，在境内向我行事诡诈。","notes":[]},{"n":8,"t":"基列是作孽之人的城，被血沾染。","notes":[]},{"n":9,"t":"强盗成群，怎样埋伏杀人，祭司结党，也照样在示剑的路上杀戮，行了邪恶。","notes":[]},{"n":10,"t":"在以色列家，我见了可憎的事；在以法莲那里有淫行，以色列被玷污。","notes":[]},{"n":11,"t":"犹大啊，我使被掳之民归回的时候，必有为你所命定的收场。","notes":[]}]},"7":{"heading":"宫廷内乱","verses":[{"n":1,"t":"我想医治以色列的时候，以法莲的罪孽和撒马利亚的罪恶就显露出来。他们行事虚谎，内有贼人入室偷窃，外有强盗成群骚扰。","notes":[]},{"n":2,"t":"他们心里并不思想我记念他们的一切恶；他们所行的现在缠绕他们，都在我面前。","notes":[]},{"n":3,"t":"他们行恶使君王欢喜，说谎使首领喜乐。","notes":[]},{"n":4,"t":"他们都是行淫的，像火炉被烤饼的烧热，从抟面到发面的时候，暂不使火着旺。","notes":[]},{"n":5,"t":"在我们王宴乐的日子，首领因酒的烈性成病；王与亵慢人拉手。","notes":[]},{"n":6,"t":"首领埋伏的时候，心中热如火炉，就如烤饼的整夜睡卧，到了早晨火气炎炎。","notes":[]},{"n":7,"t":"众民也热如火炉，烧灭他们的官长。他们的君王都仆倒而死；他们中间无一人求告我。","notes":[]},{"n":8,"t":"以法莲与列邦人搀杂；以法莲是没有翻过的饼。","notes":[],"heads":["以色列和列邦"]},{"n":9,"t":"外邦人吞吃他劳力得来的，他却不知道；头发斑白，他也不觉得。","notes":[]},{"n":10,"t":"以色列的骄傲当面见证自己，虽遭遇这一切，他们仍不归向耶和华—他们的神，也不寻求他。","notes":[]},{"n":11,"t":"以法莲好像鸽子愚蠢无知；他们求告埃及，投奔亚述。","notes":[]},{"n":12,"t":"他们去的时候，我必将我的网撒在他们身上；我要打下他们，如同空中的鸟。我必按他们会众所听见的惩罚他们。","notes":[]},{"n":13,"t":"他们因离弃我，必定有祸；因违背我，必被毁灭。我虽要救赎他们，他们却向我说谎。","notes":[]},{"n":14,"t":"他们并不诚心哀求我，乃在床上呼号；他们为求五谷新酒聚集，仍然悖逆我。","notes":[]},{"n":15,"t":"我虽教导他们，坚固他们的膀臂，他们竟图谋抗拒我。","notes":[]},{"n":16,"t":"他们归向，却不归向至上者；他们如同翻背的弓。他们的首领必因舌头的狂傲倒在刀下；这在埃及地必作人的讥笑。","notes":[]}]},"8":{"heading":"以色列人因拜偶像被定罪","verses":[{"n":1,"t":"你用口吹角吧！敌人如鹰来攻打耶和华的家；因为这民违背我的约，干犯我的律法。","notes":[]},{"n":2,"t":"他们必呼叫我说：我的神啊，我们以色列认识你了。","notes":[]},{"n":3,"t":"以色列丢弃良善；仇敌必追逼他。","notes":["或译：福分"]},{"n":4,"t":"他们立君王，却不由我；他们立首领，我却不认。他们用金银为自己制造偶像，以致被剪除。","notes":[]},{"n":5,"t":"撒马利亚啊，耶和华已经丢弃你的牛犊；我的怒气向拜牛犊的人发作。他们到几时方能无罪呢？","notes":[]},{"n":6,"t":"这牛犊出于以色列，是匠人所造的，并不是神。撒马利亚的牛犊必被打碎。","notes":[]},{"n":7,"t":"他们所种的是风，所收的是暴风；所种的不成禾稼，就是发苗也不结实；即便结实，外邦人必吞吃。","notes":[]},{"n":8,"t":"以色列被吞吃；现今在列国中，好像人不喜悦的器皿。","notes":[]},{"n":9,"t":"他们投奔亚述，如同独行的野驴；以法莲贿买朋党。","notes":[]},{"n":10,"t":"他们虽在列邦中贿买人，现在我却要聚集惩罚他们；他们因君王和首领所加的重担日渐衰微。","notes":[]},{"n":11,"t":"以法莲增添祭坛取罪；因此，祭坛使他犯罪。","notes":[]},{"n":12,"t":"我为他写了律法万条，他却以为与他毫无关涉。","notes":[]},{"n":13,"t":"至于献给我的祭物，他们自食其肉，耶和华却不悦纳他们。现在必记念他们的罪孽，追讨他们的罪恶；他们必归回埃及。","notes":[]},{"n":14,"t":"以色列忘记造他的主，建造宫殿；犹大多造坚固城，我却要降火焚烧他的城邑，烧灭其中的宫殿。","notes":[]}]},"9":{"heading":"何西阿宣布以色列受惩罚","verses":[{"n":1,"t":"以色列啊，不要像外邦人欢喜快乐；因为你行邪淫离弃你的神，在各谷场上如妓女喜爱赏赐。","notes":[]},{"n":2,"t":"谷场和酒榨都不够以色列人使用；新酒也必缺乏。","notes":[]},{"n":3,"t":"他们必不得住耶和华的地；以法莲却要归回埃及，必在亚述吃不洁净的食物。","notes":[]},{"n":4,"t":"他们必不得向耶和华奠酒，即便奠酒也不蒙悦纳。他们的祭物必如居丧者的食物，凡吃的必被玷污；因他们的食物只为自己的口腹，必不奉入耶和华的殿。","notes":[]},{"n":5,"t":"在大会的日子，到耶和华的节期，你们怎样行呢？","notes":[]},{"n":6,"t":"看哪，他们逃避灾难；埃及人必收殓他们的尸首，摩弗人必葬埋他们的骸骨。他们用银子做的美物上必长蒺藜；他们的帐棚中必生荆棘。","notes":[]},{"n":7,"t":"以色列人必知道降罚的日子临近，报应的时候来到。民说：作先知的是愚昧；受灵感的是狂妄，皆因他们多多作孽，大怀怨恨。","notes":[]},{"n":8,"t":"以法莲曾作我神守望的；至于先知，在他一切的道上作为捕鸟人的网罗，在他神的家中怀怨恨。","notes":[]},{"n":9,"t":"以法莲深深地败坏，如在基比亚的日子一样。耶和华必记念他们的罪孽，追讨他们的罪恶。","notes":[]},{"n":10,"t":"主说：我遇见以色列如葡萄在旷野；我看见你们的列祖如无花果树上春季初熟的果子。他们却来到巴力·毗珥专拜那可羞耻的，就成为可憎恶的，与他们所爱的一样。","notes":[],"heads":["以色列的罪及其后果"]},{"n":11,"t":"至于以法莲人，他们的荣耀必如鸟飞去，必不生产，不怀胎，不成孕。","notes":[]},{"n":12,"t":"纵然养大儿女，我却必使他们丧子，甚至不留一个。我离弃他们，他们就有祸了。","notes":[]},{"n":13,"t":"我看以法莲如泰尔栽于美地。以法莲却要将自己的儿女带出来，交与行杀戮的人。","notes":[]},{"n":14,"t":"耶和华啊，求你加给他们—加什么呢？要使他们胎坠乳干。","notes":[]},{"n":15,"t":"耶和华说：他们一切的恶事都在吉甲；我在那里憎恶他们。因他们所行的恶，我必从我地上赶出他们去，不再怜爱他们；他们的首领都是悖逆的。","notes":[],"heads":["耶和华审判以色列"]},{"n":16,"t":"以法莲受责罚，根本枯干，必不能结果，即或生产，我必杀他们所生的爱子。","notes":[]},{"n":17,"t":"我的神必弃绝他们，因为他们不听从他；他们也必飘流在列国中。","notes":[],"heads":["先知论以色列"]}]},"10":{"heading":"神审判以色列","verses":[{"n":1,"t":"以色列是茂盛的葡萄树，结果繁多。果子越多，就越增添祭坛；地土越肥美，就越造美丽的柱像。","notes":[]},{"n":2,"t":"他们心怀二意，现今要定为有罪。耶和华必拆毁他们的祭坛，毁坏他们的柱像。","notes":[]},{"n":3,"t":"他们必说：我们没有王，因为我们不敬畏耶和华。王能为我们做什么呢？","notes":[]},{"n":4,"t":"他们为立约说谎言，起假誓；因此，灾罚如苦菜滋生在田间的犁沟中。","notes":[]},{"n":5,"t":"撒马利亚的居民必因伯·亚文的牛犊惊恐；崇拜牛犊的民和喜爱牛犊的祭司都必因荣耀离开它，为它悲哀。","notes":[]},{"n":6,"t":"人必将牛犊带到亚述当作礼物，献给耶雷布王。以法莲必蒙羞；以色列必因自己的计谋惭愧。","notes":[]},{"n":7,"t":"至于撒马利亚，她的王必灭没，如水面的沫子一样。","notes":[]},{"n":8,"t":"伯·亚文的邱坛—就是以色列取罪的地方必被毁灭；荆棘和蒺藜必长在他们的祭坛上。他们必对大山说：遮盖我们！对小山说：倒在我们身上！","notes":[]},{"n":9,"t":"以色列啊，你从基比亚的日子以来时常犯罪。你们的先人曾站在那里，现今住基比亚的人以为攻击罪孽之辈的战事临不到自己。","notes":[]},{"n":10,"t":"我必随意惩罚他们。他们为两样的罪所缠；列邦的民必聚集攻击他们。","notes":[]},{"n":11,"t":"以法莲是驯良的母牛犊，喜爱踹谷，我却将轭加在它肥美的颈项上，我要使以法莲拉套。犹大必耕田；雅各必耙地。","notes":["或译：被骑"]},{"n":12,"t":"你们要为自己栽种公义，就能收割慈爱。现今正是寻求耶和华的时候；你们要开垦荒地，等他临到，使公义如雨降在你们身上。","notes":[]},{"n":13,"t":"你们耕种的是奸恶，收割的是罪孽，吃的是谎话的果子。因你倚靠自己的行为，仰赖勇士众多，","notes":[]},{"n":14,"t":"所以在这民中必有哄嚷之声，你一切的保障必被拆毁，就如沙勒幔在争战的日子拆毁伯·亚比勒，将其中的母子一同摔死。","notes":[]},{"n":15,"t":"因他们的大恶，伯特利必使你们遭遇如此。到了黎明，以色列的王必全然灭绝。","notes":[]}]},"11":{"heading":"怜爱叛民","verses":[{"n":1,"t":"以色列年幼的时候，我爱他，就从埃及召出我的儿子来。","notes":[]},{"n":2,"t":"先知越发招呼他们，他们越发走开，向诸巴力献祭，给雕刻的偶像烧香。","notes":[]},{"n":3,"t":"我原教导以法莲行走，用膀臂抱着他们，他们却不知道是我医治他们。","notes":[]},{"n":4,"t":"我用慈绳爱索牵引他们；我待他们如人放松牛的两腮夹板，把粮食放在他们面前。","notes":["慈：原文是人的"]},{"n":5,"t":"他们必不归回埃及地，亚述人却要作他们的王，因他们不肯归向我。","notes":[]},{"n":6,"t":"刀剑必临到他们的城邑，毁坏门闩，把人吞灭，都因他们随从自己的计谋。","notes":[]},{"n":7,"t":"我的民偏要背道离开我；众先知虽然招呼他们归向至上的主，却无人尊崇主。","notes":[]},{"n":8,"t":"以法莲哪，我怎能舍弃你？以色列啊，我怎能弃绝你？我怎能使你如押玛？怎能使你如洗扁？我回心转意，我的怜爱大大发动。","notes":[]},{"n":9,"t":"我必不发猛烈的怒气，也不再毁灭以法莲。因我是神，并非世人，是你们中间的圣者；我必不在怒中临到你们。","notes":[]},{"n":10,"t":"耶和华必如狮子吼叫，子民必跟随他。他一吼叫，他们就从西方急速而来。","notes":[]},{"n":11,"t":"他们必如雀鸟从埃及急速而来，又如鸽子从亚述地来到。我必使他们住自己的房屋。这是耶和华说的。","notes":[]},{"n":12,"t":"以法莲用谎话，以色列家用诡计围绕我；犹大却靠神掌权，向圣者有忠心。","notes":["或译：犹大向神，向诚实的圣者犹疑不定"],"heads":["以色列和犹大受谴责"]}]},"12":{"heading":"其他的判词","verses":[{"n":1,"t":"以法莲吃风，且追赶东风，时常增添虚谎和强暴，与亚述立约，把油送到埃及。","notes":[]},{"n":2,"t":"耶和华与犹大争辩，必照雅各所行的惩罚他，按他所做的报应他。","notes":[]},{"n":3,"t":"他在腹中抓住哥哥的脚跟，壮年的时候与神较力，","notes":[]},{"n":4,"t":"与天使较力，并且得胜，哭泣恳求，在伯特利遇见耶和华。耶和华—万军之神在那里晓谕我们以色列人；耶和华是他可记念的名。","notes":[],"end":5},{"n":6,"t":"所以你当归向你的神，谨守仁爱、公平，常常等候你的神。","notes":[]},{"n":7,"t":"以法莲是商人，手里有诡诈的天平，爱行欺骗。","notes":[]},{"n":8,"t":"以法莲说：我果然成了富足，得了财宝；我所劳碌得来的，人必不见有什么不义，可算为罪的。","notes":[]},{"n":9,"t":"自从你出埃及地以来，我就是耶和华—你的神；我必使你再住帐棚，如在大会的日子一样。","notes":[]},{"n":10,"t":"我已晓谕众先知，并且加增默示，借先知设立比喻。","notes":[]},{"n":11,"t":"基列人没有罪孽吗？他们全然是虚假的。人在吉甲献牛犊为祭，他们的祭坛好像田间犁沟中的乱堆。","notes":[]},{"n":12,"t":"从前雅各逃到亚兰地，以色列为得妻服事人，为得妻与人放羊。","notes":[]},{"n":13,"t":"耶和华借先知领以色列从埃及上来；以色列也借先知而得保存。","notes":[]},{"n":14,"t":"以法莲大大惹动主怒，所以他流血的罪必归在他身上。主必将那因以法莲所受的羞辱归还他。","notes":[]}]},"13":{"heading":"以色列最后的审判","verses":[{"n":1,"t":"从前以法莲说话，人都战兢，他在以色列中居处高位；但他在事奉巴力的事上犯罪就死了。","notes":[]},{"n":2,"t":"现今他们罪上加罪，用银子为自己铸造偶像，就是照自己的聪明制造，都是匠人的工作。有人论说，献祭的人可以向牛犊亲嘴。","notes":[]},{"n":3,"t":"因此，他们必如早晨的云雾，又如速散的甘露，像场上的糠秕被狂风吹去，又像烟气腾于窗外。","notes":[]},{"n":4,"t":"自从你出埃及地以来，我就是耶和华—你的神。在我以外，你不可认识别神；除我以外并没有救主。","notes":[]},{"n":5,"t":"我曾在旷野干旱之地认识你。","notes":[]},{"n":6,"t":"这些民照我所赐的食物得了饱足；既得饱足，心就高傲，忘记了我。","notes":[]},{"n":7,"t":"因此，我向他们如狮子，又如豹伏在道旁。","notes":[]},{"n":8,"t":"我遇见他们必像丢崽子的母熊，撕裂他们的胸膛。在那里，我必像母狮吞吃他们；野兽必撕裂他们。","notes":["或译：心膜"]},{"n":9,"t":"以色列啊，你与我反对，就是反对帮助你的，自取败坏。","notes":[]},{"n":10,"t":"你曾求我说：给我立王和首领。现在你的王在哪里呢？治理你的在哪里呢？让他在你所有的城中拯救你吧！","notes":[]},{"n":11,"t":"我在怒气中将王赐你，又在烈怒中将王废去。","notes":[]},{"n":12,"t":"以法莲的罪孽包裹；他的罪恶收藏。","notes":[]},{"n":13,"t":"产妇的疼痛必临到他身上；他是无智慧之子，到了产期不当迟延。","notes":[]},{"n":14,"t":"我必救赎他们脱离阴间，救赎他们脱离死亡。死亡啊，你的灾害在哪里呢？阴间哪，你的毁灭在哪里呢？在我眼前绝无后悔之事。","notes":[]},{"n":15,"t":"他在弟兄中虽然茂盛，必有东风刮来，就是耶和华的风从旷野上来。他的泉源必干；他的源头必竭；仇敌必掳掠他所积蓄的一切宝器。","notes":[]},{"n":16,"t":"撒马利亚必担当自己的罪，因为悖逆她的神。她必倒在刀下；婴孩必被摔死；孕妇必被剖开。","notes":[]}]},"14":{"heading":"何西阿劝告以色列人","verses":[{"n":1,"t":"以色列啊，你要归向耶和华—你的神；你是因自己的罪孽跌倒了。","notes":[]},{"n":2,"t":"当归向耶和华，用言语祷告他说：求你除净罪孽，悦纳善行；这样，我们就把嘴唇的祭代替牛犊献上。","notes":[]},{"n":3,"t":"我们不向亚述求救，不骑埃及的马，也不再对我们手所造的说：你是我们的神。因为孤儿在你—耶和华那里得蒙怜悯。","notes":[]},{"n":4,"t":"我必医治他们背道的病，甘心爱他们；因为我的怒气向他们转消。","notes":[],"heads":["耶和华应许以色列新生命"]},{"n":5,"t":"我必向以色列如甘露；他必如百合花开放，如黎巴嫩的树木扎根。","notes":[]},{"n":6,"t":"他的枝条必延长；他的荣华如橄榄树；他的香气如黎巴嫩的香柏树。","notes":[]},{"n":7,"t":"曾住在他荫下的必归回，发旺如五谷，开花如葡萄树。他的香气如黎巴嫩的酒。","notes":[]},{"n":8,"t":"以法莲必说：我与偶像还有什么关涉呢？我—耶和华回答他，也必顾念他。我如青翠的松树；你的果子从我而得。","notes":[]},{"n":9,"t":"谁是智慧人？可以明白这些事；谁是通达人？可以知道这一切。因为，耶和华的道是正直的；义人必在其中行走，罪人却在其上跌倒。","notes":[],"heads":["结束的话"]}]}},"JOL":{"1":{"heading":"百姓因收成受损坏而悲伤","verses":[{"n":1,"t":"耶和华的话临到毗土珥的儿子约珥。","notes":[]},{"n":2,"t":"老年人哪，当听我的话；国中的居民哪，都要侧耳而听。在你们的日子，或你们列祖的日子，曾有这样的事吗？","notes":[]},{"n":3,"t":"你们要将这事传与子，子传与孙，孙传与后代。","notes":[]},{"n":4,"t":"剪虫剩下的，蝗虫来吃；蝗虫剩下的，蝻子来吃；蝻子剩下的，蚂蚱来吃。","notes":[]},{"n":5,"t":"酒醉的人哪，要清醒哭泣；好酒的人哪，都要为甜酒哀号，因为从你们的口中断绝了。","notes":[]},{"n":6,"t":"有一队蝗虫又强盛又无数，侵犯我的地；它的牙齿如狮子的牙齿，大牙如母狮的大牙。","notes":["原文是民"]},{"n":7,"t":"它毁坏我的葡萄树，剥了我无花果树的皮，剥尽而丢弃，使枝条露白。","notes":[]},{"n":8,"t":"我的民哪，你当哀号，像处女腰束麻布，为幼年的丈夫哀号。","notes":[]},{"n":9,"t":"素祭和奠祭从耶和华的殿中断绝；事奉耶和华的祭司都悲哀。","notes":[]},{"n":10,"t":"田荒凉，地悲哀；因为五谷毁坏，新酒干竭，油也缺乏。","notes":[]},{"n":11,"t":"农夫啊，你们要惭愧；修理葡萄园的啊，你们要哀号；因为大麦小麦与田间的庄稼都灭绝了。","notes":[]},{"n":12,"t":"葡萄树枯干；无花果树衰残。石榴树、棕树、苹果树，连田野一切的树木也都枯干；众人的喜乐尽都消灭。","notes":[]},{"n":13,"t":"祭司啊，你们当腰束麻布痛哭；伺候祭坛的啊，你们要哀号；事奉我神的啊，你们要来披上麻布过夜，因为素祭和奠祭从你们神的殿中断绝了。","notes":[]},{"n":14,"t":"你们要分定禁食的日子，宣告严肃会，招聚长老和国中的一切居民到耶和华—你们神的殿，向耶和华哀求。","notes":[]},{"n":15,"t":"哀哉！耶和华的日子临近了。这日来到，好像毁灭从全能者来到。","notes":[]},{"n":16,"t":"粮食不是在我们眼前断绝了吗？欢喜快乐不是从我们神的殿中止息了吗？","notes":[]},{"n":17,"t":"谷种在土块下朽烂；仓也荒凉，廪也破坏；因为五谷枯干了。","notes":[]},{"n":18,"t":"牲畜哀鸣；牛群混乱，因为无草；羊群也受了困苦。","notes":[]},{"n":19,"t":"耶和华啊，我向你求告，因为火烧灭旷野的草场；火焰烧尽田野的树木。","notes":[]},{"n":20,"t":"田野的走兽向你发喘；因为溪水干涸，火也烧灭旷野的草场。","notes":[]}]},"2":{"heading":"以蝗虫为耶和华日子的警告","verses":[{"n":1,"t":"你们要在锡安吹角，在我圣山吹出大声。国中的居民都要发颤；因为耶和华的日子将到，已经临近。","notes":[]},{"n":2,"t":"那日是黑暗、幽冥、密云、乌黑的日子，好像晨光铺满山岭。有一队蝗虫又大又强；从来没有这样的，以后直到万代也必没有。","notes":["原文是民"]},{"n":3,"t":"它们前面如火烧灭，后面如火焰烧尽。未到以前，地如伊甸园；过去以后，成了荒凉的旷野；没有一样能躲避它们的。","notes":[]},{"n":4,"t":"它们的形状如马，奔跑如马兵。","notes":[]},{"n":5,"t":"在山顶蹦跳的响声如车辆的响声，又如火焰烧碎秸的响声，好像强盛的民摆阵预备打仗。","notes":[]},{"n":6,"t":"它们一来，众民伤恸，脸都变色。","notes":[]},{"n":7,"t":"它们如勇士奔跑，像战士爬城；各都步行，不乱队伍。","notes":[]},{"n":8,"t":"彼此并不拥挤，向前各行其路，直闯兵器，不偏左右。","notes":[]},{"n":9,"t":"它们蹦上城，蹿上墙，爬上房屋，进入窗户如同盗贼。","notes":[]},{"n":10,"t":"它们一来，地震天动，日月昏暗，星宿无光。","notes":[]},{"n":11,"t":"耶和华在他军旅前发声，他的队伍甚大；成就他命的是强盛者。因为耶和华的日子大而可畏，谁能当得起呢？","notes":[]},{"n":12,"t":"耶和华说：虽然如此，你们应当禁食、哭泣、悲哀，一心归向我。","notes":[],"heads":["呼吁百姓悔改"]},{"n":13,"t":"你们要撕裂心肠，不撕裂衣服。归向耶和华—你们的神；因为他有恩典，有怜悯，不轻易发怒，有丰盛的慈爱，并且后悔不降所说的灾。","notes":[]},{"n":14,"t":"或者他转意后悔，留下余福，就是留下献给耶和华—你们神的素祭和奠祭，也未可知。","notes":[]},{"n":15,"t":"你们要在锡安吹角，分定禁食的日子，宣告严肃会。","notes":[]},{"n":16,"t":"聚集众民，使会众自洁：招聚老者，聚集孩童和吃奶的；使新郎出离洞房，新妇出离内室。","notes":[]},{"n":17,"t":"事奉耶和华的祭司要在廊子和祭坛中间哭泣，说：耶和华啊，求你顾惜你的百姓，不要使你的产业受羞辱，列邦管辖他们。为何容列国的人说：「他们的神在哪里」呢？","notes":[]},{"n":18,"t":"耶和华就为自己的地发热心，怜恤他的百姓。","notes":[],"heads":["神再赐福泽"]},{"n":19,"t":"耶和华应允他的百姓说：我必赐给你们五谷、新酒，和油，使你们饱足；我也不再使你们受列国的羞辱；","notes":[]},{"n":20,"t":"却要使北方来的军队远离你们，将他们赶到干旱荒废之地：前队赶入东海，后队赶入西海；因为他们所行的大恶，臭气上升，腥味腾空。","notes":["原文是事"]},{"n":21,"t":"地土啊，不要惧怕；要欢喜快乐，因为耶和华行了大事。","notes":[]},{"n":22,"t":"田野的走兽啊，不要惧怕；因为，旷野的草发生，树木结果，无花果树、葡萄树也都效力。","notes":[]},{"n":23,"t":"锡安的民哪，你们要快乐，为耶和华—你们的神欢喜；因他赐给你们合宜的秋雨，为你们降下甘霖，就是秋雨、春雨，和先前一样。","notes":[]},{"n":24,"t":"禾场必满了麦子；酒榨与油榨必有新酒和油盈溢。","notes":[]},{"n":25,"t":"我打发到你们中间的大军队，就是蝗虫、蝻子、蚂蚱、剪虫，那些年所吃的，我要补还你们。","notes":[]},{"n":26,"t":"你们必多吃而得饱足，就赞美为你们行奇妙事之耶和华—你们神的名。我的百姓必永远不至羞愧。","notes":[]},{"n":27,"t":"你们必知道我是在以色列中间，又知道我是耶和华—你们的神；在我以外并无别神。我的百姓必永远不致羞愧。","notes":[]},{"n":28,"t":"以后，我要将我的灵浇灌凡有血气的。你们的儿女要说预言；你们的老年人要做异梦，少年人要见异象。","notes":[],"heads":["耶和华的日子"]},{"n":29,"t":"在那些日子，我要将我的灵浇灌我的仆人和使女。","notes":[]},{"n":30,"t":"「在天上地下，我要显出奇事，有血，有火，有烟柱。","notes":[]},{"n":31,"t":"日头要变为黑暗，月亮要变为血，这都在耶和华大而可畏的日子未到以前。","notes":[]},{"n":32,"t":"到那时候，凡求告耶和华名的就必得救；因为照耶和华所说的，在锡安山，耶路撒冷必有逃脱的人，在剩下的人中必有耶和华所召的。」","notes":[]}]},"3":{"heading":"神要审判万民","verses":[{"n":1,"t":"「到那日，我使犹大和耶路撒冷被掳之人归回的时候，","notes":[]},{"n":2,"t":"我要聚集万民，带他们下到约沙法谷，在那里施行审判；因为他们将我的百姓，就是我的产业以色列，分散在列国中，又分取我的地土，","notes":[]},{"n":3,"t":"且为我的百姓拈阄，将童子换妓女，卖童女买酒喝。","notes":[]},{"n":4,"t":"「泰尔、西顿，和非利士四境的人哪，你们与我何干？你们要报复我吗？若报复我，我必使报应速速归到你们的头上。","notes":[]},{"n":5,"t":"你们既然夺取我的金银，又将我可爱的宝物带入你们宫殿，","notes":["或译：庙中"]},{"n":6,"t":"并将犹大人和耶路撒冷人卖给希腊人，使他们远离自己的境界。","notes":["原文是雅完人"]},{"n":7,"t":"我必激动他们离开你们所卖到之地，又必使报应归到你们的头上。","notes":[]},{"n":8,"t":"我必将你们的儿女卖在犹大人的手中，他们必卖给远方示巴国的人。这是耶和华说的。」","notes":[]},{"n":9,"t":"当在万民中宣告说：要预备打仗；激动勇士，使一切战士上前来。","notes":[]},{"n":10,"t":"要将犁头打成刀剑，将镰刀打成戈矛；软弱的要说：我有勇力。","notes":[]},{"n":11,"t":"四围的列国啊，你们要速速地来，一同聚集。耶和华啊，求你使你的大能者降临。","notes":[]},{"n":12,"t":"万民都当兴起，上到约沙法谷；因为我必坐在那里，审判四围的列国。","notes":[]},{"n":13,"t":"开镰吧！因为庄稼熟了；践踏吧！因为酒榨满了。酒池盈溢；他们的罪恶甚大。","notes":[]},{"n":14,"t":"许多许多的人在断定谷，因为耶和华的日子临近断定谷。","notes":[]},{"n":15,"t":"日月昏暗，星宿无光。","notes":[]},{"n":16,"t":"耶和华必从锡安吼叫，从耶路撒冷发声，天地就震动。耶和华却要作他百姓的避难所，作以色列人的保障。","notes":[],"heads":["神将赐福给他的子民"]},{"n":17,"t":"你们就知道我是耶和华—你们的神，且又住在锡安—我的圣山。那时，耶路撒冷必成为圣；外邦人不再从其中经过。","notes":[]},{"n":18,"t":"到那日，大山要滴甜酒；小山要流奶子；犹大溪河都有水流。必有泉源从耶和华的殿中流出来，滋润什亭谷。","notes":[]},{"n":19,"t":"埃及必然荒凉，以东变为凄凉的旷野，都因向犹大人所行的强暴，又因在本地流无辜人的血。","notes":[]},{"n":20,"t":"但犹大必存到永远；耶路撒冷必存到万代。","notes":[]},{"n":21,"t":"我未曾报复流血的罪，现在我要报复，因为耶和华住在锡安。","notes":["或译：洗除；下同"]}]}},"AMO":{"1":{"heading":"神审判以色列的邻国","verses":[{"n":1,"t":"当犹大王乌西雅，以色列王约阿施的儿子耶罗波安在位的时候，大地震前二年，提哥亚牧人中的阿摩司得默示论以色列。","notes":[]},{"n":2,"t":"他说：耶和华必从锡安吼叫，从耶路撒冷发声；牧人的草场要悲哀；迦密的山顶要枯干。","notes":[]},{"n":3,"t":"耶和华如此说：大马士革三番四次地犯罪，我必不免去她的刑罚；因为她以打粮食的铁器打过基列。","notes":[]},{"n":4,"t":"我却要降火在哈薛的家中，烧灭便·哈达的宫殿。","notes":[]},{"n":5,"t":"我必折断大马士革的门闩，剪除亚文平原的居民和伯·伊甸掌权的。亚兰人必被掳到吉珥。这是耶和华说的。","notes":[]},{"n":6,"t":"耶和华如此说：迦萨三番四次地犯罪，我必不免去她的刑罚；因为她掳掠众民交给以东。","notes":[]},{"n":7,"t":"我却要降火在迦萨的城内，烧灭其中的宫殿。","notes":[]},{"n":8,"t":"我必剪除亚实突的居民和亚实基伦掌权的，也必反手攻击以革伦。非利士人所余剩的必都灭亡。这是主耶和华说的。","notes":[]},{"n":9,"t":"耶和华如此说：泰尔三番四次地犯罪，我必不免去她的刑罚；因为她将众民交给以东，并不记念弟兄的盟约。","notes":[]},{"n":10,"t":"我却要降火在泰尔的城内，烧灭其中的宫殿。","notes":[]},{"n":11,"t":"耶和华如此说：以东三番四次地犯罪，我必不免去她的刑罚；因为她拿刀追赶兄弟，毫无怜悯，发怒撕裂，永怀忿怒。","notes":[]},{"n":12,"t":"我却要降火在提幔，烧灭波斯拉的宫殿。","notes":[]},{"n":13,"t":"耶和华如此说：亚扪人三番四次地犯罪，我必不免去他们的刑罚；因为他们剖开基列的孕妇，扩张自己的境界。","notes":[]},{"n":14,"t":"我却要在争战呐喊的日子，旋风狂暴的时候，点火在拉巴的城内，烧灭其中的宫殿。","notes":[]},{"n":15,"t":"他们的王和首领必一同被掳去。这是耶和华说的。","notes":[]}]},"2":{"heading":"神审判以色列","verses":[{"n":1,"t":"耶和华如此说：摩押三番四次地犯罪，我必不免去她的刑罚；因为她将以东王的骸骨焚烧成灰。","notes":[]},{"n":2,"t":"我却要降火在摩押，烧灭加略的宫殿。摩押必在哄嚷呐喊吹角之中死亡。","notes":[]},{"n":3,"t":"我必剪除摩押中的审判者，将其中的一切首领和他一同杀戮。这是耶和华说的。","notes":[]},{"n":4,"t":"耶和华如此说：犹大人三番四次地犯罪，我必不免去他们的刑罚；因为他们厌弃耶和华的训诲，不遵守他的律例。他们列祖所随从虚假的偶像使他们走迷了。","notes":[]},{"n":5,"t":"我却要降火在犹大，烧灭耶路撒冷的宫殿。","notes":[]},{"n":6,"t":"耶和华如此说：以色列人三番四次地犯罪，我必不免去他们的刑罚；因他们为银子卖了义人，为一双鞋卖了穷人。","notes":[]},{"n":7,"t":"他们见穷人头上所蒙的灰也都垂涎，阻碍谦卑人的道路。父子同一个女子行淫，亵渎我的圣名。","notes":[]},{"n":8,"t":"他们在各坛旁铺人所当的衣服，卧在其上，又在他们神的庙中喝受罚之人的酒。","notes":[]},{"n":9,"t":"我从以色列人面前除灭亚摩利人。他虽高大如香柏树，坚固如橡树，我却上灭他的果子，下绝他的根本。","notes":[]},{"n":10,"t":"我也将你们从埃及地领上来，在旷野引导你们四十年，使你们得亚摩利人之地为业。","notes":[]},{"n":11,"t":"我从你们子弟中兴起先知，又从你们少年人中兴起拿细耳人。以色列人哪，不是这样吗？这是耶和华说的。","notes":[]},{"n":12,"t":"你们却给拿细耳人酒喝，嘱咐先知说：不要说预言。","notes":[]},{"n":13,"t":"看哪，在你们所住之地，我必压你们，如同装满禾捆的车压物一样。","notes":[]},{"n":14,"t":"快跑的不能逃脱；有力的不能用力；刚勇的也不能自救。","notes":[]},{"n":15,"t":"拿弓的不能站立；腿快的不能逃脱；骑马的也不能自救。","notes":[]},{"n":16,"t":"到那日，勇士中最有胆量的，必赤身逃跑。这是耶和华说的。","notes":[]}]},"3":{"heading":"先知的任务","verses":[{"n":1,"t":"以色列人哪，你们全家是我从埃及地领上来的，当听耶和华攻击你们的话：","notes":[]},{"n":2,"t":"在地上万族中，我只认识你们；因此，我必追讨你们的一切罪孽。","notes":[]},{"n":3,"t":"二人若不同心，岂能同行呢？","notes":[]},{"n":4,"t":"狮子若非抓食，岂能在林中咆哮呢？少壮狮子若无所得，岂能从洞中发声呢？","notes":[]},{"n":5,"t":"若没有机槛，雀鸟岂能陷在网罗里呢？网罗若无所得，岂能从地上翻起呢？","notes":[]},{"n":6,"t":"城中若吹角，百姓岂不惊恐呢？灾祸若临到一城，岂非耶和华所降的吗？","notes":[]},{"n":7,"t":"主耶和华若不将奥秘指示他的仆人—众先知，就一无所行。","notes":[]},{"n":8,"t":"狮子吼叫，谁不惧怕呢？主耶和华发命，谁能不说预言呢？","notes":[]},{"n":9,"t":"要在亚实突的宫殿中和埃及地的宫殿里传扬说：你们要聚集在撒马利亚的山上，就看见城中有何等大的扰乱与欺压的事。","notes":[],"heads":["撒马利亚的结局"]},{"n":10,"t":"那些以强暴抢夺财物、积蓄在自己家中的人不知道行正直的事。这是耶和华说的。","notes":[]},{"n":11,"t":"所以主耶和华如此说：敌人必来围攻这地，使你的势力衰微，抢掠你的家宅。","notes":[]},{"n":12,"t":"耶和华如此说：「牧人怎样从狮子口中抢回两条羊腿或半个耳朵，住撒马利亚的以色列人躺卧在床角上或铺绣花毯的榻上，他们得救也不过如此。」","notes":[]},{"n":13,"t":"主耶和华—万军之神说：当听这话，警戒雅各家。","notes":[]},{"n":14,"t":"我讨以色列罪的日子，也要讨伯特利祭坛的罪；坛角必被砍下，坠落于地。","notes":[]},{"n":15,"t":"我要拆毁过冬和过夏的房屋。象牙的房屋也必毁灭；高大的房屋都归无有。这是耶和华说的。","notes":[]}]},"4":{"heading":"以色列的失败","verses":[{"n":1,"t":"你们住撒马利亚山如巴珊母牛的啊，当听我的话—你们欺负贫寒的，压碎穷乏的，对家主说：拿酒来，我们喝吧！","notes":[]},{"n":2,"t":"主耶和华指着自己的圣洁起誓说：日子快到，人必用钩子将你们钩去，用鱼钩将你们余剩的钩去。","notes":[]},{"n":3,"t":"你们各人必从破口直往前行，投入哈门。这是耶和华说的。","notes":[]},{"n":4,"t":"以色列人哪，任你们往伯特利去犯罪，到吉甲加增罪过；每日早晨献上你们的祭物，每三日奉上你们的十分之一。","notes":[]},{"n":5,"t":"任你们献有酵的感谢祭，把甘心祭宣传报告给众人，因为是你们所喜爱的。这是主耶和华说的。","notes":[]},{"n":6,"t":"我使你们在一切城中牙齿干净，在你们各处粮食缺乏，你们仍不归向我。这是耶和华说的。","notes":[]},{"n":7,"t":"在收割的前三月，我使雨停止，不降在你们那里；我降雨在这城，不降雨在那城；这块地有雨，那块地无雨；无雨的就枯干了。","notes":[]},{"n":8,"t":"这样，两三城的人凑到一城去找水，却喝不足；你们仍不归向我。这是耶和华说的。","notes":[]},{"n":9,"t":"我以旱风、霉烂攻击你们，你们园中许多菜蔬、葡萄树、无花果树、橄榄树都被剪虫所吃；你们仍不归向我。这是耶和华说的。","notes":[]},{"n":10,"t":"我降瘟疫在你们中间，像在埃及一样；用刀杀戮你们的少年人，使你们的马匹被掳掠，营中尸首的臭气扑鼻；你们仍不归向我。这是耶和华说的。","notes":[]},{"n":11,"t":"我倾覆你们中间的城邑，如同我从前倾覆所多玛、蛾摩拉一样，使你们好像从火中抽出来的一根柴；你们仍不归向我。这是耶和华说的。","notes":[]},{"n":12,"t":"以色列啊，我必向你如此行；以色列啊，我既这样行，你当预备迎见你的神。","notes":[]},{"n":13,"t":"那创山、造风、将心意指示人、使晨光变为幽暗、脚踏在地之高处的，他的名是耶和华—万军之神。","notes":[]}]},"5":{"heading":"呼吁以色列人悔改","verses":[{"n":1,"t":"以色列家啊，要听我为你们所作的哀歌：","notes":[]},{"n":2,"t":"以色列民跌倒，不得再起；躺在地上，无人搀扶。","notes":["原文是处女"]},{"n":3,"t":"主耶和华如此说：以色列家的城发出一千兵的，只剩一百；发出一百的，只剩十个。","notes":[]},{"n":4,"t":"耶和华向以色列家如此说：你们要寻求我，就必存活。","notes":[]},{"n":5,"t":"不要往伯特利寻求，不要进入吉甲，不要过到别是巴；因为吉甲必被掳掠，伯特利也必归于无有。","notes":[]},{"n":6,"t":"要寻求耶和华，就必存活，免得他在约瑟家像火发出，在伯特利焚烧，无人扑灭。","notes":[]},{"n":7,"t":"你们这使公平变为茵陈、将公义丢弃于地的，","notes":[]},{"n":8,"t":"要寻求那造昴星和参星，使死荫变为晨光，使白日变为黑夜，命海水来浇在地上的—耶和华是他的名；","notes":[]},{"n":9,"t":"他使力强的忽遭灭亡，以致保障遭遇毁坏。","notes":[]},{"n":10,"t":"你们怨恨那在城门口责备人的，憎恶那说正直话的。","notes":[]},{"n":11,"t":"你们践踏贫民，向他们勒索麦子；你们用凿过的石头建造房屋，却不得住在其内；栽种美好的葡萄园，却不得喝所出的酒。","notes":[]},{"n":12,"t":"我知道你们的罪过何等多，你们的罪恶何等大。你们苦待义人，收受贿赂，在城门口屈枉穷乏人。","notes":[]},{"n":13,"t":"所以通达人见这样的时势必静默不言，因为时势真恶。","notes":[]},{"n":14,"t":"你们要求善，不要求恶，就必存活。这样，耶和华—万军之神必照你们所说的与你们同在。","notes":[]},{"n":15,"t":"要恶恶好善，在城门口秉公行义；或者耶和华—万军之神向约瑟的余民施恩。","notes":[]},{"n":16,"t":"主耶和华—万军之神如此说：在一切宽阔处必有哀号的声音；在各街市上必有人说：哀哉！哀哉！又必叫农夫来哭号，叫善唱哀歌的来举哀。","notes":[]},{"n":17,"t":"在各葡萄园必有哀号的声音，因为我必从你中间经过。这是耶和华说的。","notes":[]},{"n":18,"t":"想望耶和华日子来到的有祸了！你们为何想望耶和华的日子呢？那日黑暗没有光明，","notes":[]},{"n":19,"t":"景况好像人躲避狮子又遇见熊，或是进房屋以手靠墙，就被蛇咬。","notes":[]},{"n":20,"t":"耶和华的日子不是黑暗没有光明吗？不是幽暗毫无光辉吗？","notes":[]},{"n":21,"t":"我厌恶你们的节期，也不喜悦你们的严肃会。","notes":[]},{"n":22,"t":"你们虽然向我献燔祭和素祭，我却不悦纳，也不顾你们用肥畜献的平安祭；","notes":[]},{"n":23,"t":"要使你们歌唱的声音远离我，因为我不听你们弹琴的响声。","notes":[]},{"n":24,"t":"惟愿公平如大水滚滚，使公义如江河滔滔。","notes":[]},{"n":25,"t":"「以色列家啊，你们在旷野四十年，岂是将祭物和供物献给我呢？","notes":[]},{"n":26,"t":"你们抬着为自己所造之摩洛的帐幕和偶像的龛，并你们的神星。","notes":[]},{"n":27,"t":"所以我要把你们掳到大马士革以外。」这是耶和华、名为万军之神说的。","notes":[]}]},"6":{"heading":"以色列的毁灭","verses":[{"n":1,"t":"国为列国之首，人最著名，且为以色列家所归向，在锡安和撒马利亚山安逸无虑的，有祸了！","notes":[]},{"n":2,"t":"你们要过到甲尼察看，从那里往大城哈马去，又下到非利士人的迦特，看那些国比你们的国还强吗？境界比你们的境界还宽吗？","notes":[]},{"n":3,"t":"你们以为降祸的日子还远，坐在位上尽行强暴。","notes":["或译：行强暴使审判临近"]},{"n":4,"t":"你们躺卧在象牙床上，舒身在榻上，吃群中的羊羔，棚里的牛犊；","notes":[]},{"n":5,"t":"弹琴鼓瑟唱消闲的歌曲，为自己制造乐器，如同大卫所造的；","notes":[]},{"n":6,"t":"以大碗喝酒，用上等的油抹身，却不为约瑟的苦难担忧。","notes":[]},{"n":7,"t":"所以这些人必在被掳的人中首先被掳；舒身的人荒宴之乐必消灭了。","notes":[]},{"n":8,"t":"主耶和华—万军之神指着自己起誓说：我憎恶雅各的荣华，厌弃他的宫殿；因此，我必将城和其中所有的都交付敌人。","notes":[]},{"n":9,"t":"那时，若在一房之内剩下十个人，也都必死。","notes":[]},{"n":10,"t":"死人的伯叔，就是烧他尸首的，要将这尸首搬到房外，问房屋内间的人说：「你那里还有人没有？」他必说：「没有」；又说：「不要作声，因为我们不可提耶和华的名。」","notes":[]},{"n":11,"t":"看哪，耶和华出令，大房就被攻破，小屋就被打裂。","notes":[]},{"n":12,"t":"马岂能在崖石上奔跑？人岂能在那里用牛耕种呢？你们却使公平变为苦胆，使公义的果子变为茵陈。","notes":[]},{"n":13,"t":"你们喜爱虚浮的事，自夸说：我们不是凭自己的力量取了角吗？","notes":[]},{"n":14,"t":"耶和华、万军之神说：以色列家啊，我必兴起一国攻击你们；他们必欺压你们，从哈马口直到亚拉巴的河。","notes":[]}]},"7":{"heading":"蝗虫的异象","verses":[{"n":1,"t":"主耶和华指示我一件事：为王割菜之后，菜又发生；刚发生的时候，主造蝗虫。","notes":["或译：草"]},{"n":2,"t":"蝗虫吃尽那地的青物，我就说：「主耶和华啊，求你赦免；因为雅各微弱，他怎能站立得住呢？」","notes":[]},{"n":3,"t":"耶和华就后悔说：「这灾可以免了。」","notes":[]},{"n":4,"t":"主耶和华又指示我一件事：他命火来惩罚以色列，火就吞灭深渊，险些将地烧灭。","notes":[],"heads":["火的异象"]},{"n":5,"t":"我就说：「主耶和华啊，求你止息；因为雅各微弱，他怎能站立得住呢？」","notes":[]},{"n":6,"t":"耶和华就后悔说：「这灾也可免了。」","notes":[]},{"n":7,"t":"他又指示我一件事：有一道墙是按准绳建筑的，主手拿准绳站在其上。","notes":[],"heads":["准绳的异象"]},{"n":8,"t":"耶和华对我说：「阿摩司啊，你看见什么？」我说：「看见准绳。」主说：「我要吊起准绳在我民以色列中，我必不再宽恕他们。","notes":[]},{"n":9,"t":"以撒的邱坛必然凄凉；以色列的圣所必然荒废。我必兴起，用刀攻击耶罗波安的家。」","notes":[]},{"n":10,"t":"伯特利的祭司亚玛谢打发人到以色列王耶罗波安那里，说：「阿摩司在以色列家中图谋背叛你；他所说的一切话，这国担当不起；","notes":[],"heads":["阿摩司和亚玛谢"]},{"n":11,"t":"因为阿摩司如此说：『耶罗波安必被刀杀；以色列民定被掳去离开本地。』」","notes":[]},{"n":12,"t":"亚玛谢又对阿摩司说：「你这先见哪，要逃往犹大地去，在那里糊口，在那里说预言，","notes":[]},{"n":13,"t":"却不要在伯特利再说预言；因为这里有王的圣所，有王的宫殿。」","notes":[]},{"n":14,"t":"阿摩司对亚玛谢说：「我原不是先知，也不是先知的门徒。我是牧人，又是修理桑树的。","notes":["原文是儿子"]},{"n":15,"t":"耶和华选召我，使我不跟从羊群，对我说：『你去向我民以色列说预言。』","notes":[]},{"n":16,"t":"亚玛谢啊，现在你要听耶和华的话。你说：『不要向以色列说预言，也不要向以撒家滴下预言。』","notes":[]},{"n":17,"t":"所以耶和华如此说：『你的妻子必在城中作妓女；你的儿女必倒在刀下。你的地必有人用绳子量了分取；你自己必死在污秽之地。以色列民定被掳去离开本地。』」","notes":[]}]},"8":{"heading":"一筐水果的异象","verses":[{"n":1,"t":"主耶和华又指示我一件事：我看见一筐夏天的果子。","notes":[]},{"n":2,"t":"他说：「阿摩司啊，你看见什么？」我说：「看见一筐夏天的果子。」耶和华说：「我民以色列的结局到了，我必不再宽恕他们。」","notes":[]},{"n":3,"t":"主耶和华说：「那日，殿中的诗歌变为哀号；必有许多尸首在各处抛弃，无人作声。」","notes":[]},{"n":4,"t":"你们这些要吞吃穷乏人、使困苦人衰败的，当听我的话！","notes":[],"heads":["以色列的结局"]},{"n":5,"t":"你们说：月朔几时过去，我们好卖粮；安息日几时过去，我们好摆开麦子；卖出用小升斗，收银用大戥子，用诡诈的天平欺哄人，","notes":[]},{"n":6,"t":"好用银子买贫寒人，用一双鞋换穷乏人，将坏了的麦子卖给人。","notes":[]},{"n":7,"t":"耶和华指着雅各的荣耀起誓说：他们的一切行为，我必永远不忘。","notes":[]},{"n":8,"t":"地岂不因这事震动？其上的居民不也悲哀吗？地必全然像尼罗河涨起，如同埃及河涌上落下。","notes":[]},{"n":9,"t":"主耶和华说：到那日，我必使日头在午间落下，使地在白昼黑暗。","notes":[]},{"n":10,"t":"我必使你们的节期变为悲哀，歌曲变为哀歌。众人腰束麻布，头上光秃，使这场悲哀如丧独生子，至终如痛苦的日子一样。","notes":[]},{"n":11,"t":"主耶和华说：日子将到，我必命饥荒降在地上。人饥饿非因无饼，干渴非因无水，乃因不听耶和华的话。","notes":[]},{"n":12,"t":"他们必飘流，从这海到那海，从北边到东边，往来奔跑，寻求耶和华的话，却寻不着。","notes":[]},{"n":13,"t":"当那日，美貌的处女和少年的男子必因干渴发昏。","notes":[]},{"n":14,"t":"那指着撒马利亚牛犊起誓的说：但哪，我们指着你那里的活神起誓；又说：我们指着别是巴的神道起誓。这些人都必仆倒，永不再起来。","notes":["原文是罪","神：原文是活"]}]},"9":{"heading":"耶和华的审判","verses":[{"n":1,"t":"我看见主站在祭坛旁边；他说：你要击打柱顶，使门槛震动，打碎柱顶，落在众人头上；所剩下的人，我必用刀杀戮，无一人能逃避，无一人能逃脱。","notes":[]},{"n":2,"t":"他们虽然挖透阴间，我的手必取出他们来；虽然爬上天去，我必拿下他们来；","notes":[]},{"n":3,"t":"虽然藏在迦密山顶，我必搜寻，捉出他们来；虽然从我眼前藏在海底，我必命蛇咬他们；","notes":[]},{"n":4,"t":"虽被仇敌掳去，我必命刀剑杀戮他们；我必向他们定住眼目，降祸不降福。","notes":[]},{"n":5,"t":"主—万军之耶和华摸地，地就消化，凡住在地上的都必悲哀。地必全然像尼罗河涨起，如同埃及河落下。","notes":[]},{"n":6,"t":"那在天上建造楼阁、在地上安定穹苍、命海水浇在地上的—耶和华是他的名。","notes":[]},{"n":7,"t":"耶和华说：以色列人哪，我岂不看你们如古实人吗？我岂不是领以色列人出埃及地，领非利士人出迦斐托，领亚兰人出吉珥吗？","notes":[]},{"n":8,"t":"主耶和华的眼目察看这有罪的国，必将这国从地上灭绝，却不将雅各家灭绝净尽。这是耶和华说的。","notes":[]},{"n":9,"t":"我必出令，将以色列家分散在列国中，好像用筛子筛谷，连一粒也不落在地上。","notes":[]},{"n":10,"t":"我民中的一切罪人说：灾祸必追不上我们，也迎不着我们。他们必死在刀下。","notes":[]},{"n":11,"t":"到那日，我必建立大卫倒塌的帐幕，堵住其中的破口，把那破坏的建立起来，重新修造，像古时一样，","notes":[],"heads":["以色列的未来复兴"]},{"n":12,"t":"使以色列人得以东所余剩的和所有称为我名下的国。此乃行这事的耶和华说的。","notes":[]},{"n":13,"t":"耶和华说：日子将到，耕种的必接续收割的；踹葡萄的必接续撒种的；大山要滴下甜酒；小山都必流奶。","notes":["原文是消化，见约珥三章十八节"]},{"n":14,"t":"我必使我民以色列被掳的归回；他们必重修荒废的城邑居住，栽种葡萄园，喝其中所出的酒，修造果木园，吃其中的果子。","notes":[]},{"n":15,"t":"我要将他们栽于本地，他们不再从我所赐给他们的地上拔出来。这是耶和华—你的神说的。","notes":[]}]}},"OBA":{"1":{"heading":"耶和华要惩罚以东","verses":[{"n":1,"t":"俄巴底亚得了耶和华的默示。论以东说：我从耶和华那里听见信息，并有使者被差往列国去，说：起来吧，一同起来与以东争战！","notes":[]},{"n":2,"t":"我使你—以东在列国中为最小的，被人大大藐视。","notes":[]},{"n":3,"t":"住在山穴中、居所在高处的啊，你因狂傲自欺，心里说：谁能将我拉下地去呢？","notes":[]},{"n":4,"t":"你虽如大鹰高飞，在星宿之间搭窝，我必从那里拉下你来。这是耶和华说的。","notes":[]},{"n":5,"t":"盗贼若来在你那里，或强盗夜间而来—你何竟被剪除—岂不偷窃直到够了呢？摘葡萄的若来到你那里，岂不剩下些葡萄呢？","notes":[]},{"n":6,"t":"以扫的隐密处何竟被搜寻？他隐藏的宝物何竟被查出？","notes":[]},{"n":7,"t":"与你结盟的都送你上路，直到交界；与你和好的欺骗你，且胜过你；与你一同吃饭的设下网罗陷害你；在你心里毫无聪明。","notes":[]},{"n":8,"t":"耶和华说：到那日，我岂不从以东除灭智慧人？从以扫山除灭聪明人？","notes":[]},{"n":9,"t":"提幔哪，你的勇士必惊惶，甚至以扫山的人都被杀戮剪除。","notes":[]},{"n":10,"t":"因你向兄弟雅各行强暴，羞愧必遮盖你，你也必永远断绝。","notes":[],"heads":["以东受罚的原因"]},{"n":11,"t":"当外人掳掠雅各的财物，外邦人进入他的城门，为耶路撒冷拈阄的日子，你竟站在一旁，像与他们同伙。","notes":[]},{"n":12,"t":"你兄弟遭难的日子，你不当瞪眼看着；犹大人被灭的日子，你不当因此欢乐；他们遭难的日子，你不当说狂傲的话。","notes":[]},{"n":13,"t":"我民遭灾的日子，你不当进他们的城门；他们遭灾的日子，你不当瞪眼看着他们受苦；他们遭灾的日子，你不当伸手抢他们的财物；","notes":[]},{"n":14,"t":"你不当站在岔路口剪除他们中间逃脱的；他们遭难的日子，你不当将他们剩下的人交付仇敌。","notes":[]},{"n":15,"t":"耶和华降罚的日子临近万国。你怎样行，他也必照样向你行；你的报应必归到你头上。","notes":[],"heads":["神要审判万国"]},{"n":16,"t":"你们犹大人在我圣山怎样喝了苦杯，万国也必照样常常地喝；且喝且咽，他们就归于无有。","notes":[]},{"n":17,"t":"在锡安山必有逃脱的人，那山也必成圣；雅各家必得原有的产业。","notes":[],"heads":["以色列的胜利"]},{"n":18,"t":"雅各家必成为大火；约瑟家必为火焰；以扫家必如碎秸；火必将他烧着吞灭。以扫家必无余剩的。这是耶和华说的。","notes":[]},{"n":19,"t":"南地的人必得以扫山；高原的人必得非利士地，也得以法莲地和撒马利亚地；便雅悯人必得基列。","notes":[]},{"n":20,"t":"在迦南人中被掳的以色列众人必得地直到撒勒法；在西法拉中被掳的耶路撒冷人必得南地的城邑。","notes":[]},{"n":21,"t":"必有拯救者上到锡安山，审判以扫山；国度就归耶和华了。","notes":[]}]}},"JON":{"1":{"heading":"约拿违背耶和华","verses":[{"n":1,"t":"耶和华的话临到亚米太的儿子约拿，说：","notes":[]},{"n":2,"t":"「你起来往尼尼微大城去，向其中的居民呼喊，因为他们的恶达到我面前。」","notes":[]},{"n":3,"t":"约拿却起来，逃往他施去躲避耶和华；下到约帕，遇见一只船，要往他施去。他就给了船价，上了船，要与船上的人同往他施去躲避耶和华。","notes":[]},{"n":4,"t":"然而耶和华使海中起大风，海就狂风大作，甚至船几乎破坏。","notes":[]},{"n":5,"t":"水手便惧怕，各人哀求自己的神。他们将船上的货物抛在海中，为要使船轻些。约拿已下到底舱，躺卧沉睡。","notes":[]},{"n":6,"t":"船主到他那里对他说：「你这沉睡的人哪，为何这样呢？起来，求告你的神，或者神顾念我们，使我们不致灭亡。」","notes":[]},{"n":7,"t":"船上的人彼此说：「来吧，我们掣签，看看这灾临到我们是因谁的缘故。」于是他们掣签，掣出约拿来。","notes":[]},{"n":8,"t":"众人对他说：「请你告诉我们，这灾临到我们是因谁的缘故？你以何事为业？你从哪里来？你是哪一国？属哪一族的人？」","notes":[]},{"n":9,"t":"他说：「我是希伯来人。我敬畏耶和华—那创造沧海旱地之天上的神。」","notes":[]},{"n":10,"t":"他们就大大惧怕，对他说：「你做的是什么事呢？」他们已经知道他躲避耶和华，因为他告诉了他们。","notes":[]},{"n":11,"t":"他们问他说：「我们当向你怎样行，使海浪平静呢？」这话是因海浪越发翻腾。","notes":[]},{"n":12,"t":"他对他们说：「你们将我抬起来，抛在海中，海就平静了；我知道你们遭这大风是因我的缘故。」","notes":[]},{"n":13,"t":"然而那些人竭力荡桨，要把船拢岸，却是不能，因为海浪越发向他们翻腾。","notes":[]},{"n":14,"t":"他们便求告耶和华说：「耶和华啊，我们恳求你，不要因这人的性命使我们死亡，不要使流无辜血的罪归与我们；因为你—耶和华是随自己的意旨行事。」","notes":[]},{"n":15,"t":"他们遂将约拿抬起，抛在海中，海的狂浪就平息了。","notes":[]},{"n":16,"t":"那些人便大大敬畏耶和华，向耶和华献祭，并且许愿。","notes":[]},{"n":17,"t":"耶和华安排一条大鱼吞了约拿，他在鱼腹中三日三夜。","notes":[]}]},"2":{"heading":"约拿的祷告","verses":[{"n":1,"t":"约拿在鱼腹中祷告耶和华—他的神，","notes":[]},{"n":2,"t":"说：我遭遇患难求告耶和华，你就应允我；从阴间的深处呼求，你就俯听我的声音。","notes":[]},{"n":3,"t":"你将我投下深渊，就是海的深处；大水环绕我，你的波浪洪涛都漫过我身。","notes":[]},{"n":4,"t":"我说：我从你眼前虽被驱逐，我仍要仰望你的圣殿。","notes":[]},{"n":5,"t":"诸水环绕我，几乎淹没我；深渊围住我；海草缠绕我的头。","notes":[]},{"n":6,"t":"我下到山根，地的门将我永远关住。耶和华—我的神啊，你却将我的性命从坑中救出来。","notes":[]},{"n":7,"t":"我心在我里面发昏的时候，我就想念耶和华。我的祷告进入你的圣殿，达到你的面前。","notes":[]},{"n":8,"t":"那信奉虚无之神的人，离弃怜爱他们的主；","notes":[]},{"n":9,"t":"但我必用感谢的声音献祭与你。我所许的愿，我必偿还。救恩出于耶和华。","notes":[]},{"n":10,"t":"耶和华吩咐鱼，鱼就把约拿吐在旱地上。","notes":[]}]},"3":{"heading":"约拿顺服耶和华","verses":[{"n":1,"t":"耶和华的话二次临到约拿说：","notes":[]},{"n":2,"t":"「你起来！往尼尼微大城去，向其中的居民宣告我所吩咐你的话。」","notes":[]},{"n":3,"t":"约拿便照耶和华的话起来，往尼尼微去。这尼尼微是极大的城，有三日的路程。","notes":[]},{"n":4,"t":"约拿进城走了一日，宣告说：「再等四十日，尼尼微必倾覆了！」","notes":[]},{"n":5,"t":"尼尼微人信服神，便宣告禁食，从最大的到至小的都穿麻衣。","notes":["或译：披上麻布"]},{"n":6,"t":"这信息传到尼尼微王的耳中，他就下了宝座，脱下朝服，披上麻布，坐在灰中。","notes":[]},{"n":7,"t":"他又使人遍告尼尼微通城，说：「王和大臣有令，人不可尝什么，牲畜、牛羊不可吃草，也不可喝水。","notes":[]},{"n":8,"t":"人与牲畜都当披上麻布；人要切切求告神。各人回头离开所行的恶道，丢弃手中的强暴。","notes":[]},{"n":9,"t":"或者神转意后悔，不发烈怒，使我们不致灭亡，也未可知。」","notes":[]},{"n":10,"t":"于是神察看他们的行为，见他们离开恶道，他就后悔，不把所说的灾祸降与他们了。","notes":[]}]},"4":{"heading":"约拿的忿怒和神的怜悯","verses":[{"n":1,"t":"这事约拿大大不悦，且甚发怒，","notes":[]},{"n":2,"t":"就祷告耶和华说：「耶和华啊，我在本国的时候岂不是这样说吗？我知道你是有恩典、有怜悯的神，不轻易发怒，有丰盛的慈爱，并且后悔不降所说的灾，所以我急速逃往他施去。","notes":[]},{"n":3,"t":"耶和华啊，现在求你取我的命吧！因为我死了比活着还好。」","notes":[]},{"n":4,"t":"耶和华说：「你这样发怒合乎理吗？」","notes":[]},{"n":5,"t":"于是约拿出城，坐在城的东边，在那里为自己搭了一座棚，坐在棚的荫下，要看看那城究竟如何。","notes":[]},{"n":6,"t":"耶和华神安排一棵蓖麻，使其发生高过约拿，影儿遮盖他的头，救他脱离苦楚；约拿因这棵蓖麻大大喜乐。","notes":[]},{"n":7,"t":"次日黎明，神却安排一条虫子咬这蓖麻，以致枯槁。","notes":[]},{"n":8,"t":"日头出来的时候，神安排炎热的东风，日头曝晒约拿的头，使他发昏，他就为自己求死，说：「我死了比活着还好！」","notes":[]},{"n":9,"t":"神对约拿说：「你因这棵蓖麻发怒合乎理吗？」他说：「我发怒以至于死，都合乎理！」","notes":[]},{"n":10,"t":"耶和华说：「这蓖麻不是你栽种的，也不是你培养的；一夜发生，一夜干死，你尚且爱惜；","notes":[]},{"n":11,"t":"何况这尼尼微大城，其中不能分辨左手右手的有十二万多人，并有许多牲畜，我岂能不爱惜呢？」","notes":[]}]}},"MIC":{"1":{"heading":"为撒马利亚和耶路撒冷唱哀歌","verses":[{"n":1,"t":"当犹大王约坦、亚哈斯、希西家在位的时候，摩利沙人弥迦得耶和华的默示，论撒马利亚和耶路撒冷。","notes":[]},{"n":2,"t":"万民哪，你们都要听！地和其上所有的，也都要侧耳而听！主耶和华从他的圣殿要见证你们的不是。","notes":[]},{"n":3,"t":"看哪，耶和华出了他的居所，降临步行地的高处。","notes":[]},{"n":4,"t":"众山在他以下必消化，诸谷必崩裂，如蜡化在火中，如水冲下山坡。","notes":[]},{"n":5,"t":"这都因雅各的罪过，以色列家的罪恶。雅各的罪过在哪里呢？岂不是在撒马利亚吗？犹大的邱坛在哪里呢？岂不是在耶路撒冷吗？","notes":[]},{"n":6,"t":"所以我必使撒马利亚变为田野的乱堆，又作为种葡萄之处；也必将她的石头倒在谷中，露出根基来。","notes":[]},{"n":7,"t":"她一切雕刻的偶像必被打碎；她所得的财物必被火烧；所有的偶像我必毁灭；因为是从妓女雇价所聚来的，后必归为妓女的雇价。","notes":[]},{"n":8,"t":"先知说：因此我必大声哀号，赤脚露体而行；又要呼号如野狗，哀鸣如鸵鸟。","notes":[]},{"n":9,"t":"因为撒马利亚的伤痕无法医治，延及犹大和耶路撒冷我民的城门。","notes":[]},{"n":10,"t":"不要在迦特报告这事，总不要哭泣；我在伯·亚弗拉滚于灰尘之中。","notes":[],"heads":["敌人迫近耶路撒冷"]},{"n":11,"t":"沙斐的居民哪，你们要赤身蒙羞过去。撒南的居民不敢出来。伯·以薛人的哀哭使你们无处可站。","notes":[]},{"n":12,"t":"玛律的居民心甚忧急，切望得好处，因为灾祸从耶和华那里临到耶路撒冷的城门。","notes":[]},{"n":13,"t":"拉吉的居民哪，要用快马套车；锡安民的罪由你而起；以色列人的罪过在你那里显出。","notes":["原文是女子"]},{"n":14,"t":"犹大啊，你要将礼物送给摩利设·迦特。亚革悉的众族必用诡诈待以色列诸王。","notes":[]},{"n":15,"t":"玛利沙的居民哪，我必使那夺取你的来到你这里；以色列的尊贵人必到亚杜兰。","notes":["原文是荣耀"]},{"n":16,"t":"犹大啊，要为你所喜爱的儿女剪除你的头发，使头光秃，要大大地光秃，如同秃鹰，因为他们都被掳去离开你。","notes":[]}]},"2":{"heading":"欺压者的命运","verses":[{"n":1,"t":"祸哉，那些在床上图谋罪孽、造作奸恶的！天一发亮，因手有能力就行出来了。","notes":[]},{"n":2,"t":"他们贪图田地就占据，贪图房屋便夺取；他们欺压人，霸占房屋和产业。","notes":[]},{"n":3,"t":"所以耶和华如此说：我筹划灾祸降与这族；这祸在你们的颈项上不能解脱；你们也不能昂首而行，因为这时势是恶的。","notes":[]},{"n":4,"t":"到那日，必有人向你们提起悲惨的哀歌，讥刺说：我们全然败落了！耶和华将我们的分转归别人，何竟使这分离开我们？他将我们的田地分给悖逆的人。","notes":[]},{"n":5,"t":"所以在耶和华的会中，你必没有人拈阄拉准绳。","notes":[]},{"n":6,"t":"他们说：你们不可说预言；不可向这些人说预言，不住地羞辱我们。","notes":["或译：假先知"]},{"n":7,"t":"雅各家啊，岂可说耶和华的心不忍耐吗？这些事是他所行的吗？我—耶和华的言语岂不是与行动正直的人有益吗？","notes":["或译：心肠狭窄吗"]},{"n":8,"t":"然而，近来我的民兴起如仇敌，从那些安然经过不愿打仗之人身上剥去外衣。","notes":[]},{"n":9,"t":"你们将我民中的妇人从安乐家中赶出，又将我的荣耀从她们的小孩子尽行夺去。","notes":[]},{"n":10,"t":"你们起来去吧！这不是你们安息之所；因为污秽使人毁灭，而且大大毁灭。","notes":["或译：地"]},{"n":11,"t":"若有人心存虚假，用谎言说：我要向你们预言得清酒和浓酒。那人就必作这民的先知。","notes":[]},{"n":12,"t":"雅各家啊，我必要聚集你们，必要招聚以色列剩下的人，安置在一处，如波斯拉的羊，又如草场上的羊群；因为人数众多就必大大喧哗。","notes":[]},{"n":13,"t":"开路的在他们前面上去；他们直闯过城门，从城门出去。他们的王在前面行；耶和华引导他们。","notes":["或译：破城的"]}]},"3":{"heading":"弥迦斥责以色列的领袖","verses":[{"n":1,"t":"我说：雅各的首领，以色列家的官长啊，你们要听！你们不当知道公平吗？","notes":[]},{"n":2,"t":"你们恶善好恶，从人身上剥皮，从人骨头上剔肉，","notes":[]},{"n":3,"t":"吃我民的肉，剥他们的皮，打折他们的骨头，分成块子像要下锅，又像釜中的肉。","notes":[]},{"n":4,"t":"到了遭灾的时候，这些人必哀求耶和华，他却不应允他们。那时他必照他们所行的恶事向他们掩面。","notes":[]},{"n":5,"t":"论到使我民走差路的先知—他们牙齿有所嚼的，他们就呼喊说：平安了！凡不供给他们吃的，他们就预备攻击他—耶和华如此说：","notes":["预备攻击他：或译说必遭遇刀兵"]},{"n":6,"t":"你们必遭遇黑夜，以致不见异象；又必遭遇幽暗，以致不能占卜。日头必向你们沉落，白昼变为黑暗。","notes":[]},{"n":7,"t":"先见必抱愧，占卜的必蒙羞，都必捂着嘴唇，因为神不应允他们。","notes":[]},{"n":8,"t":"至于我，我借耶和华的灵，满有力量、公平、才能，可以向雅各说明他的过犯，向以色列指出他的罪恶。","notes":[]},{"n":9,"t":"雅各家的首领、以色列家的官长啊，当听我的话！你们厌恶公平，在一切事上屈枉正直；","notes":[]},{"n":10,"t":"以人血建立锡安，以罪孽建造耶路撒冷。","notes":[]},{"n":11,"t":"首领为贿赂行审判；祭司为雇价施训诲；先知为银钱行占卜。他们却倚赖耶和华，说：耶和华不是在我们中间吗？灾祸必不临到我们。","notes":[]},{"n":12,"t":"所以因你们的缘故，锡安必被耕种像一块田，耶路撒冷必变为乱堆；这殿的山必像丛林的高处。","notes":[]}]},"4":{"heading":"耶和华作王，天下太平","verses":[{"n":1,"t":"末后的日子，耶和华殿的山必坚立，超乎诸山，高举过于万岭；万民都要流归这山。","notes":[]},{"n":2,"t":"必有许多国的民前往，说：来吧，我们登耶和华的山，奔雅各神的殿。主必将他的道教训我们；我们也要行他的路。因为训诲必出于锡安；耶和华的言语必出于耶路撒冷。","notes":[]},{"n":3,"t":"他必在多国的民中施行审判，为远方强盛的国断定是非。他们要将刀打成犁头，把枪打成镰刀。这国不举刀攻击那国；他们也不再学习战事。","notes":[]},{"n":4,"t":"人人都要坐在自己葡萄树下和无花果树下，无人惊吓。这是万军之耶和华亲口说的。","notes":[]},{"n":5,"t":"万民各奉己神的名而行；我们却永永远远奉耶和华—我们神的名而行。","notes":[]},{"n":6,"t":"耶和华说：到那日，我必聚集瘸腿的，招聚被赶出的和我所惩治的。","notes":[],"heads":["以色列人归回本国"]},{"n":7,"t":"我必使瘸腿的为余剩之民，使赶到远方的为强盛之民。耶和华要在锡安山作王治理他们，从今直到永远。","notes":[]},{"n":8,"t":"你这羊群的高台、锡安城的山哪，从前的权柄—就是耶路撒冷民的国权—必归与你。","notes":["原文是女子","原文是女子"]},{"n":9,"t":"现在你为何大声哭号呢？疼痛抓住你仿佛产难的妇人，是因你中间没有君王吗？你的谋士灭亡了吗？","notes":[]},{"n":10,"t":"锡安的民哪，你要疼痛劬劳，仿佛产难的妇人；因为你必从城里出来，住在田野，到巴比伦去。在那里要蒙解救；在那里耶和华必救赎你脱离仇敌的手。","notes":["原文是女子"]},{"n":11,"t":"现在有许多国的民聚集攻击你，说：愿锡安被玷污！愿我们亲眼见她遭报！","notes":[]},{"n":12,"t":"他们却不知道耶和华的意念，也不明白他的筹划。他聚集他们，好像把禾捆聚到禾场一样。","notes":[]},{"n":13,"t":"锡安的民哪，起来踹谷吧！我必使你的角成为铁，使你的蹄成为铜。你必打碎多国的民，将他们的财献与耶和华，将他们的货献与普天下的主。","notes":["原文是女子"]}]},"5":{"heading":"神应许一位掌权者出于伯利恒","verses":[{"n":1,"t":"成群的民哪，现在你要聚集成队；因为仇敌围攻我们，要用杖击打以色列审判者的脸。","notes":["原文是女子"]},{"n":2,"t":"伯利恒的以法他啊，你在犹大诸城中为小，将来必有一位从你那里出来，在以色列中为我作掌权的；他的根源从亘古，从太初就有。","notes":[]},{"n":3,"t":"耶和华必将以色列人交付敌人，直等那生产的妇人生下子来。那时掌权者其余的弟兄必归到以色列人那里。","notes":["原文是他"]},{"n":4,"t":"他必起来，倚靠耶和华的大能，并耶和华—他神之名的威严，牧养他的羊群。他们要安然居住；因为他必日见尊大，直到地极。","notes":[]},{"n":5,"t":"这位必作我们的平安。当亚述人进入我们的地境，践踏宫殿的时候，我们就立起七个牧者，八个首领攻击他。","notes":[]},{"n":6,"t":"他们必用刀剑毁坏亚述地和宁录地的关口。亚述人进入我们的地境践踏的时候，他必拯救我们。","notes":[]},{"n":7,"t":"雅各余剩的人必在多国的民中，如从耶和华那里降下的露水，又如甘霖降在草上；不仗赖人力，也不等候世人之功。","notes":[]},{"n":8,"t":"雅各余剩的人必在多国多民中，如林间百兽中的狮子，又如少壮狮子在羊群中。他若经过就必践踏撕裂，无人搭救。","notes":[]},{"n":9,"t":"愿你的手举起，高过敌人！愿你的仇敌都被剪除！","notes":[]},{"n":10,"t":"耶和华说：到那日，我必从你中间剪除马匹，毁坏车辆，","notes":[]},{"n":11,"t":"也必从你国中除灭城邑，拆毁一切的保障，","notes":[]},{"n":12,"t":"又必除掉你手中的邪术；你那里也不再有占卜的。","notes":[]},{"n":13,"t":"我必从你中间除灭雕刻的偶像和柱像，你就不再跪拜自己手所造的。","notes":[]},{"n":14,"t":"我必从你中间拔出木偶，又毁灭你的城邑。","notes":[]},{"n":15,"t":"我也必在怒气和忿怒中向那不听从的列国施报。","notes":[]}]},"6":{"heading":"耶和华谴责以色列","verses":[{"n":1,"t":"以色列人哪，当听耶和华的话！要起来向山岭争辩，使冈陵听你的话。","notes":[]},{"n":2,"t":"山岭和地永久的根基啊，要听耶和华争辩的话！因为耶和华要与他的百姓争辩，与以色列争论。","notes":[]},{"n":3,"t":"我的百姓啊，我向你做了什么呢？我在什么事上使你厌烦？你可以对我证明。","notes":[]},{"n":4,"t":"我曾将你从埃及地领出来，从作奴仆之家救赎你；我也差遣摩西、亚伦，和米利暗在你前面行。","notes":[]},{"n":5,"t":"我的百姓啊，你们当追念摩押王巴勒所设的谋和比珥的儿子巴兰回答他的话，并你们从什亭到吉甲所遇见的事，好使你们知道耶和华公义的作为。","notes":[]},{"n":6,"t":"我朝见耶和华，在至高神面前跪拜，当献上什么呢？岂可献一岁的牛犊为燔祭吗？","notes":[],"heads":["耶和华的要求"]},{"n":7,"t":"耶和华岂喜悦千千的公羊，或是万万的油河吗？我岂可为自己的罪过献我的长子吗？为心中的罪恶献我身所生的吗？","notes":[]},{"n":8,"t":"世人哪，耶和华已指示你何为善。他向你所要的是什么呢？只要你行公义，好怜悯，存谦卑的心，与你的神同行。","notes":[]},{"n":9,"t":"耶和华向这城呼叫，智慧人必敬畏他的名。你们当听是谁派定刑杖的惩罚。","notes":[]},{"n":10,"t":"恶人家中不仍有非义之财和可恶的小升斗吗？","notes":[]},{"n":11,"t":"我若用不公道的天平和囊中诡诈的法码，岂可算为清洁呢？","notes":[]},{"n":12,"t":"城里的富户满行强暴；其中的居民也说谎言，口中的舌头是诡诈的。","notes":[]},{"n":13,"t":"因此，我击打你，使你的伤痕甚重，使你因你的罪恶荒凉。","notes":[]},{"n":14,"t":"你要吃，却吃不饱；你的虚弱必显在你中间。你必挪去，却不得救护；所救护的，我必交给刀剑。","notes":[]},{"n":15,"t":"你必撒种，却不得收割；踹橄榄，却不得油抹身；踹葡萄，却不得酒喝。","notes":[]},{"n":16,"t":"因为你守暗利的恶规，行亚哈家一切所行的，顺从他们的计谋；因此，我必使你荒凉，使你的居民令人嗤笑，你们也必担当我民的羞辱。","notes":[]}]},"7":{"heading":"以色列人的腐败","verses":[{"n":1,"t":"哀哉！我好像夏天的果子已被收尽，又像摘了葡萄所剩下的，没有一挂可吃的；我心羡慕初熟的无花果。","notes":["或译：以色列"]},{"n":2,"t":"地上虔诚人灭尽；世间没有正直人；各人埋伏，要杀人流血，都用网罗猎取弟兄。","notes":[]},{"n":3,"t":"他们双手作恶；君王徇情面，审判官要贿赂；位分大的吐出恶意，都彼此结联行恶。","notes":[]},{"n":4,"t":"他们最好的，不过是蒺藜；最正直的，不过是荆棘篱笆。你守望者说，降罚的日子已经来到。他们必扰乱不安。","notes":[]},{"n":5,"t":"不要倚赖邻舍；不要信靠密友。要守住你的口；不要向你怀中的妻提说。","notes":[]},{"n":6,"t":"因为，儿子藐视父亲；女儿抗拒母亲；媳妇抗拒婆婆；人的仇敌就是自己家里的人。","notes":[]},{"n":7,"t":"至于我，我要仰望耶和华，要等候那救我的神；我的神必应允我。","notes":[]},{"n":8,"t":"我的仇敌啊，不要向我夸耀。我虽跌倒，却要起来；我虽坐在黑暗里，耶和华却作我的光。","notes":[],"heads":["耶和华拯救他的子民"]},{"n":9,"t":"我要忍受耶和华的恼怒；因我得罪了他，直等他为我辨屈，为我伸冤。他必领我到光明中；我必得见他的公义。","notes":[]},{"n":10,"t":"那时我的仇敌，就是曾对我说「耶和华—你神在哪里」的，他一看见这事就被羞愧遮盖。我必亲眼见他遭报；他必被践踏，如同街上的泥土。","notes":[]},{"n":11,"t":"以色列啊，日子必到，你的墙垣必重修；到那日，你的境界必开展。","notes":["或译：命令必传到远方"]},{"n":12,"t":"当那日，人必从亚述，从埃及的城邑，从埃及到大河，从这海到那海，从这山到那山，都归到你这里。","notes":[]},{"n":13,"t":"然而，这地因居民的缘故，又因他们行事的结果，必然荒凉。","notes":[]},{"n":14,"t":"求耶和华在迦密山的树林中，用你的杖牧放你独居的民，就是你产业的羊群。求你容他们在巴珊和基列得食物，像古时一样。","notes":[],"heads":["耶和华怜悯以色列"]},{"n":15,"t":"耶和华说：我要把奇事显给他们看，好像出埃及地的时候一样。","notes":[]},{"n":16,"t":"列国看见这事就必为自己的势力惭愧；他们必用手捂口，掩耳不听。","notes":[]},{"n":17,"t":"他们必舔土如蛇，又如土中腹行的物，战战兢兢地出他们的营寨。他们必战惧投降耶和华，也必因我们的神而惧怕。","notes":[]},{"n":18,"t":"神啊，有何神像你，赦免罪孽，饶恕你产业之余民的罪过，不永远怀怒，喜爱施恩？","notes":[]},{"n":19,"t":"必再怜悯我们，将我们的罪孽踏在脚下，又将我们的一切罪投于深海。","notes":[]},{"n":20,"t":"你必按古时起誓应许我们列祖的话，向雅各发诚实，向亚伯拉罕施慈爱。","notes":[]}]}},"NAM":{"1":{"heading":"耶和华向尼尼微发怒","verses":[{"n":1,"t":"论尼尼微的默示，就是伊勒歌斯人那鸿所得的默示。","notes":[]},{"n":2,"t":"耶和华是忌邪施报的神。耶和华施报大有忿怒；向他的敌人施报，向他的仇敌怀怒。","notes":[]},{"n":3,"t":"耶和华不轻易发怒，大有能力，万不以有罪的为无罪。他乘旋风和暴风而来，云彩为他脚下的尘土。","notes":[]},{"n":4,"t":"他斥责海，使海干了，使一切江河干涸。巴珊和迦密的树林衰残；黎巴嫩的花草也衰残了。","notes":[]},{"n":5,"t":"大山因他震动；小山也都消化。大地在他面前突起；世界和住在其间的也都如此。","notes":[]},{"n":6,"t":"他发忿恨，谁能立得住呢？他发烈怒，谁能当得起呢？他的忿怒如火倾倒；磐石因他崩裂。","notes":[]},{"n":7,"t":"耶和华本为善，在患难的日子为人的保障，并且认得那些投靠他的人。","notes":[]},{"n":8,"t":"但他必以涨溢的洪水淹没尼尼微，又驱逐仇敌进入黑暗。","notes":[]},{"n":9,"t":"尼尼微人哪，设何谋攻击耶和华呢？他必将你们灭绝净尽；灾难不再兴起。","notes":[]},{"n":10,"t":"你们像丛杂的荆棘，像喝醉了的人，又如枯干的碎秸全然烧灭。","notes":[]},{"n":11,"t":"有一人从你那里出来，图谋邪恶，设恶计攻击耶和华。","notes":[]},{"n":12,"t":"耶和华如此说：尼尼微虽然势力充足，人数繁多，也被剪除，归于无有。犹大啊，我虽然使你受苦，却不再使你受苦。","notes":[]},{"n":13,"t":"现在我必从你颈项上折断他的轭，扭开他的绳索。","notes":[]},{"n":14,"t":"耶和华已经出令，指着尼尼微说：你名下的人必不留后；我必从你神的庙中除灭雕刻的偶像和铸造的偶像；我必因你鄙陋，使你归于坟墓。","notes":[]},{"n":15,"t":"看哪，有报好信传平安之人的脚登山，说：犹大啊，可以守你的节期，还你所许的愿吧！因为那恶人不再从你中间经过，他已灭绝净尽了。","notes":[]}]},"2":{"heading":"尼尼微的倾覆","verses":[{"n":1,"t":"尼尼微啊，那打碎邦国的上来攻击你。你要看守保障，谨防道路，使腰强壮，大大勉力。","notes":[]},{"n":2,"t":"耶和华复兴雅各的荣华，好像以色列的荣华一样；因为使地空虚的，已经使雅各和以色列空虚，将他们的葡萄枝毁坏了。）","notes":[]},{"n":3,"t":"他勇士的盾牌是红的，精兵都穿朱红衣服。在他预备争战的日子，战车上的钢铁闪烁如火，柏木把的枪也抡起来了。","notes":[]},{"n":4,"t":"车辆在街上急行，在宽阔处奔来奔去，形状如火把，飞跑如闪电。","notes":["或译：城外"]},{"n":5,"t":"尼尼微王招聚他的贵胄；他们步行绊跌，速上城墙，预备挡牌。","notes":[]},{"n":6,"t":"河闸开放，宫殿冲没。","notes":[]},{"n":7,"t":"王后蒙羞，被人掳去；宫女捶胸，哀鸣如鸽。此乃命定之事。","notes":[]},{"n":8,"t":"尼尼微自古以来充满人民，如同聚水的池子；现在居民却都逃跑。虽有人呼喊说：站住！站住！却无人回顾。","notes":[]},{"n":9,"t":"你们抢掠金银吧！因为所积蓄的无穷，华美的宝器无数。","notes":[]},{"n":10,"t":"尼尼微现在空虚荒凉，人心消化，双膝相碰，腰都疼痛，脸都变色。","notes":[]},{"n":11,"t":"狮子的洞和少壮狮子喂养之处在哪里呢？公狮母狮小狮游行、无人惊吓之地在哪里呢？","notes":[]},{"n":12,"t":"公狮为小狮撕碎许多食物，为母狮掐死活物，把撕碎的、掐死的充满它的洞穴。","notes":[]},{"n":13,"t":"万军之耶和华说：「我与你为敌，必将你的车辆焚烧成烟，刀剑也必吞灭你的少壮狮子。我必从地上除灭你所撕碎的，你使者的声音必不再听见。」","notes":[]}]},"3":{"heading":"","verses":[{"n":1,"t":"祸哉！这流人血的城，充满谎诈和强暴—抢夺的事总不止息。","notes":[]},{"n":2,"t":"鞭声响亮，车轮轰轰，马匹踢跳，车辆奔腾，","notes":[]},{"n":3,"t":"马兵争先，刀剑发光，枪矛闪烁，被杀的甚多，尸首成了大堆，尸骸无数，人碰着而跌倒，","notes":[]},{"n":4,"t":"都因那美貌的妓女多有淫行，惯行邪术，借淫行诱惑列国，用邪术诱惑多族。","notes":["原文是卖"]},{"n":5,"t":"万军之耶和华说：我与你为敌；我必揭起你的衣襟，蒙在你脸上，使列国看见你的赤体，使列邦观看你的丑陋。","notes":[]},{"n":6,"t":"我必将可憎污秽之物抛在你身上，辱没你，为众目所观。","notes":[]},{"n":7,"t":"凡看见你的，都必逃跑离开你，说：尼尼微荒凉了！有谁为你悲伤呢？我何处寻得安慰你的人呢？","notes":[]},{"n":8,"t":"你岂比挪亚们强呢？挪亚们坐落在众河之间，周围有水；海作她的濠沟，又作她的城墙。","notes":["指尼罗河"]},{"n":9,"t":"古实和埃及是她无穷的力量；弗人和路比族是她的帮手。","notes":[]},{"n":10,"t":"但她被迁移，被掳去；她的婴孩在各市口上也被摔死。人为她的尊贵人拈阄；她所有的大人都被链子锁着。","notes":[]},{"n":11,"t":"你也必喝醉，必被埋藏，并因仇敌的缘故寻求避难所。","notes":[]},{"n":12,"t":"你一切保障必像无花果树上初熟的无花果，若一摇撼就落在想吃之人的口中。","notes":[]},{"n":13,"t":"你地上的人民如同妇女；你国中的关口向仇敌敞开；你的门闩被火焚烧。","notes":[]},{"n":14,"t":"你要打水预备受困；要坚固你的保障，踹土和泥，修补砖窑。","notes":[]},{"n":15,"t":"在那里，火必烧灭你；刀必杀戮你，吞灭你如同蝻子。任你加增人数多如蝻子，多如蝗虫吧！","notes":[]},{"n":16,"t":"你增添商贾，多过天上的星；蝻子吃尽而去。","notes":[]},{"n":17,"t":"你的首领多如蝗虫；你的军长仿佛成群的蚂蚱，天凉的时候齐落在篱笆上，日头一出便都飞去，人不知道落在何处。","notes":[]},{"n":18,"t":"亚述王啊，你的牧人睡觉；你的贵胄安歇；你的人民散在山间，无人招聚。","notes":[]},{"n":19,"t":"你的损伤无法医治；你的伤痕极其重大。凡听你信息的必都因此向你拍掌。你所行的恶谁没有时常遭遇呢？","notes":[]}]}},"HAB":{"1":{"heading":"哈巴谷为不公平而诉苦","verses":[{"n":1,"t":"先知哈巴谷所得的默示。","notes":[]},{"n":2,"t":"他说：耶和华啊！我呼求你，你不应允，要到几时呢？我因强暴哀求你，你还不拯救。","notes":[]},{"n":3,"t":"你为何使我看见罪孽？你为何看着奸恶而不理呢？毁灭和强暴在我面前，又起了争端和相斗的事。","notes":[]},{"n":4,"t":"因此律法放松，公理也不显明；恶人围困义人，所以公理显然颠倒。","notes":[]},{"n":5,"t":"耶和华说：你们要向列国中观看，大大惊奇；因为在你们的时候，我行一件事，虽有人告诉你们，你们总是不信。","notes":[],"heads":["耶和华的回答"]},{"n":6,"t":"我必兴起迦勒底人，就是那残忍暴躁之民，通行遍地，占据那不属自己的住处。","notes":[]},{"n":7,"t":"他威武可畏，判断和势力都任意发出。","notes":[]},{"n":8,"t":"他的马比豹更快，比晚上的豺狼更猛。马兵踊跃争先，都从远方而来；他们飞跑如鹰抓食，","notes":[]},{"n":9,"t":"都为行强暴而来，定住脸面向前，将掳掠的人聚集，多如尘沙。","notes":[]},{"n":10,"t":"他们讥诮君王，笑话首领，嗤笑一切保障，筑垒攻取。","notes":[]},{"n":11,"t":"他以自己的势力为神，像风猛然扫过，显为有罪。","notes":[]},{"n":12,"t":"耶和华—我的神，我的圣者啊，你不是从亘古而有吗？我们必不致死。耶和华啊，你派定他为要刑罚人；磐石啊，你设立他为要惩治人。","notes":[],"heads":["哈巴谷又向耶和华诉苦"]},{"n":13,"t":"你眼目清洁，不看邪僻，不看奸恶；行诡诈的，你为何看着不理呢？恶人吞灭比自己公义的，你为何静默不语呢？","notes":[]},{"n":14,"t":"你为何使人如海中的鱼，又如没有管辖的爬物呢？","notes":[]},{"n":15,"t":"他用钩钩住，用网捕获，用拉网聚集他们；因此，他欢喜快乐，","notes":[]},{"n":16,"t":"就向网献祭，向网烧香，因他由此得肥美的分和富裕的食物。","notes":[]},{"n":17,"t":"他岂可屡次倒空网罗，将列国的人时常杀戮，毫不顾惜呢？","notes":[]}]},"2":{"heading":"耶和华回答哈巴谷","verses":[{"n":1,"t":"我要站在守望所，立在望楼上观看，看耶和华对我说什么话，我可用什么话向他诉冤。","notes":["向他诉冤：或译回答所疑问的"]},{"n":2,"t":"他对我说：将这默示明明地写在版上，使读的人容易读。","notes":["或译：随跑随读"]},{"n":3,"t":"因为这默示有一定的日期，快要应验，并不虚谎。虽然迟延，还要等候；因为必然临到，不再迟延。","notes":[]},{"n":4,"t":"迦勒底人自高自大，心不正直；惟义人因信得生。","notes":[]},{"n":5,"t":"迦勒底人因酒诡诈，狂傲，不住在家中，扩充心欲，好像阴间。他如死不能知足，聚集万国，堆积万民都归自己。","notes":[],"heads":["不义的结局"]},{"n":6,"t":"这些国的民岂不都要提起诗歌并俗语讥刺他说：祸哉！迦勒底人，你增添不属自己的财物，多多取人的当头，要到几时为止呢？","notes":[]},{"n":7,"t":"咬伤你的岂不忽然起来，扰害你的岂不兴起，你就作他们的掳物吗？","notes":[]},{"n":8,"t":"因你抢夺许多的国，杀人流血，向国内的城并城中一切居民施行强暴，所以各国剩下的民都必抢夺你。","notes":[]},{"n":9,"t":"为本家积蓄不义之财、在高处搭窝、指望免灾的有祸了！","notes":[]},{"n":10,"t":"你图谋剪除多国的民，犯了罪，使你的家蒙羞，自害己命。","notes":[]},{"n":11,"t":"墙里的石头必呼叫；房内的栋梁必应声。","notes":[]},{"n":12,"t":"以人血建城、以罪孽立邑的有祸了！","notes":[]},{"n":13,"t":"众民所劳碌得来的被火焚烧，列国由劳乏而得的归于虚空，不都是出于万军之耶和华吗？","notes":[]},{"n":14,"t":"认识耶和华荣耀的知识要充满遍地，好像水充满洋海一般。","notes":[]},{"n":15,"t":"给人酒喝、又加上毒物、使他喝醉、好看见他下体的有祸了！","notes":[]},{"n":16,"t":"你满受羞辱，不得荣耀；你也喝吧，显出是未受割礼的！耶和华右手的杯必传到你那里；你的荣耀就变为大大地羞辱。","notes":[]},{"n":17,"t":"你向黎巴嫩行强暴与残害惊吓野兽的事必遮盖你；因你杀人流血，向国内的城并城中一切居民施行强暴。","notes":[]},{"n":18,"t":"雕刻的偶像，人将它刻出来，有什么益处呢？铸造的偶像就是虚谎的师傅。制造者倚靠这哑巴偶像有什么益处呢？","notes":[]},{"n":19,"t":"对木偶说：醒起！对哑巴石像说：起来！那人有祸了！这个还能教训人吗？看哪，是包裹金银的，其中毫无气息。","notes":[]},{"n":20,"t":"惟耶和华在他的圣殿中；全地的人都当在他面前肃敬静默。","notes":[]}]},"3":{"heading":"哈巴谷的祈祷","verses":[{"n":1,"t":"先知哈巴谷的祷告，调用流离歌。","notes":[]},{"n":2,"t":"耶和华啊，我听见你的名声就惧怕。耶和华啊，求你在这些年间复兴你的作为，在这些年间显明出来；在发怒的时候以怜悯为念。","notes":["或译：言语"]},{"n":3,"t":"神从提幔而来；圣者从巴兰山临到。 （细拉）他的荣光遮蔽诸天；颂赞充满大地。","notes":[]},{"n":4,"t":"他的辉煌如同日光；从他手里射出光线，在其中藏着他的能力。","notes":[]},{"n":5,"t":"在他前面有瘟疫流行；在他脚下有热症发出。","notes":[]},{"n":6,"t":"他站立，量了大地，观看，赶散万民。永久的山崩裂；长存的岭塌陷；他的作为与古时一样。","notes":["或译：使地震动"]},{"n":7,"t":"我见古珊的帐棚遭难，米甸的幔子战兢。","notes":[]},{"n":8,"t":"耶和华啊，你乘在马上，坐在得胜的车上，岂是不喜悦江河、向江河发怒气、向洋海发愤恨吗？","notes":[]},{"n":9,"t":"你的弓全然显露，向众支派所起的誓都是可信的。 （细拉）你以江河分开大地。","notes":[]},{"n":10,"t":"山岭见你，无不战惧；大水泛滥过去，深渊发声，汹涌翻腾。","notes":["原文是向上举手"]},{"n":11,"t":"因你的箭射出发光，你的枪闪出光耀，日月都在本宫停住。","notes":[]},{"n":12,"t":"你发忿恨通行大地，发怒气责打列国，如同打粮。","notes":[]},{"n":13,"t":"你出来要拯救你的百姓，拯救你的受膏者，打破恶人家长的头，露出他的脚，直到颈项。 （细拉）","notes":["原文是根基"]},{"n":14,"t":"你用敌人的戈矛刺透他战士的头；他们来如旋风，要将我们分散。他们所喜爱的是暗中吞吃贫民。","notes":[]},{"n":15,"t":"你乘马践踏红海，就是践踏汹涌的大水。","notes":[]},{"n":16,"t":"我听见耶和华的声音，身体战兢，嘴唇发颤，骨中朽烂；我在所立之处战兢。我只可安静等候灾难之日临到，犯境之民上来。","notes":[]},{"n":17,"t":"虽然无花果树不发旺，葡萄树不结果，橄榄树也不效力，田地不出粮食，圈中绝了羊，棚内也没有牛；","notes":[]},{"n":18,"t":"然而，我要因耶和华欢欣，因救我的神喜乐。","notes":[]},{"n":19,"t":"主耶和华是我的力量；他使我的脚快如母鹿的蹄，又使我稳行在高处。这歌交与伶长，用丝弦的乐器。","notes":[]}]}},"ZEP":{"1":{"heading":"耶和华审判的日子","verses":[{"n":1,"t":"当犹大王亚们的儿子约西亚在位的时候，耶和华的话临到希西家的玄孙，亚玛利雅的曾孙，基大利的孙子，古示的儿子西番雅。","notes":[]},{"n":2,"t":"耶和华说：我必从地上除灭万类。","notes":[]},{"n":3,"t":"我必除灭人和牲畜，与空中的鸟、海里的鱼，以及绊脚石和恶人；我必将人从地上剪除。这是耶和华说的。","notes":[]},{"n":4,"t":"我必伸手攻击犹大和耶路撒冷的一切居民，也必从这地方剪除所剩下的巴力，并基玛林的名和祭司，","notes":[]},{"n":5,"t":"与那些在房顶上敬拜天上万象的，并那些敬拜耶和华指着他起誓，又指着玛勒堪起誓的，","notes":[]},{"n":6,"t":"与那些转去不跟从耶和华的，和不寻求耶和华也不访问他的。","notes":[]},{"n":7,"t":"你要在主耶和华面前静默无声，因为耶和华的日子快到。耶和华已经预备祭物，将他的客分别为圣。","notes":[]},{"n":8,"t":"到了我—耶和华献祭的日子，必惩罚首领和王子，并一切穿外邦衣服的。","notes":[]},{"n":9,"t":"到那日，我必惩罚一切跳过门槛、将强暴和诡诈得来之物充满主人房屋的。","notes":[]},{"n":10,"t":"耶和华说：当那日，从鱼门必发出悲哀的声音，从二城发出哀号的声音，从山间发出大破裂的响声。","notes":[]},{"n":11,"t":"玛革提施的居民哪，你们要哀号，因为迦南的商民都灭亡了！凡搬运银子的都被剪除。","notes":[]},{"n":12,"t":"那时，我必用灯巡查耶路撒冷；我必惩罚那些如酒在渣滓上澄清的；他们心里说：耶和华必不降福，也不降祸。","notes":[]},{"n":13,"t":"他们的财宝必成为掠物；他们的房屋必变为荒场。他们必建造房屋，却不得住在其内；栽种葡萄园，却不得喝所出的酒。","notes":[]},{"n":14,"t":"耶和华的大日临近，临近而且甚快，乃是耶和华日子的风声；勇士必痛痛地哭号。","notes":[]},{"n":15,"t":"那日是忿怒的日子，是急难困苦的日子，是荒废凄凉的日子，是黑暗幽冥、密云乌黑的日子，","notes":[]},{"n":16,"t":"是吹角呐喊的日子，要攻击坚固城和高大的城楼。","notes":[]},{"n":17,"t":"我必使灾祸临到人身上，使他们行走如同瞎眼的，因为得罪了我。他们的血必倒出如灰尘；他们的肉必抛弃如粪土。","notes":[]},{"n":18,"t":"当耶和华发怒的日子，他们的金银不能救他们；他的忿怒如火必烧灭全地，毁灭这地的一切居民，而且大大毁灭。","notes":[]}]},"2":{"heading":"呼吁百姓悔改","verses":[{"n":1,"t":"不知羞耻的国民哪，你们应当聚集！趁命令没有发出，日子过去如风前的糠，耶和华的烈怒未临到你们，他发怒的日子未到以先，你们应当聚集前来。","notes":[],"end":2},{"n":3,"t":"世上遵守耶和华典章的谦卑人哪，你们都当寻求耶和华！当寻求公义谦卑，或者在耶和华发怒的日子可以隐藏起来。","notes":[]},{"n":4,"t":"迦萨必致见弃；亚实基伦必然荒凉。人在正午必赶出亚实突的民；以革伦也被拔出根来。","notes":[],"heads":["以色列邻国的结局"]},{"n":5,"t":"住沿海之地的基利提族有祸了！迦南、非利士人之地啊，耶和华的话与你反对，说：我必毁灭你，以致无人居住。","notes":[]},{"n":6,"t":"沿海之地要变为草场，其上有牧人的住处和羊群的圈。","notes":[]},{"n":7,"t":"这地必为犹大家剩下的人所得；他们必在那里牧放群羊，晚上必躺卧在亚实基伦的房屋中；因为耶和华—他们的神必眷顾他们，使他们被掳的人归回。","notes":[]},{"n":8,"t":"我听见摩押人的毁谤和亚扪人的辱骂，就是毁谤我的百姓，自夸自大，侵犯他们的境界。","notes":[]},{"n":9,"t":"万军之耶和华—以色列的神说：我指着我的永生起誓：摩押必像所多玛，亚扪人必像蛾摩拉，都变为刺草、盐坑、永远荒废之地。我百姓所剩下的必掳掠他们；我国中所余剩的必得着他们的地。","notes":[]},{"n":10,"t":"这事临到他们是因他们骄傲，自夸自大，毁谤万军之耶和华的百姓。","notes":[]},{"n":11,"t":"耶和华必向他们显可畏之威，因他必叫世上的诸神瘦弱。列国海岛的居民各在自己的地方敬拜他。","notes":[]},{"n":12,"t":"古实人哪，你们必被我的刀所杀。","notes":[]},{"n":13,"t":"耶和华必伸手攻击北方，毁灭亚述，使尼尼微荒凉，又干旱如旷野。","notes":[]},{"n":14,"t":"群畜，就是各国的走兽必卧在其中；鹈鹕和箭猪要宿在柱顶上。在窗户内有鸣叫的声音；门槛都必毁坏，香柏木已经露出。","notes":["国：或译类"]},{"n":15,"t":"这是素来欢乐安然居住的城，心里说：惟有我，除我以外再没有别的；现在何竟荒凉成为野兽躺卧之处！凡经过的人都必摇手嗤笑她。","notes":[]}]},"3":{"heading":"耶路撒冷的罪恶和救赎","verses":[{"n":1,"t":"这悖逆、污秽、欺压的城有祸了！","notes":[]},{"n":2,"t":"她不听从命令，不领受训诲，不倚靠耶和华，不亲近她的神。","notes":[]},{"n":3,"t":"她中间的首领是咆哮的狮子；她的审判官是晚上的豺狼，一点食物也不留到早晨。","notes":[]},{"n":4,"t":"她的先知是虚浮诡诈的人；她的祭司亵渎圣所，强解律法。","notes":[]},{"n":5,"t":"耶和华在她中间是公义的，断不做非义的事，每早晨显明他的公义，无日不然；只是不义的人不知羞耻。","notes":[]},{"n":6,"t":"我—耶和华已经除灭列国的民；他们的城楼毁坏。我使他们的街道荒凉，以致无人经过；他们的城邑毁灭，以致无人，也无居民。","notes":[]},{"n":7,"t":"我说：你只要敬畏我，领受训诲；如此，你的住处不致照我所拟定的除灭。只是你们从早起来就在一切事上败坏自己。","notes":[]},{"n":8,"t":"耶和华说：你们要等候我，直到我兴起掳掠的日子；因为我已定意招聚列国，聚集列邦，将我的恼怒—就是我的烈怒都倾在她们身上。我的忿怒如火，必烧灭全地。","notes":[]},{"n":9,"t":"那时，我必使万民用清洁的言语好求告我—耶和华的名，同心合意地事奉我。","notes":[]},{"n":10,"t":"祈祷我的，就是我所分散的民，必从古实河外来，给我献供物。","notes":["原文是女子；下同"]},{"n":11,"t":"当那日，你必不因你一切得罪我的事自觉羞愧；因为那时我必从你中间除掉矜夸高傲之辈，你也不再于我的圣山狂傲。","notes":[]},{"n":12,"t":"我却要在你中间留下困苦贫寒的民；他们必投靠我—耶和华的名。","notes":[]},{"n":13,"t":"以色列所剩下的人必不作罪孽，不说谎言，口中也没有诡诈的舌头；而且吃喝躺卧，无人惊吓。","notes":[]},{"n":14,"t":"锡安的民哪，应当歌唱！以色列啊，应当欢呼！耶路撒冷的民哪，应当满心欢喜快乐！","notes":[],"heads":["欢乐之歌"]},{"n":15,"t":"耶和华已经除去你的刑罚，赶出你的仇敌。以色列的王—耶和华在你中间；你必不再惧怕灾祸。","notes":[]},{"n":16,"t":"当那日，必有话向耶路撒冷说：不要惧怕！锡安哪；不要手软！","notes":[]},{"n":17,"t":"耶和华—你的神是施行拯救、大有能力的主。他在你中间必因你欢欣喜乐，默然爱你，且因你喜乐而欢呼。","notes":[]},{"n":18,"t":"那些属你、为无大会愁烦、因你担当羞辱的，我必聚集他们。","notes":[]},{"n":19,"t":"那时，我必罚办一切苦待你的人，又拯救你瘸腿的，聚集你被赶出的。那些在全地受羞辱的，我必使他们得称赞，有名声。","notes":[]},{"n":20,"t":"那时，我必领你们进来，聚集你们；我使你们被掳之人归回的时候，就必使你们在地上的万民中有名声，得称赞。这是耶和华说的。","notes":[]}]}},"HAG":{"1":{"heading":"耶和华命令重建圣殿","verses":[{"n":1,"t":"大流士王第二年六月初一日，耶和华的话借先知哈该向犹大省长撒拉铁的儿子所罗巴伯和约撒答的儿子大祭司约书亚说：","notes":[]},{"n":2,"t":"万军之耶和华如此说：「这百姓说，建造耶和华殿的时候尚未来到。」","notes":[]},{"n":3,"t":"那时耶和华的话临到先知哈该说：","notes":[]},{"n":4,"t":"「这殿仍然荒凉，你们自己还住天花板的房屋吗？","notes":[]},{"n":5,"t":"现在万军之耶和华如此说：你们要省察自己的行为。","notes":[]},{"n":6,"t":"你们撒的种多，收的却少；你们吃，却不得饱；喝，却不得足；穿衣服，却不得暖；得工钱的，将工钱装在破漏的囊中。」","notes":[]},{"n":7,"t":"万军之耶和华如此说：「你们要省察自己的行为。","notes":[]},{"n":8,"t":"你们要上山取木料，建造这殿，我就因此喜乐，且得荣耀。这是耶和华说的。","notes":[]},{"n":9,"t":"你们盼望多得，所得的却少；你们收到家中，我就吹去。这是为什么呢？因为我的殿荒凉，你们各人却顾自己的房屋。这是万军之耶和华说的。","notes":["原文是奔"]},{"n":10,"t":"所以为你们的缘故，天就不降甘露，地也不出土产。","notes":[]},{"n":11,"t":"我命干旱临到地土、山冈、五谷、新酒，和油，并地上的出产、人民、牲畜，以及人手一切劳碌得来的。」","notes":[]},{"n":12,"t":"那时，撒拉铁的儿子所罗巴伯和约撒答的儿子大祭司约书亚，并剩下的百姓，都听从耶和华—他们神的话和先知哈该奉耶和华—他们神差来所说的话；百姓也在耶和华面前存敬畏的心。","notes":[],"heads":["百姓顺从耶和华的命令"]},{"n":13,"t":"耶和华的使者哈该奉耶和华差遣对百姓说：「耶和华说：我与你们同在。」","notes":[]},{"n":14,"t":"耶和华激动犹大省长撒拉铁的儿子所罗巴伯和约撒答的儿子大祭司约书亚，并剩下之百姓的心，他们就来为万军之耶和华—他们神的殿做工。","notes":[]},{"n":15,"t":"这是在大流士王第二年六月二十四日。","notes":[]}]},"2":{"heading":"新殿的荣耀","verses":[{"n":1,"t":"七月二十一日，耶和华的话临到先知哈该说：","notes":[]},{"n":2,"t":"「你要晓谕犹大省长撒拉铁的儿子所罗巴伯和约撒答的儿子大祭司约书亚，并剩下的百姓，说：","notes":[]},{"n":3,"t":"你们中间存留的，有谁见过这殿从前的荣耀呢？现在你们看着如何？岂不在眼中看如无有吗？」","notes":[]},{"n":4,"t":"耶和华说：「所罗巴伯啊，虽然如此，你当刚强！约撒答的儿子大祭司约书亚啊，你也当刚强！这地的百姓，你们都当刚强做工，因为我与你们同在。这是万军之耶和华说的。","notes":[]},{"n":5,"t":"这是照着你们出埃及我与你们立约的话。那时，我的灵住在你们中间，你们不要惧怕。」","notes":[]},{"n":6,"t":"万军之耶和华如此说：「过不多时，我必再一次震动天地、沧海，与旱地。","notes":[]},{"n":7,"t":"我必震动万国；万国的珍宝必都运来，我就使这殿满了荣耀。这是万军之耶和华说的。」","notes":["或译：万国所羡慕的必来到"]},{"n":8,"t":"万军之耶和华说：「银子是我的，金子也是我的。","notes":[]},{"n":9,"t":"这殿后来的荣耀必大过先前的荣耀；在这地方我必赐平安。这是万军之耶和华说的。」","notes":[]},{"n":10,"t":"大流士王第二年九月二十四日，耶和华的话临到先知哈该说：","notes":[],"heads":["先知向祭司请教"]},{"n":11,"t":"万军之耶和华如此说：「你要向祭司问律法，","notes":[]},{"n":12,"t":"说：若有人用衣襟兜圣肉，这衣襟挨着饼，或汤，或酒，或油，或别的食物，便算为圣吗？」祭司说：「不算为圣。」","notes":[]},{"n":13,"t":"哈该又说：「若有人因摸死尸染了污秽，然后挨着这些物的哪一样，这物算污秽吗？」祭司说：「必算污秽。」","notes":[]},{"n":14,"t":"于是哈该说：「耶和华说：这民这国，在我面前也是如此；他们手下的各样工作都是如此；他们在坛上所献的也是如此。」","notes":[]},{"n":15,"t":"现在你们要追想，此日以前，耶和华的殿没有一块石头垒在石头上的光景。","notes":[],"heads":["耶和华应许赐福"]},{"n":16,"t":"在那一切日子，有人来到谷堆，想得二十斗，只得了十斗。有人来到酒池，想得五十桶，只得了二十桶。","notes":[]},{"n":17,"t":"在你们手下的各样工作上，我以旱风、霉烂、冰雹攻击你们，你们仍不归向我。这是耶和华说的。","notes":[]},{"n":18,"t":"你们要追想此日以前，就是从这九月二十四日起，追想到立耶和华殿根基的日子。","notes":[]},{"n":19,"t":"仓里有谷种吗？葡萄树、无花果树、石榴树、橄榄树都没有结果子。从今日起，我必赐福与你们。","notes":[]},{"n":20,"t":"这月二十四日，耶和华的话二次临到哈该说：","notes":[],"heads":["耶和华给所罗巴伯的应许"]},{"n":21,"t":"「你要告诉犹大省长所罗巴伯说：我必震动天地。","notes":[]},{"n":22,"t":"我必倾覆列国的宝座，除灭列邦的势力，并倾覆战车和坐在其上的。马必跌倒，骑马的败落，各人被弟兄的刀所杀。","notes":[]},{"n":23,"t":"万军之耶和华说：我仆人撒拉铁的儿子所罗巴伯啊，到那日，我必以你为印，因我拣选了你。这是万军之耶和华说的。」","notes":[]}]}},"ZEC":{"1":{"heading":"耶和华呼唤子民归向他","verses":[{"n":1,"t":"大流士王第二年八月，耶和华的话临到易多的孙子、比利家的儿子先知撒迦利亚，说：","notes":[]},{"n":2,"t":"「耶和华曾向你们列祖大大发怒。","notes":[]},{"n":3,"t":"所以你要对以色列人说，万军之耶和华如此说：你们要转向我，我就转向你们。这是万军之耶和华说的。","notes":[]},{"n":4,"t":"不要效法你们列祖。从前的先知呼叫他们说，万军之耶和华如此说：『你们要回头离开你们的恶道恶行。』他们却不听，也不顺从我。这是耶和华说的。","notes":[]},{"n":5,"t":"你们的列祖在哪里呢？那些先知能永远存活吗？","notes":[]},{"n":6,"t":"只是我的言语和律例，就是所吩咐我仆人众先知的，岂不临到你们列祖吗？他们就回头，说：『万军之耶和华定意按我们的行动作为向我们怎样行，他已照样行了。』」","notes":[]},{"n":7,"t":"大流士第二年十一月，就是细罢特月二十四日，耶和华的话临到易多的孙子、比利家的儿子先知撒迦利亚，说：","notes":[],"heads":["马的异象"]},{"n":8,"t":"「我夜间观看，见一人骑着红马，站在洼地番石榴树中间。在他身后又有红马、黄马，和白马。」","notes":[]},{"n":9,"t":"我对与我说话的天使说：「主啊，这是什么意思？」他说：「我要指示你这是什么意思。」","notes":[]},{"n":10,"t":"那站在番石榴树中间的人说：「这是奉耶和华差遣在遍地走来走去的。」","notes":[]},{"n":11,"t":"那些骑马的对站在番石榴树中间耶和华的使者说：「我们已在遍地走来走去，见全地都安息平静。」","notes":[]},{"n":12,"t":"于是，耶和华的使者说：「万军之耶和华啊，你恼恨耶路撒冷和犹大的城邑已经七十年，你不施怜悯要到几时呢？」","notes":[]},{"n":13,"t":"耶和华就用美善的安慰话回答那与我说话的天使。","notes":[]},{"n":14,"t":"与我说话的天使对我说：「你要宣告说，万军之耶和华如此说：我为耶路撒冷为锡安，心里极其火热。","notes":[]},{"n":15,"t":"我甚恼怒那安逸的列国，因我从前稍微恼怒我民，他们就加害过分。","notes":[]},{"n":16,"t":"所以耶和华如此说：现今我回到耶路撒冷，仍施怜悯，我的殿必重建在其中，准绳必拉在耶路撒冷之上。这是万军之耶和华说的。","notes":[]},{"n":17,"t":"你要再宣告说，万军之耶和华如此说：我的城邑必再丰盛发达。耶和华必再安慰锡安，拣选耶路撒冷。」","notes":[]},{"n":18,"t":"我举目观看，见有四角。","notes":[],"heads":["角的异象"]},{"n":19,"t":"我就问与我说话的天使说：「这是什么意思？」他回答说：「这是打散犹大、以色列，和耶路撒冷的角。」","notes":[]},{"n":20,"t":"耶和华又指四个匠人给我看。","notes":[]},{"n":21,"t":"我说：「他们来做什么呢？」他说：「这是打散犹大的角，使人不敢抬头；但这些匠人来威吓列国，打掉他们的角，就是举起打散犹大地的角。」","notes":[]}]},"2":{"heading":"准绳的异象","verses":[{"n":1,"t":"我又举目观看，见一人手拿准绳。","notes":[]},{"n":2,"t":"我说：「你往哪里去？」他对我说：「要去量耶路撒冷，看有多宽多长。」","notes":[]},{"n":3,"t":"与我说话的天使去的时候，又有一位天使迎着他来，","notes":[]},{"n":4,"t":"对他说：「你跑去告诉那少年人说，耶路撒冷必有人居住，好像无城墙的乡村，因为人民和牲畜甚多。","notes":[]},{"n":5,"t":"耶和华说：我要作耶路撒冷四围的火城，并要作其中的荣耀。」","notes":[]},{"n":6,"t":"耶和华说：「我从前分散你们在天的四方，现在你们要从北方之地逃回。这是耶和华说的。","notes":["原文是犹如天的四风"],"heads":["呼唤被掳者归回"]},{"n":7,"t":"与巴比伦人同住的锡安民哪，应当逃脱。","notes":[]},{"n":8,"t":"万军之耶和华说，在显出荣耀之后，差遣我去惩罚那掳掠你们的列国，摸你们的就是摸他眼中的瞳人。","notes":[]},{"n":9,"t":"看哪，我要向他们抡手，他们就必作服事他们之人的掳物，你们便知道万军之耶和华差遣我了。","notes":["或译：他"]},{"n":10,"t":"锡安城啊，应当欢乐歌唱，因为我来要住在你中间。这是耶和华说的。」","notes":[]},{"n":11,"t":"那时，必有许多国归附耶和华，作他的子民。他要住在你中间，你就知道万军之耶和华差遣我到你那里去了。","notes":["原文是我","原文是我"]},{"n":12,"t":"耶和华必收回犹大作他圣地的分，也必再拣选耶路撒冷。","notes":[]},{"n":13,"t":"凡有血气的都当在耶和华面前静默无声；因为他兴起，从圣所出来了。","notes":[]}]},"3":{"heading":"大祭司的异象","verses":[{"n":1,"t":"天使又指给我看：大祭司约书亚站在耶和华的使者面前；撒但也站在约书亚的右边，与他作对。","notes":["原文是他"]},{"n":2,"t":"耶和华向撒但说：「撒但哪，耶和华责备你！就是拣选耶路撒冷的耶和华责备你！这不是从火中抽出来的一根柴吗？」","notes":[]},{"n":3,"t":"约书亚穿着污秽的衣服站在使者面前。","notes":[]},{"n":4,"t":"使者吩咐站在面前的说：「你们要脱去他污秽的衣服」；又对约书亚说：「我使你脱离罪孽，要给你穿上华美的衣服。」","notes":[]},{"n":5,"t":"我说：「要将洁净的冠冕戴在他头上。」他们就把洁净的冠冕戴在他头上，给他穿上华美的衣服，耶和华的使者在旁边站立。","notes":[]},{"n":6,"t":"耶和华的使者告诫约书亚说：","notes":[]},{"n":7,"t":"「万军之耶和华如此说：你若遵行我的道，谨守我的命令，你就可以管理我的家，看守我的院宇；我也要使你在这些站立的人中间来往。","notes":[]},{"n":8,"t":"大祭司约书亚啊，你和坐在你面前的同伴都当听。（他们是作预兆的。）我必使我仆人大卫的苗裔发出。","notes":[]},{"n":9,"t":"看哪，我在约书亚面前所立的石头，在一块石头上有七眼。万军之耶和华说：我要亲自雕刻这石头，并要在一日之间除掉这地的罪孽。","notes":[]},{"n":10,"t":"当那日，你们各人要请邻舍坐在葡萄树和无花果树下。这是万军之耶和华说的。」","notes":[]}]},"4":{"heading":"金灯台的异象","verses":[{"n":1,"t":"那与我说话的天使又来叫醒我，好像人睡觉被唤醒一样。","notes":[]},{"n":2,"t":"他问我说：「你看见了什么？」我说：「我看见了一个纯金的灯台，顶上有灯盏，灯台上有七盏灯，每盏有七个管子。","notes":[]},{"n":3,"t":"旁边有两棵橄榄树，一棵在灯盏的右边，一棵在灯盏的左边。」","notes":[]},{"n":4,"t":"我问与我说话的天使说：「主啊，这是什么意思？」","notes":[]},{"n":5,"t":"与我说话的天使回答我说：「你不知道这是什么意思吗？」我说：「主啊，我不知道。」","notes":[]},{"n":6,"t":"他对我说：「这是耶和华指示所罗巴伯的。万军之耶和华说：不是倚靠势力，不是倚靠才能，乃是倚靠我的灵方能成事。","notes":[],"heads":["神给所罗巴伯的应许"]},{"n":7,"t":"大山哪，你算什么呢？在所罗巴伯面前，你必成为平地。他必搬出一块石头，安在殿顶上。人且大声欢呼说：『愿恩惠恩惠归与这殿！』」","notes":["殿：或译石"]},{"n":8,"t":"耶和华的话又临到我说：","notes":[]},{"n":9,"t":"「所罗巴伯的手立了这殿的根基，他的手也必完成这工，你就知道万军之耶和华差遣我到你们这里来了。","notes":[]},{"n":10,"t":"谁藐视这日的事为小呢？这七眼乃是耶和华的眼睛，遍察全地，见所罗巴伯手拿线铊就欢喜。」","notes":[]},{"n":11,"t":"我又问天使说：「这灯台左右的两棵橄榄树是什么意思？」","notes":[]},{"n":12,"t":"我二次问他说：「这两根橄榄枝在两个流出金色油的金嘴旁边是什么意思？」","notes":[]},{"n":13,"t":"他对我说：「你不知道这是什么意思吗？」我说：「主啊，我不知道。」","notes":[]},{"n":14,"t":"他说：「这是两个受膏者站在普天下主的旁边。」","notes":[]}]},"5":{"heading":"飞卷的异象","verses":[{"n":1,"t":"我又举目观看，见有一飞行的书卷。","notes":[]},{"n":2,"t":"他问我说：「你看见什么？」我回答说：「我看见一飞行的书卷，长二十肘，宽十肘。」","notes":[]},{"n":3,"t":"他对我说：「这是发出行在遍地上的咒诅。凡偷窃的必按卷上这面的话除灭；凡起假誓的必按卷上那面的话除灭。","notes":[]},{"n":4,"t":"万军之耶和华说：我必使这书卷出去，进入偷窃人的家和指我名起假誓人的家，必常在他家里，连房屋带木石都毁灭了。」","notes":[]},{"n":5,"t":"与我说话的天使出来，对我说：「你要举目观看，见所出来的是什么？」","notes":[],"heads":["量器中妇人的异象"]},{"n":6,"t":"我说：「这是什么呢？」他说：「这出来的是量器。」他又说：「这是恶人在遍地的形状。」","notes":[]},{"n":7,"t":"（我见有一片圆铅被举起来。）这坐在量器中的是个妇人。","notes":[]},{"n":8,"t":"天使说：「这是罪恶。」他就把妇人扔在量器中，将那片圆铅扔在量器的口上。","notes":[]},{"n":9,"t":"我又举目观看，见有两个妇人出来，在她们翅膀中有风，飞得甚快，翅膀如同鹳鸟的翅膀。她们将量器抬起来，悬在天地中间。","notes":[]},{"n":10,"t":"我问与我说话的天使说：「她们要将量器抬到哪里去呢？」","notes":[]},{"n":11,"t":"他对我说：「要往示拿地去，为它盖造房屋；等房屋齐备，就把它安置在自己的地方。」","notes":[]}]},"6":{"heading":"马车的异象","verses":[{"n":1,"t":"我又举目观看，见有四辆车从两山中间出来；那山是铜山。","notes":[]},{"n":2,"t":"第一辆车套着红马，第二辆车套着黑马。","notes":[]},{"n":3,"t":"第三辆车套着白马，第四辆车套着有斑点的壮马。","notes":[]},{"n":4,"t":"我就问与我说话的天使说：「主啊，这是什么意思？」","notes":[]},{"n":5,"t":"天使回答我说：「这是天的四风，是从普天下的主面前出来的。」","notes":[]},{"n":6,"t":"套着黑马的车往北方去，白马跟随在后；有斑点的马往南方去。","notes":[]},{"n":7,"t":"壮马出来，要在遍地走来走去。天使说：「你们只管在遍地走来走去。」它们就照样行了。","notes":[]},{"n":8,"t":"他又呼叫我说：「看哪，往北方去的已在北方安慰我的心。」","notes":[]},{"n":9,"t":"耶和华的话临到我说：","notes":[],"heads":["为约书亚加冕"]},{"n":10,"t":"「你要从被掳之人中取黑玳、多比雅、耶大雅的金银。这三人是从巴比伦来到西番雅的儿子约西亚的家里。当日你要进他的家，","notes":[]},{"n":11,"t":"取这金银做冠冕，戴在约撒答的儿子大祭司约书亚的头上，","notes":[]},{"n":12,"t":"对他说，万军之耶和华如此说：看哪，那名称为大卫苗裔的，他要在本处长起来，并要建造耶和华的殿。","notes":[]},{"n":13,"t":"他要建造耶和华的殿，并担负尊荣，坐在位上掌王权；又必在位上作祭司，使两职之间筹定和平。","notes":[]},{"n":14,"t":"这冠冕要归希连、多比雅、耶大雅，和西番雅的儿子贤，放在耶和华的殿里为记念。」","notes":["就是黑玳","就是约西亚"]},{"n":15,"t":"远方的人也要来建造耶和华的殿，你们就知道万军之耶和华差遣我到你们这里来。你们若留意听从耶和华—你们神的话，这事必然成就。","notes":[]}]},"7":{"heading":"谴责不诚恳的禁食","verses":[{"n":1,"t":"大流士王第四年九月，就是基斯流月初四日，耶和华的话临到撒迦利亚。","notes":[]},{"n":2,"t":"那时伯特利人已经打发沙利色和利坚米勒，并跟从他们的人，去恳求耶和华的恩，","notes":[]},{"n":3,"t":"并问万军之耶和华殿中的祭司和先知说：「我历年以来，在五月间哭泣斋戒，现在还当这样行吗？」","notes":[]},{"n":4,"t":"万军之耶和华的话就临到我说：","notes":[]},{"n":5,"t":"「你要宣告国内的众民和祭司，说：『你们这七十年，在五月、七月禁食悲哀，岂是丝毫向我禁食吗？","notes":[]},{"n":6,"t":"你们吃喝，不是为自己吃，为自己喝吗？","notes":[]},{"n":7,"t":"当耶路撒冷和四围的城邑有居民，正兴盛，南地高原有人居住的时候，耶和华借从前的先知所宣告的话，你们不当听吗？』」","notes":[]},{"n":8,"t":"耶和华的话又临到撒迦利亚说：","notes":[],"heads":["被掳的原因是悖逆"]},{"n":9,"t":"「万军之耶和华曾对你们的列祖如此说：『要按至理判断，各人以慈爱怜悯弟兄。","notes":[]},{"n":10,"t":"不可欺压寡妇、孤儿、寄居的，和贫穷人。谁都不可心里谋害弟兄。』」","notes":[]},{"n":11,"t":"他们却不肯听从，扭转肩头，塞耳不听，","notes":[]},{"n":12,"t":"使心硬如金钢石，不听律法和万军之耶和华用灵借从前的先知所说的话。故此，万军之耶和华大发烈怒。","notes":[]},{"n":13,"t":"万军之耶和华说：「我曾呼唤他们，他们不听；将来他们呼求我，我也不听！","notes":[]},{"n":14,"t":"我必以旋风吹散他们到素不认识的万国中。这样，他们的地就荒凉，甚至无人来往经过，因为他们使美好之地荒凉了。」","notes":[]}]},"8":{"heading":"耶和华应许复兴耶路撒冷","verses":[{"n":1,"t":"万军之耶和华的话临到我说：","notes":[]},{"n":2,"t":"「万军之耶和华如此说：我为锡安心里极其火热，我为她火热，向她的仇敌发烈怒。","notes":[]},{"n":3,"t":"耶和华如此说：我现在回到锡安，要住在耶路撒冷中。耶路撒冷必称为诚实的城，万军之耶和华的山必称为圣山。","notes":[]},{"n":4,"t":"万军之耶和华如此说：将来必有年老的男女坐在耶路撒冷街上，因为年纪老迈就手拿拐杖。","notes":[]},{"n":5,"t":"城中街上必满有男孩女孩玩耍。","notes":[]},{"n":6,"t":"万军之耶和华如此说：到那日，这事在余剩的民眼中看为希奇，在我眼中也看为希奇吗？这是万军之耶和华说的。","notes":[]},{"n":7,"t":"万军之耶和华如此说：我要从东方从西方救回我的民。","notes":[]},{"n":8,"t":"我要领他们来，使他们住在耶路撒冷中。他们要作我的子民，我要作他们的神，都凭诚实和公义。」","notes":[]},{"n":9,"t":"万军之耶和华如此说：「当建造万军之耶和华的殿，立根基之日的先知所说的话，现在你们听见，应当手里强壮。","notes":[]},{"n":10,"t":"那日以先，人得不着雇价，牲畜也是如此；且因敌人的缘故，出入之人不得平安，乃因我使众人互相攻击。","notes":[]},{"n":11,"t":"但如今，我待这余剩的民必不像从前。这是万军之耶和华说的。","notes":[]},{"n":12,"t":"因为他们必平安撒种，葡萄树必结果子，地土必有出产，天也必降甘露。我要使这余剩的民享受这一切的福。","notes":[]},{"n":13,"t":"犹大家和以色列家啊，你们从前在列国中怎样成为可咒诅的；照样，我要拯救你们，使人称你们为有福的。你们不要惧怕，手要强壮。」","notes":["或译：使你们叫人得福"]},{"n":14,"t":"万军之耶和华如此说：「你们列祖惹我发怒的时候，我怎样定意降祸，并不后悔。","notes":[]},{"n":15,"t":"现在我照样定意施恩与耶路撒冷和犹大家，你们不要惧怕。","notes":[]},{"n":16,"t":"你们所当行的是这样：各人与邻舍说话诚实，在城门口按至理判断，使人和睦。","notes":[]},{"n":17,"t":"谁都不可心里谋害邻舍，也不可喜爱起假誓，因为这些事都为我所恨恶。这是耶和华说的。」","notes":[]},{"n":18,"t":"万军之耶和华的话临到我说：","notes":[]},{"n":19,"t":"「万军之耶和华如此说：四月、五月禁食的日子，七月、十月禁食的日子，必变为犹大家欢喜快乐的日子和欢乐的节期；所以你们要喜爱诚实与和平。」","notes":[]},{"n":20,"t":"万军之耶和华如此说：「将来必有列国的人和多城的居民来到。","notes":[]},{"n":21,"t":"这城的居民必到那城，说：『我们要快去恳求耶和华的恩，寻求万军之耶和华；我也要去。』","notes":[]},{"n":22,"t":"必有列邦的人和强国的民来到耶路撒冷寻求万军之耶和华，恳求耶和华的恩。","notes":[]},{"n":23,"t":"万军之耶和华如此说：在那些日子，必有十个人从列国诸族中出来，拉住一个犹大人的衣襟，说：『我们要与你们同去，因为我们听见神与你们同在了。』」","notes":["原文是方言"]}]},"9":{"heading":"审判邻国","verses":[{"n":1,"t":"耶和华的默示应验在哈得拉地大马士革—世人和以色列各支派的眼目都仰望耶和华—","notes":[]},{"n":2,"t":"和靠近的哈马，并泰尔、西顿；因为这二城的人大有智慧。","notes":[]},{"n":3,"t":"泰尔为自己修筑保障，积蓄银子如尘沙，堆起精金如街上的泥土。","notes":[]},{"n":4,"t":"主必赶出她，打败她海上的权利；她必被火烧灭。","notes":[]},{"n":5,"t":"亚实基伦看见必惧怕；迦萨看见甚痛苦；以革伦因失了盼望蒙羞。迦萨必不再有君王；亚实基伦也不再有居民。","notes":[]},{"n":6,"t":"私生子必住在亚实突；我必除灭非利士人的骄傲。","notes":["或译：外族人"]},{"n":7,"t":"我必除去他口中带血之肉和牙齿内可憎之物。他必作为余剩的人归与我们的神，必在犹大像族长；以革伦人必如耶布斯人。","notes":[]},{"n":8,"t":"我必在我家的四围安营，使敌军不得任意往来，暴虐的人也不再经过，因为我亲眼看顾我的家。","notes":[]},{"n":9,"t":"锡安的民哪，应当大大喜乐；耶路撒冷的民哪，应当欢呼。看哪，你的王来到你这里！他是公义的，并且施行拯救，谦谦和和地骑着驴，就是骑着驴的驹子。","notes":[],"heads":["未来的君王"]},{"n":10,"t":"我必除灭以法莲的战车和耶路撒冷的战马；争战的弓也必除灭。他必向列国讲和平；他的权柄必从这海管到那海，从大河管到地极。","notes":[]},{"n":11,"t":"锡安哪，我因与你立约的血，将你中间被掳而囚的人从无水的坑中释放出来。","notes":[],"heads":["神子民的复兴"]},{"n":12,"t":"你们被囚而有指望的人都要转回保障。我今日说明，我必加倍赐福给你们。","notes":[]},{"n":13,"t":"我拿犹大作上弦的弓；我拿以法莲为张弓的箭。锡安哪，我要激发你的众子，攻击希腊的众子，使你如勇士的刀。","notes":["原文是雅完"]},{"n":14,"t":"耶和华必显现在他们以上；他的箭必射出像闪电。主耶和华必吹角，乘南方的旋风而行。","notes":[]},{"n":15,"t":"万军之耶和华必保护他们；他们必吞灭仇敌，践踏弹石。他们必喝血呐喊，犹如饮酒；他们必像盛满血的碗，又像坛的四角满了血。","notes":[]},{"n":16,"t":"当那日，耶和华—他们的神必看他的民如群羊，拯救他们；因为他们必像冠冕上的宝石，高举在他的地以上。","notes":["或译：在他的地上发光辉"]},{"n":17,"t":"他的恩慈何等大！他的荣美何其盛！五谷健壮少男；新酒培养处女。","notes":[]}]},"10":{"heading":"耶和华应许解救","verses":[{"n":1,"t":"当春雨的时候，你们要向发闪电的耶和华求雨。他必为众人降下甘霖，使田园生长菜蔬。","notes":[]},{"n":2,"t":"因为，家神所言的是虚空；卜士所见的是虚假；做梦者所说的是假梦。他们白白地安慰人，所以众人如羊流离，因无牧人就受苦。","notes":[]},{"n":3,"t":"我的怒气向牧人发作；我必惩罚公山羊；因我—万军之耶和华眷顾自己的羊群，就是犹大家，必使他们如骏马在阵上。","notes":[]},{"n":4,"t":"房角石、钉子、争战的弓，和一切掌权的都从他而出。","notes":[]},{"n":5,"t":"他们必如勇士在阵上将仇敌践踏在街上的泥土中。他们必争战，因为耶和华与他们同在；骑马的也必羞愧。","notes":[]},{"n":6,"t":"我要坚固犹大家，拯救约瑟家，要领他们归回。我要怜恤他们；他们必像未曾弃绝的一样，都因我是耶和华—他们的神，我必应允他们的祷告。","notes":[]},{"n":7,"t":"以法莲人必如勇士；他们心中畅快如同喝酒；他们的儿女必看见而快活；他们的心必因耶和华喜乐。","notes":[]},{"n":8,"t":"我要发嘶声，聚集他们，因我已经救赎他们。他们的人数必加增，如从前加增一样。","notes":[]},{"n":9,"t":"我虽然播散他们在列国中，他们必在远方记念我。他们与儿女都必存活，且得归回。","notes":["或译：必"]},{"n":10,"t":"我必再领他们出埃及地，招聚他们出亚述，领他们到基列和黎巴嫩；这地尚且不够他们居住。","notes":[]},{"n":11,"t":"耶和华必经过苦海，击打海浪，使尼罗河的深处都枯干。亚述的骄傲必致卑微；埃及的权柄必然灭没。","notes":[]},{"n":12,"t":"我必使他们倚靠我，得以坚固；一举一动必奉我的名。这是耶和华说的。","notes":[]}]},"11":{"heading":"暴君的没落","verses":[{"n":1,"t":"黎巴嫩哪，开开你的门，任火烧灭你的香柏树。","notes":[]},{"n":2,"t":"松树啊，应当哀号；因为香柏树倾倒，佳美的树毁坏。巴珊的橡树啊，应当哀号，因为茂盛的树林已经倒了。","notes":[]},{"n":3,"t":"听啊，有牧人哀号的声音，因他们荣华的草场毁坏了。有少壮狮子咆哮的声音，因约旦河旁的丛林荒废了。","notes":[]},{"n":4,"t":"耶和华—我的神如此说：「你—撒迦利亚要牧养这将宰的群羊。","notes":[],"heads":["两个牧人"]},{"n":5,"t":"买他们的宰了他们，以自己为无罪；卖他们的说：『耶和华是应当称颂的，因我成为富足。』牧养他们的并不怜恤他们。","notes":[]},{"n":6,"t":"耶和华说：『我不再怜恤这地的居民，必将这民交给各人的邻舍和他们王的手中。他们必毁灭这地，我也不救这民脱离他们的手。』」","notes":[]},{"n":7,"t":"于是，我牧养这将宰的群羊，就是群中最困苦的羊。我拿着两根杖，一根我称为「荣美」，一根我称为「联索」。这样，我牧养了群羊。","notes":[]},{"n":8,"t":"一月之内，我除灭三个牧人，因为我的心厌烦他们；他们的心也憎嫌我。","notes":[]},{"n":9,"t":"我就说：「我不牧养你们。要死的，由他死；要丧亡的，由他丧亡；余剩的，由他们彼此相食。」","notes":[]},{"n":10,"t":"我折断那称为「荣美」的杖，表明我废弃与万民所立的约。","notes":[]},{"n":11,"t":"当日就废弃了。这样，那些仰望我的困苦羊就知道所说的是耶和华的话。","notes":[]},{"n":12,"t":"我对他们说：「你们若以为美，就给我工价。不然，就罢了！」于是他们给了三十块钱作为我的工价。","notes":[]},{"n":13,"t":"耶和华吩咐我说：「要把众人所估定美好的价值丢给窑户。」我便将这三十块钱，在耶和华的殿中丢给窑户了。","notes":[]},{"n":14,"t":"我又折断称为「联索」的那根杖，表明我废弃犹大与以色列弟兄的情谊。","notes":[]},{"n":15,"t":"耶和华又吩咐我说：「你再取愚昧牧人所用的器具，","notes":[]},{"n":16,"t":"因我要在这地兴起一个牧人。他不看顾丧亡的，不寻找分散的，不医治受伤的，也不牧养强壮的；却要吃肥羊的肉，撕裂它的蹄子。","notes":[]},{"n":17,"t":"无用的牧人丢弃羊群有祸了！刀必临到他的膀臂和右眼上。他的膀臂必全然枯干；他的右眼也必昏暗失明。」","notes":[]}]},"12":{"heading":"耶路撒冷将蒙拯救","verses":[{"n":1,"t":"耶和华论以色列的默示。铺张诸天、建立地基、造人里面之灵的耶和华说：","notes":[]},{"n":2,"t":"「我必使耶路撒冷被围困的时候，向四围列国的民成为令人昏醉的杯；这默示也论到犹大。","notes":["或译：犹大也是如此"]},{"n":3,"t":"那日，我必使耶路撒冷向聚集攻击他的万民当作一块重石头；凡举起的必受重伤。","notes":[]},{"n":4,"t":"耶和华说：到那日，我必使一切马匹惊惶，使骑马的颠狂。我必看顾犹大家，使列国的一切马匹瞎眼。","notes":[]},{"n":5,"t":"犹大的族长必心里说：『耶路撒冷的居民倚靠万军之耶和华—他们的神，就作我们的能力。』","notes":[]},{"n":6,"t":"「那日，我必使犹大的族长如火盆在木柴中，又如火把在禾捆里；他们必左右烧灭四围列国的民。耶路撒冷人必仍住本处，就是耶路撒冷。","notes":[]},{"n":7,"t":"「耶和华必先拯救犹大的帐棚，免得大卫家的荣耀和耶路撒冷居民的荣耀胜过犹大。","notes":[]},{"n":8,"t":"那日，耶和华必保护耶路撒冷的居民。他们中间软弱的必如大卫；大卫的家必如神，如行在他们前面之耶和华的使者。","notes":[]},{"n":9,"t":"那日，我必定意灭绝来攻击耶路撒冷各国的民。","notes":[]},{"n":10,"t":"「我必将那施恩叫人恳求的灵，浇灌大卫家和耶路撒冷的居民。他们必仰望我，就是他们所扎的；必为我悲哀，如丧独生子，又为我愁苦，如丧长子。","notes":["或译：他；本节同"]},{"n":11,"t":"那日，耶路撒冷必有大大的悲哀，如米吉多平原之哈达临门的悲哀。","notes":[]},{"n":12,"t":"境内一家一家地都必悲哀。大卫家，男的独在一处，女的独在一处。拿单家，男的独在一处，女的独在一处。","notes":[]},{"n":13,"t":"利未家，男的独在一处，女的独在一处。示每家，男的独在一处，女的独在一处。","notes":[]},{"n":14,"t":"其余的各家，男的独在一处，女的独在一处。","notes":[]}]},"13":{"heading":"牧人被杀","verses":[{"n":1,"t":"「那日，必给大卫家和耶路撒冷的居民开一个泉源，洗除罪恶与污秽。」","notes":[]},{"n":2,"t":"万军之耶和华说：「那日，我必从地上除灭偶像的名，不再被人记念；也必使这地不再有假先知与污秽的灵。","notes":[]},{"n":3,"t":"若再有人说预言，生他的父母必对他说：『你不得存活，因为你托耶和华的名说假预言。』生他的父母在他说预言的时候，要将他刺透。","notes":[]},{"n":4,"t":"那日，凡作先知说预言的必因他所论的异象羞愧，不再穿毛衣哄骗人。","notes":[]},{"n":5,"t":"他必说：『我不是先知，我是耕地的；我从幼年作人的奴仆。』","notes":[]},{"n":6,"t":"必有人问他说：『你两臂中间是什么伤呢？』他必回答说：『这是我在亲友家中所受的伤。』」","notes":[]},{"n":7,"t":"万军之耶和华说：刀剑哪，应当兴起，攻击我的牧人和我的同伴。击打牧人，羊就分散；我必反手加在微小者的身上。","notes":[]},{"n":8,"t":"耶和华说：这全地的人，三分之二必剪除而死，三分之一仍必存留。","notes":[]},{"n":9,"t":"我要使这三分之一经火，熬炼他们，如熬炼银子；试炼他们，如试炼金子。他们必求告我的名，我必应允他们。我要说：这是我的子民。他们也要说：耶和华是我们的神。","notes":[]}]},"14":{"heading":"耶路撒冷和列国","verses":[{"n":1,"t":"耶和华的日子临近，你的财物必被抢掠，在你中间分散。","notes":[]},{"n":2,"t":"因为我必聚集万国与耶路撒冷争战，城必被攻取，房屋被抢夺，妇女被玷污，城中的民一半被掳去；剩下的民仍在城中，不致剪除。","notes":[]},{"n":3,"t":"那时，耶和华必出去与那些国争战，好像从前争战一样。","notes":[]},{"n":4,"t":"那日，他的脚必站在耶路撒冷前面朝东的橄榄山上。这山必从中间分裂，自东至西成为极大的谷。山的一半向北挪移，一半向南挪移。","notes":[]},{"n":5,"t":"你们要从我山的谷中逃跑，因为山谷必延到亚萨。你们逃跑，必如犹大王乌西雅年间的人逃避大地震一样。耶和华—我的神必降临，有一切圣者同来。","notes":[]},{"n":6,"t":"那日，必没有光，三光必退缩。","notes":[]},{"n":7,"t":"那日，必是耶和华所知道的，不是白昼，也不是黑夜，到了晚上才有光明。","notes":[]},{"n":8,"t":"那日，必有活水从耶路撒冷出来，一半往东海流，一半往西海流；冬夏都是如此。","notes":[]},{"n":9,"t":"耶和华必作全地的王。那日耶和华必为独一无二的，他的名也是独一无二的。","notes":[]},{"n":10,"t":"全地，从迦巴直到耶路撒冷南方的临门，要变为亚拉巴。耶路撒冷必仍居高位，就是从便雅悯门到第一门之处，又到角门，并从哈楠业楼，直到王的酒榨。","notes":[]},{"n":11,"t":"人必住在其中，不再有咒诅。耶路撒冷人必安然居住。","notes":[]},{"n":12,"t":"耶和华用灾殃攻击那与耶路撒冷争战的列国人，必是这样：他们两脚站立的时候，肉必消没，眼在眶中干瘪，舌在口中溃烂。","notes":[]},{"n":13,"t":"那日，耶和华必使他们大大扰乱。他们各人彼此揪住，举手攻击。","notes":[]},{"n":14,"t":"犹大也必在耶路撒冷争战。那时四围各国的财物，就是许多金银衣服，必被收聚。","notes":[]},{"n":15,"t":"那临到马匹、骡子、骆驼、驴，和营中一切牲畜的灾殃是与那灾殃一般。","notes":[]},{"n":16,"t":"所有来攻击耶路撒冷列国中剩下的人，必年年上来敬拜大君王—万军之耶和华，并守住棚节。","notes":[]},{"n":17,"t":"地上万族中，凡不上耶路撒冷敬拜大君王—万军之耶和华的，必无雨降在他们的地上。","notes":[]},{"n":18,"t":"埃及族若不上来，雨也不降在他们的地上；凡不上来守住棚节的列国人，耶和华也必用这灾攻击他们。","notes":[]},{"n":19,"t":"这就是埃及的刑罚和那不上来守住棚节之列国的刑罚。","notes":[]},{"n":20,"t":"当那日，马的铃铛上必有「归耶和华为圣」的这句话。耶和华殿内的锅必如祭坛前的碗一样。","notes":[]},{"n":21,"t":"凡耶路撒冷和犹大的锅都必归万军之耶和华为圣。凡献祭的都必来取这锅，煮肉在其中。当那日，在万军之耶和华的殿中必不再有迦南人。","notes":[]}]}},"MAL":{"1":{"heading":"耶和华爱以色列","verses":[{"n":1,"t":"耶和华借玛拉基传给以色列的默示。","notes":[]},{"n":2,"t":"耶和华说：「我曾爱你们。」你们却说：「你在何事上爱我们呢？」耶和华说：「以扫不是雅各的哥哥吗？我却爱雅各，","notes":[]},{"n":3,"t":"恶以扫，使他的山岭荒凉，把他的地业交给旷野的野狗。」","notes":[]},{"n":4,"t":"以东人说：「我们现在虽被毁坏，却要重建荒废之处。」万军之耶和华如此说：「任他们建造，我必拆毁；人必称他们的地为『罪恶之境』；称他们的民为『耶和华永远恼怒之民』。」","notes":[]},{"n":5,"t":"你们必亲眼看见，也必说：「愿耶和华在以色列境界之外被尊为大！」","notes":[]},{"n":6,"t":"「藐视我名的祭司啊，万军之耶和华对你们说：儿子尊敬父亲，仆人敬畏主人；我既为父亲，尊敬我的在哪里呢？我既为主人，敬畏我的在哪里呢？你们却说：『我们在何事上藐视你的名呢？』","notes":[],"heads":["斥责祭司"]},{"n":7,"t":"你们将污秽的食物献在我的坛上，且说：『我们在何事上污秽你呢？』因你们说，耶和华的桌子是可藐视的。","notes":[]},{"n":8,"t":"你们将瞎眼的献为祭物，这不为恶吗？将瘸腿的、有病的献上，这不为恶吗？你献给你的省长，他岂喜悦你，岂能看你的情面吗？这是万军之耶和华说的。","notes":[]},{"n":9,"t":"「现在我劝你们恳求神，他好施恩与我们。这妄献的事，既由你们经手，他岂能看你们的情面吗？这是万军之耶和华说的。","notes":[]},{"n":10,"t":"甚愿你们中间有一人关上殿门，免得你们徒然在我坛上烧火。万军之耶和华说：我不喜悦你们，也不从你们手中收纳供物。","notes":[]},{"n":11,"t":"万军之耶和华说：从日出之地到日落之处，我的名在外邦中必尊为大。在各处，人必奉我的名烧香，献洁净的供物，因为我的名在外邦中必尊为大。","notes":[]},{"n":12,"t":"你们却亵渎我的名，说：『耶和华的桌子是污秽的，其上的食物是可藐视的。』","notes":[]},{"n":13,"t":"你们又说：『这些事何等烦琐！』并嗤之以鼻。这是万军之耶和华说的。你们把抢夺的、瘸腿的、有病的拿来献上为祭。我岂能从你们手中收纳呢？这是耶和华说的。","notes":[]},{"n":14,"t":"行诡诈的在群中有公羊，他许愿却用有残疾的献给主，这人是可咒诅的。因为我是大君王，我的名在外邦中是可畏的。这是万军之耶和华说的。","notes":[]}]},"2":{"heading":"百姓对神不忠","verses":[{"n":1,"t":"「众祭司啊，这诫命是传给你们的。","notes":[]},{"n":2,"t":"万军之耶和华说：你们若不听从，也不放在心上，将荣耀归与我的名，我就使咒诅临到你们，使你们的福分变为咒诅；因你们不把诫命放在心上，我已经咒诅你们了。","notes":[]},{"n":3,"t":"我必斥责你们的种子，又把你们牺牲的粪抹在你们的脸上；你们要与粪一同除掉。","notes":[]},{"n":4,"t":"你们就知道我传这诫命给你们，使我与利未所立的约可以常存。这是万军之耶和华说的。","notes":["或译：利未人"]},{"n":5,"t":"我曾与他立生命和平安的约。我将这两样赐给他，使他存敬畏的心，他就敬畏我，惧怕我的名。","notes":[]},{"n":6,"t":"真实的律法在他口中，他嘴里没有不义的话。他以平安和正直与我同行，使多人回头离开罪孽。","notes":[]},{"n":7,"t":"祭司的嘴里当存知识，人也当由他口中寻求律法，因为他是万军之耶和华的使者。","notes":[]},{"n":8,"t":"你们却偏离正道，使许多人在律法上跌倒。你们废弃我与利未所立的约。这是万军之耶和华说的。","notes":[]},{"n":9,"t":"所以我使你们被众人藐视，看为下贱；因你们不守我的道，竟在律法上瞻徇情面。」","notes":[]},{"n":10,"t":"我们岂不都是一位父吗？岂不是一位神所造的吗？我们各人怎么以诡诈待弟兄，背弃了神与我们列祖所立的约呢？","notes":[]},{"n":11,"t":"犹大人行事诡诈，并且在以色列和耶路撒冷中行一件可憎的事；因为犹大人亵渎耶和华所喜爱的圣洁，娶事奉外邦神的女子为妻。","notes":["或译：圣地"]},{"n":12,"t":"凡行这事的，无论何人，就是献供物给万军之耶和华，耶和华也必从雅各的帐棚中剪除他。","notes":["何人：原文是叫醒的，答应的"]},{"n":13,"t":"你们又行了一件这样的事，使前妻叹息哭泣的眼泪遮盖耶和华的坛，以致耶和华不再看顾那供物，也不乐意从你们手中收纳。","notes":[]},{"n":14,"t":"你们还说：「这是为什么呢？」因耶和华在你和你幼年所娶的妻中间作见证。她虽是你的配偶，又是你盟约的妻，你却以诡诈待她。","notes":[]},{"n":15,"t":"虽然神有灵的余力能造多人，他不是单造一人吗？为何只造一人呢？乃是他愿人得虔诚的后裔。所以当谨守你们的心，谁也不可以诡诈待幼年所娶的妻。","notes":[]},{"n":16,"t":"耶和华—以色列的神说：「休妻的事和以强暴待妻的人都是我所恨恶的！所以当谨守你们的心，不可行诡诈。」这是万军之耶和华说的。","notes":[]},{"n":17,"t":"你们用言语烦琐耶和华，你们还说：「我们在何事上烦琐他呢？」因为你们说：「凡行恶的，耶和华眼看为善，并且他喜悦他们」；或说：「公义的神在哪里呢？」","notes":[],"heads":["审判之日已近"]}]},"3":{"heading":"十分之一捐献","verses":[{"n":1,"t":"万军之耶和华说：「我要差遣我的使者在我前面预备道路。你们所寻求的主必忽然进入他的殿；立约的使者，就是你们所仰慕的，快要来到。」","notes":[]},{"n":2,"t":"他来的日子，谁能当得起呢？他显现的时候，谁能立得住呢？因为他如炼金之人的火，如漂布之人的硷。","notes":[]},{"n":3,"t":"他必坐下如炼净银子的，必洁净利未人，熬炼他们像金银一样；他们就凭公义献供物给耶和华。","notes":[]},{"n":4,"t":"那时，犹大和耶路撒冷所献的供物必蒙耶和华悦纳，仿佛古时之日、上古之年。","notes":[]},{"n":5,"t":"万军之耶和华说：「我必临近你们，施行审判。我必速速作见证，警戒行邪术的、犯奸淫的、起假誓的、亏负人之工价的、欺压寡妇孤儿的、屈枉寄居的，和不敬畏我的。」","notes":[]},{"n":6,"t":"「因我—耶和华是不改变的，所以你们雅各之子没有灭亡。","notes":[]},{"n":7,"t":"万军之耶和华说：从你们列祖的日子以来，你们常常偏离我的典章而不遵守。现在你们要转向我，我就转向你们。你们却问说：『我们如何才是转向呢？』","notes":[]},{"n":8,"t":"人岂可夺取神之物呢？你们竟夺取我的供物。你们却说：『我们在何事上夺取你的供物呢？』就是你们在当纳的十分之一和当献的供物上。","notes":[]},{"n":9,"t":"因你们通国的人都夺取我的供物，咒诅就临到你们身上。","notes":[]},{"n":10,"t":"万军之耶和华说：你们要将当纳的十分之一全然送入仓库，使我家有粮，以此试试我，是否为你们敞开天上的窗户，倾福与你们，甚至无处可容。","notes":[]},{"n":11,"t":"万军之耶和华说：我必为你们斥责蝗虫，不容它毁坏你们的土产。你们田间的葡萄树在未熟之先也不掉果子。","notes":["原文是吞噬者"]},{"n":12,"t":"万军之耶和华说：万国必称你们为有福的，因你们的地必成为喜乐之地。」","notes":[]},{"n":13,"t":"耶和华说：「你们用话顶撞我，你们还说：『我们用什么话顶撞了你呢？』","notes":[],"heads":["神应许施怜悯"]},{"n":14,"t":"你们说：『事奉神是徒然的，遵守神所吩咐的，在万军之耶和华面前苦苦斋戒，有什么益处呢？","notes":[]},{"n":15,"t":"如今我们称狂傲的人为有福，并且行恶的人得建立；他们虽然试探神，却得脱离灾难。』」","notes":[]},{"n":16,"t":"那时，敬畏耶和华的彼此谈论，耶和华侧耳而听，且有纪念册在他面前，记录那敬畏耶和华、思念他名的人。","notes":[]},{"n":17,"t":"万军之耶和华说：「在我所定的日子，他们必属我，特特归我。我必怜恤他们，如同人怜恤服事自己的儿子。","notes":[]},{"n":18,"t":"那时你们必归回，将善人和恶人，事奉神的和不事奉神的，分别出来。」","notes":[]}]},"4":{"heading":"耶和华的日子临近","verses":[{"n":1,"t":"万军之耶和华说：「那日临近，势如烧着的火炉，凡狂傲的和行恶的必如碎秸，在那日必被烧尽，根本枝条一无存留。","notes":[]},{"n":2,"t":"但向你们敬畏我名的人必有公义的日头出现，其光线有医治之能。你们必出来跳跃如圈里的肥犊。","notes":["原文是翅膀"]},{"n":3,"t":"你们必践踏恶人；在我所定的日子，他们必如灰尘在你们脚掌之下。这是万军之耶和华说的。","notes":[]},{"n":4,"t":"「你们当记念我仆人摩西的律法，就是我在何烈山为以色列众人所吩咐他的律例典章。","notes":[]},{"n":5,"t":"「看哪，耶和华大而可畏之日未到以前，我必差遣先知以利亚到你们那里去。","notes":[]},{"n":6,"t":"他必使父亲的心转向儿女，儿女的心转向父亲，免得我来咒诅遍地。」","notes":[]}]}},"MAT":{"1":{"heading":"耶稣基督的家谱","verses":[{"n":1,"t":"亚伯拉罕的后裔，大卫的子孙，耶稣基督的家谱：","notes":["后裔，子孙：原文是儿子；下同"]},{"n":2,"t":"亚伯拉罕生以撒；以撒生雅各；雅各生犹大和他的弟兄；","notes":[]},{"n":3,"t":"犹大从她玛氏生法勒斯和谢拉；法勒斯生希斯仑；希斯仑生亚兰；","notes":[]},{"n":4,"t":"亚兰生亚米拿达；亚米拿达生拿顺；拿顺生撒门；","notes":[]},{"n":5,"t":"撒门从喇合氏生波阿斯；波阿斯从路得氏生俄备得；俄备得生耶西；","notes":[]},{"n":6,"t":"耶西生大卫王。大卫从乌利亚的妻子生所罗门；","notes":[]},{"n":7,"t":"所罗门生罗波安；罗波安生亚比雅；亚比雅生亚撒；","notes":[]},{"n":8,"t":"亚撒生约沙法；约沙法生约兰； 约兰生乌西雅；","notes":[]},{"n":9,"t":"乌西雅生约坦；约坦生亚哈斯；亚哈斯生希西家；","notes":[]},{"n":10,"t":"希西家生玛拿西；玛拿西生亚们；亚们生约西亚；","notes":[]},{"n":11,"t":"百姓被迁到巴比伦的时候，约西亚生耶哥尼雅和他的弟兄。","notes":[]},{"n":12,"t":"迁到巴比伦之后，耶哥尼雅生撒拉铁；撒拉铁生所罗巴伯；","notes":[]},{"n":13,"t":"所罗巴伯生亚比玉；亚比玉生以利亚敬；以利亚敬生亚所；","notes":[]},{"n":14,"t":"亚所生撒督；撒督生亚金；亚金生以律；","notes":[]},{"n":15,"t":"以律生以利亚撒；以利亚撒生马但；马但生雅各；","notes":[]},{"n":16,"t":"雅各生约瑟，就是马利亚的丈夫。那称为基督的耶稣是从马利亚生的。","notes":[]},{"n":17,"t":"这样，从亚伯拉罕到大卫共有十四代；从大卫到迁至巴比伦的时候也有十四代；从迁至巴比伦的时候到基督又有十四代。","notes":[]},{"n":18,"t":"耶稣基督降生的事记在下面：他母亲马利亚已经许配了约瑟，还没有迎娶，马利亚就从圣灵怀了孕。","notes":[],"heads":["耶稣基督降生"]},{"n":19,"t":"她丈夫约瑟是个义人，不愿意明明地羞辱她，想要暗暗地把她休了。","notes":[]},{"n":20,"t":"正思念这事的时候，有主的使者向他梦中显现，说：「大卫的子孙约瑟，不要怕！只管娶过你的妻子马利亚来，因她所怀的孕是从圣灵来的。","notes":[]},{"n":21,"t":"她将要生一个儿子，你要给他起名叫耶稣，因他要将自己的百姓从罪恶里救出来。」","notes":[]},{"n":22,"t":"这一切的事成就是要应验主借先知所说的话，","notes":[]},{"n":23,"t":"说：必有童女怀孕生子；人要称他的名为以马内利。（以马内利翻出来就是「神与我们同在」。）","notes":[]},{"n":24,"t":"约瑟醒了，起来，就遵着主使者的吩咐把妻子娶过来；","notes":[]},{"n":25,"t":"只是没有和她同房，等她生了儿子，就给他起名叫耶稣。","notes":["有古卷：等她生了头胎的儿子"]}]},"2":{"heading":"博士朝拜","verses":[{"n":1,"t":"当希律王的时候，耶稣生在犹太的伯利恒。有几个博士从东方来到耶路撒冷，说：","notes":[]},{"n":2,"t":"「那生下来作犹太人之王的在哪里？我们在东方看见他的星，特来拜他。」","notes":[]},{"n":3,"t":"希律王听见了，就心里不安；耶路撒冷合城的人也都不安。","notes":[]},{"n":4,"t":"他就召齐了祭司长和民间的文士，问他们说：「基督当生在何处？」","notes":[]},{"n":5,"t":"他们回答说：「在犹太的伯利恒。因为有先知记着，说：","notes":[]},{"n":6,"t":"犹大地的伯利恒啊，你在犹大诸城中并不是最小的；因为将来有一位君王要从你那里出来，牧养我以色列民。」","notes":[]},{"n":7,"t":"当下，希律暗暗地召了博士来，细问那星是什么时候出现的，","notes":[]},{"n":8,"t":"就差他们往伯利恒去，说：「你们去仔细寻访那小孩子，寻到了就来报信，我也好去拜他。」","notes":[]},{"n":9,"t":"他们听见王的话就去了。在东方所看见的那星忽然在他们前头行，直行到小孩子的地方，就在上头停住了。","notes":[]},{"n":10,"t":"他们看见那星，就大大地欢喜；","notes":[]},{"n":11,"t":"进了房子，看见小孩子和他母亲马利亚，就俯伏拜那小孩子，揭开宝盒，拿黄金、乳香、没药为礼物献给他。","notes":[]},{"n":12,"t":"博士因为在梦中被主指示不要回去见希律，就从别的路回本地去了。","notes":[]},{"n":13,"t":"他们去后，有主的使者向约瑟梦中显现，说：「起来！带着小孩子同他母亲逃往埃及，住在那里，等我吩咐你；因为希律必寻找小孩子，要除灭他。」","notes":[],"heads":["逃往埃及"]},{"n":14,"t":"约瑟就起来，夜间带着小孩子和他母亲往埃及去，","notes":[]},{"n":15,"t":"住在那里，直到希律死了。这是要应验主借先知所说的话，说：「我从埃及召出我的儿子来。」","notes":[]},{"n":16,"t":"希律见自己被博士愚弄，就大大发怒，差人将伯利恒城里并四境所有的男孩，照着他向博士仔细查问的时候，凡两岁以里的，都杀尽了。","notes":[],"heads":["屠杀男孩"]},{"n":17,"t":"这就应了先知耶利米的话，说：","notes":[]},{"n":18,"t":"在拉玛听见号咷大哭的声音，是拉结哭她儿女，不肯受安慰，因为他们都不在了。","notes":[]},{"n":19,"t":"希律死了以后，有主的使者在埃及向约瑟梦中显现，说：","notes":[],"heads":["从埃及回来"]},{"n":20,"t":"「起来！带着小孩子和他母亲往以色列地去，因为要害小孩子性命的人已经死了。」","notes":[]},{"n":21,"t":"约瑟就起来，把小孩子和他母亲带到以色列地去；","notes":[]},{"n":22,"t":"只因听见亚基老接着他父亲希律作了犹太王，就怕往那里去，又在梦中被主指示，便往加利利境内去了，","notes":[]},{"n":23,"t":"到了一座城，名叫拿撒勒，就住在那里。这是要应验先知所说，他将称为拿撒勒人的话了。","notes":[]}]},"3":{"heading":"施洗约翰传道","verses":[{"n":1,"t":"那时，有施洗的约翰出来，在犹太的旷野传道，说：","notes":[]},{"n":2,"t":"「天国近了，你们应当悔改！」","notes":[]},{"n":3,"t":"这人就是先知以赛亚所说的。他说：「在旷野有人声喊着说：预备主的道，修直他的路！」","notes":[]},{"n":4,"t":"这约翰身穿骆驼毛的衣服，腰束皮带，吃的是蝗虫、野蜜。","notes":[]},{"n":5,"t":"那时，耶路撒冷和犹太全地，并约旦河一带地方的人，都出去到约翰那里，","notes":[]},{"n":6,"t":"承认他们的罪，在约旦河里受他的洗。","notes":[]},{"n":7,"t":"约翰看见许多法利赛人和撒都该人也来受洗，就对他们说：「毒蛇的种类！谁指示你们逃避将来的愤怒呢？","notes":[]},{"n":8,"t":"你们要结出果子来，与悔改的心相称。","notes":[]},{"n":9,"t":"不要自己心里说：『有亚伯拉罕为我们的祖宗。』我告诉你们，神能从这些石头中给亚伯拉罕兴起子孙来。","notes":[]},{"n":10,"t":"现在斧子已经放在树根上，凡不结好果子的树就砍下来，丢在火里。","notes":[]},{"n":11,"t":"我是用水给你们施洗，叫你们悔改。但那在我以后来的，能力比我更大，我就是给他提鞋也不配。他要用圣灵与火给你们施洗。","notes":[]},{"n":12,"t":"他手里拿着簸箕，要扬净他的场，把麦子收在仓里，把糠用不灭的火烧尽了。」","notes":[]},{"n":13,"t":"当下，耶稣从加利利来到约旦河，见了约翰，要受他的洗。","notes":[],"heads":["耶稣受洗"]},{"n":14,"t":"约翰想要拦住他，说：「我当受你的洗，你反倒上我这里来吗？」","notes":[]},{"n":15,"t":"耶稣回答说：「你暂且许我，因为我们理当这样尽诸般的义。」于是约翰许了他。","notes":["或译：礼"]},{"n":16,"t":"耶稣受了洗，随即从水里上来。天忽然为他开了，他就看见神的灵仿佛鸽子降下，落在他身上。","notes":[]},{"n":17,"t":"从天上有声音说：「这是我的爱子，我所喜悦的。」","notes":[]}]},"4":{"heading":"耶稣受试探","verses":[{"n":1,"t":"当时，耶稣被圣灵引到旷野，受魔鬼的试探。","notes":[]},{"n":2,"t":"他禁食四十昼夜，后来就饿了。","notes":[]},{"n":3,"t":"那试探人的进前来，对他说：「你若是神的儿子，可以吩咐这些石头变成食物。」","notes":[]},{"n":4,"t":"耶稣却回答说：「经上记着说：人活着，不是单靠食物，乃是靠神口里所出的一切话。」","notes":[]},{"n":5,"t":"魔鬼就带他进了圣城，叫他站在殿顶上，","notes":["顶：原文是翅"]},{"n":6,"t":"对他说：「你若是神的儿子，可以跳下去，因为经上记着说：主要为你吩咐他的使者用手托着你，免得你的脚碰在石头上。」","notes":[]},{"n":7,"t":"耶稣对他说：「经上又记着说：『不可试探主—你的神。』」","notes":[]},{"n":8,"t":"魔鬼又带他上了一座最高的山，将世上的万国与万国的荣华都指给他看，","notes":[]},{"n":9,"t":"对他说：「你若俯伏拜我，我就把这一切都赐给你。」","notes":[]},{"n":10,"t":"耶稣说：「撒但，退去吧！因为经上记着说：当拜主—你的神，单要事奉他。」","notes":["就是抵挡的意思，乃魔鬼的别名"]},{"n":11,"t":"于是，魔鬼离了耶稣，有天使来伺候他。","notes":[]},{"n":12,"t":"耶稣听见约翰下了监，就退到加利利去；","notes":[],"heads":["开始在加利利传道"]},{"n":13,"t":"后又离开拿撒勒，往迦百农去，就住在那里。那地方靠海，在西布伦和拿弗他利的边界上。","notes":[]},{"n":14,"t":"这是要应验先知以赛亚的话，","notes":[]},{"n":15,"t":"说：西布伦地，拿弗他利地，就是沿海的路，约旦河外，外邦人的加利利地—","notes":[]},{"n":16,"t":"那坐在黑暗里的百姓看见了大光；坐在死荫之地的人有光发现照着他们。","notes":[]},{"n":17,"t":"从那时候，耶稣就传起道来，说：「天国近了，你们应当悔改！」","notes":[]},{"n":18,"t":"耶稣在加利利海边行走，看见弟兄二人，就是那称呼彼得的西门和他兄弟安得烈，在海里撒网；他们本是打鱼的。","notes":[],"heads":["呼召四个渔夫"]},{"n":19,"t":"耶稣对他们说：「来跟从我，我要叫你们得人如得鱼一样。」","notes":[]},{"n":20,"t":"他们就立刻舍了网，跟从了他。","notes":[]},{"n":21,"t":"从那里往前走，又看见弟兄二人，就是西庇太的儿子雅各和他兄弟约翰，同他们的父亲西庇太在船上补网，耶稣就招呼他们，","notes":[]},{"n":22,"t":"他们立刻舍了船，别了父亲，跟从了耶稣。","notes":[]},{"n":23,"t":"耶稣走遍加利利，在各会堂里教训人，传天国的福音，医治百姓各样的病症。","notes":[],"heads":["耶稣向广大的群众传道"]},{"n":24,"t":"他的名声就传遍了叙利亚。那里的人把一切害病的，就是害各样疾病、各样疼痛的和被鬼附的、癫痫的、瘫痪的，都带了来，耶稣就治好了他们。","notes":[]},{"n":25,"t":"当下，有许多人从加利利、低加坡里、耶路撒冷、犹太、约旦河外来跟着他。","notes":[]}]},"5":{"heading":"山上宝训","verses":[{"n":1,"t":"耶稣看见这许多的人，就上了山，既已坐下，门徒到他跟前来，","notes":[]},{"n":2,"t":"他就开口教训他们，说：","notes":[]},{"n":3,"t":"虚心的人有福了！因为天国是他们的。","notes":[],"heads":["论福"]},{"n":4,"t":"哀恸的人有福了！因为他们必得安慰。","notes":[]},{"n":5,"t":"温柔的人有福了！因为他们必承受地土。","notes":[]},{"n":6,"t":"饥渴慕义的人有福了！因为他们必得饱足。","notes":[]},{"n":7,"t":"怜恤人的人有福了！因为他们必蒙怜恤。","notes":[]},{"n":8,"t":"清心的人有福了！因为他们必得见神。","notes":[]},{"n":9,"t":"使人和睦的人有福了！因为他们必称为神的儿子。","notes":[]},{"n":10,"t":"为义受逼迫的人有福了！因为天国是他们的。","notes":[]},{"n":11,"t":"「人若因我辱骂你们，逼迫你们，捏造各样坏话毁谤你们，你们就有福了！","notes":[]},{"n":12,"t":"应当欢喜快乐，因为你们在天上的赏赐是大的。在你们以前的先知，人也是这样逼迫他们。」","notes":[]},{"n":13,"t":"「你们是世上的盐。盐若失了味，怎能叫它再咸呢？以后无用，不过丢在外面，被人践踏了。","notes":[],"heads":["盐和光"]},{"n":14,"t":"你们是世上的光。城造在山上是不能隐藏的。","notes":[]},{"n":15,"t":"人点灯，不放在斗底下，是放在灯台上，就照亮一家的人。","notes":[]},{"n":16,"t":"你们的光也当这样照在人前，叫他们看见你们的好行为，便将荣耀归给你们在天上的父。」","notes":[]},{"n":17,"t":"「莫想我来要废掉律法和先知。我来不是要废掉，乃是要成全。","notes":[],"heads":["论律法"]},{"n":18,"t":"我实在告诉你们，就是到天地都废去了，律法的一点一画也不能废去，都要成全。","notes":[]},{"n":19,"t":"所以，无论何人废掉这诫命中最小的一条，又教训人这样做，他在天国要称为最小的。但无论何人遵行这诫命，又教训人遵行，他在天国要称为大的。","notes":[]},{"n":20,"t":"我告诉你们，你们的义若不胜于文士和法利赛人的义，断不能进天国。」","notes":[]},{"n":21,"t":"「你们听见有吩咐古人的话，说：『不可杀人』；又说：『凡杀人的难免受审判。』","notes":[],"heads":["论发怒"]},{"n":22,"t":"只是我告诉你们，凡向弟兄动怒的，难免受审断；凡骂弟兄是拉加的，难免公会的审断；凡骂弟兄是魔利的，难免地狱的火。","notes":["有古卷在凡字下加：无缘无故地"]},{"n":23,"t":"所以，你在祭坛上献礼物的时候，若想起弟兄向你怀怨，","notes":[]},{"n":24,"t":"就把礼物留在坛前，先去同弟兄和好，然后来献礼物。","notes":[]},{"n":25,"t":"你同告你的对头还在路上，就赶紧与他和息，恐怕他把你送给审判官，审判官交付衙役，你就下在监里了。","notes":[]},{"n":26,"t":"我实在告诉你，若有一文钱没有还清，你断不能从那里出来。」","notes":[]},{"n":27,"t":"「你们听见有话说：『不可奸淫。』","notes":[],"heads":["论奸淫"]},{"n":28,"t":"只是我告诉你们，凡看见妇女就动淫念的，这人心里已经与她犯奸淫了。","notes":[]},{"n":29,"t":"若是你的右眼叫你跌倒，就剜出来丢掉，宁可失去百体中的一体，不叫全身丢在地狱里。","notes":[]},{"n":30,"t":"若是右手叫你跌倒，就砍下来丢掉，宁可失去百体中的一体，不叫全身下入地狱。」","notes":[]},{"n":31,"t":"「又有话说：『人若休妻，就当给她休书。』","notes":[],"heads":["论休妻"]},{"n":32,"t":"只是我告诉你们，凡休妻的，若不是为淫乱的缘故，就是叫她作淫妇了；人若娶这被休的妇人，也是犯奸淫了。」","notes":[]},{"n":33,"t":"「你们又听见有吩咐古人的话，说：『不可背誓，所起的誓总要向主谨守。』","notes":[],"heads":["论起誓"]},{"n":34,"t":"只是我告诉你们，什么誓都不可起。不可指着天起誓，因为天是神的座位；","notes":[]},{"n":35,"t":"不可指着地起誓，因为地是他的脚凳；也不可指着耶路撒冷起誓，因为耶路撒冷是大君的京城；","notes":[]},{"n":36,"t":"又不可指着你的头起誓，因为你不能使一根头发变黑变白了。","notes":[]},{"n":37,"t":"你们的话，是，就说是；不是，就说不是；若再多说就是出于那恶者。」","notes":["或译：就是从恶里出来的"]},{"n":38,"t":"「你们听见有话说：『以眼还眼，以牙还牙。』","notes":[],"heads":["论报复"]},{"n":39,"t":"只是我告诉你们，不要与恶人作对。有人打你的右脸，连左脸也转过来由他打；","notes":[]},{"n":40,"t":"有人想要告你，要拿你的里衣，连外衣也由他拿去；","notes":[]},{"n":41,"t":"有人强逼你走一里路，你就同他走二里；","notes":[]},{"n":42,"t":"有求你的，就给他；有向你借贷的，不可推辞。」","notes":[]},{"n":43,"t":"「你们听见有话说：『当爱你的邻舍，恨你的仇敌。』","notes":[],"heads":["论爱仇敌"]},{"n":44,"t":"只是我告诉你们，要爱你们的仇敌，为那逼迫你们的祷告。","notes":[]},{"n":45,"t":"这样就可以作你们天父的儿子；因为他叫日头照好人，也照歹人；降雨给义人，也给不义的人。","notes":[]},{"n":46,"t":"你们若单爱那爱你们的人，有什么赏赐呢？就是税吏不也是这样行吗？","notes":[]},{"n":47,"t":"你们若单请你弟兄的安，比人有什么长处呢？就是外邦人不也是这样行吗？","notes":[]},{"n":48,"t":"所以，你们要完全，像你们的天父完全一样。」","notes":[]}]},"6":{"heading":"论施舍","verses":[{"n":1,"t":"「你们要小心，不可将善事行在人的面前，故意叫他们看见，若是这样，就不能得你们天父的赏赐了。","notes":[]},{"n":2,"t":"所以，你施舍的时候，不可在你前面吹号，像那假冒为善的人在会堂里和街道上所行的，故意要得人的荣耀。我实在告诉你们，他们已经得了他们的赏赐。","notes":[]},{"n":3,"t":"你施舍的时候，不要叫左手知道右手所做的，","notes":[]},{"n":4,"t":"要叫你施舍的事行在暗中。你父在暗中察看，必然报答你。」","notes":["有古卷：必在明处报答你"]},{"n":5,"t":"「你们祷告的时候，不可像那假冒为善的人，爱站在会堂里和十字路口上祷告，故意叫人看见。我实在告诉你们，他们已经得了他们的赏赐。","notes":[],"heads":["论祷告"]},{"n":6,"t":"你祷告的时候，要进你的内屋，关上门，祷告你在暗中的父；你父在暗中察看，必然报答你。","notes":[]},{"n":7,"t":"你们祷告，不可像外邦人，用许多重复话，他们以为话多了必蒙垂听。","notes":[]},{"n":8,"t":"你们不可效法他们；因为你们没有祈求以先，你们所需用的，你们的父早已知道了。","notes":[]},{"n":9,"t":"所以，你们祷告要这样说：我们在天上的父：愿人都尊你的名为圣。","notes":[]},{"n":10,"t":"愿你的国降临；愿你的旨意行在地上，如同行在天上。","notes":[]},{"n":11,"t":"我们日用的饮食，今日赐给我们。","notes":[]},{"n":12,"t":"免我们的债，如同我们免了人的债。","notes":[]},{"n":13,"t":"不叫我们遇见试探；救我们脱离凶恶。因为国度、权柄、荣耀，全是你的，直到永远。阿们！","notes":["或译：脱离恶者","有古卷没有因为…阿们等字"]},{"n":14,"t":"「你们饶恕人的过犯，你们的天父也必饶恕你们的过犯；","notes":[]},{"n":15,"t":"你们不饶恕人的过犯，你们的天父也必不饶恕你们的过犯。」","notes":[]},{"n":16,"t":"「你们禁食的时候，不可像那假冒为善的人，脸上带着愁容；因为他们把脸弄得难看，故意叫人看出他们是禁食。我实在告诉你们，他们已经得了他们的赏赐。","notes":[],"heads":["论禁食"]},{"n":17,"t":"你禁食的时候，要梳头洗脸，","notes":[]},{"n":18,"t":"不叫人看出你禁食来，只叫你暗中的父看见；你父在暗中察看，必然报答你。」","notes":[]},{"n":19,"t":"「不要为自己积攒财宝在地上；地上有虫子咬，能锈坏，也有贼挖窟窿来偷。","notes":[],"heads":["论天上的财宝"]},{"n":20,"t":"只要积攒财宝在天上；天上没有虫子咬，不能锈坏，也没有贼挖窟窿来偷。","notes":[]},{"n":21,"t":"因为你的财宝在哪里，你的心也在那里。」","notes":[]},{"n":22,"t":"「眼睛就是身上的灯。你的眼睛若了亮，全身就光明；","notes":[],"heads":["论心里的光"]},{"n":23,"t":"你的眼睛若昏花，全身就黑暗。你里头的光若黑暗了，那黑暗是何等大呢！」","notes":[]},{"n":24,"t":"「一个人不能事奉两个主；不是恶这个、爱那个，就是重这个、轻那个。你们不能又事奉神，又事奉玛门。」","notes":["玛门：财利的意思"],"heads":["论神和财利"]},{"n":25,"t":"「所以我告诉你们，不要为生命忧虑吃什么，喝什么；为身体忧虑穿什么。生命不胜于饮食吗？身体不胜于衣裳吗？","notes":[],"heads":["不要忧虑"]},{"n":26,"t":"你们看那天上的飞鸟，也不种，也不收，也不积蓄在仓里，你们的天父尚且养活它。你们不比飞鸟贵重得多吗？","notes":[]},{"n":27,"t":"你们哪一个能用思虑使寿数多加一刻呢？","notes":["或译：使身量多加一肘呢"]},{"n":28,"t":"何必为衣裳忧虑呢？你想野地里的百合花怎么长起来；它也不劳苦，也不纺线。","notes":[]},{"n":29,"t":"然而我告诉你们，就是所罗门极荣华的时候，他所穿戴的，还不如这花一朵呢！","notes":[]},{"n":30,"t":"你们这小信的人哪！野地里的草今天还在，明天就丢在炉里，神还给它这样的妆饰，何况你们呢！","notes":[]},{"n":31,"t":"所以，不要忧虑说，吃什么？喝什么？穿什么？","notes":[]},{"n":32,"t":"这都是外邦人所求的。你们需用的这一切东西，你们的天父是知道的。","notes":[]},{"n":33,"t":"你们要先求他的国和他的义，这些东西都要加给你们了。","notes":[]},{"n":34,"t":"所以，不要为明天忧虑，因为明天自有明天的忧虑；一天的难处一天当就够了。」","notes":[]}]},"7":{"heading":"不要论断人","verses":[{"n":1,"t":"「你们不要论断人，免得你们被论断。","notes":[]},{"n":2,"t":"因为你们怎样论断人，也必怎样被论断；你们用什么量器量给人，也必用什么量器量给你们。","notes":[]},{"n":3,"t":"为什么看见你弟兄眼中有刺，却不想自己眼中有梁木呢？","notes":[]},{"n":4,"t":"你自己眼中有梁木，怎能对你弟兄说：『容我去掉你眼中的刺』呢？","notes":[]},{"n":5,"t":"你这假冒为善的人！先去掉自己眼中的梁木，然后才能看得清楚，去掉你弟兄眼中的刺。","notes":[]},{"n":6,"t":"不要把圣物给狗，也不要把你们的珍珠丢在猪前，恐怕它践踏了珍珠，转过来咬你们。」","notes":[]},{"n":7,"t":"「你们祈求，就给你们；寻找，就寻见；叩门，就给你们开门。","notes":[],"heads":["祈求、寻找、叩门"]},{"n":8,"t":"因为凡祈求的，就得着；寻找的，就寻见；叩门的，就给他开门。","notes":[]},{"n":9,"t":"你们中间谁有儿子求饼，反给他石头呢？","notes":[]},{"n":10,"t":"求鱼，反给他蛇呢？","notes":[]},{"n":11,"t":"你们虽然不好，尚且知道拿好东西给儿女，何况你们在天上的父，岂不更把好东西给求他的人吗？","notes":[]},{"n":12,"t":"所以，无论何事，你们愿意人怎样待你们，你们也要怎样待人，因为这就是律法和先知的道理。」","notes":[]},{"n":13,"t":"「你们要进窄门。因为引到灭亡，那门是宽的，路是大的，进去的人也多；","notes":[],"heads":["窄门"]},{"n":14,"t":"引到永生，那门是窄的，路是小的，找着的人也少。」","notes":[]},{"n":15,"t":"「你们要防备假先知。他们到你们这里来，外面披着羊皮，里面却是残暴的狼。","notes":[],"heads":["两种果树"]},{"n":16,"t":"凭着他们的果子，就可以认出他们来。荆棘上岂能摘葡萄呢？蒺藜里岂能摘无花果呢？","notes":[]},{"n":17,"t":"这样，凡好树都结好果子，惟独坏树结坏果子。","notes":[]},{"n":18,"t":"好树不能结坏果子；坏树不能结好果子。","notes":[]},{"n":19,"t":"凡不结好果子的树就砍下来，丢在火里。","notes":[]},{"n":20,"t":"所以，凭着他们的果子就可以认出他们来。」","notes":[]},{"n":21,"t":"「凡称呼我『主啊，主啊』的人不能都进天国；惟独遵行我天父旨意的人才能进去。","notes":[],"heads":["我不认识你们"]},{"n":22,"t":"当那日必有许多人对我说：『主啊，主啊，我们不是奉你的名传道，奉你的名赶鬼，奉你的名行许多异能吗？』","notes":[]},{"n":23,"t":"我就明明地告诉他们说：『我从来不认识你们，你们这些作恶的人，离开我去吧！』」","notes":[]},{"n":24,"t":"「所以，凡听见我这话就去行的，好比一个聪明人，把房子盖在磐石上；","notes":[],"heads":["两种盖房子的人"]},{"n":25,"t":"雨淋，水冲，风吹，撞着那房子，房子总不倒塌，因为根基立在磐石上。","notes":[]},{"n":26,"t":"凡听见我这话不去行的，好比一个无知的人，把房子盖在沙土上；","notes":[]},{"n":27,"t":"雨淋，水冲，风吹，撞着那房子，房子就倒塌了，并且倒塌得很大。」","notes":[]},{"n":28,"t":"耶稣讲完了这些话，众人都希奇他的教训；","notes":[]},{"n":29,"t":"因为他教训他们，正像有权柄的人，不像他们的文士。","notes":[]}]},"8":{"heading":"洁净长大麻风的人","verses":[{"n":1,"t":"耶稣下了山，有许多人跟着他。","notes":[]},{"n":2,"t":"有一个长大麻风的来拜他，说：「主若肯，必能叫我洁净了。」","notes":[]},{"n":3,"t":"耶稣伸手摸他，说：「我肯，你洁净了吧！」他的大麻风立刻就洁净了。","notes":[]},{"n":4,"t":"耶稣对他说：「你切不可告诉人，只要去把身体给祭司察看，献上摩西所吩咐的礼物，对众人作证据。」","notes":[]},{"n":5,"t":"耶稣进了迦百农，有一个百夫长进前来，求他说：","notes":[],"heads":["治好百夫长的仆人"]},{"n":6,"t":"「主啊，我的仆人害瘫痪病，躺在家里，甚是疼苦。」","notes":[]},{"n":7,"t":"耶稣说：「我去医治他。」","notes":[]},{"n":8,"t":"百夫长回答说：「主啊，你到我舍下，我不敢当；只要你说一句话，我的仆人就必好了。","notes":[]},{"n":9,"t":"因为我在人的权下，也有兵在我以下；对这个说『去！』他就去；对那个说『来！』他就来；对我的仆人说：『你做这事！』他就去做。」","notes":[]},{"n":10,"t":"耶稣听见就希奇，对跟从的人说：「我实在告诉你们，这么大的信心，就是在以色列中，我也没有遇见过。","notes":[]},{"n":11,"t":"我又告诉你们，从东从西，将有许多人来，在天国里与亚伯拉罕、以撒、雅各一同坐席；","notes":[]},{"n":12,"t":"惟有本国的子民竟被赶到外边黑暗里去，在那里必要哀哭切齿了。」","notes":[]},{"n":13,"t":"耶稣对百夫长说：「你回去吧！照你的信心，给你成全了。」那时，他的仆人就好了。","notes":[]},{"n":14,"t":"耶稣到了彼得家里，见彼得的岳母害热病躺着。","notes":[],"heads":["治好许多病人"]},{"n":15,"t":"耶稣把她的手一摸，热就退了；她就起来服事耶稣。","notes":[]},{"n":16,"t":"到了晚上，有人带着许多被鬼附的来到耶稣跟前，他只用一句话就把鬼都赶出去，并且治好了一切有病的人。","notes":[]},{"n":17,"t":"这是要应验先知以赛亚的话，说：他代替我们的软弱，担当我们的疾病。","notes":[]},{"n":18,"t":"耶稣见许多人围着他，就吩咐渡到那边去。","notes":[],"heads":["要跟从耶稣的人"]},{"n":19,"t":"有一个文士来，对他说：「夫子，你无论往哪里去，我要跟从你。」","notes":[]},{"n":20,"t":"耶稣说：「狐狸有洞，天空的飞鸟有窝，人子却没有枕头的地方。」","notes":[]},{"n":21,"t":"又有一个门徒对耶稣说：「主啊，容我先回去埋葬我的父亲。」","notes":[]},{"n":22,"t":"耶稣说：「任凭死人埋葬他们的死人；你跟从我吧！」","notes":[]},{"n":23,"t":"耶稣上了船，门徒跟着他。","notes":[],"heads":["平静风和海"]},{"n":24,"t":"海里忽然起了暴风，甚至船被波浪掩盖；耶稣却睡着了。","notes":[]},{"n":25,"t":"门徒来叫醒了他，说：「主啊，救我们，我们丧命啦！」","notes":[]},{"n":26,"t":"耶稣说：「你们这小信的人哪，为什么胆怯呢？」于是起来，斥责风和海，风和海就大大地平静了。","notes":[]},{"n":27,"t":"众人希奇，说：「这是怎样的人？连风和海也听从他了！」","notes":[]},{"n":28,"t":"耶稣既渡到那边去，来到加大拉人的地方，就有两个被鬼附的人从坟茔里出来迎着他，极其凶猛，甚至没有人能从那条路上经过。","notes":[],"heads":["治好加大拉被鬼附的人"]},{"n":29,"t":"他们喊着说：「神的儿子，我们与你有什么相干？时候还没有到，你就上这里来叫我们受苦吗？」","notes":[]},{"n":30,"t":"离他们很远，有一大群猪吃食。","notes":[]},{"n":31,"t":"鬼就央求耶稣，说：「若把我们赶出去，就打发我们进入猪群吧！」","notes":[]},{"n":32,"t":"耶稣说：「去吧！」鬼就出来，进入猪群。全群忽然闯下山崖，投在海里淹死了。","notes":[]},{"n":33,"t":"放猪的就逃跑进城，将这一切事和被鬼附的人所遭遇的都告诉人。","notes":[]},{"n":34,"t":"合城的人都出来迎见耶稣，既见了就央求他离开他们的境界。","notes":[]}]},"9":{"heading":"治好瘫痪病人","verses":[{"n":1,"t":"耶稣上了船，渡过海，来到自己的城里。","notes":[]},{"n":2,"t":"有人用褥子抬着一个瘫子到耶稣跟前来。耶稣见他们的信心，就对瘫子说：「小子，放心吧！你的罪赦了。」","notes":[]},{"n":3,"t":"有几个文士心里说：「这个人说僭妄的话了。」","notes":[]},{"n":4,"t":"耶稣知道他们的心意，就说：「你们为什么心里怀着恶念呢？","notes":[]},{"n":5,"t":"或说『你的罪赦了』，或说『你起来行走』，哪一样容易呢？","notes":[]},{"n":6,"t":"但要叫你们知道，人子在地上有赦罪的权柄」；就对瘫子说：「起来！拿你的褥子回家去吧。」","notes":[]},{"n":7,"t":"那人就起来，回家去了。","notes":[]},{"n":8,"t":"众人看见都惊奇，就归荣耀与神，因为他将这样的权柄赐给人。","notes":[]},{"n":9,"t":"耶稣从那里往前走，看见一个人名叫马太，坐在税关上，就对他说：「你跟从我来。」他就起来跟从了耶稣。","notes":[],"heads":["呼召马太"]},{"n":10,"t":"耶稣在屋里坐席的时候，有好些税吏和罪人来，与耶稣和他的门徒一同坐席。","notes":[]},{"n":11,"t":"法利赛人看见，就对耶稣的门徒说：「你们的先生为什么和税吏并罪人一同吃饭呢？」","notes":[]},{"n":12,"t":"耶稣听见，就说：「康健的人用不着医生，有病的人才用得着。","notes":[]},{"n":13,"t":"经上说：『我喜爱怜恤，不喜爱祭祀。』这句话的意思，你们且去揣摩。我来本不是召义人，乃是召罪人。」","notes":[]},{"n":14,"t":"那时，约翰的门徒来见耶稣，说：「我们和法利赛人常常禁食，你的门徒倒不禁食，这是为什么呢？」","notes":[],"heads":["禁食的问题"]},{"n":15,"t":"耶稣对他们说：「新郎和陪伴之人同在的时候，陪伴之人岂能哀恸呢？但日子将到，新郎要离开他们，那时候他们就要禁食。","notes":[]},{"n":16,"t":"没有人把新布补在旧衣服上；因为所补上的反带坏了那衣服，破的就更大了。","notes":[]},{"n":17,"t":"也没有人把新酒装在旧皮袋里；若是这样，皮袋就裂开，酒漏出来，连皮袋也坏了。惟独把新酒装在新皮袋里，两样就都保全了。」","notes":[]},{"n":18,"t":"耶稣说这话的时候，有一个管会堂的来拜他，说：「我女儿刚才死了，求你去按手在她身上，她就必活了。」","notes":[],"heads":["管会堂者的女儿和血漏的女人"]},{"n":19,"t":"耶稣便起来跟着他去；门徒也跟了去。","notes":[]},{"n":20,"t":"有一个女人，患了十二年的血漏，来到耶稣背后，摸他的衣裳繸子；","notes":[]},{"n":21,"t":"因为她心里说：「我只摸他的衣裳，就必痊愈。」","notes":[]},{"n":22,"t":"耶稣转过来，看见她，就说：「女儿，放心！你的信救了你。」从那时候，女人就痊愈了。","notes":[]},{"n":23,"t":"耶稣到了管会堂的家里，看见有吹手，又有许多人乱嚷，","notes":[]},{"n":24,"t":"就说：「退去吧！这闺女不是死了，是睡着了。」他们就嗤笑他。","notes":[]},{"n":25,"t":"众人既被撵出，耶稣就进去，拉着闺女的手，闺女便起来了。","notes":[]},{"n":26,"t":"于是这风声传遍了那地方。","notes":[]},{"n":27,"t":"耶稣从那里往前走，有两个瞎子跟着他，喊叫说：「大卫的子孙，可怜我们吧！」","notes":[],"heads":["两个瞎子得医治"]},{"n":28,"t":"耶稣进了房子，瞎子就来到他跟前。耶稣说：「你们信我能做这事吗？」他们说：「主啊，我们信。」","notes":[]},{"n":29,"t":"耶稣就摸他们的眼睛，说：「照着你们的信给你们成全了吧。」","notes":[]},{"n":30,"t":"他们的眼睛就开了。耶稣切切地嘱咐他们说：「你们要小心，不可叫人知道。」","notes":[]},{"n":31,"t":"他们出去，竟把他的名声传遍了那地方。","notes":[]},{"n":32,"t":"他们出去的时候，有人将鬼所附的一个哑巴带到耶稣跟前来。","notes":[],"heads":["治好哑巴"]},{"n":33,"t":"鬼被赶出去，哑巴就说出话来。众人都希奇，说：「在以色列中，从来没有见过这样的事。」","notes":[]},{"n":34,"t":"法利赛人却说：「他是靠着鬼王赶鬼。」","notes":[]},{"n":35,"t":"耶稣走遍各城各乡，在会堂里教训人，宣讲天国的福音，又医治各样的病症。","notes":[],"heads":["耶稣的怜悯"]},{"n":36,"t":"他看见许多的人，就怜悯他们；因为他们困苦流离，如同羊没有牧人一般。","notes":[]},{"n":37,"t":"于是对门徒说：「要收的庄稼多，做工的人少。","notes":[]},{"n":38,"t":"所以，你们当求庄稼的主打发工人出去收他的庄稼。」","notes":[]}]},"10":{"heading":"十二使徒","verses":[{"n":1,"t":"耶稣叫了十二个门徒来，给他们权柄，能赶逐污鬼，并医治各样的病症。","notes":[]},{"n":2,"t":"这十二使徒的名：头一个叫西门（又称彼得），还有他兄弟安得烈，西庇太的儿子雅各和雅各的兄弟约翰，","notes":[]},{"n":3,"t":"腓力和巴多罗买，多马和税吏马太，亚勒腓的儿子雅各，和达太，","notes":[]},{"n":4,"t":"奋锐党的西门，还有卖耶稣的加略人犹大。","notes":[]},{"n":5,"t":"耶稣差这十二个人去，吩咐他们说：「外邦人的路，你们不要走；撒马利亚人的城，你们不要进；","notes":[],"heads":["十二使徒的使命"]},{"n":6,"t":"宁可往以色列家迷失的羊那里去。","notes":[]},{"n":7,"t":"随走随传，说『天国近了！』","notes":[]},{"n":8,"t":"医治病人，叫死人复活，叫长大麻风的洁净，把鬼赶出去。你们白白地得来，也要白白地舍去。","notes":[]},{"n":9,"t":"腰袋里不要带金银铜钱；","notes":[]},{"n":10,"t":"行路不要带口袋；不要带两件褂子，也不要带鞋和拐杖。因为工人得饮食是应当的。","notes":[]},{"n":11,"t":"你们无论进哪一城，哪一村，要打听那里谁是好人，就住在他家，直住到走的时候。","notes":[]},{"n":12,"t":"进他家里去，要请他的安。","notes":[]},{"n":13,"t":"那家若配得平安，你们所求的平安就必临到那家；若不配得，你们所求的平安仍归你们。","notes":[]},{"n":14,"t":"凡不接待你们、不听你们话的人，你们离开那家，或是那城的时候，就把脚上的尘土跺下去。","notes":[]},{"n":15,"t":"我实在告诉你们，当审判的日子，所多玛和蛾摩拉所受的，比那城还容易受呢！」","notes":[]},{"n":16,"t":"「我差你们去，如同羊进入狼群；所以你们要灵巧像蛇，驯良像鸽子。","notes":[],"heads":["将来的逼迫"]},{"n":17,"t":"你们要防备人；因为他们要把你们交给公会，也要在会堂里鞭打你们，","notes":[]},{"n":18,"t":"并且你们要为我的缘故被送到诸侯君王面前，对他们和外邦人作见证。","notes":[]},{"n":19,"t":"你们被交的时候，不要思虑怎样说话，或说什么话。到那时候，必赐给你们当说的话；","notes":[]},{"n":20,"t":"因为不是你们自己说的，乃是你们父的灵在你们里头说的。","notes":[]},{"n":21,"t":"弟兄要把弟兄，父亲要把儿子，送到死地；儿女要与父母为敌，害死他们；","notes":[]},{"n":22,"t":"并且你们要为我的名被众人恨恶。惟有忍耐到底的必然得救。","notes":[]},{"n":23,"t":"有人在这城里逼迫你们，就逃到那城里去。我实在告诉你们，以色列的城邑，你们还没有走遍，人子就到了。","notes":[]},{"n":24,"t":"学生不能高过先生；仆人不能高过主人。","notes":[]},{"n":25,"t":"学生和先生一样，仆人和主人一样，也就罢了。人既骂家主是别西卜，何况他的家人呢？」","notes":["别西卜：是鬼王的名"]},{"n":26,"t":"「所以，不要怕他们；因为掩盖的事没有不露出来的，隐藏的事没有不被人知道的。","notes":[],"heads":["该怕的是谁"]},{"n":27,"t":"我在暗中告诉你们的，你们要在明处说出来；你们耳中所听的，要在房上宣扬出来。","notes":[]},{"n":28,"t":"那杀身体、不能杀灵魂的，不要怕他们；惟有能把身体和灵魂都灭在地狱里的，正要怕他。","notes":[]},{"n":29,"t":"两个麻雀不是卖一分银子吗？若是你们的父不许，一个也不能掉在地上；","notes":[]},{"n":30,"t":"就是你们的头发也都被数过了。","notes":[]},{"n":31,"t":"所以，不要惧怕，你们比许多麻雀还贵重！」","notes":[]},{"n":32,"t":"「凡在人面前认我的，我在我天上的父面前也必认他；","notes":[],"heads":["在人的面前承认基督"]},{"n":33,"t":"凡在人面前不认我的，我在我天上的父面前也必不认他。」","notes":[]},{"n":34,"t":"「你们不要想我来是叫地上太平；我来并不是叫地上太平，乃是叫地上动刀兵。","notes":[],"heads":["不是和平，而是刀剑"]},{"n":35,"t":"因为我来是叫人与父亲生疏，女儿与母亲生疏，媳妇与婆婆生疏。","notes":[]},{"n":36,"t":"人的仇敌就是自己家里的人。","notes":[]},{"n":37,"t":"「爱父母过于爱我的，不配作我的门徒；爱儿女过于爱我的，不配作我的门徒；","notes":[]},{"n":38,"t":"不背着他的十字架跟从我的，也不配作我的门徒。","notes":[]},{"n":39,"t":"得着生命的，将要失丧生命；为我失丧生命的，将要得着生命。」","notes":[]},{"n":40,"t":"「人接待你们就是接待我；接待我就是接待那差我来的。","notes":[],"heads":["论报赏"]},{"n":41,"t":"人因为先知的名接待先知，必得先知所得的赏赐；人因为义人的名接待义人，必得义人所得的赏赐。","notes":[]},{"n":42,"t":"无论何人，因为门徒的名，只把一杯凉水给这小子里的一个喝，我实在告诉你们，这人不能不得赏赐。」","notes":[]}]},"11":{"heading":"施洗约翰的门徒来见耶稣","verses":[{"n":1,"t":"耶稣吩咐完了十二个门徒，就离开那里，往各城去传道、教训人。","notes":[]},{"n":2,"t":"约翰在监里听见基督所做的事，就打发两个门徒去，","notes":[]},{"n":3,"t":"问他说：「那将要来的是你吗？还是我们等候别人呢？」","notes":[]},{"n":4,"t":"耶稣回答说：「你们去，把所听见、所看见的事告诉约翰。","notes":[]},{"n":5,"t":"就是瞎子看见，瘸子行走，长大麻风的洁净，聋子听见，死人复活，穷人有福音传给他们。","notes":[]},{"n":6,"t":"凡不因我跌倒的就有福了！」","notes":[]},{"n":7,"t":"他们走的时候，耶稣就对众人讲论约翰说：「你们从前出到旷野是要看什么呢？要看风吹动的芦苇吗？","notes":[]},{"n":8,"t":"你们出去到底是要看什么？要看穿细软衣服的人吗？那穿细软衣服的人是在王宫里。","notes":[]},{"n":9,"t":"你们出去究竟是为什么？是要看先知吗？我告诉你们，是的，他比先知大多了。","notes":[]},{"n":10,"t":"经上记着说：『我要差遣我的使者在你前面预备道路』，所说的就是这个人。","notes":[]},{"n":11,"t":"我实在告诉你们，凡妇人所生的，没有一个兴起来大过施洗约翰的；然而天国里最小的比他还大。","notes":[]},{"n":12,"t":"从施洗约翰的时候到如今，天国是努力进入的，努力的人就得着了。","notes":[]},{"n":13,"t":"因为众先知和律法说预言，到约翰为止。","notes":[]},{"n":14,"t":"你们若肯领受，这人就是那应当来的以利亚。","notes":[]},{"n":15,"t":"有耳可听的，就应当听！","notes":[]},{"n":16,"t":"我可用什么比这世代呢？好像孩童坐在街市上招呼同伴，说：","notes":[]},{"n":17,"t":"我们向你们吹笛，你们不跳舞；我们向你们举哀，你们不捶胸。","notes":[]},{"n":18,"t":"约翰来了，也不吃也不喝，人就说他是被鬼附着的；","notes":[]},{"n":19,"t":"人子来了，也吃也喝，人又说他是贪食好酒的人，是税吏和罪人的朋友。但智慧之子总以智慧为是。」","notes":["有古卷：但智慧在行为上就显为是"]},{"n":20,"t":"耶稣在诸城中行了许多异能，那些城的人终不悔改，就在那时候责备他们，说：","notes":[],"heads":["耶稣责备不悔改的城"]},{"n":21,"t":"「哥拉汛哪，你有祸了！伯赛大啊，你有祸了！因为在你们中间所行的异能，若行在泰尔、西顿，他们早已披麻蒙灰悔改了。","notes":[]},{"n":22,"t":"但我告诉你们，当审判的日子，泰尔、西顿所受的，比你们还容易受呢！","notes":[]},{"n":23,"t":"迦百农啊，你已经升到天上，将来必坠落阴间；因为在你那里所行的异能，若行在所多玛，它还可以存到今日。","notes":["或译：你将要升到天上吗"]},{"n":24,"t":"但我告诉你们，当审判的日子，所多玛所受的，比你还容易受呢！」","notes":[]},{"n":25,"t":"那时，耶稣说：「父啊，天地的主，我感谢你！因为你将这些事向聪明通达人就藏起来，向婴孩就显出来。","notes":[],"heads":["到我这里来"]},{"n":26,"t":"父啊，是的，因为你的美意本是如此。","notes":[]},{"n":27,"t":"一切所有的，都是我父交付我的；除了父，没有人知道子；除了子和子所愿意指示的，没有人知道父。","notes":[]},{"n":28,"t":"凡劳苦担重担的人可以到我这里来，我就使你们得安息。","notes":[]},{"n":29,"t":"我心里柔和谦卑，你们当负我的轭，学我的样式；这样，你们心里就必得享安息。","notes":[]},{"n":30,"t":"因为我的轭是容易的，我的担子是轻省的。」","notes":[]}]},"12":{"heading":"安息日的问题","verses":[{"n":1,"t":"那时，耶稣在安息日从麦地经过。他的门徒饿了，就掐起麦穗来吃。","notes":[]},{"n":2,"t":"法利赛人看见，就对耶稣说：「看哪，你的门徒做安息日不可做的事了！」","notes":[]},{"n":3,"t":"耶稣对他们说：「经上记着大卫和跟从他的人饥饿之时所做的事，你们没有念过吗？","notes":[]},{"n":4,"t":"他怎么进了神的殿，吃了陈设饼，这饼不是他和跟从他的人可以吃得，惟独祭司才可以吃。","notes":[]},{"n":5,"t":"再者，律法上所记的，当安息日，祭司在殿里犯了安息日还是没有罪，你们没有念过吗？","notes":[]},{"n":6,"t":"但我告诉你们，在这里有一人比殿更大。","notes":[]},{"n":7,"t":"『我喜爱怜恤，不喜爱祭祀。』你们若明白这话的意思，就不将无罪的当作有罪的了。","notes":[]},{"n":8,"t":"因为人子是安息日的主。」","notes":[]},{"n":9,"t":"耶稣离开那地方，进了一个会堂。","notes":[],"heads":["治好枯干了一只手的人"]},{"n":10,"t":"那里有一个人枯干了一只手。有人问耶稣说：「安息日治病可以不可以？」意思是要控告他。","notes":[]},{"n":11,"t":"耶稣说：「你们中间谁有一只羊，当安息日掉在坑里，不把它抓住、拉上来呢？","notes":[]},{"n":12,"t":"人比羊何等贵重呢！所以，在安息日做善事是可以的。」","notes":[]},{"n":13,"t":"于是对那人说：「伸出手来！」他把手一伸，手就复了原，和那只手一样。","notes":[]},{"n":14,"t":"法利赛人出去，商议怎样可以除灭耶稣。","notes":[]},{"n":15,"t":"耶稣知道了，就离开那里，有许多人跟着他。他把其中有病的人都治好了；","notes":[],"heads":["神所拣选的仆人"]},{"n":16,"t":"又嘱咐他们，不要给他传名。","notes":[]},{"n":17,"t":"这是要应验先知以赛亚的话，说：","notes":[]},{"n":18,"t":"看哪！我的仆人，我所拣选、所亲爱、心里所喜悦的，我要将我的灵赐给他；他必将公理传给外邦。","notes":[]},{"n":19,"t":"他不争竞，不喧嚷；街上也没有人听见他的声音。","notes":[]},{"n":20,"t":"压伤的芦苇，他不折断；将残的灯火，他不吹灭；等他施行公理，叫公理得胜。","notes":[]},{"n":21,"t":"外邦人都要仰望他的名。","notes":[]},{"n":22,"t":"当下，有人将一个被鬼附着、又瞎又哑的人带到耶稣那里，耶稣就医治他，甚至那哑巴又能说话，又能看见。","notes":[],"heads":["耶稣和别西卜"]},{"n":23,"t":"众人都惊奇，说：「这不是大卫的子孙吗？」","notes":[]},{"n":24,"t":"但法利赛人听见，就说：「这个人赶鬼，无非是靠着鬼王别西卜啊。」","notes":[]},{"n":25,"t":"耶稣知道他们的意念，就对他们说：「凡一国自相纷争，就成为荒场；一城一家自相纷争，必站立不住；","notes":[]},{"n":26,"t":"若撒但赶逐撒但，就是自相纷争，他的国怎能站得住呢？","notes":[]},{"n":27,"t":"我若靠着别西卜赶鬼，你们的子弟赶鬼又靠着谁呢？这样，他们就要断定你们的是非。","notes":[]},{"n":28,"t":"我若靠着神的灵赶鬼，这就是神的国临到你们了。","notes":[]},{"n":29,"t":"人怎能进壮士家里，抢夺他的家具呢？除非先捆住那壮士，才可以抢夺他的家财。","notes":[]},{"n":30,"t":"不与我相合的，就是敌我的；不同我收聚的，就是分散的。」","notes":[]},{"n":31,"t":"所以我告诉你们：「人一切的罪和亵渎的话都可得赦免，惟独亵渎圣灵，总不得赦免。","notes":[]},{"n":32,"t":"凡说话干犯人子的，还可得赦免；惟独说话干犯圣灵的，今世来世总不得赦免。」","notes":[]},{"n":33,"t":"「你们或以为树好，果子也好；树坏，果子也坏；因为看果子就可以知道树。","notes":[],"heads":["树和果子"]},{"n":34,"t":"毒蛇的种类！你们既是恶人，怎能说出好话来呢？因为心里所充满的，口里就说出来。","notes":[]},{"n":35,"t":"善人从他心里所存的善就发出善来；恶人从他心里所存的恶就发出恶来。","notes":[]},{"n":36,"t":"我又告诉你们，凡人所说的闲话，当审判的日子，必要句句供出来；","notes":[]},{"n":37,"t":"因为要凭你的话定你为义，也要凭你的话定你有罪。」","notes":[]},{"n":38,"t":"当时，有几个文士和法利赛人对耶稣说：「夫子，我们愿意你显个神迹给我们看。」","notes":[],"heads":["要求神迹"]},{"n":39,"t":"耶稣回答说：「一个邪恶淫乱的世代求看神迹，除了先知约拿的神迹以外，再没有神迹给他们看。","notes":[]},{"n":40,"t":"约拿三日三夜在大鱼肚腹中，人子也要这样三日三夜在地里头。","notes":[]},{"n":41,"t":"当审判的时候，尼尼微人要起来定这世代的罪，因为尼尼微人听了约拿所传的就悔改了。看哪，在这里有一人比约拿更大！","notes":[]},{"n":42,"t":"当审判的时候，南方的女王要起来定这世代的罪；因为她从地极而来，要听所罗门的智慧话。看哪，在这里有一人比所罗门更大！」","notes":[]},{"n":43,"t":"「污鬼离了人身，就在无水之地过来过去，寻求安歇之处，却寻不着。","notes":[],"heads":["污鬼回来"]},{"n":44,"t":"于是说：『我要回到我所出来的屋里去。』到了，就看见里面空闲，打扫干净，修饰好了，","notes":[]},{"n":45,"t":"便去另带了七个比自己更恶的鬼来，都进去住在那里。那人末后的景况比先前更不好了。这邪恶的世代也要如此。」","notes":[]},{"n":46,"t":"耶稣还对众人说话的时候，不料他母亲和他弟兄站在外边，要与他说话。","notes":[],"heads":["耶稣的母亲和兄弟们"]},{"n":47,"t":"有人告诉他说：「看哪，你母亲和你弟兄站在外边，要与你说话。」","notes":[]},{"n":48,"t":"他却回答那人说：「谁是我的母亲？谁是我的弟兄？」","notes":[]},{"n":49,"t":"就伸手指着门徒，说：「看哪，我的母亲，我的弟兄。","notes":[]},{"n":50,"t":"凡遵行我天父旨意的人，就是我的弟兄姊妹和母亲了。」","notes":[]}]},"13":{"heading":"撒种的比喻","verses":[{"n":1,"t":"当那一天，耶稣从房子里出来，坐在海边。","notes":[]},{"n":2,"t":"有许多人到他那里聚集，他只得上船坐下，众人都站在岸上。","notes":[]},{"n":3,"t":"他用比喻对他们讲许多道理，说：「有一个撒种的出去撒种；","notes":[]},{"n":4,"t":"撒的时候，有落在路旁的，飞鸟来吃尽了；","notes":[]},{"n":5,"t":"有落在土浅石头地上的，土既不深，发苗最快，","notes":[]},{"n":6,"t":"日头出来一晒，因为没有根，就枯干了；","notes":[]},{"n":7,"t":"有落在荆棘里的，荆棘长起来，把它挤住了；","notes":[]},{"n":8,"t":"又有落在好土里的，就结实，有一百倍的，有六十倍的，有三十倍的。","notes":[]},{"n":9,"t":"有耳可听的，就应当听！」","notes":[]},{"n":10,"t":"门徒进前来，问耶稣说：「对众人讲话，为什么用比喻呢？」","notes":[],"heads":["用比喻的目的"]},{"n":11,"t":"耶稣回答说：「因为天国的奥秘只叫你们知道，不叫他们知道。","notes":[]},{"n":12,"t":"凡有的，还要加给他，叫他有余；凡没有的，连他所有的，也要夺去。","notes":[]},{"n":13,"t":"所以我用比喻对他们讲，是因他们看也看不见，听也听不见，也不明白。","notes":[]},{"n":14,"t":"在他们身上，正应了以赛亚的预言，说：你们听是要听见，却不明白；看是要看见，却不晓得；","notes":[]},{"n":15,"t":"因为这百姓油蒙了心，耳朵发沉，眼睛闭着，恐怕眼睛看见，耳朵听见，心里明白，回转过来，我就医治他们。","notes":[]},{"n":16,"t":"「但你们的眼睛是有福的，因为看见了；你们的耳朵也是有福的，因为听见了。","notes":[]},{"n":17,"t":"我实在告诉你们，从前有许多先知和义人要看你们所看的，却没有看见，要听你们所听的，却没有听见。」","notes":[]},{"n":18,"t":"「所以，你们当听这撒种的比喻。","notes":[],"heads":["解明撒种的比喻"]},{"n":19,"t":"凡听见天国道理不明白的，那恶者就来，把所撒在他心里的夺了去；这就是撒在路旁的了。","notes":[]},{"n":20,"t":"撒在石头地上的，就是人听了道，当下欢喜领受，","notes":[]},{"n":21,"t":"只因心里没有根，不过是暂时的，及至为道遭了患难，或是受了逼迫，立刻就跌倒了。","notes":[]},{"n":22,"t":"撒在荆棘里的，就是人听了道，后来有世上的思虑、钱财的迷惑把道挤住了，不能结实。","notes":[]},{"n":23,"t":"撒在好地上的，就是人听道明白了，后来结实，有一百倍的，有六十倍的，有三十倍的。」","notes":[]},{"n":24,"t":"耶稣又设个比喻对他们说：「天国好像人撒好种在田里，","notes":[],"heads":["稗子的比喻"]},{"n":25,"t":"及至人睡觉的时候，有仇敌来，将稗子撒在麦子里就走了。","notes":[]},{"n":26,"t":"到长苗吐穗的时候，稗子也显出来。","notes":[]},{"n":27,"t":"田主的仆人来告诉他说：『主啊，你不是撒好种在田里吗？从哪里来的稗子呢？』","notes":[]},{"n":28,"t":"主人说：『这是仇敌做的。』仆人说：『你要我们去薅出来吗？』","notes":[]},{"n":29,"t":"主人说：『不必，恐怕薅稗子，连麦子也拔出来。","notes":[]},{"n":30,"t":"容这两样一齐长，等着收割。当收割的时候，我要对收割的人说，先将稗子薅出来，捆成捆，留着烧；惟有麦子要收在仓里。』」","notes":[]},{"n":31,"t":"他又设个比喻对他们说：「天国好像一粒芥菜种，有人拿去种在田里。","notes":[],"heads":["芥菜种和面酵的比喻"]},{"n":32,"t":"这原是百种里最小的，等到长起来，却比各样的菜都大，且成了树，天上的飞鸟来宿在它的枝上。」","notes":[]},{"n":33,"t":"他又对他们讲个比喻说：「天国好像面酵，有妇人拿来，藏在三斗面里，直等全团都发起来。」","notes":[]},{"n":34,"t":"这都是耶稣用比喻对众人说的话；若不用比喻，就不对他们说什么。","notes":[],"heads":["用比喻的原因"]},{"n":35,"t":"这是要应验先知的话，说：我要开口用比喻，把创世以来所隐藏的事发明出来。","notes":[]},{"n":36,"t":"当下，耶稣离开众人，进了房子。他的门徒进前来，说：「请把田间稗子的比喻讲给我们听。」","notes":[],"heads":["解明稗子的比喻"]},{"n":37,"t":"他回答说：「那撒好种的就是人子；","notes":[]},{"n":38,"t":"田地就是世界；好种就是天国之子；稗子就是那恶者之子；","notes":[]},{"n":39,"t":"撒稗子的仇敌就是魔鬼；收割的时候就是世界的末了；收割的人就是天使。","notes":[]},{"n":40,"t":"将稗子薅出来用火焚烧，世界的末了也要如此。","notes":[]},{"n":41,"t":"人子要差遣使者，把一切叫人跌倒的和作恶的，从他国里挑出来，","notes":[]},{"n":42,"t":"丢在火炉里；在那里必要哀哭切齿了。","notes":[]},{"n":43,"t":"那时，义人在他们父的国里，要发出光来，像太阳一样。有耳可听的，就应当听！」","notes":[]},{"n":44,"t":"「天国好像宝贝藏在地里，人遇见了就把它藏起来，欢欢喜喜地去变卖一切所有的，买这块地。","notes":[],"heads":["藏宝、寻珠、撒网的比喻"]},{"n":45,"t":"天国又好像买卖人寻找好珠子，","notes":[]},{"n":46,"t":"遇见一颗重价的珠子，就去变卖他一切所有的，买了这颗珠子。","notes":[]},{"n":47,"t":"天国又好像网撒在海里，聚拢各样水族，","notes":[]},{"n":48,"t":"网既满了，人就拉上岸来，坐下，拣好的收在器具里，将不好的丢弃了。","notes":[]},{"n":49,"t":"世界的末了也要这样。天使要出来，从义人中把恶人分别出来，","notes":[]},{"n":50,"t":"丢在火炉里；在那里必要哀哭切齿了。」","notes":[]},{"n":51,"t":"耶稣说：「这一切的话你们都明白了吗？」他们说：「我们明白了。」","notes":[],"heads":["新旧的东西"]},{"n":52,"t":"他说：「凡文士受教作天国的门徒，就像一个家主从他库里拿出新旧的东西来。」","notes":[]},{"n":53,"t":"耶稣说完了这些比喻，就离开那里，","notes":[],"heads":["拿撒勒人厌弃耶稣"]},{"n":54,"t":"来到自己的家乡，在会堂里教训人，甚至他们都希奇，说：「这人从哪里有这等智慧和异能呢？","notes":[]},{"n":55,"t":"这不是木匠的儿子吗？他母亲不是叫马利亚吗？他弟兄们不是叫雅各、约西、西门、犹大吗？","notes":["有古卷：约瑟"]},{"n":56,"t":"他妹妹们不是都在我们这里吗？这人从哪里有这一切的事呢？」","notes":[]},{"n":57,"t":"他们就厌弃他。耶稣对他们说：「大凡先知，除了本地本家之外，没有不被人尊敬的。」","notes":["厌弃他：原文是因他跌倒"]},{"n":58,"t":"耶稣因为他们不信，就在那里不多行异能了。","notes":[]}]},"14":{"heading":"施洗约翰的死","verses":[{"n":1,"t":"那时，分封的王希律听见耶稣的名声，","notes":[]},{"n":2,"t":"就对臣仆说：「这是施洗的约翰从死里复活，所以这些异能从他里面发出来。」","notes":[]},{"n":3,"t":"起先，希律为他兄弟腓力的妻子希罗底的缘故，把约翰拿住，锁在监里。","notes":[]},{"n":4,"t":"因为约翰曾对他说：「你娶这妇人是不合理的。」","notes":[]},{"n":5,"t":"希律就想要杀他，只是怕百姓，因为他们以约翰为先知。","notes":[]},{"n":6,"t":"到了希律的生日，希罗底的女儿在众人面前跳舞，使希律欢喜。","notes":[]},{"n":7,"t":"希律就起誓，应许随她所求的给她。","notes":[]},{"n":8,"t":"女儿被母亲所使，就说：「请把施洗约翰的头放在盘子里，拿来给我。」","notes":[]},{"n":9,"t":"王便忧愁，但因他所起的誓，又因同席的人，就吩咐给她；","notes":[]},{"n":10,"t":"于是打发人去，在监里斩了约翰，","notes":[]},{"n":11,"t":"把头放在盘子里，拿来给了女子；女子拿去给她母亲。","notes":[]},{"n":12,"t":"约翰的门徒来，把尸首领去埋葬了，就去告诉耶稣。","notes":[]},{"n":13,"t":"耶稣听见了，就上船从那里独自退到野地里去。众人听见，就从各城里步行跟随他。","notes":[],"heads":["耶稣给五千人吃饱"]},{"n":14,"t":"耶稣出来，见有许多的人，就怜悯他们，治好了他们的病人。","notes":[]},{"n":15,"t":"天将晚的时候，门徒进前来，说：「这是野地，时候已经过了，请叫众人散开，他们好往村子里去，自己买吃的。」","notes":[]},{"n":16,"t":"耶稣说：「不用他们去，你们给他们吃吧！」","notes":[]},{"n":17,"t":"门徒说：「我们这里只有五个饼，两条鱼。」","notes":[]},{"n":18,"t":"耶稣说：「拿过来给我。」","notes":[]},{"n":19,"t":"于是吩咐众人坐在草地上，就拿着这五个饼，两条鱼，望着天祝福，擘开饼，递给门徒，门徒又递给众人。","notes":[]},{"n":20,"t":"他们都吃，并且吃饱了，把剩下的零碎收拾起来，装满了十二个篮子。","notes":[]},{"n":21,"t":"吃的人，除了妇女孩子，约有五千。","notes":[]},{"n":22,"t":"耶稣随即催门徒上船，先渡到那边去，等他叫众人散开。","notes":[],"heads":["耶稣在海面上行走"]},{"n":23,"t":"散了众人以后，他就独自上山去祷告。到了晚上，只有他一人在那里。","notes":[]},{"n":24,"t":"那时船在海中，因风不顺，被浪摇撼。","notes":[]},{"n":25,"t":"夜里四更天，耶稣在海面上走，往门徒那里去。","notes":[]},{"n":26,"t":"门徒看见他在海面上走，就惊慌了，说：「是个鬼怪！」便害怕，喊叫起来。","notes":[]},{"n":27,"t":"耶稣连忙对他们说：「你们放心，是我，不要怕！」","notes":[]},{"n":28,"t":"彼得说：「主，如果是你，请叫我从水面上走到你那里去。」","notes":[]},{"n":29,"t":"耶稣说：「你来吧。」彼得就从船上下去，在水面上走，要到耶稣那里去；","notes":[]},{"n":30,"t":"只因见风甚大，就害怕，将要沉下去，便喊着说：「主啊，救我！」","notes":[]},{"n":31,"t":"耶稣赶紧伸手拉住他，说：「你这小信的人哪，为什么疑惑呢？」","notes":[]},{"n":32,"t":"他们上了船，风就住了。","notes":[]},{"n":33,"t":"在船上的人都拜他，说：「你真是神的儿子了。」","notes":[]},{"n":34,"t":"他们过了海，来到革尼撒勒地方。","notes":[],"heads":["治好革尼撒勒的病人"]},{"n":35,"t":"那里的人一认出是耶稣，就打发人到周围地方去，把所有的病人带到他那里，","notes":[]},{"n":36,"t":"只求耶稣准他们摸他的衣裳繸子；摸着的人就都好了。","notes":[]}]},"15":{"heading":"古人的传统","verses":[{"n":1,"t":"那时，有法利赛人和文士从耶路撒冷来见耶稣，说：","notes":[]},{"n":2,"t":"「你的门徒为什么犯古人的遗传呢？因为吃饭的时候，他们不洗手。」","notes":[]},{"n":3,"t":"耶稣回答说：「你们为什么因着你们的遗传犯神的诫命呢？","notes":[]},{"n":4,"t":"神说：『当孝敬父母』；又说：『咒骂父母的，必治死他。』","notes":[]},{"n":5,"t":"你们倒说：『无论何人对父母说：我所当奉给你的已经作了供献，","notes":[]},{"n":6,"t":"他就可以不孝敬父母。』这就是你们借着遗传，废了神的诫命。","notes":[]},{"n":7,"t":"假冒为善的人哪，以赛亚指着你们说的预言是不错的。他说：","notes":[]},{"n":8,"t":"这百姓用嘴唇尊敬我，心却远离我；","notes":[]},{"n":9,"t":"他们将人的吩咐当作道理教导人，所以拜我也是枉然。」","notes":[]},{"n":10,"t":"耶稣就叫了众人来，对他们说：「你们要听，也要明白。","notes":[]},{"n":11,"t":"入口的不能污秽人，出口的乃能污秽人。」","notes":[]},{"n":12,"t":"当时，门徒进前来对他说：「法利赛人听见这话，不服，你知道吗？」","notes":["原文是跌倒"]},{"n":13,"t":"耶稣回答说：「凡栽种的物，若不是我天父栽种的，必要拔出来。","notes":[]},{"n":14,"t":"任凭他们吧！他们是瞎眼领路的；若是瞎子领瞎子，两个人都要掉在坑里。」","notes":[]},{"n":15,"t":"彼得对耶稣说：「请将这比喻讲给我们听。」","notes":[]},{"n":16,"t":"耶稣说：「你们到如今还不明白吗？","notes":[]},{"n":17,"t":"岂不知凡入口的，是运到肚子里，又落在茅厕里吗？","notes":[]},{"n":18,"t":"惟独出口的，是从心里发出来的，这才污秽人。","notes":[]},{"n":19,"t":"因为从心里发出来的，有恶念、凶杀、奸淫、苟合、偷盗、妄证、谤讟。","notes":[]},{"n":20,"t":"这都是污秽人的；至于不洗手吃饭，那却不污秽人。」","notes":[]},{"n":21,"t":"耶稣离开那里，退到泰尔、西顿的境内去。","notes":[],"heads":["迦南妇人的信心"]},{"n":22,"t":"有一个迦南妇人，从那地方出来，喊着说：「主啊，大卫的子孙，可怜我！我女儿被鬼附得甚苦。」","notes":[]},{"n":23,"t":"耶稣却一言不答。门徒进前来，求他说：「这妇人在我们后头喊叫，请打发她走吧。」","notes":[]},{"n":24,"t":"耶稣说：「我奉差遣不过是到以色列家迷失的羊那里去。」","notes":[]},{"n":25,"t":"那妇人来拜他，说：「主啊，帮助我！」","notes":[]},{"n":26,"t":"他回答说：「不好拿儿女的饼丢给狗吃。」","notes":[]},{"n":27,"t":"妇人说：「主啊，不错；但是狗也吃它主人桌子上掉下来的碎渣儿。」","notes":[]},{"n":28,"t":"耶稣说：「妇人，你的信心是大的！照你所要的，给你成全了吧。」从那时候，她女儿就好了。","notes":[]},{"n":29,"t":"耶稣离开那地方，来到靠近加利利的海边，就上山坐下。","notes":[],"heads":["治好许多病人"]},{"n":30,"t":"有许多人到他那里，带着瘸子、瞎子、哑巴、有残疾的，和好些别的病人，都放在他脚前；他就治好了他们。","notes":[]},{"n":31,"t":"甚至众人都希奇；因为看见哑巴说话，残疾的痊愈，瘸子行走，瞎子看见，他们就归荣耀给以色列的神。","notes":[]},{"n":32,"t":"耶稣叫门徒来，说：「我怜悯这众人；因为他们同我在这里已经三天，也没有吃的了。我不愿意叫他们饿着回去，恐怕在路上困乏。」","notes":[],"heads":["耶稣给四千人吃饱"]},{"n":33,"t":"门徒说：「我们在这野地，哪里有这么多的饼叫这许多人吃饱呢？」","notes":[]},{"n":34,"t":"耶稣说：「你们有多少饼？」他们说：「有七个，还有几条小鱼。」","notes":[]},{"n":35,"t":"他就吩咐众人坐在地上，","notes":[]},{"n":36,"t":"拿着这七个饼和几条鱼，祝谢了，擘开，递给门徒；门徒又递给众人。","notes":[]},{"n":37,"t":"众人都吃，并且吃饱了，收拾剩下的零碎，装满了七个筐子。","notes":[]},{"n":38,"t":"吃的人，除了妇女孩子，共有四千。","notes":[]},{"n":39,"t":"耶稣叫众人散去，就上船，来到马加丹的境界。","notes":[]}]},"16":{"heading":"求主显个神迹","verses":[{"n":1,"t":"法利赛人和撒都该人来试探耶稣，请他从天上显个神迹给他们看。","notes":[]},{"n":2,"t":"耶稣回答说：「晚上天发红，你们就说：『天必要晴。』","notes":[]},{"n":3,"t":"早晨天发红，又发黑，你们就说：『今日必有风雨。』你们知道分辨天上的气色，倒不能分辨这时候的神迹。","notes":[]},{"n":4,"t":"一个邪恶淫乱的世代求神迹，除了约拿的神迹以外，再没有神迹给他看。」耶稣就离开他们去了。","notes":[]},{"n":5,"t":"门徒渡到那边去，忘了带饼。","notes":[],"heads":["防备法利赛人和撒都该人的酵"]},{"n":6,"t":"耶稣对他们说：「你们要谨慎，防备法利赛人和撒都该人的酵。」","notes":[]},{"n":7,"t":"门徒彼此议论说：「这是因为我们没有带饼吧。」","notes":[]},{"n":8,"t":"耶稣看出来，就说：「你们这小信的人，为什么因为没有饼彼此议论呢？","notes":[]},{"n":9,"t":"你们还不明白吗？不记得那五个饼分给五千人、又收拾了多少篮子的零碎吗？","notes":[]},{"n":10,"t":"也不记得那七个饼分给四千人、又收拾了多少筐子的零碎吗？","notes":[]},{"n":11,"t":"我对你们说：『要防备法利赛人和撒都该人的酵』，这话不是指着饼说的，你们怎么不明白呢？」","notes":[]},{"n":12,"t":"门徒这才晓得他说的不是叫他们防备饼的酵，乃是防备法利赛人和撒都该人的教训。","notes":[]},{"n":13,"t":"耶稣到了凯撒利亚·腓立比的境内，就问门徒说：「人说我—人子是谁？」","notes":["有古卷没有我字"],"heads":["彼得认耶稣为基督"]},{"n":14,"t":"他们说：「有人说是施洗的约翰；有人说是以利亚；又有人说是耶利米或是先知里的一位。」","notes":[]},{"n":15,"t":"耶稣说：「你们说我是谁？」","notes":[]},{"n":16,"t":"西门·彼得回答说：「你是基督，是永生神的儿子。」","notes":[]},{"n":17,"t":"耶稣对他说：「西门·巴·约拿，你是有福的！因为这不是属血肉的指示你的，乃是我在天上的父指示的。","notes":[]},{"n":18,"t":"我还告诉你，你是彼得，我要把我的教会建造在这磐石上；阴间的权柄不能胜过他。","notes":["权柄：原文是门"]},{"n":19,"t":"我要把天国的钥匙给你，凡你在地上所捆绑的，在天上也要捆绑；凡你在地上所释放的，在天上也要释放。」","notes":[]},{"n":20,"t":"当下，耶稣嘱咐门徒，不可对人说他是基督。","notes":[]},{"n":21,"t":"从此，耶稣才指示门徒，他必须上耶路撒冷去，受长老、祭司长、文士许多的苦，并且被杀，第三日复活。","notes":[],"heads":["耶稣预言受难和复活"]},{"n":22,"t":"彼得就拉着他，劝他说：「主啊，万不可如此！这事必不临到你身上。」","notes":[]},{"n":23,"t":"耶稣转过来，对彼得说：「撒但，退我后边去吧！你是绊我脚的；因为你不体贴神的意思，只体贴人的意思。」","notes":[]},{"n":24,"t":"于是耶稣对门徒说：「若有人要跟从我，就当舍己，背起他的十字架来跟从我。","notes":[]},{"n":25,"t":"因为，凡要救自己生命的，必丧掉生命；凡为我丧掉生命的，必得着生命。","notes":["生命：或译灵魂；下同"]},{"n":26,"t":"人若赚得全世界，赔上自己的生命，有什么益处呢？人还能拿什么换生命呢？","notes":[]},{"n":27,"t":"人子要在他父的荣耀里，同着众使者降临；那时候，他要照各人的行为报应各人。","notes":[]},{"n":28,"t":"我实在告诉你们，站在这里的，有人在没尝死味以前必看见人子降临在他的国里。」","notes":[]}]},"17":{"heading":"耶稣改变形象","verses":[{"n":1,"t":"过了六天，耶稣带着彼得、雅各，和雅各的兄弟约翰，暗暗地上了高山，","notes":[]},{"n":2,"t":"就在他们面前变了形象，脸面明亮如日头，衣裳洁白如光。","notes":[]},{"n":3,"t":"忽然，有摩西、以利亚向他们显现，同耶稣说话。","notes":[]},{"n":4,"t":"彼得对耶稣说：「主啊，我们在这里真好！你若愿意，我就在这里搭三座棚，一座为你，一座为摩西，一座为以利亚。」","notes":[]},{"n":5,"t":"说话之间，忽然有一朵光明的云彩遮盖他们，且有声音从云彩里出来，说：「这是我的爱子，我所喜悦的。你们要听他！」","notes":[]},{"n":6,"t":"门徒听见，就俯伏在地，极其害怕。","notes":[]},{"n":7,"t":"耶稣进前来，摸他们，说：「起来，不要害怕！」","notes":[]},{"n":8,"t":"他们举目不见一人，只见耶稣在那里。","notes":[]},{"n":9,"t":"下山的时候，耶稣吩咐他们说：「人子还没有从死里复活，你们不要将所看见的告诉人。」","notes":[]},{"n":10,"t":"门徒问耶稣说：「文士为什么说以利亚必须先来？」","notes":[]},{"n":11,"t":"耶稣回答说：「以利亚固然先来，并要复兴万事；","notes":[]},{"n":12,"t":"只是我告诉你们，以利亚已经来了，人却不认识他，竟任意待他。人子也将要这样受他们的害。」","notes":[]},{"n":13,"t":"门徒这才明白耶稣所说的是指着施洗的约翰。","notes":[]},{"n":14,"t":"耶稣和门徒到了众人那里，有一个人来见耶稣，跪下，","notes":[],"heads":["治好被鬼附身的孩子"]},{"n":15,"t":"说：「主啊，怜悯我的儿子！他害癫痫的病很苦，屡次跌在火里，屡次跌在水里。","notes":[]},{"n":16,"t":"我带他到你门徒那里，他们却不能医治他。」","notes":[]},{"n":17,"t":"耶稣说：「嗳！这又不信又悖谬的世代啊，我在你们这里要到几时呢？我忍耐你们要到几时呢？把他带到我这里来吧！」","notes":[]},{"n":18,"t":"耶稣斥责那鬼，鬼就出来；从此孩子就痊愈了。","notes":[]},{"n":19,"t":"门徒暗暗地到耶稣跟前，说：「我们为什么不能赶出那鬼呢？」","notes":[]},{"n":20,"t":"耶稣说：「是因你们的信心小。我实在告诉你们，你们若有信心，像一粒芥菜种，就是对这座山说：『你从这边挪到那边』，它也必挪去；并且你们没有一件不能做的事了。","notes":[]},{"n":21,"t":"至于这一类的鬼，若不祷告、禁食，他就不出来。」","notes":["或译：不能赶他出来"]},{"n":22,"t":"他们还住在加利利的时候，耶稣对门徒说：「人子将要被交在人手里。","notes":[],"heads":["耶稣第二次预言受难和复活"]},{"n":23,"t":"他们要杀害他，第三日他要复活。」门徒就大大地忧愁。","notes":[]},{"n":24,"t":"到了迦百农，有收丁税的人来见彼得，说：「你们的先生不纳丁税吗？」","notes":["丁税约有半块钱"],"heads":["缴纳殿税"]},{"n":25,"t":"彼得说：「纳。」他进了屋子，耶稣先向他说：「西门，你的意思如何？世上的君王向谁征收关税、丁税？是向自己的儿子呢？是向外人呢？」","notes":[]},{"n":26,"t":"彼得说：「是向外人。」耶稣说：「既然如此，儿子就可以免税了。","notes":[]},{"n":27,"t":"但恐怕触犯他们，你且往海边去钓鱼，把先钓上来的鱼拿起来，开了它的口，必得一块钱，可以拿去给他们，作你我的税银。」","notes":["触犯：原文是绊倒"]}]},"18":{"heading":"天国里最伟大的人","verses":[{"n":1,"t":"当时，门徒进前来，问耶稣说：「天国里谁是最大的？」","notes":[]},{"n":2,"t":"耶稣便叫一个小孩子来，使他站在他们当中，","notes":[]},{"n":3,"t":"说：「我实在告诉你们，你们若不回转，变成小孩子的样式，断不得进天国。","notes":[]},{"n":4,"t":"所以，凡自己谦卑像这小孩子的，他在天国里就是最大的。","notes":[]},{"n":5,"t":"凡为我的名接待一个像这小孩子的，就是接待我。」","notes":[]},{"n":6,"t":"「凡使这信我的一个小子跌倒的，倒不如把大磨石拴在这人的颈项上，沉在深海里。","notes":[],"heads":["罪的诱惑"]},{"n":7,"t":"这世界有祸了，因为将人绊倒；绊倒人的事是免不了的，但那绊倒人的有祸了！","notes":[]},{"n":8,"t":"倘若你一只手，或是一只脚，叫你跌倒，就砍下来丢掉。你缺一只手，或是一只脚，进入永生，强如有两手两脚被丢在永火里。","notes":[]},{"n":9,"t":"倘若你一只眼叫你跌倒，就把它剜出来丢掉。你只有一只眼进入永生，强如有两只眼被丢在地狱的火里。」","notes":[]},{"n":10,"t":"「你们要小心，不可轻看这小子里的一个；我告诉你们，他们的使者在天上，常见我天父的面。","notes":["有古卷加：11人子来，为要拯救失丧的人。"],"heads":["迷羊的比喻"]},{"n":12,"t":"一个人若有一百只羊，一只走迷了路，你们的意思如何？他岂不撇下这九十九只，往山里去找那只迷路的羊吗？","notes":[]},{"n":13,"t":"若是找着了，我实在告诉你们，他为这一只羊欢喜，比为那没有迷路的九十九只欢喜还大呢！","notes":[]},{"n":14,"t":"你们在天上的父也是这样，不愿意这小子里失丧一个。」","notes":[]},{"n":15,"t":"「倘若你的弟兄得罪你，你就去，趁着只有他和你在一处的时候，指出他的错来。他若听你，你便得了你的弟兄；","notes":[],"heads":["如何对待犯过错的弟兄"]},{"n":16,"t":"他若不听，你就另外带一两个人同去，要凭两三个人的口作见证，句句都可定准。","notes":[]},{"n":17,"t":"若是不听他们，就告诉教会；若是不听教会，就看他像外邦人和税吏一样。","notes":[]},{"n":18,"t":"「我实在告诉你们，凡你们在地上所捆绑的，在天上也要捆绑；凡你们在地上所释放的，在天上也要释放。","notes":[]},{"n":19,"t":"我又告诉你们，若是你们中间有两个人在地上同心合意地求什么事，我在天上的父必为他们成全。","notes":[]},{"n":20,"t":"因为无论在哪里，有两三个人奉我的名聚会，那里就有我在他们中间。」","notes":[]},{"n":21,"t":"那时，彼得进前来，对耶稣说：「主啊，我弟兄得罪我，我当饶恕他几次呢？到七次可以吗？」","notes":[],"heads":["不饶恕人的恶仆"]},{"n":22,"t":"耶稣说：「我对你说，不是到七次，乃是到七十个七次。","notes":[]},{"n":23,"t":"天国好像一个王要和他仆人算帐。","notes":[]},{"n":24,"t":"才算的时候，有人带了一个欠一千万银子的来。","notes":[]},{"n":25,"t":"因为他没有什么偿还之物，主人吩咐把他和他妻子儿女，并一切所有的都卖了偿还。","notes":[]},{"n":26,"t":"那仆人就俯伏拜他，说：『主啊，宽容我，将来我都要还清。』","notes":[]},{"n":27,"t":"那仆人的主人就动了慈心，把他释放了，并且免了他的债。","notes":[]},{"n":28,"t":"「那仆人出来，遇见他的一个同伴欠他十两银子，便揪着他，掐住他的喉咙，说：『你把所欠的还我！』","notes":[]},{"n":29,"t":"他的同伴就俯伏央求他，说：『宽容我吧，将来我必还清。』","notes":[]},{"n":30,"t":"他不肯，竟去把他下在监里，等他还了所欠的债。","notes":[]},{"n":31,"t":"众同伴看见他所做的事就甚忧愁，去把这事都告诉了主人。","notes":[]},{"n":32,"t":"于是主人叫了他来，对他说：『你这恶奴才！你央求我，我就把你所欠的都免了，","notes":[]},{"n":33,"t":"你不应当怜恤你的同伴，像我怜恤你吗？』","notes":[]},{"n":34,"t":"主人就大怒，把他交给掌刑的，等他还清了所欠的债。","notes":[]},{"n":35,"t":"你们各人若不从心里饶恕你的弟兄，我天父也要这样待你们了。」","notes":[]}]},"19":{"heading":"休妻的问题","verses":[{"n":1,"t":"耶稣说完了这些话，就离开加利利，来到犹太的境界约旦河外。","notes":[]},{"n":2,"t":"有许多人跟着他，他就在那里把他们的病人治好了。","notes":[]},{"n":3,"t":"有法利赛人来试探耶稣，说：「人无论什么缘故都可以休妻吗？」","notes":[]},{"n":4,"t":"耶稣回答说：「那起初造人的，是造男造女，","notes":[]},{"n":5,"t":"并且说：『因此，人要离开父母，与妻子连合，二人成为一体。』这经你们没有念过吗？","notes":[]},{"n":6,"t":"既然如此，夫妻不再是两个人，乃是一体的了。所以，神配合的，人不可分开。」","notes":[]},{"n":7,"t":"法利赛人说：「这样，摩西为什么吩咐给妻子休书，就可以休她呢？」","notes":[]},{"n":8,"t":"耶稣说：「摩西因为你们的心硬，所以许你们休妻，但起初并不是这样。","notes":[]},{"n":9,"t":"我告诉你们，凡休妻另娶的，若不是为淫乱的缘故，就是犯奸淫了；有人娶那被休的妇人，也是犯奸淫了。」","notes":[]},{"n":10,"t":"门徒对耶稣说：「人和妻子既是这样，倒不如不娶。」","notes":[]},{"n":11,"t":"耶稣说：「这话不是人都能领受的，惟独赐给谁，谁才能领受。","notes":[]},{"n":12,"t":"因为有生来是阉人，也有被人阉的，并有为天国的缘故自阉的。这话谁能领受就可以领受。」","notes":[]},{"n":13,"t":"那时，有人带着小孩子来见耶稣，要耶稣给他们按手祷告，门徒就责备那些人。","notes":[],"heads":["耶稣为小孩祝福"]},{"n":14,"t":"耶稣说：「让小孩子到我这里来，不要禁止他们；因为在天国的，正是这样的人。」","notes":[]},{"n":15,"t":"耶稣给他们按手，就离开那地方去了。","notes":[]},{"n":16,"t":"有一个人来见耶稣，说：「夫子，我该做什么善事才能得永生？」","notes":["有古卷：良善的夫子"],"heads":["少年财主"]},{"n":17,"t":"耶稣对他说：「你为什么以善事问我呢？只有一位是善的。你若要进入永生，就当遵守诫命。」","notes":["有古卷：你为什么称我是良善的？除了神以外，没有一个良善的"]},{"n":18,"t":"他说：「什么诫命？」耶稣说：「就是不可杀人；不可奸淫；不可偷盗；不可作假见证；","notes":[]},{"n":19,"t":"当孝敬父母；又当爱人如己。」","notes":[]},{"n":20,"t":"那少年人说：「这一切我都遵守了，还缺少什么呢？」","notes":[]},{"n":21,"t":"耶稣说：「你若愿意作完全人，可去变卖你所有的，分给穷人，就必有财宝在天上；你还要来跟从我。」","notes":[]},{"n":22,"t":"那少年人听见这话，就忧忧愁愁地走了，因为他的产业很多。","notes":[]},{"n":23,"t":"耶稣对门徒说：「我实在告诉你们，财主进天国是难的。","notes":[]},{"n":24,"t":"我又告诉你们，骆驼穿过针的眼，比财主进神的国还容易呢！」","notes":[]},{"n":25,"t":"门徒听见这话，就希奇得很，说：「这样谁能得救呢？」","notes":[]},{"n":26,"t":"耶稣看着他们，说：「在人这是不能的，在神凡事都能。」","notes":[]},{"n":27,"t":"彼得就对他说：「看哪，我们已经撇下所有的跟从你，将来我们要得什么呢？」","notes":[]},{"n":28,"t":"耶稣说：「我实在告诉你们，你们这跟从我的人，到复兴的时候，人子坐在他荣耀的宝座上，你们也要坐在十二个宝座上，审判以色列十二个支派。","notes":[]},{"n":29,"t":"凡为我的名撇下房屋，或是弟兄、姊妹、父亲、母亲、 儿女、田地的，必要得着百倍，并且承受永生。","notes":["有古卷加：妻子、"]},{"n":30,"t":"然而，有许多在前的，将要在后；在后的，将要在前。」","notes":[]}]},"20":{"heading":"葡萄园的比喻","verses":[{"n":1,"t":"「因为天国好像家主清早去雇人进他的葡萄园做工，","notes":[]},{"n":2,"t":"和工人讲定一天一钱银子，就打发他们进葡萄园去。","notes":[]},{"n":3,"t":"约在巳初出去，看见市上还有闲站的人，","notes":[]},{"n":4,"t":"就对他们说：『你们也进葡萄园去，所当给的，我必给你们。』他们也进去了。","notes":[]},{"n":5,"t":"约在午正和申初又出去，也是这样行。","notes":[]},{"n":6,"t":"约在酉初出去，看见还有人站在那里，就问他们说：『你们为什么整天在这里闲站呢？』","notes":[]},{"n":7,"t":"他们说：『因为没有人雇我们。』他说：『你们也进葡萄园去。』","notes":[]},{"n":8,"t":"到了晚上，园主对管事的说：『叫工人都来，给他们工钱，从后来的起，到先来的为止。","notes":[]},{"n":9,"t":"约在酉初雇的人来了，各人得了一钱银子。","notes":[]},{"n":10,"t":"及至那先雇的来了，他们以为必要多得；谁知也是各得一钱。","notes":[]},{"n":11,"t":"他们得了，就埋怨家主说：","notes":[]},{"n":12,"t":"『我们整天劳苦受热，那后来的只做了一小时，你竟叫他们和我们一样吗？』","notes":[]},{"n":13,"t":"家主回答其中的一人说：『朋友，我不亏负你，你与我讲定的不是一钱银子吗？","notes":[]},{"n":14,"t":"拿你的走吧！我给那后来的和给你一样，这是我愿意的。","notes":[]},{"n":15,"t":"我的东西难道不可随我的意思用吗？因为我作好人，你就红了眼吗？』","notes":[]},{"n":16,"t":"这样，那在后的，将要在前；在前的，将要在后了。」","notes":["有古卷加：因为被召的人多，选上的人少。"]},{"n":17,"t":"耶稣上耶路撒冷去的时候，在路上把十二个门徒带到一边，对他们说：","notes":[],"heads":["耶稣第三次预言受难和复活"]},{"n":18,"t":"「看哪，我们上耶路撒冷去，人子要被交给祭司长和文士。他们要定他死罪，","notes":[]},{"n":19,"t":"又交给外邦人，将他戏弄，鞭打，钉在十字架上；第三日他要复活。」","notes":[]},{"n":20,"t":"那时，西庇太儿子的母亲同她两个儿子上前来拜耶稣，求他一件事。","notes":[],"heads":["母亲的请求"]},{"n":21,"t":"耶稣说：「你要什么呢？」她说：「愿你叫我这两个儿子在你国里，一个坐在你右边，一个坐在你左边。」","notes":[]},{"n":22,"t":"耶稣回答说：「你们不知道所求的是什么；我将要喝的杯，你们能喝吗？」他们说：「我们能。」","notes":[]},{"n":23,"t":"耶稣说：「我所喝的杯，你们必要喝；只是坐在我的左右，不是我可以赐的，乃是我父为谁预备的，就赐给谁。」","notes":[]},{"n":24,"t":"那十个门徒听见，就恼怒他们弟兄二人。","notes":[]},{"n":25,"t":"耶稣叫了他们来，说：「你们知道外邦人有君王为主治理他们，有大臣操权管束他们。","notes":[]},{"n":26,"t":"只是在你们中间，不可这样；你们中间谁愿为大，就必作你们的用人；","notes":[]},{"n":27,"t":"谁愿为首，就必作你们的仆人。","notes":[]},{"n":28,"t":"正如人子来，不是要受人的服事，乃是要服事人，并且要舍命，作多人的赎价。」","notes":[]},{"n":29,"t":"他们出耶利哥的时候，有极多的人跟随他。","notes":[],"heads":["治好两个瞎子"]},{"n":30,"t":"有两个瞎子坐在路旁，听说是耶稣经过，就喊着说：「主啊，大卫的子孙，可怜我们吧！」","notes":[]},{"n":31,"t":"众人责备他们，不许他们作声；他们却越发喊着说：「主啊，大卫的子孙，可怜我们吧！」","notes":[]},{"n":32,"t":"耶稣就站住，叫他们来，说：「要我为你们做什么？」","notes":[]},{"n":33,"t":"他们说：「主啊，要我们的眼睛能看见！」","notes":[]},{"n":34,"t":"耶稣就动了慈心，把他们的眼睛一摸，他们立刻看见，就跟从了耶稣。","notes":[]}]},"21":{"heading":"光荣地进耶路撒冷","verses":[{"n":1,"t":"耶稣和门徒将近耶路撒冷，到了伯法其，在橄榄山那里。","notes":[]},{"n":2,"t":"耶稣就打发两个门徒，对他们说：「你们往对面村子里去，必看见一匹驴拴在那里，还有驴驹同在一处；你们解开，牵到我这里来。","notes":[]},{"n":3,"t":"若有人对你们说什么，你们就说：『主要用它。』那人必立时让你们牵来。","notes":[]},{"n":4,"t":"这事成就是要应验先知的话，说：","notes":[]},{"n":5,"t":"要对锡安的居民说：看哪，你的王来到你这里，是温柔的，又骑着驴，就是骑着驴驹子。」","notes":["原文是女子"]},{"n":6,"t":"门徒就照耶稣所吩咐的去行，","notes":[]},{"n":7,"t":"牵了驴和驴驹来，把自己的衣服搭在上面，耶稣就骑上。","notes":[]},{"n":8,"t":"众人多半把衣服铺在路上；还有人砍下树枝来铺在路上。","notes":[]},{"n":9,"t":"前行后随的众人喊着说：和散那归于大卫的子孙！奉主名来的是应当称颂的！高高在上和散那！","notes":["原有求救的意思，在此是称颂的话"]},{"n":10,"t":"耶稣既进了耶路撒冷，合城都惊动了，说：「这是谁？」","notes":[]},{"n":11,"t":"众人说：「这是加利利拿撒勒的先知耶稣。」","notes":[]},{"n":12,"t":"耶稣进了神的殿，赶出殿里一切做买卖的人，推倒兑换银钱之人的桌子，和卖鸽子之人的凳子，","notes":[],"heads":["洁净圣殿"]},{"n":13,"t":"对他们说：「经上记着说：我的殿必称为祷告的殿，你们倒使它成为贼窝了。」","notes":[]},{"n":14,"t":"在殿里有瞎子、瘸子到耶稣跟前，他就治好了他们。","notes":[]},{"n":15,"t":"祭司长和文士看见耶稣所行的奇事，又见小孩子在殿里喊着说：「和散那归于大卫的子孙！」就甚恼怒，","notes":[]},{"n":16,"t":"对他说：「这些人所说的，你听见了吗？」耶稣说：「是的。经上说『你从婴孩和吃奶的口中完全了赞美』的话，你们没有念过吗？」","notes":[]},{"n":17,"t":"于是离开他们，出城到伯大尼去，在那里住宿。","notes":[]},{"n":18,"t":"早晨回城的时候，他饿了，","notes":[],"heads":["咒诅无花果树"]},{"n":19,"t":"看见路旁有一棵无花果树，就走到跟前，在树上找不着什么，不过有叶子，就对树说：「从今以后，你永不结果子。」那无花果树就立刻枯干了。","notes":[]},{"n":20,"t":"门徒看见了，便希奇说：「无花果树怎么立刻枯干了呢？」","notes":[]},{"n":21,"t":"耶稣回答说：「我实在告诉你们，你们若有信心，不疑惑，不但能行无花果树上所行的事，就是对这座山说：『你挪开此地，投在海里！』也必成就。","notes":[]},{"n":22,"t":"你们祷告，无论求什么，只要信，就必得着。」","notes":[]},{"n":23,"t":"耶稣进了殿，正教训人的时候，祭司长和民间的长老来问他说：「你仗着什么权柄做这些事？给你这权柄的是谁呢？」","notes":[],"heads":["质问耶稣的权柄"]},{"n":24,"t":"耶稣回答说：「我也要问你们一句话，你们若告诉我，我就告诉你们我仗着什么权柄做这些事。","notes":[]},{"n":25,"t":"约翰的洗礼是从哪里来的？是从天上来的？是从人间来的呢？」他们彼此商议说：「我们若说『从天上来』，他必对我们说：『这样，你们为什么不信他呢？』","notes":[]},{"n":26,"t":"若说『从人间来』，我们又怕百姓，因为他们都以约翰为先知。」","notes":[]},{"n":27,"t":"于是回答耶稣说：「我们不知道。」耶稣说：「我也不告诉你们我仗着什么权柄做这些事。」","notes":[]},{"n":28,"t":"又说：「一个人有两个儿子。他来对大儿子说：『我儿，你今天到葡萄园里去做工。』","notes":[],"heads":["两个儿子的比喻"]},{"n":29,"t":"他回答说：『我不去』，以后自己懊悔，就去了。","notes":[]},{"n":30,"t":"又来对小儿子也是这样说。他回答说：『父啊，我去』，他却不去。","notes":[]},{"n":31,"t":"你们想，这两个儿子是哪一个遵行父命呢？」他们说：「大儿子。」耶稣说：「我实在告诉你们，税吏和娼妓倒比你们先进神的国。","notes":[]},{"n":32,"t":"因为约翰遵着义路到你们这里来，你们却不信他；税吏和娼妓倒信他。你们看见了，后来还是不懊悔去信他。」","notes":[]},{"n":33,"t":"「你们再听一个比喻：有个家主栽了一个葡萄园，周围圈上篱笆，里面挖了一个压酒池，盖了一座楼，租给园户，就往外国去了。","notes":[],"heads":["凶恶园户的比喻"]},{"n":34,"t":"收果子的时候近了，就打发仆人到园户那里去收果子。","notes":[]},{"n":35,"t":"园户拿住仆人，打了一个，杀了一个，用石头打死一个。","notes":[]},{"n":36,"t":"主人又打发别的仆人去，比先前更多；园户还是照样待他们。","notes":[]},{"n":37,"t":"后来打发他的儿子到他们那里去，意思说：『他们必尊敬我的儿子。』","notes":[]},{"n":38,"t":"不料，园户看见他儿子，就彼此说：『这是承受产业的。来吧，我们杀他，占他的产业！』","notes":[]},{"n":39,"t":"他们就拿住他，推出葡萄园外，杀了。","notes":[]},{"n":40,"t":"园主来的时候要怎样处治这些园户呢？」","notes":[]},{"n":41,"t":"他们说：「要下毒手除灭那些恶人，将葡萄园另租给那按着时候交果子的园户。」","notes":[]},{"n":42,"t":"耶稣说：「经上写着：匠人所弃的石头已作了房角的头块石头。这是主所做的，在我们眼中看为希奇。这经你们没有念过吗？","notes":[]},{"n":43,"t":"所以我告诉你们，神的国必从你们夺去，赐给那能结果子的百姓。","notes":[]},{"n":44,"t":"谁掉在这石头上，必要跌碎；这石头掉在谁的身上，就要把谁砸得稀烂。」","notes":[]},{"n":45,"t":"祭司长和法利赛人听见他的比喻，就看出他是指着他们说的。","notes":[]},{"n":46,"t":"他们想要捉拿他，只是怕众人，因为众人以他为先知。","notes":[]}]},"22":{"heading":"喜筵的比喻","verses":[{"n":1,"t":"耶稣又用比喻对他们说：","notes":[]},{"n":2,"t":"「天国好比一个王为他儿子摆设娶亲的筵席，","notes":[]},{"n":3,"t":"就打发仆人去，请那些被召的人来赴席，他们却不肯来。","notes":[]},{"n":4,"t":"王又打发别的仆人，说：『你们告诉那被召的人，我的筵席已经预备好了，牛和肥畜已经宰了，各样都齐备，请你们来赴席。』","notes":[]},{"n":5,"t":"那些人不理就走了；一个到自己田里去；一个做买卖去；","notes":[]},{"n":6,"t":"其余的拿住仆人，凌辱他们，把他们杀了。","notes":[]},{"n":7,"t":"王就大怒，发兵除灭那些凶手，烧毁他们的城。","notes":[]},{"n":8,"t":"于是对仆人说：『喜筵已经齐备，只是所召的人不配。","notes":[]},{"n":9,"t":"所以你们要往岔路口上去，凡遇见的，都召来赴席。』","notes":[]},{"n":10,"t":"那些仆人就出去，到大路上，凡遇见的，不论善恶都召聚了来，筵席上就坐满了客。","notes":[]},{"n":11,"t":"王进来观看宾客，见那里有一个没有穿礼服的，","notes":[]},{"n":12,"t":"就对他说：『朋友，你到这里来怎么不穿礼服呢？』那人无言可答。","notes":[]},{"n":13,"t":"于是王对使唤的人说：『捆起他的手脚来，把他丢在外边的黑暗里；在那里必要哀哭切齿了。』","notes":[]},{"n":14,"t":"因为被召的人多，选上的人少。」","notes":[]},{"n":15,"t":"当时，法利赛人出去商议，怎样就着耶稣的话陷害他，","notes":[],"heads":["纳税给凯撒的问题"]},{"n":16,"t":"就打发他们的门徒同希律党的人去见耶稣，说：「夫子，我们知道你是诚实人，并且诚诚实实传神的道，什么人你都不徇情面，因为你不看人的外貌。","notes":[]},{"n":17,"t":"请告诉我们，你的意见如何？纳税给凯撒可以不可以？」","notes":[]},{"n":18,"t":"耶稣看出他们的恶意，就说：「假冒为善的人哪，为什么试探我？","notes":[]},{"n":19,"t":"拿一个上税的钱给我看！」他们就拿一个银钱来给他。","notes":[]},{"n":20,"t":"耶稣说：「这像和这号是谁的？」","notes":[]},{"n":21,"t":"他们说：「是凯撒的。」耶稣说：「这样，凯撒的物当归给凯撒；神的物当归给神。」","notes":[]},{"n":22,"t":"他们听见就希奇，离开他走了。","notes":[]},{"n":23,"t":"撒都该人常说没有复活的事。那天，他们来问耶稣说：","notes":[],"heads":["复活的问题"]},{"n":24,"t":"「夫子，摩西说：『人若死了，没有孩子，他兄弟当娶他的妻，为哥哥生子立后。』","notes":[]},{"n":25,"t":"从前，在我们这里有弟兄七人，第一个娶了妻，死了，没有孩子，撇下妻子给兄弟。","notes":[]},{"n":26,"t":"第二、第三，直到第七个，都是如此。","notes":[]},{"n":27,"t":"末后，妇人也死了。","notes":[]},{"n":28,"t":"这样，当复活的时候，她是七个人中哪一个的妻子呢？因为他们都娶过她。」","notes":[]},{"n":29,"t":"耶稣回答说：「你们错了；因为不明白圣经，也不晓得神的大能。","notes":[]},{"n":30,"t":"当复活的时候，人也不娶也不嫁，乃像天上的使者一样。","notes":[]},{"n":31,"t":"论到死人复活，神在经上向你们所说的，你们没有念过吗？","notes":[]},{"n":32,"t":"他说：『我是亚伯拉罕的神，以撒的神，雅各的神。』神不是死人的神，乃是活人的神。」","notes":[]},{"n":33,"t":"众人听见这话，就希奇他的教训。","notes":[]},{"n":34,"t":"法利赛人听见耶稣堵住了撒都该人的口，他们就聚集。","notes":[],"heads":["最大的诫命"]},{"n":35,"t":"内中有一个人是律法师，要试探耶稣，就问他说：","notes":[]},{"n":36,"t":"「夫子，律法上的诫命，哪一条是最大的呢？」","notes":[]},{"n":37,"t":"耶稣对他说：「你要尽心、尽性、尽意爱主—你的神。","notes":[]},{"n":38,"t":"这是诫命中的第一，且是最大的。","notes":[]},{"n":39,"t":"其次也相仿，就是要爱人如己。","notes":[]},{"n":40,"t":"这两条诫命是律法和先知一切道理的总纲。」","notes":[]},{"n":41,"t":"法利赛人聚集的时候，耶稣问他们说：","notes":[],"heads":["大卫子孙的问题"]},{"n":42,"t":"「论到基督，你们的意见如何？他是谁的子孙呢？」他们回答说：「是大卫的子孙。」","notes":[]},{"n":43,"t":"耶稣说：「这样，大卫被圣灵感动，怎么还称他为主，说：","notes":[]},{"n":44,"t":"主对我主说：你坐在我的右边，等我把你仇敌放在你的脚下。","notes":[]},{"n":45,"t":"大卫既称他为主，他怎么又是大卫的子孙呢？」","notes":[]},{"n":46,"t":"他们没有一个人能回答一言。从那日以后，也没有人敢再问他什么。","notes":[]}]},"23":{"heading":"谴责文士和法利赛人","verses":[{"n":1,"t":"那时，耶稣对众人和门徒讲论，","notes":[]},{"n":2,"t":"说：「文士和法利赛人坐在摩西的位上，","notes":[]},{"n":3,"t":"凡他们所吩咐你们的，你们都要谨守遵行。但不要效法他们的行为；因为他们能说，不能行。","notes":[]},{"n":4,"t":"他们把难担的重担捆起来，搁在人的肩上，但自己一个指头也不肯动。","notes":[]},{"n":5,"t":"他们一切所做的事都是要叫人看见，所以将佩戴的经文做宽了，衣裳的繸子做长了，","notes":[]},{"n":6,"t":"喜爱筵席上的首座，会堂里的高位，","notes":[]},{"n":7,"t":"又喜爱人在街市上问他安，称呼他拉比。","notes":["拉比就是夫子"]},{"n":8,"t":"但你们不要受拉比的称呼，因为只有一位是你们的夫子；你们都是弟兄。","notes":[]},{"n":9,"t":"也不要称呼地上的人为父，因为只有一位是你们的父，就是在天上的父。","notes":[]},{"n":10,"t":"也不要受师尊的称呼，因为只有一位是你们的师尊，就是基督。","notes":[]},{"n":11,"t":"你们中间谁为大，谁就要作你们的用人。","notes":[]},{"n":12,"t":"凡自高的，必降为卑；自卑的，必升为高。","notes":[]},{"n":13,"t":"「你们这假冒为善的文士和法利赛人有祸了！因为你们正当人前，把天国的门关了，自己不进去，正要进去的人，你们也不容他们进去。","notes":["有古卷加： 14你们这假冒为善的文士和法利赛人有祸了！因为你们侵吞寡妇的家产，假意做很长的祷告，所以要受更重的刑罚。"]},{"n":15,"t":"「你们这假冒为善的文士和法利赛人有祸了！因为你们走遍洋海陆地，勾引一个人入教，既入了教，却使他作地狱之子，比你们还加倍。","notes":[]},{"n":16,"t":"「你们这瞎眼领路的有祸了！你们说：『凡指着殿起誓的，这算不得什么；只是凡指着殿中金子起誓的，他就该谨守。』","notes":[]},{"n":17,"t":"你们这无知瞎眼的人哪，什么是大的？是金子呢？还是叫金子成圣的殿呢？","notes":[]},{"n":18,"t":"你们又说：『凡指着坛起誓的，这算不得什么；只是凡指着坛上礼物起誓的，他就该谨守。』","notes":[]},{"n":19,"t":"你们这瞎眼的人哪，什么是大的？是礼物呢？还是叫礼物成圣的坛呢？","notes":[]},{"n":20,"t":"所以，人指着坛起誓，就是指着坛和坛上一切所有的起誓；","notes":[]},{"n":21,"t":"人指着殿起誓，就是指着殿和那住在殿里的起誓；","notes":[]},{"n":22,"t":"人指着天起誓，就是指着神的宝座和那坐在上面的起誓。","notes":[]},{"n":23,"t":"「你们这假冒为善的文士和法利赛人有祸了！因为你们将薄荷、茴香、芹菜献上十分之一，那律法上更重的事，就是公义、怜悯、信实，反倒不行了。这更重的是你们当行的；那也是不可不行的。","notes":[]},{"n":24,"t":"你们这瞎眼领路的，蠓虫你们就滤出来，骆驼你们倒吞下去。","notes":[]},{"n":25,"t":"「你们这假冒为善的文士和法利赛人有祸了！因为你们洗净杯盘的外面，里面却盛满了勒索和放荡。","notes":[]},{"n":26,"t":"你这瞎眼的法利赛人，先洗净杯盘的里面，好叫外面也干净了。","notes":[]},{"n":27,"t":"「你们这假冒为善的文士和法利赛人有祸了！因为你们好像粉饰的坟墓，外面好看，里面却装满了死人的骨头和一切的污秽。","notes":[]},{"n":28,"t":"你们也是如此，在人前，外面显出公义来，里面却装满了假善和不法的事。","notes":[]},{"n":29,"t":"「你们这假冒为善的文士和法利赛人有祸了！因为你们建造先知的坟，修饰义人的墓，说：","notes":[]},{"n":30,"t":"『若是我们在我们祖宗的时候，必不和他们同流先知的血。』","notes":[]},{"n":31,"t":"这就是你们自己证明是杀害先知者的子孙了。","notes":[]},{"n":32,"t":"你们去充满你们祖宗的恶贯吧！","notes":[]},{"n":33,"t":"你们这些蛇类、毒蛇之种啊，怎能逃脱地狱的刑罚呢？","notes":[]},{"n":34,"t":"所以我差遣先知和智慧人并文士到你们这里来，有的你们要杀害，要钉十字架；有的你们要在会堂里鞭打，从这城追逼到那城，","notes":[]},{"n":35,"t":"叫世上所流义人的血都归到你们身上，从义人亚伯的血起，直到你们在殿和坛中间所杀的巴拉加的儿子撒迦利亚的血为止。","notes":[]},{"n":36,"t":"我实在告诉你们，这一切的罪都要归到这世代了。」","notes":[]},{"n":37,"t":"「耶路撒冷啊，耶路撒冷啊，你常杀害先知，又用石头打死那奉差遣到你这里来的人。我多次愿意聚集你的儿女，好像母鸡把小鸡聚集在翅膀底下，只是你们不愿意。","notes":[],"heads":["为耶路撒冷哀哭"]},{"n":38,"t":"看哪，你们的家成为荒场留给你们。","notes":[]},{"n":39,"t":"我告诉你们，从今以后，你们不得再见我，直等到你们说：『奉主名来的是应当称颂的。』」","notes":[]}]},"24":{"heading":"预言圣殿被毁","verses":[{"n":1,"t":"耶稣出了圣殿，正走的时候，门徒进前来，把殿宇指给他看。","notes":[]},{"n":2,"t":"耶稣对他们说：「你们不是看见这殿宇吗？我实在告诉你们，将来在这里没有一块石头留在石头上，不被拆毁了。」","notes":[]},{"n":3,"t":"耶稣在橄榄山上坐着，门徒暗暗地来说：「请告诉我们，什么时候有这些事？你降临和世界的末了有什么预兆呢？」","notes":[],"heads":["灾难的起头"]},{"n":4,"t":"耶稣回答说：「你们要谨慎，免得有人迷惑你们。","notes":[]},{"n":5,"t":"因为将来有好些人冒我的名来，说：『我是基督』，并且要迷惑许多人。","notes":[]},{"n":6,"t":"你们也要听见打仗和打仗的风声，总不要惊慌；因为这些事是必须有的，只是末期还没有到。","notes":[]},{"n":7,"t":"民要攻打民，国要攻打国；多处必有饥荒、地震。","notes":[]},{"n":8,"t":"这都是灾难的起头。","notes":["灾难：原文是生产之难"]},{"n":9,"t":"那时，人要把你们陷在患难里，也要杀害你们；你们又要为我的名被万民恨恶。","notes":[]},{"n":10,"t":"那时，必有许多人跌倒，也要彼此陷害，彼此恨恶；","notes":[]},{"n":11,"t":"且有好些假先知起来，迷惑多人。","notes":[]},{"n":12,"t":"只因不法的事增多，许多人的爱心才渐渐冷淡了。","notes":[]},{"n":13,"t":"惟有忍耐到底的，必然得救。","notes":[]},{"n":14,"t":"这天国的福音要传遍天下，对万民作见证，然后末期才来到。」","notes":[]},{"n":15,"t":"「你们看见先知但以理所说的『那行毁坏可憎的』站在圣地（读这经的人须要会意）。","notes":[],"heads":["大灾难"]},{"n":16,"t":"那时，在犹太的，应当逃到山上；","notes":[]},{"n":17,"t":"在房上的，不要下来拿家里的东西；","notes":[]},{"n":18,"t":"在田里的，也不要回去取衣裳。","notes":[]},{"n":19,"t":"当那些日子，怀孕的和奶孩子的有祸了。","notes":[]},{"n":20,"t":"你们应当祈求，叫你们逃走的时候，不遇见冬天或是安息日。","notes":[]},{"n":21,"t":"因为那时必有大灾难，从世界的起头直到如今，没有这样的灾难，后来也必没有。","notes":[]},{"n":22,"t":"若不减少那日子，凡有血气的总没有一个得救的；只是为选民，那日子必减少了。","notes":[]},{"n":23,"t":"那时，若有人对你们说：『基督在这里』，或说：『基督在那里』，你们不要信！","notes":[]},{"n":24,"t":"因为假基督、假先知将要起来，显大神迹、大奇事，倘若能行，连选民也就迷惑了。","notes":[]},{"n":25,"t":"看哪，我预先告诉你们了。","notes":[]},{"n":26,"t":"若有人对你们说：『看哪，基督在旷野里』，你们不要出去！或说：『看哪，基督在内屋中』，你们不要信！","notes":[]},{"n":27,"t":"闪电从东边发出，直照到西边。人子降临也要这样。","notes":[]},{"n":28,"t":"尸首在哪里，鹰也必聚在那里。」","notes":[]},{"n":29,"t":"「那些日子的灾难一过去，日头就变黑了，月亮也不放光，众星要从天上坠落，天势都要震动。","notes":[],"heads":["人子的降临"]},{"n":30,"t":"那时，人子的兆头要显在天上，地上的万族都要哀哭。他们要看见人子，有能力，有大荣耀，驾着天上的云降临。","notes":[]},{"n":31,"t":"他要差遣使者，用号筒的大声，将他的选民，从四方，从天这边到天那边，都招聚了来。」","notes":["方：原文是风"]},{"n":32,"t":"「你们可以从无花果树学个比方：当树枝发嫩长叶的时候，你们就知道夏天近了。","notes":[],"heads":["从无花果树学个比方"]},{"n":33,"t":"这样，你们看见这一切的事，也该知道人子近了，正在门口了。","notes":[]},{"n":34,"t":"我实在告诉你们，这世代还没有过去，这些事都要成就。","notes":[]},{"n":35,"t":"天地要废去，我的话却不能废去。」","notes":[]},{"n":36,"t":"「但那日子，那时辰，没有人知道，连天上的使者也不知道，子也不知道，惟独父知道。","notes":[],"heads":["那日那时没有人知道"]},{"n":37,"t":"挪亚的日子怎样，人子降临也要怎样。","notes":[]},{"n":38,"t":"当洪水以前的日子，人照常吃喝嫁娶，直到挪亚进方舟的那日；","notes":[]},{"n":39,"t":"不知不觉洪水来了，把他们全都冲去。人子降临也要这样。","notes":[]},{"n":40,"t":"那时，两个人在田里，取去一个，撇下一个。","notes":[]},{"n":41,"t":"两个女人推磨，取去一个，撇下一个。","notes":[]},{"n":42,"t":"所以，你们要警醒，因为不知道你们的主是哪一天来到。","notes":[]},{"n":43,"t":"家主若知道几更天有贼来，就必警醒，不容人挖透房屋；这是你们所知道的。","notes":[]},{"n":44,"t":"所以，你们也要预备，因为你们想不到的时候，人子就来了。」","notes":[]},{"n":45,"t":"「谁是忠心有见识的仆人，为主人所派，管理家里的人，按时分粮给他们呢？","notes":[],"heads":["忠心和不忠心的仆人"]},{"n":46,"t":"主人来到，看见他这样行，那仆人就有福了。","notes":[]},{"n":47,"t":"我实在告诉你们，主人要派他管理一切所有的。","notes":[]},{"n":48,"t":"倘若那恶仆心里说：『我的主人必来得迟』，","notes":[]},{"n":49,"t":"就动手打他的同伴，又和酒醉的人一同吃喝。","notes":[]},{"n":50,"t":"在想不到的日子，不知道的时辰，那仆人的主人要来，","notes":[]},{"n":51,"t":"重重地处治他，定他和假冒为善的人同罪；在那里必要哀哭切齿了。」","notes":["或译：把他腰斩了"]}]},"25":{"heading":"十童女的比喻","verses":[{"n":1,"t":"「那时，天国好比十个童女拿着灯出去迎接新郎。","notes":[]},{"n":2,"t":"其中有五个是愚拙的，五个是聪明的。","notes":[]},{"n":3,"t":"愚拙的拿着灯，却不预备油；","notes":[]},{"n":4,"t":"聪明的拿着灯，又预备油在器皿里。","notes":[]},{"n":5,"t":"新郎迟延的时候，她们都打盹，睡着了。","notes":[]},{"n":6,"t":"半夜有人喊着说：『新郎来了，你们出来迎接他！』","notes":[]},{"n":7,"t":"那些童女就都起来收拾灯。","notes":[]},{"n":8,"t":"愚拙的对聪明的说：『请分点油给我们，因为我们的灯要灭了。』","notes":[]},{"n":9,"t":"聪明的回答说：『恐怕不够你我用的；不如你们自己到卖油的那里去买吧。』","notes":[]},{"n":10,"t":"她们去买的时候，新郎到了。那预备好了的，同他进去坐席，门就关了。","notes":[]},{"n":11,"t":"其余的童女随后也来了，说：『主啊，主啊，给我们开门！』","notes":[]},{"n":12,"t":"他却回答说：『我实在告诉你们，我不认识你们。』","notes":[]},{"n":13,"t":"所以，你们要警醒；因为那日子，那时辰，你们不知道。」","notes":[]},{"n":14,"t":"「天国又好比一个人要往外国去，就叫了仆人来，把他的家业交给他们，","notes":[],"heads":["按才干接受托付的比喻"]},{"n":15,"t":"按着各人的才干给他们银子：一个给了五千，一个给了二千，一个给了一千，就往外国去了。","notes":[]},{"n":16,"t":"那领五千的随即拿去做买卖，另外赚了五千。","notes":[]},{"n":17,"t":"那领二千的也照样另赚了二千。","notes":[]},{"n":18,"t":"但那领一千的去掘开地，把主人的银子埋藏了。","notes":[]},{"n":19,"t":"过了许久，那些仆人的主人来了，和他们算帐。","notes":[]},{"n":20,"t":"那领五千银子的又带着那另外的五千来，说：『主啊，你交给我五千银子。请看，我又赚了五千。』","notes":[]},{"n":21,"t":"主人说：『好，你这又良善又忠心的仆人，你在不多的事上有忠心，我要把许多事派你管理；可以进来享受你主人的快乐。』","notes":[]},{"n":22,"t":"那领二千的也来，说：『主啊，你交给我二千银子。请看，我又赚了二千。』","notes":[]},{"n":23,"t":"主人说：『好，你这又良善又忠心的仆人，你在不多的事上有忠心，我要把许多事派你管理；可以进来享受你主人的快乐。』","notes":[]},{"n":24,"t":"那领一千的也来，说：『主啊，我知道你是忍心的人，没有种的地方要收割，没有散的地方要聚敛，","notes":[]},{"n":25,"t":"我就害怕，去把你的一千银子埋藏在地里。请看，你的原银子在这里。』","notes":[]},{"n":26,"t":"主人回答说：『你这又恶又懒的仆人，你既知道我没有种的地方要收割，没有散的地方要聚敛，","notes":[]},{"n":27,"t":"就当把我的银子放给兑换银钱的人，到我来的时候，可以连本带利收回。","notes":[]},{"n":28,"t":"夺过他这一千来，给那有一万的。","notes":[]},{"n":29,"t":"因为凡有的，还要加给他，叫他有余；没有的，连他所有的也要夺过来。","notes":[]},{"n":30,"t":"把这无用的仆人丢在外面黑暗里；在那里必要哀哭切齿了。』」","notes":[]},{"n":31,"t":"「当人子在他荣耀里、同着众天使降临的时候，要坐在他荣耀的宝座上。","notes":[],"heads":["万民受审判"]},{"n":32,"t":"万民都要聚集在他面前。他要把他们分别出来，好像牧羊的分别绵羊山羊一般，","notes":[]},{"n":33,"t":"把绵羊安置在右边，山羊在左边。","notes":[]},{"n":34,"t":"于是王要向那右边的说：『你们这蒙我父赐福的，可来承受那创世以来为你们所预备的国；","notes":[]},{"n":35,"t":"因为我饿了，你们给我吃，渴了，你们给我喝；我作客旅，你们留我住；","notes":[]},{"n":36,"t":"我赤身露体，你们给我穿；我病了，你们看顾我；我在监里，你们来看我。』","notes":[]},{"n":37,"t":"义人就回答说：『主啊，我们什么时候见你饿了，给你吃，渴了，给你喝？","notes":[]},{"n":38,"t":"什么时候见你作客旅，留你住，或是赤身露体，给你穿？","notes":[]},{"n":39,"t":"又什么时候见你病了，或是在监里，来看你呢？』","notes":[]},{"n":40,"t":"王要回答说：『我实在告诉你们，这些事你们既做在我这弟兄中一个最小的身上，就是做在我身上了。』","notes":[]},{"n":41,"t":"王又要向那左边的说：『你们这被咒诅的人，离开我！进入那为魔鬼和他的使者所预备的永火里去！","notes":[]},{"n":42,"t":"因为我饿了，你们不给我吃，渴了，你们不给我喝；","notes":[]},{"n":43,"t":"我作客旅，你们不留我住；我赤身露体，你们不给我穿；我病了，我在监里，你们不来看顾我。』","notes":[]},{"n":44,"t":"他们也要回答说：『主啊，我们什么时候见你饿了，或渴了，或作客旅，或赤身露体，或病了，或在监里，不伺候你呢？』","notes":[]},{"n":45,"t":"王要回答说：『我实在告诉你们，这些事你们既不做在我这弟兄中一个最小的身上，就是不做在我身上了。』","notes":[]},{"n":46,"t":"这些人要往永刑里去；那些义人要往永生里去。」","notes":[]}]},"26":{"heading":"杀害耶稣的阴谋","verses":[{"n":1,"t":"耶稣说完了这一切的话，就对门徒说：","notes":[]},{"n":2,"t":"「你们知道，过两天是逾越节，人子将要被交给人，钉在十字架上。」","notes":[]},{"n":3,"t":"那时，祭司长和民间的长老聚集在大祭司称为该亚法的院里。","notes":[]},{"n":4,"t":"大家商议要用诡计拿住耶稣，杀他，","notes":[]},{"n":5,"t":"只是说：「当节的日子不可，恐怕民间生乱。」","notes":[]},{"n":6,"t":"耶稣在伯大尼长大麻风的西门家里，","notes":[],"heads":["在伯大尼受膏"]},{"n":7,"t":"有一个女人拿着一玉瓶极贵的香膏来，趁耶稣坐席的时候，浇在他的头上。","notes":[]},{"n":8,"t":"门徒看见就很不喜悦，说：「何用这样的枉费呢！","notes":[]},{"n":9,"t":"这香膏可以卖许多钱，周济穷人。」","notes":[]},{"n":10,"t":"耶稣看出他们的意思，就说：「为什么难为这女人呢？她在我身上做的是一件美事。","notes":[]},{"n":11,"t":"因为常有穷人和你们同在；只是你们不常有我。","notes":[]},{"n":12,"t":"她将这香膏浇在我身上是为我安葬做的。","notes":[]},{"n":13,"t":"我实在告诉你们，普天之下，无论在什么地方传这福音，也要述说这女人所行的，作个纪念。」","notes":[]},{"n":14,"t":"当下，十二门徒里有一个称为加略人犹大的，去见祭司长，","notes":[],"heads":["犹大出卖耶稣"]},{"n":15,"t":"说：「我把他交给你们，你们愿意给我多少钱？」他们就给了他三十块钱。","notes":[]},{"n":16,"t":"从那时候，他就找机会要把耶稣交给他们。","notes":[]},{"n":17,"t":"除酵节的第一天，门徒来问耶稣说：「你吃逾越节的筵席，要我们在哪里给你预备？」","notes":[],"heads":["和门徒同度逾越节"]},{"n":18,"t":"耶稣说：「你们进城去，到某人那里，对他说：『夫子说：我的时候快到了，我与门徒要在你家里守逾越节。』」","notes":[]},{"n":19,"t":"门徒遵着耶稣所吩咐的就去预备了逾越节的筵席。","notes":[]},{"n":20,"t":"到了晚上，耶稣和十二个门徒坐席。","notes":[]},{"n":21,"t":"正吃的时候，耶稣说：「我实在告诉你们，你们中间有一个人要卖我了。」","notes":[]},{"n":22,"t":"他们就甚忧愁，一个一个地问他说：「主，是我吗？」","notes":[]},{"n":23,"t":"耶稣回答说：「同我蘸手在盘子里的，就是他要卖我。","notes":[]},{"n":24,"t":"人子必要去世，正如经上指着他所写的；但卖人子的人有祸了！那人不生在世上倒好。」","notes":[]},{"n":25,"t":"卖耶稣的犹大问他说：「拉比，是我吗？」耶稣说：「你说的是。」","notes":[]},{"n":26,"t":"他们吃的时候，耶稣拿起饼来，祝福，就擘开，递给门徒，说：「你们拿着吃，这是我的身体」；","notes":[],"heads":["设立主的晚餐"]},{"n":27,"t":"又拿起杯来，祝谢了，递给他们，说：「你们都喝这个；","notes":[]},{"n":28,"t":"因为这是我立约的血，为多人流出来，使罪得赦。","notes":[]},{"n":29,"t":"但我告诉你们，从今以后，我不再喝这葡萄汁，直到我在我父的国里同你们喝新的那日子。」","notes":[]},{"n":30,"t":"他们唱了诗，就出来往橄榄山去。","notes":[]},{"n":31,"t":"那时，耶稣对他们说：「今夜，你们为我的缘故都要跌倒。因为经上记着说：我要击打牧人，羊就分散了。","notes":[],"heads":["预言彼得不认主"]},{"n":32,"t":"但我复活以后，要在你们以先往加利利去。」","notes":[]},{"n":33,"t":"彼得说：「众人虽然为你的缘故跌倒，我却永不跌倒。」","notes":[]},{"n":34,"t":"耶稣说：「我实在告诉你，今夜鸡叫以先，你要三次不认我。」","notes":[]},{"n":35,"t":"彼得说：「我就是必须和你同死，也总不能不认你。」众门徒都是这样说。","notes":[]},{"n":36,"t":"耶稣同门徒来到一个地方，名叫客西马尼，就对他们说：「你们坐在这里，等我到那边去祷告。」","notes":[],"heads":["在客西马尼祷告"]},{"n":37,"t":"于是带着彼得和西庇太的两个儿子同去，就忧愁起来，极其难过，","notes":[]},{"n":38,"t":"便对他们说：「我心里甚是忧伤，几乎要死；你们在这里等候，和我一同警醒。」","notes":[]},{"n":39,"t":"他就稍往前走，俯伏在地，祷告说：「我父啊，倘若可行，求你叫这杯离开我。然而，不要照我的意思，只要照你的意思。」","notes":[]},{"n":40,"t":"来到门徒那里，见他们睡着了，就对彼得说：「怎么样？你们不能同我警醒片时吗？","notes":[]},{"n":41,"t":"总要警醒祷告，免得入了迷惑。你们心灵固然愿意，肉体却软弱了。」","notes":[]},{"n":42,"t":"第二次又去祷告说：「我父啊，这杯若不能离开我，必要我喝，就愿你的意旨成全。」","notes":[]},{"n":43,"t":"又来，见他们睡着了，因为他们的眼睛困倦。","notes":[]},{"n":44,"t":"耶稣又离开他们去了。第三次祷告，说的话还是与先前一样。","notes":[]},{"n":45,"t":"于是来到门徒那里，对他们说：「现在你们仍然睡觉安歇吧！时候到了，人子被卖在罪人手里了。","notes":["吧：或译吗？"]},{"n":46,"t":"起来！我们走吧。看哪，卖我的人近了！」","notes":[]},{"n":47,"t":"说话之间，那十二个门徒里的犹大来了，并有许多人带着刀棒，从祭司长和民间的长老那里与他同来。","notes":[],"heads":["耶稣被捕"]},{"n":48,"t":"那卖耶稣的给了他们一个暗号，说：「我与谁亲嘴，谁就是他。你们可以拿住他。」","notes":[]},{"n":49,"t":"犹大随即到耶稣跟前，说：「请拉比安」，就与他亲嘴。","notes":[]},{"n":50,"t":"耶稣对他说：「朋友，你来要做的事，就做吧。」于是那些人上前，下手拿住耶稣。","notes":[]},{"n":51,"t":"有跟随耶稣的一个人伸手拔出刀来，将大祭司的仆人砍了一刀，削掉了他一个耳朵。","notes":[]},{"n":52,"t":"耶稣对他说：「收刀入鞘吧！凡动刀的，必死在刀下。","notes":[]},{"n":53,"t":"你想，我不能求我父现在为我差遣十二营多天使来吗？","notes":[]},{"n":54,"t":"若是这样，经上所说，事情必须如此的话怎么应验呢？」","notes":[]},{"n":55,"t":"当时，耶稣对众人说：「你们带着刀棒出来拿我，如同拿强盗吗？我天天坐在殿里教训人，你们并没有拿我。","notes":[]},{"n":56,"t":"但这一切的事成就了，为要应验先知书上的话。」当下，门徒都离开他，逃走了。","notes":[]},{"n":57,"t":"拿耶稣的人把他带到大祭司该亚法那里去；文士和长老已经在那里聚会。","notes":[],"heads":["耶稣在公会里受审"]},{"n":58,"t":"彼得远远地跟着耶稣，直到大祭司的院子，进到里面，就和差役同坐，要看这事到底怎样。","notes":[]},{"n":59,"t":"祭司长和全公会寻找假见证控告耶稣，要治死他。","notes":[]},{"n":60,"t":"虽有好些人来作假见证，总得不着实据。末后有两个人前来，说：","notes":[]},{"n":61,"t":"「这个人曾说：『我能拆毁神的殿，三日内又建造起来。』」","notes":[]},{"n":62,"t":"大祭司就站起来，对耶稣说：「你什么都不回答吗？这些人作见证告你的是什么呢？」","notes":[]},{"n":63,"t":"耶稣却不言语。大祭司对他说：「我指着永生神叫你起誓告诉我们，你是神的儿子基督不是？」","notes":[]},{"n":64,"t":"耶稣对他说：「你说的是。然而，我告诉你们，后来你们要看见人子坐在那权能者的右边，驾着天上的云降临。」","notes":[]},{"n":65,"t":"大祭司就撕开衣服，说：「他说了僭妄的话，我们何必再用见证人呢？这僭妄的话，现在你们都听见了。","notes":[]},{"n":66,"t":"你们的意见如何？」他们回答说：「他是该死的。」","notes":[]},{"n":67,"t":"他们就吐唾沫在他脸上，用拳头打他，也有用手掌打他的，说：","notes":[]},{"n":68,"t":"「基督啊！你是先知，告诉我们打你的是谁？」","notes":[]},{"n":69,"t":"彼得在外面院子里坐着，有一个使女前来，说：「你素来也是同那加利利人耶稣一伙的。」","notes":[],"heads":["彼得三次不认主"]},{"n":70,"t":"彼得在众人面前却不承认，说：「我不知道你说的是什么！」","notes":[]},{"n":71,"t":"既出去，到了门口，又有一个使女看见他，就对那里的人说：「这个人也是同拿撒勒人耶稣一伙的。」","notes":[]},{"n":72,"t":"彼得又不承认，并且起誓说：「我不认得那个人。」","notes":[]},{"n":73,"t":"过了不多的时候，旁边站着的人前来，对彼得说：「你真是他们一党的，你的口音把你露出来了。」","notes":[]},{"n":74,"t":"彼得就发咒起誓地说：「我不认得那个人。」立时，鸡就叫了。","notes":[]},{"n":75,"t":"彼得想起耶稣所说的话：「鸡叫以先，你要三次不认我。」他就出去痛哭。","notes":[]}]},"27":{"heading":"耶稣被交给彼拉多","verses":[{"n":1,"t":"到了早晨，众祭司长和民间的长老大家商议要治死耶稣，","notes":[]},{"n":2,"t":"就把他捆绑，解去，交给巡抚彼拉多。","notes":[]},{"n":3,"t":"这时候，卖耶稣的犹大看见耶稣已经定了罪，就后悔，把那三十块钱拿回来给祭司长和长老，说：","notes":[],"heads":["犹大的死"]},{"n":4,"t":"「我卖了无辜之人的血是有罪了。」他们说：「那与我们有什么相干？你自己承当吧！」","notes":[]},{"n":5,"t":"犹大就把那银钱丢在殿里，出去吊死了。","notes":[]},{"n":6,"t":"祭司长拾起银钱来，说：「这是血价，不可放在库里。」","notes":[]},{"n":7,"t":"他们商议，就用那银钱买了窑户的一块田，为要埋葬外乡人。","notes":[]},{"n":8,"t":"所以那块田直到今日还叫做「血田」。","notes":[]},{"n":9,"t":"这就应了先知耶利米的话，说：「他们用那三十块钱，就是被估定之人的价钱，是以色列人中所估定的，","notes":[]},{"n":10,"t":"买了窑户的一块田；这是照着主所吩咐我的。」","notes":[]},{"n":11,"t":"耶稣站在巡抚面前；巡抚问他说：「你是犹太人的王吗？」耶稣说：「你说的是。」","notes":[],"heads":["耶稣在彼拉多面前受审"]},{"n":12,"t":"他被祭司长和长老控告的时候，什么都不回答。","notes":[]},{"n":13,"t":"彼拉多就对他说：「他们作见证告你这么多的事，你没有听见吗？」","notes":[]},{"n":14,"t":"耶稣仍不回答，连一句话也不说，以致巡抚甚觉希奇。","notes":[]},{"n":15,"t":"巡抚有一个常例，每逢这节期，随众人所要的释放一个囚犯给他们。","notes":[],"heads":["耶稣被判死刑"]},{"n":16,"t":"当时有一个出名的囚犯叫巴拉巴。","notes":[]},{"n":17,"t":"众人聚集的时候，彼拉多就对他们说：「你们要我释放哪一个给你们？是巴拉巴呢？是称为基督的耶稣呢？」","notes":[]},{"n":18,"t":"巡抚原知道他们是因为嫉妒才把他解了来。","notes":[]},{"n":19,"t":"正坐堂的时候，他的夫人打发人来说：「这义人的事，你一点不可管，因为我今天在梦中为他受了许多的苦。」","notes":[]},{"n":20,"t":"祭司长和长老挑唆众人，求释放巴拉巴，除灭耶稣。","notes":[]},{"n":21,"t":"巡抚对众人说：「这两个人，你们要我释放哪一个给你们呢？」他们说：「巴拉巴。」","notes":[]},{"n":22,"t":"彼拉多说：「这样，那称为基督的耶稣我怎么办他呢？」他们都说：「把他钉十字架！」","notes":[]},{"n":23,"t":"巡抚说：「为什么呢？他做了什么恶事呢？」他们便极力地喊着说：「把他钉十字架！」","notes":[]},{"n":24,"t":"彼拉多见说也无济于事，反要生乱，就拿水在众人面前洗手，说：「流这义人的血，罪不在我，你们承当吧。」","notes":[]},{"n":25,"t":"众人都回答说：「他的血归到我们和我们的子孙身上。」","notes":[]},{"n":26,"t":"于是彼拉多释放巴拉巴给他们，把耶稣鞭打了，交给人钉十字架。","notes":[]},{"n":27,"t":"巡抚的兵就把耶稣带进衙门，叫全营的兵都聚集在他那里。","notes":[],"heads":["兵丁戏弄耶稣"]},{"n":28,"t":"他们给他脱了衣服，穿上一件朱红色袍子，","notes":[]},{"n":29,"t":"用荆棘编做冠冕，戴在他头上，拿一根苇子放在他右手里，跪在他面前，戏弄他，说：「恭喜，犹太人的王啊！」","notes":[]},{"n":30,"t":"又吐唾沫在他脸上，拿苇子打他的头。","notes":[]},{"n":31,"t":"戏弄完了，就给他脱了袍子，仍穿上他自己的衣服，带他出去，要钉十字架。","notes":[]},{"n":32,"t":"他们出来的时候，遇见一个古利奈人，名叫西门，就勉强他同去，好背着耶稣的十字架。","notes":[],"heads":["耶稣被钉十字架"]},{"n":33,"t":"到了一个地方名叫各各他，意思就是「髑髅地」。","notes":[]},{"n":34,"t":"兵丁拿苦胆调和的酒给耶稣喝；他尝了，就不肯喝。","notes":[]},{"n":35,"t":"他们既将他钉在十字架上，就拈阄分他的衣服，","notes":[]},{"n":36,"t":"又坐在那里看守他。","notes":[]},{"n":37,"t":"在他头以上安一个牌子，写着他的罪状，说：「这是犹太人的王耶稣。」","notes":[]},{"n":38,"t":"当时，有两个强盗和他同钉十字架，一个在右边，一个在左边。","notes":[]},{"n":39,"t":"从那里经过的人讥诮他，摇着头，说：","notes":[]},{"n":40,"t":"「你这拆毁圣殿、三日又建造起来的，可以救自己吧！你如果是神的儿子，就从十字架上下来吧！」","notes":[]},{"n":41,"t":"祭司长和文士并长老也是这样戏弄他，说：","notes":[]},{"n":42,"t":"「他救了别人，不能救自己。他是以色列的王，现在可以从十字架上下来，我们就信他。","notes":[]},{"n":43,"t":"他倚靠神，神若喜悦他，现在可以救他；因为他曾说：『我是神的儿子。』」","notes":[]},{"n":44,"t":"那和他同钉的强盗也是这样地讥诮他。","notes":[]},{"n":45,"t":"从午正到申初，遍地都黑暗了。","notes":[],"heads":["耶稣的死"]},{"n":46,"t":"约在申初，耶稣大声喊着说：「以利！以利！拉马撒巴各大尼？」就是说：「我的神！我的神！为什么离弃我？」","notes":[]},{"n":47,"t":"站在那里的人，有的听见就说：「这个人呼叫以利亚呢！」","notes":[]},{"n":48,"t":"内中有一个人赶紧跑去，拿海绒蘸满了醋，绑在苇子上，送给他喝。","notes":[]},{"n":49,"t":"其余的人说：「且等着，看以利亚来救他不来。」","notes":[]},{"n":50,"t":"耶稣又大声喊叫，气就断了。","notes":[]},{"n":51,"t":"忽然，殿里的幔子从上到下裂为两半，地也震动，磐石也崩裂，","notes":[]},{"n":52,"t":"坟墓也开了，已睡圣徒的身体多有起来的。","notes":[]},{"n":53,"t":"到耶稣复活以后，他们从坟墓里出来，进了圣城，向许多人显现。","notes":[]},{"n":54,"t":"百夫长和一同看守耶稣的人看见地震并所经历的事，就极其害怕，说：「这真是神的儿子了！」","notes":[]},{"n":55,"t":"有好些妇女在那里，远远地观看；她们是从加利利跟随耶稣来服事他的。","notes":[]},{"n":56,"t":"内中有抹大拉的马利亚，又有雅各和约西的母亲马利亚，并有西庇太两个儿子的母亲。","notes":[]},{"n":57,"t":"到了晚上，有一个财主，名叫约瑟，是亚利马太来的，他也是耶稣的门徒。","notes":[],"heads":["耶稣的安葬"]},{"n":58,"t":"这人去见彼拉多，求耶稣的身体；彼拉多就吩咐给他。","notes":[]},{"n":59,"t":"约瑟取了身体，用干净细麻布裹好，","notes":[]},{"n":60,"t":"安放在自己的新坟墓里，就是他凿在磐石里的。他又把大石头滚到墓门口，就去了。","notes":[]},{"n":61,"t":"有抹大拉的马利亚和那个马利亚在那里，对着坟墓坐着。","notes":[]},{"n":62,"t":"次日，就是预备日的第二天，祭司长和法利赛人聚集来见彼拉多，说：","notes":[],"heads":["封石妥守"]},{"n":63,"t":"「大人，我们记得那诱惑人的还活着的时候曾说：『三日后我要复活。』","notes":[]},{"n":64,"t":"因此，请吩咐人将坟墓把守妥当，直到第三日，恐怕他的门徒来，把他偷了去，就告诉百姓说：『他从死里复活了。』这样，那后来的迷惑比先前的更利害了！」","notes":[]},{"n":65,"t":"彼拉多说：「你们有看守的兵，去吧！尽你们所能的把守妥当。」","notes":[]},{"n":66,"t":"他们就带着看守的兵同去，封了石头，将坟墓把守妥当。","notes":[]}]},"28":{"heading":"耶稣复活","verses":[{"n":1,"t":"安息日将尽，七日的头一日，天快亮的时候，抹大拉的马利亚和那个马利亚来看坟墓。","notes":[]},{"n":2,"t":"忽然，地大震动；因为有主的使者从天上下来，把石头滚开，坐在上面。","notes":[]},{"n":3,"t":"他的相貌如同闪电，衣服洁白如雪。","notes":[]},{"n":4,"t":"看守的人就因他吓得浑身乱战，甚至和死人一样。","notes":[]},{"n":5,"t":"天使对妇女说：「不要害怕！我知道你们是寻找那钉十字架的耶稣。","notes":[]},{"n":6,"t":"他不在这里，照他所说的，已经复活了。你们来看安放主的地方。","notes":[]},{"n":7,"t":"快去告诉他的门徒，说他从死里复活了，并且在你们以先往加利利去，在那里你们要见他。看哪，我已经告诉你们了。」","notes":[]},{"n":8,"t":"妇女们就急忙离开坟墓，又害怕，又大大地欢喜，跑去要报给他的门徒。","notes":[]},{"n":9,"t":"忽然，耶稣遇见她们，说：「愿你们平安！」她们就上前抱住他的脚拜他。","notes":[]},{"n":10,"t":"耶稣对她们说：「不要害怕！你们去告诉我的弟兄，叫他们往加利利去，在那里必见我。」","notes":[]},{"n":11,"t":"她们去的时候，看守的兵有几个进城去，将所经历的事都报给祭司长。","notes":[],"heads":["看守的兵报告祭司长"]},{"n":12,"t":"祭司长和长老聚集商议，就拿许多银钱给兵丁，说：","notes":[]},{"n":13,"t":"「你们要这样说：『夜间我们睡觉的时候，他的门徒来，把他偷去了。』","notes":[]},{"n":14,"t":"倘若这话被巡抚听见，有我们劝他，保你们无事。」","notes":[]},{"n":15,"t":"兵丁受了银钱，就照所嘱咐他们的去行。这话就传说在犹太人中间，直到今日。","notes":[]},{"n":16,"t":"十一个门徒往加利利去，到了耶稣约定的山上。","notes":[],"heads":["门徒奉差遣"]},{"n":17,"t":"他们见了耶稣就拜他，然而还有人疑惑。","notes":[]},{"n":18,"t":"耶稣进前来，对他们说：「天上地下所有的权柄都赐给我了。","notes":[]},{"n":19,"t":"所以，你们要去，使万民作我的门徒，奉父、子、圣灵的名给他们施洗。","notes":["或译：给他们施洗，归于父、子、圣灵的名"]},{"n":20,"t":"凡我所吩咐你们的，都教训他们遵守，我就常与你们同在，直到世界的末了。」","notes":[]}]}},"MRK":{"1":{"heading":"施洗约翰传道","verses":[{"n":1,"t":"神的儿子，耶稣基督福音的起头。","notes":[]},{"n":2,"t":"正如先知以赛亚书上记着说：看哪，我要差遣我的使者在你前面，预备道路。","notes":["有古卷没有以赛亚三个字"]},{"n":3,"t":"在旷野有人声喊着说：预备主的道，修直他的路。","notes":[]},{"n":4,"t":"照这话，约翰来了，在旷野施洗，传悔改的洗礼，使罪得赦。","notes":[]},{"n":5,"t":"犹太全地和耶路撒冷的人都出去到约翰那里，承认他们的罪，在约旦河里受他的洗。","notes":[]},{"n":6,"t":"约翰穿骆驼毛的衣服，腰束皮带，吃的是蝗虫、野蜜。","notes":[]},{"n":7,"t":"他传道说：「有一位在我以后来的，能力比我更大，我就是弯腰给他解鞋带也是不配的。","notes":[]},{"n":8,"t":"我是用水给你们施洗，他却要用圣灵给你们施洗。」","notes":[]},{"n":9,"t":"那时，耶稣从加利利的拿撒勒来，在约旦河里受了 约翰的洗。","notes":[],"heads":["耶稣受洗"]},{"n":10,"t":"他从水里一上来，就看见天裂开了，圣灵仿佛鸽子，降在他身上。","notes":[]},{"n":11,"t":"又有声音从天上来，说：「你是我的爱子，我喜悦你。」","notes":[]},{"n":12,"t":"圣灵就把耶稣催到旷野里去。","notes":[],"heads":["耶稣受试探"]},{"n":13,"t":"他在旷野四十天，受撒但的试探，并与野兽同在一处，且有天使来伺候他。","notes":[]},{"n":14,"t":"约翰下监以后，耶稣来到加利利，宣传神的福音，","notes":[],"heads":["开始在加利利传道"]},{"n":15,"t":"说：「日期满了，神的国近了。你们当悔改，信福音！」","notes":[]},{"n":16,"t":"耶稣顺着加利利的海边走，看见西门和西门的兄弟安得烈在海里撒网；他们本是打鱼的。","notes":[],"heads":["呼召四个渔夫"]},{"n":17,"t":"耶稣对他们说：「来跟从我，我要叫你们得人如得鱼一样。」","notes":[]},{"n":18,"t":"他们就立刻舍了网，跟从了他。","notes":[]},{"n":19,"t":"耶稣稍往前走，又见西庇太的儿子雅各和雅各的兄弟约翰在船上补网。","notes":[]},{"n":20,"t":"耶稣随即招呼他们，他们就把父亲 西庇太和雇工人留在船上，跟从耶稣去了。","notes":[]},{"n":21,"t":"到了迦百农，耶稣就在安息日进了会堂教训人。","notes":[],"heads":["一个污鬼附身的人"]},{"n":22,"t":"众人很希奇他的教训；因为他教训他们，正像有权柄的人，不像文士。","notes":[]},{"n":23,"t":"在会堂里，有一个人被污鬼附着。他喊叫说：","notes":[]},{"n":24,"t":"「拿撒勒人耶稣，我们与你有什么相干？你来灭我们吗？我知道你是谁，乃是神的圣者。」","notes":[]},{"n":25,"t":"耶稣责备他说：「不要作声！从这人身上出来吧。」","notes":[]},{"n":26,"t":"污鬼叫那人抽了一阵风，大声喊叫，就出来了。","notes":[]},{"n":27,"t":"众人都惊讶，以致彼此对问说：「这是什么事？是个新道理啊！他用权柄吩咐污鬼，连污鬼也听从了他。」","notes":[]},{"n":28,"t":"耶稣的名声就传遍了加利利的四方。","notes":[]},{"n":29,"t":"他们一出会堂，就同着雅各、约翰，进了西门和安得烈的家。","notes":[],"heads":["治好许多病人"]},{"n":30,"t":"西门的岳母正害热病躺着，就有人告诉耶稣。","notes":[]},{"n":31,"t":"耶稣进前拉着她的手，扶她起来，热就退了，她就服事他们。","notes":[]},{"n":32,"t":"天晚日落的时候，有人带着一切害病的，和被鬼附的，来到耶稣跟前。","notes":[]},{"n":33,"t":"合城的人都聚集在门前。","notes":[]},{"n":34,"t":"耶稣治好了许多害各样病的人，又赶出许多鬼，不许鬼说话，因为鬼认识他。","notes":[]},{"n":35,"t":"次日早晨，天未亮的时候，耶稣起来，到旷野地方去，在那里祷告。","notes":[],"heads":["在加利利各会堂传道"]},{"n":36,"t":"西门和同伴追了他去，","notes":[]},{"n":37,"t":"遇见了就对他说：「众人都找你。」","notes":[]},{"n":38,"t":"耶稣对他们说：「我们可以往别处去，到邻近的乡村，我也好在那里传道，因为我是为这事出来的。」","notes":[]},{"n":39,"t":"于是在加利利全地，进了会堂，传道，赶鬼。","notes":[]},{"n":40,"t":"有一个长大麻风的来求耶稣，向他跪下，说：「你若肯，必能叫我洁净了。」","notes":[],"heads":["洁净长大麻风的人"]},{"n":41,"t":"耶稣动了慈心，就伸手摸他，说：「我肯，你洁净了吧！」","notes":[]},{"n":42,"t":"大麻风即时离开他，他就洁净了。","notes":[]},{"n":43,"t":"耶稣严严地嘱咐他，就打发他走，","notes":[]},{"n":44,"t":"对他说：「你要谨慎，什么话都不可告诉人，只要去把身体给祭司察看，又因为你洁净了，献上摩西所吩咐的礼物，对众人作证据。」","notes":[]},{"n":45,"t":"那人出去，倒说许多的话，把这件事传扬开了，叫耶稣以后不得再明明地进城，只好在外边旷野地方。人从各处都就了他来。","notes":[]}]},"2":{"heading":"治好瘫痪病人","verses":[{"n":1,"t":"过了些日子，耶稣又进了迦百农。人听见他在房子里，","notes":[]},{"n":2,"t":"就有许多人聚集，甚至连门前都没有空地；耶稣就对他们讲道。","notes":[]},{"n":3,"t":"有人带着一个瘫子来见耶稣，是用四个人抬来的；","notes":[]},{"n":4,"t":"因为人多，不得近前，就把耶稣所在的房子，拆了房顶，既拆通了，就把瘫子连所躺卧的褥子都缒下来。","notes":[]},{"n":5,"t":"耶稣见他们的信心，就对瘫子说：「小子，你的罪赦了。」","notes":[]},{"n":6,"t":"有几个文士坐在那里，心里议论，说：","notes":[]},{"n":7,"t":"「这个人为什么这样说呢？他说僭妄的话了。除了神以外，谁能赦罪呢？」","notes":[]},{"n":8,"t":"耶稣心中知道他们心里这样议论，就说：「你们心里为什么这样议论呢？","notes":[]},{"n":9,"t":"或对瘫子说『你的罪赦了』，或说『起来！拿你的褥子行走』，哪一样容易呢？","notes":[]},{"n":10,"t":"但要叫你们知道，人子在地上有赦罪的权柄。」就对瘫子说：","notes":[]},{"n":11,"t":"「我吩咐你，起来！拿你的褥子回家去吧。」","notes":[]},{"n":12,"t":"那人就起来，立刻拿着褥子，当众人面前出去了，以致众人都惊奇，归荣耀与神，说：「我们从来没有见过这样的事！」","notes":[]},{"n":13,"t":"耶稣又出到海边去，众人都就了他来，他便教训他们。","notes":[],"heads":["呼召利未"]},{"n":14,"t":"耶稣经过的时候，看见亚勒腓的儿子利未坐在税关上，就对他说：「你跟从我来。」他就起来，跟从了耶稣。","notes":[]},{"n":15,"t":"耶稣在利未家里坐席的时候，有好些税吏和罪人与耶稣并门徒一同坐席；因为这样的人多，他们也跟随耶稣。","notes":[]},{"n":16,"t":"法利赛人中的文士看见耶稣和罪人并税吏一同吃饭，就对他门徒说：「他和税吏并罪人一同吃喝吗？」","notes":["有古卷：文士和法利赛人"]},{"n":17,"t":"耶稣听见，就对他们说：「康健的人用不着医生，有病的人才用得着。我来本不是召义人，乃是召罪人。」","notes":[]},{"n":18,"t":"当下，约翰的门徒和法利赛人禁食。他们来问耶稣说：「约翰的门徒和法利赛人的门徒禁食，你的门徒倒不禁食，这是为什么呢？」","notes":[],"heads":["禁食的问题"]},{"n":19,"t":"耶稣对他们说：「新郎和陪伴之人同在的时候，陪伴之人岂能禁食呢？新郎还同在，他们不能禁食。","notes":[]},{"n":20,"t":"但日子将到，新郎要离开他们，那日他们就要禁食。","notes":[]},{"n":21,"t":"没有人把新布缝在旧衣服上，恐怕所补上的新布带坏了旧衣服，破的就更大了。","notes":[]},{"n":22,"t":"也没有人把新酒装在旧皮袋里，恐怕酒把皮袋裂开，酒和皮袋就都坏了；惟把新酒装在新皮袋里。」","notes":[]},{"n":23,"t":"耶稣当安息日从麦地经过。他门徒行路的时候，掐了麦穗。","notes":[],"heads":["安息日的问题"]},{"n":24,"t":"法利赛人对耶稣说：「看哪，他们在安息日为什么做不可做的事呢？」","notes":[]},{"n":25,"t":"耶稣对他们说：「经上记着大卫和跟从他的人缺乏饥饿之时所做的事，你们没有念过吗？","notes":[]},{"n":26,"t":"他当亚比亚他作大祭司的时候，怎么进了神的殿，吃了陈设饼，又给跟从他的人吃。这饼除了祭司以外，人都不可吃。」","notes":[]},{"n":27,"t":"又对他们说：「安息日是为人设立的，人不是为安息日设立的。","notes":[]},{"n":28,"t":"所以，人子也是安息日的主。」","notes":[]}]},"3":{"heading":"治好枯干了一只手的人","verses":[{"n":1,"t":"耶稣又进了会堂，在那里有一个人枯干了一只手。","notes":[]},{"n":2,"t":"众人窥探耶稣，在安息日医治不医治，意思是要控告耶稣。","notes":[]},{"n":3,"t":"耶稣对那枯干一只手的人说：「起来，站在当中。」","notes":[]},{"n":4,"t":"又问众人说：「在安息日行善行恶，救命害命，哪样是可以的呢？」他们都不作声。","notes":[]},{"n":5,"t":"耶稣怒目周围看他们，忧愁他们的心刚硬，就对那人说：「伸出手来！」他把手一伸，手就复了原。","notes":[]},{"n":6,"t":"法利赛人出去，同希律一党的人商议怎样可以除灭耶稣。","notes":[]},{"n":7,"t":"耶稣和门徒退到海边去，有许多人从加利利跟随他。","notes":[],"heads":["海边的群众"]},{"n":8,"t":"还有许多人听见他所做的大事，就从犹太、耶路撒冷、以土买、约旦河外，并泰尔、西顿的四方来到他那里。","notes":[]},{"n":9,"t":"他因为人多，就吩咐门徒叫一只小船伺候着，免得众人拥挤他。","notes":[]},{"n":10,"t":"他治好了许多人，所以凡有灾病的，都挤进来要摸他。","notes":[]},{"n":11,"t":"污鬼无论何时看见他，就俯伏在他面前，喊着说：「你是神的儿子。」","notes":[]},{"n":12,"t":"耶稣再三地嘱咐他们，不要把他显露出来。","notes":[]},{"n":13,"t":"耶稣上了山，随自己的意思叫人来；他们便来到他那里。","notes":[],"heads":["设立十二门徒"]},{"n":14,"t":"他就设立十二个人，要他们常和自己同在，也要差他们去传道，","notes":[]},{"n":15,"t":"并给他们权柄赶鬼。","notes":[]},{"n":16,"t":"这十二个人有西门（耶稣又给他起名叫彼得），","notes":[]},{"n":17,"t":"还有西庇太的儿子雅各和雅各的兄弟约翰（又给这两个人起名叫半尼其，就是雷子的意思），","notes":[]},{"n":18,"t":"又有安得烈、腓力、巴多罗买、马太、多马、亚勒腓的儿子雅各，和达太，并奋锐党的西门，","notes":[]},{"n":19,"t":"还有卖耶稣的加略人犹大。","notes":[]},{"n":20,"t":"耶稣进了一个屋子，众人又聚集，甚至他连饭也顾不得吃。","notes":[],"heads":["耶稣和别西卜"]},{"n":21,"t":"耶稣的亲属听见，就出来要拉住他，因为他们说他癫狂了。","notes":[]},{"n":22,"t":"从耶路撒冷下来的文士说：「他是被别西卜附着」；又说：「他是靠着鬼王赶鬼。」","notes":[]},{"n":23,"t":"耶稣叫他们来，用比喻对他们说：「撒但怎能赶出撒但呢？","notes":[]},{"n":24,"t":"若一国自相纷争，那国就站立不住；","notes":[]},{"n":25,"t":"若一家自相纷争，那家就站立不住。","notes":[]},{"n":26,"t":"若撒但自相攻打纷争，他就站立不住，必要灭亡。","notes":[]},{"n":27,"t":"没有人能进壮士家里，抢夺他的家具；必先捆住那壮士，才可以抢夺他的家。","notes":[]},{"n":28,"t":"我实在告诉你们，世人一切的罪和一切亵渎的话都可得赦免；","notes":[]},{"n":29,"t":"凡亵渎圣灵的，却永不得赦免，乃要担当永远的罪。」","notes":[]},{"n":30,"t":"这话是因为他们说：「他是被污鬼附着的。」","notes":[]},{"n":31,"t":"当下，耶稣的母亲和弟兄来，站在外边，打发人去叫他。","notes":[],"heads":["耶稣的母亲和兄弟们"]},{"n":32,"t":"有许多人在耶稣周围坐着，他们就告诉他说：「看哪，你母亲和你弟兄在外边找你。」","notes":[]},{"n":33,"t":"耶稣回答说：「谁是我的母亲？谁是我的弟兄？」","notes":[]},{"n":34,"t":"就四面观看那周围坐着的人，说：「看哪，我的母亲，我的弟兄。","notes":[]},{"n":35,"t":"凡遵行神旨意的人就是我的弟兄姊妹和母亲了。」","notes":[]}]},"4":{"heading":"撒种的比喻","verses":[{"n":1,"t":"耶稣又在海边教训人。有许多人到他那里聚集，他只得上船坐下。船在海里，众人都靠近海，站在岸上。","notes":[]},{"n":2,"t":"耶稣就用比喻教训他们许多道理。在教训之间，对他们说：","notes":[]},{"n":3,"t":"「你们听啊！有一个撒种的出去撒种。","notes":[]},{"n":4,"t":"撒的时候，有落在路旁的，飞鸟来吃尽了；","notes":[]},{"n":5,"t":"有落在土浅石头地上的，土既不深，发苗最快，","notes":[]},{"n":6,"t":"日头出来一晒，因为没有根，就枯干了；","notes":[]},{"n":7,"t":"有落在荆棘里的，荆棘长起来，把它挤住了，就不结实；","notes":[]},{"n":8,"t":"又有落在好土里的，就发生长大，结实有三十倍的，有六十倍的，有一百倍的」；","notes":[]},{"n":9,"t":"又说：「有耳可听的，就应当听！」","notes":[]},{"n":10,"t":"无人的时候，跟随耶稣的人和十二个门徒问他这比喻的意思。","notes":[],"heads":["用比喻的目的"]},{"n":11,"t":"耶稣对他们说：「神国的奥秘只叫你们知道，若是对外人讲，凡事就用比喻，","notes":[]},{"n":12,"t":"叫他们看是看见，却不晓得；听是听见，却不明白；恐怕他们回转过来，就得赦免。」","notes":[]},{"n":13,"t":"又对他们说：「你们不明白这比喻吗？这样怎能明白一切的比喻呢？","notes":[],"heads":["解明撒种的比喻"]},{"n":14,"t":"撒种之人所撒的就是道。","notes":[]},{"n":15,"t":"那撒在路旁的，就是人听了道，撒但立刻来，把撒在他心里的道夺了去。","notes":[]},{"n":16,"t":"那撒在石头地上的，就是人听了道，立刻欢喜领受，","notes":[]},{"n":17,"t":"但他心里没有根，不过是暂时的，及至为道遭了患难，或是受了逼迫，立刻就跌倒了。","notes":[]},{"n":18,"t":"还有那撒在荆棘里的，就是人听了道，","notes":[]},{"n":19,"t":"后来有世上的思虑、钱财的迷惑，和别样的私欲进来，把道挤住了，就不能结实。","notes":[]},{"n":20,"t":"那撒在好地上的，就是人听道，又领受，并且结实，有三十倍的，有六十倍的，有一百倍的。」","notes":[]},{"n":21,"t":"耶稣又对他们说：「人拿灯来，岂是要放在斗底下，床底下，不放在灯台上吗？","notes":[],"heads":["斗底下的灯"]},{"n":22,"t":"因为掩藏的事，没有不显出来的；隐瞒的事，没有不露出来的。","notes":[]},{"n":23,"t":"有耳可听的，就应当听！」","notes":[]},{"n":24,"t":"又说：「你们所听的要留心。你们用什么量器量给人，也必用什么量器量给你们，并且要多给你们。","notes":[]},{"n":25,"t":"因为有的，还要给他；没有的，连他所有的也要夺去。」","notes":[]},{"n":26,"t":"又说：「神的国如同人把种撒在地上。","notes":[],"heads":["种子长大的比喻"]},{"n":27,"t":"黑夜睡觉，白日起来，这种就发芽渐长，那人却不晓得如何这样。","notes":[]},{"n":28,"t":"地生五谷是出于自然的：先发苗，后长穗，再后穗上结成饱满的子粒；","notes":[]},{"n":29,"t":"谷既熟了，就用镰刀去割，因为收成的时候到了。」","notes":[]},{"n":30,"t":"又说：「神的国，我们可用什么比较呢？可用什么比喻表明呢？","notes":[],"heads":["芥菜种的比喻"]},{"n":31,"t":"好像一粒芥菜种，种在地里的时候，虽比地上的百种都小，","notes":[]},{"n":32,"t":"但种上以后，就长起来，比各样的菜都大，又长出大枝来，甚至天上的飞鸟可以宿在它的荫下。」","notes":[]},{"n":33,"t":"耶稣用许多这样的比喻，照他们所能听的，对他们讲道。","notes":[],"heads":["耶稣用比喻讲道"]},{"n":34,"t":"若不用比喻，就不对他们讲；没有人的时候，就把一切的道讲给门徒听。","notes":[]},{"n":35,"t":"当那天晚上，耶稣对门徒说：「我们渡到那边去吧。」","notes":[],"heads":["平静风和海"]},{"n":36,"t":"门徒离开众人，耶稣仍在船上，他们就把他一同带去；也有别的船和他同行。","notes":[]},{"n":37,"t":"忽然起了暴风，波浪打入船内，甚至船要满了水。","notes":[]},{"n":38,"t":"耶稣在船尾上，枕着枕头睡觉。门徒叫醒了他，说：「夫子！我们丧命，你不顾吗？」","notes":[]},{"n":39,"t":"耶稣醒了，斥责风，向海说：「住了吧！静了吧！」风就止住，大大地平静了。","notes":[]},{"n":40,"t":"耶稣对他们说：「为什么胆怯？你们还没有信心吗？」","notes":[]},{"n":41,"t":"他们就大大地惧怕，彼此说：「这到底是谁，连风和海也听从他了。」","notes":[]}]},"5":{"heading":"治好格拉森被鬼附的人","verses":[{"n":1,"t":"他们来到海那边格拉森人的地方。","notes":[]},{"n":2,"t":"耶稣一下船，就有一个被污鬼附着的人从坟茔里出来迎着他。","notes":[]},{"n":3,"t":"那人常住在坟茔里，没有人能捆住他，就是用铁链也不能；","notes":[]},{"n":4,"t":"因为人屡次用脚镣和铁链捆锁他，铁链竟被他挣断了，脚镣也被他弄碎了；总没有人能制伏他。","notes":[]},{"n":5,"t":"他昼夜常在坟茔里和山中喊叫，又用石头砍自己。","notes":[]},{"n":6,"t":"他远远地看见耶稣，就跑过去拜他，","notes":[]},{"n":7,"t":"大声呼叫说：「至高神的儿子耶稣，我与你有什么相干？我指着神恳求你，不要叫我受苦！」","notes":[]},{"n":8,"t":"是因耶稣曾吩咐他说：「污鬼啊，从这人身上出来吧！」","notes":[]},{"n":9,"t":"耶稣问他说：「你名叫什么？」回答说：「我名叫『群』，因为我们多的缘故」；","notes":[]},{"n":10,"t":"就再三地求耶稣，不要叫他们离开那地方。","notes":[]},{"n":11,"t":"在那里山坡上，有一大群猪吃食；","notes":[]},{"n":12,"t":"鬼就央求耶稣说：「求你打发我们往猪群里，附着猪去。」","notes":[]},{"n":13,"t":"耶稣准了他们，污鬼就出来，进入猪里去。于是那群猪闯下山崖，投在海里，淹死了。猪的数目约有二千。","notes":[]},{"n":14,"t":"放猪的就逃跑了，去告诉城里和乡下的人。众人就来，要看是什么事。","notes":[]},{"n":15,"t":"他们来到耶稣那里，看见那被鬼附着的人，就是从前被群鬼所附的，坐着，穿上衣服，心里明白过来，他们就害怕。","notes":[]},{"n":16,"t":"看见这事的，便将鬼附之人所遇见的和那群猪的事都告诉了众人；","notes":[]},{"n":17,"t":"众人就央求耶稣离开他们的境界。","notes":[]},{"n":18,"t":"耶稣上船的时候，那从前被鬼附着的人恳求和耶稣同在。","notes":[]},{"n":19,"t":"耶稣不许，却对他说：「你回家去，到你的亲属那里，将主为你所做的是何等大的事，是怎样怜悯你，都告诉他们。」","notes":[]},{"n":20,"t":"那人就走了，在低加坡里传扬耶稣为他做了何等大的事，众人就都希奇。","notes":[]},{"n":21,"t":"耶稣坐船又渡到那边去，就有许多人到他那里聚集；他正在海边上。","notes":[],"heads":["睚鲁的女儿和血漏的女人"]},{"n":22,"t":"有一个管会堂的人，名叫睚鲁，来见耶稣，就俯伏在他脚前，","notes":[]},{"n":23,"t":"再三地求他，说：「我的小女儿快要死了，求你去按手在她身上，使她痊愈，得以活了。」","notes":[]},{"n":24,"t":"耶稣就和他同去。有许多人跟随拥挤他。","notes":[]},{"n":25,"t":"有一个女人，患了十二年的血漏，","notes":[]},{"n":26,"t":"在好些医生手里受了许多的苦，又花尽了她所有的，一点也不见好，病势反倒更重了。","notes":[]},{"n":27,"t":"她听见耶稣的事，就从后头来，杂在众人中间，摸耶稣的衣裳，","notes":[]},{"n":28,"t":"意思说：「我只摸他的衣裳，就必痊愈。」","notes":[]},{"n":29,"t":"于是她血漏的源头立刻干了；她便觉得身上的灾病好了。","notes":[]},{"n":30,"t":"耶稣顿时心里觉得有能力从自己身上出去，就在众人中间转过来，说：「谁摸我的衣裳？」","notes":[]},{"n":31,"t":"门徒对他说：「你看众人拥挤你，还说『谁摸我』吗？」","notes":[]},{"n":32,"t":"耶稣周围观看，要见做这事的女人。","notes":[]},{"n":33,"t":"那女人知道在自己身上所成的事，就恐惧战兢，来俯伏在耶稣跟前，将实情全告诉他。","notes":[]},{"n":34,"t":"耶稣对她说：「女儿，你的信救了你，平平安安地回去吧！你的灾病痊愈了。」","notes":[]},{"n":35,"t":"还说话的时候，有人从管会堂的家里来，说：「你的女儿死了，何必还劳动先生呢？」","notes":[]},{"n":36,"t":"耶稣听见所说的话，就对管会堂的说：「不要怕，只要信！」","notes":[]},{"n":37,"t":"于是带着彼得、雅各，和雅各的兄弟约翰同去，不许别人跟随他。","notes":[]},{"n":38,"t":"他们来到管会堂的家里；耶稣看见那里乱嚷，并有人大大地哭泣哀号，","notes":[]},{"n":39,"t":"进到里面，就对他们说：「为什么乱嚷哭泣呢？孩子不是死了，是睡着了。」","notes":[]},{"n":40,"t":"他们就嗤笑耶稣。耶稣把他们都撵出去，就带着孩子的父母和跟随的人进了孩子所在的地方，","notes":[]},{"n":41,"t":"就拉着孩子的手，对她说：「大利大，古米！」（翻出来就是说：「闺女，我吩咐你起来！」）","notes":[]},{"n":42,"t":"那闺女立时起来走。他们就大大地惊奇；闺女已经十二岁了。","notes":[]},{"n":43,"t":"耶稣切切地嘱咐他们，不要叫人知道这事，又吩咐给她东西吃。","notes":[]}]},"6":{"heading":"拿撒勒人厌弃耶稣","verses":[{"n":1,"t":"耶稣离开那里，来到自己的家乡；门徒也跟从他。","notes":[]},{"n":2,"t":"到了安息日，他在会堂里教训人。众人听见，就甚希奇，说：「这人从哪里有这些事呢？所赐给他的是什么智慧？他手所做的是何等的异能呢？","notes":[]},{"n":3,"t":"这不是那木匠吗？不是马利亚的儿子雅各、约西、犹大、西门的长兄吗？他妹妹们不也是在我们这里吗？」他们就厌弃他。","notes":["厌弃他：原文是因他跌倒"]},{"n":4,"t":"耶稣对他们说：「大凡先知，除了本地、亲属、本家之外，没有不被人尊敬的。」","notes":[]},{"n":5,"t":"耶稣就在那里不得行什么异能，不过按手在几个病人身上，治好他们。","notes":[]},{"n":6,"t":"他也诧异他们不信，就往周围乡村教训人去了。","notes":[]},{"n":7,"t":"耶稣叫了十二个门徒来，差遣他们两个两个地出去，也赐给他们权柄，制伏污鬼；","notes":[],"heads":["耶稣差遣十二门徒"]},{"n":8,"t":"并且嘱咐他们：「行路的时候不要带食物和口袋，腰袋里也不要带钱，除了拐杖以外，什么都不要带；","notes":[]},{"n":9,"t":"只要穿鞋，也不要穿两件褂子」；","notes":[]},{"n":10,"t":"又对他们说：「你们无论到何处，进了人的家，就住在那里，直到离开那地方。","notes":[]},{"n":11,"t":"何处的人不接待你们，不听你们，你们离开那里的时候，就把脚上的尘土跺下去，对他们作见证。」","notes":[]},{"n":12,"t":"门徒就出去传道，叫人悔改，","notes":[]},{"n":13,"t":"又赶出许多的鬼，用油抹了许多病人，治好他们。","notes":[]},{"n":14,"t":"耶稣的名声传扬出来。希律王听见了，就说：「施洗的约翰从死里复活了，所以这些异能由他里面发出来。」","notes":[],"heads":["施洗约翰的死"]},{"n":15,"t":"但别人说：「是以利亚。」又有人说：「是先知，正像先知中的一位。」","notes":[]},{"n":16,"t":"希律听见却说：「是我所斩的约翰，他复活了。」","notes":[]},{"n":17,"t":"先是希律为他兄弟腓力的妻子希罗底的缘故，差人去拿住约翰，锁在监里，因为希律已经娶了那妇人。","notes":[]},{"n":18,"t":"约翰曾对希律说：「你娶你兄弟的妻子是不合理的。」","notes":[]},{"n":19,"t":"于是希罗底怀恨他，想要杀他，只是不能；","notes":[]},{"n":20,"t":"因为希律知道约翰是义人，是圣人，所以敬畏他，保护他，听他讲论，就多照着行，并且乐意听他。","notes":["有古卷：游移不定"]},{"n":21,"t":"有一天，恰巧是希律的生日，希律摆设筵席，请了大臣和千夫长，并加利利作首领的。","notes":[]},{"n":22,"t":"希罗底的女儿进来跳舞，使希律和同席的人都欢喜。王就对女子说：「你随意向我求什么，我必给你。」","notes":[]},{"n":23,"t":"又对她起誓说：「随你向我求什么，就是我国的一半，我也必给你。」","notes":[]},{"n":24,"t":"她就出去对她母亲说：「我可以求什么呢？」她母亲说：「施洗约翰的头。」","notes":[]},{"n":25,"t":"她就急忙进去见王，求他说：「我愿王立时把施洗约翰的头放在盘子里给我。」","notes":[]},{"n":26,"t":"王就甚忧愁；但因他所起的誓，又因同席的人，就不肯推辞，","notes":[]},{"n":27,"t":"随即差一个护卫兵，吩咐拿约翰的头来。护卫兵就去，在监里斩了约翰，","notes":[]},{"n":28,"t":"把头放在盘子里，拿来给女子，女子就给她母亲。","notes":[]},{"n":29,"t":"约翰的门徒听见了，就来把他的尸首领去，葬在坟墓里。","notes":[]},{"n":30,"t":"使徒聚集到耶稣那里，将一切所做的事、所传的道全告诉他。","notes":[],"heads":["耶稣给五千人吃饱"]},{"n":31,"t":"他就说：「你们来，同我暗暗地到旷野地方去歇一歇。」这是因为来往的人多，他们连吃饭也没有工夫。","notes":[]},{"n":32,"t":"他们就坐船，暗暗地往旷野地方去。","notes":[]},{"n":33,"t":"众人看见他们去，有许多认识他们的，就从各城步行，一同跑到那里，比他们先赶到了。","notes":[]},{"n":34,"t":"耶稣出来，见有许多的人，就怜悯他们，因为他们如同羊没有牧人一般，于是开口教训他们许多道理。","notes":[]},{"n":35,"t":"天已经晚了，门徒进前来，说：「这是野地，天已经晚了，","notes":[]},{"n":36,"t":"请叫众人散开，他们好往四面乡村里去，自己买什么吃。」","notes":[]},{"n":37,"t":"耶稣回答说：「你们给他们吃吧。」门徒说：「我们可以去买二十两银子的饼给他们吃吗？」","notes":[]},{"n":38,"t":"耶稣说：「你们有多少饼，可以去看看。」他们知道了，就说：「五个饼，两条鱼。」","notes":[]},{"n":39,"t":"耶稣吩咐他们，叫众人一帮一帮地坐在青草地上。","notes":[]},{"n":40,"t":"众人就一排一排地坐下，有一百一排的，有五十一排的。","notes":[]},{"n":41,"t":"耶稣拿着这五个饼，两条鱼，望着天祝福，擘开饼，递给门徒，摆在众人面前，也把那两条鱼分给众人。","notes":[]},{"n":42,"t":"他们都吃，并且吃饱了。","notes":[]},{"n":43,"t":"门徒就把碎饼碎鱼收拾起来，装满了十二个篮子。","notes":[]},{"n":44,"t":"吃饼的男人共有五千。","notes":[]},{"n":45,"t":"耶稣随即催门徒上船，先渡到那边伯赛大去，等他叫众人散开。","notes":[],"heads":["耶稣在海上行走"]},{"n":46,"t":"他既辞别了他们，就往山上去祷告。","notes":[]},{"n":47,"t":"到了晚上，船在海中，耶稣独自在岸上；","notes":[]},{"n":48,"t":"看见门徒因风不顺，摇橹甚苦。夜里约有四更天，就在海面上走，往他们那里去，意思要走过他们去。","notes":[]},{"n":49,"t":"但门徒看见他在海面上走，以为是鬼怪，就喊叫起来；","notes":[]},{"n":50,"t":"因为他们都看见了他，且甚惊慌。耶稣连忙对他们说：「你们放心！是我，不要怕！」","notes":[]},{"n":51,"t":"于是到他们那里，上了船，风就住了；他们心里十分惊奇。","notes":[]},{"n":52,"t":"这是因为他们不明白那分饼的事，心里还是愚顽。","notes":[]},{"n":53,"t":"既渡过去，来到革尼撒勒地方，就靠了岸，","notes":[],"heads":["治好革尼撒勒的病人"]},{"n":54,"t":"一下船，众人认得是耶稣，","notes":[]},{"n":55,"t":"就跑遍那一带地方，听见他在何处，便将有病的人用褥子抬到那里。","notes":[]},{"n":56,"t":"凡耶稣所到的地方，或村中，或城里，或乡间，他们都将病人放在街市上，求耶稣只容他们摸他的衣裳繸子；凡摸着的人就都好了。","notes":[]}]},"7":{"heading":"古人的传统","verses":[{"n":1,"t":"有法利赛人和几个文士从耶路撒冷来，到耶稣那里聚集。","notes":[]},{"n":2,"t":"他们曾看见他的门徒中有人用俗手，就是没有洗的手，吃饭。（","notes":[]},{"n":3,"t":"原来法利赛人和犹太人都拘守古人的遗传，若不仔细洗手就不吃饭；","notes":[]},{"n":4,"t":"从市上来，若不洗浴也不吃饭；还有好些别的规矩，他们历代拘守，就是洗杯、罐、铜器等物。）","notes":[]},{"n":5,"t":"法利赛人和文士问他说：「你的门徒为什么不照古人的遗传，用俗手吃饭呢？」","notes":[]},{"n":6,"t":"耶稣说：「以赛亚指着你们假冒为善之人所说的预言是不错的。如经上说：这百姓用嘴唇尊敬我，心却远离我。","notes":[]},{"n":7,"t":"他们将人的吩咐当作道理教导人，所以拜我也是枉然。","notes":[]},{"n":8,"t":"你们是离弃神的诫命，拘守人的遗传」；","notes":[]},{"n":9,"t":"又说：「你们诚然是废弃神的诫命，要守自己的遗传。","notes":[]},{"n":10,"t":"摩西说：『当孝敬父母』；又说：『咒骂父母的，必治死他。』","notes":[]},{"n":11,"t":"你们倒说：『人若对父母说：我所当奉给你的，已经作了各耳板』（各耳板就是供献的意思），","notes":[]},{"n":12,"t":"以后你们就不容他再奉养父母。","notes":[]},{"n":13,"t":"这就是你们承接遗传，废了神的道。你们还做许多这样的事。」","notes":[]},{"n":14,"t":"耶稣又叫众人来，对他们说：「你们都要听我的话，也要明白。","notes":[]},{"n":15,"t":"从外面进去的不能污秽人，惟有从里面出来的乃能污秽人。」","notes":["有古卷加：16有耳可听的，就应当听！"]},{"n":17,"t":"耶稣离开众人，进了屋子，门徒就问他这比喻的意思。","notes":[]},{"n":18,"t":"耶稣对他们说：「你们也是这样不明白吗？岂不晓得凡从外面进入的，不能污秽人，","notes":[]},{"n":19,"t":"因为不是入他的心，乃是入他的肚腹，又落到茅厕里（这是说，各样的食物都是洁净的）」；","notes":[]},{"n":20,"t":"又说：「从人里面出来的，那才能污秽人；","notes":[]},{"n":21,"t":"因为从里面，就是从人心里，发出恶念、苟合、","notes":[]},{"n":22,"t":"偷盗、凶杀、奸淫、贪婪、邪恶、诡诈、淫荡、嫉妒、谤讟、骄傲、狂妄。","notes":[]},{"n":23,"t":"这一切的恶都是从里面出来，且能污秽人。」","notes":[]},{"n":24,"t":"耶稣从那里起身，往泰尔、西顿的境内去，进了一家，不愿意人知道，却隐藏不住。","notes":[],"heads":["一个妇人的信心"]},{"n":25,"t":"当下，有一个妇人，她的小女儿被污鬼附着，听见耶稣的事，就来俯伏在他脚前。","notes":[]},{"n":26,"t":"这妇人是希腊人，属叙利腓尼基族。她求耶稣赶出那鬼离开她的女儿。","notes":[]},{"n":27,"t":"耶稣对她说：「让儿女们先吃饱，不好拿儿女的饼丢给狗吃。」","notes":[]},{"n":28,"t":"妇人回答说：「主啊，不错；但是狗在桌子底下也吃孩子们的碎渣儿。」","notes":[]},{"n":29,"t":"耶稣对她说：「因这句话，你回去吧；鬼已经离开你的女儿了。」","notes":[]},{"n":30,"t":"她就回家去，见小孩子躺在床上，鬼已经出去了。","notes":[]},{"n":31,"t":"耶稣又离了泰尔的境界，经过西顿，就从低加坡里境内来到加利利 海。","notes":[],"heads":["耶稣治好耳聋舌结的人"]},{"n":32,"t":"有人带着一个耳聋舌结的人来见耶稣，求他按手在他身上。","notes":[]},{"n":33,"t":"耶稣领他离开众人，到一边去，就用指头探他的耳朵，吐唾沫抹他的舌头，","notes":[]},{"n":34,"t":"望天叹息，对他说：「以法大！」就是说：「开了吧！」","notes":[]},{"n":35,"t":"他的耳朵就开了，舌结也解了，说话也清楚了。","notes":[]},{"n":36,"t":"耶稣嘱咐他们不要告诉人；但他越发嘱咐，他们越发传扬开了。","notes":[]},{"n":37,"t":"众人分外希奇，说：「他所做的事都好，他连聋子也叫他们听见，哑巴也叫他们说话。」","notes":[]}]},"8":{"heading":"耶稣给四千人吃饱","verses":[{"n":1,"t":"那时，又有许多人聚集，并没有什么吃的。耶稣叫门徒来，说：","notes":[]},{"n":2,"t":"「我怜悯这众人；因为他们同我在这里已经三天，也没有吃的了。","notes":[]},{"n":3,"t":"我若打发他们饿着回家，就必在路上困乏，因为其中有从远处来的。」","notes":[]},{"n":4,"t":"门徒回答说：「在这野地，从哪里能得饼，叫这些人吃饱呢？」","notes":[]},{"n":5,"t":"耶稣问他们说：「你们有多少饼？」他们说：「七个。」","notes":[]},{"n":6,"t":"他吩咐众人坐在地上，就拿着这七个饼祝谢了，擘开，递给门徒，叫他们摆开，门徒就摆在众人面前。","notes":[]},{"n":7,"t":"又有几条小鱼；耶稣祝了福，就吩咐也摆在众人面前。","notes":[]},{"n":8,"t":"众人都吃，并且吃饱了，收拾剩下的零碎，有七筐子。","notes":[]},{"n":9,"t":"人数约有四千。耶稣打发他们走了，","notes":[]},{"n":10,"t":"随即同门徒上船，来到大玛努他境内。","notes":[]},{"n":11,"t":"法利赛人出来盘问耶稣，求他从天上显个神迹给他们看，想要试探他。","notes":[],"heads":["求主显个神迹"]},{"n":12,"t":"耶稣心里深深地叹息，说：「这世代为什么求神迹呢？我实在告诉你们，没有神迹给这世代看。」","notes":[]},{"n":13,"t":"他就离开他们，又上船往海那边去了。","notes":[]},{"n":14,"t":"门徒忘了带饼；在船上除了一个饼，没有别的食物。","notes":[],"heads":["防备法利赛人和希律的酵"]},{"n":15,"t":"耶稣嘱咐他们说：「你们要谨慎，防备法利赛人的酵和希律的酵。」","notes":[]},{"n":16,"t":"他们彼此议论说：「这是因为我们没有饼吧。」","notes":[]},{"n":17,"t":"耶稣看出来，就说：「你们为什么因为没有饼就议论呢？你们还不省悟，还不明白吗？你们的心还是愚顽吗？","notes":[]},{"n":18,"t":"你们有眼睛，看不见吗？有耳朵，听不见吗？也不记得吗？","notes":[]},{"n":19,"t":"我擘开那五个饼分给五千人，你们收拾的零碎装满了多少篮子呢？」他们说：「十二个。」","notes":[]},{"n":20,"t":"「又擘开那七个饼分给四千人，你们收拾的零碎装满了多少筐子呢？」他们说：「七个。」","notes":[]},{"n":21,"t":"耶稣说：「你们还是不明白吗？」","notes":[]},{"n":22,"t":"他们来到伯赛大，有人带一个瞎子来，求耶稣摸他。","notes":[],"heads":["治好伯赛大的瞎子"]},{"n":23,"t":"耶稣拉着瞎子的手，领他到村外，就吐唾沫在他眼睛上，按手在他身上，问他说：「你看见什么了？」","notes":[]},{"n":24,"t":"他就抬头一看，说：「我看见人了；他们好像树木，并且行走。」","notes":[]},{"n":25,"t":"随后又按手在他眼睛上，他定睛一看，就复了原，样样都看得清楚了。","notes":[]},{"n":26,"t":"耶稣打发他回家，说：「连这村子你也不要进去。」","notes":[]},{"n":27,"t":"耶稣和门徒出去，往凯撒利亚·腓立比村庄去；在路上问门徒说：「人说我是谁？」","notes":[],"heads":["彼得认耶稣为基督"]},{"n":28,"t":"他们说：「有人说是施洗的约翰；有人说是以利亚；又有人说是先知里的一位。」","notes":[]},{"n":29,"t":"又问他们说：「你们说我是谁？」彼得回答说：「你是基督。」","notes":[]},{"n":30,"t":"耶稣就禁戒他们，不要告诉人。","notes":[]},{"n":31,"t":"从此，他教训他们说：「人子必须受许多的苦，被长老、祭司长，和文士弃绝，并且被杀，过三天复活。」","notes":[],"heads":["耶稣预言受难和复活"]},{"n":32,"t":"耶稣明明地说这话，彼得就拉着他，劝他。","notes":[]},{"n":33,"t":"耶稣转过来，看着门徒，就责备彼得说：「撒但，退我后边去吧！因为你不体贴神的意思，只体贴人的意思。」","notes":[]},{"n":34,"t":"于是叫众人和门徒来，对他们说：「若有人要跟从我，就当舍己，背起他的十字架来跟从我。","notes":[]},{"n":35,"t":"因为，凡要救自己生命的，必丧掉生命；凡为我和福音丧掉生命的，必救了生命。","notes":["或译：灵魂；下同"]},{"n":36,"t":"人就是赚得全世界，赔上自己的生命，有什么益处呢？","notes":[]},{"n":37,"t":"人还能拿什么换生命呢？","notes":[]},{"n":38,"t":"凡在这淫乱罪恶的世代，把我和我的道当作可耻的，人子在他父的荣耀里，同圣天使降临的时候，也要把那人当作可耻的。」","notes":[]}]},"9":{"heading":"耶稣改变形象","verses":[{"n":1,"t":"耶稣又对他们说：「我实在告诉你们，站在这里的，有人在没尝死味以前，必要看见神的国大有能力临到。」","notes":[]},{"n":2,"t":"过了六天，耶稣带着彼得、雅各、约翰暗暗地上了高山，就在他们面前变了形象，","notes":[]},{"n":3,"t":"衣服放光，极其洁白，地上漂布的，没有一个能漂得那样白。","notes":[]},{"n":4,"t":"忽然，有以利亚同摩西向他们显现，并且和耶稣说话。","notes":[]},{"n":5,"t":"彼得对耶稣说：「拉比，我们在这里真好！可以搭三座棚，一座为你，一座为摩西，一座为以利亚。」","notes":["就是夫子"]},{"n":6,"t":"彼得不知道说什么才好，因为他们甚是惧怕。","notes":[]},{"n":7,"t":"有一朵云彩来遮盖他们；也有声音从云彩里出来，说：「这是我的爱子，你们要听他。」","notes":[]},{"n":8,"t":"门徒忽然周围一看，不再见一人，只见耶稣同他们在那里。","notes":[]},{"n":9,"t":"下山的时候，耶稣嘱咐他们说：「人子还没有从死里复活，你们不要将所看见的告诉人。」","notes":[]},{"n":10,"t":"门徒将这话存记在心，彼此议论「从死里复活」是什么意思。","notes":[]},{"n":11,"t":"他们就问耶稣说：「文士为什么说以利亚必须先来？」","notes":[]},{"n":12,"t":"耶稣说：「以利亚固然先来复兴万事；经上不是指着人子说，他要受许多的苦被人轻慢呢？","notes":[]},{"n":13,"t":"我告诉你们，以利亚已经来了，他们也任意待他，正如经上所指着他的话。」","notes":[]},{"n":14,"t":"耶稣到了门徒那里，看见有许多人围着他们，又有文士和他们辩论。","notes":[],"heads":["治好被污鬼附身的孩子"]},{"n":15,"t":"众人一见耶稣，都甚希奇，就跑上去问他的安。","notes":[]},{"n":16,"t":"耶稣问他们说：「你们和他们辩论的是什么？」","notes":[]},{"n":17,"t":"众人中间有一个人回答说：「夫子，我带了我的儿子到你这里来，他被哑巴鬼附着。","notes":[]},{"n":18,"t":"无论在哪里，鬼捉弄他，把他摔倒，他就口中流沫，咬牙切齿，身体枯干。我请过你的门徒把鬼赶出去，他们却是不能。」","notes":[]},{"n":19,"t":"耶稣说：「嗳！不信的世代啊，我在你们这里要到几时呢？我忍耐你们要到几时呢？把他带到我这里来吧。」","notes":[]},{"n":20,"t":"他们就带了他来。他一见耶稣，鬼便叫他重重地抽风，倒在地上，翻来覆去，口中流沫。","notes":[]},{"n":21,"t":"耶稣问他父亲说：「他得这病有多少日子呢？」回答说：「从小的时候。","notes":[]},{"n":22,"t":"鬼屡次把他扔在火里、水里，要灭他。你若能做什么，求你怜悯我们，帮助我们。」","notes":[]},{"n":23,"t":"耶稣对他说：「你若能信，在信的人，凡事都能。」","notes":[]},{"n":24,"t":"孩子的父亲立时喊着说：「我信！但我信不足，求主帮助。」","notes":["有古卷：立时流泪地喊着说"]},{"n":25,"t":"耶稣看见众人都跑上来，就斥责那污鬼，说：「你这聋哑的鬼，我吩咐你从他里头出来，再不要进去！」","notes":[]},{"n":26,"t":"那鬼喊叫，使孩子大大地抽了一阵风，就出来了。孩子好像死了一般，以致众人多半说：「他是死了。」","notes":[]},{"n":27,"t":"但耶稣拉着他的手，扶他起来，他就站起来了。","notes":[]},{"n":28,"t":"耶稣进了屋子，门徒就暗暗地问他说：「我们为什么不能赶出他去呢？」","notes":[]},{"n":29,"t":"耶稣说：「非用祷告，这一类的鬼总不能出来。」","notes":["有古卷加：禁食二字","或译：不能赶他出来"]},{"n":30,"t":"他们离开那地方，经过加利利；耶稣不愿意人知道。","notes":[],"heads":["耶稣第二次预言受难和复活"]},{"n":31,"t":"于是教训门徒，说：「人子将要被交在人手里，他们要杀害他；被杀以后，过三天他要复活。」","notes":[]},{"n":32,"t":"门徒却不明白这话，又不敢问他。","notes":[]},{"n":33,"t":"他们来到迦百农。耶稣在屋里问门徒说：「你们在路上议论的是什么？」","notes":[],"heads":["谁最伟大"]},{"n":34,"t":"门徒不作声，因为他们在路上彼此争论谁为大。","notes":[]},{"n":35,"t":"耶稣坐下，叫十二个门徒来，说：「若有人愿意作首先的，他必作众人末后的，作众人的用人。」","notes":[]},{"n":36,"t":"于是领过一个小孩子来，叫他站在门徒中间，又抱起他来，对他们说：","notes":[]},{"n":37,"t":"「凡为我名接待一个像这小孩子的，就是接待我；凡接待我的，不是接待我，乃是接待那差我来的。」","notes":[]},{"n":38,"t":"约翰对耶稣说：「夫子，我们看见一个人奉你的名赶鬼，我们就禁止他，因为他不跟从我们。」","notes":[],"heads":["不敌挡我们就是帮助我们"]},{"n":39,"t":"耶稣说：「不要禁止他；因为没有人奉我名行异能，反倒轻易毁谤我。","notes":[]},{"n":40,"t":"不敌挡我们的，就是帮助我们的。","notes":[]},{"n":41,"t":"凡因你们是属基督，给你们一杯水喝的，我实在告诉你们，他不能不得赏赐。」","notes":[]},{"n":42,"t":"「凡使这信我的一个小子跌倒的，倒不如把大磨石拴在这人的颈项上，扔在海里。","notes":[],"heads":["罪的诱惑"]},{"n":43,"t":"倘若你一只手叫你跌倒，就把它砍下来；","notes":[]},{"n":44,"t":"你缺了肢体进入永生，强如有两只手落到地狱，入那不灭的火里去。","notes":[]},{"n":45,"t":"倘若你一只脚叫你跌倒，就把它砍下来；","notes":[]},{"n":46,"t":"你瘸腿进入永生，强如有两只脚被丢在地狱里。","notes":[]},{"n":47,"t":"倘若你一只眼叫你跌倒，就去掉它；你只有一只眼进入神的国，强如有两只眼被丢在地狱里。","notes":[]},{"n":48,"t":"在那里，虫是不死的，火是不灭的。","notes":[]},{"n":49,"t":"因为必用火当盐腌各人。","notes":["有古卷加：凡祭物必用盐腌。"]},{"n":50,"t":"盐本是好的，若失了味，可用什么叫它再咸呢？你们里头应当有盐，彼此和睦。」","notes":[]}]},"10":{"heading":"休妻的问题","verses":[{"n":1,"t":"耶稣从那里起身，来到犹太的境界并约旦河外。众人又聚集到他那里，他又照常教训他们。","notes":[]},{"n":2,"t":"有法利赛人来问他说：「人休妻可以不可以？」意思要试探他。","notes":[]},{"n":3,"t":"耶稣回答说：「摩西吩咐你们的是什么？」","notes":[]},{"n":4,"t":"他们说：「摩西许人写了休书便可以休妻。」","notes":[]},{"n":5,"t":"耶稣说：「摩西因为你们的心硬，所以写这条例给你们；","notes":[]},{"n":6,"t":"但从起初创造的时候，神造人是造男造女。","notes":[]},{"n":7,"t":"因此，人要离开父母，与妻子连合，二人成为一体。","notes":[]},{"n":8,"t":"既然如此，夫妻不再是两个人，乃是一体的了。","notes":[]},{"n":9,"t":"所以，神配合的，人不可分开。」","notes":[]},{"n":10,"t":"到了屋里，门徒就问他这事。","notes":[]},{"n":11,"t":"耶稣对他们说：「凡休妻另娶的，就是犯奸淫，辜负他的妻子；","notes":[]},{"n":12,"t":"妻子若离弃丈夫另嫁，也是犯奸淫了。」","notes":[]},{"n":13,"t":"有人带着小孩子来见耶稣，要耶稣摸他们，门徒便责备那些人。","notes":[],"heads":["耶稣为小孩祝福"]},{"n":14,"t":"耶稣看见就恼怒，对门徒说：「让小孩子到我这里来，不要禁止他们；因为在神国的，正是这样的人。","notes":[]},{"n":15,"t":"我实在告诉你们，凡要承受神国的，若不像小孩子，断不能进去。」","notes":[]},{"n":16,"t":"于是抱着小孩子，给他们按手，为他们祝福。","notes":[]},{"n":17,"t":"耶稣出来行路的时候，有一个人跑来，跪在他面前，问他说：「良善的夫子，我当做什么事才可以承受永生？」","notes":[],"heads":["财主寻求永生之道"]},{"n":18,"t":"耶稣对他说：「你为什么称我是良善的？除了神一位之外，再没有良善的。","notes":[]},{"n":19,"t":"诫命你是晓得的：不可杀人；不可奸淫；不可偷盗；不可作假见证；不可亏负人；当孝敬父母。」","notes":[]},{"n":20,"t":"他对耶稣说：「夫子，这一切我从小都遵守了。」","notes":[]},{"n":21,"t":"耶稣看着他，就爱他，对他说：「你还缺少一件：去变卖你所有的，分给穷人，就必有财宝在天上；你还要来跟从我。」","notes":[]},{"n":22,"t":"他听见这话，脸上就变了色，忧忧愁愁地走了，因为他的产业很多。","notes":[]},{"n":23,"t":"耶稣周围一看，对门徒说：「有钱财的人进神的国是何等地难哪！」","notes":[]},{"n":24,"t":"门徒希奇他的话。耶稣又对他们说：「小子，倚靠钱财的人进神的国是何等地难哪！","notes":[]},{"n":25,"t":"骆驼穿过针的眼，比财主进神的国还容易呢。」","notes":[]},{"n":26,"t":"门徒就分外希奇，对他说：「这样谁能得救呢？」","notes":[]},{"n":27,"t":"耶稣看着他们，说：「在人是不能，在神却不然，因为神凡事都能。」","notes":[]},{"n":28,"t":"彼得就对他说：「看哪，我们已经撇下所有的跟从你了。」","notes":[]},{"n":29,"t":"耶稣说：「我实在告诉你们，人为我和福音撇下房屋，或是弟兄、姊妹、父母、儿女、田地，","notes":[]},{"n":30,"t":"没有不在今世得百倍的，就是房屋、弟兄、姊妹、母亲、儿女、田地，并且要受逼迫，在来世必得永生。","notes":[]},{"n":31,"t":"然而，有许多在前的，将要在后，在后的，将要在前。」","notes":[]},{"n":32,"t":"他们行路上耶路撒冷去。耶稣在前头走，门徒就希奇，跟从的人也害怕。耶稣又叫过十二个门徒来，把自己将要遭遇的事告诉他们说：","notes":[],"heads":["耶稣第三次预言受难和复活"]},{"n":33,"t":"「看哪，我们上耶路撒冷去，人子将要被交给祭司长和文士，他们要定他死罪，交给外邦人。","notes":[]},{"n":34,"t":"他们要戏弄他，吐唾沫在他脸上，鞭打他，杀害他。过了三天，他要复活。」","notes":[]},{"n":35,"t":"西庇太的儿子雅各、约翰进前来，对耶稣说：「夫子，我们无论求你什么，愿你给我们做。」","notes":[],"heads":["雅各和约翰的要求"]},{"n":36,"t":"耶稣说：「要我给你们做什么？」","notes":[]},{"n":37,"t":"他们说：「赐我们在你的荣耀里，一个坐在你右边，一个坐在你左边。」","notes":[]},{"n":38,"t":"耶稣说：「你们不知道所求的是什么。我所喝的杯，你们能喝吗？我所受的洗，你们能受吗？」","notes":[]},{"n":39,"t":"他们说：「我们能。」耶稣说：「我所喝的杯，你们也要喝；我所受的洗，你们也要受；","notes":[]},{"n":40,"t":"只是坐在我的左右，不是我可以赐的，乃是为谁预备的，就赐给谁。」","notes":[]},{"n":41,"t":"那十个门徒听见，就恼怒雅各、约翰。","notes":[]},{"n":42,"t":"耶稣叫他们来，对他们说：「你们知道，外邦人有尊为君王的，治理他们，有大臣操权管束他们。","notes":[]},{"n":43,"t":"只是在你们中间，不是这样。你们中间，谁愿为大，就必作你们的用人；","notes":[]},{"n":44,"t":"在你们中间，谁愿为首，就必作众人的仆人。","notes":[]},{"n":45,"t":"因为人子来，并不是要受人的服事，乃是要服事人，并且要舍命作多人的赎价。」","notes":[]},{"n":46,"t":"到了耶利哥；耶稣同门徒并许多人出耶利哥的时候，有一个讨饭的瞎子，是底买的儿子巴底买，坐在路旁。","notes":[],"heads":["治好瞎子巴底买"]},{"n":47,"t":"他听见是拿撒勒的耶稣，就喊着说：「大卫的子孙耶稣啊！可怜我吧！」","notes":[]},{"n":48,"t":"有许多人责备他，不许他作声。他却越发大声喊着说：「大卫的子孙哪，可怜我吧！」","notes":[]},{"n":49,"t":"耶稣就站住，说：「叫过他来。」他们就叫那瞎子，对他说：「放心，起来！他叫你啦。」","notes":[]},{"n":50,"t":"瞎子就丢下衣服，跳起来，走到耶稣那里。","notes":[]},{"n":51,"t":"耶稣说：「要我为你做什么？」瞎子说：「拉波尼，我要能看见。」","notes":["就是夫子"]},{"n":52,"t":"耶稣说：「你去吧！你的信救了你了。」瞎子立刻看见了，就在路上跟随耶稣。","notes":[]}]},"11":{"heading":"光荣地进耶路撒冷","verses":[{"n":1,"t":"耶稣和门徒将近耶路撒冷，到了伯法其和伯大尼，在橄榄山那里；耶稣就打发两个门徒，","notes":[]},{"n":2,"t":"对他们说：「你们往对面村子里去，一进去的时候，必看见一匹驴驹拴在那里，是从来没有人骑过的，可以解开，牵来。","notes":[]},{"n":3,"t":"若有人对你们说：『为什么做这事？』你们就说：『主要用它。』那人必立时让你们牵来。」","notes":[]},{"n":4,"t":"他们去了，便看见一匹驴驹拴在门外街道上，就把它解开。","notes":[]},{"n":5,"t":"在那里站着的人，有几个说：「你们解驴驹做什么？」","notes":[]},{"n":6,"t":"门徒照着耶稣所说的回答，那些人就任凭他们牵去了。","notes":[]},{"n":7,"t":"他们把驴驹牵到耶稣那里，把自己的衣服搭在上面，耶稣就骑上。","notes":[]},{"n":8,"t":"有许多人把衣服铺在路上，也有人把田间的树枝砍下来，铺在路上。","notes":[]},{"n":9,"t":"前行后随的人都喊着说：和散那！奉主名来的是应当称颂的！","notes":["和散那：原有求救的意思，在此乃是称颂的话"]},{"n":10,"t":"那将要来的我祖大卫之国是应当称颂的！高高在上和散那！","notes":[]},{"n":11,"t":"耶稣进了耶路撒冷，入了圣殿，周围看了各样物件。天色已晚，就和十二个门徒出城，往伯大尼去了。","notes":[]},{"n":12,"t":"第二天，他们从伯大尼出来，耶稣饿了。","notes":[],"heads":["咒诅无花果树"]},{"n":13,"t":"远远地看见一棵无花果树，树上有叶子，就往那里去，或者在树上可以找着什么。到了树下，竟找不着什么，不过有叶子，因为不是收无花果的时候。","notes":[]},{"n":14,"t":"耶稣就对树说：「从今以后，永没有人吃你的果子。」他的门徒也听见了。","notes":[]},{"n":15,"t":"他们来到耶路撒冷。耶稣进入圣殿，赶出殿里做买卖的人，推倒兑换银钱之人的桌子和卖鸽子之人的凳子；","notes":[],"heads":["洁净圣殿"]},{"n":16,"t":"也不许人拿着器具从殿里经过；","notes":[]},{"n":17,"t":"便教训他们说：「经上不是记着说：我的殿必称为万国祷告的殿吗？你们倒使它成为贼窝了。」","notes":[]},{"n":18,"t":"祭司长和文士听见这话，就想法子要除灭耶稣，却又怕他，因为众人都希奇他的教训。","notes":[]},{"n":19,"t":"每天晚上，耶稣出城去。","notes":[]},{"n":20,"t":"早晨，他们从那里经过，看见无花果树连根都枯干了。","notes":[],"heads":["从无花果树得教训"]},{"n":21,"t":"彼得想起耶稣的话来，就对他说：「拉比，请看！你所咒诅的无花果树已经枯干了。」","notes":[]},{"n":22,"t":"耶稣回答说：「你们当信服神。","notes":[]},{"n":23,"t":"我实在告诉你们，无论何人对这座山说：『你挪开此地，投在海里！』他若心里不疑惑，只信他所说的必成，就必给他成了。","notes":[]},{"n":24,"t":"所以我告诉你们，凡你们祷告祈求的，无论是什么，只要信是得着的，就必得着。","notes":[]},{"n":25,"t":"你们站着祷告的时候，若想起有人得罪你们，就当饶恕他，好叫你们在天上的父也饶恕你们的过犯。","notes":[]},{"n":26,"t":"你们若不饶恕人，你们在天上的父也不饶恕你们的过犯。」","notes":["有古卷无此节"]},{"n":27,"t":"他们又来到耶路撒冷。耶稣在殿里行走的时候，祭司长和文士并长老进前来，","notes":[],"heads":["质问耶稣的权柄"]},{"n":28,"t":"问他说：「你仗着什么权柄做这些事？给你这权柄的是谁呢？」","notes":[]},{"n":29,"t":"耶稣对他们说：「我要问你们一句话，你们回答我，我就告诉你们我仗着什么权柄做这些事。","notes":[]},{"n":30,"t":"约翰的洗礼是从天上来的？是从人间来的呢？你们可以回答我。」","notes":[]},{"n":31,"t":"他们彼此商议说：「我们若说『从天上来』，他必说：『这样，你们为什么不信他呢？』","notes":[]},{"n":32,"t":"若说『从人间来』，却又怕百姓，因为众人真以约翰为先知。」","notes":[]},{"n":33,"t":"于是回答耶稣说：「我们不知道。」耶稣说：「我也不告诉你们我仗着什么权柄做这些事。」","notes":[]}]},"12":{"heading":"凶恶园户的比喻","verses":[{"n":1,"t":"耶稣就用比喻对他们说：「有人栽了一个葡萄园，周围圈上篱笆，挖了一个压酒池，盖了一座楼，租给园户，就往外国去了。","notes":[]},{"n":2,"t":"到了时候，打发一个仆人到园户那里，要从园户收葡萄园的果子。","notes":[]},{"n":3,"t":"园户拿住他，打了他，叫他空手回去。","notes":[]},{"n":4,"t":"再打发一个仆人到他们那里。他们打伤他的头，并且凌辱他。","notes":[]},{"n":5,"t":"又打发一个仆人去，他们就杀了他。后又打发好些仆人去，有被他们打的，有被他们杀的。","notes":[]},{"n":6,"t":"园主还有一位是他的爱子，末后又打发他去，意思说：『他们必尊敬我的儿子。』","notes":[]},{"n":7,"t":"不料，那些园户彼此说：『这是承受产业的。来吧，我们杀他，产业就归我们了！』","notes":[]},{"n":8,"t":"于是拿住他，杀了他，把他丢在园外。","notes":[]},{"n":9,"t":"这样，葡萄园的主人要怎么办呢？他要来除灭那些园户，将葡萄园转给别人。","notes":[]},{"n":10,"t":"经上写着说：匠人所弃的石头已作了房角的头块石头。","notes":[]},{"n":11,"t":"这是主所做的，在我们眼中看为希奇。这经你们没有念过吗？」","notes":[]},{"n":12,"t":"他们看出这比喻是指着他们说的，就想要捉拿他，只是惧怕百姓，于是离开他走了。","notes":[]},{"n":13,"t":"后来，他们打发几个法利赛人和几个希律党的人到耶稣那里，要就着他的话陷害他。","notes":[],"heads":["纳税给凯撒的问题"]},{"n":14,"t":"他们来了，就对他说：「夫子，我们知道你是诚实的，什么人你都不徇情面；因为你不看人的外貌，乃是诚诚实实传神的道。纳税给凯撒可以不可以？","notes":[]},{"n":15,"t":"我们该纳不该纳？」耶稣知道他们的假意，就对他们说：「你们为什么试探我？拿一个银钱来给我看！」","notes":[]},{"n":16,"t":"他们就拿了来。耶稣说：「这像和这号是谁的？」他们说：「是凯撒的。」","notes":[]},{"n":17,"t":"耶稣说：「凯撒的物当归给凯撒，神的物当归给神。」他们就很希奇他。","notes":[]},{"n":18,"t":"撒都该人常说没有复活的事。他们来问耶稣说：","notes":[],"heads":["复活的问题"]},{"n":19,"t":"「夫子，摩西为我们写着说：『人若死了，撇下妻子，没有孩子，他兄弟当娶他的妻，为哥哥生子立后。』","notes":[]},{"n":20,"t":"有弟兄七人，第一个娶了妻，死了，没有留下孩子。","notes":[]},{"n":21,"t":"第二个娶了她，也死了，没有留下孩子。第三个也是这样。","notes":[]},{"n":22,"t":"那七个人都没有留下孩子；末了，那妇人也死了。","notes":[]},{"n":23,"t":"当复活的时候，她是哪一个的妻子呢？因为他们七个人都娶过她。」","notes":[]},{"n":24,"t":"耶稣说：「你们所以错了，岂不是因为不明白圣经，不晓得神的大能吗？","notes":[]},{"n":25,"t":"人从死里复活，也不娶也不嫁，乃像天上的使者一样。","notes":[]},{"n":26,"t":"论到死人复活，你们没有念过摩西的书荆棘篇上所载的吗？神对摩西说：『我是亚伯拉罕的神，以撒的神，雅各的神。』","notes":[]},{"n":27,"t":"神不是死人的神，乃是活人的神。你们是大错了。」","notes":[]},{"n":28,"t":"有一个文士来，听见他们辩论，晓得耶稣回答的好，就问他说：「诫命中哪是第一要紧的呢？」","notes":[],"heads":["最大的诫命"]},{"n":29,"t":"耶稣回答说：「第一要紧的就是说：『以色列啊，你要听，主—我们神是独一的主。","notes":[]},{"n":30,"t":"你要尽心、尽性、尽意、尽力爱主—你的神。』","notes":[]},{"n":31,"t":"其次就是说：『要爱人如己。』再没有比这两条诫命更大的了。」","notes":[]},{"n":32,"t":"那文士对耶稣说：「夫子说，神是一位，实在不错；除了他以外，再没有别的神；","notes":[]},{"n":33,"t":"并且尽心、尽智、尽力爱他，又爱人如己，就比一切燔祭和各样祭祀好的多。」","notes":[]},{"n":34,"t":"耶稣见他回答的有智慧，就对他说：「你离神的国不远了。」从此以后，没有人敢再问他什么。","notes":[]},{"n":35,"t":"耶稣在殿里教训人，就问他们说：「文士怎么说基督是大卫的子孙呢？","notes":[],"heads":["大卫子孙的问题"]},{"n":36,"t":"大卫被圣灵感动，说：主对我主说：你坐在我的右边，等我使你仇敌作你的脚凳。","notes":[]},{"n":37,"t":"大卫既自己称他为主，他怎么又是大卫的子孙呢？」众人都喜欢听他。","notes":[]},{"n":38,"t":"耶稣在教训之间，说：「你们要防备文士；他们好穿长衣游行，喜爱人在街市上问他们的安，","notes":[],"heads":["谴责文士"]},{"n":39,"t":"又喜爱会堂里的高位，筵席上的首座。","notes":[]},{"n":40,"t":"他们侵吞寡妇的家产，假意作很长的祷告。这些人要受更重的刑罚！」","notes":[]},{"n":41,"t":"耶稣对银库坐着，看众人怎样投钱入库。有好些财主往里投了若干的钱。","notes":[],"heads":["寡妇的奉献"]},{"n":42,"t":"有一个穷寡妇来，往里投了两个小钱，就是一个大钱。","notes":[]},{"n":43,"t":"耶稣叫门徒来，说：「我实在告诉你们，这穷寡妇投入库里的，比众人所投的更多。","notes":[]},{"n":44,"t":"因为，他们都是自己有余，拿出来投在里头；但这寡妇是自己不足，把她一切养生的都投上了。」","notes":[]}]},"13":{"heading":"预言圣殿被毁","verses":[{"n":1,"t":"耶稣从殿里出来的时候，有一个门徒对他说：「夫子，请看，这是何等的石头！何等的殿宇！」","notes":[]},{"n":2,"t":"耶稣对他说：「你看见这大殿宇吗？将来在这里没有一块石头留在石头上，不被拆毁了。」","notes":[]},{"n":3,"t":"耶稣在橄榄山上对圣殿而坐。彼得、雅各、约翰，和安得烈暗暗地问他说：","notes":[],"heads":["灾难的起头"]},{"n":4,"t":"「请告诉我们，什么时候有这些事呢？这一切事将成的时候有什么预兆呢？」","notes":[]},{"n":5,"t":"耶稣说：「你们要谨慎，免得有人迷惑你们。","notes":[]},{"n":6,"t":"将来有好些人冒我的名来，说：『我是基督』，并且要迷惑许多人。","notes":[]},{"n":7,"t":"你们听见打仗和打仗的风声，不要惊慌。这些事是必须有的，只是末期还没有到。","notes":[]},{"n":8,"t":"民要攻打民，国要攻打国；多处必有地震、饥荒。这都是灾难的起头。","notes":["灾难：原文是生产之难"]},{"n":9,"t":"但你们要谨慎；因为人要把你们交给公会，并且你们在会堂里要受鞭打，又为我的缘故站在诸侯与君王面前，对他们作见证。","notes":[]},{"n":10,"t":"然而，福音必须先传给万民。","notes":[]},{"n":11,"t":"人把你们拉去交官的时候，不要预先思虑说什么；到那时候，赐给你们什么话，你们就说什么；因为说话的不是你们，乃是圣灵。","notes":[]},{"n":12,"t":"弟兄要把弟兄，父亲要把儿子，送到死地；儿女要起来与父母为敌，害死他们；","notes":[]},{"n":13,"t":"并且你们要为我的名被众人恨恶。惟有忍耐到底的，必然得救。」","notes":[]},{"n":14,"t":"「你们看见那行毁坏可憎的，站在不当站的地方（读这经的人须要会意）。那时，在犹太的，应当逃到山上；","notes":[],"heads":["大灾难"]},{"n":15,"t":"在房上的，不要下来，也不要进去拿家里的东西；","notes":[]},{"n":16,"t":"在田里的，也不要回去取衣裳。","notes":[]},{"n":17,"t":"当那些日子，怀孕的和奶孩子的有祸了！","notes":[]},{"n":18,"t":"你们应当祈求，叫这些事不在冬天临到。","notes":[]},{"n":19,"t":"因为在那些日子必有灾难，自从神创造万物直到如今，并没有这样的灾难，后来也必没有。","notes":[]},{"n":20,"t":"若不是主减少那日子，凡有血气的，总没有一个得救的；只是为主的选民，他将那日子减少了。","notes":[]},{"n":21,"t":"那时若有人对你们说：『看哪，基督在这里』，或说：『基督在那里』，你们不要信！","notes":[]},{"n":22,"t":"因为假基督、假先知将要起来，显神迹奇事，倘若能行，就把选民迷惑了。","notes":[]},{"n":23,"t":"你们要谨慎。看哪，凡事我都预先告诉你们了。」","notes":[]},{"n":24,"t":"「在那些日子，那灾难以后，日头要变黑了，月亮也不放光，","notes":[],"heads":["人子的降临"]},{"n":25,"t":"众星要从天上坠落，天势都要震动。","notes":[]},{"n":26,"t":"那时，他们要看见人子有大能力、大荣耀，驾云降临。","notes":["马太二十四章三十节是地上的万族"]},{"n":27,"t":"他要差遣天使，把他的选民，从四方，从地极直到天边，都招聚了来。」","notes":["方：原文是风"]},{"n":28,"t":"「你们可以从无花果树学个比方：当树枝发嫩长叶的时候，你们就知道夏天近了。","notes":[],"heads":["从无花果树学个比方"]},{"n":29,"t":"这样，你们几时看见这些事成就，也该知道人子近了，正在门口了。","notes":["人子：或译神的国"]},{"n":30,"t":"我实在告诉你们，这世代还没有过去，这些事都要成就。","notes":[]},{"n":31,"t":"天地要废去，我的话却不能废去。」","notes":[]},{"n":32,"t":"「但那日子，那时辰，没有人知道，连天上的使者也不知道，子也不知道，惟有父知道。","notes":[],"heads":["那日那时没有人知道"]},{"n":33,"t":"你们要谨慎，警醒祈祷，因为你们不晓得那日期几时来到。","notes":[]},{"n":34,"t":"这事正如一个人离开本家，寄居外邦，把权柄交给仆人，分派各人当做的工，又吩咐看门的警醒。","notes":[]},{"n":35,"t":"所以，你们要警醒；因为你们不知道家主什么时候来，或晚上，或半夜，或鸡叫，或早晨；","notes":[]},{"n":36,"t":"恐怕他忽然来到，看见你们睡着了。","notes":[]},{"n":37,"t":"我对你们所说的话，也是对众人说：要警醒！」","notes":[]}]},"14":{"heading":"杀害耶稣的阴谋","verses":[{"n":1,"t":"过两天是逾越节，又是除酵节，祭司长和文士想法子怎么用诡计捉拿耶稣，杀他。","notes":[]},{"n":2,"t":"只是说：「当节的日子不可，恐怕百姓生乱。」","notes":[]},{"n":3,"t":"耶稣在伯大尼长大麻风的西门家里坐席的时候，有一个女人拿着一玉瓶至贵的真哪哒香膏来，打破玉瓶，把膏浇在耶稣的头上。","notes":[],"heads":["在伯大尼受膏"]},{"n":4,"t":"有几个人心中很不喜悦，说：「何用这样枉费香膏呢？","notes":[]},{"n":5,"t":"这香膏可以卖三十多两银子周济穷人。」他们就向那女人生气。","notes":[]},{"n":6,"t":"耶稣说：「由她吧！为什么难为她呢？她在我身上做的是一件美事。","notes":[]},{"n":7,"t":"因为常有穷人和你们同在，要向他们行善随时都可以；只是你们不常有我。","notes":[]},{"n":8,"t":"她所做的，是尽她所能的；她是为我安葬的事把香膏预先浇在我身上。","notes":[]},{"n":9,"t":"我实在告诉你们，普天之下，无论在什么地方传这福音，也要述说这女人所做的，以为记念。」","notes":[]},{"n":10,"t":"十二门徒之中，有一个加略人犹大去见祭司长，要把耶稣交给他们。","notes":[],"heads":["犹大出卖耶稣"]},{"n":11,"t":"他们听见就欢喜，又应许给他银子；他就寻思如何得便把耶稣交给他们。","notes":[]},{"n":12,"t":"除酵节的第一天，就是宰逾越羊羔的那一天，门徒对耶稣说：「你吃逾越节的筵席要我们往哪里去预备呢？」","notes":[],"heads":["和门徒同度逾越节"]},{"n":13,"t":"耶稣就打发两个门徒，对他们说：「你们进城去，必有人拿着一瓶水迎面而来，你们就跟着他。","notes":[]},{"n":14,"t":"他进哪家去，你们就对那家的主人说：『夫子说：客房在哪里？我与门徒好在那里吃逾越节的筵席。』","notes":[]},{"n":15,"t":"他必指给你们摆设整齐的一间大楼，你们就在那里为我们预备。」","notes":[]},{"n":16,"t":"门徒出去，进了城，所遇见的正如耶稣所说的。他们就预备了逾越节的筵席。","notes":[]},{"n":17,"t":"到了晚上，耶稣和十二个门徒都来了。","notes":[]},{"n":18,"t":"他们坐席正吃的时候，耶稣说：「我实在告诉你们，你们中间有一个与我同吃的人要卖我了。」","notes":[]},{"n":19,"t":"他们就忧愁起来，一个一个地问他说：「是我吗？」","notes":[]},{"n":20,"t":"耶稣对他们说：「是十二个门徒中同我蘸手在盘子里的那个人。","notes":[]},{"n":21,"t":"人子必要去世，正如经上指着他所写的；但卖人子的人有祸了！那人不生在世上倒好。」","notes":[]},{"n":22,"t":"他们吃的时候，耶稣拿起饼来，祝了福，就擘开，递给他们，说：「你们拿着吃，这是我的身体」；","notes":[],"heads":["设立主的晚餐"]},{"n":23,"t":"又拿起杯来，祝谢了，递给他们；他们都喝了。","notes":[]},{"n":24,"t":"耶稣说：「这是我立约的血，为多人流出来的。","notes":[]},{"n":25,"t":"我实在告诉你们，我不再喝这葡萄汁，直到我在神的国里喝新的那日子。」","notes":[]},{"n":26,"t":"他们唱了诗，就出来，往橄榄山去。","notes":[]},{"n":27,"t":"耶稣对他们说：「你们都要跌倒了，因为经上记着说：我要击打牧人，羊就分散了。","notes":[],"heads":["预言彼得不认主"]},{"n":28,"t":"但我复活以后，要在你们以先往加利利去。」","notes":[]},{"n":29,"t":"彼得说：「众人虽然跌倒，我总不能。」","notes":[]},{"n":30,"t":"耶稣对他说：「我实在告诉你，就在今天夜里，鸡叫两遍以先，你要三次不认我。」","notes":[]},{"n":31,"t":"彼得却极力地说：「我就是必须和你同死，也总不能不认你。」众门徒都是这样说。","notes":[]},{"n":32,"t":"他们来到一个地方，名叫客西马尼。耶稣对门徒说：「你们坐在这里，等我祷告。」","notes":[],"heads":["在客西马尼祷告"]},{"n":33,"t":"于是带着彼得、雅各、约翰同去，就惊恐起来，极其难过，","notes":[]},{"n":34,"t":"对他们说：「我心里甚是忧伤，几乎要死；你们在这里等候，警醒。」","notes":[]},{"n":35,"t":"他就稍往前走，俯伏在地，祷告说：「倘若可行，便叫那时候过去。」","notes":[]},{"n":36,"t":"他说：「阿爸！父啊！在你凡事都能；求你将这杯撤去。然而，不要从我的意思，只要从你的意思。」","notes":[]},{"n":37,"t":"耶稣回来，见他们睡着了，就对彼得说：「西门，你睡觉吗？不能警醒片时吗？","notes":[]},{"n":38,"t":"总要警醒祷告，免得入了迷惑。你们心灵固然愿意，肉体却软弱了。」","notes":[]},{"n":39,"t":"耶稣又去祷告，说的话还是与先前一样，","notes":[]},{"n":40,"t":"又来见他们睡着了，因为他们的眼睛甚是困倦；他们也不知道怎么回答。","notes":[]},{"n":41,"t":"第三次来，对他们说：「现在你们仍然睡觉安歇吧！够了，时候到了。看哪，人子被卖在罪人手里了。","notes":["吧：或译吗？"]},{"n":42,"t":"起来！我们走吧。看哪，那卖我的人近了！」","notes":[]},{"n":43,"t":"说话之间，忽然那十二个门徒里的犹大来了，并有许多人带着刀棒，从祭司长和文士并长老那里与他同来。","notes":[],"heads":["耶稣被捕"]},{"n":44,"t":"卖耶稣的人曾给他们一个暗号，说：「我与谁亲嘴，谁就是他。你们把他拿住，牢牢靠靠地带去。」","notes":[]},{"n":45,"t":"犹大来了，随即到耶稣跟前，说：「拉比」，便与他亲嘴。","notes":[]},{"n":46,"t":"他们就下手拿住他。","notes":[]},{"n":47,"t":"旁边站着的人，有一个拔出刀来，将大祭司的仆人砍了一刀，削掉了他一个耳朵。","notes":[]},{"n":48,"t":"耶稣对他们说：「你们带着刀棒出来拿我，如同拿强盗吗？","notes":[]},{"n":49,"t":"我天天教训人，同你们在殿里，你们并没有拿我。但这事成就，为要应验经上的话。」","notes":[]},{"n":50,"t":"门徒都离开他，逃走了。","notes":[]},{"n":51,"t":"有一个少年人，赤身披着一块麻布，跟随耶稣，众人就捉拿他。","notes":[],"heads":["逃走的少年人"]},{"n":52,"t":"他却丢了麻布，赤身逃走了。","notes":[]},{"n":53,"t":"他们把耶稣带到大祭司那里，又有众祭司长和长老并文士都来和大祭司一同聚集。","notes":[],"heads":["耶稣在公会里受审"]},{"n":54,"t":"彼得远远地跟着耶稣，一直进入大祭司的院里，和差役一同坐在火光里烤火。","notes":[]},{"n":55,"t":"祭司长和全公会寻找见证控告耶稣，要治死他，却寻不着。","notes":[]},{"n":56,"t":"因为有好些人作假见证告他，只是他们的见证各不相合。","notes":[]},{"n":57,"t":"又有几个人站起来作假见证告他，说：","notes":[]},{"n":58,"t":"「我们听见他说：『我要拆毁这人手所造的殿，三日内就另造一座不是人手所造的。』」","notes":[]},{"n":59,"t":"他们就是这么作见证，也是各不相合。","notes":[]},{"n":60,"t":"大祭司起来站在中间，问耶稣说：「你什么都不回答吗？这些人作见证告你的是什么呢？」","notes":[]},{"n":61,"t":"耶稣却不言语，一句也不回答。大祭司又问他说：「你是那当称颂者的儿子基督不是？」","notes":[]},{"n":62,"t":"耶稣说：「我是。你们必看见人子坐在那权能者的右边，驾着天上的云降临。」","notes":[]},{"n":63,"t":"大祭司就撕开衣服，说：「我们何必再用见证人呢？","notes":[]},{"n":64,"t":"你们已经听见他这僭妄的话了。你们的意见如何？」他们都定他该死的罪。","notes":[]},{"n":65,"t":"就有人吐唾沫在他脸上，又蒙着他的脸，用拳头打他，对他说：「你说预言吧！」差役接过他来，用手掌打他。","notes":[]},{"n":66,"t":"彼得在下边院子里；来了大祭司的一个使女，","notes":[],"heads":["彼得三次不认主"]},{"n":67,"t":"见彼得烤火，就看着他，说：「你素来也是同拿撒勒人耶稣一伙的。」","notes":[]},{"n":68,"t":"彼得却不承认，说：「我不知道，也不明白你说的是什么。」于是出来，到了前院，鸡就叫了。","notes":[]},{"n":69,"t":"那使女看见他，又对旁边站着的人说：「这也是他们一党的。」","notes":[]},{"n":70,"t":"彼得又不承认。过了不多的时候，旁边站着的人又对彼得说：「你真是他们一党的！因为你是加利利人。」","notes":[]},{"n":71,"t":"彼得就发咒起誓地说：「我不认得你们说的这个人。」","notes":[]},{"n":72,"t":"立时鸡叫了第二遍。彼得想起耶稣对他所说的话：「鸡叫两遍以先，你要三次不认我。」思想起来，就哭了。","notes":[]}]},"15":{"heading":"耶稣在彼拉多面前受审","verses":[{"n":1,"t":"一到早晨，祭司长和长老、文士、全公会的人大家商议，就把耶稣捆绑，解去交给彼拉多。","notes":[]},{"n":2,"t":"彼拉多问他说：「你是犹太人的王吗？」耶稣回答说：「你说的是。」","notes":[]},{"n":3,"t":"祭司长告他许多的事。","notes":[]},{"n":4,"t":"彼拉多又问他说：「你看，他们告你这么多的事，你什么都不回答吗？」","notes":[]},{"n":5,"t":"耶稣仍不回答，以致彼拉多觉得希奇。","notes":[]},{"n":6,"t":"每逢这节期，巡抚照众人所求的，释放一个囚犯给他们。","notes":[],"heads":["耶稣被判死刑"]},{"n":7,"t":"有一个人名叫巴拉巴，和作乱的人一同捆绑。他们作乱的时候，曾杀过人。","notes":[]},{"n":8,"t":"众人上去求巡抚，照常例给他们办。","notes":[]},{"n":9,"t":"彼拉多说：「你们要我释放犹太人的王给你们吗？」","notes":[]},{"n":10,"t":"他原晓得，祭司长是因为嫉妒才把耶稣解了来。","notes":[]},{"n":11,"t":"只是祭司长挑唆众人，宁可释放巴拉巴给他们。","notes":[]},{"n":12,"t":"彼拉多又说：「那么样，你们所称为犹太人的王，我怎么办他呢？」","notes":[]},{"n":13,"t":"他们又喊着说：「把他钉十字架！」","notes":[]},{"n":14,"t":"彼拉多说：「为什么呢？他做了什么恶事呢？」他们便极力地喊着说：「把他钉十字架！」","notes":[]},{"n":15,"t":"彼拉多要叫众人喜悦，就释放巴拉巴给他们，将耶稣鞭打了，交给人钉十字架。","notes":[]},{"n":16,"t":"兵丁把耶稣带进衙门院里，叫齐了全营的兵。","notes":[],"heads":["兵丁戏弄耶稣"]},{"n":17,"t":"他们给他穿上紫袍，又用荆棘编做冠冕给他戴上，","notes":[]},{"n":18,"t":"就庆贺他说：「恭喜，犹太人的王啊！」","notes":[]},{"n":19,"t":"又拿一根苇子打他的头，吐唾沫在他脸上，屈膝拜他。","notes":[]},{"n":20,"t":"戏弄完了，就给他脱了紫袍，仍穿上他自己的衣服，带他出去，要钉十字架。","notes":[]},{"n":21,"t":"有一个古利奈人西门，就是亚历山大和鲁孚的父亲，从乡下来，经过那地方，他们就勉强他同去，好背着耶稣的十字架。","notes":[],"heads":["耶稣被钉十字架"]},{"n":22,"t":"他们带耶稣到了各各他地方（各各他翻出来就是髑髅地），","notes":[]},{"n":23,"t":"拿没药调和的酒给耶稣，他却不受。","notes":[]},{"n":24,"t":"于是将他钉在十字架上，拈阄分他的衣服，看是谁得什么。","notes":[]},{"n":25,"t":"钉他在十字架上是巳初的时候。","notes":[]},{"n":26,"t":"在上面有他的罪状，写的是：「犹太人的王。」","notes":[]},{"n":27,"t":"他们又把两个强盗和他同钉十字架，一个在右边，一个在左边。","notes":["有古卷加：28这就应了经上的话说：他被列在罪犯之中。"]},{"n":29,"t":"从那里经过的人辱骂他，摇着头说：「咳！你这拆毁圣殿、三日又建造起来的，","notes":[]},{"n":30,"t":"可以救自己，从十字架上下来吧！」","notes":[]},{"n":31,"t":"祭司长和文士也是这样戏弄他，彼此说：「他救了别人，不能救自己。","notes":[]},{"n":32,"t":"以色列的王基督，现在可以从十字架上下来，叫我们看见，就信了。」那和他同钉的人也是讥诮他。","notes":[]},{"n":33,"t":"从午正到申初，遍地都黑暗了。","notes":[],"heads":["耶稣的死"]},{"n":34,"t":"申初的时候，耶稣大声喊着说：「以罗伊！以罗伊！拉马撒巴各大尼？」（翻出来就是：我的神！我的神！为什么离弃我？）","notes":[]},{"n":35,"t":"旁边站着的人，有的听见就说：「看哪，他叫以利亚呢！」","notes":[]},{"n":36,"t":"有一个人跑去，把海绒蘸满了醋，绑在苇子上，送给他喝，说：「且等着，看以利亚来不来把他取下。」","notes":[]},{"n":37,"t":"耶稣大声喊叫，气就断了。","notes":[]},{"n":38,"t":"殿里的幔子从上到下裂为两半。","notes":[]},{"n":39,"t":"对面站着的百夫长看见耶稣这样喊叫断气，就说：「这人真是神的儿子！」","notes":["有古卷没有喊叫二字"]},{"n":40,"t":"还有些妇女远远地观看；内中有抹大拉的马利亚，又有小雅各和约西的母亲马利亚，并有撒罗米，","notes":[]},{"n":41,"t":"就是耶稣在 加利利的时候，跟随他、服事他的那些人，还有同耶稣上耶路撒冷的好些妇女 在那里观看。","notes":[]},{"n":42,"t":"到了晚上，因为这是预备日，就是安息日的前一日，","notes":[],"heads":["耶稣的安葬"]},{"n":43,"t":"有亚利马太的约瑟前来，他是尊贵的议士，也是等候神国的。他放胆进去见彼拉多，求耶稣的身体；","notes":[]},{"n":44,"t":"彼拉多诧异耶稣已经死了，便叫百夫长来，问他耶稣死了久不久。","notes":[]},{"n":45,"t":"既从百夫长得知实情，就把耶稣的尸首赐给约瑟。","notes":[]},{"n":46,"t":"约瑟买了细麻布，把耶稣取下来，用细麻布裹好，安放在磐石中凿出来的坟墓里，又滚过一块石头来挡住墓门。","notes":[]},{"n":47,"t":"抹大拉的马利亚和约西的母亲马利亚都看见安放他的地方。","notes":[]}]},"16":{"heading":"耶稣复活","verses":[{"n":1,"t":"过了安息日，抹大拉的马利亚和雅各的母亲马利亚并撒罗米，买了香膏要去膏耶稣的身体。","notes":[]},{"n":2,"t":"七日的第一日清早，出太阳的时候，她们来到坟墓那里，","notes":[]},{"n":3,"t":"彼此说：「谁给我们把石头从墓门滚开呢？」","notes":[]},{"n":4,"t":"那石头原来很大，她们抬头一看，却见石头已经滚开了。","notes":[]},{"n":5,"t":"她们进了坟墓，看见一个少年人坐在右边，穿着白袍，就甚惊恐。","notes":[]},{"n":6,"t":"那少年人对她们说：「不要惊恐！你们寻找那钉十字架的拿撒勒人耶稣，他已经复活了，不在这里。请看安放他的地方。","notes":[]},{"n":7,"t":"你们可以去告诉他的门徒和彼得，说：『他在你们以先往加利利去。在那里你们要见他，正如他从前所告诉你们的。』」","notes":[]},{"n":8,"t":"她们就出来，从坟墓那里逃跑，又发抖又惊奇，什么也不告诉人，因为她们害怕。","notes":[]},{"n":9,"t":"在七日的第一日清早，耶稣复活了，就先向抹大拉的马利亚显现（耶稣从她身上曾赶出七个鬼）。","notes":[],"heads":["向抹大拉的马利亚显现"]},{"n":10,"t":"她去告诉那向来跟随耶稣的人；那时他们正哀恸哭泣。","notes":[]},{"n":11,"t":"他们听见耶稣活了，被马利亚看见，却是不信。","notes":[]},{"n":12,"t":"这事以后，门徒中间有两个人往乡下去。走路的时候，耶稣变了形象，向他们显现。","notes":[],"heads":["向两个门徒显现"]},{"n":13,"t":"他们就去告诉其余的门徒；其余的门徒也是不信。","notes":[]},{"n":14,"t":"后来，十一个门徒坐席的时候，耶稣向他们显现，责备他们不信，心里刚硬，因为他们不信那些在他复活以后看见他的人。","notes":[],"heads":["门徒奉差遣"]},{"n":15,"t":"他又对他们说：「你们往普天下去，传福音给万民听。","notes":["万民：原文是凡受造的"]},{"n":16,"t":"信而受洗的，必然得救；不信的，必被定罪。","notes":[]},{"n":17,"t":"信的人必有神迹随着他们，就是奉我的名赶鬼；说新方言；","notes":[]},{"n":18,"t":"手能拿蛇；若喝了什么毒物，也必不受害；手按病人，病人就必好了。」","notes":[]},{"n":19,"t":"主耶稣和他们说完了话，后来被接到天上，坐在神的右边。","notes":[],"heads":["耶稣升天"]},{"n":20,"t":"门徒出去，到处宣传福音。主和他们同工，用神迹随着，证实所传的道。阿们！","notes":[]}]}},"LUK":{"1":{"heading":"写给提阿非罗","verses":[{"n":1,"t":"提阿非罗大人哪，有好些人提笔作书，述说在我们中间所成就的事，是照传道的人从起初亲眼看见又传给我们的。","notes":[],"end":2},{"n":3,"t":"这些事我既从起头都详细考察了，就定意要按着次序写给你，","notes":[]},{"n":4,"t":"使你知道所学之道都是确实的。","notes":[]},{"n":5,"t":"当犹太王希律的时候，亚比雅班里有一个祭司，名叫撒迦利亚；他妻子是亚伦的后人，名叫伊利莎白。","notes":[],"heads":["预言施洗约翰的诞生"]},{"n":6,"t":"他们二人在神面前都是义人，遵行主的一切诫命礼仪，没有可指摘的，","notes":[]},{"n":7,"t":"只是没有孩子；因为伊利莎白不生育，两个人又年纪老迈了。","notes":[]},{"n":8,"t":"撒迦利亚按班次在神面前供祭司的职分，","notes":[]},{"n":9,"t":"照祭司的规矩掣签，得进主殿烧香。","notes":[]},{"n":10,"t":"烧香的时候，众百姓在外面祷告。","notes":[]},{"n":11,"t":"有主的使者站在香坛的右边，向他显现。","notes":[]},{"n":12,"t":"撒迦利亚看见，就惊慌害怕。","notes":[]},{"n":13,"t":"天使对他说：「撒迦利亚，不要害怕，因为你的祈祷已经被听见了。你的妻子伊利莎白要给你生一个儿子，你要给他起名叫约翰。","notes":[]},{"n":14,"t":"你必欢喜快乐；有许多人因他出世，也必喜乐。","notes":[]},{"n":15,"t":"他在主面前将要为大，淡酒浓酒都不喝，从母腹里就被圣灵充满了。","notes":[]},{"n":16,"t":"他要使许多以色列人回转，归于主—他们的神。","notes":[]},{"n":17,"t":"他必有以利亚的心志能力，行在主的前面，叫为父的心转向儿女，叫悖逆的人转从义人的智慧，又为主预备合用的百姓。」","notes":[]},{"n":18,"t":"撒迦利亚对天使说：「我凭着什么可知道这事呢？我已经老了，我的妻子也年纪老迈了。」","notes":[]},{"n":19,"t":"天使回答说：「我是站在神面前的加百列，奉差而来对你说话，将这好信息报给你。","notes":[]},{"n":20,"t":"到了时候，这话必然应验；只因你不信，你必哑巴，不能说话，直到这事成就的日子。」","notes":[]},{"n":21,"t":"百姓等候撒迦利亚，诧异他许久在殿里。","notes":[]},{"n":22,"t":"及至他出来，不能和他们说话，他们就知道他在殿里见了异象；因为他直向他们打手式，竟成了哑巴。","notes":[]},{"n":23,"t":"他供职的日子已满，就回家去了。","notes":[]},{"n":24,"t":"这些日子以后，他的妻子伊利莎白怀了孕，就隐藏了五个月，","notes":[]},{"n":25,"t":"说：「主在眷顾我的日子，这样看待我，要把我在人间的羞耻除掉。」","notes":[]},{"n":26,"t":"到了第六个月，天使加百列奉神的差遣往加利利的一座城去（这城名叫拿撒勒），","notes":[],"heads":["预言耶稣的降生"]},{"n":27,"t":"到一个童女那里，是已经许配大卫家的一个人，名叫约瑟。童女的名字叫马利亚；","notes":[]},{"n":28,"t":"天使进去，对她说：「蒙大恩的女子，我问你安，主和你同在了！」","notes":[]},{"n":29,"t":"马利亚因这话就很惊慌，又反复思想这样问安是什么意思。","notes":[]},{"n":30,"t":"天使对她说：「马利亚，不要怕！你在神面前已经蒙恩了。","notes":[]},{"n":31,"t":"你要怀孕生子，可以给他起名叫耶稣。","notes":[]},{"n":32,"t":"他要为大，称为至高者的儿子；主神要把他祖大卫的位给他。","notes":[]},{"n":33,"t":"他要作雅各家的王，直到永远；他的国也没有穷尽。」","notes":[]},{"n":34,"t":"马利亚对天使说：「我没有出嫁，怎么有这事呢？」","notes":[]},{"n":35,"t":"天使回答说：「圣灵要临到你身上，至高者的能力要荫庇你，因此所要生的圣者必称为神的儿子。","notes":["或译：所要生的，必称为圣，称为神的儿子"]},{"n":36,"t":"况且你的亲戚伊利莎白，在年老的时候也怀了男胎，就是那素来称为不生育的，现在有孕六个月了。","notes":[]},{"n":37,"t":"因为，出于神的话，没有一句不带能力的。」","notes":[]},{"n":38,"t":"马利亚说：「我是主的使女，情愿照你的话成就在我身上。」天使就离开她去了。","notes":[]},{"n":39,"t":"那时候，马利亚起身，急忙往山地里去，来到犹大的一座城；","notes":[],"heads":["马利亚访问伊利莎白"]},{"n":40,"t":"进了撒迦利亚的家，问伊利莎白安。","notes":[]},{"n":41,"t":"伊利莎白一听马利亚问安，所怀的胎就在腹里跳动。伊利莎白且被圣灵充满，","notes":[]},{"n":42,"t":"高声喊着说：「你在妇女中是有福的！你所怀的胎也是有福的！","notes":[]},{"n":43,"t":"我主的母到我这里来，这是从哪里得的呢？","notes":[]},{"n":44,"t":"因为你问安的声音一入我耳，我腹里的胎就欢喜跳动。","notes":[]},{"n":45,"t":"这相信的女子是有福的！因为主对她所说的话都要应验。」","notes":[]},{"n":46,"t":"马利亚说：我心尊主为大；","notes":[],"heads":["马利亚的尊主颂"]},{"n":47,"t":"我灵以神我的救主为乐；","notes":[]},{"n":48,"t":"因为他顾念他使女的卑微；从今以后，万代要称我有福。","notes":[]},{"n":49,"t":"那有权能的，为我成就了大事；他的名为圣。","notes":[]},{"n":50,"t":"他怜悯敬畏他的人，直到世世代代。","notes":[]},{"n":51,"t":"他用膀臂施展大能；那狂傲的人正心里妄想就被他赶散了。","notes":[]},{"n":52,"t":"他叫有权柄的失位，叫卑贱的升高；","notes":[]},{"n":53,"t":"叫饥饿的得饱美食，叫富足的空手回去。","notes":[]},{"n":54,"t":"他扶助了他的仆人以色列，","notes":[]},{"n":55,"t":"为要记念亚伯拉罕和他的后裔，施怜悯直到永远，正如从前对我们列祖所说的话。","notes":[]},{"n":56,"t":"马利亚和伊利莎白同住，约有三个月，就回家去了。","notes":[]},{"n":57,"t":"伊利莎白的产期到了，就生了一个儿子。","notes":[],"heads":["施洗约翰的出生"]},{"n":58,"t":"邻里亲族听见主向她大施怜悯，就和她一同欢乐。","notes":[]},{"n":59,"t":"到了第八日，他们来要给孩子行割礼，并要照他父亲的名字叫他撒迦利亚。","notes":[]},{"n":60,"t":"他母亲说：「不可！要叫他约翰。」","notes":[]},{"n":61,"t":"他们说：「你亲族中没有叫这名字的。」","notes":[]},{"n":62,"t":"他们就向他父亲打手式，问他要叫这孩子什么名字。","notes":[]},{"n":63,"t":"他要了一块写字的板，就写上，说：「他的名字是约翰。」他们便都希奇。","notes":[]},{"n":64,"t":"撒迦利亚的口立时开了，舌头也舒展了，就说出话来，称颂神。","notes":[]},{"n":65,"t":"周围居住的人都惧怕；这一切的事就传遍了犹太的山地。","notes":[]},{"n":66,"t":"凡听见的人都将这事放在心里，说：「这个孩子将来怎么样呢？因为有主与他同在。」","notes":[]},{"n":67,"t":"他父亲撒迦利亚被圣灵充满了，就预言说：","notes":[],"heads":["撒迦利亚的预言"]},{"n":68,"t":"主—以色列的神是应当称颂的！因他眷顾他的百姓，为他们施行救赎，","notes":[]},{"n":69,"t":"在他仆人大卫家中，为我们兴起了拯救的角，","notes":[]},{"n":70,"t":"正如主借着从创世以来圣先知的口所说的话，","notes":[]},{"n":71,"t":"拯救我们脱离仇敌和一切恨我们之人的手，","notes":[]},{"n":72,"t":"向我们列祖施怜悯，记念他的圣约—","notes":[]},{"n":73,"t":"就是他对我们祖宗亚伯拉罕所起的誓—","notes":[]},{"n":74,"t":"叫我们既从仇敌手中被救出来，","notes":[]},{"n":75,"t":"就可以终身在他面前，坦然无惧地用圣洁、公义事奉他。","notes":[]},{"n":76,"t":"孩子啊！你要称为至高者的先知；因为你要行在主的前面，预备他的道路，","notes":[]},{"n":77,"t":"叫他的百姓因罪得赦，就知道救恩。","notes":[]},{"n":78,"t":"因我们神怜悯的心肠，叫清晨的日光从高天临到我们，","notes":[]},{"n":79,"t":"要照亮坐在黑暗中死荫里的人，把我们的脚引到平安的路上。","notes":[]},{"n":80,"t":"那孩子渐渐长大，心灵强健，住在旷野，直到他显明在以色列人面前的日子。","notes":[]}]},"2":{"heading":"耶稣降生","verses":[{"n":1,"t":"当那些日子，凯撒奥古斯都有旨意下来，叫天下人民都报名上册。","notes":[]},{"n":2,"t":"这是居里扭作叙利亚巡抚的时候，头一次行报名上册的事。","notes":[]},{"n":3,"t":"众人各归各城，报名上册。","notes":[]},{"n":4,"t":"约瑟也从加利利的拿撒勒城上犹太去，到了大卫的城，名叫伯利恒，因他本是大卫一族一家的人，","notes":[]},{"n":5,"t":"要和他所聘之妻马利亚一同报名上册。那时马利亚的身孕已经重了。","notes":[]},{"n":6,"t":"他们在那里的时候，马利亚的产期到了，","notes":[]},{"n":7,"t":"就生了头胎的儿子，用布包起来，放在马槽里，因为客店里没有地方。","notes":[]},{"n":8,"t":"在伯利恒之野地里有牧羊的人，夜间按着更次看守羊群。","notes":[],"heads":["天使报喜讯给牧羊的人"]},{"n":9,"t":"有主的使者站在他们旁边，主的荣光四面照着他们；牧羊的人就甚惧怕。","notes":[]},{"n":10,"t":"那天使对他们说：「不要惧怕！我报给你们大喜的信息，是关乎万民的；","notes":[]},{"n":11,"t":"因今天在大卫的城里，为你们生了救主，就是主基督。","notes":[]},{"n":12,"t":"你们要看见一个婴孩，包着布，卧在马槽里，那就是记号了。」","notes":[]},{"n":13,"t":"忽然，有一大队天兵同那天使赞美神说：","notes":[]},{"n":14,"t":"在至高之处荣耀归与神！在地上平安归与他所喜悦的人！","notes":["有古卷：喜悦归与人"]},{"n":15,"t":"众天使离开他们，升天去了。牧羊的人彼此说：「我们往伯利恒去，看看所成的事，就是主所指示我们的。」","notes":[]},{"n":16,"t":"他们急忙去了，就寻见马利亚和约瑟，又有那婴孩卧在马槽里；","notes":[]},{"n":17,"t":"既然看见，就把天使论这孩子的话传开了。","notes":[]},{"n":18,"t":"凡听见的，就诧异牧羊之人对他们所说的话。","notes":[]},{"n":19,"t":"马利亚却把这一切的事存在心里，反复思想。","notes":[]},{"n":20,"t":"牧羊的人回去了，因所听见所看见的一切事，正如天使向他们所说的，就归荣耀与神，赞美他。","notes":[]},{"n":21,"t":"满了八天，就给孩子行割礼，与他起名叫耶稣；这就是没有成胎以前，天使所起的名。","notes":[]},{"n":22,"t":"按摩西律法满了洁净的日子，他们带着孩子上耶路撒冷去，要把他献与主，（","notes":[],"heads":["在圣殿里献与主"]},{"n":23,"t":"正如主的律法上所记：「凡头生的男子必称圣归主。」）","notes":[]},{"n":24,"t":"又要照主的律法上所说，或用一对斑鸠，或用两只雏鸽献祭。","notes":[]},{"n":25,"t":"在耶路撒冷有一个人，名叫西面；这人又公义又虔诚，素常盼望以色列的安慰者来到，又有圣灵在他身上。","notes":[]},{"n":26,"t":"他得了圣灵的启示，知道自己未死以前，必看见主所立的基督。","notes":[]},{"n":27,"t":"他受了圣灵的感动，进入圣殿，正遇见耶稣的父母抱着孩子进来，要照律法的规矩办理。","notes":[]},{"n":28,"t":"西面就用手接过他来，称颂神说：","notes":[]},{"n":29,"t":"主啊！如今可以照你的话，释放仆人安然去世；","notes":[]},{"n":30,"t":"因为我的眼睛已经看见你的救恩—","notes":[]},{"n":31,"t":"就是你在万民面前所预备的：","notes":[]},{"n":32,"t":"是照亮外邦人的光，又是你民以色列的荣耀。","notes":[]},{"n":33,"t":"孩子的父母因这论耶稣的话就希奇。","notes":[]},{"n":34,"t":"西面给他们祝福，又对孩子的母亲马利亚说：「这孩子被立，是要叫以色列中许多人跌倒，许多人兴起；又要作毁谤的话柄，叫许多人心里的意念显露出来；你自己的心也要被刀刺透。」","notes":[],"end":35},{"n":36,"t":"又有女先知，名叫亚拿，是亚设支派法内力的女儿，年纪已经老迈，从作童女出嫁的时候，同丈夫住了七年就寡居了，","notes":[]},{"n":37,"t":"现在已经八十四岁，并不离开圣殿，禁食祈求，昼夜事奉神。","notes":["或译：就寡居了八十四年"]},{"n":38,"t":"正当那时，她进前来称谢神，将孩子的事对一切盼望耶路撒冷得救赎的人讲说。","notes":[]},{"n":39,"t":"约瑟和马利亚照主的律法办完了一切的事，就回加利利，到自己的城拿撒勒去了。","notes":[],"heads":["回拿撒勒"]},{"n":40,"t":"孩子渐渐长大，强健起来，充满智慧，又有神的恩在他身上。","notes":[]},{"n":41,"t":"每年到逾越节，他父母就上耶路撒冷去。","notes":[],"heads":["孩童耶稣在圣殿里"]},{"n":42,"t":"当他十二岁的时候，他们按着节期的规矩上去。","notes":[]},{"n":43,"t":"守满了节期，他们回去，孩童耶稣仍旧在耶路撒冷。他的父母并不知道，","notes":[]},{"n":44,"t":"以为他在同行的人中间，走了一天的路程，就在亲族和熟识的人中找他，","notes":[]},{"n":45,"t":"既找不着，就回耶路撒冷去找他。","notes":[]},{"n":46,"t":"过了三天，就遇见他在殿里，坐在教师中间，一面听，一面问。","notes":[]},{"n":47,"t":"凡听见他的，都希奇他的聪明和他的应对。","notes":[]},{"n":48,"t":"他父母看见就很希奇。他母亲对他说：「我儿！为什么向我们这样行呢？看哪，你父亲和我伤心来找你！」","notes":[]},{"n":49,"t":"耶稣说：「为什么找我呢？岂不知我应当以我父的事为念吗？」","notes":["或译：岂不知我应当在我父的家里吗"]},{"n":50,"t":"他所说的这话，他们不明白。","notes":[]},{"n":51,"t":"他就同他们下去，回到拿撒勒，并且顺从他们。他母亲把这一切的事都存在心里。","notes":[]},{"n":52,"t":"耶稣的智慧和身量，并神和人喜爱他的心，都一齐增长。","notes":["或译：年纪"]}]},"3":{"heading":"施洗约翰传道","verses":[{"n":1,"t":"凯撒提庇留在位第十五年，本丢·彼拉多作犹太巡抚，希律作加利利分封的王，他兄弟腓力作以土利亚和特拉可尼地方分封的王，吕撒聂作亚比利尼分封的王，","notes":[]},{"n":2,"t":"亚那和该亚法作大祭司。那时，撒迦利亚的儿子约翰在旷野里，神的话临到他。","notes":[]},{"n":3,"t":"他就来到约旦河一带地方，宣讲悔改的洗礼，使罪得赦。","notes":[]},{"n":4,"t":"正如先知以赛亚书上所记的话，说：在旷野有人声喊着说：预备主的道，修直他的路！","notes":[]},{"n":5,"t":"一切山洼都要填满；大小山冈都要削平！弯弯曲曲的地方要改为正直；高高低低的道路要改为平坦！","notes":[]},{"n":6,"t":"凡有血气的，都要见神的救恩！","notes":[]},{"n":7,"t":"约翰对那出来要受他洗的众人说：「毒蛇的种类！谁指示你们逃避将来的忿怒呢？","notes":[]},{"n":8,"t":"你们要结出果子来，与悔改的心相称。不要自己心里说：『有亚伯拉罕为我们的祖宗。』我告诉你们，神能从这些石头中，给亚伯拉罕兴起子孙来。","notes":[]},{"n":9,"t":"现在斧子已经放在树根上，凡不结好果子的树就砍下来，丢在火里。」","notes":[]},{"n":10,"t":"众人问他说：「这样，我们当做什么呢？」","notes":[]},{"n":11,"t":"约翰回答说：「有两件衣裳的，就分给那没有的；有食物的，也当这样行。」","notes":[]},{"n":12,"t":"又有税吏来要受洗，问他说：「夫子，我们当做什么呢？」","notes":[]},{"n":13,"t":"约翰说：「除了例定的数目，不要多取。」","notes":[]},{"n":14,"t":"又有兵丁问他说：「我们当做什么呢？」约翰说：「不要以强暴待人，也不要讹诈人，自己有钱粮就当知足。」","notes":[]},{"n":15,"t":"百姓指望基督来的时候，人都心里猜疑，或者约翰是基督。","notes":[]},{"n":16,"t":"约翰说：「我是用水给你们施洗，但有一位能力比我更大的要来，我就是给他解鞋带也不配。他要用圣灵与火给你们施洗。","notes":[]},{"n":17,"t":"他手里拿着簸箕，要扬净他的场，把麦子收在仓里，把糠用不灭的火烧尽了。」","notes":[]},{"n":18,"t":"约翰又用许多别的话劝百姓，向他们传福音。","notes":[]},{"n":19,"t":"只是分封的王希律，因他兄弟之妻希罗底的缘故，并因他所行的一切恶事，受了约翰的责备；","notes":[]},{"n":20,"t":"又另外添了一件，就是把约翰收在监里。","notes":[]},{"n":21,"t":"众百姓都受了洗，耶稣也受了洗。正祷告的时候，天就开了，","notes":[],"heads":["耶稣受洗"]},{"n":22,"t":"圣灵降临在他身上，形状仿佛鸽子；又有声音从天上来，说：「你是我的爱子，我喜悦你。」","notes":[]},{"n":23,"t":"耶稣开头传道，年纪约有三十岁。依人看来，他是约瑟的儿子；约瑟是希里的儿子；","notes":[],"heads":["耶稣的家谱"]},{"n":24,"t":"希里是玛塔的儿子；玛塔是利未的儿子；利未是麦基的儿子；麦基是雅拿的儿子；雅拿是约瑟的儿子；","notes":[]},{"n":25,"t":"约瑟是玛他提亚的儿子；玛他提亚是亚摩斯的儿子；亚摩斯是拿鸿的儿子；拿鸿是以斯利的儿子；以斯利是拿该的儿子；","notes":[]},{"n":26,"t":"拿该是玛押的儿子；玛押是玛他提亚的儿子；玛他提亚是西美的儿子；西美是约瑟的儿子；约瑟是犹大的儿子；犹大是约亚拿的儿子；","notes":[]},{"n":27,"t":"约亚拿是利撒的儿子；利撒是所罗巴伯的儿子；所罗巴伯是撒拉铁的儿子；撒拉铁是尼利的儿子；尼利是麦基的儿子；","notes":[]},{"n":28,"t":"麦基是亚底的儿子；亚底是哥桑的儿子；哥桑是以摩当的儿子；以摩当是珥的儿子；珥是约细的儿子；","notes":[]},{"n":29,"t":"约细是以利以谢的儿子；以利以谢是约令的儿子；约令是玛塔的儿子；玛塔是利未的儿子；","notes":[]},{"n":30,"t":"利未是西缅的儿子；西缅是犹大的儿子；犹大是约瑟的儿子；约瑟是约南的儿子；约南是以利亚敬的儿子；","notes":[]},{"n":31,"t":"以利亚敬是米利亚的儿子；米利亚是买南的儿子；买南是玛达他的儿子；玛达他是拿单的儿子；拿单是大卫的儿子；","notes":[]},{"n":32,"t":"大卫是耶西的儿子；耶西是俄备得的儿子；俄备得是波阿斯的儿子；波阿斯是撒门的儿子；撒门是拿顺的儿子；","notes":[]},{"n":33,"t":"拿顺是亚米拿达的儿子；亚米拿达是亚兰的儿子；亚兰是希斯仑的儿子；希斯仑是法勒斯的儿子；法勒斯是犹大的儿子；","notes":[]},{"n":34,"t":"犹大是雅各的儿子；雅各是以撒的儿子；以撒是亚伯拉罕的儿子；亚伯拉罕是他拉的儿子；他拉是拿鹤的儿子；","notes":[]},{"n":35,"t":"拿鹤是西鹿的儿子；西鹿是拉吴的儿子；拉吴是法勒的儿子；法勒是希伯的儿子；希伯是沙拉的儿子；","notes":[]},{"n":36,"t":"沙拉是该南的儿子；该南是亚法撒的儿子；亚法撒是闪的儿子；闪是挪亚的儿子；挪亚是拉麦的儿子；","notes":[]},{"n":37,"t":"拉麦是玛土撒拉的儿子；玛土撒拉是以诺的儿子；以诺是雅列的儿子；雅列是玛勒列的儿子；玛勒列是该南的儿子；该南是以挪士的儿子；","notes":[]},{"n":38,"t":"以挪士是塞特的儿子；塞特是亚当的儿子；亚当是神的儿子。","notes":[]}]},"4":{"heading":"耶稣受试探","verses":[{"n":1,"t":"耶稣被圣灵充满，从约旦河回来，圣灵将他引到旷野，","notes":[]},{"n":2,"t":"四十天受魔鬼的试探。那些日子没有吃什么；日子满了，他就饿了。","notes":[]},{"n":3,"t":"魔鬼对他说：「你若是神的儿子，可以吩咐这块石头变成食物。」","notes":[]},{"n":4,"t":"耶稣回答说：「经上记着说：『人活着不是单靠食物，乃是靠神口里所出的一切话。』」","notes":[]},{"n":5,"t":"魔鬼又领他上了高山，霎时间把天下的万国都指给他看，","notes":[]},{"n":6,"t":"对他说：「这一切权柄、荣华，我都要给你，因为这原是交付我的，我愿意给谁就给谁。","notes":[]},{"n":7,"t":"你若在我面前下拜，这都要归你。」","notes":[]},{"n":8,"t":"耶稣说：「经上记着说：当拜主—你的神，单要事奉他。」","notes":[]},{"n":9,"t":"魔鬼又领他到耶路撒冷去，叫他站在殿顶上，对他说：「你若是神的儿子，可以从这里跳下去；","notes":["顶：原文是翅"]},{"n":10,"t":"因为经上记着说：主要为你吩咐他的使者保护你；","notes":[]},{"n":11,"t":"他们要用手托着你，免得你的脚碰在石头上。」","notes":[]},{"n":12,"t":"耶稣对他说：「经上说：『不可试探主—你的神。』」","notes":[]},{"n":13,"t":"魔鬼用完了各样的试探，就暂时离开耶稣。","notes":[]},{"n":14,"t":"耶稣满有圣灵的能力，回到加利利；他的名声就传遍了四方。","notes":[],"heads":["开始在加利利传道"]},{"n":15,"t":"他在各会堂里教训人，众人都称赞他。","notes":[]},{"n":16,"t":"耶稣来到拿撒勒，就是他长大的地方。在安息日，照他平常的规矩进了会堂，站起来要念圣经。","notes":[],"heads":["拿撒勒人厌弃耶稣"]},{"n":17,"t":"有人把先知以赛亚的书交给他，他就打开，找到一处写着说：","notes":[]},{"n":18,"t":"主的灵在我身上，因为他用膏膏我，叫我传福音给贫穷的人；差遣我报告：被掳的得释放，瞎眼的得看见，叫那受压制的得自由，","notes":[]},{"n":19,"t":"报告神悦纳人的禧年。","notes":[]},{"n":20,"t":"于是把书卷起来，交还执事，就坐下。会堂里的人都定睛看他。","notes":[]},{"n":21,"t":"耶稣对他们说：「今天这经应验在你们耳中了。」","notes":[]},{"n":22,"t":"众人都称赞他，并希奇他口中所出的恩言；又说：「这不是约瑟的儿子吗？」","notes":[]},{"n":23,"t":"耶稣对他们说：「你们必引这俗语向我说：『医生，你医治自己吧！我们听见你在迦百农所行的事，也当行在你自己家乡里』」；","notes":[]},{"n":24,"t":"又说：「我实在告诉你们，没有先知在自己家乡被人悦纳的。","notes":[]},{"n":25,"t":"我对你们说实话，当以利亚的时候，天闭塞了三年零六个月，遍地有大饥荒，那时，以色列中有许多寡妇，","notes":[]},{"n":26,"t":"以利亚并没有奉差往她们一个人那里去，只奉差往西顿的撒勒法一个寡妇那里去。","notes":[]},{"n":27,"t":"先知以利沙的时候，以色列中有许多长大麻风的，但内中除了叙利亚国的乃缦，没有一个得洁净的。」","notes":[]},{"n":28,"t":"会堂里的人听见这话，都怒气满胸，","notes":[]},{"n":29,"t":"就起来撵他出城（他们的城造在山上）；他们带他到山崖，要把他推下去。","notes":[]},{"n":30,"t":"他却从他们中间直行，过去了。","notes":[]},{"n":31,"t":"耶稣下到迦百农，就是加利利的一座城，在安息日教训众人。","notes":[],"heads":["一个污鬼附身的人"]},{"n":32,"t":"他们很希奇他的教训，因为他的话里有权柄。","notes":[]},{"n":33,"t":"在会堂里有一个人，被污鬼的精气附着，大声喊叫说：","notes":[]},{"n":34,"t":"「唉！拿撒勒的耶稣，我们与你有什么相干？你来灭我们吗？我知道你是谁，乃是神的圣者。」","notes":[]},{"n":35,"t":"耶稣责备他说：「不要作声，从这人身上出来吧！」鬼把那人摔倒在众人中间，就出来了，却也没有害他。","notes":[]},{"n":36,"t":"众人都惊讶，彼此对问说：「这是什么道理呢？因为他用权柄能力吩咐污鬼，污鬼就出来。」","notes":[]},{"n":37,"t":"于是耶稣的名声传遍了周围地方。","notes":[]},{"n":38,"t":"耶稣出了会堂，进了西门的家。西门的岳母害热病甚重，有人为她求耶稣。","notes":[],"heads":["治好许多病人"]},{"n":39,"t":"耶稣站在她旁边，斥责那热病，热就退了。她立刻起来服事他们。","notes":[]},{"n":40,"t":"日落的时候，凡有病人的，不论害什么病，都带到耶稣那里。耶稣按手在他们各人身上，医好他们。","notes":[]},{"n":41,"t":"又有鬼从好些人身上出来，喊着说：「你是神的儿子。」耶稣斥责他们，不许他们说话，因为他们知道他是基督。","notes":[]},{"n":42,"t":"天亮的时候，耶稣出来，走到旷野地方。众人去找他，到了他那里，要留住他，不要他离开他们。","notes":[],"heads":["在加利利各会堂传道"]},{"n":43,"t":"但耶稣对他们说：「我也必须在别城传神国的福音，因我奉差原是为此。」","notes":[]},{"n":44,"t":"于是耶稣在加利利的各会堂传道。","notes":[]}]},"5":{"heading":"耶稣呼召头几个门徒","verses":[{"n":1,"t":"耶稣站在革尼撒勒湖边，众人拥挤他，要听神的道。","notes":[]},{"n":2,"t":"他见有两只船湾在湖边；打鱼的人却离开船洗网去了。","notes":[]},{"n":3,"t":"有一只船是西门的，耶稣就上去，请他把船撑开，稍微离岸，就坐下，从船上教训众人。","notes":[]},{"n":4,"t":"讲完了，对西门说：「把船开到水深之处，下网打鱼。」","notes":[]},{"n":5,"t":"西门说：「夫子，我们整夜劳力，并没有打着什么。但依从你的话，我就下网。」","notes":[]},{"n":6,"t":"他们下了网，就圈住许多鱼，网险些裂开，","notes":[]},{"n":7,"t":"便招呼那只船上的同伴来帮助。他们就来，把鱼装满了两只船，甚至船要沉下去。","notes":[]},{"n":8,"t":"西门·彼得看见，就俯伏在耶稣膝前，说：「主啊，离开我，我是个罪人！」","notes":[]},{"n":9,"t":"他和一切同在的人都惊讶这一网所打的鱼。","notes":[]},{"n":10,"t":"他的伙伴西庇太的儿子雅各、约翰，也是这样。耶稣对西门说：「不要怕！从今以后，你要得人了。」","notes":[]},{"n":11,"t":"他们把两只船拢了岸，就撇下所有的，跟从了耶稣。","notes":[]},{"n":12,"t":"有一回，耶稣在一个城里，有人满身长了大麻风，看见他，就俯伏在地，求他说：「主若肯，必能叫我洁净了。」","notes":[],"heads":["洁净长大麻风的人"]},{"n":13,"t":"耶稣伸手摸他，说：「我肯，你洁净了吧！」大麻风立刻就离了他的身。","notes":[]},{"n":14,"t":"耶稣嘱咐他：「你切不可告诉人，只要去把身体给祭司察看，又要为你得了洁净，照摩西所吩咐的献上礼物，对众人作证据。」","notes":[]},{"n":15,"t":"但耶稣的名声越发传扬出去。有极多的人聚集来听道，也指望医治他们的病。","notes":[]},{"n":16,"t":"耶稣却退到旷野去祷告。","notes":[]},{"n":17,"t":"有一天，耶稣教训人，有法利赛人和教法师在旁边坐着；他们是从加利利各乡村和犹太并耶路撒冷来的。主的能力与耶稣同在，使他能医治病人。","notes":[],"heads":["治好瘫痪病人"]},{"n":18,"t":"有人用褥子抬着一个瘫子，要抬进去放在耶稣面前，","notes":[]},{"n":19,"t":"却因人多，寻不出法子抬进去，就上了房顶，从瓦间把他连褥子缒到当中，正在耶稣面前。","notes":[]},{"n":20,"t":"耶稣见他们的信心，就对瘫子说：「你的罪赦了。」","notes":[]},{"n":21,"t":"文士和法利赛人就议论说：「这说僭妄话的是谁？除了神以外，谁能赦罪呢？」","notes":[]},{"n":22,"t":"耶稣知道他们所议论的，就说：「你们心里议论的是什么呢？","notes":[]},{"n":23,"t":"或说『你的罪赦了』，或说『你起来行走』，哪一样容易呢？","notes":[]},{"n":24,"t":"但要叫你们知道，人子在地上有赦罪的权柄。」就对瘫子说：「我吩咐你，起来，拿你的褥子回家去吧！」","notes":[]},{"n":25,"t":"那人当众人面前立刻起来，拿着他所躺卧的褥子回家去，归荣耀与神。","notes":[]},{"n":26,"t":"众人都惊奇，也归荣耀与神，并且满心惧怕，说：「我们今日看见非常的事了。」","notes":[]},{"n":27,"t":"这事以后，耶稣出去，看见一个税吏，名叫利未，坐在税关上，就对他说：「你跟从我来。」","notes":[],"heads":["呼召利未"]},{"n":28,"t":"他就撇下所有的，起来，跟从了耶稣。","notes":[]},{"n":29,"t":"利未在自己家里为耶稣大摆筵席，有许多税吏和别人与他们一同坐席。","notes":[]},{"n":30,"t":"法利赛人和文士就向耶稣的门徒发怨言说：「你们为什么和税吏并罪人一同吃喝呢？」","notes":[]},{"n":31,"t":"耶稣对他们说：「无病的人用不着医生；有病的人才用得着。","notes":[]},{"n":32,"t":"我来本不是召义人悔改，乃是召罪人悔改。」","notes":[]},{"n":33,"t":"他们说：「约翰的门徒屡次禁食祈祷，法利赛人的门徒也是这样；惟独你的门徒又吃又喝。」","notes":[],"heads":["禁食的问题"]},{"n":34,"t":"耶稣对他们说：「新郎和陪伴之人同在的时候，岂能叫陪伴之人禁食呢？","notes":[]},{"n":35,"t":"但日子将到，新郎要离开他们，那日他们就要禁食了。」","notes":[]},{"n":36,"t":"耶稣又设一个比喻，对他们说：「没有人把新衣服撕下一块来补在旧衣服上；若是这样，就把新的撕破了，并且所撕下来的那块新的和旧的也不相称。","notes":[]},{"n":37,"t":"也没有人把新酒装在旧皮袋里；若是这样，新酒必将皮袋裂开，酒便漏出来，皮袋也就坏了。","notes":[]},{"n":38,"t":"但新酒必须装在新皮袋里。","notes":[]},{"n":39,"t":"没有人喝了陈酒又想喝新的；他总说陈的好。」","notes":[]}]},"6":{"heading":"安息日的问题","verses":[{"n":1,"t":"有一个安息日，耶稣从麦地经过。他的门徒掐了麦穗，用手搓着吃。","notes":[]},{"n":2,"t":"有几个法利赛人说：「你们为什么做安息日不可做的事呢？」","notes":[]},{"n":3,"t":"耶稣对他们说：「经上记着大卫和跟从他的人饥饿之时所做的事，连这个你们也没有念过吗？","notes":[]},{"n":4,"t":"他怎么进了神的殿，拿陈设饼吃，又给跟从的人吃？这饼除了祭司以外，别人都不可吃。」","notes":[]},{"n":5,"t":"又对他们说：「人子是安息日的主。」","notes":[]},{"n":6,"t":"又有一个安息日，耶稣进了会堂教训人，在那里有一个人右手枯干了。","notes":[],"heads":["治好枯干了一只手的人"]},{"n":7,"t":"文士和法利赛人窥探耶稣，在安息日治病不治病，要得把柄去告他。","notes":[]},{"n":8,"t":"耶稣却知道他们的意念，就对那枯干一只手的人说：「起来！站在当中。」那人就起来，站着。","notes":[]},{"n":9,"t":"耶稣对他们说：「我问你们，在安息日行善行恶，救命害命，哪样是可以的呢？」","notes":[]},{"n":10,"t":"他就周围看着他们众人，对那人说：「伸出手来！」他把手一伸，手就复了原。","notes":[]},{"n":11,"t":"他们就满心大怒，彼此商议怎样处治耶稣。","notes":[]},{"n":12,"t":"那时，耶稣出去，上山祷告，整夜祷告神；","notes":[],"heads":["挑选十二门徒"]},{"n":13,"t":"到了天亮，叫他的门徒来，就从他们中间挑选十二个人，称他们为使徒。","notes":[]},{"n":14,"t":"这十二个人有西门（耶稣又给他起名叫彼得），还有他兄弟安得烈，又有雅各和约翰，腓力和巴多罗买，","notes":[]},{"n":15,"t":"马太和多马，亚勒腓的儿子雅各和奋锐党的西门，","notes":[]},{"n":16,"t":"雅各的儿子犹大，和卖主的加略人犹大。","notes":["或译：兄弟"]},{"n":17,"t":"耶稣和他们下了山，站在一块平地上；同站的有许多门徒，又有许多百姓，从犹太全地和耶路撒冷，并泰尔、西顿的海边来，都要听他讲道，又指望医治他们的病；","notes":[],"heads":["向群众传道"]},{"n":18,"t":"还有被污鬼缠磨的，也得了医治。","notes":[]},{"n":19,"t":"众人都想要摸他；因为有能力从他身上发出来，医好了他们。","notes":[]},{"n":20,"t":"耶稣举目看着门徒，说：你们贫穷的人有福了！因为神的国是你们的。","notes":[],"heads":["论福和祸"]},{"n":21,"t":"你们饥饿的人有福了！因为你们将要饱足。你们哀哭的人有福了！因为你们将要喜笑。","notes":[]},{"n":22,"t":"「人为人子恨恶你们，拒绝你们，辱骂你们，弃掉你们的名，以为是恶，你们就有福了！","notes":[]},{"n":23,"t":"当那日，你们要欢喜跳跃，因为你们在天上的赏赐是大的。他们的祖宗待先知也是这样。","notes":[]},{"n":24,"t":"但你们富足的人有祸了！因为你们受过你们的安慰。","notes":[]},{"n":25,"t":"你们饱足的人有祸了！因为你们将要饥饿。你们喜笑的人有祸了！因为你们将要哀恸哭泣。","notes":[]},{"n":26,"t":"「人都说你们好的时候，你们就有祸了！因为他们的祖宗待假先知也是这样。」","notes":[]},{"n":27,"t":"「只是我告诉你们这听道的人，你们的仇敌，要爱他！恨你们的，要待他好！","notes":[],"heads":["论爱仇敌"]},{"n":28,"t":"咒诅你们的，要为他祝福！凌辱你们的，要为他祷告！","notes":[]},{"n":29,"t":"有人打你这边的脸，连那边的脸也由他打。有人夺你的外衣，连里衣也由他拿去。","notes":[]},{"n":30,"t":"凡求你的，就给他。有人夺你的东西去，不用再要回来。","notes":[]},{"n":31,"t":"你们愿意人怎样待你们，你们也要怎样待人。","notes":[]},{"n":32,"t":"你们若单爱那爱你们的人，有什么可酬谢的呢？就是罪人也爱那爱他们的人。","notes":[]},{"n":33,"t":"你们若善待那善待你们的人，有什么可酬谢的呢？就是罪人也是这样行。","notes":[]},{"n":34,"t":"你们若借给人，指望从他收回，有什么可酬谢的呢？就是罪人也借给罪人，要如数收回。","notes":[]},{"n":35,"t":"你们倒要爱仇敌，也要善待他们，并要借给人不指望偿还，你们的赏赐就必大了，你们也必作至高者的儿子，因为他恩待那忘恩的和作恶的。","notes":[]},{"n":36,"t":"你们要慈悲，像你们的父慈悲一样。」","notes":[]},{"n":37,"t":"「你们不要论断人，就不被论断；你们不要定人的罪，就不被定罪；你们要饶恕人，就必蒙饶恕；","notes":["饶恕：原文是释放"],"heads":["不要论断人"]},{"n":38,"t":"你们要给人，就必有给你们的，并且用十足的升斗，连摇带按，上尖下流地倒在你们怀里；因为你们用什么量器量给人，也必用什么量器量给你们。」","notes":[]},{"n":39,"t":"耶稣又用比喻对他们说：「瞎子岂能领瞎子，两个人不是都要掉在坑里吗？","notes":[]},{"n":40,"t":"学生不能高过先生；凡学成了的不过和先生一样。","notes":[]},{"n":41,"t":"为什么看见你弟兄眼中有刺，却不想自己眼中有梁木呢？","notes":[]},{"n":42,"t":"你不见自己眼中有梁木，怎能对你弟兄说：『容我去掉你眼中的刺』呢？你这假冒为善的人！先去掉自己眼中的梁木，然后才能看得清楚，去掉你弟兄眼中的刺。」","notes":[]},{"n":43,"t":"「因为，没有好树结坏果子，也没有坏树结好果子。","notes":[],"heads":["树和果子"]},{"n":44,"t":"凡树木看果子，就可以认出它来。人不是从荆棘上摘无花果，也不是从蒺藜里摘葡萄。","notes":[]},{"n":45,"t":"善人从他心里所存的善就发出善来；恶人从他心里所存的恶就发出恶来；因为心里所充满的，口里就说出来。」","notes":[]},{"n":46,"t":"「你们为什么称呼我『主啊，主啊』却不遵我的话行呢？","notes":[],"heads":["两种盖房子的人"]},{"n":47,"t":"凡到我这里来，听见我的话就去行的，我要告诉你们他像什么人：","notes":[]},{"n":48,"t":"他像一个人盖房子，深深地挖地，把根基安在磐石上；到发大水的时候，水冲那房子，房子总不能摇动，因为根基立在磐石上。","notes":["有古卷：因为盖造得好"]},{"n":49,"t":"惟有听见不去行的，就像一个人在土地上盖房子，没有根基；水一冲，随即倒塌了，并且那房子坏的很大。」","notes":[]}]},"7":{"heading":"治好百夫长的仆人","verses":[{"n":1,"t":"耶稣对百姓讲完了这一切的话，就进了迦百农。","notes":[]},{"n":2,"t":"有一个百夫长所宝贵的仆人害病，快要死了。","notes":[]},{"n":3,"t":"百夫长风闻耶稣的事，就托犹太人的几个长老去求耶稣来救他的仆人。","notes":[]},{"n":4,"t":"他们到了耶稣那里，就切切地求他说：「你给他行这事是他所配得的；","notes":[]},{"n":5,"t":"因为他爱我们的百姓，给我们建造会堂。」","notes":[]},{"n":6,"t":"耶稣就和他们同去。离那家不远，百夫长托几个朋友去见耶稣，对他说：「主啊！不要劳动；因你到我舍下，我不敢当。","notes":[]},{"n":7,"t":"我也自以为不配去见你，只要你说一句话，我的仆人就必好了。","notes":[]},{"n":8,"t":"因为我在人的权下，也有兵在我以下，对这个说：『去！』他就去；对那个说：『来！』他就来；对我的仆人说：『你做这事！』他就去做。」","notes":[]},{"n":9,"t":"耶稣听见这话，就希奇他，转身对跟随的众人说：「我告诉你们，这么大的信心，就是在以色列中，我也没有遇见过。」","notes":[]},{"n":10,"t":"那托来的人回到百夫长家里，看见仆人已经好了。","notes":[]},{"n":11,"t":"过了不多时，耶稣往一座城去，这城名叫拿因，他的门徒和极多的人与他同行。","notes":["有古卷：次日"],"heads":["使拿因城寡妇之子复活"]},{"n":12,"t":"将近城门，有一个死人被抬出来。这人是他母亲独生的儿子；他母亲又是寡妇。有城里的许多人同着寡妇送殡。","notes":[]},{"n":13,"t":"主看见那寡妇，就怜悯她，对她说：「不要哭！」","notes":[]},{"n":14,"t":"于是进前按着杠，抬的人就站住了。耶稣说：「少年人，我吩咐你，起来！」","notes":[]},{"n":15,"t":"那死人就坐起，并且说话。耶稣便把他交给他母亲。","notes":[]},{"n":16,"t":"众人都惊奇，归荣耀与神，说：「有大先知在我们中间兴起来了！」又说：「神眷顾了他的百姓！」","notes":[]},{"n":17,"t":"他这事的风声就传遍了犹太和周围地方。","notes":[]},{"n":18,"t":"约翰的门徒把这些事都告诉约翰。","notes":[],"heads":["施洗约翰的门徒来见耶稣"]},{"n":19,"t":"他便叫了两个门徒来，打发他们到主那里去，说：「那将要来的是你吗？还是我们等候别人呢？」","notes":[]},{"n":20,"t":"那两个人来到耶稣那里，说：「施洗的约翰打发我们来问你：『那将要来的是你吗？还是我们等候别人呢？』」","notes":[]},{"n":21,"t":"正当那时候，耶稣治好了许多有疾病的，受灾患的，被恶鬼附着的，又开恩叫好些瞎子能看见。","notes":[]},{"n":22,"t":"耶稣回答说：「你们去，把所看见所听见的事告诉约翰，就是瞎子看见，瘸子行走，长大麻风的洁净，聋子听见，死人复活，穷人有福音传给他们。","notes":[]},{"n":23,"t":"凡不因我跌倒的，就有福了！」","notes":[]},{"n":24,"t":"约翰所差来的人既走了，耶稣就对众人讲论约翰说：「你们从前出去到旷野，是要看什么呢？要看风吹动的芦苇吗？","notes":[]},{"n":25,"t":"你们出去，到底是要看什么？要看穿细软衣服的人吗？那穿华丽衣服、宴乐度日的人是在王宫里。","notes":[]},{"n":26,"t":"你们出去，究竟是要看什么？要看先知吗？我告诉你们，是的，他比先知大多了。","notes":[]},{"n":27,"t":"经上记着说：『我要差遣我的使者在你前面预备道路』，所说的就是这个人。","notes":[]},{"n":28,"t":"我告诉你们，凡妇人所生的，没有一个大过约翰的；然而神国里最小的比他还大。」","notes":[]},{"n":29,"t":"众百姓和税吏既受过约翰的洗，听见这话，就以神为义；","notes":[]},{"n":30,"t":"但法利赛人和律法师没有受过约翰的洗，竟为自己废弃了神 的旨意。","notes":["二十九三十两节或译：众百姓和税吏听见了约翰的话，就受了他的洗，便以 神为义；但法利赛人和律法师不受约翰的洗，竟为自己废弃了神的旨意。"]},{"n":31,"t":"主又说：「这样，我可用什么比这世代的人呢？他们好像什么呢？","notes":[]},{"n":32,"t":"好像孩童坐在街市上，彼此呼叫说：我们向你们吹笛，你们不跳舞；我们向你们举哀，你们不啼哭。","notes":[]},{"n":33,"t":"施洗的约翰来，不吃饼，不喝酒，你们说他是被鬼附着的。","notes":[]},{"n":34,"t":"人子来，也吃也喝，你们说他是贪食好酒的人，是税吏和罪人的朋友。","notes":[]},{"n":35,"t":"但智慧之子都以智慧为是。」","notes":[]},{"n":36,"t":"有一个法利赛人请耶稣和他吃饭；耶稣就到法利赛人家里去坐席。","notes":[],"heads":["有罪的女人得蒙赦免"]},{"n":37,"t":"那城里有一个女人，是个罪人，知道耶稣在法利赛人家里坐席，就拿着盛香膏的玉瓶，","notes":[]},{"n":38,"t":"站在耶稣背后，挨着他的脚哭，眼泪湿了耶稣的脚，就用自己的头发擦干，又用嘴连连亲他的脚，把香膏抹上。","notes":[]},{"n":39,"t":"请耶稣的法利赛人看见这事，心里说：「这人若是先知，必知道摸他的是谁，是个怎样的女人；乃是个罪人。」","notes":[]},{"n":40,"t":"耶稣对他说：「西门！我有句话要对你说。」西门说：「夫子，请说。」","notes":[]},{"n":41,"t":"耶稣说：「一个债主有两个人欠他的债；一个欠五十两银子，一个欠五两银子；","notes":[]},{"n":42,"t":"因为他们无力偿还，债主就开恩免了他们两个人的债。这两个人哪一个更爱他呢？」","notes":[]},{"n":43,"t":"西门回答说：「我想是那多得恩免的人。」耶稣说：「你断的不错。」","notes":[]},{"n":44,"t":"于是转过来向着那女人，便对西门说：「你看见这女人吗？我进了你的家，你没有给我水洗脚；但这女人用眼泪湿了我的脚，用头发擦干。","notes":[]},{"n":45,"t":"你没有与我亲嘴；但这女人从我进来的时候就不住地用嘴亲我的脚。","notes":[]},{"n":46,"t":"你没有用油抹我的头；但这女人用香膏抹我的脚。","notes":[]},{"n":47,"t":"所以我告诉你，她许多的罪都赦免了，因为她的爱多；但那赦免少的，他的爱就少。」","notes":[]},{"n":48,"t":"于是对那女人说：「你的罪赦免了。」","notes":[]},{"n":49,"t":"同席的人心里说：「这是什么人，竟赦免人的罪呢？」","notes":[]},{"n":50,"t":"耶稣对那女人说：「你的信救了你；平平安安回去吧！」","notes":[]}]},"8":{"heading":"跟从耶稣的妇女们","verses":[{"n":1,"t":"过了不多日，耶稣周游各城各乡传道，宣讲神国的福音。和他同去的有十二个门徒，","notes":[]},{"n":2,"t":"还有被恶鬼所附、被疾病所累、已经治好的几个妇女，内中有称为抹大拉的马利亚（曾有七个鬼从她身上赶出来），","notes":[]},{"n":3,"t":"又有希律的家宰苦撒的妻子约亚拿，并苏撒拿，和好些别的妇女，都是用自己的财物供给耶稣和门徒。","notes":[]},{"n":4,"t":"当许多人聚集、又有人从各城里出来见耶稣的时候，耶稣就用比喻说：","notes":[],"heads":["撒种的比喻"]},{"n":5,"t":"「有一个撒种的出去撒种。撒的时候，有落在路旁的，被人践踏，天上的飞鸟又来吃尽了。","notes":[]},{"n":6,"t":"有落在磐石上的，一出来就枯干了，因为得不着滋润。","notes":[]},{"n":7,"t":"有落在荆棘里的，荆棘一同生长，把它挤住了。","notes":[]},{"n":8,"t":"又有落在好土里的，生长起来，结实百倍。」耶稣说了这些话，就大声说：「有耳可听的，就应当听！」","notes":[]},{"n":9,"t":"门徒问耶稣说：「这比喻是什么意思呢？」","notes":[],"heads":["用比喻的目的"]},{"n":10,"t":"他说：「神国的奥秘只叫你们知道；至于别人，就用比喻，叫他们看也看不见，听也听不明。」","notes":[]},{"n":11,"t":"「这比喻乃是这样：种子就是神的道。","notes":[],"heads":["解明撒种的比喻"]},{"n":12,"t":"那些在路旁的，就是人听了道，随后魔鬼来，从他们心里把道夺去，恐怕他们信了得救。","notes":[]},{"n":13,"t":"那些在磐石上的，就是人听道，欢喜领受，但心中没有根，不过暂时相信，及至遇见试炼就退后了。","notes":[]},{"n":14,"t":"那落在荆棘里的，就是人听了道，走开以后，被今生的思虑、钱财、宴乐挤住了，便结不出成熟的子粒来。","notes":[]},{"n":15,"t":"那落在好土里的，就是人听了道，持守在诚实善良的心里，并且忍耐着结实。」","notes":[]},{"n":16,"t":"「没有人点灯用器皿盖上，或放在床底下，乃是放在灯台上，叫进来的人看见亮光。","notes":[],"heads":["器皿下的灯"]},{"n":17,"t":"因为掩藏的事没有不显出来的；隐瞒的事没有不露出来被人知道的。","notes":[]},{"n":18,"t":"所以，你们应当小心怎样听；因为凡有的，还要加给他；凡没有的，连他自以为有的，也要夺去。」","notes":[]},{"n":19,"t":"耶稣的母亲和他弟兄来了，因为人多，不得到他跟前。","notes":[],"heads":["耶稣的母亲和兄弟们"]},{"n":20,"t":"有人告诉他说：「你母亲和你弟兄站在外边，要见你。」","notes":[]},{"n":21,"t":"耶稣回答说：「听了神之道而遵行的人就是我的母亲，我的弟兄了。」","notes":[]},{"n":22,"t":"有一天，耶稣和门徒上了船，对门徒说：「我们可以渡到湖那边去。」他们就开了船。","notes":[],"heads":["平静风浪"]},{"n":23,"t":"正行的时候，耶稣睡着了。湖上忽然起了暴风，船将满了水，甚是危险。","notes":[]},{"n":24,"t":"门徒来叫醒了他，说：「夫子！夫子！我们丧命啦！」耶稣醒了，斥责那狂风大浪；风浪就止住，平静了。","notes":[]},{"n":25,"t":"耶稣对他们说：「你们的信心在哪里呢？」他们又惧怕又希奇，彼此说：「这到底是谁？他吩咐风和水，连风和水也听从他了。」","notes":[]},{"n":26,"t":"他们到了格拉森人的地方，就是加利利的对面。","notes":["有古卷：加大拉"],"heads":["治好格拉森被鬼附的人"]},{"n":27,"t":"耶稣上了岸，就有城里一个被鬼附着的人迎面而来。这个人许久不穿衣服，不住房子，只住在坟茔里。","notes":[]},{"n":28,"t":"他见了耶稣，就俯伏在他面前，大声喊叫，说：「至高神的儿子耶稣，我与你有什么相干？求你不要叫我受苦！」","notes":[]},{"n":29,"t":"是因耶稣曾吩咐污鬼从那人身上出来。原来这鬼屡次抓住他；他常被人看守，又被铁链和脚镣捆锁，他竟把锁链挣断，被鬼赶到旷野去。","notes":[]},{"n":30,"t":"耶稣问他说：「你名叫什么？」他说：「我名叫『群』」；这是因为附着他的鬼多。","notes":[]},{"n":31,"t":"鬼就央求耶稣，不要吩咐他们到无底坑里去。","notes":[]},{"n":32,"t":"那里有一大群猪在山上吃食。鬼央求耶稣，准他们进入猪里去。耶稣准了他们，","notes":[]},{"n":33,"t":"鬼就从那人出来，进入猪里去。于是那群猪闯下山崖，投在湖里淹死了。","notes":[]},{"n":34,"t":"放猪的看见这事就逃跑了，去告诉城里和乡下的人。","notes":[]},{"n":35,"t":"众人出来要看是什么事；到了耶稣那里，看见鬼所离开的那人，坐在耶稣脚前，穿着衣服，心里明白过来，他们就害怕。","notes":[]},{"n":36,"t":"看见这事的便将被鬼附着的人怎么得救告诉他们。","notes":[]},{"n":37,"t":"格拉森四围的人，因为害怕得很，都求耶稣离开他们；耶稣就上船回去了。","notes":[]},{"n":38,"t":"鬼所离开的那人恳求和耶稣同在；耶稣却打发他回去，说：","notes":[]},{"n":39,"t":"「你回家去，传说神为你做了何等大的事。」他就去，满城里传扬耶稣为他做了何等大的事。","notes":[]},{"n":40,"t":"耶稣回来的时候，众人迎接他，因为他们都等候他。","notes":[],"heads":["睚鲁的女儿和血漏的女人"]},{"n":41,"t":"有一个管会堂的，名叫睚鲁，来俯伏在耶稣脚前，求耶稣到他家里去；","notes":[]},{"n":42,"t":"因他有一个独生女儿，约有十二岁，快要死了。耶稣去的时候，众人拥挤他。","notes":[]},{"n":43,"t":"有一个女人，患了十二年的血漏，在医生手里花尽了她一切养生的，并没有一人能医好她。","notes":[]},{"n":44,"t":"她来到耶稣背后，摸他的衣裳繸子，血漏立刻就止住了。","notes":[]},{"n":45,"t":"耶稣说：「摸我的是谁？」众人都不承认。彼得和同行的人都说：「夫子，众人拥拥挤挤紧靠着你。」","notes":["有古卷加：你还问摸我的是谁吗？"]},{"n":46,"t":"耶稣说：「总有人摸我，因我觉得有能力从我身上出去。」","notes":[]},{"n":47,"t":"那女人知道不能隐藏，就战战兢兢地来俯伏在耶稣脚前，把摸他的缘故和怎样立刻得好了，当着众人都说出来。","notes":[]},{"n":48,"t":"耶稣对她说：「女儿，你的信救了你；平平安安地去吧！」","notes":[]},{"n":49,"t":"还说话的时候，有人从管会堂的家里来，说：「你的女儿死了，不要劳动夫子。」","notes":[]},{"n":50,"t":"耶稣听见就对他说：「不要怕，只要信！你的女儿就必得救。」","notes":[]},{"n":51,"t":"耶稣到了他的家，除了彼得、约翰、雅各，和女儿的父母，不许别人同他进去。","notes":[]},{"n":52,"t":"众人都为这女儿哀哭捶胸。耶稣说：「不要哭！她不是死了，是睡着了。」","notes":[]},{"n":53,"t":"他们晓得女儿已经死了，就嗤笑耶稣。","notes":[]},{"n":54,"t":"耶稣拉着她的手，呼叫说：「女儿，起来吧！」","notes":[]},{"n":55,"t":"她的灵魂便回来，她就立刻起来了。耶稣吩咐给她东西吃。","notes":[]},{"n":56,"t":"她的父母惊奇得很；耶稣嘱咐他们，不要把所做的事告诉人。","notes":[]}]},"9":{"heading":"耶稣差遣十二个门徒","verses":[{"n":1,"t":"耶稣叫齐了十二个门徒，给他们能力、权柄，制伏一切的鬼，医治各样的病，","notes":[]},{"n":2,"t":"又差遣他们去宣传神国的道，医治病人，","notes":[]},{"n":3,"t":"对他们说：「行路的时候，不要带拐杖和口袋，不要带食物和银子，也不要带两件褂子。","notes":[]},{"n":4,"t":"无论进哪一家，就住在那里，也从那里起行。","notes":[]},{"n":5,"t":"凡不接待你们的，你们离开那城的时候，要把脚上的尘土跺下去，见证他们的不是。」","notes":[]},{"n":6,"t":"门徒就出去，走遍各乡宣传福音，到处治病。","notes":[]},{"n":7,"t":"分封的王希律听见耶稣所做的一切事，就游移不定；因为有人说：「是约翰从死里复活」；","notes":[],"heads":["希律的困惑"]},{"n":8,"t":"又有人说：「是以利亚显现」；还有人说：「是古时的一个先知又活了。」","notes":[]},{"n":9,"t":"希律说：「约翰我已经斩了，这却是什么人？我竟听见他这样的事呢？」就想要见他。","notes":[]},{"n":10,"t":"使徒回来，将所做的事告诉耶稣，耶稣就带他们暗暗地离开那里，往一座城去；那城名叫伯赛大。","notes":[],"heads":["耶稣给五千人吃饱"]},{"n":11,"t":"但众人知道了，就跟着他去；耶稣便接待他们，对他们讲论神国的道，医治那些需医的人。","notes":[]},{"n":12,"t":"日头快要平西，十二个门徒来对他说：「请叫众人散开，他们好往四面乡村里去借宿找吃的，因为我们这里是野地。」","notes":[]},{"n":13,"t":"耶稣说：「你们给他们吃吧！」门徒说：「我们不过有五个饼，两条鱼，若不去为这许多人买食物就不够。」","notes":[]},{"n":14,"t":"那时，人数约有五千。耶稣对门徒说：「叫他们一排一排地坐下，每排大约五十个人。」","notes":[]},{"n":15,"t":"门徒就如此行，叫众人都坐下。","notes":[]},{"n":16,"t":"耶稣拿着这五个饼，两条鱼，望着天祝福，擘开，递给门徒，摆在众人面前。","notes":[]},{"n":17,"t":"他们就吃，并且都吃饱了；把剩下的零碎收拾起来，装满了十二篮子。","notes":[]},{"n":18,"t":"耶稣自己祷告的时候，门徒也同他在那里。耶稣问他们说：「众人说我是谁？」","notes":[],"heads":["彼得认耶稣为基督"]},{"n":19,"t":"他们说：「有人说是施洗的约翰；有人说是以利亚；还有人说是古时的一个先知又活了。」","notes":[]},{"n":20,"t":"耶稣说：「你们说我是谁？」彼得回答说：「是神所立的基督。」","notes":[]},{"n":21,"t":"耶稣切切地嘱咐他们，不可将这事告诉人，","notes":[],"heads":["耶稣预言受难和复活"]},{"n":22,"t":"又说：「人子必须受许多的苦，被长老、祭司长，和文士弃绝，并且被杀，第三日复活。」","notes":[]},{"n":23,"t":"耶稣又对众人说：「若有人要跟从我，就当舍己，天天背起他的十字架来跟从我。","notes":[]},{"n":24,"t":"因为，凡要救自己生命的，必丧掉生命；凡为我丧掉生命的，必救了生命。","notes":["生命：或译灵魂；下同"]},{"n":25,"t":"人若赚得全世界，却丧了自己，赔上自己，有什么益处呢？","notes":[]},{"n":26,"t":"凡把我和我的道当作可耻的，人子在自己的荣耀里，并天父与圣天使的荣耀里降临的时候，也要把那人当作可耻的。","notes":[]},{"n":27,"t":"我实在告诉你们，站在这里的，有人在没尝死味以前，必看见神的国。」","notes":[]},{"n":28,"t":"说了这话以后约有八天，耶稣带着彼得、约翰、雅各上山去祷告。","notes":[],"heads":["耶稣改变形象"]},{"n":29,"t":"正祷告的时候，他的面貌就改变了，衣服洁白放光。","notes":[]},{"n":30,"t":"忽然有摩西、以利亚两个人同耶稣说话；","notes":[]},{"n":31,"t":"他们在荣光里显现，谈论耶稣去世的事，就是他在耶路撒冷将要成的事。","notes":[]},{"n":32,"t":"彼得和他的同伴都打盹，既清醒了，就看见耶稣的荣光，并同他站着的那两个人。","notes":[]},{"n":33,"t":"二人正要和耶稣分离的时候，彼得对耶稣说：「夫子，我们在这里真好！可以搭三座棚，一座为你，一座为摩西，一座为以利亚。」他却不知道所说的是什么。","notes":[]},{"n":34,"t":"说这话的时候，有一朵云彩来遮盖他们；他们进入云彩里就惧怕。","notes":[]},{"n":35,"t":"有声音从云彩里出来，说：「这是我的儿子，我所拣选的，你们要听他。」","notes":["有古卷：这是我的爱子"]},{"n":36,"t":"声音住了，只见耶稣一人在那里。当那些日子，门徒不提所看见的事，一样也不告诉人。","notes":[]},{"n":37,"t":"第二天，他们下了山，就有许多人迎见耶稣。","notes":[],"heads":["治好被污鬼附身的孩子"]},{"n":38,"t":"其中有一人喊叫说：「夫子！求你看顾我的儿子，因为他是我的独生子。","notes":[]},{"n":39,"t":"他被鬼抓住就忽然喊叫；鬼又叫他抽风，口中流沫，并且重重地伤害他，难以离开他。","notes":[]},{"n":40,"t":"我求过你的门徒，把鬼赶出去，他们却是不能。」","notes":[]},{"n":41,"t":"耶稣说：「嗳！这又不信又悖谬的世代啊，我在你们这里，忍耐你们要到几时呢？将你的儿子带到这里来吧！」","notes":[]},{"n":42,"t":"正来的时候，鬼把他摔倒，叫他重重地抽风。耶稣就斥责那污鬼，把孩子治好了，交给他父亲。","notes":[]},{"n":43,"t":"众人都诧异神的大能。耶稣所做的一切事，众人正希奇的时候，耶稣对门徒说：","notes":["大能：或译威荣"]},{"n":44,"t":"「你们要把这些话存在耳中，因为人子将要被交在人手里。」","notes":[]},{"n":45,"t":"他们不明白这话，意思乃是隐藏的，叫他们不能明白，他们也不敢问这话的意思。","notes":[]},{"n":46,"t":"门徒中间起了议论，谁将为大。","notes":[],"heads":["谁最伟大"]},{"n":47,"t":"耶稣看出他们心中的议论，就领一个小孩子来，叫他站在自己旁边，","notes":[]},{"n":48,"t":"对他们说：「凡为我名接待这小孩子的，就是接待我；凡接待我的，就是接待那差我来的。你们中间最小的，他便为大。」","notes":[]},{"n":49,"t":"约翰说：「夫子，我们看见一个人奉你的名赶鬼，我们就禁止他，因为他不与我们一同跟从你。」","notes":[],"heads":["不敌挡你们就是帮助你们"]},{"n":50,"t":"耶稣说：「不要禁止他；因为不敌挡你们的，就是帮助你们的。」","notes":[]},{"n":51,"t":"耶稣被接上升的日子将到，他就定意向耶路撒冷去，","notes":[],"heads":["不接待主的村庄"]},{"n":52,"t":"便打发使者在他前头走。他们到了撒马利亚的一个村庄，要为他预备。","notes":[]},{"n":53,"t":"那里的人不接待他，因他面向耶路撒冷去。","notes":[]},{"n":54,"t":"他的门徒雅各、约翰看见了，就说：「主啊，你要我们吩咐火从天上降下来烧灭他们，像以利亚所做的吗？」","notes":["有古卷没有像以利亚所做的这几个字"]},{"n":55,"t":"耶稣转身责备两个门徒，说：「你们的心如何，你们并不知道。","notes":[]},{"n":56,"t":"人子来不是要灭人的性命，是要救人的性命。」说着就往别的村庄去了。","notes":["性命：或译灵魂；下同","有古卷只有五十五节首句，五十六节末句"]},{"n":57,"t":"他们走路的时候，有一人对耶稣说：「你无论往哪里去，我要跟从你。」","notes":[],"heads":["要跟从耶稣的人"]},{"n":58,"t":"耶稣说：「狐狸有洞，天空的飞鸟有窝，只是人子没有枕头的地方。」","notes":[]},{"n":59,"t":"又对一个人说：「跟从我来！」那人说：「主，容我先回去埋葬我的父亲。」","notes":[]},{"n":60,"t":"耶稣说：「任凭死人埋葬他们的死人，你只管去传扬神国的道。」","notes":[]},{"n":61,"t":"又有一人说：「主，我要跟从你，但容我先去辞别我家里的人。」","notes":[]},{"n":62,"t":"耶稣说：「手扶着犁向后看的，不配进神的国。」","notes":[]}]},"10":{"heading":"主差遣七十人","verses":[{"n":1,"t":"这事以后，主又设立七十个人，差遣他们两个两个地在他前面，往自己所要到的各城各地方去，","notes":[]},{"n":2,"t":"就对他们说：「要收的庄稼多，做工的人少。所以，你们当求庄稼的主打发工人出去收他的庄稼。","notes":[]},{"n":3,"t":"你们去吧！我差你们出去，如同羊羔进入狼群。","notes":[]},{"n":4,"t":"不要带钱囊，不要带口袋，不要带鞋；在路上也不要问人的安。","notes":[]},{"n":5,"t":"无论进哪一家，先要说：『愿这一家平安。』","notes":[]},{"n":6,"t":"那里若有当得平安的人，你们所求的平安就必临到那家；不然，就归与你们了。","notes":["当得平安的人：原文是平安之子"]},{"n":7,"t":"你们要住在那家，吃喝他们所供给的，因为工人得工价是应当的；不要从这家搬到那家。","notes":[]},{"n":8,"t":"无论进哪一城，人若接待你们，给你们摆上什么，你们就吃什么。","notes":[]},{"n":9,"t":"要医治那城里的病人，对他们说：『神的国临近你们了。』","notes":[]},{"n":10,"t":"无论进哪一城，人若不接待你们，你们就到街上去，","notes":[]},{"n":11,"t":"说：『就是你们城里的尘土黏在我们的脚上，我们也当着你们擦去。虽然如此，你们该知道神的国临近了。』","notes":[]},{"n":12,"t":"我告诉你们，当审判的日子，所多玛所受的，比那城还容易受呢！」","notes":[]},{"n":13,"t":"「哥拉汛哪，你有祸了！伯赛大啊，你有祸了！因为在你们中间所行的异能若行在泰尔、西顿，他们早已披麻蒙灰，坐在地上悔改了。","notes":[],"heads":["不悔改的城有祸了"]},{"n":14,"t":"当审判的日子，泰尔、西顿所受的，比你们还容易受呢！","notes":[]},{"n":15,"t":"迦百农啊，你已经升到天上，将来必推下阴间。」","notes":["或译：你将要升到天上吗"]},{"n":16,"t":"又对门徒说：「听从你们的就是听从我；弃绝你们的就是弃绝我；弃绝我的就是弃绝那差我来的。」","notes":[]},{"n":17,"t":"那七十个人欢欢喜喜地回来，说：「主啊！因你的名，就是鬼也服了我们。」","notes":[],"heads":["七十个人回来"]},{"n":18,"t":"耶稣对他们说：「我曾看见撒但从天上坠落，像闪电一样。","notes":[]},{"n":19,"t":"我已经给你们权柄可以践踏蛇和蝎子，又胜过仇敌一切的能力，断没有什么能害你们。","notes":[]},{"n":20,"t":"然而，不要因鬼服了你们就欢喜，要因你们的名记录在天上欢喜。」","notes":[]},{"n":21,"t":"正当那时，耶稣被圣灵感动就欢乐，说：「父啊，天地的主，我感谢你！因为你将这些事向聪明通达人就藏起来，向婴孩就显出来。父啊！是的，因为你的美意本是如此。","notes":[],"heads":["耶稣的欢乐"]},{"n":22,"t":"一切所有的都是我父交付我的；除了父，没有人知道子是谁；除了子和子所愿意指示的，没有人知道父是谁。」","notes":[]},{"n":23,"t":"耶稣转身暗暗地对门徒说：「看见你们所看见的，那眼睛就有福了。","notes":[]},{"n":24,"t":"我告诉你们，从前有许多先知和君王要看你们所看的，却没有看见，要听你们所听的，却没有听见。」","notes":[]},{"n":25,"t":"有一个律法师起来试探耶稣， 说：「夫子！我该做什么才可以承受永生？」","notes":[],"heads":["好撒马利亚人"]},{"n":26,"t":"耶稣对他说：「律法上写的是什么？你念的是怎样呢？」","notes":[]},{"n":27,"t":"他回答说：「你要尽心、尽性、尽力、尽意爱主—你的神；又要爱邻舍如同自己。」","notes":[]},{"n":28,"t":"耶稣说：「你回答的是；你这样行，就必得永生。」","notes":[]},{"n":29,"t":"那人要显明自己有理，就对耶稣说：「谁是我的邻舍呢？」","notes":[]},{"n":30,"t":"耶稣回答说：「有一个人从耶路撒冷下耶利哥去，落在强盗手中。他们剥去他的衣裳，把他打个半死，就丢下他走了。","notes":[]},{"n":31,"t":"偶然有一个祭司从这条路下来，看见他就从那边过去了。","notes":[]},{"n":32,"t":"又有一个利未人来到这地方，看见他，也照样从那边过去了。","notes":[]},{"n":33,"t":"惟有一个撒马利亚人行路来到那里，看见他就动了慈心，","notes":[]},{"n":34,"t":"上前用油和酒倒在他的伤处，包裹好了，扶他骑上自己的牲口，带到店里去照应他。","notes":[]},{"n":35,"t":"第二天拿出二钱银子来，交给店主，说：『你且照应他；此外所费用的，我回来必还你。』","notes":[]},{"n":36,"t":"你想，这三个人哪一个是落在强盗手中的邻舍呢？」","notes":[]},{"n":37,"t":"他说：「是怜悯他的。」耶稣说：「你去照样行吧。」","notes":[]},{"n":38,"t":"他们走路的时候，耶稣进了一个村庄。有一个女人，名叫马大，接他到自己家里。","notes":[],"heads":["耶稣探望马大和马利亚"]},{"n":39,"t":"她有一个妹子，名叫马利亚，在耶稣脚前坐着听他的道。","notes":[]},{"n":40,"t":"马大伺候的事多，心里忙乱，就进前来，说：「主啊，我的妹子留下我一个人伺候，你不在意吗？请吩咐她来帮助我。」","notes":[]},{"n":41,"t":"耶稣回答说：「马大！马大！你为许多的事思虑烦扰，","notes":[]},{"n":42,"t":"但是不可少的只有一件；马利亚已经选择那上好的福分，是不能夺去的。」","notes":[]}]},"11":{"heading":"祷告的教训","verses":[{"n":1,"t":"耶稣在一个地方祷告；祷告完了，有个门徒对他说：「求主教导我们祷告，像约翰教导他的门徒。」","notes":[]},{"n":2,"t":"耶稣说：「你们祷告的时候，要说：我们在天上的父：愿人都尊你的名为圣。愿你的国降临；愿你的旨意行在地上，如同行在天上。","notes":["有古卷：父啊","有古卷没有愿你的旨意…"]},{"n":3,"t":"我们日用的饮食，天天赐给我们。","notes":[]},{"n":4,"t":"赦免我们的罪，因为我们也赦免凡亏欠我们的人。不叫我们遇见试探；救我们脱离凶恶。」","notes":["有古卷没有末句"]},{"n":5,"t":"耶稣又说：「你们中间谁有一个朋友半夜到他那里去，说：『朋友！请借给我三个饼；","notes":[]},{"n":6,"t":"因为我有一个朋友行路，来到我这里，我没有什么给他摆上。』","notes":[]},{"n":7,"t":"那人在里面回答说：『不要搅扰我，门已经关闭，孩子们也同我在床上了，我不能起来给你。』","notes":[]},{"n":8,"t":"我告诉你们，虽不因他是朋友起来给他，但因他情词迫切地直求，就必起来照他所需用的给他。","notes":[]},{"n":9,"t":"我又告诉你们，你们祈求，就给你们；寻找，就寻见；叩门，就给你们开门。","notes":[]},{"n":10,"t":"因为，凡祈求的，就得着；寻找的，就寻见；叩门的，就给他开门。","notes":[]},{"n":11,"t":"你们中间作父亲的，谁有儿子求饼，反给他石头呢？求鱼，反拿蛇当鱼给他呢？","notes":[]},{"n":12,"t":"求鸡蛋，反给他蝎子呢？","notes":[]},{"n":13,"t":"你们虽然不好，尚且知道拿好东西给儿女；何况天父，岂不更将圣灵给求他的人吗？」","notes":[]},{"n":14,"t":"耶稣赶出一个叫人哑巴的鬼；鬼出去了，哑巴就说出话来；众人都希奇。","notes":[],"heads":["耶稣和别西卜"]},{"n":15,"t":"内中却有人说：「他是靠着鬼王别西卜赶鬼。」","notes":[]},{"n":16,"t":"又有人试探耶稣，向他求从天上来的神迹。","notes":[]},{"n":17,"t":"他晓得他们的意念，便对他们说：「凡一国自相纷争，就成为荒场；凡一家自相纷争，就必败落。","notes":[]},{"n":18,"t":"若撒但自相纷争，他的国怎能站得住呢？因为你们说我是靠着别西卜赶鬼。","notes":[]},{"n":19,"t":"我若靠着别西卜赶鬼，你们的子弟赶鬼又靠着谁呢？这样，他们就要断定你们的是非。","notes":[]},{"n":20,"t":"我若靠着神的能力赶鬼，这就是神的国临到你们了。","notes":[]},{"n":21,"t":"壮士披挂整齐，看守自己的住宅，他所有的都平安无事；","notes":[]},{"n":22,"t":"但有一个比他更壮的来，胜过他，就夺去他所倚靠的盔甲兵器，又分了他的赃。","notes":[]},{"n":23,"t":"不与我相合的，就是敌我的；不同我收聚的，就是分散的。」","notes":[]},{"n":24,"t":"「污鬼离了人身，就在无水之地过来过去，寻求安歇之处；既寻不着，便说：『我要回到我所出来的屋里去。』","notes":[],"heads":["污鬼回来"]},{"n":25,"t":"到了，就看见里面打扫干净，修饰好了，","notes":[]},{"n":26,"t":"便去另带了七个比自己更恶的鬼来，都进去住在那里。那人末后的景况比先前更不好了。」","notes":[]},{"n":27,"t":"耶稣正说这话的时候，众人中间有一个女人大声说：「怀你胎的和乳养你的有福了！」","notes":[],"heads":["真正的福"]},{"n":28,"t":"耶稣说：「是，却还不如听神之道而遵守的人有福。」","notes":[]},{"n":29,"t":"当众人聚集的时候，耶稣开讲说：「这世代是一个邪恶的世代。他们求看神迹，除了约拿的神迹以外，再没有神迹给他们看。","notes":[],"heads":["求神迹的受责备"]},{"n":30,"t":"约拿怎样为尼尼微人成了神迹，人子也要照样为这世代的人成了神迹。","notes":[]},{"n":31,"t":"当审判的时候，南方的女王要起来定这世代的罪；因为她从地极而来，要听所罗门的智慧话。看哪，在这里有一人比所罗门更大。","notes":[]},{"n":32,"t":"当审判的时候，尼尼微人要起来定这世代的罪，因为尼尼微人听了约拿所传的就悔改了。看哪，在这里有一人比约拿更大。」","notes":[]},{"n":33,"t":"「没有人点灯放在地窨子里，或是斗底下，总是放在灯台上，使进来的人得见亮光。","notes":[],"heads":["论心里的光"]},{"n":34,"t":"你眼睛就是身上的灯。你的眼睛若了亮，全身就光明；眼睛若昏花，全身就黑暗。","notes":[]},{"n":35,"t":"所以，你要省察，恐怕你里头的光或者黑暗了。","notes":[]},{"n":36,"t":"若是你全身光明，毫无黑暗，就必全然光明，如同灯的明光照亮你。」","notes":[]},{"n":37,"t":"说话的时候，有一个法利赛人请耶稣同他吃饭，耶稣就进去坐席。","notes":[],"heads":["谴责法利赛人和文士"]},{"n":38,"t":"这法利赛人看见耶稣饭前不洗手便诧异。","notes":[]},{"n":39,"t":"主对他说：「如今你们法利赛人洗净杯盘的外面，你们里面却满了勒索和邪恶。","notes":[]},{"n":40,"t":"无知的人哪，造外面的，不也造里面吗？","notes":[]},{"n":41,"t":"只要把里面的施舍给人，凡物于你们就都洁净了。","notes":[]},{"n":42,"t":"「你们法利赛人有祸了！因为你们将薄荷、芸香并各样菜蔬献上十分之一，那公义和爱神的事反倒不行了。这原是你们当行的；那也是不可不行的。","notes":[]},{"n":43,"t":"你们法利赛人有祸了！因为你们喜爱会堂里的首位，又喜爱人在街市上问你们的安。","notes":[]},{"n":44,"t":"你们有祸了！因为你们如同不显露的坟墓，走在上面的人并不知道。」","notes":[]},{"n":45,"t":"律法师中有一个回答耶稣说：「夫子！你这样说也把我们糟蹋了。」","notes":[]},{"n":46,"t":"耶稣说：「你们律法师也有祸了！因为你们把难担的担子放在人身上，自己一个指头却不肯动。","notes":[]},{"n":47,"t":"你们有祸了！因为你们修造先知的坟墓，那先知正是你们的祖宗所杀的。","notes":[]},{"n":48,"t":"可见你们祖宗所做的事，你们又证明又喜欢；因为他们杀了先知，你们修造先知的坟墓。","notes":[]},{"n":49,"t":"所以神用智慧曾说：『我要差遣先知和使徒到他们那里去，有的他们要杀害，有的他们要逼迫』，","notes":["用智慧：或译的智者"]},{"n":50,"t":"使创世以来所流众先知血的罪都要问在这世代的人身上，","notes":[]},{"n":51,"t":"就是从亚伯的血起，直到被杀在坛和殿中间撒迦利亚的血为止。我实在告诉你们，这都要问在这世代的人身上。","notes":[]},{"n":52,"t":"你们律法师有祸了！因为你们把知识的钥匙夺了去，自己不进去，正要进去的人你们也阻挡他们。」","notes":[]},{"n":53,"t":"耶稣从那里出来，文士和法利赛人就极力地催逼他，引动他多说话，","notes":[]},{"n":54,"t":"私下窥听，要拿他的话柄。","notes":[]}]},"12":{"heading":"防备假冒为善","verses":[{"n":1,"t":"这时，有几万人聚集，甚至彼此践踏。耶稣开讲，先对门徒说：「你们要防备法利赛人的酵，就是假冒为善。","notes":[]},{"n":2,"t":"掩盖的事没有不露出来的；隐藏的事没有不被人知道的。","notes":[]},{"n":3,"t":"因此，你们在暗中所说的，将要在明处被人听见；在内室附耳所说的，将要在房上被人宣扬。」","notes":[]},{"n":4,"t":"「我的朋友，我对你们说，那杀身体以后不能再做什么的，不要怕他们。","notes":[],"heads":["该怕的是谁"]},{"n":5,"t":"我要指示你们当怕的是谁：当怕那杀了以后又有权柄丢在地狱里的。我实在告诉你们，正要怕他。","notes":[]},{"n":6,"t":"五个麻雀不是卖二分银子吗？但在神面前，一个也不忘记；","notes":[]},{"n":7,"t":"就是你们的头发，也都被数过了。不要惧怕，你们比许多麻雀还贵重！」","notes":[]},{"n":8,"t":"「我又告诉你们，凡在人面前认我的，人子在神的使者面前也必认他；","notes":[],"heads":["在人的面前承认基督"]},{"n":9,"t":"在人面前不认我的，人子在神的使者面前也必不认他。","notes":[]},{"n":10,"t":"凡说话干犯人子的，还可得赦免；惟独亵渎圣灵的，总不得赦免。","notes":[]},{"n":11,"t":"人带你们到会堂，并官府和有权柄的人面前，不要思虑怎么分诉，说什么话；","notes":[]},{"n":12,"t":"因为正在那时候，圣灵要指教你们当说的话。」","notes":[]},{"n":13,"t":"众人中有一个人对耶稣说：「夫子！请你吩咐我的兄长和我分开家业。」","notes":[],"heads":["无知财主的比喻"]},{"n":14,"t":"耶稣说：「你这个人！谁立我作你们断事的官，给你们分家业呢？」","notes":[]},{"n":15,"t":"于是对众人说：「你们要谨慎自守，免去一切的贪心，因为人的生命不在乎家道丰富。」","notes":[]},{"n":16,"t":"就用比喻对他们说：「有一个财主田产丰盛；","notes":[]},{"n":17,"t":"自己心里思想说：『我的出产没有地方收藏，怎么办呢？』","notes":[]},{"n":18,"t":"又说：『我要这么办：要把我的仓房拆了，另盖更大的，在那里好收藏我一切的粮食和财物，","notes":[]},{"n":19,"t":"然后要对我的灵魂说：灵魂哪，你有许多财物积存，可作多年的费用，只管安安逸逸地吃喝快乐吧！』","notes":[]},{"n":20,"t":"神却对他说：『无知的人哪，今夜必要你的灵魂；你所预备的要归谁呢？』","notes":[]},{"n":21,"t":"凡为自己积财，在神面前却不富足的，也是这样。」","notes":[]},{"n":22,"t":"耶稣又对门徒说：「所以我告诉你们，不要为生命忧虑吃什么，为身体忧虑穿什么；","notes":[],"heads":["不要忧虑"]},{"n":23,"t":"因为生命胜于饮食，身体胜于衣裳。","notes":[]},{"n":24,"t":"你想乌鸦，也不种也不收，又没有仓又没有库，神尚且养活它。你们比飞鸟是何等地贵重呢！","notes":[]},{"n":25,"t":"你们哪一个能用思虑使寿数多加一刻呢？","notes":["或译：使身量多加一肘呢"]},{"n":26,"t":"这最小的事，你们尚且不能做，为什么还忧虑其余的事呢？","notes":[]},{"n":27,"t":"你想百合花怎么长起来；它也不劳苦，也不纺线。然而我告诉你们，就是所罗门极荣华的时候，他所穿戴的，还不如这花一朵呢！","notes":[]},{"n":28,"t":"你们这小信的人哪，野地里的草今天还在，明天就丢在炉里，神还给它这样的妆饰，何况你们呢！","notes":[]},{"n":29,"t":"你们不要求吃什么，喝什么，也不要挂心；","notes":[]},{"n":30,"t":"这都是外邦人所求的。你们必须用这些东西，你们的父是知道的。","notes":[]},{"n":31,"t":"你们只要求他的国，这些东西就必加给你们了。","notes":[]},{"n":32,"t":"你们这小群，不要惧怕，因为你们的父乐意把国赐给你们。","notes":[]},{"n":33,"t":"你们要变卖所有的周济人，为自己预备永不坏的钱囊，用不尽的财宝在天上，就是贼不能近、虫不能蛀的地方。","notes":[]},{"n":34,"t":"因为，你们的财宝在哪里，你们的心也在那里。」","notes":[]},{"n":35,"t":"「你们腰里要束上带，灯也要点着，","notes":[],"heads":["警醒的仆人"]},{"n":36,"t":"自己好像仆人等候主人从婚姻的筵席上回来。他来到，叩门，就立刻给他开门。","notes":[]},{"n":37,"t":"主人来了，看见仆人警醒，那仆人就有福了。我实在告诉你们，主人必叫他们坐席，自己束上带，进前伺候他们。","notes":[]},{"n":38,"t":"或是二更天来，或是三更天来，看见仆人这样，那仆人就有福了。","notes":[]},{"n":39,"t":"家主若知道贼什么时候来，就必警醒，不容贼挖透房屋，这是你们所知道的。","notes":[]},{"n":40,"t":"你们也要预备；因为你们想不到的时候，人子就来了。」","notes":[]},{"n":41,"t":"彼得说：「主啊，这比喻是为我们说的呢？还是为众人呢？」","notes":[]},{"n":42,"t":"主说：「谁是那忠心有见识的管家，主人派他管理家里的人，按时分粮给他们呢？","notes":[]},{"n":43,"t":"主人来到，看见仆人这样行，那仆人就有福了。","notes":[]},{"n":44,"t":"我实在告诉你们，主人要派他管理一切所有的。","notes":[]},{"n":45,"t":"那仆人若心里说：『我的主人必来得迟』，就动手打仆人和使女，并且吃喝醉酒；","notes":[]},{"n":46,"t":"在他想不到的日子，不知道的时辰，那仆人的主人要来，重重地处治他，定他和不忠心的人同罪。","notes":["或译：把他腰斩了"]},{"n":47,"t":"仆人知道主人的意思，却不预备，又不顺他的意思行，那仆人必多受责打；","notes":[]},{"n":48,"t":"惟有那不知道的，做了当受责打的事，必少受责打；因为多给谁，就向谁多取；多托谁，就向谁多要。」","notes":[]},{"n":49,"t":"「我来要把火丢在地上，倘若已经着起来，不也是我所愿意的吗？","notes":[],"heads":["分裂的原因"]},{"n":50,"t":"我有当受的洗还没有成就，我是何等地迫切呢？","notes":[]},{"n":51,"t":"你们以为我来，是叫地上太平吗？我告诉你们，不是，乃是叫人纷争。","notes":[]},{"n":52,"t":"从今以后，一家五个人将要纷争：三个人和两个人相争，两个人和三个人相争；","notes":[]},{"n":53,"t":"父亲和儿子相争，儿子和父亲相争；母亲和女儿相争，女儿和母亲相争；婆婆和媳妇相争，媳妇和婆婆相争。」","notes":[]},{"n":54,"t":"耶稣又对众人说：「你们看见西边起了云彩，就说：『要下一阵雨』；果然就有。","notes":[],"heads":["分辨时候"]},{"n":55,"t":"起了南风，就说：『将要燥热』；也就有了。","notes":[]},{"n":56,"t":"假冒为善的人哪，你们知道分辨天地的气色，怎么不知道分辨这时候呢？」","notes":[]},{"n":57,"t":"「你们又为何不自己审量什么是合理的呢？","notes":[],"heads":["同对头和解"]},{"n":58,"t":"你同告你的对头去见官，还在路上，务要尽力地和他了结；恐怕他拉你到官面前，官交付差役，差役把你下在监里。","notes":[]},{"n":59,"t":"我告诉你，若有半文钱没有还清，你断不能从那里出来。」","notes":[]}]},"13":{"heading":"悔改或灭亡","verses":[{"n":1,"t":"正当那时，有人将彼拉多使加利利人的血搀杂在他们祭物中的事告诉耶稣。","notes":[]},{"n":2,"t":"耶稣说：「你们以为这些加利利人比众加利利人更有罪，所以受这害吗？","notes":[]},{"n":3,"t":"我告诉你们，不是的！你们若不悔改，都要如此灭亡！","notes":[]},{"n":4,"t":"从前西罗亚楼倒塌了，压死十八个人；你们以为那些人比一切住在耶路撒冷的人更有罪吗？","notes":[]},{"n":5,"t":"我告诉你们，不是的！你们若不悔改，都要如此灭亡！」","notes":[]},{"n":6,"t":"于是用比喻说：「一个人有一棵无花果树栽在葡萄园里。他来到树前找果子，却找不着。","notes":[],"heads":["不结实的无花果树"]},{"n":7,"t":"就对管园的说：『看哪，我这三年来到这无花果树前找果子，竟找不着。把它砍了吧，何必白占地土呢！』","notes":[]},{"n":8,"t":"管园的说：『主啊，今年且留着，等我周围掘开土，加上粪；","notes":[]},{"n":9,"t":"以后若结果子便罢，不然再把它砍了。』」","notes":[]},{"n":10,"t":"安息日，耶稣在会堂里教训人。","notes":[],"heads":["安息日治好驼背的女人"]},{"n":11,"t":"有一个女人被鬼附着，病了十八年，腰弯得一点直不起来。","notes":[]},{"n":12,"t":"耶稣看见，便叫过她来，对她说：「女人，你脱离这病了！」","notes":[]},{"n":13,"t":"于是用两只手按着她；她立刻直起腰来，就归荣耀与神。","notes":[]},{"n":14,"t":"管会堂的因为耶稣在安息日治病，就气忿忿地对众人说：「有六日应当做工；那六日之内可以来求医，在安息日却不可。」","notes":[]},{"n":15,"t":"主说：「假冒为善的人哪，难道你们各人在安息日不解开槽上的牛、驴，牵去饮吗？","notes":[]},{"n":16,"t":"况且这女人本是亚伯拉罕的后裔，被撒但捆绑了这十八年，不当在安息日解开她的绑吗？」","notes":[]},{"n":17,"t":"耶稣说这话，他的敌人都惭愧了；众人因他所行一切荣耀的事，就都欢喜了。","notes":[]},{"n":18,"t":"耶稣说：「神的国好像什么？我拿什么来比较呢？","notes":[],"heads":["芥菜种和面酵的比喻"]},{"n":19,"t":"好像一粒芥菜种，有人拿去种在园子里，长大成树，天上的飞鸟宿在它的枝上。」","notes":[]},{"n":20,"t":"又说：「我拿什么来比神的国呢？","notes":[]},{"n":21,"t":"好比面酵，有妇人拿来藏在三斗面里，直等全团都发起来。」","notes":[]},{"n":22,"t":"耶稣往耶路撒冷去，在所经过的各城各乡教训人。","notes":[],"heads":["当进窄门"]},{"n":23,"t":"有一个人问他说：「主啊，得救的人少吗？」","notes":[]},{"n":24,"t":"耶稣对众人说：「你们要努力进窄门。我告诉你们，将来有许多人想要进去，却是不能。","notes":[]},{"n":25,"t":"及至家主起来关了门，你们站在外面叩门，说：『主啊，给我们开门！』他就回答说：『我不认识你们，不晓得你们是哪里来的！』","notes":[]},{"n":26,"t":"那时，你们要说：『我们在你面前吃过喝过，你也在我们的街上教训过人。』","notes":[]},{"n":27,"t":"他要说：『我告诉你们，我不晓得你们是哪里来的。你们这一切作恶的人，离开我去吧！』","notes":[]},{"n":28,"t":"你们要看见亚伯拉罕、以撒、雅各，和众先知都在神的国里，你们却被赶到外面，在那里必要哀哭切齿了。","notes":[]},{"n":29,"t":"从东、从西、从南、从北将有人来，在神的国里坐席。","notes":[]},{"n":30,"t":"只是有在后的，将要在前；有在前的，将要在后。」","notes":[]},{"n":31,"t":"正当那时，有几个法利赛人来对耶稣说：「离开这里去吧，因为希律想要杀你。」","notes":[],"heads":["为耶路撒冷哀哭"]},{"n":32,"t":"耶稣说：「你们去告诉那个狐狸说：『今天、明天我赶鬼治病，第三天我的事就成全了。』","notes":[]},{"n":33,"t":"虽然这样，今天、明天、后天，我必须前行，因为先知在耶路撒冷之外丧命是不能的。","notes":[]},{"n":34,"t":"耶路撒冷啊！耶路撒冷啊！你常杀害先知，又用石头打死那奉差遣到你这里来的人。我多次愿意聚集你的儿女，好像母鸡把小鸡聚集在翅膀底下；只是你们不愿意。","notes":[]},{"n":35,"t":"看哪，你们的家成为荒场留给你们。我告诉你们，从今以后你们不得再见我，直等到你们说：『奉主名来的是应当称颂的。』」","notes":[]}]},"14":{"heading":"在安息日治好臌胀的人","verses":[{"n":1,"t":"安息日，耶稣到一个法利赛人的首领家里去吃饭，他们就窥探他。","notes":[]},{"n":2,"t":"在他面前有一个患水臌的人。","notes":[]},{"n":3,"t":"耶稣对律法师和法利赛人说：「安息日治病可以不可以？」","notes":[]},{"n":4,"t":"他们却不言语。耶稣就治好那人，叫他走了；","notes":[]},{"n":5,"t":"便对他们说：「你们中间谁有驴或有牛，在安息日掉在井里，不立时拉它上来呢？」","notes":[]},{"n":6,"t":"他们不能对答这话。","notes":[]},{"n":7,"t":"耶稣见所请的客拣择首位，就用比喻对他们说：","notes":[],"heads":["给客人和主人的教训"]},{"n":8,"t":"「你被人请去赴婚姻的筵席，不要坐在首位上，恐怕有比你尊贵的客被他请来；","notes":[]},{"n":9,"t":"那请你们的人前来对你说：『让座给这一位吧！』你就羞羞惭惭地退到末位上去了。","notes":[]},{"n":10,"t":"你被请的时候，就去坐在末位上，好叫那请你的人来对你说：『朋友，请上座。』那时，你在同席的人面前就有光彩了。","notes":[]},{"n":11,"t":"因为，凡自高的，必降为卑；自卑的，必升为高。」","notes":[]},{"n":12,"t":"耶稣又对请他的人说：「你摆设午饭或晚饭，不要请你的朋友、弟兄、亲属，和富足的邻舍，恐怕他们也请你，你就得了报答。","notes":[]},{"n":13,"t":"你摆设筵席，倒要请那贫穷的、残废的、瘸腿的、瞎眼的，你就有福了！","notes":[]},{"n":14,"t":"因为他们没有什么可报答你。到义人复活的时候，你要得着报答。」","notes":[]},{"n":15,"t":"同席的有一人听见这话，就对耶稣说：「在神国里吃饭的有福了！」","notes":[],"heads":["大筵席的比喻"]},{"n":16,"t":"耶稣对他说：「有一人摆设大筵席，请了许多客。","notes":[]},{"n":17,"t":"到了坐席的时候，打发仆人去对所请的人说：『请来吧！样样都齐备了。』","notes":[]},{"n":18,"t":"众人一口同音地推辞。头一个说：『我买了一块地，必须去看看。请你准我辞了。』","notes":[]},{"n":19,"t":"又有一个说：『我买了五对牛，要去试一试。请你准我辞了。』","notes":[]},{"n":20,"t":"又有一个说：『我才娶了妻，所以不能去。』","notes":[]},{"n":21,"t":"那仆人回来，把这事都告诉了主人。家主就动怒，对仆人说：『快出去，到城里大街小巷，领那贫穷的、残废的、瞎眼的、瘸腿的来。』","notes":[]},{"n":22,"t":"仆人说：『主啊，你所吩咐的已经办了，还有空座。』","notes":[]},{"n":23,"t":"主人对仆人说：『你出去到路上和篱笆那里，勉强人进来，坐满我的屋子。","notes":[]},{"n":24,"t":"我告诉你们，先前所请的人没有一个得尝我的筵席。』」","notes":[]},{"n":25,"t":"有极多的人和耶稣同行。他转过来对他们说：","notes":[],"heads":["作门徒的代价"]},{"n":26,"t":"「人到我这里来，若不爱我胜过爱自己的父 母、妻子、儿女、弟兄、姊妹，和自己的性命，就不能作我的门徒。","notes":["爱我胜过爱：原文是恨"]},{"n":27,"t":"凡不背着自己十字架跟从我的，也不能作我的门徒。","notes":[]},{"n":28,"t":"你们哪一个要盖一座楼，不先坐下算计花费，能盖成不能呢？","notes":[]},{"n":29,"t":"恐怕安了地基，不能成功，看见的人都笑话他，说：","notes":[]},{"n":30,"t":"『这个人开了工，却不能完工。』","notes":[]},{"n":31,"t":"或是一个王出去和别的王打仗，岂不先坐下酌量，能用一万兵去敌那领二万兵来攻打他的吗？","notes":[]},{"n":32,"t":"若是不能，就趁敌人还远的时候，派使者去求和息的条款。","notes":[]},{"n":33,"t":"这样，你们无论什么人，若不撇下一切所有的，就不能作我的门徒。」","notes":[]},{"n":34,"t":"「盐本是好的；盐若失了味，可用什么叫它再咸呢？","notes":[],"heads":["失味的盐"]},{"n":35,"t":"或用在田里，或堆在粪里，都不合式，只好丢在外面。有耳可听的，就应当听！」","notes":[]}]},"15":{"heading":"迷羊的比喻","verses":[{"n":1,"t":"众税吏和罪人都挨近耶稣，要听他讲道。","notes":[]},{"n":2,"t":"法利赛人和文士私下议论说：「这个人接待罪人，又同他们吃饭。」","notes":[]},{"n":3,"t":"耶稣就用比喻说：","notes":[]},{"n":4,"t":"「你们中间谁有一百只羊失去一只，不把这九十九只撇在旷野、去找那失去的羊，直到找着呢？","notes":[]},{"n":5,"t":"找着了，就欢欢喜喜地扛在肩上，回到家里，","notes":[]},{"n":6,"t":"就请朋友邻舍来，对他们说：『我失去的羊已经找着了，你们和我一同欢喜吧！』","notes":[]},{"n":7,"t":"我告诉你们，一个罪人悔改，在天上也要这样为他欢喜，较比为九十九个不用悔改的义人欢喜更大。」","notes":[]},{"n":8,"t":"「或是一个妇人有十块钱，若失落一块，岂不点上灯，打扫屋子，细细地找，直到找着吗？","notes":[],"heads":["失钱的比喻"]},{"n":9,"t":"找着了，就请朋友邻舍来，对他们说：『我失落的那块钱已经找着了，你们和我一同欢喜吧！』","notes":[]},{"n":10,"t":"我告诉你们，一个罪人悔改，在神的使者面前也是这样为他欢喜。」","notes":[]},{"n":11,"t":"耶稣又说：「一个人有两个儿子。","notes":[],"heads":["浪子的比喻"]},{"n":12,"t":"小儿子对父亲说：『父亲，请你把我应得的家业分给我。』他父亲就把产业分给他们。","notes":[]},{"n":13,"t":"过了不多几日，小儿子就把他一切所有的都收拾起来，往远方去了。在那里任意放荡，浪费资财。","notes":[]},{"n":14,"t":"既耗尽了一切所有的，又遇着那地方大遭饥荒，就穷苦起来。","notes":[]},{"n":15,"t":"于是去投靠那地方的一个人；那人打发他到田里去放猪。","notes":[]},{"n":16,"t":"他恨不得拿猪所吃的豆荚充饥，也没有人给他。","notes":[]},{"n":17,"t":"他醒悟过来，就说：『我父亲有多少的雇工，口粮有余，我倒在这里饿死吗？","notes":[]},{"n":18,"t":"我要起来，到我父亲那里去，向他说：父亲！我得罪了天，又得罪了你；","notes":[]},{"n":19,"t":"从今以后，我不配称为你的儿子，把我当作一个雇工吧！』","notes":[]},{"n":20,"t":"于是起来，往他父亲那里去。相离还远，他父亲看见，就动了慈心，跑去抱着他的颈项，连连与他亲嘴。","notes":[]},{"n":21,"t":"儿子说：『父亲！我得罪了天，又得罪了你；从今以后，我不配称为你的儿子。』","notes":[]},{"n":22,"t":"父亲却吩咐仆人说：『把那上好的袍子快拿出来给他穿；把戒指戴在他指头上；把鞋穿在他脚上；","notes":[]},{"n":23,"t":"把那肥牛犊牵来宰了，我们可以吃喝快乐；","notes":[]},{"n":24,"t":"因为我这个儿子是死而复活，失而又得的。』他们就快乐起来。","notes":[]},{"n":25,"t":"那时，大儿子正在田里。他回来，离家不远，听见作乐跳舞的声音，","notes":[]},{"n":26,"t":"便叫过一个仆人来，问是什么事。","notes":[]},{"n":27,"t":"仆人说：『你兄弟来了；你父亲因为得他无灾无病地回来，把肥牛犊宰了。』","notes":[]},{"n":28,"t":"大儿子却生气，不肯进去；他父亲就出来劝他。","notes":[]},{"n":29,"t":"他对父亲说：『我服事你这多年，从来没有违背过你的命，你并没有给我一只山羊羔，叫我和朋友一同快乐。","notes":[]},{"n":30,"t":"但你这个儿子和娼妓吞尽了你的产业，他一来了，你倒为他宰了肥牛犊。』","notes":[]},{"n":31,"t":"父亲对他说：『儿啊！你常和我同在，我一切所有的都是你的；","notes":[]},{"n":32,"t":"只是你这个兄弟是死而复活、失而又得的，所以我们理当欢喜快乐。』」","notes":[]}]},"16":{"heading":"不义的管家","verses":[{"n":1,"t":"耶稣又对门徒说：「有一个财主的管家，别人向他主人告他浪费主人的财物。","notes":[]},{"n":2,"t":"主人叫他来，对他说：『我听见你这事怎么样呢？把你所经管的交代明白，因你不能再作我的管家。』","notes":[]},{"n":3,"t":"那管家心里说：『主人辞我，不用我再作管家，我将来做什么？锄地呢？无力；讨饭呢？怕羞。","notes":[]},{"n":4,"t":"我知道怎么行，好叫人在我不作管家之后，接我到他们家里去。』","notes":[]},{"n":5,"t":"于是把欠他主人债的，一个一个地叫了来，问头一个说：『你欠我主人多少？』","notes":[]},{"n":6,"t":"他说：『一百篓油。』管家说：『拿你的帐，快坐下，写五十。』","notes":["每篓约五十斤"]},{"n":7,"t":"又问一个说：『你欠多少？』他说：『一百石麦子。』管家说：『拿你的帐，写八十。』","notes":[]},{"n":8,"t":"主人就夸奖这不义的管家做事聪明；因为今世之子，在世事之上，较比光明之子更加聪明。","notes":[]},{"n":9,"t":"我又告诉你们，要借着那不义的钱财结交朋友，到了钱财无用的时候，他们可以接你们到永存的帐幕里去。","notes":[]},{"n":10,"t":"人在最小的事上忠心，在大事上也忠心；在最小的事上不义，在大事上也不义。","notes":[]},{"n":11,"t":"倘若你们在不义的钱财上不忠心，谁还把那真实的钱财托付你们呢？","notes":[]},{"n":12,"t":"倘若你们在别人的东西上不忠心，谁还把你们自己的东西给你们呢？","notes":[]},{"n":13,"t":"一个仆人不能事奉两个主；不是恶这个爱那个，就是重这个轻那个。你们不能又事奉神，又事奉玛门。」","notes":[]},{"n":14,"t":"法利赛人是贪爱钱财的；他们听见这一切话，就嗤笑耶稣。","notes":[],"heads":["律法和神的国"]},{"n":15,"t":"耶稣对他们说：「你们是在人面前自称为义的，你们的心，神却知道；因为人所尊贵的，是神看为可憎恶的。","notes":[]},{"n":16,"t":"律法和先知到约翰为止，从此神国的福音传开了，人人努力要进去。","notes":[]},{"n":17,"t":"天地废去较比律法的一点一画落空还容易。","notes":[]},{"n":18,"t":"凡休妻另娶的就是犯奸淫；娶被休之妻的也是犯奸淫。」","notes":[]},{"n":19,"t":"「有一个财主穿着紫色袍和细麻布衣服，天天奢华宴乐。","notes":[],"heads":["财主和拉撒路"]},{"n":20,"t":"又有一个讨饭的，名叫拉撒路，浑身生疮，被人放在财主门口，","notes":[]},{"n":21,"t":"要得财主桌子上掉下来的零碎充饥，并且狗来舔他的疮。","notes":[]},{"n":22,"t":"后来那讨饭的死了，被天使带去放在亚伯拉罕的怀里。财主也死了，并且埋葬了。","notes":[]},{"n":23,"t":"他在阴间受痛苦，举目远远地望见亚伯拉罕，又望见拉撒路在他怀里，","notes":[]},{"n":24,"t":"就喊着说：『我祖亚伯拉罕哪，可怜我吧！打发拉撒路来，用指头尖蘸点水，凉凉我的舌头；因为我在这火焰里，极其痛苦。』","notes":[]},{"n":25,"t":"亚伯拉罕说：『儿啊，你该回想你生前享过福，拉撒路也受过苦；如今他在这里得安慰，你倒受痛苦。","notes":[]},{"n":26,"t":"不但这样，并且在你我之间，有深渊限定，以致人要从这边过到你们那边是不能的；要从那边过到我们这边也是不能的。』","notes":[]},{"n":27,"t":"财主说：『我祖啊！既是这样，求你打发拉撒路到我父家去；","notes":[]},{"n":28,"t":"因为我还有五个弟兄，他可以对他们作见证，免得他们也来到这痛苦的地方。』","notes":[]},{"n":29,"t":"亚伯拉罕说：『他们有摩西和先知的话可以听从。』","notes":[]},{"n":30,"t":"他说：『我祖亚伯拉罕哪，不是的，若有一个从死里复活的，到他们那里去的，他们必要悔改。』","notes":[]},{"n":31,"t":"亚伯拉罕说：『若不听从摩西和先知的话，就是有一个从死里复活的，他们也是不听劝。』」","notes":[]}]},"17":{"heading":"罪，信心，仆人的本分","verses":[{"n":1,"t":"耶稣又对门徒说：「绊倒人的事是免不了的；但那绊倒人的有祸了。","notes":[]},{"n":2,"t":"就是把磨石拴在这人的颈项上，丢在海里，还强如他把这小子里的一个绊倒了。","notes":[]},{"n":3,"t":"你们要谨慎！若是你的弟兄得罪你，就劝戒他；他若懊悔，就饶恕他。","notes":[]},{"n":4,"t":"倘若他一天七次得罪你，又七次回转，说：『我懊悔了』，你总要饶恕他。」","notes":[]},{"n":5,"t":"使徒对主说：「求主加增我们的信心。」","notes":[]},{"n":6,"t":"主说：「你们若有信心像一粒芥菜种，就是对这棵桑树说：『你要拔起根来，栽在海里』，它也必听从你们。","notes":[]},{"n":7,"t":"你们谁有仆人耕地或是放羊，从田里回来，就对他说：『你快来坐下吃饭』呢？","notes":[]},{"n":8,"t":"岂不对他说：『你给我预备晚饭，束上带子伺候我，等我吃喝完了，你才可以吃喝』吗？","notes":[]},{"n":9,"t":"仆人照所吩咐的去做，主人还谢谢他吗？","notes":[]},{"n":10,"t":"这样，你们做完了一切所吩咐的，只当说：『我们是无用的仆人，所做的本是我们应分做的。』」","notes":[]},{"n":11,"t":"耶稣往耶路撒冷去，经过撒马利亚和加利利。","notes":[],"heads":["治好十个长大麻风的"]},{"n":12,"t":"进入一个村子，有十个长大麻风的，迎面而来，远远地站着，","notes":[]},{"n":13,"t":"高声说：「耶稣，夫子，可怜我们吧！」","notes":[]},{"n":14,"t":"耶稣看见，就对他们说：「你们去把身体给祭司察看。」他们去的时候就洁净了。","notes":[]},{"n":15,"t":"内中有一个见自己已经好了，就回来大声归荣耀与神，","notes":[]},{"n":16,"t":"又俯伏在耶稣脚前感谢他；这人是撒马利亚人。","notes":[]},{"n":17,"t":"耶稣说：「洁净了的不是十个人吗？那九个在哪里呢？","notes":[]},{"n":18,"t":"除了这外族人，再没有别人回来归荣耀与神吗？」","notes":[]},{"n":19,"t":"就对那人说：「起来，走吧！你的信救了你了。」","notes":[]},{"n":20,"t":"法利赛人问：「神的国几时来到？」耶稣回答说：「神的国来到不是眼所能见的。","notes":[],"heads":["神国的来到"]},{"n":21,"t":"人也不得说：『看哪，在这里！看哪，在那里！』因为神的国就在你们心里。」","notes":["心里：或译中间"]},{"n":22,"t":"他又对门徒说：「日子将到，你们巴不得看见人子的一个日子，却不得看见。","notes":[]},{"n":23,"t":"人将要对你们说：『看哪，在那里！看哪，在这里！』你们不要出去，也不要跟随他们！","notes":[]},{"n":24,"t":"因为人子在他降临的日子，好像闪电从天这边一闪直照到天那边。","notes":[]},{"n":25,"t":"只是他必须先受许多苦，又被这世代弃绝。","notes":[]},{"n":26,"t":"挪亚的日子怎样，人子的日子也要怎样。","notes":[]},{"n":27,"t":"那时候的人又吃又喝，又娶又嫁，到挪亚进方舟的那日，洪水就来，把他们全都灭了。","notes":[]},{"n":28,"t":"又好像罗得的日子；人又吃又喝，又买又卖，又耕种又盖造。","notes":[]},{"n":29,"t":"到罗得出所多玛的那日，就有火与硫磺从天上降下来，把他们全都灭了。","notes":[]},{"n":30,"t":"人子显现的日子也要这样。","notes":[]},{"n":31,"t":"当那日，人在房上，器具在屋里，不要下来拿；人在田里，也不要回家。","notes":[]},{"n":32,"t":"你们要回想罗得的妻子。","notes":[]},{"n":33,"t":"凡想要保全生命的，必丧掉生命；凡丧掉生命的，必救活生命。","notes":[]},{"n":34,"t":"我对你们说，当那一夜，两个人在一个床上，要取去一个，撇下一个。","notes":[]},{"n":35,"t":"两个女人一同推磨，要取去一个，撇下一个。」","notes":["有古卷加：36两个人在田里，要取去一个，撇下一个。"]},{"n":37,"t":"门徒说：「主啊，在哪里有这事呢？」耶稣说：「尸首在哪里，鹰也必聚在那里。」","notes":[]}]},"18":{"heading":"寡妇和法官的比喻","verses":[{"n":1,"t":"耶稣设一个比喻，是要人常常祷告，不可灰心。","notes":[]},{"n":2,"t":"说：「某城里有一个官，不惧怕神，也不尊重世人。","notes":[]},{"n":3,"t":"那城里有个寡妇，常到他那里，说：『我有一个对头，求你给我伸冤。』","notes":[]},{"n":4,"t":"他多日不准，后来心里说：『我虽不惧怕神，也不尊重世人，","notes":[]},{"n":5,"t":"只因这寡妇烦扰我，我就给她伸冤吧，免得她常来缠磨我！』」","notes":[]},{"n":6,"t":"主说：「你们听这不义之官所说的话。","notes":[]},{"n":7,"t":"神的选民昼夜呼吁他，他纵然为他们忍了多时，岂不终久给他们伸冤吗？","notes":[]},{"n":8,"t":"我告诉你们，要快快地给他们伸冤了。然而，人子来的时候，遇得见世上有信德吗？」","notes":[]},{"n":9,"t":"耶稣向那些仗着自己是义人，藐视别人的，设一个比喻，","notes":[],"heads":["法利赛人和税吏的祷告"]},{"n":10,"t":"说：「有两个人上殿里去祷告：一个是法利赛人，一个是税吏。","notes":[]},{"n":11,"t":"法利赛人站着，自言自语地祷告说：『神啊，我感谢你，我不像别人勒索、不义、奸淫，也不像这个税吏。","notes":[]},{"n":12,"t":"我一个礼拜禁食两次，凡我所得的都捐上十分之一。』","notes":[]},{"n":13,"t":"那税吏远远地站着，连举目望天也不敢，只捶着胸说：『神啊，开恩可怜我这个罪人！』","notes":[]},{"n":14,"t":"我告诉你们，这人回家去比那人倒算为义了；因为，凡自高的，必降为卑；自卑的，必升为高。」","notes":[]},{"n":15,"t":"有人抱着自己的婴孩来见耶稣，要他摸他们；门徒看见就责备那些人。","notes":[],"heads":["耶稣为小孩祝福"]},{"n":16,"t":"耶稣却叫他们来，说：「让小孩子到我这里来，不要禁止他们，因为在神国的正是这样的人。","notes":[]},{"n":17,"t":"我实在告诉你们，凡要承受神国的，若不像小孩子，断不能进去。」","notes":[]},{"n":18,"t":"有一个官问耶稣说：「良善的夫子，我该做什么事才可以承受永生？」","notes":[],"heads":["富足的官寻求永生之道"]},{"n":19,"t":"耶稣对他说：「你为什么称我是良善的？除了神一位之外，再没有良善的。","notes":[]},{"n":20,"t":"诫命你是晓得的：『不可奸淫；不可杀人；不可偷盗；不可作假见证；当孝敬父母。』」","notes":[]},{"n":21,"t":"那人说：「这一切我从小都遵守了。」","notes":[]},{"n":22,"t":"耶稣听见了，就说：「你还缺少一件：要变卖你一切所有的，分给穷人，就必有财宝在天上；你还要来跟从我。」","notes":[]},{"n":23,"t":"他听见这话，就甚忧愁，因为他很富足。","notes":[]},{"n":24,"t":"耶稣看见他，就说：「有钱财的人进神的国是何等的难哪！","notes":[]},{"n":25,"t":"骆驼穿过针的眼比财主进神的国还容易呢！」","notes":[]},{"n":26,"t":"听见的人说：「这样，谁能得救呢？」","notes":[]},{"n":27,"t":"耶稣说：「在人所不能的事，在神却能。」","notes":[]},{"n":28,"t":"彼得说：「看哪，我们已经撇下自己所有的跟从你了。」","notes":[]},{"n":29,"t":"耶稣说：「我实在告诉你们，人为神的国撇下房屋，或是妻子、弟兄、父母、儿女，","notes":[]},{"n":30,"t":"没有在今世不得百倍，在来世不得永生的。」","notes":[]},{"n":31,"t":"耶稣带着十二个门徒，对他们说：「看哪，我们上耶路撒冷去，先知所写的一切事都要成就在人子身上。","notes":[],"heads":["耶稣第三次预言受难和复活"]},{"n":32,"t":"他将要被交给外邦人；他们要戏弄他，凌辱他，吐唾沫在他脸上，","notes":[]},{"n":33,"t":"并要鞭打他，杀害他；第三日他要复活。」","notes":[]},{"n":34,"t":"这些事门徒一样也不懂得，意思乃是隐藏的；他们不晓得所说的是什么。","notes":[]},{"n":35,"t":"耶稣将近耶利哥的时候，有一个瞎子坐在路旁讨饭。","notes":[],"heads":["治好耶利哥的瞎子"]},{"n":36,"t":"听见许多人经过，就问是什么事。","notes":[]},{"n":37,"t":"他们告诉他，是拿撒勒人耶稣经过。","notes":[]},{"n":38,"t":"他就呼叫说：「大卫的子孙耶稣啊，可怜我吧！」","notes":[]},{"n":39,"t":"在前头走的人就责备他，不许他作声；他却越发喊叫说：「大卫的子孙，可怜我吧！」","notes":[]},{"n":40,"t":"耶稣站住，吩咐把他领过来，到了跟前，就问他说：","notes":[]},{"n":41,"t":"「你要我为你做什么？」他说：「主啊，我要能看见。」","notes":[]},{"n":42,"t":"耶稣说：「你可以看见！你的信救了你了。」","notes":[]},{"n":43,"t":"瞎子立刻看见了，就跟随耶稣，一路归荣耀与神。众人看见这事，也赞美神。","notes":[]}]},"19":{"heading":"耶稣和撒该","verses":[{"n":1,"t":"耶稣进了耶利哥，正经过的时候，","notes":[]},{"n":2,"t":"有一个人名叫撒该，作税吏长，是个财主。","notes":[]},{"n":3,"t":"他要看看耶稣是怎样的人；只因人多，他的身量又矮，所以不得看见，","notes":[]},{"n":4,"t":"就跑到前头，爬上桑树，要看耶稣，因为耶稣必从那里经过。","notes":[]},{"n":5,"t":"耶稣到了那里，抬头一看，对他说：「撒该，快下来！今天我必住在你家里。」","notes":[]},{"n":6,"t":"他就急忙下来，欢欢喜喜地接待耶稣。","notes":[]},{"n":7,"t":"众人看见，都私下议论说：「他竟到罪人家里去住宿。」","notes":[]},{"n":8,"t":"撒该站着对主说：「主啊，我把所有的一半给穷人；我若讹诈了谁，就还他四倍。」","notes":[]},{"n":9,"t":"耶稣说：「今天救恩到了这家，因为他也是亚伯拉罕的子孙。","notes":[]},{"n":10,"t":"人子来，为要寻找、拯救失丧的人。」","notes":[]},{"n":11,"t":"众人正在听见这些话的时候，耶稣因为将近耶路撒冷，又因他们以为神的国快要显出来，就另设一个比喻，说：","notes":[],"heads":["十锭银子的比喻"]},{"n":12,"t":"「有一个贵胄往远方去，要得国回来，","notes":[]},{"n":13,"t":"便叫了他的十个仆人来，交给他们十锭银子，说：『你们去做生意，直等我回来。』","notes":["锭：原文作弥拿，一弥拿约银十两"]},{"n":14,"t":"他本国的人却恨他，打发使者随后去，说：『我们不愿意这个人作我们的王。』","notes":[]},{"n":15,"t":"他既得国回来，就吩咐叫那领银子的仆人来，要知道他们做生意赚了多少。","notes":[]},{"n":16,"t":"头一个上来，说：『主啊，你的一锭银子已经赚了十锭。』","notes":[]},{"n":17,"t":"主人说：『好！良善的仆人，你既在最小的事上有忠心，可以有权柄管十座城。』","notes":[]},{"n":18,"t":"第二个来，说：『主啊，你的一锭银子已经赚了五锭。』","notes":[]},{"n":19,"t":"主人说：『你也可以管五座城。』","notes":[]},{"n":20,"t":"又有一个来说：『主啊，看哪，你的一锭银子在这里，我把它包在手巾里存着。","notes":[]},{"n":21,"t":"我原是怕你，因为你是严厉的人；没有放下的，还要去拿，没有种下的，还要去收。』","notes":[]},{"n":22,"t":"主人对他说：『你这恶仆，我要凭你的口定你的罪。你既知道我是严厉的人，没有放下的，还要去拿，没有种下的，还要去收，","notes":[]},{"n":23,"t":"为什么不把我的银子交给银行，等我来的时候，连本带利都可以要回来呢？』","notes":[]},{"n":24,"t":"就对旁边站着的人说：『夺过他这一锭来，给那有十锭的。』","notes":[]},{"n":25,"t":"他们说：『主啊，他已经有十锭了。』","notes":[]},{"n":26,"t":"主人说：『我告诉你们，凡有的，还要加给他；没有的，连他所有的也要夺过来。","notes":[]},{"n":27,"t":"至于我那些仇敌，不要我作他们王的，把他们拉来，在我面前杀了吧！』」","notes":[]},{"n":28,"t":"耶稣说完了这话，就在前面走，上耶路撒冷去。","notes":[],"heads":["光荣地进耶路撒冷"]},{"n":29,"t":"将近伯法其和伯大尼，在一座山名叫橄榄山那里，就打发两个门徒，说：","notes":[]},{"n":30,"t":"「你们往对面村子里去，进去的时候，必看见一匹驴驹拴在那里，是从来没有人骑过的，可以解开牵来。","notes":[]},{"n":31,"t":"若有人问为什么解它，你们就说：『主要用它。』」","notes":[]},{"n":32,"t":"打发的人去了，所遇见的正如耶稣所说的。","notes":[]},{"n":33,"t":"他们解驴驹的时候，主人问他们说：「解驴驹做什么？」","notes":[]},{"n":34,"t":"他们说：「主要用它。」","notes":[]},{"n":35,"t":"他们牵到耶稣那里，把自己的衣服搭在上面，扶着耶稣骑上。","notes":[]},{"n":36,"t":"走的时候，众人把衣服铺在路上。","notes":[]},{"n":37,"t":"将近耶路撒冷，正下橄榄山的时候，众门徒因所见过的一切异能，都欢乐起来，大声赞美神，","notes":[]},{"n":38,"t":"说：奉主名来的王是应当称颂的！在天上有和平；在至高之处有荣光。","notes":[]},{"n":39,"t":"众人中有几个法利赛人对耶稣说：「夫子，责备你的门徒吧！」","notes":[]},{"n":40,"t":"耶稣说：「我告诉你们，若是他们闭口不说，这些石头必要呼叫起来。」","notes":[]},{"n":41,"t":"耶稣快到耶路撒冷，看见城，就为它哀哭，","notes":[]},{"n":42,"t":"说：「巴不得你在这日子知道关系你平安的事；无奈这事现在是隐藏的，叫你的眼看不出来。","notes":[]},{"n":43,"t":"因为日子将到，你的仇敌必筑起土垒，周围环绕你，四面困住你，","notes":[]},{"n":44,"t":"并要扫灭你和你里头的儿女，连一块石头也不留在石头上，因你不知道眷顾你的时候。」","notes":[]},{"n":45,"t":"耶稣进了殿，赶出里头做买卖的人，","notes":[],"heads":["洁净圣殿"]},{"n":46,"t":"对他们说：「经上说：我的殿必作祷告的殿，你们倒使它成为贼窝了。」","notes":[]},{"n":47,"t":"耶稣天天在殿里教训人。祭司长和文士与百姓的尊长都想要杀他，","notes":[]},{"n":48,"t":"但寻不出法子来，因为百姓都侧耳听他。","notes":[]}]},"20":{"heading":"质问耶稣的权柄","verses":[{"n":1,"t":"有一天，耶稣在殿里教训百姓，讲福音的时候，祭司长和文士并长老上前来，","notes":[]},{"n":2,"t":"问他说：「你告诉我们，你仗着什么权柄做这些事？给你这权柄的是谁呢？」","notes":[]},{"n":3,"t":"耶稣回答说：「我也要问你们一句话，你们且告诉我。","notes":[]},{"n":4,"t":"约翰的洗礼是从天上来的？是从人间来的呢？」","notes":[]},{"n":5,"t":"他们彼此商议说：「我们若说『从天上来』，他必说：『你们为什么不信他呢？』","notes":[]},{"n":6,"t":"若说『从人间来』，百姓都要用石头打死我们，因为他们信约翰是先知。」","notes":[]},{"n":7,"t":"于是回答说：「不知道是从哪里来的。」","notes":[]},{"n":8,"t":"耶稣说：「我也不告诉你们，我仗着什么权柄做这些事。」","notes":[]},{"n":9,"t":"耶稣就设比喻对百姓说：「有人栽了一个葡萄园，租给园户，就往外国去住了许久。","notes":[],"heads":["凶恶园户的比喻"]},{"n":10,"t":"到了时候，打发一个仆人到园户那里去，叫他们把园中当纳的果子交给他；园户竟打了他，叫他空手回去。","notes":[]},{"n":11,"t":"又打发一个仆人去，他们也打了他，并且凌辱他，叫他空手回去。","notes":[]},{"n":12,"t":"又打发第三个仆人去，他们也打伤了他，把他推出去了。","notes":[]},{"n":13,"t":"园主说：『我怎么办呢？我要打发我的爱子去，或者他们尊敬他。』","notes":[]},{"n":14,"t":"不料，园户看见他，就彼此商量说：『这是承受产业的，我们杀他吧，使产业归于我们！』","notes":[]},{"n":15,"t":"于是把他推出葡萄园外，杀了。这样，葡萄园的主人要怎样处治他们呢？","notes":[]},{"n":16,"t":"他要来除灭这些园户，将葡萄园转给别人。」听见的人说：「这是万不可的！」","notes":[]},{"n":17,"t":"耶稣看着他们说：「经上记着：匠人所弃的石头已作了房角的头块石头。这是什么意思呢？","notes":[]},{"n":18,"t":"凡掉在那石头上的，必要跌碎；那石头掉在谁的身上，就要把谁砸得稀烂。」","notes":[]},{"n":19,"t":"文士和祭司长看出这比喻是指着他们说的，当时就想要下手拿他，只是惧怕百姓。","notes":[],"heads":["纳税给凯撒的问题"]},{"n":20,"t":"于是窥探耶稣，打发奸细装作好人，要在他的话上得把柄，好将他交在巡抚的政权之下。","notes":[]},{"n":21,"t":"奸细就问耶稣说：「夫子，我们晓得你所讲所传都是正道，也不取人的外貌，乃是诚诚实实传神的道。","notes":[]},{"n":22,"t":"我们纳税给凯撒，可以不可以？」","notes":[]},{"n":23,"t":"耶稣看出他们的诡诈，就对他们说：","notes":[]},{"n":24,"t":"「拿一个银钱来给我看。这像和这号是谁的？」他们说：「是凯撒的。」","notes":[]},{"n":25,"t":"耶稣说：「这样，凯撒的物当归给凯撒，神的物当归给神。」","notes":[]},{"n":26,"t":"他们当着百姓，在这话上得不着把柄，又希奇他的应对，就闭口无言了。","notes":[]},{"n":27,"t":"撒都该人常说没有复活的事。有几个来问耶稣说：","notes":[],"heads":["复活的问题"]},{"n":28,"t":"「夫子！摩西为我们写着说：『人若有妻无子就死了，他兄弟当娶他的妻，为哥哥生子立后。』","notes":[]},{"n":29,"t":"有弟兄七人，第一个娶了妻，没有孩子死了；","notes":[]},{"n":30,"t":"第二个、第三个也娶过她；","notes":[]},{"n":31,"t":"那七个人都娶过她，没有留下孩子就死了。","notes":[]},{"n":32,"t":"后来妇人也死了。","notes":[]},{"n":33,"t":"这样，当复活的时候，她是哪一个的妻子呢？因为他们七个人都娶过她。」","notes":[]},{"n":34,"t":"耶稣说：「这世界的人有娶有嫁；","notes":[]},{"n":35,"t":"惟有算为配得那世界，与从死里复活的人也不娶也不嫁；","notes":[]},{"n":36,"t":"因为他们不能再死，和天使一样；既是复活的人，就为神的儿子。","notes":[]},{"n":37,"t":"至于死人复活，摩西在荆棘篇上，称主是亚伯拉罕的神，以撒的神，雅各的神，就指示明白了。","notes":[]},{"n":38,"t":"神原不是死人的神，乃是活人的神；因为在他那里，人都是活的。」","notes":["那里：或译看来"]},{"n":39,"t":"有几个文士说：「夫子！你说得好。」","notes":[]},{"n":40,"t":"以后他们不敢再问他什么。","notes":[]},{"n":41,"t":"耶稣对他们说：「人怎么说基督是大卫的子孙呢？","notes":[],"heads":["大卫子孙的问题"]},{"n":42,"t":"诗篇上大卫自己说：主对我主说：你坐在我的右边，","notes":[]},{"n":43,"t":"等我使你仇敌作你的脚凳。","notes":[]},{"n":44,"t":"大卫既称他为主，他怎么又是大卫的子孙呢？」","notes":[]},{"n":45,"t":"众百姓听的时候，耶稣对门徒说：","notes":[],"heads":["谴责文士"]},{"n":46,"t":"「你们要防备文士。他们好穿长衣游行，喜爱人在街市上问他们安，又喜爱会堂里的高位，筵席上的首座；","notes":[]},{"n":47,"t":"他们侵吞寡妇的家产，假意作很长的祷告。这些人要受更重的刑罚！」","notes":[]}]},"21":{"heading":"寡妇的奉献","verses":[{"n":1,"t":"耶稣抬头观看，见财主把捐项投在库里，","notes":[]},{"n":2,"t":"又见一个穷寡妇投了两个小钱，","notes":[]},{"n":3,"t":"就说：「我实在告诉你们，这穷寡妇所投的比众人还多；","notes":[]},{"n":4,"t":"因为众人都是自己有余，拿出来投在捐项里，但这寡妇是自己不足，把她一切养生的都投上了。」","notes":[]},{"n":5,"t":"有人谈论圣殿是用美石和供物妆饰的；","notes":[],"heads":["预言圣殿被毁"]},{"n":6,"t":"耶稣就说：「论到你们所看见的这一切，将来日子到了，在这里没有一块石头留在石头上，不被拆毁了。」","notes":[]},{"n":7,"t":"他们问他说：「夫子！什么时候有这事呢？这事将到的时候有什么预兆呢？」","notes":[],"heads":["预兆和逼迫"]},{"n":8,"t":"耶稣说：「你们要谨慎，不要受迷惑；因为将来有好些人冒我的名来，说：『我是基督』，又说：『时候近了』，你们不要跟从他们！","notes":[]},{"n":9,"t":"你们听见打仗和扰乱的事，不要惊惶；因为这些事必须先有，只是末期不能立时就到。」","notes":[]},{"n":10,"t":"当时，耶稣对他们说：「民要攻打民，国要攻打国；","notes":[]},{"n":11,"t":"地要大大震动，多处必有饥荒、瘟疫，又有可怕的异象和大神迹从天上显现。","notes":[]},{"n":12,"t":"但这一切的事以先，人要下手拿住你们，逼迫你们，把你们交给会堂，并且收在监里，又为我的名拉你们到君王诸侯面前。","notes":[]},{"n":13,"t":"但这些事终必为你们的见证。","notes":[]},{"n":14,"t":"所以，你们当立定心意，不要预先思想怎样分诉；","notes":[]},{"n":15,"t":"因为我必赐你们口才、智慧，是你们一切敌人所敌不住、驳不倒的。","notes":[]},{"n":16,"t":"连你们的父母、弟兄、亲族、朋友也要把你们交官；你们也有被他们害死的。","notes":[]},{"n":17,"t":"你们要为我的名被众人恨恶，","notes":[]},{"n":18,"t":"然而，你们连一根头发也必不损坏。","notes":[]},{"n":19,"t":"你们常存忍耐，就必保全灵魂。」","notes":["或译：必得生命"]},{"n":20,"t":"「你们看见耶路撒冷被兵围困，就可知道它成荒场的日子近了。","notes":[],"heads":["预言耶路撒冷被毁"]},{"n":21,"t":"那时，在犹太的应当逃到山上；在城里的应当出来；在乡下的不要进城；","notes":[]},{"n":22,"t":"因为这是报应的日子，使经上所写的都得应验。","notes":[]},{"n":23,"t":"当那些日子，怀孕的和奶孩子的有祸了！因为将有大灾难降在这地方，也有震怒临到这百姓。","notes":[]},{"n":24,"t":"他们要倒在刀下，又被掳到各国去。耶路撒冷要被外邦人践踏，直到外邦人的日期满了。」","notes":[]},{"n":25,"t":"「日、月、星辰要显出异兆，地上的邦国也有困苦；因海中波浪的响声，就慌慌不定。","notes":[],"heads":["人子的降临"]},{"n":26,"t":"天势都要震动，人想起那将要临到世界的事，就都吓得魂不附体。","notes":[]},{"n":27,"t":"那时，他们要看见人子有能力，有大荣耀驾云降临。","notes":[]},{"n":28,"t":"一有这些事，你们就当挺身昂首，因为你们得赎的日子近了。」","notes":[]},{"n":29,"t":"耶稣又设比喻对他们说：「你们看无花果树和各样的树；它发芽的时候，你们一看见，自然晓得夏天近了。","notes":[],"end":30,"heads":["从无花果树学功课"]},{"n":31,"t":"这样，你们看见这些事渐渐地成就，也该晓得神的国近了。","notes":[]},{"n":32,"t":"我实在告诉你们，这世代还没有过去，这些事都要成就。","notes":[]},{"n":33,"t":"天地要废去，我的话却不能废去。」","notes":[]},{"n":34,"t":"「你们要谨慎，恐怕因贪食、醉酒，并今生的思虑累住你们的心，那日子就如同网罗忽然临到你们；","notes":[],"heads":["劝告门徒警醒"]},{"n":35,"t":"因为那日子要这样临到全地上一切居住的人。","notes":[]},{"n":36,"t":"你们要时时警醒，常常祈求，使你们能逃避这一切要来的事，得以站立在人子面前。」","notes":[]},{"n":37,"t":"耶稣每日在殿里教训人，每夜出城在一座山，名叫橄榄山住宿。","notes":[]},{"n":38,"t":"众百姓清早上圣殿，到耶稣那里，要听他讲道。","notes":[]}]},"22":{"heading":"杀害耶稣的阴谋","verses":[{"n":1,"t":"除酵节（又名逾越节）近了。","notes":[]},{"n":2,"t":"祭司长和文士想法子怎么才能杀害耶稣，是因他们惧怕百姓。","notes":[]},{"n":3,"t":"这时，撒但入了那称为加略人犹大的心；他本是十二门徒里的一个。","notes":[]},{"n":4,"t":"他去和祭司长并守殿官商量，怎么可以把耶稣交给他们。","notes":[]},{"n":5,"t":"他们欢喜，就约定给他银子。","notes":[]},{"n":6,"t":"他应允了，就找机会，要趁众人不在跟前的时候把耶稣交给他们。","notes":[]},{"n":7,"t":"除酵节，须宰逾越羊羔的那一天到了。","notes":[],"heads":["预备逾越节的筵席"]},{"n":8,"t":"耶稣打发彼得、约翰，说：「你们去为我们预备逾越节的筵席，好叫我们吃。」","notes":[]},{"n":9,"t":"他们问他说：「要我们在哪里预备？」","notes":[]},{"n":10,"t":"耶稣说：「你们进了城，必有人拿着一瓶水迎面而来，你们就跟着他，到他所进的房子里去，","notes":[]},{"n":11,"t":"对那家的主人说：『夫子说：客房在哪里？我与门徒好在那里吃逾越节的筵席。』","notes":[]},{"n":12,"t":"他必指给你们摆设整齐的一间大楼，你们就在那里预备。」","notes":[]},{"n":13,"t":"他们去了，所遇见的正如耶稣所说的；他们就预备了逾越节的筵席。","notes":[]},{"n":14,"t":"时候到了，耶稣坐席，使徒也和他同坐。","notes":[],"heads":["设立主的晚餐"]},{"n":15,"t":"耶稣对他们说：「我很愿意在受害以先和你们吃这逾越节的筵席。","notes":[]},{"n":16,"t":"我告诉你们，我不再吃这筵席，直到成就在神的国里。」","notes":[]},{"n":17,"t":"耶稣接过杯来，祝谢了，说：「你们拿这个，大家分着喝。","notes":[]},{"n":18,"t":"我告诉你们，从今以后，我不再喝这葡萄汁，直等神的国来到。」","notes":[]},{"n":19,"t":"又拿起饼来，祝谢了，就擘开，递给他们，说：「这是我的身体，为你们舍的，你们也应当如此行，为的是记念我。」","notes":[]},{"n":20,"t":"饭后也照样拿起杯来，说：「这杯是用我血所立的新约，是为你们流出来的。","notes":[]},{"n":21,"t":"看哪，那卖我之人的手与我一同在桌子上。","notes":[]},{"n":22,"t":"人子固然要照所预定的去世，但卖人子的人有祸了！」","notes":[]},{"n":23,"t":"他们就彼此对问，是哪一个要做这事。","notes":[]},{"n":24,"t":"门徒起了争论，他们中间哪一个可算为大。","notes":[],"heads":["争论谁为大"]},{"n":25,"t":"耶稣说：「外邦人有君王为主治理他们，那掌权管他们的称为恩主。","notes":[]},{"n":26,"t":"但你们不可这样；你们里头为大的，倒要像年幼的，为首领的，倒要像服事人的。","notes":[]},{"n":27,"t":"是谁为大？是坐席的呢？是服事人的呢？不是坐席的大吗？然而，我在你们中间如同服事人的。","notes":[]},{"n":28,"t":"我在磨炼之中，常和我同在的就是你们。","notes":[]},{"n":29,"t":"我将国赐给你们，正如我父赐给我一样，","notes":[]},{"n":30,"t":"叫你们在我国里，坐在我的席上吃喝，并且坐在宝座上，审判以色列十二个支派。」","notes":[]},{"n":31,"t":"主又说：「西门！西门！撒但想要得着你们，好筛你们像筛麦子一样；","notes":[],"heads":["预言彼得不认主"]},{"n":32,"t":"但我已经为你祈求，叫你不至于失了信心。你回头以后，要坚固你的弟兄。」","notes":[]},{"n":33,"t":"彼得说：「主啊，我就是同你下监，同你受死，也是甘心！」","notes":[]},{"n":34,"t":"耶稣说：「彼得，我告诉你，今日鸡还没有叫，你要三次说不认得我。」","notes":[]},{"n":35,"t":"耶稣又对他们说：「我差你们出去的时候，没有钱囊，没有口袋，没有鞋，你们缺少什么没有？」他们说：「没有。」","notes":[],"heads":["钱囊、口袋、刀"]},{"n":36,"t":"耶稣说：「但如今有钱囊的可以带着，有口袋的也可以带着，没有刀的要卖衣服买刀。","notes":[]},{"n":37,"t":"我告诉你们，经上写着说：『他被列在罪犯之中。』这话必应验在我身上，因为那关系我的事必然成就。」","notes":[]},{"n":38,"t":"他们说：「主啊，请看！这里有两把刀。」耶稣说：「够了。」","notes":[]},{"n":39,"t":"耶稣出来，照常往橄榄山去，门徒也跟随他。","notes":[],"heads":["在橄榄山上祷告"]},{"n":40,"t":"到了那地方，就对他们说：「你们要祷告，免得入了迷惑。」","notes":[]},{"n":41,"t":"于是离开他们约有扔一块石头那么远，跪下祷告，","notes":[]},{"n":42,"t":"说：「父啊！你若愿意，就把这杯撤去；然而，不要成就我的意思，只要成就你的意思。」","notes":[]},{"n":43,"t":"有一位天使从天上显现，加添他的力量。","notes":[]},{"n":44,"t":"耶稣极其伤痛，祷告更加恳切，汗珠如大血点滴在地上。","notes":[]},{"n":45,"t":"祷告完了，就起来，到门徒那里，见他们因为忧愁都睡着了，","notes":[]},{"n":46,"t":"就对他们说：「你们为什么睡觉呢？起来祷告，免得入了迷惑！」","notes":[]},{"n":47,"t":"说话之间，来了许多人。那十二个门徒里名叫犹大的，走在前头，就近耶稣，要与他亲嘴。","notes":[],"heads":["耶稣被捕"]},{"n":48,"t":"耶稣对他说：「犹大！你用亲嘴的暗号卖人子吗？」","notes":[]},{"n":49,"t":"左右的人见光景不好，就说：「主啊！我们拿刀砍可以不可以？」","notes":[]},{"n":50,"t":"内中有一个人把大祭司的仆人砍了一刀，削掉了他的右耳。","notes":[]},{"n":51,"t":"耶稣说：「到了这个地步，由他们吧！」就摸那人的耳朵，把他治好了。","notes":[]},{"n":52,"t":"耶稣对那些来拿他的祭司长和守殿官并长老说：「你们带着刀棒出来拿我，如同拿强盗吗？","notes":[]},{"n":53,"t":"我天天同你们在殿里，你们不下手拿我。现在却是你们的时候，黑暗掌权了。」","notes":[]},{"n":54,"t":"他们拿住耶稣，把他带到大祭司的宅里。彼得远远地跟着。","notes":[],"heads":["彼得三次不认主"]},{"n":55,"t":"他们在院子里生了火，一同坐着；彼得也坐在他们中间。","notes":[]},{"n":56,"t":"有一个使女看见彼得坐在火光里，就定睛看他，说：「这个人素来也是同那人一伙的。」","notes":[]},{"n":57,"t":"彼得却不承认，说：「女子，我不认得他。」","notes":[]},{"n":58,"t":"过了不多的时候，又有一个人看见他，说：「你也是他们一党的。」彼得说：「你这个人！我不是。」","notes":[]},{"n":59,"t":"约过了一小时，又有一个人极力地说：「他实在是同那人一伙的，因为他也是加利利人。」","notes":[]},{"n":60,"t":"彼得说：「你这个人！我不晓得你说的是什么！」正说话之间，鸡就叫了。","notes":[]},{"n":61,"t":"主转过身来看彼得，彼得便想起主对他所说的话：「今日鸡叫以先，你要三次不认我。」","notes":[]},{"n":62,"t":"他就出去痛哭。","notes":[]},{"n":63,"t":"看守耶稣的人戏弄他，打他，","notes":[],"heads":["戏弄鞭打耶稣"]},{"n":64,"t":"又蒙着他的眼，问他说：「你是先知，告诉我们打你的是谁？」","notes":[]},{"n":65,"t":"他们还用许多别的话辱骂他。","notes":[]},{"n":66,"t":"天一亮，民间的众长老连祭司长带文士都聚会，把耶稣带到他们的公会里，","notes":[],"heads":["耶稣在公会里受审"]},{"n":67,"t":"说：「你若是基督，就告诉我们。」耶稣说：「我若告诉你们，你们也不信；","notes":[]},{"n":68,"t":"我若问你们，你们也不回答。","notes":[]},{"n":69,"t":"从今以后，人子要坐在神权能的右边。」","notes":[]},{"n":70,"t":"他们都说：「这样，你是神的儿子吗？」耶稣说：「你们所说的是。」","notes":[]},{"n":71,"t":"他们说：「何必再用见证呢？他亲口所说的，我们都亲自听见了。」","notes":[]}]},"23":{"heading":"耶稣在彼拉多面前受审","verses":[{"n":1,"t":"众人都起来，把耶稣解到彼拉多面前，","notes":[]},{"n":2,"t":"就告他说：「我们见这人诱惑国民，禁止纳税给凯撒，并说自己是基督，是王。」","notes":[]},{"n":3,"t":"彼拉多问耶稣说：「你是犹太人的王吗？」耶稣回答说：「你说的是。」","notes":[]},{"n":4,"t":"彼拉多对祭司长和众人说：「我查不出这人有什么罪来。」","notes":[]},{"n":5,"t":"但他们越发极力地说：「他煽惑百姓，在犹太遍地传道，从加利利起，直到这里了。」","notes":[]},{"n":6,"t":"彼拉多一听见，就问：「这人是加利利人吗？」","notes":[],"heads":["希律藐视耶稣"]},{"n":7,"t":"既晓得耶稣属希律所管，就把他送到希律那里去。那时希律正在耶路撒冷。","notes":[]},{"n":8,"t":"希律看见耶稣，就很欢喜；因为听见过他的事，久已想要见他，并且指望看他行一件神迹，","notes":[]},{"n":9,"t":"于是问他许多的话，耶稣却一言不答。","notes":[]},{"n":10,"t":"祭司长和文士都站着，极力地告他。","notes":[]},{"n":11,"t":"希律和他的兵丁就藐视耶稣，戏弄他，给他穿上华丽衣服，把他送回彼拉多那里去。","notes":[]},{"n":12,"t":"从前希律和彼拉多彼此有仇，在那一天就成了朋友。","notes":[]},{"n":13,"t":"彼拉多传齐了祭司长和官府并百姓，","notes":[],"heads":["耶稣被判死刑"]},{"n":14,"t":"就对他们说：「你们解这人到我这里，说他是诱惑百姓的。看哪，我也曾将你们告他的事，在你们面前审问他，并没有查出他什么罪来；","notes":[]},{"n":15,"t":"就是希律也是如此，所以把他送回来。可见他没有做什么该死的事。","notes":[]},{"n":16,"t":"故此，我要责打他，把他释放了。」","notes":["有古卷加：17 每逢这节期，巡抚必须释放一个囚犯给他们。"]},{"n":18,"t":"众人却一齐喊着说：「除掉这个人！释放巴拉巴给我们！」","notes":[]},{"n":19,"t":"这巴拉巴是因在城里作乱杀人，下在监里的。","notes":[]},{"n":20,"t":"彼拉多愿意释放耶稣，就又劝解他们。","notes":[]},{"n":21,"t":"无奈他们喊着说：「钉他十字架！钉他十字架！」","notes":[]},{"n":22,"t":"彼拉多第三次对他们说：「为什么呢？这人做了什么恶事呢？我并没有查出他什么该死的罪来。所以，我要责打他，把他释放了。」","notes":[]},{"n":23,"t":"他们大声催逼彼拉多，求他把耶稣钉在十字架上。他们的声音就得了胜。","notes":[]},{"n":24,"t":"彼拉多这才照他们所求的定案，","notes":[]},{"n":25,"t":"把他们所求的那作乱杀人、下在监里的释放了，把耶稣交给他们，任凭他们的意思行。","notes":[]},{"n":26,"t":"带耶稣去的时候，有一个古利奈人西门，从乡下来；他们就抓住他，把十字架搁在他身上，叫他背着跟随耶稣。","notes":[],"heads":["耶稣被钉十字架"]},{"n":27,"t":"有许多百姓跟随耶稣，内中有好些妇女；妇女们为他号咷痛哭。","notes":[]},{"n":28,"t":"耶稣转身对她们说：「耶路撒冷的女子，不要为我哭，当为自己和自己的儿女哭。","notes":[]},{"n":29,"t":"因为日子要到，人必说：『不生育的，和未曾怀胎的，未曾乳养婴孩的，有福了！』","notes":[]},{"n":30,"t":"那时，人要向大山说：倒在我们身上！向小山说：遮盖我们！","notes":[]},{"n":31,"t":"「这些事既行在有汁水的树上，那枯干的树将来怎么样呢？」","notes":[]},{"n":32,"t":"又有两个犯人，和耶稣一同带来处死。","notes":[]},{"n":33,"t":"到了一个地方，名叫「髑髅地」，就在那里把耶稣钉在十字架上，又钉了两个犯人：一个在左边，一个在右边。","notes":[]},{"n":34,"t":"当下耶稣说：「父啊！赦免他们；因为他们所做的，他们不晓得。」兵丁就拈阄分他的衣服。","notes":[]},{"n":35,"t":"百姓站在那里观看。官府也嗤笑他，说：「他救了别人；他若是基督，神所拣选的，可以救自己吧！」","notes":[]},{"n":36,"t":"兵丁也戏弄他，上前拿醋送给他喝，","notes":[]},{"n":37,"t":"说：「你若是犹太人的王，可以救自己吧！」","notes":[]},{"n":38,"t":"在耶稣以上有一个牌子写着：「这是犹太人的王。」","notes":["有古卷加：用希腊、罗马、希伯来的文字"]},{"n":39,"t":"那同钉的两个犯人有一个讥笑他，说：「你不是基督吗？可以救自己和我们吧！」","notes":[]},{"n":40,"t":"那一个就应声责备他，说：「你既是一样受刑的，还不怕神吗？","notes":[]},{"n":41,"t":"我们是应该的，因我们所受的与我们所做的相称，但这个人没有做过一件不好的事。」","notes":[]},{"n":42,"t":"就说：「耶稣啊，你得国降临的时候，求你记念我！」","notes":[]},{"n":43,"t":"耶稣对他说：「我实在告诉你，今日你要同我在乐园里了。」","notes":[]},{"n":44,"t":"那时约有午正，遍地都黑暗了，直到申初，","notes":[],"heads":["耶稣的死"]},{"n":45,"t":"日头变黑了；殿里的幔子从当中裂为两半。","notes":[]},{"n":46,"t":"耶稣大声喊着说：「父啊！我将我的灵魂交在你手里。」说了这话，气就断了。","notes":[]},{"n":47,"t":"百夫长看见所成的事，就归荣耀与神，说：「这真是个义人！」","notes":[]},{"n":48,"t":"聚集观看的众人见了这所成的事都捶着胸回去了。","notes":[]},{"n":49,"t":"还有一切与耶稣熟识的人，和从加利利跟着他来的妇女们，都远远地站着看这些事。","notes":[]},{"n":50,"t":"有一个人名叫约瑟，是个议士，为人善良公义；","notes":[],"heads":["耶稣的安葬"]},{"n":51,"t":"众人所谋所为，他并没有附从。他本是犹太、亚利马太城里素常盼望神国的人。","notes":[]},{"n":52,"t":"这人去见彼拉多，求耶稣的身体，","notes":[]},{"n":53,"t":"就取下来，用细麻布裹好，安放在石头凿成的坟墓里；那里头从来没有葬过人。","notes":[]},{"n":54,"t":"那日是预备日，安息日也快到了。","notes":[]},{"n":55,"t":"那些从加利利和耶稣同来的妇女跟在后面，看见了坟墓和他的身体怎样安放。","notes":[]},{"n":56,"t":"她们就回去，预备了香料香膏。她们在安息日，便遵着诫命安息了。","notes":[]}]},"24":{"heading":"耶稣复活","verses":[{"n":1,"t":"七日的头一日，黎明的时候，那些妇女带着所预备的香料来到坟墓前，","notes":[]},{"n":2,"t":"看见石头已经从坟墓滚开了，","notes":[]},{"n":3,"t":"她们就进去，只是不见主耶稣的身体。","notes":[]},{"n":4,"t":"正在猜疑之间，忽然有两个人站在旁边，衣服放光。","notes":[]},{"n":5,"t":"妇女们惊怕，将脸伏地。那两个人就对她们说：「为什么在死人中找活人呢？","notes":[]},{"n":6,"t":"他不在这里，已经复活了。当记念他还在加利利的时候怎样告诉你们，","notes":[]},{"n":7,"t":"说：『人子必须被交在罪人手里，钉在十字架上，第三日复活。』」","notes":[]},{"n":8,"t":"她们就想起耶稣的话来，","notes":[]},{"n":9,"t":"便从坟墓那里回去，把这一切的事告诉十一个使徒和其余的人。","notes":[]},{"n":10,"t":"那告诉使徒的就是抹大拉的马利亚和约亚拿，并雅各的母亲马利亚，还有与她们在一处的妇女。","notes":[]},{"n":11,"t":"她们这些话，使徒以为是胡言，就不相信。","notes":[]},{"n":12,"t":"彼得起来，跑到坟墓前，低头往里看，见细麻布独在一处，就回去了，心里希奇所成的事。","notes":[]},{"n":13,"t":"正当那日，门徒中有两个人往一个村子去；这村子名叫以马忤斯，离耶路撒冷约有二十五里。","notes":[],"heads":["在以马忤斯的路上"]},{"n":14,"t":"他们彼此谈论所遇见的这一切事。","notes":[]},{"n":15,"t":"正谈论相问的时候，耶稣亲自就近他们，和他们同行；","notes":[]},{"n":16,"t":"只是他们的眼睛迷糊了，不认识他。","notes":[]},{"n":17,"t":"耶稣对他们说：「你们走路彼此谈论的是什么事呢？」他们就站住，脸上带着愁容。","notes":[]},{"n":18,"t":"二人中有一个名叫革流巴的回答说：「你在耶路撒冷作客，还不知道这几天在那里所出的事吗？」","notes":[]},{"n":19,"t":"耶稣说：「什么事呢？」他们说：「就是拿撒勒人耶稣的事。他是个先知，在神和众百姓面前，说话行事都有大能。","notes":[]},{"n":20,"t":"祭司长和我们的官府竟把他解去，定了死罪，钉在十字架上。","notes":[]},{"n":21,"t":"但我们素来所盼望、要赎以色列民的就是他！不但如此，而且这事成就，现在已经三天了。","notes":[]},{"n":22,"t":"再者，我们中间有几个妇女使我们惊奇；她们清早到了坟墓那里，","notes":[]},{"n":23,"t":"不见他的身体，就回来告诉我们，说看见了天使显现，说他活了。","notes":[]},{"n":24,"t":"又有我们的几个人往坟墓那里去，所遇见的正如妇女们所说的，只是没有看见他。」","notes":[]},{"n":25,"t":"耶稣对他们说：「无知的人哪，先知所说的一切话，你们的心信得太迟钝了。","notes":[]},{"n":26,"t":"基督这样受害，又进入他的荣耀，岂不是应当的吗？」","notes":[]},{"n":27,"t":"于是从摩西和众先知起，凡经上所指着自己的话都给他们讲解明白了。","notes":[]},{"n":28,"t":"将近他们所去的村子，耶稣好像还要往前行，","notes":[]},{"n":29,"t":"他们却强留他，说：「时候晚了，日头已经平西了，请你同我们住下吧！」耶稣就进去，要同他们住下。","notes":[]},{"n":30,"t":"到了坐席的时候，耶稣拿起饼来，祝谢了，擘开，递给他们。","notes":[]},{"n":31,"t":"他们的眼睛明亮了，这才认出他来。忽然耶稣不见了。","notes":[]},{"n":32,"t":"他们彼此说：「在路上，他和我们说话，给我们讲解圣经的时候，我们的心岂不是火热的吗？」","notes":[]},{"n":33,"t":"他们就立时起身，回耶路撒冷去，正遇见十一个使徒和他们的同人聚集在一处，","notes":[]},{"n":34,"t":"说：「主果然复活，已经现给西门看了。」","notes":[]},{"n":35,"t":"两个人就把路上所遇见，和擘饼的时候怎么被他们认出来的事，都述说了一遍。","notes":[]},{"n":36,"t":"正说这话的时候，耶稣亲自站在他们当中，说：「愿你们平安！」","notes":[],"heads":["向门徒显现"]},{"n":37,"t":"他们却惊慌害怕，以为所看见的是魂。","notes":[]},{"n":38,"t":"耶稣说：「你们为什么愁烦？为什么心里起疑念呢？","notes":[]},{"n":39,"t":"你们看我的手，我的脚，就知道实在是我了。摸我看看！魂无骨无肉，你们看，我是有的。」","notes":[]},{"n":40,"t":"说了这话，就把手和脚给他们看。","notes":[]},{"n":41,"t":"他们正喜得不敢信，并且希奇；耶稣就说：「你们这里有什么吃的没有？」","notes":[]},{"n":42,"t":"他们便给他一片烧鱼。","notes":["有古卷加：和一块蜜房。"]},{"n":43,"t":"他接过来，在他们面前吃了。","notes":[]},{"n":44,"t":"耶稣对他们说：「这就是我从前与你们同在之时所告诉你们的话说：摩西的律法、先知的书，和诗篇上所记的，凡指着我的话都必须应验。」","notes":[]},{"n":45,"t":"于是耶稣开他们的心窍，使他们能明白圣经，","notes":[]},{"n":46,"t":"又对他们说：「照经上所写的，基督必受害，第三日从死里复活，","notes":[]},{"n":47,"t":"并且人要奉他的名传悔改、赦罪的道，从耶路撒冷起直传到万邦。","notes":[]},{"n":48,"t":"你们就是这些事的见证。","notes":[]},{"n":49,"t":"我要将我父所应许的降在你们身上，你们要在城里等候，直到你们领受从上头来的能力。」","notes":[]},{"n":50,"t":"耶稣领他们到伯大尼的对面，就举手给他们祝福。","notes":[],"heads":["耶稣升天"]},{"n":51,"t":"正祝福的时候，他就离开他们，被带到天上去了。","notes":[]},{"n":52,"t":"他们就拜他，大大地欢喜，回耶路撒冷去，","notes":[]},{"n":53,"t":"常在殿里称颂神。","notes":[]}]}},"JHN":{"1":{"heading":"道成肉身","verses":[{"n":1,"t":"太初有道，道与神同在，道就是神。","notes":[]},{"n":2,"t":"这道太初与神同在。","notes":[]},{"n":3,"t":"万物是借着他造的；凡被造的，没有一样不是借着他造的。","notes":[]},{"n":4,"t":"生命在他里头，这生命就是人的光。","notes":[]},{"n":5,"t":"光照在黑暗里，黑暗却不接受光。","notes":[]},{"n":6,"t":"有一个人，是从神那里差来的，名叫约翰。","notes":[]},{"n":7,"t":"这人来，为要作见证，就是为光作见证，叫众人因他可以信。","notes":[]},{"n":8,"t":"他不是那光，乃是要为光作见证。","notes":[]},{"n":9,"t":"那光是真光，照亮一切生在世上的人。","notes":[]},{"n":10,"t":"他在世界，世界也是借着他造的，世界却不认识他。","notes":[]},{"n":11,"t":"他到自己的地方来，自己的人倒不接待他。","notes":[]},{"n":12,"t":"凡接待他的，就是信他名的人，他就赐他们权柄作神的儿女。","notes":[]},{"n":13,"t":"这等人不是从血气生的，不是从情欲生的，也不是从人意生的，乃是从神生的。","notes":[]},{"n":14,"t":"道成了肉身，住在我们中间，充充满满地有恩典有真理。我们也见过他的荣光，正是父独生子的荣光。","notes":[]},{"n":15,"t":"约翰为他作见证，喊着说：「这就是我曾说：『那在我以后来的，反成了在我以前的，因他本来在我以前。』」","notes":[]},{"n":16,"t":"从他丰满的恩典里，我们都领受了，而且恩上加恩。","notes":[]},{"n":17,"t":"律法本是借着摩西传的；恩典和真理都是由耶稣基督来的。","notes":[]},{"n":18,"t":"从来没有人看见神，只有在父怀里的独生子将他表明出来。","notes":[]},{"n":19,"t":"约翰所作的见证记在下面：犹太人从耶路撒冷差祭司和利未人到约翰那里，问他说：「你是谁？」","notes":[],"heads":["施洗约翰的见证"]},{"n":20,"t":"他就明说，并不隐瞒，明说：「我不是基督。」","notes":[]},{"n":21,"t":"他们又问他说：「这样，你是谁呢？是以利亚吗？」他说：「我不是。」「是那先知吗？」他回答说：「不是。」","notes":[]},{"n":22,"t":"于是他们说：「你到底是谁，叫我们好回复差我们来的人。你自己说，你是谁？」","notes":[]},{"n":23,"t":"他说：「我就是那在旷野有人声喊着说：『修直主的道路』，正如先知以赛亚所说的。」","notes":[]},{"n":24,"t":"那些人是法利赛人差来的；","notes":["或译：那差来的是法利赛人"]},{"n":25,"t":"他们就问他说：「你既不是基督，不是以利亚，也不是那先知，为什么施洗呢？」","notes":[]},{"n":26,"t":"约翰回答说：「我是用水施洗，但有一位站在你们中间，是你们不认识的，","notes":[]},{"n":27,"t":"就是那在我以后来的，我给他解鞋带也不配。」","notes":[]},{"n":28,"t":"这是在约旦河外伯大尼，约翰施洗的地方作的见证。","notes":["有古卷：伯大巴喇"]},{"n":29,"t":"次日，约翰看见耶稣来到他那里，就说：「看哪，神的羔羊，除去世人罪孽的！","notes":["或译：背负"],"heads":["神的羔羊"]},{"n":30,"t":"这就是我曾说：『有一位在我以后来、反成了在我以前的，因他本来在我以前。』","notes":[]},{"n":31,"t":"我先前不认识他，如今我来用水施洗，为要叫他显明给以色列人。」","notes":[]},{"n":32,"t":"约翰又作见证说：「我曾看见圣灵，仿佛鸽子从天降下，住在他的身上。","notes":[]},{"n":33,"t":"我先前不认识他，只是那差我来用水施洗的、对我说：『你看见圣灵降下来，住在谁的身上，谁就是用圣灵施洗的。』","notes":[]},{"n":34,"t":"我看见了，就证明这是神的儿子。」","notes":[]},{"n":35,"t":"再次日，约翰同两个门徒站在那里。","notes":[],"heads":["初次选召门徒"]},{"n":36,"t":"他见耶稣行走，就说：「看哪，这是神的羔羊！」","notes":[]},{"n":37,"t":"两个门徒听见他的话，就跟从了耶稣。","notes":[]},{"n":38,"t":"耶稣转过身来，看见他们跟着，就问他们说：「你们要什么？」他们说：「拉比，在哪里住？」（拉比翻出来就是夫子。）","notes":[]},{"n":39,"t":"耶稣说：「你们来看。」他们就去看他在哪里住，这一天便与他同住；那时约有申正了。","notes":[]},{"n":40,"t":"听见约翰的话跟从耶稣的那两个人，一个是西门·彼得的兄弟安得烈。","notes":[]},{"n":41,"t":"他先找着自己的哥哥西门，对他说：「我们遇见弥赛亚了。」（弥赛亚翻出来就是基督。）","notes":[]},{"n":42,"t":"于是领他去见耶稣。耶稣看着他，说：「你是约翰的儿子西门，你要称为矶法。」（矶法翻出来就是彼得。）","notes":["约翰在马太十六章十七节称约拿"]},{"n":43,"t":"又次日，耶稣想要往加利利去，遇见腓力，就对他说：「来跟从我吧。」","notes":[],"heads":["呼召腓力和拿但业"]},{"n":44,"t":"这腓力是伯赛大人，和安得烈、彼得同城。","notes":[]},{"n":45,"t":"腓力找着拿但业，对他说：「摩西在律法上所写的和众先知所记的那一位，我们遇见了，就是约瑟的儿子拿撒勒人耶稣。」","notes":[]},{"n":46,"t":"拿但业对他说：「拿撒勒还能出什么好的吗？」腓力说：「你来看！」","notes":[]},{"n":47,"t":"耶稣看见拿但业来，就指着他说：「看哪，这是个真以色列人，他心里是没有诡诈的。」","notes":[]},{"n":48,"t":"拿但业对耶稣说：「你从哪里知道我呢？」耶稣回答说：「腓力还没有招呼你，你在无花果树底下，我就看见你了。」","notes":[]},{"n":49,"t":"拿但业说：「拉比，你是神的儿子，你是以色列的王！」","notes":[]},{"n":50,"t":"耶稣对他说：「因为我说『在无花果树底下看见你』，你就信吗？你将要看见比这更大的事」；","notes":[]},{"n":51,"t":"又说：「我实实在在地告诉你们，你们将要看见天开了，神的使者上去下来在人子身上。」","notes":[]}]},"2":{"heading":"迦拿的婚礼","verses":[{"n":1,"t":"第三日，在加利利的迦拿有娶亲的筵席，耶稣的母亲在那里。","notes":[]},{"n":2,"t":"耶稣和他的门徒也被请去赴席。","notes":[]},{"n":3,"t":"酒用尽了，耶稣的母亲对他说：「他们没有酒了。」","notes":[]},{"n":4,"t":"耶稣说：「母亲，我与你有什么相干？我的时候还没有到。」","notes":["原文是妇人"]},{"n":5,"t":"他母亲对用人说：「他告诉你们什么，你们就做什么。」","notes":[]},{"n":6,"t":"照犹太人洁净的规矩，有六口石缸摆在那里，每口可以盛两三桶水。","notes":[]},{"n":7,"t":"耶稣对用人说：「把缸倒满了水。」他们就倒满了，直到缸口。","notes":[]},{"n":8,"t":"耶稣又说：「现在可以舀出来，送给管筵席的。」他们就送了去。","notes":[]},{"n":9,"t":"管筵席的尝了那水变的酒，并不知道是哪里来的，只有舀水的用人知道。管筵席的便叫新郎来，","notes":[]},{"n":10,"t":"对他说：「人都是先摆上好酒，等客喝足了，才摆上次的，你倒把好酒留到如今！」","notes":[]},{"n":11,"t":"这是耶稣所行的头一件神迹，是在加利利的迦拿行的，显出他的荣耀来；他的门徒就信他了。","notes":[]},{"n":12,"t":"这事以后，耶稣与他的母亲、弟兄，和门徒都下迦百农去，在那里住了不多几日。","notes":[]},{"n":13,"t":"犹太人的逾越节近了，耶稣就上耶路撒冷去。","notes":[],"heads":["洁净圣殿"]},{"n":14,"t":"看见殿里有卖牛、羊、鸽子的，并有兑换银钱的人坐在那里，","notes":[]},{"n":15,"t":"耶稣就拿绳子做成鞭子，把牛羊都赶出殿去，倒出兑换银钱之人的银钱，推翻他们的桌子，","notes":[]},{"n":16,"t":"又对卖鸽子的说：「把这些东西拿去！不要将我父的殿当作买卖的地方。」","notes":[]},{"n":17,"t":"他的门徒就想起经上记着说：「我为你的殿心里焦急，如同火烧。」","notes":[]},{"n":18,"t":"因此犹太人问他说：「你既做这些事，还显什么神迹给我们看呢？」","notes":[]},{"n":19,"t":"耶稣回答说：「你们拆毁这殿，我三日内要再建立起来。」","notes":[]},{"n":20,"t":"犹太人便说：「这殿是四十六年才造成的，你三日内就再建立起来吗？」","notes":[]},{"n":21,"t":"但耶稣这话是以他的身体为殿。","notes":[]},{"n":22,"t":"所以到他从死里复活以后，门徒就想起他说过这话，便信了圣经和耶稣所说的。","notes":[]},{"n":23,"t":"当耶稣在耶路撒冷过逾越节的时候，有许多人看见他所行的神迹，就信了他的名。","notes":[],"heads":["耶稣洞悉人心"]},{"n":24,"t":"耶稣却不将自己交托他们；因为他知道万人，","notes":[]},{"n":25,"t":"也用不着谁见证人怎样，因他知道人心里所存的。","notes":[]}]},"3":{"heading":"耶稣与尼哥德慕","verses":[{"n":1,"t":"有一个法利赛人，名叫尼哥德慕，是犹太人的官。","notes":[]},{"n":2,"t":"这人夜里来见耶稣，说：「拉比，我们知道你是由神那里来作师傅的；因为你所行的神迹，若没有神同在，无人能行。」","notes":[]},{"n":3,"t":"耶稣回答说：「我实实在在地告诉你，人若不重生，就不能见神的国。」","notes":[]},{"n":4,"t":"尼哥德慕说：「人已经老了，如何能重生呢？岂能再进母腹生出来吗？」","notes":[]},{"n":5,"t":"耶稣说：「我实实在在地告诉你，人若不是从水和圣灵生的，就不能进神的国。","notes":[]},{"n":6,"t":"从肉身生的就是肉身；从灵生的就是灵。","notes":[]},{"n":7,"t":"我说：『你们必须重生』，你不要以为希奇。","notes":[]},{"n":8,"t":"风随着意思吹，你听见风的响声，却不晓得从哪里来，往哪里去；凡从圣灵生的，也是如此。」","notes":[]},{"n":9,"t":"尼哥德慕问他说：「怎能有这事呢？」","notes":[]},{"n":10,"t":"耶稣回答说：「你是以色列人的先生，还不明白这事吗？","notes":[]},{"n":11,"t":"我实实在在地告诉你，我们所说的是我们知道的；我们所见证的是我们见过的；你们却不领受我们的见证。","notes":[]},{"n":12,"t":"我对你们说地上的事，你们尚且不信，若说天上的事，如何能信呢？","notes":[]},{"n":13,"t":"除了从天降下、仍旧在天的人子，没有人升过天。","notes":[]},{"n":14,"t":"摩西在旷野怎样举蛇，人子也必照样被举起来，","notes":[]},{"n":15,"t":"叫一切信他的都得永生。","notes":["或译：叫一切信的人在他里面得永生"]},{"n":16,"t":"「神爱世人，甚至将他的独生子赐给他们，叫一切信他的，不致灭亡，反得永生。","notes":[]},{"n":17,"t":"因为神差他的儿子降世，不是要定世人的罪，乃是要叫世人因他得救。","notes":["或译：审判世人；下同"]},{"n":18,"t":"信他的人，不被定罪；不信的人，罪已经定了，因为他不信神独生子的名。","notes":[]},{"n":19,"t":"光来到世间，世人因自己的行为是恶的，不爱光，倒爱黑暗，定他们的罪就是在此。","notes":[]},{"n":20,"t":"凡作恶的便恨光，并不来就光，恐怕他的行为受责备。","notes":[]},{"n":21,"t":"但行真理的必来就光，要显明他所行的是靠神而行。」","notes":[]},{"n":22,"t":"这事以后，耶稣和门徒到了犹太地，在那里居住，施洗。","notes":[],"heads":["耶稣和施洗约翰"]},{"n":23,"t":"约翰在靠近撒冷的哀嫩也施洗；因为那里水多，众人都去受洗。（","notes":[]},{"n":24,"t":"那时约翰还没有下在监里。）","notes":[]},{"n":25,"t":"约翰的门徒和一个犹太人辩论洁净的礼，","notes":[]},{"n":26,"t":"就来见约翰，说：「拉比，从前同你在约旦河外、你所见证的那位，现在施洗，众人都往他那里去了。」","notes":[]},{"n":27,"t":"约翰说：「若不是从天上赐的，人就不能得什么。","notes":[]},{"n":28,"t":"我曾说：『我不是基督，是奉差遣在他前面的』，你们自己可以给我作见证。","notes":[]},{"n":29,"t":"娶新妇的就是新郎；新郎的朋友站着，听见新郎的声音就甚喜乐。故此，我这喜乐满足了。","notes":[]},{"n":30,"t":"他必兴旺，我必衰微。」","notes":[]},{"n":31,"t":"「从天上来的是在万有之上；从地上来的是属乎地，他所说的也是属乎地。从天上来的是在万有之上。","notes":[],"heads":["从天上来的那一位"]},{"n":32,"t":"他将所见所闻的见证出来，只是没有人领受他的见证。","notes":[]},{"n":33,"t":"那领受他见证的，就印上印，证明神是真的。","notes":[]},{"n":34,"t":"神所差来的就说神的话，因为神赐圣灵给他是没有限量的。","notes":[]},{"n":35,"t":"父爱子，已将万有交在他手里。","notes":[]},{"n":36,"t":"信子的人有永生；不信子的人得不着永生，神的震怒常在他身上。」","notes":["原文是不得见永生"]}]},"4":{"heading":"耶稣和撒马利亚妇人","verses":[{"n":1,"t":"主知道法利赛人听见他收门徒，施洗，比约翰还多，（","notes":[]},{"n":2,"t":"其实不是耶稣亲自施洗，乃是他的门徒施洗，）","notes":[]},{"n":3,"t":"他就离了犹太，又往加利利去。","notes":[]},{"n":4,"t":"必须经过撒马利亚，","notes":[]},{"n":5,"t":"于是到了撒马利亚的一座城，名叫叙加，靠近雅各给他儿子约瑟的那块地。","notes":[]},{"n":6,"t":"在那里有雅各井；耶稣因走路困乏，就坐在井旁。那时约有午正。","notes":[]},{"n":7,"t":"有一个撒马利亚的妇人来打水。耶稣对她说：「请你给我水喝。」（","notes":[]},{"n":8,"t":"那时门徒进城买食物去了。）","notes":[]},{"n":9,"t":"撒马利亚的妇人对他说：「你既是犹太人，怎么向我一个撒马利亚妇人要水喝呢？」原来犹太人和撒马利亚人没有来往。","notes":[]},{"n":10,"t":"耶稣回答说：「你若知道神的恩赐，和对你说『给我水喝』的是谁，你必早求他，他也必早给了你活水。」","notes":[]},{"n":11,"t":"妇人说：「先生，没有打水的器具，井又深，你从哪里得活水呢？","notes":[]},{"n":12,"t":"我们的祖宗雅各将这井留给我们，他自己和儿子并牲畜也都喝这井里的水，难道你比他还大吗？」","notes":[]},{"n":13,"t":"耶稣回答说：「凡喝这水的还要再渴；","notes":[]},{"n":14,"t":"人若喝我所赐的水就永远不渴。我所赐的水要在他里头成为泉源，直涌到永生。」","notes":[]},{"n":15,"t":"妇人说：「先生，请把这水赐给我，叫我不渴，也不用来这么远打水。」","notes":[]},{"n":16,"t":"耶稣说：「你去叫你丈夫也到这里来。」","notes":[]},{"n":17,"t":"妇人说：「我没有丈夫。」耶稣说：「你说没有丈夫是不错的。","notes":[]},{"n":18,"t":"你已经有五个丈夫，你现在有的并不是你的丈夫。你这话是真的。」","notes":[]},{"n":19,"t":"妇人说：「先生，我看出你是先知。","notes":[]},{"n":20,"t":"我们的祖宗在这山上礼拜，你们倒说，应当礼拜的地方是在耶路撒冷。」","notes":[]},{"n":21,"t":"耶稣说：「妇人，你当信我。时候将到，你们拜父，也不在这山上，也不在耶路撒冷。","notes":[]},{"n":22,"t":"你们所拜的，你们不知道；我们所拜的，我们知道，因为救恩是从犹太人出来的。","notes":[]},{"n":23,"t":"时候将到，如今就是了，那真正拜父的，要用心灵和诚实拜他，因为父要这样的人拜他。」","notes":[]},{"n":24,"t":"神是个灵，所以拜他的必须用心灵和诚实拜他。","notes":["或无个字"]},{"n":25,"t":"妇人说：「我知道弥赛亚（就是那称为基督的）要来；他来了，必将一切的事都告诉我们。」","notes":[]},{"n":26,"t":"耶稣说：「这和你说话的就是他！」","notes":[]},{"n":27,"t":"当下门徒回来，就希奇耶稣和一个妇人说话；只是没有人说：「你是要什么？」或说：「你为什么和她说话？」","notes":[]},{"n":28,"t":"那妇人就留下水罐子，往城里去，对众人说：","notes":[]},{"n":29,"t":"「你们来看！有一个人将我素来所行的一切事都给我说出来了，莫非这就是基督吗？」","notes":[]},{"n":30,"t":"众人就出城，往耶稣那里去。","notes":[]},{"n":31,"t":"这其间，门徒对耶稣说：「拉比，请吃。」","notes":[]},{"n":32,"t":"耶稣说：「我有食物吃，是你们不知道的。」","notes":[]},{"n":33,"t":"门徒就彼此对问说：「莫非有人拿什么给他吃吗？」","notes":[]},{"n":34,"t":"耶稣说：「我的食物就是遵行差我来者的旨意，做成他的工。","notes":[]},{"n":35,"t":"你们岂不说『到收割的时候还有四个月』吗？我告诉你们，举目向田观看，庄稼已经熟了，可以收割了。","notes":["原文是发白"]},{"n":36,"t":"收割的人得工价，积蓄五谷到永生，叫撒种的和收割的一同快乐。","notes":[]},{"n":37,"t":"俗语说：『那人撒种，这人收割』，这话可见是真的。","notes":[]},{"n":38,"t":"我差你们去收你们所没有劳苦的；别人劳苦，你们享受他们所劳苦的。」","notes":[]},{"n":39,"t":"那城里有好些撒马利亚人信了耶稣，因为那妇人作见证说：「他将我素来所行的一切事都给我说出来了。」","notes":[]},{"n":40,"t":"于是撒马利亚人来见耶稣，求他在他们那里住下，他便在那里住了两天。","notes":[]},{"n":41,"t":"因耶稣的话，信的人就更多了，","notes":[]},{"n":42,"t":"便对妇人说：「现在我们信，不是因为你的话，是我们亲自听见了，知道这真是救世主。」","notes":[]},{"n":43,"t":"过了那两天，耶稣离了那地方，往加利利去。","notes":[],"heads":["耶稣治好大臣的儿子"]},{"n":44,"t":"因为耶稣自己作过见证说：「先知在本地是没有人尊敬的。」","notes":[]},{"n":45,"t":"到了加利利，加利利人既然看见他在耶路撒冷过节所行的一切事，就接待他，因为他们也是上去过节。","notes":[]},{"n":46,"t":"耶稣又到了加利利的迦拿，就是他从前变水为酒的地方。有一个大臣，他的儿子在迦百农患病。","notes":[]},{"n":47,"t":"他听见耶稣从犹太到了加利利，就来见他，求他下去医治他的儿子，因为他儿子快要死了。","notes":[]},{"n":48,"t":"耶稣就对他说：「若不看见神迹奇事，你们总是不信。」","notes":[]},{"n":49,"t":"那大臣说：「先生，求你趁着我的孩子还没有死就下去。」","notes":[]},{"n":50,"t":"耶稣对他说：「回去吧，你的儿子活了！」那人信耶稣所说的话就回去了。","notes":[]},{"n":51,"t":"正下去的时候，他的仆人迎见他，说他的儿子活了。","notes":[]},{"n":52,"t":"他就问什么时候见好的。他们说：「昨日未时热就退了。」","notes":[]},{"n":53,"t":"他便知道这正是耶稣对他说「你儿子活了」的时候；他自己和全家就都信了。","notes":[]},{"n":54,"t":"这是耶稣在加利利行的第二件神迹，是他从犹太回去以后行的。","notes":[]}]},"5":{"heading":"在毕士大池边治病","verses":[{"n":1,"t":"这事以后，到了犹太人的一个节期，耶稣就上耶路撒冷去。","notes":[]},{"n":2,"t":"在耶路撒冷，靠近羊门有一个池子，希伯来话叫作毕士大，旁边有五个廊子；","notes":[]},{"n":3,"t":"里面躺着瞎眼的、瘸腿的、血气枯干的许多病人。","notes":["有古卷加：等候水动；4因为有天使按时下池子搅动那水，水动之后，谁先下去，无论害什么病就痊愈了。"]},{"n":5,"t":"在那里有一个人，病了三十八年。","notes":[]},{"n":6,"t":"耶稣看见他躺着，知道他病了许久，就问他说：「你要痊愈吗？」","notes":[]},{"n":7,"t":"病人回答说：「先生，水动的时候，没有人把我放在池子里；我正去的时候，就有别人比我先下去。」","notes":[]},{"n":8,"t":"耶稣对他说：「起来，拿你的褥子走吧！」","notes":[]},{"n":9,"t":"那人立刻痊愈，就拿起褥子来走了。","notes":[]},{"n":10,"t":"那天是安息日，所以犹太人对那医好的人说：「今天是安息日，你拿褥子是不可的。」","notes":[]},{"n":11,"t":"他却回答说：「那使我痊愈的，对我说：『拿你的褥子走吧。』」","notes":[]},{"n":12,"t":"他们问他说：「对你说『拿褥子走』的是什么人？」","notes":[]},{"n":13,"t":"那医好的人不知道是谁；因为那里的人多，耶稣已经躲开了。","notes":[]},{"n":14,"t":"后来耶稣在殿里遇见他，对他说：「你已经痊愈了，不要再犯罪，恐怕你遭遇的更加利害。」","notes":[]},{"n":15,"t":"那人就去告诉犹太人，使他痊愈的是耶稣。","notes":[]},{"n":16,"t":"所以犹太人逼迫耶稣，因为他在安息日做了这事。","notes":[]},{"n":17,"t":"耶稣就对他们说：「我父做事直到如今，我也做事。」","notes":[]},{"n":18,"t":"所以犹太人越发想要杀他；因他不但犯了安息日，并且称神为他的父，将自己和神当作平等。","notes":[]},{"n":19,"t":"耶稣对他们说：「我实实在在地告诉你们，子凭着自己不能做什么，惟有看见父所做的，子才能做；父所做的事，子也照样做。","notes":[],"heads":["子的权柄"]},{"n":20,"t":"父爱子，将自己所做的一切事指给他看，还要将比这更大的事指给他看，叫你们希奇。","notes":[]},{"n":21,"t":"父怎样叫死人起来，使他们活着，子也照样随自己的意思使人活着。","notes":[]},{"n":22,"t":"父不审判什么人，乃将审判的事全交与子，","notes":[]},{"n":23,"t":"叫人都尊敬子如同尊敬父一样。不尊敬子的，就是不尊敬差子来的父。","notes":[]},{"n":24,"t":"我实实在在地告诉你们，那听我话、又信差我来者的，就有永生；不至于定罪，是已经出死入生了。","notes":[]},{"n":25,"t":"我实实在在地告诉你们，时候将到，现在就是了，死人要听见神儿子的声音，听见的人就要活了。","notes":[]},{"n":26,"t":"因为父怎样在自己有生命，就赐给他儿子也照样在自己有生命，","notes":[]},{"n":27,"t":"并且因为他是人子，就赐给他行审判的权柄。","notes":[]},{"n":28,"t":"你们不要把这事看作希奇。时候要到，凡在坟墓里的，都要听见他的声音，就出来：","notes":[]},{"n":29,"t":"行善的，复活得生；作恶的，复活定罪。","notes":[]},{"n":30,"t":"「我凭着自己不能做什么，我怎么听见就怎么审判。我的审判也是公平的；因为我不求自己的意思，只求那差我来者的意思。」","notes":[]},{"n":31,"t":"「我若为自己作见证，我的见证就不真。","notes":[],"heads":["为耶稣作证"]},{"n":32,"t":"另有一位给我作见证，我也知道他给我作的见证是真的。","notes":[]},{"n":33,"t":"你们曾差人到约翰那里，他为真理作过见证。","notes":[]},{"n":34,"t":"其实，我所受的见证不是从人来的；然而，我说这些话，为要叫你们得救。","notes":[]},{"n":35,"t":"约翰是点着的明灯，你们情愿暂时喜欢他的光。","notes":[]},{"n":36,"t":"但我有比约翰更大的见证；因为父交给我要我成就的事，就是我所做的事，这便见证我是父所差来的。","notes":[]},{"n":37,"t":"差我来的父也为我作过见证。你们从来没有听见他的声音，也没有看见他的形象。","notes":[]},{"n":38,"t":"你们并没有他的道存在心里；因为他所差来的，你们不信。","notes":[]},{"n":39,"t":"你们查考圣经，因你们以为内中有永生；给我作见证的就是这经。","notes":["或译：应当查考圣经"]},{"n":40,"t":"然而，你们不肯到我这里来得生命。","notes":[]},{"n":41,"t":"「我不受从人来的荣耀。","notes":[]},{"n":42,"t":"但我知道，你们心里没有神的爱。","notes":[]},{"n":43,"t":"我奉我父的名来，你们并不接待我；若有别人奉自己的名来，你们倒要接待他。","notes":[]},{"n":44,"t":"你们互相受荣耀，却不求从独一之神来的荣耀，怎能信我呢？","notes":[]},{"n":45,"t":"不要想我在父面前要告你们；有一位告你们的，就是你们所仰赖的摩西。","notes":[]},{"n":46,"t":"你们如果信摩西，也必信我，因为他书上有指着我写的话。","notes":[]},{"n":47,"t":"你们若不信他的书，怎能信我的话呢？」","notes":[]}]},"6":{"heading":"耶稣给五千人吃饱","verses":[{"n":1,"t":"这事以后，耶稣渡过加利利海，就是提比哩亚海。","notes":[]},{"n":2,"t":"有许多人因为看见他在病人身上所行的神迹，就跟随他。","notes":[]},{"n":3,"t":"耶稣上了山，和门徒一同坐在那里。","notes":[]},{"n":4,"t":"那时犹太人的逾越节近了。","notes":[]},{"n":5,"t":"耶稣举目看见许多人来，就对腓力说：「我们从哪里买饼叫这些人吃呢？」（","notes":[]},{"n":6,"t":"他说这话是要试验腓力；他自己原知道要怎样行。）","notes":[]},{"n":7,"t":"腓力回答说：「就是二十两银子的饼，叫他们各人吃一点也是不够的。」","notes":[]},{"n":8,"t":"有一个门徒，就是西门·彼得的兄弟安得烈，对耶稣说：","notes":[]},{"n":9,"t":"「在这里有一个孩童，带着五个大麦饼、两条鱼，只是分给这许多人还算什么呢？」","notes":[]},{"n":10,"t":"耶稣说：「你们叫众人坐下。」原来那地方的草多，众人就坐下，数目约有五千。","notes":[]},{"n":11,"t":"耶稣拿起饼来，祝谢了，就分给那坐着的人；分鱼也是这样，都随着他们所要的。","notes":[]},{"n":12,"t":"他们吃饱了，耶稣对门徒说：「把剩下的零碎收拾起来，免得有糟蹋的。」","notes":[]},{"n":13,"t":"他们便将那五个大麦饼的零碎，就是众人吃了剩下的，收拾起来，装满了十二个篮子。","notes":[]},{"n":14,"t":"众人看见耶稣所行的神迹，就说：「这真是那要到世间来的先知！」","notes":[]},{"n":15,"t":"耶稣既知道众人要来强逼他作王，就独自又退到山上去了。","notes":[]},{"n":16,"t":"到了晚上，他的门徒下海边去，","notes":[],"heads":["耶稣在海面上行走"]},{"n":17,"t":"上了船，要过海往迦百农去。天已经黑了，耶稣还没有来到他们那里。","notes":[]},{"n":18,"t":"忽然狂风大作，海就翻腾起来。","notes":[]},{"n":19,"t":"门徒摇橹，约行了十里多路，看见耶稣在海面上走，渐渐近了船，他们就害怕。","notes":[]},{"n":20,"t":"耶稣对他们说：「是我，不要怕！」","notes":[]},{"n":21,"t":"门徒就喜欢接他上船，船立时到了他们所要去的地方。","notes":[]},{"n":22,"t":"第二日，站在海那边的众人知道那里没有别的船，只有一只小船，又知道耶稣没有同他的门徒上船，乃是门徒自己去的。","notes":[],"heads":["耶稣是生命的粮"]},{"n":23,"t":"然而，有几只小船从提比哩亚来，靠近主祝谢后分饼给人吃的地方。","notes":[]},{"n":24,"t":"众人见耶稣和门徒都不在那里，就上了船，往迦百农去找耶稣。","notes":[]},{"n":25,"t":"既在海那边找着了，就对他说：「拉比，是几时到这里来的？」","notes":[]},{"n":26,"t":"耶稣回答说：「我实实在在地告诉你们，你们找我，并不是因见了神迹，乃是因吃饼得饱。","notes":[]},{"n":27,"t":"不要为那必坏的食物劳力，要为那存到永生的食物劳力，就是人子要赐给你们的，因为人子是父神所印证的。」","notes":[]},{"n":28,"t":"众人问他说：「我们当行什么才算做神的工呢？」","notes":[]},{"n":29,"t":"耶稣回答说：「信神所差来的，这就是做神的工。」","notes":[]},{"n":30,"t":"他们又说：「你行什么神迹，叫我们看见就信你；你到底做什么事呢？","notes":[]},{"n":31,"t":"我们的祖宗在旷野吃过吗哪，如经上写着说：『他从天上赐下粮来给他们吃。』」","notes":[]},{"n":32,"t":"耶稣说：「我实实在在地告诉你们，那从天上来的粮不是摩西赐给你们的，乃是我父将天上来的真粮赐给你们。","notes":[]},{"n":33,"t":"因为神的粮就是那从天上降下来、赐生命给世界的。」","notes":[]},{"n":34,"t":"他们说：「主啊，常将这粮赐给我们！」","notes":[]},{"n":35,"t":"耶稣说：「我就是生命的粮。到我这里来的，必定不饿；信我的，永远不渴。","notes":[]},{"n":36,"t":"只是我对你们说过，你们已经看见我，还是不信。","notes":[]},{"n":37,"t":"凡父所赐给我的人必到我这里来；到我这里来的，我总不丢弃他。","notes":[]},{"n":38,"t":"因为我从天上降下来，不是要按自己的意思行，乃是要按那差我来者的意思行。","notes":[]},{"n":39,"t":"差我来者的意思就是：他所赐给我的，叫我一个也不失落，在末日却叫他复活。","notes":[]},{"n":40,"t":"因为我父的意思是叫一切见子而信的人得永生，并且在末日我要叫他复活。」","notes":[]},{"n":41,"t":"犹太人因为耶稣说「我是从天上降下来的粮」，就私下议论他，","notes":[]},{"n":42,"t":"说：「这不是约瑟的儿子耶稣吗？他的父母我们岂不认得吗？他如今怎么说『我是从天上降下来的』呢？」","notes":[]},{"n":43,"t":"耶稣回答说：「你们不要大家议论。","notes":[]},{"n":44,"t":"若不是差我来的父吸引人，就没有能到我这里来的；到我这里来的，在末日我要叫他复活。","notes":[]},{"n":45,"t":"在先知书上写着说：『他们都要蒙神的教训。』凡听见父之教训又学习的，就到我这里来。","notes":[]},{"n":46,"t":"这不是说有人看见过父，惟独从神来的，他看见过父。","notes":[]},{"n":47,"t":"我实实在在地告诉你们，信的人有永生。","notes":[]},{"n":48,"t":"我就是生命的粮。","notes":[]},{"n":49,"t":"你们的祖宗在旷野吃过吗哪，还是死了。","notes":[]},{"n":50,"t":"这是从天上降下来的粮，叫人吃了就不死。","notes":[]},{"n":51,"t":"我是从天上降下来生命的粮；人若吃这粮，就必永远活着。我所要赐的粮就是我的肉，为世人之生命所赐的。」","notes":[]},{"n":52,"t":"因此，犹太人彼此争论说：「这个人怎能把他的肉给我们吃呢？」","notes":[]},{"n":53,"t":"耶稣说：「我实实在在地告诉你们，你们若不吃人子的肉，不喝人子的血，就没有生命在你们里面。","notes":[]},{"n":54,"t":"吃我肉、喝我血的人就有永生，在末日我要叫他复活。","notes":[]},{"n":55,"t":"我的肉真是可吃的，我的血真是可喝的。","notes":[]},{"n":56,"t":"吃我肉、喝我血的人常在我里面，我也常在他里面。","notes":[]},{"n":57,"t":"永活的父怎样差我来，我又因父活着；照样，吃我肉的人也要因我活着。","notes":[]},{"n":58,"t":"这就是从天上降下来的粮。吃这粮的人就永远活着，不像你们的祖宗吃过吗哪还是死了。」","notes":[]},{"n":59,"t":"这些话是耶稣在迦百农会堂里教训人说的。","notes":[]},{"n":60,"t":"他的门徒中有好些人听见了，就说：「这话甚难，谁能听呢？」","notes":[],"heads":["永生的话语"]},{"n":61,"t":"耶稣心里知道门徒为这话议论，就对他们说：「这话是叫你们厌弃吗？","notes":["原文是跌倒"]},{"n":62,"t":"倘或你们看见人子升到他原来所在之处，怎么样呢？","notes":[]},{"n":63,"t":"叫人活着的乃是灵，肉体是无益的。我对你们所说的话就是灵，就是生命。","notes":[]},{"n":64,"t":"只是你们中间有不信的人。」耶稣从起头就知道谁不信他，谁要卖他。","notes":[]},{"n":65,"t":"耶稣又说：「所以我对你们说过，若不是蒙我父的恩赐，没有人能到我这里来。」","notes":[]},{"n":66,"t":"从此，他门徒中多有退去的，不再和他同行。","notes":[]},{"n":67,"t":"耶稣就对那十二个门徒说：「你们也要去吗？」","notes":[]},{"n":68,"t":"西门·彼得回答说：「主啊，你有永生之道，我们还归从谁呢？","notes":[]},{"n":69,"t":"我们已经信了，又知道你是神的圣者。」","notes":[]},{"n":70,"t":"耶稣说：「我不是拣选了你们十二个门徒吗？但你们中间有一个是魔鬼。」","notes":[]},{"n":71,"t":"耶稣这话是指着加略人西门的儿子犹大说的；他本是十二个门徒里的一个，后来要卖耶稣的。","notes":[]}]},"7":{"heading":"耶稣的兄弟不信","verses":[{"n":1,"t":"这事以后，耶稣在加利利游行，不愿在犹太游行，因为犹太人想要杀他。","notes":[]},{"n":2,"t":"当时犹太人的住棚节近了。","notes":[]},{"n":3,"t":"耶稣的弟兄就对他说：「你离开这里上犹太去吧，叫你的门徒也看见你所行的事。","notes":[]},{"n":4,"t":"人要显扬名声，没有在暗处行事的；你如果行这些事，就当将自己显明给世人看。」","notes":[]},{"n":5,"t":"因为连他的弟兄说这话，是因为不信他。","notes":[]},{"n":6,"t":"耶稣就对他们说：「我的时候还没有到；你们的时候常是方便的。","notes":[]},{"n":7,"t":"世人不能恨你们，却是恨我，因为我指证他们所做的事是恶的。","notes":[]},{"n":8,"t":"你们上去过节吧，我现在不上去过这节，因为我的时候还没有满。」","notes":[]},{"n":9,"t":"耶稣说了这话，仍旧住在加利利。","notes":[]},{"n":10,"t":"但他弟兄上去以后，他也上去过节，不是明去，似乎是暗去的。","notes":[],"heads":["耶稣过住棚节"]},{"n":11,"t":"正在节期，犹太人寻找耶稣，说：「他在哪里？」","notes":[]},{"n":12,"t":"众人为他纷纷议论，有的说：「他是好人。」有的说：「不然，他是迷惑众人的。」","notes":[]},{"n":13,"t":"只是没有人明明地讲论他，因为怕犹太人。","notes":[]},{"n":14,"t":"到了节期，耶稣上殿里去教训人。","notes":[]},{"n":15,"t":"犹太人就希奇，说：「这个人没有学过，怎么明白书呢？」","notes":[]},{"n":16,"t":"耶稣说：「我的教训不是我自己的，乃是那差我来者的。","notes":[]},{"n":17,"t":"人若立志遵着他的旨意行，就必晓得这教训或是出于神，或是我凭着自己说的。","notes":[]},{"n":18,"t":"人凭着自己说，是求自己的荣耀；惟有求那差他来者的荣耀，这人是真的，在他心里没有不义。","notes":[]},{"n":19,"t":"摩西岂不是传律法给你们吗？你们却没有一个人守律法。为什么想要杀我呢？」","notes":[]},{"n":20,"t":"众人回答说：「你是被鬼附着了！谁想要杀你？」","notes":[]},{"n":21,"t":"耶稣说：「我做了一件事，你们都以为希奇。","notes":[]},{"n":22,"t":"摩西传割礼给你们（其实不是从摩西起的，乃是从祖先起的），因此你们也在安息日给人行割礼。","notes":[]},{"n":23,"t":"人若在安息日受割礼，免得违背摩西的律法，我在安息日叫一个人全然好了，你们就向我生气吗？","notes":[]},{"n":24,"t":"不可按外貌断定是非，总要按公平断定是非。」","notes":[]},{"n":25,"t":"耶路撒冷人中有的说：「这不是他们想要杀的人吗？","notes":[],"heads":["这是基督吗？"]},{"n":26,"t":"你看他还明明地讲道，他们也不向他说什么，难道官长真知道这是基督吗？","notes":[]},{"n":27,"t":"然而，我们知道这个人从哪里来；只是基督来的时候，没有人知道他从哪里来。」","notes":[]},{"n":28,"t":"那时，耶稣在殿里教训人，大声说：「你们也知道我，也知道我从哪里来；我来并不是由于自己。但那差我来的是真的。你们不认识他，","notes":[]},{"n":29,"t":"我却认识他；因为我是从他来的，他也是差了我来。」","notes":[]},{"n":30,"t":"他们就想要捉拿耶稣；只是没有人下手，因为他的时候还没有到。","notes":[]},{"n":31,"t":"但众人中间有好些信他的，说：「基督来的时候，他所行的神迹岂能比这人所行的更多吗？」","notes":[]},{"n":32,"t":"法利赛人听见众人为耶稣这样纷纷议论，祭司长和法利赛人就打发差役去捉拿他。","notes":[],"heads":["差役捉拿耶稣"]},{"n":33,"t":"于是耶稣说：「我还有不多的时候和你们同在，以后就回到差我来的那里去。","notes":[]},{"n":34,"t":"你们要找我，却找不着；我所在的地方你们不能到。」","notes":[]},{"n":35,"t":"犹太人就彼此对问说：「这人要往哪里去，叫我们找不着呢？难道他要往散住希腊中的犹太人那里去教训希腊人吗？","notes":[]},{"n":36,"t":"他说：『你们要找我，却找不着；我所在的地方，你们不能到』，这话是什么意思呢？」","notes":[]},{"n":37,"t":"节期的末日，就是最大之日，耶稣站着高声说：「人若渴了，可以到我这里来喝。","notes":[],"heads":["活水的江河"]},{"n":38,"t":"信我的人就如经上所说：『从他腹中要流出活水的江河来。』」","notes":[]},{"n":39,"t":"耶稣这话是指着信他之人要受圣灵说的。那时还没有赐下圣灵来，因为耶稣尚未得着荣耀。","notes":[]},{"n":40,"t":"众人听见这话，有的说：「这真是那先知。」","notes":[],"heads":["群众因耶稣而纷争"]},{"n":41,"t":"有的说：「这是基督。」但也有的说：「基督岂是从加利利出来的吗？","notes":[]},{"n":42,"t":"经上岂不是说『基督是大卫的后裔，从大卫本乡伯利恒出来的』吗？」","notes":[]},{"n":43,"t":"于是众人因着耶稣起了纷争。","notes":[]},{"n":44,"t":"其中有人要捉拿他，只是无人下手。","notes":[]},{"n":45,"t":"差役回到祭司长和法利赛人那里。他们对差役说：「你们为什么没有带他来呢？」","notes":[],"heads":["犹太领袖的不信"]},{"n":46,"t":"差役回答说：「从来没有像他这样说话的！」","notes":[]},{"n":47,"t":"法利赛人说：「你们也受了迷惑吗？","notes":[]},{"n":48,"t":"官长或是法利赛人岂有信他的呢？","notes":[]},{"n":49,"t":"但这些不明白律法的百姓是被咒诅的！」","notes":[]},{"n":50,"t":"内中有尼哥德慕，就是从前去见耶稣的，对他们说：","notes":[]},{"n":51,"t":"「不先听本人的口供，不知道他所做的事，难道我们的律法还定他的罪吗？」","notes":[]},{"n":52,"t":"他们回答说：「你也是出于加利利吗？你且去查考，就可知道加利利没有出过先知。」","notes":[]}]},"8":{"heading":"行淫时被捉的女人","verses":[{"n":1,"t":"于是各人都回家去了；耶稣却往橄榄山去，","notes":[]},{"n":2,"t":"清早又回到殿里。众百姓都到他那里去，他就坐下，教训他们。","notes":[]},{"n":3,"t":"文士和法利赛人带着一个行淫时被拿的妇人来，叫她站在当中，","notes":[]},{"n":4,"t":"就对耶稣说：「夫子，这妇人是正行淫之时被拿的。","notes":[]},{"n":5,"t":"摩西在律法上吩咐我们把这样的妇人用石头打死。你说该把她怎么样呢？」","notes":[]},{"n":6,"t":"他们说这话，乃试探耶稣，要得着告他的把柄。耶稣却弯着腰，用指头在地上画字。","notes":[]},{"n":7,"t":"他们还是不住地问他，耶稣就直起腰来，对他们说：「你们中间谁是没有罪的，谁就可以先拿石头打她。」","notes":[]},{"n":8,"t":"于是又弯着腰，用指头在地上画字。","notes":[]},{"n":9,"t":"他们听见这话，就从老到少，一个一个地都出去了，只剩下耶稣一人，还有那妇人仍然站在当中。","notes":[]},{"n":10,"t":"耶稣就直起腰来，对她说：「妇人，那些人在哪里呢？没有人定你的罪吗？」","notes":[]},{"n":11,"t":"她说：「主啊，没有。」耶稣说：「我也不定你的罪。去吧，从此不要再犯罪了！」","notes":[]},{"n":12,"t":"耶稣又对众人说：「我是世界的光。跟从我的，就不在黑暗里走，必要得着生命的光。」","notes":[],"heads":["耶稣是世界的光"]},{"n":13,"t":"法利赛人对他说：「你是为自己作见证，你的见证不真。」","notes":[]},{"n":14,"t":"耶稣说：「我虽然为自己作见证，我的见证还是真的；因我知道我从哪里来，往哪里去；你们却不知道我从哪里来，往哪里去。","notes":[]},{"n":15,"t":"你们是以外貌判断人，我却不判断人。","notes":["原文是凭肉身"]},{"n":16,"t":"就是判断人，我的判断也是真的；因为不是我独自在这里，还有差我来的父与我同在。","notes":[]},{"n":17,"t":"你们的律法上也记着说：『两个人的见证是真的。』","notes":[]},{"n":18,"t":"我是为自己作见证，还有差我来的父也是为我作见证。」","notes":[]},{"n":19,"t":"他们就问他说：「你的父在哪里？」耶稣回答说：「你们不认识我，也不认识我的父；若是认识我，也就认识我的父。」","notes":[]},{"n":20,"t":"这些话是耶稣在殿里的库房、教训人时所说的，也没有人拿他，因为他的时候还没有到。","notes":[]},{"n":21,"t":"耶稣又对他们说：「我要去了，你们要找我，并且你们要死在罪中。我所去的地方，你们不能到。」","notes":[],"heads":["我所去的地方你们不能到"]},{"n":22,"t":"犹太人说：「他说『我所去的地方，你们不能到』，难道他要自尽吗？」","notes":[]},{"n":23,"t":"耶稣对他们说：「你们是从下头来的，我是从上头来的；你们是属这世界的，我不是属这世界的。","notes":[]},{"n":24,"t":"所以我对你们说，你们要死在罪中。你们若不信我是基督，必要死在罪中。」","notes":[]},{"n":25,"t":"他们就问他说：「你是谁？」耶稣对他们说：「就是我从起初所告诉你们的。","notes":[]},{"n":26,"t":"我有许多事讲论你们，判断你们；但那差我来的是真的，我在他那里所听见的，我就传给世人。」","notes":[]},{"n":27,"t":"他们不明白耶稣是指着父说的。","notes":[]},{"n":28,"t":"所以耶稣说：「你们举起人子以后，必知道我是基督，并且知道我没有一件事是凭着自己做的。我说这些话乃是照着父所教训我的。","notes":[]},{"n":29,"t":"那差我来的是与我同在；他没有撇下我独自在这里，因为我常做他所喜悦的事。」","notes":[]},{"n":30,"t":"耶稣说这话的时候，就有许多人信他。","notes":[]},{"n":31,"t":"耶稣对信他的犹太人说：「你们若常常遵守我的道，就真是我的门徒；","notes":[],"heads":["真理必使你们得自由"]},{"n":32,"t":"你们必晓得真理，真理必叫你们得以自由。」","notes":[]},{"n":33,"t":"他们回答说：「我们是亚伯拉罕的后裔，从来没有作过谁的奴仆。你怎么说『你们必得以自由』呢？」","notes":[]},{"n":34,"t":"耶稣回答说：「我实实在在地告诉你们，所有犯罪的就是罪的奴仆。","notes":[]},{"n":35,"t":"奴仆不能永远住在家里；儿子是永远住在家里。","notes":[]},{"n":36,"t":"所以天父的儿子若叫你们自由，你们就真自由了。","notes":[]},{"n":37,"t":"我知道你们是亚伯拉罕的子孙，你们却想要杀我，因为你们心里容不下我的道。","notes":[]},{"n":38,"t":"我所说的是在我父那里看见的；你们所行的是在你们的父那里听见的。」","notes":[]},{"n":39,"t":"他们说：「我们的父就是亚伯拉罕。」耶稣说：「你们若是亚伯拉罕的儿子，就必行亚伯拉罕所行的事。","notes":[],"heads":["你们的父是魔鬼"]},{"n":40,"t":"我将在神那里所听见的真理告诉了你们，现在你们却想要杀我，这不是亚伯拉罕所行的事。","notes":[]},{"n":41,"t":"你们是行你们父所行的事。」他们说：「我们不是从淫乱生的；我们只有一位父，就是神。」","notes":[]},{"n":42,"t":"耶稣说：「倘若神是你们的父，你们就必爱我；因为我本是出于神，也是从神而来，并不是由着自己来，乃是他差我来。","notes":[]},{"n":43,"t":"你们为什么不明白我的话呢？无非是因你们不能听我的道。","notes":[]},{"n":44,"t":"你们是出于你们的父魔鬼，你们父的私欲你们偏要行。他从起初是杀人的，不守真理，因他心里没有真理。他说谎是出于自己；因他本来是说谎的，也是说谎之人的父。","notes":[]},{"n":45,"t":"我将真理告诉你们，你们就因此不信我。","notes":[]},{"n":46,"t":"你们中间谁能指证我有罪呢？我既然将真理告诉你们，为什么不信我呢？","notes":[]},{"n":47,"t":"出于神的，必听神的话；你们不听，因为你们不是出于神。」","notes":[]},{"n":48,"t":"犹太人回答说：「我们说你是撒马利亚人，并且是鬼附着的，这话岂不正对吗？」","notes":[],"heads":["还没有亚伯拉罕就有了我"]},{"n":49,"t":"耶稣说：「我不是鬼附着的；我尊敬我的父，你们倒轻慢我。","notes":[]},{"n":50,"t":"我不求自己的荣耀，有一位为我求荣耀、定是非的。","notes":[]},{"n":51,"t":"我实实在在地告诉你们，人若遵守我的道，就永远不见死。」","notes":[]},{"n":52,"t":"犹太人对他说：「现在我们知道你是鬼附着的。亚伯拉罕死了，众先知也死了，你还说：『人若遵守我的道，就永远不尝死味。』","notes":[]},{"n":53,"t":"难道你比我们的祖宗亚伯拉罕还大吗？他死了，众先知也死了，你将自己当作什么人呢？」","notes":[]},{"n":54,"t":"耶稣回答说：「我若荣耀自己，我的荣耀就算不得什么；荣耀我的乃是我的父，就是你们所说是你们的神。","notes":[]},{"n":55,"t":"你们未曾认识他；我却认识他。我若说不认识他，我就是说谎的，像你们一样；但我认识他，也遵守他的道。","notes":[]},{"n":56,"t":"你们的祖宗亚伯拉罕欢欢喜喜地仰望我的日子，既看见了就快乐。」","notes":[]},{"n":57,"t":"犹太人说：「你还没有五十岁，岂见过亚伯拉罕呢？」","notes":[]},{"n":58,"t":"耶稣说：「我实实在在地告诉你们，还没有亚伯拉罕就有了我。」","notes":[]},{"n":59,"t":"于是他们拿石头要打他；耶稣却躲藏，从殿里出去了。","notes":[]}]},"9":{"heading":"治好生来瞎眼的","verses":[{"n":1,"t":"耶稣过去的时候，看见一个人生来是瞎眼的。","notes":[]},{"n":2,"t":"门徒问耶稣说：「拉比，这人生来是瞎眼的，是谁犯了罪？是这人呢？是他父母呢？」","notes":[]},{"n":3,"t":"耶稣回答说：「也不是这人犯了罪，也不是他父母犯了罪，是要在他身上显出神的作为来。","notes":[]},{"n":4,"t":"趁着白日，我们必须做那差我来者的工；黑夜将到，就没有人能做工了。","notes":[]},{"n":5,"t":"我在世上的时候，是世上的光。」","notes":[]},{"n":6,"t":"耶稣说了这话，就吐唾沫在地上，用唾沫和泥抹在瞎子的眼睛上，","notes":[]},{"n":7,"t":"对他说：「你往西罗亚池子里去洗。」（西罗亚翻出来就是「奉差遣」。）他去一洗，回头就看见了。","notes":[]},{"n":8,"t":"他的邻舍和那素常见他是讨饭的，就说：「这不是那从前坐着讨饭的人吗？」","notes":[]},{"n":9,"t":"有人说：「是他」；又有人说：「不是，却是像他。」他自己说：「是我。」","notes":[]},{"n":10,"t":"他们对他说：「你的眼睛是怎么开的呢？」","notes":[]},{"n":11,"t":"他回答说：「有一个人，名叫耶稣，他和泥抹我的眼睛，对我说：『你往西罗亚池子去洗。』我去一洗，就看见了。」","notes":[]},{"n":12,"t":"他们说：「那个人在哪里？」他说：「我不知道。」","notes":[]},{"n":13,"t":"他们把从前瞎眼的人带到法利赛人那里。","notes":[],"heads":["法利赛人盘问医治的事"]},{"n":14,"t":"耶稣和泥开他眼睛的日子是安息日。","notes":[]},{"n":15,"t":"法利赛人也问他是怎么得看见的。瞎子对他们说：「他把泥抹在我的眼睛上，我去一洗，就看见了。」","notes":[]},{"n":16,"t":"法利赛人中有的说：「这个人不是从神来的，因为他不守安息日。」又有人说：「一个罪人怎能行这样的神迹呢？」他们就起了纷争。","notes":[]},{"n":17,"t":"他们又对瞎子说：「他既然开了你的眼睛，你说他是怎样的人呢？」他说：「是个先知。」","notes":[]},{"n":18,"t":"犹太人不信他从前是瞎眼，后来能看见的，等到叫了他的父母来，","notes":[]},{"n":19,"t":"问他们说：「这是你们的儿子吗？你们说他生来是瞎眼的，如今怎么能看见了呢？」","notes":[]},{"n":20,"t":"他父母回答说：「他是我们的儿子，生来就瞎眼，这是我们知道的。","notes":[]},{"n":21,"t":"至于他如今怎么能看见，我们却不知道；是谁开了他的眼睛，我们也不知道。他已经成了人，你们问他吧，他自己必能说。」","notes":[]},{"n":22,"t":"他父母说这话，是怕犹太人；因为犹太人已经商议定了，若有认耶稣是基督的，要把他赶出会堂。","notes":[]},{"n":23,"t":"因此他父母说：「他已经成了人，你们问他吧。」","notes":[]},{"n":24,"t":"所以法利赛人第二次叫了那从前瞎眼的人来，对他说：「你该将荣耀归给神，我们知道这人是个罪人。」","notes":[]},{"n":25,"t":"他说：「他是个罪人不是，我不知道；有一件事我知道，从前我是眼瞎的，如今能看见了。」","notes":[]},{"n":26,"t":"他们就问他说：「他向你做什么？是怎么开了你的眼睛呢？」","notes":[]},{"n":27,"t":"他回答说：「我方才告诉你们，你们不听，为什么又要听呢？莫非你们也要作他的门徒吗？」","notes":[]},{"n":28,"t":"他们就骂他说：「你是他的门徒；我们是摩西的门徒。","notes":[]},{"n":29,"t":"神对摩西说话是我们知道的；只是这个人，我们不知道他从哪里来！」","notes":[]},{"n":30,"t":"那人回答说：「他开了我的眼睛，你们竟不知道他从哪里来，这真是奇怪！","notes":[]},{"n":31,"t":"我们知道神不听罪人，惟有敬奉神、遵行他旨意的，神才听他。","notes":[]},{"n":32,"t":"从创世以来，未曾听见有人把生来是瞎子的眼睛开了。","notes":[]},{"n":33,"t":"这人若不是从神来的，什么也不能做。」","notes":[]},{"n":34,"t":"他们回答说：「你全然生在罪孽中，还要教训我们吗？」于是把他赶出去了。","notes":[]},{"n":35,"t":"耶稣听说他们把他赶出去，后来遇见他，就说：「你信神的儿子吗？」","notes":[],"heads":["灵性的盲目"]},{"n":36,"t":"他回答说：「主啊，谁是神的儿子，叫我信他呢？」","notes":[]},{"n":37,"t":"耶稣说：「你已经看见他，现在和你说话的就是他。」","notes":[]},{"n":38,"t":"他说：「主啊，我信！」就拜耶稣。","notes":[]},{"n":39,"t":"耶稣说：「我为审判到这世上来，叫不能看见的，可以看见；能看见的，反瞎了眼。」","notes":[]},{"n":40,"t":"同他在那里的法利赛人听见这话，就说：「难道我们也瞎了眼吗？」","notes":[]},{"n":41,"t":"耶稣对他们说：「你们若瞎了眼，就没有罪了；但如今你们说『我们能看见』，所以你们的罪还在。」","notes":[]}]},"10":{"heading":"羊圈的比喻","verses":[{"n":1,"t":"「我实实在在地告诉你们，人进羊圈，不从门进去，倒从别处爬进去，那人就是贼，就是强盗。","notes":[]},{"n":2,"t":"从门进去的，才是羊的牧人。","notes":[]},{"n":3,"t":"看门的就给他开门；羊也听他的声音。他按着名叫自己的羊，把羊领出来。","notes":[]},{"n":4,"t":"既放出自己的羊来，就在前头走，羊也跟着他，因为认得他的声音。","notes":[]},{"n":5,"t":"羊不跟着生人；因为不认得他的声音，必要逃跑。」","notes":[]},{"n":6,"t":"耶稣将这比喻告诉他们，但他们不明白所说的是什么意思。","notes":[]},{"n":7,"t":"所以，耶稣又对他们说：「我实实在在地告诉你们，我就是羊的门。","notes":[],"heads":["好牧人耶稣"]},{"n":8,"t":"凡在我以先来的都是贼，是强盗；羊却不听他们。","notes":[]},{"n":9,"t":"我就是门；凡从我进来的，必然得救，并且出入得草吃。","notes":[]},{"n":10,"t":"盗贼来，无非要偷窃，杀害，毁坏；我来了，是要叫羊得生命，并且得的更丰盛。","notes":["或译：人"]},{"n":11,"t":"我是好牧人；好牧人为羊舍命。","notes":[]},{"n":12,"t":"若是雇工，不是牧人，羊也不是他自己的，他看见狼来，就撇下羊逃走；狼抓住羊，赶散了羊群。","notes":[]},{"n":13,"t":"雇工逃走，因他是雇工，并不顾念羊。","notes":[]},{"n":14,"t":"我是好牧人；我认识我的羊，我的羊也认识我，","notes":[]},{"n":15,"t":"正如父认识我，我也认识父一样；并且我为羊舍命。","notes":[]},{"n":16,"t":"我另外有羊，不是这圈里的；我必须领他们来，他们也要听我的声音，并且要合成一群，归一个牧人了。","notes":[]},{"n":17,"t":"我父爱我；因我将命舍去，好再取回来。","notes":[]},{"n":18,"t":"没有人夺我的命去，是我自己舍的。我有权柄舍了，也有权柄取回来。这是我从我父所受的命令。」","notes":[]},{"n":19,"t":"犹太人为这些话又起了纷争。","notes":[]},{"n":20,"t":"内中有好些人说：「他是被鬼附着，而且疯了，为什么听他呢？」","notes":[]},{"n":21,"t":"又有人说：「这不是鬼附之人所说的话。鬼岂能叫瞎子的眼睛开了呢？」","notes":[]},{"n":22,"t":"在耶路撒冷有修殿节，是冬天的时候。","notes":[],"heads":["被犹太人弃绝"]},{"n":23,"t":"耶稣在殿里所罗门的廊下行走。","notes":[]},{"n":24,"t":"犹太人围着他，说：「你叫我们犹疑不定到几时呢？你若是基督，就明明地告诉我们。」","notes":[]},{"n":25,"t":"耶稣回答说：「我已经告诉你们，你们不信。我奉我父之名所行的事可以为我作见证；","notes":[]},{"n":26,"t":"只是你们不信，因为你们不是我的羊。","notes":[]},{"n":27,"t":"我的羊听我的声音，我也认识他们，他们也跟着我。","notes":[]},{"n":28,"t":"我又赐给他们永生；他们永不灭亡，谁也不能从我手里把他们夺去。","notes":[]},{"n":29,"t":"我父把羊赐给我，他比万有都大，谁也不能从我父手里把他们夺去。","notes":[]},{"n":30,"t":"我与父原为一。」","notes":[]},{"n":31,"t":"犹太人又拿起石头来要打他。","notes":[]},{"n":32,"t":"耶稣对他们说：「我从父显出许多善事给你们看，你们是为哪一件拿石头打我呢？」","notes":[]},{"n":33,"t":"犹太人回答说：「我们不是为善事拿石头打你，是为你说僭妄的话；又为你是个人，反将自己当作神。」","notes":[]},{"n":34,"t":"耶稣说：「你们的律法上岂不是写着『我曾说你们是神』吗？","notes":[]},{"n":35,"t":"经上的话是不能废的；若那些承受神道的人尚且称为神，","notes":[]},{"n":36,"t":"父所分别为圣、又差到世间来的，他自称是神的儿子，你们还向他说『你说僭妄的话』吗？","notes":[]},{"n":37,"t":"我若不行我父的事，你们就不必信我；","notes":[]},{"n":38,"t":"我若行了，你们纵然不信我，也当信这些事，叫你们又知道又明白父在我里面，我也在父里面。」","notes":[]},{"n":39,"t":"他们又要拿他，他却逃出他们的手走了。","notes":[]},{"n":40,"t":"耶稣又往约旦河外去，到了约翰起初施洗的地方，就住在那里。","notes":[]},{"n":41,"t":"有许多人来到他那里。他们说：「约翰一件神迹没有行过，但约翰指着这人所说的一切话都是真的。」","notes":[]},{"n":42,"t":"在那里，信耶稣的人就多了。","notes":[]}]},"11":{"heading":"拉撒路的死","verses":[{"n":1,"t":"有一个患病的人，名叫拉撒路，住在伯大尼，就是马利亚和她姊姊马大的村庄。","notes":[]},{"n":2,"t":"这马利亚就是那用香膏抹主，又用头发擦他脚的；患病的拉撒路是她的兄弟。","notes":[]},{"n":3,"t":"她姊妹两个就打发人去见耶稣，说：「主啊，你所爱的人病了。」","notes":[]},{"n":4,"t":"耶稣听见，就说：「这病不至于死，乃是为神的荣耀，叫神的儿子因此得荣耀。」","notes":[]},{"n":5,"t":"耶稣素来爱马大和她妹子并拉撒路。","notes":[]},{"n":6,"t":"听见拉撒路病了，就在所居之地仍住了两天。","notes":[]},{"n":7,"t":"然后对门徒说：「我们再往犹太去吧。」","notes":[]},{"n":8,"t":"门徒说：「拉比，犹太人近来要拿石头打你，你还往那里去吗？」","notes":[]},{"n":9,"t":"耶稣回答说：「白日不是有十二小时吗？人在白日走路，就不至跌倒，因为看见这世上的光。","notes":[]},{"n":10,"t":"若在黑夜走路，就必跌倒，因为他没有光。」","notes":[]},{"n":11,"t":"耶稣说了这话，随后对他们说：「我们的朋友拉撒路睡了，我去叫醒他。」","notes":[]},{"n":12,"t":"门徒说：「主啊，他若睡了，就必好了。」","notes":[]},{"n":13,"t":"耶稣这话是指着他死说的，他们却以为是说照常睡了。","notes":[]},{"n":14,"t":"耶稣就明明地告诉他们说：「拉撒路死了。","notes":[]},{"n":15,"t":"我没有在那里就欢喜，这是为你们的缘故，好叫你们相信。如今我们可以往他那里去吧。」","notes":[]},{"n":16,"t":"多马，又称为低土马，就对那同作门徒的说：「我们也去和他同死吧。」","notes":[]},{"n":17,"t":"耶稣到了，就知道拉撒路在坟墓里已经四天了。","notes":[],"heads":["复活在我，生命在我"]},{"n":18,"t":"伯大尼离耶路撒冷不远，约有六里路。","notes":[]},{"n":19,"t":"有好些犹太人来看马大和马利亚，要为她们的兄弟安慰她们。","notes":[]},{"n":20,"t":"马大听见耶稣来了，就出去迎接他；马利亚却仍然坐在家里。","notes":[]},{"n":21,"t":"马大对耶稣说：「主啊，你若早在这里，我兄弟必不死。","notes":[]},{"n":22,"t":"就是现在，我也知道，你无论向神求什么，神也必赐给你。」","notes":[]},{"n":23,"t":"耶稣说：「你兄弟必然复活。」","notes":[]},{"n":24,"t":"马大说：「我知道在末日复活的时候，他必复活。」","notes":[]},{"n":25,"t":"耶稣对她说：「复活在我，生命也在我。信我的人虽然死了，也必复活；","notes":[]},{"n":26,"t":"凡活着信我的人必永远不死。你信这话吗？」","notes":[]},{"n":27,"t":"马大说：「主啊，是的，我信你是基督，是神的儿子，就是那要临到世界的。」","notes":[]},{"n":28,"t":"马大说了这话，就回去暗暗地叫她妹子马利亚，说：「夫子来了，叫你。」","notes":[],"heads":["耶稣哭了"]},{"n":29,"t":"马利亚听见了，就急忙起来，到耶稣那里去。","notes":[]},{"n":30,"t":"那时，耶稣还没有进村子，仍在马大迎接他的地方。","notes":[]},{"n":31,"t":"那些同马利亚在家里安慰她的犹太人，见她急忙起来出去，就跟着她，以为她要往坟墓那里去哭。","notes":[]},{"n":32,"t":"马利亚到了耶稣那里，看见他，就俯伏在他脚前，说：「主啊，你若早在这里，我兄弟必不死。」","notes":[]},{"n":33,"t":"耶稣看见她哭，并看见与她同来的犹太人也哭，就心里悲叹，又甚忧愁，","notes":[]},{"n":34,"t":"便说：「你们把他安放在哪里？」他们回答说：「请主来看。」","notes":[]},{"n":35,"t":"耶稣哭了。","notes":[]},{"n":36,"t":"犹太人就说：「你看他爱这人是何等恳切。」","notes":[]},{"n":37,"t":"其中有人说：「他既然开了瞎子的眼睛，岂不能叫这人不死吗？」","notes":[]},{"n":38,"t":"耶稣又心里悲叹，来到坟墓前；那坟墓是个洞，有一块石头挡着。","notes":[],"heads":["拉撒路复活"]},{"n":39,"t":"耶稣说：「你们把石头挪开。」那死人的姊姊马大对他说：「主啊，他现在必是臭了，因为他死了已经四天了。」","notes":[]},{"n":40,"t":"耶稣说：「我不是对你说过，你若信，就必看见神的荣耀吗？」","notes":[]},{"n":41,"t":"他们就把石头挪开。耶稣举目望天，说：「父啊，我感谢你，因为你已经听我。","notes":[]},{"n":42,"t":"我也知道你常听我，但我说这话是为周围站着的众人，叫他们信是你差了我来。」","notes":[]},{"n":43,"t":"说了这话，就大声呼叫说：「拉撒路出来！」","notes":[]},{"n":44,"t":"那死人就出来了，手脚裹着布，脸上包着手巾。耶稣对他们说：「解开，叫他走！」","notes":[]},{"n":45,"t":"那些来看马利亚的犹太人见了耶稣所做的事，就多有信他的；","notes":[],"heads":["杀害耶稣的阴谋"]},{"n":46,"t":"但其中也有去见法利赛人的，将耶稣所做的事告诉他们。","notes":[]},{"n":47,"t":"祭司长和法利赛人聚集公会，说：「这人行好些神迹，我们怎么办呢？","notes":[]},{"n":48,"t":"若这样由着他，人人都要信他，罗马人也要来夺我们的地土和我们的百姓。」","notes":[]},{"n":49,"t":"内中有一个人，名叫该亚法，本年作大祭司，对他们说：「你们不知道什么。","notes":[]},{"n":50,"t":"独不想一个人替百姓死，免得通国灭亡，就是你们的益处。」","notes":[]},{"n":51,"t":"他这话不是出于自己，是因他本年作大祭司，所以预言耶稣将要替这一国死；","notes":[]},{"n":52,"t":"也不但替这一国死，并要将神四散的子民都聚集归一。","notes":[]},{"n":53,"t":"从那日起，他们就商议要杀耶稣","notes":[]},{"n":54,"t":"所以，耶稣不再显然行在犹太人中间，就离开那里往靠近旷野的地方去，到了一座城，名叫以法莲，就在那里和门徒同住。","notes":[]},{"n":55,"t":"犹太人的逾越节近了，有许多人从乡下上耶路撒冷去，要在节前洁净自己。","notes":[]},{"n":56,"t":"他们就寻找耶稣，站在殿里彼此说：「你们的意思如何，他不来过节吗？」","notes":[]},{"n":57,"t":"那时，祭司长和法利赛人早已吩咐说，若有人知道耶稣在哪里，就要报明，好去拿他。","notes":[]}]},"12":{"heading":"在伯大尼受膏","verses":[{"n":1,"t":"逾越节前六日，耶稣来到伯大尼，就是他叫拉撒路从死里复活之处。","notes":[]},{"n":2,"t":"有人在那里给耶稣预备筵席；马大伺候，拉撒路也在那同耶稣坐席的人中。","notes":[]},{"n":3,"t":"马利亚就拿着一斤极贵的真哪哒香膏，抹耶稣的脚，又用自己头发去擦，屋里就满了膏的香气。","notes":[]},{"n":4,"t":"有一个门徒，就是那将要卖耶稣的加略人犹大，","notes":[]},{"n":5,"t":"说：「这香膏为什么不卖三十两银子周济穷人呢？」","notes":[]},{"n":6,"t":"他说这话，并不是挂念穷人，乃因他是个贼，又带着钱囊，常取其中所存的。","notes":[]},{"n":7,"t":"耶稣说：「由她吧！她是为我安葬之日存留的。","notes":[]},{"n":8,"t":"因为常有穷人和你们同在，只是你们不常有我。」","notes":[]},{"n":9,"t":"有许多犹太人知道耶稣在那里，就来了，不但是为耶稣的缘故，也是要看他从死里所复活的拉撒路。","notes":[],"heads":["杀害拉撒路的阴谋"]},{"n":10,"t":"但祭司长商议连拉撒路也要杀了；","notes":[]},{"n":11,"t":"因有好些犹太人为拉撒路的缘故，回去信了耶稣。","notes":[]},{"n":12,"t":"第二天，有许多上来过节的人听见耶稣将到耶路撒冷，","notes":[],"heads":["光荣地进耶路撒冷"]},{"n":13,"t":"就拿着棕树枝出去迎接他，喊着说：和散那！奉主名来的以色列王是应当称颂的！","notes":[]},{"n":14,"t":"耶稣得了一个驴驹，就骑上，如经上所记的说：","notes":[]},{"n":15,"t":"锡安的民哪，不要惧怕！你的王骑着驴驹来了。","notes":["原文是女子"]},{"n":16,"t":"这些事门徒起先不明白，等到耶稣得了荣耀以后才想起这话是指着他写的，并且众人果然向他这样行了。","notes":[]},{"n":17,"t":"当耶稣呼唤拉撒路，叫他从死复活出坟墓的时候，同耶稣在那里的众人就作见证。","notes":[]},{"n":18,"t":"众人因听见耶稣行了这神迹，就去迎接他。","notes":[]},{"n":19,"t":"法利赛人彼此说：「看哪，你们是徒劳无益，世人都随从他去了。」","notes":[]},{"n":20,"t":"那时，上来过节礼拜的人中，有几个希腊人。","notes":[],"heads":["希腊人求见耶稣"]},{"n":21,"t":"他们来见加利利、伯赛大的腓力，求他说：「先生，我们愿意见耶稣。」","notes":[]},{"n":22,"t":"腓力去告诉安得烈，安得烈同腓力去告诉耶稣。","notes":[]},{"n":23,"t":"耶稣说：「人子得荣耀的时候到了。","notes":[]},{"n":24,"t":"我实实在在地告诉你们，一粒麦子不落在地里死了，仍旧是一粒，若是死了，就结出许多子粒来。","notes":[]},{"n":25,"t":"爱惜自己生命的，就失丧生命；在这世上恨恶自己生命的，就要保守生命到永生。","notes":[]},{"n":26,"t":"若有人服事我，就当跟从我；我在哪里，服事我的人也要在那里；若有人服事我，我父必尊重他。」","notes":[]},{"n":27,"t":"「我现在心里忧愁，我说什么才好呢？父啊，救我脱离这时候；但我原是为这时候来的。","notes":[],"heads":["人子必须被举起来"]},{"n":28,"t":"父啊，愿你荣耀你的名！」当时就有声音从天上来，说：「我已经荣耀了我的名，还要再荣耀。」","notes":[]},{"n":29,"t":"站在旁边的众人听见，就说：「打雷了。」还有人说：「有天使对他说话。」","notes":[]},{"n":30,"t":"耶稣说：「这声音不是为我，是为你们来的。","notes":[]},{"n":31,"t":"现在这世界受审判，这世界的王要被赶出去。","notes":[]},{"n":32,"t":"我若从地上被举起来，就要吸引万人来归我。」","notes":[]},{"n":33,"t":"耶稣这话原是指着自己将要怎样死说的。","notes":[]},{"n":34,"t":"众人回答说：「我们听见律法上有话说，基督是永存的，你怎么说『人子必须被举起来』呢？这人子是谁呢？」","notes":[]},{"n":35,"t":"耶稣对他们说：「光在你们中间还有不多的时候，应当趁着有光行走，免得黑暗临到你们；那在黑暗里行走的，不知道往何处去。","notes":[]},{"n":36,"t":"你们应当趁着有光，信从这光，使你们成为光明之子。」耶稣说了这话，就离开他们隐藏了。","notes":[]},{"n":37,"t":"他虽然在他们面前行了许多神迹，他们还是不信他。","notes":[]},{"n":38,"t":"这是要应验先知以赛亚的话，说：主啊，我们所传的有谁信呢？主的膀臂向谁显露呢？","notes":[]},{"n":39,"t":"他们所以不能信，因为以赛亚又说：","notes":[]},{"n":40,"t":"主叫他们瞎了眼，硬了心，免得他们眼睛看见，心里明白，回转过来，我就医治他们。","notes":[]},{"n":41,"t":"以赛亚因为看见他的荣耀，就指着他说这话。","notes":[]},{"n":42,"t":"虽然如此，官长中却有好些信他的，只因法利赛人的缘故，就不承认，恐怕被赶出会堂。","notes":[]},{"n":43,"t":"这是因他们爱人的荣耀过于爱神的荣耀。","notes":[]},{"n":44,"t":"耶稣大声说：「信我的，不是信我，乃是信那差我来的。","notes":[],"heads":["耶稣的话要审判人"]},{"n":45,"t":"人看见我，就是看见那差我来的。","notes":[]},{"n":46,"t":"我到世上来，乃是光，叫凡信我的，不住在黑暗里。","notes":[]},{"n":47,"t":"若有人听见我的话不遵守，我不审判他。我来本不是要审判世界，乃是要拯救世界。","notes":[]},{"n":48,"t":"弃绝我、不领受我话的人，有审判他的—就是我所讲的道在末日要审判他。","notes":[]},{"n":49,"t":"因为我没有凭着自己讲，惟有差我来的父已经给我命令，叫我说什么，讲什么。","notes":[]},{"n":50,"t":"我也知道他的命令就是永生。故此，我所讲的话正是照着父对我所说的。」","notes":[]}]},"13":{"heading":"耶稣为门徒洗脚","verses":[{"n":1,"t":"逾越节以前，耶稣知道自己离世归父的时候到了。他既然爱世间属自己的人，就爱他们到底。","notes":[]},{"n":2,"t":"吃晚饭的时候，魔鬼已将卖耶稣的意思放在西门的儿子加略人犹大心里。","notes":[]},{"n":3,"t":"耶稣知道父已将万有交在他手里，且知道自己是从神出来的，又要归到神那里去，","notes":[]},{"n":4,"t":"就离席站起来，脱了衣服，拿一条手巾束腰，","notes":[]},{"n":5,"t":"随后把水倒在盆里，就洗门徒的脚，并用自己所束的手巾擦干。","notes":[]},{"n":6,"t":"挨到西门·彼得，彼得对他说：「主啊，你洗我的脚吗？」","notes":[]},{"n":7,"t":"耶稣回答说：「我所做的，你如今不知道，后来必明白。」","notes":[]},{"n":8,"t":"彼得说：「你永不可洗我的脚！」耶稣说：「我若不洗你，你就与我无分了。」","notes":[]},{"n":9,"t":"西门·彼得说：「主啊，不但我的脚，连手和头也要洗。」","notes":[]},{"n":10,"t":"耶稣说：「凡洗过澡的人，只要把脚一洗，全身就干净了。你们是干净的，然而不都是干净的。」","notes":[]},{"n":11,"t":"耶稣原知道要卖他的是谁，所以说：「你们不都是干净的。」","notes":[]},{"n":12,"t":"耶稣洗完了他们的脚，就穿上衣服，又坐下，对他们说：「我向你们所做的，你们明白吗？","notes":[]},{"n":13,"t":"你们称呼我夫子，称呼我主，你们说的不错，我本来是。","notes":[]},{"n":14,"t":"我是你们的主，你们的夫子，尚且洗你们的脚，你们也当彼此洗脚。","notes":[]},{"n":15,"t":"我给你们作了榜样，叫你们照着我向你们所做的去做。","notes":[]},{"n":16,"t":"我实实在在地告诉你们，仆人不能大于主人，差人也不能大于差他的人。","notes":[]},{"n":17,"t":"你们既知道这事，若是去行就有福了。","notes":[]},{"n":18,"t":"我这话不是指着你们众人说的，我知道我所拣选的是谁。现在要应验经上的话，说：『同我吃饭的人用脚踢我。』","notes":[]},{"n":19,"t":"如今事情还没有成就，我要先告诉你们，叫你们到事情成就的时候可以信我是基督。","notes":[]},{"n":20,"t":"我实实在在地告诉你们，有人接待我所差遣的，就是接待我；接待我，就是接待那差遣我的。」","notes":[]},{"n":21,"t":"耶稣说了这话，心里忧愁，就明说：「我实实在在地告诉你们，你们中间有一个人要卖我了。」","notes":[],"heads":["预言自己将被出卖"]},{"n":22,"t":"门徒彼此对看，猜不透所说的是谁。","notes":[]},{"n":23,"t":"有一个门徒，是耶稣所爱的，侧身挨近耶稣的怀里。","notes":[]},{"n":24,"t":"西门·彼得点头对他说：「你告诉我们，主是指着谁说的。」","notes":[]},{"n":25,"t":"那门徒便就势靠着耶稣的胸膛，问他说：「主啊，是谁呢？」","notes":[]},{"n":26,"t":"耶稣回答说：「我蘸一点饼给谁，就是谁。」耶稣就蘸了一点饼，递给加略人西门的儿子犹大。","notes":[]},{"n":27,"t":"他吃了以后，撒但就入了他的心。耶稣便对他说：「你所做的，快做吧！」","notes":[]},{"n":28,"t":"同席的人没有一个知道是为什么对他说这话。","notes":[]},{"n":29,"t":"有人因犹大带着钱囊，以为耶稣是对他说：「你去买我们过节所应用的东西」，或是叫他拿什么周济穷人。","notes":[]},{"n":30,"t":"犹大受了那点饼，立刻就出去。那时候是夜间了。","notes":[]},{"n":31,"t":"他既出去，耶稣就说：「如今人子得了荣耀，神在人子身上也得了荣耀。","notes":[],"heads":["新的命令"]},{"n":32,"t":"神要因自己荣耀人子，并且要快快地荣耀他。","notes":[]},{"n":33,"t":"小子们，我还有不多的时候与你们同在；后来你们要找我，但我所去的地方你们不能到。这话我曾对犹太人说过，如今也照样对你们说。","notes":[]},{"n":34,"t":"我赐给你们一条新命令，乃是叫你们彼此相爱；我怎样爱你们，你们也要怎样相爱。","notes":[]},{"n":35,"t":"你们若有彼此相爱的心，众人因此就认出你们是我的门徒了。」","notes":[]},{"n":36,"t":"西门·彼得问耶稣说：「主往哪里去？」耶稣回答说：「我所去的地方，你现在不能跟我去，后来却要跟我去。」","notes":[],"heads":["预言彼得不认主"]},{"n":37,"t":"彼得说：「主啊，我为什么现在不能跟你去？我愿意为你舍命！」","notes":[]},{"n":38,"t":"耶稣说：「你愿意为我舍命吗？我实实在在地告诉你，鸡叫以先，你要三次不认我。」","notes":[]}]},"14":{"heading":"耶稣是道路、真理、生命","verses":[{"n":1,"t":"「你们心里不要忧愁；你们信神，也当信我。","notes":[]},{"n":2,"t":"在我父的家里有许多住处；若是没有，我就早已告诉你们了。我去原是为你们预备地方去。","notes":[]},{"n":3,"t":"我若去为你们预备了地方，就必再来接你们到我那里去，我在哪里，叫你们也在那里。","notes":[]},{"n":4,"t":"我往哪里去，你们知道；那条路，你们也知道。」","notes":["有古卷：我往哪里去，你们知道那条路"]},{"n":5,"t":"多马对他说：「主啊，我们不知道你往哪里去，怎么知道那条路呢？」","notes":[]},{"n":6,"t":"耶稣说：「我就是道路、真理、生命；若不借着我，没有人能到父那里去。","notes":[]},{"n":7,"t":"你们若认识我，也就认识我的父。从今以后，你们认识他，并且已经看见他。」","notes":[]},{"n":8,"t":"腓力对他说：「求主将父显给我们看，我们就知足了。」","notes":[]},{"n":9,"t":"耶稣对他说：「腓力，我与你们同在这样长久，你还不认识我吗？人看见了我，就是看见了父；你怎么说『将父显给我们看』呢？","notes":[]},{"n":10,"t":"我在父里面，父在我里面，你不信吗？我对你们所说的话，不是凭着自己说的，乃是住在我里面的父做他自己的事。","notes":[]},{"n":11,"t":"你们当信我，我在父里面，父在我里面；即或不信，也当因我所做的事信我。","notes":[]},{"n":12,"t":"我实实在在地告诉你们，我所做的事，信我的人也要做，并且要做比这更大的事，因为我往父那里去。","notes":[]},{"n":13,"t":"你们奉我的名无论求什么，我必成就，叫父因儿子得荣耀。","notes":[]},{"n":14,"t":"你们若奉我的名求什么，我必成就。」","notes":[]},{"n":15,"t":"「你们若爱我，就必遵守我的命令。","notes":[],"heads":["应许赐圣灵"]},{"n":16,"t":"我要求父，父就另外赐给你们一位保惠师，叫他永远与你们同在，","notes":["或译：训慰师；下同"]},{"n":17,"t":"就是真理的圣灵，乃世人不能接受的；因为不见他，也不认识他。你们却认识他，因他常与你们同在，也要在你们里面。","notes":[]},{"n":18,"t":"我不撇下你们为孤儿，我必到你们这里来。","notes":[]},{"n":19,"t":"还有不多的时候，世人不再看见我，你们却看见我；因为我活着，你们也要活着。","notes":[]},{"n":20,"t":"到那日，你们就知道我在父里面，你们在我里面，我也在你们里面。","notes":[]},{"n":21,"t":"有了我的命令又遵守的，这人就是爱我的；爱我的必蒙我父爱他，我也要爱他，并且要向他显现。」","notes":[]},{"n":22,"t":"犹大（不是加略人犹大）问耶稣说：「主啊，为什么要向我们显现，不向世人显现呢？」","notes":[]},{"n":23,"t":"耶稣回答说：「人若爱我，就必遵守我的道；我父也必爱他，并且我们要到他那里去，与他同住。","notes":[]},{"n":24,"t":"不爱我的人就不遵守我的道。你们所听见的道不是我的，乃是差我来之父的道。","notes":[]},{"n":25,"t":"「我还与你们同住的时候，已将这些话对你们说了。","notes":[]},{"n":26,"t":"但保惠师，就是父因我的名所要差来的圣灵，他要将一切的事指教你们，并且要叫你们想起我对你们所说的一切话。","notes":[]},{"n":27,"t":"我留下平安给你们；我将我的平安赐给你们。我所赐的，不像世人所赐的。你们心里不要忧愁，也不要胆怯。","notes":[]},{"n":28,"t":"你们听见我对你们说了，我去还要到你们这里来。你们若爱我，因我到父那里去，就必喜乐，因为父是比我大的。","notes":[]},{"n":29,"t":"现在事情还没有成就，我预先告诉你们，叫你们到事情成就的时候就可以信。","notes":[]},{"n":30,"t":"以后我不再和你们多说话，因为这世界的王将到。他在我里面是毫无所有；","notes":[]},{"n":31,"t":"但要叫世人知道我爱父，并且父怎样吩咐我，我就怎样行。起来，我们走吧！」","notes":[]}]},"15":{"heading":"耶稣是真葡萄树","verses":[{"n":1,"t":"「我是真葡萄树，我父是栽培的人。","notes":[]},{"n":2,"t":"凡属我不结果子的枝子，他就剪去；凡结果子的，他就修理干净，使枝子结果子更多。","notes":[]},{"n":3,"t":"现在你们因我讲给你们的道，已经干净了。","notes":[]},{"n":4,"t":"你们要常在我里面，我也常在你们里面。枝子若不常在葡萄树上，自己就不能结果子；你们若不常在我里面，也是这样。","notes":[]},{"n":5,"t":"我是葡萄树，你们是枝子。常在我里面的，我也常在他里面，这人就多结果子；因为离了我，你们就不能做什么。","notes":[]},{"n":6,"t":"人若不常在我里面，就像枝子丢在外面枯干，人拾起来，扔在火里烧了。","notes":[]},{"n":7,"t":"你们若常在我里面，我的话也常在你们里面，凡你们所愿意的，祈求，就给你们成就。","notes":[]},{"n":8,"t":"你们多结果子，我父就因此得荣耀，你们也就是我的门徒了。","notes":[]},{"n":9,"t":"我爱你们，正如父爱我一样；你们要常在我的爱里。","notes":[]},{"n":10,"t":"你们若遵守我的命令，就常在我的爱里，正如我遵守了我父的命令，常在他的爱里。","notes":[]},{"n":11,"t":"「这些事我已经对你们说了，是要叫我的喜乐存在你们心里，并叫你们的喜乐可以满足。","notes":[]},{"n":12,"t":"你们要彼此相爱，像我爱你们一样；这就是我的命令。","notes":[]},{"n":13,"t":"人为朋友舍命，人的爱心没有比这个大的。","notes":[]},{"n":14,"t":"你们若遵行我所吩咐的，就是我的朋友了。","notes":[]},{"n":15,"t":"以后我不再称你们为仆人，因仆人不知道主人所做的事。我乃称你们为朋友；因我从我父所听见的，已经都告诉你们了。","notes":[]},{"n":16,"t":"不是你们拣选了我，是我拣选了你们，并且分派你们去结果子，叫你们的果子常存，使你们奉我的名，无论向父求什么，他就赐给你们。","notes":[]},{"n":17,"t":"我这样吩咐你们，是要叫你们彼此相爱。」","notes":[]},{"n":18,"t":"「世人若恨你们，你们知道，恨你们以先已经恨我了。","notes":["或译：该知道"],"heads":["世人的憎恨"]},{"n":19,"t":"你们若属世界，世界必爱属自己的；只因你们不属世界，乃是我从世界中拣选了你们，所以世界就恨你们。","notes":[]},{"n":20,"t":"你们要记念我从前对你们所说的话：『仆人不能大于主人。』他们若逼迫了我，也要逼迫你们；若遵守了我的话，也要遵守你们的话。","notes":[]},{"n":21,"t":"但他们因我的名要向你们行这一切的事，因为他们不认识那差我来的。","notes":[]},{"n":22,"t":"我若没有来教训他们，他们就没有罪；但如今他们的罪无可推诿了。","notes":[]},{"n":23,"t":"恨我的，也恨我的父。","notes":[]},{"n":24,"t":"我若没有在他们中间行过别人未曾行的事，他们就没有罪；但如今连我与我的父，他们也看见也恨恶了。","notes":[]},{"n":25,"t":"这要应验他们律法上所写的话，说：『他们无故地恨我。』","notes":[]},{"n":26,"t":"但我要从父那里差保惠师来，就是从父出来真理的圣灵；他来了，就要为我作见证。","notes":[]},{"n":27,"t":"你们也要作见证，因为你们从起头就与我同在。」","notes":[]}]},"16":{"heading":"圣灵的工作","verses":[{"n":1,"t":"「我已将这些事告诉你们，使你们不至于跌倒。","notes":[]},{"n":2,"t":"人要把你们赶出会堂，并且时候将到，凡杀你们的就以为是事奉神。","notes":[]},{"n":3,"t":"他们这样行，是因未曾认识父，也未曾认识我。","notes":[]},{"n":4,"t":"我将这事告诉你们，是叫你们到了时候可以想起我对你们说过了。」「我起先没有将这事告诉你们，因为我与你们同在。","notes":[]},{"n":5,"t":"现今我往差我来的父那里去，你们中间并没有人问我：『你往哪里去？』","notes":[]},{"n":6,"t":"只因我将这事告诉你们，你们就满心忧愁。","notes":[]},{"n":7,"t":"然而，我将真情告诉你们，我去是与你们有益的；我若不去，保惠师就不到你们这里来；我若去，就差他来。","notes":[]},{"n":8,"t":"他既来了，就要叫世人为罪、为义、为审判，自己责备自己。","notes":[]},{"n":9,"t":"为罪，是因他们不信我；","notes":[]},{"n":10,"t":"为义，是因我往父那里去，你们就不再见我；","notes":[]},{"n":11,"t":"为审判，是因这世界的王受了审判。","notes":[]},{"n":12,"t":"「我还有好些事要告诉你们，但你们现在担当不了。","notes":["或译：不能领会"]},{"n":13,"t":"只等真理的圣灵来了，他要引导你们明白一切的真理；因为他不是凭自己说的，乃是把他所听见的都说出来，并要把将来的事告诉你们。","notes":["原文是进入"]},{"n":14,"t":"他要荣耀我，因为他要将受于我的告诉你们。","notes":[]},{"n":15,"t":"凡父所有的，都是我的；所以我说，他要将受于我的告诉你们。」","notes":[]},{"n":16,"t":"「等不多时，你们就不得见我；再等不多时，你们还要见我。」","notes":[],"heads":["忧愁变为喜乐"]},{"n":17,"t":"有几个门徒就彼此说：「他对我们说：『等不多时，你们就不得见我；再等不多时，你们还要见我』；又说：『因我往父那里去。』这是什么意思呢？」","notes":[]},{"n":18,"t":"门徒彼此说：「他说『等不多时』到底是什么意思呢？我们不明白他所说的话。」","notes":[]},{"n":19,"t":"耶稣看出他们要问他，就说：「我说『等不多时，你们就不得见我；再等不多时，你们还要见我』，你们为这话彼此相问吗？","notes":[]},{"n":20,"t":"我实实在在地告诉你们，你们将要痛哭、哀号，世人倒要喜乐；你们将要忧愁，然而你们的忧愁要变为喜乐。","notes":[]},{"n":21,"t":"妇人生产的时候就忧愁，因为她的时候到了；既生了孩子，就不再记念那苦楚，因为欢喜世上生了一个人。","notes":[]},{"n":22,"t":"你们现在也是忧愁，但我要再见你们，你们的心就喜乐了；这喜乐也没有人能夺去。","notes":[]},{"n":23,"t":"到那日，你们什么也就不问我了。我实实在在地告诉你们，你们若向父求什么，他必因我的名赐给你们。","notes":[]},{"n":24,"t":"向来你们没有奉我的名求什么，如今你们求，就必得着，叫你们的喜乐可以满足。」","notes":[]},{"n":25,"t":"「这些事，我是用比喻对你们说的；时候将到，我不再用比喻对你们说，乃要将父明明地告诉你们。","notes":[],"heads":["我已经胜过世界"]},{"n":26,"t":"到那日，你们要奉我的名祈求；我并不对你们说，我要为你们求父。","notes":[]},{"n":27,"t":"父自己爱你们；因为你们已经爱我，又信我是从父出来的。","notes":[]},{"n":28,"t":"我从父出来，到了世界；我又离开世界，往父那里去。」","notes":[]},{"n":29,"t":"门徒说：「如今你是明说，并不用比喻了。","notes":[]},{"n":30,"t":"现在我们晓得你凡事都知道，也不用人问你，因此我们信你是从神出来的。」","notes":[]},{"n":31,"t":"耶稣说：「现在你们信吗？","notes":[]},{"n":32,"t":"看哪，时候将到，且是已经到了，你们要分散，各归自己的地方去，留下我独自一人；其实我不是独自一人，因为有父与我同在。","notes":[]},{"n":33,"t":"我将这些事告诉你们，是要叫你们在我里面有平安。在世上，你们有苦难；但你们可以放心，我已经胜了世界。」","notes":[]}]},"17":{"heading":"耶稣的祷告","verses":[{"n":1,"t":"耶稣说了这话，就举目望天，说：「父啊，时候到了，愿你荣耀你的儿子，使儿子也荣耀你；","notes":[]},{"n":2,"t":"正如你曾赐给他权柄管理凡有血气的，叫他将永生赐给你所赐给他的人。","notes":[]},{"n":3,"t":"认识你—独一的真神，并且认识你所差来的耶稣基督，这就是永生。","notes":[]},{"n":4,"t":"我在地上已经荣耀你，你所托付我的事，我已成全了。","notes":[]},{"n":5,"t":"父啊，现在求你使我同你享荣耀，就是未有世界以先，我同你所有的荣耀。","notes":[]},{"n":6,"t":"「你从世上赐给我的人，我已将你的名显明与他们。他们本是你的，你将他们赐给我，他们也遵守了你的道。","notes":[]},{"n":7,"t":"如今他们知道，凡你所赐给我的，都是从你那里来的；","notes":[]},{"n":8,"t":"因为你所赐给我的道，我已经赐给他们，他们也领受了，又确实知道，我是从你出来的，并且信你差了我来。","notes":[]},{"n":9,"t":"我为他们祈求，不为世人祈求，却为你所赐给我的人祈求，因他们本是你的。","notes":[]},{"n":10,"t":"凡是我的，都是你的；你的也是我的，并且我因他们得了荣耀。","notes":[]},{"n":11,"t":"从今以后，我不在世上，他们却在世上；我往你那里去。圣父啊，求你因你所赐给我的名保守他们，叫他们合而为一像我们一样。","notes":[]},{"n":12,"t":"我与他们同在的时候，因你所赐给我的名保守了他们，我也护卫了他们；其中除了那灭亡之子，没有一个灭亡的，好叫经上的话得应验。","notes":[]},{"n":13,"t":"现在我往你那里去，我还在世上说这话，是叫他们心里充满我的喜乐。","notes":[]},{"n":14,"t":"我已将你的道赐给他们。世界又恨他们；因为他们不属世界，正如我不属世界一样。","notes":[]},{"n":15,"t":"我不求你叫他们离开世界，只求你保守他们脱离那恶者。","notes":["或译：脱离罪恶"]},{"n":16,"t":"他们不属世界，正如我不属世界一样。","notes":[]},{"n":17,"t":"求你用真理使他们成圣；你的道就是真理。","notes":[]},{"n":18,"t":"你怎样差我到世上，我也照样差他们到世上。","notes":[]},{"n":19,"t":"我为他们的缘故，自己分别为圣，叫他们也因真理成圣。","notes":[]},{"n":20,"t":"「我不但为这些人祈求，也为那些因他们的话信我的人祈求，","notes":[]},{"n":21,"t":"使他们都合而为一。正如你父在我里面，我在你里面，使他们也在我们里面，叫世人可以信你差了我来。","notes":[]},{"n":22,"t":"你所赐给我的荣耀，我已赐给他们，使他们合而为一，像我们合而为一。","notes":[]},{"n":23,"t":"我在他们里面，你在我里面，使他们完完全全地合而为一，叫世人知道你差了我来，也知道你爱他们如同爱我一样。","notes":[]},{"n":24,"t":"父啊，我在哪里，愿你所赐给我的人也同我在那里，叫他们看见你所赐给我的荣耀；因为创立世界以前，你已经爱我了。","notes":[]},{"n":25,"t":"公义的父啊，世人未曾认识你，我却认识你；这些人也知道你差了我来。","notes":[]},{"n":26,"t":"我已将你的名指示他们，还要指示他们，使你所爱我的爱在他们里面，我也在他们里面。」","notes":[]}]},"18":{"heading":"耶稣被捕","verses":[{"n":1,"t":"耶稣说了这话，就同门徒出去，过了汲沦溪。在那里有一个园子，他和门徒进去了。","notes":[]},{"n":2,"t":"卖耶稣的犹大也知道那地方，因为耶稣和门徒屡次上那里去聚集。","notes":[]},{"n":3,"t":"犹大领了一队兵，和祭司长并法利赛人的差役，拿着灯笼、火把、兵器，就来到园里。","notes":[]},{"n":4,"t":"耶稣知道将要临到自己的一切事，就出来对他们说：「你们找谁？」","notes":[]},{"n":5,"t":"他们回答说：「找拿撒勒人耶稣。」耶稣说：「我就是！」卖他的犹大也同他们站在那里。","notes":[]},{"n":6,"t":"耶稣一说「我就是」，他们就退后倒在地上。","notes":[]},{"n":7,"t":"他又问他们说：「你们找谁？」他们说：「找拿撒勒人耶稣。」","notes":[]},{"n":8,"t":"耶稣说：「我已经告诉你们，我就是。你们若找我，就让这些人去吧。」","notes":[]},{"n":9,"t":"这要应验耶稣从前的话，说：「你所赐给我的人，我没有失落一个。」","notes":[]},{"n":10,"t":"西门·彼得带着一把刀，就拔出来，将大祭司的仆人砍了一刀，削掉他的右耳；那仆人名叫马勒古。","notes":[]},{"n":11,"t":"耶稣就对彼得说：「收刀入鞘吧，我父所给我的那杯，我岂可不喝呢？」","notes":[]},{"n":12,"t":"那队兵和千夫长，并犹太人的差役就拿住耶稣，把他捆绑了，","notes":[],"heads":["耶稣被带到亚那面前"]},{"n":13,"t":"先带到亚那面前，因为亚那是本年作大祭司该亚法的岳父。","notes":[]},{"n":14,"t":"这该亚法就是从前向犹太人发议论说「一个人替百姓死是有益的」那位。","notes":[]},{"n":15,"t":"西门·彼得跟着耶稣，还有一个门徒跟着。那门徒是大祭司所认识的，他就同耶稣进了大祭司的院子。","notes":[],"heads":["彼得不认耶稣"]},{"n":16,"t":"彼得却站在门外。大祭司所认识的那个门徒出来，和看门的使女说了一声，就领彼得进去。","notes":[]},{"n":17,"t":"那看门的使女对彼得说：「你不也是这人的门徒吗？」他说：「我不是。」","notes":[]},{"n":18,"t":"仆人和差役因为天冷，就生了炭火，站在那里烤火；彼得也同他们站着烤火。","notes":[]},{"n":19,"t":"大祭司就以耶稣的门徒和他的教训盘问他。","notes":[],"heads":["大祭司盘问耶稣"]},{"n":20,"t":"耶稣回答说：「我从来是明明地对世人说话。我常在会堂和殿里，就是犹太人聚集的地方教训人；我在暗地里并没有说什么。","notes":[]},{"n":21,"t":"你为什么问我呢？可以问那听见的人，我对他们说的是什么；我所说的，他们都知道。」","notes":[]},{"n":22,"t":"耶稣说了这话，旁边站着的一个差役用手掌打他，说：「你这样回答大祭司吗？」","notes":[]},{"n":23,"t":"耶稣说：「我若说的不是，你可以指证那不是；我若说的是，你为什么打我呢？」","notes":[]},{"n":24,"t":"亚那就把耶稣解到大祭司该亚法那里，仍是捆着解去的。","notes":[]},{"n":25,"t":"西门·彼得正站着烤火，有人对他说：「你不也是他的门徒吗？」彼得不承认，说：「我不是。」","notes":[],"heads":["彼得再次不认耶稣"]},{"n":26,"t":"有大祭司的一个仆人，是彼得削掉耳朵那人的亲属，说：「我不是看见你同他在园子里吗？」","notes":[]},{"n":27,"t":"彼得又不承认。立时鸡就叫了。","notes":[]},{"n":28,"t":"众人将耶稣从该亚法那里往衙门内解去，那时天还早。他们自己却不进衙门，恐怕染了污秽，不能吃逾越节的筵席。","notes":[],"heads":["耶稣在彼拉多面前受审"]},{"n":29,"t":"彼拉多就出来，到他们那里，说：「你们告这人是为什么事呢？」","notes":[]},{"n":30,"t":"他们回答说：「这人若不是作恶的，我们就不把他交给你。」","notes":[]},{"n":31,"t":"彼拉多说：「你们自己带他去，按着你们的律法审问他吧。」犹太人说：「我们没有杀人的权柄。」","notes":[]},{"n":32,"t":"这要应验耶稣所说自己将要怎样死的话了。","notes":[]},{"n":33,"t":"彼拉多又进了衙门，叫耶稣来，对他说：「你是犹太人的王吗？」","notes":[]},{"n":34,"t":"耶稣回答说：「这话是你自己说的，还是别人论我对你说的呢？」","notes":[]},{"n":35,"t":"彼拉多说：「我岂是犹太人呢？你本国的人和祭司长把你交给我。你做了什么事呢？」","notes":[]},{"n":36,"t":"耶稣回答说：「我的国不属这世界；我的国若属这世界，我的臣仆必要争战，使我不至于被交给犹太人。只是我的国不属这世界。」","notes":[]},{"n":37,"t":"彼拉多就对他说：「这样，你是王吗？」耶稣回答说：「你说我是王。我为此而生，也为此来到世间，特为给真理作见证。凡属真理的人就听我的话。」","notes":[]},{"n":38,"t":"彼拉多说：「真理是什么呢？」说了这话，又出来到犹太人那里，对他们说：「我查不出他有什么罪来。","notes":[]},{"n":39,"t":"但你们有个规矩，在逾越节要我给你们释放一个人，你们要我给你们释放犹太人的王吗？」","notes":[]},{"n":40,"t":"他们又喊着说：「不要这人，要巴拉巴！」这巴拉巴是个强盗。","notes":[]}]},"19":{"heading":"耶稣被钉十字架","verses":[{"n":1,"t":"当下彼拉多将耶稣鞭打了。","notes":[]},{"n":2,"t":"兵丁用荆棘编做冠冕戴在他头上，给他穿上紫袍，","notes":[]},{"n":3,"t":"又挨近他，说：「恭喜，犹太人的王啊！」他们就用手掌打他。","notes":[]},{"n":4,"t":"彼拉多又出来对众人说：「我带他出来见你们，叫你们知道我查不出他有什么罪来。」","notes":[]},{"n":5,"t":"耶稣出来，戴着荆棘冠冕，穿着紫袍。彼拉多对他们说：「你们看这个人！」","notes":[]},{"n":6,"t":"祭司长和差役看见他，就喊着说：「钉他十字架！钉他十字架！」彼拉多说：「你们自己把他钉十字架吧！我查不出他有什么罪来。」","notes":[]},{"n":7,"t":"犹太人回答说：「我们有律法，按那律法，他是该死的，因他以自己为神的儿子。」","notes":[]},{"n":8,"t":"彼拉多听见这话，越发害怕，","notes":[]},{"n":9,"t":"又进衙门，对耶稣说：「你是哪里来的？」耶稣却不回答。","notes":[]},{"n":10,"t":"彼拉多说：「你不对我说话吗？你岂不知我有权柄释放你，也有权柄把你钉十字架吗？」","notes":[]},{"n":11,"t":"耶稣回答说：「若不是从上头赐给你的，你就毫无权柄办我。所以，把我交给你的那人罪更重了。」","notes":[]},{"n":12,"t":"从此，彼拉多想要释放耶稣，无奈犹太人喊着说：「你若释放这个人，就不是凯撒的忠臣。凡以自己为王的，就是背叛凯撒了。」","notes":["原文是朋友"]},{"n":13,"t":"彼拉多听见这话，就带耶稣出来，到了一个地方，名叫「铺华石处」，希伯来话叫厄巴大，就在那里坐堂。","notes":[]},{"n":14,"t":"那日是预备逾越节的日子，约有午正。彼拉多对犹太人说：「看哪，这是你们的王！」","notes":[]},{"n":15,"t":"他们喊着说：「除掉他！除掉他！钉他在十字架上！」彼拉多说：「我可以把你们的王钉十字架吗？」祭司长回答说：「除了凯撒，我们没有王。」","notes":[]},{"n":16,"t":"于是彼拉多将耶稣交给他们去钉十字架。","notes":[]},{"n":17,"t":"他们就把耶稣带了去。耶稣背着自己的十字架出来，到了一个地方，名叫「髑髅地」，希伯来话叫各各他。","notes":[]},{"n":18,"t":"他们就在那里钉他在十字架上，还有两个人和他一同钉着，一边一个，耶稣在中间。","notes":[]},{"n":19,"t":"彼拉多又用牌子写了一个名号，安在十字架上，写的是：「犹太人的王，拿撒勒人耶稣。」","notes":[]},{"n":20,"t":"有许多犹太人念这名号；因为耶稣被钉十字架的地方与城相近，并且是用希伯来、罗马、希腊三样文字写的。","notes":[]},{"n":21,"t":"犹太人的祭司长就对彼拉多说：「不要写『犹太人的王』，要写『他自己说：我是犹太人的王』。」","notes":[]},{"n":22,"t":"彼拉多说：「我所写的，我已经写上了。」","notes":[]},{"n":23,"t":"兵丁既然将耶稣钉在十字架上，就拿他的衣服分为四分，每兵一分；又拿他的里衣，这件里衣原来没有缝儿，是上下一片织成的。","notes":[]},{"n":24,"t":"他们就彼此说：「我们不要撕开，只要拈阄，看谁得着。」这要应验经上的话说：他们分了我的外衣，为我的里衣拈阄。兵丁果然做了这事。","notes":[]},{"n":25,"t":"站在耶稣十字架旁边的，有他母亲与他母亲的姊妹，并革罗罢的妻子马利亚，和抹大拉的马利亚。","notes":[]},{"n":26,"t":"耶稣见母亲和他所爱的那门徒站在旁边，就对他母亲说：「母亲，看，你的儿子！」","notes":["原文是妇人"]},{"n":27,"t":"又对那门徒说：「看，你的母亲！」从此，那门徒就接她到自己家里去了。","notes":[]},{"n":28,"t":"这事以后，耶稣知道各样的事已经成了，为要使经上的话应验，就说：「我渴了。」","notes":[],"heads":["耶稣的死"]},{"n":29,"t":"有一个器皿盛满了醋，放在那里；他们就拿海绒蘸满了醋，绑在牛膝草上，送到他口。","notes":[]},{"n":30,"t":"耶稣尝了那醋，就说：「成了！」便低下头，将灵魂交付神了。","notes":["原文是受"]},{"n":31,"t":"犹太人因这日是预备日，又因那安息日是个大日，就求彼拉多叫人打断他们的腿，把他们拿去，免得尸首当安息日留在十字架上。","notes":[],"heads":["肋旁被扎"]},{"n":32,"t":"于是兵丁来，把头一个人的腿，并与耶稣同钉第二个人的腿，都打断了。","notes":[]},{"n":33,"t":"只是来到耶稣那里，见他已经死了，就不打断他的腿。","notes":[]},{"n":34,"t":"惟有一个兵拿枪扎他的肋旁，随即有血和水流出来。","notes":[]},{"n":35,"t":"看见这事的那人就作见证—他的见证也是真的，并且他知道自己所说的是真的—叫你们也可以信。","notes":[]},{"n":36,"t":"这些事成了，为要应验经上的话说：「他的骨头一根也不可折断。」","notes":[]},{"n":37,"t":"经上又有一句说：「他们要仰望自己所扎的人。」","notes":[]},{"n":38,"t":"这些事以后，有亚利马太人约瑟，是耶稣的门徒，只因怕犹太人，就暗暗地作门徒。他来求彼拉多，要把耶稣的身体领去。彼拉多允准，他就把耶稣的身体领去了。","notes":[],"heads":["耶稣的安葬"]},{"n":39,"t":"又有尼哥德慕，就是先前夜里去见耶稣的，带着没药和沉香约有一百斤前来。","notes":[]},{"n":40,"t":"他们就照犹太人殡葬的规矩，把耶稣的身体用细麻布加上香料裹好了。","notes":[]},{"n":41,"t":"在耶稣钉十字架的地方有一个园子，园子里有一座新坟墓，是从来没有葬过人的。","notes":[]},{"n":42,"t":"只因是犹太人的预备日，又因那坟墓近，他们就把耶稣安放在那里。","notes":[]}]},"20":{"heading":"耶稣复活","verses":[{"n":1,"t":"七日的第一日清早，天还黑的时候，抹大拉的马利亚来到坟墓那里，看见石头从坟墓挪开了，","notes":[]},{"n":2,"t":"就跑来见西门·彼得和耶稣所爱的那个门徒，对他们说：「有人把主从坟墓里挪了去，我们不知道放在哪里。」","notes":[]},{"n":3,"t":"彼得和那门徒就出来，往坟墓那里去。","notes":[]},{"n":4,"t":"两个人同跑，那门徒比彼得跑得更快，先到了坟墓，","notes":[]},{"n":5,"t":"低头往里看，就见细麻布还放在那里，只是没有进去。","notes":[]},{"n":6,"t":"西门·彼得随后也到了，进坟墓里去，就看见细麻布还放在那里，","notes":[]},{"n":7,"t":"又看见耶稣的裹头巾没有和细麻布放在一处，是另在一处卷着。","notes":[]},{"n":8,"t":"先到坟墓的那门徒也进去，看见就信了。（","notes":[]},{"n":9,"t":"因为他们还不明白圣经的意思，就是耶稣必要从死里复活。）","notes":[]},{"n":10,"t":"于是两个门徒回自己的住处去了。","notes":[]},{"n":11,"t":"马利亚却站在坟墓外面哭。哭的时候，低头往坟墓里看，","notes":[],"heads":["向抹大拉的马利亚显现"]},{"n":12,"t":"就见两个天使，穿着白衣，在安放耶稣身体的地方坐着，一个在头，一个在脚。","notes":[]},{"n":13,"t":"天使对她说：「妇人，你为什么哭？」她说：「因为有人把我主挪了去，我不知道放在哪里。」","notes":[]},{"n":14,"t":"说了这话，就转过身来，看见耶稣站在那里，却不知道是耶稣。","notes":[]},{"n":15,"t":"耶稣问她说：「妇人，为什么哭？你找谁呢？」马利亚以为是看园的，就对他说：「先生，若是你把他移了去，请告诉我，你把他放在哪里，我便去取他。」","notes":[]},{"n":16,"t":"耶稣说：「马利亚。」马利亚就转过来，用希伯来话对他说：「拉波尼！」（拉波尼就是夫子的意思。）","notes":[]},{"n":17,"t":"耶稣说：「不要摸我，因我还没有升上去见我的父。你往我弟兄那里去，告诉他们说，我要升上去见我的父，也是你们的父，见我的神，也是你们的神。」","notes":[]},{"n":18,"t":"抹大拉的马利亚就去告诉门徒说：「我已经看见了主。」她又将主对她说的这话告诉他们。","notes":[]},{"n":19,"t":"那日（就是七日的第一日）晚上，门徒所在的地方，因怕犹太人，门都关了。耶稣来，站在当中，对他们说：「愿你们平安！」","notes":[],"heads":["向门徒显现"]},{"n":20,"t":"说了这话，就把手和肋旁指给他们看。门徒看见主，就喜乐了。","notes":[]},{"n":21,"t":"耶稣又对他们说：「愿你们平安！父怎样差遣了我，我也照样差遣你们。」","notes":[]},{"n":22,"t":"说了这话，就向他们吹一口气，说：「你们受圣灵！","notes":[]},{"n":23,"t":"你们赦免谁的罪，谁的罪就赦免了；你们留下谁的罪，谁的罪就留下了。」","notes":[]},{"n":24,"t":"那十二个门徒中，有称为低土马的多马；耶稣来的时候，他没有和他们同在。","notes":[],"heads":["耶稣和多马"]},{"n":25,"t":"那些门徒就对他说：「我们已经看见主了。」多马却说：「我非看见他手上的钉痕，用指头探入那钉痕，又用手探入他的肋旁，我总不信。」","notes":[]},{"n":26,"t":"过了八日，门徒又在屋里，多马也和他们同在，门都关了。耶稣来，站在当中说：「愿你们平安！」","notes":[]},{"n":27,"t":"就对多马说：「伸过你的指头来，摸我的手；伸出你的手来，探入我的肋旁。不要疑惑，总要信！」","notes":["原文是看"]},{"n":28,"t":"多马说：「我的主！我的神！」","notes":[]},{"n":29,"t":"耶稣对他说：「你因看见了我才信；那没有看见就信的有福了。」","notes":[]},{"n":30,"t":"耶稣在门徒面前另外行了许多神迹，没有记在这书上。","notes":[],"heads":["本书的目的"]},{"n":31,"t":"但记这些事要叫你们信耶稣是基督，是神的儿子，并且叫你们信了他，就可以因他的名得生命。","notes":[]}]},"21":{"heading":"耶稣向七个门徒显现","verses":[{"n":1,"t":"这些事以后，耶稣在提比哩亚海边又向门徒显现。他怎样显现记在下面：","notes":[]},{"n":2,"t":"有西门·彼得和称为低土马的多马，并加利利的迦拿人拿但业，还有西庇太的两个儿子，又有两个门徒，都在一处。","notes":[]},{"n":3,"t":"西门·彼得对他们说：「我打鱼去。」他们说：「我们也和你同去。」他们就出去，上了船；那一夜并没有打着什么。","notes":[]},{"n":4,"t":"天将亮的时候，耶稣站在岸上，门徒却不知道是耶稣。","notes":[]},{"n":5,"t":"耶稣就对他们说：「小子！你们有吃的没有？」他们回答说：「没有。」","notes":[]},{"n":6,"t":"耶稣说：「你们把网撒在船的右边，就必得着。」他们便撒下网去，竟拉不上来了，因为鱼甚多。","notes":[]},{"n":7,"t":"耶稣所爱的那门徒对彼得说：「是主！」那时西门·彼得赤着身子，一听见是主，就束上一件外衣，跳在海里。","notes":[]},{"n":8,"t":"其余的门徒离岸不远，约有二百肘，就在小船上把那网鱼拉过来。","notes":["古时以肘为尺，一肘约有今时尺半"]},{"n":9,"t":"他们上了岸，就看见那里有炭火，上面有鱼，又有饼。","notes":[]},{"n":10,"t":"耶稣对他们说：「把刚才打的鱼拿几条来。」","notes":[]},{"n":11,"t":"西门·彼得就去，把网拉到岸上。那网满了大鱼，共一百五十三条；鱼虽这样多，网却没有破。","notes":["或译：上船"]},{"n":12,"t":"耶稣说：「你们来吃早饭。」门徒中没有一个敢问他：「你是谁？」因为知道是主。","notes":[]},{"n":13,"t":"耶稣就来拿饼和鱼给他们。","notes":[]},{"n":14,"t":"耶稣从死里复活以后，向门徒显现，这是第三次。","notes":[]},{"n":15,"t":"他们吃完了早饭，耶稣对西门·彼得说：「约翰的儿子西门，你爱我比这些更深吗？」彼得说：「主啊，是的，你知道我爱你。」耶稣对他说：「你喂养我的小羊。」","notes":["在马太十六章十七节称约拿"],"heads":["耶稣和彼得"]},{"n":16,"t":"耶稣第二次又对他说：「约翰的儿子西门，你爱我吗？」彼得说：「主啊，是的，你知道我爱你。」耶稣说：「你牧养我的羊。」","notes":[]},{"n":17,"t":"第三次对他说：「约翰的儿子西门，你爱我吗？」彼得因为耶稣第三次对他说「你爱我吗」，就忧愁，对耶稣说：「主啊，你是无所不知的；你知道我爱你。」耶稣说：「你喂养我的羊。","notes":[]},{"n":18,"t":"我实实在在地告诉你，你年少的时候，自己束上带子，随意往来；但年老的时候，你要伸出手来，别人要把你束上，带你到不愿意去的地方。」","notes":[]},{"n":19,"t":"（耶稣说这话是指着彼得要怎样死，荣耀神。）说了这话，就对他说：「你跟从我吧！」","notes":[]},{"n":20,"t":"彼得转过来，看见耶稣所爱的那门徒跟着，（就是在晚饭的时候，靠着耶稣胸膛说：「主啊，卖你的是谁？」的那门徒。）","notes":[],"heads":["耶稣和他所爱的那门徒"]},{"n":21,"t":"彼得看见他，就问耶稣说：「主啊，这人将来如何？」","notes":[]},{"n":22,"t":"耶稣对他说：「我若要他等到我来的时候，与你何干？你跟从我吧！」","notes":[]},{"n":23,"t":"于是这话传在弟兄中间，说那门徒不死。其实，耶稣不是说他不死，乃是说：「我若要他等到我来的时候，与你何干？」","notes":[]},{"n":24,"t":"为这些事作见证，并且记载这些事的就是这门徒；我们也知道他的见证是真的。","notes":[]},{"n":25,"t":"耶稣所行的事还有许多，若是一一地都写出来，我想，所写的书就是世界也容不下了。","notes":[]}]}},"ACT":{"1":{"heading":"赐圣灵的应许","verses":[{"n":1,"t":"提阿非罗啊，我已经作了前书，论到耶稣开头一切所行所教训的，","notes":[]},{"n":2,"t":"直到他借着圣灵吩咐所拣选的使徒，以后被接上升的日子为止。","notes":[]},{"n":3,"t":"他受害之后，用许多的凭据将自己活活地显给使徒看，四十天之久向他们显现，讲说神国的事。","notes":[]},{"n":4,"t":"耶稣和他们聚集的时候，嘱咐他们说：「不要离开耶路撒冷，要等候父所应许的，就是你们听见我说过的。","notes":[]},{"n":5,"t":"约翰是用水施洗，但不多几日，你们要受圣灵的洗。」","notes":[]},{"n":6,"t":"他们聚集的时候，问耶稣说：「主啊，你复兴以色列国就在这时候吗？」","notes":[],"heads":["耶稣升天"]},{"n":7,"t":"耶稣对他们说：「父凭着自己的权柄所定的时候、日期，不是你们可以知道的。","notes":[]},{"n":8,"t":"但圣灵降临在你们身上，你们就必得着能力，并要在耶路撒冷、犹太全地，和撒马利亚，直到地极，作我的见证。」","notes":[]},{"n":9,"t":"说了这话，他们正看的时候，他就被取上升，有一朵云彩把他接去，便看不见他了。","notes":[]},{"n":10,"t":"当他往上去，他们定睛望天的时候，忽然有两个人身穿白衣，站在旁边，说：","notes":[]},{"n":11,"t":"「加利利人哪，你们为什么站着望天呢？这离开你们被接升天的耶稣，你们见他怎样往天上去，他还要怎样来。」","notes":[]},{"n":12,"t":"有一座山，名叫橄榄山，离耶路撒冷不远，约有安息日可走的路程。当下，门徒从那里回耶路撒冷去，","notes":[],"heads":["接替犹大职分的人"]},{"n":13,"t":"进了城，就上了所住的一间楼房；在那里有彼得、约翰、雅各、安得烈、腓力、多马、巴多罗买、马太、亚勒腓的儿子雅各、奋锐党的西门，和雅各的儿子犹大。","notes":["或译：兄弟"]},{"n":14,"t":"这些人同着几个妇人和耶稣的母亲马利亚，并耶稣的弟兄，都同心合意地恒切祷告。","notes":[]},{"n":15,"t":"那时，有许多人聚会，约有一百二十名，彼得就在弟兄中间站起来，","notes":[]},{"n":16,"t":"说：「弟兄们！圣灵借大卫的口，在圣经上预言领人捉拿耶稣的犹大，这话是必须应验的。","notes":[]},{"n":17,"t":"他本来列在我们数中，并且在使徒的职任上得了一分。","notes":[]},{"n":18,"t":"这人用他作恶的工价买了一块田，以后身子仆倒，肚腹崩裂，肠子都流出来。","notes":[]},{"n":19,"t":"住在耶路撒冷的众人都知道这事，所以按着他们那里的话给那块田起名叫亚革大马，就是「血田」的意思。","notes":[]},{"n":20,"t":"因为诗篇上写着，说：愿他的住处变为荒场，无人在内居住；又说：愿别人得他的职分。","notes":[]},{"n":21,"t":"所以，主耶稣在我们中间始终出入的时候，","notes":[]},{"n":22,"t":"就是从约翰施洗起，直到主离开我们被接上升的日子为止，必须从那常与我们作伴的人中立一位与我们同作耶稣复活的见证。」","notes":[]},{"n":23,"t":"于是选举两个人，就是那叫做巴撒巴，又称呼犹士都的约瑟，和马提亚。","notes":[]},{"n":24,"t":"众人就祷告说：「主啊，你知道万人的心，求你从这两个人中，指明你所拣选的是谁，叫他得这使徒的位分。这位分犹大已经丢弃，往自己的地方去了。」","notes":[],"end":25},{"n":26,"t":"于是众人为他们摇签，摇出马提亚来；他就和十一个使徒同列。","notes":[]}]},"2":{"heading":"圣灵降临","verses":[{"n":1,"t":"五旬节到了，门徒都聚集在一处。","notes":[]},{"n":2,"t":"忽然，从天上有响声下来，好像一阵大风吹过，充满了他们所坐的屋子，","notes":[]},{"n":3,"t":"又有舌头如火焰显现出来，分开落在他们各人头上。","notes":[]},{"n":4,"t":"他们就都被圣灵充满，按着圣灵所赐的口才说起别国的话来。","notes":[]},{"n":5,"t":"那时，有虔诚的犹太人从天下各国来，住在耶路撒冷。","notes":[]},{"n":6,"t":"这声音一响，众人都来聚集，各人听见门徒用众人的乡谈说话，就甚纳闷；","notes":[]},{"n":7,"t":"都惊讶希奇说：「看哪，这说话的不都是加利利人吗？","notes":[]},{"n":8,"t":"我们各人怎么听见他们说我们生来所用的乡谈呢？","notes":[]},{"n":9,"t":"我们帕提亚人、米底亚人、以拦人，和住在美索不达米亚、犹太、加帕多家、本都、亚细亚、","notes":[]},{"n":10,"t":"弗吕家、旁非利亚、埃及的人，并靠近古利奈的利比亚一带地方的人，从罗马来的客旅中，或是犹太人，或是进犹太教的人，","notes":[]},{"n":11,"t":"克里特和阿拉伯人，都听见他们用我们的乡谈，讲说神的大作为。」","notes":[]},{"n":12,"t":"众人就都惊讶猜疑，彼此说：「这是什么意思呢？」","notes":[]},{"n":13,"t":"还有人讥诮说：「他们无非是新酒灌满了。」","notes":[]},{"n":14,"t":"彼得和十一个使徒站起，高声说：「犹太人和一切住在耶路撒冷的人哪，这件事你们当知道，也当侧耳听我的话。","notes":[],"heads":["彼得在五旬节的讲论"]},{"n":15,"t":"你们想这些人是醉了；其实不是醉了，因为时候刚到巳初。","notes":[]},{"n":16,"t":"这正是先知约珥所说的：","notes":[]},{"n":17,"t":"神说：在末后的日子，我要将我的灵浇灌凡有血气的。你们的儿女要说预言；你们的少年人要见异象；老年人要做异梦。","notes":[]},{"n":18,"t":"在那些日子，我要将我的灵浇灌我的仆人和使女，他们就要说预言。","notes":[]},{"n":19,"t":"在天上，我要显出奇事；在地下，我要显出神迹；有血，有火，有烟雾。","notes":[]},{"n":20,"t":"日头要变为黑暗，月亮要变为血；这都在主大而明显的日子未到以前。","notes":[]},{"n":21,"t":"到那时候，凡求告主名的，就必得救。","notes":[]},{"n":22,"t":"「以色列人哪，请听我的话：神借着拿撒勒人耶稣在你们中间施行异能、奇事、神迹，将他证明出来，这是你们自己知道的。","notes":[]},{"n":23,"t":"他既按着神的定旨先见被交与人，你们就借着无法之人的手，把他钉在十字架上，杀了。","notes":[]},{"n":24,"t":"神却将死的痛苦解释了，叫他复活，因为他原不能被死拘禁。","notes":[]},{"n":25,"t":"大卫指着他说：我看见主常在我眼前；他在我右边，叫我不至于摇动。","notes":[]},{"n":26,"t":"所以，我心里欢喜，我的灵快乐；并且我的肉身要安居在指望中。","notes":["原文是舌"]},{"n":27,"t":"因你必不将我的灵魂撇在阴间，也不叫你的圣者见朽坏。","notes":[]},{"n":28,"t":"你已将生命的道路指示我，必叫我因见你的面得着满足的快乐。","notes":["或译：叫我在你面前"]},{"n":29,"t":"「弟兄们！先祖大卫的事，我可以明明地对你们说：他死了，也葬埋了，并且他的坟墓直到今日还在我们这里。","notes":[]},{"n":30,"t":"大卫既是先知，又晓得神曾向他起誓，要从他的后裔中立一位坐在他的宝座上，","notes":[]},{"n":31,"t":"就预先看明这事，讲论基督复活说：他的灵魂不撇在阴间；他的肉身也不见朽坏。","notes":[]},{"n":32,"t":"这耶稣，神已经叫他复活了，我们都为这事作见证。","notes":[]},{"n":33,"t":"他既被神的右手高举，又从父受了所应许的圣灵，就把你们所看见所听见的，浇灌下来。","notes":["或译：他既高举在神的右边"]},{"n":34,"t":"大卫并没有升到天上，但自己说：主对我主说：你坐在我的右边，","notes":[]},{"n":35,"t":"等我使你仇敌作你的脚凳。","notes":[]},{"n":36,"t":"「故此，以色列全家当确实地知道，你们钉在十字架上的这位耶稣，神已经立他为主，为基督了。」","notes":[]},{"n":37,"t":"众人听见这话，觉得扎心，就对彼得和其余的使徒说：「弟兄们，我们当怎样行？」","notes":[]},{"n":38,"t":"彼得说：「你们各人要悔改，奉耶稣基督的名受洗，叫你们的罪得赦，就必领受所赐的圣灵；","notes":[]},{"n":39,"t":"因为这应许是给你们和你们的儿女，并一切在远方的人，就是主—我们神所召来的。」","notes":[]},{"n":40,"t":"彼得还用许多话作见证，劝勉他们说：「你们当救自己脱离这弯曲的世代。」","notes":[]},{"n":41,"t":"于是领受他话的人就受了洗。那一天，门徒约添了三千人，","notes":[]},{"n":42,"t":"都恒心遵守使徒的教训，彼此交接，擘饼，祈祷。","notes":[]},{"n":43,"t":"众人都惧怕；使徒又行了许多奇事神迹。","notes":[],"heads":["在圣徒中间的生活"]},{"n":44,"t":"信的人都在一处，凡物公用，","notes":[]},{"n":45,"t":"并且卖了田产、家业，照各人所需用的分给各人。","notes":[]},{"n":46,"t":"他们天天同心合意恒切地在殿里，且在家中擘饼，存着欢喜、诚实的心用饭，","notes":[]},{"n":47,"t":"赞美神，得众民的喜爱。主将得救的人天天加给他们。","notes":[]}]},"3":{"heading":"圣殿门口的瘸腿者得医治","verses":[{"n":1,"t":"申初祷告的时候，彼得、约翰上圣殿去。","notes":[]},{"n":2,"t":"有一个人，生来是瘸腿的，天天被人抬来，放在殿的一个门口（那门名叫美门），要求进殿的人周济。","notes":[]},{"n":3,"t":"他看见彼得、约翰将要进殿，就求他们周济。","notes":[]},{"n":4,"t":"彼得、约翰定睛看他；彼得说：「你看我们！」","notes":[]},{"n":5,"t":"那人就留意看他们，指望得着什么。","notes":[]},{"n":6,"t":"彼得说：「金银我都没有，只把我所有的给你：我奉拿撒勒人耶稣基督的名，叫你起来行走！」","notes":[]},{"n":7,"t":"于是拉着他的右手，扶他起来；他的脚和踝子骨立刻健壮了，","notes":[]},{"n":8,"t":"就跳起来，站着，又行走，同他们进了殿，走着，跳着，赞美神。","notes":[]},{"n":9,"t":"百姓都看见他行走，赞美神；","notes":[]},{"n":10,"t":"认得他是那素常坐在殿的美门口求周济的，就因他所遇着的事满心希奇、惊讶。","notes":[]},{"n":11,"t":"那人正在称为所罗门的廊下，拉着彼得、约翰；众百姓一齐跑到他们那里，很觉希奇。","notes":[],"heads":["彼得在所罗门廊下的讲论"]},{"n":12,"t":"彼得看见，就对百姓说：「以色列人哪，为什么把这事当作希奇呢？为什么定睛看我们，以为我们凭自己的能力和虔诚使这人行走呢？","notes":[]},{"n":13,"t":"亚伯拉罕、以撒、雅各的神，就是我们列祖的神，已经荣耀了他的仆人耶稣；你们却把他交付彼拉多。彼拉多定意要释放他，你们竟在彼拉多面前弃绝了他。","notes":["或译：儿子"]},{"n":14,"t":"你们弃绝了那圣洁公义者，反求着释放一个凶手给你们。","notes":[]},{"n":15,"t":"你们杀了那生命的主，神却叫他从死里复活了；我们都是为这事作见证。","notes":[]},{"n":16,"t":"我们因信他的名，他的名便叫你们所看见所认识的这人健壮了；正是他所赐的信心，叫这人在你们众人面前全然好了。","notes":[]},{"n":17,"t":"弟兄们，我晓得你们做这事是出于不知，你们的官长也是如此。","notes":[]},{"n":18,"t":"但神曾借众先知的口，预言基督将要受害，就这样应验了。","notes":[]},{"n":19,"t":"所以，你们当悔改归正，使你们的罪得以涂抹，","notes":[]},{"n":20,"t":"这样，那安舒的日子就必从主面前来到；主也必差遣所预定给你们的基督（耶稣）降临。","notes":[]},{"n":21,"t":"天必留他，等到万物复兴的时候，就是神从创世以来、借着圣先知的口所说的。","notes":[]},{"n":22,"t":"摩西曾说：『主—神要从你们弟兄中间给你们兴起一位先知像我，凡他向你们所说的，你们都要听从。","notes":[]},{"n":23,"t":"凡不听从那先知的，必要从民中全然灭绝。』","notes":[]},{"n":24,"t":"从撒母耳以来的众先知，凡说预言的，也都说到这些日子。","notes":[]},{"n":25,"t":"你们是先知的子孙，也承受神与你们祖宗所立的约，就是对亚伯拉罕说：『地上万族都要因你的后裔得福。』","notes":[]},{"n":26,"t":"神既兴起他的仆人，就先差他到你们这里来，赐福给你们，叫你们各人回转，离开罪恶。」","notes":["或译：儿子"]}]},"4":{"heading":"彼得、约翰在公会被查问","verses":[{"n":1,"t":"使徒对百姓说话的时候，祭司们和守殿官，并撒都该人忽然来了。","notes":[]},{"n":2,"t":"因他们教训百姓，本着耶稣，传说死人复活，就很烦恼，","notes":[]},{"n":3,"t":"于是下手拿住他们；因为天已经晚了，就把他们押到第二天。","notes":[]},{"n":4,"t":"但听道之人有许多信的，男丁数目约到五千。","notes":[]},{"n":5,"t":"第二天，官府、长老，和文士在耶路撒冷聚会，","notes":[]},{"n":6,"t":"又有大祭司亚那和该亚法、约翰、亚历山大，并大祭司的亲族都在那里，","notes":[]},{"n":7,"t":"叫使徒站在当中，就问他们说：「你们用什么能力，奉谁的名做这事呢？」","notes":[]},{"n":8,"t":"那时彼得被圣灵充满，对他们说：","notes":[]},{"n":9,"t":"「治民的官府和长老啊，倘若今日因为在残疾人身上所行的善事查问我们他是怎么得了痊愈，","notes":[]},{"n":10,"t":"你们众人和以色列百姓都当知道，站在你们面前的这人得痊愈是因你们所钉十字架、神叫他从死里复活的拿撒勒人耶稣基督的名。","notes":[]},{"n":11,"t":"他是你们匠人所弃的石头，已成了房角的头块石头。","notes":[]},{"n":12,"t":"除他以外，别无拯救；因为在天下人间，没有赐下别的名，我们可以靠着得救。」","notes":[]},{"n":13,"t":"他们见彼得、约翰的胆量，又看出他们原是没有学问的小民，就希奇，认明他们是跟过耶稣的；","notes":[]},{"n":14,"t":"又看见那治好了的人和他们一同站着，就无话可驳。","notes":[]},{"n":15,"t":"于是吩咐他们从公会出去，就彼此商议说：","notes":[]},{"n":16,"t":"「我们当怎样办这两个人呢？因为他们诚然行了一件明显的神迹，凡住耶路撒冷的人都知道，我们也不能说没有。","notes":[]},{"n":17,"t":"惟恐这事越发传扬在民间，我们必须恐吓他们，叫他们不再奉这名对人讲论。」","notes":[]},{"n":18,"t":"于是叫了他们来，禁止他们总不可奉耶稣的名讲论教训人。","notes":[]},{"n":19,"t":"彼得、约翰说：「听从你们，不听从神，这在神面前合理不合理，你们自己酌量吧！","notes":[]},{"n":20,"t":"我们所看见所听见的，不能不说。」","notes":[]},{"n":21,"t":"官长为百姓的缘故，想不出法子刑罚他们，又恐吓一番，把他们释放了。这是因众人为所行的奇事都归荣耀与神。","notes":[]},{"n":22,"t":"原来借着神迹医好的那人有四十多岁了。","notes":[]},{"n":23,"t":"二人既被释放，就到会友那里去，把祭司长和长老所说的话都告诉他们。","notes":[],"heads":["门徒求主赐胆量"]},{"n":24,"t":"他们听见了，就同心合意地高声向神说：「主啊！你是造天、地、海，和其中万物的，","notes":[]},{"n":25,"t":"你曾借着圣灵，托你仆人—我们祖宗大卫的口，说：外邦为什么争闹？万民为什么谋算虚妄的事？","notes":[]},{"n":26,"t":"世上的君王一齐起来，臣宰也聚集，要敌挡主，并主的受膏者。","notes":["或译：基督"]},{"n":27,"t":"希律和本丢·彼拉多，外邦人和以色列民，果然在这城里聚集，要攻打你所膏的圣仆耶稣，","notes":["仆：或译子"]},{"n":28,"t":"成就你手和你意旨所预定必有的事。","notes":[]},{"n":29,"t":"他们恐吓我们，现在求主鉴察，一面叫你仆人大放胆量讲你的道，一面伸出你的手来医治疾病，并且使神迹奇事因着你圣仆耶稣的名行出来。」","notes":["仆：或译子"],"end":30},{"n":31,"t":"祷告完了，聚会的地方震动，他们就都被圣灵充满，放胆讲论神的道。","notes":[]},{"n":32,"t":"那许多信的人都是一心一意的，没有一人说他的东西有一样是自己的，都是大家公用。","notes":[],"heads":["凡物公用"]},{"n":33,"t":"使徒大有能力，见证主耶稣复活；众人也都蒙大恩。","notes":[]},{"n":34,"t":"内中也没有一个缺乏的；因为人人将田产房屋都卖了，把所卖的价银拿来，","notes":[]},{"n":35,"t":"放在使徒脚前，照各人所需用的，分给各人。","notes":[]},{"n":36,"t":"有一个利未人，生在塞浦路斯，名叫约瑟，使徒称他为巴拿巴（巴拿巴翻出来就是劝慰子）。","notes":[]},{"n":37,"t":"他有田地，也卖了，把价银拿来，放在使徒脚前。","notes":[]}]},"5":{"heading":"亚拿尼亚和撒非喇","verses":[{"n":1,"t":"有一个人，名叫亚拿尼亚，同他的妻子撒非喇卖了田产，","notes":[]},{"n":2,"t":"把价银私自留下几分，他的妻子也知道，其余的几分拿来放在使徒脚前。","notes":[]},{"n":3,"t":"彼得说：「亚拿尼亚！为什么撒但充满了你的心，叫你欺哄圣灵，把田地的价银私自留下几分呢？","notes":[]},{"n":4,"t":"田地还没有卖，不是你自己的吗？既卖了，价银不是你作主吗？你怎么心里起这意念呢？你不是欺哄人，是欺哄神了。」","notes":[]},{"n":5,"t":"亚拿尼亚听见这话，就仆倒，断了气；听见的人都甚惧怕。","notes":[]},{"n":6,"t":"有些少年人起来，把他包裹，抬出去埋葬了。","notes":[]},{"n":7,"t":"约过了三小时，他的妻子进来，还不知道这事。","notes":[]},{"n":8,"t":"彼得对她说：「你告诉我，你们卖田地的价银就是这些吗？」她说：「就是这些。」","notes":[]},{"n":9,"t":"彼得说：「你们为什么同心试探主的灵呢？埋葬你丈夫之人的脚已到门口，他们也要把你抬出去。」","notes":[]},{"n":10,"t":"妇人立刻仆倒在彼得脚前，断了气。那些少年人进来，见她已经死了，就抬出去，埋在她丈夫旁边。","notes":[]},{"n":11,"t":"全教会和听见这事的人都甚惧怕。","notes":[]},{"n":12,"t":"主借使徒的手在民间行了许多神迹奇事；他们都同心合意地在所罗门的廊下。","notes":["或译：信的人"],"heads":["主借使徒行了许多神迹奇事"]},{"n":13,"t":"其余的人没有一个敢贴近他们，百姓却尊重他们。","notes":[]},{"n":14,"t":"信而归主的人越发增添，连男带女很多。","notes":[]},{"n":15,"t":"甚至有人将病人抬到街上，放在床上或褥子上，指望彼得过来的时候，或者得他的影儿照在什么人身上。","notes":[]},{"n":16,"t":"还有许多人带着病人和被污鬼缠磨的，从耶路撒冷四围的城邑来，全都得了医治。","notes":[]},{"n":17,"t":"大祭司和他的一切同人，就是撒都该教门的人，都起来，满心忌恨，","notes":[],"heads":["使徒受迫害"]},{"n":18,"t":"就下手拿住使徒，收在外监。","notes":[]},{"n":19,"t":"但主的使者夜间开了监门，领他们出来，","notes":[]},{"n":20,"t":"说：「你们去站在殿里，把这生命的道都讲给百姓听。」","notes":[]},{"n":21,"t":"使徒听了这话，天将亮的时候就进殿里去教训人。大祭司和他的同人来了，叫齐公会的人和以色列族的众长老，就差人到监里去，要把使徒提出来。","notes":[]},{"n":22,"t":"但差役到了，不见他们在监里，就回来禀报说：","notes":[]},{"n":23,"t":"「我们看见监牢关得极妥当，看守的人也站在门外；及至开了门，里面一个人都不见。」","notes":[]},{"n":24,"t":"守殿官和祭司长听见这话，心里犯难，不知这事将来如何。","notes":[]},{"n":25,"t":"有一个人来禀报说：「你们收在监里的人，现在站在殿里教训百姓。」","notes":[]},{"n":26,"t":"于是守殿官和差役去带使徒来，并没有用强暴，因为怕百姓用石头打他们。","notes":[]},{"n":27,"t":"带到了，便叫使徒站在公会前；大祭司问他们说：","notes":[]},{"n":28,"t":"「我们不是严严地禁止你们，不可奉这名教训人吗？你们倒把你们的道理充满了耶路撒冷，想要叫这人的血归到我们身上！」","notes":[]},{"n":29,"t":"彼得和众使徒回答说：「顺从神，不顺从人，是应当的。","notes":[]},{"n":30,"t":"你们挂在木头上杀害的耶稣，我们祖宗的神已经叫他复活。","notes":[]},{"n":31,"t":"神且用右手将他高举，叫他作君王，作救主，将悔改的心和赦罪的恩赐给以色列人。","notes":["或译：他就是神高举在自己的右边"]},{"n":32,"t":"我们为这事作见证；神赐给顺从之人的圣灵也为这事作见证。」","notes":[]},{"n":33,"t":"公会的人听见就极其恼怒，想要杀他们。","notes":[]},{"n":34,"t":"但有一个法利赛人，名叫迦玛列，是众百姓所敬重的教法师，在公会中站起来，吩咐人把使徒暂且带到外面去，","notes":[]},{"n":35,"t":"就对众人说：「以色列人哪，论到这些人，你们应当小心怎样办理。","notes":[]},{"n":36,"t":"从前杜达起来，自夸为大，附从他的人约有四百，他被杀后，附从他的全都散了，归于无有。","notes":[]},{"n":37,"t":"此后，报名上册的时候，又有加利利的犹大起来，引诱些百姓跟从他；他也灭亡，附从他的人也都四散了。","notes":[]},{"n":38,"t":"现在，我劝你们不要管这些人，任凭他们吧！他们所谋的、所行的，若是出于人，必要败坏；","notes":[]},{"n":39,"t":"若是出于神，你们就不能败坏他们，恐怕你们倒是攻击神了。」","notes":[]},{"n":40,"t":"公会的人听从了他，便叫使徒来，把他们打了，又吩咐他们不可奉耶稣的名讲道，就把他们释放了。","notes":[]},{"n":41,"t":"他们离开公会，心里欢喜，因被算是配为这名受辱。","notes":[]},{"n":42,"t":"他们就每日在殿里、在家里不住地教训人，传耶稣是基督。","notes":[]}]},"6":{"heading":"拣选七人办理供给的事","verses":[{"n":1,"t":"那时，门徒增多，有说希腊话的犹太人向希伯来人发怨言，因为在天天的供给上忽略了他们的寡妇。","notes":[]},{"n":2,"t":"十二使徒叫众门徒来，对他们说：「我们撇下神的道去管理饭食，原是不合宜的。","notes":[]},{"n":3,"t":"所以弟兄们，当从你们中间选出七个有好名声、被圣灵充满、智慧充足的人，我们就派他们管理这事。","notes":[]},{"n":4,"t":"但我们要专心以祈祷、传道为事。」","notes":[]},{"n":5,"t":"大众都喜悦这话，就拣选了司提反，乃是大有信心、圣灵充满的人，又拣选腓利、伯罗哥罗、尼迦挪、提门、巴米拿，并进犹太教的安提阿人尼哥拉，","notes":[]},{"n":6,"t":"叫他们站在使徒面前。使徒祷告了，就按手在他们头上。","notes":[]},{"n":7,"t":"神的道兴旺起来；在耶路撒冷门徒数目加增的甚多，也有许多祭司信从了这道。","notes":[]},{"n":8,"t":"司提反满得恩惠、能力，在民间行了大奇事和神迹。","notes":[],"heads":["司提反被捕"]},{"n":9,"t":"当时有称利百地拿会堂的几个人，并有古利奈、亚历山大、基利家、亚细亚各处会堂的几个人，都起来和司提反辩论。","notes":[]},{"n":10,"t":"司提反是以智慧和圣灵说话，众人敌挡不住，","notes":[]},{"n":11,"t":"就买出人来说：「我们听见他说谤讟摩西和神的话。」","notes":[]},{"n":12,"t":"他们又耸动了百姓、长老，并文士，就忽然来捉拿他，把他带到公会去，","notes":[]},{"n":13,"t":"设下假见证，说：「这个人说话，不住地糟践圣所和律法。","notes":[]},{"n":14,"t":"我们曾听见他说，这拿撒勒人耶稣要毁坏此地，也要改变摩西所交给我们的规条。」","notes":[]},{"n":15,"t":"在公会里坐着的人都定睛看他，见他的面貌，好像天使的面貌。","notes":[]}]},"7":{"heading":"司提反当众申诉","verses":[{"n":1,"t":"大祭司就说：「这些事果然有吗？」","notes":[]},{"n":2,"t":"司提反说：「诸位父兄请听！当日我们的祖宗亚伯拉罕在美索不达米亚还未住哈兰的时候，荣耀的神向他显现，","notes":[]},{"n":3,"t":"对他说：『你要离开本地和亲族，往我所要指示你的地方去。』","notes":[]},{"n":4,"t":"他就离开迦勒底人之地，住在哈兰。他父亲死了以后，神使他从那里搬到你们现在所住之地。","notes":[]},{"n":5,"t":"在这地方，神并没有给他产业，连立足之地也没有给他；但应许要将这地赐给他和他的后裔为业；那时他还没有儿子。","notes":[]},{"n":6,"t":"神说：『他的后裔必寄居外邦，那里的人要叫他们作奴仆，苦待他们四百年。』","notes":[]},{"n":7,"t":"神又说：『使他们作奴仆的那国，我要惩罚。以后他们要出来，在这地方事奉我。』","notes":[]},{"n":8,"t":"神又赐他割礼的约。于是亚伯拉罕生了以撒，第八日给他行了割礼。以撒生雅各；雅各生十二位先祖。","notes":[]},{"n":9,"t":"「先祖嫉妒约瑟，把他卖到埃及去；神却与他同在，","notes":[]},{"n":10,"t":"救他脱离一切苦难，又使他在埃及王法老面前得恩典，有智慧。法老就派他作埃及国的宰相兼管全家。","notes":[]},{"n":11,"t":"后来埃及和迦南全地遭遇饥荒，大受艰难，我们的祖宗就绝了粮。","notes":[]},{"n":12,"t":"雅各听见在埃及有粮，就打发我们的祖宗初次往那里去。","notes":[]},{"n":13,"t":"第二次约瑟与弟兄们相认，他的亲族也被法老知道了。","notes":[]},{"n":14,"t":"约瑟就打发弟兄请父亲雅各和全家七十五个人都来。","notes":[]},{"n":15,"t":"于是雅各下了埃及，后来他和我们的祖宗都死在那里；","notes":[]},{"n":16,"t":"又被带到示剑，葬于亚伯拉罕在示剑用银子从哈抹子孙买来的坟墓里。","notes":[]},{"n":17,"t":"「及至神应许亚伯拉罕的日期将到，以色列民在埃及兴盛众多，","notes":[]},{"n":18,"t":"直到有不晓得约瑟的新王兴起。","notes":[]},{"n":19,"t":"他用诡计待我们的宗族，苦害我们的祖宗，叫他们丢弃婴孩，使婴孩不能存活。","notes":[]},{"n":20,"t":"那时，摩西生下来，俊美非凡，在他父亲家里抚养了三个月。","notes":[]},{"n":21,"t":"他被丢弃的时候，法老的女儿拾了去，养为自己的儿子。","notes":[]},{"n":22,"t":"摩西学了埃及人一切的学问，说话行事都有才能。","notes":[]},{"n":23,"t":"「他将到四十岁，心中起意去看望他的弟兄以色列人；","notes":[]},{"n":24,"t":"到了那里，见他们一个人受冤屈，就护庇他，为那受欺压的人报仇，打死了那埃及人。","notes":[]},{"n":25,"t":"他以为弟兄必明白神是借他的手搭救他们；他们却不明白。","notes":[]},{"n":26,"t":"第二天，遇见两个以色列人争斗，就劝他们和睦，说：『你们二位是弟兄，为什么彼此欺负呢？』","notes":[]},{"n":27,"t":"那欺负邻舍的把他推开，说：『谁立你作我们的首领和审判官呢？","notes":[]},{"n":28,"t":"难道你要杀我，像昨天杀那埃及人吗？』","notes":[]},{"n":29,"t":"摩西听见这话就逃走了，寄居于米甸；在那里生了两个儿子。","notes":[]},{"n":30,"t":"「过了四十年，在西奈山的旷野，有一位天使从荆棘火焰中向摩西显现。","notes":[]},{"n":31,"t":"摩西见了那异象，便觉希奇，正进前观看的时候，有主的声音说：","notes":[]},{"n":32,"t":"『我是你列祖的神，就是亚伯拉罕的神，以撒的神，雅各的神。』摩西战战兢兢，不敢观看。","notes":[]},{"n":33,"t":"主对他说：『把你脚上的鞋脱下来，因为你所站之地是圣地。","notes":[]},{"n":34,"t":"我的百姓在埃及所受的困苦，我实在看见了，他们悲叹的声音，我也听见了。我下来要救他们。你来！我要差你往埃及去。』","notes":[]},{"n":35,"t":"这摩西就是百姓弃绝说『谁立你作我们的首领和审判官』的；神却借那在荆棘中显现之使者的手差派他作首领、作救赎的。","notes":[]},{"n":36,"t":"这人领百姓出来，在埃及，在红海，在旷野，四十年间行了奇事神迹。","notes":[]},{"n":37,"t":"那曾对以色列人说『神要从你们弟兄中间给你们兴起一位先知像我』的，就是这位摩西。","notes":[]},{"n":38,"t":"这人曾在旷野会中和西奈山上，与那对他说话的天使同在，又与我们的祖宗同在，并且领受活泼的圣言传给我们。","notes":[]},{"n":39,"t":"我们的祖宗不肯听从，反弃绝他，心里归向埃及，","notes":[]},{"n":40,"t":"对亚伦说：『你且为我们造些神像，在我们前面引路；因为领我们出埃及地的那个摩西，我们不知道他遭了什么事。』","notes":[]},{"n":41,"t":"那时，他们造了一个牛犊，又拿祭物献给那像，欢喜自己手中的工作。","notes":[]},{"n":42,"t":"神就转脸不顾，任凭他们事奉天上的日月星辰，正如先知书上所写的说：以色列家啊，你们四十年间在旷野，岂是将牺牲和祭物献给我吗？","notes":[]},{"n":43,"t":"你们抬着摩洛的帐幕和理番神的星，就是你们所造为要敬拜的像。因此，我要把你们迁到巴比伦外去。","notes":[]},{"n":44,"t":"「我们的祖宗在旷野，有法柜的帐幕，是神吩咐摩西叫他照所看见的样式做的。","notes":[]},{"n":45,"t":"这帐幕，我们的祖宗相继承受。当神在他们面前赶出外邦人去的时候，他们同约书亚把帐幕搬进承受为业之地，直存到大卫的日子。","notes":[]},{"n":46,"t":"大卫在神面前蒙恩，祈求为雅各的神预备居所；","notes":[]},{"n":47,"t":"却是所罗门为神造成殿宇。","notes":[]},{"n":48,"t":"其实，至高者并不住人手所造的，就如先知所言：","notes":[]},{"n":49,"t":"主说：天是我的座位，地是我的脚凳；你们要为我造何等的殿宇？哪里是我安息的地方呢？","notes":[]},{"n":50,"t":"这一切不都是我手所造的吗？","notes":[]},{"n":51,"t":"「你们这硬着颈项、心与耳未受割礼的人，常时抗拒圣灵！你们的祖宗怎样，你们也怎样。","notes":[]},{"n":52,"t":"哪一个先知不是你们祖宗逼迫呢？他们也把预先传说那义者要来的人杀了；如今你们又把那义者卖了，杀了。","notes":[]},{"n":53,"t":"你们受了天使所传的律法，竟不遵守。」","notes":[]},{"n":54,"t":"众人听见这话就极其恼怒，向司提反咬牙切齿。","notes":[],"heads":["众人用石头打死司提反"]},{"n":55,"t":"但司提反被圣灵充满，定睛望天，看见神的荣耀，又看见耶稣站在神的右边，","notes":[]},{"n":56,"t":"就说：「我看见天开了，人子站在神的右边。」","notes":[]},{"n":57,"t":"众人大声喊叫，捂着耳朵，齐心拥上前去，","notes":[]},{"n":58,"t":"把他推到城外，用石头打他。作见证的人把衣裳放在一个少年人名叫扫罗的脚前。","notes":[]},{"n":59,"t":"他们正用石头打的时候，司提反呼吁主说：「求主耶稣接收我的灵魂！」","notes":[]},{"n":60,"t":"又跪下大声喊着说：「主啊，不要将这罪归于他们！」说了这话，就睡了。扫罗也喜悦他被害。","notes":[]}]},"8":{"heading":"扫罗逼迫教会","verses":[{"n":1,"t":"从这日起，耶路撒冷的教会大遭逼迫，除了使徒以外，门徒都分散在犹太和撒马利亚各处。","notes":[]},{"n":2,"t":"有虔诚的人把司提反埋葬了，为他捶胸大哭。","notes":[]},{"n":3,"t":"扫罗却残害教会，进各人的家，拉着男女下在监里。","notes":[]},{"n":4,"t":"那些分散的人往各处去传道。","notes":[],"heads":["福音传到撒马利亚"]},{"n":5,"t":"腓利下撒马利亚城去，宣讲基督。","notes":[]},{"n":6,"t":"众人听见了，又看见腓利所行的神迹，就同心合意地听从他的话。","notes":[]},{"n":7,"t":"因为有许多人被污鬼附着，那些鬼大声呼叫，从他们身上出来；还有许多瘫痪的、瘸腿的，都得了医治。","notes":[]},{"n":8,"t":"在那城里，就大有欢喜。","notes":[]},{"n":9,"t":"有一个人，名叫西门，向来在那城里行邪术，妄自尊大，使撒马利亚的百姓惊奇；","notes":[]},{"n":10,"t":"无论大小都听从他，说：「这人就是那称为神的大能者。」","notes":[]},{"n":11,"t":"他们听从他，因他久用邪术，使他们惊奇。","notes":[]},{"n":12,"t":"及至他们信了腓利所传神国的福音和耶稣基督的名，连男带女就受了洗。","notes":[]},{"n":13,"t":"西门自己也信了；既受了洗，就常与腓利在一处，看见他所行的神迹和大异能，就甚惊奇。","notes":[]},{"n":14,"t":"使徒在耶路撒冷听见撒马利亚人领受了神的道，就打发彼得、约翰往他们那里去。","notes":[]},{"n":15,"t":"两个人到了，就为他们祷告，要叫他们受圣灵。","notes":[]},{"n":16,"t":"因为圣灵还没有降在他们一个人身上，他们只奉主耶稣的名受了洗。","notes":[]},{"n":17,"t":"于是使徒按手在他们头上，他们就受了圣灵。","notes":[]},{"n":18,"t":"西门看见使徒按手，便有圣灵赐下，就拿钱给使徒，","notes":[]},{"n":19,"t":"说：「把这权柄也给我，叫我手按着谁，谁就可以受圣灵。」","notes":[]},{"n":20,"t":"彼得说：「你的银子和你一同灭亡吧！因你想神的恩赐是可以用钱买的。","notes":[]},{"n":21,"t":"你在这道上无分无关；因为在神面前，你的心不正。","notes":[]},{"n":22,"t":"你当懊悔你这罪恶，祈求主，或者你心里的意念可得赦免。","notes":[]},{"n":23,"t":"我看出你正在苦胆之中，被罪恶捆绑。」","notes":[]},{"n":24,"t":"西门说：「愿你们为我求主，叫你们所说的，没有一样临到我身上。」","notes":[]},{"n":25,"t":"使徒既证明主道，而且传讲，就回耶路撒冷去，一路在撒马利亚好些村庄传扬福音。","notes":[]},{"n":26,"t":"有主的一个使者对腓利说：「起来！向南走，往那从耶路撒冷下迦萨的路上去。」那路是旷野。","notes":[],"heads":["腓利和衣索匹亚的太监"]},{"n":27,"t":"腓利就起身去了，不料，有一个衣索匹亚人，是个有大权的太监，在衣索匹亚女王甘大基的手下总管银库，他上耶路撒冷礼拜去了。","notes":["就是古实，见以赛亚十八章一节"]},{"n":28,"t":"现在回来，在车上坐着，念先知以赛亚的书。","notes":[]},{"n":29,"t":"圣灵对腓利说：「你去！贴近那车走。」","notes":[]},{"n":30,"t":"腓利就跑到太监那里，听见他念先知以赛亚的书，便问他说：「你所念的，你明白吗？」","notes":[]},{"n":31,"t":"他说：「没有人指教我，怎能明白呢？」于是请腓利上车，与他同坐。","notes":[]},{"n":32,"t":"他所念的那段经，说：他像羊被牵到宰杀之地，又像羊羔在剪毛的人手下无声；他也是这样不开口。","notes":[]},{"n":33,"t":"他卑微的时候，人不按公义审判他；谁能述说他的世代？因为他的生命从地上夺去。","notes":["原文是他的审判被夺去"]},{"n":34,"t":"太监对腓利说：「请问，先知说这话是指着谁？是指着自己呢？是指着别人呢？」","notes":[]},{"n":35,"t":"腓利就开口从这经上起，对他传讲耶稣。","notes":[]},{"n":36,"t":"二人正往前走，到了有水的地方，太监说：「看哪，这里有水，我受洗有什么妨碍呢？」","notes":["有古卷加：37腓利说：「你若是一心相信，就可以。」他回答说：「我信耶稣基督是神的儿子。」"]},{"n":38,"t":"于是吩咐车站住，腓利和太监二人同下水里去，腓利就给他施洗。","notes":[]},{"n":39,"t":"从水里上来，主的灵把腓利提了去，太监也不再见他了，就欢欢喜喜地走路。","notes":[]},{"n":40,"t":"后来有人在亚锁都遇见腓利；他走遍那地方，在各城宣传福音，直到凯撒利亚。","notes":[]}]},"9":{"heading":"扫罗的转变","verses":[{"n":1,"t":"扫罗仍然向主的门徒口吐威吓凶杀的话，去见大祭司，","notes":[]},{"n":2,"t":"求文书给大马士革的各会堂，若是找着信奉这道的人，无论男女，都准他捆绑带到耶路撒冷。","notes":[]},{"n":3,"t":"扫罗行路，将到大马士革，忽然从天上发光，四面照着他；","notes":[]},{"n":4,"t":"他就仆倒在地，听见有声音对他说：「扫罗！扫罗！你为什么逼迫我？」","notes":[]},{"n":5,"t":"他说：「主啊！你是谁？」主说：「我就是你所逼迫的耶稣。","notes":[]},{"n":6,"t":"起来！进城去，你所当做的事，必有人告诉你。」","notes":[]},{"n":7,"t":"同行的人站在那里，说不出话来，听见声音，却看不见人。","notes":[]},{"n":8,"t":"扫罗从地上起来，睁开眼睛，竟不能看见什么。有人拉他的手，领他进了大马士革；","notes":[]},{"n":9,"t":"三日不能看见，也不吃也不喝。","notes":[]},{"n":10,"t":"当下，在大马士革有一个门徒，名叫亚拿尼亚。主在异象中对他说：「亚拿尼亚。」他说：「主，我在这里。」","notes":[]},{"n":11,"t":"主对他说：「起来！往直街去，在犹大的家里，访问一个大数人，名叫扫罗。他正祷告，","notes":[]},{"n":12,"t":"又看见了一个人，名叫亚拿尼亚，进来按手在他身上，叫他能看见。」","notes":[]},{"n":13,"t":"亚拿尼亚回答说：「主啊，我听见许多人说，这人怎样在耶路撒冷多多苦害你的圣徒，","notes":[]},{"n":14,"t":"并且他在这里有从祭司长得来的权柄捆绑一切求告你名的人。」","notes":[]},{"n":15,"t":"主对亚拿尼亚说：「你只管去！他是我所拣选的器皿，要在外邦人和君王，并以色列人面前宣扬我的名。","notes":[]},{"n":16,"t":"我也要指示他，为我的名必须受许多的苦难。」","notes":[]},{"n":17,"t":"亚拿尼亚就去了，进入那家，把手按在扫罗身上，说：「兄弟扫罗，在你来的路上向你显现的主，就是耶稣，打发我来，叫你能看见，又被圣灵充满。」","notes":[]},{"n":18,"t":"扫罗的眼睛上，好像有鳞立刻掉下来，他就能看见。于是起来受了洗；","notes":[]},{"n":19,"t":"吃过饭就健壮了。扫罗和大马士革的门徒同住了些日子，","notes":[]},{"n":20,"t":"就在各会堂里宣传耶稣，说他是神的儿子。","notes":[]},{"n":21,"t":"凡听见的人都惊奇，说：「在耶路撒冷残害求告这名的，不是这人吗？并且他到这里来，特要捆绑他们，带到祭司长那里。」","notes":[]},{"n":22,"t":"但扫罗越发有能力，驳倒住大马士革的犹太人，证明耶稣是基督。","notes":[]},{"n":23,"t":"过了好些日子，犹太人商议要杀扫罗，","notes":[],"heads":["未受犹太人的谋害"]},{"n":24,"t":"但他们的计谋被扫罗知道了。他们又昼夜在城门守候，要杀他。","notes":[]},{"n":25,"t":"他的门徒就在夜间用筐子把他从城墙上缒下去。","notes":[]},{"n":26,"t":"扫罗到了耶路撒冷，想与门徒结交，他们却都怕他，不信他是门徒。","notes":[],"heads":["扫罗在耶路撒冷"]},{"n":27,"t":"惟有巴拿巴接待他，领去见使徒，把他在路上怎么看见主，主怎么向他说话，他在大马士革怎么奉耶稣的名放胆传道，都述说出来。","notes":[]},{"n":28,"t":"于是扫罗在耶路撒冷和门徒出入来往，","notes":[]},{"n":29,"t":"奉主的名放胆传道，并与说希腊话的犹太人讲论辩驳；他们却想法子要杀他。","notes":[]},{"n":30,"t":"弟兄们知道了就送他下凯撒利亚，打发他往大数去。","notes":[]},{"n":31,"t":"那时，犹太、加利利、撒马利亚各处的教会都得平安，被建立；凡事敬畏主，蒙圣灵的安慰，人数就增多了。","notes":[]},{"n":32,"t":"彼得周流四方的时候，也到了居住吕大的圣徒那里；","notes":[],"heads":["以尼雅得医治"]},{"n":33,"t":"遇见一个人，名叫以尼雅，得了瘫痪，在褥子上躺卧八年。","notes":[]},{"n":34,"t":"彼得对他说：「以尼雅，耶稣基督医好你了，起来！收拾你的褥子。」他就立刻起来了。","notes":[]},{"n":35,"t":"凡住吕大和沙仑的人都看见了他，就归服主。","notes":[]},{"n":36,"t":"在约帕有一个女徒，名叫大比大，翻希腊话就是多加；她广行善事，多施周济。","notes":["就是羚羊的意思"],"heads":["多加复活"]},{"n":37,"t":"当时，她患病而死，有人把她洗了，停在楼上。","notes":[]},{"n":38,"t":"吕大原与约帕相近；门徒听见彼得在那里，就打发两个人去见他，央求他说：「快到我们那里去，不要耽延。」","notes":[]},{"n":39,"t":"彼得就起身和他们同去；到了，便有人领他上楼。众寡妇都站在彼得旁边哭，拿多加与她们同在时所做的里衣外衣给他看。","notes":[]},{"n":40,"t":"彼得叫她们都出去，就跪下祷告，转身对着死人说：「大比大，起来！」她就睁开眼睛，见了彼得，便坐起来。","notes":[]},{"n":41,"t":"彼得伸手扶她起来，叫众圣徒和寡妇进去，把多加活活地交给他们。","notes":[]},{"n":42,"t":"这事传遍了约帕，就有许多人信了主。","notes":[]},{"n":43,"t":"此后，彼得在约帕一个硝皮匠西门的家里住了多日。","notes":[]}]},"10":{"heading":"彼得和哥尼流","verses":[{"n":1,"t":"在凯撒利亚有一个人，名叫哥尼流，是「意大利营」的百夫长。","notes":[]},{"n":2,"t":"他是个虔诚人，他和全家都敬畏神，多多周济百姓，常常祷告神。","notes":[]},{"n":3,"t":"有一天，约在申初，他在异象中明明看见神的一个使者进去，到他那里，说：「哥尼流。」","notes":[]},{"n":4,"t":"哥尼流定睛看他，惊怕说：「主啊，什么事呢？」天使说：「你的祷告和你的周济达到神面前，已蒙记念了。","notes":[]},{"n":5,"t":"现在你当打发人往约帕去，请那称呼彼得的西门来。","notes":[]},{"n":6,"t":"他住在海边一个硝皮匠西门的家里，房子在海边上。」","notes":[]},{"n":7,"t":"向他说话的天使去后，哥尼流叫了两个家人和常伺候他的一个虔诚兵来，","notes":[]},{"n":8,"t":"把这事都述说给他们听，就打发他们往约帕去。","notes":[]},{"n":9,"t":"第二天，他们行路将近那城。彼得约在午正，上房顶去祷告，","notes":[]},{"n":10,"t":"觉得饿了，想要吃。那家的人正预备饭的时候，彼得魂游象外，","notes":[]},{"n":11,"t":"看见天开了，有一物降下，好像一块大布，系着四角，缒在地上，","notes":[]},{"n":12,"t":"里面有地上各样四足的走兽和昆虫，并天上的飞鸟；","notes":[]},{"n":13,"t":"又有声音向他说：「彼得，起来，宰了吃！」","notes":[]},{"n":14,"t":"彼得却说：「主啊，这是不可的！凡俗物和不洁净的物，我从来没有吃过。」","notes":[]},{"n":15,"t":"第二次有声音向他说：「神所洁净的，你不可当作俗物。」","notes":[]},{"n":16,"t":"这样一连三次，那物随即收回天上去了。","notes":[]},{"n":17,"t":"彼得心里正在猜疑之间，不知所看见的异象是什么意思。哥尼流所差来的人已经访问到西门的家，站在门外，","notes":[]},{"n":18,"t":"喊着问：「有称呼彼得的西门住在这里没有？」","notes":[]},{"n":19,"t":"彼得还思想那异象的时候，圣灵向他说：「有三个人来找你。","notes":[]},{"n":20,"t":"起来，下去，和他们同往，不要疑惑，因为是我差他们来的。」","notes":[]},{"n":21,"t":"于是彼得下去见那些人，说：「我就是你们所找的人。你们来是为什么缘故？」","notes":[]},{"n":22,"t":"他们说：「百夫长哥尼流是个义人，敬畏神，为犹太通国所称赞。他蒙一位圣天使所指示，叫他请你到他家里去，听你的话。」","notes":[]},{"n":23,"t":"彼得就请他们进去，住了一宿。次日，起身和他们同去，还有约帕的几个弟兄同着他去；","notes":[]},{"n":24,"t":"又次日，他们进入凯撒利亚，哥尼流已经请了他的亲属密友等候他们。","notes":[]},{"n":25,"t":"彼得一进去，哥尼流就迎接他，俯伏在他脚前拜他。","notes":[]},{"n":26,"t":"彼得却拉他，说：「你起来，我也是人。」","notes":[]},{"n":27,"t":"彼得和他说着话进去，见有好些人在那里聚集，","notes":[]},{"n":28,"t":"就对他们说：「你们知道，犹太人和别国的人亲近来往本是不合例的，但神已经指示我，无论什么人都不可看作俗而不洁净的。","notes":[]},{"n":29,"t":"所以我被请的时候，就不推辞而来。现在请问：你们叫我来有什么意思呢？」","notes":[]},{"n":30,"t":"哥尼流说：「前四天，这个时候，我在家中守着申初的祷告，忽然有一个人穿着光明的衣裳，站在我面前，","notes":[]},{"n":31,"t":"说：『哥尼流，你的祷告已蒙垂听，你的周济达到神面前已蒙记念了。","notes":[]},{"n":32,"t":"你当打发人往约帕去，请那称呼彼得的西门来，他住在海边一个硝皮匠西门的家里。』","notes":[]},{"n":33,"t":"所以我立时打发人去请你。你来了很好；现今我们都在神面前，要听主所吩咐你的一切话。」","notes":[]},{"n":34,"t":"彼得就开口说：「我真看出神是不偏待人。","notes":[],"heads":["在哥尼流家中讲道"]},{"n":35,"t":"原来，各国中那敬畏主、行义的人都为主所悦纳。","notes":[]},{"n":36,"t":"神借着耶稣基督（他是万有的主）传和平的福音，将这道赐给以色列人。","notes":[]},{"n":37,"t":"这话在约翰宣传洗礼以后，从加利利起，传遍了犹太。","notes":[]},{"n":38,"t":"神怎样以圣灵和能力膏拿撒勒人耶稣，这都是你们知道的。他周流四方，行善事，医好凡被魔鬼压制的人，因为神与他同在。","notes":[]},{"n":39,"t":"他在犹太人之地，并耶路撒冷所行的一切事，有我们作见证。他们竟把他挂在木头上杀了。","notes":[]},{"n":40,"t":"第三日，神叫他复活，显现出来；","notes":[]},{"n":41,"t":"不是显现给众人看，乃是显现给神预先所拣选为他作见证的人看，就是我们这些在他从死里复活以后和他同吃同喝的人。","notes":[]},{"n":42,"t":"他吩咐我们传道给众人，证明他是神所立定的，要作审判活人、死人的主。","notes":[]},{"n":43,"t":"众先知也为他作见证说：『凡信他的人必因他的名得蒙赦罪。』」","notes":[]},{"n":44,"t":"彼得还说这话的时候，圣灵降在一切听道的人身上。","notes":[],"heads":["外邦人领受圣灵"]},{"n":45,"t":"那些奉割礼、和彼得同来的信徒，见圣灵的恩赐也浇在外邦人身上，就都希奇；","notes":[]},{"n":46,"t":"因听见他们说方言，称赞神为大。","notes":[]},{"n":47,"t":"于是彼得说：「这些人既受了圣灵，与我们一样，谁能禁止用水给他们施洗呢？」","notes":[]},{"n":48,"t":"就吩咐奉耶稣基督的名给他们施洗。他们又请彼得住了几天。","notes":[]}]},"11":{"heading":"向耶路撒冷教会报告","verses":[{"n":1,"t":"使徒和在犹太的众弟兄听说外邦人也领受了神的道。","notes":[]},{"n":2,"t":"及至彼得上了耶路撒冷，那些奉割礼的门徒和他争辩说：","notes":[]},{"n":3,"t":"「你进入未受割礼之人的家和他们一同吃饭了。」","notes":[]},{"n":4,"t":"彼得就开口把这事挨次给他们讲解说：","notes":[]},{"n":5,"t":"「我在约帕城里祷告的时候，魂游象外，看见异象，有一物降下，好像一块大布，系着四角，从天缒下，直来到我跟前。","notes":[]},{"n":6,"t":"我定睛观看，见内中有地上四足的牲畜和野兽、昆虫，并天上的飞鸟。","notes":[]},{"n":7,"t":"我且听见有声音向我说：『彼得，起来，宰了吃！』","notes":[]},{"n":8,"t":"我说：『主啊，这是不可的！凡俗而不洁净的物从来没有入过我的口。』","notes":[]},{"n":9,"t":"第二次，有声音从天上说：『神所洁净的，你不可当作俗物。』","notes":[]},{"n":10,"t":"这样一连三次，就都收回天上去了。","notes":[]},{"n":11,"t":"正当那时，有三个人站在我们所住的房门前，是从凯撒利亚差来见我的。","notes":[]},{"n":12,"t":"圣灵吩咐我和他们同去，不要疑惑。同着我去的，还有这六位弟兄，我们都进了那人的家。","notes":["或译：不要分别等类"]},{"n":13,"t":"那人就告诉我们，他如何看见一位天使站在他屋里，说：『你打发人往约帕去，请那称呼彼得的西门来，","notes":[]},{"n":14,"t":"他有话告诉你，可以叫你和你的全家得救。』","notes":[]},{"n":15,"t":"我一开讲，圣灵便降在他们身上，正像当初降在我们身上一样。","notes":[]},{"n":16,"t":"我就想起主的话说：『约翰是用水施洗，但你们要受圣灵的洗。』","notes":[]},{"n":17,"t":"神既然给他们恩赐，像在我们信主耶稣基督的时候给了我们一样；我是谁，能拦阻神呢？」","notes":[]},{"n":18,"t":"众人听见这话，就不言语了，只归荣耀与神，说：「这样看来，神也赐恩给外邦人，叫他们悔改得生命了。」","notes":[]},{"n":19,"t":"那些因司提反的事遭患难四散的门徒直走到腓尼基和塞浦路斯，并安提阿；他们不向别人讲道，只向犹太人讲。","notes":[],"heads":["安提阿的教会"]},{"n":20,"t":"但内中有塞浦路斯和古利奈人，他们到了安提阿也向希腊人传讲主耶稣。","notes":["有古卷：也向说希腊话的犹太人传讲主耶稣"]},{"n":21,"t":"主与他们同在，信而归主的人就很多了。","notes":[]},{"n":22,"t":"这风声传到耶路撒冷教会人的耳中，他们就打发巴拿巴出去，走到安提阿为止。","notes":[]},{"n":23,"t":"他到了那里，看见神所赐的恩就欢喜，劝勉众人，立定心志，恒久靠主。","notes":[]},{"n":24,"t":"这巴拿巴原是个好人，被圣灵充满，大有信心。于是有许多人归服了主。","notes":[]},{"n":25,"t":"他又往大数去找扫罗，","notes":[]},{"n":26,"t":"找着了，就带他到安提阿去。他们足有一年的工夫和教会一同聚集，教训了许多人。门徒称为「基督徒」是从安提阿起首。","notes":[]},{"n":27,"t":"当那些日子，有几位先知从耶路撒冷下到安提阿。","notes":[]},{"n":28,"t":"内中有一位，名叫亚迦布，站起来，借着圣灵指明天下将有大饥荒。（这事到克劳第年间果然有了。）","notes":[]},{"n":29,"t":"于是门徒定意照各人的力量捐钱，送去供给住在犹太的弟兄。","notes":[]},{"n":30,"t":"他们就这样行，把捐项托巴拿巴和扫罗送到众长老那里。","notes":[]}]},"12":{"heading":"雅各被杀，彼得被囚","verses":[{"n":1,"t":"那时，希律王下手苦害教会中几个人，","notes":[]},{"n":2,"t":"用刀杀了约翰的哥哥雅各。","notes":[]},{"n":3,"t":"他见犹太人喜欢这事，又去捉拿彼得。那时正是除酵的日子。","notes":[]},{"n":4,"t":"希律拿了彼得，收在监里，交付四班兵丁看守，每班四个人，意思要在逾越节后把他提出来，当着百姓办他。","notes":[]},{"n":5,"t":"于是彼得被囚在监里；教会却为他切切地祷告神。","notes":[]},{"n":6,"t":"希律将要提他出来的前一夜，彼得被两条铁链锁着，睡在两个兵丁当中；看守的人也在门外看守。","notes":[],"heads":["彼得获救出狱"]},{"n":7,"t":"忽然，有主的一个使者站在旁边，屋里有光照耀，天使拍彼得的肋旁，拍醒了他，说：「快快起来！」那铁链就从他手上脱落下来。","notes":[]},{"n":8,"t":"天使对他说：「束上带子，穿上鞋。」他就那样做。天使又说：「披上外衣，跟着我来。」","notes":[]},{"n":9,"t":"彼得就出来跟着他，不知道天使所做是真的，只当见了异象。","notes":[]},{"n":10,"t":"过了第一层第二层监牢，就来到临街的铁门，那门自己开了。他们出来，走过一条街，天使便离开他去了。","notes":[]},{"n":11,"t":"彼得醒悟过来，说：「我现在真知道主差遣他的使者，救我脱离希律的手和犹太百姓一切所盼望的。」","notes":[]},{"n":12,"t":"想了一想，就往那称呼马可的约翰、他母亲马利亚家去，在那里有好些人聚集祷告。","notes":[]},{"n":13,"t":"彼得敲外门，有一个使女，名叫罗大，出来探听，","notes":[]},{"n":14,"t":"听得是彼得的声音，就欢喜的顾不得开门，跑进去告诉众人说：「彼得站在门外。」","notes":[]},{"n":15,"t":"他们说：「你是疯了！」使女极力地说：「真是他！」他们说：「必是他的天使！」","notes":[]},{"n":16,"t":"彼得不住地敲门。他们开了门，看见他，就甚惊奇。","notes":[]},{"n":17,"t":"彼得摆手，不要他们作声，就告诉他们主怎样领他出监；又说：「你们把这事告诉雅各和众弟兄。」于是出去，往别处去了。","notes":[]},{"n":18,"t":"到了天亮，兵丁扰乱得很，不知道彼得往哪里去了。","notes":[]},{"n":19,"t":"希律找他，找不着，就审问看守的人，吩咐把他们拉去杀了。后来希律离开犹太，下凯撒利亚去，住在那里。","notes":[]},{"n":20,"t":"希律恼怒泰尔、西顿的人。他们那一带地方是从王的地土得粮，因此就托了王的内侍臣伯拉斯都的情，一心来求和。","notes":[],"heads":["希律的死"]},{"n":21,"t":"希律在所定的日子，穿上朝服，坐在位上，对他们讲论一番。","notes":[]},{"n":22,"t":"百姓喊着说：「这是神的声音，不是人的声音。」","notes":[]},{"n":23,"t":"希律不归荣耀给神，所以主的使者立刻罚他，他被虫所咬，气就绝了。","notes":[]},{"n":24,"t":"神的道日见兴旺，越发广传。","notes":[]},{"n":25,"t":"巴拿巴和扫罗办完了他们供给的事，就从耶路撒冷回来，带着称呼马可的约翰同去。","notes":[]}]},"13":{"heading":"巴拿巴和扫罗奉差遣","verses":[{"n":1,"t":"在安提阿的教会中，有几位先知和教师，就是巴拿巴和称呼尼结的西面、古利奈人路求，与分封之王希律同养的马念，并扫罗。","notes":[]},{"n":2,"t":"他们事奉主、禁食的时候，圣灵说：「要为我分派巴拿巴和扫罗，去做我召他们所做的工。」","notes":[]},{"n":3,"t":"于是禁食祷告，按手在他们头上，就打发他们去了。","notes":[]},{"n":4,"t":"他们既被圣灵差遣，就下到西流基，从那里坐船往塞浦路斯去。","notes":[],"heads":["在塞浦路斯传道"]},{"n":5,"t":"到了撒拉米，就在犹太人各会堂里传讲神的道，也有约翰作他们的帮手。","notes":[]},{"n":6,"t":"经过全岛，直到帕弗，在那里遇见一个有法术、假充先知的犹太人，名叫巴·耶稣。","notes":[]},{"n":7,"t":"这人常和方伯士求·保罗同在。士求·保罗是个通达人，他请了巴拿巴和扫罗来，要听神的道。","notes":[]},{"n":8,"t":"只是那行法术的以吕马（这名翻出来就是行法术的意思）敌挡使徒，要叫方伯不信真道。","notes":[]},{"n":9,"t":"扫罗又名保罗，被圣灵充满，定睛看他，","notes":[]},{"n":10,"t":"说：「你这充满各样诡诈奸恶，魔鬼的儿子，众善的仇敌，你混乱主的正道还不止住吗？","notes":[]},{"n":11,"t":"现在主的手加在你身上，你要瞎眼，暂且不见日光。」他的眼睛立刻昏蒙黑暗，四下里求人拉着手领他。","notes":[]},{"n":12,"t":"方伯看见所做的事，很希奇主的道，就信了。","notes":[]},{"n":13,"t":"保罗和他的同人从帕弗开船，来到旁非利亚的别加，约翰就离开他们，回耶路撒冷去。","notes":[],"heads":["在彼西底的安提阿传道"]},{"n":14,"t":"他们离了别加往前行，来到彼西底的安提阿，在安息日进会堂坐下。","notes":[]},{"n":15,"t":"读完了律法和先知的书，管会堂的叫人过去，对他们说：「二位兄台，若有什么劝勉众人的话，请说。」","notes":[]},{"n":16,"t":"保罗就站起来，举手，说：「以色列人和一切敬畏神的人，请听。","notes":[]},{"n":17,"t":"这以色列民的神拣选了我们的祖宗，当民寄居埃及的时候抬举他们，用大能的手领他们出来；","notes":[]},{"n":18,"t":"又在旷野容忍他们，约有四十年。","notes":["或译：抚养"]},{"n":19,"t":"既灭了迦南地七族的人，就把那地分给他们为业；","notes":[]},{"n":20,"t":"此后给他们设立士师，约有四百五十年，直到先知撒母耳的时候。","notes":[]},{"n":21,"t":"后来他们求一个王，神就将便雅悯支派中基士的儿子扫罗，给他们作王四十年。","notes":[]},{"n":22,"t":"既废了扫罗，就选立大卫作他们的王，又为他作见证说：『我寻得耶西的儿子大卫，他是合我心意的人，凡事要遵行我的旨意。』","notes":[]},{"n":23,"t":"从这人的后裔中，神已经照着所应许的，为以色列人立了一位救主，就是耶稣。","notes":[]},{"n":24,"t":"在他没有出来以先，约翰向以色列众民宣讲悔改的洗礼。","notes":[]},{"n":25,"t":"约翰将行尽他的程途说：『你们以为我是谁？我不是基督；只是有一位在我以后来的，我解他脚上的鞋带也是不配的。』","notes":[]},{"n":26,"t":"「弟兄们，亚伯拉罕的子孙和你们中间敬畏神的人哪，这救世的道是传给我们的。","notes":[]},{"n":27,"t":"耶路撒冷居住的人和他们的官长，因为不认识基督，也不明白每安息日所读众先知的书，就把基督定了死罪，正应了先知的预言；","notes":[]},{"n":28,"t":"虽然查不出他有当死的罪来，还是求彼拉多杀他；","notes":[]},{"n":29,"t":"既成就了经上指着他所记的一切话，就把他从木头上取下来，放在坟墓里。","notes":[]},{"n":30,"t":"神却叫他从死里复活。","notes":[]},{"n":31,"t":"那从加利利同他上耶路撒冷的人多日看见他，这些人如今在民间是他的见证。","notes":[]},{"n":32,"t":"我们也报好信息给你们，就是那应许祖宗的话，","notes":[]},{"n":33,"t":"神已经向我们这作儿女的应验，叫耶稣复活了。正如诗篇第二篇上记着说：你是我的儿子，我今日生你。","notes":[]},{"n":34,"t":"论到神叫他从死里复活，不再归于朽坏，就这样说：我必将所应许大卫那圣洁、可靠的恩典赐给你们。","notes":[]},{"n":35,"t":"又有一篇上说：你必不叫你的圣者见朽坏。","notes":[]},{"n":36,"t":"「大卫在世的时候遵行了神的旨意，就睡了，归到他祖宗那里，已见朽坏；","notes":["或译：大卫按神的旨意服事了他那一世的人，就睡了"]},{"n":37,"t":"惟独神所复活的，他并未见朽坏。","notes":[]},{"n":38,"t":"所以，弟兄们，你们当晓得：赦罪的道是由这人传给你们的。","notes":[]},{"n":39,"t":"你们靠摩西的律法，在一切不得称义的事上信靠这人，就都得称义了。","notes":[]},{"n":40,"t":"所以，你们务要小心，免得先知书上所说的临到你们。","notes":[]},{"n":41,"t":"主说：你们这轻慢的人要观看，要惊奇，要灭亡；因为在你们的时候，我行一件事，虽有人告诉你们，你们总是不信。」","notes":[]},{"n":42,"t":"他们出会堂的时候，众人请他们到下安息日再讲这话给他们听。","notes":[]},{"n":43,"t":"散会以后，犹太人和敬虔进犹太教的人多有跟从保罗、巴拿巴的。二人对他们讲道，劝他们务要恒久在神的恩中。","notes":[]},{"n":44,"t":"到下安息日，合城的人几乎都来聚集，要听神的道。","notes":[]},{"n":45,"t":"但犹太人看见人这样多，就满心嫉妒，硬驳保罗所说的话，并且毁谤。","notes":[]},{"n":46,"t":"保罗和巴拿巴放胆说：「神的道先讲给你们原是应当的；只因你们弃绝这道，断定自己不配得永生，我们就转向外邦人去。","notes":[]},{"n":47,"t":"因为主曾这样吩咐我们说：我已经立你作外邦人的光，叫你施行救恩，直到地极。」","notes":[]},{"n":48,"t":"外邦人听见这话，就欢喜了，赞美神的道；凡预定得永生的人都信了。","notes":[]},{"n":49,"t":"于是主的道传遍了那一带地方。","notes":[]},{"n":50,"t":"但犹太人挑唆虔敬、尊贵的妇女和城内有名望的人，逼迫保罗、巴拿巴，将他们赶出境外。","notes":[]},{"n":51,"t":"二人对着众人跺下脚上的尘土，就往以哥念去了。","notes":[]},{"n":52,"t":"门徒满心喜乐，又被圣灵充满。","notes":[]}]},"14":{"heading":"在以哥念传道","verses":[{"n":1,"t":"二人在以哥念同进犹太人的会堂，在那里讲的，叫犹太人和希腊人信的很多。","notes":[]},{"n":2,"t":"但那不顺从的犹太人耸动外邦人，叫他们心里恼恨弟兄。","notes":[]},{"n":3,"t":"二人在那里住了多日，倚靠主放胆讲道，主借他们的手施行神迹奇事，证明他的恩道。","notes":[]},{"n":4,"t":"城里的众人就分了党，有附从犹太人的，有附从使徒的。","notes":[]},{"n":5,"t":"那时，外邦人和犹太人，并他们的官长，一齐拥上来，要凌辱使徒，用石头打他们。","notes":[]},{"n":6,"t":"使徒知道了，就逃往吕高尼的路司得、特庇两个城和周围地方去，","notes":[]},{"n":7,"t":"在那里传福音。","notes":[]},{"n":8,"t":"路司得城里坐着一个两脚无力的人，生来是瘸腿的，从来没有走过。","notes":[],"heads":["在路司得传道"]},{"n":9,"t":"他听保罗讲道，保罗定睛看他，见他有信心，可得痊愈，","notes":[]},{"n":10,"t":"就大声说：「你起来，两脚站直！」那人就跳起来，而且行走。","notes":[]},{"n":11,"t":"众人看见保罗所做的事，就用吕高尼的话大声说：「有神借着人形降临在我们中间了。」","notes":[]},{"n":12,"t":"于是称巴拿巴为宙斯，称保罗为希耳米，因为他说话领首。","notes":[]},{"n":13,"t":"有城外宙斯庙的祭司牵着牛，拿着花圈，来到门前，要同众人向使徒献祭。","notes":[]},{"n":14,"t":"巴拿巴、保罗二使徒听见，就撕开衣裳，跳进众人中间，喊着说：","notes":[]},{"n":15,"t":"「诸君，为什么做这事呢？我们也是人，性情和你们一样。我们传福音给你们，是叫你们离弃这些虚妄，归向那创造天、地、海，和其中万物的永生神。","notes":[]},{"n":16,"t":"他在从前的世代，任凭万国各行其道；","notes":[]},{"n":17,"t":"然而为自己未尝不显出证据来，就如常施恩惠，从天降雨，赏赐丰年，叫你们饮食饱足，满心喜乐。」","notes":[]},{"n":18,"t":"二人说了这些话，仅仅地拦住众人不献祭与他们。","notes":[]},{"n":19,"t":"但有些犹太人从安提阿和以哥念来，挑唆众人，就用石头打保罗，以为他是死了，便拖到城外。","notes":[]},{"n":20,"t":"门徒正围着他，他就起来，走进城去。第二天，同巴拿巴往特庇去，","notes":[]},{"n":21,"t":"对那城里的人传了福音，使好些人作门徒，就回路司得、以哥念、安提阿去，","notes":[]},{"n":22,"t":"坚固门徒的心，劝他们恒守所信的道；又说：「我们进入神的国，必须经历许多艰难。」","notes":[]},{"n":23,"t":"二人在各教会中选立了长老，又禁食祷告，就把他们交托所信的主。","notes":[]},{"n":24,"t":"二人经过彼西底，来到旁非利亚。","notes":[]},{"n":25,"t":"在别加讲了道，就下亚大利去，","notes":[]},{"n":26,"t":"从那里坐船，往安提阿去。当初，他们被众人所托、蒙神之恩、要办现在所做之工，就是在这地方。","notes":[]},{"n":27,"t":"到了那里，聚集了会众，就述说神借他们所行的一切事，并神怎样为外邦人开了信道的门。","notes":[]},{"n":28,"t":"二人就在那里同门徒住了多日。","notes":[]}]},"15":{"heading":"耶路撒冷会议","verses":[{"n":1,"t":"有几个人从犹太下来，教训弟兄们说：「你们若不按摩西的规条受割礼，不能得救。」","notes":[]},{"n":2,"t":"保罗、巴拿巴与他们大大地纷争辩论；众门徒就定规，叫保罗、巴拿巴和本会中几个人，为所辩论的，上耶路撒冷去见使徒和长老。","notes":[]},{"n":3,"t":"于是教会送他们起行。他们经过腓尼基、撒马利亚，随处传说外邦人归主的事，叫众弟兄都甚欢喜。","notes":[]},{"n":4,"t":"到了耶路撒冷，教会和使徒并长老都接待他们，他们就述说神同他们所行的一切事。","notes":[]},{"n":5,"t":"惟有几个信徒是法利赛教门的人，起来说：「必须给外邦人行割礼，吩咐他们遵守摩西的律法。」","notes":[]},{"n":6,"t":"使徒和长老聚会商议这事；","notes":[]},{"n":7,"t":"辩论已经多了，彼得就起来，说：「诸位弟兄，你们知道神早已在你们中间拣选了我，叫外邦人从我口中得听福音之道，而且相信。","notes":[]},{"n":8,"t":"知道人心的神也为他们作了见证，赐圣灵给他们，正如给我们一样；","notes":[]},{"n":9,"t":"又借着信洁净了他们的心，并不分他们我们。","notes":[]},{"n":10,"t":"现在为什么试探神，要把我们祖宗和我们所不能负的轭放在门徒的颈项上呢？","notes":[]},{"n":11,"t":"我们得救乃是因主耶稣的恩，和他们一样，这是我们所信的。」","notes":[]},{"n":12,"t":"众人都默默无声，听巴拿巴和保罗述说神借他们在外邦人中所行的神迹奇事。","notes":[]},{"n":13,"t":"他们住了声，雅各就说：「诸位弟兄，请听我的话。","notes":[]},{"n":14,"t":"方才西门述说神当初怎样眷顾外邦人，从他们中间选取百姓归于自己的名下；","notes":[]},{"n":15,"t":"众先知的话也与这意思相合。","notes":[]},{"n":16,"t":"正如经上所写的：此后，我要回来，重新修造大卫倒塌的帐幕，把那破坏的重新修造建立起来，","notes":[]},{"n":17,"t":"叫余剩的人，就是凡称为我名下的外邦人，都寻求主。","notes":[]},{"n":18,"t":"这话是从创世以来显明这事的主说的。","notes":[]},{"n":19,"t":"「所以据我的意见，不可难为那归服神的外邦人；","notes":[]},{"n":20,"t":"只要写信，吩咐他们禁戒偶像的污秽和奸淫，并勒死的牲畜和血。","notes":[]},{"n":21,"t":"因为从古以来，摩西的书在各城有人传讲，每逢安息日，在会堂里诵读。」","notes":[]},{"n":22,"t":"那时，使徒和长老并全教会定意从他们中间拣选人，差他们和保罗、巴拿巴同往安提阿去；所拣选的就是称呼巴撒巴的犹大和西拉。这两个人在弟兄中是作首领的。","notes":[],"heads":["会议的复函"]},{"n":23,"t":"于是写信交付他们，内中说：「使徒和作长老的弟兄们问安提阿、叙利亚、基利家外邦众弟兄的安。","notes":[]},{"n":24,"t":"我们听说，有几个人从我们这里出去，用言语搅扰你们，惑乱你们的心。其实我们并没有吩咐他们。","notes":["有古卷加：你们必须受割礼，守摩西的律法。"]},{"n":25,"t":"所以，我们同心定意，拣选几个人，差他们同我们所亲爱的巴拿巴和保罗往你们那里去。","notes":[]},{"n":26,"t":"这二人是为我主耶稣基督的名不顾性命的。","notes":[]},{"n":27,"t":"我们就差了犹大和西拉，他们也要亲口诉说这些事。","notes":[]},{"n":28,"t":"因为圣灵和我们定意不将别的重担放在你们身上，惟有几件事是不可少的，","notes":[]},{"n":29,"t":"就是禁戒祭偶像的物和血，并勒死的牲畜和奸淫。这几件你们若能自己禁戒不犯就好了。愿你们平安！」","notes":[]},{"n":30,"t":"他们既奉了差遣，就下安提阿去，聚集众人，交付书信。","notes":[]},{"n":31,"t":"众人念了，因为信上安慰的话就欢喜了。","notes":[]},{"n":32,"t":"犹大和西拉也是先知，就用许多话劝勉弟兄，坚固他们。","notes":[]},{"n":33,"t":"住了些日子，弟兄们打发他们平平安安地回到差遣他们的人那里去。","notes":["有古卷加：34惟有西拉定意仍住在那里。"]},{"n":35,"t":"但保罗和巴拿巴仍住在安提阿，和许多别人一同教训人，传主的道。","notes":[]},{"n":36,"t":"过了些日子，保罗对巴拿巴说：「我们可以回到从前宣传主道的各城，看望弟兄们景况如何。」","notes":[],"heads":["保罗和巴拿巴分手"]},{"n":37,"t":"巴拿巴有意要带称呼马可的约翰同去；","notes":[]},{"n":38,"t":"但保罗因为马可从前在旁非利亚离开他们，不和他们同去做工，就以为不可带他去。","notes":[]},{"n":39,"t":"于是二人起了争论，甚至彼此分开。巴拿巴带着马可，坐船往塞浦路斯去；","notes":[]},{"n":40,"t":"保罗拣选了西拉，也出去，蒙弟兄们把他交于主的恩中。","notes":[]},{"n":41,"t":"他就走遍叙利亚、基利家，坚固众教会。","notes":[]}]},"16":{"heading":"提摩太跟保罗、西拉同工","verses":[{"n":1,"t":"保罗来到特庇，又到路司得。在那里有一个门徒，名叫提摩太，是信主之犹太妇人的儿子，他父亲却是希腊人。","notes":[]},{"n":2,"t":"路司得和以哥念的弟兄都称赞他。","notes":[]},{"n":3,"t":"保罗要带他同去，只因那些地方的犹太人都知道他父亲是希腊人，就给他行了割礼。","notes":[]},{"n":4,"t":"他们经过各城，把耶路撒冷使徒和长老所定的条规交给门徒遵守。","notes":[]},{"n":5,"t":"于是众教会信心越发坚固，人数天天加增。","notes":[]},{"n":6,"t":"圣灵既然禁止他们在亚细亚讲道，他们就经过弗吕家、加拉太一带地方。","notes":[],"heads":["保罗看见马其顿人的异象"]},{"n":7,"t":"到了每西亚的边界，他们想要往庇推尼去，耶稣的灵却不许。","notes":[]},{"n":8,"t":"他们就越过每西亚，下到特罗亚去。","notes":[]},{"n":9,"t":"在夜间有异象现与保罗。有一个马其顿人站着求他说：「请你过到马其顿来帮助我们。」","notes":[]},{"n":10,"t":"保罗既看见这异象，我们随即想要往马其顿去，以为神召我们传福音给那里的人听。","notes":[]},{"n":11,"t":"于是从特罗亚开船，一直行到撒摩特喇，第二天到了尼亚坡里。","notes":[],"heads":["吕底亚归主"]},{"n":12,"t":"从那里来到腓立比，就是马其顿这一方的头一个城，也是罗马的驻防城。我们在这城里住了几天。","notes":[]},{"n":13,"t":"当安息日，我们出城门，到了河边，知道那里有一个祷告的地方，我们就坐下对那聚会的妇女讲道。","notes":[]},{"n":14,"t":"有一个卖紫色布疋的妇人，名叫吕底亚，是推雅推喇城的人，素来敬拜神。她听见了，主就开导她的心，叫她留心听保罗所讲的话。","notes":[]},{"n":15,"t":"她和她一家既领了洗，便求我们说：「你们若以为我是真信主的，请到我家里来住」；于是强留我们。","notes":["或译：你们若以为我是忠心事主的"]},{"n":16,"t":"后来，我们往那祷告的地方去。有一个使女迎着面来，她被巫鬼所附，用法术，叫她主人们大得财利。","notes":[],"heads":["在腓立比被囚"]},{"n":17,"t":"她跟随保罗和我们，喊着说：「这些人是至高神的仆人，对你们传说救人的道。」","notes":[]},{"n":18,"t":"她一连多日这样喊叫，保罗就心中厌烦，转身对那鬼说：「我奉耶稣基督的名，吩咐你从她身上出来！」那鬼当时就出来了。","notes":[]},{"n":19,"t":"使女的主人们见得利的指望没有了，便揪住保罗和西拉，拉他们到市上去见首领；","notes":[]},{"n":20,"t":"又带到官长面前说：「这些人原是犹太人，竟骚扰我们的城，","notes":[]},{"n":21,"t":"传我们罗马人所不可受不可行的规矩。」","notes":[]},{"n":22,"t":"众人就一同起来攻击他们。官长吩咐剥了他们的衣裳，用棍打；","notes":[]},{"n":23,"t":"打了许多棍，便将他们下在监里，嘱咐禁卒严紧看守。","notes":[]},{"n":24,"t":"禁卒领了这样的命，就把他们下在内监里，两脚上了木狗。","notes":[]},{"n":25,"t":"约在半夜，保罗和西拉祷告，唱诗赞美神，众囚犯也侧耳而听。","notes":[]},{"n":26,"t":"忽然，地大震动，甚至监牢的地基都摇动了，监门立刻全开，众囚犯的锁链也都松开了。","notes":[]},{"n":27,"t":"禁卒一醒，看见监门全开，以为囚犯已经逃走，就拔刀要自杀。","notes":[]},{"n":28,"t":"保罗大声呼叫说：「不要伤害自己！我们都在这里。」","notes":[]},{"n":29,"t":"禁卒叫人拿灯来，就跳进去，战战兢兢地俯伏在保罗、西拉面前；","notes":[]},{"n":30,"t":"又领他们出来，说：「二位先生，我当怎样行才可以得救？」","notes":[]},{"n":31,"t":"他们说：「当信主耶稣，你和你一家都必得救。」","notes":[]},{"n":32,"t":"他们就把主的道讲给他和他全家的人听。","notes":[]},{"n":33,"t":"当夜，就在那时候，禁卒把他们带去，洗他们的伤；他和属乎他的人立时都受了洗。","notes":[]},{"n":34,"t":"于是禁卒领他们上自己家里去，给他们摆上饭。他和全家，因为信了神，都很喜乐。","notes":[]},{"n":35,"t":"到了天亮，官长打发差役来，说：「释放那两个人吧。」","notes":[]},{"n":36,"t":"禁卒就把这话告诉保罗说：「官长打发人来叫释放你们，如今可以出监，平平安安地去吧。」","notes":[]},{"n":37,"t":"保罗却说：「我们是罗马人，并没有定罪，他们就在众人面前打了我们，又把我们下在监里，现在要私下撵我们出去吗？这是不行的。叫他们自己来领我们出去吧！」","notes":[]},{"n":38,"t":"差役把这话回禀官长。官长听见他们是罗马人，就害怕了，","notes":[]},{"n":39,"t":"于是来劝他们，领他们出来，请他们离开那城。","notes":[]},{"n":40,"t":"二人出了监，往吕底亚家里去，见了弟兄们，劝慰他们一番，就走了。","notes":[]}]},"17":{"heading":"帖撒罗尼迦的骚动","verses":[{"n":1,"t":"保罗和西拉经过暗妃坡里、亚波罗尼亚，来到帖撒罗尼迦，在那里有犹太人的会堂。","notes":[]},{"n":2,"t":"保罗照他素常的规矩进去，一连三个安息日，本着圣经与他们辩论，","notes":[]},{"n":3,"t":"讲解陈明基督必须受害，从死里复活；又说：「我所传与你们的这位耶稣就是基督。」","notes":[]},{"n":4,"t":"他们中间有些人听了劝，就附从保罗和西拉，并有许多虔敬的希腊人，尊贵的妇女也不少。","notes":[]},{"n":5,"t":"但那不信的犹太人心里嫉妒，招聚了些市井匪类，搭伙成群，耸动合城的人闯进耶孙的家，要将保罗、西拉带到百姓那里。","notes":[]},{"n":6,"t":"找不着他们，就把耶孙和几个弟兄拉到地方官那里，喊叫说：「那搅乱天下的也到这里来了，","notes":[]},{"n":7,"t":"耶孙收留他们。这些人都违背凯撒的命令，说另有一个王耶稣。」","notes":[]},{"n":8,"t":"众人和地方官听见这话，就惊慌了；","notes":[]},{"n":9,"t":"于是取了耶孙和其余之人的保状，就释放了他们。","notes":[]},{"n":10,"t":"弟兄们随即在夜间打发保罗和西拉往庇哩亚去。二人到了，就进入犹太人的会堂。","notes":[],"heads":["使徒们在庇哩亚传道"]},{"n":11,"t":"这地方的人贤于帖撒罗尼迦的人，甘心领受这道，天天考查圣经，要晓得这道是与不是。","notes":[]},{"n":12,"t":"所以他们中间多有相信的，又有希腊尊贵的妇女，男子也不少。","notes":[]},{"n":13,"t":"但帖撒罗尼迦的犹太人知道保罗又在庇哩亚传神的道，也就往那里去，耸动搅扰众人。","notes":[]},{"n":14,"t":"当时弟兄们便打发保罗往海边去，西拉和提摩太仍住在庇哩亚。","notes":[]},{"n":15,"t":"送保罗的人带他到了雅典，既领了保罗的命，叫西拉和提摩太速速到他这里来，就回去了。","notes":[]},{"n":16,"t":"保罗在雅典等候他们的时候，看见满城都是偶像，就心里着急；","notes":[],"heads":["保罗在雅典"]},{"n":17,"t":"于是在会堂里与犹太人和虔敬的人，并每日在市上所遇见的人，辩论。","notes":[]},{"n":18,"t":"还有伊壁鸠鲁和斯多亚两门的学士，与他争论。有的说：「这胡言乱语的要说什么？」有的说：「他似乎是传说外邦鬼神的。」这话是因保罗传讲耶稣与复活的道。","notes":[]},{"n":19,"t":"他们就把他带到亚略·巴古，说：「你所讲的这新道，我们也可以知道吗？","notes":[]},{"n":20,"t":"因为你有些奇怪的事传到我们耳中，我们愿意知道这些事是什么意思。」（","notes":[]},{"n":21,"t":"雅典人和住在那里的客人都不顾别的事，只将新闻说说听听。）","notes":[]},{"n":22,"t":"保罗站在亚略·巴古当中，说：「众位雅典人哪，我看你们凡事很敬畏鬼神。","notes":[]},{"n":23,"t":"我游行的时候，观看你们所敬拜的，遇见一座坛，上面写着『未识之神』。你们所不认识而敬拜的，我现在告诉你们。","notes":[]},{"n":24,"t":"创造宇宙和其中万物的神，既是天地的主，就不住人手所造的殿，","notes":[]},{"n":25,"t":"也不用人手服事，好像缺少什么；自己倒将生命、气息、万物，赐给万人。","notes":[]},{"n":26,"t":"他从一本造出万族的人，住在全地上，并且预先定准他们的年限和所住的疆界，","notes":["本：有古卷是血脉"]},{"n":27,"t":"要叫他们寻求神，或者可以揣摩而得，其实他离我们各人不远；","notes":[]},{"n":28,"t":"我们生活、动作、存留，都在乎他。就如你们作诗的，有人说：『我们也是他所生的。』","notes":[]},{"n":29,"t":"我们既是神所生的，就不当以为神的神性像人用手艺、心思所雕刻的金、银、石。","notes":[]},{"n":30,"t":"世人蒙昧无知的时候，神并不监察，如今却吩咐各处的人都要悔改。","notes":[]},{"n":31,"t":"因为他已经定了日子，要借着他所设立的人按公义审判天下，并且叫他从死里复活，给万人作可信的凭据。」","notes":[]},{"n":32,"t":"众人听见从死里复活的话，就有讥诮他的；又有人说：「我们再听你讲这个吧！」","notes":[]},{"n":33,"t":"于是保罗从他们当中出去了。","notes":[]},{"n":34,"t":"但有几个人贴近他，信了主，其中有亚略·巴古的官丢尼修，并一个妇人，名叫大马哩，还有别人一同信从。","notes":[]}]},"18":{"heading":"保罗在哥林多","verses":[{"n":1,"t":"这事以后，保罗离了雅典，来到哥林多。","notes":[]},{"n":2,"t":"遇见一个犹太人，名叫亚居拉，他生在本都；因为克劳第命犹太人都离开罗马，新近带着妻百基拉，从意大利来。保罗就投奔了他们。","notes":[]},{"n":3,"t":"他们本是制造帐棚为业。保罗因与他们同业，就和他们同住做工。","notes":[]},{"n":4,"t":"每逢安息日，保罗在会堂里辩论，劝化犹太人和希腊人。","notes":[]},{"n":5,"t":"西拉和提摩太从马其顿来的时候，保罗为道迫切，向犹太人证明耶稣是基督。","notes":[]},{"n":6,"t":"他们既抗拒、毁谤，保罗就抖着衣裳，说：「你们的罪归到你们自己头上，与我无干。从今以后，我要往外邦人那里去。」","notes":["原文是血","原文是我却干净"]},{"n":7,"t":"于是离开那里，到了一个人的家中；这人名叫提多·犹士都，是敬拜神的，他的家靠近会堂。","notes":[]},{"n":8,"t":"管会堂的基利司布和全家都信了主，还有许多哥林多人听了，就相信受洗。","notes":[]},{"n":9,"t":"夜间，主在异象中对保罗说：「不要怕，只管讲，不要闭口，","notes":[]},{"n":10,"t":"有我与你同在，必没有人下手害你，因为在这城里我有许多的百姓。」","notes":[]},{"n":11,"t":"保罗在那里住了一年零六个月，将神的道教训他们。","notes":[]},{"n":12,"t":"到迦流作亚该亚方伯的时候，犹太人同心起来攻击保罗，拉他到公堂，","notes":[]},{"n":13,"t":"说：「这个人劝人不按着律法敬拜神。」","notes":[]},{"n":14,"t":"保罗刚要开口，迦流就对犹太人说：「你们这些犹太人！如果是为冤枉或奸恶的事，我理当耐性听你们。","notes":[]},{"n":15,"t":"但所争论的，若是关乎言语、名目，和你们的律法，你们自己去办吧！这样的事我不愿意审问」；","notes":[]},{"n":16,"t":"就把他们撵出公堂。","notes":[]},{"n":17,"t":"众人便揪住管会堂的所提尼，在堂前打他。这些事迦流都不管。","notes":[]},{"n":18,"t":"保罗又住了多日，就辞别了弟兄，坐船往叙利亚去；百基拉、亚居拉和他同去。他因为许过愿，就在坚革哩剪了头发。","notes":[],"heads":["保罗回到安提阿"]},{"n":19,"t":"到了以弗所，保罗就把他们留在那里，自己进了会堂，和犹太人辩论。","notes":[]},{"n":20,"t":"众人请他多住些日子，他却不允，","notes":[]},{"n":21,"t":"就辞别他们，说：「神若许我，我还要回到你们这里」；于是开船离了以弗所。","notes":[]},{"n":22,"t":"在凯撒利亚下了船，就上耶路撒冷去问教会安，随后下安提阿去。","notes":[]},{"n":23,"t":"住了些日子，又离开那里，挨次经过加拉太和弗吕家地方，坚固众门徒。","notes":[]},{"n":24,"t":"有一个犹太人，名叫亚波罗，来到以弗所。他生在亚历山大，是有学问的，最能讲解圣经。","notes":["或译：口才"],"heads":["亚波罗在以弗所讲道"]},{"n":25,"t":"这人已经在主的道上受了教训，心里火热，将耶稣的事详细讲论教训人；只是他单晓得约翰的洗礼。","notes":[]},{"n":26,"t":"他在会堂里放胆讲道；百基拉、亚居拉听见，就接他来，将神的道给他讲解更加详细。","notes":[]},{"n":27,"t":"他想要往亚该亚去，弟兄们就勉励他，并写信请门徒接待他。他到了那里，多帮助那蒙恩信主的人，","notes":["或译：弟兄们就写信劝门徒接待他"]},{"n":28,"t":"在众人面前极有能力驳倒犹太人，引圣经证明耶稣是基督。","notes":[]}]},"19":{"heading":"保罗在以弗所","verses":[{"n":1,"t":"亚波罗在哥林多的时候，保罗经过了上边一带地方，就来到以弗所；在那里遇见几个门徒，","notes":[]},{"n":2,"t":"问他们说：「你们信的时候受了圣灵没有？」他们回答说：「没有，也未曾听见有圣灵赐下来。」","notes":[]},{"n":3,"t":"保罗说：「这样，你们受的是什么洗呢？」他们说：「是约翰的洗。」","notes":[]},{"n":4,"t":"保罗说：「约翰所行的是悔改的洗，告诉百姓当信那在他以后要来的，就是耶稣。」","notes":[]},{"n":5,"t":"他们听见这话，就奉主耶稣的名受洗。","notes":[]},{"n":6,"t":"保罗按手在他们头上，圣灵便降在他们身上，他们就说方言，又说预言。","notes":["或译：又讲道"]},{"n":7,"t":"一共约有十二个人。","notes":[]},{"n":8,"t":"保罗进会堂，放胆讲道，一连三个月，辩论神国的事，劝化众人。","notes":[]},{"n":9,"t":"后来，有些人心里刚硬不信，在众人面前毁谤这道，保罗就离开他们，也叫门徒与他们分离，便在推喇奴的学房天天辩论。","notes":[]},{"n":10,"t":"这样有两年之久，叫一切住在亚细亚的，无论是犹太人，是希腊人，都听见主的道。","notes":[]},{"n":11,"t":"神借保罗的手行了些非常的奇事；","notes":[],"heads":["士基瓦的儿子们"]},{"n":12,"t":"甚至有人从保罗身上拿手巾或围裙放在病人身上，病就退了，恶鬼也出去了。","notes":[]},{"n":13,"t":"那时，有几个游行各处、念咒赶鬼的犹太人，向那被恶鬼附的人擅自称主耶稣的名，说：「我奉保罗所传的耶稣敕令你们出来！」","notes":[]},{"n":14,"t":"做这事的，有犹太祭司长士基瓦的七个儿子。","notes":[]},{"n":15,"t":"恶鬼回答他们说：「耶稣我认识，保罗我也知道。你们却是谁呢？」","notes":[]},{"n":16,"t":"恶鬼所附的人就跳在他们身上，胜了其中二人，制伏他们，叫他们赤着身子受了伤，从那房子里逃出去了。","notes":[]},{"n":17,"t":"凡住在以弗所的，无论是犹太人，是希腊人，都知道这事，也都惧怕；主耶稣的名从此就尊大了。","notes":[]},{"n":18,"t":"那已经信的，多有人来承认诉说自己所行的事。","notes":[]},{"n":19,"t":"平素行邪术的，也有许多人把书拿来，堆积在众人面前焚烧。他们算计书价，便知道共合五万块钱。","notes":[]},{"n":20,"t":"主的道大大兴旺，而且得胜，就是这样。","notes":[]},{"n":21,"t":"这些事完了，保罗心里定意经过了马其顿、亚该亚，就往耶路撒冷去；又说：「我到了那里以后，也必须往罗马去看看。」","notes":[],"heads":["以弗所的暴动"]},{"n":22,"t":"于是从帮助他的人中打发提摩太、以拉都二人往马其顿去，自己暂时等在亚细亚。","notes":[]},{"n":23,"t":"那时，因为这道起的扰乱不小。","notes":[]},{"n":24,"t":"有一个银匠，名叫底米丢，是制造亚底米神银龛的，他使这样手艺人生意发达。","notes":[]},{"n":25,"t":"他聚集他们和同行的工人，说：「众位，你们知道我们是倚靠这生意发财。","notes":[]},{"n":26,"t":"这保罗不但在以弗所，也几乎在亚细亚全地，引诱迷惑许多人，说：『人手所做的，不是神。』这是你们所看见所听见的。","notes":[]},{"n":27,"t":"这样，不独我们这事业被人藐视，就是大女神亚底米的庙也要被人轻忽，连亚细亚全地和普天下所敬拜的大女神之威荣也要消灭了。」","notes":[]},{"n":28,"t":"众人听见，就怒气填胸，喊着说：「大哉，以弗所人的亚底米啊！」","notes":[]},{"n":29,"t":"满城都轰动起来。众人拿住与保罗同行的马其顿人该犹和亚里达古，齐心拥进戏园里去。","notes":[]},{"n":30,"t":"保罗想要进去，到百姓那里，门徒却不许他去。","notes":[]},{"n":31,"t":"还有亚细亚几位首领，是保罗的朋友，打发人来劝他，不要冒险到戏园里去。","notes":[]},{"n":32,"t":"聚集的人纷纷乱乱，有喊叫这个的，有喊叫那个的；大半不知道是为什么聚集。","notes":[]},{"n":33,"t":"有人把亚历山大从众人中带出来，犹太人推他往前，亚历山大就摆手，要向百姓分诉；","notes":[]},{"n":34,"t":"只因他们认出他是犹太人，就大家同声喊着说：「大哉！以弗所人的亚底米啊。」如此约有两小时。","notes":[]},{"n":35,"t":"那城里的书记安抚了众人，就说：「以弗所人哪，谁不知道以弗所人的城是看守大亚底米的庙和从宙斯那里落下来的像呢？","notes":[]},{"n":36,"t":"这事既是驳不倒的，你们就当安静，不可造次。","notes":[]},{"n":37,"t":"你们把这些人带来，他们并没有偷窃庙中之物，也没有谤讟我们的女神。","notes":[]},{"n":38,"t":"若是底米丢和他同行的人有控告人的事，自有放告的日子，也有方伯可以彼此对告。","notes":["或译：自有公堂"]},{"n":39,"t":"你们若问别的事，就可以照常例聚集断定。","notes":[]},{"n":40,"t":"今日的扰乱本是无缘无故，我们难免被查问。论到这样聚众，我们也说不出所以然来。」","notes":[]},{"n":41,"t":"说了这话，便叫众人散去。","notes":[]}]},"20":{"heading":"保罗再访问马其顿和希腊","verses":[{"n":1,"t":"乱定之后，保罗请门徒来，劝勉他们，就辞别起行，往马其顿去。","notes":[]},{"n":2,"t":"走遍了那一带地方，用许多话劝勉门徒，然后来到希腊。","notes":["或译：众人"]},{"n":3,"t":"在那里住了三个月，将要坐船往叙利亚去，犹太人设计要害他，他就定意从马其顿回去。","notes":[]},{"n":4,"t":"同他到亚细亚去的，有庇哩亚人毕罗斯的儿子所巴特，帖撒罗尼迦人亚里达古和西公都，还有特庇人该犹，并提摩太，又有亚细亚人推基古和特罗非摩。","notes":[]},{"n":5,"t":"这些人先走，在特罗亚等候我们。","notes":[]},{"n":6,"t":"过了除酵的日子，我们从腓立比开船，五天到了特罗亚，和他们相会，在那里住了七天。","notes":[]},{"n":7,"t":"七日的第一日，我们聚会擘饼的时候，保罗因为要次日起行，就与他们讲论，直讲到半夜。","notes":[],"heads":["保罗最后一次访问特罗亚"]},{"n":8,"t":"我们聚会的那座楼上，有好些灯烛。","notes":[]},{"n":9,"t":"有一个少年人，名叫犹推古，坐在窗台上，困倦沉睡。保罗讲了多时，少年人睡熟了，就从三层楼上掉下去；扶起他来，已经死了。","notes":[]},{"n":10,"t":"保罗下去，伏在他身上，抱着他，说：「你们不要发慌，他的灵魂还在身上。」","notes":[]},{"n":11,"t":"保罗又上去，擘饼，吃了，谈论许久，直到天亮，这才走了。","notes":[]},{"n":12,"t":"有人把那童子活活地领来，得的安慰不小。","notes":[]},{"n":13,"t":"我们先上船，开往亚朔去，意思要在那里接保罗；因为他是这样安排的，他自己打算要步行。","notes":[],"heads":["从特罗亚到米利都"]},{"n":14,"t":"他既在亚朔与我们相会，我们就接他上船，来到米推利尼。","notes":[]},{"n":15,"t":"从那里开船，次日到了基阿的对面；又次日，在撒摩靠岸；又次日，来到米利都。","notes":[]},{"n":16,"t":"乃因保罗早已定意越过以弗所，免得在亚细亚耽延，他急忙前走，巴不得赶五旬节能到耶路撒冷。","notes":[]},{"n":17,"t":"保罗从米利都打发人往以弗所去，请教会的长老来。","notes":[],"heads":["保罗向以弗所长老发表谈话"]},{"n":18,"t":"他们来了，保罗就说：「你们知道，自从我到亚细亚的日子以来，在你们中间始终为人如何，","notes":[]},{"n":19,"t":"服事主，凡事谦卑，眼中流泪，又因犹太人的谋害，经历试炼。","notes":[]},{"n":20,"t":"你们也知道，凡与你们有益的，我没有一样避讳不说的，或在众人面前，或在各人家里，我都教导你们；","notes":[]},{"n":21,"t":"又对犹太人和希腊人证明当向神悔改，信靠我主耶稣基督。","notes":[]},{"n":22,"t":"现在我往耶路撒冷去，心甚迫切，不知道在那里要遇见什么事；","notes":["原文是心被捆绑"]},{"n":23,"t":"但知道圣灵在各城里向我指证，说有捆锁与患难等待我。","notes":[]},{"n":24,"t":"我却不以性命为念，也不看为宝贵，只要行完我的路程，成就我从主耶稣所领受的职事，证明神恩惠的福音。","notes":[]},{"n":25,"t":"「我素常在你们中间来往，传讲神国的道；如今我晓得，你们以后都不得再见我的面了。","notes":[]},{"n":26,"t":"所以我今日向你们证明，你们中间无论何人死亡，罪不在我身上。","notes":["原文是我于众人的血是洁净的"]},{"n":27,"t":"因为神的旨意，我并没有一样避讳不传给你们的。","notes":[]},{"n":28,"t":"圣灵立你们作全群的监督，你们就当为自己谨慎，也为全群谨慎，牧养神的教会，就是他用自己血所买来的。","notes":["或译：救赎的"]},{"n":29,"t":"我知道，我去之后必有凶暴的豺狼进入你们中间，不爱惜羊群。","notes":[]},{"n":30,"t":"就是你们中间，也必有人起来说悖谬的话，要引诱门徒跟从他们。","notes":[]},{"n":31,"t":"所以你们应当警醒，记念我三年之久昼夜不住地流泪、劝戒你们各人。","notes":[]},{"n":32,"t":"如今我把你们交托神和他恩惠的道；这道能建立你们，叫你们和一切成圣的人同得基业。","notes":[]},{"n":33,"t":"我未曾贪图一个人的金、银、衣服。","notes":[]},{"n":34,"t":"我这两只手常供给我和同人的需用，这是你们自己知道的。","notes":[]},{"n":35,"t":"我凡事给你们作榜样，叫你们知道应当这样劳苦，扶助软弱的人，又当记念主耶稣的话，说：『施比受更为有福。』」","notes":[]},{"n":36,"t":"保罗说完了这话，就跪下同众人祷告。","notes":[]},{"n":37,"t":"众人痛哭，抱着保罗的颈项，和他亲嘴。","notes":[]},{"n":38,"t":"叫他们最伤心的，就是他说「以后不能再见我的面」那句话，于是送他上船去了。","notes":[]}]},"21":{"heading":"保罗上耶路撒冷","verses":[{"n":1,"t":"我们离别了众人，就开船一直行到哥士。第二天到了罗底，从那里到帕大喇，","notes":[]},{"n":2,"t":"遇见一只船要往腓尼基去，就上船起行。","notes":[]},{"n":3,"t":"望见塞浦路斯，就从南边行过，往叙利亚去，我们就在泰尔上岸，因为船要在那里卸货。","notes":[]},{"n":4,"t":"找着了门徒，就在那里住了七天。他们被圣灵感动，对保罗说：「不要上耶路撒冷去。」","notes":[]},{"n":5,"t":"过了这几天，我们就起身前行。他们众人同妻子儿女，送我们到城外，我们都跪在岸上祷告，彼此辞别。","notes":[]},{"n":6,"t":"我们上了船，他们就回家去了。","notes":[]},{"n":7,"t":"我们从泰尔行尽了水路，来到多利买，就问那里的弟兄安，和他们同住了一天。","notes":[]},{"n":8,"t":"第二天，我们离开那里，来到凯撒利亚，就进了传福音的腓利家里，和他同住。他是那七个执事里的一个。","notes":[]},{"n":9,"t":"他有四个女儿，都是处女，是说预言的。","notes":[]},{"n":10,"t":"我们在那里多住了几天，有一个先知，名叫亚迦布，从犹太下来，","notes":[]},{"n":11,"t":"到了我们这里，就拿保罗的腰带捆上自己的手脚，说：「圣灵说：犹太人在耶路撒冷，要如此捆绑这腰带的主人，把他交在外邦人手里。」","notes":[]},{"n":12,"t":"我们和那本地的人听见这话，都苦劝保罗不要上耶路撒冷去。","notes":[]},{"n":13,"t":"保罗说：「你们为什么这样痛哭，使我心碎呢？我为主耶稣的名，不但被人捆绑，就是死在耶路撒冷也是愿意的。」","notes":[]},{"n":14,"t":"保罗既不听劝，我们便住了口，只说：「愿主的旨意成就」，便了。","notes":[]},{"n":15,"t":"过了几日，我们收拾行李上耶路撒冷去。","notes":[]},{"n":16,"t":"有凯撒利亚的几个门徒和我们同去，带我们到一个久为门徒的家里，叫我们与他同住；他名叫拿孙，是塞浦路斯人。","notes":["久为：或译老"]},{"n":17,"t":"到了耶路撒冷，弟兄们欢欢喜喜地接待我们。","notes":[],"heads":["保罗访问雅各"]},{"n":18,"t":"第二天，保罗同我们去见雅各；长老们也都在那里。","notes":[]},{"n":19,"t":"保罗问了他们安，便将神用他传教，在外邦人中间所行之事，一一地述说了。","notes":[]},{"n":20,"t":"他们听见，就归荣耀与神，对保罗说：「兄台，你看犹太人中信主的有多少万，并且都为律法热心。","notes":[]},{"n":21,"t":"他们听见人说，你教训一切在外邦的犹太人离弃摩西，对他们说，不要给孩子行割礼，也不要遵行条规。","notes":[]},{"n":22,"t":"众人必听见你来了，这可怎么办呢？","notes":[]},{"n":23,"t":"你就照着我们的话行吧！我们这里有四个人，都有愿在身。","notes":[]},{"n":24,"t":"你带他们去，与他们一同行洁净的礼，替他们拿出规费，叫他们得以剃头。这样，众人就可知道，先前所听见你的事都是虚的；并可知道，你自己为人，循规蹈矩，遵行律法。","notes":[]},{"n":25,"t":"至于信主的外邦人，我们已经写信拟定，叫他们谨忌那祭偶像之物，和血，并勒死的牲畜，与奸淫。」","notes":[]},{"n":26,"t":"于是保罗带着那四个人，第二天与他们一同行了洁净的礼，进了殿，报明洁净的日期满足，只等祭司为他们各人献祭。","notes":[]},{"n":27,"t":"那七日将完，从亚细亚来的犹太人看见保罗在殿里，就耸动了众人，下手拿他，","notes":[],"heads":["保罗在圣殿里被捕"]},{"n":28,"t":"喊叫说：「以色列人来帮助，这就是在各处教训众人糟践我们百姓和律法，并这地方的。他又带着希腊人进殿，污秽了这圣地。」（","notes":[]},{"n":29,"t":"这话是因他们曾看见以弗所人特罗非摩同保罗在城里，以为保罗带他进了殿。）","notes":[]},{"n":30,"t":"合城都震动，百姓一齐跑来，拿住保罗，拉他出殿，殿门立刻都关了。","notes":[]},{"n":31,"t":"他们正想要杀他，有人报信给营里的千夫长说：「耶路撒冷合城都乱了。」","notes":[]},{"n":32,"t":"千夫长立时带着兵丁和几个百夫长，跑下去到他们那里。他们见了千夫长和兵丁，就止住不打保罗。","notes":[]},{"n":33,"t":"于是千夫长上前拿住他，吩咐用两条铁链捆锁；又问他是什么人，做的是什么事。","notes":[]},{"n":34,"t":"众人有喊叫这个的，有喊叫那个的；千夫长因为这样乱嚷，得不着实情，就吩咐人将保罗带进营楼去。","notes":[]},{"n":35,"t":"到了台阶上，众人挤得凶猛，兵丁只得将保罗抬起来。","notes":[]},{"n":36,"t":"众人跟在后面，喊着说：「除掉他！」","notes":[]},{"n":37,"t":"将要带他进营楼，保罗对千夫长说：「我对你说句话可以不可以？」他说：「你懂得希腊话吗？","notes":[],"heads":["保罗为自己辩护"]},{"n":38,"t":"你莫非是从前作乱、带领四千凶徒往旷野去的那埃及人吗？」","notes":[]},{"n":39,"t":"保罗说：「我本是犹太人，生在基利家的大数，并不是无名小城的人。求你准我对百姓说话。」","notes":[]},{"n":40,"t":"千夫长准了。保罗就站在台阶上，向百姓摆手，他们都静默无声，保罗便用希伯来话对他们说：","notes":[]}]},"22":{"heading":"保罗叙述归主的经过","verses":[{"n":1,"t":"「诸位父兄请听，我现在对你们分诉。」","notes":[]},{"n":2,"t":"众人听他说的是希伯来话，就更加安静了。","notes":[]},{"n":3,"t":"保罗说：「我原是犹太人，生在基利家的大数，长在这城里，在迦玛列门下，按着我们祖宗严紧的律法受教，热心事奉神，像你们众人今日一样。","notes":[]},{"n":4,"t":"我也曾逼迫奉这道的人，直到死地，无论男女都锁拿下监。","notes":[]},{"n":5,"t":"这是大祭司和众长老都可以给我作见证的。我又领了他们达与弟兄的书信，往大马士革去，要把在那里奉这道的人锁拿，带到耶路撒冷受刑。」","notes":[]},{"n":6,"t":"「我将到大马士革，正走的时候，约在晌午，忽然从天上发大光，四面照着我。","notes":[]},{"n":7,"t":"我就仆倒在地，听见有声音对我说：『扫罗！扫罗！你为什么逼迫我？』","notes":[]},{"n":8,"t":"我回答说：『主啊，你是谁？』他说：『我就是你所逼迫的拿撒勒人耶稣。』","notes":[]},{"n":9,"t":"与我同行的人看见了那光，却没有听明那位对我说话的声音。","notes":[]},{"n":10,"t":"我说：『主啊，我当做什么？』主说：『起来，进大马士革去，在那里，要将所派你做的一切事告诉你。』","notes":[]},{"n":11,"t":"我因那光的荣耀不能看见，同行的人就拉着我手进了大马士革。","notes":[]},{"n":12,"t":"那里有一个人，名叫亚拿尼亚，按着律法是虔诚人，为一切住在那里的犹太人所称赞。","notes":[]},{"n":13,"t":"他来见我，站在旁边，对我说：『兄弟扫罗，你可以看见。』我当时往上一看，就看见了他。","notes":[]},{"n":14,"t":"他又说：『我们祖宗的神拣选了你，叫你明白他的旨意，又得见那义者，听他口中所出的声音。","notes":[]},{"n":15,"t":"因为你要将所看见的，所听见的，对着万人为他作见证。","notes":[]},{"n":16,"t":"现在你为什么耽延呢？起来，求告他的名受洗，洗去你的罪。』」","notes":[]},{"n":17,"t":"「后来，我回到耶路撒冷，在殿里祷告的时候，魂游象外，","notes":[],"heads":["保罗奉召向外邦人传道"]},{"n":18,"t":"看见主向我说：『你赶紧地离开耶路撒冷，不可迟延；因你为我作的见证，这里的人必不领受。』","notes":[]},{"n":19,"t":"我就说：『主啊，他们知道我从前把信你的人收在监里，又在各会堂里鞭打他们。","notes":[]},{"n":20,"t":"并且你的见证人司提反被害流血的时候，我也站在旁边欢喜；又看守害死他之人的衣裳。』","notes":[]},{"n":21,"t":"主向我说：『你去吧！我要差你远远地往外邦人那里去。』」","notes":[]},{"n":22,"t":"众人听他说到这句话，就高声说：「这样的人，从世上除掉他吧！他是不当活着的。」","notes":[],"heads":["保罗与长官交涉"]},{"n":23,"t":"众人喧嚷，摔掉衣裳，把尘土向空中扬起来。","notes":[]},{"n":24,"t":"千夫长就吩咐将保罗带进营楼去，叫人用鞭子拷问他，要知道他们向他这样喧嚷是为什么缘故。","notes":[]},{"n":25,"t":"刚用皮条捆上，保罗对旁边站着的百夫长说：「人是罗马人，又没有定罪，你们就鞭打他，有这个例吗？」","notes":[]},{"n":26,"t":"百夫长听见这话，就去见千夫长，告诉他说：「你要做什么？这人是罗马人。」","notes":[]},{"n":27,"t":"千夫长就来问保罗说：「你告诉我，你是罗马人吗？」保罗说：「是。」","notes":[]},{"n":28,"t":"千夫长说：「我用许多银子才入了罗马的民籍。」保罗说：「我生来就是。」","notes":[]},{"n":29,"t":"于是那些要拷问保罗的人就离开他去了。千夫长既知道他是罗马人，又因为捆绑了他，也害怕了。","notes":[]},{"n":30,"t":"第二天，千夫长为要知道犹太人控告保罗的实情，便解开他，吩咐祭司长和全公会的人都聚集，将保罗带下来，叫他站在他们面前。","notes":[],"heads":["保罗在公会前申诉"]}]},"23":{"heading":"杀害保罗的阴谋","verses":[{"n":1,"t":"保罗定睛看着公会的人，说：「弟兄们，我在神面前行事为人都是凭着良心，直到今日。」","notes":[]},{"n":2,"t":"大祭司亚拿尼亚就吩咐旁边站着的人打他的嘴。","notes":[]},{"n":3,"t":"保罗对他说：「你这粉饰的墙，神要打你！你坐堂为的是按律法审问我，你竟违背律法，吩咐人打我吗？」","notes":[]},{"n":4,"t":"站在旁边的人说：「你辱骂神的大祭司吗？」","notes":[]},{"n":5,"t":"保罗说：「弟兄们，我不晓得他是大祭司；经上记着说：『不可毁谤你百姓的官长。』」","notes":[]},{"n":6,"t":"保罗看出大众一半是撒都该人，一半是法利赛人，就在公会中大声说：「弟兄们，我是法利赛人，也是法利赛人的子孙。我现在受审问，是为盼望死人复活。」","notes":[]},{"n":7,"t":"说了这话，法利赛人和撒都该人就争论起来，会众分为两党。","notes":[]},{"n":8,"t":"因为撒都该人说，没有复活，也没有天使和鬼魂；法利赛人却说，两样都有。","notes":[]},{"n":9,"t":"于是大大地喧嚷起来。有几个法利赛党的文士站起来争辩说：「我们看不出这人有什么恶处，倘若有鬼魂或是天使对他说过话，怎么样呢？」","notes":[]},{"n":10,"t":"那时大起争吵，千夫长恐怕保罗被他们扯碎了，就吩咐兵丁下去，把他从众人当中抢出来，带进营楼去。","notes":[]},{"n":11,"t":"当夜，主站在保罗旁边，说：「放心吧！你怎样在耶路撒冷为我作见证，也必怎样在罗马为我作见证。」","notes":[]},{"n":12,"t":"到了天亮，犹太人同谋起誓，说：「若不先杀保罗就不吃不喝。」","notes":[]},{"n":13,"t":"这样同心起誓的有四十多人。","notes":[]},{"n":14,"t":"他们来见祭司长和长老，说：「我们已经起了一个大誓，若不先杀保罗就不吃什么。","notes":[]},{"n":15,"t":"现在你们和公会要知会千夫长，叫他带下保罗到你们这里来，假作要详细察考他的事；我们已经预备好了，不等他来到跟前就杀他。」","notes":[]},{"n":16,"t":"保罗的外甥听见他们设下埋伏，就来到营楼里告诉保罗。","notes":[]},{"n":17,"t":"保罗请一个百夫长来，说：「你领这少年人去见千夫长，他有事告诉他。」","notes":[]},{"n":18,"t":"于是把他领去见千夫长，说：「被囚的保罗请我到他那里，求我领这少年人来见你；他有事告诉你。」","notes":[]},{"n":19,"t":"千夫长就拉着他的手，走到一旁，私下问他说：「你有什么事告诉我呢？」","notes":[]},{"n":20,"t":"他说：「犹太人已经约定，要求你明天带下保罗到公会里去，假作要详细查问他的事。","notes":[]},{"n":21,"t":"你切不要随从他们；因为他们有四十多人埋伏，已经起誓说，若不先杀保罗就不吃不喝。现在预备好了，只等你应允。」","notes":[]},{"n":22,"t":"于是千夫长打发少年人走，嘱咐他说：「不要告诉人你将这事报给我了。」","notes":[]},{"n":23,"t":"千夫长便叫了两个百夫长来，说：「预备步兵二百，马兵七十，长枪手二百，今夜亥初往凯撒利亚去；","notes":[],"heads":["保罗被解交腓力斯巡抚"]},{"n":24,"t":"也要预备牲口叫保罗骑上，护送到巡抚腓力斯那里去。」","notes":[]},{"n":25,"t":"千夫长又写了文书，","notes":[]},{"n":26,"t":"大略说：「克劳第·吕西亚，请巡抚腓力斯大人安。","notes":[]},{"n":27,"t":"这人被犹太人拿住，将要杀害，我得知他是罗马人，就带兵丁下去救他出来。","notes":[]},{"n":28,"t":"因要知道他们告他的缘故，我就带他下到他们的公会去，","notes":[]},{"n":29,"t":"便查知他被告是因他们律法的辩论，并没有什么该死该绑的罪名。","notes":[]},{"n":30,"t":"后来有人把要害他的计谋告诉我，我就立时解他到你那里去，又吩咐告他的人在你面前告他。」","notes":["有古卷加：愿你平安！"]},{"n":31,"t":"于是，兵丁照所吩咐他们的，将保罗夜里带到安提帕底。","notes":[]},{"n":32,"t":"第二天，让马兵护送，他们就回营楼去。","notes":[]},{"n":33,"t":"马兵来到凯撒利亚，把文书呈给巡抚，便叫保罗站在他面前。","notes":[]},{"n":34,"t":"巡抚看了文书，问保罗是哪省的人，既晓得他是基利家人，","notes":[]},{"n":35,"t":"就说：「等告你的人来到，我要细听你的事」；便吩咐人把他看守在希律的衙门里。","notes":[]}]},"24":{"heading":"犹太人控告保罗","verses":[{"n":1,"t":"过了五天，大祭司亚拿尼亚同几个长老，和一个辩士帖土罗下来，向巡抚控告保罗。","notes":[]},{"n":2,"t":"保罗被提了来，帖土罗就告他说：","notes":[]},{"n":3,"t":"「腓力斯大人，我们因你得以大享太平，并且这一国的弊病，因着你的先见得以更正了；我们随时随地满心感谢不尽。","notes":[]},{"n":4,"t":"惟恐多说，你嫌烦絮，只求你宽容听我们说几句话。","notes":[]},{"n":5,"t":"我们看这个人，如同瘟疫一般，是鼓动普天下众犹太人生乱的，又是拿撒勒教党里的一个头目，","notes":[]},{"n":6,"t":"连圣殿他也想要污秽；我们把他捉住了。","notes":["有古卷加：要按我们的律法审问，7不料，千夫长吕西亚前来，甚是强横，从我们手中把他夺去，吩咐告他的人到你这里来。"]},{"n":8,"t":"你自己究问他，就可以知道我们告他的一切事了。」","notes":[]},{"n":9,"t":"众犹太人也随着告他说：「事情诚然是这样。」","notes":[]},{"n":10,"t":"巡抚点头叫保罗说话。他就说：「我知道你在这国里断事多年，所以我乐意为自己分诉。","notes":[],"heads":["保罗为自己辩护"]},{"n":11,"t":"你查问就可以知道，从我上耶路撒冷礼拜到今日不过有十二天。","notes":[]},{"n":12,"t":"他们并没有看见我在殿里，或是在会堂里，或是在城里，和人辩论，耸动众人。","notes":[]},{"n":13,"t":"他们现在所告我的事并不能对你证实了。","notes":[]},{"n":14,"t":"但有一件事，我向你承认，就是他们所称为异端的道，我正按着那道事奉我祖宗的神，又信合乎律法的和先知书上一切所记载的，","notes":[]},{"n":15,"t":"并且靠着神，盼望死人，无论善恶，都要复活，就是他们自己也有这个盼望。","notes":[]},{"n":16,"t":"我因此自己勉励，对神对人，常存无亏的良心。","notes":[]},{"n":17,"t":"过了几年，我带着周济本国的捐项和供献的物上去。","notes":[]},{"n":18,"t":"正献的时候，他们看见我在殿里已经洁净了，并没有聚众，也没有吵嚷，惟有几个从亚细亚来的犹太人。","notes":[]},{"n":19,"t":"他们若有告我的事，就应当到你面前来告我。","notes":[]},{"n":20,"t":"即或不然，这些人若看出我站在公会前，有妄为的地方，他们自己也可以说明。","notes":[]},{"n":21,"t":"纵然有，也不过一句话，就是我站在他们中间大声说：『我今日在你们面前受审，是为死人复活的道理。』」","notes":[]},{"n":22,"t":"腓力斯本是详细晓得这道，就支吾他们说：「且等千夫长吕西亚下来，我要审断你们的事。」","notes":[]},{"n":23,"t":"于是吩咐百夫长看守保罗，并且宽待他，也不拦阻他的亲友来供给他。","notes":[]},{"n":24,"t":"过了几天，腓力斯和他夫人—犹太的女子土西拉—一同来到，就叫了保罗来，听他讲论信基督耶稣的道。","notes":[],"heads":["腓力斯留保罗在监里"]},{"n":25,"t":"保罗讲论公义、节制，和将来的审判。腓力斯甚觉恐惧，说：「你暂且去吧，等我得便再叫你来。」","notes":[]},{"n":26,"t":"腓力斯又指望保罗送他银钱，所以屡次叫他来，和他谈论。","notes":[]},{"n":27,"t":"过了两年，波求·非斯都接了腓力斯的任；腓力斯要讨犹太人的喜欢，就留保罗在监里。","notes":[]}]},"25":{"heading":"保罗要向凯撒上诉","verses":[{"n":1,"t":"非斯都到了任，过了三天，就从凯撒利亚上耶路撒冷去。","notes":[]},{"n":2,"t":"祭司长和犹太人的首领向他控告保罗，","notes":[]},{"n":3,"t":"又央告他，求他的情，将保罗提到耶路撒冷来，他们要在路上埋伏杀害他。","notes":[]},{"n":4,"t":"非斯都却回答说：「保罗押在凯撒利亚，我自己快要往那里去」；","notes":[]},{"n":5,"t":"又说：「你们中间有权势的人与我一同下去，那人若有什么不是，就可以告他。」","notes":[]},{"n":6,"t":"非斯都在他们那里住了不过十天八天，就下凯撒利亚去；第二天坐堂，吩咐将保罗提上来。","notes":[]},{"n":7,"t":"保罗来了，那些从耶路撒冷下来的犹太人周围站着，将许多重大的事控告他，都是不能证实的。","notes":[]},{"n":8,"t":"保罗分诉说：「无论犹太人的律法，或是圣殿，或是凯撒，我都没有干犯。」","notes":[]},{"n":9,"t":"但非斯都要讨犹太人的喜欢，就问保罗说：「你愿意上耶路撒冷去，在那里听我审断这事吗？」","notes":[]},{"n":10,"t":"保罗说：「我站在凯撒的堂前，这就是我应当受审的地方。我向犹太人并没有行过什么不义的事，这也是你明明知道的。","notes":[]},{"n":11,"t":"我若行了不义的事，犯了什么该死的罪，就是死，我也不辞。他们所告我的事若都不实，就没有人可以把我交给他们。我要上告于凯撒。」","notes":[]},{"n":12,"t":"非斯都和议会商量了，就说：「你既上告于凯撒，可以往凯撒那里去。」","notes":[]},{"n":13,"t":"过了些日子，亚基帕王和百妮基氏来到凯撒利亚，问非斯都安。","notes":[],"heads":["保罗被带到亚基帕王面前"]},{"n":14,"t":"在那里住了多日，非斯都将保罗的事告诉王，说：「这里有一个人，是腓力斯留在监里的。","notes":[]},{"n":15,"t":"我在耶路撒冷的时候，祭司长和犹太的长老将他的事禀报了我，求我定他的罪。","notes":[]},{"n":16,"t":"我对他们说，无论什么人，被告还没有和原告对质，未得机会分诉所告他的事，就先定他的罪，这不是罗马人的条例。","notes":[]},{"n":17,"t":"及至他们都来到这里，我就不耽延，第二天便坐堂，吩咐把那人提上来。","notes":[]},{"n":18,"t":"告他的人站着告他；所告的，并没有我所逆料的那等恶事。","notes":[]},{"n":19,"t":"不过是有几样辩论，为他们自己敬鬼神的事，又为一个人名叫耶稣，是已经死了，保罗却说他是活着的。","notes":[]},{"n":20,"t":"这些事当怎样究问，我心里作难，所以问他说：『你愿意上耶路撒冷去，在那里为这些事听审吗？』","notes":[]},{"n":21,"t":"但保罗求我留下他，要听皇上审断，我就吩咐把他留下，等我解他到凯撒那里去。」","notes":[]},{"n":22,"t":"亚基帕对非斯都说：「我自己也愿听这人辩论。」非斯都说：「明天你可以听。」","notes":[]},{"n":23,"t":"第二天，亚基帕和百妮基大张威势而来，同着众千夫长和城里的尊贵人进了公厅。非斯都吩咐一声，就有人将保罗带进来。","notes":[]},{"n":24,"t":"非斯都说：「亚基帕王和在这里的诸位啊，你们看这人，就是一切犹太人，在耶路撒冷和这里，曾向我恳求、呼叫说：『不可容他再活着。』","notes":[]},{"n":25,"t":"但我查明他没有犯什么该死的罪，并且他自己上告于皇帝，所以我定意把他解去。","notes":[]},{"n":26,"t":"论到这人，我没有确实的事可以奏明主上。因此，我带他到你们面前，也特意带他到你亚基帕王面前，为要在查问之后有所陈奏。","notes":[]},{"n":27,"t":"据我看来，解送囚犯，不指明他的罪案是不合理的。」","notes":[]}]},"26":{"heading":"保罗在亚基帕王面前申辩","verses":[{"n":1,"t":"亚基帕对保罗说：「准你为自己辩明。」于是保罗伸手分诉，说：「","notes":[]},{"n":2,"t":"亚基帕王啊，犹太人所告我的一切事，今日得在你面前分诉，实为万幸；","notes":[]},{"n":3,"t":"更可幸的，是你熟悉犹太人的规矩和他们的辩论；所以求你耐心听我。","notes":[]},{"n":4,"t":"我从起初在本国的民中，并在耶路撒冷，自幼为人如何，犹太人都知道。","notes":[]},{"n":5,"t":"他们若肯作见证就晓得，我从起初是按着我们教中最严紧的教门作了法利赛人。","notes":[]},{"n":6,"t":"现在我站在这里受审，是因为指望神向我们祖宗所应许的；","notes":[]},{"n":7,"t":"这应许，我们十二个支派，昼夜切切地事奉神，都指望得着。王啊，我被犹太人控告，就是因这指望。","notes":[]},{"n":8,"t":"神叫死人复活，你们为什么看作不可信的呢？","notes":[]},{"n":9,"t":"从前我自己以为应当多方攻击拿撒勒人耶稣的名，","notes":[]},{"n":10,"t":"我在耶路撒冷也曾这样行了。既从祭司长得了权柄，我就把许多圣徒囚在监里。他们被杀，我也出名定案。","notes":[]},{"n":11,"t":"在各会堂，我屡次用刑强逼他们说亵渎的话，又分外恼恨他们，甚至追逼他们，直到外邦的城邑。」","notes":[]},{"n":12,"t":"「那时，我领了祭司长的权柄和命令，往大马士革去。","notes":[],"heads":["保罗叙述归主经过"]},{"n":13,"t":"王啊，我在路上，晌午的时候，看见从天发光，比日头还亮，四面照着我并与我同行的人。","notes":[]},{"n":14,"t":"我们都仆倒在地，我就听见有声音用希伯来话向我说：『扫罗！扫罗！为什么逼迫我？你用脚踢刺是难的！』","notes":[]},{"n":15,"t":"我说：『主啊，你是谁？』主说：『我就是你所逼迫的耶稣。","notes":[]},{"n":16,"t":"你起来站着，我特意向你显现，要派你作执事，作见证，将你所看见的事和我将要指示你的事证明出来。","notes":[]},{"n":17,"t":"我也要救你脱离百姓和外邦人的手。","notes":[]},{"n":18,"t":"我差你到他们那里去，要叫他们的眼睛得开，从黑暗中归向光明，从撒但权下归向神；又因信我，得蒙赦罪，和一切成圣的人同得基业。』」","notes":[]},{"n":19,"t":"「亚基帕王啊，我故此没有违背那从天上来的异象；","notes":[],"heads":["保罗向犹太和外邦人作见证"]},{"n":20,"t":"先在大马士革，后在耶路撒冷和犹太全地，以及外邦，劝勉他们应当悔改归向神，行事与悔改的心相称。","notes":[]},{"n":21,"t":"因此，犹太人在殿里拿住我，想要杀我。","notes":[]},{"n":22,"t":"然而我蒙神的帮助，直到今日还站得住，对着尊贵、卑贱、老幼作见证；所讲的并不外乎众先知和摩西所说将来必成的事，","notes":[]},{"n":23,"t":"就是基督必须受害，并且因从死里复活，要首先把光明的道传给百姓和外邦人。」","notes":[]},{"n":24,"t":"保罗这样分诉，非斯都大声说：「保罗，你癫狂了吧。你的学问太大，反叫你癫狂了！」","notes":[],"heads":["保罗恳请亚基帕信主"]},{"n":25,"t":"保罗说：「非斯都大人，我不是癫狂，我说的乃是真实明白话。","notes":[]},{"n":26,"t":"王也晓得这些事，所以我向王放胆直言，我深信这些事没有一件向王隐藏的，因都不是在背地里做的。","notes":[]},{"n":27,"t":"亚基帕王啊，你信先知吗？我知道你是信的。」","notes":[]},{"n":28,"t":"亚基帕对保罗说：「你想少微一劝，便叫我作基督徒啊！」","notes":["或译：你这样劝我，几乎叫我作基督徒了"]},{"n":29,"t":"保罗说：「无论是少劝是多劝，我向神所求的，不但你一个人，就是今天一切听我的，都要像我一样，只是不要像我有这些锁链。」","notes":[]},{"n":30,"t":"于是，王和巡抚并百妮基与同坐的人都起来，","notes":[]},{"n":31,"t":"退到里面，彼此谈论说：「这人并没有犯什么该死该绑的罪。」","notes":[]},{"n":32,"t":"亚基帕又对非斯都说：「这人若没有上告于凯撒，就可以释放了。」","notes":[]}]},"27":{"heading":"保罗坐船往罗马","verses":[{"n":1,"t":"非斯都既然定规了，叫我们坐船往意大利去，便将保罗和别的囚犯交给御营里的一个百夫长，名叫犹流。","notes":[]},{"n":2,"t":"有一只亚大米田的船，要沿着亚细亚一带地方的海边走，我们就上了那船开行；有马其顿的帖撒罗尼迦人亚里达古和我们同去。","notes":[]},{"n":3,"t":"第二天，到了西顿；犹流宽待保罗，准他往朋友那里去，受他们的照应。","notes":[]},{"n":4,"t":"从那里又开船，因为风不顺，就贴着塞浦路斯背风岸行去。","notes":[]},{"n":5,"t":"过了基利家、旁非利亚前面的海，就到了吕家的每拉。","notes":[]},{"n":6,"t":"在那里，百夫长遇见一只亚历山大的船，要往意大利去，便叫我们上了那船。","notes":[]},{"n":7,"t":"一连多日，船行得慢，仅仅来到革尼土的对面。因为被风拦阻，就贴着克里特背风岸，从撒摩尼对面行过。","notes":[]},{"n":8,"t":"我们沿岸行走，仅仅来到一个地方，名叫佳澳；离那里不远，有拉西亚城。","notes":[]},{"n":9,"t":"走的日子多了，已经过了禁食的节期，行船又危险，保罗就劝众人说：","notes":[]},{"n":10,"t":"「众位，我看这次行船，不但货物和船要受损伤，大遭破坏，连我们的性命也难保。」","notes":[]},{"n":11,"t":"但百夫长信从掌船的和船主，不信从保罗所说的。","notes":[]},{"n":12,"t":"且因在这海口过冬不便，船上的人就多半说，不如开船离开这地方，或者能到菲尼基过冬。菲尼基是克里特的一个海口，一面朝东北，一面朝东南。","notes":[]},{"n":13,"t":"这时，微微起了南风，他们以为得意，就起了锚，贴近克里特行去。","notes":[],"heads":["海上的风暴"]},{"n":14,"t":"不多几时，狂风从岛上扑下来；那风名叫「友拉革罗」。","notes":[]},{"n":15,"t":"船被风抓住，敌不住风，我们就任风刮去。","notes":[]},{"n":16,"t":"贴着一个小岛的背风岸奔行，那岛名叫高大，在那里仅仅收住了小船。","notes":[]},{"n":17,"t":"既然把小船拉上来，就用缆索捆绑船底，又恐怕在赛耳底沙滩上搁了浅，就落下篷来，任船飘去。","notes":[]},{"n":18,"t":"我们被风浪逼得甚急，第二天众人就把货物抛在海里。","notes":[]},{"n":19,"t":"到第三天，他们又亲手把船上的器具抛弃了。","notes":[]},{"n":20,"t":"太阳和星辰多日不显露，又有狂风大浪催逼，我们得救的指望就都绝了。","notes":[]},{"n":21,"t":"众人多日没有吃什么，保罗就出来站在他们中间，说：「众位，你们本该听我的话，不离开克里特，免得遭这样的伤损破坏。","notes":[]},{"n":22,"t":"现在我还劝你们放心，你们的性命一个也不失丧，惟独失丧这船。","notes":[]},{"n":23,"t":"因我所属所事奉的神，他的使者昨夜站在我旁边，说：","notes":[]},{"n":24,"t":"『保罗，不要害怕，你必定站在凯撒面前，并且与你同船的人，神都赐给你了。』","notes":[]},{"n":25,"t":"所以众位可以放心，我信神他怎样对我说，事情也要怎样成就。","notes":[]},{"n":26,"t":"只是我们必要撞在一个岛上。」","notes":[]},{"n":27,"t":"到了第十四天夜间，船在亚得里亚海飘来飘去。约到半夜，水手以为渐近旱地，","notes":[]},{"n":28,"t":"就探深浅，探得有十二丈；稍往前行，又探深浅，探得有九丈。","notes":[]},{"n":29,"t":"恐怕撞在石头上，就从船尾抛下四个锚，盼望天亮。","notes":[]},{"n":30,"t":"水手想要逃出船去，把小船放在海里，假作要从船头抛锚的样子。","notes":[]},{"n":31,"t":"保罗对百夫长和兵丁说：「这些人若不等在船上，你们必不能得救。」","notes":[]},{"n":32,"t":"于是兵丁砍断小船的绳子，由它飘去。","notes":[]},{"n":33,"t":"天渐亮的时候，保罗劝众人都吃饭，说：「你们悬望忍饿不吃什么，已经十四天了。","notes":[]},{"n":34,"t":"所以我劝你们吃饭，这是关乎你们救命的事；因为你们各人连一根头发也不至于损坏。」","notes":[]},{"n":35,"t":"保罗说了这话，就拿着饼，在众人面前祝谢了神，擘开吃。","notes":[]},{"n":36,"t":"于是他们都放下心，也就吃了。","notes":[]},{"n":37,"t":"我们在船上的共有二百七十六个人。","notes":[]},{"n":38,"t":"他们吃饱了，就把船上的麦子抛在海里，为要叫船轻一点。","notes":[]},{"n":39,"t":"到了天亮，他们不认识那地方，但见一个海湾，有岸可登，就商议能把船拢进去不能。","notes":[],"heads":["船搁了浅"]},{"n":40,"t":"于是砍断缆索，弃锚在海里；同时也松开舵绳，拉起头篷，顺着风向岸行去。","notes":[]},{"n":41,"t":"但遇着两水夹流的地方，就把船搁了浅；船头胶住不动，船尾被浪的猛力冲坏。","notes":[]},{"n":42,"t":"兵丁的意思要把囚犯杀了，恐怕有洑水脱逃的。","notes":[]},{"n":43,"t":"但百夫长要救保罗，不准他们任意而行，就吩咐会洑水的，跳下水去先上岸；","notes":[]},{"n":44,"t":"其余的人可以用板子或船上的零碎东西上岸。这样，众人都得了救，上了岸。","notes":[]}]},"28":{"heading":"保罗在马耳他岛上","verses":[{"n":1,"t":"我们既已得救，才知道那岛名叫马耳他。","notes":[]},{"n":2,"t":"土人看待我们，有非常的情分；因为当时下雨，天气又冷，就生火接待我们众人。","notes":[]},{"n":3,"t":"那时，保罗拾起一捆柴，放在火上，有一条毒蛇，因为热了出来，咬住他的手。","notes":[]},{"n":4,"t":"土人看见那毒蛇悬在他手上，就彼此说：「这人必是个凶手，虽然从海里救上来，天理还不容他活着。」","notes":[]},{"n":5,"t":"保罗竟把那毒蛇甩在火里，并没有受伤。","notes":[]},{"n":6,"t":"土人想他必要肿起来，或是忽然仆倒死了；看了多时，见他无害，就转念，说：「他是个神。」","notes":[]},{"n":7,"t":"离那地方不远，有田产是岛长部百流的；他接纳我们，尽情款待三日。","notes":[]},{"n":8,"t":"当时，部百流的父亲患热病和痢疾躺着。保罗进去，为他祷告，按手在他身上，治好了他。","notes":[]},{"n":9,"t":"从此，岛上其余的病人也来，得了医治。","notes":[]},{"n":10,"t":"他们又多方地尊敬我们；到了开船的时候，也把我们所需用的送到船上。","notes":[]},{"n":11,"t":"过了三个月，我们上了亚历山大的船往前行；这船以「宙斯双子」为记，是在那海岛过了冬的。","notes":[],"heads":["保罗抵达罗马"]},{"n":12,"t":"到了叙拉古，我们停泊三日；","notes":[]},{"n":13,"t":"又从那里绕行，来到利基翁。过了一天，起了南风，第二天就来到部丢利。","notes":[]},{"n":14,"t":"在那里遇见弟兄们，请我们与他们同住了七天。这样，我们来到罗马。","notes":[]},{"n":15,"t":"那里的弟兄们一听见我们的信息就出来，到亚比乌市和三馆地方迎接我们。保罗见了他们，就感谢神，放心壮胆。","notes":[]},{"n":16,"t":"进了罗马城，保罗蒙准和一个看守他的兵另住在一处。","notes":["有古卷加：百夫长把众囚犯交给御营的统领，惟有"]},{"n":17,"t":"过了三天，保罗请犹太人的首领来。他们来了，就对他们说：「弟兄们，我虽没有做什么事干犯本国的百姓和我们祖宗的规条，却被锁绑，从耶路撒冷解在罗马人的手里。","notes":[],"heads":["保罗在罗马传道"]},{"n":18,"t":"他们审问了我，就愿意释放我；因为在我身上，并没有该死的罪。","notes":[]},{"n":19,"t":"无奈犹太人不服，我不得已，只好上告于凯撒，并非有什么事要控告我本国的百姓。","notes":[]},{"n":20,"t":"因此，我请你们来见面说话，我原为以色列人所指望的，被这链子捆锁。」","notes":[]},{"n":21,"t":"他们说：「我们并没有接着从犹太来论你的信，也没有弟兄到这里来报给我们说你有什么不好处。","notes":[]},{"n":22,"t":"但我们愿意听你的意见如何；因为这教门，我们晓得是到处被毁谤的。」","notes":[]},{"n":23,"t":"他们和保罗约定了日子，就有许多人到他的寓处来。保罗从早到晚，对他们讲论这事，证明神国的道，引摩西的律法和先知的书，以耶稣的事劝勉他们。","notes":[]},{"n":24,"t":"他所说的话，有信的，有不信的。","notes":[]},{"n":25,"t":"他们彼此不合，就散了；未散以先，保罗说了一句话，说：「圣灵借先知以赛亚向你们祖宗所说的话是不错的。","notes":[]},{"n":26,"t":"他说：你去告诉这百姓说：你们听是要听见，却不明白；看是要看见，却不晓得；","notes":[]},{"n":27,"t":"因为这百姓油蒙了心，耳朵发沉，眼睛闭着；恐怕眼睛看见，耳朵听见，心里明白，回转过来，我就医治他们。","notes":[]},{"n":28,"t":"所以你们当知道，神这救恩，如今传给外邦人，他们也必听受。」","notes":["有古卷加：29_保罗_说了这话，_犹太_人议论纷纷地就走了。"]},{"n":30,"t":"保罗在自己所租的房子里住了足足两年。凡来见他的人，他全都接待，","notes":[]},{"n":31,"t":"放胆传讲神国的道，将主耶稣基督的事教导人，并没有人禁止。","notes":[]}]}},"ROM":{"1":{"heading":"祝福","verses":[{"n":1,"t":"耶稣基督的仆人保罗，奉召为使徒，特派传神的福音。","notes":[]},{"n":2,"t":"这福音是神从前借众先知在圣经上所应许的，","notes":[]},{"n":3,"t":"论到他儿子—我主耶稣基督。按肉体说，是从大卫后裔生的；","notes":[]},{"n":4,"t":"按圣善的灵说，因从死里复活，以大能显明是神的儿子。","notes":[]},{"n":5,"t":"我们从他受了恩惠并使徒的职分，在万国之中叫人为他的名信服真道；","notes":[]},{"n":6,"t":"其中也有你们这蒙召属耶稣基督的人。","notes":[]},{"n":7,"t":"我写信给你们在罗马、为神所爱、奉召作圣徒的众人。愿恩惠、平安从我们的父神并主耶稣基督归与你们！","notes":[]},{"n":8,"t":"第一，我靠着耶稣基督，为你们众人感谢我的神，因你们的信德传遍了天下。","notes":[],"heads":["保罗有意访问罗马"]},{"n":9,"t":"我在他儿子福音上，用心灵所事奉的神可以见证，我怎样不住地提到你们；","notes":[]},{"n":10,"t":"在祷告之间常常恳求，或者照神的旨意，终能得平坦的道路往你们那里去。","notes":[]},{"n":11,"t":"因为我切切地想见你们，要把些属灵的恩赐分给你们，使你们可以坚固；","notes":[]},{"n":12,"t":"这样，我在你们中间，因你与我彼此的信心，就可以同得安慰。","notes":[]},{"n":13,"t":"弟兄们，我不愿意你们不知道，我屡次定意往你们那里去，要在你们中间得些果子，如同在其余的外邦人中一样；只是到如今仍有阻隔。","notes":[]},{"n":14,"t":"无论是希腊人、化外人、聪明人、愚拙人，我都欠他们的债，","notes":[]},{"n":15,"t":"所以情愿尽我的力量，将福音也传给你们在罗马的人。","notes":[]},{"n":16,"t":"我不以福音为耻；这福音本是神的大能，要救一切相信的，先是犹太人，后是希腊人。","notes":[],"heads":["福音是神的大能"]},{"n":17,"t":"因为神的义正在这福音上显明出来；这义是本于信，以至于信。如经上所记：「义人必因信得生。」","notes":[]},{"n":18,"t":"原来，神的忿怒从天上显明在一切不虔不义的人身上，就是那些行不义阻挡真理的人。","notes":[],"heads":["人类的罪恶"]},{"n":19,"t":"神的事情，人所能知道的，原显明在人心里，因为神已经给他们显明。","notes":[]},{"n":20,"t":"自从造天地以来，神的永能和神性是明明可知的，虽是眼不能见，但借着所造之物就可以晓得，叫人无可推诿。","notes":[]},{"n":21,"t":"因为，他们虽然知道神，却不当作神荣耀他，也不感谢他。他们的思念变为虚妄，无知的心就昏暗了。","notes":[]},{"n":22,"t":"自称为聪明，反成了愚拙，","notes":[]},{"n":23,"t":"将不能朽坏之神的荣耀变为偶像，仿佛必朽坏的人和飞禽、走兽、昆虫的样式。","notes":[]},{"n":24,"t":"所以，神任凭他们逞着心里的情欲行污秽的事，以致彼此玷辱自己的身体。","notes":[]},{"n":25,"t":"他们将神的真实变为虚谎，去敬拜事奉受造之物，不敬奉那造物的主—主乃是可称颂的，直到永远。阿们！","notes":[]},{"n":26,"t":"因此，神任凭他们放纵可羞耻的情欲。他们的女人把顺性的用处变为逆性的用处；","notes":[]},{"n":27,"t":"男人也是如此，弃了女人顺性的用处，欲火攻心，彼此贪恋，男和男行可羞耻的事，就在自己身上受这妄为当得的报应。","notes":[]},{"n":28,"t":"他们既然故意不认识神，神就任凭他们存邪僻的心，行那些不合理的事；","notes":[]},{"n":29,"t":"装满了各样不义、邪恶、贪婪、恶毒；满心是嫉妒、凶杀、争竞、诡诈、毒恨；","notes":["或译：阴毒"]},{"n":30,"t":"又是谗毁的、背后说人的、怨恨神的、侮慢人的、狂傲的、自夸的、捏造恶事的、违背父母的、","notes":["或译：被神所憎恶的"]},{"n":31,"t":"无知的、背约的、无亲情的、不怜悯人的。","notes":[]},{"n":32,"t":"他们虽知道神判定行这样事的人是当死的，然而他们不但自己去行，还喜欢别人去行。","notes":[]}]},"2":{"heading":"神的公义判断","verses":[{"n":1,"t":"你这论断人的，无论你是谁，也无可推诿。你在什么事上论断人，就在什么事上定自己的罪；因你这论断人的，自己所行却和别人一样。","notes":[]},{"n":2,"t":"我们知道这样行的人，神必照真理审判他。","notes":[]},{"n":3,"t":"你这人哪，你论断行这样事的人，自己所行的却和别人一样，你以为能逃脱神的审判吗？","notes":[]},{"n":4,"t":"还是你藐视他丰富的恩慈、宽容、忍耐，不晓得他的恩慈是领你悔改呢？","notes":[]},{"n":5,"t":"你竟任着你刚硬不悔改的心，为自己积蓄忿怒，以致神震怒，显他公义审判的日子来到。","notes":[]},{"n":6,"t":"他必照各人的行为报应各人。","notes":[]},{"n":7,"t":"凡恒心行善、寻求荣耀、尊贵和不能朽坏之福的，就以永生报应他们；","notes":[]},{"n":8,"t":"惟有结党、不顺从真理、反顺从不义的，就以忿怒、恼恨报应他们；","notes":[]},{"n":9,"t":"将患难、困苦加给一切作恶的人，先是犹太人，后是希腊人，","notes":[]},{"n":10,"t":"却将荣耀、尊贵、平安加给一切行善的人，先是犹太人，后是希腊人。","notes":[]},{"n":11,"t":"因为神不偏待人。","notes":[]},{"n":12,"t":"凡没有律法犯了罪的，也必不按律法灭亡；凡在律法以下犯了罪的，也必按律法受审判。（","notes":[]},{"n":13,"t":"原来在神面前，不是听律法的为义，乃是行律法的称义。","notes":[]},{"n":14,"t":"没有律法的外邦人若顺着本性行律法上的事，他们虽然没有律法，自己就是自己的律法。","notes":[]},{"n":15,"t":"这是显出律法的功用刻在他们心里，他们是非之心同作见证，并且他们的思念互相较量，或以为是，或以为非。）","notes":[]},{"n":16,"t":"就在神借耶稣基督审判人隐秘事的日子，照着我的福音所言。","notes":[]},{"n":17,"t":"你称为犹太人，又倚靠律法，且指着神夸口；","notes":[],"heads":["犹太人与律法"]},{"n":18,"t":"既从律法中受了教训，就晓得神的旨意，也能分别是非；","notes":["或译：也喜爱那美好的事"]},{"n":19,"t":"又深信自己是给瞎子领路的，是黑暗中人的光，","notes":[]},{"n":20,"t":"是蠢笨人的师傅，是小孩子的先生，在律法上有知识和真理的模范。","notes":[]},{"n":21,"t":"你既是教导别人，还不教导自己吗？你讲说人不可偷窃，自己还偷窃吗？","notes":[]},{"n":22,"t":"你说人不可奸淫，自己还奸淫吗？你厌恶偶像，自己还偷窃庙中之物吗？","notes":[]},{"n":23,"t":"你指着律法夸口，自己倒犯律法、玷辱神吗？","notes":[]},{"n":24,"t":"神的名在外邦人中，因你们受了亵渎，正如经上所记的。","notes":[]},{"n":25,"t":"你若是行律法的，割礼固然于你有益；若是犯律法的，你的割礼就算不得割礼。","notes":[]},{"n":26,"t":"所以那未受割礼的，若遵守律法的条例，他虽然未受割礼，岂不算是有割礼吗？","notes":[]},{"n":27,"t":"而且那本来未受割礼的，若能全守律法，岂不是要审判你这有仪文和割礼竟犯律法的人吗？","notes":[]},{"n":28,"t":"因为外面作犹太人的，不是真犹太人；外面肉身的割礼，也不是真割礼。","notes":[]},{"n":29,"t":"惟有里面作的，才是真犹太人；真割礼也是心里的，在乎灵，不在乎仪文。这人的称赞不是从人来的，乃是从神来的。","notes":[]}]},"3":{"heading":"没有义人","verses":[{"n":1,"t":"这样说来，犹太人有什么长处？割礼有什么益处呢？","notes":[]},{"n":2,"t":"凡事大有好处：第一是神的圣言交托他们。","notes":[]},{"n":3,"t":"即便有不信的，这有何妨呢？难道他们的不信就废掉神的信吗？","notes":[]},{"n":4,"t":"断乎不能！不如说，神是真实的，人都是虚谎的。如经上所记：你责备人的时候，显为公义；被人议论的时候，可以得胜。","notes":[]},{"n":5,"t":"我且照着人的常话说，我们的不义若显出神的义来，我们可以怎么说呢？神降怒，是他不义吗？","notes":[]},{"n":6,"t":"断乎不是！若是这样，神怎能审判世界呢？","notes":[]},{"n":7,"t":"若神的真实，因我的虚谎越发显出他的荣耀，为什么我还受审判，好像罪人呢？","notes":[]},{"n":8,"t":"为什么不说，我们可以作恶以成善呢？这是毁谤我们的人说我们有这话。这等人定罪是该当的。","notes":[]},{"n":9,"t":"这却怎么样呢？我们比他们强吗？决不是的！因我们已经证明：犹太人和希腊人都在罪恶之下。","notes":[]},{"n":10,"t":"就如经上所记：没有义人，连一个也没有。","notes":[]},{"n":11,"t":"没有明白的；没有寻求神的；","notes":[]},{"n":12,"t":"都是偏离正路，一同变为无用。没有行善的，连一个也没有。","notes":[]},{"n":13,"t":"他们的喉咙是敞开的坟墓；他们用舌头弄诡诈，嘴唇里有虺蛇的毒气，","notes":[]},{"n":14,"t":"满口是咒骂苦毒。","notes":[]},{"n":15,"t":"杀人流血，他们的脚飞跑，","notes":[]},{"n":16,"t":"所经过的路便行残害暴虐的事。","notes":[]},{"n":17,"t":"平安的路，他们未曾知道；","notes":[]},{"n":18,"t":"他们眼中不怕神。","notes":[]},{"n":19,"t":"我们晓得律法上的话都是对律法以下之人说的，好塞住各人的口，叫普世的人都伏在神审判之下。","notes":[]},{"n":20,"t":"所以凡有血气的，没有一个因行律法能在神面前称义，因为律法本是叫人知罪。","notes":[]},{"n":21,"t":"但如今，神的义在律法以外已经显明出来，有律法和先知为证：","notes":[],"heads":["因信称义"]},{"n":22,"t":"就是神的义，因信耶稣基督加给一切相信的人，并没有分别。","notes":[]},{"n":23,"t":"因为世人都犯了罪，亏缺了神的荣耀；","notes":[]},{"n":24,"t":"如今却蒙神的恩典，因基督耶稣的救赎，就白白地称义。","notes":[]},{"n":25,"t":"神设立耶稣作挽回祭，是凭着耶稣的血，借着人的信，要显明神的义；因为他用忍耐的心宽容人先时所犯的罪，","notes":[]},{"n":26,"t":"好在今时显明他的义，使人知道他自己为义，也称信耶稣的人为义。","notes":[]},{"n":27,"t":"既是这样，哪里能夸口呢？没有可夸的了。用何法没有的呢？是用立功之法吗？不是，乃用信主之法。","notes":[]},{"n":28,"t":"所以我们看定了：人称义是因着信，不在乎遵行律法。","notes":["有古卷：因为"]},{"n":29,"t":"难道神只作犹太人的神吗？不也是作外邦人的神吗？是的，也作外邦人的神。","notes":[]},{"n":30,"t":"神既是一位，他就要因信称那受割礼的为义，也要因信称那未受割礼的为义。","notes":[]},{"n":31,"t":"这样，我们因信废了律法吗？断乎不是！更是坚固律法。","notes":[]}]},"4":{"heading":"以亚伯拉罕为例","verses":[{"n":1,"t":"如此说来，我们的祖宗亚伯拉罕凭着肉体得了什么呢？","notes":[]},{"n":2,"t":"倘若亚伯拉罕是因行为称义，就有可夸的；只是在神面前并无可夸。","notes":[]},{"n":3,"t":"经上说什么呢？说：「亚伯拉罕信神，这就算为他的义。」","notes":[]},{"n":4,"t":"做工的得工价，不算恩典，乃是该得的；","notes":[]},{"n":5,"t":"惟有不做工的，只信称罪人为义的神，他的信就算为义。","notes":[]},{"n":6,"t":"正如大卫称那在行为以外蒙神算为义的人是有福的。","notes":[]},{"n":7,"t":"他说：得赦免其过、遮盖其罪的，这人是有福的。","notes":[]},{"n":8,"t":"主不算为有罪的，这人是有福的。","notes":[]},{"n":9,"t":"如此看来，这福是单加给那受割礼的人吗？不也是加给那未受割礼的人吗？因我们所说，亚伯拉罕的信，就算为他的义，","notes":[]},{"n":10,"t":"是怎么算的呢？是在他受割礼的时候呢？是在他未受割礼的时候呢？不是在受割礼的时候，乃是在未受割礼的时候。","notes":[]},{"n":11,"t":"并且他受了割礼的记号，作他未受割礼的时候因信称义的印证，叫他作一切未受割礼而信之人的父，使他们也算为义；","notes":[]},{"n":12,"t":"又作受割礼之人的父，就是那些不但受割礼，并且按我们的祖宗亚伯拉罕未受割礼而信之踪迹去行的人。","notes":[]},{"n":13,"t":"因为神应许亚伯拉罕和他后裔，必得承受世界，不是因律法，乃是因信而得的义。","notes":[],"heads":["应许因信而实现"]},{"n":14,"t":"若是属乎律法的人才得为后嗣，信就归于虚空，应许也就废弃了。","notes":[]},{"n":15,"t":"因为律法是惹动忿怒的；哪里没有律法，那里就没有过犯。","notes":["或译：叫人受刑的"]},{"n":16,"t":"所以人得为后嗣是本乎信，因此就属乎恩，叫应许定然归给一切后裔；不但归给那属乎律法的，也归给那效法亚伯拉罕之信的。","notes":[]},{"n":17,"t":"亚伯拉罕所信的，是那叫死人复活、使无变为有的神，他在主面前作我们世人的父。如经上所记：「我已经立你作多国的父。」","notes":[]},{"n":18,"t":"他在无可指望的时候，因信仍有指望，就得以作多国的父，正如先前所说：「你的后裔将要如此。」","notes":[]},{"n":19,"t":"他将近百岁的时候，虽然想到自己的身体如同已死，撒拉的生育已经断绝，他的信心还是不软弱；","notes":[]},{"n":20,"t":"并且仰望神的应许，总没有因不信心里起疑惑，反倒因信心里得坚固，将荣耀归给神，","notes":[]},{"n":21,"t":"且满心相信神所应许的必能做成。","notes":[]},{"n":22,"t":"所以，这就算为他的义。","notes":[]},{"n":23,"t":"「算为他义」的这句话不是单为他写的，","notes":[]},{"n":24,"t":"也是为我们将来得算为义之人写的，就是我们这信神使我们的主耶稣从死里复活的人。","notes":[]},{"n":25,"t":"耶稣被交给人，是为我们的过犯；复活，是为叫我们称义。","notes":["或译：耶稣是为我们的过犯交付了，是为我们称义复活了"]}]},"5":{"heading":"因信称义的福","verses":[{"n":1,"t":"我们既因信称义，就借着我们的主耶稣基督得与神相和。","notes":[]},{"n":2,"t":"我们又借着他，因信得进入现在所站的这恩典中，并且欢欢喜喜盼望神的荣耀。","notes":[]},{"n":3,"t":"不但如此，就是在患难中也是欢欢喜喜的；因为知道患难生忍耐，","notes":[]},{"n":4,"t":"忍耐生老练，老练生盼望；","notes":[]},{"n":5,"t":"盼望不至于羞耻，因为所赐给我们的圣灵将神的爱浇灌在我们心里。","notes":[]},{"n":6,"t":"因我们还软弱的时候，基督就按所定的日期为罪人死。","notes":[]},{"n":7,"t":"为义人死，是少有的；为仁人死，或者有敢做的。","notes":[]},{"n":8,"t":"惟有基督在我们还作罪人的时候为我们死，神的爱就在此向我们显明了。","notes":[]},{"n":9,"t":"现在我们既靠着他的血称义，就更要借着他免去神的忿怒。","notes":[]},{"n":10,"t":"因为我们作仇敌的时候，且借着神儿子的死，得与神和好；既已和好，就更要因他的生得救了。","notes":[]},{"n":11,"t":"不但如此，我们既借着我主耶稣基督得与神和好，也就借着他以神为乐。","notes":[]},{"n":12,"t":"这就如罪是从一人入了世界，死又是从罪来的，于是死就临到众人，因为众人都犯了罪。","notes":[],"heads":["亚当和基督"]},{"n":13,"t":"没有律法之先，罪已经在世上；但没有律法，罪也不算罪。","notes":[]},{"n":14,"t":"然而从亚当到摩西，死就作了王，连那些不与亚当犯一样罪过的，也在他的权下。亚当乃是那以后要来之人的预像。","notes":[]},{"n":15,"t":"只是过犯不如恩赐，若因一人的过犯，众人都死了，何况神的恩典，与那因耶稣基督一人恩典中的赏赐，岂不更加倍地临到众人吗？","notes":[]},{"n":16,"t":"因一人犯罪就定罪，也不如恩赐，原来审判是由一人而定罪，恩赐乃是由许多过犯而称义。","notes":[]},{"n":17,"t":"若因一人的过犯，死就因这一人作了王，何况那些受洪恩又蒙所赐之义的，岂不更要因耶稣基督一人在生命中作王吗？","notes":[]},{"n":18,"t":"如此说来，因一次的过犯，众人都被定罪；照样，因一次的义行，众人也就被称义得生命了。","notes":[]},{"n":19,"t":"因一人的悖逆，众人成为罪人；照样，因一人的顺从，众人也成为义了。","notes":[]},{"n":20,"t":"律法本是外添的，叫过犯显多；只是罪在哪里显多，恩典就更显多了。","notes":[]},{"n":21,"t":"就如罪作王叫人死；照样，恩典也借着义作王，叫人因我们的主耶稣基督得永生。","notes":[]}]},"6":{"heading":"在罪上死，在基督里活","verses":[{"n":1,"t":"这样，怎么说呢？我们可以仍在罪中、叫恩典显多吗？","notes":[]},{"n":2,"t":"断乎不可！我们在罪上死了的人岂可仍在罪中活着呢？","notes":[]},{"n":3,"t":"岂不知我们这受洗归入基督耶稣的人是受洗归入他的死吗？","notes":[]},{"n":4,"t":"所以，我们借着洗礼归入死，和他一同埋葬，原是叫我们一举一动有新生的样式，像基督借着父的荣耀从死里复活一样。","notes":[]},{"n":5,"t":"我们若在他死的形状上与他联合，也要在他复活的形状上与他联合；","notes":[]},{"n":6,"t":"因为知道我们的旧人和他同钉十字架，使罪身灭绝，叫我们不再作罪的奴仆；","notes":[]},{"n":7,"t":"因为已死的人是脱离了罪。","notes":[]},{"n":8,"t":"我们若是与基督同死，就信必与他同活。","notes":[]},{"n":9,"t":"因为知道基督既从死里复活，就不再死，死也不再作他的主了。","notes":[]},{"n":10,"t":"他死是向罪死了，只有一次；他活是向神活着。","notes":[]},{"n":11,"t":"这样，你们向罪也当看自己是死的；向神在基督耶稣里，却当看自己是活的。","notes":[]},{"n":12,"t":"所以，不要容罪在你们必死的身上作王，使你们顺从身子的私欲。","notes":[]},{"n":13,"t":"也不要将你们的肢体献给罪作不义的器具；倒要像从死里复活的人，将自己献给神，并将肢体作义的器具献给神。","notes":[]},{"n":14,"t":"罪必不能作你们的主；因你们不在律法之下，乃在恩典之下。","notes":[]},{"n":15,"t":"这却怎么样呢？我们在恩典之下，不在律法之下，就可以犯罪吗？断乎不可！","notes":[],"heads":["义的奴仆"]},{"n":16,"t":"岂不晓得你们献上自己作奴仆，顺从谁，就作谁的奴仆吗？或作罪的奴仆，以至于死；或作顺命的奴仆，以至成义。","notes":[]},{"n":17,"t":"感谢神！因为你们从前虽然作罪的奴仆，现今却从心里顺服了所传给你们道理的模范。","notes":[]},{"n":18,"t":"你们既从罪里得了释放，就作了义的奴仆。","notes":[]},{"n":19,"t":"我因你们肉体的软弱，就照人的常话对你们说。你们从前怎样将肢体献给不洁不法作奴仆，以至于不法；现今也要照样将肢体献给义作奴仆，以至于成圣。","notes":[]},{"n":20,"t":"因为你们作罪之奴仆的时候，就不被义约束了。","notes":[]},{"n":21,"t":"你们现今所看为羞耻的事，当日有什么果子呢？那些事的结局就是死。","notes":[]},{"n":22,"t":"但现今，你们既从罪里得了释放，作了神的奴仆，就有成圣的果子，那结局就是永生。","notes":[]},{"n":23,"t":"因为罪的工价乃是死；惟有神的恩赐，在我们的主基督耶稣里，乃是永生。","notes":[]}]},"7":{"heading":"以婚姻关系为例","verses":[{"n":1,"t":"弟兄们，我现在对明白律法的人说，你们岂不晓得律法管人是在活着的时候吗？","notes":[]},{"n":2,"t":"就如女人有了丈夫，丈夫还活着，就被律法约束；丈夫若死了，就脱离了丈夫的律法。","notes":[]},{"n":3,"t":"所以丈夫活着，她若归于别人，便叫淫妇；丈夫若死了，她就脱离了丈夫的律法，虽然归于别人，也不是淫妇。","notes":[]},{"n":4,"t":"我的弟兄们，这样说来，你们借着基督的身体，在律法上也是死了，叫你们归于别人，就是归于那从死里复活的，叫我们结果子给神。","notes":[]},{"n":5,"t":"因为我们属肉体的时候，那因律法而生的恶欲就在我们肢体中发动，以致结成死亡的果子。","notes":[]},{"n":6,"t":"但我们既然在捆我们的律法上死了，现今就脱离了律法，叫我们服事主，要按着心灵的新样，不按着仪文的旧样。","notes":["心灵：或译圣灵"]},{"n":7,"t":"这样，我们可说什么呢？律法是罪吗？断乎不是！只是非因律法，我就不知何为罪。非律法说「不可起贪心」，我就不知何为贪心。","notes":[],"heads":["内在的罪"]},{"n":8,"t":"然而，罪趁着机会，就借着诫命叫诸般的贪心在我里头发动；因为没有律法，罪是死的。","notes":[]},{"n":9,"t":"我以前没有律法是活着的；但是诫命来到，罪又活了，我就死了。","notes":[]},{"n":10,"t":"那本来叫人活的诫命，反倒叫我死；","notes":[]},{"n":11,"t":"因为罪趁着机会，就借着诫命引诱我，并且杀了我。","notes":[]},{"n":12,"t":"这样看来，律法是圣洁的，诫命也是圣洁、公义、良善的。","notes":[]},{"n":13,"t":"既然如此，那良善的是叫我死吗？断乎不是！叫我死的乃是罪。但罪借着那良善的叫我死，就显出真是罪，叫罪因着诫命更显出是恶极了。","notes":[]},{"n":14,"t":"我们原晓得律法是属乎灵的，但我是属乎肉体的，是已经卖给罪了。","notes":[]},{"n":15,"t":"因为我所做的，我自己不明白；我所愿意的，我并不做；我所恨恶的，我倒去做。","notes":[]},{"n":16,"t":"若我所做的，是我所不愿意的，我就应承律法是善的。","notes":[]},{"n":17,"t":"既是这样，就不是我做的，乃是住在我里头的罪做的。","notes":[]},{"n":18,"t":"我也知道，在我里头，就是我肉体之中，没有良善。因为，立志为善由得我，只是行出来由不得我。","notes":[]},{"n":19,"t":"故此，我所愿意的善，我反不做；我所不愿意的恶，我倒去做。","notes":[]},{"n":20,"t":"若我去做所不愿意做的，就不是我做的，乃是住在我里头的罪做的。","notes":[]},{"n":21,"t":"我觉得有个律，就是我愿意为善的时候，便有恶与我同在。","notes":[]},{"n":22,"t":"因为按着我里面的意思，我是喜欢神的律；","notes":["原文是人"]},{"n":23,"t":"但我觉得肢体中另有个律和我心中的律交战，把我掳去，叫我附从那肢体中犯罪的律。","notes":[]},{"n":24,"t":"我真是苦啊！谁能救我脱离这取死的身体呢？","notes":[]},{"n":25,"t":"感谢神，靠着我们的主耶稣基督就能脱离了。这样看来，我以内心顺服神的律，我肉体却顺服罪的律了。","notes":[]}]},"8":{"heading":"在圣灵里的生活","verses":[{"n":1,"t":"如今，那些在基督耶稣里的就不定罪了。","notes":[]},{"n":2,"t":"因为赐生命圣灵的律，在基督耶稣里释放了我，使我脱离罪和死的律了。","notes":[]},{"n":3,"t":"律法既因肉体软弱，有所不能行的，神就差遣自己的儿子，成为罪身的形状，作了赎罪祭，在肉体中定了罪案，","notes":[]},{"n":4,"t":"使律法的义成就在我们这不随从肉体、只随从圣灵的人身上。","notes":[]},{"n":5,"t":"因为，随从肉体的人体贴肉体的事；随从圣灵的人体贴圣灵的事。","notes":[]},{"n":6,"t":"体贴肉体的，就是死；体贴圣灵的，乃是生命、平安。","notes":[]},{"n":7,"t":"原来体贴肉体的，就是与神为仇；因为不服神的律法，也是不能服，","notes":[]},{"n":8,"t":"而且属肉体的人不能得神的喜欢。","notes":[]},{"n":9,"t":"如果神的灵住在你们心里，你们就不属肉体，乃属圣灵了。人若没有基督的灵，就不是属基督的。","notes":[]},{"n":10,"t":"基督若在你们心里，身体就因罪而死，心灵却因义而活。","notes":[]},{"n":11,"t":"然而，叫耶稣从死里复活者的灵若住在你们心里，那叫基督耶稣从死里复活的，也必借着住在你们心里的圣灵，使你们必死的身体又活过来。","notes":[]},{"n":12,"t":"弟兄们，这样看来，我们并不是欠肉体的债去顺从肉体活着。","notes":[]},{"n":13,"t":"你们若顺从肉体活着，必要死；若靠着圣灵治死身体的恶行，必要活着。","notes":[]},{"n":14,"t":"因为凡被神的灵引导的，都是神的儿子。","notes":[]},{"n":15,"t":"你们所受的，不是奴仆的心，仍旧害怕；所受的，乃是儿子的心，因此我们呼叫：「阿爸！父！」","notes":[]},{"n":16,"t":"圣灵与我们的心同证我们是神的儿女；","notes":[]},{"n":17,"t":"既是儿女，便是后嗣，就是神的后嗣，和基督同作后嗣。如果我们和他一同受苦，也必和他一同得荣耀。","notes":[]},{"n":18,"t":"我想，现在的苦楚若比起将来要显于我们的荣耀就不足介意了。","notes":[],"heads":["将来的荣耀"]},{"n":19,"t":"受造之物切望等候神的众子显出来。","notes":[]},{"n":20,"t":"因为受造之物服在虚空之下，不是自己愿意，乃是因那叫他如此的。","notes":[]},{"n":21,"t":"但受造之物仍然指望脱离败坏的辖制，得享神儿女自由的荣耀。","notes":["享：原文是入"]},{"n":22,"t":"我们知道，一切受造之物一同叹息，劳苦，直到如今。","notes":[]},{"n":23,"t":"不但如此，就是我们这有圣灵初结果子的，也是自己心里叹息，等候得着儿子的名分，乃是我们的身体得赎。","notes":[]},{"n":24,"t":"我们得救是在乎盼望；只是所见的盼望不是盼望，谁还盼望他所见的呢？","notes":["有古卷：人所看见的何必再盼望呢"]},{"n":25,"t":"但我们若盼望那所不见的，就必忍耐等候。","notes":[]},{"n":26,"t":"况且，我们的软弱有圣灵帮助；我们本不晓得当怎样祷告，只是圣灵亲自用说不出来的叹息替我们祷告。","notes":[]},{"n":27,"t":"鉴察人心的，晓得圣灵的意思，因为圣灵照着神的旨意替圣徒祈求。","notes":[]},{"n":28,"t":"我们晓得万事都互相效力，叫爱神的人得益处，就是按他旨意被召的人。","notes":[]},{"n":29,"t":"因为他预先所知道的人，就预先定下效法他儿子的模样，使他儿子在许多弟兄中作长子。","notes":[]},{"n":30,"t":"预先所定下的人又召他们来；所召来的人又称他们为义；所称为义的人又叫他们得荣耀。","notes":[]},{"n":31,"t":"既是这样，还有什么说的呢？神若帮助我们，谁能敌挡我们呢？","notes":[],"heads":["神的爱"]},{"n":32,"t":"神既不爱惜自己的儿子，为我们众人舍了，岂不也把万物和他一同白白地赐给我们吗？","notes":[]},{"n":33,"t":"谁能控告神所拣选的人呢？有神称他们为义了。","notes":["或译：是称他们为义的神吗"]},{"n":34,"t":"谁能定他们的罪呢？有基督耶稣已经死了，而且从死里复活，现今在神的右边，也替我们祈求。","notes":["有基督<ins>.</ins>.或译：是已经死了，而且从死里复活，现今在神的右边，也替我们祈求的基督耶稣吗"]},{"n":35,"t":"谁能使我们与基督的爱隔绝呢？难道是患难吗？是困苦吗？是逼迫吗？是饥饿吗？是赤身露体吗？是危险吗？是刀剑吗？","notes":[]},{"n":36,"t":"如经上所记：我们为你的缘故终日被杀；人看我们如将宰的羊。","notes":[]},{"n":37,"t":"然而，靠着爱我们的主，在这一切的事上已经得胜有余了。","notes":[]},{"n":38,"t":"因为我深信无论是死，是生，是天使，是掌权的，是有能的，是现在的事，是将来的事，","notes":[]},{"n":39,"t":"是高处的，是低处的，是别的受造之物，都不能叫我们与神的爱隔绝；这爱是在我们的主基督耶稣里的。","notes":[]}]},"9":{"heading":"神拣选以色列人","verses":[{"n":1,"t":"我在基督里说真话，并不谎言，有我良心被圣灵感动，给我作见证：","notes":[]},{"n":2,"t":"我是大有忧愁，心里时常伤痛；","notes":[]},{"n":3,"t":"为我弟兄，我骨肉之亲，就是自己被咒诅，与基督分离，我也愿意。","notes":[]},{"n":4,"t":"他们是以色列人；那儿子的名分、荣耀、诸约、律法、礼仪、应许都是他们的。","notes":[]},{"n":5,"t":"列祖就是他们的祖宗；按肉体说，基督也是从他们出来的。他是在万有之上，永远可称颂的神。阿们！","notes":[]},{"n":6,"t":"这不是说神的话落了空。因为从以色列生的不都是以色列人，","notes":[]},{"n":7,"t":"也不因为是亚伯拉罕的后裔就都作他的儿女；惟独「从以撒生的才要称为你的后裔。」","notes":[]},{"n":8,"t":"这就是说，肉身所生的儿女不是神的儿女，惟独那应许的儿女才算是后裔。","notes":[]},{"n":9,"t":"因为所应许的话是这样说：「到明年这时候我要来，撒拉必生一个儿子。」","notes":[]},{"n":10,"t":"不但如此，还有利百加，既从一个人，就是从我们的祖宗以撒怀了孕，（","notes":[]},{"n":11,"t":"双子还没有生下来，善恶还没有做出来，只因要显明神拣选人的旨意，不在乎人的行为，乃在乎召人的主。）","notes":[]},{"n":12,"t":"神就对利百加说：「将来，大的要服事小的。」","notes":[]},{"n":13,"t":"正如经上所记：雅各是我所爱的；以扫是我所恶的。","notes":[]},{"n":14,"t":"这样，我们可说什么呢？难道神有什么不公平吗？断乎没有！","notes":[]},{"n":15,"t":"因他对摩西说：我要怜悯谁就怜悯谁，要恩待谁就恩待谁。","notes":[]},{"n":16,"t":"据此看来，这不在乎那定意的，也不在乎那奔跑的，只在乎发怜悯的神。","notes":[]},{"n":17,"t":"因为经上有话向法老说：「我将你兴起来，特要在你身上彰显我的权能，并要使我的名传遍天下。」","notes":[]},{"n":18,"t":"如此看来，神要怜悯谁就怜悯谁，要叫谁刚硬就叫谁刚硬。","notes":[]},{"n":19,"t":"这样，你必对我说：「他为什么还指责人呢？有谁抗拒他的旨意呢？」","notes":[],"heads":["神的忿怒和怜悯"]},{"n":20,"t":"你这个人哪，你是谁，竟敢向神强嘴呢？受造之物岂能对造他的说：「你为什么这样造我呢？」","notes":[]},{"n":21,"t":"窑匠难道没有权柄从一团泥里拿一块做成贵重的器皿，又拿一块做成卑贱的器皿吗？","notes":[]},{"n":22,"t":"倘若神要显明他的忿怒，彰显他的权能，就多多忍耐宽容那可怒、预备遭毁灭的器皿，","notes":[]},{"n":23,"t":"又要将他丰盛的荣耀彰显在那蒙怜悯、早预备得荣耀的器皿上。","notes":[]},{"n":24,"t":"这器皿就是我们被神所召的，不但是从犹太人中，也是从外邦人中。这有什么不可呢？","notes":[]},{"n":25,"t":"就像神在何西阿书上说：那本来不是我子民的，我要称为「我的子民」；本来不是蒙爱的，我要称为「蒙爱的」。","notes":[]},{"n":26,"t":"从前在什么地方对他们说：你们不是我的子民，将来就在那里称他们为「永生神的儿子」。","notes":[]},{"n":27,"t":"以赛亚指着以色列人喊着说：「以色列人虽多如海沙，得救的不过是剩下的余数；","notes":[]},{"n":28,"t":"因为主要在世上施行他的话，叫他的话都成全，速速地完结。」","notes":[]},{"n":29,"t":"又如以赛亚先前说过：若不是万军之主给我们存留余种，我们早已像所多玛、蛾摩拉的样子了。","notes":[]},{"n":30,"t":"这样，我们可说什么呢？那本来不追求义的外邦人反得了义，就是因信而得的义。","notes":[],"heads":["以色列人和福音"]},{"n":31,"t":"但以色列人追求律法的义，反得不着律法的义。","notes":[]},{"n":32,"t":"这是什么缘故呢？是因为他们不凭着信心求，只凭着行为求；他们正跌在那绊脚石上。","notes":[]},{"n":33,"t":"就如经上所记：我在锡安放一块绊脚的石头，跌人的磐石；信靠他的人必不至于羞愧。","notes":[]}]},"10":{"heading":"求告主名的必要得救","verses":[{"n":1,"t":"弟兄们，我心里所愿的，向神所求的，是要以色列人得救。","notes":[]},{"n":2,"t":"我可以证明，他们向神有热心，但不是按着真知识；","notes":[]},{"n":3,"t":"因为不知道神的义，想要立自己的义，就不服神的义了。","notes":[]},{"n":4,"t":"律法的总结就是基督，使凡信他的都得着义。","notes":[]},{"n":5,"t":"摩西写着说：「人若行那出于律法的义，就必因此活着。」","notes":[]},{"n":6,"t":"惟有出于信心的义如此说：「你不要心里说：谁要升到天上去呢？（就是要领下基督来；）","notes":[]},{"n":7,"t":"谁要下到阴间去呢？（就是要领基督从死里上来。）」","notes":[]},{"n":8,"t":"他到底怎么说呢？他说：这道离你不远，正在你口里，在你心里—（就是我们所传信主的道。）","notes":[]},{"n":9,"t":"你若口里认耶稣为主，心里信神叫他从死里复活，就必得救。","notes":[]},{"n":10,"t":"因为，人心里相信就可以称义，口里承认就可以得救。","notes":[]},{"n":11,"t":"经上说：「凡信他的人必不至于羞愧。」","notes":[]},{"n":12,"t":"犹太人和希腊人并没有分别，因为众人同有一位主；他也厚待一切求告他的人。","notes":[]},{"n":13,"t":"因为「凡求告主名的就必得救」。","notes":[]},{"n":14,"t":"然而，人未曾信他，怎能求他呢？未曾听见他，怎能信他呢？没有传道的，怎能听见呢？","notes":[]},{"n":15,"t":"若没有奉差遣，怎能传道呢？如经上所记：「报福音、传喜信的人，他们的脚踪何等佳美！」","notes":[]},{"n":16,"t":"只是人没有都听从福音，因为以赛亚说：「主啊，我们所传的有谁信呢？」","notes":[]},{"n":17,"t":"可见，信道是从听道来的，听道是从基督的话来的。","notes":[]},{"n":18,"t":"但我说，人没有听见吗？诚然听见了。他们的声音传遍天下；他们的言语传到地极。","notes":[]},{"n":19,"t":"我再说，以色列人不知道吗？先有摩西说：我要用那不成子民的惹动你们的愤恨；我要用那无知的民触动你们的怒气。","notes":[]},{"n":20,"t":"又有以赛亚放胆说：没有寻找我的，我叫他们遇见；没有访问我的，我向他们显现。","notes":[]},{"n":21,"t":"至于以色列人，他说：「我整天伸手招呼那悖逆顶嘴的百姓。」","notes":[]}]},"11":{"heading":"以色列的余民","verses":[{"n":1,"t":"我且说，神弃绝了他的百姓吗？断乎没有！因为我也是以色列人，亚伯拉罕的后裔，属便雅悯支派的。","notes":[]},{"n":2,"t":"神并没有弃绝他预先所知道的百姓。你们岂不晓得经上论到以利亚是怎么说的呢？他在神面前怎样控告以色列人说：","notes":[]},{"n":3,"t":"「主啊，他们杀了你的先知，拆了你的祭坛，只剩下我一个人；他们还要寻索我的命。」","notes":[]},{"n":4,"t":"神的回话是怎么说的呢？他说：「我为自己留下七千人，是未曾向巴力屈膝的。」","notes":[]},{"n":5,"t":"如今也是这样，照着拣选的恩典，还有所留的余数。","notes":[]},{"n":6,"t":"既是出于恩典，就不在乎行为；不然，恩典就不是恩典了。","notes":[]},{"n":7,"t":"这是怎么样呢？以色列人所求的，他们没有得着。惟有蒙拣选的人得着了；其余的就成了顽梗不化的。","notes":[]},{"n":8,"t":"如经上所记：神给他们昏迷的心，眼睛不能看见，耳朵不能听见，直到今日。","notes":[]},{"n":9,"t":"大卫也说：愿他们的筵席变为网罗，变为机槛，变为绊脚石，作他们的报应。","notes":[]},{"n":10,"t":"愿他们的眼睛昏蒙，不得看见；愿你时常弯下他们的腰。","notes":[]},{"n":11,"t":"我且说，他们失脚是要他们跌倒吗？断乎不是！反倒因他们的过失，救恩便临到外邦人，要激动他们发愤。","notes":[],"heads":["外邦人得救"]},{"n":12,"t":"若他们的过失为天下的富足，他们的缺乏为外邦人的富足，何况他们的丰满呢？","notes":[]},{"n":13,"t":"我对你们外邦人说这话；因我是外邦人的使徒，所以敬重我的职分，","notes":["原文是荣耀"]},{"n":14,"t":"或者可以激动我骨肉之亲发愤，好救他们一些人。","notes":[]},{"n":15,"t":"若他们被丢弃，天下就得与神和好，他们被收纳，岂不是死而复生吗？","notes":[]},{"n":16,"t":"所献的新面若是圣洁，全团也就圣洁了；树根若是圣洁，树枝也就圣洁了。","notes":[]},{"n":17,"t":"若有几根枝子被折下来，你这野橄榄得接在其中，一同得着橄榄根的肥汁，","notes":[]},{"n":18,"t":"你就不可向旧枝子夸口；若是夸口，当知道不是你托着根，乃是根托着你。","notes":[]},{"n":19,"t":"你若说，那枝子被折下来是特为叫我接上。","notes":[]},{"n":20,"t":"不错！他们因为不信，所以被折下来；你因为信，所以立得住；你不可自高，反要惧怕。","notes":[]},{"n":21,"t":"神既不爱惜原来的枝子，也必不爱惜你。","notes":[]},{"n":22,"t":"可见，神的恩慈和严厉向那跌倒的人是严厉的，向你是有恩慈的，只要你长久在他的恩慈里；不然，你也要被砍下来。","notes":[]},{"n":23,"t":"而且他们若不是长久不信，仍要被接上，因为神能够把他们从新接上。","notes":[]},{"n":24,"t":"你是从那天生的野橄榄上砍下来的，尚且逆着性得接在好橄榄上，何况这本树的枝子，要接在本树上呢！","notes":[]},{"n":25,"t":"弟兄们，我不愿意你们不知道这奥秘（恐怕你们自以为聪明），就是以色列人有几分是硬心的，等到外邦人的数目添满了，","notes":[],"heads":["以色列人的复兴"]},{"n":26,"t":"于是以色列全家都要得救。如经上所记：必有一位救主从锡安出来，要消除雅各家的一切罪恶；","notes":[]},{"n":27,"t":"又说：我除去他们罪的时候，这就是我与他们所立的约。","notes":[]},{"n":28,"t":"就着福音说，他们为你们的缘故是仇敌；就着拣选说，他们为列祖的缘故是蒙爱的。","notes":[]},{"n":29,"t":"因为神的恩赐和选召是没有后悔的。","notes":[]},{"n":30,"t":"你们从前不顺服神，如今因他们的不顺服，你们倒蒙了怜恤。","notes":[]},{"n":31,"t":"这样，他们也是不顺服，叫他们因着施给你们的怜恤，现在也就蒙怜恤。","notes":[]},{"n":32,"t":"因为神将众人都圈在不顺服之中，特意要怜恤众人。","notes":[]},{"n":33,"t":"深哉，神丰富的智慧和知识！他的判断何其难测！他的踪迹何其难寻！","notes":[]},{"n":34,"t":"谁知道主的心？谁作过他的谋士呢？","notes":[]},{"n":35,"t":"谁是先给了他，使他后来偿还呢？","notes":[]},{"n":36,"t":"因为万有都是本于他，倚靠他，归于他。愿荣耀归给他，直到永远。阿们！","notes":[]}]},"12":{"heading":"基督里的新生活","verses":[{"n":1,"t":"所以，弟兄们，我以神的慈悲劝你们，将身体献上，当作活祭，是圣洁的，是神所喜悦的；你们如此事奉乃是理所当然的。","notes":[]},{"n":2,"t":"不要效法这个世界，只要心意更新而变化，叫你们察验何为神的善良、纯全、可喜悦的旨意。","notes":[]},{"n":3,"t":"我凭着所赐我的恩对你们各人说：不要看自己过于所当看的；要照着神所分给各人信心的大小，看得合乎中道。","notes":[]},{"n":4,"t":"正如我们一个身子上有好些肢体，肢体也不都是一样的用处。","notes":[]},{"n":5,"t":"我们这许多人，在基督里成为一身，互相联络作肢体，也是如此。","notes":[]},{"n":6,"t":"按我们所得的恩赐，各有不同。或说预言，就当照着信心的程度说预言；","notes":[]},{"n":7,"t":"或作执事，就当专一执事；或作教导的，就当专一教导；","notes":[]},{"n":8,"t":"或作劝化的，就当专一劝化；施舍的，就当诚实；治理的，就当殷勤；怜悯人的，就当甘心。","notes":[]},{"n":9,"t":"爱人不可虚假。恶，要厌恶；善，要亲近。","notes":[],"heads":["基督徒的生活守则"]},{"n":10,"t":"爱弟兄，要彼此亲热；恭敬人，要彼此推让。","notes":[]},{"n":11,"t":"殷勤，不可懒惰；要心里火热，常常服事主。","notes":[]},{"n":12,"t":"在指望中要喜乐；在患难中要忍耐；祷告要恒切。","notes":[]},{"n":13,"t":"圣徒缺乏，要帮补；客，要一味地款待。","notes":[]},{"n":14,"t":"逼迫你们的，要给他们祝福；只要祝福，不可咒诅。","notes":[]},{"n":15,"t":"与喜乐的人要同乐；与哀哭的人要同哭。","notes":[]},{"n":16,"t":"要彼此同心；不要志气高大，倒要俯就卑微的人。不要自以为聪明。","notes":["人：或译事"]},{"n":17,"t":"不要以恶报恶；众人以为美的事要留心去做。","notes":[]},{"n":18,"t":"若是能行，总要尽力与众人和睦。","notes":[]},{"n":19,"t":"亲爱的弟兄，不要自己伸冤，宁可让步，听凭主怒；因为经上记着：「主说：『伸冤在我，我必报应。』」","notes":["或译：让人发怒"]},{"n":20,"t":"所以，「你的仇敌若饿了，就给他吃，若渴了，就给他喝；因为你这样行就是把炭火堆在他的头上。」","notes":[]},{"n":21,"t":"你不可为恶所胜，反要以善胜恶。","notes":[]}]},"13":{"heading":"顺服掌权者","verses":[{"n":1,"t":"在上有权柄的，人人当顺服他，因为没有权柄不是出于神的。凡掌权的都是神所命的。","notes":[]},{"n":2,"t":"所以，抗拒掌权的就是抗拒神的命；抗拒的必自取刑罚。","notes":[]},{"n":3,"t":"作官的原不是叫行善的惧怕，乃是叫作恶的惧怕。你愿意不惧怕掌权的吗？你只要行善，就可得他的称赞；","notes":[]},{"n":4,"t":"因为他是神的用人，是与你有益的。你若作恶，却当惧怕，因为他不是空空地佩剑；他是神的用人，是伸冤的，刑罚那作恶的。","notes":[]},{"n":5,"t":"所以，你们必须顺服，不但是因为刑罚，也是因为良心。","notes":[]},{"n":6,"t":"你们纳粮，也为这个缘故；因他们是神的差役，常常特管这事。","notes":[]},{"n":7,"t":"凡人所当得的，就给他。当得粮的，给他纳粮；当得税的，给他上税；当惧怕的，惧怕他；当恭敬的，恭敬他。","notes":[]},{"n":8,"t":"凡事都不可亏欠人，惟有彼此相爱要常以为亏欠，因为爱人的就完全了律法。","notes":[],"heads":["相爱如兄弟"]},{"n":9,"t":"像那不可奸淫，不可杀人，不可偷盗，不可贪婪，或有别的诫命，都包在爱人如己这一句话之内了。","notes":[]},{"n":10,"t":"爱是不加害与人的，所以爱就完全了律法。","notes":[]},{"n":11,"t":"再者，你们晓得，现今就是该趁早睡醒的时候；因为我们得救，现今比初信的时候更近了。","notes":[],"heads":["白昼将近"]},{"n":12,"t":"黑夜已深，白昼将近。我们就当脱去暗昧的行为，带上光明的兵器。","notes":[]},{"n":13,"t":"行事为人要端正，好像行在白昼。不可荒宴醉酒；不可好色邪荡；不可争竞嫉妒。","notes":[]},{"n":14,"t":"总要披戴主耶稣基督，不要为肉体安排，去放纵私欲。","notes":[]}]},"14":{"heading":"不可论断弟兄","verses":[{"n":1,"t":"信心软弱的，你们要接纳，但不要辩论所疑惑的事。","notes":[]},{"n":2,"t":"有人信百物都可吃；但那软弱的，只吃蔬菜。","notes":[]},{"n":3,"t":"吃的人不可轻看不吃的人；不吃的人不可论断吃的人；因为神已经收纳他了。","notes":[]},{"n":4,"t":"你是谁，竟论断别人的仆人呢？他或站住或跌倒，自有他的主人在；而且他也必要站住，因为主能使他站住。","notes":[]},{"n":5,"t":"有人看这日比那日强；有人看日日都是一样。只是各人心里要意见坚定。","notes":[]},{"n":6,"t":"守日的人是为主守的。吃的人是为主吃的，因他感谢神；不吃的人是为主不吃的，也感谢神。","notes":[]},{"n":7,"t":"我们没有一个人为自己活，也没有一个人为自己死。","notes":[]},{"n":8,"t":"我们若活着，是为主而活；若死了，是为主而死。所以，我们或活或死总是主的人。","notes":[]},{"n":9,"t":"因此，基督死了，又活了，为要作死人并活人的主。","notes":[]},{"n":10,"t":"你这个人，为什么论断弟兄呢？又为什么轻看弟兄呢？因我们都要站在神的台前。","notes":[]},{"n":11,"t":"经上写着：主说：我凭着我的永生起誓：万膝必向我跪拜；万口必向我承认。","notes":[]},{"n":12,"t":"这样看来，我们各人必要将自己的事在神面前说明。","notes":[]},{"n":13,"t":"所以，我们不可再彼此论断，宁可定意谁也不给弟兄放下绊脚跌人之物。","notes":[],"heads":["不可使弟兄跌倒"]},{"n":14,"t":"我凭着主耶稣确知深信，凡物本来没有不洁净的；惟独人以为不洁净的，在他就不洁净了。","notes":[]},{"n":15,"t":"你若因食物叫弟兄忧愁，就不是按着爱人的道理行。基督已经替他死，你不可因你的食物叫他败坏。","notes":[]},{"n":16,"t":"不可叫你的善被人毁谤；","notes":[]},{"n":17,"t":"因为神的国不在乎吃喝，只在乎公义、和平，并圣灵中的喜乐。","notes":[]},{"n":18,"t":"在这几样上服事基督的，就为神所喜悦，又为人所称许。","notes":[]},{"n":19,"t":"所以，我们务要追求和睦的事与彼此建立德行的事。","notes":[]},{"n":20,"t":"不可因食物毁坏神的工程。凡物固然洁净，但有人因食物叫人跌倒，就是他的罪了。","notes":[]},{"n":21,"t":"无论是吃肉是喝酒，是什么别的事，叫弟兄跌倒，一概不做才好。","notes":[]},{"n":22,"t":"你有信心，就当在神面前守着。人在自己以为可行的事上能不自责，就有福了。","notes":[]},{"n":23,"t":"若有疑心而吃的，就必有罪，因为他吃不是出于信心。凡不出于信心的都是罪。","notes":[]}]},"15":{"heading":"不求自己的喜悦，要叫邻舍喜悦","verses":[{"n":1,"t":"我们坚固的人应该担代不坚固人的软弱，不求自己的喜悦。","notes":[]},{"n":2,"t":"我们各人务要叫邻舍喜悦，使他得益处，建立德行。","notes":[]},{"n":3,"t":"因为基督也不求自己的喜悦，如经上所记：「辱骂你人的辱骂都落在我身上。」","notes":[]},{"n":4,"t":"从前所写的圣经都是为教训我们写的，叫我们因圣经所生的忍耐和安慰可以得着盼望。","notes":[]},{"n":5,"t":"但愿赐忍耐安慰的神叫你们彼此同心，效法基督耶稣，","notes":[]},{"n":6,"t":"一心一口荣耀神—我们主耶稣基督的父！","notes":[]},{"n":7,"t":"所以，你们要彼此接纳，如同基督接纳你们一样，使荣耀归与神。","notes":[],"heads":["神的福音一视同仁"]},{"n":8,"t":"我说，基督是为神真理作了受割礼人的执事，要证实所应许列祖的话，","notes":[]},{"n":9,"t":"并叫外邦人因他的怜悯荣耀神。如经上所记：因此，我要在外邦中称赞你，歌颂你的名；","notes":[]},{"n":10,"t":"又说：你们外邦人当与主的百姓一同欢乐；","notes":[]},{"n":11,"t":"又说：外邦啊，你们当赞美主！万民哪，你们都当颂赞他！","notes":[]},{"n":12,"t":"又有以赛亚说：将来有耶西的根，就是那兴起来要治理外邦的；外邦人要仰望他。","notes":[]},{"n":13,"t":"但愿使人有盼望的神，因信将诸般的喜乐、平安充满你们的心，使你们借着圣灵的能力大有盼望！","notes":[]},{"n":14,"t":"弟兄们，我自己也深信你们是满有良善，充足了诸般的知识，也能彼此劝戒。","notes":[],"heads":["保罗的宣教使命"]},{"n":15,"t":"但我稍微放胆写信给你们，是要提醒你们的记性，特因神所给我的恩典，","notes":[]},{"n":16,"t":"使我为外邦人作基督耶稣的仆役，作神福音的祭司，叫所献上的外邦人，因着圣灵成为圣洁，可蒙悦纳。","notes":[]},{"n":17,"t":"所以论到神的事，我在基督耶稣里有可夸的。","notes":[]},{"n":18,"t":"除了基督借我做的那些事，我什么都不敢提，只提他借我言语作为，用神迹奇事的能力，并圣灵的能力，使外邦人顺服；","notes":[]},{"n":19,"t":"甚至我从耶路撒冷，直转到以利哩古，到处传了基督的福音。","notes":[]},{"n":20,"t":"我立了志向，不在基督的名被称过的地方传福音，免得建造在别人的根基上。","notes":[]},{"n":21,"t":"就如经上所记：未曾闻知他信息的，将要看见；未曾听过的，将要明白。","notes":[]},{"n":22,"t":"我因多次被拦阻，总不得到你们那里去。","notes":[],"heads":["保罗计划访问罗马"]},{"n":23,"t":"但如今，在这里再没有可传的地方，而且这好几年，我切心想望到西班牙去的时候，可以到你们那里，","notes":[]},{"n":24,"t":"盼望从你们那里经过，得见你们，先与你们彼此交往，心里稍微满足，然后蒙你们送行。","notes":[]},{"n":25,"t":"但现在，我往耶路撒冷去供给圣徒。","notes":[]},{"n":26,"t":"因为马其顿和亚该亚人乐意凑出捐项给耶路撒冷圣徒中的穷人。","notes":[]},{"n":27,"t":"这固然是他们乐意的，其实也算是所欠的债；因外邦人既然在他们属灵的好处上有分，就当把养身之物供给他们。","notes":[]},{"n":28,"t":"等我办完了这事，把这善果向他们交付明白，我就要路过你们那里，往西班牙去。","notes":[]},{"n":29,"t":"我也晓得，去的时候必带着基督丰盛的恩典而去。","notes":[]},{"n":30,"t":"弟兄们，我借着我们主耶稣基督，又借着圣灵的爱，劝你们与我一同竭力，为我祈求神，","notes":[]},{"n":31,"t":"叫我脱离在犹太不顺从的人，也叫我为耶路撒冷所办的捐项可蒙圣徒悦纳，","notes":[]},{"n":32,"t":"并叫我顺着神的旨意，欢欢喜喜地到你们那里，与你们同得安息。","notes":[]},{"n":33,"t":"愿赐平安的神常和你们众人同在。阿们！","notes":[]}]},"16":{"heading":"问安","verses":[{"n":1,"t":"我对你们举荐我们的姊妹非比；她是坚革哩教会中的女执事。","notes":[]},{"n":2,"t":"请你们为主接待她，合乎圣徒的体统。她在何事上要你们帮助，你们就帮助她；因她素来帮助许多人，也帮助了我。","notes":[]},{"n":3,"t":"问百基拉和亚居拉安。他们在基督耶稣里与我同工，","notes":[]},{"n":4,"t":"也为我的命将自己的颈项置之度外。不但我感谢他们，就是外邦的众教会也感谢他们。","notes":[]},{"n":5,"t":"又问在他们家中的教会安。问我所亲爱的以拜尼土安；他在亚细亚是归基督初结的果子。","notes":[]},{"n":6,"t":"又问马利亚安；她为你们多受劳苦。","notes":[]},{"n":7,"t":"又问我亲属与我一同坐监的安多尼古和犹尼亚安；他们在使徒中是有名望的，也是比我先在基督里。","notes":[]},{"n":8,"t":"又问我在主里面所亲爱的暗伯利安。","notes":[]},{"n":9,"t":"又问在基督里与我们同工的耳巴奴，并我所亲爱的士大古安。","notes":[]},{"n":10,"t":"又问在基督里经过试验的亚比利安。问亚利多布家里的人安。","notes":[]},{"n":11,"t":"又问我亲属希罗天安。问拿其数家在主里的人安。","notes":[]},{"n":12,"t":"又问为主劳苦的土非拿氏和土富撒氏安。问可亲爱为主多受劳苦的彼息氏安。","notes":[]},{"n":13,"t":"又问在主蒙拣选的鲁孚和他母亲安；他的母亲就是我的母亲。","notes":[]},{"n":14,"t":"又问亚逊其土、弗勒干、黑米、八罗巴、黑马，并与他们在一处的弟兄们安。","notes":[]},{"n":15,"t":"又问非罗罗古和犹利亚，尼利亚和他姊妹，同阿林巴并与他们在一处的众圣徒安。","notes":[]},{"n":16,"t":"你们亲嘴问安，彼此务要圣洁。基督的众教会都问你们安。","notes":[]},{"n":17,"t":"弟兄们，那些离间你们、叫你们跌倒、背乎所学之道的人，我劝你们要留意躲避他们。","notes":[]},{"n":18,"t":"因为这样的人不服事我们的主基督，只服事自己的肚腹，用花言巧语诱惑那些老实人的心。","notes":[]},{"n":19,"t":"你们的顺服已经传于众人，所以我为你们欢喜；但我愿意你们在善上聪明，在恶上愚拙。","notes":[]},{"n":20,"t":"赐平安的神快要将撒但践踏在你们脚下。愿我主耶稣基督的恩常和你们同在！","notes":[]},{"n":21,"t":"与我同工的提摩太，和我的亲属路求、耶孙、所西巴德，问你们安。","notes":[]},{"n":22,"t":"我这代笔写信的德提，在主里面问你们安。","notes":[]},{"n":23,"t":"那接待我、也接待全教会的该犹问你们安。","notes":[]},{"n":24,"t":"城内管银库的以拉都和兄弟括土问你们安。","notes":[]},{"n":25,"t":"惟有神能照我所传的福音和所讲的耶稣基督，并照永古隐藏不言的奥秘，坚固你们的心。","notes":[],"heads":["颂赞"]},{"n":26,"t":"这奥秘如今显明出来，而且按着永生神的命，借众先知的书指示万国的民，使他们信服真道。","notes":[]},{"n":27,"t":"愿荣耀，因耶稣基督，归与独一全智的神，直到永远。阿们！","notes":[]}]}},"1CO":{"1":{"heading":"祝福和感谢","verses":[{"n":1,"t":"奉神旨意，蒙召作耶稣基督使徒的保罗，同兄弟所提尼，","notes":[]},{"n":2,"t":"写信给在哥林多神的教会，就是在基督耶稣里成圣、蒙召作圣徒的，以及所有在各处求告我主耶稣基督之名的人。基督是他们的主，也是我们的主。","notes":[]},{"n":3,"t":"愿恩惠、平安从神我们的父并主耶稣基督归与你们。","notes":[]},{"n":4,"t":"我常为你们感谢我的神，因神在基督耶稣里所赐给你们的恩惠；","notes":[]},{"n":5,"t":"又因你们在他里面凡事富足，口才、知识都全备，","notes":[]},{"n":6,"t":"正如我为基督作的见证，在你们心里得以坚固，","notes":[]},{"n":7,"t":"以致你们在恩赐上没有一样不及人的，等候我们的主耶稣基督显现。","notes":[]},{"n":8,"t":"他也必坚固你们到底，叫你们在我们主耶稣基督的日子无可责备。","notes":[]},{"n":9,"t":"神是信实的，你们原是被他所召，好与他儿子—我们的主耶稣基督一同得分。","notes":[]},{"n":10,"t":"弟兄们，我借我们主耶稣基督的名劝你们都说一样的话。你们中间也不可分党，只要一心一意，彼此相合。","notes":[],"heads":["在教会中有纷争"]},{"n":11,"t":"因为革来氏家里的人曾对我提起弟兄们来，说你们中间有纷争。","notes":[]},{"n":12,"t":"我的意思就是你们各人说：「我是属保罗的」；「我是属亚波罗的」；「我是属矶法的」；「我是属基督的」。","notes":[]},{"n":13,"t":"基督是分开的吗？保罗为你们钉了十字架吗？你们是奉保罗的名受了洗吗？","notes":[]},{"n":14,"t":"我感谢神，除了基利司布并该犹以外，我没有给你们一个人施洗，","notes":[]},{"n":15,"t":"免得有人说，你们是奉我的名受洗。","notes":[]},{"n":16,"t":"我也给司提反家施过洗，此外给别人施洗没有，我却记不清。","notes":[]},{"n":17,"t":"基督差遣我，原不是为施洗，乃是为传福音，并不用智慧的言语，免得基督的十字架落了空。","notes":[]},{"n":18,"t":"因为十字架的道理，在那灭亡的人为愚拙；在我们得救的人，却为神的大能。","notes":[],"heads":["基督是神的能力和智慧"]},{"n":19,"t":"就如经上所记：我要灭绝智慧人的智慧，废弃聪明人的聪明。","notes":[]},{"n":20,"t":"智慧人在哪里？文士在哪里？这世上的辩士在哪里？神岂不是叫这世上的智慧变成愚拙吗？","notes":[]},{"n":21,"t":"世人凭自己的智慧，既不认识神，神就乐意用人所当作愚拙的道理拯救那些信的人；这就是神的智慧了。","notes":[]},{"n":22,"t":"犹太人是要神迹，希腊人是求智慧，","notes":[]},{"n":23,"t":"我们却是传钉在十字架的基督，在犹太人为绊脚石，在外邦人为愚拙；","notes":[]},{"n":24,"t":"但在那蒙召的，无论是犹太人、希腊人，基督总为神的能力，神的智慧。","notes":[]},{"n":25,"t":"因神的愚拙总比人智慧，神的软弱总比人强壮。","notes":[]},{"n":26,"t":"弟兄们哪，可见你们蒙召的，按着肉体有智慧的不多，有能力的不多，有尊贵的也不多。","notes":[]},{"n":27,"t":"神却拣选了世上愚拙的，叫有智慧的羞愧；又拣选了世上软弱的，叫那强壮的羞愧。","notes":[]},{"n":28,"t":"神也拣选了世上卑贱的，被人厌恶的，以及那无有的，为要废掉那有的，","notes":[]},{"n":29,"t":"使一切有血气的，在神面前一个也不能自夸。","notes":[]},{"n":30,"t":"但你们得在基督耶稣里是本乎神，神又使他成为我们的智慧、公义、圣洁、救赎。","notes":[]},{"n":31,"t":"如经上所记：「夸口的，当指着主夸口。」","notes":[]}]},"2":{"heading":"传扬钉十字架的基督","verses":[{"n":1,"t":"弟兄们，从前我到你们那里去，并没有用高言大智对你们宣传神的奥秘。","notes":[]},{"n":2,"t":"因为我曾定了主意，在你们中间不知道别的，只知道耶稣基督并他钉十字架。","notes":[]},{"n":3,"t":"我在你们那里，又软弱，又惧怕又甚战兢。","notes":[]},{"n":4,"t":"我说的话、讲的道，不是用智慧委婉的言语，乃是用圣灵和大能的明证，","notes":[]},{"n":5,"t":"叫你们的信不在乎人的智慧，只在乎神的大能。","notes":[]},{"n":6,"t":"然而，在完全的人中，我们也讲智慧。但不是这世上的智慧，也不是这世上有权有位、将要败亡之人的智慧。","notes":[],"heads":["神借着圣灵启示我们"]},{"n":7,"t":"我们讲的，乃是从前所隐藏、神奥秘的智慧，就是神在万世以前预定使我们得荣耀的。","notes":[]},{"n":8,"t":"这智慧世上有权有位的人没有一个知道的，他们若知道，就不把荣耀的主钉在十字架上了。","notes":[]},{"n":9,"t":"如经上所记：神为爱他的人所预备的是眼睛未曾看见，耳朵未曾听见，人心也未曾想到的。","notes":[]},{"n":10,"t":"只有神借着圣灵向我们显明了，因为圣灵参透万事，就是神深奥的事也参透了。","notes":[]},{"n":11,"t":"除了在人里头的灵，谁知道人的事？像这样，除了神的灵，也没有人知道神的事。","notes":[]},{"n":12,"t":"我们所领受的，并不是世上的灵，乃是从神来的灵，叫我们能知道神开恩赐给我们的事。","notes":[]},{"n":13,"t":"并且我们讲说这些事，不是用人智慧所指教的言语，乃是用圣灵所指教的言语，将属灵的话解释属灵的事。","notes":["或译：将属灵的事讲与属灵的人"]},{"n":14,"t":"然而，属血气的人不领会神圣灵的事，反倒以为愚拙，并且不能知道，因为这些事惟有属灵的人才能看透。","notes":[]},{"n":15,"t":"属灵的人能看透万事，却没有一人能看透了他。","notes":[]},{"n":16,"t":"谁曾知道主的心去教导他呢？但我们是有基督的心了。","notes":[]}]},"3":{"heading":"神的同工","verses":[{"n":1,"t":"弟兄们，我从前对你们说话，不能把你们当作属灵的，只得把你们当作属肉体，在基督里为婴孩的。","notes":[]},{"n":2,"t":"我是用奶喂你们，没有用饭喂你们。那时你们不能吃，就是如今还是不能。","notes":[]},{"n":3,"t":"你们仍是属肉体的，因为在你们中间有嫉妒、纷争，这岂不是属乎肉体、照着世人的样子行吗？","notes":[]},{"n":4,"t":"有说：「我是属保罗的」；有说：「我是属亚波罗的。」这岂不是你们和世人一样吗？","notes":[]},{"n":5,"t":"亚波罗算什么？保罗算什么？无非是执事，照主所赐给他们各人的，引导你们相信。","notes":[]},{"n":6,"t":"我栽种了，亚波罗浇灌了，惟有神叫他生长。","notes":[]},{"n":7,"t":"可见栽种的，算不得什么，浇灌的，也算不得什么；只在那叫他生长的神。","notes":[]},{"n":8,"t":"栽种的和浇灌的，都是一样，但将来各人要照自己的工夫得自己的赏赐。","notes":[]},{"n":9,"t":"因为我们是与神同工的；你们是神所耕种的田地，所建造的房屋。","notes":[]},{"n":10,"t":"我照神所给我的恩，好像一个聪明的工头，立好了根基，有别人在上面建造；只是各人要谨慎怎样在上面建造。","notes":[]},{"n":11,"t":"因为那已经立好的根基就是耶稣基督，此外没有人能立别的根基。","notes":[]},{"n":12,"t":"若有人用金、银、宝石、草木、禾秸在这根基上建造，","notes":[]},{"n":13,"t":"各人的工程必然显露，因为那日子要将它表明出来，有火发现；这火要试验各人的工程怎样。","notes":[]},{"n":14,"t":"人在那根基上所建造的工程若存得住，他就要得赏赐。","notes":[]},{"n":15,"t":"人的工程若被烧了，他就要受亏损，自己却要得救；虽然得救，乃像从火里经过的一样。","notes":[]},{"n":16,"t":"岂不知你们是神的殿，神的灵住在你们里头吗？","notes":[]},{"n":17,"t":"若有人毁坏神的殿，神必要毁坏那人；因为神的殿是圣的，这殿就是你们。","notes":[]},{"n":18,"t":"人不可自欺。你们中间若有人在这世界自以为有智慧，倒不如变作愚拙，好成为有智慧的。","notes":[]},{"n":19,"t":"因这世界的智慧，在神看是愚拙。如经上记着说：「主叫有智慧的，中了自己的诡计」；","notes":[]},{"n":20,"t":"又说：「主知道智慧人的意念是虚妄的。」","notes":[]},{"n":21,"t":"所以无论谁，都不可拿人夸口，因为万有全是你们的。","notes":[]},{"n":22,"t":"或保罗，或亚波罗，或矶法，或世界，或生，或死，或现今的事，或将来的事，全是你们的；","notes":[]},{"n":23,"t":"并且你们是属基督的，基督又是属神的。","notes":[]}]},"4":{"heading":"使徒的工作","verses":[{"n":1,"t":"人应当以我们为基督的执事，为神奥秘事的管家。","notes":[]},{"n":2,"t":"所求于管家的，是要他有忠心。","notes":[]},{"n":3,"t":"我被你们论断，或被别人论断，我都以为极小的事；连我自己也不论断自己。","notes":[]},{"n":4,"t":"我虽不觉得自己有错，却也不能因此得以称义；但判断我的乃是主。","notes":[]},{"n":5,"t":"所以，时候未到，什么都不要论断，只等主来，他要照出暗中的隐情，显明人心的意念。那时，各人要从神那里得着称赞。","notes":[]},{"n":6,"t":"弟兄们，我为你们的缘故，拿这些事转比自己和亚波罗，叫你们效法我们不可过于圣经所记，免得你们自高自大，贵重这个，轻看那个。","notes":[]},{"n":7,"t":"使你与人不同的是谁呢？你有什么不是领受的呢？若是领受的，为何自夸，仿佛不是领受的呢？","notes":[]},{"n":8,"t":"你们已经饱足了！已经丰富了！不用我们，自己就作王了！我愿意你们果真作王，叫我们也得与你们一同作王。","notes":[]},{"n":9,"t":"我想神把我们使徒明明列在末后，好像定死罪的囚犯；因为我们成了一台戏，给世人和天使观看。","notes":[]},{"n":10,"t":"我们为基督的缘故算是愚拙的，你们在基督里倒是聪明的；我们软弱，你们倒强壮；你们有荣耀，我们倒被藐视。","notes":[]},{"n":11,"t":"直到如今，我们还是又饥又渴，又赤身露体，又挨打，又没有一定的住处，","notes":[]},{"n":12,"t":"并且劳苦，亲手做工。被人咒骂，我们就祝福；被人逼迫，我们就忍受；","notes":[]},{"n":13,"t":"被人毁谤，我们就善劝。直到如今，人还把我们看作世界上的污秽，万物中的渣滓。","notes":[]},{"n":14,"t":"我写这话，不是叫你们羞愧，乃是警戒你们，好像我所亲爱的儿女一样。","notes":[]},{"n":15,"t":"你们学基督的，师傅虽有一万，为父的却是不多，因我在基督耶稣里用福音生了你们。","notes":[]},{"n":16,"t":"所以，我求你们效法我。","notes":[]},{"n":17,"t":"因此我已打发提摩太到你们那里去。他在主里面，是我所亲爱、有忠心的儿子。他必提醒你们，记念我在基督里怎样行事，在各处各教会中怎样教导人。","notes":[]},{"n":18,"t":"有些人自高自大，以为我不到你们那里去；","notes":[]},{"n":19,"t":"然而，主若许我，我必快到你们那里去，并且我所要知道的，不是那些自高自大之人的言语，乃是他们的权能。","notes":[]},{"n":20,"t":"因为神的国不在乎言语，乃在乎权能。","notes":[]},{"n":21,"t":"你们愿意怎么样呢？是愿意我带着刑杖到你们那里去呢？还是要我存慈爱温柔的心呢？","notes":[]}]},"5":{"heading":"判断淫乱的事件","verses":[{"n":1,"t":"风闻在你们中间有淫乱的事。这样的淫乱连外邦人中也没有，就是有人收了他的继母。","notes":[]},{"n":2,"t":"你们还是自高自大，并不哀痛，把行这事的人从你们中间赶出去。","notes":[]},{"n":3,"t":"我身子虽不在你们那里，心却在你们那里，好像我亲自与你们同在，已经判断了行这事的人。","notes":[]},{"n":4,"t":"就是你们聚会的时候，我的心也同在。奉我们主耶稣的名，并用我们主耶稣的权能，","notes":[]},{"n":5,"t":"要把这样的人交给撒但，败坏他的肉体，使他的灵魂在主耶稣的日子可以得救。","notes":[]},{"n":6,"t":"你们这自夸是不好的。岂不知一点面酵能使全团发起来吗？","notes":[]},{"n":7,"t":"你们既是无酵的面，应当把旧酵除净，好使你们成为新团；因为我们逾越节的羔羊基督已经被杀献祭了。","notes":[]},{"n":8,"t":"所以，我们守这节不可用旧酵，也不可用恶毒、邪恶的酵，只用诚实真正的无酵饼。","notes":["或译：阴毒"]},{"n":9,"t":"我先前写信给你们说，不可与淫乱的人相交。","notes":[]},{"n":10,"t":"此话不是指这世上一概行淫乱的，或贪婪的，勒索的，或拜偶像的；若是这样，你们除非离开世界方可。","notes":[]},{"n":11,"t":"但如今我写信给你们说，若有称为弟兄是行淫乱的，或贪婪的，或拜偶像的，或辱骂的，或醉酒的，或勒索的，这样的人不可与他相交，就是与他吃饭都不可。","notes":[]},{"n":12,"t":"因为审判教外的人与我何干？教内的人岂不是你们审判的吗？","notes":[]},{"n":13,"t":"至于外人有神审判他们。你们应当把那恶人从你们中间赶出去。","notes":[]}]},"6":{"heading":"在不信主的人面前求审","verses":[{"n":1,"t":"你们中间有彼此相争的事，怎敢在不义的人面前求审，不在圣徒面前求审呢？","notes":[]},{"n":2,"t":"岂不知圣徒要审判世界吗？若世界为你们所审，难道你们不配审判这最小的事吗？","notes":[]},{"n":3,"t":"岂不知我们要审判天使吗？何况今生的事呢？","notes":[]},{"n":4,"t":"既是这样，你们若有今生的事当审判，是派教会所轻看的人审判吗？","notes":[]},{"n":5,"t":"我说这话是要叫你们羞耻。难道你们中间没有一个智慧人能审断弟兄们的事吗？","notes":[]},{"n":6,"t":"你们竟是弟兄与弟兄告状，而且告在不信主的人面前。","notes":[]},{"n":7,"t":"你们彼此告状，这已经是你们的大错了。为什么不情愿受欺呢？为什么不情愿吃亏呢？","notes":[]},{"n":8,"t":"你们倒是欺压人、亏负人，况且所欺压所亏负的就是弟兄。","notes":[]},{"n":9,"t":"你们岂不知不义的人不能承受神的国吗？不要自欺！无论是淫乱的、拜偶像的、奸淫的、作娈童的、亲男色的、","notes":[]},{"n":10,"t":"偷窃的、贪婪的、醉酒的、辱骂的、勒索的，都不能承受神的国。","notes":[]},{"n":11,"t":"你们中间也有人从前是这样；但如今你们奉主耶稣基督的名，并借着我们神的灵，已经洗净，成圣，称义了。","notes":[]},{"n":12,"t":"凡事我都可行，但不都有益处。凡事我都可行，但无论哪一件，我总不受它的辖制。","notes":[],"heads":["在身子上荣耀神"]},{"n":13,"t":"食物是为肚腹，肚腹是为食物；但神要叫这两样都废坏。身子不是为淫乱，乃是为主；主也是为身子。","notes":[]},{"n":14,"t":"并且神已经叫主复活，也要用自己的能力叫我们复活。","notes":[]},{"n":15,"t":"岂不知你们的身子是基督的肢体吗？我可以将基督的肢体作为娼妓的肢体吗？断乎不可！","notes":[]},{"n":16,"t":"岂不知与娼妓联合的，便是与她成为一体吗？因为主说：「二人要成为一体。」","notes":[]},{"n":17,"t":"但与主联合的，便是与主成为一灵。","notes":[]},{"n":18,"t":"你们要逃避淫行。人所犯的，无论什么罪，都在身子以外，惟有行淫的，是得罪自己的身子。","notes":[]},{"n":19,"t":"岂不知你们的身子就是圣灵的殿吗？这圣灵是从神而来，住在你们里头的；并且你们不是自己的人，","notes":[]},{"n":20,"t":"因为你们是重价买来的。所以，要在你们的身子上荣耀神。","notes":[]}]},"7":{"heading":"婚姻的问题","verses":[{"n":1,"t":"论到你们信上所提的事，我说男不近女倒好。","notes":[]},{"n":2,"t":"但要免淫乱的事，男子当各有自己的妻子；女子也当各有自己的丈夫。","notes":[]},{"n":3,"t":"丈夫当用合宜之分待妻子；妻子待丈夫也要如此。","notes":[]},{"n":4,"t":"妻子没有权柄主张自己的身子，乃在丈夫；丈夫也没有权柄主张自己的身子，乃在妻子。","notes":[]},{"n":5,"t":"夫妻不可彼此亏负，除非两相情愿，暂时分房，为要专心祷告方可；以后仍要同房，免得撒但趁着你们情不自禁，引诱你们。","notes":[]},{"n":6,"t":"我说这话，原是准你们的，不是命你们的。","notes":[]},{"n":7,"t":"我愿意众人像我一样；只是各人领受神的恩赐，一个是这样，一个是那样。","notes":[]},{"n":8,"t":"我对着没有嫁娶的和寡妇说，若他们常像我就好。","notes":[]},{"n":9,"t":"倘若自己禁止不住，就可以嫁娶。与其欲火攻心，倒不如嫁娶为妙。","notes":[]},{"n":10,"t":"至于那已经嫁娶的，我吩咐他们；其实不是我吩咐，乃是主吩咐说：妻子不可离开丈夫，","notes":[]},{"n":11,"t":"若是离开了，不可再嫁，或是仍同丈夫和好。丈夫也不可离弃妻子。","notes":[]},{"n":12,"t":"我对其余的人说（不是主说）：倘若某弟兄有不信的妻子，妻子也情愿和他同住，他就不要离弃妻子。","notes":[]},{"n":13,"t":"妻子有不信的丈夫，丈夫也情愿和她同住，她就不要离弃丈夫。","notes":[]},{"n":14,"t":"因为不信的丈夫就因着妻子成了圣洁，并且不信的妻子就因着丈夫成了圣洁。不然，你们的儿女就不洁净，但如今他们是圣洁的了。","notes":["原文是弟兄"]},{"n":15,"t":"倘若那不信的人要离去，就由他离去吧！无论是弟兄，是姊妹，遇着这样的事都不必拘束。神召我们原是要我们和睦。","notes":[]},{"n":16,"t":"你这作妻子的，怎么知道不能救你的丈夫呢？你这作丈夫的，怎么知道不能救你的妻子呢？","notes":[]},{"n":17,"t":"只要照主所分给各人的，和神所召各人的而行。我吩咐各教会都是这样。","notes":[],"heads":["照主分给各人的去行"]},{"n":18,"t":"有人已受割礼蒙召呢，就不要废割礼；有人未受割礼蒙召呢，就不要受割礼。","notes":[]},{"n":19,"t":"受割礼算不得什么，不受割礼也算不得什么，只要守神的诫命就是了。","notes":[]},{"n":20,"t":"各人蒙召的时候是什么身分，仍要守住这身分。","notes":[]},{"n":21,"t":"你是作奴隶蒙召的吗？不要因此忧虑；若能以自由，就求自由更好。","notes":[]},{"n":22,"t":"因为作奴仆蒙召于主的，就是主所释放的人；作自由之人蒙召的，就是基督的奴仆。","notes":[]},{"n":23,"t":"你们是重价买来的，不要作人的奴仆。","notes":[]},{"n":24,"t":"弟兄们，你们各人蒙召的时候是什么身分，仍要在神面前守住这身分。","notes":[]},{"n":25,"t":"论到童身的人，我没有主的命令，但我既蒙主怜恤能作忠心的人，就把自己的意见告诉你们。","notes":[],"heads":["未婚和寡居"]},{"n":26,"t":"因现今的艰难，据我看来，人不如守素安常才好。","notes":[]},{"n":27,"t":"你有妻子缠着呢，就不要求脱离；你没有妻子缠着呢，就不要求妻子。","notes":[]},{"n":28,"t":"你若娶妻，并不是犯罪；处女若出嫁，也不是犯罪。然而这等人肉身必受苦难，我却愿意你们免这苦难。","notes":[]},{"n":29,"t":"弟兄们，我对你们说：时候减少了。从此以后，那有妻子的，要像没有妻子；","notes":[]},{"n":30,"t":"哀哭的，要像不哀哭；快乐的，要像不快乐；置买的，要像无有所得；","notes":[]},{"n":31,"t":"用世物的，要像不用世物，因为这世界的样子将要过去了。","notes":[]},{"n":32,"t":"我愿你们无所挂虑。没有娶妻的，是为主的事挂虑，想怎样叫主喜悦。","notes":[]},{"n":33,"t":"娶了妻的，是为世上的事挂虑，想怎样叫妻子喜悦。","notes":[]},{"n":34,"t":"妇人和处女也有分别。没有出嫁的，是为主的事挂虑，要身体、灵魂都圣洁；已经出嫁的，是为世上的事挂虑，想怎样叫丈夫喜悦。","notes":[]},{"n":35,"t":"我说这话是为你们的益处，不是要牢笼你们，乃是要叫你们行合宜的事，得以殷勤服事主，没有分心的事。","notes":[]},{"n":36,"t":"若有人以为自己待他的女儿不合宜，女儿也过了年岁，事又当行，他就可随意办理，不算有罪，叫二人成亲就是了。","notes":[]},{"n":37,"t":"倘若人心里坚定，没有不得已的事，并且由得自己作主，心里又决定了留下女儿不出嫁，如此行也好。","notes":[]},{"n":38,"t":"这样看来，叫自己的女儿出嫁是好，不叫她出嫁更是好。","notes":[]},{"n":39,"t":"丈夫活着的时候，妻子是被约束的；丈夫若死了，妻子就可以自由，随意再嫁，只是要嫁这在主里面的人。","notes":[]},{"n":40,"t":"然而按我的意见，若常守节更有福气。我也想自己是被神的灵感动了。","notes":[]}]},"8":{"heading":"祭过偶像的食物","verses":[{"n":1,"t":"论到祭偶像之物，我们晓得我们都有知识。但知识是叫人自高自大，惟有爱心能造就人。","notes":[]},{"n":2,"t":"若有人以为自己知道什么，按他所当知道的，他仍是不知道。","notes":[]},{"n":3,"t":"若有人爱神，这人乃是神所知道的。","notes":[]},{"n":4,"t":"论到吃祭偶像之物，我们知道偶像在世上算不得什么，也知道神只有一位，再没有别的神。","notes":[]},{"n":5,"t":"虽有称为神的，或在天，或在地，就如那许多的神，许多的主；","notes":[]},{"n":6,"t":"然而我们只有一位神，就是父—万物都本于他；我们也归于他—并有一位主，就是耶稣基督—万物都是借着他有的；我们也是借着他有的。","notes":[]},{"n":7,"t":"但人不都有这等知识。有人到如今因拜惯了偶像，就以为所吃的是祭偶像之物。他们的良心既然软弱，也就污秽了。","notes":[]},{"n":8,"t":"其实食物不能叫神看中我们，因为我们不吃也无损，吃也无益。","notes":[]},{"n":9,"t":"只是你们要谨慎，恐怕你们这自由竟成了那软弱人的绊脚石。","notes":[]},{"n":10,"t":"若有人见你这有知识的，在偶像的庙里坐席，这人的良心若是软弱，岂不放胆去吃那祭偶像之物吗？","notes":[]},{"n":11,"t":"因此，基督为他死的那软弱弟兄，也就因你的知识沉沦了。","notes":[]},{"n":12,"t":"你们这样得罪弟兄们，伤了他们软弱的良心，就是得罪基督。","notes":[]},{"n":13,"t":"所以，食物若叫我弟兄跌倒，我就永远不吃肉，免得叫我弟兄跌倒了。","notes":[]}]},"9":{"heading":"使徒的权利","verses":[{"n":1,"t":"我不是自由的吗？我不是使徒吗？我不是见过我们的主耶稣吗？你们不是我在主里面所做之工吗？","notes":[]},{"n":2,"t":"假若在别人，我不是使徒，在你们，我总是使徒，因为你们在主里正是我作使徒的印证。","notes":[]},{"n":3,"t":"我对那盘问我的人就是这样分诉：","notes":[]},{"n":4,"t":"难道我们没有权柄靠福音吃喝吗？","notes":[]},{"n":5,"t":"难道我们没有权柄娶信主的姊妹为妻，带着一同往来，仿佛其余的使徒和主的弟兄并矶法一样吗？","notes":[]},{"n":6,"t":"独有我与巴拿巴没有权柄不做工吗？","notes":[]},{"n":7,"t":"有谁当兵自备粮饷呢？有谁栽葡萄园不吃园里的果子呢？有谁牧养牛羊不吃牛羊的奶呢？","notes":[]},{"n":8,"t":"我说这话，岂是照人的意见；律法不也是这样说吗？","notes":[]},{"n":9,"t":"就如摩西的律法记着说：「牛在场上踹谷的时候，不可笼住它的嘴。」难道神所挂念的是牛吗？","notes":[]},{"n":10,"t":"不全是为我们说的吗？分明是为我们说的。因为耕种的当存着指望去耕种；打场的也当存得粮的指望去打场。","notes":[]},{"n":11,"t":"我们若把属灵的种子撒在你们中间，就是从你们收割奉养肉身之物，这还算大事吗？","notes":[]},{"n":12,"t":"若别人在你们身上有这权柄，何况我们呢？然而，我们没有用过这权柄，倒凡事忍受，免得基督的福音被阻隔。","notes":[]},{"n":13,"t":"你们岂不知为圣事劳碌的就吃殿中的物吗？伺候祭坛的就分领坛上的物吗？","notes":[]},{"n":14,"t":"主也是这样命定，叫传福音的靠着福音养生。","notes":[]},{"n":15,"t":"但这权柄我全没有用过。我写这话，并非要你们这样待我，因为我宁可死也不叫人使我所夸的落了空。","notes":[]},{"n":16,"t":"我传福音原没有可夸的，因为我是不得已的。若不传福音，我便有祸了。","notes":[]},{"n":17,"t":"我若甘心做这事，就有赏赐；若不甘心，责任却已经托付我了。","notes":[]},{"n":18,"t":"既是这样，我的赏赐是什么呢？就是我传福音的时候叫人不花钱得福音，免得用尽我传福音的权柄。","notes":[]},{"n":19,"t":"我虽是自由的，无人辖管；然而我甘心作了众人的仆人，为要多得人。","notes":[]},{"n":20,"t":"向犹太人，我就作犹太人，为要得犹太人；向律法以下的人，我虽不在律法以下，还是作律法以下的人，为要得律法以下的人。","notes":[]},{"n":21,"t":"向没有律法的人，我就作没有律法的人，为要得没有律法的人；其实我在神面前，不是没有律法；在基督面前，正在律法之下。","notes":[]},{"n":22,"t":"向软弱的人，我就作软弱的人，为要得软弱的人。向什么样的人，我就作什么样的人。无论如何，总要救些人。","notes":[]},{"n":23,"t":"凡我所行的，都是为福音的缘故，为要与人同得这福音的好处。","notes":[]},{"n":24,"t":"岂不知在场上赛跑的都跑，但得奖赏的只有一人？你们也当这样跑，好叫你们得着奖赏。","notes":[]},{"n":25,"t":"凡较力争胜的，诸事都有节制，他们不过是要得能坏的冠冕；我们却是要得不能坏的冠冕。","notes":[]},{"n":26,"t":"所以，我奔跑不像无定向的；我斗拳不像打空气的。","notes":[]},{"n":27,"t":"我是攻克己身，叫身服我，恐怕我传福音给别人，自己反被弃绝了。","notes":[]}]},"10":{"heading":"警戒拜偶像的事","verses":[{"n":1,"t":"弟兄们，我不愿意你们不晓得，我们的祖宗从前都在云下，都从海中经过，","notes":[]},{"n":2,"t":"都在云里、海里受洗归了摩西；","notes":[]},{"n":3,"t":"并且都吃了一样的灵食，","notes":[]},{"n":4,"t":"也都喝了一样的灵水。所喝的，是出于随着他们的灵磐石；那磐石就是基督。","notes":[]},{"n":5,"t":"但他们中间多半是神不喜欢的人，所以在旷野倒毙。","notes":[]},{"n":6,"t":"这些事都是我们的鉴戒，叫我们不要贪恋恶事，像他们那样贪恋的；","notes":[]},{"n":7,"t":"也不要拜偶像，像他们有人拜的。如经上所记：「百姓坐下吃喝，起来玩耍。」","notes":[]},{"n":8,"t":"我们也不要行奸淫，像他们有人行的，一天就倒毙了二万三千人；","notes":[]},{"n":9,"t":"也不要试探主，像他们有人试探的，就被蛇所灭。","notes":["有古卷：基督"]},{"n":10,"t":"你们也不要发怨言，像他们有发怨言的，就被灭命的所灭。","notes":[]},{"n":11,"t":"他们遭遇这些事都要作为鉴戒，并且写在经上，正是警戒我们这末世的人。","notes":[]},{"n":12,"t":"所以，自己以为站得稳的，须要谨慎，免得跌倒。","notes":[]},{"n":13,"t":"你们所遇见的试探，无非是人所能受的。神是信实的，必不叫你们受试探过于所能受的；在受试探的时候，总要给你们开一条出路，叫你们能忍受得住。","notes":[]},{"n":14,"t":"我所亲爱的弟兄啊，你们要逃避拜偶像的事。","notes":[]},{"n":15,"t":"我好像对明白人说的，你们要审察我的话。","notes":[]},{"n":16,"t":"我们所祝福的杯，岂不是同领基督的血吗？我们所擘开的饼，岂不是同领基督的身体吗？","notes":[]},{"n":17,"t":"我们虽多，仍是一个饼，一个身体，因为我们都是分受这一个饼。","notes":[]},{"n":18,"t":"你们看属肉体的以色列人，那吃祭物的岂不是在祭坛上有分吗？","notes":[]},{"n":19,"t":"我是怎么说呢？岂是说祭偶像之物算得什么呢？或说偶像算得什么呢？","notes":[]},{"n":20,"t":"我乃是说，外邦人所献的祭是祭鬼，不是祭神。我不愿意你们与鬼相交。","notes":[]},{"n":21,"t":"你们不能喝主的杯又喝鬼的杯，不能吃主的筵席又吃鬼的筵席。","notes":[]},{"n":22,"t":"我们可惹主的愤恨吗？我们比他还有能力吗？","notes":[]},{"n":23,"t":"凡事都可行，但不都有益处。凡事都可行，但不都造就人。","notes":[],"heads":["凡事为荣耀神而行"]},{"n":24,"t":"无论何人，不要求自己的益处，乃要求别人的益处。","notes":[]},{"n":25,"t":"凡市上所卖的，你们只管吃，不要为良心的缘故问什么话，","notes":[]},{"n":26,"t":"因为地和其中所充满的都属乎主。","notes":[]},{"n":27,"t":"倘有一个不信的人请你们赴席，你们若愿意去，凡摆在你们面前的，只管吃，不要为良心的缘故问什么话。","notes":[]},{"n":28,"t":"若有人对你们说：「这是献过祭的物」，就要为那告诉你们的人，并为良心的缘故不吃。","notes":[]},{"n":29,"t":"我说的良心不是你的，乃是他的。我这自由为什么被别人的良心论断呢？","notes":[]},{"n":30,"t":"我若谢恩而吃，为什么因我谢恩的物被人毁谤呢？","notes":[]},{"n":31,"t":"所以，你们或吃或喝，无论做什么，都要为荣耀神而行。","notes":[]},{"n":32,"t":"不拘是犹太人，是希腊人，是神的教会，你们都不要使他跌倒；","notes":[]},{"n":33,"t":"就好像我凡事都叫众人喜欢，不求自己的益处，只求众人的益处，叫他们得救。","notes":[]}]},"11":{"heading":"礼拜时蒙头的问题","verses":[{"n":1,"t":"你们该效法我，像我效法基督一样。","notes":[]},{"n":2,"t":"我称赞你们，因你们凡事记念我，又坚守我所传给你们的。","notes":[]},{"n":3,"t":"我愿意你们知道，基督是各人的头；男人是女人的头；神是基督的头。","notes":[]},{"n":4,"t":"凡男人祷告或是讲道，若蒙着头，就羞辱自己的头。","notes":["或译：说预言；下同"]},{"n":5,"t":"凡女人祷告或是讲道，若不蒙着头，就羞辱自己的头，因为这就如同剃了头发一样。","notes":[]},{"n":6,"t":"女人若不蒙着头，就该剪了头发；女人若以剪发、剃发为羞愧，就该蒙着头。","notes":[]},{"n":7,"t":"男人本不该蒙着头，因为他是神的形象和荣耀；但女人是男人的荣耀。","notes":[]},{"n":8,"t":"起初，男人不是由女人而出，女人乃是由男人而出；","notes":[]},{"n":9,"t":"并且男人不是为女人造的，女人乃是为男人造的。","notes":[]},{"n":10,"t":"因此，女人为天使的缘故，应当在头上有服权柄的记号。","notes":[]},{"n":11,"t":"然而照主的安排，女也不是无男，男也不是无女。","notes":[]},{"n":12,"t":"因为女人原是由男人而出，男人也是由女人而出；但万有都是出乎神。","notes":[]},{"n":13,"t":"你们自己审察，女人祷告神，不蒙着头是合宜的吗？","notes":[]},{"n":14,"t":"你们的本性不也指示你们，男人若有长头发，便是他的羞辱吗？","notes":[]},{"n":15,"t":"但女人有长头发，乃是她的荣耀，因为这头发是给她作盖头的。","notes":[]},{"n":16,"t":"若有人想要辩驳，我们却没有这样的规矩，神的众教会也是没有的。","notes":[]},{"n":17,"t":"我现今吩咐你们的话，不是称赞你们；因为你们聚会不是受益，乃是招损。","notes":[],"heads":["圣餐时的混乱"]},{"n":18,"t":"第一，我听说，你们聚会的时候彼此分门别类，我也稍微地信这话。","notes":[]},{"n":19,"t":"在你们中间不免有分门结党的事，好叫那些有经验的人显明出来。","notes":[]},{"n":20,"t":"你们聚会的时候，算不得吃主的晚餐；","notes":[]},{"n":21,"t":"因为吃的时候，各人先吃自己的饭，甚至这个饥饿，那个酒醉。","notes":[]},{"n":22,"t":"你们要吃喝，难道没有家吗？还是藐视神的教会，叫那没有的羞愧呢？我向你们可怎么说呢？可因此称赞你们吗？我不称赞！","notes":[]},{"n":23,"t":"我当日传给你们的，原是从主领受的，就是主耶稣被卖的那一夜，拿起饼来，","notes":[],"heads":["圣餐的设立"]},{"n":24,"t":"祝谢了，就擘开，说：「这是我的身体，为你们舍的，你们应当如此行，为的是记念我。」","notes":["有古卷：擘开"]},{"n":25,"t":"饭后，也照样拿起杯来，说：「这杯是用我的血所立的新约，你们每逢喝的时候，要如此行，为的是记念我。」","notes":[]},{"n":26,"t":"你们每逢吃这饼，喝这杯，是表明主的死，直等到他来。","notes":[]},{"n":27,"t":"所以，无论何人，不按理吃主的饼，喝主的杯，就是干犯主的身、主的血了。","notes":[],"heads":["不按理吃主的晚餐"]},{"n":28,"t":"人应当自己省察，然后吃这饼、喝这杯。","notes":[]},{"n":29,"t":"因为人吃喝，若不分辨是主的身体，就是吃喝自己的罪了。","notes":[]},{"n":30,"t":"因此，在你们中间有好些软弱的与患病的，死的也不少。","notes":["原文是睡"]},{"n":31,"t":"我们若是先分辨自己，就不至于受审。","notes":[]},{"n":32,"t":"我们受审的时候，乃是被主惩治，免得我们和世人一同定罪。","notes":[]},{"n":33,"t":"所以我弟兄们，你们聚会吃的时候，要彼此等待。","notes":[]},{"n":34,"t":"若有人饥饿，可以在家里先吃，免得你们聚会，自己取罪。其余的事，我来的时候再安排。","notes":[]}]},"12":{"heading":"属灵的恩赐","verses":[{"n":1,"t":"弟兄们，论到属灵的恩赐，我不愿意你们不明白。","notes":[]},{"n":2,"t":"你们作外邦人的时候，随事被牵引，受迷惑，去服事那哑巴偶像，这是你们知道的。","notes":[]},{"n":3,"t":"所以我告诉你们，被神的灵感动的，没有说「耶稣是可咒诅」的；若不是被圣灵感动的，也没有能说「耶稣是主」的。","notes":[]},{"n":4,"t":"恩赐原有分别，圣灵却是一位。","notes":[]},{"n":5,"t":"职事也有分别，主却是一位。","notes":[]},{"n":6,"t":"功用也有分别，神却是一位，在众人里面运行一切的事。","notes":[]},{"n":7,"t":"圣灵显在各人身上，是叫人得益处。","notes":[]},{"n":8,"t":"这人蒙圣灵赐他智慧的言语，那人也蒙这位圣灵赐他知识的言语，","notes":[]},{"n":9,"t":"又有一人蒙这位圣灵赐他信心，还有一人蒙这位圣灵赐他医病的恩赐，","notes":[]},{"n":10,"t":"又叫一人能行异能，又叫一人能作先知，又叫一人能辨别诸灵，又叫一人能说方言，又叫一人能翻方言。","notes":[]},{"n":11,"t":"这一切都是这位圣灵所运行、随己意分给各人的。","notes":[]},{"n":12,"t":"就如身子是一个，却有许多肢体；而且肢体虽多，仍是一个身子；基督也是这样。","notes":[],"heads":["一个身体有许多肢体"]},{"n":13,"t":"我们不拘是犹太人，是希腊人，是为奴的，是自主的，都从一位圣灵受洗，成了一个身体，饮于一位圣灵。","notes":[]},{"n":14,"t":"身子原不是一个肢体，乃是许多肢体。","notes":[]},{"n":15,"t":"设若脚说：「我不是手，所以不属乎身子，」它不能因此就不属乎身子。","notes":[]},{"n":16,"t":"设若耳说：「我不是眼，所以不属乎身子，」它也不能因此就不属乎身子。","notes":[]},{"n":17,"t":"若全身是眼，从哪里听声呢？若全身是耳，从哪里闻味呢？","notes":[]},{"n":18,"t":"但如今，神随自己的意思把肢体俱各安排在身上了。","notes":[]},{"n":19,"t":"若都是一个肢体，身子在哪里呢？","notes":[]},{"n":20,"t":"但如今肢体是多的，身子却是一个。","notes":[]},{"n":21,"t":"眼不能对手说：「我用不着你」；头也不能对脚说：「我用不着你。」","notes":[]},{"n":22,"t":"不但如此，身上肢体人以为软弱的，更是不可少的。","notes":[]},{"n":23,"t":"身上肢体，我们看为不体面的，越发给它加上体面；不俊美的，越发得着俊美。","notes":[]},{"n":24,"t":"我们俊美的肢体，自然用不着装饰；但神配搭这身子，把加倍的体面给那有缺欠的肢体，","notes":[]},{"n":25,"t":"免得身上分门别类，总要肢体彼此相顾。","notes":[]},{"n":26,"t":"若一个肢体受苦，所有的肢体就一同受苦；若一个肢体得荣耀，所有的肢体就一同快乐。","notes":[]},{"n":27,"t":"你们就是基督的身子，并且各自作肢体。","notes":[]},{"n":28,"t":"神在教会所设立的：第一是使徒，第二是先知，第三是教师，其次是行异能的，再次是得恩赐医病的，帮助人的，治理事的，说方言的。","notes":[]},{"n":29,"t":"岂都是使徒吗？岂都是先知吗？岂都是教师吗？岂都是行异能的吗？","notes":[]},{"n":30,"t":"岂都是得恩赐医病的吗？岂都是说方言的吗？岂都是翻方言的吗？","notes":[]},{"n":31,"t":"你们要切切地求那更大的恩赐。我现今把最妙的道指示你们。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"我若能说万人的方言，并天使的话语，却没有爱，我就成了鸣的锣，响的钹一般。","notes":[]},{"n":2,"t":"我若有先知讲道之能，也明白各样的奥秘，各样的知识，而且有全备的信，叫我能够移山，却没有爱，我就算不得什么。","notes":[]},{"n":3,"t":"我若将所有的周济穷人，又舍己身叫人焚烧，却没有爱，仍然与我无益。","notes":[]},{"n":4,"t":"爱是恒久忍耐，又有恩慈；爱是不嫉妒；爱是不自夸，不张狂，","notes":[]},{"n":5,"t":"不做害羞的事，不求自己的益处，不轻易发怒，不计算人的恶，","notes":[]},{"n":6,"t":"不喜欢不义，只喜欢真理；","notes":[]},{"n":7,"t":"凡事包容，凡事相信，凡事盼望，凡事忍耐。","notes":[]},{"n":8,"t":"爱是永不止息。先知讲道之能终必归于无有；说方言之能终必停止；知识也终必归于无有。","notes":[]},{"n":9,"t":"我们现在所知道的有限，先知所讲的也有限，","notes":[]},{"n":10,"t":"等那完全的来到，这有限的必归于无有了。","notes":[]},{"n":11,"t":"我作孩子的时候，话语像孩子，心思像孩子，意念像孩子，既成了人，就把孩子的事丢弃了。","notes":[]},{"n":12,"t":"我们如今仿佛对着镜子观看，模糊不清，到那时就要面对面了。我如今所知道的有限，到那时就全知道，如同主知道我一样。","notes":["原文是如同猜谜"]},{"n":13,"t":"如今常存的有信，有望，有爱这三样，其中最大的是爱。","notes":[]}]},"14":{"heading":"说方言和作先知讲道","verses":[{"n":1,"t":"你们要追求爱，也要切慕属灵的恩赐，其中更要羡慕的，是作先知讲道。","notes":["原文作：是说预言；下同"]},{"n":2,"t":"那说方言的，原不是对人说，乃是对神说，因为没有人听出来。然而，他在心灵里却是讲说各样的奥秘。","notes":[]},{"n":3,"t":"但作先知讲道的，是对人说，要造就、安慰、劝勉人。","notes":[]},{"n":4,"t":"说方言的，是造就自己；作先知讲道的，乃是造就教会。","notes":[]},{"n":5,"t":"我愿意你们都说方言，更愿意你们作先知讲道；因为说方言的，若不翻出来，使教会被造就，那作先知讲道的，就比他强了。","notes":[]},{"n":6,"t":"弟兄们，我到你们那里去，若只说方言，不用启示，或知识，或预言，或教训，给你们讲解，我与你们有什么益处呢？","notes":[]},{"n":7,"t":"就是那有声无气的物，或箫，或琴，若发出来的声音没有分别，怎能知道所吹所弹的是什么呢？","notes":[]},{"n":8,"t":"若吹无定的号声，谁能预备打仗呢？","notes":[]},{"n":9,"t":"你们也是如此。舌头若不说容易明白的话，怎能知道所说的是什么呢？这就是向空说话了。","notes":[]},{"n":10,"t":"世上的声音，或者甚多，却没有一样是无意思的。","notes":[]},{"n":11,"t":"我若不明白那声音的意思，这说话的人必以我为化外之人，我也以他为化外之人。","notes":[]},{"n":12,"t":"你们也是如此，既是切慕属灵的恩赐，就当求多得造就教会的恩赐。","notes":[]},{"n":13,"t":"所以那说方言的，就当求着能翻出来。","notes":[]},{"n":14,"t":"我若用方言祷告，是我的灵祷告，但我的悟性没有果效。","notes":[]},{"n":15,"t":"这却怎么样呢？我要用灵祷告，也要用悟性祷告；我要用灵歌唱，也要用悟性歌唱。","notes":[]},{"n":16,"t":"不然，你用灵祝谢，那在座不通方言的人，既然不明白你的话，怎能在你感谢的时候说「阿们」呢？","notes":[]},{"n":17,"t":"你感谢的固然是好，无奈不能造就别人。","notes":[]},{"n":18,"t":"我感谢神，我说方言比你们众人还多。","notes":[]},{"n":19,"t":"但在教会中，宁可用悟性说五句教导人的话，强如说万句方言。","notes":[]},{"n":20,"t":"弟兄们，在心志上不要作小孩子。然而，在恶事上要作婴孩，在心志上总要作大人。","notes":[]},{"n":21,"t":"律法上记着：主说：我要用外邦人的舌头和外邦人的嘴唇向这百姓说话；虽然如此，他们还是不听从我。","notes":[]},{"n":22,"t":"这样看来，说方言不是为信的人作证据，乃是为不信的人；作先知讲道不是为不信的人作证据，乃是为信的人。","notes":[]},{"n":23,"t":"所以，全教会聚在一处的时候，若都说方言，偶然有不通方言的，或是不信的人进来，岂不说你们癫狂了吗？","notes":[]},{"n":24,"t":"若都作先知讲道，偶然有不信的，或是不通方言的人进来，就被众人劝醒，被众人审明，","notes":[]},{"n":25,"t":"他心里的隐情显露出来，就必将脸伏地，敬拜神，说：「神真是在你们中间了。」","notes":[]},{"n":26,"t":"弟兄们，这却怎么样呢？你们聚会的时候，各人或有诗歌，或有教训，或有启示，或有方言，或有翻出来的话，凡事都当造就人。","notes":[],"heads":["凡事都要按次序行"]},{"n":27,"t":"若有说方言的，只好两个人，至多三个人，且要轮流着说，也要一个人翻出来。","notes":[]},{"n":28,"t":"若没有人翻，就当在会中闭口，只对自己和神说就是了。","notes":[]},{"n":29,"t":"至于作先知讲道的，只好两个人或是三个人，其余的就当慎思明辨。","notes":[]},{"n":30,"t":"若旁边坐着的得了启示，那先说话的就当闭口不言。","notes":[]},{"n":31,"t":"因为你们都可以一个一个地作先知讲道，叫众人学道理，叫众人得劝勉。","notes":[]},{"n":32,"t":"先知的灵原是顺服先知的；","notes":[]},{"n":33,"t":"因为神不是叫人混乱，乃是叫人安静。","notes":[]},{"n":34,"t":"妇女在会中要闭口不言，像在圣徒的众教会一样，因为不准她们说话。她们总要顺服，正如律法所说的。","notes":[]},{"n":35,"t":"她们若要学什么，可以在家里问自己的丈夫，因为妇女在会中说话原是可耻的。","notes":[]},{"n":36,"t":"神的道理岂是从你们出来吗？岂是单临到你们吗？","notes":[]},{"n":37,"t":"若有人以为自己是先知，或是属灵的，就该知道，我所写给你们的是主的命令。","notes":[]},{"n":38,"t":"若有不知道的，就由他不知道吧！","notes":[]},{"n":39,"t":"所以我弟兄们，你们要切慕作先知讲道，也不要禁止说方言。","notes":[]},{"n":40,"t":"凡事都要规规矩矩地按着次序行。","notes":[]}]},"15":{"heading":"基督的复活","verses":[{"n":1,"t":"弟兄们，我如今把先前所传给你们的福音告诉你们知道；这福音你们也领受了，又靠着站立得住，","notes":[]},{"n":2,"t":"并且你们若不是徒然相信，能以持守我所传给你们的，就必因这福音得救。","notes":[]},{"n":3,"t":"我当日所领受又传给你们的：第一，就是基督照圣经所说，为我们的罪死了，","notes":[]},{"n":4,"t":"而且埋葬了；又照圣经所说，第三天复活了，","notes":[]},{"n":5,"t":"并且显给矶法看，然后显给十二使徒看；","notes":[]},{"n":6,"t":"后来一时显给五百多弟兄看，其中一大半到如今还在，却也有已经睡了的。","notes":[]},{"n":7,"t":"以后显给雅各看，再显给众使徒看，","notes":[]},{"n":8,"t":"末了也显给我看；我如同未到产期而生的人一般。","notes":[]},{"n":9,"t":"我原是使徒中最小的，不配称为使徒，因为我从前逼迫神的教会。","notes":[]},{"n":10,"t":"然而，我今日成了何等人，是蒙神的恩才成的，并且他所赐我的恩不是徒然的。我比众使徒格外劳苦；这原不是我，乃是神的恩与我同在。","notes":[]},{"n":11,"t":"不拘是我，是众使徒，我们如此传，你们也如此信了。","notes":[]},{"n":12,"t":"既传基督是从死里复活了，怎么在你们中间有人说没有死人复活的事呢？","notes":[],"heads":["死人的复活"]},{"n":13,"t":"若没有死人复活的事，基督也就没有复活了。","notes":[]},{"n":14,"t":"若基督没有复活，我们所传的便是枉然，你们所信的也是枉然；","notes":[]},{"n":15,"t":"并且明显我们是为神妄作见证的，因我们见证神是叫基督复活了。若死人真不复活，神也就没有叫基督复活了。","notes":[]},{"n":16,"t":"因为死人若不复活，基督也就没有复活了。","notes":[]},{"n":17,"t":"基督若没有复活，你们的信便是徒然，你们仍在罪里。","notes":[]},{"n":18,"t":"就是在基督里睡了的人也灭亡了。","notes":[]},{"n":19,"t":"我们若靠基督只在今生有指望，就算比众人更可怜。","notes":[]},{"n":20,"t":"但基督已经从死里复活，成为睡了之人初熟的果子。","notes":[]},{"n":21,"t":"死既是因一人而来，死人复活也是因一人而来。","notes":[]},{"n":22,"t":"在亚当里众人都死了；照样，在基督里众人也都要复活。","notes":[]},{"n":23,"t":"但各人是按着自己的次序复活：初熟的果子是基督；以后，在他来的时候，是那些属基督的。","notes":[]},{"n":24,"t":"再后，末期到了，那时基督既将一切执政的、掌权的、有能的都毁灭了，就把国交与父神。","notes":[]},{"n":25,"t":"因为基督必要作王，等神把一切仇敌都放在他的脚下。","notes":[]},{"n":26,"t":"尽末了所毁灭的仇敌就是死。","notes":[]},{"n":27,"t":"因为经上说：「神叫万物都服在他的脚下。」既说万物都服了他，明显那叫万物服他的，不在其内了。","notes":[]},{"n":28,"t":"万物既服了他，那时子也要自己服那叫万物服他的，叫神在万物之上，为万物之主。","notes":[]},{"n":29,"t":"不然，那些为死人受洗的，将来怎样呢？若死人总不复活，因何为他们受洗呢？","notes":[]},{"n":30,"t":"我们又因何时刻冒险呢？","notes":[]},{"n":31,"t":"弟兄们，我在我主基督耶稣里，指着你们所夸的口极力地说，我是天天冒死。","notes":[]},{"n":32,"t":"我若当日像寻常人，在以弗所同野兽战斗，那于我有什么益处呢？若死人不复活，我们就吃吃喝喝吧！因为明天要死了。","notes":[]},{"n":33,"t":"你们不要自欺；滥交是败坏善行。","notes":[]},{"n":34,"t":"你们要醒悟为善，不要犯罪，因为有人不认识神。我说这话是要叫你们羞愧。","notes":[]},{"n":35,"t":"或有人问：「死人怎样复活，带着什么身体来呢？」","notes":[],"heads":["复活的身体"]},{"n":36,"t":"无知的人哪，你所种的，若不死就不能生。","notes":[]},{"n":37,"t":"并且你所种的不是那将来的形体，不过是子粒，即如麦子，或是别样的谷。","notes":[]},{"n":38,"t":"但神随自己的意思给他一个形体，并叫各等子粒各有自己的形体。","notes":[]},{"n":39,"t":"凡肉体各有不同：人是一样，兽又是一样，鸟又是一样，鱼又是一样。","notes":[]},{"n":40,"t":"有天上的形体，也有地上的形体；但天上形体的荣光是一样，地上形体的荣光又是一样。","notes":[]},{"n":41,"t":"日有日的荣光，月有月的荣光，星有星的荣光；这星和那星的荣光也有分别。","notes":[]},{"n":42,"t":"死人复活也是这样：所种的是必朽坏的，复活的是不朽坏的；","notes":[]},{"n":43,"t":"所种的是羞辱的，复活的是荣耀的；所种的是软弱的，复活的是强壮的；","notes":[]},{"n":44,"t":"所种的是血气的身体，复活的是灵性的身体。若有血气的身体，也必有灵性的身体。","notes":[]},{"n":45,"t":"经上也是这样记着说：「首先的人亚当成了有灵的活人」；末后的亚当成了叫人活的灵。","notes":["灵：或译血气"]},{"n":46,"t":"但属灵的不在先，属血气的在先，以后才有属灵的。","notes":[]},{"n":47,"t":"头一个人是出于地，乃属土；第二个人是出于天。","notes":[]},{"n":48,"t":"那属土的怎样，凡属土的也就怎样；属天的怎样，凡属天的也就怎样。","notes":[]},{"n":49,"t":"我们既有属土的形状，将来也必有属天的形状。","notes":[]},{"n":50,"t":"弟兄们，我告诉你们说，血肉之体不能承受神的国，必朽坏的不能承受不朽坏的。","notes":[]},{"n":51,"t":"我如今把一件奥秘的事告诉你们：我们不是都要睡觉，乃是都要改变，","notes":[]},{"n":52,"t":"就在一霎时，眨眼之间，号筒末次吹响的时候。因号筒要响，死人要复活成为不朽坏的，我们也要改变。","notes":[]},{"n":53,"t":"这必朽坏的总要变成不朽坏的，这必死的总要变成不死的。","notes":["变成：原文是穿；下同"]},{"n":54,"t":"这必朽坏的既变成不朽坏的，这必死的既变成不死的，那时经上所记「死被得胜吞灭」的话就应验了。","notes":[]},{"n":55,"t":"死啊！你得胜的权势在哪里？死啊！你的毒钩在哪里？","notes":[]},{"n":56,"t":"死的毒钩就是罪，罪的权势就是律法。","notes":[]},{"n":57,"t":"感谢神，使我们借着我们的主耶稣基督得胜。","notes":[]},{"n":58,"t":"所以，我亲爱的弟兄们，你们务要坚固，不可摇动，常常竭力多做主工；因为知道，你们的劳苦在主里面不是徒然的。","notes":[]}]},"16":{"heading":"捐助圣徒","verses":[{"n":1,"t":"论到为圣徒捐钱，我从前怎样吩咐加拉太的众教会，你们也当怎样行。","notes":[]},{"n":2,"t":"每逢七日的第一日，各人要照自己的进项抽出来留着，免得我来的时候现凑。","notes":[]},{"n":3,"t":"及至我来到了，你们写信举荐谁，我就打发他们，把你们的捐资送到耶路撒冷去。","notes":[]},{"n":4,"t":"若我也该去，他们可以和我同去。","notes":[]},{"n":5,"t":"我要从马其顿经过；既经过了，就要到你们那里去，","notes":[],"heads":["行程的计划"]},{"n":6,"t":"或者和你们同住几时，或者也过冬。无论我往哪里去，你们就可以给我送行。","notes":[]},{"n":7,"t":"我如今不愿意路过见你们；主若许我，我就指望和你们同住几时。","notes":[]},{"n":8,"t":"但我要仍旧住在以弗所，直等到五旬节；","notes":[]},{"n":9,"t":"因为有宽大又有功效的门为我开了，并且反对的人也多。","notes":[]},{"n":10,"t":"若是提摩太来到，你们要留心，叫他在你们那里无所惧怕；因为他劳力做主的工，像我一样。","notes":[]},{"n":11,"t":"所以，无论谁都不可藐视他，只要送他平安前行，叫他到我这里来，因我指望他和弟兄们同来。","notes":[]},{"n":12,"t":"至于兄弟亚波罗，我再三地劝他同弟兄们到你们那里去；但这时他决不愿意去，几时有了机会他必去。","notes":[]},{"n":13,"t":"你们务要警醒，在真道上站立得稳，要作大丈夫，要刚强。","notes":[],"heads":["请求和问安"]},{"n":14,"t":"凡你们所做的都要凭爱心而做。","notes":[]},{"n":15,"t":"弟兄们，你们晓得司提反一家，是亚该亚初结的果子，并且他们专以服事圣徒为念。","notes":[]},{"n":16,"t":"我劝你们顺服这样的人，并一切同工同劳的人。","notes":[]},{"n":17,"t":"司提反和福徒拿都，并亚该古到这里来，我很喜欢；因为你们待我有不及之处，他们补上了。","notes":[]},{"n":18,"t":"他们叫我和你们心里都快活。这样的人，你们务要敬重。","notes":[]},{"n":19,"t":"亚细亚的众教会问你们安。亚居拉和百基拉并在他们家里的教会，因主多多地问你们安。","notes":[]},{"n":20,"t":"众弟兄都问你们安。你们要亲嘴问安，彼此务要圣洁。","notes":[]},{"n":21,"t":"我—保罗亲笔问安。","notes":[]},{"n":22,"t":"若有人不爱主，这人可诅可咒。主必要来！","notes":[]},{"n":23,"t":"愿主耶稣基督的恩常与你们众人同在！","notes":[]},{"n":24,"t":"我在基督耶稣里的爱与你们众人同在。阿们！","notes":[]}]}},"2CO":{"1":{"heading":"问候","verses":[{"n":1,"t":"奉神旨意作基督耶稣使徒的保罗和兄弟提摩太，写信给在哥林多神的教会，并亚该亚遍处的众圣徒。","notes":[]},{"n":2,"t":"愿恩惠、平安从神我们的父和主耶稣基督归与你们！","notes":[]},{"n":3,"t":"愿颂赞归与我们的主耶稣基督的父神，就是发慈悲的父，赐各样安慰的神。","notes":[],"heads":["保罗受患难后的感恩"]},{"n":4,"t":"我们在一切患难中，他就安慰我们，叫我们能用神所赐的安慰去安慰那遭各样患难的人。","notes":[]},{"n":5,"t":"我们既多受基督的苦楚，就靠基督多得安慰。","notes":[]},{"n":6,"t":"我们受患难呢，是为叫你们得安慰，得拯救；我们得安慰呢，也是为叫你们得安慰；这安慰能叫你们忍受我们所受的那样苦楚。","notes":[]},{"n":7,"t":"我们为你们所存的盼望是确定的，因为知道你们既是同受苦楚，也必同得安慰。","notes":[]},{"n":8,"t":"弟兄们，我们不要你们不晓得，我们从前在亚细亚遭遇苦难，被压太重，力不能胜，甚至连活命的指望都绝了；","notes":[]},{"n":9,"t":"自己心里也断定是必死的，叫我们不靠自己，只靠叫死人复活的神。","notes":[]},{"n":10,"t":"他曾救我们脱离那极大的死亡，现在仍要救我们，并且我们指望他将来还要救我们。","notes":[]},{"n":11,"t":"你们以祈祷帮助我们，好叫许多人为我们谢恩，就是为我们因许多人所得的恩。","notes":[]},{"n":12,"t":"我们所夸的是自己的良心，见证我们凭着神的圣洁和诚实；在世为人不靠人的聪明，乃靠神的恩惠，向你们更是这样。","notes":[],"heads":["保罗延期访问哥林多"]},{"n":13,"t":"我们现在写给你们的话，并不外乎你们所念的、所认识的，我也盼望你们到底还是要认识；","notes":[]},{"n":14,"t":"正如你们已经有几分认识我们，以我们夸口，好像我们在我们主耶稣的日子以你们夸口一样。","notes":[]},{"n":15,"t":"我既然这样深信，就早有意到你们那里去，叫你们再得益处；","notes":[]},{"n":16,"t":"也要从你们那里经过，往马其顿去，再从马其顿回到你们那里，叫你们给我送行往犹太去。","notes":[]},{"n":17,"t":"我有此意，岂是反复不定吗？我所起的意，岂是从情欲起的，叫我忽是忽非吗？","notes":[]},{"n":18,"t":"我指着信实的神说，我们向你们所传的道，并没有是而又非的。","notes":[]},{"n":19,"t":"因为我和西拉并提摩太，在你们中间所传神的儿子耶稣基督，总没有是而又非的，在他只有一是。","notes":[]},{"n":20,"t":"神的应许，不论有多少，在基督都是是的。所以借着他也都是实在的，叫神因我们得荣耀。","notes":["实在：原文是阿们"]},{"n":21,"t":"那在基督里坚固我们和你们，并且膏我们的就是神。","notes":[]},{"n":22,"t":"他又用印印了我们，并赐圣灵在我们心里作凭据。","notes":["原文是质"]},{"n":23,"t":"我呼吁神给我的心作见证，我没有往哥林多去是为要宽容你们。","notes":[]},{"n":24,"t":"我们并不是辖管你们的信心，乃是帮助你们的快乐，因为你们凭信才站立得住。","notes":[]}]},"2":{"heading":"赦免犯过失的人","verses":[{"n":1,"t":"我自己定了主意再到你们那里去，必须大家没有忧愁。","notes":[]},{"n":2,"t":"倘若我叫你们忧愁，除了我叫那忧愁的人以外，谁能叫我快乐呢？","notes":[]},{"n":3,"t":"我曾把这事写给你们，恐怕我到的时候，应该叫我快乐的那些人，反倒叫我忧愁。我也深信，你们众人都以我的快乐为自己的快乐。","notes":[]},{"n":4,"t":"我先前心里难过痛苦，多多地流泪，写信给你们，不是叫你们忧愁，乃是叫你们知道我格外地疼爱你们。","notes":[]},{"n":5,"t":"若有叫人忧愁的，他不但叫我忧愁，也是叫你们众人有几分忧愁。我说几分，恐怕说得太重。","notes":[]},{"n":6,"t":"这样的人受了众人的责罚也就够了，","notes":[]},{"n":7,"t":"倒不如赦免他，安慰他，免得他忧愁太过，甚至沉沦了。","notes":[]},{"n":8,"t":"所以我劝你们，要向他显出坚定不移的爱心来。","notes":[]},{"n":9,"t":"为此我先前也写信给你们，要试验你们，看你们凡事顺从不顺从。","notes":[]},{"n":10,"t":"你们赦免谁，我也赦免谁。我若有所赦免的，是在基督面前为你们赦免的，","notes":[]},{"n":11,"t":"免得撒但趁着机会胜过我们，因我们并非不晓得他的诡计。","notes":[]},{"n":12,"t":"我从前为基督的福音到了特罗亚，主也给我开了门。","notes":[],"heads":["保罗的忧愁和安慰"]},{"n":13,"t":"那时，因为没有遇见兄弟提多，我心里不安，便辞别那里的人往马其顿去了。","notes":[]},{"n":14,"t":"感谢神！常率领我们在基督里夸胜，并借着我们在各处显扬那因认识基督而有的香气。","notes":[]},{"n":15,"t":"因为我们在神面前，无论在得救的人身上或灭亡的人身上，都有基督馨香之气。","notes":[]},{"n":16,"t":"在这等人，就作了死的香气叫他死；在那等人，就作了活的香气叫他活。这事谁能当得起呢？","notes":[]},{"n":17,"t":"我们不像那许多人，为利混乱神的道；乃是由于诚实，由于神，在神面前凭着基督讲道。","notes":[]}]},"3":{"heading":"新约的执事","verses":[{"n":1,"t":"我们岂是又举荐自己吗？岂像别人用人的荐信给你们或用你们的荐信给人吗？","notes":[]},{"n":2,"t":"你们就是我们的荐信，写在我们的心里，被众人所知道所念诵的。","notes":[]},{"n":3,"t":"你们明显是基督的信，借着我们修成的。不是用墨写的，乃是用永生神的灵写的；不是写在石版上，乃是写在心版上。","notes":[]},{"n":4,"t":"我们因基督，所以在神面前才有这样的信心。","notes":[]},{"n":5,"t":"并不是我们凭自己能承担什么事；我们所能承担的，乃是出于神。","notes":[]},{"n":6,"t":"他叫我们能承当这新约的执事，不是凭着字句，乃是凭着精意；因为那字句是叫人死，精意是叫人活。","notes":["或译：圣灵"]},{"n":7,"t":"那用字刻在石头上属死的职事尚且有荣光，甚至以色列人因摩西面上的荣光，不能定睛看他的脸；这荣光原是渐渐退去的，","notes":[]},{"n":8,"t":"何况那属灵的职事岂不更有荣光吗？","notes":[]},{"n":9,"t":"若是定罪的职事有荣光，那称义的职事荣光就越发大了。","notes":[]},{"n":10,"t":"那从前有荣光的，因这极大的荣光就算不得有荣光了；","notes":[]},{"n":11,"t":"若那废掉的有荣光，这长存的就更有荣光了。","notes":[]},{"n":12,"t":"我们既有这样的盼望，就大胆讲说，","notes":[]},{"n":13,"t":"不像摩西将帕子蒙在脸上，叫以色列人不能定睛看到那将废者的结局。","notes":[]},{"n":14,"t":"但他们的心地刚硬，直到今日诵读旧约的时候，这帕子还没有揭去。这帕子在基督里已经废去了。","notes":[]},{"n":15,"t":"然而直到今日，每逢诵读摩西书的时候，帕子还在他们心上。","notes":[]},{"n":16,"t":"但他们的心几时归向主，帕子就几时除去了。","notes":[]},{"n":17,"t":"主就是那灵；主的灵在哪里，那里就得以自由。","notes":[]},{"n":18,"t":"我们众人既然敞着脸得以看见主的荣光，好像从镜子里返照，就变成主的形状，荣上加荣，如同从主的灵变成的。","notes":[]}]},"4":{"heading":"在瓦器里的宝贝","verses":[{"n":1,"t":"我们既然蒙怜悯，受了这职分，就不丧胆，","notes":[]},{"n":2,"t":"乃将那些暗昧可耻的事弃绝了；不行诡诈，不谬讲神的道理，只将真理表明出来，好在神面前把自己荐与各人的良心。","notes":[]},{"n":3,"t":"如果我们的福音蒙蔽，就是蒙蔽在灭亡的人身上。","notes":[]},{"n":4,"t":"此等不信之人被这世界的神弄瞎了心眼，不叫基督荣耀福音的光照着他们。基督本是神的像。","notes":[]},{"n":5,"t":"我们原不是传自己，乃是传基督耶稣为主，并且自己因耶稣作你们的仆人。","notes":[]},{"n":6,"t":"那吩咐光从黑暗里照出来的神，已经照在我们心里，叫我们得知神荣耀的光显在耶稣基督的面上。","notes":[]},{"n":7,"t":"我们有这宝贝放在瓦器里，要显明这莫大的能力是出于神，不是出于我们。","notes":[]},{"n":8,"t":"我们四面受敌，却不被困住；心里作难，却不至失望；","notes":[]},{"n":9,"t":"遭逼迫，却不被丢弃；打倒了，却不至死亡。","notes":[]},{"n":10,"t":"身上常带着耶稣的死，使耶稣的生也显明在我们身上。","notes":[]},{"n":11,"t":"因为我们这活着的人是常为耶稣被交于死地，使耶稣的生在我们这必死的身上显明出来。","notes":[]},{"n":12,"t":"这样看来，死是在我们身上发动，生却在你们身上发动。","notes":[]},{"n":13,"t":"但我们既有信心，正如经上记着说：「我因信，所以如此说话。」我们也信，所以也说话。","notes":[]},{"n":14,"t":"自己知道那叫主耶稣复活的，也必叫我们与耶稣一同复活，并且叫我们与你们一同站在他面前。","notes":[]},{"n":15,"t":"凡事都是为你们，好叫恩惠因人多越发加增，感谢格外显多，以致荣耀归与神。","notes":[]},{"n":16,"t":"所以，我们不丧胆。外体虽然毁坏，内心却一天新似一天。","notes":[],"heads":["靠信心生活"]},{"n":17,"t":"我们这至暂至轻的苦楚，要为我们成就极重无比、永远的荣耀。","notes":[]},{"n":18,"t":"原来我们不是顾念所见的，乃是顾念所不见的；因为所见的是暂时的，所不见的是永远的。","notes":[]}]},"5":{"heading":"劝人与神和好的职分","verses":[{"n":1,"t":"我们原知道，我们这地上的帐棚若拆毁了，必得神所造，不是人手所造，在天上永存的房屋。","notes":[]},{"n":2,"t":"我们在这帐棚里叹息，深想得那从天上来的房屋，好像穿上衣服；","notes":[]},{"n":3,"t":"倘若穿上，被遇见的时候就不至于赤身了。","notes":[]},{"n":4,"t":"我们在这帐棚里叹息劳苦，并非愿意脱下这个，乃是愿意穿上那个，好叫这必死的被生命吞灭了。","notes":[]},{"n":5,"t":"为此，培植我们的就是神，他又赐给我们圣灵作凭据。","notes":["原文是质"]},{"n":6,"t":"所以，我们时常坦然无惧，并且晓得我们住在身内，便与主相离。","notes":[]},{"n":7,"t":"因我们行事为人是凭着信心，不是凭着眼见。","notes":[]},{"n":8,"t":"我们坦然无惧，是更愿意离开身体与主同住。","notes":[]},{"n":9,"t":"所以，无论是住在身内，离开身外，我们立了志向，要得主的喜悦。","notes":[]},{"n":10,"t":"因为我们众人必要在基督台前显露出来，叫各人按着本身所行的，或善或恶受报。","notes":[]},{"n":11,"t":"我们既知道主是可畏的，所以劝人。但我们在神面前是显明的，盼望在你们的良心里也是显明的。","notes":[]},{"n":12,"t":"我们不是向你们再举荐自己，乃是叫你们因我们有可夸之处，好对那凭外貌不凭内心夸口的人，有言可答。","notes":[]},{"n":13,"t":"我们若果颠狂，是为神；若果谨守，是为你们。","notes":[]},{"n":14,"t":"原来基督的爱激励我们；因我们想，一人既替众人死，众人就都死了；","notes":[]},{"n":15,"t":"并且他替众人死，是叫那些活着的人不再为自己活，乃为替他们死而复活的主活。","notes":[]},{"n":16,"t":"所以，我们从今以后，不凭着外貌认人了。虽然凭着外貌认过基督，如今却不再这样认他了。","notes":["原文是肉体；本节同"]},{"n":17,"t":"若有人在基督里，他就是新造的人，旧事已过，都变成新的了。","notes":[]},{"n":18,"t":"一切都是出于神；他借着基督使我们与他和好，又将劝人与他和好的职分赐给我们。","notes":[]},{"n":19,"t":"这就是神在基督里，叫世人与自己和好，不将他们的过犯归到他们身上，并且将这和好的道理托付了我们。","notes":[]},{"n":20,"t":"所以，我们作基督的使者，就好像神借我们劝你们一般。我们替基督求你们与神和好。","notes":[]},{"n":21,"t":"神使那无罪的，替我们成为罪，好叫我们在他里面成为神的义。","notes":["无罪：原文是不知罪"]}]},"6":{"heading":"永生神的殿","verses":[{"n":1,"t":"我们与神同工的，也劝你们不可徒受他的恩典。","notes":[]},{"n":2,"t":"因为他说：「在悦纳的时候，我应允了你；在拯救的日子，我搭救了你。」看哪，现在正是悦纳的时候！现在正是拯救的日子；","notes":[]},{"n":3,"t":"我们凡事都不叫人有妨碍，免得这职分被人毁谤；","notes":[]},{"n":4,"t":"反倒在各样的事上表明自己是神的用人，就如在许多的忍耐、患难、穷乏、困苦、","notes":[]},{"n":5,"t":"鞭打、监禁、扰乱、勤劳、警醒、不食、","notes":[]},{"n":6,"t":"廉洁、知识、恒忍、恩慈、圣灵的感化、无伪的爱心、","notes":[]},{"n":7,"t":"真实的道理、神的大能；仁义的兵器在左在右；","notes":[]},{"n":8,"t":"荣耀、羞辱，恶名、美名；似乎是诱惑人的，却是诚实的；","notes":[]},{"n":9,"t":"似乎不为人所知，却是人所共知的；似乎要死，却是活着的；似乎受责罚，却是不至丧命的；","notes":[]},{"n":10,"t":"似乎忧愁，却是常常快乐的；似乎贫穷，却是叫许多人富足的；似乎一无所有，却是样样都有的。","notes":[]},{"n":11,"t":"哥林多人哪，我们向你们，口是张开的，心是宽宏的。","notes":[]},{"n":12,"t":"你们狭窄，原不在乎我们，是在乎自己的心肠狭窄。","notes":[]},{"n":13,"t":"你们也要照样用宽宏的心报答我。我这话正像对自己的孩子说的。","notes":[]},{"n":14,"t":"你们和不信的原不相配，不要同负一轭。义和不义有什么相交呢？光明和黑暗有什么相通呢？","notes":[]},{"n":15,"t":"基督和彼列有什么相和呢？信主的和不信主的有什么相干呢？","notes":["彼列就是撒但的别名"]},{"n":16,"t":"神的殿和偶像有什么相同呢？因为我们是永生神的殿，就如神曾说：我要在他们中间居住，在他们中间来往；我要作他们的神；他们要作我的子民。","notes":[]},{"n":17,"t":"又说：你们务要从他们中间出来，与他们分别；不要沾不洁净的物，我就收纳你们。","notes":[]},{"n":18,"t":"我要作你们的父；你们要作我的儿女。这是全能的主说的。","notes":[]}]},"7":{"heading":"保罗为教会悔改而欢乐","verses":[{"n":1,"t":"亲爱的弟兄啊，我们既有这等应许，就当洁净自己，除去身体、灵魂一切的污秽，敬畏神，得以成圣。","notes":[]},{"n":2,"t":"你们要心地宽大收纳我们。我们未曾亏负谁，未曾败坏谁，未曾占谁的便宜。","notes":[]},{"n":3,"t":"我说这话，不是要定你们的罪。我已经说过，你们常在我们心里，情愿与你们同生同死。","notes":[]},{"n":4,"t":"我大大地放胆，向你们说话；我因你们多多夸口，满得安慰；我们在一切患难中分外的快乐。","notes":[]},{"n":5,"t":"我们从前就是到了马其顿的时候，身体也不得安宁，周围遭患难，外有争战，内有惧怕。","notes":[]},{"n":6,"t":"但那安慰丧气之人的神借着提多来安慰了我们；","notes":[]},{"n":7,"t":"不但借着他来，也借着他从你们所得的安慰，安慰了我们；因他把你们的想念、哀恸，和向我的热心，都告诉了我，叫我更加欢喜。","notes":[]},{"n":8,"t":"我先前写信叫你们忧愁，我后来虽然懊悔，如今却不懊悔；因我知道，那信叫你们忧愁不过是暂时的。","notes":[]},{"n":9,"t":"如今我欢喜，不是因你们忧愁，是因你们从忧愁中生出懊悔来。你们依着神的意思忧愁，凡事就不至于因我们受亏损了。","notes":[]},{"n":10,"t":"因为依着神的意思忧愁，就生出没有后悔的懊悔来，以致得救；但世俗的忧愁是叫人死。","notes":[]},{"n":11,"t":"你看，你们依着神的意思忧愁，从此就生出何等的殷勤、自诉、自恨、恐惧、想念、热心、责罚。在这一切事上，你们都表明自己是洁净的。","notes":["或译：自责"]},{"n":12,"t":"我虽然从前写信给你们，却不是为那亏负人的，也不是为那受人亏负的，乃要在神面前把你们顾念我们的热心表明出来。","notes":[]},{"n":13,"t":"故此，我们得了安慰。并且在安慰之中，因你们众人使提多心里畅快欢喜，我们就更加欢喜了。","notes":[]},{"n":14,"t":"我若对提多夸奖了你们什么，也觉得没有惭愧；因我对提多夸奖你们的话成了真的，正如我对你们所说的话也都是真的。","notes":[]},{"n":15,"t":"并且提多想起你们众人的顺服，是怎样恐惧战兢地接待他，他爱你们的心肠就越发热了。","notes":[]},{"n":16,"t":"我如今欢喜，能在凡事上为你们放心。","notes":[]}]},"8":{"heading":"慷慨的捐助","verses":[{"n":1,"t":"弟兄们，我把神赐给马其顿众教会的恩告诉你们，","notes":[]},{"n":2,"t":"就是他们在患难中受大试炼的时候，仍有满足的快乐，在极穷之间还格外显出他们乐捐的厚恩。","notes":[]},{"n":3,"t":"我可以证明，他们是按着力量，而且也过了力量，自己甘心乐意地捐助，","notes":[]},{"n":4,"t":"再三地求我们，准他们在这供给圣徒的恩情上有分；","notes":[]},{"n":5,"t":"并且他们所做的，不但照我们所想望的，更照神的旨意先把自己献给主，又归附了我们。","notes":[]},{"n":6,"t":"因此我劝提多，既然在你们中间开办这慈惠的事，就当办成了。","notes":[]},{"n":7,"t":"你们既然在信心、口才、知识、热心，和待我们的爱心上，都格外显出满足来，就当在这慈惠的事上也格外显出满足来。","notes":[]},{"n":8,"t":"我说这话，不是吩咐你们，乃是借着别人的热心试验你们爱心的实在。","notes":[]},{"n":9,"t":"你们知道我们主耶稣基督的恩典：他本来富足，却为你们成了贫穷，叫你们因他的贫穷，可以成为富足。","notes":[]},{"n":10,"t":"我在这事上把我的意见告诉你们，是与你们有益；因为你们下手办这事，而且起此心意，已经有一年了，","notes":[]},{"n":11,"t":"如今就当办成这事。既有愿做的心，也当照你们所有的去办成。","notes":[]},{"n":12,"t":"因为人若有愿做的心，必蒙悦纳，乃是照他所有的，并不是照他所无的。","notes":[]},{"n":13,"t":"我原不是要别人轻省，你们受累，","notes":[]},{"n":14,"t":"乃要均平，就是要你们的富余，现在可以补他们的不足，使他们的富余，将来也可以补你们的不足，这就均平了。","notes":[]},{"n":15,"t":"如经上所记：多收的也没有余；少收的也没有缺。","notes":[]},{"n":16,"t":"多谢神，感动提多的心，叫他待你们殷勤，像我一样。","notes":[],"heads":["提多和他的同工"]},{"n":17,"t":"他固然是听了我的劝，但自己更是热心，情愿往你们那里去。","notes":[]},{"n":18,"t":"我们还打发一位兄弟和他同去，这人在福音上得了众教会的称赞。","notes":[]},{"n":19,"t":"不但这样，他也被众教会挑选，和我们同行，把所托与我们的这捐资送到了，可以荣耀主，又表明我们乐意的心。","notes":[]},{"n":20,"t":"这就免得有人因我们收的捐银很多，就挑我们的不是。","notes":[]},{"n":21,"t":"我们留心行光明的事，不但在主面前，就在人面前也是这样。","notes":[]},{"n":22,"t":"我们又打发一位兄弟同去；这人的热心，我们在许多事上屡次试验过。现在他因为深信你们，就更加热心了。","notes":[]},{"n":23,"t":"论到提多，他是我的同伴，一同为你们劳碌的。论到那两位兄弟，他们是众教会的使者，是基督的荣耀。","notes":[]},{"n":24,"t":"所以，你们务要在众教会面前显明你们爱心的凭据，并我所夸奖你们的凭据。","notes":[]}]},"9":{"heading":"帮助圣徒的捐款","verses":[{"n":1,"t":"论到供给圣徒的事，我不必写信给你们；","notes":[]},{"n":2,"t":"因为我知道你们乐意的心，常对马其顿人夸奖你们，说亚该亚人预备好了，已经有一年了；并且你们的热心激动了许多人。","notes":[]},{"n":3,"t":"但我打发那几位弟兄去，要叫你们照我的话预备妥当，免得我们在这事上夸奖你们的话落了空。","notes":[]},{"n":4,"t":"万一有马其顿人与我同去，见你们没有预备，就叫我们所确信的，反成了羞愧；你们羞愧，更不用说了。","notes":[]},{"n":5,"t":"因此，我想不得不求那几位弟兄先到你们那里去，把从前所应许的捐资预备妥当，就显出你们所捐的是出于乐意，不是出于勉强。","notes":[]},{"n":6,"t":"「少种的少收，多种的多收」，这话是真的。","notes":[]},{"n":7,"t":"各人要随本心所酌定的，不要作难，不要勉强，因为捐得乐意的人是神所喜爱的。","notes":[]},{"n":8,"t":"神能将各样的恩惠多多地加给你们，使你们凡事常常充足，能多行各样善事。","notes":[]},{"n":9,"t":"如经上所记：他施舍钱财，周济贫穷；他的仁义存到永远。","notes":[]},{"n":10,"t":"那赐种给撒种的，赐粮给人吃的，必多多加给你们种地的种子，又增添你们仁义的果子；","notes":[]},{"n":11,"t":"叫你们凡事富足，可以多多施舍，就借着我们使感谢归于神。","notes":[]},{"n":12,"t":"因为办这供给的事，不但补圣徒的缺乏，而且叫许多人越发感谢神。","notes":[]},{"n":13,"t":"他们从这供给的事上得了凭据，知道你们承认基督顺服他的福音，多多地捐钱给他们和众人，便将荣耀归与神。","notes":[]},{"n":14,"t":"他们也因神极大的恩赐显在你们心里，就切切地想念你们，为你们祈祷。","notes":[]},{"n":15,"t":"感谢神，因他有说不尽的恩赐！","notes":[]}]},"10":{"heading":"保罗为他的工作辩护","verses":[{"n":1,"t":"我—保罗，就是与你们见面的时候是谦卑的，不在你们那里的时候向你们是勇敢的，如今亲自借着基督的温柔、和平劝你们。","notes":[]},{"n":2,"t":"有人以为我是凭着血气行事，我也以为必须用勇敢待这等人；求你们不要叫我在你们那里的时候，有这样的勇敢。","notes":[]},{"n":3,"t":"因为我们虽然在血气中行事，却不凭着血气争战。","notes":[]},{"n":4,"t":"我们争战的兵器本不是属血气的，乃是在神面前有能力，可以攻破坚固的营垒，","notes":[]},{"n":5,"t":"将各样的计谋，各样拦阻人认识神的那些自高之事，一概攻破了，又将人所有的心意夺回，使他都顺服基督。","notes":[]},{"n":6,"t":"并且我已经预备好了，等你们十分顺服的时候，要责罚那一切不顺服的人。","notes":[]},{"n":7,"t":"你们是看眼前的吗？倘若有人自信是属基督的，他要再想想，他如何属基督，我们也是如何属基督的。","notes":[]},{"n":8,"t":"主赐给我们权柄，是要造就你们，并不是要败坏你们；我就是为这权柄稍微夸口，也不至于惭愧。","notes":[]},{"n":9,"t":"我说这话，免得你们以为我写信是要威吓你们；","notes":[]},{"n":10,"t":"因为有人说：「他的信又沉重又厉害，及至见面，却是气貌不扬，言语粗俗的。」","notes":[]},{"n":11,"t":"这等人当想，我们不在那里的时候，信上的言语如何，见面的时候，行事也必如何。","notes":[]},{"n":12,"t":"因为我们不敢将自己和那自荐的人同列相比。他们用自己度量自己，用自己比较自己，乃是不通达的。","notes":[]},{"n":13,"t":"我们不愿意分外夸口，只要照神所量给我们的界限搆到你们那里。","notes":[]},{"n":14,"t":"我们并非过了自己的界限，好像搆不到你们那里；因为我们早到你们那里，传了基督的福音。","notes":[]},{"n":15,"t":"我们不仗着别人所劳碌的，分外夸口；但指望你们信心增长的时候，所量给我们的界限，就可以因着你们更加开展，","notes":[],"heads":["当指着主夸口"]},{"n":16,"t":"得以将福音传到你们以外的地方；并不是在别人界限之内，借着他现成的事夸口。","notes":[]},{"n":17,"t":"但夸口的，当指着主夸口。","notes":[]},{"n":18,"t":"因为蒙悦纳的，不是自己称许的，乃是主所称许的。","notes":[]}]},"11":{"heading":"保罗和假使徒","verses":[{"n":1,"t":"但愿你们宽容我这一点愚妄，其实你们原是宽容我的。","notes":[]},{"n":2,"t":"我为你们起的愤恨，原是神那样的愤恨。因为我曾把你们许配一个丈夫，要把你们如同贞洁的童女，献给基督。","notes":[]},{"n":3,"t":"我只怕你们的心或偏于邪，失去那向基督所存纯一清洁的心，就像蛇用诡诈诱惑了夏娃一样。","notes":[]},{"n":4,"t":"假如有人来另传一个耶稣，不是我们所传过的；或者你们另受一个灵，不是你们所受过的；或者另得一个福音，不是你们所得过的；你们容让他也就罢了。","notes":[]},{"n":5,"t":"但我想，我一点不在那些最大的使徒以下。","notes":[]},{"n":6,"t":"我的言语虽然粗俗，我的知识却不粗俗。这是我们在凡事上向你们众人显明出来的。","notes":[]},{"n":7,"t":"我因为白白传神的福音给你们，就自居卑微，叫你们高升，这算是我犯罪吗？","notes":[]},{"n":8,"t":"我亏负了别的教会，向他们取了工价来给你们效力。","notes":[]},{"n":9,"t":"我在你们那里缺乏的时候，并没有累着你们一个人；因我所缺乏的，那从马其顿来的弟兄们都补足了。我向来凡事谨守，后来也必谨守，总不至于累着你们。","notes":[]},{"n":10,"t":"既有基督的诚实在我里面，就无人能在亚该亚一带地方阻挡我这自夸。","notes":[]},{"n":11,"t":"为什么呢？是因我不爱你们吗？这有神知道。","notes":[]},{"n":12,"t":"我现在所做的，后来还要做，为要断绝那些寻机会人的机会，使他们在所夸的事上也不过与我们一样。","notes":[]},{"n":13,"t":"那等人是假使徒，行事诡诈，装作基督使徒的模样。","notes":[]},{"n":14,"t":"这也不足为怪，因为连撒但也装作光明的天使。","notes":[]},{"n":15,"t":"所以他的差役，若装作仁义的差役，也不算希奇。他们的结局必然照着他们的行为。","notes":[]},{"n":16,"t":"我再说，人不可把我看作愚妄的。纵然如此，也要把我当作愚妄人接纳，叫我可以略略自夸。","notes":[],"heads":["保罗作使徒所受的患难"]},{"n":17,"t":"我说的话不是奉主命说的，乃是像愚妄人放胆自夸；","notes":[]},{"n":18,"t":"既有好些人凭着血气自夸，我也要自夸了。","notes":[]},{"n":19,"t":"你们既是精明人，就能甘心忍耐愚妄人。","notes":[]},{"n":20,"t":"假若有人强你们作奴仆，或侵吞你们，或掳掠你们，或侮慢你们，或打你们的脸，你们都能忍耐他。","notes":[]},{"n":21,"t":"我说这话是羞辱自己，好像我们从前是软弱的。然而，人在何事上勇敢，（我说句愚妄话，）我也勇敢。","notes":[]},{"n":22,"t":"他们是希伯来人吗？我也是。他们是以色列人吗？我也是。他们是亚伯拉罕的后裔吗？我也是。","notes":[]},{"n":23,"t":"他们是基督的仆人吗？（我说句狂话，）我更是。我比他们多受劳苦，多下监牢，受鞭打是过重的，冒死是屡次有的。","notes":[]},{"n":24,"t":"被犹太人鞭打五次，每次四十减去一下；","notes":[]},{"n":25,"t":"被棍打了三次；被石头打了一次；遇着船坏三次，一昼一夜在深海里。","notes":[]},{"n":26,"t":"又屡次行远路，遭江河的危险、盗贼的危险、同族的危险、外邦人的危险、城里的危险、旷野的危险、海中的危险、假弟兄的危险。","notes":[]},{"n":27,"t":"受劳碌、受困苦，多次不得睡，又饥又渴，多次不得食，受寒冷，赤身露体。","notes":[]},{"n":28,"t":"除了这外面的事，还有为众教会挂心的事，天天压在我身上。","notes":[]},{"n":29,"t":"有谁软弱，我不软弱呢？有谁跌倒，我不焦急呢？","notes":[]},{"n":30,"t":"我若必须自夸，就夸那关乎我软弱的事便了。","notes":[]},{"n":31,"t":"那永远可称颂之主耶稣的父神知道我不说谎。","notes":[]},{"n":32,"t":"在大马士革的亚哩达王手下的提督把守大马士革城，要捉拿我，","notes":[]},{"n":33,"t":"我就从窗户中，在筐子里，从城墙上被人缒下去，脱离了他的手。","notes":[]}]},"12":{"heading":"异象和启示","verses":[{"n":1,"t":"我自夸固然无益，但我是不得已的。如今我要说到主的显现和启示。","notes":[]},{"n":2,"t":"我认得一个在基督里的人，他前十四年被提到第三层天上去；（或在身内，我不知道；或在身外，我也不知道；只有神知道。）","notes":[]},{"n":3,"t":"我认得这人；（或在身内，或在身外，我都不知道，只有神知道。）","notes":[]},{"n":4,"t":"他被提到乐园里，听见隐秘的言语，是人不可说的。","notes":[]},{"n":5,"t":"为这人，我要夸口；但是为我自己，除了我的软弱以外，我并不夸口。","notes":[]},{"n":6,"t":"我就是愿意夸口也不算狂，因为我必说实话；只是我禁止不说，恐怕有人把我看高了，过于他在我身上所看见所听见的。","notes":[]},{"n":7,"t":"又恐怕我因所得的启示甚大，就过于自高，所以有一根刺加在我肉体上，就是撒但的差役要攻击我，免得我过于自高。","notes":[]},{"n":8,"t":"为这事，我三次求过主，叫这刺离开我。","notes":[]},{"n":9,"t":"他对我说：「我的恩典够你用的，因为我的能力是在人的软弱上显得完全。」所以，我更喜欢夸自己的软弱，好叫基督的能力覆庇我。","notes":[]},{"n":10,"t":"我为基督的缘故，就以软弱、凌辱、急难、逼迫、困苦为可喜乐的；因我什么时候软弱，什么时候就刚强了。","notes":[]},{"n":11,"t":"我成了愚妄人，是被你们强逼的。我本该被你们称许才是。我虽算不了什么，却没有一件事在那些最大的使徒以下。","notes":[],"heads":["保罗关心哥林多教会"]},{"n":12,"t":"我在你们中间，用百般的忍耐，借着神迹、奇事、异能显出使徒的凭据来。","notes":[]},{"n":13,"t":"除了我不累着你们这一件事，你们还有什么事不及别的教会呢？这不公之处，求你们饶恕我吧。","notes":[]},{"n":14,"t":"如今，我打算第三次到你们那里去，也必不累着你们；因我所求的是你们，不是你们的财物。儿女不该为父母积财，父母该为儿女积财。","notes":[]},{"n":15,"t":"我也甘心乐意为你们的灵魂费财费力。难道我越发爱你们，就越发少得你们的爱吗？","notes":[]},{"n":16,"t":"罢了，我自己并没有累着你们，你们却有人说，我是诡诈，用心计牢笼你们。","notes":[]},{"n":17,"t":"我所差到你们那里去的人，我借着他们一个人占过你们的便宜吗？","notes":[]},{"n":18,"t":"我劝了提多到你们那里去，又差那位兄弟与他同去。提多占过你们的便宜吗？我们行事，不同是一个心灵吗？不同是一个脚踪吗？","notes":["或译：圣灵"]},{"n":19,"t":"你们到如今，还想我们是向你们分诉；我们本是在基督里当神面前说话。亲爱的弟兄啊，一切的事都是为造就你们。","notes":[]},{"n":20,"t":"我怕我再来的时候，见你们不合我所想望的，你们见我也不合你们所想望的；又怕有纷争、嫉妒、恼怒、结党、毁谤、谗言、狂傲、混乱的事。","notes":[]},{"n":21,"t":"且怕我来的时候，我的神叫我在你们面前惭愧，又因许多人从前犯罪，行污秽、奸淫、邪荡的事不肯悔改，我就忧愁。","notes":[]}]},"13":{"heading":"警告和问候","verses":[{"n":1,"t":"这是我第三次要到你们那里去。「凭两三个人的口作见证，句句都要定准。」","notes":[]},{"n":2,"t":"我从前说过，如今不在你们那里又说，正如我第二次见你们的时候所说的一样，就是对那犯了罪的和其余的人说：「我若再来，必不宽容。」","notes":[]},{"n":3,"t":"你们既然寻求基督在我里面说话的凭据，我必不宽容。因为，基督在你们身上不是软弱的，在你们里面是有大能的。","notes":[]},{"n":4,"t":"他因软弱被钉在十字架上，却因神的大能仍然活着。我们也是这样同他软弱，但因神向你们所显的大能，也必与他同活。","notes":[]},{"n":5,"t":"你们总要自己省察有信心没有，也要自己试验。岂不知你们若不是可弃绝的，就有耶稣基督在你们心里吗？","notes":[]},{"n":6,"t":"我却盼望你们晓得，我们不是可弃绝的人。","notes":[]},{"n":7,"t":"我们求神，叫你们一件恶事都不做；这不是要显明我们是蒙悦纳的，是要你们行事端正，任凭人看我们是被弃绝的吧！","notes":[]},{"n":8,"t":"我们凡事不能敌挡真理，只能扶助真理。","notes":[]},{"n":9,"t":"即便我们软弱，你们刚强，我们也欢喜；并且我们所求的，就是你们作完全人。","notes":[]},{"n":10,"t":"所以，我不在你们那里的时候，把这话写给你们，好叫我见你们的时候，不用照主所给我的权柄严厉地待你们。这权柄原是为造就人，并不是为败坏人。","notes":[]},{"n":11,"t":"还有末了的话：愿弟兄们都喜乐。要作完全人；要受安慰；要同心合意；要彼此和睦。如此，仁爱和平的神必常与你们同在。","notes":[]},{"n":12,"t":"你们亲嘴问安，彼此务要圣洁。","notes":[]},{"n":13,"t":"众圣徒都问你们安。","notes":[]},{"n":14,"t":"愿主耶稣基督的恩惠、神的慈爱、圣灵的感动常与你们众人同在！","notes":[]}]}},"GAL":{"1":{"heading":"问候","verses":[{"n":1,"t":"作使徒的保罗（不是由于人，也不是借着人，乃是借着耶稣基督，与叫他从死里复活的父神）","notes":[]},{"n":2,"t":"和一切与我同在的众弟兄，写信给加拉太的各教会。","notes":[]},{"n":3,"t":"愿恩惠、平安从父神与我们的主耶稣基督归与你们！","notes":[]},{"n":4,"t":"基督照我们父神的旨意，为我们的罪舍己，要救我们脱离这罪恶的世代。","notes":[]},{"n":5,"t":"但愿荣耀归于神，直到永永远远。阿们！","notes":[]},{"n":6,"t":"我希奇你们这么快离开那借着基督之恩召你们的，去从别的福音。","notes":[],"heads":["没有别的福音"]},{"n":7,"t":"那并不是福音，不过有些人搅扰你们，要把基督的福音更改了。","notes":[]},{"n":8,"t":"但无论是我们，是天上来的使者，若传福音给你们，与我们所传给你们的不同，他就应当被咒诅。","notes":[]},{"n":9,"t":"我们已经说了，现在又说，若有人传福音给你们，与你们所领受的不同，他就应当被咒诅。","notes":[]},{"n":10,"t":"我现在是要得人的心呢？还是要得神的心呢？我岂是讨人的喜欢吗？若仍旧讨人的喜欢，我就不是基督的仆人了。","notes":[]},{"n":11,"t":"弟兄们，我告诉你们，我素来所传的福音不是出于人的意思。","notes":[],"heads":["保罗怎样成为使徒"]},{"n":12,"t":"因为我不是从人领受的，也不是人教导我的，乃是从耶稣基督启示来的。","notes":[]},{"n":13,"t":"你们听见我从前在犹太教中所行的事，怎样极力逼迫残害神的教会。","notes":[]},{"n":14,"t":"我又在犹太教中，比我本国许多同岁的人更有长进，为我祖宗的遗传更加热心。","notes":[]},{"n":15,"t":"然而，那把我从母腹里分别出来、又施恩召我的神，","notes":[]},{"n":16,"t":"既然乐意将他儿子启示在我心里，叫我把他传在外邦人中，我就没有与属血气的人商量，","notes":[]},{"n":17,"t":"也没有上耶路撒冷去见那些比我先作使徒的，惟独往阿拉伯去，后又回到大马士革。","notes":[]},{"n":18,"t":"过了三年，才上耶路撒冷去见矶法，和他同住了十五天。","notes":[]},{"n":19,"t":"至于别的使徒，除了主的兄弟雅各，我都没有看见。","notes":[]},{"n":20,"t":"我写给你们的不是谎话，这是我在神面前说的。","notes":[]},{"n":21,"t":"以后我到了叙利亚和基利家境内。","notes":[]},{"n":22,"t":"那时，犹太信基督的各教会都没有见过我的面。","notes":[]},{"n":23,"t":"不过听说那从前逼迫我们的，现在传扬他原先所残害的真道。","notes":[]},{"n":24,"t":"他们就为我的缘故，归荣耀给神。","notes":[]}]},"2":{"heading":"保罗被其他的使徒接纳","verses":[{"n":1,"t":"过了十四年，我同巴拿巴又上耶路撒冷去，并带着提多同去。","notes":[]},{"n":2,"t":"我是奉启示上去的，把我在外邦人中所传的福音对弟兄们陈说；却是背地里对那有名望之人说的，惟恐我现在，或是从前，徒然奔跑。","notes":[]},{"n":3,"t":"但与我同去的提多，虽是希腊人，也没有勉强他受割礼；","notes":[]},{"n":4,"t":"因为有偷着引进来的假弟兄，私下窥探我们在基督耶稣里的自由，要叫我们作奴仆。","notes":[]},{"n":5,"t":"我们就是一刻的工夫也没有容让顺服他们，为要叫福音的真理仍存在你们中间。","notes":[]},{"n":6,"t":"至于那些有名望的，不论他是何等人，都与我无干。神不以外貌取人。那些有名望的，并没有加增我什么，","notes":[]},{"n":7,"t":"反倒看见了主托我传福音给那未受割礼的人，正如托彼得传福音给那受割礼的人。（","notes":[]},{"n":8,"t":"那感动彼得、叫他为受割礼之人作使徒的，也感动我，叫我为外邦人作使徒；）","notes":[]},{"n":9,"t":"又知道所赐给我的恩典，那称为教会柱石的雅各、矶法、约翰，就向我和巴拿巴用右手行相交之礼，叫我们往外邦人那里去，他们往受割礼的人那里去。","notes":[]},{"n":10,"t":"只是愿意我们记念穷人；这也是我本来热心去行的。","notes":[]},{"n":11,"t":"后来，矶法到了安提阿；因他有可责之处，我就当面抵挡他。","notes":[],"heads":["保罗在安提阿责备彼得"]},{"n":12,"t":"从雅各那里来的人未到以先，他和外邦人一同吃饭，及至他们来到，他因怕奉割礼的人，就退去与外邦人隔开了。","notes":[]},{"n":13,"t":"其余的犹太人也都随着他装假，甚至连巴拿巴也随伙装假。","notes":[]},{"n":14,"t":"但我一看见他们行的不正，与福音的真理不合，就在众人面前对矶法说：「你既是犹太人，若随外邦人行事，不随犹太人行事，怎么还勉强外邦人随犹太人呢？」","notes":[]},{"n":15,"t":"我们这生来的犹太人，不是外邦的罪人；","notes":[],"heads":["犹太人和外邦人都因信得救"]},{"n":16,"t":"既知道人称义不是因行律法，乃是因信耶稣基督，连我们也信了基督耶稣，使我们因信基督称义，不因行律法称义；因为凡有血气的，没有一人因行律法称义。","notes":[]},{"n":17,"t":"我们若求在基督里称义，却仍旧是罪人，难道基督是叫人犯罪的吗？断乎不是！","notes":[]},{"n":18,"t":"我素来所拆毁的，若重新建造，这就证明自己是犯罪的人。","notes":[]},{"n":19,"t":"我因律法，就向律法死了，叫我可以向神活着。","notes":[]},{"n":20,"t":"我已经与基督同钉十字架，现在活着的不再是我，乃是基督在我里面活着；并且我如今在肉身活着，是因信神的儿子而活；他是爱我，为我舍己。","notes":[]},{"n":21,"t":"我不废掉神的恩；义若是借着律法得的，基督就是徒然死了。","notes":[]}]},"3":{"heading":"律法和信心","verses":[{"n":1,"t":"无知的加拉太人哪，耶稣基督钉十字架，已经活画在你们眼前，谁又迷惑了你们呢？","notes":[]},{"n":2,"t":"我只要问你们这一件：你们受了圣灵，是因行律法呢？是因听信福音呢？","notes":[]},{"n":3,"t":"你们既靠圣灵入门，如今还靠肉身成全吗？你们是这样的无知吗？","notes":[]},{"n":4,"t":"你们受苦如此之多，都是徒然的吗？难道果真是徒然的吗？","notes":[]},{"n":5,"t":"那赐给你们圣灵，又在你们中间行异能的，是因你们行律法呢？是因你们听信福音呢？","notes":[]},{"n":6,"t":"正如「亚伯拉罕信神，这就算为他的义」。","notes":[]},{"n":7,"t":"所以，你们要知道：那以信为本的人，就是亚伯拉罕的子孙。","notes":[]},{"n":8,"t":"并且圣经既然预先看明，神要叫外邦人因信称义，就早已传福音给亚伯拉罕，说：「万国都必因你得福。」","notes":[]},{"n":9,"t":"可见那以信为本的人和有信心的亚伯拉罕一同得福。","notes":[]},{"n":10,"t":"凡以行律法为本的，都是被咒诅的；因为经上记着：「凡不常照律法书上所记一切之事去行的，就被咒诅。」","notes":[]},{"n":11,"t":"没有一个人靠着律法在神面前称义，这是明显的；因为经上说：「义人必因信得生。」","notes":[]},{"n":12,"t":"律法原不本乎信，只说：「行这些事的，就必因此活着。」","notes":[]},{"n":13,"t":"基督既为我们受了咒诅，就赎出我们脱离律法的咒诅；因为经上记着：「凡挂在木头上都是被咒诅的。」","notes":["原文是成"]},{"n":14,"t":"这便叫亚伯拉罕的福，因基督耶稣可以临到外邦人，使我们因信得着所应许的圣灵。","notes":[]},{"n":15,"t":"弟兄们，我且照着人的常话说：虽然是人的文约，若已经立定了，就没有能废弃或加增的。","notes":[],"heads":["律法和应许"]},{"n":16,"t":"所应许的原是向亚伯拉罕和他子孙说的。神并不是说「众子孙」，指着许多人，乃是说「你那一个子孙」，指着一个人，就是基督。","notes":[]},{"n":17,"t":"我是这么说，神预先所立的约，不能被那四百三十年以后的律法废掉，叫应许归于虚空。","notes":[]},{"n":18,"t":"因为承受产业，若本乎律法，就不本乎应许；但神是凭着应许把产业赐给亚伯拉罕。","notes":[]},{"n":19,"t":"这样说来，律法是为什么有的呢？原是为过犯添上的，等候那蒙应许的子孙来到，并且是借天使经中保之手设立的。","notes":[]},{"n":20,"t":"但中保本不是为一面作的；神却是一位。","notes":[]},{"n":21,"t":"这样，律法是与神的应许反对吗？断乎不是！若曾传一个能叫人得生的律法，义就诚然本乎律法了。","notes":[],"heads":["奴仆和儿子"]},{"n":22,"t":"但圣经把众人都圈在罪里，使所应许的福因信耶稣基督，归给那信的人。","notes":[]},{"n":23,"t":"但这因信得救的理还未来以先，我们被看守在律法之下，直圈到那将来的真道显明出来。","notes":[]},{"n":24,"t":"这样，律法是我们训蒙的师傅，引我们到基督那里，使我们因信称义。","notes":[]},{"n":25,"t":"但这因信得救的理既然来到，我们从此就不在师傅的手下了。","notes":[]},{"n":26,"t":"所以，你们因信基督耶稣都是神的儿子。","notes":[]},{"n":27,"t":"你们受洗归入基督的都是披戴基督了。","notes":[]},{"n":28,"t":"并不分犹太人、希腊人，自主的、为奴的，或男或女，因为你们在基督耶稣里都成为一了。","notes":[]},{"n":29,"t":"你们既属乎基督，就是亚伯拉罕的后裔，是照着应许承受产业的了。","notes":[]}]},"4":{"heading":"保罗关怀加拉太人","verses":[{"n":1,"t":"我说那承受产业的，虽然是全业的主人，但为孩童的时候却与奴仆毫无分别，","notes":[]},{"n":2,"t":"乃在师傅和管家的手下，直等他父亲预定的时候来到。","notes":[]},{"n":3,"t":"我们为孩童的时候，受管于世俗小学之下，也是如此。","notes":[]},{"n":4,"t":"及至时候满足，神就差遣他的儿子，为女子所生，且生在律法以下，","notes":[]},{"n":5,"t":"要把律法以下的人赎出来，叫我们得着儿子的名分。","notes":[]},{"n":6,"t":"你们既为儿子，神就差他儿子的灵进入你们的心，呼叫：「阿爸！父！」","notes":["原文是我们"]},{"n":7,"t":"可见，从此以后，你不是奴仆，乃是儿子了；既是儿子，就靠着神为后嗣。","notes":[]},{"n":8,"t":"但从前你们不认识神的时候，是给那些本来不是神的作奴仆；","notes":[]},{"n":9,"t":"现在你们既然认识神，更可说是被神所认识的，怎么还要归回那懦弱无用的小学，情愿再给他作奴仆呢？","notes":[]},{"n":10,"t":"你们谨守日子、月份、节期、年份，","notes":[]},{"n":11,"t":"我为你们害怕，惟恐我在你们身上是枉费了工夫。","notes":[]},{"n":12,"t":"弟兄们，我劝你们要像我一样，因为我也像你们一样。你们一点没有亏负我。","notes":[]},{"n":13,"t":"你们知道我头一次传福音给你们，是因为身体有疾病。","notes":[]},{"n":14,"t":"你们为我身体的缘故受试炼，没有轻看我，也没有厌弃我，反倒接待我，如同神的使者，如同基督耶稣。","notes":[]},{"n":15,"t":"你们当日所夸的福气在哪里呢？那时你们若能行，就是把自己的眼睛剜出来给我，也都情愿。这是我可以给你们作见证的。","notes":[]},{"n":16,"t":"如今我将真理告诉你们，就成了你们的仇敌吗？","notes":[]},{"n":17,"t":"那些人热心待你们，却不是好意，是要离间你们，叫你们热心待他们。","notes":["原文是把你们关在外面"]},{"n":18,"t":"在善事上，常用热心待人原是好的，却不单我与你们同在的时候才这样。","notes":[]},{"n":19,"t":"我小子啊，我为你们再受生产之苦，直等到基督成形在你们心里。","notes":[]},{"n":20,"t":"我巴不得现今在你们那里，改换口气，因我为你们心里作难。","notes":[]},{"n":21,"t":"你们这愿意在律法以下的人，请告诉我，你们岂没有听见律法吗？","notes":[],"heads":["夏甲和撒拉的例子"]},{"n":22,"t":"因为律法上记着，亚伯拉罕有两个儿子，一个是使女生的，一个是自主之妇人生的。","notes":[]},{"n":23,"t":"然而，那使女所生的是按着血气生的；那自主之妇人所生的是凭着应许生的。","notes":[]},{"n":24,"t":"这都是比方：那两个妇人就是两约。一约是出于西奈山，生子为奴，乃是夏甲。","notes":[]},{"n":25,"t":"这夏甲二字是指着阿拉伯的西奈山，与现在的耶路撒冷同类，因耶路撒冷和她的儿女都是为奴的。","notes":[]},{"n":26,"t":"但那在上的耶路撒冷是自主的，她是我们的母。","notes":[]},{"n":27,"t":"因为经上记着：不怀孕、不生养的，你要欢乐；未曾经过产难的，你要高声欢呼；因为没有丈夫的，比有丈夫的儿女更多。","notes":[]},{"n":28,"t":"弟兄们，我们是凭着应许作儿女，如同以撒一样。","notes":[]},{"n":29,"t":"当时，那按着血气生的逼迫了那按着圣灵生的，现在也是这样。","notes":[]},{"n":30,"t":"然而经上是怎么说的呢？是说：「把使女和她儿子赶出去！因为使女的儿子不可与自主妇人的儿子一同承受产业。」","notes":[]},{"n":31,"t":"弟兄们，这样看来，我们不是使女的儿女，乃是自主妇人的儿女了。","notes":[]}]},"5":{"heading":"基督徒的自由","verses":[{"n":1,"t":"基督释放了我们，叫我们得以自由。所以要站立得稳，不要再被奴仆的轭挟制。","notes":[]},{"n":2,"t":"我—保罗告诉你们，若受割礼，基督就与你们无益了。","notes":[]},{"n":3,"t":"我再指着凡受割礼的人确实地说，他是欠着行全律法的债。","notes":[]},{"n":4,"t":"你们这要靠律法称义的，是与基督隔绝，从恩典中坠落了。","notes":[]},{"n":5,"t":"我们靠着圣灵，凭着信心，等候所盼望的义。","notes":[]},{"n":6,"t":"原来在基督耶稣里，受割礼不受割礼全无功效，惟独使人生发仁爱的信心才有功效。","notes":[]},{"n":7,"t":"你们向来跑得好，有谁拦阻你们，叫你们不顺从真理呢？","notes":[]},{"n":8,"t":"这样的劝导不是出于那召你们的。","notes":[]},{"n":9,"t":"一点面酵能使全团都发起来。","notes":[]},{"n":10,"t":"我在主里很信你们必不怀别样的心；但搅扰你们的，无论是谁，必担当他的罪名。","notes":[]},{"n":11,"t":"弟兄们，我若仍旧传割礼，为什么还受逼迫呢？若是这样，那十字架讨厌的地方就没有了。","notes":[]},{"n":12,"t":"恨不得那搅乱你们的人把自己割绝了。","notes":[]},{"n":13,"t":"弟兄们，你们蒙召是要得自由，只是不可将你们的自由当作放纵情欲的机会，总要用爱心互相服事。","notes":[]},{"n":14,"t":"因为全律法都包在「爱人如己」这一句话之内了。","notes":[]},{"n":15,"t":"你们要谨慎，若相咬相吞，只怕要彼此消灭了。","notes":[]},{"n":16,"t":"我说，你们当顺着圣灵而行，就不放纵肉体的情欲了。","notes":[],"heads":["圣灵的果子和肉体的恶行"]},{"n":17,"t":"因为情欲和圣灵相争，圣灵和情欲相争，这两个是彼此相敌，使你们不能做所愿意做的。","notes":[]},{"n":18,"t":"但你们若被圣灵引导，就不在律法以下。","notes":[]},{"n":19,"t":"情欲的事都是显而易见的，就如奸淫、污秽、邪荡、","notes":[]},{"n":20,"t":"拜偶像、邪术、仇恨、争竞、忌恨、恼怒、结党、纷争、异端、","notes":[]},{"n":21,"t":"嫉妒、醉酒、荒宴等类。我从前告诉你们，现在又告诉你们，行这样事的人必不能承受神的国。","notes":["有古卷加：凶杀二字"]},{"n":22,"t":"圣灵所结的果子，就是仁爱、喜乐、和平、忍耐、恩慈、良善、信实、","notes":[]},{"n":23,"t":"温柔、节制。这样的事没有律法禁止。","notes":[]},{"n":24,"t":"凡属基督耶稣的人，是已经把肉体连肉体的邪情私欲同钉在十字架上了。","notes":[]},{"n":25,"t":"我们若是靠圣灵得生，就当靠圣灵行事。","notes":[]},{"n":26,"t":"不要贪图虚名，彼此惹气，互相嫉妒。","notes":[]}]},"6":{"heading":"各人的重担要互相担当","verses":[{"n":1,"t":"弟兄们，若有人偶然被过犯所胜，你们属灵的人就当用温柔的心把他挽回过来；又当自己小心，恐怕也被引诱。","notes":[]},{"n":2,"t":"你们各人的重担要互相担当，如此，就完全了基督的律法。","notes":[]},{"n":3,"t":"人若无有，自己还以为有，就是自欺了。","notes":[]},{"n":4,"t":"各人应当察验自己的行为；这样，他所夸的就专在自己，不在别人了，","notes":[]},{"n":5,"t":"因为各人必担当自己的担子。","notes":[]},{"n":6,"t":"在道理上受教的，当把一切需用的供给施教的人。","notes":[]},{"n":7,"t":"不要自欺，神是轻慢不得的。人种的是什么，收的也是什么。","notes":[]},{"n":8,"t":"顺着情欲撒种的，必从情欲收败坏；顺着圣灵撒种的，必从圣灵收永生。","notes":[]},{"n":9,"t":"我们行善，不可丧志；若不灰心，到了时候就要收成。","notes":[]},{"n":10,"t":"所以，有了机会就当向众人行善，向信徒一家的人更当这样。","notes":[]},{"n":11,"t":"请看我亲手写给你们的字是何等的大呢！","notes":[],"heads":["警告和祝福"]},{"n":12,"t":"凡希图外貌体面的人都勉强你们受割礼，无非是怕自己为基督的十字架受逼迫。","notes":[]},{"n":13,"t":"他们那些受割礼的，连自己也不守律法；他们愿意你们受割礼，不过要借着你们的肉体夸口。","notes":[]},{"n":14,"t":"但我断不以别的夸口，只夸我们主耶稣基督的十字架；因这十字架，就我而论，世界已经钉在十字架上；就世界而论，我已经钉在十字架上。","notes":[]},{"n":15,"t":"受割礼不受割礼都无关紧要，要紧的就是作新造的人。","notes":[]},{"n":16,"t":"凡照此理而行的，愿平安、怜悯加给他们，和神的以色列民。","notes":[]},{"n":17,"t":"从今以后，人都不要搅扰我，因为我身上带着耶稣的印记。","notes":[]},{"n":18,"t":"弟兄们，愿我主耶稣基督的恩常在你们心里。阿们！","notes":[]}]}},"EPH":{"1":{"heading":"问候","verses":[{"n":1,"t":"奉神旨意，作基督耶稣使徒的保罗，写信给在以弗所的圣徒，就是在基督耶稣里有忠心的人。","notes":[]},{"n":2,"t":"愿恩惠、平安从神我们的父和主耶稣基督归与你们！","notes":[]},{"n":3,"t":"愿颂赞归与我们主耶稣基督的父神！他在基督里曾赐给我们天上各样属灵的福气：","notes":[],"heads":["基督里的属灵福气"]},{"n":4,"t":"就如神从创立世界以前，在基督里拣选了我们，使我们在他面前成为圣洁，无有瑕疵；","notes":[]},{"n":5,"t":"又因爱我们，就按着自己的意旨所喜悦的，预定我们借着耶稣基督得儿子的名分，","notes":[]},{"n":6,"t":"使他荣耀的恩典得着称赞；这恩典是他在爱子里所赐给我们的。","notes":[]},{"n":7,"t":"我们借这爱子的血得蒙救赎，过犯得以赦免，乃是照他丰富的恩典。","notes":[]},{"n":8,"t":"这恩典是神用诸般智慧聪明，充充足足赏给我们的；","notes":[]},{"n":9,"t":"都是照他自己所预定的美意，叫我们知道他旨意的奥秘，","notes":[]},{"n":10,"t":"要照所安排的，在日期满足的时候，使天上、地上、一切所有的都在基督里面同归于一。","notes":[]},{"n":11,"t":"我们也在他里面得了基业；这原是那位随己意行、做万事的，照着他旨意所预定的，","notes":["得：或译成"]},{"n":12,"t":"叫他的荣耀从我们这首先在基督里有盼望的人可以得着称赞。","notes":[]},{"n":13,"t":"你们既听见真理的道，就是那叫你们得救的福音，也信了基督，既然信他，就受了所应许的圣灵为印记。","notes":[]},{"n":14,"t":"这圣灵是我们得基业的凭据，直等到神之民被赎，使他的荣耀得着称赞。","notes":["原文是质","民：原文是产业"]},{"n":15,"t":"因此，我既听见你们信从主耶稣，亲爱众圣徒，","notes":[],"heads":["保罗的祷告"]},{"n":16,"t":"就为你们不住地感谢神。祷告的时候，常提到你们，","notes":[]},{"n":17,"t":"求我们主耶稣基督的神，荣耀的父，将那赐人智慧和启示的灵赏给你们，使你们真知道他，","notes":[]},{"n":18,"t":"并且照明你们心中的眼睛，使你们知道他的恩召有何等指望，他在圣徒中得的基业有何等丰盛的荣耀；","notes":[]},{"n":19,"t":"并知道他向我们这信的人所显的能力是何等浩大，","notes":[]},{"n":20,"t":"就是照他在基督身上所运行的大能大力，使他从死里复活，叫他在天上坐在自己的右边，","notes":[]},{"n":21,"t":"远超过一切执政的、掌权的、有能的、主治的，和一切有名的；不但是今世的，连来世的也都超过了。","notes":[]},{"n":22,"t":"又将万有服在他的脚下，使他为教会作万有之首。","notes":[]},{"n":23,"t":"教会是他的身体，是那充满万有者所充满的。","notes":[]}]},"2":{"heading":"出死入生","verses":[{"n":1,"t":"你们死在过犯罪恶之中，他叫你们活过来。","notes":[]},{"n":2,"t":"那时，你们在其中行事为人，随从今世的风俗，顺服空中掌权者的首领，就是现今在悖逆之子心中运行的邪灵。","notes":[]},{"n":3,"t":"我们从前也都在他们中间，放纵肉体的私欲，随着肉体和心中所喜好的去行，本为可怒之子，和别人一样。","notes":[]},{"n":4,"t":"然而，神既有丰富的怜悯，因他爱我们的大爱，","notes":[]},{"n":5,"t":"当我们死在过犯中的时候，便叫我们与基督一同活过来。你们得救是本乎恩。","notes":[]},{"n":6,"t":"他又叫我们与基督耶稣一同复活，一同坐在天上，","notes":[]},{"n":7,"t":"要将他极丰富的恩典，就是他在基督耶稣里向我们所施的恩慈，显明给后来的世代看。","notes":[]},{"n":8,"t":"你们得救是本乎恩，也因着信；这并不是出于自己，乃是神所赐的；","notes":[]},{"n":9,"t":"也不是出于行为，免得有人自夸。","notes":[]},{"n":10,"t":"我们原是他的工作，在基督耶稣里造成的，为要叫我们行善，就是神所预备叫我们行的。","notes":[]},{"n":11,"t":"所以你们应当记念：你们从前按肉体是外邦人，是称为没受割礼的；这名原是那些凭人手在肉身上称为受割礼之人所起的。","notes":[],"heads":["在基督里合一"]},{"n":12,"t":"那时，你们与基督无关，在以色列国民以外，在所应许的诸约上是局外人，并且活在世上没有指望，没有神。","notes":[]},{"n":13,"t":"你们从前远离神的人，如今却在基督耶稣里，靠着他的血，已经得亲近了。","notes":[]},{"n":14,"t":"因他使我们和睦，将两下合而为一，拆毁了中间隔断的墙；","notes":["原文是因他是我们的和睦"]},{"n":15,"t":"而且以自己的身体废掉冤仇，就是那记在律法上的规条，为要将两下借着自己造成一个新人，如此便成就了和睦。","notes":[]},{"n":16,"t":"既在十字架上灭了冤仇，便借这十字架使两下归为一体，与神和好了，","notes":[]},{"n":17,"t":"并且来传和平的福音给你们远处的人，也给那近处的人。","notes":[]},{"n":18,"t":"因为我们两下借着他被一个圣灵所感，得以进到父面前。","notes":[]},{"n":19,"t":"这样，你们不再作外人和客旅，是与圣徒同国，是神家里的人了；","notes":[]},{"n":20,"t":"并且被建造在使徒和先知的根基上，有基督耶稣自己为房角石，","notes":[]},{"n":21,"t":"各房靠他联络得合式，渐渐成为主的圣殿。","notes":["或译：全"]},{"n":22,"t":"你们也靠他同被建造，成为神借着圣灵居住的所在。","notes":[]}]},"3":{"heading":"保罗奉差向外邦人传福音","verses":[{"n":1,"t":"因此，我—保罗为你们外邦人作了基督耶稣被囚的，替你们祈祷。","notes":["此句是照对十四节所加"]},{"n":2,"t":"谅必你们曾听见神赐恩给我，将关切你们的职分托付我，","notes":[]},{"n":3,"t":"用启示使我知道福音的奥秘，正如我以前略略写过的。","notes":[]},{"n":4,"t":"你们念了，就能晓得我深知基督的奥秘。","notes":[]},{"n":5,"t":"这奥秘在以前的世代没有叫人知道，像如今借着圣灵启示他的圣使徒和先知一样。","notes":[]},{"n":6,"t":"这奥秘就是外邦人在基督耶稣里，借着福音，得以同为后嗣，同为一体，同蒙应许。","notes":[]},{"n":7,"t":"我作了这福音的执事，是照神的恩赐，这恩赐是照他运行的大能赐给我的。","notes":[]},{"n":8,"t":"我本来比众圣徒中最小的还小，然而他还赐我这恩典，叫我把基督那测不透的丰富传给外邦人，","notes":[]},{"n":9,"t":"又使众人都明白，这历代以来隐藏在创造万物之神里的奥秘是如何安排的，","notes":[]},{"n":10,"t":"为要借着教会使天上执政的、掌权的，现在得知神百般的智慧。","notes":[]},{"n":11,"t":"这是照神从万世以前，在我们主基督耶稣里所定的旨意。","notes":[]},{"n":12,"t":"我们因信耶稣，就在他里面放胆无惧，笃信不疑地来到神面前。","notes":[]},{"n":13,"t":"所以，我求你们不要因我为你们所受的患难丧胆，这原是你们的荣耀。","notes":[]},{"n":14,"t":"因此，我在父面前屈膝，（","notes":[],"heads":["明白基督的爱"]},{"n":15,"t":"天上地上的各家，都是从他得名。）","notes":["或译：全"]},{"n":16,"t":"求他按着他丰盛的荣耀，借着他的灵，叫你们心里的力量刚强起来，","notes":[]},{"n":17,"t":"使基督因你们的信，住在你们心里，叫你们的爱心有根有基，","notes":[]},{"n":18,"t":"能以和众圣徒一同明白基督的爱是何等长阔高深，","notes":[]},{"n":19,"t":"并知道这爱是过于人所能测度的，便叫神一切所充满的，充满了你们。","notes":[]},{"n":20,"t":"神能照着运行在我们心里的大力充充足足地成就一切，超过我们所求所想的。","notes":[]},{"n":21,"t":"但愿他在教会中，并在基督耶稣里，得着荣耀，直到世世代代，永永远远。阿们！","notes":[]}]},"4":{"heading":"身体的合一","verses":[{"n":1,"t":"我为主被囚的劝你们：既然蒙召，行事为人就当与蒙召的恩相称。","notes":[]},{"n":2,"t":"凡事谦虚、温柔、忍耐，用爱心互相宽容，","notes":[]},{"n":3,"t":"用和平彼此联络，竭力保守圣灵所赐合而为一的心。","notes":[]},{"n":4,"t":"身体只有一个，圣灵只有一个，正如你们蒙召同有一个指望。","notes":[]},{"n":5,"t":"一主，一信，一洗，","notes":[]},{"n":6,"t":"一神，就是众人的父，超乎众人之上，贯乎众人之中，也住在众人之内。","notes":[]},{"n":7,"t":"我们各人蒙恩，都是照基督所量给各人的恩赐。","notes":[]},{"n":8,"t":"所以经上说：他升上高天的时候，掳掠了仇敌，将各样的恩赐赏给人。（","notes":[]},{"n":9,"t":"既说升上，岂不是先降在地下吗？","notes":[]},{"n":10,"t":"那降下的，就是远升诸天之上要充满万有的。）","notes":[]},{"n":11,"t":"他所赐的，有使徒，有先知，有传福音的，有牧师和教师，","notes":[]},{"n":12,"t":"为要成全圣徒，各尽其职，建立基督的身体，","notes":[]},{"n":13,"t":"直等到我们众人在真道上同归于一，认识神的儿子，得以长大成人，满有基督长成的身量，","notes":[]},{"n":14,"t":"使我们不再作小孩子，中了人的诡计和欺骗的法术，被一切异教之风摇动，飘来飘去，就随从各样的异端；","notes":[]},{"n":15,"t":"惟用爱心说诚实话，凡事长进，连于元首基督，","notes":[]},{"n":16,"t":"全身都靠他联络得合式，百节各按各职，照着各体的功用彼此相助，便叫身体渐渐增长，在爱中建立自己。","notes":[]},{"n":17,"t":"所以我说，且在主里确实地说，你们行事不要再像外邦人存虚妄的心行事。","notes":[],"heads":["旧人和新人"]},{"n":18,"t":"他们心地昏昧，与神所赐的生命隔绝了，都因自己无知，心里刚硬；","notes":[]},{"n":19,"t":"良心既然丧尽，就放纵私欲，贪行种种的污秽。","notes":[]},{"n":20,"t":"你们学了基督，却不是这样。","notes":[]},{"n":21,"t":"如果你们听过他的道，领了他的教，学了他的真理，","notes":[]},{"n":22,"t":"就要脱去你们从前行为上的旧人，这旧人是因私欲的迷惑渐渐变坏的；","notes":[]},{"n":23,"t":"又要将你们的心志改换一新，","notes":[]},{"n":24,"t":"并且穿上新人；这新人是照着神的形象造的，有真理的仁义和圣洁。","notes":[]},{"n":25,"t":"所以，你们要弃绝谎言，各人与邻舍说实话，因为我们是互相为肢体。","notes":[],"heads":["新生活的守则"]},{"n":26,"t":"生气却不要犯罪；不可含怒到日落，","notes":[]},{"n":27,"t":"也不可给魔鬼留地步。","notes":[]},{"n":28,"t":"从前偷窃的，不要再偷；总要劳力，亲手做正经事，就可有余分给那缺少的人。","notes":[]},{"n":29,"t":"污秽的言语一句不可出口，只要随事说造就人的好话，叫听见的人得益处。","notes":[]},{"n":30,"t":"不要叫神的圣灵担忧；你们原是受了他的印记，等候得赎的日子来到。","notes":[]},{"n":31,"t":"一切苦毒、恼恨、忿怒、嚷闹、毁谤，并一切的恶毒，都当从你们中间除掉；","notes":["或译：阴毒"]},{"n":32,"t":"并要以恩慈相待，存怜悯的心，彼此饶恕，正如神在基督里饶恕了你们一样。","notes":[]}]},"5":{"heading":"行事为人当像光明的子女","verses":[{"n":1,"t":"所以，你们该效法神，好像蒙慈爱的儿女一样。","notes":[]},{"n":2,"t":"也要凭爱心行事，正如基督爱我们，为我们舍了自己，当作馨香的供物和祭物，献与神。","notes":[]},{"n":3,"t":"至于淫乱并一切污秽，或是贪婪，在你们中间连提都不可，方合圣徒的体统。","notes":[]},{"n":4,"t":"淫词、妄语，和戏笑的话都不相宜；总要说感谢的话。","notes":[]},{"n":5,"t":"因为你们确实地知道，无论是淫乱的，是污秽的，是有贪心的，在基督和神的国里都是无分的。有贪心的，就与拜偶像的一样。","notes":[]},{"n":6,"t":"不要被人虚浮的话欺哄；因这些事，神的忿怒必临到那悖逆之子。","notes":[]},{"n":7,"t":"所以，你们不要与他们同伙。","notes":[]},{"n":8,"t":"从前你们是暗昧的，但如今在主里面是光明的，行事为人就当像光明的子女。","notes":[]},{"n":9,"t":"光明所结的果子就是一切良善、公义、诚实。","notes":[]},{"n":10,"t":"总要察验何为主所喜悦的事。","notes":[]},{"n":11,"t":"那暗昧无益的事，不要与人同行，倒要责备行这事的人；","notes":[]},{"n":12,"t":"因为他们暗中所行的，就是提起来也是可耻的。","notes":[]},{"n":13,"t":"凡事受了责备，就被光显明出来，因为一切能显明的就是光。","notes":[]},{"n":14,"t":"所以主说：你这睡着的人当醒过来，从死里复活！基督就要光照你了。","notes":[]},{"n":15,"t":"你们要谨慎行事，不要像愚昧人，当像智慧人。","notes":[]},{"n":16,"t":"要爱惜光阴，因为现今的世代邪恶。","notes":[]},{"n":17,"t":"不要作糊涂人，要明白主的旨意如何。","notes":[]},{"n":18,"t":"不要醉酒，酒能使人放荡；乃要被圣灵充满。","notes":[]},{"n":19,"t":"当用诗章、颂词、灵歌彼此对说，口唱心和地赞美主。","notes":[]},{"n":20,"t":"凡事要奉我们主耶稣基督的名常常感谢父神。","notes":[]},{"n":21,"t":"又当存敬畏基督的心，彼此顺服。","notes":[]},{"n":22,"t":"你们作妻子的，当顺服自己的丈夫，如同顺服主。","notes":[],"heads":["丈夫和妻子"]},{"n":23,"t":"因为丈夫是妻子的头，如同基督是教会的头；他又是教会全体的救主。","notes":[]},{"n":24,"t":"教会怎样顺服基督，妻子也要怎样凡事顺服丈夫。","notes":[]},{"n":25,"t":"你们作丈夫的，要爱你们的妻子，正如基督爱教会，为教会舍己。","notes":[]},{"n":26,"t":"要用水借着道把教会洗净，成为圣洁，","notes":[]},{"n":27,"t":"可以献给自己，作个荣耀的教会，毫无玷污、皱纹等类的病，乃是圣洁没有瑕疵的。","notes":[]},{"n":28,"t":"丈夫也当照样爱妻子，如同爱自己的身子；爱妻子便是爱自己了。","notes":[]},{"n":29,"t":"从来没有人恨恶自己的身子，总是保养顾惜，正像基督待教会一样，","notes":[]},{"n":30,"t":"因我们是他身上的肢体。","notes":["有古卷加：就是他的骨他的肉"]},{"n":31,"t":"为这个缘故，人要离开父母，与妻子连合，二人成为一体。","notes":[]},{"n":32,"t":"这是极大的奥秘，但我是指着基督和教会说的。","notes":[]},{"n":33,"t":"然而，你们各人都当爱妻子，如同爱自己一样。妻子也当敬重她的丈夫。","notes":[]}]},"6":{"heading":"儿女和父母","verses":[{"n":1,"t":"你们作儿女的，要在主里听从父母，这是理所当然的。","notes":[]},{"n":2,"t":"「要孝敬父母，使你得福，在世长寿。」这是第一条带应许的诫命。","notes":[],"end":3},{"n":4,"t":"你们作父亲的，不要惹儿女的气，只要照着主的教训和警戒养育他们。","notes":[]},{"n":5,"t":"你们作仆人的，要惧怕战兢，用诚实的心听从你们肉身的主人，好像听从基督一般。","notes":[],"heads":["仆人和主人"]},{"n":6,"t":"不要只在眼前事奉，像是讨人喜欢的，要像基督的仆人，从心里遵行神的旨意。","notes":[]},{"n":7,"t":"甘心事奉，好像服事主，不像服事人。","notes":[]},{"n":8,"t":"因为晓得各人所行的善事，不论是为奴的，是自主的，都必按所行的得主的赏赐。","notes":[]},{"n":9,"t":"你们作主人的，待仆人也是一理，不要威吓他们。因为知道，他们和你们同有一位主在天上；他并不偏待人。","notes":[]},{"n":10,"t":"我还有末了的话：你们要靠着主，倚赖他的大能大力作刚强的人。","notes":[],"heads":["与邪恶争战"]},{"n":11,"t":"要穿戴神所赐的全副军装，就能抵挡魔鬼的诡计。","notes":[]},{"n":12,"t":"因我们并不是与属血气的争战，乃是与那些执政的、掌权的、管辖这幽暗世界的，以及天空属灵气的恶魔争战。","notes":["原文是摔跤；下同"]},{"n":13,"t":"所以，要拿起神所赐的全副军装，好在磨难的日子抵挡仇敌，并且成就了一切，还能站立得住。","notes":[]},{"n":14,"t":"所以要站稳了，用真理当作带子束腰，用公义当作护心镜遮胸，","notes":[]},{"n":15,"t":"又用平安的福音当作预备走路的鞋穿在脚上。","notes":[]},{"n":16,"t":"此外，又拿着信德当作盾牌，可以灭尽那恶者一切的火箭；","notes":[]},{"n":17,"t":"并戴上救恩的头盔，拿着圣灵的宝剑，就是神的道；","notes":[]},{"n":18,"t":"靠着圣灵，随时多方祷告祈求；并要在此警醒不倦，为众圣徒祈求，","notes":[]},{"n":19,"t":"也为我祈求，使我得着口才，能以放胆开口讲明福音的奥秘，","notes":[]},{"n":20,"t":"（我为这福音的奥秘作了带锁链的使者，）并使我照着当尽的本分放胆讲论。","notes":[]},{"n":21,"t":"今有所亲爱、忠心事奉主的兄弟推基古，他要把我的事情，并我的景况如何全告诉你们，叫你们知道。","notes":[],"heads":["祝福"]},{"n":22,"t":"我特意打发他到你们那里去，好叫你们知道我们的光景，又叫他安慰你们的心。","notes":[]},{"n":23,"t":"愿平安、仁爱、信心从父神和主耶稣基督归与弟兄们！","notes":[]},{"n":24,"t":"并愿所有诚心爱我们主耶稣基督的人都蒙恩惠！","notes":[]}]}},"PHP":{"1":{"heading":"问候","verses":[{"n":1,"t":"基督耶稣的仆人保罗和提摩太写信给凡住腓立比、在基督耶稣里的众圣徒，和诸位监督，诸位执事。","notes":[]},{"n":2,"t":"愿恩惠、平安从神我们的父并主耶稣基督归与你们！","notes":[]},{"n":3,"t":"我每逢想念你们，就感谢我的神；","notes":[],"heads":["保罗为腓立比信徒祷告"]},{"n":4,"t":"每逢为你们众人祈求的时候，常是欢欢喜喜地祈求。","notes":[]},{"n":5,"t":"因为从头一天直到如今，你们是同心合意地兴旺福音。","notes":[]},{"n":6,"t":"我深信那在你们心里动了善工的，必成全这工，直到耶稣基督的日子。","notes":[]},{"n":7,"t":"我为你们众人有这样的意念，原是应当的；因你们常在我心里，无论我是在捆锁之中，是辩明证实福音的时候，你们都与我一同得恩。","notes":[]},{"n":8,"t":"我体会基督耶稣的心肠，切切地想念你们众人；这是神可以给我作见证的。","notes":[]},{"n":9,"t":"我所祷告的，就是要你们的爱心在知识和各样见识上多而又多，","notes":[]},{"n":10,"t":"使你们能分别是非，作诚实无过的人，直到基督的日子；","notes":["或译：喜爱那美好的事"]},{"n":11,"t":"并靠着耶稣基督结满了仁义的果子，叫荣耀称赞归与神。","notes":[]},{"n":12,"t":"弟兄们，我愿意你们知道，我所遭遇的事更是叫福音兴旺，","notes":[],"heads":["我活着就是基督"]},{"n":13,"t":"以致我受的捆锁在御营全军和其余的人中，已经显明是为基督的缘故。","notes":[]},{"n":14,"t":"并且那在主里的弟兄多半因我受的捆锁就笃信不疑，越发放胆传神的道，无所惧怕。","notes":[]},{"n":15,"t":"有的传基督是出于嫉妒纷争，也有的是出于好意。","notes":[]},{"n":16,"t":"这一等是出于爱心，知道我是为辩明福音设立的；","notes":[]},{"n":17,"t":"那一等传基督是出于结党，并不诚实，意思要加增我捆锁的苦楚。","notes":[]},{"n":18,"t":"这有何妨呢？或是假意，或是真心，无论怎样，基督究竟被传开了。为此，我就欢喜，并且还要欢喜；","notes":[]},{"n":19,"t":"因为我知道，这事借着你们的祈祷和耶稣基督之灵的帮助，终必叫我得救。","notes":[]},{"n":20,"t":"照着我所切慕、所盼望的，没有一事叫我羞愧。只要凡事放胆，无论是生是死，总叫基督在我身上照常显大。","notes":[]},{"n":21,"t":"因我活着就是基督，我死了就有益处。","notes":[]},{"n":22,"t":"但我在肉身活着，若成就我工夫的果子，我就不知道该挑选什么。","notes":[]},{"n":23,"t":"我正在两难之间，情愿离世与基督同在，因为这是好得无比的。","notes":[]},{"n":24,"t":"然而，我在肉身活着，为你们更是要紧的。","notes":[]},{"n":25,"t":"我既然这样深信，就知道仍要住在世间，且与你们众人同住，使你们在所信的道上又长进又喜乐，","notes":[]},{"n":26,"t":"叫你们在基督耶稣里的欢乐，因我再到你们那里去，就越发加增。","notes":[]},{"n":27,"t":"只要你们行事为人与基督的福音相称，叫我或来见你们，或不在你们那里，可以听见你们的景况，知道你们同有一个心志，站立得稳，为所信的福音齐心努力。","notes":[]},{"n":28,"t":"凡事不怕敌人的惊吓，这是证明他们沉沦，你们得救都是出于神。","notes":[]},{"n":29,"t":"因为你们蒙恩，不但得以信服基督，并要为他受苦。","notes":[]},{"n":30,"t":"你们的争战，就与你们在我身上从前所看见、现在所听见的一样。","notes":[]}]},"2":{"heading":"以基督的心为心","verses":[{"n":1,"t":"所以，在基督里若有什么劝勉，爱心有什么安慰，圣灵有什么交通，心中有什么慈悲怜悯，","notes":[]},{"n":2,"t":"你们就要意念相同，爱心相同，有一样的心思，有一样的意念，使我的喜乐可以满足。","notes":[]},{"n":3,"t":"凡事不可结党，不可贪图虚浮的荣耀；只要存心谦卑，各人看别人比自己强。","notes":[]},{"n":4,"t":"各人不要单顾自己的事，也要顾别人的事。","notes":[]},{"n":5,"t":"你们当以基督耶稣的心为心：","notes":[]},{"n":6,"t":"他本有神的形象，不以自己与神同等为强夺的；","notes":[]},{"n":7,"t":"反倒虚己，取了奴仆的形象，成为人的样式；","notes":[]},{"n":8,"t":"既有人的样子，就自己卑微，存心顺服，以至于死，且死在十字架上。","notes":[]},{"n":9,"t":"所以，神将他升为至高，又赐给他那超乎万名之上的名，","notes":[]},{"n":10,"t":"叫一切在天上的、地上的，和地底下的，因耶稣的名无不屈膝，","notes":[]},{"n":11,"t":"无不口称「耶稣基督为主」，使荣耀归与父神。","notes":[]},{"n":12,"t":"这样看来，我亲爱的弟兄，你们既是常顺服的，不但我在你们那里，就是我如今不在你们那里，更是顺服的，就当恐惧战兢做成你们得救的工夫。","notes":[],"heads":["在这世上像明光照耀"]},{"n":13,"t":"因为你们立志行事都是神在你们心里运行，为要成就他的美意。","notes":[]},{"n":14,"t":"凡所行的，都不要发怨言，起争论，","notes":[]},{"n":15,"t":"使你们无可指摘，诚实无伪，在这弯曲悖谬的世代作神无瑕疵的儿女。你们显在这世代中，好像明光照耀，","notes":[]},{"n":16,"t":"将生命的道表明出来，叫我在基督的日子好夸我没有空跑，也没有徒劳。","notes":[]},{"n":17,"t":"我以你们的信心为供献的祭物，我若被浇奠在其上，也是喜乐，并且与你们众人一同喜乐。","notes":[]},{"n":18,"t":"你们也要照样喜乐，并且与我一同喜乐。","notes":[]},{"n":19,"t":"我靠主耶稣指望快打发提摩太去见你们，叫我知道你们的事，心里就得着安慰。","notes":[],"heads":["提摩太和以巴弗提"]},{"n":20,"t":"因为我没有别人与我同心，实在挂念你们的事。","notes":[]},{"n":21,"t":"别人都求自己的事，并不求耶稣基督的事。","notes":[]},{"n":22,"t":"但你们知道提摩太的明证；他兴旺福音，与我同劳，待我像儿子待父亲一样。","notes":[]},{"n":23,"t":"所以，我一看出我的事要怎样了结，就盼望立刻打发他去；","notes":[]},{"n":24,"t":"但我靠着主自信我也必快去。","notes":[]},{"n":25,"t":"然而，我想必须打发以巴弗提到你们那里去。他是我的兄弟，与我一同做工，一同当兵，是你们所差遣的，也是供给我需用的。","notes":[]},{"n":26,"t":"他很想念你们众人，并且极其难过，因为你们听见他病了。","notes":[]},{"n":27,"t":"他实在是病了，几乎要死；然而神怜恤他，不但怜恤他，也怜恤我，免得我忧上加忧。","notes":[]},{"n":28,"t":"所以我越发急速打发他去，叫你们再见他，就可以喜乐，我也可以少些忧愁。","notes":[]},{"n":29,"t":"故此，你们要在主里欢欢乐乐地接待他，而且要尊重这样的人；","notes":[]},{"n":30,"t":"因他为做基督的工夫，几乎至死，不顾性命，要补足你们供给我的不及之处。","notes":[]}]},"3":{"heading":"真正的义","verses":[{"n":1,"t":"弟兄们，我还有话说，你们要靠主喜乐。我把这话再写给你们，于我并不为难，于你们却是妥当。","notes":[]},{"n":2,"t":"应当防备犬类，防备作恶的，防备妄自行割的。","notes":[]},{"n":3,"t":"因为真受割礼的，乃是我们这以神的灵敬拜、在基督耶稣里夸口、不靠着肉体的。","notes":[]},{"n":4,"t":"其实，我也可以靠肉体；若是别人想他可以靠肉体，我更可以靠着了。","notes":[]},{"n":5,"t":"我第八天受割礼；我是以色列族、便雅悯支派的人，是希伯来人所生的希伯来人。就律法说，我是法利赛人；","notes":[]},{"n":6,"t":"就热心说，我是逼迫教会的；就律法上的义说，我是无可指摘的。","notes":[]},{"n":7,"t":"只是我先前以为与我有益的，我现在因基督都当作有损的。","notes":[]},{"n":8,"t":"不但如此，我也将万事当作有损的，因我以认识我主基督耶稣为至宝。我为他已经丢弃万事，看作粪土，为要得着基督；","notes":[]},{"n":9,"t":"并且得以在他里面，不是有自己因律法而得的义，乃是有信基督的义，就是因信神而来的义，","notes":[]},{"n":10,"t":"使我认识基督，晓得他复活的大能，并且晓得和他一同受苦，效法他的死，","notes":[]},{"n":11,"t":"或者我也得以从死里复活。","notes":[]},{"n":12,"t":"这不是说我已经得着了，已经完全了；我乃是竭力追求，或者可以得着基督耶稣所以得着我的。","notes":["所以得着我的：或译所要我得的"],"heads":["向着标竿直跑"]},{"n":13,"t":"弟兄们，我不是以为自己已经得着了；我只有一件事，就是忘记背后，努力面前的，","notes":[]},{"n":14,"t":"向着标竿直跑，要得神在基督耶稣里从上面召我来得的奖赏。","notes":[]},{"n":15,"t":"所以我们中间，凡是完全人总要存这样的心；若在什么事上存别样的心，神也必以此指示你们。","notes":[]},{"n":16,"t":"然而，我们到了什么地步，就当照着什么地步行。","notes":[]},{"n":17,"t":"弟兄们，你们要一同效法我，也当留意看那些照我们榜样行的人。","notes":[]},{"n":18,"t":"因为有许多人行事是基督十字架的仇敌。我屡次告诉你们，现在又流泪地告诉你们：","notes":[]},{"n":19,"t":"他们的结局就是沉沦；他们的神就是自己的肚腹。他们以自己的羞辱为荣耀，专以地上的事为念。","notes":[]},{"n":20,"t":"我们却是天上的国民，并且等候救主，就是主耶稣基督从天上降临。","notes":[]},{"n":21,"t":"他要按着那能叫万有归服自己的大能，将我们这卑贱的身体改变形状，和他自己荣耀的身体相似。","notes":[]}]},"4":{"heading":"保罗的劝导","verses":[{"n":1,"t":"我所亲爱、所想念的弟兄们，你们就是我的喜乐，我的冠冕。我亲爱的弟兄，你们应当靠主站立得稳。","notes":[]},{"n":2,"t":"我劝友阿蝶和循都基，要在主里同心。","notes":[]},{"n":3,"t":"我也求你这真实同负一轭的，帮助这两个女人，因为她们在福音上曾与我一同劳苦；还有革利免，并其余和我一同做工的，他们的名字都在生命册上。","notes":[]},{"n":4,"t":"你们要靠主常常喜乐。我再说，你们要喜乐。","notes":[]},{"n":5,"t":"当叫众人知道你们谦让的心。主已经近了。","notes":[]},{"n":6,"t":"应当一无挂虑，只要凡事借着祷告、祈求，和感谢，将你们所要的告诉神。","notes":[]},{"n":7,"t":"神所赐、出人意外的平安必在基督耶稣里保守你们的心怀意念。","notes":[]},{"n":8,"t":"弟兄们，我还有未尽的话：凡是真实的、可敬的、公义的、清洁的、可爱的、有美名的，若有什么德行，若有什么称赞，这些事你们都要思念。","notes":[]},{"n":9,"t":"你们在我身上所学习的，所领受的，所听见的，所看见的，这些事你们都要去行，赐平安的神就必与你们同在。","notes":[]},{"n":10,"t":"我靠主大大地喜乐，因为你们思念我的心如今又发生；你们向来就思念我，只是没得机会。","notes":[],"heads":["为馈送而致谢"]},{"n":11,"t":"我并不是因缺乏说这话；我无论在什么景况都可以知足，这是我已经学会了。","notes":[]},{"n":12,"t":"我知道怎样处卑贱，也知道怎样处丰富；或饱足，或饥饿；或有余，或缺乏，随事随在，我都得了秘诀。","notes":[]},{"n":13,"t":"我靠着那加给我力量的，凡事都能做。","notes":[]},{"n":14,"t":"然而，你们和我同受患难原是美事。","notes":[]},{"n":15,"t":"腓立比人哪，你们也知道我初传福音离了马其顿的时候，论到授受的事，除了你们以外，并没有别的教会供给我。","notes":[]},{"n":16,"t":"就是我在帖撒罗尼迦，你们也一次两次地打发人供给我的需用。","notes":[]},{"n":17,"t":"我并不求什么馈送，所求的就是你们的果子渐渐增多，归在你们的帐上。","notes":[]},{"n":18,"t":"但我样样都有，并且有余。我已经充足，因我从以巴弗提受了你们的馈送，当作极美的香气，为神所收纳、所喜悦的祭物。","notes":[]},{"n":19,"t":"我的神必照他荣耀的丰富，在基督耶稣里，使你们一切所需用的都充足。","notes":[]},{"n":20,"t":"愿荣耀归给我们的父神，直到永永远远。阿们！","notes":[]},{"n":21,"t":"请问在基督耶稣里的各位圣徒安。在我这里的众弟兄都问你们安。","notes":[],"heads":["祝福"]},{"n":22,"t":"众圣徒都问你们安。在凯撒家里的人特特地问你们安。","notes":[]},{"n":23,"t":"愿主耶稣基督的恩常在你们心里！","notes":[]}]}},"COL":{"1":{"heading":"问候","verses":[{"n":1,"t":"奉神旨意，作基督耶稣使徒的保罗和兄弟提摩太","notes":[]},{"n":2,"t":"写信给歌罗西的圣徒，在基督里有忠心的弟兄。愿恩惠、平安从神我们的父归与你们！","notes":[]},{"n":3,"t":"我们感谢神我们主耶稣基督的父，常常为你们祷告；","notes":[],"heads":["为信徒感谢神"]},{"n":4,"t":"因听见你们在基督耶稣里的信心，并向众圣徒的爱心，","notes":[]},{"n":5,"t":"是为那给你们存在天上的盼望；这盼望就是你们从前在福音真理的道上所听见的。","notes":[]},{"n":6,"t":"这福音传到你们那里，也传到普天之下，并且结果，增长，如同在你们中间，自从你们听见福音，真知道神恩惠的日子一样。","notes":[]},{"n":7,"t":"正如你们从我们所亲爱、一同作仆人的以巴弗所学的。他为我们作了基督忠心的执事，","notes":["有古卷：你们"]},{"n":8,"t":"也把你们因圣灵所存的爱心告诉了我们。","notes":[]},{"n":9,"t":"因此，我们自从听见的日子，也就为你们不住地祷告祈求，愿你们在一切属灵的智慧悟性上，满心知道神的旨意；","notes":[],"heads":["基督的位格和工作"]},{"n":10,"t":"好叫你们行事为人对得起主，凡事蒙他喜悦，在一切善事上结果子，渐渐地多知道神；","notes":[]},{"n":11,"t":"照他荣耀的权能，得以在各样的力上加力，好叫你们凡事欢欢喜喜地忍耐宽容；","notes":[]},{"n":12,"t":"又感谢父，叫我们能与众圣徒在光明中同得基业。","notes":[]},{"n":13,"t":"他救了我们脱离黑暗的权势，把我们迁到他爱子的国里；","notes":[]},{"n":14,"t":"我们在爱子里得蒙救赎，罪过得以赦免。","notes":[]},{"n":15,"t":"爱子是那不能看见之神的像，是首生的，在一切被造的以先。","notes":[]},{"n":16,"t":"因为万有都是靠他造的，无论是天上的，地上的；能看见的，不能看见的；或是有位的，主治的，执政的，掌权的；一概都是借着他造的，又是为他造的。","notes":[]},{"n":17,"t":"他在万有之先；万有也靠他而立。","notes":[]},{"n":18,"t":"他也是教会全体之首。他是元始，是从死里首先复生的，使他可以在凡事上居首位。","notes":[]},{"n":19,"t":"因为父喜欢叫一切的丰盛在他里面居住。","notes":[]},{"n":20,"t":"既然借着他在十字架上所流的血成就了和平，便借着他叫万有—无论是地上的、天上的—都与自己和好了。","notes":[]},{"n":21,"t":"你们从前与神隔绝，因着恶行，心里与他为敌。","notes":[]},{"n":22,"t":"但如今他借着基督的肉身受死，叫你们与自己和好，都成了圣洁，没有瑕疵，无可责备，把你们引到自己面前。","notes":[]},{"n":23,"t":"只要你们在所信的道上恒心，根基稳固，坚定不移，不至被引动失去福音的盼望。这福音就是你们所听过的，也是传与普天下万人听的，我—保罗也作了这福音的执事。","notes":["原文是离开","原文是凡受造的"]},{"n":24,"t":"现在我为你们受苦，倒觉欢乐；并且为基督的身体，就是为教会，要在我肉身上补满基督患难的缺欠。","notes":[],"heads":["保罗为教会的工作"]},{"n":25,"t":"我照神为你们所赐我的职分作了教会的执事，要把神的道理传得全备，","notes":[]},{"n":26,"t":"这道理就是历世历代所隐藏的奥秘；但如今向他的圣徒显明了。","notes":[]},{"n":27,"t":"神愿意叫他们知道，这奥秘在外邦人中有何等丰盛的荣耀，就是基督在你们心里成了有荣耀的盼望。","notes":[]},{"n":28,"t":"我们传扬他，是用诸般的智慧，劝戒各人，教导各人，要把各人在基督里完完全全地引到神面前。","notes":[]},{"n":29,"t":"我也为此劳苦，照着他在我里面运用的大能尽心竭力。","notes":[]}]},"2":{"heading":"基督里生命的丰盛","verses":[{"n":1,"t":"我愿意你们晓得，我为你们和老底嘉人，并一切没有与我亲自见面的人，是何等地尽心竭力；","notes":[]},{"n":2,"t":"要叫他们的心得安慰，因爱心互相联络，以致丰丰足足在悟性中有充足的信心，使他们真知神的奥秘，就是基督；","notes":[]},{"n":3,"t":"所积蓄的一切智慧知识，都在他里面藏着。","notes":[]},{"n":4,"t":"我说这话，免得有人用花言巧语迷惑你们。","notes":[]},{"n":5,"t":"我身子虽与你们相离，心却与你们同在，见你们循规蹈矩，信基督的心也坚固，我就欢喜了。","notes":[]},{"n":6,"t":"你们既然接受了主基督耶稣，就当遵他而行，","notes":[]},{"n":7,"t":"在他里面生根建造，信心坚固，正如你们所领的教训，感谢的心也更增长了。","notes":[]},{"n":8,"t":"你们要谨慎，恐怕有人用他的理学和虚空的妄言，不照着基督，乃照人间的遗传和世上的小学就把你们掳去。","notes":[]},{"n":9,"t":"因为神本性一切的丰盛都有形有体地居住在基督里面，","notes":[]},{"n":10,"t":"你们在他里面也得了丰盛。他是各样执政掌权者的元首。","notes":[]},{"n":11,"t":"你们在他里面也受了不是人手所行的割礼，乃是基督使你们脱去肉体情欲的割礼。","notes":[]},{"n":12,"t":"你们既受洗与他一同埋葬，也就在此与他一同复活，都因信那叫他从死里复活神的功用。","notes":[]},{"n":13,"t":"你们从前在过犯和未受割礼的肉体中死了，神赦免了你们一切过犯，便叫你们与基督一同活过来；","notes":["或译：我们"]},{"n":14,"t":"又涂抹了在律例上所写、攻击我们、有碍于我们的字据，把它撤去，钉在十字架上。","notes":[]},{"n":15,"t":"既将一切执政的、掌权的掳来，明显给众人看，就仗着十字架夸胜。","notes":[]},{"n":16,"t":"所以，不拘在饮食上，或节期、月朔、安息日都不可让人论断你们。","notes":[]},{"n":17,"t":"这些原是后事的影儿；那形体却是基督。","notes":[]},{"n":18,"t":"不可让人因着故意谦虚和敬拜天使，就夺去你们的奖赏。这等人拘泥在所见过的，随着自己的欲心，无故地自高自大，","notes":["有古卷：这等人窥察所没有见过的"]},{"n":19,"t":"不持定元首。全身既然靠着他，筋节得以相助联络，就因神大得长进。","notes":[]},{"n":20,"t":"你们若是与基督同死，脱离了世上的小学，为什么仍像在世俗中活着、服从那「不可拿、不可尝、不可摸」等类的规条呢？","notes":[],"end":21,"heads":["基督里的新生活"]},{"n":22,"t":"这都是照人所吩咐、所教导的。说到这一切，正用的时候就都败坏了。","notes":[]},{"n":23,"t":"这些规条使人徒有智慧之名，用私意崇拜，自表谦卑，苦待己身，其实在克制肉体的情欲上是毫无功效。","notes":[]}]},"3":{"heading":"新生活的本分","verses":[{"n":1,"t":"所以，你们若真与基督一同复活，就当求在上面的事；那里有基督坐在神的右边。","notes":[]},{"n":2,"t":"你们要思念上面的事，不要思念地上的事。","notes":[]},{"n":3,"t":"因为你们已经死了，你们的生命与基督一同藏在神里面。","notes":[]},{"n":4,"t":"基督是我们的生命，他显现的时候，你们也要与他一同显现在荣耀里。","notes":[]},{"n":5,"t":"所以，要治死你们在地上的肢体，就如淫乱、污秽、邪情、恶欲，和贪婪（贪婪就与拜偶像一样）。","notes":[]},{"n":6,"t":"因这些事，神的忿怒必临到那悖逆之子。","notes":[]},{"n":7,"t":"当你们在这些事中活着的时候，也曾这样行过。","notes":[]},{"n":8,"t":"但现在你们要弃绝这一切的事，以及恼恨、忿怒、恶毒、毁谤，并口中污秽的言语。","notes":["或译：阴毒"]},{"n":9,"t":"不要彼此说谎；因你们已经脱去旧人和旧人的行为，","notes":[]},{"n":10,"t":"穿上了新人。这新人在知识上渐渐更新，正如造他主的形象。","notes":[]},{"n":11,"t":"在此并不分希腊人、犹太人，受割礼的、未受割礼的，化外人、西古提人，为奴的、自主的，惟有基督是包括一切，又住在各人之内。","notes":[]},{"n":12,"t":"所以，你们既是神的选民，圣洁蒙爱的人，就要存怜悯、恩慈、谦虚、温柔、忍耐的心。","notes":["原文是穿；下同"]},{"n":13,"t":"倘若这人与那人有嫌隙，总要彼此包容，彼此饶恕；主怎样饶恕了你们，你们也要怎样饶恕人。","notes":[]},{"n":14,"t":"在这一切之外，要存着爱心，爱心就是联络全德的。","notes":[]},{"n":15,"t":"又要叫基督的平安在你们心里作主；你们也为此蒙召，归为一体；且要存感谢的心。","notes":[]},{"n":16,"t":"当用各样的智慧，把基督的道理丰丰富富地存在心里，用诗章、颂词、灵歌，彼此教导，互相劝戒，心被恩感，歌颂神。","notes":["或译：当把基督的道理丰丰富富地存在心里，以各样的智慧"]},{"n":17,"t":"无论做什么，或说话或行事，都要奉主耶稣的名，借着他感谢父神。","notes":[]},{"n":18,"t":"你们作妻子的，当顺服自己的丈夫，这在主里面是相宜的。","notes":[]},{"n":19,"t":"你们作丈夫的，要爱你们的妻子，不可苦待她们。","notes":[]},{"n":20,"t":"你们作儿女的，要凡事听从父母，因为这是主所喜悦的。","notes":[]},{"n":21,"t":"你们作父亲的，不要惹儿女的气，恐怕他们失了志气。","notes":[]},{"n":22,"t":"你们作仆人的，要凡事听从你们肉身的主人，不要只在眼前事奉，像是讨人喜欢的，总要存心诚实敬畏主。","notes":[]},{"n":23,"t":"无论做什么，都要从心里做，像是给主做的，不是给人做的，","notes":[]},{"n":24,"t":"因你们知道从主那里必得着基业为赏赐；你们所事奉的乃是主基督。","notes":[]},{"n":25,"t":"那行不义的必受不义的报应；主并不偏待人。","notes":[]}]},"4":{"heading":"劝导","verses":[{"n":1,"t":"你们作主人的，要公公平平地待仆人，因为知道你们也有一位主在天上。","notes":[]},{"n":2,"t":"你们要恒切祷告，在此警醒感恩。","notes":[]},{"n":3,"t":"也要为我们祷告，求神给我们开传道的门，能以讲基督的奥秘（我为此被捆锁），","notes":[]},{"n":4,"t":"叫我按着所该说的话将这奥秘发明出来。","notes":[]},{"n":5,"t":"你们要爱惜光阴，用智慧与外人交往。","notes":[]},{"n":6,"t":"你们的言语要常常带着和气，好像用盐调和，就可知道该怎样回答各人。","notes":[]},{"n":7,"t":"有我亲爱的兄弟推基古要将我一切的事都告诉你们。他是忠心的执事，和我一同作主的仆人。","notes":[],"heads":["最后的问候"]},{"n":8,"t":"我特意打发他到你们那里去，好叫你们知道我们的光景，又叫他安慰你们的心。","notes":[]},{"n":9,"t":"我又打发一位亲爱忠心的兄弟阿尼西谋同去；他也是你们那里的人。他们要把这里一切的事都告诉你们。","notes":[]},{"n":10,"t":"与我一同坐监的亚里达古问你们安。巴拿巴的表弟马可也问你们安。（说到这马可，你们已经受了吩咐；他若到了你们那里，你们就接待他。）","notes":[]},{"n":11,"t":"耶数又称为犹士都，也问你们安。奉割礼的人中，只有这三个人是为神的国与我一同做工的，也是叫我心里得安慰的。","notes":[]},{"n":12,"t":"有你们那里的人，作基督耶稣仆人的以巴弗问你们安。他在祷告之间，常为你们竭力地祈求，愿你们在神一切的旨意上得以完全，信心充足，能站立得稳。","notes":[]},{"n":13,"t":"他为你们和老底嘉并希拉坡里的弟兄多多地劳苦，这是我可以给他作见证的。","notes":[]},{"n":14,"t":"所亲爱的医生路加和底马问你们安。","notes":[]},{"n":15,"t":"请问老底嘉的弟兄和宁法，并她家里的教会安。","notes":[]},{"n":16,"t":"你们念了这书信，便交给老底嘉的教会，叫他们也念；你们也要念从老底嘉来的书信。","notes":[]},{"n":17,"t":"要对亚基布说：「务要谨慎，尽你从主所受的职分。」","notes":[]},{"n":18,"t":"我—保罗亲笔问你们安。你们要记念我的捆锁。愿恩惠常与你们同在！","notes":[]}]}},"1TH":{"1":{"heading":"问候","verses":[{"n":1,"t":"保罗、西拉、提摩太写信给帖撒罗尼迦在父神和主耶稣基督里的教会。愿恩惠、平安归与你们！","notes":[]},{"n":2,"t":"我们为你们众人常常感谢神，祷告的时候提到你们，","notes":[],"heads":["帖撒罗尼迦信徒的信心和榜样"]},{"n":3,"t":"在神—我们的父面前，不住地记念你们因信心所做的工夫，因爱心所受的劳苦，因盼望我们主耶稣基督所存的忍耐。","notes":[]},{"n":4,"t":"被神所爱的弟兄啊，我知道你们是蒙拣选的；","notes":[]},{"n":5,"t":"因为我们的福音传到你们那里，不独在乎言语，也在乎权能和圣灵，并充足的信心。正如你们知道，我们在你们那里，为你们的缘故是怎样为人。","notes":[]},{"n":6,"t":"并且你们在大难之中，蒙了圣灵所赐的喜乐，领受真道就效法我们，也效法了主；","notes":[]},{"n":7,"t":"甚至你们作了马其顿和亚该亚所有信主之人的榜样。","notes":[]},{"n":8,"t":"因为主的道从你们那里已经传扬出来。你们向神的信心不但在马其顿和亚该亚，就是在各处也都传开了，所以不用我们说什么话。","notes":[]},{"n":9,"t":"因为他们自己已经报明我们是怎样进到你们那里，你们是怎样离弃偶像，归向神，要服事那又真又活的神，","notes":[]},{"n":10,"t":"等候他儿子从天降临，就是他从死里复活的—那位救我们脱离将来忿怒的耶稣。","notes":[]}]},"2":{"heading":"保罗在帖撒罗尼迦工作","verses":[{"n":1,"t":"弟兄们，你们自己原晓得我们进到你们那里并不是徒然的。","notes":[]},{"n":2,"t":"我们从前在腓立比被害受辱，这是你们知道的；然而还是靠我们的神放开胆量，在大争战中把神的福音传给你们。","notes":[]},{"n":3,"t":"我们的劝勉不是出于错误，不是出于污秽，也不是用诡诈。","notes":[]},{"n":4,"t":"但神既然验中了我们，把福音托付我们，我们就照样讲，不是要讨人喜欢，乃是要讨那察验我们心的神喜欢。","notes":[]},{"n":5,"t":"因为我们从来没有用过谄媚的话，这是你们知道的；也没有藏着贪心，这是神可以作见证的。","notes":[]},{"n":6,"t":"我们作基督的使徒，虽然可以叫人尊重，却没有向你们或向别人求荣耀；","notes":[]},{"n":7,"t":"只在你们中间存心温柔，如同母亲乳养自己的孩子。","notes":[]},{"n":8,"t":"我们既是这样爱你们，不但愿意将神的福音给你们，连自己的性命也愿意给你们，因你们是我们所疼爱的。","notes":[]},{"n":9,"t":"弟兄们，你们记念我们的辛苦劳碌，昼夜做工，传神的福音给你们，免得叫你们一人受累。","notes":[]},{"n":10,"t":"我们向你们信主的人，是何等圣洁、公义、无可指摘，有你们作见证，也有神作见证。","notes":[]},{"n":11,"t":"你们也晓得，我们怎样劝勉你们，安慰你们，嘱咐你们各人，好像父亲待自己的儿女一样，","notes":[]},{"n":12,"t":"要叫你们行事对得起那召你们进他国、得他荣耀的神。","notes":[]},{"n":13,"t":"为此，我们也不住地感谢神，因你们听见我们所传神的道就领受了；不以为是人的道，乃以为是神的道。这道实在是神的，并且运行在你们信主的人心中。","notes":[]},{"n":14,"t":"弟兄们，你们曾效法犹太中在基督耶稣里神的各教会；因为你们也受了本地人的苦害，像他们受了犹太人的苦害一样。","notes":[]},{"n":15,"t":"这犹太人杀了主耶稣和先知，又把我们赶出去。他们不得神的喜悦，且与众人为敌，","notes":[]},{"n":16,"t":"不许我们传道给外邦人使外邦人得救，常常充满自己的罪恶。神的忿怒临在他们身上已经到了极处。","notes":[]},{"n":17,"t":"弟兄们，我们暂时与你们离别，是面目离别，心里却不离别；我们极力地想法子，很愿意见你们的面。","notes":[],"heads":["保罗希望再访问帖撒罗尼迦教会"]},{"n":18,"t":"所以我们有意到你们那里；我—保罗有一两次要去，只是撒但阻挡了我们。","notes":[]},{"n":19,"t":"我们的盼望和喜乐，并所夸的冠冕是什么呢？岂不是我们主耶稣来的时候、你们在他面前站立得住吗？","notes":[]},{"n":20,"t":"因为你们就是我们的荣耀，我们的喜乐。","notes":[]}]},"3":{"heading":"","verses":[{"n":1,"t":"我们既不能再忍，就愿意独自等在雅典，","notes":[]},{"n":2,"t":"打发我们的兄弟在基督福音上作神执事的提摩太前去，坚固你们，并在你们所信的道上劝慰你们，","notes":["作神执事的：有古卷是与神同工的"]},{"n":3,"t":"免得有人被诸般患难摇动。因为你们自己知道，我们受患难原是命定的。","notes":[]},{"n":4,"t":"我们在你们那里的时候，预先告诉你们，我们必受患难，以后果然应验了，你们也知道。","notes":[]},{"n":5,"t":"为此，我既不能再忍，就打发人去，要晓得你们的信心如何，恐怕那诱惑人的到底诱惑了你们，叫我们的劳苦归于徒然。","notes":[]},{"n":6,"t":"但提摩太刚才从你们那里回来，将你们信心和爱心的好消息报给我们，又说你们常常记念我们，切切地想见我们，如同我们想见你们一样。","notes":[]},{"n":7,"t":"所以，弟兄们，我们在一切困苦患难之中，因着你们的信心就得了安慰。","notes":[]},{"n":8,"t":"你们若靠主站立得稳，我们就活了。","notes":[]},{"n":9,"t":"我们在神面前，因着你们甚是喜乐；为这一切喜乐，可用何等的感谢为你们报答神呢？","notes":[]},{"n":10,"t":"我们昼夜切切地祈求，要见你们的面，补满你们信心的不足。","notes":[]},{"n":11,"t":"愿神—我们的父和我们的主耶稣一直引领我们到你们那里去。","notes":[]},{"n":12,"t":"又愿主叫你们彼此相爱的心，并爱众人的心都能增长，充足，如同我们爱你们一样，","notes":[]},{"n":13,"t":"好使你们当我们主耶稣同他众圣徒来的时候，在我们父神面前，心里坚固，成为圣洁，无可责备。","notes":[]}]},"4":{"heading":"神所悦纳的生活","verses":[{"n":1,"t":"弟兄们，我还有话说：我们靠着主耶稣求你们，劝你们，你们既然受了我们的教训，知道该怎样行可以讨神的喜悦，就要照你们现在所行的更加勉励。","notes":[]},{"n":2,"t":"你们原晓得，我们凭主耶稣传给你们什么命令。","notes":[]},{"n":3,"t":"神的旨意就是要你们成为圣洁，远避淫行；","notes":[]},{"n":4,"t":"要你们各人晓得怎样用圣洁、尊贵守着自己的身体，","notes":[]},{"n":5,"t":"不放纵私欲的邪情，像那不认识神的外邦人。","notes":[]},{"n":6,"t":"不要一个人在这事上越分，欺负他的弟兄；因为这一类的事，主必报应，正如我预先对你们说过、又切切嘱咐你们的。","notes":[]},{"n":7,"t":"神召我们，本不是要我们沾染污秽，乃是要我们成为圣洁。","notes":[]},{"n":8,"t":"所以，那弃绝的，不是弃绝人，乃是弃绝那赐圣灵给你们的神。","notes":[]},{"n":9,"t":"论到弟兄们相爱，不用人写信给你们；因为你们自己蒙了神的教训，叫你们彼此相爱。","notes":[]},{"n":10,"t":"你们向马其顿全地的众弟兄固然是这样行，但我劝弟兄们要更加勉励。","notes":[]},{"n":11,"t":"又要立志作安静人，办自己的事，亲手做工，正如我们从前所吩咐你们的，","notes":[]},{"n":12,"t":"叫你们可以向外人行事端正，自己也就没有什么缺乏了。","notes":[]},{"n":13,"t":"论到睡了的人，我们不愿意弟兄们不知道，恐怕你们忧伤，像那些没有指望的人一样。","notes":[],"heads":["主的降临"]},{"n":14,"t":"我们若信耶稣死而复活了，那已经在耶稣里睡了的人，神也必将他们与耶稣一同带来。","notes":[]},{"n":15,"t":"我们现在照主的话告诉你们一件事：我们这活着还存留到主降临的人，断不能在那已经睡了的人之先。","notes":[]},{"n":16,"t":"因为主必亲自从天降临，有呼叫的声音和天使长的声音，又有神的号吹响；那在基督里死了的人必先复活。","notes":[]},{"n":17,"t":"以后我们这活着还存留的人必和他们一同被提到云里，在空中与主相遇。这样，我们就要和主永远同在。","notes":[]},{"n":18,"t":"所以，你们当用这些话彼此劝慰。","notes":[]}]},"5":{"heading":"最后的劝勉与祝福","verses":[{"n":1,"t":"弟兄们，论到时候、日期，不用写信给你们，","notes":[]},{"n":2,"t":"因为你们自己明明晓得，主的日子来到，好像夜间的贼一样。","notes":[]},{"n":3,"t":"人正说「平安稳妥」的时候，灾祸忽然临到他们，如同产难临到怀胎的妇人一样，他们绝不能逃脱。","notes":[]},{"n":4,"t":"弟兄们，你们却不在黑暗里，叫那日子临到你们像贼一样。","notes":[]},{"n":5,"t":"你们都是光明之子，都是白昼之子。我们不是属黑夜的，也不是属幽暗的。","notes":[]},{"n":6,"t":"所以，我们不要睡觉像别人一样，总要警醒谨守。","notes":[]},{"n":7,"t":"因为睡了的人是在夜间睡，醉了的人是在夜间醉。","notes":[]},{"n":8,"t":"但我们既然属乎白昼，就应当谨守，把信和爱当作护心镜遮胸，把得救的盼望当作头盔戴上。","notes":[]},{"n":9,"t":"因为神不是预定我们受刑，乃是预定我们借着我们主耶稣基督得救。","notes":[]},{"n":10,"t":"他替我们死，叫我们无论醒着，睡着，都与他同活。","notes":[]},{"n":11,"t":"所以，你们该彼此劝慰，互相建立，正如你们素常所行的。","notes":[]},{"n":12,"t":"弟兄们，我们劝你们敬重那在你们中间劳苦的人，就是在主里面治理你们、劝戒你们的；","notes":[]},{"n":13,"t":"又因他们所做的工，用爱心格外尊重他们。你们也要彼此和睦。","notes":[]},{"n":14,"t":"我们又劝弟兄们，要警戒不守规矩的人，勉励灰心的人，扶助软弱的人，也要向众人忍耐。","notes":[]},{"n":15,"t":"你们要谨慎，无论是谁都不可以恶报恶；或是彼此相待，或是待众人，常要追求良善。","notes":[]},{"n":16,"t":"要常常喜乐，","notes":[]},{"n":17,"t":"不住地祷告，","notes":[]},{"n":18,"t":"凡事谢恩；因为这是神在基督耶稣里向你们所定的旨意。","notes":[]},{"n":19,"t":"不要消灭圣灵的感动；","notes":[]},{"n":20,"t":"不要藐视先知的讲论。","notes":[]},{"n":21,"t":"但要凡事察验；善美的要持守，","notes":[]},{"n":22,"t":"各样的恶事要禁戒不做。","notes":[]},{"n":23,"t":"愿赐平安的神亲自使你们全然成圣！又愿你们的灵与魂与身子得蒙保守，在我们主耶稣基督降临的时候，完全无可指摘！","notes":[]},{"n":24,"t":"那召你们的本是信实的，他必成就这事。","notes":[]},{"n":25,"t":"请弟兄们为我们祷告。","notes":[]},{"n":26,"t":"与众弟兄亲嘴问安，务要圣洁。","notes":[]},{"n":27,"t":"我指着主嘱咐你们，要把这信念给众弟兄听。","notes":[]},{"n":28,"t":"愿我主耶稣基督的恩常与你们同在！","notes":[]}]}},"2TH":{"1":{"heading":"问候","verses":[{"n":1,"t":"保罗、西拉、提摩太写信给帖撒罗尼迦、在神—我们的父与主耶稣基督里的教会。","notes":[]},{"n":2,"t":"愿恩惠、平安从父神和主耶稣基督归与你们！","notes":[]},{"n":3,"t":"弟兄们，我们该为你们常常感谢神，这本是合宜的；因你们的信心格外增长，并且你们众人彼此相爱的心也都充足。","notes":[],"heads":["基督再来时的审判"]},{"n":4,"t":"甚至我们在神的各教会里为你们夸口，都因你们在所受的一切逼迫患难中，仍旧存忍耐和信心。","notes":[]},{"n":5,"t":"这正是神公义判断的明证，叫你们可算配得神的国；你们就是为这国受苦。","notes":[]},{"n":6,"t":"神既是公义的，就必将患难报应那加患难给你们的人，","notes":[]},{"n":7,"t":"也必使你们这受患难的人与我们同得平安。那时，主耶稣同他有能力的天使从天上在火焰中显现，","notes":[]},{"n":8,"t":"要报应那不认识神和那不听从我主耶稣福音的人。","notes":[]},{"n":9,"t":"他们要受刑罚，就是永远沉沦，离开主的面和他权能的荣光。","notes":[]},{"n":10,"t":"这正是主降临、要在他圣徒的身上得荣耀、又在一切信的人身上显为希奇的那日子。我们对你们作的见证，你们也信了。","notes":[]},{"n":11,"t":"因此，我们常为你们祷告，愿我们的神看你们配得过所蒙的召，又用大能成就你们一切所羡慕的良善和一切因信心所做的工夫，","notes":[]},{"n":12,"t":"叫我们主耶稣的名在你们身上得荣耀，你们也在他身上得荣耀，都照着我们的神并主耶稣基督的恩。","notes":[]}]},"2":{"heading":"不法的人","verses":[{"n":1,"t":"弟兄们，论到我们主耶稣基督降临和我们到他那里聚集，","notes":[]},{"n":2,"t":"我劝你们：无论有灵、有言语、有冒我名的书信，说主的日子现在到了，不要轻易动心，也不要惊慌。","notes":["现在：或译就"]},{"n":3,"t":"人不拘用什么法子，你们总不要被他诱惑；因为那日子以前，必有离道反教的事，并有那大罪人，就是沉沦之子，显露出来。","notes":[]},{"n":4,"t":"他是抵挡主，高抬自己，超过一切称为神的和一切受人敬拜的，甚至坐在神的殿里，自称是神。","notes":[]},{"n":5,"t":"我还在你们那里的时候，曾把这些事告诉你们，你们不记得吗？","notes":[]},{"n":6,"t":"现在你们也知道，那拦阻他的是什么，是叫他到了的时候才可以显露。","notes":[]},{"n":7,"t":"因为那不法的隐意已经发动，只是现在有一个拦阻的，等到那拦阻的被除去，","notes":[]},{"n":8,"t":"那时这不法的人必显露出来。主耶稣要用口中的气灭绝他，用降临的荣光废掉他。","notes":[]},{"n":9,"t":"这不法的人来，是照撒但的运动，行各样的异能、神迹，和一切虚假的奇事，","notes":[]},{"n":10,"t":"并且在那沉沦的人身上行各样出于不义的诡诈；因他们不领受爱真理的心，使他们得救。","notes":[]},{"n":11,"t":"故此，神就给他们一个生发错误的心，叫他们信从虚谎，","notes":[]},{"n":12,"t":"使一切不信真理、倒喜爱不义的人都被定罪。","notes":[]},{"n":13,"t":"主所爱的弟兄们哪，我们本该常为你们感谢神；因为他从起初拣选了你们，叫你们因信真道，又被圣灵感动，成为圣洁，能以得救。","notes":[],"heads":["被拣选接受救恩"]},{"n":14,"t":"神借我们所传的福音召你们到这地步，好得着我们主耶稣基督的荣光。","notes":[]},{"n":15,"t":"所以，弟兄们，你们要站立得稳，凡所领受的教训，不拘是我们口传的，是信上写的，都要坚守。","notes":[]},{"n":16,"t":"但愿我们主耶稣基督和那爱我们、开恩将永远的安慰并美好的盼望赐给我们的父神，","notes":[]},{"n":17,"t":"安慰你们的心，并且在一切善行善言上坚固你们。","notes":[]}]},"3":{"heading":"请为我们祷告","verses":[{"n":1,"t":"弟兄们，我还有话说：请你们为我们祷告，好叫主的道理快快行开，得着荣耀，正如在你们中间一样，","notes":[]},{"n":2,"t":"也叫我们脱离无理之恶人的手；因为人不都是有信心。","notes":[]},{"n":3,"t":"但主是信实的，要坚固你们，保护你们脱离那恶者。","notes":["或译：脱离凶恶"]},{"n":4,"t":"我们靠主深信，你们现在是遵行我们所吩咐的，后来也必要遵行。","notes":[]},{"n":5,"t":"愿主引导你们的心，叫你们爱神，并学基督的忍耐！","notes":[]},{"n":6,"t":"弟兄们，我们奉主耶稣基督的名吩咐你们，凡有弟兄不按规矩而行，不遵守从我们所受的教训，就当远离他。","notes":[],"heads":["警戒懒惰的人"]},{"n":7,"t":"你们自己原知道应当怎样效法我们。因为我们在你们中间，未尝不按规矩而行，","notes":[]},{"n":8,"t":"也未尝白吃人的饭，倒是辛苦劳碌，昼夜做工，免得叫你们一人受累。","notes":[]},{"n":9,"t":"这并不是因我们没有权柄，乃是要给你们作榜样，叫你们效法我们。","notes":[]},{"n":10,"t":"我们在你们那里的时候，曾吩咐你们说，若有人不肯做工，就不可吃饭。","notes":[]},{"n":11,"t":"因我们听说，在你们中间有人不按规矩而行，什么工都不做，反倒专管闲事。","notes":[]},{"n":12,"t":"我们靠主耶稣基督吩咐、劝戒这样的人，要安静做工，吃自己的饭。","notes":[]},{"n":13,"t":"弟兄们，你们行善不可丧志。","notes":[]},{"n":14,"t":"若有人不听从我们这信上的话，要记下他，不和他交往，叫他自觉羞愧。","notes":[]},{"n":15,"t":"但不要以他为仇人，要劝他如弟兄。","notes":[]},{"n":16,"t":"愿赐平安的主随时随事亲自给你们平安！愿主常与你们众人同在！","notes":[],"heads":["祝福"]},{"n":17,"t":"我—保罗亲笔问你们安。凡我的信都以此为记，我的笔迹就是这样。","notes":[]},{"n":18,"t":"愿我们主耶稣基督的恩常与你们众人同在！","notes":[]}]}},"1TI":{"1":{"heading":"问候","verses":[{"n":1,"t":"奉我们救主神和我们的盼望基督耶稣之命，作基督耶稣使徒的保罗","notes":[]},{"n":2,"t":"写信给那因信主作我真儿子的提摩太。愿恩惠、怜悯、平安从父神和我们主基督耶稣归与你！","notes":[]},{"n":3,"t":"我往马其顿去的时候，曾劝你仍住在以弗所，好嘱咐那几个人不可传异教，","notes":[],"heads":["警告虚伪的道理"]},{"n":4,"t":"也不可听从荒渺无凭的话语和无穷的家谱；这等事只生辩论，并不发明神在信上所立的章程。","notes":[]},{"n":5,"t":"但命令的总归就是爱；这爱是从清洁的心和无亏的良心，无伪的信心生出来的。","notes":[]},{"n":6,"t":"有人偏离这些，反去讲虚浮的话，","notes":[]},{"n":7,"t":"想要作教法师，却不明白自己所讲说的所论定的。","notes":[]},{"n":8,"t":"我们知道律法原是好的，只要人用得合宜；","notes":[]},{"n":9,"t":"因为律法不是为义人设立的，乃是为不法和不服的，不虔诚和犯罪的，不圣洁和恋世俗的，弑父母和杀人的，","notes":[]},{"n":10,"t":"行淫和亲男色的，抢人口和说谎话的，并起假誓的，或是为别样敌正道的事设立的。","notes":[]},{"n":11,"t":"这是照着可称颂之神交托我荣耀福音说的。","notes":[]},{"n":12,"t":"我感谢那给我力量的我们主基督耶稣，因他以我有忠心，派我服事他。","notes":[],"heads":["感谢神的怜悯"]},{"n":13,"t":"我从前是亵渎神的，逼迫人的，侮慢人的；然而我还蒙了怜悯，因我是不信不明白的时候而做的。","notes":[]},{"n":14,"t":"并且我主的恩是格外丰盛，使我在基督耶稣里有信心和爱心。","notes":[]},{"n":15,"t":"「基督耶稣降世，为要拯救罪人。」这话是可信的，是十分可佩服的。在罪人中我是个罪魁。","notes":[]},{"n":16,"t":"然而，我蒙了怜悯，是因耶稣基督要在我这罪魁身上显明他一切的忍耐，给后来信他得永生的人作榜样。","notes":[]},{"n":17,"t":"但愿尊贵、荣耀归与那不能朽坏、不能看见、永世的君王、独一的神，直到永永远远。阿们！","notes":[]},{"n":18,"t":"我儿提摩太啊，我照从前指着你的预言，将这命令交托你，叫你因此可以打那美好的仗。","notes":[]},{"n":19,"t":"常存信心和无亏的良心。有人丢弃良心，就在真道上如同船破坏了一般。","notes":[]},{"n":20,"t":"其中有许米乃和亚历山大；我已经把他们交给撒但，使他们受责罚就不再谤渎了。","notes":[]}]},"2":{"heading":"有关祷告的指示","verses":[{"n":1,"t":"我劝你，第一要为万人恳求、祷告、代求、祝谢；","notes":[]},{"n":2,"t":"为君王和一切在位的，也该如此，使我们可以敬虔、端正、平安无事地度日。","notes":[]},{"n":3,"t":"这是好的，在神我们救主面前可蒙悦纳。","notes":[]},{"n":4,"t":"他愿意万人得救，明白真道。","notes":[]},{"n":5,"t":"因为只有一位神，在神和人中间，只有一位中保，乃是降世为人的基督耶稣；","notes":[]},{"n":6,"t":"他舍自己作万人的赎价，到了时候，这事必证明出来。","notes":[]},{"n":7,"t":"我为此奉派作传道的，作使徒，作外邦人的师傅，教导他们相信，学习真道。我说的是真话，并不是谎言。","notes":[]},{"n":8,"t":"我愿男人无忿怒，无争论，举起圣洁的手，随处祷告；","notes":["或译：疑惑"]},{"n":9,"t":"又愿女人廉耻、自守，以正派衣裳为妆饰，不以编发、黄金、珍珠，和贵价的衣裳为妆饰，","notes":[]},{"n":10,"t":"只要有善行，这才与自称是敬神的女人相宜。","notes":[]},{"n":11,"t":"女人要沉静学道，一味地顺服。","notes":[]},{"n":12,"t":"我不许女人讲道，也不许她辖管男人，只要沉静。","notes":[]},{"n":13,"t":"因为先造的是亚当，后造的是夏娃，","notes":[]},{"n":14,"t":"且不是亚当被引诱，乃是女人被引诱，陷在罪里。","notes":[]},{"n":15,"t":"然而，女人若常存信心、爱心，又圣洁自守，就必在生产上得救。","notes":[]}]},"3":{"heading":"监督的资格","verses":[{"n":1,"t":"「人若想要得监督的职分，就是羡慕善工。」这话是可信的。","notes":[]},{"n":2,"t":"作监督的，必须无可指责，只作一个妇人的丈夫，有节制，自守，端正，乐意接待远人，善于教导；","notes":[]},{"n":3,"t":"不因酒滋事，不打人，只要温和，不争竞，不贪财；","notes":[]},{"n":4,"t":"好好管理自己的家，使儿女凡事端庄顺服。","notes":["或译：端端庄庄地使儿女顺服"]},{"n":5,"t":"人若不知道管理自己的家，焉能照管神的教会呢？","notes":[]},{"n":6,"t":"初入教的不可作监督，恐怕他自高自大，就落在魔鬼所受的刑罚里。","notes":[]},{"n":7,"t":"监督也必须在教外有好名声，恐怕被人毁谤，落在魔鬼的网罗里。","notes":[]},{"n":8,"t":"作执事的，也是如此：必须端庄，不一口两舌，不好喝酒，不贪不义之财；","notes":[],"heads":["执事的资格"]},{"n":9,"t":"要存清洁的良心，固守真道的奥秘。","notes":[]},{"n":10,"t":"这等人也要先受试验，若没有可责之处，然后叫他们作执事。","notes":[]},{"n":11,"t":"女执事也是如此：必须端庄，不说谗言，有节制，凡事忠心。","notes":["原文是女人"]},{"n":12,"t":"执事只要作一个妇人的丈夫，好好管理儿女和自己的家。","notes":[]},{"n":13,"t":"因为善作执事的，自己就得到美好的地步，并且在基督耶稣里的真道上大有胆量。","notes":[]},{"n":14,"t":"我指望快到你那里去，所以先将这些事写给你。","notes":[],"heads":["敬虔的奥秘"]},{"n":15,"t":"倘若我耽延日久，你也可以知道在神的家中当怎样行。这家就是永生神的教会，真理的柱石和根基。","notes":[]},{"n":16,"t":"大哉，敬虔的奥秘，无人不以为然！就是神在肉身显现，被圣灵称义，被天使看见，被传于外邦，被世人信服，被接在荣耀里。","notes":["或译：在灵性称义"]}]},"4":{"heading":"预言有人离弃真道","verses":[{"n":1,"t":"圣灵明说，在后来的时候，必有人离弃真道，听从那引诱人的邪灵和鬼魔的道理。","notes":[]},{"n":2,"t":"这是因为说谎之人的假冒；这等人的良心如同被热铁烙惯了一般。","notes":[]},{"n":3,"t":"他们禁止嫁娶，又禁戒食物，就是神所造、叫那信而明白真道的人感谢着领受的。","notes":["或译：又叫人戒荤"]},{"n":4,"t":"凡神所造的物都是好的，若感谢着领受，就没有一样可弃的，","notes":[]},{"n":5,"t":"都因神的道和人的祈求成为圣洁了。","notes":[]},{"n":6,"t":"你若将这些事提醒弟兄们，便是基督耶稣的好执事，在真道的话语和你向来所服从的善道上得了教育。","notes":[],"heads":["基督耶稣的好执事"]},{"n":7,"t":"只是要弃绝那世俗的言语和老妇荒谬的话，在敬虔上操练自己。","notes":[]},{"n":8,"t":"「操练身体，益处还少；惟独敬虔，凡事都有益处，因有今生和来生的应许。」","notes":[]},{"n":9,"t":"这话是可信的，是十分可佩服的。","notes":[]},{"n":10,"t":"我们劳苦努力，正是为此，因我们的指望在乎永生的神；他是万人的救主，更是信徒的救主。","notes":[]},{"n":11,"t":"这些事，你要吩咐人，也要教导人。","notes":[]},{"n":12,"t":"不可叫人小看你年轻，总要在言语、行为、爱心、信心、清洁上，都作信徒的榜样。","notes":[]},{"n":13,"t":"你要以宣读、劝勉、教导为念，直等到我来。","notes":[]},{"n":14,"t":"你不要轻忽所得的恩赐，就是从前借着预言、在众长老按手的时候赐给你的。","notes":[]},{"n":15,"t":"这些事你要殷勤去做，并要在此专心，使众人看出你的长进来。","notes":[]},{"n":16,"t":"你要谨慎自己和自己的教训，要在这些事上恒心；因为这样行，又能救自己，又能救听你的人。","notes":[]}]},"5":{"heading":"对别人的本分","verses":[{"n":1,"t":"不可严责老年人，只要劝他如同父亲；劝少年人如同弟兄；","notes":[]},{"n":2,"t":"劝老年妇女如同母亲；劝少年妇女如同姊妹；总要清清洁洁的。","notes":[]},{"n":3,"t":"要尊敬那真为寡妇的。","notes":[]},{"n":4,"t":"若寡妇有儿女，或有孙子孙女，便叫他们先在自己家中学着行孝，报答亲恩，因为这在神面前是可悦纳的。","notes":[]},{"n":5,"t":"那独居无靠、真为寡妇的，是仰赖神，昼夜不住地祈求祷告。","notes":[]},{"n":6,"t":"但那好宴乐的寡妇正活着的时候也是死的。","notes":[]},{"n":7,"t":"这些事你要嘱咐她们，叫她们无可指责。","notes":[]},{"n":8,"t":"人若不看顾亲属，就是背了真道，比不信的人还不好，不看顾自己家里的人，更是如此。","notes":[]},{"n":9,"t":"寡妇记在册子上，必须年纪到六十岁，从来只作一个丈夫的妻子，","notes":[]},{"n":10,"t":"又有行善的名声，就如养育儿女，接待远人，洗圣徒的脚，救济遭难的人，竭力行各样善事。","notes":[]},{"n":11,"t":"至于年轻的寡妇，就可以辞她；因为她们的情欲发动，违背基督的时候就想要嫁人。","notes":[]},{"n":12,"t":"她们被定罪，是因废弃了当初所许的愿；","notes":[]},{"n":13,"t":"并且她们又习惯懒惰，挨家闲游；不但是懒惰，又说长道短，好管闲事，说些不当说的话。","notes":[]},{"n":14,"t":"所以我愿意年轻的寡妇嫁人，生养儿女，治理家务，不给敌人辱骂的把柄。","notes":[]},{"n":15,"t":"因为已经有转去随从撒但的。","notes":[]},{"n":16,"t":"信主的妇女，若家中有寡妇，自己就当救济她们，不可累着教会，好使教会能救济那真无倚靠的寡妇。","notes":[]},{"n":17,"t":"那善于管理教会的长老，当以为配受加倍的敬奉；那劳苦传道教导人的，更当如此。","notes":[]},{"n":18,"t":"因为经上说：「牛在场上踹谷的时候，不可笼住它的嘴」；又说：「工人得工价是应当的。」","notes":[]},{"n":19,"t":"控告长老的呈子，非有两三个见证就不要收。","notes":[]},{"n":20,"t":"犯罪的人，当在众人面前责备他，叫其余的人也可以惧怕。","notes":[]},{"n":21,"t":"我在神和基督耶稣并蒙拣选的天使面前嘱咐你：要遵守这些话，不可存成见，行事也不可有偏心。","notes":[]},{"n":22,"t":"给人行按手的礼，不可急促；不要在别人的罪上有分，要保守自己清洁。","notes":[]},{"n":23,"t":"因你胃口不清，屡次患病，再不要照常喝水，可以稍微用点酒。","notes":[]},{"n":24,"t":"有些人的罪是明显的，如同先到审判案前；有些人的罪是随后跟了去的。","notes":[]},{"n":25,"t":"这样，善行也有明显的，那不明显的也不能隐藏。","notes":[]}]},"6":{"heading":"假道理和真财富","verses":[{"n":1,"t":"凡在轭下作仆人的，当以自己主人配受十分的恭敬，免得神的名和道理被人亵渎。","notes":[]},{"n":2,"t":"仆人有信道的主人，不可因为与他是弟兄就轻看他；更要加意服事他；因为得服事之益处的，是信道蒙爱的。你要以此教训人，劝勉人。","notes":[]},{"n":3,"t":"若有人传异教，不服从我们主耶稣基督纯正的话与那合乎敬虔的道理，","notes":[]},{"n":4,"t":"他是自高自大，一无所知，专好问难，争辩言词，从此就生出嫉妒、纷争、毁谤、妄疑，","notes":[]},{"n":5,"t":"并那坏了心术、失丧真理之人的争竞。他们以敬虔为得利的门路。","notes":[]},{"n":6,"t":"然而，敬虔加上知足的心便是大利了；","notes":[]},{"n":7,"t":"因为我们没有带什么到世上来，也不能带什么去。","notes":[]},{"n":8,"t":"只要有衣有食，就当知足。","notes":[]},{"n":9,"t":"但那些想要发财的人，就陷在迷惑、落在网罗和许多无知有害的私欲里，叫人沉在败坏和灭亡中。","notes":[]},{"n":10,"t":"贪财是万恶之根。有人贪恋钱财，就被引诱离了真道，用许多愁苦把自己刺透了。","notes":[]},{"n":11,"t":"但你这属神的人要逃避这些事，追求公义、敬虔、信心、爱心、忍耐、温柔。","notes":[],"heads":["美好的仗"]},{"n":12,"t":"你要为真道打那美好的仗，持定永生。你为此被召，也在许多见证人面前，已经作了那美好的见证。","notes":[]},{"n":13,"t":"我在叫万物生活的神面前，并在向本丢·彼拉多作过那美好见证的基督耶稣面前嘱咐你：","notes":[]},{"n":14,"t":"要守这命令，毫不玷污，无可指责，直到我们的主耶稣基督显现。","notes":[]},{"n":15,"t":"到了日期，那可称颂、独有权能的万王之王、万主之主，","notes":[]},{"n":16,"t":"就是那独一不死、住在人不能靠近的光里，是人未曾看见、也是不能看见的，要将他显明出来。但愿尊贵和永远的权能都归给他。阿们！","notes":[]},{"n":17,"t":"你要嘱咐那些今世富足的人，不要自高，也不要倚靠无定的钱财；只要倚靠那厚赐百物给我们享受的神。","notes":[]},{"n":18,"t":"又要嘱咐他们行善，在好事上富足，甘心施舍，乐意供给人，","notes":["或译：体贴"]},{"n":19,"t":"为自己积成美好的根基，预备将来，叫他们持定那真正的生命。","notes":[]},{"n":20,"t":"提摩太啊，你要保守所托付你的，躲避世俗的虚谈和那敌真道、似是而非的学问。","notes":[]},{"n":21,"t":"已经有人自称有这学问，就偏离了真道。愿恩惠常与你们同在！","notes":[]}]}},"2TI":{"1":{"heading":"问候","verses":[{"n":1,"t":"奉神旨意，照着在基督耶稣里生命的应许，作基督耶稣使徒的保罗","notes":[]},{"n":2,"t":"写信给我亲爱的儿子提摩太。愿恩惠、怜悯、平安从父神和我们主基督耶稣归与你！","notes":[]},{"n":3,"t":"我感谢神，就是我接续祖先用清洁的良心所事奉的神。祈祷的时候，不住的想念你，","notes":[],"heads":["忠于福音"]},{"n":4,"t":"记念你的眼泪，昼夜切切地想要见你，好叫我满心快乐。","notes":[]},{"n":5,"t":"想到你心里无伪之信，这信是先在你外祖母罗以和你母亲友妮基心里的，我深信也在你的心里。","notes":[]},{"n":6,"t":"为此我提醒你，使你将神借我按手所给你的恩赐再如火挑旺起来。","notes":[]},{"n":7,"t":"因为神赐给我们，不是胆怯的心，乃是刚强、仁爱、谨守的心。","notes":[]},{"n":8,"t":"你不要以给我们的主作见证为耻，也不要以我这为主被囚的为耻；总要按神的能力，与我为福音同受苦难。","notes":[]},{"n":9,"t":"神救了我们，以圣召召我们，不是按我们的行为，乃是按他的旨意和恩典；这恩典是万古之先，在基督耶稣里赐给我们的，","notes":[]},{"n":10,"t":"但如今借着我们救主基督耶稣的显现才表明出来了。他已经把死废去，借着福音，将不能坏的生命彰显出来。","notes":[]},{"n":11,"t":"我为这福音奉派作传道的，作使徒，作师傅。","notes":[]},{"n":12,"t":"为这缘故，我也受这些苦难。然而我不以为耻；因为知道我所信的是谁，也深信他能保全我所交付他的，直到那日。","notes":["或译：他所交托我的"]},{"n":13,"t":"你从我听的那纯正话语的规模，要用在基督耶稣里的信心和爱心，常常守着。","notes":[]},{"n":14,"t":"从前所交托你的善道，你要靠着那住在我们里面的圣灵牢牢地守着。","notes":[]},{"n":15,"t":"凡在亚细亚的人都离弃我，这是你知道的，其中有腓吉路和黑摩其尼。","notes":[]},{"n":16,"t":"愿主怜悯阿尼色弗一家的人；因他屡次使我畅快，不以我的锁链为耻，","notes":[]},{"n":17,"t":"反倒在罗马的时候，殷勤地找我，并且找着了。","notes":[]},{"n":18,"t":"愿主使他在那日得主的怜悯。他在以弗所怎样多多地服事我，是你明明知道的。","notes":[]}]},"2":{"heading":"基督耶稣的精兵","verses":[{"n":1,"t":"我儿啊，你要在基督耶稣的恩典上刚强起来。","notes":[]},{"n":2,"t":"你在许多见证人面前听见我所教训的，也要交托那忠心能教导别人的人。","notes":[]},{"n":3,"t":"你要和我同受苦难，好像基督耶稣的精兵。","notes":[]},{"n":4,"t":"凡在军中当兵的，不将世务缠身，好叫那招他当兵的人喜悦。","notes":[]},{"n":5,"t":"人若在场上比武，非按规矩，就不能得冠冕。","notes":[]},{"n":6,"t":"劳力的农夫理当先得粮食。","notes":[]},{"n":7,"t":"我所说的话，你要思想，因为凡事主必给你聪明。","notes":[]},{"n":8,"t":"你要记念耶稣基督乃是大卫的后裔，他从死里复活，正合乎我所传的福音。","notes":[]},{"n":9,"t":"我为这福音受苦难，甚至被捆绑，像犯人一样。然而神的道却不被捆绑。","notes":[]},{"n":10,"t":"所以，我为选民凡事忍耐，叫他们也可以得着那在基督耶稣里的救恩和永远的荣耀。","notes":[]},{"n":11,"t":"有可信的话说：我们若与基督同死，也必与他同活；","notes":[]},{"n":12,"t":"我们若能忍耐，也必和他一同作王。我们若不认他，他也必不认我们；","notes":[]},{"n":13,"t":"我们纵然失信，他仍是可信的，因为他不能背乎自己。","notes":[]},{"n":14,"t":"你要使众人回想这些事，在主面前嘱咐他们：不可为言语争辩；这是没有益处的，只能败坏听见的人。","notes":[],"heads":["无愧的工人"]},{"n":15,"t":"你当竭力在神面前得蒙喜悦，作无愧的工人，按着正意分解真理的道。","notes":[]},{"n":16,"t":"但要远避世俗的虚谈，因为这等人必进到更不敬虔的地步。","notes":[]},{"n":17,"t":"他们的话如同毒疮，越烂越大；其中有许米乃和腓理徒，","notes":[]},{"n":18,"t":"他们偏离了真道，说复活的事已过，就败坏好些人的信心。","notes":[]},{"n":19,"t":"然而，神坚固的根基立住了；上面有这印记说：「主认识谁是他的人」；又说：「凡称呼主名的人总要离开不义。」","notes":[]},{"n":20,"t":"在大户人家，不但有金器银器，也有木器瓦器；有作为贵重的，有作为卑贱的。","notes":[]},{"n":21,"t":"人若自洁，脱离卑贱的事，就必作贵重的器皿，成为圣洁，合乎主用，预备行各样的善事。","notes":[]},{"n":22,"t":"你要逃避少年的私欲，同那清心祷告主的人追求公义、信德、仁爱、和平。","notes":[]},{"n":23,"t":"惟有那愚拙无学问的辩论，总要弃绝，因为知道这等事是起争竞的。","notes":[]},{"n":24,"t":"然而主的仆人不可争竞，只要温温和和地待众人，善于教导，存心忍耐，","notes":[]},{"n":25,"t":"用温柔劝戒那抵挡的人；或者神给他们悔改的心，可以明白真道，","notes":[]},{"n":26,"t":"叫他们这已经被魔鬼任意掳去的，可以醒悟，脱离他的网罗。","notes":[]}]},"3":{"heading":"末世的人性","verses":[{"n":1,"t":"你该知道，末世必有危险的日子来到。","notes":[]},{"n":2,"t":"因为那时，人要专顾自己，贪爱钱财，自夸，狂傲，谤讟，违背父母，忘恩负义，心不圣洁，","notes":[]},{"n":3,"t":"无亲情，不解怨，好说谗言，不能自约，性情凶暴，不爱良善，","notes":[]},{"n":4,"t":"卖主卖友，任意妄为，自高自大，爱宴乐，不爱神，","notes":[]},{"n":5,"t":"有敬虔的外貌，却背了敬虔的实意；这等人你要躲开。","notes":[]},{"n":6,"t":"那偷进人家、牢笼无知妇女的，正是这等人。这些妇女担负罪恶，被各样的私欲引诱，","notes":[]},{"n":7,"t":"常常学习，终久不能明白真道。","notes":[]},{"n":8,"t":"从前雅尼和佯庇怎样敌挡摩西，这等人也怎样敌挡真道。他们的心地坏了，在真道上是可废弃的。","notes":[]},{"n":9,"t":"然而他们不能再这样敌挡；因为他们的愚昧必在众人面前显露出来，像那二人一样。","notes":[]},{"n":10,"t":"但你已经服从了我的教训、品行、志向、信心、宽容、爱心、忍耐，","notes":[],"heads":["对提摩太的最后指示"]},{"n":11,"t":"以及我在安提阿、以哥念、路司得所遭遇的逼迫、苦难。我所忍受是何等的逼迫；但从这一切苦难中，主都把我救出来了。","notes":[]},{"n":12,"t":"不但如此，凡立志在基督耶稣里敬虔度日的也都要受逼迫。","notes":[]},{"n":13,"t":"只是作恶的和迷惑人的，必越久越恶，他欺哄人，也被人欺哄。","notes":[]},{"n":14,"t":"但你所学习的，所确信的，要存在心里；因为你知道是跟谁学的，","notes":[]},{"n":15,"t":"并且知道你是从小明白圣经，这圣经能使你因信基督耶稣，有得救的智慧。","notes":[]},{"n":16,"t":"圣经都是神所默示的，于教训、督责、使人归正、教导人学义都是有益的，","notes":["或译：凡神所默示的圣经"]},{"n":17,"t":"叫属神的人得以完全，预备行各样的善事。","notes":[]}]},"4":{"heading":"私事的嘱咐","verses":[{"n":1,"t":"我在神面前，并在将来审判活人死人的基督耶稣面前，凭着他的显现和他的国度嘱咐你：","notes":[]},{"n":2,"t":"务要传道，无论得时不得时总要专心，并用百般的忍耐、各样的教训责备人，警戒人，劝勉人。","notes":[]},{"n":3,"t":"因为时候要到，人必厌烦纯正的道理，耳朵发痒，就随从自己的情欲，增添好些师傅，","notes":[]},{"n":4,"t":"并且掩耳不听真道，偏向荒渺的言语。","notes":[]},{"n":5,"t":"你却要凡事谨慎，忍受苦难，做传道的工夫，尽你的职分。","notes":[]},{"n":6,"t":"我现在被浇奠，我离世的时候到了。","notes":[]},{"n":7,"t":"那美好的仗我已经打过了，当跑的路我已经跑尽了，所信的道我已经守住了。","notes":[]},{"n":8,"t":"从此以后，有公义的冠冕为我存留，就是按着公义审判的主到了那日要赐给我的；不但赐给我，也赐给凡爱慕他显现的人。","notes":[]},{"n":9,"t":"你要赶紧地到我这里来。","notes":[]},{"n":10,"t":"因为底马贪爱现今的世界，就离弃我往帖撒罗尼迦去了；革勒士往加拉太去；提多往挞马太去；","notes":[]},{"n":11,"t":"独有路加在我这里。你来的时候，要把马可带来，因为他在传道的事上于我有益处。","notes":["或译：服事我"]},{"n":12,"t":"我已经打发推基古往以弗所去。","notes":[]},{"n":13,"t":"我在特罗亚留于加布的那件外衣，你来的时候可以带来，那些书也要带来，更要紧的是那些皮卷。","notes":[]},{"n":14,"t":"铜匠亚历山大多多地害我；主必照他所行的报应他。","notes":[]},{"n":15,"t":"你也要防备他，因为他极力敌挡了我们的话。","notes":[]},{"n":16,"t":"我初次申诉，没有人前来帮助，竟都离弃我；但愿这罪不归与他们。","notes":[]},{"n":17,"t":"惟有主站在我旁边，加给我力量，使福音被我尽都传明，叫外邦人都听见；我也从狮子口里被救出来。","notes":[]},{"n":18,"t":"主必救我脱离诸般的凶恶，也必救我进他的天国。愿荣耀归给他，直到永永远远。阿们。","notes":[]},{"n":19,"t":"问百基拉、亚居拉，和阿尼色弗一家的人安。","notes":[],"heads":["问候与祝福"]},{"n":20,"t":"以拉都在哥林多住下了。特罗非摩病了，我就留他在米利都。","notes":[]},{"n":21,"t":"你要赶紧在冬天以前到我这里来。有友布罗、布田、利奴、革老底亚，和众弟兄都问你安。","notes":[]},{"n":22,"t":"愿主与你的灵同在！愿恩惠常与你们同在！","notes":[]}]}},"TIT":{"1":{"heading":"问候","verses":[{"n":1,"t":"神的仆人，耶稣基督的使徒保罗，凭着神选民的信心与敬虔真理的知识，","notes":[]},{"n":2,"t":"盼望那无谎言的神在万古之先所应许的永生，","notes":[]},{"n":3,"t":"到了日期，借着传扬的工夫把他的道显明了；这传扬的责任是按着神—我们救主的命令交托了我。","notes":[]},{"n":4,"t":"现在写信给提多，就是照着我们共信之道作我真儿子的。愿恩惠、平安从父神和我们的救主基督耶稣归与你！","notes":[]},{"n":5,"t":"我从前留你在克里特，是要你将那没有办完的事都办整齐了，又照我所吩咐你的，在各城设立长老。","notes":[],"heads":["提多在克里特的工作"]},{"n":6,"t":"若有无可指责的人，只作一个妇人的丈夫，儿女也是信主的，没有人告他们是放荡不服约束的，就可以设立。","notes":[]},{"n":7,"t":"监督既是神的管家，必须无可指责，不任性，不暴躁，不因酒滋事，不打人，不贪无义之财；","notes":[]},{"n":8,"t":"乐意接待远人，好善，庄重，公平，圣洁自持；","notes":[]},{"n":9,"t":"坚守所教真实的道理，就能将纯正的教训劝化人，又能把争辩的人驳倒了。","notes":[]},{"n":10,"t":"因为有许多人不服约束，说虚空话欺哄人；那奉割礼的更是这样。","notes":[]},{"n":11,"t":"这些人的口总要堵住。他们因贪不义之财，将不该教导的教导人，败坏人的全家。","notes":[]},{"n":12,"t":"有克里特人中的一个本地先知说：「克里特人常说谎话，乃是恶兽，又馋又懒。」","notes":[]},{"n":13,"t":"这个见证是真的。所以，你要严严地责备他们，使他们在真道上纯全无疵，","notes":[]},{"n":14,"t":"不听犹太人荒谬的言语和离弃真道之人的诫命。","notes":[]},{"n":15,"t":"在洁净的人，凡物都洁净；在污秽不信的人，什么都不洁净，连心地和天良也都污秽了。","notes":[]},{"n":16,"t":"他们说是认识神，行事却和他相背；本是可憎恶的，是悖逆的，在各样善事上是可废弃的。","notes":[]}]},"2":{"heading":"纯正的道理","verses":[{"n":1,"t":"但你所讲的总要合乎那纯正的道理。","notes":[]},{"n":2,"t":"劝老年人要有节制、端庄、自守，在信心、爱心、忍耐上都要纯全无疵。","notes":[]},{"n":3,"t":"又劝老年妇人，举止行动要恭敬，不说谗言，不给酒作奴仆，用善道教训人，","notes":[]},{"n":4,"t":"好指教少年妇人，爱丈夫，爱儿女，","notes":[]},{"n":5,"t":"谨守，贞洁，料理家务，待人有恩，顺服自己的丈夫，免得神的道理被毁谤。","notes":[]},{"n":6,"t":"又劝少年人要谨守。","notes":[]},{"n":7,"t":"你自己凡事要显出善行的榜样；在教训上要正直、端庄，","notes":[]},{"n":8,"t":"言语纯全，无可指责，叫那反对的人，既无处可说我们的不是，便自觉羞愧。","notes":[]},{"n":9,"t":"劝仆人要顺服自己的主人，凡事讨他的喜欢，不可顶撞他，","notes":[]},{"n":10,"t":"不可私拿东西，要显为忠诚，以致凡事尊荣我们救主—神的道。","notes":[]},{"n":11,"t":"因为神救众人的恩典已经显明出来，","notes":[]},{"n":12,"t":"教训我们除去不敬虔的心和世俗的情欲，在今世自守、公义、敬虔度日，","notes":[]},{"n":13,"t":"等候所盼望的福，并等候至大的神和我们救主耶稣基督的荣耀显现。","notes":["或译：神—我们"]},{"n":14,"t":"他为我们舍了自己，要赎我们脱离一切罪恶，又洁净我们，特作自己的子民，热心为善。","notes":[]},{"n":15,"t":"这些事你要讲明，劝戒人，用各等权柄责备人；不可叫人轻看你。","notes":[]}]},"3":{"heading":"热心行善","verses":[{"n":1,"t":"你要提醒众人，叫他们顺服作官的、掌权的，遵他的命，预备行各样的善事。","notes":[]},{"n":2,"t":"不要毁谤，不要争竞，总要和平，向众人大显温柔。","notes":[]},{"n":3,"t":"我们从前也是无知、悖逆、受迷惑、服事各样私欲，和宴乐，常存恶毒嫉妒的心，是可恨的，又是彼此相恨。","notes":["或译：阴毒"]},{"n":4,"t":"但到了神—我们救主的恩慈和他向人所施的慈爱显明的时候，","notes":[]},{"n":5,"t":"他便救了我们；并不是因我们自己所行的义，乃是照他的怜悯，借着重生的洗和圣灵的更新。","notes":[]},{"n":6,"t":"圣灵就是神借着耶稣基督—我们救主厚厚浇灌在我们身上的，","notes":[]},{"n":7,"t":"好叫我们因他的恩得称为义，可以凭着永生的盼望成为后嗣。","notes":["或译：可以凭着盼望承受永生"]},{"n":8,"t":"这话是可信的。我也愿你把这些事切切实实地讲明，使那些已信神的人留心做正经事业。这都是美事，并且与人有益。","notes":["或译：留心行善"]},{"n":9,"t":"要远避无知的辩论和家谱的空谈，以及纷争，并因律法而起的争竞，因为这都是虚妄无益的。","notes":[]},{"n":10,"t":"分门结党的人，警戒过一两次，就要弃绝他。","notes":[]},{"n":11,"t":"因为知道这等人已经背道，犯了罪，自己明知不是，还是去做。","notes":[]},{"n":12,"t":"我打发亚提马或是推基古到你那里去的时候，你要赶紧往尼哥坡里去见我，因为我已经定意在那里过冬。","notes":[],"heads":["个人的指示和问安"]},{"n":13,"t":"你要赶紧给律师西纳和亚波罗送行，叫他们没有缺乏。","notes":[]},{"n":14,"t":"并且我们的人要学习正经事业，预备所需用的，免得不结果子。","notes":["或译：要学习行善"]},{"n":15,"t":"同我在一处的人都问你安。请代问那些因有信心爱我们的人安。愿恩惠常与你们众人同在！","notes":[]}]}},"PHM":{"1":{"heading":"问候","verses":[{"n":1,"t":"为基督耶稣被囚的保罗，同兄弟提摩太写信给我们所亲爱的同工腓利门，","notes":[]},{"n":2,"t":"和妹子亚腓亚并与我们同当兵的亚基布，以及在你家的教会。","notes":[]},{"n":3,"t":"愿恩惠、平安从神我们的父和主耶稣基督归与你们！","notes":[]},{"n":4,"t":"我祷告的时候提到你，常为你感谢我的神；","notes":[],"heads":["腓利门的爱心和信心"]},{"n":5,"t":"因听说你的爱心并你向主耶稣和众圣徒的信心。","notes":["或译：因听说你向主耶稣和众圣徒有爱心有信心"]},{"n":6,"t":"愿你与人所同有的信心显出功效，使人知道你们各样善事都是为基督做的。","notes":[]},{"n":7,"t":"兄弟啊，我为你的爱心，大有快乐，大得安慰，因众圣徒的心从你得了畅快。","notes":[]},{"n":8,"t":"我虽然靠着基督能放胆吩咐你合宜的事，","notes":[],"heads":["保罗为阿尼西谋请求"]},{"n":9,"t":"然而像我这有年纪的保罗，现在又是为基督耶稣被囚的，宁可凭着爱心求你，","notes":[]},{"n":10,"t":"就是为我在捆锁中所生的儿子阿尼西谋求你。","notes":["就是有益处的意思"]},{"n":11,"t":"他从前与你没有益处，但如今与你我都有益处。","notes":[]},{"n":12,"t":"我现在打发他亲自回你那里去；他是我心上的人。","notes":[]},{"n":13,"t":"我本来有意将他留下，在我为福音所受的捆锁中替你伺候我。","notes":[]},{"n":14,"t":"但不知道你的意思，我就不愿意这样行，叫你的善行不是出于勉强，乃是出于甘心。","notes":[]},{"n":15,"t":"他暂时离开你，或者是叫你永远得着他，","notes":[]},{"n":16,"t":"不再是奴仆，乃是高过奴仆，是亲爱的兄弟。在我实在是如此，何况在你呢！这也不拘是按肉体说，是按主说。","notes":[]},{"n":17,"t":"你若以我为同伴，就收纳他，如同收纳我一样。","notes":[]},{"n":18,"t":"他若亏负你，或欠你什么，都归在我的帐上；","notes":[]},{"n":19,"t":"我必偿还，这是我—保罗亲笔写的。我并不用对你说，连你自己也是亏欠于我。","notes":[]},{"n":20,"t":"兄弟啊，望你使我在主里因你得快乐，并望你使我的心在基督里得畅快。","notes":["或译：益处"]},{"n":21,"t":"我写信给你，深信你必顺服，知道你所要行的必过于我所说的。","notes":[]},{"n":22,"t":"此外你还要给我预备住处；因为我盼望借着你们的祷告，必蒙恩到你们那里去。","notes":[]},{"n":23,"t":"为基督耶稣与我同坐监的以巴弗问你安。","notes":[],"heads":["最后的问安"]},{"n":24,"t":"与我同工的马可、亚里达古、底马、路加也都问你安。","notes":[]},{"n":25,"t":"愿我们主耶稣基督的恩常在你的心里。阿们！","notes":[]}]}},"HEB":{"1":{"heading":"神借着他儿子说话","verses":[{"n":1,"t":"神既在古时借着众先知多次多方地晓谕列祖，","notes":[]},{"n":2,"t":"就在这末世借着他儿子晓谕我们；又早已立他为承受万有的，也曾借着他创造诸世界。","notes":[]},{"n":3,"t":"他是神荣耀所发的光辉，是神本体的真像，常用他权能的命令托住万有。他洗净了人的罪，就坐在高天至大者的右边。","notes":[]},{"n":4,"t":"他所承受的名，既比天使的名更尊贵，就远超过天使。","notes":[]},{"n":5,"t":"所有的天使，神从来对哪一个说：你是我的儿子，我今日生你？又指着哪一个说：我要作他的父，他要作我的子？","notes":[],"heads":["儿子远超过天使"]},{"n":6,"t":"再者，神使长子到世上来的时候，就说：神的使者都要拜他。","notes":["或译：神再使长子到世上来的时候"]},{"n":7,"t":"论到使者，又说：神以风为使者，以火焰为仆役；","notes":[]},{"n":8,"t":"论到子却说：神啊，你的宝座是永永远远的；你的国权是正直的。","notes":[]},{"n":9,"t":"你喜爱公义，恨恶罪恶；所以神，就是你的神，用喜乐油膏你，胜过膏你的同伴；","notes":[]},{"n":10,"t":"又说：主啊，你起初立了地的根基；天也是你手所造的。","notes":[]},{"n":11,"t":"天地都要灭没，你却要长存。天地都要像衣服渐渐旧了；","notes":[]},{"n":12,"t":"你要将天地卷起来，像一件外衣，天地就都改变了。惟有你永不改变；你的年数没有穷尽。","notes":[]},{"n":13,"t":"所有的天使，神从来对哪一个说：你坐在我的右边，等我使你仇敌作你的脚凳？","notes":[]},{"n":14,"t":"天使岂不都是服役的灵、奉差遣为那将要承受救恩的人效力吗？","notes":[]}]},"2":{"heading":"这么大的救恩","verses":[{"n":1,"t":"所以，我们当越发郑重所听见的道理，恐怕我们随流失去。","notes":[]},{"n":2,"t":"那借着天使所传的话既是确定的；凡干犯悖逆的都受了该受的报应。","notes":[]},{"n":3,"t":"我们若忽略这么大的救恩，怎能逃罪呢？这救恩起先是主亲自讲的，后来是听见的人给我们证实了。","notes":[]},{"n":4,"t":"神又按自己的旨意，用神迹、奇事和百般的异能，并圣灵的恩赐，同他们作见证。","notes":[]},{"n":5,"t":"我们所说将来的世界，神原没有交给天使管辖。","notes":[],"heads":["救恩的元帅"]},{"n":6,"t":"但有人在经上某处证明说：人算什么，你竟顾念他？世人算什么，你竟眷顾他？","notes":[]},{"n":7,"t":"你叫他比天使微小一点，赐他荣耀尊贵为冠冕，并将你手所造的都派他管理，","notes":["或译：你叫他暂时比天使小"]},{"n":8,"t":"叫万物都服在他的脚下。既叫万物都服他，就没有剩下一样不服他的。只是如今我们还不见万物都服他。","notes":[]},{"n":9,"t":"惟独见那成为比天使小一点的耶稣；因为受死的苦，就得了尊贵荣耀为冠冕，叫他因着神的恩，为人人尝了死味。","notes":["或译：惟独见耶稣暂时比天使小"]},{"n":10,"t":"原来那为万物所属、为万物所本的，要领许多的儿子进荣耀里去，使救他们的元帅，因受苦难得以完全，本是合宜的。","notes":[]},{"n":11,"t":"因那使人成圣的和那些得以成圣的，都是出于一。所以，他称他们为弟兄也不以为耻，","notes":[]},{"n":12,"t":"说：我要将你的名传与我的弟兄，在会中我要颂扬你；","notes":[]},{"n":13,"t":"又说：我要倚赖他；又说：看哪，我与神所给我的儿女。","notes":[]},{"n":14,"t":"儿女既同有血肉之体，他也照样亲自成了血肉之体，特要借着死败坏那掌死权的，就是魔鬼，","notes":[]},{"n":15,"t":"并要释放那些一生因怕死而为奴仆的人。","notes":[]},{"n":16,"t":"他并不救拔天使，乃是救拔亚伯拉罕的后裔。","notes":[]},{"n":17,"t":"所以，他凡事该与他的弟兄相同，为要在神的事上成为慈悲忠信的大祭司，为百姓的罪献上挽回祭。","notes":[]},{"n":18,"t":"他自己既然被试探而受苦，就能搭救被试探的人。","notes":[]}]},"3":{"heading":"耶稣超越摩西","verses":[{"n":1,"t":"同蒙天召的圣洁弟兄啊，你们应当思想我们所认为使者、为大祭司的耶稣。","notes":[]},{"n":2,"t":"他为那设立他的尽忠，如同摩西在神的全家尽忠一样。","notes":[]},{"n":3,"t":"他比摩西算是更配多得荣耀，好像建造房屋的比房屋更尊荣；","notes":[]},{"n":4,"t":"因为房屋都必有人建造，但建造万物的就是神。","notes":[]},{"n":5,"t":"摩西为仆人，在神的全家诚然尽忠，为要证明将来必传说的事。","notes":[]},{"n":6,"t":"但基督为儿子，治理神的家；我们若将可夸的盼望和胆量坚持到底，便是他的家了。","notes":[]},{"n":7,"t":"圣灵有话说：你们今日若听他的话，","notes":[],"heads":["神子民的安息"]},{"n":8,"t":"就不可硬着心，像在旷野惹他发怒、试探他的时候一样。","notes":[]},{"n":9,"t":"在那里，你们的祖宗试我探我，并且观看我的作为有四十年之久。","notes":[]},{"n":10,"t":"所以，我厌烦那世代的人，说：他们心里常常迷糊，竟不晓得我的作为！","notes":[]},{"n":11,"t":"我就在怒中起誓说：他们断不可进入我的安息。","notes":[]},{"n":12,"t":"弟兄们，你们要谨慎，免得你们中间或有人存着不信的恶心，把永生神离弃了。","notes":[]},{"n":13,"t":"总要趁着还有今日，天天彼此相劝，免得你们中间有人被罪迷惑，心里就刚硬了。","notes":[]},{"n":14,"t":"我们若将起初确实的信心坚持到底，就在基督里有分了。","notes":[]},{"n":15,"t":"经上说：「你们今日若听他的话，就不可硬着心，像惹他发怒的日子一样。」","notes":[]},{"n":16,"t":"那时，听见他话惹他发怒的是谁呢？岂不是跟着摩西从埃及出来的众人吗？","notes":[]},{"n":17,"t":"神四十年之久，又厌烦谁呢？岂不是那些犯罪、尸首倒在旷野的人吗？","notes":[]},{"n":18,"t":"又向谁起誓，不容他们进入他的安息呢？岂不是向那些不信从的人吗？","notes":[]},{"n":19,"t":"这样看来，他们不能进入安息是因为不信的缘故了。","notes":[]}]},"4":{"heading":"大祭司耶稣","verses":[{"n":1,"t":"我们既蒙留下，有进入他安息的应许，就当畏惧，免得我们中间或有人似乎是赶不上了。","notes":["原文是你们"]},{"n":2,"t":"因为有福音传给我们，像传给他们一样；只是所听见的道与他们无益，因为他们没有信心与所听见的道调和。","notes":[]},{"n":3,"t":"但我们已经相信的人得以进入那安息，正如神所说：「我在怒中起誓说：『他们断不可进入我的安息！』」其实造物之工，从创世以来已经成全了。","notes":[]},{"n":4,"t":"论到第七日，有一处说：「到第七日，神就歇了他一切的工。」","notes":[]},{"n":5,"t":"又有一处说：「他们断不可进入我的安息！」","notes":[]},{"n":6,"t":"既有必进安息的人，那先前听见福音的，因为不信从，不得进去。","notes":[]},{"n":7,"t":"所以过了多年，就在大卫的书上，又限定一日，如以上所引的说：「你们今日若听他的话，就不可硬着心。」","notes":[]},{"n":8,"t":"若是约书亚已叫他们享了安息，后来神就不再提别的日子了。","notes":[]},{"n":9,"t":"这样看来，必另有一安息日的安息为神的子民存留。","notes":[]},{"n":10,"t":"因为那进入安息的，乃是歇了自己的工，正如神歇了他的工一样。","notes":[]},{"n":11,"t":"所以，我们务必竭力进入那安息，免得有人学那不信从的样子跌倒了。","notes":[]},{"n":12,"t":"神的道是活泼的，是有功效的，比一切两刃的剑更快，甚至魂与灵，骨节与骨髓，都能刺入、剖开，连心中的思念和主意都能辨明。","notes":[]},{"n":13,"t":"并且被造的没有一样在他面前不显然的；原来万物在那与我们有关系的主眼前，都是赤露敞开的。","notes":[]},{"n":14,"t":"我们既然有一位已经升入高天尊荣的大祭司，就是神的儿子耶稣，便当持定所承认的道。","notes":[]},{"n":15,"t":"因我们的大祭司并非不能体恤我们的软弱。他也曾凡事受过试探，与我们一样，只是他没有犯罪。","notes":[]},{"n":16,"t":"所以，我们只管坦然无惧地来到施恩的宝座前，为要得怜恤，蒙恩惠，作随时的帮助。","notes":[]}]},"5":{"heading":"警戒叛道的人","verses":[{"n":1,"t":"凡从人间挑选的大祭司，是奉派替人办理属神的事，为要献上礼物和赎罪祭。","notes":["或译：要为罪献上礼物和祭物"]},{"n":2,"t":"他能体谅那愚蒙的和失迷的人，因为他自己也是被软弱所困。","notes":[]},{"n":3,"t":"故此，他理当为百姓和自己献祭赎罪。","notes":[]},{"n":4,"t":"这大祭司的尊荣，没有人自取。惟要蒙神所召，像亚伦一样。","notes":[]},{"n":5,"t":"如此，基督也不是自取荣耀作大祭司，乃是在乎向他说「你是我的儿子，我今日生你」的那一位；","notes":[]},{"n":6,"t":"就如经上又有一处说：「你是照着麦基洗德的等次永远为祭司。」","notes":[]},{"n":7,"t":"基督在肉体的时候，既大声哀哭，流泪祷告，恳求那能救他免死的主，就因他的虔诚蒙了应允。","notes":[]},{"n":8,"t":"他虽然为儿子，还是因所受的苦难学了顺从。","notes":[]},{"n":9,"t":"他既得以完全，就为凡顺从他的人成了永远得救的根源，","notes":[]},{"n":10,"t":"并蒙神照着麦基洗德的等次称他为大祭司。","notes":[]},{"n":11,"t":"论到麦基洗德，我们有好些话，并且难以解明，因为你们听不进去。","notes":[]},{"n":12,"t":"看你们学习的工夫，本该作师傅，谁知还得有人将神圣言小学的开端另教导你们，并且成了那必须吃奶、不能吃干粮的人。","notes":[]},{"n":13,"t":"凡只能吃奶的都不熟练仁义的道理，因为他是婴孩；","notes":[]},{"n":14,"t":"惟独长大成人的才能吃干粮；他们的心窍习练得通达，就能分辨好歹了。","notes":[]}]},"6":{"heading":"神确切的应许","verses":[{"n":1,"t":"所以，我们应当离开基督道理的开端，竭力进到完全的地步，不必再立根基，就如那懊悔死行、信靠神、","notes":[]},{"n":2,"t":"各样洗礼、按手之礼、死人复活，以及永远审判各等教训。","notes":[]},{"n":3,"t":"神若许我们，我们必如此行。","notes":[]},{"n":4,"t":"论到那些已经蒙了光照、尝过天恩的滋味、又于圣灵有分，","notes":[]},{"n":5,"t":"并尝过神善道的滋味、觉悟来世权能的人，","notes":[]},{"n":6,"t":"若是离弃道理，就不能叫他们从新懊悔了。因为他们把神的儿子重钉十字架，明明地羞辱他。","notes":[]},{"n":7,"t":"就如一块田地，吃过屡次下的雨水，生长菜蔬，合乎耕种的人用，就从神得福；","notes":[]},{"n":8,"t":"若长荆棘和蒺藜，必被废弃，近于咒诅，结局就是焚烧。","notes":[]},{"n":9,"t":"亲爱的弟兄们，我们虽是这样说，却深信你们的行为强过这些，而且近乎得救。","notes":[]},{"n":10,"t":"因为神并非不公义，竟忘记你们所做的工和你们为他名所显的爱心，就是先前伺候圣徒，如今还是伺候。","notes":[]},{"n":11,"t":"我们愿你们各人都显出这样的殷勤，使你们有满足的指望，一直到底。","notes":[]},{"n":12,"t":"并且不懈怠，总要效法那些凭信心和忍耐承受应许的人。","notes":[]},{"n":13,"t":"当初神应许亚伯拉罕的时候，因为没有比自己更大可以指着起誓的，就指着自己起誓，说：","notes":[]},{"n":14,"t":"「论福，我必赐大福给你；论子孙，我必叫你的子孙多起来。」","notes":[]},{"n":15,"t":"这样，亚伯拉罕既恒久忍耐，就得了所应许的。","notes":[]},{"n":16,"t":"人都是指着比自己大的起誓，并且以起誓为实据，了结各样的争论。","notes":[]},{"n":17,"t":"照样，神愿意为那承受应许的人格外显明他的旨意是不更改的，就起誓为证。","notes":[]},{"n":18,"t":"借这两件不更改的事，神决不能说谎，好叫我们这逃往避难所、持定摆在我们前头指望的人可以大得勉励。","notes":[]},{"n":19,"t":"我们有这指望，如同灵魂的锚，又坚固又牢靠，且通入幔内。","notes":[]},{"n":20,"t":"作先锋的耶稣，既照着麦基洗德的等次成了永远的大祭司，就为我们进入幔内。","notes":[]}]},"7":{"heading":"麦基洗德的祭司等次","verses":[{"n":1,"t":"这麦基洗德就是撒冷王，又是至高神的祭司，本是长远为祭司的。他当亚伯拉罕杀败诸王回来的时候，就迎接他，给他祝福。","notes":[]},{"n":2,"t":"亚伯拉罕也将自己所得来的，取十分之一给他。他头一个名翻出来就是仁义王，他又名撒冷王，就是平安王的意思。","notes":[]},{"n":3,"t":"他无父，无母，无族谱，无生之始，无命之终，乃是与神的儿子相似。","notes":[]},{"n":4,"t":"你们想一想，先祖亚伯拉罕将自己所掳来上等之物取十分之一给他，这人是何等尊贵呢！","notes":[]},{"n":5,"t":"那得祭司职任的利未子孙，领命照例向百姓取十分之一，这百姓是自己的弟兄，虽是从亚伯拉罕身中生的，还是照例取十分之一。","notes":["原文是腰"]},{"n":6,"t":"独有麦基洗德，不与他们同谱，倒收纳亚伯拉罕的十分之一，为那蒙应许的亚伯拉罕祝福。","notes":[]},{"n":7,"t":"从来位分大的给位分小的祝福，这是驳不倒的理。","notes":[]},{"n":8,"t":"在这里收十分之一的都是必死的人；但在那里收十分之一的，有为他作见证的说，他是活的；","notes":[]},{"n":9,"t":"并且可说那受十分之一的利未，也是借着亚伯拉罕纳了十分之一。","notes":[]},{"n":10,"t":"因为麦基洗德迎接亚伯拉罕的时候，利未已经在他先祖的身中。","notes":["原文是腰"]},{"n":11,"t":"从前百姓在利未人祭司职任以下受律法，倘若借这职任能得完全，又何用另外兴起一位祭司，照麦基洗德的等次，不照亚伦的等次呢？","notes":[]},{"n":12,"t":"祭司的职任既已更改，律法也必须更改。","notes":[]},{"n":13,"t":"因为这话所指的人本属别的支派，那支派里从来没有一人伺候祭坛。","notes":[]},{"n":14,"t":"我们的主分明是从犹大出来的；但这支派，摩西并没有提到祭司。","notes":[]},{"n":15,"t":"倘若照麦基洗德的样式，另外兴起一位祭司来，我的话更是显而易见的了。","notes":[]},{"n":16,"t":"他成为祭司，并不是照属肉体的条例，乃是照无穷之生命的大能。","notes":["原文是不能毁坏"]},{"n":17,"t":"因为有给他作见证的说：「你是照着麦基洗德的等次永远为祭司。」","notes":[]},{"n":18,"t":"先前的条例，因软弱无益，所以废掉了，","notes":[]},{"n":19,"t":"（律法原来一无所成）就引进了更美的指望；靠这指望，我们便可以进到神面前。","notes":[]},{"n":20,"t":"再者，耶稣为祭司，并不是不起誓立的。","notes":[]},{"n":21,"t":"至于那些祭司，原不是起誓立的，只有耶稣是起誓立的；因为那立他的对他说：「主起了誓，决不后悔，你是永远为祭司。」","notes":[]},{"n":22,"t":"既是起誓立的，耶稣就作了更美之约的中保。","notes":[]},{"n":23,"t":"那些成为祭司的，数目本来多，是因为有死阻隔，不能长久。","notes":[]},{"n":24,"t":"这位既是永远常存的，他祭司的职任就长久不更换。","notes":[]},{"n":25,"t":"凡靠着他进到神面前的人，他都能拯救到底；因为他是长远活着，替他们祈求。","notes":[]},{"n":26,"t":"像这样圣洁、无邪恶、无玷污、远离罪人、高过诸天的大祭司，原是与我们合宜的。","notes":[]},{"n":27,"t":"他不像那些大祭司，每日必须先为自己的罪，后为百姓的罪献祭；因为他只一次将自己献上，就把这事成全了。","notes":[]},{"n":28,"t":"律法本是立软弱的人为大祭司；但在律法以后起誓的话，是立儿子为大祭司，乃是成全到永远的。","notes":[]}]},"8":{"heading":"更美之约的大祭司","verses":[{"n":1,"t":"我们所讲的事，其中第一要紧的，就是我们有这样的大祭司，已经坐在天上至大者宝座的右边，","notes":[]},{"n":2,"t":"在圣所，就是真帐幕里，作执事；这帐幕是主所支的，不是人所支的。","notes":[]},{"n":3,"t":"凡大祭司都是为献礼物和祭物设立的，所以这位大祭司也必须有所献的。","notes":[]},{"n":4,"t":"他若在地上，必不得为祭司，因为已经有照律法献礼物的祭司。","notes":[]},{"n":5,"t":"他们供奉的事本是天上事的形状和影像，正如摩西将要造帐幕的时候，蒙神警戒他，说：「你要谨慎，作各样的物件都要照着在山上指示你的样式。」","notes":[]},{"n":6,"t":"如今耶稣所得的职任是更美的，正如他作更美之约的中保；这约原是凭更美之应许立的。","notes":[]},{"n":7,"t":"那前约若没有瑕疵，就无处寻求后约了。","notes":[]},{"n":8,"t":"所以主指责他的百姓说：日子将到，我要与以色列家和犹大家另立新约，","notes":["或译：所以主指前约的缺欠说"]},{"n":9,"t":"不像我拉着他们祖宗的手，领他们出埃及的时候，与他们所立的约。因为他们不恒心守我的约，我也不理他们。这是主说的。","notes":[]},{"n":10,"t":"主又说：那些日子以后，我与以色列家所立的约乃是这样：我要将我的律法放在他们里面，写在他们心上；我要作他们的神；他们要作我的子民。","notes":[]},{"n":11,"t":"他们不用各人教导自己的乡邻和自己的弟兄，说：你该认识主；因为他们从最小的到至大的，都必认识我。","notes":[]},{"n":12,"t":"我要宽恕他们的不义，不再记念他们的罪愆。","notes":[]},{"n":13,"t":"既说新约，就以前约为旧了；但那渐旧渐衰的，就必快归无有了。","notes":[]}]},"9":{"heading":"地上和天上的圣所","verses":[{"n":1,"t":"原来前约有礼拜的条例和属世界的圣幕。","notes":[]},{"n":2,"t":"因为有预备的帐幕，头一层叫作圣所，里面有灯台、桌子，和陈设饼。","notes":[]},{"n":3,"t":"第二幔子后又有一层帐幕，叫作至圣所，","notes":[]},{"n":4,"t":"有金香炉，有包金的约柜，柜里有盛吗哪的金罐和亚伦发过芽的杖，并两块约版；","notes":["炉：或译坛"]},{"n":5,"t":"柜上面有荣耀基路伯的影罩着施恩座。这几件我现在不能一一细说。","notes":["施恩：原文是蔽罪"]},{"n":6,"t":"这些物件既如此预备齐了，众祭司就常进头一层帐幕，行拜神的礼。","notes":[]},{"n":7,"t":"至于第二层帐幕，惟有大祭司一年一次独自进去，没有不带着血为自己和百姓的过错献上。","notes":[]},{"n":8,"t":"圣灵用此指明，头一层帐幕仍存的时候，进入至圣所的路还未显明。","notes":[]},{"n":9,"t":"那头一层帐幕作现今的一个表样，所献的礼物和祭物，就着良心说，都不能叫礼拜的人得以完全。","notes":[]},{"n":10,"t":"这些事，连那饮食和诸般洗濯的规矩，都不过是属肉体的条例，命定到振兴的时候为止。","notes":[]},{"n":11,"t":"但现在基督已经来到，作了将来美事的大祭司，经过那更大更全备的帐幕，不是人手所造，也不是属乎这世界的；","notes":[]},{"n":12,"t":"并且不用山羊和牛犊的血，乃用自己的血，只一次进入圣所，成了永远赎罪的事。","notes":[]},{"n":13,"t":"若山羊和公牛的血，并母牛犊的灰，洒在不洁的人身上，尚且叫人成圣，身体洁净，","notes":[]},{"n":14,"t":"何况基督借着永远的灵，将自己无瑕无疵献给神，他的血岂不更能洗净你们的心，除去你们的死行，使你们事奉那永生神吗？","notes":["原文是良心"]},{"n":15,"t":"为此，他作了新约的中保，既然受死赎了人在前约之时所犯的罪过，便叫蒙召之人得着所应许永远的产业。","notes":[]},{"n":16,"t":"凡有遗命必须等到留遗命的人死了；","notes":["遗命：原文与约字同"]},{"n":17,"t":"因为人死了，遗命才有效力，若留遗命的尚在，那遗命还有用处吗？","notes":[]},{"n":18,"t":"所以，前约也不是不用血立的；","notes":[]},{"n":19,"t":"因为摩西当日照着律法将各样诫命传给众百姓，就拿朱红色绒和牛膝草，把牛犊山羊的血和水洒在书上，又洒在众百姓身上，说：","notes":[]},{"n":20,"t":"「这血就是神与你们立约的凭据。」","notes":[]},{"n":21,"t":"他又照样把血洒在帐幕和各样器皿上。","notes":[]},{"n":22,"t":"按着律法，凡物差不多都是用血洁净的；若不流血，罪就不得赦免了。","notes":[]},{"n":23,"t":"照着天上样式做的物件必须用这些祭物去洁净；但那天上的本物自然当用更美的祭物去洁净。","notes":[],"heads":["基督献己为祭除掉了罪"]},{"n":24,"t":"因为基督并不是进了人手所造的圣所（这不过是真圣所的影相），乃是进了天堂，如今为我们显在神面前；","notes":[]},{"n":25,"t":"也不是多次将自己献上，像那大祭司每年带着牛羊的血进入圣所，","notes":["牛羊的血：原文作不是自己的血"]},{"n":26,"t":"如果这样，他从创世以来，就必多次受苦了。但如今在这末世显现一次，把自己献为祭，好除掉罪。","notes":[]},{"n":27,"t":"按着定命，人人都有一死，死后且有审判。","notes":[]},{"n":28,"t":"像这样，基督既然一次被献，担当了多人的罪，将来要向那等候他的人第二次显现，并与罪无关，乃是为拯救他们。","notes":[]}]},"10":{"heading":"劝勉和警告","verses":[{"n":1,"t":"律法既是将来美事的影儿，不是本物的真像，总不能借着每年常献一样的祭物叫那近前来的人得以完全。","notes":[]},{"n":2,"t":"若不然，献祭的事岂不早已止住了吗？因为礼拜的人，良心既被洁净，就不再觉得有罪了。","notes":[]},{"n":3,"t":"但这些祭物是叫人每年想起罪来；","notes":[]},{"n":4,"t":"因为公牛和山羊的血，断不能除罪。","notes":[]},{"n":5,"t":"所以基督到世上来的时候，就说：神啊，祭物和礼物是你不愿意的；你曾给我预备了身体。","notes":[]},{"n":6,"t":"燔祭和赎罪祭是你不喜欢的。","notes":[]},{"n":7,"t":"那时我说：神啊，我来了，为要照你的旨意行；我的事在经卷上已经记载了。","notes":[]},{"n":8,"t":"以上说：「祭物和礼物，燔祭和赎罪祭，是你不愿意的，也是你不喜欢的（这都是按着律法献的）」；","notes":[]},{"n":9,"t":"后又说：「我来了为要照你的旨意行」；可见他是除去在先的，为要立定在后的。","notes":[]},{"n":10,"t":"我们凭这旨意，靠耶稣基督，只一次献上他的身体，就得以成圣。","notes":[]},{"n":11,"t":"凡祭司天天站着事奉神，屡次献上一样的祭物，这祭物永不能除罪。","notes":[]},{"n":12,"t":"但基督献了一次永远的赎罪祭，就在神的右边坐下了。","notes":[]},{"n":13,"t":"从此，等候他仇敌成了他的脚凳。","notes":[]},{"n":14,"t":"因为他一次献祭，便叫那得以成圣的人永远完全。","notes":[]},{"n":15,"t":"圣灵也对我们作见证；因为他既已说过：","notes":[]},{"n":16,"t":"主说：那些日子以后，我与他们所立的约乃是这样：我要将我的律法写在他们心上，又要放在他们的里面。","notes":[]},{"n":17,"t":"以后就说：我不再记念他们的罪愆和他们的过犯。","notes":[]},{"n":18,"t":"这些罪过既已赦免，就不用再为罪献祭了。","notes":[]},{"n":19,"t":"弟兄们，我们既因耶稣的血得以坦然进入至圣所，","notes":[]},{"n":20,"t":"是借着他给我们开了一条又新又活的路，从幔子经过，这幔子就是他的身体。","notes":[]},{"n":21,"t":"又有一位大祭司治理神的家，","notes":[]},{"n":22,"t":"并我们心中天良的亏欠已经洒去，身体用清水洗净了，就当存着诚心和充足的信心来到神面前；","notes":[]},{"n":23,"t":"也要坚守我们所承认的指望，不至摇动，因为那应许我们的是信实的。","notes":[]},{"n":24,"t":"又要彼此相顾，激发爱心，勉励行善。","notes":[]},{"n":25,"t":"你们不可停止聚会，好像那些停止惯了的人，倒要彼此劝勉，既知道那日子临近，就更当如此。","notes":["原文是看见"]},{"n":26,"t":"因为我们得知真道以后，若故意犯罪，赎罪的祭就再没有了；","notes":[]},{"n":27,"t":"惟有战惧等候审判和那烧灭众敌人的烈火。","notes":[]},{"n":28,"t":"人干犯摩西的律法，凭两三个见证人，尚且不得怜恤而死，","notes":[]},{"n":29,"t":"何况人践踏神的儿子，将那使他成圣之约的血当作平常，又亵慢施恩的圣灵，你们想，他要受的刑罚该怎样加重呢！","notes":[]},{"n":30,"t":"因为我们知道谁说：「伸冤在我，我必报应」；又说：「主要审判他的百姓。」","notes":[]},{"n":31,"t":"落在永生神的手里，真是可怕的！","notes":[]},{"n":32,"t":"你们要追念往日，蒙了光照以后所忍受大争战的各样苦难：","notes":[]},{"n":33,"t":"一面被毁谤，遭患难，成了戏景，叫众人观看；一面陪伴那些受这样苦难的人。","notes":[]},{"n":34,"t":"因为你们体恤了那些被捆锁的人，并且你们的家业被人抢去，也甘心忍受，知道自己有更美长存的家业。","notes":[]},{"n":35,"t":"所以，你们不可丢弃勇敢的心；存这样的心必得大赏赐。","notes":[]},{"n":36,"t":"你们必须忍耐，使你们行完了神的旨意，就可以得着所应许的。","notes":[]},{"n":37,"t":"因为还有一点点时候，那要来的就来，并不迟延；","notes":[]},{"n":38,"t":"只是义人必因信得生。他若退后，我心里就不喜欢他。","notes":["有古卷：我的义人"]},{"n":39,"t":"我们却不是退后入沉沦的那等人，乃是有信心以致灵魂得救的人。","notes":[]}]},"11":{"heading":"论信","verses":[{"n":1,"t":"信就是所望之事的实底，是未见之事的确据。","notes":[]},{"n":2,"t":"古人在这信上得了美好的证据。","notes":[]},{"n":3,"t":"我们因着信，就知道诸世界是借神的话造成的；这样，所看见的，并不是从显然之物造出来的。","notes":[]},{"n":4,"t":"亚伯因着信，献祭与神，比该隐所献的更美，因此便得了称义的见证，就是神指他礼物作的见证。他虽然死了，却因这信，仍旧说话。","notes":[]},{"n":5,"t":"以诺因着信，被接去，不至于见死，人也找不着他，因为神已经把他接去了；只是他被接去以先，已经得了神喜悦他的明证。","notes":[]},{"n":6,"t":"人非有信，就不能得神的喜悦；因为到神面前来的人必须信有神，且信他赏赐那寻求他的人。","notes":[]},{"n":7,"t":"挪亚因着信，既蒙神指示他未见的事，动了敬畏的心，预备了一只方舟，使他全家得救。因此就定了那世代的罪，自己也承受了那从信而来的义。","notes":[]},{"n":8,"t":"亚伯拉罕因着信，蒙召的时候就遵命出去，往将来要得为业的地方去；出去的时候，还不知往哪里去。","notes":[]},{"n":9,"t":"他因着信，就在所应许之地作客，好像在异地居住帐棚，与那同蒙一个应许的以撒、雅各一样。","notes":[]},{"n":10,"t":"因为他等候那座有根基的城，就是神所经营所建造的。","notes":[]},{"n":11,"t":"因着信，连撒拉自己，虽然过了生育的岁数，还能怀孕，因她以为那应许她的是可信的。","notes":[]},{"n":12,"t":"所以从一个仿佛已死的人就生出子孙，如同天上的星那样众多，海边的沙那样无数。","notes":[]},{"n":13,"t":"这些人都是存着信心死的，并没有得着所应许的；却从远处望见，且欢喜迎接，又承认自己在世上是客旅，是寄居的。","notes":[]},{"n":14,"t":"说这样话的人是表明自己要找一个家乡。","notes":[]},{"n":15,"t":"他们若想念所离开的家乡，还有可以回去的机会。","notes":[]},{"n":16,"t":"他们却羡慕一个更美的家乡，就是在天上的。所以神被称为他们的神，并不以为耻，因为他已经给他们预备了一座城。","notes":[]},{"n":17,"t":"亚伯拉罕因着信，被试验的时候，就把以撒献上；这便是那欢喜领受应许的，将自己独生的儿子献上。","notes":[]},{"n":18,"t":"论到这儿子，曾有话说：「从以撒生的才要称为你的后裔。」","notes":[]},{"n":19,"t":"他以为神还能叫人从死里复活；他也仿佛从死中得回他的儿子来。","notes":[]},{"n":20,"t":"以撒因着信，就指着将来的事给雅各、以扫祝福。","notes":[]},{"n":21,"t":"雅各因着信，临死的时候，给约瑟的两个儿子各自祝福，扶着杖头敬拜神。","notes":[]},{"n":22,"t":"约瑟因着信，临终的时候，提到以色列族将来要出埃及，并为自己的骸骨留下遗命。","notes":[]},{"n":23,"t":"摩西生下来，他的父母见他是个俊美的孩子，就因着信，把他藏了三个月，并不怕王命。","notes":[]},{"n":24,"t":"摩西因着信，长大了就不肯称为法老女儿之子。","notes":[]},{"n":25,"t":"他宁可和神的百姓同受苦害，也不愿暂时享受罪中之乐。","notes":[]},{"n":26,"t":"他看为基督受的凌辱比埃及的财物更宝贵，因他想望所要得的赏赐。","notes":[]},{"n":27,"t":"他因着信，就离开埃及，不怕王怒；因为他恒心忍耐，如同看见那不能看见的主。","notes":[]},{"n":28,"t":"他因着信，就守逾越节，行洒血的礼，免得那灭长子的临近以色列人。","notes":["或译：立"]},{"n":29,"t":"他们因着信，过红海如行干地；埃及人试着要过去，就被吞灭了。","notes":[]},{"n":30,"t":"以色列人因着信，围绕耶利哥城七日，城墙就倒塌了。","notes":[]},{"n":31,"t":"妓女喇合因着信，曾和和平平地接待探子，就不与那些不顺从的人一同灭亡。","notes":[]},{"n":32,"t":"我又何必再说呢？若要一一细说，基甸、巴拉、参孙、耶弗他、大卫、撒母耳，和众先知的事，时候就不够了。","notes":[]},{"n":33,"t":"他们因着信，制伏了敌国，行了公义，得了应许，堵了狮子的口，","notes":[]},{"n":34,"t":"灭了烈火的猛势，脱了刀剑的锋刃；软弱变为刚强，争战显出勇敢，打退外邦的全军。","notes":[]},{"n":35,"t":"有妇人得自己的死人复活。又有人忍受严刑，不肯苟且得释放，为要得着更美的复活。","notes":["原文是赎"]},{"n":36,"t":"又有人忍受戏弄、鞭打、捆锁、监禁、各等的磨炼，","notes":[]},{"n":37,"t":"被石头打死，被锯锯死，受试探，被刀杀，披着绵羊山羊的皮各处奔跑，受穷乏、患难、苦害，","notes":[]},{"n":38,"t":"在旷野、山岭、山洞、地穴，飘流无定，本是世界不配有的人。","notes":[]},{"n":39,"t":"这些人都是因信得了美好的证据，却仍未得着所应许的；","notes":[]},{"n":40,"t":"因为神给我们预备了更美的事，叫他们若不与我们同得，就不能完全。","notes":[]}]},"12":{"heading":"主的管教","verses":[{"n":1,"t":"我们既有这许多的见证人，如同云彩围着我们，就当放下各样的重担，脱去容易缠累我们的罪，存心忍耐，奔那摆在我们前头的路程，","notes":[]},{"n":2,"t":"仰望为我们信心创始成终的耶稣。他因那摆在前面的喜乐，就轻看羞辱，忍受了十字架的苦难，便坐在神宝座的右边。","notes":["或译：仰望那将真道创始成终的耶稣"]},{"n":3,"t":"那忍受罪人这样顶撞的，你们要思想，免得疲倦灰心。","notes":[]},{"n":4,"t":"你们与罪恶相争，还没有抵挡到流血的地步。","notes":[]},{"n":5,"t":"你们又忘了那劝你们如同劝儿子的话，说：我儿，你不可轻看主的管教，被他责备的时候也不可灰心；","notes":[]},{"n":6,"t":"因为主所爱的，他必管教，又鞭打凡所收纳的儿子。","notes":[]},{"n":7,"t":"你们所忍受的，是神管教你们，待你们如同待儿子。焉有儿子不被父亲管教的呢？","notes":[]},{"n":8,"t":"管教原是众子所共受的。你们若不受管教，就是私子，不是儿子了。","notes":[]},{"n":9,"t":"再者，我们曾有生身的父管教我们，我们尚且敬重他，何况万灵的父，我们岂不更当顺服他得生吗？","notes":[]},{"n":10,"t":"生身的父都是暂随己意管教我们；惟有万灵的父管教我们，是要我们得益处，使我们在他的圣洁上有分。","notes":[]},{"n":11,"t":"凡管教的事，当时不觉得快乐，反觉得愁苦；后来却为那经练过的人结出平安的果子，就是义。","notes":[]},{"n":12,"t":"所以，你们要把下垂的手、发酸的腿挺起来；","notes":[]},{"n":13,"t":"也要为自己的脚，把道路修直了，使瘸子不致歪脚，反得痊愈。","notes":["或译：差路"]},{"n":14,"t":"你们要追求与众人和睦，并要追求圣洁；非圣洁没有人能见主。","notes":[],"heads":["警告弃绝神恩典的人"]},{"n":15,"t":"又要谨慎，恐怕有人失了神的恩；恐怕有毒根生出来扰乱你们，因此叫众人沾染污秽；","notes":[]},{"n":16,"t":"恐怕有淫乱的，有贪恋世俗如以扫的，他因一点食物把自己长子的名分卖了。","notes":[]},{"n":17,"t":"后来想要承受父所祝的福，竟被弃绝，虽然号哭切求，却得不着门路使他父亲的心意回转。这是你们知道的。","notes":[]},{"n":18,"t":"你们原不是来到那能摸的山；此山有火焰、密云、黑暗、暴风、","notes":[]},{"n":19,"t":"角声与说话的声音。那些听见这声音的，都求不要再向他们说话；","notes":[]},{"n":20,"t":"因为他们当不起所命他们的话，说：「靠近这山的，即便是走兽，也要用石头打死。」","notes":[]},{"n":21,"t":"所见的极其可怕，甚至摩西说：「我甚是恐惧战兢。」","notes":[]},{"n":22,"t":"你们乃是来到锡安山，永生神的城邑，就是天上的耶路撒冷。那里有千万的天使，","notes":[]},{"n":23,"t":"有名录在天上诸长子之会所共聚的总会，有审判众人的神和被成全之义人的灵魂，","notes":[]},{"n":24,"t":"并新约的中保耶稣，以及所洒的血；这血所说的比亚伯的血所说的更美。","notes":[]},{"n":25,"t":"你们总要谨慎，不可弃绝那向你们说话的。因为，那些弃绝在地上警戒他们的尚且不能逃罪，何况我们违背那从天上警戒我们的呢？","notes":[]},{"n":26,"t":"当时他的声音震动了地，但如今他应许说：「再一次我不单要震动地，还要震动天。」","notes":[]},{"n":27,"t":"这再一次的话，是指明被震动的，就是受造之物都要挪去，使那不被震动的常存。","notes":[]},{"n":28,"t":"所以我们既得了不能震动的国，就当感恩，照神所喜悦的，用虔诚、敬畏的心事奉神。","notes":[]},{"n":29,"t":"因为我们的神乃是烈火。","notes":[]}]},"13":{"heading":"蒙神悦纳的服务","verses":[{"n":1,"t":"你们务要常存弟兄相爱的心。","notes":[]},{"n":2,"t":"不可忘记用爱心接待客旅；因为曾有接待客旅的，不知不觉就接待了天使。","notes":[]},{"n":3,"t":"你们要记念被捆绑的人，好像与他们同受捆绑；也要记念遭苦害的人，想到自己也在肉身之内。","notes":[]},{"n":4,"t":"婚姻，人人都当尊重，床也不可污秽；因为苟合行淫的人，神必要审判。","notes":[]},{"n":5,"t":"你们存心不可贪爱钱财，要以自己所有的为足；因为主曾说：「我总不撇下你，也不丢弃你。」","notes":[]},{"n":6,"t":"所以我们可以放胆说：主是帮助我的，我必不惧怕；人能把我怎么样呢？","notes":[]},{"n":7,"t":"从前引导你们、传神之道给你们的人，你们要想念他们，效法他们的信心，留心看他们为人的结局。","notes":[]},{"n":8,"t":"耶稣基督昨日、今日、一直到永远，是一样的。","notes":[]},{"n":9,"t":"你们不要被那诸般怪异的教训勾引了去；因为人心靠恩得坚固才是好的，并不是靠饮食。那在饮食上专心的从来没有得着益处。","notes":[]},{"n":10,"t":"我们有一祭坛，上面的祭物是那些在帐幕中供职的人不可同吃的。","notes":[]},{"n":11,"t":"原来牲畜的血被大祭司带入圣所作赎罪祭；牲畜的身子被烧在营外。","notes":[]},{"n":12,"t":"所以，耶稣要用自己的血叫百姓成圣，也就在城门外受苦。","notes":[]},{"n":13,"t":"这样，我们也当出到营外，就了他去，忍受他所受的凌辱。","notes":[]},{"n":14,"t":"我们在这里本没有常存的城，乃是寻求那将来的城。","notes":[]},{"n":15,"t":"我们应当靠着耶稣，常常以颂赞为祭献给神，这就是那承认主名之人嘴唇的果子。","notes":[]},{"n":16,"t":"只是不可忘记行善和捐输的事，因为这样的祭是神所喜悦的。","notes":[]},{"n":17,"t":"你们要依从那些引导你们的，且要顺服；因他们为你们的灵魂时刻警醒，好像那将来交帐的人。你们要使他们交的时候有快乐，不致忧愁；若忧愁就与你们无益了。","notes":[]},{"n":18,"t":"请你们为我们祷告，因我们自觉良心无亏，愿意凡事按正道而行。","notes":[]},{"n":19,"t":"我更求你们为我祷告，使我快些回到你们那里去。","notes":[]},{"n":20,"t":"但愿赐平安的神，就是那凭永约之血、使群羊的大牧人—我主耶稣从死里复活的神，","notes":[],"heads":["祝福和问安"]},{"n":21,"t":"在各样善事上成全你们，叫你们遵行他的旨意；又借着耶稣基督在你们心里行他所喜悦的事。愿荣耀归给他，直到永永远远。阿们！","notes":[]},{"n":22,"t":"弟兄们，我略略写信给你们，望你们听我劝勉的话。","notes":[]},{"n":23,"t":"你们该知道，我们的兄弟提摩太已经释放了；他若快来，我必同他去见你们。","notes":[]},{"n":24,"t":"请你们问引导你们的诸位和众圣徒安。从意大利来的人也问你们安。","notes":[]},{"n":25,"t":"愿恩惠常与你们众人同在。阿们！","notes":[]}]}},"JAS":{"1":{"heading":"问候","verses":[{"n":1,"t":"作神和主耶稣基督仆人的雅各请散住十二个支派之人的安。","notes":[]},{"n":2,"t":"我的弟兄们，你们落在百般试炼中，都要以为大喜乐；","notes":[],"heads":["信心和智慧"]},{"n":3,"t":"因为知道你们的信心经过试验，就生忍耐。","notes":[]},{"n":4,"t":"但忍耐也当成功，使你们成全、完备，毫无缺欠。","notes":[]},{"n":5,"t":"你们中间若有缺少智慧的，应当求那厚赐与众人、也不斥责人的神，主就必赐给他。","notes":[]},{"n":6,"t":"只要凭着信心求，一点不疑惑；因为那疑惑的人，就像海中的波浪，被风吹动翻腾。","notes":[]},{"n":7,"t":"这样的人不要想从主那里得什么。","notes":[]},{"n":8,"t":"心怀二意的人，在他一切所行的路上都没有定见。","notes":[]},{"n":9,"t":"卑微的弟兄升高，就该喜乐；","notes":[],"heads":["贫穷和富有"]},{"n":10,"t":"富足的降卑，也该如此；因为他必要过去，如同草上的花一样。","notes":[]},{"n":11,"t":"太阳出来，热风刮起，草就枯干，花也凋谢，美容就消没了；那富足的人，在他所行的事上也要这样衰残。","notes":[]},{"n":12,"t":"忍受试探的人是有福的，因为他经过试验以后，必得生命的冠冕；这是主应许给那些爱他之人的。","notes":[],"heads":["考验和试探"]},{"n":13,"t":"人被试探，不可说：「我是被神试探」；因为神不能被恶试探，他也不试探人。","notes":[]},{"n":14,"t":"但各人被试探，乃是被自己的私欲牵引诱惑的。","notes":[]},{"n":15,"t":"私欲既怀了胎，就生出罪来；罪既长成，就生出死来。","notes":[]},{"n":16,"t":"我亲爱的弟兄们，不要看错了。","notes":[]},{"n":17,"t":"各样美善的恩赐和各样全备的赏赐都是从上头来的，从众光之父那里降下来的；在他并没有改变，也没有转动的影儿。","notes":[]},{"n":18,"t":"他按自己的旨意，用真道生了我们，叫我们在他所造的万物中好像初熟的果子。","notes":[]},{"n":19,"t":"我亲爱的弟兄们，这是你们所知道的。但你们各人要快快地听，慢慢地说，慢慢地动怒，","notes":[],"heads":["听道和行道"]},{"n":20,"t":"因为人的怒气并不成就神的义。","notes":[]},{"n":21,"t":"所以，你们要脱去一切的污秽和盈余的邪恶，存温柔的心领受那所栽种的道，就是能救你们灵魂的道。","notes":[]},{"n":22,"t":"只是你们要行道，不要单单听道，自己欺哄自己。","notes":[]},{"n":23,"t":"因为听道而不行道的，就像人对着镜子看自己本来的面目，","notes":[]},{"n":24,"t":"看见，走后，随即忘了他的相貌如何。","notes":[]},{"n":25,"t":"惟有详细察看那全备、使人自由之律法的，并且时常如此，这人既不是听了就忘，乃是实在行出来，就在他所行的事上必然得福。","notes":[]},{"n":26,"t":"若有人自以为虔诚，却不勒住他的舌头，反欺哄自己的心，这人的虔诚是虚的。","notes":[]},{"n":27,"t":"在神我们的父面前，那清洁没有玷污的虔诚，就是看顾在患难中的孤儿寡妇，并且保守自己不沾染世俗。","notes":[]}]},"2":{"heading":"警告偏私","verses":[{"n":1,"t":"我的弟兄们，你们信奉我们荣耀的主耶稣基督，便不可按着外貌待人。","notes":[]},{"n":2,"t":"若有一个人带着金戒指，穿着华美衣服，进你们的会堂去；又有一个穷人穿着肮脏衣服也进去；","notes":[]},{"n":3,"t":"你们就重看那穿华美衣服的人，说：「请坐在这好位上」；又对那穷人说：「你站在那里」，或「坐在我脚凳下边。」","notes":[]},{"n":4,"t":"这岂不是你们偏心待人，用恶意断定人吗？","notes":[]},{"n":5,"t":"我亲爱的弟兄们，请听，神岂不是拣选了世上的贫穷人，叫他们在信上富足，并承受他所应许给那些爱他之人的国吗？","notes":[]},{"n":6,"t":"你们反倒羞辱贫穷人。那富足人岂不是欺压你们、拉你们到公堂去吗？","notes":[]},{"n":7,"t":"他们不是亵渎你们所敬奉的尊名吗？","notes":["所敬奉：或译被称"]},{"n":8,"t":"经上记着说：「要爱人如己。」你们若全守这至尊的律法才是好的。","notes":[]},{"n":9,"t":"但你们若按外貌待人，便是犯罪，被律法定为犯法的。","notes":[]},{"n":10,"t":"因为凡遵守全律法的，只在一条上跌倒，他就是犯了众条。","notes":[]},{"n":11,"t":"原来那说「不可奸淫」的，也说「不可杀人」；你就是不奸淫，却杀人，仍是成了犯律法的。","notes":[]},{"n":12,"t":"你们既然要按使人自由的律法受审判，就该照这律法说话行事。","notes":[]},{"n":13,"t":"因为那不怜悯人的，也要受无怜悯的审判；怜悯原是向审判夸胜。","notes":[]},{"n":14,"t":"我的弟兄们，若有人说自己有信心，却没有行为，有什么益处呢？这信心能救他吗？","notes":[],"heads":["信心和行为"]},{"n":15,"t":"若是弟兄或是姊妹，赤身露体，又缺了日用的饮食；","notes":[]},{"n":16,"t":"你们中间有人对他们说：「平平安安地去吧！愿你们穿得暖，吃得饱」，却不给他们身体所需用的，这有什么益处呢？","notes":[]},{"n":17,"t":"这样，信心若没有行为就是死的。","notes":[]},{"n":18,"t":"必有人说：「你有信心，我有行为；你将你没有行为的信心指给我看，我便借着我的行为，将我的信心指给你看。」","notes":[]},{"n":19,"t":"你信神只有一位，你信的不错；鬼魔也信，却是战惊。","notes":[]},{"n":20,"t":"虚浮的人哪，你愿意知道没有行为的信心是死的吗？","notes":[]},{"n":21,"t":"我们的祖宗亚伯拉罕把他儿子以撒献在坛上，岂不是因行为称义吗？","notes":[]},{"n":22,"t":"可见，信心是与他的行为并行，而且信心因着行为才得成全。","notes":[]},{"n":23,"t":"这就应验经上所说：「亚伯拉罕信神，这就算为他的义。」他又得称为神的朋友。","notes":[]},{"n":24,"t":"这样看来，人称义是因着行为，不是单因着信。","notes":[]},{"n":25,"t":"妓女喇合接待使者，又放他们从别的路上出去，不也是一样因行为称义吗？","notes":[]},{"n":26,"t":"身体没有灵魂是死的，信心没有行为也是死的。","notes":[]}]},"3":{"heading":"论舌头","verses":[{"n":1,"t":"我的弟兄们，不要多人作师傅，因为晓得我们要受更重的判断。","notes":[]},{"n":2,"t":"原来我们在许多事上都有过失；若有人在话语上没有过失，他就是完全人，也能勒住自己的全身。","notes":[]},{"n":3,"t":"我们若把嚼环放在马嘴里，叫它顺服，就能调动它的全身。","notes":[]},{"n":4,"t":"看哪，船只虽然甚大，又被大风催逼，只用小小的舵，就随着掌舵的意思转动。","notes":[]},{"n":5,"t":"这样，舌头在百体里也是最小的，却能说大话。看哪，最小的火能点着最大的树林。","notes":[]},{"n":6,"t":"舌头就是火，在我们百体中，舌头是个罪恶的世界，能污秽全身，也能把生命的轮子点起来，并且是从地狱里点着的。","notes":[]},{"n":7,"t":"各类的走兽、飞禽、昆虫、水族，本来都可以制伏，也已经被人制伏了；","notes":[]},{"n":8,"t":"惟独舌头没有人能制伏，是不止息的恶物，满了害死人的毒气。","notes":[]},{"n":9,"t":"我们用舌头颂赞那为主、为父的，又用舌头咒诅那照着神形象被造的人。","notes":[]},{"n":10,"t":"颂赞和咒诅从一个口里出来！我的弟兄们，这是不应当的！","notes":[]},{"n":11,"t":"泉源从一个眼里能发出甜苦两样的水吗？","notes":[]},{"n":12,"t":"我的弟兄们，无花果树能生橄榄吗？葡萄树能结无花果吗？咸水里也不能发出甜水来。","notes":[]},{"n":13,"t":"你们中间谁是有智慧有见识的呢？他就当在智慧的温柔上显出他的善行来。","notes":[],"heads":["论从上头来的智慧"]},{"n":14,"t":"你们心里若怀着苦毒的嫉妒和纷争，就不可自夸，也不可说谎话抵挡真道。","notes":[]},{"n":15,"t":"这样的智慧不是从上头来的，乃是属地的，属情欲的，属鬼魔的。","notes":[]},{"n":16,"t":"在何处有嫉妒、纷争，就在何处有扰乱和各样的坏事。","notes":[]},{"n":17,"t":"惟独从上头来的智慧，先是清洁，后是和平，温良柔顺，满有怜悯，多结善果，没有偏见，没有假冒。","notes":[]},{"n":18,"t":"并且使人和平的，是用和平所栽种的义果。","notes":[]}]},"4":{"heading":"不可与世俗为友","verses":[{"n":1,"t":"你们中间的争战斗殴是从哪里来的呢？不是从你们百体中战斗之私欲来的吗？","notes":[]},{"n":2,"t":"你们贪恋，还是得不着；你们杀害嫉妒，又斗殴争战，也不能得。你们得不着，是因为你们不求。","notes":[]},{"n":3,"t":"你们求也得不着，是因为你们妄求，要浪费在你们的宴乐中。","notes":[]},{"n":4,"t":"你们这些淫乱的人哪，岂不知与世俗为友就是与神为敌吗？所以凡想要与世俗为友的，就是与神为敌了。","notes":["原文是淫妇"]},{"n":5,"t":"你们想经上所说是徒然的吗？神所赐、住在我们里面的灵，是恋爱至于嫉妒吗？","notes":[]},{"n":6,"t":"但他赐更多的恩典，所以经上说：神阻挡骄傲的人，赐恩给谦卑的人。","notes":[]},{"n":7,"t":"故此，你们要顺服神。务要抵挡魔鬼，魔鬼就必离开你们逃跑了。","notes":[]},{"n":8,"t":"你们亲近神，神就必亲近你们。有罪的人哪，要洁净你们的手！心怀二意的人哪，要清洁你们的心！","notes":[]},{"n":9,"t":"你们要愁苦、悲哀、哭泣，将喜笑变作悲哀，欢乐变作愁闷。","notes":[]},{"n":10,"t":"务要在主面前自卑，主就必叫你们升高。","notes":[]},{"n":11,"t":"弟兄们，你们不可彼此批评。人若批评弟兄，论断弟兄，就是批评律法，论断律法。你若论断律法，就不是遵行律法，乃是判断人的。","notes":[],"heads":["不可论断弟兄"]},{"n":12,"t":"设立律法和判断人的，只有一位，就是那能救人也能灭人的。你是谁，竟敢论断别人呢？","notes":[]},{"n":13,"t":"嗐！你们有话说：「今天明天我们要往某城里去，在那里住一年，做买卖得利。」","notes":[],"heads":["警戒自夸"]},{"n":14,"t":"其实明天如何，你们还不知道。你们的生命是什么呢？你们原来是一片云雾，出现少时就不见了。","notes":[]},{"n":15,"t":"你们只当说：「主若愿意，我们就可以活着，也可以做这事，或做那事。」","notes":[]},{"n":16,"t":"现今你们竟以张狂夸口；凡这样夸口都是恶的。","notes":[]},{"n":17,"t":"人若知道行善，却不去行，这就是他的罪了。","notes":[]}]},"5":{"heading":"警告富足的人","verses":[{"n":1,"t":"嗐！你们这些富足人哪，应当哭泣、号咷，因为将有苦难临到你们身上。","notes":[]},{"n":2,"t":"你们的财物坏了，衣服也被虫子咬了。","notes":[]},{"n":3,"t":"你们的金银都长了锈；那锈要证明你们的不是，又要吃你们的肉，如同火烧。你们在这末世只知积攒钱财。","notes":[]},{"n":4,"t":"工人给你们收割庄稼，你们亏欠他们的工钱，这工钱有声音呼叫，并且那收割之人的冤声已经入了万军之主的耳了。","notes":[]},{"n":5,"t":"你们在世上享美福，好宴乐，当宰杀的日子竟娇养你们的心。","notes":[]},{"n":6,"t":"你们定了义人的罪，把他杀害，他也不抵挡你们。","notes":[]},{"n":7,"t":"弟兄们哪，你们要忍耐，直到主来。看哪，农夫忍耐等候地里宝贵的出产，直到得了秋雨春雨。","notes":[],"heads":["忍耐和祷告"]},{"n":8,"t":"你们也当忍耐，坚固你们的心，因为主来的日子近了。","notes":[]},{"n":9,"t":"弟兄们，你们不要彼此埋怨，免得受审判。看哪，审判的主站在门前了。","notes":[]},{"n":10,"t":"弟兄们，你们要把那先前奉主名说话的众先知当作能受苦能忍耐的榜样。","notes":[]},{"n":11,"t":"那先前忍耐的人，我们称他们是有福的。你们听见过约伯的忍耐，也知道主给他的结局，明显主是满心怜悯，大有慈悲。","notes":[]},{"n":12,"t":"我的弟兄们，最要紧的是不可起誓；不可指着天起誓，也不可指着地起誓，无论何誓都不可起。你们说话，是，就说是；不是，就说不是，免得你们落在审判之下。","notes":[]},{"n":13,"t":"你们中间有受苦的呢，他就该祷告；有喜乐的呢，他就该歌颂。","notes":[]},{"n":14,"t":"你们中间有病了的呢，他就该请教会的长老来；他们可以奉主的名用油抹他，为他祷告。","notes":[]},{"n":15,"t":"出于信心的祈祷要救那病人，主必叫他起来；他若犯了罪，也必蒙赦免。","notes":[]},{"n":16,"t":"所以你们要彼此认罪，互相代求，使你们可以得医治。义人祈祷所发的力量是大有功效的。","notes":[]},{"n":17,"t":"以利亚与我们是一样性情的人，他恳切祷告，求不要下雨，雨就三年零六个月不下在地上。","notes":[]},{"n":18,"t":"他又祷告，天就降下雨来，地也生出土产。","notes":[]},{"n":19,"t":"我的弟兄们，你们中间若有失迷真道的，有人使他回转，","notes":[]},{"n":20,"t":"这人该知道：叫一个罪人从迷路上转回便是救一个灵魂不死，并且遮盖许多的罪。","notes":[]}]}},"1PE":{"1":{"heading":"问候","verses":[{"n":1,"t":"耶稣基督的使徒彼得写信给那分散在本都、加拉太、加帕多家、亚细亚、庇推尼寄居的，","notes":[]},{"n":2,"t":"就是照父神的先见被拣选，借着圣灵得成圣洁，以致顺服耶稣基督，又蒙他血所洒的人。愿恩惠、平安多多地加给你们。","notes":[]},{"n":3,"t":"愿颂赞归与我们主耶稣基督的父神！他曾照自己的大怜悯，借耶稣基督从死里复活，重生了我们，叫我们有活泼的盼望，","notes":[],"heads":["活的盼望"]},{"n":4,"t":"可以得着不能朽坏、不能玷污、不能衰残、为你们存留在天上的基业。","notes":[]},{"n":5,"t":"你们这因信蒙神能力保守的人，必能得着所预备、到末世要显现的救恩。","notes":[]},{"n":6,"t":"因此，你们是大有喜乐；但如今，在百般的试炼中暂时忧愁，","notes":[]},{"n":7,"t":"叫你们的信心既被试验，就比那被火试验仍然能坏的金子更显宝贵，可以在耶稣基督显现的时候得着称赞、荣耀、尊贵。","notes":[]},{"n":8,"t":"你们虽然没有见过他，却是爱他；如今虽不得看见，却因信他就有说不出来、满有荣光的大喜乐；","notes":[]},{"n":9,"t":"并且得着你们信心的果效，就是灵魂的救恩。","notes":[]},{"n":10,"t":"论到这救恩，那预先说你们要得恩典的众先知早已详细地寻求考察，","notes":[]},{"n":11,"t":"就是考察在他们心里基督的灵，预先证明基督受苦难，后来得荣耀，是指着什么时候，并怎样的时候。","notes":[]},{"n":12,"t":"他们得了启示，知道他们所传讲的一切事，不是为自己，乃是为你们。那靠着从天上差来的圣灵传福音给你们的人，现在将这些事报给你们；天使也愿意详细察看这些事。","notes":["原文是服事"]},{"n":13,"t":"所以要约束你们的心，谨慎自守，专心盼望耶稣基督显现的时候所带来给你们的恩。","notes":["原文是束上你们心中的腰"],"heads":["应当过圣洁的生活"]},{"n":14,"t":"你们既作顺命的儿女，就不要效法从前蒙昧无知的时候那放纵私欲的样子。","notes":[]},{"n":15,"t":"那召你们的既是圣洁，你们在一切所行的事上也要圣洁。","notes":[]},{"n":16,"t":"因为经上记着说：「你们要圣洁，因为我是圣洁的。」","notes":[]},{"n":17,"t":"你们既称那不偏待人、按各人行为审判人的主为父，就当存敬畏的心度你们在世寄居的日子，","notes":[]},{"n":18,"t":"知道你们得赎，脱去你们祖宗所传流虚妄的行为，不是凭着能坏的金银等物，","notes":[]},{"n":19,"t":"乃是凭着基督的宝血，如同无瑕疵、无玷污的羔羊之血。","notes":[]},{"n":20,"t":"基督在创世以前是预先被神知道的，却在这末世才为你们显现。","notes":[]},{"n":21,"t":"你们也因着他，信那叫他从死里复活、又给他荣耀的神，叫你们的信心和盼望都在于神。","notes":[]},{"n":22,"t":"你们既因顺从真理，洁净了自己的心，以致爱弟兄没有虚假，就当从心里彼此切实相爱。","notes":["从心里：有古卷是从清洁的心"]},{"n":23,"t":"你们蒙了重生，不是由于能坏的种子，乃是由于不能坏的种子，是借着神活泼常存的道。","notes":[]},{"n":24,"t":"因为凡有血气的，尽都如草；他的美荣都像草上的花。草必枯干，花必凋谢；","notes":[]},{"n":25,"t":"惟有主的道是永存的。所传给你们的福音就是这道。","notes":[]}]},"2":{"heading":"活石和圣洁的国度","verses":[{"n":1,"t":"所以，你们既除去一切的恶毒、诡诈，并假善、嫉妒，和一切毁谤的话，","notes":["或译：阴毒"]},{"n":2,"t":"就要爱慕那纯净的灵奶，像才生的婴孩爱慕奶一样，叫你们因此渐长，以致得救。","notes":[]},{"n":3,"t":"你们若尝过主恩的滋味，就必如此。","notes":[]},{"n":4,"t":"主乃活石，固然是被人所弃的，却是被神所拣选、所宝贵的。","notes":[]},{"n":5,"t":"你们来到主面前，也就像活石，被建造成为灵宫，作圣洁的祭司，借着耶稣基督奉献神所悦纳的灵祭。","notes":[]},{"n":6,"t":"因为经上说：看哪，我把所拣选、所宝贵的房角石安放在锡安；信靠他的人必不至于羞愧。","notes":[]},{"n":7,"t":"所以，他在你们信的人就为宝贵，在那不信的人有话说：匠人所弃的石头已作了房角的头块石头。","notes":[]},{"n":8,"t":"又说：作了绊脚的石头，跌人的磐石。他们既不顺从，就在道理上绊跌；他们这样绊跌也是预定的。","notes":["或译：他们绊跌都因不顺从道理"]},{"n":9,"t":"惟有你们是被拣选的族类，是有君尊的祭司，是圣洁的国度，是属神的子民，要叫你们宣扬那召你们出黑暗入奇妙光明者的美德。","notes":[]},{"n":10,"t":"你们从前算不得子民，现在却作了神的子民；从前未曾蒙怜恤，现在却蒙了怜恤。","notes":[]},{"n":11,"t":"亲爱的弟兄啊，你们是客旅，是寄居的。我劝你们要禁戒肉体的私欲；这私欲是与灵魂争战的。","notes":[],"heads":["作神的仆人"]},{"n":12,"t":"你们在外邦人中，应当品行端正，叫那些毁谤你们是作恶的，因看见你们的好行为，便在鉴察的日子归荣耀给神。","notes":["或译：眷顾"]},{"n":13,"t":"你们为主的缘故，要顺服人的一切制度，或是在上的君王，","notes":[]},{"n":14,"t":"或是君王所派罚恶赏善的臣宰。","notes":[]},{"n":15,"t":"因为神的旨意原是要你们行善，可以堵住那糊涂无知人的口。","notes":[]},{"n":16,"t":"你们虽是自由的，却不可借着自由遮盖恶毒，总要作神的仆人。","notes":["或译：阴毒"]},{"n":17,"t":"务要尊敬众人，亲爱教中的弟兄，敬畏神，尊敬君王。","notes":[]},{"n":18,"t":"你们作仆人的，凡事要存敬畏的心顺服主人；不但顺服那善良温和的，就是那乖僻的也要顺服。","notes":[],"heads":["基督受苦的榜样"]},{"n":19,"t":"倘若人为叫良心对得住神，就忍受冤屈的苦楚，这是可喜爱的。","notes":[]},{"n":20,"t":"你们若因犯罪受责打，能忍耐，有什么可夸的呢？但你们若因行善受苦，能忍耐，这在神看是可喜爱的。","notes":[]},{"n":21,"t":"你们蒙召原是为此；因基督也为你们受过苦，给你们留下榜样，叫你们跟随他的脚踪行。","notes":[]},{"n":22,"t":"他并没有犯罪，口里也没有诡诈。","notes":[]},{"n":23,"t":"他被骂不还口；受害不说威吓的话，只将自己交托那按公义审判人的主。","notes":[]},{"n":24,"t":"他被挂在木头上，亲身担当了我们的罪，使我们既然在罪上死，就得以在义上活。因他受的鞭伤，你们便得了医治。","notes":[]},{"n":25,"t":"你们从前好像迷路的羊，如今却归到你们灵魂的牧人监督了。","notes":[]}]},"3":{"heading":"妻子和丈夫","verses":[{"n":1,"t":"你们作妻子的要顺服自己的丈夫；这样，若有不信从道理的丈夫，他们虽然不听道，也可以因妻子的品行被感化过来；","notes":[]},{"n":2,"t":"这正是因看见你们有贞洁的品行和敬畏的心。","notes":[]},{"n":3,"t":"你们不要以外面的辫头发，戴金饰，穿美衣为妆饰，","notes":[]},{"n":4,"t":"只要以里面存着长久温柔、安静的心为妆饰；这在神面前是极宝贵的。","notes":[]},{"n":5,"t":"因为古时仰赖神的圣洁妇人正是以此为妆饰，顺服自己的丈夫，","notes":[]},{"n":6,"t":"就如撒拉听从亚伯拉罕，称他为主。你们若行善，不因恐吓而害怕，便是撒拉的女儿了。","notes":[]},{"n":7,"t":"你们作丈夫的也要按情理和妻子同住；因她比你软弱，与你一同承受生命之恩的，所以要敬重她。这样，便叫你们的祷告没有阻碍。","notes":["原文是知识","比你软弱：原文作是软弱的器皿"]},{"n":8,"t":"总而言之，你们都要同心，彼此体恤，相爱如弟兄，存慈怜谦卑的心。","notes":[],"heads":["为义受苦"]},{"n":9,"t":"不以恶报恶，以辱骂还辱骂，倒要祝福；因你们是为此蒙召，好叫你们承受福气。","notes":[]},{"n":10,"t":"因为经上说：人若爱生命，愿享美福，须要禁止舌头不出恶言，嘴唇不说诡诈的话；","notes":[]},{"n":11,"t":"也要离恶行善，寻求和睦，一心追赶。","notes":[]},{"n":12,"t":"因为，主的眼看顾义人；主的耳听他们的祈祷。惟有行恶的人，主向他们变脸。","notes":[]},{"n":13,"t":"你们若是热心行善，有谁害你们呢？","notes":[]},{"n":14,"t":"你们就是为义受苦，也是有福的。不要怕人的威吓，也不要惊慌；","notes":["的威吓：或译所怕的"]},{"n":15,"t":"只要心里尊主基督为圣。有人问你们心中盼望的缘由，就要常作准备，以温柔、敬畏的心回答各人；","notes":[]},{"n":16,"t":"存着无亏的良心，叫你们在何事上被毁谤，就在何事上可以叫那诬赖你们在基督里有好品行的人自觉羞愧。","notes":[]},{"n":17,"t":"神的旨意若是叫你们因行善受苦，总强如因行恶受苦。","notes":[]},{"n":18,"t":"因基督也曾一次为罪受苦，就是义的代替不义的，为要引我们到神面前。按着肉体说，他被治死；按着灵性说，他复活了。","notes":["有古卷：受死"]},{"n":19,"t":"他借这灵曾去传道给那些在监狱里的灵听，","notes":[]},{"n":20,"t":"就是那从前在挪亚预备方舟、神容忍等待的时候，不信从的人。当时进入方舟，借着水得救的不多，只有八个人。","notes":[]},{"n":21,"t":"这水所表明的洗礼，现在借着耶稣基督复活也拯救你们；这洗礼本不在乎除掉肉体的污秽，只求在神面前有无亏的良心。","notes":[]},{"n":22,"t":"耶稣已经进入天堂，在神的右边；众天使和有权柄的，并有能力的，都服从了他。","notes":[]}]},"4":{"heading":"神恩赐的好管家","verses":[{"n":1,"t":"基督既在肉身受苦，你们也当将这样的心志作为兵器，因为在肉身受过苦的，就已经与罪断绝了。","notes":[]},{"n":2,"t":"你们存这样的心，从今以后就可以不从人的情欲，只从神的旨意在世度余下的光阴。","notes":[]},{"n":3,"t":"因为往日随从外邦人的心意行邪淫、恶欲、醉酒、荒宴、群饮，并可恶拜偶像的事，时候已经够了。","notes":[]},{"n":4,"t":"他们在这些事上，见你们不与他们同奔那放荡无度的路，就以为怪，毁谤你们。","notes":[]},{"n":5,"t":"他们必在那将要审判活人死人的主面前交帐。","notes":[]},{"n":6,"t":"为此，就是死人也曾有福音传给他们，要叫他们的肉体按着人受审判，他们的灵性却靠神活着。","notes":[]},{"n":7,"t":"万物的结局近了。所以，你们要谨慎自守，警醒祷告。","notes":[]},{"n":8,"t":"最要紧的是彼此切实相爱，因为爱能遮掩许多的罪。","notes":[]},{"n":9,"t":"你们要互相款待，不发怨言。","notes":[]},{"n":10,"t":"各人要照所得的恩赐彼此服事，作神百般恩赐的好管家。","notes":[]},{"n":11,"t":"若有讲道的，要按着神的圣言讲；若有服事人的，要按着神所赐的力量服事，叫神在凡事上因耶稣基督得荣耀。原来荣耀、权能都是他的，直到永永远远。阿们！","notes":[]},{"n":12,"t":"亲爱的弟兄啊，有火炼的试验临到你们，不要以为奇怪（似乎是遭遇非常的事），","notes":[],"heads":["为作基督徒受苦"]},{"n":13,"t":"倒要欢喜；因为你们是与基督一同受苦，使你们在他荣耀显现的时候，也可以欢喜快乐。","notes":[]},{"n":14,"t":"你们若为基督的名受辱骂，便是有福的；因为神荣耀的灵常住在你们身上。","notes":[]},{"n":15,"t":"你们中间却不可有人因为杀人、偷窃、作恶、好管闲事而受苦。","notes":[]},{"n":16,"t":"若为作基督徒受苦，却不要羞耻，倒要因这名归荣耀给神。","notes":[]},{"n":17,"t":"因为时候到了，审判要从神的家起首。若是先从我们起首，那不信从神福音的人将有何等的结局呢？","notes":[]},{"n":18,"t":"若是义人仅仅得救，那不虔敬和犯罪的人将有何地可站呢？","notes":[]},{"n":19,"t":"所以，那照神旨意受苦的人要一心为善，将自己灵魂交与那信实的造化之主。","notes":[]}]},"5":{"heading":"照管神的羊群","verses":[{"n":1,"t":"我这作长老、作基督受苦的见证、同享后来所要显现之荣耀的，劝你们中间与我同作长老的人：","notes":[]},{"n":2,"t":"务要牧养在你们中间神的群羊，按着神旨意照管他们；不是出于勉强，乃是出于甘心；也不是因为贪财，乃是出于乐意；","notes":[]},{"n":3,"t":"也不是辖制所托付你们的，乃是作群羊的榜样。","notes":[]},{"n":4,"t":"到了牧长显现的时候，你们必得那永不衰残的荣耀冠冕。","notes":[]},{"n":5,"t":"你们年幼的，也要顺服年长的。就是你们众人也都要以谦卑束腰，彼此顺服；因为神阻挡骄傲的人，赐恩给谦卑的人。","notes":[]},{"n":6,"t":"所以，你们要自卑，服在神大能的手下，到了时候，他必叫你们升高。","notes":[]},{"n":7,"t":"你们要将一切的忧虑卸给神，因为他顾念你们。","notes":[]},{"n":8,"t":"务要谨守，警醒。因为你们的仇敌魔鬼，如同吼叫的狮子，遍地游行，寻找可吞吃的人。","notes":[]},{"n":9,"t":"你们要用坚固的信心抵挡他，因为知道你们在世上的众弟兄也是经历这样的苦难。","notes":[]},{"n":10,"t":"那赐诸般恩典的神曾在基督里召你们，得享他永远的荣耀，等你们暂受苦难之后，必要亲自成全你们，坚固你们，赐力量给你们。","notes":[]},{"n":11,"t":"愿权能归给他，直到永永远远。阿们！","notes":[]},{"n":12,"t":"我略略地写了这信，托我所看为忠心的兄弟西拉转交你们，劝勉你们，又证明这恩是神的真恩。你们务要在这恩上站立得住。","notes":[],"heads":["问安"]},{"n":13,"t":"在巴比伦与你们同蒙拣选的教会问你们安。我儿子马可也问你们安。","notes":[]},{"n":14,"t":"你们要用爱心彼此亲嘴问安。愿平安归与你们凡在基督里的人！","notes":[]}]}},"2PE":{"1":{"heading":"问候","verses":[{"n":1,"t":"作耶稣基督仆人和使徒的西门·彼得写信给那因我们的神和救主耶稣基督之义、与我们同得一样宝贵信心的人。","notes":["有古卷没有和字"]},{"n":2,"t":"愿恩惠、平安，因你们认识神和我们主耶稣，多多地加给你们。","notes":[]},{"n":3,"t":"神的神能已将一切关乎生命和虔敬的事赐给我们，皆因我们认识那用自己荣耀和美德召我们的主。","notes":[],"heads":["信徒所蒙的恩召和拣选"]},{"n":4,"t":"因此，他已将又宝贵又极大的应许赐给我们，叫我们既脱离世上从情欲来的败坏，就得与神的性情有分。","notes":[]},{"n":5,"t":"正因这缘故，你们要分外地殷勤；有了信心，又要加上德行；有了德行，又要加上知识；","notes":[]},{"n":6,"t":"有了知识，又要加上节制；有了节制，又要加上忍耐；有了忍耐，又要加上虔敬；","notes":[]},{"n":7,"t":"有了虔敬，又要加上爱弟兄的心；有了爱弟兄的心，又要加上爱众人的心。","notes":[]},{"n":8,"t":"你们若充充足足地有这几样，就必使你们在认识我们的主耶稣基督上不至于闲懒不结果子了。","notes":[]},{"n":9,"t":"人若没有这几样，就是眼瞎，只看见近处的，忘了他旧日的罪已经得了洁净。","notes":[]},{"n":10,"t":"所以弟兄们，应当更加殷勤，使你们所蒙的恩召和拣选坚定不移。你们若行这几样，就永不失脚；","notes":[]},{"n":11,"t":"这样，必叫你们丰丰富富地得以进入我们主—救主耶稣基督永远的国。","notes":[]},{"n":12,"t":"你们虽然晓得这些事，并且在你们已有的真道上坚固，我却要将这些事常常提醒你们。","notes":[]},{"n":13,"t":"我以为应当趁我还在这帐棚的时候提醒你们，激发你们；","notes":[]},{"n":14,"t":"因为知道我脱离这帐棚的时候快到了，正如我们主耶稣基督所指示我的。","notes":[]},{"n":15,"t":"并且，我要尽心竭力，使你们在我去世以后时常记念这些事。","notes":[]},{"n":16,"t":"我们从前将我们主耶稣基督的大能和他降临的事告诉你们，并不是随从乖巧捏造的虚言，乃是亲眼见过他的威荣。","notes":[],"heads":["基督的荣耀和先知的预言"]},{"n":17,"t":"他从父神得尊贵荣耀的时候，从极大荣光之中有声音出来，向他说：「这是我的爱子，我所喜悦的。」","notes":[]},{"n":18,"t":"我们同他在圣山的时候，亲自听见这声音从天上出来。","notes":[]},{"n":19,"t":"我们并有先知更确的预言，如同灯照在暗处。你们在这预言上留意，直等到天发亮，晨星在你们心里出现的时候，才是好的。","notes":[]},{"n":20,"t":"第一要紧的，该知道经上所有的预言没有可随私意解说的；","notes":[]},{"n":21,"t":"因为预言从来没有出于人意的，乃是人被圣灵感动，说出神的话来。","notes":[]}]},"2":{"heading":"假先知和假师傅","verses":[{"n":1,"t":"从前在百姓中有假先知起来，将来在你们中间也必有假师傅，私自引进陷害人的异端，连买他们的主他们也不承认，自取速速地灭亡。","notes":[]},{"n":2,"t":"将有许多人随从他们邪淫的行为，便叫真道因他们的缘故被毁谤。","notes":[]},{"n":3,"t":"他们因有贪心，要用捏造的言语在你们身上取利。他们的刑罚，自古以来并不迟延；他们的灭亡也必速速来到。","notes":["原文是也不打盹"]},{"n":4,"t":"就是天使犯了罪，神也没有宽容，曾把他们丢在地狱，交在黑暗坑中，等候审判。","notes":[]},{"n":5,"t":"神也没有宽容上古的世代，曾叫洪水临到那不敬虔的世代，却保护了传义道的挪亚一家八口。","notes":[]},{"n":6,"t":"又判定所多玛、蛾摩拉，将二城倾覆，焚烧成灰，作为后世不敬虔人的鉴戒；","notes":[]},{"n":7,"t":"只搭救了那常为恶人淫行忧伤的义人罗得。（","notes":[]},{"n":8,"t":"因为那义人住在他们中间，看见听见他们不法的事，他的义心就天天伤痛。）","notes":[]},{"n":9,"t":"主知道搭救敬虔的人脱离试探，把不义的人留在刑罚之下，等候审判的日子。","notes":[]},{"n":10,"t":"那些随肉身、纵污秽的情欲、轻慢主治之人的，更是如此。他们胆大任性，毁谤在尊位的，也不知惧怕。","notes":[]},{"n":11,"t":"就是天使，虽然力量权能更大，还不用毁谤的话在主面前告他们。","notes":[]},{"n":12,"t":"但这些人好像没有灵性，生来就是畜类，以备捉拿宰杀的。他们毁谤所不晓得的事，正在败坏人的时候，自己必遭遇败坏。","notes":[]},{"n":13,"t":"行的不义，就得了不义的工价。这些人喜爱白昼宴乐，他们已被玷污，又有瑕疵，正与你们一同坐席，就以自己的诡诈为快乐。","notes":[]},{"n":14,"t":"他们满眼是淫色，止不住犯罪，引诱那心不坚固的人，心中习惯了贪婪，正是被咒诅的种类。","notes":["原文是淫妇"]},{"n":15,"t":"他们离弃正路，就走差了，随从比珥之子巴兰的路。巴兰就是那贪爱不义之工价的先知，","notes":[]},{"n":16,"t":"他却为自己的过犯受了责备；那不能说话的驴以人言拦阻先知的狂妄。","notes":[]},{"n":17,"t":"这些人是无水的井，是狂风催逼的雾气，有墨黑的幽暗为他们存留。","notes":[]},{"n":18,"t":"他们说虚妄矜夸的大话，用肉身的情欲和邪淫的事引诱那些刚才脱离妄行的人。","notes":[]},{"n":19,"t":"他们应许人得以自由，自己却作败坏的奴仆，因为人被谁制伏就是谁的奴仆。","notes":[]},{"n":20,"t":"倘若他们因认识主—救主耶稣基督，得以脱离世上的污秽，后来又在其中被缠住、制伏，他们末后的景况就比先前更不好了。","notes":[]},{"n":21,"t":"他们晓得义路，竟背弃了传给他们的圣命，倒不如不晓得为妙。","notes":[]},{"n":22,"t":"俗语说得真不错：狗所吐的，它转过来又吃；猪洗净了又回到泥里去滚；这话在他们身上正合式。","notes":[]}]},"3":{"heading":"主再来的应许","verses":[{"n":1,"t":"亲爱的弟兄啊，我现在写给你们的是第二封信。这两封都是提醒你们，激发你们诚实的心，","notes":[]},{"n":2,"t":"叫你们记念圣先知预先所说的话和主救主的命令，就是使徒所传给你们的。","notes":[]},{"n":3,"t":"第一要紧的，该知道在末世必有好讥诮的人随从自己的私欲出来讥诮说：","notes":[]},{"n":4,"t":"「主要降临的应许在哪里呢？因为从列祖睡了以来，万物与起初创造的时候仍是一样。」","notes":[]},{"n":5,"t":"他们故意忘记，从太古，凭神的命有了天，并从水而出、借水而成的地。","notes":[]},{"n":6,"t":"故此，当时的世界被水淹没就消灭了。","notes":[]},{"n":7,"t":"但现在的天地还是凭着那命存留，直留到不敬虔之人受审判遭沉沦的日子，用火焚烧。","notes":[]},{"n":8,"t":"亲爱的弟兄啊，有一件事你们不可忘记，就是主看一日如千年，千年如一日。","notes":[]},{"n":9,"t":"主所应许的尚未成就，有人以为他是耽延，其实不是耽延，乃是宽容你们，不愿有一人沉沦，乃愿人人都悔改。","notes":[]},{"n":10,"t":"但主的日子要像贼来到一样。那日，天必大有响声废去，有形质的都要被烈火销化，地和其上的物都要烧尽了。","notes":[]},{"n":11,"t":"这一切既然都要如此销化，你们为人该当怎样圣洁，怎样敬虔，","notes":[]},{"n":12,"t":"切切仰望神的日子来到。在那日，天被火烧就销化了，有形质的都要被烈火熔化。","notes":[]},{"n":13,"t":"但我们照他的应许，盼望新天新地，有义居在其中。","notes":[]},{"n":14,"t":"亲爱的弟兄啊，你们既盼望这些事，就当殷勤，使自己没有玷污，无可指摘，安然见主；","notes":[]},{"n":15,"t":"并且要以我主长久忍耐为得救的因由，就如我们所亲爱的兄弟保罗，照着所赐给他的智慧写了信给你们。","notes":[]},{"n":16,"t":"他一切的信上也都是讲论这事。信中有些难明白的，那无学问、不坚固的人强解，如强解别的经书一样，就自取沉沦。","notes":[]},{"n":17,"t":"亲爱的弟兄啊，你们既然预先知道这事，就当防备，恐怕被恶人的错谬诱惑，就从自己坚固的地步上坠落。","notes":[]},{"n":18,"t":"你们却要在我们主—救主耶稣基督的恩典和知识上有长进。愿荣耀归给他，从今直到永远。阿们！","notes":[]}]}},"1JN":{"1":{"heading":"生命之道","verses":[{"n":1,"t":"论到从起初原有的生命之道，就是我们所听见、所看见、亲眼看过、亲手摸过的。（","notes":[]},{"n":2,"t":"这生命已经显现出来，我们也看见过，现在又作见证，将原与父同在、且显现与我们那永远的生命传给你们。）","notes":[]},{"n":3,"t":"我们将所看见、所听见的传给你们，使你们与我们相交。我们乃是与父并他儿子耶稣基督相交的。","notes":[]},{"n":4,"t":"我们将这些话写给你们，使你们的喜乐充足。","notes":["有古卷：我们"]},{"n":5,"t":"神就是光，在他毫无黑暗。这是我们从主所听见、又报给你们的信息。","notes":[],"heads":["神就是光"]},{"n":6,"t":"我们若说是与神相交，却仍在黑暗里行，就是说谎话，不行真理了。","notes":[]},{"n":7,"t":"我们若在光明中行，如同神在光明中，就彼此相交，他儿子耶稣的血也洗净我们一切的罪。","notes":[]},{"n":8,"t":"我们若说自己无罪，便是自欺，真理不在我们心里了。","notes":[]},{"n":9,"t":"我们若认自己的罪，神是信实的，是公义的，必要赦免我们的罪，洗净我们一切的不义。","notes":[]},{"n":10,"t":"我们若说自己没有犯过罪，便是以神为说谎的，他的道也不在我们心里了。","notes":[]}]},"2":{"heading":"我们的中保基督","verses":[{"n":1,"t":"我小子们哪，我将这些话写给你们，是要叫你们不犯罪。若有人犯罪，在父那里我们有一位中保，就是那义者耶稣基督。","notes":[]},{"n":2,"t":"他为我们的罪作了挽回祭，不是单为我们的罪，也是为普天下人的罪。","notes":[]},{"n":3,"t":"我们若遵守他的诫命，就晓得是认识他。","notes":[]},{"n":4,"t":"人若说「我认识他」，却不遵守他的诫命，便是说谎话的，真理也不在他心里了。","notes":[]},{"n":5,"t":"凡遵守主道的，爱神的心在他里面实在是完全的。从此，我们知道我们是在主里面。","notes":[]},{"n":6,"t":"人若说他住在主里面，就该自己照主所行的去行。","notes":[]},{"n":7,"t":"亲爱的弟兄啊，我写给你们的，不是一条新命令，乃是你们从起初所受的旧命令；这旧命令就是你们所听见的道。","notes":[],"heads":["新命令"]},{"n":8,"t":"再者，我写给你们的，是一条新命令，在主是真的，在你们也是真的；因为黑暗渐渐过去，真光已经照耀。","notes":[]},{"n":9,"t":"人若说自己在光明中，却恨他的弟兄，他到如今还是在黑暗里。","notes":[]},{"n":10,"t":"爱弟兄的，就是住在光明中，在他并没有绊跌的缘由。","notes":[]},{"n":11,"t":"惟独恨弟兄的，是在黑暗里，且在黑暗里行，也不知道往哪里去，因为黑暗叫他眼睛瞎了。","notes":[]},{"n":12,"t":"小子们哪，我写信给你们，因为你们的罪借着主名得了赦免。","notes":[]},{"n":13,"t":"父老啊，我写信给你们，因为你们认识那从起初原有的。少年人哪，我写信给你们，因为你们胜了那恶者。","notes":[]},{"n":14,"t":"小子们哪，我曾写信给你们，因为你们认识父。父老啊，我曾写信给你们，因为你们认识那从起初原有的。少年人哪，我曾写信给你们；因为你们刚强，神的道常存在你们心里；你们也胜了那恶者。","notes":[]},{"n":15,"t":"不要爱世界和世界上的事。人若爱世界，爱父的心就不在他里面了。","notes":[]},{"n":16,"t":"因为，凡世界上的事，就像肉体的情欲、眼目的情欲，并今生的骄傲，都不是从父来的，乃是从世界来的。","notes":[]},{"n":17,"t":"这世界和其上的情欲都要过去，惟独遵行神旨意的，是永远常存。","notes":[]},{"n":18,"t":"小子们哪，如今是末时了。你们曾听见说，那敌基督的要来；现在已经有好些敌基督的出来了，从此我们就知道如今是末时了。","notes":[],"heads":["敌基督者"]},{"n":19,"t":"他们从我们中间出去，却不是属我们的；若是属我们的，就必仍旧与我们同在；他们出去，显明都不是属我们的。","notes":[]},{"n":20,"t":"你们从那圣者受了恩膏，并且知道这一切的事。","notes":["或译：都有知识"]},{"n":21,"t":"我写信给你们，不是因你们不知道真理，正是因你们知道，并且知道没有虚谎是从真理出来的。","notes":[]},{"n":22,"t":"谁是说谎话的呢？不是那不认耶稣为基督的吗？不认父与子的，这就是敌基督的。","notes":[]},{"n":23,"t":"凡不认子的，就没有父；认子的，连父也有了。","notes":[]},{"n":24,"t":"论到你们，务要将那从起初所听见的，常存在心里。若将从起初所听见的存在心里，你们就必住在子里面，也必住在父里面。","notes":[]},{"n":25,"t":"主所应许我们的就是永生。","notes":[]},{"n":26,"t":"我将这些话写给你们，是指着那引诱你们的人说的。","notes":[]},{"n":27,"t":"你们从主所受的恩膏常存在你们心里，并不用人教训你们，自有主的恩膏在凡事上教训你们。这恩膏是真的，不是假的；你们要按这恩膏的教训住在主里面。","notes":[]},{"n":28,"t":"小子们哪，你们要住在主里面。这样，他若显现，我们就可以坦然无惧；当他来的时候，在他面前也不至于惭愧。","notes":[],"heads":["神的儿女"]},{"n":29,"t":"你们若知道他是公义的，就知道凡行公义之人都是他所生的。","notes":[]}]},"3":{"heading":"彼此相爱","verses":[{"n":1,"t":"你看父赐给我们是何等的慈爱，使我们得称为神的儿女；我们也真是他的儿女。世人所以不认识我们，是因未曾认识他。","notes":[]},{"n":2,"t":"亲爱的弟兄啊，我们现在是神的儿女，将来如何，还未显明；但我们知道，主若显现，我们必要像他，因为必得见他的真体。","notes":[]},{"n":3,"t":"凡向他有这指望的，就洁净自己，像他洁净一样。","notes":[]},{"n":4,"t":"凡犯罪的，就是违背律法；违背律法就是罪。","notes":[]},{"n":5,"t":"你们知道主曾显现，是要除掉人的罪，在他并没有罪。","notes":[]},{"n":6,"t":"凡住在他里面的，就不犯罪；凡犯罪的，是未曾看见他，也未曾认识他。","notes":[]},{"n":7,"t":"小子们哪，不要被人诱惑。行义的才是义人，正如主是义的一样。","notes":[]},{"n":8,"t":"犯罪的是属魔鬼，因为魔鬼从起初就犯罪。神的儿子显现出来，为要除灭魔鬼的作为。","notes":[]},{"n":9,"t":"凡从神生的，就不犯罪，因神的道存在他心里；他也不能犯罪，因为他是由神生的。","notes":["原文是种"]},{"n":10,"t":"从此就显出谁是神的儿女，谁是魔鬼的儿女。凡不行义的就不属神，不爱弟兄的也是如此。","notes":[]},{"n":11,"t":"我们应当彼此相爱。这就是你们从起初所听见的命令。","notes":[]},{"n":12,"t":"不可像该隐；他是属那恶者，杀了他的兄弟。为什么杀了他呢？因自己的行为是恶的，兄弟的行为是善的。","notes":[]},{"n":13,"t":"弟兄们，世人若恨你们，不要以为希奇。","notes":[]},{"n":14,"t":"我们因为爱弟兄，就晓得是已经出死入生了。没有爱心的，仍住在死中。","notes":[]},{"n":15,"t":"凡恨他弟兄的，就是杀人的；你们晓得凡杀人的，没有永生存在他里面。","notes":[]},{"n":16,"t":"主为我们舍命，我们从此就知道何为爱；我们也当为弟兄舍命。","notes":[]},{"n":17,"t":"凡有世上财物的，看见弟兄穷乏，却塞住怜恤的心，爱神的心怎能存在他里面呢？","notes":[]},{"n":18,"t":"小子们哪，我们相爱，不要只在言语和舌头上，总要在行为和诚实上。","notes":[]},{"n":19,"t":"从此就知道我们是属真理的，并且我们的心在神面前可以安稳。","notes":[],"heads":["在神面前安稳"]},{"n":20,"t":"我们的心若责备我们，神比我们的心大，一切事没有不知道的。","notes":[]},{"n":21,"t":"亲爱的弟兄啊，我们的心若不责备我们，就可以向神坦然无惧了。","notes":[]},{"n":22,"t":"并且我们一切所求的，就从他得着；因为我们遵守他的命令，行他所喜悦的事。","notes":[]},{"n":23,"t":"神的命令就是叫我们信他儿子耶稣基督的名，且照他所赐给我们的命令彼此相爱。","notes":[]},{"n":24,"t":"遵守神命令的，就住在神里面，神也住在他里面。我们所以知道神住在我们里面是因他所赐给我们的圣灵。","notes":[]}]},"4":{"heading":"神的灵和敌基督者的灵","verses":[{"n":1,"t":"亲爱的弟兄啊，一切的灵，你们不可都信，总要试验那些灵是出于神的不是，因为世上有许多假先知已经出来了。","notes":[]},{"n":2,"t":"凡灵认耶稣基督是成了肉身来的，就是出于神的；从此你们可以认出神的灵来。","notes":[]},{"n":3,"t":"凡灵不认耶稣，就不是出于神，这是那敌基督者的灵。你们从前听见他要来，现在已经在世上了。","notes":[]},{"n":4,"t":"小子们哪，你们是属神的，并且胜了他们；因为那在你们里面的，比那在世界上的更大。","notes":[]},{"n":5,"t":"他们是属世界的，所以论世界的事，世人也听从他们。","notes":[]},{"n":6,"t":"我们是属神的，认识神的就听从我们；不属神的就不听从我们。从此我们可以认出真理的灵和谬妄的灵来。","notes":[]},{"n":7,"t":"亲爱的弟兄啊，我们应当彼此相爱，因为爱是从神来的。凡有爱心的，都是由神而生，并且认识神。","notes":[],"heads":["神就是爱"]},{"n":8,"t":"没有爱心的，就不认识神，因为神就是爱。","notes":[]},{"n":9,"t":"神差他独生子到世间来，使我们借着他得生，神爱我们的心在此就显明了。","notes":[]},{"n":10,"t":"不是我们爱神，乃是神爱我们，差他的儿子为我们的罪作了挽回祭，这就是爱了。","notes":[]},{"n":11,"t":"亲爱的弟兄啊，神既是这样爱我们，我们也当彼此相爱。","notes":[]},{"n":12,"t":"从来没有人见过神，我们若彼此相爱，神就住在我们里面，爱他的心在我们里面得以完全了。","notes":[]},{"n":13,"t":"神将他的灵赐给我们，从此就知道我们是住在他里面，他也住在我们里面。","notes":[]},{"n":14,"t":"父差子作世人的救主；这是我们所看见且作见证的。","notes":[]},{"n":15,"t":"凡认耶稣为神儿子的，神就住在他里面，他也住在神里面。","notes":[]},{"n":16,"t":"神爱我们的心，我们也知道也信。神就是爱；住在爱里面的，就是住在神里面，神也住在他里面。","notes":[]},{"n":17,"t":"这样，爱在我们里面得以完全，我们就可以在审判的日子坦然无惧。因为他如何，我们在这世上也如何。","notes":[]},{"n":18,"t":"爱里没有惧怕；爱既完全，就把惧怕除去。因为惧怕里含着刑罚，惧怕的人在爱里未得完全。","notes":[]},{"n":19,"t":"我们爱，因为神先爱我们。","notes":[]},{"n":20,"t":"人若说「我爱神」，却恨他的弟兄，就是说谎话的；不爱他所看见的弟兄，就不能爱没有看见的神。","notes":["有古卷：怎能爱没有看见的神呢"]},{"n":21,"t":"爱神的，也当爱弟兄，这是我们从神所受的命令。","notes":[]}]},"5":{"heading":"胜了世界的就是信心","verses":[{"n":1,"t":"凡信耶稣是基督的，都是从神而生，凡爱生他之神的，也必爱从神生的。","notes":[]},{"n":2,"t":"我们若爱神，又遵守他的诫命，从此就知道我们爱神的儿女。","notes":[]},{"n":3,"t":"我们遵守神的诫命，这就是爱他了，并且他的诫命不是难守的。","notes":[]},{"n":4,"t":"因为凡从神生的，就胜过世界；使我们胜了世界的，就是我们的信心。","notes":[]},{"n":5,"t":"胜过世界的是谁呢？不是那信耶稣是神儿子的吗？","notes":[]},{"n":6,"t":"这借着水和血而来的，就是耶稣基督；不是单用水，乃是用水又用血，","notes":[],"heads":["神为他儿子作的见证"]},{"n":7,"t":"并且有圣灵作见证，因为圣灵就是真理。","notes":[]},{"n":8,"t":"作见证的原来有三：就是圣灵、水，与血，这三样也都归于一。","notes":[]},{"n":9,"t":"我们既领受人的见证，神的见证更该领受了，因神的见证是为他儿子作的。","notes":["该领受：原文是大"]},{"n":10,"t":"信神儿子的，就有这见证在他心里；不信神的，就是将神当作说谎的，因不信神为他儿子作的见证。","notes":[]},{"n":11,"t":"这见证就是神赐给我们永生；这永生也是在他儿子里面。","notes":[]},{"n":12,"t":"人有了神的儿子就有生命，没有神的儿子就没有生命。","notes":[]},{"n":13,"t":"我将这些话写给你们信奉神儿子之名的人，要叫你们知道自己有永生。","notes":[],"heads":["知道自己有永生"]},{"n":14,"t":"我们若照他的旨意求什么，他就听我们，这是我们向他所存坦然无惧的心。","notes":[]},{"n":15,"t":"既然知道他听我们一切所求的，就知道我们所求于他的，无不得着。","notes":[]},{"n":16,"t":"人若看见弟兄犯了不至于死的罪，就当为他祈求，神必将生命赐给他；有至于死的罪，我不说当为这罪祈求。","notes":[]},{"n":17,"t":"凡不义的事都是罪，也有不至于死的罪。","notes":[]},{"n":18,"t":"我们知道凡从神生的，必不犯罪，从神生的，必保守自己，那恶者也就无法害他。","notes":["有古卷：那从神生的必保护他"]},{"n":19,"t":"我们知道，我们是属神的，全世界都卧在那恶者手下。","notes":[]},{"n":20,"t":"我们也知道，神的儿子已经来到，且将智慧赐给我们，使我们认识那位真实的，我们也在那位真实的里面，就是在他儿子耶稣基督里面。这是真神，也是永生。","notes":[]},{"n":21,"t":"小子们哪，你们要自守，远避偶像！","notes":[]}]}},"2JN":{"1":{"heading":"问候","verses":[{"n":1,"t":"作长老的写信给蒙拣选的太太和她的儿女，就是我诚心所爱的；不但我爱，也是一切知道真理之人所爱的。","notes":["或译：教会；下同"]},{"n":2,"t":"爱你们是为真理的缘故，这真理存在我们里面，也必永远与我们同在。","notes":[]},{"n":3,"t":"恩惠、怜悯、平安从父神和他儿子耶稣基督在真理和爱心上必常与我们同在！","notes":[]},{"n":4,"t":"我见你的儿女，有照我们从父所受之命令遵行真理的，就甚欢喜。","notes":[],"heads":["真理和爱"]},{"n":5,"t":"太太啊，我现在劝你，我们大家要彼此相爱。这并不是我写一条新命令给你，乃是我们从起初所受的命令。","notes":[]},{"n":6,"t":"我们若照他的命令行，这就是爱。你们从起初所听见当行的，就是这命令。","notes":[]},{"n":7,"t":"因为世上有许多迷惑人的出来，他们不认耶稣基督是成了肉身来的；这就是那迷惑人、敌基督的。","notes":[]},{"n":8,"t":"你们要小心，不要失去你们所做的工，乃要得着满足的赏赐。","notes":["有古卷：我们"]},{"n":9,"t":"凡越过基督的教训不常守着的，就没有神；常守这教训的，就有父又有子。","notes":[]},{"n":10,"t":"若有人到你们那里，不是传这教训，不要接他到家里，也不要问他的安；","notes":[]},{"n":11,"t":"因为问他安的，就在他的恶行上有分。","notes":[]},{"n":12,"t":"我还有许多事要写给你们，却不愿意用纸墨写出来，但盼望到你们那里，与你们当面谈论，使你们的喜乐满足。","notes":[],"heads":["问安"]},{"n":13,"t":"你那蒙拣选之姊妹的儿女都问你安。","notes":[]}]}},"3JN":{"1":{"heading":"问候","verses":[{"n":1,"t":"作长老的写信给亲爱的该犹，就是我诚心所爱的。","notes":[]},{"n":2,"t":"亲爱的兄弟啊，我愿你凡事兴盛，身体健壮，正如你的灵魂兴盛一样。","notes":[]},{"n":3,"t":"有弟兄来证明你心里存的真理，正如你按真理而行，我就甚喜乐。","notes":[]},{"n":4,"t":"我听见我的儿女们按真理而行，我的喜乐就没有比这个大的。","notes":[]},{"n":5,"t":"亲爱的兄弟啊，凡你向作客旅之弟兄所行的都是忠心的。","notes":[],"heads":["合作和反对"]},{"n":6,"t":"他们在教会面前证明了你的爱；你若配得过神，帮助他们往前行，这就好了。","notes":[]},{"n":7,"t":"因他们是为主的名出外，对于外邦人一无所取。","notes":["原文是那名"]},{"n":8,"t":"所以我们应该接待这样的人，叫我们与他们一同为真理做工。","notes":[]},{"n":9,"t":"我曾略略地写信给教会，但那在教会中好为首的丢特腓不接待我们。","notes":[]},{"n":10,"t":"所以我若去，必要提说他所行的事，就是他用恶言妄论我们。还不以此为足，他自己不接待弟兄，有人愿意接待，他也禁止，并且将接待弟兄的人赶出教会。","notes":[]},{"n":11,"t":"亲爱的兄弟啊，不要效法恶，只要效法善。行善的属乎神；行恶的未曾见过神。","notes":[]},{"n":12,"t":"低米丢行善，有众人给他作见证，又有真理给他作见证，就是我们也给他作见证。你也知道我们的见证是真的。","notes":[]},{"n":13,"t":"我原有许多事要写给你，却不愿意用笔墨写给你，","notes":[],"heads":["问安"]},{"n":14,"t":"但盼望快快地见你，我们就当面谈论。","notes":[]},{"n":15,"t":"愿你平安。众位朋友都问你安。请你替我按着姓名问众位朋友安。","notes":[]}]}},"JUD":{"1":{"heading":"假教师的刑罚","verses":[{"n":1,"t":"耶稣基督的仆人，雅各的弟兄犹大，写信给那被召、在父神里蒙爱、为耶稣基督保守的人。","notes":[]},{"n":2,"t":"愿怜恤、平安、慈爱多多地加给你们。","notes":[]},{"n":3,"t":"亲爱的弟兄啊，我想尽心写信给你们，论我们同得救恩的时候，就不得不写信劝你们，要为从前一次交付圣徒的真道竭力地争辩。","notes":[]},{"n":4,"t":"因为有些人偷着进来，就是自古被定受刑罚的，是不虔诚的，将我们神的恩变作放纵情欲的机会，并且不认独一的主宰—我们主耶稣基督。","notes":["或译和我们"]},{"n":5,"t":"从前主救了他的百姓出埃及地，后来就把那些不信的灭绝了。这一切的事，你们虽然都知道，我却仍要提醒你们。","notes":[]},{"n":6,"t":"又有不守本位、离开自己住处的天使，主用锁链把他们永远拘留在黑暗里，等候大日的审判。","notes":[]},{"n":7,"t":"又如所多玛、蛾摩拉和周围城邑的人，也照他们一味地行淫，随从逆性的情欲，就受永火的刑罚，作为鉴戒。","notes":[]},{"n":8,"t":"这些作梦的人也像他们污秽身体，轻慢主治的，毁谤在尊位的。","notes":[]},{"n":9,"t":"天使长米迦勒为摩西的尸首与魔鬼争辩的时候，尚且不敢用毁谤的话罪责他，只说：「主责备你吧！」。","notes":[]},{"n":10,"t":"但这些人毁谤他们所不知道的。他们本性所知道的事与那没有灵性的畜类一样，在这事上竟败坏了自己。","notes":[]},{"n":11,"t":"他们有祸了！因为走了该隐的道路，又为利往巴兰的错谬里直奔，并在可拉的背叛中灭亡了。","notes":[]},{"n":12,"t":"这样的人在你们的爱席上与你们同吃的时候，正是礁石。他们作牧人，只知喂养自己，无所惧怕；是没有雨的云彩，被风飘荡；是秋天没有果子的树，死而又死，连根被拔出来；","notes":["或译：玷污"]},{"n":13,"t":"是海里的狂浪，涌出自己可耻的沫子来；是流荡的星，有墨黑的幽暗为他们永远存留。","notes":[]},{"n":14,"t":"亚当的七世孙以诺曾预言这些人说：「看哪，主带着他的千万圣者降临，","notes":[]},{"n":15,"t":"要在众人身上行审判，证实那一切不敬虔的人所妄行一切不敬虔的事，又证实不敬虔之罪人所说顶撞他的刚愎话。」","notes":[]},{"n":16,"t":"这些人是私下议论，常发怨言的，随从自己的情欲而行，口中说夸大的话，为得便宜谄媚人。","notes":[]},{"n":17,"t":"亲爱的弟兄啊，你们要记念我们主耶稣基督之使徒从前所说的话。","notes":[],"heads":["警告和劝勉"]},{"n":18,"t":"他们曾对你们说过，末世必有好讥诮的人随从自己不敬虔的私欲而行。","notes":[]},{"n":19,"t":"这就是那些引人结党、属乎血气、没有圣灵的人。","notes":[]},{"n":20,"t":"亲爱的弟兄啊，你们却要在至圣的真道上造就自己，在圣灵里祷告，","notes":[]},{"n":21,"t":"保守自己常在神的爱中，仰望我们主耶稣基督的怜悯，直到永生。","notes":[]},{"n":22,"t":"有些人存疑心，你们要怜悯他们；","notes":[]},{"n":23,"t":"有些人你们要从火中抢出来，搭救他们；有些人你们要存惧怕的心怜悯他们，连那被情欲沾染的衣服也当厌恶。","notes":[]},{"n":24,"t":"那能保守你们不失脚、叫你们无瑕无疵、欢欢喜喜站在他荣耀之前的我们的救主—独一的神，","notes":[],"heads":["祝福"]},{"n":25,"t":"愿荣耀、威严、能力、权柄，因我们的主耶稣基督归与他，从万古以前并现今，直到永永远远。阿们！","notes":[]}]}},"REV":{"1":{"heading":"引言和致意","verses":[{"n":1,"t":"耶稣基督的启示，就是神赐给他，叫他将必要快成的事指示他的众仆人。他就差遣使者晓谕他的仆人约翰。","notes":[]},{"n":2,"t":"约翰便将神的道和耶稣基督的见证，凡自己所看见的都证明出来。","notes":[]},{"n":3,"t":"念这书上预言的和那些听见又遵守其中所记载的，都是有福的，因为日期近了。","notes":[]},{"n":4,"t":"约翰写信给亚细亚的七个教会。但愿从那昔在、今在、以后永在的神，和他宝座前的七灵，","notes":[]},{"n":5,"t":"并那诚实作见证的、从死里首先复活、为世上君王元首的耶稣基督，有恩惠、平安归与你们！他爱我们，用自己的血使我们脱离罪恶，","notes":["有古卷：洗去"]},{"n":6,"t":"又使我们成为国民，作他父神的祭司。但愿荣耀、权能归给他，直到永永远远。阿们！","notes":[]},{"n":7,"t":"看哪，他驾云降临！众目要看见他，连刺他的人也要看见他；地上的万族都要因他哀哭。这话是真实的。阿们！","notes":[]},{"n":8,"t":"主神说：「我是阿拉法，我是俄梅戛，是昔在、今在、以后永在的全能者。」","notes":["阿拉法，俄梅戛：是希腊字母首末二字"]},{"n":9,"t":"我—约翰就是你们的弟兄，和你们在耶稣的患难、国度、忍耐里一同有分，为神的道，并为给耶稣作的见证，曾在那名叫拔摩的海岛上。","notes":[],"heads":["基督的异象"]},{"n":10,"t":"当主日，我被圣灵感动，听见在我后面有大声音如吹号，说：","notes":[]},{"n":11,"t":"「你所看见的当写在书上，达与以弗所、士每拿、别迦摩、推雅推喇、撒狄、非拉铁非、老底嘉那七个教会。」","notes":[]},{"n":12,"t":"我转过身来，要看是谁发声与我说话；既转过来，就看见七个金灯台。","notes":[]},{"n":13,"t":"灯台中间有一位好像人子，身穿长衣，直垂到脚，胸间束着金带。","notes":[]},{"n":14,"t":"他的头与发皆白，如白羊毛，如雪；眼目如同火焰；","notes":[]},{"n":15,"t":"脚好像在炉中锻炼光明的铜；声音如同众水的声音。","notes":[]},{"n":16,"t":"他右手拿着七星，从他口中出来一把两刃的利剑；面貌如同烈日放光。","notes":[]},{"n":17,"t":"我一看见，就仆倒在他脚前，像死了一样。他用右手按着我，说：「不要惧怕！我是首先的，我是末后的，","notes":[]},{"n":18,"t":"又是那存活的；我曾死过，现在又活了，直活到永永远远；并且拿着死亡和阴间的钥匙。","notes":[]},{"n":19,"t":"所以你要把所看见的，和现在的事，并将来必成的事，都写出来。","notes":[]},{"n":20,"t":"论到你所看见、在我右手中的七星和七个金灯台的奥秘，那七星就是七个教会的使者，七灯台就是七个教会。」","notes":[]}]},"2":{"heading":"给以弗所教会的信","verses":[{"n":1,"t":"「你要写信给以弗所教会的使者，说：『那右手拿着七星、在七个金灯台中间行走的，说：","notes":[]},{"n":2,"t":"我知道你的行为、劳碌、忍耐，也知道你不能容忍恶人。你也曾试验那自称为使徒却不是使徒的，看出他们是假的来。","notes":[]},{"n":3,"t":"你也能忍耐，曾为我的名劳苦，并不乏倦。","notes":[]},{"n":4,"t":"然而有一件事我要责备你，就是你把起初的爱心离弃了。","notes":[]},{"n":5,"t":"所以，应当回想你是从哪里坠落的，并要悔改，行起初所行的事。你若不悔改，我就临到你那里，把你的灯台从原处挪去。","notes":[]},{"n":6,"t":"然而你还有一件可取的事，就是你恨恶尼哥拉一党人的行为，这也是我所恨恶的。","notes":[]},{"n":7,"t":"圣灵向众教会所说的话，凡有耳的，就应当听！得胜的，我必将神乐园中生命树的果子赐给他吃。』」","notes":[]},{"n":8,"t":"「你要写信给士每拿教会的使者，说：『那首先的、末后的、死过又活的，说：","notes":[],"heads":["给士每拿教会的信"]},{"n":9,"t":"我知道你的患难，你的贫穷（你却是富足的），也知道那自称是犹太人所说的毁谤话，其实他们不是犹太人，乃是撒但一会的人。","notes":[]},{"n":10,"t":"你将要受的苦你不用怕。魔鬼要把你们中间几个人下在监里，叫你们被试炼，你们必受患难十日。你务要至死忠心，我就赐给你那生命的冠冕。","notes":[]},{"n":11,"t":"圣灵向众教会所说的话，凡有耳的，就应当听！得胜的，必不受第二次死的害。』」","notes":[]},{"n":12,"t":"「你要写信给别迦摩教会的使者，说：『那有两刃利剑的，说：","notes":[],"heads":["给别迦摩教会的信"]},{"n":13,"t":"我知道你的居所，就是有撒但座位之处；当我忠心的见证人安提帕在你们中间、撒但所住的地方被杀之时，你还坚守我的名，没有弃绝我的道。","notes":[]},{"n":14,"t":"然而，有几件事我要责备你：因为在你那里有人服从了巴兰的教训；这巴兰曾教导巴勒将绊脚石放在以色列人面前，叫他们吃祭偶像之物，行奸淫的事。","notes":[]},{"n":15,"t":"你那里也有人照样服从了尼哥拉一党人的教训。","notes":[]},{"n":16,"t":"所以，你当悔改；若不悔改，我就快临到你那里，用我口中的剑攻击他们。","notes":[]},{"n":17,"t":"圣灵向众教会所说的话，凡有耳的，就应当听！得胜的，我必将那隐藏的吗哪赐给他，并赐他一块白石，石上写着新名；除了那领受的以外，没有人能认识。』」","notes":[]},{"n":18,"t":"「你要写信给推雅推喇教会的使者，说：『那眼目如火焰、脚像光明铜的神之子说：","notes":[],"heads":["给推雅推喇教会的信"]},{"n":19,"t":"我知道你的行为、爱心、信心、勤劳、忍耐，又知道你末后所行的善事，比起初所行的更多。","notes":[]},{"n":20,"t":"然而，有一件事我要责备你，就是你容让那自称是先知的妇人耶洗别教导我的仆人，引诱他们行奸淫，吃祭偶像之物。","notes":[]},{"n":21,"t":"我曾给她悔改的机会，她却不肯悔改她的淫行。","notes":[]},{"n":22,"t":"看哪，我要叫她病卧在床。那些与她行淫的人，若不悔改所行的，我也要叫他们同受大患难。","notes":[]},{"n":23,"t":"我又要杀死她的党类，叫众教会知道，我是那察看人肺腑心肠的，并要照你们的行为报应你们各人。","notes":["原文是儿女"]},{"n":24,"t":"至于你们推雅推喇其余的人，就是一切不从那教训、不晓得他们素常所说撒但深奥之理的人，我告诉你们，我不将别的担子放在你们身上。","notes":[]},{"n":25,"t":"但你们已经有的，总要持守，直等到我来。","notes":[]},{"n":26,"t":"那得胜又遵守我命令到底的，我要赐给他权柄制伏列国；","notes":[]},{"n":27,"t":"他必用铁杖辖管他们，将他们如同窑户的瓦器打得粉碎，像我从我父领受的权柄一样。","notes":["辖管：原文是牧"]},{"n":28,"t":"我又要把晨星赐给他。","notes":[]},{"n":29,"t":"圣灵向众教会所说的话，凡有耳的，就应当听！』」","notes":[]}]},"3":{"heading":"给撒狄教会的信","verses":[{"n":1,"t":"「你要写信给撒狄教会的使者，说：『那有神的七灵和七星的，说：我知道你的行为，按名你是活的，其实是死的。","notes":[]},{"n":2,"t":"你要警醒，坚固那剩下将要衰微的；因我见你的行为，在我神面前，没有一样是完全的。","notes":["原文是死"]},{"n":3,"t":"所以要回想你是怎样领受、怎样听见的，又要遵守，并要悔改。若不警醒，我必临到你那里，如同贼一样。我几时临到，你也决不能知道。","notes":[]},{"n":4,"t":"然而在撒狄，你还有几名是未曾污秽自己衣服的，他们要穿白衣与我同行，因为他们是配得过的。","notes":[]},{"n":5,"t":"凡得胜的必这样穿白衣，我也必不从生命册上涂抹他的名；且要在我父面前，和我父众使者面前，认他的名。","notes":[]},{"n":6,"t":"圣灵向众教会所说的话，凡有耳的，就应当听！』」","notes":[]},{"n":7,"t":"「你要写信给非拉铁非教会的使者，说：『那圣洁、真实、拿着大卫的钥匙、开了就没有人能关、关了就没有人能开的，说：","notes":[],"heads":["给非拉铁非教会的信"]},{"n":8,"t":"我知道你的行为，你略有一点力量，也曾遵守我的道，没有弃绝我的名。看哪，我在你面前给你一个敞开的门，是无人能关的。","notes":[]},{"n":9,"t":"那撒但一会的，自称是犹太人，其实不是犹太人，乃是说谎话的，我要使他们来，在你脚前下拜，也使他们知道我是已经爱你了。","notes":[]},{"n":10,"t":"你既遵守我忍耐的道，我必在普天下人受试炼的时候，保守你免去你的试炼。","notes":[]},{"n":11,"t":"我必快来，你要持守你所有的，免得人夺去你的冠冕。","notes":[]},{"n":12,"t":"得胜的，我要叫他在我神殿中作柱子，他也必不再从那里出去。我又要将我神的名和我神城的名（这城就是从天上、从我神那里降下来的新耶路撒冷），并我的新名，都写在他上面。","notes":[]},{"n":13,"t":"圣灵向众教会所说的话，凡有耳的，就应当听！』」","notes":[]},{"n":14,"t":"「你要写信给老底嘉教会的使者，说：『那为阿们的，为诚信真实见证的，在神创造万物之上为元首的，说：","notes":[],"heads":["给老底嘉教会的信"]},{"n":15,"t":"我知道你的行为，你也不冷也不热；我巴不得你或冷或热。","notes":[]},{"n":16,"t":"你既如温水，也不冷也不热，所以我必从我口中把你吐出去。","notes":[]},{"n":17,"t":"你说：我是富足，已经发了财，一样都不缺；却不知道你是那困苦、可怜、贫穷、瞎眼、赤身的。","notes":[]},{"n":18,"t":"我劝你向我买火炼的金子，叫你富足；又买白衣穿上，叫你赤身的羞耻不露出来；又买眼药擦你的眼睛，使你能看见。","notes":[]},{"n":19,"t":"凡我所疼爱的，我就责备管教他；所以你要发热心，也要悔改。","notes":[]},{"n":20,"t":"看哪，我站在门外叩门，若有听见我声音就开门的，我要进到他那里去，我与他，他与我一同坐席。","notes":[]},{"n":21,"t":"得胜的，我要赐他在我宝座上与我同坐，就如我得了胜，在我父的宝座上与他同坐一般。","notes":[]},{"n":22,"t":"圣灵向众教会所说的话，凡有耳的，就应当听！』」","notes":[]}]},"4":{"heading":"天上的敬拜","verses":[{"n":1,"t":"此后，我观看，见天上有门开了。我初次听见好像吹号的声音，对我说：「你上到这里来，我要将以后必成的事指示你。」","notes":[]},{"n":2,"t":"我立刻被圣灵感动，见有一个宝座安置在天上，又有一位坐在宝座上。","notes":[]},{"n":3,"t":"看那坐着的，好像碧玉和红宝石；又有虹围着宝座，好像绿宝石。","notes":[]},{"n":4,"t":"宝座的周围又有二十四个座位；其上坐着二十四位长老，身穿白衣，头上戴着金冠冕。","notes":[]},{"n":5,"t":"有闪电、声音、雷轰从宝座中发出；又有七盏火灯在宝座前点着；这七灯就是神的七灵。","notes":[]},{"n":6,"t":"宝座前好像一个玻璃海，如同水晶。宝座中和宝座周围有四个活物，前后遍体都满了眼睛。","notes":[]},{"n":7,"t":"第一个活物像狮子，第二个像牛犊，第三个脸面像人，第四个像飞鹰。","notes":[]},{"n":8,"t":"四活物各有六个翅膀，遍体内外都满了眼睛。他们昼夜不住地说：圣哉！圣哉！圣哉！主神是昔在、今在、以后永在的全能者。","notes":[]},{"n":9,"t":"每逢四活物将荣耀、尊贵、感谢归给那坐在宝座上、活到永永远远者的时候，","notes":[]},{"n":10,"t":"那二十四位长老就俯伏在坐宝座的面前敬拜那活到永永远远的，又把他们的冠冕放在宝座前，说：","notes":[]},{"n":11,"t":"我们的主，我们的神，你是配得荣耀、尊贵、权柄的；因为你创造了万物，并且万物是因你的旨意被创造而有的。","notes":[]}]},"5":{"heading":"书卷和羔羊","verses":[{"n":1,"t":"我看见坐宝座的右手中有书卷，里外都写着字，用七印封严了。","notes":[]},{"n":2,"t":"我又看见一位大力的天使大声宣传说：「有谁配展开那书卷，揭开那七印呢？」","notes":[]},{"n":3,"t":"在天上、地上、地底下，没有能展开、能观看那书卷的。","notes":[]},{"n":4,"t":"因为没有配展开、配观看那书卷的，我就大哭。","notes":[]},{"n":5,"t":"长老中有一位对我说：「不要哭！看哪，犹大支派中的狮子，大卫的根，他已得胜，能以展开那书卷，揭开那七印。」","notes":[]},{"n":6,"t":"我又看见宝座与四活物，并长老之中有羔羊站立，像是被杀过的，有七角七眼，就是神的七灵，奉差遣往普天下去的。","notes":[]},{"n":7,"t":"这羔羊前来，从坐宝座的右手里拿了书卷。","notes":[]},{"n":8,"t":"他既拿了书卷，四活物和二十四位长老就俯伏在羔羊面前，各拿着琴和盛满了香的金炉；这香就是众圣徒的祈祷。","notes":[]},{"n":9,"t":"他们唱新歌，说：你配拿书卷，配揭开七印；因为你曾被杀，用自己的血从各族、各方、各民、各国中买了人来，叫他们归于神，","notes":[]},{"n":10,"t":"又叫他们成为国民，作祭司归于神，在地上执掌王权。","notes":[]},{"n":11,"t":"我又看见且听见，宝座与活物并长老的周围有许多天使的声音；他们的数目有千千万万，","notes":[]},{"n":12,"t":"大声说：曾被杀的羔羊是配得权柄、丰富、智慧、能力、尊贵、荣耀、颂赞的。","notes":[]},{"n":13,"t":"我又听见在天上、地上、地底下、沧海里，和天地间一切所有被造之物，都说：但愿颂赞、尊贵、荣耀、权势都归给坐宝座的和羔羊，直到永永远远！","notes":[]},{"n":14,"t":"四活物就说：「阿们！」众长老也俯伏敬拜。","notes":[]}]},"6":{"heading":"揭开封严的印","verses":[{"n":1,"t":"我看见羔羊揭开七印中第一印的时候，就听见四活物中的一个活物，声音如雷，说：「你来！」","notes":[]},{"n":2,"t":"我就观看，见有一匹白马；骑在马上的，拿着弓，并有冠冕赐给他。他便出来，胜了又要胜。","notes":[]},{"n":3,"t":"揭开第二印的时候，我听见第二个活物说：「你来！」","notes":[]},{"n":4,"t":"就另有一匹马出来，是红的，有权柄给了那骑马的，可以从地上夺去太平，使人彼此相杀；又有一把大刀赐给他。","notes":[]},{"n":5,"t":"揭开第三印的时候，我听见第三个活物说：「你来！」我就观看，见有一匹黑马；骑在马上的，手里拿着天平。","notes":[]},{"n":6,"t":"我听见在四活物中似乎有声音说：「一钱银子买一升麦子，一钱银子买三升大麦；油和酒不可糟蹋。」","notes":[]},{"n":7,"t":"揭开第四印的时候，我听见第四个活物说：「你来！」","notes":[]},{"n":8,"t":"我就观看，见有一匹灰色马；骑在马上的，名字叫作死，阴府也随着他；有权柄赐给他们，可以用刀剑、饥荒、瘟疫、野兽，杀害地上四分之一的人。","notes":["或译：死亡"]},{"n":9,"t":"揭开第五印的时候，我看见在祭坛底下，有为神的道、并为作见证被杀之人的灵魂，","notes":[]},{"n":10,"t":"大声喊着说：「圣洁真实的主啊，你不审判住在地上的人，给我们伸流血的冤，要等到几时呢？」","notes":[]},{"n":11,"t":"于是有白衣赐给他们各人；又有话对他们说，还要安息片时，等着一同作仆人的和他们的弟兄也像他们被杀，满足了数目。","notes":[]},{"n":12,"t":"揭开第六印的时候，我又看见地大震动，日头变黑像毛布，满月变红像血，","notes":[]},{"n":13,"t":"天上的星辰坠落于地，如同无花果树被大风摇动，落下未熟的果子一样。","notes":[]},{"n":14,"t":"天就挪移，好像书卷被卷起来；山岭海岛都被挪移离开本位。","notes":[]},{"n":15,"t":"地上的君王、臣宰、将军、富户、壮士，和一切为奴的、自主的，都藏在山洞和岩石穴里，","notes":[]},{"n":16,"t":"向山和岩石说：「倒在我们身上吧！把我们藏起来，躲避坐宝座者的面目和羔羊的忿怒；","notes":[]},{"n":17,"t":"因为他们忿怒的大日到了，谁能站得住呢？」","notes":[]}]},"7":{"heading":"以色列人十四万四千被印","verses":[{"n":1,"t":"此后，我看见四位天使站在地的四角，执掌地上四方的风，叫风不吹在地上、海上，和树上。","notes":[]},{"n":2,"t":"我又看见另有一位天使，从日出之地上来，拿着永生神的印。他就向那得着权柄能伤害地和海的四位天使大声喊着说：","notes":[]},{"n":3,"t":"「地与海并树木，你们不可伤害，等我们印了我们神众仆人的额。」","notes":[]},{"n":4,"t":"我听见以色列人各支派中受印的数目有十四万四千。","notes":[]},{"n":5,"t":"犹大支派中受印的有一万二千；吕便支派中有一万二千；迦得支派中有一万二千；","notes":[]},{"n":6,"t":"亚设支派中有一万二千；拿弗他利支派中有一万二千；玛拿西支派中有一万二千；","notes":[]},{"n":7,"t":"西缅支派中有一万二千；利未支派中有一万二千；以萨迦支派中有一万二千；","notes":[]},{"n":8,"t":"西布伦支派中有一万二千；约瑟支派中有一万二千；便雅悯支派中受印的有一万二千。","notes":[]},{"n":9,"t":"此后，我观看，见有许多的人，没有人能数过来，是从各国、各族、各民、各方来的，站在宝座和羔羊面前，身穿白衣，手拿棕树枝，","notes":[],"heads":["无数的人从各国各族而来"]},{"n":10,"t":"大声喊着说：「愿救恩归与坐在宝座上我们的神，也归与羔羊！」","notes":[]},{"n":11,"t":"众天使都站在宝座和众长老并四活物的周围，在宝座前，面伏于地，敬拜神，","notes":[]},{"n":12,"t":"说：阿们！颂赞、荣耀、智慧、感谢、尊贵、权柄、大力都归与我们的神，直到永永远远。阿们！","notes":[]},{"n":13,"t":"长老中有一位问我说：「这些穿白衣的是谁？是从哪里来的？」","notes":[]},{"n":14,"t":"我对他说：「我主，你知道。」他向我说：「这些人是从大患难中出来的，曾用羔羊的血把衣裳洗白净了。","notes":[]},{"n":15,"t":"所以，他们在神宝座前，昼夜在他殿中事奉他。坐宝座的要用帐幕覆庇他们。","notes":[]},{"n":16,"t":"他们不再饥，不再渴；日头和炎热也必不伤害他们。","notes":[]},{"n":17,"t":"因为宝座中的羔羊必牧养他们，领他们到生命水的泉源；神也必擦去他们一切的眼泪。」","notes":[]}]},"8":{"heading":"第七印和香炉","verses":[{"n":1,"t":"羔羊揭开第七印的时候，天上寂静约有二刻。","notes":[]},{"n":2,"t":"我看见那站在神面前的七位天使，有七枝号赐给他们。","notes":[]},{"n":3,"t":"另有一位天使，拿着金香炉来，站在祭坛旁边。有许多香赐给他，要和众圣徒的祈祷一同献在宝座前的金坛上。","notes":[]},{"n":4,"t":"那香的烟和众圣徒的祈祷从天使的手中一同升到神面前。","notes":[]},{"n":5,"t":"天使拿着香炉，盛满了坛上的火，倒在地上；随有雷轰、大声、闪电、地震。","notes":[]},{"n":6,"t":"拿着七枝号的七位天使就预备要吹。","notes":[],"heads":["七号"]},{"n":7,"t":"第一位天使吹号，就有雹子与火搀着血丢在地上；地的三分之一和树的三分之一被烧了，一切的青草也被烧了。","notes":[]},{"n":8,"t":"第二位天使吹号，就有仿佛火烧着的大山扔在海中；海的三分之一变成血，","notes":[]},{"n":9,"t":"海中的活物死了三分之一，船只也坏了三分之一。","notes":[]},{"n":10,"t":"第三位天使吹号，就有烧着的大星，好像火把从天上落下来，落在江河的三分之一和众水的泉源上。","notes":[]},{"n":11,"t":"（这星名叫「茵陈」。）众水的三分之一变为茵陈，因水变苦，就死了许多人。","notes":[]},{"n":12,"t":"第四位天使吹号，日头的三分之一、月亮的三分之一、星辰的三分之一都被击打，以致日月星的三分之一黑暗了，白昼的三分之一没有光，黑夜也是这样。","notes":[]},{"n":13,"t":"我又看见一个鹰飞在空中，并听见它大声说：「三位天使要吹那其余的号。你们住在地上的民，祸哉！祸哉！祸哉！」","notes":[]}]},"9":{"heading":"","verses":[{"n":1,"t":"第五位天使吹号，我就看见一个星从天落到地上，有无底坑的钥匙赐给它。","notes":[]},{"n":2,"t":"它开了无底坑，便有烟从坑里往上冒，好像大火炉的烟；日头和天空都因这烟昏暗了。","notes":[]},{"n":3,"t":"有蝗虫从烟中出来，飞到地上；有能力赐给它们，好像地上蝎子的能力一样，","notes":[]},{"n":4,"t":"并且吩咐它们说，不可伤害地上的草和各样青物，并一切树木，惟独要伤害额上没有神印记的人。","notes":[]},{"n":5,"t":"但不许蝗虫害死他们，只叫他们受痛苦五个月。这痛苦就像蝎子螫人的痛苦一样。","notes":[]},{"n":6,"t":"在那些日子，人要求死，决不得死；愿意死，死却远避他们。","notes":[]},{"n":7,"t":"蝗虫的形状，好像预备出战的马一样，头上戴的好像金冠冕，脸面好像男人的脸面，","notes":[]},{"n":8,"t":"头发像女人的头发，牙齿像狮子的牙齿。","notes":[]},{"n":9,"t":"胸前有甲，好像铁甲。它们翅膀的声音，好像许多车马奔跑上阵的声音。","notes":[]},{"n":10,"t":"有尾巴像蝎子，尾巴上的毒钩能伤人五个月。","notes":[]},{"n":11,"t":"有无底坑的使者作它们的王，按着希伯来话，名叫亚巴顿，希腊话，名叫亚玻伦。","notes":[]},{"n":12,"t":"第一样灾祸过去了，还有两样灾祸要来。","notes":[]},{"n":13,"t":"第六位天使吹号，我就听见有声音从神面前金坛的四角出来，","notes":[]},{"n":14,"t":"吩咐那吹号的第六位天使，说：「把那捆绑在幼发拉底大河的四个使者释放了。」","notes":[]},{"n":15,"t":"那四个使者就被释放；他们原是预备好了，到某年某月某日某时，要杀人的三分之一。","notes":[]},{"n":16,"t":"马军有二万万；他们的数目我听见了。","notes":[]},{"n":17,"t":"我在异象中看见那些马和骑马的，骑马的胸前有甲如火，与紫玛瑙并硫磺。马的头好像狮子头，有火、有烟、有硫磺从马的口中出来。","notes":[]},{"n":18,"t":"口中所出来的火与烟并硫磺，这三样灾杀了人的三分之一。","notes":[]},{"n":19,"t":"这马的能力是在口里和尾巴上；因这尾巴像蛇，并且有头用以害人。","notes":[]},{"n":20,"t":"其余未曾被这些灾所杀的人仍旧不悔改自己手所做的，还是去拜鬼魔和那些不能看、不能听、不能走，金、银、铜、木、石的偶像，","notes":[]},{"n":21,"t":"又不悔改他们那些凶杀、邪术、奸淫、偷窃的事。","notes":[]}]},"10":{"heading":"天使和小书卷","verses":[{"n":1,"t":"我又看见另有一位大力的天使从天降下，披着云彩，头上有虹，脸面像日头，两脚像火柱。","notes":[]},{"n":2,"t":"他手里拿着小书卷，是展开的。他右脚踏海，左脚踏地，","notes":[]},{"n":3,"t":"大声呼喊，好像狮子吼叫。呼喊完了，就有七雷发声。","notes":[]},{"n":4,"t":"七雷发声之后，我正要写出来，就听见从天上有声音说：「七雷所说的，你要封上，不可写出来。」","notes":[]},{"n":5,"t":"我所看见的那踏海踏地的天使向天举起右手来，","notes":[]},{"n":6,"t":"指着那创造天和天上之物，地和地上之物，海和海中之物，直活到永永远远的，起誓说：「不再有时日了。」","notes":["或译：不再耽延了"]},{"n":7,"t":"但在第七位天使吹号发声的时候，神的奥秘就成全了，正如神所传给他仆人众先知的佳音。","notes":[]},{"n":8,"t":"我先前从天上所听见的那声音又吩咐我说：「你去，把那踏海踏地之天使手中展开的小书卷取过来。」","notes":[]},{"n":9,"t":"我就走到天使那里，对他说：「请你把小书卷给我。」他对我说：「你拿着吃尽了，便叫你肚子发苦，然而在你口中要甜如蜜。」","notes":[]},{"n":10,"t":"我从天使手中把小书卷接过来，吃尽了，在我口中果然甜如蜜，吃了以后，肚子觉得发苦了。","notes":[]},{"n":11,"t":"天使对我说：「你必指着多民、多国、多方、多王再说预言。」","notes":["原文是他们"]}]},"11":{"heading":"两个见证人","verses":[{"n":1,"t":"有一根苇子赐给我，当作量度的杖；且有话说：「起来！将神的殿和祭坛，并在殿中礼拜的人都量一量。","notes":[]},{"n":2,"t":"只是殿外的院子要留下不用量，因为这是给了外邦人的；他们要践踏圣城四十二个月。","notes":[]},{"n":3,"t":"我要使我那两个见证人，穿着毛衣，传道一千二百六十天。」","notes":[]},{"n":4,"t":"他们就是那两棵橄榄树，两个灯台，立在世界之主面前的。","notes":[]},{"n":5,"t":"若有人想要害他们，就有火从他们口中出来，烧灭仇敌。凡想要害他们的都必这样被杀。","notes":[]},{"n":6,"t":"这二人有权柄，在他们传道的日子叫天闭塞不下雨；又有权柄叫水变为血，并且能随时随意用各样的灾殃攻击世界。","notes":[]},{"n":7,"t":"他们作完见证的时候，那从无底坑里上来的兽必与他们交战，并且得胜，把他们杀了。","notes":[]},{"n":8,"t":"他们的尸首就倒在大城里的街上；这城按着灵意叫所多玛，又叫埃及，就是他们的主钉十字架之处。","notes":[]},{"n":9,"t":"从各民、各族、各方、各国中，有人观看他们的尸首三天半，又不许把尸首放在坟墓里。","notes":[]},{"n":10,"t":"住在地上的人就为他们欢喜快乐，互相馈送礼物，因这两位先知曾叫住在地上的人受痛苦。","notes":[]},{"n":11,"t":"过了这三天半，有生气从神那里进入他们里面，他们就站起来；看见他们的人甚是害怕。","notes":[]},{"n":12,"t":"两位先知听见有大声音从天上来，对他们说：「上到这里来。」他们就驾着云上了天，他们的仇敌也看见了。","notes":[]},{"n":13,"t":"正在那时候，地大震动，城就倒塌了十分之一，因地震而死的有七千人；其余的都恐惧，归荣耀给天上的神。","notes":[]},{"n":14,"t":"第二样灾祸过去，第三样灾祸快到了。","notes":[]},{"n":15,"t":"第七位天使吹号，天上就有大声音说：世上的国成了我主和主基督的国；他要作王，直到永永远远。","notes":[],"heads":["第七号"]},{"n":16,"t":"在神面前，坐在自己位上的二十四位长老，就面伏于地，敬拜神，","notes":[]},{"n":17,"t":"说：昔在、今在的主神—全能者啊，我们感谢你！因你执掌大权作王了。","notes":[]},{"n":18,"t":"外邦发怒，你的忿怒也临到了；审判死人的时候也到了。你的仆人众先知和众圣徒，凡敬畏你名的人，连大带小得赏赐的时候也到了。你败坏那些败坏世界之人的时候也就到了。","notes":[]},{"n":19,"t":"当时，神天上的殿开了，在他殿中现出他的约柜。随后有闪电、声音、雷轰、地震、大雹。","notes":[]}]},"12":{"heading":"妇人和龙","verses":[{"n":1,"t":"天上现出大异象来：有一个妇人身披日头，脚踏月亮，头戴十二星的冠冕。","notes":[]},{"n":2,"t":"她怀了孕，在生产的艰难中疼痛呼叫。","notes":[]},{"n":3,"t":"天上又现出异象来：有一条大红龙，七头十角；七头上戴着七个冠冕。","notes":[]},{"n":4,"t":"它的尾巴拖拉着天上星辰的三分之一，摔在地上。龙就站在那将要生产的妇人面前，等她生产之后，要吞吃她的孩子。","notes":[]},{"n":5,"t":"妇人生了一个男孩子，是将来要用铁杖辖管万国的；她的孩子被提到神宝座那里去了。","notes":["辖管：原文是牧"]},{"n":6,"t":"妇人就逃到旷野，在那里有神给她预备的地方，使她被养活一千二百六十天。","notes":[]},{"n":7,"t":"在天上就有了争战。米迦勒同他的使者与龙争战，龙也同它的使者去争战，","notes":[]},{"n":8,"t":"并没有得胜，天上再没有它们的地方。","notes":[]},{"n":9,"t":"大龙就是那古蛇，名叫魔鬼，又叫撒但，是迷惑普天下的。它被摔在地上，它的使者也一同被摔下去。","notes":[]},{"n":10,"t":"我听见在天上有大声音说：「我神的救恩、能力、国度，并他基督的权柄，现在都来到了！因为那在我们神面前昼夜控告我们弟兄的，已经被摔下去了。","notes":[]},{"n":11,"t":"弟兄胜过它，是因羔羊的血和自己所见证的道。他们虽至于死，也不爱惜性命。","notes":[]},{"n":12,"t":"所以，诸天和住在其中的，你们都快乐吧！只是地与海有祸了！因为魔鬼知道自己的时候不多，就气忿忿地下到你们那里去了。」","notes":[]},{"n":13,"t":"龙见自己被摔在地上，就逼迫那生男孩子的妇人。","notes":[]},{"n":14,"t":"于是有大鹰的两个翅膀赐给妇人，叫她能飞到旷野，到自己的地方，躲避那蛇；她在那里被养活一载二载半载。","notes":[]},{"n":15,"t":"蛇就在妇人身后，从口中吐出水来，像河一样，要将妇人冲去。","notes":[]},{"n":16,"t":"地却帮助妇人，开口吞了从龙口吐出来的水。","notes":["原文是河"]},{"n":17,"t":"龙向妇人发怒，去与她其余的儿女争战，这儿女就是那守神诫命、为耶稣作见证的。","notes":[]},{"n":18,"t":"那时龙就站在海边的沙上。","notes":[]}]},"13":{"heading":"两个兽","verses":[{"n":1,"t":"我又看见一个兽从海中上来，有十角七头，在十角上戴着十个冠冕，七头上有亵渎的名号。","notes":[]},{"n":2,"t":"我所看见的兽，形状像豹，脚像熊的脚，口像狮子的口。那龙将自己的能力、座位，和大权柄都给了它。","notes":[]},{"n":3,"t":"我看见兽的七头中，有一个似乎受了死伤，那死伤却医好了。全地的人都希奇跟从那兽，","notes":[]},{"n":4,"t":"又拜那龙—因为它将自己的权柄给了兽，也拜兽，说：「谁能比这兽，谁能与它交战呢？」","notes":[]},{"n":5,"t":"又赐给它说夸大亵渎话的口，又有权柄赐给它，可以任意而行四十二个月。","notes":[]},{"n":6,"t":"兽就开口向神说亵渎的话，亵渎神的名并他的帐幕，以及那些住在天上的。","notes":[]},{"n":7,"t":"又任凭它与圣徒争战，并且得胜；也把权柄赐给它，制伏各族、各民、各方、各国。","notes":[]},{"n":8,"t":"凡住在地上、名字从创世以来没有记在被杀之羔羊生命册上的人，都要拜它。","notes":[]},{"n":9,"t":"凡有耳的，就应当听！","notes":[]},{"n":10,"t":"掳掠人的，必被掳掠；用刀杀人的，必被刀杀。圣徒的忍耐和信心就是在此。","notes":[]},{"n":11,"t":"我又看见另有一个兽从地中上来，有两角如同羊羔，说话好像龙。","notes":[]},{"n":12,"t":"它在头一个兽面前，施行头一个兽所有的权柄，并且叫地和住在地上的人拜那死伤医好的头一个兽。","notes":[]},{"n":13,"t":"又行大奇事，甚至在人面前，叫火从天降在地上。","notes":[]},{"n":14,"t":"它因赐给它权柄在兽面前能行奇事，就迷惑住在地上的人，说：「要给那受刀伤还活着的兽作个像。」","notes":[]},{"n":15,"t":"又有权柄赐给它，叫兽像有生气，并且能说话，又叫所有不拜兽像的人都被杀害。","notes":[]},{"n":16,"t":"它又叫众人，无论大小、贫富、自主的、为奴的，都在右手上或是在额上受一个印记。","notes":[]},{"n":17,"t":"除了那受印记、有了兽名或有兽名数目的，都不得做买卖。","notes":[]},{"n":18,"t":"在这里有智慧：凡有聪明的，可以算计兽的数目；因为这是人的数目，它的数目是六百六十六。","notes":[]}]},"14":{"heading":"十四万四千人的歌","verses":[{"n":1,"t":"我又观看，见羔羊站在锡安山，同他又有十四万四千人，都有他的名和他父的名写在额上。","notes":[]},{"n":2,"t":"我听见从天上有声音，像众水的声音和大雷的声音，并且我所听见的好像弹琴的所弹的琴声。","notes":[]},{"n":3,"t":"他们在宝座前，并在四活物和众长老前唱歌，仿佛是新歌；除了从地上买来的那十四万四千人以外，没有人能学这歌。","notes":[]},{"n":4,"t":"这些人未曾沾染妇女，他们原是童身。羔羊无论往哪里去，他们都跟随他。他们是从人间买来的，作初熟的果子归与神和羔羊。","notes":[]},{"n":5,"t":"在他们口中察不出谎言来；他们是没有瑕疵的。","notes":[]},{"n":6,"t":"我又看见另有一位天使飞在空中，有永远的福音要传给住在地上的人，就是各国、各族、各方、各民。","notes":[],"heads":["三位天使的信息"]},{"n":7,"t":"他大声说：「应当敬畏神，将荣耀归给他！因他施行审判的时候已经到了。应当敬拜那创造天地海和众水泉源的。」","notes":[]},{"n":8,"t":"又有第二位天使接着说：「叫万民喝邪淫、大怒之酒的巴比伦大城倾倒了！倾倒了！」","notes":[]},{"n":9,"t":"又有第三位天使接着他们，大声说：「若有人拜兽和兽像，在额上或在手上受了印记，","notes":[]},{"n":10,"t":"这人也必喝神大怒的酒；此酒斟在神忿怒的杯中纯一不杂。他要在圣天使和羔羊面前，在火与硫磺之中受痛苦。","notes":[]},{"n":11,"t":"他受痛苦的烟往上冒，直到永永远远。那些拜兽和兽像，受它名之印记的，昼夜不得安宁。」","notes":[]},{"n":12,"t":"圣徒的忍耐就在此；他们是守神诫命和耶稣真道的。","notes":[]},{"n":13,"t":"我听见从天上有声音说：「你要写下：从今以后，在主里面而死的人有福了！」圣灵说：「是的，他们息了自己的劳苦，做工的果效也随着他们。」","notes":[]},{"n":14,"t":"我又观看，见有一片白云，云上坐着一位好像人子，头上戴着金冠冕，手里拿着快镰刀。","notes":[],"heads":["地上的收割"]},{"n":15,"t":"又有一位天使从殿中出来，向那坐在云上的大声喊着说：「伸出你的镰刀来收割；因为收割的时候已经到了，地上的庄稼已经熟透了。」","notes":[]},{"n":16,"t":"那坐在云上的，就把镰刀扔在地上，地上的庄稼就被收割了。","notes":[]},{"n":17,"t":"又有一位天使从天上的殿中出来，他也拿着快镰刀。","notes":[]},{"n":18,"t":"又有一位天使从祭坛中出来，是有权柄管火的，向拿着快镰刀的大声喊着说：「伸出快镰刀来，收取地上葡萄树的果子，因为葡萄熟透了！」","notes":[]},{"n":19,"t":"那天使就把镰刀扔在地上，收取了地上的葡萄，丢在神忿怒的大酒榨中。","notes":[]},{"n":20,"t":"那酒榨踹在城外，就有血从酒榨里流出来，高到马的嚼环，远有六百里。","notes":[]}]},"15":{"heading":"七位天使掌管最后的灾","verses":[{"n":1,"t":"我又看见在天上有异象，大而且奇，就是七位天使掌管末了的七灾，因为神的大怒在这七灾中发尽了。","notes":[]},{"n":2,"t":"我看见仿佛有玻璃海，其中有火搀杂。又看见那些胜了兽和兽的像并它名字数目的人，都站在玻璃海上，拿着神的琴，","notes":[]},{"n":3,"t":"唱神仆人摩西的歌和羔羊的歌，说：主神—全能者啊，你的作为大哉！奇哉！万世之王啊，你的道途义哉！诚哉！","notes":["或译：国"]},{"n":4,"t":"主啊，谁敢不敬畏你，不将荣耀归与你的名呢？因为独有你是圣的。万民都要来在你面前敬拜，因你公义的作为已经显出来了。","notes":[]},{"n":5,"t":"此后，我看见在天上那存法柜的殿开了。","notes":[]},{"n":6,"t":"那掌管七灾的七位天使从殿中出来，穿着洁白光明的细麻衣，胸间束着金带。","notes":["细麻衣：有古卷是宝石"]},{"n":7,"t":"四活物中有一个把盛满了活到永永远远之神大怒的七个金碗给了那七位天使。","notes":[]},{"n":8,"t":"因神的荣耀和能力，殿中充满了烟。于是没有人能以进殿，直等到那七位天使所降的七灾完毕了。","notes":[]}]},"16":{"heading":"神大怒的碗","verses":[{"n":1,"t":"我听见有大声音从殿中出来，向那七位天使说：「你们去，把盛神大怒的七碗倒在地上。」","notes":[]},{"n":2,"t":"第一位天使便去，把碗倒在地上，就有恶而且毒的疮生在那些有兽印记、拜兽像的人身上。","notes":[]},{"n":3,"t":"第二位天使把碗倒在海里，海就变成血，好像死人的血，海中的活物都死了。","notes":[]},{"n":4,"t":"第三位天使把碗倒在江河与众水的泉源里，水就变成血了。","notes":[]},{"n":5,"t":"我听见掌管众水的天使说：昔在、今在的圣者啊，你这样判断是公义的；","notes":[]},{"n":6,"t":"他们曾流圣徒与先知的血，现在你给他们血喝；这是他们所该受的。","notes":[]},{"n":7,"t":"我又听见祭坛中有声音说：是的，主神—全能者啊，你的判断义哉！诚哉！","notes":[]},{"n":8,"t":"第四位天使把碗倒在日头上，叫日头能用火烤人。","notes":[]},{"n":9,"t":"人被大热所烤，就亵渎那有权掌管这些灾的神之名，并不悔改将荣耀归给神。","notes":[]},{"n":10,"t":"第五位天使把碗倒在兽的座位上，兽的国就黑暗了。人因疼痛就咬自己的舌头；","notes":[]},{"n":11,"t":"又因所受的疼痛，和生的疮，就亵渎天上的神，并不悔改所行的。","notes":[]},{"n":12,"t":"第六位天使把碗倒在幼发拉底大河上，河水就干了，要给那从日出之地所来的众王预备道路。","notes":[]},{"n":13,"t":"我又看见三个污秽的灵，好像青蛙，从龙口、兽口并假先知的口中出来。","notes":[]},{"n":14,"t":"他们本是鬼魔的灵，施行奇事，出去到普天下众王那里，叫他们在神全能者的大日聚集争战。","notes":[]},{"n":15,"t":"看哪，我来像贼一样。那警醒、看守衣服、免得赤身而行、叫人见他羞耻的有福了！","notes":[]},{"n":16,"t":"那三个鬼魔便叫众王聚集在一处，希伯来话叫作哈米吉多顿。","notes":[]},{"n":17,"t":"第七位天使把碗倒在空中，就有大声音从殿中的宝座上出来，说：「成了！」","notes":[]},{"n":18,"t":"又有闪电、声音、雷轰、大地震，自从地上有人以来，没有这样大、这样厉害的地震。","notes":[]},{"n":19,"t":"那大城裂为三段，列国的城也都倒塌了；神也想起巴比伦大城来，要把那盛自己烈怒的酒杯递给他。","notes":[]},{"n":20,"t":"各海岛都逃避了，众山也不见了。","notes":[]},{"n":21,"t":"又有大雹子从天落在人身上，每一个约重一他连得。为这雹子的灾极大，人就亵渎神。","notes":["一他连得约有九十斤"]}]},"17":{"heading":"大淫妇和兽","verses":[{"n":1,"t":"拿着七碗的七位天使中，有一位前来对我说：「你到这里来，我将坐在众水上的大淫妇所要受的刑罚指给你看。","notes":[]},{"n":2,"t":"地上的君王与她行淫，住在地上的人喝醉了她淫乱的酒。」","notes":[]},{"n":3,"t":"我被圣灵感动，天使带我到旷野去，我就看见一个女人骑在朱红色的兽上；那兽有七头十角，遍体有亵渎的名号。","notes":[]},{"n":4,"t":"那女人穿着紫色和朱红色的衣服，用金子、宝石、珍珠为妆饰；手拿金杯，杯中盛满了可憎之物，就是她淫乱的污秽。","notes":[]},{"n":5,"t":"在她额上有名写着说：「奥秘哉！大巴比伦，作世上的淫妇和一切可憎之物的母。」","notes":[]},{"n":6,"t":"我又看见那女人喝醉了圣徒的血和为耶稣作见证之人的血。我看见她，就大大地希奇。","notes":[]},{"n":7,"t":"天使对我说：「你为什么希奇呢？我要将这女人和驮着她的那七头十角兽的奥秘告诉你。","notes":[]},{"n":8,"t":"你所看见的兽，先前有，如今没有，将要从无底坑里上来，又要归于沉沦。凡住在地上、名字从创世以来没有记在生命册上的，见先前有、如今没有、以后再有的兽，就必希奇。","notes":[]},{"n":9,"t":"智慧的心在此可以思想。那七头就是女人所坐的七座山，","notes":[]},{"n":10,"t":"又是七位王；五位已经倾倒了，一位还在，一位还没有来到；他来的时候，必须暂时存留。","notes":[]},{"n":11,"t":"那先前有如今没有的兽，就是第八位；他也和那七位同列，并且归于沉沦。","notes":[]},{"n":12,"t":"你所看见的那十角就是十王；他们还没有得国，但他们一时之间要和兽同得权柄，与王一样。","notes":[]},{"n":13,"t":"他们同心合意将自己的能力、权柄给那兽。","notes":[]},{"n":14,"t":"他们与羔羊争战，羔羊必胜过他们，因为羔羊是万主之主、万王之王。同着羔羊的，就是蒙召、被选、有忠心的，也必得胜。」","notes":[]},{"n":15,"t":"天使又对我说：「你所看见那淫妇坐的众水，就是多民、多人、多国、多方。","notes":[]},{"n":16,"t":"你所看见的那十角与兽必恨这淫妇，使她冷落赤身，又要吃她的肉，用火将她烧尽。","notes":[]},{"n":17,"t":"因为神使诸王同心合意，遵行他的旨意，把自己的国给那兽，直等到神的话都应验了。","notes":[]},{"n":18,"t":"你所看见的那女人就是管辖地上众王的大城。」","notes":[]}]},"18":{"heading":"巴比伦倾倒","verses":[{"n":1,"t":"此后，我看见另有一位有大权柄的天使从天降下，地就因他的荣耀发光。","notes":[]},{"n":2,"t":"他大声喊着说：巴比伦大城倾倒了！倾倒了！成了鬼魔的住处和各样污秽之灵的巢穴，并各样污秽可憎之雀鸟的巢穴。","notes":["或译：牢狱；下同"]},{"n":3,"t":"因为列国都被她邪淫大怒的酒倾倒了。地上的君王与她行淫；地上的客商因她奢华太过就发了财。","notes":[]},{"n":4,"t":"我又听见从天上有声音说：我的民哪，你们要从那城出来，免得与她一同有罪，受她所受的灾殃；","notes":[]},{"n":5,"t":"因她的罪恶滔天；她的不义，神已经想起来了。","notes":[]},{"n":6,"t":"她怎样待人，也要怎样待她，按她所行的加倍地报应她；用她调酒的杯加倍地调给她喝。","notes":[]},{"n":7,"t":"她怎样荣耀自己，怎样奢华，也当叫她照样痛苦悲哀，因她心里说：我坐了皇后的位，并不是寡妇，决不至于悲哀。","notes":[]},{"n":8,"t":"所以在一天之内，她的灾殃要一齐来到，就是死亡、悲哀、饥荒。她又要被火烧尽了，因为审判她的主神大有能力。","notes":[]},{"n":9,"t":"地上的君王，素来与她行淫、一同奢华的，看见烧她的烟，就必为她哭泣哀号。","notes":[]},{"n":10,"t":"因怕她的痛苦，就远远地站着说：哀哉！哀哉！巴比伦大城，坚固的城啊，一时之间你的刑罚就来到了。","notes":[]},{"n":11,"t":"地上的客商也都为她哭泣悲哀，因为没有人再买他们的货物了；","notes":[]},{"n":12,"t":"这货物就是金、银、宝石、珍珠、细麻布、紫色料、绸子、朱红色料、各样香木、各样象牙的器皿、各样极宝贵的木头，和铜、铁、汉白玉的器皿，","notes":[]},{"n":13,"t":"并肉桂、豆蔻、香料、香膏、乳香、酒、油、细面、麦子、牛、羊、车、马，和奴仆、人口。","notes":[]},{"n":14,"t":"巴比伦哪，你所贪爱的果子离开了你；你一切的珍馐美味和华美的物件也从你中间毁灭，决不能再见了。","notes":[]},{"n":15,"t":"贩卖这些货物、借着她发了财的客商，因怕她的痛苦，就远远地站着哭泣悲哀，说：","notes":[]},{"n":16,"t":"哀哉！哀哉！这大城啊，素常穿着细麻、紫色、朱红色的衣服，又用金子、宝石，和珍珠为妆饰。","notes":[]},{"n":17,"t":"一时之间，这么大的富厚就归于无有了。凡船主和坐船往各处去的，并众水手，连所有靠海为业的，都远远地站着，","notes":[]},{"n":18,"t":"看见烧她的烟，就喊着说：「有何城能比这大城呢？」","notes":[]},{"n":19,"t":"他们又把尘土撒在头上，哭泣悲哀，喊着说：哀哉！哀哉！这大城啊。凡有船在海中的，都因她的珍宝成了富足！她在一时之间就成了荒场！","notes":[]},{"n":20,"t":"天哪，众圣徒、众使徒、众先知啊，你们都要因她欢喜，因为神已经在她身上伸了你们的冤。","notes":[]},{"n":21,"t":"有一位大力的天使举起一块石头，好像大磨石，扔在海里，说：巴比伦大城也必这样猛力地被扔下去，决不能再见了。","notes":[]},{"n":22,"t":"弹琴、作乐、吹笛、吹号的声音，在你中间决不能再听见；各行手艺人在你中间决不能再遇见；推磨的声音在你中间决不能再听见；","notes":[]},{"n":23,"t":"灯光在你中间决不能再照耀；新郎和新妇的声音，在你中间决不能再听见。你的客商原来是地上的尊贵人；万国也被你的邪术迷惑了。","notes":[]},{"n":24,"t":"先知和圣徒，并地上一切被杀之人的血，都在这城里看见了。","notes":[]}]},"19":{"heading":"羔羊的婚筵","verses":[{"n":1,"t":"此后，我听见好像群众在天上大声说：哈利路亚！救恩、荣耀、权能都属乎我们的神！","notes":["就是要赞美耶和华的意思"]},{"n":2,"t":"他的判断是真实公义的；因他判断了那用淫行败坏世界的大淫妇，并且向淫妇讨流仆人血的罪，给他们伸冤。","notes":[]},{"n":3,"t":"又说：哈利路亚！烧淫妇的烟往上冒，直到永永远远。","notes":[]},{"n":4,"t":"那二十四位长老与四活物就俯伏敬拜坐宝座的神，说：阿们！哈利路亚！","notes":[]},{"n":5,"t":"有声音从宝座出来说：神的众仆人哪，凡敬畏他的，无论大小，都要赞美我们的神！","notes":[]},{"n":6,"t":"我听见好像群众的声音，众水的声音，大雷的声音，说：哈利路亚！因为主—我们的神、全能者作王了。","notes":[]},{"n":7,"t":"我们要欢喜快乐，将荣耀归给他。因为，羔羊婚娶的时候到了；新妇也自己预备好了，","notes":[]},{"n":8,"t":"就蒙恩得穿光明洁白的细麻衣。（这细麻衣就是圣徒所行的义。）","notes":[]},{"n":9,"t":"天使吩咐我说：「你要写上：凡被请赴羔羊之婚筵的有福了！」又对我说：「这是神真实的话。」","notes":[]},{"n":10,"t":"我就俯伏在他脚前要拜他。他说：「千万不可！我和你，并你那些为耶稣作见证的弟兄同是作仆人的，你要敬拜神。」因为预言中的灵意乃是为耶稣作见证。","notes":[]},{"n":11,"t":"我观看，见天开了。有一匹白马，骑在马上的称为诚信真实，他审判，争战，都按着公义。","notes":[],"heads":["骑白马者"]},{"n":12,"t":"他的眼睛如火焰，他头上戴着许多冠冕；又有写着的名字，除了他自己没有人知道。","notes":[]},{"n":13,"t":"他穿着溅了血的衣服；他的名称为神之道。","notes":[]},{"n":14,"t":"在天上的众军骑着白马，穿着细麻衣，又白又洁，跟随他。","notes":[]},{"n":15,"t":"有利剑从他口中出来，可以击杀列国。他必用铁杖辖管他们，并要踹全能神烈怒的酒榨。","notes":["辖管：原文是牧"]},{"n":16,"t":"在他衣服和大腿上有名写着说：「万王之王，万主之主。」","notes":[]},{"n":17,"t":"我又看见一位天使站在日头中，向天空所飞的鸟大声喊着说：「你们聚集来赴神的大筵席，","notes":[]},{"n":18,"t":"可以吃君王与将军的肉，壮士与马和骑马者的肉，并一切自主的为奴的，以及大小人民的肉。」","notes":[]},{"n":19,"t":"我看见那兽和地上的君王，并他们的众军都聚集，要与骑白马的并他的军兵争战。","notes":[]},{"n":20,"t":"那兽被擒拿；那在兽面前曾行奇事、迷惑受兽印记和拜兽像之人的假先知，也与兽同被擒拿。他们两个就活活地被扔在烧着硫磺的火湖里；","notes":[]},{"n":21,"t":"其余的被骑白马者口中出来的剑杀了；飞鸟都吃饱了他们的肉。","notes":[]}]},"20":{"heading":"一千年","verses":[{"n":1,"t":"我又看见一位天使从天降下，手里拿着无底坑的钥匙和一条大链子。","notes":[]},{"n":2,"t":"他捉住那龙，就是古蛇，又叫魔鬼，也叫撒但，把它捆绑一千年，","notes":[]},{"n":3,"t":"扔在无底坑里，将无底坑关闭，用印封上，使它不得再迷惑列国。等到那一千年完了，以后必须暂时释放它。","notes":[]},{"n":4,"t":"我又看见几个宝座，也有坐在上面的，并有审判的权柄赐给他们。我又看见那些因为给耶稣作见证，并为神之道被斩者的灵魂，和那没有拜过兽与兽像，也没有在额上和手上受过他印记之人的灵魂，他们都复活了，与基督一同作王一千年。","notes":[]},{"n":5,"t":"这是头一次的复活。（其余的死人还没有复活，直等那一千年完了。）","notes":[]},{"n":6,"t":"在头一次复活有分的有福了，圣洁了！第二次的死在他们身上没有权柄。他们必作神和基督的祭司，并要与基督一同作王一千年。","notes":[]},{"n":7,"t":"那一千年完了，撒但必从监牢里被释放，","notes":[],"heads":["击败撒但"]},{"n":8,"t":"出来要迷惑地上四方的列国，就是歌革和玛各，叫他们聚集争战。他们的人数多如海沙。","notes":["原文是角"]},{"n":9,"t":"他们上来遍满了全地，围住圣徒的营与蒙爱的城，就有火从天降下，烧灭了他们。","notes":[]},{"n":10,"t":"那迷惑他们的魔鬼被扔在硫磺的火湖里，就是兽和假先知所在的地方。他们必昼夜受痛苦，直到永永远远。","notes":[]},{"n":11,"t":"我又看见一个白色的大宝座与坐在上面的；从他面前天地都逃避，再无可见之处了。","notes":[],"heads":["末日的审判"]},{"n":12,"t":"我又看见死了的人，无论大小，都站在宝座前。案卷展开了，并且另有一卷展开，就是生命册。死了的人都凭着这些案卷所记载的，照他们所行的受审判。","notes":[]},{"n":13,"t":"于是海交出其中的死人；死亡和阴间也交出其中的死人；他们都照各人所行的受审判。","notes":[]},{"n":14,"t":"死亡和阴间也被扔在火湖里；这火湖就是第二次的死。","notes":[]},{"n":15,"t":"若有人名字没记在生命册上，他就被扔在火湖里。","notes":[]}]},"21":{"heading":"新天新地","verses":[{"n":1,"t":"我又看见一个新天新地；因为先前的天地已经过去了，海也不再有了。","notes":[]},{"n":2,"t":"我又看见圣城新耶路撒冷由神那里从天而降，预备好了，就如新妇妆饰整齐，等候丈夫。","notes":[]},{"n":3,"t":"我听见有大声音从宝座出来说：「看哪，神的帐幕在人间。他要与人同住，他们要作他的子民。神要亲自与他们同在，作他们的神。","notes":[]},{"n":4,"t":"神要擦去他们一切的眼泪；不再有死亡，也不再有悲哀、哭号、疼痛，因为以前的事都过去了。」","notes":[]},{"n":5,"t":"坐宝座的说：「看哪，我将一切都更新了！」又说：「你要写上；因这些话是可信的，是真实的。」","notes":[]},{"n":6,"t":"他又对我说：「都成了！我是阿拉法，我是俄梅戛；我是初，我是终。我要将生命泉的水白白赐给那口渴的人喝。","notes":[]},{"n":7,"t":"得胜的，必承受这些为业：我要作他的神，他要作我的儿子。","notes":[]},{"n":8,"t":"惟有胆怯的、不信的、可憎的、杀人的、淫乱的、行邪术的、拜偶像的，和一切说谎话的，他们的分就在烧着硫磺的火湖里；这是第二次的死。」","notes":[]},{"n":9,"t":"拿着七个金碗、盛满末后七灾的七位天使中，有一位来对我说：「你到这里来，我要将新妇，就是羔羊的妻，指给你看。」","notes":[],"heads":["新耶路撒冷"]},{"n":10,"t":"我被圣灵感动，天使就带我到一座高大的山，将那由神那里、从天而降的圣城耶路撒冷指示我。","notes":[]},{"n":11,"t":"城中有神的荣耀；城的光辉如同极贵的宝石，好像碧玉，明如水晶。","notes":[]},{"n":12,"t":"有高大的墙，有十二个门，门上有十二位天使，门上又写着以色列十二个支派的名字。","notes":[]},{"n":13,"t":"东边有三门，北边有三门，南边有三门，西边有三门。","notes":[]},{"n":14,"t":"城墙有十二根基，根基上有羔羊十二使徒的名字。","notes":[]},{"n":15,"t":"对我说话的，拿着金苇子当尺，要量那城和城门城墙。","notes":[]},{"n":16,"t":"城是四方的，长宽一样。天使用苇子量那城，共有四千里，长、宽、高都是一样；","notes":[]},{"n":17,"t":"又量了城墙，按着人的尺寸，就是天使的尺寸，共有一百四十四肘。","notes":[]},{"n":18,"t":"墙是碧玉造的；城是精金的，如同明净的玻璃。","notes":[]},{"n":19,"t":"城墙的根基是用各样宝石修饰的：第一根基是碧玉；第二是蓝宝石；第三是绿玛瑙；第四是绿宝石；","notes":[]},{"n":20,"t":"第五是红玛瑙；第六是红宝石；第七是黄璧玺；第八是水苍玉；第九是红璧玺；第十是翡翠；第十一是紫玛瑙；第十二是紫晶。","notes":[]},{"n":21,"t":"十二个门是十二颗珍珠，每门是一颗珍珠。城内的街道是精金，好像明透的玻璃。","notes":[]},{"n":22,"t":"我未见城内有殿，因主神—全能者和羔羊为城的殿。","notes":[]},{"n":23,"t":"那城内又不用日月光照；因有神的荣耀光照，又有羔羊为城的灯。","notes":[]},{"n":24,"t":"列国要在城的光里行走；地上的君王必将自己的荣耀归与那城。","notes":[]},{"n":25,"t":"城门白昼总不关闭，在那里原没有黑夜。","notes":[]},{"n":26,"t":"人必将列国的荣耀、尊贵归与那城。","notes":[]},{"n":27,"t":"凡不洁净的，并那行可憎与虚谎之事的，总不得进那城；只有名字写在羔羊生命册上的才得进去。","notes":[]}]},"22":{"heading":"基督再临","verses":[{"n":1,"t":"天使又指示我在城内街道当中一道生命水的河，明亮如水晶，从神和羔羊的宝座流出来。","notes":[]},{"n":2,"t":"在河这边与那边有生命树，结十二样果子，每月都结果子；树上的叶子乃为医治万民。","notes":["或译：回"]},{"n":3,"t":"以后再没有咒诅；在城里有神和羔羊的宝座；他的仆人都要事奉他，","notes":[]},{"n":4,"t":"也要见他的面。他的名字必写在他们的额上。","notes":[]},{"n":5,"t":"不再有黑夜；他们也不用灯光、日光，因为主神要光照他们。他们要作王，直到永永远远。","notes":[]},{"n":6,"t":"天使又对我说：「这些话是真实可信的。主就是众先知被感之灵的神，差遣他的使者，将那必要快成的事指示他仆人。」","notes":[]},{"n":7,"t":"「看哪，我必快来！凡遵守这书上预言的有福了！」","notes":[]},{"n":8,"t":"这些事是我—约翰所听见、所看见的；我既听见、看见了，就在指示我的天使脚前俯伏要拜他。","notes":[]},{"n":9,"t":"他对我说：「千万不可！我与你和你的弟兄众先知，并那些守这书上言语的人，同是作仆人的。你要敬拜神。」","notes":[]},{"n":10,"t":"他又对我说：「不可封了这书上的预言，因为日期近了。","notes":[]},{"n":11,"t":"不义的，叫他仍旧不义；污秽的，叫他仍旧污秽；为义的，叫他仍旧为义；圣洁的，叫他仍旧圣洁。」","notes":[]},{"n":12,"t":"「看哪，我必快来！赏罚在我，要照各人所行的报应他。","notes":[]},{"n":13,"t":"我是阿拉法，我是俄梅戛；我是首先的，我是末后的；我是初，我是终。」","notes":[]},{"n":14,"t":"那些洗净自己衣服的有福了！可得权柄能到生命树那里，也能从门进城。","notes":[]},{"n":15,"t":"城外有那些犬类、行邪术的、淫乱的、杀人的、拜偶像的，并一切喜好说谎言、编造虚谎的。","notes":[]},{"n":16,"t":"「我—耶稣差遣我的使者为众教会将这些事向你们证明。我是大卫的根，又是他的后裔。我是明亮的晨星。」","notes":[]},{"n":17,"t":"圣灵和新妇都说：「来！」听见的人也该说：「来！」口渴的人也当来；愿意的，都可以白白取生命的水喝。","notes":[]},{"n":18,"t":"我向一切听见这书上预言的作见证，若有人在这预言上加添什么，神必将写在这书上的灾祸加在他身上；","notes":[],"heads":["警戒增减这书上的预言"]},{"n":19,"t":"这书上的预言，若有人删去什么，神必从这书上所写的生命树和圣城删去他的分。","notes":[]},{"n":20,"t":"证明这事的说：「是了，我必快来！」阿们！主耶稣啊，我愿你来！","notes":[]},{"n":21,"t":"愿主耶稣的恩惠常与众圣徒同在。阿们！","notes":[]}]}}},"traditional":{"GEN":{"1":{"heading":"神的創造","verses":[{"n":1,"t":"起初，神創造天地。","notes":[]},{"n":2,"t":"地是空虛混沌，淵面黑暗；神的靈運行在水面上。","notes":[]},{"n":3,"t":"神說：「要有光」，就有了光。","notes":[]},{"n":4,"t":"神看光是好的，就把光暗分開了。","notes":[]},{"n":5,"t":"神稱光為「晝」，稱暗為「夜」。有晚上，有早晨，這是頭一日。","notes":[]},{"n":6,"t":"神說：「諸水之間要有空氣，將水分為上下。」","notes":[]},{"n":7,"t":"神就造出空氣，將空氣以下的水、空氣以上的水分開了。事就這樣成了。","notes":[]},{"n":8,"t":"神稱空氣為「天」。有晚上，有早晨，是第二日。","notes":[]},{"n":9,"t":"神說：「天下的水要聚在一處，使旱地露出來。」事就這樣成了。","notes":[]},{"n":10,"t":"神稱旱地為「地」，稱水的聚處為「海」。神看著是好的。","notes":[]},{"n":11,"t":"神說：「地要發生青草和結種子的菜蔬，並結果子的樹木，各從其類，果子都包著核。」事就這樣成了。","notes":[]},{"n":12,"t":"於是地發生了青草和結種子的菜蔬，各從其類；並結果子的樹木，各從其類；果子都包著核。神看著是好的。","notes":[]},{"n":13,"t":"有晚上，有早晨，是第三日。","notes":[]},{"n":14,"t":"神說：「天上要有光體，可以分晝夜，作記號，定節令、日子、年歲，","notes":[]},{"n":15,"t":"並要發光在天空，普照在地上。」事就這樣成了。","notes":[]},{"n":16,"t":"於是神造了兩個大光，大的管晝，小的管夜，又造眾星，","notes":[]},{"n":17,"t":"就把這些光擺列在天空，普照在地上，","notes":[]},{"n":18,"t":"管理晝夜，分別明暗。神看著是好的。","notes":[]},{"n":19,"t":"有晚上，有早晨，是第四日。","notes":[]},{"n":20,"t":"神說：「水要多多滋生有生命的物；要有雀鳥飛在地面以上，天空之中。」","notes":[]},{"n":21,"t":"神就造出大魚和水中所滋生各樣有生命的動物，各從其類；又造出各樣飛鳥，各從其類。神看著是好的。","notes":[]},{"n":22,"t":"神就賜福給這一切，說：「滋生繁多，充滿海中的水；雀鳥也要多生在地上。」","notes":[]},{"n":23,"t":"有晚上，有早晨，是第五日。","notes":[]},{"n":24,"t":"神說：「地要生出活物來，各從其類；牲畜、昆蟲、野獸，各從其類。」事就這樣成了。","notes":[]},{"n":25,"t":"於是神造出野獸，各從其類；牲畜，各從其類；地上一切昆蟲，各從其類。神看著是好的。","notes":[]},{"n":26,"t":"神說：「我們要照著我們的形像、按著我們的樣式造人，使他們管理海裏的魚、空中的鳥、地上的牲畜，和全地，並地上所爬的一切昆蟲。」","notes":[]},{"n":27,"t":"神就照著自己的形像造人，乃是照著他的形像造男造女。","notes":[]},{"n":28,"t":"神就賜福給他們，又對他們說：「要生養眾多，遍滿地面，治理這地，也要管理海裏的魚、空中的鳥，和地上各樣行動的活物。」","notes":[]},{"n":29,"t":"神說：「看哪，我將遍地上一切結種子的菜蔬和一切樹上所結有核的果子全賜給你們作食物。","notes":[]},{"n":30,"t":"至於地上的走獸和空中的飛鳥，並各樣爬在地上有生命的物，我將青草賜給牠們作食物。」事就這樣成了。","notes":[]},{"n":31,"t":"神看著一切所造的都甚好。有晚上，有早晨，是第六日。","notes":[]}]},"2":{"heading":"伊甸園","verses":[{"n":1,"t":"天地萬物都造齊了。","notes":[]},{"n":2,"t":"到第七日，神造物的工已經完畢，就在第七日歇了他一切的工，安息了。","notes":[]},{"n":3,"t":"神賜福給第七日，定為聖日；因為在這日，神歇了他一切創造的工，就安息了。","notes":[]},{"n":4,"t":"創造天地的來歷，在耶和華神造天地的日子，乃是這樣，","notes":[]},{"n":5,"t":"野地還沒有草木，田間的菜蔬還沒有長起來；因為耶和華神還沒有降雨在地上，也沒有人耕地，","notes":[]},{"n":6,"t":"但有霧氣從地上騰，滋潤遍地。","notes":[]},{"n":7,"t":"耶和華神用地上的塵土造人，將生氣吹在他鼻孔裏，他就成了有靈的活人，名叫亞當。","notes":[]},{"n":8,"t":"耶和華神在東方的伊甸立了一個園子，把所造的人安置在那裏。","notes":[]},{"n":9,"t":"耶和華神使各樣的樹從地裏長出來，可以悅人的眼目，其上的果子好作食物。園子當中又有生命樹和分別善惡的樹。","notes":[]},{"n":10,"t":"有河從伊甸流出來，滋潤那園子，從那裏分為四道：","notes":[]},{"n":11,"t":"第一道名叫比遜，就是環繞哈腓拉全地的。在那裏有金子，","notes":[]},{"n":12,"t":"並且那地的金子是好的；在那裏又有珍珠和紅瑪瑙。","notes":[]},{"n":13,"t":"第二道河名叫基訓，就是環繞古實全地的。","notes":[]},{"n":14,"t":"第三道河名叫底格里斯，流在亞述的東邊。第四道河就是幼發拉底河。","notes":[]},{"n":15,"t":"耶和華神將那人安置在伊甸園，使他修理，看守。","notes":[]},{"n":16,"t":"耶和華神吩咐他說：「園中各樣樹上的果子，你可以隨意吃，","notes":[]},{"n":17,"t":"只是分別善惡樹上的果子，你不可吃，因為你吃的日子必定死！」","notes":[]},{"n":18,"t":"耶和華神說：「那人獨居不好，我要為他造一個配偶幫助他。」","notes":[]},{"n":19,"t":"耶和華神用土所造成的野地各樣走獸和空中各樣飛鳥都帶到那人面前，看他叫甚麼。那人怎樣叫各樣的活物，那就是牠的名字。","notes":[]},{"n":20,"t":"那人便給一切牲畜和空中飛鳥、野地走獸都起了名；只是那人沒有遇見配偶幫助他。","notes":[]},{"n":21,"t":"耶和華神使他沉睡，他就睡了；於是取下他的一條肋骨，又把肉合起來。","notes":[]},{"n":22,"t":"耶和華神就用那人身上所取的肋骨造成一個女人，領她到那人跟前。","notes":[]},{"n":23,"t":"那人說：這是我骨中的骨，肉中的肉，可以稱她為「女人」，因為她是從「男人」身上取出來的。","notes":[]},{"n":24,"t":"因此，人要離開父母，與妻子連合，二人成為一體。","notes":[]},{"n":25,"t":"當時夫妻二人赤身露體，並不羞恥。","notes":[]}]},"3":{"heading":"人違背命令","verses":[{"n":1,"t":"耶和華神所造的，惟有蛇比田野一切的活物更狡猾。蛇對女人說：「神豈是真說不許你們吃園中所有樹上的果子嗎？」","notes":[]},{"n":2,"t":"女人對蛇說：「園中樹上的果子，我們可以吃，","notes":[]},{"n":3,"t":"惟有園當中那棵樹上的果子，神曾說：『你們不可吃，也不可摸，免得你們死。』」","notes":[]},{"n":4,"t":"蛇對女人說：「你們不一定死；","notes":[]},{"n":5,"t":"因為神知道，你們吃的日子眼睛就明亮了，你們便如神能知道善惡。」","notes":[]},{"n":6,"t":"於是女人見那棵樹的果子好作食物，也悅人的眼目，且是可喜愛的，能使人有智慧，就摘下果子來吃了，又給她丈夫，她丈夫也吃了。","notes":[]},{"n":7,"t":"他們二人的眼睛就明亮了，才知道自己是赤身露體，便拿無花果樹的葉子為自己編做裙子。","notes":[]},{"n":8,"t":"天起了涼風，耶和華神在園中行走。那人和他妻子聽見神的聲音，就藏在園裏的樹木中，躲避耶和華神的面。","notes":[]},{"n":9,"t":"耶和華神呼喚那人，對他說：「你在哪裏？」","notes":[]},{"n":10,"t":"他說：「我在園中聽見你的聲音，我就害怕；因為我赤身露體，我便藏了。」","notes":[]},{"n":11,"t":"耶和華說：「誰告訴你赤身露體呢？莫非你吃了我吩咐你不可吃的那樹上的果子嗎？」","notes":[]},{"n":12,"t":"那人說：「你所賜給我、與我同居的女人，她把那樹上的果子給我，我就吃了。」","notes":[]},{"n":13,"t":"耶和華神對女人說：「你做的是甚麼事呢？」女人說：「那蛇引誘我，我就吃了。」","notes":[]},{"n":14,"t":"耶和華神對蛇說：你既做了這事，就必受咒詛，比一切的牲畜野獸更甚；你必用肚子行走，終身吃土。","notes":[],"heads":["神的宣判"]},{"n":15,"t":"我又要叫你和女人彼此為仇；你的後裔和女人的後裔也彼此為仇。女人的後裔要傷你的頭；你要傷他的腳跟。","notes":[]},{"n":16,"t":"又對女人說：我必多多加增你懷胎的苦楚；你生產兒女必多受苦楚。你必戀慕你丈夫；你丈夫必管轄你。","notes":[]},{"n":17,"t":"又對亞當說：你既聽從妻子的話，吃了我所吩咐你不可吃的那樹上的果子，地必為你的緣故受咒詛；你必終身勞苦才能從地裏得吃的。","notes":[]},{"n":18,"t":"地必給你長出荊棘和蒺藜來；你也要吃田間的菜蔬。","notes":[]},{"n":19,"t":"你必汗流滿面才得糊口，直到你歸了土，因為你是從土而出的。你本是塵土，仍要歸於塵土。","notes":[]},{"n":20,"t":"亞當給他妻子起名叫夏娃，因為她是眾生之母。","notes":[]},{"n":21,"t":"耶和華神為亞當和他妻子用皮子做衣服給他們穿。","notes":[]},{"n":22,"t":"耶和華神說：「那人已經與我們相似，能知道善惡；現在恐怕他伸手又摘生命樹的果子吃，就永遠活著。」","notes":[],"heads":["亞當和夏娃被趕出伊甸園"]},{"n":23,"t":"耶和華神便打發他出伊甸園去，耕種他所自出之土。","notes":[]},{"n":24,"t":"於是把他趕出去了；又在伊甸園的東邊安設基路伯和四面轉動發火焰的劍，要把守生命樹的道路。","notes":[]}]},"4":{"heading":"該隱和亞伯","verses":[{"n":1,"t":"有一日，那人和他妻子夏娃同房，夏娃就懷孕，生了該隱，便說：「耶和華使我得了一個男子。」","notes":["就是得的意思"]},{"n":2,"t":"又生了該隱的兄弟亞伯。亞伯是牧羊的；該隱是種地的。","notes":[]},{"n":3,"t":"有一日，該隱拿地裏的出產為供物獻給耶和華；","notes":[]},{"n":4,"t":"亞伯也將他羊群中頭生的和羊的脂油獻上。耶和華看中了亞伯和他的供物，","notes":[]},{"n":5,"t":"只是看不中該隱和他的供物。該隱就大大地發怒，變了臉色。","notes":[]},{"n":6,"t":"耶和華對該隱說：「你為甚麼發怒呢？你為甚麼變了臉色呢？","notes":[]},{"n":7,"t":"你若行得好，豈不蒙悅納？你若行得不好，罪就伏在門前。它必戀慕你，你卻要制伏它。」","notes":[]},{"n":8,"t":"該隱與他兄弟亞伯說話；二人正在田間。該隱起來打他兄弟亞伯，把他殺了。","notes":[]},{"n":9,"t":"耶和華對該隱說：「你兄弟亞伯在哪裏？」他說：「我不知道！我豈是看守我兄弟的嗎？」","notes":[]},{"n":10,"t":"耶和華說：「你做了甚麼事呢？你兄弟的血有聲音從地裏向我哀告。","notes":[]},{"n":11,"t":"地開了口，從你手裏接受你兄弟的血。現在你必從這地受咒詛。","notes":[]},{"n":12,"t":"你種地，地不再給你效力；你必流離飄蕩在地上。」","notes":[]},{"n":13,"t":"該隱對耶和華說：「我的刑罰太重，過於我所能當的。","notes":[]},{"n":14,"t":"你如今趕逐我離開這地，以致不見你面；我必流離飄蕩在地上，凡遇見我的必殺我。」","notes":[]},{"n":15,"t":"耶和華對他說：「凡殺該隱的，必遭報七倍。」耶和華就給該隱立一個記號，免得人遇見他就殺他。","notes":[]},{"n":16,"t":"於是該隱離開耶和華的面，去住在伊甸東邊挪得之地。","notes":[]},{"n":17,"t":"該隱與妻子同房，他妻子就懷孕，生了以諾。該隱建造了一座城，就按著他兒子的名將那城叫做以諾。","notes":[],"heads":["該隱的後代"]},{"n":18,"t":"以諾生以拿；以拿生米戶雅利；米戶雅利生瑪土撒利；瑪土撒利生拉麥。","notes":[]},{"n":19,"t":"拉麥娶了兩個妻：一個名叫亞大，一個名叫洗拉。","notes":[]},{"n":20,"t":"亞大生雅八；雅八就是住帳棚、牧養牲畜之人的祖師。","notes":[]},{"n":21,"t":"雅八的兄弟名叫猶八；他是一切彈琴吹簫之人的祖師。","notes":[]},{"n":22,"t":"洗拉又生了土八‧該隱；他是打造各樣銅鐵利器的。土八‧該隱的妹子是拿瑪。","notes":["或譯：是銅匠鐵匠的祖師"]},{"n":23,"t":"拉麥對他兩個妻子說：亞大、洗拉，聽我的聲音；拉麥的妻子，細聽我的話語：壯年人傷我，我把他殺了；少年人損我，我把他害了 。","notes":["或譯：我殺壯士卻傷自己，我害幼童卻損本身"]},{"n":24,"t":"若殺該隱，遭報七倍，殺拉麥，必遭報七十七倍。","notes":[]},{"n":25,"t":"亞當又與妻子同房，她就生了一個兒子，起名叫塞特，意思說：「神另給我立了一個兒子代替亞伯，因為該隱殺了他。」","notes":[],"heads":["塞特和以挪士"]},{"n":26,"t":"塞特也生了一個兒子，起名叫以挪士。那時候，人才求告耶和華的名。","notes":[]}]},"5":{"heading":"亞當的後代","verses":[{"n":1,"t":"亞當的後代記在下面。（當神造人的日子，是照著自己的樣式造的，","notes":[]},{"n":2,"t":"並且造男造女。在他們被造的日子，神賜福給他們，稱他們為「人」。）","notes":[]},{"n":3,"t":"亞當活到一百三十歲，生了一個兒子，形像樣式和自己相似，就給他起名叫塞特。","notes":[]},{"n":4,"t":"亞當生塞特之後，又在世八百年，並且生兒養女。","notes":[]},{"n":5,"t":"亞當共活了九百三十歲就死了。","notes":[]},{"n":6,"t":"塞特活到一百零五歲，生了以挪士。","notes":[]},{"n":7,"t":"塞特生以挪士之後，又活了八百零七年，並且生兒養女。","notes":[]},{"n":8,"t":"塞特共活了九百一十二歲就死了。","notes":[]},{"n":9,"t":"以挪士活到九十歲，生了該南。","notes":[]},{"n":10,"t":"以挪士生該南之後，又活了八百一十五年，並且生兒養女。","notes":[]},{"n":11,"t":"以挪士共活了九百零五歲就死了。","notes":[]},{"n":12,"t":"該南活到七十歲，生了瑪勒列。","notes":[]},{"n":13,"t":"該南生瑪勒列之後，又活了八百四十年，並且生兒養女。","notes":[]},{"n":14,"t":"該南共活了九百一十歲就死了。","notes":[]},{"n":15,"t":"瑪勒列活到六十五歲，生了雅列。","notes":[]},{"n":16,"t":"瑪勒列生雅列之後，又活了八百三十年，並且生兒養女。","notes":[]},{"n":17,"t":"瑪勒列共活了八百九十五歲就死了。","notes":[]},{"n":18,"t":"雅列活到一百六十二歲，生了以諾。","notes":[]},{"n":19,"t":"雅列生以諾之後，又活了八百年，並且生兒養女。","notes":[]},{"n":20,"t":"雅列共活了九百六十二歲就死了。","notes":[]},{"n":21,"t":"以諾活到六十五歲，生了瑪土撒拉。","notes":[]},{"n":22,"t":"以諾生瑪土撒拉之後，與神同行三百年，並且生兒養女。","notes":[]},{"n":23,"t":"以諾共活了三百六十五歲。","notes":[]},{"n":24,"t":"以諾與神同行，神將他取去，他就不在世了。","notes":[]},{"n":25,"t":"瑪土撒拉活到一百八十七歲，生了拉麥。","notes":[]},{"n":26,"t":"瑪土撒拉生拉麥之後，又活了七百八十二年，並且生兒養女。","notes":[]},{"n":27,"t":"瑪土撒拉共活了九百六十九歲就死了。","notes":[]},{"n":28,"t":"拉麥活到一百八十二歲，生了一個兒子，","notes":[]},{"n":29,"t":"給他起名叫挪亞，說：「這個兒子必為我們的操作和手中的勞苦安慰我們；這操作勞苦是因為耶和華咒詛地。」","notes":[]},{"n":30,"t":"拉麥生挪亞之後，又活了五百九十五年，並且生兒養女。","notes":[]},{"n":31,"t":"拉麥共活了七百七十七歲就死了。","notes":[]},{"n":32,"t":"挪亞五百歲生了閃、含、雅弗。","notes":[]}]},"6":{"heading":"人類的邪惡","verses":[{"n":1,"t":"當人在世上多起來、又生女兒的時候，","notes":[]},{"n":2,"t":"神的兒子們看見人的女子美貌，就隨意挑選，娶來為妻。","notes":[]},{"n":3,"t":"耶和華說：「人既屬乎血氣，我的靈就不永遠住在他裏面；然而他的日子還可到一百二十年。」","notes":[]},{"n":4,"t":"那時候有偉人在地上，後來神的兒子們和人的女子們交合生子；那就是上古英武有名的人。","notes":[]},{"n":5,"t":"耶和華見人在地上罪惡很大，終日所思想的盡都是惡，","notes":[]},{"n":6,"t":"耶和華就後悔造人在地上，心中憂傷。","notes":[]},{"n":7,"t":"耶和華說：「我要將所造的人和走獸，並昆蟲，以及空中的飛鳥，都從地上除滅，因為我造他們後悔了。」","notes":[]},{"n":8,"t":"惟有挪亞在耶和華眼前蒙恩。","notes":[]},{"n":9,"t":"挪亞的後代記在下面。挪亞是個義人，在當時的世代是個完全人。挪亞與神同行。","notes":[],"heads":["挪亞"]},{"n":10,"t":"挪亞生了三個兒子，就是閃、含、雅弗。","notes":[]},{"n":11,"t":"世界在神面前敗壞，地上滿了強暴。","notes":[]},{"n":12,"t":"神觀看世界，見是敗壞了；凡有血氣的人在地上都敗壞了行為。","notes":[]},{"n":13,"t":"神就對挪亞說：「凡有血氣的人，他的盡頭已經來到我面前；因為地上滿了他們的強暴，我要把他們和地一併毀滅。","notes":[]},{"n":14,"t":"你要用歌斐木造一隻方舟，分一間一間地造，裏外抹上松香。","notes":[]},{"n":15,"t":"方舟的造法乃是這樣：要長三百肘，寬五十肘，高三十肘。","notes":[]},{"n":16,"t":"方舟上邊要留透光處，高一肘。方舟的門要開在旁邊。方舟要分上、中、下三層。","notes":[]},{"n":17,"t":"看哪，我要使洪水氾濫在地上，毀滅天下；凡地上有血肉、有氣息的活物，無一不死。","notes":[]},{"n":18,"t":"我卻要與你立約；你同你的妻，與兒子兒婦，都要進入方舟。","notes":[]},{"n":19,"t":"凡有血肉的活物，每樣兩個，一公一母，你要帶進方舟，好在你那裏保全生命。","notes":[]},{"n":20,"t":"飛鳥各從其類，牲畜各從其類，地上的昆蟲各從其類，每樣兩個，要到你那裏，好保全生命。","notes":[]},{"n":21,"t":"你要拿各樣食物積蓄起來，好作你和牠們的食物。」","notes":[]},{"n":22,"t":"挪亞就這樣行。凡神所吩咐的，他都照樣行了。","notes":[]}]},"7":{"heading":"洪水","verses":[{"n":1,"t":"耶和華對挪亞說：「你和你的全家都要進入方舟；因為在這世代中，我見你在我面前是義人。","notes":[]},{"n":2,"t":"凡潔淨的畜類，你要帶七公七母；不潔淨的畜類，你要帶一公一母；","notes":[]},{"n":3,"t":"空中的飛鳥也要帶七公七母，可以留種，活在全地上；","notes":[]},{"n":4,"t":"因為再過七天，我要降雨在地上四十晝夜，把我所造的各種活物都從地上除滅。」","notes":[]},{"n":5,"t":"挪亞就遵著耶和華所吩咐的行了。","notes":[]},{"n":6,"t":"當洪水氾濫在地上的時候，挪亞整六百歲。","notes":[]},{"n":7,"t":"挪亞就同他的妻和兒子兒婦都進入方舟，躲避洪水。","notes":[]},{"n":8,"t":"潔淨的畜類和不潔淨的畜類，飛鳥並地上一切的昆蟲，","notes":[]},{"n":9,"t":"都是一對一對地，有公有母，到挪亞那裏進入方舟，正如神所吩咐挪亞的。","notes":[]},{"n":10,"t":"過了那七天，洪水氾濫在地上。","notes":[]},{"n":11,"t":"當挪亞六百歲，二月十七日那一天，大淵的泉源都裂開了，天上的窗戶也敞開了，","notes":[]},{"n":12,"t":"四十晝夜降大雨在地上。","notes":[]},{"n":13,"t":"正當那日，挪亞和他三個兒子閃、含、雅弗，並挪亞的妻子和三個兒婦，都進入方舟。","notes":[]},{"n":14,"t":"他們和百獸，各從其類，一切牲畜，各從其類，爬在地上的昆蟲，各從其類，一切禽鳥，各從其類，都進入方舟。","notes":[]},{"n":15,"t":"凡有血肉、有氣息的活物，都一對一對地到挪亞那裏，進入方舟。","notes":[]},{"n":16,"t":"凡有血肉進入方舟的，都是有公有母，正如神所吩咐挪亞的。耶和華就把他關在方舟裏頭。","notes":[]},{"n":17,"t":"洪水氾濫在地上四十天，水往上長，把方舟從地上漂起。","notes":[]},{"n":18,"t":"水勢浩大，在地上大大地往上長，方舟在水面上漂來漂去。","notes":[]},{"n":19,"t":"水勢在地上極其浩大，天下的高山都淹沒了。","notes":[]},{"n":20,"t":"水勢比山高過十五肘，山嶺都淹沒了。","notes":[]},{"n":21,"t":"凡在地上有血肉的動物，就是飛鳥、牲畜、走獸，和爬在地上的昆蟲，以及所有的人，都死了。","notes":[]},{"n":22,"t":"凡在旱地上、鼻孔有氣息的生靈都死了。","notes":[]},{"n":23,"t":"凡地上各類的活物，連人帶牲畜、昆蟲，以及空中的飛鳥，都從地上除滅了，只留下挪亞和那些與他同在方舟裏的。","notes":[]},{"n":24,"t":"水勢浩大，在地上共一百五十天。","notes":[]}]},"8":{"heading":"洪水消退","verses":[{"n":1,"t":"神記念挪亞和挪亞方舟裏的一切走獸牲畜。神叫風吹地，水勢漸落。","notes":[]},{"n":2,"t":"淵源和天上的窗戶都閉塞了，天上的大雨也止住了。","notes":[]},{"n":3,"t":"水從地上漸退。過了一百五十天，水就漸消。","notes":[]},{"n":4,"t":"七月十七日，方舟停在亞拉臘山上。","notes":[]},{"n":5,"t":"水又漸消，到十月初一日，山頂都現出來了。","notes":[]},{"n":6,"t":"過了四十天，挪亞開了方舟的窗戶，","notes":[]},{"n":7,"t":"放出一隻烏鴉去；那烏鴉飛來飛去，直到地上的水都乾了。","notes":[]},{"n":8,"t":"他又放出一隻鴿子去，要看看水從地上退了沒有。","notes":[]},{"n":9,"t":"但遍地上都是水，鴿子找不著落腳之地，就回到方舟挪亞那裏，挪亞伸手把鴿子接進方舟來。","notes":[]},{"n":10,"t":"他又等了七天，再把鴿子從方舟放出去。","notes":[]},{"n":11,"t":"到了晚上，鴿子回到他那裏，嘴裏叼著一個新擰下來的橄欖葉子，挪亞就知道地上的水退了。","notes":[]},{"n":12,"t":"他又等了七天，放出鴿子去，鴿子就不再回來了。","notes":[]},{"n":13,"t":"到挪亞六百零一歲，正月初一日，地上的水都乾了。挪亞撤去方舟的蓋觀看，便見地面上乾了。","notes":[]},{"n":14,"t":"到了二月二十七日，地就都乾了。","notes":[]},{"n":15,"t":"神對挪亞說：","notes":[]},{"n":16,"t":"「你和你的妻子、兒子、兒婦都可以出方舟。","notes":[]},{"n":17,"t":"在你那裏凡有血肉的活物，就是飛鳥、牲畜，和一切爬在地上的昆蟲，都要帶出來，叫牠在地上多多滋生，大大興旺。」","notes":[]},{"n":18,"t":"於是挪亞和他的妻子、兒子、兒婦都出來了。","notes":[]},{"n":19,"t":"一切走獸、昆蟲、飛鳥，和地上所有的動物，各從其類，也都出了方舟。","notes":[]},{"n":20,"t":"挪亞為耶和華築了一座壇，拿各類潔淨的牲畜、飛鳥獻在壇上為燔祭。","notes":[],"heads":["挪亞獻祭"]},{"n":21,"t":"耶和華聞那馨香之氣，就心裏說：「我不再因人的緣故咒詛地（人從小時心裏懷著惡念），也不再按著我才行的滅各種的活物了。","notes":[]},{"n":22,"t":"地還存留的時候，稼穡、寒暑、冬夏、晝夜就永不停息了。」","notes":[]}]},"9":{"heading":"神跟挪亞立約","verses":[{"n":1,"t":"神賜福給挪亞和他的兒子，對他們說：「你們要生養眾多，遍滿了地。","notes":[]},{"n":2,"t":"凡地上的走獸和空中的飛鳥都必驚恐，懼怕你們，連地上一切的昆蟲並海裏一切的魚都交付你們的手。","notes":[]},{"n":3,"t":"凡活著的動物都可以作你們的食物。這一切我都賜給你們，如同菜蔬一樣。","notes":[]},{"n":4,"t":"惟獨肉帶著血，那就是牠的生命，你們不可吃。","notes":[]},{"n":5,"t":"流你們血、害你們命的，無論是獸是人，我必討他的罪，就是向各人的弟兄也是如此。","notes":[]},{"n":6,"t":"凡流人血的，他的血也必被人所流，因為神造人是照自己的形像造的。","notes":[]},{"n":7,"t":"你們要生養眾多，在地上昌盛繁茂。」","notes":[]},{"n":8,"t":"神曉諭挪亞和他的兒子說：","notes":[]},{"n":9,"t":"「我與你們和你們的後裔立約，","notes":[]},{"n":10,"t":"並與你們這裏的一切活物－就是飛鳥、牲畜、走獸，凡從方舟裏出來的活物－立約。","notes":[]},{"n":11,"t":"我與你們立約，凡有血肉的，不再被洪水滅絕，也不再有洪水毀壞地了。」","notes":[]},{"n":12,"t":"神說：「我與你們並你們這裏的各樣活物所立的永約是有記號的。","notes":[]},{"n":13,"t":"我把虹放在雲彩中，這就可作我與地立約的記號了。","notes":[]},{"n":14,"t":"我使雲彩蓋地的時候，必有虹現在雲彩中，","notes":[]},{"n":15,"t":"我便記念我與你們和各樣有血肉的活物所立的約，水就再不氾濫、毀壞一切有血肉的物了。","notes":[]},{"n":16,"t":"虹必現在雲彩中，我看見，就要記念我與地上各樣有血肉的活物所立的永約。」","notes":[]},{"n":17,"t":"神對挪亞說：「這就是我與地上一切有血肉之物立約的記號了。」","notes":[]},{"n":18,"t":"出方舟挪亞的兒子就是閃、含、雅弗。含是迦南的父親。","notes":[],"heads":["挪亞和他的兒子們"]},{"n":19,"t":"這是挪亞的三個兒子，他們的後裔分散在全地。","notes":[]},{"n":20,"t":"挪亞作起農夫來，栽了一個葡萄園。","notes":[]},{"n":21,"t":"他喝了園中的酒便醉了，在帳棚裏赤著身子。","notes":[]},{"n":22,"t":"迦南的父親含看見他父親赤身，就到外邊告訴他兩個弟兄。","notes":[]},{"n":23,"t":"於是閃和雅弗拿件衣服搭在肩上，倒退著進去，給他父親蓋上；他們背著臉就看不見父親的赤身。","notes":[]},{"n":24,"t":"挪亞醒了酒，知道小兒子向他所做的事，","notes":[]},{"n":25,"t":"就說：迦南當受咒詛，必給他弟兄作奴僕的奴僕；","notes":[]},{"n":26,"t":"又說：耶和華－閃的神是應當稱頌的！願迦南作閃的奴僕。","notes":[]},{"n":27,"t":"願神使雅弗擴張，使他住在閃的帳棚裏；又願迦南作他的奴僕。","notes":[]},{"n":28,"t":"洪水以後，挪亞又活了三百五十年。","notes":[]},{"n":29,"t":"挪亞共活了九百五十歲就死了。","notes":[]}]},"10":{"heading":"閃、含、雅弗的後代","verses":[{"n":1,"t":"挪亞的兒子閃、含、雅弗的後代記在下面。洪水以後，他們都生了兒子。","notes":[]},{"n":2,"t":"雅弗的兒子是歌篾、瑪各、瑪代、雅完、土巴、米設、提拉。","notes":[]},{"n":3,"t":"歌篾的兒子是亞實基拿、利法、陀迦瑪。","notes":[]},{"n":4,"t":"雅完的兒子是以利沙、他施、基提、多單。","notes":[]},{"n":5,"t":"這些人的後裔將各國的地土、海島分開居住，各隨各的方言、宗族立國。","notes":[]},{"n":6,"t":"含的兒子是古實、麥西、弗、迦南。","notes":[]},{"n":7,"t":"古實的兒子是西巴、哈腓拉、撒弗他、拉瑪、撒弗提迦。拉瑪的兒子是示巴、底但。","notes":[]},{"n":8,"t":"古實又生寧錄，他為世上英雄之首。","notes":[]},{"n":9,"t":"他在耶和華面前是個英勇的獵戶，所以俗語說：「像寧錄在耶和華面前是個英勇的獵戶。」","notes":[]},{"n":10,"t":"他國的起頭是巴別、以力、亞甲、甲尼，都在示拿地。","notes":[]},{"n":11,"t":"他從那地出來往亞述去，建造尼尼微、利河伯、迦拉，","notes":[]},{"n":12,"t":"和尼尼微、迦拉中間的利鮮，這就是那大城。","notes":[]},{"n":13,"t":"麥西生路低人、亞拿米人、利哈比人、拿弗土希人、","notes":[]},{"n":14,"t":"帕斯魯細人、迦斯路希人、迦斐託人；從迦斐託出來的有非利士人。","notes":[]},{"n":15,"t":"迦南生長子西頓，又生赫","notes":[]},{"n":16,"t":"和耶布斯人、亞摩利人、革迦撒人、","notes":[]},{"n":17,"t":"希未人、亞基人、西尼人、","notes":[]},{"n":18,"t":"亞瓦底人、洗瑪利人、哈馬人，後來迦南的諸族分散了。","notes":[]},{"n":19,"t":"迦南的境界是從西頓向基拉耳的路上，直到迦薩，又向所多瑪、蛾摩拉、押瑪、洗扁的路上，直到拉沙。","notes":[]},{"n":20,"t":"這就是含的後裔，各隨他們的宗族、方言，所住的地土、邦國。","notes":[]},{"n":21,"t":"雅弗的哥哥閃，是希伯子孫之祖，他也生了兒子。","notes":[]},{"n":22,"t":"閃的兒子是以攔、亞述、亞法撒、路德、亞蘭。","notes":[]},{"n":23,"t":"亞蘭的兒子是烏斯、戶勒、基帖、瑪施。","notes":[]},{"n":24,"t":"亞法撒生沙拉；沙拉生希伯。","notes":[]},{"n":25,"t":"希伯生了兩個兒子，一個名叫法勒，因為那時人就分地居住；法勒的兄弟名叫約坍。","notes":["就是分的意思"]},{"n":26,"t":"約坍生亞摩答、沙列、哈薩瑪非、耶拉、","notes":[]},{"n":27,"t":"哈多蘭、烏薩、德拉、","notes":[]},{"n":28,"t":"俄巴路、亞比瑪利、示巴、","notes":[]},{"n":29,"t":"阿斐、哈腓拉、約巴，這都是約坍的兒子。","notes":[]},{"n":30,"t":"他們所住的地方是從米沙直到西發東邊的山。","notes":[]},{"n":31,"t":"這就是閃的子孫，各隨他們的宗族、方言，所住的地土、邦國。","notes":[]},{"n":32,"t":"這些都是挪亞三個兒子的宗族，各隨他們的支派立國。洪水以後，他們在地上分為邦國。","notes":[]}]},"11":{"heading":"巴別塔","verses":[{"n":1,"t":"那時，天下人的口音、言語都是一樣。","notes":[]},{"n":2,"t":"他們往東邊遷移的時候，在示拿地遇見一片平原，就住在那裏。","notes":[]},{"n":3,"t":"他們彼此商量說：「來吧！我們要做磚，把磚燒透了。」他們就拿磚當石頭，又拿石漆當灰泥。","notes":[]},{"n":4,"t":"他們說：「來吧！我們要建造一座城和一座塔，塔頂通天，為要傳揚我們的名，免得我們分散在全地上。」","notes":[]},{"n":5,"t":"耶和華降臨，要看看世人所建造的城和塔。","notes":[]},{"n":6,"t":"耶和華說：「看哪，他們成為一樣的人民，都是一樣的言語，如今既做起這事來，以後他們所要做的事就沒有不成就的了。","notes":[]},{"n":7,"t":"我們下去，在那裏變亂他們的口音，使他們的言語彼此不通。」","notes":[]},{"n":8,"t":"於是耶和華使他們從那裏分散在全地上；他們就停工，不造那城了。","notes":[]},{"n":9,"t":"因為耶和華在那裏變亂天下人的言語，使眾人分散在全地上，所以那城名叫巴別。","notes":["就是變亂的意思"]},{"n":10,"t":"閃的後代記在下面。洪水以後二年，閃一百歲生了亞法撒。","notes":[],"heads":["閃的後代"]},{"n":11,"t":"閃生亞法撒之後又活了五百年，並且生兒養女。","notes":[]},{"n":12,"t":"亞法撒活到三十五歲，生了沙拉。","notes":[]},{"n":13,"t":"亞法撒生沙拉之後又活了四百零三年，並且生兒養女。","notes":[]},{"n":14,"t":"沙拉活到三十歲，生了希伯。","notes":[]},{"n":15,"t":"沙拉生希伯之後又活了四百零三年，並且生兒養女。","notes":[]},{"n":16,"t":"希伯活到三十四歲，生了法勒。","notes":[]},{"n":17,"t":"希伯生法勒之後又活了四百三十年，並且生兒養女。","notes":[]},{"n":18,"t":"法勒活到三十歲，生了拉吳。","notes":[]},{"n":19,"t":"法勒生拉吳之後又活了二百零九年，並且生兒養女。","notes":[]},{"n":20,"t":"拉吳活到三十二歲，生了西鹿。","notes":[]},{"n":21,"t":"拉吳生西鹿之後又活了二百零七年，並且生兒養女。","notes":[]},{"n":22,"t":"西鹿活到三十歲，生了拿鶴。","notes":[]},{"n":23,"t":"西鹿生拿鶴之後又活了二百年，並且生兒養女。","notes":[]},{"n":24,"t":"拿鶴活到二十九歲，生了他拉。","notes":[]},{"n":25,"t":"拿鶴生他拉之後又活了一百一十九年，並且生兒養女。","notes":[]},{"n":26,"t":"他拉活到七十歲，生了亞伯蘭、拿鶴、哈蘭。","notes":[]},{"n":27,"t":"他拉的後代記在下面。他拉生亞伯蘭、拿鶴、哈蘭；哈蘭生羅得。","notes":[],"heads":["他拉的後代"]},{"n":28,"t":"哈蘭死在他的本地迦勒底的吾珥，在他父親他拉之先。","notes":[]},{"n":29,"t":"亞伯蘭、拿鶴各娶了妻：亞伯蘭的妻子名叫撒萊；拿鶴的妻子名叫密迦，是哈蘭的女兒；哈蘭是密迦和亦迦的父親。","notes":[]},{"n":30,"t":"撒萊不生育，沒有孩子。","notes":[]},{"n":31,"t":"他拉帶著他兒子亞伯蘭和他孫子哈蘭的兒子羅得，並他兒婦亞伯蘭的妻子撒萊，出了迦勒底的吾珥，要往迦南地去；他們走到哈蘭，就住在那裏。","notes":[]},{"n":32,"t":"他拉共活了二百零五歲，就死在哈蘭。","notes":[]}]},"12":{"heading":"神呼召亞伯蘭","verses":[{"n":1,"t":"耶和華對亞伯蘭說：「你要離開本地、本族、父家，往我所要指示你的地去。","notes":[]},{"n":2,"t":"我必叫你成為大國。我必賜福給你，叫你的名為大；你也要叫別人得福。","notes":[]},{"n":3,"t":"為你祝福的，我必賜福與他；那咒詛你的，我必咒詛他。地上的萬族都要因你得福。」","notes":[]},{"n":4,"t":"亞伯蘭就照著耶和華的吩咐去了；羅得也和他同去。亞伯蘭出哈蘭的時候年七十五歲。","notes":[]},{"n":5,"t":"亞伯蘭將他妻子撒萊和姪兒羅得，連他們在哈蘭所積蓄的財物、所得的人口，都帶往迦南地去。他們就到了迦南地。","notes":[]},{"n":6,"t":"亞伯蘭經過那地，到了示劍地方、摩利橡樹那裏。那時迦南人住在那地。","notes":[]},{"n":7,"t":"耶和華向亞伯蘭顯現，說：「我要把這地賜給你的後裔。」亞伯蘭就在那裏為向他顯現的耶和華築了一座壇。","notes":[]},{"n":8,"t":"從那裏他又遷到伯特利東邊的山，支搭帳棚；西邊是伯特利，東邊是艾。他在那裏又為耶和華築了一座壇，求告耶和華的名。","notes":[]},{"n":9,"t":"後來亞伯蘭又漸漸遷往南地去。","notes":[]},{"n":10,"t":"那地遭遇饑荒。因饑荒甚大，亞伯蘭就下埃及去，要在那裏暫居。","notes":[],"heads":["亞伯蘭到埃及"]},{"n":11,"t":"將近埃及，就對他妻子撒萊說：「我知道你是容貌俊美的婦人。","notes":[]},{"n":12,"t":"埃及人看見你必說：『這是他的妻子』，他們就要殺我，卻叫你存活。","notes":[]},{"n":13,"t":"求你說，你是我的妹子，使我因你得平安，我的命也因你存活。」","notes":[]},{"n":14,"t":"及至亞伯蘭到了埃及，埃及人看見那婦人極其美貌。","notes":[]},{"n":15,"t":"法老的臣宰看見了她，就在法老面前誇獎她。那婦人就被帶進法老的宮去。","notes":[]},{"n":16,"t":"法老因這婦人就厚待亞伯蘭，亞伯蘭得了許多牛、羊、駱駝、公驢、母驢、僕婢。","notes":[]},{"n":17,"t":"耶和華因亞伯蘭妻子撒萊的緣故，降大災與法老和他的全家。","notes":[]},{"n":18,"t":"法老就召了亞伯蘭來，說：「你這向我做的是甚麼事呢？為甚麼沒有告訴我她是你的妻子？","notes":[]},{"n":19,"t":"為甚麼說她是你的妹子，以致我把她取來要作我的妻子？現在你的妻子在這裏，可以帶她走吧。」","notes":[]},{"n":20,"t":"於是法老吩咐人將亞伯蘭和他妻子，並他所有的都送走了。","notes":[]}]},"13":{"heading":"亞伯蘭跟羅得分手","verses":[{"n":1,"t":"亞伯蘭帶著他的妻子與羅得，並一切所有的，都從埃及上南地去。","notes":[]},{"n":2,"t":"亞伯蘭的金、銀、牲畜極多。","notes":[]},{"n":3,"t":"他從南地漸漸往伯特利去，到了伯特利和艾的中間，就是從前支搭帳棚的地方，","notes":[]},{"n":4,"t":"也是他起先築壇的地方；他又在那裏求告耶和華的名。","notes":[]},{"n":5,"t":"與亞伯蘭同行的羅得也有牛群、羊群、帳棚。","notes":[]},{"n":6,"t":"那地容不下他們；因為他們的財物甚多，使他們不能同居。","notes":[]},{"n":7,"t":"當時，迦南人與比利洗人在那地居住。亞伯蘭的牧人和羅得的牧人相爭。","notes":[]},{"n":8,"t":"亞伯蘭就對羅得說：「你我不可相爭，你的牧人和我的牧人也不可相爭，因為我們是骨肉。","notes":["原文是弟兄"]},{"n":9,"t":"遍地不都在你眼前嗎？請你離開我：你向左，我就向右；你向右，我就向左。」","notes":[]},{"n":10,"t":"羅得舉目看見約旦河的全平原，直到瑣珥，都是滋潤的，那地在耶和華未滅所多瑪、蛾摩拉以先如同耶和華的園子，也像埃及地。","notes":[]},{"n":11,"t":"於是羅得選擇約旦河的全平原，往東遷移；他們就彼此分離了。","notes":[]},{"n":12,"t":"亞伯蘭住在迦南地，羅得住在平原的城邑，漸漸挪移帳棚，直到所多瑪。","notes":[]},{"n":13,"t":"所多瑪人在耶和華面前罪大惡極。","notes":[]},{"n":14,"t":"羅得離別亞伯蘭以後，耶和華對亞伯蘭說：「從你所在的地方，你舉目向東西南北觀看；","notes":[],"heads":["亞伯蘭遷往希伯崙"]},{"n":15,"t":"凡你所看見的一切地，我都要賜給你和你的後裔，直到永遠。","notes":[]},{"n":16,"t":"我也要使你的後裔如同地上的塵沙那樣多，人若能數算地上的塵沙才能數算你的後裔。","notes":[]},{"n":17,"t":"你起來，縱橫走遍這地，因為我必把這地賜給你。」","notes":[]},{"n":18,"t":"亞伯蘭就搬了帳棚，來到希伯崙幔利的橡樹那裏居住，在那裏為耶和華築了一座壇。","notes":[]}]},"14":{"heading":"亞伯蘭搶救羅得","verses":[{"n":1,"t":"當暗拉非作示拿王，亞略作以拉撒王，基大老瑪作以攔王，提達作戈印王的時候，","notes":[]},{"n":2,"t":"他們都攻打所多瑪王比拉、蛾摩拉王比沙、押瑪王示納、洗扁王善以別，和比拉王；比拉就是瑣珥。","notes":[]},{"n":3,"t":"這五王都在西訂谷會合；西訂谷就是鹽海。","notes":[]},{"n":4,"t":"他們已經事奉基大老瑪十二年，到十三年就背叛了。","notes":[]},{"n":5,"t":"十四年，基大老瑪和同盟的王都來在亞特律‧加寧，殺敗了利乏音人，在哈麥殺敗了蘇西人，在沙微‧基列亭殺敗了以米人，","notes":[]},{"n":6,"t":"在何利人的西珥山殺敗了何利人，一直殺到靠近曠野的伊勒‧巴蘭。","notes":[]},{"n":7,"t":"他們回到安‧密巴，就是加低斯，殺敗了亞瑪力全地的人，以及住在哈洗遜‧他瑪的亞摩利人。","notes":[]},{"n":8,"t":"於是所多瑪王、蛾摩拉王、押瑪王、洗扁王，和比拉王（比拉就是瑣珥）都出來，在西訂谷擺陣，與他們交戰，","notes":[]},{"n":9,"t":"就是與以攔王基大老瑪、戈印王提達、示拿王暗拉非、以拉撒王亞略交戰；乃是四王與五王交戰。","notes":[]},{"n":10,"t":"西訂谷有許多石漆坑。所多瑪王和蛾摩拉王逃跑，有掉在坑裏的，其餘的人都往山上逃跑。","notes":[]},{"n":11,"t":"四王就把所多瑪和蛾摩拉所有的財物，並一切的糧食都擄掠去了；","notes":[]},{"n":12,"t":"又把亞伯蘭的姪兒羅得和羅得的財物擄掠去了。當時羅得正住在所多瑪。","notes":[]},{"n":13,"t":"有一個逃出來的人告訴希伯來人亞伯蘭；亞伯蘭正住在亞摩利人幔利的橡樹那裏。幔利和以實各並亞乃都是弟兄，曾與亞伯蘭聯盟。","notes":[]},{"n":14,"t":"亞伯蘭聽見他姪兒被擄去，就率領他家裏生養的精練壯丁三百一十八人，直追到但，","notes":["原文是弟兄"]},{"n":15,"t":"便在夜間，自己同僕人分隊殺敗敵人，又追到大馬士革左邊的何把，","notes":[]},{"n":16,"t":"將被擄掠的一切財物奪回來，連他姪兒羅得和他的財物，以及婦女、人民也都奪回來。","notes":[]},{"n":17,"t":"亞伯蘭殺敗基大老瑪和與他同盟的王回來的時候，所多瑪王出來，在沙微谷迎接他；沙微谷就是王谷。","notes":[],"heads":["麥基洗德祝福亞伯蘭"]},{"n":18,"t":"又有撒冷王麥基洗德帶著餅和酒出來迎接；他是至高神的祭司。","notes":[]},{"n":19,"t":"他為亞伯蘭祝福，說：「願天地的主、至高的神賜福與亞伯蘭！","notes":[]},{"n":20,"t":"至高的神把敵人交在你手裏，是應當稱頌的！」亞伯蘭就把所得的拿出十分之一來，給麥基洗德。","notes":[]},{"n":21,"t":"所多瑪王對亞伯蘭說：「你把人口給我，財物你自己拿去吧！」","notes":[]},{"n":22,"t":"亞伯蘭對所多瑪王說：「我已經向天地的主－至高的神耶和華起誓：","notes":[]},{"n":23,"t":"凡是你的東西，就是一根線、一根鞋帶，我都不拿，免得你說：『我使亞伯蘭富足！』","notes":[]},{"n":24,"t":"只有僕人所吃的，並與我同行的亞乃、以實各、幔利所應得的分，可以任憑他們拿去。」","notes":[]}]},"15":{"heading":"神與亞伯蘭立約","verses":[{"n":1,"t":"這事以後，耶和華在異象中有話對亞伯蘭說：「亞伯蘭，你不要懼怕！我是你的盾牌，必大大地賞賜你。」","notes":[]},{"n":2,"t":"亞伯蘭說：「主耶和華啊，我既無子，你還賜我甚麼呢？並且要承受我家業的是大馬士革人以利以謝。」","notes":[]},{"n":3,"t":"亞伯蘭又說：「你沒有給我兒子；那生在我家中的人就是我的後嗣。」","notes":[]},{"n":4,"t":"耶和華又有話對他說：「這人必不成為你的後嗣；你本身所生的才成為你的後嗣。」","notes":[]},{"n":5,"t":"於是領他走到外邊，說：「你向天觀看，數算眾星，能數得過來嗎？」又對他說：「你的後裔將要如此。」","notes":[]},{"n":6,"t":"亞伯蘭信耶和華，耶和華就以此為他的義。","notes":[]},{"n":7,"t":"耶和華又對他說：「我是耶和華，曾領你出了迦勒底的吾珥，為要將這地賜你為業。」","notes":[]},{"n":8,"t":"亞伯蘭說：「主耶和華啊，我怎能知道必得這地為業呢？」","notes":[]},{"n":9,"t":"他說：「你為我取一隻三年的母牛，一隻三年的母山羊，一隻三年的公綿羊，一隻斑鳩，一隻雛鴿。」","notes":[]},{"n":10,"t":"亞伯蘭就取了這些來，每樣劈開，分成兩半，一半對著一半地擺列，只有鳥沒有劈開。","notes":[]},{"n":11,"t":"有鷙鳥下來，落在那死畜的肉上，亞伯蘭就把牠嚇飛了。","notes":[]},{"n":12,"t":"日頭正落的時候，亞伯蘭沉沉地睡了；忽然有驚人的大黑暗落在他身上。","notes":[]},{"n":13,"t":"耶和華對亞伯蘭說：「你要的確知道，你的後裔必寄居別人的地，又服事那地的人；那地的人要苦待他們四百年。","notes":[]},{"n":14,"t":"並且他們所要服事的那國，我要懲罰，後來他們必帶著許多財物從那裏出來。","notes":[]},{"n":15,"t":"但你要享大壽數，平平安安地歸到你列祖那裏，被人埋葬。","notes":[]},{"n":16,"t":"到了第四代，他們必回到此地，因為亞摩利人的罪孽還沒有滿盈。」","notes":[]},{"n":17,"t":"日落天黑，不料有冒煙的爐並燒著的火把從那些肉塊中經過。","notes":[]},{"n":18,"t":"當那日，耶和華與亞伯蘭立約，說：「我已賜給你的後裔，從埃及河直到幼發拉底大河之地，","notes":[]},{"n":19,"t":"就是基尼人、基尼洗人、甲摩尼人、","notes":[]},{"n":20,"t":"赫人、比利洗人、利乏音人、","notes":[]},{"n":21,"t":"亞摩利人、迦南人、革迦撒人、耶布斯人之地。」","notes":[]}]},"16":{"heading":"夏甲和以實瑪利","verses":[{"n":1,"t":"亞伯蘭的妻子撒萊不給他生兒女。撒萊有一個使女，名叫夏甲，是埃及人。","notes":[]},{"n":2,"t":"撒萊對亞伯蘭說：「耶和華使我不能生育。求你和我的使女同房，或者我可以因她得孩子。」亞伯蘭聽從了撒萊的話。","notes":["得孩子：原文是被建立"]},{"n":3,"t":"於是亞伯蘭的妻子撒萊將使女埃及人夏甲給了丈夫為妾；那時亞伯蘭在迦南已經住了十年。","notes":[]},{"n":4,"t":"亞伯蘭與夏甲同房，夏甲就懷了孕；她見自己有孕，就小看她的主母。","notes":[]},{"n":5,"t":"撒萊對亞伯蘭說：「我因你受屈。我將我的使女放在你懷中，她見自己有了孕，就小看我。願耶和華在你我中間判斷。」","notes":[]},{"n":6,"t":"亞伯蘭對撒萊說：「使女在你手下，你可以隨意待她。」撒萊苦待她，她就從撒萊面前逃走了。","notes":[]},{"n":7,"t":"耶和華的使者在曠野書珥路上的水泉旁遇見她，","notes":[]},{"n":8,"t":"對她說：「撒萊的使女夏甲，你從哪裏來？要往哪裏去？」夏甲說：「我從我的主母撒萊面前逃出來。」","notes":[]},{"n":9,"t":"耶和華的使者對她說：「你回到你主母那裏，服在她手下」；","notes":[]},{"n":10,"t":"又說：「我必使你的後裔極其繁多，甚至不可勝數」；","notes":[]},{"n":11,"t":"並說：「你如今懷孕要生一個兒子，可以給他起名叫以實瑪利，因為耶和華聽見了你的苦情。","notes":["就是神聽見的意思"]},{"n":12,"t":"他為人必像野驢。他的手要攻打人，人的手也要攻打他；他必住在眾弟兄的東邊。」","notes":[]},{"n":13,"t":"夏甲就稱那對她說話的耶和華為「看顧人的神」。因而說：「在這裏我也看見那看顧我的嗎？」","notes":[]},{"n":14,"t":"所以這井名叫庇耳‧拉海‧萊。這井正在加低斯和巴列中間。","notes":[]},{"n":15,"t":"後來夏甲給亞伯蘭生了一個兒子；亞伯蘭給他起名叫以實瑪利。","notes":[]},{"n":16,"t":"夏甲給亞伯蘭生以實瑪利的時候，亞伯蘭年八十六歲。","notes":[]}]},"17":{"heading":"割禮－立約的記號","verses":[{"n":1,"t":"亞伯蘭年九十九歲的時候，耶和華向他顯現，對他說：「我是全能的神。你當在我面前作完全人，","notes":[]},{"n":2,"t":"我就與你立約，使你的後裔極其繁多。」","notes":[]},{"n":3,"t":"亞伯蘭俯伏在地；神又對他說：","notes":[]},{"n":4,"t":"「我與你立約：你要作多國的父。","notes":[]},{"n":5,"t":"從此以後，你的名不再叫亞伯蘭，要叫亞伯拉罕，因為我已立你作多國的父。","notes":[]},{"n":6,"t":"我必使你的後裔極其繁多；國度從你而立，君王從你而出。","notes":[]},{"n":7,"t":"我要與你並你世世代代的後裔堅立我的約，作永遠的約，是要作你和你後裔的神。","notes":[]},{"n":8,"t":"我要將你現在寄居的地，就是迦南全地，賜給你和你的後裔永遠為業，我也必作他們的神。」","notes":[]},{"n":9,"t":"神又對亞伯拉罕說：「你和你的後裔必世世代代遵守我的約。","notes":[]},{"n":10,"t":"你們所有的男子都要受割禮；這就是我與你並你的後裔所立的約，是你們所當遵守的。","notes":[]},{"n":11,"t":"你們都要受割禮；這是我與你們立約的證據。","notes":["原文是割陽皮；十四、二十三、二十四、二十五節同"]},{"n":12,"t":"你們世世代代的男子，無論是家裏生的，是在你後裔之外用銀子從外人買的，生下來第八日，都要受割禮。","notes":[]},{"n":13,"t":"你家裏生的和你用銀子買的，都必須受割禮。這樣，我的約就立在你們肉體上作永遠的約。","notes":[]},{"n":14,"t":"但不受割禮的男子必從民中剪除，因他背了我的約。」","notes":[]},{"n":15,"t":"神又對亞伯拉罕說：「你的妻子撒萊不可再叫撒萊，她的名要叫撒拉。","notes":[]},{"n":16,"t":"我必賜福給她，也要使你從她得一個兒子。我要賜福給她，她也要作多國之母；必有百姓的君王從她而出。」","notes":[]},{"n":17,"t":"亞伯拉罕就俯伏在地喜笑，心裏說：「一百歲的人還能得孩子嗎？撒拉已經九十歲了，還能生養嗎？」","notes":[]},{"n":18,"t":"亞伯拉罕對神說：「但願以實瑪利活在你面前。」","notes":[]},{"n":19,"t":"神說：「不然，你妻子撒拉要給你生一個兒子，你要給他起名叫以撒。我要與他堅定所立的約，作他後裔永遠的約。","notes":[]},{"n":20,"t":"至於以實瑪利，我也應允你：我必賜福給他，使他昌盛，極其繁多。他必生十二個族長；我也要使他成為大國。","notes":[]},{"n":21,"t":"到明年這時節，撒拉必給你生以撒，我要與他堅定所立的約。」","notes":[]},{"n":22,"t":"神和亞伯拉罕說完了話，就離開他上升去了。","notes":[]},{"n":23,"t":"正當那日，亞伯拉罕遵著神的命，給他的兒子以實瑪利和家裏的一切男子，無論是在家裏生的，是用銀子買的，都行了割禮。","notes":[]},{"n":24,"t":"亞伯拉罕受割禮的時候年九十九歲。","notes":[]},{"n":25,"t":"他兒子以實瑪利受割禮的時候年十三歲。","notes":[]},{"n":26,"t":"正當那日，亞伯拉罕和他兒子以實瑪利一同受了割禮。","notes":[]},{"n":27,"t":"家裏所有的人，無論是在家裏生的，是用銀子從外人買的，也都一同受了割禮。","notes":[]}]},"18":{"heading":"神應許亞伯拉罕得兒子","verses":[{"n":1,"t":"耶和華在幔利橡樹那裏向亞伯拉罕顯現出來。那時正熱，亞伯拉罕坐在帳棚門口，","notes":[]},{"n":2,"t":"舉目觀看，見有三個人在對面站著。他一見，就從帳棚門口跑去迎接他們，俯伏在地，","notes":[]},{"n":3,"t":"說：「我主，我若在你眼前蒙恩，求你不要離開僕人往前去。","notes":[]},{"n":4,"t":"容我拿點水來，你們洗洗腳，在樹下歇息歇息。","notes":[]},{"n":5,"t":"我再拿一點餅來，你們可以加添心力，然後往前去。你們既到僕人這裏來，理當如此。」他們說：「就照你說的行吧。」","notes":[]},{"n":6,"t":"亞伯拉罕急忙進帳棚見撒拉，說：「你速速拿三細亞細麵調和做餅。」","notes":[]},{"n":7,"t":"亞伯拉罕又跑到牛群裏，牽了一隻又嫩又好的牛犢來，交給僕人，僕人急忙預備好了。","notes":[]},{"n":8,"t":"亞伯拉罕又取了奶油和奶，並預備好的牛犢來，擺在他們面前，自己在樹下站在旁邊，他們就吃了。","notes":[]},{"n":9,"t":"他們問亞伯拉罕說：「你妻子撒拉在哪裏？」他說：「在帳棚裏。」","notes":[]},{"n":10,"t":"三人中有一位說：「到明年這時候，我必要回到你這裏；你的妻子撒拉必生一個兒子。」撒拉在那人後邊的帳棚門口也聽見了這話。","notes":[]},{"n":11,"t":"亞伯拉罕和撒拉年紀老邁，撒拉的月經已斷絕了。","notes":[]},{"n":12,"t":"撒拉心裏暗笑，說：「我既已衰敗，我主也老邁，豈能有這喜事呢？」","notes":[]},{"n":13,"t":"耶和華對亞伯拉罕說：「撒拉為甚麼暗笑，說：『我既已年老，果真能生養嗎？』","notes":[]},{"n":14,"t":"耶和華豈有難成的事嗎？到了日期，明年這時候，我必回到你這裏，撒拉必生一個兒子。」","notes":[]},{"n":15,"t":"撒拉就害怕，不承認，說：「我沒有笑。」那位說：「不然，你實在笑了。」","notes":[]},{"n":16,"t":"三人就從那裏起行，向所多瑪觀看，亞伯拉罕也與他們同行，要送他們一程。","notes":[],"heads":["亞伯拉罕為所多瑪祈求"]},{"n":17,"t":"耶和華說：「我所要做的事豈可瞞著亞伯拉罕呢？","notes":[]},{"n":18,"t":"亞伯拉罕必要成為強大的國；地上的萬國都必因他得福。","notes":[]},{"n":19,"t":"我眷顧他，為要叫他吩咐他的眾子和他的眷屬遵守我的道，秉公行義，使我所應許亞伯拉罕的話都成就了。」","notes":[]},{"n":20,"t":"耶和華說：「所多瑪和蛾摩拉的罪惡甚重，聲聞於我。","notes":[]},{"n":21,"t":"我現在要下去，察看他們所行的，果然盡像那達到我耳中的聲音一樣嗎？若是不然，我也必知道。」","notes":[]},{"n":22,"t":"二人轉身離開那裏，向所多瑪去；但亞伯拉罕仍舊站在耶和華面前。","notes":[]},{"n":23,"t":"亞伯拉罕近前來，說：「無論善惡，你都要剿滅嗎？","notes":[]},{"n":24,"t":"假若那城裏有五十個義人，你還剿滅那地方嗎？不為城裏這五十個義人饒恕其中的人嗎？","notes":[]},{"n":25,"t":"將義人與惡人同殺，將義人與惡人一樣看待，這斷不是你所行的。審判全地的主豈不行公義嗎？」","notes":[]},{"n":26,"t":"耶和華說：「我若在所多瑪城裏見有五十個義人，我就為他們的緣故饒恕那地方的眾人。」","notes":[]},{"n":27,"t":"亞伯拉罕說：「我雖然是灰塵，還敢對主說話。","notes":[]},{"n":28,"t":"假若這五十個義人短了五個，你就因為短了五個毀滅全城嗎？」他說：「我在那裏若見有四十五個，也不毀滅那城。」","notes":[]},{"n":29,"t":"亞伯拉罕又對他說：「假若在那裏見有四十個怎麼樣呢？」他說：「為這四十個的緣故，我也不做這事。」","notes":[]},{"n":30,"t":"亞伯拉罕說：「求主不要動怒，容我說，假若在那裏見有三十個怎麼樣呢？」他說：「我在那裏若見有三十個，我也不做這事。」","notes":[]},{"n":31,"t":"亞伯拉罕說：「我還敢對主說話，假若在那裏見有二十個怎麼樣呢？」他說：「為這二十個的緣故，我也不毀滅那城。」","notes":[]},{"n":32,"t":"亞伯拉罕說：「求主不要動怒，我再說這一次，假若在那裏見有十個呢？」他說：「為這十個的緣故，我也不毀滅那城。」","notes":[]},{"n":33,"t":"耶和華與亞伯拉罕說完了話就走了；亞伯拉罕也回到自己的地方去了。","notes":[]}]},"19":{"heading":"所多瑪的罪惡","verses":[{"n":1,"t":"那兩個天使晚上到了所多瑪；羅得正坐在所多瑪城門口，看見他們，就起來迎接，臉伏於地下拜，","notes":[]},{"n":2,"t":"說：「我主啊，請你們到僕人家裏洗洗腳，住一夜，清早起來再走。」他們說：「不！我們要在街上過夜。」","notes":[]},{"n":3,"t":"羅得切切地請他們，他們這才進去，到他屋裏。羅得為他們預備筵席，烤無酵餅，他們就吃了。","notes":[]},{"n":4,"t":"他們還沒有躺下，所多瑪城裏各處的人，連老帶少，都來圍住那房子，","notes":[]},{"n":5,"t":"呼叫羅得說：「今日晚上到你這裏來的人在哪裏呢？把他們帶出來，任我們所為。」","notes":[]},{"n":6,"t":"羅得出來，把門關上，到眾人那裏，","notes":[]},{"n":7,"t":"說：「眾弟兄，請你們不要做這惡事。","notes":[]},{"n":8,"t":"我有兩個女兒，還是處女，容我領出來，任憑你們的心願而行；只是這兩個人既然到我舍下，不要向他們做甚麼。」","notes":[]},{"n":9,"t":"眾人說：「退去吧！」又說：「這個人來寄居，還想要作官哪！現在我們要害你比害他們更甚。」眾人就向前擁擠羅得，要攻破房門。","notes":[]},{"n":10,"t":"只是那二人伸出手來，將羅得拉進屋去，把門關上，","notes":[]},{"n":11,"t":"並且使門外的人，無論老少，眼都昏迷；他們摸來摸去，總尋不著房門。","notes":[]},{"n":12,"t":"二人對羅得說：「你這裏還有甚麼人嗎？無論是女婿是兒女，和這城中一切屬你的人，你都要將他們從這地方帶出去。","notes":[],"heads":["羅得離開所多瑪"]},{"n":13,"t":"我們要毀滅這地方；因為城內罪惡的聲音在耶和華面前甚大，耶和華差我們來，要毀滅這地方。」","notes":[]},{"n":14,"t":"羅得就出去，告訴娶了他女兒的女婿們說：「你們起來離開這地方，因為耶和華要毀滅這城。」他女婿們卻以為他說的是戲言。","notes":["或譯：將要娶"]},{"n":15,"t":"天明了，天使催逼羅得說：「起來！帶著你的妻子和你在這裏的兩個女兒出去，免得你因這城裏的罪惡同被剿滅。」","notes":[]},{"n":16,"t":"但羅得遲延不走。二人因為耶和華憐恤羅得，就拉著他的手和他妻子的手，並他兩個女兒的手，把他們領出來，安置在城外；","notes":[]},{"n":17,"t":"領他們出來以後，就說：「逃命吧！不可回頭看，也不可在平原站住。要往山上逃跑，免得你被剿滅。」","notes":[]},{"n":18,"t":"羅得對他們說：「我主啊，不要如此！","notes":[]},{"n":19,"t":"你僕人已經在你眼前蒙恩；你又向我顯出莫大的慈愛，救我的性命。我不能逃到山上去，恐怕這災禍臨到我，我便死了。","notes":[]},{"n":20,"t":"看哪，這座城又小又近，容易逃到，這不是一個小的嗎？求你容我逃到那裏，我的性命就得存活。」","notes":[]},{"n":21,"t":"天使對他說：「這事我也應允你；我不傾覆你所說的這城。","notes":[]},{"n":22,"t":"你要速速地逃到那城；因為你還沒有到那裏，我不能做甚麼。」因此那城名叫瑣珥。","notes":["就是小的意思"]},{"n":23,"t":"羅得到了瑣珥，日頭已經出來了。","notes":[],"heads":["所多瑪蛾摩拉的毀滅"]},{"n":24,"t":"當時，耶和華將硫磺與火從天上耶和華那裏降與所多瑪和蛾摩拉，","notes":[]},{"n":25,"t":"把那些城和全平原，並城裏所有的居民，連地上生長的，都毀滅了。","notes":[]},{"n":26,"t":"羅得的妻子在後邊回頭一看，就變成了一根鹽柱。","notes":[]},{"n":27,"t":"亞伯拉罕清早起來，到了他從前站在耶和華面前的地方，","notes":[]},{"n":28,"t":"向所多瑪和蛾摩拉與平原的全地觀看，不料，那地方煙氣上騰，如同燒窯一般。","notes":[]},{"n":29,"t":"當神毀滅平原諸城的時候，他記念亞伯拉罕，正在傾覆羅得所住之城的時候，就打發羅得從傾覆之中出來。","notes":[]},{"n":30,"t":"羅得因為怕住在瑣珥，就同他兩個女兒從瑣珥上去，住在山裏；他和兩個女兒住在一個洞裏。","notes":[],"heads":["摩押人和亞捫人的起源"]},{"n":31,"t":"大女兒對小女兒說：「我們的父親老了，地上又無人按著世上的常規進到我們這裏。","notes":[]},{"n":32,"t":"來！我們可以叫父親喝酒，與他同寢。這樣，我們好從他存留後裔。」","notes":[]},{"n":33,"t":"於是，那夜她們叫父親喝酒，大女兒就進去和她父親同寢；她幾時躺下，幾時起來，父親都不知道。","notes":[]},{"n":34,"t":"第二天，大女兒對小女兒說：「我昨夜與父親同寢。今夜我們再叫他喝酒，你可以進去與他同寢。這樣，我們好從父親存留後裔。」","notes":[]},{"n":35,"t":"於是，那夜她們又叫父親喝酒，小女兒起來與她父親同寢；她幾時躺下，幾時起來，父親都不知道。","notes":[]},{"n":36,"t":"這樣，羅得的兩個女兒都從她父親懷了孕。","notes":[]},{"n":37,"t":"大女兒生了兒子，給他起名叫摩押，就是現今摩押人的始祖。","notes":[]},{"n":38,"t":"小女兒也生了兒子，給他起名叫便‧亞米，就是現今亞捫人的始祖。","notes":[]}]},"20":{"heading":"亞伯拉罕和亞比米勒","verses":[{"n":1,"t":"亞伯拉罕從那裏向南地遷去，寄居在加低斯和書珥中間的基拉耳。","notes":[]},{"n":2,"t":"亞伯拉罕稱他的妻撒拉為妹子，基拉耳王亞比米勒差人把撒拉取了去。","notes":[]},{"n":3,"t":"但夜間，神來，在夢中對亞比米勒說：「你是個死人哪！因為你取了那女人來；她原是別人的妻子。」","notes":[]},{"n":4,"t":"亞比米勒卻還沒有親近撒拉；他說：「主啊，連有義的國，你也要毀滅嗎？","notes":[]},{"n":5,"t":"那人豈不是自己對我說『她是我的妹子』嗎？就是女人也自己說：『他是我的哥哥。』我做這事是心正手潔的。」","notes":[]},{"n":6,"t":"神在夢中對他說：「我知道你做這事是心中正直；我也攔阻了你，免得你得罪我，所以我不容你沾著她。","notes":[]},{"n":7,"t":"現在你把這人的妻子歸還他；因為他是先知，他要為你禱告，使你存活。你若不歸還他，你當知道，你和你所有的人都必要死。」","notes":[]},{"n":8,"t":"亞比米勒清早起來，召了眾臣僕來，將這些事都說給他們聽，他們都甚懼怕。","notes":[]},{"n":9,"t":"亞比米勒召了亞伯拉罕來，對他說：「你怎麼向我這樣行呢？我在甚麼事上得罪了你，你竟使我和我國裏的人陷在大罪裏？你向我行不當行的事了！」","notes":[]},{"n":10,"t":"亞比米勒又對亞伯拉罕說：「你見了甚麼才做這事呢？」","notes":[]},{"n":11,"t":"亞伯拉罕說：「我以為這地方的人總不懼怕神，必為我妻子的緣故殺我。","notes":[]},{"n":12,"t":"況且她也實在是我的妹子；她與我是同父異母，後來作了我的妻子。","notes":[]},{"n":13,"t":"當神叫我離開父家、飄流在外的時候，我對她說：『我們無論走到甚麼地方，你可以對人說：他是我的哥哥；這就是你待我的恩典了。』」","notes":[]},{"n":14,"t":"亞比米勒把牛、羊、僕婢賜給亞伯拉罕，又把他的妻子撒拉歸還他。","notes":[]},{"n":15,"t":"亞比米勒又說：「看哪，我的地都在你面前，你可以隨意居住」；","notes":[]},{"n":16,"t":"又對撒拉說：「我給你哥哥一千銀子，作為你在閤家人面前遮羞的，你就在眾人面前沒有不是了。」","notes":["羞：原文是眼"]},{"n":17,"t":"亞伯拉罕禱告神，神就醫好了亞比米勒和他的妻子，並他的眾女僕，她們便能生育。","notes":[]},{"n":18,"t":"因耶和華為亞伯拉罕的妻子撒拉的緣故，已經使亞比米勒家中的婦人不能生育。","notes":[]}]},"21":{"heading":"以撒出生","verses":[{"n":1,"t":"耶和華按著先前的話眷顧撒拉，便照他所說的給撒拉成就。","notes":[]},{"n":2,"t":"當亞伯拉罕年老的時候，撒拉懷了孕；到神所說的日期，就給亞伯拉罕生了一個兒子。","notes":[]},{"n":3,"t":"亞伯拉罕給撒拉所生的兒子起名叫以撒。","notes":[]},{"n":4,"t":"以撒生下來第八日，亞伯拉罕照著神所吩咐的，給以撒行了割禮。","notes":[]},{"n":5,"t":"他兒子以撒生的時候，亞伯拉罕年一百歲。","notes":[]},{"n":6,"t":"撒拉說：「神使我喜笑，凡聽見的必與我一同喜笑」；","notes":[]},{"n":7,"t":"又說：「誰能預先對亞伯拉罕說『撒拉要乳養嬰孩』呢？因為在他年老的時候，我給他生了一個兒子。」","notes":[]},{"n":8,"t":"孩子漸長，就斷了奶。以撒斷奶的日子，亞伯拉罕設擺豐盛的筵席。","notes":[]},{"n":9,"t":"當時，撒拉看見埃及人夏甲給亞伯拉罕所生的兒子戲笑，","notes":[],"heads":["夏甲和以實瑪利被逐"]},{"n":10,"t":"就對亞伯拉罕說：「你把這使女和她兒子趕出去！因為這使女的兒子不可與我的兒子以撒一同承受產業。」","notes":[]},{"n":11,"t":"亞伯拉罕因他兒子的緣故很憂愁。","notes":[]},{"n":12,"t":"神對亞伯拉罕說：「你不必為這童子和你的使女憂愁。凡撒拉對你說的話，你都該聽從；因為從以撒生的，才要稱為你的後裔。","notes":[]},{"n":13,"t":"至於使女的兒子，我也必使他的後裔成立一國，因為他是你所生的。」","notes":[]},{"n":14,"t":"亞伯拉罕清早起來，拿餅和一皮袋水，給了夏甲，搭在她的肩上，又把孩子交給她，打發她走。夏甲就走了，在別是巴的曠野走迷了路。","notes":[]},{"n":15,"t":"皮袋的水用盡了，夏甲就把孩子撇在小樹底下，","notes":[]},{"n":16,"t":"自己走開約有一箭之遠，相對而坐，說：「我不忍見孩子死」，就相對而坐，放聲大哭。","notes":[]},{"n":17,"t":"神聽見童子的聲音；神的使者從天上呼叫夏甲說：「夏甲，你為何這樣呢？不要害怕，神已經聽見童子的聲音了。","notes":[]},{"n":18,"t":"起來！把童子抱在懷中，我必使他的後裔成為大國。」","notes":["懷：原文是手"]},{"n":19,"t":"神使夏甲的眼睛明亮，她就看見一口水井，便去將皮袋盛滿了水，給童子喝。","notes":[]},{"n":20,"t":"神保佑童子，他就漸長，住在曠野，成了弓箭手。","notes":[]},{"n":21,"t":"他住在巴蘭的曠野；他母親從埃及地給他娶了一個妻子。","notes":[]},{"n":22,"t":"當那時候，亞比米勒同他軍長非各對亞伯拉罕說：「凡你所行的事都有神的保佑。","notes":[],"heads":["亞伯拉罕跟亞比米勒立約"]},{"n":23,"t":"我願你如今在這裏指著神對我起誓，不要欺負我與我的兒子，並我的子孫。我怎樣厚待了你，你也要照樣厚待我與你所寄居這地的民。」","notes":[]},{"n":24,"t":"亞伯拉罕說：「我情願起誓。」","notes":[]},{"n":25,"t":"從前，亞比米勒的僕人霸佔了一口水井，亞伯拉罕為這事指責亞比米勒。","notes":[]},{"n":26,"t":"亞比米勒說：「誰做這事，我不知道，你也沒有告訴我，今日我才聽見了。」","notes":[]},{"n":27,"t":"亞伯拉罕把羊和牛給了亞比米勒，二人就彼此立約。","notes":[]},{"n":28,"t":"亞伯拉罕把七隻母羊羔另放在一處。","notes":[]},{"n":29,"t":"亞比米勒問亞伯拉罕說：「你把這七隻母羊羔另放在一處，是甚麼意思呢？」","notes":[]},{"n":30,"t":"他說：「你要從我手裏受這七隻母羊羔，作我挖這口井的證據。」","notes":[]},{"n":31,"t":"所以他給那地方起名叫別是巴，因為他們二人在那裏起了誓。","notes":["就是盟誓的井的意思"]},{"n":32,"t":"他們在別是巴立了約，亞比米勒就同他軍長非各起身回非利士地去了。","notes":[]},{"n":33,"t":"亞伯拉罕在別是巴栽上一棵垂絲柳樹，又在那裏求告耶和華－永生神的名。","notes":[]},{"n":34,"t":"亞伯拉罕在非利士人的地寄居了多日。","notes":[]}]},"22":{"heading":"神吩咐亞伯拉罕獻以撒","verses":[{"n":1,"t":"這些事以後，神要試驗亞伯拉罕，就呼叫他說：「亞伯拉罕！」他說：「我在這裏。」","notes":[]},{"n":2,"t":"神說：「你帶著你的兒子，就是你獨生的兒子，你所愛的以撒，往摩利亞地去，在我所要指示你的山上，把他獻為燔祭。」","notes":[]},{"n":3,"t":"亞伯拉罕清早起來，備上驢，帶著兩個僕人和他兒子以撒，也劈好了燔祭的柴，就起身往神所指示他的地方去了。","notes":[]},{"n":4,"t":"到了第三日，亞伯拉罕舉目遠遠地看見那地方。","notes":[]},{"n":5,"t":"亞伯拉罕對他的僕人說：「你們和驢在此等候，我與童子往那裏去拜一拜，就回到你們這裏來。」","notes":[]},{"n":6,"t":"亞伯拉罕把燔祭的柴放在他兒子以撒身上，自己手裏拿著火與刀；於是二人同行。","notes":[]},{"n":7,"t":"以撒對他父親亞伯拉罕說：「父親哪！」亞伯拉罕說：「我兒，我在這裏。」以撒說：「請看，火與柴都有了，但燔祭的羊羔在哪裏呢？」","notes":[]},{"n":8,"t":"亞伯拉罕說：「我兒，神必自己預備作燔祭的羊羔。」於是二人同行。","notes":[]},{"n":9,"t":"他們到了神所指示的地方，亞伯拉罕在那裏築壇，把柴擺好，捆綁他的兒子以撒，放在壇的柴上。","notes":[]},{"n":10,"t":"亞伯拉罕就伸手拿刀，要殺他的兒子。","notes":[]},{"n":11,"t":"耶和華的使者從天上呼叫他說：「亞伯拉罕！亞伯拉罕！」他說：「我在這裏。」","notes":[]},{"n":12,"t":"天使說：「你不可在這童子身上下手。一點不可害他！現在我知道你是敬畏神的了；因為你沒有將你的兒子，就是你獨生的兒子，留下不給我。」","notes":[]},{"n":13,"t":"亞伯拉罕舉目觀看，不料，有一隻公羊，兩角扣在稠密的小樹中。亞伯拉罕就取了那隻公羊來，獻為燔祭，代替他的兒子。","notes":[]},{"n":14,"t":"亞伯拉罕給那地方起名叫「耶和華以勒」，直到今日人還說：「在耶和華的山上必有預備。」","notes":["就是耶和華必預備的意思"]},{"n":15,"t":"耶和華的使者第二次從天上呼叫亞伯拉罕說：","notes":[]},{"n":16,"t":"「耶和華說：『你既行了這事，不留下你的兒子，就是你獨生的兒子，我便指著自己起誓說：","notes":[]},{"n":17,"t":"論福，我必賜大福給你；論子孫，我必叫你的子孫多起來，如同天上的星，海邊的沙。你子孫必得著仇敵的城門，","notes":[]},{"n":18,"t":"並且地上萬國都必因你的後裔得福，因為你聽從了我的話。』」","notes":[]},{"n":19,"t":"於是亞伯拉罕回到他僕人那裏，他們一同起身往別是巴去，亞伯拉罕就住在別是巴。","notes":[]},{"n":20,"t":"這事以後，有人告訴亞伯拉罕說：「密迦給你兄弟拿鶴生了幾個兒子，","notes":[],"heads":["拿鶴的後代"]},{"n":21,"t":"長子是烏斯，他的兄弟是布斯和亞蘭的父親基母利，","notes":[]},{"n":22,"t":"並基薛、哈瑣、必達、益拉、彼土利（彼土利生利百加）。」","notes":[]},{"n":23,"t":"這八個人都是密迦給亞伯拉罕的兄弟拿鶴生的。","notes":[]},{"n":24,"t":"拿鶴的妾名叫流瑪，生了提八、迦含、他轄，和瑪迦。","notes":[]}]},"23":{"heading":"亞伯拉罕買墳地埋葬撒拉","verses":[{"n":1,"t":"撒拉享壽一百二十七歲，這是撒拉一生的歲數。","notes":[]},{"n":2,"t":"撒拉死在迦南地的基列‧亞巴，就是希伯崙。亞伯拉罕為她哀慟哭號。","notes":[]},{"n":3,"t":"後來亞伯拉罕從死人面前起來，對赫人說：","notes":[]},{"n":4,"t":"「我在你們中間是外人，是寄居的。求你們在這裏給我一塊地，我好埋葬我的死人，使她不在我眼前。」","notes":[]},{"n":5,"t":"赫人回答亞伯拉罕說：","notes":[]},{"n":6,"t":"「我主請聽。你在我們中間是一位尊大的王子，只管在我們最好的墳地裏埋葬你的死人；我們沒有一人不容你在他的墳地裏埋葬你的死人。」","notes":[]},{"n":7,"t":"亞伯拉罕就起來，向那地的赫人下拜，","notes":[]},{"n":8,"t":"對他們說：「你們若有意叫我埋葬我的死人，使她不在我眼前，就請聽我的話，為我求瑣轄的兒子以弗崙，","notes":[]},{"n":9,"t":"把田頭上那麥比拉洞給我，他可以按著足價賣給我，作我在你們中間的墳地。」","notes":[]},{"n":10,"t":"當時以弗崙正坐在赫人中間。於是，赫人以弗崙在城門出入的赫人面前對亞伯拉罕說：","notes":[]},{"n":11,"t":"「不然，我主請聽。我送給你這塊田，連田間的洞也送給你，在我同族的人面前都給你，可以埋葬你的死人。」","notes":[]},{"n":12,"t":"亞伯拉罕就在那地的人民面前下拜，","notes":[]},{"n":13,"t":"在他們面前對以弗崙說：「你若應允，請聽我的話。我要把田價給你，求你收下，我就在那裏埋葬我的死人。」","notes":[]},{"n":14,"t":"以弗崙回答亞伯拉罕說：","notes":[]},{"n":15,"t":"「我主請聽。值四百舍客勒銀子的一塊田，在你我中間還算甚麼呢？只管埋葬你的死人吧！」","notes":[]},{"n":16,"t":"亞伯拉罕聽從了以弗崙，照著他在赫人面前所說的話，把買賣通用的銀子平了四百舍客勒給以弗崙。","notes":[]},{"n":17,"t":"於是，麥比拉、幔利前、以弗崙的那塊田和其中的洞，並田間四圍的樹木，","notes":[]},{"n":18,"t":"都定準歸與亞伯拉罕，乃是他在赫人面前並城門出入的人面前買妥的。","notes":[]},{"n":19,"t":"此後，亞伯拉罕把他妻子撒拉埋葬在迦南地幔利前的麥比拉田間的洞裏。（幔利就是希伯崙）。","notes":[]},{"n":20,"t":"從此，那塊田和田間的洞就藉著赫人定準歸與亞伯拉罕作墳地。","notes":[]}]},"24":{"heading":"以撒娶妻","verses":[{"n":1,"t":"亞伯拉罕年紀老邁，向來在一切事上耶和華都賜福給他。","notes":[]},{"n":2,"t":"亞伯拉罕對管理他全業最老的僕人說：「請你把手放在我大腿底下。","notes":[]},{"n":3,"t":"我要叫你指著耶和華－天地的主起誓，不要為我兒子娶這迦南地中的女子為妻。","notes":[]},{"n":4,"t":"你要往我本地本族去，為我的兒子以撒娶一個妻子。」","notes":[]},{"n":5,"t":"僕人對他說：「倘若女子不肯跟我到這地方來，我必須將你的兒子帶回你原出之地嗎？」","notes":[]},{"n":6,"t":"亞伯拉罕對他說：「你要謹慎，不要帶我的兒子回那裏去。","notes":[]},{"n":7,"t":"耶和華－天上的主曾帶領我離開父家和本族的地，對我說話，向我起誓說：『我要將這地賜給你的後裔。』他必差遣使者在你面前，你就可以從那裏為我兒子娶一個妻子。","notes":[]},{"n":8,"t":"倘若女子不肯跟你來，我使你起的誓就與你無干了，只是不可帶我的兒子回那裏去。」","notes":[]},{"n":9,"t":"僕人就把手放在他主人亞伯拉罕的大腿底下，為這事向他起誓。","notes":[]},{"n":10,"t":"那僕人從他主人的駱駝裏取了十匹駱駝，並帶些他主人各樣的財物，起身往美索不達米亞去，到了拿鶴的城。","notes":[]},{"n":11,"t":"天將晚，眾女子出來打水的時候，他便叫駱駝跪在城外的水井那裏。","notes":[]},{"n":12,"t":"他說：「耶和華－我主人亞伯拉罕的神啊，求你施恩給我主人亞伯拉罕，使我今日遇見好機會。","notes":[]},{"n":13,"t":"我現今站在井旁，城內居民的女子們正出來打水。","notes":[]},{"n":14,"t":"我向那一個女子說：『請你拿下水瓶來，給我水喝。』她若說：『請喝！我也給你的駱駝喝。』願那女子就作你所預定給你僕人以撒的妻。這樣，我便知道你施恩給我主人了。」","notes":[]},{"n":15,"t":"話還沒有說完，不料，利百加肩頭上扛著水瓶出來。利百加是彼土利所生的；彼土利是亞伯拉罕兄弟拿鶴妻子密迦的兒子。","notes":[]},{"n":16,"t":"那女子容貌極其俊美，還是處女，也未曾有人親近她。她下到井旁，打滿了瓶，又上來。","notes":[]},{"n":17,"t":"僕人跑上前去迎著她，說：「求你將瓶裏的水給我一點喝。」","notes":[]},{"n":18,"t":"女子說：「我主請喝！」就急忙拿下瓶來，托在手上給他喝。","notes":[]},{"n":19,"t":"女子給他喝了，就說：「我再為你的駱駝打水，叫駱駝也喝足。」","notes":[]},{"n":20,"t":"她就急忙把瓶裏的水倒在槽裏，又跑到井旁打水，就為所有的駱駝打上水來。","notes":[]},{"n":21,"t":"那人定睛看她，一句話也不說，要曉得耶和華賜他通達的道路沒有。","notes":[]},{"n":22,"t":"駱駝喝足了，那人就拿一個金環，重半舍客勒，兩個金鐲，重十舍客勒，給了那女子，","notes":[]},{"n":23,"t":"說：「請告訴我，你是誰的女兒？你父親家裏有我們住宿的地方沒有？」","notes":[]},{"n":24,"t":"女子說：「我是密迦與拿鶴之子彼土利的女兒」；","notes":[]},{"n":25,"t":"又說：「我們家裏足有糧草，也有住宿的地方。」","notes":[]},{"n":26,"t":"那人就低頭向耶和華下拜，","notes":[]},{"n":27,"t":"說：「耶和華－我主人亞伯拉罕的神是應當稱頌的，因他不斷地以慈愛誠實待我主人。至於我，耶和華在路上引領我，直走到我主人的兄弟家裏。」","notes":[]},{"n":28,"t":"女子跑回去，照著這些話告訴她母親和她家裏的人。","notes":[]},{"n":29,"t":"利百加有一個哥哥，名叫拉班，看見金環，又看見金鐲在他妹子的手上，並聽見他妹子利百加的話，說那人對我如此如此說。拉班就跑出來往井旁去，到那人跟前，見他仍站在駱駝旁邊的井旁那裏，","notes":[],"end":30},{"n":31,"t":"便對他說：「你這蒙耶和華賜福的，請進來，為甚麼站在外邊？我已經收拾了房屋，也為駱駝預備了地方。」","notes":[]},{"n":32,"t":"那人就進了拉班的家。拉班卸了駱駝，用草料餵上，拿水給那人和跟隨的人洗腳；","notes":[]},{"n":33,"t":"把飯擺在他面前，叫他吃，他卻說：「我不吃，等我說明白我的事情再吃。」拉班說：「請說。」","notes":[]},{"n":34,"t":"他說：「我是亞伯拉罕的僕人。","notes":[]},{"n":35,"t":"耶和華大大地賜福給我主人，使他昌大，又賜給他羊群、牛群、金銀、僕婢、駱駝，和驢。","notes":[]},{"n":36,"t":"我主人的妻子撒拉年老的時候給我主人生了一個兒子；我主人也將一切所有的都給了這個兒子。","notes":[]},{"n":37,"t":"我主人叫我起誓說：『你不要為我兒子娶迦南地的女子為妻。","notes":[]},{"n":38,"t":"你要往我父家、我本族那裏去，為我的兒子娶一個妻子。』","notes":[]},{"n":39,"t":"我對我主人說：『恐怕女子不肯跟我來。』","notes":[]},{"n":40,"t":"他就說：『我所事奉的耶和華必要差遣他的使者與你同去，叫你的道路通達，你就得以在我父家、我本族那裏，給我的兒子娶一個妻子。","notes":[]},{"n":41,"t":"只要你到了我本族那裏，我使你起的誓就與你無干。他們若不把女子交給你，我使你起的誓也與你無干。』","notes":[]},{"n":42,"t":"「我今日到了井旁，便說：『耶和華－我主人亞伯拉罕的神啊，願你叫我所行的道路通達。","notes":[]},{"n":43,"t":"我如今站在井旁，對哪一個出來打水的女子說：請你把你瓶裏的水給我一點喝；","notes":[]},{"n":44,"t":"她若說：你只管喝，我也為你的駱駝打水；願那女子就作耶和華給我主人兒子所預定的妻。』","notes":[]},{"n":45,"t":"我心裏的話還沒有說完，利百加就出來，肩頭上扛著水瓶，下到井旁打水。我便對她說：『請你給我水喝。』","notes":[]},{"n":46,"t":"她就急忙從肩頭上拿下瓶來，說：『請喝！我也給你的駱駝喝。』我便喝了；她又給我的駱駝喝了。","notes":[]},{"n":47,"t":"我問她說：『你是誰的女兒？』她說：『我是密迦與拿鶴之子彼土利的女兒。』我就把環子戴在她鼻子上，把鐲子戴在她兩手上。","notes":[]},{"n":48,"t":"隨後我低頭向耶和華下拜，稱頌耶和華－我主人亞伯拉罕的神；因為他引導我走合式的道路，使我得著我主人兄弟的孫女，給我主人的兒子為妻。","notes":[]},{"n":49,"t":"現在你們若願以慈愛誠實待我主人，就告訴我；若不然，也告訴我，使我可以或向左，或向右。」","notes":[]},{"n":50,"t":"拉班和彼土利回答說：「這事乃出於耶和華，我們不能向你說好說歹。","notes":[]},{"n":51,"t":"看哪，利百加在你面前，可以將她帶去，照著耶和華所說的，給你主人的兒子為妻。」","notes":[]},{"n":52,"t":"亞伯拉罕的僕人聽見他們這話，就向耶和華俯伏在地。","notes":[]},{"n":53,"t":"當下僕人拿出金器、銀器，和衣服送給利百加，又將寶物送給她哥哥和她母親。","notes":[]},{"n":54,"t":"僕人和跟從他的人吃了喝了，住了一夜。早晨起來，僕人就說：「請打發我回我主人那裏去吧。」","notes":[]},{"n":55,"t":"利百加的哥哥和她母親說：「讓女子同我們再住幾天，至少十天，然後她可以去。」","notes":[]},{"n":56,"t":"僕人說：「耶和華既賜給我通達的道路，你們不要耽誤我，請打發我走，回我主人那裏去吧。」","notes":[]},{"n":57,"t":"他們說：「我們把女子叫來問問她」，","notes":[]},{"n":58,"t":"就叫了利百加來，問她說：「你和這人同去嗎？」利百加說：「我去。」","notes":[]},{"n":59,"t":"於是他們打發妹子利百加和她的乳母，同亞伯拉罕的僕人，並跟從僕人的，都走了。","notes":[]},{"n":60,"t":"他們就給利百加祝福說：我們的妹子啊，願你作千萬人的母！願你的後裔得著仇敵的城門！","notes":[]},{"n":61,"t":"利百加和她的使女們起來，騎上駱駝，跟著那僕人，僕人就帶著利百加走了。","notes":[]},{"n":62,"t":"那時，以撒住在南地，剛從庇耳‧拉海‧萊回來。","notes":[]},{"n":63,"t":"天將晚，以撒出來在田間默想，舉目一看，見來了些駱駝。","notes":[]},{"n":64,"t":"利百加舉目看見以撒，就急忙下了駱駝，","notes":[]},{"n":65,"t":"問那僕人說：「這田間走來迎接我們的是誰？」僕人說：「是我的主人。」利百加就拿帕子蒙上臉。","notes":[]},{"n":66,"t":"僕人就將所辦的一切事都告訴以撒。","notes":[]},{"n":67,"t":"以撒便領利百加進了他母親撒拉的帳棚，娶了她為妻，並且愛她。以撒自從他母親不在了，這才得了安慰。","notes":[]}]},"25":{"heading":"亞伯拉罕的其他後代","verses":[{"n":1,"t":"亞伯拉罕又娶了一妻，名叫基土拉。","notes":[]},{"n":2,"t":"基土拉給他生了心蘭、約珊、米但、米甸、伊施巴，和書亞。","notes":[]},{"n":3,"t":"約珊生了示巴和底但。底但的子孫是亞書利族、利都是族，和利烏米族。","notes":[]},{"n":4,"t":"米甸的兒子是以法、以弗、哈諾、亞比大，和以勒大。這都是基土拉的子孫。","notes":[]},{"n":5,"t":"亞伯拉罕將一切所有的都給了以撒。","notes":[]},{"n":6,"t":"亞伯拉罕把財物分給他庶出的眾子，趁著自己還在世的時候打發他們離開他的兒子以撒，往東方去。","notes":[]},{"n":7,"t":"亞伯拉罕一生的年日是一百七十五歲。","notes":[],"heads":["亞伯拉罕的死和埋葬"]},{"n":8,"t":"亞伯拉罕壽高年邁，氣絕而死，歸到他列祖那裏。","notes":["原文是本民"]},{"n":9,"t":"他兩個兒子以撒、以實瑪利把他埋葬在麥比拉洞裏。這洞在幔利前、赫人瑣轄的兒子以弗崙的田中，","notes":[]},{"n":10,"t":"就是亞伯拉罕向赫人買的那塊田。亞伯拉罕和他妻子撒拉都葬在那裏。","notes":[]},{"n":11,"t":"亞伯拉罕死了以後，神賜福給他的兒子以撒。以撒靠近庇耳‧拉海‧萊居住。","notes":[]},{"n":12,"t":"撒拉的使女埃及人夏甲給亞伯拉罕所生的兒子是以實瑪利。","notes":[],"heads":["以實瑪利的後代"]},{"n":13,"t":"以實瑪利兒子們的名字，按著他們的家譜記在下面。以實瑪利的長子是尼拜約，又有基達、亞德別、米比衫、","notes":[]},{"n":14,"t":"米施瑪、度瑪、瑪撒、","notes":[]},{"n":15,"t":"哈大、提瑪、伊突、拿非施、基底瑪。","notes":[]},{"n":16,"t":"這是以實瑪利眾子的名字，照著他們的村莊、營寨，作了十二族的族長。","notes":[]},{"n":17,"t":"以實瑪利享壽一百三十七歲，氣絕而死，歸到他列祖那裏。","notes":["原文是本民"]},{"n":18,"t":"他子孫的住處在他眾弟兄東邊，從哈腓拉直到埃及前的書珥，正在亞述的道上。","notes":[]},{"n":19,"t":"亞伯拉罕的兒子以撒的後代記在下面。亞伯拉罕生以撒。","notes":[],"heads":["以掃和雅各出生"]},{"n":20,"t":"以撒娶利百加為妻的時候正四十歲。利百加是巴旦‧亞蘭地的亞蘭人彼土利的女兒，是亞蘭人拉班的妹子。","notes":[]},{"n":21,"t":"以撒因他妻子不生育，就為她祈求耶和華；耶和華應允他的祈求，他的妻子利百加就懷了孕。","notes":[]},{"n":22,"t":"孩子們在她腹中彼此相爭，她就說：「若是這樣，我為甚麼活著呢？」她就去求問耶和華。","notes":["或譯：我為甚麼如此呢"]},{"n":23,"t":"耶和華對她說：兩國在你腹內；兩族要從你身上出來。這族必強於那族；將來大的要服事小的。","notes":[]},{"n":24,"t":"生產的日子到了，腹中果然是雙子。","notes":[]},{"n":25,"t":"先產的身體發紅，渾身有毛，如同皮衣，他們就給他起名叫以掃。","notes":["就是有毛的意思"]},{"n":26,"t":"隨後又生了以掃的兄弟，手抓住以掃的腳跟，因此給他起名叫雅各。利百加生下兩個兒子的時候，以撒年正六十歲。","notes":["就是抓住的意思"]},{"n":27,"t":"兩個孩子漸漸長大，以掃善於打獵，常在田野；雅各為人安靜，常住在帳棚裏。","notes":[],"heads":["以掃出賣長子的名分"]},{"n":28,"t":"以撒愛以掃，因為常吃他的野味；利百加卻愛雅各。","notes":[]},{"n":29,"t":"有一天，雅各熬湯，以掃從田野回來累昏了。","notes":[]},{"n":30,"t":"以掃對雅各說：「我累昏了，求你把這紅湯給我喝。」因此以掃又叫以東。","notes":["就是紅的意思"]},{"n":31,"t":"雅各說：「你今日把長子的名分賣給我吧。」","notes":[]},{"n":32,"t":"以掃說：「我將要死，這長子的名分於我有甚麼益處呢？」","notes":[]},{"n":33,"t":"雅各說：「你今日對我起誓吧。」以掃就對他起了誓，把長子的名分賣給雅各。","notes":[]},{"n":34,"t":"於是雅各將餅和紅豆湯給了以掃，以掃吃了喝了，便起來走了。這就是以掃輕看了他長子的名分。","notes":[]}]},"26":{"heading":"以撒住在基拉耳","verses":[{"n":1,"t":"在亞伯拉罕的日子，那地有一次饑荒；這時又有饑荒，以撒就往基拉耳去，到非利士人的王亞比米勒那裏。","notes":[]},{"n":2,"t":"耶和華向以撒顯現，說：「你不要下埃及去，要住在我所指示你的地。","notes":[]},{"n":3,"t":"你寄居在這地，我必與你同在，賜福給你，因為我要將這些地都賜給你和你的後裔。我必堅定我向你父亞伯拉罕所起的誓。","notes":[]},{"n":4,"t":"我要加增你的後裔，像天上的星那樣多，又要將這些地都賜給你的後裔。並且地上萬國必因你的後裔得福－","notes":[]},{"n":5,"t":"都因亞伯拉罕聽從我的話，遵守我的吩咐和我的命令、律例、法度。」","notes":[]},{"n":6,"t":"以撒就住在基拉耳。","notes":[]},{"n":7,"t":"那地方的人問到他的妻子，他便說：「那是我的妹子。」原來他怕說：「是我的妻子」；他心裏想：「恐怕這地方的人為利百加的緣故殺我」，因為她容貌俊美。","notes":[]},{"n":8,"t":"他在那裏住了許久。有一天，非利士人的王亞比米勒從窗戶裏往外觀看，見以撒和他的妻子利百加戲玩。","notes":[]},{"n":9,"t":"亞比米勒召了以撒來，對他說：「她實在是你的妻子，你怎麼說她是你的妹子？」以撒說：「我心裏想，恐怕我因她而死。」","notes":[]},{"n":10,"t":"亞比米勒說：「你向我們做的是甚麼事呢？民中險些有人和你的妻同寢，把我們陷在罪裏。」","notes":[]},{"n":11,"t":"於是亞比米勒曉諭眾民說：「凡沾著這個人，或是他妻子的，定要把他治死。」","notes":[]},{"n":12,"t":"以撒在那地耕種，那一年有百倍的收成。耶和華賜福給他，","notes":[]},{"n":13,"t":"他就昌大，日增月盛，成了大富戶。","notes":[]},{"n":14,"t":"他有羊群牛群，又有許多僕人，非利士人就嫉妒他。","notes":[]},{"n":15,"t":"當他父親亞伯拉罕在世的日子，他父親的僕人所挖的井，非利士人全都塞住，填滿了土。","notes":[]},{"n":16,"t":"亞比米勒對以撒說：「你離開我們去吧。因為你比我們強盛得多。」","notes":[]},{"n":17,"t":"以撒就離開那裏，在基拉耳谷支搭帳棚，住在那裏。","notes":[]},{"n":18,"t":"當他父親亞伯拉罕在世之日所挖的水井因非利士人在亞伯拉罕死後塞住了，以撒就重新挖出來，仍照他父親所叫的叫那些井的名字。","notes":[]},{"n":19,"t":"以撒的僕人在谷中挖井，便得了一口活水井。","notes":[]},{"n":20,"t":"基拉耳的牧人與以撒的牧人爭競，說：「這水是我們的。」以撒就給那井起名叫埃色，因為他們和他相爭。","notes":["就是相敵的意思"]},{"n":21,"t":"以撒的僕人又挖了一口井，他們又為這井爭競，因此以撒給這井起名叫西提拿。","notes":["就是為敵的意思"]},{"n":22,"t":"以撒離開那裏，又挖了一口井，他們不為這井爭競了，他就給那井起名叫利河伯。他說：「耶和華現在給我們寬闊之地，我們必在這地昌盛。」","notes":["就是寬闊的意思"]},{"n":23,"t":"以撒從那裏上別是巴去。","notes":[]},{"n":24,"t":"當夜耶和華向他顯現，說：「我是你父親亞伯拉罕的神，不要懼怕！因為我與你同在，要賜福給你，並要為我僕人亞伯拉罕的緣故，使你的後裔繁多。」","notes":[]},{"n":25,"t":"以撒就在那裏築了一座壇，求告耶和華的名，並且支搭帳棚；他的僕人便在那裏挖了一口井。","notes":[]},{"n":26,"t":"亞比米勒，同他的朋友亞戶撒和他的軍長非各，從基拉耳來見以撒。","notes":[],"heads":["以撒跟亞比米勒立約"]},{"n":27,"t":"以撒對他們說：「你們既然恨我，打發我走了，為甚麼到我這裏來呢？」","notes":[]},{"n":28,"t":"他們說：「我們明明地看見耶和華與你同在，便說，不如我們兩下彼此起誓，彼此立約，","notes":[]},{"n":29,"t":"使你不害我們，正如我們未曾害你，一味地厚待你，並且打發你平平安安地走。你是蒙耶和華賜福的了。」","notes":[]},{"n":30,"t":"以撒就為他們設擺筵席，他們便吃了喝了。","notes":[]},{"n":31,"t":"他們清早起來彼此起誓。以撒打發他們走，他們就平平安安地離開他走了。","notes":[]},{"n":32,"t":"那一天，以撒的僕人來，將挖井的事告訴他說：「我們得了水了。」","notes":[]},{"n":33,"t":"他就給那井起名叫示巴；因此那城叫做別是巴，直到今日。","notes":[]},{"n":34,"t":"以掃四十歲的時候娶了赫人比利的女兒猶滴，與赫人以倫的女兒巴實抹為妻。","notes":[],"heads":["以掃的外族妻子"]},{"n":35,"t":"她們常使以撒和利百加心裏愁煩。","notes":[]}]},"27":{"heading":"以撒祝福雅各","verses":[{"n":1,"t":"以撒年老，眼睛昏花，不能看見，就叫了他大兒子以掃來，說：「我兒。」以掃說：「我在這裏。」","notes":[]},{"n":2,"t":"他說：「我如今老了，不知道哪一天死。","notes":[]},{"n":3,"t":"現在拿你的器械，就是箭囊和弓，往田野去為我打獵，","notes":[]},{"n":4,"t":"照我所愛的做成美味，拿來給我吃，使我在未死之先給你祝福。」","notes":[]},{"n":5,"t":"以撒對他兒子以掃說話，利百加也聽見了。以掃往田野去打獵，要得野味帶來。","notes":[]},{"n":6,"t":"利百加就對她兒子雅各說：「我聽見你父親對你哥哥以掃說：","notes":[]},{"n":7,"t":"『你去把野獸帶來，做成美味給我吃，我好在未死之先，在耶和華面前給你祝福。』","notes":[]},{"n":8,"t":"現在，我兒，你要照著我所吩咐你的，聽從我的話。","notes":[]},{"n":9,"t":"你到羊群裏去，給我拿兩隻肥山羊羔來，我便照你父親所愛的給他做成美味。","notes":[]},{"n":10,"t":"你拿到你父親那裏給他吃，使他在未死之先給你祝福。」","notes":[]},{"n":11,"t":"雅各對他母親利百加說：「我哥哥以掃渾身是有毛的，我身上是光滑的；","notes":[]},{"n":12,"t":"倘若我父親摸著我，必以我為欺哄人的，我就招咒詛，不得祝福。」","notes":[]},{"n":13,"t":"他母親對他說：「我兒，你招的咒詛歸到我身上；你只管聽我的話，去把羊羔給我拿來。」","notes":[]},{"n":14,"t":"他便去拿來，交給他母親；他母親就照他父親所愛的做成美味。","notes":[]},{"n":15,"t":"利百加又把家裏所存大兒子以掃上好的衣服給她小兒子雅各穿上，","notes":[]},{"n":16,"t":"又用山羊羔皮包在雅各的手上和頸項的光滑處，","notes":[]},{"n":17,"t":"就把所做的美味和餅交在她兒子雅各的手裏。","notes":[]},{"n":18,"t":"雅各到他父親那裏說：「我父親！」他說：「我在這裏。我兒，你是誰？」","notes":[]},{"n":19,"t":"雅各對他父親說：「我是你的長子以掃；我已照你所吩咐我的行了。請起來坐著，吃我的野味，好給我祝福。」","notes":[]},{"n":20,"t":"以撒對他兒子說：「我兒，你如何找得這麼快呢？」他說：「因為耶和華－你的神使我遇見好機會得著的。」","notes":[]},{"n":21,"t":"以撒對雅各說：「我兒，你近前來，我摸摸你，知道你真是我的兒子以掃不是。」","notes":[]},{"n":22,"t":"雅各就挨近他父親以撒。以撒摸著他，說：「聲音是雅各的聲音，手卻是以掃的手。」","notes":[]},{"n":23,"t":"以撒就辨不出他來；因為他手上有毛，像他哥哥以掃的手一樣，就給他祝福；","notes":[]},{"n":24,"t":"又說：「你真是我兒子以掃嗎？」他說：「我是。」","notes":[]},{"n":25,"t":"以撒說：「你遞給我，我好吃我兒子的野味，給你祝福。」雅各就遞給他，他便吃了，又拿酒給他，他也喝了。","notes":[]},{"n":26,"t":"他父親以撒對他說：「我兒，你上前來與我親嘴。」","notes":[]},{"n":27,"t":"他就上前與父親親嘴。他父親一聞他衣服上的香氣，就給他祝福，說：我兒的香氣如同耶和華賜福之田地的香氣一樣。","notes":[]},{"n":28,"t":"願神賜你天上的甘露，地上的肥土，並許多五穀新酒。","notes":[]},{"n":29,"t":"願多民事奉你，多國跪拜你。願你作你弟兄的主；你母親的兒子向你跪拜。凡咒詛你的，願他受咒詛；為你祝福的，願他蒙福。","notes":[]},{"n":30,"t":"以撒為雅各祝福已畢，雅各從他父親那裏才出來，他哥哥以掃正打獵回來，","notes":[],"heads":["以掃求以撒祝福"]},{"n":31,"t":"也做了美味，拿來給他父親，說：「請父親起來，吃你兒子的野味，好給我祝福。」","notes":[]},{"n":32,"t":"他父親以撒對他說：「你是誰？」他說：「我是你的長子以掃。」","notes":[]},{"n":33,"t":"以撒就大大地戰兢，說：「你未來之先，是誰得了野味拿來給我呢？我已經吃了，為他祝福；他將來也必蒙福。」","notes":[]},{"n":34,"t":"以掃聽了他父親的話，就放聲痛哭，說：「我父啊，求你也為我祝福！」","notes":[]},{"n":35,"t":"以撒說：「你兄弟已經用詭計來將你的福分奪去了。」","notes":[]},{"n":36,"t":"以掃說：「他名雅各，豈不是正對嗎？因為他欺騙了我兩次：他從前奪了我長子的名分，你看，他現在又奪了我的福分。」以掃又說：「你沒有留下為我可祝的福嗎？」","notes":[]},{"n":37,"t":"以撒回答以掃說：「我已立他為你的主，使他的弟兄都給他作僕人，並賜他五穀新酒可以養生。我兒，現在我還能為你做甚麼呢？」","notes":[]},{"n":38,"t":"以掃對他父親說：「父啊，你只有一樣可祝的福嗎？我父啊，求你也為我祝福！」以掃就放聲而哭。","notes":[]},{"n":39,"t":"他父親以撒說：地上的肥土必為你所住；天上的甘露必為你所得。","notes":[]},{"n":40,"t":"你必倚靠刀劍度日，又必事奉你的兄弟；到你強盛的時候，必從你頸項上掙開他的軛。","notes":[]},{"n":41,"t":"以掃因他父親給雅各祝的福，就怨恨雅各，心裏說：「為我父親居喪的日子近了，到那時候，我要殺我的兄弟雅各。」","notes":[]},{"n":42,"t":"有人把利百加大兒子以掃的話告訴利百加，她就打發人去，叫了她小兒子雅各來，對他說：「你哥哥以掃想要殺你，報仇雪恨。","notes":[]},{"n":43,"t":"現在，我兒，你要聽我的話：起來，逃往哈蘭、我哥哥拉班那裏去，","notes":[]},{"n":44,"t":"同他住些日子，直等你哥哥的怒氣消了。","notes":[]},{"n":45,"t":"你哥哥向你消了怒氣，忘了你向他所做的事，我便打發人去把你從那裏帶回來。為甚麼一日喪你們二人呢？」","notes":[]},{"n":46,"t":"利百加對以撒說：「我因這赫人的女子連性命都厭煩了；倘若雅各也娶赫人的女子為妻，像這些一樣，我活著還有甚麼益處呢？」","notes":[],"heads":["以撒打發雅各到拉班的家去"]}]},"28":{"heading":"以掃另娶一妻","verses":[{"n":1,"t":"以撒叫了雅各來，給他祝福，並囑咐他說：「你不要娶迦南的女子為妻。","notes":[]},{"n":2,"t":"你起身往巴旦‧亞蘭去，到你外祖彼土利家裏，在你母舅拉班的女兒中娶一女為妻。","notes":[]},{"n":3,"t":"願全能的神賜福給你，使你生養眾多，成為多族，","notes":[]},{"n":4,"t":"將應許亞伯拉罕的福賜給你和你的後裔，使你承受你所寄居的地為業，就是神賜給亞伯拉罕的地。」","notes":[]},{"n":5,"t":"以撒打發雅各走了，他就往巴旦‧亞蘭去，到亞蘭人彼土利的兒子拉班那裏。拉班是雅各、以掃的母舅。","notes":[]},{"n":6,"t":"以掃見以撒已經給雅各祝福，而且打發他往巴旦‧亞蘭去，在那裏娶妻，並見祝福的時候囑咐他說：「不要娶迦南的女子為妻」，","notes":[]},{"n":7,"t":"又見雅各聽從父母的話往巴旦‧亞蘭去了，","notes":[]},{"n":8,"t":"以掃就曉得他父親以撒看不中迦南的女子，","notes":[]},{"n":9,"t":"便往以實瑪利那裏去，在他二妻之外又娶了瑪哈拉為妻。她是亞伯拉罕兒子以實瑪利的女兒，尼拜約的妹子。","notes":[]},{"n":10,"t":"雅各出了別是巴，向哈蘭走去；","notes":[],"heads":["雅各在伯特利做的夢"]},{"n":11,"t":"到了一個地方，因為太陽落了，就在那裏住宿，便拾起那地方的一塊石頭枕在頭下，在那裏躺臥睡了，","notes":[]},{"n":12,"t":"夢見一個梯子立在地上，梯子的頭頂著天，有神的使者在梯子上，上去下來。","notes":[]},{"n":13,"t":"耶和華站在梯子以上，說：「我是耶和華－你祖亞伯拉罕的神，也是以撒的神；我要將你現在所躺臥之地賜給你和你的後裔。","notes":["或譯：站在他旁邊"]},{"n":14,"t":"你的後裔必像地上的塵沙那樣多，必向東西南北開展；地上萬族必因你和你的後裔得福。","notes":[]},{"n":15,"t":"我也與你同在。你無論往哪裏去，我必保佑你，領你歸回這地，總不離棄你，直到我成全了向你所應許的。」","notes":[]},{"n":16,"t":"雅各睡醒了，說：「耶和華真在這裏，我竟不知道！」","notes":[]},{"n":17,"t":"就懼怕，說：「這地方何等可畏！這不是別的，乃是神的殿，也是天的門。」","notes":[]},{"n":18,"t":"雅各清早起來，把所枕的石頭立作柱子，澆油在上面。","notes":[]},{"n":19,"t":"他就給那地方起名叫伯特利；但那地方起先名叫路斯。","notes":["就是神殿的意思"]},{"n":20,"t":"雅各許願說：「神若與我同在，在我所行的路上保佑我，又給我食物吃，衣服穿，","notes":[]},{"n":21,"t":"使我平平安安地回到我父親的家，我就必以耶和華為我的神。","notes":[]},{"n":22,"t":"我所立為柱子的石頭也必作神的殿；凡你所賜給我的，我必將十分之一獻給你。」","notes":[]}]},"29":{"heading":"雅各到了拉班的家","verses":[{"n":1,"t":"雅各起行，到了東方人之地，","notes":[]},{"n":2,"t":"看見田間有一口井，有三群羊臥在井旁；因為人飲羊群都是用那井裏的水。井口上的石頭是大的。","notes":[]},{"n":3,"t":"常有羊群在那裏聚集，牧人把石頭轉離井口飲羊，隨後又把石頭放在井口的原處。","notes":[]},{"n":4,"t":"雅各對牧人說：「弟兄們，你們是哪裏來的？」他們說：「我們是哈蘭來的。」","notes":[]},{"n":5,"t":"他問他們說：「拿鶴的孫子拉班，你們認識嗎？」他們說：「我們認識。」","notes":[]},{"n":6,"t":"雅各說：「他平安嗎？」他們說：「平安。看哪，他女兒拉結領著羊來了。」","notes":[]},{"n":7,"t":"雅各說：「日頭還高，不是羊群聚集的時候，你們不如飲羊，再去放一放。」","notes":[]},{"n":8,"t":"他們說：「我們不能，必等羊群聚齊，人把石頭轉離井口才可飲羊。」","notes":[]},{"n":9,"t":"雅各正和他們說話的時候，拉結領著她父親的羊來了，因為那些羊是她牧放的。","notes":[]},{"n":10,"t":"雅各看見母舅拉班的女兒拉結和母舅拉班的羊群，就上前把石頭轉離井口，飲他母舅拉班的羊群。","notes":[]},{"n":11,"t":"雅各與拉結親嘴，就放聲而哭。","notes":[]},{"n":12,"t":"雅各告訴拉結，自己是她父親的外甥，是利百加的兒子，拉結就跑去告訴她父親。","notes":[]},{"n":13,"t":"拉班聽見外甥雅各的信息，就跑去迎接，抱著他，與他親嘴，領他到自己的家。雅各將一切的情由告訴拉班。","notes":[]},{"n":14,"t":"拉班對他說：「你實在是我的骨肉。」雅各就和他同住了一個月。","notes":[]},{"n":15,"t":"拉班對雅各說：「你雖是我的骨肉，豈可白白地服事我？請告訴我，你要甚麼為工價？」","notes":["原文是弟兄"],"heads":["雅各為拉結和利亞服事拉班"]},{"n":16,"t":"拉班有兩個女兒，大的名叫利亞，小的名叫拉結。","notes":[]},{"n":17,"t":"利亞的眼睛沒有神氣，拉結卻生得美貌俊秀。","notes":[]},{"n":18,"t":"雅各愛拉結，就說：「我願為你小女兒拉結服事你七年。」","notes":[]},{"n":19,"t":"拉班說：「我把她給你，勝似給別人，你與我同住吧！」","notes":[]},{"n":20,"t":"雅各就為拉結服事了七年；他因為深愛拉結，就看這七年如同幾天。","notes":[]},{"n":21,"t":"雅各對拉班說：「日期已經滿了，求你把我的妻子給我，我好與她同房。」","notes":[]},{"n":22,"t":"拉班就擺設筵席，請齊了那地方的眾人。","notes":[]},{"n":23,"t":"到晚上，拉班將女兒利亞送來給雅各，雅各就與她同房。","notes":[]},{"n":24,"t":"拉班又將婢女悉帕給女兒利亞作使女。","notes":[]},{"n":25,"t":"到了早晨，雅各一看是利亞，就對拉班說：「你向我做的是甚麼事呢？我服事你，不是為拉結嗎？你為甚麼欺哄我呢？」","notes":[]},{"n":26,"t":"拉班說：「大女兒還沒有給人，先把小女兒給人，在我們這地方沒有這規矩。","notes":[]},{"n":27,"t":"你為這個滿了七日，我就把那個也給你，你再為她服事我七年。」","notes":[]},{"n":28,"t":"雅各就如此行。滿了利亞的七日，拉班便將女兒拉結給雅各為妻。","notes":[]},{"n":29,"t":"拉班又將婢女辟拉給女兒拉結作使女。","notes":[]},{"n":30,"t":"雅各也與拉結同房，並且愛拉結勝似愛利亞，於是又服事了拉班七年。","notes":[]},{"n":31,"t":"耶和華見利亞失寵，就使她生育，拉結卻不生育。","notes":["原文是被恨；下同"],"heads":["雅各的兒女"]},{"n":32,"t":"利亞懷孕生子，就給他起名叫呂便，因而說：「耶和華看見我的苦情，如今我的丈夫必愛我。」","notes":["就是有兒子的意思"]},{"n":33,"t":"她又懷孕生子，就說：「耶和華因為聽見我失寵，所以又賜給我這個兒子」，於是給他起名叫西緬。","notes":["就是聽見的意思"]},{"n":34,"t":"她又懷孕生子，起名叫利未，說：「我給丈夫生了三個兒子，他必與我聯合。」","notes":["就是聯合的意思"]},{"n":35,"t":"她又懷孕生子，說：「這回我要讚美耶和華」，因此給他起名叫猶大。這才停了生育。","notes":["就是讚美的意思"]}]},"30":{"heading":"雅各和拉班定工價","verses":[{"n":1,"t":"拉結見自己不給雅各生子，就嫉妒她姊姊，對雅各說：「你給我孩子，不然我就死了。」","notes":[]},{"n":2,"t":"雅各向拉結生氣，說：「叫你不生育的是神，我豈能代替他作主呢？」","notes":[]},{"n":3,"t":"拉結說：「有我的使女辟拉在這裏，你可以與她同房，使她生子在我膝下，我便因她也得孩子。」","notes":["原文是被建立"]},{"n":4,"t":"拉結就把她的使女辟拉給丈夫為妾；雅各便與她同房，","notes":[]},{"n":5,"t":"辟拉就懷孕，給雅各生了一個兒子。","notes":[]},{"n":6,"t":"拉結說：「神伸了我的冤，也聽了我的聲音，賜我一個兒子」，因此給他起名叫但。","notes":["就是伸冤的意思"]},{"n":7,"t":"拉結的使女辟拉又懷孕，給雅各生了第二個兒子。","notes":[]},{"n":8,"t":"拉結說：「我與我姊姊大大相爭，並且得勝」，於是給他起名叫拿弗他利。","notes":["就是相爭的意思"]},{"n":9,"t":"利亞見自己停了生育，就把使女悉帕給雅各為妾。","notes":[]},{"n":10,"t":"利亞的使女悉帕給雅各生了一個兒子。","notes":[]},{"n":11,"t":"利亞說：「萬幸！」於是給他起名叫迦得 。","notes":["就是萬幸的意思"]},{"n":12,"t":"利亞的使女悉帕又給雅各生了第二個兒子。","notes":[]},{"n":13,"t":"利亞說：「我有福啊，眾女子都要稱我是有福的」，於是給他起名叫亞設。","notes":["就是有福的意思"]},{"n":14,"t":"割麥子的時候，呂便往田裏去，尋見風茄，拿來給他母親利亞。拉結對利亞說：「請你把你兒子的風茄給我些。」","notes":[]},{"n":15,"t":"利亞說：「你奪了我的丈夫還算小事嗎？你又要奪我兒子的風茄嗎？」拉結說：「為你兒子的風茄，今夜他可以與你同寢。」","notes":[]},{"n":16,"t":"到了晚上，雅各從田裏回來，利亞出來迎接他，說：「你要與我同寢，因為我實在用我兒子的風茄把你雇下了。」那一夜，雅各就與她同寢。","notes":[]},{"n":17,"t":"神應允了利亞，她就懷孕，給雅各生了第五個兒子。","notes":[]},{"n":18,"t":"利亞說：「神給了我價值，因為我把使女給了我丈夫」，於是給他起名叫以薩迦。","notes":["就是價值的意思"]},{"n":19,"t":"利亞又懷孕，給雅各生了第六個兒子。","notes":[]},{"n":20,"t":"利亞說：「神賜我厚賞；我丈夫必與我同住，因我給他生了六個兒子」，於是給他起名西布倫。","notes":["就是同住的意思"]},{"n":21,"t":"後來又生了一個女兒，給她起名叫底拿。","notes":[]},{"n":22,"t":"神顧念拉結，應允了她，使她能生育。","notes":[]},{"n":23,"t":"拉結懷孕生子，說：「神除去了我的羞恥」，","notes":[]},{"n":24,"t":"就給他起名叫約瑟，意思說：「願耶和華再增添我一個兒子。」","notes":["就是增添的意思"]},{"n":25,"t":"拉結生約瑟之後，雅各對拉班說：「請打發我走，叫我回到我本鄉本土去。","notes":[]},{"n":26,"t":"請你把我服事你所得的妻子和兒女給我，讓我走；我怎樣服事你，你都知道。」","notes":[]},{"n":27,"t":"拉班對他說：「我若在你眼前蒙恩，請你仍與我同住，因為我已算定，耶和華賜福與我是為你的緣故」；","notes":[]},{"n":28,"t":"又說：「請你定你的工價，我就給你。」","notes":[]},{"n":29,"t":"雅各對他說：「我怎樣服事你，你的牲畜在我手裏怎樣，是你知道的。","notes":[]},{"n":30,"t":"我未來之先，你所有的很少，現今卻發大眾多，耶和華隨我的腳步賜福與你。如今，我甚麼時候才為自己興家立業呢？」","notes":[]},{"n":31,"t":"拉班說：「我當給你甚麼呢？」雅各說：「甚麼你也不必給我，只有一件事，你若應承，我便仍舊牧放你的羊群。","notes":[]},{"n":32,"t":"今天我要走遍你的羊群，把綿羊中凡有點的、有斑的，和黑色的，並山羊中凡有斑的、有點的，都挑出來；將來這一等的就算我的工價。","notes":[]},{"n":33,"t":"以後你來查看我的工價，凡在我手裏的山羊不是有點有斑的，綿羊不是黑色的，那就算是我偷的；這樣便可證出我的公義來。」","notes":[]},{"n":34,"t":"拉班說：「好啊！我情願照著你的話行。」","notes":[]},{"n":35,"t":"當日，拉班把有紋的、有斑的公山羊，有點的、有斑的、有雜白紋的母山羊，並黑色的綿羊，都挑出來，交在他兒子們的手下，","notes":[]},{"n":36,"t":"又使自己和雅各相離三天的路程。雅各就牧養拉班其餘的羊。","notes":[]},{"n":37,"t":"雅各拿楊樹、杏樹、楓樹的嫩枝，將皮剝成白紋，使枝子露出白的來，","notes":[]},{"n":38,"t":"將剝了皮的枝子，對著羊群，插在飲羊的水溝裏和水槽裏，羊來喝的時候，牝牡配合。","notes":[]},{"n":39,"t":"羊對著枝子配合，就生下有紋的、有點的、有斑的來。","notes":[]},{"n":40,"t":"雅各把羊羔分出來，使拉班的羊與這有紋和黑色的羊相對，把自己的羊另放一處，不叫他和拉班的羊混雜。","notes":[]},{"n":41,"t":"到羊群肥壯配合的時候，雅各就把枝子插在水溝裏，使羊對著枝子配合。","notes":[]},{"n":42,"t":"只是到羊瘦弱配合的時候就不插枝子。這樣，瘦弱的就歸拉班，肥壯的就歸雅各。","notes":[]},{"n":43,"t":"於是雅各極其發大，得了許多的羊群、僕婢、駱駝，和驢。","notes":[]}]},"31":{"heading":"雅各逃離拉班","verses":[{"n":1,"t":"雅各聽見拉班的兒子們有話說：「雅各把我們父親所有的都奪了去，並藉著我們父親的，得了這一切的榮耀。」","notes":["或譯：財"]},{"n":2,"t":"雅各見拉班的氣色向他不如從前了。","notes":[]},{"n":3,"t":"耶和華對雅各說：「你要回你祖、你父之地，到你親族那裏去，我必與你同在。」","notes":[]},{"n":4,"t":"雅各就打發人，叫拉結和利亞到田野羊群那裏來，","notes":[]},{"n":5,"t":"對她們說：「我看你們父親的氣色向我不如從前了；但我父親的神向來與我同在。","notes":[]},{"n":6,"t":"你們也知道，我盡了我的力量服事你們的父親。","notes":[]},{"n":7,"t":"你們的父親欺哄我，十次改了我的工價；然而神不容他害我。","notes":[]},{"n":8,"t":"他若說：『有點的歸你作工價』，羊群所生的都有點；他若說：『有紋的歸你作工價』，羊群所生的都有紋。","notes":[]},{"n":9,"t":"這樣，神把你們父親的牲畜奪來賜給我了。","notes":[]},{"n":10,"t":"羊配合的時候，我夢中舉目一看，見跳母羊的公羊都是有紋的、有點的、有花斑的。","notes":[]},{"n":11,"t":"神的使者在那夢中呼叫我說：『雅各。』我說：『我在這裏。』","notes":[]},{"n":12,"t":"他說：『你舉目觀看，跳母羊的公羊都是有紋的、有點的、有花斑的；凡拉班向你所做的，我都看見了。","notes":[]},{"n":13,"t":"我是伯特利的神；你在那裏用油澆過柱子，向我許過願。現今你起來，離開這地，回你本地去吧！』」","notes":[]},{"n":14,"t":"拉結和利亞回答雅各說：「在我們父親的家裏還有我們可得的分嗎？還有我們的產業嗎？","notes":[]},{"n":15,"t":"我們不是被他當作外人嗎？因為他賣了我們，吞了我們的價值。","notes":[]},{"n":16,"t":"神從我們父親所奪出來的一切財物，那就是我們和我們孩子們的。現今凡神所吩咐你的，你只管去行吧！」","notes":[]},{"n":17,"t":"雅各起來，使他的兒子和妻子都騎上駱駝，","notes":[]},{"n":18,"t":"又帶著他在巴旦‧亞蘭所得的一切牲畜和財物，往迦南地、他父親以撒那裏去了。","notes":[]},{"n":19,"t":"當時拉班剪羊毛去了，拉結偷了他父親家中的神像。","notes":[]},{"n":20,"t":"雅各背著亞蘭人拉班偷走了，並不告訴他，","notes":[]},{"n":21,"t":"就帶著所有的逃跑。他起身過大河，面向基列山行去。","notes":[]},{"n":22,"t":"到第三日，有人告訴拉班，雅各逃跑了。","notes":[],"heads":["拉班追趕雅各"]},{"n":23,"t":"拉班帶領他的眾弟兄去追趕，追了七日，在基列山就追上了。","notes":[]},{"n":24,"t":"夜間，神到亞蘭人拉班那裏，在夢中對他說：「你要小心，不可與雅各說好說歹。」","notes":[]},{"n":25,"t":"拉班追上雅各。雅各在山上支搭帳棚；拉班和他的眾弟兄也在基列山上支搭帳棚。","notes":[]},{"n":26,"t":"拉班對雅各說：「你做的是甚麼事呢？你背著我偷走了，又把我的女兒們帶了去，如同用刀劍擄去的一般。","notes":[]},{"n":27,"t":"你為甚麼暗暗地逃跑，偷著走，並不告訴我，叫我可以歡樂、唱歌、擊鼓、彈琴地送你回去？","notes":[]},{"n":28,"t":"又不容我與外孫和女兒親嘴？你所行的真是愚昧！","notes":[]},{"n":29,"t":"我手中原有能力害你，只是你父親的神昨夜對我說：『你要小心，不可與雅各說好說歹。』","notes":[]},{"n":30,"t":"現在你雖然想你父家，不得不去，為甚麼又偷了我的神像呢？」","notes":[]},{"n":31,"t":"雅各回答拉班說：「恐怕你把你的女兒從我奪去，所以我逃跑。","notes":[]},{"n":32,"t":"至於你的神像，你在誰那裏搜出來，就不容誰存活。當著我們的眾弟兄，你認一認，在我這裏有甚麼東西是你的，就拿去。」原來雅各不知道拉結偷了那些神像。","notes":[]},{"n":33,"t":"拉班進了雅各、利亞，並兩個使女的帳棚，都沒有搜出來，就從利亞的帳棚出來，進了拉結的帳棚。","notes":[]},{"n":34,"t":"拉結已經把神像藏在駱駝的馱簍裏，便坐在上頭。拉班摸遍了那帳棚，並沒有摸著。","notes":[]},{"n":35,"t":"拉結對她父親說：「現在我身上不便，不能在你面前起來，求我主不要生氣。」這樣，拉班搜尋神像，竟沒有搜出來。","notes":[]},{"n":36,"t":"雅各就發怒斥責拉班說：「我有甚麼過犯，有甚麼罪惡，你竟這樣火速地追我？","notes":[]},{"n":37,"t":"你摸遍了我一切的家具，你搜出甚麼來呢？可以放在你我弟兄面前，叫他們在你我中間辨別辨別。","notes":[]},{"n":38,"t":"我在你家這二十年，你的母綿羊、母山羊沒有掉過胎。你群中的公羊，我沒有吃過；","notes":[]},{"n":39,"t":"被野獸撕裂的，我沒有帶來給你，是我自己賠上。無論是白日，是黑夜，被偷去的，你都向我索要。","notes":[]},{"n":40,"t":"我白日受盡乾熱，黑夜受盡寒霜，不得合眼睡著，我常是這樣。","notes":[]},{"n":41,"t":"我這二十年在你家裏，為你的兩個女兒服事你十四年，為你的羊群服事你六年，你又十次改了我的工價。","notes":[]},{"n":42,"t":"若不是我父親以撒所敬畏的神，就是亞伯拉罕的神與我同在，你如今必定打發我空手而去。神看見我的苦情和我的勞碌，就在昨夜責備你。」","notes":[]},{"n":43,"t":"拉班回答雅各說：「這女兒是我的女兒，這些孩子是我的孩子，這些羊群也是我的羊群；凡在你眼前的都是我的。我的女兒並她們所生的孩子，我今日能向他們做甚麼呢？","notes":[],"heads":["雅各和拉班立約"]},{"n":44,"t":"來吧！你我二人可以立約，作你我中間的證據。」","notes":[]},{"n":45,"t":"雅各就拿一塊石頭立作柱子，","notes":[]},{"n":46,"t":"又對眾弟兄說：「你們堆聚石頭。」他們就拿石頭來堆成一堆，大家便在旁邊吃喝。","notes":[]},{"n":47,"t":"拉班稱那石堆為伊迦爾‧撒哈杜他，雅各卻稱那石堆為迦累得。","notes":["都是以石堆為證的意思"]},{"n":48,"t":"拉班說：「今日這石堆作你我中間的證據。」因此這地方名叫迦累得，","notes":[]},{"n":49,"t":"又叫米斯巴，意思說：「我們彼此離別以後，願耶和華在你我中間鑒察。","notes":[]},{"n":50,"t":"你若苦待我的女兒，又在我的女兒以外另娶妻，雖沒有人知道，卻有神在你我中間作見證。」","notes":[]},{"n":51,"t":"拉班又說：「你看我在你我中間所立的這石堆和柱子。","notes":[]},{"n":52,"t":"這石堆作證據，這柱子也作證據。我必不過這石堆去害你；你也不可過這石堆和柱子來害我。","notes":[]},{"n":53,"t":"但願亞伯拉罕的神和拿鶴的神，就是他們父親的神，在你我中間判斷。」雅各就指著他父親以撒所敬畏的神起誓，","notes":[]},{"n":54,"t":"又在山上獻祭，請眾弟兄來吃飯。他們吃了飯，便在山上住宿。","notes":[]},{"n":55,"t":"拉班清早起來，與他外孫和女兒親嘴，給他們祝福，回往自己的地方去了。","notes":[]}]},"32":{"heading":"雅各準備迎見以掃","verses":[{"n":1,"t":"雅各仍舊行路，神的使者遇見他。","notes":[]},{"n":2,"t":"雅各看見他們就說：「這是神的軍兵」，於是給那地方起名叫瑪哈念。","notes":["就是二軍兵的意思"]},{"n":3,"t":"雅各打發人先往西珥地去，就是以東地，見他哥哥以掃，","notes":[]},{"n":4,"t":"吩咐他們說：「你們對我主以掃說：『你的僕人雅各這樣說：我在拉班那裏寄居，直到如今。","notes":[]},{"n":5,"t":"我有牛、驢、羊群、僕婢，現在打發人來報告我主，為要在你眼前蒙恩。』」","notes":[]},{"n":6,"t":"所打發的人回到雅各那裏，說：「我們到了你哥哥以掃那裏，他帶著四百人，正迎著你來。」","notes":[]},{"n":7,"t":"雅各就甚懼怕，而且愁煩，便把那與他同在的人口和羊群、牛群、駱駝分做兩隊，","notes":[]},{"n":8,"t":"說：「以掃若來擊殺這一隊，剩下的那一隊還可以逃避。」","notes":[]},{"n":9,"t":"雅各說：「耶和華－我祖亞伯拉罕的神，我父親以撒的神啊，你曾對我說：『回你本地本族去，我要厚待你。』","notes":[]},{"n":10,"t":"你向僕人所施的一切慈愛和誠實，我一點也不配得；我先前只拿著我的杖過這約旦河，如今我卻成了兩隊了。","notes":[]},{"n":11,"t":"求你救我脫離我哥哥以掃的手；因為我怕他來殺我，連妻子帶兒女一同殺了。","notes":[]},{"n":12,"t":"你曾說：『我必定厚待你，使你的後裔如同海邊的沙，多得不可勝數。』」","notes":[]},{"n":13,"t":"當夜，雅各在那裏住宿，就從他所有的物中拿禮物要送給他哥哥以掃：","notes":[]},{"n":14,"t":"母山羊二百隻，公山羊二十隻，母綿羊二百隻，公綿羊二十隻，","notes":[]},{"n":15,"t":"奶崽子的駱駝三十隻－各帶著崽子，母牛四十隻，公牛十隻，母驢二十匹，驢駒十匹；","notes":[]},{"n":16,"t":"每樣各分一群，交在僕人手下，就對僕人說：「你們要在我前頭過去，使群群相離，有空閒的地方」；","notes":[]},{"n":17,"t":"又吩咐儘先走的說：「我哥哥以掃遇見你的時候，問你說：『你是哪家的人？要往哪裏去？你前頭這些是誰的？』","notes":[]},{"n":18,"t":"你就說：『是你僕人雅各的，是送給我主以掃的禮物；他自己也在我們後邊。』」","notes":[]},{"n":19,"t":"又吩咐第二、第三，和一切趕群畜的人說：「你們遇見以掃的時候也要這樣對他說；","notes":[]},{"n":20,"t":"並且你們要說：『你僕人雅各在我們後邊。』」因雅各心裏說：「我藉著在我前頭去的禮物解他的恨，然後再見他的面，或者他容納我。」","notes":[]},{"n":21,"t":"於是禮物先過去了；那夜，雅各在隊中住宿。","notes":[]},{"n":22,"t":"他夜間起來，帶著兩個妻子，兩個使女，並十一個兒子，都過了雅博渡口，","notes":[],"heads":["雅各在毗努伊勒摔跤"]},{"n":23,"t":"先打發他們過河，又打發所有的都過去，","notes":[]},{"n":24,"t":"只剩下雅各一人。有一個人來和他摔跤，直到黎明。","notes":[]},{"n":25,"t":"那人見自己勝不過他，就將他的大腿窩摸了一把，雅各的大腿窩正在摔跤的時候就扭了。","notes":[]},{"n":26,"t":"那人說：「天黎明了，容我去吧！」雅各說：「你不給我祝福，我就不容你去。」","notes":[]},{"n":27,"t":"那人說：「你名叫甚麼？」他說：「我名叫雅各。」","notes":[]},{"n":28,"t":"那人說：「你的名不要再叫雅各，要叫以色列；因為你與神與人較力，都得了勝。」","notes":[]},{"n":29,"t":"雅各問他說：「請將你的名告訴我。」那人說：「何必問我的名？」於是在那裏給雅各祝福。","notes":[]},{"n":30,"t":"雅各便給那地方起名叫毗努伊勒，意思說：「我面對面見了神，我的性命仍得保全。」","notes":["就是神之面的意思"]},{"n":31,"t":"日頭剛出來的時候，雅各經過毗努伊勒，他的大腿就瘸了。","notes":[]},{"n":32,"t":"故此，以色列人不吃大腿窩的筋，直到今日，因為那人摸了雅各大腿窩的筋。","notes":[]}]},"33":{"heading":"雅各和以掃相見","verses":[{"n":1,"t":"雅各舉目觀看，見以掃來了，後頭跟著四百人，他就把孩子們分開交給利亞、拉結，和兩個使女，","notes":[]},{"n":2,"t":"並且叫兩個使女和她們的孩子在前頭，利亞和她的孩子在後頭，拉結和約瑟在儘後頭。","notes":[]},{"n":3,"t":"他自己在他們前頭過去，一連七次俯伏在地才就近他哥哥。","notes":[]},{"n":4,"t":"以掃跑來迎接他，將他抱住，又摟著他的頸項，與他親嘴，兩個人就哭了。","notes":[]},{"n":5,"t":"以掃舉目看見婦人孩子，就說：「這些和你同行的是誰呢？」雅各說：「這些孩子是神施恩給你的僕人的。」","notes":[]},{"n":6,"t":"於是兩個使女和她們的孩子前來下拜；","notes":[]},{"n":7,"t":"利亞和她的孩子也前來下拜；隨後約瑟和拉結也前來下拜。","notes":[]},{"n":8,"t":"以掃說：「我所遇見的這些群畜是甚麼意思呢？」雅各說：「是要在我主面前蒙恩的。」","notes":[]},{"n":9,"t":"以掃說：「兄弟啊，我的已經夠了，你的仍歸你吧！」","notes":[]},{"n":10,"t":"雅各說：「不然，我若在你眼前蒙恩，就求你從我手裏收下這禮物；因為我見了你的面，如同見了神的面，並且你容納了我。","notes":[]},{"n":11,"t":"求你收下我帶來給你的禮物；因為神恩待我，使我充足。」雅各再三地求他，他才收下了。","notes":[]},{"n":12,"t":"以掃說：「我們可以起身前往，我在你前頭走。」","notes":[]},{"n":13,"t":"雅各對他說：「我主知道孩子們年幼嬌嫩，牛羊也正在乳養的時候，若是催趕一天，群畜都必死了。","notes":[]},{"n":14,"t":"求我主在僕人前頭走，我要量著在我面前群畜和孩子的力量慢慢地前行，直走到西珥我主那裏。」","notes":[]},{"n":15,"t":"以掃說：「容我把跟隨我的人留幾個在你這裏。」雅各說：「何必呢？只要在我主眼前蒙恩就是了。」","notes":[]},{"n":16,"t":"於是，以掃當日起行，回往西珥去了。","notes":[]},{"n":17,"t":"雅各就往疏割去，在那裏為自己蓋造房屋，又為牲畜搭棚；因此那地方名叫疏割。","notes":["就是棚的意思"]},{"n":18,"t":"雅各從巴旦‧亞蘭回來的時候，平平安安地到了迦南地的示劍城，在城東支搭帳棚，","notes":[]},{"n":19,"t":"就用一百塊銀子向示劍的父親、哈抹的子孫買了支帳棚的那塊地，","notes":[]},{"n":20,"t":"在那裏築了一座壇，起名叫伊利‧伊羅伊‧以色列 。","notes":["就是神、以色列神的意思"]}]},"34":{"heading":"底拿受辱","verses":[{"n":1,"t":"利亞給雅各所生的女兒底拿出去，要見那地的女子們。","notes":[]},{"n":2,"t":"那地的主－希未人、哈抹的兒子示劍看見她，就拉住她，與她行淫，玷辱她。","notes":[]},{"n":3,"t":"示劍的心繫戀雅各的女兒底拿，喜愛這女子，甜言蜜語地安慰她。","notes":[]},{"n":4,"t":"示劍對他父親哈抹說：「求你為我聘這女子為妻。」","notes":[]},{"n":5,"t":"雅各聽見示劍玷污了他的女兒底拿。那時他的兒子們正和群畜在田野，雅各就閉口不言，等他們回來。","notes":[]},{"n":6,"t":"示劍的父親哈抹出來見雅各，要和他商議。","notes":[]},{"n":7,"t":"雅各的兒子們聽見這事，就從田野回來，人人忿恨，十分惱怒；因示劍在以色列家做了醜事，與雅各的女兒行淫，這本是不該做的事。","notes":[]},{"n":8,"t":"哈抹和他們商議說：「我兒子示劍的心戀慕這女子，求你們將她給我的兒子為妻。","notes":[]},{"n":9,"t":"你們與我們彼此結親；你們可以把女兒給我們，也可以娶我們的女兒。","notes":[]},{"n":10,"t":"你們與我們同住吧！這地都在你們面前，只管在此居住，做買賣，置產業。」","notes":[]},{"n":11,"t":"示劍對女兒的父親和弟兄們說：「但願我在你們眼前蒙恩，你們向我要甚麼，我必給你們。","notes":[]},{"n":12,"t":"任憑向我要多重的聘金和禮物，我必照你們所說的給你們；只要把女子給我為妻。」","notes":[]},{"n":13,"t":"雅各的兒子們因為示劍玷污了他們的妹子底拿，就用詭詐的話回答示劍和他父親哈抹，","notes":[]},{"n":14,"t":"對他們說：「我們不能把我們的妹子給沒有受割禮的人為妻，因為那是我們的羞辱。","notes":[]},{"n":15,"t":"惟有一件才可以應允：若你們所有的男丁都受割禮，和我們一樣，","notes":[]},{"n":16,"t":"我們就把女兒給你們，也娶你們的女兒；我們便與你們同住，兩下成為一樣的人民。","notes":[]},{"n":17,"t":"倘若你們不聽從我們受割禮，我們就帶著妹子走了。」","notes":[]},{"n":18,"t":"哈抹和他的兒子示劍喜歡這話。","notes":[]},{"n":19,"t":"那少年人做這事並不遲延，因為他喜愛雅各的女兒；他在他父親家中也是人最尊重的。","notes":[]},{"n":20,"t":"哈抹和他兒子示劍到本城的門口，對本城的人說：","notes":[]},{"n":21,"t":"「這些人與我們和睦，不如許他們在這地居住，做買賣；這地也寬闊，足可容下他們。我們可以娶他們的女兒為妻，也可以把我們的女兒嫁給他們。","notes":[]},{"n":22,"t":"惟有一件事我們必須做，他們才肯應允和我們同住，成為一樣的人民：就是我們中間所有的男丁都要受割禮，和他們一樣。","notes":[]},{"n":23,"t":"他們的群畜、貨財，和一切的牲口豈不都歸我們嗎？只要依從他們，他們就與我們同住。」","notes":[]},{"n":24,"t":"凡從城門出入的人就都聽從哈抹和他兒子示劍的話；於是凡從城門出入的男丁都受了割禮。","notes":[]},{"n":25,"t":"到第三天，眾人正在疼痛的時候，雅各的兩個兒子，就是底拿的哥哥西緬和利未，各拿刀劍，趁著眾人想不到的時候來到城中，把一切男丁都殺了，","notes":[]},{"n":26,"t":"又用刀殺了哈抹和他兒子示劍，把底拿從示劍家裏帶出來就走了。","notes":[]},{"n":27,"t":"雅各的兒子們因為他們的妹子受了玷污，就來到被殺的人那裏，擄掠那城，","notes":[]},{"n":28,"t":"奪了他們的羊群、牛群，和驢，並城裏田間所有的；","notes":[]},{"n":29,"t":"又把他們一切貨財、孩子、婦女，並各房中所有的，都擄掠去了。","notes":[]},{"n":30,"t":"雅各對西緬和利未說：「你們連累我，使我在這地的居民中，就是在迦南人和比利洗人中，有了臭名。我的人丁既然稀少，他們必聚集來擊殺我，我和全家的人都必滅絕。」","notes":[]},{"n":31,"t":"他們說：「他豈可待我們的妹子如同妓女嗎？」","notes":[]}]},"35":{"heading":"神在伯特利賜福雅各","verses":[{"n":1,"t":"神對雅各說：「起來！上伯特利去，住在那裏；要在那裏築一座壇給神，就是你逃避你哥哥以掃的時候向你顯現的那位。」","notes":[]},{"n":2,"t":"雅各就對他家中的人並一切與他同在的人說：「你們要除掉你們中間的外邦神，也要自潔，更換衣裳。","notes":[]},{"n":3,"t":"我們要起來，上伯特利去，在那裏我要築一座壇給神，就是在我遭難的日子應允我的禱告、在我行的路上保佑我的那位。」","notes":[]},{"n":4,"t":"他們就把外邦人的神像和他們耳朵上的環子交給雅各；雅各都藏在示劍那裏的橡樹底下。","notes":[]},{"n":5,"t":"他們便起行前往。神使那周圍城邑的人都甚驚懼，就不追趕雅各的眾子了。","notes":[]},{"n":6,"t":"於是雅各和一切與他同在的人到了迦南地的路斯，就是伯特利。","notes":[]},{"n":7,"t":"他在那裏築了一座壇，就給那地方起名叫伊勒‧伯特利；因為他逃避他哥哥的時候，神在那裏向他顯現。","notes":["就是伯特利之神的意思"]},{"n":8,"t":"利百加的奶母底波拉死了，就葬在伯特利下邊橡樹底下；那棵樹名叫亞倫‧巴古。","notes":[]},{"n":9,"t":"雅各從巴旦‧亞蘭回來，神又向他顯現，賜福與他，","notes":[]},{"n":10,"t":"且對他說：「你的名原是雅各，從今以後不要再叫雅各，要叫以色列。」這樣，他就改名叫以色列。","notes":[]},{"n":11,"t":"神又對他說：「我是全能的神；你要生養眾多，將來有一族和多國的民從你而生，又有君王從你而出。","notes":[]},{"n":12,"t":"我所賜給亞伯拉罕和以撒的地，我要賜給你與你的後裔。」","notes":[]},{"n":13,"t":"神就從那與雅各說話的地方升上去了。","notes":[]},{"n":14,"t":"雅各便在那裏立了一根石柱，在柱子上奠酒，澆油。","notes":[]},{"n":15,"t":"雅各就給那地方起名叫伯特利。","notes":[]},{"n":16,"t":"他們從伯特利起行，離以法他還有一段路程，拉結臨產甚是艱難。","notes":[],"heads":["拉結去世"]},{"n":17,"t":"正在艱難的時候，收生婆對她說：「不要怕，你又要得一個兒子了。」","notes":[]},{"n":18,"t":"她將近於死，靈魂要走的時候，就給她兒子起名叫便‧俄尼；他父親卻給他起名叫便雅憫。","notes":[]},{"n":19,"t":"拉結死了，葬在以法他的路旁；以法他就是伯利恆。","notes":[]},{"n":20,"t":"雅各在她的墳上立了一統碑，就是拉結的墓碑，到今日還在。","notes":[]},{"n":21,"t":"以色列起行前往，在以得臺那邊支搭帳棚。","notes":[]},{"n":22,"t":"以色列住在那地的時候，呂便去與他父親的妾辟拉同寢，以色列也聽見了。雅各共有十二個兒子。","notes":[],"heads":["雅各的兒子們"]},{"n":23,"t":"利亞所生的是雅各的長子呂便，還有西緬、利未、猶大、以薩迦、西布倫。","notes":[]},{"n":24,"t":"拉結所生的是約瑟、便雅憫。","notes":[]},{"n":25,"t":"拉結的使女辟拉所生的是但、拿弗他利。","notes":[]},{"n":26,"t":"利亞的使女悉帕所生的是迦得、亞設。這是雅各在巴旦‧亞蘭所生的兒子。","notes":[]},{"n":27,"t":"雅各來到他父親以撒那裏，到了基列‧亞巴的幔利，乃是亞伯拉罕和以撒寄居的地方；基列‧亞巴就是希伯崙。","notes":[],"heads":["以撒去世"]},{"n":28,"t":"以撒共活了一百八十歲。","notes":[]},{"n":29,"t":"以撒年紀老邁，日子滿足，氣絕而死，歸到他列祖那裏。他兩個兒子以掃、雅各把他埋葬了。","notes":["原文是本民"]}]},"36":{"heading":"以掃的子孫","verses":[{"n":1,"t":"以掃就是以東，他的後代記在下面。","notes":[]},{"n":2,"t":"以掃娶迦南的女子為妻，就是赫人以倫的女兒亞大和希未人祭便的孫女、亞拿的女兒阿何利巴瑪，","notes":[]},{"n":3,"t":"又娶了以實瑪利的女兒、尼拜約的妹子巴實抹。","notes":[]},{"n":4,"t":"亞大給以掃生了以利法；巴實抹生了流珥；","notes":[]},{"n":5,"t":"阿何利巴瑪生了耶烏施、雅蘭、可拉。這都是以掃的兒子，是在迦南地生的。","notes":[]},{"n":6,"t":"以掃帶著他的妻子、兒女，與家中一切的人口，並他的牛羊、牲畜，和一切貨財，就是他在迦南地所得的，往別處去，離了他兄弟雅各。","notes":[]},{"n":7,"t":"因為二人的財物群畜甚多，寄居的地方容不下他們，所以不能同居。","notes":[]},{"n":8,"t":"於是以掃住在西珥山裏；以掃就是以東。","notes":[]},{"n":9,"t":"以掃是西珥山裏以東人的始祖，他的後代記在下面。","notes":[]},{"n":10,"t":"以掃眾子的名字如下。以掃的妻子亞大生以利法；以掃的妻子巴實抹生流珥。","notes":[]},{"n":11,"t":"以利法的兒子是提幔、阿抹、洗玻、迦坦、基納斯。","notes":[]},{"n":12,"t":"亭納是以掃兒子以利法的妾；她給以利法生了亞瑪力。這是以掃的妻子亞大的子孫。","notes":[]},{"n":13,"t":"流珥的兒子是拿哈、謝拉、沙瑪、米撒。這是以掃妻子巴實抹的子孫。","notes":[]},{"n":14,"t":"以掃的妻子阿何利巴瑪是祭便的孫女，亞拿的女兒；她給以掃生了耶烏施、雅蘭、可拉。","notes":[]},{"n":15,"t":"以掃子孫中作族長的記在下面。以掃的長子以利法的子孫中，有提幔族長、阿抹族長、洗玻族長、基納斯族長、","notes":[]},{"n":16,"t":"可拉族長、迦坦族長、亞瑪力族長。這是在以東地從以利法所出的族長，都是亞大的子孫。","notes":[]},{"n":17,"t":"以掃的兒子流珥的子孫中，有拿哈族長、謝拉族長、沙瑪族長、米撒族長。這是在以東地從流珥所出的族長，都是以掃妻子巴實抹的子孫。","notes":[]},{"n":18,"t":"以掃的妻子阿何利巴瑪的子孫中，有耶烏施族長、雅蘭族長、可拉族長。這是從以掃妻子，亞拿的女兒，阿何利巴瑪子孫中所出的族長。","notes":[]},{"n":19,"t":"以上的族長都是以掃的子孫；以掃就是以東。","notes":[]},{"n":20,"t":"那地原有的居民－何利人西珥的子孫記在下面：就是羅坍、朔巴、祭便、亞拿、","notes":[],"heads":["西珥的子孫"]},{"n":21,"t":"底順、以察、底珊。這是從以東地的何利人西珥子孫中所出的族長。","notes":[]},{"n":22,"t":"羅坍的兒子是何利、希幔；羅坍的妹子是亭納。","notes":[]},{"n":23,"t":"朔巴的兒子是亞勒文、瑪拿轄、以巴錄、示玻、阿南。","notes":[]},{"n":24,"t":"祭便的兒子是亞雅、亞拿（當時在曠野放他父親祭便的驢，遇著溫泉的，就是這亞拿）。","notes":[]},{"n":25,"t":"亞拿的兒子是底順；亞拿的女兒是阿何利巴瑪。","notes":[]},{"n":26,"t":"底順的兒子是欣但、伊是班、益蘭、基蘭。","notes":[]},{"n":27,"t":"以察的兒子是辟罕、撒番、亞干。","notes":[]},{"n":28,"t":"底珊的兒子是烏斯、亞蘭。","notes":[]},{"n":29,"t":"從何利人所出的族長記在下面：就是羅坍族長、朔巴族長、祭便族長、亞拿族長、","notes":[]},{"n":30,"t":"底順族長、以察族長、底珊族長。這是從何利人所出的族長，都在西珥地，按著宗族作族長。","notes":[]},{"n":31,"t":"以色列人未有君王治理以先，在以東地作王的記在下面。","notes":[],"heads":["以東諸王"]},{"n":32,"t":"比珥的兒子比拉在以東作王，他的京城名叫亭哈巴。","notes":[]},{"n":33,"t":"比拉死了，波斯拉人謝拉的兒子約巴接續他作王。","notes":[]},{"n":34,"t":"約巴死了，提幔地的人戶珊接續他作王。","notes":[]},{"n":35,"t":"戶珊死了，比達的兒子哈達接續他作王；這哈達就是在摩押地殺敗米甸人的，他的京城名叫亞未得。","notes":[]},{"n":36,"t":"哈達死了，瑪士利加人桑拉接續他作王。","notes":[]},{"n":37,"t":"桑拉死了，大河邊的利河伯人掃羅接續他作王。","notes":[]},{"n":38,"t":"掃羅死了，亞革波的兒子巴勒‧哈南接續他作王。","notes":[]},{"n":39,"t":"亞革波的兒子巴勒‧哈南死了，哈達接續他作王，他的京城名叫巴烏；他的妻子名叫米希她別，是米‧薩合的孫女，瑪特列的女兒。","notes":[]},{"n":40,"t":"從以掃所出的族長，按著他們的宗族、住處、名字記在下面：就是亭納族長、亞勒瓦族長、耶帖族長、","notes":[]},{"n":41,"t":"阿何利巴瑪族長、以拉族長、比嫩族長、","notes":[]},{"n":42,"t":"基納斯族長、提幔族長、米比薩族長、","notes":[]},{"n":43,"t":"瑪基疊族長、以蘭族長。這是以東人在所得為業的地上，按著他們的住處。（所有的族長都是以東人的始祖以掃的後代。）","notes":[]}]},"37":{"heading":"約瑟和他的兄弟","verses":[{"n":1,"t":"雅各住在迦南地，就是他父親寄居的地。","notes":[]},{"n":2,"t":"雅各的記略如下。約瑟十七歲與他哥哥們一同牧羊。他是個童子，與他父親的妾辟拉、悉帕的兒子們常在一處。約瑟將他哥哥們的惡行報給他們的父親。","notes":[]},{"n":3,"t":"以色列原來愛約瑟過於愛他的眾子，因為約瑟是他年老生的；他給約瑟做了一件彩衣。","notes":[]},{"n":4,"t":"約瑟的哥哥們見父親愛約瑟過於愛他們，就恨約瑟，不與他說和睦的話。","notes":[]},{"n":5,"t":"約瑟做了一夢，告訴他哥哥們，他們就越發恨他。","notes":[]},{"n":6,"t":"約瑟對他們說：「請聽我所做的夢：","notes":[]},{"n":7,"t":"我們在田裏捆禾稼，我的捆起來站著，你們的捆來圍著我的捆下拜。」","notes":[]},{"n":8,"t":"他的哥哥們回答說：「難道你真要作我們的王嗎？難道你真要管轄我們嗎？」他們就因為他的夢和他的話越發恨他。","notes":[]},{"n":9,"t":"後來他又做了一夢，也告訴他的哥哥們說：「看哪，我又做了一夢，夢見太陽、月亮，與十一個星向我下拜。」","notes":[]},{"n":10,"t":"約瑟將這夢告訴他父親和他哥哥們，他父親就責備他說：「你做的這是甚麼夢！難道我和你母親、你弟兄果然要來俯伏在地，向你下拜嗎？」","notes":[]},{"n":11,"t":"他哥哥們都嫉妒他，他父親卻把這話存在心裏。","notes":[]},{"n":12,"t":"約瑟的哥哥們往示劍去放他們父親的羊。","notes":[],"heads":["約瑟被賣到埃及"]},{"n":13,"t":"以色列對約瑟說：「你哥哥們不是在示劍放羊嗎？你來，我要打發你往他們那裏去。」約瑟說：「我在這裏。」","notes":[]},{"n":14,"t":"以色列說：「你去看看你哥哥們平安不平安，群羊平安不平安，就回來報信給我」；於是打發他出希伯崙谷，他就往示劍去了。","notes":[]},{"n":15,"t":"有人遇見他在田野走迷了路，就問他說：「你找甚麼？」","notes":[]},{"n":16,"t":"他說：「我找我的哥哥們，求你告訴我，他們在何處放羊。」","notes":[]},{"n":17,"t":"那人說：「他們已經走了，我聽見他們說要往多坍去。」約瑟就去追趕他哥哥們，遇見他們在多坍。","notes":[]},{"n":18,"t":"他們遠遠地看見他，趁他還沒有走到跟前，大家就同謀要害死他，","notes":[]},{"n":19,"t":"彼此說：「你看！那做夢的來了。","notes":[]},{"n":20,"t":"來吧！我們將他殺了，丟在一個坑裏，就說有惡獸把他吃了。我們且看他的夢將來怎麼樣。」","notes":[]},{"n":21,"t":"呂便聽見了，要救他脫離他們的手，說：「我們不可害他的性命」；","notes":[]},{"n":22,"t":"又說：「不可流他的血，可以把他丟在這野地的坑裏，不可下手害他。」呂便的意思是要救他脫離他們的手，把他歸還他的父親。","notes":[]},{"n":23,"t":"約瑟到了他哥哥們那裏，他們就剝了他的外衣，就是他穿的那件彩衣，","notes":[]},{"n":24,"t":"把他丟在坑裏；那坑是空的，裏頭沒有水。","notes":[]},{"n":25,"t":"他們坐下吃飯，舉目觀看，見有一夥米甸的以實瑪利人從基列來，用駱駝馱著香料、乳香、沒藥，要帶下埃及去。","notes":[]},{"n":26,"t":"猶大對眾弟兄說：「我們殺我們的兄弟，藏了他的血有甚麼益處呢？","notes":[]},{"n":27,"t":"我們不如將他賣給以實瑪利人，不可下手害他；因為他是我們的兄弟，我們的骨肉。」眾弟兄就聽從了他。","notes":[]},{"n":28,"t":"有些米甸的商人從那裏經過，哥哥們就把約瑟從坑裏拉上來，講定二十舍客勒銀子，把約瑟賣給以實瑪利人。他們就把約瑟帶到埃及去了。","notes":[]},{"n":29,"t":"呂便回到坑邊，見約瑟不在坑裏，就撕裂衣服，","notes":[]},{"n":30,"t":"回到兄弟們那裏，說：「童子沒有了。我往哪裏去才好呢？」","notes":[]},{"n":31,"t":"他們宰了一隻公山羊，把約瑟的那件彩衣染了血，","notes":[]},{"n":32,"t":"打發人送到他們的父親那裏，說：「我們撿了這個；請認一認是你兒子的外衣不是？」","notes":[]},{"n":33,"t":"他認得，就說：「這是我兒子的外衣。有惡獸把他吃了，約瑟被撕碎了！撕碎了！」","notes":[]},{"n":34,"t":"雅各便撕裂衣服，腰間圍上麻布，為他兒子悲哀了多日。","notes":[]},{"n":35,"t":"他的兒女都起來安慰他，他卻不肯受安慰，說：「我必悲哀著下陰間，到我兒子那裏。」約瑟的父親就為他哀哭。","notes":[]},{"n":36,"t":"米甸人帶約瑟到埃及，把他賣給法老的內臣－護衛長波提乏。","notes":[]}]},"38":{"heading":"猶大和她瑪","verses":[{"n":1,"t":"那時，猶大離開他弟兄下去，到一個亞杜蘭人名叫希拉的家裏去。","notes":[]},{"n":2,"t":"猶大在那裏看見一個迦南人名叫書亞的女兒，就娶她為妻，與她同房，","notes":[]},{"n":3,"t":"她就懷孕生了兒子，猶大給他起名叫珥。","notes":[]},{"n":4,"t":"她又懷孕生了兒子，母親給他起名叫俄南。","notes":[]},{"n":5,"t":"她復又生了兒子，給他起名叫示拉。她生示拉的時候，猶大正在基悉。","notes":[]},{"n":6,"t":"猶大為長子珥娶妻，名叫她瑪。","notes":[]},{"n":7,"t":"猶大的長子珥在耶和華眼中看為惡，耶和華就叫他死了。","notes":[]},{"n":8,"t":"猶大對俄南說：「你當與你哥哥的妻子同房，向她盡你為弟的本分，為你哥哥生子立後。」","notes":[]},{"n":9,"t":"俄南知道生子不歸自己，所以同房的時候便遺在地，免得給他哥哥留後。","notes":[]},{"n":10,"t":"俄南所做的在耶和華眼中看為惡，耶和華也就叫他死了。","notes":[]},{"n":11,"t":"猶大心裏說：「恐怕示拉也死，像他兩個哥哥一樣」，就對他兒婦她瑪說：「你去，在你父親家裏守寡，等我兒子示拉長大。」她瑪就回去，住在她父親家裏。","notes":[]},{"n":12,"t":"過了許久，猶大的妻子書亞的女兒死了。猶大得了安慰，就和他朋友亞杜蘭人希拉上亭拿去，到他剪羊毛的人那裏。","notes":[]},{"n":13,"t":"有人告訴她瑪說：「你的公公上亭拿剪羊毛去了。」","notes":[]},{"n":14,"t":"她瑪見示拉已經長大，還沒有娶她為妻，就脫了她作寡婦的衣裳，用帕子蒙著臉，又遮住身體，坐在亭拿路上的伊拿印城門口。","notes":[]},{"n":15,"t":"猶大看見她，以為是妓女，因為她蒙著臉。","notes":[]},{"n":16,"t":"猶大就轉到她那裏去，說：「來吧！讓我與你同寢。」他原不知道是他的兒婦。她瑪說：「你要與我同寢，把甚麼給我呢？」","notes":[]},{"n":17,"t":"猶大說：「我從羊群裏取一隻山羊羔，打發人送來給你。」她瑪說：「在未送以先，你願意給我一個當頭嗎？」","notes":[]},{"n":18,"t":"他說：「我給你甚麼當頭呢？」她瑪說：「你的印、你的帶子，和你手裏的杖。」猶大就給了她，與她同寢，她就從猶大懷了孕。","notes":[]},{"n":19,"t":"她瑪起來走了，除去帕子，仍舊穿上作寡婦的衣裳。","notes":[]},{"n":20,"t":"猶大託他朋友亞杜蘭人送一隻山羊羔去，要從那女人手裏取回當頭來，卻找不著她，","notes":[]},{"n":21,"t":"就問那地方的人說：「伊拿印路旁的妓女在哪裏？」他們說：「這裏並沒有妓女。」","notes":[]},{"n":22,"t":"他回去見猶大說：「我沒有找著她，並且那地方的人說：『這裏沒有妓女。』」","notes":[]},{"n":23,"t":"猶大說：「我把這山羊羔送去了，你竟找不著她。任憑她拿去吧，免得我們被羞辱。」","notes":[]},{"n":24,"t":"約過了三個月，有人告訴猶大說：「你的兒婦她瑪作了妓女，且因行淫有了身孕。」猶大說：「拉出她來，把她燒了！」","notes":[]},{"n":25,"t":"她瑪被拉出來的時候便打發人去見她公公，對他說：「這些東西是誰的，我就是從誰懷的孕。請你認一認，這印和帶子並杖都是誰的？」","notes":[]},{"n":26,"t":"猶大承認說：「她比我更有義，因為我沒有將她給我的兒子示拉。」從此猶大不再與她同寢了。","notes":[]},{"n":27,"t":"她瑪將要生產，不料她腹裏是一對雙生。","notes":[]},{"n":28,"t":"到生產的時候，一個孩子伸出一隻手來；收生婆拿紅線拴在他手上，說：「這是頭生的。」","notes":[]},{"n":29,"t":"隨後這孩子把手收回去，他哥哥生出來了；收生婆說：「你為甚麼搶著來呢？」因此給他起名叫法勒斯。","notes":[]},{"n":30,"t":"後來，他兄弟那手上有紅線的也生出來，就給他起名叫謝拉。","notes":[]}]},"39":{"heading":"約瑟和波提乏之妻","verses":[{"n":1,"t":"約瑟被帶下埃及去。有一個埃及人，是法老的內臣－護衛長波提乏，從那些帶下他來的以實瑪利人手下買了他去。","notes":[]},{"n":2,"t":"約瑟住在他主人埃及人的家中，耶和華與他同在，他就百事順利。","notes":[]},{"n":3,"t":"他主人見耶和華與他同在，又見耶和華使他手裏所辦的盡都順利，","notes":[]},{"n":4,"t":"約瑟就在主人眼前蒙恩，伺候他主人，並且主人派他管理家務，把一切所有的都交在他手裏。","notes":[]},{"n":5,"t":"自從主人派約瑟管理家務和他一切所有的，耶和華就因約瑟的緣故賜福與那埃及人的家；凡家裏和田間一切所有的都蒙耶和華賜福。","notes":[]},{"n":6,"t":"波提乏將一切所有的都交在約瑟的手中，除了自己所吃的飯，別的事一概不知。約瑟原來秀雅俊美。","notes":[]},{"n":7,"t":"這事以後，約瑟主人的妻以目送情給約瑟，說：「你與我同寢吧！」","notes":[]},{"n":8,"t":"約瑟不從，對他主人的妻說：「看哪，一切家務，我主人都不知道；他把所有的都交在我手裏。","notes":[]},{"n":9,"t":"在這家裏沒有比我大的；並且他沒有留下一樣不交給我，只留下了你，因為你是他的妻子。我怎能作這大惡，得罪神呢？」","notes":[]},{"n":10,"t":"後來她天天和約瑟說，約瑟卻不聽從她，不與她同寢，也不和她在一處。","notes":[]},{"n":11,"t":"有一天，約瑟進屋裏去辦事，家中人沒有一個在那屋裏，","notes":[]},{"n":12,"t":"婦人就拉住他的衣裳，說：「你與我同寢吧！」約瑟把衣裳丟在婦人手裏，跑到外邊去了。","notes":[]},{"n":13,"t":"婦人看見約瑟把衣裳丟在她手裏跑出去了，","notes":[]},{"n":14,"t":"就叫了家裏的人來，對他們說：「你們看！他帶了一個希伯來人進入我們家裏，要戲弄我們。他到我這裏來，要與我同寢，我就大聲喊叫。","notes":[]},{"n":15,"t":"他聽見我放聲喊起來，就把衣裳丟在我這裏，跑到外邊去了。」","notes":[]},{"n":16,"t":"婦人把約瑟的衣裳放在自己那裏，等著他主人回家，","notes":[]},{"n":17,"t":"就對他如此如此說：「你所帶到我們這裏的那希伯來僕人進來要戲弄我，","notes":[]},{"n":18,"t":"我放聲喊起來，他就把衣裳丟在我這裏，跑出去了。」","notes":[]},{"n":19,"t":"約瑟的主人聽見他妻子對他所說的話，說「你的僕人如此如此待我」，他就生氣，","notes":[]},{"n":20,"t":"把約瑟下在監裏，就是王的囚犯被囚的地方。於是約瑟在那裏坐監。","notes":[]},{"n":21,"t":"但耶和華與約瑟同在，向他施恩，使他在司獄的眼前蒙恩。","notes":[]},{"n":22,"t":"司獄就把監裏所有的囚犯都交在約瑟的手下；他們在那裏所辦的事都是經他的手。","notes":[]},{"n":23,"t":"凡在約瑟手下的事，司獄一概不察，因為耶和華與約瑟同在；耶和華使他所做的盡都順利。","notes":[]}]},"40":{"heading":"約瑟為囚犯解夢","verses":[{"n":1,"t":"這事以後，埃及王的酒政和膳長得罪了他們的主－埃及王，","notes":[]},{"n":2,"t":"法老就惱怒酒政和膳長這二臣，","notes":[]},{"n":3,"t":"把他們下在護衛長府內的監裏，就是約瑟被囚的地方。","notes":[]},{"n":4,"t":"護衛長把他們交給約瑟，約瑟便伺候他們；他們有些日子在監裏。","notes":[]},{"n":5,"t":"被囚在監之埃及王的酒政和膳長二人同夜各做一夢，各夢都有講解。","notes":[]},{"n":6,"t":"到了早晨，約瑟進到他們那裏，見他們有愁悶的樣子。","notes":[]},{"n":7,"t":"他便問法老的二臣，就是與他同囚在他主人府裏的，說：「你們今日為甚麼面帶愁容呢？」","notes":[]},{"n":8,"t":"他們對他說：「我們各人做了一夢，沒有人能解。」約瑟說：「解夢不是出於神嗎？請你們將夢告訴我。」","notes":[]},{"n":9,"t":"酒政便將他的夢告訴約瑟說：「我夢見在我面前有一棵葡萄樹，","notes":[]},{"n":10,"t":"樹上有三根枝子，好像發了芽，開了花，上頭的葡萄都成熟了。","notes":[]},{"n":11,"t":"法老的杯在我手中，我就拿葡萄擠在法老的杯裏，將杯遞在他手中。」","notes":[]},{"n":12,"t":"約瑟對他說：「你所做的夢是這樣解：三根枝子就是三天；","notes":[]},{"n":13,"t":"三天之內，法老必提你出監，叫你官復原職，你仍要遞杯在法老的手中，和先前作他的酒政一樣。","notes":[]},{"n":14,"t":"但你得好處的時候，求你記念我，施恩與我，在法老面前提說我，救我出這監牢。","notes":[]},{"n":15,"t":"我實在是從希伯來人之地被拐來的；我在這裏也沒有做過甚麼，叫他們把我下在監裏。」","notes":[]},{"n":16,"t":"膳長見夢解得好，就對約瑟說：「我在夢中見我頭上頂著三筐白餅；","notes":[]},{"n":17,"t":"極上的筐子裏有為法老烤的各樣食物，有飛鳥來吃我頭上筐子裏的食物。」","notes":[]},{"n":18,"t":"約瑟說：「你的夢是這樣解：三個筐子就是三天；","notes":[]},{"n":19,"t":"三天之內，法老必斬斷你的頭，把你掛在木頭上，必有飛鳥來吃你身上的肉。」","notes":[]},{"n":20,"t":"到了第三天，是法老的生日，他為眾臣僕設擺筵席，把酒政和膳長提出監來，","notes":[]},{"n":21,"t":"使酒政官復原職，他仍舊遞杯在法老手中；","notes":[]},{"n":22,"t":"但把膳長掛起來，正如約瑟向他們所解的話。","notes":[]},{"n":23,"t":"酒政卻不記念約瑟，竟忘了他。","notes":[]}]},"41":{"heading":"約瑟為法老解夢","verses":[{"n":1,"t":"過了兩年，法老做夢，夢見自己站在河邊，","notes":[]},{"n":2,"t":"有七隻母牛從河裏上來，又美好又肥壯，在蘆荻中吃草。","notes":[]},{"n":3,"t":"隨後又有七隻母牛從河裏上來，又醜陋又乾瘦，與那七隻母牛一同站在河邊。","notes":[]},{"n":4,"t":"這又醜陋又乾瘦的七隻母牛吃盡了那又美好又肥壯的七隻母牛。法老就醒了。","notes":[]},{"n":5,"t":"他又睡著，第二回做夢，夢見一棵麥子長了七個穗子，又肥大又佳美，","notes":[]},{"n":6,"t":"隨後又長了七個穗子，又細弱又被東風吹焦了。","notes":[]},{"n":7,"t":"這細弱的穗子吞了那七個又肥大又飽滿的穗子。法老醒了，不料是個夢。","notes":[]},{"n":8,"t":"到了早晨，法老心裏不安，就差人召了埃及所有的術士和博士來；法老就把所做的夢告訴他們，卻沒有人能給法老圓解。","notes":[]},{"n":9,"t":"那時酒政對法老說：「我今日想起我的罪來。","notes":[]},{"n":10,"t":"從前法老惱怒臣僕，把我和膳長下在護衛長府內的監裏。","notes":[]},{"n":11,"t":"我們二人同夜各做一夢，各夢都有講解。","notes":[]},{"n":12,"t":"在那裏同著我們有一個希伯來的少年人，是護衛長的僕人，我們告訴他，他就把我們的夢圓解，是按著各人的夢圓解的。","notes":[]},{"n":13,"t":"後來正如他給我們圓解的成就了：我官復原職，膳長被掛起來了。」","notes":[]},{"n":14,"t":"法老遂即差人去召約瑟，他們便急忙帶他出監，他就剃頭，刮臉，換衣裳，進到法老面前。","notes":[]},{"n":15,"t":"法老對約瑟說：「我做了一夢，沒有人能解；我聽見人說，你聽了夢就能解。」","notes":[]},{"n":16,"t":"約瑟回答法老說：「這不在乎我，神必將平安的話回答法老。」","notes":[]},{"n":17,"t":"法老對約瑟說：「我夢見我站在河邊，","notes":[]},{"n":18,"t":"有七隻母牛從河裏上來，又肥壯又美好，在蘆荻中吃草。","notes":[]},{"n":19,"t":"隨後又有七隻母牛上來，又軟弱又醜陋又乾瘦，在埃及遍地，我沒有見過這樣不好的。","notes":[]},{"n":20,"t":"這又乾瘦又醜陋的母牛吃盡了那以先的七隻肥母牛，","notes":[]},{"n":21,"t":"吃了以後卻看不出是吃了，那醜陋的樣子仍舊和先前一樣。我就醒了。","notes":[]},{"n":22,"t":"我又夢見一棵麥子，長了七個穗子，又飽滿又佳美，","notes":[]},{"n":23,"t":"隨後又長了七個穗子，枯槁細弱，被東風吹焦了。","notes":[]},{"n":24,"t":"這些細弱的穗子吞了那七個佳美的穗子。我將這夢告訴了術士，卻沒有人能給我解說。」","notes":[]},{"n":25,"t":"約瑟對法老說：「法老的夢乃是一個。神已將所要做的事指示法老了。","notes":[]},{"n":26,"t":"七隻好母牛是七年，七個好穗子也是七年；這夢乃是一個。","notes":[]},{"n":27,"t":"那隨後上來的七隻又乾瘦又醜陋的母牛是七年，那七個虛空、被東風吹焦的穗子也是七年，都是七個荒年。","notes":[]},{"n":28,"t":"這就是我對法老所說，神已將所要做的事顯明給法老了。","notes":[]},{"n":29,"t":"埃及遍地必來七個大豐年，","notes":[]},{"n":30,"t":"隨後又要來七個荒年，甚至在埃及地都忘了先前的豐收，全地必被饑荒所滅。","notes":[]},{"n":31,"t":"因那以後的饑荒甚大，便不覺得先前的豐收了。","notes":[]},{"n":32,"t":"至於法老兩回做夢，是因神命定這事，而且必速速成就。","notes":[]},{"n":33,"t":"所以，法老當揀選一個有聰明有智慧的人，派他治理埃及地。","notes":[]},{"n":34,"t":"法老當這樣行，又派官員管理這地。當七個豐年的時候，征收埃及地的五分之一，","notes":[]},{"n":35,"t":"叫他們把將來豐年一切的糧食聚斂起來，積蓄五穀，收存在各城裏做食物，歸於法老的手下。","notes":[]},{"n":36,"t":"所積蓄的糧食可以防備埃及地將來的七個荒年，免得這地被饑荒所滅。」","notes":[]},{"n":37,"t":"法老和他一切臣僕都以這事為妙。","notes":[],"heads":["約瑟被立為埃及的宰相"]},{"n":38,"t":"法老對臣僕說：「像這樣的人，有神的靈在他裏頭，我們豈能找得著呢？」","notes":[]},{"n":39,"t":"法老對約瑟說：「神既將這事都指示你，可見沒有人像你這樣有聰明有智慧。","notes":[]},{"n":40,"t":"你可以掌管我的家；我的民都必聽從你的話。惟獨在寶座上我比你大。」","notes":[]},{"n":41,"t":"法老又對約瑟說：「我派你治理埃及全地。」","notes":[]},{"n":42,"t":"法老就摘下手上打印的戒指，戴在約瑟的手上，給他穿上細麻衣，把金鍊戴在他的頸項上，","notes":[]},{"n":43,"t":"又叫約瑟坐他的副車，喝道的在前呼叫說：「跪下。」這樣，法老派他治理埃及全地。","notes":[]},{"n":44,"t":"法老對約瑟說：「我是法老，在埃及全地，若沒有你的命令，不許人擅自辦事。」","notes":["原文是動手動腳"]},{"n":45,"t":"法老賜名給約瑟，叫撒發那忒‧巴內亞，又將安城的祭司波提非拉的女兒亞西納給他為妻。約瑟就出去巡行埃及地。","notes":[]},{"n":46,"t":"約瑟見埃及王法老的時候年三十歲。他從法老面前出去，遍行埃及全地。","notes":[]},{"n":47,"t":"七個豐年之內，地的出產極豐極盛，","notes":["原文是一把一把的"]},{"n":48,"t":"約瑟聚斂埃及地七個豐年一切的糧食，把糧食積存在各城裏；各城周圍田地的糧食都積存在本城裏。","notes":[]},{"n":49,"t":"約瑟積蓄五穀甚多，如同海邊的沙，無法計算，因為穀不可勝數。","notes":[]},{"n":50,"t":"荒年未到以前，安城的祭司波提非拉的女兒亞西納給約瑟生了兩個兒子。","notes":[]},{"n":51,"t":"約瑟給長子起名叫瑪拿西，因為他說：「神使我忘了一切的困苦和我父的全家。」","notes":["就是使之忘了的意思"]},{"n":52,"t":"他給次子起名叫以法蓮，因為他說：「神使我在受苦的地方昌盛。」","notes":["就是使之昌盛的意思"]},{"n":53,"t":"埃及地的七個豐年一完，","notes":[]},{"n":54,"t":"七個荒年就來了。正如約瑟所說的，各地都有饑荒；惟獨埃及全地有糧食。","notes":[]},{"n":55,"t":"及至埃及全地有了饑荒，眾民向法老哀求糧食，法老對他們說：「你們往約瑟那裏去，凡他所說的，你們都要做。」","notes":[]},{"n":56,"t":"當時饑荒遍滿天下，約瑟開了各處的倉，糶糧給埃及人；在埃及地饑荒甚大。","notes":[]},{"n":57,"t":"各地的人都往埃及去，到約瑟那裏糴糧，因為天下的饑荒甚大。","notes":[]}]},"42":{"heading":"約瑟的哥哥們往埃及買糧","verses":[{"n":1,"t":"雅各見埃及有糧，就對兒子們說：「你們為甚麼彼此觀望呢？","notes":[]},{"n":2,"t":"我聽見埃及有糧，你們可以下去，從那裏為我們糴些來，使我們可以存活，不至於死。」","notes":[]},{"n":3,"t":"於是，約瑟的十個哥哥都下埃及糴糧去了。","notes":[]},{"n":4,"t":"但約瑟的兄弟便雅憫，雅各沒有打發他和哥哥們同去，因為雅各說：「恐怕他遭害。」","notes":[]},{"n":5,"t":"來糴糧的人中有以色列的兒子們，因為迦南地也有饑荒。","notes":[]},{"n":6,"t":"當時治理埃及地的是約瑟；糶糧給那地眾民的就是他。約瑟的哥哥們來了，臉伏於地，向他下拜。","notes":[]},{"n":7,"t":"約瑟看見他哥哥們，就認得他們，卻裝作生人，向他們說些嚴厲話，問他們說：「你們從哪裏來？」他們說：「我們從迦南地來糴糧。」","notes":[]},{"n":8,"t":"約瑟認得他哥哥們，他們卻不認得他。","notes":[]},{"n":9,"t":"約瑟想起從前所做的那兩個夢，就對他們說：「你們是奸細，來窺探這地的虛實。」","notes":[]},{"n":10,"t":"他們對他說：「我主啊，不是的。僕人們是糴糧來的。","notes":[]},{"n":11,"t":"我們都是一個人的兒子，是誠實人；僕人們並不是奸細。」","notes":[]},{"n":12,"t":"約瑟說：「不然，你們必是窺探這地的虛實來的。」","notes":[]},{"n":13,"t":"他們說：「僕人們本是弟兄十二人，是迦南地一個人的兒子，頂小的現今在我們的父親那裏，有一個沒有了。」","notes":[]},{"n":14,"t":"約瑟說：「我才說你們是奸細，這話實在不錯。","notes":[]},{"n":15,"t":"我指著法老的性命起誓，若是你們的小兄弟不到這裏來，你們就不得出這地方，從此就可以把你們證驗出來了。","notes":[]},{"n":16,"t":"須要打發你們中間一個人去，把你們的兄弟帶來。至於你們，都要囚在這裏，好證驗你們的話真不真，若不真，我指著法老的性命起誓，你們一定是奸細。」","notes":[]},{"n":17,"t":"於是約瑟把他們都下在監裏三天。","notes":[]},{"n":18,"t":"到第三天，約瑟對他們說：「我是敬畏神的；你們照我的話行就可以存活。","notes":[]},{"n":19,"t":"你們如果是誠實人，可以留你們中間的一個人囚在監裏，但你們可以帶著糧食回去，救你們家裏的饑荒。","notes":[]},{"n":20,"t":"把你們的小兄弟帶到我這裏來，如此，你們的話便有證據，你們也不至於死。」他們就照樣而行。","notes":[]},{"n":21,"t":"他們彼此說：「我們在兄弟身上實在有罪。他哀求我們的時候，我們見他心裏的愁苦，卻不肯聽，所以這場苦難臨到我們身上。」","notes":[]},{"n":22,"t":"呂便說：「我豈不是對你們說過，不可傷害那孩子嗎？只是你們不肯聽，所以流他血的罪向我們追討。」","notes":[]},{"n":23,"t":"他們不知道約瑟聽得出來，因為在他們中間用通事傳話。","notes":[]},{"n":24,"t":"約瑟轉身退去，哭了一場，又回來對他們說話，就從他們中間挑出西緬來，在他們眼前把他捆綁。","notes":[]},{"n":25,"t":"約瑟吩咐人把糧食裝滿他們的器具，把各人的銀子歸還在各人的口袋裏，又給他們路上用的食物，人就照他的話辦了。","notes":[],"heads":["約瑟的哥哥們回迦南地"]},{"n":26,"t":"他們就把糧食馱在驢上，離開那裏去了。","notes":[]},{"n":27,"t":"到了住宿的地方，他們中間有一個人打開口袋，要拿料餵驢，才看見自己的銀子仍在口袋裏，","notes":[]},{"n":28,"t":"就對弟兄們說：「我的銀子歸還了，看哪，仍在我口袋裏！」他們就提心吊膽，戰戰兢兢地彼此說：「這是神向我們做甚麼呢？」","notes":[]},{"n":29,"t":"他們來到迦南地、他們的父親雅各那裏，將所遭遇的事都告訴他，說：","notes":[]},{"n":30,"t":"「那地的主對我們說嚴厲的話，把我們當作窺探那地的奸細。","notes":[]},{"n":31,"t":"我們對他說：『我們是誠實人，並不是奸細。","notes":[]},{"n":32,"t":"我們本是弟兄十二人，都是一個父親的兒子，有一個沒有了，頂小的如今同我們的父親在迦南地。』","notes":[]},{"n":33,"t":"那地的主對我們說：『若要我知道你們是誠實人，可以留下你們中間的一個人在我這裏，你們可以帶著糧食回去，救你們家裏的饑荒。","notes":[]},{"n":34,"t":"把你們的小兄弟帶到我這裏來，我便知道你們不是奸細，乃是誠實人。這樣，我就把你們的弟兄交給你們，你們也可以在這地做買賣。』」","notes":[]},{"n":35,"t":"後來他們倒口袋，不料，各人的銀包都在口袋裏；他們和父親看見銀包就都害怕。","notes":[]},{"n":36,"t":"他們的父親雅各對他們說：「你們使我喪失我的兒子：約瑟沒有了，西緬也沒有了，你們又要將便雅憫帶去；這些事都歸到我身上了。」","notes":[]},{"n":37,"t":"呂便對他父親說：「我若不帶他回來交給你，你可以殺我的兩個兒子。只管把他交在我手裏，我必帶他回來交給你。」","notes":[]},{"n":38,"t":"雅各說：「我的兒子不可與你們一同下去；他哥哥死了，只剩下他，他若在你們所行的路上遭害，那便是你們使我白髮蒼蒼、悲悲慘慘地下陰間去了。」","notes":[]}]},"43":{"heading":"約瑟的哥哥們帶便雅憫到埃及","verses":[{"n":1,"t":"那地的饑荒甚大。","notes":[]},{"n":2,"t":"他們從埃及帶來的糧食吃盡了，他們的父親就對他們說：「你們再去給我糴些糧來。」","notes":[]},{"n":3,"t":"猶大對他說：「那人諄諄地告誡我們說：『你們的兄弟若不與你們同來，你們就不得見我的面。』","notes":[]},{"n":4,"t":"你若打發我們的兄弟與我們同去，我們就下去給你糴糧；","notes":[]},{"n":5,"t":"你若不打發他去，我們就不下去，因為那人對我們說：『你們的兄弟若不與你們同來，你們就不得見我的面。』」","notes":[]},{"n":6,"t":"以色列說：「你們為甚麼這樣害我，告訴那人你們還有兄弟呢？」","notes":[]},{"n":7,"t":"他們回答說：「那人詳細問到我們和我們的親屬，說：『你們的父親還在嗎？你們還有兄弟嗎？』我們就按著他所問的告訴他，焉能知道他要說『必須把你們的兄弟帶下來』呢？」","notes":[]},{"n":8,"t":"猶大又對他父親以色列說：「你打發童子與我同去，我們就起身下去，好叫我們和你，並我們的婦人孩子，都得存活，不至於死。","notes":[]},{"n":9,"t":"我為他作保；你可以從我手中追討，我若不帶他回來交在你面前，我情願永遠擔罪。","notes":[]},{"n":10,"t":"我們若沒有耽擱，如今第二次都回來了。」","notes":[]},{"n":11,"t":"他們的父親以色列說：「若必須如此，你們就當這樣行：可以將這地土產中最好的乳香、蜂蜜、香料、沒藥、榧子、杏仁都取一點，收在器具裏，帶下去送給那人作禮物，","notes":[]},{"n":12,"t":"又要手裏加倍地帶銀子，並將歸還在你們口袋內的銀子仍帶在手裏；那或者是錯了。","notes":[]},{"n":13,"t":"也帶著你們的兄弟，起身去見那人。","notes":[]},{"n":14,"t":"但願全能的神使你們在那人面前蒙憐憫，釋放你們的那弟兄和便雅憫回來。我若喪了兒子，就喪了吧！」","notes":[]},{"n":15,"t":"於是，他們拿著那禮物，又手裏加倍地帶銀子，並且帶著便雅憫，起身下到埃及，站在約瑟面前。","notes":[]},{"n":16,"t":"約瑟見便雅憫和他們同來，就對家宰說：「將這些人領到屋裏。要宰殺牲畜，預備筵席，因為晌午這些人同我吃飯。」","notes":[]},{"n":17,"t":"家宰就遵著約瑟的命去行，領他們進約瑟的屋裏。","notes":[]},{"n":18,"t":"他們因為被領到約瑟的屋裏，就害怕，說：「領我們到這裏來，必是因為頭次歸還在我們口袋裏的銀子，找我們的錯縫，下手害我們，強取我們為奴僕，搶奪我們的驢。」","notes":[]},{"n":19,"t":"他們就挨近約瑟的家宰，在屋門口和他說話，","notes":[]},{"n":20,"t":"說：「我主啊，我們頭次下來實在是要糴糧。","notes":[]},{"n":21,"t":"後來到了住宿的地方，我們打開口袋，不料，各人的銀子，分量足數，仍在各人的口袋內，現在我們手裏又帶回來了。","notes":[]},{"n":22,"t":"另外又帶下銀子來糴糧。不知道先前誰把銀子放在我們的口袋裏。」","notes":[]},{"n":23,"t":"家宰說：「你們可以放心，不要害怕，是你們的神和你們父親的神賜給你們財寶在你們的口袋裏；你們的銀子，我早已收了。」他就把西緬帶出來，交給他們。","notes":[]},{"n":24,"t":"家宰就領他們進約瑟的屋裏，給他們水洗腳，又給他們草料餵驢。","notes":[]},{"n":25,"t":"他們就預備那禮物，等候約瑟晌午來，因為他們聽見要在那裏吃飯。","notes":[]},{"n":26,"t":"約瑟來到家裏，他們就把手中的禮物拿進屋去給他，又俯伏在地，向他下拜。","notes":[]},{"n":27,"t":"約瑟問他們好，又問：「你們的父親－就是你們所說的那老人家平安嗎？他還在嗎？」","notes":[]},{"n":28,"t":"他們回答說：「你僕人－我們的父親平安；他還在。」於是他們低頭下拜。","notes":[]},{"n":29,"t":"約瑟舉目看見他同母的兄弟便雅憫，就說：「你們向我所說那頂小的兄弟就是這位嗎？」又說：「小兒啊，願神賜恩給你！」","notes":[]},{"n":30,"t":"約瑟愛弟之情發動，就急忙尋找可哭之地，進入自己的屋裏，哭了一場。","notes":[]},{"n":31,"t":"他洗了臉出來，勉強隱忍，吩咐人擺飯。","notes":[]},{"n":32,"t":"他們就為約瑟單擺了一席，為那些人又擺了一席，也為和約瑟同吃飯的埃及人另擺了一席，因為埃及人不可和希伯來人一同吃飯；那原是埃及人所厭惡的。","notes":[]},{"n":33,"t":"約瑟使眾弟兄在他面前排列坐席，都按著長幼的次序，眾弟兄就彼此詫異。","notes":[]},{"n":34,"t":"約瑟把他面前的食物分出來，送給他們；但便雅憫所得的比別人多五倍。他們就飲酒，和約瑟一同宴樂。","notes":[]}]},"44":{"heading":"失落的杯","verses":[{"n":1,"t":"約瑟吩咐家宰說：「把糧食裝滿這些人的口袋，儘著他們的驢所能馱的，又把各人的銀子放在各人的口袋裏，","notes":[]},{"n":2,"t":"並將我的銀杯和那少年人糴糧的銀子一同裝在他的口袋裏。」家宰就照約瑟所說的話行了；","notes":[]},{"n":3,"t":"天一亮就打發那些人帶著驢走了。","notes":[]},{"n":4,"t":"他們出城走了不遠，約瑟對家宰說：「起來，追那些人去，追上了就對他們說：『你們為甚麼以惡報善呢？","notes":[]},{"n":5,"t":"這不是我主人飲酒的杯嗎？豈不是他占卜用的嗎？你們這樣行是作惡了。』」","notes":[]},{"n":6,"t":"家宰追上他們，將這些話對他們說了。","notes":[]},{"n":7,"t":"他們回答說：「我主為甚麼說這樣的話呢？你僕人斷不能做這樣的事。","notes":[]},{"n":8,"t":"你看，我們從前在口袋裏所見的銀子，尚且從迦南地帶來還你，我們怎能從你主人家裏偷竊金銀呢？","notes":[]},{"n":9,"t":"你僕人中無論在誰那裏搜出來，就叫他死，我們也作我主的奴僕。」","notes":[]},{"n":10,"t":"家宰說：「現在就照你們的話行吧！在誰那裏搜出來，誰就作我的奴僕；其餘的都沒有罪。」","notes":[]},{"n":11,"t":"於是他們各人急忙把口袋卸在地下，各人打開口袋。","notes":[]},{"n":12,"t":"家宰就搜查，從年長的起到年幼的為止，那杯竟在便雅憫的口袋裏搜出來。","notes":[]},{"n":13,"t":"他們就撕裂衣服，各人把馱子抬在驢上，回城去了。","notes":[]},{"n":14,"t":"猶大和他弟兄們來到約瑟的屋中，約瑟還在那裏，他們就在他面前俯伏於地。","notes":[]},{"n":15,"t":"約瑟對他們說：「你們做的是甚麼事呢？你們豈不知像我這樣的人必能占卜嗎？」","notes":[]},{"n":16,"t":"猶大說：「我們對我主說甚麼呢？還有甚麼話可說呢？我們怎能自己表白出來呢？神已經查出僕人的罪孽了。我們與那在他手中搜出杯來的都是我主的奴僕。」","notes":[]},{"n":17,"t":"約瑟說：「我斷不能這樣行！在誰的手中搜出杯來，誰就作我的奴僕；至於你們，可以平平安安地上你們父親那裏去。」","notes":[]},{"n":18,"t":"猶大挨近他，說：「我主啊，求你容僕人說一句話給我主聽，不要向僕人發烈怒，因為你如同法老一樣。","notes":[],"heads":["猶大替便雅憫哀求"]},{"n":19,"t":"我主曾問僕人們說：『你們有父親有兄弟沒有？』","notes":[]},{"n":20,"t":"我們對我主說：『我們有父親，已經年老，還有他老年所生的一個小孩子。他哥哥死了，他母親只撇下他一人，他父親疼愛他。』","notes":[]},{"n":21,"t":"你對僕人說：『把他帶到我這裏來，叫我親眼看看他。』","notes":[]},{"n":22,"t":"我們對我主說：『童子不能離開他父親，若是離開，他父親必死。』","notes":[]},{"n":23,"t":"你對僕人說：『你們的小兄弟若不與你們一同下來，你們就不得再見我的面。』","notes":[]},{"n":24,"t":"我們上到你僕人－我們父親那裏，就把我主的話告訴了他。","notes":[]},{"n":25,"t":"我們的父親說：『你們再去給我糴些糧來。』","notes":[]},{"n":26,"t":"我們就說：『我們不能下去。我們的小兄弟若和我們同往，我們就可以下去。因為，小兄弟若不與我們同往，我們必不得見那人的面。』","notes":[]},{"n":27,"t":"你僕人－我父親對我們說：『你們知道我的妻子給我生了兩個兒子。","notes":[]},{"n":28,"t":"一個離開我出去了；我說他必是被撕碎了，直到如今我也沒有見他。","notes":[]},{"n":29,"t":"現在你們又要把這個帶去離開我，倘若他遭害，那便是你們使我白髮蒼蒼、悲悲慘慘地下陰間去了。』","notes":[]},{"n":30,"t":"我父親的命與這童子的命相連。如今我回到你僕人－我父親那裏，若沒有童子與我們同在，","notes":[]},{"n":31,"t":"我們的父親見沒有童子，他就必死。這便是我們使你僕人－我們的父親白髮蒼蒼、悲悲慘慘地下陰間去了。","notes":[]},{"n":32,"t":"因為僕人曾向我父親為這童子作保，說：『我若不帶他回來交給父親，我便在父親面前永遠擔罪。』","notes":[]},{"n":33,"t":"現在求你容僕人住下，替這童子作我主的奴僕，叫童子和他哥哥們一同上去。","notes":[]},{"n":34,"t":"若童子不和我同去，我怎能上去見我父親呢？恐怕我看見災禍臨到我父親身上。」","notes":[]}]},"45":{"heading":"約瑟和兄弟相認","verses":[{"n":1,"t":"約瑟在左右站著的人面前情不自禁，吩咐一聲說：「人都要離開我出去！」約瑟和弟兄們相認的時候並沒有一人站在他面前。","notes":[]},{"n":2,"t":"他就放聲大哭；埃及人和法老家中的人都聽見了。","notes":[]},{"n":3,"t":"約瑟對他弟兄們說：「我是約瑟。我的父親還在嗎？」他弟兄不能回答，因為在他面前都驚惶。","notes":[]},{"n":4,"t":"約瑟又對他弟兄們說：「請你們近前來。」他們就近前來。他說：「我是你們的兄弟約瑟，就是你們所賣到埃及的。","notes":[]},{"n":5,"t":"現在，不要因為把我賣到這裏自憂自恨。這是神差我在你們以先來，為要保全生命。","notes":[]},{"n":6,"t":"現在這地的饑荒已經二年了，還有五年不能耕種，不能收成。","notes":[]},{"n":7,"t":"神差我在你們以先來，為要給你們存留餘種在世上，又要大施拯救，保全你們的生命。","notes":[]},{"n":8,"t":"這樣看來，差我到這裏來的不是你們，乃是神。他又使我如法老的父，作他全家的主，並埃及全地的宰相。","notes":[]},{"n":9,"t":"你們要趕緊上到我父親那裏，對他說：『你兒子約瑟這樣說：神使我作全埃及的主，請你下到我這裏來，不要耽延。","notes":[]},{"n":10,"t":"你和你的兒子孫子，連牛群羊群，並一切所有的，都可以住在歌珊地，與我相近。","notes":[]},{"n":11,"t":"我要在那裏奉養你；因為還有五年的饑荒，免得你和你的眷屬，並一切所有的，都敗落了。』","notes":[]},{"n":12,"t":"況且你們的眼和我兄弟便雅憫的眼都看見是我親口對你們說話。","notes":[]},{"n":13,"t":"你們也要將我在埃及一切的榮耀和你們所看見的事都告訴我父親，又要趕緊地將我父親搬到我這裏來。」","notes":[]},{"n":14,"t":"於是約瑟伏在他兄弟便雅憫的頸項上哭，便雅憫也在他的頸項上哭。","notes":[]},{"n":15,"t":"他又與眾弟兄親嘴，抱著他們哭，隨後他弟兄們就和他說話。","notes":[]},{"n":16,"t":"這風聲傳到法老的宮裏，說：「約瑟的弟兄們來了。」法老和他的臣僕都很喜歡。","notes":[]},{"n":17,"t":"法老對約瑟說：「你吩咐你的弟兄們說：『你們要這樣行：把馱子抬在牲口上，起身往迦南地去。","notes":[]},{"n":18,"t":"將你們的父親和你們的眷屬都搬到我這裏來，我要把埃及地的美物賜給你們，你們也要吃這地肥美的出產。","notes":[]},{"n":19,"t":"現在我吩咐你們要這樣行：從埃及地帶著車輛去，把你們的孩子和妻子，並你們的父親都搬來。","notes":[]},{"n":20,"t":"你們眼中不要愛惜你們的家具，因為埃及全地的美物都是你們的。』」","notes":[]},{"n":21,"t":"以色列的兒子們就如此行。約瑟照著法老的吩咐給他們車輛和路上用的食物，","notes":[]},{"n":22,"t":"又給他們各人一套衣服，惟獨給便雅憫三百銀子，五套衣服；","notes":[]},{"n":23,"t":"送給他父親公驢十匹，馱著埃及的美物，母驢十匹，馱著糧食與餅和菜，為他父親路上用。","notes":[]},{"n":24,"t":"於是約瑟打發他弟兄們回去，又對他們說：「你們不要在路上相爭。」","notes":[]},{"n":25,"t":"他們從埃及上去，來到迦南地、他們的父親雅各那裏，","notes":[]},{"n":26,"t":"告訴他說：「約瑟還在，並且作埃及全地的宰相。」雅各心裏冰涼，因為不信他們。","notes":[]},{"n":27,"t":"他們便將約瑟對他們說的一切話都告訴了他。他們父親雅各又看見約瑟打發來接他的車輛，心就甦醒了。","notes":[]},{"n":28,"t":"以色列說：「罷了！罷了！我的兒子約瑟還在，趁我未死以先，我要去見他一面。」","notes":[]}]},"46":{"heading":"雅各帶家屬到埃及","verses":[{"n":1,"t":"以色列帶著一切所有的，起身來到別是巴，就獻祭給他父親以撒的神。","notes":[]},{"n":2,"t":"夜間，神在異象中對以色列說：「雅各！雅各！」他說：「我在這裏。」","notes":[]},{"n":3,"t":"神說：「我是神，就是你父親的神。你下埃及去不要害怕，因為我必使你在那裏成為大族。","notes":[]},{"n":4,"t":"我要和你同下埃及去，也必定帶你上來；約瑟必給你送終。」","notes":["原文是將手按在你的眼睛上"]},{"n":5,"t":"雅各就從別是巴起行。以色列的兒子們使他們的父親雅各和他們的妻子、兒女都坐在法老為雅各送來的車上。","notes":[]},{"n":6,"t":"他們又帶著迦南地所得的牲畜、貨財來到埃及。雅各和他的一切子孫都一同來了。","notes":[]},{"n":7,"t":"雅各把他的兒子、孫子、女兒、孫女，並他的子子孫孫，一同帶到埃及。","notes":[]},{"n":8,"t":"來到埃及的以色列人名字記在下面。雅各和他的兒孫：雅各的長子是呂便。","notes":[]},{"n":9,"t":"呂便的兒子是哈諾、法路、希斯倫、迦米。","notes":[]},{"n":10,"t":"西緬的兒子是耶母利、雅憫、阿轄、雅斤、瑣轄，還有迦南女子所生的掃羅。","notes":[]},{"n":11,"t":"利未的兒子是革順、哥轄、米拉利。","notes":[]},{"n":12,"t":"猶大的兒子是珥、俄南、示拉、法勒斯、謝拉；惟有珥與俄南死在迦南地。法勒斯的兒子是希斯崙、哈母勒。","notes":[]},{"n":13,"t":"以薩迦的兒子是陀拉、普瓦、約伯、伸崙。","notes":[]},{"n":14,"t":"西布倫的兒子是西烈、以倫、雅利。","notes":[]},{"n":15,"t":"這是利亞在巴旦‧亞蘭給雅各所生的兒子，還有女兒底拿。兒孫共有三十三人。","notes":[]},{"n":16,"t":"迦得的兒子是洗非芸、哈基、書尼、以斯本、以利、亞羅底、亞列利。","notes":[]},{"n":17,"t":"亞設的兒子是音拿、亦施瓦、亦施韋、比利亞，還有他們的妹子西拉。比利亞的兒子是希別、瑪結。","notes":[]},{"n":18,"t":"這是拉班給他女兒利亞的婢女悉帕從雅各所生的兒孫，共有十六人。","notes":[]},{"n":19,"t":"雅各之妻拉結的兒子是約瑟和便雅憫。","notes":[]},{"n":20,"t":"約瑟在埃及地生了瑪拿西和以法蓮，就是安城的祭司波提非拉的女兒亞西納給約瑟生的。","notes":[]},{"n":21,"t":"便雅憫的兒子是比拉、比結、亞實別、基拉、乃幔、以希、羅實、母平、戶平、亞勒。","notes":[]},{"n":22,"t":"這是拉結給雅各所生的兒孫，共有十四人。","notes":[]},{"n":23,"t":"但的兒子是戶伸。","notes":[]},{"n":24,"t":"拿弗他利的兒子是雅薛、沽尼、耶色、示冷。","notes":[]},{"n":25,"t":"這是拉班給他女兒拉結的婢女辟拉從雅各所生的兒孫，共有七人。","notes":[]},{"n":26,"t":"那與雅各同到埃及的，除了他兒婦之外，凡從他所生的，共有六十六人。","notes":[]},{"n":27,"t":"還有約瑟在埃及所生的兩個兒子。雅各家來到埃及的共有七十人。","notes":[]},{"n":28,"t":"雅各打發猶大先去見約瑟，請派人引路往歌珊去；於是他們來到歌珊地。","notes":[],"heads":["雅各和家屬在埃及"]},{"n":29,"t":"約瑟套車往歌珊去，迎接他父親以色列，及至見了面，就伏在父親的頸項上，哭了許久。","notes":[]},{"n":30,"t":"以色列對約瑟說：「我既得見你的面，知道你還在，就是死我也甘心。」","notes":[]},{"n":31,"t":"約瑟對他的弟兄和他父的全家說：「我要上去告訴法老，對他說：『我的弟兄和我父的全家從前在迦南地，現今都到我這裏來了。","notes":[]},{"n":32,"t":"他們本是牧羊的人，以養牲畜為業；他們把羊群牛群和一切所有的都帶來了。』","notes":[]},{"n":33,"t":"等法老召你們的時候，問你們說：『你們以何事為業？』","notes":[]},{"n":34,"t":"你們要說：『你的僕人，從幼年直到如今，都以養牲畜為業，連我們的祖宗也都以此為業。』這樣，你們可以住在歌珊地，因為凡牧羊的都被埃及人所厭惡。」","notes":[]}]},"47":{"heading":"饑荒","verses":[{"n":1,"t":"約瑟進去告訴法老說：「我的父親和我的弟兄帶著羊群牛群，並一切所有的，從迦南地來了，如今在歌珊地。」","notes":[]},{"n":2,"t":"約瑟從他弟兄中挑出五個人來，引他們去見法老。","notes":[]},{"n":3,"t":"法老問約瑟的弟兄說：「你們以何事為業？」他們對法老說：「你僕人是牧羊的，連我們的祖宗也是牧羊的。」","notes":[]},{"n":4,"t":"他們又對法老說：「迦南地的饑荒甚大，僕人的羊群沒有草吃，所以我們來到這地寄居。現在求你容僕人住在歌珊地。」","notes":[]},{"n":5,"t":"法老對約瑟說：「你父親和你弟兄到你這裏來了，","notes":[]},{"n":6,"t":"埃及地都在你面前，只管叫你父親和你弟兄住在國中最好的地；他們可以住在歌珊地。你若知道他們中間有甚麼能人，就派他們看管我的牲畜。」","notes":[]},{"n":7,"t":"約瑟領他父親雅各進到法老面前，雅各就給法老祝福。","notes":[]},{"n":8,"t":"法老問雅各說：「你平生的年日是多少呢？」","notes":[]},{"n":9,"t":"雅各對法老說：「我寄居在世的年日是一百三十歲，我平生的年日又少又苦，不及我列祖在世寄居的年日。」","notes":[]},{"n":10,"t":"雅各又給法老祝福，就從法老面前出去了。","notes":[]},{"n":11,"t":"約瑟遵著法老的命，把埃及國最好的地，就是蘭塞境內的地，給他父親和弟兄居住，作為產業。","notes":[]},{"n":12,"t":"約瑟用糧食奉養他父親和他弟兄，並他父親全家的眷屬，都是照各家的人口奉養他們。","notes":[]},{"n":13,"t":"饑荒甚大，全地都絕了糧，甚至埃及地和迦南地的人因那饑荒的緣故都餓昏了。","notes":[]},{"n":14,"t":"約瑟收聚了埃及地和迦南地所有的銀子，就是眾人糴糧的銀子，約瑟就把那銀子帶到法老的宮裏。","notes":[]},{"n":15,"t":"埃及地和迦南地的銀子都花盡了，埃及眾人都來見約瑟，說：「我們的銀子都用盡了，求你給我們糧食，我們為甚麼死在你面前呢？」","notes":[]},{"n":16,"t":"約瑟說：「若是銀子用盡了，可以把你們的牲畜給我，我就為你們的牲畜給你們糧食。」","notes":[]},{"n":17,"t":"於是他們把牲畜趕到約瑟那裏，約瑟就拿糧食換了他們的牛、羊、驢、馬；那一年因換他們一切的牲畜，就用糧食養活他們。","notes":[]},{"n":18,"t":"那一年過去，第二年他們又來見約瑟，說：「我們不瞞我主，我們的銀子都花盡了，牲畜也都歸了我主。我們在我主眼前，除了我們的身體和田地之外，一無所剩。","notes":[]},{"n":19,"t":"你何忍見我們人死地荒呢？求你用糧食買我們和我們的地，我們和我們的地就要給法老效力。又求你給我們種子，使我們得以存活，不致死亡，地土也不致荒涼。」","notes":[]},{"n":20,"t":"於是，約瑟為法老買了埃及所有的地，埃及人因被饑荒所迫，各都賣了自己的田地；那地就都歸了法老。","notes":[]},{"n":21,"t":"至於百姓，約瑟叫他們，從埃及這邊直到埃及那邊，都各歸各城。","notes":[]},{"n":22,"t":"惟有祭司的地，約瑟沒有買，因為祭司有從法老所得的常俸。他們吃法老所給的常俸，所以他們不賣自己的地。","notes":[]},{"n":23,"t":"約瑟對百姓說：「我今日為法老買了你們和你們的地，看哪，這裏有種子給你們，你們可以種地。","notes":[]},{"n":24,"t":"後來打糧食的時候，你們要把五分之一納給法老，四分可以歸你們做地裏的種子，也做你們和你們家口孩童的食物。」","notes":[]},{"n":25,"t":"他們說：「你救了我們的性命。但願我們在我主眼前蒙恩，我們就作法老的僕人。」","notes":[]},{"n":26,"t":"於是約瑟為埃及地定下常例，直到今日：法老必得五分之一，惟獨祭司的地不歸法老。","notes":[]},{"n":27,"t":"以色列人住在埃及的歌珊地。他們在那裏置了產業，並且生育甚多。","notes":[],"heads":["雅各最後的吩咐"]},{"n":28,"t":"雅各住在埃及地十七年，雅各平生的年日是一百四十七歲。","notes":[]},{"n":29,"t":"以色列的死期臨近了，他就叫了他兒子約瑟來，說：「我若在你眼前蒙恩，請你把手放在我大腿底下，用慈愛和誠實待我，請你不要將我葬在埃及。","notes":[]},{"n":30,"t":"我與我祖我父同睡的時候，你要將我帶出埃及，葬在他們所葬的地方。」約瑟說：「我必遵著你的命而行。」","notes":[]},{"n":31,"t":"雅各說：「你要向我起誓。」約瑟就向他起了誓，於是以色列在床頭上敬拜神。","notes":["或譯：扶著杖頭"]}]},"48":{"heading":"雅各祝福以法蓮和瑪拿西","verses":[{"n":1,"t":"這事以後，有人告訴約瑟說：「你的父親病了。」他就帶著兩個兒子瑪拿西和以法蓮同去。","notes":[]},{"n":2,"t":"有人告訴雅各說：「請看，你兒子約瑟到你這裏來了。」以色列就勉強在床上坐起來。","notes":[]},{"n":3,"t":"雅各對約瑟說：「全能的神曾在迦南地的路斯向我顯現，賜福與我，","notes":[]},{"n":4,"t":"對我說：『我必使你生養眾多，成為多民，又要把這地賜給你的後裔，永遠為業。』","notes":[]},{"n":5,"t":"我未到埃及見你之先，你在埃及地所生的以法蓮和瑪拿西這兩個兒子是我的，正如呂便和西緬是我的一樣。","notes":[]},{"n":6,"t":"你在他們以後所生的就是你的，他們可以歸於他們弟兄的名下得產業。","notes":[]},{"n":7,"t":"至於我，我從巴旦來的時候，拉結死在我眼前，在迦南地的路上，離以法他還有一段路程，我就把她葬在以法他的路上（以法他就是伯利恆）。」","notes":[]},{"n":8,"t":"以色列看見約瑟的兩個兒子，就說：「這是誰？」","notes":[]},{"n":9,"t":"約瑟對他父親說：「這是神在這裏賜給我的兒子。」以色列說：「請你領他們到我跟前，我要給他們祝福。」","notes":[]},{"n":10,"t":"以色列年紀老邁，眼睛昏花，不能看見。約瑟領他們到他跟前，他就和他們親嘴，抱著他們。","notes":[]},{"n":11,"t":"以色列對約瑟說：「我想不到得見你的面，不料，神又使我得見你的兒子。」","notes":[]},{"n":12,"t":"約瑟把兩個兒子從以色列兩膝中領出來，自己就臉伏於地下拜。","notes":[]},{"n":13,"t":"隨後，約瑟又拉著他們兩個，以法蓮在他的右手裏，對著以色列的左手，瑪拿西在他的左手裏，對著以色列的右手，領他們到以色列的跟前。","notes":[]},{"n":14,"t":"以色列伸出右手來，按在以法蓮的頭上（以法蓮乃是次子），又剪搭過左手來，按在瑪拿西的頭上（瑪拿西原是長子）。","notes":[]},{"n":15,"t":"他就給約瑟祝福說：「願我祖亞伯拉罕和我父以撒所事奉的神，就是一生牧養我直到今日的神，","notes":[]},{"n":16,"t":"救贖我脫離一切患難的那使者，賜福與這兩個童子。願他們歸在我的名下和我祖亞伯拉罕、我父以撒的名下。又願他們在世界中生養眾多。」","notes":[]},{"n":17,"t":"約瑟見他父親把右手按在以法蓮的頭上，就不喜悅，便提起他父親的手，要從以法蓮頭上挪到瑪拿西的頭上。","notes":[]},{"n":18,"t":"約瑟對他父親說：「我父，不是這樣。這本是長子，求你把右手按在他的頭上。」","notes":[]},{"n":19,"t":"他父親不從，說：「我知道，我兒，我知道。他也必成為一族，也必昌大。只是他的兄弟將來比他還大；他兄弟的後裔要成為多族。」","notes":[]},{"n":20,"t":"當日就給他們祝福說：「以色列人要指著你們祝福說：『願神使你如以法蓮、瑪拿西一樣。』」於是立以法蓮在瑪拿西以上。","notes":[]},{"n":21,"t":"以色列又對約瑟說：「我要死了，但神必與你們同在，領你們回到你們列祖之地。","notes":[]},{"n":22,"t":"並且我從前用弓用刀從亞摩利人手下奪的那塊地，我都賜給你，使你比眾弟兄多得一分。」","notes":[]}]},"49":{"heading":"雅各的遺囑","verses":[{"n":1,"t":"雅各叫了他的兒子們來，說：「你們都來聚集，我好把你們日後必遇的事告訴你們。","notes":[]},{"n":2,"t":"雅各的兒子們，你們要聚集而聽，要聽你們父親以色列的話。","notes":[]},{"n":3,"t":"呂便哪，你是我的長子，是我力量強壯的時候生的，本當大有尊榮，權力超眾。","notes":[]},{"n":4,"t":"但你放縱情慾，滾沸如水，必不得居首位；因為你上了你父親的床，污穢了我的榻。","notes":[]},{"n":5,"t":"西緬和利未是弟兄；他們的刀劍是殘忍的器具。","notes":[]},{"n":6,"t":"我的靈啊，不要與他們同謀；我的心哪，不要與他們聯絡；因為他們趁怒殺害人命，任意砍斷牛腿大筋。","notes":[]},{"n":7,"t":"他們的怒氣暴烈可咒；他們的忿恨殘忍可詛。我要使他們分居在雅各家裏，散住在以色列地中。","notes":[]},{"n":8,"t":"猶大啊，你弟兄們必讚美你；你手必掐住仇敵的頸項；你父親的兒子們必向你下拜。","notes":[]},{"n":9,"t":"猶大是個小獅子；我兒啊，你抓了食便上去。你屈下身去，臥如公獅，蹲如母獅，誰敢惹你？","notes":[]},{"n":10,"t":"圭必不離猶大，杖必不離他兩腳之間，直等細羅來到，萬民都必歸順。","notes":["就是賜平安者"]},{"n":11,"t":"猶大把小驢拴在葡萄樹上，把驢駒拴在美好的葡萄樹上。他在葡萄酒中洗了衣服，在葡萄汁中洗了袍褂。","notes":[]},{"n":12,"t":"他的眼睛必因酒紅潤；他的牙齒必因奶白亮。","notes":[]},{"n":13,"t":"西布倫必住在海口，必成為停船的海口；他的境界必延到西頓。","notes":[]},{"n":14,"t":"以薩迦是個強壯的驢，臥在羊圈之中。","notes":[]},{"n":15,"t":"他以安靜為佳，以肥地為美，便低肩背重，成為服苦的僕人。","notes":[]},{"n":16,"t":"但必判斷他的民，作以色列支派之一。","notes":[]},{"n":17,"t":"但必作道上的蛇，路中的虺，咬傷馬蹄，使騎馬的墜落於後。","notes":[]},{"n":18,"t":"耶和華啊，我向來等候你的救恩。","notes":[]},{"n":19,"t":"迦得必被敵軍追逼，他卻要追逼他們的腳跟。","notes":[]},{"n":20,"t":"亞設之地必出肥美的糧食，且出君王的美味。","notes":[]},{"n":21,"t":"拿弗他利是被釋放的母鹿；他出嘉美的言語。","notes":[]},{"n":22,"t":"約瑟是多結果子的樹枝，是泉旁多結果的枝子；他的枝條探出牆外。","notes":[]},{"n":23,"t":"弓箭手將他苦害，向他射箭，逼迫他。","notes":[]},{"n":24,"t":"但他的弓仍舊堅硬；他的手健壯敏捷。這是因以色列的牧者，以色列的磐石－就是雅各的大能者。","notes":[]},{"n":25,"t":"你父親的神必幫助你；那全能者必將天上所有的福，地裏所藏的福，以及生產乳養的福，都賜給你。","notes":[]},{"n":26,"t":"你父親所祝的福勝過我祖先所祝的福，如永世的山嶺，至極的邊界；這些福必降在約瑟的頭上，臨到那與弟兄迥別之人的頂上。","notes":[]},{"n":27,"t":"便雅憫是個撕掠的狼，早晨要吃他所抓的，晚上要分他所奪的。」","notes":[]},{"n":28,"t":"這一切是以色列的十二支派；這也是他們的父親對他們所說的話，為他們所祝的福，都是按著各人的福分為他們祝福。","notes":[]},{"n":29,"t":"他又囑咐他們說：「我將要歸到我列祖那裏，你們要將我葬在赫人以弗崙田間的洞裏，與我祖我父在一處，","notes":["原文是本民"],"heads":["雅各的死和埋葬"]},{"n":30,"t":"就是在迦南地幔利前、麥比拉田間的洞；那洞和田是亞伯拉罕向赫人以弗崙買來為業，作墳地的。","notes":[]},{"n":31,"t":"他們在那裏葬了亞伯拉罕和他妻子撒拉，又在那裏葬了以撒和他的妻子利百加；我也在那裏葬了利亞。","notes":[]},{"n":32,"t":"那塊田和田間的洞原是向赫人買的。」","notes":[]},{"n":33,"t":"雅各囑咐眾子已畢，就把腳收在床上，氣絕而死，歸他列祖那裏去了。","notes":["原文是本民"]}]},"50":{"heading":"約瑟安慰哥哥們","verses":[{"n":1,"t":"約瑟伏在他父親的面上哀哭，與他親嘴。","notes":[]},{"n":2,"t":"約瑟吩咐伺候他的醫生用香料薰他父親，醫生就用香料薰了以色列。","notes":[]},{"n":3,"t":"薰屍的常例是四十天；那四十天滿了，埃及人為他哀哭了七十天。","notes":[]},{"n":4,"t":"為他哀哭的日子過了，約瑟對法老家中的人說：「我若在你們眼前蒙恩，請你們報告法老說：","notes":[]},{"n":5,"t":"『我父親要死的時候叫我起誓說：你要將我葬在迦南地，在我為自己所掘的墳墓裏。』現在求你讓我上去葬我父親，以後我必回來。」","notes":[]},{"n":6,"t":"法老說：「你可以上去，照著你父親叫你起的誓，將他葬埋。」","notes":[]},{"n":7,"t":"於是約瑟上去葬他父親。與他一同上去的，有法老的臣僕和法老家中的長老，並埃及國的長老，","notes":[]},{"n":8,"t":"還有約瑟的全家和他的弟兄們，並他父親的眷屬；只有他們的婦人孩子，和羊群牛群，都留在歌珊地。","notes":[]},{"n":9,"t":"又有車輛馬兵，和他一同上去；那一幫人甚多。","notes":[]},{"n":10,"t":"他們到了約旦河外、亞達的禾場，就在那裏大大地號咷痛哭。約瑟為他父親哀哭了七天。","notes":[]},{"n":11,"t":"迦南的居民見亞達禾場上的哀哭，就說：「這是埃及人一場極大的哀哭。」因此那地方名叫亞伯‧麥西，是在約旦河東。","notes":[]},{"n":12,"t":"雅各的兒子們就遵著他父親所吩咐的辦了，","notes":[]},{"n":13,"t":"把他搬到迦南地，葬在幔利前、麥比拉田間的洞裏；那洞和田是亞伯拉罕向赫人以弗崙買來為業，作墳地的。","notes":[]},{"n":14,"t":"約瑟葬了他父親以後，就和眾弟兄，並一切同他上去葬他父親的人，都回埃及去了。","notes":[]},{"n":15,"t":"約瑟的哥哥們見父親死了，就說：「或者約瑟懷恨我們，照著我們從前待他一切的惡足足地報復我們。」","notes":[]},{"n":16,"t":"他們就打發人去見約瑟，說：「你父親未死以先吩咐說：","notes":[]},{"n":17,"t":"『你們要對約瑟這樣說：從前你哥哥們惡待你，求你饒恕他們的過犯和罪惡。』如今求你饒恕你父親神之僕人的過犯。」他們對約瑟說這話，約瑟就哭了。","notes":[]},{"n":18,"t":"他的哥哥們又來俯伏在他面前，說：「我們是你的僕人。」","notes":[]},{"n":19,"t":"約瑟對他們說：「不要害怕，我豈能代替神呢？","notes":[]},{"n":20,"t":"從前你們的意思是要害我，但神的意思原是好的，要保全許多人的性命，成就今日的光景。","notes":[]},{"n":21,"t":"現在你們不要害怕，我必養活你們和你們的婦人孩子。」於是約瑟用親愛的話安慰他們。","notes":[]},{"n":22,"t":"約瑟和他父親的眷屬都住在埃及。約瑟活了一百一十歲。","notes":[],"heads":["約瑟的死"]},{"n":23,"t":"約瑟得見以法蓮第三代的子孫。瑪拿西的孫子、瑪吉的兒子也養在約瑟的膝上。","notes":[]},{"n":24,"t":"約瑟對他弟兄們說：「我要死了，但神必定看顧你們，領你們從這地上去，到他起誓所應許給亞伯拉罕、以撒、雅各之地。」","notes":[]},{"n":25,"t":"約瑟叫以色列的子孫起誓說：「神必定看顧你們；你們要把我的骸骨從這裏搬上去。」","notes":[]},{"n":26,"t":"約瑟死了，正一百一十歲。人用香料將他薰了，把他收殮在棺材裏，停在埃及。","notes":[]}]}},"EXO":{"1":{"heading":"以色列人在埃及受虐待","verses":[{"n":1,"t":"以色列的眾子，各帶家眷，和雅各一同來到埃及。他們的名字記在下面。","notes":[]},{"n":2,"t":"有呂便、西緬、利未、猶大、","notes":[]},{"n":3,"t":"以薩迦、西布倫、便雅憫、","notes":[]},{"n":4,"t":"但、拿弗他利、迦得、亞設。","notes":[]},{"n":5,"t":"凡從雅各而生的，共有七十人。約瑟已經在埃及。","notes":[]},{"n":6,"t":"約瑟和他的弟兄，並那一代的人，都死了。","notes":[]},{"n":7,"t":"以色列人生養眾多，並且繁茂，極其強盛，滿了那地。","notes":[]},{"n":8,"t":"有不認識約瑟的新王起來，治理埃及，","notes":[]},{"n":9,"t":"對他的百姓說：「看哪，這以色列民比我們還多，又比我們強盛。","notes":[]},{"n":10,"t":"來吧，我們不如用巧計待他們，恐怕他們多起來，日後若遇甚麼爭戰的事，就連合我們的仇敵攻擊我們，離開這地去了。」","notes":[]},{"n":11,"t":"於是埃及人派督工的轄制他們，加重擔苦害他們。他們為法老建造兩座積貨城，就是比東和蘭塞。","notes":[]},{"n":12,"t":"只是越發苦害他們，他們越發多起來，越發蔓延；埃及人就因以色列人愁煩。","notes":[]},{"n":13,"t":"埃及人嚴嚴地使以色列人做工，","notes":[]},{"n":14,"t":"使他們因做苦工覺得命苦；無論是和泥，是做磚，是做田間各樣的工，在一切的工上都嚴嚴地待他們。","notes":[]},{"n":15,"t":"有希伯來的兩個收生婆，一名施弗拉，一名普阿；埃及王對她們說：","notes":[]},{"n":16,"t":"「你們為希伯來婦人收生，看她們臨盆的時候，若是男孩，就把他殺了；若是女孩，就留她存活。」","notes":[]},{"n":17,"t":"但是收生婆敬畏神，不照埃及王的吩咐行，竟存留男孩的性命。","notes":[]},{"n":18,"t":"埃及王召了收生婆來，說：「你們為甚麼做這事，存留男孩的性命呢？」","notes":[]},{"n":19,"t":"收生婆對法老說：「因為希伯來婦人與埃及婦人不同；希伯來婦人本是健壯的，收生婆還沒有到，她們已經生產了。」","notes":["原文是活潑的"]},{"n":20,"t":"神厚待收生婆。以色列人多起來，極其強盛。","notes":[]},{"n":21,"t":"收生婆因為敬畏神，神便叫她們成立家室。","notes":[]},{"n":22,"t":"法老吩咐他的眾民說：「以色列人所生的男孩，你們都要丟在河裏；一切的女孩，你們要存留她的性命。」","notes":[]}]},"2":{"heading":"摩西的出生","verses":[{"n":1,"t":"有一個利未家的人娶了一個利未女子為妻。","notes":[]},{"n":2,"t":"那女人懷孕，生一個兒子，見他俊美，就藏了他三個月，","notes":[]},{"n":3,"t":"後來不能再藏，就取了一個蒲草箱，抹上石漆和石油，將孩子放在裏頭，把箱子擱在河邊的蘆荻中。","notes":[]},{"n":4,"t":"孩子的姊姊遠遠站著，要知道他究竟怎麼樣。","notes":[]},{"n":5,"t":"法老的女兒來到河邊洗澡，她的使女們在河邊行走。她看見箱子在蘆荻中，就打發一個婢女拿來。","notes":[]},{"n":6,"t":"她打開箱子，看見那孩子。孩子哭了，她就可憐他，說：「這是希伯來人的一個孩子。」","notes":[]},{"n":7,"t":"孩子的姊姊對法老的女兒說：「我去在希伯來婦人中叫一個奶媽來，為你奶這孩子，可以不可以？」","notes":[]},{"n":8,"t":"法老的女兒說：「可以。」童女就去叫了孩子的母親來。","notes":[]},{"n":9,"t":"法老的女兒對她說：「你把這孩子抱去，為我奶他，我必給你工價。」婦人就抱了孩子去奶他。","notes":[]},{"n":10,"t":"孩子漸長，婦人把他帶到法老的女兒那裏，就作了她的兒子。她給孩子起名叫摩西，意思說：「因我把他從水裏拉出來。」","notes":[]},{"n":11,"t":"後來，摩西長大，他出去到他弟兄那裏，看他們的重擔，見一個埃及人打希伯來人的一個弟兄。","notes":[],"heads":["摩西逃往米甸"]},{"n":12,"t":"他左右觀看，見沒有人，就把埃及人打死了，藏在沙土裏。","notes":[]},{"n":13,"t":"第二天他出去，見有兩個希伯來人爭鬥，就對那欺負人的說：「你為甚麼打你同族的人呢？」","notes":[]},{"n":14,"t":"那人說：「誰立你作我們的首領和審判官呢？難道你要殺我，像殺那埃及人嗎？」摩西便懼怕，說：「這事必是被人知道了。」","notes":[]},{"n":15,"t":"法老聽見這事，就想殺摩西，但摩西躲避法老，逃往米甸地居住。","notes":[]},{"n":16,"t":"一日，他在井旁坐下。米甸的祭司有七個女兒；她們來打水，打滿了槽，要飲父親的群羊。","notes":[]},{"n":17,"t":"有牧羊的人來，把她們趕走了，摩西卻起來幫助她們，又飲了她們的群羊。","notes":[]},{"n":18,"t":"她們來到父親流珥那裏；他說：「今日你們為何來得這麼快呢？」","notes":[]},{"n":19,"t":"她們說：「有一個埃及人救我們脫離牧羊人的手，並且為我們打水飲了群羊。」","notes":[]},{"n":20,"t":"他對女兒們說：「那個人在哪裏？你們為甚麼撇下他呢？你們去請他來吃飯。」","notes":[]},{"n":21,"t":"摩西甘心和那人同住；那人把他的女兒西坡拉給摩西為妻。","notes":[]},{"n":22,"t":"西坡拉生了一個兒子，摩西給他起名叫革舜，意思說：「因我在外邦作了寄居的。」","notes":[]},{"n":23,"t":"過了多年，埃及王死了。以色列人因做苦工，就歎息哀求，他們的哀聲達於神。","notes":[]},{"n":24,"t":"神聽見他們的哀聲，就記念他與亞伯拉罕、以撒、雅各所立的約。","notes":[]},{"n":25,"t":"神看顧以色列人，也知道他們的苦情。","notes":[]}]},"3":{"heading":"神呼召摩西","verses":[{"n":1,"t":"摩西牧養他岳父米甸祭司葉忒羅的羊群；一日領羊群往野外去，到了神的山，就是何烈山。","notes":[]},{"n":2,"t":"耶和華的使者從荊棘裏火焰中向摩西顯現。摩西觀看，不料，荊棘被火燒著，卻沒有燒毀。","notes":[]},{"n":3,"t":"摩西說：「我要過去看這大異象，這荊棘為何沒有燒壞呢？」","notes":[]},{"n":4,"t":"耶和華神見他過去要看，就從荊棘裏呼叫說：「摩西！摩西！」他說：「我在這裏。」","notes":[]},{"n":5,"t":"神說：「不要近前來。當把你腳上的鞋脫下來，因為你所站之地是聖地」；","notes":[]},{"n":6,"t":"又說：「我是你父親的神，是亞伯拉罕的神，以撒的神，雅各的神。」摩西蒙上臉，因為怕看神。","notes":[]},{"n":7,"t":"耶和華說：「我的百姓在埃及所受的困苦，我實在看見了；他們因受督工的轄制所發的哀聲，我也聽見了。我原知道他們的痛苦，","notes":[]},{"n":8,"t":"我下來是要救他們脫離埃及人的手，領他們出了那地，到美好、寬闊、流奶與蜜之地，就是到迦南人、赫人、亞摩利人、比利洗人、希未人、耶布斯人之地。","notes":[]},{"n":9,"t":"現在以色列人的哀聲達到我耳中，我也看見埃及人怎樣欺壓他們。","notes":[]},{"n":10,"t":"故此，我要打發你去見法老，使你可以將我的百姓以色列人從埃及領出來。」","notes":[]},{"n":11,"t":"摩西對神說：「我是甚麼人，竟能去見法老，將以色列人從埃及領出來呢？」","notes":[]},{"n":12,"t":"神說：「我必與你同在。你將百姓從埃及領出來之後，你們必在這山上事奉我；這就是我打發你去的證據。」","notes":[]},{"n":13,"t":"摩西對神說：「我到以色列人那裏，對他們說：『你們祖宗的神打發我到你們這裏來。』他們若問我說：『他叫甚麼名字？』我要對他們說甚麼呢？」","notes":[]},{"n":14,"t":"神對摩西說：「我是自有永有的」；又說：「你要對以色列人這樣說：『那自有的打發我到你們這裏來。』」","notes":[]},{"n":15,"t":"神又對摩西說：「你要對以色列人這樣說：『耶和華－你們祖宗的神，就是亞伯拉罕的神，以撒的神，雅各的神，打發我到你們這裏來。』耶和華是我的名，直到永遠；這也是我的紀念，直到萬代。","notes":[]},{"n":16,"t":"你去招聚以色列的長老，對他們說：『耶和華－你們祖宗的神，就是亞伯拉罕的神，以撒的神，雅各的神，向我顯現，說：我實在眷顧了你們，我也看見埃及人怎樣待你們。","notes":[]},{"n":17,"t":"我也說：要將你們從埃及的困苦中領出來，往迦南人、赫人、亞摩利人、比利洗人、希未人、耶布斯人的地去，就是到流奶與蜜之地。』","notes":[]},{"n":18,"t":"他們必聽你的話。你和以色列的長老要去見埃及王，對他說：『耶和華－希伯來人的神遇見了我們，現在求你容我們往曠野去，走三天的路程，為要祭祀耶和華－我們的神。』","notes":[]},{"n":19,"t":"我知道雖用大能的手，埃及王也不容你們去。","notes":[]},{"n":20,"t":"我必伸手在埃及中間施行我一切的奇事，攻擊那地，然後他才容你們去。","notes":[]},{"n":21,"t":"我必叫你們在埃及人眼前蒙恩，你們去的時候就不至於空手而去。","notes":[]},{"n":22,"t":"但各婦女必向她的鄰舍，並居住在她家裏的女人，要金器銀器和衣裳，好給你們的兒女穿戴。這樣你們就把埃及人的財物奪去了。」","notes":[]}]},"4":{"heading":"神賜摩西行神蹟的權能","verses":[{"n":1,"t":"摩西回答說：「他們必不信我，也不聽我的話，必說：『耶和華並沒有向你顯現。』」","notes":[]},{"n":2,"t":"耶和華對摩西說：「你手裏是甚麼？」他說：「是杖。」","notes":[]},{"n":3,"t":"耶和華說：「丟在地上。」他一丟下去，就變作蛇；摩西便跑開。","notes":[]},{"n":4,"t":"耶和華對摩西說：「伸出手來，拿住牠的尾巴，牠必在你手中仍變為杖；","notes":[]},{"n":5,"t":"如此好叫他們信耶和華－他們祖宗的神，就是亞伯拉罕的神，以撒的神，雅各的神，是向你顯現了。」","notes":[]},{"n":6,"t":"耶和華又對他說：「把手放在懷裏。」他就把手放在懷裏，及至抽出來，不料，手長了大痲瘋，有雪那樣白。","notes":[]},{"n":7,"t":"耶和華說：「再把手放在懷裏。」他就再把手放在懷裏，及至從懷裏抽出來，不料，手已經復原，與周身的肉一樣；","notes":[]},{"n":8,"t":"又說：「倘或他們不聽你的話，也不信頭一個神蹟，他們必信第二個神蹟。","notes":[]},{"n":9,"t":"這兩個神蹟若都不信，也不聽你的話，你就從河裏取些水，倒在旱地上，你從河裏取的水必在旱地上變作血。」","notes":[]},{"n":10,"t":"摩西對耶和華說：「主啊，我素日不是能言的人，就是從你對僕人說話以後，也是這樣。我本是拙口笨舌的。」","notes":[]},{"n":11,"t":"耶和華對他說：「誰造人的口呢？誰使人口啞、耳聾、目明、眼瞎呢？豈不是我－耶和華嗎？","notes":[]},{"n":12,"t":"現在去吧，我必賜你口才，指教你所當說的話。」","notes":[]},{"n":13,"t":"摩西說：「主啊，你願意打發誰，就打發誰去吧！」","notes":[]},{"n":14,"t":"耶和華向摩西發怒說：「不是有你的哥哥利未人亞倫嗎？我知道他是能言的；現在他出來迎接你，他一見你，心裏就歡喜。","notes":[]},{"n":15,"t":"你要將當說的話傳給他；我也要賜你和他口才，又要指教你們所當行的事。","notes":[]},{"n":16,"t":"他要替你對百姓說話；你要以他當作口，他要以你當作神。","notes":[]},{"n":17,"t":"你手裏要拿這杖，好行神蹟。」","notes":[]},{"n":18,"t":"於是，摩西回到他岳父葉忒羅那裏，對他說：「求你容我回去見我在埃及的弟兄，看他們還在不在。」葉忒羅對摩西說：「你可以平平安安地去吧！」","notes":[],"heads":["摩西返回埃及"]},{"n":19,"t":"耶和華在米甸對摩西說：「你要回埃及去，因為尋索你命的人都死了。」","notes":[]},{"n":20,"t":"摩西就帶著妻子和兩個兒子，叫他們騎上驢，回埃及地去。摩西手裏拿著神的杖。","notes":[]},{"n":21,"t":"耶和華對摩西說：「你回到埃及的時候，要留意將我指示你的一切奇事行在法老面前。但我要使他的心剛硬，他必不容百姓去。","notes":["或譯：任憑；下同"]},{"n":22,"t":"你要對法老說：『耶和華這樣說：以色列是我的兒子，我的長子。","notes":[]},{"n":23,"t":"我對你說過：容我的兒子去，好事奉我。你還是不肯容他去。看哪，我要殺你的長子。』」","notes":[]},{"n":24,"t":"摩西在路上住宿的地方，耶和華遇見他，想要殺他。","notes":[]},{"n":25,"t":"西坡拉就拿一塊火石，割下他兒子的陽皮，丟在摩西腳前，說：「你真是我的血郎了。」","notes":[]},{"n":26,"t":"這樣，耶和華才放了他。西坡拉說：「你因割禮就是血郎了。」","notes":[]},{"n":27,"t":"耶和華對亞倫說：「你往曠野去迎接摩西。」他就去，在神的山遇見摩西，和他親嘴。","notes":[]},{"n":28,"t":"摩西將耶和華打發他所說的言語和囑咐他所行的神蹟都告訴了亞倫。","notes":[]},{"n":29,"t":"摩西、亞倫就去招聚以色列的眾長老。","notes":[]},{"n":30,"t":"亞倫將耶和華對摩西所說的一切話述說了一遍，又在百姓眼前行了那些神蹟，","notes":[]},{"n":31,"t":"百姓就信了。以色列人聽見耶和華眷顧他們，鑒察他們的困苦，就低頭下拜。","notes":[]}]},"5":{"heading":"摩西和亞倫見埃及王","verses":[{"n":1,"t":"後來摩西、亞倫去對法老說：「耶和華－以色列的神這樣說：『容我的百姓去，在曠野向我守節。』」","notes":[]},{"n":2,"t":"法老說：「耶和華是誰，使我聽他的話，容以色列人去呢？我不認識耶和華，也不容以色列人去！」","notes":[]},{"n":3,"t":"他們說：「希伯來人的神遇見了我們。求你容我們往曠野去，走三天的路程，祭祀耶和華－我們的神，免得他用瘟疫、刀兵攻擊我們。」","notes":[]},{"n":4,"t":"埃及王對他們說：「摩西、亞倫！你們為甚麼叫百姓曠工呢？你們去擔你們的擔子吧！」","notes":[]},{"n":5,"t":"又說：「看哪，這地的以色列人如今眾多，你們竟叫他們歇下擔子！」","notes":[]},{"n":6,"t":"當天，法老吩咐督工的和官長說：","notes":[]},{"n":7,"t":"「你們不可照常把草給百姓做磚，叫他們自己去撿草。","notes":[]},{"n":8,"t":"他們素常做磚的數目，你們仍舊向他們要，一點不可減少；因為他們是懶惰的，所以呼求說：『容我們去祭祀我們的神。』","notes":[]},{"n":9,"t":"你們要把更重的工夫加在這些人身上，叫他們勞碌，不聽虛謊的言語。」","notes":[]},{"n":10,"t":"督工的和官長出來對百姓說：「法老這樣說：『我不給你們草。","notes":[]},{"n":11,"t":"你們自己在哪裏能找草，就往那裏去找吧！但你們的工一點不可減少。』」","notes":[]},{"n":12,"t":"於是百姓散在埃及遍地，撿碎稭當作草。","notes":[]},{"n":13,"t":"督工的催著說：「你們一天當完一天的工，與先前有草一樣。」","notes":[]},{"n":14,"t":"法老督工的，責打他所派以色列人的官長，說：「你們昨天今天為甚麼沒有照向來的數目做磚、完你們的工作呢？」","notes":[]},{"n":15,"t":"以色列人的官長就來哀求法老說：「為甚麼這樣待你的僕人？","notes":[]},{"n":16,"t":"督工的不把草給僕人，並且對我們說：『做磚吧！』看哪，你僕人挨了打，其實是你百姓的錯。」","notes":[]},{"n":17,"t":"但法老說：「你們是懶惰的！你們是懶惰的！所以說：『容我們去祭祀耶和華。』","notes":[]},{"n":18,"t":"現在你們去做工吧！草是不給你們的，磚卻要如數交納。」","notes":[]},{"n":19,"t":"以色列人的官長聽說「你們每天做磚的工作一點不可減少」，就知道是遭遇禍患了。","notes":[]},{"n":20,"t":"他們離了法老出來，正遇見摩西、亞倫站在對面，","notes":[]},{"n":21,"t":"就向他們說：「願耶和華鑒察你們，施行判斷；因你們使我們在法老和他臣僕面前有了臭名，把刀遞在他們手中殺我們。」","notes":[]},{"n":22,"t":"摩西回到耶和華那裏，說：「主啊，你為甚麼苦待這百姓呢？為甚麼打發我去呢？","notes":[],"heads":["摩西向耶和華訴苦"]},{"n":23,"t":"自從我去見法老，奉你的名說話，他就苦待這百姓，你一點也沒有拯救他們。」","notes":[]}]},"6":{"heading":"神呼召摩西","verses":[{"n":1,"t":"耶和華對摩西說：「現在你必看見我向法老所行的事，使他因我大能的手容以色列人去，且把他們趕出他的地。」","notes":[]},{"n":2,"t":"神曉諭摩西說：「我是耶和華。","notes":[]},{"n":3,"t":"我從前向亞伯拉罕、以撒、雅各顯現為全能的神；至於我名耶和華，他們未曾知道。","notes":[]},{"n":4,"t":"我與他們堅定所立的約，要把他們寄居的迦南地賜給他們。","notes":[]},{"n":5,"t":"我也聽見以色列人被埃及人苦待的哀聲，我也記念我的約。","notes":[]},{"n":6,"t":"所以你要對以色列人說：『我是耶和華；我要用伸出來的膀臂重重地刑罰埃及人，救贖你們脫離他們的重擔，不做他們的苦工。","notes":[]},{"n":7,"t":"我要以你們為我的百姓，我也要作你們的神。你們要知道我是耶和華－你們的神，是救你們脫離埃及人之重擔的。","notes":[]},{"n":8,"t":"我起誓應許給亞伯拉罕、以撒、雅各的那地，我要把你們領進去，將那地賜給你們為業。我是耶和華。』」","notes":[]},{"n":9,"t":"摩西將這話告訴以色列人，只是他們因苦工愁煩，不肯聽他的話。","notes":[]},{"n":10,"t":"耶和華曉諭摩西說：","notes":[]},{"n":11,"t":"「你進去對埃及王法老說，要容以色列人出他的地。」","notes":[]},{"n":12,"t":"摩西在耶和華面前說：「以色列人尚且不聽我的話，法老怎肯聽我這拙口笨舌的人呢？」","notes":[]},{"n":13,"t":"耶和華吩咐摩西、亞倫往以色列人和埃及王法老那裏去，把以色列人從埃及地領出來。","notes":[]},{"n":14,"t":"以色列人家長的名字記在下面。以色列長子呂便的兒子是哈諾、法路、希斯倫、迦米；這是呂便的各家。","notes":[],"heads":["摩西和亞倫的族譜"]},{"n":15,"t":"西緬的兒子是耶母利、雅憫、阿轄、雅斤、瑣轄，和迦南女子的兒子掃羅；這是西緬的各家。","notes":[]},{"n":16,"t":"利未眾子的名字按著他們的後代記在下面：就是革順、哥轄、米拉利。利未一生的歲數是一百三十七歲。","notes":[]},{"n":17,"t":"革順的兒子按著家室是立尼、示每。","notes":[]},{"n":18,"t":"哥轄的兒子是暗蘭、以斯哈、希伯倫、烏薛。哥轄一生的歲數是一百三十三歲。","notes":[]},{"n":19,"t":"米拉利的兒子是抹利和母示；這是利未的家，都按著他們的後代。","notes":[]},{"n":20,"t":"暗蘭娶了他父親的妹妹約基別為妻，她給他生了亞倫和摩西。暗蘭一生的歲數是一百三十七歲。","notes":[]},{"n":21,"t":"以斯哈的兒子是可拉、尼斐、細基利。","notes":[]},{"n":22,"t":"烏薛的兒子是米沙利、以利撒反、西提利。","notes":[]},{"n":23,"t":"亞倫娶了亞米拿達的女兒，拿順的妹妹，以利沙巴為妻，她給他生了拿答、亞比戶、以利亞撒、以他瑪。","notes":[]},{"n":24,"t":"可拉的兒子是亞惜、以利加拿、亞比亞撒；這是可拉的各家。","notes":[]},{"n":25,"t":"亞倫的兒子以利亞撒娶了普鐵的一個女兒為妻，她給他生了非尼哈。這是利未人的家長，都按著他們的家。","notes":[]},{"n":26,"t":"耶和華說：「將以色列人按著他們的軍隊從埃及地領出來。」這是對那亞倫、摩西說的。","notes":[]},{"n":27,"t":"對埃及王法老說要將以色列人從埃及領出來的，就是這摩西、亞倫。","notes":[]},{"n":28,"t":"當耶和華在埃及地對摩西說話的日子，","notes":[],"heads":["耶和華吩咐摩西和亞倫"]},{"n":29,"t":"他向摩西說：「我是耶和華；我對你說的一切話，你都要告訴埃及王法老。」","notes":[]},{"n":30,"t":"摩西在耶和華面前說：「看哪，我是拙口笨舌的人，法老怎肯聽我呢？」","notes":[]}]},"7":{"heading":"亞倫的杖","verses":[{"n":1,"t":"耶和華對摩西說：「我使你在法老面前代替神，你的哥哥亞倫是替你說話的。","notes":[]},{"n":2,"t":"凡我所吩咐你的，你都要說。你的哥哥亞倫要對法老說，容以色列人出他的地。","notes":[]},{"n":3,"t":"我要使法老的心剛硬，也要在埃及地多行神蹟奇事。","notes":[]},{"n":4,"t":"但法老必不聽你們；我要伸手重重地刑罰埃及，將我的軍隊以色列民從埃及地領出來。","notes":[]},{"n":5,"t":"我伸手攻擊埃及，將以色列人從他們中間領出來的時候，埃及人就要知道我是耶和華。」","notes":[]},{"n":6,"t":"摩西、亞倫這樣行；耶和華怎樣吩咐他們，他們就照樣行了。","notes":[]},{"n":7,"t":"摩西、亞倫與法老說話的時候，摩西八十歲，亞倫八十三歲。","notes":[]},{"n":8,"t":"耶和華曉諭摩西、亞倫說：","notes":[]},{"n":9,"t":"「法老若對你們說：『你們行件奇事吧！』你就吩咐亞倫說：『把杖丟在法老面前，使杖變作蛇。』」","notes":[]},{"n":10,"t":"摩西、亞倫進去見法老，就照耶和華所吩咐的行。亞倫把杖丟在法老和臣僕面前，杖就變作蛇。","notes":[]},{"n":11,"t":"於是法老召了博士和術士來；他們是埃及行法術的，也用邪術照樣而行。","notes":[]},{"n":12,"t":"他們各人丟下自己的杖，杖就變作蛇；但亞倫的杖吞了他們的杖。","notes":[]},{"n":13,"t":"法老心裏剛硬，不肯聽從摩西、亞倫，正如耶和華所說的。","notes":[]},{"n":14,"t":"耶和華對摩西說：「法老心裏固執，不肯容百姓去。","notes":[],"heads":["埃及遭災－血災"]},{"n":15,"t":"明日早晨，他出來往水邊去，你要往河邊迎接他，手裏要拿著那變過蛇的杖，","notes":[]},{"n":16,"t":"對他說：『耶和華－希伯來人的神打發我來見你，說：容我的百姓去，好在曠野事奉我。到如今你還是不聽。","notes":[]},{"n":17,"t":"耶和華這樣說：我要用我手裏的杖擊打河中的水，水就變作血；因此，你必知道我是耶和華。","notes":[]},{"n":18,"t":"河裏的魚必死，河也要腥臭，埃及人就要厭惡吃這河裏的水。』」","notes":[]},{"n":19,"t":"耶和華曉諭摩西說：「你對亞倫說：『把你的杖伸在埃及所有的水以上，就是在他們的江、河、池、塘以上，叫水都變作血。在埃及遍地，無論在木器中，石器中，都必有血。』」","notes":[]},{"n":20,"t":"摩西、亞倫就照耶和華所吩咐的行。亞倫在法老和臣僕眼前舉杖擊打河裏的水，河裏的水都變作血了。","notes":[]},{"n":21,"t":"河裏的魚死了，河也腥臭了，埃及人就不能吃這河裏的水；埃及遍地都有了血。","notes":[]},{"n":22,"t":"埃及行法術的，也用邪術照樣而行。法老心裏剛硬，不肯聽摩西、亞倫，正如耶和華所說的。","notes":[]},{"n":23,"t":"法老轉身進宮，也不把這事放在心上。","notes":[]},{"n":24,"t":"埃及人都在河的兩邊挖地，要得水喝，因為他們不能喝這河裏的水。","notes":[]},{"n":25,"t":"耶和華擊打河以後滿了七天。","notes":[]}]},"8":{"heading":"－蛙災","verses":[{"n":1,"t":"耶和華吩咐摩西說：「你進去見法老，對他說：『耶和華這樣說：容我的百姓去，好事奉我。","notes":[]},{"n":2,"t":"你若不肯容他們去，我必使青蛙糟蹋你的四境。","notes":[]},{"n":3,"t":"河裏要滋生青蛙；這青蛙要上來進你的宮殿和你的臥房，上你的床榻，進你臣僕的房屋，上你百姓的身上，進你的爐竈和你的摶麵盆，","notes":[]},{"n":4,"t":"又要上你和你百姓並你眾臣僕的身上。』」","notes":[]},{"n":5,"t":"耶和華曉諭摩西說：「你對亞倫說：『把你的杖伸在江、河、池以上，使青蛙到埃及地上來。』」","notes":[]},{"n":6,"t":"亞倫便伸杖在埃及的諸水以上，青蛙就上來，遮滿了埃及地。","notes":[]},{"n":7,"t":"行法術的也用他們的邪術照樣而行，叫青蛙上了埃及地。","notes":[]},{"n":8,"t":"法老召了摩西、亞倫來，說：「請你們求耶和華使這青蛙離開我和我的民，我就容百姓去祭祀耶和華。」","notes":[]},{"n":9,"t":"摩西對法老說：「任憑你吧，我要何時為你和你的臣僕並你的百姓祈求，除滅青蛙離開你和你的宮殿只留在河裏呢？」","notes":[]},{"n":10,"t":"他說：「明天。」摩西說：「可以照你的話吧，好叫你知道沒有像耶和華－我們神的。","notes":[]},{"n":11,"t":"青蛙要離開你和你的宮殿，並你的臣僕與你的百姓，只留在河裏。」","notes":[]},{"n":12,"t":"於是摩西、亞倫離開法老出去。摩西為擾害法老的青蛙呼求耶和華。","notes":[]},{"n":13,"t":"耶和華就照摩西的話行。凡在房裏、院中、田間的青蛙都死了。","notes":[]},{"n":14,"t":"眾人把青蛙聚攏成堆，遍地就都腥臭。","notes":[]},{"n":15,"t":"但法老見災禍鬆緩，就硬著心，不肯聽他們，正如耶和華所說的。","notes":[]},{"n":16,"t":"耶和華吩咐摩西說：「你對亞倫說：『伸出你的杖擊打地上的塵土，使塵土在埃及遍地變作虱子。』」","notes":["或譯：虼蚤；下同"],"heads":["－虱災"]},{"n":17,"t":"他們就這樣行。亞倫伸杖擊打地上的塵土，就在人身上和牲畜身上有了虱子；埃及遍地的塵土都變成虱子了。","notes":[]},{"n":18,"t":"行法術的也用邪術要生出虱子來，卻是不能。於是在人身上和牲畜身上都有了虱子。","notes":[]},{"n":19,"t":"行法術的就對法老說：「這是神的手段。」法老心裏剛硬，不肯聽摩西、亞倫，正如耶和華所說的。","notes":[]},{"n":20,"t":"耶和華對摩西說：「你清早起來，法老來到水邊，你站在他面前，對他說：『耶和華這樣說：容我的百姓去，好事奉我。","notes":[],"heads":["－蠅災"]},{"n":21,"t":"你若不容我的百姓去，我要叫成群的蒼蠅到你和你臣僕並你百姓的身上，進你的房屋，並且埃及人的房屋和他們所住的地都要滿了成群的蒼蠅。","notes":[]},{"n":22,"t":"當那日，我必分別我百姓所住的歌珊地，使那裏沒有成群的蒼蠅，好叫你知道我是天下的耶和華。","notes":[]},{"n":23,"t":"我要將我的百姓和你的百姓分別出來。明天必有這神蹟。』」","notes":[]},{"n":24,"t":"耶和華就這樣行。蒼蠅成了大群，進入法老的宮殿，和他臣僕的房屋；埃及遍地就因這成群的蒼蠅敗壞了。","notes":[]},{"n":25,"t":"法老召了摩西、亞倫來，說：「你們去，在這地祭祀你們的神吧！」","notes":[]},{"n":26,"t":"摩西說：「這樣行本不相宜，因為我們要把埃及人所厭惡的祭祀耶和華－我們的神；若把埃及人所厭惡的在他們眼前獻為祭，他們豈不拿石頭打死我們嗎？","notes":[]},{"n":27,"t":"我們要往曠野去，走三天的路程，照著耶和華－我們神所要吩咐我們的祭祀他。」","notes":[]},{"n":28,"t":"法老說：「我容你們去，在曠野祭祀耶和華－你們的神；只是不要走得很遠。求你們為我祈禱。」","notes":[]},{"n":29,"t":"摩西說：「我要出去求耶和華，使成群的蒼蠅明天離開法老和法老的臣僕並法老的百姓；法老卻不可再行詭詐，不容百姓去祭祀耶和華。」","notes":[]},{"n":30,"t":"於是摩西離開法老去求耶和華。","notes":[]},{"n":31,"t":"耶和華就照摩西的話行，叫成群的蒼蠅離開法老和他的臣僕並他的百姓，一個也沒有留下。","notes":[]},{"n":32,"t":"這一次法老又硬著心，不容百姓去。","notes":[]}]},"9":{"heading":"－畜疫之災","verses":[{"n":1,"t":"耶和華吩咐摩西說：「你進去見法老，對他說：『耶和華－希伯來人的神這樣說：容我的百姓去，好事奉我。","notes":[]},{"n":2,"t":"你若不肯容他們去，仍舊強留他們，","notes":[]},{"n":3,"t":"耶和華的手加在你田間的牲畜上，就是在馬、驢、駱駝、牛群、羊群上，必有重重的瘟疫。","notes":[]},{"n":4,"t":"耶和華要分別以色列的牲畜和埃及的牲畜，凡屬以色列人的，一樣都不死。』」","notes":[]},{"n":5,"t":"耶和華就定了時候，說：「明天耶和華必在此地行這事。」","notes":[]},{"n":6,"t":"第二天，耶和華就行這事。埃及的牲畜幾乎都死了，只是以色列人的牲畜，一個都沒有死。","notes":[]},{"n":7,"t":"法老打發人去看，誰知以色列人的牲畜連一個都沒有死。法老的心卻是固執，不容百姓去。","notes":[]},{"n":8,"t":"耶和華吩咐摩西、亞倫說：「你們取幾捧爐灰，摩西要在法老面前向天揚起來。","notes":[],"heads":["－瘡災"]},{"n":9,"t":"這灰要在埃及全地變作塵土，在人身上和牲畜身上成了起泡的瘡。」","notes":[]},{"n":10,"t":"摩西、亞倫取了爐灰，站在法老面前。摩西向天揚起來，就在人身上和牲畜身上成了起泡的瘡。","notes":[]},{"n":11,"t":"行法術的在摩西面前站立不住，因為在他們身上和一切埃及人身上都有這瘡。","notes":[]},{"n":12,"t":"耶和華使法老的心剛硬，不聽他們，正如耶和華對摩西所說的。","notes":[]},{"n":13,"t":"耶和華對摩西說：「你清早起來，站在法老面前，對他說：『耶和華－希伯來人的神這樣說：容我的百姓去，好事奉我。","notes":[],"heads":["－雹災"]},{"n":14,"t":"因為這一次我要叫一切的災殃臨到你和你臣僕並你百姓的身上，叫你知道在普天下沒有像我的。","notes":[]},{"n":15,"t":"我若伸手用瘟疫攻擊你和你的百姓，你早就從地上除滅了。","notes":[]},{"n":16,"t":"其實，我叫你存立，是特要向你顯我的大能，並要使我的名傳遍天下。","notes":[]},{"n":17,"t":"你還向我的百姓自高，不容他們去嗎？","notes":[]},{"n":18,"t":"到明天約在這時候，我必叫重大的冰雹降下，自從埃及開國以來，沒有這樣的冰雹。","notes":[]},{"n":19,"t":"現在你要打發人把你的牲畜和你田間一切所有的催進來；凡在田間不收回家的，無論是人是牲畜，冰雹必降在他們身上，他們就必死。』」","notes":[]},{"n":20,"t":"法老的臣僕中，懼怕耶和華這話的，便叫他的奴僕和牲畜跑進家來。","notes":[]},{"n":21,"t":"但那不把耶和華這話放在心上的，就將他的奴僕和牲畜留在田裏。","notes":[]},{"n":22,"t":"耶和華對摩西說：「你向天伸杖，使埃及遍地的人身上和牲畜身上，並田間各樣菜蔬上，都有冰雹。」","notes":[]},{"n":23,"t":"摩西向天伸杖，耶和華就打雷下雹，有火閃到地上；耶和華下雹在埃及地上。","notes":[]},{"n":24,"t":"那時，雹與火攙雜，甚是厲害，自從埃及成國以來，遍地沒有這樣的。","notes":[]},{"n":25,"t":"在埃及遍地，雹擊打了田間所有的人和牲畜，並一切的菜蔬，又打壞田間一切的樹木。","notes":[]},{"n":26,"t":"惟獨以色列人所住的歌珊地沒有冰雹。","notes":[]},{"n":27,"t":"法老打發人召摩西、亞倫來，對他們說：「這一次我犯了罪了。耶和華是公義的；我和我的百姓是邪惡的。","notes":[]},{"n":28,"t":"這雷轟和冰雹已經夠了。請你們求耶和華，我就容你們去，不再留住你們。」","notes":[]},{"n":29,"t":"摩西對他說：「我一出城，就要向耶和華舉手禱告；雷必止住，也不再有冰雹，叫你知道全地都是屬耶和華的。","notes":[]},{"n":30,"t":"至於你和你的臣僕，我知道你們還是不懼怕耶和華神。」（","notes":[]},{"n":31,"t":"那時，麻和大麥被雹擊打；因為大麥已經吐穗，麻也開了花。","notes":[]},{"n":32,"t":"只是小麥和粗麥沒有被擊打，因為還沒有長成。）","notes":[]},{"n":33,"t":"摩西離了法老出城，向耶和華舉手禱告；雷和雹就止住，雨也不再澆在地上了。","notes":[]},{"n":34,"t":"法老見雨和雹與雷止住，就越發犯罪；他和他的臣僕都硬著心。","notes":[]},{"n":35,"t":"法老的心剛硬，不容以色列人去，正如耶和華藉著摩西所說的。","notes":[]}]},"10":{"heading":"－蝗災","verses":[{"n":1,"t":"耶和華對摩西說：「你進去見法老。我使他和他臣僕的心剛硬，為要在他們中間顯我這些神蹟，","notes":[]},{"n":2,"t":"並要叫你將我向埃及人所做的事，和在他們中間所行的神蹟，傳於你兒子和你孫子的耳中，好叫你們知道我是耶和華。」","notes":[]},{"n":3,"t":"摩西、亞倫就進去見法老，對他說：「耶和華－希伯來人的神這樣說：『你在我面前不肯自卑要到幾時呢？容我的百姓去，好事奉我。","notes":[]},{"n":4,"t":"你若不肯容我的百姓去，明天我要使蝗蟲進入你的境內，","notes":[]},{"n":5,"t":"遮滿地面，甚至看不見地，並且吃那冰雹所剩的和田間所長的一切樹木。","notes":[]},{"n":6,"t":"你的宮殿和你眾臣僕的房屋，並一切埃及人的房屋，都要被蝗蟲佔滿了；自從你祖宗和你祖宗的祖宗在世以來，直到今日，沒有見過這樣的災。』」摩西就轉身離開法老出去。","notes":[]},{"n":7,"t":"法老的臣僕對法老說：「這人為我們的網羅要到幾時呢？容這些人去事奉耶和華－他們的神吧！埃及已經敗壞了，你還不知道嗎？」","notes":[]},{"n":8,"t":"於是摩西、亞倫被召回來見法老；法老對他們說：「你們去事奉耶和華－你們的神；但那要去的是誰呢？」","notes":[]},{"n":9,"t":"摩西說：「我們要和我們老的少的、兒子女兒同去，且把羊群牛群一同帶去，因為我們務要向耶和華守節。」","notes":[]},{"n":10,"t":"法老對他們說：「我容你們和你們婦人孩子去的時候，耶和華與你們同在吧！你們要謹慎；因為有禍在你們眼前，","notes":["或譯：你們存著惡意"]},{"n":11,"t":"不可都去！你們這壯年人去事奉耶和華吧，因為這是你們所求的。」於是把他們從法老面前攆出去。","notes":[]},{"n":12,"t":"耶和華對摩西說：「你向埃及地伸杖，使蝗蟲到埃及地上來，吃地上一切的菜蔬，就是冰雹所剩的。」","notes":[]},{"n":13,"t":"摩西就向埃及地伸杖，那一晝一夜，耶和華使東風颳在埃及地上；到了早晨，東風把蝗蟲颳了來。","notes":[]},{"n":14,"t":"蝗蟲上來，落在埃及的四境，甚是厲害；以前沒有這樣的，以後也必沒有。","notes":[]},{"n":15,"t":"因為這蝗蟲遮滿地面，甚至地都黑暗了，又吃地上一切的菜蔬和冰雹所剩樹上的果子。埃及遍地，無論是樹木，是田間的菜蔬，連一點青的也沒有留下。","notes":[]},{"n":16,"t":"於是法老急忙召了摩西、亞倫來，說：「我得罪耶和華－你們的神，又得罪了你們。","notes":[]},{"n":17,"t":"現在求你，只這一次，饒恕我的罪，求耶和華－你們的神使我脫離這一次的死亡。」","notes":[]},{"n":18,"t":"摩西就離開法老去求耶和華。","notes":[]},{"n":19,"t":"耶和華轉了極大的西風，把蝗蟲颳起，吹入紅海；在埃及的四境連一個也沒有留下。","notes":[]},{"n":20,"t":"但耶和華使法老的心剛硬，不容以色列人去。","notes":[]},{"n":21,"t":"耶和華對摩西說：「你向天伸杖，使埃及地黑暗；這黑暗似乎摸得著。」","notes":[],"heads":["－黑暗之災"]},{"n":22,"t":"摩西向天伸杖，埃及遍地就烏黑了三天。","notes":[]},{"n":23,"t":"三天之久，人不能相見，誰也不敢起來離開本處；惟有以色列人家中都有亮光。","notes":[]},{"n":24,"t":"法老就召摩西來，說：「你們去事奉耶和華；只是你們的羊群牛群要留下；你們的婦人孩子可以和你們同去。」","notes":[]},{"n":25,"t":"摩西說：「你總要把祭物和燔祭牲交給我們，使我們可以祭祀耶和華－我們的神。","notes":[]},{"n":26,"t":"我們的牲畜也要帶去，連一蹄也不留下；因為我們要從其中取出來，事奉耶和華－我們的神。我們未到那裏，還不知道用甚麼事奉耶和華。」","notes":[]},{"n":27,"t":"但耶和華使法老的心剛硬，不肯容他們去。","notes":[]},{"n":28,"t":"法老對摩西說：「你離開我去吧，你要小心，不要再見我的面！因為你見我面的那日你就必死！」","notes":[]},{"n":29,"t":"摩西說：「你說得好！我必不再見你的面了。」","notes":[]}]},"11":{"heading":"所有頭胎的都死","verses":[{"n":1,"t":"耶和華對摩西說：「我再使一樣的災殃臨到法老和埃及，然後他必容你們離開這地。他容你們去的時候，總要催逼你們都從這地出去。","notes":[]},{"n":2,"t":"你要傳於百姓的耳中，叫他們男女各人向鄰舍要金器銀器。」","notes":[]},{"n":3,"t":"耶和華叫百姓在埃及人眼前蒙恩，並且摩西在埃及地、法老臣僕，和百姓的眼中看為極大。","notes":[]},{"n":4,"t":"摩西說：「耶和華這樣說：『約到半夜，我必出去巡行埃及遍地。","notes":[]},{"n":5,"t":"凡在埃及地，從坐寶座的法老直到磨子後的婢女所有的長子，以及一切頭生的牲畜，都必死。","notes":[]},{"n":6,"t":"埃及遍地必有大哀號；從前沒有這樣的，後來也必沒有。","notes":[]},{"n":7,"t":"至於以色列中，無論是人是牲畜，連狗也不敢向他們搖舌，好叫你們知道耶和華是將埃及人和以色列人分別出來。』","notes":[]},{"n":8,"t":"你這一切臣僕都要俯伏來見我，說：『求你和跟從你的百姓都出去』，然後我要出去。」於是，摩西氣忿忿地離開法老，出去了。","notes":[]},{"n":9,"t":"耶和華對摩西說：「法老必不聽你們，使我的奇事在埃及地多起來。」","notes":[]},{"n":10,"t":"摩西、亞倫在法老面前行了這一切奇事；耶和華使法老的心剛硬，不容以色列人出離他的地。","notes":[]}]},"12":{"heading":"逾越節","verses":[{"n":1,"t":"耶和華在埃及地曉諭摩西、亞倫說：","notes":[]},{"n":2,"t":"「你們要以本月為正月，為一年之首。","notes":[]},{"n":3,"t":"你們吩咐以色列全會眾說：本月初十日，各人要按著父家取羊羔，一家一隻。","notes":[]},{"n":4,"t":"若是一家的人太少，吃不了一隻羊羔，本人就要和他隔壁的鄰舍共取一隻。你們預備羊羔，要按著人數和飯量計算。","notes":[]},{"n":5,"t":"要無殘疾、一歲的公羊羔，你們或從綿羊裏取，或從山羊裏取，都可以。","notes":[]},{"n":6,"t":"要留到本月十四日，在黃昏的時候，以色列全會眾把羊羔宰了。","notes":[]},{"n":7,"t":"各家要取點血，塗在吃羊羔的房屋左右的門框上和門楣上。","notes":[]},{"n":8,"t":"當夜要吃羊羔的肉；用火烤了，與無酵餅和苦菜同吃。","notes":[]},{"n":9,"t":"不可吃生的，斷不可吃水煮的，要帶著頭、腿、五臟，用火烤了吃。","notes":[]},{"n":10,"t":"不可剩下一點留到早晨；若留到早晨，要用火燒了。","notes":[]},{"n":11,"t":"你們吃羊羔當腰間束帶，腳上穿鞋，手中拿杖，趕緊地吃；這是耶和華的逾越節。","notes":[]},{"n":12,"t":"因為那夜我要巡行埃及地，把埃及地一切頭生的，無論是人是牲畜，都擊殺了，又要敗壞埃及一切的神。我是耶和華。","notes":[]},{"n":13,"t":"這血要在你們所住的房屋上作記號；我一見這血，就越過你們去。我擊殺埃及地頭生的時候，災殃必不臨到你們身上滅你們。」","notes":[]},{"n":14,"t":"「你們要記念這日，守為耶和華的節，作為你們世世代代永遠的定例。","notes":[],"heads":["除酵節"]},{"n":15,"t":"你們要吃無酵餅七日。頭一日要把酵從你們各家中除去；因為從頭一日起，到第七日為止，凡吃有酵之餅的，必從以色列中剪除。","notes":[]},{"n":16,"t":"頭一日你們當有聖會，第七日也當有聖會。這兩日之內，除了預備各人所要吃的以外，無論何工都不可做。","notes":[]},{"n":17,"t":"你們要守無酵節，因為我正當這日把你們的軍隊從埃及地領出來。所以，你們要守這日，作為世世代代永遠的定例。","notes":[]},{"n":18,"t":"從正月十四日晚上，直到二十一日晚上，你們要吃無酵餅。","notes":[]},{"n":19,"t":"在你們各家中，七日之內不可有酵；因為凡吃有酵之物的，無論是寄居的，是本地的，必從以色列的會中剪除。","notes":[]},{"n":20,"t":"有酵的物，你們都不可吃；在你們一切住處要吃無酵餅。」","notes":[]},{"n":21,"t":"於是，摩西召了以色列的眾長老來，對他們說：「你們要按著家口取出羊羔，把這逾越節的羊羔宰了。","notes":[],"heads":["第一個逾越節"]},{"n":22,"t":"拿一把牛膝草，蘸盆裏的血，打在門楣上和左右的門框上。你們誰也不可出自己的房門，直到早晨。","notes":[]},{"n":23,"t":"因為耶和華要巡行擊殺埃及人，他看見血在門楣上和左右的門框上，就必越過那門，不容滅命的進你們的房屋，擊殺你們。","notes":[]},{"n":24,"t":"這例，你們要守著，作為你們和你們子孫永遠的定例。","notes":[]},{"n":25,"t":"日後，你們到了耶和華按著所應許賜給你們的那地，就要守這禮。","notes":[]},{"n":26,"t":"你們的兒女問你們說：『行這禮是甚麼意思？』","notes":[]},{"n":27,"t":"你們就說：『這是獻給耶和華逾越節的祭。當以色列人在埃及的時候，他擊殺埃及人，越過以色列人的房屋，救了我們各家。』」於是百姓低頭下拜。","notes":[]},{"n":28,"t":"耶和華怎樣吩咐摩西、亞倫，以色列人就怎樣行。","notes":[]},{"n":29,"t":"到了半夜，耶和華把埃及地所有的長子，就是從坐寶座的法老，直到被擄囚在監裏之人的長子，以及一切頭生的牲畜，盡都殺了。","notes":[],"heads":["頭胎的被殺"]},{"n":30,"t":"法老和一切臣僕，並埃及眾人，夜間都起來了。在埃及有大哀號，無一家不死一個人的。","notes":[]},{"n":31,"t":"夜間，法老召了摩西、亞倫來，說：「起來！連你們帶以色列人，從我民中出去，依你們所說的，去事奉耶和華吧！","notes":[]},{"n":32,"t":"也依你們所說的，連羊群牛群帶著走吧！並要為我祝福。」","notes":[]},{"n":33,"t":"埃及人催促百姓，打發他們快快出離那地，因為埃及人說：「我們都要死了。」","notes":[]},{"n":34,"t":"百姓就拿著沒有酵的生麵，把摶麵盆包在衣服中，扛在肩頭上。","notes":[]},{"n":35,"t":"以色列人照著摩西的話行，向埃及人要金器、銀器，和衣裳。","notes":[]},{"n":36,"t":"耶和華叫百姓在埃及人眼前蒙恩，以致埃及人給他們所要的。他們就把埃及人的財物奪去了。","notes":[]},{"n":37,"t":"以色列人從蘭塞起行，往疏割去；除了婦人孩子，步行的男人約有六十萬。","notes":[],"heads":["以色列人出埃及"]},{"n":38,"t":"又有許多閒雜人，並有羊群牛群，和他們一同上去。","notes":[]},{"n":39,"t":"他們用埃及帶出來的生麵烤成無酵餅。這生麵原沒有發起；因為他們被催逼離開埃及，不能耽延，也沒有為自己預備甚麼食物。","notes":[]},{"n":40,"t":"以色列人住在埃及共有四百三十年。","notes":[]},{"n":41,"t":"正滿了四百三十年的那一天，耶和華的軍隊都從埃及地出來了。","notes":[]},{"n":42,"t":"這夜是耶和華的夜；因耶和華領他們出了埃及地，所以當向耶和華謹守，是以色列眾人世世代代該謹守的。","notes":[]},{"n":43,"t":"耶和華對摩西、亞倫說：「逾越節的例是這樣：外邦人都不可吃這羊羔。","notes":[],"heads":["逾越節的條例"]},{"n":44,"t":"但各人用銀子買的奴僕，既受了割禮就可以吃。","notes":[]},{"n":45,"t":"寄居的和雇工人都不可吃。","notes":[]},{"n":46,"t":"應當在一個房子裏吃；不可把一點肉從房子裏帶到外頭去。羊羔的骨頭一根也不可折斷。","notes":[]},{"n":47,"t":"以色列全會眾都要守這禮。","notes":[]},{"n":48,"t":"若有外人寄居在你們中間，願向耶和華守逾越節，他所有的男子務要受割禮，然後才容他前來遵守，他也就像本地人一樣；但未受割禮的，都不可吃這羊羔。","notes":[]},{"n":49,"t":"本地人和寄居在你們中間的外人同歸一例。」","notes":[]},{"n":50,"t":"耶和華怎樣吩咐摩西、亞倫，以色列眾人就怎樣行了。","notes":[]},{"n":51,"t":"正當那日，耶和華將以色列人按著他們的軍隊，從埃及地領出來。","notes":[]}]},"13":{"heading":"奉獻頭胎的","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「以色列中凡頭生的，無論是人是牲畜，都是我的，要分別為聖歸我。」","notes":[]},{"n":3,"t":"摩西對百姓說：「你們要記念從埃及為奴之家出來的這日，因為耶和華用大能的手將你們從這地方領出來。有酵的餅都不可吃。","notes":[],"heads":["除酵節"]},{"n":4,"t":"亞筆月間的這日是你們出來的日子。","notes":[]},{"n":5,"t":"將來耶和華領你進迦南人、赫人、亞摩利人、希未人、耶布斯人之地，就是他向你的祖宗起誓應許給你那流奶與蜜之地，那時你要在這月間守這禮。","notes":[]},{"n":6,"t":"你要吃無酵餅七日，到第七日要向耶和華守節。","notes":[]},{"n":7,"t":"這七日之久，要吃無酵餅；在你四境之內不可見有酵的餅，也不可見發酵的物。","notes":[]},{"n":8,"t":"當那日，你要告訴你的兒子說：『這是因耶和華在我出埃及的時候為我所行的事。","notes":[]},{"n":9,"t":"這要在你手上作記號，在你額上作紀念，使耶和華的律法常在你口中，因為耶和華曾用大能的手將你從埃及領出來。","notes":[]},{"n":10,"t":"所以你每年要按著日期守這例。』」","notes":[]},{"n":11,"t":"「將來，耶和華照他向你和你祖宗所起的誓將你領進迦南人之地，把這地賜給你，","notes":[],"heads":["長子"]},{"n":12,"t":"那時你要將一切頭生的，並牲畜中頭生的，歸給耶和華；公的都要屬耶和華。","notes":[]},{"n":13,"t":"凡頭生的驢，你要用羊羔代贖；若不代贖，就要打折牠的頸項。凡你兒子中頭生的都要贖出來。","notes":[]},{"n":14,"t":"日後，你的兒子問你說：『這是甚麼意思？』你就說：『耶和華用大能的手將我們從埃及為奴之家領出來。","notes":[]},{"n":15,"t":"那時法老幾乎不容我們去，耶和華就把埃及地所有頭生的，無論是人是牲畜，都殺了。因此，我把一切頭生的公牲畜獻給耶和華為祭，但將頭生的兒子都贖出來。","notes":[]},{"n":16,"t":"這要在你手上作記號，在你額上作經文，因為耶和華用大能的手將我們從埃及領出來。』」","notes":[]},{"n":17,"t":"法老容百姓去的時候，非利士地的道路雖近，神卻不領他們從那裏走；因為神說：「恐怕百姓遇見打仗後悔，就回埃及去。」","notes":[],"heads":["雲柱和火柱"]},{"n":18,"t":"所以神領百姓繞道而行，走紅海曠野的路。以色列人出埃及地，都帶著兵器上去。","notes":[]},{"n":19,"t":"摩西把約瑟的骸骨一同帶去；因為約瑟曾叫以色列人嚴嚴地起誓，對他們說：「神必眷顧你們，你們要把我的骸骨從這裏一同帶上去。」","notes":[]},{"n":20,"t":"他們從疏割起行，在曠野邊的以倘安營。","notes":[]},{"n":21,"t":"日間，耶和華在雲柱中領他們的路；夜間，在火柱中光照他們，使他們日夜都可以行走。","notes":[]},{"n":22,"t":"日間雲柱，夜間火柱，總不離開百姓的面前。","notes":[]}]},"14":{"heading":"過紅海","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「你吩咐以色列人轉回，安營在比‧哈希錄前，密奪和海的中間，對著巴力‧洗分，靠近海邊安營。","notes":[]},{"n":3,"t":"法老必說：『以色列人在地中繞迷了，曠野把他們困住了。』","notes":[]},{"n":4,"t":"我要使法老的心剛硬，他要追趕他們，我便在法老和他全軍身上得榮耀；埃及人就知道我是耶和華。」於是以色列人這樣行了。","notes":[]},{"n":5,"t":"有人告訴埃及王說：「百姓逃跑。」法老和他的臣僕就向百姓變心，說：「我們容以色列人去，不再服事我們，這做的是甚麼事呢？」","notes":[]},{"n":6,"t":"法老就預備他的車輛，帶領軍兵同去，","notes":[]},{"n":7,"t":"並帶著六百輛特選的車和埃及所有的車，每輛都有車兵長。","notes":[]},{"n":8,"t":"耶和華使埃及王法老的心剛硬，他就追趕以色列人，因為以色列人是昂然無懼地出埃及。","notes":[]},{"n":9,"t":"埃及人追趕他們，法老一切的馬匹、車輛、馬兵，與軍兵就在海邊上，靠近比‧哈希錄，對著巴力‧洗分，在他們安營的地方追上了。","notes":[]},{"n":10,"t":"法老臨近的時候，以色列人舉目看見埃及人趕來，就甚懼怕，向耶和華哀求。","notes":[]},{"n":11,"t":"他們對摩西說：「難道在埃及沒有墳地，你把我們帶來死在曠野嗎？你為甚麼這樣待我們，將我們從埃及領出來呢？","notes":[]},{"n":12,"t":"我們在埃及豈沒有對你說過，不要攪擾我們，容我們服事埃及人嗎？因為服事埃及人比死在曠野還好。」","notes":[]},{"n":13,"t":"摩西對百姓說：「不要懼怕，只管站住！看耶和華今天向你們所要施行的救恩。因為，你們今天所看見的埃及人必永遠不再看見了。","notes":[]},{"n":14,"t":"耶和華必為你們爭戰；你們只管靜默，不要作聲。」","notes":[]},{"n":15,"t":"耶和華對摩西說：「你為甚麼向我哀求呢？你吩咐以色列人往前走。","notes":[]},{"n":16,"t":"你舉手向海伸杖，把水分開。以色列人要下海中走乾地。","notes":[]},{"n":17,"t":"我要使埃及人的心剛硬，他們就跟著下去。我要在法老和他的全軍、車輛、馬兵上得榮耀。","notes":[]},{"n":18,"t":"我在法老和他的車輛、馬兵上得榮耀的時候，埃及人就知道我是耶和華了。」","notes":[]},{"n":19,"t":"在以色列營前行走神的使者，轉到他們後邊去；雲柱也從他們前邊轉到他們後邊立住。","notes":[]},{"n":20,"t":"在埃及營和以色列營中間有雲柱，一邊黑暗，一邊發光，終夜兩下不得相近。","notes":[]},{"n":21,"t":"摩西向海伸杖，耶和華便用大東風，使海水一夜退去，水便分開，海就成了乾地。","notes":[]},{"n":22,"t":"以色列人下海中走乾地，水在他們的左右作了牆垣。","notes":[]},{"n":23,"t":"埃及人追趕他們，法老一切的馬匹、車輛，和馬兵都跟著下到海中。","notes":[]},{"n":24,"t":"到了晨更的時候，耶和華從雲火柱中向埃及的軍兵觀看，使埃及的軍兵混亂了；","notes":[]},{"n":25,"t":"又使他們的車輪脫落，難以行走，以致埃及人說：「我們從以色列人面前逃跑吧！因耶和華為他們攻擊我們了。」","notes":[]},{"n":26,"t":"耶和華對摩西說：「你向海伸杖，叫水仍合在埃及人並他們的車輛、馬兵身上。」","notes":[]},{"n":27,"t":"摩西就向海伸杖，到了天一亮，海水仍舊復原。埃及人避水逃跑的時候，耶和華把他們推翻在海中，","notes":[]},{"n":28,"t":"水就回流，淹沒了車輛和馬兵。那些跟著以色列人下海法老的全軍，連一個也沒有剩下。","notes":[]},{"n":29,"t":"以色列人卻在海中走乾地；水在他們的左右作了牆垣。","notes":[]},{"n":30,"t":"當日，耶和華這樣拯救以色列人脫離埃及人的手，以色列人看見埃及人的死屍都在海邊了。","notes":[]},{"n":31,"t":"以色列人看見耶和華向埃及人所行的大事，就敬畏耶和華，又信服他和他的僕人摩西。","notes":[]}]},"15":{"heading":"摩西的歌","verses":[{"n":1,"t":"那時，摩西和以色列人向耶和華唱歌說：我要向耶和華歌唱，因他大大戰勝，將馬和騎馬的投在海中。","notes":[]},{"n":2,"t":"耶和華是我的力量，我的詩歌，也成了我的拯救。這是我的神，我要讚美他，是我父親的神，我要尊崇他。","notes":[]},{"n":3,"t":"耶和華是戰士；他的名是耶和華。","notes":[]},{"n":4,"t":"法老的車輛、軍兵，耶和華已拋在海中；他特選的軍長都沉於紅海。","notes":[]},{"n":5,"t":"深水淹沒他們；他們如同石頭墜到深處。","notes":[]},{"n":6,"t":"耶和華啊，你的右手施展能力，顯出榮耀；耶和華啊，你的右手摔碎仇敵。","notes":[]},{"n":7,"t":"你大發威嚴，推翻那些起來攻擊你的；你發出烈怒如火，燒滅他們像燒碎稭一樣。","notes":[]},{"n":8,"t":"你發鼻中的氣，水便聚起成堆，大水直立如壘，海中的深水凝結。","notes":[]},{"n":9,"t":"仇敵說：我要追趕，我要追上；我要分擄物，我要在他們身上稱我的心願。我要拔出刀來，親手殺滅他們。","notes":[]},{"n":10,"t":"你叫風一吹，海就把他們淹沒；他們如鉛沉在大水之中。","notes":[]},{"n":11,"t":"耶和華啊，眾神之中，誰能像你？誰能像你－至聖至榮，可頌可畏，施行奇事？","notes":[]},{"n":12,"t":"你伸出右手，地便吞滅他們。","notes":[]},{"n":13,"t":"你憑慈愛領了你所贖的百姓；你憑能力引他們到了你的聖所。","notes":[]},{"n":14,"t":"外邦人聽見就發顫；疼痛抓住非利士的居民。","notes":[]},{"n":15,"t":"那時，以東的族長驚惶，摩押的英雄被戰兢抓住，迦南的居民心都消化了。","notes":[]},{"n":16,"t":"驚駭恐懼臨到他們。耶和華啊，因你膀臂的大能，他們如石頭寂然不動，等候你的百姓過去，等候你所贖的百姓過去。","notes":[]},{"n":17,"t":"你要將他們領進去，栽於你產業的山上－耶和華啊，就是你為自己所造的住處；主啊，就是你手所建立的聖所。","notes":[]},{"n":18,"t":"耶和華必作王，直到永永遠遠！","notes":[]},{"n":19,"t":"法老的馬匹、車輛，和馬兵下到海中，耶和華使海水回流，淹沒他們；惟有以色列人在海中走乾地。","notes":[],"heads":["米利暗的歌"]},{"n":20,"t":"亞倫的姊姊，女先知米利暗，手裏拿著鼓；眾婦女也跟她出去拿鼓跳舞。","notes":[]},{"n":21,"t":"米利暗應聲說：你們要歌頌耶和華，因他大大戰勝，將馬和騎馬的投在海中。","notes":[]},{"n":22,"t":"摩西領以色列人從紅海往前行，到了書珥的曠野，在曠野走了三天，找不著水。","notes":[],"heads":["苦水"]},{"n":23,"t":"到了瑪拉，不能喝那裏的水；因為水苦，所以那地名叫瑪拉。","notes":[]},{"n":24,"t":"百姓就向摩西發怨言，說：「我們喝甚麼呢？」","notes":[]},{"n":25,"t":"摩西呼求耶和華，耶和華指示他一棵樹。他把樹丟在水裏，水就變甜了。耶和華在那裏為他們定了律例、典章，在那裏試驗他們；","notes":[]},{"n":26,"t":"又說：「你若留意聽耶和華－你神的話，又行我眼中看為正的事，留心聽我的誡命，守我一切的律例，我就不將所加與埃及人的疾病加在你身上，因為我－耶和華是醫治你的。」","notes":[]},{"n":27,"t":"他們到了以琳，在那裏有十二股水泉，七十棵棕樹；他們就在那裏的水邊安營。","notes":[]}]},"16":{"heading":"嗎哪和鵪鶉","verses":[{"n":1,"t":"以色列全會眾從以琳起行，在出埃及後第二個月十五日到了以琳和西奈中間、汛的曠野。","notes":[]},{"n":2,"t":"以色列全會眾在曠野向摩西、亞倫發怨言，","notes":[]},{"n":3,"t":"說：「巴不得我們早死在埃及地、耶和華的手下；那時我們坐在肉鍋旁邊，吃得飽足。你們將我們領出來，到這曠野，是要叫這全會眾都餓死啊！」","notes":[]},{"n":4,"t":"耶和華對摩西說：「我要將糧食從天降給你們。百姓可以出去，每天收每天的分，我好試驗他們遵不遵我的法度。","notes":[]},{"n":5,"t":"到第六天，他們要把所收進來的預備好了，比每天所收的多一倍。」","notes":[]},{"n":6,"t":"摩西、亞倫對以色列眾人說：「到了晚上，你們要知道是耶和華將你們從埃及地領出來的。","notes":[]},{"n":7,"t":"早晨，你們要看見耶和華的榮耀，因為耶和華聽見你們向他所發的怨言了。我們算甚麼，你們竟向我們發怨言呢？」","notes":[]},{"n":8,"t":"摩西又說：「耶和華晚上必給你們肉吃，早晨必給你們食物得飽；因為你們向耶和華發的怨言，他都聽見了。我們算甚麼，你們的怨言不是向我們發的，乃是向耶和華發的。」","notes":[]},{"n":9,"t":"摩西對亞倫說：「你告訴以色列全會眾說：『你們就近耶和華面前，因為他已經聽見你們的怨言了。』」","notes":[]},{"n":10,"t":"亞倫正對以色列全會眾說話的時候，他們向曠野觀看，不料，耶和華的榮光在雲中顯現。","notes":[]},{"n":11,"t":"耶和華曉諭摩西說：","notes":[]},{"n":12,"t":"「我已經聽見以色列人的怨言。你告訴他們說：『到黃昏的時候，你們要吃肉，早晨必有食物得飽，你們就知道我是耶和華－你們的神。』」","notes":[]},{"n":13,"t":"到了晚上，有鵪鶉飛來，遮滿了營；早晨在營四圍的地上有露水。","notes":[]},{"n":14,"t":"露水上升之後，不料，野地面上有如白霜的小圓物。","notes":[]},{"n":15,"t":"以色列人看見，不知道是甚麼，就彼此對問說：「這是甚麼呢？」摩西對他們說：「這就是耶和華給你們吃的食物。","notes":[]},{"n":16,"t":"耶和華所吩咐的是這樣：你們要按著各人的飯量，為帳棚裏的人，按著人數收起來，各拿一俄梅珥。」","notes":[]},{"n":17,"t":"以色列人就這樣行；有多收的，有少收的。","notes":[]},{"n":18,"t":"及至用俄梅珥量一量，多收的也沒有餘，少收的也沒有缺；各人按著自己的飯量收取。","notes":[]},{"n":19,"t":"摩西對他們說：「所收的，不許甚麼人留到早晨。」","notes":[]},{"n":20,"t":"然而他們不聽摩西的話，內中有留到早晨的，就生蟲變臭了；摩西便向他們發怒。","notes":[]},{"n":21,"t":"他們每日早晨，按著各人的飯量收取，日頭一發熱，就消化了。","notes":[]},{"n":22,"t":"到第六天，他們收了雙倍的食物，每人兩俄梅珥。會眾的官長來告訴摩西；","notes":[]},{"n":23,"t":"摩西對他們說：「耶和華這樣說：『明天是聖安息日，是向耶和華守的聖安息日。你們要烤的就烤了，要煮的就煮了，所剩下的都留到早晨。』」","notes":[]},{"n":24,"t":"他們就照摩西的吩咐留到早晨，也不臭，裏頭也沒有蟲子。","notes":[]},{"n":25,"t":"摩西說：「你們今天吃這個吧！因為今天是向耶和華守的安息日；你們在田野必找不著了。","notes":[]},{"n":26,"t":"六天可以收取，第七天乃是安息日，那一天必沒有了。」","notes":[]},{"n":27,"t":"第七天，百姓中有人出去收，甚麼也找不著。","notes":[]},{"n":28,"t":"耶和華對摩西說：「你們不肯守我的誡命和律法，要到幾時呢？","notes":[]},{"n":29,"t":"你們看！耶和華既將安息日賜給你們，所以第六天他賜給你們兩天的食物，第七天各人要住在自己的地方，不許甚麼人出去。」","notes":[]},{"n":30,"t":"於是百姓第七天安息了。","notes":[]},{"n":31,"t":"這食物，以色列家叫嗎哪；樣子像芫荽子，顏色是白的，滋味如同攙蜜的薄餅。","notes":[]},{"n":32,"t":"摩西說：「耶和華所吩咐的是這樣：『要將一滿俄梅珥嗎哪留到世世代代，使後人可以看見我當日將你們領出埃及地，在曠野所給你們吃的食物。』」","notes":[]},{"n":33,"t":"摩西對亞倫說：「你拿一個罐子，盛一滿俄梅珥嗎哪，存在耶和華面前，要留到世世代代。」","notes":[]},{"n":34,"t":"耶和華怎麼吩咐摩西，亞倫就怎麼行，把嗎哪放在法櫃前存留。","notes":[]},{"n":35,"t":"以色列人吃嗎哪共四十年，直到進了有人居住之地，就是迦南的境界。（","notes":[]},{"n":36,"t":"俄梅珥就是伊法十分之一。）","notes":[]}]},"17":{"heading":"磐石出水","verses":[{"n":1,"t":"以色列全會眾都遵耶和華的吩咐，按著站口從汛的曠野往前行，在利非訂安營。百姓沒有水喝，","notes":[]},{"n":2,"t":"所以與摩西爭鬧，說：「給我們水喝吧！」摩西對他們說：「你們為甚麼與我爭鬧？為甚麼試探耶和華呢？」","notes":[]},{"n":3,"t":"百姓在那裏甚渴，要喝水，就向摩西發怨言，說：「你為甚麼將我們從埃及領出來，使我們和我們的兒女並牲畜都渴死呢？」","notes":[]},{"n":4,"t":"摩西就呼求耶和華說：「我向這百姓怎樣行呢？他們幾乎要拿石頭打死我。」","notes":[]},{"n":5,"t":"耶和華對摩西說：「你手裏拿著你先前擊打河水的杖，帶領以色列的幾個長老，從百姓面前走過去。","notes":[]},{"n":6,"t":"我必在何烈的磐石那裏，站在你面前。你要擊打磐石，從磐石裏必有水流出來，使百姓可以喝。」摩西就在以色列的長老眼前這樣行了。","notes":[]},{"n":7,"t":"他給那地方起名叫瑪撒，又叫米利巴；因以色列人爭鬧，又因他們試探耶和華，說：「耶和華是在我們中間不是？」","notes":["就是試探的意思","就是爭鬧的意思"]},{"n":8,"t":"那時，亞瑪力人來在利非訂，和以色列人爭戰。","notes":[],"heads":["跟亞瑪力人爭戰"]},{"n":9,"t":"摩西對約書亞說：「你為我們選出人來，出去和亞瑪力人爭戰。明天我手裏要拿著神的杖，站在山頂上。」","notes":[]},{"n":10,"t":"於是約書亞照著摩西對他所說的話行，和亞瑪力人爭戰。摩西、亞倫，與戶珥都上了山頂。","notes":[]},{"n":11,"t":"摩西何時舉手，以色列人就得勝，何時垂手，亞瑪力人就得勝。","notes":[]},{"n":12,"t":"但摩西的手發沉，他們就搬石頭來，放在他以下，他就坐在上面。亞倫與戶珥扶著他的手，一個在這邊，一個在那邊，他的手就穩住，直到日落的時候。","notes":[]},{"n":13,"t":"約書亞用刀殺了亞瑪力王和他的百姓。","notes":[]},{"n":14,"t":"耶和華對摩西說：「我要將亞瑪力的名號從天下全然塗抹了；你要將這話寫在書上作紀念，又念給約書亞聽。」","notes":[]},{"n":15,"t":"摩西築了一座壇，起名叫「耶和華尼西」，","notes":["就是耶和華是我旌旗的意思"]},{"n":16,"t":"又說：「耶和華已經起了誓，必世世代代和亞瑪力人爭戰。」","notes":[]}]},"18":{"heading":"葉忒羅訪問摩西","verses":[{"n":1,"t":"摩西的岳父，米甸祭司葉忒羅，聽見神為摩西和神的百姓以色列所行的一切事，就是耶和華將以色列從埃及領出來的事，","notes":[]},{"n":2,"t":"便帶著摩西的妻子西坡拉，就是摩西從前打發回去的，","notes":[]},{"n":3,"t":"又帶著西坡拉的兩個兒子，一個名叫革舜，因為摩西說：「我在外邦作了寄居的」；","notes":[]},{"n":4,"t":"一個名叫以利以謝，因為他說：「我父親的神幫助了我，救我脫離法老的刀。」","notes":[]},{"n":5,"t":"摩西的岳父葉忒羅帶著摩西的妻子和兩個兒子來到神的山，就是摩西在曠野安營的地方。","notes":[]},{"n":6,"t":"他對摩西說：「我是你岳父葉忒羅，帶著你的妻子和兩個兒子來到你這裏。」","notes":[]},{"n":7,"t":"摩西迎接他的岳父，向他下拜，與他親嘴，彼此問安，都進了帳棚。","notes":[]},{"n":8,"t":"摩西將耶和華為以色列的緣故向法老和埃及人所行的一切事，以及路上所遭遇的一切艱難，並耶和華怎樣搭救他們，都述說與他岳父聽。","notes":[]},{"n":9,"t":"葉忒羅因耶和華待以色列的一切好處，就是拯救他們脫離埃及人的手，便甚歡喜。","notes":[]},{"n":10,"t":"葉忒羅說：「耶和華是應當稱頌的；他救了你們脫離埃及人和法老的手，將這百姓從埃及人的手下救出來。","notes":[]},{"n":11,"t":"我現今在埃及人向這百姓發狂傲的事上得知，耶和華比萬神都大。」","notes":[]},{"n":12,"t":"摩西的岳父葉忒羅把燔祭和平安祭獻給神。亞倫和以色列的眾長老都來了，與摩西的岳父在神面前吃飯。","notes":[]},{"n":13,"t":"第二天，摩西坐著審判百姓，百姓從早到晚都站在摩西的左右。","notes":[],"heads":["選立百姓的官長"]},{"n":14,"t":"摩西的岳父看見他向百姓所做的一切事，就說：「你向百姓做的是甚麼事呢？你為甚麼獨自坐著，眾百姓從早到晚都站在你的左右呢？」","notes":[]},{"n":15,"t":"摩西對岳父說：「這是因百姓到我這裏來求問神。","notes":[]},{"n":16,"t":"他們有事的時候就到我這裏來，我便在兩造之間施行審判；我又叫他們知道神的律例和法度。」","notes":[]},{"n":17,"t":"摩西的岳父說：「你這做的不好。","notes":[]},{"n":18,"t":"你和這些百姓必都疲憊；因為這事太重，你獨自一人辦理不了。","notes":[]},{"n":19,"t":"現在你要聽我的話。我為你出個主意，願神與你同在。你要替百姓到神面前，將案件奏告神；","notes":[]},{"n":20,"t":"又要將律例和法度教訓他們，指示他們當行的道，當做的事；","notes":[]},{"n":21,"t":"並要從百姓中揀選有才能的人，就是敬畏神、誠實無妄、恨不義之財的人，派他們作千夫長、百夫長、五十夫長、十夫長，管理百姓，","notes":[]},{"n":22,"t":"叫他們隨時審判百姓，大事都要呈到你這裏，小事他們自己可以審判。這樣，你就輕省些，他們也可以同當此任。","notes":[]},{"n":23,"t":"你若這樣行，神也這樣吩咐你，你就能受得住，這百姓也都平平安安歸回他們的住處。」","notes":[]},{"n":24,"t":"於是，摩西聽從他岳父的話，按著他所說的去行。","notes":[]},{"n":25,"t":"摩西從以色列人中揀選了有才能的人，立他們為百姓的首領，作千夫長、百夫長、五十夫長、十夫長。","notes":[]},{"n":26,"t":"他們隨時審判百姓，有難斷的案件就呈到摩西那裏，但各樣小事他們自己審判。","notes":[]},{"n":27,"t":"此後，摩西讓他的岳父去，他就往本地去了。","notes":[]}]},"19":{"heading":"以色列人在西奈山","verses":[{"n":1,"t":"以色列人出埃及地以後，滿了三個月的那一天，就來到西奈的曠野。","notes":[]},{"n":2,"t":"他們離了利非訂，來到西奈的曠野，就在那裏的山下安營。","notes":[]},{"n":3,"t":"摩西到神那裏，耶和華從山上呼喚他說：「你要這樣告訴雅各家，曉諭以色列人說：","notes":[]},{"n":4,"t":"『我向埃及人所行的事，你們都看見了，且看見我如鷹將你們背在翅膀上，帶來歸我。","notes":[]},{"n":5,"t":"如今你們若實在聽從我的話，遵守我的約，就要在萬民中作屬我的子民，因為全地都是我的。","notes":[]},{"n":6,"t":"你們要歸我作祭司的國度，為聖潔的國民。』這些話你要告訴以色列人。」","notes":[]},{"n":7,"t":"摩西去召了民間的長老來，將耶和華所吩咐他的話都在他們面前陳明。","notes":[]},{"n":8,"t":"百姓都同聲回答說：「凡耶和華所說的，我們都要遵行。」摩西就將百姓的話回覆耶和華。","notes":[]},{"n":9,"t":"耶和華對摩西說：「我要在密雲中臨到你那裏，叫百姓在我與你說話的時候可以聽見，也可以永遠信你了。」於是，摩西將百姓的話奏告耶和華。","notes":[]},{"n":10,"t":"耶和華又對摩西說：「你往百姓那裏去，叫他們今天明天自潔，又叫他們洗衣服。","notes":[]},{"n":11,"t":"到第三天要預備好了，因為第三天耶和華要在眾百姓眼前降臨在西奈山上。","notes":[]},{"n":12,"t":"你要在山的四圍給百姓定界限，說：『你們當謹慎，不可上山去，也不可摸山的邊界；凡摸這山的，必要治死他。","notes":[]},{"n":13,"t":"不可用手摸他，必用石頭打死，或用箭射透；無論是人是牲畜，都不得活。到角聲拖長的時候，他們才可到山根來。』」","notes":[]},{"n":14,"t":"摩西下山往百姓那裏去，叫他們自潔，他們就洗衣服。","notes":[]},{"n":15,"t":"他對百姓說：「到第三天要預備好了。不可親近女人。」","notes":[]},{"n":16,"t":"到了第三天早晨，在山上有雷轟、閃電，和密雲，並且角聲甚大，營中的百姓盡都發顫。","notes":[]},{"n":17,"t":"摩西率領百姓出營迎接神，都站在山下。","notes":[]},{"n":18,"t":"西奈全山冒煙，因為耶和華在火中降於山上。山的煙氣上騰，如燒窯一般，遍山大大地震動。","notes":[]},{"n":19,"t":"角聲漸漸地高而又高，摩西就說話，神有聲音答應他。","notes":[]},{"n":20,"t":"耶和華降臨在西奈山頂上，耶和華召摩西上山頂，摩西就上去。","notes":[]},{"n":21,"t":"耶和華對摩西說：「你下去囑咐百姓，不可闖過來到我面前觀看，恐怕他們有多人死亡；","notes":[]},{"n":22,"t":"又叫親近我的祭司自潔，恐怕我忽然出來擊殺他們。」","notes":[]},{"n":23,"t":"摩西對耶和華說：「百姓不能上西奈山，因為你已經囑咐我們說：『要在山的四圍定界限，叫山成聖。』」","notes":[]},{"n":24,"t":"耶和華對他說：「下去吧，你要和亞倫一同上來；只是祭司和百姓不可闖過來上到我面前，恐怕我忽然出來擊殺他們。」","notes":[]},{"n":25,"t":"於是摩西下到百姓那裏告訴他們。","notes":[]}]},"20":{"heading":"十誡","verses":[{"n":1,"t":"神吩咐這一切的話說：","notes":[]},{"n":2,"t":"「我是耶和華－你的神，曾將你從埃及地為奴之家領出來。","notes":[]},{"n":3,"t":"「除了我以外，你不可有別的神。","notes":[]},{"n":4,"t":"「不可為自己雕刻偶像，也不可做甚麼形像彷彿上天、下地，和地底下、水中的百物。","notes":[]},{"n":5,"t":"不可跪拜那些像，也不可事奉它，因為我耶和華－你的神是忌邪的神。恨我的，我必追討他的罪，自父及子，直到三四代；","notes":[]},{"n":6,"t":"愛我、守我誡命的，我必向他們發慈愛，直到千代。","notes":[]},{"n":7,"t":"「不可妄稱耶和華－你神的名；因為妄稱耶和華名的，耶和華必不以他為無罪。","notes":[]},{"n":8,"t":"「當記念安息日，守為聖日。","notes":[]},{"n":9,"t":"六日要勞碌做你一切的工，","notes":[]},{"n":10,"t":"但第七日是向耶和華－你神當守的安息日。這一日你和你的兒女、僕婢、牲畜，並你城裏寄居的客旅，無論何工都不可做；","notes":[]},{"n":11,"t":"因為六日之內，耶和華造天、地、海，和其中的萬物，第七日便安息，所以耶和華賜福與安息日，定為聖日。","notes":[]},{"n":12,"t":"「當孝敬父母，使你的日子在耶和華－你神所賜你的地上得以長久。","notes":[]},{"n":13,"t":"「不可殺人。","notes":[]},{"n":14,"t":"「不可姦淫。","notes":[]},{"n":15,"t":"「不可偷盜。","notes":[]},{"n":16,"t":"「不可作假見證陷害人。","notes":[]},{"n":17,"t":"「不可貪戀人的房屋；也不可貪戀人的妻子、僕婢、牛驢，並他一切所有的。」","notes":[]},{"n":18,"t":"眾百姓見雷轟、閃電、角聲、山上冒煙，就都發顫，遠遠地站立，","notes":[],"heads":["眾民戰懼"]},{"n":19,"t":"對摩西說：「求你和我們說話，我們必聽；不要神和我們說話，恐怕我們死亡。」","notes":[]},{"n":20,"t":"摩西對百姓說：「不要懼怕；因為神降臨是要試驗你們，叫你們時常敬畏他，不致犯罪。」","notes":[]},{"n":21,"t":"於是百姓遠遠地站立；摩西就挨近神所在的幽暗之中。","notes":[]},{"n":22,"t":"耶和華對摩西說：「你要向以色列人這樣說：『你們自己看見我從天上和你們說話了。","notes":[],"heads":["祭壇的條例"]},{"n":23,"t":"你們不可做甚麼神像與我相配，不可為自己做金銀的神像。","notes":[]},{"n":24,"t":"你要為我築土壇，在上面以牛羊獻為燔祭和平安祭。凡記下我名的地方，我必到那裏賜福給你。","notes":[]},{"n":25,"t":"你若為我築一座石壇，不可用鑿成的石頭，因你在上頭一動家具，就把壇污穢了。","notes":[]},{"n":26,"t":"你上我的壇，不可用臺階，免得露出你的下體來。』」","notes":[]}]},"21":{"heading":"對待奴僕的條例","verses":[{"n":1,"t":"「你在百姓面前所要立的典章是這樣：","notes":[]},{"n":2,"t":"你若買希伯來人作奴僕，他必服事你六年；第七年他可以自由，白白地出去。","notes":[]},{"n":3,"t":"他若孤身來就可以孤身去；他若有妻，他的妻就可以同他出去。","notes":[]},{"n":4,"t":"他主人若給他妻子，妻子給他生了兒子或女兒，妻子和兒女要歸主人，他要獨自出去。","notes":[]},{"n":5,"t":"倘或奴僕明說：『我愛我的主人和我的妻子兒女，不願意自由出去。』","notes":[]},{"n":6,"t":"他的主人就要帶他到審判官那裏，又要帶他到門前，靠近門框，用錐子穿他的耳朵，他就永遠服事主人。","notes":["或譯：神；下同"]},{"n":7,"t":"「人若賣女兒作婢女，婢女不可像男僕那樣出去。","notes":[]},{"n":8,"t":"主人選定她歸自己，若不喜歡她，就要許她贖身；主人既然用詭詐待她，就沒有權柄賣給外邦人。","notes":[]},{"n":9,"t":"主人若選定她給自己的兒子，就當待她如同女兒。","notes":[]},{"n":10,"t":"若另娶一個，那女子的吃食、衣服，並好合的事，仍不可減少。","notes":[]},{"n":11,"t":"若不向她行這三樣，她就可以不用錢贖，白白地出去。」","notes":[]},{"n":12,"t":"「打人以致打死的，必要把他治死。","notes":[],"heads":["懲罰暴行的條例"]},{"n":13,"t":"人若不是埋伏著殺人，乃是神交在他手中，我就設下一個地方，他可以往那裏逃跑。","notes":[]},{"n":14,"t":"人若任意用詭計殺了他的鄰舍，就是逃到我的壇那裏，也當捉去把他治死。","notes":[]},{"n":15,"t":"「打父母的，必要把他治死。","notes":[]},{"n":16,"t":"「拐帶人口，或是把人賣了，或是留在他手下，必要把他治死。","notes":[]},{"n":17,"t":"「咒罵父母的，必要把他治死。","notes":[]},{"n":18,"t":"「人若彼此相爭，這個用石頭或是拳頭打那個，尚且不至於死，不過躺臥在床，","notes":[]},{"n":19,"t":"若再能起來扶杖而出，那打他的可算無罪；但要將他耽誤的工夫用錢賠補，並要將他全然醫好。","notes":[]},{"n":20,"t":"「人若用棍子打奴僕或婢女，立時死在他的手下，他必要受刑。","notes":[]},{"n":21,"t":"若過一兩天才死，就可以不受刑，因為是用錢買的。","notes":[]},{"n":22,"t":"「人若彼此爭鬥，傷害有孕的婦人，甚至墜胎，隨後卻無別害，那傷害她的，總要按婦人的丈夫所要的，照審判官所斷的，受罰。","notes":[]},{"n":23,"t":"若有別害，就要以命償命，","notes":[]},{"n":24,"t":"以眼還眼，以牙還牙，以手還手，以腳還腳，","notes":[]},{"n":25,"t":"以烙還烙，以傷還傷，以打還打。","notes":[]},{"n":26,"t":"「人若打壞了他奴僕或是婢女的一隻眼，就要因他的眼放他去得以自由。","notes":[]},{"n":27,"t":"若打掉了他奴僕或是婢女的一個牙，就要因他的牙放他去得以自由。」","notes":[]},{"n":28,"t":"「牛若觸死男人或是女人，總要用石頭打死那牛，卻不可吃牠的肉；牛的主人可算無罪。","notes":[],"heads":["物主的責任"]},{"n":29,"t":"倘若那牛素來是觸人的，有人報告了牛主，他竟不把牛拴著，以致把男人或是女人觸死，就要用石頭打死那牛，牛主也必治死。","notes":[]},{"n":30,"t":"若罰他贖命的價銀，他必照所罰的贖他的命。","notes":[]},{"n":31,"t":"牛無論觸了人的兒子或是女兒，必照這例辦理。","notes":[]},{"n":32,"t":"牛若觸了奴僕或是婢女，必將銀子三十舍客勒給他們的主人，也要用石頭把牛打死。","notes":[]},{"n":33,"t":"「人若敞著井口，或挖井不遮蓋，有牛或驢掉在裏頭，","notes":[]},{"n":34,"t":"井主要拿錢賠還本主人，死牲畜要歸自己。","notes":[]},{"n":35,"t":"「這人的牛若傷了那人的牛，以至於死，他們要賣了活牛，平分價值，也要平分死牛。","notes":[]},{"n":36,"t":"人若知道這牛素來是觸人的，主人竟不把牛拴著，他必要以牛還牛，死牛要歸自己。」","notes":[]}]},"22":{"heading":"賠償的條例","verses":[{"n":1,"t":"「人若偷牛或羊，無論是宰了，是賣了，他就要以五牛賠一牛，四羊賠一羊。","notes":[]},{"n":2,"t":"人若遇見賊挖窟窿，把賊打了，以至於死，就不能為他有流血的罪。","notes":[]},{"n":3,"t":"若太陽已經出來，就為他有流血的罪。賊若被拿，總要賠還。若他一無所有，就要被賣，頂他所偷的物。","notes":[]},{"n":4,"t":"若他所偷的，或牛，或驢，或羊，仍在他手下存活，他就要加倍賠還。","notes":[]},{"n":5,"t":"「人若在田間或在葡萄園裏放牲畜，任憑牲畜上別人的田裏去吃，就必拿自己田間上好的和葡萄園上好的賠還。","notes":[]},{"n":6,"t":"「若點火焚燒荊棘，以致將別人堆積的禾捆，站著的禾稼，或是田園，都燒盡了，那點火的必要賠還。","notes":[]},{"n":7,"t":"「人若將銀錢或家具交付鄰舍看守，這物從那人的家被偷去，若把賊找到了，賊要加倍賠還；","notes":[]},{"n":8,"t":"若找不到賊，那家主必就近審判官，要看看他拿了原主的物件沒有。","notes":[]},{"n":9,"t":"「兩個人的案件，無論是為甚麼過犯，或是為牛，為驢，為羊，為衣裳，或是為甚麼失掉之物，有一人說：『這是我的』，兩造就要將案件稟告審判官，審判官定誰有罪，誰就要加倍賠還。","notes":[]},{"n":10,"t":"「人若將驢，或牛，或羊，或別的牲畜，交付鄰舍看守，牲畜或死，或受傷，或被趕去，無人看見，","notes":[]},{"n":11,"t":"那看守的人要憑著耶和華起誓，手裏未曾拿鄰舍的物，本主就要罷休，看守的人不必賠還。","notes":[]},{"n":12,"t":"牲畜若從看守的那裏被偷去，他就要賠還本主；","notes":[]},{"n":13,"t":"若被野獸撕碎，看守的要帶來當作證據，所撕的不必賠還。","notes":[]},{"n":14,"t":"「人若向鄰舍借甚麼，所借的或受傷，或死，本主沒有同在一處，借的人總要賠還；","notes":[]},{"n":15,"t":"若本主同在一處，他就不必賠還；若是雇的，也不必賠還，本是為雇價來的。」","notes":[]},{"n":16,"t":"「人若引誘沒有受聘的處女，與她行淫，他總要交出聘禮，娶她為妻。","notes":[],"heads":["道德上和宗教上的條例"]},{"n":17,"t":"若女子的父親決不肯將女子給他，他就要按處女的聘禮，交出錢來。","notes":[]},{"n":18,"t":"「行邪術的女人，不可容她存活。","notes":[]},{"n":19,"t":"「凡與獸淫合的，總要把他治死。","notes":[]},{"n":20,"t":"「祭祀別神，不單單祭祀耶和華的，那人必要滅絕。","notes":[]},{"n":21,"t":"「不可虧負寄居的，也不可欺壓他，因為你們在埃及地也作過寄居的。","notes":[]},{"n":22,"t":"不可苦待寡婦和孤兒；","notes":[]},{"n":23,"t":"若是苦待他們一點，他們向我一哀求，我總要聽他們的哀聲，","notes":[]},{"n":24,"t":"並要發烈怒，用刀殺你們，使你們的妻子為寡婦，兒女為孤兒。","notes":[]},{"n":25,"t":"「我民中有貧窮人與你同住，你若借錢給他，不可如放債的向他取利。","notes":[]},{"n":26,"t":"你即或拿鄰舍的衣服作當頭，必在日落以先歸還他；","notes":[]},{"n":27,"t":"因他只有這一件當蓋頭，是他蓋身的衣服，若是沒有，他拿甚麼睡覺呢？他哀求我，我就應允，因為我是有恩惠的。","notes":[]},{"n":28,"t":"「不可毀謗神；也不可毀謗你百姓的官長。","notes":[]},{"n":29,"t":"「你要從你莊稼中的穀和酒醡中滴出來的酒拿來獻上，不可遲延。「你要將頭生的兒子歸給我。","notes":[]},{"n":30,"t":"你牛羊頭生的，也要這樣；七天當跟著母，第八天要歸給我。","notes":[]},{"n":31,"t":"「你們要在我面前為聖潔的人。因此，田間被野獸撕裂牲畜的肉，你們不可吃，要丟給狗吃。」","notes":[]}]},"23":{"heading":"正義和公道","verses":[{"n":1,"t":"「不可隨夥佈散謠言；不可與惡人連手妄作見證。","notes":[]},{"n":2,"t":"不可隨眾行惡；不可在爭訟的事上隨眾偏行，作見證屈枉正直；","notes":[]},{"n":3,"t":"也不可在爭訟的事上偏護窮人。","notes":[]},{"n":4,"t":"「若遇見你仇敵的牛或驢失迷了路，總要牽回來交給他。","notes":[]},{"n":5,"t":"若看見恨你人的驢壓臥在重馱之下，不可走開，務要和驢主一同抬開重馱。","notes":[]},{"n":6,"t":"「不可在窮人爭訟的事上屈枉正直。","notes":[]},{"n":7,"t":"當遠離虛假的事。不可殺無辜和有義的人，因我必不以惡人為義。","notes":[]},{"n":8,"t":"不可受賄賂；因為賄賂能叫明眼人變瞎了，又能顛倒義人的話。","notes":[]},{"n":9,"t":"「不可欺壓寄居的；因為你們在埃及地作過寄居的，知道寄居的心。」","notes":[]},{"n":10,"t":"「六年你要耕種田地，收藏土產，","notes":[],"heads":["安息年和安息日"]},{"n":11,"t":"只是第七年要叫地歇息，不耕不種，使你民中的窮人有吃的；他們所剩下的，野獸可以吃。你的葡萄園和橄欖園也要照樣辦理。","notes":[]},{"n":12,"t":"「六日你要做工，第七日要安息，使牛、驢可以歇息，並使你婢女的兒子和寄居的都可以舒暢。","notes":[]},{"n":13,"t":"「凡我對你們說的話，你們要謹守。別神的名，你不可提，也不可從你口中傳說。」","notes":[]},{"n":14,"t":"「一年三次，你要向我守節。","notes":[],"heads":["三大節期"]},{"n":15,"t":"你要守除酵節，照我所吩咐你的，在亞筆月內所定的日期，吃無酵餅七天。誰也不可空手朝見我，因為你是這月出了埃及。","notes":[]},{"n":16,"t":"又要守收割節，所收的是你田間所種、勞碌得來初熟之物。並在年底收藏，要守收藏節。","notes":[]},{"n":17,"t":"一切的男丁要一年三次朝見主耶和華。","notes":[]},{"n":18,"t":"「不可將我祭牲的血和有酵的餅一同獻上；也不可將我節上祭牲的脂油留到早晨。","notes":[]},{"n":19,"t":"「地裏首先初熟之物要送到耶和華－你神的殿。「不可用山羊羔母的奶煮山羊羔。」","notes":[]},{"n":20,"t":"「看哪，我差遣使者在你前面，在路上保護你，領你到我所預備的地方去。","notes":[],"heads":["應許和指示"]},{"n":21,"t":"他是奉我名來的；你們要在他面前謹慎，聽從他的話，不可惹 他，因為他必不赦免你們的過犯。","notes":["或譯：違背"]},{"n":22,"t":"「你若實在聽從他的話，照著我一切所說的去行，我就向你的仇敵作仇敵，向你的敵人作敵人。","notes":[]},{"n":23,"t":"「我的使者要在你前面行，領你到亞摩利人、赫人、比利洗人、迦南人、希未人、耶布斯人那裏去，我必將他們剪除。","notes":[]},{"n":24,"t":"你不可跪拜他們的神，不可事奉他，也不可效法他們的行為，卻要把神像盡行拆毀，打碎他們的柱像。","notes":[]},{"n":25,"t":"你們要事奉耶和華－你們的神，他必賜福與你的糧與你的水，也必從你們中間除去疾病。","notes":[]},{"n":26,"t":"你境內必沒有墜胎的，不生產的。我要使你滿了你年日的數目。","notes":[]},{"n":27,"t":"凡你所到的地方，我要使那裏的眾民在你面前驚駭，擾亂，又要使你一切仇敵轉背逃跑。","notes":[]},{"n":28,"t":"我要打發黃蜂飛在你前面，把希未人、迦南人、赫人攆出去。","notes":[]},{"n":29,"t":"我不在一年之內將他們從你面前攆出去，恐怕地成為荒涼，野地的獸多起來害你。","notes":[]},{"n":30,"t":"我要漸漸地將他們從你面前攆出去，等到你的人數加多，承受那地為業。","notes":[]},{"n":31,"t":"我要定你的境界，從紅海直到非利士海，又從曠野直到大河。我要將那地的居民交在你手中，你要將他們從你面前攆出去。","notes":[]},{"n":32,"t":"不可和他們並他們的神立約。","notes":[]},{"n":33,"t":"他們不可住在你的地上，恐怕他們使你得罪我。你若事奉他們的神，這必成為你的網羅。」","notes":[]}]},"24":{"heading":"立約的憑據","verses":[{"n":1,"t":"耶和華對摩西說：「你和亞倫、拿答、亞比戶，並以色列長老中的七十人，都要上到我這裏來，遠遠地下拜。","notes":[]},{"n":2,"t":"惟獨你可以親近耶和華；他們卻不可親近；百姓也不可和你一同上來。」","notes":[]},{"n":3,"t":"摩西下山，將耶和華的命令典章都述說與百姓聽。眾百姓齊聲說：「耶和華所吩咐的，我們都必遵行。」","notes":[]},{"n":4,"t":"摩西將耶和華的命令都寫上。清早起來，在山下築一座壇，按以色列十二支派立十二根柱子，","notes":[]},{"n":5,"t":"又打發以色列人中的少年人去獻燔祭，又向耶和華獻牛為平安祭。","notes":[]},{"n":6,"t":"摩西將血一半盛在盆中，一半灑在壇上；","notes":[]},{"n":7,"t":"又將約書念給百姓聽。他們說：「耶和華所吩咐的，我們都必遵行。」","notes":[]},{"n":8,"t":"摩西將血灑在百姓身上，說：「你看！這是立約的血，是耶和華按這一切話與你們立約的憑據。」","notes":[]},{"n":9,"t":"摩西、亞倫、拿答、亞比戶，並以色列長老中的七十人，都上了山。","notes":[]},{"n":10,"t":"他們看見以色列的神，他腳下彷彿有平鋪的藍寶石，如同天色明淨。","notes":[]},{"n":11,"t":"他的手不加害在以色列的尊者身上。他們觀看神；他們又吃又喝。","notes":[]},{"n":12,"t":"耶和華對摩西說：「你上山到我這裏來，住在這裏，我要將石版並我所寫的律法和誡命賜給你，使你可以教訓百姓。」","notes":[],"heads":["摩西在西奈山上"]},{"n":13,"t":"摩西和他的幫手約書亞起來，上了神的山。","notes":[]},{"n":14,"t":"摩西對長老說：「你們在這裏等著，等到我們再回來，有亞倫、戶珥與你們同在。凡有爭訟的，都可以就近他們去。」","notes":[]},{"n":15,"t":"摩西上山，有雲彩把山遮蓋。","notes":[]},{"n":16,"t":"耶和華的榮耀停於西奈山；雲彩遮蓋山六天，第七天他從雲中召摩西。","notes":[]},{"n":17,"t":"耶和華的榮耀在山頂上，在以色列人眼前，形狀如烈火。","notes":[]},{"n":18,"t":"摩西進入雲中上山，在山上四十晝夜。","notes":[]}]},"25":{"heading":"奉獻聖所","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「你告訴以色列人當為我送禮物來；凡甘心樂意的，你們就可以收下歸我。","notes":[]},{"n":3,"t":"所要收的禮物：就是金、銀、銅，","notes":[]},{"n":4,"t":"藍色、紫色、朱紅色線，細麻，山羊毛，","notes":[]},{"n":5,"t":"染紅的公羊皮，海狗皮，皂莢木，","notes":[]},{"n":6,"t":"點燈的油並做膏油和香的香料，","notes":[]},{"n":7,"t":"紅瑪瑙與別樣的寶石，可以鑲嵌在以弗得和胸牌上。","notes":[]},{"n":8,"t":"又當為我造聖所，使我可以住在他們中間。","notes":[]},{"n":9,"t":"製造帳幕和其中的一切器具都要照我所指示你的樣式。」","notes":[]},{"n":10,"t":"「要用皂莢木做一櫃，長二肘半，寬一肘半，高一肘半。","notes":[],"heads":["約櫃"]},{"n":11,"t":"要裏外包上精金，四圍鑲上金牙邊。","notes":[]},{"n":12,"t":"也要鑄四個金環，安在櫃的四腳上；這邊兩環，那邊兩環。","notes":[]},{"n":13,"t":"要用皂莢木做兩根槓，用金包裹。","notes":[]},{"n":14,"t":"要把槓穿在櫃旁的環內，以便抬櫃。","notes":[]},{"n":15,"t":"這槓要常在櫃的環內，不可抽出來。","notes":[]},{"n":16,"t":"必將我所要賜給你的法版放在櫃裏。","notes":[]},{"n":17,"t":"要用精金做施恩座 ，長二肘半，寬一肘半。","notes":["施恩：或譯蔽罪；下同"]},{"n":18,"t":"要用金子錘出兩個基路伯來，安在施恩座的兩頭。","notes":[]},{"n":19,"t":"這頭做一個基路伯，那頭做一個基路伯，二基路伯要接連一塊，在施恩座的兩頭。","notes":[]},{"n":20,"t":"二基路伯要高張翅膀，遮掩施恩座。基路伯要臉對臉，朝著施恩座。","notes":[]},{"n":21,"t":"要將施恩座安在櫃的上邊，又將我所要賜給你的法版放在櫃裏。","notes":[]},{"n":22,"t":"我要在那裏與你相會，又要從法櫃施恩座上二基路伯中間，和你說我所要吩咐你傳給以色列人的一切事。」","notes":[]},{"n":23,"t":"「要用皂莢木做一張桌子，長二肘，寬一肘，高一肘半。","notes":[],"heads":["陳設餅的桌子"]},{"n":24,"t":"要包上精金，四圍鑲上金牙邊。","notes":[]},{"n":25,"t":"桌子的四圍各做一掌寬的橫樑，橫樑上鑲著金牙邊。","notes":[]},{"n":26,"t":"要做四個金環，安在桌子的四角上，就是桌子四腳上的四角。","notes":[]},{"n":27,"t":"安環子的地方要挨近橫樑，可以穿槓抬桌子。","notes":[]},{"n":28,"t":"要用皂莢木做兩根槓，用金包裹，以便抬桌子。","notes":[]},{"n":29,"t":"要做桌子上的盤子、調羹，並奠酒的爵和瓶；這都要用精金製作。","notes":[]},{"n":30,"t":"又要在桌子上，在我面前，常擺陳設餅。」","notes":[]},{"n":31,"t":"「要用精金做一個燈臺。燈臺的座和幹與杯、球、花，都要接連一塊錘出來。","notes":[],"heads":["燈臺"]},{"n":32,"t":"燈臺兩旁要杈出六個枝子：這旁三個，那旁三個。","notes":[]},{"n":33,"t":"這旁每枝上有三個杯，形狀像杏花，有球，有花；那旁每枝上也有三個杯，形狀像杏花，有球，有花。從燈臺杈出來的六個枝子都是如此。","notes":[]},{"n":34,"t":"燈臺上有四個杯，形狀像杏花，有球，有花。","notes":[]},{"n":35,"t":"燈臺每兩個枝子以下有球與枝子接連一塊。燈臺出的六個枝子都是如此。","notes":[]},{"n":36,"t":"球和枝子要接連一塊，都是一塊精金錘出來的。","notes":[]},{"n":37,"t":"要做燈臺的七個燈盞。祭司要點這燈，使燈光對照。","notes":[]},{"n":38,"t":"燈臺的蠟剪和蠟花盤也是要精金的。","notes":[]},{"n":39,"t":"做燈臺和這一切的器具要用精金一他連得。","notes":[]},{"n":40,"t":"要謹慎做這些物件，都要照著在山上指示你的樣式。」","notes":[]}]},"26":{"heading":"會幕","verses":[{"n":1,"t":"「你要用十幅幔子做帳幕。這些幔子要用撚的細麻和藍色、紫色、朱紅色線製造，並用巧匠的手工繡上基路伯。","notes":[]},{"n":2,"t":"每幅幔子要長二十八肘，寬四肘，幔子都要一樣的尺寸。","notes":[]},{"n":3,"t":"這五幅幔子要幅幅相連；那五幅幔子也要幅幅相連。","notes":[]},{"n":4,"t":"在這相連的幔子末幅邊上要做藍色的鈕扣；在那相連的幔子末幅邊上也要照樣做。","notes":[]},{"n":5,"t":"要在這相連的幔子上做五十個鈕扣；在那相連的幔子上也做五十個鈕扣，都要兩兩相對。","notes":[]},{"n":6,"t":"又要做五十個金鉤，用鉤使幔子相連，這才成了一個帳幕。","notes":[]},{"n":7,"t":"「你要用山羊毛織十一幅幔子，作為帳幕以上的罩棚。","notes":[]},{"n":8,"t":"每幅幔子要長三十肘，寬四肘；十一幅幔子都要一樣的尺寸。","notes":[]},{"n":9,"t":"要把五幅幔子連成一幅，又把六幅幔子連成一幅，這第六幅幔子要在罩棚的前面摺上去。","notes":[]},{"n":10,"t":"在這相連的幔子末幅邊上要做五十個鈕扣；在那相連的幔子末幅邊上也做五十個鈕扣。","notes":[]},{"n":11,"t":"又要做五十個銅鉤，鉤在鈕扣中，使罩棚連成一個。","notes":[]},{"n":12,"t":"罩棚的幔子所餘那垂下來的半幅幔子，要垂在帳幕的後頭。","notes":[]},{"n":13,"t":"罩棚的幔子所餘長的，這邊一肘，那邊一肘，要垂在帳幕的兩旁，遮蓋帳幕。","notes":[]},{"n":14,"t":"又要用染紅的公羊皮做罩棚的蓋；再用海狗皮做一層罩棚上的頂蓋。","notes":[]},{"n":15,"t":"「你要用皂莢木做帳幕的豎板。","notes":[]},{"n":16,"t":"每塊要長十肘，寬一肘半；","notes":[]},{"n":17,"t":"每塊必有兩榫相對。帳幕一切的板都要這樣做。","notes":[]},{"n":18,"t":"帳幕的南面要做板二十塊。","notes":[]},{"n":19,"t":"在這二十塊板底下要做四十個帶卯的銀座，兩卯接這塊板上的兩榫，兩卯接那塊板上的兩榫。","notes":[]},{"n":20,"t":"帳幕第二面，就是北面，也要做板二十塊","notes":[]},{"n":21,"t":"和帶卯的銀座四十個；這板底下有兩卯，那板底下也有兩卯。","notes":[]},{"n":22,"t":"帳幕的後面，就是西面，要做板六塊。","notes":[]},{"n":23,"t":"帳幕後面的拐角要做板兩塊。","notes":[]},{"n":24,"t":"板的下半截要雙的，上半截要整的，直頂到第一個環子；兩塊都要這樣做兩個拐角。","notes":[]},{"n":25,"t":"必有八塊板和十六個帶卯的銀座；這板底下有兩卯，那板底下也有兩卯。","notes":[]},{"n":26,"t":"「你要用皂莢木做閂：為帳幕這面的板做五閂，","notes":[]},{"n":27,"t":"為帳幕那面的板做五閂，又為帳幕後面的板做五閂。","notes":[]},{"n":28,"t":"板腰間的中閂要從這一頭通到那一頭。","notes":[]},{"n":29,"t":"板要用金子包裹，又要做板上的金環套閂；閂也要用金子包裹。","notes":[]},{"n":30,"t":"要照著在山上指示你的樣式立起帳幕。","notes":[]},{"n":31,"t":"「你要用藍色、紫色、朱紅色線，和撚的細麻織幔子，以巧匠的手工繡上基路伯。","notes":[]},{"n":32,"t":"要把幔子掛在四根包金的皂莢木柱子上，柱子上當有金鉤，柱子安在四個帶卯的銀座上。","notes":[]},{"n":33,"t":"要使幔子垂在鉤子下，把法櫃抬進幔子內；這幔子要將聖所和至聖所隔開。","notes":[]},{"n":34,"t":"又要把施恩座安在至聖所內的法櫃上，","notes":[]},{"n":35,"t":"把桌子安在幔子外帳幕的北面；把燈臺安在帳幕的南面，彼此相對。","notes":[]},{"n":36,"t":"「你要拿藍色、紫色、朱紅色線，和撚的細麻，用繡花的手工織帳幕的門簾。","notes":[]},{"n":37,"t":"要用皂莢木為簾子做五根柱子，用金子包裹。柱子上當有金鉤；又要為柱子用銅鑄造五個帶卯的座。」","notes":[]}]},"27":{"heading":"祭壇","verses":[{"n":1,"t":"「你要用皂莢木做壇。這壇要四方的，長五肘，寬五肘，高三肘。","notes":[]},{"n":2,"t":"要在壇的四拐角上做四個角，與壇接連一塊，用銅把壇包裹。","notes":[]},{"n":3,"t":"要做盆，收去壇上的灰，又做鏟子、盤子、肉鍤子、火鼎；壇上一切的器具都用銅做。","notes":[]},{"n":4,"t":"要為壇做一個銅網，在網的四角上做四個銅環，","notes":[]},{"n":5,"t":"把網安在壇四面的圍腰板以下，使網從下達到壇的半腰。","notes":[]},{"n":6,"t":"又要用皂莢木為壇做槓，用銅包裹。","notes":[]},{"n":7,"t":"這槓要穿在壇兩旁的環子內，用以抬壇。","notes":[]},{"n":8,"t":"要用板做壇，壇是空的，都照著在山上指示你的樣式做。」","notes":[]},{"n":9,"t":"「你要做帳幕的院子。院子的南面要用撚的細麻做帷子，長一百肘。","notes":[],"heads":["會幕的周圍"]},{"n":10,"t":"帷子的柱子要二十根，帶卯的銅座二十個。柱子上的鉤子和杆子都要用銀子做。","notes":[]},{"n":11,"t":"北面也當有帷子，長一百肘，帷子的柱子二十根，帶卯的銅座二十個。柱子上的鉤子和杆子都要用銀子做。","notes":[]},{"n":12,"t":"院子的西面當有帷子，寬五十肘，帷子的柱子十根，帶卯的座十個。","notes":[]},{"n":13,"t":"院子的東面要寬五十肘。","notes":[]},{"n":14,"t":"門這邊的帷子要十五肘，帷子的柱子三根，帶卯的座三個。","notes":[]},{"n":15,"t":"門那邊的帷子也要十五肘，帷子的柱子三根，帶卯的座三個。","notes":[]},{"n":16,"t":"院子的門當有簾子，長二十肘，要拿藍色、紫色、朱紅色線，和撚的細麻，用繡花的手工織成，柱子四根，帶卯的座四個。","notes":[]},{"n":17,"t":"院子四圍一切的柱子都要用銀杆連絡，柱子上的鉤子要用銀做，帶卯的座要用銅做。","notes":[]},{"n":18,"t":"院子要長一百肘，寬五十肘，高五肘，帷子要用撚的細麻做，帶卯的座要用銅做。","notes":[]},{"n":19,"t":"帳幕各樣用處的器具，並帳幕一切的橛子，和院子裏一切的橛子，都要用銅做。」","notes":[]},{"n":20,"t":"「你要吩咐以色列人，把那為點燈搗成的清橄欖油拿來給你，使燈常常點著。","notes":[],"heads":["燃燈的條例"]},{"n":21,"t":"在會幕中法櫃前的幔外，亞倫和他的兒子，從晚上到早晨，要在耶和華面前經理這燈。這要作以色列人世世代代永遠的定例。」","notes":[]}]},"28":{"heading":"祭司的聖服","verses":[{"n":1,"t":"「你要從以色列人中，使你的哥哥亞倫和他的兒子拿答、亞比戶、以利亞撒、以他瑪一同就近你，給我供祭司的職分。","notes":[]},{"n":2,"t":"你要給你哥哥亞倫做聖衣為榮耀，為華美。","notes":[]},{"n":3,"t":"又要吩咐一切心中有智慧的，就是我用智慧的靈所充滿的，給亞倫做衣服，使他分別為聖，可以給我供祭司的職分。","notes":[]},{"n":4,"t":"所要做的就是胸牌、以弗得、外袍、雜色的內袍、冠冕、腰帶，使你哥哥亞倫和他兒子穿這聖服，可以給我供祭司的職分。","notes":[]},{"n":5,"t":"要用金線和藍色、紫色、朱紅色線，並細麻去做。","notes":[]},{"n":6,"t":"「他們要拿金線和藍色、紫色、朱紅色線，並撚的細麻，用巧匠的手工做以弗得。","notes":[]},{"n":7,"t":"以弗得當有兩條肩帶，接上兩頭，使它相連。","notes":[]},{"n":8,"t":"其上巧工織的帶子，要和以弗得一樣的做法，用以束上，與以弗得接連一塊，要用金線和藍色、紫色、朱紅色線，並撚的細麻做成。","notes":[]},{"n":9,"t":"要取兩塊紅瑪瑙，在上面刻以色列兒子的名字：","notes":[]},{"n":10,"t":"六個名字在這塊寶石上，六個名字在那塊寶石上，都照他們生來的次序。","notes":[]},{"n":11,"t":"要用刻寶石的手工，彷彿刻圖書，按著以色列兒子的名字，刻這兩塊寶石，要鑲在金槽上。","notes":[]},{"n":12,"t":"要將這兩塊寶石安在以弗得的兩條肩帶上，為以色列人做紀念石。亞倫要在兩肩上擔他們的名字，在耶和華面前作為紀念。","notes":[]},{"n":13,"t":"要用金子做二槽，","notes":[]},{"n":14,"t":"又拿精金，用擰工彷彿擰繩子，做兩條鍊子，把這擰成的鍊子搭在二槽上。」","notes":[]},{"n":15,"t":"「你要用巧匠的手工做一個決斷的胸牌。要和以弗得一樣的做法：用金線和藍色、紫色、朱紅色線，並撚的細麻做成。","notes":[],"heads":["胸牌"]},{"n":16,"t":"這胸牌要四方的，疊為兩層，長一虎口，寬一虎口。","notes":[]},{"n":17,"t":"要在上面鑲寶石四行：第一行是紅寶石、紅璧璽、紅玉；","notes":[]},{"n":18,"t":"第二行是綠寶石、藍寶石、金鋼石；","notes":[]},{"n":19,"t":"第三行是紫瑪瑙、白瑪瑙、紫晶；","notes":[]},{"n":20,"t":"第四行是水蒼玉、紅瑪瑙、碧玉。這都要鑲在金槽中。","notes":[]},{"n":21,"t":"這些寶石都要按著以色列十二個兒子的名字，彷彿刻圖書，刻十二個支派的名字。","notes":[]},{"n":22,"t":"要在胸牌上用精金擰成如繩的鍊子。","notes":[]},{"n":23,"t":"在胸牌上也要做兩個金環，安在胸牌的兩頭。","notes":[]},{"n":24,"t":"要把那兩條擰成的金鍊子，穿過胸牌兩頭的環子。","notes":[]},{"n":25,"t":"又要把鍊子的那兩頭接在兩槽上，安在以弗得前面肩帶上。","notes":[]},{"n":26,"t":"要做兩個金環，安在胸牌的兩頭，在以弗得裏面的邊上。","notes":[]},{"n":27,"t":"又要做兩個金環，安在以弗得前面兩條肩帶的下邊，挨近相接之處，在以弗得巧工織的帶子以上。","notes":[]},{"n":28,"t":"要用藍細帶子把胸牌的環子與以弗得的環子繫住，使胸牌貼在以弗得巧工織的帶子上，不可與以弗得離縫。","notes":[]},{"n":29,"t":"亞倫進聖所的時候，要將決斷胸牌，就是刻著以色列兒子名字的，帶在胸前，在耶和華面前常作紀念。","notes":[]},{"n":30,"t":"又要將烏陵和土明放在決斷的胸牌裏；亞倫進到耶和華面前的時候，要帶在胸前，在耶和華面前常將以色列人的決斷牌帶在胸前。」","notes":[]},{"n":31,"t":"「你要做以弗得的外袍，顏色全是藍的。","notes":[],"heads":["祭司的其他聖服"]},{"n":32,"t":"袍上要為頭留一領口，口的周圍織出領邊來，彷彿鎧甲的領口，免得破裂。","notes":[]},{"n":33,"t":"袍子周圍底邊上要用藍色、紫色、朱紅色線做石榴。在袍子周圍的石榴中間要有金鈴鐺：","notes":[]},{"n":34,"t":"一個金鈴鐺一個石榴，一個金鈴鐺一個石榴，在袍子周圍的底邊上。","notes":[]},{"n":35,"t":"亞倫供職的時候要穿這袍子。他進聖所到耶和華面前，以及出來的時候，袍上的響聲必被聽見，使他不至於死亡。","notes":[]},{"n":36,"t":"「你要用精金做一面牌，在上面按刻圖書之法刻著『歸耶和華為聖』。","notes":[]},{"n":37,"t":"要用一條藍細帶子將牌繫在冠冕的前面。","notes":[]},{"n":38,"t":"這牌必在亞倫的額上，亞倫要擔當干犯聖物條例的罪孽；這聖物是以色列人在一切的聖禮物上所分別為聖的。這牌要常在他的額上，使他們可以在耶和華面前蒙悅納。","notes":[]},{"n":39,"t":"要用雜色細麻線織內袍，用細麻布做冠冕，又用繡花的手工做腰帶。","notes":[]},{"n":40,"t":"「你要為亞倫的兒子做內袍、腰帶、裹頭巾，為榮耀，為華美。","notes":[]},{"n":41,"t":"要把這些給你的哥哥亞倫和他的兒子穿戴，又要膏他們，將他們分別為聖，好給我供祭司的職分。","notes":[]},{"n":42,"t":"要給他們做細麻布褲子，遮掩下體；褲子當從腰達到大腿。","notes":[]},{"n":43,"t":"亞倫和他兒子進入會幕，或就近壇，在聖所供職的時候必穿上，免得擔罪而死。這要為亞倫和他的後裔作永遠的定例。」","notes":[]}]},"29":{"heading":"立亞倫和他子孫作祭司的條例","verses":[{"n":1,"t":"「你使亞倫和他兒子成聖，給我供祭司的職分，要如此行：取一隻公牛犢，兩隻無殘疾的公綿羊，","notes":[]},{"n":2,"t":"無酵餅和調油的無酵餅，與抹油的無酵薄餅；這都要用細麥麵做成。","notes":[]},{"n":3,"t":"這餅要裝在一個筐子裏，連筐子帶來，又把公牛和兩隻公綿羊牽來。","notes":[]},{"n":4,"t":"要使亞倫和他兒子到會幕門口來，用水洗身。","notes":[]},{"n":5,"t":"要給亞倫穿上內袍和以弗得的外袍，並以弗得，又帶上胸牌，束上以弗得巧工織的帶子。","notes":[]},{"n":6,"t":"把冠冕戴在他頭上，將聖冠加在冠冕上，","notes":[]},{"n":7,"t":"就把膏油倒在他頭上膏他。","notes":[]},{"n":8,"t":"要叫他的兒子來，給他們穿上內袍。","notes":[]},{"n":9,"t":"給亞倫和他兒子束上腰帶，包上裹頭巾，他們就憑永遠的定例得了祭司的職任。又要將亞倫和他兒子分別為聖。","notes":[]},{"n":10,"t":"「你要把公牛牽到會幕前，亞倫和他兒子要按手在公牛的頭上。","notes":[]},{"n":11,"t":"你要在耶和華面前，在會幕門口，宰這公牛。","notes":[]},{"n":12,"t":"要取些公牛的血，用指頭抹在壇的四角上，把血都倒在壇腳那裏。","notes":[]},{"n":13,"t":"要把一切蓋臟的脂油與肝上的網子，並兩個腰子和腰子上的脂油，都燒在壇上。","notes":[]},{"n":14,"t":"只是公牛的皮、肉、糞都要用火燒在營外。這牛是贖罪祭。","notes":[]},{"n":15,"t":"「你要牽一隻公綿羊來，亞倫和他兒子要按手在這羊的頭上。","notes":[]},{"n":16,"t":"要宰這羊，把血灑在壇的周圍。","notes":[]},{"n":17,"t":"要把羊切成塊子，洗淨五臟和腿，連塊子帶頭，都放在一處。","notes":[]},{"n":18,"t":"要把全羊燒在壇上，是給耶和華獻的燔祭，是獻給耶和華為馨香的火祭。","notes":[]},{"n":19,"t":"「你要將那一隻公綿羊牽來，亞倫和他兒子要按手在羊的頭上。","notes":[]},{"n":20,"t":"你要宰這羊，取點血抹在亞倫的右耳垂上和他兒子的右耳垂上，又抹在他們右手的大拇指上和右腳的大拇指上；並要把血灑在壇的四圍。","notes":[]},{"n":21,"t":"你要取點膏油和壇上的血，彈在亞倫和他的衣服上，並他兒子和他兒子的衣服上，他們和他們的衣服就一同成聖。","notes":[]},{"n":22,"t":"「你要取這羊的脂油和肥尾巴，並蓋臟的脂油與肝上的網子，兩個腰子和腰子上的脂油並右腿（這是承接聖職所獻的羊）。","notes":[]},{"n":23,"t":"再從耶和華面前裝無酵餅的筐子中取一個餅，一個調油的餅和一個薄餅，","notes":[]},{"n":24,"t":"都放在亞倫的手上和他兒子的手上，作為搖祭，在耶和華面前搖一搖。","notes":[]},{"n":25,"t":"要從他們手中接過來，燒在耶和華面前壇上的燔祭上，是獻給耶和華為馨香的火祭。","notes":[]},{"n":26,"t":"「你要取亞倫承接聖職所獻公羊的胸，作為搖祭，在耶和華面前搖一搖，這就可以作你的分。","notes":[]},{"n":27,"t":"那搖祭的胸和舉祭的腿，就是承接聖職所搖的、所舉的，是歸亞倫和他兒子的。這些你都要成為聖，","notes":[]},{"n":28,"t":"作亞倫和他子孫從以色列人中永遠所得的分，因為是舉祭。這要從以色列人的平安祭中，作為獻給耶和華的舉祭。","notes":[]},{"n":29,"t":"「亞倫的聖衣要留給他的子孫，可以穿著受膏，又穿著承接聖職。","notes":[]},{"n":30,"t":"他的子孫接續他當祭司的，每逢進會幕在聖所供職的時候，要穿七天。","notes":[]},{"n":31,"t":"「你要將承接聖職所獻公羊的肉煮在聖處。","notes":[]},{"n":32,"t":"亞倫和他兒子要在會幕門口吃這羊的肉和筐內的餅。","notes":[]},{"n":33,"t":"他們吃那些贖罪之物，好承接聖職，使他們成聖；只是外人不可吃，因為這是聖物。","notes":[]},{"n":34,"t":"那承接聖職所獻的肉或餅，若有一點留到早晨，就要用火燒了，不可吃這物，因為是聖物。","notes":[]},{"n":35,"t":"「你要這樣照我一切所吩咐的，向亞倫和他兒子行承接聖職的禮七天。","notes":[]},{"n":36,"t":"每天要獻公牛一隻為贖罪祭。你潔淨壇的時候，壇就潔淨了；且要用膏抹壇，使壇成聖。","notes":[]},{"n":37,"t":"要潔淨壇七天，使壇成聖，壇就成為至聖。凡挨著壇的都成為聖。」","notes":[]},{"n":38,"t":"「你每天所要獻在壇上的就是兩隻一歲的羊羔；","notes":[],"heads":["每天當獻的祭"]},{"n":39,"t":"早晨要獻這一隻，黃昏的時候要獻那一隻。","notes":[]},{"n":40,"t":"和這一隻羊羔同獻的，要用細麵伊法十分之一與搗成的油一欣四分之一調和，又用酒一欣四分之一作為奠祭。","notes":[]},{"n":41,"t":"那一隻羊羔要在黃昏的時候獻上，照著早晨的素祭和奠祭的禮辦理，作為獻給耶和華馨香的火祭。","notes":[]},{"n":42,"t":"這要在耶和華面前、會幕門口，作你們世世代代常獻的燔祭。我要在那裏與你們相會，和你們說話。","notes":[]},{"n":43,"t":"我要在那裏與以色列人相會，會幕就要因我的榮耀成為聖。","notes":[]},{"n":44,"t":"我要使會幕和壇成聖，也要使亞倫和他的兒子成聖，給我供祭司的職分。","notes":[]},{"n":45,"t":"我要住在以色列人中間，作他們的神。","notes":[]},{"n":46,"t":"他們必知道我是耶和華－他們的神，是將他們從埃及地領出來的，為要住在他們中間。我是耶和華－他們的神。」","notes":[]}]},"30":{"heading":"香壇","verses":[{"n":1,"t":"「你要用皂莢木做一座燒香的壇。","notes":[]},{"n":2,"t":"這壇要四方的，長一肘，寬一肘，高二肘；壇的四角要與壇接連一塊。","notes":[]},{"n":3,"t":"要用精金把壇的上面與壇的四圍，並壇的四角，包裹；又要在壇的四圍鑲上金牙邊。","notes":[]},{"n":4,"t":"要做兩個金環安在牙子邊以下，在壇的兩旁，兩根橫撐上，作為穿槓的用處，以便抬壇。","notes":[]},{"n":5,"t":"要用皂莢木做槓，用金包裹。","notes":[]},{"n":6,"t":"要把壇放在法櫃前的幔子外，對著法櫃上的施恩座，就是我要與你相會的地方。","notes":[]},{"n":7,"t":"亞倫在壇上要燒馨香料做的香；每早晨他收拾燈的時候，要燒這香。","notes":[]},{"n":8,"t":"黃昏點燈的時候，他要在耶和華面前燒這香，作為世世代代常燒的香。","notes":[]},{"n":9,"t":"在這壇上不可奉上異樣的香，不可獻燔祭、素祭，也不可澆上奠祭。","notes":[]},{"n":10,"t":"亞倫一年一次要在壇的角上行贖罪之禮。他一年一次要用贖罪祭牲的血在壇上行贖罪之禮，作為世世代代的定例。這壇在耶和華面前為至聖。」","notes":[]},{"n":11,"t":"耶和華曉諭摩西說：","notes":[],"heads":["會幕的捐獻"]},{"n":12,"t":"「你要按以色列人被數的，計算總數，你數的時候，他們各人要為自己的生命把贖價奉給耶和華，免得數的時候在他們中間有災殃。","notes":[]},{"n":13,"t":"凡過去歸那些被數之人的，每人要按聖所的平，拿銀子半舍客勒；這半舍客勒是奉給耶和華的禮物（一舍客勒是二十季拉）。","notes":[]},{"n":14,"t":"凡過去歸那些被數的人，從二十歲以外的，要將這禮物奉給耶和華。","notes":[]},{"n":15,"t":"他們為贖生命將禮物奉給耶和華，富足的不可多出，貧窮的也不可少出，各人要出半舍客勒。","notes":[]},{"n":16,"t":"你要從以色列人收這贖罪銀，作為會幕的使用，可以在耶和華面前為以色列人作紀念，贖生命。」","notes":[]},{"n":17,"t":"耶和華曉諭摩西說：","notes":[],"heads":["銅盆"]},{"n":18,"t":"「你要用銅做洗濯盆和盆座，以便洗濯。要將盆放在會幕和壇的中間，在盆裏盛水。","notes":[]},{"n":19,"t":"亞倫和他的兒子要在這盆裏洗手洗腳。","notes":[]},{"n":20,"t":"他們進會幕，或是就近壇前供職給耶和華獻火祭的時候，必用水洗濯，免得死亡。","notes":[]},{"n":21,"t":"他們洗手洗腳就免得死亡。這要作亞倫和他後裔世世代代永遠的定例。」","notes":[]},{"n":22,"t":"耶和華曉諭摩西說：","notes":[],"heads":["聖膏"]},{"n":23,"t":"「你要取上品的香料，就是流質的沒藥五百舍客勒，香肉桂一半，就是二百五十舍客勒，菖蒲二百五十舍客勒，","notes":[]},{"n":24,"t":"桂皮五百舍客勒，都按著聖所的平，又取橄欖油一欣，","notes":[]},{"n":25,"t":"按做香之法調和做成聖膏油。","notes":[]},{"n":26,"t":"要用這膏油抹會幕和法櫃，","notes":[]},{"n":27,"t":"桌子與桌子的一切器具，燈臺和燈臺的器具，並香壇、","notes":[]},{"n":28,"t":"燔祭壇，和壇的一切器具，洗濯盆和盆座。","notes":[]},{"n":29,"t":"要使這些物成為聖，好成為至聖；凡挨著的都成為聖。","notes":[]},{"n":30,"t":"要膏亞倫和他的兒子，使他們成為聖，可以給我供祭司的職分。","notes":[]},{"n":31,"t":"你要對以色列人說：『這油，我要世世代代以為聖膏油。","notes":[]},{"n":32,"t":"不可倒在別人的身上，也不可按這調和之法做與此相似的。這膏油是聖的，你們也要以為聖。","notes":[]},{"n":33,"t":"凡調和與此相似的，或將這膏膏在別人身上的，這人要從民中剪除。』」","notes":[]},{"n":34,"t":"耶和華吩咐摩西說：「你要取馨香的香料，就是拿他弗、施喜列、喜利比拿；這馨香的香料和淨乳香各樣要一般大的分量。","notes":[],"heads":["香的做法"]},{"n":35,"t":"你要用這些加上鹽，按做香之法做成清淨聖潔的香。","notes":[]},{"n":36,"t":"這香要取點搗得極細，放在會幕內、法櫃前，我要在那裏與你相會。你們要以這香為至聖。","notes":[]},{"n":37,"t":"你們不可按這調和之法為自己做香；要以這香為聖，歸耶和華。","notes":[]},{"n":38,"t":"凡做香和這香一樣，為要聞香味的，這人要從民中剪除。」","notes":[]}]},"31":{"heading":"會幕的技工","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「看哪，猶大支派中，戶珥的孫子、烏利的兒子比撒列，我已經提他的名召他。","notes":[]},{"n":3,"t":"我也以我的靈充滿了他，使他有智慧，有聰明，有知識，能做各樣的工，","notes":[]},{"n":4,"t":"能想出巧工，用金、銀、銅製造各物，","notes":[]},{"n":5,"t":"又能刻寶石，可以鑲嵌，能雕刻木頭，能做各樣的工。","notes":[]},{"n":6,"t":"我分派但支派中、亞希撒抹的兒子亞何利亞伯與他同工。凡心裏有智慧的，我更使他們有智慧，能做我一切所吩咐的，","notes":[]},{"n":7,"t":"就是會幕和法櫃，並其上的施恩座，與會幕中一切的器具，","notes":[]},{"n":8,"t":"桌子和桌子的器具，精金的燈臺和燈臺的一切器具並香壇，","notes":[]},{"n":9,"t":"燔祭壇和壇的一切器具，並洗濯盆與盆座，","notes":[]},{"n":10,"t":"精工做的禮服，和祭司亞倫並他兒子用以供祭司職分的聖衣，","notes":[]},{"n":11,"t":"膏油和為聖所用馨香的香料。他們都要照我一切所吩咐的去做。」","notes":[]},{"n":12,"t":"耶和華曉諭摩西說：","notes":[],"heads":["安息日"]},{"n":13,"t":"「你要吩咐以色列人說：『你們務要守我的安息日；因為這是你我之間世世代代的證據，使你們知道我－耶和華是叫你們成為聖的。","notes":[]},{"n":14,"t":"所以你們要守安息日，以為聖日。凡干犯這日的，必要把他治死；凡在這日做工的，必從民中剪除。","notes":[]},{"n":15,"t":"六日要做工，但第七日是安息聖日，是向耶和華守為聖的。凡在安息日做工的，必要把他治死。』","notes":[]},{"n":16,"t":"故此，以色列人要世世代代守安息日為永遠的約。","notes":[]},{"n":17,"t":"這是我和以色列人永遠的證據；因為六日之內耶和華造天地，第七日便安息舒暢。」","notes":[]},{"n":18,"t":"耶和華在西奈山和摩西說完了話，就把兩塊法版交給他，是神用指頭寫的石版。","notes":[]}]},"32":{"heading":"金牛犢","verses":[{"n":1,"t":"百姓見摩西遲延不下山，就大家聚集到亞倫那裏，對他說：「起來！為我們做神像，可以在我們前面引路；因為領我們出埃及地的那個摩西，我們不知道他遭了甚麼事。」","notes":[]},{"n":2,"t":"亞倫對他們說：「你們去摘下你們妻子、兒女耳上的金環，拿來給我。」","notes":[]},{"n":3,"t":"百姓就都摘下他們耳上的金環，拿來給亞倫。","notes":[]},{"n":4,"t":"亞倫從他們手裏接過來，鑄了一隻牛犢，用雕刻的器具做成。他們就說：「以色列啊，這是領你出埃及地的神。」","notes":[]},{"n":5,"t":"亞倫看見，就在牛犢面前築壇，且宣告說：「明日要向耶和華守節。」","notes":[]},{"n":6,"t":"次日清早，百姓起來獻燔祭和平安祭，就坐下吃喝，起來玩耍。","notes":[]},{"n":7,"t":"耶和華吩咐摩西說：「下去吧，因為你的百姓，就是你從埃及地領出來的，已經敗壞了。","notes":[]},{"n":8,"t":"他們快快偏離了我所吩咐的道，為自己鑄了一隻牛犢，向它下拜獻祭，說：『以色列啊，這就是領你出埃及地的神。』」","notes":[]},{"n":9,"t":"耶和華對摩西說：「我看這百姓真是硬著頸項的百姓。","notes":[]},{"n":10,"t":"你且由著我，我要向他們發烈怒，將他們滅絕，使你的後裔成為大國。」","notes":[]},{"n":11,"t":"摩西便懇求耶和華－他的神說：「耶和華啊，你為甚麼向你的百姓發烈怒呢？這百姓是你用大力和大能的手從埃及地領出來的。","notes":[]},{"n":12,"t":"為甚麼使埃及人議論說『他領他們出去，是要降禍與他們，把他們殺在山中，將他們從地上除滅』？求你轉意，不發你的烈怒，後悔，不降禍與你的百姓。","notes":[]},{"n":13,"t":"求你記念你的僕人亞伯拉罕、以撒、以色列。你曾指著自己起誓說：『我必使你們的後裔像天上的星那樣多，並且我所應許的這全地，必給你們的後裔，他們要永遠承受為業。』」","notes":[]},{"n":14,"t":"於是耶和華後悔，不把所說的禍降與他的百姓。","notes":[]},{"n":15,"t":"摩西轉身下山，手裏拿著兩塊法版。這版是兩面寫的，這面那面都有字，","notes":[]},{"n":16,"t":"是神的工作，字是神寫的，刻在版上。","notes":[]},{"n":17,"t":"約書亞一聽見百姓呼喊的聲音，就對摩西說：「在營裏有爭戰的聲音。」","notes":[]},{"n":18,"t":"摩西說：「這不是人打勝仗的聲音，也不是人打敗仗的聲音；我所聽見的乃是人歌唱的聲音。」","notes":[]},{"n":19,"t":"摩西挨近營前就看見牛犢，又看見人跳舞，便發烈怒，把兩塊版扔在山下摔碎了，","notes":[]},{"n":20,"t":"又將他們所鑄的牛犢用火焚燒，磨得粉碎，撒在水面上，叫以色列人喝。","notes":[]},{"n":21,"t":"摩西對亞倫說：「這百姓向你做了甚麼？你竟使他們陷在大罪裏！」","notes":[]},{"n":22,"t":"亞倫說：「求我主不要發烈怒。這百姓專於作惡，是你知道的。","notes":[]},{"n":23,"t":"他們對我說：『你為我們做神像，可以在我們前面引路；因為領我們出埃及地的那個摩西，我們不知道他遭了甚麼事。』","notes":[]},{"n":24,"t":"我對他們說：『凡有金環的可以摘下來』，他們就給了我。我把金環扔在火中，這牛犢便出來了。」","notes":[]},{"n":25,"t":"摩西見百姓放肆（亞倫縱容他們，使他們在仇敵中間被譏刺），","notes":[]},{"n":26,"t":"就站在營門中，說：「凡屬耶和華的，都要到我這裏來！」於是利未的子孫都到他那裏聚集。","notes":[]},{"n":27,"t":"他對他們說：「耶和華－以色列的神這樣說：『你們各人把刀跨在腰間，在營中往來，從這門到那門，各人殺他的弟兄與同伴並鄰舍。』」","notes":[]},{"n":28,"t":"利未的子孫照摩西的話行了。那一天百姓中被殺的約有三千。","notes":[]},{"n":29,"t":"摩西說：「今天你們要自潔，歸耶和華為聖，各人攻擊他的兒子和弟兄，使耶和華賜福與你們。」","notes":[]},{"n":30,"t":"到了第二天，摩西對百姓說：「你們犯了大罪。我如今要上耶和華那裏去，或者可以為你們贖罪。」","notes":[]},{"n":31,"t":"摩西回到耶和華那裏，說：「唉！這百姓犯了大罪，為自己做了金像。","notes":[]},{"n":32,"t":"倘或你肯赦免他們的罪..不然，求你從你所寫的冊上塗抹我的名。」","notes":[]},{"n":33,"t":"耶和華對摩西說：「誰得罪我，我就從我的冊上塗抹誰的名。","notes":[]},{"n":34,"t":"現在你去領這百姓，往我所告訴你的地方去，我的使者必在你前面引路；只是到我追討的日子，我必追討他們的罪。」","notes":[]},{"n":35,"t":"耶和華殺百姓的緣故是因他們同亞倫做了牛犢。","notes":[]}]},"33":{"heading":"耶和華吩咐以色列人離開西奈山","verses":[{"n":1,"t":"耶和華吩咐摩西說：「我曾起誓應許亞伯拉罕、以撒、雅各說：『要將迦南地賜給你的後裔。』現在你和你從埃及地所領出來的百姓，要從這裏往那地去。","notes":[]},{"n":2,"t":"我要差遣使者在你前面，攆出迦南人、亞摩利人、赫人、比利洗人、希未人、耶布斯人，","notes":[]},{"n":3,"t":"領你到那流奶與蜜之地。我自己不同你們上去；因為你們是硬著頸項的百姓，恐怕我在路上把你們滅絕。」","notes":[]},{"n":4,"t":"百姓聽見這凶信就悲哀，也沒有人佩戴妝飾。","notes":[]},{"n":5,"t":"耶和華對摩西說：「你告訴以色列人說：『耶和華說：你們是硬著頸項的百姓，我若一霎時臨到你們中間，必滅絕你們。現在你們要把身上的妝飾摘下來，使我可以知道怎樣待你們。』」","notes":[]},{"n":6,"t":"以色列人從住何烈山以後，就把身上的妝飾摘得乾淨。","notes":[]},{"n":7,"t":"摩西素常將帳棚支搭在營外，離營卻遠，他稱這帳棚為會幕。凡求問耶和華的，就到營外的會幕那裏去。","notes":[],"heads":["耶和華的會幕"]},{"n":8,"t":"當摩西出營到會幕去的時候，百姓就都起來，各人站在自己帳棚的門口，望著摩西，直等到他進了會幕。","notes":[]},{"n":9,"t":"摩西進會幕的時候，雲柱降下來，立在會幕的門前，耶和華便與摩西說話。","notes":[]},{"n":10,"t":"眾百姓看見雲柱立在會幕門前，就都起來，各人在自己帳棚的門口下拜。","notes":[]},{"n":11,"t":"耶和華與摩西面對面說話，好像人與朋友說話一般。摩西轉到營裏去，惟有他的幫手－一個少年人嫩的兒子約書亞不離開會幕。","notes":[]},{"n":12,"t":"摩西對耶和華說：「你吩咐我說：『將這百姓領上去』，卻沒有叫我知道你要打發誰與我同去，只說：『我按你的名認識你，你在我眼前也蒙了恩。』","notes":[],"heads":["耶和華應許跟百姓同在"]},{"n":13,"t":"我如今若在你眼前蒙恩，求你將你的道指示我，使我可以認識你，好在你眼前蒙恩。求你想到這民是你的民。」","notes":[]},{"n":14,"t":"耶和華說：「我必親自和你同去，使你得安息。」","notes":[]},{"n":15,"t":"摩西說：「你若不親自和我同去，就不要把我們從這裏領上去。","notes":[]},{"n":16,"t":"人在何事上得以知道我和你的百姓在你眼前蒙恩呢？豈不是因你與我們同去、使我和你的百姓與地上的萬民有分別嗎？」","notes":[]},{"n":17,"t":"耶和華對摩西說：「你這所求的我也要行；因為你在我眼前蒙了恩，並且我按你的名認識你。」","notes":[]},{"n":18,"t":"摩西說：「求你顯出你的榮耀給我看。」","notes":[]},{"n":19,"t":"耶和華說：「我要顯我一切的恩慈，在你面前經過，宣告我的名。我要恩待誰就恩待誰；要憐憫誰就憐憫誰」；","notes":[]},{"n":20,"t":"又說：「你不能看見我的面，因為人見我的面不能存活。」","notes":[]},{"n":21,"t":"耶和華說：「看哪，在我這裏有地方，你要站在磐石上。","notes":[]},{"n":22,"t":"我的榮耀經過的時候，我必將你放在磐石穴中，用我的手遮掩你，等我過去，","notes":[]},{"n":23,"t":"然後我要將我的手收回，你就得見我的背，卻不得見我的面。」","notes":[]}]},"34":{"heading":"復造法版","verses":[{"n":1,"t":"耶和華吩咐摩西說：「你要鑿出兩塊石版，和先前你摔碎的那版一樣；其上的字我要寫在這版上。","notes":[]},{"n":2,"t":"明日早晨，你要預備好了，上西奈山，在山頂上站在我面前。","notes":[]},{"n":3,"t":"誰也不可和你一同上去，遍山都不可有人，在山根也不可叫羊群牛群吃草。」","notes":[]},{"n":4,"t":"摩西就鑿出兩塊石版，和先前的一樣。清晨起來，照耶和華所吩咐的上西奈山去，手裏拿著兩塊石版。","notes":[]},{"n":5,"t":"耶和華在雲中降臨，和摩西一同站在那裏，宣告耶和華的名。","notes":[]},{"n":6,"t":"耶和華在他面前宣告說：「耶和華，耶和華，是有憐憫有恩典的神，不輕易發怒，並有豐盛的慈愛和誠實，","notes":[]},{"n":7,"t":"為千萬人存留慈愛，赦免罪孽、過犯，和罪惡，萬不以有罪的為無罪，必追討他的罪，自父及子，直到三、四代。」","notes":[]},{"n":8,"t":"摩西急忙伏地下拜，","notes":[]},{"n":9,"t":"說：「主啊，我若在你眼前蒙恩，求你在我們中間同行，因為這是硬著頸項的百姓。又求你赦免我們的罪孽和罪惡，以我們為你的產業。」","notes":[]},{"n":10,"t":"耶和華說：「我要立約，要在百姓面前行奇妙的事，是在遍地萬國中所未曾行的。在你四圍的外邦人就要看見耶和華的作為，因我向你所行的是可畏懼的事。","notes":[],"heads":["重新立約"]},{"n":11,"t":"「我今天所吩咐你的，你要謹守。我要從你面前攆出亞摩利人、迦南人、赫人、比利洗人、希未人、耶布斯人。","notes":[]},{"n":12,"t":"你要謹慎，不可與你所去那地的居民立約，恐怕成為你們中間的網羅；","notes":[]},{"n":13,"t":"卻要拆毀他們的祭壇，打碎他們的柱像，砍下他們的木偶。","notes":[]},{"n":14,"t":"不可敬拜別神；因為耶和華是忌邪的神，名為忌邪者。","notes":[]},{"n":15,"t":"只怕你與那地的居民立約，百姓隨從他們的神，就行邪淫，祭祀他們的神，有人叫你，你便吃他的祭物，","notes":[]},{"n":16,"t":"又為你的兒子娶他們的女兒為妻，他們的女兒隨從她們的神，就行邪淫，使你的兒子也隨從她們的神行邪淫。","notes":[]},{"n":17,"t":"「不可為自己鑄造神像。","notes":[]},{"n":18,"t":"「你要守除酵節，照我所吩咐你的，在亞筆月內所定的日期吃無酵餅七天，因為你是這亞筆月內出了埃及。","notes":[]},{"n":19,"t":"凡頭生的都是我的；一切牲畜頭生的，無論是牛是羊，公的都是我的。","notes":[]},{"n":20,"t":"頭生的驢要用羊羔代贖，若不代贖就要打折牠的頸項。凡頭生的兒子都要贖出來。誰也不可空手朝見我。","notes":[]},{"n":21,"t":"「你六日要做工，第七日要安息，雖在耕種收割的時候也要安息。","notes":[]},{"n":22,"t":"在收割初熟麥子的時候要守七七節；又在年底要守收藏節。","notes":[]},{"n":23,"t":"你們一切男丁要一年三次朝見主耶和華－以色列的神。","notes":[]},{"n":24,"t":"我要從你面前趕出外邦人，擴張你的境界。你一年三次上去朝見耶和華－你神的時候，必沒有人貪慕你的地土。","notes":[]},{"n":25,"t":"「你不可將我祭物的血和有酵的餅一同獻上。逾越節的祭物也不可留到早晨。","notes":[]},{"n":26,"t":"地裏首先初熟之物要送到耶和華－你神的殿。不可用山羊羔母的奶煮山羊羔。」","notes":[]},{"n":27,"t":"耶和華吩咐摩西說：「你要將這些話寫上，因為我是按這話與你和以色列人立約。」","notes":[]},{"n":28,"t":"摩西在耶和華那裏四十晝夜，也不吃飯也不喝水。耶和華將這約的話，就是十條誡，寫在兩塊版上。","notes":[]},{"n":29,"t":"摩西手裏拿著兩塊法版下西奈山的時候，不知道自己的面皮因耶和華和他說話就發了光。","notes":[],"heads":["摩西下西奈山"]},{"n":30,"t":"亞倫和以色列眾人看見摩西的面皮發光就怕挨近他。","notes":[]},{"n":31,"t":"摩西叫他們來；於是亞倫和會眾的官長都到他那裏去，摩西就與他們說話。","notes":[]},{"n":32,"t":"隨後以色列眾人都近前來，他就把耶和華在西奈山與他所說的一切話都吩咐他們。","notes":[]},{"n":33,"t":"摩西與他們說完了話就用帕子蒙上臉。","notes":[]},{"n":34,"t":"但摩西進到耶和華面前與他說話就揭去帕子，及至出來的時候便將耶和華所吩咐的告訴以色列人。","notes":[]},{"n":35,"t":"以色列人看見摩西的面皮發光。摩西又用帕子蒙上臉，等到他進去與耶和華說話就揭去帕子。","notes":[]}]},"35":{"heading":"安息日的條例","verses":[{"n":1,"t":"摩西招聚以色列全會眾，對他們說：「這是耶和華所吩咐的話，叫你們照著行：","notes":[]},{"n":2,"t":"六日要做工，第七日乃為聖日，當向耶和華守為安息聖日。凡這日之內做工的，必把他治死。","notes":[]},{"n":3,"t":"當安息日，不可在你們一切的住處生火。」","notes":[]},{"n":4,"t":"摩西對以色列全會眾說：「耶和華所吩咐的是這樣：","notes":[],"heads":["為會幕奉獻"]},{"n":5,"t":"你們中間要拿禮物獻給耶和華，凡樂意獻的可以拿耶和華的禮物來，就是金、銀、銅，","notes":[]},{"n":6,"t":"藍色、紫色、朱紅色線，細麻，山羊毛，","notes":[]},{"n":7,"t":"染紅的公羊皮，海狗皮，皂莢木，","notes":[]},{"n":8,"t":"點燈的油，並做膏油和香的香料，","notes":[]},{"n":9,"t":"紅瑪瑙與別樣的寶石，可以鑲嵌在以弗得和胸牌上。」","notes":[]},{"n":10,"t":"「你們中間凡心裏有智慧的都要來做耶和華一切所吩咐的：","notes":[],"heads":["會幕的器物"]},{"n":11,"t":"就是帳幕和帳幕的罩棚，並帳幕的蓋、鉤子、板、閂、柱子、帶卯的座，","notes":[]},{"n":12,"t":"櫃和櫃的槓，施恩座和遮掩櫃的幔子，","notes":[]},{"n":13,"t":"桌子和桌子的槓與桌子的一切器具，並陳設餅，","notes":[]},{"n":14,"t":"燈臺和燈臺的器具，燈盞並點燈的油，","notes":[]},{"n":15,"t":"香壇和壇的槓，膏油和馨香的香料，並帳幕門口的簾子，","notes":[]},{"n":16,"t":"燔祭壇和壇的銅網，壇的槓並壇的一切器具，洗濯盆和盆座，","notes":[]},{"n":17,"t":"院子的帷子和帷子的柱子，帶卯的座和院子的門簾，","notes":[]},{"n":18,"t":"帳幕的橛子並院子的橛子，和這兩處的繩子，","notes":[]},{"n":19,"t":"精工做的禮服和祭司亞倫並他兒子在聖所用以供祭司職分的聖衣。」","notes":[]},{"n":20,"t":"以色列全會眾從摩西面前退去。","notes":[],"heads":["百姓奉獻禮物"]},{"n":21,"t":"凡心裏受感和甘心樂意的都拿耶和華的禮物來，用以做會幕和其中一切的使用，又用以做聖衣。","notes":[]},{"n":22,"t":"凡心裏樂意獻禮物的，連男帶女，各將金器，就是胸前鍼、耳環、打印的戒指，和手釧帶來獻給耶和華。","notes":["或譯：鼻環"]},{"n":23,"t":"凡有藍色、紫色、朱紅色線，細麻，山羊毛，染紅的公羊皮，海狗皮的，都拿了來；","notes":[]},{"n":24,"t":"凡獻銀子和銅給耶和華為禮物的都拿了來；凡有皂莢木可做甚麼使用的也拿了來。","notes":[]},{"n":25,"t":"凡心中有智慧的婦女親手紡線，把所紡的藍色、紫色、朱紅色線，和細麻都拿了來。","notes":[]},{"n":26,"t":"凡有智慧、心裏受感的婦女就紡山羊毛。","notes":[]},{"n":27,"t":"眾官長把紅瑪瑙和別樣的寶石，可以鑲嵌在以弗得與胸牌上的，都拿了來；","notes":[]},{"n":28,"t":"又拿香料做香，拿油點燈，做膏油。","notes":[]},{"n":29,"t":"以色列人，無論男女，凡甘心樂意獻禮物給耶和華的，都將禮物拿來，做耶和華藉摩西所吩咐的一切工。","notes":[]},{"n":30,"t":"摩西對以色列人說：「猶大支派中，戶珥的孫子、烏利的兒子比撒列，耶和華已經提他的名召他，","notes":[],"heads":["造會幕的技工"]},{"n":31,"t":"又以神的靈充滿了他，使他有智慧、聰明、知識，能做各樣的工，","notes":[]},{"n":32,"t":"能想出巧工，用金、銀、銅製造各物，","notes":[]},{"n":33,"t":"又能刻寶石，可以鑲嵌，能雕刻木頭，能做各樣的巧工。","notes":[]},{"n":34,"t":"耶和華又使他，和但支派中亞希撒抹的兒子亞何利亞伯，心裏靈明，能教導人。","notes":[]},{"n":35,"t":"耶和華使他們的心滿有智慧，能做各樣的工，無論是雕刻的工，巧匠的工，用藍色、紫色、朱紅色線，和細麻、繡花的工，並機匠的工，他們都能做，也能想出奇巧的工。","notes":[]}]},"36":{"heading":"百姓奉獻禮物","verses":[{"n":1,"t":"「比撒列和亞何利亞伯，並一切心裏有智慧的，就是蒙耶和華賜智慧聰明、叫他知道做聖所各樣使用之工的，都要照耶和華所吩咐的做工。」","notes":[]},{"n":2,"t":"凡耶和華賜他心裏有智慧、而且受感前來做這工的，摩西把他們和比撒列並亞何利亞伯一同召來。","notes":[]},{"n":3,"t":"這些人就從摩西收了以色列人為做聖所並聖所使用之工所拿來的禮物。百姓每早晨還把甘心獻的禮物拿來。","notes":[]},{"n":4,"t":"凡做聖所一切工的智慧人各都離開他所做的工，","notes":[]},{"n":5,"t":"來對摩西說：「百姓為耶和華吩咐使用之工所拿來的，富富有餘。」","notes":[]},{"n":6,"t":"摩西傳命，他們就在全營中宣告說：「無論男女，不必再為聖所拿甚麼禮物來。」這樣才攔住百姓不再拿禮物來。","notes":[]},{"n":7,"t":"因為他們所有的材料夠做一切當做的物，而且有餘。","notes":[]},{"n":8,"t":"他們中間，凡心裏有智慧做工的，用十幅幔子做帳幕。這幔子是比撒列用撚的細麻和藍色、紫色、朱紅色線製造的，並用巧匠的手工繡上基路伯。","notes":[],"heads":["造耶和華的會幕"]},{"n":9,"t":"每幅幔子長二十八肘，寬四肘，都是一樣的尺寸。","notes":[]},{"n":10,"t":"他使這五幅幔子幅幅相連，又使那五幅幔子幅幅相連；","notes":[]},{"n":11,"t":"在這相連的幔子末幅邊上做藍色的鈕扣，在那相連的幔子末幅邊上也照樣做；","notes":[]},{"n":12,"t":"在這相連的幔子上做五十個鈕扣，在那相連的幔子上也做五十個鈕扣，都是兩兩相對；","notes":[]},{"n":13,"t":"又做五十個金鉤，使幔子相連。這才成了一個帳幕。","notes":[]},{"n":14,"t":"他用山羊毛織十一幅幔子，作為帳幕以上的罩棚。","notes":[]},{"n":15,"t":"每幅幔子長三十肘，寬四肘；十一幅幔子都是一樣的尺寸。","notes":[]},{"n":16,"t":"他把五幅幔子連成一幅，又把六幅幔子連成一幅；","notes":[]},{"n":17,"t":"在這相連的幔子末幅邊上做五十個鈕扣，在那相連的幔子末幅邊上也做五十個鈕扣；","notes":[]},{"n":18,"t":"又做五十個銅鉤，使罩棚連成一個；","notes":[]},{"n":19,"t":"並用染紅的公羊皮做罩棚的蓋，再用海狗皮做一層罩棚上的頂蓋。","notes":[]},{"n":20,"t":"他用皂莢木做帳幕的豎板。","notes":[]},{"n":21,"t":"每塊長十肘，寬一肘半；","notes":[]},{"n":22,"t":"每塊有兩榫相對。帳幕一切的板都是這樣做。","notes":[]},{"n":23,"t":"帳幕的南面做板二十塊。","notes":[]},{"n":24,"t":"在這二十塊板底下又做四十個帶卯的銀座：兩卯接這塊板上的兩榫，兩卯接那塊板上的兩榫。","notes":[]},{"n":25,"t":"帳幕的第二面，就是北面，也做板二十塊","notes":[]},{"n":26,"t":"和帶卯的銀座四十個：這板底下有兩卯，那板底下也有兩卯。","notes":[]},{"n":27,"t":"帳幕的後面，就是西面，做板六塊。","notes":[]},{"n":28,"t":"帳幕後面的拐角做板兩塊。","notes":[]},{"n":29,"t":"板的下半截是雙的，上半截是整的，直到第一個環子；在帳幕的兩個拐角上都是這樣做。","notes":[]},{"n":30,"t":"有八塊板和十六個帶卯的銀座，每塊板底下有兩卯。","notes":[]},{"n":31,"t":"他用皂莢木做閂：為帳幕這面的板做五閂，","notes":[]},{"n":32,"t":"為帳幕那面的板做五閂，又為帳幕後面的板做五閂，","notes":[]},{"n":33,"t":"使板腰間的中閂從這一頭通到那一頭。","notes":[]},{"n":34,"t":"用金子將板包裹，又做板上的金環套閂；閂也用金子包裹。","notes":[]},{"n":35,"t":"他用藍色、紫色、朱紅色線，和撚的細麻織幔子，以巧匠的手工繡上基路伯。","notes":[]},{"n":36,"t":"為幔子做四根皂莢木柱子，用金包裹，柱子上有金鉤，又為柱子鑄了四個帶卯的銀座。","notes":[]},{"n":37,"t":"拿藍色、紫色、朱紅色線，和撚的細麻，用繡花的手工織帳幕的門簾；","notes":[]},{"n":38,"t":"又為簾子做五根柱子和柱子上的鉤子，用金子把柱頂和柱子上的杆子包裹。柱子有五個帶卯的座，是銅的。","notes":[]}]},"37":{"heading":"造約櫃","verses":[{"n":1,"t":"比撒列用皂莢木做櫃，長二肘半，寬一肘半，高一肘半。","notes":[]},{"n":2,"t":"裏外包上精金，四圍鑲上金牙邊，","notes":[]},{"n":3,"t":"又鑄四個金環，安在櫃的四腳上：這邊兩環，那邊兩環。","notes":[]},{"n":4,"t":"用皂莢木做兩根槓，用金包裹。","notes":[]},{"n":5,"t":"把槓穿在櫃旁的環內，以便抬櫃。","notes":[]},{"n":6,"t":"用精金做施恩座，長二肘半，寬一肘半。","notes":[]},{"n":7,"t":"用金子錘出兩個基路伯來，安在施恩座的兩頭，","notes":[]},{"n":8,"t":"這頭做一個基路伯，那頭做一個基路伯，二基路伯接連一塊，在施恩座的兩頭。","notes":[]},{"n":9,"t":"二基路伯高張翅膀，遮掩施恩座；基路伯是臉對臉，朝著施恩座。","notes":[]},{"n":10,"t":"他用皂莢木做一張桌子，長二肘，寬一肘，高一肘半，","notes":[],"heads":["造陳設餅的桌子"]},{"n":11,"t":"又包上精金，四圍鑲上金牙邊。","notes":[]},{"n":12,"t":"桌子的四圍各做一掌寬的橫樑，橫樑上鑲著金牙邊，","notes":[]},{"n":13,"t":"又鑄了四個金環，安在桌子四腳的四角上。","notes":[]},{"n":14,"t":"安環子的地方是挨近橫梁，可以穿槓抬桌子。","notes":[]},{"n":15,"t":"他用皂莢木做兩根槓，用金包裹，以便抬桌子；","notes":[]},{"n":16,"t":"又用精金做桌子上的器皿，就是盤子、調羹，並奠酒的瓶和爵。","notes":[]},{"n":17,"t":"他用精金做一個燈臺；這燈臺的座和幹，與杯、球、花，都是接連一塊錘出來的。","notes":[],"heads":["造燈臺"]},{"n":18,"t":"燈臺兩旁杈出六個枝子：這旁三個，那旁三個。","notes":[]},{"n":19,"t":"這旁每枝上有三個杯，形狀像杏花，有球有花；那旁每枝上也有三個杯，形狀像杏花，有球有花。從燈臺杈出來的六個枝子都是如此。","notes":[]},{"n":20,"t":"燈臺上有四個杯，形狀像杏花，有球有花。","notes":[]},{"n":21,"t":"燈臺每兩個枝子以下有球，與枝子接連一塊；燈臺杈出的六個枝子都是如此。","notes":[]},{"n":22,"t":"球和枝子是接連一塊，都是一塊精金錘出來的。","notes":[]},{"n":23,"t":"用精金做燈臺的七個燈盞，並燈臺的蠟剪和蠟花盤。","notes":[]},{"n":24,"t":"他用精金一他連得做燈臺和燈臺的一切器具。","notes":[]},{"n":25,"t":"他用皂莢木做香壇，是四方的，長一肘，寬一肘，高二肘，壇的四角與壇接連一塊；","notes":[],"heads":["造香壇"]},{"n":26,"t":"又用精金把壇的上面與壇的四面並壇的四角包裹，又在壇的四圍鑲上金牙邊。","notes":[]},{"n":27,"t":"做兩個金環，安在牙子邊以下，在壇的兩旁、兩根橫撐上，作為穿槓的用處，以便抬壇。","notes":[]},{"n":28,"t":"用皂莢木做槓，用金包裹。","notes":[]},{"n":29,"t":"又按做香之法做聖膏油和馨香料的淨香。","notes":[],"heads":["造聖油和聖膏"]}]},"38":{"heading":"造燔祭壇","verses":[{"n":1,"t":"他用皂莢木做燔祭壇，是四方的，長五肘，寬五肘，高三肘，","notes":[]},{"n":2,"t":"在壇的四拐角上做四個角，與壇接連一塊，用銅把壇包裹。","notes":[]},{"n":3,"t":"他做壇上的盆、鏟子、盤子、肉鍤子、火鼎；這一切器具都是用銅做的。","notes":[]},{"n":4,"t":"又為壇做一個銅網，安在壇四面的圍腰板以下，從下達到壇的半腰。","notes":[]},{"n":5,"t":"為銅網的四角鑄四個環子，作為穿槓的用處。","notes":[]},{"n":6,"t":"用皂莢木做槓，用銅包裹，","notes":[]},{"n":7,"t":"把槓穿在壇兩旁的環子內，用以抬壇，並用板做壇；壇是空的。","notes":[]},{"n":8,"t":"他用銅做洗濯盆和盆座，是用會幕門前伺候的婦人之鏡子做的。","notes":[],"heads":["造銅盆"]},{"n":9,"t":"他做帳幕的院子。院子的南面用撚的細麻做帷子，寬一百肘。","notes":[],"heads":["耶和華會幕的周圍"]},{"n":10,"t":"帷子的柱子二十根，帶卯的銅座二十個；柱子上的鉤子和杆子都是用銀子做的。","notes":[]},{"n":11,"t":"北面也有帷子，寬一百肘。帷子的柱子二十根，帶卯的銅座二十個；柱子上的鉤子和杆子都是用銀子做的。","notes":[]},{"n":12,"t":"院子的西面有帷子，寬五十肘。帷子的柱子十根，帶卯的座十個；柱子的鉤子和杆子都是用銀子做的。","notes":[]},{"n":13,"t":"院子的東面，寬五十肘。","notes":[]},{"n":14,"t":"門這邊的帷子十五肘，那邊也是一樣。帷子的柱子三根，帶卯的座三個。在門的左右各有帷子十五肘，帷子的柱子三根，帶卯的座三個。","notes":[],"end":15},{"n":16,"t":"院子四面的帷子都是用撚的細麻做的。","notes":[]},{"n":17,"t":"柱子帶卯的座是銅的，柱子上的鉤子和杆子是銀的，柱頂是用銀子包的。院子一切的柱子都是用銀杆連絡的。","notes":[]},{"n":18,"t":"院子的門簾是以繡花的手工，用藍色、紫色、朱紅色線，和撚的細麻織的，寬二十肘，高五肘，與院子的帷子相配。","notes":[]},{"n":19,"t":"帷子的柱子四根，帶卯的銅座四個；柱子上的鉤子和杆子是銀的；柱頂是用銀子包的。","notes":[]},{"n":20,"t":"帳幕一切的橛子和院子四圍的橛子都是銅的。","notes":[]},{"n":21,"t":"這是法櫃的帳幕中利未人所用物件的總數，是照摩西的吩咐，經祭司亞倫的兒子以他瑪的手數點的。","notes":[],"heads":["耶和華會幕所用的金屬"]},{"n":22,"t":"凡耶和華所吩咐摩西的都是猶大支派戶珥的孫子、烏利的兒子比撒列做的。","notes":[]},{"n":23,"t":"與他同工的有但支派中亞希撒抹的兒子亞何利亞伯；他是雕刻匠，又是巧匠，又能用藍色、紫色、朱紅色線，和細麻繡花。","notes":[]},{"n":24,"t":"為聖所一切工作使用所獻的金子，按聖所的平，有二十九他連得並七百三十舍客勒。","notes":[]},{"n":25,"t":"會中被數的人所出的銀子，按聖所的平，有一百他連得並一千七百七十五舍客勒。","notes":[]},{"n":26,"t":"凡過去歸那些被數之人的，從二十歲以外，有六十萬零三千五百五十人。按聖所的平，每人出銀半舍客勒，就是一比加。","notes":[]},{"n":27,"t":"用那一百他連得銀子鑄造聖所帶卯的座和幔子柱子帶卯的座；一百他連得共一百帶卯的座，每帶卯的座用一他連得。","notes":[]},{"n":28,"t":"用那一千七百七十五舍客勒銀子做柱子上的鉤子，包裹柱頂並柱子上的杆子。","notes":[]},{"n":29,"t":"所獻的銅有七十他連得並二千四百舍客勒。","notes":[]},{"n":30,"t":"用這銅做會幕門帶卯的座和銅壇，並壇上的銅網和壇的一切器具，","notes":[]},{"n":31,"t":"並院子四圍帶卯的座和院門帶卯的座，與帳幕一切的橛子和院子四圍所有的橛子。","notes":[]}]},"39":{"heading":"為祭司製聖服","verses":[{"n":1,"t":"比撒列用藍色、紫色、朱紅色線做精緻的衣服，在聖所用以供職，又為亞倫做聖衣，是照耶和華所吩咐摩西的。","notes":[]},{"n":2,"t":"他用金線和藍色、紫色、朱紅色線，並撚的細麻做以弗得；","notes":[]},{"n":3,"t":"把金子錘成薄片，剪出線來，與藍色、紫色、朱紅色線，用巧匠的手工一同繡上。","notes":[]},{"n":4,"t":"又為以弗得做兩條相連的肩帶，接連在以弗得的兩頭。","notes":[]},{"n":5,"t":"其上巧工織的帶子和以弗得一樣的做法，用以束上，與以弗得接連一塊，是用金線和藍色、紫色、朱紅色線，並撚的細麻做的，是照耶和華所吩咐摩西的。","notes":[]},{"n":6,"t":"又琢出兩塊紅瑪瑙，鑲在金槽上，彷彿刻圖書，按著以色列兒子的名字雕刻；","notes":[]},{"n":7,"t":"將這兩塊寶石安在以弗得的兩條肩帶上，為以色列人做紀念石，是照耶和華所吩咐摩西的。","notes":[]},{"n":8,"t":"他用巧匠的手工做胸牌，和以弗得一樣的做法，用金線與藍色、紫色、朱紅色線，並撚的細麻做的。","notes":[],"heads":["製胸牌"]},{"n":9,"t":"胸牌是四方的，疊為兩層；這兩層長一虎口，寬一虎口，","notes":[]},{"n":10,"t":"上面鑲著寶石四行：第一行是紅寶石、紅璧璽、紅玉；","notes":[]},{"n":11,"t":"第二行是綠寶石、藍寶石、金鋼石；","notes":[]},{"n":12,"t":"第三行是紫瑪瑙、白瑪瑙、紫晶；","notes":[]},{"n":13,"t":"第四行是水蒼玉、紅瑪瑙、碧玉。這都鑲在金槽中。","notes":[]},{"n":14,"t":"這些寶石都是按著以色列十二個兒子的名字，彷彿刻圖書，刻十二個支派的名字。","notes":[]},{"n":15,"t":"在胸牌上，用精金擰成如繩子的鍊子。","notes":[]},{"n":16,"t":"又做兩個金槽和兩個金環，安在胸牌的兩頭。","notes":[]},{"n":17,"t":"把那兩條擰成的金鍊子穿過胸牌兩頭的環子，","notes":[]},{"n":18,"t":"又把鍊子的那兩頭接在兩槽上，安在以弗得前面肩帶上。","notes":[]},{"n":19,"t":"做兩個金環，安在胸牌的兩頭，在以弗得裏面的邊上，","notes":[]},{"n":20,"t":"又做兩個金環，安在以弗得前面兩條肩帶的下邊，挨近相接之處，在以弗得巧工織的帶子以上。","notes":[]},{"n":21,"t":"用一條藍細帶子把胸牌的環子和以弗得的環子繫住，使胸牌貼在以弗得巧工織的帶子上，不可與以弗得離縫，是照耶和華所吩咐摩西的。","notes":[]},{"n":22,"t":"他用織工做以弗得的外袍，顏色全是藍的。","notes":[],"heads":["祭司其他的聖服"]},{"n":23,"t":"袍上留一領口，口的周圍織出領邊來，彷彿鎧甲的領口，免得破裂。","notes":[]},{"n":24,"t":"在袍子底邊上，用藍色、紫色、朱紅色線，並撚的細麻做石榴，","notes":[]},{"n":25,"t":"又用精金做鈴鐺，把鈴鐺釘在袍子周圍底邊上的石榴中間：","notes":[]},{"n":26,"t":"一個鈴鐺一個石榴，一個鈴鐺一個石榴，在袍子周圍底邊上用以供職，是照耶和華所吩咐摩西的。","notes":[]},{"n":27,"t":"他用織成的細麻布為亞倫和他的兒子做內袍，","notes":[]},{"n":28,"t":"並用細麻布做冠冕和華美的裹頭巾，用撚的細麻布做褲子，","notes":[]},{"n":29,"t":"又用藍色、紫色、朱紅色線，並撚的細麻，以繡花的手工做腰帶，是照耶和華所吩咐摩西的。","notes":[]},{"n":30,"t":"他用精金做聖冠上的牌，在上面按刻圖書之法，刻著「歸耶和華為聖」。","notes":[]},{"n":31,"t":"又用一條藍細帶子將牌繫在冠冕上，是照耶和華所吩咐摩西的。","notes":[]},{"n":32,"t":"帳幕，就是會幕，一切的工就這樣做完了。凡耶和華所吩咐摩西的，以色列人都照樣做了。","notes":[],"heads":["會幕完工"]},{"n":33,"t":"他們送到摩西那裏。帳幕和帳幕的一切器具，就是鉤子、板、閂、柱子、帶卯的座，","notes":[]},{"n":34,"t":"染紅公羊皮的蓋、海狗皮的頂蓋，和遮掩櫃的幔子，","notes":[]},{"n":35,"t":"法櫃和櫃的槓並施恩座，","notes":[]},{"n":36,"t":"桌子和桌子的一切器具並陳設餅，","notes":[]},{"n":37,"t":"精金的燈臺和擺列的燈盞，與燈臺的一切器具，並點燈的油，","notes":[]},{"n":38,"t":"金壇、膏油、馨香的香料、會幕的門簾，","notes":[]},{"n":39,"t":"銅壇和壇上的銅網，壇的槓並壇的一切器具，洗濯盆和盆座，","notes":[]},{"n":40,"t":"院子的帷子和柱子，並帶卯的座，院子的門簾、繩子、橛子，並帳幕和會幕中一切使用的器具，","notes":[]},{"n":41,"t":"精工做的禮服，和祭司亞倫並他兒子在聖所用以供祭司職分的聖衣。","notes":[]},{"n":42,"t":"這一切工作都是以色列人照耶和華所吩咐摩西做的。","notes":[]},{"n":43,"t":"耶和華怎樣吩咐的，他們就怎樣做了。摩西看見一切的工都做成了，就給他們祝福。","notes":[]}]},"40":{"heading":"耶和華會幕的建立和奉獻","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「正月初一日，你要立起帳幕，","notes":[]},{"n":3,"t":"把法櫃安放在裏面，用幔子將櫃遮掩。","notes":[]},{"n":4,"t":"把桌子搬進去，擺設上面的物。把燈臺搬進去，點其上的燈。","notes":[]},{"n":5,"t":"把燒香的金壇安在法櫃前，掛上帳幕的門簾。","notes":[]},{"n":6,"t":"把燔祭壇安在帳幕門前。","notes":[]},{"n":7,"t":"把洗濯盆安在會幕和壇的中間，在盆裏盛水。","notes":[]},{"n":8,"t":"又在四圍立院帷，把院子的門簾掛上。","notes":[]},{"n":9,"t":"用膏油把帳幕和其中所有的都抹上，使帳幕和一切器具成聖，就都成聖。","notes":[]},{"n":10,"t":"又要抹燔祭壇和一切器具，使壇成聖，就都成為至聖。","notes":[]},{"n":11,"t":"要抹洗濯盆和盆座，使盆成聖。","notes":[]},{"n":12,"t":"要使亞倫和他兒子到會幕門口來，用水洗身。","notes":[]},{"n":13,"t":"要給亞倫穿上聖衣，又膏他，使他成聖，可以給我供祭司的職分；","notes":[]},{"n":14,"t":"又要使他兒子來，給他們穿上內袍。","notes":[]},{"n":15,"t":"怎樣膏他們的父親，也要照樣膏他們，使他們給我供祭司的職分。他們世世代代凡受膏的，就永遠當祭司的職任。」","notes":[]},{"n":16,"t":"摩西這樣行，都是照耶和華所吩咐他的。","notes":[]},{"n":17,"t":"第二年正月初一日，帳幕就立起來。","notes":[]},{"n":18,"t":"摩西立起帳幕，安上帶卯的座，立上板，穿上閂，立起柱子。","notes":[]},{"n":19,"t":"在帳幕以上搭罩棚，把罩棚的頂蓋蓋在其上，是照耶和華所吩咐他的。","notes":[]},{"n":20,"t":"又把法版放在櫃裏，把槓穿在櫃的兩旁，把施恩座安在櫃上。","notes":[]},{"n":21,"t":"把櫃抬進帳幕，掛上遮掩櫃的幔子，把法櫃遮掩了，是照耶和華所吩咐他的。","notes":[]},{"n":22,"t":"又把桌子安在會幕內，在帳幕北邊，在幔子外。","notes":[]},{"n":23,"t":"在桌子上將餅陳設在耶和華面前，是照耶和華所吩咐他的。","notes":[]},{"n":24,"t":"又把燈臺安在會幕內，在帳幕南邊，與桌子相對，","notes":[]},{"n":25,"t":"在耶和華面前點燈，是照耶和華所吩咐他的。","notes":[]},{"n":26,"t":"把金壇安在會幕內的幔子前，","notes":[]},{"n":27,"t":"在壇上燒了馨香料做的香，是照耶和華所吩咐他的。","notes":[]},{"n":28,"t":"又掛上帳幕的門簾。","notes":[]},{"n":29,"t":"在會幕的帳幕門前，安設燔祭壇，把燔祭和素祭獻在其上，是照耶和華所吩咐他的。","notes":[]},{"n":30,"t":"把洗濯盆安在會幕和壇的中間，盆中盛水，以便洗濯。","notes":[]},{"n":31,"t":"摩西和亞倫並亞倫的兒子在這盆裏洗手洗腳。","notes":[]},{"n":32,"t":"他們進會幕或就近壇的時候，便都洗濯，是照耶和華所吩咐他的。","notes":[]},{"n":33,"t":"在帳幕和壇的四圍立了院帷，把院子的門簾掛上。這樣，摩西就完了工。","notes":[]},{"n":34,"t":"當時，雲彩遮蓋會幕，耶和華的榮光就充滿了帳幕。","notes":[],"heads":["雲彩覆蓋會幕"]},{"n":35,"t":"摩西不能進會幕；因為雲彩停在其上，並且耶和華的榮光充滿了帳幕。","notes":[]},{"n":36,"t":"每逢雲彩從帳幕收上去，以色列人就起程前往；","notes":[]},{"n":37,"t":"雲彩若不收上去，他們就不起程，直等到雲彩收上去。","notes":[]},{"n":38,"t":"日間，耶和華的雲彩是在帳幕以上；夜間，雲中有火，在以色列全家的眼前。在他們所行的路上都是這樣。","notes":[]}]}},"LEV":{"1":{"heading":"燔祭的條例","verses":[{"n":1,"t":"耶和華從會幕中呼叫摩西，對他說：","notes":[]},{"n":2,"t":"「你曉諭以色列人說：你們中間若有人獻供物給耶和華，要從牛群羊群中獻牲畜為供物。","notes":[]},{"n":3,"t":"「他的供物若以牛為燔祭，就要在會幕門口獻一隻沒有殘疾的公牛，可以在耶和華面前蒙悅納。","notes":[]},{"n":4,"t":"他要按手在燔祭牲的頭上，燔祭便蒙悅納，為他贖罪。","notes":[]},{"n":5,"t":"他要在耶和華面前宰公牛；亞倫子孫作祭司的，要奉上血，把血灑在會幕門口、壇的周圍。","notes":[]},{"n":6,"t":"那人要剝去燔祭牲的皮，把燔祭牲切成塊子。","notes":[]},{"n":7,"t":"祭司亞倫的子孫要把火放在壇上，把柴擺在火上。","notes":[]},{"n":8,"t":"亞倫子孫作祭司的，要把肉塊和頭並脂油擺在壇上火的柴上。","notes":[]},{"n":9,"t":"但燔祭的臟腑與腿要用水洗。祭司就要把一切全燒在壇上，當作燔祭，獻與耶和華為馨香的火祭。","notes":[]},{"n":10,"t":"「人的供物若以綿羊或山羊為燔祭，就要獻上沒有殘疾的公羊。","notes":[]},{"n":11,"t":"要把羊宰於壇的北邊，在耶和華面前；亞倫子孫作祭司的，要把羊血灑在壇的周圍。","notes":[]},{"n":12,"t":"要把燔祭牲切成塊子，連頭和脂油，祭司就要擺在壇上火的柴上；","notes":[]},{"n":13,"t":"但臟腑與腿要用水洗，祭司就要全然奉獻，燒在壇上。這是燔祭，是獻與耶和華為馨香的火祭。","notes":[]},{"n":14,"t":"「人奉給耶和華的供物，若以鳥為燔祭，就要獻斑鳩或是雛鴿為供物。","notes":[]},{"n":15,"t":"祭司要把鳥拿到壇前，揪下頭來，把鳥燒在壇上；鳥的血要流在壇的旁邊；","notes":[]},{"n":16,"t":"又要把鳥的嗉子和髒物除掉，丟在壇的東邊倒灰的地方。","notes":["髒物：或譯翎毛"]},{"n":17,"t":"要拿著鳥的兩個翅膀，把鳥撕開，只是不可撕斷；祭司要在壇上、在火的柴上焚燒。這是燔祭，是獻與耶和華為馨香的火祭。」","notes":[]}]},"2":{"heading":"素祭的條例","verses":[{"n":1,"t":"「若有人獻素祭為供物給耶和華，要用細麵澆上油，加上乳香，","notes":[]},{"n":2,"t":"帶到亞倫子孫作祭司的那裏；祭司就要從細麵中取出一把來，並取些油和所有的乳香，然後要把所取的這些作為紀念，燒在壇上，是獻與耶和華為馨香的火祭。","notes":[]},{"n":3,"t":"素祭所剩的要歸給亞倫和他的子孫；這是獻與耶和華的火祭中為至聖的。","notes":[]},{"n":4,"t":"「若用爐中烤的物為素祭，就要用調油的無酵細麵餅，或是抹油的無酵薄餅。","notes":[]},{"n":5,"t":"若用鐵鏊上做的物為素祭，就要用調油的無酵細麵，","notes":[]},{"n":6,"t":"分成塊子，澆上油；這是素祭。","notes":[]},{"n":7,"t":"若用煎盤做的物為素祭，就要用油與細麵做成。","notes":[]},{"n":8,"t":"要把這些東西做的素祭帶到耶和華面前，並奉給祭司，帶到壇前。","notes":[]},{"n":9,"t":"祭司要從素祭中取出作為紀念的，燒在壇上，是獻與耶和華為馨香的火祭。","notes":[]},{"n":10,"t":"素祭所剩的要歸給亞倫和他的子孫。這是獻與耶和華的火祭中為至聖的。","notes":[]},{"n":11,"t":"「凡獻給耶和華的素祭都不可有酵；因為你們不可燒一點酵、一點蜜當作火祭獻給耶和華。","notes":[]},{"n":12,"t":"這些物要獻給耶和華作為初熟的供物，只是不可在壇上獻為馨香的祭。","notes":[]},{"n":13,"t":"凡獻為素祭的供物都要用鹽調和，在素祭上不可缺了你神立約的鹽。一切的供物都要配鹽而獻。","notes":[]},{"n":14,"t":"若向耶和華獻初熟之物為素祭，要獻上烘了的禾穗子，就是軋了的新穗子，當作初熟之物的素祭。","notes":[]},{"n":15,"t":"並要抹上油，加上乳香；這是素祭。","notes":[]},{"n":16,"t":"祭司要把其中作為紀念的，就是一些軋了的禾穗子和一些油，並所有的乳香，都焚燒，是向耶和華獻的火祭。」","notes":[]}]},"3":{"heading":"平安祭的條例","verses":[{"n":1,"t":"「人獻供物為平安祭，若是從牛群中獻，無論是公的是母的，必用沒有殘疾的獻在耶和華面前。","notes":["平安：或譯酬恩；下同"]},{"n":2,"t":"他要按手在供物的頭上，宰於會幕門口。亞倫子孫作祭司的，要把血灑在壇的周圍。","notes":[]},{"n":3,"t":"從平安祭中，將火祭獻給耶和華，也要把蓋臟的脂油和臟上所有的脂油，","notes":[]},{"n":4,"t":"並兩個腰子和腰子上的脂油，就是靠腰兩旁的脂油，與肝上的網子和腰子，一概取下。","notes":[]},{"n":5,"t":"亞倫的子孫要把這些燒在壇的燔祭上，就是在火的柴上，是獻與耶和華為馨香的火祭。","notes":[]},{"n":6,"t":"「人向耶和華獻供物為平安祭，若是從羊群中獻，無論是公的是母的，必用沒有殘疾的。","notes":[]},{"n":7,"t":"若獻一隻羊羔為供物，必在耶和華面前獻上，","notes":[]},{"n":8,"t":"並要按手在供物的頭上，宰於會幕前。亞倫的子孫要把血灑在壇的周圍。","notes":[]},{"n":9,"t":"從平安祭中，將火祭獻給耶和華，其中的脂油和整肥尾巴都要在靠近脊骨處取下，並要把蓋臟的脂油和臟上所有的脂油，","notes":[]},{"n":10,"t":"兩個腰子和腰子上的脂油，就是靠腰兩旁的脂油，並肝上的網子和腰子，一概取下。","notes":[]},{"n":11,"t":"祭司要在壇上焚燒，是獻給耶和華為食物的火祭。","notes":[]},{"n":12,"t":"「人的供物若是山羊，必在耶和華面前獻上。","notes":[]},{"n":13,"t":"要按手在山羊頭上，宰於會幕前。亞倫的子孫要把血灑在壇的周圍，","notes":[]},{"n":14,"t":"又把蓋臟的脂油和臟上所有的脂油，兩個腰子和腰子上的脂油，就是靠腰兩旁的脂油，並肝上的網子和腰子，一概取下，獻給耶和華為火祭。","notes":[],"end":15},{"n":16,"t":"祭司要在壇上焚燒，作為馨香火祭的食物。脂油都是耶和華的。","notes":[]},{"n":17,"t":"在你們一切的住處，脂油和血都不可吃；這要成為你們世世代代永遠的定例。」","notes":[]}]},"4":{"heading":"為誤犯的罪獻祭的條例","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你曉諭以色列人說：若有人在耶和華所吩咐不可行的甚麼事上誤犯了一件，","notes":[]},{"n":3,"t":"或是受膏的祭司犯罪，使百姓陷在罪裏，就當為他所犯的罪把沒有殘疾的公牛犢獻給耶和華為贖罪祭。","notes":[]},{"n":4,"t":"他要牽公牛到會幕門口，在耶和華面前按手在牛的頭上，把牛宰於耶和華面前。","notes":[]},{"n":5,"t":"受膏的祭司要取些公牛的血帶到會幕，","notes":[]},{"n":6,"t":"把指頭蘸於血中，在耶和華面前對著聖所的幔子彈血七次，","notes":[]},{"n":7,"t":"又要把些血抹在會幕內、耶和華面前香壇的四角上，再把公牛所有的血倒在會幕門口、燔祭壇的腳那裏。","notes":[]},{"n":8,"t":"要把贖罪祭公牛所有的脂油，乃是蓋臟的脂油和臟上所有的脂油，","notes":[]},{"n":9,"t":"並兩個腰子和腰子上的脂油，就是靠腰兩旁的脂油，與肝上的網子和腰子，一概取下，","notes":[]},{"n":10,"t":"與平安祭公牛上所取的一樣；祭司要把這些燒在燔祭的壇上。","notes":[]},{"n":11,"t":"公牛的皮和所有的肉，並頭、腿、臟、腑、糞，","notes":[]},{"n":12,"t":"就是全公牛，要搬到營外潔淨之地、倒灰之所，用火燒在柴上。","notes":[]},{"n":13,"t":"「以色列全會眾若行了耶和華所吩咐不可行的甚麼事，誤犯了罪，是隱而未現、會眾看不出來的，","notes":[]},{"n":14,"t":"會眾一知道所犯的罪就要獻一隻公牛犢為贖罪祭，牽到會幕前。","notes":[]},{"n":15,"t":"會中的長老就要在耶和華面前按手在牛的頭上，將牛在耶和華面前宰了。","notes":[]},{"n":16,"t":"受膏的祭司要取些公牛的血帶到會幕，","notes":[]},{"n":17,"t":"把指頭蘸於血中，在耶和華面前對著幔子彈血七次，","notes":[]},{"n":18,"t":"又要把些血抹在會幕內、耶和華面前壇的四角上，再把所有的血倒在會幕門口、燔祭壇的腳那裏。","notes":[]},{"n":19,"t":"把牛所有的脂油都取下，燒在壇上；","notes":[]},{"n":20,"t":"收拾這牛，與那贖罪祭的牛一樣。祭司要為他們贖罪，他們必蒙赦免。","notes":[]},{"n":21,"t":"他要把牛搬到營外燒了，像燒頭一個牛一樣；這是會眾的贖罪祭。","notes":[]},{"n":22,"t":"「官長若行了耶和華－他神所吩咐不可行的甚麼事，誤犯了罪，","notes":[]},{"n":23,"t":"所犯的罪自己知道了，就要牽一隻沒有殘疾的公山羊為供物，","notes":[]},{"n":24,"t":"按手在羊的頭上，宰於耶和華面前、宰燔祭牲的地方；這是贖罪祭。","notes":[]},{"n":25,"t":"祭司要用指頭蘸些贖罪祭牲的血，抹在燔祭壇的四角上，把血倒在燔祭壇的腳那裏。","notes":[]},{"n":26,"t":"所有的脂油，祭司都要燒在壇上，正如平安祭的脂油一樣。至於他的罪，祭司要為他贖了，他必蒙赦免。","notes":[]},{"n":27,"t":"「民中若有人行了耶和華所吩咐不可行的甚麼事，誤犯了罪，","notes":[]},{"n":28,"t":"所犯的罪自己知道了，就要為所犯的罪牽一隻沒有殘疾的母山羊為供物，","notes":[]},{"n":29,"t":"按手在贖罪祭牲的頭上，在那宰燔祭牲的地方宰了。","notes":[]},{"n":30,"t":"祭司要用指頭蘸些羊的血，抹在燔祭壇的四角上，所有的血都要倒在壇的腳那裏，","notes":[]},{"n":31,"t":"又要把羊所有的脂油都取下，正如取平安祭牲的脂油一樣。祭司要在壇上焚燒，在耶和華面前作為馨香的祭，為他贖罪，他必蒙赦免。","notes":[]},{"n":32,"t":"「人若牽一隻綿羊羔為贖罪祭的供物，必要牽一隻沒有殘疾的母羊，","notes":[]},{"n":33,"t":"按手在贖罪祭牲的頭上，在那宰燔祭牲的地方宰了作贖罪祭。","notes":[]},{"n":34,"t":"祭司要用指頭蘸些贖罪祭牲的血，抹在燔祭壇的四角上，所有的血都要倒在壇的腳那裏，","notes":[]},{"n":35,"t":"又要把所有的脂油都取下，正如取平安祭羊羔的脂油一樣。祭司要按獻給耶和華火祭的條例，燒在壇上。至於所犯的罪，祭司要為他贖了，他必蒙赦免。」","notes":[]}]},"5":{"heading":"贖愆祭的條例","verses":[{"n":1,"t":"「若有人聽見發誓的聲音，他本是見證，卻不把所看見的、所知道的說出來，這就是罪；他要擔當他的罪孽。","notes":["或譯：若有人聽見叫人發誓的聲音"]},{"n":2,"t":"或是有人摸了不潔的物，無論是不潔的死獸，是不潔的死畜，是不潔的死蟲，他卻不知道，因此成了不潔，就有了罪。","notes":[]},{"n":3,"t":"或是他摸了別人的污穢，無論是染了甚麼污穢，他卻不知道，一知道了就有了罪。","notes":[]},{"n":4,"t":"或是有人嘴裏冒失發誓，要行惡，要行善，無論人在甚麼事上冒失發誓，他卻不知道，一知道了就要在這其中的一件上有了罪。","notes":[]},{"n":5,"t":"他有了罪的時候，就要承認所犯的罪，","notes":[]},{"n":6,"t":"並要因所犯的罪，把他的贖愆祭牲－就是羊群中的母羊，或是一隻羊羔，或是一隻山羊－牽到耶和華面前為贖罪祭。至於他的罪，祭司要為他贖了。","notes":[]},{"n":7,"t":"「他的力量若不夠獻一隻羊羔，就要因所犯的罪，把兩隻斑鳩或是兩隻雛鴿帶到耶和華面前為贖愆祭：一隻作贖罪祭，一隻作燔祭。","notes":[]},{"n":8,"t":"把這些帶到祭司那裏，祭司就要先把那贖罪祭獻上，從鳥的頸項上揪下頭來，只是不可把鳥撕斷，","notes":[]},{"n":9,"t":"也把些贖罪祭牲的血彈在壇的旁邊，剩下的血要流在壇的腳那裏；這是贖罪祭。","notes":[]},{"n":10,"t":"他要照例獻第二隻為燔祭。至於他所犯的罪，祭司要為他贖了，他必蒙赦免。","notes":[]},{"n":11,"t":"「他的力量若不夠獻兩隻斑鳩或是兩隻雛鴿，就要因所犯的罪帶供物來，就是細麵伊法十分之一為贖罪祭；不可加上油，也不可加上乳香，因為是贖罪祭。","notes":[]},{"n":12,"t":"他要把供物帶到祭司那裏，祭司要取出自己的一把來作為紀念，按獻給耶和華火祭的條例燒在壇上；這是贖罪祭。","notes":[]},{"n":13,"t":"至於他在這幾件事中所犯的罪，祭司要為他贖了，他必蒙赦免。剩下的麵都歸與祭司，和素祭一樣。」","notes":[]},{"n":14,"t":"耶和華曉諭摩西說：","notes":[]},{"n":15,"t":"「人若在耶和華的聖物上誤犯了罪，有了過犯，就要照你所估的，按聖所的舍客勒拿銀子，將贖愆祭牲－就是羊群中一隻沒有殘疾的公綿羊－牽到耶和華面前為贖愆祭；","notes":[]},{"n":16,"t":"並且他因在聖物上的差錯要償還，另外加五分之一，都給祭司。祭司要用贖愆祭的公綿羊為他贖罪，他必蒙赦免。","notes":[]},{"n":17,"t":"「若有人犯罪，行了耶和華所吩咐不可行的甚麼事，他雖然不知道，還是有了罪，就要擔當他的罪孽；","notes":[]},{"n":18,"t":"也要照你所估定的價，從羊群中牽一隻沒有殘疾的公綿羊來，給祭司作贖愆祭。至於他誤行的那錯事，祭司要為他贖罪，他必蒙赦免。","notes":[]},{"n":19,"t":"這是贖愆祭，因他在耶和華面前實在有了罪。」","notes":[]}]},"6":{"heading":"祭司獻燔祭的責任","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「若有人犯罪，干犯耶和華，在鄰舍交付他的物上，或是在交易上行了詭詐，或是搶奪人的財物，或是欺壓鄰舍，","notes":[]},{"n":3,"t":"或是在撿了遺失的物上行了詭詐，說謊起誓，在這一切的事上犯了甚麼罪；","notes":[]},{"n":4,"t":"他既犯了罪，有了過犯，就要歸還他所搶奪的，或是因欺壓所得的，或是人交付他的，或是人遺失他所撿的物，","notes":[]},{"n":5,"t":"或是他因甚麼物起了假誓，就要如數歸還，另外加上五分之一，在查出他有罪的日子要交還本主。","notes":[]},{"n":6,"t":"也要照你所估定的價，把贖愆祭牲－就是羊群中一隻沒有殘疾的公綿羊－牽到耶和華面前，給祭司為贖愆祭。","notes":[]},{"n":7,"t":"祭司要在耶和華面前為他贖罪；他無論行了甚麼事，使他有了罪，都必蒙赦免。」","notes":[]},{"n":8,"t":"耶和華曉諭摩西說：","notes":[]},{"n":9,"t":"「你要吩咐亞倫和他的子孫說，燔祭的條例乃是這樣：燔祭要放在壇的柴上，從晚上到天亮，壇上的火要常常燒著。","notes":[]},{"n":10,"t":"祭司要穿上細麻布衣服，又要把細麻布褲子穿在身上，把壇上所燒的燔祭灰收起來，倒在壇的旁邊；","notes":[]},{"n":11,"t":"隨後要脫去這衣服，穿上別的衣服，把灰拿到營外潔淨之處。","notes":[]},{"n":12,"t":"壇上的火要在其上常常燒著，不可熄滅。祭司要每日早晨在上面燒柴，並要把燔祭擺在壇上，在其上燒平安祭牲的脂油。","notes":[]},{"n":13,"t":"在壇上必有常常燒著的火，不可熄滅。」","notes":[]},{"n":14,"t":"「素祭的條例乃是這樣：亞倫的子孫要在壇前把這祭獻在耶和華面前。","notes":[],"heads":["祭司獻素祭的責任"]},{"n":15,"t":"祭司要從其中－就是從素祭的細麵中－取出自己的一把，又要取些油和素祭上所有的乳香，燒在壇上，奉給耶和華為馨香素祭的紀念。","notes":[]},{"n":16,"t":"所剩下的，亞倫和他子孫要吃，必在聖處不帶酵而吃，要在會幕的院子裏吃。","notes":[]},{"n":17,"t":"烤的時候不可攙酵。這是從所獻給我的火祭中賜給他們的分，是至聖的，和贖罪祭並贖愆祭一樣。","notes":[]},{"n":18,"t":"凡獻給耶和華的火祭，亞倫子孫中的男丁都要吃這一分，直到萬代，作他們永得的分。摸這些祭物的，都要成為聖。」","notes":[]},{"n":19,"t":"耶和華曉諭摩西說：","notes":[]},{"n":20,"t":"「當亞倫受膏的日子，他和他子孫所要獻給耶和華的供物，就是細麵伊法十分之一，為常獻的素祭：早晨一半，晚上一半。","notes":[]},{"n":21,"t":"要在鐵鏊上用油調和做成，調勻了，你就拿進來；烤好了分成塊子，獻給耶和華為馨香的素祭。","notes":[]},{"n":22,"t":"亞倫的子孫中，接續他為受膏的祭司，要把這素祭獻上，要全燒給耶和華。這是永遠的定例。","notes":[]},{"n":23,"t":"祭司的素祭都要燒了，卻不可吃。」","notes":[]},{"n":24,"t":"耶和華曉諭摩西說：","notes":[],"heads":["祭司獻贖罪祭的責任"]},{"n":25,"t":"「你對亞倫和他的子孫說，贖罪祭的條例乃是這樣：要在耶和華面前、宰燔祭牲的地方宰贖罪祭牲；這是至聖的。","notes":[]},{"n":26,"t":"為贖罪獻這祭的祭司要吃，要在聖處，就是在會幕的院子裏吃。","notes":[]},{"n":27,"t":"凡摸這祭肉的要成為聖；這祭牲的血若彈在甚麼衣服上，所彈的那一件要在聖處洗淨。","notes":[]},{"n":28,"t":"惟有煮祭物的瓦器要打碎；若是煮在銅器裏，這銅器要擦磨，在水中涮淨。","notes":[]},{"n":29,"t":"凡祭司中的男丁都可以吃；這是至聖的。","notes":[]},{"n":30,"t":"凡贖罪祭，若將血帶進會幕在聖所贖罪，那肉都不可吃，必用火焚燒。」","notes":[]}]},"7":{"heading":"祭司獻贖愆祭的責任","verses":[{"n":1,"t":"「贖愆祭的條例乃是如此：這祭是至聖的。","notes":[]},{"n":2,"t":"人在那裏宰燔祭牲，也要在那裏宰贖愆祭牲；其血，祭司要灑在壇的周圍。","notes":[]},{"n":3,"t":"又要將肥尾巴和蓋臟的脂油，","notes":[]},{"n":4,"t":"兩個腰子和腰子上的脂油，就是靠腰兩旁的脂油，並肝上的網子和腰子，一概取下。","notes":[]},{"n":5,"t":"祭司要在壇上焚燒，為獻給耶和華的火祭，是贖愆祭。","notes":[]},{"n":6,"t":"祭司中的男丁都可以吃這祭物；要在聖處吃，是至聖的。","notes":[]},{"n":7,"t":"贖罪祭怎樣，贖愆祭也是怎樣，兩個祭是一個條例。獻贖愆祭贖罪的祭司要得這祭物。","notes":[]},{"n":8,"t":"獻燔祭的祭司，無論為誰奉獻，要親自得他所獻那燔祭牲的皮。","notes":[]},{"n":9,"t":"凡在爐中烤的素祭和煎盤中做的，並鐵鏊上做的，都要歸那獻祭的祭司。","notes":[]},{"n":10,"t":"凡素祭，無論是油調和的是乾的，都要歸亞倫的子孫，大家均分。」","notes":[]},{"n":11,"t":"「人獻與耶和華平安祭的條例乃是這樣：","notes":[],"heads":["祭司獻平安祭的責任"]},{"n":12,"t":"他若為感謝獻上，就要用調油的無酵餅和抹油的無酵薄餅，並用油調勻細麵做的餅，與感謝祭一同獻上。","notes":[]},{"n":13,"t":"要用有酵的餅和為感謝獻的平安祭，與供物一同獻上。","notes":[]},{"n":14,"t":"從各樣的供物中，他要把一個餅獻給耶和華為舉祭，是要歸給灑平安祭牲血的祭司。","notes":[]},{"n":15,"t":"為感謝獻平安祭牲的肉，要在獻的日子吃，一點不可留到早晨。","notes":[]},{"n":16,"t":"若所獻的是為還願，或是甘心獻的，必在獻祭的日子吃，所剩下的第二天也可以吃。","notes":[]},{"n":17,"t":"但所剩下的祭肉，到第三天要用火焚燒；","notes":[]},{"n":18,"t":"第三天若吃了平安祭的肉，這祭必不蒙悅納，人所獻的也不算為祭，反為可憎嫌的，吃這祭肉的，就必擔當他的罪孽。","notes":[]},{"n":19,"t":"「挨了污穢物的肉就不可吃，要用火焚燒。至於平安祭的肉，凡潔淨的人都要吃；","notes":[]},{"n":20,"t":"只是獻與耶和華平安祭的肉，人若不潔淨而吃了，這人必從民中剪除。","notes":[]},{"n":21,"t":"有人摸了甚麼不潔淨的物，或是人的不潔淨，或是不潔淨的牲畜，或是不潔可憎之物，吃了獻與耶和華平安祭的肉，這人必從民中剪除。」","notes":[]},{"n":22,"t":"耶和華對摩西說：","notes":[]},{"n":23,"t":"「你曉諭以色列人說：牛的脂油、綿羊的脂油、山羊的脂油，你們都不可吃。","notes":[]},{"n":24,"t":"自死的和被野獸撕裂的，那脂油可以做別的使用，只是你們萬不可吃。","notes":[]},{"n":25,"t":"無論何人吃了獻給耶和華當火祭牲畜的脂油，那人必從民中剪除。","notes":[]},{"n":26,"t":"在你們一切的住處，無論是雀鳥的血是野獸的血，你們都不可吃。","notes":[]},{"n":27,"t":"無論是誰吃血，那人必從民中剪除。」","notes":[]},{"n":28,"t":"耶和華對摩西說：","notes":[]},{"n":29,"t":"「你曉諭以色列人說：獻平安祭給耶和華的，要從平安祭中取些來奉給耶和華。","notes":[]},{"n":30,"t":"他親手獻給耶和華的火祭，就是脂油和胸，要帶來，好把胸在耶和華面前作搖祭，搖一搖。","notes":[]},{"n":31,"t":"祭司要把脂油在壇上焚燒，但胸要歸亞倫和他的子孫。","notes":[]},{"n":32,"t":"你們要從平安祭中把右腿作舉祭，奉給祭司。","notes":[]},{"n":33,"t":"亞倫子孫中，獻平安祭牲血和脂油的，要得這右腿為分；","notes":[]},{"n":34,"t":"因為我從以色列人的平安祭中，取了這搖的胸和舉的腿給祭司亞倫和他子孫，作他們從以色列人中所永得的分。」","notes":[]},{"n":35,"t":"這是從耶和華火祭中，作亞倫受膏的分和他子孫受膏的分，正在摩西叫他們前來給耶和華供祭司職分的日子，","notes":["原文是他"]},{"n":36,"t":"就是在摩西膏他們的日子，耶和華吩咐以色列人給他們的。這是他們世世代代永得的分。","notes":["原文是他"]},{"n":37,"t":"這就是燔祭、素祭、贖罪祭、贖愆祭，和平安祭的條例，並承接聖職的禮，","notes":[]},{"n":38,"t":"都是耶和華在西奈山所吩咐摩西的，就是他在西奈曠野吩咐以色列人獻供物給耶和華之日所說的。","notes":[]}]},"8":{"heading":"立亞倫和他的兒子們作祭司","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「你將亞倫和他兒子一同帶來，並將聖衣、膏油，與贖罪祭的一隻公牛、兩隻公綿羊、一筐無酵餅都帶來，","notes":[]},{"n":3,"t":"又招聚會眾到會幕門口。」","notes":[]},{"n":4,"t":"摩西就照耶和華所吩咐的行了；於是會眾聚集在會幕門口。","notes":[]},{"n":5,"t":"摩西告訴會眾說：「這就是耶和華所吩咐當行的事。」","notes":[]},{"n":6,"t":"摩西帶了亞倫和他兒子來，用水洗了他們。","notes":[]},{"n":7,"t":"給亞倫穿上內袍，束上腰帶，穿上外袍，又加上以弗得，用其上巧工織的帶子把以弗得繫在他身上，","notes":[]},{"n":8,"t":"又給他戴上胸牌，把烏陵和土明放在胸牌內，","notes":[]},{"n":9,"t":"把冠冕戴在他頭上，在冠冕的前面釘上金牌，就是聖冠，都是照耶和華所吩咐摩西的。","notes":[]},{"n":10,"t":"摩西用膏油抹帳幕和其中所有的，使它成聖；","notes":[]},{"n":11,"t":"又用膏油在壇上彈了七次，又抹了壇和壇的一切器皿，並洗濯盆和盆座，使它成聖；","notes":[]},{"n":12,"t":"又把膏油倒在亞倫的頭上膏他，使他成聖。","notes":[]},{"n":13,"t":"摩西帶了亞倫的兒子來，給他們穿上內袍，束上腰帶，包上裹頭巾，都是照耶和華所吩咐摩西的。","notes":[]},{"n":14,"t":"他牽了贖罪祭的公牛來，亞倫和他兒子按手在贖罪祭公牛的頭上，","notes":[]},{"n":15,"t":"就宰了公牛。摩西用指頭蘸血，抹在壇上四角的周圍，使壇潔淨，把血倒在壇的腳那裏，使壇成聖，壇就潔淨了；","notes":[]},{"n":16,"t":"又取臟上所有的脂油和肝上的網子，並兩個腰子與腰子上的脂油，都燒在壇上；","notes":[]},{"n":17,"t":"惟有公牛，連皮帶肉並糞，用火燒在營外，都是照耶和華所吩咐摩西的。","notes":[]},{"n":18,"t":"他奉上燔祭的公綿羊；亞倫和他兒子按手在羊的頭上，","notes":[]},{"n":19,"t":"就宰了公羊。摩西把血灑在壇的周圍，","notes":[]},{"n":20,"t":"把羊切成塊子，把頭和肉塊並脂油都燒了。","notes":[]},{"n":21,"t":"用水洗了臟腑和腿，就把全羊燒在壇上為馨香的燔祭，是獻給耶和華的火祭，都是照耶和華所吩咐摩西的。","notes":[]},{"n":22,"t":"他又奉上第二隻公綿羊，就是承接聖職之禮的羊；亞倫和他兒子按手在羊的頭上，","notes":[]},{"n":23,"t":"就宰了羊。摩西把些血抹在亞倫的右耳垂上和右手的大拇指上，並右腳的大拇指上，","notes":[]},{"n":24,"t":"又帶了亞倫的兒子來，把些血抹在他們的右耳垂上和右手的大拇指上，並右腳的大拇指上，又把血灑在壇的周圍。","notes":[]},{"n":25,"t":"取脂油和肥尾巴，並臟上一切的脂油與肝上的網子，兩個腰子和腰子上的脂油，並右腿，","notes":[]},{"n":26,"t":"再從耶和華面前、盛無酵餅的筐子裏取出一個無酵餅，一個油餅，一個薄餅，都放在脂油和右腿上，","notes":[]},{"n":27,"t":"把這一切放在亞倫的手上和他兒子的手上作搖祭，在耶和華面前搖一搖。","notes":[]},{"n":28,"t":"摩西從他們的手上拿下來，燒在壇上的燔祭上，都是為承接聖職獻給耶和華馨香的火祭。","notes":[]},{"n":29,"t":"摩西拿羊的胸作為搖祭，在耶和華面前搖一搖，是承接聖職之禮，歸摩西的分，都是照耶和華所吩咐摩西的。","notes":[]},{"n":30,"t":"摩西取點膏油和壇上的血，彈在亞倫和他的衣服上，並他兒子和他兒子的衣服上，使他和他們的衣服一同成聖。","notes":[]},{"n":31,"t":"摩西對亞倫和他兒子說：「把肉煮在會幕門口，在那裏吃，又吃承接聖職筐子裏的餅，按我所吩咐的說 ：『這是亞倫和他兒子要吃的。』","notes":["或譯：按所吩咐我的說"]},{"n":32,"t":"剩下的肉和餅，你們要用火焚燒。","notes":[]},{"n":33,"t":"你們七天不可出會幕的門，等到你們承接聖職的日子滿了，因為主叫你們七天承接聖職。","notes":[]},{"n":34,"t":"像今天所行的都是耶和華吩咐行的，為你們贖罪。","notes":[]},{"n":35,"t":"七天你們要晝夜住在會幕門口，遵守耶和華的吩咐，免得你們死亡，因為所吩咐我的就是這樣。」","notes":[]},{"n":36,"t":"於是亞倫和他兒子行了耶和華藉著摩西所吩咐的一切事。","notes":[]}]},"9":{"heading":"亞倫獻祭","verses":[{"n":1,"t":"到了第八天，摩西召了亞倫和他兒子，並以色列的眾長老來，","notes":[]},{"n":2,"t":"對亞倫說：「你當取牛群中的一隻公牛犢作贖罪祭，一隻公綿羊作燔祭，都要沒有殘疾的，獻在耶和華面前。","notes":[]},{"n":3,"t":"你也要對以色列人說：『你們當取一隻公山羊作贖罪祭，又取一隻牛犢和一隻綿羊羔，都要一歲、沒有殘疾的，作燔祭，","notes":[]},{"n":4,"t":"又取一隻公牛，一隻公綿羊作平安祭，獻在耶和華面前，並取調油的素祭，因為今天耶和華要向你們顯現。』」","notes":[]},{"n":5,"t":"於是他們把摩西所吩咐的，帶到會幕前；全會眾都近前來，站在耶和華面前。","notes":[]},{"n":6,"t":"摩西說：「這是耶和華吩咐你們所當行的；耶和華的榮光就要向你們顯現。」","notes":[]},{"n":7,"t":"摩西對亞倫說：「你就近壇前，獻你的贖罪祭和燔祭，為自己與百姓贖罪，又獻上百姓的供物，為他們贖罪，都照耶和華所吩咐的。」","notes":[]},{"n":8,"t":"於是，亞倫就近壇前，宰了為自己作贖罪祭的牛犢。","notes":[]},{"n":9,"t":"亞倫的兒子把血奉給他，他就把指頭蘸在血中，抹在壇的四角上，又把血倒在壇腳那裏。","notes":[]},{"n":10,"t":"惟有贖罪祭的脂油和腰子，並肝上取的網子，都燒在壇上，是照耶和華所吩咐摩西的；","notes":[]},{"n":11,"t":"又用火將肉和皮燒在營外。","notes":[]},{"n":12,"t":"亞倫宰了燔祭牲，他兒子把血遞給他，他就灑在壇的周圍，","notes":[]},{"n":13,"t":"又把燔祭一塊一塊地、連頭遞給他，他都燒在壇上；","notes":[]},{"n":14,"t":"又洗了臟腑和腿，燒在壇上的燔祭上。","notes":[]},{"n":15,"t":"他奉上百姓的供物，把那給百姓作贖罪祭的公山羊宰了，為罪獻上，和先獻的一樣；","notes":[]},{"n":16,"t":"也奉上燔祭，照例而獻。","notes":[]},{"n":17,"t":"他又奉上素祭，從其中取一滿把，燒在壇上；這是在早晨的燔祭以外。","notes":[]},{"n":18,"t":"亞倫宰了那給百姓作平安祭的公牛和公綿羊。他兒子把血遞給他，他就灑在壇的周圍；","notes":[]},{"n":19,"t":"又把公牛和公綿羊的脂油、肥尾巴，並蓋臟的脂油與腰子，和肝上的網子，都遞給他；","notes":[]},{"n":20,"t":"把脂油放在胸上，他就把脂油燒在壇上。","notes":[]},{"n":21,"t":"胸和右腿，亞倫當作搖祭，在耶和華面前搖一搖，都是照摩西所吩咐的。","notes":[]},{"n":22,"t":"亞倫向百姓舉手，為他們祝福。他獻了贖罪祭、燔祭、平安祭就下來了。","notes":[]},{"n":23,"t":"摩西、亞倫進入會幕，又出來為百姓祝福，耶和華的榮光就向眾民顯現。","notes":[]},{"n":24,"t":"有火從耶和華面前出來，在壇上燒盡燔祭和脂油；眾民一見，就都歡呼，俯伏在地。","notes":[]}]},"10":{"heading":"拿答和亞比戶犯罪","verses":[{"n":1,"t":"亞倫的兒子拿答、亞比戶各拿自己的香爐，盛上火，加上香，在耶和華面前獻上凡火，是耶和華沒有吩咐他們的，","notes":[]},{"n":2,"t":"就有火從耶和華面前出來，把他們燒滅，他們就死在耶和華面前。","notes":[]},{"n":3,"t":"於是摩西對亞倫說：「這就是耶和華所說：『我在親近我的人中要顯為聖；在眾民面前，我要得榮耀。』」亞倫就默默不言。","notes":[]},{"n":4,"t":"摩西召了亞倫叔父烏薛的兒子米沙利、以利撒反來，對他們說：「上前來，把你們的親屬從聖所前抬到營外。」","notes":[]},{"n":5,"t":"於是二人上前來，把他們穿著袍子抬到營外，是照摩西所吩咐的。","notes":[]},{"n":6,"t":"摩西對亞倫和他兒子以利亞撒、以他瑪說：「不可蓬頭散髮，也不可撕裂衣裳，免得你們死亡，又免得耶和華向會眾發怒；只要你們的弟兄以色列全家為耶和華所發的火哀哭。","notes":[]},{"n":7,"t":"你們也不可出會幕的門，恐怕你們死亡，因為耶和華的膏油在你們的身上。」他們就照摩西的話行了。","notes":[]},{"n":8,"t":"耶和華曉諭亞倫說：","notes":[],"heads":["有關祭司的條例"]},{"n":9,"t":"「你和你兒子進會幕的時候，清酒、濃酒都不可喝，免得你們死亡；這要作你們世世代代永遠的定例。","notes":[]},{"n":10,"t":"使你們可以將聖的、俗的，潔淨的、不潔淨的，分別出來；","notes":[]},{"n":11,"t":"又使你們可以將耶和華藉摩西曉諭以色列人的一切律例教訓他們。」","notes":[]},{"n":12,"t":"摩西對亞倫和他剩下的兒子以利亞撒、以他瑪說：「你們獻給耶和華火祭中所剩的素祭，要在壇旁不帶酵而吃，因為是至聖的。","notes":[]},{"n":13,"t":"你們要在聖處吃；因為在獻給耶和華的火祭中，這是你的分和你兒子的分；所吩咐我的本是這樣。","notes":[]},{"n":14,"t":"所搖的胸，所舉的腿，你們要在潔淨地方吃。你和你的兒女都要同吃；因為這些是從以色列人平安祭中給你，當你的分和你兒子的分。","notes":[]},{"n":15,"t":"所舉的腿，所搖的胸，他們要與火祭的脂油一同帶來當搖祭，在耶和華面前搖一搖；這要歸你和你兒子，當作永得的分，都是照耶和華所吩咐的。」","notes":[]},{"n":16,"t":"當下摩西急切地尋找作贖罪祭的公山羊，誰知已經焚燒了，便向亞倫剩下的兒子以利亞撒、以他瑪發怒，說：","notes":[]},{"n":17,"t":"「這贖罪祭既是至聖的，主又給了你們，為要你們擔當會眾的罪孽，在耶和華面前為他們贖罪，你們為何沒有在聖所吃呢？","notes":[]},{"n":18,"t":"看哪，這祭牲的血並沒有拿到聖所裏去，你們本當照我所吩咐的，在聖所裏吃這祭肉。」","notes":[]},{"n":19,"t":"亞倫對摩西說：「今天他們在耶和華面前獻上贖罪祭和燔祭，我又遇見這樣的災，若今天吃了贖罪祭，耶和華豈能看為美呢？」","notes":[]},{"n":20,"t":"摩西聽見這話，便以為美。","notes":[]}]},"11":{"heading":"有關食物的條例","verses":[{"n":1,"t":"耶和華對摩西、亞倫說：","notes":[]},{"n":2,"t":"「你們曉諭以色列人說，在地上一切走獸中可吃的乃是這些：","notes":[]},{"n":3,"t":"凡蹄分兩瓣、倒嚼的走獸，你們都可以吃。","notes":[]},{"n":4,"t":"但那倒嚼或分蹄之中不可吃的乃是：駱駝－因為倒嚼不分蹄，就與你們不潔淨；","notes":[]},{"n":5,"t":"沙番－因為倒嚼不分蹄，就與你們不潔淨；","notes":[]},{"n":6,"t":"兔子－因為倒嚼不分蹄，就與你們不潔淨；","notes":[]},{"n":7,"t":"豬－因為蹄分兩瓣，卻不倒嚼，就與你們不潔淨。","notes":[]},{"n":8,"t":"這些獸的肉，你們不可吃；死的，你們不可摸，都與你們不潔淨。","notes":[]},{"n":9,"t":"「水中可吃的乃是這些：凡在水裏、海裏、河裏、有翅有鱗的，都可以吃。","notes":[]},{"n":10,"t":"凡在海裏、河裏，並一切水裏游動的活物，無翅無鱗的，你們都當以為可憎。","notes":[]},{"n":11,"t":"這些無翅無鱗、以為可憎的，你們不可吃牠的肉；死的也當以為可憎。","notes":[]},{"n":12,"t":"凡水裏無翅無鱗的，你們都當以為可憎。","notes":[]},{"n":13,"t":"「雀鳥中你們當以為可憎、不可吃的乃是：鵰、狗頭鵰、紅頭鵰、","notes":[]},{"n":14,"t":"鷂鷹、小鷹與其類；","notes":[]},{"n":15,"t":"烏鴉與其類；","notes":[]},{"n":16,"t":"鴕鳥、夜鷹、魚鷹、鷹與其類；","notes":[]},{"n":17,"t":"鴞鳥、鸕鶿、貓頭鷹、","notes":[]},{"n":18,"t":"角鴟、鵜鶘、禿鵰、","notes":[]},{"n":19,"t":"鸛、鷺鷥與其類；戴鵀與蝙蝠。","notes":[]},{"n":20,"t":"「凡有翅膀用四足爬行的物，你們都當以為可憎。","notes":[]},{"n":21,"t":"只是有翅膀用四足爬行的物中，有足有腿，在地上蹦跳的，你們還可以吃。","notes":[]},{"n":22,"t":"其中有蝗蟲、螞蚱、蟋蟀與其類；蚱蜢與其類；這些你們都可以吃。","notes":[]},{"n":23,"t":"但是有翅膀有四足的爬物，你們都當以為可憎。","notes":[]},{"n":24,"t":"「這些都能使你們不潔淨。凡摸了死的，必不潔淨到晚上。","notes":[]},{"n":25,"t":"凡拿了死的，必不潔淨到晚上，並要洗衣服。","notes":[]},{"n":26,"t":"凡走獸分蹄不成兩瓣、也不倒嚼的，是與你們不潔淨；凡摸了的就不潔淨。","notes":[]},{"n":27,"t":"凡四足的走獸，用掌行走的，是與你們不潔淨；摸其屍的，必不潔淨到晚上。","notes":[]},{"n":28,"t":"拿其屍的，必不潔淨到晚上，並要洗衣服。這些是與你們不潔淨的。","notes":[]},{"n":29,"t":"「地上爬物與你們不潔淨的乃是這些：鼬鼠、鼫鼠、蜥蜴與其類；","notes":[]},{"n":30,"t":"壁虎、龍子、守宮、蛇醫、蝘蜓。","notes":[]},{"n":31,"t":"這些爬物都是與你們不潔淨的。在牠死了以後，凡摸了的，必不潔淨到晚上。","notes":[]},{"n":32,"t":"其中死了的，掉在甚麼東西上，這東西就不潔淨，無論是木器、衣服、皮子、口袋，不拘是做甚麼工用的器皿，須要放在水中，必不潔淨到晚上，到晚上才潔淨了。","notes":[]},{"n":33,"t":"若有死了掉在瓦器裏的，其中不拘有甚麼，就不潔淨，你們要把這瓦器打破了。","notes":[]},{"n":34,"t":"其中一切可吃的食物，沾水的就不潔淨，並且那樣器皿中一切可喝的，也必不潔淨。","notes":[]},{"n":35,"t":"其中已死的，若有一點掉在甚麼物件上，那物件就不潔淨，不拘是爐子，是鍋臺，就要打碎，都不潔淨，也必與你們不潔淨。","notes":[]},{"n":36,"t":"但是泉源或是聚水的池子仍是潔淨；惟挨了那死的，就不潔淨。","notes":[]},{"n":37,"t":"若是死的，有一點掉在要種的子粒上，子粒仍是潔淨；","notes":[]},{"n":38,"t":"若水已經澆在子粒上，那死的有一點掉在上頭，這子粒就與你們不潔淨。","notes":[]},{"n":39,"t":"「你們可吃的走獸若是死了，有人摸牠，必不潔淨到晚上；","notes":[]},{"n":40,"t":"有人吃那死了的走獸，必不潔淨到晚上，並要洗衣服；拿了死走獸的，必不潔淨到晚上，並要洗衣服。","notes":[]},{"n":41,"t":"「凡地上的爬物是可憎的，都不可吃。","notes":[]},{"n":42,"t":"凡用肚子行走的和用四足行走的，或是有許多足的，就是一切爬在地上的，你們都不可吃，因為是可憎的。","notes":[]},{"n":43,"t":"你們不可因甚麼爬物使自己成為可憎的，也不可因這些使自己不潔淨，以致染了污穢。","notes":[]},{"n":44,"t":"我是耶和華－你們的神；所以你們要成為聖潔，因為我是聖潔的。你們也不可在地上的爬物污穢自己。","notes":[]},{"n":45,"t":"我是把你們從埃及地領出來的耶和華，要作你們的神；所以你們要聖潔，因為我是聖潔的。」","notes":[]},{"n":46,"t":"這是走獸、飛鳥，和水中游動的活物，並地上爬物的條例。","notes":[]},{"n":47,"t":"要把潔淨的和不潔淨的，可吃的與不可吃的活物，都分別出來。","notes":[]}]},"12":{"heading":"產婦潔淨禮的條例","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你曉諭以色列人說：若有婦人懷孕生男孩，她就不潔淨七天，像在月經污穢的日子不潔淨一樣。","notes":[]},{"n":3,"t":"第八天，要給嬰孩行割禮。","notes":[]},{"n":4,"t":"婦人在產血不潔之中，要家居三十三天。她潔淨的日子未滿，不可摸聖物，也不可進入聖所。","notes":[]},{"n":5,"t":"她若生女孩，就不潔淨兩個七天，像污穢的時候一樣，要在產血不潔之中，家居六十六天。","notes":[]},{"n":6,"t":"「滿了潔淨的日子，無論是為男孩是為女孩，她要把一歲的羊羔為燔祭，一隻雛鴿或是一隻斑鳩為贖罪祭，帶到會幕門口交給祭司。","notes":[]},{"n":7,"t":"祭司要獻在耶和華面前，為她贖罪，她的血源就潔淨了。這條例是為生育的婦人，無論是生男生女。","notes":[]},{"n":8,"t":"她的力量若不夠獻一隻羊羔，她就要取兩隻斑鳩或是兩隻雛鴿，一隻為燔祭，一隻為贖罪祭。祭司要為她贖罪，她就潔淨了。」","notes":[]}]},"13":{"heading":"有關皮膚病的條例","verses":[{"n":1,"t":"耶和華曉諭摩西、亞倫說：","notes":[]},{"n":2,"t":"「人的肉皮上若長了癤子，或長了癬，或長了火斑，在他肉皮上成了大痲瘋的災病，就要將他帶到祭司亞倫或亞倫作祭司的一個子孫面前。","notes":[]},{"n":3,"t":"祭司要察看肉皮上的災病，若災病處的毛已經變白，災病的現象深於肉上的皮，這便是大痲瘋的災病。祭司要察看他，定他為不潔淨。","notes":[]},{"n":4,"t":"若火斑在他肉皮上是白的，現象不深於皮，其上的毛也沒有變白，祭司就要將有災病的人關鎖七天。","notes":[]},{"n":5,"t":"第七天，祭司要察看他，若看災病止住了，沒有在皮上發散，祭司還要將他關鎖七天。","notes":[]},{"n":6,"t":"第七天，祭司要再察看他，若災病發暗，而且沒有在皮上發散，祭司要定他為潔淨，原來是癬；那人就要洗衣服，得為潔淨。","notes":[]},{"n":7,"t":"但他為得潔淨，將身體給祭司察看以後，癬若在皮上發散開了，他要再將身體給祭司察看。","notes":[]},{"n":8,"t":"祭司要察看，癬若在皮上發散，就要定他為不潔淨，是大痲瘋。","notes":[]},{"n":9,"t":"「人有了大痲瘋的災病，就要將他帶到祭司面前。","notes":[]},{"n":10,"t":"祭司要察看，皮上若長了白癤，使毛變白，在長白癤之處有了紅瘀肉，","notes":[]},{"n":11,"t":"這是肉皮上的舊大痲瘋，祭司要定他為不潔淨，不用將他關鎖，因為他是不潔淨了。","notes":[]},{"n":12,"t":"大痲瘋若在皮上四外發散，長滿了患災病人的皮，據祭司察看，從頭到腳無處不有，","notes":[]},{"n":13,"t":"祭司就要察看，全身的肉若長滿了大痲瘋，就要定那患災病的為潔淨；全身都變為白，他乃潔淨了。","notes":[]},{"n":14,"t":"但紅肉幾時顯在他的身上就幾時不潔淨。","notes":[]},{"n":15,"t":"祭司一看那紅肉就定他為不潔淨。紅肉本是不潔淨，是大痲瘋。","notes":[]},{"n":16,"t":"紅肉若復原，又變白了，他就要來見祭司。","notes":[]},{"n":17,"t":"祭司要察看，災病處若變白了，祭司就要定那患災病的為潔淨，他乃潔淨了。","notes":[]},{"n":18,"t":"「人若在皮肉上長瘡，卻治好了，","notes":[]},{"n":19,"t":"在長瘡之處又起了白癤，或是白中帶紅的火斑，就要給祭司察看。","notes":[]},{"n":20,"t":"祭司要察看，若現象窪於皮，其上的毛也變白了，就要定他為不潔淨，是大痲瘋的災病發在瘡中。","notes":[]},{"n":21,"t":"祭司若察看，其上沒有白毛，也沒有窪於皮，乃是發暗，就要將他關鎖七天。","notes":[]},{"n":22,"t":"若在皮上發散開了，祭司就要定他為不潔淨，是災病。","notes":[]},{"n":23,"t":"火斑若在原處止住，沒有發散，便是瘡的痕跡，祭司就要定他為潔淨。","notes":[]},{"n":24,"t":"「人的皮肉上若起了火毒，火毒的瘀肉成了火斑，或是白中帶紅的，或是全白的，","notes":[]},{"n":25,"t":"祭司就要察看，火斑中的毛若變白了，現象又深於皮，是大痲瘋在火毒中發出，就要定他為不潔淨，是大痲瘋的災病。","notes":[]},{"n":26,"t":"但是祭司察看，在火斑中若沒有白毛，也沒有窪於皮，乃是發暗，就要將他關鎖七天。","notes":[]},{"n":27,"t":"到第七天，祭司要察看他，火斑若在皮上發散開了，就要定他為不潔淨，是大痲瘋的災病。","notes":[]},{"n":28,"t":"火斑若在原處止住，沒有在皮上發散，乃是發暗，是起的火毒，祭司要定他為潔淨，不過是火毒的痕跡。","notes":[]},{"n":29,"t":"「無論男女，若在頭上有災病，或是男人鬍鬚上有災病，","notes":[]},{"n":30,"t":"祭司就要察看；這災病現象若深於皮，其間有細黃毛，就要定他為不潔淨，這是頭疥，是頭上或是鬍鬚上的大痲瘋。","notes":[]},{"n":31,"t":"祭司若察看頭疥的災病，現象不深於皮，其間也沒有黑毛，就要將長頭疥災病的關鎖七天。","notes":[]},{"n":32,"t":"第七天，祭司要察看災病，若頭疥沒有發散，其間也沒有黃毛，頭疥的現象不深於皮，","notes":[]},{"n":33,"t":"那人就要剃去鬚髮，但他不可剃頭疥之處。祭司要將那長頭疥的，再關鎖七天。","notes":[]},{"n":34,"t":"第七天，祭司要察看頭疥，頭疥若沒有在皮上發散，現象也不深於皮，就要定他為潔淨，他要洗衣服，便成為潔淨。","notes":[]},{"n":35,"t":"但他得潔淨以後，頭疥若在皮上發散開了，","notes":[]},{"n":36,"t":"祭司就要察看他。頭疥若在皮上發散，就不必找那黃毛，他是不潔淨了。","notes":[]},{"n":37,"t":"祭司若看頭疥已經止住，其間也長了黑毛，頭疥已然痊癒，那人是潔淨了，就要定他為潔淨。","notes":[]},{"n":38,"t":"「無論男女，皮肉上若起了火斑，就是白火斑，","notes":[]},{"n":39,"t":"祭司就要察看，他們肉皮上的火斑若白中帶黑，這是皮上發出的白癬，那人是潔淨了。","notes":[]},{"n":40,"t":"「人頭上的髮若掉了，他不過是頭禿，還是潔淨。","notes":[]},{"n":41,"t":"他頂前若掉了頭髮，他不過是頂門禿，還是潔淨。","notes":[]},{"n":42,"t":"頭禿處或是頂門禿處若有白中帶紅的災病，這就是大痲瘋發在他頭禿處或是頂門禿處，","notes":[]},{"n":43,"t":"祭司就要察看，他起的那災病若在頭禿處或是頂門禿處有白中帶紅的，像肉皮上大痲瘋的現象，","notes":[]},{"n":44,"t":"那人就是長大痲瘋，不潔淨的，祭司總要定他為不潔淨，他的災病是在頭上。","notes":[]},{"n":45,"t":"「身上有長大痲瘋災病的，他的衣服要撕裂，也要蓬頭散髮，蒙著上唇，喊叫說：『不潔淨了！不潔淨了！』","notes":[]},{"n":46,"t":"災病在他身上的日子，他便是不潔淨；他既是不潔淨，就要獨居營外。」","notes":[]},{"n":47,"t":"「染了大痲瘋災病的衣服，無論是羊毛衣服、是麻布衣服，","notes":[],"heads":["衣物發霉的條例"]},{"n":48,"t":"無論是在經上、在緯上，是麻布的、是羊毛的，是在皮子上，或在皮子做的甚麼物件上，","notes":[]},{"n":49,"t":"或在衣服上、皮子上，經上、緯上，或在皮子做的甚麼物件上，這災病若是發綠，或是發紅，是大痲瘋的災病，要給祭司察看。","notes":[]},{"n":50,"t":"祭司就要察看那災病，把染了災病的物件關鎖七天。","notes":[]},{"n":51,"t":"第七天，他要察看那災病，災病或在衣服上，經上、緯上，皮子上，若發散，這皮子無論當作何用，這災病是蠶食的大痲瘋，都是不潔淨了。","notes":[]},{"n":52,"t":"那染了災病的衣服，或是經上、緯上，羊毛上，麻衣上，或是皮子做的甚麼物件上，他都要焚燒；因為這是蠶食的大痲瘋，必在火中焚燒。","notes":[]},{"n":53,"t":"「祭司要察看，若災病在衣服上，經上、緯上，或是皮子做的甚麼物件上，沒有發散，","notes":[]},{"n":54,"t":"祭司就要吩咐他們，把染了災病的物件洗了，再關鎖七天。","notes":[]},{"n":55,"t":"洗過以後，祭司要察看，那物件若沒有變色，災病也沒有消散，那物件就不潔淨，是透重的災病，無論正面反面，都要在火中焚燒。","notes":[]},{"n":56,"t":"洗過以後，祭司要察看，若見那災病發暗，他就要把那災病從衣服上，皮子上，經上、緯上，都撕去。","notes":[]},{"n":57,"t":"若仍現在衣服上，或是經上、緯上、皮子做的甚麼物件上，這就是災病又發了，必用火焚燒那染災病的物件。","notes":[]},{"n":58,"t":"所洗的衣服，或是經，或是緯，或是皮子做的甚麼物件，若災病離開了，要再洗，就潔淨了。」","notes":[]},{"n":59,"t":"這就是大痲瘋災病的條例，無論是在羊毛衣服上，麻布衣服上，經上、緯上，和皮子做的甚麼物件上，可以定為潔淨或是不潔淨。","notes":[]}]},"14":{"heading":"皮膚病後潔淨的條例","verses":[{"n":1,"t":"耶和華曉諭摩西說：「","notes":[]},{"n":2,"t":"長大痲瘋得潔淨的日子，其例乃是這樣：要帶他去見祭司；","notes":[]},{"n":3,"t":"祭司要出到營外察看，若見他的大痲瘋痊癒了，","notes":[]},{"n":4,"t":"就要吩咐人為那求潔淨的拿兩隻潔淨的活鳥和香柏木、朱紅色線，並牛膝草來。","notes":[]},{"n":5,"t":"祭司要吩咐用瓦器盛活水，把一隻鳥宰在上面。","notes":[]},{"n":6,"t":"至於那隻活鳥，祭司要把牠和香柏木、朱紅色線並牛膝草一同蘸於宰在活水上的鳥血中，","notes":[]},{"n":7,"t":"用以在那長大痲瘋求潔淨的人身上灑七次，就定他為潔淨，又把活鳥放在田野裏。","notes":[]},{"n":8,"t":"求潔淨的人當洗衣服，剃去毛髮，用水洗澡，就潔淨了；然後可以進營，只是要在自己的帳棚外居住七天。","notes":[]},{"n":9,"t":"第七天，再把頭上所有的頭髮與鬍鬚、眉毛，並全身的毛，都剃了；又要洗衣服，用水洗身，就潔淨了。","notes":[]},{"n":10,"t":"「第八天，他要取兩隻沒有殘疾的公羊羔和一隻沒有殘疾、一歲的母羊羔，又要把調油的細麵伊法十分之三為素祭，並油一羅革，一同取來。","notes":[]},{"n":11,"t":"行潔淨之禮的祭司要將那求潔淨的人和這些東西安置在會幕門口、耶和華面前。","notes":[]},{"n":12,"t":"祭司要取一隻公羊羔獻為贖愆祭，和那一羅革油一同作搖祭，在耶和華面前搖一搖；","notes":[]},{"n":13,"t":"把公羊羔宰於聖地，就是宰贖罪祭牲和燔祭牲之地。贖愆祭要歸祭司，與贖罪祭一樣，是至聖的。","notes":[]},{"n":14,"t":"祭司要取些贖愆祭牲的血，抹在求潔淨人的右耳垂上和右手的大拇指上，並右腳的大拇指上。","notes":[]},{"n":15,"t":"祭司要從那一羅革油中取些倒在自己的左手掌裏，","notes":[]},{"n":16,"t":"把右手的一個指頭蘸在左手的油裏，在耶和華面前用指頭彈七次。","notes":[]},{"n":17,"t":"將手裏所剩的油抹在那求潔淨人的右耳垂上和右手的大拇指上，並右腳的大拇指上，就是抹在贖愆祭牲的血上。","notes":[]},{"n":18,"t":"祭司手裏所剩的油要抹在那求潔淨人的頭上，在耶和華面前為他贖罪。","notes":[]},{"n":19,"t":"祭司要獻贖罪祭，為那本不潔淨、求潔淨的人贖罪；然後要宰燔祭牲，","notes":[]},{"n":20,"t":"把燔祭和素祭獻在壇上，為他贖罪，他就潔淨了。","notes":[]},{"n":21,"t":"「他若貧窮不能預備夠數，就要取一隻公羊羔作贖愆祭，可以搖一搖，為他贖罪；也要把調油的細麵伊法十分之一為素祭，和油一羅革一同取來；","notes":[]},{"n":22,"t":"又照他的力量取兩隻斑鳩或是兩隻雛鴿，一隻作贖罪祭，一隻作燔祭。","notes":[]},{"n":23,"t":"第八天，要為潔淨，把這些帶到會幕門口、耶和華面前，交給祭司。","notes":[]},{"n":24,"t":"祭司要把贖愆祭的羊羔和那一羅革油一同作搖祭，在耶和華面前搖一搖。","notes":[]},{"n":25,"t":"要宰了贖愆祭的羊羔，取些贖愆祭牲的血，抹在那求潔淨人的右耳垂上和右手的大拇指上，並右腳的大拇指上。","notes":[]},{"n":26,"t":"祭司要把些油倒在自己的左手掌裏，","notes":[]},{"n":27,"t":"把左手裏的油，在耶和華面前，用右手的一個指頭彈七次，","notes":[]},{"n":28,"t":"又把手裏的油抹些在那求潔淨人的右耳垂上和右手的大拇指上，並右腳的大拇指上，就是抹贖愆祭之血的原處。","notes":[]},{"n":29,"t":"祭司手裏所剩的油要抹在那求潔淨人的頭上，在耶和華面前為他贖罪。","notes":[]},{"n":30,"t":"那人又要照他的力量獻上一隻斑鳩或是一隻雛鴿，","notes":[]},{"n":31,"t":"就是他所能辦的，一隻為贖罪祭，一隻為燔祭，與素祭一同獻上；祭司要在耶和華面前為他贖罪。","notes":[]},{"n":32,"t":"這是那有大痲瘋災病的人、不能將關乎得潔淨之物預備夠數的條例。」","notes":[]},{"n":33,"t":"耶和華曉諭摩西、亞倫說：","notes":[],"heads":["處理房屋發霉的條例"]},{"n":34,"t":"「你們到了我賜給你們為業的迦南地，我若使你們所得為業之地的房屋中有大痲瘋的災病，","notes":[]},{"n":35,"t":"房主就要去告訴祭司說：『據我看，房屋中似乎有災病。』","notes":[]},{"n":36,"t":"祭司還沒有進去察看災病以前，就要吩咐人把房子騰空，免得房子裏所有的都成了不潔淨；然後祭司要進去察看房子。","notes":[]},{"n":37,"t":"他要察看那災病，災病若在房子的牆上有發綠或發紅的凹斑紋，現象窪於牆，","notes":[]},{"n":38,"t":"祭司就要出到房門外，把房子封鎖七天。","notes":[]},{"n":39,"t":"第七天，祭司要再去察看，災病若在房子的牆上發散，","notes":[]},{"n":40,"t":"就要吩咐人把那有災病的石頭挖出來，扔在城外不潔淨之處；","notes":[]},{"n":41,"t":"也要叫人刮房內的四圍，所刮掉的灰泥要倒在城外不潔淨之處；","notes":[]},{"n":42,"t":"又要用別的石頭代替那挖出來的石頭，要另用灰泥墁房子。","notes":[]},{"n":43,"t":"「他挖出石頭，刮了房子，墁了以後，災病若在房子裏又發現，","notes":[]},{"n":44,"t":"祭司就要進去察看，災病若在房子裏發散，這就是房內蠶食的大痲瘋，是不潔淨。","notes":[]},{"n":45,"t":"他就要拆毀房子，把石頭、木頭、灰泥都搬到城外不潔淨之處。","notes":[]},{"n":46,"t":"在房子封鎖的時候，進去的人必不潔淨到晚上；","notes":[]},{"n":47,"t":"在房子裏躺著的必洗衣服；在房子裏吃飯的也必洗衣服。","notes":[]},{"n":48,"t":"「房子墁了以後，祭司若進去察看，見災病在房內沒有發散，就要定房子為潔淨，因為災病已經消除。","notes":[]},{"n":49,"t":"要為潔淨房子取兩隻鳥和香柏木、朱紅色線並牛膝草，","notes":[]},{"n":50,"t":"用瓦器盛活水，把一隻鳥宰在上面，","notes":[]},{"n":51,"t":"把香柏木、牛膝草、朱紅色線，並那活鳥，都蘸在被宰的鳥血中與活水中，用以灑房子七次。","notes":[]},{"n":52,"t":"要用鳥血、活水、活鳥、香柏木、牛膝草，並朱紅色線，潔淨那房子。","notes":[]},{"n":53,"t":"但要把活鳥放在城外田野裏。這樣潔淨房子，房子就潔淨了。」","notes":["原文是為房子贖罪"]},{"n":54,"t":"這是為各類大痲瘋的災病和頭疥，","notes":[]},{"n":55,"t":"並衣服與房子的大痲瘋，","notes":[]},{"n":56,"t":"以及癤子、癬、火斑所立的條例，","notes":[]},{"n":57,"t":"指明何時為潔淨，何時為不潔淨。這是大痲瘋的條例。","notes":[]}]},"15":{"heading":"漏症患者潔淨的條例","verses":[{"n":1,"t":"耶和華對摩西、亞倫說：","notes":[]},{"n":2,"t":"「你們曉諭以色列人說：人若身患漏症，他因這漏症就不潔淨了。","notes":[]},{"n":3,"t":"他患漏症，無論是下流的，是止住的，都是不潔淨。","notes":[]},{"n":4,"t":"他所躺的床都為不潔淨，所坐的物也為不潔淨。","notes":[]},{"n":5,"t":"凡摸那床的，必不潔淨到晚上，並要洗衣服，用水洗澡。","notes":[]},{"n":6,"t":"那坐患漏症人所坐之物的，必不潔淨到晚上，並要洗衣服，用水洗澡。","notes":[]},{"n":7,"t":"那摸患漏症人身體的，必不潔淨到晚上，並要洗衣服，用水洗澡。","notes":[]},{"n":8,"t":"若患漏症人吐在潔淨的人身上，那人必不潔淨到晚上，並要洗衣服，用水洗澡。","notes":[]},{"n":9,"t":"患漏症人所騎的鞍子也為不潔淨。","notes":[]},{"n":10,"t":"凡摸了他身下之物的，必不潔淨到晚上；拿了那物的，必不潔淨到晚上，並要洗衣服，用水洗澡。","notes":[]},{"n":11,"t":"患漏症的人沒有用水涮手，無論摸了誰，誰必不潔淨到晚上，並要洗衣服，用水洗澡。","notes":[]},{"n":12,"t":"患漏症人所摸的瓦器就必打破；所摸的一切木器也必用水涮洗。","notes":[]},{"n":13,"t":"「患漏症的人痊癒了，就要為潔淨自己計算七天，也必洗衣服，用活水洗身，就潔淨了。","notes":[]},{"n":14,"t":"第八天，要取兩隻斑鳩或是兩隻雛鴿，來到會幕門口、耶和華面前，把鳥交給祭司。","notes":[]},{"n":15,"t":"祭司要獻上一隻為贖罪祭，一隻為燔祭；因那人患的漏症，祭司要在耶和華面前為他贖罪。","notes":[]},{"n":16,"t":"「人若夢遺，他必不潔淨到晚上，並要用水洗全身。","notes":[]},{"n":17,"t":"無論是衣服是皮子，被精所染，必不潔淨到晚上，並要用水洗。","notes":[]},{"n":18,"t":"若男女交合，兩個人必不潔淨到晚上，並要用水洗澡。","notes":[]},{"n":19,"t":"「女人行經，必污穢七天；凡摸她的，必不潔淨到晚上。","notes":[]},{"n":20,"t":"女人在污穢之中，凡她所躺的物件都為不潔淨，所坐的物件也都不潔淨。","notes":[]},{"n":21,"t":"凡摸她床的，必不潔淨到晚上，並要洗衣服，用水洗澡。","notes":[]},{"n":22,"t":"凡摸她所坐甚麼物件的，必不潔淨到晚上，並要洗衣服，用水洗澡。","notes":[]},{"n":23,"t":"在女人的床上，或在她坐的物上，若有別的物件，人一摸了，必不潔淨到晚上。","notes":[]},{"n":24,"t":"男人若與那女人同房，染了她的污穢，就要七天不潔淨；所躺的床也為不潔淨。","notes":[]},{"n":25,"t":"「女人若在經期以外患多日的血漏，或是經期過長，有了漏症，她就因這漏症不潔淨，與她在經期不潔淨一樣。","notes":[]},{"n":26,"t":"她在患漏症的日子所躺的床、所坐的物都要看為不潔淨，與她月經的時候一樣。","notes":[]},{"n":27,"t":"凡摸這些物件的，就為不潔淨，必不潔淨到晚上，並要洗衣服，用水洗澡。","notes":[]},{"n":28,"t":"女人的漏症若好了，就要計算七天，然後才為潔淨。","notes":[]},{"n":29,"t":"第八天，要取兩隻斑鳩或是兩隻雛鴿，帶到會幕門口給祭司。","notes":[]},{"n":30,"t":"祭司要獻一隻為贖罪祭，一隻為燔祭；因那人血漏不潔，祭司要在耶和華面前為她贖罪。","notes":[]},{"n":31,"t":"「你們要這樣使以色列人與他們的污穢隔絕，免得他們玷污我的帳幕，就因自己的污穢死亡。」","notes":[]},{"n":32,"t":"這是患漏症和夢遺而不潔淨的，","notes":[]},{"n":33,"t":"並有月經病的和患漏症的，無論男女，並人與不潔淨女人同房的條例。","notes":[]}]},"16":{"heading":"贖罪日","verses":[{"n":1,"t":"亞倫的兩個兒子近到耶和華面前死了。死了之後，耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「要告訴你哥哥亞倫，不可隨時進聖所的幔子內、到櫃上的施恩座前，免得他死亡，因為我要從雲中顯現在施恩座上。","notes":[]},{"n":3,"t":"亞倫進聖所，要帶一隻公牛犢為贖罪祭，一隻公綿羊為燔祭。","notes":[]},{"n":4,"t":"要穿上細麻布聖內袍，把細麻布褲子穿在身上，腰束細麻布帶子，頭戴細麻布冠冕；這都是聖服。他要用水洗身，然後穿戴。","notes":[]},{"n":5,"t":"要從以色列會眾取兩隻公山羊為贖罪祭，一隻公綿羊為燔祭。","notes":[]},{"n":6,"t":"「亞倫要把贖罪祭的公牛奉上，為自己和本家贖罪；","notes":[]},{"n":7,"t":"也要把兩隻公山羊安置在會幕門口、耶和華面前，","notes":[]},{"n":8,"t":"為那兩隻羊拈鬮，一鬮歸與耶和華，一鬮歸與阿撒瀉勒。","notes":[]},{"n":9,"t":"亞倫要把那拈鬮歸與耶和華的羊獻為贖罪祭，","notes":[]},{"n":10,"t":"但那拈鬮歸與阿撒瀉勒的羊要活著安置在耶和華面前，用以贖罪，打發人送到曠野去，歸與阿撒瀉勒。","notes":[]},{"n":11,"t":"「亞倫要把贖罪祭的公牛牽來宰了，為自己和本家贖罪；","notes":[]},{"n":12,"t":"拿香爐，從耶和華面前的壇上盛滿火炭，又拿一捧搗細的香料，都帶入幔子內，","notes":[]},{"n":13,"t":"在耶和華面前，把香放在火上，使香的煙雲遮掩法櫃上的施恩座，免得他死亡；","notes":[]},{"n":14,"t":"也要取些公牛的血，用指頭彈在施恩座的東面，又在施恩座的前面彈血七次。","notes":[]},{"n":15,"t":"「隨後他要宰那為百姓作贖罪祭的公山羊，把羊的血帶入幔子內，彈在施恩座的上面和前面，好像彈公牛的血一樣。","notes":[]},{"n":16,"t":"他因以色列人諸般的污穢、過犯，就是他們一切的罪愆，當這樣在聖所行贖罪之禮，並因會幕在他們污穢之中，也要照樣而行。","notes":[]},{"n":17,"t":"他進聖所贖罪的時候，會幕裏不可有人，直等到他為自己和本家並以色列全會眾贖了罪出來。","notes":[]},{"n":18,"t":"他出來，要到耶和華面前的壇那裏，在壇上行贖罪之禮，又要取些公牛的血和公山羊的血，抹在壇上四角的周圍；","notes":[]},{"n":19,"t":"也要用指頭把血彈在壇上七次，潔淨了壇，從壇上除掉以色列人諸般的污穢，使壇成聖。」","notes":[]},{"n":20,"t":"「亞倫為聖所和會幕並壇獻完了贖罪祭，就要把那隻活著的公山羊奉上。","notes":[],"heads":["代罪羊"]},{"n":21,"t":"兩手按在羊頭上，承認以色列人諸般的罪孽過犯，就是他們一切的罪愆，把這罪都歸在羊的頭上，藉著所派之人的手，送到曠野去。","notes":[]},{"n":22,"t":"要把這羊放在曠野，這羊要擔當他們一切的罪孽，帶到無人之地。","notes":[]},{"n":23,"t":"「亞倫要進會幕，把他進聖所時所穿的細麻布衣服脫下，放在那裏，","notes":[]},{"n":24,"t":"又要在聖處用水洗身，穿上衣服，出來，把自己的燔祭和百姓的燔祭獻上，為自己和百姓贖罪。","notes":[]},{"n":25,"t":"贖罪祭牲的脂油要在壇上焚燒。","notes":[]},{"n":26,"t":"那放羊歸與阿撒瀉勒的人要洗衣服，用水洗身，然後進營。","notes":[]},{"n":27,"t":"作贖罪祭的公牛和公山羊的血既帶入聖所贖罪，這牛羊就要搬到營外，將皮、肉、糞用火焚燒。","notes":[]},{"n":28,"t":"焚燒的人要洗衣服，用水洗身，然後進營。」","notes":[]},{"n":29,"t":"「每逢七月初十日，你們要刻苦己心，無論是本地人，是寄居在你們中間的外人，甚麼工都不可做；這要作你們永遠的定例。","notes":[],"heads":["守贖罪日"]},{"n":30,"t":"因在這日要為你們贖罪，使你們潔淨。你們要在耶和華面前得以潔淨，脫盡一切的罪愆。","notes":[]},{"n":31,"t":"這日你們要守為聖安息日，要刻苦己心；這為永遠的定例。","notes":[]},{"n":32,"t":"那受膏、接續他父親承接聖職的祭司要穿上細麻布的聖衣，行贖罪之禮。","notes":[]},{"n":33,"t":"他要在至聖所和會幕與壇行贖罪之禮，並要為眾祭司和會眾的百姓贖罪。","notes":[]},{"n":34,"t":"這要作你們永遠的定例－就是因以色列人一切的罪，要一年一次為他們贖罪。」於是，亞倫照耶和華所吩咐摩西的行了。","notes":[]}]},"17":{"heading":"血的神聖","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你曉諭亞倫和他兒子並以色列眾人說，耶和華所吩咐的乃是這樣：","notes":[]},{"n":3,"t":"凡以色列家中的人宰公牛，或是綿羊羔，或是山羊，不拘宰於營內營外，","notes":[]},{"n":4,"t":"若未曾牽到會幕門口、耶和華的帳幕前獻給耶和華為供物，流血的罪必歸到那人身上。他流了血，要從民中剪除。","notes":[]},{"n":5,"t":"這是為要使以色列人把他們在田野裏所獻的祭帶到會幕門口、耶和華面前，交給祭司，獻與耶和華為平安祭。","notes":[]},{"n":6,"t":"祭司要把血灑在會幕門口、耶和華的壇上，把脂油焚燒，獻給耶和華為馨香的祭。","notes":[]},{"n":7,"t":"他們不可再獻祭給他們行邪淫所隨從的鬼魔；這要作他們世世代代永遠的定例。","notes":["原文是公山羊"]},{"n":8,"t":"「你要曉諭他們說：凡以色列家中的人，或是寄居在他們中間的外人，獻燔祭或是平安祭，","notes":[]},{"n":9,"t":"若不帶到會幕門口獻給耶和華，那人必從民中剪除。","notes":[]},{"n":10,"t":"「凡以色列家中的人，或是寄居在他們中間的外人，若吃甚麼血，我必向那吃血的人變臉，把他從民中剪除。","notes":[]},{"n":11,"t":"因為活物的生命是在血中。我把這血賜給你們，可以在壇上為你們的生命贖罪；因血裏有生命，所以能贖罪。","notes":[]},{"n":12,"t":"因此，我對以色列人說：你們都不可吃血；寄居在你們中間的外人也不可吃血。","notes":[]},{"n":13,"t":"凡以色列人，或是寄居在他們中間的外人，若打獵得了可吃的禽獸，必放出牠的血來，用土掩蓋。","notes":[]},{"n":14,"t":"「論到一切活物的生命，就在血中。所以我對以色列人說：無論甚麼活物的血，你們都不可吃，因為一切活物的血就是他的生命。凡吃了血的，必被剪除。","notes":[]},{"n":15,"t":"凡吃自死的，或是被野獸撕裂的，無論是本地人，是寄居的，必不潔淨到晚上，都要洗衣服，用水洗身，到了晚上才為潔淨。","notes":[]},{"n":16,"t":"但他若不洗衣服，也不洗身，就必擔當他的罪孽。」","notes":[]}]},"18":{"heading":"有關淫亂的禁令","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你曉諭以色列人說：我是耶和華－你們的神。","notes":[]},{"n":3,"t":"你們從前住的埃及地，那裏人的行為，你們不可效法，我要領你們到的迦南地，那裏人的行為也不可效法，也不可照他們的惡俗行。","notes":[]},{"n":4,"t":"你們要遵我的典章，守我的律例，按此而行。我是耶和華－你們的神。","notes":[]},{"n":5,"t":"所以，你們要守我的律例典章；人若遵行，就必因此活著。我是耶和華。","notes":[]},{"n":6,"t":"「你們都不可露骨肉之親的下體，親近他們。我是耶和華。","notes":[]},{"n":7,"t":"不可露你母親的下體，羞辱了你父親。她是你的母親，不可露她的下體。","notes":[]},{"n":8,"t":"不可露你繼母的下體；這本是你父親的下體。","notes":[]},{"n":9,"t":"你的姊妹，不拘是異母同父的，是異父同母的，無論是生在家生在外的，都不可露她們的下體。","notes":[]},{"n":10,"t":"不可露你孫女或是外孫女的下體，露了她們的下體就是露了自己的下體。","notes":[]},{"n":11,"t":"你繼母從你父親生的女兒本是你的妹妹，不可露她的下體。","notes":[]},{"n":12,"t":"不可露你姑母的下體；她是你父親的骨肉之親。","notes":[]},{"n":13,"t":"不可露你姨母的下體；她是你母親的骨肉之親。","notes":[]},{"n":14,"t":"不可親近你伯叔之妻，羞辱了你伯叔；她是你的伯叔母。","notes":[]},{"n":15,"t":"不可露你兒婦的下體；她是你兒子的妻，不可露她的下體。","notes":[]},{"n":16,"t":"不可露你弟兄妻子的下體；這本是你弟兄的下體。","notes":[]},{"n":17,"t":"不可露了婦人的下體，又露她女兒的下體，也不可娶她孫女或是外孫女，露她們的下體；她們是骨肉之親，這本是大惡。","notes":[]},{"n":18,"t":"你妻還在的時候，不可另娶她的姊妹作對頭，露她的下體。","notes":[]},{"n":19,"t":"「女人行經不潔淨的時候，不可露她的下體，與她親近。","notes":[]},{"n":20,"t":"不可與鄰舍的妻行淫，玷污自己。","notes":[]},{"n":21,"t":"不可使你的兒女經火歸與摩洛，也不可褻瀆你神的名。我是耶和華。","notes":[]},{"n":22,"t":"不可與男人苟合，像與女人一樣；這本是可憎惡的。","notes":[]},{"n":23,"t":"不可與獸淫合，玷污自己。女人也不可站在獸前，與牠淫合；這本是逆性的事。","notes":[]},{"n":24,"t":"「在這一切的事上，你們都不可玷污自己；因為我在你們面前所逐出的列邦，在這一切的事上玷污了自己；","notes":[]},{"n":25,"t":"連地也玷污了，所以我追討那地的罪孽，那地也吐出它的居民。","notes":[]},{"n":26,"t":"故此，你們要守我的律例典章。這一切可憎惡的事，無論是本地人，是寄居在你們中間的外人，都不可行，（","notes":[]},{"n":27,"t":"在你們以先居住那地的人行了這一切可憎惡的事，地就玷污了，）","notes":[]},{"n":28,"t":"免得你們玷污那地的時候，地就把你們吐出，像吐出在你們以先的國民一樣。","notes":[]},{"n":29,"t":"無論甚麼人，行了其中可憎的一件事，必從民中剪除。","notes":[]},{"n":30,"t":"所以，你們要守我所吩咐的，免得你們隨從那些可憎的惡俗，就是在你們以先的人所常行的，以致玷污了自己。我是耶和華－你們的神。」","notes":[]}]},"19":{"heading":"聖潔和公正的法例","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你曉諭以色列全會眾說：你們要聖潔，因為我耶和華－你們的神是聖潔的。","notes":[]},{"n":3,"t":"你們各人都當孝敬父母，也要守我的安息日。我是耶和華－你們的神。","notes":[]},{"n":4,"t":"你們不可偏向虛無的神，也不可為自己鑄造神像。我是耶和華－你們的神。","notes":[]},{"n":5,"t":"你們獻平安祭給耶和華的時候，要獻得可蒙悅納。","notes":[]},{"n":6,"t":"這祭物要在獻的那一天和第二天吃，若有剩到第三天的，就必用火焚燒。","notes":[]},{"n":7,"t":"第三天若再吃，這就為可憎惡的，必不蒙悅納。","notes":[]},{"n":8,"t":"凡吃的人必擔當他的罪孽；因為他褻瀆了耶和華的聖物，那人必從民中剪除。","notes":[]},{"n":9,"t":"「在你們的地收割莊稼，不可割盡田角，也不可拾取所遺落的。","notes":[]},{"n":10,"t":"不可摘盡葡萄園的果子，也不可拾取葡萄園所掉的果子；要留給窮人和寄居的。我是耶和華－你們的神。","notes":[]},{"n":11,"t":"「你們不可偷盜，不可欺騙，也不可彼此說謊。","notes":[]},{"n":12,"t":"不可指著我的名起假誓，褻瀆你神的名。我是耶和華。","notes":[]},{"n":13,"t":"「不可欺壓你的鄰舍，也不可搶奪他的物。雇工人的工價，不可在你那裏過夜，留到早晨。","notes":[]},{"n":14,"t":"不可咒罵聾子，也不可將絆腳石放在瞎子面前，只要敬畏你的神。我是耶和華。","notes":[]},{"n":15,"t":"「你們施行審判，不可行不義；不可偏護窮人，也不可重看有勢力的人，只要按著公義審判你的鄰舍。","notes":[]},{"n":16,"t":"不可在民中往來搬弄是非，也不可與鄰舍為敵，置之於死。我是耶和華。","notes":["原文是流他的血"]},{"n":17,"t":"「不可心裏恨你的弟兄；總要指摘你的鄰舍，免得因他擔罪。","notes":[]},{"n":18,"t":"不可報仇，也不可埋怨你本國的子民，卻要愛人如己。我是耶和華。","notes":[]},{"n":19,"t":"「你們要守我的律例。不可叫你的牲畜與異類配合；不可用兩樣攙雜的種種你的地，也不可用兩樣攙雜的料做衣服穿在身上。","notes":[]},{"n":20,"t":"「婢女許配了丈夫，還沒有被贖、得釋放，人若與她行淫，二人要受刑罰，卻不把他們治死，因為婢女還沒有得自由。","notes":[]},{"n":21,"t":"那人要把贖愆祭，就是一隻公綿羊牽到會幕門口、耶和華面前。","notes":[]},{"n":22,"t":"祭司要用贖愆祭的羊在耶和華面前贖他所犯的罪，他的罪就必蒙赦免。","notes":[]},{"n":23,"t":"「你們到了迦南地，栽種各樣結果子的樹木，就要以所結的果子如未受割禮的一樣。三年之久，你們要以這些果子，如未受割禮的，是不可吃的。","notes":[]},{"n":24,"t":"但第四年所結的果子全要成為聖，用以讚美耶和華。","notes":[]},{"n":25,"t":"第五年，你們要吃那樹上的果子，好叫樹給你們結果子更多。我是耶和華－你們的神。","notes":[]},{"n":26,"t":"「你們不可吃帶血的物；不可用法術，也不可觀兆。","notes":[]},{"n":27,"t":"頭的周圍不可剃，鬍鬚的周圍也不可損壞。","notes":["或譯：兩鬢"]},{"n":28,"t":"不可為死人用刀劃身，也不可在身上刺花紋。我是耶和華。","notes":[]},{"n":29,"t":"「不可辱沒你的女兒，使她為娼妓，恐怕地上的人專向淫亂，地就滿了大惡。","notes":[]},{"n":30,"t":"你們要守我的安息日，敬我的聖所。我是耶和華。","notes":[]},{"n":31,"t":"「不可偏向那些交鬼的和行巫術的；不可求問他們，以致被他們玷污了。我是耶和華－你們的神。","notes":[]},{"n":32,"t":"「在白髮的人面前，你要站起來；也要尊敬老人，又要敬畏你的神。我是耶和華。","notes":[]},{"n":33,"t":"「若有外人在你們國中和你同居，就不可欺負他。","notes":[]},{"n":34,"t":"和你們同居的外人，你們要看他如本地人一樣，並要愛他如己，因為你們在埃及地也作過寄居的。我是耶和華－你們的神。","notes":[]},{"n":35,"t":"「你們施行審判，不可行不義；在尺、秤、升、斗上也是如此。","notes":[]},{"n":36,"t":"要用公道天平、公道法碼、公道升斗、公道秤。我是耶和華－你們的神，曾把你們從埃及地領出來的。","notes":[]},{"n":37,"t":"你們要謹守遵行我一切的律例典章。我是耶和華。」","notes":[]}]},"20":{"heading":"處罰悖逆的人","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你還要曉諭以色列人說：凡以色列人，或是在以色列中寄居的外人，把自己的兒女獻給摩洛的，總要治死他；本地人要用石頭把他打死。","notes":[]},{"n":3,"t":"我也要向那人變臉，把他從民中剪除；因為他把兒女獻給摩洛，玷污我的聖所，褻瀆我的聖名。","notes":[]},{"n":4,"t":"那人把兒女獻給摩洛，本地人若佯為不見，不把他治死，","notes":[]},{"n":5,"t":"我就要向這人和他的家變臉，把他和一切隨他與摩洛行邪淫的人都從民中剪除。","notes":[]},{"n":6,"t":"「人偏向交鬼的和行巫術的，隨他們行邪淫，我要向那人變臉，把他從民中剪除。","notes":[]},{"n":7,"t":"所以你們要自潔成聖，因為我是耶和華－你們的神。","notes":[]},{"n":8,"t":"你們要謹守遵行我的律例；我是叫你們成聖的耶和華。","notes":[]},{"n":9,"t":"凡咒罵父母的，總要治死他；他咒罵了父母，他的罪要歸到他身上。","notes":["原文是血；本章同"]},{"n":10,"t":"「與鄰舍之妻行淫的，姦夫淫婦都必治死。","notes":[]},{"n":11,"t":"與繼母行淫的，就是羞辱了他父親，總要把他們二人治死，罪要歸到他們身上。","notes":[]},{"n":12,"t":"與兒婦同房的，總要把他們二人治死；他們行了逆倫的事，罪要歸到他們身上。","notes":[]},{"n":13,"t":"人若與男人苟合，像與女人一樣，他們二人行了可憎的事，總要把他們治死，罪要歸到他們身上。","notes":[]},{"n":14,"t":"人若娶妻，並娶其母，便是大惡，要把這三人用火焚燒，使你們中間免去大惡。","notes":[]},{"n":15,"t":"人若與獸淫合，總要治死他，也要殺那獸。","notes":[]},{"n":16,"t":"女人若與獸親近，與牠淫合，你要殺那女人和那獸，總要把他們治死，罪要歸到他們身上。","notes":[]},{"n":17,"t":"「人若娶他的姊妹，無論是異母同父的，是異父同母的，彼此見了下體，這是可恥的事；他們必在本民的眼前被剪除。他露了姊妹的下體，必擔當自己的罪孽。","notes":[]},{"n":18,"t":"婦人有月經，若與她同房，露了她的下體，就是露了婦人的血源，婦人也露了自己的血源，二人必從民中剪除。","notes":[]},{"n":19,"t":"不可露姨母或是姑母的下體，這是露了骨肉之親的下體；二人必擔當自己的罪孽。","notes":[]},{"n":20,"t":"人若與伯叔之妻同房，就羞辱了他的伯叔；二人要擔當自己的罪，必無子女而死。","notes":[]},{"n":21,"t":"人若娶弟兄之妻，這本是污穢的事，羞辱了他的弟兄；二人必無子女。","notes":[]},{"n":22,"t":"「所以，你們要謹守遵行我一切的律例典章，免得我領你們去住的那地把你們吐出。","notes":[]},{"n":23,"t":"我在你們面前所逐出的國民，你們不可隨從他們的風俗；因為他們行了這一切的事，所以我厭惡他們。","notes":[]},{"n":24,"t":"但我對你們說過，你們要承受他們的地，就是我要賜給你們為業、流奶與蜜之地。我是耶和華－你們的神，使你們與萬民有分別的。","notes":[]},{"n":25,"t":"所以，你們要把潔淨和不潔淨的禽獸分別出來；不可因我給你們分為不潔淨的禽獸，或是滋生在地上的活物，使自己成為可憎惡的。","notes":[]},{"n":26,"t":"你們要歸我為聖，因為我－耶和華是聖的，並叫你們與萬民有分別，使你們作我的民。","notes":[]},{"n":27,"t":"「無論男女，是交鬼的或行巫術的，總要治死他們。人必用石頭把他們打死，罪要歸到他們身上。」","notes":[]}]},"21":{"heading":"祭司聖潔的條例","verses":[{"n":1,"t":"耶和華對摩西說：「你告訴亞倫子孫作祭司的說：祭司不可為民中的死人沾染自己，","notes":[]},{"n":2,"t":"除非為他骨肉之親的父母、兒女、弟兄，","notes":[]},{"n":3,"t":"和未曾出嫁、作處女的姊妹，才可以沾染自己。","notes":[]},{"n":4,"t":"祭司既在民中為首，就不可從俗沾染自己。","notes":[]},{"n":5,"t":"不可使頭光禿；不可剃除鬍鬚的周圍，也不可用刀劃身。","notes":[]},{"n":6,"t":"要歸神為聖，不可褻瀆神的名；因為耶和華的火祭，就是神的食物，是他們獻的，所以他們要成為聖。","notes":[]},{"n":7,"t":"不可娶妓女或被污的女人為妻，也不可娶被休的婦人為妻，因為祭司是歸神為聖。","notes":[]},{"n":8,"t":"所以你要使他成聖，因為他奉獻你神的食物；你要以他為聖，因為我－使你們成聖的耶和華－是聖的。","notes":[]},{"n":9,"t":"祭司的女兒若行淫辱沒自己，就辱沒了父親，必用火將她焚燒。","notes":[]},{"n":10,"t":"「在弟兄中作大祭司、頭上倒了膏油、又承接聖職、穿了聖衣的，不可蓬頭散髮，也不可撕裂衣服。","notes":[]},{"n":11,"t":"不可挨近死屍，也不可為父母沾染自己。","notes":[]},{"n":12,"t":"不可出聖所，也不可褻瀆神的聖所，因為神膏油的冠冕在他頭上。我是耶和華。","notes":[]},{"n":13,"t":"他要娶處女為妻。","notes":[]},{"n":14,"t":"寡婦或是被休的婦人，或是被污為妓的女人，都不可娶；只可娶本民中的處女為妻。","notes":[]},{"n":15,"t":"不可在民中辱沒他的兒女，因為我是叫他成聖的耶和華。」","notes":[]},{"n":16,"t":"耶和華對摩西說：","notes":[]},{"n":17,"t":"「你告訴亞倫說：你世世代代的後裔，凡有殘疾的，都不可近前來獻他神的食物。","notes":[]},{"n":18,"t":"因為凡有殘疾的，無論是瞎眼的、瘸腿的、塌鼻子的、肢體有餘的、","notes":[]},{"n":19,"t":"折腳折手的、","notes":[]},{"n":20,"t":"駝背的、矮矬的、眼睛有毛病的、長癬的、長疥的，或是損壞腎子的，都不可近前來。","notes":[]},{"n":21,"t":"祭司亞倫的後裔，凡有殘疾的，都不可近前來，將火祭獻給耶和華。他有殘疾，不可近前來獻神的食物。","notes":[]},{"n":22,"t":"神的食物，無論是聖的，至聖的，他都可以吃。","notes":[]},{"n":23,"t":"但不可進到幔子前，也不可就近壇前；因為他有殘疾，免得褻瀆我的聖所。我是叫他成聖的耶和華。」","notes":[]},{"n":24,"t":"於是，摩西曉諭亞倫和亞倫的子孫，並以色列眾人。","notes":[]}]},"22":{"heading":"聖物的聖潔","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你吩咐亞倫和他子孫說：要遠離以色列人所分別為聖、歸給我的聖物，免得褻瀆我的聖名。我是耶和華。","notes":[]},{"n":3,"t":"你要對他們說：你們世世代代的後裔，凡身上有污穢、親近以色列人所分別為聖、歸耶和華聖物的，那人必在我面前剪除。我是耶和華。","notes":[]},{"n":4,"t":"亞倫的後裔，凡長大痲瘋的，或是有漏症的，不可吃聖物，直等他潔淨了。無論誰摸那因死屍不潔淨的物，或是遺精的人，","notes":["或譯：人"]},{"n":5,"t":"或是摸甚麼使他不潔淨的爬物，或是摸那使他不潔淨的人（不拘那人有甚麼不潔淨），","notes":[]},{"n":6,"t":"摸了這些人、物的，必不潔淨到晚上；若不用水洗身，就不可吃聖物。","notes":[]},{"n":7,"t":"日落的時候，他就潔淨了，然後可以吃聖物，因為這是他的食物。","notes":[]},{"n":8,"t":"自死的或是被野獸撕裂的，他不可吃，因此污穢自己。我是耶和華。","notes":[]},{"n":9,"t":"所以他們要守我所吩咐的，免得輕忽了，因此擔罪而死。我是叫他們成聖的耶和華。","notes":[]},{"n":10,"t":"「凡外人不可吃聖物；寄居在祭司家的，或是雇工人，都不可吃聖物；","notes":[]},{"n":11,"t":"倘若祭司買人，是他的錢買的，那人就可以吃聖物；生在他家的人也可以吃。","notes":[]},{"n":12,"t":"祭司的女兒若嫁外人，就不可吃舉祭的聖物。","notes":[]},{"n":13,"t":"但祭司的女兒若是寡婦，或是被休的，沒有孩子，又歸回父家，與她青年一樣，就可以吃她父親的食物；只是外人不可吃。","notes":[]},{"n":14,"t":"若有人誤吃了聖物，要照聖物的原數加上五分之一交給祭司。","notes":[]},{"n":15,"t":"祭司不可褻瀆以色列人所獻給耶和華的聖物，","notes":[]},{"n":16,"t":"免得他們在吃聖物上自取罪孽，因為我是叫他們成聖的耶和華。」","notes":[]},{"n":17,"t":"耶和華對摩西說：","notes":[]},{"n":18,"t":"「你曉諭亞倫和他子孫，並以色列眾人說：以色列家中的人，或在以色列中寄居的，凡獻供物，無論是所許的願，是甘心獻的，就是獻給耶和華作燔祭的，","notes":[]},{"n":19,"t":"要將沒有殘疾的公牛，或是綿羊，或是山羊獻上，如此方蒙悅納。","notes":[]},{"n":20,"t":"凡有殘疾的，你們不可獻上，因為這不蒙悅納。","notes":[]},{"n":21,"t":"凡從牛群或是羊群中，將平安祭獻給耶和華，為要還特許的願，或是作甘心獻的，所獻的必純全無殘疾的才蒙悅納。","notes":[]},{"n":22,"t":"瞎眼的、折傷的、殘廢的、有瘤子的、長癬的、長疥的都不可獻給耶和華，也不可在壇上作為火祭獻給耶和華。","notes":[]},{"n":23,"t":"無論是公牛是綿羊羔，若肢體有餘的，或是缺少的，只可作甘心祭獻上；用以還願，卻不蒙悅納。","notes":[]},{"n":24,"t":"腎子損傷的，或是壓碎的，或是破裂的，或是騸了的，不可獻給耶和華，在你們的地上也不可這樣行。","notes":[]},{"n":25,"t":"這類的物，你們從外人的手，一樣也不可接受作你們神的食物獻上；因為這些都有損壞，有殘疾，不蒙悅納。」","notes":[]},{"n":26,"t":"耶和華曉諭摩西說：","notes":[]},{"n":27,"t":"「才生的公牛，或是綿羊或是山羊，七天當跟著母；從第八天以後，可以當供物蒙悅納，作為耶和華的火祭。","notes":[]},{"n":28,"t":"無論是母牛是母羊，不可同日宰母和子。","notes":[]},{"n":29,"t":"你們獻感謝祭給耶和華，要獻得可蒙悅納。","notes":[]},{"n":30,"t":"要當天吃，一點不可留到早晨。我是耶和華。","notes":[]},{"n":31,"t":"「你們要謹守遵行我的誡命。我是耶和華。","notes":[]},{"n":32,"t":"你們不可褻瀆我的聖名；我在以色列人中，卻要被尊為聖。我是叫你們成聖的耶和華，","notes":[]},{"n":33,"t":"把你們從埃及地領出來，作你們的神。我是耶和華。」","notes":[]}]},"23":{"heading":"節期","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你曉諭以色列人說：耶和華的節期，你們要宣告為聖會的節期。","notes":[]},{"n":3,"t":"六日要做工，第七日是聖安息日，當有聖會；你們甚麼工都不可做。這是在你們一切的住處向耶和華守的安息日。","notes":[]},{"n":4,"t":"耶和華的節期，就是你們到了日期要宣告為聖會的，乃是這些。」","notes":[]},{"n":5,"t":"「正月十四日，黃昏的時候，是耶和華的逾越節。","notes":[],"heads":["逾越節和除酵節"]},{"n":6,"t":"這月十五日是向耶和華守的無酵節；你們要吃無酵餅七日。","notes":[]},{"n":7,"t":"第一日當有聖會，甚麼勞碌的工都不可做；","notes":[]},{"n":8,"t":"要將火祭獻給耶和華七日。第七日是聖會，甚麼勞碌的工都不可做。」","notes":[]},{"n":9,"t":"耶和華對摩西說：","notes":[]},{"n":10,"t":"「你曉諭以色列人說：你們到了我賜給你們的地，收割莊稼的時候，要將初熟的莊稼一捆帶給祭司。","notes":[]},{"n":11,"t":"他要把這一捆在耶和華面前搖一搖，使你們得蒙悅納。祭司要在安息日的次日把這捆搖一搖。","notes":[]},{"n":12,"t":"搖這捆的日子，你們要把一歲、沒有殘疾的公綿羊羔獻給耶和華為燔祭。","notes":[]},{"n":13,"t":"同獻的素祭，就是調油的細麵伊法十分之二，作為馨香的火祭，獻給耶和華。同獻的奠祭，要酒一欣四分之一。","notes":[]},{"n":14,"t":"無論是餅，是烘的子粒，是新穗子，你們都不可吃，直等到把你們獻給神的供物帶來的那一天才可以吃。這在你們一切的住處作為世世代代永遠的定例。」","notes":[]},{"n":15,"t":"「你們要從安息日的次日，獻禾捆為搖祭的那日算起，要滿了七個安息日。","notes":[],"heads":["五旬收穫節"]},{"n":16,"t":"到第七個安息日的次日，共計五十天，又要將新素祭獻給耶和華。","notes":[]},{"n":17,"t":"要從你們的住處取出細麵伊法十分之二，加酵，烤成兩個搖祭的餅，當作初熟之物獻給耶和華。","notes":[]},{"n":18,"t":"又要將一歲、沒有殘疾的羊羔七隻、公牛犢一隻、公綿羊兩隻，和餅一同奉上。這些與同獻的素祭和奠祭要作為燔祭獻給耶和華，就是作馨香的火祭獻給耶和華。","notes":[]},{"n":19,"t":"你們要獻一隻公山羊為贖罪祭，兩隻一歲的公綿羊羔為平安祭。","notes":[]},{"n":20,"t":"祭司要把這些和初熟麥子做的餅一同作搖祭，在耶和華面前搖一搖；這是獻與耶和華為聖物歸給祭司的。","notes":[]},{"n":21,"t":"當這日，你們要宣告聖會；甚麼勞碌的工都不可做。這在你們一切的住處作為世世代代永遠的定例。","notes":[]},{"n":22,"t":"「在你們的地收割莊稼，不可割盡田角，也不可拾取所遺落的；要留給窮人和寄居的。我是耶和華－你們的神。」","notes":[]},{"n":23,"t":"耶和華對摩西說：","notes":[],"heads":["新年"]},{"n":24,"t":"「你曉諭以色列人說：七月初一，你們要守為聖安息日，要吹角作紀念，當有聖會。","notes":[]},{"n":25,"t":"甚麼勞碌的工都不可做；要將火祭獻給耶和華。」","notes":[]},{"n":26,"t":"耶和華曉諭摩西說：","notes":[],"heads":["贖罪日"]},{"n":27,"t":"「七月初十是贖罪日；你們要守為聖會，並要刻苦己心，也要將火祭獻給耶和華。","notes":[]},{"n":28,"t":"當這日，甚麼工都不可做；因為是贖罪日，要在耶和華－你們的神面前贖罪。","notes":[]},{"n":29,"t":"當這日，凡不刻苦己心的，必從民中剪除。","notes":[]},{"n":30,"t":"凡這日做甚麼工的，我必將他從民中除滅。","notes":[]},{"n":31,"t":"你們甚麼工都不可做。這在你們一切的住處作為世世代代永遠的定例。","notes":[]},{"n":32,"t":"你們要守這日為聖安息日，並要刻苦己心。從這月初九日晚上到次日晚上，要守為安息日。」","notes":[]},{"n":33,"t":"耶和華對摩西說：","notes":[],"heads":["住棚節"]},{"n":34,"t":"「你曉諭以色列人說：這七月十五日是住棚節，要在耶和華面前守這節七日。","notes":[]},{"n":35,"t":"第一日當有聖會，甚麼勞碌的工都不可做。","notes":[]},{"n":36,"t":"七日內要將火祭獻給耶和華。第八日當守聖會，要將火祭獻給耶和華。這是嚴肅會，甚麼勞碌的工都不可做。","notes":[]},{"n":37,"t":"「這是耶和華的節期，就是你們要宣告為聖會的節期；要將火祭、燔祭、素祭、祭物，並奠祭，各歸各日，獻給耶和華。","notes":[]},{"n":38,"t":"這是在耶和華的安息日以外，又在你們的供物和所許的願，並甘心獻給耶和華的以外。","notes":[]},{"n":39,"t":"「你們收藏了地的出產，就從七月十五日起，要守耶和華的節七日。第一日為聖安息；第八日也為聖安息。","notes":[]},{"n":40,"t":"第一日要拿美好樹上的果子和棕樹上的枝子，與茂密樹的枝條並河旁的柳枝，在耶和華－你們的神面前歡樂七日。","notes":[]},{"n":41,"t":"每年七月間，要向耶和華守這節七日。這為你們世世代代永遠的定例。","notes":[]},{"n":42,"t":"你們要住在棚裏七日；凡以色列家的人都要住在棚裏，","notes":[]},{"n":43,"t":"好叫你們世世代代知道，我領以色列人出埃及地的時候曾使他們住在棚裏。我是耶和華－你們的神。」","notes":[]},{"n":44,"t":"於是，摩西將耶和華的節期傳給以色列人。","notes":[]}]},"24":{"heading":"燃燈的條例","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「要吩咐以色列人，把那為點燈搗成的清橄欖油拿來給你，使燈常常點著。","notes":[]},{"n":3,"t":"在會幕中法櫃的幔子外，亞倫從晚上到早晨必在耶和華面前經理這燈。這要作你們世世代代永遠的定例。","notes":[]},{"n":4,"t":"他要在耶和華面前常收拾精金燈臺上的燈。」","notes":[]},{"n":5,"t":"「你要取細麵，烤成十二個餅，每餅用麵伊法十分之二。","notes":[],"heads":["陳設餅"]},{"n":6,"t":"要把餅擺列兩行，每行六個，在耶和華面前精金的桌子上；","notes":["或譯：摞；下同"]},{"n":7,"t":"又要把淨乳香放在每行餅上，作為紀念，就是作為火祭獻給耶和華。","notes":[]},{"n":8,"t":"每安息日要常擺在耶和華面前；這為以色列人作永遠的約。","notes":[]},{"n":9,"t":"這餅是要給亞倫和他子孫的；他們要在聖處吃，為永遠的定例，因為在獻給耶和華的火祭中是至聖的。」","notes":[]},{"n":10,"t":"有一個以色列婦人的兒子，他父親是埃及人，一日閒遊在以色列人中。這以色列婦人的兒子和一個以色列人在營裏爭鬥。","notes":[],"heads":["公正的判例"]},{"n":11,"t":"這以色列婦人的兒子褻瀆了聖名，並且咒詛，就有人把他送到摩西那裏。（他母親名叫示羅密，是但支派底伯利的女兒。）","notes":[]},{"n":12,"t":"他們把那人收在監裏，要得耶和華所指示的話。","notes":[]},{"n":13,"t":"耶和華曉諭摩西說：","notes":[]},{"n":14,"t":"「把那咒詛聖名的人帶到營外。叫聽見的人都放手在他頭上；全會眾就要用石頭打死他。","notes":[]},{"n":15,"t":"你要曉諭以色列人說：凡咒詛神的，必擔當他的罪。","notes":[]},{"n":16,"t":"那褻瀆耶和華名的，必被治死；全會眾總要用石頭打死他。不管是寄居的是本地人，他褻瀆耶和華名的時候，必被治死。","notes":[]},{"n":17,"t":"打死人的，必被治死；","notes":[]},{"n":18,"t":"打死牲畜的，必賠上牲畜，以命償命。","notes":[]},{"n":19,"t":"人若使他鄰舍的身體有殘疾，他怎樣行，也要照樣向他行：","notes":[]},{"n":20,"t":"以傷還傷，以眼還眼，以牙還牙。他怎樣叫人的身體有殘疾，也要照樣向他行。","notes":[]},{"n":21,"t":"打死牲畜的，必賠上牲畜；打死人的，必被治死。","notes":[]},{"n":22,"t":"不管是寄居的是本地人，同歸一例。我是耶和華－你們的神。」","notes":[]},{"n":23,"t":"於是，摩西曉諭以色列人，他們就把那咒詛聖名的人帶到營外，用石頭打死。以色列人就照耶和華所吩咐摩西的行了。","notes":[]}]},"25":{"heading":"安息年","verses":[{"n":1,"t":"耶和華在西奈山對摩西說：","notes":[]},{"n":2,"t":"「你曉諭以色列人說：你們到了我所賜你們那地的時候，地就要向耶和華守安息。","notes":[]},{"n":3,"t":"六年要耕種田地，也要修理葡萄園，收藏地的出產。","notes":[]},{"n":4,"t":"第七年，地要守聖安息，就是向耶和華守的安息，不可耕種田地，也不可修理葡萄園。","notes":[]},{"n":5,"t":"遺落自長的莊稼不可收割；沒有修理的葡萄樹也不可摘取葡萄。這年，地要守聖安息。","notes":[]},{"n":6,"t":"地在安息年所出的，要給你和你的僕人、婢女、雇工人，並寄居的外人當食物。","notes":[]},{"n":7,"t":"這年的土產也要給你的牲畜和你地上的走獸當食物。」","notes":[]},{"n":8,"t":"「你要計算七個安息年，就是七七年。這便為你成了七個安息年，共是四十九年。","notes":[],"heads":["禧年"]},{"n":9,"t":"當年七月初十日，你要大發角聲；這日就是贖罪日，要在遍地發出角聲。","notes":[]},{"n":10,"t":"第五十年，你們要當作聖年，在遍地給一切的居民宣告自由。這年必為你們的禧年，各人要歸自己的產業，各歸本家。","notes":[]},{"n":11,"t":"第五十年要作為你們的禧年。這年不可耕種；地中自長的，不可收割；沒有修理的葡萄樹也不可摘取葡萄。","notes":[]},{"n":12,"t":"因為這是禧年，你們要當作聖年，吃地中自出的土產。","notes":[]},{"n":13,"t":"「這禧年，你們各人要歸自己的地業。","notes":[]},{"n":14,"t":"你若賣甚麼給鄰舍，或是從鄰舍的手中買甚麼，彼此不可虧負。","notes":[]},{"n":15,"t":"你要按禧年以後的年數向鄰舍買；他也要按年數的收成賣給你。","notes":[]},{"n":16,"t":"年歲若多，要照數加添價值；年歲若少，要照數減去價值，因為他照收成的數目賣給你。","notes":[]},{"n":17,"t":"你們彼此不可虧負，只要敬畏你們的神，因為我是耶和華－你們的神。」","notes":[]},{"n":18,"t":"「我的律例，你們要遵行，我的典章，你們要謹守，就可以在那地上安然居住。","notes":[],"heads":["安息年的問題"]},{"n":19,"t":"地必出土產，你們就要吃飽，在那地上安然居住。","notes":[]},{"n":20,"t":"你們若說：『這第七年我們不耕種，也不收藏土產，吃甚麼呢？』","notes":[]},{"n":21,"t":"我必在第六年將我所命的福賜給你們，地便生三年的土產。","notes":[]},{"n":22,"t":"第八年，你們要耕種，也要吃陳糧，等到第九年出產收來的時候，你們還吃陳糧。」","notes":[]},{"n":23,"t":"「地不可永賣，因為地是我的；你們在我面前是客旅，是寄居的。","notes":[],"heads":["贖房地產的條例"]},{"n":24,"t":"在你們所得為業的全地，也要准人將地贖回。","notes":[]},{"n":25,"t":"你的弟兄若漸漸窮乏，賣了幾分地業，他至近的親屬就要來把弟兄所賣的贖回。","notes":["弟兄是指本國人說；下同"]},{"n":26,"t":"若沒有能給他贖回的，他自己漸漸富足，能夠贖回，","notes":[]},{"n":27,"t":"就要算出賣地的年數，把餘剩年數的價值還那買主，自己便歸回自己的地業。","notes":[]},{"n":28,"t":"倘若不能為自己得回所賣的，仍要存在買主的手裏直到禧年；到了禧年，地業要出買主的手，自己便歸回自己的地業。","notes":[]},{"n":29,"t":"「人若賣城內的住宅，賣了以後，一年之內可以贖回；在一整年，必有贖回的權柄。","notes":[]},{"n":30,"t":"若在一整年之內不贖回，這城內的房屋就定准永歸買主，世世代代為業；在禧年也不得出買主的手。","notes":[]},{"n":31,"t":"但房屋在無城牆的村莊裏，要看如鄉下的田地一樣，可以贖回；到了禧年，都要出買主的手。","notes":[]},{"n":32,"t":"然而利未人所得為業的城邑，其中的房屋，利未人可以隨時贖回。","notes":[]},{"n":33,"t":"若是一個利未人不將所賣的房屋贖回，是在所得為業的城內，到了禧年就要出買主的手，因為利未人城邑的房屋是他們在以色列人中的產業。","notes":[]},{"n":34,"t":"只是他們各城郊野之地不可賣，因為是他們永遠的產業。」","notes":[]},{"n":35,"t":"「你的弟兄在你那裏若漸漸貧窮，手中缺乏，你就要幫補他，使他與你同住，像外人和寄居的一樣。","notes":[],"heads":["借貸給窮人的條例"]},{"n":36,"t":"不可向他取利，也不可向他多要；只要敬畏你的神，使你的弟兄與你同住。","notes":[]},{"n":37,"t":"你借錢給他，不可向他取利；借糧給他，也不可向他多要。","notes":[]},{"n":38,"t":"我是耶和華－你們的神，曾領你們從埃及地出來，為要把迦南地賜給你們，要作你們的神。」","notes":[]},{"n":39,"t":"「你的弟兄若在你那裏漸漸窮乏，將自己賣給你，不可叫他像奴僕服事你。","notes":[],"heads":["贖回奴僕的條例"]},{"n":40,"t":"他要在你那裏像雇工人和寄居的一樣，要服事你直到禧年。","notes":[]},{"n":41,"t":"到了禧年，他和他兒女要離開你，一同出去歸回本家，到他祖宗的地業那裏去。","notes":[]},{"n":42,"t":"因為他們是我的僕人，是我從埃及地領出來的，不可賣為奴僕。","notes":[]},{"n":43,"t":"不可嚴嚴地轄管他，只要敬畏你的神。","notes":[]},{"n":44,"t":"至於你的奴僕、婢女，可以從你四圍的國中買。","notes":[]},{"n":45,"t":"並且那寄居在你們中間的外人和他們的家屬，在你們地上所生的，你們也可以從其中買人；他們要作你們的產業。","notes":[]},{"n":46,"t":"你們要將他們遺留給你們的子孫為產業，要永遠從他們中間揀出奴僕；只是你們的弟兄以色列人，你們不可嚴嚴地轄管。","notes":[]},{"n":47,"t":"「住在你那裏的外人，或是寄居的，若漸漸富足，你的弟兄卻漸漸窮乏，將自己賣給那外人，或是寄居的，或是外人的宗族，","notes":[]},{"n":48,"t":"賣了以後，可以將他贖回。無論是他的弟兄，","notes":[]},{"n":49,"t":"或伯叔、伯叔的兒子，本家的近支，都可以贖他。他自己若漸漸富足，也可以自贖。","notes":[]},{"n":50,"t":"他要和買主計算，從賣自己的那年起，算到禧年；所賣的價值照著年數多少，好像工人每年的工價。","notes":[]},{"n":51,"t":"若缺少的年數多，就要按著年數從買價中償還他的贖價。","notes":[]},{"n":52,"t":"若到禧年只缺少幾年，就要按著年數和買主計算，償還他的贖價。","notes":[]},{"n":53,"t":"他和買主同住，要像每年雇的工人，買主不可嚴嚴地轄管他。","notes":[]},{"n":54,"t":"他若不這樣被贖，到了禧年，要和他的兒女一同出去。","notes":[]},{"n":55,"t":"因為以色列人都是我的僕人，是我從埃及地領出來的。我是耶和華－你們的神。」","notes":[]}]},"26":{"heading":"遵行誡命者的福祉","verses":[{"n":1,"t":"「你們不可做甚麼虛無的神像，不可立雕刻的偶像或是柱像，也不可在你們的地上安甚麼鏨成的石像，向它跪拜，因為我是耶和華－你們的神。","notes":[]},{"n":2,"t":"你們要守我的安息日，敬我的聖所。我是耶和華。","notes":[]},{"n":3,"t":"「你們若遵行我的律例，謹守我的誡命，","notes":[]},{"n":4,"t":"我就給你們降下時雨，叫地生出土產，田野的樹木結果子。","notes":[]},{"n":5,"t":"你們打糧食要打到摘葡萄的時候，摘葡萄要摘到撒種的時候；並且要吃得飽足，在你們的地上安然居住。","notes":[]},{"n":6,"t":"我要賜平安在你們的地上；你們躺臥，無人驚嚇。我要叫惡獸從你們的地上熄滅；刀劍也必不經過你們的地。","notes":[]},{"n":7,"t":"你們要追趕仇敵，他們必倒在你們刀下。","notes":[]},{"n":8,"t":"你們五個人要追趕一百人，一百人要追趕一萬人；仇敵必倒在你們刀下。","notes":[]},{"n":9,"t":"我要眷顧你們，使你們生養眾多，也要與你們堅定所立的約。","notes":[]},{"n":10,"t":"你們要吃陳糧，又因新糧挪開陳糧。","notes":[]},{"n":11,"t":"我要在你們中間立我的帳幕；我的心也不厭惡你們。","notes":[]},{"n":12,"t":"我要在你們中間行走；我要作你們的神，你們要作我的子民。","notes":[]},{"n":13,"t":"我是耶和華－你們的神，曾將你們從埃及地領出來，使你們不作埃及人的奴僕；我也折斷你們所負的軛，叫你們挺身而走。」","notes":[]},{"n":14,"t":"「你們若不聽從我，不遵行我的誡命，","notes":[],"heads":["違反誡命者受懲罰"]},{"n":15,"t":"厭棄我的律例，厭惡我的典章，不遵行我一切的誡命，背棄我的約，","notes":[]},{"n":16,"t":"我待你們就要這樣：我必命定驚惶，叫眼目乾癟、精神消耗的癆病熱病轄制你們。你們也要白白地撒種，因為仇敵要吃你們所種的。","notes":[]},{"n":17,"t":"我要向你們變臉，你們就要敗在仇敵面前。恨惡你們的，必轄管你們；無人追趕，你們卻要逃跑。","notes":[]},{"n":18,"t":"你們因這些事若還不聽從我，我就要為你們的罪加七倍懲罰你們。","notes":[]},{"n":19,"t":"我必斷絕你們因勢力而有的驕傲，又要使覆你們的天如鐵，載你們的地如銅。","notes":[]},{"n":20,"t":"你們要白白地勞力；因為你們的地不出土產，其上的樹木也不結果子。","notes":[]},{"n":21,"t":"「你們行事若與我反對，不肯聽從我，我就要按你們的罪加七倍降災與你們。","notes":[]},{"n":22,"t":"我也要打發野地的走獸到你們中間，搶吃你們的兒女，吞滅你們的牲畜，使你們的人數減少，道路荒涼。","notes":[]},{"n":23,"t":"「你們因這些事若仍不改正歸我，行事與我反對，","notes":[]},{"n":24,"t":"我就要行事與你們反對，因你們的罪擊打你們七次。","notes":[]},{"n":25,"t":"我又要使刀劍臨到你們，報復你們背約的仇；聚集你們在各城內，降瘟疫在你們中間，也必將你們交在仇敵的手中。","notes":[]},{"n":26,"t":"我要折斷你們的杖，就是斷絕你們的糧。那時，必有十個女人在一個爐子給你們烤餅，按分量秤給你們；你們要吃，也吃不飽。","notes":[]},{"n":27,"t":"「你們因這一切的事若不聽從我，卻行事與我反對，","notes":[]},{"n":28,"t":"我就要發烈怒，行事與你們反對，又因你們的罪懲罰你們七次。","notes":[]},{"n":29,"t":"並且你們要吃兒子的肉，也要吃女兒的肉。","notes":[]},{"n":30,"t":"我又要毀壞你們的邱壇，砍下你們的日像，把你們的屍首扔在你們偶像的身上；我的心也必厭惡你們。","notes":[]},{"n":31,"t":"我要使你們的城邑變為荒涼，使你們的眾聖所成為荒場；我也不聞你們馨香的香氣。","notes":[]},{"n":32,"t":"我要使地成為荒場，住在其上的仇敵就因此詫異。","notes":[]},{"n":33,"t":"我要把你們散在列邦中；我也要拔刀追趕你們。你們的地要成為荒場；你們的城邑要變為荒涼。","notes":[]},{"n":34,"t":"「你們在仇敵之地居住的時候，你們的地荒涼，要享受眾安息；正在那時候，地要歇息，享受安息。","notes":[]},{"n":35,"t":"地多時為荒場，就要多時歇息；地這樣歇息，是你們住在其上的安息年所不能得的。","notes":[]},{"n":36,"t":"至於你們剩下的人，我要使他們在仇敵之地心驚膽怯。葉子被風吹的響聲，要追趕他們；他們要逃避，像人逃避刀劍，無人追趕，卻要跌倒。","notes":[]},{"n":37,"t":"無人追趕，他們要彼此撞跌，像在刀劍之前。你們在仇敵面前也必站立不住。","notes":[]},{"n":38,"t":"你們要在列邦中滅亡；仇敵之地要吞吃你們。","notes":[]},{"n":39,"t":"你們剩下的人必因自己的罪孽和祖宗的罪孽在仇敵之地消滅。","notes":[]},{"n":40,"t":"「他們要承認自己的罪和他們祖宗的罪，就是干犯我的那罪，並且承認自己行事與我反對，","notes":[]},{"n":41,"t":"我所以行事與他們反對，把他們帶到仇敵之地。那時，他們未受割禮的心若謙卑了，他們也服了罪孽的刑罰，","notes":[]},{"n":42,"t":"我就要記念我與雅各所立的約，與以撒所立的約，與亞伯拉罕所立的約，並要記念這地。","notes":[]},{"n":43,"t":"他們離開這地，地在荒廢無人的時候就要享受安息。並且他們要服罪孽的刑罰；因為他們厭棄了我的典章，心中厭惡了我的律例。","notes":[]},{"n":44,"t":"雖是這樣，他們在仇敵之地，我卻不厭棄他們，也不厭惡他們，將他們盡行滅絕，也不背棄我與他們所立的約，因為我是耶和華－他們的神。","notes":[]},{"n":45,"t":"我卻要為他們的緣故記念我與他們先祖所立的約。他們的先祖是我在列邦人眼前、從埃及地領出來的，為要作他們的神。我是耶和華。」","notes":[]},{"n":46,"t":"這些律例、典章，和法度是耶和華與以色列人在西奈山藉著摩西立的。","notes":[]}]},"27":{"heading":"許願的條例","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你曉諭以色列人說：人還特許的願，被許的人要按你所估的價值歸給耶和華。","notes":[]},{"n":3,"t":"你估定的，從二十歲到六十歲的男人，要按聖所的平，估定價銀五十舍客勒。","notes":[]},{"n":4,"t":"若是女人，你要估定三十舍客勒。","notes":[]},{"n":5,"t":"若是從五歲到二十歲，男子你要估定二十舍客勒，女子估定十舍客勒。","notes":[]},{"n":6,"t":"若是從一月到五歲，男子你要估定五舍客勒，女子估定三舍客勒。","notes":[]},{"n":7,"t":"若是從六十歲以上，男人你要估定十五舍客勒，女人估定十舍客勒。","notes":[]},{"n":8,"t":"他若貧窮，不能照你所估定的價，就要把他帶到祭司面前，祭司要按許願人的力量估定他的價。","notes":[]},{"n":9,"t":"「所許的若是牲畜，就是人獻給耶和華為供物的，凡這一類獻給耶和華的，都要成為聖。","notes":[]},{"n":10,"t":"人不可改換，也不可更換，或是好的換壞的，或是壞的換好的。若以牲畜更換牲畜，所許的與所換的都要成為聖。","notes":[]},{"n":11,"t":"若牲畜不潔淨，是不可獻給耶和華為供物的，就要把牲畜安置在祭司面前。","notes":[]},{"n":12,"t":"祭司就要估定價值；牲畜是好是壞，祭司怎樣估定，就要以怎樣為是。","notes":[]},{"n":13,"t":"他若一定要贖回，就要在你所估定的價值以外加上五分之一。","notes":[]},{"n":14,"t":"「人將房屋分別為聖，歸給耶和華，祭司就要估定價值。房屋是好是壞，祭司怎樣估定，就要以怎樣為定。","notes":[]},{"n":15,"t":"將房屋分別為聖的人，若要贖回房屋，就必在你所估定的價值以外加上五分之一，房屋仍舊歸他。","notes":[]},{"n":16,"t":"「人若將承受為業的幾分地分別為聖，歸給耶和華，你要按這地撒種多少估定價值，若撒大麥一賀梅珥，要估價五十舍客勒。","notes":[]},{"n":17,"t":"他若從禧年將地分別為聖，就要以你所估定的價為定。","notes":[]},{"n":18,"t":"倘若他在禧年以後將地分別為聖，祭司就要按著未到禧年所剩的年數推算價值，也要從你所估的減去價值。","notes":[]},{"n":19,"t":"將地分別為聖的人若定要把地贖回，他便要在你所估的價值以外加上五分之一，地就准定歸他。","notes":[]},{"n":20,"t":"他若不贖回那地，或是將地賣給別人，就再不能贖了。","notes":[]},{"n":21,"t":"但到了禧年，那地從買主手下出來的時候，就要歸耶和華為聖，和永獻的地一樣，要歸祭司為業。","notes":[]},{"n":22,"t":"他若將所買的一塊地，不是承受為業的，分別為聖歸給耶和華，","notes":[]},{"n":23,"t":"祭司就要將你所估的價值給他推算到禧年。當日，他要以你所估的價銀為聖，歸給耶和華。","notes":[]},{"n":24,"t":"到了禧年，那地要歸賣主，就是那承受為業的原主。","notes":[]},{"n":25,"t":"凡你所估定的價銀都要按著聖所的平：二十季拉為一舍客勒。","notes":[]},{"n":26,"t":"「惟獨牲畜中頭生的，無論是牛是羊，既歸耶和華，誰也不可再分別為聖，因為這是耶和華的。","notes":[]},{"n":27,"t":"若是不潔淨的牲畜生的，就要按你所估定的價值加上五分之一贖回；若不贖回，就要按你所估定的價值賣了。","notes":[]},{"n":28,"t":"「但一切永獻的，就是人從他所有永獻給耶和華的，無論是人，是牲畜，是他承受為業的地，都不可賣，也不可贖。凡永獻的是歸給耶和華為至聖。","notes":[]},{"n":29,"t":"凡從人中當滅的都不可贖，必被治死。」","notes":[]},{"n":30,"t":"「地上所有的，無論是地上的種子是樹上的果子，十分之一是耶和華的，是歸給耶和華為聖的。","notes":[]},{"n":31,"t":"人若要贖這十分之一的甚麼物，就要加上五分之一。","notes":[]},{"n":32,"t":"凡牛群羊群中，一切從杖下經過的，每第十隻要歸給耶和華為聖。","notes":[]},{"n":33,"t":"不可問是好是壞，也不可更換；若定要更換，所更換的與本來的牲畜都要成為聖，不可贖回。」","notes":[]},{"n":34,"t":"這就是耶和華在西奈山為以色列人所吩咐摩西的命令。","notes":[]}]}},"NUM":{"1":{"heading":"以色列的第一次人口普查","verses":[{"n":1,"t":"以色列人出埃及地後，第二年二月初一日，耶和華在西奈的曠野、會幕中曉諭摩西說：","notes":[]},{"n":2,"t":"「你要按以色列全會眾的家室、宗族、人名的數目計算所有的男丁。","notes":[]},{"n":3,"t":"凡以色列中，從二十歲以外，能出去打仗的，你和亞倫要照他們的軍隊數點。","notes":[]},{"n":4,"t":"每支派中必有一人作本支派的族長，幫助你們。","notes":[]},{"n":5,"t":"他們的名字：屬呂便的，有示丟珥的兒子以利蓿；","notes":[]},{"n":6,"t":"屬西緬的，有蘇利沙代的兒子示路蔑；","notes":[]},{"n":7,"t":"屬猶大的，有亞米拿達的兒子拿順；","notes":[]},{"n":8,"t":"屬以薩迦的，有蘇押的兒子拿坦業；","notes":[]},{"n":9,"t":"屬西布倫的，有希倫的兒子以利押；","notes":[]},{"n":10,"t":"約瑟子孫、屬以法蓮的，有亞米忽的兒子以利沙瑪；屬瑪拿西的，有比大蓿的兒子迦瑪列；","notes":[]},{"n":11,"t":"屬便雅憫的，有基多尼的兒子亞比但；","notes":[]},{"n":12,"t":"屬但的，有亞米沙代的兒子亞希以謝；","notes":[]},{"n":13,"t":"屬亞設的，有俄蘭的兒子帕結；","notes":[]},{"n":14,"t":"屬迦得的，有丟珥的兒子以利雅薩；","notes":[]},{"n":15,"t":"屬拿弗他利的，有以南的兒子亞希拉。","notes":[]},{"n":16,"t":"這都是從會中選召的，各作本支派的首領，都是以色列軍中的統領。」","notes":[]},{"n":17,"t":"於是，摩西、亞倫帶著這些按名指定的人，","notes":[]},{"n":18,"t":"當二月初一日招聚全會眾。會眾就照他們的家室、宗族、人名的數目，從二十歲以外的，都述說自己的家譜。","notes":[]},{"n":19,"t":"耶和華怎樣吩咐摩西，他就怎樣在西奈的曠野數點他們。","notes":[]},{"n":20,"t":"以色列的長子，呂便子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的男丁，共有四萬六千五百名。","notes":[],"end":21},{"n":22,"t":"西緬子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的男丁，共有五萬九千三百名。","notes":[],"end":23},{"n":24,"t":"迦得子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的，共有四萬五千六百五十名。","notes":[],"end":25},{"n":26,"t":"猶大子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的，共有七萬四千六百名。","notes":[],"end":27},{"n":28,"t":"以薩迦子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的，共有五萬四千四百名。","notes":[],"end":29},{"n":30,"t":"西布倫子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的，共有五萬七千四百名。","notes":[],"end":31},{"n":32,"t":"約瑟子孫屬以法蓮子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的，共有四萬零五百名。","notes":[],"end":33},{"n":34,"t":"瑪拿西子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的，共有三萬二千二百名。","notes":[],"end":35},{"n":36,"t":"便雅憫子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的，共有三萬五千四百名。","notes":[],"end":37},{"n":38,"t":"但子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的，共有六萬二千七百名。","notes":[],"end":39},{"n":40,"t":"亞設子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的，共有四萬一千五百名。","notes":[],"end":41},{"n":42,"t":"拿弗他利子孫的後代，照著家室、宗族、人名的數目，從二十歲以外，凡能出去打仗、被數的，共有五萬三千四百名。","notes":[],"end":43},{"n":44,"t":"這些就是被數點的，是摩西、亞倫，和以色列中十二個首領所數點的；這十二個人各作各宗族的代表。","notes":[]},{"n":45,"t":"這樣，凡以色列人中被數的，照著宗族，從二十歲以外，能出去打仗、被數的，共有六十萬零三千五百五十名。","notes":[],"end":46},{"n":47,"t":"利未人卻沒有按著支派數在其中，","notes":[]},{"n":48,"t":"因為耶和華曉諭摩西說：","notes":[]},{"n":49,"t":"「惟獨利未支派你不可數點，也不可在以色列人中計算他們的總數。","notes":[]},{"n":50,"t":"只要派利未人管法櫃的帳幕和其中的器具，並屬乎帳幕的；他們要抬帳幕和其中的器具，並要辦理帳幕的事，在帳幕的四圍安營。","notes":["或譯：搬運"]},{"n":51,"t":"帳幕將往前行的時候，利未人要拆卸；將支搭的時候，利未人要豎起。近前來的外人必被治死。","notes":[]},{"n":52,"t":"以色列人支搭帳棚，要照他們的軍隊，各歸本營，各歸本纛。","notes":[]},{"n":53,"t":"但利未人要在法櫃帳幕的四圍安營，免得忿怒臨到以色列會眾；利未人並要謹守法櫃的帳幕。」","notes":[]},{"n":54,"t":"以色列人就這樣行。凡耶和華所吩咐摩西的，他們就照樣行了。","notes":[]}]},"2":{"heading":"各支派在營地的位置","verses":[{"n":1,"t":"耶和華曉諭摩西、亞倫說：","notes":[]},{"n":2,"t":"「以色列人要各歸自己的纛下，在本族的旗號那裏，對著會幕的四圍安營。","notes":[]},{"n":3,"t":"在東邊，向日出之地，照著軍隊安營的是猶大營的纛。有亞米拿達的兒子拿順作猶大人的首領。","notes":[]},{"n":4,"t":"他軍隊被數的，共有七萬四千六百名。","notes":[]},{"n":5,"t":"挨著他安營的是以薩迦支派。有蘇押的兒子拿坦業作以薩迦人的首領。","notes":[]},{"n":6,"t":"他軍隊被數的，共有五萬四千四百名。","notes":[]},{"n":7,"t":"又有西布倫支派。希倫的兒子以利押作西布倫人的首領。","notes":[]},{"n":8,"t":"他軍隊被數的，共有五萬七千四百名。","notes":[]},{"n":9,"t":"凡屬猶大營、按著軍隊被數的，共有十八萬六千四百名，要作第一隊往前行。","notes":[]},{"n":10,"t":"「在南邊，按著軍隊是呂便營的纛。有示丟珥的兒子以利蓿作呂便人的首領。","notes":[]},{"n":11,"t":"他軍隊被數的，共有四萬六千五百名。","notes":[]},{"n":12,"t":"挨著他安營的是西緬支派。蘇利沙代的兒子示路蔑作西緬人的首領。","notes":[]},{"n":13,"t":"他軍隊被數的，共有五萬九千三百名。","notes":[]},{"n":14,"t":"又有迦得支派。丟珥的兒子以利雅薩作迦得人的首領。","notes":[]},{"n":15,"t":"他軍隊被數的，共有四萬五千六百五十名，","notes":[]},{"n":16,"t":"凡屬呂便營、按著軍隊被數的，共有十五萬一千四百五十名，要作第二隊往前行。","notes":[]},{"n":17,"t":"「隨後，會幕要往前行，有利未營在諸營中間。他們怎樣安營就怎樣往前行，各按本位，各歸本纛。","notes":[]},{"n":18,"t":"「在西邊，按著軍隊是以法蓮營的纛。亞米忽的兒子以利沙瑪作以法蓮人的首領。","notes":[]},{"n":19,"t":"他軍隊被數的，共有四萬零五百名。","notes":[]},{"n":20,"t":"挨著他的是瑪拿西支派。比大蓿的兒子迦瑪列作瑪拿西人的首領。","notes":[]},{"n":21,"t":"他軍隊被數的，共有三萬二千二百名。","notes":[]},{"n":22,"t":"又有便雅憫支派。基多尼的兒子亞比但作便雅憫人的首領。","notes":[]},{"n":23,"t":"他軍隊被數的，共有三萬五千四百名。","notes":[]},{"n":24,"t":"凡屬以法蓮營、按著軍隊被數的，共有十萬零八千一百名，要作第三隊往前行。","notes":[]},{"n":25,"t":"「在北邊，按著軍隊是但營的纛。亞米沙代的兒子亞希以謝作但人的首領。","notes":[]},{"n":26,"t":"他軍隊被數的，共有六萬二千七百名。","notes":[]},{"n":27,"t":"挨著他安營的是亞設支派。俄蘭的兒子帕結作亞設人的首領。","notes":[]},{"n":28,"t":"他軍隊被數的，共有四萬一千五百名。","notes":[]},{"n":29,"t":"又有拿弗他利支派。以南的兒子亞希拉作拿弗他利人的首領。","notes":[]},{"n":30,"t":"他軍隊被數的，共有五萬三千四百名。","notes":[]},{"n":31,"t":"凡但營被數的，共有十五萬七千六百名，要歸本纛作末隊往前行。」","notes":[]},{"n":32,"t":"這些以色列人，照他們的宗族，按他們的軍隊，在諸營中被數的，共有六十萬零三千五百五十名。","notes":[]},{"n":33,"t":"惟獨利未人沒有數在以色列人中，是照耶和華所吩咐摩西的。","notes":[]},{"n":34,"t":"以色列人就這樣行，各人照他們的家室、宗族歸於本纛，安營起行，都是照耶和華所吩咐摩西的。","notes":[]}]},"3":{"heading":"亞倫的兒子們","verses":[{"n":1,"t":"耶和華在西奈山曉諭摩西的日子，亞倫和摩西的後代如下：","notes":[]},{"n":2,"t":"亞倫的兒子，長子名叫拿答，還有亞比戶、以利亞撒、以他瑪。","notes":[]},{"n":3,"t":"這是亞倫兒子的名字，都是受膏的祭司，是摩西叫他們承接聖職供祭司職分的。","notes":[]},{"n":4,"t":"拿答、亞比戶在西奈的曠野向耶和華獻凡火的時候就死在耶和華面前了。他們也沒有兒子。以利亞撒、以他瑪在他們的父親亞倫面前供祭司的職分。","notes":[]},{"n":5,"t":"耶和華曉諭摩西說：","notes":[],"heads":["利未人被派作祭司"]},{"n":6,"t":"「你使利未支派近前來，站在祭司亞倫面前好服事他，","notes":[]},{"n":7,"t":"替他和會眾在會幕前守所吩咐的，辦理帳幕的事。","notes":[]},{"n":8,"t":"又要看守會幕的器具，並守所吩咐以色列人的，辦理帳幕的事。","notes":[]},{"n":9,"t":"你要將利未人給亞倫和他的兒子，因為他們是從以色列人中選出來給他的。","notes":[]},{"n":10,"t":"你要囑咐亞倫和他的兒子謹守自己祭司的職任。近前來的外人必被治死。」","notes":[]},{"n":11,"t":"耶和華曉諭摩西說：","notes":[]},{"n":12,"t":"「我從以色列人中揀選了利未人，代替以色列人一切頭生的；利未人要歸我。","notes":[]},{"n":13,"t":"因為凡頭生的是我的；我在埃及地擊殺一切頭生的那日就把以色列中一切頭生的，連人帶牲畜都分別為聖歸我；他們定要屬我。我是耶和華。」","notes":[]},{"n":14,"t":"耶和華在西奈的曠野曉諭摩西說：","notes":[],"heads":["利未人男丁的統計"]},{"n":15,"t":"「你要照利未人的宗族、家室數點他們。凡一個月以外的男子都要數點。」","notes":[]},{"n":16,"t":"於是摩西照耶和華所吩咐的數點他們。","notes":[]},{"n":17,"t":"利未眾子的名字是革順、哥轄、米拉利。","notes":[]},{"n":18,"t":"革順的兒子，按著家室，是立尼、示每。","notes":[]},{"n":19,"t":"哥轄的兒子，按著家室，是暗蘭、以斯哈、希伯倫、烏薛。","notes":[]},{"n":20,"t":"米拉利的兒子，按著家室，是抹利、母示。這些按著宗族是利未人的家室。","notes":[]},{"n":21,"t":"屬革順的，有立尼族、示每族。這是革順的二族。","notes":[]},{"n":22,"t":"其中被數、從一個月以外所有的男子共有七千五百名。","notes":[]},{"n":23,"t":"這革順的二族要在帳幕後西邊安營。","notes":[]},{"n":24,"t":"拉伊勒的兒子以利雅薩作革順人宗族的首領。","notes":[]},{"n":25,"t":"革順的子孫在會幕中所要看守的，就是帳幕和罩棚，並罩棚的蓋與會幕的門簾，","notes":[]},{"n":26,"t":"院子的帷子和門簾（院子是圍帳幕和壇的），並一切使用的繩子。","notes":[]},{"n":27,"t":"屬哥轄的，有暗蘭族、以斯哈族、希伯倫族、烏薛族。這是哥轄的諸族。","notes":[]},{"n":28,"t":"按所有男子的數目，從一個月以外看守聖所的，共有八千六百名。","notes":[]},{"n":29,"t":"哥轄兒子的諸族要在帳幕的南邊安營。","notes":[]},{"n":30,"t":"烏薛的兒子以利撒反作哥轄宗族家室的首領。","notes":[]},{"n":31,"t":"他們所要看守的是約櫃、桌子、燈臺、兩座壇與聖所內使用的器皿，並簾子和一切使用之物。","notes":[]},{"n":32,"t":"祭司亞倫的兒子以利亞撒作利未人眾首領的領袖，要監察那些看守聖所的人。","notes":[]},{"n":33,"t":"屬米拉利的，有抹利族、母示族。這是米拉利的二族。","notes":[]},{"n":34,"t":"他們被數的，按所有男子的數目，從一個月以外的，共有六千二百名。","notes":[]},{"n":35,"t":"亞比亥的兒子蘇列作米拉利二宗族的首領。他們要在帳幕的北邊安營。","notes":[]},{"n":36,"t":"米拉利子孫的職分是看守帳幕的板、閂、柱子、帶卯的座，和帳幕一切所使用的器具，","notes":[]},{"n":37,"t":"院子四圍的柱子、帶卯的座、橛子，和繩子。","notes":[]},{"n":38,"t":"在帳幕前東邊，向日出之地安營的是摩西、亞倫，和亞倫的兒子。他們看守聖所，替以色列人守耶和華所吩咐的。近前來的外人必被治死。","notes":[]},{"n":39,"t":"凡被數的利未人，就是摩西、亞倫照耶和華吩咐所數的，按著家室，從一個月以外的男子，共有二萬二千名。","notes":[]},{"n":40,"t":"耶和華對摩西說：「你要從以色列人中數點一個月以外、凡頭生的男子，把他們的名字記下。","notes":[],"heads":["利未人代替長子的地位"]},{"n":41,"t":"我是耶和華。你要揀選利未人歸我，代替以色列人所有頭生的，也取利未人的牲畜代替以色列所有頭生的牲畜。」","notes":[]},{"n":42,"t":"摩西就照耶和華所吩咐的把以色列人頭生的都數點了。","notes":[]},{"n":43,"t":"按人名的數目，從一個月以外、凡頭生的男子，共有二萬二千二百七十三名。","notes":[]},{"n":44,"t":"耶和華曉諭摩西說：","notes":[]},{"n":45,"t":"「你揀選利未人代替以色列人所有頭生的，也取利未人的牲畜代替以色列人的牲畜。利未人要歸我；我是耶和華。","notes":[]},{"n":46,"t":"以色列人中頭生的男子比利未人多二百七十三個，必當將他們贖出來。","notes":[]},{"n":47,"t":"你要按人丁，照聖所的平，每人取贖銀五舍客勒（一舍客勒是二十季拉），","notes":[]},{"n":48,"t":"把那多餘之人的贖銀交給亞倫和他的兒子。」","notes":[]},{"n":49,"t":"於是摩西從那被利未人所贖以外的人取了贖銀。","notes":[]},{"n":50,"t":"從以色列人頭生的所取之銀，按聖所的平，有一千三百六十五舍客勒。","notes":[]},{"n":51,"t":"摩西照耶和華的話把這贖銀給亞倫和他的兒子，正如耶和華所吩咐的。","notes":[]}]},"4":{"heading":"哥轄子孫的職責","verses":[{"n":1,"t":"耶和華曉諭摩西、亞倫說：","notes":[]},{"n":2,"t":"「你從利未人中，將哥轄子孫的總數，照他們的家室、宗族，","notes":[]},{"n":3,"t":"從三十歲直到五十歲，凡前來任職、在會幕裏辦事的，全都計算。","notes":[]},{"n":4,"t":"哥轄子孫在會幕搬運至聖之物，所辦的事乃是這樣：","notes":[]},{"n":5,"t":"起營的時候，亞倫和他兒子要進去摘下遮掩櫃的幔子，用以蒙蓋法櫃，","notes":[]},{"n":6,"t":"又用海狗皮蓋在上頭，再蒙上純藍色的毯子，把槓穿上。","notes":[]},{"n":7,"t":"又用藍色毯子鋪在陳設餅的桌子上，將盤子、調羹、奠酒的爵，和杯擺在上頭。桌子上也必有常設的餅。","notes":[]},{"n":8,"t":"在其上又要蒙朱紅色的毯子，再蒙上海狗皮，把槓穿上。","notes":[]},{"n":9,"t":"要拿藍色毯子，把燈臺和燈臺上所用的燈盞、剪子、蠟花盤，並一切盛油的器皿，全都遮蓋。","notes":[]},{"n":10,"t":"又要把燈臺和燈臺的一切器具包在海狗皮裏，放在抬架上。","notes":[]},{"n":11,"t":"在金壇上要鋪藍色毯子，蒙上海狗皮，把槓穿上。","notes":[]},{"n":12,"t":"又要把聖所用的一切器具包在藍色毯子裏，用海狗皮蒙上，放在抬架上。","notes":[]},{"n":13,"t":"要收去壇上的灰，把紫色毯子鋪在壇上；","notes":[]},{"n":14,"t":"又要把所用的一切器具，就是火鼎、肉鍤子、鏟子、盤子，一切屬壇的器具都擺在壇上，又蒙上海狗皮，把槓穿上。","notes":[]},{"n":15,"t":"將要起營的時候，亞倫和他兒子把聖所和聖所的一切器具遮蓋完了，哥轄的子孫就要來抬，只是不可摸聖物，免得他們死亡。會幕裏這些物件是哥轄子孫所當抬的。","notes":[]},{"n":16,"t":"「祭司亞倫的兒子以利亞撒所要看守的是點燈的油與香料，並當獻的素祭和膏油，也要看守全帳幕與其中所有的，並聖所和聖所的器具。」","notes":[]},{"n":17,"t":"耶和華曉諭摩西、亞倫說：","notes":[]},{"n":18,"t":"「你們不可將哥轄人的支派從利未人中剪除。","notes":[]},{"n":19,"t":"他們挨近至聖物的時候，亞倫和他兒子要進去派他們各人所當辦的，所當抬的。這樣待他們，好使他們活著，不致死亡。","notes":[]},{"n":20,"t":"只是他們連片時不可進去觀看聖所，免得他們死亡。」","notes":[]},{"n":21,"t":"耶和華曉諭摩西說：","notes":[],"heads":["革順子孫的職責"]},{"n":22,"t":"「你要將革順子孫的總數，照著宗族、家室，","notes":[]},{"n":23,"t":"從三十歲直到五十歲，凡前來任職、在會幕裏辦事的，全都數點。","notes":[]},{"n":24,"t":"革順人各族所辦的事、所抬的物乃是這樣：","notes":[]},{"n":25,"t":"他們要抬帳幕的幔子和會幕，並會幕的蓋與其上的海狗皮，和會幕的門簾，","notes":[]},{"n":26,"t":"院子的帷子和門簾（院子是圍帳幕和壇的）、繩子，並所用的器具，不論是做甚麼用的，他們都要經理。","notes":[]},{"n":27,"t":"革順的子孫在一切抬物辦事之上都要憑亞倫和他兒子的吩咐；他們所當抬的，要派他們看守。","notes":[]},{"n":28,"t":"這是革順子孫的各族在會幕裏所辦的事；他們所看守的，必在祭司亞倫兒子以他瑪的手下。」","notes":[]},{"n":29,"t":"「至於米拉利的子孫，你要照著家室、宗族把他們數點。","notes":[],"heads":["米拉利子孫的職責"]},{"n":30,"t":"從三十歲直到五十歲，凡前來任職、在會幕裏辦事的，你都要數點。","notes":[]},{"n":31,"t":"他們辦理會幕的事，就是抬帳幕的板、閂、柱子，和帶卯的座，","notes":[]},{"n":32,"t":"院子四圍的柱子和其上帶卯的座、橛子、繩子，並一切使用的器具。他們所抬的器具，你們要按名指定。","notes":[]},{"n":33,"t":"這是米拉利子孫各族在會幕裏所辦的事，都在祭司亞倫兒子以他瑪的手下。」","notes":[]},{"n":34,"t":"摩西、亞倫與會眾的諸首領將哥轄的子孫，照著家室、宗族，","notes":[],"heads":["利未支派男丁的統計"]},{"n":35,"t":"從三十歲直到五十歲，凡前來任職、在會幕裏辦事的，都數點了。","notes":[]},{"n":36,"t":"被數的共有二千七百五十名。","notes":[]},{"n":37,"t":"這是哥轄各族中被數的，是在會幕裏辦事的，就是摩西、亞倫照耶和華藉摩西所吩咐數點的。","notes":[]},{"n":38,"t":"革順子孫被數的，照著家室、宗族，","notes":[]},{"n":39,"t":"從三十歲直到五十歲，凡前來任職、在會幕裏辦事的，共有二千六百三十名。","notes":[],"end":40},{"n":41,"t":"這是革順子孫各族中被數的，是在會幕裏辦事的，就是摩西、亞倫照耶和華藉摩西所吩咐數點的。","notes":[]},{"n":42,"t":"米拉利子孫中各族被數的，照著家室、宗族，","notes":[]},{"n":43,"t":"從三十歲直到五十歲，凡前來任職、在會幕裏辦事的，共有三千二百名。","notes":[],"end":44},{"n":45,"t":"這是米拉利子孫各族中被數的，就是摩西、亞倫照耶和華藉摩西所吩咐數點的。","notes":[]},{"n":46,"t":"凡被數的利未人，就是摩西、亞倫並以色列眾首領，照著家室、宗族所數點的，","notes":[]},{"n":47,"t":"從三十歲直到五十歲，凡前來任職、在會幕裏做抬物之工的，共有八千五百八十名。","notes":[],"end":48},{"n":49,"t":"摩西按他們所辦的事、所抬的物，憑耶和華的吩咐數點他們；他們這樣被摩西數點，正如耶和華所吩咐他的。","notes":[]}]},"5":{"heading":"不潔的人","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「你吩咐以色列人，使一切長大痲瘋的，患漏症的，並因死屍不潔淨的，都出營外去。","notes":[]},{"n":3,"t":"無論男女都要使他們出到營外，免得污穢他們的營；這營是我所住的。」","notes":[]},{"n":4,"t":"以色列人就這樣行，使他們出到營外。耶和華怎樣吩咐摩西，以色列人就怎樣行了。","notes":[]},{"n":5,"t":"耶和華對摩西說：","notes":[],"heads":["賠償虧負"]},{"n":6,"t":"「你曉諭以色列人說：無論男女，若犯了人所常犯的罪，以致干犯耶和華，那人就有了罪。","notes":[]},{"n":7,"t":"他要承認所犯的罪，將所虧負人的，如數賠還，另外加上五分之一，也歸與所虧負的人。","notes":[]},{"n":8,"t":"那人若沒有親屬可受所賠還的，那所賠還的就要歸與服事耶和華的祭司；至於那為他贖罪的公羊是在外。","notes":[]},{"n":9,"t":"以色列人一切的聖物中，所奉給祭司的舉祭都要歸與祭司。","notes":[]},{"n":10,"t":"各人所分別為聖的物，無論是甚麼，都要歸給祭司。」","notes":[]},{"n":11,"t":"耶和華對摩西說：","notes":[],"heads":["疑妻不貞的案件"]},{"n":12,"t":"「你曉諭以色列人說：人的妻若有邪行，得罪她丈夫，","notes":[]},{"n":13,"t":"有人與她行淫，事情嚴密，瞞過她丈夫，而且她被玷污，沒有作見證的人，當她行淫的時候也沒有被捉住，","notes":[]},{"n":14,"t":"她丈夫生了疑恨的心，疑恨她，她是被玷污，或是她丈夫生了疑恨的心，疑恨她，她並沒有被玷污，","notes":[]},{"n":15,"t":"這人就要將妻送到祭司那裏，又為她帶著大麥麵伊法十分之一作供物，不可澆上油，也不可加上乳香；因為這是疑恨的素祭，是思念的素祭，使人思念罪孽。","notes":[]},{"n":16,"t":"「祭司要使那婦人近前來，站在耶和華面前。","notes":[]},{"n":17,"t":"祭司要把聖水盛在瓦器裏，又從帳幕的地上取點塵土，放在水中。","notes":[]},{"n":18,"t":"祭司要叫那婦人蓬頭散髮，站在耶和華面前，把思念的素祭，就是疑恨的素祭，放在她手中。祭司手裏拿著致咒詛的苦水，","notes":[]},{"n":19,"t":"要叫婦人起誓，對她說：『若沒有人與你行淫，也未曾背著丈夫做污穢的事，你就免受這致咒詛苦水的災。","notes":[]},{"n":20,"t":"你若背著丈夫行了污穢的事，在你丈夫以外有人與你行淫，","notes":[]},{"n":21,"t":"（祭司叫婦人發咒起誓），願耶和華叫你大腿消瘦，肚腹發脹，使你在你民中被人咒詛，成了誓語；","notes":[]},{"n":22,"t":"並且這致咒詛的水入你的腸中，要叫你的肚腹發脹，大腿消瘦。』婦人要回答說：『阿們，阿們。』","notes":[]},{"n":23,"t":"「祭司要寫這咒詛的話，將所寫的字抹在苦水裏，","notes":[]},{"n":24,"t":"又叫婦人喝這致咒詛的苦水；這水要進入她裏面變苦了。","notes":[]},{"n":25,"t":"祭司要從婦人的手中取那疑恨的素祭，在耶和華面前搖一搖，拿到壇前；","notes":[]},{"n":26,"t":"又要從素祭中取出一把，作為這事的紀念，燒在壇上，然後叫婦人喝這水。","notes":[]},{"n":27,"t":"叫她喝了以後，她若被玷污，得罪了丈夫，這致咒詛的水必進入她裏面變苦了，她的肚腹就要發脹，大腿就要消瘦，那婦人便要在他民中被人咒詛。","notes":[]},{"n":28,"t":"若婦人沒有被玷污，卻是清潔的，就要免受這災，且要懷孕。","notes":[]},{"n":29,"t":"「妻子背著丈夫行了污穢的事，","notes":[]},{"n":30,"t":"或是人生了疑恨的心，疑恨他的妻，就有這疑恨的條例。那時他要叫婦人站在耶和華面前，祭司要在她身上照這條例而行。","notes":[]},{"n":31,"t":"男人就為無罪，婦人必擔當自己的罪孽。」","notes":[]}]},"6":{"heading":"拿細耳人的條例","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你曉諭以色列人說：無論男女許了特別的願，就是拿細耳人的願，要離俗歸耶和華。","notes":["拿細耳就是歸主的意思；下同"]},{"n":3,"t":"他就要遠離清酒濃酒，也不可喝甚麼清酒濃酒做的醋；不可喝甚麼葡萄汁，也不可吃鮮葡萄和乾葡萄。","notes":[]},{"n":4,"t":"在一切離俗的日子，凡葡萄樹上結的，自核至皮所做的物，都不可吃。","notes":[]},{"n":5,"t":"「在他一切許願離俗的日子，不可用剃頭刀剃頭，要由髮綹長長了。他要聖潔，直到離俗歸耶和華的日子滿了。","notes":[]},{"n":6,"t":"在他離俗歸耶和華的一切日子，不可挨近死屍。","notes":[]},{"n":7,"t":"他的父母或是弟兄姊妹死了的時候，他不可因他們使自己不潔淨，因為那離俗歸神的憑據是在他頭上。","notes":[]},{"n":8,"t":"在他一切離俗的日子是歸耶和華為聖。","notes":[]},{"n":9,"t":"「若在他旁邊忽然有人死了，以致沾染了他離俗的頭，他要在第七日，得潔淨的時候，剃頭。","notes":[]},{"n":10,"t":"第八日，他要把兩隻斑鳩或兩隻雛鴿帶到會幕門口，交給祭司。","notes":[]},{"n":11,"t":"祭司要獻一隻作贖罪祭，一隻作燔祭，為他贖那因死屍而有的罪，並要當日使他的頭成為聖潔。","notes":[]},{"n":12,"t":"他要另選離俗歸耶和華的日子，又要牽一隻一歲的公羊羔來作贖愆祭；但先前的日子要歸徒然，因為他在離俗之間被玷污了。","notes":[]},{"n":13,"t":"「拿細耳人滿了離俗的日子乃有這條例：人要領他到會幕門口，","notes":[]},{"n":14,"t":"他要將供物奉給耶和華，就是一隻沒有殘疾、一歲的公羊羔作燔祭，一隻沒有殘疾、一歲的母羊羔作贖罪祭，和一隻沒有殘疾的公綿羊作平安祭，","notes":[]},{"n":15,"t":"並一筐子無酵調油的細麵餅，與抹油的無酵薄餅，並同獻的素祭和奠祭。","notes":[]},{"n":16,"t":"祭司要在耶和華面前獻那人的贖罪祭和燔祭；","notes":[]},{"n":17,"t":"也要把那隻公羊和那筐無酵餅獻給耶和華作平安祭，又要將同獻的素祭和奠祭獻上。","notes":[]},{"n":18,"t":"拿細耳人要在會幕門口剃離俗的頭，把離俗頭上的髮放在平安祭下的火上。","notes":[]},{"n":19,"t":"他剃了以後，祭司就要取那已煮的公羊一條前腿，又從筐子裏取一個無酵餅和一個無酵薄餅，都放在他手上。","notes":[]},{"n":20,"t":"祭司要拿這些作為搖祭，在耶和華面前搖一搖；這與所搖的胸、所舉的腿同為聖物，歸給祭司。然後拿細耳人可以喝酒。","notes":[]},{"n":21,"t":"「許願的拿細耳人為離俗所獻的供物，和他以外所能得的獻給耶和華，就有這條例。他怎樣許願就當照離俗的條例行。」","notes":[]},{"n":22,"t":"耶和華曉諭摩西說：","notes":[],"heads":["祭司的祝福"]},{"n":23,"t":"「你告訴亞倫和他兒子說：你們要這樣為以色列人祝福，說：","notes":[]},{"n":24,"t":"『願耶和華賜福給你，保護你。","notes":[]},{"n":25,"t":"願耶和華使他的臉光照你，賜恩給你。","notes":[]},{"n":26,"t":"願耶和華向你仰臉，賜你平安。』","notes":[]},{"n":27,"t":"他們要如此奉我的名為以色列人祝福；我也要賜福給他們。」","notes":[]}]},"7":{"heading":"各族長奉獻祭物","verses":[{"n":1,"t":"摩西立完了帳幕，就把帳幕用膏抹了，使它成聖，又把其中的器具和壇，並壇上的器具，都抹了，使它成聖。","notes":[]},{"n":2,"t":"當天，以色列的眾首領，就是各族的族長，都來奉獻。他們是各支派的首領，管理那些被數的人。","notes":[]},{"n":3,"t":"他們把自己的供物送到耶和華面前，就是六輛篷子車和十二隻公牛。每兩個首領奉獻一輛車，每首領奉獻一隻牛。他們把這些都奉到帳幕前。","notes":[]},{"n":4,"t":"耶和華曉諭摩西說：","notes":[]},{"n":5,"t":"「你要收下這些，好作會幕的使用，都要照利未人所辦的事交給他們。」","notes":[]},{"n":6,"t":"於是摩西收了車和牛，交給利未人，","notes":[]},{"n":7,"t":"把兩輛車，四隻牛，照革順子孫所辦的事交給他們，","notes":[]},{"n":8,"t":"又把四輛車，八隻牛，照米拉利子孫所辦的事交給他們；他們都在祭司亞倫的兒子以他瑪手下。","notes":[]},{"n":9,"t":"但車與牛都沒有交給哥轄子孫；因為他們辦的是聖所的事，在肩頭上抬聖物。","notes":[]},{"n":10,"t":"用膏抹壇的日子，首領都來行奉獻壇的禮，眾首領就在壇前獻供物。","notes":[]},{"n":11,"t":"耶和華對摩西說：「眾首領為行奉獻壇的禮，要每天一個首領來獻供物。」","notes":[]},{"n":12,"t":"頭一日獻供物的是猶大支派的亞米拿達的兒子拿順。","notes":[]},{"n":13,"t":"他的供物是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":14,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":15,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":16,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":17,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是亞米拿達兒子拿順的供物。","notes":[]},{"n":18,"t":"第二日來獻的是以薩迦子孫的首領、蘇押的兒子拿坦業。","notes":[]},{"n":19,"t":"他獻為供物的是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":20,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":21,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":22,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":23,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是蘇押兒子拿坦業的供物。","notes":[]},{"n":24,"t":"第三日來獻的是西布倫子孫的首領、希倫的兒子以利押。","notes":[]},{"n":25,"t":"他的供物是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":26,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":27,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":28,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":29,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是希倫兒子以利押的供物。","notes":[]},{"n":30,"t":"第四日來獻的是呂便子孫的首領、示丟珥的兒子以利蓿。","notes":[]},{"n":31,"t":"他的供物是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":32,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":33,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":34,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":35,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是示丟珥的兒子以利蓿的供物。","notes":[]},{"n":36,"t":"第五日來獻的是西緬子孫的首領、蘇利沙代的兒子示路蔑。","notes":[]},{"n":37,"t":"他的供物是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":38,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":39,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":40,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":41,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是蘇利沙代兒子示路蔑的供物。","notes":[]},{"n":42,"t":"第六日來獻的是迦得子孫的首領、丟珥的兒子以利雅薩。","notes":[]},{"n":43,"t":"他的供物是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":44,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":45,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":46,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":47,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是丟珥的兒子以利雅薩的供物。","notes":[]},{"n":48,"t":"第七日來獻的是以法蓮子孫的首領、亞米忽的兒子以利沙瑪。","notes":[]},{"n":49,"t":"他的供物是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":50,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":51,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":52,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":53,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是亞米忽兒子以利沙瑪的供物。","notes":[]},{"n":54,"t":"第八日來獻的是瑪拿西子孫的首領、比大蓿的兒子迦瑪列。","notes":[]},{"n":55,"t":"他的供物是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":56,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":57,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":58,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":59,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是比大蓿兒子迦瑪列的供物。","notes":[]},{"n":60,"t":"第九日來獻的是便雅憫子孫的首領、基多尼的兒子亞比但。","notes":[]},{"n":61,"t":"他的供物是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":62,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":63,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":64,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":65,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是基多尼兒子亞比但的供物。","notes":[]},{"n":66,"t":"第十日來獻的是但子孫的首領、亞米沙代的兒子亞希以謝。","notes":[]},{"n":67,"t":"他的供物是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":68,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":69,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":70,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":71,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是亞米沙代兒子亞希以謝的供物。","notes":[]},{"n":72,"t":"第十一日來獻的是亞設子孫的首領、俄蘭的兒子帕結。","notes":[]},{"n":73,"t":"他的供物是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":74,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":75,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":76,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":77,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是俄蘭兒子帕結的供物。","notes":[]},{"n":78,"t":"第十二日來獻的是拿弗他利子孫的首領、以南兒子亞希拉。","notes":[]},{"n":79,"t":"他的供物是：一個銀盤子，重一百三十舍客勒，一個銀碗，重七十舍客勒，都是按聖所的平，也都盛滿了調油的細麵作素祭；","notes":[]},{"n":80,"t":"一個金盂，重十舍客勒，盛滿了香；","notes":[]},{"n":81,"t":"一隻公牛犢，一隻公綿羊，一隻一歲的公羊羔作燔祭；","notes":[]},{"n":82,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":83,"t":"兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是以南兒子亞希拉的供物。","notes":[]},{"n":84,"t":"用膏抹壇的日子，以色列的眾首領為行獻壇之禮所獻的是：銀盤子十二個，銀碗十二個，金盂十二個；","notes":[]},{"n":85,"t":"每盤子重一百三十舍客勒，每碗重七十舍客勒。一切器皿的銀子，按聖所的平，共有二千四百舍客勒。","notes":[]},{"n":86,"t":"十二個金盂盛滿了香，按聖所的平，每盂重十舍客勒，所有的金子共一百二十舍客勒。","notes":[]},{"n":87,"t":"作燔祭的，共有公牛十二隻，公羊十二隻，一歲的公羊羔十二隻，並同獻的素祭作贖罪祭的公山羊十二隻；","notes":[]},{"n":88,"t":"作平安祭的，共有公牛二十四隻，公綿羊六十隻，公山羊六十隻，一歲的公羊羔六十隻。這就是用膏抹壇之後，為行奉獻壇之禮所獻的。","notes":[]},{"n":89,"t":"摩西進會幕要與耶和華說話的時候，聽見法櫃的施恩座以上、二基路伯中間有與他說話的聲音，就是耶和華與他說話。","notes":[]}]},"8":{"heading":"安置七盞燈","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「你告訴亞倫說：點燈的時候，七盞燈都要向燈臺前面發光。」","notes":[]},{"n":3,"t":"亞倫便這樣行。他點燈臺上的燈，使燈向前發光，是照耶和華所吩咐摩西的。","notes":[]},{"n":4,"t":"這燈臺的做法是用金子錘出來的，連座帶花都是錘出來的。摩西製造燈臺，是照耶和華所指示的樣式。","notes":[]},{"n":5,"t":"耶和華曉諭摩西說：","notes":[],"heads":["為利未人行潔淨與奉獻禮"]},{"n":6,"t":"「你從以色列人中選出利未人來，潔淨他們。","notes":[]},{"n":7,"t":"潔淨他們當這樣行：用除罪水彈在他們身上，又叫他們用剃頭刀刮全身，洗衣服，潔淨自己。","notes":[]},{"n":8,"t":"然後叫他們取一隻公牛犢，並同獻的素祭，就是調油的細麵；你要另取一隻公牛犢作贖罪祭。","notes":[]},{"n":9,"t":"將利未人奉到會幕前，招聚以色列全會眾。","notes":[]},{"n":10,"t":"將利未人奉到耶和華面前，以色列人要按手在他們頭上。","notes":[]},{"n":11,"t":"亞倫也將他們奉到耶和華面前，為以色列人當作搖祭，使他們好辦耶和華的事。","notes":[]},{"n":12,"t":"利未人要按手在那兩隻牛的頭上；你要將一隻作贖罪祭，一隻作燔祭，獻給耶和華，為利未人贖罪。","notes":[]},{"n":13,"t":"你也要使利未人站在亞倫和他兒子面前，將他們當作搖祭奉給耶和華。","notes":[]},{"n":14,"t":"「這樣，你從以色列人中將利未人分別出來，利未人便要歸我。","notes":[]},{"n":15,"t":"此後利未人要進去辦會幕的事，你要潔淨他們，將他們當作搖祭奉上；","notes":[]},{"n":16,"t":"因為他們是從以色列人中全然給我的，我揀選他們歸我，是代替以色列人中一切頭生的。","notes":[]},{"n":17,"t":"以色列人中一切頭生的，連人帶牲畜，都是我的。我在埃及地擊殺一切頭生的那天，將他們分別為聖歸我。","notes":[]},{"n":18,"t":"我揀選利未人代替以色列人中一切頭生的。","notes":[]},{"n":19,"t":"我從以色列人中將利未人當作賞賜給亞倫和他的兒子，在會幕中辦以色列人的事，又為以色列人贖罪，免得他們挨近聖所，有災殃臨到他們中間。」","notes":[]},{"n":20,"t":"摩西、亞倫，並以色列全會眾便向利未人如此行。凡耶和華指著利未人所吩咐摩西的，以色列人就向他們這樣行。","notes":[]},{"n":21,"t":"於是利未人潔淨自己，除了罪，洗了衣服；亞倫將他們當作搖祭奉到耶和華面前，又為他們贖罪，潔淨他們。","notes":[]},{"n":22,"t":"然後利未人進去，在亞倫和他兒子面前，在會幕中辦事。耶和華指著利未人怎樣吩咐摩西，以色列人就怎樣向他們行了。","notes":[]},{"n":23,"t":"耶和華曉諭摩西說：","notes":[]},{"n":24,"t":"「利未人是這樣：從二十五歲以外，他們要前來任職，辦會幕的事。","notes":[]},{"n":25,"t":"到了五十歲要停工退任，不再辦事，","notes":[]},{"n":26,"t":"只要在會幕裏，和他們的弟兄一同伺候，謹守所吩咐的，不再辦事了。至於所吩咐利未人的，你要這樣向他們行。」","notes":[]}]},"9":{"heading":"第二個逾越節","verses":[{"n":1,"t":"以色列人出埃及地以後，第二年正月，耶和華在西奈的曠野吩咐摩西說：","notes":[]},{"n":2,"t":"「以色列人應當在所定的日期守逾越節，","notes":[]},{"n":3,"t":"就是本月十四日黃昏的時候，你們要在所定的日期守這節，要按這節的律例典章而守。」","notes":[]},{"n":4,"t":"於是摩西吩咐以色列人守逾越節。","notes":[]},{"n":5,"t":"他們就在西奈的曠野，正月十四日黃昏的時候，守逾越節。凡耶和華所吩咐摩西的，以色列人都照樣行了。","notes":[]},{"n":6,"t":"有幾個人因死屍而不潔淨，不能在那日守逾越節。當日他們到摩西、亞倫面前，","notes":[]},{"n":7,"t":"說：「我們雖因死屍而不潔淨，為何被阻止、不得同以色列人在所定的日期獻耶和華的供物呢？」","notes":[]},{"n":8,"t":"摩西對他們說：「你們暫且等候，我可以去聽耶和華指著你們是怎樣吩咐的。」","notes":[]},{"n":9,"t":"耶和華對摩西說：","notes":[]},{"n":10,"t":"「你曉諭以色列人說：你們和你們後代中，若有人因死屍而不潔淨，或在遠方行路，還要向耶和華守逾越節。","notes":[]},{"n":11,"t":"他們要在二月十四日黃昏的時候，守逾越節。要用無酵餅與苦菜，和逾越節的羊羔同吃。","notes":[]},{"n":12,"t":"一點不可留到早晨；羊羔的骨頭一根也不可折斷。他們要照逾越節的一切律例而守。","notes":[]},{"n":13,"t":"那潔淨而不行路的人若推辭不守逾越節，那人要從民中剪除；因為他在所定的日期不獻耶和華的供物，應該擔當他的罪。","notes":[]},{"n":14,"t":"若有外人寄居在你們中間，願意向耶和華守逾越節，他要照逾越節的律例典章行，不管是寄居的是本地人，同歸一例。」","notes":[]},{"n":15,"t":"立起帳幕的那日，有雲彩遮蓋帳幕，就是法櫃的帳幕；從晚上到早晨，雲彩在其上，形狀如火。","notes":[],"heads":["雲彩遮蓋帳幕"]},{"n":16,"t":"常是這樣，雲彩遮蓋帳幕，夜間形狀如火。","notes":[]},{"n":17,"t":"雲彩幾時從帳幕收上去，以色列人就幾時起行；雲彩在哪裏停住，以色列人就在那裏安營。","notes":[]},{"n":18,"t":"以色列人遵耶和華的吩咐起行，也遵耶和華的吩咐安營。雲彩在帳幕上停住幾時，他們就住營幾時。","notes":[]},{"n":19,"t":"雲彩在帳幕上停留許多日子，以色列人就守耶和華所吩咐的不起行。","notes":[]},{"n":20,"t":"有時雲彩在帳幕上幾天，他們就照耶和華的吩咐住營，也照耶和華的吩咐起行。","notes":[]},{"n":21,"t":"有時從晚上到早晨，有這雲彩在帳幕上；早晨雲彩收上去，他們就起行。有時晝夜雲彩停在帳幕上，收上去的時候，他們就起行。","notes":[]},{"n":22,"t":"雲彩停留在帳幕上，無論是兩天，是一月，是一年，以色列人就住營不起行；但雲彩收上去，他們就起行。","notes":[]},{"n":23,"t":"他們遵耶和華的吩咐安營，也遵耶和華的吩咐起行。他們守耶和華所吩咐的，都是憑耶和華吩咐摩西的。","notes":[]}]},"10":{"heading":"製銀號","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「你要用銀子做兩枝號，都要錘出來的，用以招聚會眾，並叫眾營起行。","notes":[]},{"n":3,"t":"吹這號的時候，全會眾要到你那裏，聚集在會幕門口。","notes":[]},{"n":4,"t":"若單吹一枝，眾首領，就是以色列軍中的統領，要聚集到你那裏。","notes":[]},{"n":5,"t":"吹出大聲的時候，東邊安的營都要起行。","notes":[]},{"n":6,"t":"二次吹出大聲的時候，南邊安的營都要起行。他們將起行，必吹出大聲。","notes":[]},{"n":7,"t":"但招聚會眾的時候，你們要吹號，卻不要吹出大聲。","notes":[]},{"n":8,"t":"亞倫子孫作祭司的要吹這號；這要作你們世世代代永遠的定例。","notes":[]},{"n":9,"t":"你們在自己的地，與欺壓你們的敵人打仗，就要用號吹出大聲，便在耶和華－你們的神面前得蒙紀念，也蒙拯救脫離仇敵。","notes":[]},{"n":10,"t":"在你們快樂的日子和節期，並月朔，獻燔祭和平安祭，也要吹號，這都要在你們的神面前作為紀念。我是耶和華－你們的神。」","notes":[]},{"n":11,"t":"第二年二月二十日，雲彩從法櫃的帳幕收上去。","notes":[],"heads":["離開西奈山"]},{"n":12,"t":"以色列人就按站往前行，離開西奈的曠野，雲彩停住在巴蘭的曠野。","notes":[]},{"n":13,"t":"這是他們照耶和華藉摩西所吩咐的，初次往前行。","notes":[]},{"n":14,"t":"按著軍隊首先往前行的是猶大營的纛。統領軍隊的是亞米拿達的兒子拿順。","notes":[]},{"n":15,"t":"統領以薩迦支派軍隊的是蘇押的兒子拿坦業。","notes":[]},{"n":16,"t":"統領西布倫支派軍隊的是希倫的兒子以利押。","notes":[]},{"n":17,"t":"帳幕拆卸，革順的子孫和米拉利的子孫就抬著帳幕先往前行。","notes":[]},{"n":18,"t":"按著軍隊往前行的是呂便營的纛。統領軍隊的是示丟珥的兒子以利蓿。","notes":[]},{"n":19,"t":"統領西緬支派軍隊的是蘇利沙代的兒子示路蔑。","notes":[]},{"n":20,"t":"統領迦得支派軍隊的是丟珥的兒子以利雅薩。","notes":[]},{"n":21,"t":"哥轄人抬著聖物先往前行。他們未到以前，抬帳幕的已經把帳幕支好。","notes":[]},{"n":22,"t":"按著軍隊往前行的是以法蓮營的纛，統領軍隊的是亞米忽的兒子以利沙瑪。","notes":[]},{"n":23,"t":"統領瑪拿西支派軍隊的是比大蓿的兒子迦瑪列。","notes":[]},{"n":24,"t":"統領便雅憫支派軍隊的是基多尼的兒子亞比但。","notes":[]},{"n":25,"t":"在諸營末後的是但營的纛，按著軍隊往前行。統領軍隊的是亞米沙代的兒子亞希以謝。","notes":[]},{"n":26,"t":"統領亞設支派軍隊的是俄蘭的兒子帕結。","notes":[]},{"n":27,"t":"統領拿弗他利支派軍隊的是以南的兒子亞希拉。","notes":[]},{"n":28,"t":"以色列人按著軍隊往前行，就是這樣。","notes":[]},{"n":29,"t":"摩西對他岳父－米甸人流珥的兒子何巴－說：「我們要行路，往耶和華所應許之地去；他曾說：『我要將這地賜給你們。』現在求你和我們同去，我們必厚待你，因為耶和華指著以色列人已經應許給好處。」","notes":["或譯：內兄"]},{"n":30,"t":"何巴回答說：「我不去；我要回本地本族那裏去。」","notes":[]},{"n":31,"t":"摩西說：「求你不要離開我們；因為你知道我們要在曠野安營，你可以當作我們的眼目。","notes":[]},{"n":32,"t":"你若和我們同去，將來耶和華有甚麼好處待我們，我們也必以甚麼好處待你。」","notes":[]},{"n":33,"t":"以色列人離開耶和華的山，往前行了三天的路程；耶和華的約櫃在前頭行了三天的路程，為他們尋找安歇的地方。","notes":[],"heads":["眾民和約櫃往前行"]},{"n":34,"t":"他們拔營往前行，日間有耶和華的雲彩在他們以上。","notes":[]},{"n":35,"t":"約櫃往前行的時候，摩西就說：「耶和華啊，求你興起！願你的仇敵四散！願恨你的人從你面前逃跑！」","notes":[]},{"n":36,"t":"約櫃停住的時候，他就說：「耶和華啊，求你回到以色列的千萬人中！」","notes":[]}]},"11":{"heading":"在他備拉發怨言","verses":[{"n":1,"t":"眾百姓發怨言，他們的惡語達到耶和華的耳中。耶和華聽見了就怒氣發作，使火在他們中間焚燒，直燒到營的邊界。","notes":[]},{"n":2,"t":"百姓向摩西哀求，摩西祈求耶和華，火就熄了。","notes":[]},{"n":3,"t":"那地方便叫做他備拉，因為耶和華的火燒在他們中間。","notes":[]},{"n":4,"t":"他們中間的閒雜人大起貪慾的心；以色列人又哭號說：「誰給我們肉吃呢？","notes":[],"heads":["摩西選立七十個長老"]},{"n":5,"t":"我們記得，在埃及的時候不花錢就吃魚，也記得有黃瓜、西瓜、韭菜、葱、蒜。","notes":[]},{"n":6,"t":"現在我們的心血枯竭了，除這嗎哪以外，在我們眼前並沒有別的東西。」","notes":[]},{"n":7,"t":"這嗎哪彷彿芫荽子，又好像珍珠。","notes":[]},{"n":8,"t":"百姓周圍行走，把嗎哪收起來，或用磨推，或用臼搗，煮在鍋中，又做成餅，滋味好像新油。","notes":[]},{"n":9,"t":"夜間露水降在營中，嗎哪也隨著降下。）","notes":[]},{"n":10,"t":"摩西聽見百姓各在各家的帳棚門口哭號。耶和華的怒氣便大發作，摩西就不喜悅。","notes":[]},{"n":11,"t":"摩西對耶和華說：「你為何苦待僕人？我為何不在你眼前蒙恩，竟把這管理百姓的重任加在我身上呢？","notes":[]},{"n":12,"t":"這百姓豈是我懷的胎，豈是我生下來的呢？你竟對我說：『把他們抱在懷裏，如養育之父抱吃奶的孩子，直抱到你起誓應許給他們祖宗的地去。』","notes":[]},{"n":13,"t":"我從哪裏得肉給這百姓吃呢？他們都向我哭號說：『你給我們肉吃吧！』","notes":[]},{"n":14,"t":"管理這百姓的責任太重了，我獨自擔當不起。","notes":[]},{"n":15,"t":"你這樣待我，我若在你眼前蒙恩，求你立時將我殺了，不叫我見自己的苦情。」","notes":[]},{"n":16,"t":"耶和華對摩西說：「你從以色列的長老中招聚七十個人，就是你所知道作百姓的長老和官長的，到我這裏來，領他們到會幕前，使他們和你一同站立。","notes":[]},{"n":17,"t":"我要在那裏降臨，與你說話，也要把降於你身上的靈分賜他們，他們就和你同當這管百姓的重任，免得你獨自擔當。","notes":[]},{"n":18,"t":"又要對百姓說：『你們應當自潔，預備明天吃肉，因為你們哭號說：誰給我們肉吃！我們在埃及很好。這聲音達到了耶和華的耳中，所以他必給你們肉吃。","notes":[]},{"n":19,"t":"你們不止吃一天、兩天、五天、十天、二十天，","notes":[]},{"n":20,"t":"要吃一個整月，甚至肉從你們鼻孔裏噴出來，使你們厭惡了，因為你們厭棄住在你們中間的耶和華，在他面前哭號說：我們為何出了埃及呢！』」","notes":[]},{"n":21,"t":"摩西對耶和華說：「這與我同住的百姓、步行的男人有六十萬，你還說：『我要把肉給他們，使他們可以吃一個整月。』","notes":[]},{"n":22,"t":"難道給他們宰了羊群牛群，或是把海中所有的魚都聚了來，就夠他們吃嗎？」","notes":[]},{"n":23,"t":"耶和華對摩西說：「耶和華的膀臂豈是縮短了嗎？現在要看我的話向你應驗不應驗。」","notes":[]},{"n":24,"t":"摩西出去，將耶和華的話告訴百姓，又招聚百姓的長老中七十個人來，使他們站在會幕的四圍。","notes":[]},{"n":25,"t":"耶和華在雲中降臨，對摩西說話，把降與他身上的靈分賜那七十個長老。靈停在他們身上的時候，他們就受感說話，以後卻沒有再說。","notes":[]},{"n":26,"t":"但有兩個人仍在營裏，一個名叫伊利達，一個名叫米達。他們本是在那些被錄的人中，卻沒有到會幕那裏去。靈停在他們身上，他們就在營裏說預言。","notes":[]},{"n":27,"t":"有個少年人跑來告訴摩西說：「伊利達、米達在營裏說預言。」","notes":[]},{"n":28,"t":"摩西的幫手，嫩的兒子約書亞，就是摩西所揀選的一個人，說：「請我主摩西禁止他們。」","notes":[]},{"n":29,"t":"摩西對他說：「你為我的緣故嫉妒人嗎？惟願耶和華的百姓都受感說話！願耶和華把他的靈降在他們身上！」","notes":[]},{"n":30,"t":"於是，摩西和以色列的長老都回到營裏去。","notes":[]},{"n":31,"t":"有風從耶和華那裏颳起，把鵪鶉由海面颳來，飛散在營邊和營的四圍；這邊約有一天的路程，那邊約有一天的路程，離地面約有二肘。","notes":[],"heads":["神賜鵪鶉為食物"]},{"n":32,"t":"百姓起來，終日終夜，並次日一整天，捕取鵪鶉；至少的也取了十賀梅珥，為自己擺列在營的四圍。","notes":[]},{"n":33,"t":"肉在他們牙齒之間尚未嚼爛，耶和華的怒氣就向他們發作，用最重的災殃擊殺了他們。","notes":[]},{"n":34,"t":"那地方便叫做基博羅‧哈他瓦，因為他們在那裏葬埋那起貪慾之心的人。","notes":["就是貪慾之人的墳墓"]},{"n":35,"t":"百姓從基博羅‧哈他瓦走到哈洗錄，就住在哈洗錄。","notes":[]}]},"12":{"heading":"米利暗受罰","verses":[{"n":1,"t":"摩西娶了古實女子為妻。米利暗和亞倫因他所娶的古實女子就毀謗他，說：","notes":[]},{"n":2,"t":"「難道耶和華單與摩西說話，不也與我們說話嗎？」這話耶和華聽見了。（","notes":[]},{"n":3,"t":"摩西為人極其謙和，勝過世上的眾人。）","notes":[]},{"n":4,"t":"耶和華忽然對摩西、亞倫、米利暗說：「你們三個人都出來，到會幕這裏。」他們三個人就出來了。","notes":[]},{"n":5,"t":"耶和華在雲柱中降臨，站在會幕門口，召亞倫和米利暗，二人就出來了。","notes":[]},{"n":6,"t":"耶和華說：「你們且聽我的話：你們中間若有先知，我－耶和華必在異象中向他顯現，在夢中與他說話。","notes":[]},{"n":7,"t":"我的僕人摩西不是這樣；他是在我全家盡忠的。","notes":[]},{"n":8,"t":"我要與他面對面說話，乃是明說，不用謎語，並且他必見我的形像。你們毀謗我的僕人摩西，為何不懼怕呢？」","notes":[]},{"n":9,"t":"耶和華就向他們二人發怒而去。","notes":[]},{"n":10,"t":"雲彩從會幕上挪開了，不料，米利暗長了大痲瘋，有雪那樣白。亞倫一看米利暗長了大痲瘋，","notes":[]},{"n":11,"t":"就對摩西說：「我主啊，求你不要因我們愚昧犯罪，便將這罪加在我們身上。","notes":[]},{"n":12,"t":"求你不要使她像那出母腹、肉已半爛的死胎。」","notes":[]},{"n":13,"t":"於是摩西哀求耶和華說：「神啊，求你醫治她！」","notes":[]},{"n":14,"t":"耶和華對摩西說：「她父親若吐唾沫在她臉上，她豈不蒙羞七天嗎？現在要把她在營外關鎖七天，然後才可以領她進來。」","notes":[]},{"n":15,"t":"於是米利暗關鎖在營外七天。百姓沒有行路，直等到把米利暗領進來。","notes":[]},{"n":16,"t":"以後百姓從哈洗錄起行，在巴蘭的曠野安營。","notes":[]}]},"13":{"heading":"十二個探子","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「你打發人去窺探我所賜給以色列人的迦南地，他們每支派中要打發一個人，都要作首領的。」","notes":[]},{"n":3,"t":"摩西就照耶和華的吩咐從巴蘭的曠野打發他們去；他們都是以色列人的族長。","notes":[]},{"n":4,"t":"他們的名字：屬呂便支派的有撒刻的兒子沙母亞。","notes":[]},{"n":5,"t":"屬西緬支派的有何利的兒子沙法。","notes":[]},{"n":6,"t":"屬猶大支派的有耶孚尼的兒子迦勒。","notes":[]},{"n":7,"t":"屬以薩迦支派的有約色的兒子以迦。","notes":[]},{"n":8,"t":"屬以法蓮支派的有嫩的兒子何希阿。","notes":[]},{"n":9,"t":"屬便雅憫支派的有拉孚的兒子帕提。","notes":[]},{"n":10,"t":"屬西布倫支派的有梭底的兒子迦疊。","notes":[]},{"n":11,"t":"約瑟的子孫，屬瑪拿西支派的有穌西的兒子迦底。","notes":[]},{"n":12,"t":"屬但支派的有基瑪利的兒子亞米利。","notes":[]},{"n":13,"t":"屬亞設支派的有米迦勒的兒子西帖。","notes":[]},{"n":14,"t":"屬拿弗他利支派的有縛西的兒子拿比。","notes":[]},{"n":15,"t":"屬迦得支派的有瑪基的兒子臼利。","notes":[]},{"n":16,"t":"這就是摩西所打發、窺探那地之人的名字。摩西就稱嫩的兒子何希阿為約書亞。","notes":[]},{"n":17,"t":"摩西打發他們去窺探迦南地，說：「你們從南地上山地去，","notes":[]},{"n":18,"t":"看那地如何，其中所住的民是強是弱，是多是少，","notes":[]},{"n":19,"t":"所住之地是好是歹，所住之處是營盤是堅城。","notes":[]},{"n":20,"t":"又看那地土是肥美是瘠薄，其中有樹木沒有。你們要放開膽量，把那地的果子帶些來。」（那時正是葡萄初熟的時候。）","notes":[]},{"n":21,"t":"他們上去窺探那地，從尋的曠野到利合，直到哈馬口。","notes":[]},{"n":22,"t":"他們從南地上去，到了希伯崙；在那裏有亞衲族人亞希幔、示篩、撻買。（原來希伯崙城被建造比埃及的鎖安城早七年。）","notes":[]},{"n":23,"t":"他們到了以實各谷，從那裏砍了葡萄樹的一枝，上頭有一掛葡萄，兩個人用槓抬著，又帶了些石榴和無花果來。（","notes":[]},{"n":24,"t":"因為以色列人從那裏砍來的那掛葡萄，所以那地方叫做以實各谷。）","notes":[]},{"n":25,"t":"過了四十天，他們窺探那地才回來，","notes":[]},{"n":26,"t":"到了巴蘭曠野的加低斯，見摩西、亞倫，並以色列的全會眾，回報摩西、亞倫，並全會眾，又把那地的果子給他們看；","notes":[]},{"n":27,"t":"又告訴摩西說：「我們到了你所打發我們去的那地，果然是流奶與蜜之地；這就是那地的果子。","notes":[]},{"n":28,"t":"然而住那地的民強壯，城邑也堅固寬大，並且我們在那裏看見了亞衲族的人。","notes":[]},{"n":29,"t":"亞瑪力人住在南地；赫人、耶布斯人、亞摩利人住在山地；迦南人住在海邊並約旦河旁。」","notes":[]},{"n":30,"t":"迦勒在摩西面前安撫百姓，說：「我們立刻上去得那地吧！我們足能得勝。」","notes":[]},{"n":31,"t":"但那些和他同去的人說：「我們不能上去攻擊那民，因為他們比我們強壯。」","notes":[]},{"n":32,"t":"探子中有人論到所窺探之地，向以色列人報惡信，說：「我們所窺探、經過之地是吞吃居民之地，我們在那裏所看見的人民都身量高大。","notes":[]},{"n":33,"t":"我們在那裏看見亞衲族人，就是偉人；他們是偉人的後裔。據我們看，自己就如蚱蜢一樣；據他們看，我們也是如此。」","notes":[]}]},"14":{"heading":"民眾埋怨","verses":[{"n":1,"t":"當下，全會眾大聲喧嚷；那夜百姓都哭號。","notes":[]},{"n":2,"t":"以色列眾人向摩西、亞倫發怨言；全會眾對他們說：「巴不得我們早死在埃及地，或是死在這曠野。","notes":[]},{"n":3,"t":"耶和華為甚麼把我們領到那地，使我們倒在刀下呢？我們的妻子和孩子必被擄掠。我們回埃及去豈不好嗎？」","notes":[]},{"n":4,"t":"眾人彼此說：「我們不如立一個首領回埃及去吧！」","notes":[]},{"n":5,"t":"摩西、亞倫就俯伏在以色列全會眾面前。","notes":[]},{"n":6,"t":"窺探地的人中，嫩的兒子約書亞和耶孚尼的兒子迦勒撕裂衣服，","notes":[]},{"n":7,"t":"對以色列全會眾說：「我們所窺探、經過之地是極美之地。","notes":[]},{"n":8,"t":"耶和華若喜悅我們，就必將我們領進那地，把地賜給我們；那地原是流奶與蜜之地。","notes":[]},{"n":9,"t":"但你們不可背叛耶和華，也不要怕那地的居民；因為他們是我們的食物，並且蔭庇他們的已經離開他們。有耶和華與我們同在，不要怕他們！」","notes":[]},{"n":10,"t":"但全會眾說：「拿石頭打死他們二人。」忽然，耶和華的榮光在會幕中向以色列眾人顯現。","notes":[]},{"n":11,"t":"耶和華對摩西說：「這百姓藐視我要到幾時呢？我在他們中間行了這一切神蹟，他們還不信我要到幾時呢？","notes":[],"heads":["摩西為民眾禱告"]},{"n":12,"t":"我要用瘟疫擊殺他們，使他們不得承受那地，叫你的後裔成為大國，比他們強勝。」","notes":[]},{"n":13,"t":"摩西對耶和華說：「埃及人必聽見這事；因為你曾施展大能，將這百姓從他們中間領上來。","notes":[]},{"n":14,"t":"埃及人要將這事傳給迦南地的居民；那民已經聽見你－耶和華是在這百姓中間；因為你面對面被人看見，有你的雲彩停在他們以上。你日間在雲柱中，夜間在火柱中，在他們前面行。","notes":[]},{"n":15,"t":"如今你若把這百姓殺了，如殺一人，那些聽見你名聲的列邦必議論說：","notes":[]},{"n":16,"t":"『耶和華因為不能把這百姓領進他向他們起誓應許之地，所以在曠野把他們殺了。』","notes":[]},{"n":17,"t":"現在求主大顯能力，照你所說過的話說：","notes":[]},{"n":18,"t":"『耶和華不輕易發怒，並有豐盛的慈愛，赦免罪孽和過犯；萬不以有罪的為無罪，必追討他的罪，自父及子，直到三、四代。』","notes":[]},{"n":19,"t":"求你照你的大慈愛赦免這百姓的罪孽，好像你從埃及到如今常赦免他們一樣。」","notes":[]},{"n":20,"t":"耶和華說：「我照著你的話赦免了他們。","notes":[]},{"n":21,"t":"然我指著我的永生起誓，遍地要被我的榮耀充滿。","notes":[]},{"n":22,"t":"這些人雖看見我的榮耀和我在埃及與曠野所行的神蹟，仍然試探我這十次，不聽從我的話，","notes":[]},{"n":23,"t":"他們斷不得看見我向他們的祖宗所起誓應許之地。凡藐視我的，一個也不得看見；","notes":[]},{"n":24,"t":"惟獨我的僕人迦勒，因他另有一個心志，專一跟從我，我就把他領進他所去過的那地；他的後裔也必得那地為業。","notes":[]},{"n":25,"t":"亞瑪力人和迦南人住在谷中，明天你們要轉回，從紅海的路往曠野去。」","notes":[]},{"n":26,"t":"耶和華對摩西、亞倫說：","notes":[],"heads":["耶和華懲罰埋怨的民眾"]},{"n":27,"t":"「這惡會眾向我發怨言，我忍耐他們要到幾時呢？以色列人向我所發的怨言，我都聽見了。","notes":[]},{"n":28,"t":"你們告訴他們，耶和華說：『我指著我的永生起誓，我必要照你們達到我耳中的話待你們。","notes":[]},{"n":29,"t":"你們的屍首必倒在這曠野，並且你們中間凡被數點、從二十歲以外、向我發怨言的，","notes":[]},{"n":30,"t":"必不得進我起誓應許叫你們住的那地；惟有耶孚尼的兒子迦勒和嫩的兒子約書亞才能進去。","notes":[]},{"n":31,"t":"但你們的婦人孩子，就是你們所說、要被擄掠的，我必把他們領進去，他們就得知你們所厭棄的那地。","notes":[]},{"n":32,"t":"至於你們，你們的屍首必倒在這曠野；","notes":[]},{"n":33,"t":"你們的兒女必在曠野飄流四十年，擔當你們淫行的罪，直到你們的屍首在曠野消滅。","notes":[]},{"n":34,"t":"按你們窺探那地的四十日，一年頂一日，你們要擔當罪孽四十年，就知道我與你們疏遠了，","notes":[]},{"n":35,"t":"我－耶和華說過，我總要這樣待這一切聚集敵我的惡會眾；他們必在這曠野消滅，在這裏死亡。』」","notes":[]},{"n":36,"t":"摩西所打發、窺探那地的人回來，報那地的惡信，叫全會眾向摩西發怨言，","notes":[]},{"n":37,"t":"這些報惡信的人都遭瘟疫，死在耶和華面前。","notes":[]},{"n":38,"t":"其中惟有嫩的兒子約書亞和耶孚尼的兒子迦勒仍然存活。","notes":[]},{"n":39,"t":"摩西將這些話告訴以色列眾人，他們就甚悲哀。","notes":[],"heads":["首次進攻迦南"]},{"n":40,"t":"清早起來，上山頂去，說：「我們在這裏，我們有罪了；情願上耶和華所應許的地方去。」","notes":[]},{"n":41,"t":"摩西說：「你們為何違背耶和華的命令呢？這事不能順利了。","notes":[]},{"n":42,"t":"不要上去；因為耶和華不在你們中間，恐怕你們被仇敵殺敗了。","notes":[]},{"n":43,"t":"亞瑪力人和迦南人都在你們面前，你們必倒在刀下；因你們退回不跟從耶和華，所以他必不與你們同在。」","notes":[]},{"n":44,"t":"他們卻擅敢上山頂去，然而耶和華的約櫃和摩西沒有出營。","notes":[]},{"n":45,"t":"於是亞瑪力人和住在那山上的迦南人都下來擊打他們，把他們殺退了，直到何珥瑪。","notes":[]}]},"15":{"heading":"獻祭的條例","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你曉諭以色列人說：你們到了我所賜給你們居住的地，","notes":[]},{"n":3,"t":"若願意從牛群羊群中取牛羊作火祭，獻給耶和華，無論是燔祭是平安祭，為要還特許的願，或是作甘心祭，或是逢你們節期獻的，都要奉給耶和華為馨香之祭。","notes":[]},{"n":4,"t":"那獻供物的就要將細麵伊法十分之一，並油一欣四分之一，調和作素祭，獻給耶和華。","notes":[]},{"n":5,"t":"無論是燔祭是平安祭，你要為每隻綿羊羔，一同預備奠祭的酒一欣四分之一。","notes":[]},{"n":6,"t":"為公綿羊預備細麵伊法十分之二，並油一欣三分之一，調和作素祭，","notes":[]},{"n":7,"t":"又用酒一欣三分之一作奠祭，獻給耶和華為馨香之祭。","notes":[]},{"n":8,"t":"你預備公牛作燔祭，或是作平安祭，為要還特許的願，或是作平安祭，獻給耶和華，","notes":[]},{"n":9,"t":"就要把細麵伊法十分之三，並油半欣，調和作素祭，和公牛一同獻上，","notes":[]},{"n":10,"t":"又用酒半欣作奠祭，獻給耶和華為馨香的火祭。","notes":[]},{"n":11,"t":"「獻公牛、公綿羊、綿羊羔、山羊羔，每隻都要這樣辦理。","notes":[]},{"n":12,"t":"照你們所預備的數目，按著隻數都要這樣辦理。","notes":[]},{"n":13,"t":"凡本地人將馨香的火祭獻給耶和華，都要這樣辦理。","notes":[]},{"n":14,"t":"若有外人和你們同居，或有人世世代代住在你們中間，願意將馨香的火祭獻給耶和華，你們怎樣辦理，他也要照樣辦理。","notes":[]},{"n":15,"t":"至於會眾，你們和同居的外人都歸一例，作為你們世世代代永遠的定例，在耶和華面前，你們怎樣，寄居的也要怎樣。","notes":[]},{"n":16,"t":"你們並與你們同居的外人當有一樣的條例，一樣的典章。」","notes":[]},{"n":17,"t":"耶和華對摩西說：","notes":[]},{"n":18,"t":"「你曉諭以色列人說：你們到了我所領你們進去的那地，","notes":[]},{"n":19,"t":"吃那地的糧食，就要把舉祭獻給耶和華。","notes":[]},{"n":20,"t":"你們要用初熟的麥子磨麵，做餅當舉祭奉獻；你們舉上，好像舉禾場的舉祭一樣。","notes":[]},{"n":21,"t":"你們世世代代要用初熟的麥子磨麵，當舉祭獻給耶和華。","notes":[]},{"n":22,"t":"「你們有錯誤的時候，不守耶和華所曉諭摩西的這一切命令，","notes":[]},{"n":23,"t":"就是耶和華藉摩西一切所吩咐你們的，自那日以至你們的世世代代，","notes":[]},{"n":24,"t":"若有誤行，是會眾所不知道的，後來全會眾就要將一隻公牛犢作燔祭，並照典章把素祭和奠祭一同獻給耶和華為馨香之祭，又獻一隻公山羊作贖罪祭。","notes":[]},{"n":25,"t":"祭司要為以色列全會眾贖罪，他們就必蒙赦免，因為這是錯誤。他們又因自己的錯誤，把供物，就是向耶和華獻的火祭和贖罪祭，一並奉到耶和華面前。","notes":[]},{"n":26,"t":"以色列全會眾和寄居在他們中間的外人就必蒙赦免，因為這罪是百姓誤犯的。","notes":[]},{"n":27,"t":"「若有一個人誤犯了罪，他就要獻一歲的母山羊作贖罪祭。","notes":[]},{"n":28,"t":"那誤行的人犯罪的時候，祭司要在耶和華面前為他贖罪，他就必蒙赦免。","notes":[]},{"n":29,"t":"以色列中的本地人和寄居在他們中間的外人，若誤行了甚麼事，必歸一樣的條例。","notes":[]},{"n":30,"t":"但那擅敢行事的，無論是本地人是寄居的，他褻瀆了耶和華，必從民中剪除。","notes":[]},{"n":31,"t":"因他藐視耶和華的言語，違背耶和華的命令，那人總要剪除；他的罪孽要歸到他身上。」","notes":[]},{"n":32,"t":"以色列人在曠野的時候，遇見一個人在安息日撿柴。","notes":[],"heads":["違反安息日的人"]},{"n":33,"t":"遇見他撿柴的人，就把他帶到摩西、亞倫並全會眾那裏，","notes":[]},{"n":34,"t":"將他收在監內；因為當怎樣辦他，還沒有指明。","notes":[]},{"n":35,"t":"耶和華吩咐摩西說：「總要把那人治死；全會眾要在營外用石頭把他打死。」","notes":[]},{"n":36,"t":"於是全會眾將他帶到營外，用石頭打死他，是照耶和華所吩咐摩西的。","notes":[]},{"n":37,"t":"耶和華曉諭摩西說：","notes":[],"heads":["有關衣服繸子的條例"]},{"n":38,"t":"「你吩咐以色列人，叫他們世世代代在衣服邊上做繸子，又在底邊的繸子上釘一根藍細帶子。","notes":[]},{"n":39,"t":"你們佩帶這繸子，好叫你們看見就記念遵行耶和華一切的命令，不隨從自己的心意、眼目行邪淫，像你們素常一樣；","notes":[]},{"n":40,"t":"使你們記念遵行我一切的命令，成為聖潔，歸與你們的神。","notes":[]},{"n":41,"t":"「我是耶和華－你們的神，曾把你們從埃及地領出來，要作你們的神。我是耶和華－你們的神。」","notes":[]}]},"16":{"heading":"可拉、大坍、亞比蘭的叛變","verses":[{"n":1,"t":"利未的曾孫、哥轄的孫子、以斯哈的兒子可拉，和呂便子孫中以利押的兒子大坍、亞比蘭，與比勒的兒子安，","notes":[]},{"n":2,"t":"並以色列會中的二百五十個首領，就是有名望選入會中的人，在摩西面前一同起來，","notes":[]},{"n":3,"t":"聚集攻擊摩西、亞倫，說：「你們擅自專權！全會眾個個既是聖潔，耶和華也在他們中間，你們為甚麼自高，超過耶和華的會眾呢？」","notes":[]},{"n":4,"t":"摩西聽見這話就俯伏在地，","notes":[]},{"n":5,"t":"對可拉和他一黨的人說：「到了早晨，耶和華必指示誰是屬他的，誰是聖潔的，就叫誰親近他；他所揀選的是誰，必叫誰親近他。","notes":[]},{"n":6,"t":"可拉啊，你們要這樣行，你和你的一黨要拿香爐來。","notes":[]},{"n":7,"t":"明日，在耶和華面前，把火盛在爐中，把香放在其上。耶和華揀選誰，誰就為聖潔。你們這利未的子孫擅自專權了！」","notes":[]},{"n":8,"t":"摩西又對可拉說：「利未的子孫哪，你們聽我說！","notes":[]},{"n":9,"t":"以色列的神從以色列會中將你們分別出來，使你們親近他，辦耶和華帳幕的事，並站在會眾面前替他們當差。","notes":[]},{"n":10,"t":"耶和華又使你和你一切弟兄－利未的子孫－一同親近他，這豈為小事？你們還要求祭司的職任嗎？","notes":[]},{"n":11,"t":"你和你一黨的人聚集是要攻擊耶和華。亞倫算甚麼，你們竟向他發怨言呢？」","notes":[]},{"n":12,"t":"摩西打發人去召以利押的兒子大坍、亞比蘭。他們說：「我們不上去！","notes":[]},{"n":13,"t":"你將我們從流奶與蜜之地領上來，要在曠野殺我們，這豈為小事？你還要自立為王轄管我們嗎？","notes":[]},{"n":14,"t":"並且你沒有將我們領到流奶與蜜之地，也沒有把田地和葡萄園給我們為業。難道你要剜這些人的眼睛嗎？我們不上去！」","notes":[]},{"n":15,"t":"摩西就甚發怒，對耶和華說：「求你不要享受他們的供物。我並沒有奪過他們一匹驢，也沒有害過他們一個人。」","notes":[]},{"n":16,"t":"摩西對可拉說：「明天，你和你一黨的人，並亞倫，都要站在耶和華面前；","notes":[]},{"n":17,"t":"各人要拿一個香爐，共二百五十個，把香放在上面，到耶和華面前。你和亞倫也各拿自己的香爐。」","notes":[]},{"n":18,"t":"於是他們各人拿一個香爐，盛上火，加上香，同摩西、亞倫站在會幕門前。","notes":[]},{"n":19,"t":"可拉招聚全會眾到會幕門前，要攻擊摩西、亞倫；耶和華的榮光就向全會眾顯現。","notes":[]},{"n":20,"t":"耶和華曉諭摩西、亞倫說：","notes":[]},{"n":21,"t":"「你們離開這會眾，我好在轉眼之間把他們滅絕。」","notes":[]},{"n":22,"t":"摩西、亞倫就俯伏在地，說：「神，萬人之靈的神啊，一人犯罪，你就要向全會眾發怒嗎？」","notes":[]},{"n":23,"t":"耶和華曉諭摩西說：","notes":[]},{"n":24,"t":"「你吩咐會眾說：『你們離開可拉、大坍、亞比蘭帳棚的四圍。』」","notes":[]},{"n":25,"t":"摩西起來，往大坍、亞比蘭那裏去；以色列的長老也隨著他去。","notes":[]},{"n":26,"t":"他吩咐會眾說：「你們離開這惡人的帳棚吧，他們的物件，甚麼都不可摸，恐怕你們陷在他們的罪中，與他們一同消滅。」","notes":[]},{"n":27,"t":"於是眾人離開可拉、大坍、亞比蘭帳棚的四圍。大坍、亞比蘭帶著妻子、兒女、小孩子，都出來，站在自己的帳棚門口。","notes":[]},{"n":28,"t":"摩西說：「我行的這一切事本不是憑我自己心意行的，乃是耶和華打發我行的，必有證據使你們知道。","notes":[]},{"n":29,"t":"這些人死若與世人無異，或是他們所遭的與世人相同，就不是耶和華打發我來的。","notes":[]},{"n":30,"t":"倘若耶和華創作一件新事，使地開口，把他們和一切屬他們的都吞下去，叫他們活活地墜落陰間，你們就明白這些人是藐視耶和華了。」","notes":[]},{"n":31,"t":"摩西剛說完了這一切話，他們腳下的地就開了口，","notes":[]},{"n":32,"t":"把他們和他們的家眷，並一切屬可拉的人丁、財物，都吞下去。","notes":[]},{"n":33,"t":"這樣，他們和一切屬他們的，都活活地墜落陰間；地口在他們上頭照舊合閉，他們就從會中滅亡。","notes":[]},{"n":34,"t":"在他們四圍的以色列眾人聽他們呼號，就都逃跑，說：「恐怕地也把我們吞下去。」","notes":[]},{"n":35,"t":"又有火從耶和華那裏出來，燒滅了那獻香的二百五十個人。","notes":[]},{"n":36,"t":"耶和華曉諭摩西說：","notes":[],"heads":["香爐"]},{"n":37,"t":"「你吩咐祭司亞倫的兒子以利亞撒從火中撿起那些香爐來，把火撒在別處，因為那些香爐是聖的。","notes":[]},{"n":38,"t":"把那些犯罪、自害己命之人的香爐，叫人錘成片子，用以包壇。那些香爐本是他們在耶和華面前獻過的，所以是聖的，並且可以給以色列人作記號。」","notes":[]},{"n":39,"t":"於是祭司以利亞撒將被燒之人所獻的銅香爐拿來，人就錘出來，用以包壇，","notes":[]},{"n":40,"t":"給以色列人作紀念，使亞倫後裔之外的人不得近前來在耶和華面前燒香，免得他遭可拉和他一黨所遭的。這乃是照耶和華藉著摩西所吩咐的。","notes":[]},{"n":41,"t":"第二天，以色列全會眾都向摩西、亞倫發怨言說：「你們殺了耶和華的百姓了。」","notes":[],"heads":["亞倫救了人民"]},{"n":42,"t":"會眾聚集攻擊摩西、亞倫的時候，向會幕觀看，不料，有雲彩遮蓋了，耶和華的榮光顯現。","notes":[]},{"n":43,"t":"摩西、亞倫就來到會幕前。","notes":[]},{"n":44,"t":"耶和華吩咐摩西說：","notes":[]},{"n":45,"t":"「你們離開這會眾，我好在轉眼之間把他們滅絕。」他們二人就俯伏於地。","notes":[]},{"n":46,"t":"摩西對亞倫說：「拿你的香爐，把壇上的火盛在其中，又加上香，快快帶到會眾那裏，為他們贖罪；因為有忿怒從耶和華那裏出來，瘟疫已經發作了。」","notes":[]},{"n":47,"t":"亞倫照著摩西所說的拿來，跑到會中，不料，瘟疫在百姓中已經發作了。他就加上香，為百姓贖罪。","notes":[]},{"n":48,"t":"他站在活人死人中間，瘟疫就止住了。","notes":[]},{"n":49,"t":"除了因可拉事情死的以外，遭瘟疫死的，共有一萬四千七百人。","notes":[]},{"n":50,"t":"亞倫回到會幕門口，到摩西那裏，瘟疫已經止住了。","notes":[]}]},"17":{"heading":"亞倫的杖","verses":[{"n":1,"t":"耶和華對摩西說：","notes":[]},{"n":2,"t":"「你曉諭以色列人，從他們手下取杖，每支派一根；從他們所有的首領，按著支派，共取十二根。你要將各人的名字寫在各人的杖上，","notes":[]},{"n":3,"t":"並要將亞倫的名字寫在利未的杖上，因為各族長必有一根杖。","notes":[]},{"n":4,"t":"你要把這些杖存在會幕內法櫃前，就是我與你們相會之處。","notes":[]},{"n":5,"t":"後來我所揀選的那人，他的杖必發芽。這樣，我必使以色列人向你們所發的怨言止息，不再達到我耳中。」","notes":[]},{"n":6,"t":"於是摩西曉諭以色列人，他們的首領就把杖交給他，按著支派，每首領一根，共有十二根；亞倫的杖也在其中。","notes":[]},{"n":7,"t":"摩西就把杖存在法櫃的帳幕內，在耶和華面前。","notes":[]},{"n":8,"t":"第二天，摩西進法櫃的帳幕去。誰知利未族亞倫的杖已經發了芽，生了花苞，開了花，結了熟杏。","notes":[]},{"n":9,"t":"摩西就把所有的杖從耶和華面前拿出來，給以色列眾人看；他們看見了，各首領就把自己的杖拿去。","notes":[]},{"n":10,"t":"耶和華吩咐摩西說：「把亞倫的杖還放在法櫃前，給這些背叛之子留作記號。這樣，你就使他們向我發的怨言止息，免得他們死亡。」","notes":[]},{"n":11,"t":"摩西就這樣行。耶和華怎樣吩咐他，他就怎樣行了。","notes":[]},{"n":12,"t":"以色列人對摩西說：「我們死啦！我們滅亡啦！都滅亡啦！","notes":[]},{"n":13,"t":"凡挨近耶和華帳幕的是必死的。我們都要死亡嗎？」","notes":[]}]},"18":{"heading":"祭司和利未人的職責","verses":[{"n":1,"t":"耶和華對亞倫說：「你和你的兒子，並你本族的人，要一同擔當干犯聖所的罪孽。你和你的兒子也要一同擔當干犯祭司職任的罪孽。","notes":[]},{"n":2,"t":"你要帶你弟兄利未人，就是你祖宗支派的人前來，使他們與你聯合，服事你，只是你和你的兒子，要一同在法櫃的帳幕前供職。","notes":[]},{"n":3,"t":"他們要守所吩咐你的，並守全帳幕，只是不可挨近聖所的器具和壇，免得他們和你們都死亡。","notes":[]},{"n":4,"t":"他們要與你聯合，也要看守會幕，辦理帳幕一切的事，只是外人不可挨近你們。","notes":[]},{"n":5,"t":"你們要看守聖所和壇，免得忿怒再臨到以色列人。","notes":[]},{"n":6,"t":"我已將你們的弟兄利未人從以色列人中揀選出來歸耶和華，是給你們為賞賜的，為要辦理會幕的事。","notes":[]},{"n":7,"t":"你和你的兒子要為一切屬壇和幔子內的事一同守祭司的職任。你們要這樣供職；我將祭司的職任給你們當作賞賜事奉我。凡挨近的外人必被治死。」","notes":[]},{"n":8,"t":"耶和華曉諭亞倫說：「我已將歸我的舉祭，就是以色列人一切分別為聖的物，交給你經管；因你受過膏，把這些都賜給你和你的子孫，當作永得的分。","notes":[],"heads":["祭司當得之物"]},{"n":9,"t":"以色列人歸給我至聖的供物，就是一切的素祭、贖罪祭、贖愆祭，其中所有存留不經火的，都為至聖之物，要歸給你和你的子孫。","notes":[]},{"n":10,"t":"你要拿這些當至聖物吃；凡男丁都可以吃。你當以此物為聖。","notes":[]},{"n":11,"t":"以色列人所獻的舉祭並搖祭都是你的；我已賜給你和你的兒女，當作永得的分；凡在你家中的潔淨人都可以吃。","notes":[]},{"n":12,"t":"凡油中、新酒中、五穀中至好的，就是以色列人所獻給耶和華初熟之物，我都賜給你。","notes":[]},{"n":13,"t":"凡從他們地上所帶來給耶和華初熟之物也都要歸與你。你家中的潔淨人都可以吃。","notes":[]},{"n":14,"t":"以色列中一切永獻的都必歸與你。","notes":[]},{"n":15,"t":"他們所有奉給耶和華的，連人帶牲畜，凡頭生的，都要歸給你；只是人頭生的，總要贖出來；不潔淨牲畜頭生的，也要贖出來。","notes":[]},{"n":16,"t":"其中在一月之外所當贖的，要照你所估定的價，按聖所的平，用銀子五舍客勒贖出來（一舍客勒是二十季拉）。","notes":[]},{"n":17,"t":"只是頭生的牛，或是頭生的綿羊和山羊，必不可贖，都是聖的，要把牠的血灑在壇上，把牠的脂油焚燒，當作馨香的火祭獻給耶和華。","notes":[]},{"n":18,"t":"牠的肉必歸你，像被搖的胸、被舉的右腿歸你一樣。","notes":[]},{"n":19,"t":"凡以色列人所獻給耶和華聖物中的舉祭，我都賜給你和你的兒女，當作永得的分。這是給你和你的後裔、在耶和華面前作為永遠的鹽約。」","notes":["鹽就是不廢壞的意思"]},{"n":20,"t":"耶和華對亞倫說：「你在以色列人的境內不可有產業，在他們中間也不可有分。我就是你的分，是你的產業。」","notes":[]},{"n":21,"t":"「凡以色列中出產的十分之一，我已賜給利未的子孫為業；因他們所辦的是會幕的事，所以賜給他們為酬他們的勞。","notes":[],"heads":["利未人的分"]},{"n":22,"t":"從今以後，以色列人不可挨近會幕，免得他們擔罪而死。","notes":[]},{"n":23,"t":"惟獨利未人要辦會幕的事，擔當罪孽；這要作你們世世代代永遠的定例。他們在以色列人中不可有產業；","notes":[]},{"n":24,"t":"因為以色列人中出產的十分之一，就是獻給耶和華為舉祭的，我已賜給利未人為業。所以我對他們說：『在以色列人中不可有產業。』」","notes":[]},{"n":25,"t":"耶和華吩咐摩西說：","notes":[],"heads":["利未人的十分之一奉獻"]},{"n":26,"t":"「你曉諭利未人說：你們從以色列人中所取的十分之一，就是我給你們為業的，要再從那十分之一中取十分之一作為舉祭獻給耶和華，","notes":[]},{"n":27,"t":"這舉祭要算為你們場上的穀，又如滿酒醡的酒。","notes":[]},{"n":28,"t":"這樣，你們從以色列人中所得的十分之一也要作舉祭獻給耶和華，從這十分之一中，將所獻給耶和華的舉祭歸給祭司亞倫。","notes":[]},{"n":29,"t":"奉給你們的一切禮物，要從其中將至好的，就是分別為聖的，獻給耶和華為舉祭。","notes":[]},{"n":30,"t":"所以你要對利未人說：你們從其中將至好的舉起，這就算為你們場上的糧，又如酒醡的酒。","notes":[]},{"n":31,"t":"你們和你們家屬隨處可以吃；這原是你們的賞賜，是酬你們在會幕裏辦事的勞。","notes":[]},{"n":32,"t":"你們從其中將至好的舉起，就不致因這物擔罪。你們不可褻瀆以色列人的聖物，免得死亡。」","notes":[]}]},"19":{"heading":"紅母牛的灰","verses":[{"n":1,"t":"耶和華曉諭摩西、亞倫說：","notes":[]},{"n":2,"t":"「耶和華命定律法中的一條律例乃是這樣說：你要吩咐以色列人，把一隻沒有殘疾、未曾負軛、純紅的母牛牽到你這裏來，","notes":[]},{"n":3,"t":"交給祭司以利亞撒；他必牽到營外，人就把牛宰在他面前。","notes":[]},{"n":4,"t":"祭司以利亞撒要用指頭蘸這牛的血，向會幕前面彈七次。","notes":[]},{"n":5,"t":"人要在他眼前把這母牛焚燒；牛的皮、肉、血、糞都要焚燒。","notes":[]},{"n":6,"t":"祭司要把香柏木、牛膝草、朱紅色線都丟在燒牛的火中。","notes":[]},{"n":7,"t":"祭司必不潔淨到晚上，要洗衣服，用水洗身，然後可以進營。","notes":[]},{"n":8,"t":"燒牛的人必不潔淨到晚上，也要洗衣服，用水洗身。","notes":[]},{"n":9,"t":"必有一個潔淨的人收起母牛的灰，存在營外潔淨的地方，為以色列會眾調做除污穢的水。這本是除罪的。","notes":[]},{"n":10,"t":"收起母牛灰的人必不潔淨到晚上，要洗衣服。這要給以色列人和寄居在他們中間的外人作為永遠的定例。」","notes":[]},{"n":11,"t":"「摸了人死屍的，就必七天不潔淨。","notes":[],"heads":["接觸屍體不潔的條例"]},{"n":12,"t":"那人到第三天要用這除污穢的水潔淨自己，第七天就潔淨了。他若在第三天不潔淨自己，第七天就不潔淨了。","notes":[]},{"n":13,"t":"凡摸了人死屍、不潔淨自己的，就玷污了耶和華的帳幕，這人必從以色列中剪除；因為那除污穢的水沒有灑在他身上，他就為不潔淨，污穢還在他身上。","notes":[]},{"n":14,"t":"「人死在帳棚裏的條例乃是這樣：凡進那帳棚的，和一切在帳棚裏的，都必七天不潔淨。","notes":[]},{"n":15,"t":"凡敞口的器皿，就是沒有紮上蓋的，也是不潔淨。","notes":[]},{"n":16,"t":"無論何人在田野裏摸了被刀殺的，或是屍首，或是人的骨頭，或是墳墓，就要七天不潔淨。","notes":[]},{"n":17,"t":"要為這不潔淨的人拿些燒成的除罪灰放在器皿裏，倒上活水。","notes":[]},{"n":18,"t":"必當有一個潔淨的人拿牛膝草蘸在這水中，把水灑在帳棚上，和一切器皿並帳棚內的眾人身上，又灑在摸了骨頭，或摸了被殺的，或摸了自死的，或摸了墳墓的那人身上。","notes":[]},{"n":19,"t":"第三天和第七天，潔淨的人要灑水在不潔淨的人身上，第七天就使他成為潔淨。那人要洗衣服，用水洗澡，到晚上就潔淨了。","notes":[]},{"n":20,"t":"「但那污穢而不潔淨自己的，要將他從會中剪除，因為他玷污了耶和華的聖所。除污穢的水沒有灑在他身上，他是不潔淨的。","notes":[]},{"n":21,"t":"這要給你們作為永遠的定例。並且那灑除污穢水的人要洗衣服。凡摸除污穢水的，必不潔淨到晚上。","notes":[]},{"n":22,"t":"不潔淨人所摸的一切物就不潔淨；摸了這物的人必不潔淨到晚上。」","notes":[]}]},"20":{"heading":"在加低斯發生的事件","verses":[{"n":1,"t":"正月間，以色列全會眾到了尋的曠野，就住在加低斯。米利暗死在那裏，就葬在那裏。","notes":[]},{"n":2,"t":"會眾沒有水喝，就聚集攻擊摩西、亞倫。","notes":[]},{"n":3,"t":"百姓向摩西爭鬧說：「我們的弟兄曾死在耶和華面前，我們恨不得與他們同死。","notes":[]},{"n":4,"t":"你們為何把耶和華的會眾領到這曠野、使我們和牲畜都死在這裏呢？","notes":[]},{"n":5,"t":"你們為何逼著我們出埃及、領我們到這壞地方呢？這地方不好撒種，也沒有無花果樹、葡萄樹、石榴樹，又沒有水喝。」","notes":[]},{"n":6,"t":"摩西、亞倫離開會眾，到會幕門口，俯伏在地；耶和華的榮光向他們顯現。","notes":[]},{"n":7,"t":"耶和華曉諭摩西說：","notes":[]},{"n":8,"t":"「你拿著杖去，和你的哥哥亞倫招聚會眾，在他們眼前吩咐磐石發出水來，水就從磐石流出，給會眾和他們的牲畜喝。」","notes":[]},{"n":9,"t":"於是摩西照耶和華所吩咐的，從耶和華面前取了杖去。","notes":[]},{"n":10,"t":"摩西、亞倫就招聚會眾到磐石前。摩西說：「你們這些背叛的人聽我說：我為你們使水從這磐石中流出來嗎？」","notes":[]},{"n":11,"t":"摩西舉手，用杖擊打磐石兩下，就有許多水流出來，會眾和他們的牲畜都喝了。","notes":[]},{"n":12,"t":"耶和華對摩西、亞倫說：「因為你們不信我，不在以色列人眼前尊我為聖，所以你們必不得領這會眾進我所賜給他們的地去。」","notes":[]},{"n":13,"t":"這水名叫米利巴水，是因以色列人向耶和華爭鬧，耶和華就在他們面前顯為聖。","notes":["米利巴就是爭鬧的意思"]},{"n":14,"t":"摩西從加低斯差遣使者去見以東王，說：「你的弟兄以色列人這樣說：『我們所遭遇的一切艱難，","notes":[],"heads":["以東王不容以色列人通行"]},{"n":15,"t":"就是我們的列祖下到埃及，我們在埃及久住；埃及人惡待我們的列祖和我們，","notes":[]},{"n":16,"t":"我們哀求耶和華的時候，他聽了我們的聲音，差遣使者把我們從埃及領出來。這事你都知道。如今，我們在你邊界上的城加低斯。","notes":[]},{"n":17,"t":"求你容我們從你的地經過。我們不走田間和葡萄園，也不喝井裏的水，只走大道，不偏左右，直到過了你的境界。』」","notes":["原文是王道"]},{"n":18,"t":"以東王說：「你不可從我的地經過，免得我帶刀出去攻擊你。」","notes":[]},{"n":19,"t":"以色列人說：「我們要走大道上去；我們和牲畜若喝你的水，必給你價值。不求別的，只求你容我們步行過去。」","notes":[]},{"n":20,"t":"以東王說：「你們不可經過！」就率領許多人出來，要用強硬的手攻擊以色列人。","notes":[]},{"n":21,"t":"這樣，以東王不肯容以色列人從他的境界過去。於是他們轉去，離開他。","notes":[]},{"n":22,"t":"以色列全會眾從加低斯起行，到了何珥山。","notes":[],"heads":["亞倫逝世"]},{"n":23,"t":"耶和華在附近以東邊界的何珥山上曉諭摩西、亞倫說：","notes":[]},{"n":24,"t":"「亞倫要歸到他列祖那裏。他必不得入我所賜給以色列人的地；因為在米利巴水，你們違背了我的命。","notes":["原文是本民"]},{"n":25,"t":"你帶亞倫和他的兒子以利亞撒上何珥山，","notes":[]},{"n":26,"t":"把亞倫的聖衣脫下來，給他的兒子以利亞撒穿上；亞倫必死在那裏，歸他列祖。」","notes":[]},{"n":27,"t":"摩西就照耶和華所吩咐的行。三人當著會眾的眼前上了何珥山。","notes":[]},{"n":28,"t":"摩西把亞倫的聖衣脫下來，給他的兒子以利亞撒穿上，亞倫就死在山頂那裏。於是摩西和以利亞撒下了山。","notes":[]},{"n":29,"t":"全會眾，就是以色列全家，見亞倫已經死了，便都為亞倫哀哭了三十天。","notes":[]}]},"21":{"heading":"戰勝迦南人","verses":[{"n":1,"t":"住南地的迦南人亞拉得王，聽說以色列人從亞他林路來，就和以色列人爭戰，擄了他們幾個人。","notes":[]},{"n":2,"t":"以色列人向耶和華發願說：「你若將這民交付我手，我就把他們的城邑盡行毀滅。」","notes":[]},{"n":3,"t":"耶和華應允了以色列人，把迦南人交付他們，他們就把迦南人和迦南人的城邑盡行毀滅。那地方的名便叫何珥瑪。","notes":["就是毀滅的意思"]},{"n":4,"t":"他們從何珥山起行，往紅海那條路走，要繞過以東地。百姓因這路難行，心中甚是煩躁，","notes":[],"heads":["銅製的蛇"]},{"n":5,"t":"就怨讟神和摩西說：「你們為甚麼把我們從埃及領出來、使我們死在曠野呢？這裏沒有糧，沒有水，我們的心厭惡這淡薄的食物。」","notes":[]},{"n":6,"t":"於是耶和華使火蛇進入百姓中間，蛇就咬他們。以色列人中死了許多。","notes":[]},{"n":7,"t":"百姓到摩西那裏，說：「我們怨讟耶和華和你，有罪了。求你禱告耶和華，叫這些蛇離開我們。」於是摩西為百姓禱告。","notes":[]},{"n":8,"t":"耶和華對摩西說：「你製造一條火蛇，掛在杆子上；凡被咬的，一望這蛇，就必得活。」","notes":[]},{"n":9,"t":"摩西便製造一條銅蛇，掛在杆子上；凡被蛇咬的，一望這銅蛇就活了。","notes":[]},{"n":10,"t":"以色列人起行，安營在阿伯。","notes":[],"heads":["從何珥山到摩押谷"]},{"n":11,"t":"又從阿伯起行，安營在以耶‧亞巴琳，與摩押相對的曠野，向日出之地。","notes":[]},{"n":12,"t":"從那裏起行，安營在撒烈谷。","notes":[]},{"n":13,"t":"從那裏起行，安營在亞嫩河那邊。這亞嫩河是在曠野，從亞摩利的境界流出來的；原來亞嫩河是摩押的邊界，在摩押和亞摩利人搭界的地方。","notes":[]},{"n":14,"t":"所以耶和華的戰記上說：「蘇法的哇哈伯與亞嫩河的谷，","notes":[]},{"n":15,"t":"並向亞珥城眾谷的下坡，是靠近摩押的境界。」","notes":[]},{"n":16,"t":"以色列人從那裏起行，到了比珥。從前耶和華吩咐摩西說：「招聚百姓，我好給他們水喝」，說的就是這井。","notes":["就是井的意思"]},{"n":17,"t":"當時，以色列人唱歌說：井啊，湧上水來！你們要向這井歌唱。","notes":[]},{"n":18,"t":"這井是首領和民中的尊貴人用圭用杖所挖所掘的。以色列人從曠野往瑪他拿去，","notes":[]},{"n":19,"t":"從瑪他拿到拿哈列，從拿哈列到巴末，","notes":[]},{"n":20,"t":"從巴末到摩押地的谷，又到那下望曠野之毗斯迦的山頂。","notes":[]},{"n":21,"t":"以色列人差遣使者去見亞摩利人的王西宏，說：","notes":[],"heads":["戰勝亞摩利王和巴珊王"]},{"n":22,"t":"「求你容我們從你的地經過；我們不偏入田間和葡萄園，也不喝井裏的水，只走大道，直到過了你的境界。」","notes":["原文是王道"]},{"n":23,"t":"西宏不容以色列人從他的境界經過，就招聚他的眾民出到曠野，要攻擊以色列人，到了雅雜與以色列人爭戰。","notes":[]},{"n":24,"t":"以色列人用刀殺了他，得了他的地，從亞嫩河到雅博河，直到亞捫人的境界，因為亞捫人的境界多有堅壘。","notes":[]},{"n":25,"t":"以色列人奪取這一切的城邑，也住亞摩利人的城邑，就是希實本與希實本的一切鄉村。","notes":[]},{"n":26,"t":"這希實本是亞摩利王西宏的京城；西宏曾與摩押的先王爭戰，從他手中奪取了全地，直到亞嫩河。","notes":[]},{"n":27,"t":"所以那些作詩歌的說：你們來到希實本；願西宏的城被修造，被建立。","notes":[]},{"n":28,"t":"因為有火從希實本發出，有火焰出於西宏的城，燒盡摩押的亞珥和亞嫩河邱壇的祭司。","notes":["祭司原文是主"]},{"n":29,"t":"摩押啊，你有禍了！基抹的民哪，你們滅亡了！基抹的男子逃奔，女子被擄，交付亞摩利的王西宏。","notes":[]},{"n":30,"t":"我們射了他們；希實本直到底本盡皆毀滅。我們使地變成荒場，直到挪法；這挪法直延到米底巴。","notes":[]},{"n":31,"t":"這樣，以色列人就住在亞摩利人之地。","notes":[]},{"n":32,"t":"摩西打發人去窺探雅謝，以色列人就佔了雅謝的鎮市，趕出那裏的亞摩利人。","notes":[]},{"n":33,"t":"以色列人轉回，向巴珊去。巴珊王噩和他的眾民都出來，在以得來與他們交戰。","notes":[]},{"n":34,"t":"耶和華對摩西說：「不要怕他！因我已將他和他的眾民，並他的地，都交在你手中；你要待他像從前待住希實本的亞摩利王西宏一般。」","notes":[]},{"n":35,"t":"於是他們殺了他和他的眾子，並他的眾民，沒有留下一個，就得了他的地。","notes":[]}]},"22":{"heading":"摩押王召巴蘭","verses":[{"n":1,"t":"以色列人起行，在摩押平原、約旦河東，對著耶利哥安營。","notes":[]},{"n":2,"t":"以色列人向亞摩利人所行的一切事，西撥的兒子巴勒都看見了。","notes":[]},{"n":3,"t":"摩押人因以色列民甚多，就大大懼怕，心內憂急，","notes":[]},{"n":4,"t":"對米甸的長老說：「現在這眾人要把我們四圍所有的一概餂盡，就如牛餂盡田間的草一般。」那時西撥的兒子巴勒作摩押王。","notes":[]},{"n":5,"t":"他差遣使者往大河邊的毗奪去，到比珥的兒子巴蘭本鄉那裏，召巴蘭來，說：「有一宗民從埃及出來，遮滿地面，與我對居。","notes":[]},{"n":6,"t":"這民比我強盛，現在求你來為我咒詛他們，或者我能得勝，攻打他們，趕出此地。因為我知道，你為誰祝福，誰就得福；你咒詛誰，誰就受咒詛。」","notes":[]},{"n":7,"t":"摩押的長老和米甸的長老手裏拿著卦金，到了巴蘭那裏，將巴勒的話都告訴了他。","notes":[]},{"n":8,"t":"巴蘭說：「你們今夜在這裏住宿，我必照耶和華所曉諭我的回報你們。」摩押的使臣就在巴蘭那裏住下了。","notes":[]},{"n":9,"t":"神臨到巴蘭那裏，說：「在你這裏的人都是誰？」","notes":[]},{"n":10,"t":"巴蘭回答說：「是摩押王西撥的兒子巴勒打發人到我這裏來，說：","notes":[]},{"n":11,"t":"『從埃及出來的民遮滿地面，你來為我咒詛他們，或者我能與他們爭戰，把他們趕出去。』」","notes":[]},{"n":12,"t":"神對巴蘭說：「你不可同他們去，也不可咒詛那民，因為那民是蒙福的。」","notes":[]},{"n":13,"t":"巴蘭早晨起來，對巴勒的使臣說：「你們回本地去吧，因為耶和華不容我和你們同去。」","notes":[]},{"n":14,"t":"摩押的使臣就起來，回巴勒那裏去，說：「巴蘭不肯和我們同來。」","notes":[]},{"n":15,"t":"巴勒又差遣使臣，比先前的又多又尊貴。","notes":[]},{"n":16,"t":"他們到了巴蘭那裏，對他說：「西撥的兒子巴勒這樣說：『求你不容甚麼事攔阻你不到我這裏來，","notes":[]},{"n":17,"t":"因為我必使你得極大的尊榮。你向我要甚麼，我就給你甚麼；只求你來為我咒詛這民。』」","notes":[]},{"n":18,"t":"巴蘭回答巴勒的臣僕說：「巴勒就是將他滿屋的金銀給我，我行大事小事也不得越過耶和華－我神的命。","notes":[]},{"n":19,"t":"現在我請你們今夜在這裏住宿，等我得知耶和華還要對我說甚麼。」","notes":[]},{"n":20,"t":"當夜，神臨到巴蘭那裏，說：「這些人若來召你，你就起來同他們去，你只要遵行我對你所說的話。」","notes":[]},{"n":21,"t":"巴蘭早晨起來，備上驢，和摩押的使臣一同去了。","notes":[],"heads":["巴蘭和他的驢"]},{"n":22,"t":"神因他去就發了怒；耶和華的使者站在路上敵擋他。他騎著驢，有兩個僕人跟隨他。","notes":[]},{"n":23,"t":"驢看見耶和華的使者站在路上，手裏有拔出來的刀，就從路上跨進田間，巴蘭便打驢，要叫牠回轉上路。","notes":[]},{"n":24,"t":"耶和華的使者就站在葡萄園的窄路上；這邊有牆，那邊也有牆。","notes":[]},{"n":25,"t":"驢看見耶和華的使者，就貼靠牆，將巴蘭的腳擠傷了；巴蘭又打驢。","notes":[]},{"n":26,"t":"耶和華的使者又往前去，站在狹窄之處，左右都沒有轉折的地方。","notes":[]},{"n":27,"t":"驢看見耶和華的使者，就臥在巴蘭底下，巴蘭發怒，用杖打驢。","notes":[]},{"n":28,"t":"耶和華叫驢開口，對巴蘭說：「我向你行了甚麼，你竟打我這三次呢？」","notes":[]},{"n":29,"t":"巴蘭對驢說：「因為你戲弄我，我恨不能手中有刀，把你殺了。」","notes":[]},{"n":30,"t":"驢對巴蘭說：「我不是你從小時直到今日所騎的驢嗎？我素常向你這樣行過嗎？」巴蘭說：「沒有。」","notes":[]},{"n":31,"t":"當時，耶和華使巴蘭的眼目明亮，他就看見耶和華的使者站在路上，手裏有拔出來的刀，巴蘭便低頭俯伏在地。","notes":[]},{"n":32,"t":"耶和華的使者對他說：「你為何這三次打你的驢呢？我出來敵擋你，因你所行的，在我面前偏僻。","notes":[]},{"n":33,"t":"驢看見我就三次從我面前偏過去；驢若沒有偏過去，我早把你殺了，留牠存活。」","notes":[]},{"n":34,"t":"巴蘭對耶和華的使者說：「我有罪了。我不知道你站在路上阻擋我；你若不喜歡我去，我就轉回。」","notes":[]},{"n":35,"t":"耶和華的使者對巴蘭說：「你同這些人去吧！你只要說我對你說的話。」於是巴蘭同著巴勒的使臣去了。","notes":[]},{"n":36,"t":"巴勒聽見巴蘭來了，就往摩押京城去迎接他；這城是在邊界上，在亞嫩河旁。","notes":[],"heads":["巴勒歡迎巴蘭"]},{"n":37,"t":"巴勒對巴蘭說：「我不是急急地打發人到你那裏去召你嗎？你為何不到我這裏來呢？我豈不能使你得尊榮嗎？」","notes":[]},{"n":38,"t":"巴蘭說：「我已經到你這裏來了！現在我豈能擅自說甚麼呢？神將甚麼話傳給我，我就說甚麼。」","notes":[]},{"n":39,"t":"巴蘭和巴勒同行，來到基列‧胡瑣。","notes":[]},{"n":40,"t":"巴勒宰了牛羊，送給巴蘭和陪伴的使臣。","notes":["原文是獻"]},{"n":41,"t":"到了早晨，巴勒領巴蘭到巴力的高處；巴蘭從那裏觀看以色列營的邊界。","notes":[],"heads":["巴蘭首次預言"]}]},"23":{"heading":"巴蘭第二次預言","verses":[{"n":1,"t":"巴蘭對巴勒說：「你在這裏給我築七座壇，為我預備七隻公牛，七隻公羊。」","notes":[]},{"n":2,"t":"巴勒照巴蘭的話行了。巴勒和巴蘭在每座壇上獻一隻公牛，一隻公羊。","notes":[]},{"n":3,"t":"巴蘭對巴勒說：「你站在你的燔祭旁邊，我且往前去，或者耶和華來迎見我。他指示我甚麼，我必告訴你。」於是巴蘭上一淨光的高處。","notes":[]},{"n":4,"t":"神迎見巴蘭；巴蘭說：「我預備了七座壇，在每座壇上獻了一隻公牛，一隻公羊。」","notes":[]},{"n":5,"t":"耶和華將話傳給巴蘭，又說：「你回到巴勒那裏，要如此如此說。」","notes":[]},{"n":6,"t":"他就回到巴勒那裏，見他同摩押的使臣都站在燔祭旁邊。","notes":[]},{"n":7,"t":"巴蘭便題起詩歌說：巴勒引我出亞蘭，摩押王引我出東山，說：來啊，為我咒詛雅各；來啊，怒罵以色列。","notes":[]},{"n":8,"t":"神沒有咒詛的，我焉能咒詛？耶和華沒有怒罵的，我焉能怒罵？","notes":[]},{"n":9,"t":"我從高峰看他，從小山望他；這是獨居的民，不列在萬民中。","notes":[]},{"n":10,"t":"誰能數點雅各的塵土？誰能計算以色列的四分之一？我願如義人之死而死；我願如義人之終而終。","notes":[]},{"n":11,"t":"巴勒對巴蘭說：「你向我做的是甚麼事呢？我領你來咒詛我的仇敵，不料，你竟為他們祝福。」","notes":[]},{"n":12,"t":"他回答說：「耶和華傳給我的話，我能不謹慎傳說嗎？」","notes":[]},{"n":13,"t":"巴勒說：「求你同我往別處去，在那裏可以看見他們；你不能全看見，只能看見他們邊界上的人。在那裏要為我咒詛他們。」","notes":[]},{"n":14,"t":"於是領巴蘭到了瑣腓田，上了毗斯迦山頂，築了七座壇；每座壇上獻一隻公牛，一隻公羊。","notes":[]},{"n":15,"t":"巴蘭對巴勒說：「你站在這燔祭旁邊，等我往那邊去迎見耶和華。」","notes":[]},{"n":16,"t":"耶和華臨到巴蘭那裏，將話傳給他；又說：「你回到巴勒那裏，要如此如此說。」","notes":[]},{"n":17,"t":"他就回到巴勒那裏，見他站在燔祭旁邊；摩押的使臣也和他在一處。巴勒問他說：「耶和華說了甚麼話呢？」","notes":[]},{"n":18,"t":"巴蘭就題詩歌說：巴勒，你起來聽；西撥的兒子，你聽我言。","notes":[]},{"n":19,"t":"神非人，必不致說謊，也非人子，必不致後悔。他說話豈不照著行呢？他發言豈不要成就呢？","notes":[]},{"n":20,"t":"我奉命祝福；神也曾賜福，此事我不能翻轉。","notes":[]},{"n":21,"t":"他未見雅各中有罪孽，也未見以色列中有奸惡。耶和華－他的神和他同在；有歡呼王的聲音在他們中間。","notes":[]},{"n":22,"t":"神領他們出埃及；他們似乎有野牛之力。","notes":[]},{"n":23,"t":"斷沒有法術可以害雅各，也沒有占卜可以害以色列。現在必有人論及雅各，就是論及以色列說：神為他行了何等的大事！","notes":[]},{"n":24,"t":"這民起來，彷彿母獅，挺身，好像公獅，未曾吃野食，未曾喝被傷者之血，決不躺臥。","notes":[]},{"n":25,"t":"巴勒對巴蘭說：「你一點不要咒詛他們，也不要為他們祝福。」","notes":[]},{"n":26,"t":"巴蘭回答巴勒說：「我豈不是告訴你說『凡耶和華所說的，我必須遵行』嗎？」","notes":[]},{"n":27,"t":"巴勒對巴蘭說：「來吧，我領你往別處去，或者神喜歡你在那裏為我咒詛他們。」","notes":[],"heads":["巴蘭第三次預言"]},{"n":28,"t":"巴勒就領巴蘭到那下望曠野的毗珥山頂上。","notes":[]},{"n":29,"t":"巴蘭對巴勒說：「你在這裏為我築七座壇，又在這裏為我預備七隻公牛，七隻公羊。」","notes":[]},{"n":30,"t":"巴勒就照巴蘭的話行，在每座壇上獻一隻公牛，一隻公羊。","notes":[]}]},"24":{"heading":"巴蘭末次預言","verses":[{"n":1,"t":"巴蘭見耶和華喜歡賜福與以色列，就不像前兩次去求法術，卻面向曠野。","notes":[]},{"n":2,"t":"巴蘭舉目，看見以色列人照著支派居住。神的靈就臨到他身上，","notes":[]},{"n":3,"t":"他便題起詩歌說：比珥的兒子巴蘭說，眼目閉住的人說，","notes":["或譯：睜開"]},{"n":4,"t":"得聽神的言語，得見全能者的異象，眼目睜開而仆倒的人說：","notes":[]},{"n":5,"t":"雅各啊，你的帳棚何等華美！以色列啊，你的帳幕何其華麗！","notes":[]},{"n":6,"t":"如接連的山谷，如河旁的園子，如耶和華所栽的沉香樹，如水邊的香柏木。","notes":[]},{"n":7,"t":"水要從他的桶裏流出；種子要撒在多水之處。他的王必超過亞甲；他的國必要振興。","notes":[]},{"n":8,"t":"神領他出埃及；他似乎有野牛之力。他要吞吃敵國，折斷他們的骨頭，用箭射透他們。","notes":[]},{"n":9,"t":"他蹲如公獅，臥如母獅，誰敢惹他？凡給你祝福的，願他蒙福；凡咒詛你的，願他受咒詛。","notes":[]},{"n":10,"t":"巴勒向巴蘭生氣，就拍起手來，對巴蘭說：「我召你來為我咒詛仇敵，不料，你這三次竟為他們祝福。","notes":[]},{"n":11,"t":"如今你快回本地去吧！我想使你得大尊榮，耶和華卻阻止你不得尊榮。」","notes":[]},{"n":12,"t":"巴蘭對巴勒說：「我豈不是對你所差遣到我那裏的使者說：","notes":[]},{"n":13,"t":"『巴勒就是將他滿屋的金銀給我，我也不得越過耶和華的命，憑自己的心意行好行歹。耶和華說甚麼，我就要說甚麼』？」","notes":[]},{"n":14,"t":"「現在我要回本族去。你來，我告訴你這民日後要怎樣待你的民。」","notes":[]},{"n":15,"t":"他就題起詩歌說：比珥的兒子巴蘭說：眼目閉住的人說，","notes":["或譯：睜開"]},{"n":16,"t":"得聽神的言語，明白至高者的意旨，看見全能者的異象，眼目睜開而仆倒的人說：","notes":[]},{"n":17,"t":"我看他卻不在現時；我望他卻不在近日。有星要出於雅各，有杖要興於以色列，必打破摩押的四角，毀壞擾亂之子。","notes":[]},{"n":18,"t":"他必得以東為基業，又得仇敵之地西珥為產業；以色列必行事勇敢。","notes":[]},{"n":19,"t":"有一位出於雅各的，必掌大權；他要除滅城中的餘民。","notes":[]},{"n":20,"t":"巴蘭觀看亞瑪力，就題起詩歌說：亞瑪力原為諸國之首，但他終必沉淪。","notes":[]},{"n":21,"t":"巴蘭觀看基尼人，就題起詩歌說：你的住處本是堅固；你的窩巢做在巖穴中。","notes":[]},{"n":22,"t":"然而基尼必至衰微，直到亞述把你擄去。","notes":[]},{"n":23,"t":"巴蘭又題起詩歌說：哀哉！神行這事，誰能得活？","notes":[]},{"n":24,"t":"必有人乘船從基提界而來，苦害亞述，苦害希伯；他也必至沉淪。","notes":[]},{"n":25,"t":"於是巴蘭起來，回他本地去；巴勒也回去了。","notes":[]}]},"25":{"heading":"以色列人在毗珥","verses":[{"n":1,"t":"以色列人住在什亭，百姓與摩押女子行起淫亂。","notes":[]},{"n":2,"t":"因為這女子叫百姓來，一同給她們的神獻祭，百姓就吃她們的祭物，跪拜她們的神。","notes":[]},{"n":3,"t":"以色列人與巴力‧毗珥連合，耶和華的怒氣就向以色列人發作。","notes":[]},{"n":4,"t":"耶和華吩咐摩西說：「將百姓中所有的族長在我面前對著日頭懸掛，使我向以色列人所發的怒氣可以消了。」","notes":[]},{"n":5,"t":"於是摩西吩咐以色列的審判官說：「凡屬你們的人，有與巴力‧毗珥連合的，你們各人要把他們殺了。」","notes":[]},{"n":6,"t":"摩西和以色列全會眾正在會幕門前哭泣的時候，誰知，有以色列中的一個人，當他們眼前，帶著一個米甸女人到他弟兄那裏去。","notes":[]},{"n":7,"t":"祭司亞倫的孫子，以利亞撒的兒子非尼哈看見了，就從會中起來，手裏拿著槍，","notes":[]},{"n":8,"t":"跟隨那以色列人進亭子裏去，便將以色列人和那女人由腹中刺透。這樣，在以色列人中瘟疫就止息了。","notes":[]},{"n":9,"t":"那時遭瘟疫死的，有二萬四千人。","notes":[]},{"n":10,"t":"耶和華曉諭摩西說：","notes":[]},{"n":11,"t":"「祭司亞倫的孫子，以利亞撒的兒子非尼哈，使我向以色列人所發的怒消了；因他在他們中間，以我的忌邪為心，使我不在忌邪中把他們除滅。","notes":[]},{"n":12,"t":"因此，你要說：『我將我平安的約賜給他。","notes":[]},{"n":13,"t":"這約要給他和他的後裔，作為永遠當祭司職任的約；因他為神有忌邪的心，為以色列人贖罪。』」","notes":[]},{"n":14,"t":"那與米甸女人一同被殺的以色列人，名叫心利，是撒路的兒子，是西緬一個宗族的首領。","notes":[]},{"n":15,"t":"那被殺的米甸女人，名叫哥斯比，是蘇珥的女兒；這蘇珥是米甸一個宗族的首領。","notes":[]},{"n":16,"t":"耶和華曉諭摩西說：","notes":[]},{"n":17,"t":"「你要擾害米甸人，擊殺他們；","notes":[]},{"n":18,"t":"因為他們用詭計擾害你們，在毗珥的事上和他們的姊妹、米甸首領的女兒哥斯比的事上，用這詭計誘惑了你們；這哥斯比，當瘟疫流行的日子，因毗珥的事被殺了。」","notes":[]}]},"26":{"heading":"第二次的人口普查","verses":[{"n":1,"t":"瘟疫之後，耶和華曉諭摩西和祭司亞倫的兒子以利亞撒說：","notes":[]},{"n":2,"t":"「你們要將以色列全會眾，按他們的宗族，凡以色列中從二十歲以外、能出去打仗的，計算總數。」","notes":[]},{"n":3,"t":"摩西和祭司以利亞撒在摩押平原與耶利哥相對的約旦河邊向以色列人說：","notes":[]},{"n":4,"t":"「將你們中間從二十歲以外的計算總數」；是照耶和華吩咐出埃及地的摩西和以色列人的話。","notes":[]},{"n":5,"t":"以色列的長子是呂便。呂便的眾子：屬哈諾的，有哈諾族；屬法路的，有法路族；","notes":[]},{"n":6,"t":"屬希斯倫的，有希斯倫族；屬迦米的，有迦米族；","notes":[]},{"n":7,"t":"這就是呂便的各族；其中被數的，共有四萬三千七百三十名。","notes":[]},{"n":8,"t":"法路的兒子是以利押。","notes":[]},{"n":9,"t":"以利押的眾子是尼母利、大坍、亞比蘭。這大坍、亞比蘭，就是從會中選召的，與可拉一黨同向耶和華爭鬧的時候也向摩西、亞倫爭鬧；","notes":[]},{"n":10,"t":"地便開口吞了他們，和可拉、可拉的黨類一同死亡。那時火燒滅了二百五十個人；他們就作了警戒。","notes":[]},{"n":11,"t":"然而可拉的眾子沒有死亡。","notes":[]},{"n":12,"t":"按著家族，西緬的眾子：屬尼母利的，有尼母利族；屬雅憫的，有雅憫族；屬雅斤的，有雅斤族；","notes":[]},{"n":13,"t":"屬謝拉的，有謝拉族；屬掃羅的，有掃羅族。","notes":[]},{"n":14,"t":"這就是西緬的各族，共有二萬二千二百名。","notes":[]},{"n":15,"t":"按著家族，迦得的眾子：屬洗分的，有洗分族；屬哈基的，有哈基族；屬書尼的，有書尼族；","notes":[]},{"n":16,"t":"屬阿斯尼的，有阿斯尼族；屬以利的，有以利族；","notes":[]},{"n":17,"t":"屬亞律的，有亞律族；屬亞列利的，有亞列利族。","notes":[]},{"n":18,"t":"這就是迦得子孫的各族，照他們中間被數的，共有四萬零五百名。","notes":[]},{"n":19,"t":"猶大的兒子是珥和俄南。這珥和俄南死在迦南地。","notes":[]},{"n":20,"t":"按著家族，猶大其餘的眾子：屬示拉的，有示拉族；屬法勒斯的，有法勒斯族；屬謝拉的，有謝拉族。","notes":[]},{"n":21,"t":"法勒斯的兒子：屬希斯崙的，有希斯崙族；屬哈母勒的，有哈母勒族。","notes":[]},{"n":22,"t":"這就是猶大的各族，照他們中間被數的，共有七萬六千五百名。","notes":[]},{"n":23,"t":"按著家族，以薩迦的眾子：屬陀拉的，有陀拉族；屬普瓦的，有普瓦族；","notes":[]},{"n":24,"t":"屬雅述的，有雅述族；屬伸崙的，有伸崙族。","notes":[]},{"n":25,"t":"這就是以薩迦的各族，照他們中間被數的，共有六萬四千三百名。","notes":[]},{"n":26,"t":"按著家族，西布倫的眾子：屬西烈的，有西烈族；屬以倫的，有以倫族；屬雅利的，有雅利族。","notes":[]},{"n":27,"t":"這就是西布倫的各族，照他們中間被數的，共有六萬零五百名。","notes":[]},{"n":28,"t":"按著家族，約瑟的兒子有瑪拿西、以法蓮。","notes":[]},{"n":29,"t":"瑪拿西的眾子：屬瑪吉的，有瑪吉族；瑪吉生基列；屬基列的，有基列族。","notes":[]},{"n":30,"t":"基列的眾子：屬伊以謝的，有伊以謝族；屬希勒的，有希勒族；","notes":[]},{"n":31,"t":"屬亞斯烈的，有亞斯烈族；屬示劍的，有示劍族；","notes":[]},{"n":32,"t":"屬示米大的，有示米大族；屬希弗的，有希弗族。","notes":[]},{"n":33,"t":"希弗的兒子：西羅非哈沒兒子，只有女兒。西羅非哈女兒的名字就是瑪拉、挪阿、曷拉、密迦、得撒。","notes":[]},{"n":34,"t":"這就是瑪拿西的各族；他們中間被數的，共有五萬二千七百名。","notes":[]},{"n":35,"t":"按著家族，以法蓮的眾子：屬書提拉的，有書提拉族；屬比結的，有比結族；屬他罕的，有他罕族。","notes":[]},{"n":36,"t":"書提拉的眾子：屬以蘭的，有以蘭族。","notes":[]},{"n":37,"t":"這就是以法蓮子孫的各族，照他們中間被數的，共有三萬二千五百名。按著家族，這都是約瑟的子孫。","notes":[]},{"n":38,"t":"按著家族，便雅憫的眾子：屬比拉的，有比拉族；屬亞實別的，有亞實別族；屬亞希蘭的，有亞希蘭族；","notes":[]},{"n":39,"t":"屬書反的，有書反族；屬戶反的，有戶反族。","notes":[]},{"n":40,"t":"比拉的眾子是亞勒、乃幔。屬亞勒的，有亞勒族；屬乃幔的，有乃幔族。","notes":[]},{"n":41,"t":"按著家族，這就是便雅憫的子孫，其中被數的，共有四萬五千六百名。","notes":[]},{"n":42,"t":"按著家族，但的眾子：屬書含的，有書含族。按著家族，這就是但的各族。","notes":[]},{"n":43,"t":"照其中被數的，書含所有的各族，共有六萬四千四百名。","notes":[]},{"n":44,"t":"按著家族，亞設的眾子：屬音拿的，有音拿族；屬亦施韋的，有亦施韋族；屬比利亞的，有比利亞族。","notes":[]},{"n":45,"t":"比利亞的眾子：屬希別的，有希別族；屬瑪結的，有瑪結族。","notes":[]},{"n":46,"t":"亞設的女兒名叫西拉。","notes":[]},{"n":47,"t":"這就是亞設子孫的各族，照他們中間被數的，共有五萬三千四百名。","notes":[]},{"n":48,"t":"按著家族，拿弗他利的眾子：屬雅薛的，有雅薛族；屬沽尼的，有沽尼族；","notes":[]},{"n":49,"t":"屬耶色的，有耶色族；屬示冷的，有示冷族。","notes":[]},{"n":50,"t":"按著家族，這就是拿弗他利的各族；他們中間被數的，共有四萬五千四百名。","notes":[]},{"n":51,"t":"以色列人中被數的，共有六十萬零一千七百三十名。","notes":[]},{"n":52,"t":"耶和華曉諭摩西說：","notes":[]},{"n":53,"t":"「你要按著人名的數目將地分給這些人為業。","notes":[]},{"n":54,"t":"人多的，你要把產業多分給他們；人少的，你要把產業少分給他們；要照被數的人數，把產業分給各人。","notes":[]},{"n":55,"t":"雖是這樣，還要拈鬮分地。他們要按著祖宗各支派的名字承受為業。","notes":[]},{"n":56,"t":"要按著所拈的鬮，看人數多，人數少，把產業分給他們。」","notes":[]},{"n":57,"t":"利未人，按著他們的各族被數的：屬革順的，有革順族；屬哥轄的，有哥轄族；屬米拉利的，有米拉利族。","notes":[]},{"n":58,"t":"利未的各族有立尼族、希伯倫族、瑪利族、母示族、可拉族。哥轄生暗蘭。","notes":[]},{"n":59,"t":"暗蘭的妻名叫約基別，是利未女子，生在埃及。她給暗蘭生了亞倫、摩西，並他們的姊姊米利暗。","notes":[]},{"n":60,"t":"亞倫生拿答、亞比戶、以利亞撒、以他瑪。","notes":[]},{"n":61,"t":"拿答、亞比戶在耶和華面前獻凡火的時候就死了。","notes":[]},{"n":62,"t":"利未人中，凡一個月以外、被數的男丁，共有二萬三千。他們本來沒有數在以色列人中；因為在以色列人中，沒有分給他們產業。","notes":[]},{"n":63,"t":"這些就是被摩西和祭司以利亞撒所數的；他們在摩押平原與耶利哥相對的約旦河邊數點以色列人。","notes":[]},{"n":64,"t":"但被數的人中，沒有一個是摩西和祭司亞倫從前在西奈的曠野所數的以色列人，","notes":[]},{"n":65,"t":"因為耶和華論到他們說：「他們必要死在曠野。」所以，除了耶孚尼的兒子迦勒和嫩的兒子約書亞以外，連一個人也沒有存留。","notes":[]}]},"27":{"heading":"西羅非哈的女兒們","verses":[{"n":1,"t":"屬約瑟的兒子瑪拿西的各族，有瑪拿西的玄孫，瑪吉的曾孫，基列的孫子，希弗的兒子西羅非哈的女兒，名叫瑪拉、挪阿、曷拉、密迦、得撒。她們前來，","notes":[]},{"n":2,"t":"站在會幕門口，在摩西和祭司以利亞撒，並眾首領與全會眾面前，說：","notes":[]},{"n":3,"t":"「我們的父親死在曠野。他不與可拉同黨聚集攻擊耶和華，是在自己罪中死的；他也沒有兒子。","notes":[]},{"n":4,"t":"為甚麼因我們的父親沒有兒子就把他的名從他族中除掉呢？求你們在我們父親的弟兄中分給我們產業。」","notes":[]},{"n":5,"t":"於是，摩西將她們的案件呈到耶和華面前。","notes":[]},{"n":6,"t":"耶和華曉諭摩西說：","notes":[]},{"n":7,"t":"「西羅非哈的女兒說得有理。你定要在她們父親的弟兄中，把地分給她們為業；要將她們父親的產業歸給她們。","notes":[]},{"n":8,"t":"你也要曉諭以色列人說：『人若死了沒有兒子，就要把他的產業歸給他的女兒。","notes":[]},{"n":9,"t":"他若沒有女兒，就要把他的產業給他的弟兄。","notes":[]},{"n":10,"t":"他若沒有弟兄，就要把他的產業給他父親的弟兄。","notes":[]},{"n":11,"t":"他父親若沒有弟兄，就要把他的產業給他族中最近的親屬，他便要得為業。』這要作以色列人的律例典章，是照耶和華吩咐摩西的。」","notes":[]},{"n":12,"t":"耶和華對摩西說：「你上這亞巴琳山，觀看我所賜給以色列人的地。","notes":[],"heads":["約書亞被選為摩西的繼承人"]},{"n":13,"t":"看了以後，你也必歸到你列祖那裏，像你哥哥亞倫一樣。","notes":["原文是本民"]},{"n":14,"t":"因為你們在尋的曠野，當會眾爭鬧的時候，違背了我的命，沒有在湧水之地、會眾眼前尊我為聖。」（這水就是尋的曠野加低斯米利巴水。）","notes":[]},{"n":15,"t":"摩西對耶和華說：","notes":[]},{"n":16,"t":"「願耶和華萬人之靈的神，立一個人治理會眾，","notes":[]},{"n":17,"t":"可以在他們面前出入，也可以引導他們，免得耶和華的會眾如同沒有牧人的羊群一般。」","notes":[]},{"n":18,"t":"耶和華對摩西說：「嫩的兒子約書亞是心中有聖靈的；你將他領來，按手在他頭上，","notes":[]},{"n":19,"t":"使他站在祭司以利亞撒和全會眾面前，囑咐他，","notes":[]},{"n":20,"t":"又將你的尊榮給他幾分，使以色列全會眾都聽從他。","notes":[]},{"n":21,"t":"他要站在祭司以利亞撒面前；以利亞撒要憑烏陵的判斷，在耶和華面前為他求問。他和以色列全會眾都要遵以利亞撒的命出入。」","notes":[]},{"n":22,"t":"於是摩西照耶和華所吩咐的將約書亞領來，使他站在祭司以利亞撒和全會眾面前，","notes":[]},{"n":23,"t":"按手在他頭上，囑咐他，是照耶和華藉摩西所說的話。","notes":[]}]},"28":{"heading":"每天例常的祭","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人說：『獻給我的供物，就是獻給我作馨香火祭的食物，你們要按日期獻給我』；","notes":[]},{"n":3,"t":"又要對他們說：你們要獻給耶和華的火祭，就是沒有殘疾、一歲的公羊羔，每日兩隻，作為常獻的燔祭。","notes":[]},{"n":4,"t":"早晨要獻一隻，黃昏的時候要獻一隻；","notes":[]},{"n":5,"t":"又用細麵伊法十分之一，並搗成的油一欣四分之一，調和作為素祭。","notes":[]},{"n":6,"t":"這是西奈山所命定為常獻的燔祭，是獻給耶和華為馨香的火祭。","notes":[]},{"n":7,"t":"為這一隻羊羔，要同獻奠祭的酒一欣四分之一。在聖所中，你要將醇酒奉給耶和華為奠祭。","notes":[]},{"n":8,"t":"晚上，你要獻那一隻羊羔，必照早晨的素祭和同獻的奠祭獻上，作為馨香的火祭，獻給耶和華。」","notes":[]},{"n":9,"t":"「當安息日，要獻兩隻沒有殘疾、一歲的公羊羔，並用調油的細麵伊法十分之二為素祭，又將同獻的奠祭獻上。","notes":[],"heads":["安息日獻的祭"]},{"n":10,"t":"這是每安息日獻的燔祭；那常獻的燔祭和同獻的奠祭在外。」","notes":[]},{"n":11,"t":"「每月朔，你們要將兩隻公牛犢，一隻公綿羊，七隻沒有殘疾、一歲的公羊羔，獻給耶和華為燔祭。","notes":[],"heads":["月初獻的祭"]},{"n":12,"t":"每隻公牛要用調油的細麵伊法十分之三作為素祭；那隻公羊也用調油的細麵伊法十分之二作為素祭；","notes":[]},{"n":13,"t":"每隻羊羔要用調油的細麵伊法十分之一作為素祭和馨香的燔祭，是獻給耶和華的火祭。","notes":[]},{"n":14,"t":"一隻公牛要奠酒半欣，一隻公羊要奠酒一欣三分之一，一隻羊羔也奠酒一欣四分之一。這是每月的燔祭，一年之中要月月如此。","notes":[]},{"n":15,"t":"又要將一隻公山羊為贖罪祭，獻給耶和華；要獻在常獻的燔祭和同獻的奠祭以外。」","notes":[]},{"n":16,"t":"「正月十四日是耶和華的逾越節。","notes":[],"heads":["除酵節獻的祭"]},{"n":17,"t":"這月十五日是節期，要吃無酵餅七日。","notes":[]},{"n":18,"t":"第一日當有聖會；甚麼勞碌的工都不可做。","notes":[]},{"n":19,"t":"當將公牛犢兩隻，公綿羊一隻，一歲的公羊羔七隻，都要沒有殘疾的，用火獻給耶和華為燔祭。","notes":[]},{"n":20,"t":"同獻的素祭用調油的細麵；為一隻公牛要獻伊法十分之三；為一隻公羊要獻伊法十分之二；","notes":[]},{"n":21,"t":"為那七隻羊羔，每隻要獻伊法十分之一。","notes":[]},{"n":22,"t":"並獻一隻公山羊作贖罪祭，為你們贖罪。","notes":[]},{"n":23,"t":"你們獻這些，要在早晨常獻的燔祭以外。","notes":[]},{"n":24,"t":"一連七日，每日要照這例把馨香火祭的食物獻給耶和華，是在常獻的燔祭和同獻的奠祭以外。","notes":[]},{"n":25,"t":"第七日當有聖會，甚麼勞碌的工都不可做。」","notes":[]},{"n":26,"t":"「七七節莊稼初熟，你們獻新素祭給耶和華的日子，當有聖會；甚麼勞碌的工都不可做。","notes":[],"heads":["七七收穫節獻的祭"]},{"n":27,"t":"只要將公牛犢兩隻，公綿羊一隻，一歲的公羊羔七隻，作為馨香的燔祭獻給耶和華。","notes":[]},{"n":28,"t":"同獻的素祭用調油的細麵；為每隻公牛要獻伊法十分之三；為一隻公羊要獻伊法十分之二；","notes":[]},{"n":29,"t":"為那七隻羊羔，每隻要獻伊法十分之一。","notes":[]},{"n":30,"t":"並獻一隻公山羊為你們贖罪。","notes":[]},{"n":31,"t":"這些，你們要獻在常獻的燔祭和同獻的素祭並同獻的奠祭以外，都要沒有殘疾的。」","notes":[]}]},"29":{"heading":"新年獻的祭","verses":[{"n":1,"t":"「七月初一日，你們當有聖會；甚麼勞碌的工都不可做，是你們當守為吹角的日子。","notes":[]},{"n":2,"t":"你們要將公牛犢一隻，公綿羊一隻，沒有殘疾、一歲的公羊羔七隻，作為馨香的燔祭獻給耶和華。","notes":[]},{"n":3,"t":"同獻的素祭用調油的細麵；為一隻公牛要獻伊法十分之三；為一隻公羊要獻伊法十分之二；","notes":[]},{"n":4,"t":"為那七隻羊羔，每隻要獻伊法十分之一。","notes":[]},{"n":5,"t":"又獻一隻公山羊作贖罪祭，為你們贖罪。","notes":[]},{"n":6,"t":"這些是在月朔的燔祭和同獻的素祭，並常獻的燔祭與同獻的素祭，以及照例同獻的奠祭以外，都作為馨香的火祭獻給耶和華。」","notes":[]},{"n":7,"t":"「七月初十日，你們當有聖會；要刻苦己心，甚麼工都不可做。","notes":[],"heads":["贖罪日獻的祭"]},{"n":8,"t":"只要將公牛犢一隻，公綿羊一隻，一歲的公羊羔七隻，都要沒有殘疾的，作為馨香的燔祭獻給耶和華。","notes":[]},{"n":9,"t":"同獻的素祭用調油的細麵：為一隻公牛要獻伊法十分之三；為一隻公羊要獻伊法十分之二；","notes":[]},{"n":10,"t":"為那七隻羊羔，每隻要獻伊法十分之一。","notes":[]},{"n":11,"t":"又獻一隻公山羊為贖罪祭。這是在贖罪祭和常獻的燔祭，與同獻的素祭並同獻的奠祭以外。」","notes":[]},{"n":12,"t":"「七月十五日，你們當有聖會；甚麼勞碌的工都不可做，要向耶和華守節七日。","notes":[],"heads":["住棚節獻的祭"]},{"n":13,"t":"又要將公牛犢十三隻，公綿羊兩隻，一歲的公羊羔十四隻，都要沒有殘疾的，用火獻給耶和華為馨香的燔祭。","notes":[]},{"n":14,"t":"同獻的素祭用調油的細麵；為那十三隻公牛，每隻要獻伊法十分之三；為那兩隻公羊，每隻要獻伊法十分之二；","notes":[]},{"n":15,"t":"為那十四隻羊羔，每隻要獻伊法十分之一。","notes":[]},{"n":16,"t":"並獻一隻公山羊為贖罪祭，這是在常獻的燔祭和同獻的素祭並同獻的奠祭以外。","notes":[]},{"n":17,"t":"「第二日要獻公牛犢十二隻，公綿羊兩隻，沒有殘疾、一歲的公羊羔十四隻；","notes":[]},{"n":18,"t":"並為公牛、公羊，和羊羔，按數照例，獻同獻的素祭和同獻的奠祭。","notes":[]},{"n":19,"t":"又要獻一隻公山羊為贖罪祭。這是在常獻的燔祭和同獻的素祭並同獻的奠祭以外。","notes":[]},{"n":20,"t":"「第三日要獻公牛十一隻，公羊兩隻，沒有殘疾、一歲的公羊羔十四隻；","notes":[]},{"n":21,"t":"並為公牛、公羊，和羊羔，按數照例，獻同獻的素祭和同獻的奠祭。","notes":[]},{"n":22,"t":"又要獻一隻公山羊為贖罪祭。這是在常獻的燔祭和同獻的素祭並同獻的奠祭以外。","notes":[]},{"n":23,"t":"「第四日要獻公牛十隻，公羊兩隻，沒有殘疾、一歲的公羊羔十四隻；","notes":[]},{"n":24,"t":"並為公牛、公羊，和羊羔，按數照例，獻同獻的素祭和同獻的奠祭。","notes":[]},{"n":25,"t":"又要獻一隻公山羊為贖罪祭。這是在常獻的燔祭和同獻的素祭並同獻的奠祭以外。","notes":[]},{"n":26,"t":"「第五日要獻公牛九隻，公羊兩隻，沒有殘疾、一歲的公羊羔十四隻；","notes":[]},{"n":27,"t":"並為公牛、公羊，和羊羔，按數照例，獻同獻的素祭和同獻的奠祭。","notes":[]},{"n":28,"t":"又要獻一隻公山羊為贖罪祭。這是在常獻的燔祭和同獻的素祭並同獻的奠祭以外。","notes":[]},{"n":29,"t":"「第六日要獻公牛八隻，公羊兩隻，沒有殘疾、一歲的公羊羔十四隻；","notes":[]},{"n":30,"t":"並為公牛、公羊，和羊羔，按數照例，獻同獻的素祭和同獻的奠祭。","notes":[]},{"n":31,"t":"又要獻一隻公山羊為贖罪祭。這是在常獻的燔祭和同獻的素祭並同獻的奠祭以外。","notes":[]},{"n":32,"t":"「第七日要獻公牛七隻，公羊兩隻，沒有殘疾、一歲的公羊羔十四隻；","notes":[]},{"n":33,"t":"並為公牛、公羊，和羊羔，按數照例，獻同獻的素祭和同獻的奠祭。","notes":[]},{"n":34,"t":"又要獻一隻公山羊為贖罪祭。這是在常獻的燔祭和同獻的素祭並同獻的奠祭以外。","notes":[]},{"n":35,"t":"「第八日你們當有嚴肅會；甚麼勞碌的工都不可做；","notes":[]},{"n":36,"t":"只要將公牛一隻，公羊一隻，沒有殘疾、一歲的公羊羔七隻作火祭，獻給耶和華為馨香的燔祭；","notes":[]},{"n":37,"t":"並為公牛、公羊，和羊羔，按數照例，獻同獻的素祭和同獻的奠祭。","notes":[]},{"n":38,"t":"又要獻一隻公山羊為贖罪祭。這是在常獻的燔祭和同獻的素祭並同獻的奠祭以外。","notes":[]},{"n":39,"t":"「這些祭要在你們的節期獻給耶和華，都在所許的願並甘心所獻的以外，作為你們的燔祭、素祭、奠祭，和平安祭。」","notes":[]},{"n":40,"t":"於是，摩西照耶和華所吩咐他的一切話告訴以色列人。","notes":[]}]},"30":{"heading":"許願的條例","verses":[{"n":1,"t":"摩西曉諭以色列各支派的首領說：「耶和華所吩咐的乃是這樣：","notes":[]},{"n":2,"t":"人若向耶和華許願或起誓，要約束自己，就不可食言，必要按口中所出的一切話行。","notes":[]},{"n":3,"t":"女子年幼、還在父家的時候，若向耶和華許願，要約束自己，","notes":[]},{"n":4,"t":"她父親也聽見她所許的願並約束自己的話，卻向她默默不言，她所許的願並約束自己的話就都要為定。","notes":[]},{"n":5,"t":"但她父親聽見的日子若不應承她所許的願和約束自己的話，就都不得為定；耶和華也必赦免她，因為她父親不應承。","notes":[]},{"n":6,"t":"她若出了嫁，有願在身，或是口中出了約束自己的冒失話，","notes":[]},{"n":7,"t":"她丈夫聽見的日子，卻向她默默不言，她所許的願並約束自己的話就都要為定。","notes":[]},{"n":8,"t":"但她丈夫聽見的日子，若不應承，就算廢了她所許的願和她出口約束自己的冒失話；耶和華也必赦免她。","notes":[]},{"n":9,"t":"寡婦或是被休的婦人所許的願，就是她約束自己的話，都要為定。","notes":[]},{"n":10,"t":"她若在丈夫家裏許了願或起了誓，約束自己，","notes":[]},{"n":11,"t":"丈夫聽見，卻向她默默不言，也沒有不應承，她所許的願並約束自己的話就都要為定。","notes":[]},{"n":12,"t":"丈夫聽見的日子，若把這兩樣全廢了，婦人口中所許的願或是約束自己的話就都不得為定，因她丈夫已經把這兩樣廢了；耶和華也必赦免她。","notes":[]},{"n":13,"t":"凡她所許的願和刻苦約束自己所起的誓，她丈夫可以堅定，也可以廢去。","notes":[]},{"n":14,"t":"倘若她丈夫天天向她默默不言，就算是堅定她所許的願和約束自己的話；因丈夫聽見的日子向她默默不言，就使這兩樣堅定。","notes":[]},{"n":15,"t":"但她丈夫聽見以後，若使這兩樣全廢了，就要擔當婦人的罪孽。」","notes":[]},{"n":16,"t":"這是丈夫待妻子，父親待女兒，女兒年幼、還在父家，耶和華所吩咐摩西的律例。","notes":[]}]},"31":{"heading":"跟米甸人打仗","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要在米甸人身上報以色列人的仇，後來要歸到你列祖那裏。」","notes":["原文是本民"]},{"n":3,"t":"摩西吩咐百姓說：「要從你們中間叫人帶兵器出去攻擊米甸，好在米甸人身上為耶和華報仇。","notes":[]},{"n":4,"t":"從以色列眾支派中，每支派要打發一千人去打仗。」","notes":[]},{"n":5,"t":"於是從以色列千萬人中，每支派交出一千人，共一萬二千人，帶著兵器預備打仗。","notes":[]},{"n":6,"t":"摩西就打發每支派的一千人去打仗，並打發祭司以利亞撒的兒子非尼哈同去；非尼哈手裏拿著聖所的器皿和吹大聲的號筒。","notes":[]},{"n":7,"t":"他們就照耶和華所吩咐摩西的，與米甸人打仗，殺了所有的男丁。","notes":[]},{"n":8,"t":"在所殺的人中，殺了米甸的五王，就是以未、利金、蘇珥、戶珥、利巴，又用刀殺了比珥的兒子巴蘭。","notes":[]},{"n":9,"t":"以色列人擄了米甸人的婦女孩子，並將他們的牲畜、羊群，和所有的財物都奪了來，當作擄物，","notes":[]},{"n":10,"t":"又用火焚燒他們所住的城邑和所有的營寨，","notes":[]},{"n":11,"t":"把一切所奪的、所擄的，連人帶牲畜都帶了去，","notes":[]},{"n":12,"t":"將所擄的人，所奪的牲畜、財物，都帶到摩押平原，在約旦河邊與耶利哥相對的營盤，交給摩西和祭司以利亞撒，並以色列的會眾。","notes":[]},{"n":13,"t":"摩西和祭司以利亞撒，並會眾一切的首領，都出到營外迎接他們。","notes":[],"heads":["打仗回來"]},{"n":14,"t":"摩西向打仗回來的軍長，就是千夫長、百夫長，發怒，","notes":[]},{"n":15,"t":"對他們說：「你們要存留這一切婦女的活命嗎？","notes":[]},{"n":16,"t":"這些婦女因巴蘭的計謀，叫以色列人在毗珥的事上得罪耶和華，以致耶和華的會眾遭遇瘟疫。","notes":[]},{"n":17,"t":"所以，你們要把一切的男孩和所有已嫁的女子都殺了。","notes":[]},{"n":18,"t":"但女孩子中，凡沒有出嫁的，你們都可以存留她的活命。","notes":[]},{"n":19,"t":"你們要在營外駐紮七日；凡殺了人的，和一切摸了被殺的，並你們所擄來的人口，第三日，第七日，都要潔淨自己，","notes":[]},{"n":20,"t":"也要因一切的衣服、皮物、山羊毛織的物，和各樣的木器，潔淨自己。」","notes":[]},{"n":21,"t":"祭司以利亞撒對打仗回來的兵丁說：「耶和華所吩咐摩西律法中的條例乃是這樣：","notes":[]},{"n":22,"t":"金、銀、銅、鐵、錫、鉛，","notes":[]},{"n":23,"t":"凡能見火的，你們要叫它經火就為潔淨，然而還要用除污穢的水潔淨它；凡不能見火的，你們要叫它過水。","notes":[]},{"n":24,"t":"第七日，你們要洗衣服，就為潔淨，然後可以進營。」","notes":[]},{"n":25,"t":"耶和華曉諭摩西說：","notes":[],"heads":["分戰利品"]},{"n":26,"t":"「你和祭司以利亞撒，並會眾的各族長，要計算所擄來的人口和牲畜的總數。","notes":[]},{"n":27,"t":"把所擄來的分作兩半：一半歸與出去打仗的精兵，一半歸與全會眾。","notes":[]},{"n":28,"t":"又要從出去打仗所得的人口、牛、驢、羊群中，每五百取一，作為貢物奉給耶和華。","notes":[]},{"n":29,"t":"從他們一半之中，要取出來交給祭司以利亞撒，作為耶和華的舉祭。","notes":[]},{"n":30,"t":"從以色列人的一半之中，就是從人口、牛、驢、羊群、各樣牲畜中，每五十取一，交給看守耶和華帳幕的利未人。」","notes":[]},{"n":31,"t":"於是摩西和祭司以利亞撒照耶和華所吩咐摩西的行了。","notes":[]},{"n":32,"t":"除了兵丁所奪的財物以外，所擄來的：羊六十七萬五千隻；","notes":[]},{"n":33,"t":"牛七萬二千隻；","notes":[]},{"n":34,"t":"驢六萬一千匹；","notes":[]},{"n":35,"t":"女人共三萬二千口，都是沒有出嫁的。","notes":[]},{"n":36,"t":"出去打仗之人的分，就是他們所得的那一半，共計羊三十三萬七千五百隻，","notes":[]},{"n":37,"t":"從其中歸耶和華為貢物的，有六百七十五隻；","notes":[]},{"n":38,"t":"牛三萬六千隻，從其中歸耶和華為貢物的，有七十二隻；","notes":[]},{"n":39,"t":"驢三萬零五百匹，從其中歸耶和華為貢物的，有六十一匹；","notes":[]},{"n":40,"t":"人一萬六千口，從其中歸耶和華的，有三十二口。","notes":[]},{"n":41,"t":"摩西把貢物，就是歸與耶和華的舉祭，交給祭司以利亞撒，是照耶和華所吩咐摩西的。","notes":[]},{"n":42,"t":"以色列人所得的那一半，就是摩西從打仗的人取來分給他們的。（","notes":[]},{"n":43,"t":"會眾的那一半有：羊三十三萬七千五百隻；","notes":[]},{"n":44,"t":"牛三萬六千隻；","notes":[]},{"n":45,"t":"驢三萬零五百匹；","notes":[]},{"n":46,"t":"人一萬六千口。）","notes":[]},{"n":47,"t":"無論是人口是牲畜，摩西每五十取一，交給看守耶和華帳幕的利未人，是照耶和華所吩咐摩西的。","notes":[]},{"n":48,"t":"帶領千軍的各軍長，就是千夫長、百夫長，都近前來見摩西，","notes":[]},{"n":49,"t":"對他說：「僕人權下的兵已經計算總數，並不短少一人。","notes":[]},{"n":50,"t":"如今我們將各人所得的金器，就是腳鍊子、鐲子、打印的戒指、耳環、手釧，都送來為耶和華的供物，好在耶和華面前為我們的生命贖罪。」","notes":[]},{"n":51,"t":"摩西和祭司以利亞撒就收了他們的金子，都是打成的器皿。","notes":[]},{"n":52,"t":"千夫長、百夫長所獻給耶和華為舉祭的金子共有一萬六千七百五十舍客勒。","notes":[]},{"n":53,"t":"各兵丁都為自己奪了財物。","notes":[]},{"n":54,"t":"摩西和祭司以利亞撒收了千夫長、百夫長的金子，就帶進會幕，在耶和華面前作為以色列人的紀念。","notes":[]}]},"32":{"heading":"約旦河東的兩支派","verses":[{"n":1,"t":"呂便子孫和迦得子孫的牲畜極其眾多；他們看見雅謝地和基列地是可牧放牲畜之地，","notes":[]},{"n":2,"t":"就來見摩西和祭司以利亞撒，並會眾的首領，說：","notes":[]},{"n":3,"t":"「亞大錄、底本、雅謝、寧拉、希實本、以利亞利、示班、尼波、比穩，","notes":[]},{"n":4,"t":"就是耶和華在以色列會眾前面所攻取之地，是可牧放牲畜之地，你僕人也有牲畜」；","notes":[]},{"n":5,"t":"又說：「我們若在你眼前蒙恩，求你把這地給我們為業，不要領我們過約旦河。」","notes":[]},{"n":6,"t":"摩西對迦得子孫和呂便子孫說：「難道你們的弟兄去打仗，你們竟坐在這裏嗎？","notes":[]},{"n":7,"t":"你們為何使以色列人灰心喪膽、不過去進入耶和華所賜給他們的那地呢？","notes":[]},{"n":8,"t":"我先前從加低斯‧巴尼亞打發你們先祖去窺探那地，他們也是這樣行。","notes":[]},{"n":9,"t":"他們上以實各谷，去窺探那地回來的時候，使以色列人灰心喪膽，不進入耶和華所賜給他們的地。","notes":[]},{"n":10,"t":"當日，耶和華的怒氣發作，就起誓說：","notes":[]},{"n":11,"t":"『凡從埃及上來、二十歲以外的人斷不得看見我對亞伯拉罕、以撒、雅各起誓應許之地，因為他們沒有專心跟從我。","notes":[]},{"n":12,"t":"惟有基尼洗族耶孚尼的兒子迦勒和嫩的兒子約書亞可以看見，因為他們專心跟從我。』","notes":[]},{"n":13,"t":"耶和華的怒氣向以色列人發作，使他們在曠野飄流四十年，等到在耶和華眼前行惡的那一代人都消滅了。","notes":[]},{"n":14,"t":"誰知，你們起來接續先祖，增添罪人的數目，使耶和華向以色列大發烈怒。","notes":[]},{"n":15,"t":"你們若退後不跟從他，他還要把以色列人撇在曠野，便是你們使這眾民滅亡。」","notes":[]},{"n":16,"t":"兩支派的人挨近摩西，說：「我們要在這裏為牲畜壘圈，為婦人孩子造城。","notes":[]},{"n":17,"t":"我們自己要帶兵器行在以色列人的前頭，好把他們領到他們的地方；但我們的婦人孩子，因這地居民的緣故，要住在堅固的城內。","notes":[]},{"n":18,"t":"我們不回家，直等到以色列人各承受自己的產業。","notes":[]},{"n":19,"t":"我們不和他們在約旦河那邊一帶之地同受產業，因為我們的產業是坐落在約旦河東邊這裏。」","notes":[]},{"n":20,"t":"摩西對他們說：「你們若這樣行，在耶和華面前帶著兵器出去打仗，","notes":[]},{"n":21,"t":"所有帶兵器的人都要在耶和華面前過約旦河，等他趕出他的仇敵，","notes":[]},{"n":22,"t":"那地被耶和華制伏了，然後你們可以回來，向耶和華和以色列才為無罪，這地也必在耶和華面前歸你們為業。","notes":[]},{"n":23,"t":"倘若你們不這樣行，就得罪耶和華，要知道你們的罪必追上你們。","notes":[]},{"n":24,"t":"如今你們口中所出的，只管去行，為你們的婦人孩子造城，為你們的羊群壘圈。」","notes":[]},{"n":25,"t":"迦得子孫和呂便子孫對摩西說：「僕人要照我主所吩咐的去行。","notes":[]},{"n":26,"t":"我們的妻子、孩子、羊群，和所有的牲畜都要留在基列的各城。","notes":[]},{"n":27,"t":"但你的僕人，凡帶兵器的，都要照我主所說的話，在耶和華面前過去打仗。」","notes":[]},{"n":28,"t":"於是，摩西為他們囑咐祭司以利亞撒和嫩的兒子約書亞，並以色列眾支派的族長，說：","notes":[]},{"n":29,"t":"「迦得子孫和呂便子孫，凡帶兵器在耶和華面前去打仗的，若與你們一同過約旦河，那地被你們制伏了，你們就要把基列地給他們為業。","notes":[]},{"n":30,"t":"倘若他們不帶兵器和你們一同過去，就要在迦南地你們中間得產業。」","notes":[]},{"n":31,"t":"迦得子孫和呂便子孫回答說：「耶和華怎樣吩咐僕人，僕人就怎樣行。","notes":[]},{"n":32,"t":"我們要帶兵器，在耶和華面前過去，進入迦南地，只是約旦河這邊、我們所得為業之地仍歸我們。」","notes":[]},{"n":33,"t":"摩西將亞摩利王西宏的國和巴珊王噩的國，連那地和周圍的城邑，都給了迦得子孫和呂便子孫，並約瑟的兒子瑪拿西半個支派。","notes":[]},{"n":34,"t":"迦得子孫建造底本、亞他錄、亞羅珥、","notes":[]},{"n":35,"t":"亞他錄‧朔反、雅謝、約比哈、","notes":[]},{"n":36,"t":"伯‧寧拉、伯‧哈蘭，都是堅固城。他們又壘羊圈。","notes":[]},{"n":37,"t":"呂便子孫建造希實本、以利亞利、基列亭、","notes":[]},{"n":38,"t":"尼波、巴力‧免、西比瑪（尼波、巴力‧免，名字是改了的），又給他們所建造的城另起別名。","notes":[]},{"n":39,"t":"瑪拿西的兒子瑪吉，他的子孫往基列去，佔了那地，趕出那裏的亞摩利人。","notes":[]},{"n":40,"t":"摩西將基列賜給瑪拿西的兒子瑪吉，他子孫就住在那裏。","notes":[]},{"n":41,"t":"瑪拿西的子孫睚珥去佔了基列的村莊，就稱這些村莊為哈倭特‧睚珥。","notes":[]},{"n":42,"t":"挪巴去佔了基納和基納的鄉村，就按自己的名稱基納為挪巴。","notes":[]}]},"33":{"heading":"從埃及到摩押","verses":[{"n":1,"t":"以色列人按著軍隊，在摩西、亞倫的手下出埃及地所行的路程記在下面。","notes":["或譯：站口；下同"]},{"n":2,"t":"摩西遵著耶和華的吩咐記載他們所行的路程，其路程乃是這樣：","notes":[]},{"n":3,"t":"正月十五日，就是逾越節的次日，以色列人從蘭塞起行，在一切埃及人眼前昂然無懼地出去。","notes":[]},{"n":4,"t":"那時，埃及人正葬埋他們的長子，就是耶和華在他們中間所擊殺的；耶和華也敗壞他們的神。","notes":[]},{"n":5,"t":"以色列人從蘭塞起行，安營在疏割。","notes":[]},{"n":6,"t":"從疏割起行，安營在曠野邊的以倘。","notes":[]},{"n":7,"t":"從以倘起行，轉到比‧哈希錄，是在巴力‧洗分對面，就在密奪安營。","notes":[]},{"n":8,"t":"從比‧哈希錄對面起行，經過海中到了書珥曠野，又在伊坦的曠野走了三天的路程，就安營在瑪拉。","notes":[]},{"n":9,"t":"從瑪拉起行，來到以琳（以琳有十二股水泉，七十棵棕樹），就在那裏安營。","notes":[]},{"n":10,"t":"從以琳起行，安營在紅海邊。","notes":[]},{"n":11,"t":"從紅海邊起行，安營在汛的曠野。","notes":[]},{"n":12,"t":"從汛的曠野起行，安營在脫加。","notes":[]},{"n":13,"t":"從脫加起行，安營在亞錄。","notes":[]},{"n":14,"t":"從亞錄起行，安營在利非訂；在那裏，百姓沒有水喝。","notes":[]},{"n":15,"t":"從利非訂起行，安營在西奈的曠野。","notes":[]},{"n":16,"t":"從西奈的曠野起行，安營在基博羅‧哈他瓦。","notes":[]},{"n":17,"t":"從基博羅‧哈他瓦起行，安營在哈洗錄。","notes":[]},{"n":18,"t":"從哈洗錄起行，安營在利提瑪。","notes":[]},{"n":19,"t":"從利提瑪起行，安營在臨門‧帕烈。","notes":[]},{"n":20,"t":"從臨門‧帕烈起行，安營在立拿。","notes":[]},{"n":21,"t":"從立拿起行，安營在勒撒。","notes":[]},{"n":22,"t":"從勒撒起行，安營在基希拉他。","notes":[]},{"n":23,"t":"從基希拉他起行，安營在沙斐山。","notes":[]},{"n":24,"t":"從沙斐山起行，安營在哈拉大。","notes":[]},{"n":25,"t":"從哈拉大起行，安營在瑪吉希錄。","notes":[]},{"n":26,"t":"從瑪吉希錄起行，安營在他哈。","notes":[]},{"n":27,"t":"從他哈起行，安營在他拉。","notes":[]},{"n":28,"t":"從他拉起行，安營在密加。","notes":[]},{"n":29,"t":"從密加起行，安營在哈摩拿。","notes":[]},{"n":30,"t":"從哈摩拿起行，安營在摩西錄。","notes":[]},{"n":31,"t":"從摩西錄起行，安營在比尼‧亞干。","notes":[]},{"n":32,"t":"從比尼‧亞干起行，安營在曷‧哈及甲。","notes":[]},{"n":33,"t":"從曷‧哈及甲起行，安營在約巴他。","notes":[]},{"n":34,"t":"從約巴他起行，安營在阿博拿。","notes":[]},{"n":35,"t":"從阿博拿起行，安營在以旬‧迦別。","notes":[]},{"n":36,"t":"從以旬‧迦別起行，安營在尋的曠野，就是加低斯。","notes":[]},{"n":37,"t":"從加低斯起行，安營在何珥山，以東地的邊界。","notes":[]},{"n":38,"t":"以色列人出了埃及地後四十年，五月初一日，祭司亞倫遵著耶和華的吩咐上何珥山，就死在那裏。","notes":[]},{"n":39,"t":"亞倫死在何珥山的時候年一百二十三歲。","notes":[]},{"n":40,"t":"住在迦南南地的迦南人亞拉得王聽說以色列人來了。","notes":[]},{"n":41,"t":"以色列人從何珥山起行，安營在撒摩拿。","notes":[]},{"n":42,"t":"從撒摩拿起行，安營在普嫩。","notes":[]},{"n":43,"t":"從普嫩起行，安營在阿伯。","notes":[]},{"n":44,"t":"從阿伯起行，安營在以耶‧亞巴琳，摩押的邊界。","notes":[]},{"n":45,"t":"從以耶‧亞巴琳起行，安營在底本‧迦得。","notes":[]},{"n":46,"t":"從底本‧迦得起行，安營在亞門‧低比拉太音。","notes":[]},{"n":47,"t":"從亞門‧低比拉太音起行，安營在尼波對面的亞巴琳山裏。","notes":[]},{"n":48,"t":"從亞巴琳山起行，安營在摩押平原－約旦河邊、耶利哥對面。","notes":[]},{"n":49,"t":"他們在摩押平原沿約旦河邊安營，從伯‧耶施末直到亞伯‧什亭。","notes":[]},{"n":50,"t":"耶和華在摩押平原－約旦河邊、耶利哥對面曉諭摩西說：","notes":[],"heads":["過約旦河前的指示"]},{"n":51,"t":"「你吩咐以色列人說：你們過約旦河進迦南地的時候，","notes":[]},{"n":52,"t":"就要從你們面前趕出那裏所有的居民，毀滅他們一切鏨成的石像和他們一切鑄成的偶像，又拆毀他們一切的邱壇。","notes":[]},{"n":53,"t":"你們要奪那地，住在其中，因我把那地賜給你們為業。","notes":[]},{"n":54,"t":"你們要按家室拈鬮，承受那地；人多的，要把產業多分給他們；人少的，要把產業少分給他們。拈出何地給何人，就要歸何人。你們要按宗族的支派承受。","notes":[]},{"n":55,"t":"倘若你們不趕出那地的居民，所容留的居民就必作你們眼中的刺，肋下的荊棘，也必在你們所住的地上擾害你們。","notes":[]},{"n":56,"t":"而且我素常有意怎樣待他們，也必照樣待你們。」","notes":[]}]},"34":{"heading":"迦南地的境界","verses":[{"n":1,"t":"耶和華曉諭摩西說：","notes":[]},{"n":2,"t":"「你吩咐以色列人說：你們到了迦南地，就是歸你們為業的迦南四境之地，","notes":[]},{"n":3,"t":"南角要從尋的曠野，貼著以東的邊界；南界要從鹽海東頭起，","notes":[]},{"n":4,"t":"繞到亞克拉濱坡的南邊，接連到尋，直通到加低斯‧巴尼亞的南邊，又通到哈薩‧亞達，接連到押們，","notes":[]},{"n":5,"t":"從押們轉到埃及小河，直通到海為止。","notes":[]},{"n":6,"t":"「西邊要以大海為界；這就是你們的西界。","notes":[]},{"n":7,"t":"「北界要從大海起，劃到何珥山，","notes":[]},{"n":8,"t":"從何珥山劃到哈馬口，通到西達達，","notes":[]},{"n":9,"t":"又通到西斐崙，直到哈薩‧以難。這要作你們的北界。","notes":[]},{"n":10,"t":"「你們要從哈薩‧以難劃到示番為東界。","notes":[]},{"n":11,"t":"這界要從示番下到亞延東邊的利比拉，又要達到基尼烈湖的東邊。","notes":[]},{"n":12,"t":"這界要下到約旦河，通到鹽海為止。這四圍的邊界以內，要作你們的地。」","notes":[]},{"n":13,"t":"摩西吩咐以色列人說：「這地就是耶和華吩咐拈鬮給九個半支派承受為業的；","notes":[]},{"n":14,"t":"因為呂便支派和迦得支派按著宗族受了產業，瑪拿西半個支派也受了產業。","notes":[]},{"n":15,"t":"這兩個半支派已經在耶利哥對面、約旦河東、向日出之地受了產業。」","notes":[]},{"n":16,"t":"耶和華曉諭摩西說：","notes":[],"heads":["各支派首領負責分地"]},{"n":17,"t":"「要給你們分地為業之人的名字是祭司以利亞撒和嫩的兒子約書亞。","notes":[]},{"n":18,"t":"又要從每支派中選一個首領幫助他們。","notes":[]},{"n":19,"t":"這些人的名字：猶大支派有耶孚尼的兒子迦勒。","notes":[]},{"n":20,"t":"西緬支派有亞米忽的兒子示母利。","notes":[]},{"n":21,"t":"便雅憫支派有基斯倫的兒子以利達。","notes":[]},{"n":22,"t":"但支派有一個首領，約利的兒子布基。","notes":[]},{"n":23,"t":"約瑟的子孫瑪拿西支派有一個首領，以弗的兒子漢聶。","notes":[]},{"n":24,"t":"以法蓮支派有一個首領，拾弗但的兒子基母利。","notes":[]},{"n":25,"t":"西布倫支派有一個首領，帕納的兒子以利撒番。","notes":[]},{"n":26,"t":"以薩迦支派有一個首領，阿散的兒子帕鐵。","notes":[]},{"n":27,"t":"亞設支派有一個首領，示羅米的兒子亞希忽。","notes":[]},{"n":28,"t":"拿弗他利支派有一個首領，亞米忽的兒子比大黑。」","notes":[]},{"n":29,"t":"這些人就是耶和華所吩咐、在迦南地把產業分給以色列人的。","notes":[]}]},"35":{"heading":"分給利未人的城邑","verses":[{"n":1,"t":"耶和華在摩押平原－約旦河邊、耶利哥對面曉諭摩西說：","notes":[]},{"n":2,"t":"「你吩咐以色列人，要從所得為業的地中把些城給利未人居住，也要把這城四圍的郊野給利未人。","notes":[]},{"n":3,"t":"這城邑要歸他們居住，城邑的郊野可以牧養他們的牛羊和各樣的牲畜，又可以安置他們的財物。","notes":[]},{"n":4,"t":"你們給利未人的郊野，要從城根起，四圍往外量一千肘。","notes":[]},{"n":5,"t":"另外東量二千肘，南量二千肘，西量二千肘，北量二千肘，為邊界，城在當中；這要歸他們作城邑的郊野。","notes":[]},{"n":6,"t":"你們給利未人的城邑，其中當有六座逃城，使誤殺人的可以逃到那裏。此外還要給他們四十二座城。","notes":[]},{"n":7,"t":"你們要給利未人的城，共有四十八座，連城帶郊野都要給他們。","notes":[]},{"n":8,"t":"以色列人所得的地業從中要把些城邑給利未人；人多的就多給，人少的就少給；各支派要按所承受為業之地把城邑給利未人。」","notes":[]},{"n":9,"t":"耶和華曉諭摩西說：","notes":[],"heads":["庇護城"]},{"n":10,"t":"「你吩咐以色列人說：你們過約旦河，進了迦南地，","notes":[]},{"n":11,"t":"就要分出幾座城，為你們作逃城，使誤殺人的可以逃到那裏。","notes":[]},{"n":12,"t":"這些城可以作逃避報仇人的城，使誤殺人的不至於死，等他站在會眾面前聽審判。","notes":[]},{"n":13,"t":"你們所分出來的城，要作六座逃城。","notes":[]},{"n":14,"t":"在約旦河東要分出三座城，在迦南地也要分出三座城，都作逃城。","notes":[]},{"n":15,"t":"這六座城要給以色列人和他們中間的外人，並寄居的，作為逃城，使誤殺人的都可以逃到那裏。","notes":[]},{"n":16,"t":"「倘若人用鐵器打人，以致打死，他就是故殺人的；故殺人的必被治死。","notes":[]},{"n":17,"t":"若用可以打死人的石頭打死了人，他就是故殺人的；故殺人的必被治死。","notes":[]},{"n":18,"t":"若用可以打死人的木器打死了人，他就是故殺人的；故殺人的必被治死。","notes":[]},{"n":19,"t":"報血仇的必親自殺那故殺人的，一遇見就殺他。","notes":[]},{"n":20,"t":"人若因怨恨把人推倒，或是埋伏往人身上扔物，以致於死，","notes":[]},{"n":21,"t":"或是因仇恨用手打人，以致於死，那打人的必被治死。他是故殺人的；報血仇的一遇見就殺他。","notes":[]},{"n":22,"t":"「倘若人沒有仇恨，忽然將人推倒，或是沒有埋伏把物扔在人身上，","notes":[]},{"n":23,"t":"或是沒有看見的時候用可以打死人的石頭扔在人身上，以致於死，本來與他無仇，也無意害他。","notes":[]},{"n":24,"t":"會眾就要照典章，在打死人的和報血仇的中間審判。","notes":[]},{"n":25,"t":"會眾要救這誤殺人的脫離報血仇人的手，也要使他歸入逃城。他要住在其中，直等到受聖膏的大祭司死了。","notes":[]},{"n":26,"t":"但誤殺人的，無論甚麼時候，若出了逃城的境外，","notes":[]},{"n":27,"t":"報血仇的在逃城境外遇見他，將他殺了，報血仇的就沒有流血之罪。","notes":[]},{"n":28,"t":"因為誤殺人的該住在逃城裏，等到大祭司死了。大祭司死了以後，誤殺人的才可以回到他所得為業之地。","notes":[]},{"n":29,"t":"這在你們一切的住處，要作你們世世代代的律例典章。","notes":[]},{"n":30,"t":"「無論誰故殺人，要憑幾個見證人的口把那故殺人的殺了，只是不可憑一個見證的口叫人死。","notes":[]},{"n":31,"t":"故殺人、犯死罪的，你們不可收贖價代替他的命；他必被治死。","notes":[]},{"n":32,"t":"那逃到逃城的人，你們不可為他收贖價，使他在大祭司未死以先再來住在本地。","notes":[]},{"n":33,"t":"這樣，你們就不污穢所住之地，因為血是污穢地的；若有在地上流人血的，非流那殺人者的血，那地就不得潔淨。","notes":["原文是贖"]},{"n":34,"t":"你們不可玷污所住之地，就是我住在其中之地，因為我－耶和華住在以色列人中間。」","notes":[]}]},"36":{"heading":"承業女子結婚的條例","verses":[{"n":1,"t":"約瑟的後裔，瑪拿西的孫子，瑪吉的兒子基列，他子孫中的諸族長來到摩西和作首領的以色列人族長面前，說：","notes":[]},{"n":2,"t":"「耶和華曾吩咐我主拈鬮分給以色列人為業，我主也受了耶和華的吩咐將我們兄弟西羅非哈的產業分給他的眾女兒。","notes":[]},{"n":3,"t":"她們若嫁以色列別支派的人，就必將我們祖宗所遺留的產業加在她們丈夫支派的產業中。這樣，我們拈鬮所得的產業就要減少了。","notes":[]},{"n":4,"t":"到了以色列人的禧年，這女兒的產業就必加在她們丈夫支派的產業上。這樣，我們祖宗支派的產業就減少了。」","notes":[]},{"n":5,"t":"摩西照耶和華的話吩咐以色列人說：「約瑟支派的人說得有理。","notes":[]},{"n":6,"t":"論到西羅非哈的眾女兒，耶和華這樣吩咐說：她們可以隨意嫁人，只是要嫁同宗支派的人。","notes":[]},{"n":7,"t":"這樣，以色列人的產業就不從這支派歸到那支派，因為以色列人要各守各祖宗支派的產業。","notes":[]},{"n":8,"t":"凡在以色列支派中得了產業的女子必作同宗支派人的妻，好叫以色列人各自承受他祖宗的產業。","notes":[]},{"n":9,"t":"這樣，他們的產業就不從這支派歸到那支派，因為以色列支派的人要各守各的產業。」","notes":[]},{"n":10,"t":"耶和華怎樣吩咐摩西，西羅非哈的眾女兒就怎樣行。","notes":[]},{"n":11,"t":"西羅非哈的女兒瑪拉、得撒、曷拉、密迦、挪阿都嫁了他們伯叔的兒子。","notes":[]},{"n":12,"t":"她們嫁入約瑟兒子、瑪拿西子孫的族中；她們的產業仍留在同宗支派中。","notes":[]},{"n":13,"t":"這是耶和華在摩押平原－約旦河邊、耶利哥對面－藉著摩西所吩咐以色列人的命令典章。","notes":[]}]}},"DEU":{"1":{"heading":"摩西回憶","verses":[{"n":1,"t":"以下所記的是摩西在約旦河東的曠野、疏弗對面的亞拉巴－就是巴蘭、陀弗、拉班、哈洗錄、底撒哈中間－向以色列眾人所說的話。（","notes":[]},{"n":2,"t":"從何烈山經過西珥山到加低斯‧巴尼亞有十一天的路程。）","notes":[]},{"n":3,"t":"出埃及第四十年十一月初一日，摩西照耶和華藉著他所吩咐以色列人的話都曉諭他們。","notes":[]},{"n":4,"t":"那時，他已經擊殺了住希實本的亞摩利王西宏和住以得來、亞斯他錄的巴珊王噩。","notes":[]},{"n":5,"t":"摩西在約旦河東的摩押地講律法說：","notes":[]},{"n":6,"t":"「耶和華－我們的神在何烈山曉諭我們說：你們在這山上住的日子夠了；","notes":[]},{"n":7,"t":"要起行轉到亞摩利人的山地和靠近這山地的各處，就是亞拉巴、山地、高原、南地，沿海一帶迦南人的地，並黎巴嫩山又到幼發拉底大河。","notes":[]},{"n":8,"t":"如今我將這地擺在你們面前；你們要進去得這地，就是耶和華向你們列祖亞伯拉罕、以撒、雅各起誓應許賜給他們和他們後裔為業之地。」","notes":[]},{"n":9,"t":"「那時，我對你們說：『管理你們的重任，我獨自擔當不起。","notes":[],"heads":["摩西指派審判官"]},{"n":10,"t":"耶和華－你們的神使你們多起來。看哪，你們今日像天上的星那樣多。","notes":[]},{"n":11,"t":"惟願耶和華－你們列祖的神使你們比如今更多千倍，照他所應許你們的話賜福與你們。","notes":[]},{"n":12,"t":"但你們的麻煩，和管理你們的重任，並你們的爭訟，我獨自一人怎能擔當得起呢？","notes":[]},{"n":13,"t":"你們要按著各支派選舉有智慧、有見識、為眾人所認識的，我立他們為你們的首領。』","notes":[]},{"n":14,"t":"你們回答我說：『照你所說的行了為妙。』","notes":[]},{"n":15,"t":"我便將你們各支派的首領，有智慧、為眾人所認識的，照你們的支派，立他們為官長、千夫長、百夫長、五十夫長、十夫長，管理你們。","notes":[]},{"n":16,"t":"「當時，我囑咐你們的審判官說：『你們聽訟，無論是弟兄彼此爭訟，是與同居的外人爭訟，都要按公義判斷。","notes":[]},{"n":17,"t":"審判的時候，不可看人的外貌；聽訟不可分貴賤，不可懼怕人，因為審判是屬乎神的。若有難斷的案件，可以呈到我這裏，我就判斷。』","notes":[]},{"n":18,"t":"那時，我將你們所當行的事都吩咐你們了。」","notes":[]},{"n":19,"t":"「我們照著耶和華－我們神所吩咐的從何烈山起行，經過你們所看見那大而可怕的曠野，往亞摩利人的山地去，到了加低斯‧巴尼亞。","notes":[],"heads":["從加低斯‧巴尼亞派探子偵察"]},{"n":20,"t":"我對你們說：『你們已經到了耶和華－我們神所賜給我們的亞摩利人之山地。","notes":[]},{"n":21,"t":"看哪，耶和華－你的神已將那地擺在你面前，你要照耶和華－你列祖的神所說的上去得那地為業；不要懼怕，也不要驚惶。』","notes":[]},{"n":22,"t":"你們都就近我來說：『我們要先打發人去，為我們窺探那地，將我們上去該走何道，必進何城，都回報我們。』","notes":[]},{"n":23,"t":"這話我以為美，就從你們中間選了十二個人，每支派一人。","notes":[]},{"n":24,"t":"於是他們起身上山地去，到以實各谷，窺探那地。","notes":[]},{"n":25,"t":"他們手裏拿著那地的果子下來，到我們那裏，回報說：『耶和華－我們的神所賜給我們的是美地。』","notes":[]},{"n":26,"t":"「你們卻不肯上去，竟違背了耶和華－你們神的命令，","notes":[]},{"n":27,"t":"在帳棚內發怨言說：『耶和華因為恨我們，所以將我們從埃及地領出來，要交在亞摩利人手中，除滅我們。","notes":[]},{"n":28,"t":"我們上哪裏去呢？我們的弟兄使我們的心消化，說那地的民比我們又大又高，城邑又廣大又堅固，高得頂天，並且我們在那裏看見亞衲族的人。』","notes":[]},{"n":29,"t":"我就對你們說：『不要驚恐，也不要怕他們。","notes":[]},{"n":30,"t":"在你們前面行的耶和華－你們的神必為你們爭戰，正如他在埃及和曠野，在你們眼前所行的一樣。","notes":[]},{"n":31,"t":"你們在曠野所行的路上，也曾見耶和華－你們的神撫養你們，如同人撫養兒子一般，直等你們來到這地方。』","notes":[]},{"n":32,"t":"你們在這事上卻不信耶和華－你們的神。","notes":[]},{"n":33,"t":"他在路上，在你們前面行，為你們找安營的地方；夜間在火柱裏，日間在雲柱裏，指示你們所當行的路。」","notes":[]},{"n":34,"t":"「耶和華聽見你們這話，就發怒，起誓說：","notes":[],"heads":["耶和華刑罰以色列人"]},{"n":35,"t":"『這惡世代的人，連一個也不得見我起誓應許賜給你們列祖的美地；","notes":[]},{"n":36,"t":"惟有耶孚尼的兒子迦勒必得看見，並且我要將他所踏過的地賜給他和他的子孫，因為他專心跟從我。』","notes":[]},{"n":37,"t":"耶和華為你的緣故也向我發怒，說：『你必不得進入那地。","notes":[]},{"n":38,"t":"伺候你、嫩的兒子約書亞，他必得進入那地；你要勉勵他，因為他要使以色列人承受那地為業。","notes":[]},{"n":39,"t":"並且你們的婦人孩子，就是你們所說、必被擄掠的，和今日不知善惡的兒女，必進入那地。我要將那地賜給他們，他們必得為業。","notes":[]},{"n":40,"t":"至於你們，要轉回，從紅海的路往曠野去。』","notes":[]},{"n":41,"t":"「那時，你們回答我說：『我們得罪了耶和華，情願照耶和華－我們神一切所吩咐的上去爭戰。』於是你們各人帶著兵器，爭先上山地去了。","notes":[]},{"n":42,"t":"耶和華吩咐我說：『你對他們說：不要上去，也不要爭戰；因我不在你們中間，恐怕你們被仇敵殺敗了。』","notes":[]},{"n":43,"t":"我就告訴了你們，你們卻不聽從，竟違背耶和華的命令，擅自上山地去了。","notes":[]},{"n":44,"t":"住那山地的亞摩利人就出來攻擊你們，追趕你們，如蜂擁一般，在西珥殺退你們，直到何珥瑪。","notes":[]},{"n":45,"t":"你們便回來，在耶和華面前哭號；耶和華卻不聽你們的聲音，也不向你們側耳。","notes":[]},{"n":46,"t":"於是你們在加低斯住了許多日子。」","notes":[]}]},"2":{"heading":"多年在曠野","verses":[{"n":1,"t":"「此後，我們轉回，從紅海的路往曠野去，是照耶和華所吩咐我的。我們在西珥山繞行了許多日子。","notes":[]},{"n":2,"t":"耶和華對我說：","notes":[]},{"n":3,"t":"『你們繞行這山的日子夠了，要轉向北去。","notes":[]},{"n":4,"t":"你吩咐百姓說：你們弟兄以掃的子孫住在西珥，你們要經過他們的境界。他們必懼怕你們，所以你們要分外謹慎。","notes":[]},{"n":5,"t":"不可與他們爭戰；他們的地，連腳掌可踏之處，我都不給你們，因我已將西珥山賜給以掃為業。","notes":[]},{"n":6,"t":"你們要用錢向他們買糧吃，也要用錢向他們買水喝。","notes":[]},{"n":7,"t":"因為耶和華－你的神在你手裏所辦的一切事上已賜福與你。你走這大曠野，他都知道了。這四十年，耶和華－你的神常與你同在，故此你一無所缺。』","notes":[]},{"n":8,"t":"「於是，我們離了我們弟兄以掃子孫所住的西珥，從亞拉巴的路，經過以拉他、以旬‧迦別，轉向摩押曠野的路去。","notes":[]},{"n":9,"t":"耶和華吩咐我說：『不可擾害摩押人，也不可與他們爭戰。他們的地，我不賜給你為業，因我已將亞珥賜給羅得的子孫為業。』（","notes":[]},{"n":10,"t":"先前，有以米人住在那裏，民數眾多，身體高大，像亞衲人一樣。","notes":[]},{"n":11,"t":"這以米人像亞衲人；也算為利乏音人；摩押人稱他們為以米人。","notes":[]},{"n":12,"t":"先前，何利人也住在西珥，但以掃的子孫將他們除滅，得了他們的地，接著居住，就如以色列在耶和華賜給他為業之地所行的一樣。）","notes":[]},{"n":13,"t":"現在，起來過撒烈溪！於是我們過了撒烈溪。","notes":[]},{"n":14,"t":"自從離開加低斯‧巴尼亞，到過了撒烈溪的時候，共有三十八年，等那世代的兵丁都從營中滅盡，正如耶和華向他們所起的誓。","notes":[]},{"n":15,"t":"耶和華的手也攻擊他們，將他們從營中除滅，直到滅盡。","notes":[]},{"n":16,"t":"「兵丁從民中都滅盡死亡以後，","notes":[]},{"n":17,"t":"耶和華吩咐我說：","notes":[]},{"n":18,"t":"『你今天要從摩押的境界亞珥經過，","notes":[]},{"n":19,"t":"走近亞捫人之地，不可擾害他們，也不可與他們爭戰。亞捫人的地，我不賜給你們為業，因我已將那地賜給羅得的子孫為業。』（","notes":[]},{"n":20,"t":"那地也算為利乏音人之地，先前利乏音人住在那裏，亞捫人稱他們為散送冥。","notes":[]},{"n":21,"t":"那民眾多，身體高大，像亞衲人一樣，但耶和華從亞捫人面前除滅他們，亞捫人就得了他們的地，接著居住。","notes":[]},{"n":22,"t":"正如耶和華從前為住西珥的以掃子孫將何利人從他們面前除滅、他們得了何利人的地、接著居住一樣，直到今日。","notes":[]},{"n":23,"t":"從迦斐託出來的迦斐託人將先前住在鄉村直到迦薩的亞衛人除滅，接著居住。）","notes":[]},{"n":24,"t":"你們起來前往，過亞嫩谷；我已將亞摩利人希實本王西宏和他的地交在你手中，你要與他爭戰，得他的地為業。","notes":[]},{"n":25,"t":"從今日起，我要使天下萬民聽見你的名聲都驚恐懼怕，且因你發顫傷慟。」","notes":[]},{"n":26,"t":"「我從基底莫的曠野差遣使者去見希實本王西宏，用和睦的話說：","notes":[],"heads":["擊敗希實本王西宏"]},{"n":27,"t":"『求你容我從你的地經過，只走大道，不偏左右。","notes":[]},{"n":28,"t":"你可以賣糧給我吃，也可以賣水給我喝，只要容我步行過去，","notes":[]},{"n":29,"t":"就如住西珥的以掃子孫和住亞珥的摩押人待我一樣，等我過了約旦河，好進入耶和華－我們神所賜給我們的地。』","notes":[]},{"n":30,"t":"但希實本王西宏不容我們從他那裏經過；因為耶和華－你的神使他心中剛硬，性情頑梗，為要將他交在你手中，像今日一樣。","notes":[]},{"n":31,"t":"耶和華對我說：『從此起首，我要將西宏和他的地交給你；你要得他的地為業。』","notes":[]},{"n":32,"t":"那時，西宏和他的眾民出來攻擊我們，在雅雜與我們交戰。","notes":[]},{"n":33,"t":"耶和華－我們的神將他交給我們，我們就把他和他的兒子，並他的眾民，都擊殺了。","notes":[]},{"n":34,"t":"我們奪了他的一切城邑，將有人煙的各城，連女人帶孩子，盡都毀滅，沒有留下一個。","notes":[]},{"n":35,"t":"惟有牲畜和所奪的各城，並其中的財物，都取為自己的掠物。","notes":[]},{"n":36,"t":"從亞嫩谷邊的亞羅珥和谷中的城，直到基列，耶和華－我們的神都交給我們了，沒有一座城高得使我們不能攻取的。","notes":[]},{"n":37,"t":"惟有亞捫人之地，凡靠近雅博河的地，並山地的城邑，與耶和華－我們神所禁止我們去的地方，都沒有挨近。」","notes":[]}]},"3":{"heading":"擊敗巴珊王噩","verses":[{"n":1,"t":"「以後，我們轉回，向巴珊去。巴珊王噩和他的眾民都出來，在以得來與我們交戰。","notes":[]},{"n":2,"t":"耶和華對我說：『不要怕他！因我已將他和他的眾民，並他的地，都交在你手中；你要待他像從前待住希實本的亞摩利王西宏一樣。』","notes":[]},{"n":3,"t":"於是耶和華－我們的神也將巴珊王噩和他的眾民都交在我們手中；我們殺了他們，沒有留下一個。","notes":[]},{"n":4,"t":"那時，我們奪了他所有的城，共有六十座，沒有一座城不被我們所奪。這為亞珥歌伯的全境，就是巴珊地噩王的國。","notes":[]},{"n":5,"t":"這些城都有堅固的高牆，有門有閂。此外還有許多無城牆的鄉村。","notes":[]},{"n":6,"t":"我們將這些都毀滅了，像從前待希實本王西宏一樣，把有人煙的各城，連女人帶孩子，盡都毀滅；","notes":[]},{"n":7,"t":"惟有一切牲畜和城中的財物都取為自己的掠物。","notes":[]},{"n":8,"t":"那時，我們從約旦河東兩個亞摩利王的手將亞嫩谷直到黑門山之地奪過來（","notes":[]},{"n":9,"t":"這黑門山，西頓人稱為西連，亞摩利人稱為示尼珥），","notes":[]},{"n":10,"t":"就是奪了平原的各城、基列全地、巴珊全地，直到撒迦和以得來，都是巴珊王噩國內的城邑。（","notes":[]},{"n":11,"t":"利乏音人所剩下的只有巴珊王噩。他的床是鐵的，長九肘，寬四肘，都是以人肘為度。現今豈不是在亞捫人的拉巴嗎？）」","notes":[]},{"n":12,"t":"「那時，我們得了這地。從亞嫩谷邊的亞羅珥起，我將基列山地的一半，並其中的城邑，都給了呂便人和迦得人。","notes":[],"heads":["定居約旦河東的二支派半"]},{"n":13,"t":"其餘的基列地和巴珊全地，就是噩王的國，我給了瑪拿西半支派。亞珥歌伯全地乃是巴珊全地；這叫做利乏音人之地。","notes":[]},{"n":14,"t":"瑪拿西的子孫睚珥佔了亞珥歌伯全境，直到基述人和瑪迦人的交界，就按自己的名稱這巴珊地為哈倭特‧睚珥，直到今日。","notes":[]},{"n":15,"t":"我又將基列給了瑪吉。","notes":[]},{"n":16,"t":"從基列到亞嫩谷，以谷中為界，直到亞捫人交界的雅博河，我給了呂便人和迦得人，","notes":[]},{"n":17,"t":"又將亞拉巴和靠近約旦河之地，從基尼烈直到亞拉巴海，就是鹽海，並毗斯迦山根東邊之地，都給了他們。","notes":[]},{"n":18,"t":"「那時，我吩咐你們說：『耶和華－你們的神已將這地賜給你們為業；你們所有的勇士都要帶著兵器，在你們的弟兄以色列人前面過去。","notes":[]},{"n":19,"t":"但你們的妻子、孩子、牲畜（我知道你們有許多的牲畜）可以住在我所賜給你們的各城裏。","notes":[]},{"n":20,"t":"等到你們弟兄在約旦河那邊，也得耶和華－你們神所賜給他們的地，又使他們得享平安，與你們一樣，你們才可以回到我所賜給你們為業之地。』","notes":[]},{"n":21,"t":"那時我吩咐約書亞說：『你親眼看見了耶和華－你神向這二王所行的；耶和華也必向你所要去的各國照樣行。","notes":[]},{"n":22,"t":"你不要怕他們，因那為你爭戰的是耶和華－你的神。』」","notes":[]},{"n":23,"t":"「那時，我懇求耶和華說：","notes":[],"heads":["摩西不得進入迦南"]},{"n":24,"t":"『主耶和華啊，你已將你的大力大能顯給僕人看。在天上，在地下，有甚麼神能像你行事、像你有大能的作為呢？","notes":[]},{"n":25,"t":"求你容我過去，看約旦河那邊的美地，就是那佳美的山地和黎巴嫩。』","notes":[]},{"n":26,"t":"但耶和華因你們的緣故向我發怒，不應允我，對我說：『罷了！你不要向我再提這事。","notes":[]},{"n":27,"t":"你且上毗斯迦山頂去，向東、西、南、北舉目觀望，因為你必不能過這約旦河。","notes":[]},{"n":28,"t":"你卻要囑咐約書亞，勉勵他，使他膽壯；因為他必在這百姓前面過去，使他們承受你所要觀看之地。』","notes":[]},{"n":29,"t":"於是我們住在伯‧毗珥對面的谷中。」","notes":[]}]},"4":{"heading":"摩西勸人民遵行耶和華的律例典章","verses":[{"n":1,"t":"「以色列人哪，現在我所教訓你們的律例典章，你們要聽從遵行，好叫你們存活，得以進入耶和華－你們列祖之神所賜給你們的地，承受為業。","notes":[]},{"n":2,"t":"所吩咐你們的話，你們不可加添，也不可刪減，好叫你們遵守我所吩咐的，就是耶和華－你們神的命令。","notes":[]},{"n":3,"t":"耶和華因巴力‧毗珥的事所行的，你們親眼看見了。凡隨從巴力‧毗珥的人，耶和華－你們的神都從你們中間除滅了。","notes":[]},{"n":4,"t":"惟有你們專靠耶和華－你們神的人，今日全都存活。","notes":[]},{"n":5,"t":"我照著耶和華－我神所吩咐的將律例典章教訓你們，使你們在所要進去得為業的地上遵行。","notes":[]},{"n":6,"t":"所以你們要謹守遵行；這就是你們在萬民眼前的智慧、聰明。他們聽見這一切律例，必說：『這大國的人真是有智慧，有聰明！』","notes":[]},{"n":7,"t":"哪一大國的人有神與他們相近，像耶和華－我們的神、在我們求告他的時候與我們相近呢？","notes":[]},{"n":8,"t":"又哪一大國有這樣公義的律例典章、像我今日在你們面前所陳明的這一切律法呢？","notes":[]},{"n":9,"t":"「你只要謹慎，殷勤保守你的心靈，免得忘記你親眼所看見的事，又免得你一生、這事離開你的心；總要傳給你的子子孫孫。","notes":[]},{"n":10,"t":"你在何烈山站在耶和華－你神面前的那日，耶和華對我說：『你為我招聚百姓，我要叫他們聽見我的話，使他們存活在世的日子，可以學習敬畏我，又可以教訓兒女這樣行。』","notes":[]},{"n":11,"t":"那時你們近前來，站在山下；山上有火焰沖天，並有昏黑、密雲、幽暗。","notes":[]},{"n":12,"t":"耶和華從火焰中對你們說話，你們只聽見聲音，卻沒有看見形像。","notes":[]},{"n":13,"t":"他將所吩咐你們當守的約指示你們，就是十條誡，並將這誡寫在兩塊石版上。","notes":[]},{"n":14,"t":"那時耶和華又吩咐我將律例典章教訓你們，使你們在所要過去得為業的地上遵行。」","notes":[]},{"n":15,"t":"「所以，你們要分外謹慎；因為耶和華在何烈山、從火中對你們說話的那日，你們沒有看見甚麼形像。","notes":[],"heads":["警告人民不可拜偶像"]},{"n":16,"t":"惟恐你們敗壞自己，雕刻偶像，彷彿甚麼男像女像，","notes":[]},{"n":17,"t":"或地上走獸的像，或空中飛鳥的像，","notes":[]},{"n":18,"t":"或地上爬物的像，或地底下水中魚的像。","notes":[]},{"n":19,"t":"又恐怕你向天舉目觀看，見耶和華－你的神為天下萬民所擺列的日月星，就是天上的萬象，自己便被勾引敬拜事奉它。","notes":[]},{"n":20,"t":"耶和華將你們從埃及領出來，脫離鐵爐，要特作自己產業的子民，像今日一樣。","notes":[]},{"n":21,"t":"耶和華又因你們的緣故向我發怒，起誓必不容我過約旦河，也不容我進入耶和華－你神所賜你為業的那美地。","notes":[]},{"n":22,"t":"我只得死在這地，不能過約旦河；但你們必過去得那美地。","notes":[]},{"n":23,"t":"你們要謹慎，免得忘記耶和華－你們神與你們所立的約，為自己雕刻偶像，就是耶和華－你神所禁止你做的偶像；","notes":[]},{"n":24,"t":"因為耶和華－你的神乃是烈火，是忌邪的神。","notes":[]},{"n":25,"t":"「你們在那地住久了，生子生孫，就雕刻偶像，彷彿甚麼形像，敗壞自己，行耶和華－你神眼中看為惡的事，惹他發怒。","notes":[]},{"n":26,"t":"我今日呼天喚地向你們作見證，你們必在過約旦河得為業的地上速速滅盡！你們不能在那地上長久，必盡行除滅。","notes":[]},{"n":27,"t":"耶和華必使你們分散在萬民中；在他所領你們到的萬國裏，你們剩下的人數稀少。","notes":[]},{"n":28,"t":"在那裏，你們必事奉人手所造的神，就是用木石造成、不能看、不能聽、不能吃、不能聞的神。","notes":[]},{"n":29,"t":"但你們在那裏必尋求耶和華－你的神。你盡心盡性尋求他的時候，就必尋見。","notes":[]},{"n":30,"t":"日後你遭遇一切患難的時候，你必歸回耶和華－你的神，聽從他的話。","notes":[]},{"n":31,"t":"耶和華－你神原是有憐憫的神；他總不撇下你，不滅絕你，也不忘記他起誓與你列祖所立的約。","notes":[]},{"n":32,"t":"「你且考察在你以前的世代，自神造人在世以來，從天這邊到天那邊，曾有何民聽見神在火中說話的聲音，像你聽見還能存活呢？這樣的大事何曾有、何曾聽見呢？","notes":[],"end":33},{"n":34,"t":"神何曾從別的國中將一國的人民領出來，用試驗、神蹟、奇事、爭戰、大能的手，和伸出來的膀臂，並大可畏的事，像耶和華－你們的神在埃及，在你們眼前為你們所行的一切事呢？","notes":[]},{"n":35,"t":"這是顯給你看，要使你知道，惟有耶和華－他是神，除他以外，再無別神。","notes":[]},{"n":36,"t":"他從天上使你聽見他的聲音，為要教訓你，又在地上使你看見他的烈火，並且聽見他從火中所說的話。","notes":[]},{"n":37,"t":"因他愛你的列祖，所以揀選他們的後裔，用大能親自領你出了埃及，","notes":[]},{"n":38,"t":"要將比你強大的國民從你面前趕出，領你進去，將他們的地賜你為業，像今日一樣。","notes":[]},{"n":39,"t":"所以，今日你要知道，也要記在心上，天上地下惟有耶和華他是神，除他以外，再無別神。","notes":[]},{"n":40,"t":"我今日將他的律例誡命曉諭你，你要遵守，使你和你的子孫可以得福，並使你的日子在耶和華－你神所賜的地上得以長久。」","notes":[]},{"n":41,"t":"「那時，摩西在約旦河東，向日出之地，分定三座城，","notes":[],"heads":["設立河東的庇護城"]},{"n":42,"t":"使那素無仇恨、無心殺了人的，可以逃到這三城之中的一座城，就得存活：","notes":[]},{"n":43,"t":"為呂便人分定曠野平原的比悉；為迦得人分定基列的拉末；為瑪拿西人分定巴珊的哥蘭。」","notes":[]},{"n":44,"t":"摩西在以色列人面前所陳明的律法－","notes":[],"heads":["重申律法誡命"]},{"n":45,"t":"就是摩西在以色列人出埃及後所傳給他們的法度、律例、典章；","notes":[]},{"n":46,"t":"在約旦河東伯‧毗珥對面的谷中，在住希實本、亞摩利王西宏之地；這西宏是摩西和以色列人出埃及後所擊殺的。","notes":[]},{"n":47,"t":"他們得了他的地，又得了巴珊王噩的地，就是兩個亞摩利王，在約旦河東向日出之地。","notes":[]},{"n":48,"t":"從亞嫩谷邊的亞羅珥，直到西雲山，就是黑門山。","notes":[]},{"n":49,"t":"還有約旦河東的全亞拉巴，直到亞拉巴海，靠近毗斯迦山根。","notes":[]}]},"5":{"heading":"十誡","verses":[{"n":1,"t":"摩西將以色列眾人召了來，對他們說：「以色列人哪，我今日曉諭你們的律例典章，你們要聽，可以學習，謹守遵行。","notes":[]},{"n":2,"t":"耶和華－我們的神在何烈山與我們立約。","notes":[]},{"n":3,"t":"這約不是與我們列祖立的，乃是與我們今日在這裏存活之人立的。","notes":[]},{"n":4,"t":"耶和華在山上，從火中，面對面與你們說話－","notes":[]},{"n":5,"t":"那時我站在耶和華和你們中間，要將耶和華的話傳給你們；因為你們懼怕那火，沒有上山－說：","notes":[]},{"n":6,"t":"「『我是耶和華－你的神，曾將你從埃及地為奴之家領出來。","notes":[]},{"n":7,"t":"「『除了我以外，你不可有別的神。","notes":[]},{"n":8,"t":"「『不可為自己雕刻偶像，也不可做甚麼形像，彷彿上天、下地和地底下、水中的百物。","notes":[]},{"n":9,"t":"不可跪拜那些像，也不可事奉它，因為我耶和華－你的神是忌邪的神。恨我的，我必追討他的罪，自父及子，直到三、四代；","notes":[]},{"n":10,"t":"愛我、守我誡命的，我必向他們發慈愛，直到千代。","notes":[]},{"n":11,"t":"「『不可妄稱耶和華－你神的名；因為妄稱耶和華名的，耶和華必不以他為無罪。","notes":[]},{"n":12,"t":"「『當照耶和華－你神所吩咐的守安息日為聖日。","notes":[]},{"n":13,"t":"六日要勞碌做你一切的工，","notes":[]},{"n":14,"t":"但第七日是向耶和華－你神當守的安息日。這一日，你和你的兒女、僕婢、牛、驢、牲畜，並在你城裏寄居的客旅，無論何工都不可做，使你的僕婢可以和你一樣安息。","notes":[]},{"n":15,"t":"你也要記念你在埃及地作過奴僕；耶和華－你神用大能的手和伸出來的膀臂將你從那裏領出來。因此，耶和華－你的神吩咐你守安息日。","notes":[]},{"n":16,"t":"「『當照耶和華－你神所吩咐的孝敬父母，使你得福，並使你的日子在耶和華－你神所賜你的地上得以長久。","notes":[]},{"n":17,"t":"「『不可殺人。","notes":[]},{"n":18,"t":"「『不可姦淫。","notes":[]},{"n":19,"t":"「『不可偷盜。","notes":[]},{"n":20,"t":"「『不可作假見證陷害人。","notes":[]},{"n":21,"t":"「『不可貪戀人的妻子；也不可貪圖人的房屋、田地、僕婢、牛、驢，並他一切所有的。』","notes":[]},{"n":22,"t":"「這些話是耶和華在山上，從火中、雲中、幽暗中，大聲曉諭你們全會眾的；此外並沒有添別的話。他就把這話寫在兩塊石版上，交給我了。」","notes":[]},{"n":23,"t":"「那時，火焰燒山，你們聽見從黑暗中出來的聲音；你們支派中所有的首領和長老都來就近我，","notes":[],"heads":["百姓看見火焰燒山而懼怕"]},{"n":24,"t":"說：『看哪，耶和華－我們神將他的榮光和他的大能顯給我們看，我們又聽見他的聲音從火中出來。今日我們得見神與人說話，人還存活。","notes":[]},{"n":25,"t":"現在這大火將要燒滅我們，我們何必冒死呢？若再聽見耶和華－我們神的聲音就必死亡。","notes":[]},{"n":26,"t":"凡屬血氣的，曾有何人聽見永生神的聲音從火中出來，像我們聽見還能存活呢？","notes":[]},{"n":27,"t":"求你近前去，聽耶和華－我們神所要說的一切話，將他對你說的話都傳給我們，我們就聽從遵行。』","notes":[]},{"n":28,"t":"「你們對我說的話，耶和華都聽見了。耶和華對我說：『這百姓的話，我聽見了；他們所說的都是。","notes":[]},{"n":29,"t":"惟願他們存這樣的心敬畏我，常遵守我的一切誡命，使他們和他們的子孫永遠得福。","notes":[]},{"n":30,"t":"你去對他們說：你們回帳棚去吧！","notes":[]},{"n":31,"t":"至於你，可以站在我這裏，我要將一切誡命、律例、典章傳給你；你要教訓他們，使他們在我賜他們為業的地上遵行。』","notes":[]},{"n":32,"t":"所以，你們要照耶和華－你們神所吩咐的謹守遵行，不可偏離左右。","notes":[]},{"n":33,"t":"耶和華－你們神所吩咐你們行的，你們都要去行，使你們可以存活得福，並使你們的日子在所要承受的地上得以長久。」","notes":[]}]},"6":{"heading":"最大的誡命","verses":[{"n":1,"t":"「這是耶和華－你們神所吩咐教訓你們的誡命、律例、典章，使你們在所要過去得為業的地上遵行，","notes":[]},{"n":2,"t":"好叫你和你子子孫孫一生敬畏耶和華－你的神，謹守他的一切律例誡命，就是我所吩咐你的，使你的日子得以長久。","notes":[]},{"n":3,"t":"以色列啊，你要聽，要謹守遵行，使你可以在那流奶與蜜之地得以享福，人數極其增多，正如耶和華－你列祖的神所應許你的。","notes":[]},{"n":4,"t":"「以色列啊，你要聽！耶和華－我們神是獨一的主。","notes":[]},{"n":5,"t":"你要盡心、盡性、盡力愛耶和華－你的神。","notes":[]},{"n":6,"t":"我今日所吩咐你的話都要記在心上，","notes":[]},{"n":7,"t":"也要殷勤教訓你的兒女。無論你坐在家裏，行在路上，躺下，起來，都要談論。","notes":[]},{"n":8,"t":"也要繫在手上為記號，戴在額上為經文；","notes":[]},{"n":9,"t":"又要寫在你房屋的門框上，並你的城門上。」","notes":[]},{"n":10,"t":"「耶和華－你的神領你進他向你列祖亞伯拉罕、以撒、雅各起誓應許給你的地。那裏有城邑，又大又美，非你所建造的；","notes":[],"heads":["警告人民不可背逆神"]},{"n":11,"t":"有房屋，裝滿各樣美物，非你所裝滿的；有鑿成的水井，非你所鑿成的；還有葡萄園、橄欖園，非你所栽種的；你吃了而且飽足。","notes":[]},{"n":12,"t":"那時你要謹慎，免得你忘記將你從埃及地、為奴之家領出來的耶和華。","notes":[]},{"n":13,"t":"你要敬畏耶和華－你的神，事奉他，指著他的名起誓。","notes":[]},{"n":14,"t":"不可隨從別神，就是你們四圍國民的神；","notes":[]},{"n":15,"t":"因為在你們中間的耶和華－你神是忌邪的神，惟恐耶和華－你神的怒氣向你發作，就把你從地上除滅。","notes":[]},{"n":16,"t":"「你們不可試探耶和華－你們的神，像你們在瑪撒那樣試探他。","notes":[]},{"n":17,"t":"要留意遵守耶和華－你們神所吩咐的誡命、法度、律例。","notes":[]},{"n":18,"t":"耶和華眼中看為正、看為善的，你都要遵行，使你可以享福，並可以進去得耶和華向你列祖起誓應許的那美地，","notes":[]},{"n":19,"t":"照耶和華所說的，從你面前攆出你的一切仇敵。","notes":[]},{"n":20,"t":"「日後，你的兒子問你說：『耶和華－我們神吩咐你們的這些法度、律例、典章是甚麼意思呢？』","notes":[]},{"n":21,"t":"你就告訴你的兒子說：『我們在埃及作過法老的奴僕；耶和華用大能的手將我們從埃及領出來，","notes":[]},{"n":22,"t":"在我們眼前，將重大可怕的神蹟奇事施行在埃及地和法老並他全家的身上，","notes":[]},{"n":23,"t":"將我們從那裏領出來，要領我們進入他向我們列祖起誓應許之地，把這地賜給我們。","notes":[]},{"n":24,"t":"耶和華又吩咐我們遵行這一切律例，要敬畏耶和華－我們的神，使我們常得好處，蒙他保全我們的生命，像今日一樣。","notes":[]},{"n":25,"t":"我們若照耶和華－我們神所吩咐的一切誡命謹守遵行，這就是我們的義了。』」","notes":[]}]},"7":{"heading":"耶和華的子民","verses":[{"n":1,"t":"「耶和華－你神領你進入要得為業之地，從你面前趕出許多國民，就是赫人、革迦撒人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人，共七國的民，都比你強大。","notes":[]},{"n":2,"t":"耶和華－你神將他們交給你擊殺，那時你要把他們滅絕淨盡，不可與他們立約，也不可憐恤他們。","notes":[]},{"n":3,"t":"不可與他們結親。不可將你的女兒嫁他們的兒子，也不可叫你的兒子娶他們的女兒；","notes":[]},{"n":4,"t":"因為他必使你兒子轉離不跟從主，去事奉別神，以致耶和華的怒氣向你們發作，就速速地將你們滅絕。","notes":[]},{"n":5,"t":"你們卻要這樣待他們：拆毀他們的祭壇，打碎他們的柱像，砍下他們的木偶，用火焚燒他們雕刻的偶像。","notes":[]},{"n":6,"t":"因為你歸耶和華－你神為聖潔的民；耶和華－你神從地上的萬民中揀選你，特作自己的子民。","notes":[]},{"n":7,"t":"「耶和華專愛你們，揀選你們，並非因你們的人數多於別民，原來你們的人數在萬民中是最少的。","notes":[]},{"n":8,"t":"只因耶和華愛你們，又因要守他向你們列祖所起的誓，就用大能的手領你們出來，從為奴之家救贖你們脫離埃及王法老的手。","notes":[]},{"n":9,"t":"所以，你要知道耶和華－你的神，他是神，是信實的神；向愛他、守他誡命的人守約，施慈愛，直到千代；","notes":[]},{"n":10,"t":"向恨他的人當面報應他們，將他們滅絕。凡恨他的人必報應他們，決不遲延。","notes":[]},{"n":11,"t":"所以，你要謹守遵行我今日所吩咐你的誡命、律例、典章。」","notes":[]},{"n":12,"t":"「你們果然聽從這些典章，謹守遵行，耶和華－你神就必照他向你列祖所起的誓守約，施慈愛。","notes":[],"heads":["遵行誡命必蒙福"]},{"n":13,"t":"他必愛你，賜福與你，使你人數增多，也必在他向你列祖起誓應許給你的地上賜福與你身所生的，地所產的，並你的五穀、新酒，和油，以及牛犢、羊羔。","notes":[]},{"n":14,"t":"你必蒙福勝過萬民；你們的男女沒有不能生養的，牲畜也沒有不能生育的。","notes":[]},{"n":15,"t":"耶和華必使一切的病症離開你；你所知道埃及各樣的惡疾，他不加在你身上，只加在一切恨你的人身上。","notes":[]},{"n":16,"t":"耶和華－你神所要交給你的一切人民，你要將他們除滅；你眼不可顧惜他們。你也不可事奉他們的神，因這必成為你的網羅。","notes":[]},{"n":17,"t":"「你若心裏說，這些國的民比我更多，我怎能趕出他們呢？","notes":[]},{"n":18,"t":"你不要懼怕他們，要牢牢記念耶和華－你神向法老和埃及全地所行的事，","notes":[]},{"n":19,"t":"就是你親眼所看見的大試驗、神蹟、奇事，和大能的手，並伸出來的膀臂，都是耶和華－你神領你出來所用的。耶和華－你神必照樣待你所懼怕的一切人民。","notes":[]},{"n":20,"t":"並且耶和華－你神必打發黃蜂飛到他們中間，直到那剩下而藏躲的人從你面前滅亡。","notes":[]},{"n":21,"t":"你不要因他們驚恐，因為耶和華－你神在你們中間是大而可畏的神。","notes":[]},{"n":22,"t":"耶和華－你神必將這些國的民從你面前漸漸趕出；你不可把他們速速滅盡，恐怕野地的獸多起來害你。","notes":[]},{"n":23,"t":"耶和華－你神必將他們交給你，大大地擾亂他們，直到他們滅絕了；","notes":[]},{"n":24,"t":"又要將他們的君王交在你手中，你就使他們的名從天下消滅。必無一人能在你面前站立得住，直到你將他們滅絕了。","notes":[]},{"n":25,"t":"他們雕刻的神像，你們要用火焚燒；其上的金銀，你不可貪圖，也不可收取，免得你因此陷入網羅；這原是耶和華－你神所憎惡的。","notes":[]},{"n":26,"t":"可憎的物，你不可帶進家去；不然，你就成了當毀滅的，與那物一樣。你要十分厭惡，十分憎嫌，因為這是當毀滅的物。」","notes":[]}]},"8":{"heading":"將得美地","verses":[{"n":1,"t":"「我今日所吩咐的一切誡命，你們要謹守遵行，好叫你們存活，人數增多，且進去得耶和華向你們列祖起誓應許的那地。","notes":[]},{"n":2,"t":"你也要記念耶和華－你的神在曠野引導你這四十年，是要苦煉你，試驗你，要知道你心內如何，肯守他的誡命不肯。","notes":[]},{"n":3,"t":"他苦煉你，任你飢餓，將你和你列祖所不認識的嗎哪賜給你吃，使你知道，人活著不是單靠食物，乃是靠耶和華口裏所出的一切話。","notes":[]},{"n":4,"t":"這四十年，你的衣服沒有穿破，你的腳也沒有腫。","notes":[]},{"n":5,"t":"你當心裏思想，耶和華－你神管教你，好像人管教兒子一樣。","notes":[]},{"n":6,"t":"你要謹守耶和華－你神的誡命，遵行他的道，敬畏他。","notes":[]},{"n":7,"t":"因為耶和華－你神領你進入美地，那地有河，有泉，有源，從山谷中流出水來。","notes":[]},{"n":8,"t":"那地有小麥、大麥、葡萄樹、無花果樹、石榴樹、橄欖樹，和蜜。","notes":[]},{"n":9,"t":"你在那地不缺食物，一無所缺。那地的石頭是鐵，山內可以挖銅。","notes":[]},{"n":10,"t":"你吃得飽足，就要稱頌耶和華－你的神，因他將那美地賜給你了。」","notes":[]},{"n":11,"t":"「你要謹慎，免得忘記耶和華－你的神，不守他的誡命、典章、律例，就是我今日所吩咐你的；","notes":[],"heads":["警告百姓不可忘記主"]},{"n":12,"t":"恐怕你吃得飽足，建造美好的房屋居住，","notes":[]},{"n":13,"t":"你的牛羊加多，你的金銀增添，並你所有的全都加增，","notes":[]},{"n":14,"t":"你就心高氣傲，忘記耶和華－你的神，就是將你從埃及地為奴之家領出來的，","notes":[]},{"n":15,"t":"引你經過那大而可怕的曠野，那裏有火蛇、蠍子、乾旱無水之地。他曾為你使水從堅硬的磐石中流出來，","notes":[]},{"n":16,"t":"又在曠野將你列祖所不認識的嗎哪賜給你吃，是要苦煉你，試驗你，叫你終久享福；","notes":[]},{"n":17,"t":"恐怕你心裏說：『這貨財是我力量、我能力得來的。』","notes":[]},{"n":18,"t":"你要記念耶和華－你的神，因為得貨財的力量是他給你的，為要堅定他向你列祖起誓所立的約，像今日一樣。","notes":[]},{"n":19,"t":"你若忘記耶和華－你的神，隨從別神，事奉敬拜，你們必定滅亡；這是我今日警戒你們的。","notes":[]},{"n":20,"t":"耶和華在你們面前怎樣使列國的民滅亡，你們也必照樣滅亡，因為你們不聽從耶和華－你們神的話。」","notes":[]}]},"9":{"heading":"百姓悖逆","verses":[{"n":1,"t":"「以色列啊，你當聽！你今日要過約旦河，進去趕出比你強大的國民，得著廣大堅固、高得頂天的城邑。","notes":[]},{"n":2,"t":"那民是亞衲族的人，又大又高，是你所知道的；也曾聽見有人指著他們說：『誰能在亞衲族人面前站立得住呢？』","notes":[]},{"n":3,"t":"你今日當知道，耶和華－你的神在你前面過去，如同烈火，要滅絕他們，將他們制伏在你面前。這樣，你就要照耶和華所說的趕出他們，使他們速速滅亡。","notes":[]},{"n":4,"t":"「耶和華－你的神將這些國民從你面前攆出以後，你心裏不可說：『耶和華將我領進來得這地是因我的義。』其實，耶和華將他們從你面前趕出去是因他們的惡。","notes":[]},{"n":5,"t":"你進去得他們的地，並不是因你的義，也不是因你心裏正直，乃是因這些國民的惡，耶和華－你的神將他們從你面前趕出去，又因耶和華要堅定他向你列祖亞伯拉罕、以撒、雅各起誓所應許的話。","notes":[]},{"n":6,"t":"「你當知道，耶和華－你神將這美地賜你為業，並不是因你的義；你本是硬著頸項的百姓。","notes":[]},{"n":7,"t":"你當記念不忘，你在曠野怎樣惹耶和華－你神發怒。自從你出了埃及地的那日，直到你們來到這地方，你們時常悖逆耶和華。","notes":[]},{"n":8,"t":"你們在何烈山又惹耶和華發怒；他惱怒你們，要滅絕你們。","notes":[]},{"n":9,"t":"我上了山，要領受兩塊石版，就是耶和華與你們立約的版。那時我在山上住了四十晝夜，沒有吃飯，也沒有喝水。","notes":[]},{"n":10,"t":"耶和華把那兩塊石版交給我，是神用指頭寫的。版上所寫的是照耶和華在大會的日子、在山上、從火中對你們所說的一切話。","notes":[]},{"n":11,"t":"過了四十晝夜，耶和華把那兩塊石版，就是約版，交給我。","notes":[]},{"n":12,"t":"對我說：『你起來，趕快下去！因為你從埃及領出來的百姓已經敗壞了自己；他們快快地偏離了我所吩咐的道，為自己鑄成了偶像。』","notes":[]},{"n":13,"t":"「耶和華又對我說：『我看這百姓是硬著頸項的百姓。","notes":[]},{"n":14,"t":"你且由著我，我要滅絕他們，將他們的名從天下塗抹，使你的後裔比他們成為更大更強的國。』","notes":[]},{"n":15,"t":"於是我轉身下山，山被火燒著，兩塊約版在我兩手之中。","notes":[]},{"n":16,"t":"我一看見你們得罪了耶和華－你們的神，鑄成了牛犢，快快地偏離了耶和華所吩咐你們的道，","notes":[]},{"n":17,"t":"我就把那兩塊版從我手中扔下去，在你們眼前摔碎了。","notes":[]},{"n":18,"t":"因你們所犯的一切罪，行了耶和華眼中看為惡的事，惹他發怒，我就像從前俯伏在耶和華面前四十晝夜，沒有吃飯，也沒有喝水。","notes":[]},{"n":19,"t":"我因耶和華向你們大發烈怒，要滅絕你們，就甚害怕；但那次耶和華又應允了我。","notes":[]},{"n":20,"t":"耶和華也向亞倫甚是發怒，要滅絕他；那時我又為亞倫祈禱。","notes":[]},{"n":21,"t":"我把那叫你們犯罪所鑄的牛犢用火焚燒，又搗碎磨得很細，以致細如灰塵，我就把這灰塵撒在從山上流下來的溪水中。","notes":[]},{"n":22,"t":"「你們在他備拉、瑪撒、基博羅‧哈他瓦又惹耶和華發怒。","notes":[]},{"n":23,"t":"耶和華打發你們離開加低斯‧巴尼亞，說：『你們上去得我所賜給你們的地。』那時你們違背了耶和華－你們神的命令，不信服他，不聽從他的話。","notes":[]},{"n":24,"t":"自從我認識你們以來，你們常常悖逆耶和華。","notes":[]},{"n":25,"t":"「我因耶和華說要滅絕你們，就在耶和華面前照舊俯伏四十晝夜。","notes":[]},{"n":26,"t":"我祈禱耶和華說：『主耶和華啊，求你不要滅絕你的百姓。他們是你的產業，是你用大力救贖的，用大能從埃及領出來的。","notes":[]},{"n":27,"t":"求你記念你的僕人亞伯拉罕、以撒、雅各，不要想念這百姓的頑梗、邪惡、罪過，","notes":[]},{"n":28,"t":"免得你領我們出來的那地之人說，耶和華因為不能將這百姓領進他所應許之地，又因恨他們，所以領他們出去，要在曠野殺他們。","notes":[]},{"n":29,"t":"其實他們是你的百姓，你的產業，是你用大能和伸出來的膀臂領出來的。』」","notes":[]}]},"10":{"heading":"摩西重新接受十誡","verses":[{"n":1,"t":"「那時，耶和華吩咐我說：『你要鑿出兩塊石版，和先前的一樣，上山到我這裏來，又要做一木櫃。","notes":[]},{"n":2,"t":"你先前摔碎的那版，其上的字我要寫在這版上；你要將這版放在櫃中。』","notes":[]},{"n":3,"t":"於是我用皂莢木做了一櫃，又鑿出兩塊石版，和先前的一樣，手裏拿這兩塊版上山去了。","notes":[]},{"n":4,"t":"耶和華將那大會之日、在山上從火中所傳與你們的十條誡，照先前所寫的，寫在這版上，將版交給我了。","notes":[]},{"n":5,"t":"我轉身下山，將這版放在我所做的櫃中，現今還在那裏，正如耶和華所吩咐我的。」（","notes":[]},{"n":6,"t":"以色列人從比羅比尼‧亞干起行，到了摩西拉。亞倫死在那裏，就葬在那裏。他兒子以利亞撒接續他供祭司的職分。","notes":["或譯：亞干井"]},{"n":7,"t":"他們從那裏起行，到了谷歌大，又從谷歌大到了有溪水之地的約巴他。","notes":[]},{"n":8,"t":"那時，耶和華將利未支派分別出來，抬耶和華的約櫃，又侍立在耶和華面前事奉他，奉他的名祝福，直到今日。","notes":[]},{"n":9,"t":"所以利未人在他弟兄中無分無業，耶和華是他的產業，正如耶和華－你神所應許他的。）","notes":[]},{"n":10,"t":"「我又像從前在山上住了四十晝夜。那次耶和華也應允我，不忍將你滅絕。","notes":[]},{"n":11,"t":"耶和華吩咐我說：『你起來引導這百姓，使他們進去得我向他們列祖起誓應許所賜之地。』」","notes":[]},{"n":12,"t":"「以色列啊，現在耶和華－你神向你所要的是甚麼呢？只要你敬畏耶和華－你的神，遵行他的道，愛他，盡心盡性事奉他，","notes":[],"heads":["神的要求"]},{"n":13,"t":"遵守他的誡命律例，就是我今日所吩咐你的，為要叫你得福。","notes":[]},{"n":14,"t":"看哪，天和天上的天，地和地上所有的，都屬耶和華－你的神。","notes":[]},{"n":15,"t":"耶和華但喜悅你的列祖，愛他們，從萬民中揀選他們的後裔，就是你們，像今日一樣。","notes":[]},{"n":16,"t":"所以你們要將心裏的污穢除掉，不可再硬著頸項。","notes":[]},{"n":17,"t":"因為耶和華－你們的神－他是萬神之神，萬主之主，至大的神，大有能力，大而可畏，不以貌取人，也不受賄賂。","notes":[]},{"n":18,"t":"他為孤兒寡婦伸冤，又憐愛寄居的，賜給他衣食。","notes":[]},{"n":19,"t":"所以你們要憐愛寄居的，因為你們在埃及地也作過寄居的。","notes":[]},{"n":20,"t":"你要敬畏耶和華－你的神，事奉他，專靠他，也要指著他的名起誓。","notes":[]},{"n":21,"t":"他是你所讚美的，是你的神，為你做了那大而可畏的事，是你親眼所看見的。","notes":[]},{"n":22,"t":"你的列祖七十人下埃及；現在耶和華－你的神使你如同天上的星那樣多。」","notes":[]}]},"11":{"heading":"主的偉大","verses":[{"n":1,"t":"「你要愛耶和華－你的神，常守他的吩咐、律例、典章、誡命。","notes":[]},{"n":2,"t":"你們今日當知道，我本不是和你們的兒女說話；因為他們不知道，也沒有看見耶和華－你們神的管教、威嚴、大能的手，和伸出來的膀臂，","notes":[]},{"n":3,"t":"並他在埃及中向埃及王法老和其全地所行的神蹟奇事；","notes":[]},{"n":4,"t":"也沒有看見他怎樣待埃及的軍兵、車馬，他們追趕你們的時候，耶和華怎樣使紅海的水淹沒他們，將他們滅絕，直到今日，","notes":[]},{"n":5,"t":"並他在曠野怎樣待你們，以致你們來到這地方；","notes":[]},{"n":6,"t":"也沒有看見他怎樣待呂便子孫以利押的兒子大坍、亞比蘭，地怎樣在以色列人中間開口，吞了他們和他們的家眷，並帳棚與跟他們的一切活物。","notes":[]},{"n":7,"t":"惟有你們親眼看見耶和華所做的一切大事。」","notes":[]},{"n":8,"t":"「所以，你們要守我今日所吩咐的一切誡命，使你們膽壯，能以進去，得你們所要得的那地，","notes":[],"heads":["應許之地的福澤"]},{"n":9,"t":"並使你們的日子在耶和華向你們列祖起誓、應許給他們和他們後裔的地上得以長久；那是流奶與蜜之地。","notes":[]},{"n":10,"t":"你要進去得為業的那地，本不像你出來的埃及地。你在那裏撒種，用腳澆灌，像澆灌菜園一樣。","notes":[]},{"n":11,"t":"你們要過去得為業的那地乃是有山有谷、雨水滋潤之地，","notes":[]},{"n":12,"t":"是耶和華－你神所眷顧的；從歲首到年終，耶和華－你神的眼目時常看顧那地。","notes":[]},{"n":13,"t":"「你們若留意聽從我今日所吩咐的誡命，愛耶和華－你們的神，盡心盡性事奉他，","notes":[]},{"n":14,"t":"他必按時降秋雨春雨在你們的地上，使你們可以收藏五穀、新酒，和油，","notes":["原文是我"]},{"n":15,"t":"也必使你吃得飽足，並使田野為你的牲畜長草。","notes":[]},{"n":16,"t":"你們要謹慎，免得心中受迷惑，就偏離正路，去事奉敬拜別神。","notes":[]},{"n":17,"t":"耶和華的怒氣向你們發作，就使天閉塞不下雨，地也不出產，使你們在耶和華所賜給你們的美地上速速滅亡。","notes":[]},{"n":18,"t":"「你們要將我這話存在心內，留在意中，繫在手上為記號，戴在額上為經文；","notes":[]},{"n":19,"t":"也要教訓你們的兒女，無論坐在家裏，行在路上，躺下，起來，都要談論；","notes":[]},{"n":20,"t":"又要寫在房屋的門框上，並城門上，","notes":[]},{"n":21,"t":"使你們和你們子孫的日子在耶和華向你們列祖起誓、應許給他們的地上得以增多，如天覆地的日子那樣多。","notes":[]},{"n":22,"t":"你們若留意謹守遵行我所吩咐這一切的誡命，愛耶和華－你們的神，行他的道，專靠他，","notes":[]},{"n":23,"t":"他必從你們面前趕出這一切國民，就是比你們更大更強的國民，你們也要得他們的地。","notes":[]},{"n":24,"t":"凡你們腳掌所踏之地都必歸你們；從曠野和黎巴嫩，並幼發拉底大河，直到西海，都要作你們的境界。","notes":[]},{"n":25,"t":"必無一人能在你們面前站立得住；耶和華－你們的神必照他所說的，使懼怕驚恐臨到你們所踏之地的居民。","notes":[]},{"n":26,"t":"「看哪，我今日將祝福與咒詛的話都陳明在你們面前。","notes":[]},{"n":27,"t":"你們若聽從耶和華－你們神的誡命，就是我今日所吩咐你們的，就必蒙福。","notes":[]},{"n":28,"t":"你們若不聽從耶和華－你們神的誡命，偏離我今日所吩咐你們的道，去事奉你們素來所不認識的別神，就必受禍。","notes":[]},{"n":29,"t":"及至耶和華－你的神領你進入要去得為業的那地，你就要將祝福的話陳明在基利心山上，將咒詛的話陳明在以巴路山上。","notes":[]},{"n":30,"t":"這二山豈不是在約旦河那邊，日落之處，在住亞拉巴的迦南人之地與吉甲相對，靠近摩利橡樹嗎？","notes":[]},{"n":31,"t":"你們要過約旦河，進去得耶和華－你們神所賜你們為業之地，在那地居住。","notes":[]},{"n":32,"t":"你們要謹守遵行我今日在你們面前所陳明的一切律例典章。」","notes":[]}]},"12":{"heading":"惟一的敬拜場所","verses":[{"n":1,"t":"「你們存活於世的日子，在耶和華－你們列祖的神所賜你們為業的地上，要謹守遵行的律例典章乃是這些：","notes":[]},{"n":2,"t":"你們要將所趕出的國民事奉神的各地方，無論是在高山，在小山，在各青翠樹下，都毀壞了；","notes":[]},{"n":3,"t":"也要拆毀他們的祭壇，打碎他們的柱像，用火焚燒他們的木偶，砍下他們雕刻的神像，並將其名從那地方除滅。","notes":[]},{"n":4,"t":"你們不可照他們那樣事奉耶和華－你們的神。","notes":[]},{"n":5,"t":"但耶和華－你們的神從你們各支派中選擇何處為立他名的居所，你們就當往那裏去求問，","notes":[]},{"n":6,"t":"將你們的燔祭、平安祭、十分取一之物，和手中的舉祭，並還願祭、甘心祭，以及牛群羊群中頭生的，都奉到那裏。","notes":[]},{"n":7,"t":"在那裏，耶和華－你們神的面前，你們和你們的家屬都可以吃，並且因你手所辦的一切事蒙耶和華－你的神賜福，就都歡樂。","notes":[]},{"n":8,"t":"我們今日在這裏所行的是各人行自己眼中看為正的事，你們將來不可這樣行；","notes":[]},{"n":9,"t":"因為你們還沒有到耶和華－你神所賜你的安息地，所給你的產業。","notes":[]},{"n":10,"t":"但你們過了約旦河，得以住在耶和華－你們神使你們承受為業之地，又使你們太平，不被四圍的一切仇敵擾亂，安然居住。","notes":[]},{"n":11,"t":"那時要將我所吩咐你們的燔祭、平安祭、十分取一之物，和手中的舉祭，並向耶和華許願獻的一切美祭，都奉到耶和華－你們神所選擇要立為他名的居所。","notes":[]},{"n":12,"t":"你們和兒女、僕婢，並住在你們城裏無分無業的利未人，都要在耶和華－你們的神面前歡樂。","notes":[]},{"n":13,"t":"你要謹慎，不可在你所看中的各處獻燔祭。","notes":[]},{"n":14,"t":"惟獨耶和華從你那一支派中所選擇的地方，你就要在那裏獻燔祭，行我一切所吩咐你的。","notes":[]},{"n":15,"t":"「然而，在你各城裏都可以照耶和華－你神所賜你的福分，隨心所欲宰牲吃肉；無論潔淨人不潔淨人都可以吃，就如吃羚羊與鹿一般。","notes":[]},{"n":16,"t":"只是不可吃血，要倒在地上，如同倒水一樣。","notes":[]},{"n":17,"t":"你的五穀、新酒，和油的十分之一，或是牛群羊群中頭生的，或是你許願獻的，甘心獻的，或是手中的舉祭，都不可在你城裏吃。","notes":[]},{"n":18,"t":"但要在耶和華－你的神面前吃，在耶和華－你神所要選擇的地方，你和兒女、僕婢，並住在你城裏的利未人，都可以吃；也要因你手所辦的，在耶和華－你神面前歡樂。","notes":[]},{"n":19,"t":"你要謹慎，在你所住的地方永不可丟棄利未人。","notes":[]},{"n":20,"t":"「耶和華－你的神照他所應許擴張你境界的時候，你心裏想要吃肉，說：『我要吃肉』，就可以隨心所欲地吃肉。","notes":[]},{"n":21,"t":"耶和華－你神所選擇要立他名的地方若離你太遠，就可以照我所吩咐的，將耶和華賜給你的牛羊取些宰了，可以隨心所欲在你城裏吃。","notes":[]},{"n":22,"t":"你吃那肉，要像吃羚羊與鹿一般；無論潔淨人不潔淨人都可以吃。","notes":[]},{"n":23,"t":"只是你要心意堅定，不可吃血，因為血是生命；不可將血與肉同吃。","notes":["原文是生命"]},{"n":24,"t":"不可吃血，要倒在地上，如同倒水一樣。","notes":[]},{"n":25,"t":"不可吃血。這樣，你行耶和華眼中看為正的事，你和你的子孫就可以得福。","notes":[]},{"n":26,"t":"只是你分別為聖的物和你的還願祭要奉到耶和華所選擇的地方去。","notes":[]},{"n":27,"t":"你的燔祭，連肉帶血，都要獻在耶和華－你神的壇上。平安祭的血要倒在耶和華－你神的壇上；平安祭的肉，你自己可以吃。","notes":[]},{"n":28,"t":"你要謹守聽從我所吩咐的一切話，行耶和華－你神眼中看為善，看為正的事。這樣，你和你的子孫就可以永遠享福。」","notes":[]},{"n":29,"t":"「耶和華－你神將你要去趕出的國民從你面前剪除，你得了他們的地居住，","notes":[],"heads":["警告不可拜偶像"]},{"n":30,"t":"那時就要謹慎，不可在他們除滅之後隨從他們的惡俗，陷入網羅，也不可訪問他們的神說：『這些國民怎樣事奉他們的神，我也要照樣行。』","notes":[]},{"n":31,"t":"你不可向耶和華－你的神這樣行，因為他們向他們的神行了耶和華所憎嫌所恨惡的一切事，甚至將自己的兒女用火焚燒，獻與他們的神。","notes":[]},{"n":32,"t":"凡我所吩咐的，你們都要謹守遵行，不可加添，也不可刪減。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"「你們中間若有先知或是做夢的起來，向你顯個神蹟奇事，","notes":[]},{"n":2,"t":"對你說：『我們去隨從你素來所不認識的別神，事奉它吧。』他所顯的神蹟奇事雖有應驗，","notes":[]},{"n":3,"t":"你也不可聽那先知或是那做夢之人的話；因為這是耶和華－你們的神試驗你們，要知道你們是盡心盡性愛耶和華－你們的神不是。","notes":[]},{"n":4,"t":"你們要順從耶和華－你們的神，敬畏他，謹守他的誡命，聽從他的話，事奉他，專靠他。","notes":[]},{"n":5,"t":"那先知或是那做夢的既用言語叛逆那領你們出埃及地、救贖你脫離為奴之家的耶和華－你們的神，要勾引你離開耶和華－你神所吩咐你行的道，你便要將他治死。這樣，就把那惡從你們中間除掉。","notes":[]},{"n":6,"t":"「你的同胞弟兄，或是你的兒女，或是你懷中的妻，或是如同你性命的朋友，若暗中引誘你，說：『我們不如去事奉你和你列祖素來所不認識的別神－","notes":[]},{"n":7,"t":"是你四圍列國的神。』無論是離你近，離你遠，從地這邊到地那邊的神，","notes":[]},{"n":8,"t":"你不可依從他，也不可聽從他，眼不可顧惜他。你不可憐恤他，也不可遮庇他，","notes":[]},{"n":9,"t":"總要殺他；你先下手，然後眾民也下手，將他治死。","notes":[]},{"n":10,"t":"要用石頭打死他，因為他想要勾引你離開那領你出埃及地為奴之家的耶和華－你的神。","notes":[]},{"n":11,"t":"以色列眾人都要聽見害怕，就不敢在你們中間再行這樣的惡了。","notes":[]},{"n":12,"t":"「在耶和華－你神所賜你居住的各城中，你若聽人說，有些匪類從你們中間的一座城出來勾引本城的居民，說：『我們不如去事奉你們素來所不認識的別神』；","notes":[],"end":13},{"n":14,"t":"你就要探聽，查究，細細地訪問，果然是真，準有這可憎惡的事行在你們中間，","notes":[]},{"n":15,"t":"你必要用刀殺那城裏的居民，把城裏所有的，連牲畜，都用刀殺盡。","notes":[]},{"n":16,"t":"你從那城裏所奪的財物都要堆積在街市上，用火將城和其內所奪的財物都在耶和華－你神面前燒盡；那城就永為荒堆，不可再建造。","notes":[]},{"n":17,"t":"那當毀滅的物連一點都不可粘你的手。你要聽從耶和華－你神的話，遵守我今日所吩咐你的一切誡命，行耶和華－你神眼中看為正的事，耶和華就必轉意，不發烈怒，恩待你，憐恤你，照他向你列祖所起的誓使你人數增多。」","notes":[],"end":18}]},"14":{"heading":"舉哀時的禁例","verses":[{"n":1,"t":"「你們是耶和華－你們神的兒女。不可為死人用刀劃身，也不可將額上剃光；","notes":[]},{"n":2,"t":"因為你歸耶和華－你神為聖潔的民，耶和華從地上的萬民中揀選你特作自己的子民。」","notes":[]},{"n":3,"t":"「凡可憎的物都不可吃。","notes":[],"heads":["潔淨和不潔淨的動物"]},{"n":4,"t":"可吃的牲畜就是牛、綿羊、山羊、","notes":[]},{"n":5,"t":"鹿、羚羊、麅子、野山羊、麋鹿、黃羊、青羊。","notes":[]},{"n":6,"t":"凡分蹄成為兩瓣又倒嚼的走獸，你們都可以吃。","notes":[]},{"n":7,"t":"但那些倒嚼或是分蹄之中不可吃的乃是駱駝、兔子、沙番－因為是倒嚼不分蹄，就與你們不潔淨；","notes":[]},{"n":8,"t":"豬－因為是分蹄卻不倒嚼，就與你們不潔淨。這些獸的肉，你們不可吃，死的也不可摸。","notes":[]},{"n":9,"t":"「水中可吃的乃是這些：凡有翅有鱗的都可以吃；","notes":[]},{"n":10,"t":"凡無翅無鱗的都不可吃，是與你們不潔淨。","notes":[]},{"n":11,"t":"「凡潔淨的鳥，你們都可以吃。","notes":[]},{"n":12,"t":"不可吃的乃是鵰、狗頭鵰、紅頭鵰、","notes":[]},{"n":13,"t":"鸇、小鷹、鷂鷹與其類，","notes":[]},{"n":14,"t":"烏鴉與其類，","notes":[]},{"n":15,"t":"鴕鳥、夜鷹、魚鷹、鷹與其類，","notes":[]},{"n":16,"t":"鴞鳥、貓頭鷹、角鴟、","notes":[]},{"n":17,"t":"鵜鶘、禿鵰、鸕鶿、","notes":[]},{"n":18,"t":"鸛、鷺鷥與其類，戴鵀與蝙蝠。","notes":[]},{"n":19,"t":"凡有翅膀爬行的物是與你們不潔淨，都不可吃。","notes":[]},{"n":20,"t":"凡潔淨的鳥，你們都可以吃。","notes":[]},{"n":21,"t":"「凡自死的，你們都不可吃，可以給你城裏寄居的吃，或賣與外人吃，因為你是歸耶和華－你神為聖潔的民。「不可用山羊羔母的奶煮山羊羔。」","notes":[]},{"n":22,"t":"「你要把你撒種所產的，就是你田地每年所出的，十分取一分；","notes":[],"heads":["十分獻一的條例"]},{"n":23,"t":"又要把你的五穀、新酒、和油的十分之一，並牛群羊群中頭生的，吃在耶和華－你神面前，就是他所選擇要立為他名的居所。這樣，你可以學習時常敬畏耶和華－你的神。","notes":[]},{"n":24,"t":"當耶和華－你神賜福與你的時候，耶和華－你神所選擇要立為他名的地方若離你太遠，那路也太長，使你不能把這物帶到那裏去，","notes":[]},{"n":25,"t":"你就可以換成銀子，將銀子包起來，拿在手中，往耶和華－你神所要選擇的地方去。","notes":[]},{"n":26,"t":"你用這銀子，隨心所欲，或買牛羊，或買清酒濃酒，凡你心所想的都可以買；你和你的家屬在耶和華－你神的面前吃喝快樂。","notes":[]},{"n":27,"t":"「住在你城裏的利未人，你不可丟棄他，因為他在你們中間無分無業。","notes":[]},{"n":28,"t":"每逢三年的末一年，你要將本年的土產十分之一都取出來，積存在你的城中。","notes":[]},{"n":29,"t":"在你城裏無分無業的利未人，和你城裏寄居的，並孤兒寡婦，都可以來，吃得飽足。這樣，耶和華－你的神必在你手裏所辦的一切事上賜福與你。」","notes":[]}]},"15":{"heading":"安息年","verses":[{"n":1,"t":"「每逢七年末一年，你要施行豁免。","notes":[]},{"n":2,"t":"豁免的定例乃是這樣：凡債主要把所借給鄰舍的豁免了；不可向鄰舍和弟兄追討，因為耶和華的豁免年已經宣告了。","notes":[]},{"n":3,"t":"若借給外邦人，你可以向他追討；但借給你弟兄，無論是甚麼，你要鬆手豁免了。","notes":[]},{"n":4,"t":"你若留意聽從耶和華－你神的話，謹守遵行我今日所吩咐你這一切的命令，就必在你們中間沒有窮人了（在耶和華－你神所賜你為業的地上，耶和華必大大賜福與你。）","notes":[],"end":5},{"n":6,"t":"因為耶和華－你的神必照他所應許你的賜福與你。你必借給許多國民，卻不致向他們借貸；你必管轄許多國民，他們卻不能管轄你。","notes":[]},{"n":7,"t":"「在耶和華－你神所賜你的地上，無論哪一座城裏，你弟兄中若有一個窮人，你不可忍著心、揝著手不幫補你窮乏的弟兄。","notes":[]},{"n":8,"t":"總要向他鬆開手，照他所缺乏的借給他，補他的不足。","notes":[]},{"n":9,"t":"你要謹慎，不可心裏起惡念，說：『第七年的豁免年快到了』，你便惡眼看你窮乏的弟兄，甚麼都不給他，以致他因你求告耶和華，罪便歸於你了。","notes":[]},{"n":10,"t":"你總要給他，給他的時候心裏不可愁煩；因耶和華－你的神必在你這一切所行的，並你手裏所辦的事上，賜福與你。","notes":[]},{"n":11,"t":"原來那地上的窮人永不斷絕；所以我吩咐你說：『總要向你地上困苦窮乏的弟兄鬆開手。』」","notes":[]},{"n":12,"t":"「你弟兄中，若有一個希伯來男人或希伯來女人被賣給你，服事你六年，到第七年就要任他自由出去。","notes":[],"heads":["對待奴婢的條例"]},{"n":13,"t":"你任他自由的時候，不可使他空手而去，","notes":[]},{"n":14,"t":"要從你羊群、禾場、酒醡之中多多地給他；耶和華－你的神怎樣賜福與你，你也要照樣給他。","notes":[]},{"n":15,"t":"要記念你在埃及地作過奴僕，耶和華－你的神將你救贖；因此，我今日吩咐你這件事。","notes":[]},{"n":16,"t":"他若對你說：『我不願意離開你』，是因他愛你和你的家，且因在你那裏很好，","notes":[]},{"n":17,"t":"你就要拿錐子將他的耳朵在門上刺透，他便永為你的奴僕了。你待婢女也要這樣。","notes":[]},{"n":18,"t":"你任他自由的時候，不可以為難事，因他服事你六年，較比雇工的工價多加一倍了。耶和華－你的神就必在你所做的一切事上賜福與你。」","notes":[]},{"n":19,"t":"「你牛群羊群中頭生的，凡是公的，都要分別為聖，歸耶和華－你的神。牛群中頭生的，不可用牠耕地；羊群中頭生的，不可剪毛。","notes":[],"heads":["頭生牛羊的條例"]},{"n":20,"t":"這頭生的，你和你的家屬，每年要在耶和華所選擇的地方，在耶和華－你神面前吃。","notes":[]},{"n":21,"t":"這頭生的若有甚麼殘疾，就如瘸腿的、瞎眼的，無論有甚麼惡殘疾，都不可獻給耶和華－你的神；","notes":[]},{"n":22,"t":"可以在你城裏吃；潔淨人與不潔淨人都可以吃，就如吃羚羊與鹿一般。","notes":[]},{"n":23,"t":"只是不可吃牠的血；要倒在地上，如同倒水一樣。」","notes":[]}]},"16":{"heading":"逾越節","verses":[{"n":1,"t":"「你要注意亞筆月，向耶和華－你的神守逾越節，因為耶和華－你的神在亞筆月夜間領你出埃及。","notes":[]},{"n":2,"t":"你當在耶和華所選擇要立為他名的居所，從牛群羊群中，將逾越節的祭牲獻給耶和華－你的神。","notes":[]},{"n":3,"t":"你吃這祭牲，不可吃有酵的餅；七日之內要吃無酵餅，就是困苦餅－你本是急忙出了埃及地－要叫你一生一世記念你從埃及地出來的日子。","notes":[]},{"n":4,"t":"在你四境之內，七日不可見麵酵，頭一日晚上所獻的肉，一點不可留到早晨。","notes":[]},{"n":5,"t":"在耶和華－你神所賜的各城中，你不可獻逾越節的祭；","notes":[]},{"n":6,"t":"只當在耶和華－你神所選擇要立為他名的居所，晚上日落的時候，乃是你出埃及的時候，獻逾越節的祭。","notes":[]},{"n":7,"t":"當在耶和華－你神所選擇的地方把肉烤了吃，次日早晨就回到你的帳棚去。","notes":["烤：或譯煮"]},{"n":8,"t":"你要吃無酵餅六日，第七日要向耶和華－你的神守嚴肅會，不可做工。」","notes":[]},{"n":9,"t":"「你要計算七七日：從你開鐮收割禾稼時算起，共計七七日。","notes":[],"heads":["七七收穫節"]},{"n":10,"t":"你要照耶和華－你神所賜你的福，手裏拿著甘心祭，獻在耶和華－你的神面前，守七七節。","notes":[]},{"n":11,"t":"你和你兒女、僕婢，並住在你城裏的利未人，以及在你們中間寄居的與孤兒寡婦，都要在耶和華－你神所選擇立為他名的居所，在耶和華－你的神面前歡樂。","notes":[]},{"n":12,"t":"你也要記念你在埃及作過奴僕。你要謹守遵行這些律例。」","notes":[]},{"n":13,"t":"「你把禾場的穀、酒醡的酒收藏以後，就要守住棚節七日。","notes":[],"heads":["住棚節"]},{"n":14,"t":"守節的時候，你和你兒女、僕婢，並住在你城裏的利未人，以及寄居的與孤兒寡婦，都要歡樂。","notes":[]},{"n":15,"t":"在耶和華所選擇的地方，你當向耶和華－你的神守節七日；因為耶和華－你神在你一切的土產上和你手裏所辦的事上要賜福與你，你就非常地歡樂。","notes":[]},{"n":16,"t":"你一切的男丁要在除酵節、七七節、住棚節，一年三次，在耶和華－你神所選擇的地方朝見他，卻不可空手朝見。","notes":[]},{"n":17,"t":"各人要按自己的力量，照耶和華－你神所賜的福分，奉獻禮物。」","notes":[]},{"n":18,"t":"「你要在耶和華－你神所賜的各城裏，按著各支派設立審判官和官長。他們必按公義的審判判斷百姓。","notes":[],"heads":["秉公審斷"]},{"n":19,"t":"不可屈枉正直；不可看人的外貌。也不可受賄賂；因為賄賂能叫智慧人的眼變瞎了，又能顛倒義人的話。","notes":[]},{"n":20,"t":"你要追求至公至義，好叫你存活，承受耶和華－你神所賜你的地。","notes":[]},{"n":21,"t":"「你為耶和華－你的神築壇，不可在壇旁栽甚麼樹木作為木偶。","notes":[]},{"n":22,"t":"也不可為自己設立柱像；這是耶和華－你神所恨惡的。","notes":[]}]},"17":{"heading":"有關立王的指示","verses":[{"n":1,"t":"「凡有殘疾，或有甚麼惡病的牛羊，你都不可獻給耶和華－你的神，因為這是耶和華－你神所憎惡的。","notes":[]},{"n":2,"t":"「在你們中間，在耶和華－你神所賜你的諸城中，無論哪座城裏，若有人，或男或女，行耶和華－你神眼中看為惡的事，違背了他的約，","notes":[]},{"n":3,"t":"去事奉敬拜別神，或拜日頭，或拜月亮，或拜天象，是主不曾吩咐的；","notes":[]},{"n":4,"t":"有人告訴你，你也聽見了，就要細細地探聽，果然是真，準有這可憎惡的事行在以色列中，","notes":[]},{"n":5,"t":"你就要將行這惡事的男人或女人拉到城門外，用石頭將他打死。","notes":[]},{"n":6,"t":"要憑兩三個人的口作見證將那當死的人治死；不可憑一個人的口作見證將他治死。","notes":[]},{"n":7,"t":"見證人要先下手，然後眾民也下手將他治死。這樣，就把那惡從你們中間除掉。","notes":[]},{"n":8,"t":"「你城中若起了爭訟的事，或因流血，或因爭競，或因毆打，是你難斷的案件，你就當起來，往耶和華－你神所選擇的地方","notes":[]},{"n":9,"t":"去見祭司利未人，並當時的審判官，求問他們，他們必將判語指示你。","notes":[]},{"n":10,"t":"他們在耶和華所選擇的地方指示你的判語，你必照著他們所指教你的一切話謹守遵行。","notes":[]},{"n":11,"t":"要按他們所指教你的律法，照他們所斷定的去行；他們所指示你的判語，你不可偏離左右。","notes":[]},{"n":12,"t":"若有人擅敢不聽從那侍立在耶和華－你神面前的祭司，或不聽從審判官，那人就必治死；這樣，便將那惡從以色列中除掉。","notes":[]},{"n":13,"t":"眾百姓都要聽見害怕，不再擅敢行事。」","notes":[]},{"n":14,"t":"「到了耶和華－你神所賜你的地，得了那地居住的時候，若說：『我要立王治理我，像四圍的國一樣。』","notes":[]},{"n":15,"t":"你總要立耶和華－你神所揀選的人為王。必從你弟兄中立一人；不可立你弟兄以外的人為王。","notes":[]},{"n":16,"t":"只是王不可為自己加添馬匹，也不可使百姓回埃及去，為要加添他的馬匹，因耶和華曾吩咐你們說：『不可再回那條路去。』","notes":[]},{"n":17,"t":"他也不可為自己多立妃嬪，恐怕他的心偏邪；也不可為自己多積金銀。","notes":[]},{"n":18,"t":"他登了國位，就要將祭司利未人面前的這律法書，為自己抄錄一本，","notes":[]},{"n":19,"t":"存在他那裏，要平生誦讀，好學習敬畏耶和華－他的神，謹守遵行這律法書上的一切言語和這些律例，","notes":[]},{"n":20,"t":"免得他向弟兄心高氣傲，偏左偏右，離了這誡命。這樣，他和他的子孫便可在以色列中，在國位上年長日久。」","notes":[]}]},"18":{"heading":"祭司當得的分","verses":[{"n":1,"t":"「祭司利未人和利未全支派必在以色列中無分無業；他們所吃用的就是獻給耶和華的火祭和一切所捐的。","notes":[]},{"n":2,"t":"他們在弟兄中必沒有產業；耶和華是他們的產業，正如耶和華所應許他們的。","notes":[]},{"n":3,"t":"祭司從百姓所當得的分乃是這樣：凡獻牛或羊為祭的，要把前腿和兩腮並脾胃給祭司。","notes":[]},{"n":4,"t":"初收的五穀、新酒和油，並初剪的羊毛，也要給他；","notes":[]},{"n":5,"t":"因為耶和華－你的神從你各支派中將他揀選出來，使他和他子孫永遠奉耶和華的名侍立，事奉。","notes":[]},{"n":6,"t":"「利未人無論寄居在以色列中的哪一座城，若從那裏出來，一心願意到耶和華所選擇的地方，","notes":[]},{"n":7,"t":"就要奉耶和華－他神的名事奉，像他眾弟兄利未人侍立在耶和華面前事奉一樣。","notes":[]},{"n":8,"t":"除了他賣祖父產業所得的以外，還要得一分祭物與他們同吃。」","notes":[]},{"n":9,"t":"「你到了耶和華－你神所賜之地，那些國民所行可憎惡的事，你不可學著行。","notes":[],"heads":["不可隨從異邦的惡俗"]},{"n":10,"t":"你們中間不可有人使兒女經火，也不可有占卜的、觀兆的、用法術的、行邪術的、","notes":[]},{"n":11,"t":"用迷術的、交鬼的、行巫術的、過陰的。","notes":[]},{"n":12,"t":"凡行這些事的都為耶和華所憎惡；因那些國民行這可憎惡的事，所以耶和華－你的神將他們從你面前趕出。","notes":[]},{"n":13,"t":"你要在耶和華－你的神面前作完全人。」","notes":[]},{"n":14,"t":"「因你所要趕出的那些國民都聽信觀兆的和占卜的，至於你，耶和華－你的神從來不許你這樣行。","notes":[],"heads":["應許興起先知"]},{"n":15,"t":"耶和華－你的神要從你們弟兄中間給你興起一位先知，像我，你們要聽從他。","notes":[]},{"n":16,"t":"正如你在何烈山大會的日子求耶和華－你神一切的話，說：『求你不再叫我聽見耶和華－我神的聲音，也不再叫我看見這大火，免得我死亡。』","notes":[]},{"n":17,"t":"耶和華就對我說：『他們所說的是。","notes":[]},{"n":18,"t":"我必在他們弟兄中間給他們興起一位先知，像你。我要將當說的話傳給他；他要將我一切所吩咐的都傳給他們。","notes":[]},{"n":19,"t":"誰不聽他奉我名所說的話，我必討誰的罪。","notes":[]},{"n":20,"t":"若有先知擅敢託我的名說我所未曾吩咐他說的話，或是奉別神的名說話，那先知就必治死。』","notes":[]},{"n":21,"t":"你心裏若說：『耶和華所未曾吩咐的話，我們怎能知道呢？』","notes":[]},{"n":22,"t":"先知託耶和華的名說話，所說的若不成就，也無效驗，這就是耶和華所未曾吩咐的，是那先知擅自說的，你不要怕他。」","notes":[]}]},"19":{"heading":"設立庇護城","verses":[{"n":1,"t":"「耶和華－你神將列國之民剪除的時候，耶和華－你神也將他們的地賜給你，你接著住他們的城邑並他們的房屋，","notes":[]},{"n":2,"t":"就要在耶和華－你神所賜你為業的地上分定三座城。","notes":[]},{"n":3,"t":"要將耶和華－你神使你承受為業的地分為三段；又要預備道路，使誤殺人的，都可以逃到那裏去。","notes":[]},{"n":4,"t":"「誤殺人的逃到那裏可以存活，定例乃是這樣：凡素無仇恨，無心殺了人的，","notes":[]},{"n":5,"t":"就如人與鄰舍同入樹林砍伐樹木，手拿斧子一砍，本想砍下樹木，不料，斧頭脫了把，飛落在鄰舍身上，以致於死，這人逃到那些城的一座城，就可以存活，","notes":[]},{"n":6,"t":"免得報血仇的，心中火熱追趕他，因路遠就追上，將他殺死；其實他不該死，因為他與被殺的素無仇恨。","notes":[]},{"n":7,"t":"所以我吩咐你說，要分定三座城。","notes":[]},{"n":8,"t":"耶和華－你神若照他向你列祖所起的誓擴張你的境界，將所應許賜你列祖的地全然給你，","notes":[]},{"n":9,"t":"你若謹守遵行我今日所吩咐的這一切誡命，愛耶和華－你的神，常常遵行他的道，就要在這三座城之外，再添三座城，","notes":[]},{"n":10,"t":"免得無辜之人的血流在耶和華－你神所賜你為業的地上，流血的罪就歸於你。","notes":[]},{"n":11,"t":"「若有人恨他的鄰舍，埋伏著起來擊殺他，以致於死，便逃到這些城的一座城，","notes":[]},{"n":12,"t":"本城的長老就要打發人去，從那裏帶出他來，交在報血仇的手中，將他治死。","notes":[]},{"n":13,"t":"你眼不可顧惜他，卻要從以色列中除掉流無辜血的罪，使你可以得福。」","notes":[]},{"n":14,"t":"「在耶和華－你神所賜你承受為業之地，不可挪移你鄰舍的地界，那是先人所定的。」","notes":[],"heads":["舊地界"]},{"n":15,"t":"「人無論犯甚麼罪，作甚麼惡，不可憑一個人的口作見證，總要憑兩三個人的口作見證才可定案。","notes":[],"heads":["有關證人的條例"]},{"n":16,"t":"若有凶惡的見證人起來，見證某人作惡，","notes":[]},{"n":17,"t":"這兩個爭訟的人就要站在耶和華面前，和當時的祭司，並審判官面前，","notes":[]},{"n":18,"t":"審判官要細細地查究，若見證人果然是作假見證的，以假見證陷害弟兄，","notes":[]},{"n":19,"t":"你們就要待他如同他想要待的弟兄。這樣，就把那惡從你們中間除掉。","notes":[]},{"n":20,"t":"別人聽見都要害怕，就不敢在你們中間再行這樣的惡了。","notes":[]},{"n":21,"t":"你眼不可顧惜，要以命償命，以眼還眼，以牙還牙，以手還手，以腳還腳。」","notes":[]}]},"20":{"heading":"有關戰爭的條例","verses":[{"n":1,"t":"「你出去與仇敵爭戰的時候，看見馬匹、車輛，並有比你多的人民，不要怕他們，因為領你出埃及地的耶和華－你神與你同在。","notes":[]},{"n":2,"t":"你們將要上陣的時候，祭司要到百姓面前宣告","notes":[]},{"n":3,"t":"說：『以色列人哪，你們當聽，你們今日將要與仇敵爭戰，不要膽怯，不要懼怕戰兢，也不要因他們驚恐；","notes":[]},{"n":4,"t":"因為耶和華－你們的神與你們同去，要為你們與仇敵爭戰，拯救你們。』","notes":[]},{"n":5,"t":"官長也要對百姓宣告說：『誰建造房屋，尚未奉獻，他可以回家去，恐怕他陣亡，別人去奉獻。","notes":[]},{"n":6,"t":"誰種葡萄園，尚未用所結的果子，他可以回家去，恐怕他陣亡，別人去用。","notes":[]},{"n":7,"t":"誰聘定了妻，尚未迎娶，他可以回家去，恐怕他陣亡，別人去娶。』","notes":[]},{"n":8,"t":"官長又要對百姓宣告說：『誰懼怕膽怯，他可以回家去，恐怕他弟兄的心消化，和他一樣。』","notes":[]},{"n":9,"t":"官長對百姓宣告完了，就當派軍長率領他們。","notes":[]},{"n":10,"t":"「你臨近一座城、要攻打的時候，先要對城裏的民宣告和睦的話。","notes":[]},{"n":11,"t":"他們若以和睦的話回答你，給你開了城，城裏所有的人都要給你效勞，服事你；","notes":[]},{"n":12,"t":"若不肯與你和好，反要與你打仗，你就要圍困那城。","notes":[]},{"n":13,"t":"耶和華－你的神把城交付你手，你就要用刀殺盡這城的男丁。","notes":[]},{"n":14,"t":"惟有婦女、孩子、牲畜，和城內一切的財物，你可以取為自己的掠物。耶和華－你神把你仇敵的財物賜給你，你可以吃用。","notes":[]},{"n":15,"t":"離你甚遠的各城，不是這些國民的城，你都要這樣待他。","notes":[]},{"n":16,"t":"但這些國民的城，耶和華－你神既賜你為業，其中凡有氣息的，一個不可存留；","notes":[]},{"n":17,"t":"只要照耶和華－你神所吩咐的將這赫人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人都滅絕淨盡，","notes":[]},{"n":18,"t":"免得他們教導你們學習一切可憎惡的事，就是他們向自己神所行的，以致你們得罪耶和華－你們的神。","notes":[]},{"n":19,"t":"「你若許久圍困、攻打所要取的一座城，就不可舉斧子砍壞樹木；因為你可以吃那樹上的果子，不可砍伐。田間的樹木豈是人，叫你糟蹋嗎？","notes":[]},{"n":20,"t":"惟獨你所知道不是結果子的樹木可以毀壞、砍伐，用以修築營壘，攻擊那與你打仗的城，直到攻塌了。」","notes":[]}]},"21":{"heading":"有關未結案的謀殺案件","verses":[{"n":1,"t":"「在耶和華－你神所賜你為業的地上，若遇見被殺的人倒在田野，不知道是誰殺的，","notes":[]},{"n":2,"t":"長老和審判官就要出去，從被殺的人那裏量起，直量到四圍的城邑，","notes":[]},{"n":3,"t":"看哪城離被殺的人最近，那城的長老就要從牛群中取一隻未曾耕地、未曾負軛的母牛犢，","notes":[]},{"n":4,"t":"把母牛犢牽到流水、未曾耕種的山谷去，在谷中打折母牛犢的頸項。","notes":[]},{"n":5,"t":"祭司利未的子孫要近前來；因為耶和華－你的神揀選了他們事奉他，奉耶和華的名祝福，所有爭訟毆打的事都要憑他們判斷。","notes":[]},{"n":6,"t":"那城的眾長老，就是離被殺的人最近的，要在那山谷中，在所打折頸項的母牛犢以上洗手，","notes":[]},{"n":7,"t":"禱告說：『我們的手未曾流這人的血；我們的眼也未曾看見這事。","notes":["原文是回答"]},{"n":8,"t":"耶和華啊，求你赦免你所救贖的以色列民，不要使流無辜血的罪歸在你的百姓以色列中間。』這樣，流血的罪必得赦免。","notes":[]},{"n":9,"t":"你行耶和華眼中看為正的事，就可以從你們中間除掉流無辜血的罪。」","notes":[]},{"n":10,"t":"「你出去與仇敵爭戰的時候，耶和華－你的神將他們交在你手中，你就擄了他們去。","notes":[],"heads":["有關女戰俘的案件"]},{"n":11,"t":"若在被擄的人中見有美貌的女子，戀慕她，要娶她為妻，","notes":[]},{"n":12,"t":"就可以領她到你家裏去；她便要剃頭髮，修指甲，","notes":[]},{"n":13,"t":"脫去被擄時所穿的衣服，住在你家裏哀哭父母一個整月，然後可以與她同房。你作她的丈夫，她作你的妻子。","notes":[]},{"n":14,"t":"後來你若不喜悅她，就要由她隨意出去，決不可為錢賣她，也不可當婢女待她，因為你玷污了她。」","notes":[]},{"n":15,"t":"「人若有二妻，一為所愛，一為所惡，所愛的、所惡的都給他生了兒子，但長子是所惡之妻生的。","notes":[],"heads":["有關長子的繼承權"]},{"n":16,"t":"到了把產業分給兒子承受的時候，不可將所愛之妻生的兒子立為長子，在所惡之妻生的兒子以上，","notes":[]},{"n":17,"t":"卻要認所惡之妻生的兒子為長子，將產業多加一分給他；因這兒子是他力量強壯的時候生的，長子的名分本當歸他。」","notes":[]},{"n":18,"t":"「人若有頑梗悖逆的兒子，不聽從父母的話，他們雖懲治他，他仍不聽從，","notes":[],"heads":["有關逆子的處置"]},{"n":19,"t":"父母就要抓住他，將他帶到本地的城門、本城的長老那裏，","notes":[]},{"n":20,"t":"對長老說：『我們這兒子頑梗悖逆，不聽從我們的話，是貪食好酒的人。』","notes":[]},{"n":21,"t":"本城的眾人就要用石頭將他打死。這樣，就把那惡從你們中間除掉，以色列眾人都要聽見害怕。」","notes":[]},{"n":22,"t":"「人若犯該死的罪，被治死了，你將他掛在木頭上，","notes":[],"heads":["其他的條例"]},{"n":23,"t":"他的屍首不可留在木頭上過夜，必要當日將他葬埋，免得玷污了耶和華－你神所賜你為業之地。因為被掛的人是在神面前受咒詛的。","notes":[]}]},"22":{"heading":"有關貞潔的條例","verses":[{"n":1,"t":"「你若看見弟兄的牛或羊失迷了路，不可佯為不見，總要把牠牽回來交給你的弟兄。","notes":[]},{"n":2,"t":"你弟兄若離你遠，或是你不認識他，就要牽到你家去，留在你那裏，等你弟兄來尋找就還給他。","notes":[]},{"n":3,"t":"你的弟兄無論失落甚麼，或是驢，或是衣服，你若遇見，都要這樣行，不可佯為不見。","notes":[]},{"n":4,"t":"你若看見弟兄的牛或驢跌倒在路上，不可佯為不見，總要幫助他拉起來。","notes":[]},{"n":5,"t":"「婦女不可穿戴男子所穿戴的，男子也不可穿婦女的衣服，因為這樣行都是耶和華－你神所憎惡的。","notes":[]},{"n":6,"t":"「你若路上遇見鳥窩，或在樹上或在地上，裏頭有雛或有蛋，母鳥伏在雛上或在蛋上，你不可連母帶雛一併取去。","notes":[]},{"n":7,"t":"總要放母，只可取雛；這樣你就可以享福，日子得以長久。","notes":[]},{"n":8,"t":"「你若建造房屋，要在房上的四圍安欄杆，免得有人從房上掉下來，流血的罪就歸於你家。","notes":[]},{"n":9,"t":"「不可把兩樣種子種在你的葡萄園裏，免得你撒種所結的和葡萄園的果子都要充公。","notes":[]},{"n":10,"t":"不可並用牛、驢耕地。","notes":[]},{"n":11,"t":"不可穿羊毛、細麻兩樣攙雜料做的衣服。","notes":[]},{"n":12,"t":"「你要在所披的外衣上四圍做繸子。」","notes":[]},{"n":13,"t":"「人若娶妻，與她同房之後恨惡她，","notes":[]},{"n":14,"t":"信口說她，將醜名加在她身上，說：『我娶了這女子，與她同房，見她沒有貞潔的憑據』；","notes":[]},{"n":15,"t":"女子的父母就要把女子貞潔的憑據拿出來，帶到本城門長老那裏。","notes":[]},{"n":16,"t":"女子的父親要對長老說：『我將我的女兒給這人為妻，他恨惡她，","notes":[]},{"n":17,"t":"信口說她，說：我見你的女兒沒有貞潔的憑據；其實這就是我女兒貞潔的憑據。』父母就把那布鋪在本城的長老面前。","notes":[]},{"n":18,"t":"本城的長老要拿住那人，懲治他，","notes":[]},{"n":19,"t":"並要罰他一百舍客勒銀子，給女子的父親，因為他將醜名加在以色列的一個處女身上。女子仍作他的妻，終身不可休她。","notes":[]},{"n":20,"t":"但這事若是真的，女子沒有貞潔的憑據，","notes":[]},{"n":21,"t":"就要將女子帶到她父家的門口，本城的人要用石頭將她打死；因為她在父家行了淫亂，在以色列中做了醜事。這樣，就把那惡從你們中間除掉。","notes":[]},{"n":22,"t":"「若遇見人與有丈夫的婦人行淫，就要將姦夫淫婦一併治死。這樣，就把那惡從以色列中除掉。","notes":[]},{"n":23,"t":"「若有處女已經許配丈夫，有人在城裏遇見她，與她行淫，","notes":[]},{"n":24,"t":"你們就要把這二人帶到本城門，用石頭打死－女子是因為雖在城裏卻沒有喊叫；男子是因為玷污別人的妻。這樣，就把那惡從你們中間除掉。","notes":[]},{"n":25,"t":"「若有男子在田野遇見已經許配人的女子，強與她行淫，只要將那男子治死。","notes":[]},{"n":26,"t":"但不可辦女子；她本沒有該死的罪，這事就類乎人起來攻擊鄰舍，將他殺了一樣。","notes":[]},{"n":27,"t":"因為男子是在田野遇見那已經許配人的女子，女子喊叫，並無人救她。","notes":[]},{"n":28,"t":"「若有男子遇見沒有許配人的處女，抓住她，與她行淫，被人看見，","notes":[]},{"n":29,"t":"這男子就要拿五十舍客勒銀子給女子的父親；因他玷污了這女子，就要娶她為妻，終身不可休她。","notes":[]},{"n":30,"t":"「人不可娶繼母為妻；不可掀開他父親的衣襟。」","notes":[]}]},"23":{"heading":"不許進入聖會的人","verses":[{"n":1,"t":"「凡外腎受傷的，或被閹割的，不可入耶和華的會。","notes":[]},{"n":2,"t":"「私生子不可入耶和華的會；他的子孫，直到十代，也不可入耶和華的會。","notes":[]},{"n":3,"t":"「亞捫人或是摩押人不可入耶和華的會；他們的子孫，雖過十代，也永不可入耶和華的會。","notes":[]},{"n":4,"t":"因為你們出埃及的時候，他們沒有拿食物和水在路上迎接你們，又因他們雇了美索不達米亞的毗奪人比珥的兒子巴蘭來咒詛你們。","notes":[]},{"n":5,"t":"然而耶和華－你的神不肯聽從巴蘭，卻使那咒詛的言語變為祝福的話，因為耶和華－你的神愛你。","notes":[]},{"n":6,"t":"你一生一世永不可求他們的平安和他們的利益。","notes":[]},{"n":7,"t":"「不可憎惡以東人，因為他是你的弟兄。不可憎惡埃及人，因為你在他的地上作過寄居的。","notes":[]},{"n":8,"t":"他們第三代子孫可以入耶和華的會。」","notes":[]},{"n":9,"t":"「你出兵攻打仇敵，就要遠避諸惡。","notes":[],"heads":["保持軍營的衛生"]},{"n":10,"t":"「你們中間，若有人夜間偶然夢遺，不潔淨，就要出到營外，不可入營；","notes":[]},{"n":11,"t":"到傍晚的時候，他要用水洗澡，及至日落了才可以入營。","notes":[]},{"n":12,"t":"「你在營外也該定出一個地方作為便所。","notes":[]},{"n":13,"t":"在你器械之中當預備一把鍬，你出營外便溺以後，用以鏟土，轉身掩蓋。","notes":[]},{"n":14,"t":"因為耶和華－你的神常在你營中行走，要救護你，將仇敵交給你，所以你的營理當聖潔，免得他見你那裏有污穢，就離開你。」","notes":[]},{"n":15,"t":"「若有奴僕脫了主人的手，逃到你那裏，你不可將他交付他的主人。","notes":[],"heads":["一般條例"]},{"n":16,"t":"他必在你那裏與你同住，在你的城邑中，要由他選擇一個所喜悅的地方居住；你不可欺負他。","notes":[]},{"n":17,"t":"「以色列的女子中不可有妓女；以色列的男子中不可有孌童。","notes":[]},{"n":18,"t":"娼妓所得的錢，或孌童所得的價，你不可帶入耶和華－你神的殿還願，因為這兩樣都是耶和華－你神所憎惡的。","notes":["原文是狗"]},{"n":19,"t":"「你借給你弟兄的，或是錢財或是糧食，無論甚麼可生利的物，都不可取利。","notes":[]},{"n":20,"t":"借給外邦人可以取利，只是借給你弟兄不可取利。這樣，耶和華－你神必在你所去得為業的地上和你手裏所辦的一切事上賜福與你。","notes":[]},{"n":21,"t":"「你向耶和華－你的神許願，償還不可遲延；因為耶和華－你的神必定向你追討，你不償還就有罪。","notes":[]},{"n":22,"t":"你若不許願，倒無罪。","notes":[]},{"n":23,"t":"你嘴裏所出的，就是你口中應許甘心所獻的，要照你向耶和華－你神所許的願謹守遵行。","notes":[]},{"n":24,"t":"「你進了鄰舍的葡萄園，可以隨意吃飽了葡萄，只是不可裝在器皿中。","notes":[]},{"n":25,"t":"你進了鄰舍站著的禾稼，可以用手摘穗子，只是不可用鐮刀割取禾稼。」","notes":[]}]},"24":{"heading":"離婚和再婚","verses":[{"n":1,"t":"「人若娶妻以後，見她有甚麼不合理的事，不喜悅她，就可以寫休書交在她手中，打發她離開夫家。","notes":[]},{"n":2,"t":"婦人離開夫家以後，可以去嫁別人。","notes":[]},{"n":3,"t":"後夫若恨惡她，寫休書交在她手中，打發她離開夫家，或是娶她為妻的後夫死了，","notes":[]},{"n":4,"t":"打發她去的前夫不可在婦人玷污之後再娶她為妻，因為這是耶和華所憎惡的；不可使耶和華－你神所賜為業之地被玷污了。」","notes":[]},{"n":5,"t":"「新娶妻之人不可從軍出征，也不可託他辦理甚麼公事，可以在家清閒一年，使他所娶的妻快活。","notes":[],"heads":["一般條例"]},{"n":6,"t":"「不可拿人的全盤磨石或是上磨石作當頭，因為這是拿人的命作當頭。","notes":[]},{"n":7,"t":"「若遇見人拐帶以色列中的一個弟兄，當奴才待他，或是賣了他，那拐帶人的就必治死。這樣，便將那惡從你們中間除掉。","notes":[]},{"n":8,"t":"「在大痲瘋的災病上，你們要謹慎，照祭司利未人一切所指教你們的留意遵行。我怎樣吩咐他們，你們要怎樣遵行。","notes":[]},{"n":9,"t":"當記念出埃及後，在路上，耶和華－你神向米利暗所行的事。","notes":[]},{"n":10,"t":"「你借給鄰舍，不拘是甚麼，不可進他家拿他的當頭。","notes":[]},{"n":11,"t":"要站在外面，等那向你借貸的人把當頭拿出來交給你。","notes":[]},{"n":12,"t":"他若是窮人，你不可留他的當頭過夜。","notes":[]},{"n":13,"t":"日落的時候，總要把當頭還他，使他用那件衣服蓋著睡覺，他就為你祝福；這在耶和華－你神面前就是你的義了。","notes":[]},{"n":14,"t":"「困苦窮乏的雇工，無論是你的弟兄或是在你城裏寄居的，你不可欺負他。","notes":[]},{"n":15,"t":"要當日給他工價，不可等到日落－因為他窮苦，把心放在工價上－恐怕他因你求告耶和華，罪便歸你了。","notes":[]},{"n":16,"t":"「不可因子殺父，也不可因父殺子；凡被殺的都為本身的罪。","notes":[]},{"n":17,"t":"「你不可向寄居的和孤兒屈枉正直，也不可拿寡婦的衣裳作當頭。","notes":[]},{"n":18,"t":"要記念你在埃及作過奴僕。耶和華－你的神從那裏將你救贖，所以我吩咐你這樣行。","notes":[]},{"n":19,"t":"「你在田間收割莊稼，若忘下一捆，不可回去再取，要留給寄居的與孤兒寡婦。這樣，耶和華－你神必在你手裏所辦的一切事上賜福與你。","notes":[]},{"n":20,"t":"你打橄欖樹，枝上剩下的，不可再打；要留給寄居的與孤兒寡婦。","notes":[]},{"n":21,"t":"你摘葡萄園的葡萄，所剩下的，不可再摘；要留給寄居的與孤兒寡婦。","notes":[]},{"n":22,"t":"你也要記念你在埃及地作過奴僕，所以我吩咐你這樣行。","notes":[]}]},"25":{"heading":"對喪亡的弟兄傳宗接代","verses":[{"n":1,"t":"「人若有爭訟，來聽審判，審判官就要定義人有理，定惡人有罪。","notes":[]},{"n":2,"t":"惡人若該受責打，審判官就要叫他當面伏在地上，按著他的罪照數責打。","notes":[]},{"n":3,"t":"只可打他四十下，不可過數；若過數，便是輕賤你的弟兄了。","notes":[]},{"n":4,"t":"「牛在場上踹穀的時候，不可籠住牠的嘴。」","notes":[]},{"n":5,"t":"「弟兄同居，若死了一個，沒有兒子，死人的妻不可出嫁外人，她丈夫的兄弟當盡弟兄的本分，娶她為妻，與她同房。","notes":[]},{"n":6,"t":"婦人生的長子必歸死兄的名下，免得他的名在以色列中塗抹了。","notes":[]},{"n":7,"t":"那人若不願意娶他哥哥的妻，他哥哥的妻就要到城門長老那裏，說：『我丈夫的兄弟不肯在以色列中興起他哥哥的名字，不給我盡弟兄的本分。』","notes":[]},{"n":8,"t":"本城的長老就要召那人來問他，他若執意說：『我不願意娶她』，","notes":[]},{"n":9,"t":"他哥哥的妻就要當著長老到那人的跟前，脫了他的鞋，吐唾沫在他臉上，說：『凡不為哥哥建立家室的都要這樣待他。』","notes":[]},{"n":10,"t":"在以色列中，他的名必稱為脫鞋之家。」","notes":[]},{"n":11,"t":"「若有二人爭鬥，這人的妻近前來，要救她丈夫脫離那打她丈夫之人的手，抓住那人的下體，","notes":[],"heads":["其他的條例"]},{"n":12,"t":"就要砍斷婦人的手，眼不可顧惜她。","notes":[]},{"n":13,"t":"「你囊中不可有一大一小兩樣的法碼。","notes":[]},{"n":14,"t":"你家裏不可有一大一小兩樣的升斗。","notes":[]},{"n":15,"t":"當用對準公平的法碼，公平的升斗。這樣，在耶和華－你神所賜你的地上，你的日子就可以長久。","notes":[]},{"n":16,"t":"因為行非義之事的人都是耶和華－你神所憎惡的。」","notes":[]},{"n":17,"t":"「你要記念你們出埃及的時候，亞瑪力人在路上怎樣待你。","notes":[],"heads":["命令百姓消滅亞瑪力人"]},{"n":18,"t":"他們在路上遇見你，趁你疲乏困倦擊殺你儘後邊軟弱的人，並不敬畏神。","notes":[]},{"n":19,"t":"所以耶和華－你神使你不被四圍一切的仇敵擾亂，在耶和華－你神賜你為業的地上得享平安。那時，你要將亞瑪力的名號從天下塗抹了，不可忘記。」","notes":[]}]},"26":{"heading":"奉獻初熟的土產","verses":[{"n":1,"t":"「你進去得了耶和華－你神所賜你為業之地居住，","notes":[]},{"n":2,"t":"就要從耶和華－你神賜你的地上將所收的各種初熟的土產取些來，盛在筐子裏，往耶和華－你神所選擇要立為他名的居所去，","notes":[]},{"n":3,"t":"見當時作祭司的，對他說：『我今日向耶和華－你神明認，我已來到耶和華向我們列祖起誓應許賜給我們的地。』","notes":[]},{"n":4,"t":"祭司就從你手裏取過筐子來，放在耶和華－你神的壇前。","notes":[]},{"n":5,"t":"你要在耶和華－你神面前說：『我祖原是一個將亡的亞蘭人，下到埃及寄居。他人口稀少，在那裏卻成了又大又強、人數很多的國民。","notes":[]},{"n":6,"t":"埃及人惡待我們，苦害我們，將苦工加在我們身上。","notes":[]},{"n":7,"t":"於是我們哀求耶和華－我們列祖的神，耶和華聽見我們的聲音，看見我們所受的困苦、勞碌、欺壓，","notes":[]},{"n":8,"t":"他就用大能的手和伸出來的膀臂，並大可畏的事與神蹟奇事，領我們出了埃及，","notes":[]},{"n":9,"t":"將我們領進這地方，把這流奶與蜜之地賜給我們。","notes":[]},{"n":10,"t":"耶和華啊，現在我把你所賜給我地上初熟的土產奉了來。』隨後你要把筐子放在耶和華－你神面前，向耶和華－你的神下拜。","notes":[]},{"n":11,"t":"你和利未人，並在你們中間寄居的，要因耶和華－你神所賜你和你家的一切福分歡樂。","notes":[]},{"n":12,"t":"「每逢三年，就是十分取一之年，你取完了一切土產的十分之一，要分給利未人和寄居的，與孤兒寡婦，使他們在你城中可以吃得飽足。","notes":[]},{"n":13,"t":"你又要在耶和華－你神面前說：『我已將聖物從我家裏拿出來，給了利未人和寄居的，與孤兒寡婦，是照你所吩咐我的一切命令。你的命令我都沒有違背，也沒有忘記。","notes":[]},{"n":14,"t":"我守喪的時候，沒有吃這聖物；不潔淨的時候，也沒有拿出來，又沒有為死人送去。我聽從了耶和華－我神的話，都照你所吩咐的行了。","notes":[]},{"n":15,"t":"求你從天上、你的聖所垂看，賜福給你的百姓以色列與你所賜給我們的地，就是你向我們列祖起誓賜我們流奶與蜜之地。』」","notes":[]},{"n":16,"t":"「耶和華－你的神今日吩咐你行這些律例典章，所以你要盡心盡性謹守遵行。","notes":[],"heads":["作聖潔的子民"]},{"n":17,"t":"你今日認耶和華為你的神，應許遵行他的道，謹守他的律例、誡命、典章，聽從他的話。","notes":[]},{"n":18,"t":"耶和華今日照他所應許你的，也認你為他的子民，使你謹守他的一切誡命，","notes":[]},{"n":19,"t":"又使你得稱讚、美名、尊榮，超乎他所造的萬民之上，並照他所應許的使你歸耶和華－你神為聖潔的民。」","notes":[]}]},"27":{"heading":"神的律法寫在石頭上","verses":[{"n":1,"t":"摩西和以色列的眾長老吩咐百姓說：「你們要遵守我今日所吩咐的一切誡命。","notes":[]},{"n":2,"t":"你們過約旦河，到了耶和華－你神所賜給你的地，當天要立起幾塊大石頭，墁上石灰，","notes":[]},{"n":3,"t":"把這律法的一切話寫在石頭上。你過了河，可以進入耶和華－你神所賜你流奶與蜜之地，正如耶和華－你列祖之神所應許你的。","notes":[]},{"n":4,"t":"你們過了約旦河，就要在以巴路山上照我今日所吩咐的，將這些石頭立起來，墁上石灰。","notes":[]},{"n":5,"t":"在那裏要為耶和華－你的神築一座石壇；在石頭上不可動鐵器。","notes":[]},{"n":6,"t":"要用沒有鑿過的石頭築耶和華－你神的壇，在壇上要將燔祭獻給耶和華－你的神。","notes":[]},{"n":7,"t":"又要獻平安祭，且在那裏吃，在耶和華－你的神面前歡樂。","notes":[]},{"n":8,"t":"你要將這律法的一切話明明地寫在石頭上。」","notes":[]},{"n":9,"t":"摩西和祭司利未人曉諭以色列眾人說：「以色列啊，要默默靜聽。你今日成為耶和華－你神的百姓了。","notes":[]},{"n":10,"t":"所以要聽從耶和華－你神的話，遵行他的誡命律例，就是我今日所吩咐你的。」","notes":[]},{"n":11,"t":"當日，摩西囑咐百姓說：","notes":[],"heads":["違命必受咒詛"]},{"n":12,"t":"「你們過了約旦河，西緬、利未、猶大、以薩迦、約瑟、便雅憫六個支派的人都要站在基利心山上為百姓祝福。","notes":[]},{"n":13,"t":"呂便、迦得、亞設、西布倫、但、拿弗他利六個支派的人都要站在以巴路山上宣布咒詛。","notes":[]},{"n":14,"t":"利未人要向以色列眾人高聲說：","notes":[]},{"n":15,"t":"「『有人製造耶和華所憎惡的偶像，或雕刻，或鑄造，就是工匠手所做的，在暗中設立，那人必受咒詛！』百姓都要答應說：『阿們！』","notes":[]},{"n":16,"t":"「『輕慢父母的，必受咒詛！』百姓都要說：『阿們！』","notes":[]},{"n":17,"t":"「『挪移鄰舍地界的，必受咒詛！』百姓都要說：『阿們！』","notes":[]},{"n":18,"t":"「『使瞎子走差路的，必受咒詛！』百姓都要說：『阿們！』","notes":[]},{"n":19,"t":"「『向寄居的和孤兒寡婦屈枉正直的，必受咒詛！』百姓都要說：『阿們！』","notes":[]},{"n":20,"t":"「『與繼母行淫的，必受咒詛！因為掀開他父親的衣襟。』百姓都要說：『阿們！』","notes":[]},{"n":21,"t":"「『與獸淫合的，必受咒詛！』百姓都要說：『阿們！』","notes":[]},{"n":22,"t":"「『與異母同父，或異父同母的姊妹行淫的，必受咒詛！』百姓都要說：『阿們！』","notes":[]},{"n":23,"t":"「『與岳母行淫的，必受咒詛！』百姓都要說：『阿們！』","notes":[]},{"n":24,"t":"「『暗中殺人的，必受咒詛！』百姓都要說：『阿們！』","notes":[]},{"n":25,"t":"「『受賄賂害死無辜之人的，必受咒詛！』百姓都要說：『阿們！』","notes":[]},{"n":26,"t":"「『不堅守遵行這律法言語的，必受咒詛！』百姓都要說：『阿們！』」","notes":[]}]},"28":{"heading":"遵行誡命蒙福","verses":[{"n":1,"t":"「你若留意聽從耶和華－你神的話，謹守遵行他的一切誡命，就是我今日所吩咐你的，他必使你超乎天下萬民之上。","notes":[]},{"n":2,"t":"你若聽從耶和華－你神的話，這以下的福必追隨你，臨到你身上：","notes":[]},{"n":3,"t":"你在城裏必蒙福，在田間也必蒙福。","notes":[]},{"n":4,"t":"你身所生的，地所產的，牲畜所下的，以及牛犢、羊羔，都必蒙福。","notes":[]},{"n":5,"t":"你的筐子和你的摶麵盆都必蒙福。","notes":[]},{"n":6,"t":"你出也蒙福，入也蒙福。","notes":[]},{"n":7,"t":"「仇敵起來攻擊你，耶和華必使他們在你面前被你殺敗；他們從一條路來攻擊你，必從七條路逃跑。","notes":[]},{"n":8,"t":"在你倉房裏，並你手所辦的一切事上，耶和華所命的福必臨到你。耶和華－你神也要在所給你的地上賜福與你。","notes":[]},{"n":9,"t":"你若謹守耶和華－你神的誡命，遵行他的道，他必照著向你所起的誓立你作為自己的聖民。","notes":[]},{"n":10,"t":"天下萬民見你歸在耶和華的名下，就要懼怕你。","notes":[]},{"n":11,"t":"你在耶和華向你列祖起誓應許賜你的地上，他必使你身所生的，牲畜所下的，地所產的，都綽綽有餘。","notes":[]},{"n":12,"t":"耶和華必為你開天上的府庫，按時降雨在你的地上。在你手裏所辦的一切事上賜福與你。你必借給許多國民，卻不致向他們借貸。","notes":[]},{"n":13,"t":"你若聽從耶和華－你神的誡命，就是我今日所吩咐你的，謹守遵行，不偏左右，也不隨從事奉別神，耶和華就必使你作首不作尾，但居上不居下。」","notes":[],"end":14},{"n":15,"t":"「你若不聽從耶和華－你神的話，不謹守遵行他的一切誡命律例，就是我今日所吩咐你的，這以下的咒詛都必追隨你，臨到你身上：","notes":[],"heads":["悖逆的後果"]},{"n":16,"t":"你在城裏必受咒詛，在田間也必受咒詛。","notes":[]},{"n":17,"t":"你的筐子和你的摶麵盆都必受咒詛。","notes":[]},{"n":18,"t":"你身所生的，地所產的，以及牛犢、羊羔，都必受咒詛。","notes":[]},{"n":19,"t":"你出也受咒詛，入也受咒詛。","notes":[]},{"n":20,"t":"耶和華因你行惡離棄他，必在你手裏所辦的一切事上，使咒詛、擾亂、責罰臨到你，直到你被毀滅，速速地滅亡。","notes":[]},{"n":21,"t":"耶和華必使瘟疫貼在你身上，直到他將你從所進去得為業的地上滅絕。","notes":[]},{"n":22,"t":"耶和華要用癆病、熱病、火症、瘧疾、刀劍、旱風、霉爛攻擊你。這都要追趕你，直到你滅亡。","notes":["或譯：乾旱"]},{"n":23,"t":"你頭上的天要變為銅，腳下的地要變為鐵。","notes":[]},{"n":24,"t":"耶和華要使那降在你地上的雨變為塵沙，從天臨在你身上，直到你滅亡。","notes":[]},{"n":25,"t":"「耶和華必使你敗在仇敵面前，你從一條路去攻擊他們，必從七條路逃跑。你必在天下萬國中拋來拋去。","notes":[]},{"n":26,"t":"你的屍首必給空中的飛鳥和地上的走獸作食物，並無人鬨趕。","notes":[]},{"n":27,"t":"耶和華必用埃及人的瘡並痔瘡、牛皮癬與疥攻擊你，使你不能醫治。","notes":[]},{"n":28,"t":"耶和華必用癲狂、眼瞎、心驚攻擊你。","notes":[]},{"n":29,"t":"你必在午間摸索，好像瞎子在暗中摸索一樣。你所行的必不亨通，時常遭遇欺壓、搶奪，無人搭救。","notes":[]},{"n":30,"t":"你聘定了妻，別人必與她同房；你建造房屋，不得住在其內；你栽種葡萄園，也不得用其中的果子。","notes":[]},{"n":31,"t":"你的牛在你眼前宰了，你必不得吃牠的肉；你的驢在你眼前被搶奪，不得歸還；你的羊歸了仇敵，無人搭救。","notes":[]},{"n":32,"t":"你的兒女必歸與別國的民；你的眼目終日切望，甚至失明，你手中無力拯救。","notes":[]},{"n":33,"t":"你的土產和你勞碌得來的，必被你所不認識的國民吃盡。你時常被欺負，受壓制，","notes":[]},{"n":34,"t":"甚至你因眼中所看見的，必致瘋狂。","notes":[]},{"n":35,"t":"耶和華必攻擊你，使你膝上腿上，從腳掌到頭頂，長毒瘡無法醫治。","notes":[]},{"n":36,"t":"「耶和華必將你和你所立的王領到你和你列祖素不認識的國去；在那裏你必事奉木頭石頭的神。","notes":[]},{"n":37,"t":"你在耶和華領你到的各國中，要令人驚駭、笑談、譏誚。","notes":[]},{"n":38,"t":"你帶到田間的種子雖多，收進來的卻少，因為被蝗蟲吃了。","notes":[]},{"n":39,"t":"你栽種、修理葡萄園，卻不得收葡萄，也不得喝葡萄酒，因為被蟲子吃了。","notes":[]},{"n":40,"t":"你全境有橄欖樹，卻不得其油抹身，因為樹上的橄欖不熟自落了。","notes":[]},{"n":41,"t":"你生兒養女，卻不算是你的，因為必被擄去。","notes":[]},{"n":42,"t":"你所有的樹木和你地裏的出產必被蝗蟲所吃。","notes":[]},{"n":43,"t":"在你中間寄居的，必漸漸上升，比你高而又高；你必漸漸下降，低而又低。","notes":[]},{"n":44,"t":"他必借給你，你卻不能借給他；他必作首，你必作尾。","notes":[]},{"n":45,"t":"這一切咒詛必追隨你，趕上你，直到你滅亡；因為你不聽從耶和華－你神的話，不遵守他所吩咐的誡命律例。","notes":[]},{"n":46,"t":"這些咒詛必在你和你後裔的身上成為異蹟奇事，直到永遠！","notes":[]},{"n":47,"t":"「因為你富有的時候，不歡心樂意地事奉耶和華－你的神，","notes":[]},{"n":48,"t":"所以你必在飢餓、乾渴、赤露、缺乏之中事奉耶和華所打發來攻擊你的仇敵。他必把鐵軛加在你的頸項上，直到將你滅絕。","notes":[]},{"n":49,"t":"「耶和華要從遠方、地極帶一國的民，如鷹飛來攻擊你。這民的言語，你不懂得。","notes":[]},{"n":50,"t":"這民的面貌凶惡，不顧恤年老的，也不恩待年少的。","notes":[]},{"n":51,"t":"他們必吃你牲畜所下的和你地土所產的，直到你滅亡。你的五穀、新酒，和油，以及牛犢、羊羔，都不給你留下，直到將你滅絕。","notes":[]},{"n":52,"t":"他們必將你困在你各城裏，直到你所倚靠、高大堅固的城牆都被攻塌。他們必將你困在耶和華－你神所賜你遍地的各城裏。","notes":[]},{"n":53,"t":"你在仇敵圍困窘迫之中，必吃你本身所生的，就是耶和華－你神所賜給你的兒女之肉。","notes":[]},{"n":54,"t":"你們中間，柔弱嬌嫩的人必惡眼看他弟兄和他懷中的妻，並他餘剩的兒女；","notes":[]},{"n":55,"t":"甚至在你受仇敵圍困窘迫的城中，他要吃兒女的肉，不肯分一點給他的親人，因為他一無所剩。","notes":[]},{"n":56,"t":"你們中間，柔弱嬌嫩的婦人，是因嬌嫩柔弱不肯把腳踏地的，必惡眼看她懷中的丈夫和她的兒女。","notes":[]},{"n":57,"t":"她兩腿中間出來的嬰孩與她所要生的兒女，她因缺乏一切就要在你受仇敵圍困窘迫的城中將他們暗暗地吃了。","notes":[]},{"n":58,"t":"「這書上所寫律法的一切話是叫你敬畏耶和華－你神可榮可畏的名。你若不謹守遵行，耶和華就必將奇災，就是至大至長的災，至重至久的病，加在你和你後裔的身上，","notes":[],"end":59},{"n":60,"t":"也必使你所懼怕、埃及人的病都臨到你，貼在你身上，","notes":[]},{"n":61,"t":"又必將沒有寫在這律法書上的各樣疾病、災殃降在你身上，直到你滅亡。","notes":[]},{"n":62,"t":"你們先前雖然像天上的星那樣多，卻因不聽從耶和華－你神的話，所剩的人數就稀少了。","notes":[]},{"n":63,"t":"先前耶和華怎樣喜悅善待你們，使你們眾多，也要照樣喜悅毀滅你們，使你們滅亡；並且你們從所要進去得的地上必被拔除。","notes":[]},{"n":64,"t":"耶和華必使你們分散在萬民中，從地這邊到地那邊，你必在那裏事奉你和你列祖素不認識、木頭石頭的神。","notes":[]},{"n":65,"t":"在那些國中，你必不得安逸，也不得落腳之地；耶和華卻使你在那裏心中跳動，眼目失明，精神消耗。","notes":[]},{"n":66,"t":"你的性命必懸懸無定；你晝夜恐懼，自料性命難保。","notes":[]},{"n":67,"t":"你因心裏所恐懼的，眼中所看見的，早晨必說，巴不得到晚上才好；晚上必說，巴不得到早晨才好。","notes":[]},{"n":68,"t":"耶和華必使你坐船回埃及去，走我曾告訴你不得再見的路；在那裏你必賣己身與仇敵作奴婢，卻無人買。」","notes":[]}]},"29":{"heading":"在摩押跟以色列人立約","verses":[{"n":1,"t":"這是耶和華在摩押地吩咐摩西與以色列人立約的話，是在他和他們於何烈山所立的約之外。","notes":[]},{"n":2,"t":"摩西召了以色列眾人來，對他們說：「耶和華在埃及地，在你們眼前向法老和他眾臣僕，並他全地所行的一切事，你們都看見了，","notes":[]},{"n":3,"t":"就是你親眼看見的大試驗和神蹟，並那些大奇事。","notes":[]},{"n":4,"t":"但耶和華到今日沒有使你們心能明白，眼能看見，耳能聽見。","notes":[]},{"n":5,"t":"我領你們在曠野四十年，你們身上的衣服並沒有穿破，腳上的鞋也沒有穿壞。","notes":[]},{"n":6,"t":"你們沒有吃餅，也沒有喝清酒濃酒。這要使你們知道，耶和華是你們的神。","notes":[]},{"n":7,"t":"你們來到這地方，希實本王西宏、巴珊王噩都出來與我們交戰，我們就擊殺了他們，","notes":[]},{"n":8,"t":"取了他們的地給呂便支派、迦得支派，和瑪拿西半支派為業。","notes":[]},{"n":9,"t":"所以你們要謹守遵行這約的話，好叫你們在一切所行的事上亨通。","notes":[]},{"n":10,"t":"「今日，你們的首領、族長、長老、官長、以色列的男丁，你們的妻子兒女，和營中寄居的，以及為你們劈柴挑水的人，都站在耶和華－你們的神面前，","notes":["原文是支派"],"end":11},{"n":12,"t":"為要你順從耶和華－你神今日與你所立的約，向你所起的誓。","notes":[]},{"n":13,"t":"這樣，他要照他向你所應許的話，又向你列祖亞伯拉罕、以撒、雅各所起的誓，今日立你作他的子民，他作你的神。","notes":[]},{"n":14,"t":"我不但與你們立這約，起這誓，","notes":[]},{"n":15,"t":"凡與我們一同站在耶和華－我們神面前的，並今日不在我們這裏的人，我也與他們立這約，起這誓。","notes":[]},{"n":16,"t":"「我們曾住過埃及地，也從列國經過；這是你們知道的。","notes":[]},{"n":17,"t":"你們也看見他們中間可憎之物，並他們木、石、金、銀的偶像。","notes":[]},{"n":18,"t":"惟恐你們中間，或男或女，或族長或支派長，今日心裏偏離耶和華－我們的神，去事奉那些國的神；又怕你們中間有惡根生出苦菜和茵蔯來，","notes":[]},{"n":19,"t":"聽見這咒詛的話，心裏仍是自誇說：『我雖然行事心裏頑梗，連累眾人，卻還是平安。』","notes":[]},{"n":20,"t":"耶和華必不饒恕他；耶和華的怒氣與憤恨要向他發作，如煙冒出，將這書上所寫的一切咒詛都加在他身上。耶和華又要從天下塗抹他的名，","notes":[]},{"n":21,"t":"也必照著寫在律法書上、約中的一切咒詛將他從以色列眾支派中分別出來，使他受禍。","notes":[]},{"n":22,"t":"你們的後代，就是以後興起來的子孫，和遠方來的外人，看見這地的災殃，並耶和華所降與這地的疾病，","notes":[]},{"n":23,"t":"又看見遍地有硫磺，有鹽鹵，有火跡，沒有耕種，沒有出產，連草都不生長－好像耶和華在忿怒中所傾覆的所多瑪、蛾摩拉、押瑪、洗扁一樣－","notes":[]},{"n":24,"t":"所看見的人，連萬國人，都必問說：『耶和華為何向此地這樣行呢？這樣大發烈怒是甚麼意思呢？』","notes":[]},{"n":25,"t":"人必回答說：『是因這地的人離棄了耶和華－他們列祖的神，領他們出埃及地的時候與他們所立的約，","notes":[]},{"n":26,"t":"去事奉敬拜素不認識的別神，是耶和華所未曾給他們安排的。","notes":[]},{"n":27,"t":"所以耶和華的怒氣向這地發作，將這書上所寫的一切咒詛都降在這地上。","notes":[]},{"n":28,"t":"耶和華在怒氣、忿怒、大惱恨中將他們從本地拔出來，扔在別的地上，像今日一樣。』","notes":[]},{"n":29,"t":"「隱祕的事是屬耶和華－我們神的；惟有明顯的事是永遠屬我們和我們子孫的，好叫我們遵行這律法上的一切話。」","notes":[]}]},"30":{"heading":"復興和蒙福的條件","verses":[{"n":1,"t":"「我所陳明在你面前的這一切咒詛都臨到你身上；你在耶和華－你神追趕你到的萬國中必心裏追念祝福的話；","notes":[]},{"n":2,"t":"你和你的子孫若盡心盡性歸向耶和華－你的神，照著我今日一切所吩咐的聽從他的話；","notes":[]},{"n":3,"t":"那時，耶和華－你的神必憐恤你，救回你這被擄的子民；耶和華－你的神要回轉過來，從分散你到的萬民中將你招聚回來。","notes":[]},{"n":4,"t":"你被趕散的人，就是在天涯的，耶和華－你的神也必從那裏將你招聚回來。","notes":[]},{"n":5,"t":"耶和華－你的神必領你進入你列祖所得的地，使你可以得著；又必善待你，使你的人數比你列祖眾多。","notes":[]},{"n":6,"t":"耶和華－你神必將你心裏和你後裔心裏的污穢除掉，好叫你盡心盡性愛耶和華－你的神，使你可以存活。","notes":[]},{"n":7,"t":"耶和華－你的神必將這一切咒詛加在你仇敵和恨惡你、逼迫你的人身上。","notes":[]},{"n":8,"t":"你必歸回，聽從耶和華的話，遵行他的一切誡命，就是我今日所吩咐你的。","notes":[]},{"n":9,"t":"你若聽從耶和華－你神的話，謹守這律法書上所寫的誡命律例，又盡心盡性歸向耶和華－你的神，他必使你手裏所辦的一切事，並你身所生的，牲畜所下的，地土所產的，都綽綽有餘；因為耶和華必再喜悅你，降福與你，像從前喜悅你列祖一樣。","notes":[],"end":10},{"n":11,"t":"「我今日所吩咐你的誡命不是你難行的，也不是離你遠的；","notes":[]},{"n":12,"t":"不是在天上，使你說：『誰替我們上天取下來，使我們聽見可以遵行呢？』","notes":[]},{"n":13,"t":"也不是在海外，使你說：『誰替我們過海取了來，使我們聽見可以遵行呢？』","notes":[]},{"n":14,"t":"這話卻離你甚近，就在你口中，在你心裏，使你可以遵行。","notes":[]},{"n":15,"t":"「看哪，我今日將生與福，死與禍，陳明在你面前。","notes":[]},{"n":16,"t":"吩咐你愛耶和華－你的神，遵行他的道，謹守他的誡命、律例、典章，使你可以存活，人數增多，耶和華－你神就必在你所要進去得為業的地上賜福與你。","notes":[]},{"n":17,"t":"倘若你心裏偏離，不肯聽從，卻被勾引去敬拜事奉別神，","notes":[]},{"n":18,"t":"我今日明明告訴你們，你們必要滅亡；在你過約旦河、進去得為業的地上，你的日子必不長久。","notes":[]},{"n":19,"t":"我今日呼天喚地向你作見證；我將生死禍福陳明在你面前，所以你要揀選生命，使你和你的後裔都得存活；","notes":[]},{"n":20,"t":"且愛耶和華－你的神，聽從他的話，專靠他；因為他是你的生命，你的日子長久也在乎他。這樣，你就可以在耶和華向你列祖亞伯拉罕、以撒、雅各起誓應許所賜的地上居住。」","notes":[]}]},"31":{"heading":"約書亞繼承摩西","verses":[{"n":1,"t":"摩西去告訴以色列眾人","notes":[]},{"n":2,"t":"說：「我現在一百二十歲了，不能照常出入；耶和華也曾對我說：『你必不得過這約旦河。』","notes":[]},{"n":3,"t":"耶和華－你們的神必引導你們過去，將這些國民在你們面前滅絕，你們就得他們的地。約書亞必引導你們過去，正如耶和華所說的。","notes":[]},{"n":4,"t":"耶和華必待他們，如同從前待他所滅絕的亞摩利二王西宏與噩以及他們的國一樣。","notes":[]},{"n":5,"t":"耶和華必將他們交給你們；你們要照我所吩咐的一切命令待他們。","notes":[]},{"n":6,"t":"你們當剛強壯膽，不要害怕，也不要畏懼他們，因為耶和華－你的神和你同去。他必不撇下你，也不丟棄你。」","notes":[]},{"n":7,"t":"摩西召了約書亞來，在以色列眾人眼前對他說：「你當剛強壯膽！因為，你要和這百姓一同進入耶和華向他們列祖起誓應許所賜之地；你也要使他們承受那地為業。","notes":[]},{"n":8,"t":"耶和華必在你前面行；他必與你同在，必不撇下你，也不丟棄你。不要懼怕，也不要驚惶。」","notes":[]},{"n":9,"t":"摩西將這律法寫出來，交給抬耶和華約櫃的祭司利未子孫和以色列的眾長老。","notes":[],"heads":["每七年誦讀律法一次"]},{"n":10,"t":"摩西吩咐他們說：「每逢七年的末一年，就在豁免年的定期住棚節的時候，","notes":[]},{"n":11,"t":"以色列眾人來到耶和華－你神所選擇的地方朝見他。那時，你要在以色列眾人面前將這律法念給他們聽。","notes":[]},{"n":12,"t":"要招聚他們男、女、孩子，並城裏寄居的，使他們聽，使他們學習，好敬畏耶和華－你們的神，謹守、遵行這律法的一切話，","notes":[]},{"n":13,"t":"也使他們未曾曉得這律法的兒女得以聽見，學習敬畏耶和華－你們的神，在你們過約旦河要得為業之地，存活的日子，常常這樣行。」","notes":[]},{"n":14,"t":"耶和華對摩西說：「你的死期臨近了；要召約書亞來，你們二人站在會幕裏，我好囑咐他。」於是摩西和約書亞去站在會幕裏。","notes":[],"heads":["對摩西和約書亞的最後囑咐"]},{"n":15,"t":"耶和華在會幕裏雲柱中顯現，雲柱停在會幕門以上。","notes":[]},{"n":16,"t":"耶和華又對摩西說：「你必和你列祖同睡。這百姓要起來，在他們所要去的地上，在那地的人中，隨從外邦神行邪淫，離棄我，違背我與他們所立的約。","notes":[]},{"n":17,"t":"那時，我的怒氣必向他們發作；我也必離棄他們，掩面不顧他們，以致他們被吞滅，並有許多的禍患災難臨到他們。那日他們必說：『這些禍患臨到我們，豈不是因我們的神不在我們中間嗎？』","notes":[]},{"n":18,"t":"那時，因他們偏向別神所行的一切惡，我必定掩面不顧他們。","notes":[]},{"n":19,"t":"現在你要寫一篇歌，教導以色列人，傳給他們，使這歌見證他們的不是；","notes":[]},{"n":20,"t":"因為我將他們領進我向他們列祖起誓應許那流奶與蜜之地，他們在那裏吃得飽足，身體肥胖，就必偏向別神，事奉他們，藐視我，背棄我的約。","notes":[]},{"n":21,"t":"那時，有許多禍患災難臨到他們，這歌必在他們面前作見證，他們後裔的口中必念誦不忘。我未領他們到我所起誓應許之地以先，他們所懷的意念我都知道了。」","notes":[]},{"n":22,"t":"當日摩西就寫了一篇歌，教導以色列人。","notes":[]},{"n":23,"t":"耶和華囑咐嫩的兒子約書亞說：「你當剛強壯膽，因為你必領以色列人進我所起誓應許他們的地；我必與你同在。」","notes":[]},{"n":24,"t":"摩西將這律法的話寫在書上，及至寫完了，","notes":[]},{"n":25,"t":"就吩咐抬耶和華約櫃的利未人說：","notes":[]},{"n":26,"t":"「將這律法書放在耶和華－你們神的約櫃旁，可以在那裏見證以色列人的不是；","notes":[]},{"n":27,"t":"因為我知道你們是悖逆的，是硬著頸項的。我今日還活著與你們同在，你們尚且悖逆耶和華，何況我死後呢？","notes":[]},{"n":28,"t":"你們要將你們支派的眾長老和官長都招聚了來，我好將這些話說與他們聽，並呼天喚地見證他們的不是。","notes":[]},{"n":29,"t":"我知道我死後，你們必全然敗壞，偏離我所吩咐你們的道，行耶和華眼中看為惡的事，以手所做的惹他發怒；日後必有禍患臨到你們。」","notes":[]},{"n":30,"t":"摩西將這一篇歌的話都說與以色列全會眾聽。","notes":[],"heads":["摩西的歌"]}]},"32":{"heading":"摩西的最後訓言","verses":[{"n":1,"t":"諸天哪，側耳，我要說話；願地也聽我口中的言語。","notes":[]},{"n":2,"t":"我的教訓要淋漓如雨；我的言語要滴落如露，如細雨降在嫩草上，如甘霖降在菜蔬中。","notes":[]},{"n":3,"t":"我要宣告耶和華的名；你們要將大德歸與我們的神。","notes":[]},{"n":4,"t":"他是磐石，他的作為完全；他所行的無不公平，是誠實無偽的神，又公義，又正直。","notes":[]},{"n":5,"t":"這乖僻彎曲的世代向他行事邪僻；有這弊病就不是他的兒女。","notes":[]},{"n":6,"t":"愚昧無知的民哪，你們這樣報答耶和華嗎？他豈不是你的父、將你買來的嗎？他是製造你、建立你的。","notes":[]},{"n":7,"t":"你當追想上古之日，思念歷代之年；問你的父親，他必指示你；問你的長者，他必告訴你。","notes":[]},{"n":8,"t":"至高者將地業賜給列邦，將世人分開，就照以色列人的數目立定萬民的疆界。","notes":[]},{"n":9,"t":"耶和華的分本是他的百姓；他的產業本是雅各。","notes":[]},{"n":10,"t":"耶和華遇見他在曠野－荒涼野獸吼叫之地，就環繞他，看顧他，保護他，如同保護眼中的瞳人。","notes":[]},{"n":11,"t":"又如鷹攪動巢窩，在雛鷹以上兩翅搧展，接取雛鷹，背在兩翼之上。","notes":[]},{"n":12,"t":"這樣，耶和華獨自引導他，並無外邦神與他同在。","notes":[]},{"n":13,"t":"耶和華使他乘駕地的高處，得吃田間的土產；又使他從磐石中咂蜜，從堅石中吸油；","notes":[]},{"n":14,"t":"也吃牛的奶油，羊的奶，羊羔的脂油，巴珊所出的公綿羊和山羊，與上好的麥子，也喝葡萄汁釀的酒。","notes":[]},{"n":15,"t":"但耶書崙漸漸肥胖，粗壯，光潤，踢跳，奔跑，便離棄造他的神，輕看救他的磐石；","notes":[]},{"n":16,"t":"敬拜別神，觸動神的憤恨，行可憎惡的事，惹了他的怒氣。","notes":[]},{"n":17,"t":"所祭祀的鬼魔並非真神，乃是素不認識的神，是近來新興的，是你列祖所不畏懼的。","notes":[]},{"n":18,"t":"你輕忽生你的磐石，忘記產你的神。","notes":[]},{"n":19,"t":"耶和華看見他的兒女惹動他，就厭惡他們，說：","notes":[]},{"n":20,"t":"我要向他們掩面，看他們的結局如何。他們本是極乖僻的族類，心中無誠實的兒女。","notes":[]},{"n":21,"t":"他們以那「不算為神」的觸動我的憤恨，以虛無的神惹了我的怒氣。我也要以那「不成子民」的觸動他們的憤恨，以愚昧的國民惹了他們的怒氣。","notes":[]},{"n":22,"t":"因為在我怒中有火燒起，直燒到極深的陰間，把地和地的出產盡都焚燒，山的根基也燒著了。","notes":[]},{"n":23,"t":"我要將禍患堆在他們身上，把我的箭向他們射盡。","notes":[]},{"n":24,"t":"他們必因飢餓消瘦，被炎熱苦毒吞滅。我要打發野獸用牙齒咬他們，並土中腹行的，用毒氣害他們。","notes":[]},{"n":25,"t":"外頭有刀劍，內室有驚恐，使人喪亡，使少男、童女、吃奶的、白髮的，盡都滅絕。","notes":[]},{"n":26,"t":"我說，我必將他們分散遠方，使他們的名號從人間除滅。","notes":[]},{"n":27,"t":"惟恐仇敵惹動我，只怕敵人錯看，說：是我們手的能力，並非耶和華所行的。","notes":[]},{"n":28,"t":"因為以色列民毫無計謀，心中沒有聰明。","notes":[]},{"n":29,"t":"惟願他們有智慧，能明白這事，肯思念他們的結局。","notes":[]},{"n":30,"t":"若不是他們的磐石賣了他們，若不是耶和華交出他們，一人焉能追趕他們千人？二人焉能使萬人逃跑呢？","notes":[]},{"n":31,"t":"據我們的仇敵自己斷定，他們的磐石不如我們的磐石。","notes":[]},{"n":32,"t":"他們的葡萄樹是所多瑪的葡萄樹，蛾摩拉田園所生的；他們的葡萄是毒葡萄，全掛都是苦的。","notes":[]},{"n":33,"t":"他們的酒是大蛇的毒氣，是虺蛇殘害的惡毒。","notes":[]},{"n":34,"t":"這不都是積蓄在我這裏，封鎖在我府庫中嗎？","notes":[]},{"n":35,"t":"他們失腳的時候，伸冤報應在我；因他們遭災的日子近了；那要臨在他們身上的必速速來到。","notes":[]},{"n":36,"t":"耶和華見他百姓毫無能力，無論困住的、自由的都沒有剩下，就必為他們伸冤，為他的僕人後悔。","notes":[]},{"n":37,"t":"他必說：他們的神，他們所投靠的磐石，","notes":[]},{"n":38,"t":"就是向來吃他們祭牲的脂油，喝他們奠祭之酒的，在哪裏呢？他可以興起幫助你們，護衛你們。","notes":[]},{"n":39,"t":"你們如今要知道：我，惟有我是神；在我以外並無別神。我使人死，我使人活；我損傷，我也醫治，並無人能從我手中救出來。","notes":[]},{"n":40,"t":"我向天舉手說：我憑我的永生起誓：","notes":[]},{"n":41,"t":"我若磨我閃亮的刀，手掌審判之權，就必報復我的敵人，報應恨我的人。","notes":[]},{"n":42,"t":"我要使我的箭飲血飲醉，就是被殺被擄之人的血。我的刀要吃肉，乃是仇敵中首領之頭的肉。","notes":[]},{"n":43,"t":"你們外邦人當與主的百姓一同歡呼；因他要伸他僕人流血的冤，報應他的敵人，潔淨他的地，救贖他的百姓。","notes":[]},{"n":44,"t":"摩西和嫩的兒子約書亞去將這歌的一切話說給百姓聽。","notes":[]},{"n":45,"t":"摩西向以色列眾人說完了這一切的話，","notes":[]},{"n":46,"t":"又說：「我今日所警教你們的，你們都要放在心上；要吩咐你們的子孫謹守遵行這律法上的話。","notes":[]},{"n":47,"t":"因為這不是虛空、與你們無關的事，乃是你們的生命；在你們過約旦河要得為業的地上必因這事日子得以長久。」","notes":[]},{"n":48,"t":"當日，耶和華吩咐摩西說：","notes":[]},{"n":49,"t":"「你上這亞巴琳山中的尼波山去，在摩押地與耶利哥相對，觀看我所要賜給以色列人為業的迦南地。","notes":[]},{"n":50,"t":"你必死在你所登的山上，歸你列祖去，像你哥哥亞倫死在何珥山上，歸他的列祖一樣。","notes":["原文是本民"]},{"n":51,"t":"因為你們在尋的曠野，加低斯的米利巴水，在以色列人中沒有尊我為聖，得罪了我。","notes":[]},{"n":52,"t":"我所賜給以色列人的地，你可以遠遠地觀看，卻不得進去。」","notes":[]}]},"33":{"heading":"摩西祝福以色列眾支派","verses":[{"n":1,"t":"以下是神人摩西在未死之先為以色列人所祝的福：","notes":[]},{"n":2,"t":"他說：耶和華從西奈而來，從西珥向他們顯現，從巴蘭山發出光輝，從萬萬聖者中來臨，從他右手為百姓傳出烈火的律法。","notes":[]},{"n":3,"t":"他疼愛百姓；眾聖徒都在他手中。他們坐在他的腳下，領受他的言語。","notes":[]},{"n":4,"t":"摩西將律法傳給我們，作為雅各會眾的產業。","notes":[]},{"n":5,"t":"百姓的眾首領，以色列的各支派，一同聚會的時候，耶和華在耶書崙中為王。","notes":["原文是他"]},{"n":6,"t":"願呂便存活，不致死亡；願他人數不致稀少。","notes":[]},{"n":7,"t":"為猶大祝福說：求耶和華俯聽猶大的聲音，引導他歸於本族；他曾用手為自己爭戰，你必幫助他攻擊敵人。","notes":[]},{"n":8,"t":"論利未說：耶和華啊，你的土明和烏陵都在你的虔誠人那裏。你在瑪撒曾試驗他，在米利巴水與他爭論。","notes":[]},{"n":9,"t":"他論自己的父母說：我未曾看見；他也不承認弟兄，也不認識自己的兒女。這是因利未人遵行你的話，謹守你的約。","notes":[]},{"n":10,"t":"他們要將你的典章教訓雅各，將你的律法教訓以色列。他們要把香焚在你面前，把全牲的燔祭獻在你的壇上。","notes":[]},{"n":11,"t":"求耶和華降福在他的財物上，悅納他手裏所辦的事。那些起來攻擊他和恨惡他的人，願你刺透他們的腰，使他們不得再起來。","notes":[]},{"n":12,"t":"論便雅憫說：耶和華所親愛的必同耶和華安然居住；耶和華終日遮蔽他，也住在他兩肩之中。","notes":[]},{"n":13,"t":"論約瑟說：願他的地蒙耶和華賜福，得天上的寶物、甘露，以及地裏所藏的泉水；","notes":[]},{"n":14,"t":"得太陽所曬熟的美果，月亮所養成的寶物；","notes":[]},{"n":15,"t":"得上古之山的至寶，永世之嶺的寶物；","notes":[]},{"n":16,"t":"得地和其中所充滿的寶物，並住荊棘中上主的喜悅。願這些福都歸於約瑟的頭上，歸於那與弟兄迥別之人的頂上。","notes":[]},{"n":17,"t":"他為牛群中頭生的，有威嚴；他的角是野牛的角，用以牴觸萬邦，直到地極。這角是以法蓮的萬萬，瑪拿西的千千。","notes":[]},{"n":18,"t":"論西布倫說：西布倫哪，你出外可以歡喜。以薩迦啊，在你帳棚裏可以快樂。","notes":[]},{"n":19,"t":"他們要將列邦召到山上，在那裏獻公義的祭；因為他們要吸取海裏的豐富，並沙中所藏的珍寶。","notes":[]},{"n":20,"t":"論迦得說：使迦得擴張的應當稱頌！迦得住如母獅；他撕裂膀臂，連頭頂也撕裂。","notes":[]},{"n":21,"t":"他為自己選擇頭一段地，因在那裏有設立律法者的分存留。他與百姓的首領同來；他施行耶和華的公義和耶和華與以色列所立的典章。","notes":[]},{"n":22,"t":"論但說：但為小獅子，從巴珊跳出來。","notes":[]},{"n":23,"t":"論拿弗他利說：拿弗他利啊，你足沾恩惠，滿得耶和華的福，可以得西方和南方為業。","notes":[]},{"n":24,"t":"論亞設說：願亞設享受多子的福樂，得他弟兄的喜悅，可以把腳蘸在油中。","notes":[]},{"n":25,"t":"你的門閂是銅的，鐵的。你的日子如何，你的力量也必如何。","notes":["或譯：鞋"]},{"n":26,"t":"耶書崙哪，沒有能比神的。他為幫助你，乘在天空，顯其威榮，駕行穹蒼。","notes":[]},{"n":27,"t":"永生的神是你的居所；他永久的膀臂在你以下。他在你前面攆出仇敵，說：毀滅吧。","notes":[]},{"n":28,"t":"以色列安然居住；雅各的本源獨居五穀新酒之地。他的天也滴甘露。","notes":[]},{"n":29,"t":"以色列啊，你是有福的！誰像你這蒙耶和華所拯救的百姓呢？他是你的盾牌，幫助你，是你威榮的刀劍。你的仇敵必投降你；你必踏在他們的高處。","notes":[]}]},"34":{"heading":"摩西去世","verses":[{"n":1,"t":"摩西從摩押平原登尼波山，上了那與耶利哥相對的毗斯迦山頂。耶和華把基列全地直到但，","notes":[]},{"n":2,"t":"拿弗他利全地，以法蓮、瑪拿西的地，猶大全地直到西海，","notes":[]},{"n":3,"t":"南地和棕樹城耶利哥的平原，直到瑣珥，都指給他看。","notes":[]},{"n":4,"t":"耶和華對他說：「這就是我向亞伯拉罕、以撒、雅各起誓應許之地，說：『我必將這地賜給你的後裔。』現在我使你眼睛看見了，你卻不得過到那裏去。」","notes":[]},{"n":5,"t":"於是，耶和華的僕人摩西死在摩押地，正如耶和華所說的。","notes":[]},{"n":6,"t":"耶和華將他埋葬在摩押地、伯‧毗珥對面的谷中，只是到今日沒有人知道他的墳墓。","notes":[]},{"n":7,"t":"摩西死的時候年一百二十歲；眼目沒有昏花，精神沒有衰敗。","notes":[]},{"n":8,"t":"以色列人在摩押平原為摩西哀哭了三十日，為摩西居喪哀哭的日子就滿了。","notes":[]},{"n":9,"t":"嫩的兒子約書亞；因為摩西曾按手在他頭上，就被智慧的靈充滿，以色列人便聽從他，照著耶和華吩咐摩西的行了。","notes":[]},{"n":10,"t":"以後以色列中再沒有興起先知像摩西的。他是耶和華面對面所認識的。","notes":[]},{"n":11,"t":"耶和華打發他在埃及地向法老和他的一切臣僕，並他的全地，行各樣神蹟奇事，","notes":[]},{"n":12,"t":"又在以色列眾人眼前顯大能的手，行一切大而可畏的事。","notes":[]}]}},"JOS":{"1":{"heading":"神命令約書亞征服迦南","verses":[{"n":1,"t":"耶和華的僕人摩西死了以後，耶和華曉諭摩西的幫手，嫩的兒子約書亞，說：","notes":[]},{"n":2,"t":"「我的僕人摩西死了。現在你要起來，和眾百姓過這約旦河，往我所要賜給以色列人的地去。","notes":[]},{"n":3,"t":"凡你們腳掌所踏之地，我都照著我所應許摩西的話賜給你們了。","notes":[]},{"n":4,"t":"從曠野和這黎巴嫩，直到幼發拉底大河，赫人的全地，又到大海日落之處，都要作你們的境界。","notes":[]},{"n":5,"t":"你平生的日子，必無一人能在你面前站立得住。我怎樣與摩西同在，也必照樣與你同在；我必不撇下你，也不丟棄你。","notes":[]},{"n":6,"t":"你當剛強壯膽！因為你必使這百姓承受那地為業，就是我向他們列祖起誓應許賜給他們的地。","notes":[]},{"n":7,"t":"只要剛強，大大壯膽，謹守遵行我僕人摩西所吩咐你的一切律法，不可偏離左右，使你無論往哪裏去，都可以順利。","notes":[]},{"n":8,"t":"這律法書不可離開你的口，總要晝夜思想，好使你謹守遵行這書上所寫的一切話。如此，你的道路就可以亨通，凡事順利。","notes":[]},{"n":9,"t":"我豈沒有吩咐你嗎？你當剛強壯膽！不要懼怕，也不要驚惶；因為你無論往哪裏去，耶和華－你的神必與你同在。」","notes":[]},{"n":10,"t":"於是，約書亞吩咐百姓的官長說：","notes":[],"heads":["約書亞吩咐百姓準備渡河"]},{"n":11,"t":"「你們要走遍營中，吩咐百姓說：『當預備食物；因為三日之內你們要過這約旦河，進去得耶和華－你們神賜你們為業之地。』」","notes":[]},{"n":12,"t":"約書亞對呂便人、迦得人，和瑪拿西半支派的人說：","notes":[]},{"n":13,"t":"「你們要追念耶和華的僕人摩西所吩咐你們的話說：『耶和華－你們的神使你們得享平安，也必將這地賜給你們。』","notes":[]},{"n":14,"t":"你們的妻子、孩子，和牲畜都可以留在約旦河東、摩西所給你們的地；但你們中間一切大能的勇士都要帶著兵器在你們的弟兄前面過去，幫助他們，","notes":[]},{"n":15,"t":"等到耶和華使你們的弟兄像你們一樣得享平安，並且得著耶和華－你們神所賜他們為業之地，那時才可以回你們所得之地，承受為業，就是耶和華的僕人摩西在約旦河東、向日出之地所給你們的。」","notes":[]},{"n":16,"t":"他們回答約書亞說：「你所吩咐我們行的，我們都必行；你所差遣我們去的，我們都必去。","notes":[]},{"n":17,"t":"我們從前在一切事上怎樣聽從摩西，現在也必照樣聽從你；惟願耶和華－你的神與你同在，像與摩西同在一樣。","notes":[]},{"n":18,"t":"無論甚麼人違背你的命令，不聽從你所吩咐他的一切話，就必治死他。你只要剛強壯膽！」","notes":[]}]},"2":{"heading":"約書亞派探子進耶利哥","verses":[{"n":1,"t":"當下，嫩的兒子約書亞從什亭暗暗打發兩個人作探子，吩咐說：「你們去窺探那地和耶利哥。」於是二人去了，來到一個妓女名叫喇合的家裏，就在那裏躺臥。","notes":[]},{"n":2,"t":"有人告訴耶利哥王說：「今夜有以色列人來到這裏窺探此地。」","notes":[]},{"n":3,"t":"耶利哥王打發人去見喇合說：「那來到你這裏、進了你家的人要交出來，因為他們來窺探全地。」","notes":[]},{"n":4,"t":"女人將二人隱藏，就回答說：「那人果然到我這裏來；他們是哪裏來的我卻不知道。","notes":[]},{"n":5,"t":"天黑、要關城門的時候，他們出去了，往哪裏去我卻不知道。你們快快地去追趕，就必追上。」（","notes":[]},{"n":6,"t":"先是女人領二人上了房頂，將他們藏在那裏所擺的麻稭中。）","notes":[]},{"n":7,"t":"那些人就往約旦河的渡口追趕他們去了。追趕他們的人一出去，城門就關了。","notes":[]},{"n":8,"t":"二人還沒有躺臥，女人就上房頂，到他們那裏，","notes":[]},{"n":9,"t":"對他們說：「我知道耶和華已經把這地賜給你們，並且因你們的緣故我們都驚慌了。這地的一切居民在你們面前心都消化了；","notes":[]},{"n":10,"t":"因為我們聽見你們出埃及的時候，耶和華怎樣在你們前面使紅海的水乾了，並且你們怎樣待約旦河東的兩個亞摩利王西宏和噩，將他們盡行毀滅。","notes":[]},{"n":11,"t":"我們一聽見這些事，心就消化了。因你們的緣故，並無一人有膽氣。耶和華－你們的神本是上天下地的神。","notes":[]},{"n":12,"t":"現在我既是恩待你們，求你們指著耶和華向我起誓，也要恩待我父家，並給我一個實在的證據，","notes":[]},{"n":13,"t":"要救活我的父母、弟兄、姊妹，和一切屬他們的，拯救我們性命不死。」","notes":[]},{"n":14,"t":"二人對她說：「你若不洩漏我們這件事，我們情願替你們死。耶和華將這地賜給我們的時候，我們必以慈愛誠實待你。」","notes":[]},{"n":15,"t":"於是女人用繩子將二人從窗戶裏縋下去；因她的房子是在城牆邊上，她也住在城牆上。","notes":[]},{"n":16,"t":"她對他們說：「你們且往山上去，恐怕追趕的人碰見你們；要在那裏隱藏三天，等追趕的人回來，然後才可以走你們的路。」","notes":[]},{"n":17,"t":"二人對她說：「你要這樣行。不然，你叫我們所起的誓就與我們無干了。","notes":[]},{"n":18,"t":"我們來到這地的時候，你要把這條朱紅線繩繫在縋我們下去的窗戶上，並要使你的父母、弟兄，和你父的全家都聚集在你家中。","notes":[]},{"n":19,"t":"凡出了你家門往街上去的，他的罪 必歸到自己的頭上，與我們無干了。凡在你家裏的，若有人下手害他，流他血的罪就歸到我們的頭上。","notes":["原文是血"]},{"n":20,"t":"你若洩漏我們這件事，你叫我們所起的誓就與我們無干了。」","notes":[]},{"n":21,"t":"女人說：「照你們的話行吧！」於是打發他們去了，又把朱紅線繩繫在窗戶上。","notes":[]},{"n":22,"t":"二人到山上，在那裏住了三天，等著追趕的人回去了。追趕的人一路找他們，卻找不著。","notes":[]},{"n":23,"t":"二人就下山回來，過了河，到嫩的兒子約書亞那裏，向他述說所遭遇的一切事；","notes":[]},{"n":24,"t":"又對約書亞說：「耶和華果然將那全地交在我們手中；那地的一切居民在我們面前心都消化了。」","notes":[]}]},"3":{"heading":"以色列人過約旦河","verses":[{"n":1,"t":"約書亞清早起來，和以色列眾人都離開什亭，來到約旦河，就住在那裏，等候過河。","notes":[]},{"n":2,"t":"過了三天，官長走遍營中，","notes":[]},{"n":3,"t":"吩咐百姓說：「你們看見耶和華－你們神的約櫃，又見祭司利未人抬著，就要離開所住的地方，跟著約櫃去。","notes":[]},{"n":4,"t":"只是你們和約櫃相離要量二千肘，不可與約櫃相近，使你們知道所當走的路，因為這條路你們向來沒有走過。」","notes":[]},{"n":5,"t":"約書亞吩咐百姓說：「你們要自潔，因為明天耶和華必在你們中間行奇事。」","notes":[]},{"n":6,"t":"約書亞又吩咐祭司說：「你們抬起約櫃，在百姓前頭過去。」於是他們抬起約櫃，在百姓前頭走。","notes":[]},{"n":7,"t":"耶和華對約書亞說：「從今日起，我必使你在以色列眾人眼前尊大，使他們知道我怎樣與摩西同在，也必照樣與你同在。","notes":[]},{"n":8,"t":"你要吩咐抬約櫃的祭司說：『你們到了約旦河的水邊上，就要在約旦河水裏站住。』」","notes":[]},{"n":9,"t":"約書亞對以色列人說：「你們近前來，聽耶和華－你們神的話。」","notes":[]},{"n":10,"t":"約書亞說：「看哪，普天下主的約櫃必在你們前頭過去，到約旦河裏，因此你們就知道在你們中間有永生神；並且他必在你們面前趕出迦南人、赫人、希未人、比利洗人、革迦撒人、亞摩利人、耶布斯人。","notes":[],"end":11},{"n":12,"t":"你們現在要從以色列支派中揀選十二個人，每支派一人，","notes":[]},{"n":13,"t":"等到抬普天下主耶和華約櫃的祭司把腳站在約旦河水裏，約旦河的水，就是從上往下流的水，必然斷絕，立起成壘。」","notes":[]},{"n":14,"t":"百姓離開帳棚要過約旦河的時候，抬約櫃的祭司乃在百姓的前頭。","notes":[]},{"n":15,"t":"他們到了約旦河，腳一入水（原來約旦河水在收割的日子漲過兩岸），","notes":[]},{"n":16,"t":"那從上往下流的水便在極遠之地、撒拉但旁的亞當城那裏停住，立起成壘；那往亞拉巴的海，就是鹽海，下流的水全然斷絕。於是百姓在耶利哥的對面過去了。","notes":[]},{"n":17,"t":"抬耶和華約櫃的祭司在約旦河中的乾地上站定，以色列眾人都從乾地上過去，直到國民盡都過了約旦河。","notes":[]}]},"4":{"heading":"立石為記","verses":[{"n":1,"t":"國民盡都過了約旦河，耶和華就對約書亞說：","notes":[]},{"n":2,"t":"「你從民中要揀選十二個人，每支派一人，","notes":[]},{"n":3,"t":"吩咐他們說：『你們從這裏，從約旦河中、祭司腳站定的地方，取十二塊石頭帶過去，放在你們今夜要住宿的地方。』」","notes":[]},{"n":4,"t":"於是，約書亞將他從以色列人中所預備的那十二個人，每支派一人，都召了來。","notes":[]},{"n":5,"t":"對他們說：「你們下約旦河中，過到耶和華－你們神的約櫃前頭，按著以色列人十二支派的數目，每人取一塊石頭扛在肩上。","notes":[]},{"n":6,"t":"這些石頭在你們中間可以作為證據。日後，你們的子孫問你們說：『這些石頭是甚麼意思？』","notes":[]},{"n":7,"t":"你們就對他們說：『這是因為約旦河的水在耶和華的約櫃前斷絕；約櫃過約旦河的時候，約旦河的水就斷絕了。這些石頭要作以色列人永遠的紀念。』」","notes":[]},{"n":8,"t":"以色列人就照約書亞所吩咐的，按著以色列人支派的數目，從約旦河中取了十二塊石頭，都遵耶和華所吩咐約書亞的行了。他們把石頭帶過去，到他們所住宿的地方，就放在那裏。","notes":[]},{"n":9,"t":"約書亞另把十二塊石頭立在約旦河中，在抬約櫃的祭司腳站立的地方；直到今日，那石頭還在那裏。","notes":[]},{"n":10,"t":"抬約櫃的祭司站在約旦河中，等到耶和華曉諭約書亞吩咐百姓的事辦完了，是照摩西所吩咐約書亞的一切話。於是百姓急速過去了。","notes":[]},{"n":11,"t":"眾百姓盡都過了河，耶和華的約櫃和祭司就在百姓面前過去。","notes":[]},{"n":12,"t":"呂便人、迦得人、瑪拿西半支派的人都照摩西所吩咐他們的，帶著兵器在以色列人前頭過去。","notes":[]},{"n":13,"t":"約有四萬人都準備打仗，在耶和華面前過去，到耶利哥的平原，等候上陣。","notes":[]},{"n":14,"t":"當那日，耶和華使約書亞在以色列眾人眼前尊大。在他平生的日子，百姓敬畏他，像從前敬畏摩西一樣。","notes":[]},{"n":15,"t":"耶和華曉諭約書亞說：","notes":[]},{"n":16,"t":"「你吩咐抬法櫃的祭司從約旦河裏上來。」","notes":[]},{"n":17,"t":"約書亞就吩咐祭司說：「你們從約旦河裏上來。」","notes":[]},{"n":18,"t":"抬耶和華約櫃的祭司從約旦河裏上來，腳掌剛落旱地，約旦河的水就流到原處，仍舊漲過兩岸。","notes":[]},{"n":19,"t":"正月初十日，百姓從約旦河裏上來，就在吉甲，在耶利哥的東邊安營。","notes":[]},{"n":20,"t":"他們從約旦河中取來的那十二塊石頭，約書亞就立在吉甲，","notes":[]},{"n":21,"t":"對以色列人說：「日後你們的子孫問他們的父親說：『這些石頭是甚麼意思？』","notes":[]},{"n":22,"t":"你們就告訴他們說：『以色列人曾走乾地過這約旦河；","notes":[]},{"n":23,"t":"因為耶和華－你們的神在你們前面使約旦河的水乾了，等著你們過來，就如耶和華－你們的神從前在我們前面使紅海乾了，等著我們過來一樣，","notes":[]},{"n":24,"t":"要使地上萬民都知道，耶和華的手大有能力，也要使你們永遠敬畏耶和華－你們的神。』」","notes":[]}]},"5":{"heading":"在吉甲行割禮","verses":[{"n":1,"t":"約旦河西亞摩利人的諸王和靠海迦南人的諸王，聽見耶和華在以色列人前面使約旦河的水乾了，等到我們過去，他們的心因以色列人的緣故就消化了，不再有膽氣。","notes":[]},{"n":2,"t":"那時，耶和華吩咐約書亞說：「你製造火石刀，第二次給以色列人行割禮。」","notes":[]},{"n":3,"t":"約書亞就製造了火石刀，在「除皮山」那裏給以色列人行割禮。","notes":[]},{"n":4,"t":"約書亞行割禮的緣故，是因為從埃及出來的眾民，就是一切能打仗的男丁，出了埃及以後，都死在曠野的路上。","notes":[]},{"n":5,"t":"因為出來的眾民都受過割禮；惟獨出埃及以後、在曠野的路上所生的眾民都沒有受過割禮。","notes":[]},{"n":6,"t":"以色列人在曠野走了四十年，等到國民，就是出埃及的兵丁，都消滅了，因為他們沒有聽從耶和華的話。耶和華曾向他們起誓，必不容他們看見耶和華向他們列祖起誓、應許賜給我們的地，就是流奶與蜜之地。","notes":[]},{"n":7,"t":"他們的子孫，就是耶和華所興起來接續他們的，都沒有受過割禮；因為在路上沒有給他們行割禮，約書亞這才給他們行了。","notes":[]},{"n":8,"t":"國民都受完了割禮，就住在營中自己的地方，等到痊癒了。","notes":[]},{"n":9,"t":"耶和華對約書亞說：「我今日將埃及的羞辱從你們身上滾去了。」因此，那地方名叫吉甲，直到今日。","notes":["就是滾的意思"]},{"n":10,"t":"以色列人在吉甲安營。正月十四日晚上，在耶利哥的平原守逾越節。","notes":[]},{"n":11,"t":"逾越節的次日，他們就吃了那地的出產；正當那日吃無酵餅和烘的穀。","notes":[]},{"n":12,"t":"他們吃了那地的出產，第二日嗎哪就止住了，以色列人也不再有嗎哪了。那一年，他們卻吃迦南地的出產。","notes":[]},{"n":13,"t":"約書亞靠近耶利哥的時候，舉目觀看，不料，有一個人手裏有拔出來的刀，對面站立。約書亞到他那裏，問他說：「你是幫助我們呢，是幫助我們敵人呢？」","notes":[],"heads":["約書亞和耶和華軍隊的元帥"]},{"n":14,"t":"他回答說：「不是的，我來是要作耶和華軍隊的元帥。」約書亞就俯伏在地下拜，說：「我主有甚麼話吩咐僕人。」","notes":[]},{"n":15,"t":"耶和華軍隊的元帥對約書亞說：「把你腳上的鞋脫下來，因為你所站的地方是聖的。」約書亞就照著行了。","notes":[]}]},"6":{"heading":"耶利哥城陷落","verses":[{"n":1,"t":"耶利哥的城門因以色列人就關得嚴緊，無人出入。","notes":[]},{"n":2,"t":"耶和華曉諭約書亞說：「看哪，我已經把耶利哥和耶利哥的王，並大能的勇士，都交在你手中。","notes":[]},{"n":3,"t":"你們的一切兵丁要圍繞這城，一日圍繞一次，六日都要這樣行。","notes":[]},{"n":4,"t":"七個祭司要拿七個羊角走在約櫃前。到第七日，你們要繞城七次，祭司也要吹角。","notes":[]},{"n":5,"t":"他們吹的角聲拖長，你們聽見角聲，眾百姓要大聲呼喊，城牆就必塌陷，各人都要往前直上。」","notes":[]},{"n":6,"t":"嫩的兒子約書亞召了祭司來，吩咐他們說：「你們抬起約櫃來，要有七個祭司拿七個羊角走在耶和華的約櫃前」；","notes":[]},{"n":7,"t":"又對百姓說：「你們前去繞城，帶兵器的要走在耶和華的約櫃前。」","notes":[]},{"n":8,"t":"約書亞對百姓說完了話，七個祭司拿七個羊角走在耶和華面前吹角；耶和華的約櫃在他們後面跟隨。","notes":[]},{"n":9,"t":"帶兵器的走在吹角的祭司前面，後隊隨著約櫃行。祭司一面走一面吹。","notes":[]},{"n":10,"t":"約書亞吩咐百姓說：「你們不可呼喊，不可出聲，連一句話也不可出你們的口，等到我吩咐你們呼喊的日子，那時才可以呼喊。」","notes":[]},{"n":11,"t":"這樣，他使耶和華的約櫃繞城，把城繞了一次；眾人回到營裏，就在營裏住宿。","notes":[]},{"n":12,"t":"約書亞清早起來，祭司又抬起耶和華的約櫃。","notes":[]},{"n":13,"t":"七個祭司拿七個羊角在耶和華的約櫃前，時常行走吹角；帶兵器的在他們前面走，後隊隨著耶和華的約櫃行。祭司一面走一面吹。","notes":[]},{"n":14,"t":"第二日，眾人把城繞了一次，就回營裏去。六日都是這樣行。","notes":[]},{"n":15,"t":"第七日清早，黎明的時候，他們起來，照樣繞城七次；惟獨這日把城繞了七次。","notes":[]},{"n":16,"t":"到了第七次，祭司吹角的時候，約書亞吩咐百姓說：「呼喊吧，因為耶和華已經把城交給你們了！","notes":[]},{"n":17,"t":"這城和其中所有的都要在耶和華面前毀滅；只有妓女喇合與她家中所有的可以存活，因為她隱藏了我們所打發的使者。","notes":[]},{"n":18,"t":"至於你們，務要謹慎，不可取那當滅的物，恐怕你們取了那當滅的物就連累以色列的全營，使全營受咒詛。","notes":[]},{"n":19,"t":"惟有金子、銀子，和銅鐵的器皿都要歸耶和華為聖，必入耶和華的庫中。」","notes":[]},{"n":20,"t":"於是百姓呼喊，祭司也吹角。百姓聽見角聲，便大聲呼喊，城牆就塌陷，百姓便上去進城，各人往前直上，將城奪取；","notes":[]},{"n":21,"t":"又將城中所有的，不拘男女老少，牛羊和驢，都用刀殺盡。","notes":[]},{"n":22,"t":"約書亞吩咐窺探地的兩個人說：「你們進那妓女的家，照著你們向她所起的誓，將那女人和她所有的都從那裏帶出來。」","notes":[]},{"n":23,"t":"當探子的兩個少年人就進去，將喇合與她的父母、弟兄，和她所有的，並她一切的親眷，都帶出來，安置在以色列的營外。","notes":[]},{"n":24,"t":"眾人就用火將城和其中所有的焚燒了；惟有金子、銀子，和銅鐵的器皿都放在耶和華殿的庫中。","notes":[]},{"n":25,"t":"約書亞卻把妓女喇合與她父家，並她所有的，都救活了；因為她隱藏了約書亞所打發窺探耶利哥的使者，她就住在以色列中，直到今日。","notes":[]},{"n":26,"t":"當時，約書亞叫眾人起誓說：「有興起重修這耶利哥城的人，當在耶和華面前受咒詛。他立根基的時候，必喪長子，安門的時候，必喪幼子。」","notes":[]},{"n":27,"t":"耶和華與約書亞同在，約書亞的聲名傳揚遍地。","notes":[]}]},"7":{"heading":"亞干犯罪","verses":[{"n":1,"t":"以色列人在當滅的物上犯了罪；因為猶大支派中，謝拉的曾孫，撒底的孫子，迦米的兒子亞干取了當滅的物；耶和華的怒氣就向以色列人發作。","notes":[]},{"n":2,"t":"當下，約書亞從耶利哥打發人往伯特利東邊、靠近伯‧亞文的艾城去，吩咐他們說：「你們上去窺探那地。」他們就上去窺探艾城。","notes":[]},{"n":3,"t":"他們回到約書亞那裏，對他說：「眾民不必都上去，只要二三千人上去就能攻取艾城；不必勞累眾民都去，因為那裏的人少。」","notes":[]},{"n":4,"t":"於是民中約有三千人上那裏去，竟在艾城人面前逃跑了。","notes":[]},{"n":5,"t":"艾城的人擊殺了他們三十六人，從城門前追趕他們，直到示巴琳，在下坡殺敗他們；眾民的心就消化如水。","notes":[]},{"n":6,"t":"約書亞便撕裂衣服；他和以色列的長老把灰撒在頭上，在耶和華的約櫃前俯伏在地，直到晚上。","notes":[]},{"n":7,"t":"約書亞說：「哀哉！主耶和華啊，你為甚麼竟領這百姓過約旦河，將我們交在亞摩利人的手中，使我們滅亡呢？我們不如住在約旦河那邊倒好。","notes":[]},{"n":8,"t":"主啊，以色列人既在仇敵面前轉背逃跑，我還有甚麼可說的呢？","notes":[]},{"n":9,"t":"迦南人和這地一切的居民聽見了就必圍困我們，將我們的名從地上除滅。那時你為你的大名要怎樣行呢？」","notes":[]},{"n":10,"t":"耶和華吩咐約書亞說：「起來！你為何這樣俯伏在地呢？","notes":[]},{"n":11,"t":"以色列人犯了罪，違背了我所吩咐他們的約，取了當滅的物；又偷竊，又行詭詐，又把那當滅的放在他們的家具裏。","notes":[]},{"n":12,"t":"因此，以色列人在仇敵面前站立不住。他們在仇敵面前轉背逃跑，是因成了被咒詛的；你們若不把當滅的物從你們中間除掉，我就不再與你們同在了。","notes":[]},{"n":13,"t":"你起來，叫百姓自潔，對他們說：『你們要自潔，預備明天，因為耶和華－以色列的神這樣說：以色列啊，你們中間有當滅的物，你們若不除掉，在仇敵面前必站立不住！』","notes":[]},{"n":14,"t":"到了早晨，你們要按著支派近前來；耶和華所取的支派，要按著宗族近前來；耶和華所取的宗族，要按著家室近前來；耶和華所取的家室，要按著人丁，一個一個地近前來。","notes":[]},{"n":15,"t":"被取的人有當滅的物在他那裏，他和他所有的必被火焚燒；因他違背了耶和華的約，又因他在以色列中行了愚妄的事。」","notes":[]},{"n":16,"t":"於是，約書亞清早起來，使以色列人按著支派近前來，取出來的是猶大支派；","notes":[]},{"n":17,"t":"使猶大支派近前來，就取了謝拉的宗族；使謝拉的宗族，按著家室人丁，一個一個地近前來，取出來的是撒底；","notes":["原文是宗族"]},{"n":18,"t":"使撒底的家室，按著人丁，一個一個地近前來，就取出猶大支派的人謝拉的曾孫，撒底的孫子，迦米的兒子亞干。","notes":[]},{"n":19,"t":"約書亞對亞干說：「我兒，我勸你將榮耀歸給耶和華－以色列的神，在他面前認罪，將你所做的事告訴我，不要向我隱瞞。」","notes":[]},{"n":20,"t":"亞干回答約書亞說：「我實在得罪了耶和華－以色列的神。我所做的事如此如此：","notes":[]},{"n":21,"t":"我在所奪的財物中看見一件美好的示拿衣服，二百舍客勒銀子，一條金子重五十舍客勒，我就貪愛這些物件，便拿去了。現今藏在我帳棚內的地裏，銀子在衣服底下。」","notes":[]},{"n":22,"t":"約書亞就打發人跑到亞干的帳棚裏。那件衣服果然藏在他帳棚內，銀子在底下。","notes":[]},{"n":23,"t":"他們就從帳棚裏取出來，拿到約書亞和以色列眾人那裏，放在耶和華面前。","notes":[]},{"n":24,"t":"約書亞和以色列眾人把謝拉的曾孫亞干和那銀子、那件衣服、那條金子，並亞干的兒女、牛、驢、羊、帳棚，以及他所有的，都帶到亞割谷去。","notes":[]},{"n":25,"t":"約書亞說：「你為甚麼連累我們呢？今日耶和華必叫你受連累。」於是以色列眾人用石頭打死他，將石頭扔在其上，又用火焚燒他所有的。","notes":["原文是他們"]},{"n":26,"t":"眾人在亞干身上堆成一大堆石頭，直存到今日。於是耶和華轉意，不發他的烈怒。因此那地方名叫亞割谷，直到今日。","notes":["就是連累的意思"]}]},"8":{"heading":"攻取艾城","verses":[{"n":1,"t":"耶和華對約書亞說：「不要懼怕，也不要驚惶。你起來，率領一切兵丁上艾城去，我已經把艾城的王和他的民、他的城，並他的地，都交在你手裏。","notes":[]},{"n":2,"t":"你怎樣待耶利哥和耶利哥的王，也當照樣待艾城和艾城的王。只是城內所奪的財物和牲畜，你們可以取為自己的掠物。你要在城後設下伏兵。」","notes":[]},{"n":3,"t":"於是，約書亞和一切兵丁都起來，要上艾城去。約書亞選了三萬大能的勇士，夜間打發他們前往，","notes":[]},{"n":4,"t":"吩咐他們說：「你們要在城後埋伏，不可離城太遠，都要各自準備。","notes":[]},{"n":5,"t":"我與我所帶領的眾民要向城前往。城裏的人像初次出來攻擊我們的時候，我們就在他們面前逃跑，","notes":[]},{"n":6,"t":"他們必出來追趕我們，直到我們引誘他們離開城；因為他們必說：『這些人像初次在我們面前逃跑。』所以我們要在他們面前逃跑，","notes":[]},{"n":7,"t":"你們就從埋伏的地方起來，奪取那城，因為耶和華－你們的神必把城交在你們手裏。","notes":[]},{"n":8,"t":"你們奪了城以後，就放火燒城，要照耶和華的話行。這是我吩咐你們的。」","notes":[]},{"n":9,"t":"約書亞打發他們前往，他們就上埋伏的地方去，住在伯特利和艾城的中間，就是在艾城的西邊。這夜約書亞卻在民中住宿。","notes":[]},{"n":10,"t":"約書亞清早起來，點齊百姓，他和以色列的長老在百姓前面上艾城去。","notes":[]},{"n":11,"t":"眾民，就是他所帶領的兵丁，都上去，向前直往，來到城前，在艾城北邊安營。在約書亞和艾城中間有一山谷。","notes":[]},{"n":12,"t":"他挑了約有五千人，使他們埋伏在伯特利和艾城的中間，就是在艾城的西邊，","notes":[]},{"n":13,"t":"於是安置了百姓，就是城北的全軍和城西的伏兵。這夜約書亞進入山谷之中。","notes":[]},{"n":14,"t":"艾城的王看見這景況，就和全城的人，清早急忙起來，按所定的時候，出到亞拉巴前，要與以色列人交戰；王卻不知道在城後有伏兵。","notes":[]},{"n":15,"t":"約書亞和以色列眾人在他們面前裝敗，往那通曠野的路逃跑。","notes":[]},{"n":16,"t":"城內的眾民都被招聚，追趕他們；艾城人追趕的時候，就被引誘離開城。","notes":[]},{"n":17,"t":"艾城和伯特利城沒有一人不出來追趕以色列人的，撇了敞開的城門，去追趕以色列人。","notes":[]},{"n":18,"t":"耶和華吩咐約書亞說：「你向艾城伸出手裏的短槍，因為我要將城交在你手裏。」約書亞就向城伸出手裏的短槍。","notes":[]},{"n":19,"t":"他一伸手，伏兵就從埋伏的地方急忙起來，奪了城，跑進城去，放火焚燒。","notes":[]},{"n":20,"t":"艾城的人回頭一看，不料，城中煙氣沖天，他們就無力向左向右逃跑。那往曠野逃跑的百姓便轉身攻擊追趕他們的人。","notes":[]},{"n":21,"t":"約書亞和以色列眾人見伏兵已經奪了城，城中煙氣飛騰，就轉身回去，擊殺艾城的人。","notes":[]},{"n":22,"t":"伏兵也出城迎擊艾城人，艾城人就困在以色列人中間，前後都是以色列人。於是以色列人擊殺他們，沒有留下一個，也沒有一個逃脫的，","notes":[]},{"n":23,"t":"生擒了艾城的王，將他解到約書亞那裏。","notes":[]},{"n":24,"t":"以色列人在田間和曠野殺盡所追趕一切艾城的居民。艾城人倒在刀下，直到滅盡；以色列眾人就回到艾城，用刀殺了城中的人。","notes":[]},{"n":25,"t":"當日殺斃的人，連男帶女共有一萬二千，就是艾城所有的人。","notes":[]},{"n":26,"t":"約書亞沒有收回手裏所伸出來的短槍，直到把艾城的一切居民盡行殺滅。","notes":[]},{"n":27,"t":"惟獨城中的牲畜和財物，以色列人都取為自己的掠物，是照耶和華所吩咐約書亞的話。","notes":[]},{"n":28,"t":"約書亞將艾城焚燒，使城永為高堆、荒場，直到今日；","notes":[]},{"n":29,"t":"又將艾城王掛在樹上，直到晚上。日落的時候，約書亞吩咐人把屍首從樹上取下來，丟在城門口，在屍首上堆成一大堆石頭，直存到今日。","notes":[]},{"n":30,"t":"那時，約書亞在以巴路山上為耶和華－以色列的神築一座壇，","notes":[],"heads":["在以巴路山上宣讀律法"]},{"n":31,"t":"是用沒有動過鐵器的整石頭築的，照著耶和華僕人摩西所吩咐以色列人的話，正如摩西律法書上所寫的。眾人在這壇上給耶和華奉獻燔祭和平安祭。","notes":[]},{"n":32,"t":"約書亞在那裏，當著以色列人面前，將摩西所寫的律法抄寫在石頭上。","notes":[]},{"n":33,"t":"以色列眾人，無論是本地人、是寄居的，和長老、官長，並審判官，都站在約櫃兩旁，在抬耶和華約櫃的祭司利未人面前，一半對著基利心山，一半對著以巴路山，為以色列民祝福，正如耶和華僕人摩西先前所吩咐的。","notes":[]},{"n":34,"t":"隨後，約書亞將律法上祝福、咒詛的話，照著律法書上一切所寫的，都宣讀了一遍。","notes":[]},{"n":35,"t":"摩西所吩咐的一切話，約書亞在以色列全會眾和婦女、孩子，並他們中間寄居的外人面前，沒有一句不宣讀的。","notes":[]}]},"9":{"heading":"基遍人欺瞞約書亞","verses":[{"n":1,"t":"約旦河西，住山地、高原，並對著黎巴嫩山沿大海一帶的諸王，就是赫人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人的諸王，聽見這事，","notes":[]},{"n":2,"t":"就都聚集，同心合意地要與約書亞和以色列人爭戰。","notes":[]},{"n":3,"t":"基遍的居民聽見約書亞向耶利哥和艾城所行的事，","notes":[]},{"n":4,"t":"就設詭計，假充使者，拿舊口袋和破裂縫補的舊皮酒袋馱在驢上，","notes":[]},{"n":5,"t":"將補過的舊鞋穿在腳上，把舊衣服穿在身上；他們所帶的餅都是乾的，長了霉了。","notes":[]},{"n":6,"t":"他們到吉甲營中見約書亞，對他和以色列人說：「我們是從遠方來的，現在求你與我們立約。」","notes":[]},{"n":7,"t":"以色列人對這些希未人說：「只怕你們是住在我們中間的；若是這樣，怎能和你們立約呢？」","notes":[]},{"n":8,"t":"他們對約書亞說：「我們是你的僕人。」約書亞問他們說：「你們是甚麼人？是從哪裏來的？」","notes":[]},{"n":9,"t":"他們回答說：「僕人從極遠之地而來，是因聽見耶和華－你神的名聲和他在埃及所行的一切事，","notes":[]},{"n":10,"t":"並他向約旦河東的兩個亞摩利王，就是希實本王西宏和在亞斯他錄的巴珊王噩一切所行的事。","notes":[]},{"n":11,"t":"我們的長老和我們那地的一切居民對我們說：『你們手裏要帶著路上用的食物去迎接以色列人，對他們說：我們是你們的僕人；現在求你們與我們立約。』","notes":[]},{"n":12,"t":"我們出來要往你們這裏來的日子，從家裏帶出來的這餅還是熱的；看哪，現在都乾了，長了霉了。","notes":[]},{"n":13,"t":"這皮酒袋，我們盛酒的時候還是新的；看哪，現在已經破裂。我們這衣服和鞋，因為道路甚遠，也都穿舊了。」","notes":[]},{"n":14,"t":"以色列人受了他們些食物，並沒有求問耶和華。","notes":[]},{"n":15,"t":"於是約書亞與他們講和，與他們立約，容他們活著；會眾的首領也向他們起誓。","notes":[]},{"n":16,"t":"以色列人與他們立約之後，過了三天才聽見他們是近鄰，住在以色列人中間的。","notes":[]},{"n":17,"t":"以色列人起行，第三天到了他們的城邑，就是基遍、基非拉、比錄、基列‧耶琳。","notes":[]},{"n":18,"t":"因為會眾的首領已經指著耶和華－以色列的神向他們起誓，所以以色列人不擊殺他們；全會眾就向首領發怨言。","notes":[]},{"n":19,"t":"眾首領對全會眾說：「我們已經指著耶和華－以色列的神向他們起誓，現在我們不能害他們。","notes":[]},{"n":20,"t":"我們要如此待他們，容他們活著，免得有忿怒因我們所起的誓臨到我們身上。」","notes":[]},{"n":21,"t":"首領又對會眾說：「要容他們活著。」於是他們為全會眾作了劈柴挑水的人，正如首領對他們所說的話。","notes":[]},{"n":22,"t":"約書亞召了他們來，對他們說：「為甚麼欺哄我們說『我們離你們甚遠』呢？其實你們是住在我們中間。","notes":[]},{"n":23,"t":"現在你們是被咒詛的！你們中間的人必斷不了作奴僕，為我神的殿作劈柴挑水的人。」","notes":[]},{"n":24,"t":"他們回答約書亞說：「因為有人實在告訴你的僕人，耶和華－你的神曾吩咐他的僕人摩西，把這全地賜給你們，並在你們面前滅絕這地的一切居民，所以我們為你們的緣故甚怕喪命，就行了這事。","notes":[]},{"n":25,"t":"現在我們在你手中，你以怎樣待我們為善為正，就怎樣做吧！」","notes":[]},{"n":26,"t":"於是約書亞這樣待他們，救他們脫離以色列人的手，以色列人就沒有殺他們。","notes":[]},{"n":27,"t":"當日約書亞使他們在耶和華所要選擇的地方，為會眾和耶和華的壇作劈柴挑水的人，直到今日。","notes":[]}]},"10":{"heading":"擊敗亞摩利人","verses":[{"n":1,"t":"耶路撒冷王亞多尼‧洗德聽見約書亞奪了艾城，盡行毀滅，怎樣待耶利哥和耶利哥的王，也照樣待艾城和艾城的王，又聽見基遍的居民與以色列人立了和約，住在他們中間，","notes":[]},{"n":2,"t":"就甚懼怕；因為基遍是一座大城，如都城一般，比艾城更大，並且城內的人都是勇士。","notes":[]},{"n":3,"t":"所以耶路撒冷王亞多尼‧洗德打發人去見希伯崙王何咸、耶末王毗蘭、拉吉王雅非亞，和伊磯倫王底璧，說：","notes":[]},{"n":4,"t":"「求你們上來幫助我，我們好攻打基遍，因為他們與約書亞和以色列人立了和約。」","notes":[]},{"n":5,"t":"於是五個亞摩利王，就是耶路撒冷王、希伯崙王、耶末王、拉吉王、伊磯倫王，大家聚集，率領他們的眾軍上去，對著基遍安營，攻打基遍。","notes":[]},{"n":6,"t":"基遍人就打發人往吉甲的營中去見約書亞，說：「你不要袖手不顧你的僕人，求你速速上來拯救我們，幫助我們，因為住山地亞摩利人的諸王都聚集攻擊我們。」","notes":[]},{"n":7,"t":"於是約書亞和他一切兵丁，並大能的勇士，都從吉甲上去。","notes":[]},{"n":8,"t":"耶和華對約書亞說：「不要怕他們；因為我已將他們交在你手裏，他們無一人能在你面前站立得住。」","notes":[]},{"n":9,"t":"約書亞就終夜從吉甲上去，猛然臨到他們那裏。","notes":[]},{"n":10,"t":"耶和華使他們在以色列人面前潰亂。約書亞在基遍大大地殺敗他們，追趕他們，在伯‧和崙的上坡路擊殺他們，直到亞西加和瑪基大。","notes":[]},{"n":11,"t":"他們在以色列人面前逃跑，正在伯‧和崙下坡的時候，耶和華從天上降大冰雹在他們身上，直降到亞西加，打死他們。被冰雹打死的，比以色列人用刀殺死的還多。","notes":["原文是石頭"]},{"n":12,"t":"當耶和華將亞摩利人交付以色列人的日子，約書亞就禱告耶和華，在以色列人眼前說：日頭啊，你要停在基遍；月亮啊，你要止在亞雅崙谷。","notes":[]},{"n":13,"t":"於是日頭停留，月亮止住，直等國民向敵人報仇。這事豈不是寫在雅煞珥書上嗎？日頭在天當中停住，不急速下落，約有一日之久。","notes":[]},{"n":14,"t":"在這日以前，這日以後，耶和華聽人的禱告，沒有像這日的，是因耶和華為以色列爭戰。","notes":[]},{"n":15,"t":"約書亞和以色列眾人回到吉甲的營中。","notes":[]},{"n":16,"t":"那五王逃跑，藏在瑪基大洞裏。","notes":[],"heads":["生擒亞摩利的五王"]},{"n":17,"t":"有人告訴約書亞說：「那五王已經找到了，都藏在瑪基大洞裏。」","notes":[]},{"n":18,"t":"約書亞說：「你們把幾塊大石頭滾到洞口，派人看守，","notes":[]},{"n":19,"t":"你們卻不可耽延，要追趕你們的仇敵，擊殺他們儘後邊的人，不容他們進自己的城邑，因為耶和華－你們的神已經把他們交在你們手裏。」","notes":[]},{"n":20,"t":"約書亞和以色列人大大殺敗他們，直到將他們滅盡；其中剩下的人都進了堅固的城。","notes":[]},{"n":21,"t":"眾百姓就安然回瑪基大營中，到約書亞那裏。沒有一人敢向以色列人饒舌。","notes":[]},{"n":22,"t":"約書亞說：「打開洞口，將那五王從洞裏帶出來，領到我面前。」","notes":[]},{"n":23,"t":"眾人就這樣行，將那五王，就是耶路撒冷王、希伯崙王、耶末王、拉吉王、伊磯倫王，從洞裏帶出來，領到約書亞面前。","notes":[]},{"n":24,"t":"帶出那五王到約書亞面前的時候，約書亞就召了以色列眾人來，對那些和他同去的軍長說：「你們近前來，把腳踏在這些王的頸項上。」他們就近前來，把腳踏在這些王的頸項上。","notes":[]},{"n":25,"t":"約書亞對他們說：「你們不要懼怕，也不要驚惶。應當剛強壯膽，因為耶和華必這樣待你們所要攻打的一切仇敵。」","notes":[]},{"n":26,"t":"隨後約書亞將這五王殺死，掛在五棵樹上。他們就在樹上直掛到晚上。","notes":[]},{"n":27,"t":"日頭要落的時候，約書亞一吩咐，人就把屍首從樹上取下來，丟在他們藏過的洞裏，把幾塊大石頭放在洞口，直存到今日。","notes":[]},{"n":28,"t":"當日，約書亞奪了瑪基大，用刀擊殺城中的人和王；將其中一切人口盡行殺滅，沒有留下一個。他待瑪基大王，像從前待耶利哥王一樣。","notes":[],"heads":["約書亞攻取更多的城邑"]},{"n":29,"t":"約書亞和以色列眾人從瑪基大往立拿去，攻打立拿。","notes":[]},{"n":30,"t":"耶和華將立拿和立拿的王也交在以色列人手裏。約書亞攻打這城，用刀擊殺了城中的一切人口，沒有留下一個。他待立拿王，像從前待耶利哥王一樣。","notes":[]},{"n":31,"t":"約書亞和以色列眾人從立拿往拉吉去，對著拉吉安營，攻打這城。","notes":[]},{"n":32,"t":"耶和華將拉吉交在以色列人的手裏。第二天約書亞就奪了拉吉，用刀擊殺了城中的一切人口，是照他向立拿一切所行的。","notes":[]},{"n":33,"t":"那時基色王荷蘭上來幫助拉吉，約書亞就把他和他的民都擊殺了，沒有留下一個。","notes":[]},{"n":34,"t":"約書亞和以色列眾人從拉吉往伊磯倫去，對著伊磯倫安營，攻打這城。","notes":[]},{"n":35,"t":"當日就奪了城，用刀擊殺了城中的人。那日，約書亞將城中的一切人口盡行殺滅，是照他向拉吉一切所行的。","notes":[]},{"n":36,"t":"約書亞和以色列眾人從伊磯倫上希伯崙去，攻打這城，","notes":[]},{"n":37,"t":"就奪了希伯崙和屬希伯崙的諸城邑，用刀將城中的人與王，並那些城邑中的人口，都擊殺了，沒有留下一個，是照他向伊磯倫所行的，把城中的一切人口盡行殺滅。","notes":[]},{"n":38,"t":"約書亞和以色列眾人回到底璧，攻打這城，","notes":[]},{"n":39,"t":"就奪了底璧和屬底璧的城邑，又擒獲底璧的王，用刀將這些城中的人口盡行殺滅，沒有留下一個。他待底璧和底璧王，像從前待希伯崙和立拿與立拿王一樣。","notes":[]},{"n":40,"t":"這樣，約書亞擊殺全地的人，就是山地、南地、高原、山坡的人，和那些地的諸王，沒有留下一個。將凡有氣息的盡行殺滅，正如耶和華－以色列的神所吩咐的。","notes":[]},{"n":41,"t":"約書亞從加低斯‧巴尼亞攻擊到迦薩，又攻擊歌珊全地，直到基遍。","notes":[]},{"n":42,"t":"約書亞一時殺敗了這些王，並奪了他們的地，因為耶和華－以色列的神為以色列爭戰。","notes":[]},{"n":43,"t":"於是約書亞和以色列眾人回到吉甲的營中。","notes":[]}]},"11":{"heading":"約書亞擊敗耶賓和他的盟國","verses":[{"n":1,"t":"夏瑣王耶賓聽見這事，就打發人去見瑪頓王約巴、伸崙王、押煞王，","notes":[]},{"n":2,"t":"與北方山地、基尼烈南邊的亞拉巴高原，並西邊多珥山岡的諸王；","notes":[]},{"n":3,"t":"又去見東方和西方的迦南人，與山地的亞摩利人、赫人、比利洗人、耶布斯人，並黑門山根米斯巴地的希未人。","notes":[]},{"n":4,"t":"這些王和他們的眾軍都出來，人數多如海邊的沙，並有許多馬匹車輛。","notes":[]},{"n":5,"t":"這諸王會合，來到米倫水邊，一同安營，要與以色列人爭戰。","notes":[]},{"n":6,"t":"耶和華對約書亞說：「你不要因他們懼怕。明日這時，我必將他們交付以色列人全然殺了。你要砍斷他們馬的蹄筋，用火焚燒他們的車輛。」","notes":[]},{"n":7,"t":"於是約書亞率領一切兵丁，在米倫水邊突然向前攻打他們。","notes":[]},{"n":8,"t":"耶和華將他們交在以色列人手裏，以色列人就擊殺他們，追趕他們到西頓大城，到米斯利弗‧瑪音，直到東邊米斯巴的平原，將他們擊殺，沒有留下一個。","notes":[]},{"n":9,"t":"約書亞就照耶和華所吩咐他的去行，砍斷他們馬的蹄筋，用火焚燒他們的車輛。","notes":[]},{"n":10,"t":"當時，約書亞轉回奪了夏瑣，用刀擊殺夏瑣王。（素來夏瑣在這諸國中是為首的。）","notes":[]},{"n":11,"t":"以色列人用刀擊殺城中的人口，將他們盡行殺滅；凡有氣息的沒有留下一個。約書亞又用火焚燒夏瑣。","notes":[]},{"n":12,"t":"約書亞奪了這些王的一切城邑，擒獲其中的諸王，用刀擊殺他們，將他們盡行殺滅，正如耶和華僕人摩西所吩咐的。","notes":[]},{"n":13,"t":"至於造在山岡上的城，除了夏瑣以外，以色列人都沒有焚燒。約書亞只將夏瑣焚燒了。","notes":[]},{"n":14,"t":"那些城邑所有的財物和牲畜，以色列人都取為自己的掠物；惟有一切人口都用刀擊殺，直到殺盡；凡有氣息的沒有留下一個。","notes":[]},{"n":15,"t":"耶和華怎樣吩咐他僕人摩西，摩西就照樣吩咐約書亞，約書亞也照樣行。凡耶和華所吩咐摩西的，約書亞沒有一件懈怠不行的。","notes":[]},{"n":16,"t":"約書亞奪了那全地，就是山地、一帶南地、歌珊全地、高原、亞拉巴、以色列的山地，和山下的高原。","notes":[],"heads":["約書亞佔領的土地"]},{"n":17,"t":"從上西珥的哈拉山，直到黑門山下黎巴嫩平原的巴力‧迦得，並且擒獲那些地的諸王，將他們殺死。","notes":[]},{"n":18,"t":"約書亞和這諸王爭戰了許多年日。","notes":[]},{"n":19,"t":"除了基遍的希未人之外，沒有一城與以色列人講和的，都是以色列人爭戰奪來的。","notes":[]},{"n":20,"t":"因為耶和華的意思是要使他們心裏剛硬，來與以色列人爭戰，好叫他們盡被殺滅，不蒙憐憫，正如耶和華所吩咐摩西的。","notes":[]},{"n":21,"t":"當時約書亞來到，將住山地、希伯崙、底璧、亞拿伯、猶大山地、以色列山地所有的亞衲族人剪除了。約書亞將他們和他們的城邑盡都毀滅。","notes":[]},{"n":22,"t":"在以色列人的地沒有留下一個亞衲族人，只在迦薩、迦特，和亞實突有留下的。","notes":[]},{"n":23,"t":"這樣，約書亞照著耶和華所吩咐摩西的一切話奪了那全地，就按著以色列支派的宗族將地分給他們為業。於是國中太平，沒有爭戰了。","notes":[]}]},"12":{"heading":"摩西擊敗的諸王","verses":[{"n":1,"t":"以色列人在約旦河外向日出之地擊殺二王，得他們的地，就是從亞嫩谷直到黑門山，並東邊的全亞拉巴之地。","notes":[]},{"n":2,"t":"這二王，有住希實本、亞摩利人的王西宏。他所管之地是從亞嫩谷邊的亞羅珥和谷中的城，並基列一半，直到亞捫人的境界，雅博河","notes":[]},{"n":3,"t":"與約旦河東邊的亞拉巴，直到基尼烈海，又到亞拉巴的海，就是鹽海，通伯‧耶西末的路，以及南方，直到毗斯迦的山根。","notes":[]},{"n":4,"t":"又有巴珊王噩。他是利乏音人所剩下的，住在亞斯他錄和以得來。","notes":[]},{"n":5,"t":"他所管之地是黑門山、撒迦、巴珊全地，直到基述人和瑪迦人的境界，並基列一半，直到希實本王西宏的境界。","notes":[]},{"n":6,"t":"這二王是耶和華僕人摩西和以色列人所擊殺的；耶和華僕人摩西將他們的地賜給呂便人、迦得人，和瑪拿西半支派的人為業。","notes":[]},{"n":7,"t":"約書亞和以色列人在約旦河西擊殺了諸王。他們的地是從黎巴嫩平原的巴力‧迦得，直到上西珥的哈拉山。約書亞就將那地按著以色列支派的宗族分給他們為業，","notes":[],"heads":["約書亞擊敗的諸王"]},{"n":8,"t":"就是赫人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人的山地、高原亞拉巴、山坡、曠野，和南地。","notes":[]},{"n":9,"t":"他們的王：一個是耶利哥王，一個是靠近伯特利的艾城王，","notes":[]},{"n":10,"t":"一個是耶路撒冷王，一個是希伯崙王，","notes":[]},{"n":11,"t":"一個是耶末王，一個是拉吉王，","notes":[]},{"n":12,"t":"一個是伊磯倫王，一個是基色王，","notes":[]},{"n":13,"t":"一個是底璧王，一個是基德王，","notes":[]},{"n":14,"t":"一個是何珥瑪王，一個是亞拉得王，","notes":[]},{"n":15,"t":"一個是立拿王，一個是亞杜蘭王，","notes":[]},{"n":16,"t":"一個是瑪基大王，一個是伯特利王，","notes":[]},{"n":17,"t":"一個是他普亞王，一個是希弗王，","notes":[]},{"n":18,"t":"一個是亞弗王，一個是拉沙崙王，","notes":[]},{"n":19,"t":"一個是瑪頓王，一個是夏瑣王，","notes":[]},{"n":20,"t":"一個是伸崙‧米崙王，一個是押煞王，","notes":[]},{"n":21,"t":"一個是他納王，一個是米吉多王，","notes":[]},{"n":22,"t":"一個是基低斯王，一個是靠近迦密的約念王，","notes":[]},{"n":23,"t":"一個是多珥山岡的多珥王，一個是吉甲的戈印王，","notes":[]},{"n":24,"t":"一個是得撒王；共計三十一個王。","notes":[]}]},"13":{"heading":"尚未佔領之地","verses":[{"n":1,"t":"約書亞年紀老邁，耶和華對他說：「你年紀老邁了，還有許多未得之地，","notes":[]},{"n":2,"t":"就是非利士人的全境和基述人的全地。","notes":[]},{"n":3,"t":"從埃及前的西曷河往北，直到以革倫的境界，就算屬迦南人之地。有非利士人五個首領所管的迦薩人、亞實突人、亞實基倫人、迦特人、以革倫人之地，並有南方亞衛人之地。","notes":[]},{"n":4,"t":"又有迦南人的全地，並屬西頓人的米亞拉到亞弗，直到亞摩利人的境界。","notes":[]},{"n":5,"t":"還有迦巴勒人之地，並向日出的全黎巴嫩，就是從黑門山根的巴力‧迦得，直到哈馬口。","notes":[]},{"n":6,"t":"山地的一切居民，從黎巴嫩直到米斯利弗‧瑪音，就是所有的西頓人，我必在以色列人面前趕出他們去。你只管照我所吩咐的，將這地拈鬮分給以色列人為業。","notes":[]},{"n":7,"t":"現在你要把這地分給九個支派和瑪拿西半個支派為業。」","notes":[]},{"n":8,"t":"瑪拿西那半支派和呂便、迦得二支派已經受了產業，就是耶和華的僕人摩西在約旦河東所賜給他們的：","notes":[],"heads":["分配約旦河東之地"]},{"n":9,"t":"是從亞嫩谷邊的亞羅珥和谷中的城，並米底巴的全平原，直到底本，","notes":[]},{"n":10,"t":"和在希實本作王亞摩利王西宏的諸城，直到亞捫人的境界；","notes":[]},{"n":11,"t":"又有基列地、基述人、瑪迦人的地界，並黑門全山、巴珊全地，直到撒迦；","notes":[]},{"n":12,"t":"又有巴珊王噩的全國－他在亞斯他錄和以得來作王（利乏音人所存留的只剩下他）。這些地的人都是摩西所擊殺、所趕逐的。","notes":[]},{"n":13,"t":"以色列人卻沒有趕逐基述人、瑪迦人；這些人仍住在以色列中，直到今日。","notes":[]},{"n":14,"t":"只是利未支派，摩西 沒有把產業分給他們。他們的產業乃是獻與耶和華－以色列神的火祭，正如耶和華所應許他們的。","notes":["原文是他"]},{"n":15,"t":"摩西按著呂便支派的宗族分給他們產業。","notes":[],"heads":["分給呂便支派的土地"]},{"n":16,"t":"他們的境界是亞嫩谷邊的亞羅珥和谷中的城，靠近米底巴的全平原；","notes":[]},{"n":17,"t":"希實本並屬希實本平原的各城，底本、巴末‧巴力、伯‧巴力‧勉、","notes":[]},{"n":18,"t":"雅雜、基底莫、米法押、","notes":[]},{"n":19,"t":"基列亭、西比瑪、谷中山的細列‧哈沙轄、","notes":[]},{"n":20,"t":"伯‧毗珥、毗斯迦山坡、伯‧耶西末；","notes":[]},{"n":21,"t":"平原的各城，並亞摩利王西宏的全國。這西宏曾在希實本作王，摩西把他和米甸的族長以未、利金、蘇珥、戶珥、利巴擊殺了；這都是住那地屬西宏為首領的。","notes":[]},{"n":22,"t":"那時以色列人在所殺的人中，也用刀殺了比珥的兒子術士巴蘭。","notes":[]},{"n":23,"t":"呂便人的境界就是約旦河與靠近約旦河的地。以上是呂便人按著宗族所得為業的諸城，並屬城的村莊。","notes":[]},{"n":24,"t":"摩西按著迦得支派的宗族分給他們產業。","notes":[],"heads":["分給迦得支派的土地"]},{"n":25,"t":"他們的境界是雅謝和基列的各城，並亞捫人的一半地，直到拉巴前的亞羅珥；","notes":[]},{"n":26,"t":"從希實本到拉抹‧米斯巴和比多寧，又從瑪哈念到底璧的境界，","notes":[]},{"n":27,"t":"並谷中的伯‧亞蘭、伯‧寧拉、疏割、撒分，就是希實本王西宏國中的餘地，以及約旦河與靠近約旦河的地，直到基尼烈海的極邊，都在約旦河東。","notes":[]},{"n":28,"t":"以上是迦得人按著宗族所得為業的諸城，並屬城的村莊。","notes":[]},{"n":29,"t":"摩西把產業分給瑪拿西半支派，是按著瑪拿西半支派的宗族所分的。","notes":[],"heads":["分給瑪拿西半支派的土地"]},{"n":30,"t":"他們的境界是從瑪哈念起，包括巴珊全地，就是巴珊王噩的全國，並在巴珊、睚珥的一切城邑，共六十個。","notes":[]},{"n":31,"t":"基列的一半，並亞斯他錄、以得來，就是屬巴珊王噩國的二城，是按著宗族給瑪拿西的兒子瑪吉的一半子孫。","notes":[]},{"n":32,"t":"以上是摩西在約旦河東對著耶利哥的摩押平原所分給他們的產業。","notes":[]},{"n":33,"t":"只是利未支派，摩西沒有把產業分給他們。耶和華－以色列的神是他們的產業，正如耶和華所應許他們的。","notes":[]}]},"14":{"heading":"分配約旦河西的土地","verses":[{"n":1,"t":"以色列人在迦南地所得的產業，就是祭司以利亞撒和嫩的兒子約書亞，並以色列各支派的族長所分給他們的，都記在下面，","notes":[]},{"n":2,"t":"是照耶和華藉摩西所吩咐的，把產業拈鬮分給九個半支派。","notes":[]},{"n":3,"t":"原來，摩西在約旦河東已經把產業分給那兩個半支派，只是在他們中間沒有把產業分給利未人。","notes":[]},{"n":4,"t":"因為約瑟的子孫是兩個支派，就是瑪拿西和以法蓮，所以沒有把地分給利未人，但給他們城邑居住，並城邑的郊野，可以牧養他們的牲畜，安置他們的財物。","notes":[]},{"n":5,"t":"耶和華怎樣吩咐摩西，以色列人就照樣行，把地分了。","notes":[]},{"n":6,"t":"那時，猶大人來到吉甲見約書亞，有基尼洗族耶孚尼的兒子迦勒對約書亞說：「耶和華在加低斯‧巴尼亞指著我與你對神人摩西所說的話，你都知道了。","notes":[],"heads":["迦勒得希伯崙為業"]},{"n":7,"t":"耶和華的僕人摩西從加低斯‧巴尼亞打發我窺探這地，那時我正四十歲；我按著心意回報他。","notes":[]},{"n":8,"t":"然而，同我上去的眾弟兄使百姓的心消化；但我專心跟從耶和華－我的神。","notes":[]},{"n":9,"t":"當日摩西起誓說：『你腳所踏之地定要歸你和你的子孫永遠為業，因為你專心跟從耶和華－我的神。』","notes":[]},{"n":10,"t":"自從耶和華對摩西說這話的時候，耶和華照他所應許的使我存活這四十五年；其間以色列人在曠野行走。看哪，現今我八十五歲了，","notes":[]},{"n":11,"t":"我還是強壯，像摩西打發我去的那天一樣；無論是爭戰，是出入，我的力量那時如何，現在還是如何。","notes":[]},{"n":12,"t":"求你將耶和華那日應許我的這山地給我；那裏有亞衲族人，並寬大堅固的城，你也曾聽見了。或者耶和華照他所應許的與我同在，我就把他們趕出去。」","notes":[]},{"n":13,"t":"於是約書亞為耶孚尼的兒子迦勒祝福，將希伯崙給他為業。","notes":[]},{"n":14,"t":"所以希伯崙作了基尼洗族耶孚尼的兒子迦勒的產業，直到今日，因為他專心跟從耶和華－以色列的神。","notes":[]},{"n":15,"t":"希伯崙從前名叫基列‧亞巴；亞巴是亞衲族中最尊大的人。於是國中太平，沒有爭戰了。","notes":[]}]},"15":{"heading":"分給猶大支派的土地","verses":[{"n":1,"t":"猶大支派按著宗族拈鬮所得之地是在儘南邊，到以東的交界，向南直到尋的曠野。","notes":[]},{"n":2,"t":"他們的南界是從鹽海的儘邊，就是從朝南的海汊起，","notes":[]},{"n":3,"t":"通到亞克拉濱坡的南邊，接連到尋，上到加低斯‧巴尼亞的南邊，又過希斯崙，上到亞達珥，繞到甲加，","notes":[]},{"n":4,"t":"接連到押們，通到埃及小河，直通到海為止。這就是他們的南界。","notes":[]},{"n":5,"t":"東界是從鹽海南邊到約旦河口。北界是從約旦河口的海汊起，","notes":[]},{"n":6,"t":"上到伯‧曷拉，過伯‧亞拉巴的北邊，上到呂便之子波罕的磐石；","notes":[]},{"n":7,"t":"從亞割谷往北，上到底璧，直向河南亞都冥坡對面的吉甲；又接連到隱‧示麥泉，直通到隱‧羅結，","notes":[]},{"n":8,"t":"上到欣嫩子谷，貼近耶布斯的南界（耶布斯就是耶路撒冷）；又上到欣嫩谷西邊的山頂，就是在利乏音谷極北的邊界；","notes":[]},{"n":9,"t":"又從山頂延到尼弗多亞的水源，通到以弗崙山的城邑，又延到巴拉（巴拉就是基列‧耶琳）；","notes":[]},{"n":10,"t":"又從巴拉往西繞到西珥山，接連到耶琳山的北邊（耶琳就是基撒崙）；又下到伯‧示麥過亭納，","notes":[]},{"n":11,"t":"通到以革倫北邊，延到施基崙，接連到巴拉山；又通到雅比聶，直通到海為止。","notes":[]},{"n":12,"t":"西界就是大海和靠近大海之地。這是猶大人按著宗族所得之地四圍的交界。","notes":[]},{"n":13,"t":"約書亞照耶和華所吩咐的，將猶大人中的一段地，就是基列‧亞巴，分給耶孚尼的兒子迦勒。亞巴是亞衲族的始祖（基列‧亞巴就是希伯崙）。","notes":[],"heads":["迦勒攻取希伯崙和底璧"]},{"n":14,"t":"迦勒就從那裏趕出亞衲族的三個族長，就是示篩、亞希幔、撻買；","notes":[]},{"n":15,"t":"又從那裏上去，攻擊底璧的居民。（這底璧從前名叫基列‧西弗。）","notes":[]},{"n":16,"t":"迦勒說：「誰能攻打基列‧西弗將城奪取，我就把我女兒押撒給他為妻。」","notes":[]},{"n":17,"t":"迦勒兄弟基納斯的兒子俄陀聶奪取了那城，迦勒就把女兒押撒給他為妻。","notes":[]},{"n":18,"t":"押撒過門的時候，勸丈夫向她父親求一塊田，押撒一下驢，迦勒問她說：「你要甚麼？」","notes":[]},{"n":19,"t":"她說：「求你賜福給我，你既將我安置在南地，求你也給我水泉。」她父親就把上泉下泉賜給她。","notes":[]},{"n":20,"t":"以下是猶大支派按著宗族所得的產業。","notes":[],"heads":["猶大所得的城邑"]},{"n":21,"t":"猶大支派儘南邊的城邑，與以東交界相近的，就是甲薛、以得、雅姑珥、","notes":[]},{"n":22,"t":"基拿、底摩拿、亞大達、","notes":[]},{"n":23,"t":"基低斯、夏瑣、以提楠、","notes":[]},{"n":24,"t":"西弗、提鍊、比亞綠、","notes":[]},{"n":25,"t":"夏瑣‧哈大他、加略‧希斯崙（加略‧希斯崙就是夏瑣）、","notes":[]},{"n":26,"t":"亞曼、示瑪、摩拉大、","notes":[]},{"n":27,"t":"哈薩‧迦大、黑實門、伯‧帕列、","notes":[]},{"n":28,"t":"哈薩‧書亞、別是巴、比斯約他、","notes":[]},{"n":29,"t":"巴拉、以因、以森、","notes":[]},{"n":30,"t":"伊勒多臘、基失、何珥瑪、","notes":[]},{"n":31,"t":"洗革拉、麥瑪拿、三撒拿、","notes":[]},{"n":32,"t":"利巴勿、實忻、亞因、臨門，共二十九座城，還有屬城的村莊。","notes":[]},{"n":33,"t":"在高原有以實陶、瑣拉、亞實拿、","notes":[]},{"n":34,"t":"撒挪亞、隱‧干寧、他普亞、以楠、","notes":[]},{"n":35,"t":"耶末、亞杜蘭、梭哥、亞西加、","notes":[]},{"n":36,"t":"沙拉音、亞底他音、基底拉、基底羅他音，共十四座城，還有屬城的村莊。","notes":[]},{"n":37,"t":"又有洗楠、哈大沙、麥大‧迦得、","notes":[]},{"n":38,"t":"底連、米斯巴、約帖、","notes":[]},{"n":39,"t":"拉吉、波斯加、伊磯倫、","notes":[]},{"n":40,"t":"迦本、拉幔、基提利、","notes":[]},{"n":41,"t":"基低羅、伯‧大袞、拿瑪、瑪基大，共十六座城，還有屬城的村莊。","notes":[]},{"n":42,"t":"又有立拿、以帖、亞珊、","notes":[]},{"n":43,"t":"益弗他、亞實拿、尼悉、","notes":[]},{"n":44,"t":"基伊拉、亞革悉、瑪利沙，共九座城，還有屬城的村莊。","notes":[]},{"n":45,"t":"又有以革倫和屬以革倫的鎮市村莊；","notes":[]},{"n":46,"t":"從以革倫直到海，一切靠近亞實突之地，並屬其地的村莊。","notes":[]},{"n":47,"t":"亞實突和屬亞實突的鎮市村莊；迦薩和屬迦薩的鎮市村莊；直到埃及小河，並大海和靠近大海之地。","notes":[]},{"n":48,"t":"在山地有沙密、雅提珥、梭哥、","notes":[]},{"n":49,"t":"大拿、基列‧薩拿（基列‧薩拿就是底璧）、","notes":[]},{"n":50,"t":"亞拿伯、以實提莫、亞念、","notes":[]},{"n":51,"t":"歌珊、何倫、基羅，共十一座城，還有屬城的村莊。","notes":[]},{"n":52,"t":"又有亞拉、度瑪、以珊、","notes":[]},{"n":53,"t":"雅農、伯‧他普亞、亞非加、","notes":[]},{"n":54,"t":"宏他、基列‧亞巴（基列‧亞巴就是希伯崙）、洗珥，共九座城，還有屬城的村莊。","notes":[]},{"n":55,"t":"又有瑪雲、迦密、西弗、淤他、","notes":[]},{"n":56,"t":"耶斯列、約甸、撒挪亞、","notes":[]},{"n":57,"t":"該隱、基比亞、亭納，共十座城，還有屬城的村莊。","notes":[]},{"n":58,"t":"又有哈忽、伯‧夙、基突、","notes":[]},{"n":59,"t":"瑪臘、伯‧亞諾、伊勒提君，共六座城，還有屬城的村莊。","notes":[]},{"n":60,"t":"又有基列‧巴力（基列‧巴力就是基列‧耶琳）、拉巴，共兩座城，還有屬城的村莊。","notes":[]},{"n":61,"t":"在曠野有伯‧亞拉巴、密丁、西迦迦、","notes":[]},{"n":62,"t":"匿珊、鹽城、隱‧基底，共六座城，還有屬城的村莊。","notes":[]},{"n":63,"t":"至於住耶路撒冷的耶布斯人，猶大人不能把他們趕出去，耶布斯人卻在耶路撒冷與猶大人同住，直到今日。","notes":[]}]},"16":{"heading":"分給以法蓮支派和瑪拿西半支派的土地","verses":[{"n":1,"t":"約瑟的子孫拈鬮所得之地是從靠近耶利哥的約旦河起，以耶利哥東邊的水為界：從耶利哥上去，通過山地的曠野，到伯特利；","notes":[]},{"n":2,"t":"又從伯特利到路斯，接連到亞基人的境界，至亞他綠；","notes":[]},{"n":3,"t":"又往西下到押利提人的境界，到下伯‧和崙的境界，直到基色，通到海為止。","notes":[]},{"n":4,"t":"約瑟的兒子瑪拿西、以法蓮就得了他們的地業。","notes":[]},{"n":5,"t":"以法蓮子孫的境界，按著宗族所得的，記在下面：他們地業的東界是亞他綠‧亞達到上伯‧和崙；","notes":[],"heads":["以法蓮支派"]},{"n":6,"t":"往西通到北邊的密米他，又向東繞到他納‧示羅，又接連到雅挪哈的東邊；","notes":[]},{"n":7,"t":"從雅挪哈下到亞他綠，又到拿拉，達到耶利哥，通到約旦河為止；","notes":[]},{"n":8,"t":"從他普亞往西，到加拿河，直通到海為止。這就是以法蓮支派按著宗族所得的地業。","notes":[]},{"n":9,"t":"另外在瑪拿西人地業中得了些城邑和屬城的村莊。這都是分給以法蓮子孫的。","notes":[]},{"n":10,"t":"他們沒有趕出住基色的迦南人；迦南人卻住在以法蓮人中間，成為做苦工的僕人，直到今日。","notes":[]}]},"17":{"heading":"西瑪拿西半支派","verses":[{"n":1,"t":"瑪拿西是約瑟的長子，他的支派拈鬮所得之地記在下面。至於瑪拿西的長子基列之父 瑪吉，因為是勇士就得了基列和巴珊。","notes":["或譯：主"]},{"n":2,"t":"瑪拿西其餘的子孫，按著宗族拈鬮分地，就是亞比以謝子孫，希勒子孫，亞斯列子孫，示劍子孫，希弗子孫，示米大子孫；這些按著宗族，都是約瑟兒子瑪拿西子孫的男丁。","notes":[]},{"n":3,"t":"瑪拿西的玄孫，瑪吉的曾孫，基列的孫子，希弗的兒子西羅非哈沒有兒子，只有女兒。他的女兒名叫瑪拉、挪阿、曷拉、密迦、得撒；","notes":[]},{"n":4,"t":"她們來到祭司以利亞撒和嫩的兒子約書亞並眾首領面前，說：「耶和華曾吩咐摩西在我們弟兄中分給我們產業。」於是約書亞照耶和華所吩咐的，在她們伯叔中，把產業分給她們。","notes":[]},{"n":5,"t":"除了約旦河東的基列和巴珊地之外，還有十分地歸瑪拿西，","notes":[]},{"n":6,"t":"因為瑪拿西的孫女們在瑪拿西的孫子中得了產業。基列地是屬瑪拿西其餘的子孫。","notes":[]},{"n":7,"t":"瑪拿西的境界：從亞設起，到示劍前的密米他，往北到隱‧他普亞居民之地。","notes":[]},{"n":8,"t":"他普亞地歸瑪拿西，只是瑪拿西境界上的他普亞城歸以法蓮子孫。","notes":[]},{"n":9,"t":"其界下到加拿河的南邊。在瑪拿西城邑中的這些城邑都歸以法蓮。瑪拿西的地界是在河北直通到海為止；","notes":[]},{"n":10,"t":"南歸以法蓮，北歸瑪拿西，以海為界；北邊到亞設，東邊到以薩迦。","notes":[]},{"n":11,"t":"瑪拿西在以薩迦和亞設境內，有伯‧善和屬伯‧善的鎮市，以伯蓮和屬以伯蓮的鎮市，多珥的居民和屬多珥的鎮市；又有三處山岡，就是隱‧多珥和屬隱‧多珥的鎮市；他納的居民和屬他納的鎮市，米吉多的居民和屬米吉多的鎮市。","notes":[]},{"n":12,"t":"只是瑪拿西子孫不能趕出這些城的居民，迦南人偏要住在那地。","notes":[]},{"n":13,"t":"及至以色列人強盛了，就使迦南人做苦工，沒有把他們全然趕出。","notes":[]},{"n":14,"t":"約瑟的子孫對約書亞說：「耶和華到如今既然賜福與我們，我們也族大人多，你為甚麼僅將一鬮一段之地分給我們為業呢？」","notes":[],"heads":["約瑟子孫要求多得土地"]},{"n":15,"t":"約書亞說：「你們如果族大人多，嫌以法蓮山地窄小，就可以上比利洗人、利乏音人之地，在樹林中砍伐樹木。」","notes":[]},{"n":16,"t":"約瑟的子孫說：「那山地容不下我們，並且住平原的迦南人，就是住伯‧善和屬伯‧善的鎮市，並住耶斯列平原的人，都有鐵車。」","notes":[]},{"n":17,"t":"約書亞對約瑟家，就是以法蓮和瑪拿西人，說：「你是族大人多，並且強盛，不可僅有一鬮之地，","notes":[]},{"n":18,"t":"山地也要歸你，雖是樹林，你也可以砍伐；靠近之地必歸你。迦南人雖有鐵車，雖是強盛，你也能把他們趕出去。」","notes":[]}]},"18":{"heading":"餘地的分配","verses":[{"n":1,"t":"以色列的全會眾都聚集在示羅，把會幕設立在那裏，那地已經被他們制伏了。","notes":[]},{"n":2,"t":"以色列人中其餘的七個支派還沒有分給他們地業。","notes":[]},{"n":3,"t":"約書亞對以色列人說：「耶和華－你們列祖的神所賜給你們的地，你們耽延不去得，要到幾時呢？","notes":[]},{"n":4,"t":"你們每支派當選舉三個人，我要打發他們去，他們就要起身走遍那地，按著各支派應得的地業寫明，就回到我這裏來。","notes":["或譯：畫圖"]},{"n":5,"t":"他們要將地分做七分；猶大仍在南方，住在他的境內。約瑟家仍在北方，住在他的境內。","notes":[]},{"n":6,"t":"你們要將地分做七分，寫明了拿到我這裏來。我要在耶和華－我們神面前，為你們拈鬮。","notes":[]},{"n":7,"t":"利未人在你們中間沒有分，因為供耶和華祭司的職任就是他們的產業。迦得支派、呂便支派，和瑪拿西半支派已經在約旦河東得了地業，就是耶和華僕人摩西所給他們的。」","notes":[]},{"n":8,"t":"劃地勢的人起身去的時候，約書亞囑咐他們說：「你們去走遍那地，劃明地勢，就回到我這裏來。我要在示羅這裏，耶和華面前，為你們拈鬮。」","notes":[]},{"n":9,"t":"他們就去了，走遍那地，按著城邑分做七分，寫在冊子上，回到示羅營中見約書亞。","notes":[]},{"n":10,"t":"約書亞就在示羅，耶和華面前，為他們拈鬮。約書亞在那裏，按著以色列人的支派，將地分給他們。","notes":[]},{"n":11,"t":"便雅憫支派，按著宗族拈鬮所得之地，是在猶大、約瑟子孫中間。","notes":[],"heads":["分給便雅憫支派的土地"]},{"n":12,"t":"他們的北界是從約旦河起，往上貼近耶利哥的北邊；又往西通過山地，直到伯‧亞文的曠野；","notes":[]},{"n":13,"t":"從那裏往南接連到路斯，貼近路斯（路斯就是伯特利），又下到亞他綠‧亞達，靠近下伯‧和崙南邊的山；","notes":[]},{"n":14,"t":"從那裏往西，又轉向南，從伯‧和崙南對面的山，直達到猶大人的城基列‧巴力（基列‧巴力就是基列‧耶琳）；這是西界。","notes":[]},{"n":15,"t":"南界是從基列‧耶琳的儘邊起，往西達到尼弗多亞的水源；","notes":[]},{"n":16,"t":"又下到欣嫩子谷對面山的儘邊，就是利乏音谷北邊的山；又下到欣嫩谷，貼近耶布斯的南邊；又下到隱‧羅結；","notes":[]},{"n":17,"t":"又往北通到隱‧示麥，達到亞都冥坡對面的基利綠；又下到呂便之子波罕的磐石；","notes":[]},{"n":18,"t":"又接連到亞拉巴對面，往北下到亞拉巴；","notes":[]},{"n":19,"t":"又接連到伯‧曷拉的北邊，直通到鹽海的北汊，就是約旦河的南頭；這是南界。","notes":[]},{"n":20,"t":"東界是約旦河。這是便雅憫人按著宗族，照他們四圍的交界所得的地業。","notes":[]},{"n":21,"t":"便雅憫支派按著宗族所得的城邑就是：耶利哥、伯‧曷拉、伊麥‧基悉、","notes":[]},{"n":22,"t":"伯‧亞拉巴、洗瑪臉、伯特利、","notes":[]},{"n":23,"t":"亞文、巴拉、俄弗拉、","notes":[]},{"n":24,"t":"基法‧阿摩尼、俄弗尼、迦巴，共十二座城，還有屬城的村莊；","notes":[]},{"n":25,"t":"又有基遍、拉瑪、比錄、","notes":[]},{"n":26,"t":"米斯巴、基非拉、摩撒、","notes":[]},{"n":27,"t":"利堅、伊利毗勒、他拉拉、","notes":[]},{"n":28,"t":"洗拉、以利弗、耶布斯（耶布斯就是耶路撒冷）、基比亞、基列，共十四座城，還有屬城的村莊。這是便雅憫人按著宗族所得的地業。","notes":[]}]},"19":{"heading":"分給西緬支派的土地","verses":[{"n":1,"t":"為西緬支派的人，按著宗族，拈出第二鬮。他們所得的地業是在猶大人地業中間。","notes":[]},{"n":2,"t":"他們所得為業之地就是：別是巴（或名示巴）、摩拉大、","notes":[]},{"n":3,"t":"哈薩‧書亞、巴拉、以森、","notes":[]},{"n":4,"t":"伊利多拉、比土力、何珥瑪、","notes":[]},{"n":5,"t":"洗革拉、伯‧瑪加博、哈薩‧蘇撒、","notes":[]},{"n":6,"t":"伯‧利巴勿、沙魯險，共十三座城，還有屬城的村莊；","notes":[]},{"n":7,"t":"又有亞因、利門、以帖、亞珊，共四座城，還有屬城的村莊；","notes":[]},{"n":8,"t":"並有這些城邑四圍一切的村莊，直到巴拉‧比珥，就是南地的拉瑪。這是西緬支派按著宗族所得的地業。","notes":[]},{"n":9,"t":"西緬人的地業是從猶大人地業中得來的；因為猶大人的分過多，所以西緬人在他們的地業中得了地業。","notes":[]},{"n":10,"t":"為西布倫人，按著宗族，拈出第三鬮。他們地業的境界是到撒立；","notes":[],"heads":["分給西布倫支派的土地"]},{"n":11,"t":"往西上到瑪拉拉，達到大巴設，又達到約念前的河；","notes":[]},{"n":12,"t":"又從撒立往東轉向日出之地，到吉斯綠‧他泊的境界，又通到大比拉，上到雅非亞；","notes":[]},{"n":13,"t":"從那裏往東，接連到迦特‧希弗，至以特‧加汛，通到臨門，臨門延到尼亞；","notes":[]},{"n":14,"t":"又繞過尼亞的北邊，轉到哈拿頓，通到伊弗他‧伊勒谷。","notes":[]},{"n":15,"t":"還有加他、拿哈拉、伸崙、以大拉、伯利恆，共十二座城，還有屬城的村莊。","notes":[]},{"n":16,"t":"這些城並屬城的村莊就是西布倫人按著宗族所得的地業。","notes":[]},{"n":17,"t":"為以薩迦人，按著宗族，拈出第四鬮。","notes":[],"heads":["分給以薩迦支派的土地"]},{"n":18,"t":"他們的境界是到耶斯列、基蘇律、書念、","notes":[]},{"n":19,"t":"哈弗連、示按、亞拿哈拉、","notes":[]},{"n":20,"t":"拉璧、基善、亞別、","notes":[]},{"n":21,"t":"利篾、隱‧干寧、隱‧哈大、伯‧帕薛；","notes":[]},{"n":22,"t":"又達到他泊、沙哈洗瑪、伯‧示麥，直通到約旦河為止，共十六座城，還有屬城的村莊。","notes":[]},{"n":23,"t":"這些城並屬城的村莊就是以薩迦支派按著宗族所得的地業。","notes":[]},{"n":24,"t":"為亞設支派，按著宗族，拈出第五鬮。","notes":[],"heads":["分給亞設支派的土地"]},{"n":25,"t":"他們的境界是黑甲、哈利、比田、押煞、","notes":[]},{"n":26,"t":"亞拉米勒、亞末、米沙勒；往西達到迦密，又到希曷‧立納，","notes":[]},{"n":27,"t":"轉向日出之地，到伯‧大袞，達到細步綸；往北到伊弗他‧伊勒谷，到伯‧以墨和尼業，也通到迦步勒的左邊；","notes":[]},{"n":28,"t":"又到義伯崙、利合、哈們、加拿，直到西頓大城；","notes":[]},{"n":29,"t":"轉到拉瑪和堅固城泰爾；又轉到何薩，靠近亞革悉一帶地方，直通到海；","notes":[]},{"n":30,"t":"又有烏瑪、亞弗、利合，共二十二座城，還有屬城的村莊。","notes":[]},{"n":31,"t":"這些城並屬城的村莊就是亞設支派按著宗族所得的地業。","notes":[]},{"n":32,"t":"為拿弗他利人，按著宗族，拈出第六鬮。","notes":[],"heads":["分給拿弗他利支派的土地"]},{"n":33,"t":"他們的境界是從希利弗從撒拿音的橡樹，從亞大米‧尼吉和雅比聶，直到拉共，通到約旦河；","notes":[]},{"n":34,"t":"又轉向西到亞斯納‧他泊，從那裏通到戶割，南邊到西布倫，西邊到亞設，又向日出之地，達到約旦河那裏的猶大。","notes":[]},{"n":35,"t":"堅固的城就是：西丁、側耳、哈末、拉甲、基尼烈、","notes":[]},{"n":36,"t":"亞大瑪、拉瑪、夏瑣、","notes":[]},{"n":37,"t":"基低斯、以得來、隱‧夏瑣、","notes":[]},{"n":38,"t":"以利穩、密大‧伊勒、和璉、伯‧亞納、伯‧示麥，共十九座城，還有屬城的村莊。","notes":[]},{"n":39,"t":"這些城並屬城的村莊就是拿弗他利支派按著宗族所得的地業。","notes":[]},{"n":40,"t":"為但支派，按著宗族，拈出第七鬮。","notes":[],"heads":["分給但支派的土地"]},{"n":41,"t":"他們地業的境界是瑣拉、以實陶、伊珥‧示麥、","notes":[]},{"n":42,"t":"沙拉賓、亞雅崙、伊提拉、","notes":[]},{"n":43,"t":"以倫、亭拿他、以革倫、","notes":[]},{"n":44,"t":"伊利提基、基比頓、巴拉、","notes":[]},{"n":45,"t":"伊胡得、比尼‧比拉、迦特‧臨門、","notes":[]},{"n":46,"t":"美‧耶昆、拉昆，並約帕對面的地界。","notes":[]},{"n":47,"t":"但人的地界越過原得的地界；因為但人上去攻取利善，用刀擊殺城中的人，得了那城，住在其中，以他們先祖但的名將利善改名為但。","notes":[]},{"n":48,"t":"這些城並屬城的村莊就是但支派按著宗族所得的地業。","notes":[]},{"n":49,"t":"以色列人按著境界分完了地業，就在他們中間將地給嫩的兒子約書亞為業，","notes":[],"heads":["最後分配的土地"]},{"n":50,"t":"是照耶和華的吩咐，將約書亞所求的城，就是以法蓮山地的亭拿‧西拉城，給了他。他就修那城，住在其中。","notes":[]},{"n":51,"t":"這就是祭司以利亞撒和嫩的兒子約書亞，並以色列各支派的族長，在示羅會幕門口，耶和華面前，拈鬮所分的地業。這樣，他們把地分完了。","notes":[]}]},"20":{"heading":"設立庇護城","verses":[{"n":1,"t":"耶和華曉諭約書亞說：","notes":[]},{"n":2,"t":"「你吩咐以色列人說：你們要照著我藉摩西所曉諭你們的，為自己設立逃城，","notes":[]},{"n":3,"t":"使那無心而誤殺人的，可以逃到那裏。這些城可以作你們逃避報血仇人的地方。","notes":[]},{"n":4,"t":"那殺人的要逃到這些城中的一座城，站在城門口，將他的事情說給城內的長老們聽。他們就把他收進城裏，給他地方，使他住在他們中間。","notes":[]},{"n":5,"t":"若是報血仇的追了他來，長老不可將他交在報血仇的手裏；因為他是素無仇恨，無心殺了人的。","notes":[]},{"n":6,"t":"他要住在那城裏，站在會眾面前聽審判，等到那時的大祭司死了，殺人的才可以回到本城本家，就是他所逃出來的那城。」","notes":[]},{"n":7,"t":"於是，以色列人在拿弗他利山地分定加利利的基低斯；在以法蓮山地分定示劍；在猶大山地分定基列‧亞巴（基列‧亞巴就是希伯崙）；","notes":[]},{"n":8,"t":"又在約旦河外耶利哥東，從呂便支派中，在曠野的平原，設立比悉；從迦得支派中設立基列的拉末；從瑪拿西支派中設立巴珊的哥蘭。","notes":[]},{"n":9,"t":"這都是為以色列眾人和在他們中間寄居的外人所分定的城邑，使誤殺人的都可以逃到那裏，不死在報血仇人的手中，等他站在會眾面前聽審判。","notes":[]}]},"21":{"heading":"利未人的城邑","verses":[{"n":1,"t":"那時，利未人的眾族長來到祭司以利亞撒和嫩的兒子約書亞，並以色列各支派的族長面前，","notes":[]},{"n":2,"t":"在迦南地的示羅對他們說：「從前耶和華藉著摩西吩咐給我們城邑居住，並城邑的郊野可以牧養我們的牲畜。」","notes":[]},{"n":3,"t":"於是以色列人照耶和華所吩咐的，從自己的地業中，將以下所記的城邑和城邑的郊野給了利未人。","notes":[]},{"n":4,"t":"為哥轄族拈鬮：利未人的祭司、亞倫的子孫，從猶大支派、西緬支派、便雅憫支派的地業中，按鬮得了十三座城。","notes":[]},{"n":5,"t":"哥轄其餘的子孫，從以法蓮支派、但支派、瑪拿西半支派的地業中，按鬮得了十座城。","notes":[]},{"n":6,"t":"革順的子孫，從以薩迦支派、亞設支派、拿弗他利支派、住巴珊的瑪拿西半支派的地業中，按鬮得了十三座城。","notes":[]},{"n":7,"t":"米拉利的子孫，按著宗族，從呂便支派、迦得支派、西布倫支派的地業中，按鬮得了十二座城。","notes":[]},{"n":8,"t":"以色列人照著耶和華藉摩西所吩咐的，將這些城邑和城邑的郊野，按鬮分給利未人。","notes":[]},{"n":9,"t":"從猶大支派、西緬支派的地業中，將以下所記的城給了利未支派哥轄宗族亞倫的子孫；因為給他們拈出頭一鬮，","notes":[],"end":10},{"n":11,"t":"將猶大山地的基列‧亞巴和四圍的郊野給了他們。亞巴是亞衲族的始祖。（基列‧亞巴就是希伯崙）。","notes":[]},{"n":12,"t":"惟將屬城的田地和村莊給了耶孚尼的兒子迦勒為業。","notes":[]},{"n":13,"t":"以色列人將希伯崙，就是誤殺人的逃城和屬城的郊野，給了祭司亞倫的子孫；又給他們立拿和屬城的郊野，","notes":[]},{"n":14,"t":"雅提珥和屬城的郊野，以實提莫和屬城的郊野，","notes":[]},{"n":15,"t":"何崙和屬城的郊野，底璧和屬城的郊野，","notes":[]},{"n":16,"t":"亞因和屬城的郊野，淤他和屬城的郊野，伯‧示麥和屬城的郊野，共九座城，都是從這二支派中分出來的。","notes":[]},{"n":17,"t":"又從便雅憫支派的地業中給了他們基遍和屬城的郊野，迦巴和屬城的郊野，","notes":[]},{"n":18,"t":"亞拿突和屬城的郊野，亞勒們和屬城的郊野，共四座城。","notes":[]},{"n":19,"t":"亞倫子孫作祭司的共有十三座城，還有屬城的郊野。","notes":[]},{"n":20,"t":"利未支派中哥轄的宗族，就是哥轄其餘的子孫，拈鬮所得的城有從以法蓮支派中分出來的。","notes":[]},{"n":21,"t":"以色列人將以法蓮山地的示劍，就是誤殺人的逃城和屬城的郊野，給了他們；又給他們基色和屬城的郊野，","notes":[]},{"n":22,"t":"基伯先和屬城的郊野，伯‧和崙和屬城的郊野，共四座城；","notes":[]},{"n":23,"t":"又從但支派的地業中給了他們伊利提基和屬城的郊野，基比頓和屬城的郊野，","notes":[]},{"n":24,"t":"亞雅崙和屬城的郊野，迦特‧臨門和屬城的郊野，共四座城；","notes":[]},{"n":25,"t":"又從瑪拿西半支派的地業中給了他們他納和屬城的郊野，迦特‧臨門和屬城的郊野，共兩座城。","notes":[]},{"n":26,"t":"哥轄其餘的子孫共有十座城，還有屬城的郊野。","notes":[]},{"n":27,"t":"以色列人又從瑪拿西半支派的地業中將巴珊的哥蘭，就是誤殺人的逃城和屬城的郊野，給了利未支派革順的子孫；又給他們比‧施提拉和屬城的郊野，共兩座城；","notes":[]},{"n":28,"t":"又從以薩迦支派的地業中給了他們基善和屬城的郊野，大比拉和屬城的郊野，","notes":[]},{"n":29,"t":"耶末和屬城的郊野，隱‧干寧和屬城的郊野，共四座城；","notes":[]},{"n":30,"t":"又從亞設支派的地業中給了他們米沙勒和屬城的郊野，押頓和屬城的郊野，","notes":[]},{"n":31,"t":"黑甲和屬城的郊野，利合和屬城的郊野，共四座城；","notes":[]},{"n":32,"t":"又從拿弗他利支派的地業中將加利利的基低斯，就是誤殺人的逃城和屬城的郊野，給了他們；又給他們哈末‧多珥和屬城的郊野，加珥坦和屬城的郊野，共三座城。","notes":[]},{"n":33,"t":"革順人按著宗族所得的城，共十三座，還有屬城的郊野。","notes":[]},{"n":34,"t":"其餘利未支派米拉利子孫，從西布倫支派的地業中所得的，就是約念和屬城的郊野，加珥他和屬城的郊野，","notes":[]},{"n":35,"t":"丁拿和屬城的郊野，拿哈拉和屬城的郊野，共四座城；","notes":[]},{"n":36,"t":"又從呂便支派的地業中給了他們比悉和屬城的郊野，雅雜和屬城的郊野，","notes":[]},{"n":37,"t":"基底莫和屬城的郊野，米法押和屬城的郊野，共四座城；","notes":[]},{"n":38,"t":"又從迦得支派的地業中，將基列的拉末，就是誤殺人的逃城和屬城的郊野，給了他們；又給他們瑪哈念和屬城的郊野，","notes":[]},{"n":39,"t":"希實本和屬城的郊野，雅謝和屬城的郊野，共四座城。","notes":[]},{"n":40,"t":"其餘利未支派的人，就是米拉利的子孫，按著宗族拈鬮所得的，共十二座城。","notes":[]},{"n":41,"t":"利未人在以色列人的地業中所得的城，共四十八座，並有屬城的郊野。","notes":[]},{"n":42,"t":"這些城四圍都有屬城的郊野，城城都是如此。","notes":[]},{"n":43,"t":"這樣，耶和華將從前向他們列祖起誓所應許的全地賜給以色列人，他們就得了為業，住在其中。","notes":[],"heads":["以色列人得地為業"]},{"n":44,"t":"耶和華照著向他們列祖起誓所應許的一切話，使他們四境平安；他們一切仇敵中，沒有一人在他們面前站立得住。耶和華把一切仇敵都交在他們手中。","notes":[]},{"n":45,"t":"耶和華應許賜福給以色列家的話一句也沒有落空，都應驗了。","notes":[]}]},"22":{"heading":"約書亞打發二支派半的人回去","verses":[{"n":1,"t":"當時，約書亞召了呂便人、迦得人，和瑪拿西半支派的人來，","notes":[]},{"n":2,"t":"對他們說：「耶和華僕人摩西所吩咐你們的，你們都遵守了；我所吩咐你們的，你們也都聽從了。","notes":[]},{"n":3,"t":"你們這許多日子，總沒有撇離你們的弟兄，直到今日，並守了耶和華－你們神所吩咐你們當守的。","notes":[]},{"n":4,"t":"如今耶和華－你們神照著他所應許的，使你們弟兄得享平安，現在可以轉回你們的帳棚，到耶和華的僕人摩西在約旦河東所賜你們為業之地。","notes":[]},{"n":5,"t":"只要切切地謹慎遵行耶和華僕人摩西所吩咐你們的誡命律法，愛耶和華－你們的神，行他一切的道，守他的誡命，專靠他，盡心盡性事奉他。」","notes":[]},{"n":6,"t":"於是約書亞為他們祝福，打發他們去，他們就回自己的帳棚去了。","notes":[]},{"n":7,"t":"瑪拿西那半支派，摩西早已在巴珊分給他們地業。這半支派，約書亞在約旦河西，在他們弟兄中，分給他們地業。約書亞打發他們回帳棚的時候為他們祝福，","notes":[]},{"n":8,"t":"對他們說：「你們帶許多財物，許多牲畜和金、銀、銅、鐵，並許多衣服，回你們的帳棚去，要將你們從仇敵奪來的物，與你們眾弟兄同分。」","notes":[]},{"n":9,"t":"於是呂便人、迦得人、瑪拿西半支派的人從迦南地的示羅起行，離開以色列人，回往他們得為業的基列地，就是照耶和華藉摩西所吩咐的得了為業之地。","notes":[]},{"n":10,"t":"呂便人、迦得人，和瑪拿西半支派的人到了靠近約旦河的一帶迦南地，就在約旦河那裏築了一座壇；那壇看著高大。","notes":[],"heads":["約旦河旁的祭壇"]},{"n":11,"t":"以色列人聽說呂便人、迦得人、瑪拿西半支派的人靠近約旦河邊，在迦南地屬以色列人的那邊築了一座壇。","notes":[]},{"n":12,"t":"全會眾一聽見，就聚集在示羅，要上去攻打他們。","notes":[]},{"n":13,"t":"以色列人打發祭司以利亞撒的兒子非尼哈，往基列地去見呂便人、迦得人、瑪拿西半支派的人；","notes":[]},{"n":14,"t":"又打發十個首領與非尼哈同去，就是以色列每支派的一個首領，都是以色列軍中的統領。","notes":[]},{"n":15,"t":"他們到了基列地，見呂便人、迦得人，和瑪拿西半支派的人，對他們說：","notes":[]},{"n":16,"t":"「耶和華全會眾這樣說，你們今日轉去不跟從耶和華，干犯以色列的神，為自己築一座壇，悖逆了耶和華，這犯的是甚麼罪呢？","notes":[]},{"n":17,"t":"從前拜毗珥的罪孽還算小嗎？雖然瘟疫臨到耶和華的會眾，到今日我們還沒有洗淨這罪。","notes":[]},{"n":18,"t":"你們今日竟轉去不跟從耶和華嗎？你們今日既悖逆耶和華，明日他必向以色列全會眾發怒。","notes":[]},{"n":19,"t":"你們所得為業之地，若嫌不潔淨，就可以過到耶和華之地，就是耶和華的帳幕所住之地，在我們中間得地業。只是不可悖逆耶和華，也不可得罪我們，在耶和華－我們神的壇以外為自己築壇。","notes":[]},{"n":20,"t":"從前謝拉的曾孫亞干豈不是在那當滅的物上犯了罪，就有忿怒臨到以色列全會眾嗎？那人在所犯的罪中不獨一人死亡。」","notes":[]},{"n":21,"t":"於是呂便人、迦得人、瑪拿西半支派的人回答以色列軍中的統領說：","notes":[]},{"n":22,"t":"「大能者神耶和華！大能者神耶和華！他是知道的！以色列人也必知道！我們若有悖逆的意思，或是干犯耶和華（願你今日不保佑我們），","notes":[]},{"n":23,"t":"為自己築壇，要轉去不跟從耶和華，或是要將燔祭、素祭、平安祭獻在壇上，願耶和華親自討我們的罪。","notes":[]},{"n":24,"t":"我們行這事並非無故，是特意做的，說：恐怕日後你們的子孫對我們的子孫說：『你們與耶和華－以色列的神有何關涉呢？","notes":[]},{"n":25,"t":"因為耶和華把約旦河定為我們和你們這呂便人、迦得人的交界，你們與耶和華無分了。』這樣，你們的子孫就使我們的子孫不再敬畏耶和華了。","notes":[]},{"n":26,"t":"因此我們說：『不如為自己築一座壇，不是為獻燔祭，也不是為獻別的祭，","notes":[]},{"n":27,"t":"乃是為你我中間和你我後人中間作證據，好叫我們也在耶和華面前獻燔祭、平安祭，和別的祭事奉他，免得你們的子孫日後對我們的子孫說，你們與耶和華無分了。』","notes":[]},{"n":28,"t":"所以我們說：『日後你們對我們，或對我們的後人這樣說，我們就可以回答說，你們看我們列祖所築的壇是耶和華壇的樣式；這並不是為獻燔祭，也不是為獻別的祭，乃是為作你我中間的證據。』","notes":[]},{"n":29,"t":"我們在耶和華－我們神帳幕前的壇以外，另築一座壇，為獻燔祭、素祭，和別的祭，悖逆耶和華，今日轉去不跟從他，我們斷沒有這個意思。」","notes":[]},{"n":30,"t":"祭司非尼哈與會中的首領，就是與他同來以色列軍中的統領，聽見呂便人、迦得人、瑪拿西人所說的話，就都以為美。","notes":[]},{"n":31,"t":"祭司以利亞撒的兒子非尼哈對呂便人、迦得人、瑪拿西人說：「今日我們知道耶和華在我們中間，因為你們沒有向他犯了這罪。現在你們救以色列人脫離耶和華的手了。」","notes":[]},{"n":32,"t":"祭司以利亞撒的兒子非尼哈與眾首領離了呂便人、迦得人，從基列地回往迦南地，到了以色列人那裏，便將這事回報他們。","notes":[]},{"n":33,"t":"以色列人以這事為美，就稱頌神，不再提上去攻打呂便人、迦得人、毀壞他們所住的地了。","notes":[]},{"n":34,"t":"呂便人、迦得人給壇起名叫證壇，意思說：這壇在我們中間證明耶和華是神。","notes":[]}]},"23":{"heading":"約書亞的遺言","verses":[{"n":1,"t":"耶和華使以色列人安靜，不與四圍的一切仇敵爭戰，已經多日。約書亞年紀老邁，","notes":[]},{"n":2,"t":"就把以色列眾人的長老、族長、審判官，並官長都召了來，對他們說：「我年紀已經老邁。","notes":[]},{"n":3,"t":"耶和華－你們的神因你們的緣故向那些國所行的一切事，你們親眼看見了，因那為你們爭戰的是耶和華－你們的神。","notes":[]},{"n":4,"t":"我所剪除和所剩下的各國，從約旦河起到日落之處的大海，我已經拈鬮分給你們各支派為業。","notes":[]},{"n":5,"t":"耶和華－你們的神必將他們從你們面前趕出去，使他們離開你們，你們就必得他們的地為業，正如耶和華－你們的神所應許的。","notes":[]},{"n":6,"t":"所以，你們要大大壯膽，謹守遵行寫在摩西律法書上的一切話，不可偏離左右。","notes":[]},{"n":7,"t":"不可與你們中間所剩下的這些國民攙雜。他們的神，你們不可提他的名，不可指著他起誓，也不可事奉、叩拜；","notes":[]},{"n":8,"t":"只要照著你們到今日所行的，專靠耶和華－你們的神。","notes":[]},{"n":9,"t":"因為耶和華已經把又大又強的國民從你們面前趕出；直到今日，沒有一人在你們面前站立得住。","notes":[]},{"n":10,"t":"你們一人必追趕千人，因耶和華－你們的神照他所應許的，為你們爭戰。","notes":[]},{"n":11,"t":"你們要分外謹慎，愛耶和華－你們的神。","notes":[]},{"n":12,"t":"你們若稍微轉去，與你們中間所剩下的這些國民聯絡，彼此結親，互相往來，","notes":[]},{"n":13,"t":"你們要確實知道，耶和華－你們的神必不再將他們從你們眼前趕出；他們卻要成為你們的網羅、機檻、肋上的鞭、眼中的刺，直到你們在耶和華－你們神所賜的這美地上滅亡。","notes":[]},{"n":14,"t":"「我現在要走世人必走的路。你們是一心一意地知道，耶和華－你們神所應許賜福與你們的話沒有一句落空，都應驗在你們身上了。","notes":[]},{"n":15,"t":"耶和華－你們神所應許的一切福氣怎樣臨到你們身上，耶和華也必照樣使各樣禍患臨到你們身上，直到把你們從耶和華－你們神所賜的這美地上除滅。","notes":[]},{"n":16,"t":"你們若違背耶和華－你們神吩咐你們所守的約，去事奉別神，叩拜他，耶和華的怒氣必向你們發作，使你們在他所賜的美地上速速滅亡。」","notes":[]}]},"24":{"heading":"約書亞在示劍向百姓講話","verses":[{"n":1,"t":"約書亞將以色列的眾支派聚集在示劍，召了以色列的長老、族長、審判官，並官長來，他們就站在神面前。","notes":[]},{"n":2,"t":"約書亞對眾民說：「耶和華－以色列的神如此說：『古時你們的列祖，就是亞伯拉罕和拿鶴的父親他拉，住在大河那邊事奉別神，","notes":[]},{"n":3,"t":"我將你們的祖宗亞伯拉罕從大河那邊帶來，領他走遍迦南全地，又使他的子孫眾多，把以撒賜給他；","notes":[]},{"n":4,"t":"又把雅各和以掃賜給以撒，將西珥山賜給以掃為業；後來雅各和他的子孫下到埃及去了。","notes":[]},{"n":5,"t":"我差遣摩西、亞倫，並照我在埃及中所行的降災與埃及，然後把你們領出來。","notes":[]},{"n":6,"t":"我領你們列祖出埃及，他們就到了紅海；埃及人帶領車輛馬兵追趕你們列祖到紅海。","notes":[]},{"n":7,"t":"你們列祖哀求耶和華，他就使你們和埃及人中間黑暗了，又使海水淹沒埃及人。我在埃及所行的事，你們親眼見過。你們在曠野也住了許多年日。","notes":[]},{"n":8,"t":"我領你們到約旦河東亞摩利人所住之地。他們與你們爭戰，我將他們交在你們手中，你們便得了他們的地為業；我也在你們面前將他們滅絕。","notes":[]},{"n":9,"t":"那時，摩押王西撥的兒子巴勒起來攻擊以色列人，打發人召了比珥的兒子巴蘭來咒詛你們。","notes":[]},{"n":10,"t":"我不肯聽巴蘭的話，所以他倒為你們連連祝福。這樣，我便救你們脫離巴勒的手。","notes":[]},{"n":11,"t":"你們過了約旦河，到了耶利哥；耶利哥人、亞摩利人、比利洗人、迦南人、赫人、革迦撒人、希未人、耶布斯人都與你們爭戰；我把他們交在你們手裏。","notes":[]},{"n":12,"t":"我打發黃蜂飛在你們前面，將亞摩利人的二王從你們面前攆出，並不是用你的刀，也不是用你的弓。","notes":[]},{"n":13,"t":"我賜給你們地土，非你們所修治的；我賜給你們城邑，非你們所建造的。你們就住在其中，又得吃非你們所栽種的葡萄園、橄欖園的果子。』","notes":[]},{"n":14,"t":"「現在你們要敬畏耶和華，誠心實意地事奉他，將你們列祖在大河那邊和在埃及所事奉的神除掉，去事奉耶和華。","notes":[]},{"n":15,"t":"若是你們以事奉耶和華為不好，今日就可以選擇所要事奉的：是你們列祖在大河那邊所事奉的神呢？是你們所住這地的亞摩利人的神呢？至於我和我家，我們必定事奉耶和華。」","notes":[]},{"n":16,"t":"百姓回答說：「我們斷不敢離棄耶和華去事奉別神；","notes":[]},{"n":17,"t":"因耶和華－我們的神曾將我們和我們列祖從埃及地的為奴之家領出來，在我們眼前行了那些大神蹟，在我們所行的道上，所經過的諸國，都保護了我們。","notes":[]},{"n":18,"t":"耶和華又把住此地的亞摩利人都從我們面前趕出去。所以，我們必事奉耶和華，因為他是我們的神。」","notes":[]},{"n":19,"t":"約書亞對百姓說：「你們不能事奉耶和華；因為他是聖潔的神，是忌邪的神，必不赦免你們的過犯罪惡。","notes":[]},{"n":20,"t":"你們若離棄耶和華去事奉外邦神，耶和華在降福之後，必轉而降禍與你們，把你們滅絕。」","notes":[]},{"n":21,"t":"百姓回答約書亞說：「不然，我們定要事奉耶和華。」","notes":[]},{"n":22,"t":"約書亞對百姓說：「你們選定耶和華，要事奉他，你們自己作見證吧！」他們說：「我們願意作見證。」","notes":[]},{"n":23,"t":"約書亞說：「你們現在要除掉你們中間的外邦神，專心歸向耶和華－以色列的神。」","notes":[]},{"n":24,"t":"百姓回答約書亞說：「我們必事奉耶和華－我們的神，聽從他的話。」","notes":[]},{"n":25,"t":"當日，約書亞就與百姓立約，在示劍為他們立定律例典章。","notes":[]},{"n":26,"t":"約書亞將這些話都寫在神的律法書上，又將一塊大石頭立在橡樹下耶和華的聖所旁邊。","notes":[]},{"n":27,"t":"約書亞對百姓說：「看哪，這石頭可以向我們作見證；因為是聽見了耶和華所吩咐我們的一切話，倘或你們背棄你們的神，這石頭就可以向你們作見證。」","notes":["倘或…見證：或譯所以要向你們作見證，免得你們背棄耶和華－你們的神"]},{"n":28,"t":"於是約書亞打發百姓各歸自己的地業去了。","notes":[]},{"n":29,"t":"這些事以後，耶和華的僕人嫩的兒子約書亞，正一百一十歲，就死了。","notes":[],"heads":["約書亞和以利亞撒去世"]},{"n":30,"t":"以色列人將他葬在他地業的境內，就是在以法蓮山地的亭拿‧西拉，在迦實山的北邊。","notes":[]},{"n":31,"t":"約書亞在世和約書亞死後，那些知道耶和華為以色列人所行諸事的長老還在的時候，以色列人事奉耶和華。","notes":[]},{"n":32,"t":"以色列人從埃及所帶來約瑟的骸骨，葬埋在示劍，就是在雅各從前用一百塊銀子向示劍的父親、哈抹的子孫所買的那塊地裏；這就作了約瑟子孫的產業。","notes":[]},{"n":33,"t":"亞倫的兒子以利亞撒也死了，就把他葬在他兒子非尼哈所得以法蓮山地的小山上。","notes":[]}]}},"JDG":{"1":{"heading":"猶大和西緬支派俘虜亞多尼‧比色","verses":[{"n":1,"t":"約書亞死後，以色列人求問耶和華說：「我們中間誰當首先上去攻擊迦南人，與他們爭戰？」","notes":[]},{"n":2,"t":"耶和華說：「猶大當先上去，我已將那地交在他手中。」","notes":[]},{"n":3,"t":"猶大對他哥哥西緬說：「請你同我到拈鬮所得之地去，好與迦南人爭戰；以後我也同你到你拈鬮所得之地去。」於是西緬與他同去。","notes":[]},{"n":4,"t":"猶大就上去；耶和華將迦南人和比利洗人交在他們手中。他們在比色擊殺了一萬人，","notes":[]},{"n":5,"t":"又在那裏遇見亞多尼‧比色，與他爭戰，殺敗迦南人和比利洗人。","notes":[]},{"n":6,"t":"亞多尼‧比色逃跑；他們追趕，拿住他，砍斷他手腳的大拇指。","notes":[]},{"n":7,"t":"亞多尼‧比色說：「從前有七十個王，手腳的大拇指都被我砍斷，在我桌子底下拾取零碎食物。現在神按著我所行的報應我了。」於是他們將亞多尼‧比色帶到耶路撒冷，他就死在那裏。","notes":[]},{"n":8,"t":"猶大人攻打耶路撒冷，將城攻取，用刀殺了城內的人，並且放火燒城。","notes":[],"heads":["猶大支派攻取耶路撒冷和希伯崙"]},{"n":9,"t":"後來猶大人下去，與住山地、南地，和高原的迦南人爭戰。","notes":[]},{"n":10,"t":"猶大人去攻擊住希伯崙的迦南人，殺了示篩、亞希幔、撻買。希伯崙從前名叫基列‧亞巴。","notes":[]},{"n":11,"t":"他們從那裏去攻擊底壁的居民；底壁從前名叫基列‧西弗。","notes":[],"heads":["俄陀聶攻取底壁城"]},{"n":12,"t":"迦勒說：「誰能攻打基列‧西弗，將城奪取，我就把我女兒押撒給他為妻。」","notes":[]},{"n":13,"t":"迦勒兄弟基納斯的兒子俄陀聶奪取了那城，迦勒就把女兒押撒給他為妻。","notes":[]},{"n":14,"t":"押撒過門的時候，勸丈夫向她父親求一塊田。押撒一下驢，迦勒問她說：「你要甚麼？」","notes":[]},{"n":15,"t":"她說：「求你賜福給我，你既將我安置在南地，求你也給我水泉。」迦勒就把上泉下泉賜給她。","notes":[]},{"n":16,"t":"摩西的內兄是基尼人，他的子孫與猶大人一同離了棕樹城，往亞拉得以南的猶大曠野去，就住在民中。","notes":["或譯：岳父"],"heads":["猶大和便雅憫支派的勝利"]},{"n":17,"t":"猶大和他哥哥西緬同去，擊殺了住洗法的迦南人，將城盡行毀滅，那城的名便叫何珥瑪。","notes":[]},{"n":18,"t":"猶大又取了迦薩和迦薩的四境，亞實基倫和亞實基倫的四境，以革倫和以革倫的四境。","notes":[]},{"n":19,"t":"耶和華與猶大同在，猶大就趕出山地的居民，只是不能趕出平原的居民，因為他們有鐵車。","notes":[]},{"n":20,"t":"以色列人照摩西所說的，將希伯崙給了迦勒；迦勒就從那裏趕出亞衲族的三個族長。","notes":[]},{"n":21,"t":"便雅憫人沒有趕出住耶路撒冷的耶布斯人。耶布斯人仍在耶路撒冷與便雅憫人同住，直到今日。","notes":[]},{"n":22,"t":"約瑟家也上去攻打伯特利；耶和華與他們同在。","notes":[],"heads":["以法蓮和瑪拿西支派攻取伯特利"]},{"n":23,"t":"約瑟家打發人去窺探伯特利（那城起先名叫路斯）。","notes":[]},{"n":24,"t":"窺探的人看見一個人從城裏出來，就對他說：「求你將進城的路指示我們，我們必恩待你。」","notes":[]},{"n":25,"t":"那人將進城的路指示他們，他們就用刀擊殺了城中的居民，但將那人和他全家放去。","notes":[]},{"n":26,"t":"那人往赫人之地去，築了一座城，起名叫路斯。那城到如今還叫這名。","notes":[]},{"n":27,"t":"瑪拿西沒有趕出伯‧善和屬伯‧善鄉村的居民，他納和屬他納鄉村的居民，多珥和屬多珥鄉村的居民，以伯蓮和屬以伯蓮鄉村的居民，米吉多和屬米吉多鄉村的居民；迦南人卻執意住在那些地方。","notes":[],"heads":["以色列人沒有趕出去的民"]},{"n":28,"t":"及至以色列強盛了，就使迦南人做苦工，沒有把他們全然趕出。","notes":[]},{"n":29,"t":"以法蓮沒有趕出住基色的迦南人。於是迦南人仍住在基色，在以法蓮中間。","notes":[]},{"n":30,"t":"西布倫沒有趕出基倫的居民和拿哈拉的居民。於是迦南人仍住在西布倫中間，成了服苦的人。","notes":[]},{"n":31,"t":"亞設沒有趕出亞柯和西頓的居民，亞黑拉和亞革悉的居民，黑巴、亞弗革與利合的居民。","notes":[]},{"n":32,"t":"於是，亞設因為沒有趕出那地的迦南人，就住在他們中間。","notes":[]},{"n":33,"t":"拿弗他利沒有趕出伯‧示麥和伯‧亞納的居民，於是拿弗他利就住在那地的迦南人中間；然而伯‧示麥和伯‧亞納的居民成了服苦的人。","notes":[]},{"n":34,"t":"亞摩利人強逼但人住在山地，不容他們下到平原；","notes":[]},{"n":35,"t":"亞摩利人卻執意住在希烈山和亞雅崙並沙賓。然而約瑟家勝了他們，使他們成了服苦的人。","notes":[]},{"n":36,"t":"亞摩利人的境界，是從亞克拉濱坡，從西拉而上。","notes":[]}]},"2":{"heading":"耶和華的使者在波金","verses":[{"n":1,"t":"耶和華的使者從吉甲上到波金，對以色列人說：「我使你們從埃及上來，領你們到我向你們列祖起誓應許之地。我又說：『我永不廢棄與你們所立的約。","notes":[]},{"n":2,"t":"你們也不可與這地的居民立約，要拆毀他們的祭壇。你們竟沒有聽從我的話！為何這樣行呢？』","notes":[]},{"n":3,"t":"因此我又說：『我必不將他們從你們面前趕出；他們必作你們肋下的荊棘。他們的神必作你們的網羅。』」","notes":[]},{"n":4,"t":"耶和華的使者向以色列眾人說這話的時候，百姓就放聲而哭；","notes":[]},{"n":5,"t":"於是給那地方起名叫波金。眾人在那裏向耶和華獻祭。","notes":["就是哭的意思"]},{"n":6,"t":"從前約書亞打發以色列百姓去的時候，他們各歸自己的地業，佔據地土。","notes":[],"heads":["約書亞去世"]},{"n":7,"t":"約書亞在世和約書亞死後，那些見耶和華為以色列人所行大事的長老還在的時候，百姓都事奉耶和華。","notes":[]},{"n":8,"t":"耶和華的僕人、嫩的兒子約書亞，正一百一十歲就死了。","notes":[]},{"n":9,"t":"以色列人將他葬在他地業的境內，就是在以法蓮山地的亭拿‧希烈，在迦實山的北邊。","notes":[]},{"n":10,"t":"那世代的人也都歸了自己的列祖。後來有別的世代興起，不知道耶和華，也不知道耶和華為以色列人所行的事。","notes":[]},{"n":11,"t":"以色列人行耶和華眼中看為惡的事，去事奉諸巴力，","notes":[],"heads":["以色列離棄耶和華"]},{"n":12,"t":"離棄了領他們出埃及地的耶和華－他們列祖的神，去叩拜別神，就是四圍列國的神，惹耶和華發怒；","notes":[]},{"n":13,"t":"並離棄耶和華，去事奉巴力和亞斯她錄。","notes":[]},{"n":14,"t":"耶和華的怒氣向以色列人發作，就把他們交在搶奪他們的人手中，又將他們付與四圍仇敵的手中，甚至他們在仇敵面前再不能站立得住。","notes":[]},{"n":15,"t":"他們無論往何處去，耶和華都以災禍攻擊他們，正如耶和華所說的話，又如耶和華向他們所起的誓；他們便極其困苦。","notes":[]},{"n":16,"t":"耶和華興起士師，士師就拯救他們脫離搶奪他們人的手。","notes":[]},{"n":17,"t":"他們卻不聽從士師，竟隨從叩拜別神，行了邪淫，速速地偏離他們列祖所行的道，不如他們列祖順從耶和華的命令。","notes":[]},{"n":18,"t":"耶和華為他們興起士師，就與那士師同在。士師在世的一切日子，耶和華拯救他們脫離仇敵的手。他們因受欺壓擾害，就哀聲歎氣，所以耶和華後悔了。","notes":[]},{"n":19,"t":"及至士師死後，他們就轉去行惡，比他們列祖更甚，去事奉叩拜別神，總不斷絕頑梗的惡行。","notes":[]},{"n":20,"t":"於是耶和華的怒氣向以色列人發作。他說：「因這民違背我吩咐他們列祖所守的約，不聽從我的話，","notes":[]},{"n":21,"t":"所以約書亞死的時候所剩下的各族，我必不再從他們面前趕出，","notes":[]},{"n":22,"t":"為要藉此試驗以色列人，看他們肯照他們列祖謹守遵行我的道不肯。」","notes":[]},{"n":23,"t":"這樣耶和華留下各族，不將他們速速趕出，也沒有交付約書亞的手。","notes":[]}]},"3":{"heading":"留下來的民族","verses":[{"n":1,"t":"耶和華留下這幾族，為要試驗那不曾知道與迦南爭戰之事的以色列人，","notes":[]},{"n":2,"t":"好叫以色列的後代又知道又學習未曾曉得的戰事。","notes":[]},{"n":3,"t":"所留下的就是非利士的五個首領和一切迦南人、西頓人，並住黎巴嫩山的希未人，從巴力‧黑們山直到哈馬口。","notes":[]},{"n":4,"t":"留下這幾族，為要試驗以色列人，知道他們肯聽從耶和華藉摩西吩咐他們列祖的誡命不肯。","notes":[]},{"n":5,"t":"以色列人竟住在迦南人、赫人、亞摩利人、比利洗人、希未人、耶布斯人中間，","notes":[]},{"n":6,"t":"娶他們的女兒為妻，將自己的女兒嫁給他們的兒子，並事奉他們的神。","notes":[]},{"n":7,"t":"以色列人行耶和華眼中看為惡的事，忘記耶和華－他們的神，去事奉諸巴力和亞舍拉，","notes":[],"heads":["俄陀聶"]},{"n":8,"t":"所以耶和華的怒氣向以色列人發作，就把他們交在美索不達米亞王古珊‧利薩田的手中。以色列人服事古珊‧利薩田八年。","notes":[]},{"n":9,"t":"以色列人呼求耶和華的時候，耶和華就為他們興起一位拯救者救他們，就是迦勒兄弟基納斯的兒子俄陀聶。","notes":[]},{"n":10,"t":"耶和華的靈降在他身上，他就作了以色列的士師，出去爭戰。耶和華將美索不達米亞王古珊‧利薩田交在他手中，他便勝了古珊‧利薩田。","notes":[]},{"n":11,"t":"於是國中太平四十年。基納斯的兒子俄陀聶死了。","notes":[]},{"n":12,"t":"以色列人又行耶和華眼中看為惡的事，耶和華就使摩押王伊磯倫強盛，攻擊以色列人。","notes":[],"heads":["以笏"]},{"n":13,"t":"伊磯倫招聚亞捫人和亞瑪力人，去攻打以色列人，佔據棕樹城。","notes":[]},{"n":14,"t":"於是以色列人服事摩押王伊磯倫十八年。","notes":[]},{"n":15,"t":"以色列人呼求耶和華的時候，耶和華就為他們興起一位拯救者，就是便雅憫人基拉的兒子以笏；他是左手便利的。以色列人託他送禮物給摩押王伊磯倫。","notes":[]},{"n":16,"t":"以笏打了一把兩刃的劍，長一肘，帶在右腿上衣服裏面。","notes":[]},{"n":17,"t":"他將禮物獻給摩押王伊磯倫（原來伊磯倫極其肥胖）；","notes":[]},{"n":18,"t":"以笏獻完禮物，便將抬禮物的人打發走了，","notes":[]},{"n":19,"t":"自己卻從靠近吉甲鑿石之地回來，說：「王啊，我有一件機密事奏告你。」王說：「迴避吧！」於是左右侍立的人都退去了。","notes":[]},{"n":20,"t":"以笏來到王面前；王獨自一人坐在涼樓上。以笏說：「我奉神的命報告你一件事。」王就從座位上站起來。","notes":[]},{"n":21,"t":"以笏便伸左手，從右腿上拔出劍來，刺入王的肚腹，","notes":[]},{"n":22,"t":"連劍把都刺進去了。劍被肥肉夾住，他沒有從王的肚腹拔出來，且穿通了後身。","notes":[]},{"n":23,"t":"以笏就出到遊廊，將樓門盡都關鎖。","notes":[]},{"n":24,"t":"以笏出來之後，王的僕人到了，看見樓門關鎖，就說：「他必是在樓上大解。」","notes":[]},{"n":25,"t":"他們等煩了，見仍不開樓門，就拿鑰匙開了，不料，他們的主人已死，倒在地上。","notes":[]},{"n":26,"t":"他們耽延的時候，以笏就逃跑了，經過鑿石之地，逃到西伊拉；","notes":[]},{"n":27,"t":"到了，就在以法蓮山地吹角。以色列人隨著他下了山地，他在前頭引路，","notes":[]},{"n":28,"t":"對他們說：「你們隨我來，因為耶和華已經把你們的仇敵摩押人交在你們手中。」於是他們跟著他下去，把守約旦河的渡口，不容摩押一人過去。","notes":[]},{"n":29,"t":"那時擊殺了摩押人約有一萬，都是強壯的勇士，沒有一人逃脫。","notes":[]},{"n":30,"t":"這樣，摩押就被以色列人制伏了。國中太平八十年。","notes":[]},{"n":31,"t":"以笏之後，有亞拿的兒子珊迦，他用趕牛的棍子打死六百非利士人。他也救了以色列人。","notes":[],"heads":["珊迦"]}]},"4":{"heading":"底波拉和巴拉","verses":[{"n":1,"t":"以笏死後，以色列人又行耶和華眼中看為惡的事，","notes":[]},{"n":2,"t":"耶和華就把他們付與在夏瑣作王的迦南王耶賓手中；他的將軍是西西拉，住在外邦人的夏羅設。","notes":[]},{"n":3,"t":"耶賓王有鐵車九百輛。他大大欺壓以色列人二十年，以色列人就呼求耶和華。","notes":[]},{"n":4,"t":"有一位女先知名叫底波拉，是拉比多的妻，當時作以色列的士師。","notes":[]},{"n":5,"t":"她住在以法蓮山地拉瑪和伯特利中間，在底波拉的棕樹下。以色列人都上她那裏去聽判斷。","notes":[]},{"n":6,"t":"她打發人從拿弗他利的基低斯將亞比挪菴的兒子巴拉召了來，對他說：「耶和華－以色列的神吩咐你說：『你率領一萬拿弗他利和西布倫人上他泊山去。","notes":[]},{"n":7,"t":"我必使耶賓的將軍西西拉率領他的車輛和全軍往基順河，到你那裏去；我必將他交在你手中。』」","notes":[]},{"n":8,"t":"巴拉說：「你若同我去，我就去；你若不同我去，我就不去。」","notes":[]},{"n":9,"t":"底波拉說：「我必與你同去，只是你在所行的路上得不著榮耀，因為耶和華要將西西拉交在一個婦人手裏。」於是底波拉起來，與巴拉一同往基低斯去了。","notes":[]},{"n":10,"t":"巴拉就招聚西布倫人和拿弗他利人到基低斯，跟他上去的有一萬人。底波拉也同他上去。","notes":[]},{"n":11,"t":"摩西岳父 何巴的後裔，基尼人希百曾離開基尼族，到靠近基低斯、撒拿音的橡樹旁支搭帳棚。","notes":["或譯：內兄"]},{"n":12,"t":"有人告訴西西拉說：「亞比挪菴的兒子巴拉已經上他泊山了。」","notes":[]},{"n":13,"t":"西西拉就聚集所有的鐵車九百輛和跟隨他的全軍，從外邦人的夏羅設出來，到了基順河。","notes":[]},{"n":14,"t":"底波拉對巴拉說：「你起來，今日就是耶和華將西西拉交在你手的日子。耶和華豈不在你前頭行嗎？」於是巴拉下了他泊山，跟隨他有一萬人。","notes":[]},{"n":15,"t":"耶和華使西西拉和他一切車輛全軍潰亂，在巴拉面前被刀殺敗；西西拉下車步行逃跑。","notes":[]},{"n":16,"t":"巴拉追趕車輛、軍隊，直到外邦人的夏羅設。西西拉的全軍都倒在刀下，沒有留下一人。","notes":[]},{"n":17,"t":"只有西西拉步行逃跑，到了基尼人希百之妻雅億的帳棚，因為夏瑣王耶賓與基尼人希百家和好。","notes":[]},{"n":18,"t":"雅億出來迎接西西拉，對他說：「請我主進來，不要懼怕」；西西拉就進了她的帳棚。雅億用被將他遮蓋。","notes":[]},{"n":19,"t":"西西拉對雅億說：「我渴了，求你給我一點水喝。」雅億就打開皮袋，給他奶子喝，仍舊把他遮蓋。","notes":[]},{"n":20,"t":"西西拉又對雅億說：「請你站在帳棚門口，若有人來問你說：『有人在這裏沒有？』你就說：『沒有。』」","notes":[]},{"n":21,"t":"西西拉疲乏沉睡。希百的妻雅億取了帳棚的橛子，手裏拿著錘子，輕悄悄地到他旁邊，將橛子從他鬢邊釘進去，釘入地裏。西西拉就死了。","notes":[]},{"n":22,"t":"巴拉追趕西西拉的時候，雅億出來迎接他說：「來吧，我將你所尋找的人給你看。」他就進入帳棚，看見西西拉已經死了，倒在地上，橛子還在他鬢中。","notes":[]},{"n":23,"t":"這樣，神使迦南王耶賓被以色列人制伏了。","notes":[]},{"n":24,"t":"從此以色列人的手越發有力，勝了迦南王耶賓，直到將他滅絕了。","notes":[]}]},"5":{"heading":"底波拉和巴拉的歌","verses":[{"n":1,"t":"那時，底波拉和亞比挪菴的兒子巴拉作歌，說：","notes":[]},{"n":2,"t":"因為以色列中有軍長率領，百姓也甘心犧牲自己，你們應當頌讚耶和華！","notes":[]},{"n":3,"t":"君王啊，要聽！王子啊，要側耳而聽！我要向耶和華歌唱；我要歌頌耶和華－以色列的神。","notes":[]},{"n":4,"t":"耶和華啊，你從西珥出來，由以東地行走。那時地震天漏，雲也落雨。","notes":[]},{"n":5,"t":"山見耶和華的面就震動，西奈山見耶和華－以色列神的面也是如此。","notes":[]},{"n":6,"t":"在亞拿之子珊迦的時候，又在雅億的日子，大道無人行走，都是繞道而行。","notes":[]},{"n":7,"t":"以色列中的官長停職，直到我底波拉興起，等我興起作以色列的母。","notes":[]},{"n":8,"t":"以色列人選擇新神，爭戰的事就臨到城門。那時，以色列四萬人中豈能見盾牌槍矛呢？","notes":[]},{"n":9,"t":"我心傾向以色列的首領，他們在民中甘心犧牲自己。你們應當頌讚耶和華！","notes":[]},{"n":10,"t":"騎白驢的、坐繡花毯子的、行路的，你們都當傳揚！","notes":[]},{"n":11,"t":"在遠離弓箭響聲打水之處，人必述說耶和華公義的作為，就是他治理以色列公義的作為。那時耶和華的民下到城門。","notes":[]},{"n":12,"t":"底波拉啊，興起！興起！你當興起，興起，唱歌。亞比挪菴的兒子巴拉啊，你當奮興，擄掠你的敵人。","notes":[]},{"n":13,"t":"那時有餘剩的貴冑和百姓一同下來；耶和華降臨，為我攻擊勇士。","notes":[]},{"n":14,"t":"有根本在亞瑪力人的地，從以法蓮下來的；便雅憫在民中跟隨你。有掌權的從瑪吉下來；有持杖檢點民數的從西布倫下來；","notes":[]},{"n":15,"t":"以薩迦的首領與底波拉同來；以薩迦怎樣，巴拉也怎樣。眾人都跟隨巴拉衝下平原；在呂便的溪水旁有心中定大志的。","notes":[]},{"n":16,"t":"你為何坐在羊圈內聽群中吹笛的聲音呢？在呂便的溪水旁有心中設大謀的。","notes":[]},{"n":17,"t":"基列人安居在約旦河外。但人為何等在船上？亞設人在海口靜坐，在港口安居。","notes":[]},{"n":18,"t":"西布倫人是拚命敢死的；拿弗他利人在田野的高處也是如此。","notes":[]},{"n":19,"t":"君王都來爭戰。那時迦南諸王在米吉多水旁的他納爭戰，卻未得擄掠銀錢。","notes":[]},{"n":20,"t":"星宿從天上爭戰，從其軌道攻擊西西拉。","notes":[]},{"n":21,"t":"基順古河把敵人沖沒；我的靈啊，應當努力前行。","notes":[]},{"n":22,"t":"那時壯馬馳驅，踢跳，奔騰。","notes":[]},{"n":23,"t":"耶和華的使者說：應當咒詛米羅斯，大大咒詛其中的居民；因為他們不來幫助耶和華，不來幫助耶和華攻擊勇士。","notes":[]},{"n":24,"t":"願基尼人希百的妻雅億比眾婦人多得福氣，比住帳棚的婦人更蒙福祉。","notes":[]},{"n":25,"t":"西西拉求水，雅億給他奶子，用寶貴的盤子給他奶油。","notes":[]},{"n":26,"t":"雅億左手拿著帳棚的橛子，右手拿著匠人的錘子，擊打西西拉，打傷他的頭，把他的鬢角打破穿通。","notes":[]},{"n":27,"t":"西西拉在她腳前曲身仆倒，在她腳前曲身倒臥；在那裏曲身，就在那裏死亡。","notes":[]},{"n":28,"t":"西西拉的母親從窗戶裏往外觀看，從窗櫺中呼叫說：他的戰車為何耽延不來呢？他的車輪為何行得慢呢？","notes":[]},{"n":29,"t":"聰明的宮女安慰她，她也自言自語地說：","notes":["原文是回答她"]},{"n":30,"t":"他們莫非得財而分？每人得了一兩個女子？西西拉得了彩衣為擄物，得繡花的彩衣為掠物。這彩衣兩面繡花，乃是披在被擄之人頸項上的。","notes":[]},{"n":31,"t":"耶和華啊，願你的仇敵都這樣滅亡！願愛你的人如日頭出現，光輝烈烈！這樣，國中太平四十年。","notes":[]}]},"6":{"heading":"基甸","verses":[{"n":1,"t":"以色列人又行耶和華眼中看為惡的事，耶和華就把他們交在米甸人手裏七年。","notes":[]},{"n":2,"t":"米甸人壓制以色列人；以色列人因為米甸人，就在山中挖穴、挖洞、建造營寨。","notes":[]},{"n":3,"t":"以色列人每逢撒種之後，米甸人、亞瑪力人，和東方人都上來攻打他們，","notes":[]},{"n":4,"t":"對著他們安營，毀壞土產，直到迦薩，沒有給以色列人留下食物，牛、羊、驢也沒有留下；","notes":[]},{"n":5,"t":"因為那些人帶著牲畜帳棚來，像蝗蟲那樣多，人和駱駝無數，都進入國內，毀壞全地。","notes":[]},{"n":6,"t":"以色列人因米甸人的緣故，極其窮乏，就呼求耶和華。","notes":[]},{"n":7,"t":"以色列人因米甸人的緣故，呼求耶和華，","notes":[]},{"n":8,"t":"耶和華就差遣先知到以色列人那裏，對他們說：「耶和華－以色列的神如此說：『我曾領你們從埃及上來，出了為奴之家，","notes":[]},{"n":9,"t":"救你們脫離埃及人的手，並脫離一切欺壓你們之人的手，把他們從你們面前趕出，將他們的地賜給你們』；","notes":[]},{"n":10,"t":"又對你們說：『我是耶和華－你們的神。你們住在亞摩利人的地，不可敬畏他們的神。你們竟不聽從我的話。』」","notes":[]},{"n":11,"t":"耶和華的使者到了俄弗拉，坐在亞比以謝族人約阿施的橡樹下。約阿施的兒子基甸正在酒醡那裏打麥子，為要防備米甸人。","notes":[]},{"n":12,"t":"耶和華的使者向基甸顯現，對他說：「大能的勇士啊，耶和華與你同在！」","notes":[]},{"n":13,"t":"基甸說：「主啊，耶和華若與我們同在，我們何致遭遇這一切事呢？我們的列祖不是向我們說『耶和華領我們從埃及上來』嗎？他那樣奇妙的作為在哪裏呢？現在他卻丟棄我們，將我們交在米甸人手裏。」","notes":[]},{"n":14,"t":"耶和華觀看基甸，說：「你靠著你這能力去從米甸人手裏拯救以色列人，不是我差遣你去的嗎？」","notes":[]},{"n":15,"t":"基甸說：「主啊，我有何能拯救以色列人呢？我家在瑪拿西支派中是至貧窮的。我在我父家是至微小的。」","notes":[]},{"n":16,"t":"耶和華對他說：「我與你同在，你就必擊打米甸人，如擊打一人一樣。」","notes":[]},{"n":17,"t":"基甸說：「我若在你眼前蒙恩，求你給我一個證據，使我知道與我說話的就是主。","notes":[]},{"n":18,"t":"求你不要離開這裏，等我歸回將禮物帶來供在你面前。」主說：「我必等你回來。」","notes":[]},{"n":19,"t":"基甸去預備了一隻山羊羔，用一伊法細麵做了無酵餅，將肉放在筐內，把湯盛在壺中，帶到橡樹下，獻在使者面前。","notes":[]},{"n":20,"t":"神的使者吩咐基甸說：「將肉和無酵餅放在這磐石上，把湯倒出來。」他就這樣行了。","notes":[]},{"n":21,"t":"耶和華的使者伸出手內的杖，杖頭挨了肉和無酵餅，就有火從磐石中出來，燒盡了肉和無酵餅。耶和華的使者也就不見了。","notes":[]},{"n":22,"t":"基甸見他是耶和華的使者，就說：「哀哉！主耶和華啊，我不好了，因為我覿面看見耶和華的使者。」","notes":[]},{"n":23,"t":"耶和華對他說：「你放心，不要懼怕，你必不致死。」","notes":[]},{"n":24,"t":"於是基甸在那裏為耶和華築了一座壇，起名叫「耶和華沙龍」。（這壇在亞比以謝族的俄弗拉直到如今。）","notes":["就是耶和華賜平安的意思"]},{"n":25,"t":"當那夜，耶和華吩咐基甸說：「你取你父親的牛來，就是那七歲的第二隻牛，並拆毀你父親為巴力所築的壇，砍下壇旁的木偶，","notes":["或譯：和"]},{"n":26,"t":"在這磐石上整整齊齊地為耶和華－你的神築一座壇，將第二隻牛獻為燔祭，用你所砍下的木偶作柴。」","notes":["原文是保障"]},{"n":27,"t":"基甸就從他僕人中挑了十個人，照著耶和華吩咐他的行了。他因怕父家和本城的人，不敢在白晝行這事，就在夜間行了。","notes":[]},{"n":28,"t":"城裏的人清早起來，見巴力的壇拆毀，壇旁的木偶砍下，第二隻牛獻在新築的壇上，","notes":[]},{"n":29,"t":"就彼此說：「這事是誰做的呢？」他們訪查之後，就說：「這是約阿施的兒子基甸做的。」","notes":[]},{"n":30,"t":"城裏的人對約阿施說：「將你兒子交出來，好治死他；因為他拆毀了巴力的壇，砍下壇旁的木偶。」","notes":[]},{"n":31,"t":"約阿施回答站著攻擊他的眾人說：「你們是為巴力爭論嗎？你們要救他嗎？誰為他爭論，趁早將誰治死！巴力若果是神，有人拆毀他的壇，讓他為自己爭論吧！」","notes":[]},{"n":32,"t":"所以當日人稱基甸為耶路‧巴力，意思說：「他拆毀巴力的壇，讓巴力與他爭論。」","notes":[]},{"n":33,"t":"那時，米甸人、亞瑪力人，和東方人都聚集過河，在耶斯列平原安營。","notes":[]},{"n":34,"t":"耶和華的靈降在基甸身上，他就吹角；亞比以謝族都聚集跟隨他。","notes":[]},{"n":35,"t":"他打發人走遍瑪拿西地，瑪拿西人也聚集跟隨他；又打發人去見亞設人、西布倫人、拿弗他利人，他們也都出來與他們會合。","notes":[]},{"n":36,"t":"基甸對神說：「你若果照著所說的話，藉我手拯救以色列人，","notes":[]},{"n":37,"t":"我就把一團羊毛放在禾場上：若單是羊毛上有露水，別的地方都是乾的，我就知道你必照著所說的話，藉我手拯救以色列人。」","notes":[]},{"n":38,"t":"次日早晨基甸起來，見果然是這樣；將羊毛擠一擠，從羊毛中擰出滿盆的露水來。","notes":[]},{"n":39,"t":"基甸又對神說：「求你不要向我發怒，我再說這一次：讓我將羊毛再試一次。但願羊毛是乾的，別的地方都有露水。」","notes":[]},{"n":40,"t":"這夜神也如此行：獨羊毛上是乾的，別的地方都有露水。","notes":[]}]},"7":{"heading":"基甸擊敗米甸人","verses":[{"n":1,"t":"耶路‧巴力就是基甸，他和一切跟隨的人早晨起來，在哈律泉旁安營。米甸營在他們北邊的平原，靠近摩利岡。","notes":[]},{"n":2,"t":"耶和華對基甸說：「跟隨你的人過多，我不能將米甸人交在他們手中，免得以色列人向我誇大，說：『是我們自己的手救了我們。』","notes":[]},{"n":3,"t":"現在你要向這些人宣告說：『凡懼怕膽怯的，可以離開基列山回去。』」於是有二萬二千人回去，只剩下一萬。","notes":[]},{"n":4,"t":"耶和華對基甸說：「人還是過多；你要帶他們下到水旁，我好在那裏為你試試他們。我指點誰說：『這人可以同你去』，他就可以同你去；我指點誰說：『這人不可同你去』，他就不可同你去。」","notes":[]},{"n":5,"t":"基甸就帶他們下到水旁。耶和華對基甸說：「凡用舌頭舔水，像狗舔的，要使他單站在一處；凡跪下喝水的，也要使他單站在一處。」","notes":[]},{"n":6,"t":"於是用手捧著舔水的有三百人，其餘的都跪下喝水。","notes":[]},{"n":7,"t":"耶和華對基甸說：「我要用這舔水的三百人拯救你們，將米甸人交在你手中；其餘的人都可以各歸各處去。」","notes":[]},{"n":8,"t":"這三百人就帶著食物和角；其餘的以色列人，基甸都打發他們各歸各的帳棚，只留下這三百人。米甸營在他下邊的平原裏。","notes":[]},{"n":9,"t":"當那夜，耶和華吩咐基甸說：「起來，下到米甸營裏去，因我已將他們交在你手中。","notes":[]},{"n":10,"t":"倘若你怕下去，就帶你的僕人普拉下到那營裏去。","notes":[]},{"n":11,"t":"你必聽見他們所說的，然後你就有膽量下去攻營。」於是基甸帶著僕人普拉下到營旁。","notes":[]},{"n":12,"t":"米甸人、亞瑪力人，和一切東方人都布散在平原，如同蝗蟲那樣多。他們的駱駝無數，多如海邊的沙。","notes":[]},{"n":13,"t":"基甸到了，就聽見一人將夢告訴同伴說：「我做了一夢，夢見一個大麥餅滾入米甸營中，到了帳幕，將帳幕撞倒，帳幕就翻轉傾覆了。」","notes":[]},{"n":14,"t":"那同伴說：「這不是別的，乃是以色列人約阿施的兒子基甸的刀；神已將米甸和全軍都交在他的手中。」","notes":[]},{"n":15,"t":"基甸聽見這夢和夢的講解，就敬拜神，回到以色列營中，說：「起來吧！耶和華已將米甸的軍隊交在你們手中了。」","notes":[]},{"n":16,"t":"於是基甸將三百人分作三隊，把角和空瓶交在各人手裏（瓶內都藏著火把），","notes":[]},{"n":17,"t":"吩咐他們說：「你們要看我行事：我到了營的旁邊怎樣行，你們也要怎樣行。","notes":[]},{"n":18,"t":"我和一切跟隨我的人吹角的時候，你們也要在營的四圍吹角，喊叫說：『耶和華和基甸的刀！』」","notes":[]},{"n":19,"t":"基甸和跟隨他的一百人，在三更之初才換更的時候，來到營旁，就吹角，打破手中的瓶。","notes":[]},{"n":20,"t":"三隊的人就都吹角，打破瓶子，左手拿著火把，右手拿著角，喊叫說：「耶和華和基甸的刀！」","notes":[]},{"n":21,"t":"他們在營的四圍各站各的地方；全營的人都亂竄。三百人吶喊，使他們逃跑。","notes":[]},{"n":22,"t":"三百人就吹角，耶和華使全營的人用刀互相擊殺，逃到西利拉的伯‧哈示他，直逃到靠近他巴的亞伯‧米何拉。","notes":[]},{"n":23,"t":"以色列人就從拿弗他利、亞設，和瑪拿西全地聚集來追趕米甸人。","notes":[]},{"n":24,"t":"基甸打發人走遍以法蓮山地，說：「你們下來攻擊米甸人，爭先把守約旦河的渡口，直到伯‧巴拉。」於是以法蓮的眾人聚集，把守約旦河的渡口，直到伯‧巴拉，","notes":[]},{"n":25,"t":"捉住了米甸人的兩個首領：一名俄立，一名西伊伯；將俄立殺在俄立磐石上，將西伊伯殺在西伊伯酒醡那裏；又追趕米甸人，將俄立和西伊伯的首級帶過約旦河，到基甸那裏。","notes":[]}]},"8":{"heading":"擊敗米甸人","verses":[{"n":1,"t":"以法蓮人對基甸說：「你去與米甸人爭戰，沒有招我們同去，為甚麼這樣待我們呢？」他們就與基甸大大地爭吵。","notes":[]},{"n":2,"t":"基甸對他們說：「我所行的豈能比你們所行的呢？以法蓮拾取剩下的葡萄不強過亞比以謝所摘的葡萄嗎？","notes":[]},{"n":3,"t":"神已將米甸人的兩個首領俄立和西伊伯交在你們手中；我所行的豈能比你們所行的呢？」基甸說了這話，以法蓮人的怒氣就消了。","notes":[]},{"n":4,"t":"基甸和跟隨他的三百人到約旦河過渡，雖然疲乏，還是追趕。","notes":[]},{"n":5,"t":"基甸對疏割人說：「求你們拿餅來給跟隨我的人吃，因為他們疲乏了；我們追趕米甸人的兩個王西巴和撒慕拿。」","notes":[]},{"n":6,"t":"疏割人的首領回答說：「西巴和撒慕拿已經在你手裏，你使我們將餅給你的軍兵嗎？」","notes":[]},{"n":7,"t":"基甸說：「耶和華將西巴和撒慕拿交在我手之後，我就用野地的荊條和枳棘打傷你們。」","notes":[]},{"n":8,"t":"基甸從那裏上到毗努伊勒，對那裏的人也是這樣說；毗努伊勒人也與疏割人回答他的話一樣。","notes":[]},{"n":9,"t":"他向毗努伊勒人說：「我平平安安回來的時候，我必拆毀這樓。」","notes":[]},{"n":10,"t":"那時西巴和撒慕拿，並跟隨他們的軍隊都在加各，約有一萬五千人，就是東方人全軍所剩下的；已經被殺約有十二萬拿刀的。","notes":[]},{"n":11,"t":"基甸就由挪巴和約比哈東邊，從住帳棚人的路上去，殺敗了米甸人的軍兵，因為他們坦然無懼。","notes":[]},{"n":12,"t":"西巴和撒慕拿逃跑；基甸追趕他們，捉住米甸的二王西巴和撒慕拿，驚散全軍。","notes":[]},{"n":13,"t":"約阿施的兒子基甸由希列斯坡從陣上回來，","notes":[]},{"n":14,"t":"捉住疏割的一個少年人，問他：「疏割的首領長老是誰？」他就將首領長老七十七個人的名字寫出來。","notes":[]},{"n":15,"t":"基甸到了疏割，對那裏的人說：「你們從前譏誚我說：『西巴和撒慕拿已經在你手裏，你使我們將餅給跟隨你的疲乏人嗎？』現在西巴和撒慕拿在這裏。」","notes":[]},{"n":16,"t":"於是捉住那城內的長老，用野地的荊條和枳棘責打 疏割人；","notes":["原文是指教"]},{"n":17,"t":"又拆了毗努伊勒的樓，殺了那城裏的人。","notes":[]},{"n":18,"t":"基甸問西巴和撒慕拿說：「你們在他泊山所殺的人是甚麼樣式？」回答說：「他們好像你，各人都有王子的樣式。」","notes":[]},{"n":19,"t":"基甸說：「他們是我同母的弟兄，我指著永生的耶和華起誓，你們從前若存留他們的性命，我如今就不殺你們了。」","notes":[]},{"n":20,"t":"於是對他的長子益帖說：「你起來殺他們。」但益帖因為是童子，害怕，不敢拔刀。","notes":[]},{"n":21,"t":"西巴和撒慕拿說：「你自己起來殺我們吧！因為人如何，力量也是如何。」基甸就起來，殺了西巴和撒慕拿，奪獲他們駱駝項上戴的月牙圈。","notes":[]},{"n":22,"t":"以色列人對基甸說：「你既救我們脫離米甸人的手，願你和你的兒孫管理我們。」","notes":[]},{"n":23,"t":"基甸說：「我不管理你們，我的兒子也不管理你們，惟有耶和華管理你們。」","notes":[]},{"n":24,"t":"基甸又對他們說：「我有一件事求你們：請你們各人將所奪的耳環給我。」（原來仇敵是以實瑪利人，都是戴金耳環的。）","notes":[]},{"n":25,"t":"他們說：「我們情願給你」，就鋪開一件外衣，各人將所奪的耳環丟在其上。","notes":[]},{"n":26,"t":"基甸所要出來的金耳環重一千七百舍客勒金子。此外還有米甸王所戴的月環、耳墜，和所穿的紫色衣服，並駱駝項上的金鍊子。","notes":[]},{"n":27,"t":"基甸以此製造了一個以弗得，設立在本城俄弗拉。後來以色列人拜那以弗得行了邪淫；這就作了基甸和他全家的網羅。","notes":[]},{"n":28,"t":"這樣，米甸人被以色列人制伏了，不敢再抬頭。基甸還在的日子，國中太平四十年。","notes":[]},{"n":29,"t":"約阿施的兒子耶路‧巴力回去，住在自己家裏。","notes":[],"heads":["基甸去世"]},{"n":30,"t":"基甸有七十個親生的兒子，因為他有許多的妻。","notes":[]},{"n":31,"t":"他的妾住在示劍，也給他生了一個兒子。基甸與他起名叫亞比米勒。","notes":[]},{"n":32,"t":"約阿施的兒子基甸，年紀老邁而死，葬在亞比以謝族的俄弗拉，在他父親約阿施的墳墓裏。","notes":[]},{"n":33,"t":"基甸死後，以色列人又去隨從諸巴力行邪淫，以巴力‧比利土為他們的神。","notes":[]},{"n":34,"t":"以色列人不記念耶和華－他們的神，就是拯救他們脫離四圍仇敵之手的，","notes":[]},{"n":35,"t":"也不照著耶路‧巴力，就是基甸向他們所施的恩惠厚待他的家。","notes":[]}]},"9":{"heading":"亞比米勒","verses":[{"n":1,"t":"耶路‧巴力的兒子亞比米勒到了示劍見他的眾母舅，對他們和他外祖全家的人說：","notes":[]},{"n":2,"t":"「請你們問示劍的眾人說，是耶路‧巴力的眾子七十人都管理你們好呢？還是一人管理你們好呢？你們又要記念我是你們的骨肉。」","notes":[]},{"n":3,"t":"他的眾母舅便將這一切話為他說給示劍人聽，示劍人的心就歸向亞比米勒。他們說：「他原是我們的弟兄」；","notes":[]},{"n":4,"t":"就從巴力‧比利土的廟中取了七十舍客勒銀子給亞比米勒；亞比米勒用以雇了些匪徒跟隨他。","notes":[]},{"n":5,"t":"他往俄弗拉到他父親的家，將他弟兄、耶路‧巴力的眾子七十人都殺在一塊磐石上；只剩下耶路‧巴力的小兒子約坦，因為他躲藏了。","notes":[]},{"n":6,"t":"示劍人和米羅人都一同聚集，往示劍橡樹旁的柱子那裏，立亞比米勒為王。","notes":[]},{"n":7,"t":"有人將這事告訴約坦，他就去站在基利心山頂上，向眾人大聲喊叫說：「示劍人哪，你們要聽我的話，神也就聽你們的話。","notes":[]},{"n":8,"t":"有一時，樹木要膏一樹為王，管理他們，就去對橄欖樹說：『請你作我們的王。』","notes":[]},{"n":9,"t":"橄欖樹回答說：『我豈肯止住供奉神和尊重人的油，飄颻在眾樹之上呢？』","notes":[]},{"n":10,"t":"樹木對無花果樹說：『請你來作我們的王。』","notes":[]},{"n":11,"t":"無花果樹回答說：『我豈肯止住所結甜美的果子，飄颻在眾樹之上呢？』","notes":[]},{"n":12,"t":"樹木對葡萄樹說：『請你來作我們的王。』","notes":[]},{"n":13,"t":"葡萄樹回答說：『我豈肯止住使神和人喜樂的新酒，飄颻在眾樹之上呢？』","notes":[]},{"n":14,"t":"眾樹對荊棘說：『請你來作我們的王。』","notes":[]},{"n":15,"t":"荊棘回答說：『你們若誠誠實實地膏我為王，就要投在我的蔭下；不然，願火從荊棘裏出來，燒滅黎巴嫩的香柏樹。』","notes":[]},{"n":16,"t":"「現在你們立亞比米勒為王，若按誠實正直善待耶路‧巴力和他的全家，這就是酬他的勞。","notes":[]},{"n":17,"t":"從前我父冒死為你們爭戰，救了你們脫離米甸人的手。","notes":[]},{"n":18,"t":"你們如今起來攻擊我的父家，將他眾子七十人殺在一塊磐石上，又立他婢女所生的兒子亞比米勒為示劍人的王；他原是你們的弟兄。","notes":[]},{"n":19,"t":"你們如今若按誠實正直待耶路‧巴力和他的家，就可因亞比米勒得歡樂，他也可因你們得歡樂；","notes":[]},{"n":20,"t":"不然，願火從亞比米勒發出，燒滅示劍人和米羅眾人，又願火從示劍人和米羅人中出來，燒滅亞比米勒。」","notes":[]},{"n":21,"t":"約坦因怕他弟兄亞比米勒，就逃跑，來到比珥，住在那裏。","notes":[]},{"n":22,"t":"亞比米勒管理以色列人三年。","notes":[]},{"n":23,"t":"神使惡魔降在亞比米勒和示劍人中間，示劍人就以詭詐待亞比米勒。","notes":[]},{"n":24,"t":"這是要叫耶路‧巴力七十個兒子所受的殘害歸與他們的哥哥亞比米勒，又叫那流他們血的罪歸與幫助他殺弟兄的示劍人。","notes":[]},{"n":25,"t":"示劍人在山頂上設埋伏，等候亞比米勒。凡從他們那裏經過的人，他們就搶奪。有人將這事告訴亞比米勒。","notes":[]},{"n":26,"t":"以別的兒子迦勒和他的弟兄來到示劍，示劍人都信靠他。","notes":[]},{"n":27,"t":"示劍人出城到田間去，摘下葡萄，踹酒，設擺筵宴，進他們神的廟中吃喝，咒詛亞比米勒。","notes":[]},{"n":28,"t":"以別的兒子迦勒說：「亞比米勒是誰？示劍是誰？使我們服事他呢？他不是耶路‧巴力的兒子嗎？他的幫手不是西布勒嗎？你們可以服事示劍的父親哈抹的後裔。我們為何服事亞比米勒呢？","notes":[]},{"n":29,"t":"惟願這民歸我的手下，我就除掉亞比米勒。」迦勒又對亞比米勒說：「增添你的軍兵出來吧。」","notes":[]},{"n":30,"t":"邑宰西布勒聽見以別的兒子迦勒的話，就發怒，","notes":[]},{"n":31,"t":"悄悄地打發人去見亞比米勒，說：「以別的兒子迦勒和他的弟兄到了示劍，煽惑城中的民攻擊你。","notes":[]},{"n":32,"t":"現在你和跟隨你的人今夜起來，在田間埋伏。","notes":[]},{"n":33,"t":"到早晨太陽一出，你就起來闖城。迦勒和跟隨他的人出來攻擊你的時候，你便向他們見機而做。」","notes":[]},{"n":34,"t":"於是，亞比米勒和跟隨他的眾人夜間起來，分作四隊，埋伏等候示劍人。","notes":[]},{"n":35,"t":"以別的兒子迦勒出去，站在城門口。亞比米勒和跟隨他的人從埋伏之處起來。","notes":[]},{"n":36,"t":"迦勒看見那些人，就對西布勒說：「看哪，有人從山頂上下來了。」西布勒說：「你看見山的影子，以為是人。」","notes":[]},{"n":37,"t":"迦勒又說：「看哪，有人從高處下來，又有一隊從米惡尼尼橡樹的路上而來。」","notes":[]},{"n":38,"t":"西布勒對他說：「你曾說，亞比米勒是誰，叫我們服事他？你所誇的口在哪裏呢？這不是你所藐視的民嗎？你現在出去，與他們交戰吧！」","notes":[]},{"n":39,"t":"於是迦勒率領示劍人出去，與亞比米勒交戰。","notes":[]},{"n":40,"t":"亞比米勒追趕迦勒；迦勒在他面前逃跑，有許多受傷仆倒的，直到城門。","notes":[]},{"n":41,"t":"亞比米勒住在亞魯瑪。西布勒趕出迦勒和他弟兄，不准他們住在示劍。","notes":[]},{"n":42,"t":"次日，民出到田間，有人告訴亞比米勒；","notes":[]},{"n":43,"t":"他就把他的人分作三隊，埋伏在田間，看見示劍人從城裏出來，就起來擊殺他們。","notes":[]},{"n":44,"t":"亞比米勒和跟隨他的一隊向前闖去，站在城門口；那兩隊直闖到田間，擊殺了眾人。","notes":[]},{"n":45,"t":"亞比米勒整天攻打城，將城奪取，殺了其中的居民，將城拆毀，撒上了鹽。","notes":[]},{"n":46,"t":"示劍樓的人聽見了，就躲入巴力‧比利土廟的衛所。","notes":[]},{"n":47,"t":"有人告訴亞比米勒說：「示劍樓的人都聚在一處。」","notes":[]},{"n":48,"t":"亞比米勒和跟隨他的人就都上撒們山。亞比米勒手拿斧子，砍下一根樹枝，扛在肩上，對跟隨他的人說：「你們看我所行的，也當趕緊照樣行。」","notes":[]},{"n":49,"t":"眾人就各砍一枝，跟隨亞比米勒，把樹枝堆在衛所的四圍，放火燒了衛所，以致示劍樓的人都死了，男女約有一千。","notes":[]},{"n":50,"t":"亞比米勒到提備斯，向提備斯安營，就攻取了那城。","notes":[]},{"n":51,"t":"城中有一座堅固的樓；城裏的眾人，無論男女，都逃進樓去，關上門，上了樓頂。","notes":[]},{"n":52,"t":"亞比米勒到了樓前攻打，挨近樓門，要用火焚燒。","notes":[]},{"n":53,"t":"有一個婦人把一塊上磨石拋在亞比米勒的頭上，打破了他的腦骨。","notes":[]},{"n":54,"t":"他就急忙喊叫拿他兵器的少年人，對他說：「拔出你的刀來，殺了我吧！免得人議論我說，他為一個婦人所殺。」於是少年人把他刺透，他就死了。","notes":[]},{"n":55,"t":"以色列人見亞比米勒死了，便各回自己的地方去了。","notes":[]},{"n":56,"t":"這樣，神報應亞比米勒向他父親所行的惡，就是殺了弟兄七十個人的惡。","notes":[]},{"n":57,"t":"示劍人的一切惡，神也都報應在他們頭上；耶路‧巴力的兒子約坦的咒詛歸到他們身上了。","notes":[]}]},"10":{"heading":"陀拉","verses":[{"n":1,"t":"亞比米勒以後，有以薩迦人朵多的孫子、普瓦的兒子陀拉興起，拯救以色列人。他住在以法蓮山地的沙密。","notes":[]},{"n":2,"t":"陀拉作以色列的士師二十三年，就死了，葬在沙密。","notes":[]},{"n":3,"t":"在他以後有基列人睚珥興起，作以色列的士師二十二年。","notes":[],"heads":["睚珥"]},{"n":4,"t":"他有三十個兒子，騎著三十匹驢駒。他們有三十座城邑，叫作哈倭特‧睚珥，直到如今，都是在基列地。","notes":[]},{"n":5,"t":"睚珥死了，就葬在加們。","notes":[]},{"n":6,"t":"以色列人又行耶和華眼中看為惡的事，去事奉諸巴力和亞斯她錄，並亞蘭的神、西頓的神、摩押的神、亞捫人的神、非利士人的神，離棄耶和華，不事奉他。","notes":[],"heads":["耶弗他"]},{"n":7,"t":"耶和華的怒氣向以色列人發作，就把他們交在非利士人和亞捫人的手中。","notes":[]},{"n":8,"t":"從那年起，他們擾害欺壓約旦河那邊、住亞摩利人之基列地的以色列人，共有十八年。","notes":[]},{"n":9,"t":"亞捫人又渡過約旦河去攻打猶大和便雅憫，並以法蓮族。以色列人就甚覺窘迫。","notes":[]},{"n":10,"t":"以色列人哀求耶和華說：「我們得罪了你；因為離棄了我們神，去事奉諸巴力。」","notes":[]},{"n":11,"t":"耶和華對以色列人說：「我豈沒有救過你們脫離埃及人、亞摩利人、亞捫人，和非利士人嗎？","notes":[]},{"n":12,"t":"西頓人、亞瑪力人、馬雲人也都欺壓你們；你們哀求我，我也拯救你們脫離他們的手。","notes":[]},{"n":13,"t":"你們竟離棄我，事奉別神！所以我不再救你們了。","notes":[]},{"n":14,"t":"你們去哀求所選擇的神；你們遭遇急難的時候，讓他救你們吧！」","notes":[]},{"n":15,"t":"以色列人對耶和華說：「我們犯罪了，任憑你隨意待我們吧！只求你今日拯救我們。」","notes":[]},{"n":16,"t":"以色列人就除掉他們中間的外邦神，事奉耶和華。耶和華因以色列人受的苦難，就心中擔憂。","notes":[]},{"n":17,"t":"當時亞捫人聚集，安營在基列。以色列人也聚集，安營在米斯巴。","notes":[]},{"n":18,"t":"基列的民和眾首領彼此商議說：「誰能先去攻打亞捫人，誰必作基列一切居民的領袖。」","notes":[]}]},"11":{"heading":"耶弗他的女兒","verses":[{"n":1,"t":"基列人耶弗他是個大能的勇士，是妓女的兒子。耶弗他是基列所生的。","notes":[]},{"n":2,"t":"基列的妻也生了幾個兒子：他妻所生的兒子長大了，就趕逐耶弗他，說：「你不可在我們父家承受產業，因為你是妓女的兒子。」","notes":[]},{"n":3,"t":"耶弗他就逃避他的弟兄，去住在陀伯地，有些匪徒到他那裏聚集，與他一同出入。","notes":[]},{"n":4,"t":"過了些日子，亞捫人攻打以色列。","notes":[]},{"n":5,"t":"亞捫人攻打以色列的時候，基列的長老到陀伯地去，要叫耶弗他回來；","notes":[]},{"n":6,"t":"對耶弗他說：「請你來作我們的元帥，我們好與亞捫人爭戰。」","notes":[]},{"n":7,"t":"耶弗他回答基列的長老說：「從前你們不是恨我、趕逐我出離父家嗎？現在你們遭遇急難為何到我這裏來呢？」","notes":[]},{"n":8,"t":"基列的長老回答耶弗他說：「現在我們到你這裏來，是要你同我們去，與亞捫人爭戰；你可以作基列一切居民的領袖。」","notes":[]},{"n":9,"t":"耶弗他對基列的長老說：「你們叫我回去，與亞捫人爭戰，耶和華把他交給我，我可以作你們的領袖嗎？」","notes":[]},{"n":10,"t":"基列的長老回答耶弗他說：「有耶和華在你我中間作見證，我們必定照你的話行。」","notes":[]},{"n":11,"t":"於是耶弗他同基列的長老回去，百姓就立耶弗他作領袖、作元帥。耶弗他在米斯巴將自己的一切話陳明在耶和華面前。","notes":[]},{"n":12,"t":"耶弗他打發使者去見亞捫人的王，說：「你與我有甚麼相干，竟來到我國中攻打我呢？」","notes":[]},{"n":13,"t":"亞捫人的王回答耶弗他的使者說：「因為以色列人從埃及上來的時候佔據我的地，從亞嫩河到雅博河，直到約旦河。現在你要好好地將這地歸還吧！」","notes":[]},{"n":14,"t":"耶弗他又打發使者去見亞捫人的王，","notes":[]},{"n":15,"t":"對他說：「耶弗他如此說，以色列人並沒有佔據摩押地和亞捫人的地。","notes":[]},{"n":16,"t":"以色列人從埃及上來乃是經過曠野到紅海，來到加低斯，","notes":[]},{"n":17,"t":"就打發使者去見以東王，說：『求你容我從你的地經過。』以東王卻不應允。又照樣打發使者去見摩押王，他也不允准。以色列人就住在加低斯。","notes":[]},{"n":18,"t":"他們又經過曠野，繞著以東和摩押地，從摩押地的東邊過來，在亞嫩河邊安營，並沒有入摩押的境內，因為亞嫩河是摩押的邊界。","notes":[]},{"n":19,"t":"以色列人打發使者去見亞摩利王西宏，就是希實本的王，對他說：『求你容我們從你的地經過，往我們自己的地方去。』","notes":[]},{"n":20,"t":"西宏卻不信服以色列人，不容他們經過他的境界，乃招聚他的眾民在雅雜安營，與以色列人爭戰。","notes":[]},{"n":21,"t":"耶和華－以色列的神將西宏和他的眾民都交在以色列人手中，以色列人就擊殺他們，得了亞摩利人的全地：","notes":[]},{"n":22,"t":"從亞嫩河到雅博河，從曠野直到約旦河。","notes":[]},{"n":23,"t":"耶和華－以色列的神在他百姓以色列面前趕出亞摩利人，你竟要得他們的地嗎？","notes":[]},{"n":24,"t":"你的神基抹所賜你的地你不是得為業嗎？耶和華－我們的神在我們面前所趕出的人，我們就得他的地。","notes":[]},{"n":25,"t":"難道你比摩押王西撥的兒子巴勒還強嗎？他曾與以色列人爭競，或是與他們爭戰嗎？","notes":[]},{"n":26,"t":"以色列人住希實本和屬希實本的鄉村，亞羅珥和屬亞羅珥的鄉村，並沿亞嫩河的一切城邑，已經有三百年了；在這三百年之內，你們為甚麼沒有取回這些地方呢？","notes":[]},{"n":27,"t":"原來我沒有得罪你，你卻攻打我，惡待我。願審判人的耶和華今日在以色列人和亞捫人中間判斷是非。」","notes":[]},{"n":28,"t":"但亞捫人的王不肯聽耶弗他打發人說的話。","notes":[]},{"n":29,"t":"耶和華的靈降在耶弗他身上，他就經過基列和瑪拿西，來到基列的米斯巴，又從米斯巴來到亞捫人那裏。","notes":[]},{"n":30,"t":"耶弗他就向耶和華許願，說：「你若將亞捫人交在我手中，","notes":[]},{"n":31,"t":"我從亞捫人那裏平平安安回來的時候，無論甚麼人，先從我家門出來迎接我，就必歸你，我也必將他獻上為燔祭。」","notes":[]},{"n":32,"t":"於是耶弗他往亞捫人那裏去，與他們爭戰；耶和華將他們交在他手中，","notes":[]},{"n":33,"t":"他就大大殺敗他們，從亞羅珥到米匿，直到亞備勒‧基拉明，攻取了二十座城。這樣亞捫人就被以色列人制伏了。","notes":[]},{"n":34,"t":"耶弗他回米斯巴到了自己的家，不料，他女兒拿著鼓跳舞出來迎接他，是他獨生的，此外無兒無女。","notes":[]},{"n":35,"t":"耶弗他看見她，就撕裂衣服，說：「哀哉！我的女兒啊，你使我甚是愁苦，叫我作難了；因為我已經向耶和華開口許願，不能挽回。」","notes":[]},{"n":36,"t":"他女兒回答說：「父啊，你既向耶和華開口，就當照你口中所說的向我行，因耶和華已經在仇敵亞捫人身上為你報仇」；","notes":[]},{"n":37,"t":"又對父親說：「有一件事求你允准：容我去兩個月，與同伴在山上，好哀哭我終為處女。」","notes":[]},{"n":38,"t":"耶弗他說：「你去吧！」就容她去兩個月。她便和同伴去了，在山上為她終為處女哀哭。","notes":[]},{"n":39,"t":"兩月已滿，她回到父親那裏，父親就照所許的願向她行了。女兒終身沒有親近男子。","notes":[]},{"n":40,"t":"此後以色列中有個規矩，每年以色列的女子去為基列人耶弗他的女兒哀哭四天。","notes":[]}]},"12":{"heading":"耶弗他和以法蓮人","verses":[{"n":1,"t":"以法蓮人聚集，到了北方，對耶弗他說：「你去與亞捫人爭戰，為甚麼沒有招我們同去呢？我們必用火燒你和你的房屋。」","notes":[]},{"n":2,"t":"耶弗他對他們說：「我和我的民與亞捫人大大爭戰；我招你們來，你們竟沒有來救我脫離他們的手。","notes":[]},{"n":3,"t":"我見你們不來救我，我就拚命前去攻擊亞捫人，耶和華將他們交在我手中。你們今日為甚麼上我這裏來攻打我呢？」","notes":[]},{"n":4,"t":"於是耶弗他招聚基列人，與以法蓮人爭戰。基列人擊殺以法蓮人，是因他們說：「你們基列人在以法蓮、瑪拿西中間，不過是以法蓮逃亡的人。」","notes":[]},{"n":5,"t":"基列人把守約旦河的渡口，不容以法蓮人過去。以法蓮逃走的人若說：「容我過去。」基列人就問他說：「你是以法蓮人不是？」他若說：「不是」，","notes":[]},{"n":6,"t":"就對他說：「你說『示播列』。」以法蓮人因為咬不真字音，便說「西播列」。基列人就將他拿住，殺在約旦河的渡口。那時以法蓮人被殺的有四萬二千人。","notes":[]},{"n":7,"t":"耶弗他作以色列的士師六年。基列人耶弗他死了，葬在基列的一座城裏。","notes":[]},{"n":8,"t":"耶弗他以後，有伯利恆人以比讚作以色列的士師。","notes":[],"heads":["以比讚、以倫、押頓"]},{"n":9,"t":"他有三十個兒子，三十個女兒；女兒都嫁出去了。他給眾子從外鄉娶了三十個媳婦。他作以色列的士師七年。","notes":[]},{"n":10,"t":"以比讚死了，葬在伯利恆。","notes":[]},{"n":11,"t":"以比讚之後，有西布倫人以倫，作以色列的士師十年。","notes":[]},{"n":12,"t":"西布倫人以倫死了，葬在西布倫地的亞雅崙。","notes":[]},{"n":13,"t":"以倫之後，有比拉頓人希列的兒子押頓作以色列的士師。","notes":[]},{"n":14,"t":"他有四十個兒子，三十個孫子，騎著七十匹驢駒。押頓作以色列的士師八年。","notes":[]},{"n":15,"t":"比拉頓人希列的兒子押頓死了，葬在以法蓮地的比拉頓，在亞瑪力人的山地。","notes":[]}]},"13":{"heading":"參孫出生","verses":[{"n":1,"t":"以色列人又行耶和華眼中看為惡的事，耶和華將他們交在非利士人手中四十年。","notes":[]},{"n":2,"t":"那時，有一個瑣拉人，是屬但族的，名叫瑪挪亞。他的妻不懷孕，不生育。","notes":[]},{"n":3,"t":"耶和華的使者向那婦人顯現，對她說：「向來你不懷孕，不生育，如今你必懷孕生一個兒子。","notes":[]},{"n":4,"t":"所以你當謹慎，清酒濃酒都不可喝，一切不潔之物也不可吃。","notes":[]},{"n":5,"t":"你必懷孕生一個兒子，不可用剃頭刀剃他的頭，因為這孩子一出胎就歸神作拿細耳人。他必起首拯救以色列人脫離非利士人的手。」","notes":[]},{"n":6,"t":"婦人就回去對丈夫說：「有一個神人到我面前來，他的相貌如神使者的相貌，甚是可畏。我沒有問他從哪裏來，他也沒有將他的名告訴我，","notes":[]},{"n":7,"t":"卻對我說：『你要懷孕生一個兒子，所以清酒濃酒都不可喝，一切不潔之物也不可吃；因為這孩子從出胎一直到死，必歸神作拿細耳人。』」","notes":[]},{"n":8,"t":"瑪挪亞就祈求耶和華說：「主啊，求你再差遣那神人到我們這裏來，好指教我們怎樣待這將要生的孩子。」","notes":[]},{"n":9,"t":"神應允瑪挪亞的話；婦人正坐在田間的時候，神的使者又到她那裏，她丈夫瑪挪亞卻沒有同她在一處。","notes":[]},{"n":10,"t":"婦人急忙跑去告訴丈夫說：「那日到我面前來的人，又向我顯現。」","notes":[]},{"n":11,"t":"瑪挪亞起來跟隨他的妻來到那人面前，對他說：「與這婦人說話的就是你嗎？」他說：「是我。」","notes":[]},{"n":12,"t":"瑪挪亞說：「願你的話應驗！我們當怎樣待這孩子，他後來當怎樣呢？」","notes":[]},{"n":13,"t":"耶和華的使者對瑪挪亞說：「我告訴婦人的一切事，她都當謹慎。","notes":[]},{"n":14,"t":"葡萄樹所結的都不可吃，清酒濃酒都不可喝，一切不潔之物也不可吃。凡我所吩咐的，她都當遵守。」","notes":[]},{"n":15,"t":"瑪挪亞對耶和華的使者說：「求你容我們款留你，好為你預備一隻山羊羔。」","notes":[]},{"n":16,"t":"耶和華的使者對瑪挪亞說：「你雖然款留我，我卻不吃你的食物，你若預備燔祭就當獻與耶和華。」原來瑪挪亞不知道他是耶和華的使者。","notes":[]},{"n":17,"t":"瑪挪亞對耶和華的使者說：「請將你的名告訴我，到你話應驗的時候，我們好尊敬你。」","notes":[]},{"n":18,"t":"耶和華的使者對他說：「你何必問我的名，我名是奇妙的。」","notes":[]},{"n":19,"t":"瑪挪亞將一隻山羊羔和素祭在磐石上獻與耶和華，使者行奇妙的事；瑪挪亞和他的妻觀看，","notes":[]},{"n":20,"t":"見火焰從壇上往上升，耶和華的使者在壇上的火焰中也升上去了。瑪挪亞和他的妻看見，就俯伏於地。","notes":[]},{"n":21,"t":"耶和華的使者不再向瑪挪亞和他的妻顯現，瑪挪亞才知道他是耶和華的使者。","notes":[]},{"n":22,"t":"瑪挪亞對他的妻說：「我們必要死，因為看見了神。」","notes":[]},{"n":23,"t":"他的妻卻對他說：「耶和華若要殺我們，必不從我們手裏收納燔祭和素祭，並不將這一切事指示我們，今日也不將這些話告訴我們。」","notes":[]},{"n":24,"t":"後來婦人生了一個兒子，給他起名叫參孫。孩子長大，耶和華賜福與他。","notes":[]},{"n":25,"t":"在瑪哈尼‧但，就是瑣拉和以實陶中間，耶和華的靈才感動他。","notes":[]}]},"14":{"heading":"參孫和亭拿的女子","verses":[{"n":1,"t":"參孫下到亭拿，在那裏看見一個女子，是非利士人的女兒。","notes":[]},{"n":2,"t":"參孫上來稟告他父母說：「我在亭拿看見一個女子，是非利士人的女兒，願你們給我娶來為妻。」","notes":[]},{"n":3,"t":"他父母說：「在你弟兄的女兒中，或在本國的民中，豈沒有一個女子，何致你去在未受割禮的非利士人中娶妻呢？」參孫對他父親說：「願你給我娶那女子，因我喜悅她。」","notes":[]},{"n":4,"t":"他的父母卻不知道這事是出於耶和華，因為他找機會攻擊非利士人。那時，非利士人轄制以色列人。","notes":[]},{"n":5,"t":"參孫跟他父母下亭拿去，到了亭拿的葡萄園，見有一隻少壯獅子向他吼叫。","notes":[]},{"n":6,"t":"耶和華的靈大大感動參孫，他雖然手無器械，卻將獅子撕裂，如同撕裂山羊羔一樣。他行這事並沒有告訴父母。","notes":[]},{"n":7,"t":"參孫下去與女子說話，就喜悅她；","notes":[]},{"n":8,"t":"過了些日子，再下去要娶那女子，轉向道旁要看死獅，見有一群蜂子和蜜在死獅之內，","notes":[]},{"n":9,"t":"就用手取蜜，且吃且走；到了父母那裏，給他父母，他們也吃了；只是沒有告訴這蜜是從死獅之內取來的。","notes":[]},{"n":10,"t":"他父親下去見女子。參孫在那裏設擺筵宴，因為向來少年人都有這個規矩。","notes":[]},{"n":11,"t":"眾人看見參孫，就請了三十個人陪伴他。","notes":[]},{"n":12,"t":"參孫對他們說：「我給你們出一個謎語，你們在七日筵宴之內，若能猜出意思告訴我，我就給你們三十件裏衣，三十套衣裳；","notes":[]},{"n":13,"t":"你們若不能猜出意思告訴我，你們就給我三十件裏衣，三十套衣裳。」他們說：「請將謎語說給我們聽。」","notes":[]},{"n":14,"t":"參孫對他們說：吃的從吃者出來；甜的從強者出來。他們三日不能猜出謎語的意思。","notes":[]},{"n":15,"t":"到第七天，他們對參孫的妻說：「你誆哄你丈夫，探出謎語的意思告訴我們，免得我們用火燒你和你父家。你們請了我們來，是要奪我們所有的嗎？」","notes":[]},{"n":16,"t":"參孫的妻在丈夫面前啼哭說：「你是恨我，不是愛我，你給我本國的人出謎語，卻沒有將意思告訴我。」參孫回答說：「連我父母我都沒有告訴，豈可告訴你呢？」","notes":[]},{"n":17,"t":"七日筵宴之內，她在丈夫面前啼哭，到第七天逼著他，他才將謎語的意思告訴他妻，他妻就告訴本國的人。","notes":[]},{"n":18,"t":"到第七天，日頭未落以前，那城裏的人對參孫說：有甚麼比蜜還甜呢？有甚麼比獅子還強呢？參孫對他們說：你們若非用我的母牛犢耕地，就猜不出我謎語的意思來。","notes":[]},{"n":19,"t":"耶和華的靈大大感動參孫，他就下到亞實基倫，擊殺了三十個人，奪了他們的衣裳，將衣裳給了猜出謎語的人。參孫發怒，就上父家去了。","notes":[]},{"n":20,"t":"參孫的妻便歸了參孫的陪伴，就是作過他朋友的。","notes":[]}]},"15":{"heading":"參孫擊敗非利士人","verses":[{"n":1,"t":"過了些日子，到割麥子的時候，參孫帶著一隻山羊羔去看他的妻，說：「我要進內室見我的妻。」他岳父不容他進去，","notes":[]},{"n":2,"t":"說：「我估定你是極其恨她，因此我將她給了你的陪伴。她的妹子不是比她還美麗嗎？你可以娶來代替她吧！」","notes":[]},{"n":3,"t":"參孫說：「這回我加害於非利士人不算有罪。」","notes":[]},{"n":4,"t":"於是參孫去捉了三百隻狐狸，將狐狸尾巴一對一對地捆上，將火把捆在兩條尾巴中間，","notes":["或譯：野狗"]},{"n":5,"t":"點著火把，就放狐狸進入非利士人站著的禾稼，將堆集的禾捆和未割的禾稼，並橄欖園盡都燒了。","notes":[]},{"n":6,"t":"非利士人說：「這事是誰做的呢？」有人說：「是亭拿人的女婿參孫，因為他岳父將他的妻給了他的陪伴。」於是非利士人上去，用火燒了婦人和她的父親。","notes":[]},{"n":7,"t":"參孫對非利士人說：「你們既然這樣行，我必向你們報仇才肯罷休。」","notes":[]},{"n":8,"t":"參孫就大大擊殺他們，連腿帶腰都砍斷了。他便下去，住在以坦磐的穴內。","notes":[]},{"n":9,"t":"非利士人上去安營在猶大，布散在利希。","notes":[]},{"n":10,"t":"猶大人說：「你們為何上來攻擊我們呢？」他們說：「我們上來是要捆綁參孫；他向我們怎樣行，我們也要向他怎樣行。」","notes":[]},{"n":11,"t":"於是有三千猶大人下到以坦磐的穴內，對參孫說：「非利士人轄制我們，你不知道嗎？你向我們行的是甚麼事呢？」他回答說：「他們向我怎樣行，我也要向他們怎樣行。」","notes":[]},{"n":12,"t":"猶大人對他說：「我們下來是要捆綁你，將你交在非利士人手中。」參孫說：「你們要向我起誓，應承你們自己不害死我。」","notes":[]},{"n":13,"t":"他們說：「我們斷不殺你，只要將你捆綁交在非利士人手中。」於是用兩條新繩捆綁參孫，將他從以坦磐帶上去。","notes":[]},{"n":14,"t":"參孫到了利希，非利士人都迎著喧嚷。耶和華的靈大大感動參孫，他臂上的繩就像火燒的麻一樣，他的綁繩都從他手上脫落下來。","notes":[]},{"n":15,"t":"他見一塊未乾的驢腮骨，就伸手拾起來，用以擊殺一千人。","notes":[]},{"n":16,"t":"參孫說：我用驢腮骨殺人成堆，用驢腮骨殺了一千人。","notes":[]},{"n":17,"t":"說完這話，就把那腮骨從手裏拋出去了。那地便叫拉末‧利希。","notes":[]},{"n":18,"t":"參孫甚覺口渴，就求告耶和華說：「你既藉僕人的手施行這麼大的拯救，豈可任我渴死、落在未受割禮的人手中呢？」","notes":[]},{"n":19,"t":"神就使利希的窪處裂開，有水從其中湧出來。參孫喝了，精神復原；因此那泉名叫隱‧哈歌利，那泉直到今日還在利希。","notes":[]},{"n":20,"t":"當非利士人轄制以色列人的時候，參孫作以色列的士師二十年。","notes":[]}]},"16":{"heading":"參孫在迦薩","verses":[{"n":1,"t":"參孫到了迦薩，在那裏看見一個妓女，就與她親近。","notes":[]},{"n":2,"t":"有人告訴迦薩人說：「參孫到這裏來了！」他們就把他團團圍住，終夜在城門悄悄埋伏，說：「等到天亮我們便殺他。」","notes":[]},{"n":3,"t":"參孫睡到半夜，起來，將城門的門扇、門框、門閂，一齊拆下來，扛在肩上，扛到希伯崙前的山頂上。","notes":[]},{"n":4,"t":"後來，參孫在梭烈谷喜愛一個婦人，名叫大利拉。","notes":[],"heads":["參孫和大利拉"]},{"n":5,"t":"非利士人的首領上去見那婦人，對她說：「求你誆哄參孫，探探他因何有這麼大的力氣，我們用何法能勝他，捆綁剋制他。我們就每人給你一千一百舍客勒銀子。」","notes":[]},{"n":6,"t":"大利拉對參孫說：「求你告訴我，你因何有這麼大的力氣，當用何法捆綁剋制你。」","notes":[]},{"n":7,"t":"參孫回答說：「人若用七條未乾的青繩子捆綁我，我就軟弱像別人一樣。」","notes":[]},{"n":8,"t":"於是非利士人的首領拿了七條未乾的青繩子來，交給婦人，她就用繩子捆綁參孫。","notes":[]},{"n":9,"t":"有人預先埋伏在婦人的內室裏。婦人說：「參孫哪，非利士人拿你來了！」參孫就掙斷繩子，如掙斷經火的麻線一般。這樣，他力氣的根由人還是不知道。","notes":[]},{"n":10,"t":"大利拉對參孫說：「你欺哄我，向我說謊言。現在求你告訴我當用何法捆綁你。」","notes":[]},{"n":11,"t":"參孫回答說：「人若用沒有使過的新繩捆綁我，我就軟弱像別人一樣。」","notes":[]},{"n":12,"t":"大利拉就用新繩捆綁他，對他說：「參孫哪，非利士人拿你來了！」有人預先埋伏在內室裏。參孫將臂上的繩掙斷了，如掙斷一條線一樣。","notes":[]},{"n":13,"t":"大利拉對參孫說：「你到如今還是欺哄我，向我說謊言。求你告訴我，當用何法捆綁你。」參孫回答說：「你若將我頭上的七條髮綹，與緯線同織就可以了。」","notes":[]},{"n":14,"t":"於是大利拉將他的髮綹與緯線同織，用橛子釘住，對他說：「參孫哪，非利士人拿你來了！」參孫從睡中醒來，將機上的橛子和緯線一齊都拔出來了。","notes":[]},{"n":15,"t":"大利拉對參孫說：「你既不與我同心，怎麼說你愛我呢？你這三次欺哄我，沒有告訴我，你因何有這麼大的力氣。」","notes":[]},{"n":16,"t":"大利拉天天用話催逼他，甚至他心裏煩悶要死。","notes":[]},{"n":17,"t":"參孫就把心中所藏的都告訴了她，對她說：「向來人沒有用剃頭刀剃我的頭，因為我自出母胎就歸神作拿細耳人；若剃了我的頭髮，我的力氣就離開我，我便軟弱像別人一樣。」","notes":[]},{"n":18,"t":"大利拉見他把心中所藏的都告訴了她，就打發人到非利士人的首領那裏，對他們說：「他已經把心中所藏的都告訴了我，請你們再上來一次。」於是非利士人的首領手裏拿著銀子，上到婦人那裏。","notes":[]},{"n":19,"t":"大利拉使參孫枕著她的膝睡覺，叫了一個人來剃除他頭上的七條髮綹。於是大利拉剋制他，他的力氣就離開他了。","notes":[]},{"n":20,"t":"大利拉說：「參孫哪，非利士人拿你來了！」參孫從睡中醒來，心裏說：「我要像前幾次出去活動身體」；他卻不知道耶和華已經離開他了。","notes":[]},{"n":21,"t":"非利士人將他拿住，剜了他的眼睛，帶他下到迦薩，用銅鍊拘索他；他就在監裏推磨。","notes":[]},{"n":22,"t":"然而他的頭髮被剃之後，又漸漸長起來了。","notes":[]},{"n":23,"t":"非利士人的首領聚集，要給他們的神大袞獻大祭，並且歡樂，因為他們說：「我們的神將我們的仇敵參孫交在我們手中了。」","notes":[],"heads":["參孫的死"]},{"n":24,"t":"眾人看見參孫，就讚美他們的神說：「我們的神將毀壞我們地、殺害我們許多人的仇敵交在我們手中了。」","notes":[]},{"n":25,"t":"他們正宴樂的時候，就說：「叫參孫來，在我們面前戲耍戲耍。」於是將參孫從監裏提出來，他就在眾人面前戲耍。他們使他站在兩柱中間。","notes":[]},{"n":26,"t":"參孫向拉他手的童子說：「求你讓我摸著托房的柱子，我要靠一靠。」","notes":[]},{"n":27,"t":"那時房內充滿男女，非利士人的眾首領也都在那裏。房的平頂上約有三千男女觀看參孫戲耍。","notes":[]},{"n":28,"t":"參孫求告耶和華說：「主耶和華啊，求你眷念我。神啊，求你賜我這一次的力量，使我在非利士人身上報那剜我雙眼的仇。」","notes":[]},{"n":29,"t":"參孫就抱住托房的那兩根柱子：左手抱一根，右手抱一根，","notes":[]},{"n":30,"t":"說：「我情願與非利士人同死！」就盡力屈身，房子倒塌，壓住首領和房內的眾人。這樣，參孫死時所殺的人比活著所殺的還多。","notes":[]},{"n":31,"t":"參孫的弟兄和他父的全家都下去取他的屍首，抬上來葬在瑣拉和以實陶中間，在他父瑪挪亞的墳墓裏。參孫作以色列的士師二十年。","notes":[]}]},"17":{"heading":"米迦的偶像","verses":[{"n":1,"t":"以法蓮山地有一個人名叫米迦。","notes":[]},{"n":2,"t":"他對母親說：「你那一千一百舍客勒銀子被人拿去，你因此咒詛，並且告訴了我。看哪，這銀子在我這裏，是我拿去了。」他母親說：「我兒啊，願耶和華賜福與你！」","notes":[]},{"n":3,"t":"米迦就把這一千一百舍客勒銀子還他母親。他母親說：「我分出這銀子來為你獻給耶和華，好雕刻一個像，鑄成一個像。現在我還是交給你。」","notes":[]},{"n":4,"t":"米迦將銀子還他母親，他母親將二百舍客勒銀子交給銀匠，雕刻一個像，鑄成一個像，安置在米迦的屋內。","notes":[]},{"n":5,"t":"這米迦有了神堂，又製造以弗得和家中的神像，分派他一個兒子作祭司。","notes":[]},{"n":6,"t":"那時以色列中沒有王，各人任意而行。","notes":[]},{"n":7,"t":"猶大的伯利恆有一個少年人，是猶大族的利未人，他在那裏寄居。","notes":[]},{"n":8,"t":"這人離開猶大的伯利恆城，要找一個可住的地方。行路的時候，到了以法蓮山地，走到米迦的家。","notes":[]},{"n":9,"t":"米迦問他說：「你從哪裏來？」他回答說：「從猶大的伯利恆來。我是利未人，要找一個可住的地方。」","notes":[]},{"n":10,"t":"米迦說：「你可以住在我這裏，我以你為父、為祭司。我每年給你十舍客勒銀子，一套衣服和度日的食物。」利未人就進了他的家。","notes":[]},{"n":11,"t":"利未人情願與那人同住；那人看這少年人如自己的兒子一樣。","notes":[]},{"n":12,"t":"米迦分派這少年的利未人作祭司，他就住在米迦的家裏。","notes":[]},{"n":13,"t":"米迦說：「現在我知道耶和華必賜福與我，因我有一個利未人作祭司。」","notes":[]}]},"18":{"heading":"米迦和但支派","verses":[{"n":1,"t":"那時，以色列中沒有王。但支派的人仍是尋地居住；因為到那日子，他們還沒有在以色列支派中得地為業。","notes":[]},{"n":2,"t":"但人從瑣拉和以實陶打發本族中的五個勇士，去仔細窺探那地，吩咐他們說：「你們去窺探那地。」他們來到以法蓮山地，進了米迦的住宅，就在那裏住宿。","notes":[]},{"n":3,"t":"他們臨近米迦的住宅，聽出那少年利未人的口音來，就進去問他說：「誰領你到這裏來？你在這裏做甚麼？你在這裏得甚麼？」","notes":[]},{"n":4,"t":"他回答說：「米迦待我如此如此，請我作祭司。」","notes":[]},{"n":5,"t":"他們對他說：「請你求問神，使我們知道所行的道路通達不通達。」","notes":[]},{"n":6,"t":"祭司對他們說：「你們可以平平安安地去，你們所行的道路是在耶和華面前的。」","notes":[]},{"n":7,"t":"五人就走了，來到拉億，見那裏的民安居無慮，如同西頓人安居一樣。在那地沒有人掌權擾亂他們；他們離西頓人也遠，與別人沒有來往。","notes":[]},{"n":8,"t":"五人回到瑣拉和以實陶，見他們的弟兄；弟兄問他們說：「你們有甚麼話？」","notes":[]},{"n":9,"t":"他們回答說：「起來，我們上去攻擊他們吧！我們已經窺探那地，見那地甚好。你們為何靜坐不動呢？要急速前往得那地為業，不可遲延。","notes":[]},{"n":10,"t":"你們到了那裏，必看見安居無慮的民，地也寬闊。神已將那地交在你們手中；那地百物俱全，一無所缺。」","notes":[]},{"n":11,"t":"於是但族中的六百人，各帶兵器，從瑣拉和以實陶前往，","notes":[]},{"n":12,"t":"上到猶大的基列‧耶琳，在基列‧耶琳後邊安營。因此那地方名叫瑪哈尼‧但，直到今日。","notes":[]},{"n":13,"t":"他們從那裏往以法蓮山地去，來到米迦的住宅。","notes":[]},{"n":14,"t":"從前窺探拉億地的五個人對他們的弟兄說：「這宅子裏有以弗得和家中的神像，並雕刻的像與鑄成的像，你們知道嗎？現在你們要想一想當怎樣行。」","notes":[]},{"n":15,"t":"五人就進入米迦的住宅，到了那少年利未人的房內問他好。","notes":[]},{"n":16,"t":"那六百但人各帶兵器，站在門口。","notes":[]},{"n":17,"t":"窺探地的五個人走進去，將雕刻的像、以弗得、家中的神像，並鑄成的像，都拿了去。祭司和帶兵器的六百人，一同站在門口。","notes":[]},{"n":18,"t":"那五個人進入米迦的住宅，拿出雕刻的像、以弗得、家中的神像，並鑄成的像，祭司就問他們說：「你們做甚麼呢？」","notes":[]},{"n":19,"t":"他們回答說：「不要作聲，用手摀口，跟我們去吧！我們必以你為父、為祭司。你作一家的祭司好呢？還是作以色列一族一支派的祭司好呢？」","notes":[]},{"n":20,"t":"祭司心裏喜悅，便拿著以弗得和家中的神像，並雕刻的像，進入他們中間。","notes":[]},{"n":21,"t":"他們就轉身離開那裏，妻子、兒女、牲畜、財物都在前頭。","notes":[]},{"n":22,"t":"離米迦的住宅已遠，米迦的近鄰都聚集來，追趕但人，","notes":[]},{"n":23,"t":"呼叫但人。但人回頭問米迦說：「你聚集這許多人來做甚麼呢？」","notes":[]},{"n":24,"t":"米迦說：「你們將我所做的神像和祭司都帶了去，我還有所剩的嗎？怎麼還問我說『做甚麼』呢？」","notes":[]},{"n":25,"t":"但人對米迦說：「你不要使我們聽見你的聲音，恐怕有性暴的人攻擊你，以致你和你的全家盡都喪命。」","notes":[]},{"n":26,"t":"但人還是走他們的路。米迦見他們的勢力比自己強盛，就轉身回家去了。","notes":[]},{"n":27,"t":"但人將米迦所做的神像和他的祭司都帶到拉億，見安居無慮的民，就用刀殺了那民，又放火燒了那城，","notes":[]},{"n":28,"t":"並無人搭救；因為離西頓遠，他們又與別人沒有來往。城在平原，那平原靠近伯‧利合。但人又在那裏修城居住，","notes":[]},{"n":29,"t":"照著他們始祖以色列之子但的名字，給那城起名叫但；原先那城名叫拉億。","notes":[]},{"n":30,"t":"但人就為自己設立那雕刻的像。摩西的孫子、革舜的兒子約拿單，和他的子孫作但支派的祭司，直到那地遭擄掠的日子。","notes":[]},{"n":31,"t":"神的殿在示羅多少日子，但人為自己設立米迦所雕刻的像也在但多少日子。","notes":[]}]},"19":{"heading":"利未人和他的妾","verses":[{"n":1,"t":"當以色列中沒有王的時候，有住以法蓮山地那邊的一個利未人，娶了一個猶大伯利恆的女子為妾。","notes":[]},{"n":2,"t":"妾行淫離開丈夫，回猶大的伯利恆，到了父家，在那裏住了四個月。","notes":[]},{"n":3,"t":"她丈夫起來，帶著一個僕人、兩匹驢去見她，用好話勸她回來。女子就引丈夫進入父家。她父見了那人，便歡歡喜喜地迎接。","notes":[]},{"n":4,"t":"那人的岳父，就是女子的父親，將那人留下住了三天。於是二人一同吃喝、住宿。","notes":[]},{"n":5,"t":"到第四天，利未人清早起來要走，女子的父親對女婿說：「請你吃點飯，加添心力，然後可以行路。」","notes":[]},{"n":6,"t":"於是二人坐下一同吃喝。女子的父親對那人說：「請你再住一夜，暢快你的心。」","notes":[]},{"n":7,"t":"那人起來要走，他岳父強留他，他又住了一宿。","notes":[]},{"n":8,"t":"到第五天，他清早起來要走，女子的父親說：「請你吃點飯，加添心力，等到日頭偏西再走。」於是二人一同吃飯。","notes":[]},{"n":9,"t":"那人同他的妾和僕人起來要走，他岳父，就是女子的父親，對他說：「看哪，日頭偏西了，請你再住一夜；天快晚了，可以在這裏住宿，暢快你的心。明天早早起行回家去。」","notes":[]},{"n":10,"t":"那人不願再住一夜，就備上那兩匹驢，帶著妾起身走了，來到耶布斯的對面（耶布斯就是耶路撒冷。）","notes":[]},{"n":11,"t":"臨近耶布斯的時候，日頭快要落了，僕人對主人說：「我們不如進這耶布斯人的城裏住宿。」","notes":[]},{"n":12,"t":"主人回答說：「我們不可進不是以色列人住的外邦城，不如過到基比亞去」；","notes":[]},{"n":13,"t":"又對僕人說：「我們可以到一個地方，或住在基比亞，或住在拉瑪。」","notes":[]},{"n":14,"t":"他們就往前走。將到便雅憫的基比亞，日頭已經落了；","notes":[]},{"n":15,"t":"他們進入基比亞要在那裏住宿，就坐在城裏的街上，因為無人接他們進家住宿。","notes":[]},{"n":16,"t":"晚上，有一個老年人從田間做工回來。他原是以法蓮山地的人，住在基比亞；那地方的人卻是便雅憫人。","notes":[]},{"n":17,"t":"老年人舉目看見客人坐在城裏的街上，就問他說：「你從哪裏來？要往哪裏去？」","notes":[]},{"n":18,"t":"他回答說：「我們從猶大的伯利恆來，要往以法蓮山地那邊去。我原是那裏的人，到過猶大的伯利恆，現在我往耶和華的殿去，在這裏無人接我進他的家。","notes":[]},{"n":19,"t":"其實我有糧草可以餵驢，我與我的妾，並我的僕人，有餅有酒，並不缺少甚麼。」","notes":[]},{"n":20,"t":"老年人說：「願你平安！你所需用的我都給你，只是不可在街上過夜。」","notes":[]},{"n":21,"t":"於是領他們到家裏，餵上驢，他們就洗腳吃喝。","notes":[]},{"n":22,"t":"他們心裏正歡暢的時候，城中的匪徒圍住房子，連連叩門，對房主老人說：「你把那進你家的人帶出來，我們要與他交合。」","notes":[]},{"n":23,"t":"那房主出來對他們說：「弟兄們哪，不要這樣作惡；這人既然進了我的家，你們就不要行這醜事。","notes":[]},{"n":24,"t":"我有個女兒，還是處女，並有這人的妾，我將她們領出來任憑你們玷辱她們，只是向這人不可行這樣的醜事。」","notes":[]},{"n":25,"t":"那些人卻不聽從他的話。那人就把他的妾拉出去交給他們，他們便與她交合，終夜凌辱她，直到天色快亮才放她去。","notes":[]},{"n":26,"t":"天快亮的時候，婦人回到她主人住宿的房門前，就仆倒在地，直到天亮。","notes":[]},{"n":27,"t":"早晨，她的主人起來開了房門，出去要行路，不料那婦人仆倒在房門前，兩手搭在門檻上；","notes":[]},{"n":28,"t":"就對婦人說：「起來，我們走吧！」婦人卻不回答。那人便將她馱在驢上，起身回本處去了。","notes":[]},{"n":29,"t":"到了家裏，用刀將妾的屍身切成十二塊，使人拿著傳送以色列的四境。","notes":[]},{"n":30,"t":"凡看見的人都說：「從以色列人出埃及地，直到今日，這樣的事沒有行過，也沒有見過。現在應當思想，大家商議當怎樣辦理。」","notes":[]}]},"20":{"heading":"以色列人準備打仗","verses":[{"n":1,"t":"於是以色列從但到別是巴，以及住基列地的眾人都出來，如同一人，聚集在米斯巴耶和華面前。","notes":[]},{"n":2,"t":"以色列民的首領，就是各支派的軍長，都站在神百姓的會中；拿刀的步兵共有四十萬。","notes":[]},{"n":3,"t":"以色列人上到米斯巴，便雅憫人都聽見了。以色列人說：「請你將這件惡事的情由對我們說明。」","notes":[]},{"n":4,"t":"那利未人，就是被害之婦人的丈夫，回答說：「我和我的妾到了便雅憫的基比亞住宿。","notes":[]},{"n":5,"t":"基比亞人夜間起來，圍了我住的房子，想要殺我，又將我的妾強姦致死。","notes":[]},{"n":6,"t":"我就把我妾的屍身切成塊子，使人拿著傳送以色列得為業的全地，因為基比亞人在以色列中行了兇淫醜惡的事。","notes":[]},{"n":7,"t":"你們以色列人都當籌劃商議。」","notes":[]},{"n":8,"t":"眾民都起來如同一人，說：「我們連一人都不回自己帳棚、自己房屋去。","notes":[]},{"n":9,"t":"我們向基比亞人必這樣行，照所掣的籤去攻擊他們。","notes":[]},{"n":10,"t":"我們要在以色列各支派中，一百人挑取十人，一千人挑取百人，一萬人挑取千人，為民運糧，等大眾到了便雅憫的基比亞，就照基比亞人在以色列中所行的醜事征伐他們。」","notes":[]},{"n":11,"t":"於是以色列眾人彼此連合如同一人，聚集攻擊那城。","notes":[]},{"n":12,"t":"以色列眾支派打發人去，問便雅憫支派的各家說：「你們中間怎麼做了這樣的惡事呢？","notes":[]},{"n":13,"t":"現在你們要將基比亞的那些匪徒交出來，我們好治死他們，從以色列中除掉這惡。」便雅憫人卻不肯聽從他們弟兄以色列人的話。","notes":[]},{"n":14,"t":"便雅憫人從他們的各城裏出來，聚集到了基比亞，要與以色列人打仗。","notes":[]},{"n":15,"t":"那時便雅憫人從各城裏點出拿刀的，共有二萬六千；另外還有基比亞人點出七百精兵。","notes":[]},{"n":16,"t":"在眾軍之中有揀選的七百精兵，都是左手便利的，能用機弦甩石打人，毫髮不差。","notes":[]},{"n":17,"t":"便雅憫人之外，點出以色列人拿刀的，共有四十萬，都是戰士。","notes":[]},{"n":18,"t":"以色列人就起來，到伯特利去求問神說：「我們中間誰當首先上去與便雅憫人爭戰呢？」耶和華說：「猶大當先上去。」","notes":[],"heads":["攻打便雅憫人"]},{"n":19,"t":"以色列人早晨起來，對著基比亞安營。","notes":[]},{"n":20,"t":"以色列人出來，要與便雅憫人打仗，就在基比亞前擺陣。","notes":[]},{"n":21,"t":"便雅憫人就從基比亞出來，當日殺死以色列人二萬二千。","notes":[]},{"n":22,"t":"以色列人彼此奮勇，仍在頭一日擺陣的地方又擺陣。","notes":[]},{"n":23,"t":"未擺陣之先，以色列人上去，在耶和華面前哭號，直到晚上，求問耶和華說：「我們再去與我們弟兄便雅憫人打仗可以不可以？」耶和華說：「可以上去攻擊他們。」","notes":[]},{"n":24,"t":"第二日，以色列人就上前攻擊便雅憫人。","notes":[]},{"n":25,"t":"便雅憫人也在這日從基比亞出來，與以色列人接戰，又殺死他們一萬八千，都是拿刀的。","notes":[]},{"n":26,"t":"以色列眾人就上到伯特利，坐在耶和華面前哭號，當日禁食直到晚上；又在耶和華面前獻燔祭和平安祭。","notes":[]},{"n":27,"t":"那時，神的約櫃在那裏；亞倫的孫子、以利亞撒的兒子非尼哈侍立在約櫃前。以色列人問耶和華說：「我們當再出去與我們弟兄便雅憫人打仗呢？還是罷兵呢？」耶和華說：「你們當上去，因為明日我必將他們交在你們手中。」","notes":[],"end":28},{"n":29,"t":"以色列人在基比亞的四圍設下伏兵。","notes":[]},{"n":30,"t":"第三日，以色列人又上去攻擊便雅憫人，在基比亞前擺陣，與前兩次一樣。","notes":[]},{"n":31,"t":"便雅憫人也出來迎敵，就被引誘離城；在田間兩條路上，一通伯特利，一通基比亞，像前兩次，動手殺死以色列人約有三十個。","notes":[]},{"n":32,"t":"便雅憫人說：「他們仍舊敗在我們面前。」但以色列人說：「我們不如逃跑，引誘他們離開城到路上來。」","notes":[]},{"n":33,"t":"以色列眾人都起來，在巴力‧他瑪擺陣，以色列的伏兵從馬利‧迦巴埋伏的地方衝上前去。","notes":[]},{"n":34,"t":"有以色列人中的一萬精兵，來到基比亞前接戰，勢派甚是凶猛；便雅憫人卻不知道災禍臨近了。","notes":[]},{"n":35,"t":"耶和華使以色列人殺敗便雅憫人。那日，以色列人殺死便雅憫人二萬五千一百，都是拿刀的。","notes":[]},{"n":36,"t":"於是便雅憫人知道自己敗了。先是以色列人；因為靠著在基比亞前所設的伏兵，就在便雅憫人面前詐敗。","notes":[],"heads":["以色列人得勝"]},{"n":37,"t":"伏兵急忙闖進基比亞，用刀殺死全城的人。","notes":[]},{"n":38,"t":"以色列人預先同伏兵約定在城內放火，以煙氣上騰為號。","notes":[]},{"n":39,"t":"以色列人臨退陣的時候，便雅憫人動手殺死以色列人，約有三十個，就說：「他們仍像前次被我們殺敗了。」","notes":[]},{"n":40,"t":"當煙氣如柱從城中上騰的時候，便雅憫人回頭觀看，見全城的煙氣沖天。","notes":[]},{"n":41,"t":"以色列人又轉身回來，便雅憫人就甚驚惶，因為看見災禍臨到自己了。","notes":[]},{"n":42,"t":"他們在以色列人面前轉身往曠野逃跑；以色列人在後面追殺。那從各城裏出來的，也都夾攻殺滅他們。","notes":[]},{"n":43,"t":"以色列人圍繞便雅憫人，追趕他們，在他們歇腳之處、對著日出之地的基比亞踐踏他們。","notes":[]},{"n":44,"t":"便雅憫人死了的有一萬八千，都是勇士。","notes":[]},{"n":45,"t":"其餘的人轉身向曠野逃跑，往臨門磐去。以色列人在道路上殺了他們五千人，如拾取遺穗一樣，追到基頓又殺了他們二千人。","notes":[]},{"n":46,"t":"那日便雅憫死了的共有二萬五千人，都是拿刀的勇士。","notes":[]},{"n":47,"t":"只剩下六百人，轉身向曠野逃跑，到了臨門磐，就在那裏住了四個月。","notes":[]},{"n":48,"t":"以色列人又轉到便雅憫地，將各城的人和牲畜，並一切所遇見的，都用刀殺盡，又放火燒了一切城邑。","notes":[]}]},"21":{"heading":"為便雅憫支派人找妻","verses":[{"n":1,"t":"以色列人在米斯巴曾起誓說：「我們都不將女兒給便雅憫人為妻。」","notes":[]},{"n":2,"t":"以色列人來到伯特利，坐在神面前直到晚上，放聲痛哭，","notes":[]},{"n":3,"t":"說：「耶和華－以色列的神啊，為何以色列中有這樣缺了一支派的事呢？」","notes":[]},{"n":4,"t":"次日清早，百姓起來，在那裏築了一座壇，獻燔祭和平安祭。","notes":[]},{"n":5,"t":"以色列人彼此問說：「以色列各支派中，誰沒有同會眾上到耶和華面前來呢？」先是以色列人起過大誓說，凡不上米斯巴到耶和華面前來的，必將他治死。","notes":[]},{"n":6,"t":"以色列人為他們的弟兄便雅憫後悔，說：「如今以色列中絕了一個支派了。","notes":[]},{"n":7,"t":"我們既在耶和華面前起誓說，必不將我們的女兒給便雅憫人為妻，現在我們當怎樣辦理、使他們剩下的人有妻呢？」","notes":[]},{"n":8,"t":"又彼此問說：「以色列支派中誰沒有上米斯巴到耶和華面前來呢？」他們就查出基列‧雅比沒有一人進營到會眾那裏；","notes":[]},{"n":9,"t":"因為百姓被數的時候，沒有一個基列‧雅比人在那裏。","notes":[]},{"n":10,"t":"會眾就打發一萬二千大勇士，吩咐他們說：「你們去用刀將基列‧雅比人連婦女帶孩子都擊殺了。","notes":[]},{"n":11,"t":"所當行的就是這樣：要將一切男子和已嫁的女子盡行殺戮。」","notes":[]},{"n":12,"t":"他們在基列‧雅比人中，遇見了四百個未嫁的處女，就帶到迦南地的示羅營裏。","notes":[]},{"n":13,"t":"全會眾打發人到臨門磐的便雅憫人那裏，向他們說和睦的話。","notes":[]},{"n":14,"t":"當時便雅憫人回來了，以色列人就把所存活基列‧雅比的女子給他們為妻，還是不夠。","notes":[]},{"n":15,"t":"百姓為便雅憫人後悔，因為耶和華使以色列人缺了一個支派。","notes":["原文是使以色列中有了破口"]},{"n":16,"t":"會中的長老說：「便雅憫中的女子既然除滅了，我們當怎樣辦理、使那餘剩的人有妻呢？」","notes":[]},{"n":17,"t":"又說：「便雅憫逃脫的人當有地業，免得以色列中塗抹了一個支派。","notes":[]},{"n":18,"t":"只是我們不能將自己的女兒給他們為妻；因為以色列人曾起誓說，有將女兒給便雅憫人為妻的，必受咒詛。」","notes":[]},{"n":19,"t":"他們又說：「在利波拿以南，伯特利以北，在示劍大路以東的示羅，年年有耶和華的節期」；","notes":[]},{"n":20,"t":"就吩咐便雅憫人說：「你們去，在葡萄園中埋伏。","notes":[]},{"n":21,"t":"若看見示羅的女子出來跳舞，就從葡萄園出來，在示羅的女子中各搶一個為妻，回便雅憫地去。","notes":[]},{"n":22,"t":"他們的父親或是弟兄若來與我們爭競，我們就說：『求你們看我們的情面，施恩給這些人，因我們在爭戰的時候沒有給他們留下女子為妻。這也不是你們將女子給他們的；若是你們給的，就算有罪。』」","notes":[]},{"n":23,"t":"於是便雅憫人照樣而行，按著他們的數目從跳舞的女子中搶去為妻，就回自己的地業去，又重修城邑居住。","notes":[]},{"n":24,"t":"當時以色列人離開那裏，各歸本支派、本宗族、本地業去了。","notes":[]},{"n":25,"t":"那時，以色列中沒有王，各人任意而行。","notes":[]}]}},"RUT":{"1":{"heading":"以利米勒全家遷往摩押","verses":[{"n":1,"t":"當士師秉政的時候，國中遭遇饑荒。在猶大的伯利恆，有一個人帶著妻子和兩個兒子往摩押地去寄居。","notes":[]},{"n":2,"t":"這人名叫以利米勒，他的妻名叫拿俄米；他兩個兒子，一個名叫瑪倫，一個名叫基連，都是猶大伯利恆的以法他人。他們到了摩押地，就住在那裏。","notes":[]},{"n":3,"t":"後來拿俄米的丈夫以利米勒死了，剩下婦人和她兩個兒子。","notes":[]},{"n":4,"t":"這兩個兒子娶了摩押女子為妻，一個名叫俄珥巴，一個名叫路得，在那裏住了約有十年。","notes":[]},{"n":5,"t":"瑪倫和基連二人也死了，剩下拿俄米，沒有丈夫，也沒有兒子。","notes":[]},{"n":6,"t":"她就與兩個兒婦起身，要從摩押地歸回；因為她在摩押地聽見耶和華眷顧自己的百姓，賜糧食與他們。","notes":[],"heads":["拿俄米和路得回伯利恆"]},{"n":7,"t":"於是她和兩個兒婦起行離開所住的地方，要回猶大地去。","notes":[]},{"n":8,"t":"拿俄米對兩個兒婦說：「你們各人回娘家去吧。願耶和華恩待你們，像你們恩待已死的人與我一樣！","notes":[]},{"n":9,"t":"願耶和華使你們各在新夫家中得平安！」於是拿俄米與她們親嘴。她們就放聲而哭，","notes":[]},{"n":10,"t":"說：「不然，我們必與你一同回你本國去。」","notes":[]},{"n":11,"t":"拿俄米說：「我女兒們哪，回去吧！為何要跟我去呢？我還能生子作你們的丈夫嗎？","notes":[]},{"n":12,"t":"我女兒們哪，回去吧！我年紀老邁，不能再有丈夫；即或說，我還有指望，今夜有丈夫可以生子，","notes":[]},{"n":13,"t":"你們豈能等著他們長大呢？你們豈能等著他們不嫁別人呢？我女兒們哪，不要這樣。我為你們的緣故甚是愁苦，因為耶和華伸手攻擊我。」","notes":[]},{"n":14,"t":"兩個兒婦又放聲而哭，俄珥巴與婆婆親嘴而別，只是路得捨不得拿俄米。","notes":[]},{"n":15,"t":"拿俄米說：「看哪，你嫂子已經回她本國和她所拜的神那裏去了，你也跟著你嫂子回去吧！」","notes":[]},{"n":16,"t":"路得說：「不要催我回去不跟隨你。你往哪裏去，我也往那裏去；你在哪裏住宿，我也在那裏住宿；你的國就是我的國，你的神就是我的神。","notes":[]},{"n":17,"t":"你在哪裏死，我也在那裏死，也葬在那裏。除非死能使你我相離！不然，願耶和華重重地降罰與我。」","notes":[]},{"n":18,"t":"拿俄米見路得定意要跟隨自己去，就不再勸她了。","notes":[]},{"n":19,"t":"於是二人同行，來到伯利恆。她們到了伯利恆，合城的人就都驚訝。婦女們說：「這是拿俄米嗎？」","notes":[]},{"n":20,"t":"拿俄米對她們說：「不要叫我拿俄米，要叫我瑪拉，因為全能者使我受了大苦。","notes":["就是甜的意思","就是苦的意思"]},{"n":21,"t":"我滿滿地出去，耶和華使我空空地回來。耶和華降禍與我；全能者使我受苦。既是這樣，你們為何還叫我拿俄米呢？」","notes":[]},{"n":22,"t":"拿俄米和她兒婦摩押女子路得，從摩押地回來到伯利恆，正是動手割大麥的時候。","notes":[]}]},"2":{"heading":"路得在波阿斯田裏撿麥穗","verses":[{"n":1,"t":"拿俄米的丈夫以利米勒的親族中，有一個人名叫波阿斯，是個大財主。","notes":[]},{"n":2,"t":"摩押女子路得對拿俄米說：「容我往田間去，我蒙誰的恩，就在誰的身後拾取麥穗。」拿俄米說：「女兒啊，你只管去。」","notes":[]},{"n":3,"t":"路得就去了，來到田間，在收割的人身後拾取麥穗。她恰巧到了以利米勒本族的人波阿斯那塊田裏。","notes":[]},{"n":4,"t":"波阿斯正從伯利恆來，對收割的人說：「願耶和華與你們同在！」他們回答說：「願耶和華賜福與你！」","notes":[]},{"n":5,"t":"波阿斯問監管收割的僕人說：「那是誰家的女子？」","notes":[]},{"n":6,"t":"監管收割的僕人回答說：「是那摩押女子，跟隨拿俄米從摩押地回來的。","notes":[]},{"n":7,"t":"她說：『請你容我跟著收割的人拾取打捆剩下的麥穗。』她從早晨直到如今，除了在屋子裏坐一會兒，常在這裏。」","notes":[]},{"n":8,"t":"波阿斯對路得說：「女兒啊，聽我說，不要往別人田裏拾取麥穗，也不要離開這裏，要常與我使女們在一處。","notes":[]},{"n":9,"t":"我的僕人在那塊田收割，你就跟著他們去。我已經吩咐僕人不可欺負你；你若渴了，就可以到器皿那裏喝僕人打來的水。」","notes":[]},{"n":10,"t":"路得就俯伏在地叩拜，對他說：「我既是外邦人，怎麼蒙你的恩，這樣顧恤我呢？」","notes":[]},{"n":11,"t":"波阿斯回答說：「自從你丈夫死後，凡你向婆婆所行的，並你離開父母和本地，到素不認識的民中，這些事人全都告訴我了。","notes":[]},{"n":12,"t":"願耶和華照你所行的賞賜你。你來投靠耶和華－以色列神的翅膀下，願你滿得他的賞賜。」","notes":[]},{"n":13,"t":"路得說：「我主啊，願在你眼前蒙恩。我雖然不及你的一個使女，你還用慈愛的話安慰我的心。」","notes":[]},{"n":14,"t":"到了吃飯的時候，波阿斯對路得說：「你到這裏來吃餅，將餅蘸在醋裏。」路得就在收割的人旁邊坐下；他們把烘了的穗子遞給她。她吃飽了，還有餘剩的。","notes":[]},{"n":15,"t":"她起來又拾取麥穗，波阿斯吩咐僕人說：「她就是在捆中拾取麥穗，也可以容她，不可羞辱她；","notes":[]},{"n":16,"t":"並要從捆裏抽出些來，留在地下任她拾取，不可叱嚇她。」","notes":[]},{"n":17,"t":"這樣，路得在田間拾取麥穗，直到晚上，將所拾取的打了，約有一伊法大麥。","notes":[]},{"n":18,"t":"她就把所拾取的帶進城去給婆婆看，又把她吃飽了所剩的給了婆婆。","notes":[]},{"n":19,"t":"婆婆問她說：「你今日在哪裏拾取麥穗，在哪裏做工呢？願那顧恤你的得福。」路得就告訴婆婆說：「我今日在一個名叫波阿斯的人那裏做工。」","notes":[]},{"n":20,"t":"拿俄米對兒婦說：「願那人蒙耶和華賜福，因為他不斷地恩待活人死人。」拿俄米又說：「那是我們本族的人，是一個至近的親屬。」","notes":[]},{"n":21,"t":"摩押女子路得說：「他對我說：『你要緊隨我的僕人拾取麥穗，直等他們收完了我的莊稼。』」","notes":[]},{"n":22,"t":"拿俄米對兒婦路得說：「女兒啊，你跟著他的使女出去，不叫人遇見你在別人田間，這才為好。」","notes":[]},{"n":23,"t":"於是路得與波阿斯的使女常在一處拾取麥穗，直到收完了大麥和小麥。路得仍與婆婆同住。","notes":[]}]},"3":{"heading":"拿俄米替路得找歸宿","verses":[{"n":1,"t":"路得的婆婆拿俄米對她說：「女兒啊，我不當為你找個安身之處，使你享福嗎？","notes":[]},{"n":2,"t":"你與波阿斯的使女常在一處，波阿斯不是我們的親族嗎？他今夜在場上簸大麥；","notes":[]},{"n":3,"t":"你要沐浴抹膏，換上衣服，下到場上，卻不要使那人認出你來。你等他吃喝完了，","notes":[]},{"n":4,"t":"到他睡的時候，你看準他睡的地方，就進去掀開他腳上的被，躺臥在那裏，他必告訴你所當做的事。」","notes":[]},{"n":5,"t":"路得說：「凡你所吩咐的，我必遵行。」","notes":[]},{"n":6,"t":"路得就下到場上，照她婆婆所吩咐她的而行。","notes":[]},{"n":7,"t":"波阿斯吃喝完了，心裏歡暢，就去睡在麥堆旁邊。路得便悄悄地來掀開他腳上的被，躺臥在那裏。","notes":[]},{"n":8,"t":"到了夜半，那人忽然驚醒，翻過身來，不料有女子躺在他的腳下。","notes":[]},{"n":9,"t":"他就說：「你是誰？」回答說：「我是你的婢女路得。求你用你的衣襟遮蓋我，因為你是我一個至近的親屬。」","notes":[]},{"n":10,"t":"波阿斯說：「女兒啊，願你蒙耶和華賜福。你末後的恩比先前更大；因為少年人無論貧富，你都沒有跟從。","notes":[]},{"n":11,"t":"女兒啊，現在不要懼怕，凡你所說的，我必照著行；我本城的人都知道你是個賢德的女子。","notes":[]},{"n":12,"t":"我實在是你一個至近的親屬，只是還有一個人比我更近。","notes":[]},{"n":13,"t":"你今夜在這裏住宿，明早他若肯為你盡親屬的本分，就由他吧！倘若不肯，我指著永生的耶和華起誓，我必為你盡了本分，你只管躺到天亮。」","notes":[]},{"n":14,"t":"路得便在他腳下躺到天快亮，人彼此不能辨認的時候就起來了。波阿斯說：「不可使人知道有女子到場上來」；","notes":[]},{"n":15,"t":"又對路得說：「打開你所披的外衣。」她打開了，波阿斯就撮了六簸箕大麥，幫她扛在肩上，她便進城去了。","notes":[]},{"n":16,"t":"路得回到婆婆那裏，婆婆說：「女兒啊，怎麼樣了？」路得就將那人向她所行的述說了一遍，","notes":[]},{"n":17,"t":"又說：「那人給了我六簸箕大麥，對我說：『你不可空手回去見你的婆婆。』」","notes":[]},{"n":18,"t":"婆婆說：「女兒啊，你只管安坐等候，看這事怎樣成就，因為那人今日不辦成這事必不休息。」","notes":[]}]},"4":{"heading":"波阿斯娶路得","verses":[{"n":1,"t":"波阿斯到了城門，坐在那裏，恰巧波阿斯所說的那至近的親屬經過。波阿斯說：「某人哪，你來坐在這裏。」他就來坐下。","notes":[]},{"n":2,"t":"波阿斯又從本城的長老中揀選了十人，對他們說：「請你們坐在這裏。」他們就都坐下。","notes":[]},{"n":3,"t":"波阿斯對那至近的親屬說：「從摩押地回來的拿俄米，現在要賣我們族兄以利米勒的那塊地；","notes":[]},{"n":4,"t":"我想當贖那塊地的是你，其次是我，以外再沒有別人了。你可以在這裏的人面前和我本國的長老面前說明，你若肯贖就贖，若不肯贖就告訴我。」那人回答說：「我肯贖。」","notes":[]},{"n":5,"t":"波阿斯說：「你從拿俄米手中買這地的時候，也當娶死人的妻摩押女子路得，使死人在產業上存留他的名。」","notes":["原文是買；十節同"]},{"n":6,"t":"那人說：「這樣我就不能贖了，恐怕於我的產業有礙。你可以贖我所當贖的，我不能贖了。」","notes":[]},{"n":7,"t":"從前，在以色列中要定奪甚麼事，或贖回，或交易，這人就脫鞋給那人。以色列人都以此為證據。","notes":[]},{"n":8,"t":"那人對波阿斯說：「你自己買吧！」於是將鞋脫下來了。","notes":[]},{"n":9,"t":"波阿斯對長老和眾民說：「你們今日作見證，凡屬以利米勒和基連、瑪倫的，我都從拿俄米手中置買了；","notes":[]},{"n":10,"t":"又娶了瑪倫的妻摩押女子路得為妻，好在死人的產業上存留他的名，免得他的名在本族本鄉滅沒。你們今日可以作見證。」","notes":[]},{"n":11,"t":"在城門坐著的眾民和長老都說：「我們作見證。願耶和華使進你家的這女子，像建立以色列家的拉結、利亞二人一樣。又願你在以法他得亨通，在伯利恆得名聲。","notes":[]},{"n":12,"t":"願耶和華從這少年女子賜你後裔，使你的家像她瑪從猶大所生法勒斯的家一般。」","notes":[]},{"n":13,"t":"於是，波阿斯娶了路得為妻，與她同房。耶和華使她懷孕生了一個兒子。","notes":[],"heads":["波阿斯和他的後代"]},{"n":14,"t":"婦人們對拿俄米說：「耶和華是應當稱頌的！因為今日沒有撇下你，使你無至近的親屬。願這孩子在以色列中得名聲。","notes":[]},{"n":15,"t":"他必提起你的精神，奉養你的老，因為是愛慕你的那兒婦所生的。有這兒婦比有七個兒子還好！」","notes":[]},{"n":16,"t":"拿俄米就把孩子抱在懷中，作他的養母。","notes":[]},{"n":17,"t":"鄰舍的婦人說：「拿俄米得孩子了！」就給孩子起名叫俄備得。這俄備得是耶西的父，耶西是大衛的父。","notes":[]},{"n":18,"t":"法勒斯的後代記在下面：法勒斯生希斯崙；","notes":[]},{"n":19,"t":"希斯崙生蘭；蘭生亞米拿達；","notes":[]},{"n":20,"t":"亞米拿達生拿順；拿順生撒門；","notes":[]},{"n":21,"t":"撒門生波阿斯；波阿斯生俄備得；","notes":[]},{"n":22,"t":"俄備得生耶西；耶西生大衛。","notes":[]}]}},"1SA":{"1":{"heading":"以利加拿和他的家眷在示羅","verses":[{"n":1,"t":"以法蓮山地的拉瑪‧瑣非有一個以法蓮人，名叫以利加拿，是蘇弗的玄孫，託戶的曾孫，以利戶的孫子，耶羅罕的兒子。","notes":[]},{"n":2,"t":"他有兩個妻：一名哈拿，一名毗尼拿。毗尼拿有兒女，哈拿沒有兒女。","notes":[]},{"n":3,"t":"這人每年從本城上到示羅，敬拜祭祀萬軍之耶和華；在那裏有以利的兩個兒子何弗尼、非尼哈當耶和華的祭司。","notes":[]},{"n":4,"t":"以利加拿每逢獻祭的日子，將祭肉分給他的妻毗尼拿和毗尼拿所生的兒女；","notes":[]},{"n":5,"t":"給哈拿的卻是雙分，因為他愛哈拿。無奈耶和華不使哈拿生育。","notes":[]},{"n":6,"t":"毗尼拿見耶和華不使哈拿生育，就作她的對頭，大大激動她，要使她生氣。","notes":[]},{"n":7,"t":"每年上到耶和華殿的時候，以利加拿都以雙分給哈拿；毗尼拿仍是激動她，以致她哭泣不吃飯。","notes":[]},{"n":8,"t":"她丈夫以利加拿對她說：「哈拿啊，你為何哭泣，不吃飯，心裏愁悶呢？有我不比十個兒子還好嗎？」","notes":[]},{"n":9,"t":"他們在示羅吃喝完了，哈拿就站起來。祭司以利在耶和華殿的門框旁邊，坐在自己的位上。","notes":[],"heads":["哈拿和以利"]},{"n":10,"t":"哈拿心裏愁苦，就痛痛哭泣，祈禱耶和華，","notes":[]},{"n":11,"t":"許願說：「萬軍之耶和華啊，你若垂顧婢女的苦情，眷念不忘婢女，賜我一個兒子，我必使他終身歸與耶和華，不用剃頭刀剃他的頭。」","notes":[]},{"n":12,"t":"哈拿在耶和華面前不住地祈禱，以利定睛看她的嘴。（","notes":[]},{"n":13,"t":"原來哈拿心中默禱，只動嘴唇，不出聲音，因此以利以為她喝醉了。）","notes":[]},{"n":14,"t":"以利對她說：「你要醉到幾時呢？你不應該喝酒。」","notes":[]},{"n":15,"t":"哈拿回答說：「主啊，不是這樣。我是心裏愁苦的婦人，清酒濃酒都沒有喝，但在耶和華面前傾心吐意。","notes":[]},{"n":16,"t":"不要將婢女看作不正經的女子。我因被人激動，愁苦太多，所以祈求到如今。」","notes":[]},{"n":17,"t":"以利說：「你可以平平安安地回去。願以色列的神允准你向他所求的！」","notes":[]},{"n":18,"t":"哈拿說：「願婢女在你眼前蒙恩。」於是婦人走去吃飯，面上再不帶愁容了。","notes":[]},{"n":19,"t":"次日清早，他們起來，在耶和華面前敬拜，就回拉瑪。到了家裏，以利加拿和妻哈拿同房，耶和華顧念哈拿，","notes":[],"heads":["撒母耳出生和奉獻"]},{"n":20,"t":"哈拿就懷孕。日期滿足，生了一個兒子，給他起名叫撒母耳，說：「這是我從耶和華那裏求來的。」","notes":[]},{"n":21,"t":"以利加拿和他全家都上示羅去，要向耶和華獻年祭，並還所許的願。","notes":[]},{"n":22,"t":"哈拿卻沒有上去，對丈夫說：「等孩子斷了奶，我便帶他上去朝見耶和華，使他永遠住在那裏。」","notes":[]},{"n":23,"t":"她丈夫以利加拿說：「就隨你的意行吧！可以等兒子斷了奶。但願耶和華應驗他的話。」於是婦人在家裏乳養兒子，直到斷了奶；","notes":[]},{"n":24,"t":"既斷了奶，就把孩子帶上示羅，到了耶和華的殿；又帶了三隻公牛，一伊法細麵，一皮袋酒。（那時，孩子還小。）","notes":[]},{"n":25,"t":"宰了一隻公牛，就領孩子到以利面前。","notes":[]},{"n":26,"t":"婦人說：「主啊，我敢在你面前起誓，從前在你這裏站著祈求耶和華的那婦人，就是我。","notes":[]},{"n":27,"t":"我祈求為要得這孩子；耶和華已將我所求的賜給我了。","notes":[]},{"n":28,"t":"所以，我將這孩子歸與耶和華，使他終身歸與耶和華。」於是在那裏敬拜耶和華。","notes":[]}]},"2":{"heading":"哈拿的禱告","verses":[{"n":1,"t":"哈拿禱告說：我的心因耶和華快樂；我的角因耶和華高舉。我的口向仇敵張開；我因耶和華的救恩歡欣。","notes":[]},{"n":2,"t":"只有耶和華為聖；除他以外沒有可比的，也沒有磐石像我們的神。","notes":[]},{"n":3,"t":"人不要誇口說驕傲的話，也不要出狂妄的言語；因耶和華是大有智識的神，人的行為被他衡量。","notes":[]},{"n":4,"t":"勇士的弓都已折斷；跌倒的人以力量束腰。","notes":[]},{"n":5,"t":"素來飽足的，反作用人求食；飢餓的，再不飢餓。不生育的，生了七個兒子；多有兒女的，反倒衰微。","notes":[]},{"n":6,"t":"耶和華使人死，也使人活，使人下陰間，也使人往上升。","notes":[]},{"n":7,"t":"他使人貧窮，也使人富足，使人卑微，也使人高貴。","notes":[]},{"n":8,"t":"他從灰塵裏抬舉貧寒人，從糞堆中提拔窮乏人，使他們與王子同坐，得著榮耀的座位。地的柱子屬於耶和華；他將世界立在其上。","notes":[]},{"n":9,"t":"他必保護聖民的腳步，使惡人在黑暗中寂然不動；人都不能靠力量得勝。","notes":[]},{"n":10,"t":"與耶和華爭競的，必被打碎；耶和華必從天上以雷攻擊他，必審判地極的人，將力量賜與所立的王，高舉受膏者的角。","notes":[]},{"n":11,"t":"以利加拿往拉瑪回家去了。那孩子在祭司以利面前事奉耶和華。","notes":[]},{"n":12,"t":"以利的兩個兒子是惡人，不認識耶和華。","notes":[],"heads":["以利的兩個兒子"]},{"n":13,"t":"這二祭司待百姓是這樣的規矩：凡有人獻祭，正煮肉的時候，祭司的僕人就來，手拿三齒的叉子，","notes":[]},{"n":14,"t":"將叉子往罐裏，或鼎裏，或釜裏，或鍋裏一插，插上來的肉，祭司都取了去。凡上到示羅的以色列人，他們都是這樣看待。","notes":[]},{"n":15,"t":"又在未燒脂油以前，祭司的僕人就來對獻祭的人說：「將肉給祭司，叫他烤吧。他不要煮過的，要生的。」","notes":[]},{"n":16,"t":"獻祭的人若說：「必須先燒脂油，然後你可以隨意取肉。」僕人就說：「你立時給我，不然我便搶去。」","notes":[]},{"n":17,"t":"如此，這二少年人的罪在耶和華面前甚重了，因為他們藐視耶和華的祭物。","notes":["或譯：他們使人厭棄給耶和華獻祭"]},{"n":18,"t":"那時，撒母耳還是孩子，穿著細麻布的以弗得，侍立在耶和華面前。","notes":[],"heads":["撒母耳在示羅"]},{"n":19,"t":"他母親每年為他做一件小外袍，同著丈夫上來獻年祭的時候帶來給他。","notes":[]},{"n":20,"t":"以利為以利加拿和他的妻祝福，說：「願耶和華由這婦人再賜你後裔，代替你從耶和華求來的孩子。」他們就回本鄉去了。","notes":[]},{"n":21,"t":"耶和華眷顧哈拿，她就懷孕生了三個兒子，兩個女兒。那孩子撒母耳在耶和華面前漸漸長大。","notes":[]},{"n":22,"t":"以利年甚老邁，聽見他兩個兒子待以色列眾人的事，又聽見他們與會幕門前伺候的婦人苟合，","notes":[],"heads":["以利和他的兒子"]},{"n":23,"t":"他就對他們說：「你們為何行這樣的事呢？我從這眾百姓聽見你們的惡行。","notes":[]},{"n":24,"t":"我兒啊，不可這樣！我聽見你們的風聲不好，你們使耶和華的百姓犯了罪。","notes":[]},{"n":25,"t":"人若得罪人，有士師審判他；人若得罪耶和華，誰能為他祈求呢？」然而他們還是不聽父親的話，因為耶和華想要殺他們。","notes":[]},{"n":26,"t":"孩子撒母耳漸漸長大，耶和華與人越發喜愛他。","notes":[]},{"n":27,"t":"有神人來見以利，對他說：「耶和華如此說：『你祖父在埃及法老家作奴僕的時候，我不是向他們顯現嗎？","notes":[],"heads":["預言以利家遭禍"]},{"n":28,"t":"在以色列眾支派中，我不是揀選人作我的祭司，使他燒香，在我壇上獻祭，在我面前穿以弗得，又將以色列人所獻的火祭都賜給你父家嗎？","notes":[]},{"n":29,"t":"我所吩咐獻在我居所的祭物，你們為何踐踏？尊重你的兒子過於尊重我，將我民以色列所獻美好的祭物肥己呢？』","notes":[]},{"n":30,"t":"因此，耶和華－以色列的神說：『我曾說，你和你父家必永遠行在我面前；現在我卻說，決不容你們這樣行。因為尊重我的，我必重看他；藐視我的，他必被輕視。","notes":[]},{"n":31,"t":"日子必到，我要折斷你的膀臂和你父家的膀臂，使你家中沒有一個老年人。","notes":[]},{"n":32,"t":"在神使以色列人享福的時候，你必看見我居所的敗落。在你家中必永遠沒有一個老年人。","notes":[]},{"n":33,"t":"我必不從我壇前滅盡你家中的人；那未滅的必使你眼目乾癟、心中憂傷。你家中所生的人都必死在中年。","notes":[]},{"n":34,"t":"你的兩個兒子何弗尼、非尼哈所遭遇的事可作你的證據：他們二人必一日同死。","notes":[]},{"n":35,"t":"我要為自己立一個忠心的祭司；他必照我的心意而行。我要為他建立堅固的家；他必永遠行在我的受膏者面前。","notes":[]},{"n":36,"t":"你家所剩下的人都必來叩拜他，求塊銀子，求個餅，說：求你賜我祭司的職分，好叫我得點餅吃。』」","notes":[]}]},"3":{"heading":"耶和華向撒母耳顯現","verses":[{"n":1,"t":"童子撒母耳在以利面前事奉耶和華。當那些日子，耶和華的言語稀少，不常有默示。","notes":[]},{"n":2,"t":"一日，以利睡臥在自己的地方；他眼目昏花，看不分明。","notes":[]},{"n":3,"t":"神的燈在神耶和華殿內約櫃那裏，還沒有熄滅，撒母耳已經睡了。","notes":[]},{"n":4,"t":"耶和華呼喚撒母耳。撒母耳說：「我在這裏！」","notes":[]},{"n":5,"t":"就跑到以利那裏，說：「你呼喚我？我在這裏。」以利回答說：「我沒有呼喚你，你去睡吧。」他就去睡了。","notes":[]},{"n":6,"t":"耶和華又呼喚撒母耳。撒母耳起來，到以利那裏，說：「你呼喚我？我在這裏。」以利回答說：「我的兒，我沒有呼喚你，你去睡吧。」","notes":[]},{"n":7,"t":"那時撒母耳還未認識耶和華，也未得耶和華的默示。","notes":[]},{"n":8,"t":"耶和華第三次呼喚撒母耳。撒母耳起來，到以利那裏，說：「你又呼喚我？我在這裏。」以利才明白是耶和華呼喚童子。","notes":[]},{"n":9,"t":"因此以利對撒母耳說：「你仍去睡吧；若再呼喚你，你就說：『耶和華啊，請說，僕人敬聽！』」撒母耳就去，仍睡在原處。","notes":[]},{"n":10,"t":"耶和華又來站著，像前三次呼喚說：「撒母耳啊！撒母耳啊！」撒母耳回答說：「請說，僕人敬聽！」","notes":[]},{"n":11,"t":"耶和華對撒母耳說：「我在以色列中必行一件事，叫聽見的人都必耳鳴。","notes":[]},{"n":12,"t":"我指著以利家所說的話，到了時候，我必始終應驗在以利身上。","notes":[]},{"n":13,"t":"我曾告訴他必永遠降罰與他的家，因他知道兒子作孽，自招咒詛，卻不禁止他們。","notes":[]},{"n":14,"t":"所以我向以利家起誓說：『以利家的罪孽，雖獻祭奉禮物，永不能得贖去。』」","notes":[]},{"n":15,"t":"撒母耳睡到天亮，就開了耶和華的殿門，不敢將默示告訴以利。","notes":[]},{"n":16,"t":"以利呼喚撒母耳說：「我兒撒母耳啊！」撒母耳回答說：「我在這裏！」","notes":[]},{"n":17,"t":"以利說：「耶和華對你說甚麼，你不要向我隱瞞；你若將神對你所說的隱瞞一句，願他重重地降罰與你。」","notes":[]},{"n":18,"t":"撒母耳就把一切話都告訴了以利，並沒有隱瞞。以利說：「這是出於耶和華，願他憑自己的意旨而行。」","notes":[]},{"n":19,"t":"撒母耳長大了，耶和華與他同在，使他所說的話一句都不落空。","notes":[]},{"n":20,"t":"從但到別是巴所有的以色列人都知道耶和華立撒母耳為先知。","notes":[]},{"n":21,"t":"耶和華又在示羅顯現；因為耶和華將自己的話默示撒母耳，撒母耳就把這話傳遍以色列地。","notes":[]}]},"4":{"heading":"約櫃被擄","verses":[{"n":1,"t":"以色列人出去與非利士人打仗，安營在以便以謝；非利士人安營在亞弗。","notes":[]},{"n":2,"t":"非利士人向以色列人擺陣。兩軍交戰的時候，以色列人敗在非利士人面前；非利士人在戰場上殺了他們的軍兵約有四千人。","notes":[]},{"n":3,"t":"百姓回到營裏，以色列的長老說：「耶和華今日為何使我們敗在非利士人面前呢？我們不如將耶和華的約櫃從示羅抬到我們這裏來，好在我們中間救我們脫離敵人的手。」","notes":[]},{"n":4,"t":"於是百姓打發人到示羅，從那裏將坐在二基路伯上萬軍之耶和華的約櫃抬來。以利的兩個兒子何弗尼、非尼哈與神的約櫃同來。","notes":[]},{"n":5,"t":"耶和華的約櫃到了營中，以色列眾人就大聲歡呼，地便震動。","notes":[]},{"n":6,"t":"非利士人聽見歡呼的聲音，就說：「在希伯來人營裏大聲歡呼，是甚麼緣故呢？」隨後就知道耶和華的約櫃到了營中。","notes":[]},{"n":7,"t":"非利士人就懼怕起來，說：「有神到了他們營中」；又說：「我們有禍了！向來不曾有這樣的事。","notes":[]},{"n":8,"t":"我們有禍了！誰能救我們脫離這些大能之神的手呢？從前在曠野用各樣災殃擊打埃及人的，就是這些神。","notes":[]},{"n":9,"t":"非利士人哪，你們要剛強，要作大丈夫，免得作希伯來人的奴僕，如同他們作你們的奴僕一樣。你們要作大丈夫，與他們爭戰。」","notes":[]},{"n":10,"t":"非利士人和以色列人打仗，以色列人敗了，各向各家奔逃，被殺的人甚多，以色列的步兵仆倒了三萬。","notes":[]},{"n":11,"t":"神的約櫃被擄去，以利的兩個兒子何弗尼、非尼哈也都被殺了。","notes":[]},{"n":12,"t":"當日，有一個便雅憫人從陣上逃跑，衣服撕裂，頭蒙灰塵，來到示羅。","notes":[],"heads":["以利的死"]},{"n":13,"t":"到了的時候，以利正在道旁坐在自己的位上觀望，為神的約櫃心裏擔憂。那人進城報信，合城的人就都呼喊起來。","notes":[]},{"n":14,"t":"以利聽見呼喊的聲音就問說：「這喧嚷是甚麼緣故呢？」那人急忙來報信給以利。","notes":[]},{"n":15,"t":"那時以利九十八歲了，眼目發直，不能看見。","notes":[]},{"n":16,"t":"那人對以利說：「我是從陣上來的，今日我從陣上逃回。」以利說：「我兒，事情怎樣？」","notes":[]},{"n":17,"t":"報信的回答說：「以色列人在非利士人面前逃跑，民中被殺的甚多！你的兩個兒子何弗尼、非尼哈也都死了，並且神的約櫃被擄去。」","notes":[]},{"n":18,"t":"他一提神的約櫃，以利就從他的位上往後跌倒，在門旁折斷頸項而死；因為他年紀老邁，身體沉重。以利作以色列的士師四十年。","notes":[]},{"n":19,"t":"以利的兒婦、非尼哈的妻懷孕將到產期，她聽見神的約櫃被擄去，公公和丈夫都死了，就猛然疼痛，曲身生產；","notes":[],"heads":["非尼哈遺孀的死"]},{"n":20,"t":"將要死的時候，旁邊站著的婦人們對她說：「不要怕！你生了男孩子了。」她卻不回答，也不放在心上。","notes":[]},{"n":21,"t":"她給孩子起名叫以迦博，說：「榮耀離開以色列了！」這是因神的約櫃被擄去，又因她公公和丈夫都死了。","notes":[]},{"n":22,"t":"她又說：「榮耀離開以色列，因為神的約櫃被擄去了。」","notes":[]}]},"5":{"heading":"約櫃在非利士人當中","verses":[{"n":1,"t":"非利士人將神的約櫃從以便以謝抬到亞實突。","notes":[]},{"n":2,"t":"非利士人將神的約櫃抬進大袞廟，放在大袞的旁邊。","notes":[]},{"n":3,"t":"次日清早，亞實突人起來，見大袞仆倒在耶和華的約櫃前，臉伏於地，就把大袞仍立在原處。","notes":[]},{"n":4,"t":"又次日清早起來，見大袞仆倒在耶和華的約櫃前，臉伏於地，並且大袞的頭和兩手都在門檻上折斷，只剩下大袞的殘體。（","notes":[]},{"n":5,"t":"因此，大袞的祭司和一切進亞實突、大袞廟的人都不踏大袞廟的門檻，直到今日。）","notes":[]},{"n":6,"t":"耶和華的手重重加在亞實突人身上，敗壞他們，使他們生痔瘡。亞實突和亞實突的四境都是如此。","notes":[]},{"n":7,"t":"亞實突人見這光景，就說：「以色列神的約櫃不可留在我們這裏，因為他的手重重加在我們和我們神大袞的身上」；","notes":[]},{"n":8,"t":"就打發人去請非利士的眾首領來聚集，問他們說：「我們向以色列神的約櫃應當怎樣行呢？」他們回答說：「可以將以色列神的約櫃運到迦特去。」於是將以色列神的約櫃運到那裏去。","notes":[]},{"n":9,"t":"運到之後，耶和華的手攻擊那城，使那城的人大大驚慌，無論大小都生痔瘡。","notes":[]},{"n":10,"t":"他們就把神的約櫃送到以革倫。神的約櫃到了，以革倫人就喊嚷起來說：「他們將以色列神的約櫃運到我們這裏，要害我們和我們的眾民！」","notes":[]},{"n":11,"t":"於是打發人去請非利士的眾首領來，說：「願你們將以色列神的約櫃送回原處，免得害了我們和我們的眾民！」原來神的手重重攻擊那城，城中的人有因驚慌而死的；","notes":[]},{"n":12,"t":"未曾死的人都生了痔瘡。合城呼號，聲音上達於天。","notes":[]}]},"6":{"heading":"送回約櫃","verses":[{"n":1,"t":"耶和華的約櫃在非利士人之地七個月。","notes":[]},{"n":2,"t":"非利士人將祭司和占卜的聚了來，問他們說：「我們向耶和華的約櫃應當怎樣行？請指示我們用何法將約櫃送回原處。」","notes":[]},{"n":3,"t":"他們說：「若要將以色列神的約櫃送回去，不可空空地送去，必要給他獻賠罪的禮物，然後你們可得痊癒，並知道他的手為何不離開你們。」","notes":[]},{"n":4,"t":"非利士人說：「應當用甚麼獻為賠罪的禮物呢？」他們回答說：「當照非利士首領的數目，用五個金痔瘡，五個金老鼠，因為在你們眾人和你們首領的身上都是一樣的災。","notes":[]},{"n":5,"t":"所以當製造你們痔瘡的像和毀壞你們田地老鼠的像，並要歸榮耀給以色列的神，或者他向你們和你們的神，並你們的田地，把手放輕些。","notes":[]},{"n":6,"t":"你們為何硬著心像埃及人和法老一樣呢？神在埃及人中間行奇事，埃及人豈不釋放以色列人，他們就去了嗎？","notes":[]},{"n":7,"t":"現在你們應當造一輛新車，將兩隻未曾負軛有乳的母牛套在車上，使牛犢回家去，離開母牛。","notes":[]},{"n":8,"t":"把耶和華的約櫃放在車上，將所獻賠罪的金物裝在匣子裏，放在櫃旁，將櫃送去。","notes":[]},{"n":9,"t":"你們要看看：車若直行以色列的境界到伯‧示麥去，這大災就是耶和華降在我們身上的；若不然，便可以知道不是他的手擊打我們，是我們偶然遇見的。」","notes":[]},{"n":10,"t":"非利士人就這樣行：將兩隻有乳的母牛套在車上，將牛犢關在家裏，","notes":[]},{"n":11,"t":"把耶和華的約櫃和裝金老鼠並金痔瘡像的匣子都放在車上。","notes":[]},{"n":12,"t":"牛直行大道，往伯‧示麥去，一面走一面叫，不偏左右。非利士的首領跟在後面，直到伯‧示麥的境界。","notes":[]},{"n":13,"t":"伯‧示麥人正在平原收割麥子，舉目看見約櫃，就歡喜了。","notes":[]},{"n":14,"t":"車到了伯‧示麥人約書亞的田間，就站住了。在那裏有一塊大磐石，他們把車劈了，將兩隻母牛獻給耶和華為燔祭。","notes":[]},{"n":15,"t":"利未人將耶和華的約櫃和裝金物的匣子拿下來，放在大磐石上。當日伯‧示麥人將燔祭和平安祭獻給耶和華。","notes":[]},{"n":16,"t":"非利士人的五個首領看見，當日就回以革倫去了。","notes":[]},{"n":17,"t":"非利士人獻給耶和華作賠罪的金痔瘡像，就是這些：一個是為亞實突，一個是為迦薩，一個是為亞實基倫，一個是為迦特，一個是為以革倫。","notes":[]},{"n":18,"t":"金老鼠的數目是照非利士五個首領的城邑，就是堅固的城邑和鄉村，以及大磐石。這磐石是放耶和華約櫃的，到今日還在伯‧示麥人約書亞的田間。","notes":[]},{"n":19,"t":"耶和華因伯‧示麥人擅觀他的約櫃，就擊殺了他們七十人；那時有五萬人在那裏。百姓因耶和華大大擊殺他們，就哀哭了。","notes":["原文是七十人加五萬人"],"heads":["約櫃在基列‧耶琳"]},{"n":20,"t":"伯‧示麥人說：「誰能在耶和華這聖潔的神面前侍立呢？這約櫃可以從我們這裏送到誰那裏去呢？」","notes":[]},{"n":21,"t":"於是打發人去見基列‧耶琳的居民，說：「非利士人將耶和華的約櫃送回來了，你們下來將約櫃接到你們那裏去吧！」","notes":[]}]},"7":{"heading":"撒母耳統治以色列","verses":[{"n":1,"t":"基列‧耶琳人就下來，將耶和華的約櫃接上去，放在山上亞比拿達的家中，分派他兒子以利亞撒看守耶和華的約櫃。","notes":[]},{"n":2,"t":"約櫃在基列‧耶琳許久。過了二十年，以色列全家都傾向耶和華。","notes":[]},{"n":3,"t":"撒母耳對以色列全家說：「你們若一心歸順耶和華，就要把外邦的神和亞斯她錄從你們中間除掉，專心歸向耶和華，單單地事奉他。他必救你們脫離非利士人的手。」","notes":[]},{"n":4,"t":"以色列人就除掉諸巴力和亞斯她錄，單單地事奉耶和華。","notes":[]},{"n":5,"t":"撒母耳說：「要使以色列眾人聚集在米斯巴，我好為你們禱告耶和華。」","notes":[]},{"n":6,"t":"他們就聚集在米斯巴，打水澆在耶和華面前，當日禁食，說：「我們得罪了耶和華。」於是撒母耳在米斯巴審判以色列人。","notes":[]},{"n":7,"t":"非利士人聽見以色列人聚集在米斯巴，非利士的首領就上來要攻擊以色列人。以色列人聽見，就懼怕非利士人。","notes":[]},{"n":8,"t":"以色列人對撒母耳說：「願你不住地為我們呼求耶和華－我們的神，救我們脫離非利士人的手。」","notes":[]},{"n":9,"t":"撒母耳就把一隻吃奶的羊羔獻與耶和華作全牲的燔祭，為以色列人呼求耶和華；耶和華就應允他。","notes":[]},{"n":10,"t":"撒母耳正獻燔祭的時候，非利士人前來要與以色列人爭戰。當日，耶和華大發雷聲，驚亂非利士人，他們就敗在以色列人面前。","notes":[]},{"n":11,"t":"以色列人從米斯巴出來，追趕非利士人，擊殺他們，直到伯‧甲的下邊。","notes":[]},{"n":12,"t":"撒母耳將一塊石頭立在米斯巴和善的中間，給石頭起名叫以便以謝，說：「到如今耶和華都幫助我們。」","notes":[]},{"n":13,"t":"從此，非利士人就被制伏，不敢再入以色列人的境內。撒母耳作士師的時候，耶和華的手攻擊非利士人。","notes":[]},{"n":14,"t":"非利士人所取以色列人的城邑，從以革倫直到迦特，都歸以色列人了。屬這些城的四境，以色列人也從非利士人手下收回。那時以色列人與亞摩利人和好。","notes":[]},{"n":15,"t":"撒母耳平生作以色列的士師。","notes":[]},{"n":16,"t":"他每年巡行到伯特利、吉甲、米斯巴，在這幾處審判以色列人。","notes":[]},{"n":17,"t":"隨後回到拉瑪，因為他的家在那裏；也在那裏審判以色列人，且為耶和華築了一座壇。","notes":[]}]},"8":{"heading":"以色列人要求立王","verses":[{"n":1,"t":"撒母耳年紀老邁，就立他兒子作以色列的士師。","notes":[]},{"n":2,"t":"長子名叫約珥，次子名叫亞比亞；他們在別是巴作士師。","notes":[]},{"n":3,"t":"他兒子不行他的道，貪圖財利，收受賄賂，屈枉正直。","notes":[]},{"n":4,"t":"以色列的長老都聚集，來到拉瑪見撒母耳，","notes":[]},{"n":5,"t":"對他說：「你年紀老邁了，你兒子不行你的道。現在求你為我們立一個王治理我們，像列國一樣。」","notes":[]},{"n":6,"t":"撒母耳不喜悅他們說「立一個王治理我們」，他就禱告耶和華。","notes":[]},{"n":7,"t":"耶和華對撒母耳說：「百姓向你說的一切話，你只管依從；因為他們不是厭棄你，乃是厭棄我，不要我作他們的王。","notes":[]},{"n":8,"t":"自從我領他們出埃及到如今，他們常常離棄我，事奉別神。現在他們向你所行的，是照他們素來所行的。","notes":[]},{"n":9,"t":"故此你要依從他們的話，只是當警戒他們，告訴他們將來那王怎樣管轄他們。」","notes":[]},{"n":10,"t":"撒母耳將耶和華的話都傳給求他立王的百姓，說：","notes":[]},{"n":11,"t":"「管轄你們的王必這樣行：他必派你們的兒子為他趕車、跟馬，奔走在車前；","notes":[]},{"n":12,"t":"又派他們作千夫長、五十夫長，為他耕種田地，收割莊稼，打造軍器和車上的器械；","notes":[]},{"n":13,"t":"必取你們的女兒為他製造香膏，做飯烤餅；","notes":[]},{"n":14,"t":"也必取你們最好的田地、葡萄園、橄欖園賜給他的臣僕。","notes":[]},{"n":15,"t":"你們的糧食和葡萄園所出的，他必取十分之一給他的太監和臣僕；","notes":[]},{"n":16,"t":"又必取你們的僕人婢女，健壯的少年人和你們的驢，供他的差役。","notes":[]},{"n":17,"t":"你們的羊群他必取十分之一，你們也必作他的僕人。","notes":[]},{"n":18,"t":"那時你們必因所選的王哀求耶和華，耶和華卻不應允你們。」","notes":[]},{"n":19,"t":"百姓竟不肯聽撒母耳的話，說：「不然！我們定要一個王治理我們，","notes":[]},{"n":20,"t":"使我們像列國一樣，有王治理我們，統領我們，為我們爭戰。」","notes":[]},{"n":21,"t":"撒母耳聽見百姓這一切話，就將這話陳明在耶和華面前。","notes":[]},{"n":22,"t":"耶和華對撒母耳說：「你只管依從他們的話，為他們立王。」撒母耳對以色列人說：「你們各歸各城去吧！」","notes":[]}]},"9":{"heading":"掃羅見撒母耳","verses":[{"n":1,"t":"有一個便雅憫人，名叫基士，是便雅憫人亞斐亞的玄孫，比歌拉的曾孫，洗羅的孫子，亞別的兒子，是個大能的勇士。","notes":["或譯：大財主"]},{"n":2,"t":"他有一個兒子，名叫掃羅，又健壯、又俊美，在以色列人中沒有一個能比他的；身體比眾民高過一頭。","notes":[]},{"n":3,"t":"掃羅的父親基士丟了幾頭驢，他就吩咐兒子掃羅說：「你帶一個僕人去尋找驢。」","notes":[]},{"n":4,"t":"掃羅就走過以法蓮山地，又過沙利沙地，都沒有找著；又過沙琳地，驢也不在那裏；又過便雅憫地，還沒有找著。","notes":[]},{"n":5,"t":"到了蘇弗地，掃羅對跟隨他的僕人說：「我們不如回去，恐怕我父親不為驢掛心，反為我們擔憂。」","notes":[]},{"n":6,"t":"僕人說：「這城裏有一位神人，是眾人所尊重的，凡他所說的全都應驗。我們不如往他那裏去，或者他能將我們當走的路指示我們。」","notes":[]},{"n":7,"t":"掃羅對僕人說：「我們若去，有甚麼可以送那人呢？我們囊中的食物都吃盡了，也沒有禮物可以送那神人，我們還有甚麼沒有？」","notes":[]},{"n":8,"t":"僕人回答掃羅說：「我手裏有銀子一舍客勒的四分之一，可以送那神人，請他指示我們當走的路。」（","notes":[]},{"n":9,"t":"從前以色列中，若有人去問神，就說：「我們問先見去吧！」現在稱為「先知」的，從前稱為「先見」。）","notes":[]},{"n":10,"t":"掃羅對僕人說：「你說的是，我們可以去。」於是他們往神人所住的城裏去了。","notes":[]},{"n":11,"t":"他們上坡要進城，就遇見幾個少年女子出來打水，問她們說：「先見在這裏沒有？」","notes":[]},{"n":12,"t":"女子回答說：「在這裏，他在你們前面。快去吧！他今日正到城裏，因為今日百姓要在邱壇獻祭。","notes":[]},{"n":13,"t":"在他還沒有上邱壇吃祭物之先，你們一進城必遇見他；因他未到，百姓不能吃，必等他先祝祭，然後請的客才吃。現在你們上去，這時候必遇見他。」","notes":[]},{"n":14,"t":"二人就上去；將進城的時候，撒母耳正迎著他們來，要上邱壇去。","notes":[]},{"n":15,"t":"掃羅未到的前一日，耶和華已經指示撒母耳說：","notes":[]},{"n":16,"t":"「明日這時候，我必使一個人從便雅憫地到你這裏來，你要膏他作我民以色列的君。他必救我民脫離非利士人的手；因我民的哀聲上達於我，我就眷顧他們。」","notes":[]},{"n":17,"t":"撒母耳看見掃羅的時候，耶和華對他說：「看哪，這人就是我對你所說的，他必治理我的民。」","notes":[]},{"n":18,"t":"掃羅在城門裏走到撒母耳跟前，說：「請告訴我，先見的寓所在哪裏？」","notes":[]},{"n":19,"t":"撒母耳回答說：「我就是先見。你在我前面上邱壇去，因為你們今日必與我同席；明日早晨我送你去，將你心裏的事都告訴你。","notes":[]},{"n":20,"t":"至於你前三日所丟的那幾頭驢，你心裏不必掛念，已經找著了。以色列眾人所仰慕的是誰呢？不是仰慕你和你父的全家嗎？」","notes":[]},{"n":21,"t":"掃羅說：「我不是以色列支派中至小的便雅憫人嗎？我家不是便雅憫支派中至小的家嗎？你為何對我說這樣的話呢？」","notes":[]},{"n":22,"t":"撒母耳領掃羅和他僕人進了客堂，使他們在請來的客中坐首位；客約有三十個人。","notes":[]},{"n":23,"t":"撒母耳對廚役說：「我交給你收存的那一分祭肉現在可以拿來。」","notes":[]},{"n":24,"t":"廚役就把收存的腿拿來，擺在掃羅面前，撒母耳說：「這是所留下的，放在你面前。吃吧！因我請百姓的時候，特意為你存留這肉到此時。」當日，掃羅就與撒母耳同席。","notes":[]},{"n":25,"t":"眾人從邱壇下來進城，撒母耳和掃羅在房頂上說話。","notes":[],"heads":["撒母耳膏掃羅作王"]},{"n":26,"t":"次日清早起來，黎明的時候，掃羅在房頂上。撒母耳呼叫他說：「起來吧，我好送你回去。」掃羅就起來，和撒母耳一同出去。","notes":[]},{"n":27,"t":"二人下到城角，撒母耳對掃羅說：「要吩咐僕人先走（僕人就先走了）；你且站在這裏，等我將神的話傳與你聽。」","notes":[]}]},"10":{"heading":"抽籤得掃羅為王","verses":[{"n":1,"t":"撒母耳拿瓶膏油倒在掃羅的頭上，與他親嘴，說：「這不是耶和華膏你作他產業的君嗎？","notes":[]},{"n":2,"t":"你今日與我離別之後，在便雅憫境內的泄撒，靠近拉結的墳墓，要遇見兩個人。他們必對你說：『你去找的那幾頭驢已經找著了。現在你父親不為驢掛心，反為你擔憂，說：我為兒子怎麼才好呢？』","notes":[]},{"n":3,"t":"你從那裏往前行，到了他泊的橡樹那裏，必遇見三個往伯特利去拜神的人：一個帶著三隻山羊羔，一個帶著三個餅，一個帶著一皮袋酒。","notes":[]},{"n":4,"t":"他們必問你安，給你兩個餅，你就從他們手中接過來。","notes":[]},{"n":5,"t":"此後你到神的山，在那裏有非利士人的防兵。你到了城的時候，必遇見一班先知從邱壇下來，前面有鼓瑟的、擊鼓的、吹笛的、彈琴的，他們都受感說話。","notes":[]},{"n":6,"t":"耶和華的靈必大大感動你，你就與他們一同受感說話；你要變為新人。","notes":[]},{"n":7,"t":"這兆頭臨到你，你就可以趁時而做，因為神與你同在。","notes":[]},{"n":8,"t":"你當在我以先下到吉甲，我也必下到那裏獻燔祭和平安祭。你要等候七日，等我到了那裏，指示你當行的事。」","notes":[]},{"n":9,"t":"掃羅轉身離別撒母耳，神就賜他一個新心。當日這一切兆頭都應驗了。","notes":[]},{"n":10,"t":"掃羅到了那山，有一班先知遇見他，神的靈大大感動他，他就在先知中受感說話。","notes":[]},{"n":11,"t":"素來認識掃羅的，看見他和先知一同受感說話，就彼此說：「基士的兒子遇見甚麼了？掃羅也列在先知中嗎？」","notes":[]},{"n":12,"t":"那地方有一個人說：「這些人的父親是誰呢？」此後有句俗語說：「掃羅也列在先知中嗎？」","notes":[]},{"n":13,"t":"掃羅受感說話已畢，就上邱壇去了。","notes":[]},{"n":14,"t":"掃羅的叔叔問掃羅和他僕人說：「你們往哪裏去了？」回答說：「找驢去了。我們見沒有驢，就到了撒母耳那裏。」","notes":[]},{"n":15,"t":"掃羅的叔叔說：「請將撒母耳向你們所說的話告訴我。」","notes":[]},{"n":16,"t":"掃羅對他叔叔說：「他明明地告訴我們驢已經找著了。」至於撒母耳所說的國事，掃羅卻沒有告訴叔叔。","notes":[]},{"n":17,"t":"撒母耳將百姓招聚到米斯巴耶和華那裏，","notes":[]},{"n":18,"t":"對他們說：「耶和華－以色列的神如此說：『我領你們以色列人出埃及，救你們脫離埃及人的手，又救你們脫離欺壓你們各國之人的手。』","notes":[]},{"n":19,"t":"你們今日卻厭棄了救你們脫離一切災難的神，說：『求你立一個王治理我們。』現在你們應當按著支派、宗族都站在耶和華面前。」","notes":[]},{"n":20,"t":"於是，撒母耳使以色列眾支派近前來掣籤，就掣出便雅憫支派來；","notes":[]},{"n":21,"t":"又使便雅憫支派按著宗族近前來，就掣出瑪特利族，從其中又掣出基士的兒子掃羅。眾人尋找他卻尋不著，","notes":[]},{"n":22,"t":"就問耶和華說：「那人到這裏來了沒有？」耶和華說：「他藏在器具中了。」","notes":[]},{"n":23,"t":"眾人就跑去從那裏領出他來。他站在百姓中間，身體比眾民高過一頭。","notes":[]},{"n":24,"t":"撒母耳對眾民說：「你們看耶和華所揀選的人，眾民中有可比他的嗎？」眾民就大聲歡呼說：「願王萬歲！」","notes":[]},{"n":25,"t":"撒母耳將國法對百姓說明，又記在書上，放在耶和華面前，然後遣散眾民，各回各家去了。","notes":[]},{"n":26,"t":"掃羅往基比亞回家去，有神感動的一群人跟隨他。","notes":[]},{"n":27,"t":"但有些匪徒說：「這人怎能救我們呢？」就藐視他，沒有送他禮物；掃羅卻不理會。","notes":[]}]},"11":{"heading":"掃羅擊敗亞捫人","verses":[{"n":1,"t":"亞捫人的王拿轄上來，對著基列‧雅比安營。雅比眾人對拿轄說：「你與我們立約，我們就服事你。」","notes":[]},{"n":2,"t":"亞捫人拿轄說：「你們若由我剜出你們各人的右眼，以此凌辱以色列眾人，我就與你們立約。」","notes":[]},{"n":3,"t":"雅比的長老對他說：「求你寬容我們七日，等我們打發人往以色列的全境去；若沒有人救我們，我們就出來歸順你。」","notes":[]},{"n":4,"t":"使者到了掃羅住的基比亞，將這話說給百姓聽，百姓就都放聲而哭。","notes":[]},{"n":5,"t":"掃羅正從田間趕牛回來，問說：「百姓為甚麼哭呢？」眾人將雅比人的話告訴他。","notes":[]},{"n":6,"t":"掃羅聽見這話，就被神的靈大大感動，甚是發怒。","notes":[]},{"n":7,"t":"他將一對牛切成塊子，託付使者傳送以色列的全境，說：「凡不出來跟隨掃羅和撒母耳的，也必這樣切開他的牛。」於是耶和華使百姓懼怕，他們就都出來，如同一人。","notes":[]},{"n":8,"t":"掃羅在比色數點他們：以色列人有三十萬，猶大人有三萬。","notes":[]},{"n":9,"t":"眾人對那使者說：「你們要回覆基列‧雅比人說，明日太陽近午的時候，你們必得解救。」使者回去告訴雅比人，他們就歡喜了。","notes":[]},{"n":10,"t":"於是雅比人對亞捫人說：「明日我們出來歸順你們，你們可以隨意待我們。」","notes":[]},{"n":11,"t":"第二日，掃羅將百姓分為三隊，在晨更的時候入了亞捫人的營，擊殺他們直到太陽近午，剩下的人都逃散，沒有二人同在一處的。","notes":[]},{"n":12,"t":"百姓對撒母耳說：「那說『掃羅豈能管理我們』的是誰呢？可以將他交出來，我們好殺死他。」","notes":[]},{"n":13,"t":"掃羅說：「今日耶和華在以色列中施行拯救，所以不可殺人。」","notes":[]},{"n":14,"t":"撒母耳對百姓說：「我們要往吉甲去，在那裏立國。」","notes":[]},{"n":15,"t":"眾百姓就到了吉甲那裏，在耶和華面前立掃羅為王，又在耶和華面前獻平安祭。掃羅和以色列眾人大大歡喜。","notes":[]}]},"12":{"heading":"撒母耳臨別贈言","verses":[{"n":1,"t":"撒母耳對以色列眾人說：「你們向我所求的，我已應允了，為你們立了一個王；","notes":[]},{"n":2,"t":"現在有這王在你們前面行。我已年老髮白，我的兒子都在你們這裏。我從幼年直到今日都在你們前面行。","notes":[]},{"n":3,"t":"我在這裏，你們要在耶和華和他的受膏者面前給我作見證。我奪過誰的牛，搶過誰的驢，欺負過誰，虐待過誰，從誰手裏受過賄賂因而眼瞎呢？若有，我必償還。」","notes":[]},{"n":4,"t":"眾人說：「你未曾欺負我們，虐待我們，也未曾從誰手裏受過甚麼。」","notes":[]},{"n":5,"t":"撒母耳對他們說：「你們在我手裏沒有找著甚麼，有耶和華和他的受膏者今日為證。」他們說：「願他為證。」","notes":[]},{"n":6,"t":"撒母耳對百姓說：「從前立摩西、亞倫，又領你們列祖出埃及地的是耶和華。","notes":[]},{"n":7,"t":"現在你們要站住，等我在耶和華面前對你們講論耶和華向你們和你們列祖所行一切公義的事。","notes":[]},{"n":8,"t":"從前雅各到了埃及，後來你們列祖呼求耶和華，耶和華就差遣摩西、亞倫領你們列祖出埃及，使他們在這地方居住。","notes":[]},{"n":9,"t":"他們卻忘記耶和華－他們的神，他就把他們付與夏瑣將軍西西拉的手裏，和非利士人並摩押王的手裏。於是這些人常來攻擊他們。","notes":[]},{"n":10,"t":"他們就呼求耶和華說：『我們離棄耶和華，事奉巴力和亞斯她錄，是有罪了。現在求你救我們脫離仇敵的手，我們必事奉你。』","notes":[]},{"n":11,"t":"耶和華就差遣耶路‧巴力、比但、耶弗他、撒母耳救你們脫離四圍仇敵的手，你們才安然居住。","notes":[]},{"n":12,"t":"你們見亞捫人的王拿轄來攻擊你們，就對我說：『我們定要一個王治理我們。』其實耶和華－你們的神是你們的王。","notes":[]},{"n":13,"t":"現在，你們所求所選的王在這裏。看哪，耶和華已經為你們立王了。","notes":[]},{"n":14,"t":"你們若敬畏耶和華，事奉他，聽從他的話，不違背他的命令，你們和治理你們的王也都順從耶和華－你們的神就好了。","notes":[]},{"n":15,"t":"倘若不聽從耶和華的話，違背他的命令，耶和華的手必攻擊你們，像從前攻擊你們列祖一樣。","notes":[]},{"n":16,"t":"現在你們要站住，看耶和華在你們眼前要行一件大事。","notes":[]},{"n":17,"t":"這不是割麥子的時候嗎？我求告耶和華，他必打雷降雨，使你們又知道又看出，你們求立王的事是在耶和華面前犯大罪了。」","notes":[]},{"n":18,"t":"於是撒母耳求告耶和華，耶和華就在這日打雷降雨，眾民便甚懼怕耶和華和撒母耳。","notes":[]},{"n":19,"t":"眾民對撒母耳說：「求你為僕人們禱告耶和華－你的神，免得我們死亡；因為我們求立王的事正是罪上加罪了。」","notes":[]},{"n":20,"t":"撒母耳對百姓說：「不要懼怕！你們雖然行了這惡，卻不要偏離耶和華，只要盡心事奉他。","notes":[]},{"n":21,"t":"若偏離耶和華去順從那不能救人的虛神是無益的。","notes":[]},{"n":22,"t":"耶和華既喜悅選你們作他的子民，就必因他的大名不撇棄你們。","notes":[]},{"n":23,"t":"至於我，斷不停止為你們禱告，以致得罪耶和華。我必以善道正路指教你們。","notes":[]},{"n":24,"t":"只要你們敬畏耶和華，誠誠實實地盡心事奉他，想念他向你們所行的事何等大。","notes":[]},{"n":25,"t":"你們若仍然作惡，你們和你們的王必一同滅亡。」","notes":[]}]},"13":{"heading":"與非利士人爭戰","verses":[{"n":1,"t":"掃羅登基年四十歲；作以色列王二年的時候，","notes":[]},{"n":2,"t":"就從以色列中揀選了三千人：二千跟隨掃羅在密抹和伯特利山，一千跟隨約拿單在便雅憫的基比亞；其餘的人掃羅都打發各回各家去了。","notes":[]},{"n":3,"t":"約拿單攻擊在迦巴的非利士人的防營，非利士人聽見了。掃羅就在遍地吹角，意思說，要使希伯來人聽見。","notes":[]},{"n":4,"t":"以色列眾人聽見掃羅攻擊非利士人的防營，又聽見以色列人為非利士人所憎惡，就跟隨掃羅聚集在吉甲。","notes":[]},{"n":5,"t":"非利士人聚集，要與以色列人爭戰，有車三萬輛，馬兵六千，步兵像海邊的沙那樣多，就上來在伯‧亞文東邊的密抹安營。","notes":[]},{"n":6,"t":"以色列百姓見自己危急窘迫，就藏在山洞、叢林、石穴、隱密處，和坑中。","notes":[]},{"n":7,"t":"有些希伯來人過了約旦河，逃到迦得和基列地。掃羅還是在吉甲，百姓都戰戰兢兢地跟隨他。","notes":[]},{"n":8,"t":"掃羅照著撒母耳所定的日期等了七日。撒母耳還沒有來到吉甲，百姓也離開掃羅散去了。","notes":[]},{"n":9,"t":"掃羅說：「把燔祭和平安祭帶到我這裏來。」掃羅就獻上燔祭。","notes":[]},{"n":10,"t":"剛獻完燔祭，撒母耳就到了。掃羅出去迎接他，要問他好。","notes":[]},{"n":11,"t":"撒母耳說：「你做的是甚麼事呢？」掃羅說：「因為我見百姓離開我散去，你也不照所定的日期來到，而且非利士人聚集在密抹。","notes":[]},{"n":12,"t":"所以我心裏說：恐怕我沒有禱告耶和華。非利士人下到吉甲攻擊我，我就勉強獻上燔祭。」","notes":[]},{"n":13,"t":"撒母耳對掃羅說：「你做了糊塗事了，沒有遵守耶和華－你神所吩咐你的命令。若遵守，耶和華必在以色列中堅立你的王位，直到永遠。","notes":[]},{"n":14,"t":"現在你的王位必不長久。耶和華已經尋著一個合他心意的人，立他作百姓的君，因為你沒有遵守耶和華所吩咐你的。」","notes":[]},{"n":15,"t":"撒母耳就起來，從吉甲上到便雅憫的基比亞。掃羅數點跟隨他的，約有六百人。","notes":[]},{"n":16,"t":"掃羅和他兒子約拿單，並跟隨他們的人，都住在便雅憫的迦巴；但非利士人安營在密抹。","notes":[]},{"n":17,"t":"有掠兵從非利士營中出來，分為三隊：一隊往俄弗拉向書亞地去，","notes":[]},{"n":18,"t":"一隊往伯‧和崙去，一隊往洗波音谷對面的地境向曠野去。","notes":[]},{"n":19,"t":"那時，以色列全地沒有一個鐵匠；因為非利士人說，恐怕希伯來人製造刀槍。","notes":[]},{"n":20,"t":"以色列人要磨鋤、犂、斧、鏟，就下到非利士人那裏去磨。","notes":[]},{"n":21,"t":"但有銼可以銼鏟、犂、三齒叉、斧子，並趕牛錐。","notes":[]},{"n":22,"t":"所以到了爭戰的日子，跟隨掃羅和約拿單的人沒有一個手裏有刀有槍的，惟獨掃羅和他兒子約拿單有。","notes":[]},{"n":23,"t":"非利士人的一隊防兵到了密抹的隘口。","notes":[]}]},"14":{"heading":"約拿單的勇敢戰績","verses":[{"n":1,"t":"有一日，掃羅的兒子約拿單對拿他兵器的少年人說：「我們不如過到那邊，到非利士人的防營那裏去。」但他沒有告訴父親。","notes":[]},{"n":2,"t":"掃羅在基比亞的儘邊，坐在米磯崙的石榴樹下，跟隨他的約有六百人。","notes":[]},{"n":3,"t":"在那裏有亞希突的兒子亞希亞，穿著以弗得。（亞希突是以迦博的哥哥，非尼哈的兒子，以利的孫子。以利從前在示羅作耶和華的祭司。）約拿單去了，百姓卻不知道。","notes":[]},{"n":4,"t":"約拿單要從隘口過到非利士防營那裏去。這隘口兩邊各有一個山峰：一名播薛，一名西尼；","notes":[]},{"n":5,"t":"一峰向北，與密抹相對，一峰向南，與迦巴相對。","notes":[]},{"n":6,"t":"約拿單對拿兵器的少年人說：「我們不如過到未受割禮人的防營那裏去，或者耶和華為我們施展能力；因為耶和華使人得勝，不在乎人多人少。」","notes":[]},{"n":7,"t":"拿兵器的對他說：「隨你的心意行吧。你可以上去，我必跟隨你，與你同心。」","notes":[]},{"n":8,"t":"約拿單說：「我們要過到那些人那裏去，使他們看見我們。","notes":[]},{"n":9,"t":"他們若對我們說：『你們站住，等我們到你們那裏去』，我們就站住，不上他們那裏去。","notes":[]},{"n":10,"t":"他們若說：『你們上到我們這裏來』，這話就是我們的證據；我們便上去，因為耶和華將他們交在我們手裏了。」","notes":[]},{"n":11,"t":"二人就使非利士的防兵看見。非利士人說：「希伯來人從所藏的洞穴裏出來了！」","notes":[]},{"n":12,"t":"防兵對約拿單和拿兵器的人說：「你們上到這裏來，我們有一件事指示你們。」約拿單就對拿兵器的人說：「你跟隨我上去，因為耶和華將他們交在以色列人手裏了。」","notes":[]},{"n":13,"t":"約拿單就爬上去，拿兵器的人跟隨他。約拿單殺倒非利士人，拿兵器的人也隨著殺他們。","notes":[]},{"n":14,"t":"約拿單和拿兵器的人起頭所殺的約有二十人，都在一畝地的半犂溝之內。","notes":[]},{"n":15,"t":"於是在營中、在田野、在眾民內都有戰兢，防兵和掠兵也都戰兢，地也震動，戰兢之勢甚大。","notes":[]},{"n":16,"t":"在便雅憫的基比亞，掃羅的守望兵看見非利士的軍眾潰散，四圍亂竄。","notes":[],"heads":["非利士人敗退"]},{"n":17,"t":"掃羅就對跟隨他的民說：「你們查點查點，看從我們這裏出去的是誰？」他們一查點，就知道約拿單和拿兵器的人沒有在這裏。","notes":[]},{"n":18,"t":"那時神的約櫃在以色列人那裏。掃羅對亞希亞說：「你將神的約櫃運了來。」","notes":[]},{"n":19,"t":"掃羅正與祭司說話的時候，非利士營中的喧嚷越發大了；掃羅就對祭司說：「停手吧！」","notes":[]},{"n":20,"t":"掃羅和跟隨他的人都聚集，來到戰場，看見非利士人用刀互相擊殺，大大惶亂。","notes":[]},{"n":21,"t":"從前由四方來跟隨非利士軍的希伯來人現在也轉過來，幫助跟隨掃羅和約拿單的以色列人了。","notes":[]},{"n":22,"t":"那藏在以法蓮山地的以色列人聽說非利士人逃跑，就出來緊緊地追殺他們。","notes":[]},{"n":23,"t":"那日，耶和華使以色列人得勝，一直戰到伯‧亞文。","notes":[]},{"n":24,"t":"掃羅叫百姓起誓說，凡不等到晚上向敵人報完了仇吃甚麼的，必受咒詛。因此這日百姓沒有吃甚麼，就極其困憊。","notes":[],"heads":["戰後發生的事件"]},{"n":25,"t":"眾民進入樹林，見有蜜在地上。","notes":[]},{"n":26,"t":"他們進了樹林，見有蜜流下來，卻沒有人敢用手取蜜入口，因為他們怕那誓言。","notes":[]},{"n":27,"t":"約拿單沒有聽見他父親叫百姓起誓，所以伸手中的杖，用杖頭蘸在蜂房裏，轉手送入口內，眼睛就明亮了。","notes":[]},{"n":28,"t":"百姓中有一人對他說：「你父親曾叫百姓嚴嚴地起誓說，今日吃甚麼的，必受咒詛；因此百姓就疲乏了。」","notes":[]},{"n":29,"t":"約拿單說：「我父親連累你們了。你看，我嘗了這一點蜜，眼睛就明亮了。","notes":[]},{"n":30,"t":"今日百姓若任意吃了從仇敵所奪的物，擊殺的非利士人豈不更多嗎？」","notes":[]},{"n":31,"t":"這日，以色列人擊殺非利士人，從密抹直到亞雅崙。百姓甚是疲乏，","notes":[]},{"n":32,"t":"就急忙將所奪的牛羊和牛犢宰於地上，肉還帶血就吃了。","notes":[]},{"n":33,"t":"有人告訴掃羅說：「百姓吃帶血的肉，得罪耶和華了。」掃羅說：「你們有罪了，今日要將大石頭滾到我這裏來。」","notes":[]},{"n":34,"t":"掃羅又說：「你們散在百姓中，對他們說，你們各人將牛羊牽到我這裏來宰了吃，不可吃帶血的肉得罪耶和華。」這夜，百姓就把牛羊牽到那裏宰了。","notes":[]},{"n":35,"t":"掃羅為耶和華築了一座壇，這是他初次為耶和華築的壇。","notes":[]},{"n":36,"t":"掃羅說：「我們不如夜裏下去追趕非利士人，搶掠他們，直到天亮，不留他們一人。」眾民說：「你看怎樣好就去行吧！」祭司說：「我們先當親近神。」","notes":[]},{"n":37,"t":"掃羅求問神說：「我下去追趕非利士人可以不可以？你將他們交在以色列人手裏不交？」這日神沒有回答他。","notes":[]},{"n":38,"t":"掃羅說：「你們百姓中的長老都上這裏來，查明今日是誰犯了罪。","notes":[]},{"n":39,"t":"我指著救以色列－永生的耶和華起誓，就是我兒子約拿單犯了罪，他也必死。」但百姓中無一人回答他。","notes":[]},{"n":40,"t":"掃羅就對以色列眾人說：「你們站在一邊，我與我兒子約拿單也站在一邊。」百姓對掃羅說：「你看怎樣好就去行吧！」","notes":[]},{"n":41,"t":"掃羅禱告耶和華－以色列的神說：「求你指示實情。」於是掣籤掣出掃羅和約拿單來；百姓盡都無事。","notes":[]},{"n":42,"t":"掃羅說：「你們再掣籤，看是我，是我兒子約拿單」，就掣出約拿單來。","notes":[]},{"n":43,"t":"掃羅對約拿單說：「你告訴我，你做了甚麼事？」約拿單說：「我實在以手裏的杖，用杖頭蘸了一點蜜嘗了一嘗。這樣我就死嗎？」","notes":["或譯：吧！"]},{"n":44,"t":"掃羅說：「約拿單哪，你定要死！若不然，願神重重地降罰與我。」","notes":[]},{"n":45,"t":"百姓對掃羅說：「約拿單在以色列人中這樣大行拯救，豈可使他死呢？斷乎不可！我們指著永生的耶和華起誓，連他的一根頭髮也不可落地，因為他今日與神一同做事。」於是百姓救約拿單免了死亡。","notes":[]},{"n":46,"t":"掃羅回去，不追趕非利士人；非利士人也回本地去了。","notes":[]},{"n":47,"t":"掃羅執掌以色列的國權，常常攻擊他四圍的一切仇敵，就是摩押人、亞捫人、以東人，和瑣巴諸王，並非利士人。他無論往何處去，都打敗仇敵。","notes":[],"heads":["掃羅的王權和家眷"]},{"n":48,"t":"掃羅奮勇攻擊亞瑪力人，救了以色列人脫離搶掠他們之人的手。","notes":[]},{"n":49,"t":"掃羅的兒子是約拿單、亦施韋、麥基舒亞。他的兩個女兒：長女名米拉，次女名米甲。","notes":[]},{"n":50,"t":"掃羅的妻名叫亞希暖，是亞希瑪斯的女兒。掃羅的元帥名叫押尼珥，是尼珥的兒子；尼珥是掃羅的叔叔。","notes":[]},{"n":51,"t":"掃羅的父親基士，押尼珥的父親尼珥，都是亞別的兒子。","notes":[]},{"n":52,"t":"掃羅平生常與非利士人大大爭戰。掃羅遇見有能力的人或勇士，都招募了來跟隨他。","notes":[]}]},"15":{"heading":"與亞瑪力人爭戰","verses":[{"n":1,"t":"撒母耳對掃羅說：「耶和華差遣我膏你為王，治理他的百姓以色列；所以你當聽從耶和華的話。","notes":[]},{"n":2,"t":"萬軍之耶和華如此說：『以色列人出埃及的時候，在路上亞瑪力人怎樣待他們，怎樣抵擋他們，我都沒忘。","notes":[]},{"n":3,"t":"現在你要去擊打亞瑪力人，滅盡他們所有的，不可憐惜他們，將男女、孩童、吃奶的，並牛、羊、駱駝，和驢盡行殺死。』」","notes":[]},{"n":4,"t":"於是掃羅招聚百姓在提拉因，數點他們，共有步兵二十萬，另有猶大人一萬。","notes":[]},{"n":5,"t":"掃羅到了亞瑪力的京城，在谷中設下埋伏。","notes":[]},{"n":6,"t":"掃羅對基尼人說：「你們離開亞瑪力人下去吧，恐怕我將你們和亞瑪力人一同殺滅；因為以色列人出埃及的時候，你們曾恩待他們。」於是基尼人離開亞瑪力人去了。","notes":[]},{"n":7,"t":"掃羅擊打亞瑪力人，從哈腓拉直到埃及前的書珥，","notes":[]},{"n":8,"t":"生擒了亞瑪力王亞甲，用刀殺盡亞瑪力的眾民。","notes":[]},{"n":9,"t":"掃羅和百姓卻憐惜亞甲，也愛惜上好的牛、羊、牛犢、羊羔，並一切美物，不肯滅絕。凡下賤瘦弱的，盡都殺了。","notes":[]},{"n":10,"t":"耶和華的話臨到撒母耳說：","notes":[],"heads":["掃羅被廢"]},{"n":11,"t":"「我立掃羅為王，我後悔了；因為他轉去不跟從我，不遵守我的命令。」撒母耳便甚憂愁，終夜哀求耶和華。","notes":[]},{"n":12,"t":"撒母耳清早起來，迎接掃羅。有人告訴撒母耳說：「掃羅到了迦密，在那裏立了紀念碑，又轉身下到吉甲。」","notes":[]},{"n":13,"t":"撒母耳到了掃羅那裏，掃羅對他說：「願耶和華賜福與你，耶和華的命令我已遵守了。」","notes":[]},{"n":14,"t":"撒母耳說：「我耳中聽見有羊叫、牛鳴，是從哪裏來的呢？」","notes":[]},{"n":15,"t":"掃羅說：「這是百姓從亞瑪力人那裏帶來的；因為他們愛惜上好的牛羊，要獻與耶和華－你的神；其餘的，我們都滅盡了。」","notes":[]},{"n":16,"t":"撒母耳對掃羅說：「你住口吧！等我將耶和華昨夜向我所說的話告訴你。」掃羅說：「請講。」","notes":[]},{"n":17,"t":"撒母耳對掃羅說：「從前你雖然以自己為小，豈不是被立為以色列支派的元首嗎？耶和華膏你作以色列的王。","notes":[]},{"n":18,"t":"耶和華差遣你，吩咐你說，你去擊打那些犯罪的亞瑪力人，將他們滅絕淨盡。","notes":[]},{"n":19,"t":"你為何沒有聽從耶和華的命令，急忙擄掠財物，行耶和華眼中看為惡的事呢？」","notes":[]},{"n":20,"t":"掃羅對撒母耳說：「我實在聽從了耶和華的命令，行了耶和華所差遣我行的路，擒了亞瑪力王亞甲來，滅盡了亞瑪力人。","notes":[]},{"n":21,"t":"百姓卻在所當滅的物中，取了最好的牛羊，要在吉甲獻與耶和華－你的神。」","notes":[]},{"n":22,"t":"撒母耳說：耶和華喜悅燔祭和平安祭，豈如喜悅人聽從他的話呢？聽命勝於獻祭；順從勝於公羊的脂油。","notes":[]},{"n":23,"t":"悖逆的罪與行邪術的罪相等；頑梗的罪與拜虛神和偶像的罪相同。你既厭棄耶和華的命令，耶和華也厭棄你作王。","notes":[]},{"n":24,"t":"掃羅對撒母耳說：「我有罪了，我因懼怕百姓，聽從他們的話，就違背了耶和華的命令和你的言語。","notes":[],"heads":["掃羅認罪"]},{"n":25,"t":"現在求你赦免我的罪，同我回去，我好敬拜耶和華。」","notes":[]},{"n":26,"t":"撒母耳對掃羅說：「我不同你回去；因為你厭棄耶和華的命令，耶和華也厭棄你作以色列的王。」","notes":[]},{"n":27,"t":"撒母耳轉身要走，掃羅就扯住他外袍的衣襟，衣襟就撕斷了。","notes":[]},{"n":28,"t":"撒母耳對他說：「如此，今日耶和華使以色列國與你斷絕，將這國賜與比你更好的人。","notes":[]},{"n":29,"t":"以色列的大能者必不致說謊，也不致後悔；因為他迥非世人，決不後悔。」","notes":[]},{"n":30,"t":"掃羅說：「我有罪了，雖然如此，求你在我百姓的長老和以色列人面前抬舉我，同我回去，我好敬拜耶和華－你的神。」","notes":[]},{"n":31,"t":"於是撒母耳轉身跟隨掃羅回去，掃羅就敬拜耶和華。","notes":[]},{"n":32,"t":"撒母耳說：「要把亞瑪力王亞甲帶到我這裏來。」亞甲就歡歡喜喜地來到他面前，心裏說，死亡的苦難必定過去了。","notes":[]},{"n":33,"t":"撒母耳說：「你既用刀使婦人喪子，這樣，你母親在婦人中也必喪子。」於是，撒母耳在吉甲耶和華面前將亞甲殺死。","notes":[]},{"n":34,"t":"撒母耳回了拉瑪。掃羅上他所住的基比亞，回自己的家去了。","notes":[]},{"n":35,"t":"撒母耳直到死的日子，再沒有見掃羅；但撒母耳為掃羅悲傷，是因耶和華後悔立他為以色列的王。","notes":[]}]},"16":{"heading":"大衛被膏立為王","verses":[{"n":1,"t":"耶和華對撒母耳說：「我既厭棄掃羅作以色列的王，你為他悲傷要到幾時呢？你將膏油盛滿了角，我差遣你往伯利恆人耶西那裏去；因為我在他眾子之內，預定一個作王的。」","notes":[]},{"n":2,"t":"撒母耳說：「我怎能去呢？掃羅若聽見，必要殺我。」耶和華說：「你可以帶一隻牛犢去，就說：『我來是要向耶和華獻祭。』","notes":[]},{"n":3,"t":"你要請耶西來吃祭肉，我就指示你所當行的事。我所指給你的人，你要膏他。」","notes":[]},{"n":4,"t":"撒母耳就照耶和華的話去行。到了伯利恆，那城裏的長老都戰戰兢兢地出來迎接他，問他說：「你是為平安來的嗎？」","notes":[]},{"n":5,"t":"他說：「為平安來的，我是給耶和華獻祭。你們當自潔，來與我同吃祭肉。」撒母耳就使耶西和他眾子自潔，請他們來吃祭肉。","notes":[]},{"n":6,"t":"他們來的時候，撒母耳看見以利押，就心裏說，耶和華的受膏者必定在他面前。","notes":[]},{"n":7,"t":"耶和華卻對撒母耳說：「不要看他的外貌和他身材高大，我不揀選他。因為，耶和華不像人看人：人是看外貌；耶和華是看內心。」","notes":[]},{"n":8,"t":"耶西叫亞比拿達從撒母耳面前經過，撒母耳說：「耶和華也不揀選他。」","notes":[]},{"n":9,"t":"耶西又叫沙瑪從撒母耳面前經過，撒母耳說：「耶和華也不揀選他。」","notes":[]},{"n":10,"t":"耶西叫他七個兒子都從撒母耳面前經過，撒母耳說：「這都不是耶和華所揀選的。」","notes":[]},{"n":11,"t":"撒母耳對耶西說：「你的兒子都在這裏嗎？」他回答說：「還有個小的，現在放羊。」撒母耳對耶西說：「你打發人去叫他來；他若不來，我們必不坐席。」","notes":[]},{"n":12,"t":"耶西就打發人去叫了他來。他面色光紅，雙目清秀，容貌俊美。耶和華說：「這就是他，你起來膏他。」","notes":[]},{"n":13,"t":"撒母耳就用角裏的膏油，在他諸兄中膏了他。從這日起，耶和華的靈就大大感動大衛。撒母耳起身回拉瑪去了。","notes":[]},{"n":14,"t":"耶和華的靈離開掃羅，有惡魔從耶和華那裏來擾亂他。","notes":[],"heads":["大衛在掃羅的宮裏"]},{"n":15,"t":"掃羅的臣僕對他說：「現在有惡魔從神那裏來擾亂你。","notes":[]},{"n":16,"t":"我們的主可以吩咐面前的臣僕，找一個善於彈琴的來，等神那裏來的惡魔臨到你身上的時候，使他用手彈琴，你就好了。」","notes":[]},{"n":17,"t":"掃羅對臣僕說：「你們可以為我找一個善於彈琴的，帶到我這裏來。」","notes":[]},{"n":18,"t":"其中有一個少年人說：「我曾見伯利恆人耶西的一個兒子善於彈琴，是大有勇敢的戰士，說話合宜，容貌俊美，耶和華也與他同在。」","notes":[]},{"n":19,"t":"於是掃羅差遣使者去見耶西，說：「請你打發你放羊的兒子大衛到我這裏來。」","notes":[]},{"n":20,"t":"耶西就把幾個餅和一皮袋酒，並一隻山羊羔，都馱在驢上，交給他兒子大衛，送與掃羅。","notes":[]},{"n":21,"t":"大衛到了掃羅那裏，就侍立在掃羅面前。掃羅甚喜愛他，他就作了掃羅拿兵器的人。","notes":[]},{"n":22,"t":"掃羅差遣人去見耶西，說：「求你容大衛侍立在我面前，因為他在我眼前蒙了恩。」","notes":[]},{"n":23,"t":"從神那裏來的惡魔臨到掃羅身上的時候，大衛就拿琴，用手而彈，掃羅便舒暢爽快，惡魔離了他。","notes":[]}]},"17":{"heading":"歌利亞向以色列軍挑戰","verses":[{"n":1,"t":"非利士人招聚他們的軍旅，要來爭戰；聚集在屬猶大的梭哥，安營在梭哥和亞西加中間的以弗‧大憫。","notes":[]},{"n":2,"t":"掃羅和以色列人也聚集，在以拉谷安營，擺列隊伍，要與非利士人打仗。","notes":[]},{"n":3,"t":"非利士人站在這邊山上，以色列人站在那邊山上，當中有谷。","notes":[]},{"n":4,"t":"從非利士營中出來一個討戰的人，名叫歌利亞，是迦特人，身高六肘零一虎口；","notes":[]},{"n":5,"t":"頭戴銅盔，身穿鎧甲，甲重五千舍客勒；","notes":[]},{"n":6,"t":"腿上有銅護膝，兩肩之中背負銅戟；","notes":[]},{"n":7,"t":"槍桿粗如織布的機軸，鐵槍頭重六百舍客勒。有一個拿盾牌的人在他前面走。","notes":[]},{"n":8,"t":"歌利亞對著以色列的軍隊站立，呼叫說：「你們出來擺列隊伍做甚麼呢？我不是非利士人嗎？你們不是掃羅的僕人嗎？可以從你們中間揀選一人，使他下到我這裏來。","notes":[]},{"n":9,"t":"他若能與我戰鬥，將我殺死，我們就作你們的僕人；我若勝了他，將他殺死，你們就作我們的僕人，服事我們。」","notes":[]},{"n":10,"t":"那非利士人又說：「我今日向以色列人的軍隊罵陣。你們叫一個人出來，與我戰鬥。」","notes":[]},{"n":11,"t":"掃羅和以色列眾人聽見非利士人的這些話，就驚惶，極其害怕。","notes":[]},{"n":12,"t":"大衛是猶大伯利恆的以法他人耶西的兒子。耶西有八個兒子。當掃羅的時候，耶西已經老邁。","notes":[],"heads":["大衛在掃羅的營中"]},{"n":13,"t":"耶西的三個大兒子跟隨掃羅出征。這出征的三個兒子：長子名叫以利押，次子名叫亞比拿達，三子名叫沙瑪。","notes":[]},{"n":14,"t":"大衛是最小的；那三個大兒子跟隨掃羅。","notes":[]},{"n":15,"t":"大衛有時離開掃羅，回伯利恆放他父親的羊。","notes":[]},{"n":16,"t":"那非利士人早晚都出來站著，如此四十日。","notes":[]},{"n":17,"t":"一日，耶西對他兒子大衛說：「你拿一伊法烘了的穗子和十個餅，速速地送到營裏去，交給你哥哥們；","notes":[]},{"n":18,"t":"再拿這十塊奶餅，送給他們的千夫長，且問你哥哥們好，向他們要一封信來。」","notes":[]},{"n":19,"t":"掃羅與大衛的三個哥哥和以色列眾人，在以拉谷與非利士人打仗。","notes":[]},{"n":20,"t":"大衛早晨起來，將羊交託一個看守的人，照著他父親所吩咐的話，帶著食物去了。到了輜重營，軍兵剛出到戰場，吶喊要戰。","notes":[]},{"n":21,"t":"以色列人和非利士人都擺列隊伍，彼此相對。","notes":[]},{"n":22,"t":"大衛把他帶來的食物留在看守物件人的手下，跑到戰場，問他哥哥們安。","notes":[]},{"n":23,"t":"與他們說話的時候，那討戰的，就是屬迦特的非利士人歌利亞，從非利士隊中出來，說從前所說的話；大衛都聽見了。","notes":[]},{"n":24,"t":"以色列眾人看見那人，就逃跑，極其害怕。","notes":[]},{"n":25,"t":"以色列人彼此說：「這上來的人你看見了嗎？他上來是要向以色列人罵陣。若有能殺他的，王必賞賜他大財，將自己的女兒給他為妻，並在以色列人中免他父家納糧當差。」","notes":[]},{"n":26,"t":"大衛問站在旁邊的人說：「有人殺這非利士人，除掉以色列人的恥辱，怎樣待他呢？這未受割禮的非利士人是誰呢？竟敢向永生神的軍隊罵陣嗎？」","notes":[]},{"n":27,"t":"百姓照先前的話回答他說：「有人能殺這非利士人，必如此如此待他。」","notes":[]},{"n":28,"t":"大衛的長兄以利押聽見大衛與他們所說的話，就向他發怒，說：「你下來做甚麼呢？在曠野的那幾隻羊，你交託了誰呢？我知道你的驕傲和你心裏的惡意，你下來特為要看爭戰！」","notes":[]},{"n":29,"t":"大衛說：「我做了甚麼呢？我來豈沒有緣故嗎？」","notes":[]},{"n":30,"t":"大衛就離開他轉向別人，照先前的話而問；百姓仍照先前的話回答他。","notes":[]},{"n":31,"t":"有人聽見大衛所說的話，就告訴了掃羅；掃羅便打發人叫他來。","notes":[]},{"n":32,"t":"大衛對掃羅說：「人都不必因那非利士人膽怯。你的僕人要去與那非利士人戰鬥。」","notes":[]},{"n":33,"t":"掃羅對大衛說：「你不能去與那非利士人戰鬥；因為你年紀太輕，他自幼就作戰士。」","notes":[]},{"n":34,"t":"大衛對掃羅說：「你僕人為父親放羊，有時來了獅子，有時來了熊，從群中啣一隻羊羔去。","notes":[]},{"n":35,"t":"我就追趕牠，擊打牠，將羊羔從牠口中救出來。牠起來要害我，我就揪著牠的鬍子，將牠打死。","notes":[]},{"n":36,"t":"你僕人曾打死獅子和熊，這未受割禮的非利士人向永生神的軍隊罵陣，也必像獅子和熊一般。」","notes":[]},{"n":37,"t":"大衛又說：「耶和華救我脫離獅子和熊的爪，也必救我脫離這非利士人的手。」掃羅對大衛說：「你可以去吧！耶和華必與你同在。」","notes":[]},{"n":38,"t":"掃羅就把自己的戰衣給大衛穿上，將銅盔給他戴上，又給他穿上鎧甲。","notes":[]},{"n":39,"t":"大衛把刀跨在戰衣外，試試能走不能走；因為素來沒有穿慣，就對掃羅說：「我穿戴這些不能走，因為素來沒有穿慣。」於是摘脫了。","notes":[]},{"n":40,"t":"他手中拿杖，又在溪中挑選了五塊光滑石子，放在袋裏，就是牧人帶的囊裏；手中拿著甩石的機弦，就去迎那非利士人。","notes":[]},{"n":41,"t":"非利士人也漸漸地迎著大衛來，拿盾牌的走在前頭。","notes":[],"heads":["大衛擊殺歌利亞"]},{"n":42,"t":"非利士人觀看，見了大衛，就藐視他；因為他年輕，面色光紅，容貌俊美。","notes":[]},{"n":43,"t":"非利士人對大衛說：「你拿杖到我這裏來，我豈是狗呢？」非利士人就指著自己的神咒詛大衛。","notes":[]},{"n":44,"t":"非利士人又對大衛說：「來吧！我將你的肉給空中的飛鳥、田野的走獸吃。」","notes":[]},{"n":45,"t":"大衛對非利士人說：「你來攻擊我，是靠著刀槍和銅戟；我來攻擊你，是靠著萬軍之耶和華的名，就是你所怒罵帶領以色列軍隊的神。","notes":[]},{"n":46,"t":"今日耶和華必將你交在我手裏。我必殺你，斬你的頭，又將非利士軍兵的屍首給空中的飛鳥、地上的野獸吃，使普天下的人都知道以色列中有神；","notes":[]},{"n":47,"t":"又使這眾人知道耶和華使人得勝，不是用刀用槍，因為爭戰的勝敗全在乎耶和華。他必將你們交在我們手裏。」","notes":[]},{"n":48,"t":"非利士人起身，迎著大衛前來。大衛急忙迎著非利士人，往戰場跑去。","notes":[]},{"n":49,"t":"大衛用手從囊中掏出一塊石子來，用機弦甩去，打中非利士人的額，石子進入額內，他就仆倒，面伏於地。","notes":[]},{"n":50,"t":"這樣，大衛用機弦甩石，勝了那非利士人，打死他；大衛手中卻沒有刀。","notes":[]},{"n":51,"t":"大衛跑去，站在非利士人身旁，將他的刀從鞘中拔出來，殺死他，割了他的頭。非利士眾人看見他們討戰的勇士死了，就都逃跑。","notes":[]},{"n":52,"t":"以色列人和猶大人便起身吶喊，追趕非利士人，直到迦特和以革倫的城門。被殺的非利士人倒在沙拉音的路上，直到迦特和以革倫。","notes":["或譯：該"]},{"n":53,"t":"以色列人追趕非利士人回來，就奪了他們的營盤。","notes":[]},{"n":54,"t":"大衛將那非利士人的頭拿到耶路撒冷，卻將他軍裝放在自己的帳棚裏。","notes":[]},{"n":55,"t":"掃羅看見大衛去攻擊非利士人，就問元帥押尼珥說：「押尼珥啊，那少年人是誰的兒子？」押尼珥說：「我敢在王面前起誓，我不知道。」","notes":[],"heads":["大衛覲見掃羅"]},{"n":56,"t":"王說：「你可以問問那幼年人是誰的兒子。」","notes":[]},{"n":57,"t":"大衛打死非利士人回來，押尼珥領他到掃羅面前，他手中拿著非利士人的頭。","notes":[]},{"n":58,"t":"掃羅問他說：「少年人哪，你是誰的兒子？」大衛說：「我是你僕人伯利恆人耶西的兒子。」","notes":[]}]},"18":{"heading":"掃羅妒忌大衛","verses":[{"n":1,"t":"大衛對掃羅說完了話，約拿單的心與大衛的心深相契合。約拿單愛大衛，如同愛自己的性命。","notes":[]},{"n":2,"t":"那日掃羅留住大衛，不容他再回父家。","notes":[]},{"n":3,"t":"約拿單愛大衛如同愛自己的性命，就與他結盟。","notes":[]},{"n":4,"t":"約拿單從身上脫下外袍，給了大衛，又將戰衣、刀、弓、腰帶都給了他。","notes":[]},{"n":5,"t":"掃羅無論差遣大衛往何處去，他都做事精明。掃羅就立他作戰士長，眾百姓和掃羅的臣僕無不喜悅。","notes":[]},{"n":6,"t":"大衛打死了那非利士人，同眾人回來的時候，婦女們從以色列各城裏出來，歡歡喜喜，打鼓擊磬，歌唱跳舞，迎接掃羅王。","notes":[]},{"n":7,"t":"眾婦女舞蹈唱和，說：「掃羅殺死千千，大衛殺死萬萬。」","notes":[]},{"n":8,"t":"掃羅甚發怒，不喜悅這話，就說：「將萬萬歸大衛，千千歸我，只剩下王位沒有給他了。」","notes":[]},{"n":9,"t":"從這日起，掃羅就怒視大衛。","notes":[]},{"n":10,"t":"次日，從神那裏來的惡魔大大降在掃羅身上，他就在家中胡言亂語。大衛照常彈琴，掃羅手裏拿著槍。","notes":[]},{"n":11,"t":"掃羅把槍一掄，心裏說，我要將大衛刺透，釘在牆上。大衛躲避他兩次。","notes":[]},{"n":12,"t":"掃羅懼怕大衛；因為耶和華離開自己，與大衛同在。","notes":[]},{"n":13,"t":"所以掃羅使大衛離開自己，立他為千夫長，他就領兵出入。","notes":[]},{"n":14,"t":"大衛做事無不精明，耶和華也與他同在。","notes":[]},{"n":15,"t":"掃羅見大衛做事精明，就甚怕他。","notes":[]},{"n":16,"t":"但以色列和猶大眾人都愛大衛，因為他領他們出入。","notes":[]},{"n":17,"t":"掃羅對大衛說：「我將大女兒米拉給你為妻，只要你為我奮勇，為耶和華爭戰。」掃羅心裏說：「我不好親手害他，要藉非利士人的手害他。」","notes":[],"heads":["大衛娶掃羅的女兒"]},{"n":18,"t":"大衛對掃羅說：「我是誰，我是甚麼出身，我父家在以色列中是何等的家，豈敢作王的女婿呢？」","notes":[]},{"n":19,"t":"掃羅的女兒米拉到了當給大衛的時候，掃羅卻給了米何拉人亞得列為妻。","notes":[]},{"n":20,"t":"掃羅的次女米甲愛大衛。有人告訴掃羅，掃羅就喜悅。","notes":[]},{"n":21,"t":"掃羅心裏說：「我將這女兒給大衛，作他的網羅，好藉非利士人的手害他。」所以掃羅對大衛說：「你今日可以第二次作我的女婿。」","notes":[]},{"n":22,"t":"掃羅吩咐臣僕說：「你們暗中對大衛說：『王喜悅你，王的臣僕也都喜愛你，所以你當作王的女婿。』」","notes":[]},{"n":23,"t":"掃羅的臣僕就照這話說給大衛聽。大衛說：「你們以為作王的女婿是一件小事嗎？我是貧窮卑微的人。」","notes":[]},{"n":24,"t":"掃羅的臣僕回奏說，大衛所說的如此如此。","notes":[]},{"n":25,"t":"掃羅說：「你們要對大衛這樣說：『王不要甚麼聘禮，只要一百非利士人的陽皮，好在王的仇敵身上報仇。』」掃羅的意思要使大衛喪在非利士人的手裏。","notes":[]},{"n":26,"t":"掃羅的臣僕將這話告訴大衛，大衛就歡喜作王的女婿。日期還沒有到，","notes":[]},{"n":27,"t":"大衛和跟隨他的人起身前往，殺了二百非利士人，將陽皮滿數交給王，為要作王的女婿。於是掃羅將女兒米甲給大衛為妻。","notes":[]},{"n":28,"t":"掃羅見耶和華與大衛同在，又知道女兒米甲愛大衛，","notes":[]},{"n":29,"t":"就更怕大衛，常作大衛的仇敵。","notes":[]},{"n":30,"t":"每逢非利士軍長出來打仗，大衛比掃羅的臣僕做事精明，因此他的名被人尊重。","notes":[]}]},"19":{"heading":"掃羅逼迫大衛","verses":[{"n":1,"t":"掃羅對他兒子約拿單和眾臣僕說，要殺大衛；掃羅的兒子約拿單卻甚喜愛大衛。","notes":[]},{"n":2,"t":"約拿單告訴大衛說：「我父掃羅想要殺你，所以明日早晨你要小心，到一個僻靜地方藏身。","notes":[]},{"n":3,"t":"我就出到你所藏的田裏，站在我父親旁邊與他談論。我看他情形怎樣，我必告訴你。」","notes":[]},{"n":4,"t":"約拿單向他父親掃羅替大衛說好話，說：「王不可得罪王的僕人大衛；因為他未曾得罪你，他所行的都與你大有益處。","notes":[]},{"n":5,"t":"他拚命殺那非利士人，耶和華為以色列眾人大行拯救；那時你看見，甚是歡喜，現在為何無故要殺大衛，流無辜人的血，自己取罪呢？」","notes":[]},{"n":6,"t":"掃羅聽了約拿單的話，就指著永生的耶和華起誓說：「我必不殺他。」","notes":[]},{"n":7,"t":"約拿單叫大衛來，把這一切事告訴他，帶他去見掃羅。他就仍然侍立在掃羅面前。","notes":[]},{"n":8,"t":"此後又有爭戰的事。大衛出去與非利士人打仗，大大殺敗他們，他們就在他面前逃跑。","notes":[]},{"n":9,"t":"從耶和華那裏來的惡魔又降在掃羅身上（掃羅手裏拿槍坐在屋裏），大衛就用手彈琴。","notes":[]},{"n":10,"t":"掃羅用槍想要刺透大衛，釘在牆上，他卻躲開，掃羅的槍刺入牆內。當夜大衛逃走，躲避了。","notes":[]},{"n":11,"t":"掃羅打發人到大衛的房屋那裏窺探他，要等到天亮殺他。大衛的妻米甲對他說：「你今夜若不逃命，明日你要被殺。」","notes":[]},{"n":12,"t":"於是米甲將大衛從窗戶裏縋下去，大衛就逃走，躲避了。","notes":[]},{"n":13,"t":"米甲把家中的神像放在床上，頭枕在山羊毛裝的枕頭上，用被遮蓋。","notes":[]},{"n":14,"t":"掃羅打發人去捉拿大衛，米甲說：「他病了。」","notes":[]},{"n":15,"t":"掃羅又打發人去看大衛，說：「當連床將他抬來，我好殺他。」","notes":[]},{"n":16,"t":"使者進去，看見床上有神像，頭枕在山羊毛裝的枕頭上。","notes":[]},{"n":17,"t":"掃羅對米甲說：「你為甚麼這樣欺哄我，放我仇敵逃走呢？」米甲回答說：「他對我說：『你放我走，不然我要殺你。』」","notes":[]},{"n":18,"t":"大衛逃避，來到拉瑪見撒母耳，將掃羅向他所行的事述說了一遍。他和撒母耳就往拿約去居住。","notes":[]},{"n":19,"t":"有人告訴掃羅，說大衛在拉瑪的拿約。","notes":[]},{"n":20,"t":"掃羅打發人去捉拿大衛。去的人見有一班先知都受感說話，撒母耳站在其中監管他們；打發去的人也受神的靈感動說話。","notes":[]},{"n":21,"t":"有人將這事告訴掃羅，他又打發人去，他們也受感說話。掃羅第三次打發人去，他們也受感說話。","notes":[]},{"n":22,"t":"然後掃羅自己往拉瑪去，到了西沽的大井，問人說：「撒母耳和大衛在哪裏呢？」有人說：「在拉瑪的拿約。」","notes":[]},{"n":23,"t":"他就往拉瑪的拿約去。神的靈也感動他，一面走一面說話，直到拉瑪的拿約。","notes":[]},{"n":24,"t":"他就脫了衣服，在撒母耳面前受感說話，一晝一夜露體躺臥。因此有句俗語說：「掃羅也列在先知中嗎？」","notes":[]}]},"20":{"heading":"約拿單幫助大衛","verses":[{"n":1,"t":"大衛從拉瑪的拿約逃跑，來到約拿單那裏，對他說：「我做了甚麼？有甚麼罪孽呢？在你父親面前犯了甚麼罪，他竟尋索我的性命呢？」","notes":[]},{"n":2,"t":"約拿單回答說：「斷然不是！你必不致死。我父做事，無論大小，沒有不叫我知道的。怎麼獨有這事隱瞞我呢？決不如此。」","notes":[]},{"n":3,"t":"大衛又起誓說：「你父親準知我在你眼前蒙恩。他心裏說，不如不叫約拿單知道，恐怕他愁煩。我指著永生的耶和華，又敢在你面前起誓，我離死不過一步。」","notes":[]},{"n":4,"t":"約拿單對大衛說：「你心裏所求的，我必為你成就。」","notes":[]},{"n":5,"t":"大衛對約拿單說：「明日是初一，我當與王同席，求你容我去藏在田野，直到第三日晚上。","notes":[]},{"n":6,"t":"你父親若見我不在席上，你就說：『大衛切求我許他回本城伯利恆去，因為他全家在那裏獻年祭。』","notes":[]},{"n":7,"t":"你父親若說好，僕人就平安了；他若發怒，你就知道他決意要害我。","notes":[]},{"n":8,"t":"求你施恩與僕人，因你在耶和華面前曾與僕人結盟。我若有罪，不如你自己殺我，何必將我交給你父親呢？」","notes":[]},{"n":9,"t":"約拿單說：「斷無此事！我若知道我父親決意害你，我豈不告訴你呢？」","notes":[]},{"n":10,"t":"大衛對約拿單說：「你父親若用厲言回答你，誰來告訴我呢？」","notes":[]},{"n":11,"t":"約拿單對大衛說：「你我且往田野去。」二人就往田野去了。","notes":[]},{"n":12,"t":"約拿單對大衛說：「願耶和華－以色列的神為證。明日約在這時候，或第三日，我探我父親的意思，若向你有好意，我豈不打發人告訴你嗎？","notes":[]},{"n":13,"t":"我父親若有意害你，我不告訴你使你平平安安地走，願耶和華重重地降罰與我。願耶和華與你同在，如同從前與我父親同在一樣。","notes":[]},{"n":14,"t":"你要照耶和華的慈愛恩待我，不但我活著的時候免我死亡，","notes":[]},{"n":15,"t":"就是我死後，耶和華從地上剪除你仇敵的時候，你也永不可向我家絕了恩惠。」","notes":[]},{"n":16,"t":"於是約拿單與大衛家結盟，說：「願耶和華藉大衛的仇敵追討背約的罪。」","notes":[]},{"n":17,"t":"約拿單因愛大衛如同愛自己的性命，就使他再起誓。","notes":[]},{"n":18,"t":"約拿單對他說：「明日是初一，你的座位空設，人必理會你不在那裏。","notes":[]},{"n":19,"t":"你等三日，就要速速下去，到你從前遇事所藏的地方，在以色磐石那裏等候。","notes":[]},{"n":20,"t":"我要向磐石旁邊射三箭，如同射箭靶一樣。","notes":[]},{"n":21,"t":"我要打發童子，說：『去把箭找來。』我若對童子說：『箭在後頭，把箭拿來』，你就可以回來；我指著永生的耶和華起誓，你必平安無事。","notes":[]},{"n":22,"t":"我若對童子說：『箭在前頭』，你就要去，因為是耶和華打發你去的。","notes":[]},{"n":23,"t":"至於你我今日所說的話，有耶和華在你我中間為證，直到永遠。」","notes":[]},{"n":24,"t":"大衛就去藏在田野。到了初一日，王坐席要吃飯。","notes":[]},{"n":25,"t":"王照常坐在靠牆的位上，約拿單侍立，押尼珥坐在掃羅旁邊，大衛的座位空設。","notes":[]},{"n":26,"t":"然而這日掃羅沒有說甚麼，他想大衛遇事，偶染不潔，他必定是不潔。","notes":[]},{"n":27,"t":"初二日大衛的座位還空設。掃羅問他兒子約拿單說：「耶西的兒子為何昨日、今日沒有來吃飯呢？」","notes":[]},{"n":28,"t":"約拿單回答掃羅說：「大衛切求我容他往伯利恆去。","notes":[]},{"n":29,"t":"他說：『求你容我去，因為我家在城裏有獻祭的事；我長兄吩咐我去。如今我若在你眼前蒙恩，求你容我去見我的弟兄』；所以大衛沒有赴王的席。」","notes":[]},{"n":30,"t":"掃羅向約拿單發怒，對他說：「你這頑梗背逆之婦人所生的，我豈不知道你喜悅耶西的兒子，自取羞辱，以致你母親露體蒙羞嗎？","notes":[]},{"n":31,"t":"耶西的兒子若在世間活著，你和你的國位必站立不住。現在你要打發人去，將他捉拿交給我；他是該死的。」","notes":[]},{"n":32,"t":"約拿單對父親掃羅說：「他為甚麼該死呢？他做了甚麼呢？」","notes":[]},{"n":33,"t":"掃羅向約拿單掄槍要刺他，約拿單就知道他父親決意要殺大衛。","notes":[]},{"n":34,"t":"於是約拿單氣忿忿地從席上起來，在這初二日沒有吃飯。他因見父親羞辱大衛，就為大衛愁煩。","notes":[]},{"n":35,"t":"次日早晨，約拿單按著與大衛約會的時候出到田野，有一個童子跟隨。","notes":[]},{"n":36,"t":"約拿單對童子說：「你跑去，把我所射的箭找來。」童子跑去，約拿單就把箭射在童子前頭。","notes":[]},{"n":37,"t":"童子到了約拿單落箭之地，約拿單呼叫童子說：「箭不是在你前頭嗎？」","notes":[]},{"n":38,"t":"約拿單又呼叫童子說：「速速地去，不要遲延！」童子就拾起箭來，回到主人那裏。","notes":[]},{"n":39,"t":"童子卻不知道這是甚麼意思，只有約拿單和大衛知道。","notes":[]},{"n":40,"t":"約拿單將弓箭交給童子，吩咐說：「你拿到城裏去。」","notes":[]},{"n":41,"t":"童子一去，大衛就從磐石的南邊出來，俯伏在地，拜了三拜；二人親嘴，彼此哭泣，大衛哭得更慟。","notes":[]},{"n":42,"t":"約拿單對大衛說：「我們二人曾指著耶和華的名起誓說：『願耶和華在你我中間，並你我後裔中間為證，直到永遠。』如今你平平安安地去吧！」大衛就起身走了；約拿單也回城裏去了。","notes":[]}]},"21":{"heading":"大衛逃離掃羅","verses":[{"n":1,"t":"大衛到了挪伯祭司亞希米勒那裏，亞希米勒戰戰兢兢地出來迎接他，問他說：「你為甚麼獨自來，沒有人跟隨呢？」","notes":[]},{"n":2,"t":"大衛回答祭司亞希米勒說：「王吩咐我一件事說：『我差遣你委託你的這件事，不要使人知道。』故此我已派定少年人在某處等候我。","notes":[]},{"n":3,"t":"現在你手下有甚麼？求你給我五個餅或是別樣的食物。」","notes":[]},{"n":4,"t":"祭司對大衛說：「我手下沒有尋常的餅，只有聖餅；若少年人沒有親近婦人才可以給。」","notes":[]},{"n":5,"t":"大衛對祭司說：「實在約有三日我們沒有親近婦人；我出來的時候，雖是尋常行路，少年人的器皿還是潔淨的；何況今日不更是潔淨嗎？」","notes":[]},{"n":6,"t":"祭司就拿聖餅給他；因為在那裏沒有別樣餅，只有更換新餅，從耶和華面前撤下來的陳設餅。（","notes":[]},{"n":7,"t":"當日有掃羅的一個臣子留在耶和華面前。他名叫多益，是以東人，作掃羅的司牧長。）","notes":[]},{"n":8,"t":"大衛問亞希米勒說：「你手下有槍有刀沒有？因為王的事甚急，連刀劍器械我都沒有帶。」","notes":[]},{"n":9,"t":"祭司說：「你在以拉谷殺非利士人歌利亞的那刀在這裏，裹在布中，放在以弗得後邊，你要就可以拿去；除此以外，再沒有別的。」大衛說：「這刀沒有可比的！求你給我。」","notes":[]},{"n":10,"t":"那日大衛起來，躲避掃羅，逃到迦特王亞吉那裏。","notes":[]},{"n":11,"t":"亞吉的臣僕對亞吉說：「這不是以色列國王大衛嗎？那裏的婦女跳舞唱和，不是指著他說『掃羅殺死千千，大衛殺死萬萬』嗎？」","notes":[]},{"n":12,"t":"大衛將這話放在心裏，甚懼怕迦特王亞吉，","notes":[]},{"n":13,"t":"就在眾人面前改變了尋常的舉動，在他們手下假裝瘋癲，在城門的門扇上胡寫亂畫，使唾沫流在鬍子上。","notes":[]},{"n":14,"t":"亞吉對臣僕說：「你們看，這人是瘋子。為甚麼帶他到我這裏來呢？","notes":[]},{"n":15,"t":"我豈缺少瘋子，你們帶這人來在我面前瘋癲嗎？這人豈可進我的家呢？」","notes":[]}]},"22":{"heading":"殘殺祭司","verses":[{"n":1,"t":"大衛就離開那裏，逃到亞杜蘭洞。他的弟兄和他父親的全家聽見了，就都下到他那裏。","notes":[]},{"n":2,"t":"凡受窘迫的、欠債的、心裏苦惱的都聚集到大衛那裏；大衛就作他們的頭目，跟隨他的約有四百人。","notes":[]},{"n":3,"t":"大衛從那裏往摩押的米斯巴去，對摩押王說：「求你容我父母搬來，住在你們這裏，等我知道神要為我怎樣行。」","notes":[]},{"n":4,"t":"大衛領他父母到摩押王面前。大衛住山寨多少日子，他父母也住摩押王那裏多少日子。","notes":[]},{"n":5,"t":"先知迦得對大衛說：「你不要住在山寨，要往猶大地去。」大衛就離開那裏，進入哈列的樹林。","notes":[]},{"n":6,"t":"掃羅在基比亞的拉瑪，坐在垂絲柳樹下，手裏拿著槍，眾臣僕侍立在左右。掃羅聽見大衛和跟隨他的人在何處，","notes":[]},{"n":7,"t":"就對左右侍立的臣僕說：「便雅憫人哪，你們要聽我的話！耶西的兒子能將田地和葡萄園賜給你們各人嗎？能立你們各人作千夫長百夫長嗎？","notes":[]},{"n":8,"t":"你們竟都結黨害我！我的兒子與耶西的兒子結盟的時候，無人告訴我；我的兒子挑唆我的臣子謀害我，就如今日的光景，也無人告訴我，為我憂慮。」","notes":[]},{"n":9,"t":"那時以東人多益站在掃羅的臣僕中，對他說：「我曾看見耶西的兒子到了挪伯，亞希突的兒子亞希米勒那裏。","notes":[]},{"n":10,"t":"亞希米勒為他求問耶和華，又給他食物，並給他殺非利士人歌利亞的刀。」","notes":[]},{"n":11,"t":"王就打發人將祭司亞希突的兒子亞希米勒和他父親的全家，就是住挪伯的祭司都召了來；他們就來見王。","notes":[]},{"n":12,"t":"掃羅說：「亞希突的兒子，要聽我的話！」他回答說：「主啊，我在這裏。」","notes":[]},{"n":13,"t":"掃羅對他說：「你為甚麼與耶西的兒子結黨害我，將食物和刀給他，又為他求問神，使他起來謀害我，就如今日的光景？」","notes":[]},{"n":14,"t":"亞希米勒回答王說：「王的臣僕中有誰比大衛忠心呢？他是王的女婿，又是王的參謀，並且在王家中是尊貴的。","notes":[]},{"n":15,"t":"我豈是從今日才為他求問神呢？斷不是這樣！王不要將罪歸我和我父的全家；因為這事，無論大小，僕人都不知道。」","notes":[]},{"n":16,"t":"王說：「亞希米勒啊，你和你父的全家都是該死的！」","notes":[]},{"n":17,"t":"王就吩咐左右的侍衛說：「你們去殺耶和華的祭司；因為他們幫助大衛，又知道大衛逃跑，竟沒有告訴我。」掃羅的臣子卻不肯伸手殺耶和華的祭司。","notes":[]},{"n":18,"t":"王吩咐多益說：「你去殺祭司吧！」以東人多益就去殺祭司，那日殺了穿細麻布以弗得的八十五人；","notes":[]},{"n":19,"t":"又用刀將祭司城挪伯中的男女、孩童、吃奶的，和牛、羊、驢盡都殺滅。","notes":[]},{"n":20,"t":"亞希突的兒子亞希米勒有一個兒子，名叫亞比亞他，逃到大衛那裏。","notes":[]},{"n":21,"t":"亞比亞他將掃羅殺耶和華祭司的事告訴大衛。","notes":[]},{"n":22,"t":"大衛對亞比亞他說：「那日我見以東人多益在那裏，就知道他必告訴掃羅。你父的全家喪命，都是因我的緣故。","notes":[]},{"n":23,"t":"你可以住在我這裏，不要懼怕。因為尋索你命的就是尋索我的命；你在我這裏可得保全。」","notes":[]}]},"23":{"heading":"大衛救基伊拉的居民","verses":[{"n":1,"t":"有人告訴大衛說：「非利士人攻擊基伊拉，搶奪禾場。」","notes":[]},{"n":2,"t":"所以大衛求問耶和華說：「我去攻打那些非利士人可以不可以？」耶和華對大衛說：「你可以去攻打非利士人，拯救基伊拉。」","notes":[]},{"n":3,"t":"跟隨大衛的人對他說：「我們在猶大地這裏尚且懼怕，何況往基伊拉去攻打非利士人的軍旅呢？」","notes":[]},{"n":4,"t":"大衛又求問耶和華。耶和華回答說：「你起身下基伊拉去，我必將非利士人交在你手裏。」","notes":[]},{"n":5,"t":"大衛和跟隨他的人往基伊拉去，與非利士人打仗，大大殺敗他們，又奪獲他們的牲畜。這樣，大衛救了基伊拉的居民。","notes":[]},{"n":6,"t":"亞希米勒的兒子亞比亞他逃到基伊拉見大衛的時候，手裏拿著以弗得。","notes":[]},{"n":7,"t":"有人告訴掃羅說：「大衛到了基伊拉。」掃羅說：「他進了有門有閂的城，困閉在裏頭；這是神將他交在我手裏了。」","notes":[]},{"n":8,"t":"於是掃羅招聚眾民，要下去攻打基伊拉城，圍困大衛和跟隨他的人。","notes":[]},{"n":9,"t":"大衛知道掃羅設計謀害他，就對祭司亞比亞他說：「將以弗得拿過來。」","notes":[]},{"n":10,"t":"大衛禱告說：「耶和華－以色列的神啊，你僕人聽真了掃羅要往基伊拉來，為我的緣故滅城。","notes":[]},{"n":11,"t":"基伊拉人將我交在掃羅手裏不交？掃羅照著你僕人所聽的話下來不下來？耶和華－以色列的神啊，求你指示僕人！」耶和華說：「掃羅必下來。」","notes":[]},{"n":12,"t":"大衛又說：「基伊拉人將我和跟隨我的人交在掃羅手裏不交？」耶和華說：「必交出來。」","notes":[]},{"n":13,"t":"大衛和跟隨他的約有六百人，就起身出了基伊拉，往他們所能往的地方去。有人告訴掃羅，大衛離開基伊拉逃走；於是掃羅不出來了。","notes":[]},{"n":14,"t":"大衛住在曠野的山寨裏，常在西弗曠野的山地。掃羅天天尋索大衛，神卻不將大衛交在他手裏。","notes":[],"heads":["大衛在山地"]},{"n":15,"t":"大衛知道掃羅出來尋索他的命。那時，他住在西弗曠野的樹林裏；","notes":[]},{"n":16,"t":"掃羅的兒子約拿單起身，往那樹林裏去見大衛，使他倚靠神得以堅固，","notes":[]},{"n":17,"t":"對他說：「不要懼怕！我父掃羅的手必不加害於你；你必作以色列的王，我也作你的宰相。這事我父掃羅知道了。」","notes":[]},{"n":18,"t":"於是二人在耶和華面前立約。大衛仍住在樹林裏，約拿單回家去了。","notes":[]},{"n":19,"t":"西弗人上到基比亞見掃羅，說：「大衛不是在我們那裏的樹林裏山寨中、曠野南邊的哈基拉山藏著嗎？","notes":[]},{"n":20,"t":"王啊，請你隨你的心願下來，我們必親自將他交在王的手裏。」","notes":[]},{"n":21,"t":"掃羅說：「願耶和華賜福與你們，因你們顧恤我。","notes":[]},{"n":22,"t":"請你們回去，再確實查明他的住處和行蹤，是誰看見他在那裏，因為我聽見人說他甚狡猾。","notes":[]},{"n":23,"t":"所以要看準他藏匿的地方，回來據實地告訴我，我就與你們同去。他若在猶大的境內，我必從千門萬戶中搜出他來。」","notes":[]},{"n":24,"t":"西弗人就起身，在掃羅以先往西弗去。大衛和跟隨他的人卻在瑪雲曠野南邊的亞拉巴。","notes":[]},{"n":25,"t":"掃羅和跟隨他的人去尋找大衛；有人告訴大衛，他就下到磐石，住在瑪雲的曠野。掃羅聽見，便在瑪雲的曠野追趕大衛。","notes":[]},{"n":26,"t":"掃羅在山這邊走，大衛和跟隨他的人在山那邊走。大衛急忙躲避掃羅；因為掃羅和跟隨他的人，四面圍住大衛和跟隨他的人，要拿獲他們。","notes":[]},{"n":27,"t":"忽有使者來報告掃羅說：「非利士人犯境搶掠，請王快快回去！」","notes":[]},{"n":28,"t":"於是掃羅不追趕大衛，回去攻打非利士人。因此那地方名叫西拉‧哈瑪希羅結。","notes":[]},{"n":29,"t":"大衛從那裏上去，住在隱‧基底的山寨裏。","notes":[]}]},"24":{"heading":"大衛饒掃羅的命","verses":[{"n":1,"t":"掃羅追趕非利士人回來，有人告訴他說：「大衛在隱‧基底的曠野。」","notes":[]},{"n":2,"t":"掃羅就從以色列人中挑選三千精兵，率領他們往野羊的磐石去，尋索大衛和跟隨他的人。","notes":[]},{"n":3,"t":"到了路旁的羊圈，在那裏有洞，掃羅進去大解。大衛和跟隨他的人正藏在洞裏的深處。","notes":[]},{"n":4,"t":"跟隨的人對大衛說：「耶和華曾應許你說：『我要將你的仇敵交在你手裏，你可以任意待他。』如今時候到了！」大衛就起來，悄悄地割下掃羅外袍的衣襟。","notes":[]},{"n":5,"t":"隨後大衛心中自責，因為割下掃羅的衣襟；","notes":[]},{"n":6,"t":"對跟隨他的人說：「我的主乃是耶和華的受膏者，我在耶和華面前萬不敢伸手害他，因他是耶和華的受膏者。」","notes":[]},{"n":7,"t":"大衛用這話攔住跟隨他的人，不容他們起來害掃羅。掃羅起來，從洞裏出去行路。","notes":[]},{"n":8,"t":"隨後大衛也起來，從洞裏出去，呼叫掃羅說：「我主，我王！」掃羅回頭觀看，大衛就屈身、臉伏於地下拜。","notes":[]},{"n":9,"t":"大衛對掃羅說：「你為何聽信人的讒言，說大衛想要害你呢？","notes":[]},{"n":10,"t":"今日你親眼看見在洞中，耶和華將你交在我手裏；有人叫我殺你，我卻愛惜你，說：『我不敢伸手害我的主，因為他是耶和華的受膏者。』","notes":[]},{"n":11,"t":"我父啊，看看你外袍的衣襟在我手中。我割下你的衣襟，沒有殺你；你由此可以知道我沒有惡意叛逆你。你雖然獵取我的命，我卻沒有得罪你。","notes":[]},{"n":12,"t":"願耶和華在你我中間判斷是非，在你身上為我伸冤，我卻不親手加害於你。","notes":[]},{"n":13,"t":"古人有句俗語說：『惡事出於惡人。』我卻不親手加害於你。","notes":[]},{"n":14,"t":"以色列王出來要尋找誰呢？追趕誰呢？不過追趕一條死狗，一個虼蚤就是了。","notes":[]},{"n":15,"t":"願耶和華在你我中間施行審判，斷定是非，並且鑒察，為我伸冤，救我脫離你的手。」","notes":[]},{"n":16,"t":"大衛向掃羅說完這話，掃羅說：「我兒大衛，這是你的聲音嗎？」就放聲大哭，","notes":[]},{"n":17,"t":"對大衛說：「你比我公義；因為你以善待我，我卻以惡待你。","notes":[]},{"n":18,"t":"你今日顯明是以善待我；因為耶和華將我交在你手裏，你卻沒有殺我。","notes":[]},{"n":19,"t":"人若遇見仇敵，豈肯放他平安無事地去呢？願耶和華因你今日向我所行的，以善報你。","notes":[]},{"n":20,"t":"我也知道你必要作王，以色列的國必堅立在你手裏。","notes":[]},{"n":21,"t":"現在你要指著耶和華向我起誓，不剪除我的後裔，在我父家不滅沒我的名。」","notes":[]},{"n":22,"t":"於是大衛向掃羅起誓，掃羅就回家去；大衛和跟隨他的人上山寨去了。","notes":[]}]},"25":{"heading":"撒母耳去世","verses":[{"n":1,"t":"撒母耳死了，以色列眾人聚集，為他哀哭，將他葬在拉瑪－他自己的墳墓裏。大衛起身，下到巴蘭的曠野。","notes":["原文是房屋"]},{"n":2,"t":"在瑪雲有一個人，他的產業在迦密，是一個大富戶，有三千綿羊，一千山羊；他正在迦密剪羊毛。","notes":[]},{"n":3,"t":"那人名叫拿八，是迦勒族的人；他的妻名叫亞比該，是聰明俊美的婦人。拿八為人剛愎凶惡。","notes":[]},{"n":4,"t":"大衛在曠野聽見說拿八剪羊毛，","notes":[]},{"n":5,"t":"大衛就打發十個僕人，吩咐他們說：「你們上迦密去見拿八，提我的名問他安。","notes":[]},{"n":6,"t":"要對那富戶如此說：『願你平安，願你家平安，願你一切所有的都平安。","notes":[]},{"n":7,"t":"現在我聽說有人為你剪羊毛，你的牧人在迦密的時候和我們在一處，我們沒有欺負他們，他們也未曾失落甚麼。","notes":[]},{"n":8,"t":"可以問你的僕人，他們必告訴你。所以願我的僕人在你眼前蒙恩，因為是在好日子來的。求你隨手取點賜與僕人和你兒子大衛。』」","notes":[]},{"n":9,"t":"大衛的僕人到了，將這話提大衛的名都告訴了拿八，就住了口。","notes":[]},{"n":10,"t":"拿八回答大衛的僕人說：「大衛是誰？耶西的兒子是誰？近來悖逆主人奔逃的僕人甚多，","notes":[]},{"n":11,"t":"我豈可將飲食和為我剪羊毛人所宰的肉給我不知道從哪裏來的人呢？」","notes":[]},{"n":12,"t":"大衛的僕人就轉身從原路回去，照這話告訴大衛。","notes":[]},{"n":13,"t":"大衛向跟隨他的人說：「你們各人都要帶上刀！」眾人就都帶上刀，大衛也帶上刀。跟隨大衛上去的約有四百人，留下二百人看守器具。","notes":[]},{"n":14,"t":"有拿八的一個僕人告訴拿八的妻亞比該說：「大衛從曠野打發使者來問我主人的安，主人卻辱罵他們。","notes":[]},{"n":15,"t":"但是那些人待我們甚好；我們在田野與他們來往的時候，沒有受他們的欺負，也未曾失落甚麼。","notes":[]},{"n":16,"t":"我們在他們那裏牧羊的時候，他們晝夜作我們的保障。","notes":[]},{"n":17,"t":"所以你當籌劃，看怎樣行才好；不然，禍患定要臨到我主人和他全家。他性情凶暴，無人敢與他說話。」","notes":[]},{"n":18,"t":"亞比該急忙將二百餅，兩皮袋酒，五隻收拾好了的羊，五細亞烘好了的穗子，一百葡萄餅，二百無花果餅，都馱在驢上，","notes":[]},{"n":19,"t":"對僕人說：「你們前頭走，我隨著你們去。」這事她卻沒有告訴丈夫拿八。","notes":[]},{"n":20,"t":"亞比該騎著驢，正下山坡，見大衛和跟隨他的人從對面下來，亞比該就迎接他們。","notes":[]},{"n":21,"t":"大衛曾說：「我在曠野為那人看守所有的，以致他一樣不失落，實在是徒然了！他向我以惡報善。","notes":[]},{"n":22,"t":"凡屬拿八的男丁，我若留一個到明日早晨，願神重重降罰與我！」","notes":[]},{"n":23,"t":"亞比該見大衛，便急忙下驢，在大衛面前臉伏於地叩拜，","notes":[]},{"n":24,"t":"俯伏在大衛的腳前，說：「我主啊，願這罪歸我！求你容婢女向你進言，更求你聽婢女的話。","notes":[]},{"n":25,"t":"我主不要理這壞人拿八，他的性情與他的名相稱；他名叫拿八，他為人果然愚頑。但我主所打發的僕人，婢女並沒有看見。","notes":["就是愚頑的意思"]},{"n":26,"t":"我主啊，耶和華既然阻止你親手報仇，取流血的罪，所以我指著永生的耶和華、又敢在你面前起誓說：『願你的仇敵和謀害你的人都像拿八一樣。』","notes":[]},{"n":27,"t":"如今求你將婢女送來的禮物給跟隨你的僕人。","notes":[]},{"n":28,"t":"求你饒恕婢女的罪過。耶和華必為我主建立堅固的家，因我主為耶和華爭戰；並且在你平生的日子查不出有甚麼過來。","notes":[]},{"n":29,"t":"雖有人起來追逼你，尋索你的性命，你的性命卻在耶和華－你的神那裏蒙保護，如包裹寶器一樣；你仇敵的性命，耶和華必拋去，如用機弦甩石一樣。","notes":[]},{"n":30,"t":"我主現在若不親手報仇流無辜人的血，到了耶和華照所應許你的話賜福與你，立你作以色列的王，那時我主必不致心裏不安，覺得良心有虧。耶和華賜福與我主的時候，求你記念婢女。」","notes":[],"end":31},{"n":32,"t":"大衛對亞比該說：「耶和華－以色列的神是應當稱頌的，因為他今日使你來迎接我。","notes":[]},{"n":33,"t":"你和你的見識也當稱讚；因為你今日攔阻我親手報仇、流人的血。","notes":[]},{"n":34,"t":"我指著阻止我加害於你的耶和華－以色列永生的神起誓，你若不速速地來迎接我，到明日早晨，凡屬拿八的男丁必定不留一個。」","notes":[]},{"n":35,"t":"大衛受了亞比該送來的禮物，就對她說：「我聽了你的話，准了你的情面，你可以平平安安地回家吧！」","notes":[]},{"n":36,"t":"亞比該到拿八那裏，見他在家裏設擺筵席，如同王的筵席；拿八快樂大醉。亞比該無論大小事都沒有告訴他，就等到次日早晨。","notes":[]},{"n":37,"t":"到了早晨，拿八醒了酒，他的妻將這些事都告訴他，他就魂不附體，身僵如石頭一般。","notes":[]},{"n":38,"t":"過了十天，耶和華擊打拿八，他就死了。","notes":[]},{"n":39,"t":"大衛聽見拿八死了，就說：「應當稱頌耶和華，因他伸了拿八羞辱我的冤，又阻止僕人行惡；也使拿八的惡歸到拿八的頭上。」於是大衛打發人去，與亞比該說，要娶她為妻。","notes":[]},{"n":40,"t":"大衛的僕人到了迦密見亞比該，對她說：「大衛打發我們來見你，想要娶你為妻。」","notes":[]},{"n":41,"t":"亞比該就起來，俯伏在地，說：「我情願作婢女，洗我主僕人的腳。」","notes":[]},{"n":42,"t":"亞比該立刻起身，騎上驢，帶著五個使女，跟從大衛的使者去了，就作了大衛的妻。","notes":[]},{"n":43,"t":"大衛先娶了耶斯列人亞希暖，她們二人都作了他的妻。","notes":[]},{"n":44,"t":"掃羅已將他的女兒米甲，就是大衛的妻，給了迦琳人拉億的兒子帕提為妻。","notes":[]}]},"26":{"heading":"大衛又饒掃羅的命","verses":[{"n":1,"t":"西弗人到基比亞見掃羅，說：「大衛不是在曠野前的哈基拉山藏著嗎？」","notes":[]},{"n":2,"t":"掃羅就起身，帶領以色列人中挑選的三千精兵下到西弗的曠野，要在那裏尋索大衛。","notes":[]},{"n":3,"t":"掃羅在曠野前的哈基拉山，在道路上安營。大衛住在曠野，聽說掃羅到曠野來追尋他，","notes":[]},{"n":4,"t":"就打發人去探聽，便知道掃羅果然來到。","notes":[]},{"n":5,"t":"大衛起來，到掃羅安營的地方，看見掃羅和他的元帥尼珥的兒子押尼珥睡臥之處；掃羅睡在輜重營裏，百姓安營在他周圍。","notes":[]},{"n":6,"t":"大衛對赫人亞希米勒和洗魯雅的兒子約押的兄弟亞比篩說：「誰同我下到掃羅營裏去？」亞比篩說：「我同你下去。」","notes":[]},{"n":7,"t":"於是大衛和亞比篩夜間到了百姓那裏，見掃羅睡在輜重營裏；他的槍在頭旁，插在地上。押尼珥和百姓睡在他周圍。","notes":[]},{"n":8,"t":"亞比篩對大衛說：「現在神將你的仇敵交在你手裏，求你容我拿槍將他刺透在地，一刺就成，不用再刺。」","notes":[]},{"n":9,"t":"大衛對亞比篩說：「不可害死他。有誰伸手害耶和華的受膏者而無罪呢？」","notes":[]},{"n":10,"t":"大衛又說：「我指著永生的耶和華起誓，他或被耶和華擊打，或是死期到了，或是出戰陣亡；","notes":[]},{"n":11,"t":"我在耶和華面前，萬不敢伸手害耶和華的受膏者。現在你可以將他頭旁的槍和水瓶拿來，我們就走。」","notes":[]},{"n":12,"t":"大衛從掃羅的頭旁拿了槍和水瓶，二人就走了，沒有人看見，沒有人知道，也沒有人醒起，都睡著了，因為耶和華使他們沉沉地睡了。","notes":[]},{"n":13,"t":"大衛過到那邊去，遠遠地站在山頂上，與他們相離甚遠。","notes":[]},{"n":14,"t":"大衛呼叫百姓和尼珥的兒子押尼珥說：「押尼珥啊，你為何不答應呢？」押尼珥說：「你是誰？竟敢呼叫王呢？」","notes":[]},{"n":15,"t":"大衛對押尼珥說：「你不是個勇士嗎？以色列中誰能比你呢？民中有人進來要害死王－你的主，你為何沒有保護王－你的主呢？","notes":[]},{"n":16,"t":"你這樣是不好的！我指著永生的耶和華起誓，你們都是該死的；因為沒有保護你們的主，就是耶和華的受膏者。現在你看看王頭旁的槍和水瓶在哪裏。」","notes":[]},{"n":17,"t":"掃羅聽出是大衛的聲音，就說：「我兒大衛，這是你的聲音嗎？」大衛說：「主－我的王啊，是我的聲音」；","notes":[]},{"n":18,"t":"又說：「我做了甚麼？我手裏有甚麼惡事？我主竟追趕僕人呢？","notes":[]},{"n":19,"t":"求我主我王聽僕人的話：若是耶和華激發你攻擊我，願耶和華收納祭物；若是人激發你，願他在耶和華面前受咒詛；因為他現今趕逐我，不容我在耶和華的產業上有分，說：『你去事奉別神吧！』","notes":[]},{"n":20,"t":"現在求王不要使我的血流在離耶和華遠的地方。以色列王出來是尋找一個虼蚤，如同人在山上獵取一個鷓鴣一般。」","notes":[]},{"n":21,"t":"掃羅說：「我有罪了！我兒大衛，你可以回來，因你今日看我的性命為寶貴；我必不再加害於你。我是糊塗人，大大錯了。」","notes":[]},{"n":22,"t":"大衛說：「王的槍在這裏，可以吩咐一個僕人過來拿去。","notes":[]},{"n":23,"t":"今日耶和華將王交在我手裏，我卻不肯伸手害耶和華的受膏者。耶和華必照各人的公義誠實報應他。","notes":[]},{"n":24,"t":"我今日重看你的性命，願耶和華也重看我的性命，並且拯救我脫離一切患難。」","notes":[]},{"n":25,"t":"掃羅對大衛說：「我兒大衛，願你得福！你必做大事，也必得勝。」於是大衛起行，掃羅回他的本處去了。","notes":[]}]},"27":{"heading":"大衛在非利士人中間","verses":[{"n":1,"t":"大衛心裏說：「必有一日我死在掃羅手裏，不如逃奔非利士地去。掃羅見我不在以色列的境內，就必絕望，不再尋索我；這樣我可以脫離他的手。」","notes":[]},{"n":2,"t":"於是大衛起身，和跟隨他的六百人投奔迦特王－瑪俄的兒子亞吉去了。","notes":[]},{"n":3,"t":"大衛和他的兩個妻，就是耶斯列人亞希暖和作過拿八妻的迦密人亞比該，並跟隨他的人，連各人的眷屬，都住在迦特的亞吉那裏。","notes":[]},{"n":4,"t":"有人告訴掃羅說：「大衛逃到迦特。」掃羅就不再尋索他了。","notes":[]},{"n":5,"t":"大衛對亞吉說：「我若在你眼前蒙恩，求你在京外的城邑中賜我一個地方居住。僕人何必與王同住京都呢？」","notes":[]},{"n":6,"t":"當日亞吉將洗革拉賜給他，因此洗革拉屬猶大王，直到今日。","notes":[]},{"n":7,"t":"大衛在非利士地住了一年零四個月。","notes":[]},{"n":8,"t":"大衛和跟隨他的人上去，侵奪基述人、基色人、亞瑪力人之地。這幾族歷來住在那地，從書珥直到埃及。","notes":[]},{"n":9,"t":"大衛擊殺那地的人，無論男女都沒有留下一個，又奪獲牛、羊、駱駝、驢，並衣服，回來見亞吉。","notes":[]},{"n":10,"t":"亞吉說：「你們今日侵奪了甚麼地方呢？」大衛說：「侵奪了猶大的南方、耶拉篾的南方、基尼的南方。」","notes":[]},{"n":11,"t":"無論男女，大衛沒有留下一個帶到迦特來。他說：「恐怕他們將我們的事告訴人，說大衛住在非利士地的時候常常這樣行。」","notes":[]},{"n":12,"t":"亞吉信了大衛，心裏說：「大衛使本族以色列人憎惡他，所以他必永遠作我的僕人了。」","notes":[]}]},"28":{"heading":"掃羅求問女巫","verses":[{"n":1,"t":"那時，非利士人聚集軍旅，要與以色列人打仗。亞吉對大衛說：「你當知道，你和跟隨你的人都要隨我出戰。」","notes":[]},{"n":2,"t":"大衛對亞吉說：「僕人所能做的事，王必知道。」亞吉對大衛說：「這樣，我立你永遠作我的護衛長。」","notes":[]},{"n":3,"t":"那時撒母耳已經死了，以色列眾人為他哀哭，葬他在拉瑪，就是在他本城裏。掃羅曾在國內不容有交鬼的和行巫術的人。","notes":[]},{"n":4,"t":"非利士人聚集，來到書念安營；掃羅聚集以色列眾人在基利波安營。","notes":[]},{"n":5,"t":"掃羅看見非利士的軍旅就懼怕，心中發顫。","notes":[]},{"n":6,"t":"掃羅求問耶和華，耶和華卻不藉夢，或烏陵，或先知回答他。","notes":[]},{"n":7,"t":"掃羅吩咐臣僕說：「當為我找一個交鬼的婦人，我好去問她。」臣僕說：「在隱‧多珥有一個交鬼的婦人。」","notes":[]},{"n":8,"t":"於是掃羅改了裝，穿上別的衣服，帶著兩個人，夜裏去見那婦人。掃羅說：「求你用交鬼的法術，將我所告訴你的死人，為我招上來。」","notes":[]},{"n":9,"t":"婦人對他說：「你知道掃羅從國中剪除交鬼的和行巫術的。你為何陷害我的性命，使我死呢？」","notes":[]},{"n":10,"t":"掃羅向婦人指著耶和華起誓說：「我指著永生的耶和華起誓，你必不因這事受刑。」","notes":[]},{"n":11,"t":"婦人說：「我為你招誰上來呢？」回答說：「為我招撒母耳上來。」","notes":[]},{"n":12,"t":"婦人看見撒母耳，就大聲呼叫，對掃羅說：「你是掃羅，為甚麼欺哄我呢？」","notes":[]},{"n":13,"t":"王對婦人說：「不要懼怕，你看見了甚麼呢？」婦人對掃羅說：「我看見有神從地裏上來。」","notes":[]},{"n":14,"t":"掃羅說：「他是怎樣的形狀？」婦人說：「有一個老人上來，身穿長衣。」掃羅知道是撒母耳，就屈身，臉伏於地下拜。","notes":[]},{"n":15,"t":"撒母耳對掃羅說：「你為甚麼攪擾我，招我上來呢？」掃羅回答說：「我甚窘急；因為非利士人攻擊我，神也離開我，不再藉先知或夢回答我。因此請你上來，好指示我應當怎樣行。」","notes":[]},{"n":16,"t":"撒母耳說：「耶和華已經離開你，且與你為敵，你何必問我呢？","notes":[]},{"n":17,"t":"耶和華照他藉我說的話，已經從你手裏奪去國權，賜與別人，就是大衛。","notes":[]},{"n":18,"t":"因你沒有聽從耶和華的命令；他惱怒亞瑪力人，你沒有滅絕他們，所以今日耶和華向你這樣行，","notes":[]},{"n":19,"t":"並且耶和華必將你和以色列人交在非利士人的手裏。明日你和你眾子必與我在一處了；耶和華必將以色列的軍兵交在非利士人手裏。」","notes":[]},{"n":20,"t":"掃羅猛然仆倒，挺身在地，因撒母耳的話甚是懼怕；那一晝一夜，沒有吃甚麼，就毫無氣力。","notes":[]},{"n":21,"t":"婦人到掃羅面前，見他極其驚恐，對他說：「婢女聽從你的話，不顧惜自己的性命，遵從你所吩咐的。","notes":[]},{"n":22,"t":"現在求你聽婢女的話，容我在你面前擺上一點食物，你吃了，可以有氣力行路。」","notes":[]},{"n":23,"t":"掃羅不肯，說：「我不吃。」但他的僕人和婦人再三勸他，他才聽了他們的話，從地上起來，坐在床上。","notes":[]},{"n":24,"t":"婦人急忙將家裏的一隻肥牛犢宰了，又拿麵摶成無酵餅烤了，","notes":[]},{"n":25,"t":"擺在掃羅和他僕人面前。他們吃完，當夜就起身走了。","notes":[]}]},"29":{"heading":"非利士人不要大衛","verses":[{"n":1,"t":"非利士人將他們的軍旅聚到亞弗；以色列人在耶斯列的泉旁安營。","notes":[]},{"n":2,"t":"非利士人的首領各率軍隊，或百或千，挨次前進；大衛和跟隨他的人同著亞吉跟在後邊。","notes":[]},{"n":3,"t":"非利士人的首領說：「這些希伯來人在這裏做甚麼呢？」亞吉對他們說：「這不是以色列王掃羅的臣子大衛嗎？他在我這裏有些年日了。自從他投降我直到今日，我未曾見他有過錯。」","notes":[]},{"n":4,"t":"非利士人的首領向亞吉發怒，對他說：「你要叫這人回你所安置他的地方，不可叫他同我們出戰，恐怕他在陣上反為我們的敵人。他用甚麼與他主人復和呢？豈不是用我們這些人的首級嗎？","notes":[]},{"n":5,"t":"從前以色列的婦女跳舞唱和說：『掃羅殺死千千，大衛殺死萬萬』，所說的不是這個大衛嗎？」","notes":[]},{"n":6,"t":"亞吉叫大衛來，對他說：「我指著永生的耶和華起誓，你是正直人。你隨我在軍中出入，我看你甚好。自從你投奔我到如今，我未曾見你有甚麼過失；只是眾首領不喜悅你。","notes":[]},{"n":7,"t":"現在你可以平平安安地回去，免得非利士人的首領不歡喜你。」","notes":[]},{"n":8,"t":"大衛對亞吉說：「我做了甚麼呢？自從僕人到你面前，直到今日，你查出我有甚麼過錯，使我不去攻擊主－我王的仇敵呢？」","notes":[]},{"n":9,"t":"亞吉說：「我知道你在我眼前是好人，如同神的使者一般；只是非利士人的首領說：『這人不可同我們出戰。』","notes":[]},{"n":10,"t":"故此你和跟隨你的人，就是你本主的僕人，要明日早晨起來，等到天亮回去吧！」","notes":[]},{"n":11,"t":"於是大衛和跟隨他的人早晨起來，回往非利士地去。非利士人也上耶斯列去了。","notes":[]}]},"30":{"heading":"與亞瑪力人爭戰","verses":[{"n":1,"t":"第三日，大衛和跟隨他的人到了洗革拉。亞瑪力人已經侵奪南地，攻破洗革拉，用火焚燒，","notes":[]},{"n":2,"t":"擄了城內的婦女和其中的大小人口，卻沒有殺一個，都帶著走了。","notes":[]},{"n":3,"t":"大衛和跟隨他的人到了那城，不料，城已燒毀，他們的妻子兒女都被擄去了。","notes":[]},{"n":4,"t":"大衛和跟隨他的人就放聲大哭，直哭得沒有氣力。","notes":[]},{"n":5,"t":"大衛的兩個妻－耶斯列人亞希暖和作過拿八妻的迦密人亞比該，也被擄去了。","notes":[]},{"n":6,"t":"大衛甚是焦急，因眾人為自己的兒女苦惱，說：「要用石頭打死他。」大衛卻倚靠耶和華－他的神，心裏堅固。","notes":[]},{"n":7,"t":"大衛對亞希米勒的兒子祭司亞比亞他說：「請你將以弗得拿過來。」亞比亞他就將以弗得拿到大衛面前。","notes":[]},{"n":8,"t":"大衛求問耶和華說：「我追趕敵軍，追得上追不上呢？」耶和華說：「你可以追，必追得上，都救得回來。」","notes":[]},{"n":9,"t":"於是，大衛和跟隨他的六百人來到比梭溪；有不能前去的就留在那裏。","notes":[]},{"n":10,"t":"大衛卻帶著四百人往前追趕，有二百人疲乏，不能過比梭溪，所以留在那裏。","notes":[]},{"n":11,"t":"這四百人在田野遇見一個埃及人，就帶他到大衛面前，給他餅吃，給他水喝，","notes":[]},{"n":12,"t":"又給他一塊無花果餅，兩個葡萄餅。他吃了，就精神復原；因為他三日三夜沒有吃餅，沒有喝水。","notes":[]},{"n":13,"t":"大衛問他說：「你是屬誰的？你是哪裏的人？」他回答說：「我是埃及的少年人，是亞瑪力人的奴僕；因我三日前患病，我主人就把我撇棄了。","notes":[]},{"n":14,"t":"我們侵奪了基利提的南方和屬猶大的地，並迦勒地的南方，又用火燒了洗革拉。」","notes":[]},{"n":15,"t":"大衛問他說：「你肯領我們到敵軍那裏不肯？」他回答說：「你要向我指著神起誓，不殺我，也不將我交在我主人手裏，我就領你下到敵軍那裏。」","notes":[]},{"n":16,"t":"那人領大衛下去，見他們散在地上，吃喝跳舞，因為從非利士地和猶大地所擄來的財物甚多。","notes":[]},{"n":17,"t":"大衛從黎明直到次日晚上，擊殺他們，除了四百騎駱駝的少年人之外，沒有一個逃脫的。","notes":[]},{"n":18,"t":"亞瑪力人所擄去的財物，大衛全都奪回，並救回他的兩個妻來。","notes":[]},{"n":19,"t":"凡亞瑪力人所擄去的，無論大小、兒女、財物，大衛都奪回來，沒有失落一個。","notes":[]},{"n":20,"t":"大衛所奪來的牛群羊群，跟隨他的人趕在原有的群畜前邊，說：「這是大衛的掠物。」","notes":[]},{"n":21,"t":"大衛到了那疲乏不能跟隨、留在比梭溪的二百人那裏。他們出來迎接大衛並跟隨的人。大衛前來問他們安。","notes":[]},{"n":22,"t":"跟隨大衛人中的惡人和匪類說：「這些人既然沒有和我們同去，我們所奪的財物就不分給他們，只將他們各人的妻子兒女給他們，使他們帶去就是了。」","notes":[]},{"n":23,"t":"大衛說：「弟兄們，耶和華所賜給我們的，不可不分給他們；因為他保佑我們，將那攻擊我們的敵軍交在我們手裏。","notes":[]},{"n":24,"t":"這事誰肯依從你們呢？上陣的得多少，看守器具的也得多少；應當大家平分。」","notes":[]},{"n":25,"t":"大衛定此為以色列的律例典章，從那日直到今日。","notes":[]},{"n":26,"t":"大衛到了洗革拉，從掠物中取些送給他朋友猶大的長老，說：「這是從耶和華仇敵那裏奪來的，送你們為禮物。」","notes":[]},{"n":27,"t":"他送禮物給住伯特利的，南地拉末的，雅提珥的；","notes":[]},{"n":28,"t":"住亞羅珥的，息末的，以實提莫的；","notes":[]},{"n":29,"t":"住拉哈勒的，耶拉篾各城的，基尼各城的；","notes":[]},{"n":30,"t":"住何珥瑪的，歌拉珊的，亞撻的；","notes":[]},{"n":31,"t":"住希伯崙的，並大衛和跟隨他的人素來所到之處的人。","notes":[]}]},"31":{"heading":"掃羅和他兒子的死","verses":[{"n":1,"t":"非利士人與以色列人爭戰。以色列人在非利士人面前逃跑，在基利波有被殺仆倒的。","notes":[]},{"n":2,"t":"非利士人緊追掃羅和他兒子們，就殺了掃羅的兒子約拿單、亞比拿達、麥基舒亞。","notes":[]},{"n":3,"t":"勢派甚大，掃羅被弓箭手追上，射傷甚重，","notes":[]},{"n":4,"t":"就吩咐拿他兵器的人說：「你拔出刀來，將我刺死，免得那些未受割禮的人來刺我，凌辱我。」但拿兵器的人甚懼怕，不肯刺他；掃羅就自己伏在刀上死了。","notes":[]},{"n":5,"t":"拿兵器的人見掃羅已死，也伏在刀上死了。","notes":[]},{"n":6,"t":"這樣，掃羅和他三個兒子，與拿他兵器的人，以及跟隨他的人，都一同死亡。","notes":[]},{"n":7,"t":"住平原那邊並約旦河西的以色列人，見以色列軍兵逃跑，掃羅和他兒子都死了，也就棄城逃跑。非利士人便來住在其中。","notes":[]},{"n":8,"t":"次日，非利士人來剝那被殺之人的衣服，看見掃羅和他三個兒子仆倒在基利波山，","notes":[]},{"n":9,"t":"就割下他的首級，剝了他的軍裝，打發人到 非利士地的四境，報信與他們廟裏的偶像和眾民；","notes":["或譯：送到"]},{"n":10,"t":"又將掃羅的軍裝放在亞斯她錄廟裏，將他的屍身釘在伯‧珊的城牆上。","notes":[]},{"n":11,"t":"基列‧雅比的居民聽見非利士人向掃羅所行的事，","notes":[]},{"n":12,"t":"他們中間所有的勇士就起身，走了一夜，將掃羅和他兒子的屍身從伯‧珊城牆上取下來，送到雅比那裏，用火燒了；","notes":[]},{"n":13,"t":"將他們骸骨葬在雅比的垂絲柳樹下，就禁食七日。","notes":[]}]}},"2SA":{"1":{"heading":"大衛聽到掃羅的死訊","verses":[{"n":1,"t":"掃羅死後，大衛擊殺亞瑪力人回來，在洗革拉住了兩天。","notes":[]},{"n":2,"t":"第三天，有一人從掃羅的營裏出來，衣服撕裂，頭蒙灰塵，到大衛面前伏地叩拜。","notes":[]},{"n":3,"t":"大衛問他說：「你從哪裏來？」他說：「我從以色列的營裏逃來。」","notes":[]},{"n":4,"t":"大衛又問他說：「事情怎樣？請你告訴我。」他回答說：「百姓從陣上逃跑，也有許多人仆倒死亡；掃羅和他兒子約拿單也死了。」","notes":[]},{"n":5,"t":"大衛問報信的少年人說：「你怎麼知道掃羅和他兒子約拿單死了呢？」","notes":[]},{"n":6,"t":"報信的少年人說：「我偶然到基利波山，看見掃羅伏在自己槍上，有戰車、馬兵緊緊地追他。","notes":[]},{"n":7,"t":"他回頭看見我，就呼叫我。我說：『我在這裏。』","notes":[]},{"n":8,"t":"他問我說：『你是甚麼人？』我說：『我是亞瑪力人。』","notes":[]},{"n":9,"t":"他說：『請你來，將我殺死；因為痛苦抓住我，我的生命尚存。』","notes":[]},{"n":10,"t":"我準知他仆倒必不能活，就去將他殺死，把他頭上的冠冕、臂上的鐲子拿到我主這裏。」","notes":[]},{"n":11,"t":"大衛就撕裂衣服，跟隨他的人也是如此，","notes":[]},{"n":12,"t":"而且悲哀哭號，禁食到晚上，是因掃羅和他兒子約拿單，並耶和華的民以色列家的人，倒在刀下。","notes":[]},{"n":13,"t":"大衛問報信的少年人說：「你是哪裏的人？」他說：「我是亞瑪力客人的兒子。」","notes":[]},{"n":14,"t":"大衛說：「你伸手殺害耶和華的受膏者，怎麼不畏懼呢？」","notes":[]},{"n":15,"t":"大衛叫了一個少年人來，說：「你去殺他吧！」","notes":[]},{"n":16,"t":"大衛對他說：「你流人血的罪歸到自己的頭上，因為你親口作見證說：『我殺了耶和華的受膏者。』」少年人就把他殺了。","notes":[]},{"n":17,"t":"大衛作哀歌，弔掃羅和他兒子約拿單，","notes":[],"heads":["大衛為掃羅和約拿單作哀歌"]},{"n":18,"t":"且吩咐將這歌教導猶大人。這歌名叫「弓歌」，寫在雅煞珥書上。","notes":[]},{"n":19,"t":"歌中說：以色列啊，你尊榮者在山上被殺！大英雄何竟死亡！","notes":[]},{"n":20,"t":"不要在迦特報告；不要在亞實基倫街上傳揚；免得非利士的女子歡樂；免得未受割禮之人的女子矜誇。","notes":[]},{"n":21,"t":"基利波山哪，願你那裏沒有雨露！願你田地無土產可作供物！因為英雄的盾牌在那裏被污丟棄；掃羅的盾牌彷彿未曾抹油。","notes":[]},{"n":22,"t":"約拿單的弓箭非流敵人的血不退縮；掃羅的刀劍非剖勇士的油不收回。","notes":[]},{"n":23,"t":"掃羅和約拿單－活時相悅相愛，死時也不分離－他們比鷹更快，比獅子還強。","notes":[]},{"n":24,"t":"以色列的女子啊，當為掃羅哭號！他曾使你們穿朱紅色的美衣，使你們衣服有黃金的妝飾。","notes":[]},{"n":25,"t":"英雄何竟在陣上仆倒！約拿單何竟在山上被殺！","notes":[]},{"n":26,"t":"我兄約拿單哪，我為你悲傷！我甚喜悅你！你向我發的愛情奇妙非常，過於婦女的愛情。","notes":[]},{"n":27,"t":"英雄何竟仆倒！戰具何竟滅沒！","notes":[]}]},"2":{"heading":"大衛受膏作猶大王","verses":[{"n":1,"t":"此後，大衛問耶和華說：「我上猶大的一個城去可以嗎？」耶和華說：「可以。」大衛說：「我上哪一個城去呢？」耶和華說：「上希伯崙去。」","notes":[]},{"n":2,"t":"於是大衛和他的兩個妻－一個是耶斯列人亞希暖，一個是作過迦密人拿八妻的亞比該－都上那裏去了。","notes":[]},{"n":3,"t":"大衛也將跟隨他的人和他們各人的眷屬一同帶上去，住在希伯崙的城邑中。","notes":[]},{"n":4,"t":"猶大人來到希伯崙，在那裏膏大衛作猶大家的王。有人告訴大衛說：「葬埋掃羅的是基列‧雅比人。」","notes":[]},{"n":5,"t":"大衛就差人去見基列‧雅比人，對他們說：「你們厚待你們的主－掃羅，將他葬埋。願耶和華賜福與你們！","notes":[]},{"n":6,"t":"你們既行了這事，願耶和華以慈愛誠實待你們，我也要為此厚待你們。","notes":[]},{"n":7,"t":"現在你們的主－掃羅死了，猶大家已經膏我作他們的王，所以你們要剛強奮勇。」","notes":[]},{"n":8,"t":"掃羅的元帥尼珥的兒子押尼珥，曾將掃羅的兒子伊施波設帶過河，到瑪哈念，","notes":[],"heads":["伊施波設作以色列王"]},{"n":9,"t":"立他作王，治理基列、亞書利、耶斯列、以法蓮、便雅憫，和以色列眾人。","notes":[]},{"n":10,"t":"掃羅的兒子伊施波設登基的時候年四十歲，作以色列王二年；惟獨猶大家歸從大衛。","notes":[]},{"n":11,"t":"大衛在希伯崙作猶大家的王，共七年零六個月。","notes":[]},{"n":12,"t":"尼珥的兒子押尼珥和掃羅的兒子伊施波設的僕人從瑪哈念出來，往基遍去。","notes":[],"heads":["掃羅家和大衛家爭戰"]},{"n":13,"t":"洗魯雅的兒子約押和大衛的僕人也出來，在基遍池旁與他們相遇；一班坐在池這邊，一班坐在池那邊。","notes":[]},{"n":14,"t":"押尼珥對約押說：「讓少年人起來，在我們面前戲耍吧！」約押說：「可以。」","notes":[]},{"n":15,"t":"就按著定數起來：屬掃羅兒子伊施波設的便雅憫人過去十二名，大衛的僕人也過去十二名，","notes":[]},{"n":16,"t":"彼此揪頭，用刀刺肋，一同仆倒。所以，那地叫做希利甲‧哈素林，就在基遍。","notes":[]},{"n":17,"t":"那日的戰事凶猛，押尼珥和以色列人敗在大衛的僕人面前。","notes":[]},{"n":18,"t":"在那裏有洗魯雅的三個兒子：約押、亞比篩、亞撒黑。亞撒黑腳快如野鹿一般；","notes":[]},{"n":19,"t":"亞撒黑追趕押尼珥，直追趕他不偏左右。","notes":[]},{"n":20,"t":"押尼珥回頭說：「你是亞撒黑嗎？」回答說：「是。」","notes":[]},{"n":21,"t":"押尼珥對他說：「你或轉向左轉向右，拿住一個少年人，剝去他的戰衣。」亞撒黑卻不肯轉開不追趕他。","notes":[]},{"n":22,"t":"押尼珥又對亞撒黑說：「你轉開不追趕我吧！我何必殺你呢？若殺你，有甚麼臉見你哥哥約押呢？」","notes":[]},{"n":23,"t":"亞撒黑仍不肯轉開。故此，押尼珥就用槍鐏刺入他的肚腹，甚至槍從背後透出，亞撒黑就在那裏仆倒而死。眾人趕到亞撒黑仆倒而死的地方，就都站住。","notes":[]},{"n":24,"t":"約押和亞比篩追趕押尼珥，日落的時候，到了通基遍曠野的路旁，基亞對面的亞瑪山。","notes":[]},{"n":25,"t":"便雅憫人聚集，跟隨押尼珥站在一個山頂上。","notes":[]},{"n":26,"t":"押尼珥呼叫約押說：「刀劍豈可永遠殺人嗎？你豈不知終久必有苦楚嗎？你要等何時才叫百姓回去、不追趕弟兄呢？」","notes":[]},{"n":27,"t":"約押說：「我指著永生的神起誓：你若不說戲耍的那句話，今日早晨百姓就回去，不追趕弟兄了。」","notes":[]},{"n":28,"t":"於是約押吹角，眾民就站住，不再追趕以色列人，也不再打仗了。","notes":[]},{"n":29,"t":"押尼珥和跟隨他的人整夜經過亞拉巴，過約旦河，走過畢倫，到了瑪哈念。","notes":[]},{"n":30,"t":"約押追趕押尼珥回來，聚集眾民，見大衛的僕人中缺少了十九個人和亞撒黑。","notes":[]},{"n":31,"t":"但大衛的僕人殺了便雅憫人和跟隨押尼珥的人，共三百六十名。","notes":[]},{"n":32,"t":"眾人將亞撒黑送到伯利恆，葬在他父親的墳墓裏。約押和跟隨他的人走了一夜，天亮的時候到了希伯崙。","notes":[]}]},"3":{"heading":"大衛的兒子們","verses":[{"n":1,"t":"掃羅家和大衛家爭戰許久。大衛家日見強盛；掃羅家日見衰弱。","notes":[]},{"n":2,"t":"大衛在希伯崙得了幾個兒子：長子暗嫩是耶斯列人亞希暖所生的；","notes":[]},{"n":3,"t":"次子基利押是作過迦密人拿八的妻亞比該所生的；三子押沙龍是基述王達買的女兒瑪迦所生的；","notes":["在歷代志上三章一節作但以利"]},{"n":4,"t":"四子亞多尼雅是哈及所生的；五子示法提雅是亞比她所生的；","notes":[]},{"n":5,"t":"六子以特念是大衛的妻以格拉所生的。大衛這六個兒子都是在希伯崙生的。","notes":[]},{"n":6,"t":"掃羅家和大衛家爭戰的時候，押尼珥在掃羅家大有權勢。","notes":[],"heads":["押尼珥投效大衛"]},{"n":7,"t":"掃羅有一妃嬪，名叫利斯巴，是愛亞的女兒。一日，伊施波設對押尼珥說：「你為甚麼與我父的妃嬪同房呢？」","notes":[]},{"n":8,"t":"押尼珥因伊施波設的話就甚發怒，說：「我豈是猶大的狗頭呢？我恩待你父掃羅的家和他的弟兄、朋友，不將你交在大衛手裏，今日你竟為這婦人責備我嗎？","notes":[]},{"n":9,"t":"我若不照著耶和華起誓應許大衛的話行，廢去掃羅的位，建立大衛的位，使他治理以色列和猶大，從但直到別是巴，願神重重地降罰與我！」","notes":[],"end":10},{"n":11,"t":"伊施波設懼怕押尼珥，不敢回答一句。","notes":[]},{"n":12,"t":"押尼珥打發人去見大衛，替他說：「這國歸誰呢？」又說：「你與我立約，我必幫助你，使以色列人都歸服你。」","notes":[]},{"n":13,"t":"大衛說：「好！我與你立約。但有一件，你來見我面的時候，若不將掃羅的女兒米甲帶來，必不得見我的面。」","notes":[]},{"n":14,"t":"大衛就打發人去見掃羅的兒子伊施波設，說：「你要將我的妻米甲歸還我；她是我從前用一百非利士人的陽皮所聘定的。」","notes":[]},{"n":15,"t":"伊施波設就打發人去，將米甲從拉億的兒子、她丈夫帕鐵那裏接回來。","notes":[]},{"n":16,"t":"米甲的丈夫跟著她，一面走一面哭，直跟到巴戶琳。押尼珥說：「你回去吧！」帕鐵就回去了。","notes":[]},{"n":17,"t":"押尼珥對以色列長老說：「從前你們願意大衛作王治理你們，","notes":[]},{"n":18,"t":"現在你們可以照心願而行。因為耶和華曾論到大衛說：『我必藉我僕人大衛的手，救我民以色列脫離非利士人和眾仇敵的手。』」","notes":[]},{"n":19,"t":"押尼珥也用這話說給便雅憫人聽，又到希伯崙，將以色列人和便雅憫全家一切所喜悅的事說給大衛聽。","notes":[]},{"n":20,"t":"押尼珥帶著二十個人來到希伯崙見大衛，大衛就為押尼珥和他帶來的人設擺筵席。","notes":[]},{"n":21,"t":"押尼珥對大衛說：「我要起身去招聚以色列眾人來見我主我王，與你立約，你就可以照著心願作王。」於是大衛送押尼珥去，押尼珥就平平安安地去了。","notes":[]},{"n":22,"t":"約押和大衛的僕人攻擊敵軍，帶回許多的掠物。那時押尼珥不在希伯崙大衛那裏，因大衛已經送他去，他也平平安安地去了。","notes":[],"heads":["押尼珥被殺"]},{"n":23,"t":"約押和跟隨他的全軍到了，就有人告訴約押說：「尼珥的兒子押尼珥來見王，王送他去，他也平平安安地去了。」","notes":[]},{"n":24,"t":"約押去見王說：「你這是做甚麼呢？押尼珥來見你，你為何送他去，他就蹤影不見了呢？","notes":[]},{"n":25,"t":"你當曉得，尼珥的兒子押尼珥來是要誆哄你，要知道你的出入和你一切所行的事。」","notes":[]},{"n":26,"t":"約押從大衛那裏出來，就打發人去追趕押尼珥，在西拉井追上他，將他帶回來，大衛卻不知道。","notes":[]},{"n":27,"t":"押尼珥回到希伯崙，約押領他到城門的甕洞，假作要與他說機密話，就在那裏刺透他的肚腹，他便死了。這是報殺他兄弟亞撒黑的仇。","notes":[]},{"n":28,"t":"大衛聽見了，就說：「流尼珥的兒子押尼珥的血，這罪在耶和華面前必永不歸我和我的國。","notes":[]},{"n":29,"t":"願流他血的罪歸到約押頭上和他父的全家；又願約押家不斷有患漏症的，長大痲瘋的，架柺而行的，被刀殺死的，缺乏飲食的。」","notes":[]},{"n":30,"t":"約押和他兄弟亞比篩殺了押尼珥，是因押尼珥在基遍爭戰的時候殺了他們的兄弟亞撒黑。","notes":[]},{"n":31,"t":"大衛吩咐約押和跟隨他的眾人說：「你們當撕裂衣服，腰束麻布，在押尼珥棺前哀哭。」大衛王也跟在棺後。","notes":[],"heads":["安葬押尼珥"]},{"n":32,"t":"他們將押尼珥葬在希伯崙。王在押尼珥的墓旁放聲而哭，眾民也都哭了。","notes":[]},{"n":33,"t":"王為押尼珥舉哀，說：押尼珥何竟像愚頑人死呢？","notes":[]},{"n":34,"t":"你手未曾捆綁，腳未曾鎖住。你死，如人死在罪孽之輩手下一樣。於是眾民又為押尼珥哀哭。","notes":[]},{"n":35,"t":"日頭未落的時候，眾民來勸大衛吃飯，但大衛起誓說：「我若在日頭未落以前吃飯，或吃別物，願神重重地降罰與我！」","notes":[]},{"n":36,"t":"眾民知道了就都喜悅。凡王所行的，眾民無不喜悅。","notes":[]},{"n":37,"t":"那日，以色列眾民才知道殺尼珥的兒子押尼珥並非出於王意。","notes":[]},{"n":38,"t":"王對臣僕說：「你們豈不知今日以色列人中死了一個作元帥的大丈夫嗎？","notes":[]},{"n":39,"t":"我雖然受膏為王，今日還是軟弱；這洗魯雅的兩個兒子比我剛強。願耶和華照著惡人所行的惡報應他。」","notes":[]}]},"4":{"heading":"伊施波設被殺","verses":[{"n":1,"t":"掃羅的兒子伊施波設聽見押尼珥死在希伯崙，手就發軟；以色列眾人也都驚惶。","notes":[]},{"n":2,"t":"掃羅的兒子伊施波設有兩個軍長，一名巴拿，一名利甲，是便雅憫支派、比錄人臨門的兒子。比錄也屬便雅憫。","notes":[]},{"n":3,"t":"比錄人早先逃到基他音，在那裏寄居，直到今日。","notes":[]},{"n":4,"t":"掃羅的兒子約拿單有一個兒子名叫米非波設，是瘸腿的。掃羅和約拿單死亡的消息從耶斯列傳到的時候，他才五歲。他乳母抱著他逃跑；因為跑得太急，孩子掉在地上，腿就瘸了。","notes":[]},{"n":5,"t":"一日，比錄人臨門的兩個兒子利甲和巴拿出去，約在午熱的時候到了伊施波設的家；伊施波設正睡午覺。","notes":[]},{"n":6,"t":"他們進了房子，假作要取麥子，就刺透伊施波設的肚腹，逃跑了。","notes":[]},{"n":7,"t":"他們進房子的時候，伊施波設正在臥房裏躺在床上，他們將他殺死，割了他的首級，拿著首級在亞拉巴走了一夜，","notes":[]},{"n":8,"t":"將伊施波設的首級拿到希伯崙見大衛王，說：「王的仇敵掃羅曾尋索王的性命。看哪，這是他兒子伊施波設的首級；耶和華今日為我主我王在掃羅和他後裔的身上報了仇。」","notes":[]},{"n":9,"t":"大衛對比錄人臨門的兒子利甲和他兄弟巴拿說：「我指著救我性命脫離一切苦難、永生的耶和華起誓：","notes":[]},{"n":10,"t":"從前有人報告我說，掃羅死了，他自以為報好消息；我就拿住他，將他殺在洗革拉，這就作了他報消息的賞賜。","notes":[]},{"n":11,"t":"何況惡人將義人殺在他的床上，我豈不向你們討流他血的罪、從世上除滅你們呢？」","notes":[]},{"n":12,"t":"於是大衛吩咐少年人將他們殺了，砍斷他們的手腳，掛在希伯崙的池旁，卻將伊施波設的首級葬在希伯崙押尼珥的墳墓裏。","notes":[]}]},"5":{"heading":"大衛作猶大和以色列王","verses":[{"n":1,"t":"以色列眾支派來到希伯崙見大衛，說：「我們原是你的骨肉。","notes":[]},{"n":2,"t":"從前掃羅作我們王的時候，率領以色列人出入的是你；耶和華也曾應許你說：『你必牧養我的民以色列，作以色列的君。』」","notes":[]},{"n":3,"t":"於是以色列的長老都來到希伯崙見大衛王，大衛在希伯崙耶和華面前與他們立約，他們就膏大衛作以色列的王。","notes":[]},{"n":4,"t":"大衛登基的時候年三十歲，在位四十年；","notes":[]},{"n":5,"t":"在希伯崙作猶大王七年零六個月，在耶路撒冷作以色列和猶大王三十三年。","notes":[]},{"n":6,"t":"大衛和跟隨他的人到了耶路撒冷，要攻打住那地方的耶布斯人。耶布斯人對大衛說：「你若不趕出瞎子、瘸子，必不能進這地方」；心裏想大衛決不能進去。","notes":[]},{"n":7,"t":"然而大衛攻取錫安的保障，就是大衛的城。","notes":[]},{"n":8,"t":"當日，大衛說：「誰攻打耶布斯人，當上水溝攻打我心裏所恨惡的瘸子、瞎子。」從此有俗語說：「在那裏有瞎子、瘸子，他不能進屋去。」","notes":[]},{"n":9,"t":"大衛住在保障裏，給保障起名叫大衛城。大衛又從米羅以裏，周圍築牆。","notes":[]},{"n":10,"t":"大衛日見強盛，因為耶和華－萬軍之神與他同在。","notes":[]},{"n":11,"t":"泰爾王希蘭將香柏木運到大衛那裏，又差遣使者和木匠、石匠給大衛建造宮殿。","notes":[]},{"n":12,"t":"大衛就知道耶和華堅立他作以色列王，又為自己的民以色列使他的國興旺。","notes":[]},{"n":13,"t":"大衛離開希伯崙之後，在耶路撒冷又立后妃，又生兒女。","notes":[]},{"n":14,"t":"在耶路撒冷所生的兒子是沙母亞、朔罷、拿單、所羅門、","notes":[]},{"n":15,"t":"益轄、以利書亞、尼斐、雅非亞、","notes":[]},{"n":16,"t":"以利沙瑪、以利雅大、以利法列。","notes":[]},{"n":17,"t":"非利士人聽見人膏大衛作以色列王，非利士眾人就上來尋索大衛；大衛聽見，就下到保障。","notes":[],"heads":["戰勝非利士人"]},{"n":18,"t":"非利士人來了，布散在利乏音谷。","notes":[]},{"n":19,"t":"大衛求問耶和華說：「我可以上去攻打非利士人嗎？你將他們交在我手裏嗎？」耶和華說：「你可以上去，我必將非利士人交在你手裏。」","notes":[]},{"n":20,"t":"大衛來到巴力‧毗拉心，在那裏擊殺非利士人，說：「耶和華在我面前沖破敵人，如同水沖去一般。」因此稱那地方為巴力‧毗拉心。","notes":[]},{"n":21,"t":"非利士人將偶像撇在那裏，大衛和跟隨他的人拿去了。","notes":[]},{"n":22,"t":"非利士人又上來，布散在利乏音谷。","notes":[]},{"n":23,"t":"大衛求問耶和華；耶和華說：「不要一直地上去，要轉到他們後頭，從桑林對面攻打他們。","notes":[]},{"n":24,"t":"你聽見桑樹梢上有腳步的聲音，就要急速前去，因為那時耶和華已經在你前頭去攻打非利士人的軍隊。」","notes":[]},{"n":25,"t":"大衛就遵著耶和華所吩咐的去行，攻打非利士人，從迦巴直到基色。","notes":[]}]},"6":{"heading":"運約櫃到耶路撒冷","verses":[{"n":1,"t":"大衛又聚集以色列中所有挑選的人三萬。","notes":[]},{"n":2,"t":"大衛起身，率領跟隨他的眾人前往，要從巴拉‧猶大將神的約櫃運來；這約櫃就是坐在二基路伯上萬軍之耶和華留名的約櫃。","notes":[]},{"n":3,"t":"他們將神的約櫃從岡上亞比拿達的家裏抬出來，放在新車上；亞比拿達的兩個兒子烏撒和亞希約趕這新車。","notes":[]},{"n":4,"t":"他們將神的約櫃從岡上亞比拿達家裏抬出來的時候，亞希約在櫃前行走。","notes":[]},{"n":5,"t":"大衛和以色列的全家在耶和華面前，用松木製造的各樣樂器和琴、瑟、鼓、鈸、鑼，作樂跳舞。","notes":[]},{"n":6,"t":"到了拿艮的禾場，因為牛失前蹄，烏撒就伸手扶住神的約櫃。","notes":["或譯：驚跳"]},{"n":7,"t":"神耶和華向烏撒發怒，因這錯誤擊殺他，他就死在神的約櫃旁。","notes":[]},{"n":8,"t":"大衛因耶和華擊殺 烏撒，心裏愁煩，就稱那地方為毗列斯‧烏撒，直到今日。","notes":["原文是闖殺"]},{"n":9,"t":"那日，大衛懼怕耶和華，說：「耶和華的約櫃怎可運到我這裏來？」","notes":[]},{"n":10,"t":"於是大衛不肯將耶和華的約櫃運進大衛的城，卻運到迦特人俄別‧以東的家中。","notes":[]},{"n":11,"t":"耶和華的約櫃在迦特人俄別‧以東家中三個月；耶和華賜福給俄別‧以東和他的全家。","notes":[]},{"n":12,"t":"有人告訴大衛王說：「耶和華因為約櫃賜福給俄別‧以東的家和一切屬他的。」大衛就去，歡歡喜喜地將神的約櫃從俄別‧以東家中抬到大衛的城裏。","notes":[]},{"n":13,"t":"抬耶和華約櫃的人走了六步，大衛就獻牛與肥羊為祭。","notes":[]},{"n":14,"t":"大衛穿著細麻布的以弗得，在耶和華面前極力跳舞。","notes":[]},{"n":15,"t":"這樣，大衛和以色列的全家歡呼吹角，將耶和華的約櫃抬上來。","notes":[]},{"n":16,"t":"耶和華的約櫃進了大衛城的時候，掃羅的女兒米甲從窗戶裏觀看，見大衛王在耶和華面前踴躍跳舞，心裏就輕視他。","notes":[]},{"n":17,"t":"眾人將耶和華的約櫃請進去，安放在所預備的地方，就是在大衛所搭的帳幕裏。大衛在耶和華面前獻燔祭和平安祭。","notes":[]},{"n":18,"t":"大衛獻完了燔祭和平安祭，就奉萬軍之耶和華的名給民祝福，","notes":[]},{"n":19,"t":"並且分給以色列眾人，無論男女，每人一個餅，一塊肉，一個葡萄餅；眾人就各回各家去了。","notes":[]},{"n":20,"t":"大衛回家要給眷屬祝福；掃羅的女兒米甲出來迎接他，說：「以色列王今日在臣僕的婢女眼前露體，如同一個輕賤人無恥露體一樣，有好大的榮耀啊！」","notes":[]},{"n":21,"t":"大衛對米甲說：「這是在耶和華面前；耶和華已揀選我，廢了你父和你父的全家，立我作耶和華民以色列的君，所以我必在耶和華面前跳舞。","notes":[]},{"n":22,"t":"我也必更加卑微，自己看為輕賤。你所說的那些婢女，她們倒要尊敬我。」","notes":[]},{"n":23,"t":"掃羅的女兒米甲，直到死日，沒有生養兒女。","notes":[]}]},"7":{"heading":"拿單傳信息給大衛","verses":[{"n":1,"t":"王住在自己宮中，耶和華使他安靖，不被四圍的仇敵擾亂。","notes":[]},{"n":2,"t":"那時，王對先知拿單說：「看哪，我住在香柏木的宮中，神的約櫃反在幔子裏。」","notes":[]},{"n":3,"t":"拿單對王說：「你可以照你的心意而行，因為耶和華與你同在。」","notes":[]},{"n":4,"t":"當夜，耶和華的話臨到拿單說：","notes":[]},{"n":5,"t":"「你去告訴我僕人大衛，說耶和華如此說：『你豈可建造殿宇給我居住呢？","notes":[]},{"n":6,"t":"自從我領以色列人出埃及直到今日，我未曾住過殿宇，常在會幕和帳幕中行走。","notes":[]},{"n":7,"t":"凡我同以色列人所走的地方，我何曾向以色列一支派的士師，就是我吩咐牧養我民以色列的說：你們為何不給我建造香柏木的殿宇呢？』","notes":[]},{"n":8,"t":"「現在，你要告訴我僕人大衛，說萬軍之耶和華如此說：『我從羊圈中將你召來，叫你不再跟從羊群，立你作我民以色列的君。","notes":[]},{"n":9,"t":"你無論往哪裏去，我常與你同在，剪除你的一切仇敵。我必使你得大名，好像世上大大有名的人一樣。","notes":[]},{"n":10,"t":"我必為我民以色列選定一個地方，栽培他們，使他們住自己的地方，不再遷移；凶惡之子也不像從前擾害他們，","notes":[]},{"n":11,"t":"並不像我命士師治理我民以色列的時候一樣。我必使你安靖，不被一切仇敵擾亂，並且我－耶和華應許你，必為你建立家室。","notes":[]},{"n":12,"t":"你壽數滿足、與你列祖同睡的時候，我必使你的後裔接續你的位；我也必堅定他的國。","notes":[]},{"n":13,"t":"他必為我的名建造殿宇；我必堅定他的國位，直到永遠。","notes":[]},{"n":14,"t":"我要作他的父，他要作我的子；他若犯了罪，我必用人的杖責打他，用人的鞭責罰他。","notes":[]},{"n":15,"t":"但我的慈愛仍不離開他，像離開在你面前所廢棄的掃羅一樣。","notes":[]},{"n":16,"t":"你的家和你的國必在我面前永遠堅立。你的國位也必堅定，直到永遠。』」","notes":["原文是你"]},{"n":17,"t":"拿單就按這一切話，照這默示，告訴大衛。","notes":[]},{"n":18,"t":"於是大衛王進去，坐在耶和華面前，說：「主耶和華啊，我是誰？我的家算甚麼？你竟使我到這地步呢？","notes":[],"heads":["大衛的祈禱和感恩"]},{"n":19,"t":"主耶和華啊，這在你眼中還看為小，又應許你僕人的家至於久遠。主耶和華啊，這豈是人所常遇的事嗎？","notes":[]},{"n":20,"t":"主耶和華啊，我還有何言可以對你說呢？因為你知道你的僕人。","notes":[]},{"n":21,"t":"你行這大事使僕人知道，是因你所應許的話，也是照你的心意。","notes":[]},{"n":22,"t":"主耶和華啊，你本為大，照我們耳中聽見，沒有可比你的；除你以外再無神。","notes":[]},{"n":23,"t":"世上有何民能比你的民以色列呢？你從埃及救贖他們作自己的子民，又在你贖出來的民面前行大而可畏的事，驅逐列邦人和他們的神，顯出你的大名。","notes":[]},{"n":24,"t":"你曾堅立你的民以色列作你的子民，直到永遠；你－耶和華也作了他們的神。","notes":[]},{"n":25,"t":"「耶和華神啊，你所應許僕人和僕人家的話，求你堅定，直到永遠；照你所說的而行。","notes":[]},{"n":26,"t":"願人永遠尊你的名為大，說：『萬軍之耶和華是治理以色列的神。』這樣，你僕人大衛的家必在你面前堅立。","notes":[]},{"n":27,"t":"萬軍之耶和華－以色列的神啊，因你啟示你的僕人說：『我必為你建立家室』，所以僕人大膽向你如此祈禱。","notes":[]},{"n":28,"t":"「主耶和華啊，惟有你是神。你的話是真實的；你也應許將這福氣賜給僕人。","notes":[]},{"n":29,"t":"現在求你賜福與僕人的家，可以永存在你面前。主耶和華啊，這是你所應許的。願你永遠賜福與僕人的家！」","notes":[]}]},"8":{"heading":"耶和華使大衛得勝","verses":[{"n":1,"t":"此後，大衛攻打非利士人，把他們治服，從他們手下奪取了京城的權柄；","notes":["原文是母城的嚼環"]},{"n":2,"t":"又攻打摩押人，使他們躺臥在地上，用繩量一量：量二繩的殺了，量一繩的存留。摩押人就歸服大衛，給他進貢。","notes":[]},{"n":3,"t":"瑣巴王利合的兒子哈大底謝往大河去，要奪回他的國權。大衛就攻打他，","notes":[]},{"n":4,"t":"擒拿了他的馬兵一千七百，步兵二萬，將拉戰車的馬砍斷蹄筋，但留下一百輛車的馬。","notes":[]},{"n":5,"t":"大馬士革的亞蘭人來幫助瑣巴王哈大底謝，大衛就殺了亞蘭人二萬二千。","notes":[]},{"n":6,"t":"於是大衛在大馬士革的亞蘭地設立防營，亞蘭人就歸服他，給他進貢。大衛無論往哪裏去，耶和華都使他得勝。","notes":[]},{"n":7,"t":"他奪了哈大底謝臣僕所拿的金盾牌，帶到耶路撒冷。","notes":[]},{"n":8,"t":"大衛王又從屬哈大底謝的比他和比羅他城中奪取了許多的銅。","notes":[]},{"n":9,"t":"哈馬王陀以聽見大衛殺敗哈大底謝的全軍，","notes":[]},{"n":10,"t":"就打發他兒子約蘭去見大衛王，問他的安，為他祝福，因為他殺敗了哈大底謝（原來陀以與哈大底謝常常爭戰）。約蘭帶了金銀銅的器皿來，","notes":[]},{"n":11,"t":"大衛王將這些器皿和他治服各國所得來的金銀都分別為聖，獻給耶和華，","notes":[]},{"n":12,"t":"就是從亞蘭、摩押、亞捫、非利士、亞瑪力人所得來的，以及從瑣巴王利合的兒子哈大底謝所掠之物。","notes":[]},{"n":13,"t":"大衛在鹽谷擊殺了亞蘭一萬八千人回來，就得了大名；","notes":["或譯：以東，見詩篇六十篇詩題"]},{"n":14,"t":"又在以東全地設立防營，以東人就都歸服大衛。大衛無論往哪裏去，耶和華都使他得勝。","notes":[]},{"n":15,"t":"大衛作以色列眾人的王，又向眾民秉公行義。","notes":[]},{"n":16,"t":"洗魯雅的兒子約押作元帥；亞希律的兒子約沙法作史官；","notes":[]},{"n":17,"t":"亞希突的兒子撒督和亞比亞他的兒子亞希米勒作祭司長；西萊雅作書記；","notes":[]},{"n":18,"t":"耶何耶大的兒子比拿雅統轄基利提人和比利提人。大衛的眾子都作領袖。","notes":[]}]},"9":{"heading":"大衛和米非波設","verses":[{"n":1,"t":"大衛問說：「掃羅家還有剩下的人沒有？我要因約拿單的緣故向他施恩。」","notes":[]},{"n":2,"t":"掃羅家有一個僕人，名叫洗巴，有人叫他來見大衛，王問他說：「你是洗巴嗎？」回答說：「僕人是。」","notes":[]},{"n":3,"t":"王說：「掃羅家還有人沒有？我要照神的慈愛恩待他。」洗巴對王說：「還有約拿單的一個兒子，是瘸腿的。」","notes":[]},{"n":4,"t":"王說：「他在哪裏？」洗巴對王說：「他在羅‧底巴，亞米利的兒子瑪吉家裏。」","notes":[]},{"n":5,"t":"於是大衛王打發人去，從羅‧底巴亞米利的兒子瑪吉家裏召了他來。","notes":[]},{"n":6,"t":"掃羅的孫子、約拿單的兒子米非波設來見大衛，伏地叩拜。大衛說：「米非波設！」米非波設說：「僕人在此。」","notes":[]},{"n":7,"t":"大衛說：「你不要懼怕，我必因你父親約拿單的緣故施恩與你，將你祖父掃羅的一切田地都歸還你；你也可以常與我同席吃飯。」","notes":[]},{"n":8,"t":"米非波設又叩拜，說：「僕人算甚麼，不過如死狗一般，竟蒙王這樣眷顧！」","notes":[]},{"n":9,"t":"王召了掃羅的僕人洗巴來，對他說：「我已將屬掃羅和他的一切家產都賜給你主人的兒子了。","notes":[]},{"n":10,"t":"你和你的眾子、僕人要為你主人的兒子米非波設耕種田地，把所產的拿來供他食用；他卻要常與我同席吃飯。」洗巴有十五個兒子，二十個僕人。","notes":[]},{"n":11,"t":"洗巴對王說：「凡我主我王吩咐僕人的，僕人都必遵行。」王又說：「米非波設必與我同席吃飯，如王的兒子一樣。」","notes":[]},{"n":12,"t":"米非波設有一個小兒子，名叫米迦。凡住在洗巴家裏的人都作了米非波設的僕人。","notes":[]},{"n":13,"t":"於是米非波設住在耶路撒冷，常與王同席吃飯。他兩腿都是瘸的。","notes":[]}]},"10":{"heading":"擊敗亞捫人和亞蘭人","verses":[{"n":1,"t":"此後，亞捫人的王死了，他兒子哈嫩接續他作王。","notes":[]},{"n":2,"t":"大衛說：「我要照哈嫩的父親拿轄厚待我的恩典厚待哈嫩。」於是大衛差遣臣僕，為他喪父安慰他。大衛的臣僕到了亞捫人的境內。","notes":[]},{"n":3,"t":"但亞捫人的首領對他們的主哈嫩說：「大衛差人來安慰你，你想他是尊敬你父親嗎？他差臣僕來不是詳察窺探、要傾覆這城嗎？」","notes":[]},{"n":4,"t":"哈嫩便將大衛臣僕的鬍鬚剃去一半，又割斷他們下半截的衣服，使他們露出下體，打發他們回去。","notes":[]},{"n":5,"t":"有人告訴大衛，他就差人去迎接他們，（因為他們甚覺羞恥），告訴他們說：「可以住在耶利哥，等到鬍鬚長起再回來。」","notes":[]},{"n":6,"t":"亞捫人知道大衛憎惡他們，就打發人去，招募伯‧利合的亞蘭人和瑣巴的亞蘭人，步兵二萬，與瑪迦王的人一千、陀伯人一萬二千。","notes":[]},{"n":7,"t":"大衛聽見了，就差派約押統帶勇猛的全軍出去。","notes":[]},{"n":8,"t":"亞捫人出來，在城門前擺陣；瑣巴與利合的亞蘭人、陀伯人，並瑪迦人，另在郊野擺陣。","notes":[]},{"n":9,"t":"約押看見敵人在他前後擺陣，就從以色列軍中挑選精兵，使他們對著亞蘭人擺陣。","notes":[]},{"n":10,"t":"其餘的兵交與他兄弟亞比篩，對著亞捫人擺陣。","notes":[]},{"n":11,"t":"約押對亞比篩說：「亞蘭人若強過我，你就來幫助我；亞捫人若強過你，我就去幫助你。","notes":[]},{"n":12,"t":"我們都當剛強，為本國的民和神的城邑作大丈夫。願耶和華憑他的意旨而行！」","notes":[]},{"n":13,"t":"於是，約押和跟隨他的人前進攻打亞蘭人；亞蘭人在約押面前逃跑。","notes":[]},{"n":14,"t":"亞捫人見亞蘭人逃跑，他們也在亞比篩面前逃跑進城。約押就離開亞捫人那裏，回耶路撒冷去了。","notes":[]},{"n":15,"t":"亞蘭人見自己被以色列人打敗，就又聚集。","notes":[]},{"n":16,"t":"哈大底謝差遣人，將大河那邊的亞蘭人調來；他們到了希蘭，哈大底謝的將軍朔法率領他們。","notes":[]},{"n":17,"t":"有人告訴大衛，他就聚集以色列眾人，過約旦河，來到希蘭。亞蘭人迎著大衛擺陣，與他打仗。","notes":[]},{"n":18,"t":"亞蘭人在以色列人面前逃跑；大衛殺了亞蘭七百輛戰車的人，四萬馬兵，又殺了亞蘭的將軍朔法。","notes":[]},{"n":19,"t":"屬哈大底謝的諸王見自己被以色列人打敗，就與以色列人和好，歸服他們。於是亞蘭人不敢再幫助亞捫人了。","notes":[]}]},"11":{"heading":"大衛和拔示巴","verses":[{"n":1,"t":"過了一年，到列王出戰的時候，大衛又差派約押，率領臣僕和以色列眾人出戰。他們就打敗亞捫人，圍攻拉巴。大衛仍住在耶路撒冷。","notes":[]},{"n":2,"t":"一日，太陽平西，大衛從床上起來，在王宮的平頂上遊行，看見一個婦人沐浴，容貌甚美，","notes":[]},{"n":3,"t":"大衛就差人打聽那婦人是誰。有人說：「她是以連的女兒，赫人烏利亞的妻拔示巴。」","notes":[]},{"n":4,"t":"大衛差人去，將婦人接來；那時她的月經才得潔淨。她來了，大衛與她同房，她就回家去了。","notes":[]},{"n":5,"t":"於是她懷了孕，打發人去告訴大衛說：「我懷了孕。」","notes":[]},{"n":6,"t":"大衛差人到約押那裏，說：「你打發赫人烏利亞到我這裏來。」約押就打發烏利亞去見大衛。","notes":[]},{"n":7,"t":"烏利亞來了，大衛問約押好，也問兵好，又問爭戰的事怎樣。","notes":[]},{"n":8,"t":"大衛對烏利亞說：「你回家去，洗洗腳吧！」烏利亞出了王宮，隨後王送他一分食物。","notes":[]},{"n":9,"t":"烏利亞卻和他主人的僕人一同睡在宮門外，沒有回家去。","notes":[]},{"n":10,"t":"有人告訴大衛說：「烏利亞沒有回家去。」大衛就問烏利亞說：「你從遠路上來，為甚麼不回家去呢？」","notes":[]},{"n":11,"t":"烏利亞對大衛說：「約櫃和以色列與猶大兵都住在棚裏，我主約押和我主的僕人都在田野安營，我豈可回家吃喝、與妻子同寢呢？我敢在王面前起誓：我決不行這事！」","notes":["或譯：王","原文是我指著王和王的性命起誓"]},{"n":12,"t":"大衛吩咐烏利亞說：「你今日仍住在這裏，明日我打發你去。」於是烏利亞那日和次日住在耶路撒冷。","notes":[]},{"n":13,"t":"大衛召了烏利亞來，叫他在自己面前吃喝，使他喝醉。到了晚上，烏利亞出去與他主的僕人一同住宿，還沒有回到家裏去。","notes":[]},{"n":14,"t":"次日早晨，大衛寫信與約押，交烏利亞隨手帶去。","notes":[]},{"n":15,"t":"信內寫著說：「要派烏利亞前進，到陣勢極險之處，你們便退後，使他被殺。」","notes":[]},{"n":16,"t":"約押圍城的時候，知道敵人那裏有勇士，便將烏利亞派在那裏。","notes":[]},{"n":17,"t":"城裏的人出來和約押打仗；大衛的僕人中有幾個被殺的，赫人烏利亞也死了。","notes":[]},{"n":18,"t":"於是，約押差人去將爭戰的一切事告訴大衛，","notes":[]},{"n":19,"t":"又囑咐使者說：「你把爭戰的一切事對王說完了，","notes":[]},{"n":20,"t":"王若發怒，問你說：『你們打仗為甚麼挨近城牆呢？豈不知敵人必從城上射箭嗎？","notes":[]},{"n":21,"t":"從前打死耶路‧比設兒子亞比米勒的是誰呢？豈不是一個婦人從城上拋下一塊上磨石來，打在他身上，他就死在提備斯嗎？你們為甚麼挨近城牆呢？』你就說：『王的僕人－赫人烏利亞也死了。』」","notes":["就是耶路‧巴力，見士師記九章一節"]},{"n":22,"t":"使者起身，來見大衛，照著約押所吩咐他的話奏告大衛。","notes":[]},{"n":23,"t":"使者對大衛說：「敵人強過我們，出到郊野與我們打仗，我們追殺他們，直到城門口。","notes":[]},{"n":24,"t":"射箭的從城上射王的僕人，射死幾個，赫人烏利亞也死了。」","notes":[]},{"n":25,"t":"王向使者說：「你告訴約押說：『不要因這事愁悶，刀劍或吞滅這人或吞滅那人，沒有一定的；你只管竭力攻城，將城傾覆。』可以用這話勉勵約押。」","notes":[]},{"n":26,"t":"烏利亞的妻聽見丈夫烏利亞死了，就為他哀哭。","notes":[]},{"n":27,"t":"哀哭的日子過了，大衛差人將她接到宮裏，她就作了大衛的妻，給大衛生了一個兒子。但大衛所行的這事，耶和華甚不喜悅。","notes":[]}]},"12":{"heading":"拿單的信息和大衛的悔改","verses":[{"n":1,"t":"耶和華差遣拿單去見大衛。拿單到了大衛那裏，對他說：「在一座城裏有兩個人：一個是富戶，一個是窮人。","notes":[]},{"n":2,"t":"富戶有許多牛群羊群；","notes":[]},{"n":3,"t":"窮人除了所買來養活的一隻小母羊羔之外，別無所有。羊羔在他家裏和他兒女一同長大，吃他所吃的，喝他所喝的，睡在他懷中，在他看來如同女兒一樣。","notes":[]},{"n":4,"t":"有一客人來到這富戶家裏；富戶捨不得從自己的牛群羊群中取一隻預備給客人吃，卻取了那窮人的羊羔，預備給客人吃。」","notes":[]},{"n":5,"t":"大衛就甚惱怒那人，對拿單說：「我指著永生的耶和華起誓，行這事的人該死！","notes":[]},{"n":6,"t":"他必償還羊羔四倍；因為他行這事，沒有憐恤的心。」","notes":[]},{"n":7,"t":"拿單對大衛說：「你就是那人！耶和華－以色列的神如此說：『我膏你作以色列的王，救你脫離掃羅的手。","notes":[]},{"n":8,"t":"我將你主人的家業賜給你，將你主人的妻交在你懷裏，又將以色列和猶大家賜給你；你若還以為不足，我早就加倍地賜給你。","notes":[]},{"n":9,"t":"你為甚麼藐視耶和華的命令，行他眼中看為惡的事呢？你借亞捫人的刀殺害赫人烏利亞，又娶了他的妻為妻。","notes":[]},{"n":10,"t":"你既藐視我，娶了赫人烏利亞的妻為妻，所以刀劍必永不離開你的家。』","notes":[]},{"n":11,"t":"耶和華如此說：『我必從你家中興起禍患攻擊你；我必在你眼前把你的妃嬪賜給別人，他在日光之下就與她們同寢。","notes":[]},{"n":12,"t":"你在暗中行這事，我卻要在以色列眾人面前，日光之下，報應你。』」","notes":[]},{"n":13,"t":"大衛對拿單說：「我得罪耶和華了！」拿單說：「耶和華已經除掉你的罪，你必不至於死。","notes":[]},{"n":14,"t":"只是你行這事，叫耶和華的仇敵大得褻瀆的機會，故此，你所得的孩子必定要死。」","notes":[]},{"n":15,"t":"拿單就回家去了。耶和華擊打烏利亞妻給大衛所生的孩子，使他得重病。","notes":[]},{"n":16,"t":"所以大衛為這孩子懇求神，而且禁食，進入內室，終夜躺在地上。","notes":[]},{"n":17,"t":"他家中的老臣來到他旁邊，要把他從地上扶起來，他卻不肯起來，也不同他們吃飯。","notes":[]},{"n":18,"t":"到第七日，孩子死了。大衛的臣僕不敢告訴他孩子死了，因他們說：「孩子還活著的時候，我們勸他，他尚且不肯聽我們的話，若告訴他孩子死了，豈不更加憂傷嗎？」","notes":[]},{"n":19,"t":"大衛見臣僕彼此低聲說話，就知道孩子死了，問臣僕說：「孩子死了嗎？」他們說：「死了。」","notes":[]},{"n":20,"t":"大衛就從地上起來，沐浴，抹膏，換了衣裳，進耶和華的殿敬拜；然後回宮，吩咐人擺飯，他便吃了。","notes":[]},{"n":21,"t":"臣僕問他說：「你所行的是甚麼意思？孩子活著的時候，你禁食哭泣；孩子死了，你倒起來吃飯。」","notes":[]},{"n":22,"t":"大衛說：「孩子還活著，我禁食哭泣；因為我想，或者耶和華憐恤我，使孩子不死也未可知。","notes":[]},{"n":23,"t":"孩子死了，我何必禁食，我豈能使他返回呢？我必往他那裏去，他卻不能回我這裏來。」","notes":[]},{"n":24,"t":"大衛安慰他的妻拔示巴，與她同寢，她就生了兒子，給他起名叫所羅門。耶和華也喜愛他，","notes":[],"heads":["所羅門出生"]},{"n":25,"t":"就藉先知拿單賜他一個名字，叫耶底底亞，因為耶和華愛他。","notes":[]},{"n":26,"t":"約押攻取亞捫人的京城拉巴。","notes":[],"heads":["大衛攻取拉巴"]},{"n":27,"t":"約押打發使者去見大衛，說：「我攻打拉巴，取其水城。","notes":[]},{"n":28,"t":"現在你要聚集其餘的軍兵來，安營圍攻這城，恐怕我取了這城，人就以我的名叫這城。」","notes":[]},{"n":29,"t":"於是大衛聚集眾軍，往拉巴去攻城，就取了這城，","notes":[]},{"n":30,"t":"奪了亞捫人之王所戴的金冠冕，其上的金子重一他連得，又嵌著寶石。人將這冠冕戴在大衛頭上。大衛從城裏奪了許多財物，","notes":["王：或譯瑪勒堪；瑪勒堪就是米勒公，又名摩洛，亞捫族之神名"]},{"n":31,"t":"將城裏的人拉出來，放在鋸下，或鐵耙下，或鐵斧下，或叫他經過磚窯；大衛待亞捫各城的居民都是如此。其後，大衛和眾軍都回耶路撒冷去了。","notes":["或譯：強他們用鋸，或用打糧食的鐵器，或用鐵斧做工，或使在磚窯裏服役"]}]},"13":{"heading":"暗嫩和她瑪","verses":[{"n":1,"t":"大衛的兒子押沙龍有一個美貌的妹子，名叫她瑪。大衛的兒子暗嫩愛她。","notes":[]},{"n":2,"t":"暗嫩為他妹子她瑪憂急成病。她瑪還是處女，暗嫩以為難向她行事。","notes":[]},{"n":3,"t":"暗嫩有一個朋友，名叫約拿達，是大衛長兄示米亞的兒子。這約拿達為人極其狡猾；","notes":[]},{"n":4,"t":"他問暗嫩說：「王的兒子啊，為何一天比一天瘦弱呢？請你告訴我。」暗嫩回答說：「我愛我兄弟押沙龍的妹子她瑪。」","notes":[]},{"n":5,"t":"約拿達說：「你不如躺在床上裝病；你父親來看你，就對他說：『求父叫我妹子她瑪來，在我眼前預備食物，遞給我吃，使我看見，好從她手裏接過來吃。』」","notes":[]},{"n":6,"t":"於是暗嫩躺臥裝病。王來看他，他對王說：「求父叫我妹子她瑪來，在我眼前為我做兩個餅，我好從她手裏接過來吃。」","notes":[]},{"n":7,"t":"大衛就打發人到宮裏，對她瑪說：「你往你哥哥暗嫩的屋裏去，為他預備食物。」","notes":[]},{"n":8,"t":"她瑪就到她哥哥暗嫩的屋裏；暗嫩正躺臥。她瑪摶麵，在他眼前做餅，且烤熟了，","notes":[]},{"n":9,"t":"在他面前將餅從鍋裏倒出來，他卻不肯吃，便說：「眾人離開我出去吧！」眾人就都離開他，出去了。","notes":[]},{"n":10,"t":"暗嫩對她瑪說：「你把食物拿進臥房，我好從你手裏接過來吃。」她瑪就把所做的餅拿進臥房，到她哥哥暗嫩那裏，","notes":[]},{"n":11,"t":"拿著餅上前給他吃，他便拉住她瑪，說：「我妹妹，你來與我同寢。」","notes":[]},{"n":12,"t":"她瑪說：「我哥哥，不要玷辱我。以色列人中不當這樣行，你不要做這醜事；","notes":[]},{"n":13,"t":"你玷辱了我，我何以掩蓋我的羞恥呢？你在以色列中也成了愚妄人。你可以求王，他必不禁止我歸你。」","notes":[]},{"n":14,"t":"但暗嫩不肯聽她的話，因比她力大，就玷辱她，與她同寢。","notes":[]},{"n":15,"t":"隨後，暗嫩極其恨她，那恨她的心比先前愛她的心更甚，對她說：「你起來，去吧！」","notes":[]},{"n":16,"t":"她瑪說：「不要這樣！你趕出我去的這罪比你才行的更重！」但暗嫩不肯聽她的話，","notes":[]},{"n":17,"t":"就叫伺候自己的僕人來，說：「將這個女子趕出去！她一出去，你就關門，上閂。」","notes":[]},{"n":18,"t":"那時她瑪穿著彩衣，因為沒有出嫁的公主都是這樣穿。暗嫩的僕人就把她趕出去，關門上閂。","notes":[]},{"n":19,"t":"她瑪把灰塵撒在頭上，撕裂所穿的彩衣，以手抱頭，一面行走，一面哭喊。","notes":[]},{"n":20,"t":"她胞兄押沙龍問她說：「莫非你哥哥暗嫩與你親近了嗎？我妹妹，暫且不要作聲，他是你的哥哥，不要將這事放在心上。」她瑪就孤孤單單地住在她胞兄押沙龍家裏。","notes":[]},{"n":21,"t":"大衛王聽見這事，就甚發怒。","notes":[]},{"n":22,"t":"押沙龍並不和他哥哥暗嫩說好說歹；因為暗嫩玷辱他妹妹她瑪，所以押沙龍恨惡他。","notes":[]},{"n":23,"t":"過了二年，在靠近以法蓮的巴力‧夏瑣有人為押沙龍剪羊毛；押沙龍請王的眾子與他同去。","notes":[],"heads":["押沙龍為妹報仇"]},{"n":24,"t":"押沙龍來見王，說：「現在有人為僕人剪羊毛，請王和王的臣僕與僕人同去。」","notes":[]},{"n":25,"t":"王對押沙龍說：「我兒，我們不必都去，恐怕使你耗費太多。」押沙龍再三請王，王仍是不肯去，只為他祝福。","notes":[]},{"n":26,"t":"押沙龍說：「王若不去，求王許我哥哥暗嫩同去。」王說：「何必要他去呢？」","notes":[]},{"n":27,"t":"押沙龍再三求王，王就許暗嫩和王的眾子與他同去。","notes":[]},{"n":28,"t":"押沙龍吩咐僕人說：「你們注意，看暗嫩飲酒暢快的時候，我對你們說殺暗嫩，你們便殺他，不要懼怕。這不是我吩咐你們的嗎？你們只管壯膽奮勇！」","notes":[]},{"n":29,"t":"押沙龍的僕人就照押沙龍所吩咐的，向暗嫩行了。王的眾子都起來，各人騎上騾子，逃跑了。","notes":[]},{"n":30,"t":"他們還在路上，有風聲傳到大衛那裏，說：「押沙龍將王的眾子都殺了，沒有留下一個。」","notes":[]},{"n":31,"t":"王就起來，撕裂衣服，躺在地上。王的臣僕也都撕裂衣服，站在旁邊。","notes":[]},{"n":32,"t":"大衛的長兄，示米亞的兒子約拿達說：「我主，不要以為王的眾子－少年人都殺了，只有暗嫩一個人死了。自從暗嫩玷辱押沙龍妹子她瑪的那日，押沙龍就定意殺暗嫩了。","notes":[]},{"n":33,"t":"現在，我主我王，不要把這事放在心上，以為王的眾子都死了，只有暗嫩一個人死了。」","notes":[]},{"n":34,"t":"押沙龍逃跑了。守望的少年人舉目觀看，見有許多人從山坡的路上來。","notes":[]},{"n":35,"t":"約拿達對王說：「看哪，王的眾子都來了，果然與你僕人所說的相合。」","notes":[]},{"n":36,"t":"話才說完，王的眾子都到了，放聲大哭；王和臣僕也都哭得甚慟。","notes":[]},{"n":37,"t":"押沙龍逃到基述王亞米忽的兒子達買那裏去了。大衛天天為他兒子悲哀。","notes":[]},{"n":38,"t":"押沙龍逃到基述，在那裏住了三年。","notes":[]},{"n":39,"t":"暗嫩死了以後，大衛王得了安慰，心裏切切想念押沙龍。","notes":[]}]},"14":{"heading":"約押設法讓押沙龍回來","verses":[{"n":1,"t":"洗魯雅的兒子約押，知道王心裏想念押沙龍，","notes":[]},{"n":2,"t":"就打發人往提哥亞去，從那裏叫了一個聰明的婦人來，對她說：「請你假裝居喪的，穿上孝衣，不要用膏抹身，要裝作為死者許久悲哀的婦人；","notes":[]},{"n":3,"t":"進去見王，對王如此如此說。」於是約押將當說的話教導了婦人。","notes":[]},{"n":4,"t":"提哥亞婦人到王面前，伏地叩拜，說：「王啊，求你拯救！」","notes":[]},{"n":5,"t":"王問她說：「你有甚麼事呢？」回答說：「婢女實在是寡婦，我丈夫死了。","notes":[]},{"n":6,"t":"我有兩個兒子，一日在田間爭鬥，沒有人解勸，這個就打死那個。","notes":[]},{"n":7,"t":"現在全家的人都起來攻擊婢女，說：『你將那打死兄弟的交出來，我們好治死他，償他打死兄弟的命，滅絕那承受家業的。』這樣，他們要將我剩下的炭火滅盡，不與我丈夫留名留後在世上。」","notes":[]},{"n":8,"t":"王對婦人說：「你回家去吧！我必為你下令。」","notes":[]},{"n":9,"t":"提哥亞婦人又對王說：「我主我王，願這罪歸我和我父家，與王和王的位無干。」","notes":[]},{"n":10,"t":"王說：「凡難為你的，你就帶他到我這裏來，他必不再攪擾你。」","notes":[]},{"n":11,"t":"婦人說：「願王記念耶和華－你的神，不許報血仇的人施行滅絕，恐怕他們滅絕我的兒子。」王說：「我指著永生的耶和華起誓：你的兒子連一根頭髮也不致落在地上。」","notes":[]},{"n":12,"t":"婦人說：「求我主我王容婢女再說一句話。」王說：「你說吧！」","notes":[]},{"n":13,"t":"婦人說：「王為何也起意要害神的民呢？王不使那逃亡的人回來，王的這話就是自證己錯了！","notes":[]},{"n":14,"t":"我們都是必死的，如同水潑在地上，不能收回。神並不奪取人的性命，乃設法使逃亡的人不致成為趕出、回不來的。","notes":[]},{"n":15,"t":"我來將這話告訴我主我王，是因百姓使我懼怕。婢女想，不如將這話告訴王，或者王成就婢女所求的。","notes":[]},{"n":16,"t":"人要將我和我兒子從神的地業上一同除滅，王必應允救我脫離他的手。","notes":[]},{"n":17,"t":"婢女又想，我主我王的話必安慰我；因為我主我王能辨別是非，如同神的使者一樣。惟願耶和華－你的神與你同在！」","notes":[]},{"n":18,"t":"王對婦人說：「我要問你一句話，你一點不要瞞我。」婦人說：「願我主我王說。」","notes":[]},{"n":19,"t":"王說：「你這些話莫非是約押的主意嗎？」婦人說：「我敢在我主我王面前起誓：王的話正對，不偏左右，是王的僕人約押吩咐我的，這些話是他教導我的。","notes":[]},{"n":20,"t":"王的僕人約押如此行，為要挽回這事。我主的智慧卻如神使者的智慧，能知世上一切事。」","notes":[]},{"n":21,"t":"王對約押說：「我應允你這事。你可以去，把那少年人押沙龍帶回來。」","notes":[]},{"n":22,"t":"約押就面伏於地叩拜，祝謝於王，又說：「王既應允僕人所求的，僕人今日知道在我主我王眼前蒙恩了。」","notes":[]},{"n":23,"t":"於是約押起身往基述去，將押沙龍帶回耶路撒冷。","notes":[]},{"n":24,"t":"王說：「使他回自己家裏去，不要見我的面。」押沙龍就回自己家裏去，沒有見王的面。","notes":[]},{"n":25,"t":"以色列全地之中，無人像押沙龍那樣俊美，得人的稱讚，從腳底到頭頂毫無瑕疵。","notes":[],"heads":["大衛饒恕押沙龍"]},{"n":26,"t":"他的頭髮甚重，每到年底剪髮一次；所剪下來的，按王的平稱一稱，重二百舍客勒。","notes":[]},{"n":27,"t":"押沙龍生了三個兒子，一個女兒。女兒名叫她瑪，是個容貌俊美的女子。","notes":[]},{"n":28,"t":"押沙龍住在耶路撒冷足有二年，沒有見王的面。","notes":[]},{"n":29,"t":"押沙龍打發人去叫約押來，要託他去見王，約押卻不肯來。第二次打發人去叫他，他仍不肯來。","notes":[]},{"n":30,"t":"所以押沙龍對僕人說：「你們看，約押有一塊田，與我的田相近，其中有大麥，你們去放火燒了。」押沙龍的僕人就去放火燒了那田。","notes":[]},{"n":31,"t":"於是約押起來，到了押沙龍家裏，問他說：「你的僕人為何放火燒了我的田呢？」","notes":[]},{"n":32,"t":"押沙龍回答約押說：「我打發人去請你來，好託你去見王，替我說：『我為何從基述回來呢？不如仍在那裏。』現在要許我見王的面；我若有罪，任憑王殺我就是了。」","notes":[]},{"n":33,"t":"於是約押去見王，將這話奏告王，王便叫押沙龍來。押沙龍來見王，在王面前俯伏於地，王就與押沙龍親嘴。","notes":[]}]},"15":{"heading":"押沙龍陰謀造反","verses":[{"n":1,"t":"此後，押沙龍為自己預備車馬，又派五十人在他前頭奔走。","notes":[]},{"n":2,"t":"押沙龍常常早晨起來，站在城門的道旁，凡有爭訟要去求王判斷的，押沙龍就叫他過來，問他說：「你是哪一城的人？」回答說：「僕人是以色列某支派的人。」","notes":[]},{"n":3,"t":"押沙龍對他說：「你的事有情有理，無奈王沒有委人聽你伸訴。」","notes":[]},{"n":4,"t":"押沙龍又說：「恨不得我作國中的士師！凡有爭訟求審判的到我這裏來，我必秉公判斷。」","notes":[]},{"n":5,"t":"若有人近前來要拜押沙龍，押沙龍就伸手拉住他，與他親嘴。","notes":[]},{"n":6,"t":"以色列人中，凡去見王求判斷的，押沙龍都是如此待他們。這樣，押沙龍暗中得了以色列人的心。","notes":[]},{"n":7,"t":"滿了四十年，押沙龍對王說：「求你准我往希伯崙去，還我向耶和華所許的願。","notes":["有作四年的"]},{"n":8,"t":"因為僕人住在亞蘭的基述，曾許願說：『耶和華若使我再回耶路撒冷，我必事奉他。』」","notes":[]},{"n":9,"t":"王說：「你平平安安地去吧！」押沙龍就起身，往希伯崙去了。","notes":[]},{"n":10,"t":"押沙龍打發探子走遍以色列各支派，說：「你們一聽見角聲就說：『押沙龍在希伯崙作王了！』」","notes":[]},{"n":11,"t":"押沙龍在耶路撒冷請了二百人與他同去，都是誠誠實實去的，並不知道其中的真情。","notes":[]},{"n":12,"t":"押沙龍獻祭的時候，打發人去將大衛的謀士、基羅人亞希多弗從他本城請了來。於是叛逆的勢派甚大；因為隨從押沙龍的人民，日漸增多。","notes":[]},{"n":13,"t":"有人報告大衛說：「以色列人的心都歸向押沙龍了！」","notes":[],"heads":["大衛逃離耶路撒冷"]},{"n":14,"t":"大衛就對耶路撒冷跟隨他的臣僕說：「我們要起來逃走，不然都不能躲避押沙龍了；要速速地去，恐怕他忽然來到，加害於我們，用刀殺盡合城的人。」","notes":[]},{"n":15,"t":"王的臣僕對王說：「我主我王所定的，僕人都願遵行。」","notes":[]},{"n":16,"t":"於是王帶著全家的人出去了，但留下十個妃嬪看守宮殿。","notes":[]},{"n":17,"t":"王出去，眾民都跟隨他，到伯墨哈，就住下了。","notes":[]},{"n":18,"t":"王的臣僕都在他面前過去。基利提人、比利提人，就是從迦特跟隨王來的六百人，也都在他面前過去。","notes":[]},{"n":19,"t":"王對迦特人以太說：「你是外邦逃來的人，為甚麼與我們同去呢？你可以回去與新王同住，或者回你本地去吧！","notes":[]},{"n":20,"t":"你來的日子不多，我今日怎好叫你與我們一同飄流、沒有一定的住處呢？你不如帶你的弟兄回去吧！願耶和華用慈愛誠實待你。」","notes":[]},{"n":21,"t":"以太對王說：「我指著永生的耶和華起誓，又敢在王面前起誓：無論生死，王在哪裏，僕人也必在那裏。」","notes":[]},{"n":22,"t":"大衛對以太說：「你前去過河吧！」於是迦特人以太帶著跟隨他的人和所有的婦人孩子，就都過去了。","notes":[]},{"n":23,"t":"本地的人都放聲大哭。眾民盡都過去，王也過了汲淪溪；眾民往曠野去了。","notes":[]},{"n":24,"t":"撒督和抬神約櫃的利未人也一同來了，將神的約櫃放下。亞比亞他上來，等著眾民從城裏出來過去。","notes":[]},{"n":25,"t":"王對撒督說：「你將神的約櫃抬回城去。我若在耶和華眼前蒙恩，他必使我回來，再見約櫃和他的居所。","notes":[]},{"n":26,"t":"倘若他說：『我不喜悅你』，看哪，我在這裏，願他憑自己的意旨待我！」","notes":[]},{"n":27,"t":"王又對祭司撒督說：「你不是先見嗎？你可以安然回城；你兒子亞希瑪斯和亞比亞他的兒子約拿單都可以與你同去。","notes":[]},{"n":28,"t":"我在曠野的渡口那裏等你們報信給我。」","notes":[]},{"n":29,"t":"於是撒督和亞比亞他將神的約櫃抬回耶路撒冷，他們就住在那裏。","notes":[]},{"n":30,"t":"大衛蒙頭赤腳上橄欖山，一面上一面哭。跟隨他的人也都蒙頭哭著上去；","notes":[]},{"n":31,"t":"有人告訴大衛說：「亞希多弗也在叛黨之中，隨從押沙龍。」大衛禱告說：「耶和華啊，求你使亞希多弗的計謀變為愚拙！」","notes":[]},{"n":32,"t":"大衛到了山頂、敬拜神的地方，見亞基人戶篩，衣服撕裂，頭蒙灰塵來迎接他。","notes":[]},{"n":33,"t":"大衛對他說：「你若與我同去，必累贅我；","notes":[]},{"n":34,"t":"你若回城去，對押沙龍說：『王啊，我願作你的僕人；我向來作你父親的僕人，現在我也照樣作你的僕人。』這樣，你就可以為我破壞亞希多弗的計謀。","notes":[]},{"n":35,"t":"祭司撒督和亞比亞他豈不都在那裏嗎？你在王宮裏聽見甚麼，就要告訴祭司撒督和亞比亞他。","notes":[]},{"n":36,"t":"撒督的兒子亞希瑪斯，亞比亞他的兒子約拿單，也都在那裏。凡你們所聽見的可以託這二人來報告我。」","notes":[]},{"n":37,"t":"於是，大衛的朋友戶篩進了城；押沙龍也進了耶路撒冷。","notes":[]}]},"16":{"heading":"大衛和洗巴","verses":[{"n":1,"t":"大衛剛過山頂，見米非波設的僕人洗巴拉著備好了的兩匹驢，驢上馱著二百麵餅，一百葡萄餅，一百個夏天的果餅，一皮袋酒來迎接他。","notes":[]},{"n":2,"t":"王問洗巴說：「你帶這些來是甚麼意思呢？」洗巴說：「驢是給王的家眷騎的；麵餅和夏天的果餅是給少年人吃的；酒是給在曠野疲乏人喝的。」","notes":[]},{"n":3,"t":"王問說：「你主人的兒子在哪裏呢？」洗巴回答王說：「他仍在耶路撒冷，因他說：『以色列人今日必將我父的國歸還我。』」","notes":[]},{"n":4,"t":"王對洗巴說：「凡屬米非波設的都歸你了。」洗巴說：「我叩拜我主我王，願我在你眼前蒙恩。」","notes":[]},{"n":5,"t":"大衛王到了巴戶琳，見有一個人出來，是掃羅族基拉的兒子，名叫示每。他一面走一面咒罵，","notes":[],"heads":["大衛和示每"]},{"n":6,"t":"又拿石頭砍大衛王和王的臣僕；眾民和勇士都在王的左右。","notes":[]},{"n":7,"t":"示每咒罵說：「你這流人血的壞人哪，去吧去吧！","notes":[]},{"n":8,"t":"你流掃羅全家的血，接續他作王；耶和華把這罪歸在你身上，將這國交給你兒子押沙龍。現在你自取其禍，因為你是流人血的人。」","notes":[]},{"n":9,"t":"洗魯雅的兒子亞比篩對王說：「這死狗豈可咒罵我主我王呢？求你容我過去，割下他的頭來。」","notes":[]},{"n":10,"t":"王說：「洗魯雅的兒子，我與你們有何關涉呢？他咒罵是因耶和華吩咐他說：『你要咒罵大衛。』如此，誰敢說你為甚麼這樣行呢？」","notes":[]},{"n":11,"t":"大衛又對亞比篩和眾臣僕說：「我親生的兒子尚且尋索我的性命，何況這便雅憫人呢？由他咒罵吧！因為這是耶和華吩咐他的。","notes":[]},{"n":12,"t":"或者耶和華見我遭難，為我今日被這人咒罵，就施恩與我。」","notes":[]},{"n":13,"t":"於是大衛和跟隨他的人往前行走。示每在大衛對面山坡，一面行走一面咒罵，又拿石頭砍他，拿土揚他。","notes":[]},{"n":14,"t":"王和跟隨他的眾人疲疲乏乏地到了一個地方，就在那裏歇息歇息。","notes":[]},{"n":15,"t":"押沙龍和以色列眾人來到耶路撒冷；亞希多弗也與他同來。","notes":[],"heads":["押沙龍在耶路撒冷"]},{"n":16,"t":"大衛的朋友亞基人戶篩去見押沙龍，對他說：「願王萬歲！願王萬歲！」","notes":[]},{"n":17,"t":"押沙龍問戶篩說：「這是你恩待朋友嗎？為甚麼不與你的朋友同去呢？」","notes":[]},{"n":18,"t":"戶篩對押沙龍說：「不然，耶和華和這民，並以色列眾人所揀選的，我必歸順他，與他同住。","notes":[]},{"n":19,"t":"再者，我當服事誰呢？豈不是前王的兒子嗎？我怎樣服事你父親，也必照樣服事你。」","notes":[]},{"n":20,"t":"押沙龍對亞希多弗說：「你們出個主意，我們怎樣行才好？」","notes":[]},{"n":21,"t":"亞希多弗對押沙龍說：「你父所留下看守宮殿的妃嬪，你可以與她們親近。以色列眾人聽見你父親憎惡你，凡歸順你人的手就更堅強。」","notes":[]},{"n":22,"t":"於是人為押沙龍在宮殿的平頂上支搭帳棚；押沙龍在以色列眾人眼前，與他父的妃嬪親近。","notes":[]},{"n":23,"t":"那時亞希多弗所出的主意好像人問神的話一樣；他昔日給大衛，今日給押沙龍所出的主意，都是這樣。","notes":[]}]},"17":{"heading":"戶篩破壞亞希多弗的計謀","verses":[{"n":1,"t":"亞希多弗又對押沙龍說：「求你准我挑選一萬二千人，今夜我就起身追趕大衛，","notes":[]},{"n":2,"t":"趁他疲乏手軟，我忽然追上他，使他驚惶；跟隨他的民必都逃跑，我就單殺王一人，","notes":[]},{"n":3,"t":"使眾民都歸順你。你所尋找的人既然死了，眾民就如已經歸順你；這樣，也都平安無事了。」","notes":[]},{"n":4,"t":"押沙龍和以色列的長老都以這話為美。","notes":[]},{"n":5,"t":"押沙龍說：「要召亞基人戶篩來，我們也要聽他怎樣說。」","notes":[]},{"n":6,"t":"戶篩到了押沙龍面前，押沙龍向他說：「亞希多弗是如此如此說的，我們照著他的話行可以不可以？若不可，你就說吧！」","notes":[]},{"n":7,"t":"戶篩對押沙龍說：「亞希多弗這次所定的謀不善。」","notes":[]},{"n":8,"t":"戶篩又說：「你知道，你父親和跟隨他的人都是勇士，現在他們心裏惱怒，如同田野丟崽子的母熊一般，而且你父親是個戰士，必不和民一同住宿。","notes":[]},{"n":9,"t":"他現今或藏在坑中或在別處，若有人首先被殺，凡聽見的必說：『跟隨押沙龍的民被殺了。』","notes":[]},{"n":10,"t":"雖有人膽大如獅子，他的心也必消化；因為以色列人都知道你父親是英雄，跟隨他的人也都是勇士。","notes":[]},{"n":11,"t":"依我之計，不如將以色列眾人－從但直到別是巴，如同海邊的沙那樣多－聚集到你這裏來，你也親自率領他們出戰。","notes":[]},{"n":12,"t":"這樣，我們在何處遇見他，就下到他那裏，如同露水下在地上一般，連他帶跟隨他的人，一個也不留下。","notes":[]},{"n":13,"t":"他若進了哪一座城，以色列眾人必帶繩子去，將那城拉到河裏，甚至連一塊小石頭都不剩下。」","notes":[]},{"n":14,"t":"押沙龍和以色列眾人說：「亞基人戶篩的計謀比亞希多弗的計謀更好！」這是因耶和華定意破壞亞希多弗的良謀，為要降禍與押沙龍。","notes":[]},{"n":15,"t":"戶篩對祭司撒督和亞比亞他說：「亞希多弗為押沙龍和以色列的長老所定的計謀是如此如此，我所定的計謀是如此如此。","notes":[],"heads":["大衛因接獲警告而逃脫"]},{"n":16,"t":"現在你們要急速打發人去，告訴大衛說：『今夜不可住在曠野的渡口，務要過河，免得王和跟隨他的人都被吞滅。』」","notes":[]},{"n":17,"t":"那時，約拿單和亞希瑪斯在隱‧羅結那裏等候，不敢進城，恐怕被人看見。有一個使女出來，將這話告訴他們，他們就去報信給大衛王。","notes":[]},{"n":18,"t":"然而有一個童子看見他們，就去告訴押沙龍。他們急忙跑到巴戶琳某人的家裏；那人院中有一口井，他們就下到井裏。","notes":[]},{"n":19,"t":"那家的婦人用蓋蓋上井口，又在上頭鋪上碎麥，事就沒有洩漏。","notes":[]},{"n":20,"t":"押沙龍的僕人來到那家，問婦人說：「亞希瑪斯和約拿單在哪裏？」婦人說：「他們過了河了。」僕人找他們，找不著，就回耶路撒冷去了。","notes":[]},{"n":21,"t":"他們走後，二人從井裏上來，去告訴大衛王說：「亞希多弗如此如此定計害你，你們務要起來，快快過河。」","notes":[]},{"n":22,"t":"於是大衛和跟隨他的人都起來，過約旦河。到了天亮，無一人不過約旦河的。","notes":[]},{"n":23,"t":"亞希多弗見不依從他的計謀，就備上驢，歸回本城；到了家，留下遺言，便吊死了，葬在他父親的墳墓裏。","notes":[]},{"n":24,"t":"大衛到了瑪哈念，押沙龍和跟隨他的以色列人也都過了約旦河。","notes":[]},{"n":25,"t":"押沙龍立亞瑪撒作元帥，代替約押。亞瑪撒是以實瑪利人 以特拉的兒子。以特拉曾與拿轄的女兒亞比該親近；這亞比該與約押的母親洗魯雅是姊妹。","notes":["又作以色列人"]},{"n":26,"t":"押沙龍和以色列人都安營在基列地。","notes":[]},{"n":27,"t":"大衛到了瑪哈念，亞捫族的拉巴人拿轄的兒子朔比，羅‧底巴人亞‧米利的兒子瑪吉，基列的羅基琳人巴西萊，","notes":[]},{"n":28,"t":"帶著被、褥、盆、碗、瓦器、小麥、大麥、麥麵、炒穀、豆子、紅豆、炒豆、","notes":[]},{"n":29,"t":"蜂蜜、奶油、綿羊、奶餅，供給大衛和跟隨他的人吃；他們說：「民在曠野，必飢渴困乏了。」","notes":[]}]},"18":{"heading":"押沙龍敗亡","verses":[{"n":1,"t":"大衛數點跟隨他的人，立千夫長、百夫長率領他們。","notes":[]},{"n":2,"t":"大衛打發軍兵出戰，分為三隊：一隊在約押手下，一隊在洗魯雅的兒子、約押兄弟亞比篩手下，一隊在迦特人以太手下。大衛對軍兵說：「我必與你們一同出戰。」","notes":[]},{"n":3,"t":"軍兵卻說：「你不可出戰。若是我們逃跑，敵人必不介意；我們陣亡一半，敵人也不介意。因為你一人強似我們萬人，你不如在城裏預備幫助我們。」","notes":[]},{"n":4,"t":"王向他們說：「你們以為怎樣好，我就怎樣行。」於是王站在城門旁，軍兵或百或千地挨次出去了。","notes":[]},{"n":5,"t":"王囑咐約押、亞比篩、以太說：「你們要為我的緣故寬待那少年人押沙龍。」王為押沙龍囑咐眾將的話，兵都聽見了。","notes":[]},{"n":6,"t":"兵就出到田野迎著以色列人，在以法蓮樹林裏交戰。","notes":[]},{"n":7,"t":"以色列人敗在大衛的僕人面前；那日陣亡的甚多，共有二萬人。","notes":[]},{"n":8,"t":"因為在那裏四面打仗，死於樹林的比死於刀劍的更多。","notes":[]},{"n":9,"t":"押沙龍偶然遇見大衛的僕人。押沙龍騎著騾子，從大橡樹密枝底下經過，他的頭髮被樹枝繞住，就懸掛起來，所騎的騾子便離他去了。","notes":[]},{"n":10,"t":"有個人看見，就告訴約押說：「我看見押沙龍掛在橡樹上了。」","notes":[]},{"n":11,"t":"約押對報信的人說：「你既看見他，為甚麼不將他打死落在地上呢？你若打死他，我就賞你十舍客勒銀子，一條帶子。」","notes":[]},{"n":12,"t":"那人對約押說：「我就是得你一千舍客勒銀子，我也不敢伸手害王的兒子；因為我們聽見王囑咐你和亞比篩並以太說：『你們要謹慎，不可害那少年人押沙龍。』","notes":[]},{"n":13,"t":"我若妄為害了他的性命，就是你自己也必與我為敵（原來，無論何事都瞞不過王。）」","notes":[]},{"n":14,"t":"約押說：「我不能與你留連。」約押手拿三杆短槍，趁押沙龍在橡樹上還活著，就刺透他的心。","notes":[]},{"n":15,"t":"給約押拿兵器的十個少年人圍繞押沙龍，將他殺死。","notes":[]},{"n":16,"t":"約押吹角，攔阻眾人，他們就回來，不再追趕以色列人。","notes":[]},{"n":17,"t":"他們將押沙龍丟在林中一個大坑裏，上頭堆起一大堆石頭。以色列眾人都逃跑，各回各家去了。","notes":[]},{"n":18,"t":"押沙龍活著的時候，在王谷立了一根石柱，因他說：「我沒有兒子為我留名。」他就以自己的名稱那石柱叫押沙龍柱，直到今日。","notes":[]},{"n":19,"t":"撒督的兒子亞希瑪斯說：「容我跑去，將耶和華向仇敵給王報仇的信息報與王知。」","notes":[],"heads":["大衛聽聞押沙龍死訊"]},{"n":20,"t":"約押對他說：「你今日不可去報信，改日可以報信；因為今日王的兒子死了，所以你不可去報信。」","notes":[]},{"n":21,"t":"約押對古示人說：「你去將你所看見的告訴王。」古示人在約押面前下拜，就跑去了。","notes":[]},{"n":22,"t":"撒督的兒子亞希瑪斯又對約押說：「無論怎樣，求你容我隨著古示人跑去。」約押說：「我兒，你報這信息，既不得賞賜，何必要跑去呢？」","notes":[]},{"n":23,"t":"他又說：「無論怎樣，我要跑去。」約押說：「你跑去吧！」亞希瑪斯就從平原往前跑，跑過古示人去了。","notes":[]},{"n":24,"t":"大衛正坐在城甕裏。守望的人上城門樓的頂上，舉目觀看，見有一個人獨自跑來。","notes":[]},{"n":25,"t":"守望的人就大聲告訴王。王說：「他若獨自來，必是報口信的。」那人跑得漸漸近了。","notes":[]},{"n":26,"t":"守望的人又見一人跑來，就對守城門的人說：「又有一人獨自跑來。」王說：「這也必是報信的。」","notes":[]},{"n":27,"t":"守望的人說：「我看前頭人的跑法，好像撒督的兒子亞希瑪斯的跑法一樣。」王說：「他是個好人，必是報好信息。」","notes":[]},{"n":28,"t":"亞希瑪斯向王呼叫說：「平安了！」就在王面前臉伏於地叩拜，說：「耶和華－你的神是應當稱頌的，因他已將那舉手攻擊我主我王的人交給王了。」","notes":[]},{"n":29,"t":"王問說：「少年人押沙龍平安不平安？」亞希瑪斯回答說：「約押打發王的僕人，那時僕人聽見眾民大聲喧嘩，卻不知道是甚麼事。」","notes":[]},{"n":30,"t":"王說：「你退去，站在旁邊。」他就退去，站在旁邊。","notes":[]},{"n":31,"t":"古示人也來到，說：「有信息報給我主我王！耶和華今日向一切興起攻擊你的人給你報仇了。」","notes":[]},{"n":32,"t":"王問古示人說：「少年人押沙龍平安不平安？」古示人回答說：「願我主我王的仇敵，和一切興起要殺害你的人，都與那少年人一樣。」","notes":[]},{"n":33,"t":"王就心裏傷慟，上城門樓去哀哭，一面走一面說：「我兒押沙龍啊！我兒，我兒押沙龍啊！我恨不得替你死，押沙龍啊，我兒！我兒！」","notes":[]}]},"19":{"heading":"約押勸諫王","verses":[{"n":1,"t":"有人告訴約押說：「王為押沙龍哭泣悲哀。」","notes":[]},{"n":2,"t":"眾民聽說王為他兒子憂愁，他們得勝的歡樂卻變成悲哀。","notes":[]},{"n":3,"t":"那日眾民暗暗地進城，就如敗陣逃跑、慚愧的民一般。","notes":[]},{"n":4,"t":"王蒙著臉，大聲哭號說：「我兒押沙龍啊！押沙龍，我兒，我兒啊！」","notes":[]},{"n":5,"t":"約押進去見王，說：「你今日使你一切僕人臉面慚愧了！他們今日救了你的性命和你兒女妻妾的性命，","notes":[]},{"n":6,"t":"你卻愛那恨你的人，恨那愛你的人。你今日明明地不以將帥、僕人為念。我今日看明，若押沙龍活著，我們都死亡，你就喜悅了。","notes":[]},{"n":7,"t":"現在你當出去，安慰你僕人的心。我指著耶和華起誓：你若不出去，今夜必無一人與你同在一處；這禍患就比你從幼年到如今所遭的更甚！」","notes":[]},{"n":8,"t":"於是王起來，坐在城門口。眾民聽說王坐在城門口，就都到王面前。以色列人已經逃跑，各回各家去了。","notes":[]},{"n":9,"t":"以色列眾支派的人紛紛議論說：「王曾救我們脫離仇敵的手，又救我們脫離非利士人的手，現在他躲避押沙龍逃走了。","notes":[]},{"n":10,"t":"我們膏押沙龍治理我們，他已經陣亡。現在為甚麼不出一言請王回來呢？」","notes":[]},{"n":11,"t":"大衛王差人去見祭司撒督和亞比亞他，說：「你們當向猶大長老說：『以色列眾人已經有話請王回宮，你們為甚麼落在他們後頭呢？","notes":[]},{"n":12,"t":"你們是我的弟兄，是我的骨肉，為甚麼在人後頭請王回來呢？』","notes":[]},{"n":13,"t":"也要對亞瑪撒說：『你不是我的骨肉嗎？我若不立你替約押常作元帥，願神重重地降罰與我！』」","notes":[]},{"n":14,"t":"如此就挽回猶大眾人的心，如同一人的心。他們便打發人去見王，說：「請王和王的一切臣僕回來。」","notes":[]},{"n":15,"t":"王就回來，到了約旦河。猶大人來到吉甲，要去迎接王，請他過約旦河。","notes":[]},{"n":16,"t":"巴戶琳的便雅憫人、基拉的兒子示每急忙與猶大人一同下去迎接大衛王。","notes":[]},{"n":17,"t":"跟從示每的有一千便雅憫人，還有掃羅家的僕人洗巴和他十五個兒子，二十個僕人；他們都過約旦河迎接王。","notes":[]},{"n":18,"t":"有擺渡船過去，渡王的家眷，任王使用。王要過約旦河的時候，基拉的兒子示每就俯伏在王面前，","notes":[]},{"n":19,"t":"對王說：「我主我王出耶路撒冷的時候，僕人行悖逆的事，現在求我主不要因此加罪與僕人，不要記念，也不要放在心上。","notes":[]},{"n":20,"t":"僕人明知自己有罪，所以約瑟全家之中，今日我首先下來迎接我主我王。」","notes":[]},{"n":21,"t":"洗魯雅的兒子亞比篩說：「示每既咒罵耶和華的受膏者，不應當治死他嗎？」","notes":[]},{"n":22,"t":"大衛說：「洗魯雅的兒子，我與你們有何關涉，使你們今日與我反對呢？今日在以色列中豈可治死人呢？我豈不知今日我作以色列的王嗎？」","notes":[]},{"n":23,"t":"於是王對示每說：「你必不死。」王就向他起誓。","notes":[]},{"n":24,"t":"掃羅的孫子米非波設也下去迎接王。他自從王去的日子，直到王平平安安地回來，沒有修腳，沒有剃鬍鬚，也沒有洗衣服。","notes":[],"heads":["大衛善待米非波設"]},{"n":25,"t":"他來到耶路撒冷迎接王的時候，王問他說：「米非波設，你為甚麼沒有與我同去呢？」","notes":[]},{"n":26,"t":"他回答說：「我主我王，僕人是瘸腿的。那日我想要備驢騎上，與王同去，無奈我的僕人欺哄了我，","notes":[]},{"n":27,"t":"又在我主我王面前讒毀我。然而我主我王如同神的使者一般，你看怎樣好，就怎樣行吧！","notes":[]},{"n":28,"t":"因為我祖全家的人，在我主我王面前都算為死人，王卻使僕人在王的席上同人吃飯，我現在向王還能辨理訴冤嗎？」","notes":[]},{"n":29,"t":"王對他說：「你何必再提你的事呢？我說，你與洗巴均分地土。」","notes":[]},{"n":30,"t":"米非波設對王說：「我主我王既平平安安地回宮，就任憑洗巴都取了也可以。」","notes":[]},{"n":31,"t":"基列人巴西萊從羅基琳下來，要送王過約旦河，就與王一同過了約旦河。","notes":[],"heads":["大衛善待巴西萊"]},{"n":32,"t":"巴西萊年紀老邁，已經八十歲了。王住在瑪哈念的時候，他就拿食物來供給王；他原是大富戶。","notes":[]},{"n":33,"t":"王對巴西萊說：「你與我同去，我要在耶路撒冷那裏養你的老。」","notes":[]},{"n":34,"t":"巴西萊對王說：「我在世的年日還能有多少，使我與王同上耶路撒冷呢？","notes":[]},{"n":35,"t":"僕人現在八十歲了，還能嘗出飲食的滋味、辨別美惡嗎？還能聽男女歌唱的聲音嗎？僕人何必累贅我主我王呢？","notes":[]},{"n":36,"t":"僕人只要送王過約旦河，王何必賜我這樣的恩典呢？","notes":[]},{"n":37,"t":"求你准我回去，好死在我本城，葬在我父母的墓旁。這裏有王的僕人金罕，讓他同我主我王過去，可以隨意待他。」","notes":[]},{"n":38,"t":"王說：「金罕可以與我同去，我必照你的心願待他。你向我求甚麼，我都必為你成就。」","notes":[]},{"n":39,"t":"於是眾民過約旦河，王也過去。王與巴西萊親嘴，為他祝福，巴西萊就回本地去了。","notes":[]},{"n":40,"t":"王過去，到了吉甲，金罕也跟他過去。猶大眾民和以色列民的一半也都送王過去。","notes":[],"heads":["以色列人和猶大人為王起爭論"]},{"n":41,"t":"以色列眾人來見王，對他說：「我們弟兄猶大人為甚麼暗暗送王和王的家眷，並跟隨王的人過約旦河？」","notes":[]},{"n":42,"t":"猶大眾人回答以色列人說：「因為王與我們是親屬，你們為何因這事發怒呢？我們吃了王的甚麼呢？王賞賜了我們甚麼呢？」","notes":[]},{"n":43,"t":"以色列人回答猶大人說：「按支派，我們與王有十分的情分；在大衛身上，我們也比你們更有情分。你們為何藐視我們，請王回來不先與我們商量呢？」但猶大人的話比以色列人的話更硬。","notes":[]}]},"20":{"heading":"示巴反叛","verses":[{"n":1,"t":"在那裏恰巧有一個匪徒，名叫示巴，是便雅憫人比基利的兒子。他吹角，說：「我們與大衛無分，與耶西的兒子無涉。以色列人哪，你們各回各家去吧！」","notes":[]},{"n":2,"t":"於是以色列人都離開大衛，跟隨比基利的兒子示巴。但猶大人從約旦河直到耶路撒冷，都緊緊跟隨他們的王。","notes":[]},{"n":3,"t":"大衛王來到耶路撒冷，進了宮殿，就把從前留下看守宮殿的十個妃嬪禁閉在冷宮，養活她們，不與她們親近。她們如同寡婦被禁，直到死的日子。","notes":[]},{"n":4,"t":"王對亞瑪撒說：「你要在三日之內將猶大人招聚了來，你也回到這裏來。」","notes":[]},{"n":5,"t":"亞瑪撒就去招聚猶大人，卻耽延過了王所限的日期。","notes":[]},{"n":6,"t":"大衛對亞比篩說：「現在恐怕比基利的兒子示巴加害於我們比押沙龍更甚。你要帶領你主的僕人追趕他，免得他得了堅固城，躲避我們。」","notes":[]},{"n":7,"t":"約押的人和基利提人、比利提人，並所有的勇士，都跟著亞比篩，從耶路撒冷出去追趕比基利的兒子示巴。","notes":[]},{"n":8,"t":"他們到了基遍的大磐石那裏，亞瑪撒來迎接他們。那時約押穿著戰衣，腰束佩刀的帶子，刀在鞘內；約押前行，刀從鞘內掉出來。","notes":[]},{"n":9,"t":"約押左手拾起刀來，對亞瑪撒說：「我兄弟，你好啊！」就用右手抓住亞瑪撒的鬍子，要與他親嘴。","notes":[]},{"n":10,"t":"亞瑪撒沒有防備約押手裏所拿的刀；約押用刀刺入他的肚腹，他的腸子流在地上，沒有再刺他，就死了。約押和他兄弟亞比篩往前追趕比基利的兒子示巴。","notes":[]},{"n":11,"t":"有約押的一個少年人站在亞瑪撒屍身旁邊，對眾人說：「誰喜悅約押，誰歸順大衛，就當跟隨約押去。」","notes":[]},{"n":12,"t":"亞瑪撒在道路上滾在自己的血裏。那人見眾民經過都站住，就把亞瑪撒的屍身從路上挪到田間，用衣服遮蓋。","notes":[]},{"n":13,"t":"屍身從路上挪移之後，眾民就都跟隨約押去追趕比基利的兒子示巴。","notes":[]},{"n":14,"t":"他走遍以色列各支派，直到伯‧瑪迦的亞比拉，並比利人的全地；那些地方的人也都聚集跟隨他。","notes":[]},{"n":15,"t":"約押和跟隨的人到了伯‧瑪迦的亞比拉，圍困示巴，就對著城築壘；跟隨約押的眾民用錘撞城，要使城塌陷。","notes":[]},{"n":16,"t":"有一個聰明婦人從城上呼叫說：「聽啊，聽啊，請約押近前來，我好與他說話。」","notes":[]},{"n":17,"t":"約押就近前來，婦人問他說：「你是約押不是？」他說：「我是。」婦人說：「求你聽婢女的話。」約押說：「我聽。」","notes":[]},{"n":18,"t":"婦人說：「古時有話說，當先在亞比拉求問，然後事就定妥。","notes":[]},{"n":19,"t":"我們這城的人在以色列人中是和平、忠厚的。你為何要毀壞以色列中的大城，吞滅耶和華的產業呢？」","notes":[]},{"n":20,"t":"約押回答說：「我決不吞滅毀壞，","notes":[]},{"n":21,"t":"乃因以法蓮山地的一個人－比基利的兒子示巴－舉手攻擊大衛王，你們若將他一人交出來，我便離城而去。」婦人對約押說：「那人的首級必從城牆上丟給你。」","notes":[]},{"n":22,"t":"婦人就憑她的智慧去勸眾人。他們便割下比基利的兒子示巴的首級，丟給約押。約押吹角，眾人就離城而散，各歸各家去了。約押回耶路撒冷，到王那裏。","notes":[]},{"n":23,"t":"約押作以色列全軍的元帥；耶何耶大的兒子比拿雅統轄基利提人和比利提人；","notes":[]},{"n":24,"t":"亞多蘭掌管服苦的人；亞希律的兒子約沙法作史官；","notes":[]},{"n":25,"t":"示法作書記；撒督和亞比亞他作祭司長；","notes":[]},{"n":26,"t":"睚珥人以拉作大衛的宰相。","notes":[]}]},"21":{"heading":"掃羅的後代被處死","verses":[{"n":1,"t":"大衛年間有饑荒，一連三年，大衛就求問耶和華。耶和華說：「這饑荒是因掃羅和他流人血之家殺死基遍人。」","notes":[]},{"n":2,"t":"原來這基遍人不是以色列人，乃是亞摩利人中所剩的；以色列人曾向他們起誓，不殺滅他們，掃羅卻為以色列人和猶大人發熱心，想要殺滅他們。大衛王召了他們來，","notes":[]},{"n":3,"t":"問他們說：「我當為你們怎樣行呢？可用甚麼贖這罪，使你們為耶和華的產業祝福呢？」","notes":[]},{"n":4,"t":"基遍人回答說：「我們和掃羅與他家的事並不關乎金銀，也不要因我們的緣故殺一個以色列人。」大衛說：「你們怎樣說，我就為你們怎樣行。」","notes":[]},{"n":5,"t":"他們對王說：「那從前謀害我們、要滅我們、使我們不得再住以色列境內的人，","notes":[]},{"n":6,"t":"現在願將他的子孫七人交給我們，我們好在耶和華面前，將他們懸掛在耶和華揀選掃羅的基比亞。」王說：「我必交給你們。」","notes":[]},{"n":7,"t":"王因為曾與掃羅的兒子約拿單指著耶和華起誓結盟，就愛惜掃羅的孫子、約拿單的兒子米非波設，不交出來，","notes":[]},{"n":8,"t":"卻把愛雅的女兒利斯巴給掃羅所生的兩個兒子亞摩尼、米非波設，和掃羅女兒米甲的姊姊給米何拉人巴西萊兒子亞得列所生的五個兒子","notes":[]},{"n":9,"t":"交在基遍人的手裏。基遍人就把他們，在耶和華面前，懸掛在山上，這七人就一同死亡。被殺的時候正是收割的日子，就是動手割大麥的時候。","notes":[]},{"n":10,"t":"愛雅的女兒利斯巴用麻布在磐石上搭棚，從動手收割的時候直到天降雨在屍身上的時候，日間不容空中的雀鳥落在屍身上，夜間不讓田野的走獸前來糟踐。","notes":[]},{"n":11,"t":"有人將掃羅的妃嬪愛雅女兒利斯巴所行的這事告訴大衛。","notes":[]},{"n":12,"t":"大衛就去，從基列‧雅比人那裏將掃羅和他兒子約拿單的骸骨搬了來（是因非利士人從前在基利波殺掃羅，將屍身懸掛在伯‧珊的街市上，基列‧雅比人把屍身偷了去。）","notes":[]},{"n":13,"t":"大衛將掃羅和他兒子約拿單的骸骨從那裏搬了來，又收殮被懸掛七人的骸骨，","notes":[]},{"n":14,"t":"將掃羅和他兒子約拿單的骸骨葬在便雅憫的洗拉，在掃羅父親基士的墳墓裏；眾人行了王所吩咐的。此後神垂聽國民所求的。","notes":[]},{"n":15,"t":"非利士人與以色列人打仗；大衛帶領僕人下去，與非利士人接戰，大衛就疲乏了。","notes":[],"heads":["攻打非利士巨人"]},{"n":16,"t":"偉人的一個兒子以實‧比諾要殺大衛；他的銅槍重三百舍客勒，又佩著新刀。","notes":[]},{"n":17,"t":"但洗魯雅的兒子亞比篩幫助大衛，攻打非利士人，將他殺死。當日，跟隨大衛的人向大衛起誓說：「以後你不可再與我們一同出戰，恐怕熄滅以色列的燈。」","notes":[]},{"n":18,"t":"後來，以色列人在歌伯與非利士人打仗，戶沙人西比該殺了偉人的一個兒子撒弗。","notes":[]},{"n":19,"t":"又在歌伯與非利士人打仗，伯利恆人雅雷俄珥金的兒子伊勒哈難殺了迦特人歌利亞。這人的槍桿粗如織布的機軸。","notes":[]},{"n":20,"t":"又在迦特打仗，那裏有一個身量高大的人，手腳都是六指，共有二十四個指頭；他也是偉人的兒子。","notes":[]},{"n":21,"t":"這人向以色列人罵陣，大衛的哥哥示米亞的兒子約拿單就殺了他。","notes":[]},{"n":22,"t":"這四個人是迦特偉人的兒子，都死在大衛和他僕人的手下。","notes":[]}]},"22":{"heading":"大衛的凱歌","verses":[{"n":1,"t":"當耶和華救大衛脫離一切仇敵和掃羅之手的日子，他向耶和華念這詩，","notes":[]},{"n":2,"t":"說：耶和華是我的巖石，我的山寨，我的救主，","notes":[]},{"n":3,"t":"我的神，我的磐石，我所投靠的。他是我的盾牌，是拯救我的角，是我的高臺，是我的避難所。我的救主啊，你是救我脫離強暴的。","notes":[]},{"n":4,"t":"我要求告當讚美的耶和華，這樣，我必從仇敵手中被救出來。","notes":[]},{"n":5,"t":"曾有死亡的波浪環繞我，匪類的急流使我驚懼，","notes":[]},{"n":6,"t":"陰間的繩索纏繞我，死亡的網羅臨到我。","notes":[]},{"n":7,"t":"我在急難中求告耶和華，向我的神呼求。他從殿中聽了我的聲音；我的呼求入了他的耳中。","notes":[]},{"n":8,"t":"那時因他發怒，地就搖撼戰抖；天的根基也震動搖撼。","notes":[]},{"n":9,"t":"從他鼻孔冒煙上騰；從他口中發火焚燒，連炭也著了。","notes":[]},{"n":10,"t":"他又使天下垂，親自降臨；有黑雲在他腳下。","notes":[]},{"n":11,"t":"他坐著基路伯飛行，在風的翅膀上顯現。","notes":[]},{"n":12,"t":"他以黑暗和聚集的水、天空的厚雲為他四圍的行宮。","notes":[]},{"n":13,"t":"因他面前的光輝炭都著了。","notes":[]},{"n":14,"t":"耶和華從天上打雷；至高者發出聲音。","notes":[]},{"n":15,"t":"他射出箭來，使仇敵四散，發出閃電，使他們擾亂。","notes":[]},{"n":16,"t":"耶和華的斥責一發，鼻孔的氣一出，海底就出現，大地的根基也顯露。","notes":[]},{"n":17,"t":"他從高天伸手抓住我，把我從大水中拉上來。","notes":[]},{"n":18,"t":"他救我脫離我的勁敵和那些恨我的人，因為他們比我強盛。","notes":[]},{"n":19,"t":"我遭遇災難的日子，他們來攻擊我；但耶和華是我的倚靠。","notes":[]},{"n":20,"t":"他又領我到寬闊之處；他救拔我，因他喜悅我。","notes":[]},{"n":21,"t":"耶和華按著我的公義報答我，按著我手中的清潔賞賜我。","notes":[]},{"n":22,"t":"因為我遵守了耶和華的道，未曾作惡離開我的神。","notes":[]},{"n":23,"t":"他的一切典章常在我面前；他的律例，我也未曾離棄。","notes":[]},{"n":24,"t":"我在他面前作了完全人；我也保守自己遠離我的罪孽。","notes":[]},{"n":25,"t":"所以耶和華按我的公義，按我在他眼前的清潔賞賜我。","notes":[]},{"n":26,"t":"慈愛的人，你以慈愛待他；完全的人，你以完全待他；","notes":[]},{"n":27,"t":"清潔的人，你以清潔待他；乖僻的人，你以彎曲待他。","notes":[]},{"n":28,"t":"困苦的百姓，你必拯救；但你的眼目察看高傲的人，使他降卑。","notes":[]},{"n":29,"t":"耶和華啊，你是我的燈；耶和華必照明我的黑暗。","notes":[]},{"n":30,"t":"我藉著你衝入敵軍，藉著我的神跳過牆垣。","notes":[]},{"n":31,"t":"至於神，他的道是完全的；耶和華的話是煉淨的。凡投靠他的，他便作他們的盾牌。","notes":[]},{"n":32,"t":"除了耶和華，誰是神呢？除了我們的神，誰是磐石呢？","notes":[]},{"n":33,"t":"神是我堅固的保障；他引導完全人行他的路。","notes":[]},{"n":34,"t":"他使我的腳快如母鹿的蹄，又使我在高處安穩。","notes":[]},{"n":35,"t":"他教導我的手能以爭戰，甚至我的膀臂能開銅弓。","notes":[]},{"n":36,"t":"你把你的救恩給我作盾牌；你的溫和使我為大。","notes":[]},{"n":37,"t":"你使我腳下的地步寬闊；我的腳未曾滑跌。","notes":[]},{"n":38,"t":"我追趕我的仇敵，滅絕了他們，未滅以先，我沒有歸回。","notes":[]},{"n":39,"t":"我滅絕了他們，打傷了他們，使他們不能起來；他們都倒在我的腳下。","notes":[]},{"n":40,"t":"因為你曾以力量束我的腰，使我能爭戰；你也使那起來攻擊我的都服在我以下。","notes":[]},{"n":41,"t":"你又使我的仇敵在我面前轉背逃跑，叫我能以剪除那恨我的人。","notes":[]},{"n":42,"t":"他們仰望，卻無人拯救；就是呼求耶和華，他也不應允。","notes":[]},{"n":43,"t":"我搗碎他們，如同地上的灰塵，踐踏他們，四散在地，如同街上的泥土。","notes":[]},{"n":44,"t":"你救我脫離我百姓的爭競，保護我作列國的元首；我素不認識的民必事奉我。","notes":[]},{"n":45,"t":"外邦人要投降我，一聽見我的名聲就必順從我。","notes":[]},{"n":46,"t":"外邦人要衰殘，戰戰兢兢地出他們的營寨。","notes":[]},{"n":47,"t":"耶和華是活神，願我的磐石被人稱頌！願神－那拯救我的磐石被人尊崇！","notes":[]},{"n":48,"t":"這位神就是那為我伸冤、使眾民服在我以下的。","notes":[]},{"n":49,"t":"你救我脫離仇敵，又把我舉起，高過那些起來攻擊我的；你救我脫離強暴的人。","notes":[]},{"n":50,"t":"耶和華啊，因此我要在外邦中稱謝你，歌頌你的名。","notes":[]},{"n":51,"t":"耶和華賜極大的救恩給他所立的王，施慈愛給他的受膏者，就是給大衛和他的後裔，直到永遠！","notes":[]}]},"23":{"heading":"大衛的遺言","verses":[{"n":1,"t":"以下是大衛末了的話。耶西的兒子大衛得居高位，是雅各神所膏的，作以色列的美歌者，說：","notes":[]},{"n":2,"t":"耶和華的靈藉著我說：他的話在我口中。","notes":[]},{"n":3,"t":"以色列的神、以色列的磐石曉諭我說：那以公義治理人民的，敬畏神執掌權柄，","notes":[]},{"n":4,"t":"他必像日出的晨光，如無雲的清晨，雨後的晴光，使地發生嫩草。","notes":[]},{"n":5,"t":"我家在神面前並非如此；神卻與我立永遠的約。這約凡事堅穩，關乎我的一切救恩和我一切所想望的，他豈不為我成就嗎？","notes":[]},{"n":6,"t":"但匪類都必像荊棘被丟棄；人不敢用手拿它；","notes":[]},{"n":7,"t":"拿它的人必帶鐵器和槍桿，終久它必被火焚燒。","notes":[]},{"n":8,"t":"大衛勇士的名字記在下面：他革捫人約設‧巴設，又稱伊斯尼人亞底挪，他是軍長的統領，一時擊殺了八百人。","notes":[],"heads":["大衛的勇士"]},{"n":9,"t":"其次是亞合人朵多的兒子以利亞撒。從前非利士人聚集要打仗，以色列人迎著上去，有跟隨大衛的三個勇士向非利士人罵陣，其中有以利亞撒。","notes":[]},{"n":10,"t":"他起來擊殺非利士人，直到手臂疲乏，手黏住刀把。那日耶和華使以色列人大獲全勝；眾民在以利亞撒後頭專奪財物。","notes":[]},{"n":11,"t":"其次是哈拉人亞基的兒子沙瑪。一日，非利士人聚集成群，在一塊長滿紅豆的田裏，眾民就在非利士人面前逃跑。","notes":[]},{"n":12,"t":"沙瑪卻站在那田間擊殺非利士人，救護了那田。耶和華使以色列人大獲全勝。","notes":[]},{"n":13,"t":"收割的時候，有三十個勇士中的三個人下到亞杜蘭洞見大衛。非利士的軍兵在利乏音谷安營。","notes":[]},{"n":14,"t":"那時大衛在山寨，非利士人的防營在伯利恆。","notes":[]},{"n":15,"t":"大衛渴想，說：「甚願有人將伯利恆城門旁、井裏的水打來給我喝。」","notes":[]},{"n":16,"t":"這三個勇士就闖過非利士人的營盤，從伯利恆城門旁的井裏打水，拿來奉給大衛。他卻不肯喝，將水奠在耶和華面前，","notes":[]},{"n":17,"t":"說：「耶和華啊，這三個人冒死去打水；這水好像他們的血一般，我斷不敢喝。」如此，大衛不肯喝。這是三個勇士所做的事。","notes":[]},{"n":18,"t":"洗魯雅的兒子、約押的兄弟亞比篩是這三個勇士的首領；他舉槍殺了三百人，就在三個勇士裏得了名。","notes":[]},{"n":19,"t":"他在這三個勇士裏是最尊貴的，所以作他們的首領，只是不及前三個勇士。","notes":[]},{"n":20,"t":"有甲薛勇士耶何耶大的兒子比拿雅行過大能的事；他殺了摩押人亞利伊勒的兩個兒子，又在下雪的時候下坑裏去，殺了一個獅子，","notes":[]},{"n":21,"t":"又殺了一個強壯的埃及人；埃及人手裏拿著槍，比拿雅只拿著棍子下去，從埃及人手裏奪過槍來，用那槍將他殺死。","notes":[]},{"n":22,"t":"這是耶何耶大的兒子比拿雅所行的事，就在三個勇士裏得了名。","notes":[]},{"n":23,"t":"他比那三十個勇士都尊貴，只是不及前三個勇士。大衛立他作護衛長。","notes":[]},{"n":24,"t":"三十個勇士裏有約押的兄弟亞撒黑，伯利恆人朵多的兒子伊勒哈難，","notes":[]},{"n":25,"t":"哈律人沙瑪，哈律人以利加，","notes":[]},{"n":26,"t":"帕勒提人希利斯，提哥亞人益吉的兒子以拉，","notes":[]},{"n":27,"t":"亞拿突人亞比以謝，戶沙人米本乃，","notes":[]},{"n":28,"t":"亞合人撒們，尼陀法人瑪哈萊，","notes":[]},{"n":29,"t":"尼陀法人巴拿的兒子希立，便雅憫族、基比亞人利拜的兒子以太，","notes":[]},{"n":30,"t":"比拉頓人比拿雅，迦實溪人希太，","notes":[]},{"n":31,"t":"伯亞拉巴人亞比亞本，巴魯米人押斯瑪弗，","notes":[]},{"n":32,"t":"沙本人以利雅哈巴，雅善兒子中的約拿單，","notes":[]},{"n":33,"t":"哈拉人沙瑪，哈拉人沙拉的兒子亞希暗，","notes":[]},{"n":34,"t":"瑪迦人亞哈拜的兒子以利法列，基羅人亞希多弗的兒子以連，","notes":[]},{"n":35,"t":"迦密人希斯萊，亞巴人帕萊，","notes":[]},{"n":36,"t":"瑣巴人拿單的兒子以甲，迦得人巴尼，","notes":[]},{"n":37,"t":"亞捫人洗勒，比錄人拿哈萊（是給洗魯雅的兒子約押拿兵器的），","notes":[]},{"n":38,"t":"以帖人以拉，以帖人迦立，","notes":[]},{"n":39,"t":"赫人烏利亞，共有三十七人。","notes":[]}]},"24":{"heading":"大衛調查人口","verses":[{"n":1,"t":"耶和華又向以色列人發怒，就激動大衛，使他吩咐人去數點以色列人和猶大人。","notes":[]},{"n":2,"t":"大衛就吩咐跟隨他的元帥約押說：「你去走遍以色列眾支派，從但直到別是巴，數點百姓，我好知道他們的數目。」","notes":[]},{"n":3,"t":"約押對王說：「無論百姓多少，願耶和華－你的神再加增百倍，使我主我王親眼得見。我主我王何必喜悅行這事呢？」","notes":[]},{"n":4,"t":"但王的命令勝過約押和眾軍長。約押和眾軍長就從王面前出去，數點以色列的百姓。","notes":[]},{"n":5,"t":"他們過了約旦河，在迦得谷中、城的右邊亞羅珥安營，與雅謝相對，","notes":[]},{"n":6,"t":"又到了基列和他停‧合示地，又到了但‧雅安，繞到西頓，","notes":[]},{"n":7,"t":"來到泰爾的保障，並希未人和迦南人的各城，又到猶大南方的別是巴。","notes":[]},{"n":8,"t":"他們走遍全地，過了九個月零二十天，就回到耶路撒冷。","notes":[]},{"n":9,"t":"約押將百姓的總數奏告於王：以色列拿刀的勇士有八十萬；猶大有五十萬。","notes":[]},{"n":10,"t":"大衛數點百姓以後，就心中自責，禱告耶和華說：「我行這事大有罪了。耶和華啊，求你除掉僕人的罪孽，因我所行的甚是愚昧。」","notes":[]},{"n":11,"t":"大衛早晨起來，耶和華的話臨到先知迦得，就是大衛的先見，說：","notes":[]},{"n":12,"t":"「你去告訴大衛，說耶和華如此說：『我有三樣災，隨你選擇一樣，我好降與你。』」","notes":[]},{"n":13,"t":"於是迦得來見大衛，對他說：「你願意國中有七年的饑荒呢？是在你敵人面前逃跑，被追趕三個月呢？是在你國中有三日的瘟疫呢？現在你要揣摩思想，我好回覆那差我來的。」","notes":[]},{"n":14,"t":"大衛對迦得說：「我甚為難！我願落在耶和華的手裏，因為他有豐盛的憐憫。我不願落在人的手裏。」","notes":[]},{"n":15,"t":"於是，耶和華降瘟疫與以色列人，自早晨到所定的時候；從但直到別是巴，民間死了七萬人。","notes":[]},{"n":16,"t":"天使向耶路撒冷伸手要滅城的時候，耶和華後悔，就不降這災了，吩咐滅民的天使說：「夠了！住手吧！」那時耶和華的使者在耶布斯人亞勞拿的禾場那裏。","notes":[]},{"n":17,"t":"大衛看見滅民的天使，就禱告耶和華說：「我犯了罪，行了惡；但這群羊做了甚麼呢？願你的手攻擊我和我的父家。」","notes":[]},{"n":18,"t":"當日，迦得來見大衛，對他說：「你上去，在耶布斯人亞勞拿的禾場上為耶和華築一座壇。」","notes":[]},{"n":19,"t":"大衛就照著迦得奉耶和華名所說的話上去了。","notes":[]},{"n":20,"t":"亞勞拿觀看，見王和他臣僕前來，就迎接出去，臉伏於地，向王下拜，","notes":[]},{"n":21,"t":"說：「我主我王為何來到僕人這裏呢？」大衛說：「我要買你這禾場，為耶和華築一座壇，使民間的瘟疫止住。」","notes":[]},{"n":22,"t":"亞勞拿對大衛說：「我主我王，你喜悅用甚麼，就拿去獻祭。看哪，這裏有牛可以作燔祭，有打糧的器具和套牛的軛可以當柴燒。","notes":[]},{"n":23,"t":"王啊，這一切，我亞勞拿都奉給你」；又對王說：「願耶和華－你的神悅納你。」","notes":[]},{"n":24,"t":"王對亞勞拿說：「不然。我必要按著價值向你買；我不肯用白得之物作燔祭獻給耶和華－我的神。」大衛就用五十舍客勒銀子買了那禾場與牛。","notes":[]},{"n":25,"t":"大衛在那裏為耶和華築了一座壇，獻燔祭和平安祭。如此，耶和華垂聽國民所求的，瘟疫在以色列人中就止住了。","notes":[]}]}},"1KI":{"1":{"heading":"大衛王的晚年","verses":[{"n":1,"t":"大衛王年紀老邁，雖用被遮蓋，仍不覺暖。","notes":[]},{"n":2,"t":"所以臣僕對他說：「不如為我主我王尋找一個處女，使她伺候王，奉養王，睡在王的懷中，好叫我主我王得暖。」","notes":[]},{"n":3,"t":"於是在以色列全境尋找美貌的童女，尋得書念的一個童女亞比煞，就帶到王那裏。","notes":[]},{"n":4,"t":"這童女極其美貌，她奉養王，伺候王，王卻沒有與她親近。","notes":[]},{"n":5,"t":"那時，哈及的兒子亞多尼雅自尊，說：「我必作王」，就為自己預備車輛、馬兵，又派五十人在他前頭奔走。","notes":[],"heads":["亞多尼雅謀篡王位"]},{"n":6,"t":"他父親素來沒有使他憂悶，說：「你是做甚麼呢？」他甚俊美，生在押沙龍之後。","notes":[]},{"n":7,"t":"亞多尼雅與洗魯雅的兒子約押，和祭司亞比亞他商議；二人就順從他，幫助他。","notes":[]},{"n":8,"t":"但祭司撒督、耶何耶大的兒子比拿雅、先知拿單、示每、利以，並大衛的勇士都不順從亞多尼雅。","notes":[]},{"n":9,"t":"一日，亞多尼雅在隱‧羅結旁、瑣希列磐石那裏宰了牛羊、肥犢，請他的諸弟兄，就是王的眾子，並所有作王臣僕的猶大人；","notes":[]},{"n":10,"t":"惟獨先知拿單和比拿雅並勇士，與他的兄弟所羅門，他都沒有請。","notes":[]},{"n":11,"t":"拿單對所羅門的母親拔示巴說：「哈及的兒子亞多尼雅作王了，你沒有聽見嗎？我們的主大衛卻不知道。","notes":[],"heads":["所羅門被立為王"]},{"n":12,"t":"現在我可以給你出個主意，好保全你和你兒子所羅門的性命。","notes":[]},{"n":13,"t":"你進去見大衛王，對他說：『我主我王啊，你不曾向婢女起誓說：你兒子所羅門必接續我作王，坐在我的位上嗎？現在亞多尼雅怎麼作了王呢？』","notes":[]},{"n":14,"t":"你還與王說話的時候，我也隨後進去，證實你的話。」","notes":[]},{"n":15,"t":"拔示巴進入內室見王，王甚老邁，書念的童女亞比煞正伺候王。","notes":[]},{"n":16,"t":"拔示巴向王屈身下拜；王說：「你要甚麼？」","notes":[]},{"n":17,"t":"她說：「我主啊，你曾向婢女指著耶和華－你的神起誓說：『你兒子所羅門必接續我作王，坐在我的位上。』","notes":[]},{"n":18,"t":"現在亞多尼雅作王了，我主我王卻不知道。","notes":[]},{"n":19,"t":"他宰了許多牛羊、肥犢，請了王的眾子和祭司亞比亞他，並元帥約押；惟獨王的僕人所羅門，他沒有請。","notes":[]},{"n":20,"t":"我主我王啊，以色列眾人的眼目都仰望你，等你曉諭他們，在我主我王之後誰坐你的位。","notes":[]},{"n":21,"t":"若不然，到我主我王與列祖同睡以後，我和我兒子所羅門必算為罪人了。」","notes":[]},{"n":22,"t":"拔示巴還與王說話的時候，先知拿單也進來了。","notes":[]},{"n":23,"t":"有人奏告王說：「先知拿單來了。」拿單進到王前，臉伏於地。","notes":[]},{"n":24,"t":"拿單說：「我主我王果然應許亞多尼雅說『你必接續我作王，坐在我的位上』嗎？","notes":[]},{"n":25,"t":"他今日下去，宰了許多牛羊、肥犢，請了王的眾子和軍長，並祭司亞比亞他；他們正在亞多尼雅面前吃喝，說：『願亞多尼雅王萬歲！』","notes":[]},{"n":26,"t":"惟獨我，就是你的僕人和祭司撒督，耶何耶大的兒子比拿雅，並王的僕人所羅門，他都沒有請。","notes":[]},{"n":27,"t":"這事果然出乎我主我王嗎？王卻沒有告訴僕人們，在我主我王之後誰坐你的位。」","notes":[]},{"n":28,"t":"大衛王吩咐說：「叫拔示巴來。」拔示巴就進來，站在王面前。","notes":[]},{"n":29,"t":"王起誓說：「我指著救我性命脫離一切苦難、永生的耶和華起誓。","notes":[]},{"n":30,"t":"我既然指著耶和華－以色列的神向你起誓說：你兒子所羅門必接續我作王，坐在我的位上。我今日就必照這話而行。」","notes":[]},{"n":31,"t":"於是，拔示巴臉伏於地，向王下拜，說：「願我主大衛王萬歲！」","notes":[]},{"n":32,"t":"大衛王又吩咐說：「將祭司撒督、先知拿單、耶何耶大的兒子比拿雅召來！」他們就都來到王面前。","notes":[]},{"n":33,"t":"王對他們說：「要帶領你們主的僕人，使我兒子所羅門騎我的騾子，送他下到基訓；","notes":[]},{"n":34,"t":"在那裏，祭司撒督和先知拿單要膏他作以色列的王；你們也要吹角，說：『願所羅門王萬歲！』","notes":[]},{"n":35,"t":"然後要跟隨他上來，使他坐在我的位上，接續我作王。我已立他作以色列和猶大的君。」","notes":[]},{"n":36,"t":"耶何耶大的兒子比拿雅對王說：「阿們！願耶和華－我主我王的神也這樣命定。","notes":[]},{"n":37,"t":"耶和華怎樣與我主我王同在，願他照樣與所羅門同在，使他的國位比我主大衛王的國位更大。」","notes":[]},{"n":38,"t":"於是，祭司撒督、先知拿單、耶何耶大的兒子比拿雅，和基利提人、比利提人都下去使所羅門騎大衛王的騾子，將他送到基訓。","notes":[]},{"n":39,"t":"祭司撒督就從帳幕中取了盛膏油的角來，用膏膏所羅門。人就吹角，眾民都說：「願所羅門王萬歲！」","notes":[]},{"n":40,"t":"眾民跟隨他上來，且吹笛，大大歡呼，聲音震地。","notes":[]},{"n":41,"t":"亞多尼雅和所請的眾客筵宴方畢，聽見這聲音；約押聽見角聲就說：「城中為何有這響聲呢？」","notes":[]},{"n":42,"t":"他正說話的時候，祭司亞比亞他的兒子約拿單來了。亞多尼雅對他說：「進來吧！你是個忠義的人，必是報好信息。」","notes":[]},{"n":43,"t":"約拿單對亞多尼雅說：「我們的主大衛王誠然立所羅門為王了。","notes":[]},{"n":44,"t":"王差遣祭司撒督、先知拿單、耶何耶大的兒子比拿雅，和基利提人、比利提人都去使所羅門騎王的騾子。","notes":[]},{"n":45,"t":"祭司撒督和先知拿單在基訓已經膏他作王。眾人都從那裏歡呼著上來，聲音使城震動，這就是你們所聽見的聲音；","notes":[]},{"n":46,"t":"並且所羅門登了國位。","notes":[]},{"n":47,"t":"王的臣僕也來為我們的主大衛王祝福，說：『願王的神使所羅門的名比王的名更尊榮；使他的國位比王的國位更大。』王就在床上屈身下拜。","notes":[]},{"n":48,"t":"王又說：『耶和華－以色列的神是應當稱頌的；因他賜我一人今日坐在我的位上，我也親眼看見了。』」","notes":[]},{"n":49,"t":"亞多尼雅的眾客聽見這話就都驚懼，起來四散。","notes":[]},{"n":50,"t":"亞多尼雅懼怕所羅門，就起來，去抓住祭壇的角。","notes":[]},{"n":51,"t":"有人告訴所羅門說：「亞多尼雅懼怕所羅門王，現在抓住祭壇的角，說：『願所羅門王今日向我起誓，必不用刀殺僕人。』」","notes":[]},{"n":52,"t":"所羅門說：「他若作忠義的人，連一根頭髮也不致落在地上；他若行惡，必要死亡。」","notes":[]},{"n":53,"t":"於是所羅門王差遣人，使亞多尼雅從壇上下來，他就來，向所羅門王下拜；所羅門對他說：「你回家去吧！」","notes":[]}]},"2":{"heading":"大衛給所羅門的遺訓","verses":[{"n":1,"t":"大衛的死期臨近了，就囑咐他兒子所羅門說：","notes":[]},{"n":2,"t":"「我現在要走世人必走的路。所以，你當剛強，作大丈夫，","notes":[]},{"n":3,"t":"遵守耶和華－你神所吩咐的，照著摩西律法上所寫的行主的道，謹守他的律例、誡命、典章、法度。這樣，你無論做甚麼事，不拘往何處去，盡都亨通。","notes":[]},{"n":4,"t":"耶和華必成就向我所應許的話說：『你的子孫若謹慎自己的行為，盡心盡意誠誠實實地行在我面前，就不斷人坐以色列的國位。』","notes":[]},{"n":5,"t":"你知道洗魯雅的兒子約押向我所行的，就是殺了以色列的兩個元帥：尼珥的兒子押尼珥和益帖的兒子亞瑪撒。他在太平之時流這二人的血，如在爭戰之時一樣，將這血染了腰間束的帶和腳上穿的鞋。","notes":[]},{"n":6,"t":"所以你要照你的智慧行，不容他白頭安然下陰間。","notes":[]},{"n":7,"t":"你當恩待基列人巴西萊的眾子，使他們常與你同席吃飯；因為我躲避你哥哥押沙龍的時候，他們拿食物來迎接我。","notes":[]},{"n":8,"t":"在你這裏有巴戶琳的便雅憫人，基拉的兒子示每；我往瑪哈念去的那日，他用狠毒的言語咒罵我，後來卻下約旦河迎接我，我就指著耶和華向他起誓說：『我必不用刀殺你。』","notes":[]},{"n":9,"t":"現在你不要以他為無罪。你是聰明人，必知道怎樣待他，使他白頭見殺，流血下到陰間。」","notes":[]},{"n":10,"t":"大衛與他列祖同睡，葬在大衛城。","notes":[],"heads":["大衛壽終"]},{"n":11,"t":"大衛作以色列王四十年：在希伯崙作王七年，在耶路撒冷作王三十三年。","notes":[]},{"n":12,"t":"所羅門坐他父親大衛的位，他的國甚是堅固。","notes":[]},{"n":13,"t":"哈及的兒子亞多尼雅去見所羅門的母親拔示巴，拔示巴問他說：「你來是為平安嗎？」回答說：「是為平安」；","notes":[],"heads":["亞多尼雅的死"]},{"n":14,"t":"又說：「我有話對你說。」拔示巴說：「你說吧。」","notes":[]},{"n":15,"t":"亞多尼雅說：「你知道國原是歸我的，以色列眾人也都仰望我作王，不料，國反歸了我兄弟，因他得國是出乎耶和華。","notes":[]},{"n":16,"t":"現在我有一件事求你，望你不要推辭。」拔示巴說：「你說吧。」","notes":[]},{"n":17,"t":"他說：「求你請所羅門王將書念的女子亞比煞賜我為妻，因他必不推辭你。」","notes":[]},{"n":18,"t":"拔示巴說：「好，我必為你對王提說。」","notes":[]},{"n":19,"t":"於是，拔示巴去見所羅門王，要為亞多尼雅提說；王起來迎接，向她下拜，就坐在位上，吩咐人為王母設一座位，她便坐在王的右邊。","notes":[]},{"n":20,"t":"拔示巴說：「我有一件小事求你，望你不要推辭。」王說：「請母親說，我必不推辭。」","notes":[]},{"n":21,"t":"拔示巴說：「求你將書念的女子亞比煞賜給你哥哥亞多尼雅為妻。」","notes":[]},{"n":22,"t":"所羅門王對他母親說：「為何單替他求書念的女子亞比煞呢？也可以為他求國吧！他是我的哥哥，他有祭司亞比亞他和洗魯雅的兒子約押為輔佐。」","notes":[]},{"n":23,"t":"所羅門王就指著耶和華起誓說：「亞多尼雅這話是自己送命，不然，願神重重地降罰與我。","notes":[]},{"n":24,"t":"耶和華堅立我，使我坐在父親大衛的位上，照著所應許的話為我建立家室；現在我指著永生的耶和華起誓，亞多尼雅今日必被治死。」","notes":[]},{"n":25,"t":"於是所羅門王差遣耶何耶大的兒子比拿雅，將亞多尼雅殺死。","notes":[]},{"n":26,"t":"王對祭司亞比亞他說：「你回亞拿突歸自己的田地去吧！你本是該死的，但因你在我父親大衛面前抬過主耶和華的約櫃，又與我父親同受一切苦難，所以我今日不將你殺死。」","notes":[],"heads":["亞比亞他被廢和約押的死"]},{"n":27,"t":"所羅門就革除亞比亞他，不許他作耶和華的祭司。這樣，便應驗耶和華在示羅論以利家所說的話。","notes":[]},{"n":28,"t":"約押雖然沒有歸從押沙龍，卻歸從了亞多尼雅。他聽見這風聲，就逃到耶和華的帳幕，抓住祭壇的角。","notes":[]},{"n":29,"t":"有人告訴所羅門王說：「約押逃到耶和華的帳幕，現今在祭壇的旁邊。」所羅門就差遣耶何耶大的兒子比拿雅，說：「你去將他殺死。」","notes":[]},{"n":30,"t":"比拿雅來到耶和華的帳幕，對約押說：「王吩咐說，你出來吧！」他說：「我不出去，我要死在這裏。」比拿雅就去回覆王，說約押如此如此回答我。","notes":[]},{"n":31,"t":"王說：「你可以照著他的話行，殺死他，將他葬埋，好叫約押流無辜人血的罪不歸我和我的父家了。","notes":[]},{"n":32,"t":"耶和華必使約押流人血的罪歸到他自己的頭上；因為他用刀殺了兩個比他又義又好的人，就是以色列元帥尼珥的兒子押尼珥和猶大元帥益帖的兒子亞瑪撒，我父親大衛卻不知道。","notes":[]},{"n":33,"t":"故此，流這二人血的罪必歸到約押和他後裔的頭上，直到永遠；惟有大衛和他的後裔，並他的家與國，必從耶和華那裏得平安，直到永遠。」","notes":[]},{"n":34,"t":"於是耶何耶大的兒子比拿雅上去，將約押殺死，葬在曠野約押自己的墳墓裏。","notes":["原文是房屋"]},{"n":35,"t":"王就立耶何耶大的兒子比拿雅作元帥，代替約押，又使祭司撒督代替亞比亞他。","notes":[]},{"n":36,"t":"王差遣人將示每召來，對他說：「你要在耶路撒冷建造房屋居住，不可出來往別處去。","notes":[],"heads":["示每的死"]},{"n":37,"t":"你當確實地知道，你何日出來過汲淪溪，何日必死！你的罪必歸到自己的頭上。」","notes":["原文是血"]},{"n":38,"t":"示每對王說：「這話甚好！我主我王怎樣說，僕人必怎樣行。」於是示每多日住在耶路撒冷。","notes":[]},{"n":39,"t":"過了三年，示每的兩個僕人逃到迦特王瑪迦的兒子亞吉那裏去。有人告訴示每說：「你的僕人在迦特。」","notes":[]},{"n":40,"t":"示每起來，備上驢，往迦特到亞吉那裏去找他的僕人，就從迦特帶他僕人回來。","notes":[]},{"n":41,"t":"有人告訴所羅門說：「示每出耶路撒冷往迦特去，回來了。」","notes":[]},{"n":42,"t":"王就差遣人將示每召了來，對他說：「我豈不是叫你指著耶和華起誓，並且警戒你說『你當確實地知道，你哪日出來往別處去，那日必死』嗎？你也對我說：『這話甚好，我必聽從。』","notes":[]},{"n":43,"t":"現在你為何不遵守你指著耶和華起的誓和我所吩咐你的命令呢？」","notes":[]},{"n":44,"t":"王又對示每說：「你向我父親大衛所行的一切惡事，你自己心裏也知道，所以耶和華必使你的罪惡歸到自己的頭上；","notes":[]},{"n":45,"t":"惟有所羅門王必得福，並且大衛的國位必在耶和華面前堅定，直到永遠。」","notes":[]},{"n":46,"t":"於是王吩咐耶何耶大的兒子比拿雅，他就去殺死示每。這樣，便堅定了所羅門的國位。","notes":[]}]},"3":{"heading":"所羅門祈禱求智慧","verses":[{"n":1,"t":"所羅門與埃及王法老結親，娶了法老的女兒為妻，接她進入大衛城，直等到造完了自己的宮和耶和華的殿，並耶路撒冷周圍的城牆。","notes":[]},{"n":2,"t":"當那些日子，百姓仍在邱壇獻祭，因為還沒有為耶和華的名建殿。","notes":[]},{"n":3,"t":"所羅門愛耶和華，遵行他父親大衛的律例，只是還在邱壇獻祭燒香。","notes":[]},{"n":4,"t":"所羅門王上基遍去獻祭；因為在那裏有極大的邱壇，他在那壇上獻一千犧牲作燔祭。","notes":["或譯：出名"]},{"n":5,"t":"在基遍，夜間夢中，耶和華向所羅門顯現，對他說：「你願我賜你甚麼？你可以求。」","notes":[]},{"n":6,"t":"所羅門說：「你僕人－我父親大衛用誠實、公義、正直的心行在你面前，你就向他大施恩典，又為他存留大恩，賜他一個兒子坐在他的位上，正如今日一樣。","notes":[]},{"n":7,"t":"耶和華－我的神啊，如今你使僕人接續我父親大衛作王；但我是幼童，不知道應當怎樣出入。","notes":[]},{"n":8,"t":"僕人住在你所揀選的民中，這民多得不可勝數。","notes":[]},{"n":9,"t":"所以求你賜我智慧，可以判斷你的民，能辨別是非。不然，誰能判斷這眾多的民呢？」","notes":[]},{"n":10,"t":"所羅門因為求這事，就蒙主喜悅。","notes":[]},{"n":11,"t":"神對他說：「你既然求這事，不為自己求壽、求富，也不求滅絕你仇敵的性命，單求智慧可以聽訟，","notes":[]},{"n":12,"t":"我就應允你所求的，賜你聰明智慧，甚至在你以前沒有像你的，在你以後也沒有像你的。","notes":[]},{"n":13,"t":"你所沒有求的，我也賜給你，就是富足、尊榮，使你在世的日子，列王中沒有一個能比你的。","notes":[]},{"n":14,"t":"你若效法你父親大衛，遵行我的道，謹守我的律例、誡命，我必使你長壽。」","notes":[]},{"n":15,"t":"所羅門醒了，不料是個夢。他就回到耶路撒冷，站在耶和華的約櫃前，獻燔祭和平安祭，又為他眾臣僕設擺筵席。","notes":[]},{"n":16,"t":"一日，有兩個妓女來，站在王面前。","notes":[],"heads":["所羅門審斷一件疑難的案件"]},{"n":17,"t":"一個說：「我主啊，我和這婦人同住一房；她在房中的時候，我生了一個男孩。","notes":[]},{"n":18,"t":"我生孩子後第三日，這婦人也生了孩子。我們是同住的，除了我們二人之外，房中再沒有別人。","notes":[]},{"n":19,"t":"夜間，這婦人睡著的時候，壓死了她的孩子。","notes":[]},{"n":20,"t":"她半夜起來，趁我睡著，從我旁邊把我的孩子抱去，放在她懷裏，將她的死孩子放在我懷裏。","notes":[]},{"n":21,"t":"天要亮的時候，我起來要給我的孩子吃奶，不料，孩子死了；及至天亮，我細細地察看，不是我所生的孩子。」","notes":[]},{"n":22,"t":"那婦人說：「不然，活孩子是我的，死孩子是你的。」這婦人說：「不然，死孩子是你的，活孩子是我的。」她們在王面前如此爭論。","notes":[]},{"n":23,"t":"王說：「這婦人說『活孩子是我的，死孩子是你的』，那婦人說『不然，死孩子是你的，活孩子是我的』」，","notes":[]},{"n":24,"t":"就吩咐說：「拿刀來！」人就拿刀來。","notes":[]},{"n":25,"t":"王說：「將活孩子劈成兩半，一半給那婦人，一半給這婦人。」","notes":[]},{"n":26,"t":"活孩子的母親為自己的孩子心裏急痛，就說：「求我主將活孩子給那婦人吧，萬不可殺他！」那婦人說：「這孩子也不歸我，也不歸你，把他劈了吧！」","notes":[]},{"n":27,"t":"王說：「將活孩子給這婦人，萬不可殺他；這婦人實在是他的母親。」","notes":[]},{"n":28,"t":"以色列眾人聽見王這樣判斷，就都敬畏他；因為見他心裏有神的智慧，能以斷案。","notes":[]}]},"4":{"heading":"所羅門的臣僕","verses":[{"n":1,"t":"所羅門作以色列眾人的王。","notes":[]},{"n":2,"t":"他的臣子記在下面：撒督的兒子亞撒利雅作祭司，","notes":[]},{"n":3,"t":"示沙的兩個兒子以利何烈、亞希亞作書記，亞希律的兒子約沙法作史官，","notes":[]},{"n":4,"t":"耶何耶大的兒子比拿雅作元帥，撒督和亞比亞他作祭司長，","notes":[]},{"n":5,"t":"拿單的兒子亞撒利雅作眾吏長，王的朋友拿單的兒子撒布得作領袖，","notes":[]},{"n":6,"t":"亞希煞作家宰，亞比大的兒子亞多尼蘭掌管服苦的人。","notes":[]},{"n":7,"t":"所羅門在以色列全地立了十二個官吏，使他們供給王和王家的食物，每年各人供給一月。","notes":[]},{"n":8,"t":"他們的名字記在下面：在以法蓮山地有便‧戶珥；","notes":[]},{"n":9,"t":"在瑪迦斯、沙賓、伯‧示麥、以倫‧伯‧哈南有便‧底甲；","notes":[]},{"n":10,"t":"在亞魯泊有便‧希悉，他管理梭哥和希弗全地；","notes":[]},{"n":11,"t":"在多珥山岡有便‧亞比拿達，他娶了所羅門的女兒她法為妻；","notes":["或譯：全境"]},{"n":12,"t":"在他納和米吉多，並靠近撒拉他拿、耶斯列下邊的伯‧善全地，從伯‧善到亞伯‧米何拉直到約念之外，有亞希律的兒子巴拿；","notes":[]},{"n":13,"t":"在基列的拉末有便‧基別，他管理在基列的瑪拿西子孫睚珥的城邑，巴珊的亞珥歌伯地的大城六十座，都有城牆和銅閂；","notes":[]},{"n":14,"t":"在瑪哈念有易多的兒子亞希拿達；","notes":[]},{"n":15,"t":"在拿弗他利有亞希瑪斯，他也娶了所羅門的一個女兒巴實抹為妻；","notes":[]},{"n":16,"t":"在亞設和亞祿有戶篩的兒子巴拿；","notes":[]},{"n":17,"t":"在以薩迦有帕路亞的兒子約沙法；","notes":[]},{"n":18,"t":"在便雅憫有以拉的兒子示每；","notes":[]},{"n":19,"t":"在基列地，就是從前屬亞摩利王西宏和巴珊王噩之地，有烏利的兒子基別一人管理。","notes":[]},{"n":20,"t":"猶大人和以色列人如同海邊的沙那樣多，都吃喝快樂。","notes":[],"heads":["所羅門的富強"]},{"n":21,"t":"所羅門統管諸國，從大河到非利士地，直到埃及的邊界。所羅門在世的日子，這些國都進貢服事他。","notes":[]},{"n":22,"t":"所羅門每日所用的食物：細麵三十歌珥，粗麵六十歌珥，","notes":[]},{"n":23,"t":"肥牛十隻，草場的牛二十隻，羊一百隻，還有鹿、羚羊、麅子，並肥禽。","notes":[]},{"n":24,"t":"所羅門管理大河西邊的諸王，以及從提弗薩直到迦薩的全地，四境盡都平安。","notes":[]},{"n":25,"t":"所羅門在世的日子，從但到別是巴的猶大人和以色列人都在自己的葡萄樹下和無花果樹下安然居住。","notes":[]},{"n":26,"t":"所羅門有套車的馬四萬，還有馬兵一萬二千。","notes":[]},{"n":27,"t":"那十二個官吏各按各月供給所羅門王，並一切與他同席之人的食物，一無所缺。","notes":[]},{"n":28,"t":"眾人各按各分，將養馬與快馬的大麥和乾草送到官吏那裏。","notes":[]},{"n":29,"t":"神賜給所羅門極大的智慧聰明和廣大的心，如同海沙不可測量。","notes":[],"heads":["所羅門的智慧"]},{"n":30,"t":"所羅門的智慧超過東方人和埃及人的一切智慧。","notes":[]},{"n":31,"t":"他的智慧勝過萬人，勝過以斯拉人以探，並瑪曷的兒子希幔、甲各、達大的智慧。他的名聲傳揚在四圍的列國。","notes":[]},{"n":32,"t":"他作箴言三千句，詩歌一千零五首。","notes":[]},{"n":33,"t":"他講論草木，自黎巴嫩的香柏樹直到牆上長的牛膝草，又講論飛禽走獸、昆蟲水族。","notes":[]},{"n":34,"t":"天下列王聽見所羅門的智慧，就都差人來聽他的智慧話。","notes":[]}]},"5":{"heading":"所羅門準備建殿","verses":[{"n":1,"t":"泰爾王希蘭，平素愛大衛；他聽見以色列人膏所羅門，接續他父親作王，就差遣臣僕來見他。","notes":[]},{"n":2,"t":"所羅門也差遣人去見希蘭，說：","notes":[]},{"n":3,"t":"「你知道我父親大衛因四圍的爭戰，不能為耶和華－他神的名建殿，直等到耶和華使仇敵都服在他腳下。","notes":[]},{"n":4,"t":"現在耶和華－我的神使我四圍平安，沒有仇敵，沒有災禍。","notes":[]},{"n":5,"t":"我定意要為耶和華－我神的名建殿，是照耶和華應許我父親大衛的話說：『我必使你兒子接續你坐你的位，他必為我的名建殿。』","notes":[]},{"n":6,"t":"所以求你吩咐你的僕人在黎巴嫩為我砍伐香柏木，我的僕人也必幫助他們，我必照你所定的，給你僕人的工價；因為你知道，在我們中間沒有人像西頓人善於砍伐樹木。」","notes":[]},{"n":7,"t":"希蘭聽見所羅門的話，就甚喜悅，說：「今日應當稱頌耶和華；因他賜給大衛一個有智慧的兒子，治理這眾多的民。」","notes":[]},{"n":8,"t":"希蘭打發人去見所羅門，說：「你差遣人向我所提的那事，我都聽見了；論到香柏木和松木，我必照你的心願而行。","notes":[]},{"n":9,"t":"我的僕人必將這木料從黎巴嫩運到海裏，紮成筏子，浮海運到你所指定我的地方，在那裏拆開，你就可以收取；你也要成全我的心願，將食物給我的家。」","notes":[]},{"n":10,"t":"於是希蘭照著所羅門所要的，給他香柏木和松木；","notes":[]},{"n":11,"t":"所羅門給希蘭麥子二萬歌珥，清油二十歌珥，作他家的食物。所羅門每年都是這樣給希蘭。","notes":[]},{"n":12,"t":"耶和華照著所應許的賜智慧給所羅門。希蘭與所羅門和好，彼此立約。","notes":[]},{"n":13,"t":"所羅門王從以色列人中挑取服苦的人共有三萬，","notes":[]},{"n":14,"t":"派他們輪流每月一萬人上黎巴嫩去；一個月在黎巴嫩，兩個月在家裏。亞多尼蘭掌管他們。","notes":[]},{"n":15,"t":"所羅門用七萬扛抬的，八萬在山上鑿石頭的。","notes":[]},{"n":16,"t":"此外，所羅門用三千三百督工的，監管工人。","notes":[]},{"n":17,"t":"王下令，人就鑿出又大又寶貴的石頭來，用以立殿的根基。","notes":[]},{"n":18,"t":"所羅門的匠人和希蘭的匠人，並迦巴勒人，都將石頭鑿好，預備木料和石頭建殿。","notes":[]}]},"6":{"heading":"所羅門建造聖殿","verses":[{"n":1,"t":"以色列人出埃及地後四百八十年，所羅門作以色列王第四年西弗月，就是二月，開工建造耶和華的殿。","notes":[]},{"n":2,"t":"所羅門王為耶和華所建的殿，長六十肘，寬二十肘，高三十肘。","notes":[]},{"n":3,"t":"殿前的廊子長二十肘，與殿的寬窄一樣，闊十肘；","notes":[]},{"n":4,"t":"又為殿做了嚴緊的窗櫺。","notes":[]},{"n":5,"t":"靠著殿牆，圍著外殿內殿，造了三層旁屋；","notes":[]},{"n":6,"t":"下層寬五肘，中層寬六肘，上層寬七肘。殿外旁屋的樑木擱在殿牆坎上，免得插入殿牆。","notes":[]},{"n":7,"t":"建殿是用山中鑿成的石頭。建殿的時候，鎚子、斧子，和別樣鐵器的響聲都沒有聽見。","notes":[]},{"n":8,"t":"在殿右邊當中的旁屋有門，門內有旋螺的樓梯，可以上到第二層，從第二層可以上到第三層。","notes":[]},{"n":9,"t":"所羅門建殿，安置香柏木的棟樑，又用香柏木板遮蓋。","notes":[]},{"n":10,"t":"靠著殿所造的旁屋，每層高五肘，香柏木的棟樑擱在殿牆坎上。","notes":[]},{"n":11,"t":"耶和華的話臨到所羅門說：","notes":[],"heads":["耶和華的約"]},{"n":12,"t":"「論到你所建的這殿，你若遵行我的律例，謹守我的典章，遵從我的一切誡命，我必向你應驗我所應許你父親大衛的話。","notes":[]},{"n":13,"t":"我必住在以色列人中間，並不丟棄我民以色列。」","notes":[]},{"n":14,"t":"所羅門建造殿宇。","notes":[],"heads":["殿內的設備"]},{"n":15,"t":"殿裏面用香柏木板貼牆，從地到棚頂都用木板遮蔽，又用松木板鋪地。","notes":[]},{"n":16,"t":"內殿，就是至聖所，長二十肘，從地到棚頂用香柏木板遮蔽。","notes":["或譯：隔斷"]},{"n":17,"t":"內殿前的外殿，長四十肘。","notes":[]},{"n":18,"t":"殿裏一點石頭都不顯露，一概用香柏木遮蔽；上面刻著野瓜和初開的花。","notes":[]},{"n":19,"t":"殿裏預備了內殿，好安放耶和華的約櫃。","notes":[]},{"n":20,"t":"內殿長二十肘，寬二十肘，高二十肘，牆面都貼上精金；又用香柏木做壇，包上精金。","notes":[]},{"n":21,"t":"所羅門用精金貼了殿內的牆，又用金鍊子掛在內殿前門扇，用金包裹。","notes":[]},{"n":22,"t":"全殿都貼上金子，直到貼完；內殿前的壇，也都用金包裹。","notes":[]},{"n":23,"t":"他用橄欖木做兩個基路伯，各高十肘，安在內殿。","notes":[],"heads":["造二基路伯"]},{"n":24,"t":"這一個基路伯有兩個翅膀，各長五肘，從這翅膀尖到那翅膀尖共有十肘；","notes":[]},{"n":25,"t":"那一個基路伯的兩個翅膀也是十肘，兩個基路伯的尺寸、形像都是一樣。","notes":[]},{"n":26,"t":"這基路伯高十肘，那基路伯也是如此。","notes":[]},{"n":27,"t":"他將兩個基路伯安在內殿裏；基路伯的翅膀是張開的，這基路伯的一個翅膀挨著這邊的牆，那基路伯的一個翅膀挨著那邊的牆，裏邊的兩個翅膀在殿中間彼此相接；","notes":[]},{"n":28,"t":"又用金子包裹二基路伯。","notes":[]},{"n":29,"t":"內殿、外殿周圍的牆上都刻著基路伯、棕樹，和初開的花。","notes":[],"heads":["殿的裝飾"]},{"n":30,"t":"內殿、外殿的地板都貼上金子。","notes":[]},{"n":31,"t":"又用橄欖木製造內殿的門扇、門楣、門框；門口有牆的五分之一。","notes":[]},{"n":32,"t":"在橄欖木做的兩門扇上刻著基路伯、棕樹，和初開的花，都貼上金子。","notes":[]},{"n":33,"t":"又用橄欖木製造外殿的門框，門口有牆的四分之一。","notes":[]},{"n":34,"t":"用松木做門兩扇。這扇分兩扇，是摺疊的；那扇分兩扇，也是摺疊的。","notes":[]},{"n":35,"t":"上面刻著基路伯、棕樹，和初開的花，都用金子貼了。","notes":[]},{"n":36,"t":"他又用鑿成的石頭三層、香柏木一層建築內院。","notes":[]},{"n":37,"t":"所羅門在位第四年西弗月，立了耶和華殿的根基。","notes":[]},{"n":38,"t":"到十一年布勒月，就是八月，殿和一切屬殿的都按著樣式造成。他建殿的工夫共有七年。","notes":[]}]},"7":{"heading":"所羅門的王宮","verses":[{"n":1,"t":"所羅門為自己建造宮室，十三年方才造成；","notes":[]},{"n":2,"t":"又建造黎巴嫩林宮，長一百肘，寬五十肘，高三十肘，有香柏木柱三行，柱上有香柏木柁樑。","notes":["原文是四"]},{"n":3,"t":"其上以香柏木為蓋，每行柱子十五根，共有四十五根。","notes":[]},{"n":4,"t":"有窗戶三層，窗與窗相對。","notes":[]},{"n":5,"t":"所有的門框都是厚木見方的，有窗戶三層，窗與窗相對。","notes":[]},{"n":6,"t":"並建造有柱子的廊子，長五十肘，寬三十肘；在這廊前又有廊子，廊外有柱子和臺階。","notes":[]},{"n":7,"t":"又建造一廊，其中設立審判的座位，這廊從地到頂都用香柏木遮蔽。","notes":[]},{"n":8,"t":"廊後院內有所羅門住的宮室；工作與這工作相同。所羅門又為所娶法老的女兒建造一宮，做法與這廊子一樣。","notes":[]},{"n":9,"t":"建造這一切所用的石頭都是寶貴的，是按著尺寸鑿成的，是用鋸裏外鋸齊的；從根基直到檐石，從外頭直到大院，都是如此。","notes":[]},{"n":10,"t":"根基是寶貴的大石頭，有長十肘的，有長八肘的；","notes":[]},{"n":11,"t":"上面有香柏木和按著尺寸鑿成寶貴的石頭。","notes":[]},{"n":12,"t":"大院周圍有鑿成的石頭三層、香柏木一層，都照耶和華殿的內院和殿廊的樣式。","notes":[]},{"n":13,"t":"所羅門王差遣人往泰爾去，將戶蘭召了來。","notes":[],"heads":["戶蘭的工作"]},{"n":14,"t":"他是拿弗他利支派中一個寡婦的兒子，他父親是泰爾人，作銅匠的。戶蘭滿有智慧、聰明、技能，善於各樣銅作。他來到所羅門王那裏，做王一切所要做的。","notes":[]},{"n":15,"t":"他製造兩根銅柱，每根高十八肘，圍十二肘；","notes":[],"heads":["兩支銅柱"]},{"n":16,"t":"又用銅鑄了兩個柱頂安在柱上，各高五肘。","notes":[]},{"n":17,"t":"柱頂上有裝修的網子和擰成的鍊索，每頂七個。","notes":[]},{"n":18,"t":"網子周圍有兩行石榴遮蓋柱頂，兩個柱頂都是如此。","notes":[]},{"n":19,"t":"廊子的柱頂徑四肘，刻著百合花。","notes":[]},{"n":20,"t":"兩柱頂的鼓肚上挨著網子，各有兩行石榴環繞，兩行共有二百。","notes":[]},{"n":21,"t":"他將兩根柱子立在殿廊前頭：右邊立一根，起名叫雅斤；左邊立一根，起名叫波阿斯。","notes":[]},{"n":22,"t":"在柱頂上刻著百合花。這樣，造柱子的工就完畢了。","notes":[]},{"n":23,"t":"他又鑄一個銅海，樣式是圓的，高五肘，徑十肘，圍三十肘。","notes":[],"heads":["銅海"]},{"n":24,"t":"在海邊之下，周圍有野瓜的樣式；每肘十瓜，共有兩行，是鑄海的時候鑄上的。","notes":[]},{"n":25,"t":"有十二隻銅牛馱海：三隻向北，三隻向西，三隻向南，三隻向東；海在牛上，牛尾都向內。","notes":[]},{"n":26,"t":"海厚一掌，邊如杯邊，又如百合花，可容二千罷特。","notes":[]},{"n":27,"t":"他用銅製造十個盆座，每座長四肘，寬四肘，高三肘。","notes":[],"heads":["銅座"]},{"n":28,"t":"座的造法是這樣：四面都有心子，心子在邊子當中，","notes":[]},{"n":29,"t":"心子上有獅子和牛，並基路伯；邊上有小座，獅子和牛以下有垂下的瓔珞。","notes":[]},{"n":30,"t":"每盆座有四個銅輪和銅軸。小座的四角上在盆以下，有鑄成的盆架，其旁都有瓔珞。","notes":[]},{"n":31,"t":"小座高一肘，口是圓的，彷彿座的樣式，徑一肘半，在口上有雕工，心子是方的，不是圓的。","notes":[]},{"n":32,"t":"四個輪子在心子以下，輪軸與座相連，每輪高一肘半。","notes":[]},{"n":33,"t":"輪的樣式如同車輪；軸、輞、輻、轂都是鑄的。","notes":[]},{"n":34,"t":"每座四角上都有盆架，是與座一同鑄成的。","notes":[]},{"n":35,"t":"座上有圓架，高半肘；座上有撐子和心子，是與座一同鑄的。","notes":[]},{"n":36,"t":"在撐子和心子上刻著基路伯、獅子，和棕樹，周圍有瓔珞。","notes":[]},{"n":37,"t":"十個盆座都是這樣，鑄法、尺寸、樣式相同。","notes":[]},{"n":38,"t":"又用銅製造十個盆，每盆可容四十罷特。盆徑四肘，在那十座上，每座安設一盆。","notes":[]},{"n":39,"t":"五個安在殿門的右邊，五個放在殿門的左邊；又將海放在殿門的右旁，就是南邊。","notes":[]},{"n":40,"t":"戶蘭又造了盆、鏟子，和盤子。這樣，他為所羅門王做完了耶和華殿的一切工。","notes":[],"heads":["聖殿設備清單"]},{"n":41,"t":"所造的就是：兩根柱子和柱上兩個如球的頂；並兩個蓋柱頂的網子；","notes":[]},{"n":42,"t":"和四百石榴，安在兩個網子上，每網兩行，蓋著兩個柱上如球的頂；","notes":[]},{"n":43,"t":"十個座和其上的十個盆；","notes":[]},{"n":44,"t":"海和海下的十二隻牛；","notes":[]},{"n":45,"t":"盆、鏟子、盤子。這一切都是戶蘭給所羅門王用光亮的銅為耶和華的殿造成的，","notes":[]},{"n":46,"t":"是遵王命在約旦平原、疏割和撒拉但中間藉膠泥鑄成的。","notes":[]},{"n":47,"t":"這一切所羅門都沒有過秤；因為甚多，銅的輕重也無法可查。","notes":[]},{"n":48,"t":"所羅門又造耶和華殿裏的金壇和陳設餅的金桌子；","notes":[]},{"n":49,"t":"內殿前的精金燈臺：右邊五個，左邊五個，並其上的金花、燈盞、蠟剪，","notes":[]},{"n":50,"t":"與精金的杯、盤、鑷子、調羹、火鼎，以及至聖所、內殿的門樞，和外殿的門樞。","notes":[]},{"n":51,"t":"所羅門王做完了耶和華殿的一切工，就把他父大衛分別為聖的金銀和器皿都帶來放在耶和華殿的府庫裏。","notes":[],"heads":["殿工告竣"]}]},"8":{"heading":"運約櫃入殿","verses":[{"n":1,"t":"那時，所羅門將以色列的長老和各支派的首領，並以色列的族長，招聚到耶路撒冷，要把耶和華的約櫃從大衛城－就是錫安－運上來。","notes":[]},{"n":2,"t":"以他念月，就是七月，在節前，以色列人都聚集到所羅門王那裏。","notes":[]},{"n":3,"t":"以色列長老來到，祭司便抬起約櫃，","notes":[]},{"n":4,"t":"祭司和利未人將耶和華的約櫃運上來，又將會幕和會幕的一切聖器具都帶上來。","notes":[]},{"n":5,"t":"所羅門王和聚集到他那裏的以色列全會眾，一同在約櫃前獻牛羊為祭，多得不可勝數。","notes":[]},{"n":6,"t":"祭司將耶和華的約櫃抬進內殿，就是至聖所，放在兩個基路伯的翅膀底下。","notes":[]},{"n":7,"t":"基路伯張著翅膀在約櫃之上，遮掩約櫃和抬櫃的槓。","notes":[]},{"n":8,"t":"這槓甚長，槓頭在內殿前的聖所可以看見，在殿外卻不能看見，直到如今還在那裏。","notes":[]},{"n":9,"t":"約櫃裏惟有兩塊石版，就是以色列人出埃及地後，耶和華與他們立約的時候摩西在何烈山所放的。除此以外，並無別物。","notes":[]},{"n":10,"t":"祭司從聖所出來的時候，有雲充滿耶和華的殿；","notes":[]},{"n":11,"t":"甚至祭司不能站立供職，因為耶和華的榮光充滿了殿。","notes":[]},{"n":12,"t":"那時所羅門說：耶和華曾說，他必住在幽暗之處。","notes":[]},{"n":13,"t":"我已經建造殿宇作你的居所，為你永遠的住處。","notes":[]},{"n":14,"t":"王轉臉為以色列會眾祝福，以色列會眾就都站立。","notes":[],"heads":["所羅門向百姓講話"]},{"n":15,"t":"所羅門說：「耶和華－以色列的神是應當稱頌的！因他親口向我父大衛所應許的，也親手成就了。","notes":[]},{"n":16,"t":"他說：『自從我領我民以色列出埃及以來，我未曾在以色列各支派中選擇一城建造殿宇－為我名的居所，但揀選大衛治理我民以色列。』」","notes":[]},{"n":17,"t":"所羅門說：「我父大衛曾立意，要為耶和華－以色列神的名建殿。","notes":[]},{"n":18,"t":"耶和華卻對我父大衛說：『你立意為我的名建殿，這意思甚好。","notes":[]},{"n":19,"t":"只是你不可建殿，惟你所生的兒子必為我名建殿。』","notes":[]},{"n":20,"t":"現在耶和華成就了他所應許的話，使我接續我父大衛坐以色列的國位，又為耶和華－以色列神的名建造了殿。","notes":[]},{"n":21,"t":"我也在其中為約櫃預備一處。約櫃內有耶和華的約，就是他領我們列祖出埃及地的時候，與他們所立的約。」","notes":[]},{"n":22,"t":"所羅門當著以色列會眾，站在耶和華的壇前，向天舉手說：","notes":[],"heads":["所羅門的禱告"]},{"n":23,"t":"「耶和華－以色列的神啊，天上地下沒有神可比你的！你向那盡心行在你面前的僕人守約施慈愛；","notes":[]},{"n":24,"t":"向你僕人－我父大衛所應許的話現在應驗了。你親口應許，親手成就，正如今日一樣。","notes":[]},{"n":25,"t":"耶和華－以色列的神啊，你所應許你僕人－我父大衛的話說：『你的子孫若謹慎自己的行為，在我面前行事像你所行的一樣，就不斷人坐以色列的國位。』現在求你應驗這話。","notes":[]},{"n":26,"t":"以色列的神啊，求你成就向你僕人－我父大衛所應許的話。","notes":[]},{"n":27,"t":"「神果真住在地上嗎？看哪，天和天上的天尚且不足你居住的，何況我所建的這殿呢？","notes":[]},{"n":28,"t":"惟求耶和華－我的神垂顧僕人的禱告祈求，俯聽僕人今日在你面前的祈禱呼籲。","notes":[]},{"n":29,"t":"願你晝夜看顧這殿，就是你應許立為你名的居所；求你垂聽僕人向此處禱告的話。","notes":[]},{"n":30,"t":"你僕人和你民以色列向此處祈禱的時候，求你在天上你的居所垂聽，垂聽而赦免。","notes":[]},{"n":31,"t":"「人若得罪鄰舍，有人叫他起誓，他來到這殿在你的壇前起誓，","notes":[]},{"n":32,"t":"求你在天上垂聽，判斷你的僕人：定惡人有罪，照他所行的報應在他頭上；定義人有理，照他的義賞賜他。","notes":[]},{"n":33,"t":"「你的民以色列若得罪你，敗在仇敵面前，又歸向你，承認你的名，在這殿裏祈求禱告，","notes":[]},{"n":34,"t":"求你在天上垂聽，赦免你民以色列的罪，使他們歸回你賜給他們列祖之地。","notes":[]},{"n":35,"t":"「你的民因得罪你，你懲罰他們，使天閉塞不下雨；他們若向此處禱告，承認你的名，離開他們的罪，","notes":[]},{"n":36,"t":"求你在天上垂聽，赦免你僕人以色列民的罪，將當行的善道指教他們，且降雨在你的地，就是你賜給你民為業之地。","notes":[]},{"n":37,"t":"「國中若有饑荒、瘟疫、旱風、霉爛、蝗蟲、螞蚱，或有仇敵犯境圍困城邑，無論遭遇甚麼災禍疾病，","notes":[]},{"n":38,"t":"你的民以色列，或是眾人，或是一人，自覺有罪，向這殿舉手，無論祈求甚麼，禱告甚麼，","notes":["原文是災"]},{"n":39,"t":"求你在天上你的居所垂聽赦免。你是知道人心的，要照各人所行的待他們（惟有你知道世人的心），","notes":[]},{"n":40,"t":"使他們在你賜給我們列祖之地上一生一世敬畏你。","notes":[]},{"n":41,"t":"「論到不屬你民以色列的外邦人，為你名從遠方而來，","notes":[]},{"n":42,"t":"（他們聽人論說你的大名和大能的手，並伸出來的膀臂）向這殿禱告，","notes":[]},{"n":43,"t":"求你在天上你的居所垂聽，照著外邦人所祈求的而行，使天下萬民都認識你的名，敬畏你像你的民以色列一樣；又使他們知道我建造的這殿是稱為你名下的。","notes":[]},{"n":44,"t":"「你的民若奉你的差遣，無論往何處去與仇敵爭戰，向耶和華所選擇的城與我為你名所建造的殿禱告，","notes":[]},{"n":45,"t":"求你在天上垂聽他們的禱告祈求，使他們得勝。","notes":[]},{"n":46,"t":"「你的民若得罪你（世上沒有不犯罪的人），你向他們發怒，將他們交給仇敵擄到仇敵之地，或遠或近，","notes":[]},{"n":47,"t":"他們若在擄到之地想起罪來，回心轉意，懇求你說：『我們有罪了，我們悖逆了，我們作惡了』；","notes":[]},{"n":48,"t":"他們若在擄到之地盡心盡性歸服你，又向自己的地，就是你賜給他們列祖之地和你所選擇的城，並我為你名所建造的殿禱告，","notes":[]},{"n":49,"t":"求你在天上你的居所垂聽他們的禱告祈求，為他們伸冤；","notes":[]},{"n":50,"t":"饒恕得罪你的民，赦免他們的一切過犯，使他們在擄他們的人面前蒙憐恤。","notes":[]},{"n":51,"t":"因為他們是你的子民，你的產業，是你從埃及領出來脫離鐵爐的。","notes":[]},{"n":52,"t":"願你的眼目看顧僕人，聽你民以色列的祈求，無論何時向你祈求，願你垂聽。","notes":[]},{"n":53,"t":"主耶和華啊，你將他們從地上的萬民中分別出來作你的產業，是照你領我們列祖出埃及的時候，藉你僕人摩西所應許的話。」","notes":[]},{"n":54,"t":"所羅門在耶和華的壇前屈膝跪著，向天舉手，在耶和華面前禱告祈求已畢，就起來，","notes":[],"heads":["為民祝福"]},{"n":55,"t":"站著，大聲為以色列全會眾祝福，說：","notes":[]},{"n":56,"t":"「耶和華是應當稱頌的！因為他照著一切所應許的賜平安給他的民以色列人，凡藉他僕人摩西應許賜福的話，一句都沒有落空。","notes":[]},{"n":57,"t":"願耶和華－我們的神與我們同在，像與我們列祖同在一樣，不撇下我們，不丟棄我們，","notes":[]},{"n":58,"t":"使我們的心歸向他，遵行他的道，謹守他吩咐我們列祖的誡命、律例、典章。","notes":[]},{"n":59,"t":"我在耶和華面前祈求的這些話，願耶和華－我們的神晝夜垂念，每日為他僕人與他民以色列伸冤，","notes":[]},{"n":60,"t":"使地上的萬民都知道惟獨耶和華是神，並無別神。","notes":[]},{"n":61,"t":"所以你們當向耶和華－我們的神存誠實的心，遵行他的律例，謹守他的誡命，至終如今日一樣。」","notes":[]},{"n":62,"t":"王和以色列眾民一同在耶和華面前獻祭。","notes":[],"heads":["奉獻聖殿"]},{"n":63,"t":"所羅門向耶和華獻平安祭，用牛二萬二千，羊十二萬。這樣，王和以色列眾民為耶和華的殿行奉獻之禮。","notes":[]},{"n":64,"t":"當日，王因耶和華殿前的銅壇太小，容不下燔祭、素祭，和平安祭牲的脂油，便將耶和華殿前院子當中分別為聖，在那裏獻燔祭、素祭，和平安祭牲的脂油。","notes":[]},{"n":65,"t":"那時，所羅門和以色列眾人，就是從哈馬口直到埃及小河所有的以色列人，都聚集成為大會，在耶和華－我們的神面前守節七日又七日，共十四日。","notes":[]},{"n":66,"t":"第八日，王遣散眾民；他們都為王祝福。因見耶和華向他僕人大衛和他民以色列所施的一切恩惠，就都心中喜樂，各歸各家去了。","notes":[]}]},"9":{"heading":"耶和華再向所羅門顯現","verses":[{"n":1,"t":"所羅門建造耶和華殿和王宮，並一切所願意建造的都完畢了，","notes":[]},{"n":2,"t":"耶和華就二次向所羅門顯現，如先前在基遍向他顯現一樣，","notes":[]},{"n":3,"t":"對他說：「你向我所禱告祈求的，我都應允了。我已將你所建的這殿分別為聖，使我的名永遠在其中；我的眼、我的心也必常在那裏。","notes":[]},{"n":4,"t":"你若效法你父大衛，存誠實正直的心行在我面前，遵行我一切所吩咐你的，謹守我的律例典章，","notes":[]},{"n":5,"t":"我就必堅固你的國位在以色列中，直到永遠，正如我應許你父大衛說：『你的子孫必不斷人坐以色列的國位。』","notes":[]},{"n":6,"t":"倘若你們和你們的子孫轉去不跟從我，不守我指示你們的誡命律例，去事奉敬拜別神，","notes":[]},{"n":7,"t":"我就必將以色列人從我賜給他們的地上剪除，並且我為己名所分別為聖的殿也必捨棄不顧，使以色列人在萬民中作笑談，被譏誚。","notes":[]},{"n":8,"t":"這殿雖然甚高，將來經過的人必驚訝、嗤笑，說：『耶和華為何向這地和這殿如此行呢？』","notes":[]},{"n":9,"t":"人必回答說：『是因此地的人離棄領他們列祖出埃及地之耶和華－他們的神，去親近別神，事奉敬拜他，所以耶和華使這一切災禍臨到他們。』」","notes":[]},{"n":10,"t":"所羅門建造耶和華殿和王宮，這兩所二十年才完畢了。","notes":[],"heads":["所羅門跟希蘭訂約"]},{"n":11,"t":"泰爾王希蘭曾照所羅門所要的，資助他香柏木、松木，和金子；所羅門王就把加利利地的二十座城給了希蘭。","notes":[]},{"n":12,"t":"希蘭從泰爾出來，察看所羅門給他的城邑，就不喜悅，","notes":[]},{"n":13,"t":"說：「我兄啊，你給我的是甚麼城邑呢？」他就給這城邑之地起名叫迦步勒，直到今日。","notes":[]},{"n":14,"t":"希蘭給所羅門一百二十他連得金子。","notes":[]},{"n":15,"t":"所羅門王挑取服苦的人，是為建造耶和華的殿、自己的宮、米羅、耶路撒冷的城牆、夏瑣、米吉多，並基色。","notes":[],"heads":["所羅門其他政績"]},{"n":16,"t":"先前埃及王法老上來攻取基色，用火焚燒，殺了城內居住的迦南人，將城賜給他女兒所羅門的妻作妝奩。","notes":[]},{"n":17,"t":"所羅門建造基色、下伯‧和崙、","notes":[]},{"n":18,"t":"巴拉，並國中曠野裏的達莫，","notes":[]},{"n":19,"t":"又建造所有的積貨城，並屯車和馬兵的城，與耶路撒冷、黎巴嫩，以及自己治理的全國中所願建造的。","notes":[]},{"n":20,"t":"至於國中所剩下不屬以色列人的亞摩利人、赫人、比利洗人、希未人、耶布斯人，","notes":[]},{"n":21,"t":"就是以色列人不能滅盡的，所羅門挑取他們的後裔作服苦的奴僕，直到今日。","notes":[]},{"n":22,"t":"惟有以色列人，所羅門不使他們作奴僕，乃是作他的戰士、臣僕、統領、軍長、車兵長、馬兵長。","notes":[]},{"n":23,"t":"所羅門有五百五十督工的，監管工人。","notes":[]},{"n":24,"t":"法老的女兒從大衛城搬到所羅門為她建造的宮裏。那時，所羅門才建造米羅。","notes":[]},{"n":25,"t":"所羅門每年三次在他為耶和華所築的壇上獻燔祭和平安祭，又在耶和華面前的壇上燒香。這樣，他建造殿的工程完畢了。","notes":[]},{"n":26,"t":"所羅門王在以東地紅海邊，靠近以祿的以旬‧迦別製造船隻。","notes":[]},{"n":27,"t":"希蘭差遣他的僕人，就是熟悉泛海的船家，與所羅門的僕人一同坐船航海。","notes":[]},{"n":28,"t":"他們到了俄斐，從那裏得了四百二十他連得金子，運到所羅門王那裏。","notes":[]}]},"10":{"heading":"示巴女王拜訪所羅門","verses":[{"n":1,"t":"示巴女王聽見所羅門因耶和華之名所得的名聲，就來要用難解的話試問所羅門。","notes":[]},{"n":2,"t":"跟隨她到耶路撒冷的人甚多，又有駱駝馱著香料、寶石，和許多金子。她來見了所羅門王，就把心裏所有的對所羅門都說出來。","notes":[]},{"n":3,"t":"所羅門王將她所問的都答上了，沒有一句不明白、不能答的。","notes":[]},{"n":4,"t":"示巴女王見所羅門大有智慧，和他所建造的宮室，","notes":[]},{"n":5,"t":"席上的珍饈美味，群臣分列而坐，僕人兩旁侍立，以及他們的衣服裝飾和酒政的衣服裝飾，又見他上耶和華殿的臺階，就詫異得神不守舍；","notes":["或譯：他在耶和華殿裏所獻的燔祭"]},{"n":6,"t":"對王說：「我在本國裏所聽見論到你的事和你的智慧實在是真的！","notes":[]},{"n":7,"t":"我先不信那些話，及至我來親眼見了才知道人所告訴我的還不到一半。你的智慧和你的福分越過我所聽見的風聲。","notes":[]},{"n":8,"t":"你的臣子、你的僕人常侍立在你面前聽你智慧的話是有福的！","notes":[]},{"n":9,"t":"耶和華－你的神是應當稱頌的！他喜悅你，使你坐以色列的國位；因為他永遠愛以色列，所以立你作王，使你秉公行義。」","notes":[]},{"n":10,"t":"於是，示巴女王將一百二十他連得金子和寶石，與極多的香料，送給所羅門王。她送給王的香料，以後奉來的不再有這樣多。（","notes":[]},{"n":11,"t":"希蘭的船隻從俄斐運了金子來，又從俄斐運了許多檀香木和寶石來。","notes":["或譯：烏木；下同"]},{"n":12,"t":"王用檀香木為耶和華殿和王宮做欄杆，又為歌唱的人做琴瑟。以後再沒有這樣的檀香木進國來，也沒有人看見過，直到如今。）","notes":[]},{"n":13,"t":"示巴女王一切所要所求的，所羅門王都送給她，另外照自己的厚意餽送她。於是女王和她臣僕轉回本國去了。","notes":[]},{"n":14,"t":"所羅門每年所得的金子共有六百六十六他連得。","notes":[],"heads":["所羅門的財富"]},{"n":15,"t":"另外還有商人和雜族的諸王，與國中的省長所進的金子。","notes":["雜族在歷代下九章十四節是阿拉伯"]},{"n":16,"t":"所羅門王用錘出來的金子打成擋牌二百面，每面用金子六百舍客勒；","notes":[]},{"n":17,"t":"又用錘出來的金子打成盾牌三百面，每面用金子三彌那，都放在黎巴嫩林宮裏。","notes":[]},{"n":18,"t":"王用象牙製造一個寶座，用精金包裹。","notes":[]},{"n":19,"t":"寶座有六層臺階，座的後背是圓的，兩旁有扶手，靠近扶手有兩個獅子站立。","notes":[]},{"n":20,"t":"六層臺階上有十二個獅子站立，每層有兩個：左邊一個，右邊一個；在列國中沒有這樣做的。","notes":[]},{"n":21,"t":"所羅門王一切的飲器都是金子的。黎巴嫩林宮裏的一切器皿都是精金的。所羅門年間，銀子算不了甚麼。","notes":[]},{"n":22,"t":"因為王有他施船隻與希蘭的船隻一同航海，三年一次，裝載金銀、象牙、猿猴、孔雀回來。","notes":[]},{"n":23,"t":"所羅門王的財寶與智慧勝過天下的列王。","notes":[]},{"n":24,"t":"普天下的王都求見所羅門，要聽神賜給他智慧的話。","notes":[]},{"n":25,"t":"他們各帶貢物，就是金器、銀器、衣服、軍械、香料、騾馬，每年有一定之例。","notes":[]},{"n":26,"t":"所羅門聚集戰車馬兵，有戰車一千四百輛，馬兵一萬二千名，安置在屯車的城邑和耶路撒冷，就是王那裏。","notes":[],"heads":["所羅門的車騎"]},{"n":27,"t":"王在耶路撒冷使銀子多如石頭，香柏木多如高原的桑樹。","notes":[]},{"n":28,"t":"所羅門的馬是從埃及帶來的，是王的商人一群一群按著定價買來的。","notes":[]},{"n":29,"t":"從埃及買來的車，每輛價銀六百舍客勒，馬每匹一百五十舍客勒。赫人諸王和亞蘭諸王所買的車馬，也是按這價值經他們手買來的。","notes":[]}]},"11":{"heading":"所羅門離棄神","verses":[{"n":1,"t":"所羅門王在法老的女兒之外，又寵愛許多外邦女子，就是摩押女子、亞捫女子、以東女子、西頓女子、赫人女子。","notes":[]},{"n":2,"t":"論到這些國的人，耶和華曾曉諭以色列人說：「你們不可與她們往來相通，因為她們必誘惑你們的心去隨從她們的神。」所羅門卻戀愛這些女子。","notes":[]},{"n":3,"t":"所羅門有妃七百，都是公主；還有嬪三百。這些妃嬪誘惑他的心。","notes":[]},{"n":4,"t":"所羅門年老的時候，他的妃嬪誘惑他的心去隨從別神，不效法他父親大衛誠誠實實地順服耶和華－他的神。","notes":[]},{"n":5,"t":"因為所羅門隨從西頓人的女神亞斯她錄和亞捫人可憎的神米勒公。","notes":[]},{"n":6,"t":"所羅門行耶和華眼中看為惡的事，不效法他父親大衛專心順從耶和華。","notes":[]},{"n":7,"t":"所羅門為摩押可憎的神基抹和亞捫人可憎的神摩洛，在耶路撒冷對面的山上建築邱壇。","notes":[]},{"n":8,"t":"他為那些向自己的神燒香獻祭的外邦女子，就是他娶來的妃嬪也是這樣行。","notes":[]},{"n":9,"t":"耶和華向所羅門發怒，因為他的心偏離向他兩次顯現的耶和華－以色列的神。","notes":[]},{"n":10,"t":"耶和華曾吩咐他不可隨從別神，他卻沒有遵守耶和華所吩咐的。","notes":[]},{"n":11,"t":"所以耶和華對他說：「你既行了這事，不遵守我所吩咐你守的約和律例，我必將你的國奪回，賜給你的臣子。","notes":[]},{"n":12,"t":"然而，因你父親大衛的緣故，我不在你活著的日子行這事，必從你兒子的手中將國奪回。","notes":[]},{"n":13,"t":"只是我不將全國奪回，要因我僕人大衛和我所選擇的耶路撒冷，還留一支派給你的兒子。」","notes":[]},{"n":14,"t":"耶和華使以東人哈達興起，作所羅門的敵人；他是以東王的後裔。","notes":[],"heads":["所羅門的敵人"]},{"n":15,"t":"先前大衛攻擊以東，元帥約押上去葬埋陣亡的人，將以東的男丁都殺了。","notes":[]},{"n":16,"t":"約押和以色列眾人在以東住了六個月，直到將以東的男丁盡都剪除。","notes":[]},{"n":17,"t":"那時哈達還是幼童；他和他父親的臣僕，幾個以東人逃往埃及。","notes":[]},{"n":18,"t":"他們從米甸起行，到了巴蘭；從巴蘭帶著幾個人來到埃及見埃及王法老；法老為他派定糧食，又給他房屋田地。","notes":[]},{"n":19,"t":"哈達在法老面前大蒙恩惠，以致法老將王后答比匿的妹子賜他為妻。","notes":[]},{"n":20,"t":"答比匿的妹子給哈達生了一個兒子，名叫基努拔。答比匿使基努拔在法老的宮裏斷奶，基努拔就與法老的眾子一同住在法老的宮裏。","notes":[]},{"n":21,"t":"哈達在埃及聽見大衛與他列祖同睡，元帥約押也死了，就對法老說：「求王容我回本國去。」","notes":[]},{"n":22,"t":"法老對他說：「你在我這裏有甚麼缺乏，你竟要回你本國去呢？」他回答說：「我沒有缺乏甚麼，只是求王容我回去。」","notes":[]},{"n":23,"t":"神又使以利亞大的兒子利遜興起，作所羅門的敵人。他先前逃避主人瑣巴王哈大底謝。","notes":[]},{"n":24,"t":"大衛擊殺 瑣巴人的時候，利遜招聚了一群人，自己作他們的頭目，往大馬士革居住，在那裏作王。","notes":[]},{"n":25,"t":"所羅門活著的時候，哈達為患之外，利遜也作以色列的敵人。他恨惡以色列人，且作了亞蘭人的王。","notes":[]},{"n":26,"t":"所羅門的臣僕、尼八的兒子耶羅波安也舉手攻擊王。他是以法蓮支派的洗利達人，他母親是寡婦，名叫洗魯阿。","notes":[],"heads":["神給耶羅波安的應許"]},{"n":27,"t":"他舉手攻擊王的緣故，乃由先前所羅門建造米羅，修補他父親大衛城的破口。","notes":[]},{"n":28,"t":"耶羅波安是大有才能的人。所羅門見這少年人殷勤，就派他監管約瑟家的一切工程。","notes":[]},{"n":29,"t":"一日，耶羅波安出了耶路撒冷，示羅人先知亞希雅在路上遇見他；亞希雅身上穿著一件新衣。他們二人在田野，以外並無別人。","notes":[]},{"n":30,"t":"亞希雅將自己穿的那件新衣撕成十二片，","notes":[]},{"n":31,"t":"對耶羅波安說：「你可以拿十片。耶和華－以色列的神如此說：『我必將國從所羅門手裏奪回，將十個支派賜給你。（","notes":[]},{"n":32,"t":"我因僕人大衛和我在以色列眾支派中所選擇的耶路撒冷城的緣故，仍給所羅門留一個支派。）","notes":[]},{"n":33,"t":"因為他離棄我，敬拜西頓人的女神亞斯她錄、摩押的神基抹，和亞捫人的神米勒公，沒有遵從我的道，行我眼中看為正的事，守我的律例典章，像他父親大衛一樣。","notes":[]},{"n":34,"t":"但我不從他手裏將全國奪回；使他終身為君，是因我所揀選的僕人大衛謹守我的誡命律例。","notes":[]},{"n":35,"t":"我必從他兒子的手裏將國奪回，以十個支派賜給你，","notes":[]},{"n":36,"t":"還留一個支派給他的兒子，使我僕人大衛在我所選擇立我名的耶路撒冷城裏，在我面前長有燈光。","notes":[]},{"n":37,"t":"我必揀選你，使你照心裏一切所願的，作王治理以色列。","notes":[]},{"n":38,"t":"你若聽從我一切所吩咐你的，遵行我的道，行我眼中看為正的事，謹守我的律例誡命，像我僕人大衛所行的，我就與你同在，為你立堅固的家，像我為大衛所立的一樣，將以色列人賜給你。","notes":[]},{"n":39,"t":"我必因所羅門所行的使大衛後裔受患難，但不至於永遠。』」","notes":[]},{"n":40,"t":"所羅門因此想要殺耶羅波安。耶羅波安卻起身逃往埃及；到了埃及王示撒那裏，就住在埃及，直到所羅門死了。","notes":[]},{"n":41,"t":"所羅門其餘的事，凡他所行的和他的智慧都寫在所羅門記上。","notes":[],"heads":["所羅門去世"]},{"n":42,"t":"所羅門在耶路撒冷作以色列眾人的王共四十年。","notes":[]},{"n":43,"t":"所羅門與他列祖同睡，葬在他父親大衛的城裏。他兒子羅波安接續他作王。","notes":[]}]},"12":{"heading":"北方的支派反叛","verses":[{"n":1,"t":"羅波安往示劍去；因為以色列人都到了示劍要立他作王。","notes":[]},{"n":2,"t":"尼八的兒子耶羅波安先前躲避所羅門王，逃往埃及，住在那裏（他聽見這事。）","notes":[]},{"n":3,"t":"以色列人打發人去請他來，他就和以色列會眾都來見羅波安，對他說：","notes":[]},{"n":4,"t":"「你父親使我們負重軛，做苦工，現在求你使我們做的苦工、負的重軛輕鬆些，我們就事奉你。」","notes":[]},{"n":5,"t":"羅波安對他們說：「你們暫且去，第三日再來見我。」民就去了。","notes":[]},{"n":6,"t":"羅波安之父所羅門在世的日子，有侍立在他面前的老年人，羅波安王和他們商議，說：「你們給我出個甚麼主意，我好回覆這民。」","notes":[]},{"n":7,"t":"老年人對他說：「現在王若服事這民如僕人，用好話回答他們，他們就永遠作王的僕人。」","notes":[]},{"n":8,"t":"王卻不用老年人給他出的主意，就和那些與他一同長大、在他面前侍立的少年人商議，","notes":[]},{"n":9,"t":"說：「這民對我說：『你父親使我們負重軛，求你使我們輕鬆些。』你們給我出個甚麼主意，我好回覆他們。」","notes":[]},{"n":10,"t":"那同他長大的少年人說：「這民對王說：『你父親使我們負重軛，求你使我們輕鬆些。』王要對他們如此說：『我的小拇指頭比我父親的腰還粗。","notes":[]},{"n":11,"t":"我父親使你們負重軛，我必使你們負更重的軛！我父親用鞭子責打你們，我要用蠍子鞭責打你們！』」","notes":[]},{"n":12,"t":"耶羅波安和眾百姓遵著羅波安王所說「你們第三日再來見我」的那話，第三日他們果然來了。","notes":[]},{"n":13,"t":"王用嚴厲的話回答百姓，不用老年人給他所出的主意，","notes":[]},{"n":14,"t":"照著少年人所出的主意對民說：「我父親使你們負重軛，我必使你們負更重的軛！我父親用鞭子責打你們，我要用蠍子鞭責打你們！」","notes":[]},{"n":15,"t":"王不肯依從百姓，這事乃出於耶和華，為要應驗他藉示羅人亞希雅對尼八的兒子耶羅波安所說的話。","notes":[]},{"n":16,"t":"以色列眾民見王不依從他們，就對王說：我們與大衛有甚麼分兒呢？與耶西的兒子並沒有關涉。以色列人哪，各回各家去吧！大衛家啊，自己顧自己吧！於是，以色列人都回自己家裏去了，","notes":[]},{"n":17,"t":"惟獨住猶大城邑的以色列人，羅波安仍作他們的王。","notes":[]},{"n":18,"t":"羅波安王差遣掌管服苦之人的亞多蘭往以色列人那裏去，以色列人就用石頭打死他。羅波安王急忙上車，逃回耶路撒冷去了。","notes":[]},{"n":19,"t":"這樣，以色列人背叛大衛家，直到今日。","notes":[]},{"n":20,"t":"以色列眾人聽見耶羅波安回來了，就打發人去請他到會眾面前，立他作以色列眾人的王。除了猶大支派以外，沒有順從大衛家的。","notes":[]},{"n":21,"t":"羅波安來到耶路撒冷，招聚猶大全家和便雅憫支派的人共十八萬，都是挑選的戰士，要與以色列家爭戰，好將國奪回，再歸所羅門的兒子羅波安。","notes":[],"heads":["示瑪雅的預言"]},{"n":22,"t":"但神的話臨到神人示瑪雅，說：","notes":[]},{"n":23,"t":"「你去告訴所羅門的兒子猶大王羅波安和猶大、便雅憫全家，並其餘的民說：","notes":[]},{"n":24,"t":"『耶和華如此說：你們不可上去與你們的弟兄以色列人爭戰。各歸各家去吧！因為這事出於我。』」眾人就聽從耶和華的話，遵著耶和華的命回去了。","notes":[]},{"n":25,"t":"耶羅波安在以法蓮山地建築示劍，就住在其中；又從示劍出去，建築毗努伊勒。","notes":[],"heads":["耶羅波安離棄神"]},{"n":26,"t":"耶羅波安心裏說：「恐怕這國仍歸大衛家；","notes":[]},{"n":27,"t":"這民若上耶路撒冷去，在耶和華的殿裏獻祭，他們的心必歸向他們的主－猶大王羅波安，就把我殺了，仍歸猶大王羅波安。」","notes":[]},{"n":28,"t":"耶羅波安王就籌劃定妥，鑄造了兩個金牛犢，對眾民說：「以色列人哪，你們上耶路撒冷去實在是難；這就是領你們出埃及地的神。」","notes":[]},{"n":29,"t":"他就把牛犢一隻安在伯特利，一隻安在但。","notes":[]},{"n":30,"t":"這事叫百姓陷在罪裏，因為他們往但去拜那牛犢。","notes":[]},{"n":31,"t":"耶羅波安在邱壇那裏建殿，將那不屬利未人的凡民立為祭司。","notes":[]},{"n":32,"t":"耶羅波安定八月十五日為節期，像在猶大的節期一樣，自己上壇獻祭。他在伯特利也這樣向他所鑄的牛犢獻祭，又將立為邱壇的祭司安置在伯特利。","notes":[],"heads":["在伯特利拜牛犢被定罪"]},{"n":33,"t":"他在八月十五日，就是他私自所定的月日，為以色列人立作節期的日子，在伯特利上壇燒香。","notes":[]}]},"13":{"heading":"伯特利的老先知","verses":[{"n":1,"t":"那時，有一個神人奉耶和華的命從猶大來到伯特利。耶羅波安正站在壇旁要燒香；","notes":[]},{"n":2,"t":"神人奉耶和華的命向壇呼叫，說：「壇哪，壇哪！耶和華如此說：大衛家裏必生一個兒子，名叫約西亞，他必將邱壇的祭司，就是在你上面燒香的，殺在你上面，人的骨頭也必燒在你上面。」","notes":[]},{"n":3,"t":"當日，神人設個預兆，說：「這壇必破裂，壇上的灰必傾撒，這是耶和華說的預兆。」","notes":[]},{"n":4,"t":"耶羅波安王聽見神人向伯特利的壇所呼叫的話，就從壇上伸手，說：「拿住他吧！」王向神人所伸的手就枯乾了，不能彎回；","notes":[]},{"n":5,"t":"壇也破裂了，壇上的灰傾撒了，正如神人奉耶和華的命所設的預兆。","notes":[]},{"n":6,"t":"王對神人說：「請你為我禱告，求耶和華－你神的恩典使我的手復原。」於是神人祈禱耶和華，王的手就復了原，仍如尋常一樣。","notes":[]},{"n":7,"t":"王對神人說：「請你同我回去吃飯，加添心力，我也必給你賞賜。」","notes":[]},{"n":8,"t":"神人對王說：「你就是把你的宮一半給我，我也不同你進去，也不在這地方吃飯喝水；","notes":[]},{"n":9,"t":"因為有耶和華的話囑咐我，說不可在伯特利吃飯喝水，也不可從你去的原路回來。」","notes":[]},{"n":10,"t":"於是神人從別的路回去，不從伯特利來的原路回去。","notes":[]},{"n":11,"t":"有一個老先知住在伯特利，他兒子們來，將神人當日在伯特利所行的一切事和向王所說的話都告訴了父親。","notes":[]},{"n":12,"t":"父親問他們說：「神人從哪條路去了呢？」兒子們就告訴他；原來他們看見那從猶大來的神人所去的路。","notes":[]},{"n":13,"t":"老先知就吩咐他兒子們說：「你們為我備驢。」他們備好了驢，他就騎上，","notes":[]},{"n":14,"t":"去追趕神人，遇見他坐在橡樹底下，就問他說：「你是從猶大來的神人不是？」他說：「是。」","notes":[]},{"n":15,"t":"老先知對他說：「請你同我回家吃飯。」","notes":[]},{"n":16,"t":"神人說：「我不可同你回去進你的家，也不可在這裏同你吃飯喝水；","notes":[]},{"n":17,"t":"因為有耶和華的話囑咐我說：『你在那裏不可吃飯喝水，也不可從你去的原路回來。』」","notes":[]},{"n":18,"t":"老先知對他說：「我也是先知，和你一樣。有天使奉耶和華的命對我說：『你去把他帶回你的家，叫他吃飯喝水。』」這都是老先知誆哄他。","notes":[]},{"n":19,"t":"於是神人同老先知回去，在他家裏吃飯喝水。","notes":[]},{"n":20,"t":"二人坐席的時候，耶和華的話臨到那帶神人回來的先知，","notes":[]},{"n":21,"t":"他就對那從猶大來的神人說：「耶和華如此說：你既違背耶和華的話，不遵守耶和華－你神的命令，","notes":[]},{"n":22,"t":"反倒回來，在耶和華禁止你吃飯喝水的地方吃了喝了，因此你的屍身不得入你列祖的墳墓。」","notes":[]},{"n":23,"t":"吃喝完了，老先知為所帶回來的先知備驢。","notes":[]},{"n":24,"t":"他就去了，在路上有個獅子遇見他，將他咬死，屍身倒在路上，驢站在屍身旁邊，獅子也站在屍身旁邊。","notes":[]},{"n":25,"t":"有人從那裏經過，看見屍身倒在路上，獅子站在屍身旁邊，就來到老先知所住的城裏述說這事。","notes":[]},{"n":26,"t":"那帶神人回來的先知聽見這事，就說：「這是那違背了耶和華命令的神人，所以耶和華把他交給獅子；獅子抓傷他，咬死他，是應驗耶和華對他說的話。」","notes":[]},{"n":27,"t":"老先知就吩咐他兒子們說：「你們為我備驢。」他們就備了驢。","notes":[]},{"n":28,"t":"他去了，看見神人的屍身倒在路上，驢和獅子站在屍身旁邊，獅子卻沒有吃屍身，也沒有抓傷驢。","notes":[]},{"n":29,"t":"老先知就把神人的屍身馱在驢上，帶回自己的城裏，要哀哭他，葬埋他；","notes":[]},{"n":30,"t":"就把他的屍身葬在自己的墳墓裏，哀哭他，說：「哀哉！我兄啊。」","notes":[]},{"n":31,"t":"安葬之後，老先知對他兒子們說：「我死了，你們要葬我在神人的墳墓裏，使我的屍骨靠近他的屍骨，","notes":[]},{"n":32,"t":"因為他奉耶和華的命指著伯特利的壇和撒馬利亞各城有邱壇之殿所說的話必定應驗。」","notes":[]},{"n":33,"t":"這事以後，耶羅波安仍不離開他的惡道，將凡民立為邱壇的祭司；凡願意的，他都分別為聖，立為邱壇的祭司。","notes":[],"heads":["耶羅波安的嚴重罪行"]},{"n":34,"t":"這事叫耶羅波安的家陷在罪裏，甚至他的家從地上除滅了。","notes":[]}]},"14":{"heading":"耶羅波安的兒子去世","verses":[{"n":1,"t":"那時，耶羅波安的兒子亞比雅病了。","notes":[]},{"n":2,"t":"耶羅波安對他的妻說：「你可以起來改裝，使人不知道你是耶羅波安的妻，往示羅去，在那裏有先知亞希雅。他曾告訴我說，你必作這民的王。","notes":[]},{"n":3,"t":"現在你要帶十個餅，與幾個薄餅，和一瓶蜜去見他，他必告訴你兒子將要怎樣。」","notes":[]},{"n":4,"t":"耶羅波安的妻就這樣行，起身往示羅去，到了亞希雅的家。亞希雅因年紀老邁，眼目發直，不能看見。","notes":[]},{"n":5,"t":"耶和華先曉諭亞希雅說：「耶羅波安的妻要來問你，因她兒子病了，你當如此如此告訴她。她進來的時候必裝作別的婦人。」","notes":[]},{"n":6,"t":"她剛進門，亞希雅聽見她腳步的響聲，就說：「耶羅波安的妻，進來吧！你為何裝作別的婦人呢？我奉差遣將凶事告訴你。","notes":[]},{"n":7,"t":"你回去告訴耶羅波安說：『耶和華－以色列的神如此說：我從民中將你高舉，立你作我民以色列的君，","notes":[]},{"n":8,"t":"將國從大衛家奪回賜給你；你卻不效法我僕人大衛，遵守我的誡命，一心順從我，行我眼中看為正的事。","notes":[]},{"n":9,"t":"你竟行惡，比那在你以先的更甚，為自己立了別神，鑄了偶像，惹我發怒，將我丟在背後。","notes":[]},{"n":10,"t":"因此，我必使災禍臨到耶羅波安的家，將屬耶羅波安的男丁，無論困住的、自由的都從以色列中剪除，必除盡耶羅波安的家，如人除盡糞土一般。","notes":[]},{"n":11,"t":"凡屬耶羅波安的人，死在城中的必被狗吃，死在田野的必被空中的鳥吃。這是耶和華說的。』","notes":[]},{"n":12,"t":"所以你起身回家去吧！你的腳一進城，你兒子就必死了。","notes":[]},{"n":13,"t":"以色列眾人必為他哀哭，將他葬埋。凡屬耶羅波安的人，惟有他得入墳墓；因為在耶羅波安的家中，只有他向耶和華－以色列的神顯出善行。","notes":[]},{"n":14,"t":"耶和華必另立一王治理以色列。到了日期，他必剪除耶羅波安的家；那日期已經到了。","notes":[]},{"n":15,"t":"耶和華必擊打以色列人，使他們搖動，像水中的蘆葦一般；又將他們從耶和華賜給他們列祖的美地上拔出來，分散在大河那邊；因為他們做木偶，惹耶和華發怒。","notes":[]},{"n":16,"t":"因耶羅波安所犯的罪，又使以色列人陷在罪裏，耶和華必將以色列人交給仇敵。」","notes":[]},{"n":17,"t":"耶羅波安的妻起身回去，到了得撒，剛到門檻，兒子就死了。","notes":[]},{"n":18,"t":"以色列眾人將他葬埋，為他哀哭，正如耶和華藉他僕人先知亞希雅所說的話。","notes":[]},{"n":19,"t":"耶羅波安其餘的事，他怎樣爭戰，怎樣作王，都寫在以色列諸王記上。","notes":[],"heads":["耶羅波安去世"]},{"n":20,"t":"耶羅波安作王二十二年，就與他列祖同睡。他兒子拿答接續他作王。","notes":[]},{"n":21,"t":"所羅門的兒子羅波安作猶大王。他登基的時候年四十一歲，在耶路撒冷，就是耶和華從以色列眾支派中所選擇立他名的城，作王十七年。羅波安的母親名叫拿瑪，是亞捫人。","notes":[],"heads":["猶大王羅波安"]},{"n":22,"t":"猶大人行耶和華眼中看為惡的事，犯罪觸動他的憤恨，比他們列祖更甚。","notes":[]},{"n":23,"t":"因為他們在各高岡上，各青翠樹下築壇，立柱像和木偶。","notes":[]},{"n":24,"t":"國中也有孌童。猶大人效法耶和華在以色列人面前所趕出的外邦人，行一切可憎惡的事。","notes":[]},{"n":25,"t":"羅波安王第五年，埃及王示撒上來攻取耶路撒冷，","notes":[]},{"n":26,"t":"奪了耶和華殿和王宮裏的寶物，盡都帶走，又奪去所羅門製造的金盾牌。","notes":[]},{"n":27,"t":"羅波安王製造銅盾牌代替那金盾牌，交給守王宮門的護衛長看守。","notes":[]},{"n":28,"t":"王每逢進耶和華的殿，護衛兵就拿這盾牌，隨後仍將盾牌送回，放在護衛房。","notes":[]},{"n":29,"t":"羅波安其餘的事，凡他所行的，都寫在猶大列王記上。","notes":[]},{"n":30,"t":"羅波安與耶羅波安時常爭戰。","notes":[]},{"n":31,"t":"羅波安與他列祖同睡，葬在大衛城他列祖的墳地裏。他母親名叫拿瑪，是亞捫人。他兒子亞比央接續他作王。","notes":["又名_亞比雅_"]}]},"15":{"heading":"猶大王亞比央","verses":[{"n":1,"t":"尼八的兒子耶羅波安王十八年，亞比央登基作猶大王，","notes":[]},{"n":2,"t":"在耶路撒冷作王三年。他母親名叫瑪迦，是押沙龍的女兒。","notes":[]},{"n":3,"t":"亞比央行他父親在他以前所行的一切惡，他的心不像他祖大衛的心，誠誠實實地順服耶和華－他的神。","notes":[]},{"n":4,"t":"然而耶和華－他的神因大衛的緣故，仍使他在耶路撒冷有燈光，叫他兒子接續他作王，堅立耶路撒冷。","notes":[]},{"n":5,"t":"因為大衛除了赫人烏利亞那件事，都是行耶和華眼中看為正的事，一生沒有違背耶和華一切所吩咐的。","notes":[]},{"n":6,"t":"羅波安在世的日子常與耶羅波安爭戰。","notes":[]},{"n":7,"t":"亞比央其餘的事，凡他所行的，都寫在猶大列王記上。亞比央常與耶羅波安爭戰。","notes":[]},{"n":8,"t":"亞比央與他列祖同睡，葬在大衛的城裏。他兒子亞撒接續他作王。","notes":[]},{"n":9,"t":"以色列王耶羅波安二十年，亞撒登基作猶大王，","notes":[],"heads":["猶大王亞撒"]},{"n":10,"t":"在耶路撒冷作王四十一年。他祖母名叫瑪迦，是押沙龍的女兒。","notes":[]},{"n":11,"t":"亞撒效法他祖大衛行耶和華眼中看為正的事，","notes":[]},{"n":12,"t":"從國中除去孌童，又除掉他列祖所造的一切偶像；","notes":[]},{"n":13,"t":"並且貶了他祖母瑪迦太后的位，因她造了可憎的偶像亞舍拉。亞撒砍下她的偶像，燒在汲淪溪邊，","notes":[]},{"n":14,"t":"只是邱壇還沒有廢去。亞撒一生卻向耶和華存誠實的心。","notes":[]},{"n":15,"t":"亞撒將他父親所分別為聖與自己所分別為聖的金銀和器皿都奉到耶和華的殿裏。","notes":[]},{"n":16,"t":"亞撒和以色列王巴沙在世的日子常常爭戰。","notes":[]},{"n":17,"t":"以色列王巴沙上來要攻擊猶大，修築拉瑪，不許人從猶大王亞撒那裏出入。","notes":[]},{"n":18,"t":"於是亞撒將耶和華殿和王宮府庫裏所剩下的金銀都交在他臣僕手中，打發他們往住大馬士革的亞蘭王－希旬的孫子、他伯利們的兒子便‧哈達那裏去，","notes":[]},{"n":19,"t":"說：「你父曾與我父立約，我與你也要立約。現在我將金銀送你為禮物，求你廢掉你與以色列王巴沙所立的約，使他離開我。」","notes":[]},{"n":20,"t":"便‧哈達聽從亞撒王的話，派軍長去攻擊以色列的城邑；他們就攻破以雲、但、亞伯‧伯‧瑪迦、基尼烈全境、拿弗他利全境。","notes":[]},{"n":21,"t":"巴沙聽見，就停工不修築拉瑪了，仍住在得撒。","notes":[]},{"n":22,"t":"於是亞撒王宣告猶大眾人，不准一個推辭，吩咐他們將巴沙修築拉瑪所用的石頭、木頭都運去，用以修築便雅憫的迦巴和米斯巴。","notes":[]},{"n":23,"t":"亞撒其餘的事，凡他所行的，並他的勇力與他所建築的城邑，都寫在猶大列王記上。亞撒年老的時候，腳上有病。","notes":[]},{"n":24,"t":"亞撒與他列祖同睡，葬在他祖大衛城他列祖的墳地裏。他兒子約沙法接續他作王。","notes":[]},{"n":25,"t":"猶大王亞撒第二年，耶羅波安的兒子拿答登基作以色列王共二年，","notes":[],"heads":["以色列王拿答"]},{"n":26,"t":"拿答行耶和華眼中看為惡的事，行他父親所行的，犯他父親使以色列人陷在罪裏的那罪。","notes":[]},{"n":27,"t":"以薩迦人亞希雅的兒子巴沙背叛拿答，在非利士的基比頓殺了他。那時拿答和以色列眾人正圍困基比頓。","notes":[]},{"n":28,"t":"在猶大王亞撒第三年巴沙殺了他，篡了他的位。","notes":[]},{"n":29,"t":"巴沙一作王就殺了耶羅波安的全家，凡有氣息的沒有留下一個，都滅盡了，正應驗耶和華藉他僕人示羅人亞希雅所說的話。","notes":[]},{"n":30,"t":"這是因為耶羅波安所犯的罪使以色列人陷在罪裏，惹動耶和華－以色列神的怒氣。","notes":[]},{"n":31,"t":"拿答其餘的事，凡他所行的，都寫在以色列諸王記上。","notes":[]},{"n":32,"t":"亞撒和以色列王巴沙在世的日子常常爭戰。","notes":[]},{"n":33,"t":"猶大王亞撒第三年，亞希雅的兒子巴沙在得撒登基作以色列眾人的王共二十四年。","notes":[],"heads":["以色列王巴沙"]},{"n":34,"t":"他行耶和華眼中看為惡的事，行耶羅波安所行的道，犯他使以色列人陷在罪裏的那罪。","notes":[]}]},"16":{"heading":"以色列王以拉","verses":[{"n":1,"t":"耶和華的話臨到哈拿尼的兒子耶戶，責備巴沙說：","notes":[]},{"n":2,"t":"「我既從塵埃中提拔你，立你作我民以色列的君，你竟行耶羅波安所行的道，使我民以色列陷在罪裏，惹我發怒，","notes":[]},{"n":3,"t":"我必除盡你和你的家，使你的家像尼八的兒子耶羅波安的家一樣。","notes":[]},{"n":4,"t":"凡屬巴沙的人，死在城中的必被狗吃，死在田野的必被空中的鳥吃。」","notes":[]},{"n":5,"t":"巴沙其餘的事，凡他所行的和他的勇力，都寫在以色列諸王記上。","notes":[]},{"n":6,"t":"巴沙與他列祖同睡，葬在得撒。他兒子以拉接續他作王。","notes":[]},{"n":7,"t":"耶和華的話臨到哈拿尼的兒子先知耶戶，責備巴沙和他的家，因他行耶和華眼中看為惡的一切事，以他手所做的惹耶和華發怒，像耶羅波安的家一樣，又因他殺了耶羅波安的全家。","notes":[]},{"n":8,"t":"猶大王亞撒二十六年，巴沙的兒子以拉在得撒登基作以色列王共二年。","notes":[]},{"n":9,"t":"有管理他一半戰車的臣子心利背叛他。當他在得撒家宰亞雜家裏喝醉的時候，","notes":[]},{"n":10,"t":"心利就進去殺了他，篡了他的位。這是猶大王亞撒二十七年的事。","notes":[]},{"n":11,"t":"心利一坐王位就殺了巴沙的全家，連他的親屬、朋友也沒有留下一個男丁。","notes":[]},{"n":12,"t":"心利這樣滅絕巴沙的全家，正如耶和華藉先知耶戶責備巴沙的話。","notes":[]},{"n":13,"t":"這是因巴沙和他兒子以拉的一切罪，就是他們使以色列人陷在罪裏的那罪，以虛無的神惹耶和華－以色列神的怒氣。","notes":[]},{"n":14,"t":"以拉其餘的事，凡他所行的，都寫在以色列諸王記上。","notes":[]},{"n":15,"t":"猶大王亞撒二十七年，心利在得撒作王七日。那時民正安營圍攻非利士的基比頓。","notes":[],"heads":["以色列王心利"]},{"n":16,"t":"民在營中聽說心利背叛，又殺了王，故此以色列眾人當日在營中立元帥暗利作以色列王。","notes":[]},{"n":17,"t":"暗利率領以色列眾人，從基比頓上去，圍困得撒。","notes":[]},{"n":18,"t":"心利見城破失，就進了王宮的衛所，放火焚燒宮殿，自焚而死。","notes":[]},{"n":19,"t":"這是因他犯罪，行耶和華眼中看為惡的事，行耶羅波安所行的，犯他使以色列人陷在罪裏的那罪。","notes":[]},{"n":20,"t":"心利其餘的事和他背叛的情形都寫在以色列諸王記上。","notes":[]},{"n":21,"t":"那時，以色列民分為兩半：一半隨從基納的兒子提比尼，要立他作王；一半隨從暗利。","notes":[],"heads":["以色列王暗利"]},{"n":22,"t":"但隨從暗利的民勝過隨從基納的兒子提比尼的民。提比尼死了，暗利就作了王。","notes":[]},{"n":23,"t":"猶大王亞撒三十一年，暗利登基作以色列王共十二年；在得撒作王六年。","notes":[]},{"n":24,"t":"暗利用二他連得銀子向撒瑪買了撒馬利亞山，在山上造城，就按著山的原主撒瑪的名，給所造的城起名叫撒馬利亞。","notes":[]},{"n":25,"t":"暗利行耶和華眼中看為惡的事，比他以前的列王作惡更甚。","notes":[]},{"n":26,"t":"因他行了尼八的兒子耶羅波安所行的，犯他使以色列人陷在罪裏的那罪，以虛無的神惹耶和華－以色列神的怒氣。","notes":[]},{"n":27,"t":"暗利其餘的事和他所顯出的勇力都寫在以色列諸王記上。","notes":[]},{"n":28,"t":"暗利與他列祖同睡，葬在撒馬利亞。他兒子亞哈接續他作王。","notes":[]},{"n":29,"t":"猶大王亞撒三十八年，暗利的兒子亞哈登基作了以色列王。暗利的兒子亞哈在撒馬利亞作以色列王二十二年。","notes":[],"heads":["以色列王亞哈"]},{"n":30,"t":"暗利的兒子亞哈行耶和華眼中看為惡的事，比他以前的列王更甚，","notes":[]},{"n":31,"t":"犯了尼八的兒子耶羅波安所犯的罪；他還以為輕，又娶了西頓王謁巴力的女兒耶洗別為妻，去事奉敬拜巴力，","notes":[]},{"n":32,"t":"在撒馬利亞建造巴力的廟，在廟裏為巴力築壇。","notes":[]},{"n":33,"t":"亞哈又做亞舍拉，他所行的惹耶和華－以色列神的怒氣，比他以前的以色列諸王更甚。","notes":[]},{"n":34,"t":"亞哈在位的時候，有伯特利人希伊勒重修耶利哥城；立根基的時候，喪了長子亞比蘭；安門的時候，喪了幼子西割，正如耶和華藉嫩的兒子約書亞所說的話。","notes":[]}]},"17":{"heading":"以利亞和旱災","verses":[{"n":1,"t":"基列寄居的提斯比人以利亞對亞哈說：「我指著所事奉永生耶和華－以色列的神起誓，這幾年我若不禱告，必不降露，不下雨。」","notes":[]},{"n":2,"t":"耶和華的話臨到以利亞說：","notes":[]},{"n":3,"t":"「你離開這裏往東去，藏在約旦河東邊的基立溪旁。","notes":[]},{"n":4,"t":"你要喝那溪裏的水，我已吩咐烏鴉在那裏供養你。」","notes":[]},{"n":5,"t":"於是以利亞照著耶和華的話，去住在約旦河東的基立溪旁。","notes":[]},{"n":6,"t":"烏鴉早晚給他叼餅和肉來，他也喝那溪裏的水。","notes":[]},{"n":7,"t":"過了些日子，溪水就乾了，因為雨沒有下在地上。","notes":[]},{"n":8,"t":"耶和華的話臨到他說：","notes":[],"heads":["以利亞和撒勒法的寡婦"]},{"n":9,"t":"「你起身往西頓的撒勒法去，住在那裏；我已吩咐那裏的一個寡婦供養你。」","notes":["撒勒法與路加福音四章二十六節同"]},{"n":10,"t":"以利亞就起身往撒勒法去。到了城門，見有一個寡婦在那裏撿柴，以利亞呼叫她說：「求你用器皿取點水來給我喝。」","notes":[]},{"n":11,"t":"她去取水的時候，以利亞又呼叫她說：「也求你拿點餅來給我！」","notes":[]},{"n":12,"t":"她說：「我指著永生耶和華－你的神起誓，我沒有餅，罈內只有一把麵，瓶裏只有一點油；我現在找兩根柴，回家要為我和我兒子做餅；我們吃了，死就死吧！」","notes":[]},{"n":13,"t":"以利亞對她說：「不要懼怕！可以照你所說的去做吧！只要先為我做一個小餅拿來給我，然後為你和你的兒子做餅。","notes":[]},{"n":14,"t":"因為耶和華－以色列的神如此說：罈內的麵必不減少，瓶裏的油必不缺短，直到耶和華使雨降在地上的日子。」","notes":[]},{"n":15,"t":"婦人就照以利亞的話去行。她和她家中的人，並以利亞，吃了許多日子。","notes":[]},{"n":16,"t":"罈內的麵果不減少，瓶裏的油也不缺短，正如耶和華藉以利亞所說的話。","notes":[]},{"n":17,"t":"這事以後，作那家主母的婦人，她兒子病了；病得甚重，以致身無氣息。","notes":[]},{"n":18,"t":"婦人對以利亞說：「神人哪，我與你何干？你竟到我這裏來，使神想念我的罪，以致我的兒子死呢？」","notes":[]},{"n":19,"t":"以利亞對她說：「把你兒子交給我。」以利亞就從婦人懷中將孩子接過來，抱到他所住的樓中，放在自己的床上，","notes":[]},{"n":20,"t":"就求告耶和華說：「耶和華－我的神啊，我寄居在這寡婦的家裏，你就降禍與她，使她的兒子死了嗎？」","notes":[]},{"n":21,"t":"以利亞三次伏在孩子的身上，求告耶和華說：「耶和華－我的神啊，求你使這孩子的靈魂仍入他的身體！」","notes":[]},{"n":22,"t":"耶和華應允以利亞的話，孩子的靈魂仍入他的身體，他就活了。","notes":[]},{"n":23,"t":"以利亞將孩子從樓上抱下來，進屋子交給他母親，說：「看哪，你的兒子活了！」","notes":[]},{"n":24,"t":"婦人對以利亞說：「現在我知道你是神人，耶和華藉你口所說的話是真的。」","notes":[]}]},"18":{"heading":"以利亞和巴力的先知們","verses":[{"n":1,"t":"過了許久，到第三年，耶和華的話臨到以利亞說：「你去，使亞哈得見你；我要降雨在地上。」","notes":[]},{"n":2,"t":"以利亞就去，要使亞哈得見他。那時，撒馬利亞有大饑荒；","notes":[]},{"n":3,"t":"亞哈將他的家宰俄巴底召了來。（俄巴底甚是敬畏耶和華，","notes":[]},{"n":4,"t":"耶洗別殺耶和華眾先知的時候，俄巴底將一百個先知藏了，每五十人藏在一個洞裏，拿餅和水供養他們。）","notes":[]},{"n":5,"t":"亞哈對俄巴底說：「我們走遍這地，到一切水泉旁和一切溪邊，或者找得著青草，可以救活騾馬，免得絕了牲畜。」","notes":[]},{"n":6,"t":"於是二人分地遊行，亞哈獨走一路，俄巴底獨走一路。","notes":[]},{"n":7,"t":"俄巴底在路上恰與以利亞相遇，俄巴底認出他來，就俯伏在地，說：「你是我主以利亞不是？」","notes":[]},{"n":8,"t":"回答說：「是。你去告訴你主人說，以利亞在這裏。」","notes":[]},{"n":9,"t":"俄巴底說：「僕人有甚麼罪，你竟要將我交在亞哈手裏，使他殺我呢？","notes":[]},{"n":10,"t":"我指著永生耶和華－你的神起誓，無論哪一邦哪一國，我主都打發人去找你。若說你沒有在那裏，就必使那邦那國的人起誓說，實在是找不著你。","notes":[]},{"n":11,"t":"現在你說，要去告訴你主人說，以利亞在這裏；","notes":[]},{"n":12,"t":"恐怕我一離開你，耶和華的靈就提你到我所不知道的地方去。這樣，我去告訴亞哈，他若找不著你，就必殺我；僕人卻是自幼敬畏耶和華的。","notes":[]},{"n":13,"t":"耶洗別殺耶和華眾先知的時候，我將耶和華的一百個先知藏了，每五十人藏在一個洞裏，拿餅和水供養他們，豈沒有人將這事告訴我主嗎？","notes":[]},{"n":14,"t":"現在你說，要去告訴你主人說，以利亞在這裏，他必殺我。」","notes":[]},{"n":15,"t":"以利亞說：「我指著所事奉永生的萬軍之耶和華起誓，我今日必使亞哈得見我。」","notes":[]},{"n":16,"t":"於是俄巴底去迎著亞哈，告訴他；亞哈就去迎著以利亞。","notes":[]},{"n":17,"t":"亞哈見了以利亞，便說：「使以色列遭災的就是你嗎？」","notes":[]},{"n":18,"t":"以利亞說：「使以色列遭災的不是我，乃是你和你父家；因為你們離棄耶和華的誡命，去隨從巴力。","notes":[]},{"n":19,"t":"現在你當差遣人，招聚以色列眾人和事奉巴力的那四百五十個先知，並耶洗別所供養事奉亞舍拉的那四百個先知，使他們都上迦密山去見我。」","notes":[]},{"n":20,"t":"亞哈就差遣人招聚以色列眾人和先知都上迦密山。","notes":[]},{"n":21,"t":"以利亞前來對眾民說：「你們心持兩意要到幾時呢？若耶和華是神，就當順從耶和華；若巴力是神，就當順從巴力。」眾民一言不答。","notes":[]},{"n":22,"t":"以利亞對眾民說：「作耶和華先知的只剩下我一個人；巴力的先知卻有四百五十個人。","notes":[]},{"n":23,"t":"當給我們兩隻牛犢，巴力的先知可以挑選一隻，切成塊子，放在柴上，不要點火；我也預備一隻牛犢放在柴上，也不點火。","notes":[]},{"n":24,"t":"你們求告你們神的名，我也求告耶和華的名。那降火顯應的神，就是神。」眾民回答說：「這話甚好。」","notes":[]},{"n":25,"t":"以利亞對巴力的先知說：「你們既是人多，當先挑選一隻牛犢，預備好了，就求告你們神的名，卻不要點火。」","notes":[]},{"n":26,"t":"他們將所得的牛犢預備好了，從早晨到午間，求告巴力的名說：「巴力啊，求你應允我們！」卻沒有聲音，沒有應允的。他們在所築的壇四圍踊跳。","notes":[]},{"n":27,"t":"到了正午，以利亞嬉笑他們，說：「大聲求告吧！因為他是神，他或默想，或走到一邊，或行路，或睡覺，你們當叫醒他。」","notes":[]},{"n":28,"t":"他們大聲求告，按著他們的規矩，用刀槍自割、自刺，直到身體流血。","notes":[]},{"n":29,"t":"從午後直到獻晚祭的時候，他們狂呼亂叫，卻沒有聲音，沒有應允的，也沒有理會的。","notes":[]},{"n":30,"t":"以利亞對眾民說：「你們到我這裏來。」眾民就到他那裏。他便重修已經毀壞耶和華的壇。","notes":[]},{"n":31,"t":"以利亞照雅各子孫支派的數目，取了十二塊石頭（耶和華的話曾臨到雅各說：「你的名要叫以色列」），","notes":[]},{"n":32,"t":"用這些石頭為耶和華的名築一座壇，在壇的四圍挖溝，可容穀種二細亞，","notes":[]},{"n":33,"t":"又在壇上擺好了柴，把牛犢切成塊子放在柴上，對眾人說：「你們用四個桶盛滿水，倒在燔祭和柴上」；","notes":[]},{"n":34,"t":"又說：「倒第二次。」他們就倒第二次；又說：「倒第三次。」他們就倒第三次。","notes":[]},{"n":35,"t":"水流在壇的四圍，溝裏也滿了水。","notes":[]},{"n":36,"t":"到了獻晚祭的時候，先知以利亞近前來，說：「亞伯拉罕、以撒、以色列的神，耶和華啊，求你今日使人知道你是以色列的神，也知道我是你的僕人，又是奉你的命行這一切事。","notes":[]},{"n":37,"t":"耶和華啊，求你應允我，應允我！使這民知道你－耶和華是神，又知道是你叫這民的心回轉。」","notes":[]},{"n":38,"t":"於是，耶和華降下火來，燒盡燔祭、木柴、石頭、塵土，又燒乾溝裏的水。","notes":[]},{"n":39,"t":"眾民看見了，就俯伏在地，說：「耶和華是神！耶和華是神！」","notes":[]},{"n":40,"t":"以利亞對他們說：「拿住巴力的先知，不容一人逃脫！」眾人就拿住他們。以利亞帶他們到基順河邊，在那裏殺了他們。","notes":[]},{"n":41,"t":"以利亞對亞哈說：「你現在可以上去吃喝，因為有多雨的響聲了。」","notes":[],"heads":["旱災停止"]},{"n":42,"t":"亞哈就上去吃喝。以利亞上了迦密山頂，屈身在地，將臉伏在兩膝之中；","notes":[]},{"n":43,"t":"對僕人說：「你上去，向海觀看。」僕人就上去觀看，說：「沒有甚麼。」他說：「你再去觀看。」如此七次。","notes":[]},{"n":44,"t":"第七次僕人說：「我看見有一小片雲從海裏上來，不過如人手那樣大。」以利亞說：「你上去告訴亞哈，當套車下去，免得被雨阻擋。」","notes":[]},{"n":45,"t":"霎時間，天因風雲黑暗，降下大雨。亞哈就坐車往耶斯列去了。","notes":[]},{"n":46,"t":"耶和華的靈降在以利亞身上，他就束上腰，奔在亞哈前頭，直到耶斯列的城門。","notes":["原文是手"]}]},"19":{"heading":"以利亞在何烈山上","verses":[{"n":1,"t":"亞哈將以利亞一切所行的和他用刀殺眾先知的事都告訴耶洗別。","notes":[]},{"n":2,"t":"耶洗別就差遣人去見以利亞，告訴他說：「明日約在這時候，我若不使你的性命像那些人的性命一樣，願神明重重地降罰與我。」","notes":[]},{"n":3,"t":"以利亞見這光景就起來逃命，到了猶大的別是巴，將僕人留在那裏，","notes":[]},{"n":4,"t":"自己在曠野走了一日的路程，來到一棵羅騰樹下，就坐在那裏求死，說：「耶和華啊，罷了！求你取我的性命，因為我不勝於我的列祖。」","notes":["羅騰，小樹名，松類；下同"]},{"n":5,"t":"他就躺在羅騰樹下，睡著了。有一個天使拍他，說：「起來吃吧！」","notes":[]},{"n":6,"t":"他觀看，見頭旁有一瓶水與炭火燒的餅，他就吃了喝了，仍然躺下。","notes":[]},{"n":7,"t":"耶和華的使者第二次來拍他，說：「起來吃吧！因為你當走的路甚遠。」","notes":[]},{"n":8,"t":"他就起來吃了喝了，仗著這飲食的力，走了四十晝夜，到了神的山，就是何烈山。","notes":[]},{"n":9,"t":"他在那裏進了一個洞，就住在洞中。耶和華的話臨到他說：「以利亞啊，你在這裏做甚麼？」","notes":[]},{"n":10,"t":"他說：「我為耶和華－萬軍之神大發熱心；因為以色列人背棄了你的約，毀壞了你的壇，用刀殺了你的先知，只剩下我一個人，他們還要尋索我的命。」","notes":[]},{"n":11,"t":"耶和華說：「你出來站在山上，在我面前。」那時耶和華從那裏經過，在他面前有烈風大作，崩山碎石，耶和華卻不在風中；風後地震，耶和華卻不在其中；","notes":[]},{"n":12,"t":"地震後有火，耶和華也不在火中；火後有微小的聲音。","notes":[]},{"n":13,"t":"以利亞聽見，就用外衣蒙上臉，出來站在洞口。有聲音向他說：「以利亞啊，你在這裏做甚麼？」","notes":[]},{"n":14,"t":"他說：「我為耶和華－萬軍之神大發熱心；因為以色列人背棄了你的約，毀壞了你的壇，用刀殺了你的先知，只剩下我一個人，他們還要尋索我的命。」","notes":[]},{"n":15,"t":"耶和華對他說：「你回去，從曠野往大馬士革去。到了那裏，就要膏哈薛作亞蘭王，","notes":[]},{"n":16,"t":"又膏寧示的孫子耶戶作以色列王，並膏亞伯‧米何拉人沙法的兒子以利沙作先知接續你。","notes":[]},{"n":17,"t":"將來躲避哈薛之刀的，必被耶戶所殺；躲避耶戶之刀的，必被以利沙所殺。","notes":[]},{"n":18,"t":"但我在以色列人中為自己留下七千人，是未曾向巴力屈膝的，未曾與巴力親嘴的。」","notes":[]},{"n":19,"t":"於是，以利亞離開那裏走了，遇見沙法的兒子以利沙耕地；在他前頭有十二對牛，自己趕著第十二對。以利亞到他那裏去，將自己的外衣搭在他身上。","notes":[],"heads":["以利沙蒙選召"]},{"n":20,"t":"以利沙就離開牛，跑到以利亞那裏，說：「求你容我先與父母親嘴，然後我便跟隨你。」以利亞對他說：「你回去吧，我向你做了甚麼呢？」","notes":[]},{"n":21,"t":"以利沙就離開他回去，宰了一對牛，用套牛的器具煮肉給民吃，隨後就起身跟隨以利亞，服事他。","notes":[]}]},"20":{"heading":"與亞蘭人爭戰","verses":[{"n":1,"t":"亞蘭王便‧哈達聚集他的全軍，率領三十二個王，帶著車馬上來圍攻撒馬利亞；","notes":[]},{"n":2,"t":"又差遣使者進城見以色列王亞哈，對他說：「便‧哈達如此說：","notes":[]},{"n":3,"t":"你的金銀都要歸我，你妻子兒女中最美的也要歸我。」","notes":[]},{"n":4,"t":"以色列王回答說：「我主我王啊，可以依著你的話，我與我所有的都歸你。」","notes":[]},{"n":5,"t":"使者又來說：「便‧哈達如此說：我已差遣人去見你，要你將你的金銀、妻子、兒女都給我。","notes":[]},{"n":6,"t":"但明日約在這時候，我還要差遣臣僕到你那裏，搜查你的家和你僕人的家，將你眼中一切所喜愛的都拿了去。」","notes":[]},{"n":7,"t":"以色列王召了國中的長老來，對他們說：「請你們看看，這人是怎樣地謀害我，他先差遣人到我這裏來，要我的妻子、兒女，和金銀，我並沒有推辭他。」","notes":[]},{"n":8,"t":"長老和百姓對王說：「不要聽從他，也不要應允他。」","notes":[]},{"n":9,"t":"故此，以色列王對便‧哈達的使者說：「你們告訴我主我王說：王頭一次差遣人向僕人所要的，僕人都依從；但這次所要的，我不能依從。」使者就去回覆便‧哈達。","notes":[]},{"n":10,"t":"便‧哈達又差遣人去見亞哈說：「撒馬利亞的塵土若夠跟從我的人每人捧一捧的，願神明重重地降罰與我！」","notes":[]},{"n":11,"t":"以色列王說：「你告訴他說，才頂盔貫甲的，休要像摘盔卸甲的誇口。」","notes":[]},{"n":12,"t":"便‧哈達和諸王正在帳幕裏喝酒，聽見這話，就對他臣僕說：「擺隊吧！」他們就擺隊攻城。","notes":[]},{"n":13,"t":"有一個先知來見以色列王亞哈，說：「耶和華如此說：『這一大群人你看見了嗎？今日我必將他們交在你手裏，你就知道我是耶和華。』」","notes":[]},{"n":14,"t":"亞哈說：「藉著誰呢？」他回答說：「耶和華說，藉著跟從省長的少年人。」亞哈說：「要誰率領呢？」他說：「要你親自率領。」","notes":[]},{"n":15,"t":"於是亞哈數點跟從省長的少年人，共有二百三十二名，後又數點以色列的眾兵，共有七千名。","notes":[]},{"n":16,"t":"午間，他們就出城；便‧哈達和幫助他的三十二個王正在帳幕裏痛飲。","notes":[]},{"n":17,"t":"跟從省長的少年人先出城；便‧哈達差遣人去探望，他們回報說：「有人從撒馬利亞出來了。」","notes":[]},{"n":18,"t":"他說：「他們若為講和出來，要活捉他們；若為打仗出來，也要活捉他們。」","notes":[]},{"n":19,"t":"跟從省長的少年人出城，軍兵跟隨他們；","notes":[]},{"n":20,"t":"各人遇見敵人就殺。亞蘭人逃跑，以色列人追趕他們；亞蘭王便‧哈達騎著馬和馬兵一同逃跑。","notes":[]},{"n":21,"t":"以色列王出城攻打車馬，大大擊殺亞蘭人。","notes":[]},{"n":22,"t":"那先知來見以色列王，對他說：「你當自強，留心怎樣防備；因為到明年這時候，亞蘭王必上來攻擊你。」","notes":[]},{"n":23,"t":"亞蘭王的臣僕對亞蘭王說：「以色列人的神是山神，所以他們勝過我們；但在平原與他們打仗，我們必定得勝。","notes":[],"heads":["亞蘭人第二次來犯"]},{"n":24,"t":"王當這樣行：把諸王革去，派軍長代替他們，","notes":[]},{"n":25,"t":"又照著王喪失軍兵之數，再招募一軍，馬補馬，車補車，我們在平原與他們打仗，必定得勝。」王便聽臣僕的話去行。","notes":[]},{"n":26,"t":"次年，便‧哈達果然點齊亞蘭人上亞弗去，要與以色列人打仗。","notes":[]},{"n":27,"t":"以色列人也點齊軍兵，預備食物，迎著亞蘭人出去，對著他們安營，好像兩小群山羊羔；亞蘭人卻滿了地面。","notes":[]},{"n":28,"t":"有神人來見以色列王，說：「耶和華如此說：『亞蘭人既說我－耶和華是山神，不是平原的神，所以我必將這一大群人都交在你手中，你們就知道我是耶和華。』」","notes":[]},{"n":29,"t":"以色列人與亞蘭人相對安營七日，到第七日兩軍交戰；那一日以色列人殺了亞蘭人步兵十萬，","notes":[]},{"n":30,"t":"其餘的逃入亞弗城；城牆塌倒，壓死剩下的二萬七千人。便‧哈達也逃入城，藏在嚴密的屋子裏。","notes":[]},{"n":31,"t":"他的臣僕對他說：「我們聽說以色列王都是仁慈的王，現在我們不如腰束麻布，頭套繩索，出去投降以色列王，或者他存留王的性命。」","notes":[]},{"n":32,"t":"於是他們腰束麻布，頭套繩索，去見以色列王，說：「王的僕人便‧哈達說，求王存留我的性命。」亞哈說：「他還活著嗎？他是我的兄弟。」","notes":[]},{"n":33,"t":"這些人留心探出他的口氣來，便急忙就著他的話說：「便‧哈達是王的兄弟！」王說：「你們去請他來。」便‧哈達出來見王，王就請他上車。","notes":[]},{"n":34,"t":"便‧哈達對王說：「我父從你父那裏所奪的城邑，我必歸還。你可以在大馬士革立街市，像我父在撒馬利亞所立的一樣。」亞哈說：「我照此立約，放你回去」，就與他立約，放他去了。","notes":[]},{"n":35,"t":"有先知的一個門徒奉耶和華的命對他的同伴說：「你打我吧！」那人不肯打他。","notes":[],"heads":["先知責亞哈縱敵"]},{"n":36,"t":"他就對那人說：「你既不聽從耶和華的話，你一離開我，必有獅子咬死你。」那人一離開他，果然遇見獅子，把他咬死了。","notes":[]},{"n":37,"t":"先知的門徒又遇見一個人，對他說：「你打我吧！」那人就打他，將他打傷。","notes":[]},{"n":38,"t":"他就去了，用頭巾蒙眼，改換面目，在路旁等候王。","notes":[]},{"n":39,"t":"王從那裏經過，他向王呼叫說：「僕人在陣上的時候，有人帶了一個人來，對我說：『你看守這人，若把他失了，你的性命必代替他的性命；不然，你必交出一他連得銀子來。』","notes":[]},{"n":40,"t":"僕人正在忙亂之間，那人就不見了。」以色列王對他說：「你自己定妥了，必照樣判斷你。」","notes":[]},{"n":41,"t":"他急忙除掉蒙眼的頭巾，以色列王就認出他是一個先知。","notes":[]},{"n":42,"t":"他對王說：「耶和華如此說：『因你將我定要滅絕的人放去，你的命就必代替他的命，你的民也必代替他的民。』」","notes":[]},{"n":43,"t":"於是以色列王悶悶不樂地回到撒馬利亞，進了他的宮。","notes":[]}]},"21":{"heading":"拿伯的葡萄園","verses":[{"n":1,"t":"這事以後，又有一事。耶斯列人拿伯在耶斯列有一個葡萄園，靠近撒馬利亞王亞哈的宮。","notes":[]},{"n":2,"t":"亞哈對拿伯說：「你將你的葡萄園給我作菜園，因為是靠近我的宮；我就把更好的葡萄園換給你，或是你要銀子，我就按著價值給你。」","notes":[]},{"n":3,"t":"拿伯對亞哈說：「我敬畏耶和華，萬不敢將我先人留下的產業給你。」","notes":[]},{"n":4,"t":"亞哈因耶斯列人拿伯說「我不敢將我先人留下的產業給你」，就悶悶不樂地回宮，躺在床上，轉臉向內，也不吃飯。","notes":[]},{"n":5,"t":"王后耶洗別來問他說：「你為甚麼心裏這樣憂悶，不吃飯呢？」","notes":[]},{"n":6,"t":"他回答說：「因我向耶斯列人拿伯說：『你將你的葡萄園給我，我給你價銀，或是你願意，我就把別的葡萄園換給你』；他卻說：『我不將我的葡萄園給你。』」","notes":[]},{"n":7,"t":"王后耶洗別對亞哈說：「你現在是治理以色列國不是？只管起來，心裏暢暢快快地吃飯，我必將耶斯列人拿伯的葡萄園給你。」","notes":[]},{"n":8,"t":"於是託亞哈的名寫信，用王的印印上，送給那些與拿伯同城居住的長老貴冑。","notes":[]},{"n":9,"t":"信上寫著說：「你們當宣告禁食，叫拿伯坐在民間的高位上，","notes":[]},{"n":10,"t":"又叫兩個匪徒坐在拿伯對面，作見證告他說：『你謗瀆神和王了』；隨後就把他拉出去用石頭打死。」","notes":[]},{"n":11,"t":"那些與拿伯同城居住的長老貴冑得了耶洗別的信，就照信而行，","notes":[]},{"n":12,"t":"宣告禁食，叫拿伯坐在民間的高位上。","notes":[]},{"n":13,"t":"有兩個匪徒來，坐在拿伯的對面，當著眾民作見證告他說：「拿伯謗瀆神和王了！」眾人就把他拉到城外，用石頭打死。","notes":[]},{"n":14,"t":"於是打發人去見耶洗別，說：「拿伯被石頭打死了。」","notes":[]},{"n":15,"t":"耶洗別聽見拿伯被石頭打死，就對亞哈說：「你起來得耶斯列人拿伯不肯為價銀給你的葡萄園吧！現在他已經死了。」","notes":[]},{"n":16,"t":"亞哈聽見拿伯死了，就起來，下去要得耶斯列人拿伯的葡萄園。","notes":[]},{"n":17,"t":"耶和華的話臨到提斯比人以利亞說：","notes":[]},{"n":18,"t":"「你起來，去見住撒馬利亞的以色列王亞哈，他下去要得拿伯的葡萄園，現今正在那園裏。","notes":[]},{"n":19,"t":"你要對他說：『耶和華如此說：你殺了人，又得他的產業嗎？』又要對他說：『耶和華如此說：狗在何處舔拿伯的血，也必在何處舔你的血。』」","notes":[]},{"n":20,"t":"亞哈對以利亞說：「我仇敵啊，你找到我嗎？」他回答說：「我找到你了；因為你賣了自己，行耶和華眼中看為惡的事。","notes":[]},{"n":21,"t":"耶和華說：『我必使災禍臨到你，將你除盡。凡屬你的男丁，無論困住的、自由的，都從以色列中剪除。","notes":[]},{"n":22,"t":"我必使你的家像尼八的兒子耶羅波安的家，又像亞希雅的兒子巴沙的家；因為你惹我發怒，又使以色列人陷在罪裏。』","notes":[]},{"n":23,"t":"論到耶洗別，耶和華也說：『狗在耶斯列的外郭必吃耶洗別的肉。","notes":[]},{"n":24,"t":"凡屬亞哈的人，死在城中的必被狗吃，死在田野的必被空中的鳥吃。』」（","notes":[]},{"n":25,"t":"從來沒有像亞哈的，因他自賣，行耶和華眼中看為惡的事，受了王后耶洗別的聳動；","notes":[]},{"n":26,"t":"就照耶和華在以色列人面前所趕出的亞摩利人，行了最可憎惡的事，信從偶像。）","notes":[]},{"n":27,"t":"亞哈聽見這話，就撕裂衣服，禁食，身穿麻布，睡臥也穿著麻布，並且緩緩而行。","notes":[]},{"n":28,"t":"耶和華的話臨到提斯比人以利亞說：","notes":[]},{"n":29,"t":"「亞哈在我面前這樣自卑，你看見了嗎？因他在我面前自卑，他還在世的時候，我不降這禍；到他兒子的時候，我必降這禍與他的家。」","notes":[]}]},"22":{"heading":"先知米該雅警告亞哈","verses":[{"n":1,"t":"亞蘭國和以色列國三年沒有爭戰。","notes":[]},{"n":2,"t":"到第三年，猶大王約沙法下去見以色列王。","notes":[]},{"n":3,"t":"以色列王對臣僕說：「你們不知道基列的拉末是屬我們的嗎？我們豈可靜坐不動，不從亞蘭王手裏奪回來嗎？」","notes":[]},{"n":4,"t":"亞哈問約沙法說：「你肯同我去攻取基列的拉末嗎？」約沙法對以色列王說：「你我不分彼此，我的民與你的民一樣，我的馬與你的馬一樣。」","notes":[]},{"n":5,"t":"約沙法對以色列王說：「請你先求問耶和華。」","notes":[]},{"n":6,"t":"於是以色列王招聚先知，約有四百人，問他們說：「我上去攻取基列的拉末可以不可以？」他們說：「可以上去，因為主必將那城交在王的手裏。」","notes":[]},{"n":7,"t":"約沙法說：「這裏不是還有耶和華的先知，我們可以求問他嗎？」","notes":[]},{"n":8,"t":"以色列王對約沙法說：「還有一個人，是音拉的兒子米該雅，我們可以託他求問耶和華。只是我恨他；因為他指著我所說的預言，不說吉語，單說凶言。」約沙法說：「王不必這樣說。」","notes":[]},{"n":9,"t":"以色列王就召了一個太監來，說：「你快去，將音拉的兒子米該雅召來。」","notes":[]},{"n":10,"t":"以色列王和猶大王約沙法在撒馬利亞城門前的空場上，各穿朝服，坐在位上，所有的先知都在他們面前說預言。","notes":[]},{"n":11,"t":"基拿拿的兒子西底家造了兩個鐵角，說：「耶和華如此說：『你要用這角牴觸亞蘭人，直到將他們滅盡。』」","notes":[]},{"n":12,"t":"所有的先知也都這樣預言說：「可以上基列的拉末去，必然得勝，因為耶和華必將那城交在王的手中。」","notes":[]},{"n":13,"t":"那去召米該雅的使者對米該雅說：「眾先知一口同音地都向王說吉言，你不如與他們說一樣的話，也說吉言。」","notes":[]},{"n":14,"t":"米該雅說：「我指著永生的耶和華起誓，耶和華對我說甚麼，我就說甚麼。」","notes":[]},{"n":15,"t":"米該雅到王面前，王問他說：「米該雅啊，我們上去攻取基列的拉末可以不可以？」他回答說：「可以上去，必然得勝，耶和華必將那城交在王的手中。」","notes":[]},{"n":16,"t":"王對他說：「我當囑咐你幾次，你才奉耶和華的名向我說實話呢？」","notes":[]},{"n":17,"t":"米該雅說：「我看見以色列眾民散在山上，如同沒有牧人的羊群一般。耶和華說：『這民沒有主人，他們可以平平安安地各歸各家去。』」","notes":[]},{"n":18,"t":"以色列王對約沙法說：「我豈沒有告訴你，這人指著我所說的預言，不說吉語單說凶言嗎？」","notes":[]},{"n":19,"t":"米該雅說：「你要聽耶和華的話！我看見耶和華坐在寶座上，天上的萬軍侍立在他左右。","notes":[]},{"n":20,"t":"耶和華說：『誰去引誘亞哈上基列的拉末去陣亡呢？』這個就這樣說，那個就那樣說。","notes":[]},{"n":21,"t":"隨後有一個神靈出來，站在耶和華面前，說：『我去引誘他。』","notes":[]},{"n":22,"t":"耶和華問他說：『你用何法呢？』他說：『我去，要在他眾先知口中作謊言的靈。』耶和華說：『這樣，你必能引誘他，你去如此行吧！』","notes":[]},{"n":23,"t":"現在耶和華使謊言的靈入了你這些先知的口，並且耶和華已經命定降禍與你。」","notes":[]},{"n":24,"t":"基拿拿的兒子西底家前來，打米該雅的臉，說：「耶和華的靈從哪裏離開我與你說話呢？」","notes":[]},{"n":25,"t":"米該雅說：「你進嚴密的屋子藏躲的那日，就必看見了。」","notes":[]},{"n":26,"t":"以色列王說：「將米該雅帶回，交給邑宰亞們和王的兒子約阿施，說","notes":[]},{"n":27,"t":"王如此說，把這個人下在監裏，使他受苦，吃不飽喝不足，等候我平平安安地回來。」","notes":[]},{"n":28,"t":"米該雅說：「你若能平平安安地回來，那就是耶和華沒有藉我說這話了」；又說：「眾民哪，你們都要聽！」","notes":[]},{"n":29,"t":"以色列王和猶大王約沙法上基列的拉末去了。","notes":[],"heads":["亞哈陣亡"]},{"n":30,"t":"以色列王對約沙法說：「我要改裝上陣，你可以仍穿王服。」以色列王就改裝上陣。","notes":[]},{"n":31,"t":"先是亞蘭王吩咐他的三十二個車兵長說：「他們的兵將，無論大小，你們都不可與他們爭戰，只要與以色列王爭戰。」","notes":[]},{"n":32,"t":"車兵長看見約沙法，便說：「這必是以色列王！」就轉過去與他爭戰，約沙法便呼喊。","notes":[]},{"n":33,"t":"車兵長見不是以色列王，就轉去不追他了。","notes":[]},{"n":34,"t":"有一人隨便開弓，恰巧射入以色列王的甲縫裏。王對趕車的說：「我受了重傷，你轉過車來，拉我出陣吧！」","notes":[]},{"n":35,"t":"那日，陣勢越戰越猛，有人扶王站在車上，抵擋亞蘭人。到晚上，王就死了，血從傷處流在車中。","notes":[]},{"n":36,"t":"約在日落的時候，有號令傳遍軍中，說：「各歸本城，各歸本地吧！」","notes":[]},{"n":37,"t":"王既死了，眾人將他送到撒馬利亞，就葬在那裏；","notes":[]},{"n":38,"t":"又有人把他的車洗在撒馬利亞的池旁（妓女在那裏洗澡），狗來舔他的血，正如耶和華所說的話。","notes":[]},{"n":39,"t":"亞哈其餘的事，凡他所行的和他所修造的象牙宮，並所建築的一切城邑，都寫在以色列諸王記上。","notes":[]},{"n":40,"t":"亞哈與他列祖同睡。他兒子亞哈謝接續他作王。","notes":[]},{"n":41,"t":"以色列王亞哈第四年，亞撒的兒子約沙法登基作了猶大王。","notes":[],"heads":["猶大王約沙法"]},{"n":42,"t":"約沙法登基的時候年三十五歲，在耶路撒冷作王二十五年。他母親名叫阿蘇巴，乃示利希的女兒。","notes":[]},{"n":43,"t":"約沙法行他父親亞撒所行的道，不偏離左右，行耶和華眼中看為正的事；只是邱壇還沒有廢去，百姓仍在那裏獻祭燒香。","notes":[]},{"n":44,"t":"約沙法與以色列王和好。","notes":[]},{"n":45,"t":"約沙法其餘的事和他所顯出的勇力，並他怎樣爭戰，都寫在猶大列王記上。","notes":[]},{"n":46,"t":"約沙法將他父親亞撒在世所剩下的孌童都從國中除去了。","notes":[]},{"n":47,"t":"那時以東沒有王，有總督治理。","notes":[]},{"n":48,"t":"約沙法製造他施船隻，要往俄斐去，將金子運來；只是沒有去，因為船在以旬‧迦別破壞了。","notes":[]},{"n":49,"t":"亞哈的兒子亞哈謝對約沙法說：「容我的僕人和你的僕人坐船同去吧！」約沙法卻不肯。","notes":[]},{"n":50,"t":"約沙法與列祖同睡。葬在大衛城他列祖的墳地裏。他兒子約蘭接續他作王。","notes":[]},{"n":51,"t":"猶大王約沙法十七年，亞哈的兒子亞哈謝在撒馬利亞登基，作以色列王共二年。","notes":[],"heads":["以色列王亞哈謝"]},{"n":52,"t":"他行耶和華眼中看為惡的事，效法他的父母，又行尼八的兒子耶羅波安使以色列人陷在罪裏的事。","notes":[]},{"n":53,"t":"他照他父親一切所行的，事奉敬拜巴力，惹耶和華－以色列神的怒氣。","notes":[]}]}},"2KI":{"1":{"heading":"以利亞和亞哈謝王","verses":[{"n":1,"t":"亞哈死後，摩押背叛以色列。","notes":[]},{"n":2,"t":"亞哈謝在撒馬利亞，一日從樓上的欄杆裏掉下來，就病了；於是差遣使者說：「你們去問以革倫的神巴力‧西卜，我這病能好不能好。」","notes":[]},{"n":3,"t":"但耶和華的使者對提斯比人以利亞說：「你起來，去迎著撒馬利亞王的使者，對他們說：『你們去問以革倫神巴力‧西卜，豈因以色列中沒有神嗎？』","notes":[]},{"n":4,"t":"所以耶和華如此說：『你必不下你所上的床，必定要死！』」以利亞就去了。","notes":[]},{"n":5,"t":"使者回來見王，王問他們說：「你們為甚麼回來呢？」","notes":[]},{"n":6,"t":"使者回答說：「有一個人迎著我們來，對我們說：『你們回去見差你們來的王，對他說：耶和華如此說，你差人去問以革倫神巴力‧西卜，豈因以色列中沒有神嗎？所以你必不下所上的床，必定要死。』」","notes":[]},{"n":7,"t":"王問他們說：「迎著你們來告訴你們這話的，是怎樣的人？」","notes":[]},{"n":8,"t":"回答說：「他身穿毛衣，腰束皮帶。」王說：「這必是提斯比人以利亞。」","notes":[]},{"n":9,"t":"於是，王差遣五十夫長，帶領五十人去見以利亞，他就上到以利亞那裏；以利亞正坐在山頂上。五十夫長對他說：「神人哪，王吩咐你下來！」","notes":[]},{"n":10,"t":"以利亞回答說：「我若是神人，願火從天上降下來，燒滅你和你那五十人！」於是有火從天上降下來，燒滅五十夫長和他那五十人。","notes":[]},{"n":11,"t":"王第二次差遣一個五十夫長，帶領五十人去見以利亞。五十夫長對以利亞說：「神人哪，王吩咐你快快下來！」","notes":[]},{"n":12,"t":"以利亞回答說：「我若是神人，願火從天上降下來，燒滅你和你那五十人！」於是神的火從天上降下來，燒滅五十夫長和他那五十人。","notes":[]},{"n":13,"t":"王第三次差遣一個五十夫長，帶領五十人去。這五十夫長上去，雙膝跪在以利亞面前，哀求他說：「神人哪，願我的性命和你這五十個僕人的性命在你眼前看為寶貴！","notes":[]},{"n":14,"t":"已經有火從天上降下來，燒滅前兩次來的五十夫長和他們各自帶的五十人；現在願我的性命在你眼前看為寶貴！」","notes":[]},{"n":15,"t":"耶和華的使者對以利亞說：「你同著他下去，不要怕他！」以利亞就起來，同著他下去見王，","notes":[]},{"n":16,"t":"對王說：「耶和華如此說：『你差人去問以革倫神巴力‧西卜，豈因以色列中沒有神可以求問嗎？所以你必不下所上的床，必定要死！』」","notes":[]},{"n":17,"t":"亞哈謝果然死了，正如耶和華藉以利亞所說的話。因他沒有兒子，他兄弟約蘭接續他作王，正在猶大王約沙法的兒子約蘭第二年。","notes":[],"heads":["亞哈謝死後約蘭繼位"]},{"n":18,"t":"亞哈謝其餘所行的事都寫在以色列諸王記上。","notes":[]}]},"2":{"heading":"以利亞被接升天","verses":[{"n":1,"t":"耶和華要用旋風接以利亞升天的時候，以利亞與以利沙從吉甲前往。","notes":[]},{"n":2,"t":"以利亞對以利沙說：「耶和華差我往伯特利去，你可以在這裏等候。」以利沙說：「我指著永生的耶和華，又敢在你面前起誓，我必不離開你。」於是二人下到伯特利。","notes":[]},{"n":3,"t":"住伯特利的先知門徒出來見以利沙，對他說：「耶和華今日要接你的師傅離開你，你知道不知道？」他說：「我知道，你們不要作聲。」","notes":[]},{"n":4,"t":"以利亞對以利沙說：「耶和華差遣我往耶利哥去，你可以在這裏等候。」以利沙說：「我指著永生的耶和華，又敢在你面前起誓，我必不離開你。」於是二人到了耶利哥。","notes":[]},{"n":5,"t":"住耶利哥的先知門徒就近以利沙，對他說：「耶和華今日要接你的師傅離開你，你知道不知道？」他說：「我知道，你們不要作聲。」","notes":[]},{"n":6,"t":"以利亞對以利沙說：「耶和華差遣我往約旦河去，你可以在這裏等候。」以利沙說：「我指著永生的耶和華，又敢在你面前起誓，我必不離開你。」於是二人一同前往。","notes":[]},{"n":7,"t":"有先知門徒去了五十人，遠遠地站在他們對面；二人在約旦河邊站住。","notes":[]},{"n":8,"t":"以利亞將自己的外衣捲起來，用以打水，水就左右分開，二人走乾地而過。","notes":[]},{"n":9,"t":"過去之後，以利亞對以利沙說：「我未曾被接去離開你，你要我為你做甚麼，只管求我。」以利沙說：「願感動你的靈加倍地感動我。」","notes":[]},{"n":10,"t":"以利亞說：「你所求的難得。雖然如此，我被接去離開你的時候，你若看見我，就必得著；不然，必得不著了。」","notes":[]},{"n":11,"t":"他們正走著說話，忽有火車火馬將二人隔開，以利亞就乘旋風升天去了。","notes":[],"heads":["以利亞乘旋風升天"]},{"n":12,"t":"以利沙看見，就呼叫說：「我父啊！我父啊！以色列的戰車馬兵啊！」以後不再見他了。於是以利沙把自己的衣服撕為兩片。","notes":[]},{"n":13,"t":"他拾起以利亞身上掉下來的外衣，回去站在約旦河邊。","notes":[]},{"n":14,"t":"他用以利亞身上掉下來的外衣打水，說：「耶和華－以利亞的神在哪裏呢？」打水之後，水也左右分開，以利沙就過來了。","notes":[]},{"n":15,"t":"住耶利哥的先知門徒從對面看見他，就說：「感動以利亞的靈感動以利沙了。」他們就來迎接他，在他面前俯伏於地，","notes":[]},{"n":16,"t":"對他說：「僕人們這裏有五十個壯士，求你容他們去尋找你師傅，或者耶和華的靈將他提起來，投在某山某谷。」以利沙說：「你們不必打發人去。」","notes":[]},{"n":17,"t":"他們再三催促他，他難以推辭，就說：「你們打發人去吧！」他們便打發五十人去，尋找了三天，也沒有找著。","notes":[]},{"n":18,"t":"以利沙仍然在耶利哥等候他們回到他那裏；他對他們說：「我豈沒有告訴你們不必去嗎？」","notes":[]},{"n":19,"t":"耶利哥城的人對以利沙說：「這城的地勢美好，我主看見了；只是水惡劣，土產不熟而落。」","notes":[],"heads":["以利沙行的神蹟"]},{"n":20,"t":"以利沙說：「你們拿一個新瓶來，裝鹽給我」；他們就拿來給他。","notes":[]},{"n":21,"t":"他出到水源，將鹽倒在水中，說：「耶和華如此說：『我治好了這水，從此必不再使人死，也不再使地土不生產。』」","notes":[]},{"n":22,"t":"於是那水治好了，直到今日，正如以利沙所說的。","notes":[]},{"n":23,"t":"以利沙從那裏上伯特利去，正上去的時候，有些童子從城裏出來，戲笑他說：「禿頭的上去吧！禿頭的上去吧！」","notes":[]},{"n":24,"t":"他回頭看見，就奉耶和華的名咒詛他們。於是有兩個母熊從林中出來，撕裂他們中間四十二個童子。","notes":[]},{"n":25,"t":"以利沙從伯特利上迦密山，又從迦密山回到撒馬利亞。","notes":[]}]},"3":{"heading":"以色列與摩押爭戰","verses":[{"n":1,"t":"猶大王約沙法十八年，亞哈的兒子約蘭在撒馬利亞登基作了以色列王十二年。","notes":[]},{"n":2,"t":"他行耶和華眼中看為惡的事，但不致像他父母所行的，因為除掉他父所造巴力的柱像。","notes":[]},{"n":3,"t":"然而，他貼近尼八的兒子耶羅波安使以色列人陷在罪裏的那罪，總不離開。","notes":[]},{"n":4,"t":"摩押王米沙牧養許多羊，每年將十萬羊羔的毛和十萬公綿羊的毛給以色列王進貢。","notes":[]},{"n":5,"t":"亞哈死後，摩押王背叛以色列王。","notes":[]},{"n":6,"t":"那時約蘭王出撒馬利亞，數點以色列眾人。","notes":[]},{"n":7,"t":"前行的時候，差人去見猶大王約沙法，說：「摩押王背叛我，你肯同我去攻打摩押嗎？」他說：「我肯上去，你我不分彼此，我的民與你的民一樣，我的馬與你的馬一樣。」","notes":[]},{"n":8,"t":"約蘭說：「我們從哪條路上去呢？」回答說：「從以東曠野的路上去。」","notes":[]},{"n":9,"t":"於是，以色列王和猶大王，並以東王，都一同去繞行七日的路程；軍隊和所帶的牲畜沒有水喝。","notes":[]},{"n":10,"t":"以色列王說：「哀哉！耶和華招聚我們這三王，乃要交在摩押人的手裏。」","notes":[]},{"n":11,"t":"約沙法說：「這裏不是有耶和華的先知嗎？我們可以託他求問耶和華。」以色列王的一個臣子回答說：「這裏有沙法的兒子以利沙，就是從前服事以利亞的。」","notes":["原文是倒水在以利亞手上的"]},{"n":12,"t":"約沙法說：「他必有耶和華的話。」於是以色列王和約沙法，並以東王都下去見他。","notes":[]},{"n":13,"t":"以利沙對以色列王說：「我與你何干？去問你父親的先知和你母親的先知吧！」以色列王對他說：「不要這樣說，耶和華招聚我們這三王，乃要交在摩押人的手裏。」","notes":[]},{"n":14,"t":"以利沙說：「我指著所事奉永生的萬軍耶和華起誓，我若不看猶大王約沙法的情面，必不理你，不顧你。","notes":[]},{"n":15,"t":"現在你們給我找一個彈琴的來。」彈琴的時候，耶和華的靈就降在以利沙身上。","notes":["原文是手"]},{"n":16,"t":"他便說：「耶和華如此說：『你們要在這谷中滿處挖溝；","notes":[]},{"n":17,"t":"因為耶和華如此說：你們雖不見風，不見雨，這谷必滿了水，使你們和牲畜有水喝。』","notes":[]},{"n":18,"t":"在耶和華眼中這還算為小事，他也必將摩押人交在你們手中。","notes":[]},{"n":19,"t":"你們必攻破一切堅城美邑，砍伐各種佳樹，塞住一切水泉，用石頭糟踏一切美田。」","notes":[]},{"n":20,"t":"次日早晨，約在獻祭的時候，有水從以東而來，遍地就滿了水。","notes":[]},{"n":21,"t":"摩押眾人聽見這三王上來要與他們爭戰，凡能頂盔貫甲的，無論老少，盡都聚集站在邊界上。","notes":[],"heads":["摩押人敗遁"]},{"n":22,"t":"次日早晨，日光照在水上，摩押人起來，看見對面水紅如血，","notes":[]},{"n":23,"t":"就說：「這是血啊！必是三王互相擊殺，俱都滅亡。摩押人哪，我們現在去搶奪財物吧！」","notes":[]},{"n":24,"t":"摩押人到了以色列營，以色列人就起來攻打他們，以致他們在以色列人面前逃跑。以色列人往前追殺摩押人，直殺入摩押的境內，","notes":[]},{"n":25,"t":"拆毀摩押的城邑，各人拋石填滿一切美田，塞住一切水泉，砍伐各種佳樹，只剩下吉珥‧哈列設的石牆；甩石的兵在四圍攻打那城。","notes":[]},{"n":26,"t":"摩押王見陣勢甚大，難以對敵，就率領七百拿刀的兵，要衝過陣去到以東王那裏，卻是不能；","notes":[]},{"n":27,"t":"便將那應當接續他作王的長子，在城上獻為燔祭。以色列人遭遇耶和華的大怒，於是三王離開摩押王，各回本國去了。","notes":["或譯：招人痛恨"]}]},"4":{"heading":"以利沙幫助一個窮寡婦","verses":[{"n":1,"t":"有一個先知門徒的妻哀求以利沙說：「你僕人－我丈夫死了，他敬畏耶和華是你所知道的。現在有債主來，要取我兩個兒子作奴僕。」","notes":[]},{"n":2,"t":"以利沙問她說：「我可以為你做甚麼呢？你告訴我，你家裏有甚麼？」她說：「婢女家中除了一瓶油之外，沒有甚麼。」","notes":[]},{"n":3,"t":"以利沙說：「你去，向你眾鄰舍借空器皿，不要少借；","notes":[]},{"n":4,"t":"回到家裏，關上門，你和你兒子在裏面將油倒在所有的器皿裏，倒滿了的放在一邊。」","notes":[]},{"n":5,"t":"於是，婦人離開以利沙去了，關上門，自己和兒子在裏面；兒子把器皿拿來，她就倒油。","notes":[]},{"n":6,"t":"器皿都滿了，她對兒子說：「再給我拿器皿來。」兒子說：「再沒有器皿了。」油就止住了。","notes":[]},{"n":7,"t":"婦人去告訴神人，神人說：「你去賣油還債，所剩的你和你兒子可以靠著度日。」","notes":[]},{"n":8,"t":"一日，以利沙走到書念，在那裏有一個大戶的婦人強留他吃飯。此後，以利沙每從那裏經過就進去吃飯。","notes":[],"heads":["書念婦人接待以利沙"]},{"n":9,"t":"婦人對丈夫說：「我看出那常從我們這裏經過的是聖潔的神人。","notes":[]},{"n":10,"t":"我們可以為他在牆上蓋一間小樓，在其中安放床榻、桌子、椅子、燈臺，他來到我們這裏，就可以住在其間。」","notes":[]},{"n":11,"t":"一日，以利沙來到那裏，就進了那樓躺臥。","notes":[]},{"n":12,"t":"以利沙吩咐僕人基哈西說：「你叫這書念婦人來。」他就把婦人叫了來，婦人站在以利沙面前。","notes":[]},{"n":13,"t":"以利沙吩咐僕人說：「你對她說：你既為我們費了許多心思，可以為你做甚麼呢？你向王或元帥有所求的沒有？」她回答說：「我在我本鄉安居無事。」","notes":[]},{"n":14,"t":"以利沙對僕人說：「究竟當為她做甚麼呢？」基哈西說：「她沒有兒子，她丈夫也老了。」","notes":[]},{"n":15,"t":"以利沙說：「再叫她來。」於是叫了她來，她就站在門口。","notes":[]},{"n":16,"t":"以利沙說：「明年到這時候，你必抱一個兒子。」她說：「神人，我主啊，不要那樣欺哄婢女。」","notes":[]},{"n":17,"t":"婦人果然懷孕，到了那時候，生了一個兒子，正如以利沙所說的。","notes":[]},{"n":18,"t":"孩子漸漸長大，一日到他父親和收割的人那裏，","notes":[]},{"n":19,"t":"他對父親說：「我的頭啊，我的頭啊！」他父親對僕人說：「把他抱到他母親那裏。」","notes":[]},{"n":20,"t":"僕人抱去，交給他母親；孩子坐在母親的膝上，到晌午就死了。","notes":[]},{"n":21,"t":"他母親抱他上了樓，將他放在神人的床上，關上門出來，","notes":[]},{"n":22,"t":"呼叫她丈夫說：「你叫一個僕人給我牽一匹驢來，我要快快地去見神人，就回來。」","notes":[]},{"n":23,"t":"丈夫說：「今日不是月朔，也不是安息日，你為何要去見他呢？」婦人說：「平安無事。」","notes":[]},{"n":24,"t":"於是備上驢，對僕人說：「你快快趕著走，我若不吩咐你，就不要遲慢。」","notes":[]},{"n":25,"t":"婦人就往迦密山去見神人。神人遠遠地看見她，對僕人基哈西說：「看哪，書念的婦人來了！","notes":[]},{"n":26,"t":"你跑去迎接她，問她說：你平安嗎？你丈夫平安嗎？孩子平安嗎？」她說：「平安。」","notes":[]},{"n":27,"t":"婦人上了山，到神人那裏，就抱住神人的腳。基哈西前來要推開她，神人說：「由她吧！因為她心裏愁苦，耶和華向我隱瞞，沒有指示我。」","notes":[]},{"n":28,"t":"婦人說：「我何嘗向我主求過兒子呢？我豈沒有說過，不要欺哄我嗎？」","notes":[]},{"n":29,"t":"以利沙吩咐基哈西說：「你束上腰，手拿我的杖前去；若遇見人，不要向他問安；人若向你問安，也不要回答；要把我的杖放在孩子臉上。」","notes":[]},{"n":30,"t":"孩子的母親說：「我指著永生的耶和華，又敢在你面前起誓，我必不離開你。」於是以利沙起身，隨著她去了。","notes":[]},{"n":31,"t":"基哈西先去，把杖放在孩子臉上，卻沒有聲音，也沒有動靜。基哈西就迎著以利沙回來，告訴他說：「孩子還沒有醒過來。」","notes":[]},{"n":32,"t":"以利沙來到，進了屋子，看見孩子死了，放在自己的床上。","notes":[]},{"n":33,"t":"他就關上門，只有自己和孩子在裏面，他便祈禱耶和華，","notes":[]},{"n":34,"t":"上床伏在孩子身上，口對口，眼對眼，手對手；既伏在孩子身上，孩子的身體就漸漸溫和了。","notes":[]},{"n":35,"t":"然後他下來，在屋裏來往走了一趟，又上去伏在孩子身上，孩子打了七個噴嚏，就睜開眼睛了。","notes":[]},{"n":36,"t":"以利沙叫基哈西說：「你叫這書念婦人來」；於是叫了她來。以利沙說：「將你兒子抱起來。」","notes":[]},{"n":37,"t":"婦人就進來，在以利沙腳前俯伏於地，抱起她兒子出去了。","notes":[]},{"n":38,"t":"以利沙又來到吉甲，那地正有饑荒。先知門徒坐在他面前，他吩咐僕人說：「你將大鍋放在火上，給先知門徒熬湯。」","notes":[],"heads":["兩件神蹟"]},{"n":39,"t":"有一個人去到田野掐菜，遇見一棵野瓜籐，就摘了一兜野瓜回來，切了擱在熬湯的鍋中，因為他們不知道是甚麼東西；","notes":[]},{"n":40,"t":"倒出來給眾人吃，吃的時候，都喊叫說：「神人哪，鍋中有致死的毒物！」所以眾人不能吃了。","notes":[]},{"n":41,"t":"以利沙說：「拿點麵來」，就把麵撒在鍋中，說：「倒出來，給眾人吃吧！」鍋中就沒有毒了。","notes":[]},{"n":42,"t":"有一個人從巴力‧沙利沙來，帶著初熟大麥做的餅二十個，並新穗子，裝在口袋裏送給神人。神人說：「把這些給眾人吃。」","notes":[]},{"n":43,"t":"僕人說：「這一點豈可擺給一百人吃呢？」以利沙說：「你只管給眾人吃吧！因為耶和華如此說，眾人必吃了，還剩下。」","notes":[]},{"n":44,"t":"僕人就擺在眾人面前，他們吃了，果然還剩下，正如耶和華所說的。","notes":[]}]},"5":{"heading":"乃縵得醫治","verses":[{"n":1,"t":"亞蘭王的元帥乃縵在他主人面前為尊為大，因耶和華曾藉他使亞蘭人得勝；他又是大能的勇士，只是長了大痲瘋。","notes":[]},{"n":2,"t":"先前亞蘭人成群地出去，從以色列國擄了一個小女子，這女子就服事乃縵的妻。","notes":[]},{"n":3,"t":"她對主母說：「巴不得我主人去見撒馬利亞的先知，必能治好他的大痲瘋。」","notes":[]},{"n":4,"t":"乃縵進去，告訴他主人說，以色列國的女子如此如此說。","notes":[]},{"n":5,"t":"亞蘭王說：「你可以去，我也達信於以色列王。」於是乃縵帶銀子十他連得，金子六千舍客勒，衣裳十套，就去了；","notes":[]},{"n":6,"t":"且帶信給以色列王，信上說：「我打發臣僕乃縵去見你，你接到這信，就要治好他的大痲瘋。」","notes":[]},{"n":7,"t":"以色列王看了信就撕裂衣服，說：「我豈是神，能使人死使人活呢？這人竟打發人來，叫我治好他的大痲瘋。你們看一看，這人何以尋隙攻擊我呢？」","notes":[]},{"n":8,"t":"神人以利沙聽見以色列王撕裂衣服，就打發人去見王，說：「你為甚麼撕了衣服呢？可使那人到我這裏來，他就知道以色列中有先知了。」","notes":[]},{"n":9,"t":"於是，乃縵帶著車馬到了以利沙的家，站在門前。","notes":[]},{"n":10,"t":"以利沙打發一個使者，對乃縵說：「你去在約旦河中沐浴七回，你的肉就必復原，而得潔淨。」","notes":[]},{"n":11,"t":"乃縵卻發怒走了，說：「我想他必定出來見我，站著求告耶和華－他神的名，在患處以上搖手，治好這大痲瘋。","notes":[]},{"n":12,"t":"大馬士革的河亞罷拿和法珥法豈不比以色列的一切水更好嗎？我在那裏沐浴不得潔淨嗎？」於是氣忿忿地轉身去了。","notes":[]},{"n":13,"t":"他的僕人進前來，對他說：「我父啊，先知若吩咐你做一件大事，你豈不做嗎？何況說你去沐浴而得潔淨呢？」","notes":[]},{"n":14,"t":"於是乃縵下去，照著神人的話，在約旦河裏沐浴七回；他的肉復原，好像小孩子的肉，他就潔淨了。","notes":[]},{"n":15,"t":"乃縵帶著一切跟隨他的人，回到神人那裏，站在他面前，說：「如今我知道，除了以色列之外，普天下沒有神。現在求你收點僕人的禮物。」","notes":[]},{"n":16,"t":"以利沙說：「我指著所事奉永生的耶和華起誓，我必不受。」乃縵再三地求他，他卻不受。","notes":[]},{"n":17,"t":"乃縵說：「你若不肯受，請將兩騾子馱的土賜給僕人。從今以後，僕人必不再將燔祭或平安祭獻與別神，只獻給耶和華。","notes":[]},{"n":18,"t":"惟有一件事，願耶和華饒恕你僕人：我主人進臨門廟叩拜的時候，我用手攙他在臨門廟，我也屈身。我在臨門廟屈身的這事，願耶和華饒恕我。」","notes":[]},{"n":19,"t":"以利沙對他說：「你可以平平安安地回去！」乃縵就離開他去了；走了不遠，","notes":[]},{"n":20,"t":"神人以利沙的僕人基哈西心裏說：「我主人不願從這亞蘭人乃縵手裏受他帶來的禮物，我指著永生的耶和華起誓，我必跑去追上他，向他要些。」","notes":[]},{"n":21,"t":"於是基哈西追趕乃縵。乃縵看見有人追趕，就急忙下車迎著他，說：「都平安嗎？」","notes":[]},{"n":22,"t":"說：「都平安。我主人打發我來說：『剛才有兩個少年人，是先知門徒，從以法蓮山地來見我，請你賜他們一他連得銀子，兩套衣裳。』」","notes":[]},{"n":23,"t":"乃縵說：「請受二他連得」；再三地請受，便將二他連得銀子裝在兩個口袋裏，又將兩套衣裳交給兩個僕人；他們就在基哈西前頭抬著走。","notes":[]},{"n":24,"t":"到了山岡，基哈西從他們手中接過來，放在屋裏，打發他們回去。","notes":[]},{"n":25,"t":"基哈西進去，站在他主人面前。以利沙問他說：「基哈西你從哪裏來？」回答說：「僕人沒有往哪裏去。」","notes":[]},{"n":26,"t":"以利沙對他說：「那人下車轉回迎你的時候，我的心豈沒有去呢？這豈是受銀子、衣裳、買橄欖園、葡萄園、牛羊、僕婢的時候呢？","notes":[]},{"n":27,"t":"因此，乃縵的大痲瘋必沾染你和你的後裔，直到永遠。」基哈西從以利沙面前退出去，就長了大痲瘋，像雪那樣白。","notes":[]}]},"6":{"heading":"找回斧子的頭","verses":[{"n":1,"t":"先知門徒對以利沙說：「看哪，我們同你所住的地方過於窄小，","notes":[]},{"n":2,"t":"求你容我們往約旦河去，各人從那裏取一根木料建造房屋居住。」他說：「你們去吧！」","notes":[]},{"n":3,"t":"有一人說：「求你與僕人同去。」回答說：「我可以去。」","notes":[]},{"n":4,"t":"於是以利沙與他們同去。到了約旦河，就砍伐樹木。","notes":[]},{"n":5,"t":"有一人砍樹的時候，斧頭掉在水裏，他就呼叫說：「哀哉！我主啊，這斧子是借的。」","notes":[]},{"n":6,"t":"神人問說：「掉在哪裏了？」他將那地方指給以利沙看。以利沙砍了一根木頭，拋在水裏，斧頭就漂上來了。","notes":[]},{"n":7,"t":"以利沙說：「拿起來吧！」那人就伸手拿起來了。","notes":[]},{"n":8,"t":"亞蘭王與以色列人爭戰，和他的臣僕商議說：「我要在某處某處安營。」","notes":[],"heads":["亞蘭軍敗於以色列人"]},{"n":9,"t":"神人打發人去見以色列王，說：「你要謹慎，不要從某處經過，因為亞蘭人從那裏下來了。」","notes":[]},{"n":10,"t":"以色列王差人去窺探神人所告訴所警戒他去的地方，就防備未受其害，不止一兩次。","notes":[]},{"n":11,"t":"亞蘭王因這事心裏驚疑，召了臣僕來，對他們說：「我們這裏有誰幫助以色列王，你們不指給我嗎？」","notes":[]},{"n":12,"t":"有一個臣僕說：「我主，我王！無人幫助他，只有以色列中的先知以利沙，將王在臥房所說的話告訴以色列王了。」","notes":[]},{"n":13,"t":"王說：「你們去探他在哪裏，我好打發人去捉拿他。」有人告訴王說：「他在多坍。」","notes":[]},{"n":14,"t":"王就打發車馬和大軍往那裏去，夜間到了，圍困那城。","notes":[]},{"n":15,"t":"神人的僕人清早起來出去，看見車馬軍兵圍困了城。僕人對神人說：「哀哉！我主啊，我們怎樣行才好呢？」","notes":[]},{"n":16,"t":"神人說：「不要懼怕！與我們同在的比與他們同在的更多。」","notes":[]},{"n":17,"t":"以利沙禱告說：「耶和華啊，求你開這少年人的眼目，使他能看見。」耶和華開他的眼目，他就看見滿山有火車火馬圍繞以利沙。","notes":[]},{"n":18,"t":"敵人下到以利沙那裏，以利沙禱告耶和華說：「求你使這些人的眼目昏迷。」耶和華就照以利沙的話，使他們的眼目昏迷。","notes":[]},{"n":19,"t":"以利沙對他們說：「這不是那道，也不是那城；你們跟我去，我必領你們到所尋找的人那裏。」於是領他們到了撒馬利亞。","notes":[]},{"n":20,"t":"他們進了撒馬利亞，以利沙禱告說：「耶和華啊，求你開這些人的眼目，使他們能看見。」耶和華開他們的眼目，他們就看見了，不料，是在撒馬利亞的城中。","notes":[]},{"n":21,"t":"以色列王見了他們，就問以利沙說：「我父啊，我可以擊殺他們嗎？」","notes":[]},{"n":22,"t":"回答說：「不可擊殺他們！就是你用刀用弓擄來的，豈可擊殺他們嗎？當在他們面前設擺飲食，使他們吃喝回到他們的主人那裏。」","notes":["或譯：也不可擊殺，何況這些人呢"]},{"n":23,"t":"王就為他們預備了許多食物；他們吃喝完了，打發他們回到他們主人那裏。從此，亞蘭軍不再犯以色列境了。","notes":[]},{"n":24,"t":"此後，亞蘭王便‧哈達聚集他的全軍，上來圍困撒馬利亞。","notes":[],"heads":["圍困撒馬利亞"]},{"n":25,"t":"於是撒馬利亞被圍困，有饑荒，甚至一個驢頭值銀八十舍客勒，二升鴿子糞值銀五舍客勒。","notes":[]},{"n":26,"t":"一日，以色列王在城上經過，有一個婦人向他呼叫說：「我主，我王啊！求你幫助。」","notes":[]},{"n":27,"t":"王說：「耶和華不幫助你，我從何處幫助你？是從禾場，是從酒醡呢？」","notes":[]},{"n":28,"t":"王問婦人說：「你有甚麼苦處？」她回答說：「這婦人對我說：『將你的兒子取來，我們今日可以吃，明日可以吃我的兒子。』","notes":[]},{"n":29,"t":"我們就煮了我的兒子吃了。次日我對她說：『要將你的兒子取來，我們可以吃。』她卻將她的兒子藏起來了。」","notes":[]},{"n":30,"t":"王聽見婦人的話，就撕裂衣服；（王在城上經過）百姓看見王貼身穿著麻衣。","notes":[]},{"n":31,"t":"王說：「我今日若容沙法的兒子以利沙的頭仍在他項上，願神重重地降罰與我！」","notes":[]},{"n":32,"t":"那時，以利沙正坐在家中，長老也與他同坐。王打發一個伺候他的人去；他還沒有到，以利沙對長老說：「你們看這兇手之子，打發人來斬我的頭；你們看著使者來到，就關上門，用門將他推出去。在他後頭不是有他主人腳步的響聲嗎？」","notes":[]},{"n":33,"t":"正說話的時候，使者來到，王也到了，說：「這災禍是從耶和華那裏來的，我何必再仰望耶和華呢？」","notes":[]}]},"7":{"heading":"亞蘭軍棄營逃命","verses":[{"n":1,"t":"以利沙說：「你們要聽耶和華的話，耶和華如此說：明日約到這時候，在撒馬利亞城門口，一細亞細麵要賣銀一舍客勒，二細亞大麥也要賣銀一舍客勒。」","notes":[]},{"n":2,"t":"有一個攙扶王的軍長對神人說：「即便耶和華使天開了窗戶，也不能有這事。」以利沙說：「你必親眼看見，卻不得吃。」","notes":[]},{"n":3,"t":"在城門那裏有四個長大痲瘋的人，他們彼此說：「我們為何坐在這裏等死呢？","notes":[]},{"n":4,"t":"我們若說，進城去吧！城裏有饑荒，必死在那裏；若在這裏坐著不動，也必是死。來吧，我們去投降亞蘭人的軍隊，他們若留我們的活命，就活著；若殺我們，就死了吧！」","notes":[]},{"n":5,"t":"黃昏的時候，他們起來往亞蘭人的營盤去；到了營邊，不見一人在那裏。","notes":[]},{"n":6,"t":"因為主使亞蘭人的軍隊聽見車馬的聲音，是大軍的聲音；他們就彼此說：「這必是以色列王賄買赫人的諸王和埃及人的諸王來攻擊我們。」","notes":[]},{"n":7,"t":"所以，在黃昏的時候他們起來逃跑，撇下帳棚、馬、驢，營盤照舊，只顧逃命。","notes":[]},{"n":8,"t":"那些長大痲瘋的到了營邊，進了帳棚，吃了喝了，且從其中拿出金銀和衣服來，去收藏了；回來又進了一座帳棚，從其中拿出財物來去收藏了。","notes":[]},{"n":9,"t":"那時，他們彼此說：「我們所做的不好！今日是有好信息的日子，我們竟不作聲！若等到天亮，罪必臨到我們。來吧，我們與王家報信去！」","notes":[]},{"n":10,"t":"他們就去叫守城門的，告訴他們說：「我們到了亞蘭人的營，不見一人在那裏，也無人聲，只有拴著的馬和驢，帳棚都照舊。」","notes":[]},{"n":11,"t":"守城門的叫了眾守門的人來，他們就進去與王家報信。","notes":[]},{"n":12,"t":"王夜間起來，對臣僕說：「我告訴你們亞蘭人向我們如何行。他們知道我們飢餓，所以離營，埋伏在田野，說：『以色列人出城的時候，我們就活捉他們，得以進城。』」","notes":[]},{"n":13,"t":"有一個臣僕對王說：「我們不如用城裏剩下之馬中的五匹馬（馬和城裏剩下的以色列人都是一樣，快要滅絕），打發人去窺探。」","notes":[]},{"n":14,"t":"於是取了兩輛車和馬，王差人去追尋亞蘭軍，說：「你們去窺探窺探。」","notes":[]},{"n":15,"t":"他們就追尋到約旦河，看見滿道上都是亞蘭人急跑時丟棄的衣服器具，使者就回來報告王。","notes":[]},{"n":16,"t":"眾人就出去，擄掠亞蘭人的營盤。於是一細亞細麵賣銀一舍客勒，二細亞大麥也賣銀一舍客勒，正如耶和華所說的。","notes":[]},{"n":17,"t":"王派攙扶他的那軍長在城門口彈壓，眾人在那裏將他踐踏，他就死了，正如神人在王下來見他的時候所說的。","notes":[]},{"n":18,"t":"神人曾對王說：「明日約到這時候，在撒馬利亞城門口，二細亞大麥要賣銀一舍客勒，一細亞細麵也要賣銀一舍客勒。」","notes":[]},{"n":19,"t":"那軍長對神人說：「即便耶和華使天開了窗戶，也不能有這事。」神人說：「你必親眼看見，卻不得吃。」","notes":[]},{"n":20,"t":"這話果然應驗在他身上；因為眾人在城門口將他踐踏，他就死了。","notes":[]}]},"8":{"heading":"書念的婦人回原住地","verses":[{"n":1,"t":"以利沙曾對所救活之子的那婦人說：「你和你的全家要起身往你可住的地方去住，因為耶和華命饑荒降在這地七年。」","notes":[]},{"n":2,"t":"婦人就起身，照神人的話帶著全家往非利士地去，住了七年。","notes":[]},{"n":3,"t":"七年完了，那婦人從非利士地回來，就出去為自己的房屋田地哀告王。","notes":[]},{"n":4,"t":"那時王正與神人的僕人基哈西說：「請你將以利沙所行的一切大事告訴我。」","notes":[]},{"n":5,"t":"基哈西告訴王以利沙如何使死人復活，恰巧以利沙所救活、她兒子的那婦人為自己的房屋田地來哀告王。基哈西說：「我主我王，這就是那婦人，這是她的兒子，就是以利沙所救活的。」","notes":[]},{"n":6,"t":"王問那婦人，她就把那事告訴王。於是王為她派一個太監，說：「凡屬這婦人的都還給她，自從她離開本地直到今日，她田地的出產也都還給她。」","notes":[]},{"n":7,"t":"以利沙來到大馬士革，亞蘭王便‧哈達正患病。有人告訴王說：「神人來到這裏了。」","notes":[],"heads":["以利沙和便‧哈達王"]},{"n":8,"t":"王就吩咐哈薛說：「你帶著禮物去見神人，託他求問耶和華，我這病能好不能好？」","notes":[]},{"n":9,"t":"於是哈薛用四十個駱駝，馱著大馬士革的各樣美物為禮物，去見以利沙。到了他那裏，站在他面前，說：「你兒子亞蘭王便‧哈達打發我來見你，他問說：『我這病能好不能好？』」","notes":[]},{"n":10,"t":"以利沙對哈薛說：「你回去告訴他說，這病必能好；但耶和華指示我，他必要死。」","notes":[]},{"n":11,"t":"神人定睛看著哈薛，甚至他慚愧。神人就哭了；","notes":[]},{"n":12,"t":"哈薛說：「我主為甚麼哭？」回答說：「因為我知道你必苦害以色列人，用火焚燒他們的保障，用刀殺死他們的壯丁，摔死他們的嬰孩，剖開他們的孕婦。」","notes":[]},{"n":13,"t":"哈薛說：「你僕人算甚麼，不過是一條狗，焉能行這大事呢？」以利沙回答說：「耶和華指示我，你必作亞蘭王。」","notes":[]},{"n":14,"t":"哈薛離開以利沙，回去見他的主人。主人問他說：「以利沙對你說甚麼？」回答說：「他告訴我你必能好。」","notes":[]},{"n":15,"t":"次日，哈薛拿被窩浸在水中，蒙住王的臉，王就死了。於是哈薛篡了他的位。","notes":[]},{"n":16,"t":"以色列王亞哈的兒子約蘭第五年，猶大王約沙法還在位的時候，約沙法的兒子約蘭登基作了猶大王。","notes":[],"heads":["猶大王約蘭"]},{"n":17,"t":"約蘭登基的時候年三十二歲，在耶路撒冷作王八年。","notes":[]},{"n":18,"t":"他行以色列諸王所行的，與亞哈家一樣；因為他娶了亞哈的女兒為妻，行耶和華眼中看為惡的事。","notes":[]},{"n":19,"t":"耶和華卻因他僕人大衛的緣故，仍不肯滅絕猶大，照他所應許大衛的話，永遠賜燈光與他的子孫。","notes":[]},{"n":20,"t":"約蘭年間，以東人背叛猶大，脫離他的權下，自己立王。","notes":[]},{"n":21,"t":"約蘭率領所有的戰車往撒益去，夜間起來，攻打圍困他的以東人和車兵長；猶大兵就逃跑，各回各家去了。","notes":[]},{"n":22,"t":"這樣，以東人背叛猶大，脫離他的權下，直到今日。那時立拿人也背叛了。","notes":[]},{"n":23,"t":"約蘭其餘的事，凡他所行的，都寫在猶大列王記上。","notes":[]},{"n":24,"t":"約蘭與他列祖同睡，葬在大衛城他列祖的墳地裏。他兒子亞哈謝接續他作王。","notes":[]},{"n":25,"t":"以色列王亞哈的兒子約蘭十二年，猶大王約蘭的兒子亞哈謝登基。","notes":[],"heads":["猶大王亞哈謝"]},{"n":26,"t":"他登基的時候年二十二歲，在耶路撒冷作王一年。他母親名叫亞她利雅，是以色列王暗利的孫女。","notes":[]},{"n":27,"t":"亞哈謝效法亞哈家行耶和華眼中看為惡的事，與亞哈家一樣，因為他是亞哈家的女婿。","notes":[]},{"n":28,"t":"他與亞哈的兒子約蘭同往基列的拉末去，與亞蘭王哈薛爭戰。亞蘭人打傷了約蘭，","notes":[]},{"n":29,"t":"約蘭王回到耶斯列，醫治在拉末與亞蘭王哈薛打仗的時候所受的傷。猶大王約蘭的兒子亞哈謝因為亞哈的兒子約蘭病了，就下到耶斯列看望他。","notes":[]}]},"9":{"heading":"耶戶被膏立為以色列王","verses":[{"n":1,"t":"先知以利沙叫了一個先知門徒來，吩咐他說：「你束上腰，手拿這瓶膏油往基列的拉末去。","notes":[]},{"n":2,"t":"到了那裏，要尋找寧示的孫子、約沙法的兒子耶戶，使他從同僚中起來，帶他進嚴密的屋子，","notes":[]},{"n":3,"t":"將瓶裏的膏油倒在他頭上，說：『耶和華如此說：我膏你作以色列王。』說完了，就開門逃跑，不要遲延。」","notes":[]},{"n":4,"t":"於是那少年先知往基列的拉末去了。","notes":[]},{"n":5,"t":"到了那裏，看見眾軍長都坐著，就說：「將軍哪，我有話對你說。」耶戶說：「我們眾人裏，你要對哪一個說呢？」回答說：「將軍哪，我要對你說。」","notes":[]},{"n":6,"t":"耶戶就起來，進了屋子，少年人將膏油倒在他頭上，對他說：「耶和華－以色列的神如此說：『我膏你作耶和華民以色列的王。","notes":[]},{"n":7,"t":"你要擊殺你主人亞哈的全家，我好在耶洗別身上伸我僕人眾先知和耶和華一切僕人流血的冤。","notes":[]},{"n":8,"t":"亞哈全家必都滅亡，凡屬亞哈的男丁，無論是困住的、自由的，我必從以色列中剪除，","notes":[]},{"n":9,"t":"使亞哈的家像尼八兒子耶羅波安的家，又像亞希雅兒子巴沙的家。","notes":[]},{"n":10,"t":"耶洗別必在耶斯列田裏被狗所吃，無人葬埋。』」說完了，少年人就開門逃跑了。","notes":[]},{"n":11,"t":"耶戶出來，回到他主人的臣僕那裏，有一人問他說：「平安嗎？這狂妄的人來見你有甚麼事呢？」回答說：「你們認得那人，也知道他說甚麼。」","notes":[]},{"n":12,"t":"他們說：「這是假話，你據實地告訴我們。」回答說：「他如此如此對我說。他說：『耶和華如此說：我膏你作以色列王。』」","notes":[]},{"n":13,"t":"他們就急忙各將自己的衣服鋪在上層臺階，使耶戶坐在其上；他們吹角，說：「耶戶作王了！」","notes":[]},{"n":14,"t":"這樣，寧示的孫子、約沙法的兒子耶戶背叛約蘭。先是約蘭和以色列眾人因為亞蘭王哈薛的緣故，把守基列的拉末；","notes":[],"heads":["以色列王約蘭被殺"]},{"n":15,"t":"但約蘭王回到耶斯列，醫治與亞蘭王哈薛打仗所受的傷。耶戶說：「若合你們的意思，就不容人逃出城往耶斯列報信去。」","notes":[]},{"n":16,"t":"於是耶戶坐車往耶斯列去，因為約蘭病臥在那裏。猶大王亞哈謝已經下去看望他。","notes":[]},{"n":17,"t":"有一個守望的人站在耶斯列的樓上，看見耶戶帶著一群人來，就說：「我看見一群人。」約蘭說：「打發一個騎馬的去迎接他們，問說：平安不平安？」","notes":[]},{"n":18,"t":"騎馬的就去迎接耶戶，說：「王問說，平安不平安？」耶戶說：「平安不平安與你何干？你轉在我後頭吧！」守望的人又說：「使者到了他們那裏，卻不回來。」","notes":[]},{"n":19,"t":"王又打發一個騎馬的去。這人到了他們那裏，說：「王問說，平安不平安？」耶戶說：「平安不平安與你何干？你轉在我後頭吧！」","notes":[]},{"n":20,"t":"守望的人又說：「他到了他們那裏，也不回來；車趕得甚猛，像寧示的孫子耶戶的趕法。」","notes":[]},{"n":21,"t":"約蘭吩咐說：「套車！」人就給他套車。以色列王約蘭和猶大王亞哈謝各坐自己的車出去迎接耶戶，在耶斯列人拿伯的田那裏遇見他。","notes":[]},{"n":22,"t":"約蘭見耶戶就說：「耶戶啊，平安嗎？」耶戶說：「你母親耶洗別的淫行邪術這樣多，焉能平安呢？」","notes":[]},{"n":23,"t":"約蘭就轉車逃跑，對亞哈謝說：「亞哈謝啊，反了！」","notes":[]},{"n":24,"t":"耶戶開滿了弓，射中約蘭的脊背，箭從心窩穿出，約蘭就仆倒在車上。","notes":[]},{"n":25,"t":"耶戶對他的軍長畢甲說：「你把他拋在耶斯列人拿伯的田間。你當追想，你我一同坐車跟隨他父亞哈的時候，耶和華對亞哈所說的預言，","notes":[]},{"n":26,"t":"說：『我昨日看見拿伯的血和他眾子的血，我必在這塊田上報應你。』這是耶和華說的，現在你要照著耶和華的話，把他拋在這田間。」","notes":[]},{"n":27,"t":"猶大王亞哈謝見這光景，就從園亭之路逃跑。耶戶追趕他，說：「把這人也殺在車上。」到了靠近以伯蓮的姑珥坡上擊傷了他。他逃到米吉多，就死在那裏。","notes":[],"heads":["猶大王亞哈謝被殺"]},{"n":28,"t":"他的臣僕用車將他的屍首送到耶路撒冷，葬在大衛城他自己的墳墓裏，與他列祖同葬。","notes":[]},{"n":29,"t":"亞哈謝登基作猶大王的時候，是在亞哈的兒子約蘭第十一年。","notes":[]},{"n":30,"t":"耶戶到了耶斯列；耶洗別聽見就擦粉、梳頭，從窗戶裏往外觀看。","notes":[],"heads":["耶洗別王后被殺"]},{"n":31,"t":"耶戶進門的時候，耶洗別說：「殺主人的心利啊，平安嗎？」","notes":[]},{"n":32,"t":"耶戶抬頭向窗戶觀看，說：「誰順從我？」有兩三個太監從窗戶往外看他。","notes":[]},{"n":33,"t":"耶戶說：「把她扔下來！」他們就把她扔下來。她的血濺在牆上和馬上；於是把她踐踏了。","notes":[]},{"n":34,"t":"耶戶進去，吃了喝了，吩咐說：「你們把這被咒詛的婦人葬埋了，因為她是王的女兒。」","notes":[]},{"n":35,"t":"他們就去葬埋她，只尋得她的頭骨和腳，並手掌。","notes":[]},{"n":36,"t":"他們回去告訴耶戶，耶戶說：「這正應驗耶和華藉他僕人提斯比人以利亞所說的話，說：『在耶斯列田間，狗必吃耶洗別的肉；","notes":[]},{"n":37,"t":"耶洗別的屍首必在耶斯列田間如同糞土，甚至人不能說這是耶洗別。』」","notes":[]}]},"10":{"heading":"耶戶寫信給耶斯列首領","verses":[{"n":1,"t":"亞哈有七十個兒子在撒馬利亞。耶戶寫信送到撒馬利亞，通知耶斯列的首領，就是長老和教養亞哈眾子的人，說：","notes":[]},{"n":2,"t":"「你們那裏既有你們主人的眾子和車馬、器械、堅固城，","notes":[]},{"n":3,"t":"接了這信，就可以在你們主人的眾子中選擇一個賢能合宜的，使他坐他父親的位，你們也可以為你們主人的家爭戰。」","notes":[]},{"n":4,"t":"他們卻甚懼怕，彼此說：「二王在他面前尚且站立不住，我們怎能站得住呢？」","notes":[]},{"n":5,"t":"家宰、邑宰，和長老，並教養眾子的人，打發人去見耶戶，說：「我們是你的僕人，凡你所吩咐我們的都必遵行，我們不立誰作王，你看怎樣好就怎樣行。」","notes":[]},{"n":6,"t":"耶戶又給他們寫信說：「你們若歸順我，聽從我的話，明日這時候，要將你們主人眾子的首級帶到耶斯列來見我。」那時王的兒子七十人都住在教養他們那城中的尊貴人家裏。","notes":[],"heads":["亞哈眾子被殺"]},{"n":7,"t":"信一到，他們就把王的七十個兒子殺了，將首級裝在筐裏，送到在耶斯列的耶戶那裏。","notes":[]},{"n":8,"t":"有使者來告訴耶戶說：「他們將王眾子的首級送來了。」耶戶說：「將首級在城門口堆作兩堆，擱到明日。」","notes":[]},{"n":9,"t":"次日早晨，耶戶出來，站著對眾民說：「你們都是公義的，我背叛我主人，將他殺了；這些人卻是誰殺的呢？","notes":[]},{"n":10,"t":"由此可知，耶和華指著亞哈家所說的話一句沒有落空，因為耶和華藉他僕人以利亞所說的話都成就了。」","notes":[]},{"n":11,"t":"凡亞哈家在耶斯列所剩下的人和他的大臣、密友、祭司，耶戶盡都殺了，沒有留下一個。","notes":[]},{"n":12,"t":"耶戶起身往撒馬利亞去。在路上、牧人剪羊毛之處，","notes":[],"heads":["亞哈謝的兄弟被殺"]},{"n":13,"t":"遇見猶大王亞哈謝的弟兄，問他們說：「你們是誰？」回答說：「我們是亞哈謝的弟兄，現在下去要問王和太后的眾子安。」","notes":[]},{"n":14,"t":"耶戶吩咐說：「活捉他們！」跟從的人就活捉了他們，將他們殺在剪羊毛之處的坑邊，共四十二人，沒有留下一個。","notes":[]},{"n":15,"t":"耶戶從那裏前行，恰遇利甲的兒子約拿達來迎接他，耶戶問他安，對他說：「你誠心待我像我誠心待你嗎？」約拿達回答說：「是。」耶戶說：「若是這樣，你向我伸手」，他就伸手；耶戶拉他上車。","notes":[],"heads":["亞哈家剩下的人被殺"]},{"n":16,"t":"耶戶說：「你和我同去，看我為耶和華怎樣熱心」；於是請他坐在車上，","notes":[]},{"n":17,"t":"到了撒馬利亞，就把撒馬利亞的亞哈家剩下的人都殺了，直到滅盡，正如耶和華對以利亞所說的。","notes":[]},{"n":18,"t":"耶戶招聚眾民，對他們說：「亞哈事奉巴力還冷淡，耶戶卻更熱心。","notes":[],"heads":["拜巴力的人被殺"]},{"n":19,"t":"現在我要給巴力獻大祭。應當叫巴力的眾先知和一切拜巴力的人，並巴力的眾祭司，都到我這裏來，不可缺少一個；凡不來的必不得活。」耶戶這樣行，是用詭計要殺盡拜巴力的人。","notes":[]},{"n":20,"t":"耶戶說：「要為巴力宣告嚴肅會！」於是宣告了。","notes":[]},{"n":21,"t":"耶戶差人走遍以色列地；凡拜巴力的人都來齊了，沒有一個不來的。他們進了巴力廟，巴力廟中從前邊直到後邊都滿了人。","notes":[]},{"n":22,"t":"耶戶吩咐掌管禮服的人說：「拿出禮服來，給一切拜巴力的人穿。」他就拿出禮服來給了他們。","notes":[]},{"n":23,"t":"耶戶和利甲的兒子約拿達進了巴力廟，對拜巴力的人說：「你們察看察看，在你們這裏不可有耶和華的僕人，只可容留拜巴力的人。」","notes":[]},{"n":24,"t":"耶戶和約拿達進去，獻平安祭和燔祭。耶戶先安派八十人在廟外，吩咐說：「我將這些人交在你們手中，若有一人脫逃，誰放的必叫他償命！」","notes":[]},{"n":25,"t":"耶戶獻完了燔祭，就出來吩咐護衛兵和眾軍長說：「你們進去殺他們，不容一人出來！」護衛兵和軍長就用刀殺他們，將屍首拋出去，便到巴力廟的城去了，","notes":[]},{"n":26,"t":"將巴力廟中的柱像都拿出來燒了；","notes":[]},{"n":27,"t":"毀壞了巴力柱像，拆毀了巴力廟作為廁所，直到今日。","notes":[]},{"n":28,"t":"這樣，耶戶在以色列中滅了巴力。","notes":[]},{"n":29,"t":"只是耶戶不離開尼八的兒子耶羅波安使以色列人陷在罪裏的那罪，就是拜伯特利和但的金牛犢。","notes":[]},{"n":30,"t":"耶和華對耶戶說：「因你辦好我眼中看為正的事，照我的心意待亞哈家，你的子孫必接續你坐以色列的國位，直到四代。」","notes":[]},{"n":31,"t":"只是耶戶不盡心遵守耶和華－以色列神的律法，不離開耶羅波安使以色列人陷在罪裏的那罪。","notes":[]},{"n":32,"t":"在那些日子，耶和華才割裂以色列國，使哈薛攻擊以色列的境界，","notes":[],"heads":["耶戶去世"]},{"n":33,"t":"乃是約旦河東、基列全地，從靠近亞嫩谷邊的亞羅珥起，就是基列和巴珊的迦得人、呂便人、瑪拿西人之地。","notes":[]},{"n":34,"t":"耶戶其餘的事，凡他所行的和他的勇力都寫在以色列諸王記上。","notes":[]},{"n":35,"t":"耶戶與他列祖同睡，葬在撒馬利亞；他兒子約哈斯接續他作王。","notes":[]},{"n":36,"t":"耶戶在撒馬利亞作以色列王二十八年。","notes":[]}]},"11":{"heading":"猶大的王后亞她利雅","verses":[{"n":1,"t":"亞哈謝的母親亞她利雅見她兒子死了，就起來剿滅王室。","notes":[]},{"n":2,"t":"但約蘭王的女兒，亞哈謝的妹子約示巴，將亞哈謝的兒子約阿施從那被殺的王子中偷出來，把他和他的乳母都藏在臥房裏，躲避亞她利雅，免得被殺。","notes":[]},{"n":3,"t":"約阿施和他的乳母藏在耶和華的殿裏六年；亞她利雅篡了國位。","notes":[]},{"n":4,"t":"第七年，耶何耶大打發人叫迦利人和護衛兵的眾百夫長來，領他們進了耶和華的殿，與他們立約，使他們在耶和華殿裏起誓，又將王的兒子指給他們看，","notes":["或譯：親兵"]},{"n":5,"t":"吩咐他們說：「你們當這樣行：凡安息日進班的三分之一要看守王宮，","notes":[]},{"n":6,"t":"三分之一要在蘇珥門，三分之一要在護衛兵院的後門。這樣把守王宮，攔阻閒人。","notes":[]},{"n":7,"t":"你們安息日所有出班的三分之二要在耶和華的殿裏護衛王；","notes":[]},{"n":8,"t":"各人手拿兵器，四圍護衛王。凡擅入你們班次的必當治死，王出入的時候，你們當跟隨他。」","notes":[]},{"n":9,"t":"眾百夫長就照著祭司耶何耶大一切所吩咐的去行，各帶所管安息日進班出班的人來見祭司耶何耶大。","notes":[]},{"n":10,"t":"祭司便將耶和華殿裏所藏大衛王的槍和盾牌交給百夫長。","notes":[]},{"n":11,"t":"護衛兵手中各拿兵器，在壇和殿那裏，從殿右直到殿左，站在王子的四圍。","notes":[]},{"n":12,"t":"祭司領王子出來，給他戴上冠冕，將律法書交給他，膏他作王；眾人就拍掌說：「願王萬歲！」","notes":[]},{"n":13,"t":"亞她利雅聽見護衛兵和民的聲音，就到民那裏，進耶和華的殿，","notes":[]},{"n":14,"t":"看見王照例站在柱旁，百夫長和吹號的人侍立在王左右，國中的眾民歡樂吹號；亞她利雅就撕裂衣服，喊叫說：「反了！反了！」","notes":[]},{"n":15,"t":"祭司耶何耶大吩咐管轄軍兵的百夫長說：「將她趕出班外，凡跟隨她的必用刀殺死！」因為祭司說「不可在耶和華殿裏殺她」，","notes":[]},{"n":16,"t":"眾兵就閃開讓她去；她從馬路上王宮去，便在那裏被殺。","notes":[]},{"n":17,"t":"耶何耶大使王和民與耶和華立約，作耶和華的民；又使王與民立約。","notes":[],"heads":["耶何耶大的改革"]},{"n":18,"t":"於是國民都到巴力廟，拆毀了廟，打碎壇和像，又在壇前將巴力的祭司瑪坦殺了。祭司耶何耶大派官看守耶和華的殿，","notes":[]},{"n":19,"t":"又率領百夫長和迦利人與護衛兵，以及國中的眾民，請王從耶和華殿下來，由護衛兵的門進入王宮，他就坐了王位。","notes":["或譯：親兵"]},{"n":20,"t":"國民都歡樂，閤城都安靜。眾人已將亞她利雅在王宮那裏用刀殺了。","notes":[]},{"n":21,"t":"約阿施登基的時候年方七歲。","notes":[]}]},"12":{"heading":"猶大王約阿施","verses":[{"n":1,"t":"耶戶第七年，約阿施登基，在耶路撒冷作王四十年。他母親名叫西比亞，是別是巴人。","notes":[]},{"n":2,"t":"約阿施在祭司耶何耶大教訓他的時候，就行耶和華眼中看為正的事；","notes":[]},{"n":3,"t":"只是邱壇還沒有廢去，百姓仍在那裏獻祭燒香。","notes":[]},{"n":4,"t":"約阿施對眾祭司說：「凡奉到耶和華殿分別為聖之物所值通用的銀子，或各人當納的身價，或樂意奉到耶和華殿的銀子，","notes":[]},{"n":5,"t":"你們當從所認識的人收了來，修理殿的一切破壞之處。」","notes":[]},{"n":6,"t":"無奈到了約阿施王二十三年，祭司仍未修理殿的破壞之處。","notes":[]},{"n":7,"t":"所以約阿施王召了大祭司耶何耶大和眾祭司來，對他們說：「你們怎麼不修理殿的破壞之處呢？從今以後，你們不要從所認識的人再收銀子，要將所收的交出來，修理殿的破壞之處。」","notes":[]},{"n":8,"t":"眾祭司答應不再收百姓的銀子，也不修理殿的破壞之處。","notes":[]},{"n":9,"t":"祭司耶何耶大取了一個櫃子，在櫃蓋上鑽了一個窟窿，放於壇旁，在進耶和華殿的右邊；守門的祭司將奉到耶和華殿的一切銀子投在櫃裏。","notes":[]},{"n":10,"t":"他們見櫃裏的銀子多了，便叫王的書記和大祭司上來，將耶和華殿裏的銀子數算包起來。","notes":[]},{"n":11,"t":"把所平的銀子交給督工的，就是耶和華殿裏辦事的人；他們把銀子轉交修理耶和華殿的木匠和工人，","notes":[]},{"n":12,"t":"並瓦匠、石匠，又買木料和鑿成的石頭，修理耶和華殿的破壞之處，以及修理殿的各樣使用。","notes":[]},{"n":13,"t":"但那奉到耶和華殿的銀子，沒有用以做耶和華殿裏的銀杯、蠟剪、碗、號，和別樣的金銀器皿，","notes":[]},{"n":14,"t":"乃將那銀子交給督工的人修理耶和華的殿；","notes":[]},{"n":15,"t":"且將銀子交給辦事的人轉交做工的人，不與他們算賬，因為他們辦事誠實。","notes":[]},{"n":16,"t":"惟有贖愆祭、贖罪祭的銀子沒有奉到耶和華的殿，都歸祭司。","notes":[]},{"n":17,"t":"那時，亞蘭王哈薛上來攻打迦特，攻取了，就定意上來攻打耶路撒冷。","notes":[]},{"n":18,"t":"猶大王約阿施將他列祖猶大王約沙法、約蘭、亞哈謝所分別為聖的物和自己所分別為聖的物，並耶和華殿與王宮府庫裏所有的金子都送給亞蘭王哈薛；哈薛就不上耶路撒冷來了。","notes":[]},{"n":19,"t":"約阿施其餘的事，凡他所行的都寫在猶大列王記上。","notes":[]},{"n":20,"t":"約阿施的臣僕起來背叛，在下悉拉的米羅宮那裏將他殺了。","notes":[]},{"n":21,"t":"殺他的那臣僕就是示米押的兒子約撒甲和朔默的兒子約薩拔。眾人將他葬在大衛城他列祖的墳地裏。他兒子亞瑪謝接續他作王。","notes":[]}]},"13":{"heading":"以色列王約哈斯","verses":[{"n":1,"t":"猶大王亞哈謝的兒子約阿施二十三年，耶戶的兒子約哈斯在撒馬利亞登基作以色列王十七年。","notes":[]},{"n":2,"t":"約哈斯行耶和華眼中看為惡的事，效法尼八的兒子耶羅波安使以色列人陷在罪裏的那罪，總不離開。","notes":[]},{"n":3,"t":"於是，耶和華的怒氣向以色列人發作，將他們屢次交在亞蘭王哈薛和他兒子便‧哈達的手裏。","notes":[]},{"n":4,"t":"約哈斯懇求耶和華，耶和華就應允他，因為見以色列人所受亞蘭王的欺壓。","notes":[]},{"n":5,"t":"耶和華賜給以色列人一位拯救者，使他們脫離亞蘭人的手；於是以色列人仍舊安居在家裏。","notes":[]},{"n":6,"t":"然而他們不離開耶羅波安家使以色列人陷在罪裏的那罪，仍然去行，並且在撒馬利亞留下亞舍拉。","notes":[]},{"n":7,"t":"亞蘭王滅絕約哈斯的民，踐踏他們如禾場上的塵沙，只給約哈斯留下五十馬兵，十輛戰車，一萬步兵。","notes":[]},{"n":8,"t":"約哈斯其餘的事，凡他所行的和他的勇力都寫在以色列諸王記上。","notes":[]},{"n":9,"t":"約哈斯與他列祖同睡，葬在撒馬利亞。他兒子約阿施接續他作王。","notes":[]},{"n":10,"t":"猶大王約阿施三十七年，約哈斯的兒子約阿施在撒馬利亞登基作以色列王十六年。","notes":[],"heads":["以色列王約阿施"]},{"n":11,"t":"他行耶和華眼中看為惡的事，不離開尼八的兒子耶羅波安使以色列人陷在罪裏的一切罪，仍然去行。","notes":[]},{"n":12,"t":"約阿施其餘的事，凡他所行的和他與猶大王亞瑪謝爭戰的勇力，都寫在以色列諸王記上。","notes":[]},{"n":13,"t":"約阿施與他列祖同睡，耶羅波安坐了他的位。約阿施與以色列諸王一同葬在撒馬利亞。","notes":[]},{"n":14,"t":"以利沙得了必死的病，以色列王約阿施下來看他，伏在他臉上哭泣，說：「我父啊！我父啊！以色列的戰車馬兵啊！」","notes":[],"heads":["以利沙去世"]},{"n":15,"t":"以利沙對他說：「你取弓箭來。」王就取了弓箭來；","notes":[]},{"n":16,"t":"又對以色列王說：「你用手拿弓。」王就用手拿弓。以利沙按手在王的手上，","notes":[]},{"n":17,"t":"說：「你開朝東的窗戶。」他就開了。以利沙說：「射箭吧！」他就射箭。以利沙說：「這是耶和華的得勝箭，就是戰勝亞蘭人的箭；因為你必在亞弗攻打亞蘭人，直到滅盡他們。」","notes":[]},{"n":18,"t":"以利沙又說：「取幾枝箭來。」他就取了來。以利沙說：「打地吧！」他打了三次，便止住了。","notes":[]},{"n":19,"t":"神人向他發怒，說：「應當擊打五六次，就能攻打亞蘭人直到滅盡；現在只能打敗亞蘭人三次。」","notes":[]},{"n":20,"t":"以利沙死了，人將他葬埋。到了新年，有一群摩押人犯境，","notes":[]},{"n":21,"t":"有人正葬死人，忽然看見一群人，就把死人拋在以利沙的墳墓裏，一碰著以利沙的骸骨，死人就復活，站起來了。","notes":[]},{"n":22,"t":"約哈斯年間，亞蘭王哈薛屢次欺壓以色列人。","notes":[],"heads":["以色列與亞蘭爭戰"]},{"n":23,"t":"耶和華卻因與亞伯拉罕、以撒、雅各所立的約，仍施恩給以色列人，憐恤他們，眷顧他們，不肯滅盡他們，尚未趕逐他們離開自己面前。","notes":[]},{"n":24,"t":"亞蘭王哈薛死了，他兒子便‧哈達接續他作王。","notes":[]},{"n":25,"t":"從前哈薛和約阿施的父親約哈斯爭戰，攻取了些城邑，現在約哈斯的兒子約阿施三次打敗哈薛的兒子便‧哈達，就收回了以色列的城邑。","notes":[]}]},"14":{"heading":"猶大王亞瑪謝","verses":[{"n":1,"t":"以色列王約哈斯的兒子約阿施第二年，猶大王約阿施的兒子亞瑪謝登基。","notes":[]},{"n":2,"t":"他登基的時候年二十五歲，在耶路撒冷作王二十九年。他母親名叫約耶但，是耶路撒冷人。","notes":[]},{"n":3,"t":"亞瑪謝行耶和華眼中看為正的事，但不如他祖大衛，乃效法他父約阿施一切所行的；","notes":[]},{"n":4,"t":"只是邱壇還沒有廢去，百姓仍在那裏獻祭燒香。","notes":[]},{"n":5,"t":"國一堅定，就把殺他父王的臣僕殺了，","notes":[]},{"n":6,"t":"卻沒有治死殺王之人的兒子，是照摩西律法書上耶和華所吩咐的說：「不可因子殺父，也不可因父殺子，各人要為本身的罪而死。」","notes":[]},{"n":7,"t":"亞瑪謝在鹽谷殺了以東人一萬，又攻取了西拉，改名叫約帖，直到今日。","notes":[]},{"n":8,"t":"那時，亞瑪謝差遣使者去見耶戶的孫子約哈斯的兒子以色列王約阿施，說：「你來，我們二人相見於戰場。」","notes":[]},{"n":9,"t":"以色列王約阿施差遣使者去見猶大王亞瑪謝，說：「黎巴嫩的蒺藜差遣使者去見黎巴嫩的香柏樹，說：將你的女兒給我兒子為妻。後來黎巴嫩有一個野獸經過，把蒺藜踐踏了。","notes":[]},{"n":10,"t":"你打敗了以東人就心高氣傲，你以此為榮耀，在家裏安居就罷了，為何要惹禍，使自己和猶大國一同敗亡呢？」","notes":[]},{"n":11,"t":"亞瑪謝卻不肯聽這話。於是以色列王約阿施上來，在猶大的伯‧示麥與猶大王亞瑪謝相見於戰場。","notes":[]},{"n":12,"t":"猶大人敗在以色列人面前，各自逃回家裏去了。","notes":[]},{"n":13,"t":"以色列王約阿施在伯‧示麥擒住亞哈謝的孫子、約阿施的兒子猶大王亞瑪謝，就來到耶路撒冷，拆毀耶路撒冷的城牆，從以法蓮門直到角門共四百肘，","notes":[]},{"n":14,"t":"又將耶和華殿裏與王宮府庫裏所有的金銀和器皿都拿了去，並帶人去為質，就回撒馬利亞去了。","notes":[]},{"n":15,"t":"約阿施其餘所行的事和他的勇力，並與猶大王亞瑪謝爭戰的事，都寫在以色列諸王記上。","notes":[]},{"n":16,"t":"約阿施與他列祖同睡，葬在撒馬利亞，以色列諸王的墳地裏。他兒子耶羅波安接續他作王。","notes":[]},{"n":17,"t":"以色列王約哈斯的兒子約阿施死後，猶大王約阿施的兒子亞瑪謝又活了十五年。","notes":[],"heads":["猶大王亞瑪謝去世"]},{"n":18,"t":"亞瑪謝其餘的事都寫在猶大列王記上。","notes":[]},{"n":19,"t":"耶路撒冷有人背叛亞瑪謝，他就逃到拉吉；叛黨卻打發人到拉吉將他殺了。","notes":[]},{"n":20,"t":"人就用馬將他的屍首馱到耶路撒冷，葬在大衛城他列祖的墳地裏。","notes":[]},{"n":21,"t":"猶大眾民立亞瑪謝的兒子亞撒利雅接續他父作王，那時他年十六歲。","notes":["又名烏西雅"]},{"n":22,"t":"亞瑪謝與他列祖同睡之後，亞撒利雅收回以拉他仍歸猶大，又重新修理。","notes":[]},{"n":23,"t":"猶大王約阿施的兒子亞瑪謝十五年，以色列王約阿施的兒子耶羅波安在撒馬利亞登基，作王四十一年。","notes":[],"heads":["以色列王耶羅波安二世"]},{"n":24,"t":"他行耶和華眼中看為惡的事，不離開尼八的兒子耶羅波安使以色列人陷在罪裏的一切罪。","notes":[]},{"n":25,"t":"他收回以色列邊界之地，從哈馬口直到亞拉巴海，正如耶和華－以色列的神藉他僕人迦特希弗人亞米太的兒子先知約拿所說的。","notes":[]},{"n":26,"t":"因為耶和華看見以色列人甚是艱苦，無論困住的、自由的都沒有了，也無人幫助以色列人。","notes":[]},{"n":27,"t":"耶和華並沒有說要將以色列的名從天下塗抹，乃藉約阿施的兒子耶羅波安拯救他們。","notes":[]},{"n":28,"t":"耶羅波安其餘的事，凡他所行的和他的勇力，他怎樣爭戰，怎樣收回大馬士革和先前屬猶大的哈馬歸以色列，都寫在以色列諸王記上。","notes":[]},{"n":29,"t":"耶羅波安與他列祖以色列諸王同睡。他兒子撒迦利雅接續他作王。","notes":[]}]},"15":{"heading":"猶大王亞撒利雅","verses":[{"n":1,"t":"以色列王耶羅波安二十七年，猶大王亞瑪謝的兒子亞撒利雅登基，","notes":[]},{"n":2,"t":"他登基的時候年十六歲，在耶路撒冷作王五十二年。他母親名叫耶可利雅，是耶路撒冷人。","notes":[]},{"n":3,"t":"亞撒利雅行耶和華眼中看為正的事，效法他父親亞瑪謝一切所行的；","notes":[]},{"n":4,"t":"只是邱壇還沒有廢去，百姓仍在那裏獻祭燒香。","notes":[]},{"n":5,"t":"耶和華降災與王，使他長大痲瘋，直到死日，他就住在別的宮裏。他的兒子約坦管理家事，治理國民。","notes":[]},{"n":6,"t":"亞撒利雅其餘的事，凡他所行的都寫在猶大列王記上。","notes":[]},{"n":7,"t":"亞撒利雅與他列祖同睡，葬在大衛城他列祖的墳地裏。他兒子約坦接續他作王。","notes":[]},{"n":8,"t":"猶大王亞撒利雅三十八年，耶羅波安的兒子撒迦利雅在撒馬利亞作以色列王六個月。","notes":[],"heads":["以色列王撒迦利雅"]},{"n":9,"t":"他行耶和華眼中看為惡的事，效法他列祖所行的，不離開尼八的兒子耶羅波安使以色列人陷在罪裏的那罪。","notes":[]},{"n":10,"t":"雅比的兒子沙龍背叛他，在百姓面前擊殺他，篡了他的位。","notes":[]},{"n":11,"t":"撒迦利雅其餘的事都寫在以色列諸王記上。","notes":[]},{"n":12,"t":"這是從前耶和華應許耶戶說：「你的子孫必坐以色列的國位直到四代。」這話果然應驗了。","notes":[]},{"n":13,"t":"猶大王烏西雅三十九年，雅比的兒子沙龍登基在撒馬利亞作王一個月。","notes":["就是亞撒利雅"],"heads":["以色列王沙龍"]},{"n":14,"t":"迦底的兒子米拿現從得撒上撒馬利亞，殺了雅比的兒子沙龍，篡了他的位。","notes":[]},{"n":15,"t":"沙龍其餘的事和他背叛的情形都寫在以色列諸王記上。","notes":[]},{"n":16,"t":"那時米拿現從得撒起攻打提斐薩和其四境，擊殺城中一切的人，剖開其中所有的孕婦，都因他們沒有給他開城。","notes":[]},{"n":17,"t":"猶大王亞撒利雅三十九年，迦底的兒子米拿現登基，在撒馬利亞作以色列王十年。","notes":[],"heads":["以色列王米拿現"]},{"n":18,"t":"他行耶和華眼中看為惡的事，終身不離開尼八的兒子耶羅波安使以色列人陷在罪裏的那罪。","notes":[]},{"n":19,"t":"亞述王普勒來攻擊以色列國，米拿現給他一千他連得銀子，請普勒幫助他堅定國位。","notes":[]},{"n":20,"t":"米拿現向以色列一切大富戶索要銀子，使他們各出五十舍客勒，就給了亞述王。於是亞述王回去，不在國中停留。","notes":[]},{"n":21,"t":"米拿現其餘的事，凡他所行的都寫在以色列諸王記上。","notes":[]},{"n":22,"t":"米拿現與他列祖同睡。他兒子比加轄接續他作王。","notes":[]},{"n":23,"t":"猶大王亞撒利雅五十年，米拿現的兒子比加轄在撒馬利亞登基作以色列王二年。","notes":[],"heads":["以色列王比加轄"]},{"n":24,"t":"他行耶和華眼中看為惡的事，不離開尼八的兒子耶羅波安使以色列人陷在罪裏的那罪。","notes":[]},{"n":25,"t":"比加轄的將軍、利瑪利的兒子比加背叛他，在撒馬利亞王宮裏的衛所殺了他。亞珥歌伯和亞利耶並基列的五十人幫助比加；比加擊殺他，篡了他的位。","notes":[]},{"n":26,"t":"比加轄其餘的事，凡他所行的都寫在以色列諸王記上。","notes":[]},{"n":27,"t":"猶大王亞撒利雅五十二年，利瑪利的兒子比加在撒馬利亞登基作以色列王二十年。","notes":[],"heads":["以色列王比加"]},{"n":28,"t":"他行耶和華眼中看為惡的事，不離開尼八的兒子耶羅波安使以色列人陷在罪裏的那罪。","notes":[]},{"n":29,"t":"以色列王比加年間，亞述王提革拉‧毗列色來奪了以雲、亞伯‧伯‧瑪迦、亞挪、基低斯、夏瑣、基列、加利利，和拿弗他利全地，將這些地方的居民都擄到亞述去了。","notes":[]},{"n":30,"t":"烏西雅的兒子約坦二十年，以拉的兒子何細亞背叛利瑪利的兒子比加，擊殺他，篡了他的位。","notes":[]},{"n":31,"t":"比加其餘的事，凡他所行的都寫在以色列諸王記上。","notes":[]},{"n":32,"t":"以色列王利瑪利的兒子比加第二年，猶大王烏西雅的兒子約坦登基。","notes":[],"heads":["猶大王約坦"]},{"n":33,"t":"他登基的時候年二十五歲，在耶路撒冷作王十六年。他母親名叫耶路沙，是撒督的女兒。","notes":[]},{"n":34,"t":"約坦行耶和華眼中看為正的事，效法他父親烏西雅一切所行的；","notes":[]},{"n":35,"t":"只是邱壇還沒有廢去，百姓仍在那裏獻祭燒香。約坦建立耶和華殿的上門。","notes":[]},{"n":36,"t":"約坦其餘的事，凡他所行的都寫在猶大列王記上。","notes":[]},{"n":37,"t":"在那些日子，耶和華才使亞蘭王利汛和利瑪利的兒子比加去攻擊猶大。","notes":[]},{"n":38,"t":"約坦與他列祖同睡，葬在他祖大衛城他列祖的墳地裏。他兒子亞哈斯接續他作王。","notes":[]}]},"16":{"heading":"猶大王亞哈斯","verses":[{"n":1,"t":"利瑪利的兒子比加十七年，猶大王約坦的兒子亞哈斯登基。","notes":[]},{"n":2,"t":"他登基的時候年二十歲，在耶路撒冷作王十六年；不像他祖大衛行耶和華－他神眼中看為正的事，","notes":[]},{"n":3,"t":"卻效法以色列諸王所行的，又照著耶和華從以色列人面前趕出的外邦人所行可憎的事，使他的兒子經火，","notes":[]},{"n":4,"t":"並在邱壇上、山岡上、各青翠樹下獻祭燒香。","notes":[]},{"n":5,"t":"亞蘭王利汛和以色列王利瑪利的兒子比加上來攻打耶路撒冷，圍困亞哈斯，卻不能勝他。","notes":[]},{"n":6,"t":"當時亞蘭王利汛收回以拉他歸與亞蘭，將猶大人從以拉他趕出去。亞蘭人就來到以拉他，住在那裏，直到今日。","notes":["有譯以東人的"]},{"n":7,"t":"亞哈斯差遣使者去見亞述王提革拉‧毗列色，說：「我是你的僕人、你的兒子。現在亞蘭王和以色列王攻擊我，求你來救我脫離他們的手。」","notes":[]},{"n":8,"t":"亞哈斯將耶和華殿裏和王宮府庫裏所有的金銀都送給亞述王為禮物。","notes":[]},{"n":9,"t":"亞述王應允了他，就上去攻打大馬士革，將城攻取，殺了利汛，把居民擄到吉珥。","notes":[]},{"n":10,"t":"亞哈斯王上大馬士革去迎接亞述王提革拉‧毗列色，在大馬士革看見一座壇，就照壇的規模樣式作法畫了圖樣，送到祭司烏利亞那裏。","notes":[]},{"n":11,"t":"祭司烏利亞照著亞哈斯王從大馬士革送來的圖樣，在亞哈斯王沒有從大馬士革回來之先，建築一座壇。","notes":[]},{"n":12,"t":"王從大馬士革回來看見壇，就近前來，在壇上獻祭；","notes":[]},{"n":13,"t":"燒燔祭、素祭、澆奠祭，將平安祭牲的血灑在壇上，","notes":[]},{"n":14,"t":"又將耶和華面前的銅壇從耶和華殿和新壇的中間搬到新壇的北邊。","notes":[]},{"n":15,"t":"亞哈斯王吩咐祭司烏利亞說：「早晨的燔祭、晚上的素祭，王的燔祭、素祭，國內眾民的燔祭、素祭、奠祭都要燒在大壇上。燔祭牲和平安祭牲的血也要灑在這壇上，只是銅壇我要用以求問耶和華。」","notes":[]},{"n":16,"t":"祭司烏利亞就照著亞哈斯王所吩咐的行了。","notes":[]},{"n":17,"t":"亞哈斯王打掉盆座四面鑲著的心子，把盆從座上挪下來，又將銅海從馱海的銅牛上搬下來，放在鋪石地；","notes":[]},{"n":18,"t":"又因亞述王的緣故，將耶和華殿為安息日所蓋的廊子和王從外入殿的廊子挪移，圍繞耶和華的殿。","notes":[]},{"n":19,"t":"亞哈斯其餘所行的事都寫在猶大列王記上。","notes":[]},{"n":20,"t":"亞哈斯與他列祖同睡，葬在大衛城他列祖的墳地裏。他兒子希西家接續他作王。","notes":[]}]},"17":{"heading":"以色列王何細亞","verses":[{"n":1,"t":"猶大王亞哈斯十二年，以拉的兒子何細亞在撒馬利亞登基作以色列王九年。","notes":[]},{"n":2,"t":"他行耶和華眼中看為惡的事，只是不像在他以前的以色列諸王。","notes":[]},{"n":3,"t":"亞述王撒縵以色上來攻擊何細亞，何細亞就服事他，給他進貢。","notes":[]},{"n":4,"t":"何細亞背叛，差人去見埃及王梭，不照往年所行的與亞述王進貢。亞述王知道了，就把他鎖禁，囚在監裏。","notes":[]},{"n":5,"t":"亞述王上來攻擊以色列遍地，上到撒馬利亞，圍困三年。","notes":[]},{"n":6,"t":"何細亞第九年亞述王攻取了撒馬利亞，將以色列人擄到亞述，把他們安置在哈臘與歌散的哈博河邊，並米底亞人的城邑。","notes":[]},{"n":7,"t":"這是因以色列人得罪那領他們出埃及地、脫離埃及王法老手的耶和華－他們的神，去敬畏別神，","notes":[]},{"n":8,"t":"隨從耶和華在他們面前所趕出外邦人的風俗和以色列諸王所立的條規。","notes":[]},{"n":9,"t":"以色列人暗中行不正的事，違背耶和華－他們的神，在他們所有的城邑，從瞭望樓直到堅固城，建築邱壇；","notes":[]},{"n":10,"t":"在各高岡上、各青翠樹下立柱像和木偶；","notes":[]},{"n":11,"t":"在邱壇上燒香，效法耶和華在他們面前趕出的外邦人所行的，又行惡事惹動耶和華的怒氣；","notes":[]},{"n":12,"t":"且事奉偶像，就是耶和華警戒他們不可行的。","notes":[]},{"n":13,"t":"但耶和華藉眾先知、先見勸戒以色列人和猶大人說：「當離開你們的惡行，謹守我的誡命律例，遵行我吩咐你們列祖，並藉我僕人眾先知所傳給你們的律法。」","notes":[]},{"n":14,"t":"他們卻不聽從，竟硬著頸項，效法他們列祖，不信服耶和華－他們的神，","notes":[]},{"n":15,"t":"厭棄他的律例和他與他們列祖所立的約，並勸戒他們的話，隨從虛無的神，自己成為虛妄，效法周圍的外邦人，就是耶和華囑咐他們不可效法的；","notes":[]},{"n":16,"t":"離棄耶和華－他們神的一切誡命，為自己鑄了兩個牛犢的像，立了亞舍拉，敬拜天上的萬象，事奉巴力，","notes":[]},{"n":17,"t":"又使他們的兒女經火，用占卜，行法術賣了自己，行耶和華眼中看為惡的事，惹動他的怒氣。","notes":[]},{"n":18,"t":"所以耶和華向以色列人大大發怒，從自己面前趕出他們，只剩下猶大一個支派。","notes":[]},{"n":19,"t":"猶大人也不遵守耶和華－他們神的誡命，隨從以色列人所立的條規。","notes":[]},{"n":20,"t":"耶和華就厭棄以色列全族，使他們受苦，把他們交在搶奪他們的人手中，以致趕出他們離開自己面前，","notes":[]},{"n":21,"t":"將以色列國從大衛家奪回；他們就立尼八的兒子耶羅波安作王。耶羅波安引誘以色列人不隨從耶和華，陷在大罪裏。","notes":[]},{"n":22,"t":"以色列人犯耶羅波安所犯的一切罪，總不離開，","notes":[]},{"n":23,"t":"以致耶和華從自己面前趕出他們，正如藉他僕人眾先知所說的。這樣，以色列人從本地被擄到亞述，直到今日。","notes":[]},{"n":24,"t":"亞述王從巴比倫、古他、亞瓦、哈馬，和西法瓦音遷移人來，安置在撒馬利亞的城邑，代替以色列人；他們就得了撒馬利亞，住在其中。","notes":[],"heads":["亞述人定居於以色列人中"]},{"n":25,"t":"他們才住那裏的時候，不敬畏耶和華，所以耶和華叫獅子進入他們中間，咬死了些人。","notes":[]},{"n":26,"t":"有人告訴亞述王說：「你所遷移安置在撒馬利亞各城的那些民，不知道那地之神的規矩，所以那神叫獅子進入他們中間，咬死他們。」","notes":[]},{"n":27,"t":"亞述王就吩咐說：「叫所擄來的祭司回去一個，使他住在那裏，將那地之神的規矩指教那些民。」","notes":[]},{"n":28,"t":"於是有一個從撒馬利亞擄去的祭司回來，住在伯特利，指教他們怎樣敬畏耶和華。","notes":[]},{"n":29,"t":"然而，各族之人在所住的城裏各為自己製造神像，安置在撒馬利亞人所造有邱壇的殿中。","notes":[]},{"n":30,"t":"巴比倫人造疏割‧比訥像；古他人造匿甲像；哈馬人造亞示瑪像；","notes":[]},{"n":31,"t":"亞瓦人造匿哈和他珥他像；西法瓦音人用火焚燒兒女，獻給西法瓦音的神亞得米勒和亞拿米勒。","notes":[]},{"n":32,"t":"他們懼怕耶和華，也從他們中間立邱壇的祭司，為他們在有邱壇的殿中獻祭。","notes":[]},{"n":33,"t":"他們又懼怕耶和華，又事奉自己的神，從何邦遷移，就隨何邦的風俗。","notes":[]},{"n":34,"t":"他們直到如今仍照先前的風俗去行，不專心敬畏耶和華，不全守自己的規矩、典章，也不遵守耶和華吩咐雅各後裔的律法、誡命。（雅各，就是從前耶和華起名叫以色列的。）","notes":[]},{"n":35,"t":"耶和華曾與他們立約，囑咐他們說：「不可敬畏別神，不可跪拜事奉他，也不可向他獻祭。","notes":[]},{"n":36,"t":"但那用大能和伸出來的膀臂領你們出埃及地的耶和華，你們當敬畏，跪拜，向他獻祭。","notes":[]},{"n":37,"t":"他給你們寫的律例、典章、律法、誡命，你們應當永遠謹守遵行，不可敬畏別神。","notes":[]},{"n":38,"t":"我－耶和華與你們所立的約你們不可忘記，也不可敬畏別神。","notes":[]},{"n":39,"t":"但要敬畏耶和華－你們的神，他必救你們脫離一切仇敵的手。」","notes":[]},{"n":40,"t":"他們卻不聽從，仍照先前的風俗去行。","notes":[]},{"n":41,"t":"如此這些民又懼怕耶和華，又事奉他們的偶像。他們子子孫孫也都照樣行，效法他們的祖宗，直到今日。","notes":[]}]},"18":{"heading":"猶大王希西家","verses":[{"n":1,"t":"以色列王以拉的兒子何細亞第三年，猶大王亞哈斯的兒子希西家登基。","notes":[]},{"n":2,"t":"他登基的時候年二十五歲，在耶路撒冷作王二十九年。他母親名叫亞比，是撒迦利雅的女兒。","notes":[]},{"n":3,"t":"希西家行耶和華眼中看為正的事，效法他祖大衛一切所行的。","notes":[]},{"n":4,"t":"他廢去邱壇，毀壞柱像，砍下木偶，打碎摩西所造的銅蛇，因為到那時以色列人仍向銅蛇燒香。希西家叫銅蛇為銅塊。","notes":["或譯：人稱銅蛇為銅像"]},{"n":5,"t":"希西家倚靠耶和華－以色列的神，在他前後的猶大列王中沒有一個及他的。","notes":[]},{"n":6,"t":"因為他專靠耶和華，總不離開，謹守耶和華所吩咐摩西的誡命。","notes":[]},{"n":7,"t":"耶和華與他同在，他無論往何處去盡都亨通。他背叛、不肯事奉亞述王。","notes":[]},{"n":8,"t":"希西家攻擊非利士人，直到迦薩，並迦薩的四境，從瞭望樓到堅固城。","notes":[]},{"n":9,"t":"希西家王第四年，就是以色列王以拉的兒子何細亞第七年，亞述王撒縵以色上來圍困撒馬利亞；","notes":[]},{"n":10,"t":"過了三年就攻取了城。希西家第六年，以色列王何細亞第九年，撒馬利亞被攻取了。","notes":[]},{"n":11,"t":"亞述王將以色列人擄到亞述，把他們安置在哈臘與歌散的哈博河邊，並米底亞人的城邑；","notes":[]},{"n":12,"t":"都因他們不聽從耶和華－他們神的話，違背他的約，就是耶和華僕人摩西吩咐他們所當守的。","notes":[]},{"n":13,"t":"希西家王十四年，亞述王西拿基立上來攻擊猶大的一切堅固城，將城攻取。","notes":[],"heads":["亞述人威脅耶路撒冷"]},{"n":14,"t":"猶大王希西家差人往拉吉去見亞述王，說：「我有罪了，求你離開我；凡你罰我的，我必承當。」於是亞述王罰猶大王希西家銀子三百他連得，金子三十他連得。","notes":[]},{"n":15,"t":"希西家就把耶和華殿裏和王宮府庫裏所有的銀子都給了他。","notes":[]},{"n":16,"t":"那時，猶大王希西家將耶和華殿門上的金子和他自己包在柱上的金子都刮下來，給了亞述王。","notes":[]},{"n":17,"t":"亞述王從拉吉差遣他珥探、拉伯撒利，和拉伯沙基率領大軍往耶路撒冷，到希西家王那裏去。他們上到耶路撒冷，就站在上池的水溝旁，在漂布地的大路上。","notes":[]},{"n":18,"t":"他們呼叫王的時候，就有希勒家的兒子家宰以利亞敬，並書記舍伯那和亞薩的兒子史官約亞，出來見他們。","notes":[]},{"n":19,"t":"拉伯沙基說：「你們去告訴希西家說，亞述大王如此說：『你所倚靠的有甚麼可仗賴的呢？","notes":[]},{"n":20,"t":"你說有打仗的計謀和能力，我看不過是虛話。你到底倚靠誰才背叛我呢？","notes":[]},{"n":21,"t":"看哪，你所倚靠的埃及是那壓傷的葦杖；人若靠這杖，就必刺透他的手。埃及王法老向一切倚靠他的人也是這樣。","notes":[]},{"n":22,"t":"你們若對我說：我們倚靠耶和華－我們的神，希西家豈不是將神的邱壇和祭壇廢去，且對猶大和耶路撒冷的人說：你們當在耶路撒冷這壇前敬拜嗎？","notes":[]},{"n":23,"t":"現在你把當頭給我主亞述王，我給你二千匹馬，看你這一面騎馬的人夠不夠。","notes":[]},{"n":24,"t":"若不然，怎能打敗我主臣僕中最小的軍長呢？你竟倚靠埃及的戰車馬兵嗎？","notes":[]},{"n":25,"t":"現在我上來攻擊毀滅這地，豈沒有耶和華的意思嗎？耶和華吩咐我說：你上去攻擊毀滅這地吧！』」","notes":[]},{"n":26,"t":"希勒家的兒子以利亞敬和舍伯那，並約亞，對拉伯沙基說：「求你用亞蘭言語和僕人說話，因為我們懂得；不要用猶大言語和我們說話，達到城上百姓的耳中。」","notes":[]},{"n":27,"t":"拉伯沙基說：「我主差遣我來，豈是單對你和你的主說這些話嗎？不也是對這些坐在城上、要與你們一同吃自己糞、喝自己尿的人說嗎？」","notes":[]},{"n":28,"t":"於是拉伯沙基站著，用猶大言語大聲喊著說：「你們當聽亞述大王的話！","notes":[]},{"n":29,"t":"王如此說：『你們不要被希西家欺哄了；因他不能救你們脫離我的手。","notes":[]},{"n":30,"t":"也不要聽希西家使你們倚靠耶和華，說耶和華必要拯救我們，這城必不交在亞述王的手中。』","notes":[]},{"n":31,"t":"不要聽希西家的話！因亞述王如此說：『你們要與我和好，出來投降我，各人就可以吃自己葡萄樹和無花果樹的果子，喝自己井裏的水。","notes":[]},{"n":32,"t":"等我來領你們到一個地方與你們本地一樣，就是有五穀和新酒之地，有糧食和葡萄園之地，有橄欖樹和蜂蜜之地，好使你們存活，不至於死。希西家勸導你們，說耶和華必拯救我們；你們不要聽他的話。","notes":[]},{"n":33,"t":"列國的神有哪一個救他本國脫離亞述王的手呢？","notes":[]},{"n":34,"t":"哈馬、亞珥拔的神在哪裏呢？西法瓦音、希拿、以瓦的神在哪裏呢？他們曾救撒馬利亞脫離我的手嗎？","notes":[]},{"n":35,"t":"這些國的神有誰曾救自己的國脫離我的手呢？難道耶和華能救耶路撒冷脫離我的手嗎？』」","notes":[]},{"n":36,"t":"百姓靜默不言，並不回答一句，因為王曾吩咐說：「不要回答他。」","notes":[]},{"n":37,"t":"當下，希勒家的兒子家宰以利亞敬和書記舍伯那，並亞薩的兒子史官約亞，都撕裂衣服，來到希西家那裏，將拉伯沙基的話告訴了他。","notes":[]}]},"19":{"heading":"希西家王派人求問以賽亞","verses":[{"n":1,"t":"希西家王聽見，就撕裂衣服，披上麻布，進了耶和華的殿；","notes":[]},{"n":2,"t":"使家宰以利亞敬和書記舍伯那，並祭司中的長老，都披上麻布，去見亞摩斯的兒子先知以賽亞，","notes":[]},{"n":3,"t":"對他說：「希西家如此說：『今日是急難、責罰、凌辱的日子，就如婦人將要生產嬰孩，卻沒有力量生產。","notes":[]},{"n":4,"t":"或者耶和華－你的神聽見拉伯沙基的一切話，就是他主人亞述王打發他來辱罵永生神的話，耶和華－你的神聽見這話，就發斥責。故此，求你為餘剩的民揚聲禱告。』」","notes":[]},{"n":5,"t":"希西家王的臣僕就去見以賽亞。","notes":[]},{"n":6,"t":"以賽亞對他們說：「要這樣對你們的主人說，耶和華如此說：『你聽見亞述王的僕人褻瀆我的話，不要懼怕。","notes":[]},{"n":7,"t":"我必驚動他的心，他要聽見風聲就歸回本地。我必使他在那裏倒在刀下。』」","notes":["原文是使靈進入"]},{"n":8,"t":"拉伯沙基回去，正遇見亞述王攻打立拿，原來他早聽見亞述王拔營離開拉吉。","notes":[],"heads":["亞述人再度威脅"]},{"n":9,"t":"亞述王聽見人論古實王特哈加說：「他出來要與你爭戰。」於是亞述王又打發使者去見希西家，吩咐他們說：","notes":[]},{"n":10,"t":"「你們對猶大王希西家如此說：『不要聽你所倚靠的神欺哄你，說耶路撒冷必不交在亞述王的手中。","notes":[]},{"n":11,"t":"你總聽說亞述諸王向列國所行的，乃是盡行滅絕，難道你還能得救嗎？","notes":[]},{"n":12,"t":"我列祖所毀滅的，就是歌散、哈蘭、利色，和屬提‧拉撒的伊甸人，這些國的神何曾拯救這些國呢？","notes":[]},{"n":13,"t":"哈馬的王、亞珥拔的王、西法瓦音城的王、希拿，和以瓦的王都在哪裏呢？』」","notes":[]},{"n":14,"t":"希西家從使者手裏接過書信來，看完了，就上耶和華的殿，將書信在耶和華面前展開。","notes":[]},{"n":15,"t":"希西家向耶和華禱告說：「坐在二基路伯上耶和華－以色列的神啊，你是天下萬國的神，你曾創造天地。","notes":[]},{"n":16,"t":"耶和華啊，求你側耳而聽！耶和華啊，求你睜眼而看！要聽西拿基立打發使者來辱罵永生神的話。","notes":[]},{"n":17,"t":"耶和華啊，亞述諸王果然使列國和列國之地變為荒涼，","notes":[]},{"n":18,"t":"將列國的神像都扔在火裏；因為它本不是神，乃是人手所造的，是木頭石頭的，所以滅絕它。","notes":[]},{"n":19,"t":"耶和華－我們的神啊，現在求你救我們脫離亞述王的手，使天下萬國都知道惟獨你－耶和華是神！」","notes":[]},{"n":20,"t":"亞摩斯的兒子以賽亞就打發人去見希西家，說：「耶和華－以色列的神如此說：『你既然求我攻擊亞述王西拿基立，我已聽見了。』","notes":[],"heads":["以賽亞傳給王的信息"]},{"n":21,"t":"耶和華論他這樣說：錫安的處女藐視你，嗤笑你；耶路撒冷的女子向你搖頭。","notes":[]},{"n":22,"t":"你辱罵誰？褻瀆誰？揚起聲來，高舉眼目攻擊誰呢？乃是攻擊以色列的聖者！","notes":[]},{"n":23,"t":"你藉你的使者辱罵主，並說：我率領許多戰車上山頂，到黎巴嫩極深之處；我要砍伐其中高大的香柏樹和佳美的松樹；我必上極高之處，進入肥田的樹林。","notes":[]},{"n":24,"t":"我已經在外邦挖井喝水；我必用腳掌踏乾埃及的一切河。","notes":[]},{"n":25,"t":"耶和華說，我早先所做的，古時所立的，就是現在藉你使堅固城荒廢，變為亂堆，這事你豈沒有聽見嗎？","notes":[]},{"n":26,"t":"所以其中的居民力量甚小，驚惶羞愧。他們像野草，像青菜，如房頂上的草，又如未長成而枯乾的禾稼。","notes":[]},{"n":27,"t":"你坐下，你出去，你進來，你向我發烈怒，我都知道。","notes":[]},{"n":28,"t":"因你向我發烈怒，又因你狂傲的話達到我耳中，我就要用鉤子鉤上你的鼻子，把嚼環放在你口裏，使你從你來的路轉回去。","notes":[]},{"n":29,"t":"「以色列人哪，我賜你們一個證據：你們今年要吃自生的，明年也要吃自長的；至於後年，你們要耕種收割，栽植葡萄園，吃其中的果子。","notes":[]},{"n":30,"t":"猶大家所逃脫餘剩的，仍要往下扎根，向上結果。","notes":[]},{"n":31,"t":"必有餘剩的民從耶路撒冷而出；必有逃脫的人從錫安山而來。耶和華的熱心必成就這事。","notes":[]},{"n":32,"t":"「所以，耶和華論亞述王如此說：『他必不得來到這城，也不在這裏射箭，不得拿盾牌到城前，也不築壘攻城。","notes":[]},{"n":33,"t":"他從哪條路來，必從那條路回去，必不得來到這城。這是耶和華說的。","notes":[]},{"n":34,"t":"因我為自己的緣故，又為我僕人大衛的緣故，必保護拯救這城。』」","notes":[]},{"n":35,"t":"當夜，耶和華的使者出去，在亞述營中殺了十八萬五千人。清早有人起來，一看，都是死屍了。","notes":[]},{"n":36,"t":"亞述王西拿基立就拔營回去，住在尼尼微。","notes":[]},{"n":37,"t":"一日在他的神尼斯洛廟裏叩拜，他兒子亞得米勒和沙利色用刀殺了他，就逃到亞拉臘地。他兒子以撒哈頓接續他作王。","notes":[]}]},"20":{"heading":"希西家病重康復","verses":[{"n":1,"t":"那時，希西家病得要死。亞摩斯的兒子先知以賽亞去見他，對他說：「耶和華如此說：『你當留遺命與你的家，因為你必死，不能活了。』」","notes":[]},{"n":2,"t":"希西家就轉臉朝牆，禱告耶和華說：","notes":[]},{"n":3,"t":"「耶和華啊，求你記念我在你面前怎樣存完全的心，按誠實行事，又做你眼中所看為善的。」希西家就痛哭了。","notes":[]},{"n":4,"t":"以賽亞出來，還沒有到中院，耶和華的話就臨到他，說：","notes":["院：或譯城"]},{"n":5,"t":"「你回去告訴我民的君希西家說：耶和華－你祖大衛的神如此說：『我聽見了你的禱告，看見了你的眼淚，我必醫治你；到第三日，你必上到耶和華的殿。","notes":[]},{"n":6,"t":"我必加增你十五年的壽數，並且我要救你和這城脫離亞述王的手。我為自己和我僕人大衛的緣故，必保護這城。』」","notes":[]},{"n":7,"t":"以賽亞說：「當取一塊無花果餅來。」人就取了來，貼在瘡上，王便痊癒了。","notes":[]},{"n":8,"t":"希西家問以賽亞說：「耶和華必醫治我，到第三日，我能上耶和華的殿，有甚麼兆頭呢？」","notes":[]},{"n":9,"t":"以賽亞說：「耶和華必成就他所說的。這是他給你的兆頭：你要日影向前進十度呢？是要往後退十度呢？」","notes":[]},{"n":10,"t":"希西家回答說：「日影向前進十度容易，我要日影往後退十度。」","notes":[]},{"n":11,"t":"先知以賽亞求告耶和華，耶和華就使亞哈斯的日晷向前進的日影，往後退了十度。","notes":[]},{"n":12,"t":"那時，巴比倫王巴拉但的兒子米羅達‧巴拉但聽見希西家病而痊癒，就送書信和禮物給他。","notes":[],"heads":["從巴比倫來的使者"]},{"n":13,"t":"希西家聽從使者的話，就把他寶庫的金子、銀子、香料、貴重的膏油，和他武庫的一切軍器，並他所有的財寶，都給他們看。他家中和他全國之內，希西家沒有一樣不給他們看的。","notes":[]},{"n":14,"t":"於是先知以賽亞來見希西家王，問他說：「這些人說甚麼？他們從哪裏來見你？」希西家說：「他們從遠方的巴比倫來。」","notes":[]},{"n":15,"t":"以賽亞說：「他們在你家裏看見了甚麼？」希西家說：「凡我家中所有的，他們都看見了；我財寶中沒有一樣不給他們看的。」","notes":[]},{"n":16,"t":"以賽亞對希西家說：「你要聽耶和華的話，","notes":[]},{"n":17,"t":"日子必到，凡你家裏所有的，並你列祖積蓄到如今的，都要被擄到巴比倫去，不留下一樣。這是耶和華說的。","notes":[]},{"n":18,"t":"並且從你本身所生的眾子，其中必有被擄去在巴比倫王宮裏當太監的。」","notes":[]},{"n":19,"t":"希西家對以賽亞說：「你所說耶和華的話甚好！若在我的年日中有太平和穩固的景況，豈不是好嗎？」","notes":[]},{"n":20,"t":"希西家其餘的事和他的勇力，他怎樣挖池、挖溝、引水入城，都寫在猶大列王記上。","notes":[],"heads":["希西家逝世"]},{"n":21,"t":"希西家與他列祖同睡。他兒子瑪拿西接續他作王。","notes":[]}]},"21":{"heading":"猶大王瑪拿西","verses":[{"n":1,"t":"瑪拿西登基的時候年十二歲，在耶路撒冷作王五十五年。他母親名叫協西巴。","notes":[]},{"n":2,"t":"瑪拿西行耶和華眼中看為惡的事，效法耶和華在以色列人面前趕出的外邦人所行可憎的事。","notes":[]},{"n":3,"t":"重新建築他父希西家所毀壞的邱壇，又為巴力築壇，做亞舍拉像，效法以色列王亞哈所行的，且敬拜事奉天上的萬象；","notes":[]},{"n":4,"t":"在耶和華殿宇中築壇。耶和華曾指著這殿說：「我必立我的名在耶路撒冷。」","notes":[]},{"n":5,"t":"他在耶和華殿的兩院中為天上的萬象築壇，","notes":[]},{"n":6,"t":"並使他的兒子經火，又觀兆，用法術，立交鬼的和行巫術的，多行耶和華眼中看為惡的事，惹動他的怒氣；","notes":[]},{"n":7,"t":"又在殿內立雕刻的亞舍拉像。耶和華曾對大衛和他兒子所羅門說：「我在以色列眾支派中所選擇的耶路撒冷和這殿，必立我的名，直到永遠。","notes":[]},{"n":8,"t":"以色列人若謹守遵行我一切所吩咐他們的和我僕人摩西所吩咐他們的一切律法，我就不再使他們挪移離開我所賜給他們列祖之地。」","notes":[]},{"n":9,"t":"他們卻不聽從。瑪拿西引誘他們行惡，比耶和華在以色列人面前所滅的列國更甚。","notes":[]},{"n":10,"t":"耶和華藉他僕人眾先知說：","notes":[]},{"n":11,"t":"「因猶大王瑪拿西行這些可憎的惡事比先前亞摩利人所行的更甚，使猶大人拜他的偶像，陷在罪裏；","notes":[]},{"n":12,"t":"所以耶和華－以色列的神如此說：我必降禍與耶路撒冷和猶大，叫一切聽見的人無不耳鳴。","notes":[]},{"n":13,"t":"我必用量撒馬利亞的準繩和亞哈家的線鉈拉在耶路撒冷上，必擦淨耶路撒冷，如人擦盤，將盤倒扣。","notes":[]},{"n":14,"t":"我必棄掉所餘剩的子民，把他們交在仇敵手中，使他們成為一切仇敵擄掠之物；","notes":["原文是產業"]},{"n":15,"t":"是因他們自從列祖出埃及直到如今，常行我眼中看為惡的事，惹動我的怒氣。」","notes":[]},{"n":16,"t":"瑪拿西行耶和華眼中看為惡的事，使猶大人陷在罪裏，又流許多無辜人的血，充滿了耶路撒冷，從這邊直到那邊。","notes":[]},{"n":17,"t":"瑪拿西其餘的事，凡他所行的和他所犯的罪都寫在猶大列王記上。","notes":[]},{"n":18,"t":"瑪拿西與他列祖同睡，葬在自己宮院烏撒的園內；他兒子亞們接續他作王。","notes":[]},{"n":19,"t":"亞們登基的時候年二十二歲，在耶路撒冷作王二年。他母親名叫米舒利密，是約提巴人哈魯斯的女兒。","notes":[],"heads":["猶大王亞們"]},{"n":20,"t":"亞們行耶和華眼中看為惡的事，與他父親瑪拿西所行的一樣；","notes":[]},{"n":21,"t":"行他父親一切所行的，敬奉他父親所敬奉的偶像，","notes":[]},{"n":22,"t":"離棄耶和華－他列祖的神，不遵行耶和華的道。","notes":[]},{"n":23,"t":"亞們王的臣僕背叛他，在宮裏殺了他。","notes":[]},{"n":24,"t":"但國民殺了那些背叛亞們王的人，立他兒子約西亞接續他作王。","notes":[]},{"n":25,"t":"亞們其餘所行的事都寫在猶大列王記上。","notes":[]},{"n":26,"t":"亞們葬在烏撒的園內自己的墳墓裏。他兒子約西亞接續他作王。","notes":[]}]},"22":{"heading":"猶大王約西亞","verses":[{"n":1,"t":"約西亞登基的時候年八歲，在耶路撒冷作王三十一年。他母親名叫耶底大，是波斯加人亞大雅的女兒。","notes":[]},{"n":2,"t":"約西亞行耶和華眼中看為正的事，行他祖大衛一切所行的，不偏左右。","notes":[]},{"n":3,"t":"約西亞王十八年，王差遣米書蘭的孫子、亞薩利的兒子－書記沙番上耶和華殿去，吩咐他說：","notes":[],"heads":["發現律法書"]},{"n":4,"t":"「你去見大祭司希勒家，使他將奉到耶和華殿的銀子，就是守門的從民中收聚的銀子，數算數算，","notes":[]},{"n":5,"t":"交給耶和華殿裏辦事的人，使他們轉交耶和華殿裏做工的人，好修理殿的破壞之處，","notes":[]},{"n":6,"t":"就是轉交木匠和工人，並瓦匠，又買木料和鑿成的石頭修理殿宇，","notes":[]},{"n":7,"t":"將銀子交在辦事的人手裏，不與他們算帳，因為他們辦事誠實。」","notes":[]},{"n":8,"t":"大祭司希勒家對書記沙番說：「我在耶和華殿裏得了律法書。」希勒家將書遞給沙番，沙番就看了。","notes":[]},{"n":9,"t":"書記沙番到王那裏，回覆王說：「你的僕人已將殿裏的銀子倒出數算，交給耶和華殿裏辦事的人了。」","notes":[]},{"n":10,"t":"書記沙番又對王說：「祭司希勒家遞給我一卷書。」沙番就在王面前讀那書。","notes":[]},{"n":11,"t":"王聽見律法書上的話，便撕裂衣服，","notes":[]},{"n":12,"t":"吩咐祭司希勒家與沙番的兒子亞希甘、米該亞的兒子亞革波、書記沙番和王的臣僕亞撒雅，說：","notes":[]},{"n":13,"t":"「你們去為我、為民、為猶大眾人，以這書上的話求問耶和華；因為我們列祖沒有聽從這書上的言語，沒有遵著書上所吩咐我們的去行，耶和華就向我們大發烈怒。」","notes":[]},{"n":14,"t":"於是，祭司希勒家和亞希甘、亞革波、沙番、亞撒雅都去見女先知戶勒大。戶勒大是掌管禮服沙龍的妻；沙龍是哈珥哈斯的孫子、特瓦的兒子。戶勒大住在耶路撒冷第二區。他們請問於她。","notes":[]},{"n":15,"t":"她對他們說：「耶和華－以色列的神如此說：『你們可以回覆那差遣你們來見我的人說，","notes":[]},{"n":16,"t":"耶和華如此說：我必照著猶大王所讀那書上的一切話，降禍與這地和其上的居民。","notes":[]},{"n":17,"t":"因為他們離棄我，向別神燒香，用他們手所做的惹我發怒，所以我的忿怒必向這地發作，總不止息。』","notes":[]},{"n":18,"t":"然而，差遣你們來求問耶和華的猶大王，你們要這樣回覆他說：『耶和華－以色列的神如此說：至於你所聽見的話，","notes":[]},{"n":19,"t":"就是聽見我指著這地和其上的居民所說、要使這地變為荒場、民受咒詛的話，你便心裏敬服，在我面前自卑，撕裂衣服，向我哭泣，因此我應允了你。這是我－耶和華說的。","notes":[]},{"n":20,"t":"我必使你平平安安地歸到墳墓到你列祖那裏；我要降與這地的一切災禍，你也不致親眼看見。』」他們就回覆王去了。","notes":[]}]},"23":{"heading":"約西亞廢除異教崇拜","verses":[{"n":1,"t":"王差遣人招聚猶大和耶路撒冷的眾長老來。","notes":[]},{"n":2,"t":"王和猶大眾人與耶路撒冷的居民，並祭司、先知，和所有的百姓，無論大小，都一同上到耶和華的殿；王就把耶和華殿裏所得的約書念給他們聽。","notes":[]},{"n":3,"t":"王站在柱旁，在耶和華面前立約，要盡心盡性地順從耶和華，遵守他的誡命、法度、律例，成就這書上所記的約言。眾民都服從這約。","notes":[]},{"n":4,"t":"王吩咐大祭司希勒家和副祭司，並把門的，將那為巴力和亞舍拉，並天上萬象所造的器皿，都從耶和華殿裏搬出來，在耶路撒冷外汲淪溪旁的田間燒了，把灰拿到伯特利去。","notes":[]},{"n":5,"t":"從前猶大列王所立拜偶像的祭司，在猶大城邑的邱壇和耶路撒冷的周圍燒香，現在王都廢去，又廢去向巴力和日、月、行星，並天上萬象燒香的人；","notes":["或譯：十二宮"]},{"n":6,"t":"又從耶和華殿裏將亞舍拉搬到耶路撒冷外汲淪溪邊焚燒，打碎成灰，將灰撒在平民的墳上；","notes":[]},{"n":7,"t":"又拆毀耶和華殿裏孌童的屋子，就是婦女為亞舍拉織帳子的屋子，","notes":[]},{"n":8,"t":"並且從猶大的城邑帶眾祭司來，污穢祭司燒香的邱壇，從迦巴直到別是巴，又拆毀城門旁的邱壇，這邱壇在邑宰約書亞門前，進城門的左邊。","notes":[]},{"n":9,"t":"但是邱壇的祭司不登耶路撒冷耶和華的壇，只在他們弟兄中間吃無酵餅。","notes":[]},{"n":10,"t":"又污穢欣嫩子谷的陀斐特，不許人在那裏使兒女經火獻給摩洛；","notes":[]},{"n":11,"t":"又將猶大列王在耶和華殿門旁、太監拿單‧米勒靠近遊廊的屋子、向日頭所獻的馬廢去，且用火焚燒日車。","notes":[]},{"n":12,"t":"猶大列王在亞哈斯樓頂上所築的壇和瑪拿西在耶和華殿兩院中所築的壇，王都拆毀打碎了，就把灰倒在汲淪溪中。","notes":[]},{"n":13,"t":"從前以色列王所羅門在耶路撒冷前、邪僻山右邊為西頓人可憎的神亞斯她錄、摩押人可憎的神基抹、亞捫人可憎的神米勒公所築的邱壇，王都污穢了，","notes":[]},{"n":14,"t":"又打碎柱像，砍下木偶，將人的骨頭充滿了那地方。","notes":[]},{"n":15,"t":"他將伯特利的壇，就是叫以色列人陷在罪裏、尼八的兒子耶羅波安所築的那壇，都拆毀焚燒，打碎成灰，並焚燒了亞舍拉。","notes":[]},{"n":16,"t":"約西亞回頭，看見山上的墳墓，就打發人將墳墓裏的骸骨取出來，燒在壇上，污穢了壇，正如從前神人宣傳耶和華的話。","notes":[]},{"n":17,"t":"約西亞問說：「我所看見的是甚麼碑？」那城裏的人回答說：「先前有神人從猶大來，預先說王現在向伯特利壇所行的事，這就是他的墓碑。」","notes":[]},{"n":18,"t":"約西亞說：「由他吧！不要挪移他的骸骨。」他們就不動他的骸骨，也不動從撒馬利亞來那先知的骸骨。","notes":[]},{"n":19,"t":"從前以色列諸王在撒馬利亞的城邑建築邱壇的殿，惹動耶和華的怒氣，現在約西亞都廢去了，就如他在伯特利所行的一般；","notes":[]},{"n":20,"t":"又將邱壇的祭司都殺在壇上，並在壇上燒人的骨頭，就回耶路撒冷去了。","notes":[]},{"n":21,"t":"王吩咐眾民說：「你們當照這約書上所寫的，向耶和華－你們的神守逾越節。」","notes":[],"heads":["約西亞守逾越節"]},{"n":22,"t":"自從士師治理以色列人和以色列王、猶大王的時候，直到如今，實在沒有守過這樣的逾越節；","notes":[]},{"n":23,"t":"只有約西亞王十八年在耶路撒冷向耶和華守這逾越節。","notes":[]},{"n":24,"t":"凡猶大國和耶路撒冷所有交鬼的、行巫術的，與家中的神像和偶像，並一切可憎之物，約西亞盡都除掉，成就了祭司希勒家在耶和華殿裏所得律法書上所寫的話。","notes":[],"heads":["約西亞的其他改革"]},{"n":25,"t":"在約西亞以前沒有王像他盡心、盡性、盡力地歸向耶和華，遵行摩西的一切律法；在他以後也沒有興起一個王像他。","notes":[]},{"n":26,"t":"然而，耶和華向猶大所發猛烈的怒氣仍不止息，是因瑪拿西諸事惹動他。","notes":[]},{"n":27,"t":"耶和華說：「我必將猶大人從我面前趕出，如同趕出以色列人一般；我必棄掉我從前所選擇的這城－耶路撒冷和我所說立我名的殿。」","notes":[]},{"n":28,"t":"約西亞其餘的事，凡他所行的都寫在猶大列王記上。","notes":[],"heads":["約西亞逝世"]},{"n":29,"t":"約西亞年間，埃及王法老尼哥上到幼發拉底河攻擊亞述王；約西亞王去抵擋他。埃及王遇見約西亞在米吉多，就殺了他。","notes":[]},{"n":30,"t":"他的臣僕用車將他的屍首從米吉多送到耶路撒冷，葬在他自己的墳墓裏。國民膏約西亞的兒子約哈斯接續他父親作王。","notes":[]},{"n":31,"t":"約哈斯登基的時候年二十三歲，在耶路撒冷作王三個月。他母親名叫哈慕她，是立拿人耶利米的女兒。","notes":[],"heads":["猶大王約哈斯"]},{"n":32,"t":"約哈斯行耶和華眼中看為惡的事，效法他列祖一切所行的。","notes":[]},{"n":33,"t":"法老尼哥將約哈斯鎖禁在哈馬地的利比拉，不許他在耶路撒冷作王，又罰猶大國銀子一百他連得，金子一他連得。","notes":[]},{"n":34,"t":"法老尼哥立約西亞的兒子以利亞敬接續他父親約西亞作王，給他改名叫約雅敬，卻將約哈斯帶到埃及，他就死在那裏。","notes":[]},{"n":35,"t":"約雅敬將金銀給法老，遵著法老的命向國民徵取金銀，按著各人的力量派定，索要金銀，好給法老尼哥。","notes":[],"heads":["猶大王約雅敬"]},{"n":36,"t":"約雅敬登基的時候年二十五歲，在耶路撒冷作王十一年。他母親名叫西布大，是魯瑪人毗大雅的女兒。","notes":[]},{"n":37,"t":"約雅敬行耶和華眼中看為惡的事，效法他列祖一切所行的。","notes":[]}]},"24":{"heading":"猶大王約雅斤","verses":[{"n":1,"t":"約雅敬年間，巴比倫王尼布甲尼撒上到猶大；約雅敬服事他三年，然後背叛他。","notes":[]},{"n":2,"t":"耶和華使迦勒底軍、亞蘭軍、摩押軍，和亞捫人的軍來攻擊約雅敬，毀滅猶大，正如耶和華藉他僕人眾先知所說的。","notes":[]},{"n":3,"t":"這禍臨到猶大人，誠然是耶和華所命的，要將他們從自己面前趕出，是因瑪拿西所犯的一切罪；","notes":[]},{"n":4,"t":"又因他流無辜人的血，充滿了耶路撒冷；耶和華決不肯赦免。","notes":[]},{"n":5,"t":"約雅敬其餘的事，凡他所行的都寫在猶大列王記上。","notes":[]},{"n":6,"t":"約雅敬與他列祖同睡。他兒子約雅斤接續他作王。","notes":[]},{"n":7,"t":"埃及王不再從他國中出來；因為巴比倫王將埃及王所管之地，從埃及小河直到幼發拉底河都奪去了。","notes":[]},{"n":8,"t":"約雅斤登基的時候年十八歲，在耶路撒冷作王三個月。他母親名叫尼護施她，是耶路撒冷人以利拿單的女兒。","notes":[]},{"n":9,"t":"約雅斤行耶和華眼中看為惡的事，效法他父親一切所行的。","notes":[]},{"n":10,"t":"那時，巴比倫王尼布甲尼撒的軍兵上到耶路撒冷，圍困城。","notes":[]},{"n":11,"t":"當他軍兵圍困城的時候，巴比倫王尼布甲尼撒就親自來了。","notes":[]},{"n":12,"t":"猶大王約雅斤和他母親、臣僕、首領、太監一同出城，投降巴比倫王；巴比倫王便拿住他。那時是巴比倫王第八年。","notes":[]},{"n":13,"t":"巴比倫王將耶和華殿和王宮裏的寶物都拿去了，將以色列王所羅門所造耶和華殿裏的金器都毀壞了，正如耶和華所說的；","notes":[]},{"n":14,"t":"又將耶路撒冷的眾民和眾首領，並所有大能的勇士，共一萬人，連一切木匠、鐵匠都擄了去；除了國中極貧窮的人以外，沒有剩下的；","notes":[]},{"n":15,"t":"並將約雅斤和王母、后妃、太監，與國中的大官，都從耶路撒冷擄到巴比倫去了；","notes":[]},{"n":16,"t":"又將一切勇士七千人和木匠、鐵匠一千人，都是能上陣的勇士，全擄到巴比倫去了。","notes":[]},{"n":17,"t":"巴比倫王立約雅斤的叔叔瑪探雅代替他作王，給瑪探雅改名叫西底家。","notes":[]},{"n":18,"t":"西底家登基的時候年二十一歲，在耶路撒冷作王十一年。他母親名叫哈慕她，是立拿人耶利米的女兒。","notes":[],"heads":["猶大王西底家"]},{"n":19,"t":"西底家行耶和華眼中看為惡的事，是照約雅敬一切所行的。","notes":[]},{"n":20,"t":"因此耶和華的怒氣在耶路撒冷和猶大發作，以致將人民從自己面前趕出。","notes":[]}]},"25":{"heading":"耶路撒冷陷落","verses":[{"n":1,"t":"西底家背叛巴比倫王。他作王第九年十月初十日，巴比倫王尼布甲尼撒率領全軍來攻擊耶路撒冷，對城安營，四圍築壘攻城。","notes":[]},{"n":2,"t":"於是城被圍困，直到西底家王十一年。","notes":[]},{"n":3,"t":"四月初九日，城裏有大饑荒，甚至百姓都沒有糧食。","notes":[]},{"n":4,"t":"城被攻破，一切兵丁就在夜間從靠近王園兩城中間的門逃跑。迦勒底人正在四圍攻城，王就向亞拉巴逃走。","notes":[]},{"n":5,"t":"迦勒底的軍隊追趕王，在耶利哥的平原追上他；他的全軍都離開他四散了。","notes":[]},{"n":6,"t":"迦勒底人就拿住王，帶他到在利比拉的巴比倫王那裏審判他。","notes":[]},{"n":7,"t":"在西底家眼前殺了他的眾子，並且剜了西底家的眼睛，用銅鍊鎖著他，帶到巴比倫去。","notes":[]},{"n":8,"t":"巴比倫王尼布甲尼撒十九年五月初七日，巴比倫王的臣僕、護衛長尼布撒拉旦來到耶路撒冷，","notes":[],"heads":["聖殿被毀"]},{"n":9,"t":"用火焚燒耶和華的殿和王宮，又焚燒耶路撒冷的房屋，就是各大戶家的房屋。","notes":[]},{"n":10,"t":"跟從護衛長迦勒底的全軍就拆毀耶路撒冷四圍的城牆。","notes":[]},{"n":11,"t":"那時護衛長尼布撒拉旦將城裏所剩下的百姓，並已經投降巴比倫王的人，以及大眾所剩下的人，都擄去了。","notes":[]},{"n":12,"t":"但護衛長留下些民中最窮的，使他們修理葡萄園，耕種田地。","notes":[]},{"n":13,"t":"耶和華殿的銅柱，並耶和華殿的盆座和銅海，迦勒底人都打碎了，將那銅運到巴比倫去了，","notes":[]},{"n":14,"t":"又帶去鍋、鏟子、蠟剪、調羹，並所用的一切銅器，","notes":[]},{"n":15,"t":"火鼎、碗，無論金的銀的，護衛長也都帶去了。","notes":[]},{"n":16,"t":"所羅門為耶和華殿所造的兩根銅柱、一個銅海，和幾個盆座，這一切的銅，多得無法可稱。","notes":[]},{"n":17,"t":"這一根柱子高十八肘，柱上有銅頂，高三肘；銅頂的周圍有網子和石榴，都是銅的。那一根柱子，照此一樣，也有網子。","notes":[]},{"n":18,"t":"護衛長拿住大祭司西萊雅、副祭司西番亞，和三個把門的，","notes":[],"heads":["猶大人被擄"]},{"n":19,"t":"又從城中拿住一個管理兵丁的官，並在城裏所遇常見王面的五個人和檢點國民軍長的書記，以及城裏遇見的國民六十個人。","notes":["或譯：太監"]},{"n":20,"t":"護衛長尼布撒拉旦將這些人帶到在利比拉的巴比倫王那裏。","notes":[]},{"n":21,"t":"巴比倫王就把他們擊殺在哈馬地的利比拉。這樣，猶大人被擄去離開本地。","notes":[]},{"n":22,"t":"至於猶大國剩下的民，就是巴比倫王尼布甲尼撒所剩下的，巴比倫王立了沙番的孫子、亞希甘的兒子基大利作他們的省長。","notes":[],"heads":["立基大利作猶大省長"]},{"n":23,"t":"眾軍長和屬他們的人聽見巴比倫王立了基大利作省長，於是軍長尼探雅的兒子以實瑪利、加利亞的兒子約哈難、尼陀法人單戶蔑的兒子西萊雅、瑪迦人的兒子雅撒尼亞，和屬他們的人都到米斯巴見基大利。","notes":[]},{"n":24,"t":"基大利向他們和屬他們的人起誓說：「你們不必懼怕迦勒底臣僕，只管住在這地服事巴比倫王，就可以得福。」","notes":[]},{"n":25,"t":"七月間，宗室以利沙瑪的孫子、尼探雅的兒子以實瑪利帶著十個人來，殺了基大利和同他在米斯巴的猶大人與迦勒底人。","notes":[]},{"n":26,"t":"於是眾民，無論大小，連眾軍長；因為懼怕迦勒底人，都起身往埃及去了。","notes":[]},{"n":27,"t":"猶大王約雅斤被擄後三十七年，巴比倫王以未‧米羅達元年十二月二十七日，使猶大王約雅斤抬頭，提他出監；","notes":[],"heads":["約雅斤被釋"]},{"n":28,"t":"又對他說恩言，使他的位高過與他一同在巴比倫眾王的位，","notes":[]},{"n":29,"t":"給他脫了囚服。他終身常在巴比倫王面前吃飯。","notes":[]},{"n":30,"t":"王賜他所需用的食物，日日賜他一分，終身都是這樣。","notes":[]}]}},"1CH":{"1":{"heading":"從亞當到亞伯拉罕","verses":[{"n":1,"t":"亞當生塞特；塞特生以挪士；","notes":[]},{"n":2,"t":"以挪士生該南；該南生瑪勒列；瑪勒列生雅列；","notes":[]},{"n":3,"t":"雅列生以諾；以諾生瑪土撒拉；瑪土撒拉生拉麥；","notes":[]},{"n":4,"t":"拉麥生挪亞；挪亞生閃、含、雅弗。","notes":[]},{"n":5,"t":"雅弗的兒子是歌篾、瑪各、瑪代、雅完、土巴、米設、提拉。","notes":[]},{"n":6,"t":"歌篾的兒子是亞實基拿、低法、陀迦瑪。","notes":["在創世記十章三節是利法"]},{"n":7,"t":"雅完的兒子是以利沙、他施、基提、多單。","notes":["有作羅單的"]},{"n":8,"t":"含的兒子是古實、麥西、弗、迦南。","notes":[]},{"n":9,"t":"古實的兒子是西巴、哈腓拉、撒弗他、拉瑪、撒弗提迦。拉瑪的兒子是示巴、底但。","notes":[]},{"n":10,"t":"古實生寧錄；他為世上英雄之首。","notes":[]},{"n":11,"t":"麥西生路低人、亞拿米人、利哈比人、拿弗土希人、","notes":[]},{"n":12,"t":"帕斯魯細人、迦斯路希人、迦斐託人；從迦斐託出來的有非利士人。","notes":[]},{"n":13,"t":"迦南生長子西頓，又生赫","notes":[]},{"n":14,"t":"和耶布斯人、亞摩利人、革迦撒人、","notes":[]},{"n":15,"t":"希未人、亞基人、西尼人、","notes":[]},{"n":16,"t":"亞瓦底人、洗瑪利人，並哈馬人。","notes":[]},{"n":17,"t":"閃的兒子是以攔、亞述、亞法撒、路德、亞蘭、烏斯、戶勒、基帖、米設。","notes":["在創世記十章二十三節是瑪施"]},{"n":18,"t":"亞法撒生沙拉；沙拉生希伯。","notes":[]},{"n":19,"t":"希伯生了兩個兒子：一個名叫法勒，因為那時人就分地居住；法勒的兄弟名叫約坍。","notes":["就是分的意思"]},{"n":20,"t":"約坍生亞摩答、沙列、哈薩瑪非、耶拉、","notes":[]},{"n":21,"t":"哈多蘭、烏薩、德拉、","notes":[]},{"n":22,"t":"以巴錄、亞比瑪利、示巴、","notes":[]},{"n":23,"t":"阿斐、哈腓拉、約巴。這都是約坍的兒子。","notes":[]},{"n":24,"t":"閃生亞法撒；亞法撒生沙拉；","notes":[]},{"n":25,"t":"沙拉生希伯；希伯生法勒；法勒生拉吳；","notes":[]},{"n":26,"t":"拉吳生西鹿；西鹿生拿鶴；拿鶴生他拉；","notes":[]},{"n":27,"t":"他拉生亞伯蘭，亞伯蘭就是亞伯拉罕。","notes":[]},{"n":28,"t":"亞伯拉罕的兒子是以撒、以實瑪利。","notes":[],"heads":["以實瑪利的後裔"]},{"n":29,"t":"以實瑪利的兒子記在下面：以實瑪利的長子是尼拜約，其次是基達、押德別、米比衫、","notes":[]},{"n":30,"t":"米施瑪、度瑪、瑪撒、哈達、提瑪、","notes":[]},{"n":31,"t":"伊突、拿非施、基底瑪。這都是以實瑪利的兒子。","notes":[]},{"n":32,"t":"亞伯拉罕的妾基土拉所生的兒子，就是心蘭、約珊、米但、米甸、伊施巴、書亞。約珊的兒子是示巴、底但。","notes":[]},{"n":33,"t":"米甸的兒子是以法、以弗、哈諾、亞比大、以勒大。這都是基土拉的子孫。","notes":[]},{"n":34,"t":"亞伯拉罕生以撒；以撒的兒子是以掃和以色列。","notes":[],"heads":["以掃的後裔"]},{"n":35,"t":"以掃的兒子是以利法、流珥、耶烏施、雅蘭、可拉。","notes":[]},{"n":36,"t":"以利法的兒子是提幔、阿抹、洗玻、迦坦、基納斯、亭納、亞瑪力。","notes":[]},{"n":37,"t":"流珥的兒子是拿哈、謝拉、沙瑪、米撒。","notes":[]},{"n":38,"t":"西珥的兒子是羅坍、朔巴、祭便、亞拿、底順、以察、底珊。","notes":[],"heads":["以東地的原住民"]},{"n":39,"t":"羅坍的兒子是何利、荷幔；羅坍的妹子是亭納。","notes":[]},{"n":40,"t":"朔巴的兒子是亞勒文、瑪拿轄、以巴錄、示非、阿南。祭便的兒子是亞雅、亞拿。","notes":[]},{"n":41,"t":"亞拿的兒子是底順。底順的兒子是哈默蘭、伊是班、益蘭、基蘭。","notes":[]},{"n":42,"t":"以察的兒子是辟罕、撒番、亞干。底珊的兒子是烏斯、亞蘭。","notes":[]},{"n":43,"t":"以色列人未有君王治理之先，在以東地作王的記在下面：有比珥的兒子比拉，他的京城名叫亭哈巴。","notes":[],"heads":["以東諸王"]},{"n":44,"t":"比拉死了，波斯拉人謝拉的兒子約巴接續他作王。","notes":[]},{"n":45,"t":"約巴死了，提幔地的人戶珊接續他作王。","notes":[]},{"n":46,"t":"戶珊死了，比達的兒子哈達接續他作王。這哈達就是在摩押地殺敗米甸人的，他的京城名叫亞未得。","notes":[]},{"n":47,"t":"哈達死了，瑪士利加人桑拉接續他作王。","notes":[]},{"n":48,"t":"桑拉死了，大河邊的利河伯人掃羅接續他作王。","notes":[]},{"n":49,"t":"掃羅死了，亞革波的兒子巴勒‧哈南接續他作王。","notes":[]},{"n":50,"t":"巴勒‧哈南死了，哈達接續他作王。他的京城名叫巴伊，他的妻子名叫米希她別，是米‧薩合的孫女，瑪特列的女兒。","notes":[]},{"n":51,"t":"哈達死了，以東人的族長有亭納族長、亞勒瓦族長、耶帖族長、","notes":[]},{"n":52,"t":"亞何利巴瑪族長、以拉族長、比嫩族長、","notes":[]},{"n":53,"t":"基納斯族長、提幔族長、米比薩族長、","notes":[]},{"n":54,"t":"瑪基疊族長、以蘭族長。這都是以東人的族長。","notes":[]}]},"2":{"heading":"猶大的後裔","verses":[{"n":1,"t":"以色列的兒子是呂便、西緬、利未、猶大、以薩迦、西布倫、","notes":[]},{"n":2,"t":"但、約瑟、便雅憫、拿弗他利、迦得、亞設。","notes":[]},{"n":3,"t":"猶大的兒子是珥、俄南、示拉，這三人是迦南人書亞女兒所生的。猶大的長子珥在耶和華眼中看為惡，耶和華就使他死了。","notes":[]},{"n":4,"t":"猶大的兒婦她瑪給猶大生法勒斯和謝拉。猶大共有五個兒子。","notes":[]},{"n":5,"t":"法勒斯的兒子是希斯崙、哈母勒。","notes":[]},{"n":6,"t":"謝拉的兒子是心利、以探、希幔、甲各、大拉，共五人。","notes":["就是達大"]},{"n":7,"t":"迦米的兒子是亞干，這亞干在當滅的物上犯了罪，連累了以色列人。","notes":[]},{"n":8,"t":"以探的兒子是亞撒利雅。","notes":[]},{"n":9,"t":"希斯崙所生的兒子是耶拉篾、蘭、基路拜。","notes":[],"heads":["大衛王的家譜"]},{"n":10,"t":"蘭生亞米拿達；亞米拿達生拿順。拿順作猶大人的首領。","notes":[]},{"n":11,"t":"拿順生撒門；撒門生波阿斯；","notes":[]},{"n":12,"t":"波阿斯生俄備得；俄備得生耶西；","notes":[]},{"n":13,"t":"耶西生長子以利押，次子亞比拿達，三子示米亞，","notes":["示米亞就是沙瑪，見撒母耳上十六章九節"]},{"n":14,"t":"四子拿坦業，五子拉代，","notes":[]},{"n":15,"t":"六子阿鮮，七子大衛。","notes":[]},{"n":16,"t":"他們的姊妹是洗魯雅和亞比該。洗魯雅的兒子是亞比篩、約押、亞撒黑，共三人。","notes":[]},{"n":17,"t":"亞比該生亞瑪撒；亞瑪撒的父親是以實瑪利人益帖。","notes":[]},{"n":18,"t":"希斯崙的兒子迦勒娶阿蘇巴和耶略為妻，阿蘇巴的兒子是耶設、朔罷、押墩。","notes":[],"heads":["希斯崙的後裔"]},{"n":19,"t":"阿蘇巴死了，迦勒又娶以法她，生了戶珥。","notes":[]},{"n":20,"t":"戶珥生烏利；烏利生比撒列。","notes":[]},{"n":21,"t":"希斯崙正六十歲娶了基列父親瑪吉的女兒，與她同房；瑪吉的女兒生了西割；","notes":[]},{"n":22,"t":"西割生睚珥。睚珥在基列地有二十三個城邑。","notes":[]},{"n":23,"t":"後來基述人和亞蘭人奪了睚珥的城邑，並基納和其鄉村，共六十個。這都是基列父親瑪吉之子的。","notes":[]},{"n":24,"t":"希斯崙在迦勒‧以法他死後，他的妻亞比雅給他生了亞施戶；亞施戶是提哥亞的父親。","notes":[]},{"n":25,"t":"希斯崙的長子耶拉篾生長子蘭，又生布拿、阿連、阿鮮、亞希雅。","notes":[],"heads":["耶拉篾的後裔"]},{"n":26,"t":"耶拉篾又娶一妻名叫亞她拉，是阿南的母親。","notes":[]},{"n":27,"t":"耶拉篾長子蘭的兒子是瑪斯、雅憫、以結。","notes":[]},{"n":28,"t":"阿南的兒子是沙買、雅大。沙買的兒子是拿答、亞比述。","notes":[]},{"n":29,"t":"亞比述的妻名叫亞比孩，亞比孩給他生了亞辦和摩利。","notes":[]},{"n":30,"t":"拿答的兒子是西列、亞遍；西列死了沒有兒子。","notes":[]},{"n":31,"t":"亞遍的兒子是以示；以示的兒子是示珊；示珊的兒子是亞來。","notes":[]},{"n":32,"t":"沙買兄弟雅大的兒子是益帖、約拿單；益帖死了沒有兒子。","notes":[]},{"n":33,"t":"約拿單的兒子是比勒、撒薩。這都是耶拉篾的子孫。","notes":[]},{"n":34,"t":"示珊沒有兒子，只有女兒。示珊有一個僕人名叫耶哈，是埃及人。","notes":[]},{"n":35,"t":"示珊將女兒給了僕人耶哈為妻，給他生了亞太。","notes":[]},{"n":36,"t":"亞太生拿單；拿單生撒拔；","notes":[]},{"n":37,"t":"撒拔生以弗拉；以弗拉生俄備得；","notes":[]},{"n":38,"t":"俄備得生耶戶；耶戶生亞撒利雅；","notes":[]},{"n":39,"t":"亞撒利雅生希利斯；希利斯生以利亞薩；","notes":[]},{"n":40,"t":"以利亞薩生西斯買；西斯買生沙龍；","notes":[]},{"n":41,"t":"沙龍生耶加米雅；耶加米雅生以利沙瑪。","notes":[]},{"n":42,"t":"耶拉篾兄弟迦勒的長子米沙，是西弗之祖瑪利沙的兒子，是希伯崙之祖。","notes":[],"heads":["迦勒的其餘後裔"]},{"n":43,"t":"希伯崙的兒子是可拉、他普亞、利肯、示瑪。","notes":[]},{"n":44,"t":"示瑪生拉含，是約干之祖。利肯生沙買。","notes":[]},{"n":45,"t":"沙買的兒子是瑪雲；瑪雲是伯‧夙之祖。","notes":[]},{"n":46,"t":"迦勒的妾以法生哈蘭、摩撒、迦謝；哈蘭生迦卸。（","notes":[]},{"n":47,"t":"雅代的兒子是利健、約坦、基珊、毗力、以法、沙亞弗。）","notes":[]},{"n":48,"t":"迦勒的妾瑪迦生示別、特哈拿，","notes":[]},{"n":49,"t":"又生麥瑪拿之祖沙亞弗、抹比拿和基比亞之祖示法。迦勒的女兒是押撒。","notes":[]},{"n":50,"t":"迦勒的子孫就是以法她的長子、戶珥的兒子，記在下面：基列‧耶琳之祖朔巴，","notes":[]},{"n":51,"t":"伯利恆之祖薩瑪，伯迦得之祖哈勒。","notes":[]},{"n":52,"t":"基列‧耶琳之祖朔巴的子孫是哈羅以和一半米努‧哈人。","notes":["米努‧哈人就是瑪拿哈人"]},{"n":53,"t":"基列‧耶琳的諸族是以帖人、布特人、舒瑪人、密來人，又從這些族中生出瑣拉人和以實陶人來。","notes":[]},{"n":54,"t":"薩瑪的子孫是伯利恆人、尼陀法人、亞他綠‧伯‧約押人、一半瑪拿哈人、瑣利人，","notes":[]},{"n":55,"t":"和住雅比斯眾文士家的特拉人、示米押人、蘇甲人。這都是基尼人利甲家之祖哈末所生的。","notes":[]}]},"3":{"heading":"大衛的兒女","verses":[{"n":1,"t":"大衛在希伯崙所生的兒子記在下面：長子暗嫩是耶斯列人亞希暖生的。次子但以利是迦密人亞比該生的。","notes":[]},{"n":2,"t":"三子押沙龍是基述王達買的女兒瑪迦生的。四子亞多尼雅是哈及生的。","notes":[]},{"n":3,"t":"五子示法提雅是亞比她生的。六子以特念是大衛的妻以格拉生的。","notes":[]},{"n":4,"t":"這六人都是大衛在希伯崙生的。大衛在希伯崙作王七年零六個月，在耶路撒冷作王三十三年。","notes":[]},{"n":5,"t":"大衛在耶路撒冷所生的兒子是示米亞、朔罷、拿單、所羅門。這四人是亞米利的女兒拔‧書亞生的。","notes":[]},{"n":6,"t":"還有益轄、以利沙瑪、以利法列、","notes":[]},{"n":7,"t":"挪迦、尼斐、雅非亞、","notes":[]},{"n":8,"t":"以利沙瑪、以利雅大、以利法列，共九人。","notes":[]},{"n":9,"t":"這都是大衛的兒子，還有他們的妹子她瑪，妃嬪的兒子不在其內。","notes":[]},{"n":10,"t":"所羅門的兒子是羅波安；羅波安的兒子是亞比雅；亞比雅的兒子是亞撒；亞撒的兒子是約沙法；","notes":[],"heads":["所羅門的後裔"]},{"n":11,"t":"約沙法的兒子是約蘭；約蘭的兒子是亞哈謝；亞哈謝的兒子是約阿施；","notes":[]},{"n":12,"t":"約阿施的兒子是亞瑪謝；亞瑪謝的兒子是亞撒利雅；亞撒利雅的兒子是約坦；","notes":[]},{"n":13,"t":"約坦的兒子是亞哈斯；亞哈斯的兒子是希西家；希西家的兒子是瑪拿西；","notes":[]},{"n":14,"t":"瑪拿西的兒子是亞們；亞們的兒子是約西亞；","notes":[]},{"n":15,"t":"約西亞的長子是約哈難，次子是約雅敬，三子是西底家，四子是沙龍。","notes":[]},{"n":16,"t":"約雅敬的兒子是耶哥尼雅和西底家。","notes":[]},{"n":17,"t":"耶哥尼雅被擄。他的兒子是撒拉鐵、","notes":[],"heads":["耶哥尼雅的後裔"]},{"n":18,"t":"瑪基蘭、毗大雅、示拿薩、耶加米、何沙瑪、尼大比雅。","notes":[]},{"n":19,"t":"毗大雅的兒子是所羅巴伯、示每。所羅巴伯的兒子是米書蘭、哈拿尼雅，他們的妹子名叫示羅密。","notes":[]},{"n":20,"t":"米書蘭的兒子是哈舒巴、阿黑、比利家、哈撒底、于沙‧希悉，共五人。","notes":[]},{"n":21,"t":"哈拿尼雅的兒子是毗拉提、耶篩亞。還有利法雅的眾子，亞珥難的眾子，俄巴底亞的眾子，示迦尼的眾子。","notes":[]},{"n":22,"t":"示迦尼的兒子是示瑪雅；示瑪雅的兒子是哈突、以甲、巴利亞、尼利雅、沙法，共六人。","notes":[]},{"n":23,"t":"尼利雅的兒子是以利約乃、希西家、亞斯利干，共三人。","notes":[]},{"n":24,"t":"以利約乃的兒子是何大雅、以利亞實、毗萊雅、阿谷、約哈難、第萊雅、阿拿尼，共七人。","notes":[]}]},"4":{"heading":"復記猶大的後裔","verses":[{"n":1,"t":"猶大的兒子是法勒斯、希斯崙、迦米、戶珥、朔巴。","notes":[]},{"n":2,"t":"朔巴的兒子利亞雅生雅哈；雅哈生亞戶買和拉哈。這是瑣拉人的諸族。","notes":[]},{"n":3,"t":"以坦之祖的兒子是耶斯列、伊施瑪、伊得巴；他們的妹子名叫哈悉勒玻尼。","notes":[]},{"n":4,"t":"基多之祖是毗努伊勒。戶沙之祖是以謝珥。這都是伯利恆之祖以法她的長子戶珥所生的。","notes":[]},{"n":5,"t":"提哥亞之祖亞施戶有兩個妻子：一名希拉，一名拿拉。","notes":[]},{"n":6,"t":"拿拉給亞施戶生亞戶撒、希弗、提米尼、哈轄斯他利。這都是拿拉的兒子。","notes":[]},{"n":7,"t":"希拉的兒子是洗列、瑣轄、伊提南。","notes":[]},{"n":8,"t":"哥斯生亞諾、瑣比巴，並哈崙兒子亞哈黑的諸族。","notes":[]},{"n":9,"t":"雅比斯比他眾弟兄更尊貴，他母親給他起名叫雅比斯，意思說：我生他甚是痛苦。","notes":[]},{"n":10,"t":"雅比斯求告以色列的神說：「甚願你賜福與我，擴張我的境界，常與我同在，保佑我不遭患難，不受艱苦。」神就應允他所求的。","notes":[]},{"n":11,"t":"書哈的弟兄基綠生米黑，米黑是伊施屯之祖。","notes":[],"heads":["其他的家族"]},{"n":12,"t":"伊施屯生伯拉巴、巴西亞，並珥拿轄之祖提欣拿，這都是利迦人。","notes":[]},{"n":13,"t":"基納斯的兒子是俄陀聶、西萊雅。俄陀聶的兒子是哈塔。","notes":[]},{"n":14,"t":"憫挪太生俄弗拉；西萊雅生革‧夏納欣人之祖約押。他們都是匠人。","notes":[]},{"n":15,"t":"耶孚尼的兒子是迦勒；迦勒的兒子是以路、以拉、拿安。以拉的兒子是基納斯。","notes":[]},{"n":16,"t":"耶哈利勒的兒子是西弗、西法、提利、亞撒列。","notes":[]},{"n":17,"t":"以斯拉的兒子是益帖、米列、以弗、雅倫。米列娶法老女兒比提雅為妻，生米利暗、沙買，和以實提摩之祖益巴。米列又娶猶大女子為妻，生基多之祖雅列，梭哥之祖希伯，和撒挪亞之祖耶古鐵。","notes":[],"end":18},{"n":19,"t":"荷第雅的妻是拿含的妹子，她所生的兒子是迦米人基伊拉和瑪迦人以實提摩之祖。","notes":[]},{"n":20,"t":"示門的兒子是暗嫩、林拿、便‧哈南、提倫。以示的兒子是梭黑與便‧梭黑。","notes":[]},{"n":21,"t":"猶大的兒子是示拉；示拉的兒子是利迦之祖珥，瑪利沙之祖拉大，和屬亞實比族織細麻布的各家。","notes":[],"heads":["示拉的後裔"]},{"n":22,"t":"還有約敬、哥西巴人、約阿施、薩拉，就是在摩押地掌權的，又有雅叔比利恆。這都是古時所記載的。","notes":[]},{"n":23,"t":"這些人都是窯匠，是尼他應和基低拉的居民；與王同處，為王做工。","notes":[]},{"n":24,"t":"西緬的兒子是尼母利、雅憫、雅立、謝拉、掃羅。","notes":[],"heads":["西緬的後裔"]},{"n":25,"t":"掃羅的兒子是沙龍；沙龍的兒子是米比衫；米比衫的兒子是米施瑪；","notes":[]},{"n":26,"t":"米施瑪的兒子是哈母利；哈母利的兒子是撒刻；撒刻的兒子是示每。","notes":[]},{"n":27,"t":"示每有十六個兒子，六個女兒，他弟兄的兒女不多，他們各家不如猶大族的人丁增多。","notes":[]},{"n":28,"t":"西緬人住在別是巴、摩拉大、哈薩‧書亞、","notes":[]},{"n":29,"t":"辟拉、以森、陀臘、","notes":[]},{"n":30,"t":"彼土利、何珥瑪、洗革拉、","notes":[]},{"n":31,"t":"伯‧瑪嘉博、哈薩‧蘇撒、伯‧比利、沙拉音，這些城邑直到大衛作王的時候都是屬西緬人的。","notes":[]},{"n":32,"t":"他們的五個城邑是以坦、亞因、臨門、陀健、亞珊；","notes":[]},{"n":33,"t":"還有屬城的鄉村，直到巴力。這是他們的住處，他們都有家譜。","notes":[]},{"n":34,"t":"還有米所巴、雅米勒、亞瑪謝的兒子約沙、","notes":[]},{"n":35,"t":"約珥、約示比的兒子耶戶；約示比是西萊雅的兒子；西萊雅是亞薛的兒子。","notes":[]},{"n":36,"t":"還有以利約乃、雅哥巴、約朔海、亞帥雅、亞底業、耶西篾、比拿雅、","notes":[]},{"n":37,"t":"示非的兒子細撒。示非是亞龍的兒子；亞龍是耶大雅的兒子；耶大雅是申利的兒子；申利是示瑪雅的兒子。","notes":[]},{"n":38,"t":"以上所記的人名都是作族長的，他們宗族的人數增多。","notes":[]},{"n":39,"t":"他們往平原東邊基多口去，尋找牧放羊群的草場，","notes":[]},{"n":40,"t":"尋得肥美的草場地，又寬闊又平靜。從前住那裏的是含族的人。","notes":[]},{"n":41,"t":"以上錄名的人，在猶大王希西家年間，來攻擊含族人的帳棚和那裏所有的米烏尼人，將他們滅盡，就住在他們的地方，直到今日，因為那裏有草場可以牧放羊群。","notes":[]},{"n":42,"t":"這西緬人中，有五百人上西珥山，率領他們的是以示的兒子毗拉提、尼利雅、利法雅，和烏薛，","notes":[]},{"n":43,"t":"殺了逃脫剩下的亞瑪力人，就住在那裏直到今日。","notes":[]}]},"5":{"heading":"呂便的後裔","verses":[{"n":1,"t":"以色列的長子原是呂便；因他污穢了父親的床，他長子的名分就歸了約瑟。只是按家譜他不算長子。","notes":[]},{"n":2,"t":"猶大勝過一切弟兄，君王也是從他而出；長子的名分卻歸約瑟。","notes":[]},{"n":3,"t":"以色列長子呂便的兒子是哈諾、法路、希斯倫、迦米。","notes":[]},{"n":4,"t":"約珥的兒子是示瑪雅；示瑪雅的兒子是歌革；歌革的兒子是示每；","notes":[]},{"n":5,"t":"示每的兒子是米迦；米迦的兒子是利亞雅；利亞雅的兒子是巴力；","notes":[]},{"n":6,"t":"巴力的兒子是備拉。這備拉作呂便支派的首領，被亞述王提革拉‧毗列色擄去。","notes":[]},{"n":7,"t":"他的弟兄照著宗族，按著家譜作族長的是耶利、撒迦利雅、比拉。","notes":[]},{"n":8,"t":"比拉是亞撒的兒子；亞撒是示瑪的兒子；示瑪是約珥的兒子；約珥所住的地方是從亞羅珥直到尼波和巴力‧免，","notes":[]},{"n":9,"t":"又向東延到幼發拉底河這邊的曠野，因為他們在基列地牲畜增多。","notes":[]},{"n":10,"t":"掃羅年間，他們與夏甲人爭戰，夏甲人倒在他們手下，他們就在基列東邊的全地，住在夏甲人的帳棚裏。","notes":[]},{"n":11,"t":"迦得的子孫在呂便對面，住在巴珊地，延到撒迦。","notes":[],"heads":["迦得的後裔"]},{"n":12,"t":"他們中間有作族長的約珥，有作副族長的沙番，還有雅乃和住在巴珊的沙法。","notes":[]},{"n":13,"t":"他們族弟兄是米迦勒、米書蘭、示巴、約賴、雅干、細亞、希伯，共七人。","notes":[]},{"n":14,"t":"這都是亞比孩的兒子。亞比孩是戶利的兒子；戶利是耶羅亞的兒子；耶羅亞是基列的兒子；基列是米迦勒的兒子；米迦勒是耶示篩的兒子；耶示篩是耶哈多的兒子；耶哈多是布斯的兒子。","notes":[]},{"n":15,"t":"還有古尼的孫子、押比疊的兒子亞希。這都是作族長的。","notes":[]},{"n":16,"t":"他們住在基列與巴珊和巴珊的鄉村，並沙崙的郊野，直到四圍的交界。","notes":[]},{"n":17,"t":"這些人在猶大王約坦並在以色列王耶羅波安年間，都載入家譜。","notes":[]},{"n":18,"t":"呂便人、迦得人，和瑪拿西半支派的人，能拿盾牌和刀劍、拉弓射箭、出征善戰的勇士共有四萬四千七百六十名。","notes":[],"heads":["呂便迦得瑪拿西族的軍隊"]},{"n":19,"t":"他們與夏甲人、伊突人、拿非施人、挪答人爭戰。","notes":[]},{"n":20,"t":"他們得了神的幫助，夏甲人和跟隨夏甲的人都交在他們手中；因為他們在陣上呼求神，倚賴神，神就應允他們。","notes":[]},{"n":21,"t":"他們擄掠了夏甲人的牲畜，有駱駝五萬，羊二十五萬，驢二千；又有人十萬。","notes":[]},{"n":22,"t":"敵人被殺仆倒的甚多，因為這爭戰是出乎神。他們就住在敵人的地上，直到被擄的時候。","notes":[]},{"n":23,"t":"瑪拿西半支派的人住在那地。從巴珊延到巴力‧黑們、示尼珥與黑門山。","notes":[],"heads":["瑪拿西半支派"]},{"n":24,"t":"他們的族長是以弗、以示、以列、亞斯列、耶利米、何達威雅、雅疊，都是大能的勇士，是有名的人，也是作族長的。","notes":[]},{"n":25,"t":"他們得罪了他們列祖的神，隨從那地之民的神行邪淫；這民就是神在他們面前所除滅的。","notes":[],"heads":["二支派半人叛逆神"]},{"n":26,"t":"故此，以色列的神激動亞述王普勒和亞述王提革拉‧毗列色的心，他們就把呂便人、迦得人、瑪拿西半支派的人擄到哈臘、哈博、哈拉與歌散河邊，直到今日還在那裏。","notes":[]}]},"6":{"heading":"利未的後裔","verses":[{"n":1,"t":"利未的兒子是革順、哥轄、米拉利。","notes":[]},{"n":2,"t":"哥轄的兒子是暗蘭、以斯哈、希伯倫、烏薛。","notes":[]},{"n":3,"t":"暗蘭的兒子是亞倫、摩西，還有女兒米利暗。亞倫的兒子是拿答、亞比戶、以利亞撒、以他瑪。","notes":[]},{"n":4,"t":"以利亞撒生非尼哈；非尼哈生亞比書；","notes":[]},{"n":5,"t":"亞比書生布基；布基生烏西；","notes":[]},{"n":6,"t":"烏西生西拉希雅；西拉希雅生米拉約；","notes":[]},{"n":7,"t":"米拉約生亞瑪利雅；亞瑪利雅生亞希突；","notes":[]},{"n":8,"t":"亞希突生撒督；撒督生亞希瑪斯；","notes":[]},{"n":9,"t":"亞希瑪斯生亞撒利雅；亞撒利雅生約哈難；","notes":[]},{"n":10,"t":"約哈難生亞撒利雅（這亞撒利雅在所羅門於耶路撒冷所建造的殿中，供祭司的職分）；","notes":[]},{"n":11,"t":"亞撒利雅生亞瑪利雅；亞瑪利雅生亞希突；","notes":[]},{"n":12,"t":"亞希突生撒督；撒督生沙龍；","notes":[]},{"n":13,"t":"沙龍生希勒家；希勒家生亞撒利雅；","notes":[]},{"n":14,"t":"亞撒利雅生西萊雅；西萊雅生約薩答。","notes":[]},{"n":15,"t":"當耶和華藉尼布甲尼撒的手擄掠猶大和耶路撒冷人的時候，這約薩答也被擄去。","notes":[]},{"n":16,"t":"利未的兒子是革順、哥轄、米拉利。","notes":[],"heads":["利未的其餘後裔"]},{"n":17,"t":"革順的兒子名叫立尼、示每。","notes":[]},{"n":18,"t":"哥轄的兒子是暗蘭、以斯哈、希伯倫、烏薛。","notes":[]},{"n":19,"t":"米拉利的兒子是抹利、母示。這是按著利未人宗族分的各家。","notes":[]},{"n":20,"t":"革順的兒子是立尼；立尼的兒子是雅哈；雅哈的兒子是薪瑪；","notes":[]},{"n":21,"t":"薪瑪的兒子是約亞；約亞的兒子是易多；易多的兒子是謝拉；謝拉的兒子是耶特賴。","notes":[]},{"n":22,"t":"哥轄的兒子是亞米拿達；亞米拿達的兒子是可拉；可拉的兒子是亞惜；","notes":[]},{"n":23,"t":"亞惜的兒子是以利加拿；以利加拿的兒子是以比雅撒；以比雅撒的兒子是亞惜；","notes":[]},{"n":24,"t":"亞惜的兒子是他哈；他哈的兒子是烏列；烏列的兒子是烏西雅；烏西雅的兒子是少羅。","notes":[]},{"n":25,"t":"以利加拿的兒子是亞瑪賽和亞希摩。","notes":[]},{"n":26,"t":"亞希摩的兒子是以利加拿；以利加拿的兒子是瑣菲；瑣菲的兒子是拿哈；","notes":[]},{"n":27,"t":"拿哈的兒子是以利押；以利押的兒子是耶羅罕；耶羅罕的兒子是以利加拿；以利加拿的兒子是撒母耳。","notes":[]},{"n":28,"t":"撒母耳的長子是約珥，次子是亞比亞。","notes":[]},{"n":29,"t":"米拉利的兒子是抹利；抹利的兒子是立尼；立尼的兒子是示每；示每的兒子是烏撒；","notes":[]},{"n":30,"t":"烏撒的兒子是示米亞；示米亞的兒子是哈基雅；哈基雅的兒子是亞帥雅。","notes":[]},{"n":31,"t":"約櫃安設之後，大衛派人在耶和華殿中管理歌唱的事。","notes":[],"heads":["聖殿中的歌者"]},{"n":32,"t":"他們就在會幕前當歌唱的差，及至所羅門在耶路撒冷建造了耶和華的殿，他們便按著班次供職。","notes":[]},{"n":33,"t":"供職的人和他們的子孫記在下面：哥轄的子孫中有歌唱的希幔。希幔是約珥的兒子；約珥是撒母耳的兒子；","notes":[]},{"n":34,"t":"撒母耳是以利加拿的兒子；以利加拿是耶羅罕的兒子；耶羅罕是以列的兒子；以列是陀亞的兒子；","notes":[]},{"n":35,"t":"陀亞是蘇弗的兒子；蘇弗是以利加拿的兒子；以利加拿是瑪哈的兒子；瑪哈是亞瑪賽的兒子；","notes":[]},{"n":36,"t":"亞瑪賽是以利加拿的兒子；以利加拿是約珥的兒子；約珥是亞撒利雅的兒子；亞撒利雅是西番雅的兒子；","notes":[]},{"n":37,"t":"西番雅是他哈的兒子；他哈是亞惜的兒子；亞惜是以比雅撒的兒子；以比雅撒是可拉的兒子；","notes":[]},{"n":38,"t":"可拉是以斯哈的兒子；以斯哈是哥轄的兒子；哥轄是利未的兒子；利未是以色列的兒子。","notes":[]},{"n":39,"t":"希幔的族兄亞薩是比利家的兒子，亞薩在希幔右邊供職。比利家是示米亞的兒子；","notes":[]},{"n":40,"t":"示米亞是米迦勒的兒子；米迦勒是巴西雅的兒子；巴西雅是瑪基雅的兒子；","notes":[]},{"n":41,"t":"瑪基雅是伊特尼的兒子；伊特尼是謝拉的兒子；謝拉是亞大雅的兒子；","notes":[]},{"n":42,"t":"亞大雅是以探的兒子；以探是薪瑪的兒子；薪瑪是示每的兒子；","notes":[]},{"n":43,"t":"示每是雅哈的兒子；雅哈是革順的兒子。革順是利未的兒子。","notes":[]},{"n":44,"t":"他們的族弟兄米拉利的子孫，在他們左邊供職的有以探。以探是基示的兒子；基示是亞伯底的兒子；亞伯底是瑪鹿的兒子；","notes":[]},{"n":45,"t":"瑪鹿是哈沙比雅的兒子；哈沙比雅是亞瑪謝的兒子；亞瑪謝是希勒家的兒子；","notes":[]},{"n":46,"t":"希勒家是暗西的兒子；暗西是巴尼的兒子；巴尼是沙麥的兒子；","notes":[]},{"n":47,"t":"沙麥是末力的兒子；末力是母示的兒子；母示是米拉利的兒子；米拉利是利未的兒子。","notes":[]},{"n":48,"t":"他們的族弟兄利未人也被派辦神殿中的一切事。","notes":[]},{"n":49,"t":"亞倫和他的子孫在燔祭壇和香壇上獻祭燒香，又在至聖所辦理一切的事，為以色列人贖罪，是照神僕人摩西所吩咐的。","notes":[],"heads":["亞倫的後裔"]},{"n":50,"t":"亞倫的兒子是以利亞撒；以利亞撒的兒子是非尼哈；非尼哈的兒子是亞比書；","notes":[]},{"n":51,"t":"亞比書的兒子是布基；布基的兒子是烏西；烏西的兒子是西拉希雅；","notes":[]},{"n":52,"t":"西拉希雅的兒子是米拉約；米拉約的兒子是亞瑪利雅；亞瑪利雅的兒子是亞希突；","notes":[]},{"n":53,"t":"亞希突的兒子是撒督；撒督的兒子是亞希瑪斯。","notes":[]},{"n":54,"t":"他們的住處按著境內的營寨，記在下面：哥轄族亞倫的子孫先拈鬮得地，","notes":[],"heads":["利未支派的居地"]},{"n":55,"t":"在猶大地中得了希伯崙和四圍的郊野；","notes":[]},{"n":56,"t":"只是屬城的田地和村莊都為耶孚尼的兒子迦勒所得。","notes":[]},{"n":57,"t":"亞倫的子孫得了逃城希伯崙，又得了立拿與其郊野，雅提珥、以實提莫與其郊野；","notes":[]},{"n":58,"t":"希崙與其郊野，底璧與其郊野，","notes":[]},{"n":59,"t":"亞珊與其郊野，伯‧示麥與其郊野。","notes":[]},{"n":60,"t":"在便雅憫支派的地中，得了迦巴與其郊野，阿勒篾與其郊野，亞拿突與其郊野。他們諸家所得的城共十三座。","notes":[]},{"n":61,"t":"哥轄族其餘的人又拈鬮，在瑪拿西半支派的地中得了十座城。","notes":[]},{"n":62,"t":"革順族按著宗族，在以薩迦支派的地中，亞設支派的地中，拿弗他利支派的地中，巴珊內瑪拿西支派的地中，得了十三座城。","notes":[]},{"n":63,"t":"米拉利族按著宗族拈鬮，在呂便支派的地中，迦得支派的地中，西布倫支派的地中，得了十二座城。","notes":[]},{"n":64,"t":"以色列人將這些城與其郊野給了利未人。","notes":[]},{"n":65,"t":"這以上錄名的城，在猶大、西緬、便雅憫三支派的地中，以色列人拈鬮給了他們。","notes":[]},{"n":66,"t":"哥轄族中有幾家在以法蓮支派的地中也得了城邑，","notes":[]},{"n":67,"t":"在以法蓮山地得了逃城示劍與其郊野，又得了基色與其郊野，","notes":[]},{"n":68,"t":"約緬與其郊野，伯‧和崙與其郊野，","notes":[]},{"n":69,"t":"亞雅崙與其郊野，迦特‧臨門與其郊野。","notes":[]},{"n":70,"t":"哥轄族其餘的人在瑪拿西半支派的地中得了亞乃與其郊野，比連與其郊野。","notes":[]},{"n":71,"t":"革順族在瑪拿西半支派的地中得了巴珊的哥蘭與其郊野，亞斯他錄與其郊野；","notes":[]},{"n":72,"t":"又在以薩迦支派的地中得了基低斯與其郊野，大比拉與其郊野，","notes":[]},{"n":73,"t":"拉末與其郊野，亞年與其郊野；","notes":[]},{"n":74,"t":"在亞設支派的地中得了瑪沙與其郊野，押頓與其郊野，","notes":[]},{"n":75,"t":"戶割與其郊野，利合與其郊野；","notes":[]},{"n":76,"t":"在拿弗他利支派的地中得了加利利的基低斯與其郊野，哈們與其郊野，基列亭與其郊野。","notes":[]},{"n":77,"t":"還有米拉利族的人在西布倫支派的地中得了臨摩挪與其郊野，他泊與其郊野；","notes":[]},{"n":78,"t":"又在耶利哥的約旦河東，在呂便支派的地中得了曠野的比悉與其郊野，雅哈撒與其郊野，","notes":[]},{"n":79,"t":"基底莫與其郊野，米法押與其郊野；","notes":[]},{"n":80,"t":"又在迦得支派的地中得了基列的拉末與其郊野，瑪哈念與其郊野，","notes":[]},{"n":81,"t":"希實本與其郊野，雅謝與其郊野。","notes":[]}]},"7":{"heading":"以薩迦的後裔","verses":[{"n":1,"t":"以薩迦的兒子是陀拉、普瓦、雅述、伸崙，共四人。","notes":["在創世記第四十六章十三節是約伯"]},{"n":2,"t":"陀拉的兒子是烏西、利法雅、耶勒、雅買、易伯散、示母利，都是陀拉的族長，是大能的勇士。到大衛年間，他們的人數共有二萬二千六百名。","notes":[]},{"n":3,"t":"烏西的兒子是伊斯拉希；伊斯拉希的兒子是米迦勒、俄巴底亞、約珥、伊示雅，共五人，都是族長。","notes":[]},{"n":4,"t":"他們所率領的，按著宗族出戰的軍隊，共有三萬六千人，因為他們的妻和子眾多。","notes":[]},{"n":5,"t":"他們的族弟兄在以薩迦各族中都是大能的勇士，按著家譜計算共有八萬七千人。","notes":[]},{"n":6,"t":"便雅憫的兒子是比拉、比結、耶疊，共三人。","notes":[],"heads":["便雅憫和但的後裔"]},{"n":7,"t":"比拉的兒子是以斯本、烏西、烏薛、耶利摩、以利，共五人，都是族長，是大能的勇士。按著家譜計算，他們的子孫共有二萬二千零三十四人。","notes":[]},{"n":8,"t":"比結的兒子是細米拉、約阿施、以利以謝、以利約乃、暗利、耶利摩、亞比雅、亞拿突、亞拉篾。這都是比結的兒子。","notes":[]},{"n":9,"t":"他們都是族長，是大能的勇士。按著家譜計算，他們的子孫共有二萬零二百人。","notes":[]},{"n":10,"t":"耶疊的兒子是比勒罕；比勒罕的兒子是耶烏施、便雅憫、以忽、基拿拿、細坦、他施、亞希沙哈。","notes":[]},{"n":11,"t":"這都是耶疊的兒子，都是族長，是大能的勇士；他們的子孫能上陣打仗的，共有一萬七千二百人。","notes":[]},{"n":12,"t":"還有以珥的兒子書品、戶品，並亞黑的兒子戶伸。","notes":[]},{"n":13,"t":"拿弗他利的兒子是雅薛、沽尼、耶色、沙龍。這都是辟拉的子孫。","notes":[],"heads":["拿弗他利的後裔"]},{"n":14,"t":"瑪拿西的兒子亞斯列是他妾亞蘭人所生的，又生了基列之父瑪吉。","notes":[],"heads":["瑪拿西的後裔"]},{"n":15,"t":"瑪吉娶的妻是戶品、書品的妹子，名叫瑪迦。瑪拿西的次子名叫西羅非哈；西羅非哈但有幾個女兒。","notes":[]},{"n":16,"t":"瑪吉的妻瑪迦生了一個兒子，起名叫毗利施。毗利施的兄弟名叫示利施；示利施的兒子是烏蘭和利金。","notes":[]},{"n":17,"t":"烏蘭的兒子是比但。這都是基列的子孫。基列是瑪吉的兒子，瑪吉是瑪拿西的兒子。","notes":[]},{"n":18,"t":"基列的妹子哈摩利吉生了伊施荷、亞比以謝、瑪拉。（","notes":[]},{"n":19,"t":"示米大的兒子是亞現、示劍、利克希、阿尼安。）","notes":[]},{"n":20,"t":"以法蓮的兒子是書提拉；書提拉的兒子是比列；比列的兒子是他哈；他哈的兒子是以拉大；以拉大的兒子是他哈；","notes":[],"heads":["以法蓮的後裔"]},{"n":21,"t":"他哈的兒子是撒拔；撒拔的兒子是書提拉。以法蓮又生以謝、以列；這二人因為下去奪取迦特人的牲畜，被本地的迦特人殺了。","notes":[]},{"n":22,"t":"他們的父親以法蓮為他們悲哀了多日，他的弟兄都來安慰他。","notes":[]},{"n":23,"t":"以法蓮與妻同房，他妻就懷孕生了一子，以法蓮因為家裏遭禍，就給這兒子起名叫比利亞。","notes":[]},{"n":24,"t":"他的女兒名叫舍伊拉，就是建築上伯‧和崙、下伯‧和崙與烏羨‧舍伊拉的。","notes":[]},{"n":25,"t":"比利亞的兒子是利法和利悉。利悉的兒子是他拉；他拉的兒子是他罕；","notes":[]},{"n":26,"t":"他罕的兒子是拉但；拉但的兒子是亞米忽；亞米忽的兒子是以利沙瑪；","notes":[]},{"n":27,"t":"以利沙瑪的兒子是嫩；嫩的兒子是約書亞。","notes":[]},{"n":28,"t":"以法蓮人的地業和住處是伯特利與其村莊；東邊拿蘭，西邊基色與其村莊；示劍與其村莊，直到迦薩與其村莊；","notes":[]},{"n":29,"t":"還有靠近瑪拿西人的境界，伯‧善與其村莊；他納與其村莊；米吉多與其村莊；多珥與其村莊。以色列兒子約瑟的子孫住在這些地方。","notes":[]},{"n":30,"t":"亞設的兒子是音拿、亦施瓦、亦施韋、比利亞，還有他們的妹子西拉。","notes":[],"heads":["亞設的後裔"]},{"n":31,"t":"比利亞的兒子是希別、瑪結；瑪結是比撒威的父親。","notes":[]},{"n":32,"t":"希別生雅弗勒、朔默、何坦，和他們的妹子書雅。","notes":[]},{"n":33,"t":"雅弗勒的兒子是巴薩、賓哈、亞施法。這都是雅弗勒的兒子。","notes":[]},{"n":34,"t":"朔默的兒子是亞希、羅迦、耶戶巴、亞蘭。","notes":[]},{"n":35,"t":"朔默兄弟希連的兒子是瑣法、音那、示利斯、亞抹。","notes":[]},{"n":36,"t":"瑣法的兒子是書亞、哈尼弗、書阿勒、比利、音拉、","notes":[]},{"n":37,"t":"比悉、河得、珊瑪、施沙、益蘭、比拉。","notes":[]},{"n":38,"t":"益帖的兒子是耶孚尼、毗斯巴、亞拉。","notes":[]},{"n":39,"t":"烏拉的兒子是亞拉、漢尼業、利寫。","notes":[]},{"n":40,"t":"這都是亞設的子孫，都是族長，是精壯大能的勇士，也是首領中的頭目，按著家譜計算，他們的子孫能出戰的共有二萬六千人。","notes":[]}]},"8":{"heading":"便雅憫的後裔","verses":[{"n":1,"t":"便雅憫的長子比拉，次子亞實別，三子亞哈拉，","notes":[]},{"n":2,"t":"四子挪哈，五子拉法。","notes":[]},{"n":3,"t":"比拉的兒子是亞大、基拉、亞比忽、","notes":[]},{"n":4,"t":"亞比書、乃幔、亞何亞、","notes":[]},{"n":5,"t":"基拉、示孚汛、戶蘭。","notes":[]},{"n":6,"t":"以忽的兒子作迦巴居民的族長，被擄到瑪拿轄；","notes":[]},{"n":7,"t":"以忽的兒子乃幔、亞希亞、基拉也被擄去。基拉生烏撒、亞希忽。","notes":[]},{"n":8,"t":"沙哈連休他二妻戶伸和巴拉之後，在摩押地生了兒子。","notes":[]},{"n":9,"t":"他與妻賀得同房，生了約巴、洗比雅、米沙、瑪拉干、","notes":[]},{"n":10,"t":"耶烏斯、沙迦、米瑪。他這些兒子都是族長。","notes":[]},{"n":11,"t":"他的妻戶伸給他生的兒子有亞比突、以利巴力。","notes":[]},{"n":12,"t":"以利巴力的兒子是希伯、米珊、沙麥。沙麥建立阿挪和羅德二城與其村莊。","notes":[]},{"n":13,"t":"又有比利亞和示瑪是亞雅崙居民的族長，是驅逐迦特人的。","notes":[],"heads":["在亞雅崙的便雅憫人"]},{"n":14,"t":"亞希約、沙煞、耶利末、","notes":[]},{"n":15,"t":"西巴第雅、亞拉得、亞得、","notes":[]},{"n":16,"t":"米迦勒、伊施巴、約哈都是比利亞的兒子。","notes":[]},{"n":17,"t":"西巴第雅、米書蘭、希西基、希伯、","notes":[],"heads":["在耶路撒冷的便雅憫人"]},{"n":18,"t":"伊施米萊、伊斯利亞、約巴都是以利巴力的兒子。","notes":[]},{"n":19,"t":"雅金、細基利、撒底、","notes":[]},{"n":20,"t":"以利乃、洗勒太、以列、","notes":[]},{"n":21,"t":"亞大雅、比拉雅、申拉都是示每的兒子。","notes":[]},{"n":22,"t":"伊施班、希伯、以列、","notes":[]},{"n":23,"t":"亞伯頓、細基利、哈難、","notes":[]},{"n":24,"t":"哈拿尼雅、以攔、安陀提雅、","notes":[]},{"n":25,"t":"伊弗底雅、毗努伊勒都是沙煞的兒子。","notes":[]},{"n":26,"t":"珊示萊、示哈利、亞他利雅、","notes":[]},{"n":27,"t":"雅利西、以利亞、細基利都是耶羅罕的兒子。","notes":[]},{"n":28,"t":"這些人都是著名的族長，住在耶路撒冷。","notes":[]},{"n":29,"t":"在基遍住的有基遍的父親耶利。他的妻名叫瑪迦；","notes":[],"heads":["在基遍和耶路撒冷的便雅憫人"]},{"n":30,"t":"他長子是亞伯頓。他又生蘇珥、基士、巴力、拿答、","notes":[]},{"n":31,"t":"基多、亞希約、撒迦、米基羅。","notes":[]},{"n":32,"t":"米基羅生示米暗。這些人和他們的弟兄在耶路撒冷對面居住。","notes":[]},{"n":33,"t":"尼珥生基士；基士生掃羅；掃羅生約拿單、麥基舒亞、亞比拿達、伊施‧巴力。","notes":[],"heads":["掃羅王的家族"]},{"n":34,"t":"約拿單的兒子是米力‧巴力；米力‧巴力生米迦。","notes":["在撒母耳下四章四節是米非波設"]},{"n":35,"t":"米迦的兒子是毗敦、米勒、他利亞、亞哈斯；","notes":[]},{"n":36,"t":"亞哈斯生耶何阿達；耶何阿達生亞拉篾、亞斯瑪威、心利；心利生摩撒；","notes":[]},{"n":37,"t":"摩撒生比尼亞；比尼亞的兒子是拉法；拉法的兒子是以利亞薩；以利亞薩的兒子是亞悉。","notes":[]},{"n":38,"t":"亞悉有六個兒子，他們的名字是亞斯利干、波基路、以實瑪利、示亞利雅、俄巴底雅、哈難。這都是亞悉的兒子。","notes":[]},{"n":39,"t":"亞悉兄弟以設的長子是烏蘭，次子耶烏施，三子是以利法列。","notes":[]},{"n":40,"t":"烏蘭的兒子都是大能的勇士，是弓箭手，他們有許多的子孫，共一百五十名，都是便雅憫人。","notes":[]}]},"9":{"heading":"被擄歸回的人","verses":[{"n":1,"t":"以色列人都按家譜計算，寫在以色列諸王記上。猶大人因犯罪就被擄到巴比倫。","notes":[]},{"n":2,"t":"先從巴比倫回來，住在自己地業城邑中的有以色列人、祭司、利未人、尼提寧的首領。","notes":[]},{"n":3,"t":"住在耶路撒冷的有猶大人、便雅憫人、以法蓮人、瑪拿西人。","notes":[]},{"n":4,"t":"猶大兒子法勒斯的子孫中有烏太。烏太是亞米忽的兒子；亞米忽是暗利的兒子；暗利是音利的兒子；音利是巴尼的兒子。","notes":[]},{"n":5,"t":"示羅的子孫中有長子亞帥雅和他的眾子。","notes":[]},{"n":6,"t":"謝拉的子孫中有耶烏利和他的弟兄，共六百九十人。","notes":[]},{"n":7,"t":"便雅憫人中有哈西努的曾孫、何達威雅的孫子、米書蘭的兒子撒路，","notes":[]},{"n":8,"t":"又有耶羅罕的兒子伊比尼雅，米基立的孫子、烏西的兒子以拉，伊比尼雅的曾孫、流珥的孫子、示法提雅的兒子米書蘭，","notes":[]},{"n":9,"t":"和他們的族弟兄，按著家譜計算共有九百五十六名。這些人都是他們的族長。","notes":[]},{"n":10,"t":"祭司中有耶大雅、耶何雅立、雅斤，","notes":[],"heads":["住在耶路撒冷的祭司"]},{"n":11,"t":"還有管理神殿希勒家的兒子亞薩利雅。希勒家是米書蘭的兒子；米書蘭是撒督的兒子；撒督是米拉約的兒子；米拉約是亞希突的兒子。","notes":[]},{"n":12,"t":"有瑪基雅的曾孫、巴施戶珥的孫子、耶羅罕的兒子亞大雅，又有亞第業的兒子瑪賽；亞第業是雅希細拉的兒子；雅希細拉是米書蘭的兒子；米書蘭是米實利密的兒子；米實利密是音麥的兒子。","notes":[]},{"n":13,"t":"他們和眾弟兄都是族長，共有一千七百六十人，是善於做神殿使用之工的。","notes":[]},{"n":14,"t":"利未人米拉利的子孫中，有哈沙比雅的曾孫、押利甘的孫子、哈述的兒子示瑪雅。","notes":[],"heads":["住在耶路撒冷的利未人"]},{"n":15,"t":"有拔巴甲、黑勒施、迦拉，並亞薩的曾孫、細基利的孫子、米迦的兒子瑪探雅，","notes":[]},{"n":16,"t":"又有耶杜頓的曾孫、迦拉的孫子、示瑪雅的兒子俄巴底，還有以利加拿的孫子、亞撒的兒子比利家。他們都住在尼陀法人的村莊。","notes":[]},{"n":17,"t":"守門的是沙龍、亞谷、達們、亞希幔，和他們的弟兄；沙龍為長。","notes":[],"heads":["住在耶路撒冷的聖殿守衛"]},{"n":18,"t":"從前這些人看守朝東的王門，如今是利未營中守門的。","notes":[]},{"n":19,"t":"可拉的曾孫、以比雅撒的孫子、可利的兒子沙龍，和他的族弟兄可拉人都管理使用之工，並守會幕的門。他們的祖宗曾管理耶和華的營盤，又把守營門。","notes":[]},{"n":20,"t":"從前以利亞撒的兒子非尼哈管理他們，耶和華也與他同在。","notes":[]},{"n":21,"t":"米施利米雅的兒子撒迦利雅是看守會幕之門的。","notes":[]},{"n":22,"t":"被選守門的人共有二百一十二名。他們在自己的村莊，按著家譜計算，是大衛和先見撒母耳所派當這緊要職任的。","notes":[]},{"n":23,"t":"他們和他們的子孫按著班次看守耶和華殿的門，就是會幕的門。","notes":[]},{"n":24,"t":"在東西南北，四方都有守門的。","notes":[]},{"n":25,"t":"他們的族弟兄住在村莊，每七日來與他們換班。","notes":[]},{"n":26,"t":"這四個門領都是利未人，各有緊要的職任，看守神殿的倉庫。","notes":[]},{"n":27,"t":"他們住在神殿的四圍，是因委託他們守殿，要每日早晨開門。","notes":[]},{"n":28,"t":"利未人中有管理使用器皿的，按著數目拿出拿入；","notes":[],"heads":["其餘的利未人"]},{"n":29,"t":"又有人管理器具和聖所的器皿，並細麵、酒、油、乳香、香料。","notes":[]},{"n":30,"t":"祭司中有人用香料做膏油。","notes":[]},{"n":31,"t":"利未人瑪他提雅是可拉族沙龍的長子，他緊要的職任是管理盤中烤的物。","notes":[]},{"n":32,"t":"他們族弟兄哥轄子孫中，有管理陳設餅的，每安息日預備擺列。","notes":[]},{"n":33,"t":"歌唱的有利未人的族長，住在屬殿的房屋，晝夜供職，不做別樣的工。","notes":[]},{"n":34,"t":"以上都是利未人著名的族長，住在耶路撒冷。","notes":[]},{"n":35,"t":"在基遍住的有基遍的父親耶利。他的妻名叫瑪迦；","notes":[],"heads":["掃羅王的祖先和後代"]},{"n":36,"t":"他長子是亞伯頓。他又生蘇珥、基士、巴力、尼珥、拿答、","notes":[]},{"n":37,"t":"基多、亞希約、撒迦利雅、米基羅。","notes":[]},{"n":38,"t":"米基羅生示米暗。這些人和他們的弟兄在耶路撒冷對面居住。","notes":[]},{"n":39,"t":"尼珥生基士；基士生掃羅；掃羅生約拿單、麥基舒亞、亞比拿達、伊施‧巴力。","notes":[]},{"n":40,"t":"約拿單的兒子是米力‧巴力；米力‧巴力生米迦。","notes":["就是米非波設"]},{"n":41,"t":"米迦的兒子是毗敦、米勒、他利亞、亞哈斯。","notes":[]},{"n":42,"t":"亞哈斯生雅拉；雅拉生亞拉篾、亞斯瑪威、心利；心利生摩撒；","notes":[]},{"n":43,"t":"摩撒生比尼亞；比尼亞生利法雅；利法雅的兒子是以利亞薩；以利亞薩的兒子是亞悉。","notes":[]},{"n":44,"t":"亞悉有六個兒子，他們的名字是亞斯利干、波基路、以實瑪利、示亞利雅、俄巴底雅、哈難。這都是亞悉的兒子。","notes":[]}]},"10":{"heading":"掃羅逝世","verses":[{"n":1,"t":"非利士人與以色列人爭戰，以色列人在非利士人面前逃跑，在基利波山有被殺仆倒的。","notes":[]},{"n":2,"t":"非利士人緊追掃羅和他兒子們，就殺了掃羅的兒子約拿單、亞比拿達、麥基舒亞。","notes":[]},{"n":3,"t":"勢派甚大，掃羅被弓箭手追上，射傷甚重，","notes":[]},{"n":4,"t":"就吩咐拿他兵器的人說：「你拔出刀來，將我刺死，免得那些未受割禮的人來凌辱我。」但拿兵器的人甚懼怕，不肯刺他；","notes":[]},{"n":5,"t":"掃羅就自己伏在刀上死了。拿兵器的人見掃羅已死，也伏在刀上死了。","notes":[]},{"n":6,"t":"這樣，掃羅和他三個兒子，並他的全家都一同死亡。","notes":[]},{"n":7,"t":"住平原的以色列眾人見以色列軍兵逃跑，掃羅和他兒子都死了，也就棄城逃跑，非利士人便來住在其中。","notes":[]},{"n":8,"t":"次日，非利士人來剝那被殺之人的衣服，看見掃羅和他兒子仆倒在基利波山，","notes":[]},{"n":9,"t":"就剝了他的軍裝，割下他的首級，打發人到 非利士地的四境報信與他們的偶像和眾民，","notes":["到：或譯送到"]},{"n":10,"t":"又將掃羅的軍裝放在他們神的廟裏，將他的首級釘在大袞廟中。","notes":[]},{"n":11,"t":"基列‧雅比人聽見非利士人向掃羅所行的一切事，","notes":[]},{"n":12,"t":"他們中間所有的勇士就起身前去，將掃羅和他兒子的屍身送到雅比，將他們的屍骨葬在雅比的橡樹下，就禁食七日。","notes":[]},{"n":13,"t":"這樣，掃羅死了。因為他干犯耶和華，沒有遵守耶和華的命；又因他求問交鬼的婦人，","notes":[]},{"n":14,"t":"沒有求問耶和華，所以耶和華使他被殺，把國歸於耶西的兒子大衛。","notes":[]}]},"11":{"heading":"大衛作以色列和猶大的王","verses":[{"n":1,"t":"以色列眾人聚集到希伯崙見大衛，說：「我們原是你的骨肉。","notes":[]},{"n":2,"t":"從前掃羅作王的時候，率領以色列人出入的是你；耶和華－你的神也曾應許你說：『你必牧養我的民以色列，作以色列的君。』」","notes":[]},{"n":3,"t":"於是以色列的長老都來到希伯崙見大衛王。大衛在希伯崙耶和華面前與他們立約，他們就膏大衛作以色列的王，是照耶和華藉撒母耳所說的話。","notes":[]},{"n":4,"t":"大衛和以色列眾人到了耶路撒冷，就是耶布斯；那時耶布斯人住在那裏。","notes":[]},{"n":5,"t":"耶布斯人對大衛說：「你決不能進這地方。」然而大衛攻取錫安的保障，就是大衛的城。","notes":[]},{"n":6,"t":"大衛說：「誰先攻打耶布斯人，必作首領元帥。」洗魯雅的兒子約押先上去，就作了元帥。","notes":[]},{"n":7,"t":"大衛住在保障裏，所以那保障叫作大衛城。","notes":[]},{"n":8,"t":"大衛又從米羅起，四圍建築城牆，其餘的是約押修理。","notes":[]},{"n":9,"t":"大衛日見強盛，因為萬軍之耶和華與他同在。","notes":[]},{"n":10,"t":"以下記錄跟隨大衛勇士的首領，就是奮勇幫助他得國、照著耶和華吩咐以色列人的話、與以色列人一同立他作王的。","notes":[],"heads":["大衛的有名將領"]},{"n":11,"t":"大衛勇士的數目記在下面：哈革摩尼的兒子雅朔班，他是軍長的統領，一時舉槍殺了三百人。","notes":[]},{"n":12,"t":"其次是亞合人朵多的兒子以利亞撒，他是三個勇士裏的一個。","notes":[]},{"n":13,"t":"他從前與大衛在巴斯‧達閔，非利士人聚集要打仗。那裏有一塊長滿大麥的田，眾民就在非利士人面前逃跑；","notes":[]},{"n":14,"t":"這勇士便站在那田間擊殺非利士人，救護了那田。耶和華使以色列人大獲全勝。","notes":[]},{"n":15,"t":"三十個勇士中的三個人下到磐石那裏，進了亞杜蘭洞見大衛；非利士的軍隊在利乏音谷安營。","notes":[]},{"n":16,"t":"那時大衛在山寨，非利士人的防營在伯利恆。","notes":[]},{"n":17,"t":"大衛渴想，說：「甚願有人將伯利恆城門旁井裏的水打來給我喝！」","notes":[]},{"n":18,"t":"這三個勇士就闖過非利士人的營盤，從伯利恆城門旁的井裏打水，拿來奉給大衛。他卻不肯喝，將水奠在耶和華面前，","notes":[]},{"n":19,"t":"說：「我的神啊，這三個人冒死去打水，這水好像他們的血一般，我斷不敢喝！」如此，大衛不肯喝。這是三個勇士所做的事。","notes":[]},{"n":20,"t":"約押的兄弟亞比篩是這三個勇士的首領；他舉槍殺了三百人，就在三個勇士裏得了名。","notes":[]},{"n":21,"t":"他在這三個勇士裏是最尊貴的，所以作他們的首領；只是不及前三個勇士。","notes":[]},{"n":22,"t":"有甲薛勇士耶何耶大的兒子比拿雅行過大能的事：他殺了摩押人亞利伊勒的兩個兒子，又在下雪的時候下坑裏去殺了一個獅子，","notes":[]},{"n":23,"t":"又殺了一個埃及人。埃及人身高五肘，手裏拿著槍，槍桿粗如織布的機軸；比拿雅只拿著棍子下去，從埃及人手裏奪過槍來，用那槍將他刺死。","notes":[]},{"n":24,"t":"這是耶何耶大的兒子比拿雅所行的事，就在三個勇士裏得了名。","notes":[]},{"n":25,"t":"他比那三十個勇士都尊貴，只是不及前三個勇士。大衛立他作護衛長。","notes":[]},{"n":26,"t":"軍中的勇士有約押的兄弟亞撒黑，伯利恆人朵多的兒子伊勒哈難，","notes":[]},{"n":27,"t":"哈律人沙瑪，比倫人希利斯，","notes":[]},{"n":28,"t":"提哥亞人益吉的兒子以拉，亞拿突人亞比以謝，","notes":[]},{"n":29,"t":"戶沙人西比該，亞合人以來，","notes":[]},{"n":30,"t":"尼陀法人瑪哈萊，尼陀法人巴拿的兒子希立，","notes":[]},{"n":31,"t":"便雅憫族基比亞人利拜的兒子以太，比拉頓人比拿雅，","notes":[]},{"n":32,"t":"迦實溪人戶萊，亞拉巴人亞比，","notes":[]},{"n":33,"t":"巴路米人押斯瑪弗，沙本人以利雅哈巴，","notes":[]},{"n":34,"t":"基孫人哈深的眾子，哈拉人沙基的兒子約拿單，","notes":[]},{"n":35,"t":"哈拉人沙甲的兒子亞希暗，吾珥的兒子以利法勒，","notes":[]},{"n":36,"t":"米基拉人希弗，比倫人亞希雅，","notes":[]},{"n":37,"t":"迦密人希斯羅，伊斯拜的兒子拿萊，","notes":[]},{"n":38,"t":"拿單的兄弟約珥，哈基利的兒子彌伯哈，","notes":[]},{"n":39,"t":"亞捫人洗勒，比錄人拿哈萊（拿哈萊是給洗魯雅的兒子約押拿兵器的），","notes":[]},{"n":40,"t":"以帖人以拉，以帖人迦立，","notes":[]},{"n":41,"t":"赫人烏利亞，亞萊的兒子撒拔，","notes":[]},{"n":42,"t":"呂便人示撒的兒子亞第拿（他是呂便支派中的一個族長，率領三十人），","notes":[]},{"n":43,"t":"瑪迦的兒子哈難，彌特尼人約沙法，","notes":[]},{"n":44,"t":"亞施他拉人烏西亞，亞羅珥人何坦的兒子沙瑪、耶利，","notes":[]},{"n":45,"t":"提洗人申利的兒子耶疊和他的兄弟約哈，","notes":[]},{"n":46,"t":"瑪哈未人以利業，伊利拿安的兒子耶利拜、約沙未雅，摩押人伊特瑪、","notes":[]},{"n":47,"t":"以利業、俄備得，並米瑣八人雅西業。","notes":[]}]},"12":{"heading":"早期跟隨大衛的便雅憫人","verses":[{"n":1,"t":"大衛因怕基士的兒子掃羅，躲在洗革拉的時候，有勇士到他那裏幫助他打仗。","notes":[]},{"n":2,"t":"他們善於拉弓，能用左右兩手甩石射箭，都是便雅憫人掃羅的族弟兄。","notes":[]},{"n":3,"t":"為首的是亞希以謝，其次是約阿施，都是基比亞人示瑪的兒子。還有亞斯瑪威的兒子耶薛和毗力，又有比拉迦，並亞拿突人耶戶，","notes":[]},{"n":4,"t":"基遍人以實買雅（他在三十人中是勇士，管理他們），且有耶利米、雅哈悉、約哈難，和基得拉人約撒拔、","notes":[]},{"n":5,"t":"伊利烏賽、耶利摩、比亞利雅、示瑪利雅，哈律弗人示法提雅，","notes":[]},{"n":6,"t":"可拉人以利加拿、耶西亞、亞薩列、約以謝、雅朔班，","notes":[]},{"n":7,"t":"基多人耶羅罕的兒子猶拉和西巴第雅。","notes":[]},{"n":8,"t":"迦得支派中有人到曠野的山寨投奔大衛，都是大能的勇士，能拿盾牌和槍的戰士。他們的面貌好像獅子，快跑如同山上的鹿。","notes":[],"heads":["跟隨大衛的迦得人"]},{"n":9,"t":"第一以薛，第二俄巴底雅，第三以利押，","notes":[]},{"n":10,"t":"第四彌施瑪拿，第五耶利米，","notes":[]},{"n":11,"t":"第六亞太，第七以利業，","notes":[]},{"n":12,"t":"第八約哈難，第九以利薩巴，","notes":[]},{"n":13,"t":"第十耶利米，第十一末巴奈。","notes":[]},{"n":14,"t":"這都是迦得人中的軍長，至小的能抵一百人，至大的能抵一千人。","notes":[]},{"n":15,"t":"正月，約旦河水漲過兩岸的時候，他們過河，使一切住平原的人東奔西逃。","notes":[]},{"n":16,"t":"又有便雅憫和猶大人到山寨大衛那裏。","notes":[],"heads":["跟隨大衛的便雅憫人和猶大人"]},{"n":17,"t":"大衛出去迎接他們，對他們說：「你們若是和和平平地來幫助我，我心就與你們相契；你們若是將我這無罪的人賣在敵人手裏，願我們列祖的神察看責罰。」","notes":[]},{"n":18,"t":"那時神的靈感動那三十個勇士的首領亞瑪撒，他就說：大衛啊，我們是歸於你的！耶西的兒子啊，我們是幫助你的！願你平平安安，願幫助你的也都平安！因為你的神幫助你。大衛就收留他們，立他們作軍長。","notes":[]},{"n":19,"t":"大衛從前與非利士人同去，要與掃羅爭戰，有些瑪拿西人來投奔大衛，他們卻沒有幫助非利士人；因為非利士人的首領商議，打發他們回去，說：「恐怕大衛拿我們的首級，歸降他的主人掃羅。」","notes":[],"heads":["跟隨大衛的瑪拿西人"]},{"n":20,"t":"大衛往洗革拉去的時候，有瑪拿西人的千夫長押拿、約撒拔、耶疊、米迦勒、約撒拔、以利戶、洗勒太都來投奔他。","notes":[]},{"n":21,"t":"這些人幫助大衛攻擊群賊；他們都是大能的勇士，且作軍長。","notes":[]},{"n":22,"t":"那時天天有人來幫助大衛，以致成了大軍，如神的軍一樣。","notes":[]},{"n":23,"t":"預備打仗的兵來到希伯崙見大衛，要照著耶和華的話將掃羅的國位歸與大衛。他們的數目如下：","notes":[],"heads":["大衛的軍力"]},{"n":24,"t":"猶大支派，拿盾牌和槍預備打仗的有六千八百人。","notes":[]},{"n":25,"t":"西緬支派，能上陣大能的勇士有七千一百人。","notes":[]},{"n":26,"t":"利未支派有四千六百人。","notes":[]},{"n":27,"t":"耶何耶大是亞倫家的首領，跟從他的有三千七百人。","notes":[]},{"n":28,"t":"還有少年大能的勇士撒督，同著他的有族長二十二人。","notes":[]},{"n":29,"t":"便雅憫支派，掃羅的族弟兄也有三千人，他們向來大半歸順掃羅家。","notes":[]},{"n":30,"t":"以法蓮支派大能的勇士，在本族著名的有二萬零八百人。","notes":[]},{"n":31,"t":"瑪拿西半支派，冊上有名的共一萬八千人，都來立大衛作王。","notes":[]},{"n":32,"t":"以薩迦支派，有二百族長都通達時務，知道以色列人所當行的；他們族弟兄都聽從他們的命令。","notes":[]},{"n":33,"t":"西布倫支派，能上陣用各樣兵器打仗、行伍整齊、不生二心的有五萬人。","notes":[]},{"n":34,"t":"拿弗他利支派，有一千軍長；跟從他們、拿盾牌和槍的有三萬七千人。","notes":[]},{"n":35,"t":"但支派，能擺陣的有二萬八千六百人。","notes":[]},{"n":36,"t":"亞設支派，能上陣打仗的有四萬人。","notes":[]},{"n":37,"t":"約旦河東的呂便支派、迦得支派、瑪拿西半支派，拿著各樣兵器打仗的有十二萬人。","notes":[]},{"n":38,"t":"以上都是能守行伍的戰士，他們都誠心來到希伯崙，要立大衛作以色列的王。以色列其餘的人也都一心要立大衛作王。","notes":[]},{"n":39,"t":"他們在那裏三日，與大衛一同吃喝，因為他們的族弟兄給他們預備了。","notes":[]},{"n":40,"t":"靠近他們的人以及以薩迦、西布倫、拿弗他利人將許多麵餅、無花果餅、乾葡萄、酒、油，用驢、駱駝、騾子、牛馱來，又帶了許多的牛和羊來，因為以色列人甚是歡樂。","notes":[]}]},"13":{"heading":"約櫃遷出基列‧耶琳","verses":[{"n":1,"t":"大衛與千夫長、百夫長，就是一切首領商議。","notes":[]},{"n":2,"t":"大衛對以色列全會眾說：「你們若以為美，見這事是出於耶和華－我們的神，我們就差遣人走遍以色列地，見我們未來的弟兄，又見住在有郊野之城的祭司利未人，使他們都到這裏來聚集。","notes":[]},{"n":3,"t":"我們要把神的約櫃運到我們這裏來；因為在掃羅年間，我們沒有在約櫃前求問神。」","notes":[]},{"n":4,"t":"全會眾都說可以如此行；這事在眾民眼中都看為好。","notes":[]},{"n":5,"t":"於是，大衛將以色列人從埃及的西曷河直到哈馬口都招聚了來，要從基列‧耶琳將神的約櫃運來。","notes":[]},{"n":6,"t":"大衛率領以色列眾人上到巴拉，就是屬猶大的基列‧耶琳，要從那裏將約櫃運來。這約櫃就是坐在二基路伯上耶和華神留名的約櫃。","notes":[]},{"n":7,"t":"他們將神的約櫃從亞比拿達的家裏抬出來，放在新車上。烏撒和亞希約趕車。","notes":[]},{"n":8,"t":"大衛和以色列眾人在神前用琴、瑟、鑼、鼓、號作樂，極力跳舞歌唱。","notes":[]},{"n":9,"t":"到了基頓的禾場；因為牛失前蹄，烏撒就伸手扶住約櫃。","notes":["在撒母耳下六章六節是拿艮","或譯：驚跳"]},{"n":10,"t":"耶和華向他發怒，因他伸手扶住約櫃擊殺他，他就死在神面前。","notes":[]},{"n":11,"t":"大衛因耶和華擊殺烏撒，心裏愁煩，就稱那地方為毗列斯‧烏撒，直到今日。","notes":["原文是闖殺"]},{"n":12,"t":"那日，大衛懼怕神，說：「神的約櫃怎可運到我這裏來？」","notes":[]},{"n":13,"t":"於是大衛不將約櫃運進大衛的城，卻運到迦特人俄別‧以東的家中。","notes":[]},{"n":14,"t":"神的約櫃在俄別‧以東家中三個月，耶和華賜福給俄別‧以東的家和他一切所有的。","notes":[]}]},"14":{"heading":"大衛在耶路撒冷的活動","verses":[{"n":1,"t":"泰爾王希蘭將香柏木運到大衛那裏，又差遣使者和石匠、木匠給大衛建造宮殿。","notes":[]},{"n":2,"t":"大衛就知道耶和華堅立他作以色列王，又為自己的民以色列，使他的國興旺。","notes":[]},{"n":3,"t":"大衛在耶路撒冷又立后妃，又生兒女。","notes":[]},{"n":4,"t":"在耶路撒冷所生的眾子是沙母亞、朔罷、拿單、所羅門、","notes":[]},{"n":5,"t":"益轄、以利書亞、以法列、","notes":[]},{"n":6,"t":"挪迦、尼斐、雅非亞、","notes":[]},{"n":7,"t":"以利沙瑪、比利雅大、以利法列。","notes":[]},{"n":8,"t":"非利士人聽見大衛受膏作以色列眾人的王，非利士眾人就上來尋索大衛。大衛聽見，就出去迎敵。","notes":[],"heads":["戰勝非利士人"]},{"n":9,"t":"非利士人來了，布散在利乏音谷。","notes":[]},{"n":10,"t":"大衛求問神，說：「我可以上去攻打非利士人嗎？你將他們交在我手裏嗎？」耶和華說：「你可以上去，我必將他們交在你手裏。」","notes":[]},{"n":11,"t":"非利士人來到巴力‧毗拉心，大衛在那裏殺敗他們。大衛說：「神藉我的手沖破敵人，如同水沖去一般」；因此稱那地方為巴力‧毗拉心。","notes":[]},{"n":12,"t":"非利士人將神像撇在那裏，大衛吩咐人用火焚燒了。","notes":[]},{"n":13,"t":"非利士人又布散在利乏音谷。","notes":[]},{"n":14,"t":"大衛又求問神。神說：「不要一直地上去，要轉到他們後頭，從桑林對面攻打他們。","notes":[]},{"n":15,"t":"你聽見桑樹梢上有腳步的聲音，就要出戰，因為神已經在你前頭去攻打非利士人的軍隊。」","notes":[]},{"n":16,"t":"大衛就遵著神所吩咐的，攻打非利士人的軍隊，從基遍直到基色。","notes":[]},{"n":17,"t":"於是大衛的名傳揚到列國，耶和華使列國都懼怕他。","notes":[]}]},"15":{"heading":"準備搬運約櫃","verses":[{"n":1,"t":"大衛在大衛城為自己建造宮殿，又為神的約櫃預備地方，支搭帳幕。","notes":[]},{"n":2,"t":"那時大衛說：「除了利未人之外，無人可抬神的約櫃；因為耶和華揀選他們抬神的約櫃，且永遠事奉他。」","notes":[]},{"n":3,"t":"大衛招聚以色列眾人到耶路撒冷，要將耶和華的約櫃抬到他所預備的地方。","notes":[]},{"n":4,"t":"大衛又聚集亞倫的子孫和利未人。","notes":[]},{"n":5,"t":"哥轄子孫中有族長烏列和他的弟兄一百二十人。","notes":[]},{"n":6,"t":"米拉利子孫中有族長亞帥雅和他的弟兄二百二十人。","notes":[]},{"n":7,"t":"革順子孫中有族長約珥和他的弟兄一百三十人。","notes":[]},{"n":8,"t":"以利撒反子孫中有族長示瑪雅和他的弟兄二百人。","notes":[]},{"n":9,"t":"希伯崙子孫中有族長以列和他的弟兄八十人。","notes":[]},{"n":10,"t":"烏薛子孫中有族長亞米拿達和他的弟兄一百一十二人。","notes":[]},{"n":11,"t":"大衛將祭司撒督和亞比亞他，並利未人烏列、亞帥雅、約珥、示瑪雅、以列、亞米拿達召來，","notes":[]},{"n":12,"t":"對他們說：「你們是利未人的族長，你們和你們的弟兄應當自潔，好將耶和華－以色列神的約櫃抬到我所預備的地方。","notes":[]},{"n":13,"t":"因你們先前沒有抬這約櫃，按定例求問耶和華－我們的神，所以他刑罰我們。」","notes":["原文是闖殺"]},{"n":14,"t":"於是祭司利未人自潔，好將耶和華－以色列神的約櫃抬上來。","notes":[]},{"n":15,"t":"利未子孫就用槓，肩抬神的約櫃，是照耶和華藉摩西所吩咐的。","notes":[]},{"n":16,"t":"大衛吩咐利未人的族長，派他們歌唱的弟兄用琴瑟和鈸作樂，歡歡喜喜地大聲歌頌。","notes":[]},{"n":17,"t":"於是利未人派約珥的兒子希幔和他弟兄中比利家的兒子亞薩，並他們族弟兄米拉利子孫裏古沙雅的兒子以探。","notes":[]},{"n":18,"t":"其次還有他們的弟兄撒迦利雅、便雅薛、示米拉末、耶歇、烏尼、以利押、比拿雅、瑪西雅、瑪他提雅、以利斐利戶、彌克尼雅，並守門的俄別‧以東和耶利。","notes":[]},{"n":19,"t":"這樣，派歌唱的希幔、亞薩、以探敲銅鈸，大發響聲；","notes":[]},{"n":20,"t":"派撒迦利雅、雅薛、示米拉末、耶歇、烏尼、以利押、瑪西雅、比拿雅鼓瑟，調用女音；","notes":[]},{"n":21,"t":"又派瑪他提雅、以利斐利戶、彌克尼雅、俄別‧以東、耶利、亞撒西雅領首彈琴，調用第八。","notes":[]},{"n":22,"t":"利未人的族長基拿尼雅是歌唱人的首領，又教訓人歌唱，因為他精通此事。","notes":[]},{"n":23,"t":"比利家、以利加拿是約櫃前守門的。","notes":[]},{"n":24,"t":"祭司示巴尼、約沙法、拿坦業、亞瑪賽、撒迦利雅、比拿亞、以利以謝在神的約櫃前吹號。俄別‧以東和耶希亞也是約櫃前守門的。","notes":[]},{"n":25,"t":"於是，大衛和以色列的長老，並千夫長都去從俄別‧以東的家歡歡喜喜地將耶和華的約櫃抬上來。","notes":[],"heads":["約櫃遷入耶路撒冷"]},{"n":26,"t":"神賜恩與抬耶和華約櫃的利未人，他們就獻上七隻公牛，七隻公羊。","notes":[]},{"n":27,"t":"大衛和抬約櫃的利未人，並歌唱人的首領基拿尼雅，以及歌唱的人，都穿著細麻布的外袍；大衛另外穿著細麻布的以弗得。","notes":[]},{"n":28,"t":"這樣，以色列眾人歡呼吹角、吹號、敲鈸、鼓瑟、彈琴，大發響聲，將耶和華的約櫃抬上來。","notes":[]},{"n":29,"t":"耶和華的約櫃進了大衛城的時候，掃羅的女兒米甲從窗戶裏觀看，見大衛王踴躍跳舞，心裏就輕視他。","notes":[]}]},"16":{"heading":"頌讚之歌","verses":[{"n":1,"t":"眾人將神的約櫃請進去，安放在大衛所搭的帳幕裏，就在神面前獻燔祭和平安祭。","notes":[]},{"n":2,"t":"大衛獻完了燔祭和平安祭，就奉耶和華的名給民祝福，","notes":[]},{"n":3,"t":"並且分給以色列人，無論男女，每人一個餅，一塊肉，一個葡萄餅。","notes":[]},{"n":4,"t":"大衛派幾個利未人在耶和華的約櫃前事奉，頌揚，稱謝，讚美耶和華－以色列的神：","notes":[]},{"n":5,"t":"為首的是亞薩，其次是撒迦利雅、雅薛、示米拉末、耶歇、瑪他提雅、以利押、比拿雅、俄別‧以東、耶利，鼓瑟彈琴；惟有亞薩敲鈸，大發響聲；","notes":[]},{"n":6,"t":"祭司比拿雅和雅哈悉常在神的約櫃前吹號。","notes":[]},{"n":7,"t":"那日，大衛初次藉亞薩和他的弟兄以詩歌稱頌耶和華，說：","notes":[]},{"n":8,"t":"你們要稱謝耶和華，求告他的名，在萬民中傳揚他的作為！","notes":[]},{"n":9,"t":"要向他唱詩、歌頌，談論他一切奇妙的作為。","notes":[]},{"n":10,"t":"要以他的聖名誇耀；尋求耶和華的人，心中應當歡喜。","notes":[]},{"n":11,"t":"要尋求耶和華與他的能力，時常尋求他的面。","notes":[]},{"n":12,"t":"他僕人以色列的後裔，他所揀選雅各的子孫哪，你們要記念他奇妙的作為和他的奇事，並他口中的判語。","notes":[],"end":13},{"n":14,"t":"他是耶和華－我們的神，全地都有他的判斷。","notes":[]},{"n":15,"t":"你們要記念他的約，直到永遠；他所吩咐的話，直到千代，","notes":[]},{"n":16,"t":"就是與亞伯拉罕所立的約，向以撒所起的誓。","notes":[]},{"n":17,"t":"他又將這約向雅各定為律例，向以色列定為永遠的約，","notes":[]},{"n":18,"t":"說：我必將迦南地賜給你，作你產業的分。","notes":[]},{"n":19,"t":"當時你們人丁有限，數目稀少，並且在那地為寄居的；","notes":[]},{"n":20,"t":"他們從這邦游到那邦，從這國行到那國。","notes":[]},{"n":21,"t":"耶和華不容甚麼人欺負他們，為他們的緣故責備君王，","notes":[]},{"n":22,"t":"說：不可難為我受膏的人，也不可惡待我的先知！","notes":[]},{"n":23,"t":"全地都要向耶和華歌唱！天天傳揚他的救恩，","notes":[]},{"n":24,"t":"在列邦中述說他的榮耀，在萬民中述說他的奇事。","notes":[]},{"n":25,"t":"因耶和華為大，當受極大的讚美；他在萬神之上，當受敬畏。","notes":[]},{"n":26,"t":"外邦的神都屬虛無，惟獨耶和華創造諸天。","notes":[]},{"n":27,"t":"有尊榮和威嚴在他面前，有能力和喜樂在他聖所。","notes":[]},{"n":28,"t":"民中的萬族啊，你們要將榮耀能力歸給耶和華，都歸給耶和華！","notes":[]},{"n":29,"t":"要將耶和華的名所當得的榮耀歸給他，拿供物來奉到他面前；當以聖潔的妝飾敬拜耶和華。","notes":["的：或譯為"]},{"n":30,"t":"全地要在他面前顫抖，世界也堅定不得動搖。","notes":[]},{"n":31,"t":"願天歡喜，願地快樂；願人在列邦中說：耶和華作王了！","notes":[]},{"n":32,"t":"願海和其中所充滿的澎湃；願田和其中所有的都歡樂。","notes":[]},{"n":33,"t":"那時，林中的樹木都要在耶和華面前歡呼，因為他來要審判全地。","notes":[]},{"n":34,"t":"應當稱謝耶和華；因他本為善，他的慈愛永遠長存！","notes":[]},{"n":35,"t":"要說：拯救我們的神啊，求你救我們，聚集我們，使我們脫離外邦，我們好稱讚你的聖名，以讚美你為誇勝。","notes":[]},{"n":36,"t":"耶和華－以色列的神，從亙古直到永遠，是應當稱頌的！眾民都說：「阿們！」並且讚美耶和華。","notes":[]},{"n":37,"t":"大衛派亞薩和他的弟兄在約櫃前常常事奉耶和華，一日盡一日的職分；","notes":[],"heads":["在耶路撒冷和基遍的敬拜"]},{"n":38,"t":"又派俄別‧以東和他的弟兄六十八人，與耶杜頓的兒子俄別‧以東，並何薩作守門的；","notes":[]},{"n":39,"t":"且派祭司撒督和他弟兄眾祭司在基遍的邱壇、耶和華的帳幕前燔祭壇上，每日早晚，照著耶和華律法書上所吩咐以色列人的，常給耶和華獻燔祭。","notes":[],"end":40},{"n":41,"t":"與他們一同被派的有希幔、耶杜頓，和其餘被選名字錄在冊上的，稱謝耶和華，因他的慈愛永遠長存。","notes":[]},{"n":42,"t":"希幔、耶杜頓同著他們吹號、敲鈸，大發響聲，並用別的樂器隨著歌頌神。耶杜頓的子孫作守門的。","notes":[]},{"n":43,"t":"於是眾民各歸各家；大衛也回去為家眷祝福。","notes":[]}]},"17":{"heading":"拿單傳給大衛的信息","verses":[{"n":1,"t":"大衛住在自己宮中，對先知拿單說：「看哪，我住在香柏木的宮中，耶和華的約櫃反在幔子裏。」","notes":[]},{"n":2,"t":"拿單對大衛說：「你可以照你的心意而行，因為神與你同在。」","notes":[]},{"n":3,"t":"當夜，神的話臨到拿單，說：","notes":[]},{"n":4,"t":"「你去告訴我僕人大衛，說耶和華如此說：『你不可建造殿宇給我居住。","notes":[]},{"n":5,"t":"自從我領以色列人出埃及，直到今日，我未曾住過殿宇，乃從這會幕到那會幕，從這帳幕到那帳幕。","notes":[]},{"n":6,"t":"凡我同以色列人所走的地方，我何曾向以色列的一個士師，就是我吩咐牧養我民的說：你為何不給我建造香柏木的殿宇呢？』","notes":[]},{"n":7,"t":"現在你要告訴我僕人大衛，說萬軍之耶和華如此說：『我從羊圈中將你召來，叫你不再跟從羊群，立你作我民以色列的君。","notes":[]},{"n":8,"t":"你無論往哪裏去，我常與你同在，剪除你的一切仇敵；我必使你得大名，好像世上大大有名的人一樣。","notes":[]},{"n":9,"t":"我必為我民以色列選定一個地方，栽培他們，使他們住自己的地方，不再遷移；凶惡之子也不像從前擾害他們，","notes":[]},{"n":10,"t":"並不像我命士師治理我民以色列的時候一樣。我必治服你的一切仇敵，並且我－耶和華應許你，必為你建立家室。","notes":[]},{"n":11,"t":"你壽數滿足歸你列祖的時候，我必使你的後裔接續你的位，我也必堅定他的國。","notes":[]},{"n":12,"t":"他必為我建造殿宇；我必堅定他的國位直到永遠。","notes":[]},{"n":13,"t":"我要作他的父，他要作我的子；並不使我的慈愛離開他，像離開在你以前的掃羅一樣。","notes":[]},{"n":14,"t":"我卻要將他永遠堅立在我家裏和我國裏；他的國位也必堅定，直到永遠。』」","notes":[]},{"n":15,"t":"拿單就按這一切話，照這默示告訴大衛。","notes":[]},{"n":16,"t":"於是大衛王進去，坐在耶和華面前，說：「耶和華神啊，我是誰，我的家算甚麼，你竟使我到這地步呢？","notes":[],"heads":["感恩的禱告"]},{"n":17,"t":"神啊，這在你眼中還看為小，又應許你僕人的家至於久遠。耶和華神啊，你看顧我好像看顧高貴的人。","notes":[]},{"n":18,"t":"你加於僕人的尊榮，我還有何言可說呢？因為你知道你的僕人。","notes":[]},{"n":19,"t":"耶和華啊，你行了這大事，並且顯明出來，是因你僕人的緣故，也是照你的心意。","notes":[]},{"n":20,"t":"耶和華啊，照我們耳中聽見，沒有可比你的，除你以外再無神。","notes":[]},{"n":21,"t":"世上有何民能比你的民以色列呢？你神從埃及救贖他們作自己的子民，又在你贖出來的民面前行大而可畏的事，驅逐列邦人，顯出你的大名。","notes":[]},{"n":22,"t":"你使以色列人作你的子民，直到永遠；你－耶和華也作他們的神。","notes":[]},{"n":23,"t":"耶和華啊，你所應許僕人和僕人家的話，求你堅定，直到永遠，照你所說的而行。","notes":[]},{"n":24,"t":"願你的名永遠堅立，被尊為大，說：『萬軍之耶和華是以色列的神，是治理以色列的神。』這樣，你僕人大衛的家必在你面前堅立。","notes":[]},{"n":25,"t":"我的神啊，因你啟示僕人說，我必為你建立家室，所以僕人大膽在你面前祈禱。","notes":[]},{"n":26,"t":"耶和華啊，惟有你是神，你也應許將這福氣賜給僕人。","notes":[]},{"n":27,"t":"現在你喜悅賜福與僕人的家，可以永存在你面前。耶和華啊，你已經賜福，還要賜福到永遠。」","notes":[]}]},"18":{"heading":"在軍事上的勝利","verses":[{"n":1,"t":"此後，大衛攻打非利士人，把他們治服，從他們手下奪取了迦特和屬迦特的村莊；","notes":[]},{"n":2,"t":"又攻打摩押，摩押人就歸服大衛，給他進貢。","notes":[]},{"n":3,"t":"瑣巴王哈大利謝往幼發拉底河去，要堅定自己的國權，大衛就攻打他，直到哈馬，","notes":["在撒母耳下八章三節是哈大底謝"]},{"n":4,"t":"奪了他的戰車一千，馬兵七千，步兵二萬，將拉戰車的馬砍斷蹄筋，但留下一百輛車的馬。","notes":[]},{"n":5,"t":"大馬士革的亞蘭人來幫助瑣巴王哈大利謝，大衛就殺了亞蘭人二萬二千。","notes":[]},{"n":6,"t":"於是大衛在大馬士革的亞蘭地設立防營，亞蘭人就歸服他，給他進貢。大衛無論往哪裏去，耶和華都使他得勝。","notes":[]},{"n":7,"t":"他奪了哈大利謝臣僕所拿的金盾牌帶到耶路撒冷。","notes":[]},{"n":8,"t":"大衛又從屬哈大利謝的提巴和均二城中奪取了許多的銅。後來所羅門用此製造銅海、銅柱，和一切的銅器。","notes":["或譯：比他"]},{"n":9,"t":"哈馬王陀烏聽見大衛殺敗瑣巴王哈大利謝的全軍，","notes":[]},{"n":10,"t":"就打發他兒子哈多蘭去見大衛王，問他的安，為他祝福，因為他殺敗了哈大利謝（原來陀烏與哈大利謝常常爭戰）。哈多蘭帶了金銀銅的各樣器皿來。","notes":[]},{"n":11,"t":"大衛王將這些器皿，並從各國奪來的金銀，就是從以東、摩押、亞捫、非利士、亞瑪力人所奪來的，都分別為聖獻給耶和華。","notes":[]},{"n":12,"t":"洗魯雅的兒子亞比篩在鹽谷擊殺了以東一萬八千人。","notes":[]},{"n":13,"t":"大衛在以東地設立防營，以東人就都歸服他。大衛無論往哪裏去，耶和華都使他得勝。","notes":[]},{"n":14,"t":"大衛作以色列眾人的王，又向眾民秉公行義。","notes":[]},{"n":15,"t":"洗魯雅的兒子約押作元帥；亞希律的兒子約沙法作史官；","notes":[]},{"n":16,"t":"亞希突的兒子撒督和亞比亞他的兒子亞希米勒作祭司長；沙威沙作書記；","notes":[]},{"n":17,"t":"耶何耶大的兒子比拿雅統轄基利提人和比利提人。大衛的眾子都在王的左右作領袖。","notes":[]}]},"19":{"heading":"大衛擊敗亞捫人和亞蘭人","verses":[{"n":1,"t":"此後，亞捫人的王拿轄死了，他兒子接續他作王。","notes":[]},{"n":2,"t":"大衛說：「我要照哈嫩的父親拿轄厚待我的恩典厚待哈嫩。」於是大衛差遣使者為他喪父安慰他。大衛的臣僕到了亞捫人的境內見哈嫩，要安慰他，","notes":[]},{"n":3,"t":"但亞捫人的首領對哈嫩說：「大衛差人來安慰你，你想他是尊敬你父親嗎？他的臣僕來見你不是為詳察窺探、傾覆這地嗎？」","notes":[]},{"n":4,"t":"哈嫩便將大衛臣僕的鬍鬚剃去一半，又割斷他們下半截的衣服，使他們露出下體，打發他們回去。","notes":[]},{"n":5,"t":"有人將臣僕所遇的事告訴大衛，他就差人去迎接他們，因為他們甚覺羞恥；告訴他們說：「可以住在耶利哥，等到鬍鬚長起再回來。」","notes":[]},{"n":6,"t":"亞捫人知道大衛憎惡他們，哈嫩和亞捫人就打發人拿一千他連得銀子，從美索不達米亞、亞蘭、瑪迦、瑣巴雇戰車和馬兵，","notes":[]},{"n":7,"t":"於是雇了三萬二千輛戰車和瑪迦王並他的軍兵；他們來安營在米底巴前。亞捫人也從他們的城裏出來，聚集交戰。","notes":[]},{"n":8,"t":"大衛聽見了，就差派約押統帶勇猛的全軍出去。","notes":[]},{"n":9,"t":"亞捫人出來在城門前擺陣，所來的諸王另在郊野擺陣。","notes":[]},{"n":10,"t":"約押看見敵人在他前後擺陣，就從以色列軍中挑選精兵，使他們對著亞蘭人擺陣；","notes":[]},{"n":11,"t":"其餘的兵交與他兄弟亞比篩，對著亞捫人擺陣。","notes":[]},{"n":12,"t":"約押對亞比篩說：「亞蘭人若強過我，你就來幫助我；亞捫人若強過你，我就去幫助你。","notes":[]},{"n":13,"t":"我們都當剛強，為本國的民和神的城邑作大丈夫，願耶和華憑他的意旨而行。」","notes":[]},{"n":14,"t":"於是約押和跟隨他的人前進攻打亞蘭人；亞蘭人在約押面前逃跑。","notes":[]},{"n":15,"t":"亞捫人見亞蘭人逃跑，他們也在約押的兄弟亞比篩面前逃跑進城。約押就回耶路撒冷去了。","notes":[]},{"n":16,"t":"亞蘭人見自己被以色列人打敗，就打發使者將大河那邊的亞蘭人調來，哈大利謝的將軍朔法率領他們。","notes":[]},{"n":17,"t":"有人告訴大衛，他就聚集以色列眾人過約旦河，來到亞蘭人那裏，迎著他們擺陣。大衛既擺陣攻擊亞蘭人，亞蘭人就與他打仗。","notes":[]},{"n":18,"t":"亞蘭人在以色列人面前逃跑。大衛殺了亞蘭七千輛戰車的人，四萬步兵，又殺了亞蘭的將軍朔法。","notes":[]},{"n":19,"t":"屬哈大利謝的諸王見自己被以色列人打敗，就與大衛和好，歸服他。於是亞蘭人不敢再幫助亞捫人了。","notes":[]}]},"20":{"heading":"大衛攻取拉巴城","verses":[{"n":1,"t":"過了一年，到列王出戰的時候，約押率領軍兵毀壞亞捫人的地，圍攻拉巴；大衛仍住在耶路撒冷。約押攻打拉巴，將城傾覆。","notes":[]},{"n":2,"t":"大衛奪了亞捫人之王所戴的金冠冕，其上的金子重一他連得，又嵌著寶石；人將這冠冕戴在大衛頭上。大衛從城裏奪了許多財物，","notes":["王：或譯瑪勒堪。瑪勒堪即米勒公，是亞捫族之神名"]},{"n":3,"t":"將城裏的人拉出來，放在鋸下，或鐵耙下，或鐵斧下，大衛待亞捫各城的居民都是如此。其後大衛和眾軍都回耶路撒冷去了。","notes":["或譯：強他們用鋸，或用打糧食的鐵器，或用鐵斧做工"]},{"n":4,"t":"後來，以色列人在基色與非利士人打仗。戶沙人西比該殺了偉人的一個兒子細派，非利士人就被制伏了。","notes":[],"heads":["與非利士巨人爭戰"]},{"n":5,"t":"又與非利士人打仗。睚珥的兒子伊勒哈難殺了迦特人歌利亞的兄弟拉哈米；這人的槍桿粗如織布的機軸。","notes":[]},{"n":6,"t":"又在迦特打仗。那裏有一個身量高大的人，手腳都是六指，共有二十四個指頭，他也是偉人的兒子。","notes":[]},{"n":7,"t":"這人向以色列人罵陣，大衛的哥哥示米亞的兒子約拿單就殺了他。","notes":[]},{"n":8,"t":"這三個人是迦特偉人的兒子，都死在大衛和他僕人的手下。","notes":[]}]},"21":{"heading":"大衛數點以色列民","verses":[{"n":1,"t":"撒但起來攻擊以色列人，激動大衛數點他們。","notes":[]},{"n":2,"t":"大衛就吩咐約押和民中的首領說：「你們去數點以色列人，從別是巴直到但，回來告訴我，我好知道他們的數目。」","notes":[]},{"n":3,"t":"約押說：「願耶和華使他的百姓比現在加增百倍。我主我王啊，他們不都是你的僕人嗎？我主為何吩咐行這事，為何使以色列人陷在罪裏呢？」","notes":[]},{"n":4,"t":"但王的命令勝過約押。約押就出去，走遍以色列地，回到耶路撒冷，","notes":[]},{"n":5,"t":"將百姓的總數奏告大衛：以色列人拿刀的有一百一十萬；猶大人拿刀的有四十七萬。","notes":[]},{"n":6,"t":"惟有利未人和便雅憫人沒有數在其中，因為約押厭惡王的這命令。","notes":[]},{"n":7,"t":"神不喜悅這數點百姓的事，便降災給以色列人。","notes":[]},{"n":8,"t":"大衛禱告神說：「我行這事大有罪了！現在求你除掉僕人的罪孽，因我所行的甚是愚昧。」","notes":[]},{"n":9,"t":"耶和華吩咐大衛的先見迦得說：","notes":[]},{"n":10,"t":"「你去告訴大衛說，耶和華如此說：我有三樣災，隨你選擇一樣，我好降與你。」","notes":[]},{"n":11,"t":"於是，迦得來見大衛，對他說：「耶和華如此說：『你可以隨意選擇：","notes":[]},{"n":12,"t":"或三年的饑荒；或敗在你敵人面前，被敵人的刀追殺三個月；或在你國中有耶和華的刀，就是三日的瘟疫，耶和華的使者在以色列的四境施行毀滅。』現在你要想一想，我好回覆那差我來的。」","notes":[]},{"n":13,"t":"大衛對迦得說：「我甚為難。我願落在耶和華的手裏，因為他有豐盛的憐憫；我不願落在人的手裏。」","notes":[]},{"n":14,"t":"於是，耶和華降瘟疫與以色列人，以色列人就死了七萬。","notes":[]},{"n":15,"t":"神差遣使者去滅耶路撒冷，剛要滅的時候，耶和華看見後悔，就不降這災了，吩咐滅城的天使說：「夠了，住手吧！」那時，耶和華的使者站在耶布斯人阿珥楠的禾場那裏。","notes":[]},{"n":16,"t":"大衛舉目，看見耶和華的使者站在天地間，手裏有拔出來的刀，伸在耶路撒冷以上。大衛和長老都身穿麻衣，面伏於地。","notes":[]},{"n":17,"t":"大衛禱告神說：「吩咐數點百姓的不是我嗎？我犯了罪，行了惡，但這群羊做了甚麼呢？願耶和華－我神的手攻擊我和我的父家，不要攻擊你的民，降瘟疫與他們。」","notes":[]},{"n":18,"t":"耶和華的使者吩咐迦得去告訴大衛，叫他上去，在耶布斯人阿珥楠的禾場上為耶和華築一座壇；","notes":[]},{"n":19,"t":"大衛就照著迦得奉耶和華名所說的話上去了。","notes":[]},{"n":20,"t":"那時阿珥楠正打麥子，回頭看見天使，就和他四個兒子都藏起來了。","notes":[]},{"n":21,"t":"大衛到了阿珥楠那裏，阿珥楠看見大衛，就從禾場上出去，臉伏於地，向他下拜。","notes":[]},{"n":22,"t":"大衛對阿珥楠說：「你將這禾場與相連之地賣給我，我必給你足價，我好在其上為耶和華築一座壇，使民間的瘟疫止住。」","notes":[]},{"n":23,"t":"阿珥楠對大衛說：「你可以用這禾場，願我主我王照你所喜悅的去行。我也將牛給你作燔祭，把打糧的器具當柴燒，拿麥子作素祭。這些我都送給你。」","notes":[]},{"n":24,"t":"大衛王對阿珥楠說：「不然！我必要用足價向你買。我不用你的物獻給耶和華，也不用白得之物獻為燔祭。」","notes":[]},{"n":25,"t":"於是大衛為那塊地平了六百舍客勒金子給阿珥楠。","notes":[]},{"n":26,"t":"大衛在那裏為耶和華築了一座壇，獻燔祭和平安祭，求告耶和華。耶和華就應允他，使火從天降在燔祭壇上。","notes":[]},{"n":27,"t":"耶和華吩咐使者，他就收刀入鞘。","notes":[]},{"n":28,"t":"那時，大衛見耶和華在耶布斯人阿珥楠的禾場上應允了他，就在那裏獻祭。","notes":[]},{"n":29,"t":"摩西在曠野所造之耶和華的帳幕和燔祭壇都在基遍的高處；","notes":[]},{"n":30,"t":"只是大衛不敢前去求問神，因為懼怕耶和華使者的刀。","notes":[]}]},"22":{"heading":"籌備建殿","verses":[{"n":1,"t":"大衛說：「這就是耶和華神的殿，為以色列人獻燔祭的壇。」","notes":[]},{"n":2,"t":"大衛吩咐聚集住以色列地的外邦人，從其中派石匠鑿石頭，要建造神的殿。","notes":[]},{"n":3,"t":"大衛預備許多鐵做門上的釘子和鉤子，又預備許多銅，多得無法可稱；","notes":[]},{"n":4,"t":"又預備無數的香柏木，因為西頓人和泰爾人給大衛運了許多香柏木來。","notes":[]},{"n":5,"t":"大衛說：「我兒子所羅門還年幼嬌嫩，要為耶和華建造的殿宇必須高大輝煌，使名譽榮耀傳遍萬國；所以我要為殿預備材料。」於是，大衛在未死之先預備的材料甚多。","notes":[]},{"n":6,"t":"大衛召了他兒子所羅門來，囑咐他給耶和華－以色列的神建造殿宇，","notes":[]},{"n":7,"t":"對所羅門說：「我兒啊，我心裏本想為耶和華－我神的名建造殿宇，","notes":[]},{"n":8,"t":"只是耶和華的話臨到我說：『你流了多人的血，打了多次大仗，你不可為我的名建造殿宇，因為你在我眼前使多人的血流在地上。","notes":[]},{"n":9,"t":"你要生一個兒子，他必作太平的人；我必使他安靜，不被四圍的仇敵擾亂。他的名要叫所羅門。他在位的日子，我必使以色列人平安康泰。","notes":["就是太平的意思"]},{"n":10,"t":"他必為我的名建造殿宇。他要作我的子；我要作他的父。他作以色列王；我必堅定他的國位，直到永遠。』","notes":[]},{"n":11,"t":"我兒啊，現今願耶和華與你同在，使你亨通，照他指著你說的話，建造耶和華－你神的殿。","notes":[]},{"n":12,"t":"但願耶和華賜你聰明智慧，好治理以色列國，遵行耶和華－你神的律法。","notes":[]},{"n":13,"t":"你若謹守遵行耶和華藉摩西吩咐以色列的律例典章，就得亨通。你當剛強壯膽，不要懼怕，也不要驚惶。","notes":[]},{"n":14,"t":"我在困難之中為耶和華的殿預備了金子十萬他連得，銀子一百萬他連得，銅和鐵多得無法可稱；我也預備了木頭、石頭，你還可以增添。","notes":[]},{"n":15,"t":"你有許多匠人，就是石匠、木匠，和一切能做各樣工的巧匠，","notes":[]},{"n":16,"t":"並有無數的金銀銅鐵。你當起來辦事，願耶和華與你同在。」","notes":[]},{"n":17,"t":"大衛又吩咐以色列的眾首領幫助他兒子所羅門，說：","notes":[]},{"n":18,"t":"「耶和華－你們的神不是與你們同在嗎？不是叫你們四圍都平安嗎？因他已將這地的居民交在我手中，這地就在耶和華與他百姓面前制伏了。","notes":[]},{"n":19,"t":"現在你們應當立定心意，尋求耶和華－你們的神；也當起來建造耶和華神的聖所，好將耶和華的約櫃和供奉神的聖器皿都搬進為耶和華名建造的殿裏。」","notes":[]}]},"23":{"heading":"利未人的職務","verses":[{"n":1,"t":"大衛年紀老邁，日子滿足，就立他兒子所羅門作以色列的王。","notes":[]},{"n":2,"t":"大衛招聚以色列的眾首領和祭司利未人。","notes":[]},{"n":3,"t":"利未人從三十歲以外的都被數點，他們男丁的數目共有三萬八千；","notes":[]},{"n":4,"t":"其中有二萬四千人管理耶和華殿的事，有六千人作官長和士師，","notes":[]},{"n":5,"t":"有四千人作守門的，又有四千人用大衛所做的樂器頌讚耶和華。","notes":[]},{"n":6,"t":"大衛將利未人革順、哥轄、米拉利的子孫分了班次。","notes":[]},{"n":7,"t":"革順的子孫有拉但和示每。","notes":[]},{"n":8,"t":"拉但的長子是耶歇，還有細坦和約珥，共三人。","notes":[]},{"n":9,"t":"示每的兒子是示羅密、哈薛、哈蘭三人。這是拉但族的族長。","notes":[]},{"n":10,"t":"示每的兒子是雅哈、細拿、耶烏施、比利亞共四人。","notes":[]},{"n":11,"t":"雅哈是長子，細撒是次子。但耶烏施和比利亞的子孫不多，所以算為一族。","notes":[]},{"n":12,"t":"哥轄的兒子是暗蘭、以斯哈、希伯倫、烏薛共四人。","notes":[]},{"n":13,"t":"暗蘭的兒子是亞倫、摩西。亞倫和他的子孫分出來，好分別至聖的物，在耶和華面前燒香、事奉他，奉他的名祝福，直到永遠。","notes":[]},{"n":14,"t":"至於神人摩西，他的子孫名字記在利未支派的冊上。","notes":[]},{"n":15,"t":"摩西的兒子是革舜和以利以謝。","notes":[]},{"n":16,"t":"革舜的長子是細布業；","notes":[]},{"n":17,"t":"以利以謝的兒子是利哈比雅。以利以謝沒有別的兒子，但利哈比雅的子孫甚多。","notes":[]},{"n":18,"t":"以斯哈的長子是示羅密。","notes":[]},{"n":19,"t":"希伯倫的長子是耶利雅，次子是亞瑪利亞，三子是雅哈悉，四子是耶加面。","notes":[]},{"n":20,"t":"烏薛的長子是米迦，次子是耶西雅。","notes":[]},{"n":21,"t":"米拉利的兒子是抹利、母示。抹利的兒子是以利亞撒、基士。","notes":[]},{"n":22,"t":"以利亞撒死了，沒有兒子，只有女兒，他們本族基士的兒子娶了她們為妻。","notes":[]},{"n":23,"t":"母示的兒子是末力、以得、耶利摩共三人。","notes":[]},{"n":24,"t":"以上利未子孫作族長的，照著男丁的數目，從二十歲以外，都辦耶和華殿的事務。","notes":[]},{"n":25,"t":"大衛說：「耶和華－以色列的神已經使他的百姓平安，他永遠住在耶路撒冷。","notes":[]},{"n":26,"t":"利未人不必再抬帳幕和其中所用的一切器皿了。」","notes":[]},{"n":27,"t":"照著大衛臨終所吩咐的，利未人從二十歲以外的都被數點。","notes":[]},{"n":28,"t":"他們的職任是服事亞倫的子孫，在耶和華的殿和院子，並屋中辦事，潔淨一切聖物，就是辦神殿的事務，","notes":[]},{"n":29,"t":"並管理陳設餅，素祭的細麵，或無酵薄餅，或用盤烤，或用油調和的物，又管理各樣的升斗尺度；","notes":[]},{"n":30,"t":"每日早晚，站立稱謝讚美耶和華，","notes":[]},{"n":31,"t":"又在安息日、月朔，並節期，按數照例，將燔祭常常獻給耶和華；","notes":[]},{"n":32,"t":"又看守會幕和聖所，並守耶和華吩咐他們弟兄亞倫子孫的，辦耶和華殿的事。","notes":[]}]},"24":{"heading":"祭司的職務","verses":[{"n":1,"t":"亞倫子孫的班次記在下面：亞倫的兒子是拿答、亞比戶、以利亞撒、以他瑪。","notes":[]},{"n":2,"t":"拿答、亞比戶死在他們父親之先，沒有留下兒子；故此，以利亞撒、以他瑪供祭司的職分。","notes":[]},{"n":3,"t":"以利亞撒的子孫撒督和以他瑪的子孫亞希米勒，同著大衛將他們的族弟兄分成班次。","notes":[]},{"n":4,"t":"以利亞撒子孫中為首的比以他瑪子孫中為首的更多，分班如下：以利亞撒的子孫中有十六個族長，以他瑪的子孫中有八個族長；","notes":[]},{"n":5,"t":"都掣籤分立，彼此一樣。在聖所和神面前作首領的有以利亞撒的子孫，也有以他瑪的子孫。","notes":[]},{"n":6,"t":"作書記的利未人拿坦業的兒子示瑪雅在王和首領，與祭司撒督、亞比亞他的兒子亞希米勒，並祭司利未人的族長面前記錄他們的名字。在以利亞撒的子孫中取一族，在以他瑪的子孫中取一族。","notes":[]},{"n":7,"t":"掣籤的時候，第一掣出來的是耶何雅立，第二是耶大雅，","notes":[]},{"n":8,"t":"第三是哈琳，第四是梭琳，","notes":[]},{"n":9,"t":"第五是瑪基雅，第六是米雅民，","notes":[]},{"n":10,"t":"第七是哈歌斯，第八是亞比雅，","notes":[]},{"n":11,"t":"第九是耶書亞，第十是示迦尼，","notes":[]},{"n":12,"t":"第十一是以利亞實，第十二是雅金，","notes":[]},{"n":13,"t":"第十三是胡巴，第十四是耶是比押，","notes":[]},{"n":14,"t":"第十五是璧迦，第十六是音麥，","notes":[]},{"n":15,"t":"第十七是希悉，第十八是哈闢悉，","notes":[]},{"n":16,"t":"第十九是毗他希雅，第二十是以西結，","notes":[]},{"n":17,"t":"第二十一是雅斤，第二十二是迦末，","notes":[]},{"n":18,"t":"第二十三是第來雅，第二十四是瑪西亞。","notes":[]},{"n":19,"t":"這就是他們的班次，要照耶和華－以色列的神藉他們祖宗亞倫所吩咐的條例進入耶和華的殿辦理事務。","notes":[]},{"n":20,"t":"利未其餘的子孫如下：暗蘭的子孫裏有書巴業；書巴業的子孫裏有耶希底亞。","notes":[],"heads":["利未人名單"]},{"n":21,"t":"利哈比雅的子孫裏有長子伊示雅。","notes":[]},{"n":22,"t":"以斯哈的子孫裏有示羅摩；示羅摩的子孫裏有雅哈。","notes":[]},{"n":23,"t":"希伯倫的子孫裏有長子耶利雅，次子亞瑪利亞，三子雅哈悉，四子耶加面。","notes":[]},{"n":24,"t":"烏薛的子孫裏有米迦；米迦的子孫裏有沙密。","notes":[]},{"n":25,"t":"米迦的兄弟是伊示雅；伊示雅的子孫裏有撒迦利雅。","notes":[]},{"n":26,"t":"米拉利的兒子是抹利、母示、雅西雅；雅西雅的兒子有比挪；","notes":[]},{"n":27,"t":"米拉利的子孫裏有雅西雅的兒子比挪、朔含、撒刻、伊比利。","notes":[]},{"n":28,"t":"抹利的兒子是以利亞撒；以利亞撒沒有兒子。","notes":[]},{"n":29,"t":"基士的子孫裏有耶拉篾。","notes":[]},{"n":30,"t":"母示的兒子是末力、以得、耶利摩。按著宗族這都是利未的子孫。","notes":[]},{"n":31,"t":"他們在大衛王和撒督，並亞希米勒與祭司利未人的族長面前掣籤，正如他們弟兄亞倫的子孫一般。各族的長者與兄弟沒有分別。","notes":[]}]},"25":{"heading":"聖殿中的聖樂人員","verses":[{"n":1,"t":"大衛和眾首領分派亞薩、希幔，並耶杜頓的子孫彈琴、鼓瑟、敲鈸、唱歌。他們供職的人數記在下面：","notes":["原文是說預言；本章同"]},{"n":2,"t":"亞薩的兒子撒刻、約瑟、尼探雅、亞薩利拉都歸亞薩指教，遵王的旨意唱歌。","notes":[]},{"n":3,"t":"耶杜頓的兒子基大利、西利、耶篩亞、哈沙比雅、瑪他提雅、示每共六人，都歸他們父親耶杜頓指教，彈琴，唱歌，稱謝，頌讚耶和華。","notes":[]},{"n":4,"t":"希幔的兒子布基雅、瑪探雅、烏薛、細布業、耶利摩、哈拿尼雅、哈拿尼、以利亞他、基大利提、羅幔提‧以謝、約施比加沙、瑪羅提、何提、瑪哈秀；","notes":[]},{"n":5,"t":"這都是希幔的兒子，吹角頌讚。希幔奉神之命作王的先見。神賜給希幔十四個兒子，三個女兒，","notes":[]},{"n":6,"t":"都歸他們父親指教，在耶和華的殿唱歌、敲鈸、彈琴、鼓瑟，辦神殿的事務。亞薩、耶杜頓、希幔都是王所命定的。","notes":[]},{"n":7,"t":"他們和他們的弟兄學習頌讚耶和華；善於歌唱的共有二百八十八人。","notes":[]},{"n":8,"t":"這些人無論大小，為師的、為徒的，都一同掣籤分了班次。","notes":[]},{"n":9,"t":"掣籤的時候，第一掣出來的是亞薩的兒子約瑟。第二是基大利；他和他弟兄並兒子共十二人。","notes":[]},{"n":10,"t":"第三是撒刻；他和他兒子並弟兄共十二人。","notes":[]},{"n":11,"t":"第四是伊洗利；他和他兒子並弟兄共十二人。","notes":[]},{"n":12,"t":"第五是尼探雅；他和他兒子並弟兄共十二人。","notes":[]},{"n":13,"t":"第六是布基雅；他和他兒子並弟兄共十二人。","notes":[]},{"n":14,"t":"第七是耶薩利拉；他和他兒子並弟兄共十二人。","notes":[]},{"n":15,"t":"第八是耶篩亞；他和他兒子並弟兄共十二人。","notes":[]},{"n":16,"t":"第九是瑪探雅；他和他兒子並弟兄共十二人。","notes":[]},{"n":17,"t":"第十是示每；他和他兒子並弟兄共十二人。","notes":[]},{"n":18,"t":"第十一是亞薩烈；他和他兒子並弟兄共十二人。","notes":[]},{"n":19,"t":"第十二是哈沙比雅；他和他兒子並弟兄共十二人。","notes":[]},{"n":20,"t":"第十三是書巴業；他和他兒子並弟兄共十二人。","notes":[]},{"n":21,"t":"第十四是瑪他提雅；他和他兒子並弟兄共十二人。","notes":[]},{"n":22,"t":"第十五是耶利摩；他和他兒子並弟兄共十二人。","notes":[]},{"n":23,"t":"第十六是哈拿尼雅；他和他兒子並弟兄共十二人。","notes":[]},{"n":24,"t":"第十七是約施比加沙；他和他兒子並弟兄共十二人。","notes":[]},{"n":25,"t":"第十八是哈拿尼；他和他兒子並弟兄共十二人。","notes":[]},{"n":26,"t":"第十九是瑪羅提；他和他兒子並弟兄共十二人。","notes":[]},{"n":27,"t":"第二十是以利亞他；他和他兒子並弟兄共十二人。","notes":[]},{"n":28,"t":"第二十一是何提；他和他兒子並弟兄共十二人。","notes":[]},{"n":29,"t":"第二十二是基大利提；他和他兒子並弟兄共十二人。","notes":[]},{"n":30,"t":"第二十三是瑪哈秀；他和他兒子並弟兄共十二人。","notes":[]},{"n":31,"t":"第二十四是羅幔提‧以謝；他和他兒子並弟兄共十二人。","notes":[]}]},"26":{"heading":"聖殿的衛隊","verses":[{"n":1,"t":"守門的班次記在下面：可拉族亞薩的子孫中，有可利的兒子米施利米雅。","notes":[]},{"n":2,"t":"米施利米雅的長子是撒迦利亞，次子是耶疊，三子是西巴第雅，四子是耶提聶，","notes":[]},{"n":3,"t":"五子是以攔，六子是約哈難，七子是以利約乃。","notes":[]},{"n":4,"t":"俄別‧以東的長子是示瑪雅，次子是約薩拔，三子是約亞，四子是沙甲，五子是拿坦業，","notes":[]},{"n":5,"t":"六子是亞米利，七子是以薩迦，八子是毗烏利太，因為神賜福與俄別‧以東。","notes":[]},{"n":6,"t":"他的兒子示瑪雅有幾個兒子，都是大能的壯士，掌管父親的家。","notes":[]},{"n":7,"t":"示瑪雅的兒子是俄得尼、利法益、俄備得、以利薩巴。以利薩巴的弟兄是壯士，還有以利戶和西瑪迦。","notes":[]},{"n":8,"t":"這都是俄別‧以東的子孫，他們和他們的兒子並弟兄，都是善於辦事的壯士。俄別‧以東的子孫共六十二人。","notes":[]},{"n":9,"t":"米施利米雅的兒子和弟兄都是壯士，共十八人。","notes":[]},{"n":10,"t":"米拉利子孫何薩有幾個兒子：長子是申利，他原不是長子，是他父親立他作長子。","notes":[]},{"n":11,"t":"次子是希勒家，三子是底巴利雅，四子是撒迦利亞。何薩的兒子並弟兄共十三人。","notes":[]},{"n":12,"t":"這些人都是守門的班長，與他們的弟兄一同在耶和華殿裏按班供職。","notes":[]},{"n":13,"t":"他們無論大小，都按著宗族掣籤分守各門。","notes":[]},{"n":14,"t":"掣籤守東門的是示利米雅；他的兒子撒迦利亞是精明的謀士，掣籤守北門。","notes":[]},{"n":15,"t":"俄別‧以東守南門，他的兒子守庫房。","notes":[]},{"n":16,"t":"書聘與何薩守西門，在靠近沙利基門、通著往上去的街道上，班與班相對。","notes":[]},{"n":17,"t":"每日東門有六個利未人，北門有四個，南門有四個，庫房有兩個，又有兩個輪班替換。","notes":[]},{"n":18,"t":"在西面街道上有四個，在遊廊上有兩個。","notes":[]},{"n":19,"t":"以上是可拉子孫和米拉利子孫守門的班次。","notes":[]},{"n":20,"t":"利未子孫中有亞希雅掌管神殿的府庫和聖物的府庫。","notes":[],"heads":["其他職守"]},{"n":21,"t":"革順族、拉但子孫裏，作族長的是革順族拉但的子孫耶希伊利。","notes":[]},{"n":22,"t":"耶希伊利的兒子西坦和他兄弟約珥掌管耶和華殿裏的府庫。","notes":[]},{"n":23,"t":"暗蘭族、以斯哈族、希伯倫族、烏泄族也有職分。","notes":[]},{"n":24,"t":"摩西的孫子、革舜的兒子細布業掌管府庫。","notes":[]},{"n":25,"t":"還有他的弟兄以利以謝。以利以謝的兒子是利哈比雅；利哈比雅的兒子是耶篩亞；耶篩亞的兒子是約蘭；約蘭的兒子是細基利；細基利的兒子是示羅密。","notes":[]},{"n":26,"t":"這示羅密和他的弟兄掌管府庫的聖物，就是大衛王和眾族長、千夫長、百夫長，並軍長所分別為聖的物。","notes":[]},{"n":27,"t":"他們將爭戰時所奪的財物分別為聖，以備修造耶和華的殿。","notes":[]},{"n":28,"t":"先見撒母耳、基士的兒子掃羅、尼珥的兒子押尼珥、洗魯雅的兒子約押所分別為聖的物都歸示羅密和他的弟兄掌管。","notes":[]},{"n":29,"t":"以斯哈族有基拿尼雅和他眾子作官長和士師，管理以色列的外事。","notes":[],"heads":["其餘利未人的職守"]},{"n":30,"t":"希伯倫族有哈沙比雅和他弟兄一千七百人，都是壯士，在約旦河西、以色列地辦理耶和華與王的事。","notes":[]},{"n":31,"t":"希伯倫族中有耶利雅作族長。大衛作王第四十年，在基列的雅謝，從這族中尋得大能的勇士。","notes":[]},{"n":32,"t":"耶利雅的弟兄有二千七百人，都是壯士，且作族長；大衛王派他們在呂便支派、迦得支派、瑪拿西半支派中辦理神和王的事。","notes":[]}]},"27":{"heading":"軍事長官名單","verses":[{"n":1,"t":"以色列人的族長、千夫長、百夫長，和官長都分定班次，每班是二萬四千人，週年按月輪流，替換出入服事王。","notes":[]},{"n":2,"t":"正月第一班的班長是撒巴第業的兒子雅朔班；他班內有二萬四千人。","notes":[]},{"n":3,"t":"他是法勒斯的子孫，統管正月班的一切軍長。","notes":[]},{"n":4,"t":"二月的班長是亞哈希人朵代，還有副官密基羅；他班內有二萬四千人。","notes":[]},{"n":5,"t":"三月第三班的班長是祭司耶何耶大的兒子比拿雅；他班內有二萬四千人。","notes":["原文是軍長；下同"]},{"n":6,"t":"這比拿雅是那三十人中的勇士，管理那三十人；他班內又有他兒子暗米薩拔。","notes":[]},{"n":7,"t":"四月第四班的班長是約押的兄弟亞撒黑。接續他的是他兒子西巴第雅；他班內有二萬四千人。","notes":[]},{"n":8,"t":"五月第五班的班長是伊斯拉人珊合；他班內有二萬四千人。","notes":[]},{"n":9,"t":"六月第六班的班長是提哥亞人益吉的兒子以拉；他班內有二萬四千人。","notes":[]},{"n":10,"t":"七月第七班的班長是以法蓮族比倫人希利斯；他班內有二萬四千人。","notes":[]},{"n":11,"t":"八月第八班的班長是謝拉族戶沙人西比該；他班內有二萬四千人。","notes":[]},{"n":12,"t":"九月第九班的班長是便雅憫族亞拿突人亞比以謝；他班內有二萬四千人。","notes":[]},{"n":13,"t":"十月第十班的班長是謝拉族尼陀法人瑪哈萊；他班內有二萬四千人。","notes":[]},{"n":14,"t":"十一月第十一班的班長是以法蓮族比拉頓人比拿雅；他班內有二萬四千人。","notes":[]},{"n":15,"t":"十二月第十二班的班長是俄陀聶族尼陀法人黑玳；他班內有二萬四千人。","notes":[]},{"n":16,"t":"管理以色列眾支派的記在下面：管呂便人的是細基利的兒子以利以謝；管西緬人的是瑪迦的兒子示法提雅；","notes":[],"heads":["以色列各支派的行政長官"]},{"n":17,"t":"管利未人的是基母利的兒子哈沙比雅；管亞倫子孫的是撒督；","notes":[]},{"n":18,"t":"管猶大人的是大衛的一個哥哥以利戶；管以薩迦人的是米迦勒的兒子暗利；","notes":[]},{"n":19,"t":"管西布倫人的是俄巴第雅的兒子伊施瑪雅；管拿弗他利人的是亞斯列的兒子耶利摩；","notes":[]},{"n":20,"t":"管以法蓮人的是阿撒細雅的兒子何細亞；管瑪拿西半支派的是毗大雅的兒子約珥；","notes":[]},{"n":21,"t":"管基列地瑪拿西那半支派的是撒迦利亞的兒子易多；管便雅憫人的是押尼珥的兒子雅西業；","notes":[]},{"n":22,"t":"管但人的是耶羅罕的兒子亞薩列。以上是以色列眾支派的首領。","notes":[]},{"n":23,"t":"以色列人二十歲以內的，大衛沒有記其數目；因耶和華曾應許說，必加增以色列人如天上的星那樣多。","notes":[]},{"n":24,"t":"洗魯雅的兒子約押動手數點，當時耶和華的烈怒臨到以色列人；因此，沒有點完，數目也沒有寫在大衛王記上。","notes":[]},{"n":25,"t":"掌管王府庫的是亞疊的兒子押斯馬威。掌管田野城邑村莊保障之倉庫的是烏西雅的兒子約拿單。","notes":[],"heads":["管理王產的官員"]},{"n":26,"t":"掌管耕田種地的是基綠的兒子以斯利。","notes":[]},{"n":27,"t":"掌管葡萄園的是拉瑪人示每。掌管葡萄園酒窖的是實弗米人撒巴底。","notes":[]},{"n":28,"t":"掌管高原橄欖樹和桑樹的是基第利人巴勒‧哈南。掌管油庫的是約阿施。","notes":[]},{"n":29,"t":"掌管沙崙牧放牛群的是沙崙人施提賚。掌管山谷牧養牛群的是亞第賚的兒子沙法。","notes":[]},{"n":30,"t":"掌管駝群的是以實瑪利人阿比勒。掌管驢群的是米崙人耶希底亞。掌管羊群的是夏甲人雅悉。","notes":[]},{"n":31,"t":"這都是給大衛王掌管產業的。","notes":[]},{"n":32,"t":"大衛的叔叔約拿單作謀士；這人有智慧，又作書記。哈摩尼的兒子耶歇作王眾子的師傅。","notes":[],"heads":["大衛的謀士"]},{"n":33,"t":"亞希多弗也作王的謀士。亞基人戶篩作王的陪伴。","notes":[]},{"n":34,"t":"亞希多弗之後，有比拿雅的兒子耶何耶大和亞比亞他接續他作謀士。約押作王的元帥。","notes":[]}]},"28":{"heading":"大衛對建殿的指示","verses":[{"n":1,"t":"大衛招聚以色列各支派的首領和輪班服事王的軍長，與千夫長、百夫長，掌管王和王子產業牲畜的，並太監，以及大能的勇士，都到耶路撒冷來。","notes":[]},{"n":2,"t":"大衛王就站起來，說：「我的弟兄，我的百姓啊，你們當聽我言，我心裏本想建造殿宇，安放耶和華的約櫃，作為我神的腳凳；我已經預備建造的材料。","notes":[]},{"n":3,"t":"只是神對我說：『你不可為我的名建造殿宇；因你是戰士，流了人的血。』","notes":[]},{"n":4,"t":"然而，耶和華－以色列的神在我父的全家揀選我作以色列的王，直到永遠。因他揀選猶大為首領；在猶大支派中揀選我父家，在我父的眾子裏喜悅我，立我作以色列眾人的王。","notes":[]},{"n":5,"t":"耶和華賜我許多兒子，在我兒子中揀選所羅門坐耶和華的國位，治理以色列人。","notes":[]},{"n":6,"t":"耶和華對我說：『你兒子所羅門必建造我的殿和院宇；因為我揀選他作我的子，我也必作他的父。","notes":[]},{"n":7,"t":"他若恆久遵行我的誡命典章如今日一樣，我就必堅定他的國位，直到永遠。』","notes":[]},{"n":8,"t":"現今在耶和華的會中，以色列眾人眼前所說的，我們的神也聽見了。你們應當尋求耶和華－你們神的一切誡命，謹守遵行，如此你們可以承受這美地，遺留給你們的子孫，永遠為業。","notes":[]},{"n":9,"t":"「我兒所羅門哪，你當認識耶和華－你父的神，誠心樂意地事奉他；因為他鑒察眾人的心，知道一切心思意念。你若尋求他，他必使你尋見；你若離棄他，他必永遠丟棄你。","notes":[]},{"n":10,"t":"你當謹慎，因耶和華揀選你建造殿宇作為聖所。你當剛強去行。」","notes":[]},{"n":11,"t":"大衛將殿的遊廊、旁屋、府庫、樓房、內殿，和施恩所的樣式指示他兒子所羅門，","notes":[]},{"n":12,"t":"又將被靈感動所得的樣式，就是耶和華神殿的院子、周圍的房屋、殿的府庫，和聖物府庫的一切樣式都指示他；","notes":[]},{"n":13,"t":"又指示他祭司和利未人的班次與耶和華殿裏各樣的工作，並耶和華殿裏一切器皿的樣式，","notes":[]},{"n":14,"t":"以及各樣應用金器的分兩和各樣應用銀器的分兩，","notes":[]},{"n":15,"t":"金燈臺和金燈的分兩，銀燈臺和銀燈的分兩，輕重各都合宜；","notes":[]},{"n":16,"t":"陳設餅金桌子的分兩，銀桌子的分兩，","notes":[]},{"n":17,"t":"精金的肉叉子、盤子，和爵的分兩，各金碗與各銀碗的分兩，","notes":[]},{"n":18,"t":"精金香壇的分兩，並用金子做基路伯；基路伯張開翅膀，遮掩耶和華的約櫃。","notes":["原文是用金子做車式的基路伯"]},{"n":19,"t":"大衛說：「這一切工作的樣式都是耶和華用手劃出來使我明白的。」","notes":[]},{"n":20,"t":"大衛又對他兒子所羅門說：「你當剛強壯膽去行！不要懼怕，也不要驚惶。因為耶和華神就是我的神，與你同在；他必不撇下你，也不丟棄你，直到耶和華殿的工作都完畢了。","notes":[]},{"n":21,"t":"有祭司和利未人的各班，為要辦理神殿各樣的事，又有靈巧的人在各樣的工作上樂意幫助你；並有眾首領和眾民一心聽從你的命令。」","notes":[]}]},"29":{"heading":"為建殿而獻的禮物","verses":[{"n":1,"t":"大衛王對會眾說：「我兒子所羅門是神特選的，還年幼嬌嫩；這工程甚大，因這殿不是為人，乃是為耶和華神建造的。","notes":[]},{"n":2,"t":"我為我神的殿已經盡力，預備金子做金器，銀子做銀器，銅做銅器，鐵做鐵器，木做木器，還有紅瑪瑙可鑲嵌的寶石，彩石和一切的寶石，並許多漢白玉。","notes":[]},{"n":3,"t":"且因我心中愛慕我神的殿，就在預備建造聖殿的材料之外，又將我自己積蓄的金銀獻上，建造我神的殿，","notes":[]},{"n":4,"t":"就是俄斐金三千他連得、精鍊的銀子七千他連得，以貼殿牆。","notes":[]},{"n":5,"t":"金子做金器，銀子做銀器，並藉匠人的手製造一切。今日有誰樂意將自己獻給耶和華呢？」","notes":[]},{"n":6,"t":"於是，眾族長和以色列各支派的首領、千夫長、百夫長，並監管王工的官長，都樂意獻上。","notes":[]},{"n":7,"t":"他們為神殿的使用獻上金子五千他連得零一萬達利克，銀子一萬他連得，銅一萬八千他連得，鐵十萬他連得。","notes":[]},{"n":8,"t":"凡有寶石的都交給革順人耶歇，送入耶和華殿的府庫。","notes":[]},{"n":9,"t":"因這些人誠心樂意獻給耶和華，百姓就歡喜，大衛王也大大歡喜。","notes":[]},{"n":10,"t":"所以，大衛在會眾面前稱頌耶和華說：「耶和華－我們的父，以色列的神是應當稱頌，直到永永遠遠的！","notes":[],"heads":["大衛稱頌耶和華"]},{"n":11,"t":"耶和華啊，尊大、能力、榮耀、強勝、威嚴都是你的；凡天上地下的都是你的；國度也是你的，並且你為至高，為萬有之首。","notes":[]},{"n":12,"t":"豐富尊榮都從你而來，你也治理萬物。在你手裏有大能大力，使人尊大強盛都出於你。","notes":[]},{"n":13,"t":"我們的神啊，現在我們稱謝你，讚美你榮耀之名！","notes":[]},{"n":14,"t":"「我算甚麼，我的民算甚麼，竟能如此樂意奉獻？因為萬物都從你而來，我們把從你而得的獻給你。","notes":[]},{"n":15,"t":"我們在你面前是客旅，是寄居的，與我們列祖一樣。我們在世的日子如影兒，不能長存。","notes":["或譯：沒有長存的指望"]},{"n":16,"t":"耶和華－我們的神啊，我們預備這許多材料，要為你的聖名建造殿宇，都是從你而來，都是屬你的。","notes":[]},{"n":17,"t":"我的神啊，我知道你察驗人心，喜悅正直；我以正直的心樂意獻上這一切物。現在我喜歡見你的民在這裏都樂意奉獻與你。","notes":[]},{"n":18,"t":"耶和華－我們列祖亞伯拉罕、以撒、以色列的神啊，求你使你的民常存這樣的心思意念，堅定他們的心歸向你，","notes":[]},{"n":19,"t":"又求你賜我兒子所羅門誠實的心，遵守你的命令、法度、律例，成就這一切的事，用我所預備的建造殿宇。」","notes":[]},{"n":20,"t":"大衛對全會眾說：「你們應當稱頌耶和華－你們的神。」於是會眾稱頌耶和華－他們列祖的神，低頭拜耶和華與王。","notes":[]},{"n":21,"t":"次日，他們向耶和華獻平安祭和燔祭，就是獻公牛一千隻，公綿羊一千隻，羊羔一千隻，並同獻的奠祭；又為以色列眾人獻許多的祭。那日，他們在耶和華面前吃喝，大大歡樂。","notes":[]},{"n":22,"t":"他們奉耶和華的命再膏大衛的兒子所羅門作王，又膏撒督作祭司。","notes":[]},{"n":23,"t":"於是所羅門坐在耶和華所賜的位上，接續他父親大衛作王，萬事亨通；以色列眾人也都聽從他。","notes":[]},{"n":24,"t":"眾首領和勇士，並大衛王的眾子，都順服所羅門王。","notes":[]},{"n":25,"t":"耶和華使所羅門在以色列眾人眼前甚為尊大，極其威嚴，勝過在他以前的以色列王。","notes":[]},{"n":26,"t":"耶西的兒子大衛作以色列眾人的王，","notes":[],"heads":["大衛政績簡述"]},{"n":27,"t":"作王共四十年：在希伯崙作王七年，在耶路撒冷作王三十三年。","notes":[]},{"n":28,"t":"他年紀老邁，日子滿足，享受豐富、尊榮，就死了。他兒子所羅門接續他作王。","notes":[]},{"n":29,"t":"大衛王始終的事都寫在先見撒母耳的書上和先知拿單並先見迦得的書上。","notes":[]},{"n":30,"t":"他的國事和他的勇力，以及他和以色列並列國所經過的事都寫在這書上。","notes":[]}]}},"2CH":{"1":{"heading":"所羅門王祈求智慧","verses":[{"n":1,"t":"大衛的兒子所羅門國位堅固；耶和華－他的神與他同在，使他甚為尊大。","notes":[]},{"n":2,"t":"所羅門吩咐以色列眾人，就是千夫長、百夫長、審判官、首領與族長都來。","notes":[]},{"n":3,"t":"所羅門和會眾都往基遍的邱壇去，因那裏有神的會幕，就是耶和華僕人摩西在曠野所製造的。","notes":[]},{"n":4,"t":"只是神的約櫃，大衛已經從基列‧耶琳搬到他所預備的地方，因他曾在耶路撒冷為約櫃支搭了帳幕，","notes":[]},{"n":5,"t":"並且戶珥的孫子、烏利的兒子比撒列所造的銅壇也在基遍耶和華的會幕前。所羅門和會眾都就近壇前。","notes":[]},{"n":6,"t":"所羅門上到耶和華面前會幕的銅壇那裏，獻一千犧牲為燔祭。","notes":[]},{"n":7,"t":"當夜，神向所羅門顯現，對他說：「你願我賜你甚麼，你可以求。」","notes":[]},{"n":8,"t":"所羅門對神說：「你曾向我父大衛大施慈愛，使我接續他作王。","notes":[]},{"n":9,"t":"耶和華神啊，現在求你成就向我父大衛所應許的話；因你立我作這民的王，他們如同地上塵沙那樣多。","notes":[]},{"n":10,"t":"求你賜我智慧聰明，我好在這民前出入；不然，誰能判斷這眾多的民呢？」","notes":[]},{"n":11,"t":"神對所羅門說：「我已立你作我民的王。你既有這心意，並不求資財、豐富、尊榮，也不求滅絕那恨你之人的性命，又不求大壽數，只求智慧聰明好判斷我的民；","notes":[]},{"n":12,"t":"我必賜你智慧聰明，也必賜你資財、豐富、尊榮。在你以前的列王都沒有這樣，在你以後也必沒有這樣的。」","notes":[]},{"n":13,"t":"於是，所羅門從基遍邱壇會幕前回到耶路撒冷，治理以色列人。","notes":[]},{"n":14,"t":"所羅門聚集戰車馬兵，有戰車一千四百輛，馬兵一萬二千名，安置在屯車的城邑和耶路撒冷，就是王那裏。","notes":[],"heads":["所羅門的權力和財力"]},{"n":15,"t":"王在耶路撒冷使金銀多如石頭，香柏木多如高原的桑樹。","notes":[]},{"n":16,"t":"所羅門的馬是從埃及帶來的，是王的商人一群一群按著定價買來的。","notes":[]},{"n":17,"t":"他們從埃及買來的車，每輛價銀六百舍客勒，馬每匹一百五十舍客勒。赫人諸王和亞蘭諸王所買的車馬，也是按這價值經他們手買來的。","notes":[]}]},"2":{"heading":"籌備建造聖殿","verses":[{"n":1,"t":"所羅門定意要為耶和華的名建造殿宇，又為自己的國建造宮室。","notes":[]},{"n":2,"t":"所羅門就挑選七萬扛抬的，八萬在山上鑿石頭的，三千六百督工的。","notes":[]},{"n":3,"t":"所羅門差人去見泰爾王希蘭，說：「你曾運香柏木與我父大衛建宮居住，求你也這樣待我。","notes":[]},{"n":4,"t":"我要為耶和華－我神的名建造殿宇，分別為聖獻給他，在他面前焚燒美香，常擺陳設餅，每早晚、安息日、月朔，並耶和華－我們神所定的節期獻燔祭。這是以色列人永遠的定例。","notes":[]},{"n":5,"t":"我所要建造的殿宇甚大；因為我們的神至大，超乎諸神。","notes":[]},{"n":6,"t":"天和天上的天，尚且不足他居住的，誰能為他建造殿宇呢？我是誰？能為他建造殿宇嗎？不過在他面前燒香而已。","notes":[]},{"n":7,"t":"現在求你差一個巧匠來，就是善用金、銀、銅、鐵，和紫色、朱紅色、藍色線，並精於雕刻之工的巧匠，與我父大衛在猶大和耶路撒冷所預備的巧匠一同做工；","notes":[]},{"n":8,"t":"又求你從黎巴嫩運些香柏木、松木、檀香木到我這裏來，因我知道你的僕人善於砍伐黎巴嫩的樹木。我的僕人也必與你的僕人同工。","notes":[]},{"n":9,"t":"這樣，可以給我預備許多的木料，因我要建造的殿宇高大出奇。","notes":[]},{"n":10,"t":"你的僕人砍伐樹木，我必給他們打好了的小麥二萬歌珥，大麥二萬歌珥，酒二萬罷特，油二萬罷特。」","notes":[]},{"n":11,"t":"泰爾王希蘭寫信回答所羅門說：「耶和華因為愛他的子民，所以立你作他們的王」；","notes":[]},{"n":12,"t":"又說：「創造天地的耶和華－以色列的神是應當稱頌的！他賜給大衛王一個有智慧的兒子，使他有謀略聰明，可以為耶和華建造殿宇，又為自己的國建造宮室。","notes":[]},{"n":13,"t":"「現在我打發一個精巧有聰明的人去，他是我父親希蘭所用的，","notes":[]},{"n":14,"t":"是但支派一個婦人的兒子。他父親是泰爾人，他善用金、銀、銅、鐵、石、木，和紫色、藍色、朱紅色線與細麻製造各物，並精於雕刻，又能想出各樣的巧工。請你派定這人，與你的巧匠和你父－我主大衛的巧匠一同做工。","notes":[]},{"n":15,"t":"我主所說的小麥、大麥、酒、油，願我主運來給眾僕人。","notes":[]},{"n":16,"t":"我們必照你所需用的，從黎巴嫩砍伐樹木，紮成筏子，浮海運到約帕；你可以從那裏運到耶路撒冷。」","notes":[]},{"n":17,"t":"所羅門仿照他父大衛數點住在以色列地所有寄居的外邦人，共有十五萬三千六百名；","notes":[],"heads":["聖殿工程動工"]},{"n":18,"t":"使七萬人扛抬材料，八萬人在山上鑿石頭，三千六百人督理工作。","notes":[]}]},"3":{"heading":"兩根銅柱","verses":[{"n":1,"t":"所羅門就在耶路撒冷、耶和華向他父大衛顯現的摩利亞山上，就是耶布斯人阿珥楠的禾場上、大衛所指定的地方預備好了，開工建造耶和華的殿。","notes":[]},{"n":2,"t":"所羅門作王第四年二月初二日開工建造。","notes":[]},{"n":3,"t":"所羅門建築神殿的根基，乃是這樣：長六十肘，寬二十肘，都按著古時的尺寸。","notes":[]},{"n":4,"t":"殿前的廊子長二十肘，與殿的寬窄一樣，高一百二十肘；裏面貼上精金。","notes":[]},{"n":5,"t":"大殿的牆都用松木板遮蔽，又貼了精金，上面雕刻棕樹和鍊子；","notes":[]},{"n":6,"t":"又用寶石裝飾殿牆，使殿華美；所用的金子都是巴瓦音的金子。","notes":[]},{"n":7,"t":"又用金子貼殿和殿的棟樑、門檻、牆壁、門扇；牆上雕刻基路伯。","notes":[]},{"n":8,"t":"又建造至聖所，長二十肘，與殿的寬窄一樣，寬也是二十肘；貼上精金，共用金子六百他連得。","notes":[]},{"n":9,"t":"金釘重五十舍客勒。樓房都貼上金子。","notes":[]},{"n":10,"t":"在至聖所按造像的法子造兩個基路伯，用金子包裹。","notes":[]},{"n":11,"t":"兩個基路伯的翅膀共長二十肘。這基路伯的一個翅膀長五肘，挨著殿這邊的牆；那一個翅膀也長五肘，與那基路伯翅膀相接。","notes":[]},{"n":12,"t":"那基路伯的一個翅膀長五肘，挨著殿那邊的牆；那一個翅膀也長五肘，與這基路伯的翅膀相接。","notes":[]},{"n":13,"t":"兩個基路伯張開翅膀，共長二十肘，面向外殿而立。","notes":[]},{"n":14,"t":"又用藍色、紫色、朱紅色線和細麻織幔子，在其上繡出基路伯來。","notes":[]},{"n":15,"t":"在殿前造了兩根柱子，高三十五肘；每柱頂高五肘。","notes":[]},{"n":16,"t":"又照聖所內鍊子的樣式做鍊子，安在柱頂上；又做一百石榴，安在鍊子上。","notes":[]},{"n":17,"t":"將兩根柱子立在殿前，一根在右邊，一根在左邊；右邊的起名叫雅斤，左邊的起名叫波阿斯。","notes":[]}]},"4":{"heading":"聖殿的設備","verses":[{"n":1,"t":"他又製造一座銅壇，長二十肘，寬二十肘，高十肘；","notes":[]},{"n":2,"t":"又鑄一個銅海，樣式是圓的，高五肘，徑十肘，圍三十肘；","notes":[]},{"n":3,"t":"海周圍有野瓜的樣式，每肘十瓜，共有兩行，是鑄海的時候鑄上的；","notes":["野瓜：原文是牛"]},{"n":4,"t":"有十二隻銅牛馱海：三隻向北，三隻向西，三隻向南，三隻向東；海在牛上，牛尾向內；","notes":[]},{"n":5,"t":"海厚一掌，邊如杯邊，又如百合花，可容三千罷特；","notes":[]},{"n":6,"t":"又製造十個盆：五個放在右邊，五個放在左邊，獻燔祭所用之物都洗在其內；但海是為祭司沐浴的。","notes":[]},{"n":7,"t":"他又照所定的樣式造十個金燈臺，放在殿裏：五個在右邊，五個在左邊；","notes":[]},{"n":8,"t":"又造十張桌子，放在殿裏：五張在右邊，五張在左邊；又造一百個金碗；","notes":[]},{"n":9,"t":"又建立祭司院和大院，並院門，用銅包裹門扇；","notes":[]},{"n":10,"t":"將海安在殿門的右邊，就是南邊。","notes":[]},{"n":11,"t":"戶蘭又造了盆、鏟、碗。這樣，他為所羅門王做完了神殿的工。","notes":[]},{"n":12,"t":"所造的就是：兩根柱子和柱上兩個如球的頂，並兩個蓋柱頂的網子","notes":[]},{"n":13,"t":"和四百石榴，安在兩個網子上（每網兩行蓋著兩個柱上如球的頂）。","notes":[]},{"n":14,"t":"盆座和其上的盆，","notes":[]},{"n":15,"t":"海和海下的十二隻牛，","notes":[]},{"n":16,"t":"盆、鏟子、肉鍤子，與耶和華殿裏的一切器皿，都是巧匠戶蘭用光亮的銅為所羅門王造成的，","notes":[]},{"n":17,"t":"是在約旦平原疏割和撒利但中間藉膠泥鑄成的。","notes":[]},{"n":18,"t":"所羅門製造的這一切甚多，銅的輕重無法可查。","notes":[]},{"n":19,"t":"所羅門又造神殿裏的金壇和陳設餅的桌子，","notes":[]},{"n":20,"t":"並精金的燈臺和燈盞，可以照例點在內殿前。","notes":[]},{"n":21,"t":"燈臺上的花和燈盞，並蠟剪都是金的，且是純金的；","notes":[]},{"n":22,"t":"又用精金製造鑷子、盤子、調羹、火鼎。至於殿門和至聖所的門扇，並殿的門扇，都是金子妝飾的。","notes":[]}]},"5":{"heading":"運約櫃入殿","verses":[{"n":1,"t":"所羅門做完了耶和華殿的一切工，就把他父大衛分別為聖的金銀和器皿都帶來，放在神殿的府庫裏。","notes":[]},{"n":2,"t":"那時，所羅門將以色列的長老、各支派的首領，並以色列的族長招聚到耶路撒冷，要把耶和華的約櫃從大衛城－就是錫安－運上來。","notes":[]},{"n":3,"t":"於是以色列眾人在七月節前都聚集到王那裏。","notes":[]},{"n":4,"t":"以色列眾長老來到，利未人便抬起約櫃。","notes":[]},{"n":5,"t":"祭司利未人將約櫃運上來，又將會幕和會幕的一切聖器具都帶上來。","notes":[]},{"n":6,"t":"所羅門王和聚集到他那裏的以色列全會眾都在約櫃前獻牛羊為祭，多得不可勝數。","notes":[]},{"n":7,"t":"祭司將耶和華的約櫃抬進內殿，就是至聖所，放在兩個基路伯的翅膀底下。","notes":[]},{"n":8,"t":"基路伯張著翅膀在約櫃之上，遮掩約櫃和抬櫃的槓。","notes":[]},{"n":9,"t":"這槓甚長，槓頭在內殿前可以看見，在殿外卻不能看見，直到如今還在那裏。","notes":[]},{"n":10,"t":"約櫃裏惟有兩塊石版，就是以色列人出埃及後，耶和華與他們立約的時候，摩西在何烈山所放的。除此以外，並無別物。","notes":[]},{"n":11,"t":"當時，在那裏所有的祭司都已自潔，並不分班供職。","notes":[],"heads":["神的榮光"]},{"n":12,"t":"他們出聖所的時候，歌唱的利未人亞薩、希幔、耶杜頓，和他們的眾子眾弟兄都穿細麻布衣服，站在壇的東邊，敲鈸、鼓瑟、彈琴，同著他們有一百二十個祭司吹號。","notes":[]},{"n":13,"t":"吹號的、歌唱的都一齊發聲，聲合為一，讚美感謝耶和華。吹號、敲鈸，用各種樂器，揚聲讚美耶和華說：耶和華本為善，他的慈愛永遠長存！那時，耶和華的殿有雲充滿，","notes":[]},{"n":14,"t":"甚至祭司不能站立供職，因為耶和華的榮光充滿了神的殿。","notes":[]}]},"6":{"heading":"所羅門向人民宣告","verses":[{"n":1,"t":"那時，所羅門說：耶和華曾說他必住在幽暗之處。","notes":[]},{"n":2,"t":"但我已經建造殿宇作你的居所，為你永遠的住處。","notes":[]},{"n":3,"t":"王轉臉為以色列會眾祝福，以色列會眾就都站立。","notes":[]},{"n":4,"t":"所羅門說：「耶和華－以色列的神是應當稱頌的！因他親口向我父大衛所應許的，也親手成就了。","notes":[]},{"n":5,"t":"他說：『自從我領我民出埃及地以來，我未曾在以色列眾支派中選擇一城建造殿宇為我名的居所，也未曾揀選一人作我民以色列的君；","notes":[]},{"n":6,"t":"但選擇耶路撒冷為我名的居所，又揀選大衛治理我民以色列。』」","notes":[]},{"n":7,"t":"所羅門說：「我父大衛曾立意要為耶和華－以色列神的名建殿，","notes":[]},{"n":8,"t":"耶和華卻對我父大衛說：『你立意要為我的名建殿，這意思甚好；","notes":[]},{"n":9,"t":"只是你不可建殿，惟你所生的兒子必為我名建殿。』","notes":[]},{"n":10,"t":"「現在耶和華成就了他所應許的話，使我接續我父大衛坐以色列的國位，是照耶和華所說的，又為耶和華－以色列神的名建造了殿。","notes":[]},{"n":11,"t":"我將約櫃安置在其中，櫃內有耶和華的約，就是他與以色列人所立的約。」","notes":[]},{"n":12,"t":"所羅門當著以色列會眾，站在耶和華的壇前，舉起手來，","notes":[],"heads":["所羅門的禱告"]},{"n":13,"t":"（所羅門曾造一個銅臺，長五肘，寬五肘，高三肘，放在院中）就站在臺上，當著以色列的會眾跪下，向天舉手，","notes":[]},{"n":14,"t":"說：「耶和華－以色列的神啊，天上地下沒有神可比你的！你向那盡心行在你面前的僕人守約施慈愛；","notes":[]},{"n":15,"t":"向你僕人－我父大衛所應許的話現在應驗了。你親口應許，親手成就，正如今日一樣。","notes":[]},{"n":16,"t":"耶和華－以色列的神啊，你所應許你僕人－我父大衛的話說：『你的子孫若謹慎自己的行為，遵守我的律法，像你在我面前所行的一樣，就不斷人坐以色列的國位。』現在求你應驗這話。","notes":[]},{"n":17,"t":"耶和華－以色列的神啊，求你成就向你僕人大衛所應許的話。","notes":[]},{"n":18,"t":"「神果真與世人同住在地上嗎？看哪，天和天上的天尚且不足你居住的，何況我所建的這殿呢？","notes":[]},{"n":19,"t":"惟求耶和華－我的神垂顧僕人的禱告祈求，俯聽僕人在你面前的祈禱呼籲。","notes":[]},{"n":20,"t":"願你晝夜看顧這殿，就是你應許立為你名的居所；求你垂聽僕人向此處禱告的話。","notes":[]},{"n":21,"t":"你僕人和你民以色列向此處祈禱的時候，求你從天上你的居所垂聽，垂聽而赦免。","notes":[]},{"n":22,"t":"「人若得罪鄰舍，有人叫他起誓，他來到這殿，在你的壇前起誓，","notes":[]},{"n":23,"t":"求你從天上垂聽，判斷你的僕人，定惡人有罪，照他所行的報應在他頭上；定義人有理，照他的義賞賜他。","notes":[]},{"n":24,"t":"「你的民以色列若得罪你，敗在仇敵面前，又回心轉意承認你的名，在這殿裏向你祈求禱告，","notes":[]},{"n":25,"t":"求你從天上垂聽，赦免你民以色列的罪，使他們歸回你賜給他們和他們列祖之地。","notes":[]},{"n":26,"t":"「你的民因得罪你，你懲罰他們，使天閉塞不下雨，他們若向此處禱告，承認你的名，離開他們的罪，","notes":[]},{"n":27,"t":"求你在天上垂聽，赦免你僕人和你民以色列的罪，將當行的善道指教他們，且降雨在你的地，就是你賜給你民為業之地。","notes":[]},{"n":28,"t":"「國中若有饑荒、瘟疫、旱風、霉爛、蝗蟲、螞蚱，或有仇敵犯境，圍困城邑，無論遭遇甚麼災禍疾病，","notes":[]},{"n":29,"t":"你的民以色列，或是眾人，或是一人，自覺災禍甚苦，向這殿舉手，無論祈求甚麼，禱告甚麼，","notes":[]},{"n":30,"t":"求你從天上你的居所垂聽赦免。你是知道人心的，要照各人所行的待他們（惟有你知道世人的心），","notes":[]},{"n":31,"t":"使他們在你賜給我們列祖之地上一生一世敬畏你，遵行你的道。","notes":[]},{"n":32,"t":"「論到不屬你民以色列的外邦人，為你的大名和大能的手，並伸出來的膀臂，從遠方而來，向這殿禱告，","notes":[]},{"n":33,"t":"求你從天上你的居所垂聽，照著外邦人所祈求的而行，使天下萬民都認識你的名，敬畏你，像你的民以色列一樣，又使他們知道我建造的這殿是稱為你名下的。","notes":[]},{"n":34,"t":"「你的民若奉你的差遣，無論往何處去與仇敵爭戰，向你所選擇的城與我為你名所建造的殿禱告，","notes":[]},{"n":35,"t":"求你從天上垂聽他們的禱告祈求，使他們得勝。","notes":[]},{"n":36,"t":"「你的民若得罪你（世上沒有不犯罪的人），你向他們發怒，將他們交給仇敵擄到或遠或近之地；","notes":[]},{"n":37,"t":"他們若在擄到之地想起罪來，回心轉意，懇求你說：『我們有罪了，我們悖逆了，我們作惡了』；","notes":[]},{"n":38,"t":"他們若在擄到之地盡心盡性歸服你，又向自己的地，就是你賜給他們列祖之地和你所選擇的城，並我為你名所建造的殿禱告，","notes":[]},{"n":39,"t":"求你從天上你的居所垂聽你民的禱告祈求，為他們伸冤，赦免他們的過犯。","notes":[]},{"n":40,"t":"「我的神啊，現在求你睜眼看，側耳聽在此處所獻的禱告。","notes":[]},{"n":41,"t":"耶和華神啊，求你起來，和你有能力的約櫃同入安息之所。耶和華神啊，願你的祭司披上救恩；願你的聖民蒙福歡樂。","notes":[]},{"n":42,"t":"耶和華神啊，求你不要厭棄你的受膏者，要記念向你僕人大衛所施的慈愛。」","notes":[]}]},"7":{"heading":"聖殿的奉獻禮","verses":[{"n":1,"t":"所羅門祈禱已畢，就有火從天上降下來，燒盡燔祭和別的祭。耶和華的榮光充滿了殿；","notes":[]},{"n":2,"t":"因耶和華的榮光充滿了耶和華殿，所以祭司不能進殿。","notes":[]},{"n":3,"t":"那火降下、耶和華的榮光在殿上的時候，以色列眾人看見，就在鋪石地俯伏叩拜，稱謝耶和華說：耶和華本為善，他的慈愛永遠長存！","notes":[]},{"n":4,"t":"王和眾民在耶和華面前獻祭。","notes":[]},{"n":5,"t":"所羅門王用牛二萬二千，羊十二萬獻祭。這樣，王和眾民為神的殿行奉獻之禮。","notes":[]},{"n":6,"t":"祭司侍立，各供其職；利未人也拿著耶和華的樂器，就是大衛王造出來、藉利未人頌讚耶和華的。（他的慈愛永遠長存！）祭司在眾人面前吹號，以色列人都站立。","notes":[]},{"n":7,"t":"所羅門因他所造的銅壇容不下燔祭、素祭，和脂油，便將耶和華殿前院子當中分別為聖，在那裏獻燔祭和平安祭牲的脂油。","notes":[]},{"n":8,"t":"那時所羅門和以色列眾人，就是從哈馬口直到埃及小河，所有的以色列人都聚集成為大會，守節七日。","notes":[]},{"n":9,"t":"第八日設立嚴肅會，行奉獻壇的禮七日，守節七日。","notes":[]},{"n":10,"t":"七月二十三日，王遣散眾民；他們因見耶和華向大衛和所羅門與他民以色列所施的恩惠，就都心中喜樂，各歸各家去了。","notes":[]},{"n":11,"t":"所羅門造成了耶和華殿和王宮；在耶和華殿和王宮凡他心中所要做的，都順順利利地做成了。","notes":[],"heads":["神再次向所羅門顯現"]},{"n":12,"t":"夜間耶和華向所羅門顯現，對他說：「我已聽了你的禱告，也選擇這地方作為祭祀我的殿宇。","notes":[]},{"n":13,"t":"我若使天閉塞不下雨，或使蝗蟲吃這地的出產，或使瘟疫流行在我民中，","notes":[]},{"n":14,"t":"這稱為我名下的子民，若是自卑、禱告，尋求我的面，轉離他們的惡行，我必從天上垂聽，赦免他們的罪，醫治他們的地。","notes":[]},{"n":15,"t":"我必睜眼看、側耳聽在此處所獻的禱告。","notes":[]},{"n":16,"t":"現在我已選擇這殿，分別為聖，使我的名永在其中，我的眼、我的心也必常在那裏。","notes":[]},{"n":17,"t":"你若在我面前效法你父大衛所行的，遵行我一切所吩咐你的，謹守我的律例典章，","notes":[]},{"n":18,"t":"我就必堅固你的國位，正如我與你父大衛所立的約，說：『你的子孫必不斷人作以色列的王。』","notes":[]},{"n":19,"t":"「倘若你們轉去丟棄我指示你們的律例誡命，去事奉敬拜別神，","notes":[]},{"n":20,"t":"我就必將以色列人從我賜給他們的地上拔出根來，並且我為己名所分別為聖的殿也必捨棄不顧，使他在萬民中作笑談，被譏誚。","notes":[]},{"n":21,"t":"這殿雖然甚高，將來經過的人必驚訝說：『耶和華為何向這地和這殿如此行呢？』","notes":[]},{"n":22,"t":"人必回答說：『是因此地的人離棄耶和華－他們列祖的神，就是領他們出埃及地的神，去親近別神，敬拜事奉他，所以耶和華使這一切災禍臨到他們。』」","notes":[]}]},"8":{"heading":"所羅門的成就","verses":[{"n":1,"t":"所羅門建造耶和華殿和王宮，二十年才完畢了。","notes":[]},{"n":2,"t":"以後所羅門重新修築希蘭送給他的那些城邑，使以色列人住在那裏。","notes":[]},{"n":3,"t":"所羅門往哈馬瑣巴去，攻取了那地方。","notes":[]},{"n":4,"t":"所羅門建造曠野裏的達莫，又建造哈馬所有的積貨城，","notes":[]},{"n":5,"t":"又建造上伯‧和崙、下伯‧和崙作為保障，都有牆，有門，有閂；","notes":[]},{"n":6,"t":"又建造巴拉和所有的積貨城，並屯車輛馬兵的城，與耶路撒冷、黎巴嫩，以及自己治理的全國中所願意建造的。","notes":[]},{"n":7,"t":"至於國中所剩下不屬以色列人的赫人、亞摩利人、比利洗人、希未人、耶布斯人，","notes":[]},{"n":8,"t":"就是以色列人未曾滅絕的，所羅門挑取他們的後裔作服苦的奴僕，直到今日。","notes":[]},{"n":9,"t":"惟有以色列人，所羅門不使他們當奴僕做工，乃是作他的戰士、軍長的統領、車兵長、馬兵長。","notes":[]},{"n":10,"t":"所羅門王有二百五十督工的，監管工人。","notes":[]},{"n":11,"t":"所羅門將法老的女兒帶出大衛城，上到為她建造的宮裏；因所羅門說：「耶和華約櫃所到之處都為聖地，所以我的妻不可住在以色列王大衛的宮裏。」","notes":[]},{"n":12,"t":"所羅門在耶和華的壇上，就是在廊子前他所築的壇上，與耶和華獻燔祭；","notes":[]},{"n":13,"t":"又遵著摩西的吩咐在安息日、月朔，並一年三節，就是除酵節、七七節、住棚節，獻每日所當獻的祭。","notes":[]},{"n":14,"t":"所羅門照著他父大衛所定的例，派定祭司的班次，使他們各供己事，又使利未人各盡其職，讚美耶和華，在祭司面前做每日所當做的；又派守門的按著班次看守各門，因為神人大衛是這樣吩咐的。","notes":[]},{"n":15,"t":"王所吩咐眾祭司和利未人的，無論是管府庫或辦別的事，他們都不違背。","notes":[]},{"n":16,"t":"所羅門建造耶和華的殿，從立根基直到成功的日子，工料俱備。這樣，耶和華的殿全然完畢。","notes":[]},{"n":17,"t":"那時，所羅門往以東地靠海的以旬‧迦別和以祿去。","notes":[]},{"n":18,"t":"希蘭差遣他的臣僕，將船隻和熟悉泛海的僕人送到所羅門那裏。他們同著所羅門的僕人到了俄斐，得了四百五十他連得金子，運到所羅門王那裏。","notes":[]}]},"9":{"heading":"示巴女王訪問所羅門","verses":[{"n":1,"t":"示巴女王聽見所羅門的名聲，就來到耶路撒冷，要用難解的話試問所羅門；跟隨她的人甚多，又有駱駝馱著香料、寶石，和許多金子。她來見了所羅門，就把心裏所有的對所羅門都說出來。","notes":[]},{"n":2,"t":"所羅門將她所問的都答上了，沒有一句不明白、不能答的。","notes":[]},{"n":3,"t":"示巴女王見所羅門的智慧和他所建造的宮室、","notes":[]},{"n":4,"t":"席上的珍饈美味、群臣分列而坐、僕人兩旁侍立，以及他們的衣服裝飾、酒政，和酒政的衣服裝飾，又見他上耶和華殿的臺階，就詫異得神不守舍，","notes":[]},{"n":5,"t":"對王說：「我在本國裏所聽見論到你的事和你的智慧實在是真的！","notes":[]},{"n":6,"t":"我先不信那些話，及至我來親眼見了，才知道你的大智慧；人所告訴我的，還不到一半；你的實跡越過我所聽見的名聲。","notes":[]},{"n":7,"t":"你的群臣、你的僕人常侍立在你面前聽你智慧的話是有福的。","notes":[]},{"n":8,"t":"耶和華－你的神是應當稱頌的！他喜悅你，使你坐他的國位，為耶和華－你的神作王；因為你的神愛以色列人，要永遠堅立他們，所以立你作他們的王，使你秉公行義。」","notes":[]},{"n":9,"t":"於是示巴女王將一百二十他連得金子和寶石，與極多的香料送給所羅門王；她送給王的香料，以後再沒有這樣的。","notes":[]},{"n":10,"t":"希蘭的僕人和所羅門的僕人從俄斐運了金子來，也運了檀香木和寶石來。","notes":["或譯：烏木；下同"]},{"n":11,"t":"王用檀香木為耶和華殿和王宮做臺，又為歌唱的人做琴瑟；猶大地從來沒有見過這樣的。","notes":[]},{"n":12,"t":"所羅門王按示巴女王所帶來的，還她禮物，另外照她一切所要所求的，都送給她。於是女王和她臣僕轉回本國去了。","notes":[]},{"n":13,"t":"所羅門每年所得的金子共有六百六十六他連得，","notes":[],"heads":["所羅門王的財富"]},{"n":14,"t":"另外還有商人所進的金子，並且阿拉伯諸王與屬國的省長都帶金銀給所羅門。","notes":[]},{"n":15,"t":"所羅門王用錘出來的金子打成擋牌二百面，每面用金子六百舍客勒；","notes":[]},{"n":16,"t":"又用錘出來的金子打成盾牌三百面，每面用金子三百舍客勒，都放在黎巴嫩林宮裏。","notes":[]},{"n":17,"t":"王用象牙製造一個大寶座，用精金包裹。","notes":[]},{"n":18,"t":"寶座有六層臺階，又有金腳凳，與寶座相連。寶座兩旁有扶手，靠近扶手有兩個獅子站立。","notes":[]},{"n":19,"t":"六層臺階上有十二個獅子站立，每層有兩個：左邊一個，右邊一個；在列國中沒有這樣做的。","notes":[]},{"n":20,"t":"所羅門王一切的飲器都是金的，黎巴嫩林宮裏的一切器皿都是精金的。所羅門年間，銀子算不了甚麼。","notes":[]},{"n":21,"t":"因為王的船隻與希蘭的僕人一同往他施去；他施船隻三年一次裝載金、銀、象牙、猿猴、孔雀回來。","notes":[]},{"n":22,"t":"所羅門王的財寶與智慧勝過天下的列王。","notes":[]},{"n":23,"t":"普天下的王都求見所羅門，要聽神賜給他智慧的話。","notes":[]},{"n":24,"t":"他們各帶貢物，就是金器、銀器、衣服、軍械、香料、騾馬，每年有一定之例。","notes":[]},{"n":25,"t":"所羅門有套車的馬四千棚，有馬兵一萬二千，安置在屯車的城邑和耶路撒冷，就是王那裏。","notes":[]},{"n":26,"t":"所羅門統管諸王，從大河到非利士地，直到埃及的邊界。","notes":[]},{"n":27,"t":"王在耶路撒冷使銀子多如石頭，香柏木多如高原的桑樹。","notes":[]},{"n":28,"t":"有人從埃及和各國為所羅門趕馬群來。","notes":[]},{"n":29,"t":"所羅門其餘的事，自始至終，不都寫在先知拿單的書上和示羅人亞希雅的預言書上，並先見易多論尼八兒子耶羅波安的默示書上嗎？","notes":[],"heads":["所羅門政績簡述"]},{"n":30,"t":"所羅門在耶路撒冷作以色列眾人的王共四十年。","notes":[]},{"n":31,"t":"所羅門與他列祖同睡，葬在他父大衛城裏。他兒子羅波安接續他作王。","notes":[]}]},"10":{"heading":"北部支派的反叛","verses":[{"n":1,"t":"羅波安往示劍去，因為以色列人都到了示劍，要立他作王。","notes":[]},{"n":2,"t":"尼八的兒子耶羅波安先前躲避所羅門王，逃往埃及，住在那裏；他聽見這事，就從埃及回來。","notes":[]},{"n":3,"t":"以色列人打發人去請他，他就和以色列眾人來見羅波安，對他說：","notes":[]},{"n":4,"t":"「你父親使我們負重軛做苦工，現在求你使我們做的苦工負的重軛輕鬆些，我們就事奉你。」","notes":[]},{"n":5,"t":"羅波安對他們說：「第三日再來見我吧！」民就去了。","notes":[]},{"n":6,"t":"羅波安之父所羅門在世的日子，有侍立在他面前的老年人，羅波安王和他們商議，說：「你們給我出個甚麼主意，我好回覆這民。」","notes":[]},{"n":7,"t":"老年人對他說：「王若恩待這民，使他們喜悅，用好話回覆他們，他們就永遠作王的僕人。」","notes":[]},{"n":8,"t":"王卻不用老年人給他出的主意，就和那些與他一同長大、在他面前侍立的少年人商議，","notes":[]},{"n":9,"t":"說：「這民對我說：『你父親使我們負重軛，求你使我們輕鬆些』；你們給我出個甚麼主意，我好回覆他們。」","notes":[]},{"n":10,"t":"那同他長大的少年人說：「這民對王說：『你父親使我們負重軛，求你使我們輕鬆些』；王要對他們如此說：『我的小拇指比我父親的腰還粗；","notes":[]},{"n":11,"t":"我父親使你們負重軛，我必使你們負更重的軛；我父親用鞭子責打你們，我要用蠍子鞭責打你們。』」","notes":[]},{"n":12,"t":"耶羅波安和眾百姓遵著羅波安王所說「你們第三日再來見我」的那話，第三日他們果然來了。","notes":[]},{"n":13,"t":"羅波安王用嚴厲的話回覆他們，不用老年人所出的主意，","notes":[]},{"n":14,"t":"照著少年人所出的主意對他們說：「我父親使你們負重軛，我必使你們負更重的軛；我父親用鞭子責打你們，我要用蠍子鞭責打你們。」","notes":[]},{"n":15,"t":"王不肯依從百姓；這事乃出於神，為要應驗耶和華藉示羅人亞希雅對尼八兒子耶羅波安所說的話。","notes":[]},{"n":16,"t":"以色列眾民見王不依從他們，就對王說：我們與大衛有甚麼分兒呢？與耶西的兒子並沒有關涉！以色列人哪，各回各家去吧！大衛家啊，自己顧自己吧！於是，以色列眾人都回自己家裏去了。","notes":[]},{"n":17,"t":"惟獨住在猶大城邑的以色列人，羅波安仍作他們的王。","notes":[]},{"n":18,"t":"羅波安王差遣掌管服苦之人的哈多蘭往以色列人那裏去，以色列人就用石頭打死他。羅波安王急忙上車，逃回耶路撒冷去了。","notes":[]},{"n":19,"t":"這樣，以色列人背叛大衛家，直到今日。","notes":[]}]},"11":{"heading":"示瑪雅的預言","verses":[{"n":1,"t":"羅波安來到耶路撒冷，招聚猶大家和便雅憫家，共十八萬人，都是挑選的戰士，要與以色列人爭戰，好將國奪回再歸自己。","notes":[]},{"n":2,"t":"但耶和華的話臨到神人示瑪雅說：","notes":[]},{"n":3,"t":"「你去告訴所羅門的兒子猶大王羅波安和住猶大、便雅憫的以色列眾人說，","notes":[]},{"n":4,"t":"耶和華如此說：『你們不可上去與你們的弟兄爭戰，各歸各家去吧！因為這事出於我。』」眾人就聽從耶和華的話歸回，不去與耶羅波安爭戰。","notes":[]},{"n":5,"t":"羅波安住在耶路撒冷，在猶大地修築城邑，","notes":[],"heads":["羅波安修築諸城"]},{"n":6,"t":"為保障修築伯利恆、以坦、提哥亞、","notes":[]},{"n":7,"t":"伯‧夙、梭哥、亞杜蘭、","notes":[]},{"n":8,"t":"迦特、瑪利沙、西弗、","notes":[]},{"n":9,"t":"亞多萊音、拉吉、亞西加、","notes":[]},{"n":10,"t":"瑣拉、亞雅崙、希伯崙。這都是猶大和便雅憫的堅固城。","notes":[]},{"n":11,"t":"羅波安又堅固各處的保障，在其中安置軍長，又預備下糧食、油、酒。","notes":[]},{"n":12,"t":"他在各城裏預備盾牌和槍，且使城極其堅固。猶大和便雅憫都歸了他。","notes":[]},{"n":13,"t":"以色列全地的祭司和利未人都從四方來歸羅波安。","notes":[],"heads":["祭司和利未人都歸猶大"]},{"n":14,"t":"利未人撇下他們的郊野和產業，來到猶大與耶路撒冷，是因耶羅波安和他的兒子拒絕他們，不許他們供祭司職分事奉耶和華。","notes":[]},{"n":15,"t":"耶羅波安為邱壇、為鬼魔、為自己所鑄造的牛犢設立祭司。","notes":["原文是公山羊"]},{"n":16,"t":"以色列各支派中，凡立定心意尋求耶和華－以色列神的，都隨從利未人，來到耶路撒冷祭祀耶和華－他們列祖的神。","notes":[]},{"n":17,"t":"這樣，就堅固猶大國，使所羅門的兒子羅波安強盛三年，因為他們三年遵行大衛和所羅門的道。","notes":[]},{"n":18,"t":"羅波安娶大衛兒子耶利摩的女兒瑪哈拉為妻，又娶耶西兒子以利押的女兒亞比孩為妻。","notes":[],"heads":["羅波安的家室"]},{"n":19,"t":"從她生了幾個兒子，就是耶烏施、示瑪利雅、撒罕。","notes":[]},{"n":20,"t":"後來又娶押沙龍的女兒瑪迦，從她生了亞比雅、亞太、細撒、示羅密。","notes":["十三章二節是烏列的女兒米該亞"]},{"n":21,"t":"羅波安娶十八個妻，立六十個妾，生二十八個兒子，六十個女兒；他卻愛押沙龍的女兒瑪迦，比愛別的妻妾更甚。","notes":[]},{"n":22,"t":"羅波安立瑪迦的兒子亞比雅作太子，在他弟兄中為首，因為想要立他接續作王。","notes":[]},{"n":23,"t":"羅波安辦事精明，使他眾子分散在猶大和便雅憫全地各堅固城裏，又賜他們許多糧食，為他們多尋妻子。","notes":[]}]},"12":{"heading":"埃及侵犯猶大","verses":[{"n":1,"t":"羅波安的國堅立，他強盛的時候就離棄耶和華的律法，以色列人也都隨從他。","notes":[]},{"n":2,"t":"羅波安王第五年，埃及王示撒上來攻打耶路撒冷，因為王和民得罪了耶和華。","notes":[]},{"n":3,"t":"示撒帶戰車一千二百輛，馬兵六萬，並且跟從他出埃及的路比人、蘇基人，和古實人，多得不可勝數。","notes":[]},{"n":4,"t":"他攻取了猶大的堅固城，就來到耶路撒冷。","notes":[]},{"n":5,"t":"那時，猶大的首領因為示撒就聚集在耶路撒冷。有先知示瑪雅去見羅波安和眾首領，對他們說：「耶和華如此說：『你們離棄了我，所以我使你們落在示撒手裏。』」","notes":[]},{"n":6,"t":"於是王和以色列的眾首領都自卑說：「耶和華是公義的。」","notes":[]},{"n":7,"t":"耶和華見他們自卑，耶和華的話就臨到示瑪雅說：「他們既自卑，我必不滅絕他們；必使他們略得拯救，我不藉著示撒的手將我的怒氣倒在耶路撒冷。","notes":[]},{"n":8,"t":"然而他們必作示撒的僕人，好叫他們知道，服事我與服事外邦人有何分別。」","notes":[]},{"n":9,"t":"於是，埃及王示撒上來攻取耶路撒冷，奪了耶和華殿和王宮裏的寶物，盡都帶走，又奪去所羅門製造的金盾牌。","notes":[]},{"n":10,"t":"羅波安王製造銅盾牌代替那金盾牌，交給守王宮門的護衛長看守。","notes":[]},{"n":11,"t":"王每逢進耶和華的殿，護衛兵就拿這盾牌，隨後仍將盾牌送回，放在護衛房。","notes":[]},{"n":12,"t":"王自卑的時候，耶和華的怒氣就轉消了，不將他滅盡，並且在猶大中間也有善益的事。","notes":[]},{"n":13,"t":"羅波安王自強，在耶路撒冷作王。他登基的時候年四十一歲，在耶路撒冷，就是耶和華從以色列眾支派中所選擇立他名的城，作王十七年。羅波安的母親名叫拿瑪，是亞捫人。","notes":[],"heads":["羅波安政績簡述"]},{"n":14,"t":"羅波安行惡，因他不立定心意尋求耶和華。","notes":[]},{"n":15,"t":"羅波安所行的事，自始至終不都寫在先知示瑪雅和先見易多的史記上嗎？羅波安與耶羅波安時常爭戰。","notes":[]},{"n":16,"t":"羅波安與他列祖同睡，葬在大衛城裏。他兒子亞比雅接續他作王。","notes":[]}]},"13":{"heading":"亞比雅與耶羅波安爭戰","verses":[{"n":1,"t":"耶羅波安王十八年，亞比雅登基作猶大王，","notes":[]},{"n":2,"t":"在耶路撒冷作王三年。他母親名叫米該亞，是基比亞人烏列的女兒。亞比雅常與耶羅波安爭戰。","notes":["又作瑪迦"]},{"n":3,"t":"有一次亞比雅率領挑選的兵四十萬擺陣，都是勇敢的戰士；耶羅波安也挑選大能的勇士八十萬，對亞比雅擺陣。","notes":[]},{"n":4,"t":"亞比雅站在以法蓮山地中的洗瑪臉山上，說：「耶羅波安和以色列眾人哪，要聽我說！","notes":[]},{"n":5,"t":"耶和華－以色列的神曾立鹽約，將以色列國永遠賜給大衛和他的子孫，你們不知道嗎？","notes":["鹽就是不廢壞的意思"]},{"n":6,"t":"無奈大衛兒子所羅門的臣僕、尼八兒子耶羅波安起來背叛他的主人。","notes":[]},{"n":7,"t":"有些無賴的匪徒聚集跟從他，逞強攻擊所羅門的兒子羅波安；那時羅波安還幼弱，不能抵擋他們。","notes":[]},{"n":8,"t":"「現在你們有意抗拒大衛子孫手下所治耶和華的國，你們的人也甚多，你們那裏又有耶羅波安為你們所造當作神的金牛犢。","notes":[]},{"n":9,"t":"你們不是驅逐耶和華的祭司亞倫的後裔和利未人嗎？不是照著外邦人的惡俗為自己立祭司嗎？無論何人牽一隻公牛犢、七隻公綿羊將自己分別出來，就可作虛無之神的祭司。","notes":[]},{"n":10,"t":"至於我們，耶和華是我們的神，我們並沒有離棄他。我們有事奉耶和華的祭司，都是亞倫的後裔，並有利未人各盡其職，","notes":[]},{"n":11,"t":"每日早晚向耶和華獻燔祭，燒美香，又在精金的桌子上擺陳設餅；又有金燈臺和燈盞，每晚點起，因為我們遵守耶和華－我們神的命；惟有你們離棄了他。","notes":[]},{"n":12,"t":"率領我們的是神，我們這裏也有神的祭司拿號向你們吹出大聲。以色列人哪，不要與耶和華－你們列祖的神爭戰，因你們必不能亨通。」","notes":[]},{"n":13,"t":"耶羅波安卻在猶大人的後頭設伏兵。這樣，以色列人在猶大人的前頭，伏兵在猶大人的後頭。","notes":[]},{"n":14,"t":"猶大人回頭觀看，見前後都有敵兵，就呼求耶和華，祭司也吹號。","notes":[]},{"n":15,"t":"於是猶大人吶喊；猶大人吶喊的時候，神就使耶羅波安和以色列眾人敗在亞比雅與猶大人面前。","notes":[]},{"n":16,"t":"以色列人在猶大人面前逃跑，神將他們交在猶大人手裏。","notes":[]},{"n":17,"t":"亞比雅和他的軍兵大大殺戮以色列人，以色列人仆倒死亡的精兵有五十萬。","notes":[]},{"n":18,"t":"那時，以色列人被制伏了，猶大人得勝，是因倚靠耶和華－他們列祖的神。","notes":[]},{"n":19,"t":"亞比雅追趕耶羅波安，攻取了他的幾座城，就是伯特利和屬伯特利的鎮市，耶沙拿和屬耶沙拿的鎮市，以法拉音和屬以法拉音的鎮市。","notes":["或譯：以弗倫"]},{"n":20,"t":"亞比雅在世的時候，耶羅波安不能再強盛；耶和華攻擊他，他就死了。","notes":[]},{"n":21,"t":"亞比雅卻漸漸強盛，娶妻妾十四個，生了二十二個兒子，十六個女兒。","notes":[]},{"n":22,"t":"亞比雅其餘的事和他的言行都寫在先知易多的傳上。","notes":[]}]},"14":{"heading":"亞撒王擊敗古實人","verses":[{"n":1,"t":"亞比雅與他列祖同睡，葬在大衛城裏。他兒子亞撒接續他作王。亞撒年間，國中太平十年。","notes":[]},{"n":2,"t":"亞撒行耶和華－他神眼中看為善為正的事，","notes":[]},{"n":3,"t":"除掉外邦神的壇和邱壇，打碎柱像，砍下木偶，","notes":[]},{"n":4,"t":"吩咐猶大人尋求耶和華－他們列祖的神，遵行他的律法、誡命；","notes":[]},{"n":5,"t":"又在猶大各城邑除掉邱壇和日像，那時國享太平；","notes":[]},{"n":6,"t":"又在猶大建造了幾座堅固城。國中太平數年，沒有戰爭，因為耶和華賜他平安。","notes":[]},{"n":7,"t":"他對猶大人說：「我們要建造這些城邑，四圍築牆，蓋樓，安門，做閂；地還屬我們，是因尋求耶和華－我們的神；我們既尋求他，他就賜我們四境平安。」於是建造城邑，諸事亨通。","notes":[]},{"n":8,"t":"亞撒的軍兵，出自猶大拿盾牌拿槍的三十萬人；出自便雅憫拿盾牌拉弓的二十八萬人。這都是大能的勇士。","notes":[]},{"n":9,"t":"有古實王謝拉率領軍兵一百萬，戰車三百輛，出來攻擊猶大人，到了瑪利沙。","notes":[]},{"n":10,"t":"於是亞撒出去與他迎敵，就在瑪利沙的洗法谷彼此擺陣。","notes":[]},{"n":11,"t":"亞撒呼求耶和華－他的神說：「耶和華啊，惟有你能幫助軟弱的，勝過強盛的。耶和華－我們的神啊，求你幫助我們；因為我們仰賴你，奉你的名來攻擊這大軍。耶和華啊，你是我們的神，不要容人勝過你。」","notes":[]},{"n":12,"t":"於是耶和華使古實人敗在亞撒和猶大人面前，古實人就逃跑了；","notes":[]},{"n":13,"t":"亞撒和跟隨他的軍兵追趕他們，直到基拉耳。古實人被殺的甚多，不能再強盛，因為敗在耶和華與他軍兵面前。猶大人就奪了許多財物，","notes":[]},{"n":14,"t":"又打破基拉耳四圍的城邑；耶和華使其中的人都甚恐懼。猶大人又將所有的城擄掠一空，因其中的財物甚多，","notes":[]},{"n":15,"t":"又毀壞了群畜的圈，奪取許多的羊和駱駝，就回耶路撒冷去了。","notes":[]}]},"15":{"heading":"亞撒的改革","verses":[{"n":1,"t":"神的靈感動俄德的兒子亞撒利雅。","notes":[]},{"n":2,"t":"他出來迎接亞撒，對他說：「亞撒和猶大、便雅憫眾人哪，要聽我說：你們若順從耶和華，耶和華必與你們同在；你們若尋求他，就必尋見；你們若離棄他，他必離棄你們。","notes":[]},{"n":3,"t":"以色列人不信真神，沒有訓誨的祭司，也沒有律法，已經好久了；","notes":[]},{"n":4,"t":"但他們在急難的時候歸向耶和華－以色列的神，尋求他，他就被他們尋見。","notes":[]},{"n":5,"t":"那時，出入的人不得平安，列國的居民都遭大亂；","notes":[]},{"n":6,"t":"這國攻擊那國，這城攻擊那城，互相破壞，因為神用各樣災難擾亂他們。","notes":[]},{"n":7,"t":"現在你們要剛強，不要手軟，因你們所行的必得賞賜。」","notes":[]},{"n":8,"t":"亞撒聽見這話和俄德兒子先知亞撒利雅的預言，就壯起膽來，在猶大、便雅憫全地，並以法蓮山地所奪的各城，將可憎之物盡都除掉，又在耶和華殿的廊前重新修築耶和華的壇；","notes":[]},{"n":9,"t":"又招聚猶大、便雅憫的眾人，並他們中間寄居的以法蓮人、瑪拿西人、西緬人。有許多以色列人歸降亞撒，因見耶和華－他的神與他同在。","notes":[]},{"n":10,"t":"亞撒十五年三月，他們都聚集在耶路撒冷。","notes":[]},{"n":11,"t":"當日他們從所取的擄物中，將牛七百隻、羊七千隻獻給耶和華。","notes":[]},{"n":12,"t":"他們就立約，要盡心盡性地尋求耶和華－他們列祖的神。","notes":[]},{"n":13,"t":"凡不尋求耶和華－以色列神的，無論大小、男女，必被治死。","notes":[]},{"n":14,"t":"他們就大聲歡呼，吹號吹角，向耶和華起誓。","notes":[]},{"n":15,"t":"猶大眾人為所起的誓歡喜；因他們是盡心起誓，盡意尋求耶和華，耶和華就被他們尋見，且賜他們四境平安。","notes":[]},{"n":16,"t":"亞撒王貶了他祖母瑪迦太后的位，因她造了可憎的偶像亞舍拉。亞撒砍下她的偶像，搗得粉碎，燒在汲淪溪邊。","notes":[]},{"n":17,"t":"只是邱壇還沒有從以色列中廢去，然而亞撒的心一生誠實。","notes":[]},{"n":18,"t":"亞撒將他父所分別為聖、與自己所分別為聖的金銀和器皿都奉到神的殿裏。","notes":[]},{"n":19,"t":"從這時直到亞撒三十五年，都沒有爭戰的事。","notes":[]}]},"16":{"heading":"猶大與以色列爭戰","verses":[{"n":1,"t":"亞撒三十六年，以色列王巴沙上來攻擊猶大，修築拉瑪，不許人從猶大王亞撒那裏出入。","notes":[]},{"n":2,"t":"於是亞撒從耶和華殿和王宮的府庫裏拿出金銀來，送與住大馬士革的亞蘭王便‧哈達，說：","notes":[]},{"n":3,"t":"「你父曾與我父立約，我與你也要立約。現在我將金銀送給你，求你廢掉你與以色列王巴沙所立的約，使他離開我。」","notes":[]},{"n":4,"t":"便‧哈達聽從亞撒王的話，派軍長去攻擊以色列的城邑。他們就攻破以雲、但、亞伯‧瑪音，和拿弗他利一切的積貨城。","notes":[]},{"n":5,"t":"巴沙聽見就停工，不修築拉瑪了。","notes":[]},{"n":6,"t":"於是亞撒王率領猶大眾人，將巴沙修築拉瑪所用的石頭、木頭都運去，用以修築迦巴和米斯巴。","notes":[]},{"n":7,"t":"那時，先見哈拿尼來見猶大王亞撒，對他說：「因你仰賴亞蘭王，沒有仰賴耶和華－你的神，所以亞蘭王的軍兵脫離了你的手。","notes":[],"heads":["先知哈拿尼"]},{"n":8,"t":"古實人、路比人的軍隊不是甚大嗎？戰車馬兵不是極多嗎？只因你仰賴耶和華，他便將他們交在你手裏。","notes":[]},{"n":9,"t":"耶和華的眼目遍察全地，要顯大能幫助向他心存誠實的人。你這事行得愚昧；此後，你必有爭戰的事。」","notes":[]},{"n":10,"t":"亞撒因此惱恨先見，將他囚在監裏。那時亞撒也虐待一些人民。","notes":[]},{"n":11,"t":"亞撒所行的事，自始至終都寫在猶大和以色列諸王記上。","notes":[],"heads":["亞撒逝世"]},{"n":12,"t":"亞撒作王三十九年，他腳上有病，而且甚重。病的時候沒有求耶和華，只求醫生。","notes":[]},{"n":13,"t":"他作王四十一年而死，與他列祖同睡，","notes":[]},{"n":14,"t":"葬在大衛城自己所鑿的墳墓裏，放在床上，其床堆滿各樣馨香的香料，就是按做香的作法調和的香料，又為他燒了許多的物件。","notes":[]}]},"17":{"heading":"猶大王約沙法","verses":[{"n":1,"t":"亞撒的兒子約沙法接續他作王，奮勇自強，防備以色列人，","notes":[]},{"n":2,"t":"安置軍兵在猶大一切堅固城裏，又安置防兵在猶大地和他父亞撒所得以法蓮的城邑中。","notes":[]},{"n":3,"t":"耶和華與約沙法同在；因為他行他祖大衛初行的道，不尋求巴力，","notes":[]},{"n":4,"t":"只尋求他父親的神，遵行他的誡命，不效法以色列人的行為。","notes":[]},{"n":5,"t":"所以耶和華堅定他的國，猶大眾人給他進貢；約沙法大有尊榮資財。","notes":[]},{"n":6,"t":"他高興遵行耶和華的道，並且從猶大除掉一切邱壇和木偶。","notes":[]},{"n":7,"t":"他作王第三年，就差遣臣子便‧亥伊勒、俄巴底、撒迦利雅、拿坦業、米該亞往猶大各城去教訓百姓。","notes":[]},{"n":8,"t":"同著他們有利未人示瑪雅、尼探雅、西巴第雅、亞撒黑、示米拉末、約拿單、亞多尼雅、多比雅、駝‧巴多尼雅，又有祭司以利沙瑪、約蘭同著他們。","notes":[]},{"n":9,"t":"他們帶著耶和華的律法書，走遍猶大各城教訓百姓。","notes":[]},{"n":10,"t":"耶和華使猶大四圍的列國都甚恐懼，不敢與約沙法爭戰。","notes":[],"heads":["約沙法的功績"]},{"n":11,"t":"有些非利士人與約沙法送禮物，納貢銀。阿拉伯人也送他公綿羊七千七百隻，公山羊七千七百隻。","notes":[]},{"n":12,"t":"約沙法日漸強大，在猶大建造營寨和積貨城。","notes":[]},{"n":13,"t":"他在猶大城邑中有許多工程，又在耶路撒冷有戰士，就是大能的勇士。","notes":[]},{"n":14,"t":"他們的數目，按著宗族，記在下面：猶大族的千夫長押拿為首率領大能的勇士－三十萬；","notes":[]},{"n":15,"t":"其次是，千夫長約哈難率領大能的勇士－二十八萬；","notes":[]},{"n":16,"t":"其次是，細基利的兒子亞瑪斯雅（他為耶和華犧牲自己）率領大能的勇士－二十萬。","notes":[]},{"n":17,"t":"便雅憫族，是大能的勇士以利雅大率領拿弓箭和盾牌的－二十萬；","notes":[]},{"n":18,"t":"其次是，約薩拔率領預備打仗的－十八萬。","notes":[]},{"n":19,"t":"這都是伺候王的，還有王在猶大全地堅固城所安置的不在其內。","notes":[]}]},"18":{"heading":"先知米該雅警告亞哈王","verses":[{"n":1,"t":"約沙法大有尊榮資財，就與亞哈結親。","notes":[]},{"n":2,"t":"過了幾年，他下到撒馬利亞去見亞哈；亞哈為他和跟從他的人宰了許多牛羊，勸他與自己同去攻取基列的拉末。","notes":[]},{"n":3,"t":"以色列王亞哈問猶大王約沙法說：「你肯同我去攻取基列的拉末嗎？」他回答說：「你我不分彼此，我的民與你的民一樣，必與你同去爭戰。」","notes":[]},{"n":4,"t":"約沙法對以色列王說：「請你先求問耶和華。」","notes":[]},{"n":5,"t":"於是以色列王招聚先知四百人，問他們說：「我們上去攻取基列的拉末可以不可以？」他們說：「可以上去，因為神必將那城交在王的手裏。」","notes":[]},{"n":6,"t":"約沙法說：「這裏不是還有耶和華的先知，我們可以求問他嗎？」","notes":[]},{"n":7,"t":"以色列王對約沙法說：「還有一個人，是音拉的兒子米該雅。我們可以託他求問耶和華，只是我恨他；因為他指著我所說的預言，不說吉語，常說凶言。」約沙法說：「王不必這樣說。」","notes":[]},{"n":8,"t":"以色列王就召了一個太監來，說：「你快去將音拉的兒子米該雅召來。」","notes":[]},{"n":9,"t":"以色列王和猶大王約沙法在撒馬利亞城門前的空場上，各穿朝服坐在位上，所有的先知都在他們面前說預言。","notes":[]},{"n":10,"t":"基拿拿的兒子西底家造了兩個鐵角，說：「耶和華如此說：『你要用這角牴觸亞蘭人，直到將他們滅盡。』」","notes":[]},{"n":11,"t":"所有的先知也都這樣預言說：「可以上基列的拉末去，必然得勝，因為耶和華必將那城交在王的手中。」","notes":[]},{"n":12,"t":"那去召米該雅的使者對米該雅說：「眾先知一口同音地都向王說吉言，你不如與他們說一樣的話，也說吉言。」","notes":[]},{"n":13,"t":"米該雅說：「我指著永生的耶和華起誓，我的神說甚麼，我就說甚麼。」","notes":[]},{"n":14,"t":"米該雅到王面前，王問他說：「米該雅啊，我們上去攻取基列的拉末可以不可以？」他說：「可以上去，必然得勝，敵人必交在你們手裏。」","notes":[]},{"n":15,"t":"王對他說：「我當囑咐你幾次，你才奉耶和華的名向我說實話呢？」","notes":[]},{"n":16,"t":"米該雅說：「我看見以色列眾民散在山上，如同沒有牧人的羊群一般。耶和華說：『這民沒有主人，他們可以平平安安地各歸各家去。』」","notes":[]},{"n":17,"t":"以色列王對約沙法說：「我豈沒有告訴你，這人指著我所說的預言，不說吉語，單說凶言嗎？」","notes":[]},{"n":18,"t":"米該雅說：「你們要聽耶和華的話。我看見耶和華坐在寶座上，天上的萬軍侍立在他左右。","notes":[]},{"n":19,"t":"耶和華說：『誰去引誘以色列王亞哈上基列的拉末去陣亡呢？』這個就這樣說，那個就那樣說。","notes":[]},{"n":20,"t":"隨後，有一個神靈出來，站在耶和華面前說：『我去引誘他。』耶和華問他說：『你用何法呢？』","notes":[]},{"n":21,"t":"他說：『我去，要在他眾先知口中作謊言的靈。』耶和華說：『這樣，你必能引誘他，你去如此行吧！』","notes":[]},{"n":22,"t":"現在耶和華使謊言的靈入了你這些先知的口，並且耶和華已經命定降禍與你。」","notes":[]},{"n":23,"t":"基拿拿的兒子西底家前來打米該雅的臉，說：「耶和華的靈從哪裏離開我與你說話呢？」","notes":[]},{"n":24,"t":"米該雅說：「你進嚴密的屋子藏躲的那日，就必看見了。」","notes":[]},{"n":25,"t":"以色列王說：「將米該雅帶回，交給邑宰亞們和王的兒子約阿施，說：","notes":[]},{"n":26,"t":"『王如此說：把這個人下在監裏，使他受苦，吃不飽喝不足，等候我平平安安地回來。』」","notes":[]},{"n":27,"t":"米該雅說：「你若能平安回來，那就是耶和華沒有藉我說這話了」；又說：「眾民哪，你們都要聽！」","notes":[]},{"n":28,"t":"以色列王和猶大王約沙法上基列的拉末去了。","notes":[],"heads":["亞哈陣亡"]},{"n":29,"t":"以色列王對約沙法說：「我要改裝上陣，你可以仍穿王服。」於是以色列王改裝，他們就上陣去了。","notes":[]},{"n":30,"t":"先是亞蘭王吩咐車兵長說：「他們的兵將，無論大小，你們都不可與他們爭戰，只要與以色列王爭戰。」","notes":[]},{"n":31,"t":"車兵長看見約沙法便說，這必是以色列王，就轉過去與他爭戰。約沙法一呼喊，耶和華就幫助他，神又感動他們離開他。","notes":[]},{"n":32,"t":"車兵長見不是以色列王，就轉去不追他了。","notes":[]},{"n":33,"t":"有一人隨便開弓，恰巧射入以色列王的甲縫裏。王對趕車的說：「我受了重傷，你轉過車來，拉我出陣吧！」","notes":[]},{"n":34,"t":"那日陣勢越戰越猛，以色列王勉強站在車上抵擋亞蘭人，直到晚上。約在日落的時候，王就死了。","notes":[]}]},"19":{"heading":"先知斥責約沙法","verses":[{"n":1,"t":"猶大王約沙法平平安安地回耶路撒冷，到宮裏去了。","notes":[]},{"n":2,"t":"先見哈拿尼的兒子耶戶出來迎接約沙法王，對他說：「你豈當幫助惡人，愛那恨惡耶和華的人呢？因此耶和華的忿怒臨到你。","notes":[]},{"n":3,"t":"然而你還有善行，因你從國中除掉木偶，立定心意尋求神。」","notes":[]},{"n":4,"t":"約沙法住在耶路撒冷，以後又出巡民間，從別是巴直到以法蓮山地，引導民歸向耶和華－他們列祖的神；","notes":[],"heads":["約沙法的改革"]},{"n":5,"t":"又在猶大國中遍地的堅固城裏設立審判官，","notes":[]},{"n":6,"t":"對他們說：「你們辦事應當謹慎；因為你們判斷不是為人，乃是為耶和華。判斷的時候，他必與你們同在。","notes":[]},{"n":7,"t":"現在你們應當敬畏耶和華，謹慎辦事；因為耶和華－我們的神沒有不義，不偏待人，也不受賄賂。」","notes":[]},{"n":8,"t":"約沙法從利未人和祭司，並以色列族長中派定人，在耶路撒冷為耶和華判斷，聽民間的爭訟，就回耶路撒冷去了。","notes":[]},{"n":9,"t":"約沙法囑咐他們說：「你們當敬畏耶和華，忠心誠實辦事。","notes":[]},{"n":10,"t":"住在各城裏你們的弟兄，若有爭訟的事來到你們這裏，或為流血，或犯律法、誡命、律例、典章，你們要警戒他們，免得他們得罪耶和華，以致他的忿怒臨到你們和你們的弟兄；這樣行，你們就沒有罪了。","notes":[]},{"n":11,"t":"凡屬耶和華的事，有大祭司亞瑪利雅管理你們；凡屬王的事，有猶大支派的族長以實瑪利的兒子西巴第雅管理你們；在你們面前有利未人作官長。你們應當壯膽辦事，願耶和華與善人同在。」","notes":[]}]},"20":{"heading":"與以東交戰","verses":[{"n":1,"t":"此後，摩押人和亞捫人，又有米烏尼人，一同來攻擊約沙法。","notes":[]},{"n":2,"t":"有人來報告約沙法說：「從海外亞蘭那邊有大軍來攻擊你，如今他們在哈洗遜‧他瑪，就是隱‧基底。」","notes":["又作以東"]},{"n":3,"t":"約沙法便懼怕，定意尋求耶和華，在猶大全地宣告禁食。","notes":[]},{"n":4,"t":"於是猶大人聚會，求耶和華幫助。猶大各城都有人出來尋求耶和華。","notes":[]},{"n":5,"t":"約沙法就在猶大和耶路撒冷的會中，站在耶和華殿的新院前，","notes":[]},{"n":6,"t":"說：「耶和華－我們列祖的神啊，你不是天上的神嗎？你不是萬邦萬國的主宰嗎？在你手中有大能大力，無人能抵擋你。","notes":[]},{"n":7,"t":"我們的神啊，你不是曾在你民以色列人面前驅逐這地的居民，將這地賜給你朋友亞伯拉罕的後裔永遠為業嗎？","notes":[]},{"n":8,"t":"他們住在這地，又為你的名建造聖所，說：","notes":[]},{"n":9,"t":"『倘有禍患臨到我們，或刀兵災殃，或瘟疫饑荒，我們在急難的時候，站在這殿前向你呼求，你必垂聽而拯救，因為你的名在這殿裏。』","notes":[]},{"n":10,"t":"從前以色列人出埃及地的時候，你不容以色列人侵犯亞捫人、摩押人，和西珥山人，以色列人就離開他們，不滅絕他們。","notes":[]},{"n":11,"t":"看哪，他們怎樣報復我們，要來驅逐我們出離你的地，就是你賜給我們為業之地。","notes":[]},{"n":12,"t":"我們的神啊，你不懲罰他們嗎？因為我們無力抵擋這來攻擊我們的大軍，我們也不知道怎樣行，我們的眼目單仰望你。」","notes":[]},{"n":13,"t":"猶大眾人和他們的嬰孩、妻子、兒女都站在耶和華面前。","notes":[]},{"n":14,"t":"那時，耶和華的靈在會中臨到利未人亞薩的後裔－瑪探雅的玄孫，耶利的曾孫，比拿雅的孫子，撒迦利雅的兒子雅哈悉。","notes":[]},{"n":15,"t":"他說：「猶大眾人、耶路撒冷的居民，和約沙法王，你們請聽。耶和華對你們如此說：『不要因這大軍恐懼驚惶；因為勝敗不在乎你們，乃在乎神。","notes":[]},{"n":16,"t":"明日你們要下去迎敵，他們是從洗斯坡上來，你們必在耶魯伊勒曠野前的谷口遇見他們。","notes":[]},{"n":17,"t":"猶大和耶路撒冷人哪，這次你們不要爭戰，要擺陣站著，看耶和華為你們施行拯救。不要恐懼，也不要驚惶。明日當出去迎敵，因為耶和華與你們同在。』」","notes":[]},{"n":18,"t":"約沙法就面伏於地，猶大眾人和耶路撒冷的居民也俯伏在耶和華面前，叩拜耶和華。","notes":[]},{"n":19,"t":"哥轄族和可拉族的利未人都起來，用極大的聲音讚美耶和華以色列的神。","notes":[]},{"n":20,"t":"次日清早，眾人起來往提哥亞的曠野去。出去的時候，約沙法站著說：「猶大人和耶路撒冷的居民哪，要聽我說：信耶和華－你們的神就必立穩；信他的先知就必亨通。」","notes":[]},{"n":21,"t":"約沙法既與民商議了，就設立歌唱的人，頌讚耶和華，使他們穿上聖潔的禮服，走在軍前讚美耶和華說：「當稱謝耶和華，因他的慈愛永遠長存！」","notes":[]},{"n":22,"t":"眾人方唱歌讚美的時候，耶和華就派伏兵擊殺那來攻擊猶大人的亞捫人、摩押人，和西珥山人，他們就被打敗了。","notes":[]},{"n":23,"t":"因為亞捫人和摩押人起來，擊殺住西珥山的人，將他們滅盡；滅盡住西珥山的人之後，他們又彼此自相擊殺。","notes":[]},{"n":24,"t":"猶大人來到曠野的望樓，向那大軍觀看，見屍橫遍地，沒有一個逃脫的。","notes":[]},{"n":25,"t":"約沙法和他的百姓就來收取敵人的財物，在屍首中見了許多財物、珍寶，他們剝脫下來的多得不可攜帶；因為甚多，直收取了三日。","notes":[]},{"n":26,"t":"第四日眾人聚集在比拉迦谷，在那裏稱頌耶和華。因此那地方名叫比拉迦谷，直到今日。","notes":["就是稱頌的意思"]},{"n":27,"t":"猶大人和耶路撒冷人都歡歡喜喜地回耶路撒冷，約沙法率領他們；因為耶和華使他們戰勝仇敵，就歡喜快樂。","notes":[]},{"n":28,"t":"他們彈琴、鼓瑟、吹號來到耶路撒冷，進了耶和華的殿。","notes":[]},{"n":29,"t":"列邦諸國聽見耶和華戰敗以色列的仇敵，就甚懼怕。","notes":[]},{"n":30,"t":"這樣，約沙法的國得享太平，因為神賜他四境平安。","notes":[]},{"n":31,"t":"約沙法作猶大王，登基的時候年三十五歲，在耶路撒冷作王二十五年。他母親名叫阿蘇巴，乃示利希的女兒。","notes":[],"heads":["約沙法逝世"]},{"n":32,"t":"約沙法效法他父亞撒所行的，不偏左右，行耶和華眼中看為正的事。","notes":[]},{"n":33,"t":"只是邱壇還沒有廢去，百姓也沒有立定心意歸向他們列祖的神。","notes":[]},{"n":34,"t":"約沙法其餘的事，自始至終都寫在哈拿尼的兒子耶戶的書上，也載入以色列諸王記上。","notes":[]},{"n":35,"t":"此後，猶大王約沙法與以色列王亞哈謝交好；亞哈謝行惡太甚。","notes":[]},{"n":36,"t":"二王合夥造船要往他施去，遂在以旬‧迦別造船。","notes":[]},{"n":37,"t":"那時瑪利沙人、多大瓦的兒子以利以謝向約沙法預言說：「因你與亞哈謝交好，耶和華必破壞你所造的。」後來那船果然破壞，不能往他施去了。","notes":[]}]},"21":{"heading":"猶大王約蘭","verses":[{"n":1,"t":"約沙法與他列祖同睡，葬在大衛城他列祖的墳地裏。他兒子約蘭接續他作王。","notes":[]},{"n":2,"t":"約蘭有幾個兄弟，就是約沙法的兒子亞撒利雅、耶歇、撒迦利雅、亞撒利雅、米迦勒、示法提雅。這都是猶大王約沙法的兒子。","notes":[]},{"n":3,"t":"他們的父親將許多金銀、財寶，和猶大地的堅固城賜給他們；但將國賜給約蘭，因為他是長子。","notes":[]},{"n":4,"t":"約蘭興起坐他父的位，奮勇自強，就用刀殺了他的眾兄弟和以色列的幾個首領。","notes":[]},{"n":5,"t":"約蘭登基的時候年三十二歲，在耶路撒冷作王八年。","notes":[]},{"n":6,"t":"他行以色列諸王的道，與亞哈家一樣；因他娶了亞哈的女兒為妻，行耶和華眼中看為惡的事。","notes":[]},{"n":7,"t":"耶和華卻因自己與大衛所立的約，不肯滅大衛的家，照他所應許的，永遠賜燈光與大衛和他的子孫。","notes":[]},{"n":8,"t":"約蘭年間，以東人背叛猶大，脫離他的權下，自己立王。","notes":[]},{"n":9,"t":"約蘭就率領軍長和所有的戰車，夜間起來，攻擊圍困他的以東人和車兵長。","notes":[]},{"n":10,"t":"這樣，以東人背叛猶大，脫離他的權下，直到今日。那時，立拿人也背叛了，因為約蘭離棄耶和華－他列祖的神。","notes":[]},{"n":11,"t":"他又在猶大諸山建築邱壇，使耶路撒冷的居民行邪淫，誘惑猶大人。","notes":[]},{"n":12,"t":"先知以利亞達信與約蘭說：「耶和華－你祖大衛的神如此說：『因為你不行你父約沙法和猶大王亞撒的道，","notes":[]},{"n":13,"t":"乃行以色列諸王的道，使猶大人和耶路撒冷的居民行邪淫，像亞哈家一樣，又殺了你父家比你好的諸兄弟。","notes":[]},{"n":14,"t":"故此，耶和華降大災與你的百姓和你的妻子、兒女，並你一切所有的。","notes":[]},{"n":15,"t":"你的腸子必患病，日加沉重，以致你的腸子墜落下來。』」","notes":[]},{"n":16,"t":"以後，耶和華激動非利士人和靠近古實的阿拉伯人來攻擊約蘭。","notes":[]},{"n":17,"t":"他們上來攻擊猶大，侵入境內，擄掠了王宮裏所有的財貨和他的妻子、兒女，除了他小兒子約哈斯之外，沒有留下一個兒子。","notes":["又名亞哈謝"]},{"n":18,"t":"這些事以後，耶和華使約蘭的腸子患不能醫治的病。","notes":[]},{"n":19,"t":"他患此病纏綿日久，過了二年，腸子墜落下來，病重而死。他的民沒有為他燒甚麼物件，像從前為他列祖所燒的一樣。","notes":[]},{"n":20,"t":"約蘭登基的時候年三十二歲，在耶路撒冷作王八年。他去世無人思慕，眾人葬他在大衛城，只是不在列王的墳墓裏。","notes":[]}]},"22":{"heading":"猶大王亞哈謝","verses":[{"n":1,"t":"耶路撒冷的居民立約蘭的小兒子亞哈謝接續他作王；因為跟隨阿拉伯人來攻營的軍兵曾殺了亞哈謝的眾兄長。這樣，猶大王約蘭的兒子亞哈謝作了王。","notes":[]},{"n":2,"t":"亞哈謝登基的時候年四十二歲，在耶路撒冷作王一年。他母親名叫亞她利雅，是暗利的孫女。","notes":["列王下八章二十六節是二十二歲"]},{"n":3,"t":"亞哈謝也行亞哈家的道；因為他母親給他主謀，使他行惡。","notes":[]},{"n":4,"t":"他行耶和華眼中看為惡的事，像亞哈家一樣；因他父親死後有亞哈家的人給他主謀，以致敗壞。","notes":[]},{"n":5,"t":"他聽從亞哈家的計謀，同以色列王亞哈的兒子約蘭往基列的拉末去，與亞蘭王哈薛爭戰；亞蘭人打傷了約蘭。","notes":[]},{"n":6,"t":"約蘭回到耶斯列，醫治在拉末與亞蘭王哈薛打仗所受的傷，猶大王約蘭的兒子亞撒利雅因為亞哈的兒子約蘭病了，就下到耶斯列看望他。","notes":["就是亞哈謝"]},{"n":7,"t":"亞哈謝去見約蘭就被害了，這是出乎神；因為他到了，就同約蘭出去攻擊寧示的孫子耶戶。這耶戶是耶和華所膏、使他剪除亞哈家的。","notes":[]},{"n":8,"t":"耶戶討亞哈家罪的時候，遇見猶大的眾首領和亞哈謝的眾姪子服事亞哈謝，就把他們都殺了。","notes":[]},{"n":9,"t":"亞哈謝藏在撒馬利亞，耶戶尋找他，眾人將他拿住，送到耶戶那裏，就殺了他，將他葬埋；因他們說，他是那盡心尋求耶和華之約沙法的兒子。這樣，亞哈謝的家無力保守國權。","notes":[]},{"n":10,"t":"亞哈謝的母親亞她利雅見她兒子死了，就起來剿滅猶大王室。","notes":[],"heads":["亞她利雅篡位"]},{"n":11,"t":"但王的女兒約示巴將亞哈謝的兒子約阿施從那被殺的王子中偷出來，把他和他的乳母都藏在臥房裏。約示巴是約蘭王的女兒，亞哈謝的妹子，祭司耶何耶大的妻。她收藏約阿施，躲避亞她利雅，免得被殺。","notes":[]},{"n":12,"t":"約阿施和她們一同藏在神殿裏六年；亞她利雅篡了國位。","notes":[]}]},"23":{"heading":"推翻亞她利雅","verses":[{"n":1,"t":"第七年，耶何耶大奮勇自強，將百夫長耶羅罕的兒子亞撒利雅，約哈難的兒子以實瑪利，俄備得的兒子亞撒利雅，亞大雅的兒子瑪西雅，細基利的兒子以利沙法召來，與他們立約。","notes":[]},{"n":2,"t":"他們走遍猶大，從猶大各城裏招聚利未人和以色列的眾族長到耶路撒冷來。","notes":[]},{"n":3,"t":"會眾在神殿裏與王立約。耶何耶大對他們說：「看哪，王的兒子必當作王，正如耶和華指著大衛子孫所應許的話」；","notes":[]},{"n":4,"t":"又說：「你們當這樣行：祭司和利未人凡安息日進班的，三分之一要把守各門，","notes":[]},{"n":5,"t":"三分之一要在王宮，三分之一要在基址門；眾百姓要在耶和華殿的院內。","notes":[]},{"n":6,"t":"除了祭司和供職的利未人之外，不准別人進耶和華的殿；惟獨他們可以進去，因為他們聖潔。眾百姓要遵守耶和華所吩咐的。","notes":[]},{"n":7,"t":"利未人要手中各拿兵器，四圍護衛王；凡擅入殿宇的，必當治死。王出入的時候，你們當跟隨他。」","notes":[]},{"n":8,"t":"利未人和猶大眾人都照著祭司耶何耶大一切所吩咐的去行，各帶所管安息日進班出班的人來，因為祭司耶何耶大不許他們下班。","notes":[]},{"n":9,"t":"祭司耶何耶大便將神殿裏所藏大衛王的槍、盾牌、擋牌交給百夫長，","notes":[]},{"n":10,"t":"又分派眾民手中各拿兵器，在壇和殿那裏，從殿右直到殿左，站在王子的四圍；","notes":[]},{"n":11,"t":"於是領王子出來，給他戴上冠冕，將律法書交給他，立他作王。耶何耶大和眾子膏他，眾人說：「願王萬歲！」","notes":[]},{"n":12,"t":"亞她利雅聽見民奔走讚美王的聲音，就到民那裏，進耶和華的殿，","notes":[]},{"n":13,"t":"看見王站在殿門的柱旁，百夫長和吹號的人侍立在王左右，國民都歡樂吹號，又有歌唱的，用各樣的樂器領人歌唱讚美；亞她利雅就撕裂衣服，喊叫說：「反了！反了！」","notes":[]},{"n":14,"t":"祭司耶何耶大帶管轄軍兵的百夫長出來，吩咐他們說：「將她趕到班外，凡跟隨她的必用刀殺死！」因為祭司說：「不可在耶和華殿裏殺她。」","notes":[]},{"n":15,"t":"眾兵就閃開，讓她去；她走到王宮的馬門，便在那裏把她殺了。","notes":[]},{"n":16,"t":"耶何耶大與眾民和王立約，都要作耶和華的民。","notes":[],"heads":["耶何耶大的改革"]},{"n":17,"t":"於是眾民都到巴力廟，拆毀了廟，打碎壇和像，又在壇前將巴力的祭司瑪坦殺了。","notes":[]},{"n":18,"t":"耶何耶大派官看守耶和華的殿，是在祭司利未人手下。這祭司利未人是大衛分派在耶和華殿中、照摩西律法上所寫的，給耶和華獻燔祭，又按大衛所定的例，歡樂歌唱；","notes":[]},{"n":19,"t":"且設立守門的把守耶和華殿的各門，無論為何事，不潔淨的人都不准進去。","notes":[]},{"n":20,"t":"又率領百夫長和貴冑，與民間的官長，並國中的眾民，請王從耶和華殿下來，由上門進入王宮，立王坐在國位上。","notes":[]},{"n":21,"t":"國民都歡樂，合城都安靜。眾人已將亞她利雅用刀殺了。","notes":[]}]},"24":{"heading":"猶大王約阿施","verses":[{"n":1,"t":"約阿施登基的時候年七歲，在耶路撒冷作王四十年。他母親名叫西比亞，是別是巴人。","notes":[]},{"n":2,"t":"祭司耶何耶大在世的時候，約阿施行耶和華眼中看為正的事。","notes":[]},{"n":3,"t":"耶何耶大為他娶了兩個妻，並且生兒養女。","notes":[]},{"n":4,"t":"此後，約阿施有意重修耶和華的殿，","notes":[]},{"n":5,"t":"便召聚眾祭司和利未人，吩咐他們說：「你們要往猶大各城去，使以色列眾人捐納銀子，每年可以修理你們神的殿；你們要急速辦理這事。」只是利未人不急速辦理。","notes":[]},{"n":6,"t":"王召了大祭司耶何耶大來，對他說：「從前耶和華的僕人摩西，為法櫃的帳幕與以色列會眾所定的捐項，你為何不叫利未人照這例從猶大和耶路撒冷帶來作殿的費用呢？」（","notes":[]},{"n":7,"t":"因為那惡婦亞她利雅的眾子曾拆毀神的殿，又用耶和華殿中分別為聖的物供奉巴力。）","notes":[]},{"n":8,"t":"於是王下令，眾人做了一櫃，放在耶和華殿的門外，","notes":[]},{"n":9,"t":"又通告猶大和耶路撒冷的百姓，要將神僕人摩西在曠野所吩咐以色列人的捐項給耶和華送來。","notes":[]},{"n":10,"t":"眾首領和百姓都歡歡喜喜地將銀子送來，投入櫃中，直到捐完。","notes":[]},{"n":11,"t":"利未人見銀子多了，就把櫃抬到王所派的司事面前；王的書記和大祭司的屬員來將櫃倒空，仍放在原處。日日都是這樣，積蓄的銀子甚多。","notes":[]},{"n":12,"t":"王與耶何耶大將銀子交給耶和華殿裏辦事的人，他們就雇了石匠、木匠重修耶和華的殿，又雇了鐵匠、銅匠修理耶和華的殿。","notes":[]},{"n":13,"t":"工人操作，漸漸修成，將神殿修造得與從前一樣，而且甚是堅固。","notes":[]},{"n":14,"t":"工程完了，他們就把其餘的銀子拿到王與耶何耶大面前，用以製造耶和華殿供奉所用的器皿和調羹，並金銀的器皿。耶何耶大在世的時候，眾人常在耶和華殿裏獻燔祭。","notes":[]},{"n":15,"t":"耶何耶大年紀老邁，日子滿足而死。死的時候年一百三十歲，","notes":[]},{"n":16,"t":"葬在大衛城列王的墳墓裏；因為他在以色列人中行善，又事奉神，修理神的殿。","notes":[]},{"n":17,"t":"耶何耶大死後，猶大的眾首領來朝拜王；王就聽從他們。","notes":[]},{"n":18,"t":"他們離棄耶和華－他們列祖神的殿，去事奉亞舍拉和偶像；因他們這罪，就有忿怒臨到猶大和耶路撒冷。","notes":[]},{"n":19,"t":"但神仍遣先知到他們那裏，引導他們歸向耶和華。這先知警戒他們，他們卻不肯聽。","notes":[]},{"n":20,"t":"那時，神的靈感動祭司耶何耶大的兒子撒迦利亞，他就站在上面對民說：「神如此說：你們為何干犯耶和華的誡命，以致不得亨通呢？因為你們離棄耶和華，所以他也離棄你們。」","notes":[]},{"n":21,"t":"眾民同心謀害撒迦利亞，就照王的吩咐，在耶和華殿的院內用石頭打死他。","notes":[]},{"n":22,"t":"這樣，約阿施王不想念撒迦利亞的父親耶何耶大向自己所施的恩，殺了他的兒子。撒迦利亞臨死的時候說：「願耶和華鑒察伸冤！」","notes":[]},{"n":23,"t":"滿了一年，亞蘭的軍兵上來攻擊約阿施，來到猶大和耶路撒冷，殺了民中的眾首領，將所掠的財貨送到大馬士革王那裏。","notes":[],"heads":["約阿施被殺"]},{"n":24,"t":"亞蘭的軍兵雖來了一小隊，耶和華卻將大隊的軍兵交在他們手裏，是因猶大人離棄耶和華－他們列祖的神，所以藉亞蘭人懲罰約阿施。","notes":[]},{"n":25,"t":"亞蘭人離開約阿施的時候，他患重病；臣僕背叛他，要報祭司耶何耶大兒子流血之仇，殺他在床上，葬他在大衛城，只是不葬在列王的墳墓裏。","notes":[]},{"n":26,"t":"背叛他的是亞捫婦人示米押的兒子撒拔和摩押婦人示米利的兒子約薩拔。","notes":[]},{"n":27,"t":"至於他的眾子和他所受的警戒，並他重修神殿的事，都寫在列王的傳上。他兒子亞瑪謝接續他作王。","notes":[]}]},"25":{"heading":"猶大王亞瑪謝","verses":[{"n":1,"t":"亞瑪謝登基的時候年二十五歲，在耶路撒冷作王二十九年。他母親名叫約耶但，是耶路撒冷人。","notes":[]},{"n":2,"t":"亞瑪謝行耶和華眼中看為正的事，只是心不專誠。","notes":[]},{"n":3,"t":"國一堅定，就把殺他父王的臣僕殺了，","notes":[]},{"n":4,"t":"卻沒有治死他們的兒子，是照摩西律法書上耶和華所吩咐的說：「不可因子殺父，也不可因父殺子，各人要為本身的罪而死。」","notes":[]},{"n":5,"t":"亞瑪謝招聚猶大人，按著猶大和便雅憫的宗族設立千夫長、百夫長，又數點人數，從二十歲以外，能拿槍拿盾牌出去打仗的精兵共有三十萬；","notes":[],"heads":["與以東交戰"]},{"n":6,"t":"又用銀子一百他連得，從以色列招募了十萬大能的勇士。","notes":[]},{"n":7,"t":"有一個神人來見亞瑪謝，對他說：「王啊，不要使以色列的軍兵與你同去，因為耶和華不與以色列人以法蓮的後裔同在。","notes":[]},{"n":8,"t":"你若一定要去，就奮勇爭戰吧！但神必使你敗在敵人面前；因為神能助人得勝，也能使人傾敗。」","notes":[]},{"n":9,"t":"亞瑪謝問神人說：「我給了以色列軍的那一百他連得銀子怎麼樣呢？」神人回答說：「耶和華能把更多的賜給你。」","notes":[]},{"n":10,"t":"於是亞瑪謝將那從以法蓮來的軍兵分別出來，叫他們回家去。故此，他們甚惱怒猶大人，氣忿忿地回家去了。","notes":[]},{"n":11,"t":"亞瑪謝壯起膽來，率領他的民到鹽谷，殺了西珥人一萬。","notes":[]},{"n":12,"t":"猶大人又生擒了一萬帶到山崖上，從那裏把他們扔下去，以致他們都摔碎了。","notes":[]},{"n":13,"t":"但亞瑪謝所打發回去、不許一同出征的那些軍兵攻打猶大各城，從撒馬利亞直到伯‧和崙，殺了三千人，搶了許多財物。","notes":[]},{"n":14,"t":"亞瑪謝殺了以東人回來，就把西珥的神像帶回，立為自己的神，在它面前叩拜燒香。","notes":[]},{"n":15,"t":"因此，耶和華的怒氣向亞瑪謝發作，就差一個先知去見他，說：「這些神不能救它的民脫離你的手，你為何尋求它呢？」","notes":[]},{"n":16,"t":"先知與王說話的時候，王對他說：「誰立你作王的謀士呢？你住口吧！為何找打呢？」先知就止住了，又說：「你行這事，不聽從我的勸戒，我知道神定意要滅你。」","notes":[]},{"n":17,"t":"猶大王亞瑪謝與群臣商議，就差遣使者去見耶戶的孫子、約哈斯的兒子、以色列王約阿施，說：「你來，我們二人相見於戰場。」","notes":[],"heads":["與以色列爭戰"]},{"n":18,"t":"以色列王約阿施差遣使者去見猶大王亞瑪謝，說：「黎巴嫩的蒺藜差遣使者去見黎巴嫩的香柏樹，說：『將你的女兒給我兒子為妻。』後來黎巴嫩有一個野獸經過，把蒺藜踐踏了。","notes":[]},{"n":19,"t":"你說：『看哪，我打敗了以東人』，你就心高氣傲，以致矜誇。你在家裏安居就罷了，為何要惹禍使自己和猶大國一同敗亡呢？」","notes":[]},{"n":20,"t":"亞瑪謝卻不肯聽從。這是出乎神，好將他們交在敵人手裏，因為他們尋求以東的神。","notes":[]},{"n":21,"t":"於是以色列王約阿施上來，在猶大的伯‧示麥與猶大王亞瑪謝相見於戰場。","notes":[]},{"n":22,"t":"猶大人敗在以色列人面前，各自逃回家裏去了。","notes":[]},{"n":23,"t":"以色列王約阿施在伯‧示麥擒住約哈斯的孫子、約阿施的兒子、猶大王亞瑪謝，將他帶到耶路撒冷，又拆毀耶路撒冷的城牆，從以法蓮門直到角門，共四百肘；","notes":["就是亞哈謝"]},{"n":24,"t":"又將俄別‧以東所看守神殿裏的一切金銀和器皿，與王宮裏的財寶都拿了去，並帶人去為質，就回撒馬利亞去了。","notes":[]},{"n":25,"t":"以色列王約哈斯的兒子約阿施死後，猶大王約阿施的兒子亞瑪謝又活了十五年。","notes":[]},{"n":26,"t":"亞瑪謝其餘的事，自始至終不都寫在猶大和以色列諸王記上嗎？","notes":[]},{"n":27,"t":"自從亞瑪謝離棄耶和華之後，在耶路撒冷有人背叛他，他就逃到拉吉；叛黨卻打發人到拉吉，將他殺了。","notes":[]},{"n":28,"t":"人就用馬將他的屍首馱回，葬在猶大京城他列祖的墳地裏。","notes":[]}]},"26":{"heading":"猶大王烏西雅","verses":[{"n":1,"t":"猶大眾民立亞瑪謝的兒子烏西雅接續他父作王，那時他年十六歲。（","notes":["又名亞撒利雅"]},{"n":2,"t":"亞瑪謝與他列祖同睡之後，烏西雅收回以祿仍歸猶大，又重新修理。）","notes":[]},{"n":3,"t":"烏西雅登基的時候年十六歲，在耶路撒冷作王五十二年。他母親名叫耶可利雅，是耶路撒冷人。","notes":[]},{"n":4,"t":"烏西雅行耶和華眼中看為正的事，效法他父亞瑪謝一切所行的；","notes":[]},{"n":5,"t":"通曉神默示，撒迦利亞在世的時候，烏西雅定意尋求神；他尋求耶和華，神就使他亨通。","notes":[]},{"n":6,"t":"他出去攻擊非利士人，拆毀了迦特城、雅比尼城，和亞實突城；在非利士人中，在亞實突境內，又建築了些城。","notes":[]},{"n":7,"t":"神幫助他攻擊非利士人和住在姑珥‧巴力的阿拉伯人，並米烏尼人。","notes":[]},{"n":8,"t":"亞捫人給烏西雅進貢。他的名聲傳到埃及，因他甚是強盛。","notes":[]},{"n":9,"t":"烏西雅在耶路撒冷的角門和谷門，並城牆轉彎之處，建築城樓，且甚堅固；","notes":[]},{"n":10,"t":"又在曠野與高原和平原，建築望樓，挖了許多井，因他的牲畜甚多；又在山地和佳美之地，有農夫和修理葡萄園的人，因為他喜悅農事。","notes":[]},{"n":11,"t":"烏西雅又有軍兵，照書記耶利和官長瑪西雅所數點的，在王的一個將軍哈拿尼雅手下，分隊出戰。","notes":[]},{"n":12,"t":"族長、大能勇士的總數共有二千六百人，","notes":[]},{"n":13,"t":"他們手下的軍兵共有三十萬七千五百人，都有大能，善於爭戰，幫助王攻擊仇敵。","notes":[]},{"n":14,"t":"烏西雅為全軍預備盾牌、槍、盔、甲、弓，和甩石的機弦，","notes":[]},{"n":15,"t":"又在耶路撒冷使巧匠做機器，安在城樓和角樓上，用以射箭發石。烏西雅的名聲傳到遠方；因為他得了非常的幫助，甚是強盛。","notes":[]},{"n":16,"t":"他既強盛，就心高氣傲，以致行事邪僻，干犯耶和華－他的神，進耶和華的殿，要在香壇上燒香。","notes":[],"heads":["烏西雅因驕傲受懲"]},{"n":17,"t":"祭司亞撒利雅率領耶和華勇敢的祭司八十人，跟隨他進去。","notes":[]},{"n":18,"t":"他們就阻擋烏西雅王，對他說：「烏西雅啊，給耶和華燒香不是你的事，乃是亞倫子孫承接聖職祭司的事。你出聖殿吧！因為你犯了罪。你行這事，耶和華神必不使你得榮耀。」","notes":[]},{"n":19,"t":"烏西雅就發怒，手拿香爐要燒香。他向祭司發怒的時候，在耶和華殿中香壇旁眾祭司面前，額上忽然發出大痲瘋。","notes":[]},{"n":20,"t":"大祭司亞撒利雅和眾祭司觀看，見他額上發出大痲瘋，就催他出殿；他自己也急速出去，因為耶和華降災與他。","notes":[]},{"n":21,"t":"烏西雅王長大痲瘋直到死日，因此住在別的宮裏，與耶和華的殿隔絕。他兒子約坦管理家事，治理國民。","notes":[]},{"n":22,"t":"烏西雅其餘的事，自始至終都是亞摩斯的兒子先知以賽亞所記的。","notes":[]},{"n":23,"t":"烏西雅與他列祖同睡，葬在王陵的田間他列祖的墳地裏；因為人說，他是長大痲瘋的。他兒子約坦接續他作王。","notes":[]}]},"27":{"heading":"猶大王約坦","verses":[{"n":1,"t":"約坦登基的時候年二十五歲，在耶路撒冷作王十六年，他母親名叫耶路沙，是撒督的女兒。","notes":[]},{"n":2,"t":"約坦行耶和華眼中看為正的事，效法他父烏西雅一切所行的，只是不入耶和華的殿。百姓還行邪僻的事。","notes":[]},{"n":3,"t":"約坦建立耶和華殿的上門，在俄斐勒城上多有建造，","notes":[]},{"n":4,"t":"又在猶大山地建造城邑，在樹林中建築營寨和高樓。","notes":[]},{"n":5,"t":"約坦與亞捫人的王打仗勝了他們，當年他們進貢銀一百他連得，小麥一萬歌珥，大麥一萬歌珥；第二年、第三年也是這樣。","notes":[]},{"n":6,"t":"約坦在耶和華－他神面前行正道，以致日漸強盛。","notes":[]},{"n":7,"t":"約坦其餘的事和一切爭戰，並他的行為，都寫在以色列和猶大列王記上。","notes":[]},{"n":8,"t":"他登基的時候年二十五歲，在耶路撒冷作王十六年。","notes":[]},{"n":9,"t":"約坦與他列祖同睡，葬在大衛城裏。他兒子亞哈斯接續他作王。","notes":[]}]},"28":{"heading":"猶大王亞哈斯","verses":[{"n":1,"t":"亞哈斯登基的時候年二十歲，在耶路撒冷作王十六年；不像他祖大衛行耶和華眼中看為正的事，","notes":[]},{"n":2,"t":"卻行以色列諸王的道，又鑄造巴力的像，","notes":[]},{"n":3,"t":"並且在欣嫩子谷燒香，用火焚燒他的兒女，行耶和華在以色列人面前所驅逐的外邦人那可憎的事；","notes":[]},{"n":4,"t":"並在邱壇上、山岡上、各青翠樹下獻祭燒香。","notes":[]},{"n":5,"t":"所以，耶和華－他的神將他交在亞蘭王手裏。亞蘭王打敗他，擄了他許多的民，帶到大馬士革去。神又將他交在以色列王手裏，以色列王向他大行殺戮。","notes":[],"heads":["跟亞蘭和以色列交戰"]},{"n":6,"t":"利瑪利的兒子比加一日殺了猶大人十二萬，都是勇士，因為他們離棄了耶和華－他們列祖的神。","notes":[]},{"n":7,"t":"有一個以法蓮中的勇士，名叫細基利，殺了王的兒子瑪西雅和管理王宮的押斯利甘，並宰相以利加拿。","notes":[]},{"n":8,"t":"以色列人擄了他們的弟兄，連婦人帶兒女共有二十萬，又掠了許多的財物，帶到撒馬利亞去了。","notes":[]},{"n":9,"t":"但那裏有耶和華的一個先知，名叫俄德，出來迎接往撒馬利亞去的軍兵，對他們說：「因為耶和華－你們列祖的神惱怒猶大人，所以將他們交在你們手裏，你們竟怒氣沖天，大行殺戮。","notes":[],"heads":["先知俄德"]},{"n":10,"t":"如今你們又有意強逼猶大人和耶路撒冷人作你們的奴婢，你們豈不也有得罪耶和華－你們神的事嗎？","notes":[]},{"n":11,"t":"現在你們當聽我說，要將擄來的弟兄釋放回去，因為耶和華向你們已經大發烈怒。」","notes":[]},{"n":12,"t":"於是，以法蓮人的幾個族長－就是約哈難的兒子亞撒利雅、米實利末的兒子比利家、沙龍的兒子耶希西家、哈得萊的兒子亞瑪撒－起來攔擋出兵回來的人，","notes":[]},{"n":13,"t":"對他們說：「你們不可帶進這被擄的人來！你們想要使我們得罪耶和華，加增我們的罪惡過犯？因為我們的罪過甚大，已經有烈怒臨到以色列人了。」","notes":[]},{"n":14,"t":"於是帶兵器的人將擄來的人口和掠來的財物都留在眾首領和會眾的面前。","notes":[]},{"n":15,"t":"以上提名的那些人就站起，使被擄的人前來；其中有赤身的，就從所掠的財物中拿出衣服和鞋來，給他們穿，又給他們吃喝，用膏抹他們；其中有軟弱的，就使他們騎驢，送到棕樹城耶利哥他們弟兄那裏；隨後就回撒馬利亞去了。","notes":[]},{"n":16,"t":"那時，亞哈斯王差遣人去見亞述諸王，求他們幫助；","notes":[],"heads":["亞哈斯向亞述王求援"]},{"n":17,"t":"因為以東人又來攻擊猶大，擄掠子民。","notes":[]},{"n":18,"t":"非利士人也來侵佔高原和猶大南方的城邑，取了伯‧示麥、亞雅崙、基低羅，梭哥和屬梭哥的鄉村，亭納和屬亭納的鄉村，瑾鎖和屬瑾鎖的鄉村，就住在那裏。","notes":[]},{"n":19,"t":"因為以色列王亞哈斯在猶大放肆，大大干犯耶和華，所以耶和華使猶大卑微。","notes":[]},{"n":20,"t":"亞述王提革拉‧毗列色上來，卻沒有幫助他，反倒欺凌他。","notes":[]},{"n":21,"t":"亞哈斯從耶和華殿裏和王宮中，並首領家內所取的財寶給了亞述王，這也無濟於事。","notes":[]},{"n":22,"t":"這亞哈斯王在急難的時候，越發得罪耶和華。","notes":[],"heads":["亞哈斯的罪行"]},{"n":23,"t":"他祭祀攻擊他的大馬士革之神，說：「因為亞蘭王的神幫助他們，我也獻祭與他，他好幫助我。」但那些神使他和以色列眾人敗亡了。","notes":[]},{"n":24,"t":"亞哈斯將神殿裏的器皿都聚了來，毀壞了，且封鎖耶和華殿的門；在耶路撒冷各處的拐角建築祭壇，","notes":[]},{"n":25,"t":"又在猶大各城建立邱壇，與別神燒香，惹動耶和華－他列祖神的怒氣。","notes":[]},{"n":26,"t":"亞哈斯其餘的事和他的行為，自始至終都寫在猶大和以色列諸王記上。","notes":[]},{"n":27,"t":"亞哈斯與他列祖同睡，葬在耶路撒冷城裏，沒有送入以色列諸王的墳墓中。他兒子希西家接續他作王。","notes":[]}]},"29":{"heading":"猶大王希西家","verses":[{"n":1,"t":"希西家登基的時候年二十五歲，在耶路撒冷作王二十九年。他母親名叫亞比雅，是撒迦利雅的女兒。","notes":[]},{"n":2,"t":"希西家行耶和華眼中看為正的事，效法他祖大衛一切所行的。","notes":[]},{"n":3,"t":"元年正月，開了耶和華殿的門，重新修理。","notes":[],"heads":["潔淨聖殿"]},{"n":4,"t":"他召眾祭司和利未人來，聚集在東邊的寬闊處，","notes":[]},{"n":5,"t":"對他們說：「利未人哪，當聽我說：現在你們要潔淨自己，又潔淨耶和華－你們列祖神的殿，從聖所中除去污穢之物。","notes":[]},{"n":6,"t":"我們列祖犯了罪，行耶和華－我們神眼中看為惡的事，離棄他，轉臉背向他的居所，","notes":[]},{"n":7,"t":"封鎖廊門，吹滅燈火，不在聖所中向以色列神燒香，或獻燔祭。","notes":[]},{"n":8,"t":"因此，耶和華的忿怒臨到猶大和耶路撒冷，將其中的人拋來拋去，令人驚駭、嗤笑，正如你們親眼所見的。","notes":[]},{"n":9,"t":"所以我們的祖宗倒在刀下，我們的妻子兒女也被擄掠。","notes":[]},{"n":10,"t":"現在我心中有意與耶和華－以色列的神立約，好使他的烈怒轉離我們。","notes":[]},{"n":11,"t":"我的眾子啊，現在不要懈怠；因為耶和華揀選你們站在他面前事奉他，與他燒香。」","notes":[]},{"n":12,"t":"於是，利未人哥轄的子孫、亞瑪賽的兒子瑪哈，亞撒利雅的兒子約珥；米拉利的子孫、亞伯底的兒子基士，耶哈利勒的兒子亞撒利雅；革順的子孫、薪瑪的兒子約亞，約亞的兒子伊甸；","notes":[]},{"n":13,"t":"以利撒反的子孫申利和耶利；亞薩的子孫撒迦利雅和瑪探雅；","notes":[]},{"n":14,"t":"希幔的子孫耶歇和示每；耶杜頓的子孫示瑪雅和烏薛；","notes":[]},{"n":15,"t":"起來聚集他們的弟兄，潔淨自己，照著王的吩咐、耶和華的命令，進去潔淨耶和華的殿。","notes":[]},{"n":16,"t":"祭司進入耶和華的殿要潔淨殿，將殿中所有污穢之物搬到耶和華殿的院內，利未人接去，搬到外頭汲淪溪邊。","notes":[]},{"n":17,"t":"從正月初一日潔淨起，初八日到了耶和華的殿廊，用八日的工夫潔淨耶和華的殿，到正月十六日才潔淨完了。","notes":[]},{"n":18,"t":"於是，他們晉見希西家王，說：「我們已將耶和華的全殿和燔祭壇，並壇的一切器皿、陳設餅的桌子，與桌子的一切器皿都潔淨了；","notes":[],"heads":["重新奉獻聖殿"]},{"n":19,"t":"並且亞哈斯王在位犯罪的時候所廢棄的器皿，我們預備齊全，且潔淨了，現今都在耶和華的壇前。」","notes":[]},{"n":20,"t":"希西家王清早起來，聚集城裏的首領都上耶和華的殿；","notes":[]},{"n":21,"t":"牽了七隻公牛，七隻公羊，七隻羊羔，七隻公山羊，要為國、為殿、為猶大人作贖罪祭。王吩咐亞倫的子孫眾祭司，獻在耶和華的壇上，","notes":[]},{"n":22,"t":"就宰了公牛，祭司接血灑在壇上，宰了公羊，把血灑在壇上，又宰了羊羔，也把血灑在壇上；","notes":[]},{"n":23,"t":"把那作贖罪祭的公山羊牽到王和會眾面前，他們就按手在其上。","notes":[]},{"n":24,"t":"祭司宰了羊，將血獻在壇上作贖罪祭，為以色列眾人贖罪，因為王吩咐將燔祭和贖罪祭為以色列眾人獻上。","notes":[]},{"n":25,"t":"王又派利未人在耶和華殿中敲鈸，鼓瑟，彈琴，乃照大衛和他先見迦得，並先知拿單所吩咐的，就是耶和華藉先知所吩咐的。","notes":[]},{"n":26,"t":"利未人拿大衛的樂器，祭司拿號，一同站立。","notes":[]},{"n":27,"t":"希西家吩咐在壇上獻燔祭，燔祭一獻，就唱讚美耶和華的歌，用號，並用以色列王大衛的樂器相和。","notes":[]},{"n":28,"t":"會眾都敬拜，歌唱的歌唱，吹號的吹號，如此直到燔祭獻完了。","notes":[]},{"n":29,"t":"獻完了祭，王和一切跟隨的人都俯伏敬拜。","notes":[]},{"n":30,"t":"希西家王與眾首領又吩咐利未人用大衛和先見亞薩的詩詞頌讚耶和華；他們就歡歡喜喜地頌讚耶和華，低頭敬拜。","notes":[]},{"n":31,"t":"希西家說：「你們既然歸耶和華為聖，就要前來把祭物和感謝祭奉到耶和華殿裏。」會眾就把祭物和感謝祭奉來，凡甘心樂意的也將燔祭奉來。","notes":[]},{"n":32,"t":"會眾所奉的燔祭如下：公牛七十隻，公羊一百隻，羊羔二百隻，這都是作燔祭獻給耶和華的；","notes":[]},{"n":33,"t":"又有分別為聖之物，公牛六百隻，綿羊三千隻。","notes":[]},{"n":34,"t":"但祭司太少，不能剝盡燔祭牲的皮，所以他們的弟兄利未人幫助他們，直等燔祭的事完了，又等別的祭司自潔了；因為利未人誠心自潔，勝過祭司。","notes":[]},{"n":35,"t":"燔祭和平安祭牲的脂油，並燔祭同獻的奠祭甚多。這樣，耶和華殿中的事務俱都齊備了。","notes":["或譯：就整頓了"]},{"n":36,"t":"這事辦的甚速，希西家和眾民都喜樂，是因神為眾民所預備的。","notes":[]}]},"30":{"heading":"預備守逾越節","verses":[{"n":1,"t":"希西家差遣人去見以色列和猶大眾人，又寫信給以法蓮和瑪拿西人，叫他們到耶路撒冷耶和華的殿，向耶和華－以色列的神守逾越節；","notes":[]},{"n":2,"t":"因為王和眾首領，並耶路撒冷全會眾已經商議，要在二月內守逾越節。","notes":[]},{"n":3,"t":"正月間他們不能守；因為自潔的祭司尚不敷用，百姓也沒有聚集在耶路撒冷；","notes":["原文是那時"]},{"n":4,"t":"王與全會眾都以這事為善。","notes":[]},{"n":5,"t":"於是定了命令，傳遍以色列，從別是巴直到但，使他們都來，在耶路撒冷向耶和華－以色列的神守逾越節；因為照所寫的例，守這節的不多了。","notes":["或譯：因為民許久沒有照所寫的例守節了"]},{"n":6,"t":"驛卒就把王和眾首領的信，遵著王命傳遍以色列和猶大。信內說：「以色列人哪，你們當轉向耶和華－亞伯拉罕、以撒、以色列的神，好叫他轉向你們這脫離亞述王手的餘民。","notes":[]},{"n":7,"t":"你們不要效法你們列祖和你們的弟兄；他們干犯耶和華－他們列祖的神，以致耶和華丟棄他們，使他們敗亡，正如你們所見的。","notes":["或譯：令人驚駭"]},{"n":8,"t":"現在不要像你們列祖硬著頸項，只要歸順耶和華，進入他的聖所，就是永遠成聖的居所；又要事奉耶和華－你們的神，好使他的烈怒轉離你們。","notes":[]},{"n":9,"t":"你們若轉向耶和華，你們的弟兄和兒女必在擄掠他們的人面前蒙憐恤，得以歸回這地，因為耶和華－你們的神有恩典、施憐憫。你們若轉向他，他必不轉臉不顧你們。」","notes":[]},{"n":10,"t":"驛卒就由這城跑到那城，傳遍了以法蓮、瑪拿西，直到西布倫。那裏的人卻戲笑他們，譏誚他們。","notes":[]},{"n":11,"t":"然而亞設、瑪拿西、西布倫中也有人自卑，來到耶路撒冷。","notes":[]},{"n":12,"t":"神也感動猶大人，使他們一心遵行王與眾首領憑耶和華之言所發的命令。","notes":[]},{"n":13,"t":"二月，有許多人在耶路撒冷聚集，成為大會，要守除酵節。","notes":[],"heads":["守逾越節"]},{"n":14,"t":"他們起來，把耶路撒冷的祭壇和燒香的壇盡都除去，拋在汲淪溪中。","notes":[]},{"n":15,"t":"二月十四日，宰了逾越節的羊羔。祭司與利未人覺得慚愧，就潔淨自己，把燔祭奉到耶和華殿中，","notes":[]},{"n":16,"t":"遵著神人摩西的律法，照例站在自己的地方；祭司從利未人手裏接過血來，灑在壇上。","notes":[]},{"n":17,"t":"會中有許多人尚未自潔，所以利未人為一切不潔之人宰逾越節的羊羔，使他們在耶和華面前成為聖潔。","notes":[]},{"n":18,"t":"以法蓮、瑪拿西、以薩迦、西布倫有許多人尚未自潔，他們卻也吃逾越節的羊羔，不合所記錄的定例。希西家為他們禱告說：「凡專心尋求神，就是耶和華－他列祖之神的，雖不照著聖所潔淨之禮自潔，求至善的耶和華也饒恕他。」","notes":[],"end":19},{"n":20,"t":"耶和華垂聽希西家的禱告，就饒恕百姓。","notes":["原文是醫治"]},{"n":21,"t":"在耶路撒冷的以色列人大大喜樂，守除酵節七日。利未人和祭司用響亮的樂器，日日頌讚耶和華。","notes":[]},{"n":22,"t":"希西家慰勞一切善於事奉耶和華的利未人。於是眾人吃節筵七日，又獻平安祭，且向耶和華－他們列祖的神認罪。","notes":[]},{"n":23,"t":"全會眾商議，要再守節七日；於是歡歡喜喜地又守節七日。","notes":[],"heads":["再度守節"]},{"n":24,"t":"猶大王希西家賜給會眾公牛一千隻，羊七千隻為祭物；眾首領也賜給會眾公牛一千隻，羊一萬隻，並有許多的祭司潔淨自己。","notes":[]},{"n":25,"t":"猶大全會眾、祭司、利未人，並那從以色列地來的會眾和寄居的人，以及猶大寄居的人，盡都喜樂。","notes":[]},{"n":26,"t":"這樣，在耶路撒冷大有喜樂，自從以色列王大衛兒子所羅門的時候，在耶路撒冷沒有這樣的喜樂。","notes":[]},{"n":27,"t":"那時，祭司、利未人起來，為民祝福。他們的聲音蒙神垂聽，他們的禱告達到天上的聖所。","notes":[]}]},"31":{"heading":"希西家的改革","verses":[{"n":1,"t":"這事既都完畢，在那裏的以色列眾人就到猶大的城邑，打碎柱像，砍斷木偶，又在猶大、便雅憫、以法蓮、瑪拿西遍地將邱壇和祭壇拆毀淨盡。於是以色列眾人各回各城，各歸各地。","notes":[]},{"n":2,"t":"希西家派定祭司利未人的班次，各按各職獻燔祭和平安祭，又在耶和華殿門內事奉，稱謝頌讚耶和華。","notes":["原文是營"]},{"n":3,"t":"王又從自己的產業中定出分來為燔祭，就是早晚的燔祭和安息日、月朔，並節期的燔祭，都是按耶和華律法上所載的；","notes":[]},{"n":4,"t":"又吩咐住耶路撒冷的百姓將祭司、利未人所應得的分給他們，使他們專心遵守耶和華的律法。","notes":[]},{"n":5,"t":"諭旨一出，以色列人就把初熟的五穀、新酒、油、蜜，和田地的出產多多送來，又把各物的十分之一送來的極多。","notes":[]},{"n":6,"t":"住猶大各城的以色列人和猶大人也將牛羊的十分之一，並分別為聖歸耶和華－他們神之物，就是十分取一之物，盡都送來，積成堆壘；","notes":[]},{"n":7,"t":"從三月積起，到七月才完。","notes":[]},{"n":8,"t":"希西家和眾首領來，看見堆壘，就稱頌耶和華，又為耶和華的民以色列人祝福。","notes":[]},{"n":9,"t":"希西家向祭司、利未人查問這堆壘。","notes":[]},{"n":10,"t":"撒督家的大祭司亞撒利雅回答說：「自從民將供物送到耶和華殿以來，我們不但吃飽，且剩下的甚多；因為耶和華賜福給他的民，所剩下的才這樣豐盛。」","notes":[]},{"n":11,"t":"希西家吩咐在耶和華殿裏預備倉房，他們就預備了。","notes":[]},{"n":12,"t":"他們誠心將供物和十分取一之物，並分別為聖之物，都搬入倉內。利未人歌楠雅掌管這事，他兄弟示每為副管。","notes":[]},{"n":13,"t":"耶歇、亞撒細雅、拿哈、亞撒黑、耶利末、約撒拔、以列、伊斯瑪基雅、瑪哈、比拿雅都是督理，在歌楠雅和他兄弟示每的手下，是希西家王和管理神殿的亞撒利雅所派的。","notes":[]},{"n":14,"t":"守東門的利未人音拿的兒子可利，掌管樂意獻與神的禮物，發放獻與耶和華的供物和至聖的物。","notes":[]},{"n":15,"t":"在他手下有伊甸、珉雅珉、耶書亞、示瑪雅、亞瑪利雅、示迦尼雅，在祭司的各城裏供緊要的職任，無論弟兄大小，都按著班次分給他們。","notes":[]},{"n":16,"t":"按家譜，三歲以外的男丁，凡每日進耶和華殿、按班次供職的，也分給他；","notes":[]},{"n":17,"t":"又按宗族家譜分給祭司，按班次職任分給二十歲以外的利未人，","notes":[]},{"n":18,"t":"又按家譜計算，分給他們會中的妻子、兒女；因他們身供要職，自潔成聖。","notes":[]},{"n":19,"t":"按名派定的人要把應得的分給亞倫子孫，住在各城郊野、祭司所有的男丁和一切載入家譜的利未人。","notes":[]},{"n":20,"t":"希西家在猶大遍地這樣辦理，行耶和華－他神眼中看為善為正為忠的事。","notes":[]},{"n":21,"t":"凡他所行的，無論是辦神殿的事，是遵律法守誡命，是尋求他的神，都是盡心去行，無不亨通。","notes":[]}]},"32":{"heading":"亞述人恐嚇耶路撒冷","verses":[{"n":1,"t":"這虔誠的事以後，亞述王西拿基立來侵入猶大，圍困一切堅固城，想要攻破佔據。","notes":[]},{"n":2,"t":"希西家見西拿基立來，定意要攻打耶路撒冷，","notes":[]},{"n":3,"t":"就與首領和勇士商議，塞住城外的泉源；他們就都幫助他。","notes":[]},{"n":4,"t":"於是有許多人聚集，塞了一切泉源，並通流國中的小河，說：「亞述王來，為何讓他得著許多水呢？」","notes":[]},{"n":5,"t":"希西家力圖自強，就修築所有拆毀的城牆，高與城樓相齊；在城外又築一城，堅固大衛城的米羅，製造了許多軍器、盾牌；","notes":[]},{"n":6,"t":"設立軍長管理百姓，將他們招聚在城門的寬闊處，用話勉勵他們，說：","notes":[]},{"n":7,"t":"「你們當剛強壯膽，不要因亞述王和跟隨他的大軍恐懼、驚慌；因為與我們同在的，比與他們同在的更大。","notes":[]},{"n":8,"t":"與他們同在的是肉臂，與我們同在的是耶和華－我們的神，他必幫助我們，為我們爭戰。」百姓就靠猶大王希西家的話，安然無懼了。","notes":[]},{"n":9,"t":"此後，亞述王西拿基立和他的全軍攻打拉吉，就差遣臣僕到耶路撒冷見猶大王希西家和一切在耶路撒冷的猶大人，說：","notes":[]},{"n":10,"t":"「亞述王西拿基立如此說：『你們倚靠甚麼，還在耶路撒冷受困呢？","notes":[]},{"n":11,"t":"希西家對你們說「耶和華－我們的神必救我們脫離亞述王的手」，這不是誘惑你們，使你們受飢渴而死嗎？","notes":[]},{"n":12,"t":"這希西家豈不是廢去耶和華的邱壇和祭壇，吩咐猶大與耶路撒冷的人說「你們當在一個壇前敬拜，在其上燒香」嗎？","notes":[]},{"n":13,"t":"我與我列祖向列邦所行的，你們豈不知道嗎？列邦的神何嘗能救自己的國脫離我手呢？","notes":[]},{"n":14,"t":"我列祖所滅的國，那些神中誰能救自己的民脫離我手呢？難道你們的神能救你們脫離我手嗎？","notes":[]},{"n":15,"t":"所以你們不要叫希西家這樣欺哄誘惑你們，也不要信他；因為沒有一國一邦的神能救自己的民脫離我手和我列祖的手，何況你們的神更不能救你們脫離我的手。』」","notes":[]},{"n":16,"t":"西拿基立的臣僕還有別的話毀謗耶和華神和他僕人希西家。","notes":[]},{"n":17,"t":"西拿基立也寫信毀謗耶和華－以色列的神說：「列邦的神既不能救他的民脫離我手，希西家的神也不能救他的民脫離我手了。」","notes":[]},{"n":18,"t":"亞述王的臣僕用猶大言語向耶路撒冷城上的民大聲呼叫，要驚嚇他們，擾亂他們，以便取城。","notes":[]},{"n":19,"t":"他們論耶路撒冷的神，如同論世上人手所造的神一樣。","notes":[]},{"n":20,"t":"希西家王和亞摩斯的兒子先知以賽亞因此禱告，向天呼求。","notes":[]},{"n":21,"t":"耶和華就差遣一個使者進入亞述王營中，把所有大能的勇士和官長、將帥盡都滅了。亞述王滿面含羞地回到本國，進了他神的廟中，有他親生的兒子在那裏用刀殺了他。","notes":[]},{"n":22,"t":"這樣，耶和華救希西家和耶路撒冷的居民脫離亞述王西拿基立的手，也脫離一切仇敵的手，又賜他們四境平安。","notes":[]},{"n":23,"t":"有許多人到耶路撒冷，將供物獻與耶和華，又將寶物送給猶大王希西家。此後，希西家在列邦人的眼中看為尊大。","notes":[]},{"n":24,"t":"那時希西家病得要死，就禱告耶和華，耶和華應允他，賜他一個兆頭。","notes":[],"heads":["希西家的疾病和驕傲"]},{"n":25,"t":"希西家卻沒有照他所蒙的恩報答耶和華；因他心裏驕傲，所以忿怒要臨到他和猶大並耶路撒冷。","notes":[]},{"n":26,"t":"但希西家和耶路撒冷的居民覺得心裏驕傲，就一同自卑，以致耶和華的忿怒在希西家的日子沒有臨到他們。","notes":[]},{"n":27,"t":"希西家大有尊榮資財，建造府庫，收藏金銀、寶石、香料、盾牌，和各樣的寶器，","notes":[],"heads":["希西家的財富和尊榮"]},{"n":28,"t":"又建造倉房，收藏五穀、新酒，和油，又為各類牲畜蓋棚立圈；","notes":[]},{"n":29,"t":"並且建立城邑，還有許多的羊群牛群，因為神賜他極多的財產。","notes":[]},{"n":30,"t":"這希西家也塞住基訓的上源，引水直下，流在大衛城的西邊。希西家所行的事盡都亨通。","notes":[]},{"n":31,"t":"惟有一件事，就是巴比倫王差遣使者來見希西家，訪問國中所現的奇事；這件事神離開他，要試驗他，好知道他心內如何。","notes":[]},{"n":32,"t":"希西家其餘的事和他的善行都寫在亞摩斯的兒子先知以賽亞的默示書上和猶大、以色列的諸王記上。","notes":[],"heads":["希西家逝世"]},{"n":33,"t":"希西家與他列祖同睡，葬在大衛子孫的高陵上。他死的時候，猶大人和耶路撒冷的居民都尊敬他。他兒子瑪拿西接續他作王。","notes":[]}]},"33":{"heading":"猶大王瑪拿西","verses":[{"n":1,"t":"瑪拿西登基的時候年十二歲，在耶路撒冷作王五十五年。","notes":[]},{"n":2,"t":"他行耶和華眼中看為惡的事，效法耶和華在以色列人面前趕出的外邦人那可憎的事，","notes":[]},{"n":3,"t":"重新建築他父希西家所拆毀的邱壇，又為巴力築壇，做木偶，且敬拜事奉天上的萬象，","notes":[]},{"n":4,"t":"在耶和華的殿宇中築壇－耶和華曾指著這殿說：「我的名必永遠在耶路撒冷。」","notes":[]},{"n":5,"t":"他在耶和華殿的兩院中為天上的萬象築壇，","notes":[]},{"n":6,"t":"並在欣嫩子谷使他的兒女經火，又觀兆，用法術，行邪術，立交鬼的和行巫術的，多行耶和華眼中看為惡的事，惹動他的怒氣，","notes":[]},{"n":7,"t":"又在神殿內立雕刻的偶像。神曾對大衛和他兒子所羅門說：「我在以色列各支派中所選擇的耶路撒冷和這殿，必立我的名直到永遠。","notes":[]},{"n":8,"t":"以色列人若謹守遵行我藉摩西所吩咐他們的一切法度、律例、典章，我就不再使他們挪移離開我所賜給他們列祖之地。」","notes":[]},{"n":9,"t":"瑪拿西引誘猶大和耶路撒冷的居民，以致他們行惡比耶和華在以色列人面前所滅的列國更甚。","notes":[]},{"n":10,"t":"耶和華警戒瑪拿西和他的百姓，他們卻是不聽。","notes":[],"heads":["瑪拿西悔改"]},{"n":11,"t":"所以耶和華使亞述王的將帥來攻擊他們，用鐃鉤鉤住瑪拿西，用銅鍊鎖住他，帶到巴比倫去。","notes":[]},{"n":12,"t":"他在急難的時候，就懇求耶和華－他的神，且在他列祖的神面前極其自卑。","notes":[]},{"n":13,"t":"他祈禱耶和華，耶和華就允准他的祈求，垂聽他的禱告，使他歸回耶路撒冷，仍坐國位。瑪拿西這才知道惟獨耶和華是神。","notes":[]},{"n":14,"t":"此後，瑪拿西在大衛城外，從谷內基訓西邊直到魚門口，建築城牆，環繞俄斐勒，這牆築得甚高；又在猶大各堅固城內設立勇敢的軍長；","notes":[]},{"n":15,"t":"並除掉外邦人的神像與耶和華殿中的偶像，又將他在耶和華殿的山上和耶路撒冷所築的各壇都拆毀拋在城外；","notes":[]},{"n":16,"t":"重修耶和華的祭壇，在壇上獻平安祭、感謝祭，吩咐猶大人事奉耶和華－以色列的神。","notes":[]},{"n":17,"t":"百姓卻仍在邱壇上獻祭，只獻給耶和華－他們的神。","notes":[]},{"n":18,"t":"瑪拿西其餘的事和禱告他神的話，並先見奉耶和華－以色列神的名警戒他的言語，都寫在以色列諸王記上。","notes":[],"heads":["瑪拿西逝世"]},{"n":19,"t":"他的禱告，與神怎樣應允他，他未自卑以前的罪愆過犯，並在何處建築邱壇，設立亞舍拉和雕刻的偶像，都寫在何賽的書上。","notes":[]},{"n":20,"t":"瑪拿西與他列祖同睡，葬在自己的宮院裏。他兒子亞們接續他作王。","notes":[]},{"n":21,"t":"亞們登基的時候年二十二歲，在耶路撒冷作王二年。","notes":[],"heads":["猶大王亞們"]},{"n":22,"t":"他行耶和華眼中看為惡的事，效法他父瑪拿西所行的，祭祀事奉他父瑪拿西所雕刻的偶像，","notes":[]},{"n":23,"t":"不在耶和華面前像他父瑪拿西自卑。這亞們所犯的罪越犯越大。","notes":[]},{"n":24,"t":"他的臣僕背叛，在宮裏殺了他。","notes":[]},{"n":25,"t":"但國民殺了那些背叛亞們王的人，立他兒子約西亞接續他作王。","notes":[]}]},"34":{"heading":"猶大王約西亞","verses":[{"n":1,"t":"約西亞登基的時候年八歲，在耶路撒冷作王三十一年。","notes":[]},{"n":2,"t":"他行耶和華眼中看為正的事，效法他祖大衛所行的，不偏左右。","notes":[]},{"n":3,"t":"他作王第八年，尚且年幼，就尋求他祖大衛的神。到了十二年才潔淨猶大和耶路撒冷，除掉邱壇、木偶、雕刻的像，和鑄造的像。","notes":[],"heads":["約西亞清除偶像"]},{"n":4,"t":"眾人在他面前拆毀巴力的壇，砍斷壇上高高的日像，又把木偶和雕刻的像，並鑄造的像打碎成灰，撒在祭偶像人的墳上，","notes":[]},{"n":5,"t":"將他們祭司的骸骨燒在壇上，潔淨了猶大和耶路撒冷；","notes":[]},{"n":6,"t":"又在瑪拿西、以法蓮、西緬、拿弗他利各城，和四圍破壞之處，都這樣行；","notes":[]},{"n":7,"t":"又拆毀祭壇，把木偶和雕刻的像打碎成灰，砍斷以色列遍地所有的日像，就回耶路撒冷去了。","notes":[]},{"n":8,"t":"約西亞王十八年，淨地淨殿之後，就差遣亞薩利雅的兒子沙番、邑宰瑪西雅、約哈斯的兒子史官約亞去修理耶和華－他神的殿。","notes":[],"heads":["發現律法書"]},{"n":9,"t":"他們就去見大祭司希勒家，將奉到神殿的銀子交給他；這銀子是看守殿門的利未人從瑪拿西、以法蓮，和一切以色列剩下的人，以及猶大、便雅憫眾人，並耶路撒冷的居民收來的。","notes":[]},{"n":10,"t":"又將這銀子交給耶和華殿裏督工的，轉交修理耶和華殿的工匠，","notes":[]},{"n":11,"t":"就是交給木匠、石匠，買鑿成的石頭和架木與棟樑，修猶大王所毀壞的殿。","notes":[]},{"n":12,"t":"這些人辦事誠實，督工的是利未人米拉利的子孫雅哈、俄巴底；督催的是哥轄的子孫撒迦利亞、米書蘭；還有善於作樂的利未人。","notes":[]},{"n":13,"t":"他們又監管扛抬的人，督催一切做工的。利未人中也有作書記、作司事、作守門的。","notes":[]},{"n":14,"t":"他們將奉到耶和華殿的銀子運出來的時候，祭司希勒家偶然得了摩西所傳耶和華的律法書。","notes":[]},{"n":15,"t":"希勒家對書記沙番說：「我在耶和華殿裏得了律法書。」遂將書遞給沙番。","notes":[]},{"n":16,"t":"沙番把書拿到王那裏，回覆王說：「凡交給僕人們辦的都辦理了。","notes":[]},{"n":17,"t":"耶和華殿裏的銀子倒出來，交給督工的和匠人的手裏了。」","notes":[]},{"n":18,"t":"書記沙番又對王說：「祭司希勒家遞給我一卷書。」沙番就在王面前讀那書。","notes":[]},{"n":19,"t":"王聽見律法上的話，就撕裂衣服，","notes":[]},{"n":20,"t":"吩咐希勒家與沙番的兒子亞希甘、米迦的兒子亞比頓、書記沙番，和王的臣僕亞撒雅說：","notes":[]},{"n":21,"t":"「你們去為我、為以色列和猶大剩下的人，以這書上的話求問耶和華；因我們列祖沒有遵守耶和華的言語，沒有照這書上所記的去行，耶和華的烈怒就倒在我們身上。」","notes":[]},{"n":22,"t":"於是，希勒家和王所派的眾人都去見女先知戶勒大。戶勒大是掌管禮服沙龍的妻，沙龍是哈斯拉的孫子、特瓦的兒子。戶勒大住在耶路撒冷第二區；他們請問於她。","notes":[]},{"n":23,"t":"她對他們說：「耶和華－以色列的神如此說：『你們可以回覆那差遣你們來見我的人說，","notes":[]},{"n":24,"t":"耶和華如此說：我必照著在猶大王面前所讀那書上的一切咒詛，降禍與這地和其上的居民；","notes":[]},{"n":25,"t":"因為他們離棄我，向別神燒香，用他們手所做的惹我發怒，所以我的忿怒如火倒在這地上，總不熄滅。』","notes":[]},{"n":26,"t":"然而差遣你們來求問耶和華的猶大王，你們要這樣回覆他說：『耶和華－以色列的神如此說：至於你所聽見的話，","notes":[]},{"n":27,"t":"就是聽見我指著這地和其上居民所說的話，你便心裏敬服，在我面前自卑，撕裂衣服，向我哭泣，因此我應允了你。這是我－耶和華說的。","notes":[]},{"n":28,"t":"我必使你平平安安地歸到墳墓，到你列祖那裏，我要降與這地和其上居民的一切災禍，你也不致親眼看見。』」他們就回覆王去了。","notes":[]},{"n":29,"t":"王差遣人招聚猶大和耶路撒冷的眾長老來。","notes":[],"heads":["約西亞立約順從主"]},{"n":30,"t":"王和猶大眾人，與耶路撒冷的居民，並祭司利未人，以及所有的百姓，無論大小，都一同上到耶和華的殿；王就把殿裏所得的約書念給他們聽。","notes":[]},{"n":31,"t":"王站在他的地位上，在耶和華面前立約，要盡心盡性地順從耶和華，遵守他的誡命、法度、律例，成就這書上所記的約言；","notes":[]},{"n":32,"t":"又使住耶路撒冷和便雅憫的人都服從這約。於是耶路撒冷的居民都遵行他們列祖之神的約。","notes":[]},{"n":33,"t":"約西亞從以色列各處將一切可憎之物盡都除掉，使以色列境內的人都事奉耶和華－他們的神。約西亞在世的日子，就跟從耶和華－他們列祖的神，總不離開。","notes":[]}]},"35":{"heading":"約西亞守逾越節","verses":[{"n":1,"t":"約西亞在耶路撒冷向耶和華守逾越節。正月十四日，就宰了逾越節的羊羔。","notes":[]},{"n":2,"t":"王分派祭司各盡其職，又勉勵他們辦耶和華殿中的事；","notes":[]},{"n":3,"t":"又對那歸耶和華為聖、教訓以色列人的利未人說：「你們將聖約櫃安放在以色列王大衛兒子所羅門建造的殿裏，不必再用肩扛抬。現在要事奉耶和華－你們的神，服事他的民以色列。","notes":[]},{"n":4,"t":"你們應當按著宗族，照著班次，遵以色列王大衛和他兒子所羅門所寫的，自己預備。","notes":[]},{"n":5,"t":"要按著你們的弟兄，這民宗族的班次，站在聖所，每班中要利未宗族的幾個人。","notes":[]},{"n":6,"t":"要宰逾越節的羊羔，潔淨自己，為你們的弟兄預備了，好遵守耶和華藉摩西所吩咐的話。」","notes":[]},{"n":7,"t":"約西亞從群畜中賜給在那裏所有的人民，綿羊羔和山羊羔三萬隻，牛三千隻，作逾越節的祭物；這都是出自王的產業中。","notes":[]},{"n":8,"t":"約西亞的眾首領也樂意將犧牲給百姓和祭司利未人；又有管理神殿的希勒家、撒迦利亞、耶歇將羊羔二千六百隻，牛三百隻，給祭司作逾越節的祭物。","notes":[]},{"n":9,"t":"利未人的族長歌楠雅和他兩個兄弟示瑪雅、拿坦業，與哈沙比雅、耶利、約撒拔將羊羔五千隻，牛五百隻，給利未人作逾越節的祭物。","notes":[]},{"n":10,"t":"這樣，供獻的事齊備了。祭司站在自己的地方，利未人按著班次站立，都是照王所吩咐的。","notes":[]},{"n":11,"t":"利未人宰了逾越節的羊羔，祭司從他們手裏接過血來灑在壇上；利未人剝皮，","notes":[]},{"n":12,"t":"將燔祭搬來，按著宗族的班次分給眾民，好照摩西書上所寫的，獻給耶和華；獻牛也是這樣。","notes":[]},{"n":13,"t":"他們按著常例，用火烤逾越節的羊羔。別的聖物用鍋，用釜，用罐煮了，速速地送給眾民。","notes":[]},{"n":14,"t":"然後為自己和祭司預備祭物；因為祭司亞倫的子孫獻燔祭和脂油，直到晚上。所以利未人為自己和祭司亞倫的子孫，預備祭物。","notes":[]},{"n":15,"t":"歌唱的亞薩之子孫，照著大衛、亞薩、希幔，和王的先見耶杜頓所吩咐的，站在自己的地位上。守門的看守各門，不用離開他們的職事，因為他們的弟兄利未人給他們預備祭物。","notes":[]},{"n":16,"t":"當日，供奉耶和華的事齊備了，就照約西亞王的吩咐守逾越節，獻燔祭在耶和華的壇上。","notes":[]},{"n":17,"t":"當時在耶路撒冷的以色列人守逾越節，又守除酵節七日。","notes":[]},{"n":18,"t":"自從先知撒母耳以來，在以色列中沒有守過這樣的逾越節，以色列諸王也沒有守過，像約西亞、祭司、利未人、在那裏的猶大人，和以色列人，以及耶路撒冷居民所守的逾越節。","notes":[]},{"n":19,"t":"這逾越節是約西亞作王十八年守的。","notes":[]},{"n":20,"t":"這事以後，約西亞修完了殿，有埃及王尼哥上來，要攻擊靠近幼發拉底河的迦基米施；約西亞出去抵擋他。","notes":[],"heads":["約西亞逝世"]},{"n":21,"t":"他差遣使者來見約西亞，說：「猶大王啊，我與你何干？我今日來不是要攻擊你，乃是要攻擊與我爭戰之家，並且神吩咐我速行，你不要干預神的事，免得他毀滅你，因為神是與我同在。」","notes":[]},{"n":22,"t":"約西亞卻不肯轉去離開他，改裝要與他打仗，不聽從神藉尼哥之口所說的話，便來到米吉多平原爭戰。","notes":[]},{"n":23,"t":"弓箭手射中約西亞王。王對他的臣僕說：「我受了重傷，你拉我出陣吧！」","notes":[]},{"n":24,"t":"他的臣僕扶他下了戰車，上了次車，送他到耶路撒冷，他就死了，葬在他列祖的墳墓裏。猶大人和耶路撒冷人都為他悲哀。","notes":[]},{"n":25,"t":"耶利米為約西亞作哀歌。所有歌唱的男女也唱哀歌，追悼約西亞，直到今日；而且在以色列中成了定例。這歌載在哀歌書上。","notes":[]},{"n":26,"t":"約西亞其餘的事和他遵著耶和華律法上所記而行的善事，","notes":[]},{"n":27,"t":"並他自始至終所行的，都寫在以色列和猶大列王記上。","notes":[]}]},"36":{"heading":"猶大王約哈斯","verses":[{"n":1,"t":"國民立約西亞的兒子約哈斯在耶路撒冷接續他父作王。","notes":[]},{"n":2,"t":"約哈斯登基的時候年二十三歲，在耶路撒冷作王三個月。","notes":[]},{"n":3,"t":"埃及王在耶路撒冷廢了他，又罰猶大國銀子一百他連得，金子一他連得。","notes":[]},{"n":4,"t":"埃及王尼哥立約哈斯的哥哥以利雅敬作猶大和耶路撒冷的王，改名叫約雅敬，又將約哈斯帶到埃及去了。","notes":[]},{"n":5,"t":"約雅敬登基的時候年二十五歲，在耶路撒冷作王十一年，行耶和華－他神眼中看為惡的事。","notes":[],"heads":["猶大王約雅敬"]},{"n":6,"t":"巴比倫王尼布甲尼撒上來攻擊他，用銅鍊鎖著他，要將他帶到巴比倫去。","notes":[]},{"n":7,"t":"尼布甲尼撒又將耶和華殿裏的器皿帶到巴比倫，放在他神的廟裏。","notes":["或譯：自己的宮裏"]},{"n":8,"t":"約雅敬其餘的事和他所行可憎的事，並他一切的行為，都寫在以色列和猶大列王記上。他兒子約雅斤接續他作王。","notes":[]},{"n":9,"t":"約雅斤登基的時候年八歲，在耶路撒冷作王三個月零十天，行耶和華眼中看為惡的事。","notes":["在列王下二十四章八節是十八歲"],"heads":["猶大王約雅斤"]},{"n":10,"t":"過了一年，尼布甲尼撒差遣人將約雅斤和耶和華殿裏各樣寶貴的器皿帶到巴比倫，就立約雅斤的叔叔 西底家作猶大和耶路撒冷的王。","notes":["原文是兄"]},{"n":11,"t":"西底家登基的時候年二十一歲，在耶路撒冷作王十一年，","notes":[],"heads":["猶大王西底家"]},{"n":12,"t":"行耶和華－他神眼中看為惡的事。先知耶利米以耶和華的話勸他，他仍不在耶利米面前自卑。","notes":[]},{"n":13,"t":"尼布甲尼撒曾使他指著神起誓，他卻背叛，強項硬心，不歸服耶和華－以色列的神。","notes":[],"heads":["耶路撒冷陷落"]},{"n":14,"t":"眾祭司長和百姓也大大犯罪，效法外邦人一切可憎的事，污穢耶和華在耶路撒冷分別為聖的殿。","notes":[]},{"n":15,"t":"耶和華－他們列祖的神因為愛惜自己的民和他的居所，從早起來差遣使者去警戒他們。","notes":[]},{"n":16,"t":"他們卻嘻笑神的使者，藐視他的言語，譏誚他的先知，以致耶和華的忿怒向他的百姓發作，無法可救。","notes":[]},{"n":17,"t":"所以，耶和華使迦勒底人的王來攻擊他們，在他們聖殿裏用刀殺了他們的壯丁，不憐恤他們的少男處女、老人白叟。耶和華將他們都交在迦勒底王手裏。","notes":[]},{"n":18,"t":"迦勒底王將神殿裏的大小器皿與耶和華殿裏的財寶，並王和眾首領的財寶，都帶到巴比倫去了。","notes":[]},{"n":19,"t":"迦勒底人焚燒神的殿，拆毀耶路撒冷的城牆，用火燒了城裏的宮殿，毀壞了城裏寶貴的器皿。","notes":[]},{"n":20,"t":"凡脫離刀劍的，迦勒底王都擄到巴比倫去，作他和他子孫的僕婢，直到波斯國興起來。","notes":[]},{"n":21,"t":"這就應驗耶和華藉耶利米口所說的話：地享受安息；因為地土荒涼便守安息，直滿了七十年。","notes":[]},{"n":22,"t":"波斯王塞魯士元年，耶和華為要應驗藉耶利米口所說的話，就激動波斯王塞魯士的心，使他下詔通告全國，說：","notes":[],"heads":["塞魯士王下令猶大人返國"]},{"n":23,"t":"「波斯王塞魯士如此說：耶和華－天上的神已將天下萬國賜給我，又囑咐我在猶大的耶路撒冷為他建造殿宇。你們中間凡作他子民的，可以上去，願耶和華－他的神與他同在。」","notes":[]}]}},"EZR":{"1":{"heading":"塞魯士下令猶太人返國","verses":[{"n":1,"t":"波斯王塞魯士元年，耶和華為要應驗藉耶利米口所說的話，就激動波斯王塞魯士的心，使他下詔通告全國說：","notes":[]},{"n":2,"t":"「波斯王塞魯士如此說：『耶和華天上的神已將天下萬國賜給我，又囑咐我在猶大的耶路撒冷為他建造殿宇。","notes":[]},{"n":3,"t":"在你們中間凡作他子民的，可以上猶大的耶路撒冷，在耶路撒冷重建耶和華－以色列神的殿（只有他是神）。願神與這人同在。","notes":[]},{"n":4,"t":"凡剩下的人，無論寄居何處，那地的人要用金銀、財物、牲畜幫助他，另外也要為耶路撒冷神的殿甘心獻上禮物。』」","notes":[]},{"n":5,"t":"於是，猶大和便雅憫的族長、祭司、利未人，就是一切被神激動他心的人，都起來要上耶路撒冷去建造耶和華的殿。","notes":[]},{"n":6,"t":"他們四圍的人就拿銀器、金子、財物、牲畜、珍寶幫助他們，另外還有甘心獻的禮物。","notes":["原文是堅固他們的手"]},{"n":7,"t":"塞魯士王也將耶和華殿的器皿拿出來，這器皿是尼布甲尼撒從耶路撒冷掠來、放在自己神之廟中的。","notes":[]},{"n":8,"t":"波斯王塞魯士派庫官米提利達將這器皿拿出來，按數交給猶大的首領設巴薩。","notes":[]},{"n":9,"t":"器皿的數目記在下面：金盤三十個，銀盤一千個，刀二十九把，","notes":[]},{"n":10,"t":"金碗三十個，銀碗之次的四百一十個，別樣的器皿一千件。","notes":[]},{"n":11,"t":"金銀器皿共有五千四百件。被擄的人從巴比倫上耶路撒冷的時候，設巴薩將這一切都帶上來。","notes":[]}]},"2":{"heading":"被擄歸回者的名單","verses":[{"n":1,"t":"巴比倫王尼布甲尼撒從前擄到巴比倫之猶大省的人，現在他們的子孫從被擄到之地回耶路撒冷和猶大，各歸本城。","notes":[]},{"n":2,"t":"他們是同著所羅巴伯、耶書亞、尼希米、西萊雅、利來雅、末底改、必珊、米斯拔、比革瓦伊、利宏、巴拿回來的。","notes":[]},{"n":3,"t":"以色列人民的數目記在下面：巴錄的子孫二千一百七十二名；","notes":[]},{"n":4,"t":"示法提雅的子孫三百七十二名；","notes":[]},{"n":5,"t":"亞拉的子孫七百七十五名；","notes":[]},{"n":6,"t":"巴哈‧摩押的後裔，就是耶書亞和約押的子孫二千八百一十二名；","notes":[]},{"n":7,"t":"以攔的子孫一千二百五十四名；","notes":[]},{"n":8,"t":"薩土的子孫九百四十五名；","notes":[]},{"n":9,"t":"薩改的子孫七百六十名；","notes":[]},{"n":10,"t":"巴尼的子孫六百四十二名；","notes":[]},{"n":11,"t":"比拜的子孫六百二十三名；","notes":[]},{"n":12,"t":"押甲的子孫一千二百二十二名；","notes":[]},{"n":13,"t":"亞多尼干的子孫六百六十六名；","notes":[]},{"n":14,"t":"比革瓦伊的子孫二千零五十六名；","notes":[]},{"n":15,"t":"亞丁的子孫四百五十四名；","notes":[]},{"n":16,"t":"亞特的後裔，就是希西家的子孫九十八名；","notes":[]},{"n":17,"t":"比賽的子孫三百二十三名；","notes":[]},{"n":18,"t":"約拉的子孫一百一十二名；","notes":[]},{"n":19,"t":"哈順的子孫二百二十三名；","notes":[]},{"n":20,"t":"吉罷珥人九十五名；","notes":[]},{"n":21,"t":"伯利恆人一百二十三名；","notes":[]},{"n":22,"t":"尼陀法人五十六名；","notes":[]},{"n":23,"t":"亞拿突人一百二十八名；","notes":[]},{"n":24,"t":"亞斯瑪弗人四十二名；","notes":[]},{"n":25,"t":"基列‧耶琳人、基非拉人、比錄人共七百四十三名；","notes":[]},{"n":26,"t":"拉瑪人、迦巴人共六百二十一名；","notes":[]},{"n":27,"t":"默瑪人一百二十二名；","notes":[]},{"n":28,"t":"伯特利人、艾人共二百二十三名；","notes":[]},{"n":29,"t":"尼波人五十二名；","notes":[]},{"n":30,"t":"末必人一百五十六名；","notes":[]},{"n":31,"t":"別的以攔子孫一千二百五十四名；","notes":[]},{"n":32,"t":"哈琳的子孫三百二十名；","notes":[]},{"n":33,"t":"羅德人、哈第人、阿挪人共七百二十五名；","notes":[]},{"n":34,"t":"耶利哥人三百四十五名；","notes":[]},{"n":35,"t":"西拿人三千六百三十名。","notes":[]},{"n":36,"t":"祭司：耶書亞家耶大雅的子孫九百七十三名；","notes":[]},{"n":37,"t":"音麥的子孫一千零五十二名；","notes":[]},{"n":38,"t":"巴施戶珥的子孫一千二百四十七名；","notes":[]},{"n":39,"t":"哈琳的子孫一千零一十七名。","notes":[]},{"n":40,"t":"利未人：何達威雅的後裔，就是耶書亞和甲篾的子孫七十四名。","notes":[]},{"n":41,"t":"歌唱的：亞薩的子孫一百二十八名。","notes":[]},{"n":42,"t":"守門的：沙龍的子孫、亞特的子孫、達們的子孫、亞谷的子孫、哈底大的子孫、朔拜的子孫，共一百三十九名。","notes":[]},{"n":43,"t":"尼提寧：西哈的子孫、哈蘇巴的子孫、答巴俄的子孫、","notes":["就是殿役"]},{"n":44,"t":"基綠的子孫、西亞的子孫、巴頓的子孫、","notes":[]},{"n":45,"t":"利巴拿的子孫、哈迦巴的子孫、亞谷的子孫、","notes":[]},{"n":46,"t":"哈甲的子孫、薩買的子孫、哈難的子孫、","notes":[]},{"n":47,"t":"吉德的子孫、迦哈的子孫、利亞雅的子孫、","notes":[]},{"n":48,"t":"利汛的子孫、尼哥大的子孫、迦散的子孫、","notes":[]},{"n":49,"t":"烏撒的子孫、巴西亞的子孫、比賽的子孫、","notes":[]},{"n":50,"t":"押拿的子孫、米烏寧的子孫、尼普心的子孫、","notes":[]},{"n":51,"t":"巴卜的子孫、哈古巴的子孫、哈忽的子孫、","notes":[]},{"n":52,"t":"巴洗律的子孫、米希大的子孫、哈沙的子孫、","notes":[]},{"n":53,"t":"巴柯的子孫、西西拉的子孫、答瑪的子孫、","notes":[]},{"n":54,"t":"尼細亞的子孫、哈提法的子孫。","notes":[]},{"n":55,"t":"所羅門僕人的後裔，就是瑣太的子孫、瑣斐列的子孫、比路大的子孫、","notes":[]},{"n":56,"t":"雅拉的子孫、達昆的子孫、吉德的子孫、","notes":[]},{"n":57,"t":"示法提雅的子孫、哈替的子孫、玻黑列‧哈斯巴音的子孫、亞米的子孫。","notes":[]},{"n":58,"t":"尼提寧和所羅門僕人的後裔共三百九十二名。","notes":[]},{"n":59,"t":"從特‧米拉、特‧哈薩、基綠、押但、音麥上來的，不能指明他們的宗族譜系是以色列人不是；","notes":[]},{"n":60,"t":"他們是第來雅的子孫、多比雅的子孫、尼哥大的子孫，共六百五十二名。","notes":[]},{"n":61,"t":"祭司中，哈巴雅的子孫、哈哥斯的子孫、巴西萊的子孫；因為他們的先祖娶了基列人巴西萊的女兒為妻，所以起名叫巴西萊。","notes":[]},{"n":62,"t":"這三家的人在族譜之中尋查自己的譜系，卻尋不著，因此算為不潔，不准供祭司的職任。","notes":[]},{"n":63,"t":"省長對他們說：「不可吃至聖的物，直到有用烏陵和土明決疑的祭司興起來。」","notes":[]},{"n":64,"t":"會眾共有四萬二千三百六十名。","notes":[]},{"n":65,"t":"此外，還有他們的僕婢七千三百三十七名，又有歌唱的男女二百名。","notes":[]},{"n":66,"t":"他們有馬七百三十六匹，騾子二百四十五匹，","notes":[]},{"n":67,"t":"駱駝四百三十五隻，驢六千七百二十匹。","notes":[]},{"n":68,"t":"有些族長到了耶路撒冷耶和華殿的地方，便為神的殿甘心獻上禮物，要重新建造。","notes":[]},{"n":69,"t":"他們量力捐入工程庫的金子六萬一千達利克，銀子五千彌拿，並祭司的禮服一百件。","notes":[]},{"n":70,"t":"於是祭司、利未人、民中的一些人、歌唱的、守門的、尼提寧，並以色列眾人，各住在自己的城裏。","notes":[]}]},"3":{"heading":"恢復敬拜神的生活","verses":[{"n":1,"t":"到了七月，以色列人住在各城；那時他們如同一人，聚集在耶路撒冷。","notes":[]},{"n":2,"t":"約薩達兒子耶書亞和他的弟兄眾祭司，並撒拉鐵的兒子所羅巴伯與他的弟兄，都起來建築以色列神的壇，要照神人摩西律法書上所寫的，在壇上獻燔祭。","notes":[]},{"n":3,"t":"他們在原有的根基上築壇，因懼怕鄰國的民，又在其上向耶和華早晚獻燔祭，","notes":[]},{"n":4,"t":"又照律法書上所寫的守住棚節，按數照例獻每日所當獻的燔祭；","notes":[]},{"n":5,"t":"其後獻常獻的燔祭，並在月朔與耶和華的一切聖節獻祭，又向耶和華獻各人的甘心祭。","notes":[]},{"n":6,"t":"從七月初一日起，他們就向耶和華獻燔祭。但耶和華殿的根基尚未立定。","notes":[]},{"n":7,"t":"他們又將銀子給石匠、木匠，把糧食、酒、油給西頓人、泰爾人，使他們將香柏樹從黎巴嫩運到海裏，浮海運到約帕，是照波斯王塞魯士所允准的。","notes":[]},{"n":8,"t":"百姓到了耶路撒冷神殿的地方。第二年二月，撒拉鐵的兒子所羅巴伯，約薩達的兒子耶書亞和其餘的弟兄，就是祭司、利未人，並一切被擄歸回耶路撒冷的人，都興工建造；又派利未人，從二十歲以外的，督理建造耶和華殿的工作。","notes":[],"heads":["開始重建聖殿"]},{"n":9,"t":"於是猶大的後裔，就是耶書亞和他的子孫與弟兄，甲篾和他的子孫，利未人希拿達的子孫與弟兄，都一同起來，督理那在神殿做工的人。","notes":["在二章四十節作何達威雅"]},{"n":10,"t":"匠人立耶和華殿根基的時候，祭司皆穿禮服吹號，亞薩的子孫利未人敲鈸，照以色列王大衛所定的例，都站著讚美耶和華。","notes":[]},{"n":11,"t":"他們彼此唱和，讚美稱謝耶和華說：他本為善，他向以色列人永發慈愛。他們讚美耶和華的時候，眾民大聲呼喊，因耶和華殿的根基已經立定。","notes":[]},{"n":12,"t":"然而有許多祭司、利未人、族長，就是見過舊殿的老年人，現在親眼看見立這殿的根基，便大聲哭號，也有許多人大聲歡呼，","notes":[]},{"n":13,"t":"甚至百姓不能分辨歡呼的聲音和哭號的聲音；因為眾人大聲呼喊，聲音聽到遠處。","notes":[]}]},"4":{"heading":"建殿之工受阻","verses":[{"n":1,"t":"猶大和便雅憫的敵人聽說被擄歸回的人為耶和華－以色列的神建造殿宇，","notes":[]},{"n":2,"t":"就去見所羅巴伯和以色列的族長，對他們說：「請容我們與你們一同建造；因為我們尋求你們的神，與你們一樣。自從亞述王以撒哈頓帶我們上這地以來，我們常祭祀神。」","notes":[]},{"n":3,"t":"但所羅巴伯、耶書亞，和其餘以色列的族長對他們說：「我們建造神的殿與你們無干，我們自己為耶和華－以色列的神協力建造，是照波斯王塞魯士所吩咐的。」","notes":[]},{"n":4,"t":"那地的民，就在猶大人建造的時候，使他們的手發軟，擾亂他們；","notes":[]},{"n":5,"t":"從波斯王塞魯士年間，直到波斯王大流士登基的時候，賄買謀士，要敗壞他們的謀算。","notes":[]},{"n":6,"t":"在亞哈隨魯才登基的時候，上本控告猶大和耶路撒冷的居民。","notes":[],"heads":["阻撓重建耶路撒冷"]},{"n":7,"t":"亞達薛西年間，比施蘭、米特利達、他別，和他們的同黨上本奏告波斯王亞達薛西。本章是用亞蘭文字，亞蘭方言。","notes":[]},{"n":8,"t":"省長利宏、書記伸帥要控告耶路撒冷人，也上本奏告亞達薛西王。","notes":[]},{"n":9,"t":"省長利宏、書記伸帥，和同黨的底拿人、亞法薩提迦人、他毗拉人、亞法撒人、亞基衛人、巴比倫人、書珊迦人、底亥人、以攔人，","notes":[]},{"n":10,"t":"和尊大的亞斯那巴所遷移、安置在撒馬利亞城，並大河西一帶地方的人等，","notes":[]},{"n":11,"t":"上奏亞達薛西王說：「河西的臣民云云：","notes":[]},{"n":12,"t":"王該知道，從王那裏上到我們這裏的猶大人，已經到耶路撒冷重建這反叛惡劣的城，築立根基，建造城牆。","notes":[]},{"n":13,"t":"如今王該知道，他們若建造這城，城牆完畢就不再與王進貢，交課，納稅，終久王必受虧損。","notes":[]},{"n":14,"t":"我們既食御鹽，不忍見王吃虧，因此奏告於王。","notes":[]},{"n":15,"t":"請王考察先王的實錄，必在其上查知這城是反叛的城，與列王和各省有害；自古以來，其中常有悖逆的事，因此這城曾被拆毀。","notes":[]},{"n":16,"t":"我們謹奏王知，這城若再建造，城牆完畢，河西之地王就無分了。」","notes":[]},{"n":17,"t":"那時王諭覆省長利宏、書記伸帥，和他們的同黨，就是住撒馬利亞並河西一帶地方的人，說：「願你們平安云云。","notes":[]},{"n":18,"t":"你們所上的本，已經明讀在我面前。","notes":[]},{"n":19,"t":"我已命人考查，得知此城古來果然背叛列王，其中常有反叛悖逆的事。","notes":[]},{"n":20,"t":"從前耶路撒冷也有大君王統管河西全地，人就給他們進貢，交課，納稅。","notes":[]},{"n":21,"t":"現在你們要出告示命這些人停工，使這城不得建造，等我降旨。","notes":[]},{"n":22,"t":"你們當謹慎，不可遲延，為何容害加重，使王受虧損呢？」","notes":[]},{"n":23,"t":"亞達薛西王的上諭讀在利宏和書記伸帥，並他們的同黨面前，他們就急忙往耶路撒冷去見猶大人，用勢力強迫他們停工。","notes":[]},{"n":24,"t":"於是，在耶路撒冷神殿的工程就停止了，直停到波斯王大流士第二年。","notes":[],"heads":["恢復重建聖殿工作"]}]},"5":{"heading":"","verses":[{"n":1,"t":"那時，先知哈該和易多的孫子撒迦利亞奉以色列神的名向猶大和耶路撒冷的猶大人說勸勉的話。","notes":[]},{"n":2,"t":"於是撒拉鐵的兒子所羅巴伯和約薩達的兒子耶書亞都起來動手建造耶路撒冷神的殿，有神的先知在那裏幫助他們。","notes":[]},{"n":3,"t":"當時河西的總督達乃和示他‧波斯乃，並他們的同黨來問說：「誰降旨讓你們建造這殿，修成這牆呢？」","notes":[]},{"n":4,"t":"我們便告訴他們建造這殿的人叫甚麼名字。","notes":[]},{"n":5,"t":"神的眼目看顧猶大的長老，以致總督等沒有叫他們停工，直到這事奏告大流士，得著他的回諭。","notes":[]},{"n":6,"t":"河西的總督達乃和示他‧波斯乃，並他們的同黨，就是住河西的亞法薩迦人，上本奏告大流士王。","notes":[]},{"n":7,"t":"本上寫著說：「願大流士王諸事平安。","notes":[]},{"n":8,"t":"王該知道，我們往猶大省去，到了至大神的殿，這殿是用大石建造的。樑木插入牆內，工作甚速，他們手下亨通。","notes":[]},{"n":9,"t":"我們就問那些長老說：『誰降旨讓你們建造這殿，修成這牆呢？』","notes":[]},{"n":10,"t":"又問他們的名字，要記錄他們首領的名字，奏告於王。","notes":[]},{"n":11,"t":"他們回答說：『我們是天地之神的僕人，重建前多年所建造的殿，就是以色列的一位大君王建造修成的。","notes":[]},{"n":12,"t":"只因我們列祖惹天上的神發怒，神把他們交在迦勒底人巴比倫王尼布甲尼撒的手中，他就拆毀這殿，又將百姓擄到巴比倫。","notes":[]},{"n":13,"t":"然而巴比倫王塞魯士元年，他降旨允准建造神的這殿。","notes":[]},{"n":14,"t":"神殿中的金、銀器皿，就是尼布甲尼撒從耶路撒冷的殿中掠去帶到巴比倫廟裏的，塞魯士王從巴比倫廟裏取出來，交給派為省長的，名叫設巴薩，","notes":[]},{"n":15,"t":"對他說可以將這些器皿帶去，放在耶路撒冷的殿中，在原處建造神的殿。","notes":[]},{"n":16,"t":"於是這設巴薩來建立耶路撒冷神殿的根基。這殿從那時直到如今尚未造成。』","notes":[]},{"n":17,"t":"現在王若以為美，請察巴比倫王的府庫，看塞魯士王降旨允准在耶路撒冷建造神的殿沒有，王的心意如何？請降旨曉諭我們。」","notes":[]}]},"6":{"heading":"發現塞魯士王原有的詔令","verses":[{"n":1,"t":"於是大流士王降旨，要尋察典籍庫內，就是在巴比倫藏寶物之處；","notes":[]},{"n":2,"t":"在米底亞省亞馬他城的宮內尋得一卷，其中記著說：","notes":[]},{"n":3,"t":"「塞魯士王元年，他降旨論到耶路撒冷神的殿，要建造這殿為獻祭之處，堅立殿的根基。殿高六十肘，寬六十肘，","notes":[]},{"n":4,"t":"用三層大石頭，一層新木頭，經費要出於王庫；","notes":[]},{"n":5,"t":"並且神殿的金銀器皿，就是尼布甲尼撒從耶路撒冷的殿中掠到巴比倫的，要歸還帶到耶路撒冷的殿中，各按原處放在神的殿裏。」","notes":[]},{"n":6,"t":"「現在河西的總督達乃和示他‧波斯乃，並你們的同黨，就是住河西的亞法薩迦人，你們當遠離他們。","notes":[],"heads":["大流士王下令繼續建殿"]},{"n":7,"t":"不要攔阻神殿的工作，任憑猶大人的省長和猶大人的長老在原處建造神的這殿。","notes":[]},{"n":8,"t":"我又降旨，吩咐你們向猶大人的長老為建造神的殿當怎樣行，就是從河西的款項中，急速撥取貢銀作他們的經費，免得耽誤工作。","notes":[]},{"n":9,"t":"他們與天上的神獻燔祭所需用的公牛犢、公綿羊、綿羊羔，並所用的麥子、鹽、酒、油，都要照耶路撒冷祭司的話，每日供給他們，不得有誤；","notes":[]},{"n":10,"t":"好叫他們獻馨香的祭給天上的神，又為王和王眾子的壽命祈禱。","notes":[]},{"n":11,"t":"我再降旨，無論誰更改這命令，必從他房屋中拆出一根樑來，把他舉起，懸在其上，又使他的房屋成為糞堆。","notes":[]},{"n":12,"t":"若有王和民伸手更改這命令，拆毀這殿，願那使耶路撒冷的殿作為他名居所的神將他們滅絕。我－大流士降這旨意，當速速遵行。」","notes":[]},{"n":13,"t":"於是，河西總督達乃和示他‧波斯乃，並他們的同黨，因大流士王所發的命令，就急速遵行。","notes":[],"heads":["聖殿奉獻典禮"]},{"n":14,"t":"猶大長老因先知哈該和易多的孫子撒迦利亞所說勸勉的話就建造這殿，凡事亨通。他們遵著以色列神的命令和波斯王塞魯士、大流士、亞達薛西的旨意，建造完畢。","notes":[]},{"n":15,"t":"大流士王第六年，亞達月初三日，這殿修成了。","notes":[]},{"n":16,"t":"以色列的祭司和利未人，並其餘被擄歸回的人都歡歡喜喜地行奉獻神殿的禮。","notes":[]},{"n":17,"t":"行奉獻神殿的禮就獻公牛一百隻，公綿羊二百隻，綿羊羔四百隻，又照以色列支派的數目獻公山羊十二隻，為以色列眾人作贖罪祭；","notes":[]},{"n":18,"t":"且派祭司和利未人按著班次在耶路撒冷事奉神，是照摩西律法書上所寫的。","notes":[]},{"n":19,"t":"正月十四日，被擄歸回的人守逾越節。","notes":[],"heads":["守逾越節"]},{"n":20,"t":"原來，祭司和利未人一同自潔，無一人不潔淨。利未人為被擄歸回的眾人和他們的弟兄眾祭司，並為自己宰逾越節的羊羔。","notes":[]},{"n":21,"t":"從擄到之地歸回的以色列人和一切除掉所染外邦人污穢、歸附他們、要尋求耶和華－以色列神的人都吃這羊羔，","notes":[]},{"n":22,"t":"歡歡喜喜地守除酵節七日；因為耶和華使他們歡喜，又使亞述王的心轉向他們，堅固他們的手，作以色列神殿的工程。","notes":[]}]},"7":{"heading":"以斯拉到達耶路撒冷","verses":[{"n":1,"t":"這事以後，波斯王亞達薛西年間，有個以斯拉，他是西萊雅的兒子，西萊雅是亞撒利雅的兒子，亞撒利雅是希勒家的兒子，","notes":[]},{"n":2,"t":"希勒家是沙龍的兒子，沙龍是撒督的兒子，撒督是亞希突的兒子，","notes":[]},{"n":3,"t":"亞希突是亞瑪利雅的兒子，亞瑪利雅是亞撒利雅的兒子，亞撒利雅是米拉約的兒子，","notes":[]},{"n":4,"t":"米拉約是西拉希雅的兒子，西拉希雅是烏西的兒子，烏西是布基的兒子，","notes":[]},{"n":5,"t":"布基是亞比書的兒子，亞比書是非尼哈的兒子，非尼哈是以利亞撒的兒子，以利亞撒是大祭司亞倫的兒子。","notes":[]},{"n":6,"t":"這以斯拉從巴比倫上來，他是敏捷的文士，通達耶和華－以色列神所賜摩西的律法書。王允准他一切所求的，是因耶和華－他神的手幫助他。","notes":[]},{"n":7,"t":"亞達薛西王第七年，以色列人、祭司、利未人、歌唱的、守門的、尼提寧，有上耶路撒冷的。","notes":[]},{"n":8,"t":"王第七年五月，以斯拉到了耶路撒冷。","notes":[]},{"n":9,"t":"正月初一日，他從巴比倫起程；因他神施恩的手幫助他，五月初一日就到了耶路撒冷。","notes":[]},{"n":10,"t":"以斯拉定志考究遵行耶和華的律法，又將律例典章教訓以色列人。","notes":[]},{"n":11,"t":"祭司以斯拉是通達耶和華誡命和賜以色列之律例的文士。亞達薛西王賜給他們諭旨，上面寫著說：","notes":[],"heads":["亞達薛西王給以斯拉的文件"]},{"n":12,"t":"「諸王之王亞達薛西，達於祭司以斯拉通達天上神律法大德的文士，云云。","notes":[]},{"n":13,"t":"住在我國中的以色列人、祭司、利未人，凡甘心上耶路撒冷去的，我降旨准他們與你同去。","notes":[]},{"n":14,"t":"王與七個謀士既然差你去，照你手中神的律法書察問猶大和耶路撒冷的景況；","notes":[]},{"n":15,"t":"又帶金銀，就是王和謀士甘心獻給住耶路撒冷、以色列神的，","notes":[]},{"n":16,"t":"並帶你在巴比倫全省所得的金銀，和百姓、祭司樂意獻給耶路撒冷－他們神殿的禮物。","notes":[]},{"n":17,"t":"所以你當用這金銀，急速買公牛、公綿羊、綿羊羔，和同獻的素祭奠祭之物，獻在耶路撒冷－你們神殿的壇上。","notes":[]},{"n":18,"t":"剩下的金銀，你和你的弟兄看著怎樣好，就怎樣用，總要遵著你們神的旨意。","notes":[]},{"n":19,"t":"所交給你神殿中使用的器皿，你要交在耶路撒冷神面前。","notes":[]},{"n":20,"t":"你神殿裏若再有需用的經費，你可以從王的府庫裏支取。","notes":[]},{"n":21,"t":"「我－亞達薛西王又降旨與河西的一切庫官，說：『通達天上神律法的文士祭司以斯拉，無論向你們要甚麼，你們要速速地備辦，","notes":[]},{"n":22,"t":"就是銀子直到一百他連得，麥子一百柯珥，酒一百罷特，油一百罷特，鹽不計其數，也要給他。","notes":[]},{"n":23,"t":"凡天上之神所吩咐的，當為天上神的殿詳細辦理。為何使忿怒臨到王和王眾子的國呢？","notes":[]},{"n":24,"t":"我又曉諭你們，至於祭司、利未人、歌唱的、守門的，和尼提寧，並在神殿當差的人，不可叫他們進貢，交課，納稅。』","notes":[]},{"n":25,"t":"「以斯拉啊，要照著你神賜你的智慧，將所有明白你神律法的人立為士師、審判官，治理河西的百姓，使他們教訓一切不明白神律法的人。","notes":[]},{"n":26,"t":"凡不遵行你神律法和王命令的人就當速速定他的罪，或治死，或充軍，或抄家，或囚禁。」","notes":[]},{"n":27,"t":"以斯拉說：「耶和華－我們列祖的神是應當稱頌的！因他使王起這心意修飾耶路撒冷耶和華的殿，","notes":[],"heads":["以斯拉稱頌耶和華"]},{"n":28,"t":"又在王和謀士，並大能的軍長面前施恩於我。因耶和華－我神的手幫助我，我就得以堅強，從以色列中招聚首領，與我一同上來。」","notes":[]}]},"8":{"heading":"從被擄之地回來的人","verses":[{"n":1,"t":"當亞達薛西王年間，同我從巴比倫上來的人，他們的族長和他們的家譜記在下面：","notes":[]},{"n":2,"t":"屬非尼哈的子孫有革順；屬以他瑪的子孫有但以理；屬大衛的子孫有哈突；","notes":[]},{"n":3,"t":"屬巴錄的後裔，就是示迦尼的子孫有撒迦利亞，同著他，按家譜計算，男丁一百五十人；","notes":[]},{"n":4,"t":"屬巴哈‧摩押的子孫有西拉希雅的兒子以利約乃，同著他有男丁二百；","notes":[]},{"n":5,"t":"屬示迦尼的子孫有雅哈悉的兒子，同著他有男丁三百；","notes":[]},{"n":6,"t":"屬亞丁的子孫有約拿單的兒子以別，同著他有男丁五十；","notes":[]},{"n":7,"t":"屬以攔的子孫有亞他利雅的兒子耶篩亞，同著他有男丁七十；","notes":[]},{"n":8,"t":"屬示法提雅的子孫有米迦勒的兒子西巴第雅，同著他有男丁八十；","notes":[]},{"n":9,"t":"屬約押的子孫有耶歇的兒子俄巴底亞，同著他有男丁二百一十八；","notes":[]},{"n":10,"t":"屬示羅密的子孫有約細斐的兒子，同著他有男丁一百六十；","notes":[]},{"n":11,"t":"屬比拜的子孫有比拜的兒子撒迦利亞，同著他有男丁二十八；","notes":[]},{"n":12,"t":"屬押甲的子孫有哈加坦的兒子約哈難，同著他有男丁一百一十；","notes":[]},{"n":13,"t":"屬亞多尼干的子孫，就是末尾的，他們的名字是以利法列、耶利、示瑪雅，同著他們有男丁六十；","notes":[]},{"n":14,"t":"屬比革瓦伊的子孫有烏太和撒布，同著他們有男丁七十。","notes":[]},{"n":15,"t":"我招聚這些人在流入亞哈瓦的河邊，我們在那裏住了三日。我查看百姓和祭司，見沒有利未人在那裏，","notes":[],"heads":["以斯拉為聖殿招集利未人"]},{"n":16,"t":"就召首領以利以謝、亞列、示瑪雅、以利拿單、雅立、以利拿單、拿單、撒迦利亞、米書蘭，又召教習約雅立和以利拿單。","notes":[]},{"n":17,"t":"我打發他們往迦西斐雅地方去見那裏的首領易多，又告訴他們當向易多和他的弟兄尼提寧說甚麼話，叫他們為我們神的殿帶使用的人來。","notes":[]},{"n":18,"t":"蒙我們神施恩的手幫助我們，他們在以色列的曾孫、利未的孫子、抹利的後裔中帶一個通達人來；還有示利比和他的眾子與弟兄共一十八人。","notes":[]},{"n":19,"t":"又有哈沙比雅，同著他有米拉利的子孫耶篩亞，並他的眾子和弟兄共二十人。","notes":[]},{"n":20,"t":"從前大衛和眾首領派尼提寧服事利未人，現在從這尼提寧中也帶了二百二十人來，都是按名指定的。","notes":[]},{"n":21,"t":"那時，我在亞哈瓦河邊宣告禁食，為要在我們神面前克苦己心，求他使我們和婦人孩子，並一切所有的，都得平坦的道路。","notes":[],"heads":["以斯拉領百姓禁食禱告"]},{"n":22,"t":"我求王撥步兵馬兵幫助我們抵擋路上的仇敵，本以為羞恥；因我曾對王說：「我們神施恩的手必幫助一切尋求他的；但他的能力和忿怒必攻擊一切離棄他的。」","notes":[]},{"n":23,"t":"所以我們禁食祈求我們的神，他就應允了我們。","notes":[]},{"n":24,"t":"我分派祭司長十二人，就是示利比、哈沙比雅，和他們的弟兄十人，","notes":[],"heads":["獻給聖殿的禮物"]},{"n":25,"t":"將王和謀士、軍長，並在那裏的以色列眾人為我們神殿所獻的金銀和器皿，都秤了交給他們。","notes":[]},{"n":26,"t":"我秤了交在他們手中的銀子有六百五十他連得；銀器重一百他連得；金子一百他連得；","notes":[]},{"n":27,"t":"金碗二十個，重一千達利克；上等光銅的器皿兩個，寶貴如金。","notes":[]},{"n":28,"t":"我對他們說：「你們歸耶和華為聖，器皿也為聖；金銀是甘心獻給耶和華－你們列祖之神的。","notes":[]},{"n":29,"t":"你們當警醒看守，直到你們在耶路撒冷耶和華殿的庫內，在祭司長和利未族長，並以色列的各族長面前過了秤。」","notes":[]},{"n":30,"t":"於是，祭司、利未人按著分量接受金銀和器皿，要帶到耶路撒冷我們神的殿裏。","notes":[]},{"n":31,"t":"正月十二日，我們從亞哈瓦河邊起行，要往耶路撒冷去。我們神的手保佑我們，救我們脫離仇敵和路上埋伏之人的手。","notes":[],"heads":["返回耶路撒冷"]},{"n":32,"t":"我們到了耶路撒冷，在那裏住了三日。","notes":[]},{"n":33,"t":"第四日，在我們神的殿裏把金銀和器皿都秤了，交在祭司烏利亞的兒子米利末的手中。同著他有非尼哈的兒子以利亞撒，還有利未人耶書亞的兒子約撒拔和賓內的兒子挪亞底。","notes":[]},{"n":34,"t":"當時都點了數目，按著分量寫在冊上。","notes":[]},{"n":35,"t":"從擄到之地歸回的人向以色列的神獻燔祭，就是為以色列眾人獻公牛十二隻，公綿羊九十六隻，綿羊羔七十七隻，又獻公山羊十二隻作贖罪祭，這都是向耶和華焚獻的。","notes":[]},{"n":36,"t":"他們將王的諭旨交給王所派的總督與河西的省長，他們就幫助百姓，又供給神殿裏所需用的。","notes":[]}]},"9":{"heading":"譴責跟異族通婚","verses":[{"n":1,"t":"這事做完了，眾首領來見我，說：「以色列民和祭司並利未人，沒有離絕迦南人、赫人、比利洗人、耶布斯人、亞捫人、摩押人、埃及人、亞摩利人，仍效法這些國的民，行可憎的事。","notes":[]},{"n":2,"t":"因他們為自己和兒子娶了這些外邦女子為妻，以致聖潔的種類和這些國的民混雜；而且首領和官長在這事上為罪魁。」","notes":[]},{"n":3,"t":"我一聽見這事，就撕裂衣服和外袍，拔了頭髮和鬍鬚，驚懼憂悶而坐。","notes":[]},{"n":4,"t":"凡為以色列神言語戰兢的，都因這被擄歸回之人所犯的罪聚集到我這裏來。我就驚懼憂悶而坐，直到獻晚祭的時候。","notes":[]},{"n":5,"t":"獻晚祭的時候我起來，心中愁苦，穿著撕裂的衣袍，雙膝跪下向耶和華－我的神舉手，","notes":[]},{"n":6,"t":"說：「我的神啊，我抱愧蒙羞，不敢向我神仰面；因為我們的罪孽滅頂，我們的罪惡滔天。","notes":[]},{"n":7,"t":"從我們列祖直到今日，我們的罪惡甚重；因我們的罪孽，我們和君王、祭司都交在外邦列王的手中，殺害、擄掠、搶奪、臉上蒙羞正如今日的光景。","notes":[]},{"n":8,"t":"現在耶和華－我們的神暫且施恩與我們，給我們留些逃脫的人，使我們安穩如釘子釘在他的聖所，我們的神好光照我們的眼目，使我們在受轄制之中稍微復興。","notes":[]},{"n":9,"t":"我們是奴僕，然而在受轄制之中，我們的神仍沒有丟棄我們，在波斯王眼前向我們施恩，叫我們復興，能重建我們神的殿，修其毀壞之處，使我們在猶大和耶路撒冷有牆垣。","notes":[]},{"n":10,"t":"「我們的神啊，既是如此，我們還有甚麼話可說呢？因為我們已經離棄你的命令，","notes":[]},{"n":11,"t":"就是你藉你僕人眾先知所吩咐的說：『你們要去得為業之地是污穢之地；因列國之民的污穢和可憎的事，叫全地從這邊直到那邊滿了污穢。","notes":[]},{"n":12,"t":"所以不可將你們的女兒嫁他們的兒子，也不可為你們的兒子娶他們的女兒，永不可求他們的平安和他們的利益，這樣你們就可以強盛，吃這地的美物，並遺留這地給你們的子孫永遠為業。』","notes":[]},{"n":13,"t":"神啊，我們因自己的惡行和大罪，遭遇了這一切的事，並且你刑罰我們輕於我們罪所當得的，又給我們留下這些人。","notes":[]},{"n":14,"t":"我們豈可再違背你的命令，與這行可憎之事的民結親呢？若這樣行，你豈不向我們發怒，將我們滅絕，以致沒有一個剩下逃脫的人嗎？","notes":[]},{"n":15,"t":"耶和華－以色列的神啊，因你是公義的，我們這剩下的人才得逃脫，正如今日的光景。看哪，我們在你面前有罪惡，因此無人在你面前站立得住。」","notes":[]}]},"10":{"heading":"終止與異族通婚的措施","verses":[{"n":1,"t":"以斯拉禱告，認罪，哭泣，俯伏在神殿前的時候，有以色列中的男女孩童聚集到以斯拉那裏，成了大會，眾民無不痛哭。","notes":[]},{"n":2,"t":"屬以攔的子孫、耶歇的兒子示迦尼對以斯拉說：「我們在此地娶了外邦女子為妻，干犯了我們的神，然而以色列人還有指望。","notes":[]},{"n":3,"t":"現在當與我們的神立約，休這一切的妻，離絕她們所生的，照著我主和那因神命令戰兢之人所議定的，按律法而行。","notes":[]},{"n":4,"t":"你起來，這是你當辦的事，我們必幫助你，你當奮勉而行。」","notes":[]},{"n":5,"t":"以斯拉便起來，使祭司長和利未人，並以色列眾人起誓說，必照這話去行；他們就起了誓。","notes":[]},{"n":6,"t":"以斯拉從神殿前起來，進入以利亞實的兒子約哈難的屋裏，到了那裏不吃飯，也不喝水；因為被擄歸回之人所犯的罪，心裏悲傷。","notes":[]},{"n":7,"t":"他們通告猶大和耶路撒冷被擄歸回的人，叫他們在耶路撒冷聚集。","notes":[]},{"n":8,"t":"凡不遵首領和長老所議定、三日之內不來的，就必抄他的家，使他離開被擄歸回之人的會。","notes":[]},{"n":9,"t":"於是，猶大和便雅憫眾人，三日之內都聚集在耶路撒冷。那日正是九月二十日，眾人都坐在神殿前的寬闊處；因這事，又因下大雨，就都戰兢。","notes":[]},{"n":10,"t":"祭司以斯拉站起來，對他們說：「你們有罪了；因你們娶了外邦的女子為妻，增添以色列人的罪惡。","notes":[]},{"n":11,"t":"現在當向耶和華－你們列祖的神認罪，遵行他的旨意，離絕這些國的民和外邦的女子。」","notes":[]},{"n":12,"t":"會眾都大聲回答說：「我們必照著你的話行，","notes":[]},{"n":13,"t":"只是百姓眾多，又逢大雨的時令，我們不能站在外頭，這也不是一兩天辦完的事，因我們在這事上犯了大罪；","notes":[]},{"n":14,"t":"不如為全會眾派首領辦理。凡我們城邑中娶外邦女子為妻的，當按所定的日期，同著本城的長老和士師而來，直到辦完這事，神的烈怒就轉離我們了。」","notes":[]},{"n":15,"t":"惟有亞撒黑的兒子約拿單，特瓦的兒子雅哈謝阻擋這事，並有米書蘭和利未人沙比太幫助他們。","notes":["或譯：總辦"]},{"n":16,"t":"被擄歸回的人如此而行。祭司以斯拉和些族長按著宗族都指名見派；在十月初一日，一同在座查辦這事，","notes":[]},{"n":17,"t":"到正月初一日，才查清娶外邦女子的人數。","notes":[]},{"n":18,"t":"在祭司中查出娶外邦女子為妻的，就是耶書亞的子孫約薩達的兒子，和他弟兄瑪西雅、以利以謝、雅立、基大利；","notes":[],"heads":["娶外邦女子的人"]},{"n":19,"t":"他們便應許必休他們的妻。他們因有罪，就獻群中的一隻公綿羊贖罪。","notes":[]},{"n":20,"t":"音麥的子孫中，有哈拿尼、西巴第雅。","notes":[]},{"n":21,"t":"哈琳的子孫中，有瑪西雅、以利雅、示瑪雅、耶歇、烏西雅。","notes":[]},{"n":22,"t":"巴施戶珥的子孫中，有以利約乃、瑪西雅、以實瑪利、拿坦業、約撒拔、以利亞撒。","notes":[]},{"n":23,"t":"利未人中，有約撒拔、示每、基拉雅（基拉雅就是基利他），還有毗他希雅、猶大、以利以謝。","notes":[]},{"n":24,"t":"歌唱的人中有以利亞實。守門的人中，有沙龍、提聯、烏利。","notes":[]},{"n":25,"t":"以色列人巴錄的子孫中，有拉米、耶西雅、瑪基雅、米雅民、以利亞撒、瑪基雅、比拿雅。","notes":[]},{"n":26,"t":"以攔的子孫中，有瑪他尼、撒迦利亞、耶歇、押底、耶利末、以利雅。","notes":[]},{"n":27,"t":"薩土的子孫中，有以利約乃、以利亞實、瑪他尼、耶利末、撒拔、亞西撒。","notes":[]},{"n":28,"t":"比拜的子孫中，有約哈難、哈拿尼雅、薩拜、亞勒。","notes":[]},{"n":29,"t":"巴尼的子孫中，有米書蘭、瑪鹿、亞大雅、雅述、示押、耶利末。","notes":[]},{"n":30,"t":"巴哈‧摩押的子孫中，有阿底拿、基拉、比拿雅、瑪西雅、瑪他尼、比撒列、賓內、瑪拿西。","notes":[]},{"n":31,"t":"哈琳的子孫中，有以利以謝、伊示雅、瑪基雅、示瑪雅、西緬、","notes":[]},{"n":32,"t":"便雅憫、瑪鹿、示瑪利雅。","notes":[]},{"n":33,"t":"哈順的子孫中，有瑪特乃、瑪達他、撒拔、以利法列、耶利買、瑪拿西、示每。","notes":[]},{"n":34,"t":"巴尼的子孫中，有瑪玳、暗蘭、烏益、","notes":[]},{"n":35,"t":"比拿雅、比底雅、基祿、","notes":[]},{"n":36,"t":"瓦尼雅、米利末、以利亞實、","notes":[]},{"n":37,"t":"瑪他尼、瑪特乃、雅掃、","notes":[]},{"n":38,"t":"巴尼、賓內、示每、","notes":[]},{"n":39,"t":"示利米雅、拿單、亞大雅、","notes":[]},{"n":40,"t":"瑪拿底拜、沙賽、沙賴、","notes":[]},{"n":41,"t":"亞薩利、示利米雅、示瑪利雅、","notes":[]},{"n":42,"t":"沙龍、亞瑪利雅、約瑟。","notes":[]},{"n":43,"t":"尼波的子孫中，有耶利、瑪他提雅、撒拔、西比拿、雅玳、約珥、比拿雅。","notes":[]},{"n":44,"t":"這些人都娶了外邦女子為妻，其中也有生了兒女的。","notes":[]}]}},"NEH":{"1":{"heading":"尼希米關心耶路撒冷","verses":[{"n":1,"t":"哈迦利亞的兒子尼希米的言語如下：亞達薛西王二十年基斯流月，我在書珊城的宮中。","notes":[]},{"n":2,"t":"那時，有我一個弟兄哈拿尼，同著幾個人從猶大來。我問他們那些被擄歸回、剩下逃脫的猶大人和耶路撒冷的光景。","notes":[]},{"n":3,"t":"他們對我說：「那些被擄歸回剩下的人在猶大省遭大難，受凌辱；並且耶路撒冷的城牆拆毀，城門被火焚燒。」","notes":[]},{"n":4,"t":"我聽見這話，就坐下哭泣，悲哀幾日，在天上的神面前禁食祈禱，說：","notes":[]},{"n":5,"t":"「耶和華－天上的神，大而可畏的神啊，你向愛你、守你誡命的人守約施慈愛。","notes":[]},{"n":6,"t":"願你睜眼看，側耳聽，你僕人晝夜在你面前為你眾僕人以色列民的祈禱，承認我們以色列人向你所犯的罪；我與我父家都有罪了。","notes":[]},{"n":7,"t":"我們向你所行的甚是邪惡，沒有遵守你藉著僕人摩西所吩咐的誡命、律例、典章。","notes":[]},{"n":8,"t":"求你記念所吩咐你僕人摩西的話，說：『你們若犯罪，我就把你們分散在萬民中；","notes":[]},{"n":9,"t":"但你們若歸向我，謹守遵行我的誡命，你們被趕散的人雖在天涯，我也必從那裏將他們招聚回來，帶到我所選擇立為我名的居所。』","notes":[]},{"n":10,"t":"這都是你的僕人、你的百姓，就是你用大力和大能的手所救贖的。","notes":[]},{"n":11,"t":"主啊，求你側耳聽你僕人的祈禱，和喜愛敬畏你名眾僕人的祈禱，使你僕人現今亨通，在王面前蒙恩。」我是作王酒政的。","notes":[]}]},"2":{"heading":"尼希米返耶路撒冷","verses":[{"n":1,"t":"亞達薛西王二十年尼散月，在王面前擺酒，我拿起酒來奉給王。我素來在王面前沒有愁容。","notes":[]},{"n":2,"t":"王對我說：「你既沒有病，為甚麼面帶愁容呢？這不是別的，必是你心中愁煩。」於是我甚懼怕。","notes":[]},{"n":3,"t":"我對王說：「願王萬歲！我列祖墳墓所在的那城荒涼，城門被火焚燒，我豈能面無愁容嗎？」","notes":[]},{"n":4,"t":"王問我說：「你要求甚麼？」於是我默禱天上的神。","notes":[]},{"n":5,"t":"我對王說：「僕人若在王眼前蒙恩，王若喜歡，求王差遣我往猶大，到我列祖墳墓所在的那城去，我好重新建造。」","notes":[]},{"n":6,"t":"那時王后坐在王的旁邊。王問我說：「你去要多少日子？幾時回來？」我就定了日期。於是王喜歡差遣我去。","notes":[]},{"n":7,"t":"我又對王說：「王若喜歡，求王賜我詔書，通知大河西的省長准我經過，直到猶大；","notes":[]},{"n":8,"t":"又賜詔書，通知管理王園林的亞薩，使他給我木料，做屬殿營樓之門的橫樑和城牆，與我自己房屋使用的。」王就允准我，因我神施恩的手幫助我。","notes":[]},{"n":9,"t":"王派了軍長和馬兵護送我。我到了河西的省長那裏，將王的詔書交給他們。","notes":[]},{"n":10,"t":"和倫人參巴拉，並為奴的亞捫人多比雅，聽見有人來為以色列人求好處，就甚惱怒。","notes":[]},{"n":11,"t":"我到了耶路撒冷，在那裏住了三日。","notes":[]},{"n":12,"t":"我夜間起來，有幾個人也一同起來；但神使我心裏要為耶路撒冷做甚麼事，我並沒有告訴人。除了我騎的牲口以外，也沒有別的牲口在我那裏。","notes":[]},{"n":13,"t":"當夜我出了谷門，往野狗井去，到了糞廠門，察看耶路撒冷的城牆，見城牆拆毀，城門被火焚燒。","notes":["野狗：或譯龍"]},{"n":14,"t":"我又往前，到了泉門和王池，但所騎的牲口沒有地方過去。","notes":[]},{"n":15,"t":"於是夜間沿溪而上，察看城牆，又轉身進入谷門，就回來了。","notes":[]},{"n":16,"t":"我往哪裏去，我做甚麼事，官長都不知道。我還沒有告訴猶大平民、祭司、貴冑、官長，和其餘做工的人。","notes":[]},{"n":17,"t":"以後，我對他們說：「我們所遭的難，耶路撒冷怎樣荒涼，城門被火焚燒，你們都看見了。來吧，我們重建耶路撒冷的城牆，免得再受凌辱！」","notes":[]},{"n":18,"t":"我告訴他們我神施恩的手怎樣幫助我，並王對我所說的話。他們就說：「我們起來建造吧！」於是他們奮勇做這善工。","notes":[]},{"n":19,"t":"但和倫人參巴拉，並為奴的亞捫人多比雅和阿拉伯人基善聽見就嗤笑我們，藐視我們，說：「你們做甚麼呢？要背叛王嗎？」","notes":[]},{"n":20,"t":"我回答他們說：「天上的神必使我們亨通。我們作他僕人的，要起來建造；你們卻在耶路撒冷無分、無權、無紀念。」","notes":[]}]},"3":{"heading":"重建耶路撒冷城牆","verses":[{"n":1,"t":"那時，大祭司以利亞實和他的弟兄眾祭司起來建立羊門，分別為聖，安立門扇，又築城牆到哈米亞樓，直到哈楠業樓，分別為聖。","notes":[]},{"n":2,"t":"其次是耶利哥人建造。其次是音利的兒子撒刻建造。","notes":[]},{"n":3,"t":"哈西拿的子孫建立魚門，架橫樑、安門扇，和閂鎖。","notes":[]},{"n":4,"t":"其次是哈哥斯的孫子、烏利亞的兒子米利末修造。其次是米示薩別的孫子、比利迦的兒子米書蘭修造。其次是巴拿的兒子撒督修造。","notes":[]},{"n":5,"t":"其次是提哥亞人修造；但是他們的貴冑不用肩擔他們主的工作。","notes":["原文是頸項"]},{"n":6,"t":"巴西亞的兒子耶何耶大與比所玳的兒子米書蘭修造古門，架橫樑，安門扇和閂鎖。","notes":[]},{"n":7,"t":"其次是基遍人米拉提，米倫人雅頓與基遍人，並屬河西總督所管的米斯巴人修造。","notes":[]},{"n":8,"t":"其次是銀匠哈海雅的兒子烏薛修造。其次是做香的哈拿尼雅修造。這些人修堅耶路撒冷，直到寬牆。","notes":[]},{"n":9,"t":"其次是管理耶路撒冷一半、戶珥的兒子利法雅修造。","notes":[]},{"n":10,"t":"其次是哈路抹的兒子耶大雅對著自己的房屋修造。其次是哈沙尼的兒子哈突修造。","notes":[]},{"n":11,"t":"哈琳的兒子瑪基雅和巴哈‧摩押的兒子哈述修造一段，並修造爐樓。","notes":[]},{"n":12,"t":"其次是管理耶路撒冷那一半、哈羅黑的兒子沙龍和他的女兒們修造。","notes":[]},{"n":13,"t":"哈嫩和撒挪亞的居民修造谷門，立門，安門扇和閂鎖，又建築城牆一千肘，直到糞廠門。","notes":[]},{"n":14,"t":"管理伯‧哈基琳、利甲的兒子瑪基雅修造糞廠門，立門，安門扇和閂鎖。","notes":[]},{"n":15,"t":"管理米斯巴、各荷西的兒子沙崙修造泉門，立門，蓋門頂，安門扇和閂鎖，又修造靠近王園西羅亞池的牆垣，直到那從大衛城下來的臺階。","notes":[]},{"n":16,"t":"其次是管理伯‧夙一半、押卜的兒子尼希米修造，直到大衛墳地的對面，又到挖成的池子，並勇士的房屋。","notes":[]},{"n":17,"t":"其次是利未人巴尼的兒子利宏修造。其次是管理基伊拉一半、哈沙比雅為他所管的本境修造。","notes":[],"heads":["造城牆的利未人"]},{"n":18,"t":"其次是利未人弟兄中管理基伊拉那一半、希拿達的兒子巴瓦伊修造。","notes":[]},{"n":19,"t":"其次是管理米斯巴、耶書亞的兒子以謝修造一段，對著武庫的上坡、城牆轉彎之處。","notes":[]},{"n":20,"t":"其次是薩拜的兒子巴錄竭力修造一段，從城牆轉彎，直到大祭司以利亞實的府門。","notes":[]},{"n":21,"t":"其次是哈哥斯的孫子、烏利亞的兒子米利末修造一段，從以利亞實的府門，直到以利亞實府的盡頭。","notes":[]},{"n":22,"t":"其次是住平原的祭司修造。","notes":[],"heads":["造城牆的祭司"]},{"n":23,"t":"其次是便雅憫與哈述對著自己的房屋修造。其次是亞難尼的孫子、瑪西雅的兒子亞撒利雅在靠近自己的房屋修造。","notes":[]},{"n":24,"t":"其次是希拿達的兒子賓內修造一段，從亞撒利雅的房屋直到城牆轉彎，又到城角。","notes":[]},{"n":25,"t":"烏賽的兒子巴拉修造對著城牆的轉彎和王上宮凸出來的城樓，靠近護衛院的那一段。其次是巴錄的兒子毗大雅修造。（","notes":[]},{"n":26,"t":"尼提寧住在俄斐勒，直到朝東水門的對面和凸出來的城樓。）","notes":[]},{"n":27,"t":"其次是提哥亞人又修一段，對著那凸出來的大樓，直到俄斐勒的牆。","notes":[],"heads":["其他建造的人"]},{"n":28,"t":"從馬門往上，眾祭司各對自己的房屋修造。","notes":[]},{"n":29,"t":"其次是音麥的兒子撒督對著自己的房屋修造。其次是守東門、示迦尼的兒子示瑪雅修造。","notes":[]},{"n":30,"t":"其次是示利米雅的兒子哈拿尼雅和薩拉的第六子哈嫩又修一段。其次是比利迦的兒子米書蘭對著自己的房屋修造。","notes":[]},{"n":31,"t":"其次是銀匠瑪基雅修造到尼提寧和商人的房屋，對著哈米弗甲門，直到城的角樓。","notes":[]},{"n":32,"t":"銀匠與商人在城的角樓和羊門中間修造。","notes":[]}]},"4":{"heading":"尼希米勝過阻撓他工作的人","verses":[{"n":1,"t":"參巴拉聽見我們修造城牆就發怒，大大惱恨，嗤笑猶大人，","notes":[]},{"n":2,"t":"對他弟兄和撒馬利亞的軍兵說：「這些軟弱的猶大人做甚麼呢？要保護自己嗎？要獻祭嗎？要一日成功嗎？要從土堆裏拿出火燒的石頭再立牆嗎？」","notes":[]},{"n":3,"t":"亞捫人多比雅站在旁邊，說：「他們所修造的石牆，就是狐狸上去也必跐倒。」","notes":[]},{"n":4,"t":"我們的神啊，求你垂聽，因為我們被藐視。求你使他們的毀謗歸於他們的頭上，使他們在擄到之地作為掠物。","notes":[]},{"n":5,"t":"不要遮掩他們的罪孽，不要使他們的罪惡從你面前塗抹，因為他們在修造的人眼前惹動你的怒氣。","notes":[]},{"n":6,"t":"這樣，我們修造城牆，城牆就都連絡，高至一半，因為百姓專心做工。","notes":[]},{"n":7,"t":"參巴拉、多比雅、阿拉伯人、亞捫人、亞實突人聽見修造耶路撒冷城牆，著手進行堵塞破裂的地方，就甚發怒。","notes":[]},{"n":8,"t":"大家同謀要來攻擊耶路撒冷，使城內擾亂。","notes":[]},{"n":9,"t":"然而，我們禱告我們的神，又因他們的緣故，就派人看守，晝夜防備。","notes":[]},{"n":10,"t":"猶大人說：「灰土尚多，扛抬的人力氣已經衰敗，所以我們不能建造城牆。」","notes":[]},{"n":11,"t":"我們的敵人且說：「趁他們不知不見，我們進入他們中間，殺他們，使工作止住。」","notes":[]},{"n":12,"t":"那靠近敵人居住的猶大人十次從各處來見我們，說：「你們必要回到我們那裏。」","notes":[]},{"n":13,"t":"所以我使百姓各按宗族拿刀、拿槍、拿弓站在城牆後邊低窪的空處。","notes":[]},{"n":14,"t":"我察看了，就起來對貴冑、官長，和其餘的人說：「不要怕他們！當記念主是大而可畏的。你們要為弟兄、兒女、妻子、家產爭戰。」","notes":[]},{"n":15,"t":"仇敵聽見我們知道他們的心意，見神也破壞他們的計謀，就不來了。我們都回到城牆那裏，各做各的工。","notes":[]},{"n":16,"t":"從那日起，我的僕人一半做工，一半拿槍、拿盾牌、拿弓、穿鎧甲，官長都站在猶大眾人的後邊。","notes":["或譯：拿"]},{"n":17,"t":"修造城牆的，扛抬材料的，都一手做工一手拿兵器。","notes":[]},{"n":18,"t":"修造的人都腰間佩刀修造，吹角的人在我旁邊。","notes":[]},{"n":19,"t":"我對貴冑、官長，和其餘的人說：「這工程浩大，我們在城牆上相離甚遠；","notes":[]},{"n":20,"t":"你們聽見角聲在哪裏，就聚集到我們那裏去。我們的神必為我們爭戰。」","notes":[]},{"n":21,"t":"於是，我們做工，一半拿兵器，從天亮直到星宿出現的時候。","notes":[]},{"n":22,"t":"那時，我又對百姓說：「各人和他的僕人當在耶路撒冷住宿，好在夜間保守我們，白晝做工。」","notes":[]},{"n":23,"t":"這樣，我和弟兄僕人，並跟從我的護兵都不脫衣服，出去打水也帶兵器。","notes":[]}]},"5":{"heading":"尼希米處理官長們的剝削","verses":[{"n":1,"t":"百姓和他們的妻大大呼號，埋怨他們的弟兄猶大人。","notes":[]},{"n":2,"t":"有的說：「我們和兒女人口眾多，要去得糧食度命」；","notes":[]},{"n":3,"t":"有的說：「我們典了田地、葡萄園、房屋，要得糧食充飢」；","notes":[]},{"n":4,"t":"有的說：「我們已經指著田地、葡萄園，借了錢給王納稅。","notes":[]},{"n":5,"t":"我們的身體與我們弟兄的身體一樣；我們的兒女與他們的兒女一般。現在我們將要使兒女作人的僕婢，我們的女兒已有為婢的；我們並無力拯救，因為我們的田地、葡萄園已經歸了別人。」","notes":[]},{"n":6,"t":"我聽見他們呼號說這些話，便甚發怒。","notes":[]},{"n":7,"t":"我心裏籌劃，就斥責貴冑和官長說：「你們各人向弟兄取利！」於是我招聚大會攻擊他們。","notes":[]},{"n":8,"t":"我對他們說：「我們盡力贖回我們弟兄，就是賣與外邦的猶大人；你們還要賣弟兄，使我們贖回來嗎？」他們就靜默不語，無話可答。","notes":[]},{"n":9,"t":"我又說：「你們所行的不善！你們行事不當敬畏我們的神嗎？不然，難免我們的仇敵外邦人毀謗我們。","notes":[]},{"n":10,"t":"我和我的弟兄與僕人也將銀錢糧食借給百姓；我們大家都當免去利息。","notes":[]},{"n":11,"t":"如今我勸你們將他們的田地、葡萄園、橄欖園、房屋，並向他們所取的銀錢、糧食、新酒，和油，百分之一的利息都歸還他們。」","notes":[]},{"n":12,"t":"眾人說：「我們必歸還，不再向他們索要，必照你的話行。」我就召了祭司來，叫眾人起誓，必照著所應許的而行。","notes":[]},{"n":13,"t":"我也抖著胸前的衣襟，說：「凡不成就這應許的，願神照樣抖他離開家產和他勞碌得來的，直到抖空了。」會眾都說：「阿們！」又讚美耶和華。百姓就照著所應許的去行。","notes":[]},{"n":14,"t":"自從我奉派作猶大地的省長，就是從亞達薛西王二十年直到三十二年，共十二年之久，我與我弟兄都沒有吃省長的俸祿。","notes":[],"heads":["尼希米大公無私"]},{"n":15,"t":"在我以前的省長加重百姓的擔子，每日索要糧食和酒，並銀子四十舍客勒，就是他們的僕人也轄制百姓；但我因敬畏神不這樣行。","notes":[]},{"n":16,"t":"並且我恆心修造城牆，並沒有置買田地；我的僕人也都聚集在那裏做工。","notes":[]},{"n":17,"t":"除了從四圍外邦中來的猶大人以外，有猶大平民和官長一百五十人在我席上吃飯。","notes":[]},{"n":18,"t":"每日預備一隻公牛，六隻肥羊，又預備些飛禽；每十日一次，多預備各樣的酒。雖然如此，我並不要省長的俸祿，因為百姓服役甚重。","notes":[]},{"n":19,"t":"我的神啊，求你記念我為這百姓所行的一切事，施恩與我。","notes":[]}]},"6":{"heading":"敵對尼希米的陰謀","verses":[{"n":1,"t":"參巴拉、多比雅、阿拉伯人基善和我們其餘的仇敵聽見我已經修完了城牆，其中沒有破裂之處（那時我還沒有安門扇）的，","notes":[]},{"n":2,"t":"參巴拉和基善就打發人來見我，說：「請你來，我們在阿挪平原的一個村莊相會。」他們卻想害我。","notes":[]},{"n":3,"t":"於是我差遣人去見他們，說：「我現在辦理大工，不能下去。焉能停工下去見你們呢？」","notes":[]},{"n":4,"t":"他們這樣四次打發人來見我，我都如此回答他們。","notes":[]},{"n":5,"t":"參巴拉第五次打發僕人來見我，手裏拿著未封的信，","notes":[]},{"n":6,"t":"信上寫著說：「外邦人中有風聲，迦施慕也說，你和猶大人謀反，修造城牆，你要作他們的王；","notes":["就是基善，見二章十九節"]},{"n":7,"t":"你又派先知在耶路撒冷指著你宣講，說在猶大有王。現在這話必傳與王知；所以請你來，與我們彼此商議。」","notes":[]},{"n":8,"t":"我就差遣人去見他，說：「你所說的這事，一概沒有，是你心裏捏造的。」","notes":[]},{"n":9,"t":"他們都要使我們懼怕，意思說，他們的手必軟弱，以致工作不能成就。神啊，求你堅固我的手。","notes":[]},{"n":10,"t":"我到了米希大別的孫子、第來雅的兒子示瑪雅家裏；那時，他閉門不出。他說：「我們不如在神的殿裏會面，將殿門關鎖；因為他們要來殺你，就是夜裏來殺你。」","notes":[]},{"n":11,"t":"我說：「像我這樣的人豈要逃跑呢？像我這樣的人豈能進入殿裏保全生命呢？我不進去！」","notes":[]},{"n":12,"t":"我看明神沒有差遣他，是他自己說這話攻擊我，是多比雅和參巴拉賄買了他。","notes":[]},{"n":13,"t":"賄買他的緣故，是要叫我懼怕，依從他犯罪，他們好傳揚惡言毀謗我。","notes":[]},{"n":14,"t":"我的神啊，多比雅、參巴拉、女先知挪亞底，和其餘的先知要叫我懼怕，求你記念他們所行的這些事。","notes":[]},{"n":15,"t":"以祿月二十五日，城牆修完了，共修了五十二天。","notes":[],"heads":["工程結束"]},{"n":16,"t":"我們一切仇敵、四圍的外邦人聽見了便懼怕，愁眉不展；因為見這工作完成是出乎我們的神。","notes":[]},{"n":17,"t":"在那些日子，猶大的貴冑屢次寄信與多比雅，多比雅也來信與他們。","notes":[]},{"n":18,"t":"在猶大有許多人與多比雅結盟；因他是亞拉的兒子，示迦尼的女婿，並且他的兒子約哈難娶了比利迦兒子米書蘭的女兒為妻。","notes":[]},{"n":19,"t":"他們常在我面前說多比雅的善行，也將我的話傳與他。多比雅又常寄信來，要叫我懼怕。","notes":[]}]},"7":{"heading":"被擄歸回者的名單","verses":[{"n":1,"t":"城牆修完，我安了門扇，守門的、歌唱的，和利未人都已派定。","notes":[]},{"n":2,"t":"我就派我的弟兄哈拿尼和營樓的宰官哈拿尼雅管理耶路撒冷；因為哈拿尼雅是忠信的，又敬畏神過於眾人。","notes":[]},{"n":3,"t":"我吩咐他們說：「等到太陽上升才可開耶路撒冷的城門；人尚看守的時候就要關門上閂；也當派耶路撒冷的居民各按班次看守自己房屋對面之處。」","notes":[]},{"n":4,"t":"城是廣大，其中的民卻稀少，房屋還沒有建造。","notes":[]},{"n":5,"t":"我的神感動我心，招聚貴冑、官長，和百姓，要照家譜計算。我找著第一次上來之人的家譜，其上寫著：","notes":[]},{"n":6,"t":"巴比倫王尼布甲尼撒從前擄去猶大省的人，現在他們的子孫從被擄到之地回耶路撒冷和猶大，各歸本城。","notes":[]},{"n":7,"t":"他們是同著所羅巴伯、耶書亞、尼希米、亞撒利雅、拉米、拿哈瑪尼、末底改、必珊、米斯毗列、比革瓦伊、尼宏、巴拿回來的。","notes":[]},{"n":8,"t":"以色列人民的數目記在下面：巴錄的子孫二千一百七十二名；","notes":[]},{"n":9,"t":"示法提雅的子孫三百七十二名；","notes":[]},{"n":10,"t":"亞拉的子孫六百五十二名；","notes":[]},{"n":11,"t":"巴哈‧摩押的後裔，就是耶書亞和約押的子孫二千八百一十八名；","notes":[]},{"n":12,"t":"以攔的子孫一千二百五十四名；","notes":[]},{"n":13,"t":"薩土的子孫八百四十五名；","notes":[]},{"n":14,"t":"薩改的子孫七百六十名；","notes":[]},{"n":15,"t":"賓內的子孫六百四十八名；","notes":[]},{"n":16,"t":"比拜的子孫六百二十八名；","notes":[]},{"n":17,"t":"押甲的子孫二千三百二十二名；","notes":[]},{"n":18,"t":"亞多尼干的子孫六百六十七名；","notes":[]},{"n":19,"t":"比革瓦伊的子孫二千零六十七名；","notes":[]},{"n":20,"t":"亞丁的子孫六百五十五名；","notes":[]},{"n":21,"t":"亞特的後裔，就是希西家的子孫九十八名；","notes":[]},{"n":22,"t":"哈順的子孫三百二十八名；","notes":[]},{"n":23,"t":"比賽的子孫三百二十四名；","notes":[]},{"n":24,"t":"哈拉的子孫一百一十二名；","notes":[]},{"n":25,"t":"基遍人九十五名；","notes":[]},{"n":26,"t":"伯利恆人和尼陀法人共一百八十八名；","notes":[]},{"n":27,"t":"亞拿突人一百二十八名；","notes":[]},{"n":28,"t":"伯‧亞斯瑪弗人四十二名；","notes":[]},{"n":29,"t":"基列‧耶琳人、基非拉人、比錄人共七百四十三名；","notes":[]},{"n":30,"t":"拉瑪人和迦巴人共六百二十一名；","notes":[]},{"n":31,"t":"默瑪人一百二十二名；","notes":[]},{"n":32,"t":"伯特利人和艾人共一百二十三名；","notes":[]},{"n":33,"t":"別的尼波人五十二名；","notes":[]},{"n":34,"t":"別的以攔子孫一千二百五十四名；","notes":[]},{"n":35,"t":"哈琳的子孫三百二十名；","notes":[]},{"n":36,"t":"耶利哥人三百四十五名；","notes":[]},{"n":37,"t":"羅德人、哈第人、阿挪人共七百二十一名；","notes":[]},{"n":38,"t":"西拿人三千九百三十名。","notes":[]},{"n":39,"t":"祭司：耶書亞家，耶大雅的子孫九百七十三名；","notes":[]},{"n":40,"t":"音麥的子孫一千零五十二名；","notes":[]},{"n":41,"t":"巴施戶珥的子孫一千二百四十七名；","notes":[]},{"n":42,"t":"哈琳的子孫一千零一十七名。","notes":[]},{"n":43,"t":"利未人：何達威的後裔，就是耶書亞和甲篾的子孫七十四名。","notes":[]},{"n":44,"t":"歌唱的：亞薩的子孫一百四十八名。","notes":[]},{"n":45,"t":"守門的：沙龍的子孫、亞特的子孫、達們的子孫、亞谷的子孫、哈底大的子孫、朔拜的子孫，共一百三十八名。","notes":[]},{"n":46,"t":"尼提寧：西哈的子孫、哈蘇巴的子孫、答巴俄的子孫、","notes":["就是殿役"]},{"n":47,"t":"基綠的子孫、西亞的子孫、巴頓的子孫、","notes":[]},{"n":48,"t":"利巴拿的子孫、哈迦巴的子孫、薩買的子孫、","notes":[]},{"n":49,"t":"哈難的子孫、吉德的子孫、迦哈的子孫、","notes":[]},{"n":50,"t":"利亞雅的子孫、利汛的子孫、尼哥大的子孫、","notes":[]},{"n":51,"t":"迦散的子孫、烏撒的子孫、巴西亞的子孫、","notes":[]},{"n":52,"t":"比賽的子孫、米烏寧的子孫、尼普心的子孫、","notes":[]},{"n":53,"t":"巴卜的子孫、哈古巴的子孫、哈忽的子孫、","notes":[]},{"n":54,"t":"巴洗律的子孫、米希大的子孫、哈沙的子孫、","notes":[]},{"n":55,"t":"巴柯的子孫、西西拉的子孫、答瑪的子孫、","notes":[]},{"n":56,"t":"尼細亞的子孫、哈提法的子孫。","notes":[]},{"n":57,"t":"所羅門僕人的後裔，就是瑣太的子孫、瑣斐列的子孫、比路大的子孫、","notes":[]},{"n":58,"t":"雅拉的子孫、達昆的子孫、吉德的子孫、","notes":[]},{"n":59,"t":"示法提雅的子孫、哈替的子孫、玻黑列‧哈斯巴音的子孫、亞們的子孫。","notes":[]},{"n":60,"t":"尼提寧和所羅門僕人的後裔共三百九十二名。","notes":[]},{"n":61,"t":"從特米拉、特哈薩、基綠、亞頓、音麥上來的，不能指明他們的宗族譜系是以色列人不是；","notes":[]},{"n":62,"t":"他們是第萊雅的子孫、多比雅的子孫、尼哥大的子孫，共六百四十二名。","notes":[]},{"n":63,"t":"祭司中，哈巴雅的子孫、哈哥斯的子孫、巴西萊的子孫；因為他們的先祖娶了基列人巴西萊的女兒為妻，所以起名叫巴西萊。","notes":[]},{"n":64,"t":"這三家的人在族譜之中尋查自己的譜系，卻尋不著，因此算為不潔，不准供祭司的職任。","notes":[]},{"n":65,"t":"省長對他們說：「不可吃至聖的物，直到有用烏陵和土明決疑的祭司興起來。」","notes":[]},{"n":66,"t":"會眾共有四萬二千三百六十名。","notes":[]},{"n":67,"t":"此外，還有他們的僕婢七千三百三十七名，又有歌唱的男女二百四十五名。","notes":[]},{"n":68,"t":"他們有馬七百三十六匹，騾子二百四十五匹，","notes":[]},{"n":69,"t":"駱駝四百三十五隻，驢六千七百二十匹。","notes":[]},{"n":70,"t":"有些族長為工程捐助。省長捐入庫中的金子一千達利克，碗五十個，祭司的禮服五百三十件。","notes":[]},{"n":71,"t":"又有族長捐入工程庫的金子二萬達利克，銀子二千二百彌拿。","notes":[]},{"n":72,"t":"其餘百姓所捐的金子二萬達利克，銀子二千彌拿，祭司的禮服六十七件。","notes":[]},{"n":73,"t":"於是祭司、利未人、守門的、歌唱的、民中的一些人、尼提寧，並以色列眾人，各住在自己的城裏。","notes":[]}]},"8":{"heading":"以斯拉向民眾宣讀律法書","verses":[{"n":1,"t":"到了七月，以色列人住在自己的城裏。那時，他們如同一人聚集在水門前的寬闊處，請文士以斯拉將耶和華藉摩西傳給以色列人的律法書帶來。","notes":[]},{"n":2,"t":"七月初一日，祭司以斯拉將律法書帶到聽了能明白的男女會眾面前。","notes":[]},{"n":3,"t":"在水門前的寬闊處，從清早到晌午，在眾男女、一切聽了能明白的人面前讀這律法書。眾民側耳而聽。","notes":[]},{"n":4,"t":"文士以斯拉站在為這事特備的木臺上。瑪他提雅、示瑪、亞奈雅、烏利亞、希勒家，和瑪西雅站在他的右邊；毗大雅、米沙利、瑪基雅、哈順、哈拔大拿、撒迦利亞，和米書蘭站在他的左邊。","notes":[]},{"n":5,"t":"以斯拉站在眾民以上，在眾民眼前展開這書。他一展開，眾民就都站起來。","notes":[]},{"n":6,"t":"以斯拉稱頌耶和華至大的神；眾民都舉手應聲說：「阿們！阿們！」就低頭，面伏於地，敬拜耶和華。","notes":[]},{"n":7,"t":"耶書亞、巴尼、示利比、雅憫、亞谷、沙比太、荷第雅、瑪西雅、基利他、亞撒利雅、約撒拔、哈難、毗萊雅，和利未人使百姓明白律法；百姓都站在自己的地方。","notes":[]},{"n":8,"t":"他們清清楚楚地念神的律法書，講明意思，使百姓明白所念的。","notes":[]},{"n":9,"t":"省長尼希米和作祭司的文士以斯拉，並教訓百姓的利未人，對眾民說：「今日是耶和華－你們神的聖日，不要悲哀哭泣。」這是因為眾民聽見律法書上的話都哭了；","notes":[]},{"n":10,"t":"又對他們說：「你們去吃肥美的，喝甘甜的，有不能預備的就分給他，因為今日是我們主的聖日。你們不要憂愁，因靠耶和華而得的喜樂是你們的力量。」","notes":[]},{"n":11,"t":"於是利未人使眾民靜默，說：「今日是聖日；不要作聲，也不要憂愁。」","notes":[]},{"n":12,"t":"眾民都去吃喝，也分給人，大大快樂，因為他們明白所教訓他們的話。","notes":[]},{"n":13,"t":"次日，眾民的族長、祭司，和利未人都聚集到文士以斯拉那裏，要留心聽律法上的話。","notes":[],"heads":["住棚節"]},{"n":14,"t":"他們見律法上寫著，耶和華藉摩西吩咐以色列人要在七月節住棚，","notes":[]},{"n":15,"t":"並要在各城和耶路撒冷宣傳報告說：「你們當上山，將橄欖樹、野橄欖樹、番石榴樹、棕樹，和各樣茂密樹的枝子取來，照著所寫的搭棚。」","notes":[]},{"n":16,"t":"於是百姓出去，取了樹枝來，各人在自己的房頂上，或院內，或神殿的院內，或水門的寬闊處，或以法蓮門的寬闊處搭棚。","notes":[]},{"n":17,"t":"從擄到之地歸回的全會眾就搭棚，住在棚裏。從嫩的兒子約書亞的時候直到這日，以色列人沒有這樣行。於是眾人大大喜樂。","notes":[]},{"n":18,"t":"從頭一天直到末一天，以斯拉每日念神的律法書。眾人守節七日，第八日照例有嚴肅會。","notes":[]}]},"9":{"heading":"以色列人承認他們的罪","verses":[{"n":1,"t":"這月二十四日，以色列人聚集禁食，身穿麻衣，頭蒙灰塵。","notes":[]},{"n":2,"t":"以色列人就與一切外邦人離絕，站著承認自己的罪惡和列祖的罪孽。","notes":["人：原文是種類"]},{"n":3,"t":"那日的四分之一站在自己的地方念耶和華－他們神的律法書，又四分之一認罪，敬拜耶和華－他們的神。","notes":[]},{"n":4,"t":"耶書亞、巴尼、甲篾、示巴尼、布尼、示利比、巴尼、基拿尼站在利未人的臺上，大聲哀求耶和華－他們的神。","notes":[]},{"n":5,"t":"利未人耶書亞、甲篾、巴尼、哈沙尼、示利比、荷第雅、示巴尼、毗他希雅說：「你們要站起來稱頌耶和華－你們的神，永世無盡。耶和華啊，你榮耀之名是應當稱頌的！超乎一切稱頌和讚美。」","notes":[]},{"n":6,"t":"「你，惟獨你是耶和華！你造了天和天上的天，並天上的萬象，地和地上的萬物，海和海中所有的；這一切都是你所保存的。天軍也都敬拜你。","notes":[],"heads":["認罪的禱告"]},{"n":7,"t":"你是耶和華神，曾揀選亞伯蘭，領他出迦勒底的吾珥，給他改名叫亞伯拉罕。","notes":[]},{"n":8,"t":"你見他在你面前心裏誠實，就與他立約，應許把迦南人、赫人、亞摩利人、比利洗人、耶布斯人、革迦撒人之地賜給他的後裔，且應驗了你的話，因為你是公義的。","notes":[]},{"n":9,"t":"「你曾看見我們列祖在埃及所受的困苦，垂聽他們在紅海邊的哀求，","notes":[]},{"n":10,"t":"就施行神蹟奇事在法老和他一切臣僕，並他國中的眾民身上。你也得了名聲，正如今日一樣，因為你知道他們向我們列祖行事狂傲。","notes":[]},{"n":11,"t":"你又在我們列祖面前把海分開，使他們在海中行走乾地，將追趕他們的人拋在深海，如石頭拋在大水中；","notes":[]},{"n":12,"t":"並且白晝用雲柱引導他們，黑夜用火柱照亮他們當行的路。","notes":[]},{"n":13,"t":"你也降臨在西奈山，從天上與他們說話，賜給他們正直的典章、真實的律法、美好的條例與誡命，","notes":[]},{"n":14,"t":"又使他們知道你的安息聖日，並藉你僕人摩西傳給他們誡命、條例、律法。","notes":[]},{"n":15,"t":"從天上賜下糧食充他們的飢，從磐石使水流出解他們的渴，又吩咐他們進去得你起誓應許賜給他們的地。","notes":[]},{"n":16,"t":"「但我們的列祖行事狂傲，硬著頸項不聽從你的誡命；","notes":[]},{"n":17,"t":"不肯順從，也不記念你在他們中間所行的奇事，竟硬著頸項，居心背逆，自立首領，要回他們為奴之地。但你是樂意饒恕人，有恩典，有憐憫，不輕易發怒，有豐盛慈愛的神，並不丟棄他們。","notes":[]},{"n":18,"t":"他們雖然鑄了一隻牛犢，彼此說『這是領你出埃及的神』，因而大大惹動你的怒氣；","notes":[]},{"n":19,"t":"你還是大施憐憫，在曠野不丟棄他們。白晝，雲柱不離開他們，仍引導他們行路；黑夜，火柱也不離開他們，仍照亮他們當行的路。","notes":[]},{"n":20,"t":"你也賜下你良善的靈教訓他們；未嘗不賜嗎哪使他們糊口，並賜水解他們的渴。","notes":[]},{"n":21,"t":"在曠野四十年，你養育他們，他們就一無所缺：衣服沒有穿破，腳也沒有腫。","notes":[]},{"n":22,"t":"並且你將列國之地照分賜給他們，他們就得了西宏之地、希實本王之地，和巴珊王噩之地。","notes":[]},{"n":23,"t":"你也使他們的子孫多如天上的星，帶他們到你所應許他們列祖進入得為業之地。","notes":[]},{"n":24,"t":"這樣，他們進去得了那地，你在他們面前制伏那地的居民，就是迦南人；將迦南人和其君王，並那地的居民，都交在他們手裏，讓他們任意而待。","notes":[]},{"n":25,"t":"他們得了堅固的城邑、肥美的地土、充滿各樣美物的房屋、鑿成的水井、葡萄園、橄欖園，並許多果木樹。他們就吃而得飽，身體肥胖，因你的大恩，心中快樂。","notes":[]},{"n":26,"t":"「然而，他們不順從，竟背叛你，將你的律法丟在背後，殺害那勸他們歸向你的眾先知，大大惹動你的怒氣。","notes":[]},{"n":27,"t":"所以你將他們交在敵人的手中，磨難他們。他們遭難的時候哀求你，你就從天上垂聽，照你的大憐憫賜給他們拯救者，救他們脫離敵人的手。","notes":[]},{"n":28,"t":"但他們得平安之後，又在你面前行惡，所以你丟棄他們在仇敵的手中，使仇敵轄制他們。然而他們轉回哀求你，你仍從天上垂聽，屢次照你的憐憫拯救他們，","notes":[]},{"n":29,"t":"又警戒他們，要使他們歸服你的律法。他們卻行事狂傲，不聽從你的誡命，干犯你的典章（人若遵行就必因此活著），扭轉肩頭，硬著頸項，不肯聽從。","notes":[]},{"n":30,"t":"但你多年寬容他們，又用你的靈藉眾先知勸戒他們，他們仍不聽從，所以你將他們交在列國之民的手中。","notes":[]},{"n":31,"t":"然而你大發憐憫，不全然滅絕他們，也不丟棄他們；因為你是有恩典、有憐憫的神。","notes":[]},{"n":32,"t":"「我們的神啊，你是至大、至能、至可畏、守約施慈愛的神。我們的君王、首領、祭司、先知、列祖，和你的眾民，從亞述列王的時候直到今日所遭遇的苦難，現在求你不要以為小。","notes":[]},{"n":33,"t":"在一切臨到我們的事上，你卻是公義的；因你所行的是誠實，我們所做的是邪惡。","notes":[]},{"n":34,"t":"我們的君王、首領、祭司、列祖都不遵守你的律法，不聽從你的誡命和你警戒他們的話。","notes":[]},{"n":35,"t":"他們在本國裏沾你大恩的時候，在你所賜給他們這廣大肥美之地上不事奉你，也不轉離他們的惡行。","notes":[]},{"n":36,"t":"我們現今作了奴僕；至於你所賜給我們列祖享受其上的土產，並美物之地，看哪，我們在這地上作了奴僕！","notes":[]},{"n":37,"t":"這地許多出產歸了列王，就是你因我們的罪所派轄制我們的。他們任意轄制我們的身體和牲畜，我們遭了大難。」","notes":[]},{"n":38,"t":"因這一切的事，我們立確實的約，寫在冊上。我們的首領、利未人，和祭司都簽了名。","notes":[]}]},"10":{"heading":"在公約上簽名的人","verses":[{"n":1,"t":"簽名的是：哈迦利亞的兒子－省長尼希米，和西底家；","notes":[]},{"n":2,"t":"祭司：西萊雅、亞撒利雅、耶利米、","notes":[]},{"n":3,"t":"巴施戶珥、亞瑪利雅、瑪基雅、","notes":[]},{"n":4,"t":"哈突、示巴尼、瑪鹿、","notes":[]},{"n":5,"t":"哈琳、米利末、俄巴底亞、","notes":[]},{"n":6,"t":"但以理、近頓、巴錄、","notes":[]},{"n":7,"t":"米書蘭、亞比雅、米雅民、","notes":[]},{"n":8,"t":"瑪西亞、璧該、示瑪雅；","notes":[]},{"n":9,"t":"又有利未人，就是亞散尼的兒子耶書亞、希拿達的子孫賓內、甲篾；","notes":[]},{"n":10,"t":"還有他們的弟兄示巴尼、荷第雅、基利他、毗萊雅、哈難、","notes":[]},{"n":11,"t":"米迦、利合、哈沙比雅、","notes":[]},{"n":12,"t":"撒刻、示利比、示巴尼、","notes":[]},{"n":13,"t":"荷第雅、巴尼、比尼努；","notes":[]},{"n":14,"t":"又有民的首領，就是巴錄、巴哈‧摩押、以攔、薩土、巴尼、","notes":[]},{"n":15,"t":"布尼、押甲、比拜、","notes":[]},{"n":16,"t":"亞多尼雅、比革瓦伊、亞丁、","notes":[]},{"n":17,"t":"亞特、希西家、押朔、","notes":[]},{"n":18,"t":"荷第雅、哈順、比賽、","notes":[]},{"n":19,"t":"哈拉、亞拿突、尼拜、","notes":[]},{"n":20,"t":"抹比押、米書蘭、希悉、","notes":[]},{"n":21,"t":"米示薩別、撒督、押杜亞、","notes":[]},{"n":22,"t":"毗拉提、哈難、亞奈雅、","notes":[]},{"n":23,"t":"何細亞、哈拿尼雅、哈述、","notes":[]},{"n":24,"t":"哈羅黑、毗利哈、朔百、","notes":[]},{"n":25,"t":"利宏、哈沙拿、瑪西雅、","notes":[]},{"n":26,"t":"亞希雅、哈難、亞難、","notes":[]},{"n":27,"t":"瑪鹿、哈琳、巴拿。","notes":[]},{"n":28,"t":"其餘的民、祭司、利未人、守門的、歌唱的、尼提寧，和一切離絕鄰邦居民歸服神律法的，並他們的妻子、兒女，凡有知識能明白的，","notes":[],"heads":["公約的內容"]},{"n":29,"t":"都隨從他們貴冑的弟兄，發咒起誓，必遵行神藉他僕人摩西所傳的律法，謹守遵行耶和華－我們主的一切誡命、典章、律例；","notes":[]},{"n":30,"t":"並不將我們的女兒嫁給這地的居民，也不為我們的兒子娶他們的女兒。","notes":[]},{"n":31,"t":"這地的居民若在安息日，或甚麼聖日，帶了貨物或糧食來賣給我們，我們必不買。每逢第七年必不耕種，凡欠我們債的必不追討。","notes":[]},{"n":32,"t":"我們又為自己定例，每年各人捐銀一舍客勒三分之一，為我們神殿的使用，","notes":[]},{"n":33,"t":"就是為陳設餅、常獻的素祭，和燔祭，安息日、月朔、節期所獻的與聖物，並以色列人的贖罪祭，以及我們神殿裏一切的費用。","notes":[]},{"n":34,"t":"我們的祭司、利未人，和百姓都掣籤，看每年是哪一族按定期將獻祭的柴奉到我們神的殿裏，照著律法上所寫的，燒在耶和華－我們神的壇上。","notes":[]},{"n":35,"t":"又定每年將我們地上初熟的土產和各樣樹上初熟的果子都奉到耶和華的殿裏。","notes":[]},{"n":36,"t":"又照律法上所寫的，將我們頭胎的兒子和首生的牛羊都奉到我們神的殿，交給我們神殿裏供職的祭司；","notes":[]},{"n":37,"t":"並將初熟之麥子所磨的麵和舉祭、各樣樹上初熟的果子、新酒與油奉給祭司，收在我們神殿的庫房裏，把我們地上所產的十分之一奉給利未人，因利未人在我們一切城邑的土產中當取十分之一。","notes":[]},{"n":38,"t":"利未人取十分之一的時候，亞倫的子孫中，當有一個祭司與利未人同在。利未人也當從十分之一中取十分之一，奉到我們神殿的屋子裏，收在庫房中。","notes":[]},{"n":39,"t":"以色列人和利未人要將五穀、新酒，和油為舉祭，奉到收存聖所器皿的屋子裏，就是供職的祭司、守門的、歌唱的所住的屋子。這樣，我們就不離棄我們神的殿。","notes":[]}]},"11":{"heading":"住在耶路撒冷的人","verses":[{"n":1,"t":"百姓的首領住在耶路撒冷。其餘的百姓掣籤，每十人中使一人來住在聖城耶路撒冷，那九人住在別的城邑。","notes":[]},{"n":2,"t":"凡甘心樂意住在耶路撒冷的，百姓都為他們祝福。","notes":[]},{"n":3,"t":"以色列人、祭司、利未人、尼提寧，和所羅門僕人的後裔都住在猶大城邑，各在自己的地業中。本省的首領住在耶路撒冷的記在下面：","notes":[]},{"n":4,"t":"其中有些猶大人和便雅憫人。猶大人中有法勒斯的子孫、烏西雅的兒子亞他雅。烏西雅是撒迦利雅的兒子；撒迦利雅是亞瑪利雅的兒子；亞瑪利雅是示法提雅的兒子；示法提雅是瑪勒列的兒子。","notes":[]},{"n":5,"t":"又有巴錄的兒子瑪西雅。巴錄是谷何西的兒子；谷何西是哈賽雅的兒子；哈賽雅是亞大雅的兒子；亞大雅是約雅立的兒子；約雅立是撒迦利雅的兒子；撒迦利雅是示羅尼的兒子。","notes":[]},{"n":6,"t":"住在耶路撒冷、法勒斯的子孫共四百六十八名，都是勇士。","notes":[]},{"n":7,"t":"便雅憫人中有米書蘭的兒子撒路。米書蘭是約葉的兒子；約葉是毗大雅的兒子；毗大雅是哥賴雅的兒子；哥賴雅是瑪西雅的兒子；瑪西雅是以鐵的兒子；以鐵是耶篩亞的兒子。","notes":[]},{"n":8,"t":"其次有迦拜、撒來的子孫，共九百二十八名。","notes":[]},{"n":9,"t":"細基利的兒子約珥是他們的長官。哈西努亞的兒子猶大是耶路撒冷的副官。","notes":[]},{"n":10,"t":"祭司中有雅斤，又有約雅立的兒子耶大雅；","notes":[]},{"n":11,"t":"還有管理神殿的西萊雅。西萊雅是希勒家的兒子；希勒家是米書蘭的兒子；米書蘭是撒督的兒子；撒督是米拉約的兒子；米拉約是亞希突的兒子。","notes":[]},{"n":12,"t":"還有他們的弟兄在殿裏供職的，共八百二十二名；又有耶羅罕的兒子亞大雅。耶羅罕是毗拉利的兒子；毗拉利是暗洗的兒子；暗洗是撒迦利亞的兒子；撒迦利亞是巴施戶珥的兒子；巴施戶珥是瑪基雅的兒子。","notes":[]},{"n":13,"t":"還有他的弟兄作族長的，二百四十二名；又有亞薩列的兒子亞瑪帥。亞薩列是亞哈賽的兒子；亞哈賽是米實利末的兒子；米實利末是音麥的兒子。","notes":[]},{"n":14,"t":"還有他們弟兄、大能的勇士共一百二十八名。哈基多琳的兒子撒巴第業是他們的長官。","notes":[]},{"n":15,"t":"利未人中有哈述的兒子示瑪雅。哈述是押利甘的兒子；押利甘是哈沙比雅的兒子；哈沙比雅是布尼的兒子。","notes":[]},{"n":16,"t":"又有利未人的族長沙比太和約撒拔管理神殿的外事。","notes":[]},{"n":17,"t":"祈禱的時候，為稱謝領首的是米迦的兒子瑪他尼。米迦是撒底的兒子；撒底是亞薩的兒子；又有瑪他尼弟兄中的八布迦為副。還有沙母亞的兒子押大。沙母亞是加拉的兒子；加拉是耶杜頓的兒子。","notes":[]},{"n":18,"t":"在聖城的利未人共二百八十四名。","notes":[]},{"n":19,"t":"守門的是亞谷和達們，並守門的弟兄，共一百七十二名。","notes":[]},{"n":20,"t":"其餘的以色列人、祭司、利未人都住在猶大的一切城邑，各在自己的地業中。","notes":[]},{"n":21,"t":"尼提寧卻住在俄斐勒；西哈和基斯帕管理他們。","notes":[]},{"n":22,"t":"在耶路撒冷、利未人的長官，管理神殿事務的是歌唱者亞薩的子孫、巴尼的兒子烏西。巴尼是哈沙比雅的兒子；哈沙比雅是瑪他尼的兒子；瑪他尼是米迦的兒子。","notes":[]},{"n":23,"t":"王為歌唱的出命令，每日供給他們必有一定之糧。","notes":[]},{"n":24,"t":"猶大兒子謝拉的子孫、米示薩別的兒子毗他希雅輔助王辦理猶大民的事。","notes":[]},{"n":25,"t":"至於村莊和屬村莊的田地，有猶大人住在基列‧亞巴和屬基列‧亞巴的鄉村；底本和屬底本的鄉村；葉甲薛和屬葉甲薛的村莊；","notes":[],"heads":["居住其他城鎮的人"]},{"n":26,"t":"耶書亞、摩拉大、伯‧帕列、","notes":[]},{"n":27,"t":"哈薩‧書亞、別是巴，和屬別是巴的鄉村；","notes":[]},{"n":28,"t":"洗革拉、米哥拿，和屬米哥拿的鄉村；","notes":[]},{"n":29,"t":"音‧臨門、瑣拉、耶末、","notes":[]},{"n":30,"t":"撒挪亞、亞杜蘭，和屬這兩處的村莊；拉吉和屬拉吉的田地；亞西加和屬亞西加的鄉村。他們所住的地方是從別是巴直到欣嫩谷。","notes":[]},{"n":31,"t":"便雅憫人從迦巴起，住在密抹、亞雅、伯特利和屬伯特利的鄉村。","notes":[]},{"n":32,"t":"亞拿突、挪伯、亞難雅、","notes":[]},{"n":33,"t":"夏瑣、拉瑪、基他音、","notes":[]},{"n":34,"t":"哈疊、洗編、尼八拉、","notes":[]},{"n":35,"t":"羅德、阿挪、匠人之谷。","notes":[]},{"n":36,"t":"利未人中有幾班曾住在猶大地歸於便雅憫的。","notes":[]}]},"12":{"heading":"祭司和利未人的名單","verses":[{"n":1,"t":"同著撒拉鐵的兒子所羅巴伯和耶書亞回來的祭司與利未人記在下面：祭司是西萊雅、耶利米、以斯拉、","notes":[]},{"n":2,"t":"亞瑪利雅、瑪鹿、哈突、","notes":[]},{"n":3,"t":"示迦尼、利宏、米利末、","notes":[]},{"n":4,"t":"易多、近頓、亞比雅、","notes":[]},{"n":5,"t":"米雅民、瑪底雅、璧迦、","notes":[]},{"n":6,"t":"示瑪雅、約雅立、耶大雅、","notes":[]},{"n":7,"t":"撒路、亞木、希勒家、耶大雅。這些人在耶書亞的時候作祭司和他們弟兄的首領。","notes":[]},{"n":8,"t":"利未人是耶書亞、賓內、甲篾、示利比、猶大、瑪他尼。這瑪他尼和他的弟兄管理稱謝的事。","notes":[]},{"n":9,"t":"他們的弟兄八布迦和烏尼照自己的班次與他們相對。","notes":[]},{"n":10,"t":"耶書亞生約雅金；約雅金生以利亞實；以利亞實生耶何耶大；","notes":[],"heads":["大祭司耶書亞的後代"]},{"n":11,"t":"耶何耶大生約拿單；約拿單生押杜亞。","notes":[]},{"n":12,"t":"在約雅金的時候，祭司作族長的西萊雅族有米拉雅；耶利米族有哈拿尼雅；","notes":["或譯：班；本段同"],"heads":["作族長的祭司"]},{"n":13,"t":"以斯拉族有米書蘭；亞瑪利雅族有約哈難；","notes":[]},{"n":14,"t":"米利古族有約拿單；示巴尼族有約瑟；","notes":[]},{"n":15,"t":"哈琳族有押拿；米拉約族有希勒愷；","notes":[]},{"n":16,"t":"易多族有撒迦利亞；近頓族有米書蘭；","notes":[]},{"n":17,"t":"亞比雅族有細基利；米拿民族某；摩亞底族有毗勒太；","notes":[]},{"n":18,"t":"璧迦族有沙母亞；示瑪雅族有約拿單；","notes":[]},{"n":19,"t":"約雅立族有瑪特乃；耶大雅族有烏西；","notes":[]},{"n":20,"t":"撒來族有加萊；亞木族有希伯；","notes":[]},{"n":21,"t":"希勒家族有哈沙比雅；耶大雅族有拿坦業。","notes":[]},{"n":22,"t":"至於利未人，當以利亞實、耶何耶大、約哈難、押杜亞的時候，他們的族長記在冊上。波斯王大流士在位的時候，作族長的祭司也記在冊上。","notes":[],"heads":["祭司和利未家族的記錄"]},{"n":23,"t":"利未人作族長的記在歷史上，直到以利亞實的兒子約哈難的時候。","notes":[]},{"n":24,"t":"利未人的族長是哈沙比雅、示利比、甲篾的兒子耶書亞，與他們弟兄的班次相對，照著神人大衛的命令一班一班地讚美稱謝。","notes":[],"heads":["聖殿供職的班次"]},{"n":25,"t":"瑪他尼、八布迦、俄巴底亞、米書蘭、達們、亞谷是守門的，就是在庫房那裏守門。","notes":[]},{"n":26,"t":"這都是在約撒達的孫子、耶書亞的兒子約雅金和省長尼希米，並祭司文士以斯拉的時候，有職任的。","notes":[]},{"n":27,"t":"耶路撒冷城牆告成的時候，眾民就把各處的利未人招到耶路撒冷，要稱謝、歌唱、敲鈸、鼓瑟、彈琴，歡歡喜喜地行告成之禮。","notes":[],"heads":["城牆落成時尼希米行奉獻之禮"]},{"n":28,"t":"歌唱的人從耶路撒冷的周圍和尼陀法的村莊與伯‧吉甲，又從迦巴和押瑪弗的田地聚集，因為歌唱的人在耶路撒冷四圍為自己立了村莊。","notes":[],"end":29},{"n":30,"t":"祭司和利未人就潔淨自己，也潔淨百姓和城門，並城牆。","notes":[]},{"n":31,"t":"我帶猶大的首領上城，使稱謝的人分為兩大隊，排列而行：第一隊在城上往右邊向糞廠門行走，","notes":[]},{"n":32,"t":"在他們後頭的有何沙雅與猶大首領的一半，","notes":[]},{"n":33,"t":"又有亞撒利雅、以斯拉、米書蘭、","notes":[]},{"n":34,"t":"猶大、便雅憫、示瑪雅、耶利米。","notes":[]},{"n":35,"t":"還有些吹號之祭司的子孫，約拿單的兒子撒迦利亞。約拿單是示瑪雅的兒子；示瑪雅是瑪他尼的兒子；瑪他尼是米該亞的兒子；米該亞是撒刻的兒子；撒刻是亞薩的兒子；","notes":[]},{"n":36,"t":"又有撒迦利亞的弟兄示瑪雅、亞撒利、米拉萊、基拉萊、瑪艾、拿坦業、猶大、哈拿尼，都拿著神人大衛的樂器，文士以斯拉引領他們。","notes":[]},{"n":37,"t":"他們經過泉門往前，從大衛城的臺階隨地勢而上，在大衛宮殿以上，直行到朝東的水門。","notes":[]},{"n":38,"t":"第二隊稱謝的人要與那一隊相迎而行。我和民的一半跟隨他們，在城牆上過了爐樓，直到寬牆；","notes":[]},{"n":39,"t":"又過了以法蓮門、古門、魚門、哈楠業樓、哈米亞樓，直到羊門，就在護衛門站住。","notes":[]},{"n":40,"t":"於是，這兩隊稱謝的人連我和官長的一半，站在神的殿裏。","notes":[]},{"n":41,"t":"還有祭司以利亞金、瑪西雅、米拿民、米該亞、以利約乃、撒迦利亞、哈楠尼亞吹號；","notes":[]},{"n":42,"t":"又有瑪西雅、示瑪雅、以利亞撒、烏西、約哈難、瑪基雅、以攔，和以謝奏樂。歌唱的就大聲歌唱，伊斯拉希雅管理他們。","notes":[]},{"n":43,"t":"那日，眾人獻大祭而歡樂；因為神使他們大大歡樂，連婦女帶孩童也都歡樂，甚至耶路撒冷中的歡聲聽到遠處。","notes":[]},{"n":44,"t":"當日，派人管理庫房，將舉祭、初熟之物和所取的十分之一，就是按各城田地，照律法所定歸給祭司和利未人的分，都收在裏頭。猶大人因祭司和利未人供職，就歡樂了。","notes":[],"heads":["聖殿的各種職責"]},{"n":45,"t":"祭司利未人遵守神所吩咐的，並守潔淨的禮。歌唱的、守門的，照著大衛和他兒子所羅門的命令也如此行。","notes":[]},{"n":46,"t":"古時，在大衛和亞薩的日子，有歌唱的伶長，並有讚美稱謝神的詩歌。","notes":[]},{"n":47,"t":"當所羅巴伯和尼希米的時候，以色列眾人將歌唱的、守門的，每日所當得的分供給他們，又給利未人當得的分；利未人又給亞倫的子孫當得的分。","notes":[]}]},"13":{"heading":"與外邦人隔離","verses":[{"n":1,"t":"當日，人念摩西的律法書給百姓聽，遇見書上寫著說，亞捫人和摩押人永不可入神的會；","notes":[]},{"n":2,"t":"因為他們沒有拿食物和水來迎接以色列人，且雇了巴蘭咒詛他們，但我們的神使那咒詛變為祝福。","notes":[]},{"n":3,"t":"以色列民聽見這律法，就與一切閒雜人絕交。","notes":[]},{"n":4,"t":"先是蒙派管理我們神殿中庫房的祭司以利亞實與多比雅結親，","notes":[],"heads":["尼希米的改革"]},{"n":5,"t":"便為他預備一間大屋子，就是從前收存素祭、乳香、器皿，和照命令供給利未人、歌唱的、守門的五穀、新酒，和油的十分之一，並歸祭司舉祭的屋子。","notes":[]},{"n":6,"t":"那時我不在耶路撒冷；因為巴比倫王亞達薛西三十二年，我回到王那裏。過了多日，我向王告假。","notes":[]},{"n":7,"t":"我來到耶路撒冷，就知道以利亞實為多比雅在神殿的院內預備屋子的那件惡事。","notes":[]},{"n":8,"t":"我甚惱怒，就把多比雅的一切家具從屋裏都拋出去，","notes":[]},{"n":9,"t":"吩咐人潔淨這屋子，遂將神殿的器皿和素祭、乳香又搬進去。","notes":[]},{"n":10,"t":"我見利未人所當得的分無人供給他們，甚至供職的利未人與歌唱的俱各奔回自己的田地去了。","notes":[]},{"n":11,"t":"我就斥責官長說：「為何離棄神的殿呢？」我便招聚利未人，使他們照舊供職。","notes":[]},{"n":12,"t":"猶大眾人就把五穀、新酒，和油的十分之一送入庫房。","notes":[]},{"n":13,"t":"我派祭司示利米雅、文士撒督，和利未人毗大雅作庫官管理庫房；副官是哈難。哈難是撒刻的兒子；撒刻是瑪他尼的兒子。這些人都是忠信的，他們的職分是將所供給的分給他們的弟兄。","notes":[]},{"n":14,"t":"我的神啊，求你因這事記念我，不要塗抹我為神的殿與其中的禮節所行的善。","notes":[]},{"n":15,"t":"那些日子，我在猶大見有人在安息日醡酒，搬運禾捆馱在驢上，又把酒、葡萄、無花果，和各樣的擔子在安息日擔入耶路撒冷，我就在他們賣食物的那日警戒他們。","notes":["原文是踹酒醡"]},{"n":16,"t":"又有泰爾人住在耶路撒冷；他們把魚和各樣貨物運進來，在安息日賣給猶大人。","notes":[]},{"n":17,"t":"我就斥責猶大的貴冑說：「你們怎麼行這惡事犯了安息日呢？","notes":[]},{"n":18,"t":"從前你們列祖豈不是這樣行，以致我們神使一切災禍臨到我們和這城嗎？現在你們還犯安息日，使忿怒越發臨到以色列！」","notes":[]},{"n":19,"t":"在安息日的前一日，耶路撒冷城門有黑影的時候，我就吩咐人將門關鎖，不過安息日不准開放。我又派我幾個僕人管理城門，免得有人在安息日擔甚麼擔子進城。","notes":[]},{"n":20,"t":"於是商人和販賣各樣貨物的，一兩次住宿在耶路撒冷城外。","notes":[]},{"n":21,"t":"我就警戒他們說：「你們為何在城外住宿呢？若再這樣，我必下手拿辦你們。」從此以後，他們在安息日不再來了。","notes":[]},{"n":22,"t":"我吩咐利未人潔淨自己，來守城門，使安息日為聖。我的神啊，求你因這事記念我，照你的大慈愛憐恤我。","notes":[]},{"n":23,"t":"那些日子，我也見猶大人娶了亞實突、亞捫、摩押的女子為妻。","notes":[]},{"n":24,"t":"他們的兒女說話，一半是亞實突的話，不會說猶大的話，所說的是照著各族的方言。","notes":[]},{"n":25,"t":"我就斥責他們，咒詛他們，打了他們幾個人，拔下他們的頭髮，叫他們指著神起誓，必不將自己的女兒嫁給外邦人的兒子，也不為自己和兒子娶他們的女兒。","notes":[]},{"n":26,"t":"我又說：「以色列王所羅門不是在這樣的事上犯罪嗎？在多國中並沒有一王像他，且蒙他神所愛，神立他作以色列全國的王；然而連他也被外邦女子引誘犯罪。","notes":[]},{"n":27,"t":"如此，我豈聽你們行這大惡，娶外邦女子干犯我們的神呢？」","notes":[]},{"n":28,"t":"大祭司以利亞實的孫子、耶何耶大的一個兒子是和倫人參巴拉的女婿，我就從我這裏把他趕出去。","notes":[]},{"n":29,"t":"我的神啊，求你記念他們的罪；因為他們玷污了祭司的職任，違背你與祭司利未人所立的約。","notes":[]},{"n":30,"t":"這樣，我潔淨他們，使他們離絕一切外邦人，派定祭司和利未人的班次，使他們各盡其職。","notes":[]},{"n":31,"t":"我又派百姓按定期獻柴和初熟的土產。我的神啊，求你記念我，施恩與我。","notes":[]}]}},"EST":{"1":{"heading":"亞哈隨魯王廢瓦實提王后","verses":[{"n":1,"t":"亞哈隨魯作王，從印度直到古實，統管一百二十七省。","notes":[]},{"n":2,"t":"亞哈隨魯王在書珊城的宮登基；","notes":[]},{"n":3,"t":"在位第三年，為他一切首領臣僕設擺筵席，有波斯和米底亞的權貴，就是各省的貴冑與首領，在他面前。","notes":[]},{"n":4,"t":"他把他榮耀之國的豐富和他美好威嚴的尊貴給他們看了許多日，就是一百八十日。","notes":[]},{"n":5,"t":"這日子滿了，又為所有住書珊城的大小人民在御園的院子裏設擺筵席七日。","notes":[]},{"n":6,"t":"有白色、綠色、藍色的帳子，用細麻繩、紫色繩從銀環內繫在白玉石柱上；有金銀的床榻擺在紅、白、黃、黑玉石的鋪石地上。","notes":[]},{"n":7,"t":"用金器皿賜酒，器皿各有不同。御酒甚多，足顯王的厚意。","notes":[]},{"n":8,"t":"喝酒有例，不准勉強人，因王吩咐宮裏的一切臣宰，讓人各隨己意。","notes":[]},{"n":9,"t":"王后瓦實提在亞哈隨魯王的宮內也為婦女設擺筵席。","notes":[]},{"n":10,"t":"第七日，亞哈隨魯王飲酒，心中快樂，就吩咐在他面前侍立的七個太監米戶幔、比斯他、哈波拿、比革他、亞拔他、西達、甲迦，","notes":[]},{"n":11,"t":"請王后瓦實提頭戴王后的冠冕到王面前，使各等臣民看她的美貌，因為她容貌甚美。","notes":[]},{"n":12,"t":"王后瓦實提卻不肯遵太監所傳的王命而來，所以王甚發怒，心如火燒。","notes":[]},{"n":13,"t":"那時，在王左右常見王面、國中坐高位的，有波斯和米底亞的七個大臣，就是甲示拿、示達、押瑪他、他施斯、米力、瑪西拿、米母干，都是達時務的明哲人。按王的常規，辦事必先詢問知例明法的人。王問他們說：","notes":[],"end":14},{"n":15,"t":"「王后瓦實提不遵太監所傳的王命，照例應當怎樣辦理呢？」","notes":[]},{"n":16,"t":"米母干在王和眾首領面前回答說：「王后瓦實提這事，不但得罪王，並且有害於王各省的臣民；","notes":[]},{"n":17,"t":"因為王后這事必傳到眾婦人的耳中，說：『亞哈隨魯王吩咐王后瓦實提到王面前，她卻不來』，她們就藐視自己的丈夫。","notes":[]},{"n":18,"t":"今日波斯和米底亞的眾夫人聽見王后這事，必向王的大臣照樣行；從此必大開藐視和忿怒之端。","notes":[]},{"n":19,"t":"王若以為美，就降旨寫在波斯和米底亞人的例中，永不更改，不准瓦實提再到王面前，將她王后的位分賜給比她還好的人。","notes":[]},{"n":20,"t":"所降的旨意傳遍通國（國度本來廣大），所有的婦人，無論丈夫貴賤都必尊敬他。」","notes":[]},{"n":21,"t":"王和眾首領都以米母干的話為美，王就照這話去行，","notes":[]},{"n":22,"t":"發詔書，用各省的文字、各族的方言通知各省，使為丈夫的在家中作主，各說本地的方言。","notes":[]}]},"2":{"heading":"以斯帖被立為王后","verses":[{"n":1,"t":"這事以後，亞哈隨魯王的忿怒止息，就想念瓦實提和她所行的，並怎樣降旨辦她。","notes":[]},{"n":2,"t":"於是王的侍臣對王說：「不如為王尋找美貌的處女。","notes":[]},{"n":3,"t":"王可以派官在國中的各省招聚美貌的處女到書珊城的女院，交給掌管女子的太監希該，給她們當用的香品。","notes":["或譯：宮"]},{"n":4,"t":"王所喜愛的女子可以立為王后，代替瓦實提。」王以這事為美，就如此行。","notes":[]},{"n":5,"t":"書珊城有一個猶大人，名叫末底改，是便雅憫人基士的曾孫，示每的孫子，睚珥的兒子。","notes":[]},{"n":6,"t":"從前巴比倫王尼布甲尼撒將猶大王耶哥尼雅和百姓從耶路撒冷擄去，末底改也在其內。","notes":["又名約雅斤"]},{"n":7,"t":"末底改撫養他叔叔的女兒哈大沙（後名以斯帖），因為她沒有父母。這女子又容貌俊美；她父母死了，末底改就收她為自己的女兒。","notes":[]},{"n":8,"t":"王的諭旨傳出，就招聚許多女子到書珊城，交給掌管女子的希該；以斯帖也送入王宮，交付希該。","notes":[]},{"n":9,"t":"希該喜悅以斯帖，就恩待她，急忙給她需用的香品和她所當得的分，又派所當得的七個宮女服事她，使她和她的宮女搬入女院上好的房屋。","notes":[]},{"n":10,"t":"以斯帖未曾將籍貫宗族告訴人，因為末底改囑咐她不可叫人知道。","notes":[]},{"n":11,"t":"末底改天天在女院前邊行走，要知道以斯帖平安不平安，並後事如何。","notes":[]},{"n":12,"t":"眾女子照例先潔淨身體十二個月：六個月用沒藥油，六個月用香料和潔身之物。滿了日期，然後挨次進去見亞哈隨魯王。","notes":[]},{"n":13,"t":"女子進去見王是這樣：從女院到王宮的時候，凡她所要的都必給她。","notes":[]},{"n":14,"t":"晚上進去，次日回到女子第二院，交給掌管妃嬪的太監沙甲；除非王喜愛她，再提名召她，就不再進去見王。","notes":[]},{"n":15,"t":"末底改叔叔亞比孩的女兒，就是末底改收為自己女兒的以斯帖，按次序當進去見王的時候，除了掌管女子的太監希該所派定給她的，她別無所求。凡看見以斯帖的都喜悅她。","notes":[]},{"n":16,"t":"亞哈隨魯王第七年十月，就是提別月，以斯帖被引入宮見王。","notes":[]},{"n":17,"t":"王愛以斯帖過於愛眾女，她在王眼前蒙寵愛比眾處女更甚。王就把王后的冠冕戴在她頭上，立她為王后，代替瓦實提。","notes":[]},{"n":18,"t":"王因以斯帖的緣故給眾首領和臣僕設擺大筵席，又豁免各省的租稅，並照王的厚意大頒賞賜。","notes":[]},{"n":19,"t":"第二次招聚處女的時候，末底改坐在朝門。","notes":[],"heads":["末底改救王的命"]},{"n":20,"t":"以斯帖照著末底改所囑咐的，還沒有將籍貫宗族告訴人；因為以斯帖遵*末底改的命，如撫養她的時候一樣。","notes":[]},{"n":21,"t":"當那時候，末底改坐在朝門，王的太監中有兩個守門的，辟探和提列，惱恨亞哈隨魯王，想要下手害他。","notes":[]},{"n":22,"t":"末底改知道了，就告訴王后以斯帖。以斯帖奉末底改的名，報告於王；","notes":[]},{"n":23,"t":"究察這事，果然是實，就把二人掛在木頭上，將這事在王面前寫於歷史上。","notes":[]}]},"3":{"heading":"哈曼陰謀除滅猶大人","verses":[{"n":1,"t":"這事以後，亞哈隨魯王抬舉亞甲族哈米大他的兒子哈曼，使他高升，叫他的爵位超過與他同事的一切臣宰。","notes":[]},{"n":2,"t":"在朝門的一切臣僕都跪拜哈曼，因為王如此吩咐；惟獨末底改不跪不拜。","notes":[]},{"n":3,"t":"在朝門的臣僕問末底改說：「你為何違背王的命令呢？」","notes":[]},{"n":4,"t":"他們天天勸他，他還是不聽，他們就告訴哈曼，要看末底改的事站得住站不住，因他已經告訴他們自己是猶大人。","notes":[]},{"n":5,"t":"哈曼見末底改不跪不拜，他就怒氣填胸。","notes":[]},{"n":6,"t":"他們已將末底改的本族告訴哈曼；他以為下手害末底改一人是小事，就要滅絕亞哈隨魯王通國所有的猶大人，就是末底改的本族。","notes":[]},{"n":7,"t":"亞哈隨魯王十二年正月，就是尼散月，人在哈曼面前，按日日月月掣普珥，就是掣籤，要定何月何日為吉，擇定了十二月，就是亞達月。","notes":[]},{"n":8,"t":"哈曼對亞哈隨魯王說：「有一種民散居在王國各省的民中；他們的律例與萬民的律例不同，也不守王的律例，所以容留他們與王無益。","notes":[]},{"n":9,"t":"王若以為美，請下旨意滅絕他們；我就捐一萬他連得銀子交給掌管國帑的人，納入王的府庫。」","notes":[]},{"n":10,"t":"於是王從自己手上摘下戒指給猶大人的仇敵－亞甲族哈米大他的兒子哈曼。","notes":[]},{"n":11,"t":"王對哈曼說：「這銀子仍賜給你，這民也交給你，你可以隨意待他們。」","notes":[]},{"n":12,"t":"正月十三日，就召了王的書記來，照著哈曼一切所吩咐的，用各省的文字、各族的方言，奉亞哈隨魯王的名寫旨意，傳與總督和各省的省長，並各族的首領；又用王的戒指蓋印，","notes":[]},{"n":13,"t":"交給驛卒傳到王的各省，吩咐將猶大人，無論老少婦女孩子，在一日之間，十二月，就是亞達月十三日，全然剪除，殺戮滅絕，並奪他們的財為掠物。","notes":[]},{"n":14,"t":"抄錄這旨意，頒行各省，宣告各族，使他們預備等候那日。","notes":[]},{"n":15,"t":"驛卒奉王命急忙起行，旨意也傳遍書珊城。王同哈曼坐下飲酒，書珊城的民卻都慌亂。","notes":[]}]},"4":{"heading":"末底改求以斯帖幫忙","verses":[{"n":1,"t":"末底改知道所做的這一切事，就撕裂衣服，穿麻衣，蒙灰塵，在城中行走，痛哭哀號。","notes":[]},{"n":2,"t":"到了朝門前停住腳步，因為穿麻衣的不可進朝門。","notes":[]},{"n":3,"t":"王的諭旨所到的各省各處，猶大人大大悲哀，禁食哭泣哀號，穿麻衣躺在灰中的甚多。","notes":[]},{"n":4,"t":"王后以斯帖的宮女和太監來把這事告訴以斯帖，她甚是憂愁，就送衣服給末底改穿，要他脫下麻衣，他卻不受。","notes":[]},{"n":5,"t":"以斯帖就把王所派伺候她的一個太監，名叫哈他革召來，吩咐他去見末底改，要知道這是甚麼事，是甚麼緣故。","notes":[]},{"n":6,"t":"於是哈他革出到朝門前的寬闊處見末底改。","notes":[]},{"n":7,"t":"末底改將自己所遇的事，並哈曼為滅絕猶大人應許捐入王庫的銀數都告訴了他；","notes":[]},{"n":8,"t":"又將所抄寫傳遍書珊城要滅絕猶大人的旨意交給哈他革，要給以斯帖看，又要給她說明，並囑咐她進去見王，為本族的人在王面前懇切祈求。","notes":[]},{"n":9,"t":"哈他革回來，將末底改的話告訴以斯帖；","notes":[]},{"n":10,"t":"以斯帖就吩咐哈他革去見末底改，說：","notes":[]},{"n":11,"t":"「王的一切臣僕和各省的人民都知道有一個定例：若不蒙召，擅入內院見王的，無論男女必被治死；除非王向他伸出金杖，不得存活。現在我沒有蒙召進去見王已經三十日了。」","notes":[]},{"n":12,"t":"人就把以斯帖這話告訴末底改。","notes":[]},{"n":13,"t":"末底改託人回覆以斯帖說：「你莫想在王宮裏強過一切猶大人，得免這禍。","notes":[]},{"n":14,"t":"此時你若閉口不言，猶大人必從別處得解脫，蒙拯救；你和你父家必致滅亡。焉知你得了王后的位分不是為現今的機會嗎？」","notes":[]},{"n":15,"t":"以斯帖就吩咐人回報末底改說：","notes":[]},{"n":16,"t":"「你當去招聚書珊城所有的猶大人，為我禁食三晝三夜，不吃不喝；我和我的宮女也要這樣禁食。然後我違例進去見王，我若死就死吧！」","notes":[]},{"n":17,"t":"於是末底改照以斯帖一切所吩咐的去行。","notes":[]}]},"5":{"heading":"以斯帖為王和哈曼設筵席","verses":[{"n":1,"t":"第三日，以斯帖穿上朝服，進王宮的內院，對殿站立。王在殿裏坐在寶座上，對著殿門。","notes":[]},{"n":2,"t":"王見王后以斯帖站在院內，就施恩於她，向她伸出手中的金杖；以斯帖便向前摸杖頭。","notes":[]},{"n":3,"t":"王對她說：「王后以斯帖啊，你要甚麼？你求甚麼，就是國的一半也必賜給你。」","notes":[]},{"n":4,"t":"以斯帖說：「王若以為美，就請王帶著哈曼今日赴我所預備的筵席。」","notes":[]},{"n":5,"t":"王說：「叫哈曼速速照以斯帖的話去行。」於是王帶著哈曼赴以斯帖所預備的筵席。","notes":[]},{"n":6,"t":"在酒席筵前，王又問以斯帖說：「你要甚麼，我必賜給你；你求甚麼，就是國的一半也必為你成就。」","notes":[]},{"n":7,"t":"以斯帖回答說：「我有所要，我有所求。","notes":[]},{"n":8,"t":"我若在王眼前蒙恩，王若願意賜我所要的，准我所求的，就請王帶著哈曼再赴我所要預備的筵席。明日我必照王所問的說明。」","notes":[]},{"n":9,"t":"那日哈曼心中快樂，歡歡喜喜地出來；但見末底改在朝門不站起來，連身也不動，就滿心惱怒末底改。","notes":[],"heads":["哈曼陰謀殺末底改"]},{"n":10,"t":"哈曼暫且忍耐回家，叫人請他朋友和他妻子細利斯來。","notes":[]},{"n":11,"t":"哈曼將他富厚的榮耀、眾多的兒女，和王抬舉他使他超乎首領臣僕之上，都述說給他們聽。","notes":[]},{"n":12,"t":"哈曼又說：「王后以斯帖預備筵席，除了我之外不許別人隨王赴席。明日王后又請我隨王赴席；","notes":[]},{"n":13,"t":"只是我見猶大人末底改坐在朝門，雖有這一切榮耀，也與我無益。」","notes":[]},{"n":14,"t":"他的妻細利斯和他一切的朋友對他說：「不如立一個五丈高的木架，明早求王將末底改掛在其上，然後你可以歡歡喜喜地隨王赴席。」哈曼以這話為美，就叫人做了木架。","notes":[]}]},"6":{"heading":"王賜末底改榮譽","verses":[{"n":1,"t":"那夜王睡不著覺，就吩咐人取歷史來，念給他聽。","notes":[]},{"n":2,"t":"正遇見書上寫著說：王的太監中有兩個守門的，辟探和提列，想要下手害亞哈隨魯王，末底改將這事告訴王后。","notes":[]},{"n":3,"t":"王說：「末底改行了這事，賜他甚麼尊榮爵位沒有？」伺候王的臣僕回答說：「沒有賜他甚麼。」","notes":[]},{"n":4,"t":"王說：「誰在院子裏？」（那時哈曼正進王宮的外院，要求王將末底改掛在他所預備的木架上。）","notes":[]},{"n":5,"t":"臣僕說：「哈曼站在院內。」王說：「叫他進來。」","notes":[]},{"n":6,"t":"哈曼就進去。王問他說：「王所喜悅尊榮的人，當如何待他呢？」哈曼心裏說：「王所喜悅尊榮的，不是我是誰呢？」","notes":[]},{"n":7,"t":"哈曼就回答說：「王所喜悅尊榮的，","notes":[]},{"n":8,"t":"當將王常穿的朝服和戴冠的御馬，","notes":[]},{"n":9,"t":"都交給王極尊貴的一個大臣，命他將衣服給王所喜悅尊榮的人穿上，使他騎上馬，走遍城裏的街市，在他面前宣告說：王所喜悅尊榮的人，就如此待他。」","notes":[]},{"n":10,"t":"王對哈曼說：「你速速將這衣服和馬，照你所說的，向坐在朝門的猶大人末底改去行。凡你所說的，一樣不可缺。」","notes":[]},{"n":11,"t":"於是哈曼將朝服給末底改穿上，使他騎上馬，走遍城裏的街市，在他面前宣告說：「王所喜悅尊榮的人，就如此待他。」","notes":[]},{"n":12,"t":"末底改仍回到朝門，哈曼卻憂憂悶悶地蒙著頭，急忙回家去了，","notes":[]},{"n":13,"t":"將所遇的一切事詳細說給他的妻細利斯和他的眾朋友聽。他的智慧人和他的妻細利斯對他說：「你在末底改面前始而敗落，他如果是猶大人，你必不能勝他，終必在他面前敗落。」","notes":[]},{"n":14,"t":"他們還與哈曼說話的時候，王的太監來催哈曼快去赴以斯帖所預備的筵席。","notes":[]}]},"7":{"heading":"哈曼被處死","verses":[{"n":1,"t":"王帶著哈曼來赴王后以斯帖的筵席。","notes":[]},{"n":2,"t":"這第二次在酒席筵前，王又問以斯帖說：「王后以斯帖啊，你要甚麼，我必賜給你；你求甚麼，*就是國的一半也必為你成就。」","notes":[]},{"n":3,"t":"王后以斯帖回答說：「我若在王眼前蒙恩，王若以為美，我所願的，是願王將我的性命賜給我；我所求的，是求王將我的本族賜給我。","notes":[]},{"n":4,"t":"因我和我的本族被賣了，要剪除殺戮滅絕我們。我們若被賣為奴為婢，我也閉口不言；但王的損失，敵人萬不能補足。」","notes":[]},{"n":5,"t":"亞哈隨魯王問王后以斯帖說：「擅敢起意如此行的是誰？這人在哪裏呢？」","notes":[]},{"n":6,"t":"以斯帖說：「仇人敵人就是這惡人哈曼！」哈曼在王和王后面前就甚驚惶。","notes":[]},{"n":7,"t":"王便大怒，起來離開酒席往御園去了。哈曼見王定意要加罪與他，就起來，求王后以斯帖救命。","notes":[]},{"n":8,"t":"王從御園回到酒席之處，見哈曼伏在以斯帖所靠的榻上；王說：「他竟敢在宮內、在我面前凌辱王后嗎？」這話一出王口，人就蒙了哈曼的臉。","notes":[]},{"n":9,"t":"伺候王的一個太監名叫哈波拿，說：「哈曼為那救王有功的末底改做了五丈高的木架，現今立在哈曼家裏。」王說：「把哈曼掛在其上。」","notes":[]},{"n":10,"t":"於是人將哈曼掛在他為末底改所預備的木架上。王的忿怒這才止息。","notes":[]}]},"8":{"heading":"猶大人的反擊","verses":[{"n":1,"t":"當日，亞哈隨魯王把猶大人仇敵哈曼的家產賜給王后以斯帖。末底改也來到王面前，因為以斯帖已經告訴王，末底改是她的親屬。","notes":[]},{"n":2,"t":"王摘下自己的戒指，就是從哈曼追回的，給了末底改。以斯帖派末底改管理哈曼的家產。","notes":[]},{"n":3,"t":"以斯帖又俯伏在王腳前，流淚哀告，求他除掉亞甲族哈曼害猶大人的惡謀。","notes":[]},{"n":4,"t":"王向以斯帖伸出金杖；以斯帖就起來，站在王前，","notes":[]},{"n":5,"t":"說：「亞甲族哈米大他的兒子哈曼設謀傳旨，要殺滅在王各省的猶大人。現今王若願意，我若在王眼前蒙恩，王若以為美，若喜悅我，請王另下旨意，廢除哈曼所傳的那旨意。","notes":[]},{"n":6,"t":"我何忍見我本族的人受害？何忍見我同宗的人被滅呢？」","notes":[]},{"n":7,"t":"亞哈隨魯王對王后以斯帖和猶大人末底改說：「因哈曼要下手害猶大人，我已將他的家產賜給以斯帖，人也將哈曼掛在木架上。","notes":[]},{"n":8,"t":"現在你們可以隨意奉王的名寫諭旨給猶大人，用王的戒指蓋印；因為奉王名所寫、用王戒指蓋印的諭旨，人都不能廢除。」","notes":[]},{"n":9,"t":"三月，就是西彎月二十三日，將王的書記召來，按著末底改所吩咐的，用各省的文字、各族的方言，並猶大人的文字方言寫諭旨，傳給那從印度直到古實一百二十七省的猶大人和總督省長首領。","notes":[]},{"n":10,"t":"末底改奉亞哈隨魯王的名寫諭旨，用王的戒指蓋印，交給騎御馬圈快馬的驛卒，傳到各處。","notes":[]},{"n":11,"t":"諭旨中，王准各省各城的猶大人在一日之間，十二月，就是亞達月十三日，聚集保護性命，剪除殺戮滅絕那要攻擊猶大人的一切仇敵和他們的妻子兒女，奪取他們的財為掠物。","notes":[],"end":12},{"n":13,"t":"抄錄這諭旨，頒行各省，宣告各族，使猶大人預備等候那日，在仇敵身上報仇。","notes":[]},{"n":14,"t":"於是騎快馬的驛卒被王命催促，急忙起行；諭旨也傳遍書珊城。","notes":[]},{"n":15,"t":"末底改穿著藍色白色的朝服，頭戴大金冠冕，又穿紫色細麻布的外袍，從王面前出來；書珊城的人民都歡呼快樂。","notes":[]},{"n":16,"t":"猶大人有光榮，歡喜快樂而得尊貴。","notes":[]},{"n":17,"t":"王的諭旨所到的各省各城，猶大人都歡喜快樂，設擺筵宴，以那日為吉日。那國的人民，有許多因懼怕猶大人，就入了猶大籍。","notes":[]}]},"9":{"heading":"猶大人除滅他們的仇敵","verses":[{"n":1,"t":"十二月，乃亞達月十三日，王的諭旨將要舉行，就是猶大人的仇敵盼望轄制他們的日子，猶大人反倒轄制恨他們的人。","notes":[]},{"n":2,"t":"猶大人在亞哈隨魯王各省的城裏聚集，下手擊殺那要害他們的人。無人能敵擋他們，因為各族都懼怕他們。","notes":[]},{"n":3,"t":"各省的首領、總督、省長，和辦理王事的人，因懼怕末底改，就都幫助猶大人。","notes":[]},{"n":4,"t":"末底改在朝中為大，名聲傳遍各省，日漸昌盛。","notes":[]},{"n":5,"t":"猶大人用刀擊殺一切仇敵，任意殺滅恨他們的人。","notes":[]},{"n":6,"t":"在書珊城，猶大人殺滅了五百人；","notes":[]},{"n":7,"t":"又殺巴珊大他、達分、亞斯帕他、","notes":[]},{"n":8,"t":"破拉他、亞大利雅、亞利大他、","notes":[]},{"n":9,"t":"帕瑪斯他、亞利賽、亞利代、瓦耶撒他；","notes":[]},{"n":10,"t":"這十人都是哈米大他的孫子、猶大人仇敵哈曼的兒子。猶大人卻沒有下手奪取財物。","notes":[]},{"n":11,"t":"當日，將書珊城被殺的人數呈在王前。","notes":[]},{"n":12,"t":"王對王后以斯帖說：「猶大人在書珊城殺滅了五百人，又殺了哈曼的十個兒子，在王的各省不知如何呢？現在你要甚麼，我必賜給你；你還求甚麼，也必為你成就。」","notes":[]},{"n":13,"t":"以斯帖說：「王若以為美，求你准書珊的猶大人，明日也照今日的旨意行，並將哈曼十個兒子的屍首掛在木架上。」","notes":[]},{"n":14,"t":"王便允准如此行。旨意傳在書珊，人就把哈曼十個兒子的屍首掛起來了。","notes":[]},{"n":15,"t":"亞達月十四日，書珊的猶大人又聚集在書珊，殺了三百人，卻沒有下手奪取財物。","notes":[]},{"n":16,"t":"在王各省其餘的猶大人也都聚集保護性命，殺了恨他們的人七萬五千，卻沒有下手奪取財物。這樣，就脫離仇敵，得享平安。","notes":[]},{"n":17,"t":"亞達月十三日，行了這事；十四日安息，以這日為設筵歡樂的日子。","notes":[]},{"n":18,"t":"但書珊的猶大人，這十三日、十四日聚集殺戮仇敵；十五日安息，以這日為設筵歡樂的日子。","notes":[]},{"n":19,"t":"所以住無城牆鄉村的猶大人，如今都以亞達月十四日為設筵歡樂的吉日，彼此餽送禮物。","notes":[]},{"n":20,"t":"末底改記錄這事，寫信與亞哈隨魯王各省遠近所有的猶大人，","notes":[],"heads":["普珥日"]},{"n":21,"t":"囑咐他們每年守亞達月十四、十五兩日，","notes":[]},{"n":22,"t":"以這月的兩日為猶大人脫離仇敵得平安、轉憂為喜、轉悲為樂的吉日。在這兩日設筵歡樂，彼此餽送禮物，賙濟窮人。","notes":[]},{"n":23,"t":"於是，猶大人按著末底改所寫與他們的信，應承照初次所守的守為永例；","notes":[]},{"n":24,"t":"是因猶大人的仇敵亞甲族哈米大他的兒子哈曼設謀殺害猶大人，掣普珥，就是掣籤，為要殺盡滅絕他們；","notes":[]},{"n":25,"t":"這事報告於王，王便降旨使哈曼謀害猶大人的惡事歸到他自己的頭上，並吩咐把他和他的眾子都掛在木架上。","notes":[]},{"n":26,"t":"照著普珥的名字，猶大人就稱這兩日為「普珥日」。他們因這信上的話，又因所看見所遇見的事，","notes":[]},{"n":27,"t":"就應承自己與後裔，並歸附他們的人，每年按時必守這兩日，永遠不廢。","notes":[]},{"n":28,"t":"各省各城、家家戶戶、世世代代紀念遵守這兩日，使這「普珥日」在猶大人中不可廢掉，在他們後裔中也不可忘記。","notes":[]},{"n":29,"t":"亞比孩的女兒－王后以斯帖和猶大人末底改以全權寫第二封信，堅囑猶大人守這「普珥日」，","notes":[]},{"n":30,"t":"用和平誠實話寫信給亞哈隨魯王國中一百二十七省所有的猶大人，","notes":[]},{"n":31,"t":"勸他們按時守這「普珥日」，禁食呼求，是照猶大人末底改和王后以斯帖所囑咐的，也照猶大人為自己與後裔所應承的。","notes":[]},{"n":32,"t":"以斯帖命定守「普珥日」，這事也記錄在書上。","notes":[]}]},"10":{"heading":"亞哈隨魯和末底改的功績","verses":[{"n":1,"t":"亞哈隨魯王使旱地和海島的人民都進貢。","notes":[]},{"n":2,"t":"他以權柄能力所行的，並他抬舉末底改使他高升的事，豈不都寫在米底亞和波斯王的歷史上嗎？","notes":[]},{"n":3,"t":"猶大人末底改作亞哈隨魯王的宰相，在猶大人中為大，得他眾弟兄的喜悅，為本族的人求好處，向他們說和平的話。","notes":[]}]}},"JOB":{"1":{"heading":"撒但試探約伯","verses":[{"n":1,"t":"烏斯地有一個人名叫約伯；那人完全正直，敬畏神，遠離惡事。","notes":[]},{"n":2,"t":"他生了七個兒子，三個女兒。","notes":[]},{"n":3,"t":"他的家產有七千羊，三千駱駝，五百對牛，五百母驢，並有許多僕婢。這人在東方人中就為至大。","notes":[]},{"n":4,"t":"他的兒子按著日子各在自己家裏設擺筵宴，就打發人去，請了他們的三個姊妹來，與他們一同吃喝。","notes":[]},{"n":5,"t":"筵宴的日子過了，約伯打發人去叫他們自潔。他清早起來，按著他們眾人的數目獻燔祭；因為他說：「恐怕我兒子犯了罪，心中棄掉神。」約伯常常這樣行。","notes":[]},{"n":6,"t":"有一天，神的眾子來侍立在耶和華面前，撒但也來在其中。","notes":[]},{"n":7,"t":"耶和華問撒但說：「你從哪裏來？」撒但回答說：「我從地上走來走去，往返而來。」","notes":[]},{"n":8,"t":"耶和華問撒但說：「你曾用心察看我的僕人約伯沒有？地上再沒有人像他完全正直，敬畏神，遠離惡事。」","notes":[]},{"n":9,"t":"撒但回答耶和華說：「約伯敬畏神，豈是無故呢？","notes":[]},{"n":10,"t":"你豈不是四面圈上籬笆圍護他和他的家，並他一切所有的嗎？他手所做的都蒙你賜福；他的家產也在地上增多。","notes":[]},{"n":11,"t":"你且伸手毀他一切所有的；他必當面棄掉你。」","notes":[]},{"n":12,"t":"耶和華對撒但說：「凡他所有的都在你手中；只是不可伸手加害於他。」於是撒但從耶和華面前退去。","notes":[]},{"n":13,"t":"有一天，約伯的兒女正在他們長兄的家裏吃飯喝酒，","notes":[],"heads":["約伯喪失兒女和財產"]},{"n":14,"t":"有報信的來見約伯，說：「牛正耕地，驢在旁邊吃草，","notes":[]},{"n":15,"t":"示巴人忽然闖來，把牲畜擄去，並用刀殺了僕人；惟有我一人逃脫，來報信給你。」","notes":[]},{"n":16,"t":"他還說話的時候，又有人來說：「神從天上降下火來，將群羊和僕人都燒滅了；惟有我一人逃脫，來報信給你。」","notes":[]},{"n":17,"t":"他還說話的時候，又有人來說：「迦勒底人分作三隊忽然闖來，把駱駝擄去，並用刀殺了僕人；惟有我一人逃脫，來報信給你。」","notes":[]},{"n":18,"t":"他還說話的時候，又有人來說：「你的兒女正在他們長兄的家裏吃飯喝酒，","notes":[]},{"n":19,"t":"不料，有狂風從曠野颳來，擊打房屋的四角，房屋倒塌在少年人身上，他們就都死了；惟有我一人逃脫，來報信給你。」","notes":[]},{"n":20,"t":"約伯便起來，撕裂外袍，剃了頭，伏在地上下拜，","notes":[]},{"n":21,"t":"說：「我赤身出於母胎，也必赤身歸回；賞賜的是耶和華，收取的也是耶和華。耶和華的名是應當稱頌的。」","notes":[]},{"n":22,"t":"在這一切的事上約伯並不犯罪，也不以神為愚妄。","notes":["或譯：也不妄評神"]}]},"2":{"heading":"撒但再試探約伯","verses":[{"n":1,"t":"又有一天，神的眾子來侍立在耶和華面前，撒但也來在其中。","notes":[]},{"n":2,"t":"耶和華問撒但說：「你從哪裏來？」撒但回答說：「我從地上走來走去，往返而來。」","notes":[]},{"n":3,"t":"耶和華問撒但說：「你曾用心察看我的僕人約伯沒有？地上再沒有人像他完全正直，敬畏神，遠離惡事。你雖激動我攻擊他，無故地毀滅他，他仍然持守他的純正。」","notes":[]},{"n":4,"t":"撒但回答耶和華說：「人以皮代皮，情願捨去一切所有的，保全性命。","notes":[]},{"n":5,"t":"你且伸手傷他的骨頭和他的肉，他必當面棄掉你。」","notes":[]},{"n":6,"t":"耶和華對撒但說：「他在你手中，只要存留他的性命。」","notes":[]},{"n":7,"t":"於是撒但從耶和華面前退去，擊打約伯，使他從腳掌到頭頂長毒瘡。","notes":[]},{"n":8,"t":"約伯就坐在爐灰中，拿瓦片刮身體。","notes":[]},{"n":9,"t":"他的妻子對他說：「你仍然持守你的純正嗎？你棄掉神，死了吧！」","notes":[]},{"n":10,"t":"約伯卻對她說：「你說話像愚頑的婦人一樣。噯！難道我們從神手裏得福，不也受禍嗎？」在這一切的事上約伯並不以口犯罪。","notes":[]},{"n":11,"t":"約伯的三個朋友－提幔人以利法、書亞人比勒達、拿瑪人瑣法－聽說有這一切的災禍臨到他身上，各人就從本處約會同來，為他悲傷，安慰他。","notes":[],"heads":["三個朋友來安慰約伯"]},{"n":12,"t":"他們遠遠地舉目觀看，認不出他來，就放聲大哭。各人撕裂外袍，把塵土向天揚起來，落在自己的頭上。","notes":[]},{"n":13,"t":"他們就同他七天七夜坐在地上，一個人也不向他說句話，因為他極其痛苦。","notes":[]}]},"3":{"heading":"約伯咒詛自己","verses":[{"n":1,"t":"此後，約伯開口咒詛自己的生日，","notes":[]},{"n":2,"t":"說：","notes":[]},{"n":3,"t":"願我生的那日和說懷了男胎的那夜都滅沒。","notes":[]},{"n":4,"t":"願那日變為黑暗；願神不從上面尋找它；願亮光不照於其上。","notes":[]},{"n":5,"t":"願黑暗和死蔭索取那日；願密雲停在其上；願日蝕恐嚇它。","notes":[]},{"n":6,"t":"願那夜被幽暗奪取，不在年中的日子同樂，也不入月中的數目。","notes":[]},{"n":7,"t":"願那夜沒有生育，其間也沒有歡樂的聲音。","notes":[]},{"n":8,"t":"願那咒詛日子且能惹動鱷魚的咒詛那夜。","notes":[]},{"n":9,"t":"願那夜黎明的星宿變為黑暗，盼亮卻不亮，也不見早晨的光線；","notes":["原文是眼皮"]},{"n":10,"t":"因沒有把懷我胎的門關閉，也沒有將患難對我的眼隱藏。","notes":[]},{"n":11,"t":"我為何不出母胎而死？為何不出母腹絕氣？","notes":[]},{"n":12,"t":"為何有膝接收我？為何有奶哺養我？","notes":[]},{"n":13,"t":"不然，我就早已躺臥安睡，","notes":[]},{"n":14,"t":"和地上為自己重造荒邱的君王、謀士，","notes":[]},{"n":15,"t":"或與有金子、將銀子裝滿了房屋的王子一同安息；","notes":[]},{"n":16,"t":"或像隱而未現、不到期而落的胎，歸於無有，如同未見光的嬰孩。","notes":[]},{"n":17,"t":"在那裏惡人止息攪擾，困乏人得享安息，","notes":[]},{"n":18,"t":"被囚的人同得安逸，不聽見督工的聲音。","notes":[]},{"n":19,"t":"大小都在那裏；奴僕脫離主人的轄制。","notes":[]},{"n":20,"t":"受患難的人為何有光賜給他呢？心中愁苦的人為何有生命賜給他呢？","notes":[]},{"n":21,"t":"他們切望死，卻不得死；求死，勝於求隱藏的珍寶。","notes":[]},{"n":22,"t":"他們尋見墳墓就快樂，極其歡喜。","notes":[]},{"n":23,"t":"人的道路既然遮隱，神又把他四面圍困，為何有光賜給他呢？","notes":[]},{"n":24,"t":"我未曾吃飯就發出歎息；我唉哼的聲音湧出如水。","notes":[]},{"n":25,"t":"因我所恐懼的臨到我身，我所懼怕的迎我而來。","notes":[]},{"n":26,"t":"我不得安逸，不得平靜，也不得安息，卻有患難來到。","notes":[]}]},"4":{"heading":"第一次對話","verses":[{"n":1,"t":"提幔人以利法回答說：","notes":[]},{"n":2,"t":"人若想與你說話，你就厭煩嗎？但誰能忍住不說呢？","notes":[]},{"n":3,"t":"你素來教導許多的人，又堅固軟弱的手。","notes":[]},{"n":4,"t":"你的言語曾扶助那將要跌倒的人；你又使軟弱的膝穩固。","notes":[]},{"n":5,"t":"但現在禍患臨到你，你就昏迷，挨近你，你便驚惶。","notes":[]},{"n":6,"t":"你的倚靠不是在你敬畏神嗎？你的盼望不是在你行事純正嗎？","notes":[]},{"n":7,"t":"請你追想：無辜的人有誰滅亡？正直的人在何處剪除？","notes":[]},{"n":8,"t":"按我所見，耕罪孽、種毒害的人都照樣收割。","notes":[]},{"n":9,"t":"神一出氣，他們就滅亡；神一發怒，他們就消沒。","notes":[]},{"n":10,"t":"獅子的吼叫和猛獅的聲音盡都止息；少壯獅子的牙齒也都敲掉。","notes":[]},{"n":11,"t":"老獅子因絕食而死；母獅之子也都離散。","notes":[]},{"n":12,"t":"我暗暗地得了默示；我耳朵也聽其細微的聲音。","notes":[]},{"n":13,"t":"在思念夜中、異象之間，世人沉睡的時候，","notes":[]},{"n":14,"t":"恐懼、戰兢臨到我身，使我百骨打戰。","notes":[]},{"n":15,"t":"有靈從我面前經過，我身上的毫毛直立。","notes":[]},{"n":16,"t":"那靈停住，我卻不能辨其形狀；有影像在我眼前。我在靜默中聽見有聲音說：","notes":[]},{"n":17,"t":"必死的人豈能比神公義嗎？人豈能比造他的主潔淨嗎？","notes":[]},{"n":18,"t":"主不信靠他的臣僕，並且指他的使者為愚昧；","notes":[]},{"n":19,"t":"何況那住在土房、根基在塵土裏、被蠹蟲所毀壞的人呢？","notes":[]},{"n":20,"t":"早晚之間，就被毀滅，永歸無有，無人理會。","notes":[]},{"n":21,"t":"他帳棚的繩索豈不從中抽出來呢？他死，且是無智慧而死。","notes":[]}]},"5":{"heading":"","verses":[{"n":1,"t":"你且呼求，有誰答應你？諸聖者之中，你轉向哪一位呢？","notes":[]},{"n":2,"t":"忿怒害死愚妄人；嫉妒殺死癡迷人。","notes":[]},{"n":3,"t":"我曾見愚妄人扎下根，但我忽然咒詛他的住處。","notes":[]},{"n":4,"t":"他的兒女遠離穩妥的地步，在城門口被壓，並無人搭救。","notes":[]},{"n":5,"t":"他的莊稼有飢餓的人吃盡了，就是在荊棘裏的也搶去了；他的財寶有網羅張口吞滅了。","notes":[]},{"n":6,"t":"禍患原不是從土中出來；患難也不是從地裏發生。","notes":[]},{"n":7,"t":"人生在世必遇患難，如同火星飛騰。","notes":[]},{"n":8,"t":"至於我，我必仰望神，把我的事情託付他。","notes":[]},{"n":9,"t":"他行大事不可測度，行奇事不可勝數：","notes":[]},{"n":10,"t":"降雨在地上，賜水於田裏；","notes":[]},{"n":11,"t":"將卑微的安置在高處，將哀痛的舉到穩妥之地；","notes":[]},{"n":12,"t":"破壞狡猾人的計謀，使他們所謀的不得成就。","notes":[]},{"n":13,"t":"他叫有智慧的中了自己的詭計，使狡詐人的計謀速速滅亡。","notes":[]},{"n":14,"t":"他們白晝遇見黑暗，午間摸索如在夜間。","notes":[]},{"n":15,"t":"神拯救窮乏人脫離他們口中的刀和強暴人的手。","notes":[]},{"n":16,"t":"這樣，貧寒的人有指望，罪孽之輩必塞口無言。","notes":[]},{"n":17,"t":"神所懲治的人是有福的！所以你不可輕看全能者的管教。","notes":[]},{"n":18,"t":"因為他打破，又纏裹；他擊傷，用手醫治。","notes":[]},{"n":19,"t":"你六次遭難，他必救你；就是七次，災禍也無法害你。","notes":[]},{"n":20,"t":"在饑荒中，他必救你脫離死亡；在爭戰中，他必救你脫離刀劍的權力。","notes":[]},{"n":21,"t":"你必被隱藏，不受口舌之害；災殃臨到，你也不懼怕。","notes":[]},{"n":22,"t":"你遇見災害饑饉，就必嬉笑；地上的野獸，你也不懼怕。","notes":[]},{"n":23,"t":"因為你必與田間的石頭立約；田裏的野獸也必與你和好。","notes":[]},{"n":24,"t":"你必知道你帳棚平安，要查看你的羊圈，一無所失；","notes":[]},{"n":25,"t":"也必知道你的後裔將來發達，你的子孫像地上的青草。","notes":[]},{"n":26,"t":"你必壽高年邁才歸墳墓，好像禾捆到時收藏。","notes":[]},{"n":27,"t":"這理，我們已經考察，本是如此。你須要聽，要知道是與自己有益。","notes":[]}]},"6":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"惟願我的煩惱稱一稱，我一切的災害放在天平裏；","notes":[]},{"n":3,"t":"現今都比海沙更重，所以我的言語急躁。","notes":[]},{"n":4,"t":"因全能者的箭射入我身；其毒，我的靈喝盡了；神的驚嚇擺陣攻擊我。","notes":[]},{"n":5,"t":"野驢有草豈能叫喚？牛有料豈能吼叫？","notes":[]},{"n":6,"t":"物淡而無鹽豈可吃嗎？蛋青有甚麼滋味呢？","notes":[]},{"n":7,"t":"看為可厭的食物，我心不肯挨近。","notes":[]},{"n":8,"t":"惟願我得著所求的，願神賜我所切望的；","notes":[]},{"n":9,"t":"就是願神把我壓碎，伸手將我剪除。","notes":[]},{"n":10,"t":"我因沒有違棄那聖者的言語，就仍以此為安慰，在不止息的痛苦中還可踴躍。","notes":[]},{"n":11,"t":"我有甚麼氣力使我等候？我有甚麼結局使我忍耐？","notes":[]},{"n":12,"t":"我的氣力豈是石頭的氣力？我的肉身豈是銅的呢？","notes":[]},{"n":13,"t":"在我豈不是毫無幫助嗎？智慧豈不是從我心中趕出淨盡嗎？","notes":[]},{"n":14,"t":"那將要灰心、離棄全能者、不敬畏神的人，他的朋友當以慈愛待他。","notes":[]},{"n":15,"t":"我的弟兄詭詐，好像溪水，又像溪水流乾的河道。","notes":[]},{"n":16,"t":"這河因結冰發黑，有雪藏在其中；","notes":[]},{"n":17,"t":"天氣漸暖就隨時消化，日頭炎熱便從原處乾涸。","notes":[]},{"n":18,"t":"結伴的客旅離棄大道，順河偏行，到荒野之地死亡。","notes":[]},{"n":19,"t":"提瑪結伴的客旅瞻望；示巴同夥的人等候。","notes":[]},{"n":20,"t":"他們因失了盼望就抱愧，來到那裏便蒙羞。","notes":[]},{"n":21,"t":"現在你們正是這樣，看見驚嚇的事便懼怕。","notes":[]},{"n":22,"t":"我豈說：請你們供給我，從你們的財物中送禮物給我？","notes":[]},{"n":23,"t":"豈說：拯救我脫離敵人的手嗎？救贖我脫離強暴人的手嗎？","notes":[]},{"n":24,"t":"請你們教導我，我便不作聲；使我明白在何事上有錯。","notes":[]},{"n":25,"t":"正直的言語力量何其大！但你們責備是責備甚麼呢？","notes":[]},{"n":26,"t":"絕望人的講論既然如風，你們還想要駁正言語嗎？","notes":[]},{"n":27,"t":"你們想為孤兒拈鬮，以朋友當貨物。","notes":[]},{"n":28,"t":"現在請你們看看我，我決不當面說謊。","notes":[]},{"n":29,"t":"請你們轉意，不要不公；請再轉意，我的事有理。","notes":[]},{"n":30,"t":"我的舌上豈有不義嗎？我的口裏豈不辨奸惡嗎？","notes":[]}]},"7":{"heading":"","verses":[{"n":1,"t":"人在世上豈無爭戰嗎？他的日子不像雇工人的日子嗎？","notes":[]},{"n":2,"t":"像奴僕切慕黑影，像雇工人盼望工價；","notes":[]},{"n":3,"t":"我也照樣經過困苦的日月，夜間的疲乏為我而定。","notes":[]},{"n":4,"t":"我躺臥的時候便說：我何時起來，黑夜就過去呢？我盡是反來覆去，直到天亮。","notes":[]},{"n":5,"t":"我的肉體以蟲子和塵土為衣；我的皮膚才收了口又重新破裂。","notes":[]},{"n":6,"t":"我的日子比梭更快，都消耗在無指望之中。","notes":[]},{"n":7,"t":"求你想念，我的生命不過是一口氣；我的眼睛必不再見福樂。","notes":[]},{"n":8,"t":"觀看我的人，他的眼必不再見我；你的眼目要看我，我卻不在了。","notes":[]},{"n":9,"t":"雲彩消散而過；照樣，人下陰間也不再上來。","notes":[]},{"n":10,"t":"他不再回自己的家；故土也不再認識他。","notes":[]},{"n":11,"t":"我不禁止我口；我靈愁苦，要發出言語；我心苦惱，要吐露哀情。","notes":[]},{"n":12,"t":"我對神說：我豈是洋海，豈是大魚，你竟防守我呢？","notes":[]},{"n":13,"t":"若說：我的床必安慰我，我的榻必解釋我的苦情，","notes":[]},{"n":14,"t":"你就用夢驚駭我，用異象恐嚇我，","notes":[]},{"n":15,"t":"甚至我寧肯噎死，寧肯死亡，勝似留我這一身的骨頭。","notes":[]},{"n":16,"t":"我厭棄性命，不願永活。你任憑我吧，因我的日子都是虛空。","notes":[]},{"n":17,"t":"人算甚麼，你竟看他為大，將他放在心上？","notes":[]},{"n":18,"t":"每早鑒察他，時刻試驗他？","notes":[]},{"n":19,"t":"你到何時才轉眼不看我，才任憑我咽下唾沫呢？","notes":[]},{"n":20,"t":"鑒察人的主啊，我若有罪，於你何妨？為何以我當你的箭靶子，使我厭棄自己的性命？","notes":[]},{"n":21,"t":"為何不赦免我的過犯，除掉我的罪孽？我現今要躺臥在塵土中；你要殷勤地尋找我，我卻不在了。","notes":[]}]},"8":{"heading":"","verses":[{"n":1,"t":"書亞人比勒達回答說：","notes":[]},{"n":2,"t":"這些話你要說到幾時？口中的言語如狂風要到幾時呢？","notes":[]},{"n":3,"t":"神豈能偏離公平？全能者豈能偏離公義？","notes":[]},{"n":4,"t":"或者你的兒女得罪了他；他使他們受報應。","notes":[]},{"n":5,"t":"你若殷勤地尋求神，向全能者懇求；","notes":[]},{"n":6,"t":"你若清潔正直，他必定為你起來，使你公義的居所興旺。","notes":[]},{"n":7,"t":"你起初雖然微小，終久必甚發達。","notes":[]},{"n":8,"t":"請你考問前代，追念他們的列祖所查究的。","notes":[]},{"n":9,"t":"我們不過從昨日才有，一無所知；我們在世的日子好像影兒。","notes":[]},{"n":10,"t":"他們豈不指教你，告訴你，從心裏發出言語來呢？","notes":[]},{"n":11,"t":"蒲草沒有泥豈能發長？蘆荻沒有水豈能生發？","notes":[]},{"n":12,"t":"尚青的時候，還沒有割下，比百樣的草先枯槁。","notes":[]},{"n":13,"t":"凡忘記神的人，景況也是這樣；不虔敬人的指望要滅沒。","notes":[]},{"n":14,"t":"他所仰賴的必折斷；他所倚靠的是蜘蛛網。","notes":[]},{"n":15,"t":"他要倚靠房屋，房屋卻站立不住；他要抓住房屋，房屋卻不能存留。","notes":[]},{"n":16,"t":"他在日光之下發青，蔓子爬滿了園子；","notes":[]},{"n":17,"t":"他的根盤繞石堆，扎入石地。","notes":[]},{"n":18,"t":"他若從本地被拔出，那地就不認識他，說：我沒有見過你。","notes":[]},{"n":19,"t":"看哪，這就是他道中之樂；以後必另有人從地而生。","notes":[]},{"n":20,"t":"神必不丟棄完全人，也不扶助邪惡人。","notes":[]},{"n":21,"t":"他還要以喜笑充滿你的口，以歡呼充滿你的嘴。","notes":[]},{"n":22,"t":"恨惡你的要披戴慚愧；惡人的帳棚必歸於無有。","notes":[]}]},"9":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"我真知道是這樣；但人在神面前怎能成為義呢？","notes":[]},{"n":3,"t":"若願意與他爭辯，千中之一也不能回答。","notes":[]},{"n":4,"t":"他心裏有智慧，且大有能力。誰向神剛硬而得亨通呢？","notes":[]},{"n":5,"t":"他發怒，把山翻倒挪移，山並不知覺。","notes":[]},{"n":6,"t":"他使地震動，離其本位，地的柱子就搖撼。","notes":[]},{"n":7,"t":"他吩咐日頭不出來，就不出來，又封閉眾星。","notes":[]},{"n":8,"t":"他獨自鋪張蒼天，步行在海浪之上。","notes":[]},{"n":9,"t":"他造北斗、參星、昴星，並南方的密宮；","notes":[]},{"n":10,"t":"他行大事，不可測度，行奇事，不可勝數。","notes":[]},{"n":11,"t":"他從我旁邊經過，我卻不看見；他在我面前行走，我倒不知覺。","notes":[]},{"n":12,"t":"他奪取，誰能阻擋？誰敢問他：你做甚麼？","notes":[]},{"n":13,"t":"神必不收回他的怒氣；扶助拉哈伯的，屈身在他以下。","notes":[]},{"n":14,"t":"既是這樣，我怎敢回答他，怎敢選擇言語與他辯論呢？","notes":[]},{"n":15,"t":"我雖有義，也不回答他，只要向那審判我的懇求。","notes":[]},{"n":16,"t":"我若呼籲，他應允我；我仍不信他真聽我的聲音。","notes":[]},{"n":17,"t":"他用暴風折斷我，無故地加增我的損傷。","notes":[]},{"n":18,"t":"我就是喘一口氣，他都不容，倒使我滿心苦惱。","notes":[]},{"n":19,"t":"若論力量，他真有能力！若論審判，他說誰能將我傳來呢？","notes":[]},{"n":20,"t":"我雖有義，自己的口要定我為有罪；我雖完全，我口必顯我為彎曲。","notes":[]},{"n":21,"t":"我本完全，不顧自己；我厭惡我的性命。","notes":[]},{"n":22,"t":"善惡無分，都是一樣；所以我說，完全人和惡人，他都滅絕。","notes":[]},{"n":23,"t":"若忽然遭殺害之禍，他必戲笑無辜的人遇難。","notes":[]},{"n":24,"t":"世界交在惡人手中；蒙蔽世界審判官的臉，若不是他，是誰呢？","notes":[]},{"n":25,"t":"我的日子比跑信的更快，急速過去，不見福樂。","notes":[]},{"n":26,"t":"我的日子過去如快船，如急落抓食的鷹。","notes":[]},{"n":27,"t":"我若說：我要忘記我的哀情，除去我的愁容，心中暢快；","notes":[]},{"n":28,"t":"我因愁苦而懼怕，知道你必不以我為無辜。","notes":[]},{"n":29,"t":"我必被你定為有罪，我何必徒然勞苦呢？","notes":[]},{"n":30,"t":"我若用雪水洗身，用鹼潔淨我的手，","notes":[]},{"n":31,"t":"你還要扔我在坑裏，我的衣服都憎惡我。","notes":[]},{"n":32,"t":"他本不像我是人，使我可以回答他，又使我們可以同聽審判。","notes":[]},{"n":33,"t":"我們中間沒有聽訟的人可以向我們兩造按手。","notes":[]},{"n":34,"t":"願他把杖離開我，不使驚惶威嚇我。","notes":[]},{"n":35,"t":"我就說話，也不懼怕他，現在我卻不是那樣。","notes":[]}]},"10":{"heading":"","verses":[{"n":1,"t":"我厭煩我的性命，必由著自己述說我的哀情；因心裏苦惱，我要說話，","notes":[]},{"n":2,"t":"對神說：不要定我有罪，要指示我，你為何與我爭辯？","notes":[]},{"n":3,"t":"你手所造的，你又欺壓，又藐視，卻光照惡人的計謀。這事你以為美嗎？","notes":[]},{"n":4,"t":"你的眼豈是肉眼？你查看豈像人查看嗎？","notes":[]},{"n":5,"t":"你的日子豈像人的日子，你的年歲豈像人的年歲，","notes":[]},{"n":6,"t":"就追問我的罪孽，尋察我的罪過嗎？","notes":[]},{"n":7,"t":"其實，你知道我沒有罪惡，並沒有能救我脫離你手的。","notes":[]},{"n":8,"t":"你的手創造我，造就我的四肢百體，你還要毀滅我。","notes":[]},{"n":9,"t":"求你記念－製造我如摶泥一般，你還要使我歸於塵土嗎？","notes":[]},{"n":10,"t":"你不是倒出我來好像奶，使我凝結如同奶餅嗎？","notes":[]},{"n":11,"t":"你以皮和肉為衣給我穿上，用骨與筋把我全體聯絡。","notes":[]},{"n":12,"t":"你將生命和慈愛賜給我；你也眷顧保全我的心靈。","notes":[]},{"n":13,"t":"然而，你待我的這些事早已藏在你心裏；我知道你久有此意。","notes":[]},{"n":14,"t":"我若犯罪，你就察看我，並不赦免我的罪孽。","notes":[]},{"n":15,"t":"我若行惡，便有了禍；我若為義，也不敢抬頭，正是滿心羞愧，眼見我的苦情。","notes":[]},{"n":16,"t":"我若昂首自得，你就追捕我如獅子，又在我身上顯出奇能。","notes":[]},{"n":17,"t":"你重立見證攻擊我，向我加增惱怒，如軍兵更換著攻擊我。","notes":[]},{"n":18,"t":"你為何使我出母胎呢？不如我當時氣絕，無人得見我；","notes":[]},{"n":19,"t":"這樣，就如沒有我一般，一出母胎就被送入墳墓。","notes":[]},{"n":20,"t":"我的日子不是甚少嗎？求你停手寬容我，叫我在往而不返之先－就是往黑暗和死蔭之地以先－可以稍得暢快。","notes":[],"end":21},{"n":22,"t":"那地甚是幽暗，是死蔭混沌之地；那裏的光好像幽暗。","notes":[]}]},"11":{"heading":"","verses":[{"n":1,"t":"拿瑪人瑣法回答說：","notes":[]},{"n":2,"t":"這許多的言語豈不該回答嗎？多嘴多舌的人豈可稱為義嗎？","notes":[]},{"n":3,"t":"你誇大的話豈能使人不作聲嗎？你戲笑的時候豈沒有人叫你害羞嗎？","notes":[]},{"n":4,"t":"你說：我的道理純全；我在你眼前潔淨。","notes":[]},{"n":5,"t":"惟願神說話；願他開口攻擊你，","notes":[]},{"n":6,"t":"並將智慧的奧祕指示你；他有諸般的智識。所以當知道神追討你比你罪孽該得的還少。","notes":[]},{"n":7,"t":"你考察就能測透神嗎？你豈能盡情測透全能者嗎？","notes":[]},{"n":8,"t":"他的智慧高於天，你還能做甚麼？深於陰間，你還能知道甚麼？","notes":[]},{"n":9,"t":"其量比地長，比海寬。","notes":[]},{"n":10,"t":"他若經過，將人拘禁，招人受審，誰能阻擋他呢？","notes":[]},{"n":11,"t":"他本知道虛妄的人；人的罪孽，他雖不留意，還是無所不見。","notes":[]},{"n":12,"t":"空虛的人卻毫無知識；人生在世好像野驢的駒子。","notes":[]},{"n":13,"t":"你若將心安正，又向主舉手；","notes":[]},{"n":14,"t":"你手裏若有罪孽，就當遠遠地除掉，也不容非義住在你帳棚之中。","notes":[]},{"n":15,"t":"那時，你必仰起臉來毫無斑點；你也必堅固，無所懼怕。","notes":[]},{"n":16,"t":"你必忘記你的苦楚，就是想起也如流過去的水一樣。","notes":[]},{"n":17,"t":"你在世的日子要比正午更明，雖有黑暗仍像早晨。","notes":[]},{"n":18,"t":"你因有指望就必穩固，也必四圍巡查，坦然安息。","notes":[]},{"n":19,"t":"你躺臥，無人驚嚇，且有許多人向你求恩。","notes":[]},{"n":20,"t":"但惡人的眼目必要失明。他們無路可逃；他們的指望就是氣絕。","notes":[]}]},"12":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"你們真是子民哪，你們死亡，智慧也就滅沒了。","notes":[]},{"n":3,"t":"但我也有聰明，與你們一樣，並非不及你們。你們所說的，誰不知道呢？","notes":[]},{"n":4,"t":"我這求告神、蒙他應允的人竟成了朋友所譏笑的；公義完全人竟受了人的譏笑。","notes":[]},{"n":5,"t":"安逸的人心裏藐視災禍；這災禍常常等待滑腳的人。","notes":[]},{"n":6,"t":"強盜的帳棚興旺，惹神的人穩固，神多將財物送到他們手中。","notes":[]},{"n":7,"t":"你且問走獸，走獸必指教你；又問空中的飛鳥，飛鳥必告訴你；","notes":[]},{"n":8,"t":"或與地說話，地必指教你；海中的魚也必向你說明。","notes":[]},{"n":9,"t":"看這一切，誰不知道是耶和華的手做成的呢？","notes":[]},{"n":10,"t":"凡活物的生命和人類的氣息都在他手中。","notes":[]},{"n":11,"t":"耳朵豈不試驗言語，正如上膛嘗食物嗎？","notes":[]},{"n":12,"t":"年老的有智慧；壽高的有知識。","notes":[]},{"n":13,"t":"在神有智慧和能力；他有謀略和知識。","notes":[]},{"n":14,"t":"他拆毀的，就不能再建造；他捆住人，便不得開釋。","notes":[]},{"n":15,"t":"他把水留住，水便枯乾；他再發出水來，水就翻地。","notes":[]},{"n":16,"t":"在他有能力和智慧，被誘惑的與誘惑人的都是屬他。","notes":[]},{"n":17,"t":"他把謀士剝衣擄去，又使審判官變成愚人。","notes":[]},{"n":18,"t":"他放鬆君王的綁，又用帶子捆他們的腰。","notes":[]},{"n":19,"t":"他把祭司剝衣擄去，又使有能的人傾敗。","notes":[]},{"n":20,"t":"他廢去忠信人的講論，又奪去老人的聰明。","notes":[]},{"n":21,"t":"他使君王蒙羞被辱，放鬆有力之人的腰帶。","notes":[]},{"n":22,"t":"他將深奧的事從黑暗中彰顯，使死蔭顯為光明。","notes":[]},{"n":23,"t":"他使邦國興旺而又毀滅；他使邦國開廣而又擄去。","notes":[]},{"n":24,"t":"他將地上民中首領的聰明奪去，使他們在荒廢無路之地漂流；","notes":[]},{"n":25,"t":"他們無光，在黑暗中摸索，又使他們東倒西歪，像醉酒的人一樣。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"這一切，我眼都見過；我耳都聽過，而且明白。","notes":[]},{"n":2,"t":"你們所知道的，我也知道，並非不及你們。","notes":[]},{"n":3,"t":"我真要對全能者說話；我願與神理論。","notes":[]},{"n":4,"t":"你們是編造謊言的，都是無用的醫生。","notes":[]},{"n":5,"t":"惟願你們全然不作聲；這就算為你們的智慧！","notes":[]},{"n":6,"t":"請你們聽我的辯論，留心聽我口中的分訴。","notes":[]},{"n":7,"t":"你們要為神說不義的話嗎？為他說詭詐的言語嗎？","notes":[]},{"n":8,"t":"你們要為神徇情嗎？要為他爭論嗎？","notes":[]},{"n":9,"t":"他查出你們來，這豈是好嗎？人欺哄人，你們也要照樣欺哄他嗎？","notes":[]},{"n":10,"t":"你們若暗中徇情，他必要責備你們。","notes":[]},{"n":11,"t":"他的尊榮豈不叫你們懼怕嗎？他的驚嚇豈不臨到你們嗎？","notes":[]},{"n":12,"t":"你們以為可記念的箴言是爐灰的箴言；你們以為可靠的堅壘是淤泥的堅壘。","notes":[]},{"n":13,"t":"你們不要作聲，任憑我吧！讓我說話，無論如何我都承當。","notes":[]},{"n":14,"t":"我何必把我的肉掛在牙上，將我的命放在手中。","notes":[]},{"n":15,"t":"他必殺我；我雖無指望，然而我在他面前還要辯明我所行的。","notes":[]},{"n":16,"t":"這要成為我的拯救，因為不虔誠的人不得到他面前。","notes":[]},{"n":17,"t":"你們要細聽我的言語，使我所辯論的入你們的耳中。","notes":[]},{"n":18,"t":"我已陳明我的案，知道自己有義。","notes":[]},{"n":19,"t":"有誰與我爭論，我就情願緘默不言，氣絕而亡。","notes":[]},{"n":20,"t":"惟有兩件不要向我施行，我就不躲開你的面：","notes":[]},{"n":21,"t":"就是把你的手縮回，遠離我身；又不使你的驚惶威嚇我。","notes":[]},{"n":22,"t":"這樣，你呼叫，我就回答；或是讓我說話，你回答我。","notes":[]},{"n":23,"t":"我的罪孽和罪過有多少呢？求你叫我知道我的過犯與罪愆。","notes":[]},{"n":24,"t":"你為何掩面、拿我當仇敵呢？","notes":[]},{"n":25,"t":"你要驚動被風吹的葉子嗎？要追趕枯乾的碎稭嗎？","notes":[]},{"n":26,"t":"你按罪狀刑罰我，又使我擔當幼年的罪孽；","notes":[]},{"n":27,"t":"也把我的腳上了木狗，並窺察我一切的道路，為我的腳掌劃定界限。","notes":[]},{"n":28,"t":"我已經像滅絕的爛物，像蟲蛀的衣裳。","notes":[]}]},"14":{"heading":"","verses":[{"n":1,"t":"人為婦人所生，日子短少，多有患難；","notes":[]},{"n":2,"t":"出來如花，又被割下，飛去如影，不能存留。","notes":[]},{"n":3,"t":"這樣的人你豈睜眼看他嗎？又叫我來受審嗎？","notes":[]},{"n":4,"t":"誰能使潔淨之物出於污穢之中呢？無論誰也不能！","notes":[]},{"n":5,"t":"人的日子既然限定，他的月數在你那裏，你也派定他的界限，使他不能越過，","notes":[]},{"n":6,"t":"便求你轉眼不看他，使他得歇息，直等他像雇工人完畢他的日子。","notes":[]},{"n":7,"t":"樹若被砍下，還可指望發芽，嫩枝生長不息；","notes":[]},{"n":8,"t":"其根雖然衰老在地裏，幹也死在土中，","notes":[]},{"n":9,"t":"及至得了水氣，還要發芽，又長枝條，像新栽的樹一樣。","notes":[]},{"n":10,"t":"但人死亡而消滅；他氣絕，竟在何處呢？","notes":[]},{"n":11,"t":"海中的水絕盡，江河消散乾涸。","notes":[]},{"n":12,"t":"人也是如此，躺下不再起來，等到天沒有了，仍不得復醒，也不得從睡中喚醒。","notes":[]},{"n":13,"t":"惟願你把我藏在陰間，存於隱密處，等你的忿怒過去；願你為我定了日期，記念我。","notes":[]},{"n":14,"t":"人若死了豈能再活呢？我只要在我一切爭戰的日子，等我被釋放的時候來到。","notes":["或譯：改變"]},{"n":15,"t":"你呼叫，我便回答；你手所做的，你必羨慕。","notes":[]},{"n":16,"t":"但如今你數點我的腳步，豈不窺察我的罪過嗎？","notes":[]},{"n":17,"t":"我的過犯被你封在囊中，也縫嚴了我的罪孽。","notes":[]},{"n":18,"t":"山崩變為無有；磐石挪開原處。","notes":[]},{"n":19,"t":"水流消磨石頭，所流溢的洗去地上的塵土；你也照樣滅絕人的指望。","notes":[]},{"n":20,"t":"你攻擊人常常得勝，使他去世；你改變他的容貌，叫他往而不回。","notes":[]},{"n":21,"t":"他兒子得尊榮，他也不知道，降為卑，他也不覺得。","notes":[]},{"n":22,"t":"但知身上疼痛，心中悲哀。","notes":[]}]},"15":{"heading":"第二次對話","verses":[{"n":1,"t":"提幔人以利法回答說：","notes":[]},{"n":2,"t":"智慧人豈可用虛空的知識回答，用東風充滿肚腹呢？","notes":[]},{"n":3,"t":"他豈可用無益的話和無濟於事的言語理論呢？","notes":[]},{"n":4,"t":"你是廢棄敬畏的意，在神面前阻止敬虔的心。","notes":[]},{"n":5,"t":"你的罪孽指教你的口；你選用詭詐人的舌頭。","notes":[]},{"n":6,"t":"你自己的口定你有罪，並非是我；你自己的嘴見證你的不是。","notes":[]},{"n":7,"t":"你豈是頭一個被生的人嗎？你受造在諸山之先嗎？","notes":[]},{"n":8,"t":"你曾聽見神的密旨嗎？你還將智慧獨自得盡嗎？","notes":[]},{"n":9,"t":"你知道甚麼是我們不知道的呢？你明白甚麼是我們不明白的呢？","notes":[]},{"n":10,"t":"我們這裏有白髮的和年紀老邁的，比你父親還老。","notes":[]},{"n":11,"t":"神用溫和的話安慰你，你以為太小嗎？","notes":[]},{"n":12,"t":"你的心為何將你逼去？你的眼為何冒出火星，","notes":[]},{"n":13,"t":"使你的靈反對神，也任你的口發這言語？","notes":[]},{"n":14,"t":"人是甚麼，竟算為潔淨呢？婦人所生的是甚麼，竟算為義呢？","notes":[]},{"n":15,"t":"神不信靠他的眾聖者；在他眼前，天也不潔淨，","notes":[]},{"n":16,"t":"何況那污穢可憎、喝罪孽如水的世人呢！","notes":[]},{"n":17,"t":"我指示你，你要聽；我要述說所看見的，","notes":[]},{"n":18,"t":"就是智慧人從列祖所受，傳說而不隱瞞的。","notes":[]},{"n":19,"t":"這地惟獨賜給他們，並沒有外人從他們中間經過。）","notes":[]},{"n":20,"t":"惡人一生之日劬勞痛苦；強暴人一生的年數也是如此。","notes":[]},{"n":21,"t":"驚嚇的聲音常在他耳中；在平安時，搶奪的必臨到他那裏。","notes":[]},{"n":22,"t":"他不信自己能從黑暗中轉回；他被刀劍等候。","notes":[]},{"n":23,"t":"他漂流在外求食，說：哪裏有食物呢？他知道黑暗的日子在他手邊預備好了。","notes":[]},{"n":24,"t":"急難困苦叫他害怕，而且勝了他，好像君王預備上陣一樣。","notes":[]},{"n":25,"t":"他伸手攻擊神，以驕傲攻擊全能者，","notes":[]},{"n":26,"t":"挺著頸項，用盾牌的厚凸面向全能者直闖；","notes":[]},{"n":27,"t":"是因他的臉蒙上脂油，腰積成肥肉。","notes":[]},{"n":28,"t":"他曾住在荒涼城邑，無人居住、將成亂堆的房屋。","notes":[]},{"n":29,"t":"他不得富足，財物不得常存，產業在地上也不加增。","notes":[]},{"n":30,"t":"他不得出離黑暗。火焰要將他的枝子燒乾；因神口中的氣，他要滅亡。","notes":["原文是走去"]},{"n":31,"t":"他不用倚靠虛假欺哄自己，因虛假必成為他的報應。","notes":[]},{"n":32,"t":"他的日期未到之先，這事必成就；他的枝子不得青綠。","notes":[]},{"n":33,"t":"他必像葡萄樹的葡萄，未熟而落；又像橄欖樹的花，一開而謝。","notes":[]},{"n":34,"t":"原來不敬虔之輩必無生育；受賄賂之人的帳棚必被火燒。","notes":[]},{"n":35,"t":"他們所懷的是毒害，所生的是罪孽；心裏所預備的是詭詐。","notes":[]}]},"16":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"這樣的話我聽了許多；你們安慰人，反叫人愁煩。","notes":[]},{"n":3,"t":"虛空的言語有窮盡嗎？有甚麼話惹動你回答呢？","notes":[]},{"n":4,"t":"我也能說你們那樣的話；你們若處在我的境遇，我也會聯絡言語攻擊你們，又能向你們搖頭。","notes":[]},{"n":5,"t":"但我必用口堅固你們，用嘴消解你們的憂愁。","notes":[]},{"n":6,"t":"我雖說話，憂愁仍不得消解；我雖停住不說，憂愁就離開我嗎？","notes":[]},{"n":7,"t":"但現在神使我困倦，使親友遠離我，","notes":[]},{"n":8,"t":"又抓住我，作見證攻擊我；我身體的枯瘦也當面見證我的不是。","notes":[]},{"n":9,"t":"主發怒撕裂我，逼迫我，向我切齒；我的敵人怒目看我。","notes":[]},{"n":10,"t":"他們向我開口，打我的臉羞辱我，聚會攻擊我。","notes":[]},{"n":11,"t":"神把我交給不敬虔的人，把我扔到惡人的手中。","notes":[]},{"n":12,"t":"我素來安逸，他折斷我，掐住我的頸項，把我摔碎，又立我為他的箭靶子。","notes":[]},{"n":13,"t":"他的弓箭手四面圍繞我；他破裂我的肺腑，並不留情，把我的膽傾倒在地上，","notes":[]},{"n":14,"t":"將我破裂又破裂，如同勇士向我直闖。","notes":[]},{"n":15,"t":"我縫麻布在我皮膚上，把我的角放在塵土中。","notes":[]},{"n":16,"t":"我的臉因哭泣發紫，在我的眼皮上有死蔭。","notes":[]},{"n":17,"t":"我的手中卻無強暴；我的祈禱也是清潔。","notes":[]},{"n":18,"t":"地啊，不要遮蓋我的血！不要阻擋我的哀求！","notes":[]},{"n":19,"t":"現今，在天有我的見證，在上有我的中保。","notes":[]},{"n":20,"t":"我的朋友譏誚我，我卻向神眼淚汪汪。","notes":[]},{"n":21,"t":"願人得與神辯白，如同人與朋友辯白一樣；","notes":[]},{"n":22,"t":"因為再過幾年，我必走那往而不返之路。","notes":[]}]},"17":{"heading":"","verses":[{"n":1,"t":"我的心靈消耗，我的日子滅盡；墳墓為我預備好了。","notes":[]},{"n":2,"t":"真有戲笑我的在我這裏，我眼常見他們惹動我。","notes":[]},{"n":3,"t":"願主拿憑據給我，自己為我作保。在你以外誰肯與我擊掌呢？","notes":[]},{"n":4,"t":"因你使他們心不明理，所以你必不高舉他們。","notes":[]},{"n":5,"t":"控告他的朋友、以朋友為可搶奪的，連他兒女的眼睛也要失明。","notes":[]},{"n":6,"t":"神使我作了民中的笑談；他們也吐唾沫在我臉上。","notes":[]},{"n":7,"t":"我的眼睛因憂愁昏花；我的百體好像影兒。","notes":[]},{"n":8,"t":"正直人因此必驚奇；無辜的人要興起攻擊不敬虔之輩。","notes":[]},{"n":9,"t":"然而，義人要持守所行的道；手潔的人要力上加力。","notes":[]},{"n":10,"t":"至於你們眾人，可以再來辯論吧！你們中間，我找不著一個智慧人。","notes":[]},{"n":11,"t":"我的日子已經過了；我的謀算、我心所想望的已經斷絕。","notes":[]},{"n":12,"t":"他們以黑夜為白晝，說：亮光近乎黑暗。","notes":[]},{"n":13,"t":"我若盼望陰間為我的房屋，若下榻在黑暗中，","notes":[]},{"n":14,"t":"若對朽壞說：你是我的父；對蟲說：你是我的母親姊妹；","notes":[]},{"n":15,"t":"這樣，我的指望在哪裏呢？我所指望的誰能看見呢？","notes":[]},{"n":16,"t":"等到安息在塵土中，這指望必下到陰間的門閂那裏了。","notes":[]}]},"18":{"heading":"","verses":[{"n":1,"t":"書亞人比勒達回答說：","notes":[]},{"n":2,"t":"你尋索言語要到幾時呢？你可以揣摩思想，然後我們就說話。","notes":[]},{"n":3,"t":"我們為何算為畜生，在你眼中看作污穢呢？","notes":[]},{"n":4,"t":"你這惱怒將自己撕裂的，難道大地為你見棄、磐石挪開原處嗎？","notes":[]},{"n":5,"t":"惡人的亮光必要熄滅；他的火焰必不照耀。","notes":[]},{"n":6,"t":"他帳棚中的亮光要變為黑暗；他以上的燈也必熄滅。","notes":[]},{"n":7,"t":"他堅強的腳步必見狹窄；自己的計謀必將他絆倒。","notes":[]},{"n":8,"t":"因為他被自己的腳陷入網中，走在纏人的網羅上。","notes":[]},{"n":9,"t":"圈套必抓住他的腳跟；機關必擒獲他。","notes":[]},{"n":10,"t":"活扣為他藏在土內；羈絆為他藏在路上。","notes":[]},{"n":11,"t":"四面的驚嚇要使他害怕，並且追趕他的腳跟。","notes":[]},{"n":12,"t":"他的力量必因飢餓衰敗；禍患要在他旁邊等候。","notes":[]},{"n":13,"t":"他本身的肢體要被吞吃；死亡的長子要吞吃他的肢體。","notes":[]},{"n":14,"t":"他要從所倚靠的帳棚被拔出來，帶到驚嚇的王那裏。","notes":[]},{"n":15,"t":"不屬他的必住在他的帳棚裏；硫磺必撒在他所住之處。","notes":[]},{"n":16,"t":"下邊，他的根本要枯乾；上邊，他的枝子要剪除。","notes":[]},{"n":17,"t":"他的記念在地上必然滅亡；他的名字在街上也不存留。","notes":[]},{"n":18,"t":"他必從光明中被攆到黑暗裏，必被趕出世界。","notes":[]},{"n":19,"t":"在本民中必無子無孫；在寄居之地也無一人存留。","notes":[]},{"n":20,"t":"以後來的要驚奇他的日子，好像以前去的受了驚駭。","notes":[]},{"n":21,"t":"不義之人的住處總是這樣；此乃不認識神之人的地步。","notes":[]}]},"19":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"你們攪擾我的心，用言語壓碎我要到幾時呢？","notes":[]},{"n":3,"t":"你們這十次羞辱我；你們苦待我也不以為恥。","notes":[]},{"n":4,"t":"果真我有錯，這錯乃是在我。","notes":[]},{"n":5,"t":"你們果然要向我誇大，以我的羞辱為證指責我，","notes":[]},{"n":6,"t":"就該知道是神傾覆我，用網羅圍繞我。","notes":[]},{"n":7,"t":"我因委曲呼叫，卻不蒙應允；我呼求，卻不得公斷。","notes":[]},{"n":8,"t":"神用籬笆攔住我的道路，使我不得經過；又使我的路徑黑暗。","notes":[]},{"n":9,"t":"他剝去我的榮光，摘去我頭上的冠冕。","notes":[]},{"n":10,"t":"他在四圍攻擊我，我便歸於死亡，將我的指望如樹拔出來。","notes":[]},{"n":11,"t":"他的忿怒向我發作，以我為敵人。","notes":[]},{"n":12,"t":"他的軍旅一齊上來，修築戰路攻擊我，在我帳棚的四圍安營。","notes":[]},{"n":13,"t":"他把我的弟兄隔在遠處，使我所認識的全然與我生疏。","notes":[]},{"n":14,"t":"我的親戚與我斷絕；我的密友都忘記我。","notes":[]},{"n":15,"t":"在我家寄居的，和我的使女都以我為外人；我在他們眼中看為外邦人。","notes":[]},{"n":16,"t":"我呼喚僕人，雖用口求他，他還是不回答。","notes":[]},{"n":17,"t":"我口的氣味，我妻子厭惡；我的懇求，我同胞也憎嫌。","notes":[]},{"n":18,"t":"連小孩子也藐視我；我若起來，他們都嘲笑我。","notes":[]},{"n":19,"t":"我的密友都憎惡我；我平日所愛的人向我翻臉。","notes":[]},{"n":20,"t":"我的皮肉緊貼骨頭；我只剩牙皮逃脫了。","notes":[]},{"n":21,"t":"我朋友啊，可憐我！可憐我！因為神的手攻擊我。","notes":[]},{"n":22,"t":"你們為甚麼彷彿神逼迫我，吃我的肉還以為不足呢？","notes":[]},{"n":23,"t":"惟願我的言語現在寫上，都記錄在書上；","notes":[]},{"n":24,"t":"用鐵筆鐫刻，用鉛灌在磐石上，直存到永遠。","notes":[]},{"n":25,"t":"我知道我的救贖主活著，末了必站立在地上。","notes":[]},{"n":26,"t":"我這皮肉滅絕之後，我必在肉體之外得見神。","notes":[]},{"n":27,"t":"我自己要見他，親眼要看他，並不像外人。我的心腸在我裏面消滅了！","notes":[]},{"n":28,"t":"你們若說：我們逼迫他要何等地重呢？惹事的根乃在乎他；","notes":[]},{"n":29,"t":"你們就當懼怕刀劍；因為忿怒惹動刀劍的刑罰，使你們知道有報應。","notes":["原文是審判"]}]},"20":{"heading":"","verses":[{"n":1,"t":"拿瑪人瑣法回答說：","notes":[]},{"n":2,"t":"我心中急躁，所以我的思念叫我回答。","notes":[]},{"n":3,"t":"我已聽見那羞辱我，責備我的話；我的悟性叫我回答。","notes":[]},{"n":4,"t":"你豈不知亙古以來，自從人生在地，","notes":[]},{"n":5,"t":"惡人誇勝是暫時的，不敬虔人的喜樂不過轉眼之間嗎？","notes":[]},{"n":6,"t":"他的尊榮雖達到天上，頭雖頂到雲中，","notes":[]},{"n":7,"t":"他終必滅亡，像自己的糞一樣；素來見他的人要說：他在哪裏呢？","notes":[]},{"n":8,"t":"他必飛去如夢，不再尋見，速被趕去，如夜間的異象。","notes":[]},{"n":9,"t":"親眼見過他的，必不再見他；他的本處也再見不著他。","notes":[]},{"n":10,"t":"他的兒女要求窮人的恩；他的手要賠還不義之財。","notes":[]},{"n":11,"t":"他的骨頭雖然有青年之力，卻要和他一同躺臥在塵土中。","notes":[]},{"n":12,"t":"他口內雖以惡為甘甜，藏在舌頭底下，","notes":[]},{"n":13,"t":"愛戀不捨，含在口中；","notes":[]},{"n":14,"t":"他的食物在肚裏卻要化為酸，在他裏面成為虺蛇的惡毒。","notes":[]},{"n":15,"t":"他吞了財寶，還要吐出；神要從他腹中掏出來。","notes":[]},{"n":16,"t":"他必吸飲虺蛇的毒氣；蝮蛇的舌頭也必殺他。","notes":[]},{"n":17,"t":"流奶與蜜之河，他不得再見。","notes":[]},{"n":18,"t":"他勞碌得來的要賠還，不得享用；不能照所得的財貨歡樂。","notes":["原文是吞下"]},{"n":19,"t":"他欺壓窮人，且又離棄；強取非自己所蓋的房屋。","notes":["或譯：強取房屋不得再建造"]},{"n":20,"t":"他因貪而無厭，所喜悅的連一樣也不能保守。","notes":[]},{"n":21,"t":"其餘的沒有一樣他不吞滅，所以他的福樂不能長久。","notes":[]},{"n":22,"t":"他在滿足有餘的時候，必到狹窄的地步；凡受苦楚的人都必加手在他身上。","notes":[]},{"n":23,"t":"他正要充滿肚腹的時候，神必將猛烈的忿怒降在他身上；正在他吃飯的時候，要將這忿怒像雨降在他身上。","notes":[]},{"n":24,"t":"他要躲避鐵器；銅弓的箭要將他射透。","notes":[]},{"n":25,"t":"他把箭一抽，就從他身上出來；發光的箭頭從他膽中出來，有驚惶臨在他身上。","notes":[]},{"n":26,"t":"他的財寶歸於黑暗；人所不吹的火要把他燒滅，要把他帳棚中所剩下的燒毀。","notes":[]},{"n":27,"t":"天要顯明他的罪孽；地要興起攻擊他。","notes":[]},{"n":28,"t":"他的家產必然過去；神發怒的日子，他的貨物都要消滅。","notes":[]},{"n":29,"t":"這是惡人從神所得的分，是神為他所定的產業。","notes":[]}]},"21":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"你們要細聽我的言語，就算是你們安慰我。","notes":[]},{"n":3,"t":"請寬容我，我又要說話；說了以後，任憑你們嗤笑吧！","notes":[]},{"n":4,"t":"我豈是向人訴冤？為何不焦急呢？","notes":[]},{"n":5,"t":"你們要看著我而驚奇，用手摀口。","notes":[]},{"n":6,"t":"我每逢思想，心就驚惶，渾身戰兢。","notes":[]},{"n":7,"t":"惡人為何存活，享大壽數，勢力強盛呢？","notes":[]},{"n":8,"t":"他們眼見兒孫，和他們一同堅立。","notes":[]},{"n":9,"t":"他們的家宅平安無懼；神的杖也不加在他們身上。","notes":[]},{"n":10,"t":"他們的公牛孳生而不斷絕；母牛下犢而不掉胎。","notes":[]},{"n":11,"t":"他們打發小孩子出去，多如羊群；他們的兒女踴躍跳舞。","notes":[]},{"n":12,"t":"他們隨著琴鼓歌唱，又因簫聲歡喜。","notes":[]},{"n":13,"t":"他們度日諸事亨通，轉眼下入陰間。","notes":[]},{"n":14,"t":"他們對神說：離開我們吧！我們不願曉得你的道。","notes":[]},{"n":15,"t":"全能者是誰，我們何必事奉他呢？求告他有甚麼益處呢？","notes":[]},{"n":16,"t":"看哪，他們亨通不在乎自己；惡人所謀定的離我好遠。","notes":[]},{"n":17,"t":"惡人的燈何嘗熄滅？患難何嘗臨到他們呢？神何嘗發怒，向他們分散災禍呢？","notes":[]},{"n":18,"t":"他們何嘗像風前的碎稭，如暴風颳去的糠秕呢？","notes":[]},{"n":19,"t":"你們說：神為惡人的兒女積蓄罪孽；我說：不如本人受報，好使他親自知道。","notes":[]},{"n":20,"t":"願他親眼看見自己敗亡，親自飲全能者的忿怒。","notes":[]},{"n":21,"t":"他的歲月既盡，他還顧他本家嗎？","notes":[]},{"n":22,"t":"神既審判那在高位的，誰能將知識教訓他呢？","notes":[]},{"n":23,"t":"有人至死身體強壯，盡得平靖安逸；","notes":[]},{"n":24,"t":"他的奶桶充滿，他的骨髓滋潤。","notes":[]},{"n":25,"t":"有人至死心中痛苦，終身未嘗福樂的滋味；","notes":[]},{"n":26,"t":"他們一樣躺臥在塵土中，都被蟲子遮蓋。","notes":[]},{"n":27,"t":"我知道你們的意思，並誣害我的計謀。","notes":[]},{"n":28,"t":"你們說：霸者的房屋在哪裏？惡人住過的帳棚在哪裏？","notes":[]},{"n":29,"t":"你們豈沒有詢問過路的人嗎？不知道他們所引的證據嗎？","notes":[]},{"n":30,"t":"就是惡人在禍患的日子得存留，在發怒的日子得逃脫。","notes":[]},{"n":31,"t":"他所行的，有誰當面給他說明？他所做的，有誰報應他呢？","notes":[]},{"n":32,"t":"然而他要被抬到塋地；並有人看守墳墓。","notes":[]},{"n":33,"t":"他要以谷中的土塊為甘甜；在他以先去的無數，在他以後去的更多。","notes":[]},{"n":34,"t":"你們對答的話中既都錯謬，怎麼徒然安慰我呢？","notes":[]}]},"22":{"heading":"第三次對話","verses":[{"n":1,"t":"提幔人以利法回答說：","notes":[]},{"n":2,"t":"人豈能使神有益呢？智慧人但能有益於己。","notes":[]},{"n":3,"t":"你為人公義，豈叫全能者喜悅呢？你行為完全，豈能使他得利呢？","notes":[]},{"n":4,"t":"豈是因你敬畏他就責備你、審判你嗎？","notes":[]},{"n":5,"t":"你的罪惡豈不是大嗎？你的罪孽也沒有窮盡；","notes":[]},{"n":6,"t":"因你無故強取弟兄的物為當頭，剝去貧寒人的衣服。","notes":[]},{"n":7,"t":"困乏的人，你沒有給他水喝；飢餓的人，你沒有給他食物。","notes":[]},{"n":8,"t":"有能力的人就得地土；尊貴的人也住在其中。","notes":[]},{"n":9,"t":"你打發寡婦空手回去，折斷孤兒的膀臂。","notes":[]},{"n":10,"t":"因此，有網羅環繞你，有恐懼忽然使你驚惶；","notes":[]},{"n":11,"t":"或有黑暗蒙蔽你，並有洪水淹沒你。","notes":[]},{"n":12,"t":"神豈不是在高天嗎？你看星宿何其高呢！","notes":[]},{"n":13,"t":"你說：神知道甚麼？他豈能看透幽暗施行審判呢？","notes":[]},{"n":14,"t":"密雲將他遮蓋，使他不能看見；他周遊穹蒼。","notes":[]},{"n":15,"t":"你要依從上古的道嗎？這道是惡人所行的。","notes":[]},{"n":16,"t":"他們未到死期，忽然除滅；根基毀壞，好像被江河沖去。","notes":[]},{"n":17,"t":"他們向神說：離開我們吧！又說：全能者能把我們怎麼樣呢？","notes":[]},{"n":18,"t":"哪知神以美物充滿他們的房屋；但惡人所謀定的離我好遠。","notes":[]},{"n":19,"t":"義人看見他們的結局就歡喜；無辜的人嗤笑他們，","notes":[]},{"n":20,"t":"說：那起來攻擊我們的果然被剪除，其餘的都被火燒滅。","notes":[]},{"n":21,"t":"你要認識神，就得平安；福氣也必臨到你。","notes":[]},{"n":22,"t":"你當領受他口中的教訓，將他的言語存在心裏。","notes":[]},{"n":23,"t":"你若歸向全能者，從你帳棚中遠除不義，就必得建立。","notes":[]},{"n":24,"t":"要將你的珍寶丟在塵土裏，將俄斐的黃金丟在溪河石頭之間；","notes":[]},{"n":25,"t":"全能者就必為你的珍寶，作你的寶銀。","notes":[]},{"n":26,"t":"你就要以全能者為喜樂，向神仰起臉來。","notes":[]},{"n":27,"t":"你要禱告他，他就聽你；你也要還你的願。","notes":[]},{"n":28,"t":"你定意要做何事，必然給你成就；亮光也必照耀你的路。","notes":[]},{"n":29,"t":"人使你降卑，你仍可說：必得高升；謙卑的人，神必然拯救。","notes":[]},{"n":30,"t":"人非無辜，神且要搭救他；他因你手中清潔，必蒙拯救。","notes":[]}]},"23":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"如今我的哀告還算為悖逆；我的責罰比我的唉哼還重。","notes":[]},{"n":3,"t":"惟願我能知道在哪裏可以尋見神，能到他的臺前，","notes":[]},{"n":4,"t":"我就在他面前將我的案件陳明，滿口辯白。","notes":[]},{"n":5,"t":"我必知道他回答我的言語，明白他向我所說的話。","notes":[]},{"n":6,"t":"他豈用大能與我爭辯嗎？必不這樣！他必理會我。","notes":[]},{"n":7,"t":"在他那裏正直人可以與他辯論；這樣，我必永遠脫離那審判我的。","notes":[]},{"n":8,"t":"只是，我往前行，他不在那裏，往後退，也不能見他。","notes":[]},{"n":9,"t":"他在左邊行事，我卻不能看見，在右邊隱藏，我也不能見他。","notes":[]},{"n":10,"t":"然而他知道我所行的路；他試煉我之後，我必如精金。","notes":[]},{"n":11,"t":"我腳追隨他的步履；我謹守他的道，並不偏離。","notes":[]},{"n":12,"t":"他嘴唇的命令，我未曾背棄；我看重他口中的言語，過於我需用的飲食。","notes":[]},{"n":13,"t":"只是他心志已定，誰能使他轉意呢？他心裏所願的，就行出來。","notes":[]},{"n":14,"t":"他向我所定的，就必做成；這類的事他還有許多。","notes":[]},{"n":15,"t":"所以我在他面前驚惶；我思念這事便懼怕他。","notes":[]},{"n":16,"t":"神使我喪膽；全能者使我驚惶。","notes":[]},{"n":17,"t":"我的恐懼不是因為黑暗，也不是因為幽暗蒙蔽我的臉。","notes":[]}]},"24":{"heading":"","verses":[{"n":1,"t":"全能者既定期罰惡，為何不使認識他的人看見那日子呢？","notes":[]},{"n":2,"t":"有人挪移地界，搶奪群畜而牧養。","notes":[]},{"n":3,"t":"他們拉去孤兒的驢，強取寡婦的牛為當頭。","notes":[]},{"n":4,"t":"他們使窮人離開正道；世上的貧民盡都隱藏。","notes":[]},{"n":5,"t":"這些貧窮人如同野驢出到曠野，殷勤尋找食物；他們靠著野地給兒女糊口，","notes":[]},{"n":6,"t":"收割別人田間的禾稼，摘取惡人餘剩的葡萄，","notes":[]},{"n":7,"t":"終夜赤身無衣，天氣寒冷毫無遮蓋，","notes":[]},{"n":8,"t":"在山上被大雨淋濕，因沒有避身之處就挨近磐石。","notes":[]},{"n":9,"t":"又有人從母懷中搶奪孤兒，強取窮人的衣服為當頭，","notes":[]},{"n":10,"t":"使人赤身無衣，到處流行，且因飢餓扛抬禾捆，","notes":[]},{"n":11,"t":"在那些人的圍牆內造油，醡酒，自己還口渴。","notes":[]},{"n":12,"t":"在多民的城內有人唉哼，受傷的人哀號；神卻不理會那惡人的愚妄。","notes":[]},{"n":13,"t":"又有人背棄光明，不認識光明的道，不住在光明的路上。","notes":[]},{"n":14,"t":"殺人的黎明起來，殺害困苦窮乏人，夜間又作盜賊。","notes":[]},{"n":15,"t":"姦夫等候黃昏，說：必無眼能見我，就把臉蒙蔽。","notes":[]},{"n":16,"t":"盜賊黑夜挖窟窿；白日躲藏，並不認識光明。","notes":[]},{"n":17,"t":"他們看早晨如幽暗，因為他們曉得幽暗的驚駭。","notes":[]},{"n":18,"t":"這些惡人猶如浮萍快快飄去。他們所得的分在世上被咒詛；他們不得再走葡萄園的路。","notes":[]},{"n":19,"t":"乾旱炎熱消沒雪水；陰間也如此消沒犯罪之輩。","notes":[]},{"n":20,"t":"懷他的母要忘記他；蟲子要吃他，覺得甘甜；他不再被人記念。不義的人必如樹折斷。","notes":["原文是胎"]},{"n":21,"t":"他惡待不懷孕不生養的婦人，不善待寡婦。","notes":["或譯：他吞滅"]},{"n":22,"t":"然而神用能力保全有勢力的人；那性命難保的人仍然興起。","notes":[]},{"n":23,"t":"神使他們安穩，他們就有所倚靠；神的眼目也看顧他們的道路。","notes":[]},{"n":24,"t":"他們被高舉，不過片時就沒有了；他們降為卑，被除滅，與眾人一樣，又如穀穗被割。","notes":[]},{"n":25,"t":"若不是這樣，誰能證實我是說謊的，將我的言語駁為虛空呢？","notes":[]}]},"25":{"heading":"","verses":[{"n":1,"t":"書亞人比勒達回答說：","notes":[]},{"n":2,"t":"神有治理之權，有威嚴可畏；他在高處施行和平。","notes":[]},{"n":3,"t":"他的諸軍豈能數算？他的光亮一發，誰不蒙照呢？","notes":[]},{"n":4,"t":"這樣在神面前，人怎能稱義？婦人所生的怎能潔淨？","notes":[]},{"n":5,"t":"在神眼前，月亮也無光亮，星宿也不清潔。","notes":[]},{"n":6,"t":"何況如蟲的人，如蛆的世人呢！","notes":[]}]},"26":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"無能的人蒙你何等的幫助！膀臂無力的人蒙你何等的拯救！","notes":[]},{"n":3,"t":"無智慧的人蒙你何等的指教！你向他多顯大知識！","notes":[]},{"n":4,"t":"你向誰發出言語來？誰的靈從你而出？","notes":[]},{"n":5,"t":"在大水和水族以下的陰魂戰兢。","notes":[]},{"n":6,"t":"在神面前，陰間顯露；滅亡也不得遮掩。","notes":[]},{"n":7,"t":"神將北極鋪在空中，將大地懸在虛空；","notes":[]},{"n":8,"t":"將水包在密雲中，雲卻不破裂；","notes":[]},{"n":9,"t":"遮蔽他的寶座，將雲鋪在其上；","notes":[]},{"n":10,"t":"在水面的周圍劃出界限，直到光明黑暗的交界。","notes":[]},{"n":11,"t":"天的柱子因他的斥責震動驚奇。","notes":[]},{"n":12,"t":"他以能力攪動大海；他藉知識打傷拉哈伯，","notes":["或譯：平靜"]},{"n":13,"t":"藉他的靈使天有妝飾；他的手刺殺快蛇。","notes":[]},{"n":14,"t":"看哪，這不過是神工作的些微；我們所聽於他的是何等細微的聲音！他大能的雷聲誰能明透呢？","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"約伯接著說：","notes":[]},{"n":2,"t":"神奪去我的理，全能者使我心中愁苦。我指著永生的神起誓：","notes":[]},{"n":3,"t":"我的生命尚在我裏面；神所賜呼吸之氣仍在我的鼻孔內。","notes":[]},{"n":4,"t":"我的嘴決不說非義之言；我的舌也不說詭詐之語。","notes":[]},{"n":5,"t":"我斷不以你們為是；我至死必不以自己為不正！","notes":[]},{"n":6,"t":"我持定我的義，必不放鬆；在世的日子，我心必不責備我。","notes":[]},{"n":7,"t":"願我的仇敵如惡人一樣；願那起來攻擊我的，如不義之人一般。","notes":[]},{"n":8,"t":"不敬虔的人雖然得利，神奪取其命的時候還有甚麼指望呢？","notes":[]},{"n":9,"t":"患難臨到他，神豈能聽他的呼求？","notes":[]},{"n":10,"t":"他豈以全能者為樂，隨時求告神呢？","notes":[]},{"n":11,"t":"神的作為，我要指教你們；全能者所行的，我也不隱瞞。","notes":[]},{"n":12,"t":"你們自己也都見過，為何全然變為虛妄呢？","notes":[]},{"n":13,"t":"神為惡人所定的分，強暴人從全能者所得的報乃是這樣：","notes":["原文是產業"]},{"n":14,"t":"倘或他的兒女增多，還是被刀所殺；他的子孫必不得飽食。","notes":[]},{"n":15,"t":"他所遺留的人必死而埋葬；他的寡婦也不哀哭。","notes":[]},{"n":16,"t":"他雖積蓄銀子如塵沙，預備衣服如泥土；","notes":[]},{"n":17,"t":"他只管預備，義人卻要穿上；他的銀子，無辜的人要分取。","notes":[]},{"n":18,"t":"他建造房屋如蟲做窩，又如守望者所搭的棚。","notes":[]},{"n":19,"t":"他雖富足躺臥，卻不得收殮，轉眼之間就不在了。","notes":[]},{"n":20,"t":"驚恐如波濤將他追上；暴風在夜間將他颳去。","notes":[]},{"n":21,"t":"東風把他飄去，又颳他離開本處。","notes":[]},{"n":22,"t":"神要向他射箭，並不留情；他恨不得逃脫神的手。","notes":[]},{"n":23,"t":"人要向他拍掌，並要發叱聲，使他離開本處。","notes":[]}]},"28":{"heading":"歌頌智慧","verses":[{"n":1,"t":"銀子有礦；煉金有方。","notes":[]},{"n":2,"t":"鐵從地裏挖出；銅從石中鎔化。","notes":[]},{"n":3,"t":"人為黑暗定界限，查究幽暗陰翳的石頭，直到極處，","notes":[]},{"n":4,"t":"在無人居住之處刨開礦穴，過路的人也想不到他們；又與人遠離，懸在空中搖來搖去。","notes":[]},{"n":5,"t":"至於地，能出糧食，地內好像被火翻起來。","notes":[]},{"n":6,"t":"地中的石頭有藍寶石，並有金沙。","notes":[]},{"n":7,"t":"礦中的路鷙鳥不得知道；鷹眼也未見過。","notes":[]},{"n":8,"t":"狂傲的野獸未曾行過；猛烈的獅子也未曾經過。","notes":[]},{"n":9,"t":"人伸手鑿開堅石，傾倒山根，","notes":[]},{"n":10,"t":"在磐石中鑿出水道，親眼看見各樣寶物。","notes":[]},{"n":11,"t":"他封閉水不得滴流，使隱藏的物顯露出來。","notes":[]},{"n":12,"t":"然而，智慧有何處可尋？聰明之處在哪裏呢？","notes":[]},{"n":13,"t":"智慧的價值無人能知，在活人之地也無處可尋。","notes":[]},{"n":14,"t":"深淵說：不在我內；滄海說：不在我中。","notes":[]},{"n":15,"t":"智慧非用黃金可得，也不能平白銀為它的價值。","notes":[]},{"n":16,"t":"俄斐金和貴重的紅瑪瑙，並藍寶石，不足與較量；","notes":[]},{"n":17,"t":"黃金和玻璃不足與比較；精金的器皿不足與兌換。","notes":[]},{"n":18,"t":"珊瑚、水晶都不足論；智慧的價值勝過珍珠。","notes":["或譯：紅寶石"]},{"n":19,"t":"古實的紅璧璽不足與比較；精金也不足與較量。","notes":[]},{"n":20,"t":"智慧從何處來呢？聰明之處在哪裏呢？","notes":[]},{"n":21,"t":"是向一切有生命的眼目隱藏，向空中的飛鳥掩蔽。","notes":[]},{"n":22,"t":"滅沒和死亡說：我們風聞其名。","notes":[]},{"n":23,"t":"神明白智慧的道路，曉得智慧的所在。","notes":[]},{"n":24,"t":"因他鑒察直到地極，遍觀普天之下，","notes":[]},{"n":25,"t":"要為風定輕重，又度量諸水；","notes":[]},{"n":26,"t":"他為雨露定命令，為雷電定道路。","notes":[]},{"n":27,"t":"那時他看見智慧，而且述說；他堅定，並且查究。","notes":[]},{"n":28,"t":"他對人說：敬畏主就是智慧；遠離惡便是聰明。","notes":[]}]},"29":{"heading":"約伯最後的申訴","verses":[{"n":1,"t":"約伯又接著說：","notes":[]},{"n":2,"t":"惟願我的景況如從前的月份，如神保守我的日子。","notes":[]},{"n":3,"t":"那時他的燈照在我頭上；我藉他的光行過黑暗。","notes":[]},{"n":4,"t":"我願如壯年的時候：那時我在帳棚中，神待我有密友之情；","notes":[]},{"n":5,"t":"全能者仍與我同在；我的兒女都環繞我。","notes":[]},{"n":6,"t":"奶多可洗我的腳；磐石為我出油成河。","notes":[]},{"n":7,"t":"我出到城門，在街上設立座位；","notes":[]},{"n":8,"t":"少年人見我而迴避，老年人也起身站立；","notes":[]},{"n":9,"t":"王子都停止說話，用手摀口；","notes":[]},{"n":10,"t":"首領靜默無聲，舌頭貼住上膛。","notes":[]},{"n":11,"t":"耳朵聽我的，就稱我有福；眼睛看我的，便稱讚我；","notes":[]},{"n":12,"t":"因我拯救哀求的困苦人和無人幫助的孤兒。","notes":[]},{"n":13,"t":"將要滅亡的為我祝福；我也使寡婦心中歡樂。","notes":[]},{"n":14,"t":"我以公義為衣服，以公平為外袍和冠冕。","notes":[]},{"n":15,"t":"我為瞎子的眼，瘸子的腳。","notes":[]},{"n":16,"t":"我為窮乏人的父；素不認識的人，我查明他的案件。","notes":[]},{"n":17,"t":"我打破不義之人的牙床，從他牙齒中奪了所搶的。","notes":[]},{"n":18,"t":"我便說：我必死在家中，必增添我的日子，多如塵沙。","notes":["原文是窩中"]},{"n":19,"t":"我的根長到水邊；露水終夜霑在我的枝上。","notes":[]},{"n":20,"t":"我的榮耀在身上增新；我的弓在手中日強。","notes":[]},{"n":21,"t":"人聽見我而仰望，靜默等候我的指教。","notes":[]},{"n":22,"t":"我說話之後，他們就不再說；我的言語像雨露滴在他們身上。","notes":[]},{"n":23,"t":"他們仰望我如仰望雨，又張開口如切慕春雨。","notes":[]},{"n":24,"t":"他們不敢自信，我就向他們含笑；他們不使我臉上的光改變。","notes":[]},{"n":25,"t":"我為他們選擇道路，又坐首位；我如君王在軍隊中居住，又如弔喪的安慰傷心的人。","notes":[]}]},"30":{"heading":"","verses":[{"n":1,"t":"但如今，比我年少的人戲笑我；其人之父我曾藐視，不肯安在看守我羊群的狗中。","notes":[]},{"n":2,"t":"他們壯年的氣力既已衰敗，其手之力與我何益呢？","notes":[]},{"n":3,"t":"他們因窮乏飢餓，身體枯瘦，在荒廢淒涼的幽暗中齦乾燥之地，","notes":[]},{"n":4,"t":"在草叢之中採鹹草，羅騰的根為他們的食物。","notes":["小樹名，松類"]},{"n":5,"t":"他們從人中被趕出；人追喊他們如賊一般，","notes":[]},{"n":6,"t":"以致他們住在荒谷之間，在地洞和巖穴中；","notes":[]},{"n":7,"t":"在草叢中叫喚，在荊棘下聚集。","notes":[]},{"n":8,"t":"這都是愚頑下賤人的兒女；他們被鞭打，趕出境外。","notes":[]},{"n":9,"t":"現在這些人以我為歌曲，以我為笑談。","notes":[]},{"n":10,"t":"他們厭惡我，躲在旁邊站著，不住地吐唾沫在我臉上。","notes":[]},{"n":11,"t":"鬆開他們的繩索苦待我，在我面前脫去轡頭。","notes":[]},{"n":12,"t":"這等下流人在我右邊起來，推開我的腳，築成戰路來攻擊我。","notes":[]},{"n":13,"t":"這些無人幫助的，毀壞我的道，加增我的災。","notes":[]},{"n":14,"t":"他們來如同闖進大破口，在毀壞之間滾在我身上。","notes":[]},{"n":15,"t":"驚恐臨到我，驅逐我的尊榮如風；我的福祿如雲過去。","notes":[]},{"n":16,"t":"現在我心極其悲傷；困苦的日子將我抓住。","notes":[]},{"n":17,"t":"夜間，我裏面的骨頭刺我，疼痛不止，好像齦我。","notes":[]},{"n":18,"t":"因神的大力，我的外衣污穢不堪，又如裏衣的領子將我纏住。","notes":[]},{"n":19,"t":"神把我扔在淤泥中，我就像塵土和爐灰一般。","notes":[]},{"n":20,"t":"主啊，我呼求你，你不應允我；我站起來，你就定睛看我。","notes":[]},{"n":21,"t":"你向我變心，待我殘忍，又用大能追逼我，","notes":[]},{"n":22,"t":"把我提在風中，使我駕風而行，又使我消滅在烈風中。","notes":[]},{"n":23,"t":"我知道要使我臨到死地，到那為眾生所定的陰宅。","notes":[]},{"n":24,"t":"然而，人仆倒豈不伸手？遇災難豈不求救呢？","notes":[]},{"n":25,"t":"人遭難，我豈不為他哭泣呢？人窮乏，我豈不為他憂愁呢？","notes":[]},{"n":26,"t":"我仰望得好處，災禍就到了；我等待光明，黑暗便來了。","notes":[]},{"n":27,"t":"我心裏煩擾不安，困苦的日子臨到我身。","notes":[]},{"n":28,"t":"我沒有日光就哀哭行去；我在會中站著求救。","notes":["或譯：我面發黑並非因日曬"]},{"n":29,"t":"我與野狗為弟兄，與鴕鳥為同伴。","notes":[]},{"n":30,"t":"我的皮膚黑而脫落；我的骨頭因熱燒焦。","notes":[]},{"n":31,"t":"所以，我的琴音變為悲音；我的簫聲變為哭聲。","notes":[]}]},"31":{"heading":"","verses":[{"n":1,"t":"我與眼睛立約，怎能戀戀瞻望處女呢？","notes":[]},{"n":2,"t":"從至上的神所得之分，從至高全能者所得之業是甚麼呢？","notes":[]},{"n":3,"t":"豈不是禍患臨到不義的，災害臨到作孽的呢？","notes":[]},{"n":4,"t":"神豈不是察看我的道路，數點我的腳步呢？","notes":[]},{"n":5,"t":"我若與虛謊同行，腳若追隨詭詐；","notes":[]},{"n":6,"t":"我若被公道的天平稱度，使神可以知道我的純正；）","notes":[]},{"n":7,"t":"我的腳步若偏離正路，我的心若隨著我的眼目，若有玷污粘在我手上；","notes":[]},{"n":8,"t":"就願我所種的有別人吃，我田所產的被拔出來。","notes":[]},{"n":9,"t":"我若受迷惑，向婦人起淫念，在鄰舍的門外蹲伏，","notes":[]},{"n":10,"t":"就願我的妻子給別人推磨，別人也與她同室。","notes":[]},{"n":11,"t":"因為這是大罪，是審判官當罰的罪孽。","notes":[]},{"n":12,"t":"這本是火焚燒，直到毀滅，必拔除我所有的家產。","notes":[]},{"n":13,"t":"我的僕婢與我爭辯的時候，我若藐視不聽他們的情節；","notes":[]},{"n":14,"t":"神興起，我怎樣行呢？他察問，我怎樣回答呢？","notes":[]},{"n":15,"t":"造我在腹中的，不也是造他嗎？將他與我摶在腹中的豈不是一位嗎？","notes":[]},{"n":16,"t":"我若不容貧寒人得其所願，或叫寡婦眼中失望，","notes":[]},{"n":17,"t":"或獨自吃我一點食物，孤兒沒有與我同吃；","notes":[]},{"n":18,"t":"從幼年時孤兒與我同長，好像父子一樣；我從出母腹就扶助 寡婦。）","notes":["原文是引領"]},{"n":19,"t":"我若見人因無衣死亡，或見窮乏人身無遮蓋；","notes":[]},{"n":20,"t":"我若不使他因我羊的毛得暖，為我祝福；","notes":[]},{"n":21,"t":"我若在城門口見有幫助我的，舉手攻擊孤兒；","notes":[]},{"n":22,"t":"情願我的肩頭從缺盆骨脫落，我的膀臂從羊矢骨折斷。","notes":[]},{"n":23,"t":"因神降的災禍使我恐懼；因他的威嚴，我不能妄為。","notes":[]},{"n":24,"t":"我若以黃金為指望，對精金說：你是我的倚靠；","notes":[]},{"n":25,"t":"我若因財物豐裕，因我手多得資財而歡喜；","notes":[]},{"n":26,"t":"我若見太陽發光，明月行在空中，","notes":[]},{"n":27,"t":"心就暗暗被引誘，口便親手；","notes":[]},{"n":28,"t":"這也是審判官當罰的罪孽，又是我背棄在上的神。","notes":[]},{"n":29,"t":"我若見恨我的遭報就歡喜，見他遭災便高興；","notes":[]},{"n":30,"t":"我沒有容口犯罪，咒詛他的生命；）","notes":[]},{"n":31,"t":"若我帳棚的人未嘗說，誰不以主人的食物吃飽呢？","notes":[]},{"n":32,"t":"從來我沒有容客旅在街上住宿，卻開門迎接行路的人；）","notes":[]},{"n":33,"t":"我若像亞當 遮掩我的過犯，將罪孽藏在懷中；","notes":["或譯：別人"]},{"n":34,"t":"因懼怕大眾，又因宗族藐視我使我驚恐，以致閉口無言，杜門不出；","notes":[]},{"n":35,"t":"惟願有一位肯聽我！（看哪，在這裏有我所劃的押，願全能者回答我！）","notes":[]},{"n":36,"t":"願那敵我者所寫的狀詞在我這裏！我必帶在肩上，又綁在頭上為冠冕。","notes":[]},{"n":37,"t":"我必向他述說我腳步的數目，必如君王進到他面前。","notes":[]},{"n":38,"t":"我若奪取田地，這地向我喊冤，犂溝一同哭泣；","notes":[]},{"n":39,"t":"我若吃地的出產不給價值，或叫原主喪命；","notes":[]},{"n":40,"t":"願這地長蒺藜代替麥子，長惡草代替大麥。約伯的話說完了。","notes":[]}]},"32":{"heading":"以利戶的話","verses":[{"n":1,"t":"於是這三個人，因約伯自以為義就不再回答他。","notes":[]},{"n":2,"t":"那時有布西人蘭族巴拉迦的兒子以利戶向約伯發怒；因約伯自以為義，不以神為義。","notes":[]},{"n":3,"t":"他又向約伯的三個朋友發怒；因為他們想不出回答的話來，仍以約伯為有罪。","notes":[]},{"n":4,"t":"以利戶要與約伯說話，就等候他們，因為他們比自己年老。","notes":[]},{"n":5,"t":"以利戶見這三個人口中無話回答，就怒氣發作。","notes":[]},{"n":6,"t":"布西人巴拉迦的兒子以利戶回答說：我年輕，你們老邁；因此我退讓，不敢向你們陳說我的意見。","notes":[]},{"n":7,"t":"我說，年老的當先說話；壽高的當以智慧教訓人。","notes":[]},{"n":8,"t":"但在人裏面有靈；全能者的氣使人有聰明。","notes":[]},{"n":9,"t":"尊貴的不都有智慧；壽高的不都能明白公平。","notes":[]},{"n":10,"t":"因此我說：你們要聽我言；我也要陳說我的意見。","notes":[]},{"n":11,"t":"你們查究所要說的話；那時我等候你們的話，側耳聽你們的辯論，","notes":[]},{"n":12,"t":"留心聽你們；誰知你們中間無一人折服約伯，駁倒他的話。","notes":[]},{"n":13,"t":"你們切不可說：我們尋得智慧；神能勝他，人卻不能。","notes":[]},{"n":14,"t":"約伯沒有向我爭辯；我也不用你們的話回答他。","notes":[]},{"n":15,"t":"他們驚奇不再回答，一言不發。","notes":[]},{"n":16,"t":"我豈因他們不說話，站住不再回答，仍舊等候呢？","notes":[]},{"n":17,"t":"我也要回答我的一分話，陳說我的意見。","notes":[]},{"n":18,"t":"因為我的言語滿懷；我裏面的靈激動我。","notes":[]},{"n":19,"t":"我的胸懷如盛酒之囊沒有出氣之縫，又如新皮袋快要破裂。","notes":[]},{"n":20,"t":"我要說話，使我舒暢；我要開口回答。","notes":[]},{"n":21,"t":"我必不看人的情面，也不奉承人。","notes":[]},{"n":22,"t":"我不曉得奉承；若奉承，造我的主必快快除滅我。","notes":[]}]},"33":{"heading":"","verses":[{"n":1,"t":"約伯啊，請聽我的話，留心聽我一切的言語。","notes":[]},{"n":2,"t":"我現在開口，用舌發言。","notes":[]},{"n":3,"t":"我的言語要發明心中所存的正直；我所知道的，我嘴唇要誠實地說出。","notes":[]},{"n":4,"t":"神的靈造我；全能者的氣使我得生。","notes":[]},{"n":5,"t":"你若回答我，就站起來，在我面前陳明。","notes":[]},{"n":6,"t":"我在神面前與你一樣，也是用土造成。","notes":[]},{"n":7,"t":"我不用威嚴驚嚇你，也不用勢力重壓你。","notes":[]},{"n":8,"t":"你所說的，我聽見了，也聽見你的言語，說：","notes":[]},{"n":9,"t":"我是清潔無過的，我是無辜的；在我裏面也沒有罪孽。","notes":[]},{"n":10,"t":"神找機會攻擊我，以我為仇敵，","notes":[]},{"n":11,"t":"把我的腳上了木狗，窺察我一切的道路。","notes":[]},{"n":12,"t":"我要回答你說：你這話無理，因神比世人更大。","notes":[]},{"n":13,"t":"你為何與他爭論呢？因他的事都不對人解說？","notes":[]},{"n":14,"t":"神說一次、兩次，世人卻不理會。","notes":[]},{"n":15,"t":"人躺在床上沉睡的時候，神就用夢和夜間的異象，","notes":[]},{"n":16,"t":"開通他們的耳朵，將當受的教訓印在他們心上，","notes":[]},{"n":17,"t":"好叫人不從自己的謀算，不行驕傲的事，","notes":["原文是將驕傲向人隱藏"]},{"n":18,"t":"攔阻人不陷於坑裏，不死在刀下。","notes":[]},{"n":19,"t":"人在床上被懲治，骨頭中不住地疼痛，","notes":[]},{"n":20,"t":"以致他的口厭棄食物，心厭惡美味。","notes":[]},{"n":21,"t":"他的肉消瘦，不得再見；先前不見的骨頭都凸出來。","notes":[]},{"n":22,"t":"他的靈魂臨近深坑；他的生命近於滅命的。","notes":[]},{"n":23,"t":"一千天使中，若有一個作傳話的與神同在，指示人所當行的事，","notes":[]},{"n":24,"t":"神就給他開恩，說：救贖他免得下坑；我已經得了贖價。","notes":[]},{"n":25,"t":"他的肉要比孩童的肉更嫩；他就返老還童。","notes":[]},{"n":26,"t":"他禱告神，神就喜悅他，使他歡呼朝見神的面；神又看他為義。","notes":[]},{"n":27,"t":"他在人前歌唱說：我犯了罪，顛倒是非，這竟與我無益。","notes":[]},{"n":28,"t":"神救贖我的靈魂免入深坑；我的生命也必見光。","notes":[]},{"n":29,"t":"神兩次、三次向人行這一切的事，","notes":[]},{"n":30,"t":"為要從深坑救回人的靈魂，使他被光照耀，與活人一樣。","notes":[]},{"n":31,"t":"約伯啊，你當側耳聽我的話，不要作聲，等我講說。","notes":[]},{"n":32,"t":"你若有話說，就可以回答我；你只管說，因我願以你為是。","notes":[]},{"n":33,"t":"若不然，你就聽我說；你不要作聲，我便將智慧教訓你。","notes":[]}]},"34":{"heading":"","verses":[{"n":1,"t":"以利戶又說：","notes":[]},{"n":2,"t":"你們智慧人要聽我的話；有知識的人要留心聽我說。","notes":[]},{"n":3,"t":"因為耳朵試驗話語，好像上膛嘗食物。","notes":[]},{"n":4,"t":"我們當選擇何為是，彼此知道何為善。","notes":[]},{"n":5,"t":"約伯曾說：我是公義，神奪去我的理；","notes":[]},{"n":6,"t":"我雖有理，還算為說謊言的；我雖無過，受的傷還不能醫治。","notes":[]},{"n":7,"t":"誰像約伯，喝譏誚如同喝水呢？","notes":[]},{"n":8,"t":"他與作孽的結伴，和惡人同行。","notes":[]},{"n":9,"t":"他說：人以神為樂，總是無益。","notes":[]},{"n":10,"t":"所以，你們明理的人要聽我的話。神斷不致行惡；全能者斷不致作孽。","notes":[]},{"n":11,"t":"他必按人所做的報應人，使各人照所行的得報。","notes":[]},{"n":12,"t":"神必不作惡；全能者也不偏離公平。","notes":[]},{"n":13,"t":"誰派他治理地，安定全世界呢？","notes":[]},{"n":14,"t":"他若專心為己，將靈和氣收歸自己，","notes":[]},{"n":15,"t":"凡有血氣的就必一同死亡；世人必仍歸塵土。","notes":[]},{"n":16,"t":"你若明理，就當聽我的話，留心聽我言語的聲音。","notes":[]},{"n":17,"t":"難道恨惡公平的可以掌權嗎？那有公義的、有大能的，豈可定他有罪嗎？","notes":[]},{"n":18,"t":"他對君王說：你是鄙陋的；對貴臣說：你是邪惡的。","notes":[]},{"n":19,"t":"他待王子不徇情面，也不看重富足的過於貧窮的，因為都是他手所造。","notes":[]},{"n":20,"t":"在轉眼之間，半夜之中，他們就死亡。百姓被震動而去世；有權力的被奪去非借人手。","notes":[]},{"n":21,"t":"神注目觀看人的道路，看明人的腳步。","notes":[]},{"n":22,"t":"沒有黑暗、陰翳能給作孽的藏身。","notes":[]},{"n":23,"t":"神審判人，不必使人到他面前再三鑒察。","notes":[]},{"n":24,"t":"他用難測之法打破有能力的人，設立別人代替他們。","notes":[]},{"n":25,"t":"他原知道他們的行為，使他們在夜間傾倒滅亡。","notes":[]},{"n":26,"t":"他在眾人眼前擊打他們，如同擊打惡人一樣。","notes":[]},{"n":27,"t":"因為他們偏行不跟從他，也不留心他的道，","notes":[]},{"n":28,"t":"甚至使貧窮人的哀聲達到他那裏；他也聽了困苦人的哀聲。","notes":[]},{"n":29,"t":"他使人安靜，誰能擾亂呢？他掩面，誰能見他呢？無論待一國或一人都是如此－","notes":["或譯：定罪"]},{"n":30,"t":"使不虔敬的人不得作王，免得有人牢籠百姓。","notes":[]},{"n":31,"t":"有誰對神說：我受了責罰，不再犯罪；","notes":[]},{"n":32,"t":"我所看不明的，求你指教我；我若作了孽，必不再作？","notes":[]},{"n":33,"t":"他施行報應，豈要隨你的心願、叫你推辭不受嗎？選定的是你，不是我。你所知道的只管說吧！","notes":[]},{"n":34,"t":"明理的人和聽我話的智慧人必對我說：","notes":[]},{"n":35,"t":"約伯說話沒有知識，言語中毫無智慧。","notes":[]},{"n":36,"t":"願約伯被試驗到底，因他回答像惡人一樣。","notes":[]},{"n":37,"t":"他在罪上又加悖逆；在我們中間拍手，用許多言語輕慢神。","notes":[]}]},"35":{"heading":"","verses":[{"n":1,"t":"以利戶又說：","notes":[]},{"n":2,"t":"你以為有理，或以為你的公義勝於神的公義，","notes":[]},{"n":3,"t":"才說這與我有甚麼益處？我不犯罪比犯罪有甚麼好處呢？","notes":[]},{"n":4,"t":"我要回答你和在你這裏的朋友。","notes":[]},{"n":5,"t":"你要向天觀看，瞻望那高於你的穹蒼。","notes":[]},{"n":6,"t":"你若犯罪，能使神受何害呢？你的過犯加增，能使神受何損呢？","notes":[]},{"n":7,"t":"你若是公義，還能加增他甚麼呢？他從你手裏還接受甚麼呢？","notes":[]},{"n":8,"t":"你的過惡或能害你這類的人；你的公義或能叫世人得益處。","notes":[]},{"n":9,"t":"人因多受欺壓就哀求，因受能者的轄制便求救，","notes":["原文是膀臂"]},{"n":10,"t":"卻無人說：造我的神在哪裏？他使人夜間歌唱，","notes":[]},{"n":11,"t":"教訓我們勝於地上的走獸，使我們有聰明勝於空中的飛鳥。","notes":[]},{"n":12,"t":"他們在那裏，因惡人的驕傲呼求，卻無人答應。","notes":[]},{"n":13,"t":"虛妄的呼求，神必不垂聽；全能者也必不眷顧。","notes":[]},{"n":14,"t":"何況你說，你不得見他；你的案件在他面前，你等候他吧。","notes":[]},{"n":15,"t":"但如今因他未曾發怒降罰，也不甚理會狂傲，","notes":[]},{"n":16,"t":"所以約伯開口說虛妄的話，多發無知識的言語。","notes":[]}]},"36":{"heading":"","verses":[{"n":1,"t":"以利戶又接著說：","notes":[]},{"n":2,"t":"你再容我片時，我就指示你，因我還有話為神說。","notes":[]},{"n":3,"t":"我要將所知道的從遠處引來，將公義歸給造我的主。","notes":[]},{"n":4,"t":"我的言語真不虛謊；有知識全備的與你同在。","notes":[]},{"n":5,"t":"神有大能，並不藐視人；他的智慧甚廣。","notes":[]},{"n":6,"t":"他不保護惡人的性命，卻為困苦人伸冤。","notes":[]},{"n":7,"t":"他時常看顧義人，使他們和君王同坐寶座，永遠要被高舉。","notes":[]},{"n":8,"t":"他們若被鎖鍊捆住，被苦難的繩索纏住，","notes":[]},{"n":9,"t":"他就把他們的作為和過犯指示他們，叫他們知道有驕傲的行動。","notes":[]},{"n":10,"t":"他也開通他們的耳朵得受教訓，吩咐他們離開罪孽轉回。","notes":[]},{"n":11,"t":"他們若聽從事奉他，就必度日亨通，歷年福樂；","notes":[]},{"n":12,"t":"若不聽從，就要被刀殺滅，無知無識而死。","notes":[]},{"n":13,"t":"那心中不敬虔的人積蓄怒氣；神捆綁他們，他們竟不求救；","notes":[]},{"n":14,"t":"必在青年時死亡，與污穢人一樣喪命。","notes":[]},{"n":15,"t":"神藉著困苦救拔困苦人，趁他們受欺壓開通他們的耳朵。","notes":[]},{"n":16,"t":"神也必引你出離患難，進入寬闊不狹窄之地；擺在你席上的必滿有肥甘。","notes":[]},{"n":17,"t":"但你滿口有惡人批評的言語；判斷和刑罰抓住你。","notes":[]},{"n":18,"t":"不可容忿怒觸動你，使你不服責罰；也不可因贖價大就偏行。","notes":[]},{"n":19,"t":"你的呼求，或是你一切的勢力，果有靈驗，叫你不受患難嗎？","notes":["或譯：資財"]},{"n":20,"t":"不要切慕黑夜，就是眾民在本處被除滅的時候。","notes":[]},{"n":21,"t":"你要謹慎，不可重看罪孽，因你選擇罪孽過於選擇苦難。","notes":[]},{"n":22,"t":"神行事有高大的能力；教訓人的有誰像他呢？","notes":[]},{"n":23,"t":"誰派定他的道路？誰能說：你所行的不義？","notes":[]},{"n":24,"t":"你不可忘記稱讚他所行的為大，就是人所歌頌的。","notes":[]},{"n":25,"t":"他所行的，萬人都看見；世人也從遠處觀看。","notes":[]},{"n":26,"t":"神為大，我們不能全知；他的年數不能測度。","notes":[]},{"n":27,"t":"他吸取水點，這水點從雲霧中就變成雨；","notes":[]},{"n":28,"t":"雲彩將雨落下，沛然降與世人。","notes":[]},{"n":29,"t":"誰能明白雲彩如何鋪張，和神行宮的雷聲呢？","notes":[]},{"n":30,"t":"他將亮光普照在自己的四圍；他又遮覆海底。","notes":[]},{"n":31,"t":"他用這些審判眾民，且賜豐富的糧食。","notes":[]},{"n":32,"t":"他以電光遮手，命閃電擊中敵人。","notes":["或譯：中了靶子"]},{"n":33,"t":"所發的雷聲顯明他的作為，又向牲畜指明要起暴風。","notes":[]}]},"37":{"heading":"","verses":[{"n":1,"t":"因此我心戰兢，從原處移動。","notes":[]},{"n":2,"t":"聽啊，神轟轟的聲音是他口中所發的響聲。","notes":[]},{"n":3,"t":"他發響聲震遍天下，發電光閃到地極。","notes":[]},{"n":4,"t":"隨後人聽見有雷聲轟轟，大發威嚴，雷電接連不斷。","notes":[]},{"n":5,"t":"神發出奇妙的雷聲；他行大事，我們不能測透。","notes":[]},{"n":6,"t":"他對雪說：要降在地上；對大雨和暴雨也是這樣說。","notes":[]},{"n":7,"t":"他封住各人的手，叫所造的萬人都曉得他的作為。","notes":[]},{"n":8,"t":"百獸進入穴中，臥在洞內。","notes":[]},{"n":9,"t":"暴風出於南宮；寒冷出於北方。","notes":[]},{"n":10,"t":"神噓氣成冰；寬闊之水也都凝結。","notes":[]},{"n":11,"t":"他使密雲盛滿水氣，布散電光之雲；","notes":[]},{"n":12,"t":"這雲是藉他的指引游行旋轉，得以在全地面上行他一切所吩咐的，","notes":[]},{"n":13,"t":"或為責罰，或為潤地，或為施行慈愛。","notes":[]},{"n":14,"t":"約伯啊，你要留心聽，要站立思想神奇妙的作為。","notes":[]},{"n":15,"t":"神如何吩咐這些，如何使雲中的電光照耀，你知道嗎？","notes":[]},{"n":16,"t":"雲彩如何浮於空中，那知識全備者奇妙的作為，你知道嗎？","notes":[]},{"n":17,"t":"南風使地寂靜，你的衣服就如火熱，你知道嗎？","notes":[]},{"n":18,"t":"你豈能與神同鋪穹蒼嗎？這穹蒼堅硬，如同鑄成的鏡子。","notes":[]},{"n":19,"t":"我們愚昧不能陳說；請你指教我們該對他說甚麼話。","notes":[]},{"n":20,"t":"人豈可說：我願與他說話？豈有人自願滅亡嗎？","notes":[]},{"n":21,"t":"現在有雲遮蔽，人不得見穹蒼的光亮；但風吹過，天又發晴。","notes":[]},{"n":22,"t":"金光出於北方，在神那裏有可怕的威嚴。","notes":[]},{"n":23,"t":"論到全能者，我們不能測度；他大有能力，有公平和大義，必不苦待人。","notes":[]},{"n":24,"t":"所以，人敬畏他；凡自以為心中有智慧的人，他都不顧念。","notes":[]}]},"38":{"heading":"耶和華回答約伯","verses":[{"n":1,"t":"那時，耶和華從旋風中回答約伯說：","notes":[]},{"n":2,"t":"誰用無知的言語使我的旨意暗昧不明？","notes":[]},{"n":3,"t":"你要如勇士束腰；我問你，你可以指示我。","notes":[]},{"n":4,"t":"我立大地根基的時候，你在哪裏呢？你若有聰明，只管說吧！","notes":[]},{"n":5,"t":"你若曉得就說，是誰定地的尺度？是誰把準繩拉在其上？","notes":[]},{"n":6,"t":"地的根基安置在何處？地的角石是誰安放的？","notes":[]},{"n":7,"t":"那時，晨星一同歌唱；神的眾子也都歡呼。","notes":[]},{"n":8,"t":"海水衝出，如出胎胞，那時誰將它關閉呢？","notes":[]},{"n":9,"t":"是我用雲彩當海的衣服，用幽暗當包裹它的布，","notes":[]},{"n":10,"t":"為它定界限，又安門和閂，","notes":[]},{"n":11,"t":"說：你只可到這裏，不可越過；你狂傲的浪要到此止住。","notes":[]},{"n":12,"t":"你自生以來，曾命定晨光，使清晨的日光知道本位，","notes":[]},{"n":13,"t":"叫這光普照地的四極，將惡人從其中驅逐出來嗎？","notes":[]},{"n":14,"t":"因這光，地面改變如泥上印印，萬物出現如衣服一樣。","notes":[]},{"n":15,"t":"亮光不照惡人；強橫的膀臂也必折斷。","notes":[]},{"n":16,"t":"你曾進到海源，或在深淵的隱密處行走嗎？","notes":[]},{"n":17,"t":"死亡的門曾向你顯露嗎？死蔭的門你曾見過嗎？","notes":[]},{"n":18,"t":"地的廣大你能明透嗎？你若全知道，只管說吧！","notes":[]},{"n":19,"t":"光明的居所從何而至？黑暗的本位在於何處？","notes":[]},{"n":20,"t":"你能帶到本境，能看明其室之路嗎？","notes":[]},{"n":21,"t":"你總知道，因為你早已生在世上，你日子的數目也多。","notes":[]},{"n":22,"t":"你曾進入雪庫，或見過雹倉嗎？","notes":[]},{"n":23,"t":"這雪雹乃是我為降災，並打仗和爭戰的日子所預備的。","notes":[]},{"n":24,"t":"光亮從何路分開？東風從何路分散遍地？","notes":[]},{"n":25,"t":"誰為雨水分道？誰為雷電開路？","notes":[]},{"n":26,"t":"使雨降在無人之地、無人居住的曠野？","notes":[]},{"n":27,"t":"使荒廢淒涼之地得以豐足，青草得以發生？","notes":[]},{"n":28,"t":"雨有父嗎？露水珠是誰生的呢？","notes":[]},{"n":29,"t":"冰出於誰的胎？天上的霜是誰生的呢？","notes":[]},{"n":30,"t":"諸水堅硬如石頭；深淵之面凝結成冰。","notes":["或譯：隱藏"]},{"n":31,"t":"你能繫住昴星的結嗎？能解開參星的帶嗎？","notes":[]},{"n":32,"t":"你能按時領出十二宮嗎？能引導北斗和隨它的眾星嗎？","notes":["星：原文是子"]},{"n":33,"t":"你知道天的定例嗎？能使地歸在天的權下嗎？","notes":[]},{"n":34,"t":"你能向雲彩揚起聲來，使傾盆的雨遮蓋你嗎？","notes":[]},{"n":35,"t":"你能發出閃電，叫它行去，使它對你說：我們在這裏？","notes":[]},{"n":36,"t":"誰將智慧放在懷中？誰將聰明賜於心內？","notes":[]},{"n":37,"t":"誰能用智慧數算雲彩呢？塵土聚集成團，土塊緊緊結連；那時，誰能傾倒天上的瓶呢？","notes":[],"end":38},{"n":39,"t":"母獅子在洞中蹲伏，少壯獅子在隱密處埋伏；你能為牠們抓取食物，使牠們飽足嗎？","notes":[],"end":40},{"n":41,"t":"烏鴉之雛因無食物飛來飛去，哀告神；那時，誰為牠預備食物呢？","notes":[]}]},"39":{"heading":"","verses":[{"n":1,"t":"山巖間的野山羊幾時生產，你知道嗎？母鹿下犢之期，你能察定嗎？","notes":[]},{"n":2,"t":"牠們懷胎的月數，你能數算嗎？牠們幾時生產，你能曉得嗎？","notes":[]},{"n":3,"t":"牠們屈身，將子生下，就除掉疼痛。","notes":[]},{"n":4,"t":"這子漸漸肥壯，在荒野長大，去而不回。","notes":[]},{"n":5,"t":"誰放野驢出去自由？誰解開快驢的繩索？","notes":[]},{"n":6,"t":"我使曠野作牠的住處，使鹹地當牠的居所。","notes":[]},{"n":7,"t":"牠嗤笑城內的喧嚷，不聽趕牲口的喝聲。","notes":[]},{"n":8,"t":"遍山是牠的草場；牠尋找各樣青綠之物。","notes":[]},{"n":9,"t":"野牛豈肯服事你？豈肯住在你的槽旁？","notes":[]},{"n":10,"t":"你豈能用套繩將野牛籠在犂溝之間？牠豈肯隨你耙山谷之地？","notes":[]},{"n":11,"t":"豈可因牠的力大就倚靠牠？豈可把你的工交給牠做嗎？","notes":[]},{"n":12,"t":"豈可信靠牠把你的糧食運到家，又收聚你禾場上的穀嗎？","notes":[]},{"n":13,"t":"鴕鳥的翅膀歡然搧展，豈是顯慈愛的翎毛和羽毛嗎？","notes":[]},{"n":14,"t":"因牠把蛋留在地上，在塵土中使得溫暖；","notes":[]},{"n":15,"t":"卻想不到被腳踹碎，或被野獸踐踏。","notes":[]},{"n":16,"t":"牠忍心待雛，似乎不是自己的；雖然徒受勞苦，也不為雛懼怕；","notes":[]},{"n":17,"t":"因為神使牠沒有智慧，也未將悟性賜給牠。","notes":[]},{"n":18,"t":"牠幾時挺身展開翅膀，就嗤笑馬和騎馬的人。","notes":[]},{"n":19,"t":"馬的大力是你所賜的嗎？牠頸項上挓挲的騌是你給牠披上的嗎？","notes":[]},{"n":20,"t":"是你叫牠跳躍像蝗蟲嗎？牠噴氣之威使人驚惶。","notes":[]},{"n":21,"t":"牠在谷中刨地，自喜其力；牠出去迎接佩帶兵器的人。","notes":[]},{"n":22,"t":"牠嗤笑可怕的事並不驚惶，也不因刀劍退回。","notes":[]},{"n":23,"t":"箭袋和發亮的槍，並短槍在牠身上錚錚有聲。","notes":[]},{"n":24,"t":"牠發猛烈的怒氣將地吞下；一聽角聲就不耐站立。","notes":[]},{"n":25,"t":"角每發聲，牠說呵哈；牠從遠處聞著戰氣，又聽見軍長大發雷聲和兵丁吶喊。","notes":[]},{"n":26,"t":"鷹雀飛翔，展開翅膀一直向南，豈是藉你的智慧嗎？","notes":[]},{"n":27,"t":"大鷹上騰在高處搭窩，豈是聽你的吩咐嗎？","notes":[]},{"n":28,"t":"牠住在山巖，以山峰和堅固之所為家，","notes":[]},{"n":29,"t":"從那裏窺看食物，眼睛遠遠觀望。","notes":[]},{"n":30,"t":"牠的雛也咂血；被殺的人在哪裏，牠也在那裏。","notes":[]}]},"40":{"heading":"","verses":[{"n":1,"t":"耶和華又對約伯說：","notes":[]},{"n":2,"t":"強辯的豈可與全能者爭論嗎？與神辯駁的可以回答這些吧！","notes":[]},{"n":3,"t":"於是，約伯回答耶和華說：","notes":[]},{"n":4,"t":"我是卑賤的！我用甚麼回答你呢？只好用手摀口。","notes":[]},{"n":5,"t":"我說了一次，再不回答；說了兩次，就不再說。","notes":[]},{"n":6,"t":"於是，耶和華從旋風中回答約伯說：","notes":[]},{"n":7,"t":"你要如勇士束腰；我問你，你可以指示我。","notes":[]},{"n":8,"t":"你豈可廢棄我所擬定的？豈可定我有罪，好顯自己為義嗎？","notes":[]},{"n":9,"t":"你有神那樣的膀臂嗎？你能像他發雷聲嗎？","notes":[]},{"n":10,"t":"你要以榮耀莊嚴為妝飾，以尊榮威嚴為衣服；","notes":[]},{"n":11,"t":"要發出你滿溢的怒氣，見一切驕傲的人，使他降卑；","notes":[]},{"n":12,"t":"見一切驕傲的人，將他制伏，把惡人踐踏在本處；","notes":[]},{"n":13,"t":"將他們一同隱藏在塵土中，把他們的臉蒙蔽在隱密處；","notes":[]},{"n":14,"t":"我就認你右手能以救自己。","notes":[]},{"n":15,"t":"你且觀看河馬；我造你也造牠。牠吃草與牛一樣；","notes":[]},{"n":16,"t":"牠的氣力在腰間，能力在肚腹的筋上。","notes":[]},{"n":17,"t":"牠搖動尾巴如香柏樹；牠大腿的筋互相聯絡。","notes":[]},{"n":18,"t":"牠的骨頭好像銅管；牠的肢體彷彿鐵棍。","notes":[]},{"n":19,"t":"牠在神所造的物中為首；創造牠的給牠刀劍。","notes":[]},{"n":20,"t":"諸山給牠出食物，也是百獸遊玩之處。","notes":[]},{"n":21,"t":"牠伏在蓮葉之下，臥在蘆葦隱密處和水窪子裏。","notes":[]},{"n":22,"t":"蓮葉的陰涼遮蔽牠；溪旁的柳樹環繞牠。","notes":[]},{"n":23,"t":"河水泛濫，牠不發戰；就是約旦河的水漲到牠口邊，也是安然。","notes":[]},{"n":24,"t":"在牠防備的時候，誰能捉拿牠？誰能牢籠牠穿牠的鼻子呢？","notes":[]}]},"41":{"heading":"","verses":[{"n":1,"t":"你能用魚鉤釣上鱷魚嗎？能用繩子壓下牠的舌頭嗎？","notes":[]},{"n":2,"t":"你能用繩索穿牠的鼻子嗎？能用鉤穿牠的腮骨嗎？","notes":[]},{"n":3,"t":"牠豈向你連連懇求，說柔和的話嗎？","notes":[]},{"n":4,"t":"豈肯與你立約，使你拿牠永遠作奴僕嗎？","notes":[]},{"n":5,"t":"你豈可拿牠當雀鳥玩耍嗎？豈可為你的幼女將牠拴住嗎？","notes":[]},{"n":6,"t":"搭夥的漁夫豈可拿牠當貨物嗎？能把牠分給商人嗎？","notes":[]},{"n":7,"t":"你能用倒鉤槍扎滿牠的皮，能用魚叉叉滿牠的頭嗎？","notes":[]},{"n":8,"t":"你按手在牠身上，想與牠爭戰，就不再這樣行吧！","notes":[]},{"n":9,"t":"人指望捉拿牠是徒然的；一見牠，豈不喪膽嗎？","notes":[]},{"n":10,"t":"沒有那麼兇猛的人敢惹牠。這樣，誰能在我面前站立得住呢？","notes":[]},{"n":11,"t":"誰先給我甚麼，使我償還呢？天下萬物都是我的。","notes":[]},{"n":12,"t":"論到鱷魚的肢體和其大力，並美好的骨骼，我不能緘默不言。","notes":[]},{"n":13,"t":"誰能剝牠的外衣？誰能進牠上下牙骨之間呢？","notes":[]},{"n":14,"t":"誰能開牠的腮頰？牠牙齒四圍是可畏的。","notes":[]},{"n":15,"t":"牠以堅固的鱗甲為可誇，緊緊合閉，封得嚴密。","notes":[]},{"n":16,"t":"這鱗甲一一相連，甚至氣不得透入其間，","notes":[]},{"n":17,"t":"都是互相聯絡、膠結，不能分離。","notes":[]},{"n":18,"t":"牠打噴嚏就發出光來；牠眼睛好像早晨的光線。","notes":["原文是眼皮"]},{"n":19,"t":"從牠口中發出燒著的火把，與飛迸的火星；","notes":[]},{"n":20,"t":"從牠鼻孔冒出煙來，如燒開的鍋和點著的蘆葦。","notes":[]},{"n":21,"t":"牠的氣點著煤炭，有火焰從牠口中發出。","notes":[]},{"n":22,"t":"牠頸項中存著勁力；在牠面前的都恐嚇蹦跳。","notes":[]},{"n":23,"t":"牠的肉塊互相聯絡，緊貼其身，不能搖動。","notes":[]},{"n":24,"t":"牠的心結實如石頭，如下磨石那樣結實。","notes":[]},{"n":25,"t":"牠一起來，勇士都驚恐，心裏慌亂，便都昏迷。","notes":[]},{"n":26,"t":"人若用刀，用槍，用標槍，用尖槍扎牠，都是無用。","notes":[]},{"n":27,"t":"牠以鐵為乾草，以銅為爛木。","notes":[]},{"n":28,"t":"箭不能恐嚇牠使牠逃避；彈石在牠看為碎稭。","notes":[]},{"n":29,"t":"棍棒算為禾稭；牠嗤笑短槍颼的響聲。","notes":[]},{"n":30,"t":"牠肚腹下如尖瓦片；牠如釘耙經過淤泥。","notes":[]},{"n":31,"t":"牠使深淵開滾如鍋，使洋海如鍋中的膏油。","notes":[]},{"n":32,"t":"牠行的路隨後發光，令人想深淵如同白髮。","notes":[]},{"n":33,"t":"在地上沒有像牠造的那樣，無所懼怕。","notes":[]},{"n":34,"t":"凡高大的，牠無不藐視；牠在驕傲的水族上作王。","notes":[]}]},"42":{"heading":"結尾","verses":[{"n":1,"t":"約伯回答耶和華說：","notes":[]},{"n":2,"t":"我知道，你萬事都能做；你的旨意不能攔阻。","notes":[]},{"n":3,"t":"誰用無知的言語使你的旨意隱藏呢？我所說的是我不明白的；這些事太奇妙，是我不知道的。","notes":[]},{"n":4,"t":"求你聽我，我要說話；我問你，求你指示我。","notes":[]},{"n":5,"t":"我從前風聞有你，現在親眼看見你。","notes":[]},{"n":6,"t":"因此我厭惡自己，在塵土和爐灰中懊悔。","notes":["或譯：我的言語"]},{"n":7,"t":"耶和華對約伯說話以後，就對提幔人以利法說：「我的怒氣向你和你兩個朋友發作，因為你們議論我不如我的僕人約伯說的是。","notes":[]},{"n":8,"t":"現在你們要取七隻公牛，七隻公羊，到我僕人約伯那裏去，為自己獻上燔祭，我的僕人約伯就為你們祈禱。我因悅納他，就不按你們的愚妄辦你們。你們議論我，不如我的僕人約伯說的是。」","notes":[]},{"n":9,"t":"於是提幔人以利法、書亞人比勒達、拿瑪人瑣法照著耶和華所吩咐的去行；耶和華就悅納約伯。","notes":[]},{"n":10,"t":"約伯為他的朋友祈禱。耶和華就使約伯從苦境轉回，並且耶和華賜給他的比他從前所有的加倍。","notes":["原文是擄掠"]},{"n":11,"t":"約伯的弟兄、姊妹，和以先所認識的人都來見他，在他家裏一同吃飯；又論到耶和華所降與他的一切災禍，都為他悲傷安慰他。每人也送他一塊銀子和一個金環。","notes":[]},{"n":12,"t":"這樣，耶和華後來賜福給約伯比先前更多。他有一萬四千羊，六千駱駝，一千對牛，一千母驢。","notes":[]},{"n":13,"t":"他也有七個兒子，三個女兒。","notes":[]},{"n":14,"t":"他給長女起名叫耶米瑪，次女叫基洗亞，三女叫基連‧哈樸。","notes":[]},{"n":15,"t":"在那全地的婦女中找不著像約伯的女兒那樣美貌。她們的父親使她們在弟兄中得產業。","notes":[]},{"n":16,"t":"此後，約伯又活了一百四十年，得見他的兒孫，直到四代。","notes":[]},{"n":17,"t":"這樣，約伯年紀老邁，日子滿足而死。","notes":[]}]}},"PSA":{"1":{"heading":"真福","verses":[{"n":1,"t":"不從惡人的計謀，不站罪人的道路，不坐褻慢人的座位，","notes":[]},{"n":2,"t":"惟喜愛耶和華的律法，晝夜思想，這人便為有福！","notes":[]},{"n":3,"t":"他要像一棵樹栽在溪水旁，按時候結果子，葉子也不枯乾。凡他所做的盡都順利。","notes":[]},{"n":4,"t":"惡人並不是這樣，乃像糠秕被風吹散。","notes":[]},{"n":5,"t":"因此，當審判的時候，惡人必站立不住；罪人在義人的會中也是如此。","notes":[]},{"n":6,"t":"因為耶和華知道義人的道路；惡人的道路卻必滅亡。","notes":[]}]},"2":{"heading":"神所揀選的君王","verses":[{"n":1,"t":"外邦為甚麼爭鬧？萬民為甚麼謀算虛妄的事？","notes":[]},{"n":2,"t":"世上的君王一齊起來，臣宰一同商議，要敵擋耶和華並他的受膏者，","notes":[]},{"n":3,"t":"說：我們要掙開他們的捆綁，脫去他們的繩索。","notes":[]},{"n":4,"t":"那坐在天上的必發笑；主必嗤笑他們。","notes":[]},{"n":5,"t":"那時，他要在怒中責備他們，在烈怒中驚嚇他們，","notes":[]},{"n":6,"t":"說：我已經立我的君在錫安－我的聖山上了。","notes":[]},{"n":7,"t":"受膏者說：我要傳聖旨。耶和華曾對我說：你是我的兒子，我今日生你。","notes":[]},{"n":8,"t":"你求我，我就將列國賜你為基業，將地極賜你為田產。","notes":[]},{"n":9,"t":"你必用鐵杖打破他們；你必將他們如同窯匠的瓦器摔碎。","notes":[]},{"n":10,"t":"現在，你們君王應當省悟！你們世上的審判官該受管教！","notes":[]},{"n":11,"t":"當存畏懼事奉耶和華，又當存戰兢而快樂。","notes":[]},{"n":12,"t":"當以嘴親子，恐怕他發怒，你們便在道中滅亡，因為他的怒氣快要發作。凡投靠他的，都是有福的。","notes":[]}]},"3":{"heading":"求助的晨禱","verses":[{"n":1,"t":"耶和華啊，我的敵人何其加增；有許多人起來攻擊我。","notes":[]},{"n":2,"t":"有許多人議論我說：他得不著神的幫助。 （細拉）","notes":[]},{"n":3,"t":"但你－耶和華是我四圍的盾牌，是我的榮耀，又是叫我抬起頭來的。","notes":[]},{"n":4,"t":"我用我的聲音求告耶和華，他就從他的聖山上應允我。 （細拉）","notes":[]},{"n":5,"t":"我躺下睡覺，我醒著，耶和華都保佑我。","notes":[]},{"n":6,"t":"雖有成萬的百姓來周圍攻擊我，我也不怕。","notes":[]},{"n":7,"t":"耶和華啊，求你起來！我的神啊，求你救我！因為你打了我一切仇敵的腮骨，敲碎了惡人的牙齒。","notes":[]},{"n":8,"t":"救恩屬乎耶和華；願你賜福給你的百姓。（細拉）","notes":[]}]},"4":{"heading":"求助的晚禱","verses":[{"n":1,"t":"顯我為義的神啊，我呼籲的時候，求你應允我！我在困苦中，你曾使我寬廣；現在求你憐恤我，聽我的禱告！","notes":[]},{"n":2,"t":"你們這上流人哪，你們將我的尊榮變為羞辱要到幾時呢？你們喜愛虛妄，尋找虛假，要到幾時呢？（細拉）","notes":[]},{"n":3,"t":"你們要知道，耶和華已經分別虔誠人歸他自己；我求告耶和華，他必聽我。","notes":[]},{"n":4,"t":"你們應當畏懼，不可犯罪；在床上的時候，要心裏思想，並要肅靜。（細拉）","notes":[]},{"n":5,"t":"當獻上公義的祭，又當倚靠耶和華。","notes":[]},{"n":6,"t":"有許多人說：誰能指示我們甚麼好處？耶和華啊，求你仰起臉來，光照我們。","notes":[]},{"n":7,"t":"你使我心裏快樂，勝過那豐收五穀新酒的人。","notes":[]},{"n":8,"t":"我必安然躺下睡覺，因為獨有你－耶和華使我安然居住。","notes":[]}]},"5":{"heading":"求主保護","verses":[{"n":1,"t":"耶和華啊，求你留心聽我的言語，顧念我的心思！","notes":[]},{"n":2,"t":"我的王我的神啊，求你垂聽我呼求的聲音！因為我向你祈禱。","notes":[]},{"n":3,"t":"耶和華啊，早晨你必聽我的聲音；早晨我必向你陳明我的心意，並要警醒！","notes":[]},{"n":4,"t":"因為你不是喜悅惡事的神，惡人不能與你同居。","notes":[]},{"n":5,"t":"狂傲人不能站在你眼前；凡作孽的，都是你所恨惡的。","notes":[]},{"n":6,"t":"說謊言的，你必滅絕；好流人血弄詭詐的，都為耶和華所憎惡。","notes":[]},{"n":7,"t":"至於我，我必憑你豐盛的慈愛進入你的居所；我必存敬畏你的心向你的聖殿下拜。","notes":[]},{"n":8,"t":"耶和華啊，求你因我的仇敵，憑你的公義引領我，使你的道路在我面前正直。","notes":[]},{"n":9,"t":"因為，他們的口中沒有誠實；他們的心裏滿有邪惡；他們的喉嚨是敞開的墳墓；他們用舌頭諂媚人。","notes":[]},{"n":10,"t":"神啊，求你定他們的罪！願他們因自己的計謀跌倒；願你在他們許多的過犯中把他們逐出，因為他們背叛了你。","notes":[]},{"n":11,"t":"凡投靠你的，願他們喜樂，時常歡呼，因為你護庇他們；又願那愛你名的人都靠你歡欣。","notes":[]},{"n":12,"t":"因為你必賜福與義人；耶和華啊，你必用恩惠如同盾牌四面護衛他。","notes":[]}]},"6":{"heading":"患難中求助的祈禱","verses":[{"n":1,"t":"耶和華啊，求你不要在怒中責備我，也不要在烈怒中懲罰我！","notes":[]},{"n":2,"t":"耶和華啊，求你可憐我，因為我軟弱。耶和華啊，求你醫治我，因為我的骨頭發戰。","notes":[]},{"n":3,"t":"我心也大大地驚惶。耶和華啊，你要到幾時才救我呢？","notes":[]},{"n":4,"t":"耶和華啊，求你轉回搭救我！因你的慈愛拯救我。","notes":[]},{"n":5,"t":"因為，在死地無人記念你，在陰間有誰稱謝你？","notes":[]},{"n":6,"t":"我因唉哼而困乏；我每夜流淚，把床榻漂起，把褥子濕透。","notes":[]},{"n":7,"t":"我因憂愁眼睛乾癟，又因我一切的敵人眼睛昏花。","notes":[]},{"n":8,"t":"你們一切作孽的人，離開我吧！因為耶和華聽了我哀哭的聲音。","notes":[]},{"n":9,"t":"耶和華聽了我的懇求；耶和華必收納我的禱告。","notes":[]},{"n":10,"t":"我的一切仇敵都必羞愧，大大驚惶；他們必要退後，忽然羞愧。","notes":[]}]},"7":{"heading":"為公義而祈禱","verses":[{"n":1,"t":"耶和華－我的神啊，我投靠你！求你救我脫離一切追趕我的人，將我救拔出來！","notes":[]},{"n":2,"t":"恐怕他們像獅子撕裂我，甚至撕碎，無人搭救。","notes":[]},{"n":3,"t":"耶和華－我的神啊，我若行了這事，若有罪孽在我手裏，","notes":[]},{"n":4,"t":"我若以惡報那與我交好的人－連那無故與我為敵的，我也救了他，","notes":[]},{"n":5,"t":"就任憑仇敵追趕我，直到追上，將我的性命踏在地下，使我的榮耀歸於灰塵。（細拉）","notes":[]},{"n":6,"t":"耶和華啊，求你在怒中起來，挺身而立，抵擋我敵人的暴怒！求你為我興起！你已經命定施行審判！","notes":[]},{"n":7,"t":"願眾民的會環繞你！願你從其上歸於高位！","notes":[]},{"n":8,"t":"耶和華向眾民施行審判；耶和華啊，求你按我的公義和我心中的純正判斷我。","notes":[]},{"n":9,"t":"願惡人的惡斷絕！願你堅立義人！因為公義的神察驗人的心腸肺腑。","notes":[]},{"n":10,"t":"神是我的盾牌；他拯救心裏正直的人。","notes":[]},{"n":11,"t":"神是公義的審判者，又是天天向惡人發怒的神。","notes":[]},{"n":12,"t":"若有人不回頭，他的刀必磨快，弓必上弦，預備妥當了。","notes":[]},{"n":13,"t":"他也預備了殺人的器械；他所射的是火箭。","notes":[]},{"n":14,"t":"試看惡人因奸惡而劬勞，所懷的是毒害，所生的是虛假。","notes":[]},{"n":15,"t":"他掘了坑，又挖深了，竟掉在自己所挖的阱裏。","notes":[]},{"n":16,"t":"他的毒害必臨到他自己的頭上；他的強暴必落到他自己的腦袋上。","notes":[]},{"n":17,"t":"我要照著耶和華的公義稱謝他，歌頌耶和華至高者的名。","notes":[]}]},"8":{"heading":"神的榮耀和人的尊貴","verses":[{"n":1,"t":"耶和華－我們的主啊，你的名在全地何其美！你將你的榮耀彰顯於天。","notes":[]},{"n":2,"t":"你因敵人的緣故，從嬰孩和吃奶的口中，建立了能力，使仇敵和報仇的閉口無言。","notes":[]},{"n":3,"t":"我觀看你指頭所造的天，並你所陳設的月亮星宿，","notes":[]},{"n":4,"t":"便說：人算甚麼，你竟顧念他！世人算甚麼，你竟眷顧他！","notes":[]},{"n":5,"t":"你叫他比天使微小一點，並賜他榮耀尊貴為冠冕。","notes":["或譯：神"]},{"n":6,"t":"你派他管理你手所造的，使萬物，就是一切的牛羊、田野的獸、空中的鳥、海裏的魚，凡經行海道的，都服在他的腳下。","notes":[],"end":8},{"n":9,"t":"耶和華－我們的主啊，你的名在全地何其美！","notes":[]}]},"9":{"heading":"稱頌耶和華的公義","verses":[{"n":1,"t":"我要一心稱謝耶和華；我要傳揚你一切奇妙的作為。","notes":[]},{"n":2,"t":"我要因你歡喜快樂；至高者啊，我要歌頌你的名！","notes":[]},{"n":3,"t":"我的仇敵轉身退去的時候，他們一見你的面就跌倒滅亡。","notes":[]},{"n":4,"t":"因你已經為我伸冤，為我辨屈；你坐在寶座上，按公義審判。","notes":[]},{"n":5,"t":"你曾斥責外邦，你曾滅絕惡人；你曾塗抹他們的名，直到永永遠遠。","notes":[]},{"n":6,"t":"仇敵到了盡頭；他們被毀壞，直到永遠。你拆毀他們的城邑，連他們的名號都歸於無有。","notes":[]},{"n":7,"t":"惟耶和華坐著為王，直到永遠；他已經為審判設擺他的寶座。","notes":[]},{"n":8,"t":"他要按公義審判世界，按正直判斷萬民。","notes":[]},{"n":9,"t":"耶和華又要給受欺壓的人作高臺，在患難的時候作高臺。","notes":[]},{"n":10,"t":"耶和華啊，認識你名的人要倚靠你，因你沒有離棄尋求你的人。","notes":[]},{"n":11,"t":"應當歌頌居錫安的耶和華，將他所行的傳揚在眾民中。","notes":[]},{"n":12,"t":"因為那追討流人血之罪的－他記念受屈的人，不忘記困苦人的哀求。","notes":[]},{"n":13,"t":"耶和華啊，你是從死門把我提拔起來的；求你憐恤我，看那恨我的人所加給我的苦難，","notes":[]},{"n":14,"t":"好叫我述說你一切的美德；我必在錫安城的門因你的救恩歡樂。","notes":["原文是女子"]},{"n":15,"t":"外邦人陷在自己所掘的坑中；他們的腳在自己暗設的網羅裏纏住了。","notes":[]},{"n":16,"t":"耶和華已將自己顯明了，他已施行審判；惡人被自己手所做的纏住了。（細拉）","notes":["或譯：他叫惡人被自己手所做的累住了"]},{"n":17,"t":"惡人，就是忘記神的外邦人，都必歸到陰間。","notes":[]},{"n":18,"t":"窮乏人必不永久被忘；困苦人的指望必不永遠落空。","notes":[]},{"n":19,"t":"耶和華啊，求你起來，不容人得勝！願外邦人在你面前受審判！","notes":[]},{"n":20,"t":"耶和華啊，求你使外邦人恐懼；願他們知道自己不過是人。（細拉）","notes":[]}]},"10":{"heading":"為公義而祈禱","verses":[{"n":1,"t":"耶和華啊，你為甚麼站在遠處？在患難的時候為甚麼隱藏？","notes":[]},{"n":2,"t":"惡人在驕橫中把困苦人追得火急；願他們陷在自己所設的計謀裏。","notes":[]},{"n":3,"t":"因為惡人以心願自誇；貪財的背棄耶和華，並且輕慢他。","notes":["或譯：他祝福貪財的，卻輕慢耶和華"]},{"n":4,"t":"惡人面帶驕傲，說：耶和華必不追究；他一切所想的都以為沒有神。","notes":[]},{"n":5,"t":"凡他所做的，時常穩固；你的審判超過他的眼界。至於他一切的敵人，他都向他們噴氣。","notes":[]},{"n":6,"t":"他心裏說：我必不動搖，世世代代不遭災難。","notes":[]},{"n":7,"t":"他滿口是咒罵、詭詐、欺壓，舌底是毒害、奸惡。","notes":[]},{"n":8,"t":"他在村莊埋伏等候；他在隱密處殺害無辜的人。他的眼睛窺探無倚無靠的人；","notes":[]},{"n":9,"t":"他埋伏在暗地，如獅子蹲在洞中。他埋伏，要擄去困苦人；他拉網，就把困苦人擄去。","notes":[]},{"n":10,"t":"他屈身蹲伏，無倚無靠的人就倒在他爪牙 之下。","notes":["爪牙：或譯強暴人"]},{"n":11,"t":"他心裏說：神竟忘記了；他掩面永不觀看。","notes":[]},{"n":12,"t":"耶和華啊，求你起來！神啊，求你舉手，不要忘記困苦人！","notes":[]},{"n":13,"t":"惡人為何輕慢神，心裏說：你必不追究？","notes":[]},{"n":14,"t":"其實你已經觀看；因為奸惡毒害，你都看見了，為要以手施行報應。無倚無靠的人把自己交託你；你向來是幫助孤兒的。","notes":[]},{"n":15,"t":"願你打斷惡人的膀臂；至於壞人，願你追究他的惡，直到淨盡。","notes":[]},{"n":16,"t":"耶和華永永遠遠為王；外邦人從他的地已經滅絕了。","notes":[]},{"n":17,"t":"耶和華啊，謙卑人的心願，你早已知道。你必預備他們的心，也必側耳聽他們的祈求，","notes":["原文是聽見"]},{"n":18,"t":"為要給孤兒和受欺壓的人伸冤，使強橫的人不再威嚇他們。","notes":[]}]},"11":{"heading":"在主裏得安穩","verses":[{"n":1,"t":"我是投靠耶和華；你們怎麼對我說：你當像鳥飛往你的山去。","notes":[]},{"n":2,"t":"看哪，惡人彎弓，把箭搭在弦上，要在暗中射那心裏正直的人。","notes":[]},{"n":3,"t":"根基若毀壞，義人還能做甚麼呢？","notes":[]},{"n":4,"t":"耶和華在他的聖殿裏；耶和華的寶座在天上；他的慧眼察看世人。","notes":[]},{"n":5,"t":"耶和華試驗義人；惟有惡人和喜愛強暴的人，他心裏恨惡。","notes":[]},{"n":6,"t":"他要向惡人密布網羅；有烈火、硫磺、熱風，作他們杯中的分。","notes":[]},{"n":7,"t":"因為耶和華是公義的，他喜愛公義；正直人必得見他的面。","notes":[]}]},"12":{"heading":"求助的祈禱","verses":[{"n":1,"t":"耶和華啊，求你幫助，因虔誠人斷絕了；世人中間的忠信人沒有了。","notes":[]},{"n":2,"t":"人人向鄰舍說謊；他們說話，是嘴唇油滑，心口不一。","notes":[]},{"n":3,"t":"凡油滑的嘴唇和誇大的舌頭，耶和華必要剪除。","notes":[]},{"n":4,"t":"他們曾說：我們必能以舌頭得勝；我們的嘴唇是我們自己的，誰能作我們的主呢？","notes":[]},{"n":5,"t":"耶和華說：因為困苦人的冤屈和貧窮人的歎息，我現在要起來，把他安置在他所切慕的穩妥之地。","notes":[]},{"n":6,"t":"耶和華的言語是純淨的言語，如同銀子在泥爐中煉過七次。","notes":[]},{"n":7,"t":"耶和華啊，你必保護他們；你必保佑他們永遠脫離這世代的人。","notes":[]},{"n":8,"t":"下流人在世人中升高，就有惡人到處遊行。","notes":[]}]},"13":{"heading":"求耶和華看顧","verses":[{"n":1,"t":"耶和華啊，你忘記我要到幾時呢？要到永遠嗎？你掩面不顧我要到幾時呢？","notes":[]},{"n":2,"t":"我心裏籌算，終日愁苦，要到幾時呢？我的仇敵升高壓制我，要到幾時呢？","notes":[]},{"n":3,"t":"耶和華－我的神啊，求你看顧我，應允我！使我眼目光明，免得我沉睡至死；","notes":[]},{"n":4,"t":"免得我的仇敵說：我勝了他；免得我的敵人在我搖動的時候喜樂。","notes":[]},{"n":5,"t":"但我倚靠你的慈愛；我的心因你的救恩快樂。","notes":[]},{"n":6,"t":"我要向耶和華歌唱，因他用厚恩待我。","notes":[]}]},"14":{"heading":"人的邪惡","verses":[{"n":1,"t":"愚頑人心裏說：沒有神。他們都是邪惡，行了可憎惡的事；沒有一個人行善。","notes":[]},{"n":2,"t":"耶和華從天上垂看世人，要看有明白的沒有，有尋求神的沒有。","notes":[]},{"n":3,"t":"他們都偏離正路，一同變為污穢；並沒有行善的，連一個也沒有。","notes":[]},{"n":4,"t":"作孽的都沒有知識嗎？他們吞吃我的百姓，如同吃飯一樣，並不求告耶和華。","notes":[]},{"n":5,"t":"他們在那裏大大地害怕，因為神在義人的族類中。","notes":[]},{"n":6,"t":"你們叫困苦人的謀算變為羞辱；然而耶和華是他的避難所。","notes":[]},{"n":7,"t":"但願以色列的救恩從錫安而出。耶和華救回他被擄的子民那時，雅各要快樂，以色列要歡喜。","notes":[]}]},"15":{"heading":"得居聖山者的品行","verses":[{"n":1,"t":"耶和華啊，誰能寄居你的帳幕？誰能住在你的聖山？","notes":[]},{"n":2,"t":"就是行為正直、做事公義、心裏說實話的人。","notes":[]},{"n":3,"t":"他不以舌頭讒謗人，不惡待朋友，也不隨夥毀謗鄰里。","notes":[]},{"n":4,"t":"他眼中藐視匪類，卻尊重那敬畏耶和華的人。他發了誓，雖然自己吃虧也不更改。","notes":[]},{"n":5,"t":"他不放債取利，不受賄賂以害無辜。行這些事的人必永不動搖。","notes":[]}]},"16":{"heading":"為信心穩固而祈禱","verses":[{"n":1,"t":"神啊，求你保佑我，因為我投靠你。","notes":[]},{"n":2,"t":"我的心哪，你曾對耶和華說：你是我的主；我的好處不在你以外。","notes":[]},{"n":3,"t":"論到世上的聖民，他們又美又善，是我最喜悅的。","notes":[]},{"n":4,"t":"以別神代替耶和華的，他們的愁苦必加增；他們所澆奠的血我不獻上；我嘴唇也不提別神的名號。","notes":["或譯：送禮物給別神的"]},{"n":5,"t":"耶和華是我的產業，是我杯中的分；我所得的，你為我持守。","notes":[]},{"n":6,"t":"用繩量給我的地界，坐落在佳美之處；我的產業實在美好。","notes":[]},{"n":7,"t":"我必稱頌那指教我的耶和華；我的心腸在夜間也警戒我。","notes":[]},{"n":8,"t":"我將耶和華常擺在我面前，因他在我右邊，我便不致搖動。","notes":[]},{"n":9,"t":"因此，我的心歡喜，我的靈快樂；我的肉身也要安然居住。","notes":["原文是榮耀"]},{"n":10,"t":"因為你必不將我的靈魂撇在陰間，也不叫你的聖者見朽壞。","notes":[]},{"n":11,"t":"你必將生命的道路指示我。在你面前有滿足的喜樂；在你右手中有永遠的福樂。","notes":[]}]},"17":{"heading":"無辜的人的禱告","verses":[{"n":1,"t":"耶和華啊，求你聽聞公義，側耳聽我的呼籲！求你留心聽我這不出於詭詐嘴唇的祈禱！","notes":[]},{"n":2,"t":"願我的判語從你面前發出；願你的眼睛觀看公正。","notes":[]},{"n":3,"t":"你已經試驗我的心；你在夜間鑒察我；你熬煉我，卻找不著甚麼；我立志叫我口中沒有過失。","notes":[]},{"n":4,"t":"論到人的行為，我藉著你嘴唇的言語自己謹守，不行強暴人的道路。","notes":[]},{"n":5,"t":"我的腳踏定了你的路徑；我的兩腳未曾滑跌。","notes":[]},{"n":6,"t":"神啊，我曾求告你，因為你必應允我；求你向我側耳，聽我的言語。","notes":[]},{"n":7,"t":"求你顯出你奇妙的慈愛來；你是那用右手拯救投靠你的脫離起來攻擊他們的人。","notes":[]},{"n":8,"t":"求你保護我，如同保護眼中的瞳人；將我隱藏在你翅膀的蔭下，","notes":[]},{"n":9,"t":"使我脫離那欺壓我的惡人，就是圍困我要害我命的仇敵。","notes":[]},{"n":10,"t":"他們的心被脂油包裹；他們用口說驕傲的話。","notes":[]},{"n":11,"t":"他們圍困了我們的腳步；他們瞪著眼，要把我們推倒在地。","notes":[]},{"n":12,"t":"他像獅子急要抓食，又像少壯獅子蹲伏在暗處。","notes":[]},{"n":13,"t":"耶和華啊，求你起來，前去迎敵，將他打倒！用你的刀救護我命脫離惡人。","notes":[]},{"n":14,"t":"耶和華啊，求你用手救我脫離世人，脫離那只在今生有福分的世人！你把你的財寶充滿他們的肚腹；他們因有兒女就心滿意足，將其餘的財物留給他們的嬰孩。","notes":[]},{"n":15,"t":"至於我，我必在義中見你的面；我醒了的時候，得見你的形像就心滿意足了。","notes":["或譯：著"]}]},"18":{"heading":"大衛的勝利之歌","verses":[{"n":1,"t":"耶和華，我的力量啊，我愛你！","notes":[]},{"n":2,"t":"耶和華是我的巖石，我的山寨，我的救主，我的神，我的磐石，我所投靠的。他是我的盾牌，是拯救我的角，是我的高臺。","notes":[]},{"n":3,"t":"我要求告當讚美的耶和華；這樣我必從仇敵手中被救出來。","notes":[]},{"n":4,"t":"曾有死亡的繩索纏繞我，匪類的急流使我驚懼，","notes":[]},{"n":5,"t":"陰間的繩索纏繞我，死亡的網羅臨到我。","notes":[]},{"n":6,"t":"我在急難中求告耶和華，向我的神呼求。他從殿中聽了我的聲音；我在他面前的呼求入了他的耳中。","notes":[]},{"n":7,"t":"那時，因他發怒，地就搖撼戰抖；山的根基也震動搖撼。","notes":[]},{"n":8,"t":"從他鼻孔冒煙上騰；從他口中發火焚燒，連炭也著了。","notes":[]},{"n":9,"t":"他又使天下垂，親自降臨，有黑雲在他腳下。","notes":[]},{"n":10,"t":"他坐著基路伯飛行；他藉著風的翅膀快飛。","notes":[]},{"n":11,"t":"他以黑暗為藏身之處，以水的黑暗、天空的厚雲為他四圍的行宮。","notes":[]},{"n":12,"t":"因他面前的光輝，他的厚雲行過便有冰雹火炭。","notes":[]},{"n":13,"t":"耶和華也在天上打雷；至高者發出聲音便有冰雹火炭。","notes":[]},{"n":14,"t":"他射出箭來，使仇敵四散；多多發出閃電，使他們擾亂。","notes":[]},{"n":15,"t":"耶和華啊，你的斥責一發，你鼻孔的氣一出，海底就出現，大地的根基也顯露。","notes":[]},{"n":16,"t":"他從高天伸手抓住我，把我從大水中拉上來。","notes":[]},{"n":17,"t":"他救我脫離我的勁敵和那些恨我的人，因為他們比我強盛。","notes":[]},{"n":18,"t":"我遭遇災難的日子，他們來攻擊我；但耶和華是我的倚靠。","notes":[]},{"n":19,"t":"他又領我到寬闊之處；他救拔我，因他喜悅我。","notes":[]},{"n":20,"t":"耶和華按著我的公義報答我，按著我手中的清潔賞賜我。","notes":[]},{"n":21,"t":"因為我遵守了耶和華的道，未曾作惡離開我的神。","notes":[]},{"n":22,"t":"他的一切典章常在我面前；他的律例我也未曾丟棄。","notes":[]},{"n":23,"t":"我在他面前作了完全人；我也保守自己遠離我的罪孽。","notes":[]},{"n":24,"t":"所以，耶和華按我的公義，按我在他眼前手中的清潔償還我。","notes":[]},{"n":25,"t":"慈愛的人，你以慈愛待他；完全的人，你以完全待他。","notes":[]},{"n":26,"t":"清潔的人，你以清潔待他；乖僻的人，你以彎曲待他。","notes":[]},{"n":27,"t":"困苦的百姓，你必拯救；高傲的眼目，你必使他降卑。","notes":[]},{"n":28,"t":"你必點著我的燈；耶和華－我的神必照明我的黑暗。","notes":[]},{"n":29,"t":"我藉著你衝入敵軍，藉著我的神跳過牆垣。","notes":[]},{"n":30,"t":"至於神，他的道是完全的；耶和華的話是煉淨的。凡投靠他的，他便作他們的盾牌。","notes":[]},{"n":31,"t":"除了耶和華，誰是神呢？除了我們的神，誰是磐石呢？","notes":[]},{"n":32,"t":"惟有那以力量束我的腰、使我行為完全的，他是神。","notes":[]},{"n":33,"t":"他使我的腳快如母鹿的蹄，又使我在高處安穩。","notes":[]},{"n":34,"t":"他教導我的手能以爭戰，甚至我的膀臂能開銅弓。","notes":[]},{"n":35,"t":"你把你的救恩給我作盾牌；你的右手扶持我；你的溫和使我為大。","notes":[]},{"n":36,"t":"你使我腳下的地步寬闊；我的腳未曾滑跌。","notes":[]},{"n":37,"t":"我要追趕我的仇敵，並要追上他們；不將他們滅絕，我總不歸回。","notes":[]},{"n":38,"t":"我要打傷他們，使他們不能起來；他們必倒在我的腳下。","notes":[]},{"n":39,"t":"因為你曾以力量束我的腰，使我能爭戰；你也使那起來攻擊我的都服在我以下。","notes":[]},{"n":40,"t":"你又使我的仇敵在我面前轉背逃跑，叫我能以剪除那恨我的人。","notes":[]},{"n":41,"t":"他們呼求，卻無人拯救；就是呼求耶和華，他也不應允。","notes":[]},{"n":42,"t":"我搗碎他們，如同風前的灰塵，倒出他們，如同街上的泥土。","notes":[]},{"n":43,"t":"你救我脫離百姓的爭競，立我作列國的元首；我素不認識的民必事奉我。","notes":[]},{"n":44,"t":"他們一聽見我的名聲就必順從我；外邦人要投降我。","notes":[]},{"n":45,"t":"外邦人要衰殘，戰戰兢兢地出他們的營寨。","notes":[]},{"n":46,"t":"耶和華是活神。願我的磐石被人稱頌；願救我的神被人尊崇。","notes":[]},{"n":47,"t":"這位神，就是那為我伸冤、使眾民服在我以下的。","notes":[]},{"n":48,"t":"你救我脫離仇敵，又把我舉起，高過那些起來攻擊我的；你救我脫離強暴的人。","notes":[]},{"n":49,"t":"耶和華啊，因此我要在外邦中稱謝你，歌頌你的名。","notes":[]},{"n":50,"t":"耶和華賜極大的救恩給他所立的王，施慈愛給他的受膏者，就是給大衛和他的後裔，直到永遠。","notes":[]}]},"19":{"heading":"造化的榮耀","verses":[{"n":1,"t":"諸天述說神的榮耀；穹蒼傳揚他的手段。","notes":[]},{"n":2,"t":"這日到那日發出言語；這夜到那夜傳出知識。","notes":[]},{"n":3,"t":"無言無語，也無聲音可聽。","notes":[]},{"n":4,"t":"它的量帶通遍天下，它的言語傳到地極。神在其間為太陽安設帳幕；","notes":[]},{"n":5,"t":"太陽如同新郎出洞房，又如勇士歡然奔路。","notes":[]},{"n":6,"t":"它從天這邊出來，繞到天那邊，沒有一物被隱藏不得它的熱氣。","notes":[]},{"n":7,"t":"耶和華的律法全備，能甦醒人心；耶和華的法度確定，能使愚人有智慧。","notes":[],"heads":["耶和華的律法"]},{"n":8,"t":"耶和華的訓詞正直，能快活人的心；耶和華的命令清潔，能明亮人的眼目。","notes":[]},{"n":9,"t":"耶和華的道理潔淨，存到永遠；耶和華的典章真實，全然公義－","notes":[]},{"n":10,"t":"都比金子可羨慕，且比極多的精金可羨慕；比蜜甘甜，且比蜂房下滴的蜜甘甜。","notes":[]},{"n":11,"t":"況且你的僕人因此受警戒，守著這些便有大賞。","notes":[]},{"n":12,"t":"誰能知道自己的錯失呢？願你赦免我隱而未現的過錯。","notes":[]},{"n":13,"t":"求你攔阻僕人不犯任意妄為的罪，不容這罪轄制我，我便完全，免犯大罪。","notes":[]},{"n":14,"t":"耶和華－我的磐石，我的救贖主啊，願我口中的言語、心裏的意念在你面前蒙悅納。","notes":[]}]},"20":{"heading":"祈求勝利","verses":[{"n":1,"t":"願耶和華在你遭難的日子應允你；願名為雅各神的高舉你。","notes":[]},{"n":2,"t":"願他從聖所救助你，從錫安堅固你，","notes":[]},{"n":3,"t":"記念你的一切供獻，悅納你的燔祭，（細拉）","notes":[]},{"n":4,"t":"將你心所願的賜給你，成就你的一切籌算。","notes":[]},{"n":5,"t":"我們要因你的救恩誇勝，要奉我們神的名豎立旌旗。願耶和華成就你一切所求的！","notes":[]},{"n":6,"t":"現在我知道耶和華救護他的受膏者，必從他的聖天上應允他，用右手的能力救護他。","notes":[]},{"n":7,"t":"有人靠車，有人靠馬，但我們要提到耶和華－我們神的名。","notes":[]},{"n":8,"t":"他們都屈身仆倒，我們卻起來，立得正直。","notes":[]},{"n":9,"t":"求耶和華施行拯救；我們呼求的時候，願王應允我們！","notes":[]}]},"21":{"heading":"為勝利而歌頌","verses":[{"n":1,"t":"耶和華啊，王必因你的能力歡喜；因你的救恩，他的快樂何其大！","notes":[]},{"n":2,"t":"他心裏所願的，你已經賜給他；他嘴唇所求的，你未嘗不應允。（細拉）","notes":[]},{"n":3,"t":"你以美福迎接他，把精金的冠冕戴在他頭上。","notes":[]},{"n":4,"t":"他向你求壽，你便賜給他，就是日子長久，直到永遠。","notes":[]},{"n":5,"t":"他因你的救恩大有榮耀；你又將尊榮威嚴加在他身上。","notes":[]},{"n":6,"t":"你使他有洪福，直到永遠，又使他在你面前歡喜快樂。","notes":[]},{"n":7,"t":"王倚靠耶和華，因至高者的慈愛必不搖動。","notes":[]},{"n":8,"t":"你的手要搜出你的一切仇敵；你的右手要搜出那些恨你的人。","notes":[]},{"n":9,"t":"你發怒的時候，要使他們如在炎熱的火爐中。耶和華要在他的震怒中吞滅他們；那火要把他們燒盡了。","notes":[]},{"n":10,"t":"你必從世上滅絕他們的子孫，從人間滅絕他們的後裔。","notes":["原文是果子"]},{"n":11,"t":"因為他們有意加害於你；他們想出計謀，卻不能做成。","notes":[]},{"n":12,"t":"你必使他們轉背逃跑，向他們的臉搭箭在弦。","notes":[]},{"n":13,"t":"耶和華啊，願你因自己的能力顯為至高！這樣，我們就唱詩，歌頌你的大能。","notes":[]}]},"22":{"heading":"痛苦中的禱告和讚美","verses":[{"n":1,"t":"我的神，我的神！為甚麼離棄我？為甚麼遠離不救我？不聽我唉哼的言語？","notes":[]},{"n":2,"t":"我的神啊，我白日呼求，你不應允，夜間呼求，並不住聲。","notes":[]},{"n":3,"t":"但你是聖潔的，是用以色列的讚美為寶座的。","notes":["或譯：居所"]},{"n":4,"t":"我們的祖宗倚靠你；他們倚靠你，你便解救他們。","notes":[]},{"n":5,"t":"他們哀求你，便蒙解救；他們倚靠你，就不羞愧。","notes":[]},{"n":6,"t":"但我是蟲，不是人，被眾人羞辱，被百姓藐視。","notes":[]},{"n":7,"t":"凡看見我的都嗤笑我；他們撇嘴搖頭，說：","notes":[]},{"n":8,"t":"他把自己交託耶和華，耶和華可以救他吧！耶和華既喜悅他，可以搭救他吧！","notes":[]},{"n":9,"t":"但你是叫我出母腹的；我在母懷裏，你就使我有倚靠的心。","notes":[]},{"n":10,"t":"我自出母胎就被交在你手裏；從我母親生我，你就是我的神。","notes":[]},{"n":11,"t":"求你不要遠離我！因為急難臨近了，沒有人幫助我。","notes":[]},{"n":12,"t":"有許多公牛圍繞我，巴珊大力的公牛四面困住我。","notes":[]},{"n":13,"t":"牠們向我張口，好像抓撕吼叫的獅子。","notes":[]},{"n":14,"t":"我如水被倒出來；我的骨頭都脫了節；我心在我裏面如蠟鎔化。","notes":[]},{"n":15,"t":"我的精力枯乾，如同瓦片；我的舌頭貼在我牙床上。你將我安置在死地的塵土中。","notes":[]},{"n":16,"t":"犬類圍著我，惡黨環繞我；他們扎了我的手，我的腳。","notes":[]},{"n":17,"t":"我的骨頭，我都能數過；他們瞪著眼看我。","notes":[]},{"n":18,"t":"他們分我的外衣，為我的裏衣拈鬮。","notes":[]},{"n":19,"t":"耶和華啊，求你不要遠離我！我的救主啊，求你快來幫助我！","notes":[]},{"n":20,"t":"求你救我的靈魂脫離刀劍，救我的生命脫離犬類，","notes":["生命：原文是獨一者"]},{"n":21,"t":"救我脫離獅子的口；你已經應允我，使我脫離野牛的角。","notes":[]},{"n":22,"t":"我要將你的名傳與我的弟兄，在會中我要讚美你。","notes":[]},{"n":23,"t":"你們敬畏耶和華的人要讚美他！雅各的後裔都要榮耀他！以色列的後裔都要懼怕他！","notes":[]},{"n":24,"t":"因為他沒有藐視憎惡受苦的人，也沒有向他掩面；那受苦之人呼籲的時候，他就垂聽。","notes":[]},{"n":25,"t":"我在大會中讚美你的話是從你而來的；我要在敬畏耶和華的人面前還我的願。","notes":[]},{"n":26,"t":"謙卑的人必吃得飽足；尋求耶和華的人必讚美他。願你們的心永遠活著！","notes":[]},{"n":27,"t":"地的四極都要想念耶和華，並且歸順他；列國的萬族都要在你面前敬拜。","notes":[]},{"n":28,"t":"因為國權是耶和華的；他是管理萬國的。","notes":[]},{"n":29,"t":"地上一切豐肥的人必吃喝而敬拜；凡下到塵土中－不能存活自己性命的人－都要在他面前下拜。","notes":[]},{"n":30,"t":"他必有後裔事奉他；主所行的事必傳與後代。","notes":[]},{"n":31,"t":"他們必來把他的公義傳給將要生的民，言明這事是他所行的。","notes":[]}]},"23":{"heading":"耶和華是我牧者","verses":[{"n":1,"t":"耶和華是我的牧者，我必不致缺乏。","notes":[]},{"n":2,"t":"他使我躺臥在青草地上，領我在可安歇的水邊。","notes":[]},{"n":3,"t":"他使我的靈魂甦醒，為自己的名引導我走義路。","notes":[]},{"n":4,"t":"我雖然行過死蔭的幽谷，也不怕遭害，因為你與我同在；你的杖，你的竿，都安慰我。","notes":[]},{"n":5,"t":"在我敵人面前，你為我擺設筵席；你用油膏了我的頭，使我的福杯滿溢。","notes":[]},{"n":6,"t":"我一生一世必有恩惠慈愛隨著我；我且要住在耶和華的殿中，直到永遠。","notes":[]}]},"24":{"heading":"偉大的君王","verses":[{"n":1,"t":"地和其中所充滿的，世界和住在其間的，都屬耶和華。","notes":[]},{"n":2,"t":"他把地建立在海上，安定在大水之上。","notes":[]},{"n":3,"t":"誰能登耶和華的山？誰能站在他的聖所？","notes":[]},{"n":4,"t":"就是手潔心清，不向虛妄，起誓不懷詭詐的人。","notes":[]},{"n":5,"t":"他必蒙耶和華賜福，又蒙救他的神使他成義。","notes":[]},{"n":6,"t":"這是尋求耶和華的族類，是尋求你面的雅各。 （細拉）","notes":[]},{"n":7,"t":"眾城門哪，你們要抬起頭來！永久的門戶，你們要被舉起！那榮耀的王將要進來！","notes":[]},{"n":8,"t":"榮耀的王是誰呢？就是有力有能的耶和華，在戰場上有能的耶和華！","notes":[]},{"n":9,"t":"眾城門哪，你們要抬起頭來！永久的門戶，你們要把頭抬起！那榮耀的王將要進來！","notes":[]},{"n":10,"t":"榮耀的王是誰呢？萬軍之耶和華，他是榮耀的王！（細拉）","notes":[]}]},"25":{"heading":"求主指引保護","verses":[{"n":1,"t":"耶和華啊，我的心仰望你。","notes":[]},{"n":2,"t":"我的神啊，我素來倚靠你；求你不要叫我羞愧，不要叫我的仇敵向我誇勝。","notes":[]},{"n":3,"t":"凡等候你的必不羞愧；惟有那無故行奸詐的必要羞愧。","notes":[]},{"n":4,"t":"耶和華啊，求你將你的道指示我，將你的路教訓我！","notes":[]},{"n":5,"t":"求你以你的真理引導我，教訓我，因為你是救我的神。我終日等候你。","notes":[]},{"n":6,"t":"耶和華啊，求你記念你的憐憫和慈愛，因為這是亙古以來所常有的。","notes":[]},{"n":7,"t":"求你不要記念我幼年的罪愆和我的過犯；耶和華啊，求你因你的恩惠，按你的慈愛記念我。","notes":[]},{"n":8,"t":"耶和華是良善正直的，所以他必指示罪人走正路。","notes":[]},{"n":9,"t":"他必按公平引領謙卑人，將他的道教訓他們。","notes":[]},{"n":10,"t":"凡遵守他的約和他法度的人，耶和華都以慈愛誠實待他。","notes":[]},{"n":11,"t":"耶和華啊，求你因你的名赦免我的罪，因為我的罪重大。","notes":[]},{"n":12,"t":"誰敬畏耶和華，耶和華必指示他當選擇的道路。","notes":[]},{"n":13,"t":"他必安然居住；他的後裔必承受地土。","notes":[]},{"n":14,"t":"耶和華與敬畏他的人親密；他必將自己的約指示他們。","notes":[]},{"n":15,"t":"我的眼目時常仰望耶和華，因為他必將我的腳從網裏拉出來。","notes":[]},{"n":16,"t":"求你轉向我，憐恤我，因為我是孤獨困苦。","notes":[]},{"n":17,"t":"我心裏的愁苦甚多，求你救我脫離我的禍患。","notes":[]},{"n":18,"t":"求你看顧我的困苦，我的艱難，赦免我一切的罪。","notes":[]},{"n":19,"t":"求你察看我的仇敵，因為他們人多，並且痛痛地恨我。","notes":[]},{"n":20,"t":"求你保護我的性命，搭救我，使我不致羞愧，因為我投靠你。","notes":[]},{"n":21,"t":"願純全、正直保守我，因為我等候你。","notes":[]},{"n":22,"t":"神啊，求你救贖以色列脫離他一切的愁苦。","notes":[]}]},"26":{"heading":"義人的祈禱","verses":[{"n":1,"t":"耶和華啊，求你為我伸冤，因我向來行事純全；我又倚靠耶和華，並不搖動。","notes":[]},{"n":2,"t":"耶和華啊，求你察看我，試驗我，熬煉我的肺腑心腸。","notes":[]},{"n":3,"t":"因為你的慈愛常在我眼前，我也按你的真理而行。","notes":[]},{"n":4,"t":"我沒有和虛謊人同坐，也不與瞞哄人的同群。","notes":[]},{"n":5,"t":"我恨惡惡人的會，必不與惡人同坐。","notes":[]},{"n":6,"t":"耶和華啊，我要洗手表明無辜，才環繞你的祭壇；","notes":[]},{"n":7,"t":"我好發稱謝的聲音，也要述說你一切奇妙的作為。","notes":[]},{"n":8,"t":"耶和華啊，我喜愛你所住的殿和你顯榮耀的居所。","notes":[]},{"n":9,"t":"不要把我的靈魂和罪人一同除掉；不要把我的性命和流人血的一同除掉。","notes":[]},{"n":10,"t":"他們的手中有奸惡，右手滿有賄賂。","notes":[]},{"n":11,"t":"至於我，卻要行事純全；求你救贖我，憐恤我！","notes":[]},{"n":12,"t":"我的腳站在平坦地方；在眾會中我要稱頌耶和華！","notes":[]}]},"27":{"heading":"讚美的禱告","verses":[{"n":1,"t":"耶和華是我的亮光，是我的拯救，我還怕誰呢？耶和華是我性命的保障，我還懼誰呢？","notes":["或譯：力量"]},{"n":2,"t":"那作惡的就是我的仇敵，前來吃我肉的時候就絆跌仆倒。","notes":[]},{"n":3,"t":"雖有軍兵安營攻擊我，我的心也不害怕；雖然興起刀兵攻擊我，我必仍舊安穩。","notes":[]},{"n":4,"t":"有一件事，我曾求耶和華，我仍要尋求：就是一生一世住在耶和華的殿中，瞻仰他的榮美，在他的殿裏求問。","notes":[]},{"n":5,"t":"因為我遭遇患難，他必暗暗地保守我；在他亭子裏，把我藏在他帳幕的隱密處，將我高舉在磐石上。","notes":[]},{"n":6,"t":"現在我得以昂首，高過四面的仇敵。我要在他的帳幕裏歡然獻祭；我要唱詩歌頌耶和華。","notes":[]},{"n":7,"t":"耶和華啊，我用聲音呼籲的時候，求你垂聽；並求你憐恤我，應允我。","notes":[]},{"n":8,"t":"你說：你們當尋求我的面。那時我心向你說：耶和華啊，你的面我正要尋求。","notes":[]},{"n":9,"t":"不要向我掩面。不要發怒趕逐僕人，你向來是幫助我的。救我的神啊，不要丟掉我，也不要離棄我。","notes":[]},{"n":10,"t":"我父母離棄我，耶和華必收留我。","notes":[]},{"n":11,"t":"耶和華啊，求你將你的道指教我，因我仇敵的緣故引導我走平坦的路。","notes":[]},{"n":12,"t":"求你不要把我交給敵人，遂其所願；因為妄作見證的和口吐凶言的，起來攻擊我。","notes":[]},{"n":13,"t":"我若不信在活人之地得見耶和華的恩惠，就早已喪膽了。","notes":[]},{"n":14,"t":"要等候耶和華！當壯膽，堅固你的心！我再說，要等候耶和華！","notes":[]}]},"28":{"heading":"求主幫助","verses":[{"n":1,"t":"耶和華啊，我要求告你！我的磐石啊，不要向我緘默！倘若你向我閉口，我就如將死的人一樣。","notes":[]},{"n":2,"t":"我呼求你，向你至聖所舉手的時候，求你垂聽我懇求的聲音！","notes":[]},{"n":3,"t":"不要把我和惡人並作孽的一同除掉；他們與鄰舍說和平話，心裏卻是奸惡。","notes":[]},{"n":4,"t":"願你按著他們所做的，並他們所行的惡事待他們。願你照著他們手所做的待他們，將他們所應得的報應加給他們。","notes":[]},{"n":5,"t":"他們既然不留心耶和華所行的和他手所做的，他就必毀壞他們，不建立他們。","notes":[]},{"n":6,"t":"耶和華是應當稱頌的，因為他聽了我懇求的聲音。","notes":[]},{"n":7,"t":"耶和華是我的力量，是我的盾牌；我心裏倚靠他就得幫助。所以我心中歡樂，我必用詩歌頌讚他。","notes":[]},{"n":8,"t":"耶和華是他百姓的力量，又是他受膏者得救的保障。","notes":[]},{"n":9,"t":"求你拯救你的百姓，賜福給你的產業，牧養他們，扶持他們，直到永遠。","notes":[]}]},"29":{"heading":"在暴風雨中耶和華的威聲","verses":[{"n":1,"t":"神的眾子啊，你們要將榮耀、能力歸給耶和華，歸給耶和華！","notes":[]},{"n":2,"t":"要將耶和華的名所當得的榮耀歸給他，以聖潔的妝飾敬拜耶和華。","notes":["的：或譯為"]},{"n":3,"t":"耶和華的聲音發在水上；榮耀的神打雷，耶和華打雷在大水之上。","notes":[]},{"n":4,"t":"耶和華的聲音大有能力；耶和華的聲音滿有威嚴。","notes":[]},{"n":5,"t":"耶和華的聲音震破香柏樹；耶和華震碎黎巴嫩的香柏樹。","notes":[]},{"n":6,"t":"他也使之跳躍如牛犢，使黎巴嫩和西連跳躍如野牛犢。","notes":[]},{"n":7,"t":"耶和華的聲音使火焰分岔。","notes":[]},{"n":8,"t":"耶和華的聲音震動曠野；耶和華震動加低斯的曠野。","notes":[]},{"n":9,"t":"耶和華的聲音驚動母鹿落胎，樹木也脫落淨光。凡在他殿中的，都稱說他的榮耀。","notes":[]},{"n":10,"t":"洪水泛濫之時，耶和華坐著為王；耶和華坐著為王，直到永遠。","notes":[]},{"n":11,"t":"耶和華必賜力量給他的百姓；耶和華必賜平安的福給他的百姓。","notes":[]}]},"30":{"heading":"感恩的禱告","verses":[{"n":1,"t":"耶和華啊，我要尊崇你，因為你曾提拔我，不叫仇敵向我誇耀。","notes":[]},{"n":2,"t":"耶和華－我的神啊，我曾呼求你，你醫治了我。","notes":[]},{"n":3,"t":"耶和華啊，你曾把我的靈魂從陰間救上來，使我存活，不至於下坑。","notes":[]},{"n":4,"t":"耶和華的聖民哪，你們要歌頌他，稱讚他可記念的聖名。","notes":[]},{"n":5,"t":"因為，他的怒氣不過是轉眼之間；他的恩典乃是一生之久。一宿雖然有哭泣，早晨便必歡呼。","notes":[]},{"n":6,"t":"至於我，我凡事平順，便說：我永不動搖。","notes":[]},{"n":7,"t":"耶和華啊，你曾施恩，叫我的江山穩固；你掩了面，我就驚惶。","notes":[]},{"n":8,"t":"耶和華啊，我曾求告你；我向耶和華懇求，說：","notes":[]},{"n":9,"t":"我被害流血，下到坑中，有甚麼益處呢？塵土豈能稱讚你，傳說你的誠實嗎？","notes":[]},{"n":10,"t":"耶和華啊，求你應允我，憐恤我！耶和華啊，求你幫助我！","notes":[]},{"n":11,"t":"你已將我的哀哭變為跳舞，將我的麻衣脫去，給我披上喜樂，","notes":[]},{"n":12,"t":"好叫我的靈歌頌你，並不住聲。耶和華－我的神啊，我要稱謝你，直到永遠！","notes":["原文是榮耀"]}]},"31":{"heading":"信靠神的祈禱","verses":[{"n":1,"t":"耶和華啊，我投靠你；求你使我永不羞愧；憑你的公義搭救我！","notes":[]},{"n":2,"t":"求你側耳而聽，快快救我！作我堅固的磐石，拯救我的保障！","notes":[]},{"n":3,"t":"因為你是我的巖石，我的山寨；所以，求你為你名的緣故引導我，指點我。","notes":[]},{"n":4,"t":"求你救我脫離人為我暗設的網羅，因為你是我的保障。","notes":[]},{"n":5,"t":"我將我的靈魂交在你手裏；耶和華誠實的神啊，你救贖了我。","notes":[]},{"n":6,"t":"我恨惡那信奉虛無之神的人；我卻倚靠耶和華。","notes":[]},{"n":7,"t":"我要為你的慈愛高興歡喜；因為你見過我的困苦，知道我心中的艱難。","notes":[]},{"n":8,"t":"你未曾把我交在仇敵手裏；你使我的腳站在寬闊之處。","notes":[]},{"n":9,"t":"耶和華啊，求你憐恤我，因為我在急難之中；我的眼睛因憂愁而乾癟，連我的身心也不安舒。","notes":[]},{"n":10,"t":"我的生命為愁苦所消耗；我的年歲為歎息所曠廢。我的力量因我的罪孽衰敗；我的骨頭也枯乾。","notes":[]},{"n":11,"t":"我因一切敵人成了羞辱，在我的鄰舍跟前更甚；那認識我的都懼怕我，在外頭看見我的都躲避我。","notes":[]},{"n":12,"t":"我被人忘記，如同死人，無人記念；我好像破碎的器皿。","notes":[]},{"n":13,"t":"我聽見了許多人的讒謗，四圍都是驚嚇；他們一同商議攻擊我的時候，就圖謀要害我的性命。","notes":[]},{"n":14,"t":"耶和華啊，我仍舊倚靠你；我說：你是我的神。","notes":[]},{"n":15,"t":"我終身的事在你手中；求你救我脫離仇敵的手和那些逼迫我的人。","notes":[]},{"n":16,"t":"求你使你的臉光照僕人，憑你的慈愛拯救我。","notes":[]},{"n":17,"t":"耶和華啊，求你叫我不致羞愧，因為我曾呼籲你；求你使惡人羞愧，使他們在陰間緘默無聲。","notes":[]},{"n":18,"t":"那撒謊的人逞驕傲輕慢，出狂妄的話攻擊義人；願他的嘴啞而無言。","notes":[]},{"n":19,"t":"敬畏你、投靠你的人，你為他們所積存的，在世人面前所施行的恩惠是何等大呢！","notes":[]},{"n":20,"t":"你必把他們藏在你面前的隱密處，免得遇見人的計謀；你必暗暗地保守他們在亭子裏，免受口舌的爭鬧。","notes":[]},{"n":21,"t":"耶和華是應當稱頌的，因為他在堅固城裏向我施展奇妙的慈愛。","notes":[]},{"n":22,"t":"至於我，我曾急促地說：我從你眼前被隔絕。然而，我呼求你的時候，你仍聽我懇求的聲音。","notes":[]},{"n":23,"t":"耶和華的聖民哪，你們都要愛他！耶和華保護誠實人，足足報應行事驕傲的人。","notes":[]},{"n":24,"t":"凡仰望耶和華的人，你們都要壯膽，堅固你們的心！","notes":[]}]},"32":{"heading":"認罪與蒙赦","verses":[{"n":1,"t":"得赦免其過、遮蓋其罪的，這人是有福的！","notes":[]},{"n":2,"t":"凡心裏沒有詭詐、耶和華不算為有罪的，這人是有福的！","notes":[]},{"n":3,"t":"我閉口不認罪的時候，因終日唉哼而骨頭枯乾。","notes":[]},{"n":4,"t":"黑夜白日，你的手在我身上沉重；我的精液耗盡，如同夏天的乾旱。（細拉）","notes":[]},{"n":5,"t":"我向你陳明我的罪，不隱瞞我的惡。我說：我要向耶和華承認我的過犯，你就赦免我的罪惡。（細拉）","notes":[]},{"n":6,"t":"為此，凡虔誠人都當趁你可尋找的時候禱告你；大水泛溢的時候，必不能到他那裏。","notes":[]},{"n":7,"t":"你是我藏身之處；你必保佑我脫離苦難，以得救的樂歌四面環繞我。（細拉）","notes":[]},{"n":8,"t":"我要教導你，指示你當行的路；我要定睛在你身上勸戒你。","notes":[]},{"n":9,"t":"你不可像那無知的騾馬，必用嚼環轡頭勒住牠；不然，就不能馴服。","notes":[]},{"n":10,"t":"惡人必多受苦楚；惟獨倚靠耶和華的必有慈愛四面環繞他。","notes":[]},{"n":11,"t":"你們義人應當靠耶和華歡喜快樂；你們心裏正直的人都當歡呼。","notes":[]}]},"33":{"heading":"頌讚之歌","verses":[{"n":1,"t":"義人哪，你們應當靠耶和華歡樂；正直人的讚美是合宜的。","notes":[]},{"n":2,"t":"你們應當彈琴稱謝耶和華，用十弦瑟歌頌他。","notes":[]},{"n":3,"t":"應當向他唱新歌，彈得巧妙，聲音洪亮。","notes":[]},{"n":4,"t":"因為耶和華的言語正直；凡他所做的盡都誠實。","notes":[]},{"n":5,"t":"他喜愛仁義公平；遍地滿了耶和華的慈愛。","notes":[]},{"n":6,"t":"諸天藉耶和華的命而造；萬象藉他口中的氣而成。","notes":[]},{"n":7,"t":"他聚集海水如壘，收藏深洋在庫房。","notes":[]},{"n":8,"t":"願全地都敬畏耶和華！願世上的居民都懼怕他！","notes":[]},{"n":9,"t":"因為他說有，就有，命立，就立。","notes":[]},{"n":10,"t":"耶和華使列國的籌算歸於無有，使眾民的思念無有功效。","notes":[]},{"n":11,"t":"耶和華的籌算永遠立定；他心中的思念萬代常存。","notes":[]},{"n":12,"t":"以耶和華為神的，那國是有福的！他所揀選為自己產業的，那民是有福的！","notes":[]},{"n":13,"t":"耶和華從天上觀看；他看見一切的世人。","notes":[]},{"n":14,"t":"從他的居所往外察看地上一切的居民－","notes":[]},{"n":15,"t":"他是那造成他們眾人心的，留意他們一切作為的。","notes":[]},{"n":16,"t":"君王不能因兵多得勝；勇士不能因力大得救。","notes":[]},{"n":17,"t":"靠馬得救是枉然的；馬也不能因力大救人。","notes":[]},{"n":18,"t":"耶和華的眼目看顧敬畏他的人和仰望他慈愛的人，","notes":[]},{"n":19,"t":"要救他們的命脫離死亡，並使他們在饑荒中存活。","notes":[]},{"n":20,"t":"我們的心向來等候耶和華；他是我們的幫助，我們的盾牌。","notes":[]},{"n":21,"t":"我們的心必靠他歡喜，因為我們向來倚靠他的聖名。","notes":[]},{"n":22,"t":"耶和華啊，求你照著我們所仰望你的，向我們施行慈愛！","notes":[]}]},"34":{"heading":"頌讚神的美善","verses":[{"n":1,"t":"我要時時稱頌耶和華；讚美他的話必常在我口中。","notes":[]},{"n":2,"t":"我的心必因耶和華誇耀；謙卑人聽見就要喜樂。","notes":[]},{"n":3,"t":"你們和我當稱耶和華為大，一同高舉他的名。","notes":[]},{"n":4,"t":"我曾尋求耶和華，他就應允我，救我脫離了一切的恐懼。","notes":[]},{"n":5,"t":"凡仰望他的，便有光榮；他們的臉必不蒙羞。","notes":[]},{"n":6,"t":"我這困苦人呼求，耶和華便垂聽，救我脫離一切患難。","notes":[]},{"n":7,"t":"耶和華的使者在敬畏他的人四圍安營，搭救他們。","notes":[]},{"n":8,"t":"你們要嘗嘗主恩的滋味，便知道他是美善；投靠他的人有福了！","notes":[]},{"n":9,"t":"耶和華的聖民哪，你們當敬畏他，因敬畏他的一無所缺。","notes":[]},{"n":10,"t":"少壯獅子還缺食忍餓，但尋求耶和華的甚麼好處都不缺。","notes":[]},{"n":11,"t":"眾弟子啊，你們當來聽我的話！我要將敬畏耶和華的道教訓你們。","notes":[]},{"n":12,"t":"有何人喜好存活，愛慕長壽，得享美福，","notes":[]},{"n":13,"t":"就要禁止舌頭不出惡言，嘴唇不說詭詐的話。","notes":[]},{"n":14,"t":"要離惡行善，尋求和睦，一心追趕。","notes":[]},{"n":15,"t":"耶和華的眼目看顧義人；他的耳朵聽他們的呼求。","notes":[]},{"n":16,"t":"耶和華向行惡的人變臉，要從世上除滅他們的名號。","notes":[]},{"n":17,"t":"義人呼求，耶和華聽見了，便救他們脫離一切患難。","notes":[]},{"n":18,"t":"耶和華靠近傷心的人，拯救靈性痛悔的人。","notes":[]},{"n":19,"t":"義人多有苦難，但耶和華救他脫離這一切，","notes":[]},{"n":20,"t":"又保全他一身的骨頭，連一根也不折斷。","notes":[]},{"n":21,"t":"惡必害死惡人；恨惡義人的，必被定罪。","notes":[]},{"n":22,"t":"耶和華救贖他僕人的靈魂；凡投靠他的，必不致定罪。","notes":[]}]},"35":{"heading":"求助的禱告","verses":[{"n":1,"t":"耶和華啊，與我相爭的，求你與他們相爭！與我相戰的，求你與他們相戰！","notes":[]},{"n":2,"t":"拿著大小的盾牌，起來幫助我。","notes":[]},{"n":3,"t":"抽出槍來，擋住那追趕我的；求你對我的靈魂說：我是拯救你的。","notes":[]},{"n":4,"t":"願那尋索我命的，蒙羞受辱！願那謀害我的，退後羞愧！","notes":[]},{"n":5,"t":"願他們像風前的糠，有耶和華的使者趕逐他們。","notes":[]},{"n":6,"t":"願他們的道路又暗又滑，有耶和華的使者追趕他們。","notes":[]},{"n":7,"t":"因他們無故地為我暗設網羅，無故地挖坑，要害我的性命。","notes":[]},{"n":8,"t":"願災禍忽然臨到他身上！願他暗設的網纏住自己！願他落在其中遭災禍！","notes":[]},{"n":9,"t":"我的心必靠耶和華快樂，靠他的救恩高興。","notes":[]},{"n":10,"t":"我的骨頭都要說：耶和華啊，誰能像你救護困苦人脫離那比他強壯的，救護困苦窮乏人脫離那搶奪他的？","notes":[]},{"n":11,"t":"凶惡的見證人起來，盤問我所不知道的事。","notes":[]},{"n":12,"t":"他們向我以惡報善，使我的靈魂孤苦。","notes":[]},{"n":13,"t":"至於我，當他們有病的時候，我便穿麻衣，禁食，刻苦己心；我所求的都歸到自己的懷中。","notes":[]},{"n":14,"t":"我這樣行，好像他是我的朋友，我的弟兄；我屈身悲哀，如同人為母親哀痛。","notes":[]},{"n":15,"t":"我在患難中，他們卻歡喜，大家聚集。我所不認識的那些下流人聚集攻擊我；他們不住地把我撕裂。","notes":[]},{"n":16,"t":"他們如同席上好嬉笑的狂妄人向我咬牙。","notes":[]},{"n":17,"t":"主啊，你看著不理要到幾時呢？求你救我的靈魂脫離他們的殘害！救我的生命脫離少壯獅子！","notes":["生命：原文是獨一者"]},{"n":18,"t":"我在大會中要稱謝你，在眾民中要讚美你。","notes":[]},{"n":19,"t":"求你不容那無理與我為仇的向我誇耀！不容那無故恨我的向我擠眼！","notes":[]},{"n":20,"t":"因為他們不說和平話，倒想出詭詐的言語害地上的安靜人。","notes":[]},{"n":21,"t":"他們大大張口攻擊我，說：阿哈，阿哈，我們的眼已經看見了！","notes":[]},{"n":22,"t":"耶和華啊，你已經看見了，求你不要閉口！主啊，求你不要遠離我！","notes":[]},{"n":23,"t":"我的神我的主啊，求你奮興醒起，判清我的事，伸明我的冤！","notes":[]},{"n":24,"t":"耶和華－我的神啊，求你按你的公義判斷我，不容他們向我誇耀！","notes":[]},{"n":25,"t":"不容他們心裏說：阿哈，遂我們的心願了！不容他們說：我們已經把他吞了！","notes":[]},{"n":26,"t":"願那喜歡我遭難的一同抱愧蒙羞！願那向我妄自尊大的披慚愧，蒙羞辱！","notes":[]},{"n":27,"t":"願那喜悅我冤屈得伸的歡呼快樂；願他們常說：當尊耶和華為大！耶和華喜悅他的僕人平安。","notes":["冤屈得伸：原文是公義"]},{"n":28,"t":"我的舌頭要終日論說你的公義，時常讚美你。","notes":[]}]},"36":{"heading":"人的邪惡","verses":[{"n":1,"t":"惡人的罪過在他心裏說：我眼中不怕神！","notes":[]},{"n":2,"t":"他自誇自媚，以為他的罪孽終不顯露，不被恨惡。","notes":[]},{"n":3,"t":"他口中的言語盡是罪孽詭詐；他與智慧善行已經斷絕。","notes":[]},{"n":4,"t":"他在床上圖謀罪孽，定意行不善的道，不憎惡惡事。","notes":[]},{"n":5,"t":"耶和華啊，你的慈愛上及諸天；你的信實達到穹蒼。","notes":[],"heads":["神的良善"]},{"n":6,"t":"你的公義好像高山；你的判斷如同深淵。耶和華啊，人民、牲畜，你都救護。","notes":[]},{"n":7,"t":"神啊，你的慈愛何其寶貴！世人投靠在你翅膀的蔭下。","notes":[]},{"n":8,"t":"他們必因你殿裏的肥甘得以飽足；你也必叫他們喝你樂河的水。","notes":[]},{"n":9,"t":"因為，在你那裏有生命的源頭；在你的光中，我們必得見光。","notes":[]},{"n":10,"t":"願你常施慈愛給認識你的人，常以公義待心裏正直的人。","notes":[]},{"n":11,"t":"不容驕傲人的腳踐踏我；不容凶惡人的手趕逐我。","notes":[]},{"n":12,"t":"在那裏，作孽的人已經仆倒；他們被推倒，不能再起來。","notes":[]}]},"37":{"heading":"義人和惡人的結局","verses":[{"n":1,"t":"不要為作惡的心懷不平，也不要向那行不義的生出嫉妒。","notes":[]},{"n":2,"t":"因為他們如草快被割下，又如青菜快要枯乾。","notes":[]},{"n":3,"t":"你當倚靠耶和華而行善，住在地上，以他的信實為糧；","notes":[]},{"n":4,"t":"又要以耶和華為樂，他就將你心裏所求的賜給你。","notes":[]},{"n":5,"t":"當將你的事交託耶和華，並倚靠他，他就必成全。","notes":[]},{"n":6,"t":"他要使你的公義如光發出，使你的公平明如正午。","notes":[]},{"n":7,"t":"你當默然倚靠耶和華，耐性等候他；不要因那道路通達的和那惡謀成就的心懷不平。","notes":[]},{"n":8,"t":"當止住怒氣，離棄忿怒；不要心懷不平，以致作惡。","notes":[]},{"n":9,"t":"因為作惡的必被剪除；惟有等候耶和華的必承受地土。","notes":[]},{"n":10,"t":"還有片時，惡人要歸於無有；你就是細察他的住處也要歸於無有。","notes":[]},{"n":11,"t":"但謙卑人必承受地土，以豐盛的平安為樂。","notes":[]},{"n":12,"t":"惡人設謀害義人，又向他咬牙。","notes":[]},{"n":13,"t":"主要笑他，因見他受罰的日子將要來到。","notes":[]},{"n":14,"t":"惡人已經弓上弦，刀出鞘，要打倒困苦窮乏的人，要殺害行動正直的人。","notes":[]},{"n":15,"t":"他們的刀必刺入自己的心；他們的弓必被折斷。","notes":[]},{"n":16,"t":"一個義人所有的雖少，強過許多惡人的富餘。","notes":[]},{"n":17,"t":"因為惡人的膀臂必被折斷；但耶和華是扶持義人。","notes":[]},{"n":18,"t":"耶和華知道完全人的日子；他們的產業要存到永遠。","notes":[]},{"n":19,"t":"他們在急難的時候不致羞愧，在饑荒的日子必得飽足。","notes":[]},{"n":20,"t":"惡人卻要滅亡。耶和華的仇敵要像羊羔的脂油；他們要消滅，要如煙消滅。","notes":["或譯：像草地的華美"]},{"n":21,"t":"惡人借貸而不償還；義人卻恩待人，並且施捨。","notes":[]},{"n":22,"t":"蒙耶和華賜福的必承受地土；被他咒詛的必被剪除。","notes":[]},{"n":23,"t":"義人的腳步被耶和華立定；他的道路，耶和華也喜愛。","notes":[]},{"n":24,"t":"他雖失腳也不致全身仆倒，因為耶和華用手攙扶他。","notes":["或譯：攙扶他的手"]},{"n":25,"t":"我從前年幼，現在年老，卻未見過義人被棄，也未見過他的後裔討飯。","notes":[]},{"n":26,"t":"他終日恩待人，借給人；他的後裔也蒙福！","notes":[]},{"n":27,"t":"你當離惡行善，就可永遠安居。","notes":[]},{"n":28,"t":"因為，耶和華喜愛公平，不撇棄他的聖民；他們永蒙保佑，但惡人的後裔必被剪除。","notes":[]},{"n":29,"t":"義人必承受地土，永居其上。","notes":[]},{"n":30,"t":"義人的口談論智慧；他的舌頭講說公平。","notes":[]},{"n":31,"t":"神的律法在他心裏；他的腳總不滑跌。","notes":[]},{"n":32,"t":"惡人窺探義人，想要殺他。","notes":[]},{"n":33,"t":"耶和華必不撇他在惡人手中；當審判的時候，也不定他的罪。","notes":[]},{"n":34,"t":"你當等候耶和華，遵守他的道，他就抬舉你，使你承受地土；惡人被剪除的時候，你必看見。","notes":[]},{"n":35,"t":"我見過惡人大有勢力，好像一棵青翠樹在本土生發。","notes":[]},{"n":36,"t":"有人從那裏經過，不料，他沒有了；我也尋找他，卻尋不著。","notes":[]},{"n":37,"t":"你要細察那完全人，觀看那正直人，因為和平人有好結局。","notes":[]},{"n":38,"t":"至於犯法的人，必一同滅絕；惡人終必剪除。","notes":[]},{"n":39,"t":"但義人得救是由於耶和華；他在患難時作他們的營寨。","notes":[]},{"n":40,"t":"耶和華幫助他們，解救他們；他解救他們脫離惡人，把他們救出來，因為他們投靠他。","notes":[]}]},"38":{"heading":"受苦者的祈禱","verses":[{"n":1,"t":"耶和華啊，求你不要在怒中責備我，不要在烈怒中懲罰我！","notes":[]},{"n":2,"t":"因為，你的箭射入我身；你的手壓住我。","notes":[]},{"n":3,"t":"因你的惱怒，我的肉無一完全；因我的罪過，我的骨頭也不安寧。","notes":[]},{"n":4,"t":"我的罪孽高過我的頭，如同重擔叫我擔當不起。","notes":[]},{"n":5,"t":"因我的愚昧，我的傷發臭流膿。","notes":[]},{"n":6,"t":"我疼痛，大大拳曲，終日哀痛。","notes":[]},{"n":7,"t":"我滿腰是火；我的肉無一完全。","notes":[]},{"n":8,"t":"我被壓傷，身體疲倦；因心裏不安，我就唉哼。","notes":[]},{"n":9,"t":"主啊，我的心願都在你面前；我的歎息不向你隱瞞。","notes":[]},{"n":10,"t":"我心跳動，我力衰微，連我眼中的光也沒有了。","notes":[]},{"n":11,"t":"我的良朋密友因我的災病都躲在旁邊站著；我的親戚本家也遠遠地站立。","notes":[]},{"n":12,"t":"那尋索我命的設下網羅；那想要害我的口出惡言，終日思想詭計。","notes":[]},{"n":13,"t":"但我如聾子不聽，像啞巴不開口。","notes":[]},{"n":14,"t":"我如不聽見的人，口中沒有回話。","notes":[]},{"n":15,"t":"耶和華啊，我仰望你！主－我的神啊，你必應允我！","notes":[]},{"n":16,"t":"我曾說：恐怕他們向我誇耀；我失腳的時候，他們向我誇大。","notes":[]},{"n":17,"t":"我幾乎跌倒；我的痛苦常在我面前。","notes":[]},{"n":18,"t":"我要承認我的罪孽；我要因我的罪憂愁。","notes":[]},{"n":19,"t":"但我的仇敵又活潑又強壯，無理恨我的增多了。","notes":[]},{"n":20,"t":"以惡報善的與我作對，因我是追求良善。","notes":[]},{"n":21,"t":"耶和華啊，求你不要撇棄我！我的神啊，求你不要遠離我！","notes":[]},{"n":22,"t":"拯救我的主啊，求你快快幫助我！","notes":[]}]},"39":{"heading":"受苦者的認罪","verses":[{"n":1,"t":"我曾說：我要謹慎我的言行，免得我舌頭犯罪；惡人在我面前的時候，我要用嚼環勒住我的口。","notes":[]},{"n":2,"t":"我默然無聲，連好話也不出口；我的愁苦就發動了，","notes":[]},{"n":3,"t":"我的心在我裏面發熱。我默想的時候，火就燒起，我便用舌頭說話。","notes":[]},{"n":4,"t":"耶和華啊，求你叫我曉得我身之終！我的壽數幾何？叫我知道我的生命不長！","notes":[]},{"n":5,"t":"你使我的年日窄如手掌；我一生的年數，在你面前如同無有。各人最穩妥的時候，真是全然虛幻。（細拉）","notes":[]},{"n":6,"t":"世人行動實係幻影。他們忙亂，真是枉然；積蓄財寶，不知將來有誰收取。","notes":[]},{"n":7,"t":"主啊，如今我等甚麼呢？我的指望在乎你！","notes":[]},{"n":8,"t":"求你救我脫離一切的過犯，不要使我受愚頑人的羞辱。","notes":[]},{"n":9,"t":"因我所遭遇的是出於你，我就默然不語。","notes":[]},{"n":10,"t":"求你把你的責罰從我身上免去；因你手的責打，我便消滅。","notes":[]},{"n":11,"t":"你因人的罪惡懲罰他的時候，叫他的笑容消滅，如衣被蟲所咬。世人真是虛幻！（細拉）","notes":["的笑容：或譯所喜愛的"]},{"n":12,"t":"耶和華啊，求你聽我的禱告，留心聽我的呼求！我流淚，求你不要靜默無聲！因為我在你面前是客旅，是寄居的，像我列祖一般。","notes":[]},{"n":13,"t":"求你寬容我，使我在去而不返之先可以力量復原。","notes":[]}]},"40":{"heading":"頌讚之歌","verses":[{"n":1,"t":"我曾耐性等候耶和華；他垂聽我的呼求。","notes":[]},{"n":2,"t":"他從禍坑裏，從淤泥中，把我拉上來，使我的腳立在磐石上，使我腳步穩當。","notes":[]},{"n":3,"t":"他使我口唱新歌，就是讚美我們神的話。許多人必看見而懼怕，並要倚靠耶和華。","notes":[]},{"n":4,"t":"那倚靠耶和華、不理會狂傲和偏向虛假之輩的，這人便為有福！","notes":[]},{"n":5,"t":"耶和華－我的神啊，你所行的奇事，並你向我們所懷的意念甚多，不能向你陳明；若要陳明，其事不可勝數。","notes":[]},{"n":6,"t":"祭物和禮物，你不喜悅；你已經開通我的耳朵。燔祭和贖罪祭非你所要。","notes":[]},{"n":7,"t":"那時我說：看哪，我來了！我的事在經卷上已經記載了。","notes":[]},{"n":8,"t":"我的神啊，我樂意照你的旨意行；你的律法在我心裏。","notes":[]},{"n":9,"t":"我在大會中宣傳公義的佳音；我必不止住我的嘴唇。耶和華啊，這是你所知道的。","notes":[]},{"n":10,"t":"我未曾把你的公義藏在心裏；我已陳明你的信實和你的救恩；我在大會中未曾隱瞞你的慈愛和誠實。","notes":[]},{"n":11,"t":"耶和華啊，求你不要向我止住你的慈悲！願你的慈愛和誠實常常保佑我！","notes":[]},{"n":12,"t":"因有無數的禍患圍困我，我的罪孽追上了我，使我不能昂首；這罪孽比我的頭髮還多，我就心寒膽戰。","notes":[],"heads":["求助的禱告"]},{"n":13,"t":"耶和華啊，求你開恩搭救我！耶和華啊，求你速速幫助我！","notes":[]},{"n":14,"t":"願那些尋找我、要滅我命的，一同抱愧蒙羞！願那些喜悅我受害的，退後受辱！","notes":[]},{"n":15,"t":"願那些對我說阿哈、阿哈的，因羞愧而敗亡！","notes":[]},{"n":16,"t":"願一切尋求你的，因你高興歡喜！願那些喜愛你救恩的，常說：當尊耶和華為大！","notes":[]},{"n":17,"t":"但我是困苦窮乏的，主仍顧念我；你是幫助我的，搭救我的。神啊，求你不要耽延！","notes":[]}]},"41":{"heading":"病中祈禱","verses":[{"n":1,"t":"眷顧貧窮的有福了！他遭難的日子，耶和華必搭救他。","notes":[]},{"n":2,"t":"耶和華必保全他，使他存活；他必在地上享福。求你不要把他交給仇敵，遂其所願。","notes":[]},{"n":3,"t":"他病重在榻，耶和華必扶持他；他在病中，你必給他鋪床。","notes":[]},{"n":4,"t":"我曾說：耶和華啊，求你憐恤我，醫治我！因為我得罪了你。","notes":[]},{"n":5,"t":"我的仇敵用惡言議論我說：他幾時死，他的名才滅亡呢？","notes":[]},{"n":6,"t":"他來看我就說假話；他心存奸惡，走到外邊才說出來。","notes":[]},{"n":7,"t":"一切恨我的，都交頭接耳地議論我；他們設計要害我。","notes":[]},{"n":8,"t":"他們說：有怪病貼在他身上；他已躺臥，必不能再起來。","notes":[]},{"n":9,"t":"連我知己的朋友，我所倚靠、吃過我飯的也用腳踢我。","notes":[]},{"n":10,"t":"耶和華啊，求你憐恤我，使我起來，好報復他們！","notes":[]},{"n":11,"t":"因我的仇敵不得向我誇勝，我從此便知道你喜愛我。","notes":[]},{"n":12,"t":"你因我純正就扶持我，使我永遠站在你的面前。","notes":[]},{"n":13,"t":"耶和華－以色列的神是應當稱頌的，從亙古直到永遠。阿們！阿們！","notes":[]}]},"42":{"heading":"流亡異鄉者的禱告﹙一﹚","verses":[{"n":1,"t":"神啊，我的心切慕你，如鹿切慕溪水。","notes":[]},{"n":2,"t":"我的心渴想神，就是永生神；我幾時得朝見神呢？","notes":[]},{"n":3,"t":"我晝夜以眼淚當飲食；人不住地對我說：你的神在哪裏呢？","notes":[]},{"n":4,"t":"我從前與眾人同往，用歡呼稱讚的聲音領他們到神的殿裏，大家守節。我追想這些事，我的心極其悲傷。","notes":[]},{"n":5,"t":"我的心哪，你為何憂悶？為何在我裏面煩躁？應當仰望神，因他笑臉幫助我；我還要稱讚他。","notes":[]},{"n":6,"t":"我的神啊，我的心在我裏面憂悶，所以我從約旦地，從黑門嶺，從米薩山記念你。","notes":[]},{"n":7,"t":"你的瀑布發聲，深淵就與深淵響應；你的波浪洪濤漫過我身。","notes":[]},{"n":8,"t":"白晝，耶和華必向我施慈愛；黑夜，我要歌頌禱告賜我生命的神。","notes":[]},{"n":9,"t":"我要對神－我的磐石說：你為何忘記我呢？我為何因仇敵的欺壓時常哀痛呢？","notes":[]},{"n":10,"t":"我的敵人辱罵我，好像打碎我的骨頭，不住地對我說：你的神在哪裏呢？","notes":[]},{"n":11,"t":"我的心哪，你為何憂悶？為何在我裏面煩躁？應當仰望神，因我還要稱讚他。他是我臉上的光榮，是我的神。","notes":["原文是幫助"]}]},"43":{"heading":"流亡異鄉者的禱告﹙二﹚","verses":[{"n":1,"t":"神啊，求你伸我的冤，向不虔誠的國為我辨屈；求你救我脫離詭詐不義的人。","notes":[]},{"n":2,"t":"因為你是賜我力量的神，為何丟棄我呢？我為何因仇敵的欺壓時常哀痛呢？","notes":[]},{"n":3,"t":"求你發出你的亮光和真實，好引導我，帶我到你的聖山，到你的居所！","notes":[]},{"n":4,"t":"我就走到神的祭壇，到我最喜樂的神那裏。神啊，我的神，我要彈琴稱讚你！","notes":[]},{"n":5,"t":"我的心哪，你為何憂悶？為何在我裏面煩躁？應當仰望神，因我還要稱讚他。他是我臉上的光榮，是我的神。","notes":["原文是幫助"]}]},"44":{"heading":"求主保護","verses":[{"n":1,"t":"神啊，你在古時，我們列祖的日子所行的事，我們親耳聽見了；我們的列祖也給我們述說過。","notes":[]},{"n":2,"t":"你曾用手趕出外邦人，卻栽培了我們列祖；你苦待列邦，卻叫我們列祖發達。","notes":[]},{"n":3,"t":"因為他們不是靠自己的刀劍得地土，也不是靠自己的膀臂得勝，乃是靠你的右手、你的膀臂，和你臉上的亮光，因為你喜悅他們。","notes":[]},{"n":4,"t":"神啊，你是我的王；求你出令使雅各得勝。","notes":[]},{"n":5,"t":"我們靠你要推倒我們的敵人，靠你的名要踐踏那起來攻擊我們的人。","notes":[]},{"n":6,"t":"因為，我必不靠我的弓；我的刀也不能使我得勝。","notes":[]},{"n":7,"t":"惟你救了我們脫離敵人，使恨我們的人羞愧。","notes":[]},{"n":8,"t":"我們終日因神誇耀，還要永遠稱謝你的名。（細拉）","notes":[]},{"n":9,"t":"但如今你丟棄了我們，使我們受辱，不和我們的軍兵同去。","notes":[]},{"n":10,"t":"你使我們向敵人轉身退後；那恨我們的人任意搶奪。","notes":[]},{"n":11,"t":"你使我們當作快要被吃的羊，把我們分散在列邦中。","notes":[]},{"n":12,"t":"你賣了你的子民也不賺利，所得的價值並不加添你的資財。","notes":[]},{"n":13,"t":"你使我們受鄰國的羞辱，被四圍的人嗤笑譏刺。","notes":[]},{"n":14,"t":"你使我們在列邦中作了笑談，使眾民向我們搖頭。","notes":[]},{"n":15,"t":"我的凌辱終日在我面前，我臉上的羞愧將我遮蔽，","notes":[]},{"n":16,"t":"都因那辱罵毀謗人的聲音，又因仇敵和報仇人的緣故。","notes":[]},{"n":17,"t":"這都臨到我們身上，我們卻沒有忘記你，也沒有違背你的約。","notes":[]},{"n":18,"t":"我們的心沒有退後；我們的腳也沒有偏離你的路。","notes":[]},{"n":19,"t":"你在野狗之處壓傷我們，用死蔭遮蔽我們。","notes":[]},{"n":20,"t":"倘若我們忘了神的名，或向別神舉手，","notes":[]},{"n":21,"t":"神豈不鑒察這事嗎？因為他曉得人心裏的隱秘。","notes":[]},{"n":22,"t":"我們為你的緣故終日被殺；人看我們如將宰的羊。","notes":[]},{"n":23,"t":"主啊，求你睡醒，為何儘睡呢？求你興起，不要永遠丟棄我們！","notes":[]},{"n":24,"t":"你為何掩面，不顧我們所遭的苦難和所受的欺壓？","notes":[]},{"n":25,"t":"我們的性命伏於塵土；我們的肚腹緊貼地面。","notes":[]},{"n":26,"t":"求你起來幫助我們！憑你的慈愛救贖我們！","notes":[]}]},"45":{"heading":"王家婚禮詩歌","verses":[{"n":1,"t":"我心裏湧出美辭；我論到我為王做的事，我的舌頭是快手筆。","notes":[]},{"n":2,"t":"你比世人更美；在你嘴裏滿有恩惠；所以神賜福給你，直到永遠。","notes":[]},{"n":3,"t":"大能者啊，願你腰間佩刀，大有榮耀和威嚴！","notes":[]},{"n":4,"t":"為真理、謙卑、公義赫然坐車前往，無不得勝；你的右手必顯明可畏的事。","notes":[]},{"n":5,"t":"你的箭鋒快，射中王敵之心；萬民仆倒在你以下。","notes":[]},{"n":6,"t":"神啊，你的寶座是永永遠遠的；你的國權是正直的。","notes":[]},{"n":7,"t":"你喜愛公義，恨惡罪惡；所以神－就是你的神－用喜樂油膏你，勝過膏你的同伴。","notes":[]},{"n":8,"t":"你的衣服都有沒藥、沉香、肉桂的香氣；象牙宮中有絲弦樂器的聲音使你歡喜。","notes":[]},{"n":9,"t":"有君王的女兒在你尊貴婦女之中；王后佩戴俄斐金飾站在你右邊。","notes":[]},{"n":10,"t":"女子啊，你要聽，要想，要側耳而聽！不要記念你的民和你的父家，","notes":[]},{"n":11,"t":"王就羨慕你的美貌；因為他是你的主，你當敬拜他。","notes":[]},{"n":12,"t":"泰爾的民必來送禮；民中的富足人也必向你求恩。","notes":["原文是女子"]},{"n":13,"t":"王女在宮裏極其榮華；她的衣服是用金線繡的。","notes":[]},{"n":14,"t":"她要穿錦繡的衣服，被引到王前；隨從她的陪伴童女也要被帶到你面前。","notes":[]},{"n":15,"t":"她們要歡喜快樂被引導；她們要進入王宮。","notes":[]},{"n":16,"t":"你的子孫要接續你的列祖；你要立他們在全地作王。","notes":[]},{"n":17,"t":"我必叫你的名被萬代記念，所以萬民要永永遠遠稱謝你。","notes":[]}]},"46":{"heading":"神與我們同在","verses":[{"n":1,"t":"神是我們的避難所，是我們的力量，是我們在患難中隨時的幫助。","notes":[]},{"n":2,"t":"所以，地雖改變，山雖搖動到海心，","notes":[]},{"n":3,"t":"其中的水雖匉訇翻騰，山雖因海漲而戰抖，我們也不害怕。（細拉）","notes":[]},{"n":4,"t":"有一道河，這河的分汊使神的城歡喜；這城就是至高者居住的聖所。","notes":[]},{"n":5,"t":"神在其中，城必不動搖；到天一亮，神必幫助這城。","notes":[]},{"n":6,"t":"外邦喧嚷，列國動搖；神發聲，地便鎔化。","notes":[]},{"n":7,"t":"萬軍之耶和華與我們同在；雅各的神是我們的避難所！（細拉）","notes":[]},{"n":8,"t":"你們來看耶和華的作為，看他使地怎樣荒涼。","notes":[]},{"n":9,"t":"他止息刀兵，直到地極；他折弓、斷槍，把戰車焚燒在火中。","notes":[]},{"n":10,"t":"你們要休息，要知道我是神！我必在外邦中被尊崇，在遍地上也被尊崇。","notes":[]},{"n":11,"t":"萬軍之耶和華與我們同在；雅各的神是我們的避難所！","notes":[]}]},"47":{"heading":"至高的主宰","verses":[{"n":1,"t":"萬民哪，你們都要拍掌！要用誇勝的聲音向神呼喊！","notes":[]},{"n":2,"t":"因為耶和華至高者是可畏的；他是治理全地的大君王。","notes":[]},{"n":3,"t":"他叫萬民服在我們以下，又叫列邦服在我們腳下。","notes":[]},{"n":4,"t":"他為我們選擇產業，就是他所愛之雅各的榮耀。（細拉）","notes":[]},{"n":5,"t":"神上升，有喊聲相送；耶和華上升，有角聲相送。","notes":[]},{"n":6,"t":"你們要向神歌頌，歌頌！向我們王歌頌，歌頌！","notes":[]},{"n":7,"t":"因為神是全地的王；你們要用悟性歌頌。","notes":[]},{"n":8,"t":"神作王治理萬國；神坐在他的聖寶座上。","notes":[]},{"n":9,"t":"列邦的君王聚集要作亞伯拉罕之神的民。因為世界的盾牌是屬神的；他為至高！","notes":[]}]},"48":{"heading":"錫安－神的城","verses":[{"n":1,"t":"耶和華本為大！在我們神的城中，在他的聖山上，該受大讚美。","notes":[]},{"n":2,"t":"錫安山－大君王的城，在北面居高華美，為全地所喜悅。","notes":[]},{"n":3,"t":"神在其宮中，自顯為避難所。","notes":[]},{"n":4,"t":"看哪，眾王會合，一同經過。","notes":[]},{"n":5,"t":"他們見了這城就驚奇喪膽，急忙逃跑。","notes":[]},{"n":6,"t":"他們在那裏被戰兢疼痛抓住，好像產難的婦人一樣。","notes":[]},{"n":7,"t":"神啊，你用東風打破他施的船隻。","notes":[]},{"n":8,"t":"我們在萬軍之耶和華的城中－就是我們神的城中－所看見的，正如我們所聽見的。神必堅立這城，直到永遠。（細拉）","notes":[]},{"n":9,"t":"神啊，我們在你的殿中想念你的慈愛。","notes":[]},{"n":10,"t":"神啊，你受的讚美正與你的名相稱，直到地極！你的右手滿了公義。","notes":[]},{"n":11,"t":"因你的判斷，錫安山應當歡喜，猶大的城邑應當快樂。","notes":["原文是女子"]},{"n":12,"t":"你們當周遊錫安，四圍旋繞，數點城樓，","notes":[]},{"n":13,"t":"細看她的外郭，察看她的宮殿，為要傳說到後代。","notes":[]},{"n":14,"t":"因為這神永永遠遠為我們的神；他必作我們引路的，直到死時。","notes":[]}]},"49":{"heading":"恃財之愚","verses":[{"n":1,"t":"萬民哪，你們都當聽這話！世上一切的居民，","notes":[]},{"n":2,"t":"無論上流下流，富足貧窮，都當留心聽！","notes":[]},{"n":3,"t":"我口要說智慧的言語；我心要想通達的道理。","notes":[]},{"n":4,"t":"我要側耳聽比喻，用琴解謎語。","notes":[]},{"n":5,"t":"在患難的日子，奸惡隨我腳跟，四面環繞我，我何必懼怕？","notes":[]},{"n":6,"t":"那些倚仗財貨自誇錢財多的人，","notes":[]},{"n":7,"t":"一個也無法贖自己的弟兄，也不能替他將贖價給神，","notes":[]},{"n":8,"t":"叫他長遠活著，不見朽壞；因為贖他生命的價值極貴，只可永遠罷休。","notes":[],"end":9},{"n":10,"t":"他必見智慧人死，又見愚頑人和畜類人一同滅亡，將他們的財貨留給別人。","notes":[]},{"n":11,"t":"他們心裏思想：他們的家室必永存，住宅必留到萬代；他們以自己的名稱自己的地。","notes":[]},{"n":12,"t":"但人居尊貴中不能長久，如同死亡的畜類一樣。","notes":[]},{"n":13,"t":"他們行的這道本為自己的愚昧；但他們以後的人還佩服他們的話語。（細拉）","notes":[]},{"n":14,"t":"他們如同羊群派定下陰間；死亡必作他們的牧者。到了早晨，正直人必管轄他們；他們的美容必被陰間所滅，以致無處可存。","notes":[]},{"n":15,"t":"只是神必救贖我的靈魂脫離陰間的權柄，因他必收納我。（細拉）","notes":[]},{"n":16,"t":"見人發財、家室增榮的時候，你不要懼怕；","notes":[]},{"n":17,"t":"因為，他死的時候甚麼也不能帶去；他的榮耀不能隨他下去。","notes":[]},{"n":18,"t":"他活著的時候，雖然自誇為有福（你若利己，人必誇獎你）；","notes":[]},{"n":19,"t":"他仍必歸到他歷代的祖宗那裏，永不見光。","notes":[]},{"n":20,"t":"人在尊貴中而不醒悟，就如死亡的畜類一樣。","notes":[]}]},"50":{"heading":"真實的敬拜","verses":[{"n":1,"t":"大能者神－耶和華已經發言招呼天下，從日出之地到日落之處。","notes":[]},{"n":2,"t":"從全美的錫安中，神已經發光了。","notes":[]},{"n":3,"t":"我們的神要來，決不閉口。有烈火在他面前吞滅；有暴風在他四圍大颳。","notes":[]},{"n":4,"t":"他招呼上天下地，為要審判他的民，","notes":[]},{"n":5,"t":"說：招聚我的聖民到我這裏來，就是那些用祭物與我立約的人。","notes":[]},{"n":6,"t":"諸天必表明他的公義，因為神是施行審判的。（細拉）","notes":[]},{"n":7,"t":"我的民哪，你們當聽我的話！以色列啊，我要勸戒你；我是神，是你的神！","notes":[]},{"n":8,"t":"我並不因你的祭物責備你；你的燔祭常在我面前。","notes":[]},{"n":9,"t":"我不從你家中取公牛，也不從你圈內取山羊；","notes":[]},{"n":10,"t":"因為，樹林中的百獸是我的，千山上的牲畜也是我的。","notes":[]},{"n":11,"t":"山中的飛鳥，我都知道；野地的走獸也都屬我。","notes":[]},{"n":12,"t":"我若是飢餓，我不用告訴你，因為世界和其中所充滿的都是我的。","notes":[]},{"n":13,"t":"我豈吃公牛的肉呢？我豈喝山羊的血呢？","notes":[]},{"n":14,"t":"你們要以感謝為祭獻與神，又要向至高者還你的願，","notes":[]},{"n":15,"t":"並要在患難之日求告我；我必搭救你，你也要榮耀我。","notes":[]},{"n":16,"t":"但神對惡人說：你怎敢傳說我的律例，口中提到我的約呢？","notes":[]},{"n":17,"t":"其實你恨惡管教，將我的言語丟在背後。","notes":[]},{"n":18,"t":"你見了盜賊就樂意與他同夥，又與行姦淫的人一同有分。","notes":[]},{"n":19,"t":"你口任說惡言；你舌編造詭詐。","notes":[]},{"n":20,"t":"你坐著毀謗你的兄弟，讒毀你親母的兒子。","notes":[]},{"n":21,"t":"你行了這些事，我還閉口不言，你想我恰和你一樣；其實我要責備你，將這些事擺在你眼前。","notes":[]},{"n":22,"t":"你們忘記神的，要思想這事，免得我把你們撕碎，無人搭救。","notes":[]},{"n":23,"t":"凡以感謝獻上為祭的便是榮耀我；那按正路而行的，我必使他得著我的救恩。","notes":[]}]},"51":{"heading":"求主赦免","verses":[{"n":1,"t":"神啊，求你按你的慈愛憐恤我！按你豐盛的慈悲塗抹我的過犯！","notes":[]},{"n":2,"t":"求你將我的罪孽洗除淨盡，並潔除我的罪！","notes":[]},{"n":3,"t":"因為，我知道我的過犯；我的罪常在我面前。","notes":[]},{"n":4,"t":"我向你犯罪，惟獨得罪了你；在你眼前行了這惡，以致你責備我的時候顯為公義，判斷我的時候顯為清正。","notes":[]},{"n":5,"t":"我是在罪孽裏生的，在我母親懷胎的時候就有了罪。","notes":[]},{"n":6,"t":"你所喜愛的是內裏誠實；你在我隱密處，必使我得智慧。","notes":[]},{"n":7,"t":"求你用牛膝草潔淨我，我就乾淨；求你洗滌我，我就比雪更白。","notes":[]},{"n":8,"t":"求你使我得聽歡喜快樂的聲音，使你所壓傷的骨頭可以踴躍。","notes":[]},{"n":9,"t":"求你掩面不看我的罪，塗抹我一切的罪孽。","notes":[]},{"n":10,"t":"神啊，求你為我造清潔的心，使我裏面重新有正直的靈。","notes":["或譯：堅定"]},{"n":11,"t":"不要丟棄我，使我離開你的面；不要從我收回你的聖靈。","notes":[]},{"n":12,"t":"求你使我仍得救恩之樂，賜我樂意的靈扶持我，","notes":[]},{"n":13,"t":"我就把你的道指教有過犯的人，罪人必歸順你。","notes":[]},{"n":14,"t":"神啊，你是拯救我的神；求你救我脫離流人血的罪！我的舌頭就高聲歌唱你的公義。","notes":[]},{"n":15,"t":"主啊，求你使我嘴唇張開，我的口便傳揚讚美你的話！","notes":[]},{"n":16,"t":"你本不喜愛祭物，若喜愛，我就獻上；燔祭，你也不喜悅。","notes":[]},{"n":17,"t":"神所要的祭就是憂傷的靈；神啊，憂傷痛悔的心，你必不輕看。","notes":[]},{"n":18,"t":"求你隨你的美意善待錫安，建造耶路撒冷的城牆。","notes":[]},{"n":19,"t":"那時，你必喜愛公義的祭和燔祭並全牲的燔祭；那時，人必將公牛獻在你壇上。","notes":[]}]},"52":{"heading":"神的審判和恩惠","verses":[{"n":1,"t":"勇士啊，你為何以作惡自誇？神的慈愛是常存的。","notes":[]},{"n":2,"t":"你的舌頭邪惡詭詐，好像剃頭刀，快利傷人。","notes":[]},{"n":3,"t":"你愛惡勝似愛善，又愛說謊，不愛說公義。（細拉）","notes":[]},{"n":4,"t":"詭詐的舌頭啊，你愛說一切毀滅的話！","notes":[]},{"n":5,"t":"神也要毀滅你，直到永遠；他要把你拿去，從你的帳棚中抽出，從活人之地將你拔出。（細拉）","notes":[]},{"n":6,"t":"義人要看見而懼怕，並要笑他，","notes":[]},{"n":7,"t":"說：看哪，這就是那不以神為他力量的人，只倚仗他豐富的財物，在邪惡上堅立自己。","notes":[]},{"n":8,"t":"至於我，就像神殿中的青橄欖樹；我永永遠遠倚靠神的慈愛。","notes":[]},{"n":9,"t":"我要稱謝你，直到永遠，因為你行了這事。我也要在你聖民面前仰望你的名；這名本為美好。","notes":[]}]},"53":{"heading":"人的邪惡","verses":[{"n":1,"t":"愚頑人心裏說：沒有神。他們都是邪惡，行了可憎惡的罪孽；沒有一個人行善。","notes":[]},{"n":2,"t":"神從天上垂看世人，要看有明白的沒有？有尋求他的沒有？","notes":[]},{"n":3,"t":"他們各人都退後，一同變為污穢；並沒有行善的，連一個也沒有。","notes":[]},{"n":4,"t":"作孽的沒有知識嗎？他們吞吃我的百姓如同吃飯一樣，並不求告神。","notes":[]},{"n":5,"t":"他們在無可懼怕之處就大大害怕，因為神把那安營攻擊你之人的骨頭散開了。你使他們蒙羞，因為神棄絕了他們。","notes":[]},{"n":6,"t":"但願以色列的救恩從錫安而出。神救回他被擄的子民那時，雅各要快樂，以色列要歡喜。","notes":[]}]},"54":{"heading":"遭敵迫害求主保護","verses":[{"n":1,"t":"神啊，求你以你的名救我，憑你的大能為我伸冤。","notes":[]},{"n":2,"t":"神啊，求你聽我的禱告，留心聽我口中的言語。","notes":[]},{"n":3,"t":"因為，外人起來攻擊我，強暴人尋索我的命；他們眼中沒有神。（細拉）","notes":[]},{"n":4,"t":"神是幫助我的，是扶持我命的。","notes":[]},{"n":5,"t":"他要報應我仇敵所行的惡；求你憑你的誠實滅絕他們。","notes":[]},{"n":6,"t":"我要把甘心祭獻給你。耶和華啊，我要稱讚你的名；這名本為美好。","notes":[]},{"n":7,"t":"他從一切的急難中把我救出來；我的眼睛也看見了我仇敵遭報。","notes":[]}]},"55":{"heading":"被友出賣者的禱告","verses":[{"n":1,"t":"神啊，求你留心聽我的禱告，不要隱藏不聽我的懇求！","notes":[]},{"n":2,"t":"求你側耳聽我，應允我。我哀歎不安，發聲唉哼，","notes":[]},{"n":3,"t":"都因仇敵的聲音，惡人的欺壓；因為他們將罪孽加在我身上，發怒氣逼迫我。","notes":[]},{"n":4,"t":"我心在我裏面甚是疼痛；死的驚惶臨到我身。","notes":[]},{"n":5,"t":"恐懼戰兢歸到我身；驚恐漫過了我。","notes":[]},{"n":6,"t":"我說：但願我有翅膀像鴿子，我就飛去，得享安息。","notes":[]},{"n":7,"t":"我必遠遊，宿在曠野。（細拉）","notes":[]},{"n":8,"t":"我必速速逃到避所，脫離狂風暴雨。","notes":[]},{"n":9,"t":"主啊，求你吞滅他們，變亂他們的舌頭！因為我在城中見了強暴爭競的事。","notes":[]},{"n":10,"t":"他們在城牆上晝夜繞行；在城內也有罪孽和奸惡。","notes":[]},{"n":11,"t":"邪惡在其中；欺壓和詭詐不離街市。","notes":[]},{"n":12,"t":"原來不是仇敵辱罵我，若是仇敵，還可忍耐；也不是恨我的人向我狂大，若是恨我的人就必躲避他。","notes":[]},{"n":13,"t":"不料是你；你原與我平等，是我的同伴，是我知己的朋友！","notes":[]},{"n":14,"t":"我們素常彼此談論，以為甘甜；我們與群眾在神的殿中同行。","notes":[]},{"n":15,"t":"願死亡忽然臨到他們！願他們活活地下入陰間！因為他們的住處，他們的心中，都是邪惡。","notes":[]},{"n":16,"t":"至於我，我要求告神；耶和華必拯救我。","notes":[]},{"n":17,"t":"我要晚上、早晨、晌午哀聲悲歎；他也必聽我的聲音。","notes":[]},{"n":18,"t":"他救贖我命脫離攻擊我的人，使我得享平安，因為與我相爭的人甚多。","notes":[]},{"n":19,"t":"那沒有更變、不敬畏神的人，從太古常存的神必聽見而苦待他。","notes":[]},{"n":20,"t":"他背了約，伸手攻擊與他和好的人。","notes":[]},{"n":21,"t":"他的口如奶油光滑，他的心卻懷著爭戰；他的話比油柔和，其實是拔出來的刀。","notes":[]},{"n":22,"t":"你要把你的重擔卸給耶和華，他必撫養你；他永不叫義人動搖。","notes":[]},{"n":23,"t":"神啊，你必使惡人下入滅亡的坑；流人血、行詭詐的人必活不到半世，但我要倚靠你。","notes":[]}]},"56":{"heading":"信靠神的祈禱","verses":[{"n":1,"t":"神啊，求你憐憫我，因為人要把我吞了，終日攻擊欺壓我。","notes":[]},{"n":2,"t":"我的仇敵終日要把我吞了，因逞驕傲攻擊我的人甚多。","notes":[]},{"n":3,"t":"我懼怕的時候要倚靠你。","notes":[]},{"n":4,"t":"我倚靠神，我要讚美他的話；我倚靠神，必不懼怕。血氣之輩能把我怎麼樣呢？","notes":[]},{"n":5,"t":"他們終日顛倒我的話；他們一切的心思都是要害我。","notes":[]},{"n":6,"t":"他們聚集，埋伏窺探我的腳蹤，等候要害我的命。","notes":[]},{"n":7,"t":"他們豈能因罪孽逃脫嗎？神啊，求你在怒中使眾民墮落！","notes":[]},{"n":8,"t":"我幾次流離，你都記數；求你把我眼淚裝在你的皮袋裏。這不都記在你冊子上嗎？","notes":[]},{"n":9,"t":"我呼求的日子，我的仇敵都要轉身退後。神幫助我，這是我所知道的。","notes":[]},{"n":10,"t":"我倚靠神，我要讚美他的話；我倚靠耶和華，我要讚美他的話。","notes":[]},{"n":11,"t":"我倚靠神，必不懼怕。人能把我怎麼樣呢？","notes":[]},{"n":12,"t":"神啊，我向你所許的願在我身上；我要將感謝祭獻給你。","notes":[]},{"n":13,"t":"因為你救我的命脫離死亡。你豈不是救護我的腳不跌倒、使我在生命光中行在神面前嗎？","notes":[]}]},"57":{"heading":"求主施援","verses":[{"n":1,"t":"神啊，求你憐憫我，憐憫我！因為我的心投靠你。我要投靠在你翅膀的蔭下，等到災害過去。","notes":[]},{"n":2,"t":"我要求告至高的神，就是為我成全諸事的神。","notes":[]},{"n":3,"t":"那要吞我的人辱罵我的時候，神從天上必施恩救我，也必向我發出慈愛和誠實。","notes":[]},{"n":4,"t":"我的性命在獅子中間；我躺臥在性如烈火的世人當中。他們的牙齒是槍、箭；他們的舌頭是快刀。","notes":[]},{"n":5,"t":"神啊，願你崇高過於諸天！願你的榮耀高過全地！","notes":[]},{"n":6,"t":"他們為我的腳設下網羅，壓制我的心；他們在我面前挖了坑，自己反掉在其中。（細拉）","notes":[]},{"n":7,"t":"神啊，我心堅定，我心堅定；我要唱詩，我要歌頌！","notes":[]},{"n":8,"t":"我的靈啊，你當醒起！琴瑟啊，你們當醒起！我自己要極早醒起！","notes":["原文是榮耀"]},{"n":9,"t":"主啊，我要在萬民中稱謝你，在列邦中歌頌你！","notes":[]},{"n":10,"t":"因為，你的慈愛高及諸天；你的誠實達到穹蒼。","notes":[]},{"n":11,"t":"神啊，願你崇高過於諸天！願你的榮耀高過全地！","notes":[]}]},"58":{"heading":"求神罰惡","verses":[{"n":1,"t":"世人哪，你們默然不語，真合公義嗎？施行審判，豈按正直嗎？","notes":[]},{"n":2,"t":"不然！你們是心中作惡；你們在地上秤出你們手所行的強暴。","notes":[]},{"n":3,"t":"惡人一出母胎就與神疏遠，一離母腹便走錯路，說謊話。","notes":[]},{"n":4,"t":"他們的毒氣好像蛇的毒氣；他們好像塞耳的聾虺，","notes":[]},{"n":5,"t":"不聽行法術的聲音，雖用極靈的咒語也是不聽。","notes":[]},{"n":6,"t":"神啊，求你敲碎他們口中的牙！耶和華啊，求你敲掉少壯獅子的大牙！","notes":[]},{"n":7,"t":"願他們消滅，如急流的水一般；他們瞅準射箭的時候，願箭頭彷彿砍斷。","notes":[]},{"n":8,"t":"願他們像蝸牛消化過去，又像婦人墜落未見天日的胎。","notes":[]},{"n":9,"t":"你們用荊棘燒火，鍋還未熱，他要用旋風把青的和燒著的一齊颳去。","notes":[]},{"n":10,"t":"義人見仇敵遭報就歡喜，要在惡人的血中洗腳。","notes":[]},{"n":11,"t":"因此，人必說：義人誠然有善報；在地上果有施行判斷的神！","notes":[]}]},"59":{"heading":"為安全求主施助","verses":[{"n":1,"t":"我的神啊，求你救我脫離仇敵，把我安置在高處，得脫那些起來攻擊我的人。","notes":[]},{"n":2,"t":"求你救我脫離作孽的人和喜愛流人血的人！","notes":[]},{"n":3,"t":"因為，他們埋伏要害我的命；有能力的人聚集來攻擊我。耶和華啊，這不是為我的過犯，也不是為我的罪愆。","notes":[]},{"n":4,"t":"我雖然無過，他們預備整齊，跑來攻擊我。求你興起鑒察，幫助我！","notes":[]},{"n":5,"t":"萬軍之神－耶和華以色列的神啊！求你興起，懲治萬邦！不要憐憫行詭詐的惡人！（細拉）","notes":[]},{"n":6,"t":"他們晚上轉回，叫號如狗，圍城繞行。","notes":[]},{"n":7,"t":"他們口中噴吐惡言，嘴裏有刀；他們說：有誰聽見？","notes":[]},{"n":8,"t":"但你－耶和華必笑話他們；你要嗤笑萬邦。","notes":[]},{"n":9,"t":"我的力量啊，我必仰望你，因為神是我的高臺。","notes":[]},{"n":10,"t":"我的神要以慈愛迎接我；神要叫我看見我仇敵遭報。","notes":[]},{"n":11,"t":"不要殺他們，恐怕我的民忘記。主啊，你是我們的盾牌；求你用你的能力使他們四散，且降為卑。","notes":[]},{"n":12,"t":"因他們口中的罪和嘴裏的言語，並咒罵虛謊的話，願他們在驕傲之中被纏住了。","notes":[]},{"n":13,"t":"求你發怒，使他們消滅，以致歸於無有，叫他們知道神在雅各中間掌權，直到地極。（細拉）","notes":[]},{"n":14,"t":"到了晚上，任憑他們轉回；任憑他們叫號如狗，圍城繞行。","notes":[]},{"n":15,"t":"他們必走來走去，尋找食物，若不得飽就終夜在外。","notes":[]},{"n":16,"t":"但我要歌頌你的力量，早晨要高唱你的慈愛；因為你作過我的高臺，在我急難的日子作過我的避難所。","notes":[]},{"n":17,"t":"我的力量啊，我要歌頌你；因為神是我的高臺，是賜恩與我的神。","notes":[]}]},"60":{"heading":"求主解救","verses":[{"n":1,"t":"神啊，你丟棄了我們，使我們破敗；你向我們發怒，求你使我們復興！","notes":[]},{"n":2,"t":"你使地震動，而且崩裂；求你將裂口醫好，因為地搖動。","notes":[]},{"n":3,"t":"你叫你的民遇見艱難；你叫我們喝那使人東倒西歪的酒。","notes":[]},{"n":4,"t":"你把旌旗賜給敬畏你的人，可以為真理揚起來。（細拉）","notes":[]},{"n":5,"t":"求你應允我們，用右手拯救我們，好叫你所親愛的人得救。","notes":[]},{"n":6,"t":"神已經指著他的聖潔說：我要歡樂；我要分開示劍，丈量疏割谷。","notes":["說：或譯應許我"]},{"n":7,"t":"基列是我的，瑪拿西也是我的。以法蓮是護衛我頭的；猶大是我的杖。","notes":[]},{"n":8,"t":"摩押是我的沐浴盆；我要向以東拋鞋。非利士啊，你還能因我歡呼嗎？","notes":[]},{"n":9,"t":"誰能領我進堅固城？誰能引我到以東地？","notes":[]},{"n":10,"t":"神啊，你不是丟棄了我們嗎？神啊，你不和我們的軍兵同去嗎？","notes":[]},{"n":11,"t":"求你幫助我們攻擊敵人，因為人的幫助是枉然的。","notes":[]},{"n":12,"t":"我們倚靠神才得施展大能，因為踐踏我們敵人的就是他。","notes":[]}]},"61":{"heading":"求主保佑","verses":[{"n":1,"t":"神啊，求你聽我的呼求，側耳聽我的禱告！","notes":[]},{"n":2,"t":"我心裏發昏的時候，我要從地極求告你。求你領我到那比我更高的磐石！","notes":[]},{"n":3,"t":"因為你作過我的避難所，作過我的堅固臺，脫離仇敵。","notes":[]},{"n":4,"t":"我要永遠住在你的帳幕裏！我要投靠在你翅膀下的隱密處！（細拉）","notes":[]},{"n":5,"t":"神啊，你原是聽了我所許的願；你將產業賜給敬畏你名的人。","notes":[]},{"n":6,"t":"你要加添王的壽數；他的年歲必存到世世。","notes":[]},{"n":7,"t":"他必永遠坐在神面前；願你預備慈愛和誠實保佑他！","notes":[]},{"n":8,"t":"這樣，我要歌頌你的名，直到永遠，好天天還我所許的願。","notes":[]}]},"62":{"heading":"在神保佑中安穩自在","verses":[{"n":1,"t":"我的心默默無聲，專等候神；我的救恩是從他而來。","notes":[]},{"n":2,"t":"惟獨他是我的磐石，我的拯救；他是我的高臺，我必不很動搖。","notes":[]},{"n":3,"t":"你們大家攻擊一人，把他毀壞，如同毀壞歪斜的牆、將倒的壁，要到幾時呢？","notes":[]},{"n":4,"t":"他們彼此商議，專要從他的尊位上把他推下；他們喜愛謊話，口雖祝福，心卻咒詛。（細拉）","notes":[]},{"n":5,"t":"我的心哪，你當默默無聲，專等候神，因為我的盼望是從他而來。","notes":[]},{"n":6,"t":"惟獨他是我的磐石，我的拯救；他是我的高臺，我必不動搖。","notes":[]},{"n":7,"t":"我的拯救、我的榮耀都在乎神；我力量的磐石、我的避難所都在乎神。","notes":[]},{"n":8,"t":"你們眾民當時時倚靠他，在他面前傾心吐意；神是我們的避難所。（細拉）","notes":[]},{"n":9,"t":"下流人真是虛空；上流人也是虛假；放在天平裏就必浮起；他們一共比空氣還輕。","notes":[]},{"n":10,"t":"不要仗勢欺人，也不要因搶奪而驕傲；若財寶加增，不要放在心上。","notes":[]},{"n":11,"t":"神說了一次、兩次，我都聽見：就是能力都屬乎神。","notes":[]},{"n":12,"t":"主啊，慈愛也是屬乎你，因為你照著各人所行的報應他。","notes":[]}]},"63":{"heading":"渴慕神","verses":[{"n":1,"t":"神啊，你是我的神，我要切切地尋求你，在乾旱疲乏無水之地，我渴想你；我的心切慕你。","notes":[]},{"n":2,"t":"我在聖所中曾如此瞻仰你，為要見你的能力和你的榮耀。","notes":[]},{"n":3,"t":"因你的慈愛比生命更好，我的嘴唇要頌讚你。","notes":[]},{"n":4,"t":"我還活的時候要這樣稱頌你；我要奉你的名舉手。","notes":[]},{"n":5,"t":"我在床上記念你，在夜更的時候思想你；我的心就像飽足了骨髓肥油，我也要以歡樂的嘴唇讚美你。","notes":[],"end":6},{"n":7,"t":"因為你曾幫助我，我就在你翅膀的蔭下歡呼。","notes":[]},{"n":8,"t":"我心緊緊地跟隨你；你的右手扶持我。","notes":[]},{"n":9,"t":"但那些尋索要滅我命的人必往地底下去；","notes":[]},{"n":10,"t":"他們必被刀劍所殺，被野狗所吃。","notes":[]},{"n":11,"t":"但是王必因神歡喜。凡指著他發誓的必要誇口，因為說謊之人的口必被塞住。","notes":[]}]},"64":{"heading":"求主保護","verses":[{"n":1,"t":"神啊，我哀歎的時候，求你聽我的聲音！求你保護我的性命，不受仇敵的驚恐！","notes":[]},{"n":2,"t":"求你把我隱藏，使我脫離作惡之人的暗謀和作孽之人的擾亂。","notes":[]},{"n":3,"t":"他們磨舌如刀，發出苦毒的言語，好像比準了的箭，","notes":[]},{"n":4,"t":"要在暗地射完全人；他們忽然射他，並不懼怕。","notes":[]},{"n":5,"t":"他們彼此勉勵設下惡計；他們商量暗設網羅，說：誰能看見？","notes":[]},{"n":6,"t":"他們圖謀奸惡，說：我們是極力圖謀的。他們各人的意念心思是深的。","notes":[]},{"n":7,"t":"但神要射他們；他們忽然被箭射傷。","notes":[]},{"n":8,"t":"他們必然絆跌，被自己的舌頭所害；凡看見他們的必都搖頭。","notes":[]},{"n":9,"t":"眾人都要害怕，要傳揚神的工作，並且明白他的作為。","notes":[]},{"n":10,"t":"義人必因耶和華歡喜， 並要投靠他；凡心裏正直的人都要誇口。","notes":[]}]},"65":{"heading":"頌讚主恩","verses":[{"n":1,"t":"神啊，錫安的人都等候讚美你；所許的願也要向你償還。","notes":[]},{"n":2,"t":"聽禱告的主啊，凡有血氣的都要來就你。","notes":[]},{"n":3,"t":"罪孽勝了我；至於我們的過犯，你都要赦免。","notes":[]},{"n":4,"t":"你所揀選、使他親近你、住在你院中的，這人便為有福！我們必因你居所、你聖殿的美福知足了。","notes":[]},{"n":5,"t":"拯救我們的神啊，你必以威嚴秉公義應允我們；你本是一切地極和海上遠處的人所倚靠的。","notes":[]},{"n":6,"t":"他既以大能束腰，就用力量安定諸山，","notes":[]},{"n":7,"t":"使諸海的響聲和其中波浪的響聲，並萬民的喧嘩，都平靜了。","notes":[]},{"n":8,"t":"住在地極的人因你的神蹟懼怕；你使日出日落之地都歡呼。","notes":[]},{"n":9,"t":"你眷顧地，降下透雨，使地大得肥美。神的河滿了水；你這樣澆灌了地，好為人預備五穀。","notes":[]},{"n":10,"t":"你澆透地的犂溝，潤平犂脊，降甘霖，使地軟和；其中發長的，蒙你賜福。","notes":[]},{"n":11,"t":"你以恩典為年歲的冠冕；你的路徑都滴下脂油，","notes":[]},{"n":12,"t":"滴在曠野的草場上。小山以歡樂束腰；","notes":[]},{"n":13,"t":"草場以羊群為衣；谷中也長滿了五穀。這一切都歡呼歌唱。","notes":[]}]},"66":{"heading":"頌讚感恩的詩","verses":[{"n":1,"t":"全地都當向神歡呼！","notes":[]},{"n":2,"t":"歌頌他名的榮耀！用讚美的言語將他的榮耀發明！","notes":[]},{"n":3,"t":"當對神說：你的作為何等可畏！因你的大能，仇敵要投降你。","notes":[]},{"n":4,"t":"全地要敬拜你，歌頌你，要歌頌你的名。（細拉）","notes":[]},{"n":5,"t":"你們來看神所行的，他向世人所做之事是可畏的。","notes":[]},{"n":6,"t":"他將海變成乾地，眾民步行過河；我們在那裏因他歡喜。","notes":[]},{"n":7,"t":"他用權能治理萬民，直到永遠。他的眼睛鑒察列邦；悖逆的人不可自高。（細拉）","notes":[]},{"n":8,"t":"萬民哪，你們當稱頌我們的神，使人得聽讚美他的聲音。","notes":[]},{"n":9,"t":"他使我們的性命存活，也不叫我們的腳搖動。","notes":[]},{"n":10,"t":"神啊，你曾試驗我們，熬煉我們，如熬煉銀子一樣。","notes":[]},{"n":11,"t":"你使我們進入網羅，把重擔放在我們的身上。","notes":[]},{"n":12,"t":"你使人坐車軋我們的頭；我們經過水火，你卻使我們到豐富之地。","notes":[]},{"n":13,"t":"我要用燔祭進你的殿，向你還我的願，","notes":[]},{"n":14,"t":"就是在急難時我嘴唇所發的、口中所許的。","notes":[]},{"n":15,"t":"我要把肥牛作燔祭，將公羊的香祭獻給你，又把公牛和山羊獻上。（細拉）","notes":[]},{"n":16,"t":"凡敬畏神的人，你們都來聽！我要述說他為我所行的事。","notes":[]},{"n":17,"t":"我曾用口求告他；我的舌頭也稱他為高。","notes":[]},{"n":18,"t":"我若心裏注重罪孽，主必不聽。","notes":[]},{"n":19,"t":"但神實在聽見了；他側耳聽了我禱告的聲音。","notes":[]},{"n":20,"t":"神是應當稱頌的！他並沒有推卻我的禱告，也沒有叫他的慈愛離開我。","notes":[]}]},"67":{"heading":"感恩的詩","verses":[{"n":1,"t":"願神憐憫我們，賜福與我們，用臉光照我們，（細拉）","notes":[]},{"n":2,"t":"好叫世界得知你的道路，萬國得知你的救恩。","notes":[]},{"n":3,"t":"神啊，願列邦稱讚你！願萬民都稱讚你！","notes":[]},{"n":4,"t":"願萬國都快樂歡呼；因為你必按公正審判萬民，引導世上的萬國。（細拉）","notes":[]},{"n":5,"t":"神啊，願列邦稱讚你！願萬民都稱讚你！","notes":[]},{"n":6,"t":"地已經出了土產；神－就是我們的神要賜福與我們。","notes":[]},{"n":7,"t":"神要賜福與我們；地的四極都要敬畏他！","notes":[]}]},"68":{"heading":"勝利之歌","verses":[{"n":1,"t":"願神興起，使他的仇敵四散，叫那恨他的人從他面前逃跑。","notes":[]},{"n":2,"t":"他們被驅逐，如煙被風吹散；惡人見神之面而消滅，如蠟被火鎔化。","notes":[]},{"n":3,"t":"惟有義人必然歡喜，在神面前高興快樂。","notes":[]},{"n":4,"t":"你們當向神唱詩，歌頌他的名；為那坐車行過曠野的修平大路。他的名是耶和華，要在他面前歡樂！","notes":[]},{"n":5,"t":"神在他的聖所作孤兒的父，作寡婦的伸冤者。","notes":[]},{"n":6,"t":"神叫孤獨的有家，使被囚的出來享福；惟有悖逆的住在乾燥之地。","notes":[]},{"n":7,"t":"神啊，你曾在你百姓前頭出來，在曠野行走。（細拉）","notes":[]},{"n":8,"t":"那時，地見神的面而震動，天也落雨；西奈山見以色列神的面也震動。","notes":[]},{"n":9,"t":"神啊，你降下大雨；你產業以色列疲乏的時候，你使他堅固。","notes":[]},{"n":10,"t":"你的會眾住在其中；神啊，你的恩惠是為困苦人預備的。","notes":[]},{"n":11,"t":"主發命令，傳好信息的婦女成了大群。","notes":[]},{"n":12,"t":"統兵的君王逃跑了，逃跑了；在家等候的婦女分受所奪的。","notes":[]},{"n":13,"t":"你們安臥在羊圈的時候，好像鴿子的翅膀鍍白銀，翎毛鍍黃金一般。","notes":[]},{"n":14,"t":"全能者在境內趕散列王的時候，勢如飄雪在撒們。","notes":[]},{"n":15,"t":"巴珊山是神的山；巴珊山是多峰多嶺的山。","notes":[]},{"n":16,"t":"你們多峰多嶺的山哪，為何斜看神所願居住的山？耶和華必住這山，直到永遠！","notes":[]},{"n":17,"t":"神的車輦累萬盈千；主在其中，好像在西奈聖山一樣。","notes":[]},{"n":18,"t":"你已經升上高天，擄掠仇敵；你在人間，就是在悖逆的人間，受了供獻，叫耶和華神可以與他們同住。","notes":[]},{"n":19,"t":"天天背負我們重擔的主，就是拯救我們的神，是應當稱頌的！（細拉）","notes":[]},{"n":20,"t":"神是為我們施行諸般救恩的神；人能脫離死亡是在乎主耶和華。","notes":[]},{"n":21,"t":"但神要打破他仇敵的頭，就是那常犯罪之人的髮頂。","notes":[]},{"n":22,"t":"主說：我要使眾民從巴珊而歸，使他們從深海而回，","notes":[]},{"n":23,"t":"使你打碎仇敵，你的腳踹在血中，使你狗的舌頭從其中得分。","notes":[]},{"n":24,"t":"神啊，你是我的神，我的王；人已經看見你行走，進入聖所。","notes":[]},{"n":25,"t":"歌唱的行在前，作樂的隨在後，都在擊鼓的童女中間。","notes":[]},{"n":26,"t":"從以色列源頭而來的，當在各會中稱頌主神！","notes":[]},{"n":27,"t":"在那裏，有統管他們的小便雅憫，有猶大的首領和他們的群眾，有西布倫的首領，有拿弗他利的首領。","notes":[]},{"n":28,"t":"以色列的能力是神所賜的；神啊，求你堅固你為我們所成全的事！","notes":[]},{"n":29,"t":"因你耶路撒冷的殿，列王必帶貢物獻給你。","notes":[]},{"n":30,"t":"求你叱喝蘆葦中的野獸和群公牛，並列邦中的牛犢。把銀塊踹在腳下；神已經趕散好爭戰的列邦。","notes":[]},{"n":31,"t":"埃及的公侯要出來朝見神；古實人要急忙舉手 禱告。","notes":[]},{"n":32,"t":"世上的列國啊，你們要向神歌唱；願你們歌頌主！","notes":[]},{"n":33,"t":"歌頌那自古駕行在諸天以上的主！他發出聲音，是極大的聲音。","notes":[]},{"n":34,"t":"你們要將能力歸給神。他的威榮在以色列之上；他的能力是在穹蒼。","notes":[]},{"n":35,"t":"神啊，你從聖所顯為可畏；以色列的神是那將力量權能賜給他百姓的。神是應當稱頌的！","notes":[]}]},"69":{"heading":"求助的禱告","verses":[{"n":1,"t":"神啊，求你救我！因為眾水要淹沒我。","notes":[]},{"n":2,"t":"我陷在深淤泥中，沒有立腳之地；我到了深水中，大水漫過我身。","notes":[]},{"n":3,"t":"我因呼求困乏，喉嚨發乾；我因等候神，眼睛失明。","notes":[]},{"n":4,"t":"無故恨我的，比我頭髮還多；無理與我為仇、要把我剪除的，甚為強盛。我沒有搶奪的，要叫我償還。","notes":[]},{"n":5,"t":"神啊，我的愚昧，你原知道；我的罪愆不能隱瞞。","notes":[]},{"n":6,"t":"萬軍的主－耶和華啊，求你叫那等候你的，不要因我蒙羞！以色列的神啊，求你叫那尋求你的，不要因我受辱！","notes":[]},{"n":7,"t":"因我為你的緣故受了辱罵，滿面羞愧。","notes":[]},{"n":8,"t":"我的弟兄看我為外路人；我的同胞看我為外邦人。","notes":[]},{"n":9,"t":"因我為你的殿心裏焦急，如同火燒，並且辱罵你人的辱罵都落在我身上。","notes":[]},{"n":10,"t":"我哭泣，以禁食刻苦我心；這倒算為我的羞辱。","notes":[]},{"n":11,"t":"我拿麻布當衣裳，就成了他們的笑談。","notes":[]},{"n":12,"t":"坐在城門口的談論我；酒徒也以我為歌曲。","notes":[]},{"n":13,"t":"但我在悅納的時候向你－耶和華祈禱。神啊，求你按你豐盛的慈愛，憑你拯救的誠實應允我！","notes":[]},{"n":14,"t":"求你搭救我出離淤泥，不叫我陷在其中；求你使我脫離那些恨我的人，使我出離深水。","notes":[]},{"n":15,"t":"求你不容大水漫過我，不容深淵吞滅我，不容坑坎在我以上合口。","notes":[]},{"n":16,"t":"耶和華啊，求你應允我！因為你的慈愛本為美好；求你按你豐盛的慈悲回轉眷顧我！","notes":[]},{"n":17,"t":"不要掩面不顧你的僕人；我是在急難之中，求你速速地應允我！","notes":[]},{"n":18,"t":"求你親近我，救贖我！求你因我的仇敵把我贖回！","notes":[]},{"n":19,"t":"你知道我受的辱罵、欺凌、羞辱；我的敵人都在你面前。","notes":[]},{"n":20,"t":"辱罵傷破了我的心，我又滿了憂愁。我指望有人體恤，卻沒有一個；我指望有人安慰，卻找不著一個。","notes":[]},{"n":21,"t":"他們拿苦膽給我當食物；我渴了，他們拿醋給我喝。","notes":[]},{"n":22,"t":"願他們的筵席在他們面前變為網羅，在他們平安的時候變為機檻。","notes":[]},{"n":23,"t":"願他們的眼睛昏矇，不得看見；願你使他們的腰常常戰抖。","notes":[]},{"n":24,"t":"求你將你的惱恨倒在他們身上，叫你的烈怒追上他們。","notes":[]},{"n":25,"t":"願他們的住處變為荒場；願他們的帳棚無人居住。","notes":[]},{"n":26,"t":"因為，你所擊打的，他們就逼迫；你所擊傷的，他們戲說他的愁苦。","notes":[]},{"n":27,"t":"願你在他們的罪上加罪，不容他們在你面前稱義。","notes":[]},{"n":28,"t":"願他們從生命冊上被塗抹，不得記錄在義人之中。","notes":[]},{"n":29,"t":"但我是困苦憂傷的；神啊，願你的救恩將我安置在高處。","notes":[]},{"n":30,"t":"我要以詩歌讚美神的名，以感謝稱他為大！","notes":[]},{"n":31,"t":"這便叫耶和華喜悅，勝似獻牛，或是獻有角有蹄的公牛。","notes":[]},{"n":32,"t":"謙卑的人看見了就喜樂；尋求神的人，願你們的心甦醒。","notes":[]},{"n":33,"t":"因為耶和華聽了窮乏人，不藐視被囚的人。","notes":[]},{"n":34,"t":"願天和地、洋海和其中一切的動物都讚美他！","notes":[]},{"n":35,"t":"因為神要拯救錫安，建造猶大的城邑；他的民要在那裏居住，得以為業。","notes":[]},{"n":36,"t":"他僕人的後裔要承受為業；愛他名的人也要住在其中。","notes":[]}]},"70":{"heading":"求助的祈禱","verses":[{"n":1,"t":"神啊，求你快快搭救我！耶和華啊，求你速速幫助我！","notes":[]},{"n":2,"t":"願那些尋索我命的，抱愧蒙羞；願那些喜悅我遭害的，退後受辱。","notes":[]},{"n":3,"t":"願那些對我說阿哈、阿哈的，因羞愧退後。","notes":[]},{"n":4,"t":"願一切尋求你的，因你高興歡喜；願那些喜愛你救恩的，常說：當尊神為大！","notes":[]},{"n":5,"t":"但我是困苦窮乏的；神啊，求你速速到我這裏來！你是幫助我的，搭救我的。耶和華啊，求你不要耽延！","notes":[]}]},"71":{"heading":"老年人的祈禱","verses":[{"n":1,"t":"耶和華啊，我投靠你；求你叫我永不羞愧！","notes":[]},{"n":2,"t":"求你憑你的公義搭救我，救拔我；側耳聽我，拯救我！","notes":[]},{"n":3,"t":"求你作我常住的磐石；你已經命定要救我，因為你是我的巖石，我的山寨。","notes":[]},{"n":4,"t":"我的神啊，求你救我脫離惡人的手，脫離不義和殘暴之人的手。","notes":[]},{"n":5,"t":"主－耶和華啊，你是我所盼望的；從我年幼，你是我所倚靠的。","notes":[]},{"n":6,"t":"我從出母胎被你扶持；使我出母腹的是你。我必常常讚美你！","notes":[]},{"n":7,"t":"許多人以我為怪，但你是我堅固的避難所。","notes":[]},{"n":8,"t":"你的讚美，你的榮耀終日必滿了我的口。","notes":[]},{"n":9,"t":"我年老的時候，求你不要丟棄我！我力氣衰弱的時候，求你不要離棄我！","notes":[]},{"n":10,"t":"我的仇敵議論我；那些窺探要害我命的彼此商議，","notes":[]},{"n":11,"t":"說：神已經離棄他；我們追趕他，捉拿他吧！因為沒有人搭救。","notes":[]},{"n":12,"t":"神啊，求你不要遠離我！我的神啊，求你速速幫助我！","notes":[]},{"n":13,"t":"願那與我性命為敵的，羞愧被滅；願那謀害我的，受辱蒙羞。","notes":[]},{"n":14,"t":"我卻要常常盼望，並要越發讚美你。","notes":[]},{"n":15,"t":"我的口終日要述說你的公義和你的救恩，因我不計其數。","notes":[]},{"n":16,"t":"我要來說主－耶和華大能的事；我單要提說你的公義。","notes":[]},{"n":17,"t":"神啊，自我年幼時，你就教訓我；直到如今，我傳揚你奇妙的作為。","notes":[]},{"n":18,"t":"神啊，我到年老髮白的時候，求你不要離棄我！等我將你的能力指示下代，將你的大能指示後世的人。","notes":[]},{"n":19,"t":"神啊，你的公義甚高；行過大事的神啊，誰能像你！","notes":[]},{"n":20,"t":"你是叫我們多經歷重大急難的，必使我們復活，從地的深處救上來。","notes":[]},{"n":21,"t":"求你使我越發昌大，又轉來安慰我。","notes":[]},{"n":22,"t":"我的神啊，我要鼓瑟稱讚你，稱讚你的誠實！以色列的聖者啊，我要彈琴歌頌你！","notes":[]},{"n":23,"t":"我歌頌你的時候，我的嘴唇和你所贖我的靈魂都必歡呼；","notes":[]},{"n":24,"t":"並且我的舌頭必終日講論你的公義，因為那些謀害我的人已經蒙羞受辱了。","notes":[]}]},"72":{"heading":"為王祈禱","verses":[{"n":1,"t":"神啊，求你將判斷的權柄賜給王，將公義賜給王的兒子。","notes":[]},{"n":2,"t":"他要按公義審判你的民，按公平審判你的困苦人。","notes":[]},{"n":3,"t":"大山小山都要因公義使民得享平安。","notes":[]},{"n":4,"t":"他必為民中的困苦人伸冤，拯救窮乏之輩，壓碎那欺壓人的。","notes":[]},{"n":5,"t":"太陽還存，月亮還在，人要敬畏你，直到萬代！","notes":[]},{"n":6,"t":"他必降臨，像雨降在已割的草地上，如甘霖滋潤田地。","notes":[]},{"n":7,"t":"在他的日子，義人要發旺，大有平安，好像月亮長存。","notes":[]},{"n":8,"t":"他要執掌權柄，從這海直到那海，從大河直到地極。","notes":[]},{"n":9,"t":"住在曠野的，必在他面前下拜；他的仇敵必要舔土。","notes":[]},{"n":10,"t":"他施和海島的王要進貢；示巴和西巴的王要獻禮物。","notes":[]},{"n":11,"t":"諸王都要叩拜他；萬國都要事奉他。","notes":[]},{"n":12,"t":"因為，窮乏人呼求的時候，他要搭救；沒有人幫助的困苦人，他也要搭救。","notes":[]},{"n":13,"t":"他要憐恤貧寒和窮乏的人，拯救窮苦人的性命。","notes":[]},{"n":14,"t":"他要救贖他們脫離欺壓和強暴；他們的血在他眼中看為寶貴。","notes":[]},{"n":15,"t":"他們要存活。示巴的金子要奉給他；人要常常為他禱告，終日稱頌他。","notes":[]},{"n":16,"t":"在地的山頂上，五穀必然茂盛；所結的穀實要響動，如黎巴嫩的樹林；城裏的人要發旺，如地上的草。","notes":["或譯：有一把五穀"]},{"n":17,"t":"他的名要存到永遠，要留傳如日之久。人要因他蒙福；萬國要稱他有福。","notes":[]},{"n":18,"t":"獨行奇事的耶和華－以色列的神是應當稱頌的！","notes":[]},{"n":19,"t":"他榮耀的名也當稱頌，直到永遠。願他的榮耀充滿全地！阿們！阿們！","notes":[]},{"n":20,"t":"耶西的兒子－大衛的祈禱完畢。","notes":[]}]},"73":{"heading":"神的公正","verses":[{"n":1,"t":"神實在恩待以色列那些清心的人！","notes":[]},{"n":2,"t":"至於我，我的腳幾乎失閃；我的腳險些滑跌。","notes":[]},{"n":3,"t":"我見惡人和狂傲人享平安就心懷不平。","notes":[]},{"n":4,"t":"他們死的時候沒有疼痛；他們的力氣卻也壯實。","notes":[]},{"n":5,"t":"他們不像別人受苦，也不像別人遭災。","notes":[]},{"n":6,"t":"所以，驕傲如鏈子戴在他們的項上；強暴像衣裳遮住他們的身體。","notes":[]},{"n":7,"t":"他們的眼睛因體胖而凸出；他們所得的，過於心裏所想的。","notes":[]},{"n":8,"t":"他們譏笑人，憑惡意說欺壓人的話；他們說話自高。","notes":[]},{"n":9,"t":"他們的口褻瀆上天；他們的舌毀謗全地。","notes":[]},{"n":10,"t":"所以神的民歸到這裏，喝盡了滿杯的苦水。","notes":[]},{"n":11,"t":"他們說：神怎能曉得？至高者豈有知識呢？","notes":[]},{"n":12,"t":"看哪，這就是惡人；他們既是常享安逸，財寶便加增。","notes":[]},{"n":13,"t":"我實在徒然潔淨了我的心，徒然洗手表明無辜。","notes":[]},{"n":14,"t":"因為，我終日遭災難；每早晨受懲治。","notes":[]},{"n":15,"t":"我若說，我要這樣講，這就是以奸詐待你的眾子。","notes":[]},{"n":16,"t":"我思索怎能明白這事，眼看實係為難，","notes":[]},{"n":17,"t":"等我進了神的聖所，思想他們的結局。","notes":[]},{"n":18,"t":"你實在把他們安在滑地，使他們掉在沉淪之中。","notes":[]},{"n":19,"t":"他們轉眼之間成了何等的荒涼！他們被驚恐滅盡了。","notes":[]},{"n":20,"t":"人睡醒了，怎樣看夢；主啊，你醒了也必照樣輕看他們的影像。","notes":[]},{"n":21,"t":"因而，我心裏發酸，肺腑被刺。","notes":[]},{"n":22,"t":"我這樣愚昧無知，在你面前如畜類一般。","notes":[]},{"n":23,"t":"然而，我常與你同在；你攙著我的右手。","notes":[]},{"n":24,"t":"你要以你的訓言引導我，以後必接我到榮耀裏。","notes":[]},{"n":25,"t":"除你以外，在天上我有誰呢？除你以外，在地上我也沒有所愛慕的。","notes":[]},{"n":26,"t":"我的肉體和我的心腸衰殘；但神是我心裏的力量，又是我的福分，直到永遠。","notes":[]},{"n":27,"t":"遠離你的，必要死亡；凡離棄你行邪淫的，你都滅絕了。","notes":[]},{"n":28,"t":"但我親近神是與我有益；我以主耶和華為我的避難所，好叫我述說你一切的作為。","notes":[]}]},"74":{"heading":"求主解救國家","verses":[{"n":1,"t":"神啊，你為何永遠丟棄我們呢？你為何向你草場的羊發怒，如煙冒出呢？","notes":[]},{"n":2,"t":"求你記念你古時所得來的會眾，就是你所贖、作你產業支派的，並記念你向來所居住的錫安山。","notes":[]},{"n":3,"t":"求你舉步去看那日久荒涼之地，仇敵在聖所中所行的一切惡事。","notes":[]},{"n":4,"t":"你的敵人在你會中吼叫；他們豎了自己的旗為記號。","notes":[]},{"n":5,"t":"他們好像人揚起斧子，砍伐林中的樹。","notes":[]},{"n":6,"t":"聖所中一切雕刻的，他們現在用斧子錘子打壞了。","notes":[]},{"n":7,"t":"他們用火焚燒你的聖所，褻瀆你名的居所，拆毀到地。","notes":[]},{"n":8,"t":"他們心裏說：我們要盡行毀滅；他們就在遍地把神的會所都燒毀了。","notes":[]},{"n":9,"t":"我們不見我們的標幟，不再有先知；我們內中也沒有人知道這災禍要到幾時呢！","notes":[]},{"n":10,"t":"神啊，敵人辱罵要到幾時呢？仇敵褻瀆你的名要到永遠嗎？","notes":[]},{"n":11,"t":"你為甚麼縮回你的右手？求你從懷中伸出來，毀滅他們。","notes":[]},{"n":12,"t":"神自古以來為我的王，在地上施行拯救。","notes":[]},{"n":13,"t":"你曾用能力將海分開，將水中大魚的頭打破。","notes":[]},{"n":14,"t":"你曾砸碎鱷魚的頭，把牠給曠野的禽獸為食物。","notes":["禽獸：原文是民"]},{"n":15,"t":"你曾分裂磐石，水便成了溪河；你使長流的江河乾了。","notes":[]},{"n":16,"t":"白晝屬你，黑夜也屬你；亮光和日頭是你所預備的。","notes":[]},{"n":17,"t":"地的一切疆界是你所立的；夏天和冬天是你所定的。","notes":[]},{"n":18,"t":"耶和華啊，仇敵辱罵，愚頑民褻瀆了你的名，求你記念這事。","notes":[]},{"n":19,"t":"不要將你斑鳩的性命交給野獸；不要永遠忘記你困苦人的性命。","notes":[]},{"n":20,"t":"求你顧念所立的約，因為地上黑暗之處都滿了強暴的居所。","notes":[]},{"n":21,"t":"不要叫受欺壓的人蒙羞回去；要叫困苦窮乏的人讚美你的名。","notes":[]},{"n":22,"t":"神啊，求你起來為自己伸訴！要記念愚頑人怎樣終日辱罵你。","notes":[]},{"n":23,"t":"不要忘記你敵人的聲音；那起來敵你之人的喧嘩時常上升。","notes":[]}]},"75":{"heading":"神是審判者","verses":[{"n":1,"t":"神啊，我們稱謝你，我們稱謝你！因為你的名相近，人都述說你奇妙的作為。","notes":[]},{"n":2,"t":"我到了所定的日期，必按正直施行審判。","notes":[]},{"n":3,"t":"地和其上的居民都消化了；我曾立了地的柱子。（細拉）","notes":[]},{"n":4,"t":"我對狂傲人說：不要行事狂傲！對凶惡人說：不要舉角！","notes":[]},{"n":5,"t":"不要把你們的角高舉；不要挺著頸項說話。","notes":[]},{"n":6,"t":"因為高舉非從東，非從西，也非從南而來。","notes":[]},{"n":7,"t":"惟有神斷定；他使這人降卑，使那人升高。","notes":[]},{"n":8,"t":"耶和華手裏有杯，其中的酒起沫，杯內滿了攙雜的酒；他倒出來，地上的惡人必都喝這酒的渣滓，而且喝盡。","notes":[]},{"n":9,"t":"但我要宣揚，直到永遠！我要歌頌雅各的神！","notes":[]},{"n":10,"t":"惡人一切的角，我要砍斷；惟有義人的角必被高舉。","notes":[]}]},"76":{"heading":"神是勝利者","verses":[{"n":1,"t":"在猶大，神為人所認識；在以色列，他的名為大。","notes":[]},{"n":2,"t":"在撒冷有他的帳幕；在錫安有他的居所。","notes":[]},{"n":3,"t":"他在那裏折斷弓上的火箭，並盾牌、刀劍，和爭戰的兵器。（細拉）","notes":[]},{"n":4,"t":"你從有野食之山而來，有光華和榮美。","notes":[]},{"n":5,"t":"心中勇敢的人都被搶奪；他們睡了長覺，沒有一個英雄能措手。","notes":[]},{"n":6,"t":"雅各的神啊，你的斥責一發，坐車的、騎馬的都沉睡了。","notes":[]},{"n":7,"t":"惟獨你是可畏的！你怒氣一發，誰能在你面前站得住呢？","notes":[]},{"n":8,"t":"你從天上使人聽判斷。神起來施行審判，要救地上一切謙卑的人；那時地就懼怕而靜默。（細拉）","notes":[],"end":9},{"n":10,"t":"人的忿怒要成全你的榮美；人的餘怒，你要禁止。","notes":[]},{"n":11,"t":"你們許願，當向耶和華－你們的神還願；在他四面的人都當拿貢物獻給那可畏的主。","notes":[]},{"n":12,"t":"他要挫折王子的驕氣；他向地上的君王顯威可畏。","notes":[]}]},"77":{"heading":"遇難時得安慰","verses":[{"n":1,"t":"我要向神發聲呼求；我向神發聲，他必留心聽我。","notes":[]},{"n":2,"t":"我在患難之日尋求主；我在夜間不住地舉手禱告；我的心不肯受安慰。","notes":[]},{"n":3,"t":"我想念神，就煩燥不安；我沉吟悲傷，心便發昏。（細拉）","notes":[]},{"n":4,"t":"你叫我不能閉眼；我煩亂不安，甚至不能說話。","notes":[]},{"n":5,"t":"我追想古時之日，上古之年。","notes":[]},{"n":6,"t":"我想起我夜間的歌曲，捫心自問；我心裏也仔細省察。","notes":[]},{"n":7,"t":"難道主要永遠丟棄我，不再施恩嗎？","notes":[]},{"n":8,"t":"難道他的慈愛永遠窮盡，他的應許世世廢棄嗎？","notes":[]},{"n":9,"t":"難道神忘記開恩，因發怒就止住他的慈悲嗎？（細拉）","notes":[]},{"n":10,"t":"我便說：這是我的懦弱，但我要追念至高者顯出右手之年代。","notes":[]},{"n":11,"t":"我要提說耶和華所行的；我要記念你古時的奇事。","notes":[]},{"n":12,"t":"我也要思想你的經營，默念你的作為。","notes":[]},{"n":13,"t":"神啊，你的作為是潔淨的；有何神大如神呢？","notes":[]},{"n":14,"t":"你是行奇事的神；你曾在列邦中彰顯你的能力。","notes":[]},{"n":15,"t":"你曾用你的膀臂贖了你的民，就是雅各和約瑟的子孫。（細拉）","notes":[]},{"n":16,"t":"神啊，諸水見你，一見就都驚惶；深淵也都戰抖。","notes":[]},{"n":17,"t":"雲中倒出水來；天空發出響聲；你的箭也飛行四方。","notes":[]},{"n":18,"t":"你的雷聲在旋風中；電光照亮世界；大地戰抖震動。","notes":[]},{"n":19,"t":"你的道在海中；你的路在大水中；你的腳蹤無人知道。","notes":[]},{"n":20,"t":"你曾藉摩西和亞倫的手引導你的百姓，好像羊群一般。","notes":[]}]},"78":{"heading":"神與他的子民","verses":[{"n":1,"t":"我的民哪，你們要留心聽我的訓誨，側耳聽我口中的話。","notes":[]},{"n":2,"t":"我要開口說比喻；我要說出古時的謎語，","notes":[]},{"n":3,"t":"是我們所聽見、所知道的，也是我們的祖宗告訴我們的。","notes":[]},{"n":4,"t":"我們不將這些事向他們的子孫隱瞞，要將耶和華的美德和他的能力，並他奇妙的作為，述說給後代聽。","notes":[]},{"n":5,"t":"因為，他在雅各中立法度，在以色列中設律法；是他吩咐我們祖宗要傳給子孫的，","notes":[]},{"n":6,"t":"使將要生的後代子孫可以曉得；他們也要起來告訴他們的子孫，","notes":[]},{"n":7,"t":"好叫他們仰望神，不忘記神的作為，惟要守他的命令。","notes":[]},{"n":8,"t":"不要像他們的祖宗，是頑梗悖逆、居心不正之輩，向著神，心不誠實。","notes":[]},{"n":9,"t":"以法蓮的子孫帶著兵器，拿著弓，臨陣之日轉身退後。","notes":[]},{"n":10,"t":"他們不遵守神的約，不肯照他的律法行；","notes":[]},{"n":11,"t":"又忘記他所行的和他顯給他們奇妙的作為。","notes":[]},{"n":12,"t":"他在埃及地，在瑣安田，在他們祖宗的眼前施行奇事。","notes":[]},{"n":13,"t":"他將海分裂，使他們過去，又叫水立起如壘。","notes":[]},{"n":14,"t":"他白日用雲彩，終夜用火光引導他們。","notes":[]},{"n":15,"t":"他在曠野分裂磐石，多多地給他們水喝，如從深淵而出。","notes":[]},{"n":16,"t":"他使水從磐石湧出，叫水如江河下流。","notes":[]},{"n":17,"t":"他們卻仍舊得罪他，在乾燥之地悖逆至高者。","notes":[]},{"n":18,"t":"他們心中試探神，隨自己所欲的求食物，","notes":[]},{"n":19,"t":"並且妄論神說：神在曠野豈能擺設筵席嗎？","notes":[]},{"n":20,"t":"他曾擊打磐石，使水湧出，成了江河；他還能賜糧食嗎？還能為他的百姓預備肉嗎？","notes":[]},{"n":21,"t":"所以，耶和華聽見就發怒；有烈火向雅各燒起；有怒氣向以色列上騰；","notes":[]},{"n":22,"t":"因為他們不信服神，不倚賴他的救恩。","notes":[]},{"n":23,"t":"他卻吩咐天空，又敞開天上的門，","notes":[]},{"n":24,"t":"降嗎哪，像雨給他們吃，將天上的糧食賜給他們。","notes":[]},{"n":25,"t":"各人吃大能者的食物；他賜下糧食，使他們飽足。","notes":["或譯：人"]},{"n":26,"t":"他領東風起在天空，又用能力引了南風來。","notes":[]},{"n":27,"t":"他降肉，像雨在他們當中，多如塵土，又降飛鳥，多如海沙，","notes":[]},{"n":28,"t":"落在他們的營中，在他們住處的四面。","notes":[]},{"n":29,"t":"他們吃了，而且飽足；這樣就隨了他們所欲的。","notes":[]},{"n":30,"t":"他們貪而無厭，食物還在他們口中的時候，","notes":[]},{"n":31,"t":"神的怒氣就向他們上騰，殺了他們內中的肥壯人，打倒以色列的少年人。","notes":[]},{"n":32,"t":"雖是這樣，他們仍舊犯罪，不信他奇妙的作為。","notes":[]},{"n":33,"t":"因此，他叫他們的日子全歸虛空，叫他們的年歲盡屬驚恐。","notes":[]},{"n":34,"t":"他殺他們的時候，他們才求問他，回心轉意，切切地尋求神。","notes":[]},{"n":35,"t":"他們也追念神是他們的磐石，至高的神是他們的救贖主。","notes":[]},{"n":36,"t":"他們卻用口諂媚他，用舌向他說謊。","notes":[]},{"n":37,"t":"因他們的心向他不正，在他的約上也不忠心。","notes":[]},{"n":38,"t":"但他有憐憫，赦免他們的罪孽，不滅絕他們，而且屢次消他的怒氣，不發盡他的忿怒。","notes":[]},{"n":39,"t":"他想到他們不過是血氣，是一陣去而不返的風。","notes":[]},{"n":40,"t":"他們在曠野悖逆他，在荒地叫他擔憂，何其多呢！","notes":[]},{"n":41,"t":"他們再三試探神，惹動以色列的聖者。","notes":[]},{"n":42,"t":"他們不追念他的能力和贖他們脫離敵人的日子；","notes":["原文是手"]},{"n":43,"t":"他怎樣在埃及地顯神蹟，在瑣安田顯奇事，","notes":[]},{"n":44,"t":"把他們的江河並河汊的水都變為血，使他們不能喝。","notes":[]},{"n":45,"t":"他叫蒼蠅成群落在他們當中，嘬盡他們，又叫青蛙滅了他們，","notes":[]},{"n":46,"t":"把他們的土產交給螞蚱，把他們辛苦得來的交給蝗蟲。","notes":[]},{"n":47,"t":"他降冰雹打壞他們的葡萄樹，下嚴霜打壞他們的桑樹，","notes":[]},{"n":48,"t":"又把他們的牲畜交給冰雹，把他們的群畜交給閃電。","notes":[]},{"n":49,"t":"他使猛烈的怒氣和忿怒、惱恨、苦難成了一群降災的使者，臨到他們。","notes":[]},{"n":50,"t":"他為自己的怒氣修平了路，將他們交給瘟疫，使他們死亡，","notes":[]},{"n":51,"t":"在埃及擊殺一切長子，在含的帳棚中擊殺他們強壯時頭生的。","notes":[]},{"n":52,"t":"他卻領出自己的民如羊，在曠野引他們如羊群。","notes":[]},{"n":53,"t":"他領他們穩穩妥妥地，使他們不致害怕；海卻淹沒他們的仇敵。","notes":[]},{"n":54,"t":"他帶他們到自己聖地的邊界，到他右手所得的這山地。","notes":[]},{"n":55,"t":"他在他們面前趕出外邦人，用繩子將外邦的地量給他們為業，叫以色列支派的人住在他們的帳棚裏。","notes":[]},{"n":56,"t":"他們仍舊試探、悖逆至高的神，不守他的法度，","notes":[]},{"n":57,"t":"反倒退後，行詭詐，像他們的祖宗一樣；他們改變，如同翻背的弓。","notes":[]},{"n":58,"t":"因他們的邱壇惹了他的怒氣；因他們雕刻的偶像觸動他的憤恨。","notes":[]},{"n":59,"t":"神聽見就發怒，極其憎惡以色列人。","notes":[]},{"n":60,"t":"甚至他離棄示羅的帳幕，就是他在人間所搭的帳棚；","notes":[]},{"n":61,"t":"又將他的約櫃交與人擄去，將他的榮耀交在敵人手中；","notes":["原文是能力"]},{"n":62,"t":"並將他的百姓交與刀劍，向他的產業發怒。","notes":[]},{"n":63,"t":"少年人被火燒滅；處女也無喜歌。","notes":[]},{"n":64,"t":"祭司倒在刀下，寡婦卻不哀哭。","notes":[]},{"n":65,"t":"那時，主像世人睡醒，像勇士飲酒呼喊。","notes":[]},{"n":66,"t":"他就打退了他的敵人，叫他們永蒙羞辱；","notes":[]},{"n":67,"t":"並且他棄掉約瑟的帳棚，不揀選以法蓮支派，","notes":[]},{"n":68,"t":"卻揀選猶大支派－他所喜愛的錫安山；","notes":[]},{"n":69,"t":"蓋造他的聖所，好像高峰，又像他建立永存之地；","notes":[]},{"n":70,"t":"又揀選他的僕人大衛，從羊圈中將他召來，","notes":[]},{"n":71,"t":"叫他不再跟從那些帶奶的母羊，為要牧養自己的百姓雅各和自己的產業以色列。","notes":[]},{"n":72,"t":"於是，他按心中的純正牧養他們，用手中的巧妙引導他們。","notes":[]}]},"79":{"heading":"求主解救國家","verses":[{"n":1,"t":"神啊，外邦人進入你的產業，污穢你的聖殿，使耶路撒冷變成荒堆，","notes":[]},{"n":2,"t":"把你僕人的屍首交與天空的飛鳥為食，把你聖民的肉交與地上的野獸，","notes":[]},{"n":3,"t":"在耶路撒冷周圍流他們的血如水，無人葬埋。","notes":[]},{"n":4,"t":"我們成為鄰國的羞辱，成為我們四圍人的嗤笑譏刺。","notes":[]},{"n":5,"t":"耶和華啊，這到幾時呢？你要動怒到永遠嗎？你的憤恨要如火焚燒嗎？","notes":[]},{"n":6,"t":"願你將你的忿怒倒在那不認識你的外邦和那不求告你名的國度。","notes":[]},{"n":7,"t":"因為他們吞了雅各，把他的住處變為荒場。","notes":[]},{"n":8,"t":"求你不要記念我們先祖的罪孽，向我們追討；願你的慈悲快迎著我們，因為我們落到極卑微的地步。","notes":[]},{"n":9,"t":"拯救我們的神啊，求你因你名的榮耀幫助我們！為你名的緣故搭救我們，赦免我們的罪。","notes":[]},{"n":10,"t":"為何容外邦人說「他們的神在哪裏」呢？願你使外邦人知道你在我們眼前伸你僕人流血的冤。","notes":[]},{"n":11,"t":"願被囚之人的歎息達到你面前；願你按你的大能力存留那些將要死的人。","notes":[]},{"n":12,"t":"主啊，願你將我們鄰邦所羞辱你的羞辱加七倍歸到他們身上。","notes":[]},{"n":13,"t":"這樣，你的民，你草場的羊，要稱謝你，直到永遠；要述說讚美你的話，直到萬代。","notes":[]}]},"80":{"heading":"求主復興國家","verses":[{"n":1,"t":"領約瑟如領羊群之以色列的牧者啊，求你留心聽！坐在二基路伯上的啊，求你發出光來！","notes":[]},{"n":2,"t":"在以法蓮、便雅憫、瑪拿西前面施展你的大能，來救我們。","notes":[]},{"n":3,"t":"神啊，求你使我們回轉，使你的臉發光，我們便要得救！","notes":["或譯：復興"]},{"n":4,"t":"耶和華－萬軍之神啊，你向你百姓的禱告發怒，要到幾時呢？","notes":[]},{"n":5,"t":"你以眼淚當食物給他們吃，又多量出眼淚給他們喝。","notes":[]},{"n":6,"t":"你使鄰邦因我們紛爭；我們的仇敵彼此戲笑。","notes":[]},{"n":7,"t":"萬軍之神啊，求你使我們回轉，使你的臉發光，我們便要得救！","notes":[]},{"n":8,"t":"你從埃及挪出一棵葡萄樹，趕出外邦人，把這樹栽上。","notes":[]},{"n":9,"t":"你在這樹根前預備了地方，它就深深扎根，爬滿了地。","notes":[]},{"n":10,"t":"它的影子遮滿了山，枝子好像佳美的香柏樹。","notes":[]},{"n":11,"t":"它發出枝子，長到大海，發出蔓子，延到大河。","notes":[]},{"n":12,"t":"你為何拆毀這樹的籬笆，任憑一切過路的人摘取？","notes":[]},{"n":13,"t":"林中出來的野豬把它糟踏；野地的走獸拿它當食物。","notes":[]},{"n":14,"t":"萬軍之神啊，求你回轉！從天上垂看，眷顧這葡萄樹，","notes":[]},{"n":15,"t":"保護你右手所栽的和你為自己所堅固的枝子。","notes":[]},{"n":16,"t":"這樹已經被火焚燒，被刀砍伐；他們因你臉上的怒容就滅亡了。","notes":[]},{"n":17,"t":"願你的手扶持你右邊的人，就是你為自己所堅固的人子。","notes":[]},{"n":18,"t":"這樣，我們便不退後離開你；求你救活我們，我們就要求告你的名。","notes":[]},{"n":19,"t":"耶和華－萬軍之神啊，求你使我們回轉，使你的臉發光，我們便要得救！","notes":[]}]},"81":{"heading":"聖潔的詩","verses":[{"n":1,"t":"你們當向神－我們的力量大聲歡呼，向雅各的神發聲歡樂！","notes":[]},{"n":2,"t":"唱起詩歌，打手鼓，彈美琴與瑟。","notes":[]},{"n":3,"t":"當在月朔並月望－我們過節的日期吹角，","notes":[]},{"n":4,"t":"因這是為以色列定的律例，是雅各神的典章。","notes":[]},{"n":5,"t":"他去攻擊埃及地的時候，在約瑟中間立此為證。我在那裏聽見我所不明白的言語：","notes":[]},{"n":6,"t":"神說：我使你的肩得脫重擔，你的手放下筐子。","notes":[]},{"n":7,"t":"你在急難中呼求，我就搭救你；我在雷的隱密處應允你，在米利巴水那裏試驗你。（細拉）","notes":[]},{"n":8,"t":"我的民哪，你當聽，我要勸戒你；以色列啊，甚願你肯聽從我。","notes":[]},{"n":9,"t":"在你當中，不可有別的神；外邦的神，你也不可下拜。","notes":[]},{"n":10,"t":"我是耶和華－你的神，曾把你從埃及地領上來；你要大大張口，我就給你充滿。","notes":[]},{"n":11,"t":"無奈，我的民不聽我的聲音；以色列全不理我。","notes":[]},{"n":12,"t":"我便任憑他們心裏剛硬，隨自己的計謀而行。","notes":[]},{"n":13,"t":"甚願我的民肯聽從我，以色列肯行我的道，","notes":[]},{"n":14,"t":"我便速速治服他們的仇敵，反手攻擊他們的敵人。","notes":[]},{"n":15,"t":"恨耶和華的人必來投降，但他的百姓必永久長存。","notes":[]},{"n":16,"t":"他也必拿上好的麥子給他們吃，又拿從磐石出的蜂蜜叫他們飽足。","notes":[]}]},"82":{"heading":"神是最高的主宰","verses":[{"n":1,"t":"神站在有權力者的會中，在諸神中行審判，","notes":[]},{"n":2,"t":"說：你們審判不秉公義，徇惡人的情面，要到幾時呢？（細拉）","notes":[]},{"n":3,"t":"你們當為貧寒的人和孤兒伸冤；當為困苦和窮乏的人施行公義。","notes":[]},{"n":4,"t":"當保護貧寒和窮乏的人，救他們脫離惡人的手。","notes":[]},{"n":5,"t":"你們仍不知道，也不明白，在黑暗中走來走去；地的根基都搖動了。","notes":[]},{"n":6,"t":"我曾說：你們是神，都是至高者的兒子。","notes":[]},{"n":7,"t":"然而，你們要死，與世人一樣，要仆倒，像王子中的一位。","notes":[]},{"n":8,"t":"神啊，求你起來審判世界，因為你要得萬邦為業。","notes":[]}]},"83":{"heading":"求主敗敵","verses":[{"n":1,"t":"神啊，求你不要靜默！神啊，求你不要閉口，也不要不作聲！","notes":[]},{"n":2,"t":"因為你的仇敵喧嚷，恨你的抬起頭來。","notes":[]},{"n":3,"t":"他們同謀奸詐要害你的百姓，彼此商議要害你所隱藏的人。","notes":[]},{"n":4,"t":"他們說：來吧，我們將他們剪滅，使他們不再成國！使以色列的名不再被人記念！","notes":[]},{"n":5,"t":"他們同心商議，彼此結盟，要抵擋你，","notes":[]},{"n":6,"t":"就是住帳棚的以東人和以實瑪利人，摩押和夏甲人，","notes":[]},{"n":7,"t":"迦巴勒、亞捫，和亞瑪力、非利士並泰爾的居民。","notes":[]},{"n":8,"t":"亞述也與他們連合；他們作羅得子孫的幫手。（細拉）","notes":[]},{"n":9,"t":"求你待他們，如待米甸，如在基順河待西西拉和耶賓一樣。","notes":[]},{"n":10,"t":"他們在隱‧多珥滅亡，成了地上的糞土。","notes":[]},{"n":11,"t":"求你叫他們的首領像俄立和西伊伯，叫他們的王子都像西巴和撒慕拿。","notes":[]},{"n":12,"t":"他們說：我們要得神的住處，作為自己的產業。","notes":[]},{"n":13,"t":"我的神啊，求你叫他們像旋風的塵土，像風前的碎稭。","notes":[]},{"n":14,"t":"火怎樣焚燒樹林，火焰怎樣燒著山嶺，","notes":[]},{"n":15,"t":"求你也照樣用狂風追趕他們，用暴雨恐嚇他們。","notes":[]},{"n":16,"t":"願你使他們滿面羞恥，好叫他們尋求你－耶和華的名！","notes":[]},{"n":17,"t":"願他們永遠羞愧驚惶！願他們慚愧滅亡！","notes":[]},{"n":18,"t":"使他們知道：惟獨你－名為耶和華的－是全地以上的至高者！","notes":[]}]},"84":{"heading":"渴慕耶和華的殿宇","verses":[{"n":1,"t":"萬軍之耶和華啊，你的居所何等可愛！","notes":[]},{"n":2,"t":"我羨慕渴想耶和華的院宇；我的心腸，我的肉體向永生神呼籲。","notes":["或譯：歡呼"]},{"n":3,"t":"萬軍之耶和華－我的王，我的神啊，在你祭壇那裏，麻雀為自己找著房屋，燕子為自己找著菢雛之窩。","notes":[]},{"n":4,"t":"如此住在你殿中的便為有福！他們仍要讚美你。（細拉）","notes":[]},{"n":5,"t":"靠你有力量、心中想往錫安大道的，這人便為有福！","notes":[]},{"n":6,"t":"他們經過「流淚谷」，叫這谷變為泉源之地；並有秋雨之福蓋滿了全谷。","notes":[]},{"n":7,"t":"他們行走，力上加力，各人到錫安朝見神。","notes":[]},{"n":8,"t":"耶和華－萬軍之神啊，求你聽我的禱告！雅各的神啊，求你留心聽！（細拉）","notes":[]},{"n":9,"t":"神啊，你是我們的盾牌；求你垂顧觀看你受膏者的面！","notes":[]},{"n":10,"t":"在你的院宇住一日，勝似在別處住千日；寧可在我神殿中看門，不願住在惡人的帳棚裏。","notes":[]},{"n":11,"t":"因為耶和華－神是日頭，是盾牌，要賜下恩惠和榮耀。他未嘗留下一樣好處不給那些行動正直的人。","notes":[]},{"n":12,"t":"萬軍之耶和華啊，倚靠你的人便為有福！","notes":[]}]},"85":{"heading":"為國求福","verses":[{"n":1,"t":"耶和華啊，你已經向你的地施恩，救回被擄的雅各。","notes":[]},{"n":2,"t":"你赦免了你百姓的罪孽，遮蓋了他們一切的過犯。（細拉）","notes":[]},{"n":3,"t":"你收轉了所發的忿怒和你猛烈的怒氣。","notes":[]},{"n":4,"t":"拯救我們的神啊，求你使我們回轉，叫你的惱恨向我們止息。","notes":[]},{"n":5,"t":"你要向我們發怒到永遠嗎？你要將你的怒氣延留到萬代嗎？","notes":[]},{"n":6,"t":"你不再將我們救活，使你的百姓靠你歡喜嗎？","notes":[]},{"n":7,"t":"耶和華啊，求你使我們得見你的慈愛，又將你的救恩賜給我們。","notes":[]},{"n":8,"t":"我要聽神－耶和華所說的話；因為他必應許將平安賜給他的百姓－他的聖民；他們卻不可再轉去妄行。","notes":[]},{"n":9,"t":"他的救恩誠然與敬畏他的人相近，叫榮耀住在我們的地上。","notes":[]},{"n":10,"t":"慈愛和誠實彼此相遇；公義和平安彼此相親。","notes":[]},{"n":11,"t":"誠實從地而生；公義從天而現。","notes":[]},{"n":12,"t":"耶和華必將好處賜給我們；我們的地也要多出土產。","notes":[]},{"n":13,"t":"公義要行在他面前，叫他的腳蹤成為可走的路。","notes":[]}]},"86":{"heading":"求主恩助","verses":[{"n":1,"t":"耶和華啊，求你側耳應允我，因我是困苦窮乏的。","notes":[]},{"n":2,"t":"求你保存我的性命，因我是虔誠人。我的神啊，求你拯救這倚靠你的僕人！","notes":[]},{"n":3,"t":"主啊，求你憐憫我，因我終日求告你。","notes":[]},{"n":4,"t":"主啊，求你使僕人心裏歡喜，因為我的心仰望你。","notes":[]},{"n":5,"t":"主啊，你本為良善，樂意饒恕人，有豐盛的慈愛賜給凡求告你的人。","notes":[]},{"n":6,"t":"耶和華啊，求你留心聽我的禱告，垂聽我懇求的聲音。","notes":[]},{"n":7,"t":"我在患難之日要求告你，因為你必應允我。","notes":[]},{"n":8,"t":"主啊，諸神之中沒有可比你的；你的作為也無可比。","notes":[]},{"n":9,"t":"主啊，你所造的萬民都要來敬拜你；他們也要榮耀你的名。","notes":[]},{"n":10,"t":"因你為大，且行奇妙的事；惟獨你是神。","notes":[]},{"n":11,"t":"耶和華啊，求你將你的道指教我；我要照你的真理行；求你使我專心敬畏你的名！","notes":[]},{"n":12,"t":"主－我的神啊，我要一心稱讚你；我要榮耀你的名，直到永遠。","notes":[]},{"n":13,"t":"因為，你向我發的慈愛是大的；你救了我的靈魂免入極深的陰間。","notes":[]},{"n":14,"t":"神啊，驕傲的人起來攻擊我，又有一黨強橫的人尋索我的命；他們沒有將你放在眼中。","notes":[]},{"n":15,"t":"主啊，你是有憐憫有恩典的神，不輕易發怒，並有豐盛的慈愛和誠實。","notes":[]},{"n":16,"t":"求你向我轉臉，憐恤我，將你的力量賜給僕人，救你婢女的兒子。","notes":[]},{"n":17,"t":"求你向我顯出恩待我的憑據，叫恨我的人看見便羞愧，因為你－耶和華幫助我，安慰我。","notes":[]}]},"87":{"heading":"錫安頌","verses":[{"n":1,"t":"耶和華所立的根基在聖山上。","notes":[]},{"n":2,"t":"他愛錫安的門，勝於愛雅各一切的住處。","notes":[]},{"n":3,"t":"神的城啊，有榮耀的事乃指著你說的。（細拉）","notes":[]},{"n":4,"t":"我要提起拉哈伯和巴比倫人，是在認識我之中的；看哪，非利士和泰爾並古實人，個個生在那裏。","notes":[]},{"n":5,"t":"論到錫安，必說：這一個、那一個都生在其中，而且至高者必親自堅立這城。","notes":[]},{"n":6,"t":"當耶和華記錄萬民的時候，他要點出這一個生在那裏。（細拉）","notes":[]},{"n":7,"t":"歌唱的，跳舞的，都要說：我的泉源都在你裏面。","notes":[]}]},"88":{"heading":"求主眷顧","verses":[{"n":1,"t":"耶和華－拯救我的神啊，我晝夜在你面前呼籲。","notes":[]},{"n":2,"t":"願我的禱告達到你面前；求你側耳聽我的呼求！","notes":[]},{"n":3,"t":"因為我心裏滿了患難；我的性命臨近陰間。","notes":[]},{"n":4,"t":"我算和下坑的人同列，如同無力的人一樣。","notes":["或譯：沒有幫助"]},{"n":5,"t":"我被丟在死人中，好像被殺的人躺在墳墓裏。他們是你不再記念的，與你隔絕了。","notes":[]},{"n":6,"t":"你把我放在極深的坑裏，在黑暗地方，在深處。","notes":[]},{"n":7,"t":"你的忿怒重壓我身；你用一切的波浪困住我。（細拉）","notes":[]},{"n":8,"t":"你把我所認識的隔在遠處，使我為他們所憎惡；我被拘困，不得出來。","notes":[]},{"n":9,"t":"我的眼睛因困苦而乾癟。耶和華啊，我天天求告你，向你舉手。","notes":[]},{"n":10,"t":"你豈要行奇事給死人看嗎？難道陰魂還能起來稱讚你嗎？（細拉）","notes":[]},{"n":11,"t":"豈能在墳墓裏述說你的慈愛嗎？豈能在滅亡中述說你的信實嗎？","notes":[]},{"n":12,"t":"你的奇事豈能在幽暗裏被知道嗎？你的公義豈能在忘記之地被知道嗎？","notes":[]},{"n":13,"t":"耶和華啊，我呼求你；我早晨的禱告要達到你面前。","notes":[]},{"n":14,"t":"耶和華啊，你為何丟棄我？為何掩面不顧我？","notes":[]},{"n":15,"t":"我自幼受苦，幾乎死亡；我受你的驚恐，甚至慌張。","notes":[]},{"n":16,"t":"你的烈怒漫過我身；你的驚嚇把我剪除。","notes":[]},{"n":17,"t":"這些終日如水環繞我，一齊都來圍困我。","notes":[]},{"n":18,"t":"你把我的良朋密友隔在遠處，使我所認識的人進入黑暗裏。","notes":[]}]},"89":{"heading":"困難中的聖詩","verses":[{"n":1,"t":"我要歌唱耶和華的慈愛，直到永遠；我要用口將你的信實傳與萬代。","notes":[]},{"n":2,"t":"因我曾說：你的慈悲必建立到永遠；你的信實必堅立在天上。","notes":[]},{"n":3,"t":"我與我所揀選的人立了約，向我的僕人大衛起了誓：","notes":[]},{"n":4,"t":"我要建立你的後裔，直到永遠；要建立你的寶座，直到萬代。（細拉）","notes":[]},{"n":5,"t":"耶和華啊，諸天要稱讚你的奇事；在聖者的會中，要稱讚你的信實。","notes":[]},{"n":6,"t":"在天空誰能比耶和華呢？神的眾子中，誰能像耶和華呢？","notes":[]},{"n":7,"t":"他在聖者的會中，是大有威嚴的神，比一切在他四圍的更可畏懼。","notes":[]},{"n":8,"t":"耶和華－萬軍之神啊，哪一個大能者像你耶和華？你的信實是在你的四圍。","notes":[]},{"n":9,"t":"你管轄海的狂傲；波浪翻騰，你就使它平靜了。","notes":[]},{"n":10,"t":"你打碎了拉哈伯，似乎是已殺的人；你用有能的膀臂打散了你的仇敵。","notes":[]},{"n":11,"t":"天屬你，地也屬你；世界和其中所充滿的都為你所建立。","notes":[]},{"n":12,"t":"南北為你所創造；他泊和黑門都因你的名歡呼。","notes":[]},{"n":13,"t":"你有大能的膀臂；你的手有力，你的右手也高舉。","notes":[]},{"n":14,"t":"公義和公平是你寶座的根基；慈愛和誠實行在你前面。","notes":[]},{"n":15,"t":"知道向你歡呼的，那民是有福的！耶和華啊，他們在你臉上的光裏行走。","notes":[]},{"n":16,"t":"他們因你的名終日歡樂，因你的公義得以高舉。","notes":[]},{"n":17,"t":"你是他們力量的榮耀；因為你喜悅我們，我們的角必被高舉。","notes":[]},{"n":18,"t":"我們的盾牌屬耶和華；我們的王屬以色列的聖者。","notes":[]},{"n":19,"t":"當時，你在異象中曉諭你的聖民，說：我已把救助之力加在那有能者的身上；我高舉那從民中所揀選的。","notes":[],"heads":["神對大衛的應許"]},{"n":20,"t":"我尋得我的僕人大衛，用我的聖膏膏他。","notes":[]},{"n":21,"t":"我的手必使他堅立；我的膀臂也必堅固他。","notes":[]},{"n":22,"t":"仇敵必不勒索他；凶惡之子也不苦害他。","notes":[]},{"n":23,"t":"我要在他面前打碎他的敵人，擊殺那恨他的人。","notes":[]},{"n":24,"t":"只是我的信實和我的慈愛要與他同在；因我的名，他的角必被高舉。","notes":[]},{"n":25,"t":"我要使他的左手伸到海上，右手伸到河上。","notes":[]},{"n":26,"t":"他要稱呼我說：你是我的父，是我的神，是拯救我的磐石。","notes":[]},{"n":27,"t":"我也要立他為長子，為世上最高的君王。","notes":[]},{"n":28,"t":"我要為他存留我的慈愛，直到永遠；我與他立的約必要堅定。","notes":[]},{"n":29,"t":"我也要使他的後裔存到永遠，使他的寶座如天之久。","notes":[]},{"n":30,"t":"倘若他的子孫離棄我的律法，不照我的典章行，","notes":[]},{"n":31,"t":"背棄我的律例，不遵守我的誡命，","notes":[]},{"n":32,"t":"我就要用杖責罰他們的過犯，用鞭責罰他們的罪孽。","notes":[]},{"n":33,"t":"只是我必不將我的慈愛全然收回，也必不叫我的信實廢棄。","notes":[]},{"n":34,"t":"我必不背棄我的約，也不改變我口中所出的。","notes":[]},{"n":35,"t":"我一次指著自己的聖潔起誓：我決不向大衛說謊！","notes":[]},{"n":36,"t":"他的後裔要存到永遠；他的寶座在我面前如日之恆一般，","notes":[]},{"n":37,"t":"又如月亮永遠堅立，如天上確實的見證。（細拉）","notes":[]},{"n":38,"t":"但你惱怒你的受膏者，就丟掉棄絕他。","notes":[],"heads":["君主慘敗的哀歌"]},{"n":39,"t":"你厭惡了與僕人所立的約，將他的冠冕踐踏於地。","notes":[]},{"n":40,"t":"你拆毀了他一切的籬笆，使他的保障變為荒場。","notes":[]},{"n":41,"t":"凡過路的人都搶奪他；他成為鄰邦的羞辱。","notes":[]},{"n":42,"t":"你高舉了他敵人的右手；你叫他一切的仇敵歡喜。","notes":[]},{"n":43,"t":"你叫他的刀劍捲刃，叫他在爭戰之中站立不住。","notes":[]},{"n":44,"t":"你使他的光輝止息，將他的寶座推倒於地。","notes":[]},{"n":45,"t":"你減少他青年的日子，又使他蒙羞。（細拉）","notes":[]},{"n":46,"t":"耶和華啊，這要到幾時呢？你要將自己隱藏到永遠嗎？你的忿怒如火焚燒要到幾時呢？","notes":[],"heads":["求救的禱告"]},{"n":47,"t":"求你想念我的時候是何等的短少；你創造世人，要使他們歸何等的虛空呢？","notes":[]},{"n":48,"t":"誰能常活免死、救他的靈魂脫離陰間的權柄呢？（細拉）","notes":[]},{"n":49,"t":"主啊，你從前憑你的信實向大衛立誓要施行的慈愛在哪裏呢？","notes":[]},{"n":50,"t":"主啊，求你記念僕人們所受的羞辱，記念我怎樣將一切強盛民的羞辱存在我懷裏。","notes":[]},{"n":51,"t":"耶和華啊，你的仇敵用這羞辱羞辱了你的僕人，羞辱了你受膏者的腳蹤。","notes":[]},{"n":52,"t":"耶和華是應當稱頌的，直到永遠。阿們！阿們！","notes":[]}]},"90":{"heading":"神與人","verses":[{"n":1,"t":"主啊，你世世代代作我們的居所。","notes":[]},{"n":2,"t":"諸山未曾生出，地與世界你未曾造成，從亙古到永遠，你是神。","notes":[]},{"n":3,"t":"你使人歸於塵土，說：你們世人要歸回。","notes":[]},{"n":4,"t":"在你看來，千年如已過的昨日，又如夜間的一更。","notes":[]},{"n":5,"t":"你叫他們如水沖去；他們如睡一覺。早晨，他們如生長的草，","notes":[]},{"n":6,"t":"早晨發芽生長，晚上割下枯乾。","notes":[]},{"n":7,"t":"我們因你的怒氣而消滅，因你的忿怒而驚惶。","notes":[]},{"n":8,"t":"你將我們的罪孽擺在你面前，將我們的隱惡擺在你面光之中。","notes":[]},{"n":9,"t":"我們經過的日子都在你震怒之下；我們度盡的年歲好像一聲歎息。","notes":[]},{"n":10,"t":"我們一生的年日是七十歲，若是強壯可到八十歲；但其中所矜誇的不過是勞苦愁煩，轉眼成空，我們便如飛而去。","notes":[]},{"n":11,"t":"誰曉得你怒氣的權勢？誰按著你該受的敬畏曉得你的忿怒呢？","notes":[]},{"n":12,"t":"求你指教我們怎樣數算自己的日子，好叫我們得著智慧的心。","notes":[]},{"n":13,"t":"耶和華啊，我們要等到幾時呢？求你轉回，為你的僕人後悔。","notes":[]},{"n":14,"t":"求你使我們早早飽得你的慈愛，好叫我們一生一世歡呼喜樂。","notes":[]},{"n":15,"t":"求你照著你使我們受苦的日子，和我們遭難的年歲，叫我們喜樂。","notes":[]},{"n":16,"t":"願你的作為向你僕人顯現；願你的榮耀向他們子孫顯明。","notes":[]},{"n":17,"t":"願主－我們神的榮美歸於我們身上。願你堅立我們手所做的工；我們手所做的工，願你堅立。","notes":[]}]},"91":{"heading":"神是我們的保護者","verses":[{"n":1,"t":"住在至高者隱密處的，必住在全能者的蔭下。","notes":[]},{"n":2,"t":"我要論到耶和華說：他是我的避難所，是我的山寨，是我的神，是我所倚靠的。","notes":[]},{"n":3,"t":"他必救你脫離捕鳥人的網羅和毒害的瘟疫。","notes":[]},{"n":4,"t":"他必用自己的翎毛遮蔽你；你要投靠在他的翅膀底下；他的誠實是大小的盾牌。","notes":[]},{"n":5,"t":"你必不怕黑夜的驚駭，或是白日飛的箭，","notes":[]},{"n":6,"t":"也不怕黑夜行的瘟疫，或是午間滅人的毒病。","notes":[]},{"n":7,"t":"雖有千人仆倒在你旁邊，萬人仆倒在你右邊，這災卻不得臨近你。","notes":[]},{"n":8,"t":"你惟親眼觀看，見惡人遭報。","notes":[]},{"n":9,"t":"耶和華是我的避難所；你已將至高者當你的居所，","notes":[]},{"n":10,"t":"禍患必不臨到你，災害也不挨近你的帳棚。","notes":[]},{"n":11,"t":"因他要為你吩咐他的使者，在你行的一切道路上保護你。","notes":[]},{"n":12,"t":"他們要用手托著你，免得你的腳碰在石頭上。","notes":[]},{"n":13,"t":"你要踹在獅子和虺蛇的身上，踐踏少壯獅子和大蛇。","notes":[]},{"n":14,"t":"神說：因為他專心愛我，我就要搭救他；因為他知道我的名，我要把他安置在高處。","notes":[]},{"n":15,"t":"他若求告我，我就應允他；他在急難中，我要與他同在；我要搭救他，使他尊貴。","notes":[]},{"n":16,"t":"我要使他足享長壽，將我的救恩顯明給他。","notes":[]}]},"92":{"heading":"頌讚之詩","verses":[{"n":1,"t":"稱謝耶和華！歌頌你至高者的名！","notes":[]},{"n":2,"t":"用十弦的樂器和瑟，用琴彈幽雅的聲音，早晨傳揚你的慈愛；每夜傳揚你的信實。這本為美事。","notes":[],"end":3},{"n":4,"t":"因你－耶和華藉著你的作為叫我高興，我要因你手的工作歡呼。","notes":[]},{"n":5,"t":"耶和華啊，你的工作何其大！你的心思極其深！","notes":[]},{"n":6,"t":"畜類人不曉得；愚頑人也不明白。","notes":[]},{"n":7,"t":"惡人茂盛如草，一切作孽之人發旺的時候，正是他們要滅亡，直到永遠。","notes":[]},{"n":8,"t":"惟你－耶和華是至高，直到永遠。","notes":[]},{"n":9,"t":"耶和華啊，你的仇敵都要滅亡；一切作孽的也要離散。","notes":[]},{"n":10,"t":"你卻高舉了我的角，如野牛的角；我是被新油膏了的。","notes":[]},{"n":11,"t":"我眼睛看見仇敵遭報；我耳朵聽見那些起來攻擊我的惡人受罰。","notes":[]},{"n":12,"t":"義人要發旺如棕樹，生長如黎巴嫩的香柏樹。","notes":[]},{"n":13,"t":"他們栽於耶和華的殿中，發旺在我們神的院裏。","notes":[]},{"n":14,"t":"他們年老的時候仍要結果子，要滿了汁漿而常發青，","notes":[]},{"n":15,"t":"好顯明耶和華是正直的。他是我的磐石，在他毫無不義。","notes":[]}]},"93":{"heading":"神是王","verses":[{"n":1,"t":"耶和華作王！他以威嚴為衣穿上；耶和華以能力為衣，以能力束腰，世界就堅定，不得動搖。","notes":[]},{"n":2,"t":"你的寶座從太初立定；你從亙古就有。","notes":[]},{"n":3,"t":"耶和華啊，大水揚起，大水發聲，波浪澎湃。","notes":[]},{"n":4,"t":"耶和華在高處大有能力，勝過諸水的響聲，洋海的大浪。","notes":[]},{"n":5,"t":"耶和華啊，你的法度最的確；你的殿永稱為聖，是合宜的。","notes":[]}]},"94":{"heading":"神審判萬人","verses":[{"n":1,"t":"耶和華啊，你是伸冤的神；伸冤的神啊，求你發出光來！","notes":[]},{"n":2,"t":"審判世界的主啊，求你挺身而立，使驕傲人受應得的報應！","notes":[]},{"n":3,"t":"耶和華啊，惡人誇勝要到幾時呢？要到幾時呢？","notes":[]},{"n":4,"t":"他們絮絮叨叨說傲慢的話；一切作孽的人都自己誇張。","notes":[]},{"n":5,"t":"耶和華啊，他們強壓你的百姓，苦害你的產業。","notes":[]},{"n":6,"t":"他們殺死寡婦和寄居的，又殺害孤兒。","notes":[]},{"n":7,"t":"他們說：耶和華必不看見；雅各的神必不思念。","notes":[]},{"n":8,"t":"你們民間的畜類人當思想；你們愚頑人到幾時才有智慧呢？","notes":[]},{"n":9,"t":"造耳朵的，難道自己不聽見嗎？造眼睛的，難道自己不看見嗎？","notes":[]},{"n":10,"t":"管教列邦的，就是叫人得知識的，難道自己不懲治人嗎？","notes":[]},{"n":11,"t":"耶和華知道人的意念是虛妄的。","notes":[]},{"n":12,"t":"耶和華啊，你所管教、用律法所教訓的人是有福的！","notes":[]},{"n":13,"t":"你使他在遭難的日子得享平安；惟有惡人陷在所挖的坑中。","notes":[]},{"n":14,"t":"因為耶和華必不丟棄他的百姓，也不離棄他的產業。","notes":[]},{"n":15,"t":"審判要轉向公義；心裏正直的，必都隨從。","notes":[]},{"n":16,"t":"誰肯為我起來攻擊作惡的？誰肯為我站起抵擋作孽的？","notes":[]},{"n":17,"t":"若不是耶和華幫助我，我就住在寂靜之中了。","notes":[]},{"n":18,"t":"我正說我失了腳，耶和華啊，那時你的慈愛扶助我。","notes":[]},{"n":19,"t":"我心裏多憂多疑，你安慰我，就使我歡樂。","notes":[]},{"n":20,"t":"那藉著律例架弄殘害、在位上行奸惡的，豈能與你相交嗎？","notes":[]},{"n":21,"t":"他們大家聚集攻擊義人，將無辜的人定為死罪。","notes":[]},{"n":22,"t":"但耶和華向來作了我的高臺；我的神作了我投靠的磐石。","notes":[]},{"n":23,"t":"他叫他們的罪孽歸到他們身上。他們正在行惡之中，他要剪除他們；耶和華－我們的神要把他們剪除。","notes":[]}]},"95":{"heading":"頌讚之詩","verses":[{"n":1,"t":"來啊，我們要向耶和華歌唱，向拯救我們的磐石歡呼！","notes":[]},{"n":2,"t":"我們要來感謝他，用詩歌向他歡呼！","notes":[]},{"n":3,"t":"因耶和華為大神，為大王，超乎萬神之上。","notes":[]},{"n":4,"t":"地的深處在他手中；山的高峰也屬他。","notes":[]},{"n":5,"t":"海洋屬他，是他造的；旱地也是他手造成的。","notes":[]},{"n":6,"t":"來啊，我們要屈身敬拜，在造我們的耶和華面前跪下。","notes":[]},{"n":7,"t":"因為他是我們的神；我們是他草場的羊，是他手下的民。惟願你們今天聽他的話：","notes":[]},{"n":8,"t":"你們不可硬著心，像當日在米利巴，就是在曠野的瑪撒。","notes":[]},{"n":9,"t":"那時，你們的祖宗試我探我，並且觀看我的作為。","notes":[]},{"n":10,"t":"四十年之久，我厭煩那世代，說：這是心裏迷糊的百姓，竟不曉得我的作為！","notes":[]},{"n":11,"t":"所以，我在怒中起誓，說：他們斷不可進入我的安息！","notes":[]}]},"96":{"heading":"神是最高的君王","verses":[{"n":1,"t":"你們要向耶和華唱新歌！全地都要向耶和華歌唱！","notes":[]},{"n":2,"t":"要向耶和華歌唱，稱頌他的名！天天傳揚他的救恩！","notes":[]},{"n":3,"t":"在列邦中述說他的榮耀！在萬民中述說他的奇事！","notes":[]},{"n":4,"t":"因耶和華為大，當受極大的讚美；他在萬神之上，當受敬畏。","notes":[]},{"n":5,"t":"外邦的神都屬虛無；惟獨耶和華創造諸天。","notes":[]},{"n":6,"t":"有尊榮和威嚴在他面前；有能力與華美在他聖所。","notes":[]},{"n":7,"t":"民中的萬族啊，你們要將榮耀、能力歸給耶和華，都歸給耶和華！","notes":[]},{"n":8,"t":"要將耶和華的名所當得的榮耀歸給他，拿供物來進入他的院宇。","notes":[]},{"n":9,"t":"當以聖潔的妝飾敬拜耶和華；全地要在他面前戰抖！","notes":["的：或譯為"]},{"n":10,"t":"人在列邦中要說：耶和華作王！世界就堅定，不得動搖；他要按公正審判眾民。","notes":[]},{"n":11,"t":"願天歡喜，願地快樂！願海和其中所充滿的澎湃！","notes":[]},{"n":12,"t":"願田和其中所有的都歡樂！那時，林中的樹木都要在耶和華面前歡呼。","notes":[]},{"n":13,"t":"因為他來了，他來要審判全地。他要按公義審判世界，按他的信實審判萬民。","notes":[]}]},"97":{"heading":"神是最高的統治者","verses":[{"n":1,"t":"耶和華作王！願地快樂！願眾海島歡喜！","notes":[]},{"n":2,"t":"密雲和幽暗在他的四圍；公義和公平是他寶座的根基。","notes":[]},{"n":3,"t":"有烈火在他前頭行，燒滅他四圍的敵人。","notes":[]},{"n":4,"t":"他的閃電光照世界，大地看見便震動。","notes":[]},{"n":5,"t":"諸山見耶和華的面，就是全地之主的面，便消化如蠟。","notes":[]},{"n":6,"t":"諸天表明他的公義；萬民看見他的榮耀。","notes":[]},{"n":7,"t":"願一切事奉雕刻的偶像、靠虛無之神自誇的，都蒙羞愧。萬神哪，你們都當拜他。","notes":[]},{"n":8,"t":"耶和華啊，錫安聽見你的判斷就歡喜；猶大的城邑也都快樂。","notes":["原文是女子"]},{"n":9,"t":"因為你－耶和華至高，超乎全地；你被尊崇，遠超萬神之上。","notes":[]},{"n":10,"t":"你們愛耶和華的，都當恨惡罪惡；他保護聖民的性命，搭救他們脫離惡人的手。","notes":[]},{"n":11,"t":"散布亮光是為義人；預備喜樂是為正直人。","notes":[]},{"n":12,"t":"你們義人當靠耶和華歡喜，稱謝他可記念的聖名。","notes":[]}]},"98":{"heading":"神掌管世界","verses":[{"n":1,"t":"你們要向耶和華唱新歌！因為他行過奇妙的事；他的右手和聖臂施行救恩。","notes":[]},{"n":2,"t":"耶和華發明了他的救恩，在列邦人眼前顯出公義；","notes":[]},{"n":3,"t":"記念他向以色列家所發的慈愛，所憑的信實。地的四極都看見我們神的救恩。","notes":[]},{"n":4,"t":"全地都要向耶和華歡樂；要發起大聲，歡呼歌頌！","notes":[]},{"n":5,"t":"要用琴歌頌耶和華，用琴和詩歌的聲音歌頌他！","notes":[]},{"n":6,"t":"用號和角聲，在大君王耶和華面前歡呼！","notes":[]},{"n":7,"t":"願海和其中所充滿的澎湃；世界和住在其間的也要發聲。","notes":[]},{"n":8,"t":"願大水拍手；願諸山在耶和華面前一同歡呼；","notes":[]},{"n":9,"t":"因為他來要審判遍地。他要按公義審判世界，按公正審判萬民。","notes":[]}]},"99":{"heading":"神是至高之王","verses":[{"n":1,"t":"耶和華作王；萬民當戰抖！他坐在二基路伯上，地當動搖。","notes":[]},{"n":2,"t":"耶和華在錫安為大；他超乎萬民之上。","notes":[]},{"n":3,"t":"他們當稱讚他大而可畏的名；他本為聖！","notes":[]},{"n":4,"t":"王有能力，喜愛公平，堅立公正，在雅各中施行公平和公義。","notes":[]},{"n":5,"t":"你們當尊崇耶和華－我們的神，在他腳凳前下拜。他本為聖！","notes":[]},{"n":6,"t":"在他的祭司中有摩西和亞倫；在求告他名的人中有撒母耳。他們求告耶和華，他就應允他們。","notes":[]},{"n":7,"t":"他在雲柱中對他們說話；他們遵守他的法度和他所賜給他們的律例。","notes":[]},{"n":8,"t":"耶和華－我們的神啊，你應允他們；你是赦免他們的神，卻按他們所行的報應他們。","notes":[]},{"n":9,"t":"你們要尊崇耶和華－我們的神，在他的聖山下拜，因為耶和華－我們的神本為聖！","notes":[]}]},"100":{"heading":"頌讚之詩","verses":[{"n":1,"t":"普天下當向耶和華歡呼！","notes":[]},{"n":2,"t":"你們當樂意事奉耶和華，當來向他歌唱！","notes":[]},{"n":3,"t":"你們當曉得耶和華是神！我們是他造的，也是屬他的；我們是他的民，也是他草場的羊。","notes":[]},{"n":4,"t":"當稱謝進入他的門；當讚美進入他的院。當感謝他，稱頌他的名！","notes":[]},{"n":5,"t":"因為耶和華本為善。他的慈愛存到永遠；他的信實直到萬代。","notes":[]}]},"101":{"heading":"王的諾言","verses":[{"n":1,"t":"我要歌唱慈愛和公平；耶和華啊，我要向你歌頌！","notes":[]},{"n":2,"t":"我要用智慧行完全的道。你幾時到我這裏來呢？我要存完全的心行在我家中。","notes":[]},{"n":3,"t":"邪僻的事，我都不擺在我眼前；悖逆人所做的事，我甚恨惡，不容沾在我身上。","notes":[]},{"n":4,"t":"彎曲的心思，我必遠離；一切的惡人，我不認識。","notes":["或譯：惡事"]},{"n":5,"t":"在暗中讒謗他鄰居的，我必將他滅絕；眼目高傲、心裏驕縱的，我必不容他。","notes":[]},{"n":6,"t":"我眼要看國中的誠實人，叫他們與我同住；行為完全的，他要伺候我。","notes":[]},{"n":7,"t":"行詭詐的，必不得住在我家裏；說謊話的，必不得立在我眼前。","notes":[]},{"n":8,"t":"我每日早晨要滅絕國中所有的惡人，好把一切作孽的從耶和華的城裏剪除。","notes":[]}]},"102":{"heading":"遭難中的祈禱","verses":[{"n":1,"t":"耶和華啊，求你聽我的禱告，容我的呼求達到你面前！","notes":[]},{"n":2,"t":"我在急難的日子，求你向我側耳；不要向我掩面！我呼求的日子，求你快快應允我！","notes":[]},{"n":3,"t":"因為，我的年日如煙雲消滅；我的骨頭如火把燒著。","notes":[]},{"n":4,"t":"我的心被傷，如草枯乾，甚至我忘記吃飯。","notes":[]},{"n":5,"t":"因我唉哼的聲音，我的肉緊貼骨頭。","notes":[]},{"n":6,"t":"我如同曠野的鵜鶘；我好像荒場的鴞鳥。","notes":[]},{"n":7,"t":"我警醒不睡；我像房頂上孤單的麻雀。","notes":[]},{"n":8,"t":"我的仇敵終日辱罵我；向我猖狂的人指著我賭咒。","notes":[]},{"n":9,"t":"我吃過爐灰，如同吃飯；我所喝的與眼淚攙雜。","notes":[]},{"n":10,"t":"這都因你的惱恨和忿怒；你把我拾起來，又把我摔下去。","notes":[]},{"n":11,"t":"我的年日如日影偏斜；我也如草枯乾。","notes":[]},{"n":12,"t":"惟你－耶和華必存到永遠；你可記念的名也存到萬代。","notes":[]},{"n":13,"t":"你必起來憐恤錫安，因現在是可憐她的時候，日期已經到了。","notes":[]},{"n":14,"t":"你的僕人原來喜悅她的石頭，可憐她的塵土。","notes":[]},{"n":15,"t":"列國要敬畏耶和華的名；世上諸王都敬畏你的榮耀。","notes":[]},{"n":16,"t":"因為耶和華建造了錫安，在他榮耀裏顯現。","notes":[]},{"n":17,"t":"他垂聽窮人的禱告，並不藐視他們的祈求。","notes":[]},{"n":18,"t":"這必為後代的人記下，將來受造的民要讚美耶和華。","notes":[]},{"n":19,"t":"因為，他從至高的聖所垂看；耶和華從天向地觀察，","notes":[]},{"n":20,"t":"要垂聽被囚之人的歎息，要釋放將要死的人，","notes":[]},{"n":21,"t":"使人在錫安傳揚耶和華的名，在耶路撒冷傳揚讚美他的話，","notes":[]},{"n":22,"t":"就是在萬民和列國聚會事奉耶和華的時候。","notes":[]},{"n":23,"t":"他使我的力量中道衰弱，使我的年日短少。","notes":[]},{"n":24,"t":"我說：我的神啊，不要使我中年去世。你的年數世世無窮！","notes":[]},{"n":25,"t":"你起初立了地的根基；天也是你手所造的。","notes":[]},{"n":26,"t":"天地都要滅沒，你卻要長存；天地都要如外衣漸漸舊了。你要將天地如裏衣更換，天地就都改變了。","notes":[]},{"n":27,"t":"惟有你永不改變；你的年數沒有窮盡。","notes":[]},{"n":28,"t":"你僕人的子孫要長存；他們的後裔要堅立在你面前。","notes":[]}]},"103":{"heading":"耶和華的慈愛","verses":[{"n":1,"t":"我的心哪，你要稱頌耶和華！凡在我裏面的，也要稱頌他的聖名！","notes":[]},{"n":2,"t":"我的心哪，你要稱頌耶和華！不可忘記他的一切恩惠！","notes":[]},{"n":3,"t":"他赦免你的一切罪孽，醫治你的一切疾病。","notes":[]},{"n":4,"t":"他救贖你的命脫離死亡，以仁愛和慈悲為你的冠冕。","notes":[]},{"n":5,"t":"他用美物使你所願的得以知足，以致你如鷹返老還童。","notes":[]},{"n":6,"t":"耶和華施行公義，為一切受屈的人伸冤。","notes":[]},{"n":7,"t":"他使摩西知道他的法則，叫以色列人曉得他的作為。","notes":[]},{"n":8,"t":"耶和華有憐憫，有恩典，不輕易發怒，且有豐盛的慈愛。","notes":[]},{"n":9,"t":"他不長久責備，也不永遠懷怒。","notes":[]},{"n":10,"t":"他沒有按我們的罪過待我們，也沒有照我們的罪孽報應我們。","notes":[]},{"n":11,"t":"天離地何等的高，他的慈愛向敬畏他的人也是何等的大！","notes":[]},{"n":12,"t":"東離西有多遠，他叫我們的過犯離我們也有多遠！","notes":[]},{"n":13,"t":"父親怎樣憐恤他的兒女，耶和華也怎樣憐恤敬畏他的人！","notes":[]},{"n":14,"t":"因為他知道我們的本體，思念我們不過是塵土。","notes":[]},{"n":15,"t":"至於世人，他的年日如草一樣。他發旺如野地的花，","notes":[]},{"n":16,"t":"經風一吹，便歸無有；它的原處也不再認識它。","notes":[]},{"n":17,"t":"但耶和華的慈愛歸於敬畏他的人，從亙古到永遠；他的公義也歸於子子孫孫－","notes":[]},{"n":18,"t":"就是那些遵守他的約、記念他的訓詞而遵行的人。","notes":[]},{"n":19,"t":"耶和華在天上立定寶座；他的權柄統管萬有。","notes":["原文是國"]},{"n":20,"t":"聽從他命令、成全他旨意、有大能的天使，都要稱頌耶和華！","notes":[]},{"n":21,"t":"你們作他的諸軍，作他的僕役，行他所喜悅的，都要稱頌耶和華！","notes":[]},{"n":22,"t":"你們一切被他造的，在他所治理的各處，都要稱頌耶和華！我的心哪，你要稱頌耶和華！","notes":[]}]},"104":{"heading":"造化主頌","verses":[{"n":1,"t":"我的心哪，你要稱頌耶和華！耶和華－我的神啊，你為至大！你以尊榮威嚴為衣服，","notes":[]},{"n":2,"t":"披上亮光，如披外袍，鋪張穹蒼，如鋪幔子，","notes":[]},{"n":3,"t":"在水中立樓閣的棟樑，用雲彩為車輦，藉著風的翅膀而行，","notes":[]},{"n":4,"t":"以風為使者，以火焰為僕役，","notes":[]},{"n":5,"t":"將地立在根基上，使地永不動搖。","notes":[]},{"n":6,"t":"你用深水遮蓋地面，猶如衣裳；諸水高過山嶺。","notes":[]},{"n":7,"t":"你的斥責一發，水便奔逃；你的雷聲一發，水便奔流。","notes":[]},{"n":8,"t":"諸山升上，諸谷沉下，歸你為它所安定之地。","notes":["或譯：隨山上翻，隨谷下流"]},{"n":9,"t":"你定了界限，使水不能過去，不再轉回遮蓋地面。","notes":[]},{"n":10,"t":"耶和華使泉源湧在山谷，流在山間，","notes":[]},{"n":11,"t":"使野地的走獸有水喝，野驢得解其渴。","notes":[]},{"n":12,"t":"天上的飛鳥在水旁住宿，在樹枝上啼叫。","notes":[]},{"n":13,"t":"他從樓閣中澆灌山嶺；因他作為的功效，地就豐足。","notes":[]},{"n":14,"t":"他使草生長，給六畜吃，使菜蔬發長，供給人用，使人從地裏能得食物，","notes":[]},{"n":15,"t":"又得酒能悅人心，得油能潤人面，得糧能養人心。","notes":[]},{"n":16,"t":"佳美的樹木，就是黎巴嫩的香柏樹，是耶和華所栽種的，都滿了汁漿。","notes":[]},{"n":17,"t":"雀鳥在其上搭窩；至於鶴，松樹是牠的房屋。","notes":[]},{"n":18,"t":"高山為野山羊的住所；巖石為沙番的藏處。","notes":[]},{"n":19,"t":"你安置月亮為定節令；日頭自知沉落。","notes":[]},{"n":20,"t":"你造黑暗為夜，林中的百獸就都爬出來。","notes":[]},{"n":21,"t":"少壯獅子吼叫，要抓食，向神尋求食物。","notes":[]},{"n":22,"t":"日頭一出，獸便躲避，臥在洞裏。","notes":[]},{"n":23,"t":"人出去做工，勞碌直到晚上。","notes":[]},{"n":24,"t":"耶和華啊，你所造的何其多！都是你用智慧造成的；遍地滿了你的豐富。","notes":[]},{"n":25,"t":"那裏有海，又大又廣；其中有無數的動物，大小活物都有。","notes":[]},{"n":26,"t":"那裏有船行走，有你所造的鱷魚游泳在其中。","notes":[]},{"n":27,"t":"這都仰望你按時給牠食物。","notes":[]},{"n":28,"t":"你給牠們，牠們便拾起來；你張手，牠們飽得美食。","notes":[]},{"n":29,"t":"你掩面，牠們便驚惶；你收回牠們的氣，牠們就死亡，歸於塵土。","notes":[]},{"n":30,"t":"你發出你的靈，牠們便受造；你使地面更換為新。","notes":[]},{"n":31,"t":"願耶和華的榮耀存到永遠！願耶和華喜悅自己所造的！","notes":[]},{"n":32,"t":"他看地，地便震動；他摸山，山就冒煙。","notes":[]},{"n":33,"t":"我要一生向耶和華唱詩！我還活的時候，要向我神歌頌！","notes":[]},{"n":34,"t":"願他以我的默念為甘甜！我要因耶和華歡喜！","notes":[]},{"n":35,"t":"願罪人從世上消滅！願惡人歸於無有！我的心哪，要稱頌耶和華！你們要讚美耶和華！","notes":["原文是哈利路亞；下同"]}]},"105":{"heading":"神和他的子民","verses":[{"n":1,"t":"你們要稱謝耶和華， 求告他的名，在萬民中傳揚他的作為！","notes":[]},{"n":2,"t":"要向他唱詩歌頌，談論他一切奇妙的作為！","notes":[]},{"n":3,"t":"要以他的聖名誇耀！尋求耶和華的人，心中應當歡喜！","notes":[]},{"n":4,"t":"要尋求耶和華與他的能力，時常尋求他的面。","notes":[]},{"n":5,"t":"他僕人亞伯拉罕的後裔，他所揀選雅各的子孫哪，你們要記念他奇妙的作為和他的奇事，並他口中的判語。","notes":[],"end":6},{"n":7,"t":"他是耶和華－我們的神；全地都有他的判斷。","notes":[]},{"n":8,"t":"他記念他的約，直到永遠；他所吩咐的話，直到千代－","notes":[]},{"n":9,"t":"就是與亞伯拉罕所立的約，向以撒所起的誓。","notes":[]},{"n":10,"t":"他又將這約向雅各定為律例，向以色列定為永遠的約，","notes":[]},{"n":11,"t":"說：我必將迦南地賜給你，作你產業的分。","notes":[]},{"n":12,"t":"當時，他們人丁有限，數目稀少，並且在那地為寄居的。","notes":[]},{"n":13,"t":"他們從這邦遊到那邦，從這國行到那國。","notes":[]},{"n":14,"t":"他不容甚麼人欺負他們，為他們的緣故責備君王，","notes":[]},{"n":15,"t":"說：不可難為我受膏的人，也不可惡待我的先知。","notes":[]},{"n":16,"t":"他命饑荒降在那地上，將所倚靠的糧食全行斷絕，","notes":[]},{"n":17,"t":"在他們以先打發一個人去－約瑟被賣為奴僕。","notes":[]},{"n":18,"t":"人用腳鐐傷他的腳；他被鐵鍊捆拘。","notes":[]},{"n":19,"t":"耶和華的話試煉他，直等到他所說的應驗了。","notes":[]},{"n":20,"t":"王打發人把他解開，就是治理眾民的，把他釋放，","notes":[]},{"n":21,"t":"立他作王家之主，掌管他一切所有的，","notes":[]},{"n":22,"t":"使他隨意捆綁他的臣宰，將智慧教導他的長老。","notes":[]},{"n":23,"t":"以色列也到了埃及；雅各在含地寄居。","notes":[]},{"n":24,"t":"耶和華使他的百姓生養眾多，使他們比敵人強盛，","notes":[]},{"n":25,"t":"使敵人的心轉去恨他的百姓，並用詭計待他的僕人。","notes":[]},{"n":26,"t":"他打發他的僕人摩西和他所揀選的亞倫，","notes":[]},{"n":27,"t":"在敵人中間顯他的神蹟，在含地顯他的奇事。","notes":[]},{"n":28,"t":"他命黑暗，就有黑暗；沒有違背他話的。","notes":[]},{"n":29,"t":"他叫埃及的水變為血，叫他們的魚死了。","notes":[]},{"n":30,"t":"在他們的地上以及王宮的內室，青蛙多多滋生。","notes":[]},{"n":31,"t":"他說一聲，蒼蠅就成群而來，並有虱子進入他們四境。","notes":[]},{"n":32,"t":"他給他們降下冰雹為雨，在他們的地上降下火焰。","notes":[]},{"n":33,"t":"他也擊打他們的葡萄樹和無花果樹，毀壞他們境內的樹木。","notes":[]},{"n":34,"t":"他說一聲，就有蝗蟲螞蚱上來，不計其數，","notes":[]},{"n":35,"t":"吃盡了他們地上各樣的菜蔬和田地的出產。","notes":[]},{"n":36,"t":"他又擊殺他們國內一切的長子，就是他們強壯時頭生的。","notes":[]},{"n":37,"t":"他領自己的百姓帶銀子金子出來；他支派中沒有一個軟弱的。","notes":[]},{"n":38,"t":"他們出來的時候，埃及人便歡喜；原來埃及人懼怕他們。","notes":[]},{"n":39,"t":"他鋪張雲彩當遮蓋，夜間使火光照。","notes":[]},{"n":40,"t":"他們一求，他就使鵪鶉飛來，並用天上的糧食叫他們飽足。","notes":[]},{"n":41,"t":"他打開磐石，水就湧出；在乾旱之處，水流成河。","notes":[]},{"n":42,"t":"這都因他記念他的聖言和他的僕人亞伯拉罕。","notes":[]},{"n":43,"t":"他帶領百姓歡樂而出，帶領選民歡呼前往。","notes":[]},{"n":44,"t":"他將列國的地賜給他們，他們便承受眾民勞碌得來的，","notes":[]},{"n":45,"t":"好使他們遵他的律例，守他的律法。你們要讚美耶和華！","notes":[]}]},"106":{"heading":"神對他子民的良善","verses":[{"n":1,"t":"你們要讚美耶和華！要稱謝耶和華，因他本為善；他的慈愛永遠長存！","notes":[]},{"n":2,"t":"誰能傳說耶和華的大能？誰能表明他一切的美德？","notes":[]},{"n":3,"t":"凡遵守公平、常行公義的，這人便為有福！","notes":[]},{"n":4,"t":"耶和華啊，你用恩惠待你的百姓；求你也用這恩惠記念我，開你的救恩眷顧我，","notes":[]},{"n":5,"t":"使我見你選民的福，樂你國民的樂，與你的產業一同誇耀。","notes":[]},{"n":6,"t":"我們與我們的祖宗一同犯罪；我們作了孽，行了惡。","notes":[]},{"n":7,"t":"我們的祖宗在埃及不明白你的奇事，不記念你豐盛的慈愛，反倒在紅海行了悖逆。","notes":[]},{"n":8,"t":"然而，他因自己的名拯救他們，為要彰顯他的大能，","notes":[]},{"n":9,"t":"並且斥責紅海，海便乾了；他帶領他們經過深處，如同經過曠野。","notes":[]},{"n":10,"t":"他拯救他們脫離恨他們人的手，從仇敵手中救贖他們。","notes":[]},{"n":11,"t":"水淹沒他們的敵人，沒有一個存留。","notes":[]},{"n":12,"t":"那時，他們才信了他的話，歌唱讚美他。","notes":[]},{"n":13,"t":"等不多時，他們就忘了他的作為，不仰望他的指教，","notes":[]},{"n":14,"t":"反倒在曠野大起慾心，在荒地試探神。","notes":[]},{"n":15,"t":"他將他們所求的賜給他們，卻使他們的心靈軟弱。","notes":[]},{"n":16,"t":"他們又在營中嫉妒摩西和耶和華的聖者亞倫。","notes":[]},{"n":17,"t":"地裂開，吞下大坍，掩蓋亞比蘭一黨的人。","notes":[]},{"n":18,"t":"有火在他們的黨中發起；有火焰燒毀了惡人。","notes":[]},{"n":19,"t":"他們在何烈山造了牛犢，叩拜鑄成的像。","notes":[]},{"n":20,"t":"如此將他們榮耀的主換為吃草之牛的像，","notes":[]},{"n":21,"t":"忘了神－他們的救主；他曾在埃及行大事，","notes":[]},{"n":22,"t":"在含地行奇事，在紅海行可畏的事。","notes":[]},{"n":23,"t":"所以，他說要滅絕他們；若非有他所揀選的摩西站在當中，使他的忿怒轉消，恐怕他就滅絕他們。","notes":["原文是破口"]},{"n":24,"t":"他們又藐視那美地，不信他的話，","notes":[]},{"n":25,"t":"在自己帳棚內發怨言，不聽耶和華的聲音。","notes":[]},{"n":26,"t":"所以，他對他們起誓：必叫他們倒在曠野，","notes":[]},{"n":27,"t":"叫他們的後裔倒在列國之中，分散在各地。","notes":[]},{"n":28,"t":"他們又與巴力‧毗珥連合，且吃了祭死神的物。","notes":["或譯：人"]},{"n":29,"t":"他們這樣行，惹耶和華發怒，便有瘟疫流行在他們中間。","notes":[]},{"n":30,"t":"那時，非尼哈站起，刑罰惡人，瘟疫這才止息。","notes":[]},{"n":31,"t":"那就算為他的義，世世代代，直到永遠。","notes":[]},{"n":32,"t":"他們在米利巴水又叫耶和華發怒，甚至摩西也受了虧損，","notes":[]},{"n":33,"t":"是因他們惹動他的靈，摩西用嘴說了急躁的話。","notes":["原文是他"]},{"n":34,"t":"他們不照耶和華所吩咐的滅絕外邦人，","notes":[]},{"n":35,"t":"反與他們混雜相合，學習他們的行為，","notes":[]},{"n":36,"t":"事奉他們的偶像，這就成了自己的網羅，","notes":[]},{"n":37,"t":"把自己的兒女祭祀鬼魔，","notes":[]},{"n":38,"t":"流無辜人的血，就是自己兒女的血，把他們祭祀迦南的偶像，那地就被血污穢了。","notes":[]},{"n":39,"t":"這樣，他們被自己所做的污穢了，在行為上犯了邪淫。","notes":[]},{"n":40,"t":"所以，耶和華的怒氣向他的百姓發作，憎惡他的產業，","notes":[]},{"n":41,"t":"將他們交在外邦人的手裏；恨他們的人就轄制他們。","notes":[]},{"n":42,"t":"他們的仇敵也欺壓他們，他們就伏在敵人手下。","notes":[]},{"n":43,"t":"他屢次搭救他們，他們卻設謀背逆，因自己的罪孽降為卑下。","notes":[]},{"n":44,"t":"然而，他聽見他們哀告的時候，就眷顧他們的急難，","notes":[]},{"n":45,"t":"為他們記念他的約，照他豐盛的慈愛後悔。","notes":[]},{"n":46,"t":"他也使他們在凡擄掠他們的人面前蒙憐恤。","notes":[]},{"n":47,"t":"耶和華－我們的神啊，求你拯救我們，從外邦中招聚我們，我們好稱讚你的聖名，以讚美你為誇勝。","notes":[]},{"n":48,"t":"耶和華－以色列的神是應當稱頌的，從亙古直到永遠。願眾民都說：阿們！你們要讚美耶和華！","notes":[]}]},"107":{"heading":"頌讚神的良善","verses":[{"n":1,"t":"你們要稱謝耶和華，因他本為善；他的慈愛永遠長存！","notes":[]},{"n":2,"t":"願耶和華的贖民說這話，就是他從敵人手中所救贖的，","notes":[]},{"n":3,"t":"從各地，從東從西，從南從北，所招聚來的。","notes":[]},{"n":4,"t":"他們在曠野荒地漂流，尋不見可住的城邑，","notes":[]},{"n":5,"t":"又飢又渴，心裏發昏。","notes":[]},{"n":6,"t":"於是，他們在苦難中哀求耶和華；他從他們的禍患中搭救他們，","notes":[]},{"n":7,"t":"又領他們行走直路，使他們往可居住的城邑。","notes":[]},{"n":8,"t":"但願人因耶和華的慈愛和他向人所行的奇事都稱讚他；","notes":[]},{"n":9,"t":"因他使心裏渴慕的人得以知足，使心裏飢餓的人得飽美物。","notes":[]},{"n":10,"t":"那些坐在黑暗中、死蔭裏的人被困苦和鐵鍊捆鎖，","notes":[]},{"n":11,"t":"是因他們違背神的話語，藐視至高者的旨意。","notes":[]},{"n":12,"t":"所以，他用勞苦治服他們的心；他們仆倒，無人扶助。","notes":[]},{"n":13,"t":"於是，他們在苦難中哀求耶和華；他從他們的禍患中拯救他們。","notes":[]},{"n":14,"t":"他從黑暗中和死蔭裏領他們出來，折斷他們的綁索。","notes":[]},{"n":15,"t":"但願人因耶和華的慈愛和他向人所行的奇事都稱讚他；","notes":[]},{"n":16,"t":"因為他打破了銅門，砍斷了鐵閂。","notes":[]},{"n":17,"t":"愚妄人因自己的過犯和自己的罪孽便受苦楚。","notes":[]},{"n":18,"t":"他們心裏厭惡各樣的食物，就臨近死門。","notes":[]},{"n":19,"t":"於是，他們在苦難中哀求耶和華；他從他們的禍患中拯救他們。","notes":[]},{"n":20,"t":"他發命醫治他們，救他們脫離死亡。","notes":[]},{"n":21,"t":"但願人因耶和華的慈愛和他向人所行的奇事都稱讚他。","notes":[]},{"n":22,"t":"願他們以感謝為祭獻給他，歡呼述說他的作為！","notes":[]},{"n":23,"t":"在海上坐船，在大水中經理事務的，","notes":[]},{"n":24,"t":"他們看見耶和華的作為，並他在深水中的奇事。","notes":[]},{"n":25,"t":"因他一吩咐，狂風就起來，海中的波浪也揚起。","notes":[]},{"n":26,"t":"他們上到天空，下到海底；他們的心因患難便消化。","notes":[]},{"n":27,"t":"他們搖搖晃晃，東倒西歪，好像醉酒的人；他們的智慧無法可施。","notes":[]},{"n":28,"t":"於是，他們在苦難中哀求耶和華，他從他們的禍患中領出他們來。","notes":[]},{"n":29,"t":"他使狂風止息，波浪就平靜。","notes":[]},{"n":30,"t":"風息浪靜，他們便歡喜；他就引他們到所願去的海口。","notes":[]},{"n":31,"t":"但願人因耶和華的慈愛和他向人所行的奇事都稱讚他。","notes":[]},{"n":32,"t":"願他們在民的會中尊崇他，在長老的位上讚美他！","notes":[]},{"n":33,"t":"他使江河變為曠野，叫水泉變為乾渴之地，","notes":[]},{"n":34,"t":"使肥地變為鹼地；這都因其間居民的罪惡。","notes":[]},{"n":35,"t":"他使曠野變為水潭，叫旱地變為水泉。","notes":[]},{"n":36,"t":"他使飢餓的人住在那裏，好建造可住的城邑，","notes":[]},{"n":37,"t":"又種田地，栽葡萄園，得享所出的土產。","notes":[]},{"n":38,"t":"他又賜福給他們，叫他們生養眾多，也不叫他們的牲畜減少。","notes":[]},{"n":39,"t":"他們又因暴虐、患難、愁苦，就減少且卑下。","notes":[]},{"n":40,"t":"他使君王蒙羞被辱，使他們在荒廢無路之地漂流。","notes":[]},{"n":41,"t":"他卻將窮乏人安置在高處，脫離苦難，使他的家屬多如羊群。","notes":[]},{"n":42,"t":"正直人看見就歡喜；罪孽之輩必塞口無言。","notes":[]},{"n":43,"t":"凡有智慧的，必在這些事上留心，也必思想耶和華的慈愛。","notes":[]}]},"108":{"heading":"抗敵求助","verses":[{"n":1,"t":"神啊，我心堅定；我口要唱詩歌頌！","notes":["原文是榮耀"]},{"n":2,"t":"琴瑟啊，你們當醒起！我自己要極早醒起！","notes":[]},{"n":3,"t":"耶和華啊，我要在萬民中稱謝你，在列邦中歌頌你！","notes":[]},{"n":4,"t":"因為，你的慈愛大過諸天；你的誠實達到穹蒼。","notes":[]},{"n":5,"t":"神啊，願你崇高過於諸天！願你的榮耀高過全地！","notes":[]},{"n":6,"t":"求你應允我們，用右手拯救我們，好叫你所親愛的人得救。","notes":[]},{"n":7,"t":"神已經指著他的聖潔說：我要歡樂；我要分開示劍，丈量疏割谷。","notes":["說：或譯應許我"]},{"n":8,"t":"基列是我的；瑪拿西是我的；以法蓮是護衛我頭的；猶大是我的杖；","notes":[]},{"n":9,"t":"摩押是我的沐浴盆；我要向以東拋鞋；我必因勝非利士呼喊。","notes":[]},{"n":10,"t":"誰能領我進堅固城？誰能引我到以東地？","notes":[]},{"n":11,"t":"神啊，你不是丟棄了我們嗎？神啊，你不和我們的軍兵同去嗎？","notes":[]},{"n":12,"t":"求你幫助我們攻擊敵人，因為人的幫助是枉然的。","notes":[]},{"n":13,"t":"我們倚靠神才得施展大能，因為踐踏我們敵人的就是他。","notes":[]}]},"109":{"heading":"遭難者的苦訴","verses":[{"n":1,"t":"我所讚美的神啊，求你不要閉口不言。","notes":[]},{"n":2,"t":"因為惡人的嘴和詭詐人的口已經張開攻擊我；他們用撒謊的舌頭對我說話。","notes":[]},{"n":3,"t":"他們圍繞我，說怨恨的話，又無故地攻打我。","notes":[]},{"n":4,"t":"他們與我為敵以報我愛，但我專心祈禱。","notes":[]},{"n":5,"t":"他們向我以惡報善，以恨報愛。","notes":[]},{"n":6,"t":"願你派一個惡人轄制他，派一個對頭站在他右邊！","notes":[]},{"n":7,"t":"他受審判的時候，願他出來擔當罪名！願他的祈禱反成為罪！","notes":[]},{"n":8,"t":"願他的年日短少！願別人得他的職分！","notes":[]},{"n":9,"t":"願他的兒女為孤兒，他的妻子為寡婦！","notes":[]},{"n":10,"t":"願他的兒女漂流討飯，從他們荒涼之處出來求食！","notes":[]},{"n":11,"t":"願強暴的債主牢籠他一切所有的！願外人搶他勞碌得來的！","notes":[]},{"n":12,"t":"願無人向他延綿施恩！願無人可憐他的孤兒！","notes":[]},{"n":13,"t":"願他的後人斷絕，名字被塗抹，不傳於下代！","notes":[]},{"n":14,"t":"願他祖宗的罪孽被耶和華記念！願他母親的罪過不被塗抹！","notes":[]},{"n":15,"t":"願這些罪常在耶和華面前，使他的名號斷絕於世！","notes":[]},{"n":16,"t":"因為他不想施恩，卻逼迫困苦窮乏的和傷心的人，要把他們治死。","notes":[]},{"n":17,"t":"他愛咒罵，咒罵就臨到他；他不喜愛福樂，福樂就與他遠離！","notes":[]},{"n":18,"t":"他拿咒罵當衣服穿上；這咒罵就如水進他裏面，像油入他的骨頭。","notes":[]},{"n":19,"t":"願這咒罵當他遮身的衣服，當他常束的腰帶！","notes":[]},{"n":20,"t":"這就是我對頭和用惡言議論我的人從耶和華那裏所受的報應。","notes":[]},{"n":21,"t":"主－耶和華啊，求你為你的名恩待我；因你的慈愛美好，求你搭救我！","notes":[]},{"n":22,"t":"因為我困苦窮乏，內心受傷。","notes":[]},{"n":23,"t":"我如日影漸漸偏斜而去；我如蝗蟲被抖出來。","notes":[]},{"n":24,"t":"我因禁食，膝骨軟弱；我身上的肉也漸漸瘦了。","notes":[]},{"n":25,"t":"我受他們的羞辱，他們看見我便搖頭。","notes":[]},{"n":26,"t":"耶和華－我的神啊，求你幫助我，照你的慈愛拯救我，","notes":[]},{"n":27,"t":"使他們知道這是你的手，是你－耶和華所行的事。","notes":[]},{"n":28,"t":"任憑他們咒罵，惟願你賜福；他們幾時起來就必蒙羞，你的僕人卻要歡喜。","notes":[]},{"n":29,"t":"願我的對頭披戴羞辱！願他們以自己的羞愧為外袍遮身！","notes":[]},{"n":30,"t":"我要用口極力稱謝耶和華；我要在眾人中間讚美他；","notes":[]},{"n":31,"t":"因為他必站在窮乏人的右邊，要救他脫離審判他靈魂的人。","notes":[]}]},"110":{"heading":"耶和華及其所選之王","verses":[{"n":1,"t":"耶和華對我主說：你坐在我的右邊，等我使你仇敵作你的腳凳。","notes":[]},{"n":2,"t":"耶和華必使你從錫安伸出能力的杖來；你要在你仇敵中掌權。","notes":[]},{"n":3,"t":"當你掌權的日子，你的民要以聖潔的妝飾為衣，甘心犧牲自己；你的民多如清晨的甘露。","notes":["或譯：行軍的日子","或譯：以聖潔為妝飾","或譯：你少年時光耀如清晨的甘露"]},{"n":4,"t":"耶和華起了誓，決不後悔，說：你是照著麥基洗德的等次永遠為祭司。","notes":[]},{"n":5,"t":"在你右邊的主，當他發怒的日子，必打傷列王。","notes":[]},{"n":6,"t":"他要在列邦中刑罰惡人，屍首就遍滿各處；他要在許多國中打破仇敵的頭。","notes":[]},{"n":7,"t":"他要喝路旁的河水，因此必抬起頭來。","notes":[]}]},"111":{"heading":"讚美耶和華","verses":[{"n":1,"t":"你們要讚美耶和華！我要在正直人的大會中，並公會中，一心稱謝耶和華。","notes":[]},{"n":2,"t":"耶和華的作為本為大；凡喜愛的都必考察。","notes":[]},{"n":3,"t":"他所行的是尊榮和威嚴；他的公義存到永遠。","notes":[]},{"n":4,"t":"他行了奇事，使人記念；耶和華有恩惠，有憐憫。","notes":[]},{"n":5,"t":"他賜糧食給敬畏他的人；他必永遠記念他的約。","notes":[]},{"n":6,"t":"他向百姓顯出大能的作為，把外邦的地賜給他們為業。","notes":[]},{"n":7,"t":"他手所行的是誠實公平；他的訓詞都是確實的，","notes":[]},{"n":8,"t":"是永永遠遠堅定的，是按誠實正直設立的。","notes":[]},{"n":9,"t":"他向百姓施行救贖，命定他的約，直到永遠；他的名聖而可畏。","notes":[]},{"n":10,"t":"敬畏耶和華是智慧的開端；凡遵行他命令的是聰明人。耶和華是永遠當讚美的！","notes":[]}]},"112":{"heading":"義人之福","verses":[{"n":1,"t":"你們要讚美耶和華！敬畏耶和華，甚喜愛他命令的，這人便為有福！","notes":[]},{"n":2,"t":"他的後裔在世必強盛；正直人的後代必要蒙福。","notes":[]},{"n":3,"t":"他家中有貨物，有錢財；他的公義存到永遠。","notes":[]},{"n":4,"t":"正直人在黑暗中，有光向他發現；他有恩惠，有憐憫，有公義。","notes":[]},{"n":5,"t":"施恩與人、借貸與人的，這人事情順利；他被審判的時候要訴明自己的冤。","notes":[]},{"n":6,"t":"他永不動搖；義人被記念，直到永遠。","notes":[]},{"n":7,"t":"他必不怕凶惡的信息；他心堅定，倚靠耶和華。","notes":[]},{"n":8,"t":"他心確定，總不懼怕，直到他看見敵人遭報。","notes":[]},{"n":9,"t":"他施捨錢財，賙濟貧窮；他的仁義存到永遠。他的角必被高舉，大有榮耀。","notes":[]},{"n":10,"t":"惡人看見便惱恨，必咬牙而消化；惡人的心願要歸滅絕。","notes":[]}]},"113":{"heading":"讚美耶和華的良善","verses":[{"n":1,"t":"你們要讚美耶和華！耶和華的僕人哪，你們要讚美，讚美耶和華的名！","notes":[]},{"n":2,"t":"耶和華的名是應當稱頌的，從今時直到永遠！","notes":[]},{"n":3,"t":"從日出之地到日落之處，耶和華的名是應當讚美的！","notes":[]},{"n":4,"t":"耶和華超乎萬民之上；他的榮耀高過諸天。","notes":[]},{"n":5,"t":"誰像耶和華－我們的神呢？他坐在至高之處，","notes":[]},{"n":6,"t":"自己謙卑，觀看天上地下的事。","notes":[]},{"n":7,"t":"他從灰塵裏抬舉貧寒人，從糞堆中提拔窮乏人，","notes":[]},{"n":8,"t":"使他們與王子同坐，就是與本國的王子同坐。","notes":[]},{"n":9,"t":"他使不能生育的婦人安居家中，為多子的樂母。你們要讚美耶和華！","notes":[]}]},"114":{"heading":"逾越節之歌","verses":[{"n":1,"t":"以色列出了埃及，雅各家離開說異言之民；","notes":[]},{"n":2,"t":"那時，猶大為主的聖所，以色列為他所治理的國度。","notes":[]},{"n":3,"t":"滄海看見就奔逃；約旦河也倒流。","notes":[]},{"n":4,"t":"大山踴躍，如公羊；小山跳舞，如羊羔。","notes":[]},{"n":5,"t":"滄海啊，你為何奔逃？約旦哪，你為何倒流？","notes":[]},{"n":6,"t":"大山哪，你為何踴躍，如公羊？小山哪，你為何跳舞，如羊羔？","notes":[]},{"n":7,"t":"大地啊，你因見主的面，就是雅各神的面，便要震動。","notes":[]},{"n":8,"t":"他叫磐石變為水池，叫堅石變為泉源。","notes":[]}]},"115":{"heading":"獨一真神","verses":[{"n":1,"t":"耶和華啊，榮耀不要歸與我們，不要歸與我們；要因你的慈愛和誠實歸在你的名下！","notes":[]},{"n":2,"t":"為何容外邦人說：他們的神在哪裏呢？","notes":[]},{"n":3,"t":"然而，我們的神在天上，都隨自己的意旨行事。","notes":[]},{"n":4,"t":"他們的偶像是金的，銀的，是人手所造的，","notes":[]},{"n":5,"t":"有口卻不能言，有眼卻不能看，","notes":[]},{"n":6,"t":"有耳卻不能聽，有鼻卻不能聞，","notes":[]},{"n":7,"t":"有手卻不能摸，有腳卻不能走，有喉嚨也不能出聲。","notes":[]},{"n":8,"t":"造他的要和他一樣；凡靠他的也要如此。","notes":[]},{"n":9,"t":"以色列啊，你要倚靠耶和華！他是你的幫助和你的盾牌。","notes":[]},{"n":10,"t":"亞倫家啊，你們要倚靠耶和華！他是你們的幫助和你們的盾牌。","notes":[]},{"n":11,"t":"你們敬畏耶和華的，要倚靠耶和華！他是你們的幫助和你們的盾牌。","notes":[]},{"n":12,"t":"耶和華向來眷念我們；他還要賜福給我們：要賜福給以色列的家，賜福給亞倫的家。","notes":[]},{"n":13,"t":"凡敬畏耶和華的，無論大小，主必賜福給他。","notes":[]},{"n":14,"t":"願耶和華叫你們和你們的子孫日見加增。","notes":[]},{"n":15,"t":"你們蒙了造天地之耶和華的福！","notes":[]},{"n":16,"t":"天，是耶和華的天；地，他卻給了世人。","notes":[]},{"n":17,"t":"死人不能讚美耶和華；下到寂靜中的也都不能。","notes":[]},{"n":18,"t":"但我們要稱頌耶和華，從今時直到永遠。你們要讚美耶和華！","notes":[]}]},"116":{"heading":"為出死入生而讚美神","verses":[{"n":1,"t":"我愛耶和華，因為他聽了我的聲音和我的懇求。","notes":[]},{"n":2,"t":"他既向我側耳，我一生要求告他。","notes":[]},{"n":3,"t":"死亡的繩索纏繞我；陰間的痛苦抓住我；我遭遇患難愁苦。","notes":[]},{"n":4,"t":"那時，我便求告耶和華的名，說：耶和華啊，求你救我的靈魂！","notes":[]},{"n":5,"t":"耶和華有恩惠，有公義；我們的神以憐憫為懷。","notes":[]},{"n":6,"t":"耶和華保護愚人；我落到卑微的地步，他救了我。","notes":[]},{"n":7,"t":"我的心哪！你要仍歸安樂，因為耶和華用厚恩待你。","notes":[]},{"n":8,"t":"主啊，你救我的命免了死亡，救我的眼免了流淚，救我的腳免了跌倒。","notes":[]},{"n":9,"t":"我要在耶和華面前行活人之路。","notes":[]},{"n":10,"t":"我因信，所以如此說話；我受了極大的困苦。","notes":[]},{"n":11,"t":"我曾急促地說：人都是說謊的！","notes":[]},{"n":12,"t":"我拿甚麼報答耶和華向我所賜的一切厚恩？","notes":[]},{"n":13,"t":"我要舉起救恩的杯，稱揚耶和華的名。","notes":[]},{"n":14,"t":"我要在他眾民面前向耶和華還我的願。","notes":[]},{"n":15,"t":"在耶和華眼中，看聖民之死極為寶貴。","notes":[]},{"n":16,"t":"耶和華啊，我真是你的僕人；我是你的僕人，是你婢女的兒子。你已經解開我的綁索。","notes":[]},{"n":17,"t":"我要以感謝為祭獻給你，又要求告耶和華的名。","notes":[]},{"n":18,"t":"我要在他眾民面前，在耶和華殿的院內，在耶路撒冷當中，向耶和華還我的願。你們要讚美耶和華！","notes":[],"end":19}]},"117":{"heading":"讚美耶和華","verses":[{"n":1,"t":"萬國啊，你們都當讚美耶和華！萬民哪，你們都當頌讚他！","notes":[]},{"n":2,"t":"因為他向我們大施慈愛；耶和華的誠實存到永遠。你們要讚美耶和華！","notes":[]}]},"118":{"heading":"因勝利而稱謝耶和華","verses":[{"n":1,"t":"你們要稱謝耶和華，因他本為善；他的慈愛永遠長存！","notes":[]},{"n":2,"t":"願以色列說：他的慈愛永遠長存！","notes":[]},{"n":3,"t":"願亞倫的家說：他的慈愛永遠長存！","notes":[]},{"n":4,"t":"願敬畏耶和華的說：他的慈愛永遠長存！","notes":[]},{"n":5,"t":"我在急難中求告耶和華，他就應允我，把我安置在寬闊之地。","notes":[]},{"n":6,"t":"有耶和華幫助我，我必不懼怕，人能把我怎麼樣呢？","notes":[]},{"n":7,"t":"在那幫助我的人中，有耶和華幫助我，所以我要看見那恨我的人遭報。","notes":[]},{"n":8,"t":"投靠耶和華，強似倚賴人；","notes":[]},{"n":9,"t":"投靠耶和華，強似倚賴王子。","notes":[]},{"n":10,"t":"萬民圍繞我，我靠耶和華的名必剿滅他們。","notes":[]},{"n":11,"t":"他們環繞我，圍困我，我靠耶和華的名必剿滅他們。","notes":[]},{"n":12,"t":"他們如同蜂子圍繞我，好像燒荊棘的火，必被熄滅；我靠耶和華的名，必剿滅他們。","notes":[]},{"n":13,"t":"你推我，要叫我跌倒，但耶和華幫助了我。","notes":[]},{"n":14,"t":"耶和華是我的力量，是我的詩歌；他也成了我的拯救。","notes":[]},{"n":15,"t":"在義人的帳棚裏，有歡呼拯救的聲音；耶和華的右手施展大能。","notes":[]},{"n":16,"t":"耶和華的右手高舉；耶和華的右手施展大能。","notes":[]},{"n":17,"t":"我必不致死，仍要存活，並要傳揚耶和華的作為。","notes":[]},{"n":18,"t":"耶和華雖嚴嚴地懲治我，卻未曾將我交於死亡。","notes":[]},{"n":19,"t":"給我敞開義門；我要進去稱謝耶和華！","notes":[]},{"n":20,"t":"這是耶和華的門；義人要進去！","notes":[]},{"n":21,"t":"我要稱謝你，因為你已經應允我，又成了我的拯救！","notes":[]},{"n":22,"t":"匠人所棄的石頭已成了房角的頭塊石頭。","notes":[]},{"n":23,"t":"這是耶和華所做的，在我們眼中看為希奇。","notes":[]},{"n":24,"t":"這是耶和華所定的日子，我們在其中要高興歡喜！","notes":[]},{"n":25,"t":"耶和華啊，求你拯救！耶和華啊，求你使我們亨通！","notes":[]},{"n":26,"t":"奉耶和華名來的是應當稱頌的！我們從耶和華的殿中為你們祝福！","notes":[]},{"n":27,"t":"耶和華是神；他光照了我們。理當用繩索把祭牲拴住，牽到壇角那裏。","notes":[]},{"n":28,"t":"你是我的神，我要稱謝你！你是我的神，我要尊崇你！","notes":[]},{"n":29,"t":"你們要稱謝耶和華，因他本為善；他的慈愛永遠長存！","notes":[]}]},"119":{"heading":"耶和華的律法","verses":[{"n":1,"t":"行為完全、遵行耶和華律法的，這人便為有福！","notes":[]},{"n":2,"t":"遵守他的法度、一心尋求他的，這人便為有福！","notes":[]},{"n":3,"t":"這人不做非義的事，但遵行他的道。","notes":[]},{"n":4,"t":"耶和華啊，你曾將你的訓詞吩咐我們，為要我們殷勤遵守。","notes":[]},{"n":5,"t":"但願我行事堅定，得以遵守你的律例。","notes":[]},{"n":6,"t":"我看重你的一切命令，就不至於羞愧。","notes":[]},{"n":7,"t":"我學了你公義的判語，就要以正直的心稱謝你。","notes":[]},{"n":8,"t":"我必守你的律例；求你總不要丟棄我！","notes":[]},{"n":9,"t":"少年人用甚麼潔淨他的行為呢？是要遵行你的話！","notes":[],"heads":["順從耶和華的律法"]},{"n":10,"t":"我一心尋求了你；求你不要叫我偏離你的命令。","notes":[]},{"n":11,"t":"我將你的話藏在心裏，免得我得罪你。","notes":[]},{"n":12,"t":"耶和華啊，你是應當稱頌的！求你將你的律例教訓我！","notes":[]},{"n":13,"t":"我用嘴唇傳揚你口中的一切典章。","notes":[]},{"n":14,"t":"我喜悅你的法度，如同喜悅一切的財物。","notes":[]},{"n":15,"t":"我要默想你的訓詞，看重你的道路。","notes":[]},{"n":16,"t":"我要在你的律例中自樂；我不忘記你的話。","notes":[]},{"n":17,"t":"求你用厚恩待你的僕人，使我存活，我就遵守你的話。","notes":[],"heads":["因耶和華律法而蒙福"]},{"n":18,"t":"求你開我的眼睛，使我看出你律法中的奇妙。","notes":[]},{"n":19,"t":"我是在地上作寄居的；求你不要向我隱瞞你的命令！","notes":[]},{"n":20,"t":"我時常切慕你的典章，甚至心碎。","notes":[]},{"n":21,"t":"受咒詛、偏離你命令的驕傲人，你已經責備他們。","notes":[]},{"n":22,"t":"求你除掉我所受的羞辱和藐視，因我遵守你的法度。","notes":[]},{"n":23,"t":"雖有首領坐著妄論我，你僕人卻思想你的律例。","notes":[]},{"n":24,"t":"你的法度是我所喜樂的，是我的謀士。","notes":[]},{"n":25,"t":"我的性命幾乎歸於塵土；求你照你的話將我救活！","notes":[],"heads":["決定遵行耶和華的律法"]},{"n":26,"t":"我述說我所行的，你應允了我；求你將你的律例教訓我！","notes":[]},{"n":27,"t":"求你使我明白你的訓詞，我就思想你的奇事。","notes":[]},{"n":28,"t":"我的心因愁苦而消化；求你照你的話使我堅立！","notes":[]},{"n":29,"t":"求你使我離開奸詐的道，開恩將你的律法賜給我！","notes":[]},{"n":30,"t":"我揀選了忠信的道，將你的典章擺在我面前。","notes":[]},{"n":31,"t":"我持守你的法度；耶和華啊，求你不要叫我羞愧！","notes":[]},{"n":32,"t":"你開廣我心的時候，我就往你命令的道上直奔。","notes":[]},{"n":33,"t":"耶和華啊，求你將你的律例指教我，我必遵守到底！","notes":[],"heads":["求主賜悟性"]},{"n":34,"t":"求你賜我悟性，我便遵守你的律法，且要一心遵守。","notes":[]},{"n":35,"t":"求你叫我遵行你的命令，因為這是我所喜樂的。","notes":[]},{"n":36,"t":"求你使我的心趨向你的法度，不趨向非義之財。","notes":[]},{"n":37,"t":"求你叫我轉眼不看虛假，又叫我在你的道中生活。","notes":[]},{"n":38,"t":"你向敬畏你的人所應許的話，求你向僕人堅定！","notes":[]},{"n":39,"t":"求你使我所怕的羞辱遠離我，因你的典章本為美。","notes":[]},{"n":40,"t":"我羨慕你的訓詞；求你使我在你的公義上生活！","notes":[]},{"n":41,"t":"耶和華啊，願你照你的話，使你的慈愛，就是你的救恩，臨到我身上，","notes":[],"heads":["倚靠耶和華的律法"]},{"n":42,"t":"我就有話回答那羞辱我的，因我倚靠你的話。","notes":[]},{"n":43,"t":"求你叫真理的話總不離開我口，因我仰望你的典章。","notes":[]},{"n":44,"t":"我要常守你的律法，直到永永遠遠。","notes":[]},{"n":45,"t":"我要自由而行，因我素來考究你的訓詞。","notes":["或譯：我要行在寬闊之地"]},{"n":46,"t":"我也要在君王面前論說你的法度，並不至於羞愧。","notes":[]},{"n":47,"t":"我要在你的命令中自樂；這命令素來是我所愛的。","notes":[]},{"n":48,"t":"我又要遵行你的命令，這命令素來是我所愛的；我也要思想你的律例。","notes":["原文是舉手"]},{"n":49,"t":"求你記念向你僕人所應許的話，叫我有盼望。","notes":[],"heads":["因耶和華的律法而安穩"]},{"n":50,"t":"這話將我救活了；我在患難中，因此得安慰。","notes":[]},{"n":51,"t":"驕傲的人甚侮慢我，我卻未曾偏離你的律法。","notes":[]},{"n":52,"t":"耶和華啊，我記念你從古以來的典章，就得了安慰。","notes":[]},{"n":53,"t":"我見惡人離棄你的律法，就怒氣發作，猶如火燒。","notes":[]},{"n":54,"t":"我在世寄居，素來以你的律例為詩歌。","notes":[]},{"n":55,"t":"耶和華啊，我夜間記念你的名，遵守你的律法。","notes":[]},{"n":56,"t":"我所以如此，是因我守你的訓詞。","notes":[]},{"n":57,"t":"耶和華是我的福分；我曾說，我要遵守你的言語。","notes":[],"heads":["深愛耶和華的律法"]},{"n":58,"t":"我一心求過你的恩；願你照你的話憐憫我！","notes":[]},{"n":59,"t":"我思想我所行的道，就轉步歸向你的法度。","notes":[]},{"n":60,"t":"我急忙遵守你的命令，並不遲延。","notes":[]},{"n":61,"t":"惡人的繩索纏繞我，我卻沒有忘記你的律法。","notes":[]},{"n":62,"t":"我因你公義的典章，半夜必起來稱謝你。","notes":[]},{"n":63,"t":"凡敬畏你、守你訓詞的人，我都與他作伴。","notes":[]},{"n":64,"t":"耶和華啊，你的慈愛遍滿大地；求你將你的律例教訓我！","notes":[]},{"n":65,"t":"耶和華啊，你向來是照你的話善待僕人。","notes":[],"heads":["耶和華律法的寶貴"]},{"n":66,"t":"求你將精明和知識賜給我，因我信了你的命令。","notes":[]},{"n":67,"t":"我未受苦以先走迷了路，現在卻遵守你的話。","notes":[]},{"n":68,"t":"你本為善，所行的也善；求你將你的律例教訓我！","notes":[]},{"n":69,"t":"驕傲人編造謊言攻擊我，我卻要一心守你的訓詞。","notes":[]},{"n":70,"t":"他們心蒙脂油，我卻喜愛你的律法。","notes":[]},{"n":71,"t":"我受苦是與我有益，為要使我學習你的律例。","notes":[]},{"n":72,"t":"你口中的訓言與我有益，勝於千萬的金銀。","notes":["或譯：律法"]},{"n":73,"t":"你的手製造我，建立我；求你賜我悟性，可以學習你的命令！","notes":[],"heads":["耶和華律法的公正"]},{"n":74,"t":"敬畏你的人見我就要歡喜，因我仰望你的話。","notes":[]},{"n":75,"t":"耶和華啊，我知道你的判語是公義的；你使我受苦是以誠實待我。","notes":[]},{"n":76,"t":"求你照著應許僕人的話，以慈愛安慰我。","notes":[]},{"n":77,"t":"願你的慈悲臨到我，使我存活，因你的律法是我所喜愛的。","notes":[]},{"n":78,"t":"願驕傲人蒙羞，因為他們無理地傾覆我；但我要思想你的訓詞。","notes":[]},{"n":79,"t":"願敬畏你的人歸向我，他們就知道你的法度。","notes":[]},{"n":80,"t":"願我的心在你的律例上完全，使我不致蒙羞。","notes":[]},{"n":81,"t":"我心渴想你的救恩，仰望你的應許。","notes":[],"heads":["求主解救"]},{"n":82,"t":"我因盼望你的應許眼睛失明，說：你何時安慰我？","notes":[]},{"n":83,"t":"我好像煙薰的皮袋，卻不忘記你的律例。","notes":[]},{"n":84,"t":"你僕人的年日有多少呢？你幾時向逼迫我的人施行審判呢？","notes":[]},{"n":85,"t":"不從你律法的驕傲人為我掘了坑。","notes":[]},{"n":86,"t":"你的命令盡都誠實；他們無理地逼迫我，求你幫助我！","notes":[]},{"n":87,"t":"他們幾乎把我從世上滅絕，但我沒有離棄你的訓詞。","notes":[]},{"n":88,"t":"求你照你的慈愛將我救活，我就遵守你口中的法度。","notes":[]},{"n":89,"t":"耶和華啊，你的話安定在天，直到永遠。","notes":[],"heads":["信賴耶和華的律法"]},{"n":90,"t":"你的誠實存到萬代；你堅定了地，地就長存。","notes":[]},{"n":91,"t":"天地照你的安排存到今日；萬物都是你的僕役。","notes":[]},{"n":92,"t":"我若不是喜愛你的律法，早就在苦難中滅絕了！","notes":[]},{"n":93,"t":"我永不忘記你的訓詞，因你用這訓詞將我救活了。","notes":[]},{"n":94,"t":"我是屬你的，求你救我，因我尋求了你的訓詞。","notes":[]},{"n":95,"t":"惡人等待我，要滅絕我，我卻要揣摩你的法度。","notes":[]},{"n":96,"t":"我看萬事盡都有限，惟有你的命令極其寬廣。","notes":[]},{"n":97,"t":"我何等愛慕你的律法，終日不住地思想。","notes":[],"heads":["喜愛耶和華的律法"]},{"n":98,"t":"你的命令常存在我心裏，使我比仇敵有智慧。","notes":[]},{"n":99,"t":"我比我的師傅更通達，因我思想你的法度。","notes":[]},{"n":100,"t":"我比年老的更明白，因我守了你的訓詞。","notes":[]},{"n":101,"t":"我禁止我腳走一切的邪路，為要遵守你的話。","notes":[]},{"n":102,"t":"我沒有偏離你的典章，因為你教訓了我。","notes":[]},{"n":103,"t":"你的言語在我上膛何等甘美，在我口中比蜜更甜！","notes":[]},{"n":104,"t":"我藉著你的訓詞得以明白，所以我恨一切的假道。","notes":[]},{"n":105,"t":"你的話是我腳前的燈，是我路上的光。","notes":[],"heads":["耶和華律法的亮光"]},{"n":106,"t":"你公義的典章，我曾起誓遵守，我必按誓而行。","notes":[]},{"n":107,"t":"我甚是受苦；耶和華啊，求你照你的話將我救活！","notes":[]},{"n":108,"t":"耶和華啊，求你悅納我口中的讚美為供物，又將你的典章教訓我！","notes":[]},{"n":109,"t":"我的性命常在危險之中，我卻不忘記你的律法。","notes":[]},{"n":110,"t":"惡人為我設下網羅，我卻沒有偏離你的訓詞。","notes":[]},{"n":111,"t":"我以你的法度為永遠的產業，因這是我心中所喜愛的。","notes":[]},{"n":112,"t":"我的心專向你的律例，永遠遵行，一直到底。","notes":[]},{"n":113,"t":"心懷二意的人為我所恨；但你的律法為我所愛。","notes":[],"heads":["因耶和華律法得安全"]},{"n":114,"t":"你是我藏身之處，又是我的盾牌；我甚仰望你的話語。","notes":[]},{"n":115,"t":"作惡的人哪，你們離開我吧！我好遵守我神的命令。","notes":[]},{"n":116,"t":"求你照你的話扶持我，使我存活，也不叫我因失望而害羞。","notes":[]},{"n":117,"t":"求你扶持我，我便得救，時常看重你的律例。","notes":[]},{"n":118,"t":"凡偏離你律例的人，你都輕棄他們，因為他們的詭詐必歸虛空。","notes":[]},{"n":119,"t":"凡地上的惡人，你除掉他，好像除掉渣滓；因此我愛你的法度。","notes":[]},{"n":120,"t":"我因懼怕你，肉就發抖；我也怕你的判語。","notes":[]},{"n":121,"t":"我行過公平和公義，求你不要撇下我給欺壓我的人！","notes":[],"heads":["遵從耶和華的律法"]},{"n":122,"t":"求你為僕人作保，使我得好處，不容驕傲人欺壓我！","notes":[]},{"n":123,"t":"我因盼望你的救恩和你公義的話眼睛失明。","notes":[]},{"n":124,"t":"求你照你的慈愛待僕人，將你的律例教訓我。","notes":[]},{"n":125,"t":"我是你的僕人，求你賜我悟性，使我得知你的法度。","notes":[]},{"n":126,"t":"這是耶和華降罰的時候，因人廢了你的律法。","notes":[]},{"n":127,"t":"所以，我愛你的命令勝於金子，更勝於精金。","notes":[]},{"n":128,"t":"你一切的訓詞，在萬事上我都以為正直；我卻恨惡一切假道。","notes":[]},{"n":129,"t":"你的法度奇妙，所以我一心謹守。","notes":[],"heads":["渴慕遵行耶和華的律法"]},{"n":130,"t":"你的言語一解開就發出亮光，使愚人通達。","notes":[]},{"n":131,"t":"我張口而氣喘，因我切慕你的命令。","notes":[]},{"n":132,"t":"求你轉向我，憐憫我，好像你素常待那些愛你名的人。","notes":[]},{"n":133,"t":"求你用你的話使我腳步穩當，不許甚麼罪孽轄制我。","notes":[]},{"n":134,"t":"求你救我脫離人的欺壓，我要遵守你的訓詞。","notes":[]},{"n":135,"t":"求你用臉光照僕人，又將你的律例教訓我。","notes":[]},{"n":136,"t":"我的眼淚下流成河，因為他們不守你的律法。","notes":[]},{"n":137,"t":"耶和華啊，你是公義的；你的判語也是正直的！","notes":[],"heads":["耶和華律法的公正"]},{"n":138,"t":"你所命定的法度是憑公義和至誠。","notes":[]},{"n":139,"t":"我心焦急，如同火燒，因我敵人忘記你的言語。","notes":[]},{"n":140,"t":"你的話極其精煉，所以你的僕人喜愛。","notes":[]},{"n":141,"t":"我微小，被人藐視，卻不忘記你的訓詞。","notes":[]},{"n":142,"t":"你的公義永遠長存；你的律法盡都真實。","notes":[]},{"n":143,"t":"我遭遇患難愁苦，你的命令卻是我所喜愛的。","notes":[]},{"n":144,"t":"你的法度永遠是公義的；求你賜我悟性，我就活了。","notes":[]},{"n":145,"t":"耶和華啊，我一心呼籲你；求你應允我，我必謹守你的律例！","notes":[],"heads":["求主解救"]},{"n":146,"t":"我向你呼籲，求你救我！我要遵守你的法度。","notes":[]},{"n":147,"t":"我趁天未亮呼求；我仰望了你的言語。","notes":[]},{"n":148,"t":"我趁夜更未換將眼睜開，為要思想你的話語。","notes":[]},{"n":149,"t":"求你照你的慈愛聽我的聲音；耶和華啊，求你照你的典章將我救活！","notes":[]},{"n":150,"t":"追求奸惡的人臨近了；他們遠離你的律法。","notes":[]},{"n":151,"t":"耶和華啊，你與我相近；你一切的命令盡都真實！","notes":[]},{"n":152,"t":"我因學你的法度，久已知道是你永遠立定的。","notes":[]},{"n":153,"t":"求你看顧我的苦難，搭救我，因我不忘記你的律法。","notes":[],"heads":["請求恩助"]},{"n":154,"t":"求你為我辨屈，救贖我，照你的話將我救活。","notes":[]},{"n":155,"t":"救恩遠離惡人，因為他們不尋求你的律例。","notes":[]},{"n":156,"t":"耶和華啊，你的慈悲本為大；求你照你的典章將我救活。","notes":[]},{"n":157,"t":"逼迫我的，抵擋我的，很多，我卻沒有偏離你的法度。","notes":[]},{"n":158,"t":"我看見奸惡的人就甚憎惡，因為他們不遵守你的話。","notes":[]},{"n":159,"t":"你看我怎樣愛你的訓詞！耶和華啊，求你照你的慈愛將我救活！","notes":[]},{"n":160,"t":"你話的總綱是真實；你一切公義的典章是永遠長存。","notes":[]},{"n":161,"t":"首領無故地逼迫我，但我的心畏懼你的言語。","notes":[],"heads":["熱愛耶和華的律法"]},{"n":162,"t":"我喜愛你的話，好像人得了許多擄物。","notes":[]},{"n":163,"t":"謊話是我所恨惡所憎嫌的；惟你的律法是我所愛的。","notes":[]},{"n":164,"t":"我因你公義的典章一天七次讚美你。","notes":[]},{"n":165,"t":"愛你律法的人有大平安，甚麼都不能使他們絆腳。","notes":[]},{"n":166,"t":"耶和華啊，我仰望了你的救恩，遵行了你的命令。","notes":[]},{"n":167,"t":"我心裏守了你的法度；這法度我甚喜愛。","notes":[]},{"n":168,"t":"我遵守了你的訓詞和法度，因我一切所行的都在你面前。","notes":[]},{"n":169,"t":"耶和華啊，願我的呼籲達到你面前，照你的話賜我悟性。","notes":[],"heads":["求主幫助"]},{"n":170,"t":"願我的懇求達到你面前，照你的話搭救我。","notes":[]},{"n":171,"t":"願我的嘴發出讚美的話，因為你將律例教訓我。","notes":[]},{"n":172,"t":"願我的舌頭歌唱你的話，因你一切的命令盡都公義。","notes":[]},{"n":173,"t":"願你用手幫助我，因我揀選了你的訓詞。","notes":[]},{"n":174,"t":"耶和華啊，我切慕你的救恩！你的律法也是我所喜愛的。","notes":[]},{"n":175,"t":"願我的性命存活，得以讚美你！願你的典章幫助我！","notes":[]},{"n":176,"t":"我如亡羊走迷了路，求你尋找僕人，因我不忘記你的命令。","notes":[]}]},"120":{"heading":"求主恩助","verses":[{"n":1,"t":"我在急難中求告耶和華，他就應允我。","notes":[]},{"n":2,"t":"耶和華啊，求你救我脫離說謊的嘴唇和詭詐的舌頭！","notes":[]},{"n":3,"t":"詭詐的舌頭啊，要給你甚麼呢？要拿甚麼加給你呢？","notes":[]},{"n":4,"t":"就是勇士的利箭和羅騰木 的炭火。","notes":["小樹名，松類"]},{"n":5,"t":"我寄居在米設，住在基達帳棚之中，有禍了！","notes":[]},{"n":6,"t":"我與那恨惡和睦的人許久同住。","notes":[]},{"n":7,"t":"我願和睦，但我發言，他們就要爭戰。","notes":[]}]},"121":{"heading":"耶和華是我們的保護者","verses":[{"n":1,"t":"我要向山舉目；我的幫助從何而來？","notes":[]},{"n":2,"t":"我的幫助從造天地的耶和華而來。","notes":[]},{"n":3,"t":"他必不叫你的腳搖動；保護你的必不打盹！","notes":[]},{"n":4,"t":"保護以色列的，也不打盹也不睡覺。","notes":[]},{"n":5,"t":"保護你的是耶和華；耶和華在你右邊蔭庇你。","notes":[]},{"n":6,"t":"白日，太陽必不傷你；夜間，月亮必不害你。","notes":[]},{"n":7,"t":"耶和華要保護你，免受一切的災害；他要保護你的性命。","notes":[]},{"n":8,"t":"你出你入，耶和華要保護你，從今時直到永遠。","notes":[]}]},"122":{"heading":"耶路撒冷頌","verses":[{"n":1,"t":"人對我說：我們往耶和華的殿去，我就歡喜。","notes":[]},{"n":2,"t":"耶路撒冷啊，我們的腳站在你的門內。","notes":[]},{"n":3,"t":"耶路撒冷被建造，如同連絡整齊的一座城。","notes":[]},{"n":4,"t":"眾支派，就是耶和華的支派，上那裏去，按以色列的常例稱讚耶和華的名。","notes":["或譯：作以色列的證據"]},{"n":5,"t":"因為在那裏設立審判的寶座，就是大衛家的寶座。","notes":[]},{"n":6,"t":"你們要為耶路撒冷求平安！耶路撒冷啊，愛你的人必然興旺！","notes":[]},{"n":7,"t":"願你城中平安！願你宮內興旺！","notes":[]},{"n":8,"t":"因我弟兄和同伴的緣故，我要說：願平安在你中間！","notes":[]},{"n":9,"t":"因耶和華－我們神殿的緣故，我要為你求福！","notes":[]}]},"123":{"heading":"求主憐憫","verses":[{"n":1,"t":"坐在天上的主啊，我向你舉目。","notes":[]},{"n":2,"t":"看哪，僕人的眼睛怎樣望主人的手，使女的眼睛怎樣望主母的手，我們的眼睛也照樣望耶和華－我們的神，直到他憐憫我們。","notes":[]},{"n":3,"t":"耶和華啊，求你憐憫我們，憐憫我們！因為我們被藐視，已到極處。","notes":[]},{"n":4,"t":"我們被那些安逸人的譏誚和驕傲人的藐視，已到極處。","notes":[]}]},"124":{"heading":"神是他子民的保護者","verses":[{"n":1,"t":"以色列人要說：若不是耶和華幫助我們，","notes":[]},{"n":2,"t":"若不是耶和華幫助我們，當人起來攻擊我們、","notes":[]},{"n":3,"t":"向我們發怒的時候，就把我們活活地吞了。","notes":[]},{"n":4,"t":"那時，波濤必漫過我們，河水必淹沒我們，","notes":[]},{"n":5,"t":"狂傲的水必淹沒我們。","notes":[]},{"n":6,"t":"耶和華是應當稱頌的！他沒有把我們當野食交給他們吞吃。","notes":["原文是牙齒"]},{"n":7,"t":"我們好像雀鳥，從捕鳥人的網羅裏逃脫；網羅破裂，我們逃脫了。","notes":[]},{"n":8,"t":"我們得幫助，是在乎倚靠造天地之耶和華的名。","notes":[]}]},"125":{"heading":"耶和華子民的安全","verses":[{"n":1,"t":"倚靠耶和華的人好像錫安山，永不動搖。","notes":[]},{"n":2,"t":"眾山怎樣圍繞耶路撒冷，耶和華也照樣圍繞他的百姓，從今時直到永遠。","notes":[]},{"n":3,"t":"惡人的杖不常落在義人的分上，免得義人伸手作惡。","notes":[]},{"n":4,"t":"耶和華啊，求你善待那些為善和心裏正直的人。","notes":[]},{"n":5,"t":"至於那偏行彎曲道路的人，耶和華必使他和作惡的人一同出去受刑。願平安歸於以色列！","notes":[]}]},"126":{"heading":"被擄歸回者的歡樂","verses":[{"n":1,"t":"當耶和華將那些被擄的帶回錫安的時候，我們好像做夢的人。","notes":[]},{"n":2,"t":"我們滿口喜笑、滿舌歡呼的時候，外邦中就有人說：耶和華為他們行了大事！","notes":[]},{"n":3,"t":"耶和華果然為我們行了大事，我們就歡喜。","notes":[]},{"n":4,"t":"耶和華啊，求你使我們被擄的人歸回，好像南地的河水復流。","notes":[]},{"n":5,"t":"流淚撒種的，必歡呼收割！","notes":[]},{"n":6,"t":"那帶種流淚出去的，必要歡歡樂樂地帶禾捆回來！","notes":[]}]},"127":{"heading":"稱頌神的良善","verses":[{"n":1,"t":"若不是耶和華建造房屋，建造的人就枉然勞力；若不是耶和華看守城池，看守的人就枉然警醒。","notes":[]},{"n":2,"t":"你們清晨早起，夜晚安歇，吃勞碌得來的飯，本是枉然；惟有耶和華所親愛的，必叫他安然睡覺。","notes":[]},{"n":3,"t":"兒女是耶和華所賜的產業；所懷的胎是他所給的賞賜。","notes":[]},{"n":4,"t":"少年時所生的兒女好像勇士手中的箭。","notes":[]},{"n":5,"t":"箭袋充滿的人便為有福；他們在城門口和仇敵說話的時候，必不至於羞愧。","notes":[]}]},"128":{"heading":"順從耶和華的賞報","verses":[{"n":1,"t":"凡敬畏耶和華、遵行他道的人便為有福！","notes":[]},{"n":2,"t":"你要吃勞碌得來的；你要享福，事情順利。","notes":[]},{"n":3,"t":"你妻子在你的內室，好像多結果子的葡萄樹；你兒女圍繞你的桌子，好像橄欖栽子。","notes":[]},{"n":4,"t":"看哪，敬畏耶和華的人必要這樣蒙福！","notes":[]},{"n":5,"t":"願耶和華從錫安賜福給你！願你一生一世看見耶路撒冷的好處！","notes":[]},{"n":6,"t":"願你看見你兒女的兒女！願平安歸於以色列！","notes":[]}]},"129":{"heading":"求耶和華退敵","verses":[{"n":1,"t":"以色列當說：從我幼年以來，敵人屢次苦害我，","notes":[]},{"n":2,"t":"從我幼年以來，敵人屢次苦害我，卻沒有勝了我。","notes":[]},{"n":3,"t":"如同扶犂的在我背上扶犂而耕，耕的犂溝甚長。","notes":[]},{"n":4,"t":"耶和華是公義的；他砍斷了惡人的繩索。","notes":[]},{"n":5,"t":"願恨惡錫安的都蒙羞退後！","notes":[]},{"n":6,"t":"願他們像房頂上的草，未長成而枯乾，","notes":[]},{"n":7,"t":"收割的不夠一把，捆禾的也不滿懷。","notes":[]},{"n":8,"t":"過路的也不說：願耶和華所賜的福歸與你們！我們奉耶和華的名給你們祝福！","notes":[]}]},"130":{"heading":"求助的祈禱","verses":[{"n":1,"t":"耶和華啊，我從深處向你求告！","notes":[]},{"n":2,"t":"主啊，求你聽我的聲音！願你側耳聽我懇求的聲音！","notes":[]},{"n":3,"t":"主－耶和華啊，你若究察罪孽，誰能站得住呢？","notes":[]},{"n":4,"t":"但在你有赦免之恩，要叫人敬畏你。","notes":[]},{"n":5,"t":"我等候耶和華，我的心等候；我也仰望他的話。","notes":[]},{"n":6,"t":"我的心等候主，勝於守夜的，等候天亮，勝於守夜的，等候天亮。","notes":[]},{"n":7,"t":"以色列啊，你當仰望耶和華！因他有慈愛，有豐盛的救恩。","notes":[]},{"n":8,"t":"他必救贖以色列脫離一切的罪孽。","notes":[]}]},"131":{"heading":"謙卑靠主","verses":[{"n":1,"t":"耶和華啊，我的心不狂傲，我的眼不高大；重大和測不透的事，我也不敢行。","notes":[]},{"n":2,"t":"我的心平穩安靜，好像斷過奶的孩子在他母親的懷中；我的心在我裏面真像斷過奶的孩子。","notes":[]},{"n":3,"t":"以色列啊，你當仰望耶和華，從今時直到永遠！","notes":[]}]},"132":{"heading":"聖殿頌","verses":[{"n":1,"t":"耶和華啊，求你記念大衛所受的一切苦難！","notes":[]},{"n":2,"t":"他怎樣向耶和華起誓，向雅各的大能者許願，","notes":[]},{"n":3,"t":"說：我必不進我的帳幕，也不上我的床榻；","notes":[]},{"n":4,"t":"我不容我的眼睛睡覺，也不容我的眼目打盹；","notes":[]},{"n":5,"t":"直等我為耶和華尋得所在，為雅各的大能者尋得居所。","notes":[]},{"n":6,"t":"我們聽說約櫃在以法他，我們在基列‧耶琳就尋見了。","notes":[]},{"n":7,"t":"我們要進他的居所，在他腳凳前下拜。","notes":[]},{"n":8,"t":"耶和華啊，求你興起，和你有能力的約櫃同入安息之所！","notes":[]},{"n":9,"t":"願你的祭司披上公義！願你的聖民歡呼！","notes":[]},{"n":10,"t":"求你因你僕人大衛的緣故，不要厭棄你的受膏者！","notes":[]},{"n":11,"t":"耶和華向大衛、憑誠實起了誓，必不反覆，說：我要使你所生的坐在你的寶座上。","notes":[]},{"n":12,"t":"你的眾子若守我的約和我所教訓他們的法度，他們的子孫必永遠坐在你的寶座上。","notes":[]},{"n":13,"t":"因為耶和華揀選了錫安，願意當作自己的居所，","notes":[]},{"n":14,"t":"說：這是我永遠安息之所；我要住在這裏，因為是我所願意的。","notes":[]},{"n":15,"t":"我要使其中的糧食豐滿，使其中的窮人飽足。","notes":[]},{"n":16,"t":"我要使祭司披上救恩，聖民大聲歡呼！","notes":[]},{"n":17,"t":"我要叫大衛的角在那裏發生；我為我的受膏者預備明燈。","notes":[]},{"n":18,"t":"我要使他的仇敵披上羞恥；但他的冠冕要在頭上發光。","notes":[]}]},"133":{"heading":"兄弟相愛頌","verses":[{"n":1,"t":"看哪，弟兄和睦同居是何等地善，何等地美！","notes":[]},{"n":2,"t":"這好比那貴重的油澆在亞倫的頭上，流到鬍鬚，又流到他的衣襟；","notes":[]},{"n":3,"t":"又好比黑門的甘露降在錫安山；因為在那裏有耶和華所命定的福，就是永遠的生命。","notes":[]}]},"134":{"heading":"宣召稱頌","verses":[{"n":1,"t":"耶和華的僕人夜間站在耶和華殿中的，你們當稱頌耶和華！","notes":[]},{"n":2,"t":"你們當向聖所舉手，稱頌耶和華！","notes":[]},{"n":3,"t":"願造天地的耶和華，從錫安賜福給你們！","notes":[]}]},"135":{"heading":"稱頌的聖詩","verses":[{"n":1,"t":"你們要讚美耶和華！你們要讚美耶和華的名！耶和華的僕人站在耶和華殿中；站在我們神殿院中的，你們要讚美他！","notes":[],"end":2},{"n":3,"t":"你們要讚美耶和華！耶和華本為善；要歌頌他的名，因為這是美好的。","notes":[]},{"n":4,"t":"耶和華揀選雅各歸自己，揀選以色列特作自己的子民。","notes":[]},{"n":5,"t":"原來我知道耶和華為大，也知道我們的主超乎萬神之上。","notes":[]},{"n":6,"t":"耶和華在天上，在地下，在海中，在一切的深處，都隨自己的意旨而行。","notes":[]},{"n":7,"t":"他使雲霧從地極上騰，造電隨雨而閃，從府庫中帶出風來。","notes":[]},{"n":8,"t":"他將埃及頭生的，連人帶牲畜都擊殺了。","notes":[]},{"n":9,"t":"埃及啊，他施行神蹟奇事，在你當中，在法老和他一切臣僕身上。","notes":[]},{"n":10,"t":"他擊殺許多的民，又殺戮大能的王，","notes":[]},{"n":11,"t":"就是亞摩利王西宏和巴珊王噩，並迦南一切的國王，","notes":[]},{"n":12,"t":"將他們的地賞賜他的百姓以色列為業。","notes":[]},{"n":13,"t":"耶和華啊，你的名存到永遠！耶和華啊，你可記念的名存到萬代！","notes":[]},{"n":14,"t":"耶和華要為他的百姓伸冤，為他的僕人後悔。","notes":[]},{"n":15,"t":"外邦的偶像是金的，銀的，是人手所造的；","notes":[]},{"n":16,"t":"有口卻不能言，有眼卻不能看，","notes":[]},{"n":17,"t":"有耳卻不能聽，口中也沒有氣息。","notes":[]},{"n":18,"t":"造他的要和他一樣，凡靠他的也要如此。","notes":[]},{"n":19,"t":"以色列家啊，你們要稱頌耶和華！亞倫家啊，你們要稱頌耶和華！","notes":[]},{"n":20,"t":"利未家啊，你們要稱頌耶和華！你們敬畏耶和華的，要稱頌耶和華！","notes":[]},{"n":21,"t":"住在耶路撒冷的耶和華該從錫安受稱頌。你們要讚美耶和華！","notes":[]}]},"136":{"heading":"感恩的聖詩","verses":[{"n":1,"t":"你們要稱謝耶和華，因他本為善；他的慈愛永遠長存。","notes":[]},{"n":2,"t":"你們要稱謝萬神之神，因他的慈愛永遠長存。","notes":[]},{"n":3,"t":"你們要稱謝萬主之主，因他的慈愛永遠長存。","notes":[]},{"n":4,"t":"稱謝那獨行大奇事的，因他的慈愛永遠長存。","notes":[]},{"n":5,"t":"稱謝那用智慧造天的，因他的慈愛永遠長存。","notes":[]},{"n":6,"t":"稱謝那鋪地在水以上的，因他的慈愛永遠長存。","notes":[]},{"n":7,"t":"稱謝那造成大光的，因他的慈愛永遠長存。","notes":[]},{"n":8,"t":"他造日頭管白晝，因他的慈愛永遠長存。","notes":[]},{"n":9,"t":"他造月亮星宿管黑夜，因他的慈愛永遠長存。","notes":[]},{"n":10,"t":"稱謝那擊殺埃及人之長子的，因他的慈愛永遠長存。","notes":[]},{"n":11,"t":"他領以色列人從他們中間出來，因他的慈愛永遠長存。","notes":[]},{"n":12,"t":"他施展大能的手和伸出來的膀臂，因他的慈愛永遠長存。","notes":[]},{"n":13,"t":"稱謝那分裂紅海的，因他的慈愛永遠長存。","notes":[]},{"n":14,"t":"他領以色列從其中經過，因他的慈愛永遠長存；","notes":[]},{"n":15,"t":"卻把法老和他的軍兵推翻在紅海裏，因他的慈愛永遠長存。","notes":[]},{"n":16,"t":"稱謝那引導自己的民行走曠野的，因他的慈愛永遠長存。","notes":[]},{"n":17,"t":"稱謝那擊殺大君王的，因他的慈愛永遠長存。","notes":[]},{"n":18,"t":"他殺戮有名的君王，因他的慈愛永遠長存；","notes":[]},{"n":19,"t":"就是殺戮亞摩利王西宏，因他的慈愛永遠長存；","notes":[]},{"n":20,"t":"又殺巴珊王噩，因他的慈愛永遠長存。","notes":[]},{"n":21,"t":"他將他們的地賜他的百姓為業，因他的慈愛永遠長存；","notes":[]},{"n":22,"t":"就是賜他的僕人以色列為業，因他的慈愛永遠長存。","notes":[]},{"n":23,"t":"他顧念我們在卑微的地步，因他的慈愛永遠長存。","notes":[]},{"n":24,"t":"他救拔我們脫離敵人，因他的慈愛永遠長存。","notes":[]},{"n":25,"t":"他賜糧食給凡有血氣的，因他的慈愛永遠長存。","notes":[]},{"n":26,"t":"你們要稱謝天上的神，因他的慈愛永遠長存。","notes":[]}]},"137":{"heading":"以色列人被擄的哀歌","verses":[{"n":1,"t":"我們曾在巴比倫的河邊坐下，一追想錫安就哭了。","notes":[]},{"n":2,"t":"我們把琴掛在那裏的柳樹上；","notes":[]},{"n":3,"t":"因為在那裏，擄掠我們的要我們唱歌，搶奪我們的要我們作樂，說：給我們唱一首錫安歌吧！","notes":[]},{"n":4,"t":"我們怎能在外邦唱耶和華的歌呢？","notes":[]},{"n":5,"t":"耶路撒冷啊，我若忘記你，情願我的右手忘記技巧！","notes":[]},{"n":6,"t":"我若不記念你，若不看耶路撒冷過於我所最喜樂的，情願我的舌頭貼於上膛！","notes":[]},{"n":7,"t":"耶路撒冷遭難的日子，以東人說：拆毀！拆毀！直拆到根基！耶和華啊，求你記念這仇！","notes":[]},{"n":8,"t":"將要被滅的巴比倫城啊，報復你像你待我們的，那人便為有福！","notes":["城：原文是女子"]},{"n":9,"t":"拿你的嬰孩摔在磐石上的，那人便為有福！","notes":[]}]},"138":{"heading":"感恩之禱","verses":[{"n":1,"t":"我要一心稱謝你，在諸神面前歌頌你。","notes":[]},{"n":2,"t":"我要向你的聖殿下拜，為你的慈愛和誠實稱讚你的名；因你使你的話顯為大，過於你所應許的。","notes":["或譯：超乎你的名聲"]},{"n":3,"t":"我呼求的日子，你就應允我，鼓勵我，使我心裏有能力。","notes":[]},{"n":4,"t":"耶和華啊，地上的君王都要稱謝你，因他們聽見了你口中的言語。","notes":[]},{"n":5,"t":"他們要歌頌耶和華的作為，因耶和華大有榮耀。","notes":[]},{"n":6,"t":"耶和華雖高，仍看顧低微的人；他卻從遠處看出驕傲的人。","notes":[]},{"n":7,"t":"我雖行在患難中，你必將我救活；我的仇敵發怒，你必伸手抵擋他們；你的右手也必救我。","notes":[]},{"n":8,"t":"耶和華必成全關乎我的事；耶和華啊，你的慈愛永遠長存！求你不要離棄你手所造的。","notes":[]}]},"139":{"heading":"耶和華的全知和眷顧","verses":[{"n":1,"t":"耶和華啊，你已經鑒察我，認識我。","notes":[]},{"n":2,"t":"我坐下，我起來，你都曉得；你從遠處知道我的意念。","notes":[]},{"n":3,"t":"我行路，我躺臥，你都細察；你也深知我一切所行的。","notes":[]},{"n":4,"t":"耶和華啊，我舌頭上的話，你沒有一句不知道的。","notes":[]},{"n":5,"t":"你在我前後環繞我，按手在我身上。","notes":[]},{"n":6,"t":"這樣的知識奇妙，是我不能測的，至高，是我不能及的。","notes":[]},{"n":7,"t":"我往哪裏去躲避你的靈？我往哪裏逃、躲避你的面？","notes":[]},{"n":8,"t":"我若升到天上，你在那裏；我若在陰間下榻，你也在那裏。","notes":[]},{"n":9,"t":"我若展開清晨的翅膀，飛到海極居住，","notes":[]},{"n":10,"t":"就是在那裏，你的手必引導我；你的右手也必扶持我。","notes":[]},{"n":11,"t":"我若說：黑暗必定遮蔽我，我周圍的亮光必成為黑夜；","notes":[]},{"n":12,"t":"黑暗也不能遮蔽我，使你不見，黑夜卻如白晝發亮。黑暗和光明，在你看都是一樣。","notes":[]},{"n":13,"t":"我的肺腑是你所造的；我在母腹中，你已覆庇我。","notes":[]},{"n":14,"t":"我要稱謝你，因我受造，奇妙可畏；你的作為奇妙，這是我心深知道的。","notes":[]},{"n":15,"t":"我在暗中受造，在地的深處被聯絡；那時，我的形體並不向你隱藏。","notes":[]},{"n":16,"t":"我未成形的體質，你的眼早已看見了；你所定的日子，我尚未度一日，你都寫在你的冊上了。","notes":["或譯：我被造的肢體尚未有其一"]},{"n":17,"t":"神啊，你的意念向我何等寶貴！其數何等眾多！","notes":[]},{"n":18,"t":"我若數點，比海沙更多；我睡醒的時候，仍和你同在。","notes":[]},{"n":19,"t":"神啊，你必要殺戮惡人；所以，你們好流人血的，離開我去吧！","notes":[]},{"n":20,"t":"因為他們說惡言頂撞你；你的仇敵也妄稱你的名。","notes":[]},{"n":21,"t":"耶和華啊，恨惡你的，我豈不恨惡他們嗎？攻擊你的，我豈不憎嫌他們嗎？","notes":[]},{"n":22,"t":"我切切地恨惡他們，以他們為仇敵。","notes":[]},{"n":23,"t":"神啊，求你鑒察我，知道我的心思，試煉我，知道我的意念，","notes":[]},{"n":24,"t":"看在我裏面有甚麼惡行沒有，引導我走永生的道路。","notes":[]}]},"140":{"heading":"求耶和華護佑","verses":[{"n":1,"t":"耶和華啊，求你拯救我脫離凶惡的人，保護我脫離強暴的人！","notes":[]},{"n":2,"t":"他們心中圖謀奸惡，常常聚集要爭戰。","notes":[]},{"n":3,"t":"他們使舌頭尖利如蛇，嘴裏有虺蛇的毒氣。（細拉）","notes":[]},{"n":4,"t":"耶和華啊，求你拯救我脫離惡人的手，保護我脫離強暴的人！他們圖謀推我跌倒。","notes":[]},{"n":5,"t":"驕傲人為我暗設網羅和繩索；他們在路旁鋪下網，設下圈套。（細拉）","notes":[]},{"n":6,"t":"我曾對耶和華說：你是我的神。耶和華啊，求你留心聽我懇求的聲音！","notes":[]},{"n":7,"t":"主－耶和華、我救恩的力量啊，在爭戰的日子，你遮蔽了我的頭。","notes":[]},{"n":8,"t":"耶和華啊，求你不要遂惡人的心願；不要成就他們的計謀，恐怕他們自高。（細拉）","notes":[]},{"n":9,"t":"至於那些昂首圍困我的人，願他們嘴唇的奸惡陷害自己！","notes":["原文是遮蔽"]},{"n":10,"t":"願火炭落在他們身上！願他們被丟在火中，拋在深坑裏，不能再起來。","notes":[]},{"n":11,"t":"說惡言的人在地上必堅立不住；禍患必獵取強暴的人，將他打倒。","notes":[]},{"n":12,"t":"我知道耶和華必為困苦人伸冤，必為窮乏人辨屈。","notes":[]},{"n":13,"t":"義人必要稱讚你的名；正直人必住在你面前。","notes":[]}]},"141":{"heading":"晚 禱","verses":[{"n":1,"t":"耶和華啊，我曾求告你，求你快快臨到我這裏！我求告你的時候，願你留心聽我的聲音！","notes":[]},{"n":2,"t":"願我的禱告如香陳列在你面前！願我舉手祈求，如獻晚祭！","notes":[]},{"n":3,"t":"耶和華啊，求你禁止我的口，把守我的嘴！","notes":[]},{"n":4,"t":"求你不叫我的心偏向邪惡，以致我和作孽的人同行惡事；也不叫我吃他們的美食。","notes":[]},{"n":5,"t":"任憑義人擊打我，這算為仁慈；任憑他責備我，這算為頭上的膏油；我的頭不要躲閃。正在他們行惡的時候，我仍要祈禱。","notes":[]},{"n":6,"t":"他們的審判官被扔在巖下；眾人要聽我的話，因為這話甘甜。","notes":[]},{"n":7,"t":"我們的骨頭散在墓旁，好像人耕田、刨地的土塊。","notes":[]},{"n":8,"t":"主－耶和華啊，我的眼目仰望你；我投靠你，求你不要將我撇得孤苦！","notes":[]},{"n":9,"t":"求你保護我脫離惡人為我設的網羅和作孽之人的圈套！","notes":[]},{"n":10,"t":"願惡人落在自己的網裏，我卻得以逃脫。","notes":[]}]},"142":{"heading":"求主眷顧","verses":[{"n":1,"t":"我發聲哀告耶和華，發聲懇求耶和華。","notes":[]},{"n":2,"t":"我在他面前吐露我的苦情，陳說我的患難。","notes":[]},{"n":3,"t":"我的靈在我裏面發昏的時候，你知道我的道路。在我行的路上，敵人為我暗設網羅。","notes":[]},{"n":4,"t":"求你向我右邊觀看，因為沒有人認識我；我無處避難，也沒有人眷顧我。","notes":[]},{"n":5,"t":"耶和華啊，我曾向你哀求。我說：你是我的避難所；在活人之地，你是我的福分。","notes":[]},{"n":6,"t":"求你側耳聽我的呼求，因我落到極卑之地；求你救我脫離逼迫我的人，因為他們比我強盛。","notes":[]},{"n":7,"t":"求你領我出離被囚之地，我好稱讚你的名。義人必環繞我，因為你是用厚恩待我。","notes":[]}]},"143":{"heading":"求主拯救","verses":[{"n":1,"t":"耶和華啊，求你聽我的禱告，留心聽我的懇求，憑你的信實和公義應允我。","notes":[]},{"n":2,"t":"求你不要審問僕人；因為在你面前，凡活著的人沒有一個是義的。","notes":[]},{"n":3,"t":"原來仇敵逼迫我，將我打倒在地，使我住在幽暗之處，像死了許久的人一樣。","notes":[]},{"n":4,"t":"所以，我的靈在我裏面發昏；我的心在我裏面悽慘。","notes":[]},{"n":5,"t":"我追想古時之日，思想你的一切作為，默念你手的工作。","notes":[]},{"n":6,"t":"我向你舉手；我的心渴想你，如乾旱之地盼雨一樣。（細拉）","notes":[]},{"n":7,"t":"耶和華啊，求你速速應允我！我心神耗盡！不要向我掩面，免得我像那些下坑的人一樣。","notes":[]},{"n":8,"t":"求你使我清晨得聽你慈愛之言，因我倚靠你；求你使我知道當行的路，因我的心仰望你。","notes":[]},{"n":9,"t":"耶和華啊，求你救我脫離我的仇敵！我往你那裏藏身。","notes":[]},{"n":10,"t":"求你指教我遵行你的旨意，因你是我的神。你的靈本為善；求你引我到平坦之地。","notes":[]},{"n":11,"t":"耶和華啊，求你為你的名將我救活，憑你的公義，將我從患難中領出來，","notes":[]},{"n":12,"t":"憑你的慈愛剪除我的仇敵，滅絕一切苦待我的人，因我是你的僕人。","notes":[]}]},"144":{"heading":"君王為勝利感恩","verses":[{"n":1,"t":"耶和華－我的磐石是應當稱頌的！他教導我的手爭戰，教導我的指頭打仗。","notes":[]},{"n":2,"t":"他是我慈愛的主，我的山寨，我的高臺，我的救主，我的盾牌，是我所投靠的；他使我的百姓服在我以下。","notes":[]},{"n":3,"t":"耶和華啊，人算甚麼，你竟認識他！世人算甚麼，你竟顧念他！","notes":[]},{"n":4,"t":"人好像一口氣；他的年日如同影兒快快過去。","notes":[]},{"n":5,"t":"耶和華啊，求你使天下垂，親自降臨，摸山，山就冒煙。","notes":[]},{"n":6,"t":"求你發出閃電，使他們四散，射出你的箭，使他們擾亂。","notes":[]},{"n":7,"t":"求你從上伸手救拔我，救我出離大水，救我脫離外邦人的手。","notes":[]},{"n":8,"t":"他們的口說謊話；他們的右手起假誓。","notes":[]},{"n":9,"t":"神啊，我要向你唱新歌，用十弦瑟向你歌頌。","notes":[]},{"n":10,"t":"你是那拯救君王的；你是那救僕人大衛脫離害命之刀的。","notes":[]},{"n":11,"t":"求你救拔我，救我脫離外邦人的手。他們的口說謊話；他們的右手起假誓。","notes":[]},{"n":12,"t":"我們的兒子從幼年好像樹栽子長大；我們的女兒如同殿角石，是按建宮的樣式鑿成的。","notes":[]},{"n":13,"t":"我們的倉盈滿，能出各樣的糧食；我們的羊在田間孳生千萬。","notes":[]},{"n":14,"t":"我們的牛馱著滿馱，沒有人闖進來搶奪，也沒有人出去爭戰；我們的街市上也沒有哭號的聲音。","notes":[]},{"n":15,"t":"遇見這光景的百姓便為有福！有耶和華為他們的神，這百姓便為有福！","notes":[]}]},"145":{"heading":"稱頌的聖詩","verses":[{"n":1,"t":"我的神我的王啊，我要尊崇你！我要永永遠遠稱頌你的名！","notes":[]},{"n":2,"t":"我要天天稱頌你，也要永永遠遠讚美你的名！","notes":[]},{"n":3,"t":"耶和華本為大，該受大讚美；其大無法測度。","notes":[]},{"n":4,"t":"這代要對那代頌讚你的作為，也要傳揚你的大能。","notes":[]},{"n":5,"t":"我要默念你威嚴的尊榮和你奇妙的作為。","notes":[]},{"n":6,"t":"人要傳說你可畏之事的能力；我也要傳揚你的大德。","notes":[]},{"n":7,"t":"他們記念你的大恩就要傳出來，並要歌唱你的公義。","notes":[]},{"n":8,"t":"耶和華有恩惠，有憐憫，不輕易發怒，大有慈愛。","notes":[]},{"n":9,"t":"耶和華善待萬民；他的慈悲覆庇他一切所造的。","notes":[]},{"n":10,"t":"耶和華啊，你一切所造的都要稱謝你；你的聖民也要稱頌你，","notes":[]},{"n":11,"t":"傳說你國的榮耀，談論你的大能，","notes":[]},{"n":12,"t":"好叫世人知道你大能的作為，並你國度威嚴的榮耀。","notes":[]},{"n":13,"t":"你的國是永遠的國！你執掌的權柄存到萬代！","notes":[]},{"n":14,"t":"凡跌倒的，耶和華將他們扶持；凡被壓下的，將他們扶起。","notes":[]},{"n":15,"t":"萬民都舉目仰望你；你隨時給他們食物。","notes":[]},{"n":16,"t":"你張手，使有生氣的都隨願飽足。","notes":[]},{"n":17,"t":"耶和華在他一切所行的，無不公義；在他一切所做的都有慈愛。","notes":[]},{"n":18,"t":"凡求告耶和華的，就是誠心求告他的，耶和華便與他們相近。","notes":[]},{"n":19,"t":"敬畏他的，他必成就他們的心願，也必聽他們的呼求，拯救他們。","notes":[]},{"n":20,"t":"耶和華保護一切愛他的人，卻要滅絕一切的惡人。","notes":[]},{"n":21,"t":"我的口要說出讚美耶和華的話；惟願凡有血氣的都永永遠遠稱頌他的聖名。","notes":[]}]},"146":{"heading":"讚美耶和華的救助","verses":[{"n":1,"t":"你們要讚美耶和華！我的心哪，你要讚美耶和華！","notes":[]},{"n":2,"t":"我一生要讚美耶和華！我還活的時候要歌頌我的神！","notes":[]},{"n":3,"t":"你們不要倚靠君王，不要倚靠世人；他一點不能幫助。","notes":[]},{"n":4,"t":"他的氣一斷，就歸回塵土；他所打算的，當日就消滅了。","notes":[]},{"n":5,"t":"以雅各的神為幫助、仰望耶和華－他神的，這人便為有福！","notes":[]},{"n":6,"t":"耶和華造天、地、海，和其中的萬物；他守誠實，直到永遠。","notes":[]},{"n":7,"t":"他為受屈的伸冤，賜食物與飢餓的。耶和華釋放被囚的；","notes":[]},{"n":8,"t":"耶和華開了瞎子的眼睛；耶和華扶起被壓下的人。耶和華喜愛義人。","notes":[]},{"n":9,"t":"耶和華保護寄居的，扶持孤兒和寡婦，卻使惡人的道路彎曲。","notes":[]},{"n":10,"t":"耶和華要作王，直到永遠！錫安哪，你的神要作王，直到萬代！你們要讚美耶和華！","notes":[]}]},"147":{"heading":"讚美神的全能","verses":[{"n":1,"t":"你們要讚美耶和華！因歌頌我們的神為善為美；讚美的話是合宜的。","notes":[]},{"n":2,"t":"耶和華建造耶路撒冷，聚集以色列中被趕散的人。","notes":[]},{"n":3,"t":"他醫好傷心的人，裹好他們的傷處。","notes":[]},{"n":4,"t":"他數點星宿的數目，一一稱它的名。","notes":[]},{"n":5,"t":"我們的主為大，最有能力；他的智慧無法測度。","notes":[]},{"n":6,"t":"耶和華扶持謙卑人，將惡人傾覆於地。","notes":[]},{"n":7,"t":"你們要以感謝向耶和華歌唱，用琴向我們的神歌頌。","notes":[]},{"n":8,"t":"他用雲遮天，為地降雨，使草生長在山上。","notes":[]},{"n":9,"t":"他賜食給走獸和啼叫的小烏鴉。","notes":[]},{"n":10,"t":"他不喜悅馬的力大，不喜愛人的腿快。","notes":[]},{"n":11,"t":"耶和華喜愛敬畏他和盼望他慈愛的人。","notes":[]},{"n":12,"t":"耶路撒冷啊，你要頌讚耶和華！錫安哪，你要讚美你的神！","notes":[]},{"n":13,"t":"因為他堅固了你的門閂，賜福給你中間的兒女。","notes":[]},{"n":14,"t":"他使你境內平安，用上好的麥子使你滿足。","notes":[]},{"n":15,"t":"他發命在地；他的話頒行最快。","notes":[]},{"n":16,"t":"他降雪如羊毛，撒霜如爐灰。","notes":[]},{"n":17,"t":"他擲下冰雹如碎渣；他發出寒冷，誰能當得起呢？","notes":[]},{"n":18,"t":"他一出令，這些就都消化；他使風颳起，水便流動。","notes":[]},{"n":19,"t":"他將他的道指示雅各，將他的律例典章指示以色列。","notes":[]},{"n":20,"t":"別國他都沒有這樣待過；至於他的典章，他們向來沒有知道。你們要讚美耶和華！","notes":[]}]},"148":{"heading":"宣召萬有讚美耶和華","verses":[{"n":1,"t":"你們要讚美耶和華！從天上讚美耶和華，在高處讚美他！","notes":[]},{"n":2,"t":"他的眾使者都要讚美他！他的諸軍都要讚美他！","notes":[]},{"n":3,"t":"日頭月亮，你們要讚美他！放光的星宿，你們都要讚美他！","notes":[]},{"n":4,"t":"天上的天和天上的水，你們都要讚美他！","notes":[]},{"n":5,"t":"願這些都讚美耶和華的名！因他一吩咐便都造成。","notes":[]},{"n":6,"t":"他將這些立定，直到永永遠遠；他定了命，不能廢去。","notes":["或譯：越過"]},{"n":7,"t":"所有在地上的，大魚和一切深洋，","notes":[]},{"n":8,"t":"火與冰雹，雪和霧氣，成就他命的狂風，","notes":[]},{"n":9,"t":"大山和小山，結果的樹木和一切香柏樹，","notes":[]},{"n":10,"t":"野獸和一切牲畜，昆蟲和飛鳥，","notes":[]},{"n":11,"t":"世上的君王和萬民，首領和世上一切審判官，","notes":[]},{"n":12,"t":"少年人和處女，老年人和孩童，都當讚美耶和華！","notes":[]},{"n":13,"t":"願這些都讚美耶和華的名！因為獨有他的名被尊崇；他的榮耀在天地之上。","notes":[]},{"n":14,"t":"他將他百姓的角高舉，因此他一切聖民以色列人，就是與他相近的百姓，都讚美他！你們要讚美耶和華！","notes":["或譯：他使"]}]},"149":{"heading":"讚美的聖詩","verses":[{"n":1,"t":"你們要讚美耶和華！向耶和華唱新歌，在聖民的會中讚美他！","notes":[]},{"n":2,"t":"願以色列因造他的主歡喜！願錫安的民因他們的王快樂！","notes":[]},{"n":3,"t":"願他們跳舞讚美他的名，擊鼓彈琴歌頌他！","notes":[]},{"n":4,"t":"因為耶和華喜愛他的百姓；他要用救恩當作謙卑人的妝飾。","notes":[]},{"n":5,"t":"願聖民因所得的榮耀高興！願他們在床上歡呼！","notes":[]},{"n":6,"t":"願他們口中稱讚神為高，手裏有兩刃的刀，","notes":[]},{"n":7,"t":"為要報復列邦，刑罰萬民。","notes":[]},{"n":8,"t":"要用鍊子捆他們的君王，用鐵鐐鎖他們的大臣；","notes":[]},{"n":9,"t":"要在他們身上施行所記錄的審判。他的聖民都有這榮耀。你們要讚美耶和華！","notes":[]}]},"150":{"heading":"讚美耶和華","verses":[{"n":1,"t":"你們要讚美耶和華！在神的聖所讚美他！在他顯能力的穹蒼讚美他！","notes":[]},{"n":2,"t":"要因他大能的作為讚美他，按著他極美的大德讚美他！","notes":[]},{"n":3,"t":"要用角聲讚美他，鼓瑟彈琴讚美他！","notes":[]},{"n":4,"t":"擊鼓跳舞讚美他！用絲弦的樂器和簫的聲音讚美他！","notes":[]},{"n":5,"t":"用大響的鈸讚美他！用高聲的鈸讚美他！","notes":[]},{"n":6,"t":"凡有氣息的都要讚美耶和華！你們要讚美耶和華！","notes":[]}]}},"PRO":{"1":{"heading":"箴言的價值","verses":[{"n":1,"t":"以色列王大衛兒子所羅門的箴言：","notes":[]},{"n":2,"t":"要使人曉得智慧和訓誨，分辨通達的言語，","notes":[]},{"n":3,"t":"使人處事領受智慧、仁義、公平、正直的訓誨，","notes":[]},{"n":4,"t":"使愚人靈明，使少年人有知識和謀略，","notes":[]},{"n":5,"t":"使智慧人聽見，增長學問，使聰明人得著智謀，","notes":[]},{"n":6,"t":"使人明白箴言和譬喻，懂得智慧人的言詞和謎語。","notes":[]},{"n":7,"t":"敬畏耶和華是知識的開端；愚妄人藐視智慧和訓誨。","notes":[],"heads":["給青年人的忠告"]},{"n":8,"t":"我兒，要聽你父親的訓誨，不可離棄你母親的法則；","notes":["或譯：指教"]},{"n":9,"t":"因為這要作你頭上的華冠，你項上的金鍊。","notes":[]},{"n":10,"t":"我兒，惡人若引誘你，你不可隨從。","notes":[]},{"n":11,"t":"他們若說：你與我們同去，我們要埋伏流人之血，要蹲伏害無罪之人；","notes":[]},{"n":12,"t":"我們好像陰間，把他們活活吞下；他們如同下坑的人，被我們囫圇吞了；","notes":[]},{"n":13,"t":"我們必得各樣寶物，將所擄來的，裝滿房屋；","notes":[]},{"n":14,"t":"你與我們大家同分，我們共用一個囊袋；","notes":[]},{"n":15,"t":"我兒，不要與他們同行一道，禁止你腳走他們的路。","notes":[]},{"n":16,"t":"因為，他們的腳奔跑行惡；他們急速流人的血，","notes":[]},{"n":17,"t":"好像飛鳥，網羅設在眼前仍不躲避。","notes":[]},{"n":18,"t":"這些人埋伏，是為自流己血；蹲伏，是為自害己命。","notes":[]},{"n":19,"t":"凡貪戀財利的，所行之路都是如此；這貪戀之心乃奪去得財者之命。","notes":[]},{"n":20,"t":"智慧在街市上呼喊，在寬闊處發聲，","notes":[],"heads":["智慧呼喚人"]},{"n":21,"t":"在熱鬧街頭喊叫，在城門口，在城中發出言語，","notes":[]},{"n":22,"t":"說：你們愚昧人喜愛愚昧，褻慢人喜歡褻慢，愚頑人恨惡知識，要到幾時呢？","notes":[]},{"n":23,"t":"你們當因我的責備回轉；我要將我的靈澆灌你們，將我的話指示你們。","notes":[]},{"n":24,"t":"我呼喚，你們不肯聽從；我伸手，無人理會；","notes":[]},{"n":25,"t":"反輕棄我一切的勸戒，不肯受我的責備。","notes":[]},{"n":26,"t":"你們遭災難，我就發笑；驚恐臨到你們，我必嗤笑。","notes":[]},{"n":27,"t":"驚恐臨到你們，好像狂風；災難來到，如同暴風；急難痛苦臨到你們身上。","notes":[]},{"n":28,"t":"那時，你們必呼求我，我卻不答應，懇切地尋找我，卻尋不見。","notes":[]},{"n":29,"t":"因為，你們恨惡知識，不喜愛敬畏耶和華，","notes":[]},{"n":30,"t":"不聽我的勸戒，藐視我一切的責備，","notes":[]},{"n":31,"t":"所以必吃自結的果子，充滿自設的計謀。","notes":[]},{"n":32,"t":"愚昧人背道，必殺己身；愚頑人安逸，必害己命。","notes":[]},{"n":33,"t":"惟有聽從我的，必安然居住，得享安靜，不怕災禍。","notes":[]}]},"2":{"heading":"智慧的賞賜","verses":[{"n":1,"t":"我兒，你若領受我的言語，存記我的命令，","notes":[]},{"n":2,"t":"側耳聽智慧，專心求聰明，","notes":[]},{"n":3,"t":"呼求明哲，揚聲求聰明，","notes":[]},{"n":4,"t":"尋找它，如尋找銀子，搜求它，如搜求隱藏的珍寶，","notes":[]},{"n":5,"t":"你就明白敬畏耶和華，得以認識神。","notes":[]},{"n":6,"t":"因為，耶和華賜人智慧；知識和聰明都由他口而出。","notes":[]},{"n":7,"t":"他給正直人存留真智慧，給行為純正的人作盾牌，","notes":[]},{"n":8,"t":"為要保守公平人的路，護庇虔敬人的道。","notes":[]},{"n":9,"t":"你也必明白仁義、公平、正直、一切的善道。","notes":[]},{"n":10,"t":"智慧必入你心；你的靈要以知識為美。","notes":[]},{"n":11,"t":"謀略必護衛你；聰明必保守你，","notes":[]},{"n":12,"t":"要救你脫離惡道，脫離說乖謬話的人。","notes":["或譯：惡人的道"]},{"n":13,"t":"那等人捨棄正直的路，行走黑暗的道，","notes":[]},{"n":14,"t":"歡喜作惡，喜愛惡人的乖僻，","notes":[]},{"n":15,"t":"在他們的道中彎曲，在他們的路上偏僻。","notes":[]},{"n":16,"t":"智慧要救你脫離淫婦，就是那油嘴滑舌的外女。","notes":[]},{"n":17,"t":"她離棄幼年的配偶，忘了神的盟約。","notes":[]},{"n":18,"t":"她的家陷入死地；她的路偏向陰間。","notes":[]},{"n":19,"t":"凡到她那裏去的，不得轉回，也得不著生命的路。","notes":[]},{"n":20,"t":"智慧必使你行善人的道，守義人的路。","notes":[]},{"n":21,"t":"正直人必在世上居住；完全人必在地上存留。","notes":[]},{"n":22,"t":"惟有惡人必然剪除；奸詐的，必然拔出。","notes":[]}]},"3":{"heading":"給青年人的忠告","verses":[{"n":1,"t":"我兒，不要忘記我的法則；你心要謹守我的誡命；","notes":["或譯：指教"]},{"n":2,"t":"因為它必將長久的日子，生命的年數與平安，加給你。","notes":[]},{"n":3,"t":"不可使慈愛、誠實離開你，要繫在你頸項上，刻在你心版上。","notes":[]},{"n":4,"t":"這樣，你必在神和世人眼前蒙恩寵，有聰明。","notes":[]},{"n":5,"t":"你要專心仰賴耶和華，不可倚靠自己的聰明，","notes":[]},{"n":6,"t":"在你一切所行的事上都要認定他，他必指引你的路。","notes":[]},{"n":7,"t":"不要自以為有智慧；要敬畏耶和華，遠離惡事。","notes":[]},{"n":8,"t":"這便醫治你的肚臍，滋潤你的百骨。","notes":[]},{"n":9,"t":"你要以財物和一切初熟的土產尊榮耶和華。","notes":[]},{"n":10,"t":"這樣，你的倉房必充滿有餘；你的酒醡有新酒盈溢。","notes":[]},{"n":11,"t":"我兒，你不可輕看耶和華的管教，也不可厭煩他的責備；","notes":["或譯：懲治"]},{"n":12,"t":"因為耶和華所愛的，他必責備，正如父親責備所喜愛的兒子。","notes":[]},{"n":13,"t":"得智慧，得聰明的，這人便為有福。","notes":[]},{"n":14,"t":"因為得智慧勝過得銀子，其利益強如精金，","notes":[]},{"n":15,"t":"比珍珠寶貴；你一切所喜愛的，都不足與比較。","notes":["或譯：紅寶石"]},{"n":16,"t":"她右手有長壽，左手有富貴。","notes":[]},{"n":17,"t":"她的道是安樂；她的路全是平安。","notes":[]},{"n":18,"t":"她與持守她的作生命樹；持定她的，俱各有福。","notes":[]},{"n":19,"t":"耶和華以智慧立地，以聰明定天，","notes":[]},{"n":20,"t":"以知識使深淵裂開，使天空滴下甘露。","notes":[]},{"n":21,"t":"我兒，要謹守真智慧和謀略，不可使她離開你的眼目。","notes":[]},{"n":22,"t":"這樣，她必作你的生命，頸項的美飾。","notes":[]},{"n":23,"t":"你就坦然行路，不致碰腳。","notes":[]},{"n":24,"t":"你躺下，必不懼怕；你躺臥，睡得香甜。","notes":[]},{"n":25,"t":"忽然來的驚恐，不要害怕；惡人遭毀滅，也不要恐懼。","notes":[]},{"n":26,"t":"因為耶和華是你所倚靠的；他必保守你的腳不陷入網羅。","notes":[]},{"n":27,"t":"你手若有行善的力量，不可推辭，就當向那應得的人施行。","notes":[]},{"n":28,"t":"你那裏若有現成的，不可對鄰舍說：去吧，明天再來，我必給你。","notes":[]},{"n":29,"t":"你的鄰舍既在你附近安居，你不可設計害他。","notes":[]},{"n":30,"t":"人未曾加害與你，不可無故與他相爭。","notes":[]},{"n":31,"t":"不可嫉妒強暴的人，也不可選擇他所行的路。","notes":[]},{"n":32,"t":"因為，乖僻人為耶和華所憎惡；正直人為他所親密。","notes":[]},{"n":33,"t":"耶和華咒詛惡人的家庭，賜福與義人的居所。","notes":[]},{"n":34,"t":"他譏誚那好譏誚的人，賜恩給謙卑的人。","notes":[]},{"n":35,"t":"智慧人必承受尊榮；愚昧人高升也成為羞辱。","notes":[]}]},"4":{"heading":"智慧的益處","verses":[{"n":1,"t":"眾子啊，要聽父親的教訓，留心得知聰明。","notes":[]},{"n":2,"t":"因我所給你們的是好教訓；不可離棄我的法則。","notes":["或譯：指教"]},{"n":3,"t":"我在父親面前為孝子，在母親眼中為獨一的嬌兒。","notes":[]},{"n":4,"t":"父親教訓我說：你心要存記我的言語，遵守我的命令，便得存活。","notes":[]},{"n":5,"t":"要得智慧，要得聰明，不可忘記，也不可偏離我口中的言語。","notes":[]},{"n":6,"t":"不可離棄智慧，智慧就護衛你；要愛她，她就保守你。","notes":[]},{"n":7,"t":"智慧為首；所以，要得智慧。在你一切所得之內必得聰明。","notes":["或譯：用你一切所得的去換聰明"]},{"n":8,"t":"高舉智慧，她就使你高升；懷抱智慧，她就使你尊榮。","notes":[]},{"n":9,"t":"她必將華冠加在你頭上，把榮冕交給你。","notes":[]},{"n":10,"t":"我兒，你要聽受我的言語，就必延年益壽。","notes":[]},{"n":11,"t":"我已指教你走智慧的道，引導你行正直的路。","notes":[]},{"n":12,"t":"你行走，腳步必不致狹窄；你奔跑，也不致跌倒。","notes":[]},{"n":13,"t":"要持定訓誨，不可放鬆；必當謹守，因為它是你的生命。","notes":[]},{"n":14,"t":"不可行惡人的路；不要走壞人的道。","notes":[]},{"n":15,"t":"要躲避，不可經過；要轉身而去。","notes":[]},{"n":16,"t":"這等人若不行惡，不得睡覺；不使人跌倒，睡臥不安；","notes":[]},{"n":17,"t":"因為他們以奸惡吃餅，以強暴喝酒。","notes":[]},{"n":18,"t":"但義人的路好像黎明的光，越照越明，直到日午。","notes":[]},{"n":19,"t":"惡人的道好像幽暗，自己不知因甚麼跌倒。","notes":[]},{"n":20,"t":"我兒，要留心聽我的言詞，側耳聽我的話語，","notes":[]},{"n":21,"t":"都不可離你的眼目，要存記在你心中。","notes":[]},{"n":22,"t":"因為得著它的，就得了生命，又得了醫全體的良藥。","notes":[]},{"n":23,"t":"你要保守你心，勝過保守一切，因為一生的果效是由心發出。","notes":["或譯：你要切切保守你心"]},{"n":24,"t":"你要除掉邪僻的口，棄絕乖謬的嘴。","notes":[]},{"n":25,"t":"你的眼目要向前正看；你的眼睛當向前直觀。","notes":["原文是皮"]},{"n":26,"t":"要修平你腳下的路，堅定你一切的道。","notes":[]},{"n":27,"t":"不可偏向左右；要使你的腳離開邪惡。","notes":[]}]},"5":{"heading":"警告勿犯淫亂","verses":[{"n":1,"t":"我兒，要留心我智慧的話語，側耳聽我聰明的言詞，","notes":[]},{"n":2,"t":"為要使你謹守謀略，嘴唇保存知識。","notes":[]},{"n":3,"t":"因為淫婦的嘴滴下蜂蜜；她的口比油更滑，","notes":[]},{"n":4,"t":"至終卻苦似茵蔯，快如兩刃的刀。","notes":[]},{"n":5,"t":"她的腳下入死地；她腳步踏住陰間，","notes":[]},{"n":6,"t":"以致她找不著生命平坦的道。她的路變遷不定，自己還不知道。","notes":[]},{"n":7,"t":"眾子啊，現在要聽從我；不可離棄我口中的話。","notes":[]},{"n":8,"t":"你所行的道要離她遠，不可就近她的房門，","notes":[]},{"n":9,"t":"恐怕將你的尊榮給別人，將你的歲月給殘忍的人；","notes":[]},{"n":10,"t":"恐怕外人滿得你的力量，你勞碌得來的，歸入外人的家；","notes":[]},{"n":11,"t":"終久，你皮肉和身體消毀，你就悲歎，","notes":[]},{"n":12,"t":"說：我怎麼恨惡訓誨，心中藐視責備，","notes":[]},{"n":13,"t":"也不聽從我師傅的話，又不側耳聽那教訓我的人？","notes":[]},{"n":14,"t":"我在聖會裏，幾乎落在諸般惡中。","notes":[]},{"n":15,"t":"你要喝自己池中的水，飲自己井裏的活水。","notes":[]},{"n":16,"t":"你的泉源豈可漲溢在外？你的河水豈可流在街上？","notes":[]},{"n":17,"t":"惟獨歸你一人，不可與外人同用。","notes":[]},{"n":18,"t":"要使你的泉源蒙福；要喜悅你幼年所娶的妻。","notes":[]},{"n":19,"t":"她如可愛的麀鹿，可喜的母鹿；願她的胸懷使你時時知足，她的愛情使你常常戀慕。","notes":[]},{"n":20,"t":"我兒，你為何戀慕淫婦？為何抱外女的胸懷？","notes":[]},{"n":21,"t":"因為，人所行的道都在耶和華眼前；他也修平人一切的路。","notes":[]},{"n":22,"t":"惡人必被自己的罪孽捉住；他必被自己的罪惡如繩索纏繞。","notes":[]},{"n":23,"t":"他因不受訓誨就必死亡；又因愚昧過甚，必走差了路。","notes":[]}]},"6":{"heading":"更多的警告","verses":[{"n":1,"t":"我兒，你若為朋友作保，替外人擊掌，","notes":[]},{"n":2,"t":"你就被口中的話語纏住，被嘴裏的言語捉住。","notes":[]},{"n":3,"t":"我兒，你既落在朋友手中，就當這樣行才可救自己：你要自卑，去懇求你的朋友。","notes":[]},{"n":4,"t":"不要容你的眼睛睡覺；不要容你的眼皮打盹。","notes":[]},{"n":5,"t":"要救自己，如鹿脫離獵戶的手，如鳥脫離捕鳥人的手。","notes":[]},{"n":6,"t":"懶惰人哪，你去察看螞蟻的動作就可得智慧。","notes":[]},{"n":7,"t":"螞蟻沒有元帥，沒有官長，沒有君王，","notes":[]},{"n":8,"t":"尚且在夏天預備食物，在收割時聚斂糧食。","notes":[]},{"n":9,"t":"懶惰人哪，你要睡到幾時呢？你何時睡醒呢？","notes":[]},{"n":10,"t":"再睡片時，打盹片時，抱著手躺臥片時，","notes":[]},{"n":11,"t":"你的貧窮就必如強盜速來，你的缺乏彷彿拿兵器的人來到。","notes":[]},{"n":12,"t":"無賴的惡徒，行動就用乖僻的口，","notes":[]},{"n":13,"t":"用眼傳神，用腳示意，用指點劃，","notes":[]},{"n":14,"t":"心中乖僻，常設惡謀，布散紛爭。","notes":[]},{"n":15,"t":"所以，災難必忽然臨到他身；他必頃刻敗壞，無法可治。","notes":[]},{"n":16,"t":"耶和華所恨惡的有六樣，連他心所憎惡的共有七樣：","notes":[]},{"n":17,"t":"就是高傲的眼，撒謊的舌，流無辜人血的手，","notes":[]},{"n":18,"t":"圖謀惡計的心，飛跑行惡的腳，","notes":[]},{"n":19,"t":"吐謊言的假見證，並弟兄中布散紛爭的人。","notes":[]},{"n":20,"t":"我兒，要謹守你父親的誡命；不可離棄你母親的法則，","notes":["或譯：指教"],"heads":["警告勿犯淫亂"]},{"n":21,"t":"要常繫在你心上，掛在你項上。","notes":[]},{"n":22,"t":"你行走，它必引導你；你躺臥，它必保守你；你睡醒，它必與你談論。","notes":[]},{"n":23,"t":"因為誡命是燈，法則是光，訓誨的責備是生命的道，","notes":["或譯：指教"]},{"n":24,"t":"能保你遠離惡婦，遠離外女諂媚的舌頭。","notes":[]},{"n":25,"t":"你心中不要戀慕她的美色，也不要被她眼皮勾引。","notes":[]},{"n":26,"t":"因為，妓女能使人只剩一塊餅；淫婦獵取人寶貴的生命。","notes":[]},{"n":27,"t":"人若懷裏搋火，衣服豈能不燒呢？","notes":[]},{"n":28,"t":"人若在火炭上走，腳豈能不燙呢？","notes":[]},{"n":29,"t":"親近鄰舍之妻的，也是如此；凡挨近她的，不免受罰。","notes":[]},{"n":30,"t":"賊因飢餓偷竊充飢，人不藐視他，","notes":[]},{"n":31,"t":"若被找著，他必賠還七倍，必將家中所有的盡都償還。","notes":[]},{"n":32,"t":"與婦人行淫的，便是無知；行這事的，必喪掉生命。","notes":[]},{"n":33,"t":"他必受傷損，必被凌辱；他的羞恥不得塗抹。","notes":[]},{"n":34,"t":"因為人的嫉恨成了烈怒，報仇的時候決不留情。","notes":[]},{"n":35,"t":"甚麼贖價，他都不顧；你雖送許多禮物，他也不肯干休。","notes":[]}]},"7":{"heading":"淫亂的婦人","verses":[{"n":1,"t":"我兒，你要遵守我的言語，將我的命令存記在心。","notes":[]},{"n":2,"t":"遵守我的命令就得存活；保守我的法則，好像保守眼中的瞳人，","notes":["或譯：指教"]},{"n":3,"t":"繫在你指頭上，刻在你心版上。","notes":[]},{"n":4,"t":"對智慧說：你是我的姊妹，稱呼聰明為你的親人，","notes":[]},{"n":5,"t":"她就保你遠離淫婦，遠離說諂媚話的外女。","notes":[]},{"n":6,"t":"我曾在我房屋的窗戶內，從我窗欞之間往外觀看：","notes":[]},{"n":7,"t":"見愚蒙人內，少年人中，分明有一個無知的少年人，","notes":[]},{"n":8,"t":"從街上經過，走近淫婦的巷口，直往通她家的路去，","notes":[]},{"n":9,"t":"在黃昏，或晚上，或半夜，或黑暗之中。","notes":[]},{"n":10,"t":"看哪，有一個婦人來迎接他，是妓女的打扮，有詭詐的心思。","notes":[]},{"n":11,"t":"這婦人喧嚷，不守約束，在家裏停不住腳，","notes":[]},{"n":12,"t":"有時在街市上，有時在寬闊處，或在各巷口蹲伏，","notes":[]},{"n":13,"t":"拉住那少年人，與他親嘴，臉無羞恥對他說：","notes":[]},{"n":14,"t":"平安祭在我這裏，今日才還了我所許的願。","notes":[]},{"n":15,"t":"因此，我出來迎接你，懇切求見你的面，恰巧遇見了你。","notes":[]},{"n":16,"t":"我已經用繡花毯子和埃及線織的花紋布鋪了我的床。","notes":[]},{"n":17,"t":"我又用沒藥、沉香、桂皮薰了我的榻。","notes":[]},{"n":18,"t":"你來，我們可以飽享愛情，直到早晨；我們可以彼此親愛歡樂。","notes":[]},{"n":19,"t":"因為我丈夫不在家，出門行遠路；","notes":[]},{"n":20,"t":"他手拿銀囊，必到月望才回家。","notes":[]},{"n":21,"t":"淫婦用許多巧言誘他隨從，用諂媚的嘴逼他同行。","notes":[]},{"n":22,"t":"少年人立刻跟隨她，好像牛往宰殺之地；又像愚昧人帶鎖鍊去受刑罰，","notes":[]},{"n":23,"t":"直等箭穿他的肝；如同雀鳥急入網羅，卻不知是自喪己命。","notes":[]},{"n":24,"t":"眾子啊，現在要聽從我，留心聽我口中的話。","notes":[]},{"n":25,"t":"你的心不可偏向淫婦的道，不要入她的迷途。","notes":[]},{"n":26,"t":"因為，被她傷害仆倒的不少；被她殺戮的而且甚多。","notes":[]},{"n":27,"t":"她的家是在陰間之路，下到死亡之宮。","notes":[]}]},"8":{"heading":"智慧頌","verses":[{"n":1,"t":"智慧豈不呼叫？聰明豈不發聲？","notes":[]},{"n":2,"t":"她在道旁高處的頂上，在十字路口站立，","notes":[]},{"n":3,"t":"在城門旁，在城門口，在城門洞，大聲說：","notes":[]},{"n":4,"t":"眾人哪，我呼叫你們，我向世人發聲。","notes":[]},{"n":5,"t":"說：愚蒙人哪，你們要會悟靈明；愚昧人哪，你們當心裏明白。","notes":[]},{"n":6,"t":"你們當聽，因我要說極美的話；我張嘴要論正直的事。","notes":[]},{"n":7,"t":"我的口要發出真理；我的嘴憎惡邪惡。","notes":[]},{"n":8,"t":"我口中的言語都是公義，並無彎曲乖僻。","notes":[]},{"n":9,"t":"有聰明的，以為明顯，得知識的，以為正直。","notes":[]},{"n":10,"t":"你們當受我的教訓，不受白銀；寧得知識，勝過黃金。","notes":[]},{"n":11,"t":"因為智慧比珍珠更美；一切可喜愛的都不足與比較。","notes":["或譯：紅寶石"]},{"n":12,"t":"我－智慧以靈明為居所，又尋得知識和謀略。","notes":[]},{"n":13,"t":"敬畏耶和華在乎恨惡邪惡；那驕傲、狂妄，並惡道，以及乖謬的口，都為我所恨惡。","notes":[]},{"n":14,"t":"我有謀略和真知識；我乃聰明，我有能力。","notes":[]},{"n":15,"t":"帝王藉我坐國位；君王藉我定公平。","notes":[]},{"n":16,"t":"王子和首領，世上一切的審判官，都是藉我掌權。","notes":[]},{"n":17,"t":"愛我的，我也愛他；懇切尋求我的，必尋得見。","notes":[]},{"n":18,"t":"豐富尊榮在我；恆久的財並公義也在我。","notes":[]},{"n":19,"t":"我的果實勝過黃金，強如精金；我的出產超乎高銀。","notes":[]},{"n":20,"t":"我在公義的道上走，在公平的路中行，","notes":[]},{"n":21,"t":"使愛我的，承受貨財，並充滿他們的府庫。","notes":[]},{"n":22,"t":"在耶和華造化的起頭，在太初創造萬物之先，就有了我。","notes":[]},{"n":23,"t":"從亙古，從太初，未有世界以前，我已被立。","notes":[]},{"n":24,"t":"沒有深淵，沒有大水的泉源，我已生出。","notes":[]},{"n":25,"t":"大山未曾奠定，小山未有之先，我已生出。","notes":[]},{"n":26,"t":"耶和華還沒有創造大地和田野，並世上的土質，我已生出。","notes":[]},{"n":27,"t":"他立高天，我在那裏；他在淵面的周圍，劃出圓圈。","notes":[]},{"n":28,"t":"上使穹蒼堅硬，下使淵源穩固，","notes":[]},{"n":29,"t":"為滄海定出界限，使水不越過他的命令，立定大地的根基。","notes":[]},{"n":30,"t":"那時，我在他那裏為工師，日日為他所喜愛，常常在他面前踴躍，","notes":[]},{"n":31,"t":"踴躍在他為人預備可住之地，也喜悅住在世人之間。","notes":[]},{"n":32,"t":"眾子啊，現在要聽從我，因為謹守我道的，便為有福。","notes":[]},{"n":33,"t":"要聽教訓就得智慧，不可棄絕。","notes":[]},{"n":34,"t":"聽從我、日日在我門口仰望、在我門框旁邊等候的，那人便為有福。","notes":[]},{"n":35,"t":"因為尋得我的，就尋得生命，也必蒙耶和華的恩惠。","notes":[]},{"n":36,"t":"得罪我的，卻害了自己的性命；恨惡我的，都喜愛死亡。","notes":[]}]},"9":{"heading":"智慧和愚蠢","verses":[{"n":1,"t":"智慧建造房屋，鑿成七根柱子，","notes":[]},{"n":2,"t":"宰殺牲畜，調和旨酒，設擺筵席；","notes":[]},{"n":3,"t":"打發使女出去，自己在城中至高處呼叫，","notes":[]},{"n":4,"t":"說：誰是愚蒙人，可以轉到這裏來！又對那無知的人說：","notes":[]},{"n":5,"t":"你們來，吃我的餅，喝我調和的酒。","notes":[]},{"n":6,"t":"你們愚蒙人，要捨棄愚蒙，就得存活，並要走光明的道。","notes":[]},{"n":7,"t":"指斥褻慢人的，必受辱罵；責備惡人的，必被玷污。","notes":[]},{"n":8,"t":"不要責備褻慢人，恐怕他恨你；要責備智慧人，他必愛你。","notes":[]},{"n":9,"t":"教導智慧人，他就越發有智慧；指示義人，他就增長學問。","notes":[]},{"n":10,"t":"敬畏耶和華是智慧的開端；認識至聖者便是聰明。","notes":[]},{"n":11,"t":"你藉著我，日子必增多，年歲也必加添。","notes":[]},{"n":12,"t":"你若有智慧，是與自己有益；你若褻慢，就必獨自擔當。","notes":[]},{"n":13,"t":"愚昧的婦人喧嚷；她是愚蒙，一無所知。","notes":[]},{"n":14,"t":"她坐在自己的家門口，坐在城中高處的座位上，","notes":[]},{"n":15,"t":"呼叫過路的，就是直行其道的人，","notes":[]},{"n":16,"t":"說：誰是愚蒙人，可以轉到這裏來！又對那無知的人說：","notes":[]},{"n":17,"t":"偷來的水是甜的，暗吃的餅是好的。","notes":[]},{"n":18,"t":"人卻不知有陰魂在她那裏；她的客在陰間的深處。","notes":[]}]},"10":{"heading":"所羅門的箴言","verses":[{"n":1,"t":"所羅門的箴言：智慧之子使父親歡樂；愚昧之子叫母親擔憂。","notes":[]},{"n":2,"t":"不義之財毫無益處；惟有公義能救人脫離死亡。","notes":[]},{"n":3,"t":"耶和華不使義人受飢餓；惡人所欲的，他必推開。","notes":[]},{"n":4,"t":"手懶的，要受貧窮；手勤的，卻要富足。","notes":[]},{"n":5,"t":"夏天聚斂的，是智慧之子；收割時沉睡的，是貽羞之子。","notes":[]},{"n":6,"t":"福祉臨到義人的頭；強暴蒙蔽惡人的口。","notes":[]},{"n":7,"t":"義人的紀念被稱讚；惡人的名字必朽爛。","notes":[]},{"n":8,"t":"心中智慧的，必受命令；口裏愚妄的，必致傾倒。","notes":[]},{"n":9,"t":"行正直路的，步步安穩；走彎曲道的，必致敗露。","notes":[]},{"n":10,"t":"以眼傳神的，使人憂患；口裏愚妄的，必致傾倒。","notes":[]},{"n":11,"t":"義人的口是生命的泉源；強暴蒙蔽惡人的口。","notes":[]},{"n":12,"t":"恨能挑啟爭端；愛能遮掩一切過錯。","notes":[]},{"n":13,"t":"明哲人嘴裏有智慧；無知人背上受刑杖。","notes":[]},{"n":14,"t":"智慧人積存知識；愚妄人的口速致敗壞。","notes":[]},{"n":15,"t":"富戶的財物是他的堅城；窮人的貧乏是他的敗壞。","notes":[]},{"n":16,"t":"義人的勤勞致生；惡人的進項致死。","notes":["死：原文是罪"]},{"n":17,"t":"謹守訓誨的，乃在生命的道上；違棄責備的，便失迷了路。","notes":[]},{"n":18,"t":"隱藏怨恨的，有說謊的嘴；口出讒謗的，是愚妄的人。","notes":[]},{"n":19,"t":"多言多語難免有過；禁止嘴唇是有智慧。","notes":[]},{"n":20,"t":"義人的舌乃似高銀；惡人的心所值無幾。","notes":[]},{"n":21,"t":"義人的口教養多人；愚昧人因無知而死亡。","notes":[]},{"n":22,"t":"耶和華所賜的福使人富足，並不加上憂慮。","notes":[]},{"n":23,"t":"愚妄人以行惡為戲耍；明哲人卻以智慧為樂。","notes":[]},{"n":24,"t":"惡人所怕的，必臨到他；義人所願的，必蒙應允。","notes":[]},{"n":25,"t":"暴風一過，惡人歸於無有；義人的根基卻是永久。","notes":[]},{"n":26,"t":"懶惰人叫差他的人如醋倒牙，如煙薰目。","notes":[]},{"n":27,"t":"敬畏耶和華使人日子加多；但惡人的年歲必被減少。","notes":[]},{"n":28,"t":"義人的盼望必得喜樂；惡人的指望必致滅沒。","notes":[]},{"n":29,"t":"耶和華的道是正直人的保障，卻成了作孽人的敗壞。","notes":[]},{"n":30,"t":"義人永不挪移；惡人不得住在地上。","notes":[]},{"n":31,"t":"義人的口滋生智慧；乖謬的舌必被割斷。","notes":[]},{"n":32,"t":"義人的嘴能令人喜悅；惡人的口說乖謬的話。","notes":[]}]},"11":{"heading":"","verses":[{"n":1,"t":"詭詐的天平為耶和華所憎惡；公平的法碼為他所喜悅。","notes":[]},{"n":2,"t":"驕傲來，羞恥也來；謙遜人卻有智慧。","notes":[]},{"n":3,"t":"正直人的純正必引導自己；奸詐人的乖僻必毀滅自己。","notes":[]},{"n":4,"t":"發怒的日子資財無益；惟有公義能救人脫離死亡。","notes":[]},{"n":5,"t":"完全人的義必指引他的路；但惡人必因自己的惡跌倒。","notes":[]},{"n":6,"t":"正直人的義必拯救自己；奸詐人必陷在自己的罪孽中。","notes":[]},{"n":7,"t":"惡人一死，他的指望必滅絕；罪人的盼望也必滅沒。","notes":[]},{"n":8,"t":"義人得脫離患難，有惡人來代替他。","notes":[]},{"n":9,"t":"不虔敬的人用口敗壞鄰舍；義人卻因知識得救。","notes":[]},{"n":10,"t":"義人享福，合城喜樂；惡人滅亡，人都歡呼。","notes":[]},{"n":11,"t":"城因正直人祝福便高舉，卻因邪惡人的口就傾覆。","notes":[]},{"n":12,"t":"藐視鄰舍的，毫無智慧；明哲人卻靜默不言。","notes":[]},{"n":13,"t":"往來傳舌的，洩漏密事；心中誠實的，遮隱事情。","notes":[]},{"n":14,"t":"無智謀，民就敗落；謀士多，人便安居。","notes":[]},{"n":15,"t":"為外人作保的，必受虧損；恨惡擊掌的，卻得安穩。","notes":[]},{"n":16,"t":"恩德的婦女得尊榮；強暴的男子得資財。","notes":[]},{"n":17,"t":"仁慈的人善待自己；殘忍的人擾害己身。","notes":[]},{"n":18,"t":"惡人經營，得虛浮的工價；撒義種的，得實在的果效。","notes":[]},{"n":19,"t":"恆心為義的，必得生命；追求邪惡的，必致死亡。","notes":[]},{"n":20,"t":"心中乖僻的，為耶和華所憎惡；行事完全的，為他所喜悅。","notes":[]},{"n":21,"t":"惡人雖然連手，必不免受罰；義人的後裔必得拯救。","notes":[]},{"n":22,"t":"婦女美貌而無見識，如同金環帶在豬鼻上。","notes":[]},{"n":23,"t":"義人的心願盡得好處；惡人的指望致干忿怒。","notes":[]},{"n":24,"t":"有施散的，卻更增添；有吝惜過度的，反致窮乏。","notes":[]},{"n":25,"t":"好施捨的，必得豐裕；滋潤人的，必得滋潤。","notes":[]},{"n":26,"t":"屯糧不賣的，民必咒詛他；情願出賣的，人必為他祝福。","notes":[]},{"n":27,"t":"懇切求善的，就求得恩惠；惟獨求惡的，惡必臨到他身。","notes":[]},{"n":28,"t":"倚仗自己財物的，必跌倒；義人必發旺，如青葉。","notes":[]},{"n":29,"t":"擾害己家的，必承受清風；愚昧人必作慧心人的僕人。","notes":[]},{"n":30,"t":"義人所結的果子就是生命樹；有智慧的，必能得人。","notes":[]},{"n":31,"t":"看哪，義人在世尚且受報，何況惡人和罪人呢？","notes":[]}]},"12":{"heading":"","verses":[{"n":1,"t":"喜愛管教的，就是喜愛知識；恨惡責備的，卻是畜類。","notes":[]},{"n":2,"t":"善人必蒙耶和華的恩惠；設詭計的人，耶和華必定他的罪。","notes":[]},{"n":3,"t":"人靠惡行不能堅立；義人的根必不動搖。","notes":[]},{"n":4,"t":"才德的婦人是丈夫的冠冕；貽羞的婦人如同朽爛在她丈夫的骨中。","notes":[]},{"n":5,"t":"義人的思念是公平；惡人的計謀是詭詐。","notes":[]},{"n":6,"t":"惡人的言論是埋伏流人的血；正直人的口必拯救人。","notes":[]},{"n":7,"t":"惡人傾覆，歸於無有；義人的家必站得住。","notes":[]},{"n":8,"t":"人必按自己的智慧被稱讚；心中乖謬的，必被藐視。","notes":[]},{"n":9,"t":"被人輕賤，卻有僕人，強如自尊，缺少食物。","notes":[]},{"n":10,"t":"義人顧惜他牲畜的命；惡人的憐憫也是殘忍。","notes":[]},{"n":11,"t":"耕種自己田地的，必得飽食；追隨虛浮的，卻是無知。","notes":[]},{"n":12,"t":"惡人想得壞人的網羅；義人的根得以結實。","notes":[]},{"n":13,"t":"惡人嘴中的過錯是自己的網羅；但義人必脫離患難。","notes":[]},{"n":14,"t":"人因口所結的果子，必飽得美福；人手所做的，必為自己的報應。","notes":[]},{"n":15,"t":"愚妄人所行的，在自己眼中看為正直；惟智慧人肯聽人的勸教。","notes":[]},{"n":16,"t":"愚妄人的惱怒立時顯露；通達人能忍辱藏羞。","notes":[]},{"n":17,"t":"說出真話的，顯明公義；作假見證的，顯出詭詐。","notes":[]},{"n":18,"t":"說話浮躁的，如刀刺人；智慧人的舌頭卻為醫人的良藥。","notes":[]},{"n":19,"t":"口吐真言，永遠堅立；舌說謊話，只存片時。","notes":[]},{"n":20,"t":"圖謀惡事的，心存詭詐；勸人和睦的，便得喜樂。","notes":[]},{"n":21,"t":"義人不遭災害；惡人滿受禍患。","notes":[]},{"n":22,"t":"說謊言的嘴為耶和華所憎惡；行事誠實的，為他所喜悅。","notes":[]},{"n":23,"t":"通達人隱藏知識；愚昧人的心彰顯愚昧。","notes":[]},{"n":24,"t":"殷勤人的手必掌權；懶惰的人必服苦。","notes":[]},{"n":25,"t":"人心憂慮，屈而不伸；一句良言，使心歡樂。","notes":[]},{"n":26,"t":"義人引導他的鄰舍；惡人的道叫人失迷。","notes":[]},{"n":27,"t":"懶惰的人不烤打獵所得的；殷勤的人卻得寶貴的財物。","notes":[]},{"n":28,"t":"在公義的道上有生命；其路之中並無死亡。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"智慧子聽父親的教訓；褻慢人不聽責備。","notes":[]},{"n":2,"t":"人因口所結的果子，必享美福；奸詐人必遭強暴。","notes":[]},{"n":3,"t":"謹守口的，得保生命；大張嘴的，必致敗亡。","notes":[]},{"n":4,"t":"懶惰人羨慕，卻無所得；殷勤人必得豐裕。","notes":[]},{"n":5,"t":"義人恨惡謊言；惡人有臭名，且致慚愧。","notes":[]},{"n":6,"t":"行為正直的，有公義保守；犯罪的，被邪惡傾覆。","notes":[]},{"n":7,"t":"假作富足的，卻一無所有；裝作窮乏的，卻廣有財物。","notes":[]},{"n":8,"t":"人的資財是他生命的贖價；窮乏人卻聽不見威嚇的話。","notes":[]},{"n":9,"t":"義人的光明亮；惡人的燈要熄滅。","notes":["原文是歡喜"]},{"n":10,"t":"驕傲只啟爭競；聽勸言的，卻有智慧。","notes":[]},{"n":11,"t":"不勞而得之財必然消耗；勤勞積蓄的，必見加增。","notes":[]},{"n":12,"t":"所盼望的遲延未得，令人心憂；所願意的臨到，卻是生命樹。","notes":[]},{"n":13,"t":"藐視訓言的，自取滅亡；敬畏誡命的，必得善報。","notes":[]},{"n":14,"t":"智慧人的法則是生命的泉源，可以使人離開死亡的網羅。","notes":["或譯：指教"]},{"n":15,"t":"美好的聰明使人蒙恩；奸詐人的道路崎嶇難行。","notes":[]},{"n":16,"t":"凡通達人都憑知識行事；愚昧人張揚自己的愚昧。","notes":[]},{"n":17,"t":"奸惡的使者必陷在禍患裏；忠信的使臣乃醫人的良藥。","notes":[]},{"n":18,"t":"棄絕管教的，必致貧受辱；領受責備的，必得尊榮。","notes":[]},{"n":19,"t":"所欲的成就，心覺甘甜；遠離惡事，為愚昧人所憎惡。","notes":[]},{"n":20,"t":"與智慧人同行的，必得智慧；和愚昧人作伴的，必受虧損。","notes":[]},{"n":21,"t":"禍患追趕罪人；義人必得善報。","notes":[]},{"n":22,"t":"善人給子孫遺留產業；罪人為義人積存資財。","notes":[]},{"n":23,"t":"窮人耕種多得糧食，但因不義，有消滅的。","notes":[]},{"n":24,"t":"不忍用杖打兒子的，是恨惡他；疼愛兒子的，隨時管教。","notes":[]},{"n":25,"t":"義人吃得飽足；惡人肚腹缺糧。","notes":[]}]},"14":{"heading":"","verses":[{"n":1,"t":"智慧婦人建立家室；愚妄婦人親手拆毀。","notes":[]},{"n":2,"t":"行動正直的，敬畏耶和華；行事乖僻的，卻藐視他。","notes":[]},{"n":3,"t":"愚妄人口中驕傲，如杖責打己身；智慧人的嘴必保守自己。","notes":[]},{"n":4,"t":"家裏無牛，槽頭乾淨；土產加多乃憑牛力。","notes":[]},{"n":5,"t":"誠實見證人不說謊話；假見證人吐出謊言。","notes":[]},{"n":6,"t":"褻慢人尋智慧，卻尋不著；聰明人易得知識。","notes":[]},{"n":7,"t":"到愚昧人面前，不見他嘴中有知識。","notes":[]},{"n":8,"t":"通達人的智慧在乎明白己道；愚昧人的愚妄乃是詭詐。","notes":["或譯：自欺"]},{"n":9,"t":"愚妄人犯罪，以為戲耍；正直人互相喜悅。","notes":["或譯：贖愆祭愚弄愚妄人"]},{"n":10,"t":"心中的苦楚，自己知道；心裏的喜樂，外人無干。","notes":[]},{"n":11,"t":"奸惡人的房屋必傾倒；正直人的帳棚必興盛。","notes":[]},{"n":12,"t":"有一條路，人以為正，至終成為死亡之路。","notes":[]},{"n":13,"t":"人在喜笑中，心也憂愁；快樂至極就生愁苦。","notes":[]},{"n":14,"t":"心中背道的，必滿得自己的結果；善人必從自己的行為得以知足。","notes":[]},{"n":15,"t":"愚蒙人是話都信；通達人步步謹慎。","notes":[]},{"n":16,"t":"智慧人懼怕，就遠離惡事；愚妄人卻狂傲自恃。","notes":[]},{"n":17,"t":"輕易發怒的，行事愚妄；設立詭計的，被人恨惡。","notes":[]},{"n":18,"t":"愚蒙人得愚昧為產業；通達人得知識為冠冕。","notes":[]},{"n":19,"t":"壞人俯伏在善人面前；惡人俯伏在義人門口。","notes":[]},{"n":20,"t":"貧窮人連鄰舍也恨他；富足人朋友最多。","notes":[]},{"n":21,"t":"藐視鄰舍的，這人有罪；憐憫貧窮的，這人有福。","notes":[]},{"n":22,"t":"謀惡的，豈非走入迷途嗎？謀善的，必得慈愛和誠實。","notes":[]},{"n":23,"t":"諸般勤勞都有益處；嘴上多言乃致窮乏。","notes":[]},{"n":24,"t":"智慧人的財為自己的冠冕；愚妄人的愚昧終是愚昧。","notes":[]},{"n":25,"t":"作真見證的，救人性命；吐出謊言的，施行詭詐。","notes":[]},{"n":26,"t":"敬畏耶和華的，大有倚靠；他的兒女也有避難所。","notes":[]},{"n":27,"t":"敬畏耶和華就是生命的泉源，可以使人離開死亡的網羅。","notes":[]},{"n":28,"t":"帝王榮耀在乎民多；君王衰敗在乎民少。","notes":[]},{"n":29,"t":"不輕易發怒的，大有聰明；性情暴躁的，大顯愚妄。","notes":[]},{"n":30,"t":"心中安靜是肉體的生命；嫉妒是骨中的朽爛。","notes":[]},{"n":31,"t":"欺壓貧寒的，是辱沒造他的主；憐憫窮乏的，乃是尊敬主。","notes":[]},{"n":32,"t":"惡人在所行的惡上必被推倒；義人臨死，有所投靠。","notes":[]},{"n":33,"t":"智慧存在聰明人心中；愚昧人心裏所存的，顯而易見。","notes":[]},{"n":34,"t":"公義使邦國高舉；罪惡是人民的羞辱。","notes":[]},{"n":35,"t":"智慧的臣子蒙王恩惠；貽羞的僕人遭其震怒。","notes":[]}]},"15":{"heading":"","verses":[{"n":1,"t":"回答柔和，使怒消退；言語暴戾，觸動怒氣。","notes":[]},{"n":2,"t":"智慧人的舌善發知識；愚昧人的口吐出愚昧。","notes":[]},{"n":3,"t":"耶和華的眼目無處不在；惡人善人，他都鑒察。","notes":[]},{"n":4,"t":"溫良的舌是生命樹；乖謬的嘴使人心碎。","notes":[]},{"n":5,"t":"愚妄人藐視父親的管教；領受責備的，得著見識。","notes":[]},{"n":6,"t":"義人家中多有財寶；惡人得利反受擾害。","notes":[]},{"n":7,"t":"智慧人的嘴播揚知識；愚昧人的心並不如此。","notes":[]},{"n":8,"t":"惡人獻祭，為耶和華所憎惡；正直人祈禱，為他所喜悅。","notes":[]},{"n":9,"t":"惡人的道路，為耶和華所憎惡；追求公義的，為他所喜愛。","notes":[]},{"n":10,"t":"捨棄正路的，必受嚴刑；恨惡責備的，必致死亡。","notes":[]},{"n":11,"t":"陰間和滅亡尚在耶和華眼前，何況世人的心呢？","notes":[]},{"n":12,"t":"褻慢人不愛受責備；他也不就近智慧人。","notes":[]},{"n":13,"t":"心中喜樂，面帶笑容；心裏憂愁，靈被損傷。","notes":[]},{"n":14,"t":"聰明人心求知識；愚昧人口吃愚昧。","notes":[]},{"n":15,"t":"困苦人的日子都是愁苦；心中歡暢的，常享豐筵。","notes":[]},{"n":16,"t":"少有財寶，敬畏耶和華，強如多有財寶，煩亂不安。","notes":[]},{"n":17,"t":"吃素菜，彼此相愛，強如吃肥牛，彼此相恨。","notes":[]},{"n":18,"t":"暴怒的人挑啟爭端；忍怒的人止息紛爭。","notes":[]},{"n":19,"t":"懶惰人的道像荊棘的籬笆；正直人的路是平坦的大道。","notes":[]},{"n":20,"t":"智慧子使父親喜樂；愚昧人藐視母親。","notes":[]},{"n":21,"t":"無知的人以愚妄為樂；聰明的人按正直而行。","notes":[]},{"n":22,"t":"不先商議，所謀無效；謀士眾多，所謀乃成。","notes":[]},{"n":23,"t":"口善應對，自覺喜樂；話合其時，何等美好。","notes":[]},{"n":24,"t":"智慧人從生命的道上升，使他遠離在下的陰間。","notes":[]},{"n":25,"t":"耶和華必拆毀驕傲人的家，卻要立定寡婦的地界。","notes":[]},{"n":26,"t":"惡謀為耶和華所憎惡；良言乃為純淨。","notes":[]},{"n":27,"t":"貪戀財利的，擾害己家；恨惡賄賂的，必得存活。","notes":[]},{"n":28,"t":"義人的心，思量如何回答；惡人的口吐出惡言。","notes":[]},{"n":29,"t":"耶和華遠離惡人，卻聽義人的禱告。","notes":[]},{"n":30,"t":"眼有光，使心喜樂；好信息，使骨滋潤。","notes":[]},{"n":31,"t":"聽從生命責備的，必常在智慧人中。","notes":[]},{"n":32,"t":"棄絕管教的，輕看自己的生命；聽從責備的，卻得智慧。","notes":[]},{"n":33,"t":"敬畏耶和華是智慧的訓誨；尊榮以前，必有謙卑。","notes":[]}]},"16":{"heading":"","verses":[{"n":1,"t":"心中的謀算在乎人；舌頭的應對由於耶和華。","notes":[]},{"n":2,"t":"人一切所行的，在自己眼中看為清潔；惟有耶和華衡量人心。","notes":[]},{"n":3,"t":"你所做的，要交託耶和華，你所謀的，就必成立。","notes":[]},{"n":4,"t":"耶和華所造的，各適其用；就是惡人也為禍患的日子所造。","notes":[]},{"n":5,"t":"凡心裏驕傲的，為耶和華所憎惡；雖然連手，他必不免受罰。","notes":[]},{"n":6,"t":"因憐憫誠實，罪孽得贖；敬畏耶和華的，遠離惡事。","notes":[]},{"n":7,"t":"人所行的，若蒙耶和華喜悅，耶和華也使他的仇敵與他和好。","notes":[]},{"n":8,"t":"多有財利，行事不義，不如少有財利，行事公義。","notes":[]},{"n":9,"t":"人心籌算自己的道路；惟耶和華指引他的腳步。","notes":[]},{"n":10,"t":"王的嘴中有神語，審判之時，他的口必不差錯。","notes":[]},{"n":11,"t":"公道的天平和秤都屬耶和華；囊中一切法碼都為他所定。","notes":[]},{"n":12,"t":"作惡，為王所憎惡，因國位是靠公義堅立。","notes":[]},{"n":13,"t":"公義的嘴為王所喜悅；說正直話的，為王所喜愛。","notes":[]},{"n":14,"t":"王的震怒如殺人的使者；但智慧人能止息王怒。","notes":[]},{"n":15,"t":"王的臉光使人有生命；王的恩典好像春雲時雨。","notes":[]},{"n":16,"t":"得智慧勝似得金子；選聰明強如選銀子。","notes":[]},{"n":17,"t":"正直人的道是遠離惡事；謹守己路的，是保全性命。","notes":[]},{"n":18,"t":"驕傲在敗壞以先；狂心在跌倒之前。","notes":[]},{"n":19,"t":"心裏謙卑與窮乏人來往，強如將擄物與驕傲人同分。","notes":[]},{"n":20,"t":"謹守訓言的，必得好處；倚靠耶和華的，便為有福。","notes":[]},{"n":21,"t":"心中有智慧，必稱為通達人；嘴中的甜言，加增人的學問。","notes":[]},{"n":22,"t":"人有智慧就有生命的泉源；愚昧人必被愚昧懲治。","notes":[]},{"n":23,"t":"智慧人的心教訓他的口，又使他的嘴增長學問。","notes":[]},{"n":24,"t":"良言如同蜂房，使心覺甘甜，使骨得醫治。","notes":[]},{"n":25,"t":"有一條路，人以為正，至終成為死亡之路。","notes":[]},{"n":26,"t":"勞力人的胃口使他勞力，因為他的口腹催逼他。","notes":[]},{"n":27,"t":"匪徒圖謀奸惡，嘴上彷彿有燒焦的火。","notes":[]},{"n":28,"t":"乖僻人播散紛爭；傳舌的，離間密友。","notes":[]},{"n":29,"t":"強暴人誘惑鄰舍，領他走不善之道。","notes":[]},{"n":30,"t":"眼目緊合的，圖謀乖僻；嘴唇緊閉的，成就邪惡。","notes":[]},{"n":31,"t":"白髮是榮耀的冠冕，在公義的道上必能得著。","notes":[]},{"n":32,"t":"不輕易發怒的，勝過勇士；治服己心的，強如取城。","notes":[]},{"n":33,"t":"籤放在懷裏，定事由耶和華。","notes":[]}]},"17":{"heading":"","verses":[{"n":1,"t":"設筵滿屋，大家相爭，不如有塊乾餅，大家相安。","notes":[]},{"n":2,"t":"僕人辦事聰明，必管轄貽羞之子，又在眾子中同分產業。","notes":[]},{"n":3,"t":"鼎為煉銀，爐為煉金；惟有耶和華熬煉人心。","notes":[]},{"n":4,"t":"行惡的，留心聽奸詐之言；說謊的，側耳聽邪惡之語。","notes":[]},{"n":5,"t":"戲笑窮人的，是辱沒造他的主；幸災樂禍的，必不免受罰。","notes":[]},{"n":6,"t":"子孫為老人的冠冕；父親是兒女的榮耀。","notes":[]},{"n":7,"t":"愚頑人說美言本不相宜，何況君王說謊話呢？","notes":[]},{"n":8,"t":"賄賂在餽送的人眼中看為寶玉，隨處運動都得順利。","notes":[]},{"n":9,"t":"遮掩人過的，尋求人愛；屢次挑錯的，離間密友。","notes":[]},{"n":10,"t":"一句責備話深入聰明人的心，強如責打愚昧人一百下。","notes":[]},{"n":11,"t":"惡人只尋背叛，所以必有嚴厲的使者奉差攻擊他。","notes":[]},{"n":12,"t":"寧可遇見丟崽子的母熊，不可遇見正行愚妄的愚昧人。","notes":[]},{"n":13,"t":"以惡報善的，禍患必不離他的家。","notes":[]},{"n":14,"t":"紛爭的起頭如水放開，所以，在爭鬧之先必當止息爭競。","notes":[]},{"n":15,"t":"定惡人為義的，定義人為惡的，這都為耶和華所憎惡。","notes":[]},{"n":16,"t":"愚昧人既無聰明，為何手拿價銀買智慧呢？","notes":[]},{"n":17,"t":"朋友乃時常親愛，弟兄為患難而生。","notes":[]},{"n":18,"t":"在鄰舍面前擊掌作保乃是無知的人。","notes":[]},{"n":19,"t":"喜愛爭競的，是喜愛過犯；高立家門的，乃自取敗壞。","notes":[]},{"n":20,"t":"心存邪僻的，尋不著好處；舌弄是非的，陷在禍患中。","notes":[]},{"n":21,"t":"生愚昧子的，必自愁苦；愚頑人的父毫無喜樂。","notes":[]},{"n":22,"t":"喜樂的心乃是良藥；憂傷的靈使骨枯乾。","notes":[]},{"n":23,"t":"惡人暗中受賄賂，為要顛倒判斷。","notes":[]},{"n":24,"t":"明哲人眼前有智慧；愚昧人眼望地極。","notes":[]},{"n":25,"t":"愚昧子使父親愁煩，使母親憂苦。","notes":[]},{"n":26,"t":"刑罰義人為不善；責打君子為不義。","notes":[]},{"n":27,"t":"寡少言語的，有知識；性情溫良的，有聰明。","notes":[]},{"n":28,"t":"愚昧人若靜默不言也可算為智慧；閉口不說也可算為聰明。","notes":[]}]},"18":{"heading":"","verses":[{"n":1,"t":"與眾寡合的，獨自尋求心願，並惱恨一切真智慧。","notes":[]},{"n":2,"t":"愚昧人不喜愛明哲，只喜愛顯露心意。","notes":[]},{"n":3,"t":"惡人來，藐視隨來；羞恥到，辱罵同到。","notes":[]},{"n":4,"t":"人口中的言語如同深水；智慧的泉源好像湧流的河水。","notes":[]},{"n":5,"t":"瞻徇惡人的情面，偏斷義人的案件，都為不善。","notes":[]},{"n":6,"t":"愚昧人張嘴啟爭端，開口招鞭打。","notes":[]},{"n":7,"t":"愚昧人的口自取敗壞；他的嘴是他生命的網羅。","notes":[]},{"n":8,"t":"傳舌人的言語如同美食，深入人的心腹。","notes":[]},{"n":9,"t":"做工懈怠的，與浪費人為弟兄。","notes":[]},{"n":10,"t":"耶和華的名是堅固臺；義人奔入便得安穩。","notes":[]},{"n":11,"t":"富足人的財物是他的堅城，在他心想，猶如高牆。","notes":[]},{"n":12,"t":"敗壞之先，人心驕傲；尊榮以前，必有謙卑。","notes":[]},{"n":13,"t":"未曾聽完先回答的，便是他的愚昧和羞辱。","notes":[]},{"n":14,"t":"人有疾病，心能忍耐；心靈憂傷，誰能承當呢？","notes":[]},{"n":15,"t":"聰明人的心得知識；智慧人的耳求知識。","notes":[]},{"n":16,"t":"人的禮物為他開路，引他到高位的人面前。","notes":[]},{"n":17,"t":"先訴情由的，似乎有理；但鄰舍來到，就察出實情。","notes":[]},{"n":18,"t":"掣籤能止息爭競，也能解散強勝的人。","notes":[]},{"n":19,"t":"弟兄結怨，勸他和好，比取堅固城還難；這樣的爭競如同堅寨的門閂。","notes":[]},{"n":20,"t":"人口中所結的果子，必充滿肚腹；他嘴所出的，必使他飽足。","notes":[]},{"n":21,"t":"生死在舌頭的權下，喜愛它的，必吃它所結的果子。","notes":[]},{"n":22,"t":"得著賢妻的，是得著好處，也是蒙了耶和華的恩惠。","notes":[]},{"n":23,"t":"貧窮人說哀求的話；富足人用威嚇的話回答。","notes":[]},{"n":24,"t":"濫交朋友的，自取敗壞；但有一朋友比弟兄更親密。","notes":[]}]},"19":{"heading":"","verses":[{"n":1,"t":"行為純正的貧窮人勝過乖謬愚妄的富足人。","notes":[]},{"n":2,"t":"心無知識的，乃為不善；腳步急快的，難免犯罪。","notes":[]},{"n":3,"t":"人的愚昧傾敗他的道；他的心也抱怨耶和華。","notes":[]},{"n":4,"t":"財物使朋友增多；但窮人朋友遠離。","notes":[]},{"n":5,"t":"作假見證的，必不免受罰；吐出謊言的，終不能逃脫。","notes":[]},{"n":6,"t":"好施散的，有多人求他的恩情；愛送禮的，人都為他的朋友。","notes":[]},{"n":7,"t":"貧窮人，弟兄都恨他；何況他的朋友，更遠離他！他用言語追隨，他們卻走了。","notes":[]},{"n":8,"t":"得著智慧的，愛惜生命；保守聰明的，必得好處。","notes":[]},{"n":9,"t":"作假見證的，不免受罰；吐出謊言的，也必滅亡。","notes":[]},{"n":10,"t":"愚昧人宴樂度日是不合宜的；何況僕人管轄王子呢？","notes":[]},{"n":11,"t":"人有見識就不輕易發怒；寬恕人的過失便是自己的榮耀。","notes":[]},{"n":12,"t":"王的忿怒好像獅子吼叫；他的恩典卻如草上的甘露。","notes":[]},{"n":13,"t":"愚昧的兒子是父親的禍患；妻子的爭吵如雨連連滴漏。","notes":[]},{"n":14,"t":"房屋錢財是祖宗所遺留的；惟有賢慧的妻是耶和華所賜的。","notes":[]},{"n":15,"t":"懶惰使人沉睡；懈怠的人必受飢餓。","notes":[]},{"n":16,"t":"謹守誡命的，保全生命；輕忽己路的，必致死亡。","notes":[]},{"n":17,"t":"憐憫貧窮的，就是借給耶和華；他的善行，耶和華必償還。","notes":[]},{"n":18,"t":"趁有指望，管教你的兒子；你的心不可任他死亡。","notes":[]},{"n":19,"t":"暴怒的人必受刑罰；你若救他，必須再救。","notes":[]},{"n":20,"t":"你要聽勸教，受訓誨，使你終久有智慧。","notes":[]},{"n":21,"t":"人心多有計謀；惟有耶和華的籌算才能立定。","notes":[]},{"n":22,"t":"施行仁慈的，令人愛慕；窮人強如說謊言的。","notes":[]},{"n":23,"t":"敬畏耶和華的，得著生命；他必恆久知足，不遭禍患。","notes":[]},{"n":24,"t":"懶惰人放手在盤子裏，就是向口撤回，他也不肯。","notes":[]},{"n":25,"t":"鞭打褻慢人，愚蒙人必長見識；責備明哲人，他就明白知識。","notes":[]},{"n":26,"t":"虐待父親、攆出母親的，是貽羞致辱之子。","notes":[]},{"n":27,"t":"我兒，不可聽了教訓而又偏離知識的言語。","notes":[]},{"n":28,"t":"匪徒作見證戲笑公平；惡人的口吞下罪孽。","notes":[]},{"n":29,"t":"刑罰是為褻慢人預備的；鞭打是為愚昧人的背預備的。","notes":[]}]},"20":{"heading":"","verses":[{"n":1,"t":"酒能使人褻慢，濃酒使人喧嚷；凡因酒錯誤的，就無智慧。","notes":[]},{"n":2,"t":"王的威嚇如同獅子吼叫；惹動他怒的，是自害己命。","notes":[]},{"n":3,"t":"遠離紛爭是人的尊榮；愚妄人都愛爭鬧。","notes":[]},{"n":4,"t":"懶惰人因冬寒不肯耕種，到收割的時候，他必討飯而無所得。","notes":[]},{"n":5,"t":"人心懷藏謀略，好像深水，惟明哲人才能汲引出來。","notes":[]},{"n":6,"t":"人多述說自己的仁慈，但忠信人誰能遇著呢？","notes":[]},{"n":7,"t":"行為純正的義人，他的子孫是有福的！","notes":[]},{"n":8,"t":"王坐在審判的位上，以眼目驅散諸惡。","notes":[]},{"n":9,"t":"誰能說，我潔淨了我的心，我脫淨了我的罪？","notes":[]},{"n":10,"t":"兩樣的法碼，兩樣的升斗，都為耶和華所憎惡。","notes":[]},{"n":11,"t":"孩童的動作是清潔，是正直，都顯明他的本性。","notes":[]},{"n":12,"t":"能聽的耳，能看的眼，都是耶和華所造的。","notes":[]},{"n":13,"t":"不要貪睡，免致貧窮；眼要睜開，你就吃飽。","notes":[]},{"n":14,"t":"買物的說：不好，不好；及至買去，他便自誇。","notes":[]},{"n":15,"t":"有金子和許多珍珠，惟有知識的嘴乃為貴重的珍寶。","notes":["或譯：紅寶石"]},{"n":16,"t":"誰為生人作保，就拿誰的衣服；誰為外人作保，誰就要承當。","notes":[]},{"n":17,"t":"以虛謊而得的食物，人覺甘甜；但後來，他的口必充滿塵沙。","notes":[]},{"n":18,"t":"計謀都憑籌算立定；打仗要憑智謀。","notes":[]},{"n":19,"t":"往來傳舌的，洩漏密事；大張嘴的，不可與他結交。","notes":[]},{"n":20,"t":"咒罵父母的，他的燈必滅，變為漆黑的黑暗。","notes":[]},{"n":21,"t":"起初速得的產業，終久卻不為福。","notes":[]},{"n":22,"t":"你不要說，我要以惡報惡；要等候耶和華，他必拯救你。","notes":[]},{"n":23,"t":"兩樣的法碼為耶和華所憎惡；詭詐的天平也為不善。","notes":[]},{"n":24,"t":"人的腳步為耶和華所定；人豈能明白自己的路呢？","notes":[]},{"n":25,"t":"人冒失說，這是聖物，許願之後才查問，就是自陷網羅。","notes":[]},{"n":26,"t":"智慧的王簸散惡人，用碌碡滾軋他們。","notes":[]},{"n":27,"t":"人的靈是耶和華的燈，鑒察人的心腹。","notes":[]},{"n":28,"t":"王因仁慈和誠實得以保全他的國位，也因仁慈立穩。","notes":[]},{"n":29,"t":"強壯乃少年人的榮耀；白髮為老年人的尊榮。","notes":[]},{"n":30,"t":"鞭傷除淨人的罪惡；責打能入人的心腹。","notes":[]}]},"21":{"heading":"","verses":[{"n":1,"t":"王的心在耶和華手中，好像隴溝的水隨意流轉。","notes":[]},{"n":2,"t":"人所行的，在自己眼中都看為正；惟有耶和華衡量人心。","notes":[]},{"n":3,"t":"行仁義公平比獻祭更蒙耶和華悅納。","notes":[]},{"n":4,"t":"惡人發達，眼高心傲，這乃是罪。","notes":["發達：原文是燈"]},{"n":5,"t":"殷勤籌劃的，足致豐裕；行事急躁的，都必缺乏。","notes":[]},{"n":6,"t":"用詭詐之舌求財的，就是自己取死；所得之財乃是吹來吹去的浮雲。","notes":[]},{"n":7,"t":"惡人的強暴必將自己掃除，因他們不肯按公平行事。","notes":[]},{"n":8,"t":"負罪之人的路甚是彎曲；至於清潔的人，他所行的乃是正直。","notes":[]},{"n":9,"t":"寧可住在房頂的角上，不在寬闊的房屋與爭吵的婦人同住。","notes":[]},{"n":10,"t":"惡人的心樂人受禍；他眼並不憐恤鄰舍。","notes":[]},{"n":11,"t":"褻慢的人受刑罰，愚蒙的人就得智慧；智慧人受訓誨，便得知識。","notes":[]},{"n":12,"t":"義人思想惡人的家，知道惡人傾倒，必致滅亡。","notes":[]},{"n":13,"t":"塞耳不聽窮人哀求的，他將來呼籲也不蒙應允。","notes":[]},{"n":14,"t":"暗中送的禮物挽回怒氣；懷中搋的賄賂止息暴怒。","notes":[]},{"n":15,"t":"秉公行義使義人喜樂，使作孽的人敗壞。","notes":[]},{"n":16,"t":"迷離通達道路的，必住在陰魂的會中。","notes":[]},{"n":17,"t":"愛宴樂的，必致窮乏；好酒，愛膏油的，必不富足。","notes":[]},{"n":18,"t":"惡人作了義人的贖價；奸詐人代替正直人。","notes":[]},{"n":19,"t":"寧可住在曠野，不與爭吵使氣的婦人同住。","notes":[]},{"n":20,"t":"智慧人家中積蓄寶物膏油；愚昧人隨得來隨吞下。","notes":[]},{"n":21,"t":"追求公義仁慈的，就尋得生命、公義，和尊榮。","notes":[]},{"n":22,"t":"智慧人爬上勇士的城牆，傾覆他所倚靠的堅壘。","notes":[]},{"n":23,"t":"謹守口與舌的，就保守自己免受災難。","notes":[]},{"n":24,"t":"心驕氣傲的人名叫褻慢；他行事狂妄，都出於驕傲。","notes":[]},{"n":25,"t":"懶惰人的心願將他殺害，因為他手不肯做工。","notes":[]},{"n":26,"t":"有終日貪得無饜的；義人施捨而不吝惜。","notes":[]},{"n":27,"t":"惡人的祭物是可憎的；何況他存惡意來獻呢？","notes":[]},{"n":28,"t":"作假見證的必滅亡；惟有聽真情而言的，其言長存。","notes":[]},{"n":29,"t":"惡人臉無羞恥；正直人行事堅定。","notes":[]},{"n":30,"t":"沒有人能以智慧、聰明、謀略敵擋耶和華。","notes":[]},{"n":31,"t":"馬是為打仗之日預備的；得勝乃在乎耶和華。","notes":[]}]},"22":{"heading":"智言三十則","verses":[{"n":1,"t":"美名勝過大財；恩寵強如金銀。","notes":[]},{"n":2,"t":"富戶窮人在世相遇，都為耶和華所造。","notes":[]},{"n":3,"t":"通達人見禍藏躲；愚蒙人前往受害。","notes":[]},{"n":4,"t":"敬畏耶和華心存謙卑，就得富有、尊榮、生命為賞賜。","notes":[]},{"n":5,"t":"乖僻人的路上有荊棘和網羅；保守自己生命的，必要遠離。","notes":[]},{"n":6,"t":"教養孩童，使他走當行的道，就是到老他也不偏離。","notes":[]},{"n":7,"t":"富戶管轄窮人；欠債的是債主的僕人。","notes":[]},{"n":8,"t":"撒罪孽的，必收災禍；他逞怒的杖也必廢掉。","notes":[]},{"n":9,"t":"眼目慈善的，就必蒙福，因他將食物分給窮人。","notes":[]},{"n":10,"t":"趕出褻慢人，爭端就消除；紛爭和羞辱也必止息。","notes":[]},{"n":11,"t":"喜愛清心的人因他嘴上的恩言，王必與他為友。","notes":[]},{"n":12,"t":"耶和華的眼目眷顧聰明人，卻傾敗奸詐人的言語。","notes":[]},{"n":13,"t":"懶惰人說：外頭有獅子；我在街上就必被殺。","notes":[]},{"n":14,"t":"淫婦的口為深坑；耶和華所憎惡的，必陷在其中。","notes":[]},{"n":15,"t":"愚蒙迷住孩童的心，用管教的杖可以遠遠趕除。","notes":[]},{"n":16,"t":"欺壓貧窮為要利己的，並送禮與富戶的，都必缺乏。","notes":[]},{"n":17,"t":"你須側耳聽受智慧人的言語，留心領會我的知識。","notes":[]},{"n":18,"t":"你若心中存記，嘴上咬定，這便為美。","notes":[]},{"n":19,"t":"我今日以此特特指教你，為要使你倚靠耶和華。","notes":[]},{"n":20,"t":"謀略和知識的美事，我豈沒有寫給你嗎？","notes":[]},{"n":21,"t":"要使你知道真言的實理，你好將真言回覆那打發你來的人。","notes":[]},{"n":22,"t":"貧窮人，你不可因他貧窮就搶奪他的物，也不可在城門口欺壓困苦人；","notes":[]},{"n":23,"t":"因耶和華必為他辨屈；搶奪他的，耶和華必奪取那人的命。","notes":[]},{"n":24,"t":"好生氣的人，不可與他結交；暴怒的人，不可與他來往；","notes":[]},{"n":25,"t":"恐怕你效法他的行為，自己就陷在網羅裏。","notes":[]},{"n":26,"t":"不要與人擊掌，不要為欠債的作保。","notes":[]},{"n":27,"t":"你若沒有甚麼償還，何必使人奪去你睡臥的床呢？","notes":[]},{"n":28,"t":"你先祖所立的地界，你不可挪移。","notes":[]},{"n":29,"t":"你看見辦事殷勤的人嗎？他必站在君王面前，必不站在下賤人面前。","notes":[]}]},"23":{"heading":"","verses":[{"n":1,"t":"你若與官長坐席，要留意在你面前的是誰。","notes":[]},{"n":2,"t":"你若是貪食的，就當拿刀放在喉嚨上。","notes":[]},{"n":3,"t":"不可貪戀他的美食，因為是哄人的食物。","notes":[]},{"n":4,"t":"不要勞碌求富，休仗自己的聰明。","notes":[]},{"n":5,"t":"你豈要定睛在虛無的錢財上嗎？因錢財必長翅膀，如鷹向天飛去。","notes":[]},{"n":6,"t":"不要吃惡眼人的飯，也不要貪他的美味；","notes":[]},{"n":7,"t":"因為他心怎樣思量，他為人就是怎樣。他雖對你說，請吃，請喝，他的心卻與你相背。","notes":[]},{"n":8,"t":"你所吃的那點食物必吐出來；你所說的甘美言語也必落空。","notes":[]},{"n":9,"t":"你不要說話給愚昧人聽，因他必藐視你智慧的言語。","notes":[]},{"n":10,"t":"不可挪移古時的地界，也不可侵入孤兒的田地；","notes":[]},{"n":11,"t":"因他們的救贖主大有能力，他必向你為他們辨屈。","notes":[]},{"n":12,"t":"你要留心領受訓誨，側耳聽從知識的言語。","notes":[]},{"n":13,"t":"不可不管教孩童；你用杖打他，他必不至於死。","notes":[]},{"n":14,"t":"你要用杖打他，就可以救他的靈魂免下陰間。","notes":[]},{"n":15,"t":"我兒，你心若存智慧，我的心也甚歡喜。","notes":[]},{"n":16,"t":"你的嘴若說正直話，我的心腸也必快樂。","notes":[]},{"n":17,"t":"你心中不要嫉妒罪人，只要終日敬畏耶和華；","notes":[]},{"n":18,"t":"因為至終必有善報，你的指望也不致斷絕。","notes":[]},{"n":19,"t":"我兒，你當聽，當存智慧，好在正道上引導你的心。","notes":[]},{"n":20,"t":"好飲酒的，好吃肉的，不要與他們來往；","notes":[]},{"n":21,"t":"因為好酒貪食的，必致貧窮；好睡覺的，必穿破爛衣服。","notes":[]},{"n":22,"t":"你要聽從生你的父親；你母親老了，也不可藐視她。","notes":[]},{"n":23,"t":"你當買真理；就是智慧、訓誨，和聰明也都不可賣。","notes":[]},{"n":24,"t":"義人的父親必大得快樂；人生智慧的兒子，必因他歡喜。","notes":[]},{"n":25,"t":"你要使父母歡喜，使生你的快樂。","notes":[]},{"n":26,"t":"我兒，要將你的心歸我；你的眼目也要喜悅我的道路。","notes":[]},{"n":27,"t":"妓女是深坑；外女是窄阱。","notes":[]},{"n":28,"t":"她埋伏好像強盜；她使人中多有奸詐的。","notes":[]},{"n":29,"t":"誰有禍患？誰有憂愁？誰有爭鬥？誰有哀歎？誰無故受傷？誰眼目紅赤？","notes":["或譯：怨言"]},{"n":30,"t":"就是那流連飲酒、常去尋找調和酒的人。","notes":[]},{"n":31,"t":"酒發紅，在杯中閃爍，你不可觀看，雖然下咽舒暢，終久是咬你如蛇，刺你如毒蛇。","notes":[],"end":32},{"n":33,"t":"你眼必看見異怪的事；你心必發出乖謬的話。","notes":["或譯：淫婦"]},{"n":34,"t":"你必像躺在海中，或像臥在桅杆上。","notes":[]},{"n":35,"t":"你必說：人打我，我卻未受傷；人鞭打我，我竟不覺得。我幾時清醒，我仍去尋酒。","notes":[]}]},"24":{"heading":"其他智言","verses":[{"n":1,"t":"你不要嫉妒惡人，也不要起意與他們相處；","notes":[]},{"n":2,"t":"因為，他們的心圖謀強暴，他們的口談論奸惡。","notes":[]},{"n":3,"t":"房屋因智慧建造，又因聰明立穩；","notes":[]},{"n":4,"t":"其中因知識充滿各樣美好寶貴的財物。","notes":[]},{"n":5,"t":"智慧人大有能力；有知識的人力上加力。","notes":[]},{"n":6,"t":"你去打仗，要憑智謀；謀士眾多，人便得勝。","notes":[]},{"n":7,"t":"智慧極高，非愚昧人所能及，所以在城門內不敢開口。","notes":[]},{"n":8,"t":"設計作惡的，必稱為奸人。","notes":[]},{"n":9,"t":"愚妄人的思念乃是罪惡；褻慢者為人所憎惡。","notes":[]},{"n":10,"t":"你在患難之日若膽怯，你的力量就微小。","notes":[]},{"n":11,"t":"人被拉到死地，你要解救；人將被殺，你須攔阻。","notes":[]},{"n":12,"t":"你若說：這事我未曾知道，那衡量人心的豈不明白嗎？保守你命的豈不知道嗎？他豈不按各人所行的報應各人嗎？","notes":[]},{"n":13,"t":"我兒，你要吃蜜，因為是好的；吃蜂房下滴的蜜便覺甘甜。","notes":[]},{"n":14,"t":"你心得了智慧，也必覺得如此。你若找著，至終必有善報；你的指望也不致斷絕。","notes":[]},{"n":15,"t":"你這惡人，不要埋伏攻擊義人的家；不要毀壞他安居之所。","notes":[]},{"n":16,"t":"因為，義人雖七次跌倒，仍必興起；惡人卻被禍患傾倒。","notes":[]},{"n":17,"t":"你仇敵跌倒，你不要歡喜；他傾倒，你心不要快樂；","notes":[]},{"n":18,"t":"恐怕耶和華看見就不喜悅，將怒氣從仇敵身上轉過來。","notes":[]},{"n":19,"t":"不要為作惡的心懷不平，也不要嫉妒惡人；","notes":[]},{"n":20,"t":"因為，惡人終不得善報；惡人的燈也必熄滅。","notes":[]},{"n":21,"t":"我兒，你要敬畏耶和華與君王，不要與反覆無常的人結交，","notes":[]},{"n":22,"t":"因為他們的災難必忽然而起。耶和華與君王所施行的毀滅，誰能知道呢？","notes":[]},{"n":23,"t":"以下也是智慧人的箴言：審判時看人情面是不好的。","notes":[]},{"n":24,"t":"對惡人說「你是義人」的，這人萬民必咒詛，列邦必憎惡。","notes":[]},{"n":25,"t":"責備惡人的，必得喜悅；美好的福也必臨到他。","notes":[]},{"n":26,"t":"應對正直的，猶如與人親嘴。","notes":[]},{"n":27,"t":"你要在外頭預備工料，在田間辦理整齊，然後建造房屋。","notes":[]},{"n":28,"t":"不可無故作見證陷害鄰舍，也不可用嘴欺騙人。","notes":[]},{"n":29,"t":"不可說：人怎樣待我，我也怎樣待他；我必照他所行的報復他。","notes":[]},{"n":30,"t":"我經過懶惰人的田地、無知人的葡萄園，","notes":[]},{"n":31,"t":"荊棘長滿了地皮，刺草遮蓋了田面，石牆也坍塌了。","notes":[]},{"n":32,"t":"我看見就留心思想；我看著就領了訓誨。","notes":[]},{"n":33,"t":"再睡片時，打盹片時，抱著手躺臥片時，","notes":[]},{"n":34,"t":"你的貧窮就必如強盜速來，你的缺乏彷彿拿兵器的人來到。","notes":[]}]},"25":{"heading":"所羅門的另一些箴言","verses":[{"n":1,"t":"以下也是所羅門的箴言，是猶大王希西家的人所謄錄的。","notes":[]},{"n":2,"t":"將事隱祕乃神的榮耀；將事察清乃君王的榮耀。","notes":[]},{"n":3,"t":"天之高，地之厚，君王之心也測不透。","notes":[]},{"n":4,"t":"除去銀子的渣滓就有銀子出來，銀匠能以做器皿。","notes":[]},{"n":5,"t":"除去王面前的惡人，國位就靠公義堅立。","notes":[]},{"n":6,"t":"不要在王面前妄自尊大；不要在大人的位上站立。","notes":[]},{"n":7,"t":"寧可有人說：請你上來，強如在你覲見的王子面前叫你退下。","notes":[]},{"n":8,"t":"不要冒失出去與人爭競，免得至終被他羞辱，你就不知道怎樣行了。","notes":[]},{"n":9,"t":"你與鄰舍爭訟，要與他一人辯論，不可洩漏人的密事，","notes":[]},{"n":10,"t":"恐怕聽見的人罵你，你的臭名就難以脫離。","notes":[]},{"n":11,"t":"一句話說得合宜，就如金蘋果在銀網子裏。","notes":[]},{"n":12,"t":"智慧人的勸戒，在順從的人耳中，好像金耳環和精金的妝飾。","notes":[]},{"n":13,"t":"忠信的使者叫差他的人心裏舒暢，就如在收割時有冰雪的涼氣。","notes":[]},{"n":14,"t":"空誇贈送禮物的，好像無雨的風雲。","notes":[]},{"n":15,"t":"恆常忍耐可以勸動君王；柔和的舌頭能折斷骨頭。","notes":[]},{"n":16,"t":"你得了蜜嗎？只可吃夠而已，恐怕你過飽就嘔吐出來。","notes":[]},{"n":17,"t":"你的腳要少進鄰舍的家，恐怕他厭煩你，恨惡你。","notes":[]},{"n":18,"t":"作假見證陷害鄰舍的，就是大槌，是利刀，是快箭。","notes":[]},{"n":19,"t":"患難時倚靠不忠誠的人，好像破壞的牙，錯骨縫的腳。","notes":[]},{"n":20,"t":"對傷心的人唱歌，就如冷天脫衣服，又如鹼上倒醋。","notes":[]},{"n":21,"t":"你的仇敵若餓了，就給他飯吃；若渴了，就給他水喝；","notes":[]},{"n":22,"t":"因為，你這樣行就是把炭火堆在他的頭上；耶和華也必賞賜你。","notes":[]},{"n":23,"t":"北風生雨，讒謗人的舌頭也生怒容。","notes":[]},{"n":24,"t":"寧可住在房頂的角上，不在寬闊的房屋與爭吵的婦人同住。","notes":[]},{"n":25,"t":"有好消息從遠方來，就如拿涼水給口渴的人喝。","notes":[]},{"n":26,"t":"義人在惡人面前退縮，好像渾之泉，弄濁之井。","notes":[]},{"n":27,"t":"吃蜜過多是不好的考究自己的榮耀也是可厭的。","notes":[]},{"n":28,"t":"人不制伏自己的心，好像毀壞的城邑沒有牆垣。","notes":[]}]},"26":{"heading":"","verses":[{"n":1,"t":"夏天落雪，收割時下雨，都不相宜；愚昧人得尊榮也是如此。","notes":[]},{"n":2,"t":"麻雀往來，燕子翻飛；這樣，無故的咒詛也必不臨到。","notes":[]},{"n":3,"t":"鞭子是為打馬，轡頭是為勒驢；刑杖是為打愚昧人的背。","notes":[]},{"n":4,"t":"不要照愚昧人的愚妄話回答他，恐怕你與他一樣。","notes":[]},{"n":5,"t":"要照愚昧人的愚妄話回答他，免得他自以為有智慧。","notes":[]},{"n":6,"t":"藉愚昧人手寄信的，是砍斷自己的腳，自受損害。","notes":["原文是：喝"]},{"n":7,"t":"瘸子的腳空存無用；箴言在愚昧人的口中也是如此。","notes":[]},{"n":8,"t":"將尊榮給愚昧人的，好像人把石子包在機弦裏。","notes":[]},{"n":9,"t":"箴言在愚昧人的口中，好像荊棘刺入醉漢的手。","notes":[]},{"n":10,"t":"雇愚昧人的，與雇過路人的，就像射傷眾人的弓箭手。","notes":[]},{"n":11,"t":"愚昧人行愚妄事，行了又行，就如狗轉過來吃牠所吐的。","notes":[]},{"n":12,"t":"你見自以為有智慧的人嗎？愚昧人比他更有指望。","notes":[]},{"n":13,"t":"懶惰人說：道上有猛獅，街上有壯獅。","notes":[]},{"n":14,"t":"門在樞紐轉動，懶惰人在床上也是如此。","notes":[]},{"n":15,"t":"懶惰人放手在盤子裏，就是向口撤回也以為勞乏。","notes":[]},{"n":16,"t":"懶惰人看自己比七個善於應對的人更有智慧。","notes":[]},{"n":17,"t":"過路被事激動，管理不干己的爭競，好像人揪住狗耳。","notes":[]},{"n":18,"t":"人欺凌鄰舍，卻說：我豈不是戲耍嗎？他就像瘋狂的人拋擲火把、利箭，與殺人的兵器。","notes":["原文是死亡"],"end":19},{"n":20,"t":"火缺了柴就必熄滅；無人傳舌，爭競便止息。","notes":[]},{"n":21,"t":"好爭競的人煽惑爭端，就如餘火加炭，火上加柴一樣。","notes":[]},{"n":22,"t":"傳舌人的言語，如同美食，深入人的心腹。","notes":[]},{"n":23,"t":"火熱的嘴，奸惡的心，好像銀渣包的瓦器。","notes":[]},{"n":24,"t":"怨恨人的，用嘴粉飾，心裏卻藏著詭詐；","notes":[]},{"n":25,"t":"他用甜言蜜語，你不可信他，因為他心中有七樣可憎惡的。","notes":[]},{"n":26,"t":"他雖用詭詐遮掩自己的怨恨，他的邪惡必在會中顯露。","notes":[]},{"n":27,"t":"挖陷坑的，自己必掉在其中；滾石頭的，石頭必反滾在他身上。","notes":[]},{"n":28,"t":"虛謊的舌恨他所壓傷的人；諂媚的口敗壞人的事。","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"不要為明日自誇，因為一日要生何事，你尚且不能知道。","notes":[]},{"n":2,"t":"要別人誇獎你，不可用口自誇；等外人稱讚你，不可用嘴自稱。","notes":[]},{"n":3,"t":"石頭重，沙土沉，愚妄人的惱怒比這兩樣更重。","notes":[]},{"n":4,"t":"忿怒為殘忍，怒氣為狂瀾，惟有嫉妒，誰能敵得住呢？","notes":[]},{"n":5,"t":"當面的責備強如背地的愛情。","notes":[]},{"n":6,"t":"朋友加的傷痕出於忠誠；仇敵連連親嘴卻是多餘。","notes":[]},{"n":7,"t":"人吃飽了，厭惡蜂房的蜜；人飢餓了，一切苦物都覺甘甜。","notes":[]},{"n":8,"t":"人離本處飄流，好像雀鳥離窩遊飛。","notes":[]},{"n":9,"t":"膏油與香料使人心喜悅；朋友誠實的勸教也是如此甘美。","notes":[]},{"n":10,"t":"你的朋友和父親的朋友，你都不可離棄。你遭難的日子，不要上弟兄的家去；相近的鄰舍強如遠方的弟兄。","notes":[]},{"n":11,"t":"我兒，你要作智慧人，好叫我的心歡喜，使我可以回答那譏誚我的人。","notes":[]},{"n":12,"t":"通達人見禍藏躲；愚蒙人前往受害。","notes":[]},{"n":13,"t":"誰為生人作保，就拿誰的衣服；誰為外女作保，誰就承當。","notes":[]},{"n":14,"t":"清晨起來，大聲給朋友祝福的，就算是咒詛他。","notes":[]},{"n":15,"t":"大雨之日連連滴漏，和爭吵的婦人一樣；","notes":[]},{"n":16,"t":"想攔阻她的，便是攔阻風，也是右手抓油。","notes":[]},{"n":17,"t":"鐵磨鐵，磨出刃來；朋友相感也是如此。","notes":["原文是磨朋友的臉"]},{"n":18,"t":"看守無花果樹的，必吃樹上的果子；敬奉主人的，必得尊榮。","notes":[]},{"n":19,"t":"水中照臉，彼此相符；人與人，心也相對。","notes":[]},{"n":20,"t":"陰間和滅亡永不滿足；人的眼目也是如此。","notes":[]},{"n":21,"t":"鼎為煉銀，爐為煉金，人的稱讚也試煉人。","notes":[]},{"n":22,"t":"你雖用杵將愚妄人與打碎的麥子一同搗在臼中，他的愚妄還是離不了他。","notes":[]},{"n":23,"t":"你要詳細知道你羊群的景況，留心料理你的牛群；","notes":[]},{"n":24,"t":"因為資財不能永有，冠冕豈能存到萬代？","notes":[]},{"n":25,"t":"乾草割去，嫩草發現，山上的菜蔬也被收斂。","notes":[]},{"n":26,"t":"羊羔之毛是為你作衣服；山羊是為作田地的價值，","notes":[]},{"n":27,"t":"並有母山羊奶夠你吃，也夠你的家眷吃，且夠養你的婢女。","notes":[]}]},"28":{"heading":"","verses":[{"n":1,"t":"惡人雖無人追趕也逃跑；義人卻膽壯像獅子。","notes":[]},{"n":2,"t":"邦國因有罪過，君王就多更換；因有聰明知識的人，國必長存。","notes":[]},{"n":3,"t":"窮人欺壓貧民，好像暴雨沖沒糧食。","notes":[]},{"n":4,"t":"違棄律法的，誇獎惡人；遵守律法的，卻與惡人相爭。","notes":[]},{"n":5,"t":"壞人不明白公義；惟有尋求耶和華的，無不明白。","notes":[]},{"n":6,"t":"行為純正的窮乏人勝過行事乖僻的富足人。","notes":[]},{"n":7,"t":"謹守律法的，是智慧之子；與貪食人作伴的，卻羞辱其父。","notes":[]},{"n":8,"t":"人以厚利加增財物，是給那憐憫窮人者積蓄的。","notes":[]},{"n":9,"t":"轉耳不聽律法的，他的祈禱也為可憎。","notes":[]},{"n":10,"t":"誘惑正直人行惡道的，必掉在自己的坑裏；惟有完全人必承受福分。","notes":[]},{"n":11,"t":"富足人自以為有智慧，但聰明的貧窮人能將他查透。","notes":[]},{"n":12,"t":"義人得志，有大榮耀；惡人興起，人就躲藏。","notes":[]},{"n":13,"t":"遮掩自己罪過的，必不亨通；承認離棄罪過的，必蒙憐恤。","notes":[]},{"n":14,"t":"常存敬畏的，便為有福；心存剛硬的，必陷在禍患裏。","notes":[]},{"n":15,"t":"暴虐的君王轄制貧民，好像吼叫的獅子、覓食的熊。","notes":[]},{"n":16,"t":"無知的君多行暴虐；以貪財為可恨的，必年長日久。","notes":[]},{"n":17,"t":"背負流人血之罪的，必往坑裏奔跑，誰也不可攔阻他。","notes":[]},{"n":18,"t":"行動正直的，必蒙拯救；行事彎曲的，立時跌倒。","notes":[]},{"n":19,"t":"耕種自己田地的，必得飽食；追隨虛浮的，足受窮乏。","notes":[]},{"n":20,"t":"誠實人必多得福；想要急速發財的，不免受罰。","notes":[]},{"n":21,"t":"看人的情面乃為不好；人因一塊餅枉法也為不好。","notes":[]},{"n":22,"t":"人有惡眼想要急速發財，卻不知窮乏必臨到他身。","notes":[]},{"n":23,"t":"責備人的，後來蒙人喜悅，多於那用舌頭諂媚人的。","notes":[]},{"n":24,"t":"偷竊父母的，說：這不是罪，此人就是與強盜同類。","notes":[]},{"n":25,"t":"心中貪婪的，挑起爭端；倚靠耶和華的，必得豐裕。","notes":[]},{"n":26,"t":"心中自是的，便是愚昧人；憑智慧行事的，必蒙拯救。","notes":[]},{"n":27,"t":"賙濟貧窮的，不致缺乏；佯為不見的，必多受咒詛。","notes":[]},{"n":28,"t":"惡人興起，人就躲藏；惡人敗亡，義人增多。","notes":[]}]},"29":{"heading":"","verses":[{"n":1,"t":"人屢次受責罰，仍然硬著頸項；他必頃刻敗壞，無法可治。","notes":[]},{"n":2,"t":"義人增多，民就喜樂；惡人掌權，民就歎息。","notes":[]},{"n":3,"t":"愛慕智慧的，使父親喜樂；與妓女結交的，卻浪費錢財。","notes":[]},{"n":4,"t":"王藉公平，使國堅定；索要賄賂，使國傾敗。","notes":[]},{"n":5,"t":"諂媚鄰舍的，就是設網羅絆他的腳。","notes":[]},{"n":6,"t":"惡人犯罪，自陷網羅；惟獨義人歡呼喜樂。","notes":[]},{"n":7,"t":"義人知道查明窮人的案；惡人沒有聰明，就不得而知。","notes":[]},{"n":8,"t":"褻慢人煽惑通城；智慧人止息眾怒。","notes":[]},{"n":9,"t":"智慧人與愚妄人相爭，或怒或笑，總不能使他止息。","notes":[]},{"n":10,"t":"好流人血的，恨惡完全人，索取正直人的性命。","notes":[]},{"n":11,"t":"愚妄人怒氣全發；智慧人忍氣含怒。","notes":[]},{"n":12,"t":"君王若聽謊言，他一切臣僕都是奸惡。","notes":[]},{"n":13,"t":"貧窮人、強暴人在世相遇；他們的眼目都蒙耶和華光照。","notes":[]},{"n":14,"t":"君王憑誠實判斷窮人；他的國位必永遠堅立。","notes":[]},{"n":15,"t":"杖打和責備能加增智慧；放縱的兒子使母親羞愧。","notes":[]},{"n":16,"t":"惡人加多，過犯也加多，義人必看見他們跌倒。","notes":[]},{"n":17,"t":"管教你的兒子，他就使你得安息，也必使你心裏喜樂。","notes":[]},{"n":18,"t":"沒有異象，民就放肆；惟遵守律法的，便為有福。","notes":["或譯：默示"]},{"n":19,"t":"只用言語，僕人不肯受管教；他雖然明白，也不留意。","notes":[]},{"n":20,"t":"你見言語急躁的人嗎？愚昧人比他更有指望。","notes":[]},{"n":21,"t":"人將僕人從小嬌養，這僕人終久必成了他的兒子。","notes":[]},{"n":22,"t":"好氣的人挑啟爭端；暴怒的人多多犯罪。","notes":[]},{"n":23,"t":"人的高傲必使他卑下；心裏謙遜的，必得尊榮。","notes":[]},{"n":24,"t":"人與盜賊分贓，是恨惡自己的性命；他聽見叫人發誓的聲音，卻不言語。","notes":[]},{"n":25,"t":"懼怕人的，陷入網羅；惟有倚靠耶和華的，必得安穩。","notes":[]},{"n":26,"t":"求王恩的人多；定人事乃在耶和華。","notes":[]},{"n":27,"t":"為非作歹的，被義人憎嫌；行事正直的，被惡人憎惡。","notes":[]}]},"30":{"heading":"亞古珥語錄","verses":[{"n":1,"t":"雅基的兒子亞古珥的言語就是真言。這人對以鐵和烏甲說：","notes":[]},{"n":2,"t":"我比眾人更蠢笨，也沒有人的聰明。","notes":[]},{"n":3,"t":"我沒有學好智慧，也不認識至聖者。","notes":[]},{"n":4,"t":"誰升天又降下來？誰聚風在掌握中？誰包水在衣服裏？誰立定地的四極？他名叫甚麼？他兒子名叫甚麼？你知道嗎？","notes":[]},{"n":5,"t":"神的言語句句都是煉淨的；投靠他的，他便作他們的盾牌。","notes":[]},{"n":6,"t":"他的言語，你不可加添，恐怕他責備你，你就顯為說謊言的。","notes":[]},{"n":7,"t":"我求你兩件事，在我未死之先，不要不賜給我：","notes":[],"heads":["其他箴言"]},{"n":8,"t":"求你使虛假和謊言遠離我；使我也不貧窮也不富足；賜給我需用的飲食，","notes":[]},{"n":9,"t":"恐怕我飽足不認你，說：耶和華是誰呢？又恐怕我貧窮就偷竊，以致褻瀆我神的名。","notes":[]},{"n":10,"t":"你不要向主人讒謗僕人，恐怕他咒詛你，你便算為有罪。","notes":[]},{"n":11,"t":"有一宗人，咒詛父親，不給母親祝福。","notes":["宗：原文是代；下同"]},{"n":12,"t":"有一宗人，自以為清潔，卻沒有洗去自己的污穢。","notes":[]},{"n":13,"t":"有一宗人，眼目何其高傲，眼皮也是高舉。","notes":[]},{"n":14,"t":"有一宗人，牙如劍，齒如刀，要吞滅地上的困苦人和世間的窮乏人。","notes":[]},{"n":15,"t":"螞蟥有兩個女兒，常說：給呀，給呀！有三樣不知足的，連不說「夠的」共有四樣：","notes":[]},{"n":16,"t":"就是陰間和石胎，浸水不足的地，並火。","notes":[]},{"n":17,"t":"戲笑父親、藐視而不聽從母親的，他的眼睛必為谷中的烏鴉啄出來，為鷹雛所吃。","notes":[]},{"n":18,"t":"我所測不透的奇妙有三樣，連我所不知道的共有四樣：","notes":[]},{"n":19,"t":"就是鷹在空中飛的道；蛇在磐石上爬的道；船在海中行的道；男與女交合的道。","notes":[]},{"n":20,"t":"淫婦的道也是這樣：她吃了，把嘴一擦就說：我沒有行惡。","notes":[]},{"n":21,"t":"使地震動的有三樣，連地擔不起的共有四樣：","notes":[]},{"n":22,"t":"就是僕人作王；愚頑人吃飽；","notes":[]},{"n":23,"t":"醜惡的女子出嫁；婢女接續主母。","notes":[]},{"n":24,"t":"地上有四樣小物，卻甚聰明：","notes":[]},{"n":25,"t":"螞蟻是無力之類，卻在夏天預備糧食。","notes":[]},{"n":26,"t":"沙番是軟弱之類，卻在磐石中造房。","notes":[]},{"n":27,"t":"蝗蟲沒有君王，卻分隊而出。","notes":[]},{"n":28,"t":"守宮用爪抓牆，卻住在王宮。","notes":[]},{"n":29,"t":"步行威武的有三樣，連行走威武的共有四樣：","notes":[]},{"n":30,"t":"就是獅子－乃百獸中最為猛烈、無所躲避的，","notes":[]},{"n":31,"t":"獵狗，公山羊，和無人能敵的君王。","notes":[]},{"n":32,"t":"你若行事愚頑，自高自傲，或是懷了惡念，就當用手摀口。","notes":[]},{"n":33,"t":"搖牛奶必成奶油；扭鼻子必出血。照樣，激動怒氣必起爭端。","notes":[]}]},"31":{"heading":"給一君王的忠告","verses":[{"n":1,"t":"利慕伊勒王的言語，是他母親教訓他的真言。","notes":[]},{"n":2,"t":"我的兒啊，我腹中生的兒啊，我許願得的兒啊！我當怎樣教訓你呢？","notes":[]},{"n":3,"t":"不要將你的精力給婦女；也不要有敗壞君王的行為。","notes":[]},{"n":4,"t":"利慕伊勒啊，君王喝酒，君王喝酒不相宜；王子說濃酒在那裏也不相宜；","notes":[]},{"n":5,"t":"恐怕喝了就忘記律例，顛倒一切困苦人的是非。","notes":[]},{"n":6,"t":"可以把濃酒給將亡的人喝，把清酒給苦心的人喝，","notes":[]},{"n":7,"t":"讓他喝了，就忘記他的貧窮，不再記念他的苦楚。","notes":[]},{"n":8,"t":"你當為啞巴開口，為一切孤獨的伸冤。","notes":["或譯：不能自辯的"]},{"n":9,"t":"你當開口按公義判斷，為困苦和窮乏的辨屈。","notes":[]},{"n":10,"t":"才德的婦人誰能得著呢？她的價值遠勝過珍珠。","notes":[],"heads":["論賢妻"]},{"n":11,"t":"她丈夫心裏倚靠她，必不缺少利益；","notes":[]},{"n":12,"t":"她一生使丈夫有益無損。","notes":[]},{"n":13,"t":"她尋找羊羢和麻，甘心用手做工。","notes":[]},{"n":14,"t":"她好像商船從遠方運糧來，","notes":[]},{"n":15,"t":"未到黎明她就起來，把食物分給家中的人，將當做的工分派婢女。","notes":[]},{"n":16,"t":"她想得田地就買來；用手所得之利栽種葡萄園。","notes":[]},{"n":17,"t":"她以能力束腰，使膀臂有力。","notes":[]},{"n":18,"t":"她覺得所經營的有利；她的燈終夜不滅。","notes":[]},{"n":19,"t":"她手拿撚線竿，手把紡線車。","notes":[]},{"n":20,"t":"她張手賙濟困苦人，伸手幫補窮乏人。","notes":[]},{"n":21,"t":"她不因下雪為家裏的人擔心，因為全家都穿著朱紅衣服。","notes":[]},{"n":22,"t":"她為自己製作繡花毯子；她的衣服是細麻和紫色布做的。","notes":[]},{"n":23,"t":"她丈夫在城門口與本地的長老同坐，為眾人所認識。","notes":[]},{"n":24,"t":"她做細麻布衣裳出賣，又將腰帶賣與商家。","notes":[]},{"n":25,"t":"能力和威儀是她的衣服；她想到日後的景況就喜笑。","notes":[]},{"n":26,"t":"她開口就發智慧；她舌上有仁慈的法則。","notes":[]},{"n":27,"t":"她觀察家務，並不吃閒飯。","notes":[]},{"n":28,"t":"她的兒女起來稱她有福；她的丈夫也稱讚她，","notes":[]},{"n":29,"t":"說：才德的女子很多，惟獨你超過一切。","notes":[]},{"n":30,"t":"艷麗是虛假的，美容是虛浮的；惟敬畏耶和華的婦女必得稱讚。","notes":[]},{"n":31,"t":"願她享受操作所得的；願她的工作在城門口榮耀她。","notes":[]}]}},"ECC":{"1":{"heading":"人生的虛空","verses":[{"n":1,"t":"在耶路撒冷作王、大衛的兒子、傳道者的言語。","notes":[]},{"n":2,"t":"傳道者說：虛空的虛空，虛空的虛空，凡事都是虛空。","notes":[]},{"n":3,"t":"人一切的勞碌，就是他在日光之下的勞碌，有甚麼益處呢？","notes":[]},{"n":4,"t":"一代過去，一代又來，地卻永遠長存。","notes":[]},{"n":5,"t":"日頭出來，日頭落下，急歸所出之地。","notes":[]},{"n":6,"t":"風往南颳，又向北轉，不住地旋轉，而且返回轉行原道。","notes":[]},{"n":7,"t":"江河都往海裏流，海卻不滿；江河從何處流，仍歸還何處。","notes":[]},{"n":8,"t":"萬事令人厭煩，人不能說盡。眼看，看不飽；耳聽，聽不足。","notes":["或譯：萬物滿有困乏"]},{"n":9,"t":"已有的事後必再有；已行的事後必再行。日光之下並無新事。","notes":[]},{"n":10,"t":"豈有一件事人能指著說這是新的？哪知，在我們以前的世代早已有了。","notes":[]},{"n":11,"t":"已過的世代，無人記念；將來的世代，後來的人也不記念。","notes":[]},{"n":12,"t":"我傳道者在耶路撒冷作過以色列的王。","notes":[],"heads":["傳道者的經驗"]},{"n":13,"t":"我專心用智慧尋求、查究天下所做的一切事，乃知神叫世人所經練的是極重的勞苦。","notes":[]},{"n":14,"t":"我見日光之下所做的一切事，都是虛空，都是捕風。","notes":[]},{"n":15,"t":"彎曲的，不能變直；缺少的，不能足數。","notes":[]},{"n":16,"t":"我心裏議論說：我得了大智慧，勝過我以前在耶路撒冷的眾人，而且我心中多經歷智慧和知識的事。","notes":[]},{"n":17,"t":"我又專心察明智慧、狂妄，和愚昧，乃知這也是捕風。","notes":[]},{"n":18,"t":"因為多有智慧，就多有愁煩；加增知識的，就加增憂傷。","notes":[]}]},"2":{"heading":"","verses":[{"n":1,"t":"我心裏說：「來吧，我以喜樂試試你，你好享福！」誰知，這也是虛空。","notes":[]},{"n":2,"t":"我指嬉笑說：「這是狂妄。」論喜樂說：「有何功效呢？」","notes":[]},{"n":3,"t":"我心裏察究，如何用酒使我肉體舒暢，我心卻仍以智慧引導我；又如何持住愚昧，等我看明世人，在天下一生當行何事為美。","notes":[]},{"n":4,"t":"我為自己動大工程，建造房屋，栽種葡萄園，","notes":[]},{"n":5,"t":"修造園囿，在其中栽種各樣果木樹；","notes":[]},{"n":6,"t":"挖造水池，用以澆灌嫩小的樹木。","notes":[]},{"n":7,"t":"我買了僕婢，也有生在家中的僕婢；又有許多牛群羊群，勝過以前在耶路撒冷眾人所有的。","notes":[]},{"n":8,"t":"我又為自己積蓄金銀和君王的財寶，並各省的財寶；又得唱歌的男女和世人所喜愛的物，並許多的妃嬪。","notes":[]},{"n":9,"t":"這樣，我就日見昌盛，勝過以前在耶路撒冷的眾人。我的智慧仍然存留。","notes":[]},{"n":10,"t":"凡我眼所求的，我沒有留下不給它的；我心所樂的，我沒有禁止不享受的；因我的心為我一切所勞碌的快樂，這就是我從勞碌中所得的分。","notes":[]},{"n":11,"t":"後來，我察看我手所經營的一切事和我勞碌所成的功。誰知都是虛空，都是捕風；在日光之下毫無益處。","notes":[]},{"n":12,"t":"我轉念觀看智慧、狂妄，和愚昧。在王以後而來的人還能做甚麼呢？也不過行早先所行的就是了。","notes":[]},{"n":13,"t":"我便看出智慧勝過愚昧，如同光明勝過黑暗。","notes":[]},{"n":14,"t":"智慧人的眼目光明，愚昧人在黑暗裏行。我卻看明有一件事，這兩等人都必遇見。","notes":["光明：原文是在他頭上"]},{"n":15,"t":"我就心裏說：「愚昧人所遇見的，我也必遇見，我為何更有智慧呢？」我心裏說，這也是虛空。","notes":[]},{"n":16,"t":"智慧人和愚昧人一樣，永遠無人記念，因為日後都被忘記；可歎智慧人死亡，與愚昧人無異。","notes":[]},{"n":17,"t":"我所以恨惡生命；因為在日光之下所行的事我都以為煩惱，都是虛空，都是捕風。","notes":[]},{"n":18,"t":"我恨惡一切的勞碌，就是我在日光之下的勞碌，因為我得來的必留給我以後的人。","notes":[]},{"n":19,"t":"那人是智慧是愚昧，誰能知道？他竟要管理我勞碌所得的，就是我在日光之下用智慧所得的。這也是虛空。","notes":[]},{"n":20,"t":"故此，我轉想我在日光之下所勞碌的一切工作，心便絕望。","notes":[]},{"n":21,"t":"因為有人用智慧、知識、靈巧所勞碌得來的，卻要留給未曾勞碌的人為分。這也是虛空，也是大患。","notes":[]},{"n":22,"t":"人在日光之下勞碌累心，在他一切的勞碌上得著甚麼呢？","notes":[]},{"n":23,"t":"因為他日日憂慮，他的勞苦成為愁煩，連夜間心也不安。這也是虛空。","notes":[]},{"n":24,"t":"人莫強如吃喝，且在勞碌中享福，我看這也是出於神的手。","notes":[]},{"n":25,"t":"論到吃用、享福，誰能勝過我呢？","notes":[]},{"n":26,"t":"神喜悅誰，就給誰智慧、知識，和喜樂；惟有罪人，神使他勞苦，叫他將所收聚的、所堆積的歸給神所喜悅的人。這也是虛空，也是捕風。","notes":[]}]},"3":{"heading":"萬事均有定時","verses":[{"n":1,"t":"凡事都有定期，天下萬務都有定時。","notes":[]},{"n":2,"t":"生有時，死有時；栽種有時，拔出所栽種的也有時；","notes":[]},{"n":3,"t":"殺戮有時，醫治有時；拆毀有時，建造有時；","notes":[]},{"n":4,"t":"哭有時，笑有時；哀慟有時，跳舞有時；","notes":[]},{"n":5,"t":"拋擲石頭有時，堆聚石頭有時；懷抱有時，不懷抱有時；","notes":[]},{"n":6,"t":"尋找有時，失落有時；保守有時，捨棄有時；","notes":[]},{"n":7,"t":"撕裂有時，縫補有時；靜默有時，言語有時；","notes":[]},{"n":8,"t":"喜愛有時，恨惡有時；爭戰有時，和好有時。","notes":[]},{"n":9,"t":"這樣看來，做事的人在他的勞碌上有甚麼益處呢？","notes":[]},{"n":10,"t":"我見神叫世人勞苦，使他們在其中受經練。","notes":[]},{"n":11,"t":"神造萬物，各按其時成為美好，又將永生安置在世人心裏。然而神從始至終的作為，人不能參透。","notes":["原文是永遠"]},{"n":12,"t":"我知道世人，莫強如終身喜樂行善；","notes":[]},{"n":13,"t":"並且人人吃喝，在他一切勞碌中享福，這也是神的恩賜。","notes":[]},{"n":14,"t":"我知道神一切所做的都必永存；無所增添，無所減少。神這樣行，是要人在他面前存敬畏的心。","notes":[]},{"n":15,"t":"現今的事早先就有了，將來的事早已也有了，並且神使已過的事重新再來。","notes":["或譯：並且神再尋回已過的事"]},{"n":16,"t":"我又見日光之下，在審判之處有奸惡，在公義之處也有奸惡。","notes":[],"heads":["世上的不公平"]},{"n":17,"t":"我心裏說，神必審判義人和惡人；因為在那裏，各樣事務，一切工作，都有定時。","notes":[]},{"n":18,"t":"我心裏說，這乃為世人的緣故，是神要試驗他們，使他們覺得自己不過像獸一樣。","notes":[]},{"n":19,"t":"因為世人遭遇的，獸也遭遇，所遭遇的都是一樣：這個怎樣死，那個也怎樣死，氣息都是一樣。人不能強於獸，都是虛空。","notes":[]},{"n":20,"t":"都歸一處，都是出於塵土，也都歸於塵土。","notes":[]},{"n":21,"t":"誰知道人的靈是往上升，獸的魂是下入地呢？","notes":[]},{"n":22,"t":"故此，我見人莫強如在他經營的事上喜樂，因為這是他的分。他身後的事誰能使他回來得見呢？","notes":[]}]},"4":{"heading":"","verses":[{"n":1,"t":"我又轉念，見日光之下所行的一切欺壓。看哪，受欺壓的流淚，且無人安慰；欺壓他們的有勢力，也無人安慰他們。","notes":[]},{"n":2,"t":"因此，我讚歎那早已死的死人，勝過那還活著的活人。","notes":[]},{"n":3,"t":"並且我以為那未曾生的，就是未見過日光之下惡事的，比這兩等人更強。","notes":[]},{"n":4,"t":"我又見人為一切的勞碌和各樣靈巧的工作就被鄰舍嫉妒。這也是虛空，也是捕風。","notes":[]},{"n":5,"t":"愚昧人抱著手，吃自己的肉。","notes":[]},{"n":6,"t":"滿了一把，得享安靜，強如滿了兩把，勞碌捕風。","notes":[]},{"n":7,"t":"我又轉念，見日光之下有一件虛空的事：","notes":[]},{"n":8,"t":"有人孤單無二，無子無兄，竟勞碌不息，眼目也不以錢財為足。他說：「我勞勞碌碌，刻苦自己，不享福樂，到底是為誰呢？」這也是虛空，是極重的勞苦。","notes":[]},{"n":9,"t":"兩個人總比一個人好，因為二人勞碌同得美好的果效。","notes":[]},{"n":10,"t":"若是跌倒，這人可以扶起他的同伴；若是孤身跌倒，沒有別人扶起他來，這人就有禍了。","notes":[]},{"n":11,"t":"再者，二人同睡就都暖和，一人獨睡怎能暖和呢？","notes":[]},{"n":12,"t":"有人攻勝孤身一人，若有二人便能敵擋他；三股合成的繩子不容易折斷。","notes":[]},{"n":13,"t":"貧窮而有智慧的少年人勝過年老不肯納諫的愚昧王。","notes":[]},{"n":14,"t":"這人是從監牢中出來作王，在他國中，生來原是貧窮的。","notes":[]},{"n":15,"t":"我見日光之下一切行動的活人都隨從那第二位，就是起來代替老王的少年人。","notes":[]},{"n":16,"t":"他所治理的眾人就是他的百姓，多得無數；在他後來的人尚且不喜悅他。這真是虛空，也是捕風。","notes":[]}]},"5":{"heading":"不可隨便許願","verses":[{"n":1,"t":"你到神的殿要謹慎腳步；因為近前聽，勝過愚昧人獻祭，他們本不知道所做的是惡。","notes":["或譯：勝過獻愚昧人的祭"]},{"n":2,"t":"你在神面前不可冒失開口，也不可心急發言；因為神在天上，你在地下，所以你的言語要寡少。","notes":[]},{"n":3,"t":"事務多，就令人做夢；言語多，就顯出愚昧。","notes":[]},{"n":4,"t":"你向神許願，償還不可遲延，因他不喜悅愚昧人，所以你許的願應當償還。","notes":[]},{"n":5,"t":"你許願不還，不如不許。","notes":[]},{"n":6,"t":"不可任你的口使肉體犯罪，也不可在祭司面前說是錯許了。為何使神因你的聲音發怒，敗壞你手所做的呢？","notes":["原文是使者"]},{"n":7,"t":"多夢和多言，其中多有虛幻，你只要敬畏神。","notes":[]},{"n":8,"t":"你若在一省之中見窮人受欺壓，並奪去公義公平的事，不要因此詫異；因有一位高過居高位的鑒察，在他們以上還有更高的。","notes":[],"heads":["人生是虛空的"]},{"n":9,"t":"況且地的益處歸眾人，就是君王也受田地的供應。","notes":[]},{"n":10,"t":"貪愛銀子的，不因得銀子知足；貪愛豐富的，也不因得利益知足。這也是虛空。","notes":[]},{"n":11,"t":"貨物增添，吃的人也增添，物主得甚麼益處呢？不過眼看而已！","notes":[]},{"n":12,"t":"勞碌的人不拘吃多吃少，睡得香甜；富足人的豐滿卻不容他睡覺。","notes":[]},{"n":13,"t":"我見日光之下有一宗大禍患，就是財主積存資財，反害自己。","notes":[]},{"n":14,"t":"因遭遇禍患，這些資財就消滅；那人若生了兒子，手裏也一無所有。","notes":[]},{"n":15,"t":"他怎樣從母胎赤身而來，也必照樣赤身而去；他所勞碌得來的，手中分毫不能帶去。","notes":[]},{"n":16,"t":"他來的情形怎樣，他去的情形也怎樣。這也是一宗大禍患。他為風勞碌有甚麼益處呢？","notes":[]},{"n":17,"t":"並且他終身在黑暗中吃喝，多有煩惱，又有病患嘔氣。","notes":[]},{"n":18,"t":"我所見為善為美的，就是人在神賜他一生的日子吃喝，享受日光之下勞碌得來的好處，因為這是他的分。","notes":[]},{"n":19,"t":"神賜人資財豐富，使他能以吃用，能取自己的分，在他勞碌中喜樂，這乃是神的恩賜。","notes":[]},{"n":20,"t":"他不多思念自己一生的年日，因為神應他的心使他喜樂。","notes":[]}]},"6":{"heading":"","verses":[{"n":1,"t":"我見日光之下有一宗禍患重壓在人身上，","notes":[]},{"n":2,"t":"就是人蒙神賜他資財、豐富、尊榮，以致他心裏所願的一樣都不缺，只是神使他不能吃用，反有外人來吃用。這是虛空，也是禍患。","notes":[]},{"n":3,"t":"人若生一百個兒子，活許多歲數，以致他的年日甚多，心裏卻不得滿享福樂，又不得埋葬；據我說，那不到期而落的胎比他倒好。","notes":[]},{"n":4,"t":"因為虛虛而來，暗暗而去，名字被黑暗遮蔽，","notes":[]},{"n":5,"t":"並且沒有見過天日，也毫無知覺；這胎，比那人倒享安息。","notes":[]},{"n":6,"t":"那人雖然活千年，再活千年，卻不享福，眾人豈不都歸一個地方去嗎？","notes":[]},{"n":7,"t":"人的勞碌都為口腹，心裏卻不知足。","notes":[]},{"n":8,"t":"這樣看來，智慧人比愚昧人有甚麼長處呢？窮人在眾人面前知道如何行，有甚麼長處呢？","notes":[]},{"n":9,"t":"眼睛所看的比心裏妄想的倒好。這也是虛空，也是捕風。","notes":[]},{"n":10,"t":"先前所有的，早已起了名，並知道何為人，他也不能與那比自己力大的相爭。","notes":[]},{"n":11,"t":"加增虛浮的事既多，這與人有甚麼益處呢？","notes":[]},{"n":12,"t":"人一生虛度的日子，就如影兒經過，誰知道甚麼與他有益呢？誰能告訴他身後在日光之下有甚麼事呢？","notes":[]}]},"7":{"heading":"智愚之別","verses":[{"n":1,"t":"名譽強如美好的膏油；人死的日子勝過人生的日子。","notes":[]},{"n":2,"t":"往遭喪的家去，強如往宴樂的家去；因為死是眾人的結局，活人也必將這事放在心上。","notes":[]},{"n":3,"t":"憂愁強如喜笑；因為面帶愁容，終必使心喜樂。","notes":[]},{"n":4,"t":"智慧人的心在遭喪之家；愚昧人的心在快樂之家。","notes":[]},{"n":5,"t":"聽智慧人的責備，強如聽愚昧人的歌唱。","notes":[]},{"n":6,"t":"愚昧人的笑聲，好像鍋下燒荊棘的爆聲；這也是虛空。","notes":[]},{"n":7,"t":"勒索使智慧人變為愚妄；賄賂能敗壞人的慧心。","notes":[]},{"n":8,"t":"事情的終局強如事情的起頭；存心忍耐的，勝過居心驕傲的。","notes":[]},{"n":9,"t":"你不要心裏急躁惱怒，因為惱怒存在愚昧人的懷中。","notes":[]},{"n":10,"t":"不要說：先前的日子強過如今的日子，是甚麼緣故呢？你這樣問，不是出於智慧。","notes":[]},{"n":11,"t":"智慧和產業並好，而且見天日的人得智慧更為有益。","notes":[]},{"n":12,"t":"因為智慧護庇人，好像銀錢護庇人一樣。惟獨智慧能保全智慧人的生命。這就是知識的益處。","notes":[]},{"n":13,"t":"你要察看神的作為；因神使為曲的，誰能變為直呢？","notes":[]},{"n":14,"t":"遇亨通的日子你當喜樂；遭患難的日子你當思想；因為神使這兩樣並列，為的是叫人查不出身後有甚麼事。","notes":[]},{"n":15,"t":"有義人行義，反致滅亡；有惡人行惡，倒享長壽。這都是我在虛度之日中所見過的。","notes":[]},{"n":16,"t":"不要行義過分，也不要過於自逞智慧，何必自取敗亡呢？","notes":[]},{"n":17,"t":"不要行惡過分，也不要為人愚昧，何必不到期而死呢？","notes":[]},{"n":18,"t":"你持守這個為美，那個也不要鬆手；因為敬畏神的人，必從這兩樣出來。","notes":[]},{"n":19,"t":"智慧使有智慧的人比城中十個官長更有能力。","notes":[]},{"n":20,"t":"時常行善而不犯罪的義人，世上實在沒有。","notes":[]},{"n":21,"t":"人所說的一切話，你不要放在心上，恐怕聽見你的僕人咒詛你。","notes":[]},{"n":22,"t":"因為你心裏知道，自己也曾屢次咒詛別人。","notes":[]},{"n":23,"t":"我曾用智慧試驗這一切事；我說，要得智慧，智慧卻離我遠。","notes":[]},{"n":24,"t":"萬事之理，離我甚遠，而且最深，誰能測透呢？","notes":[]},{"n":25,"t":"我轉念，一心要知道，要考察，要尋求智慧和萬事的理由；又要知道邪惡為愚昧，愚昧為狂妄。","notes":[]},{"n":26,"t":"我得知有等婦人比死還苦：她的心是網羅，手是鎖鍊。凡蒙神喜悅的人必能躲避她；有罪的人卻被她纏住了。","notes":[]},{"n":27,"t":"傳道者說：「看哪，一千男子中，我找到一個正直人，但眾女子中，沒有找到一個。」我將這事一一比較，要尋求其理，我心仍要尋找，卻未曾找到。","notes":[],"end":28},{"n":29,"t":"我所找到的只有一件，就是神造人原是正直，但他們尋出許多巧計。","notes":[]}]},"8":{"heading":"服從君王","verses":[{"n":1,"t":"誰如智慧人呢？誰知道事情的解釋呢？人的智慧使他的臉發光，並使他臉上的暴氣改變。","notes":[]},{"n":2,"t":"我勸你遵守王的命令；既指神起誓，理當如此。","notes":[]},{"n":3,"t":"不要急躁離開王的面前，不要固執行惡，因為他凡事都隨自己的心意而行。","notes":[]},{"n":4,"t":"王的話本有權力，誰敢問他說「你做甚麼」呢？","notes":[]},{"n":5,"t":"凡遵守命令的，必不經歷禍患；智慧人的心能辨明時候和定理。","notes":["原文是審判；下節同"]},{"n":6,"t":"各樣事務成就都有時候和定理，因為人的苦難重壓在他身上。","notes":[]},{"n":7,"t":"他不知道將來的事，因為將來如何，誰能告訴他呢？","notes":[]},{"n":8,"t":"無人有權力掌管生命，將生命留住；也無人有權力掌管死期；這場爭戰，無人能免；邪惡也不能救那好行邪惡的人。","notes":[]},{"n":9,"t":"這一切我都見過，也專心查考日光之下所做的一切事。有時這人管轄那人，令人受害。","notes":[]},{"n":10,"t":"我見惡人埋葬，歸入墳墓；又見行正直事的離開聖地，在城中被人忘記。這也是虛空。","notes":[],"heads":["惡人和義人"]},{"n":11,"t":"因為斷定罪名不立刻施刑，所以世人滿心作惡。","notes":[]},{"n":12,"t":"罪人雖然作惡百次，倒享長久的年日；然而我準知道，敬畏神的，就是在他面前敬畏的人，終久必得福樂。","notes":[]},{"n":13,"t":"惡人卻不得福樂，也不得長久的年日；這年日好像影兒，因他不敬畏神。","notes":[]},{"n":14,"t":"世上有一件虛空的事，就是義人所遭遇的，反照惡人所行的；又有惡人所遭遇的，反照義人所行的。我說，這也是虛空。","notes":[]},{"n":15,"t":"我就稱讚快樂，原來人在日光之下，莫強如吃喝快樂；因為他在日光之下，神賜他一生的年日，要從勞碌中，時常享受所得的。","notes":[]},{"n":16,"t":"我專心求智慧，要看世上所做的事。（有晝夜不睡覺不合眼的。）","notes":[]},{"n":17,"t":"我就看明神一切的作為，知道人查不出日光之下所做的事；任憑他費多少力尋查，都查不出來，就是智慧人雖想知道，也是查不出來。","notes":[]}]},"9":{"heading":"智慧勝過武力","verses":[{"n":1,"t":"我將這一切事放在心上，詳細考究，就知道義人和智慧人，並他們的作為都在神手中；或是愛，或是恨，都在他們的前面，人不能知道。","notes":[]},{"n":2,"t":"凡臨到眾人的事都是一樣：義人和惡人都遭遇一樣的事；好人，潔淨人和不潔淨人，獻祭的與不獻祭的，也是一樣。好人如何，罪人也如何；起誓的如何，怕起誓的也如何。","notes":[]},{"n":3,"t":"在日光之下所行的一切事上有一件禍患，就是眾人所遭遇的都是一樣，並且世人的心充滿了惡；活著的時候心裏狂妄，後來就歸死人那裏去了。","notes":[]},{"n":4,"t":"與一切活人相連的，那人還有指望，因為活著的狗比死了的獅子更強。","notes":[]},{"n":5,"t":"活著的人知道必死；死了的人毫無所知，也不再得賞賜；他們的名無人記念。","notes":[]},{"n":6,"t":"他們的愛，他們的恨，他們的嫉妒，早都消滅了。在日光之下所行的一切事上，他們永不再有分了。","notes":[]},{"n":7,"t":"你只管去歡歡喜喜吃你的飯，心中快樂喝你的酒，因為神已經悅納你的作為。","notes":[]},{"n":8,"t":"你的衣服當時常潔白，你頭上也不要缺少膏油。","notes":[]},{"n":9,"t":"在你一生虛空的年日，就是神賜你在日光之下虛空的年日，當同你所愛的妻，快活度日，因為那是你生前在日光之下勞碌的事上所得的分。","notes":[]},{"n":10,"t":"凡你手所當做的事要盡力去做；因為在你所必去的陰間沒有工作，沒有謀算，沒有知識，也沒有智慧。","notes":[]},{"n":11,"t":"我又轉念：見日光之下，快跑的未必能贏；力戰的未必得勝；智慧的未必得糧食；明哲的未必得資財；靈巧的未必得喜悅。所臨到眾人的是在乎當時的機會。","notes":[]},{"n":12,"t":"原來人也不知道自己的定期。魚被惡網圈住，鳥被網羅捉住，禍患忽然臨到的時候，世人陷在其中也是如此。","notes":[]},{"n":13,"t":"我見日光之下有一樣智慧，據我看乃是廣大，","notes":[]},{"n":14,"t":"就是有一小城，其中的人數稀少，有大君王來攻擊，修築營壘，將城圍困。","notes":[]},{"n":15,"t":"城中有一個貧窮的智慧人，他用智慧救了那城，卻沒有人記念那窮人。","notes":[]},{"n":16,"t":"我就說，智慧勝過勇力；然而那貧窮人的智慧被人藐視，他的話也無人聽從。","notes":[]},{"n":17,"t":"寧可在安靜之中聽智慧人的言語，不聽掌管愚昧人的喊聲。","notes":[]},{"n":18,"t":"智慧勝過打仗的兵器；但一個罪人能敗壞許多善事。","notes":[]}]},"10":{"heading":"","verses":[{"n":1,"t":"死蒼蠅使做香的膏油發出臭氣；這樣，一點愚昧也能敗壞智慧和尊榮。","notes":[]},{"n":2,"t":"智慧人的心居右；愚昧人的心居左。","notes":[]},{"n":3,"t":"並且愚昧人行路顯出無知，對眾人說，他是愚昧人。","notes":[]},{"n":4,"t":"掌權者的心若向你發怒，不要離開你的本位，因為柔和能免大過。","notes":[]},{"n":5,"t":"我見日光之下有一件禍患，似乎出於掌權的錯誤，","notes":[]},{"n":6,"t":"就是愚昧人立在高位；富足人坐在低位。","notes":[]},{"n":7,"t":"我見過僕人騎馬，王子像僕人在地上步行。","notes":[]},{"n":8,"t":"挖陷坑的，自己必掉在其中；拆牆垣的，必為蛇所咬。","notes":[]},{"n":9,"t":"鑿開石頭的，必受損傷；劈開木頭的，必遭危險。","notes":["或譯：挪移"]},{"n":10,"t":"鐵器鈍了，若不將刃磨快，就必多費氣力；但得智慧指教，便有益處。","notes":[]},{"n":11,"t":"未行法術以先，蛇若咬人，後行法術也是無益。","notes":[]},{"n":12,"t":"智慧人的口說出恩言；愚昧人的嘴吞滅自己。","notes":[]},{"n":13,"t":"他口中的言語起頭是愚昧；他話的末尾是奸惡的狂妄。","notes":[]},{"n":14,"t":"愚昧人多有言語，人卻不知將來有甚麼事；他身後的事誰能告訴他呢？","notes":[]},{"n":15,"t":"凡愚昧人，他的勞碌使自己困乏，因為連進城的路，他也不知道。","notes":[]},{"n":16,"t":"邦國啊，你的王若是孩童，你的群臣早晨宴樂，你就有禍了！","notes":[]},{"n":17,"t":"邦國啊，你的王若是貴冑之子，你的群臣按時吃喝，為要補力，不為酒醉，你就有福了！","notes":[]},{"n":18,"t":"因人懶惰，房頂塌下；因人手懶，房屋滴漏。","notes":[]},{"n":19,"t":"設擺筵席是為喜笑。酒能使人快活；錢能叫萬事應心。","notes":[]},{"n":20,"t":"你不可咒詛君王，也不可心懷此念；在你臥房也不可咒詛富戶。因為空中的鳥必傳揚這聲音，有翅膀的也必述說這事。","notes":[]}]},"11":{"heading":"智慧人的作為","verses":[{"n":1,"t":"當將你的糧食撒在水面，因為日久必能得著。","notes":[]},{"n":2,"t":"你要分給七人，或分給八人，因為你不知道將來有甚麼災禍臨到地上。","notes":[]},{"n":3,"t":"雲若滿了雨，就必傾倒在地上。樹若向南倒，或向北倒，樹倒在何處，就存在何處。","notes":[]},{"n":4,"t":"看風的，必不撒種；望雲的，必不收割。","notes":[]},{"n":5,"t":"風從何道來，骨頭在懷孕婦人的胎中如何長成，你尚且不得知道；這樣，行萬事之神的作為，你更不得知道。","notes":[]},{"n":6,"t":"早晨要撒你的種，晚上也不要歇你的手，因為你不知道哪一樣發旺；或是早撒的，或是晚撒的，或是兩樣都好。","notes":[]},{"n":7,"t":"光本是佳美的，眼見日光也是可悅的。","notes":[]},{"n":8,"t":"人活多年，就當快樂多年；然而也當想到黑暗的日子。因為這日子必多，所要來的都是虛空。","notes":[]},{"n":9,"t":"少年人哪，你在幼年時當快樂。在幼年的日子，使你的心歡暢，行你心所願行的，看你眼所愛看的；卻要知道，為這一切的事，神必審問你。","notes":[],"heads":["對年輕人的忠告"]},{"n":10,"t":"所以，你當從心中除掉愁煩，從肉體克去邪惡；因為一生的開端和幼年之時，都是虛空的。","notes":[]}]},"12":{"heading":"結論","verses":[{"n":1,"t":"你趁著年幼、衰敗的日子尚未來到，就是你所說，我毫無喜樂的那些年日未曾臨近之先，當記念造你的主。","notes":[]},{"n":2,"t":"不要等到日頭、光明、月亮、星宿變為黑暗，雨後雲彩反回，","notes":[]},{"n":3,"t":"看守房屋的發顫，有力的屈身，推磨的稀少就止息，從窗戶往外看的都昏暗；","notes":[]},{"n":4,"t":"街門關閉，推磨的響聲微小，雀鳥一叫，人就起來，唱歌的女子也都衰微。","notes":[]},{"n":5,"t":"人怕高處，路上有驚慌，杏樹開花，蚱蜢成為重擔，人所願的也都廢掉；因為人歸他永遠的家，弔喪的在街上往來。","notes":[]},{"n":6,"t":"銀鍊折斷，金罐破裂，瓶子在泉旁損壞，水輪在井口破爛，","notes":[]},{"n":7,"t":"塵土仍歸於地，靈仍歸於賜靈的神。","notes":[]},{"n":8,"t":"傳道者說：「虛空的虛空，凡事都是虛空。」","notes":[]},{"n":9,"t":"再者，傳道者因有智慧，仍將知識教訓眾人；又默想，又考查，又陳說許多箴言。","notes":[]},{"n":10,"t":"傳道者專心尋求可喜悅的言語，是憑正直寫的誠實話。","notes":[]},{"n":11,"t":"智慧人的言語好像刺棍；會中之師的言語又像釘穩的釘子，都是一個牧者所賜的。","notes":[]},{"n":12,"t":"我兒，還有一層，你當受勸戒：著書多，沒有窮盡；讀書多，身體疲倦。","notes":[]},{"n":13,"t":"這些事都已聽見了，總意就是：敬畏神，謹守他的誡命，這是人所當盡的本分。","notes":["或譯：這是眾人的本分"]},{"n":14,"t":"因為人所做的事，連一切隱藏的事，無論是善是惡，神都必審問。","notes":[]}]}},"SNG":{"1":{"heading":"第一首","verses":[{"n":1,"t":"所羅門的歌，是歌中的雅歌。","notes":[]},{"n":2,"t":"願他用口與我親嘴；因你的愛情比酒更美。","notes":[]},{"n":3,"t":"你的膏油馨香；你的名如同倒出來的香膏，所以眾童女都愛你。","notes":[]},{"n":4,"t":"願你吸引我，我們就快跑跟隨你。王帶我進了內室，我們必因你歡喜快樂。我們要稱讚你的愛情，勝似稱讚美酒。他們愛你是理所當然的。","notes":[]},{"n":5,"t":"耶路撒冷的眾女子啊，我雖然黑，卻是秀美，如同基達的帳棚，好像所羅門的幔子。","notes":[]},{"n":6,"t":"不要因日頭把我曬黑了就輕看我。我同母的弟兄向我發怒，他們使我看守葡萄園；我自己的葡萄園卻沒有看守。","notes":[]},{"n":7,"t":"我心所愛的啊，求你告訴我，你在何處牧羊？晌午在何處使羊歇臥？我何必在你同伴的羊群旁邊好像蒙著臉的人呢？","notes":[]},{"n":8,"t":"你這女子中極美麗的，你若不知道，只管跟隨羊群的腳蹤去，把你的山羊羔牧放在牧人帳棚的旁邊。","notes":[]},{"n":9,"t":"我的佳偶，我將你比法老車上套的駿馬。","notes":[]},{"n":10,"t":"你的兩腮因髮辮而秀美；你的頸項因珠串而華麗。","notes":[]},{"n":11,"t":"我們要為你編上金辮，鑲上銀釘。","notes":[]},{"n":12,"t":"王正坐席的時候，我的哪噠香膏發出香味。","notes":[]},{"n":13,"t":"我以我的良人為一袋沒藥，常在我懷中。","notes":[]},{"n":14,"t":"我以我的良人為一棵鳳仙花，在隱‧基底葡萄園中。","notes":[]},{"n":15,"t":"我的佳偶，你甚美麗！你甚美麗！你的眼好像鴿子眼。","notes":[]},{"n":16,"t":"我的良人哪，你甚美麗可愛！我們以青草為床榻，","notes":[]},{"n":17,"t":"以香柏樹為房屋的棟樑，以松樹為椽子。","notes":[]}]},"2":{"heading":"第二首","verses":[{"n":1,"t":"我是沙崙的玫瑰花，是谷中的百合花。","notes":["或譯：水仙花"]},{"n":2,"t":"我的佳偶在女子中，好像百合花在荊棘內。","notes":[]},{"n":3,"t":"我的良人在男子中，如同蘋果樹在樹林中。我歡歡喜喜坐在他的蔭下，嘗他果子的滋味，覺得甘甜。","notes":[]},{"n":4,"t":"他帶我入筵宴所，以愛為旗在我以上。","notes":[]},{"n":5,"t":"求你們給我葡萄乾增補我力，給我蘋果暢快我心，因我思愛成病。","notes":[]},{"n":6,"t":"他的左手在我頭下；他的右手將我抱住。","notes":[]},{"n":7,"t":"耶路撒冷的眾女子啊，我指著羚羊或田野的母鹿囑咐你們：不要驚動、不要叫醒我所親愛的，等他自己情願。","notes":["不要叫醒<ins>.</ins>.情願：或譯不要激動愛情，等它自發"]},{"n":8,"t":"聽啊！是我良人的聲音；看哪！他躥山越嶺而來。","notes":[]},{"n":9,"t":"我的良人好像羚羊，或像小鹿。他站在我們牆壁後，從窗戶往裏觀看，從窗欞往裏窺探。","notes":[]},{"n":10,"t":"我良人對我說：我的佳偶，我的美人，起來，與我同去！","notes":[]},{"n":11,"t":"因為冬天已往，雨水止住過去了。","notes":[]},{"n":12,"t":"地上百花開放，百鳥鳴叫的時候已經來到；斑鳩的聲音在我們境內也聽見了。","notes":["或譯：修理葡萄樹的時候"]},{"n":13,"t":"無花果樹的果子漸漸成熟；葡萄樹開花放香。我的佳偶，我的美人，起來，與我同去！","notes":[]},{"n":14,"t":"我的鴿子啊，你在磐石穴中，在陡巖的隱密處。求你容我得見你的面貌，得聽你的聲音；因為你的聲音柔和，你的面貌秀美。","notes":[]},{"n":15,"t":"要給我們擒拿狐狸，就是毀壞葡萄園的小狐狸，因為我們的葡萄正在開花。","notes":[]},{"n":16,"t":"良人屬我，我也屬他；他在百合花中牧放群羊。","notes":[]},{"n":17,"t":"我的良人哪，求你等到天起涼風、日影飛去的時候，你要轉回，好像羚羊，或像小鹿在比特山上。","notes":[]}]},"3":{"heading":"第三首","verses":[{"n":1,"t":"我夜間躺臥在床上，尋找我心所愛的；我尋找他，卻尋不見。","notes":[]},{"n":2,"t":"我說：我要起來，遊行城中，在街市上，在寬闊處，尋找我心所愛的。我尋找他，卻尋不見。","notes":[]},{"n":3,"t":"城中巡邏看守的人遇見我；我問他們：你們看見我心所愛的沒有？","notes":[]},{"n":4,"t":"我剛離開他們就遇見我心所愛的。我拉住他，不容他走，領他入我母家，到懷我者的內室。","notes":[]},{"n":5,"t":"耶路撒冷的眾女子啊，我指著羚羊或田野的母鹿囑咐你們：不要驚動、不要叫醒我所親愛的，等他自己情願。","notes":["不要叫醒<ins>.</ins>.情願：或譯不要激動愛情，等它自發"]},{"n":6,"t":"那從曠野上來、形狀如煙柱、以沒藥和乳香並商人各樣香粉薰的是誰呢？","notes":[]},{"n":7,"t":"看哪，是所羅門的轎；四圍有六十個勇士，都是以色列中的勇士；","notes":[]},{"n":8,"t":"手都持刀，善於爭戰，腰間佩刀，防備夜間有驚慌。","notes":[]},{"n":9,"t":"所羅門王用黎巴嫩木為自己製造一乘華轎。","notes":[]},{"n":10,"t":"轎柱是用銀做的，轎底是用金做的；坐墊是紫色的，其中所鋪的乃耶路撒冷眾女子的愛情。","notes":[]},{"n":11,"t":"錫安的眾女子啊，你們出去觀看所羅門王！頭戴冠冕，就是在他婚筵的日子、心中喜樂的時候，他母親給他戴上的。","notes":[]}]},"4":{"heading":"","verses":[{"n":1,"t":"我的佳偶，你甚美麗！你甚美麗！你的眼在帕子內好像鴿子眼。你的頭髮如同山羊群臥在基列山旁。","notes":[]},{"n":2,"t":"你的牙齒如新剪毛的一群母羊，洗淨上來，個個都有雙生，沒有一隻喪掉子的。","notes":[]},{"n":3,"t":"你的唇好像一條朱紅線；你的嘴也秀美。你的兩太陽在帕子內，如同一塊石榴。","notes":[]},{"n":4,"t":"你的頸項好像大衛建造收藏軍器的高臺，其上懸掛一千盾牌，都是勇士的籐牌。","notes":[]},{"n":5,"t":"你的兩乳好像百合花中吃草的一對小鹿，就是母鹿雙生的。","notes":[]},{"n":6,"t":"我要往沒藥山和乳香岡去，直等到天起涼風、日影飛去的時候回來。","notes":[]},{"n":7,"t":"我的佳偶，你全然美麗，毫無瑕疵！","notes":[]},{"n":8,"t":"我的新婦，求你與我一同離開黎巴嫩，與我一同離開黎巴嫩。從亞瑪拿頂，從示尼珥與黑門頂，從有獅子的洞，從有豹子的山往下觀看。","notes":[]},{"n":9,"t":"我妹子，我新婦，你奪了我的心。你用眼一看，用你項上的一條金鍊，奪了我的心！","notes":[]},{"n":10,"t":"我妹子，我新婦，你的愛情何其美！你的愛情比酒更美！你膏油的香氣勝過一切香品！","notes":[]},{"n":11,"t":"我新婦，你的嘴唇滴蜜，好像蜂房滴蜜；你的舌下有蜜，有奶。你衣服的香氣如黎巴嫩的香氣。","notes":[]},{"n":12,"t":"我妹子，我新婦，乃是關鎖的園，禁閉的井，封閉的泉源。","notes":[]},{"n":13,"t":"你園內所種的結了石榴，有佳美的果子，並鳳仙花與哪噠樹。","notes":[]},{"n":14,"t":"有哪噠和番紅花，菖蒲和桂樹，並各樣乳香木、沒藥、沉香，與一切上等的果品。","notes":[]},{"n":15,"t":"你是園中的泉，活水的井，從黎巴嫩流下來的溪水。","notes":[]},{"n":16,"t":"北風啊，興起！南風啊，吹來！吹在我的園內，使其中的香氣發出來。願我的良人進入自己園裏，吃他佳美的果子。","notes":[]}]},"5":{"heading":"第四首","verses":[{"n":1,"t":"我妹子，我新婦，我進了我的園中，採了我的沒藥和香料，吃了我的蜜房和蜂蜜，喝了我的酒和奶。我的朋友們，請吃！我所親愛的，請喝，且多多地喝！","notes":[]},{"n":2,"t":"我身睡臥，我心卻醒。這是我良人的聲音；他敲門說：我的妹子，我的佳偶，我的鴿子，我的完全人，求你給我開門；因我的頭滿了露水，我的頭髮被夜露滴濕。","notes":[]},{"n":3,"t":"我回答說：我脫了衣裳，怎能再穿上呢？我洗了腳，怎能再玷污呢？","notes":[]},{"n":4,"t":"我的良人從門孔裏伸進手來，我便因他動了心。","notes":[]},{"n":5,"t":"我起來，要給我良人開門。我的兩手滴下沒藥；我的指頭有沒藥汁滴在門閂上。","notes":[]},{"n":6,"t":"我給我的良人開了門；我的良人卻已轉身走了。他說話的時候，我神不守舍；我尋找他，竟尋不見；我呼叫他，他卻不回答。","notes":[]},{"n":7,"t":"城中巡邏看守的人遇見我，打了我，傷了我；看守城牆的人奪去我的披肩。","notes":[]},{"n":8,"t":"耶路撒冷的眾女子啊，我囑咐你們：若遇見我的良人，要告訴他，我因思愛成病。","notes":[]},{"n":9,"t":"你這女子中極美麗的，你的良人比別人的良人有何強處？你的良人比別人的良人有何強處，你就這樣囑咐我們？","notes":[]},{"n":10,"t":"我的良人白而且紅，超乎萬人之上。","notes":[]},{"n":11,"t":"他的頭像至精的金子；他的頭髮厚密纍垂，黑如烏鴉。","notes":[]},{"n":12,"t":"他的眼如溪水旁的鴿子眼，用奶洗淨，安得合式。","notes":[]},{"n":13,"t":"他的兩腮如香花畦，如香草臺；他的嘴唇像百合花，且滴下沒藥汁。","notes":[]},{"n":14,"t":"他的兩手好像金管，鑲嵌水蒼玉；他的身體如同雕刻的象牙，周圍鑲嵌藍寶石。","notes":[]},{"n":15,"t":"他的腿好像白玉石柱，安在精金座上；他的形狀如黎巴嫩，且佳美如香柏樹。","notes":[]},{"n":16,"t":"他的口極其甘甜；他全然可愛。耶路撒冷的眾女子啊，這是我的良人；這是我的朋友。","notes":[]}]},"6":{"heading":"第五首","verses":[{"n":1,"t":"你這女子中極美麗的，你的良人往何處去了？你的良人轉向何處去了，我們好與你同去尋找他。","notes":[]},{"n":2,"t":"我的良人下入自己園中，到香花畦，在園內牧放群羊，採百合花。","notes":[]},{"n":3,"t":"我屬我的良人，我的良人也屬我；他在百合花中牧放群羊。","notes":[]},{"n":4,"t":"我的佳偶啊，你美麗如得撒，秀美如耶路撒冷，威武如展開旌旗的軍隊。","notes":[]},{"n":5,"t":"求你掉轉眼目不看我，因你的眼目使我驚亂。你的頭髮如同山羊群臥在基列山旁。","notes":[]},{"n":6,"t":"你的牙齒如一群母羊洗淨上來，個個都有雙生，沒有一隻喪掉子的。","notes":[]},{"n":7,"t":"你的兩太陽在帕子內，如同一塊石榴。","notes":[]},{"n":8,"t":"有六十王后八十妃嬪，並有無數的童女。","notes":[]},{"n":9,"t":"我的鴿子，我的完全人，只有這一個是她母親獨生的，是生養她者所寶愛的。眾女子見了就稱她有福；王后妃嬪見了也讚美她。","notes":[]},{"n":10,"t":"那向外觀看、如晨光發現、美麗如月亮、皎潔如日頭、威武如展開旌旗軍隊的是誰呢？","notes":[]},{"n":11,"t":"我下入核桃園，要看谷中青綠的植物，要看葡萄發芽沒有，石榴開花沒有。","notes":[]},{"n":12,"t":"不知不覺，我的心將我安置在我尊長的車中。","notes":[]},{"n":13,"t":"回來，回來，書拉密女；你回來，你回來，使我們得觀看你。你們為何要觀看書拉密女，像觀看瑪哈念跳舞的呢？","notes":[]}]},"7":{"heading":"","verses":[{"n":1,"t":"王女啊，你的腳在鞋中何其美好！你的大腿圓潤，好像美玉，是巧匠的手做成的。","notes":[]},{"n":2,"t":"你的肚臍如圓杯，不缺調和的酒；你的腰如一堆麥子，周圍有百合花。","notes":[]},{"n":3,"t":"你的兩乳好像一對小鹿，就是母鹿雙生的。","notes":[]},{"n":4,"t":"你的頸項如象牙臺；你的眼目像希實本、巴特‧拉併門旁的水池；你的鼻子彷彿朝大馬士革的黎巴嫩塔。","notes":[]},{"n":5,"t":"你的頭在你身上好像迦密山；你頭上的髮是紫黑色；王的心因這下垂的髮綹繫住了。","notes":[]},{"n":6,"t":"我所愛的，你何其美好！何其可悅，使人歡暢喜樂！","notes":[]},{"n":7,"t":"你的身量好像棕樹；你的兩乳如同其上的果子，纍纍下垂。","notes":[]},{"n":8,"t":"我說：我要上這棕樹，抓住枝子。願你的兩乳好像葡萄纍纍下垂，你鼻子的氣味香如蘋果；","notes":[]},{"n":9,"t":"你的口如上好的酒。女子說：為我的良人下咽舒暢，流入睡覺人的嘴中。","notes":[]},{"n":10,"t":"我屬我的良人，他也戀慕我。","notes":[]},{"n":11,"t":"我的良人，來吧！你我可以往田間去；你我可以在村莊住宿。","notes":[]},{"n":12,"t":"我們早晨起來往葡萄園去，看看葡萄發芽開花沒有，石榴放蕊沒有；我在那裏要將我的愛情給你。","notes":[]},{"n":13,"t":"風茄放香，在我們的門內有各樣新陳佳美的果子；我的良人，這都是我為你存留的。","notes":[]}]},"8":{"heading":"第六首","verses":[{"n":1,"t":"巴不得你像我的兄弟，像吃我母親奶的兄弟；我在外頭遇見你就與你親嘴，誰也不輕看我。","notes":[]},{"n":2,"t":"我必引導你，領你進我母親的家；我可以領受教訓，也就使你喝石榴汁釀的香酒。","notes":[]},{"n":3,"t":"他的左手必在我頭下；他的右手必將我抱住。","notes":[]},{"n":4,"t":"耶路撒冷的眾女子啊，我囑咐你們：不要驚動、不要叫醒我所親愛的，等他自己情願。","notes":["不要叫醒<ins>.</ins>.情願：或譯不要激動愛情，等它自發"]},{"n":5,"t":"那靠著良人從曠野上來的是誰呢？我在蘋果樹下叫醒你。你母親在那裏為你劬勞；生養你的在那裏為你劬勞。","notes":[]},{"n":6,"t":"求你將我放在你心上如印記，帶在你臂上如戳記。因為愛情如死之堅強，嫉恨如陰間之殘忍；所發的電光是火焰的電光，是耶和華的烈焰。","notes":[]},{"n":7,"t":"愛情，眾水不能熄滅，大水也不能淹沒。若有人拿家中所有的財寶要換愛情，就全被藐視。","notes":[]},{"n":8,"t":"我們有一小妹；她的兩乳尚未長成，人來提親的日子，我們當為她怎樣辦理？","notes":[]},{"n":9,"t":"她若是牆，我們要在其上建造銀塔；她若是門，我們要用香柏木板圍護她。","notes":[]},{"n":10,"t":"我是牆；我兩乳像其上的樓。那時，我在他眼中像得平安的人。","notes":[]},{"n":11,"t":"所羅門在巴力‧哈們有一葡萄園；他將這葡萄園交給看守的人，為其中的果子必交一千舍客勒銀子。","notes":[]},{"n":12,"t":"我自己的葡萄園在我面前。所羅門哪，一千舍客勒歸你，二百舍客勒歸看守果子的人。","notes":[]},{"n":13,"t":"你這住在園中的，同伴都要聽你的聲音，求你使我也得聽見。","notes":[]},{"n":14,"t":"我的良人哪，求你快來！如羚羊或小鹿在香草山上。","notes":[]}]}},"ISA":{"1":{"heading":"神責備以色列","verses":[{"n":1,"t":"當烏西雅、約坦、亞哈斯、希西家作猶大王的時候，亞摩斯的兒子以賽亞得默示，論到猶大和耶路撒冷。","notes":[]},{"n":2,"t":"天哪，要聽！地啊，側耳而聽！因為耶和華說：我養育兒女，將他們養大，他們竟悖逆我。","notes":[]},{"n":3,"t":"牛認識主人，驢認識主人的槽，以色列卻不認識；我的民卻不留意。","notes":[]},{"n":4,"t":"嗐！犯罪的國民，擔著罪孽的百姓；行惡的種類，敗壞的兒女！他們離棄耶和華，藐視以色列的聖者，與他生疏，往後退步。","notes":[]},{"n":5,"t":"你們為甚麼屢次悖逆，還要受責打嗎？你們已經滿頭疼痛，全心發昏。","notes":[]},{"n":6,"t":"從腳掌到頭頂，沒有一處完全的，盡是傷口、青腫，與新打的傷痕，都沒有收口，沒有纏裹，也沒有用膏滋潤。","notes":[]},{"n":7,"t":"你們的地土已經荒涼；你們的城邑被火焚毀。你們的田地在你們眼前為外邦人所侵吞，既被外邦人傾覆就成為荒涼。","notes":[]},{"n":8,"t":"僅存錫安城，好像葡萄園的草棚，瓜田的茅屋，被圍困的城邑。","notes":["原文是女子"]},{"n":9,"t":"若不是萬軍之耶和華給我們稍留餘種，我們早已像所多瑪、蛾摩拉的樣子了。","notes":[]},{"n":10,"t":"你們這所多瑪的官長啊，要聽耶和華的話！你們這蛾摩拉的百姓啊，要側耳聽我們神的訓誨！","notes":[]},{"n":11,"t":"耶和華說：你們所獻的許多祭物與我何益呢？公綿羊的燔祭和肥畜的脂油，我已經夠了；公牛的血，羊羔的血，公山羊的血，我都不喜悅。","notes":[]},{"n":12,"t":"你們來朝見我，誰向你們討這些，使你們踐踏我的院宇呢？","notes":[]},{"n":13,"t":"你們不要再獻虛浮的供物。香品是我所憎惡的；月朔和安息日，並宣召的大會，也是我所憎惡的；作罪孽，又守嚴肅會，我也不能容忍。","notes":[]},{"n":14,"t":"你們的月朔和節期，我心裏恨惡，我都以為麻煩；我擔當，便不耐煩。","notes":[]},{"n":15,"t":"你們舉手禱告，我必遮眼不看；就是你們多多地祈禱，我也不聽。你們的手都滿了殺人的血。","notes":[]},{"n":16,"t":"你們要洗濯、自潔，從我眼前除掉你們的惡行，要止住作惡，","notes":[]},{"n":17,"t":"學習行善，尋求公平，解救受欺壓的；給孤兒伸冤，為寡婦辨屈。","notes":[]},{"n":18,"t":"耶和華說：你們來，我們彼此辯論。你們的罪雖像硃紅，必變成雪白；雖紅如丹顏，必白如羊毛。","notes":[]},{"n":19,"t":"你們若甘心聽從，必吃地上的美物，","notes":[]},{"n":20,"t":"若不聽從，反倒悖逆，必被刀劍吞滅。這是耶和華親口說的。","notes":[]},{"n":21,"t":"可歎，忠信的城變為妓女！從前充滿了公平，公義居在其中，現今卻有兇手居住。","notes":[],"heads":["罪大惡極的城"]},{"n":22,"t":"你的銀子變為渣滓；你的酒用水攙對。","notes":[]},{"n":23,"t":"你的官長居心悖逆，與盜賊作伴，各都喜愛賄賂，追求贓私。他們不為孤兒伸冤；寡婦的案件也不得呈到他們面前。","notes":[]},{"n":24,"t":"因此，主－萬軍之耶和華、以色列的大能者說：哎！我要向我的對頭雪恨，向我的敵人報仇。","notes":[]},{"n":25,"t":"我必反手加在你身上，煉盡你的渣滓，除淨你的雜質。","notes":[]},{"n":26,"t":"我也必復還你的審判官，像起初一樣，復還你的謀士，像起先一般。然後，你必稱為公義之城，忠信之邑。","notes":[]},{"n":27,"t":"錫安必因公平得蒙救贖；其中歸正的人必因公義得蒙救贖。","notes":[]},{"n":28,"t":"但悖逆的和犯罪的必一同敗亡；離棄耶和華的必致消滅。","notes":[]},{"n":29,"t":"那等人必因你們所喜愛的橡樹抱愧；你們必因所選擇的園子蒙羞。","notes":[]},{"n":30,"t":"因為，你們必如葉子枯乾的橡樹，好像無水澆灌的園子。","notes":[]},{"n":31,"t":"有權勢的必如麻瓤；他的工作好像火星，都要一同焚毀，無人撲滅。","notes":[]}]},"2":{"heading":"永恆的和平","verses":[{"n":1,"t":"亞摩斯的兒子以賽亞得默示，論到猶大和耶路撒冷。","notes":[]},{"n":2,"t":"末後的日子，耶和華殿的山必堅立，超乎諸山，高舉過於萬嶺；萬民都要流歸這山。","notes":[]},{"n":3,"t":"必有許多國的民前往，說：來吧，我們登耶和華的山，奔雅各神的殿。主必將他的道教訓我們；我們也要行他的路。因為訓誨必出於錫安；耶和華的言語必出於耶路撒冷。","notes":[]},{"n":4,"t":"他必在列國中施行審判，為許多國民斷定是非。他們要將刀打成犂頭，把槍打成鐮刀。這國不舉刀攻擊那國；他們也不再學習戰事。","notes":[]},{"n":5,"t":"雅各家啊，來吧！我們在耶和華的光明中行走。","notes":[]},{"n":6,"t":"耶和華，你離棄了你百姓雅各家，是因他們充滿了東方的風俗，作觀兆的，像非利士人一樣，並與外邦人擊掌。","notes":[],"heads":["驕者必敗"]},{"n":7,"t":"他們的國滿了金銀，財寶也無窮；他們的地滿了馬匹，車輛也無數。","notes":[]},{"n":8,"t":"他們的地滿了偶像；他們跪拜自己手所造的，就是自己指頭所做的。","notes":[]},{"n":9,"t":"卑賤人屈膝；尊貴人下跪；所以不可饒恕他們。","notes":[]},{"n":10,"t":"你當進入巖穴，藏在土中，躲避耶和華的驚嚇和他威嚴的榮光。","notes":[]},{"n":11,"t":"到那日，眼目高傲的必降為卑；性情狂傲的都必屈膝；惟獨耶和華被尊崇。","notes":[]},{"n":12,"t":"必有萬軍耶和華降罰的一個日子，要臨到驕傲狂妄的；一切自高的都必降為卑；","notes":[]},{"n":13,"t":"又臨到黎巴嫩高大的香柏樹和巴珊的橡樹；","notes":[]},{"n":14,"t":"又臨到一切高山的峻嶺；","notes":[]},{"n":15,"t":"又臨到高臺和堅固城牆；","notes":[]},{"n":16,"t":"又臨到他施的船隻並一切可愛的美物。","notes":[]},{"n":17,"t":"驕傲的必屈膝；狂妄的必降卑。在那日，惟獨耶和華被尊崇；","notes":[]},{"n":18,"t":"偶像必全然廢棄。","notes":[]},{"n":19,"t":"耶和華興起，使地大震動的時候，人就進入石洞，進入土穴，躲避耶和華的驚嚇和他威嚴的榮光。","notes":[]},{"n":20,"t":"到那日，人必將為拜而造的金偶像、銀偶像拋給田鼠和蝙蝠。","notes":[]},{"n":21,"t":"到耶和華興起，使地大震動的時候，人好進入磐石洞中和巖石穴裏，躲避耶和華的驚嚇和他威嚴的榮光。","notes":[]},{"n":22,"t":"你們休要倚靠世人。他鼻孔裏不過有氣息；他在一切事上可算甚麼呢？","notes":[]}]},"3":{"heading":"耶路撒冷的混亂","verses":[{"n":1,"t":"主－萬軍之耶和華從耶路撒冷和猶大，除掉眾人所倚靠的，所仗賴的，就是所倚靠的糧，所仗賴的水；","notes":[]},{"n":2,"t":"除掉勇士和戰士，審判官和先知，占卜的和長老，","notes":[]},{"n":3,"t":"五十夫長和尊貴人，謀士和有巧藝的，以及妙行法術的。","notes":[]},{"n":4,"t":"主說：我必使孩童作他們的首領，使嬰孩轄管他們。","notes":[]},{"n":5,"t":"百姓要彼此欺壓；各人受鄰舍的欺壓。少年人必侮慢老年人；卑賤人必侮慢尊貴人。","notes":[]},{"n":6,"t":"人在父家拉住弟兄，說：你有衣服，可以作我們的官長。這敗落的事歸在你手下吧！","notes":[]},{"n":7,"t":"那時，他必揚聲說：我不作醫治你們的人；因我家中沒有糧食，也沒有衣服，你們不可立我作百姓的官長。","notes":[]},{"n":8,"t":"耶路撒冷敗落，猶大傾倒；因為他們的舌頭和行為與耶和華反對，惹了他榮光的眼目。","notes":[]},{"n":9,"t":"他們的面色證明自己的不正；他們述說自己的罪惡，並不隱瞞，好像所多瑪一樣。他們有禍了！因為作惡自害。","notes":[]},{"n":10,"t":"你們要論義人說：他必享福樂，因為要吃自己行為所結的果子。","notes":[]},{"n":11,"t":"惡人有禍了！他必遭災難！因為要照自己手所行的受報應。","notes":[]},{"n":12,"t":"至於我的百姓，孩童欺壓他們，婦女轄管他們。我的百姓啊，引導你的使你走錯，並毀壞你所行的道路。","notes":[]},{"n":13,"t":"耶和華起來辯論，站著審判眾民。","notes":[],"heads":["耶和華審判他的子民"]},{"n":14,"t":"耶和華必審問他民中的長老和首領，說：吃盡葡萄園果子的就是你們；向貧窮人所奪的都在你們家中。","notes":[]},{"n":15,"t":"主－萬軍之耶和華說：你們為何壓制我的百姓，搓磨貧窮人的臉呢？","notes":[]},{"n":16,"t":"耶和華又說：因為錫安的女子狂傲，行走挺項，賣弄眼目，俏步徐行，腳下玎璫，","notes":[],"heads":["對耶路撒冷女子的警告"]},{"n":17,"t":"所以，主必使錫安的女子頭長禿瘡；耶和華又使她們赤露下體。","notes":[]},{"n":18,"t":"到那日，主必除掉她們華美的腳釧、髮網、月牙圈、","notes":[]},{"n":19,"t":"耳環、手鐲、蒙臉的帕子、","notes":[]},{"n":20,"t":"華冠、足鍊、華帶、香盒、符囊、","notes":[]},{"n":21,"t":"戒指、鼻環、","notes":[]},{"n":22,"t":"吉服、外套、雲肩、荷包、","notes":[]},{"n":23,"t":"手鏡、細麻衣、裹頭巾、蒙身的帕子。","notes":[]},{"n":24,"t":"必有臭爛代替馨香，繩子代替腰帶，光禿代替美髮，麻衣繫腰代替華服，烙傷代替美容。","notes":[]},{"n":25,"t":"你的男丁必倒在刀下；你的勇士必死在陣上。","notes":[]},{"n":26,"t":"錫安的城門必悲傷、哀號；她必荒涼坐在地上。","notes":["原文是她"]}]},"4":{"heading":"耶路撒冷的重建","verses":[{"n":1,"t":"在那日，七個女人必拉住一個男人，說：「我們吃自己的食物，穿自己的衣服，但求你許我們歸你名下；求你除掉我們的羞恥。」","notes":[]},{"n":2,"t":"到那日，耶和華發生的苗必華美尊榮，地的出產必為以色列逃脫的人顯為榮華茂盛。","notes":[]},{"n":3,"t":"主以公義的靈和焚燒的靈，將錫安女子的污穢洗去，又將耶路撒冷中殺人的血除淨。那時，剩在錫安、留在耶路撒冷的，就是一切住耶路撒冷、在生命冊上記名的，必稱為聖。","notes":[],"end":4},{"n":5,"t":"耶和華也必在錫安全山，並各會眾以上，使白日有煙雲，黑夜有火焰的光。因為在全榮耀之上必有遮蔽。","notes":[]},{"n":6,"t":"必有亭子，白日可以得蔭避暑，也可以作為藏身之處，躲避狂風暴雨。","notes":[]}]},"5":{"heading":"葡萄園之歌","verses":[{"n":1,"t":"我要為我所親愛的唱歌，是我所愛者的歌，論他葡萄園的事：我所親愛的有葡萄園在肥美的山岡上。","notes":[]},{"n":2,"t":"他刨挖園子，撿去石頭，栽種上等的葡萄樹，在園中蓋了一座樓，又鑿出壓酒池；指望結好葡萄，反倒結了野葡萄。","notes":[]},{"n":3,"t":"耶路撒冷的居民和猶大人哪，請你們現今在我與我的葡萄園中，斷定是非。","notes":[]},{"n":4,"t":"我為我葡萄園所做之外，還有甚麼可做的呢？我指望結好葡萄，怎麼倒結了野葡萄呢？","notes":[]},{"n":5,"t":"現在我告訴你們，我要向我葡萄園怎樣行：我必撤去籬笆，使它被吞滅，拆毀牆垣，使它被踐踏。","notes":[]},{"n":6,"t":"我必使它荒廢，不再修理，不再鋤刨，荊棘蒺藜倒要生長。我也必命雲不降雨在其上。","notes":[]},{"n":7,"t":"萬軍之耶和華的葡萄園就是以色列家；他所喜愛的樹就是猶大人。他指望的是公平，誰知倒有暴虐；指望的是公義，誰知倒有冤聲。","notes":["或譯：倒流人血"]},{"n":8,"t":"禍哉！那些以房接房，以地連地，以致不留餘地的，只顧自己獨居境內。","notes":[],"heads":["人的惡行"]},{"n":9,"t":"我耳聞萬軍之耶和華說：必有許多又大又美的房屋成為荒涼，無人居住。","notes":[]},{"n":10,"t":"三十畝葡萄園只出一罷特酒；一賀梅珥穀種只結一伊法糧食。","notes":[]},{"n":11,"t":"禍哉！那些清早起來追求濃酒，留連到夜深，甚至因酒發燒的人。","notes":[]},{"n":12,"t":"他們在筵席上彈琴，鼓瑟，擊鼓，吹笛，飲酒，卻不顧念耶和華的作為，也不留心他手所做的。","notes":[]},{"n":13,"t":"所以，我的百姓因無知就被擄去；他們的尊貴人甚是飢餓，群眾極其乾渴。","notes":[]},{"n":14,"t":"故此，陰間擴張其欲，開了無限量的口；他們的榮耀、群眾、繁華，並快樂的人都落在其中。","notes":[]},{"n":15,"t":"卑賤人被壓服；尊貴人降為卑；眼目高傲的人也降為卑。","notes":[]},{"n":16,"t":"惟有萬軍之耶和華因公平而崇高；聖者神因公義顯為聖。","notes":[]},{"n":17,"t":"那時，羊羔必來吃草，如同在自己的草場；豐肥人的荒場被遊行的人吃盡。","notes":[]},{"n":18,"t":"禍哉！那些以虛假之細繩牽罪孽的人！他們又像以套繩拉罪惡，","notes":[]},{"n":19,"t":"說：任他急速行，趕快成就他的作為，使我們看看；任以色列聖者所謀劃的臨近成就，使我們知道。","notes":[]},{"n":20,"t":"禍哉！那些稱惡為善，稱善為惡，以暗為光，以光為暗，以苦為甜，以甜為苦的人。","notes":[]},{"n":21,"t":"禍哉！那些自以為有智慧，自看為通達的人。","notes":[]},{"n":22,"t":"禍哉！那些勇於飲酒，以能力調濃酒的人。","notes":[]},{"n":23,"t":"他們因受賄賂，就稱惡人為義，將義人的義奪去。","notes":[]},{"n":24,"t":"火苗怎樣吞滅碎稭，乾草怎樣落在火焰之中，照樣，他們的根必像朽物，他們的花必像灰塵飛騰；因為他們厭棄萬軍之耶和華的訓誨，藐視以色列聖者的言語。","notes":[]},{"n":25,"t":"所以，耶和華的怒氣向他的百姓發作。他的手伸出攻擊他們，山嶺就震動；他們的屍首在街市上好像糞土。雖然如此，他的怒氣還未轉消；他的手仍伸不縮。","notes":[]},{"n":26,"t":"他必豎立大旗，招遠方的國民，發嘶聲叫他們從地極而來；看哪，他們必急速奔來。","notes":[]},{"n":27,"t":"其中沒有疲倦的，絆跌的；沒有打盹的，睡覺的；腰帶並不放鬆，鞋帶也不折斷。","notes":[]},{"n":28,"t":"他們的箭快利，弓也上了弦。馬蹄算如堅石，車輪好像旋風。","notes":[]},{"n":29,"t":"他們要吼叫，像母獅子，咆哮，像少壯獅子；他們要咆哮抓食，坦然叼去，無人救回。","notes":[]},{"n":30,"t":"那日，他們要向以色列人吼叫，像海浪匉訇；人若望地，只見黑暗艱難，光明在雲中變為昏暗。","notes":[]}]},"6":{"heading":"主呼召以賽亞作先知","verses":[{"n":1,"t":"當烏西雅王崩的那年，我見主坐在高高的寶座上。他的衣裳垂下，遮滿聖殿。","notes":[]},{"n":2,"t":"其上有撒拉弗侍立，各有六個翅膀：用兩個翅膀遮臉，兩個翅膀遮腳，兩個翅膀飛翔；","notes":[]},{"n":3,"t":"彼此呼喊說：聖哉！聖哉！聖哉！萬軍之耶和華；他的榮光充滿全地！","notes":[]},{"n":4,"t":"因呼喊者的聲音，門檻的根基震動，殿充滿了煙雲。","notes":[]},{"n":5,"t":"那時我說：「禍哉！我滅亡了！因為我是嘴唇不潔的人，又住在嘴唇不潔的民中，又因我眼見大君王－萬軍之耶和華。」","notes":[]},{"n":6,"t":"有一撒拉弗飛到我跟前，手裏拿著紅炭，是用火剪從壇上取下來的，","notes":[]},{"n":7,"t":"將炭沾我的口，說：「看哪，這炭沾了你的嘴，你的罪孽便除掉，你的罪惡就赦免了。」","notes":[]},{"n":8,"t":"我又聽見主的聲音說：「我可以差遣誰呢？誰肯為我們去呢？」我說：「我在這裏，請差遣我！」","notes":[]},{"n":9,"t":"他說：「你去告訴這百姓說：你們聽是要聽見，卻不明白；看是要看見，卻不曉得。","notes":[]},{"n":10,"t":"要使這百姓心蒙脂油，耳朵發沉，眼睛昏迷；恐怕眼睛看見，耳朵聽見，心裏明白，回轉過來，便得醫治。」","notes":[]},{"n":11,"t":"我就說：「主啊，這到幾時為止呢？」他說：直到城邑荒涼，無人居住，房屋空閒無人，地土極其荒涼。","notes":[]},{"n":12,"t":"並且耶和華將人遷到遠方，在這境內撇下的地土很多。","notes":[]},{"n":13,"t":"境內剩下的人若還有十分之一，也必被吞滅，像栗樹、橡樹雖被砍伐，樹墩子卻仍存留。這聖潔的種類在國中也是如此。","notes":[]}]},"7":{"heading":"傳給亞哈斯王的信息","verses":[{"n":1,"t":"烏西雅的孫子、約坦的兒子、猶大王亞哈斯在位的時候，亞蘭王利汛和利瑪利的兒子、以色列王比加上來攻打耶路撒冷，卻不能攻取。","notes":[]},{"n":2,"t":"有人告訴大衛家說：「亞蘭與以法蓮已經同盟。」王的心和百姓的心就都跳動，好像林中的樹被風吹動一樣。","notes":[]},{"n":3,"t":"耶和華對以賽亞說：「你和你的兒子施亞雅述出去，到上池的水溝頭，在漂布地的大路上，去迎接亞哈斯，","notes":[]},{"n":4,"t":"對他說：『你要謹慎安靜，不要因亞蘭王利汛和利瑪利的兒子這兩個冒煙的火把頭所發的烈怒害怕，也不要心裏膽怯。","notes":[]},{"n":5,"t":"因為亞蘭和以法蓮，並利瑪利的兒子，設惡謀害你，","notes":[]},{"n":6,"t":"說：我們可以上去攻擊猶大，擾亂它，攻破它，在其中立他比勒的兒子為王。","notes":[]},{"n":7,"t":"所以主耶和華如此說：這所謀的必立不住，也不得成就。","notes":[]},{"n":8,"t":"原來亞蘭的首城是大馬士革；大馬士革的首領是利汛。（六十五年之內，以法蓮必然破壞，不再成為國民。）","notes":[]},{"n":9,"t":"以法蓮的首城是撒馬利亞；撒馬利亞的首領是利瑪利的兒子。你們若是不信，定然不得立穩。』」","notes":[]},{"n":10,"t":"耶和華又曉諭亞哈斯說：","notes":[],"heads":["以馬內利的記號"]},{"n":11,"t":"「你向耶和華－你的神求一個兆頭：或求顯在深處，或求顯在高處。」","notes":[]},{"n":12,"t":"亞哈斯說：「我不求；我不試探耶和華。」","notes":[]},{"n":13,"t":"以賽亞說：「大衛家啊，你們當聽！你們使人厭煩豈算小事，還要使我的神厭煩嗎？","notes":[]},{"n":14,"t":"因此，主自己要給你們一個兆頭，必有童女懷孕生子，給他起名叫以馬內利。","notes":["就是神與我們同在的意思"]},{"n":15,"t":"到他曉得棄惡擇善的時候，他必吃奶油與蜂蜜。","notes":[]},{"n":16,"t":"因為在這孩子還不曉得棄惡擇善之先，你所憎惡的那二王之地必致見棄。","notes":[]},{"n":17,"t":"耶和華必使亞述王攻擊你的日子臨到你和你的百姓，並你的父家，自從以法蓮離開猶大以來，未曾有這樣的日子。","notes":[]},{"n":18,"t":"「那時，耶和華要發嘶聲，使埃及江河源頭的蒼蠅和亞述地的蜂子飛來；","notes":[]},{"n":19,"t":"都必飛來，落在荒涼的谷內、磐石的穴裏，和一切荊棘籬笆中，並一切的草場上。","notes":[]},{"n":20,"t":"「那時，主必用大河外賃的剃頭刀，就是亞述王，剃去頭髮和腳上的毛，並要剃淨鬍鬚。","notes":[]},{"n":21,"t":"「那時，一個人要養活一隻母牛犢，兩隻母綿羊；","notes":[]},{"n":22,"t":"因為出的奶多，他就得吃奶油，在境內所剩的人都要吃奶油與蜂蜜。","notes":[]},{"n":23,"t":"「從前，凡種一千棵葡萄樹、值銀一千舍客勒的地方，到那時必長荊棘和蒺藜。","notes":[]},{"n":24,"t":"人上那裏去，必帶弓箭，因為遍地滿了荊棘和蒺藜。","notes":[]},{"n":25,"t":"所有用鋤刨挖的山地，你因怕荊棘和蒺藜，不敢上那裏去；只可成了放牛之處，為羊踐踏之地。」","notes":[]}]},"8":{"heading":"用以賽亞的兒子作為記號","verses":[{"n":1,"t":"耶和華對我說：「你取一個大牌，拿人所用的筆，寫上『瑪黑珥‧沙拉勒‧哈施‧罷斯』。","notes":["或譯：人常用的字","就是擄掠速臨、搶奪快到的意思"]},{"n":2,"t":"我要用誠實的見證人，祭司烏利亞和耶比利家的兒子撒迦利亞記錄這事。」","notes":[]},{"n":3,"t":"我－以賽亞與妻子同室；她懷孕生子，耶和華就對我說：「給他起名叫瑪黑珥‧沙拉勒‧哈施‧罷斯；","notes":["原文是女先知"]},{"n":4,"t":"因為在這小孩子不曉得叫父叫母之先，大馬士革的財寶和撒馬利亞的擄物必在亞述王面前搬了去。」","notes":[]},{"n":5,"t":"耶和華又曉諭我說：","notes":[],"heads":["亞述王快來了"]},{"n":6,"t":"「這百姓既厭棄西羅亞緩流的水，喜悅利汛和利瑪利的兒子；","notes":[]},{"n":7,"t":"因此，主必使大河翻騰的水猛然沖來，就是亞述王和他所有的威勢，必漫過一切的水道，漲過兩岸；","notes":[]},{"n":8,"t":"必沖入猶大，漲溢氾濫，直到頸項。以馬內利啊，他展開翅膀，遍滿你的地。」","notes":[]},{"n":9,"t":"列國的人民哪，任憑你們喧嚷，終必破壞；遠方的眾人哪，當側耳而聽！任憑你們束起腰來，終必破壞；你們束起腰來，終必破壞。","notes":[]},{"n":10,"t":"任憑你們同謀，終歸無有；任憑你們言定，終不成立；因為神與我們同在。","notes":[]},{"n":11,"t":"耶和華以大能的手，指教我不可行這百姓所行的道，對我這樣說：","notes":[],"heads":["耶和華警告先知"]},{"n":12,"t":"「這百姓說同謀背叛，你們不要說同謀背叛。他們所怕的，你們不要怕，也不要畏懼。","notes":[]},{"n":13,"t":"但要尊萬軍之耶和華為聖，以他為你們所當怕的，所當畏懼的。","notes":[]},{"n":14,"t":"他必作為聖所，卻向以色列兩家作絆腳的石頭，跌人的磐石；向耶路撒冷的居民作為圈套和網羅。","notes":[]},{"n":15,"t":"許多人必在其上絆腳跌倒，而且跌碎，並陷入網羅，被纏住。」","notes":[]},{"n":16,"t":"你要捲起律法書，在我門徒中間封住訓誨。","notes":[],"heads":["不可求問死人"]},{"n":17,"t":"我要等候那掩面不顧雅各家的耶和華；我也要仰望他。","notes":[]},{"n":18,"t":"看哪，我與耶和華所給我的兒女，就是從住在錫安山萬軍之耶和華來的，在以色列中作為預兆和奇蹟。","notes":[]},{"n":19,"t":"有人對你們說：「當求問那些交鬼的和行巫術的，就是聲音綿蠻，言語微細的。」你們便回答說：「百姓不當求問自己的神嗎？豈可為活人求問死人呢？」","notes":[]},{"n":20,"t":"人當以訓誨和法度為標準；他們所說的，若不與此相符，必不得見晨光。","notes":[]},{"n":21,"t":"他們必經過這地，受艱難，受飢餓；飢餓的時候，心中焦躁，咒罵自己的君王和自己的神。","notes":[],"heads":["遭難的時候"]},{"n":22,"t":"仰觀上天，俯察下地，不料，盡是艱難、黑暗，和幽暗的痛苦。他們必被趕入烏黑的黑暗中去。","notes":[]}]},"9":{"heading":"未來的君王","verses":[{"n":1,"t":"但那受過痛苦的必不再見幽暗。從前神使西布倫地和拿弗他利地被藐視，末後卻使這沿海的路，約旦河外，外邦人的加利利地得著榮耀。","notes":[]},{"n":2,"t":"在黑暗中行走的百姓看見了大光；住在死蔭之地的人有光照耀他們。","notes":[]},{"n":3,"t":"你使這國民繁多，加增他們的喜樂；他們在你面前歡喜，好像收割的歡喜，像人分擄物那樣的快樂。","notes":[]},{"n":4,"t":"因為他們所負的重軛和肩頭上的杖，並欺壓他們人的棍，你都已經折斷，好像在米甸的日子一樣。","notes":[]},{"n":5,"t":"戰士在亂殺之間所穿戴的盔甲，並那滾在血中的衣服，都必作為可燒的，當作火柴。","notes":[]},{"n":6,"t":"因有一嬰孩為我們而生；有一子賜給我們。政權必擔在他的肩頭上；他名稱為「奇妙策士、全能的神、永在的父、和平的君」。","notes":[]},{"n":7,"t":"他的政權與平安必加增無窮。他必在大衛的寶座上治理他的國，以公平公義使國堅定穩固，從今直到永遠。萬軍之耶和華的熱心必成就這事。","notes":[]},{"n":8,"t":"主使一言入於雅各家，落於以色列家。","notes":[],"heads":["耶和華要懲罰以色列"]},{"n":9,"t":"這眾百姓，就是以法蓮和撒馬利亞的居民，都要知道；他們憑驕傲自大的心說：","notes":[]},{"n":10,"t":"磚牆塌了，我們卻要鑿石頭建築；桑樹砍了，我們卻要換香柏樹。","notes":[]},{"n":11,"t":"因此，耶和華要高舉利汛的敵人來攻擊以色列，並要激動以色列的仇敵。","notes":[]},{"n":12,"t":"東有亞蘭人，西有非利士人；他們張口要吞吃以色列。雖然如此，耶和華的怒氣還未轉消；他的手仍伸不縮。","notes":[]},{"n":13,"t":"這百姓還沒有歸向擊打他們的主，也沒有尋求萬軍之耶和華。","notes":[]},{"n":14,"t":"因此，耶和華一日之間必從以色列中剪除頭與尾，棕枝與蘆葦－","notes":[]},{"n":15,"t":"長老和尊貴人就是頭，以謊言教人的先知就是尾。","notes":[]},{"n":16,"t":"因為，引導這百姓的使他們走錯了路；被引導的都必敗亡。","notes":[]},{"n":17,"t":"所以，主必不喜悅他們的少年人，也不憐恤他們的孤兒寡婦；因為，各人是褻瀆的，是行惡的，並且各人的口都說愚妄的話。雖然如此，耶和華的怒氣還未轉消；他的手仍伸不縮。","notes":[]},{"n":18,"t":"邪惡像火焚燒，燒滅荊棘和蒺藜，在稠密的樹林中著起來，就成為煙柱，旋轉上騰。","notes":[]},{"n":19,"t":"因萬軍之耶和華的烈怒，地都燒遍；百姓成為火柴；無人憐愛弟兄。","notes":[]},{"n":20,"t":"有人右邊搶奪，仍受飢餓，左邊吞吃，仍不飽足；各人吃自己膀臂上的肉。","notes":[]},{"n":21,"t":"瑪拿西吞吃以法蓮；以法蓮吞吃瑪拿西，又一同攻擊猶大。雖然如此，耶和華的怒氣還未轉消；他的手仍伸不縮。","notes":["或譯：攻擊；下同"]}]},"10":{"heading":"神用亞述王為工具","verses":[{"n":1,"t":"禍哉！那些設立不義之律例的和記錄奸詐之判語的，","notes":[]},{"n":2,"t":"為要屈枉窮乏人，奪去我民中困苦人的理，以寡婦當作擄物，以孤兒當作掠物。","notes":[]},{"n":3,"t":"到降罰的日子，有災禍從遠方臨到，那時，你們怎樣行呢？你們向誰逃奔求救呢？你們的榮耀存留何處呢？","notes":["或譯：財寶"]},{"n":4,"t":"他們只得屈身在被擄的人以下，仆倒在被殺的人以下。雖然如此，耶和華的怒氣還未轉消；他的手仍伸不縮。","notes":[]},{"n":5,"t":"亞述是我怒氣的棍，手中拿我惱恨的杖。","notes":[]},{"n":6,"t":"我要打發他攻擊褻瀆的國民，吩咐他攻擊我所惱怒的百姓，搶財為擄物，奪貨為掠物，將他們踐踏，像街上的泥土一樣。","notes":[]},{"n":7,"t":"然而，他不是這樣的意思；他心也不這樣打算。他心裏倒想毀滅，剪除不少的國。","notes":[]},{"n":8,"t":"他說：我的臣僕豈不都是王嗎？","notes":[]},{"n":9,"t":"迦勒挪豈不像迦基米施嗎？哈馬豈不像亞珥拔嗎？撒馬利亞豈不像大馬士革嗎？","notes":[]},{"n":10,"t":"我手已經搆到有偶像的國；這些國雕刻的偶像過於耶路撒冷和撒馬利亞的偶像。","notes":[]},{"n":11,"t":"我怎樣待撒馬利亞和其中的偶像，豈不照樣待耶路撒冷和其中的偶像嗎？","notes":[]},{"n":12,"t":"主在錫安山和耶路撒冷成就他一切工作的時候，主說：「我必罰亞述王自大的心和他高傲眼目的榮耀。」","notes":[]},{"n":13,"t":"因為他說：我所成就的事是靠我手的能力和我的智慧，我本有聰明。我挪移列國的地界，搶奪他們所積蓄的財寶；並且我像勇士，使坐寶座的降為卑。","notes":[]},{"n":14,"t":"我的手搆到列國的財寶，好像人搆到鳥窩；我也得了全地，好像人拾起所棄的雀蛋。沒有動翅膀的；沒有張嘴的，也沒有鳴叫的。","notes":[]},{"n":15,"t":"斧豈可向用斧砍木的自誇呢？鋸豈可向用鋸的自大呢？好比棍掄起那舉棍的，好比杖舉起那非木的人。","notes":[]},{"n":16,"t":"因此，主－萬軍之耶和華必使亞述王的肥壯人變為瘦弱，在他的榮華之下必有火著起，如同焚燒一樣。","notes":[]},{"n":17,"t":"以色列的光必如火；他的聖者必如火焰。在一日之間，將亞述王的荊棘和蒺藜焚燒淨盡；","notes":[]},{"n":18,"t":"又將他樹林和肥田的榮耀全然燒盡，好像拿軍旗的昏過去一樣。","notes":[]},{"n":19,"t":"他林中剩下的樹必稀少，就是孩子也能寫其數。","notes":[]},{"n":20,"t":"到那日，以色列所剩下的和雅各家所逃脫的，不再倚靠那擊打他們的，卻要誠實倚靠耶和華－以色列的聖者。","notes":[],"heads":["殘存之民歸回"]},{"n":21,"t":"所剩下的，就是雅各家所剩下的，必歸回全能的神。","notes":[]},{"n":22,"t":"以色列啊，你的百姓雖多如海沙，惟有剩下的歸回。原來滅絕的事已定，必有公義施行，如水漲溢。","notes":[]},{"n":23,"t":"因為主－萬軍之耶和華在全地之中必成就所定規的結局。","notes":[]},{"n":24,"t":"所以，主－萬軍之耶和華如此說：「住錫安我的百姓啊，亞述王雖然用棍擊打你，又照埃及的樣子舉杖攻擊你，你卻不要怕他。","notes":[],"heads":["耶和華要懲罰亞述"]},{"n":25,"t":"因為還有一點點時候，向你們發的忿恨就要完畢，我的怒氣要向他發作，使他滅亡。","notes":[]},{"n":26,"t":"萬軍之耶和華要興起鞭來攻擊他，好像在俄立磐石那裏殺戮米甸人一樣。耶和華的杖要向海伸出，把杖舉起，像在埃及一樣。","notes":[]},{"n":27,"t":"到那日，亞述王的重擔必離開你的肩頭；他的軛必離開你的頸項；那軛也必因肥壯的緣故撐斷。」","notes":["或譯：因膏油的緣故毀壞"]},{"n":28,"t":"亞述王來到亞葉，經過米磯崙，在密抹安放輜重。","notes":[],"heads":["侵略者進攻"]},{"n":29,"t":"他們過了隘口，在迦巴住宿。拉瑪人戰兢；掃羅的基比亞人逃跑。","notes":[]},{"n":30,"t":"迦琳的居民哪，要高聲呼喊！萊煞人哪，須聽！哀哉！困苦的亞拿突啊。","notes":["原文是女子"]},{"n":31,"t":"瑪得米那人躲避；基柄的居民逃遁。","notes":[]},{"n":32,"t":"當那日，亞述王要在挪伯歇兵，向錫安女子的山－就是耶路撒冷的山－掄手攻他。","notes":[]},{"n":33,"t":"看哪，主－萬軍之耶和華以驚嚇削去樹枝；長高的必被砍下，高大的必被伐倒。","notes":[]},{"n":34,"t":"稠密的樹林，他要用鐵器砍下；黎巴嫩的樹木必被大能者伐倒。","notes":[]}]},"11":{"heading":"和平的國度","verses":[{"n":1,"t":"從耶西的本必發一條；從他根生的枝子必結果實。","notes":["原文是墩"]},{"n":2,"t":"耶和華的靈必住在他身上，就是使他有智慧和聰明的靈，謀略和能力的靈，知識和敬畏耶和華的靈。","notes":[]},{"n":3,"t":"他必以敬畏耶和華為樂；行審判不憑眼見，斷是非也不憑耳聞；","notes":[]},{"n":4,"t":"卻要以公義審判貧窮人，以正直判斷世上的謙卑人，以口中的杖擊打世界，以嘴裏的氣殺戮惡人。","notes":[]},{"n":5,"t":"公義必當他的腰帶；信實必當他脅下的帶子。","notes":[]},{"n":6,"t":"豺狼必與綿羊羔同居，豹子與山羊羔同臥；少壯獅子與牛犢並肥畜同群；小孩子要牽引牠們。","notes":[]},{"n":7,"t":"牛必與熊同食；牛犢必與小熊同臥；獅子必吃草，與牛一樣。","notes":[]},{"n":8,"t":"吃奶的孩子必玩耍在虺蛇的洞口；斷奶的嬰兒必按手在毒蛇的穴上。","notes":[]},{"n":9,"t":"在我聖山的遍處，這一切都不傷人，不害物；因為認識耶和華的知識要充滿遍地，好像水充滿洋海一般。","notes":[]},{"n":10,"t":"到那日，耶西的根立作萬民的大旗；外邦人必尋求他，他安息之所大有榮耀。","notes":[],"heads":["流亡的人回鄉"]},{"n":11,"t":"當那日，主必二次伸手救回自己百姓中所餘剩的，就是在亞述、埃及、巴忒羅、古實、以攔、示拿、哈馬，並眾海島所剩下的。","notes":[]},{"n":12,"t":"他必向列國豎立大旗，招回以色列被趕散的人，又從地的四方聚集分散的猶大人。","notes":[]},{"n":13,"t":"以法蓮的嫉妒就必消散；擾害猶大的必被剪除。以法蓮必不嫉妒猶大，猶大也不擾害以法蓮。","notes":[]},{"n":14,"t":"他們要向西飛，撲在非利士人的肩頭上，一同擄掠東方人，伸手按住以東和摩押；亞捫人也必順服他們。","notes":["肩頭上：或譯西界"]},{"n":15,"t":"耶和華必使埃及海汊枯乾，掄手用暴熱的風使大河分為七條，令人過去不致濕腳。","notes":[]},{"n":16,"t":"為主餘剩的百姓，就是從亞述剩下回來的，必有一條大道，如當日以色列從埃及地上來一樣。","notes":[]}]},"12":{"heading":"感恩的詩歌","verses":[{"n":1,"t":"到那日，你必說：耶和華啊，我要稱謝你！因為你雖然向我發怒，你的怒氣卻已轉消；你又安慰了我。","notes":[]},{"n":2,"t":"看哪！神是我的拯救；我要倚靠他，並不懼怕。因為主耶和華是我的力量，是我的詩歌，他也成了我的拯救。","notes":[]},{"n":3,"t":"所以，你們必從救恩的泉源歡然取水。","notes":[]},{"n":4,"t":"在那日，你們要說：當稱謝耶和華，求告他的名；將他所行的傳揚在萬民中，提說他的名已被尊崇。","notes":[]},{"n":5,"t":"你們要向耶和華唱歌，因他所行的甚是美好；但願這事普傳天下。","notes":[]},{"n":6,"t":"錫安的居民哪，當揚聲歡呼，因為在你們中間的以色列聖者乃為至大。","notes":[]}]},"13":{"heading":"神要懲罰巴比倫","verses":[{"n":1,"t":"亞摩斯的兒子以賽亞得默示，論巴比倫。","notes":[]},{"n":2,"t":"應當在淨光的山豎立大旗，向群眾揚聲招手，使他們進入貴冑的門。","notes":[]},{"n":3,"t":"我吩咐我所挑出來的人；我招呼我的勇士－就是那矜誇高傲之輩，為要成就我怒中所定的。","notes":[]},{"n":4,"t":"山間有多人的聲音，好像是大國人民。有許多國的民聚集鬨嚷的聲音；這是萬軍之耶和華點齊軍隊，預備打仗。","notes":[]},{"n":5,"t":"他們從遠方來，從天邊來，就是耶和華並他惱恨的兵器要毀滅這全地。","notes":[]},{"n":6,"t":"你們要哀號，因為耶和華的日子臨近了！這日來到，好像毀滅從全能者來到。","notes":[]},{"n":7,"t":"所以，人手都必軟弱；人心都必消化。","notes":[]},{"n":8,"t":"他們必驚惶悲痛；愁苦必將他們抓住。他們疼痛，好像產難的婦人一樣，彼此驚奇相看，臉如火焰。","notes":[]},{"n":9,"t":"耶和華的日子臨到，必有殘忍、忿恨、烈怒，使這地荒涼，從其中除滅罪人。","notes":[]},{"n":10,"t":"天上的眾星群宿都不發光；日頭一出就變黑暗；月亮也不放光。","notes":[]},{"n":11,"t":"我必因邪惡刑罰世界，因罪孽刑罰惡人，使驕傲人的狂妄止息，制伏強暴人的狂傲。","notes":[]},{"n":12,"t":"我必使人比精金還少，使人比俄斐純金更少。","notes":[]},{"n":13,"t":"我－萬軍之耶和華在忿恨中發烈怒的日子，必使天震動，使地搖撼，離其本位。","notes":[]},{"n":14,"t":"人必像被追趕的鹿，像無人收聚的羊，各歸回本族，各逃到本土。","notes":[]},{"n":15,"t":"凡被仇敵追上的必被刺死；凡被捉住的必被刀殺。","notes":[]},{"n":16,"t":"他們的嬰孩必在他們眼前摔碎；他們的房屋必被搶奪；他們的妻子必被玷污。","notes":[]},{"n":17,"t":"我必激動米底亞人來攻擊他們。米底亞人不注重銀子，也不喜愛金子。","notes":[]},{"n":18,"t":"他們必用弓擊碎少年人，不憐憫婦人所生的，眼也不顧惜孩子。","notes":[]},{"n":19,"t":"巴比倫素來為列國的榮耀，為迦勒底人所矜誇的華美，必像神所傾覆的所多瑪、蛾摩拉一樣。","notes":[]},{"n":20,"t":"其內必永無人煙，世世代代無人居住。阿拉伯人也不在那裏支搭帳棚；牧羊的人也不使羊群臥在那裏。","notes":[]},{"n":21,"t":"只有曠野的走獸臥在那裏；咆哮的獸滿了房屋。鴕鳥住在那裏；野山羊在那裏跳舞。","notes":[]},{"n":22,"t":"豺狼必在它宮中呼號；野狗必在它華美殿內吼叫。巴比倫受罰的時候臨近；它的日子必不長久。","notes":[]}]},"14":{"heading":"從流亡中歸回","verses":[{"n":1,"t":"耶和華要憐恤雅各，必再揀選以色列，將他們安置在本地。寄居的必與他們聯合，緊貼雅各家。","notes":[]},{"n":2,"t":"外邦人必將他們帶回本土；以色列家必在耶和華的地上得外邦人為僕婢，也要擄掠先前擄掠他們的，轄制先前欺壓他們的。","notes":[]},{"n":3,"t":"當耶和華使你脫離愁苦、煩惱，並人勉強你做的苦工，得享安息的日子，","notes":[],"heads":["巴比倫王下到陰間"]},{"n":4,"t":"你必題這詩歌論巴比倫王說：欺壓人的何竟熄滅？強暴的何竟止息？","notes":[]},{"n":5,"t":"耶和華折斷了惡人的杖，轄制人的圭，","notes":[]},{"n":6,"t":"就是在忿怒中連連攻擊眾民的，在怒氣中轄制列國，行逼迫無人阻止的。","notes":[]},{"n":7,"t":"現在全地得安息，享平靜；人皆發聲歡呼。","notes":[]},{"n":8,"t":"松樹和黎巴嫩的香柏樹都因你歡樂，說：自從你仆倒，再無人上來砍伐我們。","notes":[]},{"n":9,"t":"你下到陰間，陰間就因你震動來迎接你，又因你驚動在世曾為首領的陰魂，並使那曾為列國君王的，都離位站起。","notes":[]},{"n":10,"t":"他們都要發言對你說：你也變為軟弱像我們一樣嗎？你也成了我們的樣子嗎？","notes":[]},{"n":11,"t":"你的威勢和你琴瑟的聲音都下到陰間。你下鋪的是蟲，上蓋的是蛆。","notes":[]},{"n":12,"t":"明亮之星，早晨之子啊，你何竟從天墜落？你這攻敗列國的何竟被砍倒在地上？","notes":[]},{"n":13,"t":"你心裏曾說：我要升到天上；我要高舉我的寶座在神眾星以上；我要坐在聚會的山上，在北方的極處。","notes":[]},{"n":14,"t":"我要升到高雲之上；我要與至上者同等。","notes":[]},{"n":15,"t":"然而，你必墜落陰間，到坑中極深之處。","notes":[]},{"n":16,"t":"凡看見你的都要定睛看你，留意看你，說：使大地戰抖，使列國震動，","notes":[]},{"n":17,"t":"使世界如同荒野，使城邑傾覆，不釋放被擄的人歸家，是這個人嗎？","notes":[]},{"n":18,"t":"列國的君王俱各在自己陰宅的榮耀中安睡。","notes":[]},{"n":19,"t":"惟獨你被拋棄，不得入你的墳墓，好像可憎的枝子，以被殺的人為衣，就是被刀刺透，墜落坑中石頭那裏的；你又像被踐踏的屍首一樣。","notes":[]},{"n":20,"t":"你不得與君王同葬；因為你敗壞你的國，殺戮你的民。惡人後裔的名，必永不提說。","notes":[]},{"n":21,"t":"先人既有罪孽，就要預備殺戮他的子孫，免得他們興起來，得了遍地，在世上修滿城邑。","notes":[]},{"n":22,"t":"萬軍之耶和華說：我必興起攻擊他們，將巴比倫的名號和所餘剩的人，連子帶孫一併剪除。這是耶和華說的。","notes":[],"heads":["神要毀滅巴比倫"]},{"n":23,"t":"我必使巴比倫為箭豬所得，又變為水池；我要用滅亡的掃帚掃淨它。這是萬軍之耶和華說的。","notes":[]},{"n":24,"t":"萬軍之耶和華起誓說：我怎樣思想，必照樣成就；我怎樣定意，必照樣成立，","notes":[],"heads":["神要毀滅亞述"]},{"n":25,"t":"就是在我地上打折亞述人，在我山上將他踐踏。他加的軛必離開以色列人；他加的重擔必離開他們的肩頭。","notes":[]},{"n":26,"t":"這是向全地所定的旨意；這是向萬國所伸出的手。","notes":[]},{"n":27,"t":"萬軍之耶和華既然定意，誰能廢棄呢？他的手已經伸出，誰能轉回呢？","notes":[]},{"n":28,"t":"亞哈斯王崩的那年，就有以下的默示：","notes":[],"heads":["神要毀滅非利士"]},{"n":29,"t":"非利士全地啊，不要因擊打你的杖折斷就喜樂。因為從蛇的根必生出毒蛇；牠所生的是火焰的飛龍。","notes":[]},{"n":30,"t":"貧寒人的長子必有所食；窮乏人必安然躺臥。我必以饑荒治死你的根；你所餘剩的人必被殺戮。","notes":[]},{"n":31,"t":"門哪，應當哀號！城啊，應當呼喊！非利士全地啊，你都消化了！因為有煙從北方出來，他行伍中並無亂隊的。","notes":[]},{"n":32,"t":"可怎樣回答外邦的使者呢？必說：耶和華建立了錫安；他百姓中的困苦人必投奔在其中。","notes":["或指非利士"]}]},"15":{"heading":"神要毀滅摩押","verses":[{"n":1,"t":"論摩押的默示：一夜之間，摩押的亞珥變為荒廢，歸於無有；一夜之間，摩押的基珥變為荒廢，歸於無有。","notes":[]},{"n":2,"t":"他們上巴益，又往底本，到高處去哭泣。摩押人因尼波和米底巴哀號，各人頭上光禿，鬍鬚剃淨。","notes":[]},{"n":3,"t":"他們在街市上都腰束麻布，在房頂上和寬闊處俱各哀號，眼淚汪汪。","notes":[]},{"n":4,"t":"希實本和以利亞利悲哀的聲音達到雅雜，所以摩押帶兵器的高聲喊嚷，人心戰兢。","notes":[]},{"n":5,"t":"我心為摩押悲哀；他的貴冑逃到瑣珥，到伊基拉‧施利施亞。他們上魯希坡，隨走隨哭；在何羅念的路上，因毀滅舉起哀聲。","notes":["或譯：逃民"]},{"n":6,"t":"因為寧林的水成為乾涸，青草枯乾，嫩草滅沒，青綠之物，一無所有。","notes":[]},{"n":7,"t":"因此，摩押人所得的財物和所積蓄的都要運過柳樹河。","notes":[]},{"n":8,"t":"哀聲遍聞摩押的四境；哀號的聲音達到以基蓮；哀號的聲音達到比珥‧以琳。","notes":[]},{"n":9,"t":"底們的水充滿了血；我還要加增底們的災難，叫獅子來追上摩押逃脫的民和那地上所餘剩的人。","notes":[]}]},"16":{"heading":"摩押的難民逃到猶大","verses":[{"n":1,"t":"你們當將羊羔奉給那地掌權的，從西拉往曠野，送到錫安城的山。","notes":["原文是女子"]},{"n":2,"t":"摩押的居民在亞嫩渡口，必像遊飛的鳥，如拆窩的雛。","notes":["原文是女子"]},{"n":3,"t":"求你獻謀略，行公平，使你的影子在午間如黑夜，隱藏被趕散的人，不可顯露逃民。","notes":[]},{"n":4,"t":"求你容我這被趕散的人和你同居。至於摩押，求你作他的隱密處，脫離滅命者的面。勒索人的歸於無有，毀滅的事止息了，欺壓人的從國中除滅了，","notes":[]},{"n":5,"t":"必有寶座因慈愛堅立；必有一位誠誠實實坐在其上，在大衛帳幕中施行審判，尋求公平，速行公義。","notes":[]},{"n":6,"t":"我們聽說摩押人驕傲，是極其驕傲；聽說他狂妄、驕傲、忿怒；他誇大的話是虛空的。","notes":[]},{"n":7,"t":"因此，摩押人必為摩押哀號；人人都要哀號。你們摩押人要為吉珥‧哈列設的葡萄餅哀歎，極其憂傷。","notes":[]},{"n":8,"t":"因為希實本的田地和西比瑪的葡萄樹都衰殘了。列國的君主折斷其上美好的枝子；這枝子長到雅謝延到曠野，嫩枝向外探出，直探過鹽海。","notes":[]},{"n":9,"t":"因此，我要為西比瑪的葡萄樹哀哭，與雅謝人哀哭一樣。希實本、以利亞利啊，我要以眼淚澆灌你；因為有交戰吶喊的聲音臨到你夏天的果子，並你收割的莊稼。","notes":[]},{"n":10,"t":"從肥美的田中奪去了歡喜快樂；在葡萄園裏必無歌唱，也無歡呼的聲音。踹酒的在酒醡中不得踹出酒來；我使他歡呼的聲音止息。","notes":[]},{"n":11,"t":"因此，我心腹為摩押哀鳴如琴；我心腸為吉珥‧哈列設也是如此。","notes":[]},{"n":12,"t":"摩押人朝見的時候，在高處疲乏，又到他聖所祈禱，也不蒙應允。","notes":[]},{"n":13,"t":"這是耶和華從前論摩押的話。","notes":[]},{"n":14,"t":"但現在耶和華說：「三年之內，照雇工的年數，摩押的榮耀與他的群眾必被藐視，餘剩的人甚少無幾。」","notes":[]}]},"17":{"heading":"神要刑罰亞蘭和以色列","verses":[{"n":1,"t":"論大馬士革的默示：看哪，大馬士革已被廢棄，不再為城，必變作亂堆。","notes":[]},{"n":2,"t":"亞羅珥的城邑已被撇棄，必成為牧羊之處；羊在那裏躺臥，無人驚嚇。","notes":[]},{"n":3,"t":"以法蓮不再有保障；大馬士革不再有國權；亞蘭所剩下的必像以色列人的榮耀消滅一樣。這是萬軍之耶和華說的。","notes":[]},{"n":4,"t":"到那日，雅各的榮耀必至枵薄；他肥胖的身體必漸瘦弱。","notes":[]},{"n":5,"t":"就必像收割的人收斂禾稼，用手割取穗子，又像人在利乏音谷拾取遺落的穗子。","notes":[]},{"n":6,"t":"其間所剩下的不多，好像人打橄欖樹－在儘上的枝梢上只剩兩三個果子；在多果樹的旁枝上只剩四五個果子。這是耶和華－以色列的神說的。","notes":[]},{"n":7,"t":"當那日，人必仰望造他們的主，眼目重看以色列的聖者。","notes":[]},{"n":8,"t":"他們必不仰望祭壇，就是自己手所築的，也不重看自己指頭所做的，無論是木偶是日像。","notes":[]},{"n":9,"t":"在那日，他們的堅固城必像樹林中和山頂上所撇棄的地方，就是從前在以色列人面前被人撇棄的。這樣，地就荒涼了。","notes":[]},{"n":10,"t":"因你忘記救你的神，不記念你能力的磐石；所以，你栽上佳美的樹秧子，插上異樣的栽子。","notes":[]},{"n":11,"t":"栽種的日子，你周圍圈上籬笆，又到早晨使你所種的開花；但在愁苦極其傷痛的日子，所收割的都飛去了。","notes":[]},{"n":12,"t":"唉！多民鬨嚷，好像海浪匉訇；列邦奔騰，好像猛水滔滔；","notes":[],"heads":["敵國都被擊敗"]},{"n":13,"t":"列邦奔騰，好像多水滔滔；但神斥責他們，他們就遠遠逃避，又被追趕，如同山上的風前糠，又如暴風前的旋風土。","notes":[]},{"n":14,"t":"到晚上有驚嚇，未到早晨他們就沒有了。這是擄掠我們之人所得的分，是搶奪我們之人的報應。","notes":[]}]},"18":{"heading":"神要責罰古實","verses":[{"n":1,"t":"唉！古實河外翅膀刷刷響聲之地，","notes":[]},{"n":2,"t":"差遣使者在水面上，坐蒲草船過海。先知說：你們快行的使者，要到高大光滑的民那裏去。自從開國以來，那民極其可畏，是分地界踐踏人的；他們的地有江河分開。","notes":[]},{"n":3,"t":"世上一切的居民和地上所住的人哪，山上豎立大旗的時候你們要看；吹角的時候你們要聽。","notes":[]},{"n":4,"t":"耶和華對我這樣說：我要安靜，在我的居所觀看，如同日光中的清熱，又如露水的雲霧在收割的熱天。","notes":[]},{"n":5,"t":"收割之先，花開已謝，花也成了將熟的葡萄；他必用鐮刀削去嫩枝，又砍掉蔓延的枝條，","notes":[]},{"n":6,"t":"都要撇給山間的鷙鳥和地上的野獸。夏天，鷙鳥要宿在其上；冬天，野獸都臥在其中。","notes":[]},{"n":7,"t":"到那時，這高大光滑的民，就是從開國以來極其可畏、分地界踐踏人的，他們的地有江河分開；他們必將禮物奉給萬軍之耶和華，就是奉到錫安山－耶和華安置他名的地方。","notes":[]}]},"19":{"heading":"神要懲罰埃及","verses":[{"n":1,"t":"論埃及的默示：看哪，耶和華乘駕快雲，臨到埃及。埃及的偶像在他面前戰兢；埃及人的心在裏面消化。","notes":[]},{"n":2,"t":"我必激動埃及人攻擊埃及人－弟兄攻擊弟兄，鄰舍攻擊鄰舍；這城攻擊那城，這國攻擊那國。","notes":[]},{"n":3,"t":"埃及人的心神必在裏面耗盡；我必敗壞他們的謀略。他們必求問偶像和念咒的、交鬼的、行巫術的。","notes":[]},{"n":4,"t":"我必將埃及人交在殘忍主的手中；強暴王必轄制他們。這是主－萬軍之耶和華說的。","notes":[]},{"n":5,"t":"海中的水必絕盡，河也消沒乾涸。","notes":[]},{"n":6,"t":"江河要變臭；埃及的河水都必減少枯乾。葦子和蘆荻都必衰殘；","notes":[]},{"n":7,"t":"靠尼羅河旁的草田，並沿尼羅河所種的田，都必枯乾。莊稼被風吹去，歸於無有。","notes":[]},{"n":8,"t":"打魚的必哀哭。在尼羅河一切釣魚的必悲傷；在水上撒網的必都衰弱。","notes":[]},{"n":9,"t":"用梳好的麻造物的和織白布的都必羞愧；","notes":[]},{"n":10,"t":"國柱必被打碎，所有傭工的，心必愁煩。","notes":[]},{"n":11,"t":"瑣安的首領極其愚昧；法老大有智慧的謀士，所籌劃的成為愚謀。你們怎敢對法老說：我是智慧人的子孫，我是古王的後裔？","notes":[]},{"n":12,"t":"你的智慧人在哪裏呢？萬軍之耶和華向埃及所定的旨意，他們可以知道，可以告訴你吧！","notes":[]},{"n":13,"t":"瑣安的首領都變為愚昧；挪弗的首領都受了迷惑。當埃及支派房角石的，使埃及人走錯了路。","notes":[]},{"n":14,"t":"耶和華使乖謬的靈攙入埃及中間；首領使埃及一切所做的都有差錯，好像醉酒之人嘔吐的時候東倒西歪一樣。","notes":[]},{"n":15,"t":"埃及中，無論是頭與尾，棕枝與蘆葦，所做之工都不成就。","notes":[]},{"n":16,"t":"到那日，埃及人必像婦人一樣，他們必因萬軍之耶和華在埃及以上所掄的手，戰兢懼怕。","notes":[]},{"n":17,"t":"猶大地必使埃及驚恐，向誰提起猶大地，誰就懼怕。這是因萬軍之耶和華向埃及所定的旨意。","notes":[]},{"n":18,"t":"當那日，埃及地必有五城的人說迦南的方言，又指著萬軍之耶和華起誓。有一城必稱為「滅亡城」。","notes":[]},{"n":19,"t":"當那日，在埃及地中必有為耶和華築的一座壇；在埃及的邊界上必有為耶和華立的一根柱。","notes":[]},{"n":20,"t":"這都要在埃及地為萬軍之耶和華作記號和證據。埃及人因為受人的欺壓哀求耶和華，他就差遣一位救主作護衛者，拯救他們。","notes":[]},{"n":21,"t":"耶和華必被埃及人所認識。在那日，埃及人必認識耶和華，也要獻祭物和供物敬拜他，並向耶和華許願還願。","notes":[]},{"n":22,"t":"耶和華必擊打埃及，又擊打又醫治，埃及人就歸向耶和華。他必應允他們的禱告，醫治他們。","notes":[]},{"n":23,"t":"當那日，必有從埃及通亞述去的大道。亞述人要進入埃及，埃及人也進入亞述；埃及人要與亞述人一同敬拜耶和華。","notes":[]},{"n":24,"t":"當那日，以色列必與埃及、亞述三國一律，使地上的人得福；","notes":[]},{"n":25,"t":"因為萬軍之耶和華賜福給他們，說：「埃及－我的百姓，亞述－我手的工作，以色列－我的產業，都有福了！」","notes":[]}]},"20":{"heading":"露身赤腳的先知","verses":[{"n":1,"t":"亞述王撒珥根打發他珥探到亞實突的那年，他珥探就攻打亞實突，將城攻取。","notes":[]},{"n":2,"t":"那時，耶和華曉諭亞摩斯的兒子以賽亞說：「你去解掉你腰間的麻布，脫下你腳上的鞋。」以賽亞就這樣做，露身赤腳行走。","notes":[]},{"n":3,"t":"耶和華說：「我僕人以賽亞怎樣露身赤腳行走三年，作為關乎埃及和古實的預兆奇蹟。","notes":[]},{"n":4,"t":"照樣，亞述王也必擄去埃及人，掠去古實人，無論老少，都露身赤腳，現出下體，使埃及蒙羞。","notes":[]},{"n":5,"t":"以色列人必因所仰望的古實，所誇耀的埃及，驚惶羞愧。","notes":[]},{"n":6,"t":"「那時，這沿海一帶的居民必說：『看哪，我們素所仰望的，就是我們為脫離亞述王逃往求救的，不過是如此！我們怎能逃脫呢？』」","notes":[]}]},"21":{"heading":"巴比倫的覆滅","verses":[{"n":1,"t":"論海旁曠野的默示：有仇敵從曠野，從可怕之地而來，好像南方的旋風，猛然掃過。","notes":[]},{"n":2,"t":"令人悽慘的異象已默示於我。詭詐的行詭詐，毀滅的行毀滅。以攔哪，你要上去！米底亞啊，你要圍困！主說：我使一切歎息止住。","notes":[]},{"n":3,"t":"所以，我滿腰疼痛；痛苦將我抓住，好像產難的婦人一樣。我疼痛甚至不能聽；我驚惶甚至不能看。","notes":[]},{"n":4,"t":"我心慌張，驚恐威嚇我。我所羨慕的黃昏，變為我的戰兢。","notes":[]},{"n":5,"t":"他們擺設筵席，派人守望，又吃又喝。首領啊，你們起來，用油抹盾牌。","notes":[]},{"n":6,"t":"主對我如此說：你去設立守望的，使他將所看見的述說。","notes":[]},{"n":7,"t":"他看見軍隊，就是騎馬的一對一對地來，又看見驢隊，駱駝隊，就要側耳細聽。","notes":[]},{"n":8,"t":"他像獅子吼叫，說：主啊，我白日常站在望樓上，整夜立在我守望所。","notes":[]},{"n":9,"t":"看哪，有一隊軍兵騎著馬，一對一對地來。他就說：巴比倫傾倒了！傾倒了！他一切雕刻的神像都打碎於地。","notes":[]},{"n":10,"t":"我被打的禾稼，我場上的穀啊，我從萬軍之耶和華－以色列的神那裏所聽見的，都告訴你們了。","notes":[]},{"n":11,"t":"論度瑪的默示：有人聲從西珥呼問我說：守望的啊，夜裏如何？守望的啊，夜裏如何？","notes":[],"heads":["論以東的信息"]},{"n":12,"t":"守望的說：早晨將到，黑夜也來。你們若要問就可以問，可以回頭再來。","notes":[]},{"n":13,"t":"論阿拉伯的默示：底但結伴的客旅啊，你們必在阿拉伯的樹林中住宿。","notes":[],"heads":["論阿拉伯的信息"]},{"n":14,"t":"提瑪地的居民拿水來，送給口渴的，拿餅來迎接逃避的。","notes":[]},{"n":15,"t":"因為他們逃避刀劍和出了鞘的刀，並上了弦的弓與刀兵的重災。","notes":[]},{"n":16,"t":"主對我這樣說：「一年之內，照雇工的年數，基達的一切榮耀必歸於無有。","notes":[]},{"n":17,"t":"弓箭手所餘剩的，就是基達人的勇士，必然稀少，因為這是耶和華－以色列的神說的。」","notes":[]}]},"22":{"heading":"論耶路撒冷的信息","verses":[{"n":1,"t":"論異象谷的默示：有甚麼事使你這滿城的人都上房頂呢？","notes":[]},{"n":2,"t":"你這滿處吶喊、大有喧嘩的城，歡樂的邑啊，你中間被殺的並不是被刀殺，也不是因打仗死亡。","notes":[]},{"n":3,"t":"你所有的官長一同逃跑，都為弓箭手所捆綁。你中間一切被找到的都一同被捆綁；他們本是逃往遠方的。","notes":[]},{"n":4,"t":"所以我說：你們轉眼不看我，我要痛哭。不要因我眾民的毀滅，就竭力安慰我。","notes":["原文是民女"]},{"n":5,"t":"因為主－萬軍之耶和華使「異象谷」有潰亂、踐踏、煩擾的日子。城被攻破，哀聲達到山間。","notes":[]},{"n":6,"t":"以攔帶著箭袋，還有坐戰車的和馬兵；吉珥揭開盾牌。","notes":[]},{"n":7,"t":"你嘉美的谷遍滿戰車，也有馬兵在城門前排列。","notes":[]},{"n":8,"t":"他去掉猶大的遮蓋。那日，你就仰望林庫內的軍器。","notes":[]},{"n":9,"t":"你們看見大衛城的破口很多，便聚積下池的水，","notes":[]},{"n":10,"t":"又數點耶路撒冷的房屋，將房屋拆毀，修補城牆，","notes":[]},{"n":11,"t":"又在兩道城牆中間挖一個聚水池可盛舊池的水，卻不仰望做這事的主，也不顧念從古定這事的。","notes":[]},{"n":12,"t":"當那日，主－萬軍之耶和華叫人哭泣哀號，頭上光禿，身披麻布。","notes":[]},{"n":13,"t":"誰知，人倒歡喜快樂，宰牛殺羊，吃肉喝酒，說：我們吃喝吧！因為明天要死了。","notes":[]},{"n":14,"t":"萬軍之耶和華親自默示我說：這罪孽直到你們死，斷不得赦免！這是主－萬軍之耶和華說的。","notes":[]},{"n":15,"t":"主－萬軍之耶和華這樣說：「你去見掌銀庫的，就是家宰舍伯那，對他說：","notes":[],"heads":["對舍伯那的警告"]},{"n":16,"t":"『你在這裏做甚麼呢？有甚麼人竟在這裏鑿墳墓，就是在高處為自己鑿墳墓，在磐石中為自己鑿出安身之所？","notes":[]},{"n":17,"t":"看哪，耶和華必像大有力的人，將你緊緊纏裹，竭力拋去。","notes":[]},{"n":18,"t":"他必將你滾成一團，拋在寬闊之地，好像拋球一樣。你這主人家的羞辱，必在那裏坐你榮耀的車，也必在那裏死亡。","notes":[]},{"n":19,"t":"我必趕逐你離開官職；你必從你的原位撤下。』","notes":[]},{"n":20,"t":"「到那日，我必召我僕人希勒家的兒子以利亞敬來，","notes":[]},{"n":21,"t":"將你的外袍給他穿上，將你的腰帶給他繫緊，將你的政權交在他手中。他必作耶路撒冷居民和猶大家的父。","notes":[]},{"n":22,"t":"我必將大衛家的鑰匙放在他肩頭上。他開，無人能關；他關，無人能開。","notes":[]},{"n":23,"t":"我必將他安穩，像釘子釘在堅固處；他必作為他父家榮耀的寶座。","notes":[]},{"n":24,"t":"他父家所有的榮耀，連兒女帶子孫，都掛在他身上，好像一切小器皿，從杯子到酒瓶掛上一樣。","notes":[]},{"n":25,"t":"萬軍之耶和華說：當那日，釘在堅固處的釘子必壓斜，被砍斷落地；掛在其上的重擔必被剪斷。因為這是耶和華說的。」","notes":[]}]},"23":{"heading":"神要責罰泰爾的海港","verses":[{"n":1,"t":"論泰爾的默示：他施的船隻都要哀號；因為泰爾變為荒場，甚至沒有房屋，沒有可進之路。這消息是從基提地得來的。","notes":[]},{"n":2,"t":"沿海的居民，就是素來靠航海西頓的商家得豐盛的，你們當靜默無言。","notes":[]},{"n":3,"t":"在大水之上，西曷的糧食、尼羅河的莊稼是泰爾的進項；她作列國的大碼頭。","notes":[]},{"n":4,"t":"西頓哪，你當慚愧；因為大海說，就是海中的保障說：我沒有劬勞，也沒有生產，沒有養育男子，也沒有撫養童女。","notes":[]},{"n":5,"t":"這風聲傳到埃及；埃及人為泰爾的風聲極其疼痛。","notes":[]},{"n":6,"t":"泰爾人哪，你們當過到他施去；沿海的居民哪，你們都當哀號。","notes":[]},{"n":7,"t":"這是你們歡樂的城，從上古而有的嗎？其中的居民往遠方寄居。","notes":[]},{"n":8,"t":"泰爾本是賜冠冕的。她的商家是王子；她的買賣人是世上的尊貴人。遭遇如此是誰定的呢？","notes":[]},{"n":9,"t":"是萬軍之耶和華所定的！為要污辱一切高傲的榮耀，使地上一切的尊貴人被藐視。","notes":[]},{"n":10,"t":"他施的民哪，可以流行你的地，好像尼羅河；不再有腰帶拘緊你。","notes":["原文是女"]},{"n":11,"t":"耶和華已經向海伸手，震動列國。至於迦南，他已經吩咐拆毀其中的保障。","notes":[]},{"n":12,"t":"他又說：受欺壓西頓的居民哪，你必不得再歡樂。起來！過到基提去；就是在那裏也不得安歇。（","notes":["原文是處女"]},{"n":13,"t":"看哪，迦勒底人之地向來沒有這民，這國是亞述人為住曠野的人所立的。現在他們建築戍樓，拆毀泰爾的宮殿，使她成為荒涼。）","notes":[]},{"n":14,"t":"他施的船隻都要哀號，因為你們的保障變為荒場。","notes":[]},{"n":15,"t":"到那時，泰爾必被忘記七十年，照著一王的年日。七十年後，泰爾的景況必像妓女所唱的歌：","notes":[]},{"n":16,"t":"你這被忘記的妓女啊，拿琴周流城內，巧彈多唱，使人再想念你。","notes":[]},{"n":17,"t":"七十年後，耶和華必眷顧泰爾，她就仍得利息，與地上的萬國交易。","notes":["原文是雇價；下同","原文是行淫"]},{"n":18,"t":"她的貨財和利息要歸耶和華為聖，必不積攢存留；因為她的貨財必為住在耶和華面前的人所得，使他們吃飽，穿耐久的衣服。","notes":[]}]},"24":{"heading":"耶和華要責罰世界","verses":[{"n":1,"t":"看哪，耶和華使地空虛，變為荒涼；又翻轉大地，將居民分散。","notes":[]},{"n":2,"t":"那時百姓怎樣，祭司也怎樣；僕人怎樣，主人也怎樣；婢女怎樣，主母也怎樣；買物的怎樣，賣物的也怎樣；放債的怎樣，借債的也怎樣；取利的怎樣，出利的也怎樣。","notes":[]},{"n":3,"t":"地必全然空虛，盡都荒涼；因為這話是耶和華說的。","notes":[]},{"n":4,"t":"地上悲哀衰殘，世界敗落衰殘；地上居高位的人也敗落了。","notes":[]},{"n":5,"t":"地被其上的居民污穢；因為他們犯了律法，廢了律例，背了永約。","notes":[]},{"n":6,"t":"所以，地被咒詛吞滅；住在其上的顯為有罪。地上的居民被火焚燒，剩下的人稀少。","notes":[]},{"n":7,"t":"新酒悲哀，葡萄樹衰殘；心中歡樂的俱都歎息。","notes":[]},{"n":8,"t":"擊鼓之樂止息；宴樂人的聲音完畢，彈琴之樂也止息了。","notes":[]},{"n":9,"t":"人必不得飲酒唱歌；喝濃酒的，必以為苦。","notes":[]},{"n":10,"t":"荒涼的城拆毀了；各家關門閉戶，使人都不得進去。","notes":[]},{"n":11,"t":"在街上因酒有悲歎的聲音；一切喜樂變為昏暗；地上的歡樂歸於無有。","notes":[]},{"n":12,"t":"城中只有荒涼；城門拆毀淨盡。","notes":[]},{"n":13,"t":"在地上的萬民中，必像打過的橄欖樹，又像已摘的葡萄所剩無幾。","notes":[]},{"n":14,"t":"這些人要高聲歡呼；他們為耶和華的威嚴，從海那裏揚起聲來。","notes":[]},{"n":15,"t":"因此，你們要在東方榮耀耶和華，在眾海島榮耀耶和華－以色列神的名。","notes":[]},{"n":16,"t":"我們聽見從地極有人歌唱，說：榮耀歸於義人。我卻說：我消滅了！我消滅了，我有禍了！詭詐的行詭詐；詭詐的大行詭詐。","notes":[]},{"n":17,"t":"地上的居民哪，恐懼、陷坑、網羅都臨近你。","notes":[]},{"n":18,"t":"躲避恐懼聲音的必墜入陷坑；從陷坑上來的必被網羅纏住；因為天上的窗戶都開了，地的根基也震動了。","notes":[]},{"n":19,"t":"地全然破壞，盡都崩裂，大大地震動了。","notes":[]},{"n":20,"t":"地要東倒西歪，好像醉酒的人；又搖來搖去，好像吊床。罪過在其上沉重，必然塌陷，不能復起。","notes":[]},{"n":21,"t":"到那日，耶和華在高處必懲罰高處的眾軍，在地上必懲罰地上的列王。","notes":[]},{"n":22,"t":"他們必被聚集，像囚犯被聚在牢獄中，並要囚在監牢裏，多日之後便被討罪。","notes":["或譯：眷顧"]},{"n":23,"t":"那時，月亮要蒙羞，日頭要慚愧；因為萬軍之耶和華必在錫安山，在耶路撒冷作王；在敬畏他的長老面前，必有榮耀。","notes":[]}]},"25":{"heading":"一首讚美詩","verses":[{"n":1,"t":"耶和華啊，你是我的神；我要尊崇你，我要稱讚你的名。因為你以忠信誠實行過奇妙的事，成就你古時所定的。","notes":[]},{"n":2,"t":"你使城變為亂堆，使堅固城變為荒場，使外邦人宮殿的城不再為城，永遠不再建造。","notes":[]},{"n":3,"t":"所以，剛強的民必榮耀你；強暴之國的城必敬畏你。","notes":[]},{"n":4,"t":"因為當強暴人催逼人的時候，如同暴風直吹牆壁，你就作貧窮人的保障，作困乏人急難中的保障，作躲暴風之處，作避炎熱的陰涼。","notes":[]},{"n":5,"t":"你要壓制外邦人的喧嘩，好像乾燥地的熱氣下落；禁止強暴人的凱歌，好像熱氣被雲影消化。","notes":[]},{"n":6,"t":"在這山上，萬軍之耶和華必為萬民用肥甘設擺筵席，用陳酒和滿髓的肥甘，並澄清的陳酒，設擺筵席。","notes":[],"heads":["神為萬民設擺筵席"]},{"n":7,"t":"他又必在這山上除滅遮蓋萬民之物和遮蔽萬國蒙臉的帕子。","notes":[]},{"n":8,"t":"他已經吞滅死亡直到永遠。主耶和華必擦去各人臉上的眼淚，又除掉普天下他百姓的羞辱，因為這是耶和華說的。","notes":[]},{"n":9,"t":"到那日，人必說：「看哪，這是我們的神；我們素來等候他，他必拯救我們。這是耶和華，我們素來等候他，我們必因他的救恩歡喜快樂。」","notes":[]},{"n":10,"t":"耶和華的手必按在這山上；摩押人在所居之地必被踐踏，好像乾草被踐踏在糞池的水中。","notes":[],"heads":["神要刑罰摩押"]},{"n":11,"t":"他必在其中伸開手，好像洑水的伸開手洑水一樣；但耶和華必使他的驕傲和他手所行的詭計一併敗落。","notes":[]},{"n":12,"t":"耶和華使你城上的堅固高臺傾倒，拆平，直到塵埃。","notes":[]}]},"26":{"heading":"神使他的百姓得勝","verses":[{"n":1,"t":"當那日，在猶大地人必唱這歌說：我們有堅固的城。耶和華要將救恩定為城牆，為外郭。","notes":[]},{"n":2,"t":"敞開城門，使守信的義民得以進入。","notes":[]},{"n":3,"t":"堅心倚賴你的，你必保守他十分平安，因為他倚靠你。","notes":[]},{"n":4,"t":"你們當倚靠耶和華直到永遠，因為耶和華是永久的磐石。","notes":[]},{"n":5,"t":"他使住高處的與高城一併敗落，將城拆毀，拆平，直到塵埃，","notes":[]},{"n":6,"t":"要被腳踐踏，就是被困苦人的腳和窮乏人的腳踐踏。","notes":[]},{"n":7,"t":"義人的道是正直的；你為正直的主，必修平義人的路。","notes":[]},{"n":8,"t":"耶和華啊，我們在你行審判的路上等候你；我們心裏所羨慕的是你的名，就是你那可記念的名。","notes":[]},{"n":9,"t":"夜間，我心中羨慕你；我裏面的靈切切尋求你。因為你在世上行審判的時候，地上的居民就學習公義。","notes":[]},{"n":10,"t":"以恩惠待惡人，他仍不學習公義；在正直的地上，他必行事不義，也不注意耶和華的威嚴。","notes":[]},{"n":11,"t":"耶和華啊，你的手高舉，他們仍然不看；卻要看你為百姓發的熱心，因而抱愧，並且有火燒滅你的敵人。","notes":[]},{"n":12,"t":"耶和華啊，你必派定我們得平安，因為我們所做的事都是你給我們成就的。","notes":[]},{"n":13,"t":"耶和華－我們的神啊，在你以外曾有別的主管轄我們，但我們專要倚靠你，提你的名。","notes":[]},{"n":14,"t":"他們死了，必不能再活；他們去世，必不能再起；因為你刑罰他們，毀滅他們，他們的名號就全然消滅。","notes":[]},{"n":15,"t":"耶和華啊，你增添國民，你增添國民；你得了榮耀，又擴張地的四境。","notes":[]},{"n":16,"t":"耶和華啊，他們在急難中尋求你；你的懲罰臨到他們身上，他們就傾心吐膽禱告你。","notes":[]},{"n":17,"t":"婦人懷孕，臨產疼痛，在痛苦之中喊叫；耶和華啊，我們在你面前也是如此。","notes":[]},{"n":18,"t":"我們也曾懷孕疼痛，所產的竟像風一樣。我們在地上未曾行甚麼拯救的事；世上的居民也未曾敗落。","notes":[]},{"n":19,"t":"死人要復活，屍首要興起。睡在塵埃的啊，要醒起歌唱！因你的甘露好像菜蔬上的甘露，地也要交出死人來。","notes":["原文是你的死人","原文是我的屍首"]},{"n":20,"t":"我的百姓啊，你們要來進入內室，關上門，隱藏片時，等到忿怒過去。","notes":[],"heads":["審判和復興"]},{"n":21,"t":"因為耶和華從他的居所出來，要刑罰地上居民的罪孽。地也必露出其中的血，不再掩蓋被殺的人。","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"到那日，耶和華必用他剛硬有力的大刀刑罰鱷魚－就是那快行的蛇，刑罰鱷魚－就是那曲行的蛇，並殺海中的大魚。","notes":[]},{"n":2,"t":"當那日，有出酒的葡萄園，你們要指這園唱歌說：","notes":[]},{"n":3,"t":"我－耶和華是看守葡萄園的；我必時刻澆灌，晝夜看守，免得有人損害。","notes":[]},{"n":4,"t":"我心中不存忿怒。惟願荊棘蒺藜與我交戰，我就勇往直前，把它一同焚燒。","notes":[]},{"n":5,"t":"不然，讓它持住我的能力，使它與我和好，願它與我和好。","notes":[]},{"n":6,"t":"將來雅各要扎根，以色列要發芽開花；他們的果實必充滿世界。","notes":[]},{"n":7,"t":"主擊打他們，豈像擊打那些擊打他們的人嗎？他們被殺戮，豈像被他們所殺戮的嗎？","notes":[]},{"n":8,"t":"你打發他們去，是相機宜與他們相爭；颳東風的日子，就用暴風將他們逐去。","notes":[]},{"n":9,"t":"所以，雅各的罪孽得赦免，他的罪過得除掉的果效，全在乎此：就是他叫祭壇的石頭變為打碎的灰石，以致木偶和日像不再立起。","notes":[]},{"n":10,"t":"因為堅固城變為淒涼，成了撇下離棄的居所，像曠野一樣；牛犢必在那裏吃草，在那裏躺臥，並吃盡其中的樹枝。","notes":[]},{"n":11,"t":"枝條枯乾，必被折斷；婦女要來點火燒著。因為這百姓蒙昧無知，所以，創造他們的必不憐恤他們；造成他們的也不施恩與他們。","notes":[]},{"n":12,"t":"以色列人哪，到那日，耶和華必從大河，直到埃及小河，將你們一一地收集，如同人打樹拾果一樣。","notes":[]},{"n":13,"t":"當那日，必大發角聲，在亞述地將要滅亡的，並在埃及地被趕散的，都要來，他們就在耶路撒冷聖山上敬拜耶和華。","notes":[]}]},"28":{"heading":"對北國的警告","verses":[{"n":1,"t":"禍哉！以法蓮的酒徒，住在肥美谷的山上，他們心裏高傲，以所誇的為冠冕，猶如將殘之花。","notes":[]},{"n":2,"t":"看哪，主有一大能大力者，像一陣冰雹，像毀滅的暴風，像漲溢的大水，他必用手將冠冕摔落於地。","notes":[]},{"n":3,"t":"以法蓮高傲的酒徒，他的冠冕必被踏在腳下。","notes":[]},{"n":4,"t":"那榮美將殘之花，就是在肥美谷山上的，必像夏令以前初熟的無花果；看見這果的就注意，一到手中就吞吃了。","notes":[]},{"n":5,"t":"到那日，萬軍之耶和華必作他餘剩之民的榮冠華冕，","notes":[]},{"n":6,"t":"也作了在位上行審判者公平之靈，並城門口打退仇敵者的力量。","notes":[]},{"n":7,"t":"就是這地的人也因酒搖搖晃晃，因濃酒東倒西歪。祭司和先知因濃酒搖搖晃晃，被酒所困，因濃酒東倒西歪。他們錯解默示，謬行審判。","notes":[],"heads":["以賽亞和猶大酒醉的先知"]},{"n":8,"t":"因為各席上滿了嘔吐的污穢，無一處乾淨。","notes":[]},{"n":9,"t":"譏誚先知的說：他要將知識指教誰呢？要使誰明白傳言呢？是那剛斷奶離懷的嗎？","notes":[]},{"n":10,"t":"他竟命上加命，令上加令，律上加律，例上加例，這裏一點，那裏一點。","notes":[]},{"n":11,"t":"先知說：不然，主要藉異邦人的嘴唇和外邦人的舌頭對這百姓說話。","notes":[]},{"n":12,"t":"他曾對他們說：你們要使疲乏人得安息，這樣才得安息，才得舒暢，他們卻不肯聽。","notes":[]},{"n":13,"t":"所以，耶和華向他們說的話是命上加命，令上加令，律上加律，例上加例，這裏一點，那裏一點，以致他們前行仰面跌倒，而且跌碎，並陷入網羅被纏住。","notes":[]},{"n":14,"t":"所以，你們這些褻慢的人，就是轄管住在耶路撒冷這百姓的，要聽耶和華的話。","notes":[],"heads":["錫安的房角石"]},{"n":15,"t":"你們曾說：我們與死亡立約，與陰間結盟；敵軍如水漲漫經過的時候，必不臨到我們；因我們以謊言為避所，在虛假以下藏身。","notes":["原文是鞭子"]},{"n":16,"t":"所以，主耶和華如此說：看哪，我在錫安放一塊石頭作為根基，是試驗過的石頭，是穩固根基，寶貴的房角石；信靠的人必不著急。","notes":[]},{"n":17,"t":"我必以公平為準繩，以公義為線鉈。冰雹必沖去謊言的避所；大水必漫過藏身之處。","notes":[]},{"n":18,"t":"你們與死亡所立的約必然廢掉，與陰間所結的盟必立不住。敵軍如水漲漫經過的時候，你們必被他踐踏；","notes":["原文是鞭子"]},{"n":19,"t":"每逢經過必將你們擄去。因為每早晨他必經過，白晝黑夜都必如此。明白傳言的必受驚恐。","notes":[]},{"n":20,"t":"原來，床榻短，使人不能舒身；被窩窄，使人不能遮體。","notes":[]},{"n":21,"t":"耶和華必興起，像在毗拉心山；他必發怒，像在基遍谷，好做成他的工，就是非常的工；成就他的事，就是奇異的事。","notes":[]},{"n":22,"t":"現在你們不可褻慢，恐怕捆你們的綁索更結實了；因為我從主－萬軍之耶和華那裏聽見，已經決定在全地上施行滅絕的事。","notes":[]},{"n":23,"t":"你們當側耳聽我的聲音，留心聽我的言語。","notes":[],"heads":["神的智慧"]},{"n":24,"t":"那耕地為要撒種的，豈是常常耕地呢？豈是常常開墾耙地呢？","notes":[]},{"n":25,"t":"他拉平了地面，豈不就撒種小茴香，播種大茴香，按行列種小麥，在定處種大麥，在田邊種粗麥呢？","notes":[]},{"n":26,"t":"因為他的神教導他務農相宜，並且指教他。","notes":[]},{"n":27,"t":"原來打小茴香，不用尖利的器具，軋大茴香，也不用碌碡；但用杖打小茴香，用棍打大茴香。","notes":["原文是車輪；下同"]},{"n":28,"t":"做餅的糧食是用磨磨碎，因它不必常打；雖用碌碡和馬打散，卻不磨它。","notes":[]},{"n":29,"t":"這也是出於萬軍之耶和華－他的謀略奇妙；他的智慧廣大。","notes":[]}]},"29":{"heading":"耶路撒冷的命運","verses":[{"n":1,"t":"唉！亞利伊勒，亞利伊勒，大衛安營的城，任憑你年上加年，節期照常周流。","notes":[]},{"n":2,"t":"我終必使亞利伊勒困難；她必悲傷哀號，我卻仍以她為亞利伊勒。","notes":[]},{"n":3,"t":"我必四圍安營攻擊你，屯兵圍困你，築壘攻擊你。","notes":[]},{"n":4,"t":"你必敗落，從地中說話；你的言語必微細出於塵埃。你的聲音必像那交鬼者的聲音出於地；你的言語低低微微出於塵埃。","notes":[]},{"n":5,"t":"你仇敵的群眾，卻要像細塵；強暴人的群眾，也要像飛糠。這事必頃刻之間忽然臨到。","notes":[]},{"n":6,"t":"萬軍之耶和華必用雷轟、地震、大聲、旋風、暴風，並吞滅的火焰，向她討罪。","notes":[]},{"n":7,"t":"那時，攻擊亞利伊勒列國的群眾，就是一切攻擊亞利伊勒和她的保障，並使她困難的，必如夢景，如夜間的異象；","notes":[]},{"n":8,"t":"又必像飢餓的人夢中吃飯，醒了仍覺腹空；或像口渴的人夢中喝水，醒了仍覺發昏，心裏想喝。攻擊錫安山列國的群眾也必如此。","notes":[]},{"n":9,"t":"你們等候驚奇吧！你們宴樂昏迷吧！他們醉了，卻非因酒；他們東倒西歪，卻非因濃酒。","notes":[],"heads":["沒有人聽警告"]},{"n":10,"t":"因為耶和華將沉睡的靈澆灌你們，封閉你們的眼，蒙蓋你們的頭。你們的眼就是先知；你們的頭就是先見。","notes":[]},{"n":11,"t":"所有的默示，你們看如封住的書卷，人將這書卷交給識字的，說：「請念吧！」他說：「我不能念，因為是封住了。」","notes":[]},{"n":12,"t":"又將這書卷交給不識字的人，說：「請念吧！」他說：「我不識字。」","notes":[]},{"n":13,"t":"主說：因為這百姓親近我，用嘴唇尊敬我，心卻遠離我；他們敬畏我，不過是領受人的吩咐。","notes":[]},{"n":14,"t":"所以，我在這百姓中要行奇妙的事，就是奇妙又奇妙的事。他們智慧人的智慧必然消滅，聰明人的聰明必然隱藏。","notes":[]},{"n":15,"t":"禍哉！那些向耶和華深藏謀略的，又在暗中行事，說：誰看見我們呢？誰知道我們呢？","notes":[],"heads":["將來的希望"]},{"n":16,"t":"你們把事顛倒了，豈可看窯匠如泥嗎？被製作的物豈可論製作物的說：他沒有製作我？或是被創造的物論造物的說：他沒有聰明？","notes":[]},{"n":17,"t":"黎巴嫩變為肥田，肥田看如樹林，不是只有一點點時候嗎？","notes":[]},{"n":18,"t":"那時，聾子必聽見這書上的話；瞎子的眼必從迷矇黑暗中得以看見。","notes":[]},{"n":19,"t":"謙卑人必因耶和華增添歡喜；人間貧窮的必因以色列的聖者快樂。","notes":[]},{"n":20,"t":"因為，強暴人已歸無有，褻慢人已經滅絕，一切找機會作孽的都被剪除。","notes":[]},{"n":21,"t":"他們在爭訟的事上定無罪的為有罪，為城門口責備人的設下網羅，用虛無的事屈枉義人。","notes":[]},{"n":22,"t":"所以，救贖亞伯拉罕的耶和華論雅各家如此說：雅各必不再羞愧，面容也不致變色。","notes":[]},{"n":23,"t":"但他看見他的眾子，就是我手的工作在他那裏，他們必尊我的名為聖，必尊雅各的聖者為聖，必敬畏以色列的神。","notes":[]},{"n":24,"t":"心中迷糊的必得明白；發怨言的必受訓誨。","notes":[]}]},"30":{"heading":"跟埃及訂立無用的條約","verses":[{"n":1,"t":"耶和華說：禍哉！這悖逆的兒女。他們同謀，卻不由於我，結盟，卻不由於我的靈，以致罪上加罪；","notes":[]},{"n":2,"t":"起身下埃及去，並沒有求問我；要靠法老的力量加添自己的力量，並投在埃及的蔭下。","notes":[]},{"n":3,"t":"所以，法老的力量必作你們的羞辱；投在埃及的蔭下，要為你們的慚愧。","notes":[]},{"n":4,"t":"他們的首領已在瑣安；他們的使臣到了哈內斯。","notes":[]},{"n":5,"t":"他們必因那不利於他們的民蒙羞。那民並非幫助，也非利益，只作羞恥凌辱。","notes":[]},{"n":6,"t":"論南方牲畜的默示：他們把財物馱在驢駒的脊背上，將寶物馱在駱駝的肉鞍上，經過艱難困苦之地，就是公獅、母獅、蝮蛇、火焰的飛龍之地，往那不利於他們的民那裏去。","notes":[]},{"n":7,"t":"埃及的幫助是徒然無益的；所以我稱她為「坐而不動的拉哈伯」。","notes":[]},{"n":8,"t":"現今你去，在他們面前將這話刻在版上，寫在書上，以便傳留後世，直到永永遠遠。","notes":[],"heads":["不順服的百姓"]},{"n":9,"t":"因為他們是悖逆的百姓、說謊的兒女，不肯聽從耶和華訓誨的兒女。","notes":[]},{"n":10,"t":"他們對先見說：不要望見不吉利的事，對先知說：不要向我們講正直的話；要向我們說柔和的話，言虛幻的事。","notes":[]},{"n":11,"t":"你們要離棄正道，偏離直路，不要在我們面前再提說以色列的聖者。","notes":[]},{"n":12,"t":"所以，以色列的聖者如此說：因為你們藐視這訓誨的話，倚賴欺壓和乖僻，以此為可靠的，","notes":[]},{"n":13,"t":"故此，這罪孽在你們身上，好像將要破裂凸出來的高牆，頃刻之間忽然坍塌；","notes":[]},{"n":14,"t":"要被打碎，好像把窯匠的瓦器打碎，毫不顧惜，甚至碎塊中找不到一片可用以從爐內取火，從池中舀水。","notes":[]},{"n":15,"t":"主耶和華－以色列的聖者曾如此說：你們得救在乎歸回安息；你們得力在乎平靜安穩；你們竟自不肯。","notes":[]},{"n":16,"t":"你們卻說：不然，我們要騎馬奔走。所以你們必然奔走；又說：我們要騎飛快的牲口。所以追趕你們的，也必飛快。","notes":[]},{"n":17,"t":"一人叱喝，必令千人逃跑；五人叱喝，你們都必逃跑；以致剩下的，好像山頂的旗杆，岡上的大旗。","notes":[]},{"n":18,"t":"耶和華必然等候，要施恩給你們；必然興起，好憐憫你們。因為耶和華是公平的神；凡等候他的都是有福的！","notes":[]},{"n":19,"t":"百姓必在錫安、在耶路撒冷居住；你不再哭泣。主必因你哀求的聲音施恩給你；他聽見的時候就必應允你。","notes":[],"heads":["主要賜福給他的子民"]},{"n":20,"t":"主雖然以艱難給你當餅，以困苦給你當水，你的教師卻不再隱藏；你眼必看見你的教師。","notes":[]},{"n":21,"t":"你或向左或向右，你必聽見後邊有聲音說：「這是正路，要行在其間。」","notes":[]},{"n":22,"t":"你雕刻偶像所包的銀子和鑄造偶像所鍍的金子，你要玷污，要拋棄，好像污穢之物，對偶像說：「去吧！」","notes":[]},{"n":23,"t":"你將種子撒在地裏，主必降雨在其上，並使地所出的糧肥美豐盛。到那時，你的牲畜必在寬闊的草場吃草。","notes":[]},{"n":24,"t":"耕地的牛和驢駒必吃加鹽的料；這料是用木杴和杈子揚淨的。","notes":[]},{"n":25,"t":"在大行殺戮的日子，高臺倒塌的時候，各高山岡陵必有川流河湧。","notes":[]},{"n":26,"t":"當耶和華纏裹他百姓的損處，醫治他民鞭傷的日子，月光必像日光，日光必加七倍，像七日的光一樣。","notes":[]},{"n":27,"t":"看哪，耶和華的名從遠方來，怒氣燒起，密煙上騰。他的嘴唇滿有忿恨；他的舌頭像吞滅的火。","notes":[],"heads":["神要懲罰亞述"]},{"n":28,"t":"他的氣如漲溢的河水，直漲到頸項，要用毀滅的篩籮篩淨列國，並且在眾民的口中必有使人錯行的嚼環。","notes":[]},{"n":29,"t":"你們必唱歌，像守聖節的夜間一樣，並且心中喜樂，像人吹笛，上耶和華的山，到以色列的磐石那裏。","notes":[]},{"n":30,"t":"耶和華必使人聽他威嚴的聲音，又顯他降罰的膀臂和他怒中的忿恨，並吞滅的火焰與霹雷、暴風、冰雹。","notes":[]},{"n":31,"t":"亞述人必因耶和華的聲音驚惶；耶和華必用杖擊打他。","notes":[]},{"n":32,"t":"耶和華必將命定的杖加在他身上；每打一下，人必擊鼓彈琴。打仗的時候，耶和華必掄起手來，與他交戰。","notes":[]},{"n":33,"t":"原來陀斐特又深又寬，早已為王預備好了；其中堆的是火與許多木柴。耶和華的氣如一股硫磺火使他著起來。","notes":[]}]},"31":{"heading":"神要保護耶路撒冷","verses":[{"n":1,"t":"禍哉！那些下埃及求幫助的，是因仗賴馬匹，倚靠甚多的車輛，並倚靠強壯的馬兵，卻不仰望以色列的聖者，也不求問耶和華。","notes":[]},{"n":2,"t":"其實，耶和華有智慧；他必降災禍，並不反悔自己的話，卻要興起攻擊那作惡之家，又攻擊那作孽幫助人的。","notes":[]},{"n":3,"t":"埃及人不過是人，並不是神；他們的馬不過是血肉，並不是靈。耶和華一伸手，那幫助人的必絆跌，那受幫助的也必跌倒，都一同滅亡。","notes":[]},{"n":4,"t":"耶和華對我如此說：獅子和少壯獅子護食咆哮，就是喊許多牧人來攻擊牠，牠總不因他們的聲音驚惶，也不因他們的喧嘩縮伏。如此，萬軍之耶和華也必降臨在錫安山岡上爭戰。","notes":[]},{"n":5,"t":"雀鳥怎樣搧翅覆雛，萬軍之耶和華也要照樣保護耶路撒冷。他必保護拯救，要越門保守。","notes":[]},{"n":6,"t":"以色列人哪，你們深深地悖逆耶和華，現今要歸向他。","notes":[]},{"n":7,"t":"到那日，各人必將他金偶像銀偶像，就是親手所造、陷自己在罪中的，都拋棄了。","notes":[]},{"n":8,"t":"亞述人必倒在刀下，並非人的刀；有刀要將他吞滅，並非人的刀。他必逃避這刀；他的少年人必成為服苦的。","notes":[]},{"n":9,"t":"他的磐石必因驚嚇挪去；他的首領必因大旗驚惶。這是那有火在錫安、有爐在耶路撒冷的耶和華說的。","notes":[]}]},"32":{"heading":"公正的王","verses":[{"n":1,"t":"看哪，必有一王憑公義行政；必有首領藉公平掌權。","notes":[]},{"n":2,"t":"必有一人像避風所和避暴雨的隱密處，又像河流在乾旱之地，像大磐石的影子在疲乏之地。","notes":[]},{"n":3,"t":"那能看的人，眼不再昏迷；能聽的人，耳必得聽聞。","notes":[]},{"n":4,"t":"冒失人的心必明白知識；結吧人的舌必說話通快。","notes":[]},{"n":5,"t":"愚頑人不再稱為高明；吝嗇人不再稱為大方。","notes":[]},{"n":6,"t":"因為愚頑人必說愚頑話，心裏想作罪孽，慣行褻瀆的事，說錯謬的話攻擊耶和華，使飢餓的人無食可吃，使口渴的人無水可喝。","notes":[]},{"n":7,"t":"吝嗇人所用的法子是惡的；他圖謀惡計，用謊言毀滅謙卑人；窮乏人講公理的時候，他也是這樣行。","notes":[]},{"n":8,"t":"高明人卻謀高明事，在高明事上也必永存。","notes":[]},{"n":9,"t":"安逸的婦女啊，起來聽我的聲音！無慮的女子啊，側耳聽我的言語！","notes":[],"heads":["審判和復興"]},{"n":10,"t":"無慮的女子啊，再過一年多，必受騷擾；因為無葡萄可摘，無果子可收。","notes":["或譯：禾稼"]},{"n":11,"t":"安逸的婦女啊，要戰兢；無慮的女子啊，要受騷擾。脫去衣服，赤著身體，腰束麻布。","notes":[]},{"n":12,"t":"她們必為美好的田地和多結果的葡萄樹，搥胸哀哭。","notes":[]},{"n":13,"t":"荊棘蒺藜必長在我百姓的地上，又長在歡樂的城中和一切快樂的房屋上。","notes":[]},{"n":14,"t":"因為宮殿必被撇下，多民的城必被離棄；山岡望樓永為洞穴，作野驢所喜樂的，為羊群的草場。","notes":[]},{"n":15,"t":"等到聖靈從上澆灌我們，曠野就變為肥田，肥田看如樹林。","notes":[]},{"n":16,"t":"那時，公平要居在曠野；公義要居在肥田。","notes":[]},{"n":17,"t":"公義的果效必是平安；公義的效驗必是平穩，直到永遠。","notes":[]},{"n":18,"t":"我的百姓必住在平安的居所，安穩的住處，平靜的安歇所。","notes":[]},{"n":19,"t":"（ 但要降冰雹打倒樹林；城必全然拆平。）","notes":[]},{"n":20,"t":"你們在各水邊撒種、牧放牛驢的有福了！","notes":[]}]},"33":{"heading":"求救的祈禱","verses":[{"n":1,"t":"禍哉！你這毀滅人的，自己倒不被毀滅；行事詭詐的，人倒不以詭詐待你。你毀滅罷休了，自己必被毀滅；你行完了詭詐，人必以詭詐待你。","notes":[]},{"n":2,"t":"耶和華啊，求你施恩於我們；我們等候你。求你每早晨作我們的膀臂，遭難的時候為我們的拯救。","notes":[]},{"n":3,"t":"喧嚷的響聲一發，眾民奔逃；你一興起，列國四散。","notes":[]},{"n":4,"t":"你們所擄的必被斂盡，好像螞蚱吃盡禾稼。人要蹦在其上，好像蝗蟲一樣。","notes":["原文是斂"]},{"n":5,"t":"耶和華被尊崇，因他居在高處；他以公平公義充滿錫安。","notes":[]},{"n":6,"t":"你一生一世必得安穩－有豐盛的救恩，並智慧和知識；你以敬畏耶和華為至寶。","notes":[]},{"n":7,"t":"看哪，他們的豪傑在外頭哀號；求和的使臣痛痛哭泣。","notes":[]},{"n":8,"t":"大路荒涼，行人止息；敵人背約，藐視城邑，不顧人民。","notes":[]},{"n":9,"t":"地上悲哀衰殘；黎巴嫩羞愧枯乾；沙崙像曠野；巴珊和迦密的樹林凋殘。","notes":[]},{"n":10,"t":"耶和華說：現在我要起來；我要興起；我要勃然而興。","notes":[],"heads":["耶和華對敵人的警告"]},{"n":11,"t":"你們要懷的是糠秕，要生的是碎稭；你們的氣就是吞滅自己的火。","notes":[]},{"n":12,"t":"列邦必像已燒的石灰，像已割的荊棘在火中焚燒。","notes":[]},{"n":13,"t":"你們遠方的人當聽我所行的；你們近處的人當承認我的大能。","notes":[]},{"n":14,"t":"錫安中的罪人都懼怕；不敬虔的人被戰兢抓住。我們中間誰能與吞滅的火同住？我們中間誰能與永火同住呢？","notes":[]},{"n":15,"t":"行事公義、說話正直、憎惡欺壓的財利、擺手不受賄賂、塞耳不聽流血的話，閉眼不看邪惡事的，","notes":[]},{"n":16,"t":"他必居高處；他的保障是磐石的堅壘；他的糧必不缺乏；他的水必不斷絕。","notes":["原文是賜給"]},{"n":17,"t":"你的眼必見王的榮美，必見遼闊之地。","notes":[],"heads":["光榮的將來"]},{"n":18,"t":"你的心必思想那驚嚇的事，自問說：記數目的在哪裏呢？平貢銀的在哪裏呢？數戍樓的在哪裏呢？","notes":[]},{"n":19,"t":"你必不見那強暴的民，就是說話深奧，你不能明白，言語呢喃，你不能懂得的。","notes":[]},{"n":20,"t":"你要看錫安－我們守聖節的城！你的眼必見耶路撒冷為安靜的居所，為不挪移的帳幕，橛子永不拔出，繩索一根也不折斷。","notes":[]},{"n":21,"t":"在那裏，耶和華必顯威嚴與我們同在，當作江河寬闊之地；其中必沒有盪槳搖櫓的船來往，也沒有威武的船經過。","notes":[]},{"n":22,"t":"因為，耶和華是審判我們的；耶和華是給我們設律法的；耶和華是我們的王；他必拯救我們。","notes":[]},{"n":23,"t":"你的繩索鬆開：不能栽穩桅杆，也不能揚起篷來。那時許多擄來的物被分了；瘸腿的把掠物奪去了。","notes":[]},{"n":24,"t":"城內居民必不說：我病了；其中居住的百姓，罪孽都赦免了。","notes":[]}]},"34":{"heading":"神要懲罰仇敵","verses":[{"n":1,"t":"列國啊，要近前來聽！眾民哪，要側耳而聽！地和其上所充滿的，世界和其中一切所出的都應當聽！","notes":[]},{"n":2,"t":"因為耶和華向萬國發忿恨，向他們的全軍發烈怒，將他們滅盡，交出他們受殺戮。","notes":[]},{"n":3,"t":"被殺的必然拋棄，屍首臭氣上騰；諸山被他們的血融化。","notes":[]},{"n":4,"t":"天上的萬象都要消沒；天被捲起，好像書卷。其上的萬象要殘敗，像葡萄樹的葉子殘敗，又像無花果樹的葉子殘敗一樣。","notes":[]},{"n":5,"t":"因為我的刀在天上已經喝足；這刀必臨到以東和我所咒詛的民，要施行審判。","notes":[]},{"n":6,"t":"耶和華的刀滿了血，用脂油和羊羔、公山羊的血，並公綿羊腰子的脂油滋潤的；因為耶和華在波斯拉有獻祭的事，在以東地大行殺戮。","notes":[]},{"n":7,"t":"野牛、牛犢，和公牛要一同下來。他們的地喝醉了血；他們的塵土因脂油肥潤。","notes":[]},{"n":8,"t":"因耶和華有報仇之日，為錫安的爭辯有報應之年。","notes":[]},{"n":9,"t":"以東的河水要變為石油，塵埃要變為硫磺；地土成為燒著的石油，","notes":[]},{"n":10,"t":"晝夜總不熄滅，煙氣永遠上騰，必世世代代成為荒廢，永永遠遠無人經過。","notes":[]},{"n":11,"t":"鵜鶘、箭豬卻要得為業；貓頭鷹、烏鴉要住在其間。耶和華必將空虛的準繩，混沌的線鉈，拉在其上。","notes":[]},{"n":12,"t":"以東人要召貴冑來治國；那裏卻無一個，首領也都歸於無有。","notes":[]},{"n":13,"t":"以東的宮殿要長荊棘；保障要長蒺藜和刺草；要作野狗的住處，鴕鳥的居所。","notes":[]},{"n":14,"t":"曠野的走獸要和豺狼相遇；野山羊要與伴偶對叫。夜間的怪物必在那裏棲身，自找安歇之處。","notes":[]},{"n":15,"t":"箭蛇要在那裏做窩，下蛋，菢蛋，生子，聚子在其影下；鷂鷹各與伴偶聚集在那裏。","notes":[]},{"n":16,"t":"你們要查考宣讀耶和華的書。這都無一缺少，無一沒有伴偶；因為我的口已經吩咐，他的靈將牠們聚集。","notes":[]},{"n":17,"t":"他也為牠們拈鬮，又親手用準繩給牠們分地；牠們必永得為業，世世代代住在其間。","notes":[]}]},"35":{"heading":"神聖之路","verses":[{"n":1,"t":"曠野和乾旱之地必然歡喜；沙漠也必快樂；又像玫瑰開花，","notes":[]},{"n":2,"t":"必開花繁盛，樂上加樂，而且歡呼。黎巴嫩的榮耀，並迦密與沙崙的華美，必賜給它。人必看見耶和華的榮耀，我們神的華美。","notes":[]},{"n":3,"t":"你們要使軟弱的手堅壯，無力的膝穩固。","notes":[]},{"n":4,"t":"對膽怯的人說：你們要剛強，不要懼怕。看哪，你們的神必來報仇，必來施行極大的報應；他必來拯救你們。","notes":[]},{"n":5,"t":"那時，瞎子的眼必睜開；聾子的耳必開通。","notes":[]},{"n":6,"t":"那時，瘸子必跳躍像鹿；啞巴的舌頭必能歌唱。在曠野必有水發出；在沙漠必有河湧流。","notes":[]},{"n":7,"t":"發光的沙要變為水池；乾渴之地要變為泉源。在野狗躺臥之處，必有青草、蘆葦，和蒲草。","notes":["或譯：蜃樓"]},{"n":8,"t":"在那裏必有一條大道，稱為聖路。污穢人不得經過，必專為贖民行走；行路的人雖愚昧，也不致失迷。","notes":[]},{"n":9,"t":"在那裏必沒有獅子，猛獸也不登這路；在那裏都遇不見，只有贖民在那裏行走。","notes":[]},{"n":10,"t":"並且耶和華救贖的民必歸回，歌唱來到錫安；永樂必歸到他們的頭上；他們必得著歡喜快樂，憂愁歎息盡都逃避。","notes":[]}]},"36":{"heading":"亞述人威脅耶路撒冷","verses":[{"n":1,"t":"希西家王十四年，亞述王西拿基立上來攻擊猶大的一切堅固城，將城攻取。","notes":[]},{"n":2,"t":"亞述王從拉吉差遣拉伯沙基率領大軍往耶路撒冷，到希西家王那裏去。他就站在上池的水溝旁，在漂布地的大路上。","notes":[]},{"n":3,"t":"於是希勒家的兒子家宰以利亞敬，並書記舍伯那和亞薩的兒子史官約亞，出來見拉伯沙基。","notes":[]},{"n":4,"t":"拉伯沙基對他們說：「你們去告訴希西家說，亞述大王如此說：『你所倚靠的有甚麼可仗賴的呢？","notes":[]},{"n":5,"t":"你說，有打仗的計謀和能力，我看不過是虛話。你到底倚靠誰才背叛我呢？","notes":[]},{"n":6,"t":"看哪，你所倚靠的埃及是那壓傷的葦杖，人若靠這杖，就必刺透他的手。埃及王法老向一切倚靠他的人也是這樣。","notes":[]},{"n":7,"t":"你若對我說：我們倚靠耶和華－我們的神。希西家豈不是將神的邱壇和祭壇廢去，且對猶大和耶路撒冷的人說：你們當在這壇前敬拜嗎？","notes":[]},{"n":8,"t":"現在你把當頭給我主亞述王，我給你二千匹馬，看你這一面騎馬的人夠不夠。","notes":[]},{"n":9,"t":"若不然，怎能打敗我主臣僕中最小的軍長呢？你竟倚靠埃及的戰車馬兵嗎？","notes":[]},{"n":10,"t":"現在我上來攻擊毀滅這地，豈沒有耶和華的意思嗎？耶和華吩咐我說，你上去攻擊毀滅這地吧！』」","notes":[]},{"n":11,"t":"以利亞敬、舍伯那、約亞對拉伯沙基說：「求你用亞蘭言語和僕人說話，因為我們懂得；不要用猶大言語和我們說話，達到城上百姓的耳中。」","notes":[]},{"n":12,"t":"拉伯沙基說：「我主差遣我來，豈是單對你和你的主說這些話嗎？不也是對這些坐在城上、要與你們一同吃自己糞喝自己尿的人說嗎？」","notes":[]},{"n":13,"t":"於是，拉伯沙基站著，用猶大言語大聲喊著說：「你們當聽亞述大王的話。","notes":[]},{"n":14,"t":"王如此說：『你們不要被希西家欺哄了，因他不能拯救你們。","notes":[]},{"n":15,"t":"也不要聽希西家使你們倚靠耶和華說：耶和華必要拯救我們，這城必不交在亞述王的手中。』","notes":[]},{"n":16,"t":"不要聽希西家的話，因亞述王如此說：『你們要與我和好。出來投降我，各人就可以吃自己葡萄樹和無花果樹的果子，喝自己井裏的水。","notes":[]},{"n":17,"t":"等我來領你們到一個地方，與你們本地一樣，就是有五穀和新酒之地，有糧食和葡萄園之地。","notes":[]},{"n":18,"t":"你們要謹防，恐怕希西家勸導你們說：耶和華必拯救我們。列國的神有哪一個救他本國脫離亞述王的手呢？","notes":[]},{"n":19,"t":"哈馬和亞珥拔的神在哪裏呢？西法瓦音的神在哪裏呢？他們曾救撒馬利亞脫離我的手嗎？","notes":[]},{"n":20,"t":"這些國的神有誰曾救自己的國脫離我的手呢？難道耶和華能救耶路撒冷脫離我的手嗎？』」","notes":[]},{"n":21,"t":"百姓靜默不言，並不回答一句，因為王曾吩咐說：「不要回答他。」","notes":[]},{"n":22,"t":"當下希勒家的兒子家宰以利亞敬和書記舍伯那，並亞薩的兒子史官約亞，都撕裂衣服，來到希西家那裏，將拉伯沙基的話告訴了他。","notes":[]}]},"37":{"heading":"國王下令徵求以賽亞的意見","verses":[{"n":1,"t":"希西家王聽見就撕裂衣服，披上麻布，進了耶和華的殿，","notes":[]},{"n":2,"t":"使家宰以利亞敬和書記舍伯那，並祭司中的長老，都披上麻布，去見亞摩斯的兒子先知以賽亞，","notes":[]},{"n":3,"t":"對他說：「希西家如此說：『今日是急難、責罰、凌辱的日子，就如婦人將要生產嬰孩，卻沒有力量生產。","notes":[]},{"n":4,"t":"或者耶和華－你的神聽見拉伯沙基的話，就是他主人亞述王打發他來辱罵永生神的話；耶和華－你的神聽見這話就發斥責。故此，求你為餘剩的民揚聲禱告。』」","notes":[]},{"n":5,"t":"希西家王的臣僕就去見以賽亞。","notes":[]},{"n":6,"t":"以賽亞對他們說：「要這樣對你們的主人說，耶和華如此說：『你聽見亞述王的僕人褻瀆我的話，不要懼怕。","notes":[]},{"n":7,"t":"我必驚動他的心；他要聽見風聲就歸回本地，我必使他在那裏倒在刀下。』」","notes":["原文是使靈進入"]},{"n":8,"t":"拉伯沙基回去，正遇見亞述王攻打立拿；原來他早聽見亞述王拔營離開拉吉。","notes":[],"heads":["亞述人再來威脅"]},{"n":9,"t":"亞述王聽見人論古實王特哈加說：「他出來要與你爭戰。」亞述王一聽見，就打發使者去見希西家，吩咐他們說：","notes":[]},{"n":10,"t":"「你們對猶大王希西家如此說：『不要聽你所倚靠的神欺哄你說：耶路撒冷必不交在亞述王的手中。","notes":[]},{"n":11,"t":"你總聽說亞述諸王向列國所行的乃是盡行滅絕，難道你還能得救嗎？","notes":[]},{"n":12,"t":"我列祖所毀滅的，就是歌散、哈蘭、利色，和屬提‧拉撒的伊甸人；這些國的神何曾拯救這些國呢？","notes":[]},{"n":13,"t":"哈馬的王，亞珥拔的王，西法瓦音城的王，希拿和以瓦的王，都在哪裏呢？』」","notes":[]},{"n":14,"t":"希西家從使者手裏接過書信來，看完了，就上耶和華的殿，將書信在耶和華面前展開。","notes":[]},{"n":15,"t":"希西家向耶和華禱告說：","notes":[]},{"n":16,"t":"「坐在二基路伯上萬軍之耶和華－以色列的神啊，你－惟有你是天下萬國的神，你曾創造天地。","notes":[]},{"n":17,"t":"耶和華啊，求你側耳而聽；耶和華啊，求你睜眼而看，要聽西拿基立的一切話，他是打發使者來辱罵永生神的。","notes":[]},{"n":18,"t":"耶和華啊，亞述諸王果然使列國和列國之地變為荒涼，","notes":[]},{"n":19,"t":"將列國的神像都扔在火裏；因為他本不是神，乃是人手所造的，是木頭、石頭的，所以滅絕他。","notes":[]},{"n":20,"t":"耶和華－我們的神啊，現在求你救我們脫離亞述王的手，使天下萬國都知道惟有你是耶和華。」","notes":[]},{"n":21,"t":"亞摩斯的兒子以賽亞就打發人去見希西家，說：「耶和華－以色列的神如此說，你既然求我攻擊亞述王西拿基立，","notes":[],"heads":["以賽亞給王的信息"]},{"n":22,"t":"所以耶和華論他這樣說：錫安的處女藐視你，嗤笑你；耶路撒冷的女子向你搖頭。","notes":[]},{"n":23,"t":"你辱罵誰，褻瀆誰？揚起聲來，高舉眼目攻擊誰呢？乃是攻擊以色列的聖者。","notes":[]},{"n":24,"t":"你藉你的臣僕辱罵主說：我率領許多戰車上山頂，到黎巴嫩極深之處；我要砍伐其中高大的香柏樹和佳美的松樹。我必上極高之處，進入肥田的樹林。","notes":[]},{"n":25,"t":"我已經挖井喝水；我必用腳掌踏乾埃及的一切河。","notes":[]},{"n":26,"t":"耶和華說：你豈沒有聽見我早先所做的、古時所立的嗎？現在藉你使堅固城荒廢，變為亂堆。","notes":[]},{"n":27,"t":"所以其中的居民力量甚小，驚惶羞愧。他們像野草，像青菜，如房頂上的草，又如田間未長成的禾稼。","notes":[]},{"n":28,"t":"你坐下，你出去，你進來，你向我發烈怒，我都知道。","notes":[]},{"n":29,"t":"因你向我發烈怒，又因你狂傲的話達到我耳中，我就要用鉤子鉤上你的鼻子，把嚼環放在你口裏，使你從原路轉回去。","notes":[]},{"n":30,"t":"「以色列人哪，我賜你們一個證據：你們今年要吃自生的，明年也要吃自長的，至於後年，你們要耕種收割，栽植葡萄園，吃其中的果子。","notes":[]},{"n":31,"t":"猶大家所逃脫餘剩的，仍要往下扎根，向上結果。","notes":[]},{"n":32,"t":"必有餘剩的民從耶路撒冷而出；必有逃脫的人從錫安山而來。萬軍之耶和華的熱心必成就這事。","notes":[]},{"n":33,"t":"「所以耶和華論亞述王如此說：他必不得來到這城，也不在這裏射箭，不得拿盾牌到城前，也不築壘攻城。","notes":[]},{"n":34,"t":"他從哪條路來，必從那條路回去，必不得來到這城。這是耶和華說的。","notes":[]},{"n":35,"t":"因我為自己的緣故，又為我僕人大衛的緣故，必保護拯救這城。」","notes":[]},{"n":36,"t":"耶和華的使者出去，在亞述營中殺了十八萬五千人。清早有人起來一看，都是死屍了。","notes":[]},{"n":37,"t":"亞述王西拿基立就拔營回去，住在尼尼微。","notes":[]},{"n":38,"t":"一日在他的神－尼斯洛廟裏叩拜，他兒子亞得米勒和沙利色用刀殺了他，就逃到亞拉臘地。他兒子以撒哈頓接續他作王。","notes":[]}]},"38":{"heading":"希西家王的疾病和痊癒","verses":[{"n":1,"t":"那時希西家病得要死，亞摩斯的兒子先知以賽亞去見他，對他說：「耶和華如此說：你當留遺命與你的家，因為你必死不能活了。」","notes":[]},{"n":2,"t":"希西家就轉臉朝牆，禱告耶和華說：","notes":[]},{"n":3,"t":"「耶和華啊，求你記念我在你面前怎樣存完全的心，按誠實行事，又做你眼中所看為善的。」希西家就痛哭了。","notes":[]},{"n":4,"t":"耶和華的話臨到以賽亞說：","notes":[]},{"n":5,"t":"「你去告訴希西家說，耶和華－你祖大衛的神如此說：我聽見了你的禱告，看見了你的眼淚。我必加增你十五年的壽數；","notes":[]},{"n":6,"t":"並且我要救你和這城脫離亞述王的手，也要保護這城。","notes":[]},{"n":7,"t":"「我－耶和華必成就我所說的。我先給你一個兆頭，","notes":[]},{"n":8,"t":"就是叫亞哈斯的日晷，向前進的日影往後退十度。」於是，前進的日影果然在日晷上往後退了十度。","notes":[]},{"n":9,"t":"猶大王希西家患病已經痊癒，就作詩說：","notes":[]},{"n":10,"t":"我說：正在我中年之日必進入陰間的門；我餘剩的年歲不得享受。","notes":["或譯：晌午"]},{"n":11,"t":"我說：我必不得見耶和華，就是在活人之地不見耶和華；我與世上的居民不再見面。","notes":[]},{"n":12,"t":"我的住處被遷去離開我，好像牧人的帳棚一樣；我將性命捲起，像織布的捲布一樣。耶和華必將我從機頭剪斷，從早到晚，他要使我完結。","notes":[]},{"n":13,"t":"我使自己安靜直到天亮；他像獅子折斷我一切的骨頭，從早到晚，他要使我完結。","notes":[]},{"n":14,"t":"我像燕子呢喃，像白鶴鳴叫，又像鴿子哀鳴；我因仰觀，眼睛困倦。耶和華啊，我受欺壓，求你為我作保。","notes":[]},{"n":15,"t":"我可說甚麼呢？他應許我的，也給我成就了。我因心裏的苦楚，在一生的年日必悄悄而行。","notes":[]},{"n":16,"t":"主啊，人得存活乃在乎此。我靈存活也全在此。所以求你使我痊癒，仍然存活。","notes":[]},{"n":17,"t":"看哪，我受大苦，本為使我得平安；你因愛我的靈魂便救我脫離敗壞的坑，因為你將我一切的罪扔在你的背後。","notes":["或譯：生命"]},{"n":18,"t":"原來，陰間不能稱謝你，死亡不能頌揚你；下坑的人不能盼望你的誠實。","notes":[]},{"n":19,"t":"只有活人，活人必稱謝你，像我今日稱謝你一樣。為父的，必使兒女知道你的誠實。","notes":[]},{"n":20,"t":"耶和華肯救我，所以，我們要一生一世在耶和華殿中用絲弦的樂器唱我的詩歌。","notes":[]},{"n":21,"t":"以賽亞說：「當取一塊無花果餅來，貼在瘡上，王必痊癒。」","notes":[]},{"n":22,"t":"希西家問說：「我能上耶和華的殿，有甚麼兆頭呢？」","notes":[]}]},"39":{"heading":"巴比倫王的使節","verses":[{"n":1,"t":"那時，巴比倫王巴拉但的兒子米羅達‧巴拉但聽見希西家病而痊癒，就送書信和禮物給他。","notes":[]},{"n":2,"t":"希西家喜歡見使者，就把自己寶庫的金子、銀子、香料、貴重的膏油，和他武庫的一切軍器，並所有的財寶都給他們看；他家中和全國之內，希西家沒有一樣不給他們看的。","notes":[]},{"n":3,"t":"於是先知以賽亞來見希西家王，問他說：「這些人說甚麼？他們從哪裏來見你？」希西家說：「他們從遠方的巴比倫來見我。」","notes":[]},{"n":4,"t":"以賽亞說：「他們在你家裏看見了甚麼？」希西家說：「凡我家中所有的，他們都看見了；我財寶中沒有一樣不給他們看的。」","notes":[]},{"n":5,"t":"以賽亞對希西家說：「你要聽萬軍之耶和華的話：","notes":[]},{"n":6,"t":"日子必到，凡你家裏所有的，並你列祖積蓄到如今的，都要被擄到巴比倫去，不留下一樣；這是耶和華說的。","notes":[]},{"n":7,"t":"並且從你本身所生的眾子，其中必有被擄去、在巴比倫王宮裏當太監的。」","notes":[]},{"n":8,"t":"希西家對以賽亞說：「你所說耶和華的話甚好，因為在我的年日中必有太平和穩固的景況。」","notes":[]}]},"40":{"heading":"安慰的話","verses":[{"n":1,"t":"你們的神說：你們要安慰，安慰我的百姓。","notes":[]},{"n":2,"t":"要對耶路撒冷說安慰的話，又向她宣告說，她爭戰的日子已滿了；她的罪孽赦免了；她為自己的一切罪，從耶和華手中加倍受罰。","notes":[]},{"n":3,"t":"有人聲喊著說：在曠野預備耶和華的路，在沙漠地修平我們神的道。","notes":["或譯：在曠野，有人聲喊著說：當預備耶和華的路"]},{"n":4,"t":"一切山窪都要填滿，大小山岡都要削平；高高低低的要改為平坦，崎崎嶇嶇的必成為平原。","notes":[]},{"n":5,"t":"耶和華的榮耀必然顯現；凡有血氣的必一同看見；因為這是耶和華親口說的。","notes":[]},{"n":6,"t":"有人聲說：你喊叫吧！有一個說：我喊叫甚麼呢？說：凡有血氣的盡都如草；他的美容都像野地的花。","notes":[]},{"n":7,"t":"草必枯乾，花必凋殘，因為耶和華的氣吹在其上；百姓誠然是草。","notes":[]},{"n":8,"t":"草必枯乾，花必凋殘，惟有我們神的話必永遠立定。","notes":[]},{"n":9,"t":"報好信息給錫安的啊，你要登高山；報好信息給耶路撒冷的啊，你要極力揚聲。揚聲不要懼怕，對猶大的城邑說：看哪，你們的神！","notes":[]},{"n":10,"t":"主耶和華必像大能者臨到；他的膀臂必為他掌權。他的賞賜在他那裏；他的報應在他面前。","notes":[]},{"n":11,"t":"他必像牧人牧養自己的羊群，用膀臂聚集羊羔抱在懷中，慢慢引導那乳養小羊的。","notes":[]},{"n":12,"t":"誰曾用手心量諸水，用手虎口量蒼天，用升斗盛大地的塵土，用秤稱山嶺，用天平平岡陵呢？","notes":[],"heads":["以色列的神無可比擬"]},{"n":13,"t":"誰曾測度耶和華的心，或作他的謀士指教他呢？","notes":["或譯：誰曾指示耶和華的靈"]},{"n":14,"t":"他與誰商議，誰教導他，誰將公平的路指示他，又將知識教訓他，將通達的道指教他呢？","notes":[]},{"n":15,"t":"看哪，萬民都像水桶的一滴，又算如天平上的微塵；他舉起眾海島，好像極微之物。","notes":[]},{"n":16,"t":"黎巴嫩的樹林不夠當柴燒；其中的走獸也不夠作燔祭。","notes":[]},{"n":17,"t":"萬民在他面前好像虛無，被他看為不及虛無，乃為虛空。","notes":[]},{"n":18,"t":"你們究竟將誰比神，用甚麼形像與神比較呢？","notes":[]},{"n":19,"t":"偶像是匠人鑄造，銀匠用金包裹，為它鑄造銀鍊。","notes":[]},{"n":20,"t":"窮乏獻不起這樣供物的，就揀選不能朽壞的樹木，為自己尋找巧匠，立起不能搖動的偶像。","notes":[]},{"n":21,"t":"你們豈不曾知道嗎？你們豈不曾聽見嗎？從起初豈沒有人告訴你們嗎？自從立地的根基，你們豈沒有明白嗎？","notes":[]},{"n":22,"t":"神坐在地球大圈之上；地上的居民好像蝗蟲。他鋪張穹蒼如幔子，展開諸天如可住的帳棚。","notes":[]},{"n":23,"t":"他使君王歸於虛無，使地上的審判官成為虛空。","notes":[]},{"n":24,"t":"他們是剛才栽上，剛才種上，根也剛才扎在地裏，他一吹在其上，便都枯乾；旋風將他們吹去，像碎稭一樣。","notes":["或譯：不曾；下同"]},{"n":25,"t":"那聖者說：你們將誰比我，叫他與我相等呢？","notes":[]},{"n":26,"t":"你們向上舉目，看誰創造這萬象，按數目領出，他一一稱其名；因他的權能，又因他的大能大力，連一個都不缺。","notes":[]},{"n":27,"t":"雅各啊，你為何說，我的道路向耶和華隱藏？以色列啊，你為何言，我的冤屈神並不查問？","notes":[]},{"n":28,"t":"你豈不曾知道嗎？你豈不曾聽見嗎？永在的神耶和華，創造地極的主，並不疲乏，也不困倦；他的智慧無法測度。","notes":[]},{"n":29,"t":"疲乏的，他賜能力；軟弱的，他加力量。","notes":[]},{"n":30,"t":"就是少年人也要疲乏困倦；強壯的也必全然跌倒。","notes":[]},{"n":31,"t":"但那等候耶和華的必重新得力。他們必如鷹展翅上騰；他們奔跑卻不困倦，行走卻不疲乏。","notes":[]}]},"41":{"heading":"神對以色列的保證","verses":[{"n":1,"t":"眾海島啊，當在我面前靜默；眾民當重新得力，都要近前來才可以說話，我們可以彼此辯論。","notes":[]},{"n":2,"t":"誰從東方興起一人，憑公義召他來到腳前呢？耶和華將列國交給他，使他管轄君王，把他們如灰塵交與他的刀，如風吹的碎稭交與他的弓。","notes":[]},{"n":3,"t":"他追趕他們，走他所未走的道，坦然前行。","notes":[]},{"n":4,"t":"誰行做成就這事，從起初宣召歷代呢？就是我－耶和華！我是首先的，也與末後的同在。","notes":[]},{"n":5,"t":"海島看見就都害怕；地極也都戰兢，就近前來。","notes":[]},{"n":6,"t":"他們各人幫助鄰舍，各人對弟兄說：壯膽吧！","notes":[]},{"n":7,"t":"木匠勉勵銀匠，用鎚打光的勉勵打砧的，論銲工說，銲得好；又用釘子釘穩，免得偶像動搖。","notes":[]},{"n":8,"t":"惟你以色列－我的僕人，雅各－我所揀選的，我朋友亞伯拉罕的後裔，","notes":[]},{"n":9,"t":"你是我從地極所領來的，從地角所召來的，且對你說：你是我的僕人；我揀選你，並不棄絕你。","notes":["原文是抓"]},{"n":10,"t":"你不要害怕，因為我與你同在；不要驚惶，因為我是你的神。我必堅固你，我必幫助你；我必用我公義的右手扶持你。","notes":[]},{"n":11,"t":"凡向你發怒的必都抱愧蒙羞；與你相爭的必如無有，並要滅亡。","notes":[]},{"n":12,"t":"與你爭競的，你要找他們也找不著；與你爭戰的必如無有，成為虛無。","notes":[]},{"n":13,"t":"因為我耶和華－你的神必攙扶你的右手，對你說：不要害怕！我必幫助你。","notes":[]},{"n":14,"t":"你這蟲雅各和你們以色列人，不要害怕！耶和華說：我必幫助你。你的救贖主就是以色列的聖者。","notes":[]},{"n":15,"t":"看哪，我已使你成為有快齒打糧的新器具；你要把山嶺打得粉碎，使岡陵如同糠秕。","notes":[]},{"n":16,"t":"你要把它簸揚，風要吹去；旋風要把它颳散。你倒要以耶和華為喜樂，以以色列的聖者為誇耀。","notes":[]},{"n":17,"t":"困苦窮乏人尋求水卻沒有；他們因口渴，舌頭乾燥。我－耶和華必應允他們；我－以色列的神必不離棄他們。","notes":[]},{"n":18,"t":"我要在淨光的高處開江河，在谷中開泉源；我要使沙漠變為水池，使乾地變為湧泉。","notes":[]},{"n":19,"t":"我要在曠野種上香柏樹、皂莢樹、番石榴樹，和野橄欖樹。我在沙漠要把松樹、杉樹，並黃楊樹一同栽植；","notes":[]},{"n":20,"t":"好叫人看見、知道、思想、明白；這是耶和華的手所做的，是以色列的聖者所造的。","notes":[]},{"n":21,"t":"耶和華對假神說：你們要呈上你們的案件；雅各的君說：你們要聲明你們確實的理由。","notes":[],"heads":["耶和華向假神挑戰"]},{"n":22,"t":"可以聲明，指示我們將來必遇的事，說明先前的是甚麼事，好叫我們思索，得知事的結局，或者把將來的事指示我們。","notes":[]},{"n":23,"t":"要說明後來的事，好叫我們知道你們是神。你們或降福，或降禍，使我們驚奇，一同觀看。","notes":[]},{"n":24,"t":"看哪，你們屬乎虛無；你們的作為也屬乎虛空。那選擇你們的是可憎惡的。","notes":[]},{"n":25,"t":"我從北方興起一人；他是求告我名的，從日出之地而來。他必臨到掌權的，好像臨到灰泥，彷彿窯匠踹泥一樣。","notes":[]},{"n":26,"t":"誰從起初指明這事，使我們知道呢？誰從先前說明，使我們說他不錯呢？誰也沒有指明；誰也沒有說明；誰也沒有聽見你們的話。","notes":[]},{"n":27,"t":"我首先對錫安說：看哪，我要將一位報好信息的賜給耶路撒冷。","notes":[]},{"n":28,"t":"我看的時候並沒有人；我問的時候，他們中間也沒有謀士可以回答一句。","notes":[]},{"n":29,"t":"看哪，他們和他們的工作都是虛空，且是虛無。他們所鑄的偶像都是風，都是虛的。","notes":[]}]},"42":{"heading":"耶和華的僕人","verses":[{"n":1,"t":"看哪，我的僕人－我所扶持所揀選、心裏所喜悅的！我已將我的靈賜給他；他必將公理傳給外邦。","notes":[]},{"n":2,"t":"他不喧嚷，不揚聲，也不使街上聽見他的聲音。","notes":[]},{"n":3,"t":"壓傷的蘆葦，他不折斷；將殘的燈火，他不吹滅。他憑真實將公理傳開。","notes":[]},{"n":4,"t":"他不灰心，也不喪膽，直到他在地上設立公理；海島都等候他的訓誨。","notes":[]},{"n":5,"t":"創造諸天，鋪張穹蒼，將地和地所出的一併鋪開，賜氣息給地上的眾人，又賜靈性給行在其上之人的神耶和華，他如此說：","notes":[]},{"n":6,"t":"我－耶和華憑公義召你，必攙扶你的手，保守你，使你作眾民的中保，作外邦人的光，","notes":["中保：原文是約"]},{"n":7,"t":"開瞎子的眼，領被囚的出牢獄，領坐黑暗的出監牢。","notes":[]},{"n":8,"t":"我是耶和華，這是我的名；我必不將我的榮耀歸給假神，也不將我的稱讚歸給雕刻的偶像。","notes":[]},{"n":9,"t":"看哪，先前的事已經成就，現在我將新事說明，這事未發以先，我就說給你們聽。","notes":[]},{"n":10,"t":"航海的和海中所有的，海島和其上的居民，都當向耶和華唱新歌，從地極讚美他。","notes":[],"heads":["頌讚之歌"]},{"n":11,"t":"曠野和其中的城邑，並基達人居住的村莊都當揚聲；西拉的居民當歡呼，在山頂上吶喊。","notes":[]},{"n":12,"t":"他們當將榮耀歸給耶和華，在海島中傳揚他的頌讚。","notes":[]},{"n":13,"t":"耶和華必像勇士出去，必像戰士激動熱心，要喊叫，大聲吶喊，要用大力攻擊仇敵。","notes":[]},{"n":14,"t":"我許久閉口不言，靜默不語；現在我要喊叫，像產難的婦人；我要急氣而喘哮。","notes":[],"heads":["神應許幫助他的子民"]},{"n":15,"t":"我要使大山小岡變為荒場，使其上的花草都枯乾；我要使江河變為洲島，使水池都乾涸。","notes":[]},{"n":16,"t":"我要引瞎子行不認識的道，領他們走不知道的路；在他們面前使黑暗變為光明，使彎曲變為平直。這些事我都要行，並不離棄他們。","notes":[]},{"n":17,"t":"倚靠雕刻的偶像，對鑄造的偶像說：你是我們的神；這等人要退後，全然蒙羞。","notes":[]},{"n":18,"t":"你們這耳聾的，聽吧！你們這眼瞎的，看吧！使你們能看見。","notes":[],"heads":["以色列人不受教益"]},{"n":19,"t":"誰比我的僕人眼瞎呢？誰比我差遣的使者耳聾呢？誰瞎眼像那與我和好的？誰瞎眼像耶和華的僕人呢？","notes":[]},{"n":20,"t":"你看見許多事卻不領會，耳朵開通卻不聽見。","notes":[]},{"n":21,"t":"耶和華因自己公義的緣故，喜歡使律法為大，為尊。","notes":["或譯：訓誨"]},{"n":22,"t":"但這百姓是被搶被奪的，都牢籠在坑中，隱藏在獄裏；他們作掠物，無人拯救，作擄物，無人說交還。","notes":[]},{"n":23,"t":"你們中間誰肯側耳聽此，誰肯留心而聽，以防將來呢？","notes":[]},{"n":24,"t":"誰將雅各交出當作擄物，將以色列交給搶奪的呢？豈不是耶和華嗎？就是我們所得罪的那位。他們不肯遵行他的道，也不聽從他的訓誨。","notes":[]},{"n":25,"t":"所以，他將猛烈的怒氣和爭戰的勇力傾倒在以色列的身上。在他四圍如火著起，他還不知道，燒著他，他也不介意。","notes":[]}]},"43":{"heading":"神應許拯救他的子民","verses":[{"n":1,"t":"雅各啊，創造你的耶和華，以色列啊，造成你的那位，現在如此說：你不要害怕！因為我救贖了你。我曾提你的名召你，你是屬我的。","notes":[]},{"n":2,"t":"你從水中經過，我必與你同在；你過江河，水必不漫過你；你從火中行過，必不被燒，火焰也不著在你身上。","notes":[]},{"n":3,"t":"因為我是耶和華－你的神，是以色列的聖者－你的救主；我已經使埃及作你的贖價，使古實和西巴代替你。","notes":[]},{"n":4,"t":"因我看你為寶為尊；又因我愛你，所以我使人代替你，使列邦人替換你的生命。","notes":[]},{"n":5,"t":"不要害怕，因我與你同在；我必領你的後裔從東方來，又從西方招聚你。","notes":[]},{"n":6,"t":"我要對北方說，交出來！對南方說，不要拘留！將我的眾子從遠方帶來，將我的眾女從地極領回，","notes":[]},{"n":7,"t":"就是凡稱為我名下的人，是我為自己的榮耀創造的，是我所做成，所造作的。","notes":[]},{"n":8,"t":"你要將有眼而瞎、有耳而聾的民都帶出來！","notes":[],"heads":["以色列是耶和華的見證人"]},{"n":9,"t":"任憑萬國聚集；任憑眾民會合。其中誰能將此聲明，並將先前的事說給我們聽呢？他們可以帶出見證來，自顯為是；或者他們聽見便說：這是真的。","notes":[]},{"n":10,"t":"耶和華說：你們是我的見證，我所揀選的僕人。既是這樣，便可以知道，且信服我，又明白我就是耶和華。在我以前沒有真神；在我以後也必沒有。","notes":["真：原文是造作的"]},{"n":11,"t":"惟有我是耶和華；除我以外沒有救主。","notes":[]},{"n":12,"t":"我曾指示，我曾拯救，我曾說明，並且在你們中間沒有別神。所以耶和華說：你們是我的見證。我也是神；","notes":[]},{"n":13,"t":"自從有日子以來，我就是神；誰也不能救人脫離我手。我要行事誰能阻止呢？","notes":[]},{"n":14,"t":"耶和華－你們的救贖主、以色列的聖者如此說：因你們的緣故，我已經打發人到巴比倫去；並且我要使迦勒底人如逃民，都坐自己喜樂的船下來。","notes":[],"heads":["逃離巴比倫"]},{"n":15,"t":"我是耶和華－你們的聖者，是創造以色列的，是你們的君王。","notes":[]},{"n":16,"t":"耶和華在滄海中開道，在大水中開路，","notes":[]},{"n":17,"t":"使車輛、馬匹、軍兵、勇士都出來，一同躺下，不再起來；他們滅沒，好像熄滅的燈火。","notes":[]},{"n":18,"t":"耶和華如此說：你們不要記念從前的事，也不要思想古時的事。","notes":[]},{"n":19,"t":"看哪，我要做一件新事；如今要發現，你們豈不知道嗎？我必在曠野開道路，在沙漠開江河。","notes":[]},{"n":20,"t":"野地的走獸必尊重我；野狗和鴕鳥也必如此。因我使曠野有水，使沙漠有河，好賜給我的百姓、我的選民喝。","notes":[]},{"n":21,"t":"這百姓是我為自己所造的，好述說我的美德。","notes":[]},{"n":22,"t":"雅各啊，你並沒有求告我；以色列啊，你倒厭煩我。","notes":[],"heads":["以色列人的罪惡"]},{"n":23,"t":"你沒有將你的羊帶來給我作燔祭，也沒有用祭物尊敬我；我沒有因供物使你服勞，也沒有因乳香使你厭煩。","notes":[]},{"n":24,"t":"你沒有用銀子為我買菖蒲，也沒有用祭物的脂油使我飽足；倒使我因你的罪惡服勞，使我因你的罪孽厭煩。","notes":[]},{"n":25,"t":"惟有我為自己的緣故塗抹你的過犯；我也不記念你的罪惡。","notes":[]},{"n":26,"t":"你要提醒我，你我可以一同辯論；你可以將你的理陳明，自顯為義。","notes":[]},{"n":27,"t":"你的始祖犯罪；你的師傅違背我。","notes":[]},{"n":28,"t":"所以，我要辱沒聖所的首領，使雅各成為咒詛，使以色列成為辱罵。","notes":[]}]},"44":{"heading":"耶和華是獨一的神","verses":[{"n":1,"t":"我的僕人雅各，我所揀選的以色列啊，現在你當聽。","notes":[]},{"n":2,"t":"造作你，又從你出胎造就你，並要幫助你的耶和華如此說：我的僕人雅各，我所揀選的耶書崙哪，不要害怕！","notes":[]},{"n":3,"t":"因為我要將水澆灌口渴的人，將河澆灌乾旱之地。我要將我的靈澆灌你的後裔，將我的福澆灌你的子孫。","notes":[]},{"n":4,"t":"他們要發生在草中，像溪水旁的柳樹。","notes":[]},{"n":5,"t":"這個要說：我是屬耶和華的；那個要以雅各的名自稱；又一個要親手寫：歸耶和華的，並自稱為以色列。","notes":["或譯：在手上寫歸耶和華"]},{"n":6,"t":"耶和華－以色列的君，以色列的救贖主－萬軍之耶和華如此說：我是首先的，我是末後的；除我以外再沒有真神。","notes":[]},{"n":7,"t":"自從我設立古時的民，誰能像我宣告，並且指明，又為自己陳說呢？讓他將未來的事和必成的事說明。","notes":[]},{"n":8,"t":"你們不要恐懼，也不要害怕。我豈不是從上古就說明指示你們嗎？並且你們是我的見證！除我以外，豈有真神嗎？誠然沒有磐石，我不知道一個！","notes":[]},{"n":9,"t":"製造雕刻偶像的盡都虛空；他們所喜悅的都無益處；他們的見證無所看見，無所知曉，他們便覺羞愧。","notes":[],"heads":["虛無的偶像"]},{"n":10,"t":"誰製造神像，鑄造無益的偶像？","notes":[]},{"n":11,"t":"看哪，他的同伴都必羞愧。工匠也不過是人，任他們聚會，任他們站立，都必懼怕，一同羞愧。","notes":[]},{"n":12,"t":"鐵匠把鐵在火炭中燒熱，用鎚打鐵器，用他有力的膀臂錘成；他飢餓而無力，不喝水而發倦。","notes":[]},{"n":13,"t":"木匠拉線，用筆劃出樣子，用鉋子鉋成形狀，用圓尺劃了模樣，仿照人的體態，做成人形，好住在房屋中。","notes":[]},{"n":14,"t":"他砍伐香柏樹，又取柞樹和橡樹，在樹林中選定了一棵。他栽種松樹，得雨長養。","notes":["或譯：青桐"]},{"n":15,"t":"這樹，人可用以燒火；他自己取些烤火，又燒著烤餅，而且做神像跪拜，做雕刻的偶像向它叩拜。","notes":[]},{"n":16,"t":"他把一分燒在火中，把一分烤肉吃飽。自己烤火說：「啊哈，我暖和了，我見火了。」","notes":[]},{"n":17,"t":"他用剩下的做了一神，就是雕刻的偶像。他向這偶像俯伏叩拜，禱告它說：「求你拯救我，因你是我的神。」","notes":[]},{"n":18,"t":"他們不知道，也不思想；因為耶和華閉住他們的眼，不能看見，塞住他們的心，不能明白。","notes":[]},{"n":19,"t":"誰心裏也不醒悟，也沒有知識，沒有聰明，能說：「我曾拿一分在火中燒了，在炭火上烤過餅；我也烤過肉吃。這剩下的，我豈要做可憎的物嗎？我豈可向木墩子叩拜呢？」","notes":[]},{"n":20,"t":"他以灰為食，心中昏迷，使他偏邪，他不能自救，也不能說：「我右手中豈不是有虛謊嗎？」","notes":[]},{"n":21,"t":"雅各，以色列啊，你是我的僕人，要記念這些事。以色列啊，你是我的僕人，我造就你必不忘記你。","notes":[],"heads":["耶和華是創造主也是救贖主"]},{"n":22,"t":"我塗抹了你的過犯，像厚雲消散；我塗抹了你的罪惡，如薄雲滅沒。你當歸向我，因我救贖了你。","notes":[]},{"n":23,"t":"諸天哪，應當歌唱，因為耶和華做成這事。地的深處啊，應當歡呼；眾山應當發聲歌唱；樹林和其中所有的樹都當如此！因為耶和華救贖了雅各，並要因以色列榮耀自己。","notes":[]},{"n":24,"t":"從你出胎，造就你的救贖主－耶和華如此說：我－耶和華是創造萬物的，是獨自鋪張諸天、鋪開大地的。誰與我同在呢？","notes":[]},{"n":25,"t":"使說假話的兆頭失效，使占卜的癲狂，使智慧人退後，使他的知識變為愚拙；","notes":[]},{"n":26,"t":"使我僕人的話語立定，我使者的謀算成就。論到耶路撒冷說：必有人居住；論到猶大的城邑說：必被建造，其中的荒場我也必興起。","notes":[]},{"n":27,"t":"對深淵說：你乾了吧！我也要使你的江河乾涸。","notes":[]},{"n":28,"t":"論塞魯士說：他是我的牧人，必成就我所喜悅的，必下令建造耶路撒冷，發命立穩聖殿的根基。","notes":[]}]},"45":{"heading":"耶和華立塞魯士為王","verses":[{"n":1,"t":"我－耶和華所膏的塞魯士；我攙扶他的右手，使列國降伏在他面前。我也要放鬆列王的腰帶，使城門在他面前敞開，不得關閉。我對他如此說：","notes":[]},{"n":2,"t":"我必在你前面行，修平崎嶇之地。我必打破銅門，砍斷鐵閂。","notes":[]},{"n":3,"t":"我要將暗中的寶物和隱密的財寶賜給你，使你知道提名召你的，就是我－耶和華、以色列的神。","notes":[]},{"n":4,"t":"因我僕人雅各，我所揀選以色列的緣故，我就提名召你；你雖不認識我，我也加給你名號。","notes":[]},{"n":5,"t":"我是耶和華，在我以外並沒有別神；除了我以外再沒有神。你雖不認識我，我必給你束腰。","notes":[]},{"n":6,"t":"從日出之地到日落之處使人都知道除了我以外，沒有別神。我是耶和華；在我以外並沒有別神。","notes":[]},{"n":7,"t":"我造光，又造暗；我施平安，又降災禍；造作這一切的是我－耶和華。","notes":[]},{"n":8,"t":"諸天哪，自上而滴，穹蒼降下公義；地面開裂，產出救恩，使公義一同發生；這都是我－耶和華所造的。","notes":[]},{"n":9,"t":"禍哉，那與造他的主爭論的！他不過是地上瓦片中的一塊瓦片。泥土豈可對摶弄它的說：你做甚麼呢？所做的物豈可說：你沒有手呢？","notes":[],"heads":["創造和歷史的主宰"]},{"n":10,"t":"禍哉，那對父親說：你生的是甚麼呢？或對母親說：你產的是甚麼呢？","notes":["原文是婦人"]},{"n":11,"t":"耶和華－以色列的聖者，就是造就以色列的如此說：將來的事，你們可以問我；至於我的眾子，並我手的工作，你們可以求我命定。","notes":["原文是吩咐我"]},{"n":12,"t":"我造地，又造人在地上。我親手鋪張諸天；天上萬象也是我所命定的。","notes":[]},{"n":13,"t":"我憑公義興起塞魯士，又要修直他一切道路。他必建造我的城，釋放我被擄的民；不是為工價，也不是為賞賜。這是萬軍之耶和華說的。","notes":["原文是他"]},{"n":14,"t":"耶和華如此說：埃及勞碌得來的和古實的貨物必歸你；身量高大的西巴人必投降你，也要屬你。他們必帶著鎖鍊過來隨從你，又向你下拜，祈求你說：神真在你們中間，此外再沒有別神；再沒有別的神。","notes":[]},{"n":15,"t":"救主－以色列的神啊，你實在是自隱的神。","notes":[]},{"n":16,"t":"凡製造偶像的都必抱愧蒙羞，都要一同歸於慚愧。","notes":[]},{"n":17,"t":"惟有以色列必蒙耶和華的拯救，得永遠的救恩。你們必不蒙羞，也不抱愧，直到永世無盡。","notes":[]},{"n":18,"t":"創造諸天的耶和華，製造成全大地的神，他創造堅定大地，並非使地荒涼，是要給人居住。他如此說：我是耶和華，再沒有別神。","notes":[]},{"n":19,"t":"我沒有在隱密黑暗之地說話；我沒有對雅各的後裔說：你們尋求我是徒然的。我－耶和華所講的是公義，所說的是正直。","notes":[]},{"n":20,"t":"你們從列國逃脫的人，要一同聚集前來。那些抬著雕刻木偶、禱告不能救人之神的，毫無知識。","notes":[],"heads":["天地之主和巴比倫的偶像"]},{"n":21,"t":"你們要述說陳明你們的理，讓他們彼此商議。誰從古時指明？誰從上古述說？不是我－耶和華嗎？除了我以外，再沒有神；我是公義的神，又是救主；除了我以外，再沒有別神。","notes":[]},{"n":22,"t":"地極的人都當仰望我，就必得救；因為我是神，再沒有別神。","notes":[]},{"n":23,"t":"我指著自己起誓，我口所出的話是憑公義，並不反回：萬膝必向我跪拜；萬口必憑我起誓。","notes":[]},{"n":24,"t":"人論我說，公義、能力，惟獨在乎耶和華；人都必歸向他。凡向他發怒的必至蒙羞。","notes":[]},{"n":25,"t":"以色列的後裔都必因耶和華得稱為義，並要誇耀。","notes":[]}]},"46":{"heading":"","verses":[{"n":1,"t":"彼勒屈身，尼波彎腰；巴比倫的偶像馱在獸和牲畜上。他們所抬的如今成了重馱，使牲畜疲乏，","notes":[]},{"n":2,"t":"都一同彎腰屈身，不能保全重馱，自己倒被擄去。","notes":[]},{"n":3,"t":"雅各家，以色列家一切餘剩的要聽我言：你們自從生下，就蒙我保抱，自從出胎，便蒙我懷搋。","notes":[]},{"n":4,"t":"直到你們年老，我仍這樣；直到你們髮白，我仍懷搋。我已造作，也必保抱；我必懷抱，也必拯救。","notes":[]},{"n":5,"t":"你們將誰與我相比，與我同等，可以與我比較，使我們相同呢？","notes":[]},{"n":6,"t":"那從囊中抓金子，用天平平銀子的人，雇銀匠製造神像，他們又俯伏，又叩拜。","notes":[]},{"n":7,"t":"他們將神像抬起，扛在肩上，安置在定處，它就站立，不離本位；人呼求它，它不能答應，也不能救人脫離患難。","notes":[]},{"n":8,"t":"你們當想念這事，自己作大丈夫。悖逆的人哪，要心裏思想。","notes":[]},{"n":9,"t":"你們要追念上古的事。因為我是神，並無別神；我是神，再沒有能比我的。","notes":[]},{"n":10,"t":"我從起初指明末後的事，從古時言明未成的事，說：我的籌算必立定；凡我所喜悅的，我必成就。","notes":[]},{"n":11,"t":"我召鷙鳥從東方來，召那成就我籌算的人從遠方來。我已說出，也必成就；我已謀定，也必做成。","notes":[]},{"n":12,"t":"你們這些心中頑梗、遠離公義的，當聽我言。","notes":[]},{"n":13,"t":"我使我的公義臨近，必不遠離。我的救恩必不遲延；我要為以色列－我的榮耀，在錫安施行救恩。","notes":[]}]},"47":{"heading":"審判巴比倫","verses":[{"n":1,"t":"巴比倫的處女啊，下來坐在塵埃；迦勒底的閨女啊，沒有寶座，要坐在地上；因為你不再稱為柔弱嬌嫩的。","notes":[]},{"n":2,"t":"要用磨磨麵，揭去帕子，脫去長衣，露腿河。","notes":[]},{"n":3,"t":"你的下體必被露出；你的醜陋必被看見。我要報仇，誰也不寬容。","notes":[]},{"n":4,"t":"我們救贖主的名是萬軍之耶和華－以色列的聖者。","notes":[]},{"n":5,"t":"迦勒底的閨女啊，你要默然靜坐，進入暗中，因為你不再稱為列國的主母。","notes":[]},{"n":6,"t":"我向我的百姓發怒，使我的產業被褻瀆，將他們交在你手中，你毫不憐憫他們，把極重的軛加在老年人身上。","notes":[]},{"n":7,"t":"你自己說：我必永為主母，所以你不將這事放在心上，也不思想這事的結局。","notes":[]},{"n":8,"t":"你這專好宴樂、安然居住的，現在當聽這話。你心中說：惟有我，除我以外再沒有別的。我必不致寡居，也不遭喪子之事。","notes":[]},{"n":9,"t":"哪知，喪子、寡居這兩件事在一日轉眼之間必臨到你；正在你多行邪術、廣施符咒的時候，這兩件事必全然臨到你身上。","notes":[]},{"n":10,"t":"你素來倚仗自己的惡行，說：無人看見我。你的智慧聰明使你偏邪，並且你心裏說：惟有我，除我以外再沒有別的。","notes":[]},{"n":11,"t":"因此，禍患要臨到你身；你不知何時發現，災害落在你身上，你也不能除掉；所不知道的毀滅也必忽然臨到你身。","notes":["或譯：如何驅逐"]},{"n":12,"t":"站起來吧！用你從幼年勞神施行的符咒和你許多的邪術；或者可得益處，或者可得強勝。","notes":[]},{"n":13,"t":"你籌劃太多，以致疲倦。讓那些觀天象的，看星宿的，在月朔說預言的，都站起來，救你脫離所要臨到你的事。","notes":[]},{"n":14,"t":"他們要像碎稭被火焚燒，不能救自己脫離火焰之力；這火並非可烤的炭火，也不是可以坐在其前的火。","notes":[]},{"n":15,"t":"你所勞神的事都要這樣與你無益；從幼年與你貿易的也都各奔各鄉，無人救你。","notes":[]}]},"48":{"heading":"神掌管未來","verses":[{"n":1,"t":"雅各家，稱為以色列名下，從猶大水源出來的，當聽我言！你們指著耶和華的名起誓，提說以色列的神，卻不憑誠實，不憑公義。","notes":[]},{"n":2,"t":"他們自稱為聖城的人，所倚靠的是名為萬軍之耶和華－以色列的神。","notes":[]},{"n":3,"t":"主說：早先的事，我從古時說明，已經出了我的口，也是我所指示的；我忽然行做，事便成就。","notes":[]},{"n":4,"t":"因為我素來知道你是頑梗的－你的頸項是鐵的；你的額是銅的。","notes":[]},{"n":5,"t":"所以，我從古時將這事給你說明，在未成以先指示你，免得你說：這些事是我的偶像所行的，是我雕刻的偶像和我鑄造的偶像所命定的。","notes":[]},{"n":6,"t":"你已經聽見，現在要看見這一切；你不說明嗎？從今以後，我將新事，就是你所不知道的隱密事指示你。","notes":[]},{"n":7,"t":"這事是現今造的，並非從古就有；在今日以先，你也未曾聽見，免得你說：這事我早已知道了。","notes":[]},{"n":8,"t":"你未曾聽見，未曾知道；你的耳朵從來未曾開通。我原知道你行事極其詭詐，你自從出胎以來，便稱為悖逆的。","notes":[]},{"n":9,"t":"我為我的名暫且忍怒，為我的頌讚向你容忍，不將你剪除。","notes":[]},{"n":10,"t":"我熬煉你，卻不像熬煉銀子；你在苦難的爐中，我揀選你。","notes":[]},{"n":11,"t":"我為自己的緣故必行這事，我焉能使我的名被褻瀆？我必不將我的榮耀歸給假神。","notes":[]},{"n":12,"t":"雅各－我所選召的以色列啊，當聽我言：我是耶和華，我是首先的，也是末後的。","notes":[],"heads":["耶和華揀選塞魯士為領導者"]},{"n":13,"t":"我手立了地的根基；我右手鋪張諸天；我一招呼便都立住。","notes":[]},{"n":14,"t":"你們都當聚集而聽，他們內中誰說過這些事？耶和華所愛的人必向巴比倫行他所喜悅的事；他的膀臂也要加在迦勒底人身上。","notes":["或譯：偶像"]},{"n":15,"t":"惟有我曾說過，我又選召他，領他來，他的道路就必亨通。","notes":[]},{"n":16,"t":"你們要就近我來聽這話：我從起頭並未曾在隱密處說話；自從有這事，我就在那裏。現在，主耶和華差遣我和他的靈來。","notes":["或譯：耶和華和他的靈差遣我來"]},{"n":17,"t":"耶和華－你的救贖主，以色列的聖者如此說：我是耶和華－你的神，教訓你，使你得益處，引導你所當行的路。","notes":[],"heads":["耶和華對他子民的計劃"]},{"n":18,"t":"甚願你素來聽從我的命令！你的平安就如河水；你的公義就如海浪。","notes":[]},{"n":19,"t":"你的後裔也必多如海沙；你腹中所生的也必多如沙粒。他的名在我面前必不剪除，也不滅絕。","notes":[]},{"n":20,"t":"你們要從巴比倫出來，從迦勒底人中逃脫，以歡呼的聲音傳揚說：耶和華救贖了他的僕人雅各！你們要將這事宣揚到地極。","notes":[]},{"n":21,"t":"耶和華引導他們經過沙漠。他們並不乾渴；他為他們使水從磐石而流，分裂磐石，水就湧出。","notes":[]},{"n":22,"t":"耶和華說：惡人必不得平安！","notes":[]}]},"49":{"heading":"外邦之光","verses":[{"n":1,"t":"眾海島啊，當聽我言！遠方的眾民哪，留心而聽！自我出胎，耶和華就選召我；自出母腹，他就提我的名。","notes":[]},{"n":2,"t":"他使我的口如快刀，將我藏在他手蔭之下；又使我成為磨亮的箭，將我藏在他箭袋之中；","notes":[]},{"n":3,"t":"對我說：你是我的僕人以色列；我必因你得榮耀。","notes":[]},{"n":4,"t":"我卻說：我勞碌是徒然；我盡力是虛無虛空。然而，我當得的理必在耶和華那裏；我的賞賜必在我神那裏。","notes":[]},{"n":5,"t":"耶和華從我出胎，造就我作他的僕人，要使雅各歸向他，使以色列到他那裏聚集。原來耶和華看我為尊貴；我的神也成為我的力量。","notes":[]},{"n":6,"t":"現在他說：你作我的僕人，使雅各眾支派復興，使以色列中得保全的歸回尚為小事，我還要使你作外邦人的光，叫你施行我的救恩，直到地極。","notes":[]},{"n":7,"t":"救贖主－以色列的聖者耶和華對那被人所藐視、本國所憎惡、官長所虐待的如此說：君王要看見就站起，首領也要下拜；都因信實的耶和華，就是揀選你－以色列的聖者。","notes":[]},{"n":8,"t":"耶和華如此說：在悅納的時候，我應允了你；在拯救的日子，我濟助了你。我要保護你，使你作眾民的中保；復興遍地，使人承受荒涼之地為業。","notes":["中保：原文是約"],"heads":["耶路撒冷的復興"]},{"n":9,"t":"對那被捆綁的人說：出來吧！對那在黑暗的人說：顯露吧！他們在路上必得飲食，在一切淨光的高處必有食物。","notes":[]},{"n":10,"t":"不飢不渴，炎熱和烈日必不傷害他們；因為憐恤他們的必引導他們，領他們到水泉旁邊。","notes":[]},{"n":11,"t":"我必使我的眾山成為大道；我的大路也被修高。","notes":[]},{"n":12,"t":"看哪，這些從遠方來；這些從北方、從西方來；這些從秦國來。","notes":["原文是希尼"]},{"n":13,"t":"諸天哪，應當歡呼！大地啊，應當快樂！眾山哪，應當發聲歌唱！因為耶和華已經安慰他的百姓，也要憐恤他困苦之民。","notes":[]},{"n":14,"t":"錫安說：耶和華離棄了我；主忘記了我。","notes":[]},{"n":15,"t":"婦人焉能忘記她吃奶的嬰孩，不憐恤她所生的兒子？即或有忘記的，我卻不忘記你。","notes":[]},{"n":16,"t":"看哪，我將你銘刻在我掌上；你的牆垣常在我眼前。","notes":[]},{"n":17,"t":"你的兒女必急速歸回；毀壞你的，使你荒廢的，必都離你出去，","notes":[]},{"n":18,"t":"你舉目向四方觀看；他們都聚集來到你這裏。耶和華說：我指著我的永生起誓：你必要以他們為妝飾佩戴，以他們為華帶束腰，像新婦一樣。","notes":[]},{"n":19,"t":"至於你荒廢淒涼之處，並你被毀壞之地，現今眾民居住必顯為太窄；吞滅你的必離你遙遠。","notes":[]},{"n":20,"t":"你必聽見喪子之後所生的兒女說：這地方我居住太窄，求你給我地方居住。","notes":[]},{"n":21,"t":"那時你心裏必說：我既喪子獨居，是被擄的，漂流在外。誰給我生這些？誰將這些養大呢？撇下我一人獨居的時候，這些在哪裏呢？","notes":[]},{"n":22,"t":"主耶和華如此說：我必向列國舉手，向萬民豎立大旗；他們必將你的眾子懷中抱來，將你的眾女肩上扛來。","notes":[]},{"n":23,"t":"列王必作你的養父；王后必作你的乳母。他們必將臉伏地，向你下拜，並舔你腳上的塵土。你便知道我是耶和華；等候我的必不致羞愧。","notes":[]},{"n":24,"t":"勇士搶去的豈能奪回？該擄掠的豈能解救嗎？","notes":[]},{"n":25,"t":"但耶和華如此說：就是勇士所擄掠的，也可以奪回；強暴人所搶的，也可以解救。與你相爭的，我必與他相爭；我要拯救你的兒女。","notes":[]},{"n":26,"t":"並且我必使那欺壓你的吃自己的肉，也要以自己的血喝醉，好像喝甜酒一樣。凡有血氣的必都知道我－耶和華是你的救主，是你的救贖主，是雅各的大能者。","notes":[]}]},"50":{"heading":"耶和華僕人的順服","verses":[{"n":1,"t":"耶和華如此說：我休你們的母親，休書在哪裏呢？我將你們賣給我哪一個債主呢？你們被賣，是因你們的罪孽；你們的母親被休，是因你們的過犯。","notes":[]},{"n":2,"t":"我來的時候，為何無人等候呢？我呼喚的時候，為何無人答應呢？我的膀臂豈是縮短、不能救贖嗎？我豈無拯救之力嗎？看哪，我一斥責，海就乾了；我使江河變為曠野；其中的魚因無水腥臭，乾渴而死。","notes":[]},{"n":3,"t":"我使諸天以黑暗為衣服，以麻布為遮蓋。","notes":[]},{"n":4,"t":"主耶和華賜我受教者的舌頭，使我知道怎樣用言語扶助疲乏的人。主每早晨提醒，提醒我的耳朵，使我能聽，像受教者一樣。","notes":[]},{"n":5,"t":"主耶和華開通我的耳朵；我並沒有違背，也沒有退後。","notes":[]},{"n":6,"t":"人打我的背，我任他打；人拔我腮頰的鬍鬚，我由他拔；人辱我，吐我，我並不掩面。","notes":[]},{"n":7,"t":"主耶和華必幫助我，所以我不抱愧。我硬著臉面好像堅石；我也知道我必不致蒙羞。","notes":[]},{"n":8,"t":"稱我為義的與我相近；誰與我爭論，可以與我一同站立；誰與我作對，可以就近我來。","notes":[]},{"n":9,"t":"主耶和華要幫助我；誰能定我有罪呢？他們都像衣服漸漸舊了，為蛀蟲所咬。","notes":[]},{"n":10,"t":"你們中間誰是敬畏耶和華、聽從他僕人之話的？這人行在暗中，沒有亮光。當倚靠耶和華的名，仗賴自己的神。","notes":[]},{"n":11,"t":"凡你們點火，用火把圍繞自己的可以行在你們的火焰裏，並你們所點的火把中。這是我手所定的：你們必躺在悲慘之中。","notes":[]}]},"51":{"heading":"安慰耶路撒冷的話","verses":[{"n":1,"t":"你們這追求公義、尋求耶和華的，當聽我言！你們要追想被鑿而出的磐石，被挖而出的巖穴。","notes":[]},{"n":2,"t":"要追想你們的祖宗亞伯拉罕和生養你們的撒拉；因為亞伯拉罕獨自一人的時候，我選召他，賜福與他，使他人數增多。","notes":[]},{"n":3,"t":"耶和華已經安慰錫安和錫安一切的荒場，使曠野像伊甸，使沙漠像耶和華的園囿；在其中必有歡喜、快樂、感謝，和歌唱的聲音。","notes":[]},{"n":4,"t":"我的百姓啊，要向我留心；我的國民哪，要向我側耳；因為訓誨必從我而出；我必堅定我的公理為萬民之光。","notes":[]},{"n":5,"t":"我的公義臨近；我的救恩發出。我的膀臂要審判萬民；海島都要等候我，倚賴我的膀臂。","notes":[]},{"n":6,"t":"你們要向天舉目，觀看下地；因為天必像煙雲消散，地必如衣服漸漸舊了；其上的居民也要如此死亡。惟有我的救恩永遠長存；我的公義也不廢掉。","notes":["如此死亡：或譯像蠓蟲死亡"]},{"n":7,"t":"知道公義、將我訓誨存在心中的民，要聽我言！不要怕人的辱罵，也不要因人的毀謗驚惶。","notes":[]},{"n":8,"t":"因為蛀蟲必咬他們，好像咬衣服；蟲子必咬他們，如同咬羊絨。惟有我的公義永遠長存，我的救恩直到萬代。","notes":[]},{"n":9,"t":"耶和華的膀臂啊，興起！興起！以能力為衣穿上，像古時的年日、上古的世代興起一樣。從前砍碎拉哈伯、刺透大魚的，不是你嗎？","notes":[]},{"n":10,"t":"使海與深淵的水乾涸、使海的深處變為贖民經過之路的，不是你嗎？","notes":[]},{"n":11,"t":"耶和華救贖的民必歸回，歌唱來到錫安；永樂必歸到他們的頭上。他們必得著歡喜快樂；憂愁歎息盡都逃避。","notes":[]},{"n":12,"t":"惟有我，是安慰你們的。你是誰，竟怕那必死的人？怕那要變如草的世人？","notes":[]},{"n":13,"t":"卻忘記鋪張諸天、立定地基、創造你的耶和華？又因欺壓者圖謀毀滅要發的暴怒，整天害怕，其實那欺壓者的暴怒在哪裏呢？","notes":[]},{"n":14,"t":"被擄去的快得釋放，必不死而下坑；他的食物也不致缺乏。","notes":[]},{"n":15,"t":"我是耶和華－你的神－攪動大海，使海中的波浪匉訇－萬軍之耶和華是我的名。","notes":[]},{"n":16,"t":"我將我的話傳給你，用我的手影遮蔽你，為要栽定諸天，立定地基，又對錫安說：你是我的百姓。","notes":[]},{"n":17,"t":"耶路撒冷啊，興起！興起！站起來！你從耶和華手中喝了他忿怒之杯，喝了那使人東倒西歪的爵，以致喝盡。","notes":[],"heads":["耶路撒冷苦難的終結"]},{"n":18,"t":"她所生育的諸子中，沒有一個引導她的；她所養大的諸子中，沒有一個攙扶她的。","notes":[]},{"n":19,"t":"荒涼、毀滅、饑荒、刀兵，這幾樣臨到你，誰為你舉哀？我如何能安慰你呢？","notes":[]},{"n":20,"t":"你的眾子發昏，在各市口上躺臥，好像黃羊在網羅之中，都滿了耶和華的忿怒－你神的斥責。","notes":[]},{"n":21,"t":"因此，你這困苦卻非因酒而醉的，要聽我言。","notes":[]},{"n":22,"t":"你的主耶和華－就是為他百姓辨屈的神如此說：看哪，我已將那使人東倒西歪的杯，就是我忿怒的爵，從你手中接過來；你必不致再喝。","notes":[]},{"n":23,"t":"我必將這杯遞在苦待你的人手中；他們曾對你說：你屈身，由我們踐踏過去吧！你便以背為地，好像街市，任人經過。","notes":[]}]},"52":{"heading":"神要拯救耶路撒冷","verses":[{"n":1,"t":"錫安哪，興起！興起！披上你的能力！聖城耶路撒冷啊，穿上你華美的衣服！因為從今以後，未受割禮、不潔淨的必不再進入你中間。","notes":[]},{"n":2,"t":"耶路撒冷啊，要抖下塵土！起來坐在位上！錫安被擄的居民哪，要解開你頸項的鎖鍊！","notes":["原文是女子"]},{"n":3,"t":"耶和華如此說：「你們是無價被賣的，也必無銀被贖。","notes":[]},{"n":4,"t":"主耶和華如此說：起先我的百姓下到埃及，在那裏寄居，又有亞述人無故欺壓他們。","notes":[]},{"n":5,"t":"耶和華說：我的百姓既是無價被擄去，如今我在這裏做甚麼呢？耶和華說：轄制他們的人呼叫，我的名整天受褻瀆。","notes":[]},{"n":6,"t":"所以，我的百姓必知道我的名；到那日他們必知道說這話的就是我。看哪，是我！」","notes":[]},{"n":7,"t":"那報佳音，傳平安，報好信，傳救恩的，對錫安說：你的神作王了！這人的腳登山何等佳美！","notes":[]},{"n":8,"t":"聽啊，你守望之人的聲音，他們揚起聲來，一同歌唱；因為耶和華歸回錫安的時候，他們必親眼看見。","notes":[]},{"n":9,"t":"耶路撒冷的荒場啊，要發起歡聲，一同歌唱；因為耶和華安慰了他的百姓，救贖了耶路撒冷。","notes":[]},{"n":10,"t":"耶和華在萬國眼前露出聖臂；地極的人都看見我們神的救恩了。","notes":[]},{"n":11,"t":"你們離開吧！離開吧！從巴比倫出來。不要沾不潔淨的物；要從其中出來。你們扛抬耶和華器皿的人哪，務要自潔。","notes":[]},{"n":12,"t":"你們出來必不致急忙，也不致奔逃。因為，耶和華必在你們前頭行；以色列的神必作你們的後盾。","notes":[]},{"n":13,"t":"我的僕人行事必有智慧，必被高舉上升，且成為至高。","notes":["或譯：行事通達"],"heads":["受苦的僕人"]},{"n":14,"t":"許多人因他驚奇；他的面貌比別人憔悴；他的形容比世人枯槁。","notes":["原文是你"]},{"n":15,"t":"這樣，他必洗淨許多國民；君王要向他閉口。因所未曾傳與他們的，他們必看見；未曾聽見的，他們要明白。","notes":["或譯：鼓動"]}]},"53":{"heading":"","verses":[{"n":1,"t":"我們所傳的有誰信呢？耶和華的膀臂向誰顯露呢？","notes":["或譯：所傳與我們的"]},{"n":2,"t":"他在耶和華面前生長如嫩芽，像根出於乾地。他無佳形美容；我們看見他的時候，也無美貌使我們羨慕他。","notes":[]},{"n":3,"t":"他被藐視，被人厭棄；多受痛苦，常經憂患。他被藐視，好像被人掩面不看的一樣；我們也不尊重他。","notes":[]},{"n":4,"t":"他誠然擔當我們的憂患，背負我們的痛苦；我們卻以為他受責罰，被神擊打苦待了。","notes":[]},{"n":5,"t":"哪知他為我們的過犯受害，為我們的罪孽壓傷。因他受的刑罰，我們得平安；因他受的鞭傷，我們得醫治。","notes":[]},{"n":6,"t":"我們都如羊走迷；各人偏行己路；耶和華使我們眾人的罪孽都歸在他身上。","notes":[]},{"n":7,"t":"他被欺壓，在受苦的時候卻不開口；他像羊羔被牽到宰殺之地，又像羊在剪毛的人手下無聲，他也是這樣不開口。","notes":["或譯：他受欺壓，卻自卑不開口"]},{"n":8,"t":"因受欺壓和審判，他被奪去，至於他同世的人，誰想他受鞭打、從活人之地被剪除，是因我百姓的罪過呢？","notes":[]},{"n":9,"t":"他雖然未行強暴，口中也沒有詭詐，人還使他與惡人同埋；誰知死的時候與財主同葬。","notes":[]},{"n":10,"t":"耶和華卻定意將他壓傷，使他受痛苦。耶和華以他為贖罪祭。他必看見後裔，並且延長年日。耶和華所喜悅的事必在他手中亨通。","notes":["或譯：喜悅","或譯：他獻本身為贖罪祭"]},{"n":11,"t":"他必看見自己勞苦的功效，便心滿意足。有許多人因認識我的義僕得稱為義；並且他要擔當他們的罪孽。","notes":[]},{"n":12,"t":"所以，我要使他與位大的同分，與強盛的均分擄物。因為他將命傾倒，以致於死；他也被列在罪犯之中。他卻擔當多人的罪，又為罪犯代求。","notes":[]}]},"54":{"heading":"耶和華對以色列的愛","verses":[{"n":1,"t":"你這不懷孕、不生養的要歌唱；你這未曾經過產難的要發聲歌唱，揚聲歡呼；因為沒有丈夫的比有丈夫的兒女更多。這是耶和華說的。","notes":[]},{"n":2,"t":"要擴張你帳幕之地，張大你居所的幔子，不要限止；要放長你的繩子，堅固你的橛子。","notes":[]},{"n":3,"t":"因為你要向左向右開展；你的後裔必得多國為業，又使荒涼的城邑有人居住。","notes":[]},{"n":4,"t":"不要懼怕，因你必不致蒙羞；也不要抱愧，因你必不致受辱。你必忘記幼年的羞愧，不再記念你寡居的羞辱。","notes":[]},{"n":5,"t":"因為造你的是你的丈夫；萬軍之耶和華是他的名。救贖你的是以色列的聖者；他必稱為全地之神。","notes":[]},{"n":6,"t":"耶和華召你，如召被離棄心中憂傷的妻，就是幼年所娶被棄的妻。這是你神所說的。","notes":[]},{"n":7,"t":"我離棄你不過片時，卻要施大恩將你收回。","notes":[]},{"n":8,"t":"我的怒氣漲溢，頃刻之間向你掩面，卻要以永遠的慈愛憐恤你。這是耶和華－你的救贖主說的。","notes":[]},{"n":9,"t":"這事在我好像挪亞的洪水。我怎樣起誓不再使挪亞的洪水漫過遍地，我也照樣起誓不再向你發怒，也不斥責你。","notes":[]},{"n":10,"t":"大山可以挪開，小山可以遷移；但我的慈愛必不離開你；我平安的約也不遷移。這是憐恤你的耶和華說的。","notes":[]},{"n":11,"t":"你這受困苦、被風飄蕩不得安慰的人哪，我必以彩色安置你的石頭，以藍寶石立定你的根基；","notes":[],"heads":["耶路撒冷的將來"]},{"n":12,"t":"又以紅寶石造你的女牆，以紅玉造你的城門，以寶石造你四圍的邊界。","notes":["或譯：外郭"]},{"n":13,"t":"你的兒女都要受耶和華的教訓；你的兒女必大享平安。","notes":[]},{"n":14,"t":"你必因公義得堅立，必遠離欺壓，不致害怕；你必遠離驚嚇，驚嚇必不臨近你。","notes":[]},{"n":15,"t":"即或有人聚集，卻不由於我；凡聚集攻擊你的，必因你仆倒。","notes":["或譯：投降你"]},{"n":16,"t":"吹噓炭火、打造合用器械的鐵匠是我所造；殘害人、行毀滅的也是我所造。","notes":[]},{"n":17,"t":"凡為攻擊你造成的器械必不利用；凡在審判時興起用舌攻擊你的，你必定他為有罪。這是耶和華僕人的產業，是他們從我所得的義。這是耶和華說的。","notes":[]}]},"55":{"heading":"神要施憐憫","verses":[{"n":1,"t":"你們一切乾渴的都當就近水來；沒有銀錢的也可以來。你們都來，買了吃；不用銀錢，不用價值，也來買酒和奶。","notes":[]},{"n":2,"t":"你們為何花錢買那不足為食物的？用勞碌得來的買那不使人飽足的呢？你們要留意聽我的話就能吃那美物，得享肥甘，心中喜樂。","notes":["原文是平銀"]},{"n":3,"t":"你們當就近我來；側耳而聽，就必得活。我必與你們立永約，就是應許大衛那可靠的恩典。","notes":[]},{"n":4,"t":"我已立他作萬民的見證，為萬民的君王和司令。","notes":[]},{"n":5,"t":"你素不認識的國民，你也必召來；素不認識你的國民也必向你奔跑，都因耶和華－你的神以色列的聖者，因為他已經榮耀你。","notes":[]},{"n":6,"t":"當趁耶和華可尋找的時候尋找他，相近的時候求告他。","notes":[]},{"n":7,"t":"惡人當離棄自己的道路；不義的人當除掉自己的意念。歸向耶和華，耶和華就必憐恤他；當歸向我們的神，因為神必廣行赦免。","notes":[]},{"n":8,"t":"耶和華說：我的意念非同你們的意念；我的道路非同你們的道路。","notes":[]},{"n":9,"t":"天怎樣高過地，照樣，我的道路高過你們的道路；我的意念高過你們的意念。","notes":[]},{"n":10,"t":"雨雪從天而降，並不返回，卻滋潤地土，使地上發芽結實，使撒種的有種，使要吃的有糧。","notes":[]},{"n":11,"t":"我口所出的話也必如此，決不徒然返回，卻要成就我所喜悅的，在我發他去成就的事上必然亨通。","notes":["發他去成就：或譯所命定"]},{"n":12,"t":"你們必歡歡喜喜而出來，平平安安蒙引導。大山小山必在你們面前發聲歌唱；田野的樹木也都拍掌。","notes":[]},{"n":13,"t":"松樹長出，代替荊棘；番石榴長出，代替蒺藜。這要為耶和華留名，作為永遠的證據，不能剪除。","notes":[]}]},"56":{"heading":"神的子民將包括各國的百姓","verses":[{"n":1,"t":"耶和華如此說：你們當守公平，行公義；因我的救恩臨近，我的公義將要顯現。","notes":[]},{"n":2,"t":"謹守安息日而不干犯，禁止己手而不作惡；如此行、如此持守的人便為有福。","notes":[]},{"n":3,"t":"與耶和華聯合的外邦人不要說：耶和華必定將我從他民中分別出來。太監也不要說：我是枯樹。","notes":[]},{"n":4,"t":"因為耶和華如此說：那些謹守我的安息日，揀選我所喜悅的事，持守我約的太監，","notes":[]},{"n":5,"t":"我必使他們在我殿中，在我牆內，有記念，有名號，比有兒女的更美。我必賜他們永遠的名，不能剪除。","notes":[]},{"n":6,"t":"還有那些與耶和華聯合的外邦人，要事奉他，要愛耶和華的名，要作他的僕人－就是凡守安息日不干犯，又持守他約的人。","notes":["原文是我"]},{"n":7,"t":"我必領他們到我的聖山，使他們在禱告我的殿中喜樂。他們的燔祭和平安祭，在我壇上必蒙悅納，因我的殿必稱為萬民禱告的殿。","notes":[]},{"n":8,"t":"主耶和華，就是招聚以色列被趕散的，說：在這被招聚的人以外，我還要招聚別人歸併他們。","notes":[]},{"n":9,"t":"田野的諸獸都來吞吃吧！林中的諸獸也要如此。","notes":[],"heads":["以色列的領袖被定罪"]},{"n":10,"t":"他看守的人是瞎眼的，都沒有知識，都是啞巴狗，不能叫喚；但知做夢，躺臥，貪睡，","notes":[]},{"n":11,"t":"這些狗貪食，不知飽足。這些牧人不能明白－各人偏行己路，各從各方求自己的利益。","notes":[]},{"n":12,"t":"他們說：來吧！我去拿酒，我們飽飲濃酒；明日必和今日一樣，就是宴樂無量極大之日。","notes":[]}]},"57":{"heading":"以色列拜偶像被定罪","verses":[{"n":1,"t":"義人死亡，無人放在心上；虔誠人被收去，無人思念。這義人被收去是免了將來的禍患；","notes":[]},{"n":2,"t":"他們得享平安。素行正直的，各人在墳裏安歇。","notes":["原文是進入","原文是床上"]},{"n":3,"t":"你們這些巫婆的兒子，姦夫和妓女的種子，都要前來！","notes":[]},{"n":4,"t":"你們向誰戲笑？向誰張口吐舌呢？你們豈不是悖逆的兒女，虛謊的種類呢？","notes":[]},{"n":5,"t":"你們在橡樹中間，在各青翠樹下慾火攻心；在山谷間，在石穴下殺了兒女；","notes":[]},{"n":6,"t":"在谷中光滑石頭裏有你的分。這些就是你所得的分；你也向他澆了奠祭，獻了供物，因這事我豈能容忍嗎？","notes":[]},{"n":7,"t":"你在高而又高的山上安設床榻，也上那裏去獻祭。","notes":[]},{"n":8,"t":"你在門後，在門框後，立起你的紀念；向外人赤露，又上去擴張床榻，與他們立約；你在那裏看見他們的床就甚喜愛。","notes":[]},{"n":9,"t":"你把油帶到王那裏，又多加香料，打發使者往遠方去，自卑自賤直到陰間，","notes":[]},{"n":10,"t":"你因路遠疲倦，卻不說這是枉然；你以為有復興之力，所以不覺疲憊。","notes":[]},{"n":11,"t":"你怕誰？因誰恐懼？竟說謊，不記念我，又不將這事放在心上。我不是許久閉口不言，你仍不怕我嗎？","notes":[]},{"n":12,"t":"我要指明你的公義；至於你所行的都必與你無益。","notes":[]},{"n":13,"t":"你哀求的時候，讓你所聚集的拯救你吧！風要把他們颳散，一口氣要把他們都吹去。但那投靠我的必得地土，必承受我的聖山為業。","notes":[]},{"n":14,"t":"耶和華要說：你們修築修築，預備道路，將絆腳石從我百姓的路中除掉。","notes":[],"heads":["神應許幫助和醫治"]},{"n":15,"t":"因為那至高至上、永遠長存名為聖者的如此說：我住在至高至聖的所在，也與心靈痛悔謙卑的人同居；要使謙卑人的靈甦醒，也使痛悔人的心甦醒。","notes":["原文是住在永遠"]},{"n":16,"t":"我必不永遠相爭，也不長久發怒，恐怕我所造的人與靈性都必發昏。","notes":[]},{"n":17,"t":"因他貪婪的罪孽，我就發怒擊打他；我向他掩面發怒，他卻仍然隨心背道。","notes":[]},{"n":18,"t":"我看見他所行的道，也要醫治他；又要引導他，使他和那一同傷心的人再得安慰。","notes":[]},{"n":19,"t":"我造就嘴唇的果子；願平安康泰歸與遠處的人，也歸與近處的人；並且我要醫治他。這是耶和華說的。","notes":[]},{"n":20,"t":"惟獨惡人，好像翻騰的海，不得平靜；其中的水常湧出污穢和淤泥來。","notes":[]},{"n":21,"t":"我的神說：惡人必不得平安！","notes":[]}]},"58":{"heading":"真正的禁食","verses":[{"n":1,"t":"你要大聲喊叫，不可止息；揚起聲來，好像吹角。向我百姓說明他們的過犯；向雅各家說明他們的罪惡。","notes":[]},{"n":2,"t":"他們天天尋求我，樂意明白我的道，好像行義的國民，不離棄他們神的典章，向我求問公義的判語，喜悅親近神。","notes":[]},{"n":3,"t":"他們說：我們禁食，你為何不看見呢？我們刻苦己心，你為何不理會呢？看哪，你們禁食的日子仍求利益，勒逼人為你們做苦工。","notes":[]},{"n":4,"t":"你們禁食，卻互相爭競，以凶惡的拳頭打人。你們今日禁食，不得使你們的聲音聽聞於上。","notes":[]},{"n":5,"t":"這樣禁食豈是我所揀選、使人刻苦己心的日子嗎？豈是叫人垂頭像葦子，用麻布和爐灰鋪在他以下嗎？你這可稱為禁食、為耶和華所悅納的日子嗎？","notes":[]},{"n":6,"t":"我所揀選的禁食不是要鬆開凶惡的繩，解下軛上的索，使被欺壓的得自由，折斷一切的軛嗎？","notes":[]},{"n":7,"t":"不是要把你的餅分給飢餓的人，將飄流的窮人接到你家中，見赤身的給他衣服遮體，顧恤自己的骨肉而不掩藏嗎？","notes":[]},{"n":8,"t":"這樣，你的光就必發現如早晨的光；你所得的醫治要速速發明。你的公義必在你前面行；耶和華的榮光必作你的後盾。","notes":[]},{"n":9,"t":"那時你求告，耶和華必應允；你呼求，他必說：我在這裏。你若從你中間除掉重軛和指摘人的指頭，並發惡言的事，","notes":[]},{"n":10,"t":"你心若向飢餓的人發憐憫，使困苦的人得滿足，你的光就必在黑暗中發現；你的幽暗必變如正午。","notes":[]},{"n":11,"t":"耶和華也必時常引導你，在乾旱之地使你心滿意足，骨頭強壯。你必像澆灌的園子，又像水流不絕的泉源。","notes":[]},{"n":12,"t":"那些出於你的人必修造久已荒廢之處；你要建立拆毀累代的根基。你必稱為補破口的，和重修路徑與人居住的。","notes":[]},{"n":13,"t":"你若在安息日掉轉你的腳步，在我聖日不以操作為喜樂，稱安息日為可喜樂的，稱耶和華的聖日為可尊重的；而且尊敬這日，不辦自己的私事，不隨自己的私意，不說自己的私話，","notes":["或譯：謹慎"],"heads":["守安息日者的報賞"]},{"n":14,"t":"你就以耶和華為樂。耶和華要使你乘駕地的高處，又以你祖雅各的產業養育你。這是耶和華親口說的。","notes":[]}]},"59":{"heading":"先知指責百姓的罪惡","verses":[{"n":1,"t":"耶和華的膀臂並非縮短，不能拯救，耳朵並非發沉，不能聽見，","notes":[]},{"n":2,"t":"但你們的罪孽使你們與神隔絕；你們的罪惡使他掩面不聽你們。","notes":[]},{"n":3,"t":"因你們的手被血沾染，你們的指頭被罪孽沾污，你們的嘴唇說謊言，你們的舌頭出惡語。","notes":[]},{"n":4,"t":"無一人按公義告狀，無一人憑誠實辯白；都倚靠虛妄，說謊言。所懷的是毒害；所生的是罪孽。","notes":[]},{"n":5,"t":"他們菢毒蛇蛋，結蜘蛛網；人吃這蛋必死。這蛋被踏，必出蝮蛇。","notes":[]},{"n":6,"t":"所結的網不能成為衣服；所做的也不能遮蓋自己。他們的行為都是罪孽；手所做的都是強暴。","notes":[]},{"n":7,"t":"他們的腳奔跑行惡；他們急速流無辜人的血；意念都是罪孽，所經過的路都荒涼毀滅。","notes":[]},{"n":8,"t":"平安的路，他們不知道；所行的事沒有公平。他們為自己修彎曲的路；凡行此路的都不知道平安。","notes":[]},{"n":9,"t":"因此，公平離我們遠，公義追不上我們。我們指望光亮，卻是黑暗，指望光明，卻行幽暗。","notes":[],"heads":["百姓悔罪"]},{"n":10,"t":"我們摸索牆壁，好像瞎子；我們摸索，如同無目之人。我們晌午絆腳，如在黃昏一樣；我們在肥壯人中，像死人一般。","notes":[]},{"n":11,"t":"我們咆哮如熊，哀鳴如鴿；指望公平，卻是沒有；指望救恩，卻遠離我們。","notes":[]},{"n":12,"t":"我們的過犯在你面前增多，罪惡作見證告我們；過犯與我們同在。至於我們的罪孽，我們都知道：","notes":[]},{"n":13,"t":"就是悖逆、不認識耶和華，轉去不跟從我們的神，說欺壓和叛逆的話，心懷謊言，隨即說出。","notes":[]},{"n":14,"t":"並且公平轉而退後，公義站在遠處；誠實在街上仆倒，正直也不得進入。","notes":[]},{"n":15,"t":"誠實少見；離惡的人反成掠物。那時，耶和華看見沒有公平，甚不喜悅。","notes":[]},{"n":16,"t":"他見無人拯救，無人代求，甚為詫異，就用自己的膀臂施行拯救，以公義扶持自己。","notes":[]},{"n":17,"t":"他以公義為鎧甲，以拯救為頭盔，以報仇為衣服，以熱心為外袍。","notes":["或譯：護心鏡"]},{"n":18,"t":"他必按人的行為施報，惱怒他的敵人，報復他的仇敵，向眾海島施行報應。","notes":[]},{"n":19,"t":"如此，人從日落之處必敬畏耶和華的名，從日出之地也必敬畏他的榮耀；因為仇敵好像急流的河水沖來，是耶和華之氣所驅逐的。","notes":[]},{"n":20,"t":"必有一位救贖主來到錫安－雅各族中轉離過犯的人那裏。這是耶和華說的。","notes":[]},{"n":21,"t":"耶和華說：「至於我與他們所立的約乃是這樣：我加給你的靈，傳給你的話，必不離你的口，也不離你後裔與你後裔之後裔的口，從今直到永遠；這是耶和華說的。」","notes":[]}]},"60":{"heading":"耶路撒冷未來的榮耀","verses":[{"n":1,"t":"興起，發光！因為你的光已經來到！耶和華的榮耀發現照耀你。","notes":[]},{"n":2,"t":"看哪，黑暗遮蓋大地，幽暗遮蓋萬民，耶和華卻要顯現照耀你；他的榮耀要現在你身上。","notes":[]},{"n":3,"t":"萬國要來就你的光；君王要來就你發現的光輝。","notes":[]},{"n":4,"t":"你舉目向四方觀看；眾人都聚集來到你這裏。你的眾子從遠方而來；你的眾女也被懷抱而來。","notes":[]},{"n":5,"t":"那時，你看見就有光榮；你心又跳動又寬暢；因為大海豐盛的貨物必轉來歸你；列國的財寶也必來歸你。","notes":[]},{"n":6,"t":"成群的駱駝，並米甸和以法的獨峰駝必遮滿你；示巴的眾人都必來到；要奉上黃金乳香，又要傳說耶和華的讚美。","notes":[]},{"n":7,"t":"基達的羊群都必聚集到你這裏，尼拜約的公羊要供你使用，在我壇上必蒙悅納；我必榮耀我榮耀的殿。","notes":[]},{"n":8,"t":"那些飛來如雲、又如鴿子向窗戶飛回的是誰呢？","notes":[]},{"n":9,"t":"眾海島必等候我，首先是他施的船隻，將你的眾子連他們的金銀從遠方一同帶來，都為耶和華－你神的名，又為以色列的聖者，因為他已經榮耀了你。","notes":[]},{"n":10,"t":"外邦人必建築你的城牆；他們的王必服事你。我曾發怒擊打你，現今卻施恩憐恤你。","notes":[]},{"n":11,"t":"你的城門必時常開放，晝夜不關；使人把列國的財物帶來歸你，並將他們的君王牽引而來。","notes":[]},{"n":12,"t":"哪一邦哪一國不事奉你，就必滅亡，也必全然荒廢。","notes":[]},{"n":13,"t":"黎巴嫩的榮耀，就是松樹、杉樹、黃楊樹，都必一同歸你，為要修飾我聖所之地；我也要使我腳踏之處得榮耀。","notes":[]},{"n":14,"t":"素來苦待你的，他的子孫都必屈身來就你；藐視你的，都要在你腳下跪拜。他們要稱你為「耶和華的城」，為「以色列聖者的錫安」。","notes":[]},{"n":15,"t":"你雖然被撇棄被厭惡，甚至無人經過，我卻使你變為永遠的榮華，成為累代的喜樂。","notes":[]},{"n":16,"t":"你也必吃萬國的奶，又吃君王的奶。你便知道我－耶和華是你的救主，是你的救贖主，雅各的大能者。","notes":[]},{"n":17,"t":"我要拿金子代替銅，拿銀子代替鐵，拿銅代替木頭，拿鐵代替石頭；並要以和平為你的官長，以公義為你的監督。","notes":[]},{"n":18,"t":"你地上不再聽見強暴的事，境內不再聽見荒涼毀滅的事。你必稱你的牆為「拯救」，稱你的門為「讚美」。","notes":[]},{"n":19,"t":"日頭不再作你白晝的光；月亮也不再發光照耀你。耶和華卻要作你永遠的光；你神要為你的榮耀。","notes":[]},{"n":20,"t":"你的日頭不再下落；你的月亮也不退縮；因為耶和華必作你永遠的光。你悲哀的日子也完畢了。","notes":[]},{"n":21,"t":"你的居民都成為義人，永遠得地為業；是我種的栽子，我手的工作，使我得榮耀。","notes":[]},{"n":22,"t":"至小的族要加增千倍；微弱的國必成為強盛。我－耶和華要按定期速成這事。","notes":[]}]},"61":{"heading":"拯救的好消息","verses":[{"n":1,"t":"主耶和華的靈在我身上；因為耶和華用膏膏我，叫我傳好信息給謙卑的人，差遣我醫好傷心的人，報告被擄的得釋放，被囚的出監牢；","notes":["或譯：傳福音給貧窮的人"]},{"n":2,"t":"報告耶和華的恩年，和我們神報仇的日子；安慰一切悲哀的人，","notes":[]},{"n":3,"t":"賜華冠與錫安悲哀的人，代替灰塵；喜樂油代替悲哀；讚美衣代替憂傷之靈；使他們稱為「公義樹」，是耶和華所栽的，叫他得榮耀。","notes":[]},{"n":4,"t":"他們必修造已久的荒場，建立先前淒涼之處，重修歷代荒涼之城。","notes":[]},{"n":5,"t":"那時，外人必起來牧放你們的羊群；外邦人必作你們耕種田地的，修理葡萄園的。","notes":[]},{"n":6,"t":"你們倒要稱為耶和華的祭司；人必稱你們為我們神的僕役。你們必吃用列國的財物，因得他們的榮耀自誇。","notes":[]},{"n":7,"t":"你們必得加倍的好處，代替所受的羞辱；分中所得的喜樂，必代替所受的凌辱。在境內必得加倍的產業；永遠之樂必歸與你們。","notes":["原文是他們"]},{"n":8,"t":"因為我－耶和華喜愛公平，恨惡搶奪和罪孽；我要憑誠實施行報應，並要與我的百姓立永約。","notes":[]},{"n":9,"t":"他們的後裔必在列國中被人認識；他們的子孫在眾民中也是如此。凡看見他們的必認他們是耶和華賜福的後裔。","notes":[]},{"n":10,"t":"我因耶和華大大歡喜；我的心靠神快樂。因他以拯救為衣給我穿上，以公義為袍給我披上，好像新郎戴上華冠，又像新婦佩戴妝飾。","notes":[]},{"n":11,"t":"田地怎樣使百穀發芽，園子怎樣使所種的發生，主耶和華必照樣使公義和讚美在萬民中發出。","notes":[]}]},"62":{"heading":"","verses":[{"n":1,"t":"我因錫安必不靜默，為耶路撒冷必不息聲，直到他的公義如光輝發出，他的救恩如明燈發亮。","notes":[]},{"n":2,"t":"列國必見你的公義；列王必見你的榮耀。你必得新名的稱呼，是耶和華親口所起的。","notes":[]},{"n":3,"t":"你在耶和華的手中要作為華冠，在你神的掌上必作為冕旒。","notes":[]},{"n":4,"t":"你必不再稱為「撇棄的」；你的地也不再稱為「荒涼的」。你卻要稱為「我所喜悅的」；你的地也必稱為「有夫之婦」。因為耶和華喜悅你，你的地也必歸他。","notes":[]},{"n":5,"t":"少年人怎樣娶處女，你的眾民也要照樣娶你；新郎怎樣喜悅新婦，你的神也要照樣喜悅你。","notes":["民：原文是子"]},{"n":6,"t":"耶路撒冷啊，我在你城上設立守望的，他們晝夜必不靜默。呼籲耶和華的，你們不要歇息，","notes":[]},{"n":7,"t":"也不要使他歇息，直等他建立耶路撒冷，使耶路撒冷在地上成為可讚美的。","notes":[]},{"n":8,"t":"耶和華指著自己的右手和大能的膀臂起誓說：我必不再將你的五穀給你仇敵作食物；外邦人也不再喝你勞碌得來的新酒。","notes":[]},{"n":9,"t":"惟有那收割的要吃，並讚美耶和華；那聚斂的要在我聖所的院內喝。","notes":[]},{"n":10,"t":"你們當從門經過經過，預備百姓的路；修築修築大道，撿去石頭，為萬民豎立大旗，","notes":[]},{"n":11,"t":"看哪，耶和華曾宣告到地極，對錫安的居民說：你的拯救者來到。他的賞賜在他那裏；他的報應在他面前。","notes":["原文是女子"]},{"n":12,"t":"人必稱他們為「聖民」，為「耶和華的贖民」；你也必稱為「被眷顧、不撇棄的城」。","notes":[]}]},"63":{"heading":"耶和華恩待以色列","verses":[{"n":1,"t":"這從以東的波斯拉來，穿紅衣服，裝扮華美，能力廣大，大步行走的是誰呢？就是我，是憑公義說話，以大能施行拯救。","notes":[]},{"n":2,"t":"你的裝扮為何有紅色？你的衣服為何像踹酒醡的呢？","notes":[]},{"n":3,"t":"我獨自踹酒醡；眾民中無一人與我同在。我發怒將他們踹下，發烈怒將他們踐踏。他們的血濺在我衣服上，並且污染了我一切的衣裳。","notes":[]},{"n":4,"t":"因為，報仇之日在我心中；救贖我民之年已經來到。","notes":[]},{"n":5,"t":"我仰望，見無人幫助；我詫異，沒有人扶持。所以，我自己的膀臂為我施行拯救；我的烈怒將我扶持。","notes":[]},{"n":6,"t":"我發怒，踹下眾民；發烈怒，使他們沉醉，又將他們的血倒在地上。","notes":[]},{"n":7,"t":"我要照耶和華一切所賜給我們的，提起他的慈愛和美德，並他向以色列家所施的大恩；這恩是照他的憐恤和豐盛的慈愛賜給他們的。","notes":[],"heads":["耶和華對以色列的良善"]},{"n":8,"t":"他說：他們誠然是我的百姓，不行虛假的子民；這樣，他就作了他們的救主。","notes":[]},{"n":9,"t":"他們在一切苦難中，他也同受苦難；並且他面前的使者拯救他們；他以慈愛和憐憫救贖他們；在古時的日子常保抱他們，懷搋他們。","notes":[]},{"n":10,"t":"他們竟悖逆，使主的聖靈擔憂。他就轉作他們的仇敵，親自攻擊他們。","notes":[]},{"n":11,"t":"那時，他們想起古時的日子－摩西和他百姓，說：將百姓和牧養他全群的人從海裏領上來的在哪裏呢？將他的聖靈降在他們中間的在哪裏呢？","notes":["原文是他"]},{"n":12,"t":"使他榮耀的膀臂在摩西的右手邊行動，在他們前面將水分開，要建立自己永遠的名，","notes":[]},{"n":13,"t":"帶領他們經過深處，如馬行走曠野，使他們不致絆跌的在哪裏呢？","notes":[]},{"n":14,"t":"耶和華的靈使他們得安息，彷彿牲畜下到山谷；照樣，你也引導你的百姓，要建立自己榮耀的名。","notes":[]},{"n":15,"t":"求你從天上垂顧，從你聖潔榮耀的居所觀看。你的熱心和你大能的作為在哪裏呢？你愛慕的心腸和憐憫向我們止住了。","notes":[],"heads":["求主憐憫幫助"]},{"n":16,"t":"亞伯拉罕雖然不認識我們，以色列也不承認我們，你卻是我們的父。耶和華啊，你是我們的父；從萬古以來，你名稱為「我們的救贖主」。","notes":[]},{"n":17,"t":"耶和華啊，你為何使我們走差離開你的道，使我們心裏剛硬、不敬畏你呢？求你為你僕人，為你產業支派的緣故，轉回來。","notes":[]},{"n":18,"t":"你的聖民不過暫時得這產業；我們的敵人已經踐踏你的聖所。","notes":[]},{"n":19,"t":"我們好像你未曾治理的人，又像未曾得稱你名下的人。","notes":[]}]},"64":{"heading":"","verses":[{"n":1,"t":"願你裂天而降；願山在你面前震動－","notes":[]},{"n":2,"t":"好像火燒乾柴，又像火將水燒開，使你敵人知道你的名，使列國在你面前發顫！","notes":[]},{"n":3,"t":"你曾行我們不能逆料可畏的事。那時你降臨，山嶺在你面前震動。","notes":[]},{"n":4,"t":"從古以來，人未曾聽見、未曾耳聞、未曾眼見在你以外有甚麼神為等候他的人行事。","notes":[]},{"n":5,"t":"你迎接那歡喜行義、記念你道的人；你曾發怒，我們仍犯罪；這景況已久，我們還能得救嗎？","notes":[]},{"n":6,"t":"我們都像不潔淨的人；所有的義都像污穢的衣服。我們都像葉子漸漸枯乾；我們的罪孽好像風把我們吹去。","notes":[]},{"n":7,"t":"並且無人求告你的名；無人奮力抓住你。原來你掩面不顧我們，使我們因罪孽消化。","notes":[]},{"n":8,"t":"耶和華啊，現在你仍是我們的父！我們是泥，你是窯匠；我們都是你手的工作。","notes":[]},{"n":9,"t":"耶和華啊，求你不要大發震怒，也不要永遠記念罪孽。求你垂顧我們，我們都是你的百姓。","notes":[]},{"n":10,"t":"你的聖邑變為曠野。錫安變為曠野；耶路撒冷成為荒場。","notes":[]},{"n":11,"t":"我們聖潔華美的殿－就是我們列祖讚美你的所在被火焚燒；我們所羨慕的美地盡都荒廢。","notes":[]},{"n":12,"t":"耶和華啊，有這些事，你還忍得住嗎？你仍靜默使我們深受苦難嗎？","notes":[]}]},"65":{"heading":"神對悖逆者的懲罰","verses":[{"n":1,"t":"素來沒有訪問我的，現在求問我；沒有尋找我的，我叫他們遇見；沒有稱為我名下的，我對他們說：我在這裏！我在這裏！","notes":[]},{"n":2,"t":"我整天伸手招呼那悖逆的百姓；他們隨自己的意念行不善之道。","notes":[]},{"n":3,"t":"這百姓時常當面惹我發怒；在園中獻祭，在壇上燒香；","notes":["原文是磚"]},{"n":4,"t":"在墳墓間坐著，在隱密處住宿，吃豬肉；他們器皿中有可憎之物做的湯；","notes":[]},{"n":5,"t":"且對人說：你站開吧！不要挨近我，因為我比你聖潔。主說：這些人是我鼻中的煙，是整天燒著的火。","notes":[]},{"n":6,"t":"看哪，這都寫在我面前。我必不靜默，必施行報應，必將你們的罪孽和你們列祖的罪孽，就是在山上燒香，在岡上褻瀆我的罪孽，一同報應在他們後人懷中，我先要把他們所行的量給他們；這是耶和華說的。","notes":[],"end":7},{"n":8,"t":"耶和華如此說：葡萄中尋得新酒，人就說：不要毀壞，因為福在其中。我因我僕人的緣故也必照樣而行，不將他們全然毀滅。","notes":[]},{"n":9,"t":"我必從雅各中領出後裔，從猶大中領出承受我眾山的。我的選民必承受；我的僕人要在那裏居住。","notes":[]},{"n":10,"t":"沙崙平原必成為羊群的圈；亞割谷必成為牛群躺臥之處，都為尋求我的民所得。","notes":[]},{"n":11,"t":"但你們這些離棄耶和華、忘記我的聖山、給時運擺筵席、給天命盛滿調和酒的，","notes":["原文是桌子"]},{"n":12,"t":"我要命定你們歸在刀下，都必屈身被殺；因為我呼喚，你們沒有答應；我說話，你們沒有聽從；反倒行我眼中看為惡的，揀選我所不喜悅的。","notes":[]},{"n":13,"t":"所以，主耶和華如此說：我的僕人必得吃，你們卻飢餓；我的僕人必得喝，你們卻乾渴；我的僕人必歡喜，你們卻蒙羞。","notes":[]},{"n":14,"t":"我的僕人因心中高興歡呼，你們卻因心中憂愁哀哭，又因心裏憂傷哀號。","notes":[]},{"n":15,"t":"你們必留下自己的名，為我選民指著賭咒。主耶和華必殺你們，另起別名稱呼他的僕人。","notes":[]},{"n":16,"t":"這樣，在地上為自己求福的，必憑真實的神求福；在地上起誓的，必指真實的神起誓。因為，從前的患難已經忘記，也從我眼前隱藏了。","notes":[]},{"n":17,"t":"看哪！我造新天新地；從前的事不再被記念，也不再追想。","notes":[],"heads":["新天新地"]},{"n":18,"t":"你們當因我所造的永遠歡喜快樂；因我造耶路撒冷為人所喜，造其中的居民為人所樂。","notes":[]},{"n":19,"t":"我必因耶路撒冷歡喜，因我的百姓快樂；其中必不再聽見哭泣的聲音和哀號的聲音。","notes":[]},{"n":20,"t":"其中必沒有數日夭亡的嬰孩，也沒有壽數不滿的老者；因為百歲死的仍算孩童，有百歲死的罪人算被咒詛。","notes":[]},{"n":21,"t":"他們要建造房屋，自己居住；栽種葡萄園，吃其中的果子。","notes":[]},{"n":22,"t":"他們建造的，別人不得住；他們栽種的，別人不得吃；因為我民的日子必像樹木的日子；我選民親手勞碌得來的必長久享用。","notes":[]},{"n":23,"t":"他們必不徒然勞碌，所生產的，也不遭災害，因為都是蒙耶和華賜福的後裔；他們的子孫也是如此。","notes":[]},{"n":24,"t":"他們尚未求告，我就應允；正說話的時候，我就垂聽。","notes":[]},{"n":25,"t":"豺狼必與羊羔同食；獅子必吃草與牛一樣；塵土必作蛇的食物。在我聖山的遍處，這一切都不傷人，不害物。這是耶和華說的。","notes":[]}]},"66":{"heading":"耶和華審判萬民","verses":[{"n":1,"t":"耶和華如此說：天是我的座位；地是我的腳凳。你們要為我造何等的殿宇？哪裏是我安息的地方呢？","notes":[]},{"n":2,"t":"耶和華說：這一切都是我手所造的，所以就都有了。但我所看顧的，就是虛心痛悔、因我話而戰兢的人。","notes":["原文是貧窮"]},{"n":3,"t":"假冒為善的宰牛，好像殺人，獻羊羔，好像打折狗項，獻供物，好像獻豬血，燒乳香，好像稱頌偶像。這等人揀選自己的道路，心裏喜悅行可憎惡的事。","notes":[]},{"n":4,"t":"我也必揀選迷惑他們的事，使他們所懼怕的臨到他們；因為我呼喚，無人答應；我說話，他們不聽從；反倒行我眼中看為惡的，揀選我所不喜悅的。","notes":[]},{"n":5,"t":"你們因耶和華言語戰兢的人當聽他的話：你們的弟兄－就是恨惡你們，因我名趕出你們的，曾說：願耶和華得榮耀，使我們得見你們的喜樂；但蒙羞的究竟是他們！","notes":[]},{"n":6,"t":"有喧嘩的聲音出自城中！有聲音出於殿中！是耶和華向仇敵施行報應的聲音！","notes":[]},{"n":7,"t":"錫安未曾劬勞就生產，未覺疼痛就生出男孩。","notes":[]},{"n":8,"t":"國豈能一日而生？民豈能一時而產？因為錫安一劬勞便生下兒女，這樣的事誰曾聽見？誰曾看見呢？","notes":[]},{"n":9,"t":"耶和華說：我既使她臨產，豈不使她生產呢？你的神說：我既使她生產，豈能使她閉胎不生呢？","notes":[]},{"n":10,"t":"你們愛慕耶路撒冷的都要與她一同歡喜快樂；你們為她悲哀的都要與她一同樂上加樂；","notes":[]},{"n":11,"t":"使你們在她安慰的懷中吃奶得飽，使他們得她豐盛的榮耀，猶如擠奶，滿心喜樂。","notes":[]},{"n":12,"t":"耶和華如此說：我要使平安延及她，好像江河，使列國的榮耀延及她，如同漲溢的河。你們要從中享受；你們必蒙抱在肋旁，搖弄在膝上。","notes":["原文是咂"]},{"n":13,"t":"母親怎樣安慰兒子，我就照樣安慰你們；你們也必因耶路撒冷得安慰。","notes":["或譯：在"]},{"n":14,"t":"你們看見，就心中快樂；你們的骨頭必得滋潤像嫩草一樣；而且耶和華的手向他僕人所行的必被人知道；他也要向仇敵發惱恨。","notes":[]},{"n":15,"t":"看哪，耶和華必在火中降臨；他的車輦像旋風，以烈怒施行報應，以火焰施行責罰；","notes":[]},{"n":16,"t":"因為耶和華在一切有血氣的人身上，必以火與刀施行審判；被耶和華所殺的必多。","notes":[]},{"n":17,"t":"「那些分別為聖、潔淨自己的，進入園內跟在其中一個人的後頭，吃豬肉和倉鼠並可憎之物，他們必一同滅絕；這是耶和華說的。","notes":[]},{"n":18,"t":"「我知道他們的行為和他們的意念。時候將到，我必將萬民萬族聚來，看見我的榮耀，","notes":["族：原文是舌"]},{"n":19,"t":"我要顯神蹟在他們中間。逃脫的，我要差到列國去，就是到他施、普勒、拉弓的路德和土巴、雅完，並素來沒有聽見我名聲、沒有看見我榮耀遼遠的海島；他們必將我的榮耀傳揚在列國中。","notes":["或譯：記號"]},{"n":20,"t":"他們必將你們的弟兄從列國中送回，使他們或騎馬，或坐車，坐轎，騎騾子，騎獨峰駝，到我的聖山耶路撒冷，作為供物獻給耶和華，好像以色列人用潔淨的器皿盛供物奉到耶和華的殿中；這是耶和華說的。","notes":[]},{"n":21,"t":"耶和華說：我也必從他們中間取人為祭司，為利未人。」","notes":[]},{"n":22,"t":"耶和華說：我所要造的新天新地，怎樣在我面前長存；你們的後裔和你們的名字也必照樣長存。","notes":[]},{"n":23,"t":"每逢月朔、安息日，凡有血氣的必來在我面前下拜。這是耶和華說的。","notes":[]},{"n":24,"t":"他們必出去觀看那些違背我人的屍首；因為他們的蟲是不死的；他們的火是不滅的；凡有血氣的都必憎惡他們。","notes":[]}]}},"JER":{"1":{"heading":"耶利米蒙選召","verses":[{"n":1,"t":"便雅憫地亞拿突城的祭司中，希勒家的兒子耶利米的話記在下面。","notes":[]},{"n":2,"t":"猶大王亞們的兒子約西亞在位十三年，耶和華的話臨到耶利米。","notes":[]},{"n":3,"t":"從猶大王約西亞的兒子約雅敬在位的時候，直到猶大王約西亞的兒子西底家在位的末年，就是十一年五月間耶路撒冷人被擄的時候，耶和華的話也常臨到耶利米。","notes":[]},{"n":4,"t":"耶利米說，耶和華的話臨到我說：","notes":[]},{"n":5,"t":"我未將你造在腹中，我已曉得你；你未出母胎，我已分別你為聖；我已派你作列國的先知。","notes":[]},{"n":6,"t":"我就說：主耶和華啊，我不知怎樣說，因為我是年幼的。","notes":[]},{"n":7,"t":"耶和華對我說：你不要說我是年幼的，因為我差遣你到誰那裏去，你都要去；我吩咐你說甚麼話，你都要說。","notes":[]},{"n":8,"t":"你不要懼怕他們，因為我與你同在，要拯救你。這是耶和華說的。","notes":[]},{"n":9,"t":"於是耶和華伸手按我的口，對我說：我已將當說的話傳給你。","notes":[]},{"n":10,"t":"看哪，我今日立你在列邦列國之上，為要施行拔出、拆毀、毀壞、傾覆，又要建立、栽植。","notes":[]},{"n":11,"t":"耶和華的話又臨到我說：「耶利米，你看見甚麼？」我說：「我看見一根杏樹枝。」","notes":[],"heads":["兩個異象"]},{"n":12,"t":"耶和華對我說：「你看得不錯；因為我留意保守我的話，使得成就。」","notes":[]},{"n":13,"t":"耶和華的話第二次臨到我說：「你看見甚麼？」我說：「我看見一個燒開的鍋，從北而傾。」","notes":[]},{"n":14,"t":"耶和華對我說：「必有災禍從北方發出，臨到這地的一切居民。」","notes":[]},{"n":15,"t":"耶和華說：「看哪，我要召北方列國的眾族；他們要來，各安座位在耶路撒冷的城門口，周圍攻擊城牆，又要攻擊猶大的一切城邑。","notes":[]},{"n":16,"t":"至於這民的一切惡，就是離棄我、向別神燒香、跪拜自己手所造的，我要發出我的判語，攻擊他們。","notes":[]},{"n":17,"t":"所以你當束腰，起來將我所吩咐你的一切話告訴他們；不要因他們驚惶，免得我使你在他們面前驚惶。","notes":[]},{"n":18,"t":"看哪，我今日使你成為堅城、鐵柱、銅牆，與全地和猶大的君王、首領、祭司，並地上的眾民反對。","notes":[]},{"n":19,"t":"他們要攻擊你，卻不能勝你；因為我與你同在，要拯救你。這是耶和華說的。」","notes":[]}]},"2":{"heading":"神眷顧以色列","verses":[{"n":1,"t":"耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「你去向耶路撒冷人的耳中喊叫說，耶和華如此說：你幼年的恩愛，婚姻的愛情，你怎樣在曠野，在未曾耕種之地跟隨我，我都記得。","notes":[]},{"n":3,"t":"那時以色列歸耶和華為聖，作為土產初熟的果子；凡吞吃它的必算為有罪，災禍必臨到他們。這是耶和華說的。","notes":[]},{"n":4,"t":"雅各家、以色列家的各族啊，你們當聽耶和華的話。","notes":[],"heads":["以色列祖先的罪惡"]},{"n":5,"t":"耶和華如此說：你們的列祖見我有甚麼不義，竟遠離我，隨從虛無的神，自己成為虛妄的呢？","notes":[]},{"n":6,"t":"他們也不說：那領我們從埃及地上來，引導我們經過曠野，沙漠有深坑之地，和乾旱死蔭、無人經過、無人居住之地的耶和華在哪裏呢？","notes":[]},{"n":7,"t":"我領你們進入肥美之地，使你們得吃其中的果子和美物；但你們進入的時候就玷污我的地，使我的產業成為可憎的。","notes":[]},{"n":8,"t":"祭司都不說，耶和華在哪裏呢？傳講律法的都不認識我。官長違背我；先知藉巴力說預言，隨從無益的神。","notes":[]},{"n":9,"t":"耶和華說：我因此必與你們爭辯，也必與你們的子孫爭辯。","notes":[],"heads":["神譴責他的子民"]},{"n":10,"t":"你們且過到基提海島去察看，打發人往基達去留心查考，看曾有這樣的事沒有。","notes":[]},{"n":11,"t":"豈有一國換了他的神嗎？其實這不是神！但我的百姓將他們的榮耀換了那無益的神。","notes":[]},{"n":12,"t":"諸天哪，要因此驚奇，極其恐慌，甚為淒涼！這是耶和華說的。","notes":[]},{"n":13,"t":"因為我的百姓做了兩件惡事，就是離棄我這活水的泉源，為自己鑿出池子，是破裂不能存水的池子。","notes":[]},{"n":14,"t":"以色列是僕人嗎？是家中生的奴僕嗎？為何成為掠物呢？","notes":[],"heads":["以色列不忠的結局"]},{"n":15,"t":"少壯獅子向他咆哮，大聲吼叫，使他的地荒涼；城邑也都焚燒，無人居住。","notes":[]},{"n":16,"t":"挪弗人和答比匿人也打破你的頭頂。","notes":[]},{"n":17,"t":"這事臨到你身上，不是你自招的嗎？不是因耶和華－你神引你行路的時候，你離棄他嗎？","notes":[]},{"n":18,"t":"現今你為何在埃及路上要喝西曷的水呢？你為何在亞述路上要喝大河的水呢？","notes":[]},{"n":19,"t":"你自己的惡必懲治你；你背道的事必責備你。由此可知可見，你離棄耶和華－你的神，不存敬畏我的心，乃為惡事，為苦事。這是主－萬軍之耶和華說的。","notes":[]},{"n":20,"t":"我在古時折斷你的軛，解開你的繩索。你說：我必不事奉耶和華；因為你在各高岡上、各青翠樹下屈身行淫。","notes":["或譯：我在古時折斷你的軛，解開你的繩索，你就說：我必不事奉別神。誰知你在各高岡上、各青翠樹下仍屈身行淫"],"heads":["以色列拒絕敬拜耶和華"]},{"n":21,"t":"然而，我栽你是上等的葡萄樹，全然是真種子；你怎麼向我變為外邦葡萄樹的壞枝子呢？","notes":[]},{"n":22,"t":"你雖用鹼、多用肥皂洗濯，你罪孽的痕跡仍然在我面前顯出。這是主耶和華說的。","notes":[]},{"n":23,"t":"你怎能說：我沒有玷污、沒有隨從眾巴力？你看你谷中的路，就知道你所行的如何。你是快行的獨峰駝，狂奔亂走。","notes":[]},{"n":24,"t":"你是野驢，慣在曠野，慾心發動就吸風；起性的時候誰能使牠轉去呢？凡尋找牠的必不致疲乏；在牠的月份必能尋見。","notes":[]},{"n":25,"t":"我說：你不要使腳上無鞋，喉嚨乾渴。你倒說：這是枉然。我喜愛別神，我必隨從他們。","notes":[]},{"n":26,"t":"賊被捉拿，怎樣羞愧，以色列家和他們的君王、首領、祭司、先知也都照樣羞愧。","notes":[],"heads":["以色列該受懲罰"]},{"n":27,"t":"他們向木頭說：你是我的父；向石頭說：你是生我的。他們以背向我，不以面向我；及至遭遇患難的時候卻說：起來拯救我們。","notes":[]},{"n":28,"t":"你為自己做的神在哪裏呢？你遭遇患難的時候，叫他們起來拯救你吧！猶大啊，你神的數目與你城的數目相等。","notes":[]},{"n":29,"t":"耶和華說：你們為何與我爭辯呢？你們都違背了我。","notes":[]},{"n":30,"t":"我責打你們的兒女是徒然的，他們不受懲治。你們自己的刀吞滅你們的先知，好像殘害的獅子。","notes":[]},{"n":31,"t":"這世代的人哪，你們要看明耶和華的話。我豈向以色列作曠野呢？或作幽暗之地呢？我的百姓為何說：我們脫離約束，再不歸向你了？","notes":[]},{"n":32,"t":"處女豈能忘記她的妝飾呢？新婦豈能忘記她的美衣呢？我的百姓卻忘記了我無數的日子！","notes":[]},{"n":33,"t":"你怎麼修飾你的道路要求愛情呢？就是惡劣的婦人你也叫她們行你的路。","notes":[]},{"n":34,"t":"並且你的衣襟上有無辜窮人的血；你殺他們並不是遇見他們挖窟窿，乃是因這一切的事。","notes":[]},{"n":35,"t":"你還說：我無辜；耶和華的怒氣必定向我消了。看哪，我必審問你；因你自說：我沒有犯罪。","notes":[]},{"n":36,"t":"你為何東跑西奔要更換你的路呢？你必因埃及蒙羞，像從前因亞述蒙羞一樣。","notes":[]},{"n":37,"t":"你也必兩手抱頭從埃及出來；因為耶和華已經棄絕你所倚靠的，你必不因他們得順利。","notes":[]}]},"3":{"heading":"不忠心的以色列","verses":[{"n":1,"t":"有話說：人若休妻，妻離他而去，作了別人的妻，前夫豈能再收回她來？若收回她來，那地豈不是大大玷污了嗎？但你和許多親愛的行邪淫，還可以歸向我。這是耶和華說的。","notes":[]},{"n":2,"t":"你向淨光的高處舉目觀看，你在何處沒有淫行呢？你坐在道旁等候，好像阿拉伯人在曠野埋伏一樣，並且你的淫行邪惡玷污了全地。","notes":[]},{"n":3,"t":"因此甘霖停止，春雨不降。你還是有娼妓之臉，不顧羞恥。","notes":["原文是晚"]},{"n":4,"t":"從今以後，你豈不向我呼叫說：我父啊，你是我幼年的恩主。","notes":[]},{"n":5,"t":"耶和華豈永遠懷怒，存留到底嗎？看哪，你又發惡言又行壞事，隨自己的私意而行。」","notes":["或譯：你雖這樣說，還是行惡放縱慾心"]},{"n":6,"t":"約西亞王在位的時候，耶和華又對我說：「背道的以色列所行的，你看見沒有？她上各高山，在各青翠樹下行淫。","notes":[],"heads":["以色列和猶大應當悔改"]},{"n":7,"t":"她行這些事以後，我說她必歸向我，她卻不歸向我。她奸詐的妹妹猶大也看見了。","notes":[]},{"n":8,"t":"背道的以色列行淫，我為這緣故給她休書休她；我看見她奸詐的妹妹猶大，還不懼怕，也去行淫。","notes":[]},{"n":9,"t":"因以色列輕忽了她的淫亂，和石頭木頭行淫，地就被玷污了。","notes":[]},{"n":10,"t":"雖有這一切的事，她奸詐的妹妹猶大還不一心歸向我，不過是假意歸我。這是耶和華說的。」","notes":[]},{"n":11,"t":"耶和華對我說：「背道的以色列比奸詐的猶大還顯為義。","notes":[]},{"n":12,"t":"你去向北方宣告說：耶和華說：背道的以色列啊，回來吧！我必不怒目看你們；因為我是慈愛的，我必不永遠存怒。這是耶和華說的。","notes":[]},{"n":13,"t":"只要承認你的罪孽，就是你違背耶和華－你的神，在各青翠樹下向別神東奔西跑，沒有聽從我的話。這是耶和華說的。","notes":[]},{"n":14,"t":"耶和華說：背道的兒女啊，回來吧！因為我作你們的丈夫，並且我必將你們從一城取一人，從一族取兩人，帶到錫安。","notes":[]},{"n":15,"t":"我也必將合我心的牧者賜給你們。他們必以知識和智慧牧養你們。」","notes":[]},{"n":16,"t":"耶和華說：「你們在國中生養眾多；當那些日子，人必不再提說耶和華的約櫃，不追想，不記念，不覺缺少，也不再製造。","notes":[]},{"n":17,"t":"那時，人必稱耶路撒冷為耶和華的寶座；萬國必到耶路撒冷，在耶和華立名的地方聚集。他們必不再隨從自己頑梗的惡心行事。","notes":[]},{"n":18,"t":"當那些日子，猶大家要和以色列家同行，從北方之地一同來到我賜給你們列祖為業之地。」","notes":[]},{"n":19,"t":"我說：我怎樣將你安置在兒女之中，賜給你美地，就是萬國中肥美的產業。我又說：你們必稱我為父，也不再轉去不跟從我。","notes":[],"heads":["神的子民拜偶像"]},{"n":20,"t":"以色列家，你們向我行詭詐，真像妻子行詭詐離開她丈夫一樣。這是耶和華說的。","notes":[]},{"n":21,"t":"在淨光的高處聽見人聲，就是以色列人哭泣懇求之聲，乃因他們走彎曲之道，忘記耶和華－他們的神。","notes":[]},{"n":22,"t":"你們這背道的兒女啊，回來吧！我要醫治你們背道的病。看哪，我們來到你這裏，因你是耶和華－我們的神。","notes":[]},{"n":23,"t":"仰望從小山或從大山的喧嚷中得幫助，真是枉然的。以色列得救，誠然在乎耶和華－我們的神。","notes":[]},{"n":24,"t":"從我們幼年以來，那可恥的偶像將我們列祖所勞碌得來的羊群、牛群，和他們的兒女都吞吃了。","notes":[]},{"n":25,"t":"我們在羞恥中躺臥吧！願慚愧將我們遮蓋；因為從立國以來，我們和我們的列祖常常得罪耶和華－我們的神，沒有聽從耶和華－我們神的話。","notes":["原文是幼年"]}]},"4":{"heading":"呼召以色列悔改","verses":[{"n":1,"t":"耶和華說：以色列啊，你若回來歸向我，若從我眼前除掉你可憎的偶像，你就不被遷移。","notes":[]},{"n":2,"t":"你必憑誠實、公平、公義，指著永生的耶和華起誓；列國必因耶和華稱自己為有福，也必因他誇耀。","notes":[]},{"n":3,"t":"耶和華對猶大和耶路撒冷人如此說：要開墾你們的荒地，不要撒種在荊棘中。","notes":[]},{"n":4,"t":"猶大人和耶路撒冷的居民哪，你們當自行割禮，歸耶和華，將心裏的污穢除掉；恐怕我的忿怒因你們的惡行發作，如火著起，甚至無人能以熄滅！","notes":[]},{"n":5,"t":"你們當傳揚在猶大，宣告在耶路撒冷說：你們當在國中吹角，高聲呼叫說：你們當聚集！我們好進入堅固城！","notes":[],"heads":["外患威脅猶大"]},{"n":6,"t":"應當向錫安豎立大旗。要逃避，不要遲延，因我必使災禍與大毀滅從北方來到。","notes":[]},{"n":7,"t":"有獅子從密林中上來，是毀壞列國的。牠已經動身出離本處，要使你的地荒涼，使你的城邑變為荒場無人居住。","notes":[]},{"n":8,"t":"因此，你們當腰束麻布，大聲哀號，因為耶和華的烈怒沒有向我們轉消。","notes":[]},{"n":9,"t":"耶和華說：「到那時，君王和首領的心都要消滅；祭司都要驚奇，先知都要詫異。」","notes":[]},{"n":10,"t":"我說：「哀哉！主耶和華啊，你真是大大地欺哄這百姓和耶路撒冷，說：『你們必得平安。』其實刀劍害及性命了。」","notes":[]},{"n":11,"t":"那時，必有話對這百姓和耶路撒冷說：「有一陣熱風從曠野淨光的高處向我的眾民颳來，不是為簸揚，也不是為揚淨。","notes":["原文是民女"]},{"n":12,"t":"必有一陣更大的風從這些地方為我颳來；現在我又必發出判語，攻擊他們。」","notes":[]},{"n":13,"t":"看哪，仇敵必如雲上來；他的戰車如旋風，他的馬匹比鷹更快。我們有禍了！我們敗落了！","notes":[],"heads":["猶大被敵人圍困"]},{"n":14,"t":"耶路撒冷啊，你當洗去心中的惡，使你可以得救。惡念存在你心裏要到幾時呢？","notes":[]},{"n":15,"t":"有聲音從但傳揚，從以法蓮山報禍患。","notes":[]},{"n":16,"t":"你們當傳給列國，報告攻擊耶路撒冷的事說：有探望的人從遠方來到，向猶大的城邑大聲吶喊。","notes":[]},{"n":17,"t":"他們周圍攻擊耶路撒冷，好像看守田園的，因為她背叛了我。這是耶和華說的。","notes":[]},{"n":18,"t":"你的行動，你的作為，招惹這事；這是你罪惡的結果，實在是苦，是害及你心了！","notes":[]},{"n":19,"t":"我的肺腑啊，我的肺腑啊，我心疼痛！我心在我裏面煩躁不安。我不能靜默不言，因為我已經聽見角聲和打仗的喊聲。","notes":[],"heads":["耶利米為同胞擔憂"]},{"n":20,"t":"毀壞的信息連絡不絕，因為全地荒廢。我的帳棚忽然毀壞；我的幔子頃刻破裂。","notes":[]},{"n":21,"t":"我看見大旗，聽見角聲，要到幾時呢？","notes":[]},{"n":22,"t":"耶和華說：我的百姓愚頑，不認識我；他們是愚昧無知的兒女，有智慧行惡，沒有知識行善。","notes":[]},{"n":23,"t":"先知說：我觀看地，不料，地是空虛混沌；我觀看天，天也無光。","notes":[],"heads":["耶利米的異象－將要來臨的毀滅"]},{"n":24,"t":"我觀看大山，不料，盡都震動，小山也都搖來搖去。","notes":[]},{"n":25,"t":"我觀看，不料，無人；空中的飛鳥也都躲避。","notes":[]},{"n":26,"t":"我觀看，不料，肥田變為荒地；一切城邑在耶和華面前，因他的烈怒都被拆毀。","notes":[]},{"n":27,"t":"耶和華如此說：全地必然荒涼，我卻不毀滅淨盡。","notes":[]},{"n":28,"t":"因此，地要悲哀，在上的天也必黑暗；因為我言已出，我意已定，必不後悔，也不轉意不做。","notes":[]},{"n":29,"t":"各城的人因馬兵和弓箭手的響聲就都逃跑，進入密林，爬上磐石；各城被撇下，無人住在其中。","notes":[]},{"n":30,"t":"你淒涼的時候要怎樣行呢？你雖穿上朱紅衣服，佩戴黃金裝飾，用顏料修飾眼目，這樣標緻是枉然的！戀愛你的藐視你，並且尋索你的性命。","notes":[]},{"n":31,"t":"我聽見有聲音，彷彿婦人產難的聲音，好像生頭胎疼痛的聲音，是錫安女子的聲音；她喘著氣、挓挲手，說：我有禍了！在殺人的跟前，我的心發昏了。","notes":["就是指民的意思"]}]},"5":{"heading":"耶路撒冷的罪","verses":[{"n":1,"t":"你們當在耶路撒冷的街上跑來跑去，在寬闊處尋找，看看有一人行公義求誠實沒有？若有，我就赦免這城。","notes":[]},{"n":2,"t":"其中的人雖然指著永生的耶和華起誓，所起的誓實在是假的。","notes":[]},{"n":3,"t":"耶和華啊，你的眼目不是看顧誠實嗎？你擊打他們，他們卻不傷慟；你毀滅他們，他們仍不受懲治。他們使臉剛硬過於磐石，不肯回頭。","notes":[]},{"n":4,"t":"我說：這些人實在是貧窮的，是愚昧的，因為不曉得耶和華的作為和他們神的法則。","notes":[]},{"n":5,"t":"我要去見尊大的人，對他們說話，因為他們曉得耶和華的作為和他們神的法則。哪知，這些人齊心將軛折斷，掙開繩索。","notes":[]},{"n":6,"t":"因此，林中的獅子必害死他們；晚上的豺狼必滅絕他們；豹子要在城外窺伺他們。凡出城的必被撕碎；因為他們的罪過極多，背道的事也加增了。","notes":["或譯：野地"]},{"n":7,"t":"我怎能赦免你呢？你的兒女離棄我，又指著那不是神的起誓。我使他們飽足，他們就行姦淫，成群地聚集在娼妓家裏。","notes":[]},{"n":8,"t":"他們像餵飽的馬到處亂跑，各向他鄰舍的妻發嘶聲。","notes":[]},{"n":9,"t":"耶和華說：我豈不因這些事討罪呢？豈不報復這樣的國民呢？","notes":[]},{"n":10,"t":"你們要上她葡萄園的牆施行毀壞，但不可毀壞淨盡，只可除掉她的枝子，因為不屬耶和華。","notes":[]},{"n":11,"t":"原來以色列家和猶大家大行詭詐攻擊我。這是耶和華說的。","notes":[]},{"n":12,"t":"他們不認耶和華，說：這並不是他，災禍必不臨到我們；刀劍和饑荒，我們也看不見。","notes":[],"heads":["耶和華丟棄以色列"]},{"n":13,"t":"先知的話必成為風；道也不在他們裏面。這災必臨到他們身上。","notes":[]},{"n":14,"t":"所以耶和華－萬軍之神如此說：因為百姓說這話，我必使我的話在你口中為火，使他們為柴；這火便將他們燒滅。","notes":[]},{"n":15,"t":"耶和華說：以色列家啊，我必使一國的民從遠方來攻擊你，是強盛的國，是從古而有的國。他們的言語你不曉得，他們的話你不明白。","notes":[]},{"n":16,"t":"他們的箭袋是敞開的墳墓；他們都是勇士。","notes":[]},{"n":17,"t":"他們必吃盡你的莊稼和你的糧食，是你兒女該吃的；必吃盡你的牛羊，吃盡你的葡萄和無花果；又必用刀毀壞你所倚靠的堅固城。","notes":[]},{"n":18,"t":"耶和華說：「就是到那時，我也不將你們毀滅淨盡。","notes":[]},{"n":19,"t":"百姓若說：『耶和華－我們的神為甚麼向我們行這一切事呢？』你就對他們說：『你們怎樣離棄耶和華，在你們的地上事奉外邦神，也必照樣在不屬你們的地上事奉外邦人。』」","notes":["原文是我"]},{"n":20,"t":"當傳揚在雅各家，報告在猶大說：","notes":[],"heads":["神警告他的子民"]},{"n":21,"t":"愚昧無知的百姓啊，你們有眼不看，有耳不聽，現在當聽這話。","notes":[]},{"n":22,"t":"耶和華說：你們怎麼不懼怕我呢？我以永遠的定例，用沙為海的界限，水不得越過。因此，你們在我面前還不戰兢嗎？波浪雖然翻騰，卻不能逾越；雖然匉訇，卻不能過去。","notes":[]},{"n":23,"t":"但這百姓有背叛忤逆的心；他們叛我而去，","notes":[]},{"n":24,"t":"心內也不說：我們應當敬畏耶和華－我們的神；他按時賜雨，就是秋雨春雨，又為我們定收割的節令，永存不廢。","notes":[]},{"n":25,"t":"你們的罪孽使這些事轉離你們；你們的罪惡使你們不能得福。","notes":[]},{"n":26,"t":"因為在我民中有惡人。他們埋伏窺探，好像捕鳥的人；他們設立圈套陷害人。","notes":[]},{"n":27,"t":"籠內怎樣滿了雀鳥，他們的房中也照樣充滿詭詐；所以他們得成為大，而且富足。","notes":[]},{"n":28,"t":"他們肥胖光潤，作惡過甚，不為人伸冤！就是不為孤兒伸冤，不使他亨通，也不為窮人辨屈。","notes":[]},{"n":29,"t":"耶和華說：我豈不因這些事討罪呢？豈不報復這樣的國民呢？","notes":[]},{"n":30,"t":"國中有可驚駭、可憎惡的事：","notes":[]},{"n":31,"t":"就是先知說假預言，祭司藉他們把持權柄；我的百姓也喜愛這些事，到了結局你們怎樣行呢？","notes":[]}]},"6":{"heading":"耶路撒冷受敵人圍攻","verses":[{"n":1,"t":"便雅憫人哪，你們要逃出耶路撒冷，在提哥亞吹角，在伯‧哈基琳立號旗；因為有災禍與大毀滅從北方張望。","notes":[]},{"n":2,"t":"那秀美嬌嫩的錫安女子，我必剪除。","notes":["就是指民的意思"]},{"n":3,"t":"牧人必引他們的羊群到她那裏，在她周圍支搭帳棚，各在自己所佔之地使羊吃草。","notes":[]},{"n":4,"t":"你們要準備攻擊她。起來吧，我們可以趁午時上去。哀哉！日已漸斜，晚影拖長了。","notes":[]},{"n":5,"t":"起來吧，我們夜間上去，毀壞她的宮殿。","notes":[]},{"n":6,"t":"因為萬軍之耶和華如此說：你們要砍伐樹木，築壘攻打耶路撒冷。這就是那該罰的城，其中盡是欺壓。","notes":[]},{"n":7,"t":"井怎樣湧出水來，這城也照樣湧出惡來；在其間常聽見有強暴毀滅的事，病患損傷也常在我面前。","notes":[]},{"n":8,"t":"耶路撒冷啊，你當受教，免得我心與你生疏，免得我使你荒涼，成為無人居住之地。","notes":[]},{"n":9,"t":"萬軍之耶和華曾如此說：敵人必擄盡以色列剩下的民，如同摘淨葡萄一樣。你要像摘葡萄的人摘了又摘，回手放在筐子裏。","notes":[],"heads":["叛逆的以色列"]},{"n":10,"t":"現在我可以向誰說話作見證，使他們聽呢？他們的耳朵未受割禮，不能聽見。看哪，耶和華的話他們以為羞辱，不以為喜悅。","notes":[]},{"n":11,"t":"因此我被耶和華的忿怒充滿，難以含忍。我要傾在街中的孩童和聚會的少年人身上，連夫帶妻，並年老的與日子滿足的都必被擒拿。","notes":[]},{"n":12,"t":"他們的房屋、田地，和妻子都必轉歸別人；我要伸手攻擊這地的居民。這是耶和華說的。","notes":[]},{"n":13,"t":"因為他們從最小的到至大的都一味地貪婪，從先知到祭司都行事虛謊。","notes":[]},{"n":14,"t":"他們輕輕忽忽地醫治我百姓的損傷，說：平安了！平安了！其實沒有平安。","notes":[]},{"n":15,"t":"他們行可憎的事知道慚愧嗎？不然，他們毫不慚愧，也不知羞恥。因此，他們必在仆倒的人中仆倒；我向他們討罪的時候，他們必致跌倒。這是耶和華說的。","notes":[]},{"n":16,"t":"耶和華如此說：你們當站在路上察看，訪問古道，哪是善道，便行在其間；這樣，你們心裏必得安息。他們卻說：我們不行在其間。","notes":[],"heads":["以色列拒絕神的道路"]},{"n":17,"t":"我設立守望的人照管你們，說：要聽角聲。他們卻說：我們不聽。","notes":[]},{"n":18,"t":"列國啊，因此你們當聽！會眾啊，要知道他們必遭遇的事。","notes":[]},{"n":19,"t":"地啊，當聽！我必使災禍臨到這百姓，就是他們意念所結的果子；因為他們不聽從我的言語，至於我的訓誨，他們也厭棄了。","notes":["或譯：律法"]},{"n":20,"t":"從示巴出的乳香，從遠方出的菖蒲奉來給我有何益呢？你們的燔祭不蒙悅納；你們的平安祭，我也不喜悅。","notes":["或譯：甘蔗"]},{"n":21,"t":"所以耶和華如此說：我要將絆腳石放在這百姓前面。父親和兒子要一同跌在其上；鄰舍與朋友也都滅亡。","notes":[]},{"n":22,"t":"耶和華如此說：看哪，有一種民從北方而來，並有一大國被激動，從地極來到。","notes":[],"heads":["北方來的侵略者"]},{"n":23,"t":"他們拿弓和槍，性情殘忍，不施憐憫；他們的聲音像海浪匉訇。錫安城啊，他們騎馬都擺隊伍，如上戰場的人要攻擊你。","notes":["原文是女子"]},{"n":24,"t":"我們聽見他們的風聲，手就發軟；痛苦將我們抓住，疼痛彷彿產難的婦人。","notes":[]},{"n":25,"t":"你們不要往田野去，也不要行在路上，因四圍有仇敵的刀劍和驚嚇。","notes":[]},{"n":26,"t":"我民哪，應當腰束麻布，滾在灰中。你要悲傷，如喪獨生子痛痛哭號，因為滅命的要忽然臨到我們。","notes":["原文是民女"]},{"n":27,"t":"我使你在我民中為高臺，為保障，使你知道試驗他們的行動。","notes":["或譯：試驗人的"]},{"n":28,"t":"他們都是極悖逆的，往來讒謗人。他們是銅是鐵，都行壞事。","notes":[]},{"n":29,"t":"風箱吹火，鉛被燒毀；他們煉而又煉，終是徒然；因為惡劣的還未除掉。","notes":[]},{"n":30,"t":"人必稱他們為被棄的銀渣，因為耶和華已經棄掉他們。","notes":[]}]},"7":{"heading":"耶利米在聖殿講道","verses":[{"n":1,"t":"耶和華的話臨到耶利米說：","notes":[]},{"n":2,"t":"「你當站在耶和華殿的門口，在那裏宣傳這話說：你們進這些門敬拜耶和華的一切猶大人，當聽耶和華的話。","notes":[]},{"n":3,"t":"萬軍之耶和華－以色列的神如此說：你們改正行動作為，我就使你們在這地方仍然居住。","notes":[]},{"n":4,"t":"你們不要倚靠虛謊的話，說：『這些是耶和華的殿，是耶和華的殿，是耶和華的殿！』","notes":[]},{"n":5,"t":"「你們若實在改正行動作為，在人和鄰舍中間誠然施行公平，","notes":[]},{"n":6,"t":"不欺壓寄居的和孤兒寡婦，在這地方不流無辜人的血，也不隨從別神陷害自己，","notes":[]},{"n":7,"t":"我就使你們在這地方仍然居住，就是我古時所賜給你們列祖的地，直到永遠。","notes":[]},{"n":8,"t":"「看哪，你們倚靠虛謊無益的話。","notes":[]},{"n":9,"t":"你們偷盜，殺害，姦淫，起假誓，向巴力燒香，並隨從素不認識的別神，","notes":[]},{"n":10,"t":"且來到這稱為我名下的殿，在我面前敬拜；又說：『我們可以自由了。』你們這樣的舉動是要行那些可憎的事嗎？","notes":[]},{"n":11,"t":"這稱為我名下的殿在你們眼中豈可看為賊窩嗎？我都看見了。這是耶和華說的。","notes":[]},{"n":12,"t":"你們且往示羅去，就是我先前立為我名的居所，察看我因這百姓以色列的罪惡向那地所行的如何。」","notes":[]},{"n":13,"t":"耶和華說：「現在因你們行了這一切的事，我也從早起來警戒你們，你們卻不聽從；呼喚你們，你們卻不答應。","notes":[]},{"n":14,"t":"所以我要向這稱為我名下、你們所倚靠的殿，與我所賜給你們和你們列祖的地施行，照我從前向示羅所行的一樣。","notes":[]},{"n":15,"t":"我必將你們從我眼前趕出，正如趕出你們的眾弟兄，就是以法蓮的一切後裔。」","notes":[]},{"n":16,"t":"「所以，你不要為這百姓祈禱；不要為他們呼求禱告，也不要向我為他們祈求，因我不聽允你。","notes":[],"heads":["人民違背命令"]},{"n":17,"t":"他們在猶大城邑中和耶路撒冷街上所行的，你沒有看見嗎？","notes":[]},{"n":18,"t":"孩子撿柴，父親燒火，婦女摶麵做餅，獻給天后，又向別神澆奠祭，惹我發怒。」","notes":[]},{"n":19,"t":"耶和華說：「他們豈是惹我發怒呢？不是自己惹禍，以致臉上慚愧嗎？」","notes":[]},{"n":20,"t":"所以主耶和華如此說：「看哪，我必將我的怒氣和忿怒傾在這地方的人和牲畜身上，並田野的樹木和地裏的出產上，必如火著起，不能熄滅。」","notes":[]},{"n":21,"t":"萬軍之耶和華－以色列的神如此說：「你們將燔祭加在平安祭上，吃肉吧！","notes":[]},{"n":22,"t":"因為我將你們列祖從埃及地領出來的那日，燔祭平安祭的事我並沒有提說，也沒有吩咐他們。","notes":[]},{"n":23,"t":"我只吩咐他們這一件說：『你們當聽從我的話，我就作你們的神，你們也作我的子民。你們行我所吩咐的一切道，就可以得福。』","notes":[]},{"n":24,"t":"他們卻不聽從，不側耳而聽，竟隨從自己的計謀和頑梗的惡心，向後不向前。","notes":[]},{"n":25,"t":"自從你們列祖出埃及地的那日，直到今日，我差遣我的僕人眾先知到你們那裏去，每日從早起來差遣他們。","notes":[]},{"n":26,"t":"你們卻不聽從，不側耳而聽，竟硬著頸項行惡，比你們列祖更甚。","notes":[]},{"n":27,"t":"「你要將這一切的話告訴他們，他們卻不聽從；呼喚他們，他們卻不答應。","notes":[]},{"n":28,"t":"你要對他們說：這就是不聽從耶和華－他們神的話、不受教訓的國民；從他們的口中，誠實滅絕了。」","notes":[]},{"n":29,"t":"耶路撒冷啊，要剪髮拋棄，在淨光的高處舉哀；因為耶和華丟掉離棄了惹他忿怒的世代。","notes":[],"heads":["在欣嫩子谷的罪行"]},{"n":30,"t":"耶和華說：「猶大人行我眼中看為惡的事，將可憎之物設立在稱為我名下的殿中，污穢這殿。","notes":[]},{"n":31,"t":"他們在欣嫩子谷建築陀斐特的邱壇，好在火中焚燒自己的兒女。這並不是我所吩咐的，也不是我心所起的意。」","notes":[]},{"n":32,"t":"耶和華說：「因此，日子將到，這地方不再稱為陀斐特和欣嫩子谷，反倒稱為殺戮谷。因為要在陀斐特葬埋屍首，甚至無處可葬；","notes":[]},{"n":33,"t":"並且這百姓的屍首必給空中的飛鳥和地上的野獸作食物，並無人鬨趕。","notes":[]},{"n":34,"t":"那時，我必使猶大城邑中和耶路撒冷街上，歡喜和快樂的聲音，新郎和新婦的聲音，都止息了，因為地必成為荒場。」","notes":[]}]},"8":{"heading":"罪與罰","verses":[{"n":1,"t":"耶和華說：「到那時，人必將猶大王的骸骨和他首領的骸骨、祭司的骸骨、先知的骸骨，並耶路撒冷居民的骸骨，都從墳墓中取出來，","notes":[]},{"n":2,"t":"拋散在日頭、月亮，和天上眾星之下，就是他們從前所喜愛、所事奉、所隨從、所求問、所敬拜的。這些骸骨不再收殮，不再葬埋，必在地面上成為糞土；","notes":[]},{"n":3,"t":"並且這惡族所剩下的民在我所趕他們到的各處，寧可揀死不揀生。這是萬軍之耶和華說的。」","notes":[]},{"n":4,"t":"你要對他們說，耶和華如此說：人跌倒，不再起來嗎？人轉去，不再轉來嗎？","notes":[]},{"n":5,"t":"這耶路撒冷的民，為何恆久背道呢？他們守定詭詐，不肯回頭。","notes":[]},{"n":6,"t":"我留心聽，聽見他們說不正直的話。無人悔改惡行，說：我做的是甚麼呢？他們各人轉奔己路，如馬直闖戰場。","notes":[]},{"n":7,"t":"空中的鸛鳥知道來去的定期；斑鳩燕子與白鶴也守候當來的時令；我的百姓卻不知道耶和華的法則。","notes":[]},{"n":8,"t":"你們怎麼說：我們有智慧，耶和華的律法在我們這裏？看哪，文士的假筆舞弄虛假。","notes":[]},{"n":9,"t":"智慧人慚愧，驚惶，被擒拿；他們棄掉耶和華的話，心裏還有甚麼智慧呢？","notes":[]},{"n":10,"t":"所以我必將他們的妻子給別人，將他們的田地給別人為業；因為他們從最小的到至大的都一味地貪婪，從先知到祭司都行事虛謊。","notes":[]},{"n":11,"t":"他們輕輕忽忽地醫治我百姓的損傷，說：平安了！平安了！其實沒有平安。","notes":[]},{"n":12,"t":"他們行可憎的事知道慚愧嗎？不然，他們毫不慚愧，也不知羞恥。因此他們必在仆倒的人中仆倒；我向他們討罪的時候，他們必致跌倒。這是耶和華說的。","notes":[]},{"n":13,"t":"耶和華說：我必使他們全然滅絕；葡萄樹上必沒有葡萄，無花果樹上必沒有果子，葉子也必枯乾。我所賜給他們的，必離開他們過去。","notes":[]},{"n":14,"t":"我們為何靜坐不動呢？我們當聚集，進入堅固城，在那裏靜默不言；因為耶和華－我們的神使我們靜默不言，又將苦膽水給我們喝，都因我們得罪了耶和華。","notes":[]},{"n":15,"t":"我們指望平安，卻得不著好處；指望痊癒的時候，不料，受了驚惶。","notes":[]},{"n":16,"t":"聽見從但那裏敵人的馬噴鼻氣，他的壯馬發嘶聲，全地就都震動；因為他們來吞滅這地和其上所有的，吞滅這城與其中的居民。","notes":[]},{"n":17,"t":"看哪，我必使毒蛇到你們中間，是不服法術的，必咬你們。這是耶和華說的。","notes":[]},{"n":18,"t":"我有憂愁，願能自慰；我心在我裏面發昏。","notes":[],"heads":["耶利米為同胞悲傷"]},{"n":19,"t":"聽啊，是我百姓的哀聲從極遠之地而來，說：耶和華不在錫安嗎？錫安的王不在其中嗎？耶和華說：他們為甚麼以雕刻的偶像和外邦虛無的神惹我發怒呢？","notes":[]},{"n":20,"t":"麥秋已過，夏令已完，我們還未得救！","notes":[]},{"n":21,"t":"先知說：因我百姓的損傷，我也受了損傷。我哀痛，驚惶將我抓住。","notes":[]},{"n":22,"t":"在基列豈沒有乳香呢？在那裏豈沒有醫生呢？我百姓為何不得痊癒呢？","notes":[]}]},"9":{"heading":"耶路撒冷哀求援助","verses":[{"n":1,"t":"但願我的頭為水，我的眼為淚的泉源，我好為我百姓中被殺的人晝夜哭泣。","notes":["原文是民女；七節同"]},{"n":2,"t":"惟願我在曠野有行路人住宿之處，使我可以離開我的民出去；因他們都是行姦淫的，是行詭詐的一黨。","notes":[]},{"n":3,"t":"他們彎起舌頭像弓一樣，為要說謊話。他們在國中增長勢力，不是為行誠實，乃是惡上加惡，並不認識我。這是耶和華說的。","notes":[]},{"n":4,"t":"你們各人當謹防鄰舍，不可信靠弟兄；因為弟兄盡行欺騙，鄰舍都往來讒謗人。","notes":[]},{"n":5,"t":"他們各人欺哄鄰舍，不說真話；他們教舌頭學習說謊，勞勞碌碌地作孽。","notes":[]},{"n":6,"t":"你的住處在詭詐的人中；他們因行詭詐，不肯認識我。這是耶和華說的。","notes":[]},{"n":7,"t":"所以萬軍之耶和華如此說：看哪，我要將他們鎔化熬煉；不然，我因我百姓的罪該怎樣行呢？","notes":[]},{"n":8,"t":"他們的舌頭是毒箭，說話詭詐；人與鄰舍口說和平話，心卻謀害他。","notes":[]},{"n":9,"t":"耶和華說：我豈不因這些事討他們的罪呢？豈不報復這樣的國民呢？","notes":[]},{"n":10,"t":"我要為山嶺哭泣悲哀，為曠野的草場揚聲哀號；因為都已乾焦，甚至無人經過。人也聽不見牲畜鳴叫，空中的飛鳥和地上的野獸都已逃去。","notes":[]},{"n":11,"t":"我必使耶路撒冷變為亂堆，為野狗的住處，也必使猶大的城邑變為荒場，無人居住。","notes":[]},{"n":12,"t":"誰是智慧人，可以明白這事？耶和華的口向誰說過，使他可以傳說？遍地為何滅亡，乾焦好像曠野，甚至無人經過呢？","notes":[]},{"n":13,"t":"耶和華說：「因為這百姓離棄我在他們面前所設立的律法，沒有遵行，也沒有聽從我的話；","notes":[]},{"n":14,"t":"只隨從自己頑梗的心行事，照他們列祖所教訓的隨從眾巴力。」","notes":[]},{"n":15,"t":"所以萬軍之耶和華－以色列的神如此說：「看哪，我必將茵蔯給這百姓吃，又將苦膽水給他們喝。","notes":[]},{"n":16,"t":"我要把他們散在列邦中，就是他們和他們列祖素不認識的列邦。我也要使刀劍追殺他們，直到將他們滅盡。」","notes":[]},{"n":17,"t":"萬軍之耶和華如此說：你們應當思想，將善唱哀歌的婦女召來，又打發人召善哭的婦女來，","notes":[]},{"n":18,"t":"叫她們速速為我們舉哀，使我們眼淚汪汪，使我們的眼皮湧出水來。","notes":[]},{"n":19,"t":"因為聽見哀聲出於錫安，說：我們怎樣敗落了！我們大大地慚愧！我們撇下地土；人也拆毀了我們的房屋。","notes":[]},{"n":20,"t":"婦女們哪，你們當聽耶和華的話，領受他口中的言語；又當教導你們的兒女舉哀，各人教導鄰舍唱哀歌。","notes":[]},{"n":21,"t":"因為死亡上來，進了我們的窗戶，入了我們的宮殿；要從外邊剪除孩童，從街上剪除少年人。","notes":[]},{"n":22,"t":"你當說，耶和華如此說：人的屍首必倒在田野像糞土，又像收割的人遺落的一把禾稼，無人收取。","notes":[]},{"n":23,"t":"耶和華如此說：「智慧人不要因他的智慧誇口，勇士不要因他的勇力誇口，財主不要因他的財物誇口。","notes":[]},{"n":24,"t":"誇口的卻因他有聰明，認識我是耶和華，又知道我喜悅在世上施行慈愛、公平，和公義，以此誇口。這是耶和華說的。」","notes":[]},{"n":25,"t":"耶和華說：「看哪，日子將到，我要刑罰一切受過割禮、心卻未受割禮的，","notes":[]},{"n":26,"t":"就是埃及、猶大、以東、亞捫人、摩押人，和一切住在曠野剃周圍頭髮的；因為列國人都沒有受割禮，以色列人心中也沒有受割禮。」","notes":[]}]},"10":{"heading":"拜偶像和真敬拜","verses":[{"n":1,"t":"以色列家啊，要聽耶和華對你們所說的話。","notes":[]},{"n":2,"t":"耶和華如此說：你們不要效法列國的行為，也不要為天象驚惶，因列國為此事驚惶。","notes":[]},{"n":3,"t":"眾民的風俗是虛空的；他們在樹林中用斧子砍伐一棵樹，匠人用手工造成偶像。","notes":[]},{"n":4,"t":"他們用金銀妝飾它，用釘子和錘子釘穩，使它不動搖。","notes":[]},{"n":5,"t":"它好像棕樹，是鏇成的，不能說話，不能行走，必須有人抬著。你們不要怕它；它不能降禍，也無力降福。","notes":[]},{"n":6,"t":"耶和華啊，沒有能比你的！你本為大，有大能大力的名。","notes":[]},{"n":7,"t":"萬國的王啊，誰不敬畏你？敬畏你本是合宜的；因為在列國的智慧人中，雖有政權的尊榮，也不能比你。","notes":[]},{"n":8,"t":"他們盡都是畜類，是愚昧的。偶像的訓誨算甚麼呢？偶像不過是木頭。","notes":[]},{"n":9,"t":"有銀子打成片，是從他施帶來的，並有從烏法來的金子，都是匠人和銀匠的手工，又有藍色紫色料的衣服，都是巧匠的工作。","notes":[]},{"n":10,"t":"惟耶和華是真神，是活神，是永遠的王。他一發怒，大地震動；他一惱恨，列國都擔當不起。（","notes":[]},{"n":11,"t":"你們要對他們如此說：不是那創造天地的神，必從地上從天下被除滅！）","notes":[]},{"n":12,"t":"耶和華用能力創造大地，用智慧建立世界，用聰明鋪張穹蒼。","notes":[],"heads":["頌讚神的詩"]},{"n":13,"t":"他一發聲，空中便有多水激動；他使雲霧從地極上騰；他造電隨雨而閃，從他府庫中帶出風來。","notes":[]},{"n":14,"t":"各人都成了畜類，毫無知識；各銀匠都因他雕刻的偶像羞愧。他所鑄的偶像本是虛假的，其中並無氣息，","notes":[]},{"n":15,"t":"都是虛無的，是迷惑人的工作；到追討的時候必被除滅。","notes":[]},{"n":16,"t":"雅各的分不像這些，因他是造作萬有的主。以色列也是他產業的支派，萬軍之耶和華是他的名。","notes":[]},{"n":17,"t":"受圍困的人哪，當收拾你的財物，從國中帶出去。","notes":[],"heads":["預告被擄"]},{"n":18,"t":"因為耶和華如此說：這時候，我必將此地的居民，好像用機弦甩出去，又必加害在他們身上，使他們覺悟。","notes":[]},{"n":19,"t":"民說：禍哉！我受損傷；我的傷痕極其重大。我卻說：這真是我的痛苦，必須忍受。","notes":[]},{"n":20,"t":"我的帳棚毀壞；我的繩索折斷。我的兒女離我出去，沒有了。無人再支搭我的帳棚，掛起我的幔子。","notes":[]},{"n":21,"t":"因為牧人都成為畜類，沒有求問耶和華，所以不得順利；他們的羊群也都分散。","notes":[]},{"n":22,"t":"有風聲！看哪，敵人來了！有大擾亂從北方出來，要使猶大城邑變為荒涼，成為野狗的住處。","notes":[]},{"n":23,"t":"耶和華啊，我曉得人的道路不由自己，行路的人也不能定自己的腳步。","notes":[]},{"n":24,"t":"耶和華啊，求你從寬懲治我，不要在你的怒中懲治我，恐怕使我歸於無有。","notes":[]},{"n":25,"t":"願你將忿怒傾在不認識你的列國中，和不求告你名的各族上；因為他們吞了雅各，不但吞了，而且滅絕，把他的住處變為荒場。","notes":[]}]},"11":{"heading":"耶利米和約","verses":[{"n":1,"t":"耶和華的話臨到耶利米說：","notes":[]},{"n":2,"t":"「當聽這約的話，告訴猶大人和耶路撒冷的居民，","notes":[]},{"n":3,"t":"對他們說，耶和華－以色列的神如此說：不聽從這約之話的人必受咒詛。","notes":[]},{"n":4,"t":"這約是我將你們列祖從埃及地領出來、脫離鐵爐的那日所吩咐他們的，說：『你們要聽從我的話，照我一切所吩咐的去行。』這樣，你們就作我的子民，我也作你們的神；","notes":[]},{"n":5,"t":"我好堅定向你們列祖所起的誓，給他們流奶與蜜之地，正如今日一樣。」我就回答說：「耶和華啊，阿們！」","notes":[]},{"n":6,"t":"耶和華對我說：「你要在猶大城邑中和耶路撒冷街市上，宣告這一切話說：你們當聽從遵行這約的話。","notes":[]},{"n":7,"t":"因為我將你們列祖從埃及地領出來的那日，直到今日，都是從早起來，切切誥誡他們說：『你們當聽從我的話。』","notes":[]},{"n":8,"t":"他們卻不聽從，不側耳而聽，竟隨從自己頑梗的惡心去行。所以我使這約中一切咒詛的話臨到他們身上；這約是我吩咐他們行的，他們卻不去行。」","notes":[]},{"n":9,"t":"耶和華對我說：「在猶大人和耶路撒冷居民中有同謀背叛的事。","notes":[]},{"n":10,"t":"他們轉去效法他們的先祖，不肯聽我的話，犯罪作孽，又隨從別神，事奉它。以色列家和猶大家背了我與他們列祖所立的約。」","notes":[]},{"n":11,"t":"所以耶和華如此說：「我必使災禍臨到他們，是他們不能逃脫的。他們必向我哀求，我卻不聽。","notes":[]},{"n":12,"t":"那時，猶大城邑的人和耶路撒冷的居民要去哀求他們燒香所供奉的神；只是遭難的時候，這些神毫不拯救他們。","notes":[]},{"n":13,"t":"猶大啊，你神的數目與你城的數目相等；你為那可恥的巴力所築燒香的壇也與耶路撒冷街道的數目相等。","notes":[]},{"n":14,"t":"「所以你不要為這百姓祈禱，不要為他們呼求禱告；因為他們遭難向我哀求的時候，我必不應允。","notes":[]},{"n":15,"t":"我所親愛的，既行許多淫亂，聖肉也離了你，你在我殿中做甚麼呢？你作惡就喜樂。","notes":[]},{"n":16,"t":"從前耶和華給你起名叫青橄欖樹，又華美又結好果子；如今他用鬨嚷之聲，點火在其上，枝子也被折斷。","notes":[]},{"n":17,"t":"原來栽培你的萬軍之耶和華已經說，要降禍攻擊你，是因以色列家和猶大家行惡，向巴力燒香，惹我發怒，是自作自受。」","notes":[]},{"n":18,"t":"耶和華指示我，我就知道；你將他們所行的給我指明。","notes":[],"heads":["殺害耶利米的陰謀"]},{"n":19,"t":"我卻像柔順的羊羔被牽到宰殺之地；我並不知道他們設計謀害我，說：我們把樹連果子都滅了吧！將他從活人之地剪除，使他的名不再被紀念。","notes":[]},{"n":20,"t":"按公義判斷、察驗人肺腑心腸的萬軍之耶和華啊，我卻要見你在他們身上報仇，因我將我的案件向你稟明了。","notes":[]},{"n":21,"t":"所以，耶和華論到尋索你命的亞拿突人如此說：「他們說：你不要奉耶和華的名說預言，免得你死在我們手中。","notes":[]},{"n":22,"t":"所以萬軍之耶和華如此說：看哪，我必刑罰他們；他們的少年人必被刀劍殺死，他們的兒女必因饑荒滅亡，","notes":[]},{"n":23,"t":"並且沒有餘剩的人留給他們；因為在追討之年，我必使災禍臨到亞拿突人。」","notes":[]}]},"12":{"heading":"耶利米詢問耶和華","verses":[{"n":1,"t":"耶和華啊，我與你爭辯的時候，你顯為義；但有一件，我還要與你理論：惡人的道路為何亨通呢？大行詭詐的為何得安逸呢？","notes":[]},{"n":2,"t":"你栽培了他們，他們也扎了根，長大，而且結果。他們的口是與你相近，心卻與你遠離。","notes":[]},{"n":3,"t":"耶和華啊，你曉得我，看見我，察驗我向你是怎樣的心。求你將他們拉出來，好像將宰的羊，叫他們等候殺戮的日子。","notes":[]},{"n":4,"t":"這地悲哀，通國的青草枯乾，要到幾時呢？因其上居民的惡行，牲畜和飛鳥都滅絕了。他們曾說：他看不見我們的結局。","notes":[]},{"n":5,"t":"耶和華說：你若與步行的人同跑，尚且覺累，怎能與馬賽跑呢？你在平安之地，雖然安穩，在約旦河邊的叢林要怎樣行呢？","notes":[]},{"n":6,"t":"因為連你弟兄和你父家都用奸詐待你。他們也在你後邊大聲喊叫，雖向你說好話，你也不要信他們。","notes":[]},{"n":7,"t":"我離了我的殿宇，撇棄我的產業，將我心裏所親愛的交在她仇敵的手中。","notes":[],"heads":["耶和華為他的子民憂傷"]},{"n":8,"t":"我的產業向我如林中的獅子，她發聲攻擊我，因此我恨惡她。","notes":[]},{"n":9,"t":"我的產業向我豈如斑點的鷙鳥呢？鷙鳥豈在她四圍攻擊她呢？你們要去聚集田野的百獸，帶來吞吃吧！","notes":[]},{"n":10,"t":"許多牧人毀壞我的葡萄園，踐踏我的分，使我美好的分變為荒涼的曠野。","notes":[]},{"n":11,"t":"他們使地荒涼；地既荒涼，便向我悲哀。全地荒涼，因無人介意。","notes":[]},{"n":12,"t":"滅命的都來到曠野中一切淨光的高處；耶和華的刀從地這邊直到地那邊盡行殺滅。凡有血氣的都不得平安。","notes":[]},{"n":13,"t":"他們種的是麥子，收的是荊棘；勞勞苦苦卻毫無益處。因耶和華的烈怒，你們必為自己的土產羞愧。","notes":[]},{"n":14,"t":"耶和華如此說：「一切惡鄰，就是佔據我使百姓以色列所承受產業的，我要將他們拔出本地，又要將猶大家從他們中間拔出來。","notes":[],"heads":["耶和華對以色列鄰國的許諾"]},{"n":15,"t":"我拔出他們以後，我必轉過來憐憫他們，把他們再帶回來，各歸本業，各歸故土。","notes":[]},{"n":16,"t":"他們若殷勤學習我百姓的道，指著我的名起誓說：『我指著永生的耶和華起誓』，正如他們從前教我百姓指著巴力起誓，他們就必建立在我百姓中間。","notes":[]},{"n":17,"t":"他們若是不聽，我必拔出那國，拔出而且毀滅。這是耶和華說的。」","notes":[]}]},"13":{"heading":"腰帶的比喻","verses":[{"n":1,"t":"耶和華對我如此說：「你去買一根麻布帶子束腰，不可放在水中。」","notes":[]},{"n":2,"t":"我就照著耶和華的話，買了一根帶子束腰。","notes":[]},{"n":3,"t":"耶和華的話第二次臨到我說：","notes":[]},{"n":4,"t":"「要拿著你所買的腰帶，就是你腰上的帶子，起來往幼發拉底河去，將腰帶藏在那裏的磐石穴中。」","notes":[]},{"n":5,"t":"我就去，照著耶和華所吩咐我的，將腰帶藏在幼發拉底河邊。","notes":[]},{"n":6,"t":"過了多日，耶和華對我說：「你起來往幼發拉底河去，將我吩咐你藏在那裏的腰帶取出來。」","notes":[]},{"n":7,"t":"我就往幼發拉底河去，將腰帶從我所藏的地方刨出來，見腰帶已經變壞，毫無用了。","notes":[]},{"n":8,"t":"耶和華的話臨到我說：","notes":[]},{"n":9,"t":"「耶和華如此說：我必照樣敗壞猶大的驕傲和耶路撒冷的大驕傲。","notes":[]},{"n":10,"t":"這惡民不肯聽我的話，按自己頑梗的心而行，隨從別神，事奉敬拜，他們也必像這腰帶變為無用。」","notes":[]},{"n":11,"t":"耶和華說：「腰帶怎樣緊貼人腰，照樣，我也使以色列全家和猶大全家緊貼我，好叫他們屬我為子民，使我得名聲，得頌讚，得榮耀；他們卻不肯聽。」","notes":[]},{"n":12,"t":"「所以你要對他們說：『耶和華－以色列的神如此說：各罈都要盛滿了酒。』他們必對你說：『我們豈不確知各罈都要盛滿了酒呢？』","notes":[],"heads":["酒罈的比喻"]},{"n":13,"t":"你就要對他們說：『耶和華如此說：我必使這地的一切居民，就是坐大衛寶座的君王和祭司，與先知，並耶路撒冷的一切居民，都酩酊大醉。』」","notes":[]},{"n":14,"t":"耶和華說：「我要使他們彼此相碰，就是父與子彼此相碰；我必不可憐，不顧惜，不憐憫，以致滅絕他們。」","notes":[]},{"n":15,"t":"你們當聽，當側耳而聽。不要驕傲，因為耶和華已經說了。","notes":[],"heads":["耶利米警告狂傲的行為"]},{"n":16,"t":"耶和華－你們的神未使黑暗來到，你們的腳未在昏暗山上絆跌之先，當將榮耀歸給他；免得你們盼望光明，他使光明變為死蔭，成為幽暗。","notes":[]},{"n":17,"t":"你們若不聽這話，我必因你們的驕傲在暗地哭泣；我眼必痛哭流淚，因為耶和華的群眾被擄去了。","notes":[]},{"n":18,"t":"你要對君王和太后說：你們當自卑，坐在下邊；因你們的頭巾，就是你們的華冠，已經脫落了。","notes":[]},{"n":19,"t":"南方的城盡都關閉，無人開放；猶大全被擄掠，且擄掠淨盡。","notes":[]},{"n":20,"t":"你們要舉目觀看從北方來的人。先前賜給你的群眾，就是你佳美的群眾，如今在哪裏呢？","notes":[]},{"n":21,"t":"耶和華立你自己所交的朋友為首，轄制你，那時你還有甚麼話說呢？痛苦豈不將你抓住像產難的婦人嗎？","notes":[]},{"n":22,"t":"你若心裏說：這一切事為何臨到我呢？你的衣襟揭起，你的腳跟受傷，是因你的罪孽甚多。","notes":[]},{"n":23,"t":"古實人豈能改變皮膚呢？豹豈能改變斑點呢？若能，你們這習慣行惡的便能行善了。","notes":[]},{"n":24,"t":"所以我必用曠野的風吹散他們，像吹過的碎稭一樣。","notes":[]},{"n":25,"t":"耶和華說：這是你所當得的，是我量給你的分；因為你忘記我，倚靠虛假。","notes":["或譯：偶像"]},{"n":26,"t":"所以我要揭起你的衣襟，蒙在你臉上，顯出你的醜陋。","notes":[]},{"n":27,"t":"你那些可憎惡之事－就是在田野的山上行姦淫，發嘶聲，做淫亂的事－我都看見了。耶路撒冷啊，你有禍了！你不肯潔淨，還要到幾時呢？","notes":[]}]},"14":{"heading":"可怕的旱災","verses":[{"n":1,"t":"耶和華論到乾旱之災的話臨到耶利米：","notes":[]},{"n":2,"t":"猶大悲哀，城門衰敗。眾人披上黑衣坐在地上；耶路撒冷的哀聲上達。","notes":[]},{"n":3,"t":"他們的貴冑打發家僮打水；他們來到水池，見沒有水，就拿著空器皿，蒙羞慚愧，抱頭而回。","notes":[]},{"n":4,"t":"耕地的也蒙羞抱頭；因為無雨降在地上，地都乾裂。","notes":[]},{"n":5,"t":"田野的母鹿生下小鹿，就撇棄，因為無草。","notes":[]},{"n":6,"t":"野驢站在淨光的高處，喘氣好像野狗；因為無草，眼目失明。","notes":[]},{"n":7,"t":"耶和華啊，我們的罪孽雖然作見證告我們，還求你為你名的緣故行事。我們本是多次背道，得罪了你。","notes":[]},{"n":8,"t":"以色列所盼望、在患難時作他救主的啊，你為何在這地像寄居的，又像行路的只住一宵呢？","notes":[]},{"n":9,"t":"你為何像受驚的人，像不能救人的勇士呢？耶和華啊，你仍在我們中間；我們也稱為你名下的人，求你不要離開我們。","notes":[]},{"n":10,"t":"耶和華對這百姓如此說：這百姓喜愛妄行，不禁止腳步，所以耶和華不悅納他們。現今要記念他們的罪孽，追討他們的罪惡。","notes":["原文是飄流"]},{"n":11,"t":"耶和華又對我說：「不要為這百姓祈禱求好處。","notes":[]},{"n":12,"t":"他們禁食的時候，我不聽他們的呼求；他們獻燔祭和素祭，我也不悅納；我卻要用刀劍、饑荒、瘟疫滅絕他們。」","notes":[]},{"n":13,"t":"我就說：「唉！主耶和華啊，那些先知常對他們說：『你們必不看見刀劍，也不遭遇饑荒；耶和華要在這地方賜你們長久的平安。』」","notes":[]},{"n":14,"t":"耶和華對我說：「那些先知託我的名說假預言，我並沒有打發他們，沒有吩咐他們，也沒有對他們說話；他們向你們預言的，乃是虛假的異象和占卜，並虛無的事，以及本心的詭詐。","notes":[]},{"n":15,"t":"所以耶和華如此說：論到託我名說預言的那些先知，我並沒有打發他們；他們還說這地不能有刀劍饑荒，其實那些先知必被刀劍饑荒滅絕。","notes":[]},{"n":16,"t":"聽他們說預言的百姓必因饑荒刀劍拋在耶路撒冷的街道上，無人葬埋。他們連妻子帶兒女，都是如此。我必將他們的惡倒在他們身上。」","notes":["或譯：我必使他們罪惡的報應臨到他們身上"]},{"n":17,"t":"你要將這話對他們說：願我眼淚汪汪，晝夜不息，因為我百姓受了裂口破壞的大傷。","notes":["原文是民的處女"]},{"n":18,"t":"我若出往田間，就見有被刀殺的；我若進入城內，就見有因饑荒患病的；連先知帶祭司在國中往來，也是毫無知識。","notes":["或譯：不知怎樣才好"]},{"n":19,"t":"你全然棄掉猶大嗎？你心厭惡錫安嗎？為何擊打我們，以致無法醫治呢？我們指望平安，卻得不著好處；指望痊癒，不料，受了驚惶。","notes":[],"heads":["百姓懇求耶和華憐憫"]},{"n":20,"t":"耶和華啊，我們承認自己的罪惡，和我們列祖的罪孽，因我們得罪了你。","notes":[]},{"n":21,"t":"求你為你名的緣故，不厭惡我們，不辱沒你榮耀的寶座。求你追念，不要背了與我們所立的約。","notes":[]},{"n":22,"t":"外邦人虛無的神中有能降雨的嗎？天能自降甘霖嗎？耶和華－我們的神啊，能如此的不是你嗎？所以，我們仍要等候你，因為這一切都是你所造的。","notes":[]}]},"15":{"heading":"猶大百姓的厄運","verses":[{"n":1,"t":"耶和華對我說：「雖有摩西和撒母耳站在我面前代求，我的心也不顧惜這百姓。你將他們從我眼前趕出，叫他們去吧！","notes":[]},{"n":2,"t":"他們問你說：『我們往哪裏去呢？』你便告訴他們，耶和華如此說：定為死亡的，必致死亡；定為刀殺的，必交刀殺；定為饑荒的，必遭饑荒；定為擄掠的，必被擄掠。」","notes":[]},{"n":3,"t":"耶和華說：「我命定四樣害他們，就是刀劍殺戮、狗類撕裂、空中的飛鳥，和地上的野獸吞吃毀滅；","notes":[]},{"n":4,"t":"又必使他們在天下萬國中拋來拋去，都因猶大王希西家的兒子瑪拿西在耶路撒冷所行的事。」","notes":[]},{"n":5,"t":"耶路撒冷啊，誰可憐你呢？誰為你悲傷呢？誰轉身問你的安呢？","notes":[]},{"n":6,"t":"耶和華說：你棄絕了我，轉身退後；因此我伸手攻擊你，毀壞你。我後悔甚不耐煩。","notes":[]},{"n":7,"t":"我在境內各城門口，用簸箕簸了我的百姓，使他們喪掉兒女。我毀滅他們，他們仍不轉離所行的道。","notes":["或譯：我在這地邊界的關口"]},{"n":8,"t":"他們的寡婦在我面前比海沙更多；我使滅命的午間來，攻擊少年人的母親，使痛苦驚嚇忽然臨到她身上。","notes":[]},{"n":9,"t":"生過七子的婦人力衰氣絕；尚在白晝，日頭忽落；她抱愧蒙羞。其餘的人，我必在他們敵人跟前，交與刀劍。這是耶和華說的。","notes":[]},{"n":10,"t":"我的母親哪，我有禍了！因你生我作為遍地相爭相競的人。我素來沒有借貸與人，人也沒有借貸與我，人人卻都咒罵我。","notes":[],"heads":["耶利米向耶和華訴苦"]},{"n":11,"t":"耶和華說：「我必要堅固你，使你得好處。災禍苦難臨到的時候，我必要使仇敵央求你。（","notes":[]},{"n":12,"t":"人豈能將銅與鐵，就是北方的鐵折斷呢？）","notes":[]},{"n":13,"t":"「我必因你在四境之內所犯的一切罪，把你的貨物財寶當掠物，白白地交給仇敵。","notes":[]},{"n":14,"t":"我也必使仇敵帶這掠物到你所不認識的地去，因我怒中起的火要將你們焚燒。」","notes":[]},{"n":15,"t":"耶和華啊，你是知道的；求你記念我，眷顧我，向逼迫我的人為我報仇；不要向他們忍怒取我的命，要知道我為你的緣故受了凌辱。","notes":[]},{"n":16,"t":"耶和華－萬軍之神啊，我得著你的言語就當食物吃了；你的言語是我心中的歡喜快樂，因我是稱為你名下的人。","notes":[]},{"n":17,"t":"我沒有坐在宴樂人的會中，也沒有歡樂；我因你的感動獨自靜坐，因你使我滿心憤恨。","notes":["原文是手"]},{"n":18,"t":"我的痛苦為何長久不止呢？我的傷痕為何無法醫治、不能痊癒呢？難道你待我有詭詐，像流乾的河道嗎？","notes":[]},{"n":19,"t":"耶和華如此說：你若歸回，我就將你再帶來，使你站在我面前；你若將寶貴的和下賤的分別出來，你就可以當作我的口。他們必歸向你，你卻不可歸向他們。","notes":[]},{"n":20,"t":"我必使你向這百姓成為堅固的銅牆；他們必攻擊你，卻不能勝你；因我與你同在，要拯救你，搭救你。這是耶和華說的。","notes":[]},{"n":21,"t":"我必搭救你脫離惡人的手，救贖你脫離強暴人的手。","notes":[]}]},"16":{"heading":"耶和華要耶利米過孤獨的生活","verses":[{"n":1,"t":"耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「你在這地方不可娶妻，生兒養女。","notes":[]},{"n":3,"t":"因為論到在這地方所生的兒女，又論到在這國中生養他們的父母，耶和華如此說：","notes":[]},{"n":4,"t":"他們必死得甚苦，無人哀哭，必不得葬埋，必在地上像糞土，必被刀劍和饑荒滅絕；他們的屍首必給空中的飛鳥和地上的野獸作食物。」","notes":[]},{"n":5,"t":"耶和華如此說：「不要進入喪家，不要去哀哭，也不要為他們悲傷，因我已將我的平安、慈愛、憐憫從這百姓奪去了。這是耶和華說的。","notes":[]},{"n":6,"t":"連大帶小，都必在這地死亡，不得葬埋。人必不為他們哀哭，不用刀劃身，也不使頭光禿。","notes":[]},{"n":7,"t":"他們有喪事，人必不為他們擘餅，因死人安慰他們；他們喪父喪母，人也不給他們一杯酒安慰他們。","notes":[]},{"n":8,"t":"你不可進入宴樂的家，與他們同坐吃喝。","notes":[]},{"n":9,"t":"因為萬軍之耶和華－以色列的神如此說：你們還活著的日子在你們眼前，我必使歡喜和快樂的聲音，新郎和新婦的聲音，從這地方止息了。","notes":[]},{"n":10,"t":"「你將這一切的話指示這百姓。他們問你說：『耶和華為甚麼說，要降這大災禍攻擊我們呢？我們有甚麼罪孽呢？我們向耶和華－我們的神犯了甚麼罪呢？』","notes":[]},{"n":11,"t":"你就對他們說：『耶和華說：因為你們列祖離棄我，隨從別神，事奉敬拜，不遵守我的律法，","notes":[]},{"n":12,"t":"而且你們行惡比你們列祖更甚；因為各人隨從自己頑梗的惡心行事，甚至不聽從我，","notes":[]},{"n":13,"t":"所以我必將你們從這地趕出，直趕到你們和你們列祖素不認識的地。你們在那裏必晝夜事奉別神，因為我必不向你們施恩。』」","notes":[]},{"n":14,"t":"耶和華說：「日子將到，人必不再指著那領以色列人從埃及地上來之永生的耶和華起誓，","notes":[],"heads":["從流亡中回國"]},{"n":15,"t":"卻要指著那領以色列人從北方之地，並趕他們到的各國上來之永生的耶和華起誓，並且我要領他們再入我從前賜給他們列祖之地。」","notes":[]},{"n":16,"t":"耶和華說：「我要召許多打魚的把以色列人打上來，然後我要召許多打獵的，從各山上、各岡上、各石穴中獵取他們。","notes":[],"heads":["將要臨到的懲罰"]},{"n":17,"t":"因我的眼目察看他們的一切行為；他們不能在我面前遮掩，他們的罪孽也不能在我眼前隱藏。","notes":[]},{"n":18,"t":"我先要加倍報應他們的罪孽和罪惡；因為他們用可憎之屍玷污我的地土，又用可厭之物充滿我的產業。」","notes":[]},{"n":19,"t":"耶和華啊，你是我的力量，是我的保障；在苦難之日是我的避難所。列國人必從地極來到你這裏，說：我們列祖所承受的，不過是虛假，是虛空無益之物。","notes":[],"heads":["耶利米的信心祈禱"]},{"n":20,"t":"人豈可為自己製造神呢？其實這不是神。","notes":[]},{"n":21,"t":"耶和華說：「我要使他們知道，就是這一次使他們知道我的手和我的能力。他們就知道我的名是耶和華了。」","notes":[]}]},"17":{"heading":"猶大的罪和懲罰","verses":[{"n":1,"t":"猶大的罪是用鐵筆、用金鋼鑽記錄的，銘刻在他們的心版上和壇角上。","notes":[]},{"n":2,"t":"他們的兒女記念他們高岡上、青翠樹旁的壇和木偶。","notes":[]},{"n":3,"t":"我田野的山哪，我必因你在四境之內所犯的罪，把你的貨物、財寶，並邱壇當掠物交給仇敵；","notes":[]},{"n":4,"t":"並且你因自己的罪必失去我所賜給你的產業。我也必使你在你所不認識的地上服事你的仇敵；因為你使我怒中起火，直燒到永遠。","notes":[]},{"n":5,"t":"耶和華如此說：倚靠人血肉的膀臂，心中離棄耶和華的，那人有禍了！","notes":[],"heads":["訓誨集"]},{"n":6,"t":"因他必像沙漠的杜松，不見福樂來到，卻要住曠野乾旱之處，無人居住的鹼地。","notes":[]},{"n":7,"t":"倚靠耶和華、以耶和華為可靠的，那人有福了！","notes":[]},{"n":8,"t":"他必像樹栽於水旁，在河邊扎根，炎熱來到，並不懼怕，葉子仍必青翠，在乾旱之年毫無掛慮，而且結果不止。","notes":[]},{"n":9,"t":"人心比萬物都詭詐，壞到極處，誰能識透呢？","notes":[]},{"n":10,"t":"我－耶和華是鑒察人心、試驗人肺腑的，要照各人所行的和他做事的結果報應他。","notes":[]},{"n":11,"t":"那不按正道得財的，好像鷓鴣菢不是自己下的蛋；到了中年，那財都必離開他，他終久成為愚頑人。","notes":[]},{"n":12,"t":"我們的聖所是榮耀的寶座，從太初安置在高處。","notes":[]},{"n":13,"t":"耶和華－以色列的盼望啊，凡離棄你的必致蒙羞。耶和華說：離開我的，他們的名字必寫在土裏，因為他們離棄我這活水的泉源。","notes":[]},{"n":14,"t":"耶和華啊，求你醫治我，我便痊癒，拯救我，我便得救；因你是我所讚美的。","notes":[],"heads":["耶利米求耶和華幫助"]},{"n":15,"t":"他們對我說：耶和華的話在哪裏呢？叫這話應驗吧！","notes":[]},{"n":16,"t":"至於我，那跟從你作牧人的職分，我並沒有急忙離棄，也沒有想那災殃的日子；這是你知道的。我口中所出的言語都在你面前。","notes":[]},{"n":17,"t":"不要使我因你驚恐；當災禍的日子，你是我的避難所。","notes":[]},{"n":18,"t":"願那些逼迫我的蒙羞，卻不要使我蒙羞；使他們驚惶，卻不要使我驚惶；使災禍的日子臨到他們，以加倍的毀壞毀壞他們。","notes":[]},{"n":19,"t":"耶和華對我如此說：「你去站在平民的門口，就是猶大君王出入的門，又站在耶路撒冷的各門口，","notes":[],"heads":["關於遵守安息日"]},{"n":20,"t":"對他們說：『你們這猶大君王和猶大眾人，並耶路撒冷的一切居民，凡從這些門進入的都當聽耶和華的話。","notes":[]},{"n":21,"t":"耶和華如此說：你們要謹慎，不要在安息日擔甚麼擔子進入耶路撒冷的各門；","notes":[]},{"n":22,"t":"也不要在安息日從家中擔出擔子去。無論何工都不可做，只要以安息日為聖日，正如我所吩咐你們列祖的。』","notes":[]},{"n":23,"t":"他們卻不聽從，不側耳而聽，竟硬著頸項不聽，不受教訓。」","notes":[]},{"n":24,"t":"耶和華說：「你們若留意聽從我，在安息日不擔甚麼擔子進入這城的各門，只以安息日為聖日，在那日無論何工都不做；","notes":[]},{"n":25,"t":"那時就有坐大衛寶座的君王和首領，他們與猶大人，並耶路撒冷的居民，或坐車，或騎馬，進入這城的各門，而且這城必存到永遠。","notes":[]},{"n":26,"t":"也必有人從猶大城邑和耶路撒冷四圍的各處，從便雅憫地、高原、山地，並南地而來，都帶燔祭、平安祭、素祭，和乳香，並感謝祭，到耶和華的殿去。","notes":[]},{"n":27,"t":"你們若不聽從我，不以安息日為聖日，仍在安息日擔擔子，進入耶路撒冷的各門，我必在各門中點火；這火也必燒毀耶路撒冷的宮殿，不能熄滅。」","notes":[]}]},"18":{"heading":"耶利米在陶匠的家","verses":[{"n":1,"t":"耶和華的話臨到耶利米說：","notes":[]},{"n":2,"t":"「你起來，下到窯匠的家裏去，我在那裏要使你聽我的話。」","notes":[]},{"n":3,"t":"我就下到窯匠的家裏去，正遇他轉輪做器皿。","notes":[]},{"n":4,"t":"窯匠用泥做的器皿，在他手中做壞了，他又用這泥另做別的器皿；窯匠看怎樣好，就怎樣做。","notes":[]},{"n":5,"t":"耶和華的話就臨到我說：","notes":[]},{"n":6,"t":"「耶和華說：以色列家啊，我待你們，豈不能照這窯匠弄泥嗎？以色列家啊，泥在窯匠的手中怎樣，你們在我的手中也怎樣。","notes":[]},{"n":7,"t":"我何時論到一邦或一國說，要拔出、拆毀、毀壞；","notes":[]},{"n":8,"t":"我所說的那一邦，若是轉意離開他們的惡，我就必後悔，不將我想要施行的災禍降與他們。","notes":[]},{"n":9,"t":"我何時論到一邦或一國說，要建立、栽植；","notes":[]},{"n":10,"t":"他們若行我眼中看為惡的事，不聽從我的話，我就必後悔，不將我所說的福氣賜給他們。","notes":[]},{"n":11,"t":"現在你要對猶大人和耶路撒冷的居民說：『耶和華如此說：我造出災禍攻擊你們，定意刑罰你們。你們各人當回頭離開所行的惡道，改正你們的行動作為。』","notes":[]},{"n":12,"t":"「他們卻說：『這是枉然。我們要照自己的計謀去行。』各人隨自己頑梗的惡心做事。」","notes":[]},{"n":13,"t":"所以，耶和華如此說：你們且往各國訪問，有誰聽見這樣的事？以色列民行了一件極可憎惡的事。","notes":["原文是處女"],"heads":["百姓忘記耶和華"]},{"n":14,"t":"黎巴嫩的雪從田野的磐石上豈能斷絕呢？從遠處流下的涼水豈能乾涸呢？","notes":[]},{"n":15,"t":"我的百姓竟忘記我，向假神燒香，使他們在所行的路上，在古道上絆跌，使他們行沒有修築的斜路，","notes":[]},{"n":16,"t":"以致他們的地令人驚駭，常常嗤笑；凡經過這地的必驚駭搖頭。","notes":[]},{"n":17,"t":"我必在仇敵面前分散他們，好像用東風吹散一樣。遭難的日子，我必以背向他們，不以面向他們。","notes":[]},{"n":18,"t":"他們就說：「來吧！我們可以設計謀害耶利米；因為我們有祭司講律法，智慧人設謀略，先知說預言，都不能斷絕。來吧！我們可以用舌頭擊打他，不要理會他的一切話。」","notes":[],"heads":["謀害耶利米"]},{"n":19,"t":"耶和華啊，求你理會我，且聽那些與我爭競之人的話。","notes":[]},{"n":20,"t":"豈可以惡報善呢？他們竟挖坑要害我的性命！求你記念我怎樣站在你面前為他們代求，要使你的忿怒向他們轉消。","notes":[]},{"n":21,"t":"故此，願你將他們的兒女交與饑荒和刀劍；願他們的妻無子，且作寡婦；又願他們的男人被死亡所滅，他們的少年人在陣上被刀擊殺。","notes":[]},{"n":22,"t":"你使敵軍忽然臨到他們的時候，願人聽見哀聲從他們的屋內發出；因他們挖坑要捉拿我，暗設網羅要絆我的腳。","notes":[]},{"n":23,"t":"耶和華啊，他們要殺我的那一切計謀，你都知道。不要赦免他們的罪孽，也不要從你面前塗抹他們的罪惡，要叫他們在你面前跌倒；願你發怒的時候罰辦他們。","notes":[]}]},"19":{"heading":"破碎的瓶","verses":[{"n":1,"t":"耶和華如此說：「你去買窯匠的瓦瓶，又帶百姓中的長老和祭司中的長老，","notes":[]},{"n":2,"t":"出去到欣嫩子谷、哈珥西的門口那裏，宣告我所吩咐你的話，","notes":["就是瓦片的意思"]},{"n":3,"t":"說：『猶大君王和耶路撒冷的居民哪，當聽耶和華的話。萬軍之耶和華－以色列的神如此說：我必使災禍臨到這地方，凡聽見的人都必耳鳴；","notes":[]},{"n":4,"t":"因為他們和他們列祖，並猶大君王離棄我，將這地方看為平常，在這裏向素不認識的別神燒香，又使這地方滿了無辜人的血，","notes":[]},{"n":5,"t":"又建築巴力的邱壇，好在火中焚燒自己的兒子，作為燔祭獻給巴力。這不是我所吩咐的，不是我所提說的，也不是我心所起的意。","notes":[]},{"n":6,"t":"耶和華說：因此，日子將到，這地方不再稱為陀斐特和欣嫩子谷，反倒稱為殺戮谷。","notes":[]},{"n":7,"t":"我必在這地方使猶大和耶路撒冷的計謀落空，也必使他們在仇敵面前倒於刀下，並尋索其命的人手下。他們的屍首，我必給空中的飛鳥和地上的野獸作食物。","notes":[]},{"n":8,"t":"我必使這城令人驚駭嗤笑；凡經過的人，必因這城所遭的災驚駭嗤笑。","notes":[]},{"n":9,"t":"我必使他們在圍困窘迫之中，就是仇敵和尋索其命的人窘迫他們的時候，各人吃自己兒女的肉和朋友的肉。』","notes":[]},{"n":10,"t":"「你要在同去的人眼前打碎那瓶，","notes":[]},{"n":11,"t":"對他們說：『萬軍之耶和華如此說：我要照樣打碎這民和這城，正如人打碎窯匠的瓦器，以致不能再囫圇。並且人要在陀斐特葬埋屍首，甚至無處可葬。","notes":[]},{"n":12,"t":"耶和華說：我必向這地方和其中的居民如此行，使這城與陀斐特一樣。","notes":[]},{"n":13,"t":"耶路撒冷的房屋和猶大君王的宮殿是已經被玷污的，就是他們在其上向天上的萬象燒香、向別神澆奠祭的宮殿房屋，都必與陀斐特一樣。』」","notes":[]},{"n":14,"t":"耶利米從陀斐特－就是耶和華差他去說預言的地方－回來，站在耶和華殿的院中，對眾人說：","notes":[]},{"n":15,"t":"「萬軍之耶和華－以色列的神如此說：我必使我所說的一切災禍臨到這城和屬城的一切城邑，因為他們硬著頸項不聽我的話。」","notes":[]}]},"20":{"heading":"耶利米跟祭司巴施戶珥衝突","verses":[{"n":1,"t":"祭司音麥的兒子巴施戶珥作耶和華殿的總管，聽見耶利米預言這些事，","notes":[]},{"n":2,"t":"他就打先知耶利米，用耶和華殿裏便雅憫高門內的枷，將他枷在那裏。","notes":[]},{"n":3,"t":"次日，巴施戶珥將耶利米開枷釋放。於是耶利米對他說：「耶和華不是叫你的名為巴施戶珥，乃是叫你瑪歌珥‧米撒畢，","notes":["就是四面驚嚇的意思"]},{"n":4,"t":"因耶和華如此說：『我必使你自覺驚嚇，你也必使眾朋友驚嚇；他們必倒在仇敵的刀下，你也必親眼看見；我必將猶大人全交在巴比倫王的手中，他要將他們擄到巴比倫去，也要用刀將他們殺戮。","notes":[]},{"n":5,"t":"並且我要將這城中的一切貨財和勞碌得來的，並一切珍寶，以及猶大君王所有的寶物，都交在他們仇敵的手中；仇敵要當作掠物帶到巴比倫去。","notes":[]},{"n":6,"t":"你這巴施戶珥和一切住在你家中的人都必被擄去；你和你的眾朋友，就是你向他們說假預言的，都必到巴比倫去，要死在那裏，葬在那裏。』」","notes":[]},{"n":7,"t":"耶和華啊，你曾勸導我，我也聽了你的勸導。你比我有力量，且勝了我。我終日成為笑話，人人都戲弄我。","notes":[],"heads":["耶利米埋怨耶和華"]},{"n":8,"t":"我每逢講論的時候，就發出哀聲，我喊叫說：有強暴和毀滅！因為耶和華的話終日成了我的凌辱、譏刺。","notes":[]},{"n":9,"t":"我若說：我不再提耶和華，也不再奉他的名講論，我便心裏覺得似乎有燒著的火閉塞在我骨中，我就含忍不住，不能自禁。","notes":[]},{"n":10,"t":"我聽見了許多人的讒謗，四圍都是驚嚇；就是我知己的朋友也都窺探我，願我跌倒，說：告他吧，我們也要告他！或者他被引誘，我們就能勝他，在他身上報仇。","notes":[]},{"n":11,"t":"然而，耶和華與我同在，好像甚可怕的勇士。因此，逼迫我的必都絆跌，不能得勝；他們必大大蒙羞，就是受永不忘記的羞辱，因為他們行事沒有智慧。","notes":[]},{"n":12,"t":"試驗義人、察看人肺腑心腸的萬軍之耶和華啊，求你容我見你在他們身上報仇，因我將我的案件向你稟明了。","notes":[]},{"n":13,"t":"你們要向耶和華唱歌；讚美耶和華！因他救了窮人的性命脫離惡人的手。","notes":[]},{"n":14,"t":"願我生的那日受咒詛；願我母親產我的那日不蒙福！","notes":[]},{"n":15,"t":"給我父親報信說「你得了兒子」，使我父親甚歡喜的，願那人受咒詛。","notes":[]},{"n":16,"t":"願那人像耶和華所傾覆而不後悔的城邑；願他早晨聽見哀聲，晌午聽見吶喊；","notes":[]},{"n":17,"t":"因他在我未出胎的時候不殺我，使我母親成了我的墳墓，胎就時常重大。","notes":[]},{"n":18,"t":"我為何出胎見勞碌愁苦，使我的年日因羞愧消滅呢？","notes":[]}]},"21":{"heading":"預言耶路撒冷滅亡","verses":[{"n":1,"t":"耶和華的話臨到耶利米。那時，西底家王打發瑪基雅的兒子巴施戶珥和瑪西雅的兒子祭司西番雅去見耶利米，說：","notes":[]},{"n":2,"t":"「請你為我們求問耶和華；因為巴比倫王尼布甲尼撒來攻擊我們，或者耶和華照他一切奇妙的作為待我們，使巴比倫王離開我們上去。」","notes":[]},{"n":3,"t":"耶利米對他們說：「你們當對西底家這樣說：","notes":[]},{"n":4,"t":"『耶和華－以色列的神如此說：我要使你們手中的兵器，就是你們在城外與巴比倫王和圍困你們的迦勒底人打仗的兵器翻轉過來，又要使這些都聚集在這城中。","notes":[]},{"n":5,"t":"並且我要在怒氣、忿怒，和大惱恨中，用伸出來的手，並大能的膀臂，親自攻擊你們；","notes":[]},{"n":6,"t":"又要擊打這城的居民，連人帶牲畜都必遭遇大瘟疫死亡。","notes":[]},{"n":7,"t":"以後我要將猶大王西底家和他的臣僕百姓，就是在城內，從瘟疫、刀劍、饑荒中剩下的人，都交在巴比倫王尼布甲尼撒的手中和他們仇敵，並尋索其命的人手中。巴比倫王必用刀擊殺他們，不顧惜，不可憐，不憐憫。這是耶和華說的。』","notes":[]},{"n":8,"t":"「你要對這百姓說：『耶和華如此說：看哪，我將生命的路和死亡的路擺在你們面前。","notes":[]},{"n":9,"t":"住在這城裏的必遭刀劍、饑荒、瘟疫而死；但出去歸降圍困你們迦勒底人的必得存活，要以自己的命為掠物。","notes":[]},{"n":10,"t":"耶和華說：我向這城變臉，降禍不降福；這城必交在巴比倫王的手中，他必用火焚燒。』」","notes":[]},{"n":11,"t":"「至於猶大王的家，你們當聽耶和華的話。","notes":[],"heads":["審判猶大王室"]},{"n":12,"t":"大衛家啊，耶和華如此說：你們每早晨要施行公平，拯救被搶奪的脫離欺壓人的手，恐怕我的忿怒因你們的惡行發作，如火著起，甚至無人能以熄滅。","notes":[]},{"n":13,"t":"耶和華說：住山谷和平原磐石上的居民，你們說：誰能下來攻擊我們？誰能進入我們的住處呢？看哪，我與你們為敵。","notes":[]},{"n":14,"t":"耶和華又說：我必按你們做事的結果刑罰你們；我也必使火在耶路撒冷的林中著起，將她四圍所有的盡行燒滅。」","notes":[]}]},"22":{"heading":"耶利米給猶大王的警告","verses":[{"n":1,"t":"耶和華如此說：「你下到猶大王的宮中，在那裏說這話，","notes":[]},{"n":2,"t":"說：『坐大衛寶座的猶大王啊，你和你的臣僕，並進入城門的百姓，都當聽耶和華的話。","notes":[]},{"n":3,"t":"耶和華如此說：你們要施行公平和公義，拯救被搶奪的脫離欺壓人的手，不可虧負寄居的和孤兒寡婦，不可以強暴待他們，在這地方也不可流無辜人的血。","notes":[]},{"n":4,"t":"你們若認真行這事，就必有坐大衛寶座的君王和他的臣僕百姓，或坐車或騎馬，從這城的各門進入。","notes":[]},{"n":5,"t":"你們若不聽這些話，耶和華說：我指著自己起誓，這城必變為荒場。』","notes":[]},{"n":6,"t":"耶和華論到猶大王的家如此說：我看你如基列，如黎巴嫩頂；然而，我必使你變為曠野，為無人居住的城邑。","notes":[]},{"n":7,"t":"我要預備行毀滅的人，各拿器械攻擊你；他們要砍下你佳美的香柏樹，扔在火中。","notes":[]},{"n":8,"t":"「許多國的民要經過這城，各人對鄰舍說：『耶和華為何向這大城如此行呢？』","notes":[]},{"n":9,"t":"他們必回答說：『是因離棄了耶和華－他們神的約，事奉敬拜別神。』」","notes":[]},{"n":10,"t":"不要為死人哭號；不要為他悲傷，卻要為離家出外的人大大哭號；因為他不得再回來，也不得再見他的本國。","notes":[],"heads":["關於約哈斯"]},{"n":11,"t":"因為耶和華論到從這地方出去的猶大王約西亞的兒子沙龍，就是接續他父親約西亞作王的，這樣說：「他必不得再回到這裏來，","notes":["在列王下二十三章三十節名約哈斯"]},{"n":12,"t":"卻要死在被擄去的地方，必不得再見這地。」","notes":[]},{"n":13,"t":"那行不義蓋房、行不公造樓、白白使用人的手工不給工價的有禍了！","notes":[],"heads":["關於約雅敬"]},{"n":14,"t":"他說：我要為自己蓋廣大的房、寬敞的樓，為自己開窗戶。這樓房的護牆板是香柏木的，樓房是丹色油漆的。","notes":[]},{"n":15,"t":"難道你作王是在乎造香柏木樓房爭勝嗎？你的父親豈不是也吃也喝、也施行公平和公義嗎？那時他得了福樂。","notes":[]},{"n":16,"t":"他為困苦和窮乏人伸冤，那時就得了福樂。認識我不在乎此嗎？這是耶和華說的。","notes":[]},{"n":17,"t":"惟有你的眼和你的心專顧貪婪，流無辜人的血，行欺壓和強暴。","notes":[]},{"n":18,"t":"所以，耶和華論到猶大王約西亞的兒子約雅敬如此說：人必不為他舉哀說：哀哉！我的哥哥；或說：哀哉！我的姊姊；也不為他舉哀說：哀哉！我的主；或說：哀哉！我主的榮華。","notes":[]},{"n":19,"t":"他被埋葬，好像埋驢一樣，要拉出去扔在耶路撒冷的城門之外。","notes":[]},{"n":20,"t":"你要上黎巴嫩哀號，在巴珊揚聲，從亞巴琳哀號，因為你所親愛的都毀滅了。","notes":[],"heads":["關於耶路撒冷百姓的命運"]},{"n":21,"t":"你興盛的時候，我對你說話；你卻說：我不聽。你自幼年以來總是這樣，不聽從我的話。","notes":[]},{"n":22,"t":"你的牧人要被風吞吃，你所親愛的必被擄去；那時你必因你一切的惡抱愧蒙羞。","notes":[]},{"n":23,"t":"你這住黎巴嫩、在香柏樹上搭窩的，有痛苦臨到你，好像疼痛臨到產難的婦人，那時你何等可憐！","notes":[]},{"n":24,"t":"耶和華說：「猶大王約雅敬的兒子哥尼雅，雖是我右手上帶印的戒指，我憑我的永生起誓，也必將你從其上摘下來，","notes":["又名耶哥尼雅；下同"],"heads":["神審判哥尼雅"]},{"n":25,"t":"並且我必將你交給尋索你命的人和你所懼怕的人手中，就是巴比倫王尼布甲尼撒和迦勒底人的手中。","notes":[]},{"n":26,"t":"我也必將你和生你的母親趕到別國，並不是你們生的地方；你們必死在那裏，","notes":[]},{"n":27,"t":"但心中甚想歸回之地，必不得歸回。」","notes":[]},{"n":28,"t":"哥尼雅這人是被輕看、破壞的器皿嗎？是無人喜愛的器皿嗎？他和他的後裔為何被趕到不認識之地呢？","notes":[]},{"n":29,"t":"地啊，地啊，地啊，當聽耶和華的話！","notes":[]},{"n":30,"t":"耶和華如此說：要寫明這人算為無子，是平生不得亨通的；因為他後裔中再無一人得亨通，能坐在大衛的寶座上治理猶大。","notes":[]}]},"23":{"heading":"對將來的希望","verses":[{"n":1,"t":"耶和華說：「那些殘害、趕散我草場之羊的牧人有禍了！」","notes":[]},{"n":2,"t":"耶和華－以色列的神斥責那些牧養他百姓的牧人，如此說：「你們趕散我的羊群，並沒有看顧他們；我必討你們這行惡的罪。這是耶和華說的。","notes":[]},{"n":3,"t":"我要將我羊群中所餘剩的，從我趕他們到的各國內招聚出來，領他們歸回本圈；他們也必生養眾多。","notes":[]},{"n":4,"t":"我必設立照管他們的牧人，牧養他們。他們不再懼怕，不再驚惶，也不缺少一個；這是耶和華說的。」","notes":[]},{"n":5,"t":"耶和華說：「日子將到，我要給大衛興起一個公義的苗裔；他必掌王權，行事有智慧，在地上施行公平和公義。","notes":[]},{"n":6,"t":"在他的日子，猶大必得救，以色列也安然居住。他的名必稱為『耶和華－我們的義』。」","notes":[]},{"n":7,"t":"耶和華說：「日子將到，人必不再指著那領以色列人從埃及地上來永生的耶和華起誓，","notes":[]},{"n":8,"t":"卻要指著那領以色列家的後裔從北方和趕他們到的各國中上來、永生的耶和華起誓。他們必住在本地。」","notes":[]},{"n":9,"t":"論到那些先知，我心在我裏面憂傷，我骨頭都發顫；因耶和華和他的聖言，我像醉酒的人，像被酒所勝的人。","notes":[],"heads":["對先知們的警告"]},{"n":10,"t":"地滿了行淫的人！因妄自賭咒，地就悲哀；曠野的草場都枯乾了。他們所行的道乃是惡的；他們的勇力使得不正。","notes":[]},{"n":11,"t":"連先知帶祭司都是褻瀆的，就是在我殿中我也看見他們的惡。這是耶和華說的。","notes":[]},{"n":12,"t":"因此，他們的道路必像黑暗中的滑地，他們必被追趕，在這路中仆倒；因為當追討之年，我必使災禍臨到他們。這是耶和華說的。","notes":[]},{"n":13,"t":"我在撒馬利亞的先知中曾見愚妄；他們藉巴力說預言，使我的百姓以色列走錯了路。","notes":[]},{"n":14,"t":"我在耶路撒冷的先知中曾見可憎惡的事；他們行姦淫，做事虛妄，又堅固惡人的手，甚至無人回頭離開他的惡。他們在我面前都像所多瑪；耶路撒冷的居民都像蛾摩拉。","notes":[]},{"n":15,"t":"所以萬軍之耶和華論到先知如此說：我必將茵蔯給他們吃，又將苦膽水給他們喝；因為褻瀆的事出於耶路撒冷的先知，流行遍地。","notes":[]},{"n":16,"t":"萬軍之耶和華如此說：「這些先知向你們說預言，你們不要聽他們的話。他們以虛空教訓你們，所說的異象是出於自己的心，不是出於耶和華的口。","notes":[]},{"n":17,"t":"他們常對藐視我的人說：『耶和華說：你們必享平安』；又對一切按自己頑梗之心而行的人說：『必沒有災禍臨到你們。』」","notes":[]},{"n":18,"t":"有誰站在耶和華的會中得以聽見並會悟他的話呢？有誰留心聽他的話呢？","notes":[]},{"n":19,"t":"看哪！耶和華的忿怒好像暴風，已經發出；是暴烈的旋風，必轉到惡人的頭上。","notes":[]},{"n":20,"t":"耶和華的怒氣必不轉消，直到他心中所擬定的成就了。末後的日子你們要全然明白。","notes":[]},{"n":21,"t":"我沒有打發那些先知，他們竟自奔跑；我沒有對他們說話，他們竟自預言。","notes":[]},{"n":22,"t":"他們若是站在我的會中，就必使我的百姓聽我的話，又使他們回頭離開惡道和他們所行的惡。","notes":[]},{"n":23,"t":"耶和華說：「我豈為近處的神呢？不也為遠處的神嗎？」","notes":[]},{"n":24,"t":"耶和華說：「人豈能在隱密處藏身，使我看不見他呢？」耶和華說：「我豈不充滿天地嗎？","notes":[]},{"n":25,"t":"我已聽見那些先知所說的，就是託我名說的假預言，他們說：『我做了夢！我做了夢！』","notes":[]},{"n":26,"t":"說假預言的先知，就是預言本心詭詐的先知，他們這樣存心要到幾時呢？","notes":[]},{"n":27,"t":"他們各人將所做的夢對鄰舍述說，想要使我的百姓忘記我的名，正如他們列祖因巴力忘記我的名一樣。","notes":[]},{"n":28,"t":"得夢的先知可以述說那夢；得我話的人可以誠實講說我的話。糠秕怎能與麥子比較呢？這是耶和華說的。」","notes":[]},{"n":29,"t":"耶和華說：「我的話豈不像火，又像能打碎磐石的大錘嗎？」","notes":[]},{"n":30,"t":"耶和華說：「那些先知各從鄰舍偷竊我的言語，因此我必與他們反對。」","notes":[]},{"n":31,"t":"耶和華說：「那些先知用舌頭，說是耶和華說的；我必與他們反對。」","notes":[]},{"n":32,"t":"耶和華說：「那些以幻夢為預言，又述說這夢，以謊言和矜誇使我百姓走錯了路的，我必與他們反對。我沒有打發他們，也沒有吩咐他們。他們與這百姓毫無益處。這是耶和華說的。」","notes":[]},{"n":33,"t":"「無論是百姓，是先知，是祭司，問你說：『耶和華有甚麼默示呢？』你就對他們說：『甚麼默示啊？耶和華說：我要撇棄你們。』","notes":[],"heads":["耶和華的重擔"]},{"n":34,"t":"無論是先知，是祭司，是百姓，說『耶和華的默示』，我必刑罰那人和他的家。","notes":[]},{"n":35,"t":"你們各人要對鄰舍，各人要對弟兄如此說：『耶和華回答甚麼？』『耶和華說了甚麼呢？』","notes":[]},{"n":36,"t":"『耶和華的默示』你們不可再提，各人所說的話必作自己的重擔，因為你們謬用永生神、萬軍之耶和華－我們神的言語。","notes":["重擔和默示原文同"]},{"n":37,"t":"你們要對先知如此說：『耶和華回答你甚麼？』『耶和華說了甚麼呢？』","notes":[]},{"n":38,"t":"你們若說『耶和華的默示』，耶和華就如此說：『因你們說「耶和華的默示」這句話，我也打發人到你們那裏去，告訴你們不可說「耶和華的默示」。』","notes":[]},{"n":39,"t":"所以我必全然忘記你們，將你們和我所賜給你們並你們列祖的城撇棄了；","notes":[]},{"n":40,"t":"又必使永遠的凌辱和長久的羞恥臨到你們，是不能忘記的。」","notes":[]}]},"24":{"heading":"兩筐無花果","verses":[{"n":1,"t":"巴比倫王尼布甲尼撒將猶大王約雅敬的兒子耶哥尼雅和猶大的首領，並工匠、鐵匠從耶路撒冷擄去，帶到巴比倫。這事以後，耶和華指給我看，有兩筐無花果放在耶和華的殿前。","notes":[]},{"n":2,"t":"一筐是極好的無花果，好像是初熟的；一筐是極壞的無花果，壞得不可吃。","notes":[]},{"n":3,"t":"於是耶和華問我說：「耶利米你看見甚麼？」我說：「我看見無花果，好的極好，壞的極壞，壞得不可吃。」","notes":[]},{"n":4,"t":"耶和華的話臨到我說：","notes":[]},{"n":5,"t":"「耶和華－以色列的神如此說：被擄去的猶大人，就是我打發離開這地到迦勒底人之地去的，我必看顧他們如這好無花果，使他們得好處。","notes":[]},{"n":6,"t":"我要眷顧他們，使他們得好處，領他們歸回這地。我也要建立他們，必不拆毀；栽植他們，並不拔出。","notes":[]},{"n":7,"t":"我要賜他們認識我的心，知道我是耶和華。他們要作我的子民，我要作他們的神，因為他們要一心歸向我。」","notes":[]},{"n":8,"t":"耶和華如此說：「我必將猶大王西底家和他的首領，以及剩在這地耶路撒冷的餘民，並住在埃及地的猶大人都交出來，好像那極壞、壞得不可吃的無花果。","notes":[]},{"n":9,"t":"我必使他們交出來，在天下萬國中拋來拋去，遭遇災禍；在我趕逐他們到的各處成為凌辱、笑談、譏刺、咒詛。","notes":[]},{"n":10,"t":"我必使刀劍、饑荒、瘟疫臨到他們，直到他們從我所賜給他們和他們列祖之地滅絕。」","notes":[]}]},"25":{"heading":"從北方來的敵人","verses":[{"n":1,"t":"猶大王約西亞的兒子約雅敬第四年，就是巴比倫王尼布甲尼撒的元年，耶和華論猶大眾民的話臨到耶利米。","notes":[]},{"n":2,"t":"先知耶利米就將這話對猶大眾人和耶路撒冷的一切居民說：","notes":[]},{"n":3,"t":"「從猶大王亞們的兒子約西亞十三年直到今日，這二十三年之內，常有耶和華的話臨到我；我也對你們傳說，就是從早起來傳說，只是你們沒有聽從。","notes":[]},{"n":4,"t":"耶和華也從早起來，差遣他的僕人眾先知到你們這裏來（只是你們沒有聽從，也沒有側耳而聽），","notes":[]},{"n":5,"t":"說：『你們各人當回頭，離開惡道和所作的惡，便可居住耶和華古時所賜給你們和你們列祖之地，直到永遠。","notes":[]},{"n":6,"t":"不可隨從別神事奉敬拜，以你們手所做的惹我發怒；這樣，我就不加害與你們。","notes":[]},{"n":7,"t":"然而你們沒有聽從我，竟以手所做的惹我發怒，陷害自己。這是耶和華說的。』」","notes":[]},{"n":8,"t":"所以萬軍之耶和華如此說：「因為你們沒有聽從我的話，","notes":[]},{"n":9,"t":"我必召北方的眾族和我僕人巴比倫王尼布甲尼撒來攻擊這地和這地的居民，並四圍一切的國民。我要將他們盡行滅絕，以致他們令人驚駭、嗤笑，並且永久荒涼。這是耶和華說的。","notes":[]},{"n":10,"t":"我又要使歡喜和快樂的聲音，新郎和新婦的聲音，推磨的聲音和燈的亮光，從他們中間止息。","notes":[]},{"n":11,"t":"這全地必然荒涼，令人驚駭。這些國民要服事巴比倫王七十年。","notes":[]},{"n":12,"t":"七十年滿了以後，我必刑罰巴比倫王和那國民，並迦勒底人之地，因他們的罪孽使那地永遠荒涼。這是耶和華說的。","notes":[]},{"n":13,"t":"我也必使我向那地所說的話，就是記在這書上的話，是耶利米向這些國民說的預言，都臨到那地。","notes":[]},{"n":14,"t":"因為有多國和大君王必使迦勒底人作奴僕；我也必照他們的行為，按他們手所做的報應他們。」","notes":[]},{"n":15,"t":"耶和華－以色列的神對我如此說：「你從我手中接這杯忿怒的酒，使我所差遣你去的各國的民喝。","notes":[],"heads":["神審判列國"]},{"n":16,"t":"他們喝了就要東倒西歪，並要發狂，因我使刀劍臨到他們中間。」","notes":[]},{"n":17,"t":"我就從耶和華的手中接了這杯，給耶和華所差遣我去的各國的民喝，","notes":[]},{"n":18,"t":"就是耶路撒冷和猶大的城邑，並耶路撒冷的君王與首領，使這城邑荒涼，令人驚駭、嗤笑、咒詛，正如今日一樣。","notes":[]},{"n":19,"t":"又有埃及王法老和他的臣僕、首領，以及他的眾民，","notes":[]},{"n":20,"t":"並雜族的人民和烏斯地的諸王，與非利士地的諸王（亞實基倫、迦薩、以革倫，以及亞實突剩下的人）；","notes":[]},{"n":21,"t":"以東、摩押、亞捫人、","notes":[]},{"n":22,"t":"泰爾的諸王、西頓的諸王、海島的諸王、","notes":[]},{"n":23,"t":"底但、提瑪、布斯，和一切剃周圍頭髮的；","notes":[]},{"n":24,"t":"阿拉伯的諸王、住曠野雜族人民的諸王、","notes":[]},{"n":25,"t":"心利的諸王、以攔的諸王、米底亞的諸王、","notes":[]},{"n":26,"t":"北方遠近的諸王，以及天下地上的萬國喝了，以後示沙克王也要喝。","notes":["就是巴比倫"]},{"n":27,"t":"「你要對他們說：『萬軍之耶和華－以色列的神如此說：你們要喝，且要喝醉，要嘔吐，且要跌倒，不得再起來，都因我使刀劍臨到你們中間。』","notes":[]},{"n":28,"t":"「他們若不肯從你手接這杯喝，你就要對他們說：『萬軍之耶和華如此說：你們一定要喝！","notes":[]},{"n":29,"t":"我既從稱為我名下的城起首施行災禍，你們能盡免刑罰嗎？你們必不能免，因為我要命刀劍臨到地上一切的居民。這是萬軍之耶和華說的。』","notes":[]},{"n":30,"t":"「所以你要向他們預言這一切的話，攻擊他們，說：耶和華必從高天吼叫，從聖所發聲，向自己的羊群大聲吼叫；他要向地上一切的居民吶喊，像踹葡萄的一樣。","notes":[]},{"n":31,"t":"必有響聲達到地極，因為耶和華與列國相爭；凡有血氣的，他必審問；至於惡人，他必交給刀劍。這是耶和華說的。","notes":[]},{"n":32,"t":"萬軍之耶和華如此說：看哪，必有災禍從這國發到那國，並有大暴風從地極颳起。","notes":[]},{"n":33,"t":"「到那日，從地這邊直到地那邊都有耶和華所殺戮的。必無人哀哭，不得收殮，不得葬埋，必在地上成為糞土。","notes":[]},{"n":34,"t":"牧人哪，你們當哀號，呼喊；群眾的頭目啊，你們要滾在灰中；因為你們被殺戮分散的日子足足來到。你們要跌碎，好像美器打碎一樣。","notes":[]},{"n":35,"t":"牧人無路逃跑；群眾的頭目也無法逃脫。","notes":[]},{"n":36,"t":"聽啊，有牧人呼喊，有群眾頭目哀號的聲音，因為耶和華使他們的草場變為荒場。","notes":[]},{"n":37,"t":"耶和華發出猛烈的怒氣，平安的羊圈就都寂靜無聲。","notes":[]},{"n":38,"t":"他離了隱密處像獅子一樣，他們的地，因刀劍凶猛的欺壓，又因他猛烈的怒氣都成為可驚駭的。」","notes":[]}]},"26":{"heading":"耶利米受審","verses":[{"n":1,"t":"猶大王約西亞的兒子約雅敬登基的時候，有這話從耶和華臨到耶利米說：","notes":[]},{"n":2,"t":"「耶和華如此說：你站在耶和華殿的院內，對猶大眾城邑的人，就是到耶和華殿來禮拜的，說我所吩咐你的一切話，一字不可刪減。","notes":[]},{"n":3,"t":"或者他們肯聽從，各人回頭離開惡道，使我後悔不將我因他們所行的惡，想要施行的災禍降與他們。","notes":[]},{"n":4,"t":"你要對他們說，耶和華如此說：『你們若不聽從我，不遵行我設立在你們面前的律法，","notes":[]},{"n":5,"t":"不聽我從早起來差遣到你們那裏去我僕人眾先知的話（你們還是沒有聽從），","notes":[]},{"n":6,"t":"我就必使這殿如示羅，使這城為地上萬國所咒詛的。』」","notes":[]},{"n":7,"t":"耶利米在耶和華殿中說的這些話，祭司、先知與眾民都聽見了。","notes":[]},{"n":8,"t":"耶利米說完了耶和華所吩咐他對眾人說的一切話，祭司、先知與眾民都來抓住他，說：「你必要死！","notes":[]},{"n":9,"t":"你為何託耶和華的名預言，說這殿必如示羅，這城必變為荒場無人居住呢？」於是眾民都在耶和華的殿中聚集到耶利米那裏。","notes":[]},{"n":10,"t":"猶大的首領聽見這事，就從王宮上到耶和華的殿，坐在耶和華殿的新門口。","notes":[]},{"n":11,"t":"祭司、先知對首領和眾民說：「這人是該死的；因為他說預言攻擊這城，正如你們親耳所聽見的。」","notes":[]},{"n":12,"t":"耶利米就對眾首領和眾民說：「耶和華差遣我預言，攻擊這殿和這城，說你們所聽見的這一切話。","notes":[]},{"n":13,"t":"現在要改正你們的行動作為，聽從耶和華－你們神的話，他就必後悔，不將所說的災禍降與你們。","notes":[]},{"n":14,"t":"至於我，我在你們手中，你們眼看何為善，何為正，就那樣待我吧！","notes":[]},{"n":15,"t":"但你們要確實地知道，若把我治死，就使無辜人的血歸到你們和這城，並其中的居民了；因為耶和華實在差遣我到你們這裏來，將這一切話傳與你們耳中。」","notes":[]},{"n":16,"t":"首領和眾民就對祭司、先知說：「這人是不該死的，因為他是奉耶和華－我們神的名向我們說話。」","notes":[]},{"n":17,"t":"國中的長老就有幾個人起來，對聚會的眾民說：","notes":[]},{"n":18,"t":"「當猶大王希西家的日子，有摩利沙人彌迦對猶大眾人預言說：萬軍之耶和華如此說：錫安必被耕種像一塊田；耶路撒冷必變為亂堆；這殿的山必像叢林的高處。","notes":[]},{"n":19,"t":"猶大王希西家和猶大眾人豈是把他治死呢？希西家豈不是敬畏耶和華、懇求他的恩嗎？耶和華就後悔，不把自己所說的災禍降與他們。若治死這人，我們就作了大惡，自害己命。」（","notes":[]},{"n":20,"t":"又有一個人奉耶和華的名說預言，是基列‧耶琳人示瑪雅的兒子烏利亞，他照耶利米的一切話說預言，攻擊這城和這地。","notes":[]},{"n":21,"t":"約雅敬王和他眾勇士、眾首領聽見了烏利亞的話，王就想要把他治死。烏利亞聽見就懼怕，逃往埃及去了。","notes":[]},{"n":22,"t":"約雅敬王便打發亞革波的兒子以利拿單，帶領幾個人往埃及去。","notes":[]},{"n":23,"t":"他們就從埃及將烏利亞帶出來，送到約雅敬王那裏；王用刀殺了他，把他的屍首拋在平民的墳地中。）","notes":[]},{"n":24,"t":"然而，沙番的兒子亞希甘保護耶利米，不交在百姓的手中治死他。","notes":[]}]},"27":{"heading":"耶利米負軛","verses":[{"n":1,"t":"猶大王約西亞的兒子約雅敬登基的時候，有這話從耶和華臨到耶利米說：","notes":["約雅敬是西底家的別名，看第三節"]},{"n":2,"t":"「耶和華對我如此說：你做繩索與軛，加在自己的頸項上，","notes":[]},{"n":3,"t":"藉那些來到耶路撒冷見猶大王西底家的使臣之手，把繩索與軛送到以東王、摩押王、亞捫王、泰爾王、西頓王那裏，","notes":[]},{"n":4,"t":"且囑咐使臣，傳與他們的主人說，萬軍之耶和華－以色列的神如此說：","notes":[]},{"n":5,"t":"我用大能和伸出來的膀臂，創造大地和地上的人民、牲畜。我看給誰相宜，就把地給誰。","notes":[]},{"n":6,"t":"現在我將這些地都交給我僕人巴比倫王尼布甲尼撒的手，我也將田野的走獸給他使用。","notes":[]},{"n":7,"t":"列國都必服事他和他的兒孫，直到他本國遭報的日期來到。那時，多國和大君王要使他作他們的奴僕。","notes":[]},{"n":8,"t":"「無論哪一邦哪一國，不肯服事這巴比倫王尼布甲尼撒，也不把頸項放在巴比倫王的軛下，我必用刀劍、饑荒、瘟疫刑罰那邦，直到我藉巴比倫王的手將他們毀滅。這是耶和華說的。","notes":[]},{"n":9,"t":"至於你們，不可聽從你們的先知和占卜的、圓夢的、觀兆的，以及行邪術的；他們告訴你們說：『你們不致服事巴比倫王。』","notes":[]},{"n":10,"t":"他們向你們說假預言，要叫你們遷移，遠離本地，以致我將你們趕出去，使你們滅亡。","notes":[]},{"n":11,"t":"但哪一邦肯把頸項放在巴比倫王的軛下服事他，我必使那邦仍在本地存留，得以耕種居住。這是耶和華說的。」","notes":[]},{"n":12,"t":"我就照這一切的話對猶大王西底家說：「要把你們的頸項放在巴比倫王的軛下，服事他和他的百姓，便得存活。","notes":[]},{"n":13,"t":"你和你的百姓為何要因刀劍、饑荒、瘟疫死亡，正如耶和華論到不服事巴比倫王的那國說的話呢？","notes":[]},{"n":14,"t":"不可聽那些先知對你們所說的話；他們說：『你們不致服事巴比倫王』，其實他們向你們說假預言。","notes":[]},{"n":15,"t":"耶和華說：『我並沒有打發他們，他們卻託我的名說假預言，好使我將你們和向你們說預言的那些先知趕出去，一同滅亡。』」","notes":[]},{"n":16,"t":"我又對祭司和這眾民說：「耶和華如此說：你們不可聽那先知對你們所說的預言。他們說：『耶和華殿中的器皿快要從巴比倫帶回來』；其實他們向你們說假預言。","notes":[]},{"n":17,"t":"不可聽從他們，只管服事巴比倫王便得存活。這城何致變為荒場呢？","notes":[]},{"n":18,"t":"他們若果是先知，有耶和華的話臨到他們，讓他們祈求萬軍之耶和華，使那在耶和華殿中和猶大王宮內，並耶路撒冷剩下的器皿，不被帶到巴比倫去。（","notes":[]},{"n":19,"t":"因為萬軍之耶和華論到柱子、銅海、盆座，並剩在這城裏的器皿，","notes":[]},{"n":20,"t":"就是巴比倫王尼布甲尼撒擄掠猶大王約雅敬的兒子耶哥尼雅，和猶大、耶路撒冷一切貴冑的時候所沒有掠去的器皿。）","notes":[]},{"n":21,"t":"論到那在耶和華殿中和猶大王宮內，並耶路撒冷剩下的器皿，萬軍之耶和華－以色列的神如此說：","notes":[]},{"n":22,"t":"必被帶到巴比倫存在那裏，直到我眷顧以色列人的日子。那時，我必將這器皿帶回來，交還此地。這是耶和華說的。」","notes":[]}]},"28":{"heading":"耶利米和先知哈拿尼雅","verses":[{"n":1,"t":"當年，就是猶大王西底家登基第四年五月，基遍人押朔的兒子，先知哈拿尼雅，在耶和華的殿中當著祭司和眾民對我說：","notes":[]},{"n":2,"t":"「萬軍之耶和華－以色列的神如此說：我已經折斷巴比倫王的軛。","notes":[]},{"n":3,"t":"二年之內，我要將巴比倫王尼布甲尼撒從這地掠到巴比倫的器皿，就是耶和華殿中的一切器皿都帶回此地。","notes":[]},{"n":4,"t":"我又要將猶大王約雅敬的兒子耶哥尼雅和被擄到巴比倫去的一切猶大人帶回此地，因為我要折斷巴比倫王的軛。這是耶和華說的。」","notes":[]},{"n":5,"t":"先知耶利米當著祭司和站在耶和華殿裏的眾民對先知哈拿尼雅說：","notes":[]},{"n":6,"t":"「阿們！願耶和華如此行，願耶和華成就你所預言的話，將耶和華殿中的器皿和一切被擄去的人從巴比倫帶回此地。","notes":[]},{"n":7,"t":"然而我向你和眾民耳中所要說的話，你應當聽。","notes":[]},{"n":8,"t":"從古以來，在你我以前的先知，向多國和大邦說預言，論到爭戰、災禍、瘟疫的事。","notes":[]},{"n":9,"t":"先知預言的平安，到話語成就的時候，人便知道他真是耶和華所差來的。」","notes":[]},{"n":10,"t":"於是，先知哈拿尼雅將先知耶利米頸項上的軛取下來，折斷了。","notes":[]},{"n":11,"t":"哈拿尼雅又當著眾民說：「耶和華如此說：二年之內我必照樣從列國人的頸項上折斷巴比倫王尼布甲尼撒的軛。」於是先知耶利米就走了。","notes":[]},{"n":12,"t":"先知哈拿尼雅把先知耶利米頸項上的軛折斷以後，耶和華的話臨到耶利米說：","notes":[]},{"n":13,"t":"「你去告訴哈拿尼雅說，耶和華如此說：你折斷木軛，卻換了鐵軛！","notes":[]},{"n":14,"t":"因為萬軍之耶和華－以色列的神如此說：我已將鐵軛加在這些國的頸項上，使他們服事巴比倫王尼布甲尼撒，他們總要服事他；我也把田野的走獸給了他。」","notes":[]},{"n":15,"t":"於是先知耶利米對先知哈拿尼雅說：「哈拿尼雅啊，你應當聽！耶和華並沒有差遣你，你竟使這百姓倚靠謊言。","notes":[]},{"n":16,"t":"所以耶和華如此說：看哪，我要叫你去世，你今年必死，因為你向耶和華說了叛逆的話。」","notes":[]},{"n":17,"t":"這樣，先知哈拿尼雅當年七月間就死了。","notes":[]}]},"29":{"heading":"耶利米寫信給巴比倫的猶大人","verses":[{"n":1,"t":"先知耶利米從耶路撒冷寄信與被擄的祭司、先知，和眾民，並生存的長老，就是尼布甲尼撒從耶路撒冷擄到巴比倫去的。（","notes":[]},{"n":2,"t":"這在耶哥尼雅王和太后、太監，並猶大、耶路撒冷的首領，以及工匠、鐵匠都離了耶路撒冷以後。）","notes":[]},{"n":3,"t":"他藉沙番的兒子以利亞薩和希勒家的兒子基瑪利的手寄去。他們二人是猶大王西底家打發往巴比倫去見尼布甲尼撒王的。","notes":[]},{"n":4,"t":"信上說：「萬軍之耶和華－以色列的神對一切被擄去的（就是我使他們從耶路撒冷被擄到巴比倫的人）如此說：","notes":[]},{"n":5,"t":"你們要蓋造房屋，住在其中；栽種田園，吃其中所產的；","notes":[]},{"n":6,"t":"娶妻生兒女，為你們的兒子娶妻，使你們的女兒嫁人，生兒養女。在那裏生養眾多，不致減少。","notes":[]},{"n":7,"t":"我所使你們被擄到的那城，你們要為那城求平安，為那城禱告耶和華；因為那城得平安，你們也隨著得平安。","notes":[]},{"n":8,"t":"萬軍之耶和華－以色列的神如此說：不要被你們中間的先知和占卜的誘惑，也不要聽信自己所做的夢；","notes":[]},{"n":9,"t":"因為他們託我的名對你們說假預言，我並沒有差遣他們。這是耶和華說的。","notes":[]},{"n":10,"t":"「耶和華如此說：為巴比倫所定的七十年滿了以後，我要眷顧你們，向你們成就我的恩言，使你們仍回此地。","notes":[]},{"n":11,"t":"耶和華說：我知道我向你們所懷的意念是賜平安的意念，不是降災禍的意念，要叫你們末後有指望。","notes":[]},{"n":12,"t":"你們要呼求我，禱告我，我就應允你們。","notes":[]},{"n":13,"t":"你們尋求我，若專心尋求我，就必尋見。","notes":[]},{"n":14,"t":"耶和華說：我必被你們尋見，我也必使你們被擄的人歸回，將你們從各國中和我所趕你們到的各處招聚了來，又將你們帶回我使你們被擄掠離開的地方。這是耶和華說的。","notes":[]},{"n":15,"t":"「你們說：『耶和華在巴比倫為我們興起先知』；","notes":[]},{"n":16,"t":"所以耶和華論到坐大衛寶座的王和住在這城裏的一切百姓，就是未曾與你們一同被擄的弟兄，","notes":[]},{"n":17,"t":"萬軍之耶和華如此說：『看哪，我必使刀劍、饑荒、瘟疫臨到他們，使他們像極壞的無花果，壞得不可吃。","notes":[]},{"n":18,"t":"我必用刀劍、饑荒、瘟疫追趕他們，使他們在天下萬國拋來拋去，在我所趕他們到的各國中，令人咒詛、驚駭、嗤笑、羞辱。","notes":[]},{"n":19,"t":"耶和華說：這是因為他們沒有聽從我的話，就是我從早起來差遣我僕人眾先知去說的，無奈他們不聽。這是耶和華說的。","notes":[]},{"n":20,"t":"所以你們一切被擄去的，就是我從耶路撒冷打發到巴比倫去的，當聽耶和華的話。』」","notes":[]},{"n":21,"t":"萬軍之耶和華－以色列的神論到哥賴雅的兒子亞哈，並瑪西雅的兒子西底家，如此說：「他們是託我名向你們說假預言的，我必將他們交在巴比倫王尼布甲尼撒的手中；他要在你們眼前殺害他們。","notes":[]},{"n":22,"t":"住巴比倫一切被擄的猶大人必藉這二人賭咒說：『願耶和華使你像巴比倫王在火中燒的西底家和亞哈一樣。』","notes":[]},{"n":23,"t":"這二人是在以色列中行了醜事，與鄰舍的妻行淫，又假託我名說我未曾吩咐他們的話。知道的是我，作見證的也是我。這是耶和華說的。」","notes":[]},{"n":24,"t":"「論到尼希蘭人示瑪雅，你當說，","notes":[],"heads":["示瑪雅的信件"]},{"n":25,"t":"萬軍之耶和華－以色列的神如此說：你曾用自己的名寄信給耶路撒冷的眾民和祭司瑪西雅的兒子西番雅，並眾祭司，說：","notes":[]},{"n":26,"t":"『耶和華已經立你西番雅為祭司，代替祭司耶何耶大，使耶和華殿中有官長，好將一切狂妄自稱為先知的人用枷枷住，用鎖鎖住。","notes":[]},{"n":27,"t":"現在亞拿突人耶利米向你們自稱為先知，你們為何沒有責備他呢？","notes":[]},{"n":28,"t":"因為他寄信給我們在巴比倫的人說：被擄的事必長久。你們要蓋造房屋，住在其中；栽種田園，吃其中所產的。』」","notes":[]},{"n":29,"t":"祭司西番雅就把這信念給先知耶利米聽。","notes":[]},{"n":30,"t":"於是耶和華的話臨到耶利米說：","notes":[]},{"n":31,"t":"「你當寄信給一切被擄的人說：『耶和華論到尼希蘭人示瑪雅說：因為示瑪雅向你們說預言，我並沒有差遣他，他使你們倚靠謊言；","notes":[]},{"n":32,"t":"所以耶和華如此說：我必刑罰尼希蘭人示瑪雅和他的後裔，他必無一人存留住在這民中，也不得見我所要賜與我百姓的福樂，因為他向耶和華說了叛逆的話。這是耶和華說的。』」","notes":[]}]},"30":{"heading":"耶和華給他子民的應許","verses":[{"n":1,"t":"耶和華的話臨到耶利米說：","notes":[]},{"n":2,"t":"「耶和華－以色列的神如此說：你將我對你說過的一切話都寫在書上。","notes":[]},{"n":3,"t":"耶和華說：日子將到，我要使我的百姓以色列和猶大被擄的人歸回；我也要使他們回到我所賜給他們列祖之地，他們就得這地為業。這是耶和華說的。」","notes":[]},{"n":4,"t":"以下是耶和華論到以色列和猶大所說的話：","notes":[]},{"n":5,"t":"耶和華如此說：我們聽見聲音，是戰抖懼怕而不平安的聲音。","notes":[]},{"n":6,"t":"你們且訪問看看，男人有產難嗎？我怎麼看見人人用手掐腰，像產難的婦人，臉面都變青了呢？","notes":[]},{"n":7,"t":"哀哉！那日為大，無日可比；這是雅各遭難的時候，但他必被救出來。","notes":[]},{"n":8,"t":"萬軍之耶和華說：「到那日，我必從你頸項上折斷仇敵的軛，扭開他的繩索；外邦人不得再使你作他們的奴僕。","notes":[]},{"n":9,"t":"你們卻要事奉耶和華－你們的神和我為你們所要興起的王大衛。」","notes":[]},{"n":10,"t":"故此，耶和華說：我的僕人雅各啊，不要懼怕；以色列啊，不要驚惶；因我要從遠方拯救你，從被擄到之地拯救你的後裔；雅各必回來得享平靖安逸，無人使他害怕。","notes":[]},{"n":11,"t":"因我與你同在，要拯救你，也要將所趕散你到的那些國滅絕淨盡，卻不將你滅絕淨盡，倒要從寬懲治你，萬不能不罰你。這是耶和華說的。","notes":["不罰你：或譯以你為無罪"]},{"n":12,"t":"耶和華如此說：你的損傷無法醫治；你的傷痕極其重大。","notes":[]},{"n":13,"t":"無人為你分訴，使你的傷痕得以纏裹；你沒有醫治的良藥。","notes":[]},{"n":14,"t":"你所親愛的都忘記你，不來探問你。我因你的罪孽甚大，罪惡眾多，曾用仇敵加的傷害傷害你，用殘忍者的懲治懲治你。","notes":["或譯：理會"]},{"n":15,"t":"你為何因損傷哀號呢？你的痛苦無法醫治。我因你的罪孽甚大，罪惡眾多，曾將這些加在你身上。","notes":[]},{"n":16,"t":"故此，凡吞吃你的必被吞吃；你的敵人個個都被擄去；擄掠你的必成為擄物；搶奪你的必成為掠物。","notes":[]},{"n":17,"t":"耶和華說：我必使你痊癒，醫好你的傷痕，都因人稱你為被趕散的，說：這是錫安，無人來探問的！","notes":["或譯：理會"]},{"n":18,"t":"耶和華如此說：我必使雅各被擄去的帳棚歸回，也必顧惜他的住處。城必建造在原舊的山岡；宮殿也照舊有人居住。","notes":[]},{"n":19,"t":"必有感謝和歡樂的聲音從其中發出，我要使他們增多，不致減少；使他們尊榮，不致卑微。","notes":[]},{"n":20,"t":"他們的兒女要如往日；他們的會眾堅立在我面前；凡欺壓他們的，我必刑罰他。","notes":[]},{"n":21,"t":"他們的君王必是屬乎他們的；掌權的必從他們中間而出。我要使他就近我，他也要親近我；不然，誰有膽量親近我呢？這是耶和華說的。","notes":[]},{"n":22,"t":"你們要作我的子民，我要作你們的神。","notes":[]},{"n":23,"t":"看哪，耶和華的忿怒好像暴風已經發出；是掃滅的暴風，必轉到惡人的頭上。","notes":[]},{"n":24,"t":"耶和華的烈怒必不轉消，直到他心中所擬定的成就了；末後的日子你們要明白。","notes":[]}]},"31":{"heading":"以色列人還鄉","verses":[{"n":1,"t":"耶和華說：「那時，我必作以色列各家的神；他們必作我的子民。」","notes":[]},{"n":2,"t":"耶和華如此說：脫離刀劍的就是以色列人。我使他享安息的時候，他曾在曠野蒙恩。","notes":[]},{"n":3,"t":"古時耶和華向以色列顯現，說：我以永遠的愛愛你，因此我以慈愛吸引你。","notes":["或譯：從遠方","原文是我"]},{"n":4,"t":"以色列的民哪，我要再建立你，你就被建立；你必再以擊鼓為美，與歡樂的人一同跳舞而出；","notes":["原文是處女"]},{"n":5,"t":"又必在撒馬利亞的山上栽種葡萄園，栽種的人要享用所結的果子。","notes":[]},{"n":6,"t":"日子必到，以法蓮山上守望的人必呼叫說：起來吧！我們可以上錫安，到耶和華－我們的神那裏去。","notes":[]},{"n":7,"t":"耶和華如此說：你們當為雅各歡樂歌唱，因萬國中為首的歡呼。當傳揚頌讚說：耶和華啊，求你拯救你的百姓以色列所剩下的人。","notes":[]},{"n":8,"t":"我必將他們從北方領來，從地極招聚；同著他們來的有瞎子、瘸子、孕婦、產婦；他們必成為大幫回到這裏來。","notes":[]},{"n":9,"t":"他們要哭泣而來。我要照他們懇求的引導他們，使他們在河水旁走正直的路，在其上不致絆跌；因為我是以色列的父，以法蓮是我的長子。","notes":[]},{"n":10,"t":"列國啊，要聽耶和華的話，傳揚在遠處的海島說：趕散以色列的必招聚他，又看守他，好像牧人看守羊群。","notes":[]},{"n":11,"t":"因耶和華救贖了雅各，救贖他脫離比他更強之人的手。","notes":[]},{"n":12,"t":"他們要來到錫安的高處歌唱，又流歸耶和華施恩之地，就是有五穀、新酒，和油，並羊羔、牛犢之地。他們的心必像澆灌的園子；他們也不再有一點愁煩。","notes":[]},{"n":13,"t":"那時，處女必歡樂跳舞；年少的、年老的，也必一同歡樂；因為我要使他們的悲哀變為歡喜，並要安慰他們，使他們的愁煩轉為快樂。","notes":[]},{"n":14,"t":"我必以肥油使祭司的心滿足；我的百姓也要因我的恩惠知足。這是耶和華說的。","notes":[]},{"n":15,"t":"耶和華如此說：在拉瑪聽見號咷痛哭的聲音，是拉結哭她兒女，不肯受安慰，因為他們都不在了。","notes":[],"heads":["耶和華憐憫以色列"]},{"n":16,"t":"耶和華如此說：你禁止聲音不要哀哭，禁止眼目不要流淚，因你所做之工必有賞賜；他們必從敵國歸回。這是耶和華說的。","notes":[]},{"n":17,"t":"耶和華說：你末後必有指望；你的兒女必回到自己的境界。","notes":[]},{"n":18,"t":"我聽見以法蓮為自己悲歎說：你責罰我，我便受責罰，像不慣負軛的牛犢一樣。求你使我回轉，我便回轉，因為你是耶和華－我的神。","notes":[]},{"n":19,"t":"我回轉以後就真正懊悔；受教以後就拍腿歎息；我因擔當幼年的凌辱就抱愧蒙羞。","notes":[]},{"n":20,"t":"耶和華說：以法蓮是我的愛子嗎？是可喜悅的孩子嗎？我每逢責備他，仍深顧念他；所以我的心腸戀慕他；我必要憐憫他。","notes":[]},{"n":21,"t":"以色列民哪，你當為自己設立指路碑，豎起引路柱。你要留心向大路，就是你所去的原路；你當回轉，回轉到你這些城邑。","notes":["原文是處女"]},{"n":22,"t":"背道的民哪，你反來覆去要到幾時呢？耶和華在地上造了一件新事，就是女子護衛男子。","notes":["原文是女子"]},{"n":23,"t":"萬軍之耶和華－以色列的神如此說：「我使被擄之人歸回的時候，他們在猶大地和其中的城邑必再這樣說：公義的居所啊，聖山哪，願耶和華賜福給你。","notes":[],"heads":["神子民的光明前途"]},{"n":24,"t":"猶大和屬猶大城邑的人，農夫和放羊的人，要一同住在其中。","notes":[]},{"n":25,"t":"疲乏的人，我使他飽飫；愁煩的人，我使他知足。」","notes":[]},{"n":26,"t":"先知說：「我醒了，覺著睡得香甜！」","notes":[]},{"n":27,"t":"耶和華說：「日子將到，我要把人的種和牲畜的種播種在以色列家和猶大家。","notes":[]},{"n":28,"t":"我先前怎樣留意將他們拔出、拆毀、毀壞、傾覆、苦害，也必照樣留意將他們建立、栽植。這是耶和華說的。","notes":[]},{"n":29,"t":"當那些日子，人不再說：父親吃了酸葡萄，兒子的牙酸倒了。","notes":[]},{"n":30,"t":"但各人必因自己的罪死亡；凡吃酸葡萄的，自己的牙必酸倒。」","notes":[]},{"n":31,"t":"耶和華說：「日子將到，我要與以色列家和猶大家另立新約，","notes":[]},{"n":32,"t":"不像我拉著他們祖宗的手，領他們出埃及地的時候，與他們所立的約。我雖作他們的丈夫，他們卻背了我的約。這是耶和華說的。」","notes":[]},{"n":33,"t":"耶和華說：「那些日子以後，我與以色列家所立的約乃是這樣：我要將我的律法放在他們裏面，寫在他們心上。我要作他們的神，他們要作我的子民。","notes":[]},{"n":34,"t":"他們各人不再教導自己的鄰舍和自己的弟兄說：『你該認識耶和華』，因為他們從最小的到至大的都必認識我。我要赦免他們的罪孽，不再記念他們的罪惡。這是耶和華說的。」","notes":[]},{"n":35,"t":"那使太陽白日發光，使星月有定例，黑夜發亮，又攪動大海，使海中波浪匉訇的，萬軍之耶和華是他的名。他如此說：","notes":[]},{"n":36,"t":"這些定例若能在我面前廢掉，以色列的後裔也就在我面前斷絕，永遠不再成國。這是耶和華說的。","notes":[]},{"n":37,"t":"耶和華如此說：若能量度上天，尋察下地的根基，我就因以色列後裔一切所行的棄絕他們。這是耶和華說的。","notes":[]},{"n":38,"t":"耶和華說：「日子將到，這城必為耶和華建造，從哈楠業樓直到角門。","notes":[]},{"n":39,"t":"準繩要往外量出，直到迦立山，又轉到歌亞。","notes":[]},{"n":40,"t":"拋屍的全谷和倒灰之處，並一切田地，直到汲淪溪，又直到東方馬門的拐角，都要歸耶和華為聖，不再拔出，不再傾覆，直到永遠。」","notes":[]}]},"32":{"heading":"耶利米購置田地","verses":[{"n":1,"t":"猶大王西底家第十年，就是尼布甲尼撒十八年，耶和華的話臨到耶利米。","notes":[]},{"n":2,"t":"那時巴比倫王的軍隊圍困耶路撒冷，先知耶利米囚在護衛兵的院內，在猶大王的宮中；","notes":[]},{"n":3,"t":"因為猶大王西底家已將他囚禁，說：「你為甚麼預言說，耶和華如此說：『我必將這城交在巴比倫王的手中，他必攻取這城。","notes":[]},{"n":4,"t":"猶大王西底家必不能逃脫迦勒底人的手，定要交在巴比倫王的手中，要口對口彼此說話，眼對眼彼此相看。","notes":[]},{"n":5,"t":"巴比倫王必將西底家帶到巴比倫；西底家必住在那裏，直到我眷顧他的時候。你們雖與迦勒底人爭戰，卻不順利。這是耶和華說的。』」","notes":[]},{"n":6,"t":"耶利米說：「耶和華的話臨到我說：","notes":[]},{"n":7,"t":"『你叔叔沙龍的兒子哈拿篾必來見你，說：我在亞拿突的那塊地，求你買來；因你買這地是合乎贖回之理。』」","notes":[]},{"n":8,"t":"我叔叔的兒子哈拿篾果然照耶和華的話來到護衛兵的院內，對我說：「我在便雅憫境內、亞拿突的那塊地，求你買來；因你買來是合乎承受之理，是你當贖的。你為自己買來吧！」我－耶利米就知道這是耶和華的話。","notes":[]},{"n":9,"t":"我便向我叔叔的兒子哈拿篾買了亞拿突的那塊地，平了十七舍客勒銀子給他。","notes":[]},{"n":10,"t":"我在契上畫押，將契封緘，又請見證人來，並用天平將銀子平給他。","notes":[]},{"n":11,"t":"我便將照例按規所立的買契，就是封緘的那一張和敞著的那一張，","notes":[]},{"n":12,"t":"當著我叔叔的兒子哈拿篾和畫押作見證的人，並坐在護衛兵院內的一切猶大人眼前，交給瑪西雅的孫子尼利亞的兒子巴錄。","notes":[]},{"n":13,"t":"當著他們眾人眼前，我囑咐巴錄說：","notes":[]},{"n":14,"t":"「萬軍之耶和華－以色列的神如此說：要將這封緘的和敞著的兩張契放在瓦器裏，可以存留多日。","notes":[]},{"n":15,"t":"因為萬軍之耶和華－以色列的神如此說：將來在這地必有人再買房屋、田地，和葡萄園。」","notes":[]},{"n":16,"t":"我將買契交給尼利亞的兒子巴錄以後，便禱告耶和華說：","notes":[],"heads":["耶利米的祈禱"]},{"n":17,"t":"「主耶和華啊，你曾用大能和伸出來的膀臂創造天地，在你沒有難成的事。","notes":[]},{"n":18,"t":"你施慈愛與千萬人，又將父親的罪孽報應在他後世子孫的懷中，是至大全能的神，萬軍之耶和華是你的名。","notes":[]},{"n":19,"t":"謀事有大略，行事有大能，注目觀看世人一切的舉動，為要照各人所行的和他做事的結果報應他。","notes":[]},{"n":20,"t":"在埃及地顯神蹟奇事，直到今日在以色列和別人中間也是如此，使自己得了名聲，正如今日一樣。","notes":[]},{"n":21,"t":"用神蹟奇事和大能的手，並伸出來的膀臂與大可畏的事，領你的百姓以色列出了埃及。","notes":[]},{"n":22,"t":"將這地賜給他們，就是你向他們列祖起誓應許賜給他們流奶與蜜之地。","notes":[]},{"n":23,"t":"他們進入這地得了為業，卻不聽從你的話，也不遵行你的律法；你一切所吩咐他們行的，他們一無所行，因此你使這一切的災禍臨到他們。","notes":[]},{"n":24,"t":"看哪，敵人已經來到，築壘要攻取這城；城也因刀劍、饑荒、瘟疫交在攻城的迦勒底人手中。你所說的話都成就了，你也看見了。","notes":[]},{"n":25,"t":"主耶和華啊，你對我說：要用銀子為自己買那塊地，又請見證人。其實這城已交在迦勒底人的手中了。」","notes":[]},{"n":26,"t":"耶和華的話臨到耶利米說：","notes":[]},{"n":27,"t":"「我是耶和華，是凡有血氣者的神，豈有我難成的事嗎？","notes":[]},{"n":28,"t":"耶和華如此說：我必將這城交付迦勒底人的手和巴比倫王尼布甲尼撒的手，他必攻取這城。","notes":[]},{"n":29,"t":"攻城的迦勒底人必來放火焚燒這城和其中的房屋。在這房屋上，人曾向巴力燒香，向別神澆奠，惹我發怒。","notes":[]},{"n":30,"t":"以色列人和猶大人自從幼年以來，專行我眼中看為惡的事；以色列人盡以手所做的惹我發怒。這是耶和華說的。","notes":[]},{"n":31,"t":"這城自從建造的那日直到今日，常惹我的怒氣和忿怒，使我將這城從我面前除掉；","notes":[]},{"n":32,"t":"是因以色列人和猶大人一切的邪惡，就是他們和他們的君王、首領、祭司、先知，並猶大的眾人，以及耶路撒冷的居民所行的，惹我發怒。","notes":[]},{"n":33,"t":"他們以背向我，不以面向我；我雖從早起來教訓他們，他們卻不聽從，不受教訓，","notes":[]},{"n":34,"t":"竟把可憎之物設立在稱為我名下的殿中，污穢了這殿。","notes":[]},{"n":35,"t":"他們在欣嫩子谷建築巴力的邱壇，好使自己的兒女經火歸摩洛；他們行這可憎的事，使猶大陷在罪裏，這並不是我所吩咐的，也不是我心所起的意。」","notes":[]},{"n":36,"t":"現在論到這城，就是你們所說、已經因刀劍、饑荒、瘟疫交在巴比倫王手中的，耶和華－以色列的神如此說：","notes":[],"heads":["復國的應許"]},{"n":37,"t":"「我在怒氣、忿怒，和大惱恨中，將以色列人趕到各國。日後我必從那裏將他們招聚出來，領他們回到此地，使他們安然居住。","notes":[]},{"n":38,"t":"他們要作我的子民，我要作他們的神。","notes":[]},{"n":39,"t":"我要使他們彼此同心同道，好叫他們永遠敬畏我，使他們和他們後世的子孫得福樂，","notes":[]},{"n":40,"t":"又要與他們立永遠的約，必隨著他們施恩，並不離開他們，且使他們有敬畏我的心，不離開我。","notes":[]},{"n":41,"t":"我必歡喜施恩與他們，要盡心盡意、誠誠實實將他們栽於此地。","notes":[]},{"n":42,"t":"「因為耶和華如此說：我怎樣使這一切大禍臨到這百姓，我也要照樣使我所應許他們的一切福樂都臨到他們。","notes":[]},{"n":43,"t":"你們說，這地是荒涼、無人民、無牲畜，是交付迦勒底人手之地。日後在這境內，必有人置買田地。","notes":[]},{"n":44,"t":"在便雅憫地、耶路撒冷四圍的各處、猶大的城邑、山地的城邑、高原的城邑，並南地的城邑，人必用銀子買田地，在契上畫押，將契封緘，請出見證人，因為我必使被擄的人歸回。這是耶和華說的。」","notes":[]}]},"33":{"heading":"重申復國的應許","verses":[{"n":1,"t":"耶利米還囚在護衛兵的院內，耶和華的話第二次臨到他說：","notes":[]},{"n":2,"t":"「成就的是耶和華，造作、為要建立的也是耶和華；耶和華是他的名。他如此說：","notes":[]},{"n":3,"t":"你求告我，我就應允你，並將你所不知道、又大又難的事指示你。","notes":[]},{"n":4,"t":"論到這城中的房屋和猶大王的宮室，就是拆毀為擋敵人高壘和刀劍的，耶和華－以色列的神如此說：","notes":[]},{"n":5,"t":"人要與迦勒底人爭戰，正是拿死屍充滿這房屋，就是我在怒氣和忿怒中所殺的人，因他們的一切惡，我就掩面不顧這城。","notes":[]},{"n":6,"t":"看哪，我要使這城得以痊癒安舒，使城中的人得醫治，又將豐盛的平安和誠實顯明與他們。","notes":[]},{"n":7,"t":"我也要使猶大被擄的和以色列被擄的歸回，並建立他們和起初一樣。","notes":[]},{"n":8,"t":"我要除淨他們的一切罪，就是向我所犯的罪；又要赦免他們的一切罪，就是干犯我、違背我的罪。","notes":[]},{"n":9,"t":"這城要在地上萬國人面前使我得頌讚，得榮耀，名為可喜可樂之城。萬國人因聽見我向這城所賜的福樂、所施的恩惠平安，就懼怕戰兢。」","notes":[]},{"n":10,"t":"耶和華如此說：「你們論這地方，說是荒廢無人民無牲畜之地，但在這荒涼無人民無牲畜的猶大城邑和耶路撒冷的街上，","notes":[]},{"n":11,"t":"必再聽見有歡喜和快樂的聲音、新郎和新婦的聲音，並聽見有人說：要稱謝萬軍之耶和華，因耶和華本為善；他的慈愛永遠長存！又有奉感謝祭到耶和華殿中之人的聲音；因為我必使這地被擄的人歸回，和起初一樣。這是耶和華說的。」","notes":[]},{"n":12,"t":"萬軍之耶和華如此說：「在這荒廢無人民無牲畜之地，並其中所有的城邑，必再有牧人的住處；他們要使羊群躺臥在那裏。","notes":[]},{"n":13,"t":"在山地的城邑、高原的城邑、南地的城邑、便雅憫地、耶路撒冷四圍的各處，和猶大的城邑必再有羊群從數點的人手下經過。這是耶和華說的。」","notes":[]},{"n":14,"t":"耶和華說：「日子將到，我應許以色列家和猶大家的恩言必然成就。","notes":[]},{"n":15,"t":"當那日子，那時候，我必使大衛公義的苗裔長起來；他必在地上施行公平和公義。","notes":[]},{"n":16,"t":"在那日子猶大必得救，耶路撒冷必安然居住，他的名必稱為『耶和華－我們的義』。","notes":[]},{"n":17,"t":"「因為耶和華如此說：大衛必永不斷人坐在以色列家的寶座上；","notes":[]},{"n":18,"t":"祭司、利未人在我面前也不斷人獻燔祭、燒素祭，時常辦理獻祭的事。」","notes":[]},{"n":19,"t":"耶和華的話臨到耶利米說：","notes":[]},{"n":20,"t":"「耶和華如此說：你們若能廢棄我所立白日黑夜的約，使白日黑夜不按時輪轉，","notes":[]},{"n":21,"t":"就能廢棄我與我僕人大衛所立的約，使他沒有兒子在他的寶座上為王，並能廢棄我與事奉我的祭司、利未人所立的約。","notes":[]},{"n":22,"t":"天上的萬象不能數算，海邊的塵沙也不能斗量；我必照樣使我僕人大衛的後裔和事奉我的利未人多起來。」","notes":[]},{"n":23,"t":"耶和華的話臨到耶利米說：","notes":[]},{"n":24,"t":"「你沒有揣摩這百姓的話嗎？他們說：『耶和華所揀選的二族，他已經棄絕了。』他們這樣藐視我的百姓，以為不再成國。","notes":[]},{"n":25,"t":"耶和華如此說：若是我立白日黑夜的約不能存住，若是我未曾安排天地的定例，","notes":[]},{"n":26,"t":"我就棄絕雅各的後裔和我僕人大衛的後裔，不使大衛的後裔治理亞伯拉罕、以撒、雅各的後裔；因為我必使他們被擄的人歸回，也必憐憫他們。」","notes":[]}]},"34":{"heading":"給西底家的信息","verses":[{"n":1,"t":"巴比倫王尼布甲尼撒率領他的全軍和地上屬他的各國各邦，攻打耶路撒冷和屬耶路撒冷所有的城邑。那時，耶和華的話臨到耶利米說：","notes":[]},{"n":2,"t":"「耶和華－以色列的神說，你去告訴猶大王西底家，耶和華如此說：我要將這城交付巴比倫王的手，他必用火焚燒。","notes":[]},{"n":3,"t":"你必不能逃脫他的手，定被拿住，交在他的手中。你的眼要見巴比倫王的眼，他要口對口和你說話，你也必到巴比倫去。","notes":[]},{"n":4,"t":"猶大王西底家啊，你還要聽耶和華的話。耶和華論到你如此說：你必不被刀劍殺死，","notes":[]},{"n":5,"t":"你必平安而死，人必為你焚燒物件，好像為你列祖，就是在你以前的先王焚燒一般。人必為你舉哀說：『哀哉！我主啊。』耶和華說：這話是我說的。」","notes":[]},{"n":6,"t":"於是，先知耶利米在耶路撒冷將這一切話告訴猶大王西底家。","notes":[]},{"n":7,"t":"那時，巴比倫王的軍隊正攻打耶路撒冷，又攻打猶大所剩下的城邑，就是拉吉和亞西加。原來猶大的堅固城只剩下這兩座。","notes":[]},{"n":8,"t":"西底家王與耶路撒冷的眾民立約，要向他們宣告自由，叫各人任他希伯來的僕人和婢女自由出去，誰也不可使他的一個猶大弟兄作奴僕。（此後，有耶和華的話臨到耶利米。）","notes":[],"end":9,"heads":["違背釋放奴隸的約"]},{"n":10,"t":"所有立約的首領和眾民就任他的僕人婢女自由出去，誰也不再叫他們作奴僕。大家都順從，將他們釋放了；","notes":[]},{"n":11,"t":"後來卻又反悔，叫所任去自由的僕人婢女回來，勉強他們仍為僕婢。","notes":[]},{"n":12,"t":"因此耶和華的話臨到耶利米說：","notes":[]},{"n":13,"t":"「耶和華－以色列的神如此說：我將你們的列祖從埃及地為奴之家領出來的時候，與他們立約說：","notes":[]},{"n":14,"t":"『你的一個希伯來弟兄若賣給你，服事你六年，到第七年你們各人就要任他自由出去。』只是你們列祖不聽從我，也不側耳而聽。","notes":[]},{"n":15,"t":"如今你們回轉，行我眼中看為正的事，各人向鄰舍宣告自由，並且在稱為我名下的殿中、在我面前立約。","notes":[]},{"n":16,"t":"你們卻又反悔，褻瀆我的名，各人叫所任去隨意自由的僕人婢女回來，勉強他們仍為僕婢。","notes":[]},{"n":17,"t":"所以耶和華如此說：你們沒有聽從我，各人向弟兄鄰舍宣告自由。看哪！我向你們宣告一樣自由，就是使你們自由於刀劍、饑荒、瘟疫之下，並且使你們在天下萬國中拋來拋去。這是耶和華說的。","notes":[]},{"n":18,"t":"猶大的首領、耶路撒冷的首領、太監、祭司，和國中的眾民曾將牛犢劈開，分成兩半，從其中經過，在我面前立約。後來又違背我的約，不遵行這約上的話。","notes":[],"end":19},{"n":20,"t":"我必將他們交在仇敵和尋索其命的人手中；他們的屍首必給空中的飛鳥和地上的野獸作食物。","notes":[]},{"n":21,"t":"並且我必將猶大王西底家和他的首領交在他們仇敵和尋索其命的人，與那暫離你們而去巴比倫王軍隊的手中。","notes":[]},{"n":22,"t":"耶和華說：我必吩咐他們回到這城，攻打這城，將城攻取，用火焚燒。我也要使猶大的城邑變為荒場，無人居住。」","notes":[]}]},"35":{"heading":"耶利米和利甲族","verses":[{"n":1,"t":"當猶大王約西亞之子約雅敬的時候，耶和華的話臨到耶利米說：","notes":[]},{"n":2,"t":"「你去見利甲族的人，和他們說話，領他們進入耶和華殿的一間屋子，給他們酒喝。」","notes":[]},{"n":3,"t":"我就將哈巴洗尼雅的孫子雅利米雅的兒子雅撒尼亞和他弟兄，並他眾子，以及利甲全族的人，","notes":[]},{"n":4,"t":"領到耶和華的殿，進入神人伊基大利的兒子哈難眾子的屋子。那屋子在首領的屋子旁邊，在沙龍之子把門的瑪西雅屋子以上。","notes":[]},{"n":5,"t":"於是我在利甲族人面前設擺盛滿酒的碗和杯，對他們說：「請你們喝酒。」","notes":[]},{"n":6,"t":"他們卻說：「我們不喝酒；因為我們先祖利甲的兒子約拿達曾吩咐我們說：『你們與你們的子孫永不可喝酒，","notes":[]},{"n":7,"t":"也不可蓋房、撒種、栽種葡萄園，但一生的年日要住帳棚，使你們的日子在寄居之地得以延長。』","notes":[]},{"n":8,"t":"凡我們先祖利甲的兒子約拿達所吩咐我們的話，我們都聽從了。我們和我們的妻子兒女一生的年日都不喝酒，","notes":[]},{"n":9,"t":"也不蓋房居住，也沒有葡萄園、田地，和種子，","notes":[]},{"n":10,"t":"但住帳棚，聽從我們先祖約拿達的話，照他所吩咐我們的去行。","notes":[]},{"n":11,"t":"巴比倫王尼布甲尼撒上此地來，我們因怕迦勒底的軍隊和亞蘭的軍隊，就說：『來吧，我們到耶路撒冷去。』這樣，我們才住在耶路撒冷。」","notes":[]},{"n":12,"t":"耶和華的話臨到耶利米說：","notes":[]},{"n":13,"t":"「萬軍之耶和華－以色列的神如此說：你去對猶大人和耶路撒冷的居民說，耶和華說：你們不受教訓，不聽從我的話嗎？","notes":[]},{"n":14,"t":"利甲的兒子約拿達所吩咐他子孫不可喝酒的話，他們已經遵守，直到今日也不喝酒，因為他們聽從先祖的吩咐。我從早起來警戒你們，你們卻不聽從我。","notes":[]},{"n":15,"t":"我從早起來，差遣我的僕人眾先知去，說：『你們各人當回頭，離開惡道，改正行為，不隨從事奉別神，就必住在我所賜給你們和你們列祖的地上。』只是你們沒有聽從我，也沒有側耳而聽。","notes":[]},{"n":16,"t":"利甲的兒子約拿達的子孫能遵守先人所吩咐他們的命，這百姓卻沒有聽從我！","notes":[]},{"n":17,"t":"因此，耶和華－萬軍之神、以色列的神如此說：我要使我所說的一切災禍臨到猶大人和耶路撒冷的一切居民。因為我對他們說話，他們沒有聽從；我呼喚他們，他們沒有答應。」","notes":[]},{"n":18,"t":"耶利米對利甲族的人說：「萬軍之耶和華－以色列的神如此說：因你們聽從你們先祖約拿達的吩咐，謹守他的一切誡命，照他所吩咐你們的去行，","notes":[]},{"n":19,"t":"所以萬軍之耶和華－以色列的神如此說：利甲的兒子約拿達必永不缺人侍立在我面前。」","notes":[]}]},"36":{"heading":"巴錄在聖殿裏宣讀書卷","verses":[{"n":1,"t":"猶大王約西亞的兒子約雅敬第四年，耶和華的話臨到耶利米說：","notes":[]},{"n":2,"t":"「你取一書卷，將我對你說攻擊以色列和猶大，並各國的一切話，從我對你說話的那日，就是從約西亞的日子起直到今日，都寫在其上。","notes":[]},{"n":3,"t":"或者猶大家聽見我想要降與他們的一切災禍，各人就回頭，離開惡道，我好赦免他們的罪孽和罪惡。」","notes":[]},{"n":4,"t":"所以，耶利米召了尼利亞的兒子巴錄來；巴錄就從耶利米口中，將耶和華對耶利米所說的一切話寫在書卷上。","notes":[]},{"n":5,"t":"耶利米吩咐巴錄說：「我被拘管，不能進耶和華的殿。","notes":[]},{"n":6,"t":"所以你要去趁禁食的日子，在耶和華殿中將耶和華的話，就是你從我口中所寫在書卷上的話，念給百姓和一切從猶大城邑出來的人聽。","notes":[]},{"n":7,"t":"或者他們在耶和華面前懇求各人回頭，離開惡道，因為耶和華向這百姓所說要發的怒氣和忿怒是大的。」","notes":[]},{"n":8,"t":"尼利亞的兒子巴錄就照先知耶利米一切所吩咐的去行，在耶和華的殿中從書上念耶和華的話。","notes":[]},{"n":9,"t":"猶大王約西亞的兒子約雅敬第五年九月，耶路撒冷的眾民和那從猶大城邑來到耶路撒冷的眾民，在耶和華面前宣告禁食的日子，","notes":[]},{"n":10,"t":"巴錄就在耶和華殿的上院，耶和華殿的新門口，沙番的兒子文士基瑪利雅的屋內，念書上耶利米的話給眾民聽。","notes":[]},{"n":11,"t":"沙番的孫子、基瑪利雅的兒子米該亞聽見書上耶和華的一切話，","notes":[],"heads":["向官員宣讀書卷"]},{"n":12,"t":"他就下到王宮，進入文士的屋子。眾首領，就是文士以利沙瑪、示瑪雅的兒子第萊雅、亞革波的兒子以利拿單、沙番的兒子基瑪利雅、哈拿尼雅的兒子西底家，和其餘的首領都坐在那裏。","notes":[]},{"n":13,"t":"於是米該亞對他們述說他所聽見的一切話，就是巴錄向百姓念那書的時候所聽見的。","notes":[]},{"n":14,"t":"眾首領就打發古示的曾孫、示利米雅的孫子、尼探雅的兒子猶底到巴錄那裏，對他說：「你將所念給百姓聽的書卷拿在手中到我們這裏來。」尼利亞的兒子巴錄就手拿書卷來到他們那裏。","notes":[]},{"n":15,"t":"他們對他說：「請你坐下，念給我們聽。」巴錄就念給他們聽。","notes":[]},{"n":16,"t":"他們聽見這一切話就害怕，面面相觀，對巴錄說：「我們必須將這一切話告訴王。」","notes":[]},{"n":17,"t":"他們問巴錄說：「請你告訴我們，你怎樣從他口中寫這一切話呢？」","notes":[]},{"n":18,"t":"巴錄回答說：「他用口向我說這一切話，我就用筆墨寫在書上。」","notes":[]},{"n":19,"t":"眾首領對巴錄說：「你和耶利米要去藏起來，不可叫人知道你們在哪裏。」","notes":[]},{"n":20,"t":"眾首領進院見王，卻先把書卷存在文士以利沙瑪的屋內，以後將這一切話說給王聽。","notes":[],"heads":["約雅敬焚燒書卷"]},{"n":21,"t":"王就打發猶底去拿這書卷來，他便從文士以利沙瑪的屋內取來，念給王和王左右侍立的眾首領聽。","notes":[]},{"n":22,"t":"那時正是九月，王坐在過冬的房屋裏，王的前面火盆中有燒著的火。","notes":[]},{"n":23,"t":"猶底念了三四篇，王就用文士的刀將書卷割破，扔在火盆中，直到全卷在火中燒盡了。","notes":["或譯：行"]},{"n":24,"t":"王和聽見這一切話的臣僕都不懼怕，也不撕裂衣服。","notes":[]},{"n":25,"t":"以利拿單和第萊雅，並基瑪利雅懇求王不要燒這書卷，他卻不聽。","notes":[]},{"n":26,"t":"王就吩咐哈米勒的兒子耶拉篾和亞斯列的兒子西萊雅，並亞伯疊的兒子示利米雅，去捉拿文士巴錄和先知耶利米。耶和華卻將他們隱藏。","notes":["或譯：王的兒子"]},{"n":27,"t":"王燒了書卷（其上有巴錄從耶利米口中所寫的話）以後，耶和華的話臨到耶利米說：","notes":[],"heads":["耶利米另寫一書卷"]},{"n":28,"t":"「你再取一卷，將猶大王約雅敬所燒第一卷上的一切話寫在其上。","notes":[]},{"n":29,"t":"論到猶大王約雅敬你要說，耶和華如此說：你燒了書卷，說：『你為甚麼在其上寫著，說巴比倫王必要來毀滅這地，使這地上絕了人民牲畜呢？』","notes":[]},{"n":30,"t":"所以耶和華論到猶大王約雅敬說：他後裔中必沒有人坐在大衛的寶座上；他的屍首必被拋棄，白日受炎熱，黑夜受寒霜。","notes":[]},{"n":31,"t":"我必因他和他後裔，並他臣僕的罪孽刑罰他們。我要使我所說的一切災禍臨到他們和耶路撒冷的居民，並猶大人；只是他們不聽。」","notes":[]},{"n":32,"t":"於是，耶利米又取一書卷交給尼利亞的兒子文士巴錄，他就從耶利米的口中寫了猶大王約雅敬所燒前卷上的一切話，另外又添了許多相彷的話。","notes":[]}]},"37":{"heading":"西底家求耶利米代禱","verses":[{"n":1,"t":"約西亞的兒子西底家代替約雅敬的兒子哥尼雅為王，是巴比倫王尼布甲尼撒立在猶大地作王的。","notes":[]},{"n":2,"t":"但西底家和他的臣僕，並國中的百姓，都不聽從耶和華藉先知耶利米所說的話。","notes":[]},{"n":3,"t":"西底家王打發示利米雅的兒子猶甲和祭司瑪西雅的兒子西番雅去見先知耶利米，說：「求你為我們禱告耶和華－我們的神。」","notes":[]},{"n":4,"t":"那時耶利米在民中出入，因為他們還沒有把他囚在監裏。","notes":[]},{"n":5,"t":"法老的軍隊已經從埃及出來，那圍困耶路撒冷的迦勒底人聽見他們的風聲，就拔營離開耶路撒冷去了。","notes":[]},{"n":6,"t":"耶和華的話臨到先知耶利米說：","notes":[]},{"n":7,"t":"「耶和華－以色列的神如此說：猶大王打發你們來求問我，你們要如此對他說：『那出來幫助你們法老的軍隊必回埃及本國去。","notes":[]},{"n":8,"t":"迦勒底人必再來攻打這城，並要攻取，用火焚燒。","notes":[]},{"n":9,"t":"耶和華如此說：你們不要自欺說「迦勒底人必定離開我們」，因為他們必不離開。","notes":[]},{"n":10,"t":"你們即便殺敗了與你們爭戰的迦勒底全軍，但剩下受傷的人也必各人從帳棚裏起來，用火焚燒這城。』」","notes":[]},{"n":11,"t":"迦勒底的軍隊因怕法老的軍隊，拔營離開耶路撒冷的時候，","notes":[],"heads":["耶利米被捕入獄"]},{"n":12,"t":"耶利米就雜在民中出離耶路撒冷，要往便雅憫地去，在那裏得自己的地業。","notes":[]},{"n":13,"t":"他到了便雅憫門那裏，有守門官名叫伊利雅，是哈拿尼亞的孫子、示利米雅的兒子，他就拿住先知耶利米，說：「你是投降迦勒底人哪！」","notes":[]},{"n":14,"t":"耶利米說：「你這是謊話，我並不是投降迦勒底人。」伊利雅不聽他的話，就拿住他，解到首領那裏。","notes":[]},{"n":15,"t":"首領惱怒耶利米，就打了他，將他囚在文士約拿單的房屋中，因為他們以這房屋當作監牢。","notes":[]},{"n":16,"t":"耶利米來到獄中，進入牢房，在那裏囚了多日。","notes":[]},{"n":17,"t":"西底家王打發人提出他來，在自己的宮內私下問他說：「從耶和華有甚麼話臨到沒有？」耶利米說：「有！」又說：「你必交在巴比倫王手中。」","notes":[]},{"n":18,"t":"耶利米又對西底家王說：「我在甚麼事上得罪你，或你的臣僕，或這百姓，你竟將我囚在監裏呢？","notes":[]},{"n":19,"t":"對你們預言巴比倫王必不來攻擊你們和這地的先知，現今在哪裏呢？","notes":[]},{"n":20,"t":"主－我的王啊，求你現在垂聽，准我在你面前的懇求：不要使我回到文士約拿單的房屋中，免得我死在那裏。」","notes":[]},{"n":21,"t":"於是，西底家王下令，他們就把耶利米交在護衛兵的院中，每天從餅舖街取一個餅給他，直到城中的餅用盡了。這樣，耶利米仍在護衛兵的院中。","notes":[]}]},"38":{"heading":"耶利米在枯井裏","verses":[{"n":1,"t":"瑪坦的兒子示法提雅、巴施戶珥的兒子基大利、示利米雅的兒子猶甲、瑪基雅的兒子巴施戶珥聽見耶利米對眾人所說的話，說：","notes":[]},{"n":2,"t":"「耶和華如此說：住在這城裏的必遭刀劍、饑荒、瘟疫而死；但出去歸降迦勒底人的必得存活，就是以自己命為掠物的，必得存活。","notes":[]},{"n":3,"t":"耶和華如此說：這城必要交在巴比倫王軍隊的手中，他必攻取這城。」","notes":[]},{"n":4,"t":"於是首領對王說：「求你將這人治死；因他向城裏剩下的兵丁和眾民說這樣的話，使他們的手發軟。這人不是求這百姓得平安，乃是叫他們受災禍。」","notes":[]},{"n":5,"t":"西底家王說：「他在你們手中，無論何事，王也不能與你們反對。」","notes":[]},{"n":6,"t":"他們就拿住耶利米，下在哈米勒的兒子瑪基雅的牢獄裏；那牢獄在護衛兵的院中。他們用繩子將耶利米繫下去。牢獄裏沒有水，只有淤泥，耶利米就陷在淤泥中。","notes":["或譯：王的兒子"]},{"n":7,"t":"在王宮的太監古實人以伯‧米勒，聽見他們將耶利米下了牢獄（那時王坐在便雅憫門口），","notes":[]},{"n":8,"t":"以伯‧米勒就從王宮裏出來，對王說：","notes":[]},{"n":9,"t":"「主－我的王啊，這些人向先知耶利米一味地行惡，將他下在牢獄中；他在那裏必因飢餓而死，因為城中再沒有糧食。」","notes":[]},{"n":10,"t":"王就吩咐古實人以伯‧米勒說：「你從這裏帶領三十人，趁著先知耶利米未死以前，將他從牢獄中提上來。」","notes":[]},{"n":11,"t":"於是以伯‧米勒帶領這些人同去，進入王宮，到庫房以下，從那裏取了些碎布和破爛的衣服，用繩子縋下牢獄去到耶利米那裏。","notes":[]},{"n":12,"t":"古實人以伯‧米勒對耶利米說：「你用這些碎布和破爛的衣服放在繩子上，墊你的胳肢窩。」耶利米就照樣行了。","notes":[]},{"n":13,"t":"這樣，他們用繩子將耶利米從牢獄裏拉上來。耶利米仍在護衛兵的院中。","notes":[]},{"n":14,"t":"西底家王打發人帶領先知耶利米，進耶和華殿中第三門裏見王。王就對耶利米說：「我要問你一件事，你絲毫不可向我隱瞞。」","notes":[],"heads":["西底家問計於耶利米"]},{"n":15,"t":"耶利米對西底家說：「我若告訴你，你豈不定要殺我嗎？我若勸戒你，你必不聽從我。」","notes":[]},{"n":16,"t":"西底家王就私下向耶利米說：「我指著那造我們生命之永生的耶和華起誓：我必不殺你，也不將你交在尋索你命的人手中。」","notes":[]},{"n":17,"t":"耶利米對西底家說：「耶和華－萬軍之神、以色列的神如此說：你若出去歸降巴比倫王的首領，你的命就必存活，這城也不致被火焚燒，你和你的全家都必存活。","notes":[]},{"n":18,"t":"你若不出去歸降巴比倫王的首領，這城必交在迦勒底人手中。他們必用火焚燒，你也不得脫離他們的手。」","notes":[]},{"n":19,"t":"西底家王對耶利米說：「我怕那些投降迦勒底人的猶大人，恐怕迦勒底人將我交在他們手中，他們戲弄我。」","notes":[]},{"n":20,"t":"耶利米說：「迦勒底人必不將你交出。求你聽從我對你所說耶和華的話，這樣你必得好處，你的命也必存活。","notes":[]},{"n":21,"t":"你若不肯出去，耶和華指示我的話乃是這樣：","notes":[]},{"n":22,"t":"猶大王宮裏所剩的婦女必都帶到巴比倫王的首領那裏。這些婦女必說：你知己的朋友催逼你，勝過你；見你的腳陷入淤泥中，就轉身退後了。","notes":[]},{"n":23,"t":"「人必將你的后妃和你的兒女帶到迦勒底人那裏；你也不得脫離他們的手，必被巴比倫王的手捉住；你也必使這城被火焚燒。」","notes":[]},{"n":24,"t":"西底家對耶利米說：「不要使人知道這些話，你就不至於死。","notes":[]},{"n":25,"t":"首領若聽見了我與你說話，就來見你，問你說：『你對王說甚麼話不要向我們隱瞞，我們就不殺你。王向你說甚麼話也要告訴我們。』","notes":[]},{"n":26,"t":"你就對他們說：『我在王面前懇求不要叫我回到約拿單的房屋死在那裏。』」","notes":[]},{"n":27,"t":"隨後眾首領來見耶利米，問他，他就照王所吩咐的一切話回答他們。他們不再與他說話，因為事情沒有洩漏。","notes":[]},{"n":28,"t":"於是耶利米仍在護衛兵的院中，直到耶路撒冷被攻取的日子。","notes":[]}]},"39":{"heading":"耶路撒冷陷落","verses":[{"n":1,"t":"猶大王西底家第九年十月，巴比倫王尼布甲尼撒率領全軍來圍困耶路撒冷。","notes":[]},{"n":2,"t":"西底家十一年四月初九日，城被攻破。","notes":[]},{"n":3,"t":"耶路撒冷被攻取的時候，巴比倫王的首領尼甲‧沙利薛、三甲‧尼波、撒西金－拉撒力、尼甲‧沙利薛－拉墨，並巴比倫王其餘的一切首領都來坐在中門。","notes":[]},{"n":4,"t":"猶大王西底家和一切兵丁看見他們，就在夜間從靠近王園兩城中間的門出城逃跑，往亞拉巴逃去。","notes":[]},{"n":5,"t":"迦勒底的軍隊追趕他們，在耶利哥的平原追上西底家，將他拿住，帶到哈馬地的利比拉、巴比倫王尼布甲尼撒那裏；尼布甲尼撒就審判他。","notes":[]},{"n":6,"t":"巴比倫王在利比拉、西底家眼前殺了他的眾子，又殺了猶大的一切貴冑，","notes":[]},{"n":7,"t":"並且剜西底家的眼睛，用銅鍊鎖著他，要帶到巴比倫去。","notes":[]},{"n":8,"t":"迦勒底人用火焚燒王宮和百姓的房屋，又拆毀耶路撒冷的城牆。","notes":[]},{"n":9,"t":"那時，護衛長尼布撒拉旦將城裏所剩下的百姓和投降他的逃民，以及其餘的民都擄到巴比倫去了。","notes":[]},{"n":10,"t":"護衛長尼布撒拉旦卻將民中毫無所有的窮人留在猶大地，當時給他們葡萄園和田地。","notes":[]},{"n":11,"t":"巴比倫王尼布甲尼撒提到耶利米，囑咐護衛長尼布撒拉旦說：","notes":[],"heads":["耶利米被釋放"]},{"n":12,"t":"「你領他去，好好地看待他，切不可害他；他對你怎麼說，你就向他怎麼行。」","notes":[]},{"n":13,"t":"護衛長尼布撒拉旦和尼布沙斯班－拉撒力、尼甲‧沙利薛－拉墨，並巴比倫王的一切官長，","notes":[]},{"n":14,"t":"打發人去，將耶利米從護衛兵院中提出來，交與沙番的孫子亞希甘的兒子基大利，帶回家去。於是耶利米住在民中。","notes":[]},{"n":15,"t":"耶利米還囚在護衛兵院中的時候，耶和華的話臨到他說：","notes":[],"heads":["以伯‧米勒的希望"]},{"n":16,"t":"「你去告訴古實人以伯‧米勒說，萬軍之耶和華－以色列的神如此說：我說降禍不降福的話必臨到這城，到那時必在你面前成就了。","notes":[]},{"n":17,"t":"耶和華說：到那日我必拯救你，你必不致交在你所怕的人手中。","notes":[]},{"n":18,"t":"我定要搭救你，你不致倒在刀下，卻要以自己的命為掠物，因你倚靠我。這是耶和華說的。」","notes":[]}]},"40":{"heading":"耶利米跟基大利同住","verses":[{"n":1,"t":"耶利米鎖在耶路撒冷和猶大被擄到巴比倫的人中，護衛長尼布撒拉旦將他從拉瑪釋放以後，耶和華的話臨到耶利米。","notes":[]},{"n":2,"t":"護衛長將耶利米叫來，對他說：「耶和華－你的神曾說要降這禍與此地。","notes":[]},{"n":3,"t":"耶和華使這禍臨到，照他所說的行了；因為你們得罪耶和華，沒有聽從他的話，所以這事臨到你們。","notes":[]},{"n":4,"t":"現在我解開你手上的鍊子，你若看與我同往巴比倫去好，就可以去，我必厚待你；你若看與我同往巴比倫去不好，就不必去。看哪，全地在你面前，你以為哪裏美好，哪裏合宜，只管上那裏去吧！」","notes":[]},{"n":5,"t":"耶利米還沒有回去，護衛長說：「你可以回到沙番的孫子亞希甘的兒子基大利那裏去；現在巴比倫王立他作猶大城邑的省長。你可以在他那裏住在民中，不然，你看哪裏合宜就可以上那裏去。」於是護衛長送他糧食和禮物，釋放他去了。","notes":[]},{"n":6,"t":"耶利米就到米斯巴見亞希甘的兒子基大利，在他那裏住在境內剩下的民中。","notes":[]},{"n":7,"t":"在田野的一切軍長和屬他們的人聽見巴比倫王立了亞希甘的兒子基大利作境內的省長，並將沒有擄到巴比倫的男人、婦女、孩童，和境內極窮的人全交給他。","notes":[],"heads":["基大利被委派為總督"]},{"n":8,"t":"於是軍長尼探雅的兒子以實瑪利，加利亞的兩個兒子約哈難和約拿單，單戶篾的兒子西萊雅，並尼陀法人以斐的眾子，瑪迦人的兒子耶撒尼亞和屬他們的人，都到米斯巴見基大利。","notes":[]},{"n":9,"t":"沙番的孫子亞希甘的兒子基大利向他們和屬他們的人起誓說：「不要怕服事迦勒底人，只管住在這地，服事巴比倫王，就可以得福。","notes":[]},{"n":10,"t":"至於我，我要住在米斯巴，伺候那到我們這裏來的迦勒底人；只是你們當積蓄酒、油，和夏天的果子，收在器皿裏，住在你們所佔的城邑中。」","notes":[]},{"n":11,"t":"在摩押地和亞捫人中，在以東地和各國的一切猶大人，聽見巴比倫王留下些猶大人，並立沙番的孫子亞希甘的兒子基大利管理他們。","notes":[]},{"n":12,"t":"這一切猶大人就從所趕到的各處回來，到猶大地米斯巴的基大利那裏，又積蓄了許多的酒，並夏天的果子。","notes":[]},{"n":13,"t":"加利亞的兒子約哈難和在田野的一切軍長來到米斯巴見基大利，","notes":[],"heads":["基大利被暗殺"]},{"n":14,"t":"對他說：「亞捫人的王巴利斯打發尼探雅的兒子以實瑪利來要你的命，你知道嗎？」亞希甘的兒子基大利卻不信他們的話。","notes":[]},{"n":15,"t":"加利亞的兒子約哈難在米斯巴私下對基大利說：「求你容我去殺尼探雅的兒子以實瑪利，必無人知道。何必讓他要你的命，使聚集到你這裏來的猶大人都分散，以致猶大剩下的人都滅亡呢？」","notes":[]},{"n":16,"t":"亞希甘的兒子基大利對加利亞的兒子約哈難說：「你不可行這事，你所論以實瑪利的話是假的。」","notes":[]}]},"41":{"heading":"","verses":[{"n":1,"t":"七月間，王的大臣宗室以利沙瑪的孫子、尼探雅的兒子以實瑪利帶著十個人，來到米斯巴見亞希甘的兒子基大利。他們在米斯巴一同吃飯。","notes":[]},{"n":2,"t":"尼探雅的兒子以實瑪利和同他來的那十個人起來，用刀殺了沙番的孫子亞希甘的兒子基大利，就是巴比倫王所立為全地省長的。","notes":[]},{"n":3,"t":"以實瑪利又殺了在米斯巴、基大利那裏的一切猶大人和所遇見的迦勒底兵丁。","notes":[]},{"n":4,"t":"他殺了基大利，無人知道。","notes":[]},{"n":5,"t":"第二天，有八十人從示劍和示羅，並撒馬利亞來，鬍鬚剃去，衣服撕裂，身體劃破，手拿素祭和乳香，要奉到耶和華的殿。","notes":[]},{"n":6,"t":"尼探雅的兒子以實瑪利出米斯巴迎接他們，隨走隨哭；遇見了他們，就對他們說：「你們可以來見亞希甘的兒子基大利。」","notes":[]},{"n":7,"t":"他們到了城中，尼探雅的兒子以實瑪利和同著他的人就將他們殺了，拋在坑中。","notes":[]},{"n":8,"t":"只是他們中間有十個人對以實瑪利說：「不要殺我們，因為我們有許多大麥、小麥、油、蜜藏在田間。」於是他住了手，沒有將他們殺在弟兄中間。","notes":[]},{"n":9,"t":"以實瑪利將所殺之人的屍首都拋在坑裏基大利的旁邊；這坑是從前亞撒王因怕以色列王巴沙所挖的。尼探雅的兒子以實瑪利將那些被殺的人填滿了坑。","notes":[]},{"n":10,"t":"以實瑪利將米斯巴剩下的人，就是眾公主和仍住在米斯巴所有的百姓，原是護衛長尼布撒拉旦交給亞希甘的兒子基大利的，都擄去了。尼探雅的兒子以實瑪利擄了他們，要往亞捫人那裏去。","notes":[]},{"n":11,"t":"加利亞的兒子約哈難和同著他的眾軍長聽見尼探雅的兒子以實瑪利所行的一切惡，","notes":[]},{"n":12,"t":"就帶領眾人前往，要和尼探雅的兒子以實瑪利爭戰，在基遍的大水旁遇見他。","notes":["或譯：大水池旁"]},{"n":13,"t":"以實瑪利那裏的眾人看見加利亞的兒子約哈難和同著他的眾軍長，就都歡喜。","notes":[]},{"n":14,"t":"這樣，以實瑪利從米斯巴所擄去的眾人都轉身歸加利亞的兒子約哈難去了。","notes":[]},{"n":15,"t":"尼探雅的兒子以實瑪利和八個人脫離約哈難的手，逃往亞捫人那裏去了。","notes":[]},{"n":16,"t":"尼探雅的兒子以實瑪利殺了亞希甘的兒子基大利，從米斯巴將剩下的一切百姓、兵丁、婦女、孩童、太監擄到基遍之後，加利亞的兒子約哈難和同著他的眾軍長將他們都奪回來，","notes":[]},{"n":17,"t":"帶到靠近伯利恆的金罕寓住下，要進入埃及去；","notes":["或譯：基羅特金罕"]},{"n":18,"t":"因為尼探雅的兒子以實瑪利殺了巴比倫王所立為省長的亞希甘的兒子基大利，約哈難懼怕迦勒底人。","notes":[]}]},"42":{"heading":"百姓求耶利米代禱","verses":[{"n":1,"t":"眾軍長和加利亞的兒子約哈難，並何沙雅的兒子耶撒尼亞以及眾百姓，從最小的到至大的都進前來，","notes":["又名亞撒利雅，見四十三章二節"]},{"n":2,"t":"對先知耶利米說：「求你准我們在你面前祈求，為我們這剩下的人禱告耶和華－你的神。我們本來眾多，現在剩下的極少，這是你親眼所見的。","notes":[]},{"n":3,"t":"願耶和華－你的神指示我們所當走的路，所當做的事。」","notes":[]},{"n":4,"t":"先知耶利米對他們說：「我已經聽見你們了，我必照著你們的話禱告耶和華－你們的神。耶和華無論回答甚麼，我必都告訴你們，毫不隱瞞。」","notes":[]},{"n":5,"t":"於是他們對耶利米說：「我們若不照耶和華－你的神差遣你來說的一切話行，願耶和華在我們中間作真實誠信的見證。","notes":[]},{"n":6,"t":"我們現在請你到耶和華－我們的神面前，他說的無論是好是歹，我們都必聽從；我們聽從耶和華－我們神的話，就可以得福。」","notes":[]},{"n":7,"t":"過了十天，耶和華的話臨到耶利米。","notes":[],"heads":["耶和華回答耶利米的禱告"]},{"n":8,"t":"他就將加利亞的兒子約哈難和同著他的眾軍長，並眾百姓，從最小的到至大的都叫了來，","notes":[]},{"n":9,"t":"對他們說：「耶和華－以色列的神，就是你們請我在他面前為你們祈求的主，如此說：","notes":[]},{"n":10,"t":"『你們若仍住在這地，我就建立你們，必不拆毀，栽植你們，並不拔出，因我為降與你們的災禍後悔了。","notes":[]},{"n":11,"t":"不要怕你們所怕的巴比倫王。』」耶和華說：「不要怕他！因為我與你們同在，要拯救你們脫離他的手。","notes":[]},{"n":12,"t":"我也要使他發憐憫，好憐憫你們，叫你們歸回本地。","notes":[]},{"n":13,"t":"倘若你們說：『我們不住在這地』，以致不聽從耶和華－你們神的話，","notes":[]},{"n":14,"t":"說：『我們不住這地，卻要進入埃及地，在那裏看不見爭戰，聽不見角聲，也不致無食飢餓。我們必住在那裏。』","notes":[]},{"n":15,"t":"你們所剩下的猶大人哪，現在要聽耶和華的話。萬軍之耶和華－以色列的神如此說：『你們若定意要進入埃及，在那裏寄居，","notes":[]},{"n":16,"t":"你們所懼怕的刀劍在埃及地必追上你們！你們所懼怕的饑荒在埃及要緊緊地跟隨你們！你們必死在那裏！","notes":[]},{"n":17,"t":"凡定意要進入埃及在那裏寄居的必遭刀劍、饑荒、瘟疫而死，無一人存留，逃脫我所降與他們的災禍。』","notes":[]},{"n":18,"t":"「萬軍之耶和華－以色列的神如此說：『我怎樣將我的怒氣和忿怒傾在耶路撒冷的居民身上，你們進入埃及的時候，我也必照樣將我的忿怒傾在你們身上，以致你們令人辱罵、驚駭、咒詛、羞辱，你們不得再見這地方。』","notes":[]},{"n":19,"t":"所剩下的猶大人哪，耶和華論到你們說：『不要進入埃及去。』你們要確實地知道我今日警教你們了。","notes":[]},{"n":20,"t":"你們行詭詐自害；因為你們請我到耶和華－你們的神那裏，說：『求你為我們禱告耶和華－我們神，照耶和華－我們的神一切所說的告訴我們，我們就必遵行。』","notes":[]},{"n":21,"t":"我今日將這話告訴你們，耶和華－你們的神為你們的事差遣我到你們那裏說的，你們卻一樣沒有聽從。","notes":[]},{"n":22,"t":"現在你們要確實地知道，你們在所要去寄居之地必遭刀劍、饑荒、瘟疫而死。」","notes":[]}]},"43":{"heading":"耶利米被帶到埃及","verses":[{"n":1,"t":"耶利米向眾百姓說完了耶和華－他們神的一切話，就是耶和華－他們神差遣他去所說的一切話。","notes":[]},{"n":2,"t":"何沙雅的兒子亞撒利雅和加利亞的兒子約哈難，並一切狂傲的人，就對耶利米說：「你說謊言！耶和華－我們的神並沒有差遣你來說：『你們不可進入埃及，在那裏寄居。』","notes":[]},{"n":3,"t":"這是尼利亞的兒子巴錄挑唆你害我們，要將我們交在迦勒底人的手中，使我們有被殺的，有被擄到巴比倫去的。」","notes":[]},{"n":4,"t":"於是加利亞的兒子約哈難和一切軍長，並眾百姓，不聽從耶和華的話住在猶大地。","notes":[]},{"n":5,"t":"加利亞的兒子約哈難和一切軍長卻將所剩下的猶大人，就是從被趕到各國回來在猶大地寄居的男人、婦女、孩童，和眾公主，並護衛長尼布撒拉旦所留在沙番的孫子亞希甘的兒子基大利那裏的眾人，與先知耶利米，以及尼利亞的兒子巴錄，","notes":[],"end":6},{"n":7,"t":"都帶入埃及地，到了答比匿。這是因他們不聽從耶和華的話。","notes":[]},{"n":8,"t":"在答比匿，耶和華的話臨到耶利米說：","notes":[]},{"n":9,"t":"「你在猶大人眼前要用手拿幾塊大石頭，藏在砌磚的灰泥中，就是在答比匿法老的宮門那裏，","notes":[]},{"n":10,"t":"對他們說：『萬軍之耶和華－以色列的神如此說：我必召我的僕人巴比倫王尼布甲尼撒來。在所藏的石頭上我要安置他的寶座；他必將光華的寶帳支搭在其上。","notes":[]},{"n":11,"t":"他要來攻擊埃及地，定為死亡的，必致死亡；定為擄掠的，必被擄掠；定為刀殺的，必交刀殺。","notes":[]},{"n":12,"t":"我要在埃及神的廟中使火著起，巴比倫王要將廟宇焚燒，神像擄去；他要得埃及地，好像牧人披上外衣，從那裏安然而去。","notes":["原文是披上"]},{"n":13,"t":"他必打碎埃及地伯‧示麥的柱像，用火焚燒埃及神的廟宇。』」","notes":[]}]},"44":{"heading":"耶和華給流亡埃及的以色列人的信息","verses":[{"n":1,"t":"有臨到耶利米的話，論及一切住在埃及地的猶大人，就是住在密奪、答比匿、挪弗、巴忒羅境內的猶大人，說：","notes":[]},{"n":2,"t":"「萬軍之耶和華－以色列的神如此說：我所降與耶路撒冷和猶大各城的一切災禍你們都看見了。那些城邑今日荒涼，無人居住；","notes":[]},{"n":3,"t":"這是因居民所行的惡，去燒香事奉別神，就是他們和你們，並你們列祖所不認識的神，惹我發怒。","notes":[]},{"n":4,"t":"我從早起來差遣我的僕人眾先知去說，你們切不要行我所厭惡這可憎之事。","notes":[]},{"n":5,"t":"他們卻不聽從，不側耳而聽，不轉離惡事，仍向別神燒香。","notes":[]},{"n":6,"t":"因此，我的怒氣和忿怒都倒出來，在猶大城邑中和耶路撒冷的街市上，如火著起，以致都荒廢淒涼，正如今日一樣。","notes":[]},{"n":7,"t":"現在耶和華－萬軍之神、以色列的神如此說：你們為何作這大惡自害己命，使你們的男人、婦女、嬰孩，和吃奶的都從猶大中剪除、不留一人呢？","notes":[]},{"n":8,"t":"就是因你們手所做的，在所去寄居的埃及地向別神燒香惹我發怒，使你們被剪除，在天下萬國中令人咒詛羞辱。","notes":[]},{"n":9,"t":"你們列祖的惡行，猶大列王和他們后妃的惡行，你們自己和你們妻子的惡行，就是在猶大地、耶路撒冷街上所行的，你們都忘了嗎？","notes":[]},{"n":10,"t":"到如今還沒有懊悔，沒有懼怕，沒有遵行我在你們和你們列祖面前所設立的法度律例。","notes":[]},{"n":11,"t":"「所以萬軍之耶和華－以色列的神如此說：我必向你們變臉降災，以致剪除猶大眾人。","notes":[]},{"n":12,"t":"那定意進入埃及地、在那裏寄居的，就是所剩下的猶大人，我必使他們盡都滅絕，必在埃及地仆倒，必因刀劍饑荒滅絕；從最小的到至大的都必遭刀劍饑荒而死，以致令人辱罵、驚駭、咒詛、羞辱。","notes":[]},{"n":13,"t":"我怎樣用刀劍、饑荒、瘟疫刑罰耶路撒冷，也必照樣刑罰那些住在埃及地的猶大人；","notes":[]},{"n":14,"t":"甚至那進入埃及地寄居的，就是所剩下的猶大人，都不得逃脫，也不得存留歸回猶大地。他們心中甚想歸回居住之地；除了逃脫的以外，一個都不能歸回。」","notes":[]},{"n":15,"t":"那些住在埃及地巴忒羅知道自己妻子向別神燒香的，與旁邊站立的眾婦女，聚集成群，回答耶利米說：","notes":[]},{"n":16,"t":"「論到你奉耶和華的名向我們所說的話，我們必不聽從。","notes":[]},{"n":17,"t":"我們定要成就我們口中所出的一切話，向天后燒香、澆奠祭，按著我們與我們列祖、君王、首領在猶大的城邑中和耶路撒冷的街市上素常所行的一樣；因為那時我們吃飽飯、享福樂，並不見災禍。","notes":[]},{"n":18,"t":"自從我們停止向天后燒香、澆奠祭，我們倒缺乏一切，又因刀劍饑荒滅絕。」","notes":[]},{"n":19,"t":"婦女說：「我們向天后燒香、澆奠祭，做天后像的餅供奉她，向她澆奠祭，是外乎我們的丈夫嗎？」","notes":[]},{"n":20,"t":"耶利米對一切那樣回答他的男人婦女說：","notes":[]},{"n":21,"t":"「你們與你們列祖、君王、首領，並國內的百姓，在猶大城邑中和耶路撒冷街市上所燒的香，耶和華豈不記念，心中豈不思想嗎？","notes":[]},{"n":22,"t":"耶和華因你們所作的惡、所行可憎的事，不能再容忍，所以你們的地荒涼，令人驚駭咒詛，無人居住，正如今日一樣。","notes":[]},{"n":23,"t":"你們燒香，得罪耶和華，沒有聽從他的話，沒有遵行他的律法、條例、法度，所以你們遭遇這災禍，正如今日一樣。」","notes":[]},{"n":24,"t":"耶利米又對眾民和眾婦女說：「你們在埃及地的一切猶大人當聽耶和華的話。","notes":[]},{"n":25,"t":"萬軍之耶和華－以色列的神如此說：你們和你們的妻都口中說、手裏做，說：『我們定要償還所許的願，向天后燒香、澆奠祭。』現在你們只管堅定所許的願而償還吧！","notes":[]},{"n":26,"t":"所以你們住在埃及地的一切猶大人當聽耶和華的話。耶和華說：我指著我的大名起誓，在埃及全地，我的名不再被猶大一個人的口稱呼說：『我指著主－永生的耶和華起誓。』","notes":[]},{"n":27,"t":"我向他們留意降禍不降福；在埃及地的一切猶大人必因刀劍、饑荒所滅，直到滅盡。","notes":[]},{"n":28,"t":"脫離刀劍、從埃及地歸回猶大地的人數很少；那進入埃及地要在那裏寄居的，就是所剩下的猶大人，必知道是誰的話立得住，是我的話呢？是他們的話呢？","notes":[]},{"n":29,"t":"耶和華說：我在這地方刑罰你們，必有預兆，使你們知道我降禍與你們的話必要立得住。","notes":[]},{"n":30,"t":"耶和華如此說：我必將埃及王法老合弗拉交在他仇敵和尋索其命的人手中，像我將猶大王西底家交在他仇敵和尋索其命的巴比倫王尼布甲尼撒手中一樣。」","notes":[]}]},"45":{"heading":"耶和華給巴錄的許諾","verses":[{"n":1,"t":"猶大王約西亞的兒子約雅敬第四年，尼利亞的兒子巴錄將先知耶利米口中所說的話寫在書上。耶利米說：","notes":[]},{"n":2,"t":"「巴錄啊，耶和華－以色列的神說：","notes":[]},{"n":3,"t":"巴錄曾說：『哀哉！耶和華將憂愁加在我的痛苦上，我因唉哼而困乏，不得安歇。』","notes":["原文是你"]},{"n":4,"t":"你要這樣告訴他，耶和華如此說：我所建立的，我必拆毀；我所栽植的，我必拔出；在全地我都如此行。","notes":[]},{"n":5,"t":"你為自己圖謀大事嗎？不要圖謀！我必使災禍臨到凡有血氣的。但你無論往哪裏去，我必使你以自己的命為掠物。這是耶和華說的。」","notes":[]}]},"46":{"heading":"埃及在迦基米施受挫","verses":[{"n":1,"t":"耶和華論列國的話臨到先知耶利米。","notes":[]},{"n":2,"t":"論到關乎埃及王法老尼哥的軍隊：這軍隊安營在幼發拉底河邊的迦基米施，是巴比倫王尼布甲尼撒在猶大王約西亞的兒子約雅敬第四年所打敗的。","notes":[]},{"n":3,"t":"你們要預備大小盾牌，往前上陣。","notes":[]},{"n":4,"t":"你們套上車，騎上馬！頂盔站立，磨槍貫甲！","notes":[]},{"n":5,"t":"我為何看見他們驚惶轉身退後呢？他們的勇士打敗了，急忙逃跑，並不回頭；驚嚇四圍都有！這是耶和華說的。","notes":[]},{"n":6,"t":"不要容快跑的逃避；不要容勇士逃脫；他們在北方幼發拉底河邊絆跌仆倒。","notes":["或譯：快跑的不能逃避；勇士不能逃脫"]},{"n":7,"t":"像尼羅河漲發，像江河之水翻騰的是誰呢？","notes":[]},{"n":8,"t":"埃及像尼羅河漲發，像江河的水翻騰。他說：我要漲發遮蓋遍地；我要毀滅城邑和其中的居民。","notes":[]},{"n":9,"t":"馬匹上去吧！車輛急行吧！勇士，就是手拿盾牌的古實人和弗人，並拉弓的路德族，都出去吧！","notes":["又作利比亞人"]},{"n":10,"t":"那日是主－萬軍之耶和華報仇的日子，要向敵人報仇。刀劍必吞吃得飽，飲血飲足；因為主－萬軍之耶和華在北方幼發拉底河邊有獻祭的事。","notes":[]},{"n":11,"t":"埃及的民哪，可以上基列取乳香去；你雖多服良藥，總是徒然，不得治好。","notes":["原文是處女"]},{"n":12,"t":"列國聽見你的羞辱，遍地滿了你的哀聲；勇士與勇士彼此相碰，一齊跌倒。","notes":[]},{"n":13,"t":"耶和華對先知耶利米所說的話，論到巴比倫王尼布甲尼撒要來攻擊埃及地：","notes":[],"heads":["尼布甲尼撒來犯"]},{"n":14,"t":"你們要傳揚在埃及，宣告在密奪，報告在挪弗、答比匿說：要站起出隊，自作準備，因為刀劍在你四圍施行吞滅的事。","notes":[]},{"n":15,"t":"你的壯士為何被沖去呢？他們站立不住；因為耶和華驅逐他們，","notes":[]},{"n":16,"t":"使多人絆跌；他們也彼此撞倒，說：起來吧！我們再往本民本地去，好躲避欺壓的刀劍。","notes":[]},{"n":17,"t":"他們在那裏喊叫說：埃及王法老不過是個聲音；他已錯過所定的時候了。","notes":["或譯：已經敗亡"]},{"n":18,"t":"君王－名為萬軍之耶和華的說：我指著我的永生起誓：尼布甲尼撒來的勢派必像他泊在眾山之中，像迦密在海邊一樣。","notes":["原文是他"]},{"n":19,"t":"住在埃及的民哪，要預備擄去時所用的物件；因為挪弗必成為荒場，且被燒毀，無人居住。","notes":["原文是女子"]},{"n":20,"t":"埃及是肥美的母牛犢；但出於北方的毀滅來到了！來到了！","notes":["或譯：牛"]},{"n":21,"t":"其中的雇勇好像圈裏的肥牛犢，他們轉身退後，一齊逃跑，站立不住；因為他們遭難的日子、追討的時候已經臨到。","notes":[]},{"n":22,"t":"其中的聲音好像蛇行一樣。敵人要成隊而來，如砍伐樹木的手拿斧子攻擊他。","notes":[]},{"n":23,"t":"耶和華說：埃及的樹林雖然不能尋察，敵人卻要砍伐，因他們多於蝗蟲，不可勝數。","notes":["或譯：穿不過"]},{"n":24,"t":"埃及的民必然蒙羞，必交在北方人的手中。","notes":["原文是女子"]},{"n":25,"t":"萬軍之耶和華－以色列的神說：「我必刑罰挪的亞捫和法老，並埃及與埃及的神，以及君王，也必刑罰法老和倚靠他的人。","notes":["埃及尊大之神"]},{"n":26,"t":"我要將他們交付尋索其命之人的手和巴比倫王尼布甲尼撒與他臣僕的手；以後埃及必再有人居住，與從前一樣。這是耶和華說的。」","notes":[]},{"n":27,"t":"我的僕人雅各啊，不要懼怕！以色列啊，不要驚惶！因我要從遠方拯救你，從被擄到之地拯救你的後裔。雅各必回來，得享平靖安逸，無人使他害怕。","notes":[],"heads":["耶和華要救他的子民"]},{"n":28,"t":"我的僕人雅各啊，不要懼怕！因我與你同在。我要將我所趕你到的那些國滅絕淨盡，卻不將你滅絕淨盡，倒要從寬懲治你，萬不能不罰你。這是耶和華說的。","notes":["不罰你：或譯以你為無罪"]}]},"47":{"heading":"有關非利士的話","verses":[{"n":1,"t":"法老攻擊迦薩之先，有耶和華論非利士人的話臨到先知耶利米。","notes":[]},{"n":2,"t":"耶和華如此說：有水從北方發起，成為漲溢的河，要漲過遍地和其中所有的，並城和其中所住的。人必呼喊；境內的居民都必哀號。","notes":[]},{"n":3,"t":"聽見敵人壯馬蹄跳的響聲和戰車隆隆、車輪轟轟；為父的手就發軟，不回頭看顧兒女。","notes":[]},{"n":4,"t":"因為日子將到，要毀滅一切非利士人，剪除幫助泰爾、西頓所剩下的人。原來耶和華必毀滅非利士人，就是迦斐託海島餘剩的人。","notes":[]},{"n":5,"t":"迦薩成了光禿；平原中所剩的亞實基倫歸於無有。你用刀劃身，要到幾時呢？","notes":[]},{"n":6,"t":"耶和華的刀劍哪，你到幾時才止息呢？你要入鞘，安靖不動。","notes":[]},{"n":7,"t":"耶和華既吩咐你攻擊亞實基倫和海邊之地，他已經派定你，焉能止息呢？","notes":[]}]},"48":{"heading":"摩押的毀滅","verses":[{"n":1,"t":"論摩押。萬軍之耶和華－以色列的神如此說：尼波有禍了！因變為荒場。基列亭蒙羞被攻取；米斯迦蒙羞被毀壞；","notes":[]},{"n":2,"t":"摩押不再被稱讚。有人在希實本設計謀害她，說：來吧！我們將她剪除，不再成國。瑪得緬哪，你也必默默無聲；刀劍必追趕你。","notes":[]},{"n":3,"t":"從何羅念有喊荒涼大毀滅的哀聲：","notes":[]},{"n":4,"t":"摩押毀滅了！她的孩童發哀聲，使人聽見。","notes":["或譯：家僮"]},{"n":5,"t":"人上魯希坡隨走隨哭，因為在何羅念的下坡聽見毀滅的哀聲。","notes":[]},{"n":6,"t":"你們要奔逃，自救性命，獨自居住，好像曠野的杜松。","notes":[]},{"n":7,"t":"你因倚靠自己所做的和自己的財寶必被攻取。基抹和屬他的祭司、首領也要一同被擄去。","notes":[]},{"n":8,"t":"行毀滅的必來到各城，並無一城得免。山谷必致敗落，平原必被毀壞；正如耶和華所說的。","notes":[]},{"n":9,"t":"要將翅膀給摩押，使她可以飛去。她的城邑必致荒涼，無人居住。（","notes":[]},{"n":10,"t":"懶惰為耶和華行事的，必受咒詛；禁止刀劍不經血的，必受咒詛。）","notes":[]},{"n":11,"t":"摩押自幼年以來常享安逸，如酒在渣滓上澄清，沒有從這器皿倒在那器皿裏，也未曾被擄去。因此，它的原味尚存，香氣未變。","notes":[],"heads":["摩押的城鎮被毀滅"]},{"n":12,"t":"耶和華說：「日子將到，我必打發倒酒的往她那裏去，將她倒出來，倒空她的器皿，打碎她的罈子。","notes":[]},{"n":13,"t":"摩押必因基抹羞愧，像以色列家從前倚靠伯特利的神羞愧一樣。","notes":[]},{"n":14,"t":"你們怎麼說：我們是勇士，是有勇力打仗的呢？","notes":[]},{"n":15,"t":"摩押變為荒場，敵人上去進了她的城邑。她所特選的少年人下去遭了殺戮；這是君王－名為萬軍之耶和華說的。","notes":[]},{"n":16,"t":"摩押的災殃臨近；她的苦難速速來到。","notes":[]},{"n":17,"t":"凡在她四圍的和認識她名的，你們都要為她悲傷，說：那結實的杖和那美好的棍，何竟折斷了呢？","notes":[]},{"n":18,"t":"住在底本的民哪，要從你榮耀的位上下來，坐受乾渴；因毀滅摩押的上來攻擊你，毀壞了你的保障。","notes":["原文是女子"]},{"n":19,"t":"住亞羅珥的啊，要站在道旁觀望，問逃避的男人和逃脫的女人說：是甚麼事呢？","notes":[]},{"n":20,"t":"摩押因毀壞蒙羞；你們要哀號呼喊，要在亞嫩旁報告說：摩押變為荒場！","notes":[]},{"n":21,"t":"「刑罰臨到平原之地的何倫、雅雜、米法押、","notes":[]},{"n":22,"t":"底本、尼波、伯‧低比拉太音、","notes":[]},{"n":23,"t":"基列亭、伯‧迦末、伯‧米恩、","notes":[]},{"n":24,"t":"加略、波斯拉，和摩押地遠近所有的城邑。","notes":[]},{"n":25,"t":"摩押的角砍斷了，摩押的膀臂折斷了。這是耶和華說的。」","notes":[]},{"n":26,"t":"「你們要使摩押沉醉，因她向耶和華誇大。她要在自己所吐之中打滾，又要被人嗤笑。","notes":[],"heads":["摩押要受凌辱"]},{"n":27,"t":"摩押啊，你不曾嗤笑以色列嗎？她豈是在賊中查出來的呢？你每逢提到她便搖頭。","notes":[]},{"n":28,"t":"摩押的居民哪，要離開城邑，住在山崖裏，像鴿子在深淵口上搭窩。","notes":[]},{"n":29,"t":"我們聽說摩押人驕傲，是極其驕傲；聽說他自高自傲，並且狂妄，居心自大。","notes":[]},{"n":30,"t":"耶和華說：我知道他的忿怒是虛空的；他誇大的話一無所成。","notes":[]},{"n":31,"t":"因此，我要為摩押哀號，為摩押全地呼喊；人必為吉珥‧哈列設人歎息。","notes":[]},{"n":32,"t":"西比瑪的葡萄樹啊，我為你哀哭，甚於雅謝人哀哭。你的枝子蔓延過海，直長到雅謝海。那行毀滅的已經臨到你夏天的果子和你所摘的葡萄。","notes":[]},{"n":33,"t":"肥田和摩押地的歡喜快樂都被奪去；我使酒醡的酒絕流，無人踹酒歡呼；那歡呼卻變為仇敵的吶喊。","notes":["原文是那歡呼卻不是歡呼"]},{"n":34,"t":"「希實本人發的哀聲達到以利亞利，直達到雅雜；從瑣珥達到何羅念，直到伊基拉‧施利施亞，因為寧林的水必然乾涸。」","notes":[]},{"n":35,"t":"耶和華說：「我必在摩押地使那在邱壇獻祭的，和那向他的神燒香的都斷絕了。","notes":[]},{"n":36,"t":"我心腹為摩押哀鳴如簫，我心腸為吉珥‧哈列設人也是如此，因摩押人所得的財物都滅沒了。","notes":[]},{"n":37,"t":"「各人頭上光禿，鬍鬚剪短，手有劃傷，腰束麻布。","notes":[]},{"n":38,"t":"在摩押的各房頂上和街市上處處有人哀哭；因我打碎摩押，好像打碎無人喜悅的器皿。這是耶和華說的。","notes":[]},{"n":39,"t":"摩押何等毀壞！何等哀號！何等羞愧轉背！這樣，摩押必令四圍的人嗤笑驚駭。」","notes":[]},{"n":40,"t":"耶和華如此說：仇敵必如大鷹飛起，展開翅膀，攻擊摩押。","notes":[],"heads":["摩押無路可逃"]},{"n":41,"t":"加略被攻取，保障也被佔據。到那日，摩押的勇士心中疼痛如臨產的婦人。","notes":[]},{"n":42,"t":"摩押必被毀滅，不再成國，因她向耶和華誇大。","notes":[]},{"n":43,"t":"耶和華說：摩押的居民哪，恐懼、陷坑、網羅都臨近你。","notes":[]},{"n":44,"t":"躲避恐懼的必墜入陷坑；從陷坑上來的必被網羅纏住；因我必使追討之年臨到摩押。這是耶和華說的。","notes":[]},{"n":45,"t":"躲避的人無力站在希實本的影下；因為有火從希實本發出，有火焰出於西宏的城，燒盡摩押的角和鬨嚷人的頭頂。","notes":[]},{"n":46,"t":"摩押啊，你有禍了！屬基抹的民滅亡了！因你的眾子都被擄去，你的眾女也被擄去。","notes":[]},{"n":47,"t":"耶和華說：到末後，我還要使被擄的摩押人歸回。摩押受審判的話到此為止。","notes":[]}]},"49":{"heading":"耶和華審判亞捫","verses":[{"n":1,"t":"論亞捫人。耶和華如此說：以色列沒有兒子嗎？沒有後嗣嗎？瑪勒堪為何得迦得之地為業呢？屬他的民為何住其中的城邑呢？","notes":[]},{"n":2,"t":"耶和華說：日子將到，我必使人聽見打仗的喊聲，是攻擊亞捫人拉巴的喊聲。拉巴要成為亂堆；屬她的鄉村要被火焚燒。先前得以色列地為業的，此時以色列倒要得他們的地為業。這是耶和華說的。","notes":["原文是女子"]},{"n":3,"t":"希實本哪，你要哀號，因為愛地變為荒場。拉巴的居民哪，要呼喊，以麻布束腰；要哭號，在籬笆中跑來跑去；因瑪勒堪和屬他的祭司、首領要一同被擄去。","notes":["原文是女子"]},{"n":4,"t":"背道的民哪，你們為何因有山谷，就是水流的山谷誇張呢？為何倚靠財寶說：誰能來到我們這裏呢？","notes":["原文是女子"]},{"n":5,"t":"主－萬軍之耶和華說：我要使恐嚇從四圍的人中臨到你們；你們必被趕出，各人一直前往，沒有人收聚逃民。","notes":[]},{"n":6,"t":"後來我還要使被擄的亞捫人歸回。這是耶和華說的。","notes":[]},{"n":7,"t":"論以東。萬軍之耶和華如此說：提幔中再沒有智慧嗎？明哲人不再有謀略嗎？他們的智慧盡歸無有嗎？","notes":[],"heads":["耶和華審判以東"]},{"n":8,"t":"底但的居民哪，要轉身逃跑，住在深密處；因為我向以掃追討的時候，必使災殃臨到他。","notes":[]},{"n":9,"t":"摘葡萄的若來到他那裏，豈不剩下些葡萄呢？盜賊若夜間而來，豈不毀壞直到夠了呢？","notes":[]},{"n":10,"t":"我卻使以掃赤露，顯出他的隱密處；他不能自藏。他的後裔、弟兄、鄰舍盡都滅絕；他也歸於無有。","notes":[]},{"n":11,"t":"你撇下孤兒，我必保全他們的命；你的寡婦可以倚靠我。","notes":[]},{"n":12,"t":"耶和華如此說：「原不該喝那杯的一定要喝。你能盡免刑罰嗎？你必不能免，一定要喝！」","notes":[]},{"n":13,"t":"耶和華說：「我指著自己起誓，波斯拉必令人驚駭、羞辱、咒詛，並且荒涼。她的一切城邑必變為永遠的荒場。」","notes":[]},{"n":14,"t":"我從耶和華那裏聽見信息，並有使者被差往列國去，說：你們聚集來攻擊以東，要起來爭戰。","notes":[]},{"n":15,"t":"我使你在列國中為最小，在世人中被藐視。","notes":[]},{"n":16,"t":"住在山穴中據守山頂的啊，論到你的威嚇，你因心中的狂傲自欺；你雖如大鷹高高搭窩，我卻從那裏拉下你來。這是耶和華說的。","notes":[]},{"n":17,"t":"「以東必令人驚駭；凡經過的人就受驚駭，又因她一切的災禍嗤笑。","notes":[]},{"n":18,"t":"耶和華說：必無人住在那裏，也無人在其中寄居，要像所多瑪、蛾摩拉，和鄰近的城邑傾覆的時候一樣。","notes":[]},{"n":19,"t":"仇敵必像獅子從約旦河邊的叢林上來，攻擊堅固的居所。轉眼之間，我要使以東人逃跑，離開這地。誰蒙揀選，我就派誰治理這地。誰能比我呢？誰能給我定規日期呢？有何牧人能在我面前站立得住呢？","notes":[]},{"n":20,"t":"你們要聽耶和華攻擊以東所說的謀略和他攻擊提幔居民所定的旨意。仇敵定要將他們群眾微弱的拉去，定要使他們的居所荒涼。","notes":[]},{"n":21,"t":"因他們仆倒的聲音，地就震動。人在紅海那裏必聽見呼喊的聲音。","notes":[]},{"n":22,"t":"仇敵必如大鷹飛起，展開翅膀攻擊波斯拉。到那日，以東的勇士心中疼痛如臨產的婦人。」","notes":[]},{"n":23,"t":"論大馬士革。哈馬和亞珥拔蒙羞，因他們聽見凶惡的信息就消化了。海上有憂愁，不得平靜。","notes":[],"heads":["耶和華審判大馬士革"]},{"n":24,"t":"大馬士革發軟，轉身逃跑。戰兢將她捉住；痛苦憂愁將她抓住，如產難的婦人一樣。","notes":[]},{"n":25,"t":"我所喜樂可稱讚的城，為何被撇棄了呢？","notes":[]},{"n":26,"t":"她的少年人必仆倒在街上；當那日，一切兵丁必默默無聲。這是萬軍之耶和華說的。","notes":[]},{"n":27,"t":"我必在大馬士革城中使火著起，燒滅便‧哈達的宮殿。","notes":[]},{"n":28,"t":"論巴比倫王尼布甲尼撒所攻打的基達和夏瑣的諸國。耶和華如此說：迦勒底人哪，起來上基達去，毀滅東方人。","notes":[],"heads":["審判基達和夏瑣城"]},{"n":29,"t":"他們的帳棚和羊群都要奪去，將幔子和一切器皿，並駱駝為自己掠去。人向他們喊著說：四圍都有驚嚇。","notes":[]},{"n":30,"t":"耶和華說：夏瑣的居民哪，要逃奔遠方，住在深密處；因為巴比倫王尼布甲尼撒設計謀害你們，起意攻擊你們。","notes":[]},{"n":31,"t":"耶和華說：迦勒底人哪，起來！上安逸無慮的居民那裏去；他們是無門無閂、獨自居住的。","notes":[]},{"n":32,"t":"他們的駱駝必成為掠物；他們眾多的牲畜必成為擄物。我必將剃周圍頭髮的人分散四方，使災殃從四圍臨到他們。這是耶和華說的。","notes":["原文是風"]},{"n":33,"t":"夏瑣必成為野狗的住處，永遠淒涼；必無人住在那裏，也無人在其中寄居。","notes":[]},{"n":34,"t":"猶大王西底家登基的時候，耶和華論以攔的話臨到先知耶利米說：","notes":[],"heads":["耶和華審判以攔"]},{"n":35,"t":"「萬軍之耶和華如此說：我必折斷以攔人的弓，就是他們為首的權力。","notes":[]},{"n":36,"t":"我要使四風從天的四方颳來，臨到以攔人，將他們分散四方。這被趕散的人沒有一國不到的。」","notes":["原文是風"]},{"n":37,"t":"耶和華說：「我必使以攔人在仇敵和尋索其命的人面前驚惶；我也必使災禍，就是我的烈怒臨到他們，又必使刀劍追殺他們，直到將他們滅盡。","notes":[]},{"n":38,"t":"我要在以攔設立我的寶座，從那裏除滅君王和首領。這是耶和華說的。","notes":[]},{"n":39,"t":"「到末後，我還要使被擄的以攔人歸回。這是耶和華說的。」","notes":[]}]},"50":{"heading":"巴比倫被佔領","verses":[{"n":1,"t":"耶和華藉先知耶利米論巴比倫和迦勒底人之地所說的話。","notes":[]},{"n":2,"t":"你們要在萬國中傳揚報告，豎立大旗；要報告，不可隱瞞，說：巴比倫被攻取，彼勒蒙羞，米羅達驚惶。巴比倫的神像都蒙羞；她的偶像都驚惶。","notes":[]},{"n":3,"t":"「因有一國從北方上來攻擊她，使她的地荒涼，無人居住，連人帶牲畜都逃走了。」","notes":[]},{"n":4,"t":"耶和華說：「當那日子、那時候，以色列人要和猶大人同來，隨走隨哭，尋求耶和華－他們的神。","notes":[],"heads":["以色列人還鄉"]},{"n":5,"t":"他們必訪問錫安，又面向這裏，說：『來吧，你們要與耶和華聯合為永遠不忘的約。』","notes":[]},{"n":6,"t":"「我的百姓作了迷失的羊，牧人使他們走差路，使他們轉到山上。他們從大山走到小山，竟忘了安歇之處。","notes":[]},{"n":7,"t":"凡遇見他們的，就把他們吞滅。敵人說：『我們沒有罪；因他們得罪那作公義居所的耶和華，就是他們列祖所仰望的耶和華。』","notes":[]},{"n":8,"t":"「我民哪，你們要從巴比倫中逃走，從迦勒底人之地出去，要像羊群前面走的公山羊。","notes":[]},{"n":9,"t":"因我必激動聯合的大國從北方上來攻擊巴比倫，他們要擺陣攻擊她；她必從那裏被攻取。他們的箭好像善射之勇士的箭，一枝也不徒然返回。","notes":[]},{"n":10,"t":"迦勒底必成為掠物；凡擄掠她的都必心滿意足。這是耶和華說的。」","notes":[]},{"n":11,"t":"搶奪我產業的啊，你們因歡喜快樂，且像踹穀撒歡的母牛犢，又像發嘶聲的壯馬。","notes":[],"heads":["巴比倫陷落"]},{"n":12,"t":"你們的母巴比倫就極其抱愧，生你們的必然蒙羞。她要列在諸國之末，成為曠野、旱地、沙漠。","notes":[]},{"n":13,"t":"因耶和華的忿怒，必無人居住，要全然荒涼。凡經過巴比倫的要受驚駭，又因她所遭的災殃嗤笑。","notes":[]},{"n":14,"t":"所有拉弓的，你們要在巴比倫的四圍擺陣，射箭攻擊她。不要愛惜箭枝，因她得罪了耶和華。","notes":[]},{"n":15,"t":"你們要在她四圍吶喊；她已經投降。外郭坍塌了，城牆拆毀了，因為這是耶和華報仇的事。你們要向巴比倫報仇；她怎樣待人，也要怎樣待她。","notes":[]},{"n":16,"t":"你們要將巴比倫撒種的和收割時拿鐮刀的都剪除了。他們各人因怕欺壓的刀劍，必歸回本族，逃到本土。","notes":[]},{"n":17,"t":"「以色列是打散的羊，是被獅子趕出的。首先是亞述王將他吞滅，末後是巴比倫王尼布甲尼撒將他的骨頭折斷。」","notes":[],"heads":["以色列人還鄉"]},{"n":18,"t":"所以萬軍之耶和華－以色列的神如此說：「我必罰巴比倫王和他的地，像我從前罰亞述王一樣。","notes":[]},{"n":19,"t":"我必再領以色列回他的草場，他必在迦密和巴珊吃草，又在以法蓮山上和基列境內得以飽足。」","notes":[]},{"n":20,"t":"耶和華說：「當那日子、那時候，雖尋以色列的罪孽，一無所有；雖尋猶大的罪惡，也無所見；因為我所留下的人，我必赦免。」","notes":[]},{"n":21,"t":"耶和華說：上去攻擊米拉大翁之地，又攻擊比割的居民。要追殺滅盡，照我一切所吩咐你的去行。","notes":[],"heads":["神審判巴比倫"]},{"n":22,"t":"境內有打仗和大毀滅的響聲。","notes":[]},{"n":23,"t":"全地的大錘何竟砍斷破壞？巴比倫在列國中何竟荒涼？","notes":[]},{"n":24,"t":"巴比倫哪，我為你設下網羅，你不知不覺被纏住。你被尋著，也被捉住；因為你與耶和華爭競。","notes":[]},{"n":25,"t":"耶和華已經開了武庫，拿出他惱恨的兵器；因為主－萬軍之耶和華在迦勒底人之地有當做的事。","notes":[]},{"n":26,"t":"你們要從極遠的邊界來攻擊她，開她的倉廩，將她堆如高堆，毀滅淨盡，絲毫不留。","notes":[]},{"n":27,"t":"要殺她的一切牛犢，使他們下去遭遇殺戮。他們有禍了，因為追討他們的日子已經來到。（","notes":[]},{"n":28,"t":"有從巴比倫之地逃避出來的人，在錫安揚聲報告耶和華－我們的神報仇，就是為他的殿報仇。）","notes":[]},{"n":29,"t":"「招集一切弓箭手來攻擊巴比倫。要在巴比倫四圍安營，不要容一人逃脫，照著她所做的報應她；她怎樣待人，也要怎樣待她，因為她向耶和華－以色列的聖者發了狂傲。","notes":[]},{"n":30,"t":"所以她的少年人必仆倒在街上。當那日，一切兵丁必默默無聲。這是耶和華說的。」","notes":[]},{"n":31,"t":"主－萬軍之耶和華說：你這狂傲的啊，我與你反對，因為我追討你的日子已經來到。","notes":[]},{"n":32,"t":"狂傲的必絆跌仆倒，無人扶起。我也必使火在他的城邑中著起來，將他四圍所有的盡行燒滅。","notes":[]},{"n":33,"t":"萬軍之耶和華如此說：「以色列人和猶大人一同受欺壓；凡擄掠他們的都緊緊抓住他們，不肯釋放。","notes":[]},{"n":34,"t":"他們的救贖主大有能力，萬軍之耶和華是他的名。他必伸清他們的冤，好使全地得平安，並攪擾巴比倫的居民。」","notes":[]},{"n":35,"t":"耶和華說：「有刀劍臨到迦勒底人和巴比倫的居民，並她的首領與智慧人。","notes":[]},{"n":36,"t":"有刀劍臨到矜誇的人，他們就成為愚昧；有刀劍臨到她的勇士，他們就驚惶。","notes":[]},{"n":37,"t":"有刀劍臨到她的馬匹、車輛，和其中雜族的人民；他們必像婦女一樣。有刀劍臨到她的寶物，就被搶奪。","notes":[]},{"n":38,"t":"有乾旱臨到她的眾水，就必乾涸；因為這是有雕刻偶像之地，人因偶像而顛狂。","notes":[]},{"n":39,"t":"所以曠野的走獸和豺狼必住在那裏，鴕鳥也住在其中，永無人煙，世世代代無人居住。」","notes":[]},{"n":40,"t":"耶和華說：「必無人住在那裏，也無人在其中寄居，要像我傾覆所多瑪、蛾摩拉，和鄰近的城邑一樣。","notes":[]},{"n":41,"t":"看哪，有一種民從北方而來，並有一大國和許多君王被激動，從地極來到。","notes":[]},{"n":42,"t":"他們拿弓和槍，性情殘忍，不施憐憫；他們的聲音像海浪匉訇。巴比倫城啊，他們騎馬，都擺隊伍如上戰場的人，要攻擊你。","notes":["原文是女子"]},{"n":43,"t":"巴比倫王聽見他們的風聲，手就發軟，痛苦將他抓住，疼痛彷彿產難的婦人。","notes":[]},{"n":44,"t":"「仇敵必像獅子從約旦河邊的叢林上來，攻擊堅固的居所。轉眼之間，我要使他們逃跑，離開這地。誰蒙揀選，我就派誰治理這地。誰能比我呢？誰能給我定規日期呢？有何牧人能在我面前站立得住呢？","notes":[]},{"n":45,"t":"你們要聽耶和華攻擊巴比倫所說的謀略和他攻擊迦勒底人之地所定的旨意。仇敵定要將他們群眾微弱的拉去，定要使他們的居所荒涼。","notes":[]},{"n":46,"t":"因巴比倫被取的聲音，地就震動，人在列邦都聽見呼喊的聲音。」","notes":[]}]},"51":{"heading":"再審判巴比倫","verses":[{"n":1,"t":"耶和華如此說：我必使毀滅的風颳起，攻擊巴比倫和住在立加米的人。","notes":[]},{"n":2,"t":"我要打發外邦人來到巴比倫，簸揚她，使她的地空虛。在她遭禍的日子，他們要周圍攻擊她。","notes":[]},{"n":3,"t":"拉弓的，要向拉弓的和貫甲挺身的射箭。不要憐惜她的少年人；要滅盡她的全軍。","notes":[]},{"n":4,"t":"他們必在迦勒底人之地被殺仆倒，在巴比倫的街上被刺透。","notes":[]},{"n":5,"t":"以色列和猶大雖然境內充滿違背以色列聖者的罪，卻沒有被他的神－萬軍之耶和華丟棄。","notes":[]},{"n":6,"t":"你們要從巴比倫中逃奔，各救自己的性命！不要陷在她的罪孽中一同滅亡；因為這是耶和華報仇的時候，他必向巴比倫施行報應。","notes":[]},{"n":7,"t":"巴比倫素來是耶和華手中的金杯，使天下沉醉；萬國喝了她的酒就顛狂了。","notes":[]},{"n":8,"t":"巴比倫忽然傾覆毀壞；要為她哀號；為止她的疼痛，拿乳香或者可以治好。","notes":[]},{"n":9,"t":"我們想醫治巴比倫，她卻沒有治好。離開她吧！我們各人歸回本國；因為她受的審判通於上天，達到穹蒼。","notes":[]},{"n":10,"t":"耶和華已經彰顯我們的公義。來吧！我們可以在錫安報告耶和華－我們神的作為。","notes":[]},{"n":11,"t":"你們要磨尖了箭頭，抓住盾牌。耶和華定意攻擊巴比倫，將她毀滅，所以激動了米底亞君王的心；因這是耶和華報仇，就是為自己的殿報仇。","notes":[]},{"n":12,"t":"你們要豎立大旗，攻擊巴比倫的城牆；要堅固瞭望臺，派定守望的設下埋伏；因為耶和華指著巴比倫居民所說的話、所定的意，他已經作成。","notes":[]},{"n":13,"t":"住在眾水之上多有財寶的啊，你的結局到了！你貪婪之量滿了！","notes":[]},{"n":14,"t":"萬軍之耶和華指著自己起誓說：我必使敵人充滿你，像螞蚱一樣；他們必吶喊攻擊你。","notes":[]},{"n":15,"t":"耶和華用能力創造大地，用智慧建立世界，用聰明鋪張穹蒼。","notes":[],"heads":["頌讚神的詩歌"]},{"n":16,"t":"他一發聲，空中便有多水激動；他使雲霧從地極上騰。他造電隨雨而閃，從他府庫中帶出風來。","notes":[]},{"n":17,"t":"各人都成了畜類，毫無知識。各銀匠都因他的偶像羞愧；他所鑄的偶像本是虛假的，其中並無氣息，","notes":[]},{"n":18,"t":"都是虛無的，是迷惑人的工作，到追討的時候，必被除滅。","notes":[]},{"n":19,"t":"雅各的分不像這些，因他是造作萬有的主；以色列也是他產業的支派。萬軍之耶和華是他的名。","notes":[]},{"n":20,"t":"你是我爭戰的斧子和打仗的兵器；我要用你打碎列國，用你毀滅列邦；","notes":[],"heads":["耶和華的鐵鎚"]},{"n":21,"t":"用你打碎馬和騎馬的；用你打碎戰車和坐在其上的；","notes":[]},{"n":22,"t":"用你打碎男人和女人；用你打碎老年人和少年人；用你打碎壯丁和處女；","notes":[]},{"n":23,"t":"用你打碎牧人和他的群畜；用你打碎農夫和他一對牛；用你打碎省長和副省長。","notes":[]},{"n":24,"t":"耶和華說：「我必在你們眼前報復巴比倫人和迦勒底居民在錫安所行的諸惡。」","notes":[],"heads":["懲罰巴比倫"]},{"n":25,"t":"耶和華說：你這行毀滅的山哪，就是毀滅天下的山，我與你反對。我必向你伸手，將你從山巖滾下去，使你成為燒毀的山。","notes":[]},{"n":26,"t":"人必不從你那裏取石頭為房角石，也不取石頭為根基石；你必永遠荒涼。這是耶和華說的。","notes":[]},{"n":27,"t":"要在境內豎立大旗，在各國中吹角，使列國預備攻擊巴比倫，將亞拉臘、米尼、亞實基拿各國招來攻擊她；又派軍長來攻擊她，使馬匹上來如螞蚱，","notes":[]},{"n":28,"t":"使列國和米底亞君王，與省長和副省長，並他們所管全地之人，都預備攻擊她。","notes":[]},{"n":29,"t":"地必震動而瘠苦；因耶和華向巴比倫所定的旨意成立了，使巴比倫之地荒涼，無人居住。","notes":[]},{"n":30,"t":"巴比倫的勇士止息爭戰，藏在堅壘之中。他們的勇力衰盡，好像婦女一樣。巴比倫的住處有火著起，門閂都折斷了。","notes":[]},{"n":31,"t":"跑報的要彼此相遇，送信的要互相迎接，報告巴比倫王說：城的四方被攻取了，","notes":[]},{"n":32,"t":"渡口被佔據了，葦塘被火燒了，兵丁也驚慌了。","notes":[]},{"n":33,"t":"萬軍之耶和華－以色列的神如此說：巴比倫城好像踹穀的禾場；再過片時，收割她的時候就到了。","notes":["原文是女子"]},{"n":34,"t":"以色列人說：巴比倫王尼布甲尼撒吞滅我，壓碎我，使我成為空虛的器皿。他像大魚將我吞下，用我的美物充滿他的肚腹，又將我趕出去。","notes":[]},{"n":35,"t":"錫安的居民要說：巴比倫以強暴待我，損害我的身體，願這罪歸給她。耶路撒冷人要說：願流我們血的罪歸到迦勒底的居民。","notes":[]},{"n":36,"t":"所以，耶和華如此說：我必為你伸冤，為你報仇；我必使巴比倫的海枯竭，使她的泉源乾涸。","notes":[],"heads":["耶和華要幫助以色列"]},{"n":37,"t":"巴比倫必成為亂堆，為野狗的住處，令人驚駭、嗤笑，並且無人居住。","notes":[]},{"n":38,"t":"他們要像少壯獅子咆哮，像小獅子吼叫。","notes":[]},{"n":39,"t":"他們火熱的時候，我必為他們設擺酒席，使他們沉醉，好叫他們快樂，睡了長覺，永不醒起。這是耶和華說的。","notes":[]},{"n":40,"t":"我必使他們像羊羔、像公綿羊和公山羊下到宰殺之地。","notes":[]},{"n":41,"t":"示沙克何竟被攻取？天下所稱讚的何竟被佔據？巴比倫在列國中何竟變為荒場？","notes":["就是巴比倫"],"heads":["巴比倫的命運"]},{"n":42,"t":"海水漲起，漫過巴比倫；她被許多海浪遮蓋。","notes":[]},{"n":43,"t":"她的城邑變為荒場、旱地、沙漠，無人居住，無人經過之地。","notes":[]},{"n":44,"t":"我必刑罰巴比倫的彼勒，使他吐出所吞的。萬民必不再流歸他那裏；巴比倫的城牆也必坍塌了。","notes":[]},{"n":45,"t":"我的民哪，你們要從其中出去！各人拯救自己，躲避耶和華的烈怒。","notes":[]},{"n":46,"t":"你們不要心驚膽怯，也不要因境內所聽見的風聲懼怕；因為這年有風聲傳來；那年也有風聲傳來，境內有強暴的事，官長攻擊官長。","notes":[]},{"n":47,"t":"日子將到，我必刑罰巴比倫雕刻的偶像。她全地必然抱愧；她被殺的人必在其中仆倒。","notes":[]},{"n":48,"t":"那時，天地和其中所有的，必因巴比倫歡呼，因為行毀滅的要從北方來到她那裏。這是耶和華說的。","notes":[]},{"n":49,"t":"巴比倫怎樣使以色列被殺的人仆倒，照樣她全地被殺的人也必在巴比倫仆倒。","notes":[]},{"n":50,"t":"你們躲避刀劍的要快走，不要站住！要在遠方記念耶和華，心中追想耶路撒冷。","notes":[],"heads":["給在巴比倫的以色列人的信息"]},{"n":51,"t":"我們聽見辱罵就蒙羞，滿面慚愧，因為外邦人進入耶和華殿的聖所。","notes":[]},{"n":52,"t":"耶和華說：日子將到，我必刑罰巴比倫雕刻的偶像，通國受傷的人必唉哼。","notes":[]},{"n":53,"t":"巴比倫雖升到天上，雖使她堅固的高處更堅固，還有行毀滅的從我這裏到她那裏。這是耶和華說的。","notes":[]},{"n":54,"t":"有哀號的聲音從巴比倫出來；有大毀滅的響聲從迦勒底人之地發出。","notes":[],"heads":["巴比倫滅亡"]},{"n":55,"t":"因耶和華使巴比倫變為荒場，使其中的大聲滅絕。仇敵彷彿眾水，波浪匉訇，響聲已經發出。","notes":[]},{"n":56,"t":"這是行毀滅的臨到巴比倫。巴比倫的勇士被捉住，他們的弓折斷了；因為耶和華是施行報應的神，必定施行報應。","notes":[]},{"n":57,"t":"君王－名為萬軍之耶和華的說：我必使巴比倫的首領、智慧人、省長、副省長，和勇士都沉醉，使他們睡了長覺，永不醒起。","notes":[]},{"n":58,"t":"萬軍之耶和華如此說：巴比倫寬闊的城牆必全然傾倒；她高大的城門必被火焚燒。眾民所勞碌的必致虛空；列國所勞碌的被火焚燒，他們都必困乏。","notes":[]},{"n":59,"t":"猶大王西底家在位第四年，上巴比倫去的時候，瑪西雅的孫子、尼利亞的兒子西萊雅與王同去（西萊雅是王宮的大臣），先知耶利米有話吩咐他。","notes":[],"heads":["耶利米的信息傳到巴比倫"]},{"n":60,"t":"耶利米將一切要臨到巴比倫的災禍，就是論到巴比倫的一切話，寫在書上。","notes":[]},{"n":61,"t":"耶利米對西萊雅說：「你到了巴比倫務要念這書上的話；","notes":[]},{"n":62,"t":"又說：『耶和華啊，你曾論到這地方說：要剪除，甚至連人帶牲畜沒有在這裏居住的，必永遠荒涼。』","notes":[]},{"n":63,"t":"你念完了這書，就把一塊石頭拴在書上，扔在幼發拉底河中，","notes":[]},{"n":64,"t":"說：『巴比倫因耶和華所要降與她的災禍，必如此沉下去，不再興起，人民也必困乏。』」耶利米的話到此為止。","notes":[]}]},"52":{"heading":"耶路撒冷的陷落","verses":[{"n":1,"t":"西底家登基的時候年二十一歲，在耶路撒冷作王十一年。他母親名叫哈慕她，是立拿人耶利米的女兒。","notes":[]},{"n":2,"t":"西底家行耶和華眼中看為惡的事，是照約雅敬一切所行的。","notes":[]},{"n":3,"t":"因此耶和華的怒氣在耶路撒冷和猶大發作，以致將人民從自己的面前趕出。","notes":[]},{"n":4,"t":"西底家背叛巴比倫王。他作王第九年十月初十日，巴比倫王尼布甲尼撒率領全軍來攻擊耶路撒冷，對城安營，四圍築壘攻城。","notes":[]},{"n":5,"t":"於是城被圍困直到西底家王十一年。","notes":[]},{"n":6,"t":"四月初九日，城裏有大饑荒，甚至百姓都沒有糧食。","notes":[]},{"n":7,"t":"城被攻破，一切兵丁就在夜間從靠近王園兩城中間的門，出城逃跑；迦勒底人正在四圍攻城。他們就往亞拉巴逃去。","notes":[]},{"n":8,"t":"迦勒底的軍隊追趕西底家王，在耶利哥的平原追上他。他的全軍都離開他四散了。","notes":[]},{"n":9,"t":"迦勒底人就拿住王，帶他到在哈馬地利比拉的巴比倫王那裏；巴比倫王便審判他。","notes":[]},{"n":10,"t":"巴比倫王在西底家眼前殺了他的眾子，又在利比拉殺了猶大的一切首領，","notes":[]},{"n":11,"t":"並且剜了西底家的眼睛，用銅鍊鎖著他，帶到巴比倫去，將他囚在監裏，直到他死的日子。","notes":[]},{"n":12,"t":"巴比倫王尼布甲尼撒十九年五月初十日，在巴比倫王面前侍立的護衛長尼布撒拉旦進入耶路撒冷，","notes":[],"heads":["聖殿毀滅"]},{"n":13,"t":"用火焚燒耶和華的殿和王宮，又焚燒耶路撒冷的房屋，就是各大戶家的房屋。","notes":[]},{"n":14,"t":"跟從護衛長迦勒底的全軍就拆毀耶路撒冷四圍的城牆。","notes":[]},{"n":15,"t":"那時護衛長尼布撒拉旦將民中最窮的和城裏所剩下的百姓，並已經投降巴比倫王的人，以及大眾所剩下的人，都擄去了。","notes":[]},{"n":16,"t":"但護衛長尼布撒拉旦留下些民中最窮的，使他們修理葡萄園，耕種田地。","notes":[]},{"n":17,"t":"耶和華殿的銅柱並殿內的盆座和銅海，迦勒底人都打碎了，將那銅運到巴比倫去了，","notes":[]},{"n":18,"t":"又帶去鍋、鏟子、蠟剪、盤子、調羹，並所用的一切銅器、","notes":[]},{"n":19,"t":"杯、火鼎、碗、盆、燈臺、調羹、爵，無論金的銀的，護衛長也都帶去了。","notes":[]},{"n":20,"t":"所羅門為耶和華殿所造的兩根銅柱、一個銅海，並座下的十二隻銅牛，這一切的銅多得無法可稱。","notes":[]},{"n":21,"t":"這一根柱子高十八肘，厚四指，是空的，圍十二肘。","notes":[]},{"n":22,"t":"柱上有銅頂，高五肘；銅頂的周圍有網子和石榴，都是銅的。那一根柱子照此一樣，也有石榴。","notes":[]},{"n":23,"t":"柱子四面有九十六個石榴，在網子周圍，共有一百石榴。","notes":[]},{"n":24,"t":"護衛長拿住大祭司西萊雅、副祭司西番亞，和三個把門的，","notes":[],"heads":["猶大人被擄到巴比倫"]},{"n":25,"t":"又從城中拿住一個管理兵丁的官，並在城裏所遇常見王面的七個人和檢點國民軍長的書記，以及城裏所遇見的國民六十個人。","notes":["或譯：太監"]},{"n":26,"t":"護衛長尼布撒拉旦將這些人帶到利比拉的巴比倫王那裏。","notes":[]},{"n":27,"t":"巴比倫王就把他們擊殺在哈馬地的利比拉。這樣，猶大人被擄去離開本地。","notes":[]},{"n":28,"t":"尼布甲尼撒所擄的民數記在下面：在他第七年擄去猶大人三千零二十三名；","notes":[]},{"n":29,"t":"尼布甲尼撒十八年從耶路撒冷擄去八百三十二人；","notes":[]},{"n":30,"t":"尼布甲尼撒二十三年，護衛長尼布撒拉旦擄去猶大人七百四十五名；共有四千六百人。","notes":[]},{"n":31,"t":"猶大王約雅斤被擄後三十七年，巴比倫王以未‧米羅達元年十二月二十五日，使猶大王約雅斤抬頭，提他出監，","notes":[]},{"n":32,"t":"又對他說恩言，使他的位高過與他一同在巴比倫眾王的位，","notes":[]},{"n":33,"t":"給他脫了囚服。他終身在巴比倫王面前吃飯。","notes":[]},{"n":34,"t":"巴比倫王賜他所需用的食物，日日賜他一分，終身是這樣，直到他死的日子。","notes":[]}]}},"LAM":{"1":{"heading":"耶路撒冷的憂患","verses":[{"n":1,"t":"先前滿有人民的城，現在何竟獨坐！先前在列國中為大的，現在竟如寡婦；先前在諸省中為王后的，現在成為進貢的。","notes":[]},{"n":2,"t":"她夜間痛哭，淚流滿腮；在一切所親愛的中間沒有一個安慰她的。她的朋友都以詭詐待她，成為她的仇敵。","notes":[]},{"n":3,"t":"猶大因遭遇苦難，又因多服勞苦就遷到外邦。她住在列國中，尋不著安息；追逼她的都在狹窄之地將她追上。","notes":[]},{"n":4,"t":"錫安的路徑因無人來守聖節就悲傷；她的城門淒涼；她的祭司歎息；她的處女受艱難，自己也愁苦。","notes":[]},{"n":5,"t":"她的敵人為首；她的仇敵亨通；因耶和華為她許多的罪過使她受苦；她的孩童被敵人擄去。","notes":[]},{"n":6,"t":"錫安城的威榮全都失去。她的首領像找不著草場的鹿；在追趕的人前無力行走。","notes":["原文是女子；下同"]},{"n":7,"t":"耶路撒冷在困苦窘迫之時，就追想古時一切的樂境。她百姓落在敵人手中，無人救濟；敵人看見，就因她的荒涼嗤笑。","notes":[]},{"n":8,"t":"耶路撒冷大大犯罪，所以成為不潔之物；素來尊敬她的，見她赤露就都藐視她；她自己也歎息退後。","notes":[]},{"n":9,"t":"她的污穢是在衣襟上；她不思想自己的結局，所以非常地敗落，無人安慰她。她說：耶和華啊，求你看我的苦難，因為仇敵誇大。","notes":[]},{"n":10,"t":"敵人伸手，奪取她的美物；她眼見外邦人進入她的聖所－論這外邦人，你曾吩咐不可入你的會中。","notes":[]},{"n":11,"t":"她的民都歎息，尋求食物；他們用美物換糧食，要救性命。他們說：耶和華啊，求你觀看，因為我甚是卑賤。","notes":[]},{"n":12,"t":"你們一切過路的人哪，這事你們不介意嗎？你們要觀看：有像這臨到我的痛苦沒有－就是耶和華在他發烈怒的日子使我所受的苦？","notes":[]},{"n":13,"t":"他從高天使火進入我的骨頭，剋制了我；他鋪下網羅，絆我的腳，使我轉回；他使我終日淒涼發昏。","notes":[]},{"n":14,"t":"我罪過的軛是他手所綁的，猶如軛繩縛在我頸項上；他使我的力量衰敗。主將我交在我所不能敵擋的人手中。","notes":[]},{"n":15,"t":"主輕棄我中間的一切勇士，招聚多人攻擊我，要壓碎我的少年人。主將猶大居民踹下，像在酒醡中一樣。","notes":["原文是大會"]},{"n":16,"t":"我因這些事哭泣；我眼淚汪汪；因為那當安慰我、救我性命的，離我甚遠。我的兒女孤苦，因為仇敵得了勝。","notes":[]},{"n":17,"t":"錫安舉手，無人安慰。耶和華論雅各已經出令，使四圍的人作他仇敵；耶路撒冷在他們中間像不潔之物。","notes":[]},{"n":18,"t":"耶和華是公義的！他這樣待我，是因我違背他的命令。眾民哪，請聽我的話，看我的痛苦；我的處女和少年人都被擄去。","notes":[]},{"n":19,"t":"我招呼我所親愛的，他們卻愚弄我。我的祭司和長老正尋求食物、救性命的時候，就在城中絕氣。","notes":[]},{"n":20,"t":"耶和華啊，求你觀看，因為我在急難中。我心腸擾亂；我心在我裏面翻轉，因我大大悖逆。在外，刀劍使人喪子；在家，猶如死亡。","notes":[]},{"n":21,"t":"聽見我歎息的有人；安慰我的卻無人！我的仇敵都聽見我所遭的患難；因你做這事，他們都喜樂。你必使你報告的日子來到，他們就像我一樣。","notes":[]},{"n":22,"t":"願他們的惡行都呈在你面前；你怎樣因我的一切罪過待我，求你照樣待他們；因我歎息甚多，心中發昏。","notes":[]}]},"2":{"heading":"耶和華刑罰耶路撒冷","verses":[{"n":1,"t":"主何竟發怒，使黑雲遮蔽錫安城！他將以色列的華美從天扔在地上；在他發怒的日子並不記念自己的腳凳。","notes":[]},{"n":2,"t":"主吞滅雅各一切的住處，並不顧惜。他發怒傾覆猶大民的保障，使這保障坍倒在地；他辱沒這國和其中的首領。","notes":[]},{"n":3,"t":"他發烈怒，把以色列的角全然砍斷，在仇敵面前收回右手。他像火焰四圍吞滅，將雅各燒毀。","notes":[]},{"n":4,"t":"他張弓好像仇敵；他站著舉起右手，如同敵人將悅人眼目的，盡行殺戮。在錫安百姓的帳棚上倒出他的忿怒，像火一樣。","notes":[]},{"n":5,"t":"主如仇敵吞滅以色列和錫安的一切宮殿，拆毀百姓的保障；在猶大民中加增悲傷哭號。","notes":[]},{"n":6,"t":"他強取自己的帳幕，好像是園中的窩棚，毀壞他的聚會之處。耶和華使聖節和安息日在錫安都被忘記，又在怒氣的憤恨中藐視君王和祭司。","notes":[]},{"n":7,"t":"耶和華丟棄自己的祭壇，憎惡自己的聖所，將宮殿的牆垣交付仇敵。他們在耶和華的殿中喧嚷，像在聖會之日一樣。","notes":[]},{"n":8,"t":"耶和華定意拆毀錫安的城牆；他拉了準繩，不將手收回，定要毀滅。他使外郭和城牆都悲哀，一同衰敗。","notes":[]},{"n":9,"t":"錫安的門都陷入地內；主將她的門閂毀壞，折斷。她的君王和首領落在沒有律法的列國中；她的先知不得見耶和華的異象。","notes":[]},{"n":10,"t":"錫安城的長老坐在地上默默無聲；他們揚起塵土落在頭上，腰束麻布；耶路撒冷的處女垂頭至地。","notes":[]},{"n":11,"t":"我眼中流淚，以致失明；我的心腸擾亂，肝膽塗地，都因我眾民遭毀滅，又因孩童和吃奶的在城內街上發昏。","notes":[]},{"n":12,"t":"那時，他們在城內街上發昏，好像受傷的，在母親的懷裏，將要喪命；對母親說：穀、酒在哪裏呢？","notes":[]},{"n":13,"t":"耶路撒冷的民哪，我可用甚麼向你證明呢？我可用甚麼與你相比呢？錫安的民哪，我可拿甚麼和你比較，好安慰你呢？因為你的裂口大如海，誰能醫治你呢？","notes":[]},{"n":14,"t":"你的先知為你見虛假和愚昧的異象，並沒有顯露你的罪孽，使你被擄的歸回；卻為你見虛假的默示和使你被趕出本境的緣故。","notes":[]},{"n":15,"t":"凡過路的都向你拍掌。他們向耶路撒冷城嗤笑，搖頭，說：難道人所稱為全美的，稱為全地所喜悅的，就是這城嗎？","notes":[]},{"n":16,"t":"你的仇敵都向你大大張口；他們嗤笑，又切齒說：我們吞滅她。這真是我們所盼望的日子臨到了！我們親眼看見了！","notes":[]},{"n":17,"t":"耶和華成就了他所定的，應驗了他古時所命定的。他傾覆了，並不顧惜，使你的仇敵向你誇耀；使你敵人的角也被高舉。","notes":[]},{"n":18,"t":"錫安民的心哀求主。錫安的城牆啊，願你流淚如河，晝夜不息；願你眼中的瞳人淚流不止。","notes":[]},{"n":19,"t":"夜間，每逢交更的時候要起來呼喊，在主面前傾心如水。你的孩童在各市口上受餓發昏；你要為他們的性命向主舉手禱告。","notes":[]},{"n":20,"t":"耶和華啊，求你觀看！見你向誰這樣行？婦人豈可吃自己所生育手裏所搖弄的嬰孩嗎？祭司和先知豈可在主的聖所中被殺戮嗎？","notes":[]},{"n":21,"t":"少年人和老年人都在街上躺臥；我的處女和壯丁都倒在刀下；你發怒的日子殺死他們。你殺了，並不顧惜。","notes":[]},{"n":22,"t":"你招聚四圍驚嚇我的，像在大會的日子招聚人一樣。耶和華發怒的日子，無人逃脫，無人存留。我所搖弄所養育的嬰孩，仇敵都殺淨了。","notes":[]}]},"3":{"heading":"刑罰、悔改、希望","verses":[{"n":1,"t":"我是因耶和華忿怒的杖，遭遇困苦的人。","notes":[]},{"n":2,"t":"他引導我，使我行在黑暗中，不行在光明裏。","notes":[]},{"n":3,"t":"他真是終日再三反手攻擊我。","notes":[]},{"n":4,"t":"他使我的皮肉枯乾；他折斷我的骨頭。","notes":["或譯：壓傷"]},{"n":5,"t":"他築壘攻擊我，用苦楚和艱難圍困我。","notes":["原文是苦膽"]},{"n":6,"t":"他使我住在幽暗之處，像死了許久的人一樣。","notes":[]},{"n":7,"t":"他用籬笆圍住我，使我不能出去；他使我的銅鍊沉重。","notes":[]},{"n":8,"t":"我哀號求救；他使我的禱告不得上達。","notes":[]},{"n":9,"t":"他用鑿過的石頭擋住我的道；他使我的路彎曲。","notes":[]},{"n":10,"t":"他向我如熊埋伏，如獅子在隱密處。","notes":[]},{"n":11,"t":"他使我轉離正路，將我撕碎，使我淒涼。","notes":[]},{"n":12,"t":"他張弓將我當作箭靶子。","notes":[]},{"n":13,"t":"他把箭袋中的箭射入我的肺腑。","notes":[]},{"n":14,"t":"我成了眾民的笑話；他們終日以我為歌曲。","notes":[]},{"n":15,"t":"他用苦楚充滿我，使我飽用茵蔯。","notes":[]},{"n":16,"t":"他又用沙石磣斷我的牙，用灰塵將我蒙蔽。","notes":[]},{"n":17,"t":"你使我遠離平安，我忘記好處。","notes":[]},{"n":18,"t":"我就說：我的力量衰敗；我在耶和華那裏毫無指望！","notes":[]},{"n":19,"t":"耶和華啊，求你記念我如茵蔯和苦膽的困苦窘迫。","notes":[]},{"n":20,"t":"我心想念這些，就在裏面憂悶。","notes":[]},{"n":21,"t":"我想起這事，心裏就有指望。","notes":[]},{"n":22,"t":"我們不致消滅，是出於耶和華諸般的慈愛；是因他的憐憫不致斷絕。","notes":[]},{"n":23,"t":"每早晨，這都是新的；你的誠實極其廣大！","notes":[]},{"n":24,"t":"我心裏說：耶和華是我的分，因此，我要仰望他。","notes":[]},{"n":25,"t":"凡等候耶和華，心裏尋求他的，耶和華必施恩給他。","notes":[]},{"n":26,"t":"人仰望耶和華，靜默等候他的救恩，這原是好的。","notes":[]},{"n":27,"t":"人在幼年負軛，這原是好的。","notes":[]},{"n":28,"t":"他當獨坐無言，因為這是耶和華加在他身上的。","notes":[]},{"n":29,"t":"他當口貼塵埃，或者有指望。","notes":[]},{"n":30,"t":"他當由人打他的腮頰，要滿受凌辱。","notes":[]},{"n":31,"t":"因為主必不永遠丟棄人。","notes":[]},{"n":32,"t":"主雖使人憂愁，還要照他諸般的慈愛發憐憫。","notes":[]},{"n":33,"t":"因他並不甘心使人受苦，使人憂愁。","notes":[]},{"n":34,"t":"人將世上被囚的踹在腳下，","notes":["原文是壓"]},{"n":35,"t":"或在至高者面前屈枉人，","notes":[]},{"n":36,"t":"或在人的訟事上顛倒是非，這都是主看不上的。","notes":[]},{"n":37,"t":"除非主命定，誰能說成就成呢？","notes":[]},{"n":38,"t":"禍福不都出於至高者的口嗎？","notes":[]},{"n":39,"t":"活人因自己的罪受罰，為何發怨言呢？","notes":[]},{"n":40,"t":"我們當深深考察自己的行為，再歸向耶和華。","notes":[]},{"n":41,"t":"我們當誠心向天上的神舉手禱告。","notes":[]},{"n":42,"t":"我們犯罪背逆，你並不赦免。","notes":[]},{"n":43,"t":"你自被怒氣遮蔽，追趕我們；你施行殺戮，並不顧惜。","notes":[]},{"n":44,"t":"你以黑雲遮蔽自己，以致禱告不得透入。","notes":[]},{"n":45,"t":"你使我們在萬民中成為污穢和渣滓。","notes":[]},{"n":46,"t":"我們的仇敵都向我們大大張口。","notes":[]},{"n":47,"t":"恐懼和陷坑，殘害和毀滅，都臨近我們。","notes":[]},{"n":48,"t":"因我眾民遭的毀滅，我就眼淚下流如河。","notes":[]},{"n":49,"t":"我的眼多多流淚，總不止息，","notes":[]},{"n":50,"t":"直等耶和華垂顧，從天觀看。","notes":[]},{"n":51,"t":"因我本城的眾民，我的眼，使我的心傷痛。","notes":[]},{"n":52,"t":"無故與我為仇的追逼我，像追雀鳥一樣。","notes":[]},{"n":53,"t":"他們使我的命在牢獄中斷絕，並將一塊石頭拋在我身上。","notes":[]},{"n":54,"t":"眾水流過我頭，我說：我命斷絕了！","notes":[]},{"n":55,"t":"耶和華啊，我從深牢中求告你的名。","notes":[]},{"n":56,"t":"你曾聽見我的聲音；我求你解救，你不要掩耳不聽。","notes":[]},{"n":57,"t":"我求告你的日子，你臨近我，說：不要懼怕！","notes":[]},{"n":58,"t":"主啊，你伸明了我的冤；你救贖了我的命。","notes":[]},{"n":59,"t":"耶和華啊，你見了我受的委屈；求你為我伸冤。","notes":[]},{"n":60,"t":"他們仇恨我，謀害我，你都看見了。","notes":[]},{"n":61,"t":"耶和華啊，你聽見他們辱罵我的話，知道他們向我所設的計，","notes":[]},{"n":62,"t":"並那些起來攻擊我的人口中所說的話，以及終日向我所設的計謀。","notes":[]},{"n":63,"t":"求你觀看，他們坐下，起來，都以我為歌曲。","notes":[]},{"n":64,"t":"耶和華啊，你要按著他們手所做的向他們施行報應。","notes":[]},{"n":65,"t":"你要使他們心裏剛硬，使你的咒詛臨到他們。","notes":[]},{"n":66,"t":"你要發怒追趕他們，從耶和華的天下除滅他們。","notes":[]}]},"4":{"heading":"耶路撒冷陷落之後","verses":[{"n":1,"t":"黃金何其失光！純金何其變色！聖所的石頭倒在各市口上。","notes":[]},{"n":2,"t":"錫安寶貴的眾子好比精金，現在何竟算為窯匠手所做的瓦瓶？","notes":[]},{"n":3,"t":"野狗尚且把奶乳哺其子，我民的婦人倒成為殘忍，好像曠野的鴕鳥一般。","notes":[]},{"n":4,"t":"吃奶孩子的舌頭因乾渴貼住上膛；孩童求餅，無人擘給他們。","notes":[]},{"n":5,"t":"素來吃美好食物的，現今在街上變為孤寒；素來臥朱紅褥子的，現今躺臥糞堆。","notes":[]},{"n":6,"t":"都因我眾民的罪孽比所多瑪的罪還大；所多瑪雖然無人加手於她，還是轉眼之間被傾覆。","notes":[]},{"n":7,"t":"錫安的貴冑素來比雪純淨，比奶更白；他們的身體比紅寶玉更紅，像光潤的藍寶石一樣。","notes":["或譯：珊瑚"]},{"n":8,"t":"現在他們的面貌比煤炭更黑，以致在街上無人認識；他們的皮膚緊貼骨頭，枯乾如同槁木。","notes":[]},{"n":9,"t":"餓死的不如被刀殺的，因為這是缺了田間的土產，就身體衰弱，漸漸消滅。","notes":[]},{"n":10,"t":"慈心的婦人，當我眾民被毀滅的時候，親手煮自己的兒女作為食物。","notes":[]},{"n":11,"t":"耶和華發怒成就他所定的，倒出他的烈怒；在錫安使火著起，燒毀錫安的根基。","notes":[]},{"n":12,"t":"地上的君王和世上的居民都不信敵人和仇敵能進耶路撒冷的城門。","notes":[]},{"n":13,"t":"這都因她先知的罪惡和祭司的罪孽；他們在城中流了義人的血。","notes":[]},{"n":14,"t":"他們在街上如瞎子亂走，又被血玷污，以致人不能摸他們的衣服。","notes":[]},{"n":15,"t":"人向他們喊著說：不潔淨的，躲開，躲開！不要挨近我！他們逃走飄流的時候，列國中有人說：他們不可仍在這裏寄居。","notes":[]},{"n":16,"t":"耶和華發怒，將他們分散，不再眷顧他們；人不重看祭司，也不厚待長老。","notes":[]},{"n":17,"t":"我們仰望人來幫助，以致眼目失明，還是枉然；我們所盼望的，竟盼望一個不能救人的國！","notes":[]},{"n":18,"t":"仇敵追趕我們的腳步像打獵的，以致我們不敢在自己的街上行走。我們的結局臨近；我們的日子滿足；我們的結局來到了。","notes":[]},{"n":19,"t":"追趕我們的比空中的鷹更快；他們在山上追逼我們，在曠野埋伏，等候我們。","notes":[]},{"n":20,"t":"耶和華的受膏者好比我們鼻中的氣，在他們的坑中被捉住；我們曾論到他說：我們必在他蔭下，在列國中存活。","notes":[]},{"n":21,"t":"住烏斯地的以東民哪，只管歡喜快樂；苦杯也必傳到你那裏；你必喝醉，以致露體。","notes":[]},{"n":22,"t":"錫安的民哪，你罪孽的刑罰受足了，耶和華必不使你再被擄去。以東的民哪，他必追討你的罪孽，顯露你的罪惡。","notes":[]}]},"5":{"heading":"求耶和華垂憐","verses":[{"n":1,"t":"耶和華啊，求你記念我們所遭遇的事，觀看我們所受的凌辱。","notes":[]},{"n":2,"t":"我們的產業歸與外邦人；我們的房屋歸與外路人。","notes":[]},{"n":3,"t":"我們是無父的孤兒；我們的母親好像寡婦。","notes":[]},{"n":4,"t":"我們出錢才得水喝；我們的柴是人賣給我們的。","notes":[]},{"n":5,"t":"追趕我們的，到了我們的頸項上；我們疲乏不得歇息。","notes":[]},{"n":6,"t":"我們投降埃及人和亞述人，為要得糧吃飽。","notes":[]},{"n":7,"t":"我們列祖犯罪，而今不在了；我們擔當他們的罪孽。","notes":[]},{"n":8,"t":"奴僕轄制我們，無人救我們脫離他們的手。","notes":[]},{"n":9,"t":"因為曠野的刀劍，我們冒著險才得糧食。","notes":[]},{"n":10,"t":"因飢餓燥熱，我們的皮膚就黑如爐。","notes":[]},{"n":11,"t":"敵人在錫安玷污婦人，在猶大的城邑玷污處女。","notes":[]},{"n":12,"t":"他們吊起首領的手，也不尊敬老人的面。","notes":[]},{"n":13,"t":"少年人扛磨石，孩童背木柴，都絆跌了。","notes":[]},{"n":14,"t":"老年人在城門口斷絕；少年人不再作樂。","notes":[]},{"n":15,"t":"我們心中的快樂止息，跳舞變為悲哀。","notes":[]},{"n":16,"t":"冠冕從我們的頭上落下；我們犯罪了，我們有禍了！","notes":[]},{"n":17,"t":"這些事我們心裏發昏，我們的眼睛昏花。","notes":[]},{"n":18,"t":"錫安山荒涼，野狗行在其上。","notes":["或譯：狐狸"]},{"n":19,"t":"耶和華啊，你存到永遠；你的寶座存到萬代。","notes":[]},{"n":20,"t":"你為何永遠忘記我們？為何許久離棄我們？","notes":[]},{"n":21,"t":"耶和華啊，求你使我們向你回轉，我們便得回轉。求你復新我們的日子，像古時一樣。","notes":[]},{"n":22,"t":"你竟全然棄絕我們，向我們大發烈怒？","notes":[]}]}},"EZK":{"1":{"heading":"以西結所見的第一個異象","verses":[{"n":1,"t":"當三十年四月初五日，以西結在迦巴魯河邊被擄的人中，天就開了，得見神的異象。","notes":["原文是我"],"heads":["神的寶座"]},{"n":2,"t":"正是約雅斤王被擄去第五年四月初五日，","notes":[]},{"n":3,"t":"在迦勒底人之地、迦巴魯河邊，耶和華的話特特臨到布西的兒子祭司以西結；耶和華的靈降在他身上。","notes":["原文是手"]},{"n":4,"t":"我觀看，見狂風從北方颳來，隨著有一朵包括閃爍火的大雲，周圍有光輝；從其中的火內發出好像光耀的精金；","notes":[]},{"n":5,"t":"又從其中顯出四個活物的形像來。他們的形狀是這樣：有人的形像，","notes":[]},{"n":6,"t":"各有四個臉面，四個翅膀。","notes":[]},{"n":7,"t":"他們的腿是直的，腳掌好像牛犢之蹄，都燦爛如光明的銅。","notes":[]},{"n":8,"t":"在四面的翅膀以下有人的手。這四個活物的臉和翅膀乃是這樣：","notes":[]},{"n":9,"t":"翅膀彼此相接，行走並不轉身，俱各直往前行。","notes":[]},{"n":10,"t":"至於臉的形像：前面各有人的臉，右面各有獅子的臉，左面各有牛的臉，後面各有鷹的臉。","notes":[]},{"n":11,"t":"各展開上邊的兩個翅膀相接，各以下邊的兩個翅膀遮體。","notes":[]},{"n":12,"t":"他們俱各直往前行。靈往哪裏去，他們就往那裏去，行走並不轉身。","notes":[]},{"n":13,"t":"至於四活物的形像，就如燒著火炭的形狀，又如火把的形狀。火在四活物中間上去下來，這火有光輝，從火中發出閃電。","notes":[]},{"n":14,"t":"這活物往來奔走，好像電光一閃。","notes":[]},{"n":15,"t":"我正觀看活物的時候，見活物的臉旁各有一輪在地上。","notes":[]},{"n":16,"t":"輪的形狀和顏色好像水蒼玉。四輪都是一個樣式，形狀和作法好像輪中套輪。","notes":["原文是作法"]},{"n":17,"t":"輪行走的時候，向四方都能直行，並不掉轉。","notes":[]},{"n":18,"t":"至於輪輞，高而可畏；四個輪輞周圍滿有眼睛。","notes":[]},{"n":19,"t":"活物行走，輪也在旁邊行走；活物從地上升，輪也都上升。","notes":[]},{"n":20,"t":"靈往哪裏去，活物就往那裏去；活物上升，輪也在活物旁邊上升，因為活物的靈在輪中。","notes":[]},{"n":21,"t":"那些行走，這些也行走；那些站住，這些也站住；那些從地上升，輪也在旁邊上升，因為活物的靈在輪中。","notes":[]},{"n":22,"t":"活物的頭以上有穹蒼的形像，看著像可畏的水晶，鋪張在活物的頭以上。","notes":[]},{"n":23,"t":"穹蒼以下，活物的翅膀直張，彼此相對；每活物有兩個翅膀遮體。","notes":[]},{"n":24,"t":"活物行走的時候，我聽見翅膀的響聲，像大水的聲音，像全能者的聲音，也像軍隊鬨嚷的聲音。活物站住的時候，便將翅膀垂下。","notes":[]},{"n":25,"t":"在他們頭以上的穹蒼之上有聲音。他們站住的時候，便將翅膀垂下。","notes":[]},{"n":26,"t":"在他們頭以上的穹蒼之上有寶座的形像，彷彿藍寶石；在寶座形像以上有彷彿人的形狀。","notes":[]},{"n":27,"t":"我見從他腰以上有彷彿光耀的精金，周圍都有火的形狀，又見從他腰以下有彷彿火的形狀，周圍也有光輝。","notes":[]},{"n":28,"t":"下雨的日子，雲中虹的形狀怎樣，周圍光輝的形狀也是怎樣。這就是耶和華榮耀的形像。我一看見就俯伏在地，又聽見一位說話的聲音。","notes":[]}]},"2":{"heading":"神選召以西結作先知","verses":[{"n":1,"t":"他對我說：「人子啊，你站起來，我要和你說話。」","notes":[]},{"n":2,"t":"他對我說話的時候，靈就進入我裏面，使我站起來，我便聽見那位對我說話的聲音。","notes":[]},{"n":3,"t":"他對我說：「人子啊，我差你往悖逆的國民以色列人那裏去。他們是悖逆我的，他們和他們的列祖違背我，直到今日。","notes":[]},{"n":4,"t":"這眾子面無羞恥，心裏剛硬。我差你往他們那裏去，你要對他們說：主耶和華如此說。","notes":[]},{"n":5,"t":"他們或聽，或不聽，（他們是悖逆之家），必知道在他們中間有了先知。","notes":[]},{"n":6,"t":"人子啊，雖有荊棘和蒺藜在你那裏，你又住在蠍子中間，總不要怕他們，也不要怕他們的話；他們雖是悖逆之家，還不要怕他們的話，也不要因他們的臉色驚惶。","notes":[]},{"n":7,"t":"他們或聽，或不聽，你只管將我的話告訴他們；他們是極其悖逆的。","notes":[]},{"n":8,"t":"「人子啊，要聽我對你所說的話，不要悖逆像那悖逆之家，你要開口吃我所賜給你的。」","notes":[]},{"n":9,"t":"我觀看，見有一隻手向我伸出來，手中有一書卷。","notes":[]},{"n":10,"t":"他將書卷在我面前展開，內外都寫著字，其上所寫的有哀號、歎息、悲痛的話。","notes":[]}]},"3":{"heading":"耶和華派以西結作守望者","verses":[{"n":1,"t":"他對我說：「人子啊，要吃你所得的，要吃這書卷，好去對以色列家講說。」","notes":[]},{"n":2,"t":"於是我開口，他就使我吃這書卷，","notes":[]},{"n":3,"t":"又對我說：「人子啊，要吃我所賜給你的這書卷，充滿你的肚腹。」我就吃了，口中覺得其甜如蜜。","notes":[]},{"n":4,"t":"他對我說：「人子啊，你往以色列家那裏去，將我的話對他們講說。","notes":[]},{"n":5,"t":"你奉差遣不是往那說話深奧、言語難懂的民那裏去，乃是往以色列家去；","notes":[]},{"n":6,"t":"不是往那說話深奧、言語難懂的多國去，他們的話語是你不懂得的。我若差你往他們那裏去，他們必聽從你。","notes":[]},{"n":7,"t":"以色列家卻不肯聽從你，因為他們不肯聽從我；原來以色列全家是額堅心硬的人。","notes":[]},{"n":8,"t":"看哪，我使你的臉硬過他們的臉，使你的額硬過他們的額。","notes":[]},{"n":9,"t":"我使你的額像金鋼鑽，比火石更硬。他們雖是悖逆之家，你不要怕他們，也不要因他們的臉色驚惶。」","notes":[]},{"n":10,"t":"他又對我說：「人子啊，我對你所說的一切話，要心裏領會，耳中聽聞。","notes":[]},{"n":11,"t":"你往你本國被擄的子民那裏去，他們或聽，或不聽，你要對他們講說，告訴他們這是主耶和華說的。」","notes":[]},{"n":12,"t":"那時，靈將我舉起，我就聽見在我身後有震動轟轟的聲音，說：「從耶和華的所在顯出來的榮耀是該稱頌的！」","notes":[]},{"n":13,"t":"我又聽見那活物翅膀相碰，與活物旁邊輪子旋轉震動轟轟的響聲。","notes":[]},{"n":14,"t":"於是靈將我舉起，帶我而去。我心中甚苦，靈性忿激，並且耶和華的靈在我身上大有能力。","notes":["原文是手"]},{"n":15,"t":"我就來到提勒‧亞畢，住在迦巴魯河邊被擄的人那裏，到他們所住的地方，在他們中間憂憂悶悶地坐了七日。","notes":[]},{"n":16,"t":"過了七日，耶和華的話臨到我說：","notes":[]},{"n":17,"t":"「人子啊，我立你作以色列家守望的人，所以你要聽我口中的話，替我警戒他們。","notes":[]},{"n":18,"t":"我何時指著惡人說：他必要死；你若不警戒他，也不勸戒他，使他離開惡行，拯救他的性命，這惡人必死在罪孽之中；我卻要向你討他喪命的罪。","notes":["原文是血"]},{"n":19,"t":"倘若你警戒惡人，他仍不轉離罪惡，也不離開惡行，他必死在罪孽之中，你卻救自己脫離了罪。","notes":[]},{"n":20,"t":"再者，義人何時離義而犯罪，我將絆腳石放在他面前，他就必死；因你沒有警戒他，他必死在罪中，他素來所行的義不被記念；我卻要向你討他喪命的罪。","notes":["原文是血"]},{"n":21,"t":"倘若你警戒義人，使他不犯罪，他就不犯罪；他因受警戒就必存活，你也救自己脫離了罪。」","notes":[]},{"n":22,"t":"耶和華的靈在那裏降在我身上。他對我說：「你起來往平原去，我要在那裏和你說話。」","notes":["原文是手"],"heads":["以西結暫成啞巴"]},{"n":23,"t":"於是我起來往平原去，不料，耶和華的榮耀正如我在迦巴魯河邊所見的一樣，停在那裏，我就俯伏於地。","notes":[]},{"n":24,"t":"靈就進入我裏面，使我站起來。耶和華對我說：「你進房屋去，將門關上。","notes":[]},{"n":25,"t":"人子啊，人必用繩索捆綁你，你就不能出去在他們中間來往。","notes":[]},{"n":26,"t":"我必使你的舌頭貼住上膛，以致你啞口，不能作責備他們的人；他們原是悖逆之家。","notes":[]},{"n":27,"t":"但我對你說話的時候，必使你開口，你就要對他們說：『主耶和華如此說。』聽的可以聽，不聽的任他不聽，因為他們是悖逆之家。」","notes":[]}]},"4":{"heading":"表演耶路撒冷被困","verses":[{"n":1,"t":"「人子啊，你要拿一塊磚，擺在你面前，將一座耶路撒冷城畫在其上，","notes":[]},{"n":2,"t":"又圍困這城，造臺築壘，安營攻擊，在四圍安設撞錘攻城，","notes":[]},{"n":3,"t":"又要拿個鐵鏊，放在你和城的中間，作為鐵牆。你要對面攻擊這城，使城被困；這樣，好作以色列家的預兆。","notes":[]},{"n":4,"t":"「你要向左側臥，承當以色列家的罪孽；要按你向左側臥的日數，擔當他們的罪孽。","notes":[]},{"n":5,"t":"因為我已將他們作孽的年數定為你向左側臥的日數，就是三百九十日，你要這樣擔當以色列家的罪孽。","notes":[]},{"n":6,"t":"再者，你滿了這些日子，還要向右側臥，擔當猶大家的罪孽。我給你定規側臥四十日，一日頂一年。","notes":[]},{"n":7,"t":"你要露出膀臂，面向被困的耶路撒冷，說預言攻擊這城。","notes":[]},{"n":8,"t":"我用繩索捆綁你，使你不能輾轉，直等你滿了困城的日子。","notes":[]},{"n":9,"t":"「你要取小麥、大麥、豆子、紅豆、小米、粗麥，裝在一個器皿中，用以為自己做餅；要按你側臥的三百九十日吃這餅。","notes":[]},{"n":10,"t":"你所吃的要按分兩吃，每日二十舍客勒，按時而吃。","notes":[]},{"n":11,"t":"你喝水也要按制子，每日喝一欣六分之一，按時而喝。","notes":[]},{"n":12,"t":"你吃這餅像吃大麥餅一樣，要用人糞在眾人眼前燒烤。」","notes":[]},{"n":13,"t":"耶和華說：「以色列人在我所趕他們到的各國中，也必這樣吃不潔淨的食物。」","notes":[]},{"n":14,"t":"我說：「哎！主耶和華啊，我素來未曾被玷污，從幼年到如今沒有吃過自死的，或被野獸撕裂的，那可憎的肉也未曾入我的口。」","notes":[]},{"n":15,"t":"於是他對我說：「看哪，我給你牛糞代替人糞，你要將你的餅烤在其上。」","notes":[]},{"n":16,"t":"他又對我說：「人子啊，我必在耶路撒冷折斷他們的杖，就是斷絕他們的糧。他們吃餅要按分兩，憂慮而吃；喝水也要按制子，驚惶而喝；","notes":[]},{"n":17,"t":"使他們缺糧缺水，彼此驚惶，因自己的罪孽消滅。」","notes":[]}]},"5":{"heading":"以西結剃髮","verses":[{"n":1,"t":"「人子啊，你要拿一把快刀，當作剃頭刀，用這刀剃你的頭髮和你的鬍鬚，用天平將鬚髮平分。","notes":[]},{"n":2,"t":"圍困城的日子滿了，你要將三分之一在城中用火焚燒，將三分之一在城的四圍用刀砍碎，將三分之一任風吹散；我也要拔刀追趕。","notes":[]},{"n":3,"t":"你要從其中取幾根包在衣襟裏，","notes":[]},{"n":4,"t":"再從這幾根中取些扔在火中焚燒，從裏面必有火出來燒入以色列全家。","notes":[]},{"n":5,"t":"主耶和華如此說：這就是耶路撒冷。我曾將她安置在列邦之中；列國都在她的四圍。","notes":[]},{"n":6,"t":"她行惡，違背我的典章，過於列國；干犯我的律例，過於四圍的列邦，因為她棄掉我的典章。至於我的律例，她並沒有遵行。","notes":[]},{"n":7,"t":"所以主耶和華如此說：因為你們紛爭過於四圍的列國，也不遵行我的律例，不謹守我的典章，並以遵從四圍列國的惡規尚不滿意，","notes":[]},{"n":8,"t":"所以主耶和華如此說：看哪，我與你反對，必在列國的眼前，在你中間，施行審判；","notes":[]},{"n":9,"t":"並且因你一切可憎的事，我要在你中間行我所未曾行的，以後我也不再照著行。","notes":[]},{"n":10,"t":"在你中間父親要吃兒子，兒子要吃父親。我必向你施行審判，我必將你所剩下的分散四方。」","notes":["方：原文是風"]},{"n":11,"t":"主耶和華說：「我指著我的永生起誓，因你用一切可憎的物、可厭的事玷污了我的聖所，故此，我定要使你人數減少，我眼必不顧惜你，也不可憐你。","notes":[]},{"n":12,"t":"你的民三分之一必遭瘟疫而死，在你中間必因饑荒消滅；三分之一必在你四圍倒在刀下；我必將三分之一分散四方，並要拔刀追趕他們。","notes":["方：原文是風"]},{"n":13,"t":"「我要這樣成就怒中所定的；我向他們發的忿怒止息了，自己就得著安慰。我在他們身上成就怒中所定的那時，他們就知道我－耶和華所說的是出於熱心；","notes":[]},{"n":14,"t":"並且我必使你在四圍的列國中，在經過的眾人眼前，成了荒涼和羞辱。","notes":[]},{"n":15,"t":"這樣，我必以怒氣和忿怒，並烈怒的責備，向你施行審判。那時，你就在四圍的列國中成為羞辱、譏刺、警戒、驚駭。這是我－耶和華說的。","notes":[]},{"n":16,"t":"那時，我要將滅人、使人饑荒的惡箭，就是射去滅人的，射在你們身上，並要加增你們的饑荒，斷絕你們所倚靠的糧食；","notes":[]},{"n":17,"t":"又要使饑荒和惡獸到你那裏，叫你喪子，瘟疫和流血的事也必盛行在你那裏；我也要使刀劍臨到你。這是我－耶和華說的。」","notes":[]}]},"6":{"heading":"譴責拜偶像的罪","verses":[{"n":1,"t":"耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要面向以色列的眾山說預言，","notes":[]},{"n":3,"t":"說：以色列的眾山哪，要聽主耶和華的話。主耶和華對大山、小岡、水溝、山谷如此說：我必使刀劍臨到你們，也必毀滅你們的邱壇。","notes":[]},{"n":4,"t":"你們的祭壇必然荒涼，你們的日像必被打碎。我要使你們被殺的人倒在你們的偶像面前；","notes":[]},{"n":5,"t":"我也要將以色列人的屍首放在他們的偶像面前，將你們的骸骨拋散在你們祭壇的四圍。","notes":[]},{"n":6,"t":"在你們一切的住處，城邑要變為荒場，邱壇必然淒涼，使你們的祭壇荒廢，將你們的偶像打碎。你們的日像被砍倒，你們的工作被毀滅。","notes":[]},{"n":7,"t":"被殺的人必倒在你們中間，你們就知道我是耶和華。","notes":[]},{"n":8,"t":"「你們分散在各國的時候，我必在列邦中使你們有剩下脫離刀劍的人。","notes":[]},{"n":9,"t":"那脫離刀劍的人必在所擄到的各國中記念我，為他們心中何等傷破，是因他們起淫心，遠離我，眼對偶像行邪淫。他們因行一切可憎的惡事，必厭惡自己。","notes":[]},{"n":10,"t":"他們必知道我是耶和華；我說要使這災禍臨到他們身上，並非空話。","notes":[]},{"n":11,"t":"「主耶和華如此說：你當拍手頓足，說：哀哉！以色列家行這一切可憎的惡事，他們必倒在刀劍、饑荒、瘟疫之下。","notes":[]},{"n":12,"t":"在遠處的，必遭瘟疫而死；在近處的，必倒在刀劍之下；那存留被圍困的，必因饑荒而死；我必這樣在他們身上成就我怒中所定的。","notes":[]},{"n":13,"t":"他們被殺的人倒在他們祭壇四圍的偶像中，就是各高岡、各山頂、各青翠樹下、各茂密的橡樹下，乃是他們獻馨香的祭牲給一切偶像的地方。那時，他們就知道我是耶和華。","notes":[]},{"n":14,"t":"我必伸手攻擊他們，使他們的地從曠野到第伯拉他一切住處極其荒涼，他們就知道我是耶和華。」","notes":[]}]},"7":{"heading":"以色列的終局近了","verses":[{"n":1,"t":"耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「人子啊，主耶和華對以色列地如此說：結局到了，結局到了地的四境！","notes":[]},{"n":3,"t":"現在你的結局已經臨到，我必使我的怒氣歸與你，也必按你的行為審判你，照你一切可憎的事刑罰你。","notes":[]},{"n":4,"t":"我眼必不顧惜你，也不可憐你，卻要按你所行的報應你，照你中間可憎的事刑罰你。你就知道我是耶和華。","notes":[]},{"n":5,"t":"「主耶和華如此說：有一災，獨有一災；看哪，臨近了！","notes":[]},{"n":6,"t":"結局來了，結局來了，向你興起。看哪，來到了！","notes":[]},{"n":7,"t":"境內的居民哪，所定的災臨到你，時候到了，日子近了，乃是鬨嚷並非在山上歡呼的日子。","notes":[]},{"n":8,"t":"我快要將我的忿怒傾在你身上，向你成就我怒中所定的，按你的行為審判你，照你一切可憎的事刑罰你。","notes":[]},{"n":9,"t":"我眼必不顧惜你，也不可憐你，必按你所行的報應你，照你中間可憎的事刑罰你。你就知道擊打你的是我耶和華。","notes":[]},{"n":10,"t":"「看哪，看哪，日子快到了；所定的災已經發出！杖已經開花，驕傲已經發芽。","notes":[]},{"n":11,"t":"強暴興起，成了罰惡的杖。以色列人，或是他們的群眾，或是他們的財寶，無一存留；他們中間也沒有得尊榮的。","notes":[]},{"n":12,"t":"時候到了，日子近了，買主不可歡喜，賣主不可愁煩，因為烈怒已經臨到他們眾人身上。","notes":[]},{"n":13,"t":"賣主雖然存活，卻不能歸回再得所賣的，因為這異象關乎他們眾人。誰都不得歸回，也沒有人在他的罪孽中堅立自己。」","notes":[]},{"n":14,"t":"「他們已經吹角，預備齊全，卻無一人出戰，因為我的烈怒臨到他們眾人身上。","notes":[],"heads":["懲罰以色列的罪惡"]},{"n":15,"t":"在外有刀劍；在內有瘟疫、饑荒。在田野的，必遭刀劍而死；在城中的，必有饑荒、瘟疫吞滅他。","notes":[]},{"n":16,"t":"其中所逃脫的就必逃脫，各人因自己的罪孽在山上發出悲聲，好像谷中的鴿子哀鳴。","notes":[]},{"n":17,"t":"手都發軟，膝弱如水。","notes":[]},{"n":18,"t":"要用麻布束腰，被戰兢所蓋；各人臉上羞愧，頭上光禿。","notes":[]},{"n":19,"t":"他們要將銀子拋在街上，金子看如污穢之物。當耶和華發怒的日子，他們的金銀不能救他們，不能使心裏知足，也不能使肚腹飽滿，因為這金銀作了他們罪孽的絆腳石。","notes":[]},{"n":20,"t":"論到耶和華妝飾華美的殿，他建立得威嚴，他們卻在其中製造可憎可厭的偶像，所以這殿我使他們看如污穢之物。","notes":[]},{"n":21,"t":"我必將這殿交付外邦人為掠物，交付地上的惡人為擄物；他們也必褻瀆這殿。","notes":[]},{"n":22,"t":"我必轉臉不顧以色列人，他們褻瀆我隱密之所，強盜也必進去褻瀆。","notes":[]},{"n":23,"t":"「要製造鎖鍊；因為這地遍滿流血的罪，城邑充滿強暴的事。","notes":[]},{"n":24,"t":"所以，我必使列國中最惡的人來佔據他們的房屋；我必使強暴人的驕傲止息，他們的聖所都要被褻瀆。","notes":[]},{"n":25,"t":"毀滅臨近了；他們要求平安，卻無平安可得。","notes":[]},{"n":26,"t":"災害加上災害，風聲接連風聲；他們必向先知求異象，但祭司講的律法、長老設的謀略都必斷絕。","notes":[]},{"n":27,"t":"君要悲哀，王要披淒涼為衣，國民的手都發顫。我必照他們的行為待他們，按他們應得的審判他們，他們就知道我是耶和華。」","notes":[]}]},"8":{"heading":"以西結所見的第二個異象","verses":[{"n":1,"t":"第六年六月初五日，我坐在家中；猶大的眾長老坐在我面前。在那裏主耶和華的靈降在我身上。","notes":["原文是手"],"heads":["耶路撒冷城裏的偶像崇拜"]},{"n":2,"t":"我觀看，見有形像彷彿火的形狀，從他腰以下的形狀有火，從他腰以上有光輝的形狀，彷彿光耀的精金。","notes":[]},{"n":3,"t":"他伸出彷彿一隻手的樣式，抓住我的一綹頭髮，靈就將我舉到天地中間，在神的異象中，帶我到耶路撒冷朝北的內院門口，在那裏有觸動主怒偶像的坐位，就是惹動忌邪的。","notes":[]},{"n":4,"t":"誰知，在那裏有以色列神的榮耀，形狀與我在平原所見的一樣。","notes":[]},{"n":5,"t":"神對我說：「人子啊，你舉目向北觀看。」我就舉目向北觀看，見祭壇門的北邊，在門口有這惹忌邪的偶像；","notes":[]},{"n":6,"t":"又對我說：「人子啊，以色列家所行的，就是在此行這大可憎的事，使我遠離我的聖所，你看見了嗎？你還要看見另有大可憎的事。」","notes":[]},{"n":7,"t":"他領我到院門口。我觀看，見牆上有個窟窿。","notes":[]},{"n":8,"t":"他對我說：「人子啊，你要挖牆。」我一挖牆，見有一門。","notes":[]},{"n":9,"t":"他說：「你進去，看他們在這裏所行可憎的惡事。」","notes":[]},{"n":10,"t":"我進去一看，誰知，在四面牆上畫著各樣爬物和可憎的走獸，並以色列家一切的偶像。","notes":[]},{"n":11,"t":"在這些像前有以色列家的七十個長老站立，沙番的兒子雅撒尼亞也站在其中。各人手拿香爐，煙雲的香氣上騰。","notes":[]},{"n":12,"t":"他對我說：「人子啊，以色列家的長老暗中在各人畫像屋裏所行的，你看見了嗎？他們常說：『耶和華看不見我們；耶和華已經離棄這地。』」","notes":[]},{"n":13,"t":"他又說：「你還要看見他們另外行大可憎的事。」","notes":[]},{"n":14,"t":"他領我到耶和華殿外院朝北的門口。誰知，在那裏有婦女坐著，為搭模斯哭泣。","notes":[]},{"n":15,"t":"他對我說：「人子啊，你看見了嗎？你還要看見比這更可憎的事。」","notes":[]},{"n":16,"t":"他又領我到耶和華殿的內院。誰知，在耶和華的殿門口、廊子和祭壇中間，約有二十五個人背向耶和華的殿，面向東方拜日頭。","notes":[]},{"n":17,"t":"他對我說：「人子啊，你看見了嗎？猶大家在此行這可憎的事還算為小嗎？他們在這地遍行強暴，再三惹我發怒，他們手拿枝條舉向鼻前。","notes":[]},{"n":18,"t":"因此，我也要以忿怒行事，我眼必不顧惜，也不可憐他們；他們雖向我耳中大聲呼求，我還是不聽。」","notes":[]}]},"9":{"heading":"耶路撒冷受懲罰","verses":[{"n":1,"t":"他向我耳中大聲喊叫說：「要使那監管這城的人手中各拿滅命的兵器前來。」","notes":[]},{"n":2,"t":"忽然有六個人從朝北的上門而來，各人手拿殺人的兵器；內中有一人身穿細麻衣，腰間帶著墨盒子。他們進來，站在銅祭壇旁。","notes":[]},{"n":3,"t":"以色列神的榮耀本在基路伯上，現今從那裏升到殿的門檻。神將那身穿細麻衣、腰間帶著墨盒子的人召來。","notes":[]},{"n":4,"t":"耶和華對他說：「你去走遍耶路撒冷全城，那些因城中所行可憎之事歎息哀哭的人，畫記號在額上。」","notes":[]},{"n":5,"t":"我耳中聽見他對其餘的人說：「要跟隨他走遍全城，以行擊殺。你們的眼不要顧惜，也不要可憐他們。","notes":[]},{"n":6,"t":"要將年老的、年少的，並處女、嬰孩，和婦女，從聖所起全都殺盡，只是凡有記號的人不要挨近他。」於是他們從殿前的長老殺起。","notes":[]},{"n":7,"t":"他對他們說：「要污穢這殿，使院中充滿被殺的人。你們出去吧！」他們就出去，在城中擊殺。","notes":[]},{"n":8,"t":"他們擊殺的時候，我被留下，我就俯伏在地，說：「哎！主耶和華啊，你將忿怒傾在耶路撒冷，豈要將以色列所剩下的人都滅絕嗎？」","notes":[]},{"n":9,"t":"他對我說：「以色列家和猶大家的罪孽極其重大。遍地有流血的事，滿城有冤屈，因為他們說：『耶和華已經離棄這地，他看不見我們。』","notes":[]},{"n":10,"t":"故此，我眼必不顧惜，也不可憐他們，要照他們所行的報應在他們頭上。」","notes":[]},{"n":11,"t":"那穿細麻衣、腰間帶著墨盒子的人將這事回覆說：「我已經照你所吩咐的行了。」","notes":[]}]},"10":{"heading":"耶和華的榮耀離開聖城","verses":[{"n":1,"t":"我觀看，見基路伯頭上的穹蒼之中，顯出藍寶石的形狀，彷彿寶座的形像。","notes":[]},{"n":2,"t":"主對那穿細麻衣的人說：「你進去，在旋轉的輪內基路伯以下，從基路伯中間將火炭取滿兩手，撒在城上。」我就見他進去。","notes":[]},{"n":3,"t":"那人進去的時候，基路伯站在殿的右邊，雲彩充滿了內院。","notes":[]},{"n":4,"t":"耶和華的榮耀從基路伯那裏上升，停在門檻以上；殿內滿了雲彩，院宇也被耶和華榮耀的光輝充滿。","notes":[]},{"n":5,"t":"基路伯翅膀的響聲聽到外院，好像全能神說話的聲音。","notes":[]},{"n":6,"t":"他吩咐那穿細麻衣的人說：「要從旋轉的輪內基路伯中間取火。」那人就進去站在一個輪子旁邊。","notes":[]},{"n":7,"t":"有一個基路伯從基路伯中伸手到基路伯中間的火那裏，取些放在那穿細麻衣的人兩手中，那人就拿出去了。","notes":[]},{"n":8,"t":"在基路伯翅膀之下，顯出有人手的樣式。","notes":[]},{"n":9,"t":"我又觀看，見基路伯旁邊有四個輪子。這基路伯旁有一個輪子，那基路伯旁有一個輪子，每基路伯都是如此；輪子的顏色彷彿水蒼玉。","notes":["原文是形狀"]},{"n":10,"t":"至於四輪的形狀，都是一個樣式，彷彿輪中套輪。","notes":[]},{"n":11,"t":"輪行走的時候，向四方都能直行，並不掉轉。頭向何方，他們也隨向何方，行走的時候並不掉轉。","notes":[]},{"n":12,"t":"他們全身，連背帶手和翅膀，並輪周圍都滿了眼睛。這四個基路伯的輪子都是如此。","notes":[]},{"n":13,"t":"至於這些輪子，我耳中聽見說是旋轉的。","notes":[]},{"n":14,"t":"基路伯各有四臉：第一是基路伯的臉，第二是人的臉，第三是獅子的臉，第四是鷹的臉。","notes":[]},{"n":15,"t":"基路伯升上去了；這是我在迦巴魯河邊所見的活物。","notes":[]},{"n":16,"t":"基路伯行走，輪也在旁邊行走。基路伯展開翅膀，離地上升，輪也不轉離他們旁邊。","notes":[]},{"n":17,"t":"那些站住，這些也站住；那些上升，這些也一同上升，因為活物的靈在輪中。","notes":[]},{"n":18,"t":"耶和華的榮耀從殿的門檻那裏出去，停在基路伯以上。","notes":[]},{"n":19,"t":"基路伯出去的時候，就展開翅膀，在我眼前離地上升。輪也在他們的旁邊，都停在耶和華殿的東門口。在他們以上有以色列神的榮耀。","notes":[]},{"n":20,"t":"這是我在迦巴魯河邊所見、以色列神榮耀以下的活物，我就知道他們是基路伯。","notes":[]},{"n":21,"t":"各有四個臉面，四個翅膀，翅膀以下有人手的樣式。","notes":[]},{"n":22,"t":"至於他們臉的模樣，並身體的形像，是我從前在迦巴魯河邊所看見的。他們俱各直往前行。","notes":[]}]},"11":{"heading":"耶路撒冷被判罪","verses":[{"n":1,"t":"靈將我舉起，帶到耶和華殿向東的東門。誰知，在門口有二十五個人，我見其中有民間的首領押朔的兒子雅撒尼亞和比拿雅的兒子毗拉提。","notes":[]},{"n":2,"t":"耶和華對我說：「人子啊，這就是圖謀罪孽的人，在這城中給人設惡謀。","notes":[]},{"n":3,"t":"他們說：『蓋房屋的時候尚未臨近；這城是鍋，我們是肉。』","notes":[]},{"n":4,"t":"人子啊，因此你當說預言，說預言攻擊他們。」","notes":[]},{"n":5,"t":"耶和華的靈降在我身上，對我說：「你當說，耶和華如此說：以色列家啊，你們口中所說的，心裏所想的，我都知道。","notes":[]},{"n":6,"t":"你們在這城中殺人增多，使被殺的人充滿街道。","notes":[]},{"n":7,"t":"所以主耶和華如此說：你們殺在城中的人就是肉，這城就是鍋；你們卻要從其中被帶出去。","notes":[]},{"n":8,"t":"你們怕刀劍，我必使刀劍臨到你們。這是主耶和華說的。","notes":[]},{"n":9,"t":"我必從這城中帶出你們去，交在外邦人的手中，且要在你們中間施行審判。","notes":[]},{"n":10,"t":"你們必倒在刀下；我必在以色列的境界審判你們，你們就知道我是耶和華。","notes":[]},{"n":11,"t":"這城必不作你們的鍋，你們也不作其中的肉。我必在以色列的境界審判你們，","notes":[]},{"n":12,"t":"你們就知道我是耶和華；因為你們沒有遵行我的律例，也沒有順從我的典章，卻隨從你們四圍列國的惡規。」","notes":[]},{"n":13,"t":"我正說預言的時候，比拿雅的兒子毗拉提死了。於是我俯伏在地，大聲呼叫說：「哎！主耶和華啊，你要將以色列剩下的人滅絕淨盡嗎？」","notes":[]},{"n":14,"t":"耶和華的話臨到我說：","notes":[],"heads":["神對流亡者的應許"]},{"n":15,"t":"「人子啊，耶路撒冷的居民對你的弟兄、你的本族、你的親屬、以色列全家，就是對大眾說：『你們遠離耶和華吧！這地是賜給我們為業的。』","notes":[]},{"n":16,"t":"所以你當說：『耶和華如此說：我雖將以色列全家遠遠遷移到列國中，將他們分散在列邦內，我還要在他們所到的列邦，暫作他們的聖所。』","notes":[]},{"n":17,"t":"你當說：『主耶和華如此說：我必從萬民中招聚你們，從分散的列國內聚集你們，又要將以色列地賜給你們。』","notes":[]},{"n":18,"t":"他們必到那裏，也必從其中除掉一切可憎可厭的物。","notes":[]},{"n":19,"t":"我要使他們有合一的心，也要將新靈放在他們裏面，又從他們肉體中除掉石心，賜給他們肉心，","notes":[]},{"n":20,"t":"使他們順從我的律例，謹守遵行我的典章。他們要作我的子民，我要作他們的神。","notes":[]},{"n":21,"t":"至於那些心中隨從可憎可厭之物的，我必照他們所行的報應在他們頭上。這是主耶和華說的。」","notes":[]},{"n":22,"t":"於是，基路伯展開翅膀，輪子都在他們旁邊；在他們以上有以色列神的榮耀。","notes":[],"heads":["神的榮耀離開耶路撒冷"]},{"n":23,"t":"耶和華的榮耀從城中上升，停在城東的那座山上。","notes":[]},{"n":24,"t":"靈將我舉起，在異象中藉著神的靈將我帶進迦勒底地，到被擄的人那裏；我所見的異象就離我上升去了。","notes":[]},{"n":25,"t":"我便將耶和華所指示我的一切事都說給被擄的人聽。","notes":[]}]},"12":{"heading":"先知扮演難民","verses":[{"n":1,"t":"耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你住在悖逆的家中。他們有眼睛看不見，有耳朵聽不見，因為他們是悖逆之家。","notes":[]},{"n":3,"t":"所以人子啊，你要預備擄去使用的物件，在白日當他們眼前從你所住的地方移到別處去；他們雖是悖逆之家，或者可以揣摩思想。","notes":[]},{"n":4,"t":"你要在白日當他們眼前帶出你的物件去，好像預備擄去使用的物件。到了晚上，你要在他們眼前親自出去，像被擄的人出去一樣。","notes":[]},{"n":5,"t":"你要在他們眼前挖通了牆，從其中將物件帶出去。","notes":[]},{"n":6,"t":"到天黑時，你要當他們眼前搭在肩頭上帶出去，並要蒙住臉看不見地，因為我立你作以色列家的預兆。」","notes":[]},{"n":7,"t":"我就照著所吩咐的去行，白日帶出我的物件，好像預備擄去使用的物件。到了晚上，我用手挖通了牆。天黑的時候，就當他們眼前搭在肩頭上帶出去。","notes":[]},{"n":8,"t":"次日早晨，耶和華的話臨到我說：","notes":[]},{"n":9,"t":"「人子啊，以色列家，就是那悖逆之家，豈不是問你說：『你做甚麼呢？』","notes":[]},{"n":10,"t":"你要對他們說：『主耶和華如此說：這是關乎耶路撒冷的君王和他周圍以色列全家的預表。』","notes":["原文是擔子"]},{"n":11,"t":"你要說：『我作你們的預兆：我怎樣行，他們所遭遇的也必怎樣，他們必被擄去。』","notes":[]},{"n":12,"t":"他們中間的君王也必在天黑的時候將物件搭在肩頭上帶出去。他們要挖通了牆，從其中帶出去。他必蒙住臉，眼看不見地。","notes":[]},{"n":13,"t":"我必將我的網撒在他身上，他必在我的網羅中纏住。我必帶他到迦勒底人之地的巴比倫；他雖死在那裏，卻看不見那地。","notes":[]},{"n":14,"t":"周圍一切幫助他的和他所有的軍隊，我必分散四方，也要拔刀追趕他們。","notes":["方：原文是風"]},{"n":15,"t":"我將他們四散在列國、分散在列邦的時候，他們就知道我是耶和華。","notes":[]},{"n":16,"t":"我卻要留下他們幾個人得免刀劍、饑荒、瘟疫，使他們在所到的各國中述說他們一切可憎的事，人就知道我是耶和華。」","notes":[]},{"n":17,"t":"耶和華的話又臨到我說：","notes":[],"heads":["憂慮驚惶的預兆"]},{"n":18,"t":"「人子啊，你吃飯必膽戰，喝水必惶惶憂慮。","notes":[]},{"n":19,"t":"你要對這地的百姓說：主耶和華論耶路撒冷和以色列地的居民如此說，他們吃飯必憂慮，喝水必驚惶。因其中居住的眾人所行強暴的事，這地必然荒廢，一無所存。","notes":[]},{"n":20,"t":"有居民的城邑必變為荒場，地也必變為荒廢；你們就知道我是耶和華。」","notes":[]},{"n":21,"t":"耶和華的話臨到我說：","notes":[],"heads":["平凡的俗語和非凡的信息"]},{"n":22,"t":"「人子啊，在你們以色列地怎麼有這俗語，說『日子遲延，一切異象都落了空』呢？","notes":[]},{"n":23,"t":"你要告訴他們說：『主耶和華如此說：我必使這俗語止息，以色列中不再用這俗語。』你卻要對他們說：『日子臨近，一切的異象必都應驗。』","notes":[]},{"n":24,"t":"從此，在以色列家中必不再有虛假的異象和奉承的占卜。","notes":[]},{"n":25,"t":"我－耶和華說話，所說的必定成就，不再耽延。你們這悖逆之家，我所說的話必趁你們在世的日子成就。這是主耶和華說的。」","notes":[]},{"n":26,"t":"耶和華的話又臨到我說：","notes":[]},{"n":27,"t":"「人子啊，以色列家的人說：『他所見的異象是關乎後來許多的日子，所說的預言是指著極遠的時候。』","notes":[]},{"n":28,"t":"所以你要對他們說：『主耶和華如此說：我的話沒有一句再耽延的，我所說的必定成就。這是主耶和華說的。』」","notes":[]}]},"13":{"heading":"斥責假先知","verses":[{"n":1,"t":"耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要說預言攻擊以色列中說預言的先知，對那些本己心發預言的說：『你們當聽耶和華的話。』」","notes":[]},{"n":3,"t":"主耶和華如此說：「愚頑的先知有禍了，他們隨從自己的心意，卻一無所見。","notes":[]},{"n":4,"t":"以色列啊，你的先知好像荒場中的狐狸，","notes":[]},{"n":5,"t":"沒有上去堵擋破口，也沒有為以色列家重修牆垣，使他們當耶和華的日子在陣上站立得住。","notes":[]},{"n":6,"t":"這些人所見的是虛假，是謊詐的占卜。他們說是耶和華說的，其實耶和華並沒有差遣他們，他們倒使人指望那話必然立定。","notes":[]},{"n":7,"t":"你們豈不是見了虛假的異象嗎？豈不是說了謊詐的占卜嗎？你們說，這是耶和華說的，其實我沒有說。」","notes":[]},{"n":8,"t":"所以主耶和華如此說：「因你們說的是虛假，見的是謊詐，我就與你們反對。這是主耶和華說的。","notes":[]},{"n":9,"t":"我的手必攻擊那見虛假異象、用謊詐占卜的先知，他們必不列在我百姓的會中，不錄在以色列家的冊上，也不進入以色列地；你們就知道我是主耶和華。","notes":[]},{"n":10,"t":"因為他們誘惑我的百姓，說：『平安！』其實沒有平安，就像有人立起牆壁，他們倒用未泡透的灰抹上。","notes":[]},{"n":11,"t":"所以你要對那些抹上未泡透灰的人說：『牆要倒塌，必有暴雨漫過。大冰雹啊，你們要降下，狂風也要吹裂這牆。』","notes":[]},{"n":12,"t":"這牆倒塌之後，人豈不問你們說：『你們抹上未泡透的灰在哪裏呢？』」","notes":[]},{"n":13,"t":"所以主耶和華如此說：「我要發怒，使狂風吹裂這牆，在怒中使暴雨漫過，又發怒降下大冰雹，毀滅這牆。","notes":[]},{"n":14,"t":"我要這樣拆毀你們那未泡透灰所抹的牆，拆平到地，以致根基露出，牆必倒塌，你們也必在其中滅亡；你們就知道我是耶和華。","notes":[]},{"n":15,"t":"我要這樣向牆和用未泡透灰抹牆的人成就我怒中所定的，並要對你們說：『牆和抹牆的人都沒有了。』","notes":[]},{"n":16,"t":"這抹牆的就是以色列的先知，他們指著耶路撒冷說預言，為這城見了平安的異象，其實沒有平安。這是主耶和華說的。」","notes":[]},{"n":17,"t":"「人子啊，你要面向本民中、從己心發預言的女子說預言，攻擊她們，","notes":[],"heads":["斥責假的女先知"]},{"n":18,"t":"說主耶和華如此說：『這些婦女有禍了！她們為眾人的膀臂縫靠枕，給高矮之人做下垂的頭巾，為要獵取人的性命。難道你們要獵取我百姓的性命，為利己將人救活嗎？","notes":[]},{"n":19,"t":"你們為兩把大麥，為幾塊餅，在我民中褻瀆我，對肯聽謊言的民說謊，殺死不該死的人，救活不該活的人。』」","notes":[]},{"n":20,"t":"所以主耶和華如此說：「看哪，我與你們的靠枕反對，就是你們用以獵取人、使人的性命如鳥飛的。我要將靠枕從你們的膀臂上扯去，釋放你們獵取如鳥飛的人。","notes":[]},{"n":21,"t":"我也必撕裂你們下垂的頭巾，救我百姓脫離你們的手，不再被獵取，落在你們手中。你們就知道我是耶和華。","notes":[]},{"n":22,"t":"我不使義人傷心，你們卻以謊話使他傷心，又堅固惡人的手，使他不回頭離開惡道得以救活。","notes":[]},{"n":23,"t":"你們就不再見虛假的異象，也不再行占卜的事；我必救我的百姓脫離你們的手；你們就知道我是耶和華。」","notes":[]}]},"14":{"heading":"神斥責拜偶像的罪","verses":[{"n":1,"t":"有幾個以色列長老到我這裏來，坐在我面前。","notes":[]},{"n":2,"t":"耶和華的話就臨到我說：","notes":[]},{"n":3,"t":"「人子啊，這些人已將他們的假神接到心裏，把陷於罪的絆腳石放在面前，我豈能絲毫被他們求問嗎？","notes":[]},{"n":4,"t":"所以你要告訴他們：『主耶和華如此說：以色列家的人中，凡將他的假神接到心裏，把陷於罪的絆腳石放在面前，又就了先知來的，我－耶和華在他所求的事上，必按他眾多的假神回答他，","notes":["或譯：必按他拜許多假神的罪報應他"]},{"n":5,"t":"好在以色列家的心事上捉住他們，因為他們都藉著假神與我生疏。』","notes":[]},{"n":6,"t":"「所以你要告訴以色列家說：『主耶和華如此說：回頭吧！離開你們的偶像，轉臉莫從你們一切可憎的事。』","notes":[]},{"n":7,"t":"因為以色列家的人，或在以色列中寄居的外人，凡與我隔絕，將他的假神接到心裏，把陷於罪的絆腳石放在面前，又就了先知來要為自己的事求問我的，我－耶和華必親自回答他。","notes":[]},{"n":8,"t":"我必向那人變臉，使他作了警戒，笑談，令人驚駭，並且我要將他從我民中剪除；你們就知道我是耶和華。","notes":[]},{"n":9,"t":"先知若被迷惑說一句預言，是我－耶和華任那先知受迷惑，我也必向他伸手，將他從我民以色列中除滅。","notes":[]},{"n":10,"t":"他們必擔當自己的罪孽。先知的罪孽和求問之人的罪孽都是一樣，","notes":[]},{"n":11,"t":"好使以色列家不再走迷離開我，不再因各樣的罪過玷污自己，只要作我的子民，我作他們的神。這是主耶和華說的。」","notes":[]},{"n":12,"t":"耶和華的話臨到我說：","notes":[],"heads":["挪亞、但以理、約伯"]},{"n":13,"t":"「人子啊，若有一國犯罪干犯我，我也向他伸手折斷他們的杖，就是斷絕他們的糧，使饑荒臨到那地，將人與牲畜從其中剪除；","notes":[]},{"n":14,"t":"其中雖有挪亞、但以理、約伯這三人，他們只能因他們的義救自己的性命。這是主耶和華說的。","notes":[]},{"n":15,"t":"我若使惡獸經過糟踐那地，使地荒涼，以致因這些獸，人都不得經過；","notes":[]},{"n":16,"t":"雖有這三人在其中，主耶和華說：我指著我的永生起誓，他們連兒帶女都不能得救，只能自己得救，那地仍然荒涼。","notes":[]},{"n":17,"t":"或者我使刀劍臨到那地，說：刀劍哪，要經過那地，以致我將人與牲畜從其中剪除；","notes":[]},{"n":18,"t":"雖有這三人在其中，主耶和華說：我指著我的永生起誓，他們連兒帶女都不能得救，只能自己得救。","notes":[]},{"n":19,"t":"或者我叫瘟疫流行那地，使我滅命的忿怒傾在其上，好將人與牲畜從其中剪除；","notes":["原文是帶血"]},{"n":20,"t":"雖有挪亞、但以理、約伯在其中，主耶和華說：我指著我的永生起誓，他們連兒帶女都不能救，只能因他們的義救自己的性命。」","notes":[]},{"n":21,"t":"主耶和華如此說：「我將這四樣大災－就是刀劍、饑荒、惡獸、瘟疫降在耶路撒冷，將人與牲畜從其中剪除，豈不更重嗎？","notes":[]},{"n":22,"t":"然而其中必有剩下的人，他們連兒帶女必帶到你們這裏來，你們看見他們所行所為的，要因我降給耶路撒冷的一切災禍，便得了安慰。","notes":[]},{"n":23,"t":"你們看見他們所行所為的，得了安慰，就知道我在耶路撒冷中所行的並非無故。這是主耶和華說的。」","notes":[]}]},"15":{"heading":"葡萄樹的比喻","verses":[{"n":1,"t":"耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，葡萄樹比別樣樹有甚麼強處？葡萄枝比眾樹枝有甚麼好處？","notes":[]},{"n":3,"t":"其上可以取木料做甚麼工用，可以取來做釘子掛甚麼器皿嗎？","notes":[]},{"n":4,"t":"看哪，已經拋在火中當作柴燒，火既燒了兩頭，中間也被燒了，還有益於工用嗎？","notes":[]},{"n":5,"t":"完全的時候尚且不合乎甚麼工用，何況被火燒壞，還能合乎甚麼工用嗎？」","notes":[]},{"n":6,"t":"所以，主耶和華如此說：「眾樹以內的葡萄樹，我怎樣使它在火中當柴，也必照樣待耶路撒冷的居民。","notes":[]},{"n":7,"t":"我必向他們變臉；他們雖從火中出來，火卻要燒滅他們。我向他們變臉的時候，你們就知道我是耶和華。","notes":[]},{"n":8,"t":"我必使地土荒涼，因為他們行事干犯我。這是主耶和華說的。」","notes":[]}]},"16":{"heading":"不忠實的耶路撒冷","verses":[{"n":1,"t":"耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要使耶路撒冷知道她那些可憎的事，","notes":[]},{"n":3,"t":"說主耶和華對耶路撒冷如此說：你根本，你出世，是在迦南地；你父親是亞摩利人，你母親是赫人。","notes":[]},{"n":4,"t":"論到你出世的景況，在你初生的日子沒有為你斷臍帶，也沒有用水洗你，使你潔淨，絲毫沒有撒鹽在你身上，也沒有用布裹你。","notes":[]},{"n":5,"t":"誰的眼也不可憐你，為你做一件這樣的事憐恤你；但你初生的日子扔在田野，是因你被厭惡。","notes":[]},{"n":6,"t":"「我從你旁邊經過，見你滾在血中，就對你說：你雖在血中，仍可存活；你雖在血中，仍可存活。","notes":[]},{"n":7,"t":"我使你生長好像田間所長的，你就漸漸長大，以致極其俊美，兩乳成形，頭髮長成，你卻仍然赤身露體。","notes":[]},{"n":8,"t":"「我從你旁邊經過，看見你的時候正動愛情，便用衣襟搭在你身上，遮蓋你的赤體；又向你起誓，與你結盟，你就歸於我。這是主耶和華說的。","notes":[]},{"n":9,"t":"那時我用水洗你，洗淨你身上的血，又用油抹你。","notes":[]},{"n":10,"t":"我也使你身穿繡花衣服，腳穿海狗皮鞋，並用細麻布給你束腰，用絲綢為衣披在你身上，","notes":[]},{"n":11,"t":"又用妝飾打扮你，將鐲子戴在你手上，將金鍊戴在你項上。","notes":[]},{"n":12,"t":"我也將環子戴在你鼻子上，將耳環戴在你耳朵上，將華冠戴在你頭上。","notes":[]},{"n":13,"t":"這樣，你就有金銀的妝飾，穿的是細麻衣和絲綢，並繡花衣；吃的是細麵、蜂蜜，並油。你也極其美貌，發達到王后的尊榮。","notes":[]},{"n":14,"t":"你美貌的名聲傳在列邦中，你十分美貌，是因我加在你身上的威榮。這是主耶和華說的。","notes":[]},{"n":15,"t":"「只是你仗著自己的美貌，又因你的名聲就行邪淫。你縱情淫亂，使過路的任意而行。","notes":[]},{"n":16,"t":"你用衣服為自己在高處結彩，在其上行邪淫。這樣的事將來必沒有，也必不再行了。","notes":[]},{"n":17,"t":"你又將我所給你那華美的金銀、寶器為自己製造人像，與他行邪淫；","notes":[]},{"n":18,"t":"又用你的繡花衣服給他披上，並將我的膏油和香料擺在他跟前；","notes":[]},{"n":19,"t":"又將我賜給你的食物，就是我賜給你吃的細麵、油，和蜂蜜，都擺在他跟前為馨香的供物。這是主耶和華說的。","notes":[]},{"n":20,"t":"並且你將給我所生的兒女焚獻給他。","notes":[]},{"n":21,"t":"你行淫亂豈是小事，竟將我的兒女殺了，使他們經火歸與他嗎？","notes":[]},{"n":22,"t":"你行這一切可憎和淫亂的事，並未追念你幼年赤身露體滾在血中的日子。」","notes":[]},{"n":23,"t":"「你行這一切惡事之後（主耶和華說：你有禍了！有禍了！）","notes":[],"heads":["耶路撒冷像淫婦"]},{"n":24,"t":"又為自己建造圓頂花樓，在各街上做了高臺。","notes":[]},{"n":25,"t":"你在一切市口上建造高臺，使你的美貌變為可憎的，又與一切過路的多行淫亂。","notes":[]},{"n":26,"t":"你也和你鄰邦放縱情慾的埃及人行淫，加增你的淫亂，惹我發怒。","notes":[]},{"n":27,"t":"因此我伸手攻擊你，減少你應用的糧食，又將你交給恨你的非利士眾女，使她們任意待你。她們見你的淫行，為你羞恥。","notes":["眾女是城邑的意思；本章下同"]},{"n":28,"t":"你因貪色無厭，又與亞述人行淫，與他們行淫之後，仍不滿意，","notes":[]},{"n":29,"t":"並且多行淫亂，直到那貿易之地，就是迦勒底，你仍不滿意。","notes":[]},{"n":30,"t":"「主耶和華說：你行這一切事，都是不知羞恥妓女所行的，可見你的心是何等懦弱！","notes":[]},{"n":31,"t":"因你在一切市口上建造圓頂花樓，在各街上做了高臺，你卻藐視賞賜，不像妓女。","notes":[]},{"n":32,"t":"哎！你這行淫的妻啊，寧肯接外人，不接丈夫。","notes":[]},{"n":33,"t":"凡妓女是得人贈送，你反倒贈送你所愛的人，賄賂他們從四圍來與你行淫。","notes":[]},{"n":34,"t":"你行淫與別的婦女相反，因為不是人從你行淫；你既贈送人，人並不贈送你；所以你與別的婦女相反。」","notes":[]},{"n":35,"t":"「你這妓女啊，要聽耶和華的話。","notes":[],"heads":["神審判耶路撒冷"]},{"n":36,"t":"主耶和華如此說：因你的污穢傾洩了，你與你所愛的行淫露出下體，又因你拜一切可憎的偶像，流兒女的血獻給他，","notes":[]},{"n":37,"t":"我就要將你一切相歡相愛的和你一切所恨的都聚集來，從四圍攻擊你；又將你的下體露出，使他們看盡了。","notes":[]},{"n":38,"t":"我也要審判你，好像官長審判淫婦和流人血的婦女一樣。我因忿怒忌恨，使流血的罪歸到你身上。","notes":[]},{"n":39,"t":"我又要將你交在他們手中；他們必拆毀你的圓頂花樓，毀壞你的高臺，剝去你的衣服，奪取你的華美寶器，留下你赤身露體。","notes":[]},{"n":40,"t":"他們也必帶多人來攻擊你，用石頭打死你，用刀劍刺透你，","notes":[]},{"n":41,"t":"用火焚燒你的房屋，在許多婦人眼前向你施行審判。我必使你不再行淫，也不再贈送與人。","notes":[]},{"n":42,"t":"這樣，我就止息向你發的忿怒，我的忌恨也要離開你，我要安靜不再惱怒。","notes":[]},{"n":43,"t":"因你不追念你幼年的日子，在這一切的事上向我發烈怒，所以我必照你所行的報應在你頭上，你就不再貪淫，行那一切可憎的事。這是主耶和華說的。」","notes":[]},{"n":44,"t":"「凡說俗語的必用俗語攻擊你，說：『母親怎樣，女兒也怎樣。』","notes":[],"heads":["有其母必有其女"]},{"n":45,"t":"你正是你母親的女兒，厭棄丈夫和兒女；你正是你姊妹的姊妹，厭棄丈夫和兒女。你母親是赫人，你父親是亞摩利人。","notes":[]},{"n":46,"t":"你的姊姊是撒馬利亞，她和她的眾女住在你左邊；你的妹妹是所多瑪，她和她的眾女住在你右邊。","notes":[]},{"n":47,"t":"你沒有效法她們的行為，也沒有照她們可憎的事去做，你以那為小事，你一切所行的倒比她們更壞。","notes":[]},{"n":48,"t":"主耶和華說：我指著我的永生起誓，你妹妹所多瑪與她的眾女尚未行你和你眾女所行的事。","notes":[]},{"n":49,"t":"看哪，你妹妹所多瑪的罪孽是這樣：她和她的眾女都心驕氣傲，糧食飽足，大享安逸，並沒有扶助困苦和窮乏人的手。","notes":[]},{"n":50,"t":"她們狂傲，在我面前行可憎的事，我看見便將她們除掉。","notes":[]},{"n":51,"t":"撒馬利亞沒有犯你一半的罪，你行可憎的事比她更多，使你的姊妹因你所行一切可憎的事，倒顯為義。","notes":[]},{"n":52,"t":"你既斷定你姊妹為義，就要擔當自己的羞辱；因你所犯的罪比她們更為可憎，她們就比你更顯為義；你既使你的姊妹顯為義，你就要抱愧擔當自己的羞辱。」","notes":["為義：或譯當受羞辱"]},{"n":53,"t":"「我必叫她們被擄的歸回，就是叫所多瑪和她的眾女，撒馬利亞和她的眾女，並你們中間被擄的，都要歸回，","notes":[],"heads":["所多瑪、撒馬利亞要復興"]},{"n":54,"t":"好使你擔當自己的羞辱，並因你一切所行的使她們得安慰，你就抱愧。","notes":[]},{"n":55,"t":"你的妹妹所多瑪和她的眾女必歸回原位；撒馬利亞和她的眾女，你和你的眾女，也必歸回原位。","notes":[]},{"n":56,"t":"在你驕傲的日子，你的惡行沒有顯露以先，你的口就不提你的妹妹所多瑪。那受了凌辱的亞蘭眾女和亞蘭四圍非利士的眾女都恨惡你，藐視你。","notes":[],"end":57},{"n":58,"t":"耶和華說：你貪淫和可憎的事，你已經擔當了。」","notes":[]},{"n":59,"t":"「主耶和華如此說：你這輕看誓言、背棄盟約的，我必照你所行的待你。","notes":[],"heads":["永遠的約"]},{"n":60,"t":"然而我要追念在你幼年時與你所立的約，也要與你立定永約。","notes":[]},{"n":61,"t":"你接待你姊姊和你妹妹的時候，你要追念你所行的，自覺慚愧；並且我要將她們賜你為女兒，卻不是按著前約。","notes":[]},{"n":62,"t":"我要堅定與你所立的約（你就知道我是耶和華），","notes":[]},{"n":63,"t":"好使你在我赦免你一切所行的時候，心裏追念，自覺抱愧，又因你的羞辱就不再開口。這是主耶和華說的。」","notes":[]}]},"17":{"heading":"老鷹和葡萄樹的比喻","verses":[{"n":1,"t":"耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要向以色列家出謎語，設比喻，","notes":[]},{"n":3,"t":"說主耶和華如此說：有一大鷹，翅膀大，翎毛長，羽毛豐滿，彩色俱備，來到黎巴嫩，將香柏樹梢擰去，","notes":[]},{"n":4,"t":"就是折去香柏樹儘尖的嫩枝，叼到貿易之地，放在買賣城中；","notes":[]},{"n":5,"t":"又將以色列地的枝子栽於肥田裏，插在大水旁，如插柳樹，","notes":[]},{"n":6,"t":"就漸漸生長，成為蔓延矮小的葡萄樹。其枝轉向那鷹，其根在鷹以下，於是成了葡萄樹，生出枝子，發出小枝。","notes":[]},{"n":7,"t":"「又有一大鷹，翅膀大，羽毛多。這葡萄樹從栽種的畦中向這鷹彎過根來，發出枝子，好得它的澆灌。","notes":[]},{"n":8,"t":"這樹栽於肥田多水的旁邊，好生枝子，結果子，成為佳美的葡萄樹。","notes":[]},{"n":9,"t":"你要說，主耶和華如此說：這葡萄樹豈能發旺呢？鷹豈不拔出它的根來，芟除它的果子，使它枯乾，使它發的嫩葉都枯乾了嗎？也不用大力和多民，就拔出它的根來。","notes":[]},{"n":10,"t":"葡萄樹雖然栽種，豈能發旺呢？一經東風，豈不全然枯乾嗎？必在生長的畦中枯乾了。」","notes":[]},{"n":11,"t":"耶和華的話臨到我說：","notes":[],"heads":["解釋比喻"]},{"n":12,"t":"「你對那悖逆之家說：你們不知道這些事是甚麼意思嗎？你要告訴他們說，巴比倫王曾到耶路撒冷，將其中的君王和首領帶到巴比倫自己那裏去。","notes":[]},{"n":13,"t":"從以色列的宗室中取一人與他立約，使他發誓，並將國中有勢力的人擄去，","notes":[]},{"n":14,"t":"使國低微不能自強，惟因守盟約得以存立。","notes":[]},{"n":15,"t":"他卻背叛巴比倫王，打發使者往埃及去，要他們給他馬匹和多民。他豈能亨通呢？行這樣事的人豈能逃脫呢？他背約豈能逃脫呢？","notes":[]},{"n":16,"t":"他輕看向王所起的誓，背棄王與他所立的約。主耶和華說：我指著我的永生起誓，他定要死在立他作王、巴比倫王的京都。","notes":[]},{"n":17,"t":"敵人築壘造臺，與他打仗的時候，為要剪除多人，法老雖領大軍隊和大群眾，還是不能幫助他。","notes":[]},{"n":18,"t":"他輕看誓言，背棄盟約，已經投降，卻又做這一切的事，他必不能逃脫。」","notes":[]},{"n":19,"t":"所以主耶和華如此說：「我指著我的永生起誓，他既輕看指我所起的誓，背棄指我所立的約，我必要使這罪歸在他頭上。","notes":[]},{"n":20,"t":"我必將我的網撒在他身上，他必在我的網羅中纏住。我必帶他到巴比倫，並要在那裏因他干犯我的罪刑罰他。","notes":[]},{"n":21,"t":"他的一切軍隊，凡逃跑的，都必倒在刀下；所剩下的，也必分散四方。你們就知道說這話的是我－耶和華。」","notes":["方：原文是風"]},{"n":22,"t":"主耶和華如此說：「我要將香柏樹梢擰去栽上，就是從儘尖的嫩枝中折一嫩枝，栽於極高的山上；","notes":[],"heads":["神對將來的應許"]},{"n":23,"t":"在以色列高處的山栽上。它就生枝子，結果子，成為佳美的香柏樹，各類飛鳥都必宿在其下，就是宿在枝子的蔭下。","notes":[]},{"n":24,"t":"田野的樹木都必知道我－耶和華使高樹矮小，矮樹高大；青樹枯乾，枯樹發旺。我－耶和華如此說，也如此行了。」","notes":[]}]},"18":{"heading":"","verses":[{"n":1,"t":"耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「你們在以色列地怎麼用這俗語說『父親吃了酸葡萄，兒子的牙酸倒了』呢？」","notes":[]},{"n":3,"t":"主耶和華說：「我指著我的永生起誓，你們在以色列中，必不再有用這俗語的因由。","notes":[]},{"n":4,"t":"看哪，世人都是屬我的；為父的怎樣屬我，為子的也照樣屬我；犯罪的，他必死亡。","notes":[]},{"n":5,"t":"「人若是公義，且行正直與合理的事：","notes":[]},{"n":6,"t":"未曾在山上吃過祭偶像之物，未曾仰望以色列家的偶像，未曾玷污鄰舍的妻，未曾在婦人的經期內親近她，","notes":[]},{"n":7,"t":"未曾虧負人，乃將欠債之人的當頭還給他；未曾搶奪人的物件，卻將食物給飢餓的人吃，將衣服給赤身的人穿；","notes":[]},{"n":8,"t":"未曾向借錢的弟兄取利，也未曾向借糧的弟兄多要，縮手不作罪孽，在兩人之間，按至理判斷；","notes":[]},{"n":9,"t":"遵行我的律例，謹守我的典章，按誠實行事－這人是公義的，必定存活。這是主耶和華說的。","notes":[]},{"n":10,"t":"「他若生一個兒子，作強盜，是流人血的，不行以上所說之善，反行其中之惡，乃在山上吃過祭偶像之物，並玷污鄰舍的妻，","notes":[],"end":11},{"n":12,"t":"虧負困苦和窮乏的人，搶奪人的物，未曾將當頭還給人，仰望偶像，並行可憎的事，","notes":[]},{"n":13,"t":"向借錢的弟兄取利，向借糧的弟兄多要－這人豈能存活呢？他必不能存活。他行這一切可憎的事，必要死亡，他的罪必歸到他身上。","notes":["原文是血"]},{"n":14,"t":"「他若生一個兒子，見父親所犯的一切罪便懼怕，不照樣去做；","notes":["有古卷：思量"]},{"n":15,"t":"未曾在山上吃過祭偶像之物，未曾仰望以色列家的偶像，未曾玷污鄰舍的妻，","notes":[]},{"n":16,"t":"未曾虧負人，未曾取人的當頭，未曾搶奪人的物件，卻將食物給飢餓的人吃，將衣服給赤身的人穿，","notes":[]},{"n":17,"t":"縮手不害貧窮人，未曾向借錢的弟兄取利，也未曾向借糧的弟兄多要；他順從我的典章，遵行我的律例，就不因父親的罪孽死亡，定要存活。","notes":[]},{"n":18,"t":"至於他父親；因為欺人太甚，搶奪弟兄，在本國的民中行不善，他必因自己的罪孽死亡。","notes":[]},{"n":19,"t":"「你們還說：『兒子為何不擔當父親的罪孽呢？』兒子行正直與合理的事，謹守遵行我的一切律例，他必定存活。","notes":[]},{"n":20,"t":"惟有犯罪的，他必死亡。兒子必不擔當父親的罪孽，父親也不擔當兒子的罪孽。義人的善果必歸自己，惡人的惡報也必歸自己。","notes":[]},{"n":21,"t":"「惡人若回頭離開所做的一切罪惡，謹守我一切的律例，行正直與合理的事，他必定存活，不致死亡。","notes":[]},{"n":22,"t":"他所犯的一切罪過都不被記念，因所行的義，他必存活。","notes":[]},{"n":23,"t":"主耶和華說：惡人死亡，豈是我喜悅的嗎？不是喜悅他回頭離開所行的道存活嗎？","notes":[]},{"n":24,"t":"義人若轉離義行而作罪孽，照著惡人所行一切可憎的事而行，他豈能存活嗎？他所行的一切義都不被記念；他必因所犯的罪、所行的惡死亡。","notes":[]},{"n":25,"t":"「你們還說：『主的道不公平！』以色列家啊，你們當聽，我的道豈不公平嗎？你們的道豈不是不公平嗎？","notes":[]},{"n":26,"t":"義人若轉離義行而作罪孽死亡，他是因所作的罪孽死亡。","notes":[]},{"n":27,"t":"再者，惡人若回頭離開所行的惡，行正直與合理的事，他必將性命救活了。","notes":[]},{"n":28,"t":"因為他思量，回頭離開所犯的一切罪過，必定存活，不致死亡。","notes":[]},{"n":29,"t":"以色列家還說：『主的道不公平！』以色列家啊，我的道豈不公平嗎？你們的道豈不是不公平嗎？」","notes":[]},{"n":30,"t":"所以主耶和華說：「以色列家啊，我必按你們各人所行的審判你們。你們當回頭離開所犯的一切罪過。這樣，罪孽必不使你們敗亡。","notes":[]},{"n":31,"t":"你們要將所犯的一切罪過盡行拋棄，自做一個新心和新靈。以色列家啊，你們何必死亡呢？","notes":[]},{"n":32,"t":"主耶和華說：我不喜悅那死人之死，所以你們當回頭而存活。」","notes":[]}]},"19":{"heading":"輓歌","verses":[{"n":1,"t":"你當為以色列的王作起哀歌，","notes":[]},{"n":2,"t":"說：你的母親是甚麼呢？是個母獅子，蹲伏在獅子中間，在少壯獅子中養育小獅子。","notes":[]},{"n":3,"t":"在牠小獅子中養大一個，成了少壯獅子，學會抓食而吃人。","notes":[]},{"n":4,"t":"列國聽見了就把牠捉在他們的坑中，用鉤子拉到埃及地去。","notes":[]},{"n":5,"t":"母獅見自己等候失了指望，就從牠小獅子中又將一個養為少壯獅子。","notes":[]},{"n":6,"t":"牠在眾獅子中走來走去，成了少壯獅子，學會抓食而吃人。","notes":[]},{"n":7,"t":"牠知道列國的宮殿，又使他們的城邑變為荒場；因牠咆哮的聲音，遍地和其中所有的就都荒廢。","notes":[]},{"n":8,"t":"於是四圍邦國各省的人來攻擊牠，將網撒在牠身上，捉在他們的坑中。","notes":[]},{"n":9,"t":"他們用鉤子鉤住牠，將牠放在籠中，帶到巴比倫王那裏，將牠放入堅固之所，使牠的聲音在以色列山上不再聽見。","notes":[]},{"n":10,"t":"你的母親先前如葡萄樹，極其茂盛，栽於水旁。因為水多，就多結果子，滿生枝子；","notes":["原文是在你血中"]},{"n":11,"t":"生出堅固的枝幹，可作掌權者的杖。這枝幹高舉在茂密的枝中，而且它生長高大，枝子繁多，遠遠可見。","notes":[]},{"n":12,"t":"但這葡萄樹因忿怒被拔出摔在地上；東風吹乾其上的果子，堅固的枝幹折斷枯乾，被火燒毀了；","notes":[]},{"n":13,"t":"如今栽於曠野乾旱無水之地。","notes":[]},{"n":14,"t":"火也從它枝幹中發出，燒滅果子，以致沒有堅固的枝幹可做掌權者的杖。這是哀歌，也必用以作哀歌。","notes":[]}]},"20":{"heading":"神的旨意，人的抗命","verses":[{"n":1,"t":"第七年五月初十日，有以色列的幾個長老來求問耶和華，坐在我面前。","notes":[]},{"n":2,"t":"耶和華的話臨到我說：","notes":[]},{"n":3,"t":"「人子啊，你要告訴以色列的長老說，主耶和華如此說：你們來是求問我嗎？主耶和華說：我指著我的永生起誓，我必不被你們求問。","notes":[]},{"n":4,"t":"人子啊，你要審問審問他們嗎？你當使他們知道他們列祖那些可憎的事，","notes":[]},{"n":5,"t":"對他們說，主耶和華如此說：當日我揀選以色列，向雅各家的後裔起誓，在埃及地將自己向他們顯現，說：我是耶和華－你們的神。","notes":[]},{"n":6,"t":"那日我向他們起誓，必領他們出埃及地，到我為他們察看的流奶與蜜之地；那地在萬國中是有榮耀的。","notes":[]},{"n":7,"t":"我對他們說，你們各人要拋棄眼所喜愛那可憎之物，不可因埃及的偶像玷污自己。我是耶和華－你們的神。","notes":[]},{"n":8,"t":"他們卻悖逆我，不肯聽從我，不拋棄他們眼所喜愛那可憎之物，不離棄埃及的偶像。「我就說，我要將我的忿怒傾在他們身上，在埃及地向他們成就我怒中所定的。","notes":[]},{"n":9,"t":"我卻為我名的緣故沒有這樣行，免得我名在他們所住的列國人眼前被褻瀆；我領他們出埃及地，在這列國人的眼前將自己向他們顯現。","notes":[]},{"n":10,"t":"這樣，我就使他們出埃及地，領他們到曠野，","notes":[]},{"n":11,"t":"將我的律例賜給他們，將我的典章指示他們；人若遵行就必因此活著。","notes":[]},{"n":12,"t":"又將我的安息日賜給他們，好在我與他們中間為證據，使他們知道我－耶和華是叫他們成為聖的。","notes":[]},{"n":13,"t":"以色列家卻在曠野悖逆我，不順從我的律例，厭棄我的典章（人若遵行就必因此活著），大大干犯我的安息日。「我就說，要在曠野將我的忿怒傾在他們身上，滅絕他們。","notes":[]},{"n":14,"t":"我卻為我名的緣故，沒有這樣行，免得我的名在我領他們出埃及的列國人眼前被褻瀆。","notes":[]},{"n":15,"t":"並且我在曠野向他們起誓，必不領他們進入我所賜給他們流奶與蜜之地（那地在萬國中是有榮耀的）；","notes":[]},{"n":16,"t":"因為他們厭棄我的典章，不順從我的律例，干犯我的安息日，他們的心隨從自己的偶像。","notes":[]},{"n":17,"t":"雖然如此，我眼仍顧惜他們，不毀滅他們，不在曠野將他們滅絕淨盡。","notes":[]},{"n":18,"t":"「我在曠野對他們的兒女說：不要遵行你們父親的律例，不要謹守他們的惡規，也不要因他們的偶像玷污自己。","notes":[]},{"n":19,"t":"我是耶和華－你們的神，你們要順從我的律例，謹守遵行我的典章，","notes":[]},{"n":20,"t":"且以我的安息日為聖。這日在我與你們中間為證據，使你們知道我是耶和華－你們的神。","notes":[]},{"n":21,"t":"只是他們的兒女悖逆我，不順從我的律例，也不謹守遵行我的典章（人若遵行就必因此活著），干犯我的安息日。「我就說，要將我的忿怒傾在他們身上，在曠野向他們成就我怒中所定的。","notes":[]},{"n":22,"t":"雖然如此，我卻為我名的緣故縮手沒有這樣行，免得我的名在我領他們出埃及的列國人眼前被褻瀆。","notes":[]},{"n":23,"t":"並且我在曠野向他們起誓，必將他們分散在列國，四散在列邦；","notes":[]},{"n":24,"t":"因為他們不遵行我的典章，竟厭棄我的律例，干犯我的安息日，眼目仰望他們父親的偶像。","notes":[]},{"n":25,"t":"我也任他們遵行不美的律例，謹守不能使人活著的惡規。","notes":[]},{"n":26,"t":"因他們將一切頭生的經火，我就任憑他們在這供獻的事上玷污自己，好叫他們淒涼，使他們知道我是耶和華。","notes":[]},{"n":27,"t":"「人子啊，你要告訴以色列家說，主耶和華如此說：你們的列祖在得罪我的事上褻瀆我；","notes":[]},{"n":28,"t":"因為我領他們到了我起誓應許賜給他們的地，他們看見各高山、各茂密樹，就在那裏獻祭，奉上惹我發怒的供物，也在那裏焚燒馨香的祭牲，並澆上奠祭。","notes":[]},{"n":29,"t":"我就對他們說：你們所上的那高處叫甚麼呢？（那高處的名字叫巴麻直到今日。）","notes":[]},{"n":30,"t":"所以你要對以色列家說，主耶和華如此說：你們仍照你們列祖所行的玷污自己嗎？仍照他們可憎的事行邪淫嗎？","notes":[]},{"n":31,"t":"你們奉上供物使你們兒子經火的時候，仍將一切偶像玷污自己，直到今日嗎？以色列家啊，我豈被你們求問嗎？主耶和華說：我指著我的永生起誓，我必不被你們求問。","notes":[]},{"n":32,"t":"「你們說：我們要像外邦人和列國的宗族一樣，去事奉木頭與石頭。你們所起的這心意萬不能成就。」","notes":[]},{"n":33,"t":"主耶和華說：「我指著我的永生起誓，我總要作王，用大能的手和伸出來的膀臂，並傾出來的忿怒，治理你們。","notes":[],"heads":["神的懲罰和赦免"]},{"n":34,"t":"我必用大能的手和伸出來的膀臂，並傾出來的忿怒，將你們從萬民中領出來，從分散的列國內聚集你們。","notes":[]},{"n":35,"t":"我必帶你們到外邦人的曠野，在那裏當面刑罰你們。","notes":[]},{"n":36,"t":"我怎樣在埃及地的曠野刑罰你們的列祖，也必照樣刑罰你們。這是主耶和華說的。","notes":[]},{"n":37,"t":"我必使你們從杖下經過，使你們被約拘束。","notes":[]},{"n":38,"t":"我必從你們中間除淨叛逆和得罪我的人，將他們從所寄居的地方領出來，他們卻不得入以色列地。你們就知道我是耶和華。","notes":[]},{"n":39,"t":"「以色列家啊，至於你們，主耶和華如此說：從此以後若不聽從我，就任憑你們去事奉偶像，只是不可再因你們的供物和偶像褻瀆我的聖名。","notes":[]},{"n":40,"t":"「主耶和華說：在我的聖山，就是以色列高處的山，所有以色列的全家都要事奉我。我要在那裏悅納你們，向你們要供物和初熟的土產，並一切的聖物。","notes":[]},{"n":41,"t":"我從萬民中領你們出來，從分散的列國內聚集你們，那時我必悅納你們好像馨香之祭，要在外邦人眼前在你們身上顯為聖。","notes":[]},{"n":42,"t":"我領你們進入以色列地，就是我起誓應許賜給你們列祖之地，那時你們就知道我是耶和華。","notes":[]},{"n":43,"t":"你們在那裏要追念玷污自己的行動作為，又要因所做的一切惡事厭惡自己。","notes":[]},{"n":44,"t":"主耶和華說：以色列家啊，我為我名的緣故，不照著你們的惡行和你們的壞事待你們；你們就知道我是耶和華。」","notes":[]},{"n":45,"t":"耶和華的話臨到我說：","notes":[],"heads":["南方大火"]},{"n":46,"t":"「人子啊，你要面向南方，向南滴下預言攻擊南方田野的樹林。","notes":[]},{"n":47,"t":"對南方的樹林說，要聽耶和華的話。主耶和華如此說：我必使火在你中間著起，燒滅你中間的一切青樹和枯樹，猛烈的火焰必不熄滅。從南到北，人的臉面都被燒焦。","notes":[]},{"n":48,"t":"凡有血氣的都必知道是我－耶和華使火著起，這火必不熄滅。」","notes":[]},{"n":49,"t":"於是我說：「哎！主耶和華啊，人都指著我說：他豈不是說比喻的嗎？」","notes":[]}]},"21":{"heading":"耶和華的刀","verses":[{"n":1,"t":"耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要面向耶路撒冷和聖所滴下預言，攻擊以色列地。","notes":[]},{"n":3,"t":"對以色列地說，耶和華如此說：我與你為敵，並要拔刀出鞘，從你中間將義人和惡人一併剪除。","notes":[]},{"n":4,"t":"我既要從你中間剪除義人和惡人，所以我的刀要出鞘，自南至北攻擊一切有血氣的；","notes":[]},{"n":5,"t":"一切有血氣的就知道我－耶和華已經拔刀出鞘，必不再入鞘。","notes":[]},{"n":6,"t":"人子啊，你要歎息，在他們眼前彎著腰，苦苦地歎息。","notes":[]},{"n":7,"t":"他們問你說：『為何歎息呢？』你就說：『因為有風聲、災禍要來。人心都必消化，手都發軟，精神衰敗，膝弱如水。看哪，這災禍臨近，必然成就。這是主耶和華說的。』」","notes":[]},{"n":8,"t":"耶和華的話臨到我說：","notes":[]},{"n":9,"t":"「人子啊，你要預言。耶和華吩咐我如此說：有刀、有刀，是磨快擦亮的；","notes":[]},{"n":10,"t":"磨快為要行殺戮，擦亮為要像閃電。我們豈可快樂嗎？罰我子的杖藐視各樹。","notes":[]},{"n":11,"t":"這刀已經交給人擦亮，為要應手使用。這刀已經磨快擦亮，好交在行殺戮的人手中。","notes":[]},{"n":12,"t":"人子啊，你要呼喊哀號，因為這刀臨到我的百姓和以色列一切的首領。他們和我的百姓都交在刀下，所以你要拍腿歎息。","notes":[]},{"n":13,"t":"有試驗的事；若那藐視的杖歸於無有，怎麼樣呢？這是主耶和華說的。","notes":[]},{"n":14,"t":"「人子啊，你要拍掌預言。我－耶和華要使這刀，就是致死傷的刀，一連三次加倍刺人，進入他們的內屋，使大人受死傷的就是這刀。","notes":[]},{"n":15,"t":"我設立這恐嚇人的刀，攻擊他們的一切城門，使他們的心消化，加增他們跌倒的事。哎！這刀造得像閃電，磨得尖利，要行殺戮。","notes":[]},{"n":16,"t":"刀啊，你歸在右邊，擺在左邊；你面向哪方，就向那方殺戮。","notes":[]},{"n":17,"t":"我也要拍掌，並要使我的忿怒止息。這是我－耶和華說的。」","notes":[]},{"n":18,"t":"耶和華的話又臨到我說：","notes":[],"heads":["巴比倫王的刀"]},{"n":19,"t":"「人子啊，你要定出兩條路，好使巴比倫王的刀來。這兩條路必從一地分出來，又要在通城的路口上畫出一隻手來。","notes":[]},{"n":20,"t":"你要定出一條路，使刀來到亞捫人的拉巴；又要定出一條路，使刀來到猶大的堅固城耶路撒冷。","notes":[]},{"n":21,"t":"因為巴比倫王站在岔路那裏，在兩條路口上要占卜。他搖籤求問神像，察看犧牲的肝；","notes":["原文是箭"]},{"n":22,"t":"在右手中拿著為耶路撒冷占卜的籤，使他安設撞城錘，張口叫殺，揚聲吶喊，築壘造臺，以撞城錘，攻打城門。","notes":[]},{"n":23,"t":"據那些曾起誓的猶大人看來，這是虛假的占卜；但巴比倫王要使他們想起罪孽，以致將他們捉住。」","notes":[]},{"n":24,"t":"主耶和華如此說：「因你們的過犯顯露，使你們的罪孽被記念，以致你們的罪惡在行為上都彰顯出來；又因你們被記念，就被捉住。","notes":[]},{"n":25,"t":"你這受死傷行惡的以色列王啊，罪孽的盡頭到了，受報的日子已到。","notes":[]},{"n":26,"t":"主耶和華如此說：當除掉冠，摘下冕，景況必不再像先前；要使卑者升為高，使高者降為卑。","notes":[]},{"n":27,"t":"我要將這國傾覆，傾覆，而又傾覆；這國也必不再有，直等到那應得的人來到，我就賜給他。」","notes":[]},{"n":28,"t":"「人子啊，要發預言說：主耶和華論到亞捫人和他們的凌辱，吩咐我如此說：有刀，有拔出來的刀，已經擦亮，為行殺戮，使他像閃電以行吞滅。","notes":[],"heads":["刀和亞捫人"]},{"n":29,"t":"人為你見虛假的異象，行謊詐的占卜，使你倒在受死傷之惡人的頸項上。他們罪孽到了盡頭，受報的日子已到。","notes":[]},{"n":30,"t":"你將刀收入鞘吧！在你受造之處、生長之地，我必刑罰你。","notes":[]},{"n":31,"t":"我必將我的惱恨倒在你身上，將我烈怒的火噴在你身上；又將你交在善於殺滅的畜類人手中。","notes":[]},{"n":32,"t":"你必當柴被火焚燒；你的血必流在國中。你必不再被記念，因為這是我－耶和華說的。」","notes":[]}]},"22":{"heading":"耶路撒冷的過犯","verses":[{"n":1,"t":"耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要審問審問這流人血的城嗎？當使她知道她一切可憎的事。","notes":[]},{"n":3,"t":"你要說，主耶和華如此說：哎！這城有流人血的事在其中，叫她受報的日期來到，又做偶像玷污自己，陷害自己。","notes":[]},{"n":4,"t":"你因流了人的血，就為有罪；你做了偶像，就玷污自己，使你受報之日臨近，報應之年來到。所以我叫你受列國的凌辱和列邦的譏誚。","notes":[]},{"n":5,"t":"你這名臭、多亂的城啊，那些離你近、離你遠的都必譏誚你。","notes":[]},{"n":6,"t":"「看哪，以色列的首領各逞其能，在你中間流人之血。","notes":[]},{"n":7,"t":"在你中間有輕慢父母的，有欺壓寄居的，有虧負孤兒寡婦的。","notes":[]},{"n":8,"t":"你藐視了我的聖物，干犯了我的安息日。","notes":[]},{"n":9,"t":"在你中間有讒謗人、流人血的；有在山上吃過祭偶像之物的，有行淫亂的。","notes":[]},{"n":10,"t":"在你中間有露繼母下體羞辱父親的，有玷辱月經不潔淨之婦人的。","notes":[]},{"n":11,"t":"這人與鄰舍的妻行可憎的事；那人貪淫玷污兒婦；還有玷辱同父之姊妹的。","notes":[]},{"n":12,"t":"在你中間有為流人血受賄賂的；有向借錢的弟兄取利，向借糧的弟兄多要的。且因貪得無饜，欺壓鄰舍奪取財物，竟忘了我。這是主耶和華說的。","notes":[]},{"n":13,"t":"「看哪，我因你所得不義之財和你中間所流的血，就拍掌歎息。","notes":[]},{"n":14,"t":"到了我懲罰你的日子，你的心還能忍受嗎？你的手還能有力嗎？我－耶和華說了這話，就必照著行。","notes":[]},{"n":15,"t":"我必將你分散在列國，四散在列邦。我也必從你中間除掉你的污穢。","notes":[]},{"n":16,"t":"你必在列國人的眼前因自己所行的被褻瀆，你就知道我是耶和華。」","notes":[]},{"n":17,"t":"耶和華的話臨到我說：","notes":[],"heads":["神的大煉爐"]},{"n":18,"t":"「人子啊，以色列家在我看為渣滓。他們都是爐中的銅、錫、鐵、鉛，都是銀渣滓。","notes":[]},{"n":19,"t":"所以主耶和華如此說：因你們都成為渣滓，我必聚集你們在耶路撒冷中。","notes":[]},{"n":20,"t":"人怎樣將銀、銅、鐵、鉛、錫聚在爐中，吹火鎔化；照樣，我也要發怒氣和忿怒，將你們聚集放在城中，鎔化你們。","notes":[]},{"n":21,"t":"我必聚集你們，把我烈怒的火吹在你們身上，你們就在其中鎔化。","notes":[]},{"n":22,"t":"銀子怎樣鎔化在爐中，你們也必照樣鎔化在城中，你們就知道我－耶和華是將忿怒倒在你們身上了。」","notes":[]},{"n":23,"t":"耶和華的話臨到我說：","notes":[],"heads":["以色列領袖們的罪惡"]},{"n":24,"t":"「人子啊，你要對這地說：你是未得潔淨之地，在惱恨的日子也沒有雨下在你以上。","notes":[]},{"n":25,"t":"其中的先知同謀背叛，如咆哮的獅子抓撕掠物。他們吞滅人民，搶奪財寶，使這地多有寡婦。","notes":[]},{"n":26,"t":"其中的祭司強解我的律法，褻瀆我的聖物，不分別聖的和俗的，也不使人分辨潔淨的和不潔淨的，又遮眼不顧我的安息日；我也在他們中間被褻慢。","notes":[]},{"n":27,"t":"其中的首領彷彿豺狼抓撕掠物，殺人流血，傷害人命，要得不義之財。","notes":[]},{"n":28,"t":"其中的先知為百姓用未泡透的灰抹牆，就是為他們見虛假的異象，用謊詐的占卜，說：『主耶和華如此說』，其實耶和華沒有說。","notes":[]},{"n":29,"t":"國內眾民一味地欺壓，慣行搶奪，虧負困苦窮乏的，背理欺壓寄居的。","notes":[]},{"n":30,"t":"我在他們中間尋找一人重修牆垣，在我面前為這國站在破口防堵，使我不滅絕這國，卻找不著一個。","notes":[]},{"n":31,"t":"所以我將惱恨倒在他們身上，用烈怒的火滅了他們，照他們所行的報應在他們頭上。這是主耶和華說的。」","notes":[]}]},"23":{"heading":"兩個犯罪的姊妹","verses":[{"n":1,"t":"耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「人子啊，有兩個女子，是一母所生，","notes":[]},{"n":3,"t":"她們在埃及行邪淫，在幼年時行邪淫。她們在那裏作處女的時候，有人擁抱她們的懷，撫摸她們的乳。","notes":[]},{"n":4,"t":"她們的名字，姊姊名叫阿荷拉，妹妹名叫阿荷利巴。她們都歸於我，生了兒女。論到她們的名字，阿荷拉就是撒馬利亞，阿荷利巴就是耶路撒冷。","notes":[]},{"n":5,"t":"「阿荷拉歸我之後行邪淫，貪戀所愛的人，就是她的鄰邦亞述人。","notes":[]},{"n":6,"t":"這些人都穿藍衣，作省長、副省長，都騎著馬，是可愛的少年人。","notes":[]},{"n":7,"t":"阿荷拉就與亞述人中最美的男子放縱淫行，她因所戀愛之人的一切偶像，玷污自己。","notes":[]},{"n":8,"t":"自從在埃及的時候，她就沒有離開淫亂，因為她年幼作處女的時候，埃及人與她行淫，撫摸她的乳，縱慾與她行淫。","notes":[]},{"n":9,"t":"因此，我將她交在她所愛的人手中，就是她所戀愛的亞述人手中。","notes":[]},{"n":10,"t":"他們就露了她的下體，擄掠她的兒女，用刀殺了她，使她在婦女中留下臭名，因他們向她施行審判。","notes":[]},{"n":11,"t":"「她妹妹阿荷利巴雖然看見了，卻還貪戀，比她姊姊更醜；行淫亂比她姊姊更多。","notes":[]},{"n":12,"t":"她貪戀鄰邦的亞述人，就是穿極華美的衣服，騎著馬的省長、副省長，都是可愛的少年人。","notes":[]},{"n":13,"t":"我看見她被玷污了，她姊妹二人同行一路。","notes":[]},{"n":14,"t":"阿荷利巴又加增淫行，因她看見人像畫在牆上，就是用丹色所畫迦勒底人的像，","notes":[]},{"n":15,"t":"腰間繫著帶子，頭上有下垂的裹頭巾，都是軍長的形狀，仿照巴比倫人的形像；他們的故土就是迦勒底。","notes":[]},{"n":16,"t":"阿荷利巴一看見就貪戀他們，打發使者往迦勒底去見他們。","notes":[]},{"n":17,"t":"巴比倫人就來登她愛情的床，與她行淫玷污她。她被玷污，隨後心裏與他們生疏。","notes":[]},{"n":18,"t":"這樣，她顯露淫行，又顯露下體；我心就與她生疏，像先前與她姊姊生疏一樣。","notes":[]},{"n":19,"t":"她還加增她的淫行，追念她幼年在埃及地行邪淫的日子，","notes":[]},{"n":20,"t":"貪戀情人身壯精足，如驢如馬。","notes":[]},{"n":21,"t":"這樣，你就想起你幼年的淫行。那時，埃及人擁抱你的懷，撫摸你的乳。」","notes":[]},{"n":22,"t":"阿荷利巴啊，主耶和華如此說：「我必激動你先愛而後生疏的人來攻擊你。我必使他們來，在你四圍攻擊你。","notes":[],"heads":["神審判妹妹"]},{"n":23,"t":"所來的就是巴比倫人、迦勒底的眾人、比割人、書亞人、哥亞人，同著他們的還有亞述眾人，乃是作省長、副省長、作軍長有名聲的，都騎著馬，是可愛的少年人。","notes":[]},{"n":24,"t":"他們必帶兵器、戰車、輜重車，率領大眾來攻擊你。他們要拿大小盾牌，頂盔擺陣，在你四圍攻擊你。我要將審判的事交給他們，他們必按著自己的條例審判你。","notes":[]},{"n":25,"t":"我必以忌恨攻擊你；他們必以忿怒辦你。他們必割去你的鼻子和耳朵；你遺留的人必倒在刀下。他們必擄去你的兒女；你所遺留的必被火焚燒。","notes":["或譯：餘剩；下同"]},{"n":26,"t":"他們必剝去你的衣服，奪取你華美的寶器。","notes":[]},{"n":27,"t":"這樣，我必使你的淫行和你從埃及地染來的淫亂止息了，使你不再仰望亞述，也不再追念埃及。","notes":[]},{"n":28,"t":"主耶和華如此說：我必將你交在你所恨惡的人手中，就是你心與他生疏的人手中。","notes":[]},{"n":29,"t":"他們必以恨惡辦你，奪取你一切勞碌得來的，留下你赤身露體。你淫亂的下體，連你的淫行，帶你的淫亂，都被顯露。","notes":[]},{"n":30,"t":"人必向你行這些事；因為你隨從外邦人行邪淫，被他們的偶像玷污了。","notes":[]},{"n":31,"t":"你走了你姊姊所走的路，所以我必將她的杯交在你手中。」","notes":[]},{"n":32,"t":"主耶和華如此說：你必喝你姊姊所喝的杯；那杯又深又廣，盛得甚多，使你被人嗤笑譏刺。","notes":[]},{"n":33,"t":"你必酩酊大醉，滿有愁苦，喝乾你姊姊撒馬利亞的杯，就是令人驚駭淒涼的杯。","notes":[]},{"n":34,"t":"你必喝這杯，以致喝盡。杯破又齦杯片，撕裂自己的乳；因為這事我曾說過。這是主耶和華說的。","notes":[]},{"n":35,"t":"主耶和華如此說：「因你忘記我，將我丟在背後，所以你要擔當你淫行和淫亂的報應。」","notes":[]},{"n":36,"t":"耶和華又對我說：「人子啊，你要審問阿荷拉與阿荷利巴嗎？當指出她們所行可憎的事。","notes":[],"heads":["神審判兩姊妹"]},{"n":37,"t":"她們行淫，手中有殺人的血，又與偶像行淫，並使她們為我所生的兒女經火燒給偶像。","notes":[]},{"n":38,"t":"此外，她們還有向我所行的，就是同日玷污我的聖所，干犯我的安息日。","notes":[]},{"n":39,"t":"她們殺了兒女獻與偶像，當天又入我的聖所，將聖所褻瀆了。她們在我殿中所行的乃是如此。","notes":[]},{"n":40,"t":"「況且你們二婦打發使者去請遠方人。使者到他們那裏，他們就來了。你們為他們沐浴己身，粉飾眼目，佩戴妝飾，","notes":[]},{"n":41,"t":"坐在華美的床上，前面擺設桌案，將我的香料膏油擺在其上。","notes":[]},{"n":42,"t":"在那裏有群眾安逸歡樂的聲音，並有粗俗的人和酒徒從曠野同來，把鐲子戴在二婦的手上，把華冠戴在她們的頭上。","notes":[]},{"n":43,"t":"「我論這行淫衰老的婦人說：現在人還要與她行淫，她也要與人行淫。","notes":[]},{"n":44,"t":"人與阿荷拉，並阿荷利巴二淫婦苟合，好像與妓女苟合。","notes":[]},{"n":45,"t":"必有義人，照審判淫婦和流人血的婦人之例，審判她們；因為她們是淫婦，手中有殺人的血。」","notes":[]},{"n":46,"t":"主耶和華如此說：「我必使多人來攻擊她們，使她們拋來拋去，被人搶奪。","notes":[]},{"n":47,"t":"這些人必用石頭打死她們，用刀劍殺害她們，又殺戮她們的兒女，用火焚燒她們的房屋。","notes":[]},{"n":48,"t":"這樣，我必使淫行從境內止息，好叫一切婦人都受警戒，不效法你們的淫行。","notes":[]},{"n":49,"t":"人必照著你們的淫行報應你們；你們要擔當拜偶像的罪，就知道我是主耶和華。」","notes":[]}]},"24":{"heading":"生銹的鍋","verses":[{"n":1,"t":"第九年十月初十日，耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「人子啊，今日正是巴比倫王就近耶路撒冷的日子，你要將這日記下，","notes":[]},{"n":3,"t":"要向這悖逆之家設比喻說，主耶和華如此說：將鍋放在火上，放好了，就倒水在其中；","notes":[]},{"n":4,"t":"將肉塊，就是一切肥美的肉塊、腿，和肩都聚在其中，拿美好的骨頭把鍋裝滿；","notes":[]},{"n":5,"t":"取羊群中最好的，將柴堆在鍋下，使鍋開滾，好把骨頭煮在其中。","notes":[]},{"n":6,"t":"「主耶和華如此說：禍哉！這流人血的城，就是長銹的鍋。其中的銹未曾除掉，須要將肉塊從其中一一取出來，不必為它拈鬮。","notes":[]},{"n":7,"t":"城中所流的血倒在淨光的磐石上，不倒在地上，用土掩蓋。","notes":[]},{"n":8,"t":"這城中所流的血倒在淨光的磐石上，不得掩蓋，乃是出於我，為要發忿怒施行報應。","notes":[]},{"n":9,"t":"所以主耶和華如此說：禍哉！這流人血的城，我也必大堆火柴，","notes":[]},{"n":10,"t":"添上木柴，使火著旺，將肉煮爛，把湯熬濃，使骨頭烤焦；","notes":[]},{"n":11,"t":"把鍋倒空坐在炭火上，使鍋燒熱，使銅燒紅，鎔化其中的污穢，除淨其上的銹。","notes":[]},{"n":12,"t":"這鍋勞碌疲乏，所長的大銹仍未除掉；這銹就是用火也不能除掉。","notes":[]},{"n":13,"t":"在你污穢中有淫行，我潔淨你，你卻不潔淨。你的污穢再不能潔淨，直等我向你發的忿怒止息。","notes":[]},{"n":14,"t":"我－耶和華說過的必定成就，必照話而行，必不返回，必不顧惜，也不後悔。人必照你的舉動行為審判你。這是主耶和華說的。」","notes":[]},{"n":15,"t":"耶和華的話又臨到我說：","notes":[],"heads":["先知妻子的死"]},{"n":16,"t":"「人子啊，我要將你眼目所喜愛的忽然取去，你卻不可悲哀哭泣，也不可流淚，","notes":[]},{"n":17,"t":"只可歎息，不可出聲，不可辦理喪事；頭上仍勒裹頭巾，腳上仍穿鞋，不可蒙著嘴唇，也不可吃弔喪的食物。」","notes":[]},{"n":18,"t":"於是我將這事早晨告訴百姓，晚上我的妻就死了。次日早晨我便遵命而行。","notes":[]},{"n":19,"t":"百姓問我說：「你這樣行與我們有甚麼關係，你不告訴我們嗎？」","notes":[]},{"n":20,"t":"我回答他們：「耶和華的話臨到我說：","notes":[]},{"n":21,"t":"『你告訴以色列家，主耶和華如此說：我必使我的聖所，就是你們勢力所誇耀、眼裏所喜愛、心中所愛惜的被褻瀆，並且你們所遺留的兒女必倒在刀下。","notes":[]},{"n":22,"t":"那時，你們必行我僕人所行的，不蒙著嘴唇，也不吃弔喪的食物。","notes":[]},{"n":23,"t":"你們仍要頭上勒裹頭巾，腳上穿鞋；不可悲哀哭泣。你們必因自己的罪孽相對歎息，漸漸消滅。","notes":[]},{"n":24,"t":"以西結必這樣為你們作預兆；凡他所行的，你們也必照樣行。那事來到，你們就知道我是主耶和華。』","notes":[]},{"n":25,"t":"「人子啊，我除掉他們所倚靠、所歡喜的榮耀，並眼中所喜愛、心裏所重看的兒女。","notes":[]},{"n":26,"t":"那日逃脫的人豈不來到你這裏，使你耳聞這事嗎？","notes":[]},{"n":27,"t":"你必向逃脫的人開口說話，不再啞口。你必這樣為他們作預兆，他們就知道我是耶和華。」","notes":[]}]},"25":{"heading":"預言亞捫受懲罰","verses":[{"n":1,"t":"耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要面向亞捫人說預言，攻擊他們，","notes":[]},{"n":3,"t":"說：你們當聽主耶和華的話。主耶和華如此說：我的聖所被褻瀆，以色列地變荒涼，猶大家被擄掠；那時，你便因這些事說：『阿哈！』","notes":[]},{"n":4,"t":"所以我必將你的地交給東方人為業；他們必在你的地上安營居住，吃你的果子，喝你的奶。","notes":[]},{"n":5,"t":"我必使拉巴為駱駝場，使亞捫人的地為羊群躺臥之處，你們就知道我是耶和華。」","notes":[]},{"n":6,"t":"主耶和華如此說：「因你拍手頓足，以滿心的恨惡向以色列地歡喜，","notes":[]},{"n":7,"t":"所以我伸手攻擊你，將你交給列國作為擄物。我必從萬民中剪除你，使你從萬國中敗亡。我必除滅你，你就知道我是耶和華。」","notes":[]},{"n":8,"t":"主耶和華如此說：「因摩押和西珥人說：『看哪，猶大家與列國無異』，","notes":[],"heads":["斥責摩押"]},{"n":9,"t":"所以我要破開摩押邊界上的城邑，就是摩押人看為本國之榮耀的伯‧耶西末、巴力‧免、基列亭，","notes":[]},{"n":10,"t":"好使東方人來攻擊亞捫人。我必將亞捫人之地交給他們為業，使亞捫人在列國中不再被記念。","notes":[]},{"n":11,"t":"我必向摩押施行審判，他們就知道我是耶和華。」","notes":[]},{"n":12,"t":"主耶和華如此說：「因為以東報仇雪恨，攻擊猶大家，向他們報仇，大大有罪，","notes":[],"heads":["斥責以東"]},{"n":13,"t":"所以主耶和華如此說：我必伸手攻擊以東，剪除人與牲畜，使以東從提幔起，人必倒在刀下，地要變為荒涼，直到底但。","notes":[]},{"n":14,"t":"我必藉我民以色列的手報復以東；以色列民必照我的怒氣，按我的忿怒在以東施報，以東人就知道是我施報。這是主耶和華說的。」","notes":[]},{"n":15,"t":"主耶和華如此說：「因非利士人向猶大人報仇，就是以恨惡的心報仇雪恨，永懷仇恨，要毀滅他們，","notes":[],"heads":["斥責非利士"]},{"n":16,"t":"所以主耶和華如此說：我必伸手攻擊非利士人，剪除基利提人，滅絕沿海剩下的居民。","notes":[]},{"n":17,"t":"我向他們大施報應，發怒斥責他們。我報復他們的時候，他們就知道我是耶和華。」","notes":[]}]},"26":{"heading":"斥責泰爾","verses":[{"n":1,"t":"第十一年十一月初一日，耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，因泰爾向耶路撒冷說：『阿哈，那作眾民之門的已經破壞，向我開放；她既變為荒場，我必豐盛。』","notes":[]},{"n":3,"t":"所以，主耶和華如此說：泰爾啊，我必與你為敵，使許多國民上來攻擊你，如同海使波浪湧上來一樣。","notes":[]},{"n":4,"t":"他們必破壞泰爾的牆垣，拆毀她的城樓。我也要刮淨塵土，使她成為淨光的磐石。","notes":[]},{"n":5,"t":"她必在海中作曬網的地方，也必成為列國的擄物。這是主耶和華說的。","notes":[]},{"n":6,"t":"屬泰爾城邑的居民必被刀劍殺滅，他們就知道我是耶和華。」","notes":["原文是田間的眾女；八節同"]},{"n":7,"t":"主耶和華如此說：「我必使諸王之王的巴比倫王尼布甲尼撒率領馬匹車輛、馬兵、軍隊，和許多人民從北方來攻擊你泰爾。","notes":[]},{"n":8,"t":"他必用刀劍殺滅屬你城邑的居民，也必造臺築壘舉盾牌攻擊你。","notes":[]},{"n":9,"t":"他必安設撞城錘攻破你的牆垣，用鐵器拆毀你的城樓。","notes":[]},{"n":10,"t":"因他的馬匹眾多，塵土揚起遮蔽你。他進入你的城門，好像人進入已有破口之城。那時，你的牆垣必因騎馬的和戰車、輜重車的響聲震動。","notes":[]},{"n":11,"t":"他的馬蹄必踐踏你一切的街道；他必用刀殺戮你的居民。你堅固的柱子必倒在地上。","notes":["或譯：柱像"]},{"n":12,"t":"人必以你的財寶為擄物，以你的貨財為掠物，破壞你的牆垣，拆毀你華美的房屋，將你的石頭、木頭、塵土都拋在水中。","notes":[]},{"n":13,"t":"我必使你唱歌的聲音止息；人也不再聽見你彈琴的聲音。","notes":[]},{"n":14,"t":"我必使你成為淨光的磐石，作曬網的地方。你不得再被建造，因為這是主耶和華說的。」","notes":[]},{"n":15,"t":"主耶和華對泰爾如此說：「在你中間行殺戮，受傷之人唉哼的時候，因你傾倒的響聲，海島豈不都震動嗎？","notes":[]},{"n":16,"t":"那時靠海的君王必都下位，除去朝服，脫下花衣，披上戰兢，坐在地上，時刻發抖，為你驚駭。","notes":[]},{"n":17,"t":"他們必為你作起哀歌說：你這有名之城，素為航海之人居住，在海上為最堅固的；平日你和居民使一切住在那裏的人無不驚恐；現在何竟毀滅了？","notes":[]},{"n":18,"t":"如今在你這傾覆的日子，海島都必戰兢；海中的群島見你歸於無有就都驚惶。」","notes":[]},{"n":19,"t":"主耶和華如此說：「泰爾啊，我使你變為荒涼，如無人居住的城邑；又使深水漫過你，大水淹沒你。","notes":[]},{"n":20,"t":"那時，我要叫你下入陰府，與古時的人一同在地的深處、久已荒涼之地居住，使你不再有居民。我也要在活人之地顯榮耀。","notes":["我也<ins>.</ins>.榮耀：或譯在活人之地不再有榮耀"]},{"n":21,"t":"我必叫你令人驚恐，不再存留於世；人雖尋找你，卻永尋不見。這是主耶和華說的。」","notes":[]}]},"27":{"heading":"哀悼泰爾的輓歌","verses":[{"n":1,"t":"耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「人子啊，要為泰爾作起哀歌，","notes":[]},{"n":3,"t":"說：你居住海口，是眾民的商埠；你的交易通到許多的海島。主耶和華如此說：泰爾啊，你曾說：我是全然美麗的。","notes":[]},{"n":4,"t":"你的境界在海中，造你的使你全然美麗。","notes":[]},{"n":5,"t":"他們用示尼珥的松樹做你的一切板，用黎巴嫩的香柏樹做桅杆，","notes":[]},{"n":6,"t":"用巴珊的橡樹做你的槳，用象牙鑲嵌基提海島的黃楊木為坐板。","notes":["或譯：艙板"]},{"n":7,"t":"你的篷帆是用埃及繡花細麻布做的，可以做你的大旗；你的涼棚是用以利沙島的藍色、紫色布做的。","notes":[]},{"n":8,"t":"西頓和亞發的居民作你盪槳的。泰爾啊，你中間的智慧人作掌舵的。","notes":[]},{"n":9,"t":"迦巴勒的老者和聰明人都在你中間作補縫的；一切泛海的船隻和水手都在你中間經營交易的事。","notes":[]},{"n":10,"t":"「波斯人、路德人、弗人在你軍營中作戰士；他們在你中間懸掛盾牌和頭盔，彰顯你的尊榮。","notes":[]},{"n":11,"t":"亞發人和你的軍隊都在你四圍的牆上，你的望樓也有勇士；他們懸掛盾牌，成全你的美麗。","notes":[]},{"n":12,"t":"「他施人因你多有各類的財物，就作你的客商，拿銀、鐵、錫、鉛兌換你的貨物。","notes":[]},{"n":13,"t":"雅完人、土巴人、米設人都與你交易；他們用人口和銅器兌換你的貨物。","notes":[]},{"n":14,"t":"陀迦瑪族用馬和戰馬並騾子兌換你的貨物。","notes":[]},{"n":15,"t":"底但人與你交易，許多海島作你的碼頭；他們拿象牙、烏木與你兌換。","notes":["或譯：進貢"]},{"n":16,"t":"亞蘭人因你的工作很多，就作你的客商；他們用綠寶石、紫色布繡貨、細麻布、珊瑚、紅寶石兌換你的貨物。","notes":[]},{"n":17,"t":"猶大和以色列地的人都與你交易；他們用米匿的麥子、餅、蜜、油、乳香兌換你的貨物。","notes":[]},{"n":18,"t":"大馬士革人因你的工作很多，又因你多有各類的財物，就拿黑本酒和白羊毛與你交易。","notes":[]},{"n":19,"t":"威但人和雅完人拿紡成的線、亮鐵、桂皮、菖蒲兌換你的貨物。","notes":[]},{"n":20,"t":"底但人用高貴的毯子、鞍、屜與你交易。","notes":[]},{"n":21,"t":"阿拉伯人和基達的一切首領都作你的客商，用羊羔、公綿羊、公山羊與你交易。","notes":[]},{"n":22,"t":"示巴和拉瑪的商人與你交易，他們用各類上好的香料、各類的寶石，和黃金兌換你的貨物。","notes":[]},{"n":23,"t":"哈蘭人、干尼人、伊甸人、示巴的商人，和亞述人、基抹人與你交易。","notes":[]},{"n":24,"t":"這些商人以美好的貨物包在繡花藍色包袱內，又有華麗的衣服裝在香柏木的箱子裏，用繩捆著與你交易。","notes":[]},{"n":25,"t":"他施的船隻接連成幫為你運貨，你便在海中豐富極其榮華。","notes":[]},{"n":26,"t":"盪槳的已經把你盪到大水之處，東風在海中將你打破。","notes":[]},{"n":27,"t":"你的資財、物件、貨物、水手、掌舵的、補縫的、經營交易的，並你中間的戰士和人民，在你破壞的日子必都沉在海中。","notes":[]},{"n":28,"t":"你掌舵的呼號之聲一發，郊野都必震動。","notes":[]},{"n":29,"t":"凡盪槳的和水手，並一切泛海掌舵的，都必下船登岸。","notes":[]},{"n":30,"t":"他們必為你放聲痛哭，把塵土撒在頭上，在灰中打滾；","notes":[]},{"n":31,"t":"又為你使頭上光禿，用麻布束腰，號咷痛哭，苦苦悲哀。","notes":[]},{"n":32,"t":"他們哀號的時候，為你作起哀歌哀哭，說：有何城如泰爾？有何城如她在海中成為寂寞的呢？","notes":[]},{"n":33,"t":"你由海上運出貨物，就使許多國民充足；你以許多資財、貨物使地上的君王豐富。","notes":[]},{"n":34,"t":"你在深水中被海浪打破的時候，你的貨物和你中間的一切人民，就都沉下去了。","notes":[]},{"n":35,"t":"海島的居民為你驚奇；他們的君王都甚恐慌，面帶愁容。","notes":[]},{"n":36,"t":"各國民中的客商都向你發嘶聲；你令人驚恐，不再存留於世，直到永遠。」","notes":[]}]},"28":{"heading":"斥責泰爾王","verses":[{"n":1,"t":"耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你對泰爾君王說，主耶和華如此說：因你心裏高傲，說：我是神；我在海中坐神之位。你雖然居心自比神，也不過是人，並不是神！","notes":[]},{"n":3,"t":"看哪，你比但以理更有智慧，甚麼祕事都不能向你隱藏。","notes":[]},{"n":4,"t":"你靠自己的智慧聰明得了金銀財寶，收入庫中。","notes":[]},{"n":5,"t":"你靠自己的大智慧和貿易增添資財，又因資財心裏高傲。","notes":[]},{"n":6,"t":"所以主耶和華如此說：因你居心自比神，","notes":[]},{"n":7,"t":"我必使外邦人，就是列國中的強暴人臨到你這裏；他們必拔刀砍壞你用智慧得來的美物，褻瀆你的榮光。","notes":[]},{"n":8,"t":"他們必使你下坑；你必死在海中，與被殺的人一樣。","notes":[]},{"n":9,"t":"在殺你的人面前你還能說「我是神」嗎？其實你在殺害你的人手中，不過是人，並不是神。","notes":[]},{"n":10,"t":"你必死在外邦人手中，與未受割禮的人一樣，因為這是主耶和華說的。」","notes":["或譯：不潔；下同"]},{"n":11,"t":"耶和華的話臨到我說：","notes":[],"heads":["泰爾王的終局"]},{"n":12,"t":"「人子啊，你為泰爾王作起哀歌，說主耶和華如此說：你無所不備，智慧充足，全然美麗。","notes":[]},{"n":13,"t":"你曾在伊甸神的園中，佩戴各樣寶石，就是紅寶石、紅璧璽、金鋼石、水蒼玉、紅瑪瑙、碧玉、藍寶石、綠寶石、紅玉，和黃金；又有精美的鼓笛在你那裏，都是在你受造之日預備齊全的。","notes":[]},{"n":14,"t":"你是那受膏遮掩約櫃的基路伯；我將你安置在神的聖山上；你在發光如火的寶石中間往來。","notes":[]},{"n":15,"t":"你從受造之日所行的都完全，後來在你中間又察出不義。","notes":[]},{"n":16,"t":"因你貿易很多，就被強暴的事充滿，以致犯罪，所以我因你褻瀆聖地，就從神的山驅逐你。遮掩約櫃的基路伯啊，我已將你從發光如火的寶石中除滅。","notes":[]},{"n":17,"t":"你因美麗心中高傲，又因榮光敗壞智慧，我已將你摔倒在地，使你倒在君王面前，好叫他們目睹眼見。","notes":[]},{"n":18,"t":"你因罪孽眾多，貿易不公，就褻瀆你那裏的聖所。故此，我使火從你中間發出，燒滅你，使你在所有觀看的人眼前變為地上的爐灰。","notes":[]},{"n":19,"t":"各國民中，凡認識你的，都必為你驚奇。你令人驚恐，不再存留於世，直到永遠。」","notes":[]},{"n":20,"t":"耶和華的話臨到我說：","notes":[],"heads":["斥責西頓"]},{"n":21,"t":"「人子啊，你要向西頓預言攻擊她，","notes":[]},{"n":22,"t":"說主耶和華如此說：西頓哪，我與你為敵，我必在你中間得榮耀。我在你中間施行審判、顯為聖的時候，人就知道我是耶和華。","notes":[]},{"n":23,"t":"我必使瘟疫進入西頓，使血流在她街上。被殺的必在其中仆倒，四圍有刀劍臨到她，人就知道我是耶和華。」","notes":[]},{"n":24,"t":"「四圍恨惡以色列家的人，必不再向他們作刺人的荊棘，傷人的蒺藜，人就知道我是主耶和華。」","notes":[],"heads":["以色列要蒙福"]},{"n":25,"t":"主耶和華如此說：「我將分散在萬民中的以色列家招聚回來，向他們在列邦人眼前顯為聖的時候，他們就在我賜給我僕人雅各之地，仍然居住。","notes":[]},{"n":26,"t":"他們要在這地上安然居住。我向四圍恨惡他們的眾人施行審判以後，他們要蓋造房屋，栽種葡萄園，安然居住，就知道我是耶和華－他們的神。」","notes":[]}]},"29":{"heading":"斥責埃及","verses":[{"n":1,"t":"第十年十月十二日，耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要向埃及王法老預言攻擊他和埃及全地，","notes":[]},{"n":3,"t":"說主耶和華如此說：埃及王法老啊，我與你這臥在自己河中的大魚為敵。你曾說：這河是我的，是我為自己造的。","notes":[]},{"n":4,"t":"我－耶和華必用鉤子鉤住你的腮頰，又使江河中的魚貼住你的鱗甲；我必將你和所有貼住你鱗甲的魚，從江河中拉上來，","notes":[]},{"n":5,"t":"把你並江河中的魚都拋在曠野；你必倒在田間，不被收殮，不被掩埋。我已將你給地上野獸、空中飛鳥作食物。","notes":[]},{"n":6,"t":"「埃及一切的居民，因向以色列家成了蘆葦的杖，就知道我是耶和華。","notes":[]},{"n":7,"t":"他們用手持住你，你就斷折，傷了他們的肩；他們倚靠你，你就斷折，閃了他們的腰。","notes":[]},{"n":8,"t":"所以主耶和華如此說：我必使刀劍臨到你，從你中間將人與牲畜剪除。","notes":[]},{"n":9,"t":"埃及地必荒廢淒涼，他們就知道我是耶和華。「因為法老說：『這河是我的，是我所造的』，","notes":[]},{"n":10,"t":"所以我必與你並你的江河為敵，使埃及地，從色弗尼塔直到古實境界，全然荒廢淒涼。","notes":[]},{"n":11,"t":"人的腳、獸的蹄都不經過，四十年之久並無人居住。","notes":[]},{"n":12,"t":"我必使埃及地在荒涼的國中成為荒涼，使埃及城在荒廢的城中變為荒廢，共有四十年。我必將埃及人分散在列國，四散在列邦。」","notes":[]},{"n":13,"t":"主耶和華如此說：「滿了四十年，我必招聚分散在各國民中的埃及人。","notes":[]},{"n":14,"t":"我必叫埃及被擄的人回來，使他們歸回本地巴忒羅。在那裏必成為低微的國，","notes":[]},{"n":15,"t":"必為列國中最低微的，也不再自高於列國之上。我必減少他們，以致不再轄制列國。","notes":[]},{"n":16,"t":"埃及必不再作以色列家所倚靠的；以色列家仰望埃及人的時候，便思念罪孽。他們就知道我是主耶和華。」","notes":[]},{"n":17,"t":"二十七年正月初一日，耶和華的話臨到我說：","notes":[],"heads":["尼布甲尼撒要征服埃及"]},{"n":18,"t":"「人子啊，巴比倫王尼布甲尼撒使他的軍兵大大效勞，攻打泰爾，以致頭都光禿，肩都磨破；然而他和他的軍兵攻打泰爾，並沒有從那裏得甚麼酬勞。","notes":[]},{"n":19,"t":"所以主耶和華如此說：我必將埃及地賜給巴比倫王尼布甲尼撒；他必擄掠埃及群眾，搶其中的財為擄物，奪其中的貨為掠物，這就可以作他軍兵的酬勞。","notes":[]},{"n":20,"t":"我將埃及地賜給他，酬他所效的勞，因王與軍兵是為我勤勞。這是主耶和華說的。","notes":[]},{"n":21,"t":"「當那日，我必使以色列家的角發生，又必使你－以西結在他們中間得以開口；他們就知道我是耶和華。」","notes":[]}]},"30":{"heading":"耶和華要懲罰埃及","verses":[{"n":1,"t":"耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要發預言說，主耶和華如此說：哀哉這日！你們應當哭號。","notes":[]},{"n":3,"t":"因為耶和華的日子臨近，就是密雲之日，列國受罰之期。","notes":[]},{"n":4,"t":"必有刀劍臨到埃及；在埃及被殺之人仆倒的時候，古實人就有痛苦，人民必被擄掠，基址必被拆毀。","notes":[]},{"n":5,"t":"古實人、弗人、路德人、雜族的人民，並古巴人，以及同盟之地的人都要與埃及人一同倒在刀下。」","notes":["或譯：利比亞"]},{"n":6,"t":"耶和華如此說：扶助埃及的也必傾倒。埃及因勢力而有的驕傲必降低微；其中的人民，從色弗尼塔起必倒在刀下。這是主耶和華說的。","notes":["見二十九章十節"]},{"n":7,"t":"埃及地在荒涼的國中必成為荒涼；埃及城在荒廢的城中也變為荒廢。","notes":[]},{"n":8,"t":"我在埃及中使火著起；幫助埃及的，都被滅絕。那時，他們就知道我是耶和華。","notes":[]},{"n":9,"t":"「到那日，必有使者坐船，從我面前出去，使安逸無慮的古實人驚懼；必有痛苦臨到他們，好像埃及遭災的日子一樣。看哪，這事臨近了！","notes":[]},{"n":10,"t":"主耶和華如此說：我必藉巴比倫王尼布甲尼撒的手，除滅埃及眾人。","notes":[]},{"n":11,"t":"他和隨從他的人，就是列國中強暴的，必進來毀滅這地。他們必拔刀攻擊埃及，使遍地有被殺的人。","notes":[]},{"n":12,"t":"我必使江河乾涸，將地賣在惡人的手中；我必藉外邦人的手，使這地和其中所有的變為淒涼。這是我－耶和華說的。","notes":[]},{"n":13,"t":"主耶和華如此說：我必毀滅偶像，從挪弗除滅神像；必不再有君王出自埃及地。我要使埃及地的人懼怕。","notes":[]},{"n":14,"t":"我必使巴忒羅荒涼，在瑣安中使火著起，向挪施行審判。","notes":[]},{"n":15,"t":"我必將我的忿怒倒在埃及的保障上，就是訓上，並要剪除挪的眾人。","notes":[]},{"n":16,"t":"我必在埃及中使火著起；訓必大大痛苦；挪必被攻破；挪弗白日見仇敵。","notes":["或譯：終日"]},{"n":17,"t":"亞文和比伯實的少年人必倒在刀下；這些城的人必被擄掠。","notes":[]},{"n":18,"t":"我在答比匿折斷埃及的諸軛，使她因勢力而有的驕傲在其中止息。那時，日光必退去；至於這城，必有密雲遮蔽，其中的女子必被擄掠。","notes":[]},{"n":19,"t":"我必這樣向埃及施行審判，他們就知道我是耶和華。」","notes":[]},{"n":20,"t":"十一年正月初七日，耶和華的話臨到我說：","notes":[],"heads":["埃及王破碎的力量"]},{"n":21,"t":"「人子啊，我已打折埃及王法老的膀臂；沒有敷藥，也沒有用布纏好，使他有力持刀。","notes":[]},{"n":22,"t":"所以主耶和華如此說：看哪，我與埃及王法老為敵，必將他有力的膀臂和已打折的膀臂全行打斷，使刀從他手中墜落。","notes":[]},{"n":23,"t":"我必將埃及人分散在列國，四散在列邦。","notes":[]},{"n":24,"t":"我必使巴比倫王的膀臂有力，將我的刀交在他手中；卻要打斷法老的膀臂，他就在巴比倫王面前唉哼，如同受死傷的人一樣。","notes":[]},{"n":25,"t":"我必扶持巴比倫王的膀臂，法老的膀臂卻要下垂；我將我的刀交在巴比倫王手中，他必舉刀攻擊埃及地，他們就知道我是耶和華。","notes":[]},{"n":26,"t":"我必將埃及人分散在列國，四散在列邦；他們就知道我是耶和華。」","notes":[]}]},"31":{"heading":"以香柏樹比擬埃及","verses":[{"n":1,"t":"十一年三月初一日，耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要向埃及王法老和他的眾人說：在威勢上誰能與你相比呢？","notes":[]},{"n":3,"t":"亞述王曾如黎巴嫩中的香柏樹，枝條榮美，影密如林，極其高大，樹尖插入雲中。","notes":[]},{"n":4,"t":"眾水使它生長；深水使它長大。所栽之地有江河圍流，汊出的水道延到田野諸樹。","notes":[]},{"n":5,"t":"所以它高大超過田野諸樹；發旺的時候，枝子繁多，因得大水之力枝條長長。","notes":[]},{"n":6,"t":"空中的飛鳥都在枝子上搭窩；田野的走獸都在枝條下生子；所有大國的人民都在它蔭下居住。","notes":[]},{"n":7,"t":"樹大條長，成為榮美，因為根在眾水之旁。","notes":[]},{"n":8,"t":"神園中的香柏樹不能遮蔽它；松樹不及它的枝子；楓樹不及它的枝條；神園中的樹都沒有它榮美。","notes":[]},{"n":9,"t":"我使它的枝條蕃多，成為榮美，以致神伊甸園中的樹都嫉妒它。」","notes":[]},{"n":10,"t":"所以主耶和華如此說：「因它高大，樹尖插入雲中，心驕氣傲，","notes":[]},{"n":11,"t":"我就必將它交給列國中大有威勢的人；他必定辦它。我因它的罪惡，已經驅逐它。","notes":[]},{"n":12,"t":"外邦人，就是列邦中強暴的，將它砍斷棄掉。它的枝條落在山間和一切谷中，它的枝子折斷，落在地的一切河旁。地上的眾民已經走去，離開它的蔭下。","notes":[]},{"n":13,"t":"空中的飛鳥都要宿在這敗落的樹上，田野的走獸都要臥在它的枝條下，","notes":[]},{"n":14,"t":"好使水旁的諸樹不因高大而自尊，也不將樹尖插入雲中，並且那些得水滋潤、有勢力的，也不得高大自立。因為它們在世人中，和下坑的人都被交與死亡，到陰府去了。」","notes":[]},{"n":15,"t":"主耶和華如此說：「它下陰間的那日，我便使人悲哀。我為它遮蓋深淵，使江河凝結，大水停流；我也使黎巴嫩為它悽慘，田野的諸樹都因它發昏。","notes":[]},{"n":16,"t":"我將它扔到陰間，與下坑的人一同下去。那時，列國聽見它墜落的響聲就都震動，並且伊甸的一切樹－就是黎巴嫩得水滋潤、最佳最美的樹－都在陰府受了安慰。","notes":[]},{"n":17,"t":"它們也與它同下陰間，到被殺的人那裏。它們曾作它的膀臂，在列國中它的蔭下居住。","notes":[]},{"n":18,"t":"在這樣榮耀威勢上，在伊甸園諸樹中，誰能與你相比呢？然而你要與伊甸的諸樹一同下到陰府，在未受割禮的人中，與被殺的人一同躺臥。「法老和他的群眾乃是如此。這是主耶和華說的。」","notes":[]}]},"32":{"heading":"以鱷魚比擬埃及王","verses":[{"n":1,"t":"十二年十二月初一日，耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要為埃及王法老作哀歌，說：從前你在列國中，如同少壯獅子；現在你卻像海中的大魚。你衝出江河，用爪攪動諸水，使江河渾濁。","notes":[]},{"n":3,"t":"主耶和華如此說：我必用多國的人民，將我的網撒在你身上，把你拉上來。","notes":[]},{"n":4,"t":"我必將你丟在地上，拋在田野，使空中的飛鳥都落在你身上，使遍地的野獸吃你得飽。","notes":[]},{"n":5,"t":"我必將你的肉丟在山間，用你高大的屍首填滿山谷。","notes":[]},{"n":6,"t":"我又必用你的血澆灌你所游泳之地，漫過山頂；河道都必充滿。","notes":[]},{"n":7,"t":"我將你撲滅的時候，要把天遮蔽，使眾星昏暗，以密雲遮掩太陽，月亮也不放光。","notes":[]},{"n":8,"t":"我必使天上的亮光都在你以上變為昏暗，使你的地上黑暗。這是主耶和華說的。","notes":[]},{"n":9,"t":"「我使你敗亡的風聲傳到你所不認識的各國。那時，我必使多民的心因你愁煩。","notes":[]},{"n":10,"t":"我在許多國民和君王面前向你掄我的刀，國民就必因你驚奇，君王也必因你極其恐慌。在你仆倒的日子，他們各人為自己的性命時刻戰兢。」","notes":[]},{"n":11,"t":"主耶和華如此說：「巴比倫王的刀必臨到你。","notes":[]},{"n":12,"t":"我必藉勇士的刀使你的眾民仆倒；這勇士都是列國中強暴的。他們必使埃及的驕傲歸於無有；埃及的眾民必被滅絕。","notes":[]},{"n":13,"t":"我必從埃及多水旁除滅所有的走獸；人腳獸蹄必不再攪渾這水。","notes":[]},{"n":14,"t":"那時，我必使埃及河澄清，江河像油緩流。這是主耶和華說的。","notes":[]},{"n":15,"t":"我使埃及地變為荒廢淒涼；這地缺少從前所充滿的，又擊殺其中一切的居民。那時，他們就知道我是耶和華。","notes":[]},{"n":16,"t":"「人必用這哀歌去哀哭，列國的女子為埃及和她的群眾也必以此悲哀。這是主耶和華說的。」","notes":[]},{"n":17,"t":"十二年十二月十五日，耶和華的話臨到我說：","notes":[],"heads":["為埃及哀號"]},{"n":18,"t":"「人子啊，你要為埃及群眾哀號，又要將埃及和有名之國的女子，並下坑的人，一同扔到陰府去。","notes":[]},{"n":19,"t":"你埃及的美麗勝過誰呢？你下去與未受割禮的人一同躺臥吧！","notes":[]},{"n":20,"t":"他們必在被殺的人中仆倒。她被交給刀劍，要把她和她的群眾拉去。","notes":[]},{"n":21,"t":"強盛的勇士要在陰間對埃及王和幫助他的說話；他們是未受割禮被殺的人，已經下去，躺臥不動。","notes":[]},{"n":22,"t":"「亞述和她的眾民都在那裏，她民的墳墓在她四圍；他們都是被殺倒在刀下的。","notes":[]},{"n":23,"t":"他們的墳墓在坑中極深之處。她的眾民在她墳墓的四圍，都是被殺倒在刀下的；他們曾在活人之地使人驚恐。","notes":[]},{"n":24,"t":"「以攔也在那裏，她的群眾在她墳墓的四圍，都是被殺倒在刀下、未受割禮而下陰府的；他們曾在活人之地使人驚恐，並且與下坑的人一同擔當羞辱。","notes":[]},{"n":25,"t":"人給她和她的群眾在被殺的人中設立床榻。她民的墳墓在她四圍，他們都是未受割禮被刀殺的；他們曾在活人之地使人驚恐，並且與下坑的人一同擔當羞辱。以攔已經放在被殺的人中。","notes":[]},{"n":26,"t":"「米設、土巴，和她們的群眾都在那裏。她民的墳墓在她四圍，他們都是未受割禮被刀殺的；他們曾在活人之地使人驚恐。","notes":[]},{"n":27,"t":"他們不得與那未受割禮仆倒的勇士一同躺臥；這些勇士帶著兵器下陰間，頭枕刀劍，骨頭上有本身的罪孽；他們曾在活人之地使勇士驚恐。","notes":[]},{"n":28,"t":"「法老啊，你必在未受割禮的人中敗壞，與那些被殺的人一同躺臥。","notes":[]},{"n":29,"t":"「以東也在那裏。她君王和一切首領雖然仗著勢力，還是放在被殺的人中；他們必與未受割禮的和下坑的人一同躺臥。","notes":[]},{"n":30,"t":"「在那裏有北方的眾王子和一切西頓人，都與被殺的人下去。他們雖然仗著勢力使人驚恐，還是蒙羞。他們未受割禮，和被刀殺的一同躺臥，與下坑的人一同擔當羞辱。","notes":[]},{"n":31,"t":"「法老看見他們，便為他被殺的軍隊受安慰。這是主耶和華說的。","notes":[]},{"n":32,"t":"我任憑法老在活人之地使人驚恐，法老和他的群眾必放在未受割禮和被殺的人中。這是主耶和華說的。」","notes":[]}]},"33":{"heading":"神指派以西結作守望者","verses":[{"n":1,"t":"耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要告訴本國的子民說：我使刀劍臨到哪一國，那一國的民從他們中間選立一人為守望的。","notes":[]},{"n":3,"t":"他見刀劍臨到那地，若吹角警戒眾民，","notes":[]},{"n":4,"t":"凡聽見角聲不受警戒的，刀劍若來除滅了他，他的罪就必歸到自己的頭上。","notes":["原文是血"]},{"n":5,"t":"他聽見角聲，不受警戒，他的罪必歸到自己的身上；他若受警戒，便是救了自己的性命。","notes":[]},{"n":6,"t":"倘若守望的人見刀劍臨到，不吹角，以致民不受警戒，刀劍來殺了他們中間的一個人，他雖然死在罪孽之中，我卻要向守望的人討他喪命的罪。","notes":["原文是血"]},{"n":7,"t":"「人子啊，我照樣立你作以色列家守望的人。所以你要聽我口中的話，替我警戒他們。","notes":[]},{"n":8,"t":"我對惡人說：『惡人哪，你必要死！』你－以西結若不開口警戒惡人，使他離開所行的道，這惡人必死在罪孽之中，我卻要向你討他喪命的罪。","notes":["原文是血"]},{"n":9,"t":"倘若你警戒惡人轉離所行的道，他仍不轉離，他必死在罪孽之中，你卻救自己脫離了罪。」","notes":[]},{"n":10,"t":"「人子啊，你要對以色列家說：『你們常說：我們的過犯罪惡在我們身上，我們必因此消滅，怎能存活呢？』","notes":[],"heads":["個人的責任"]},{"n":11,"t":"你對他們說，主耶和華說：我指著我的永生起誓，我斷不喜悅惡人死亡，惟喜悅惡人轉離所行的道而活。以色列家啊，你們轉回，轉回吧！離開惡道，何必死亡呢？","notes":[]},{"n":12,"t":"人子啊，你要對本國的人民說：義人的義，在犯罪之日不能救他；至於惡人的惡，在他轉離惡行之日也不能使他傾倒；義人在犯罪之日也不能因他的義存活。","notes":[]},{"n":13,"t":"我對義人說：『你必定存活！』他若倚靠他的義而作罪孽，他所行的義都不被記念。他必因所作的罪孽死亡。","notes":[]},{"n":14,"t":"再者，我對惡人說：『你必定死亡！』他若轉離他的罪，行正直與合理的事：","notes":[]},{"n":15,"t":"還人的當頭和所搶奪的，遵行生命的律例，不作罪孽，他必定存活，不致死亡。","notes":[]},{"n":16,"t":"他所犯的一切罪必不被記念。他行了正直與合理的事，必定存活。","notes":[]},{"n":17,"t":"「你本國的子民還說：『主的道不公平。』其實他們的道不公平。","notes":[]},{"n":18,"t":"義人轉離他的義而作罪孽，就必因此死亡。","notes":[]},{"n":19,"t":"惡人轉離他的惡，行正直與合理的事，就必因此存活。","notes":[]},{"n":20,"t":"你們還說：『主的道不公平。』以色列家啊，我必按你們各人所行的審判你們。」","notes":[]},{"n":21,"t":"我們被擄之後十二年十月初五日，有人從耶路撒冷逃到我這裏，說：「城已攻破。」","notes":[],"heads":["耶路撒冷陷落的消息"]},{"n":22,"t":"逃來的人未到前一日的晚上，耶和華的靈降在我身上，開我的口。到第二日早晨，那人來到我這裏，我口就開了，不再緘默。","notes":["原文是手"]},{"n":23,"t":"耶和華的話臨到我說：","notes":[],"heads":["百姓的罪"]},{"n":24,"t":"「人子啊，住在以色列荒廢之地的人說：『亞伯拉罕獨自一人能得這地為業，我們人數眾多，這地更是給我們為業的。』","notes":[]},{"n":25,"t":"所以你要對他們說，主耶和華如此說：你們吃帶血的物，仰望偶像，並且殺人流血，你們還能得這地為業嗎？","notes":[]},{"n":26,"t":"你們倚仗自己的刀劍行可憎的事，人人玷污鄰舍的妻，你們還能得這地為業嗎？","notes":[]},{"n":27,"t":"你要對他們這樣說，主耶和華如此說：我指著我的永生起誓，在荒場中的，必倒在刀下；在田野間的，必交給野獸吞吃；在保障和洞裏的，必遭瘟疫而死。","notes":[]},{"n":28,"t":"我必使這地荒涼，令人驚駭；她因勢力而有的驕傲也必止息。以色列的山都必荒涼，無人經過。","notes":[]},{"n":29,"t":"我因他們所行一切可憎的事使地荒涼，令人驚駭。那時，他們就知道我是耶和華。」","notes":[]},{"n":30,"t":"「人子啊，你本國的子民在牆垣旁邊、在房屋門口談論你。弟兄對弟兄彼此說：『來吧！聽聽有甚麼話從耶和華而出。』","notes":[],"heads":["先知傳講信息的結果"]},{"n":31,"t":"他們來到你這裏如同民來聚會，坐在你面前彷彿是我的民。他們聽你的話卻不去行；因為他們的口多顯愛情，心卻追隨財利。","notes":[]},{"n":32,"t":"他們看你如善於奏樂、聲音幽雅之人所唱的雅歌，他們聽你的話卻不去行。","notes":[]},{"n":33,"t":"看哪，所說的快要應驗；應驗了，他們就知道在他們中間有了先知。」","notes":[]}]},"34":{"heading":"以色列的牧人","verses":[{"n":1,"t":"耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要向以色列的牧人發預言，攻擊他們，說，主耶和華如此說：禍哉！以色列的牧人只知牧養自己。牧人豈不當牧養群羊嗎？","notes":[]},{"n":3,"t":"你們吃脂油、穿羊毛、宰肥壯的，卻不牧養群羊。","notes":[]},{"n":4,"t":"瘦弱的，你們沒有養壯；有病的，你們沒有醫治；受傷的，你們沒有纏裹；被逐的，你們沒有領回；失喪的，你們沒有尋找；但用強暴嚴嚴地轄制。","notes":[]},{"n":5,"t":"因無牧人，羊就分散；既分散，便作了一切野獸的食物。","notes":[]},{"n":6,"t":"我的羊在諸山間、在各高岡上流離，在全地上分散，無人去尋，無人去找。","notes":[]},{"n":7,"t":"「所以，你們這些牧人要聽耶和華的話。","notes":[]},{"n":8,"t":"主耶和華說：我指著我的永生起誓，我的羊因無牧人就成為掠物，也作了一切野獸的食物。我的牧人不尋找我的羊；這些牧人只知牧養自己，並不牧養我的羊。","notes":[]},{"n":9,"t":"所以你們這些牧人要聽耶和華的話。","notes":[]},{"n":10,"t":"主耶和華如此說：我必與牧人為敵，必向他們的手追討我的羊，使他們不再牧放群羊；牧人也不再牧養自己。我必救我的羊脫離他們的口，不再作他們的食物。」","notes":[]},{"n":11,"t":"「主耶和華如此說：看哪，我必親自尋找我的羊，將牠們尋見。","notes":[],"heads":["好牧人"]},{"n":12,"t":"牧人在羊群四散的日子怎樣尋找他的羊，我必照樣尋找我的羊。這些羊在密雲黑暗的日子散到各處，我必從那裏救回牠們來。","notes":[]},{"n":13,"t":"我必從萬民中領出牠們，從各國內聚集牠們，引導牠們歸回故土，也必在以色列山上－一切溪水旁邊、境內一切可居之處－牧養牠們。","notes":[]},{"n":14,"t":"我必在美好的草場牧養牠們。牠們的圈必在以色列高處的山上，牠們必在佳美之圈中躺臥，也在以色列山肥美的草場吃草。","notes":[]},{"n":15,"t":"主耶和華說：我必親自作我羊的牧人，使牠們得以躺臥。","notes":[]},{"n":16,"t":"失喪的，我必尋找；被逐的，我必領回；受傷的，我必纏裹；有病的，我必醫治；只是肥的壯的，我必除滅，也要秉公牧養牠們。","notes":[]},{"n":17,"t":"「我的羊群哪，論到你們，主耶和華如此說：我必在羊與羊中間、公綿羊與公山羊中間施行判斷。","notes":[]},{"n":18,"t":"你們這些肥壯的羊，在美好的草場吃草還以為小事嗎？剩下的草，你們竟用蹄踐踏了；你們喝清水，剩下的水，你們竟用蹄攪渾了。","notes":[]},{"n":19,"t":"至於我的羊，只得吃你們所踐踏的，喝你們所攪渾的。","notes":[]},{"n":20,"t":"「所以，主耶和華如此說：我必在肥羊和瘦羊中間施行判斷。","notes":[]},{"n":21,"t":"因為你們用脅用肩擁擠一切瘦弱的，又用角牴觸，以致使牠們四散。","notes":[]},{"n":22,"t":"所以，我必拯救我的群羊不再作掠物；我也必在羊和羊中間施行判斷。","notes":[]},{"n":23,"t":"我必立一牧人照管他們，牧養他們，就是我的僕人大衛。他必牧養他們，作他們的牧人。","notes":[]},{"n":24,"t":"我－耶和華必作他們的神，我的僕人大衛必在他們中間作王。這是耶和華說的。","notes":[]},{"n":25,"t":"「我必與他們立平安的約，使惡獸從境內斷絕，他們就必安居在曠野，躺臥在林中。","notes":[]},{"n":26,"t":"我必使他們與我山的四圍成為福源，我也必叫時雨落下，必有福如甘霖而降。","notes":[]},{"n":27,"t":"田野的樹必結果，地也必有出產；他們必在故土安然居住。我折斷他們所負的軛，救他們脫離那以他們為奴之人的手；那時，他們就知道我是耶和華。","notes":[]},{"n":28,"t":"他們必不再作外邦人的掠物，地上的野獸也不再吞吃他們；卻要安然居住，無人驚嚇。","notes":[]},{"n":29,"t":"我必給他們興起有名的植物；他們在境內不再為饑荒所滅，也不再受外邦人的羞辱，","notes":[]},{"n":30,"t":"必知道我、耶和華－他們的神是與他們同在的，並知道他們－以色列家是我的民。這是主耶和華說的。","notes":[]},{"n":31,"t":"你們作我的羊，我草場上的羊，乃是以色列人，我也是你們的神。這是主耶和華說的。」","notes":[]}]},"35":{"heading":"神懲罰以東","verses":[{"n":1,"t":"耶和華的話又臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要面向西珥山發預言，攻擊它，","notes":[]},{"n":3,"t":"對它說，主耶和華如此說：西珥山哪，我與你為敵，必向你伸手攻擊你，使你荒涼，令人驚駭。","notes":[]},{"n":4,"t":"我必使你的城邑變為荒場，成為淒涼。你就知道我是耶和華。","notes":[]},{"n":5,"t":"因為你永懷仇恨，在以色列人遭災、罪孽到了盡頭的時候，將他們交與刀劍，","notes":[]},{"n":6,"t":"所以主耶和華說：我指著我的永生起誓，我必使你遭遇流血的報應，罪必追趕你；你既不恨惡殺人流血，所以這罪必追趕你。","notes":["原文是血；本節同"]},{"n":7,"t":"我必使西珥山荒涼，令人驚駭，來往經過的人我必剪除。","notes":[]},{"n":8,"t":"我必使西珥山滿有被殺的人。被刀殺的，必倒在你小山和山谷，並一切的溪水中。","notes":[]},{"n":9,"t":"我必使你永遠荒涼，使你的城邑無人居住，你的民就知道我是耶和華。","notes":[]},{"n":10,"t":"「因為你曾說：『這二國這二邦必歸於我，我必得為業』（其實耶和華仍在那裏），","notes":[]},{"n":11,"t":"所以主耶和華說：我指著我的永生起誓，我必照你的怒氣和你從仇恨中向他們所發的嫉妒待你。我審判你的時候，必將自己顯明在他們中間。","notes":[]},{"n":12,"t":"你也必知道我－耶和華聽見了你的一切毀謗，就是你攻擊以色列山的話，說：『這些山荒涼，是歸我們吞滅的。』","notes":[]},{"n":13,"t":"你們也用口向我誇大，增添與我反對的話，我都聽見了。","notes":[]},{"n":14,"t":"主耶和華如此說：全地歡樂的時候，我必使你荒涼。","notes":[]},{"n":15,"t":"你怎樣因以色列家的地業荒涼而喜樂，我必照你所行的待你。西珥山哪，你和以東全地必都荒涼。你們就知道我是耶和華。」","notes":[]}]},"36":{"heading":"神賜福給以色列","verses":[{"n":1,"t":"「人子啊，你要對以色列山發預言說：以色列山哪，要聽耶和華的話。","notes":[]},{"n":2,"t":"主耶和華如此說：因仇敵說：『阿哈！這永久的山岡都歸我們為業了！』","notes":[]},{"n":3,"t":"所以要發預言說，主耶和華如此說：因為敵人使你荒涼，四圍吞吃，好叫你歸與其餘的外邦人為業，並且多嘴多舌的人提起你來，百姓也說你有臭名。","notes":[]},{"n":4,"t":"故此，以色列山要聽主耶和華的話。大山小岡、水溝山谷、荒廢之地、被棄之城，為四圍其餘的外邦人所佔據、所譏刺的，","notes":[]},{"n":5,"t":"主耶和華對你們如此說：我真發憤恨如火，責備那其餘的外邦人和以東的眾人。他們快樂滿懷，心存恨惡，將我的地歸自己為業，又看為被棄的掠物。","notes":[]},{"n":6,"t":"所以，你要指著以色列地說預言，對大山小岡、水溝山谷說，主耶和華如此說：我發憤恨和忿怒說，因你們曾受外邦人的羞辱，","notes":[]},{"n":7,"t":"所以我起誓說：你們四圍的外邦人總要擔當自己的羞辱。這是主耶和華說的。","notes":[]},{"n":8,"t":"「以色列山哪，你必發枝條，為我的民以色列結果子，因為他們快要來到。","notes":[]},{"n":9,"t":"看哪，我是幫助你的，也必向你轉意，使你得以耕種。","notes":[]},{"n":10,"t":"我必使以色列全家的人數在你上面增多，城邑有人居住，荒場再被建造。","notes":[]},{"n":11,"t":"我必使人和牲畜在你上面加增；他們必生養眾多。我要使你照舊有人居住，並要賜福與你比先前更多，你就知道我是耶和華。","notes":[]},{"n":12,"t":"我必使人，就是我的民以色列，行在你上面。他們必得你為業；你也不再使他們喪子。","notes":[]},{"n":13,"t":"主耶和華如此說：因為人對你說：『你是吞吃人的，又使國民喪子』，","notes":[]},{"n":14,"t":"所以主耶和華說：你必不再吞吃人，也不再使國民喪子。","notes":[]},{"n":15,"t":"我使你不再聽見各國的羞辱，不再受萬民的辱罵，也不再使國民絆跌。這是主耶和華說的。」","notes":[]},{"n":16,"t":"耶和華的話又臨到我說：","notes":[],"heads":["以色列的新生活"]},{"n":17,"t":"「人子啊，以色列家住在本地的時候，在行動作為上玷污那地。他們的行為在我面前，好像正在經期的婦人那樣污穢。","notes":[]},{"n":18,"t":"所以我因他們在那地上流人的血，又因他們以偶像玷污那地，就把我的忿怒傾在他們身上。","notes":[]},{"n":19,"t":"我將他們分散在列國，四散在列邦，按他們的行動作為懲罰他們。","notes":[]},{"n":20,"t":"他們到了所去的列國，就使我的聖名被褻瀆；因為人談論他們說，這是耶和華的民，是從耶和華的地出來的。","notes":[]},{"n":21,"t":"我卻顧惜我的聖名，就是以色列家在所到的列國中所褻瀆的。","notes":[]},{"n":22,"t":"「所以，你要對以色列家說，主耶和華如此說：以色列家啊，我行這事不是為你們，乃是為我的聖名，就是在你們到的列國中所褻瀆的。","notes":[]},{"n":23,"t":"我要使我的大名顯為聖；這名在列國中已被褻瀆，就是你們在他們中間所褻瀆的。我在他們眼前，在你們身上顯為聖的時候，他們就知道我是耶和華。這是主耶和華說的。","notes":[]},{"n":24,"t":"我必從各國收取你們，從列邦聚集你們，引導你們歸回本地。","notes":[]},{"n":25,"t":"我必用清水灑在你們身上，你們就潔淨了。我要潔淨你們，使你們脫離一切的污穢，棄掉一切的偶像。","notes":[]},{"n":26,"t":"我也要賜給你們一個新心，將新靈放在你們裏面，又從你們的肉體中除掉石心，賜給你們肉心。","notes":[]},{"n":27,"t":"我必將我的靈放在你們裏面，使你們順從我的律例，謹守遵行我的典章。","notes":[]},{"n":28,"t":"你們必住在我所賜給你們列祖之地。你們要作我的子民，我要作你們的神。","notes":[]},{"n":29,"t":"我必救你們脫離一切的污穢，也必命五穀豐登，不使你們遭遇饑荒。","notes":[]},{"n":30,"t":"我必使樹木多結果子，田地多出土產，好叫你們不再因饑荒受外邦人的譏誚。","notes":[]},{"n":31,"t":"那時，你們必追想你們的惡行和你們不善的作為，就因你們的罪孽和可憎的事厭惡自己。","notes":[]},{"n":32,"t":"主耶和華說：你們要知道，我這樣行不是為你們。以色列家啊，當為自己的行為抱愧蒙羞。","notes":[]},{"n":33,"t":"「主耶和華如此說：我潔淨你們，使你們脫離一切罪孽的日子，必使城邑有人居住，荒場再被建造。","notes":[]},{"n":34,"t":"過路的人雖看為荒廢之地，現今這荒廢之地仍得耕種。","notes":[]},{"n":35,"t":"他們必說：『這先前為荒廢之地，現在成如伊甸園；這荒廢淒涼、毀壞的城邑現在堅固有人居住。』","notes":[]},{"n":36,"t":"那時，在你們四圍其餘的外邦人必知道我－耶和華修造那毀壞之處，培植那荒廢之地。我－耶和華說過，也必成就。","notes":[]},{"n":37,"t":"「主耶和華如此說：我要加增以色列家的人數，多如羊群。他們必為這事向我求問，我要給他們成就。","notes":[]},{"n":38,"t":"耶路撒冷在守節作祭物所獻的羊群怎樣多，照樣，荒涼的城邑必被人群充滿。他們就知道我是耶和華。」","notes":[]}]},"37":{"heading":"枯骨的復甦","verses":[{"n":1,"t":"耶和華的靈降在我身上。耶和華藉他的靈帶我出去，將我放在平原中；這平原遍滿骸骨。","notes":["原文是手"]},{"n":2,"t":"他使我從骸骨的四圍經過，誰知在平原的骸骨甚多，而且極其枯乾。","notes":[]},{"n":3,"t":"他對我說：「人子啊，這些骸骨能復活嗎？」我說：「主耶和華啊，你是知道的。」","notes":[]},{"n":4,"t":"他又對我說：「你向這些骸骨發預言說：枯乾的骸骨啊，要聽耶和華的話。","notes":[]},{"n":5,"t":"主耶和華對這些骸骨如此說：『我必使氣息進入你們裏面，你們就要活了。","notes":[]},{"n":6,"t":"我必給你們加上筋，使你們長肉，又將皮遮蔽你們，使氣息進入你們裏面，你們就要活了；你們便知道我是耶和華。』」","notes":[]},{"n":7,"t":"於是，我遵命說預言。正說預言的時候，不料，有響聲，有地震；骨與骨互相聯絡。","notes":[]},{"n":8,"t":"我觀看，見骸骨上有筋，也長了肉，又有皮遮蔽其上，只是還沒有氣息。","notes":[]},{"n":9,"t":"主對我說：「人子啊，你要發預言，向風發預言，說主耶和華如此說：氣息啊，要從四方而來，吹在這些被殺的人身上，使他們活了。」","notes":["原文是風"]},{"n":10,"t":"於是我遵命說預言，氣息就進入骸骨，骸骨便活了，並且站起來，成為極大的軍隊。","notes":[]},{"n":11,"t":"主對我說：「人子啊，這些骸骨就是以色列全家。他們說：『我們的骨頭枯乾了，我們的指望失去了，我們滅絕淨盡了。』","notes":[]},{"n":12,"t":"所以你要發預言對他們說，主耶和華如此說：『我的民哪，我必開你們的墳墓，使你們從墳墓中出來，領你們進入以色列地。","notes":[]},{"n":13,"t":"我的民哪，我開你們的墳墓，使你們從墳墓中出來，你們就知道我是耶和華。","notes":[]},{"n":14,"t":"我必將我的靈放在你們裏面，你們就要活了。我將你們安置在本地，你們就知道我－耶和華如此說，也如此成就了。這是耶和華說的。』」","notes":[]},{"n":15,"t":"耶和華的話又臨到我說：","notes":[],"heads":["猶大和以色列組成聯合王國"]},{"n":16,"t":"「人子啊，你要取一根木杖，在其上寫『為猶大和他的同伴以色列人』；又取一根木杖，在其上寫『為約瑟，就是為以法蓮，又為他的同伴以色列全家』。","notes":[]},{"n":17,"t":"你要使這兩根木杖接連為一，在你手中成為一根。","notes":[]},{"n":18,"t":"你本國的子民問你說：『這是甚麼意思？你不指示我們嗎？』","notes":[]},{"n":19,"t":"你就對他們說：『主耶和華如此說：我要將約瑟和他同伴以色列支派的杖，就是那在以法蓮手中的，與猶大的杖一同接連為一，在我手中成為一根。』","notes":[]},{"n":20,"t":"你所寫的那兩根杖要在他們眼前拿在手中，","notes":[]},{"n":21,"t":"要對他們說，主耶和華如此說：我要將以色列人從他們所到的各國收取，又從四圍聚集他們，引導他們歸回本地。","notes":[]},{"n":22,"t":"我要使他們在那地，在以色列山上成為一國，有一王作他們眾民的王。他們不再為二國，決不再分為二國；","notes":[]},{"n":23,"t":"也不再因偶像和可憎的物，並一切的罪過玷污自己。我卻要救他們出離一切的住處，就是他們犯罪的地方；我要潔淨他們，如此，他們要作我的子民，我要作他們的神。","notes":[]},{"n":24,"t":"「我的僕人大衛必作他們的王；眾民必歸一個牧人。他們必順從我的典章，謹守遵行我的律例。","notes":[]},{"n":25,"t":"他們必住在我賜給我僕人雅各的地上，就是你們列祖所住之地。他們和他們的子孫，並子孫的子孫，都永遠住在那裏。我的僕人大衛必作他們的王，直到永遠。","notes":[]},{"n":26,"t":"並且我要與他們立平安的約，作為永約。我也要將他們安置在本地，使他們的人數增多，又在他們中間設立我的聖所，直到永遠。","notes":[]},{"n":27,"t":"我的居所必在他們中間；我要作他們的神，他們要作我的子民。","notes":[]},{"n":28,"t":"我的聖所在以色列人中間直到永遠，外邦人就必知道我是叫以色列成為聖的耶和華。」","notes":[]}]},"38":{"heading":"歌革－耶和華的工具","verses":[{"n":1,"t":"耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「人子啊，你要面向瑪各地的歌革，就是羅施、米設、土巴的王發預言攻擊他，","notes":[]},{"n":3,"t":"說主耶和華如此說：羅施、米設、土巴的王歌革啊，我與你為敵。","notes":[]},{"n":4,"t":"我必用鉤子鉤住你的腮頰，調轉你，將你和你的軍兵、馬匹、馬兵帶出來，都披掛整齊，成了大隊，有大小盾牌，各拿刀劍。","notes":[]},{"n":5,"t":"波斯人、古實人，和弗人，各拿盾牌，頭上戴盔；","notes":["又作利比亞人"]},{"n":6,"t":"歌篾人和他的軍隊，北方極處的陀迦瑪族和他的軍隊，這許多國的民都同著你。","notes":[]},{"n":7,"t":"「那聚集到你這裏的各隊都當準備；你自己也要準備，作他們的大帥。","notes":[]},{"n":8,"t":"過了多日，你必被差派。到末後之年，你必來到脫離刀劍從列國收回之地，到以色列常久荒涼的山上；但那從列國中招聚出來的必在其上安然居住。","notes":[]},{"n":9,"t":"你和你的軍隊，並同著你許多國的民，必如暴風上來，如密雲遮蓋地面。」","notes":[]},{"n":10,"t":"主耶和華如此說：「到那時，你心必起意念，圖謀惡計，","notes":[]},{"n":11,"t":"說：『我要上那無城牆的鄉村，我要到那安靜的民那裏，他們都沒有城牆，無門、無閂，安然居住。","notes":[]},{"n":12,"t":"我去要搶財為擄物，奪貨為掠物，反手攻擊那從前荒涼、現在有人居住之地，又攻擊那住世界中間、從列國招聚、得了牲畜財貨的民。』","notes":[]},{"n":13,"t":"示巴人、底但人、他施的客商，和其間的少壯獅子都必問你說：『你來要搶財為擄物嗎？你聚集軍隊要奪貨為掠物嗎？要奪取金銀，擄去牲畜、財貨嗎？要搶奪許多財寶為擄物嗎？』","notes":[]},{"n":14,"t":"「人子啊，你要因此發預言，對歌革說，主耶和華如此說：到我民以色列安然居住之日，你豈不知道嗎？","notes":[]},{"n":15,"t":"你必從本地，從北方的極處率領許多國的民來，都騎著馬，乃一大隊極多的軍兵。","notes":[]},{"n":16,"t":"歌革啊，你必上來攻擊我的民以色列，如密雲遮蓋地面。末後的日子，我必帶你來攻擊我的地，到我在外邦人眼前，在你身上顯為聖的時候，好叫他們認識我。","notes":[]},{"n":17,"t":"主耶和華如此說：我在古時藉我的僕人以色列的先知所說的，就是你嗎？當日他們多年預言我必帶你來攻擊以色列人。」","notes":[]},{"n":18,"t":"主耶和華說：「歌革上來攻擊以色列地的時候，我的怒氣要從鼻孔裏發出。","notes":[],"heads":["神懲罰歌革"]},{"n":19,"t":"我發憤恨和烈怒如火說：那日在以色列地必有大震動，","notes":[]},{"n":20,"t":"甚至海中的魚、天空的鳥、田野的獸，並地上的一切昆蟲，和其上的眾人，因見我的面就都震動；山嶺必崩裂，陡巖必塌陷，牆垣都必坍倒。」","notes":[]},{"n":21,"t":"主耶和華說：「我必命我的諸山發刀劍來攻擊歌革；人都要用刀劍殺害弟兄。","notes":[]},{"n":22,"t":"我必用瘟疫和流血的事刑罰他。我也必將暴雨、大雹與火，並硫磺降與他和他的軍隊，並他所率領的眾民。","notes":[]},{"n":23,"t":"我必顯為大，顯為聖，在多國人的眼前顯現；他們就知道我是耶和華。」","notes":[]}]},"39":{"heading":"歌革被擊敗","verses":[{"n":1,"t":"「人子啊，你要向歌革發預言攻擊他，說主耶和華如此說：羅施、米設、土巴的王歌革啊，我與你為敵。","notes":[]},{"n":2,"t":"我必調轉你，領你前往，使你從北方的極處上來，帶你到以色列的山上。","notes":[]},{"n":3,"t":"我必從你左手打落你的弓，從你右手打掉你的箭。","notes":[]},{"n":4,"t":"你和你的軍隊，並同著你的列國人，都必倒在以色列的山上。我必將你給各類的鷙鳥和田野的走獸作食物。","notes":[]},{"n":5,"t":"你必倒在田野，因為我曾說過。這是主耶和華說的。","notes":[]},{"n":6,"t":"我要降火在瑪各和海島安然居住的人身上，他們就知道我是耶和華。","notes":[]},{"n":7,"t":"「我要在我民以色列中顯出我的聖名，也不容我的聖名再被褻瀆，列國人就知道我是耶和華－以色列中的聖者。","notes":[]},{"n":8,"t":"主耶和華說：這日事情臨近，也必成就，乃是我所說的日子。","notes":[]},{"n":9,"t":"「住以色列城邑的人必出去撿器械，就是大小盾牌、弓箭、梃杖、槍矛，都當柴燒火，直燒七年，","notes":[]},{"n":10,"t":"甚至他們不必從田野撿柴，也不必從樹林伐木；因為他們要用器械燒火，並且搶奪那搶奪他們的人，擄掠那擄掠他們的人。這是主耶和華說的。」","notes":[]},{"n":11,"t":"「當那日，我必將以色列地的谷，就是海東人所經過的谷，賜給歌革為墳地，使經過的人到此停步。在那裏人必葬埋歌革和他的群眾，就稱那地為哈們‧歌革谷。","notes":[],"heads":["歌革的埋葬"]},{"n":12,"t":"以色列家的人必用七個月葬埋他們，為要潔淨全地。","notes":[]},{"n":13,"t":"全地的居民都必葬埋他們。當我得榮耀的日子，這事必叫他們得名聲。這是主耶和華說的。","notes":[]},{"n":14,"t":"他們必分派人時常巡查遍地，與過路的人一同葬埋那剩在地面上的屍首，好潔淨全地。過了七個月，他們還要巡查。","notes":[]},{"n":15,"t":"巡查遍地的人要經過全地，見有人的骸骨，就在旁邊立一標記，等葬埋的人來將骸骨葬在哈們‧歌革谷。","notes":[]},{"n":16,"t":"他們必這樣潔淨那地，並有一城名叫哈摩那。","notes":[]},{"n":17,"t":"「人子啊，主耶和華如此說：你要對各類的飛鳥和田野的走獸說：你們聚集來吧，要從四方聚到我為你們獻祭之地，就是在以色列山上獻大祭之地，好叫你們吃肉、喝血。","notes":[]},{"n":18,"t":"你們必吃勇士的肉，喝地上首領的血，就如吃公綿羊、羊羔、公山羊、公牛，都是巴珊的肥畜。","notes":[]},{"n":19,"t":"你們吃我為你們所獻的祭，必吃飽了脂油，喝醉了血。","notes":[]},{"n":20,"t":"你們必在我席上飽吃馬匹和坐車的人，並勇士和一切的戰士。這是主耶和華說的。」","notes":[]},{"n":21,"t":"「我必顯我的榮耀在列國中；萬民就必看見我所行的審判與我在他們身上所加的手。","notes":[],"heads":["以色列的復興"]},{"n":22,"t":"這樣，從那日以後，以色列家必知道我是耶和華－他們的神。","notes":[]},{"n":23,"t":"列國人也必知道以色列家被擄掠是因他們的罪孽。他們得罪我，我就掩面不顧，將他們交在敵人手中，他們便都倒在刀下。","notes":[]},{"n":24,"t":"我是照他們的污穢和罪過待他們，並且我掩面不顧他們。」","notes":[]},{"n":25,"t":"主耶和華如此說：「我要使雅各被擄的人歸回，要憐憫以色列全家，又為我的聖名發熱心。","notes":[]},{"n":26,"t":"他們在本地安然居住，無人驚嚇，是我將他們從萬民中領回，從仇敵之地召來。我在許多國的民眼前，在他們身上顯為聖的時候，他們要擔當自己的羞辱和干犯我的一切罪。","notes":[],"end":27},{"n":28,"t":"因我使他們被擄到外邦人中，後又聚集他們歸回本地，他們就知道我是耶和華－他們的神；我必不再留他們一人在外邦。","notes":[]},{"n":29,"t":"我也不再掩面不顧他們，因我已將我的靈澆灌以色列家。這是主耶和華說的。」","notes":[]}]},"40":{"heading":"新聖殿的異象","verses":[{"n":1,"t":"我們被擄掠第二十五年，耶路撒冷城攻破後十四年，正在年初，月之初十日，耶和華的靈降在我身上，他把我帶到以色列地。","notes":["原文是手"],"heads":["以西結被帶到耶路撒冷"]},{"n":2,"t":"在神的異象中帶我到以色列地，安置在至高的山上；在山上的南邊有彷彿一座城建立。","notes":[]},{"n":3,"t":"他帶我到那裏，見有一人，顏色如銅，手拿麻繩和量度的竿，站在門口。","notes":["原文是形狀"]},{"n":4,"t":"那人對我說：「人子啊，凡我所指示你的，你都要用眼看，用耳聽，並要放在心上。我帶你到這裏來，特為要指示你；凡你所見的，你都要告訴以色列家。」","notes":[]},{"n":5,"t":"我見殿四圍有牆。那人手拿量度的竿，長六肘，每肘是一肘零一掌。他用竿量牆，厚一竿，高一竿。","notes":[],"heads":["東門"]},{"n":6,"t":"他到了朝東的門，就上門的臺階，量門的這檻，寬一竿；又量門的那檻，寬一竿。","notes":[]},{"n":7,"t":"又有衛房，每房長一竿，寬一竿，相隔五肘。門檻，就是挨著向殿的廊門檻，寬一竿。","notes":[]},{"n":8,"t":"他又量向殿門的廊子，寬一竿。","notes":[]},{"n":9,"t":"又量門廊，寬八肘，牆柱厚二肘；那門的廊子向著殿。","notes":[]},{"n":10,"t":"東門洞有衛房：這旁三間，那旁三間，都是一樣的尺寸；這邊的柱子和那邊的柱子，也是一樣的尺寸。","notes":[]},{"n":11,"t":"他量門口，寬十肘，長十三肘。","notes":[]},{"n":12,"t":"衛房前展出的境界：這邊一肘，那邊一肘；衛房這邊六肘，那邊六肘。","notes":[]},{"n":13,"t":"又量門洞，從這衛房頂的後檐到那衛房頂的後檐，寬二十五肘；衛房門與門相對。","notes":[]},{"n":14,"t":"又量廊子六十肘，牆柱外是院子，有廊為界，在門洞兩邊。","notes":["原文是造","七十士譯本是二十肘"]},{"n":15,"t":"從大門口到內廊前，共五十肘。","notes":[]},{"n":16,"t":"衛房和門洞兩旁柱間並廊子，都有嚴緊的窗櫺；裏邊都有窗櫺，柱上有雕刻的棕樹。","notes":[]},{"n":17,"t":"他帶我到外院，見院的四圍有鋪石地；鋪石地上有屋子三十間。","notes":[],"heads":["外院"]},{"n":18,"t":"鋪石地，就是矮鋪石地在各門洞兩旁，以門洞的長短為度。","notes":[]},{"n":19,"t":"他從下門量到內院外，共寬一百肘，東面北面都是如此。","notes":[]},{"n":20,"t":"他量外院朝北的門，長寬若干。","notes":[],"heads":["北門"]},{"n":21,"t":"門洞的衛房，這旁三間，那旁三間。門洞的柱子和廊子，與第一門的尺寸一樣。門洞長五十肘，寬二十五肘。","notes":[]},{"n":22,"t":"其窗櫺和廊子，並雕刻的棕樹，與朝東的門尺寸一樣。登七層臺階上到這門，前面有廊子。","notes":[]},{"n":23,"t":"內院有門與這門相對，北面東面都是如此。他從這門量到那門，共一百肘。","notes":[]},{"n":24,"t":"他帶我往南去，見朝南有門，又照先前的尺寸量門洞的柱子和廊子。","notes":[],"heads":["南門"]},{"n":25,"t":"門洞兩旁與廊子的周圍都有窗櫺，和先量的窗櫺一樣。門洞長五十肘，寬二十五肘。","notes":[]},{"n":26,"t":"登七層臺階上到這門，前面有廊子；柱上有雕刻的棕樹，這邊一棵，那邊一棵。","notes":[]},{"n":27,"t":"內院朝南有門。從這門量到朝南的那門，共一百肘。","notes":[]},{"n":28,"t":"他帶我從南門到內院，就照先前的尺寸量南門。","notes":[],"heads":["內院的南門"]},{"n":29,"t":"衛房和柱子，並廊子都照先前的尺寸。門洞兩旁與廊子的周圍都有窗櫺。門洞長五十肘，寬二十五肘。","notes":[]},{"n":30,"t":"周圍有廊子，長二十五肘，寬五肘。","notes":[]},{"n":31,"t":"廊子朝著外院，柱上有雕刻的棕樹。登八層臺階上到這門。","notes":[]},{"n":32,"t":"他帶我到內院的東面，就照先前的尺寸量東門。","notes":[],"heads":["內院的東門"]},{"n":33,"t":"衛房和柱子，並廊子都照先前的尺寸。門洞兩旁與廊子的周圍都有窗櫺。門洞長五十肘，寬二十五肘。","notes":[]},{"n":34,"t":"廊子朝著外院。門洞兩旁的柱子都有雕刻的棕樹。登八層臺階上到這門。","notes":[]},{"n":35,"t":"他帶我到北門，就照先前的尺寸量那門，","notes":[],"heads":["內院的北門"]},{"n":36,"t":"就是量衛房和柱子，並廊子。門洞周圍都有窗櫺；門洞長五十肘，寬二十五肘。","notes":[]},{"n":37,"t":"廊柱朝著外院。門洞兩旁的柱子都有雕刻的棕樹。登八層臺階上到這門。","notes":[]},{"n":38,"t":"門洞的柱旁有屋子和門；祭司在那裏洗燔祭牲。","notes":["原文是他們"],"heads":["廂房"]},{"n":39,"t":"在門廊內，這邊有兩張桌子，那邊有兩張桌子，在其上可以宰殺燔祭牲、贖罪祭牲，和贖愆祭牲。","notes":[]},{"n":40,"t":"上到朝北的門口，這邊有兩張桌子，門廊那邊也有兩張桌子。","notes":[]},{"n":41,"t":"門這邊有四張桌子，那邊有四張桌子，共八張；在其上祭司宰殺犧牲。","notes":[]},{"n":42,"t":"為燔祭牲有四張桌子，是鑿過的石頭做成的，長一肘半，寬一肘半，高一肘。祭司將宰殺燔祭牲和平安祭牲所用的器皿放在其上。","notes":[]},{"n":43,"t":"有鉤子，寬一掌，釘在廊內的四圍。桌子上有犧牲的肉。","notes":[]},{"n":44,"t":"在北門旁，內院裏有屋子，為歌唱的人而設。這屋子朝南；在南門旁，又有一間朝北。","notes":["南：原文是東"]},{"n":45,"t":"他對我說：「這朝南的屋子是為看守殿宇的祭司；","notes":[]},{"n":46,"t":"那朝北的屋子是為看守祭壇的祭司。這些祭司是利未人中撒督的子孫，近前來事奉耶和華的。」","notes":[]},{"n":47,"t":"他又量內院，長一百肘，寬一百肘，是見方的。祭壇在殿前。","notes":[],"heads":["內院和聖殿"]},{"n":48,"t":"於是他帶我到殿前的廊子，量廊子的牆柱。這面厚五肘，那面厚五肘。門兩旁，這邊三肘，那邊三肘。","notes":[]},{"n":49,"t":"廊子長二十肘，寬十一肘。上廊子有臺階。靠近牆柱又有柱子，這邊一根，那邊一根。","notes":[]}]},"41":{"heading":"靠聖殿牆邊的廂房","verses":[{"n":1,"t":"他帶我到殿那裏量牆柱：這面厚六肘，那面厚六肘，寬窄與會幕相同。","notes":[]},{"n":2,"t":"門口寬十肘。門兩旁，這邊五肘，那邊五肘。他量殿長四十肘，寬二十肘。","notes":[]},{"n":3,"t":"他到內殿量牆柱，各厚二肘。門口寬六肘，門兩旁各寬七肘。","notes":[]},{"n":4,"t":"他量內殿，長二十肘，寬二十肘。他對我說：「這是至聖所。」","notes":[]},{"n":5,"t":"他又量殿牆，厚六肘；圍著殿有旁屋，各寬四肘。","notes":[]},{"n":6,"t":"旁屋有三層，層疊而上，每層排列三十間。旁屋的梁木擱在殿牆坎上，免得插入殿牆。","notes":[]},{"n":7,"t":"這圍殿的旁屋越高越寬；因旁屋圍殿懸疊而上，所以越上越寬，從下一層，由中一層，到上一層。","notes":[]},{"n":8,"t":"我又見圍著殿有高月臺。旁屋的根基，高足一竿，就是六大肘。","notes":[]},{"n":9,"t":"旁屋的外牆厚五肘。旁屋之外還有餘地。","notes":[]},{"n":10,"t":"在旁屋與對面的房屋中間有空地，寬二十肘。","notes":[]},{"n":11,"t":"旁屋的門都向餘地：一門向北，一門向南。周圍的餘地寬五肘。","notes":[]},{"n":12,"t":"在西面空地之後有房子，寬七十肘，長九十肘，牆四圍厚五肘。","notes":[],"heads":["西邊的屋子"]},{"n":13,"t":"這樣，他量殿，長一百肘，又量空地和那房子並牆，共長一百肘。","notes":[],"heads":["聖殿的尺寸"]},{"n":14,"t":"殿的前面和兩旁的空地，寬一百肘。","notes":[]},{"n":15,"t":"他量空地後面的那房子，並兩旁的樓廊，共長一百肘。","notes":[]},{"n":16,"t":"內殿、院廊、門檻、嚴緊的窗櫺，並對著門檻的三層樓廊，從地到窗櫺（窗櫺都有蔽子），","notes":[],"heads":["聖殿的內部"]},{"n":17,"t":"直到門以上，就是到內殿和外殿內外四圍牆壁，都按尺寸用木板遮蔽。","notes":[]},{"n":18,"t":"牆上雕刻基路伯和棕樹。每二基路伯中間有一棵棕樹，每基路伯有二臉。","notes":[]},{"n":19,"t":"這邊有人臉向著棕樹，那邊有獅子臉向著棕樹，殿內周圍都是如此。","notes":[]},{"n":20,"t":"從地至門以上，都有基路伯和棕樹。殿牆就是這樣。","notes":[]},{"n":21,"t":"殿的門柱是方的。至聖所的前面，形狀和殿的形狀一樣。","notes":[]},{"n":22,"t":"壇是木頭做的，高三肘，長二肘。壇角和壇面，並四旁，都是木頭做的。他對我說：「這是耶和華面前的桌子。」","notes":[]},{"n":23,"t":"殿和至聖所的門各有兩扇。","notes":[],"heads":["門"]},{"n":24,"t":"每扇分兩扇，這兩扇是摺疊的。這邊門分兩扇，那邊門也分兩扇。","notes":[]},{"n":25,"t":"殿的門扇上雕刻基路伯和棕樹，與刻在牆上的一般。在外頭廊前有木檻。","notes":[]},{"n":26,"t":"廊這邊那邊都有嚴緊的窗櫺和棕樹；殿的旁屋和檻就是這樣。","notes":[]}]},"42":{"heading":"聖殿附近的兩座屋子","verses":[{"n":1,"t":"他帶我出來向北，到外院，又帶我進入聖屋；這聖屋一排順著空地，一排與北邊鋪石地之屋相對。","notes":[]},{"n":2,"t":"這聖屋長一百肘，寬五十肘，有向北的門。","notes":[]},{"n":3,"t":"對著內院那二十肘寬之空地，又對著外院的鋪石地，在第三層樓上有樓廊對著樓廊。","notes":[]},{"n":4,"t":"在聖屋前有一條夾道，寬十肘，長一百肘。房門都向北。","notes":[]},{"n":5,"t":"聖屋因為樓廊佔去些地方，所以上層比中下兩層窄些。","notes":[]},{"n":6,"t":"聖屋有三層，卻無柱子，不像外院的屋子有柱子；所以上層比中下兩層更窄。","notes":[]},{"n":7,"t":"聖屋外，東邊有牆，靠著外院，長五十肘。","notes":[]},{"n":8,"t":"靠著外院的聖屋長五十肘。殿北面的聖屋長一百肘。","notes":[]},{"n":9,"t":"在聖屋以下，東頭有進入之處，就是從外院進入之處。","notes":[]},{"n":10,"t":"向南在內院牆裏有聖屋，一排與鋪石地之屋相對，一排順著空地。","notes":["原文是東"]},{"n":11,"t":"這聖屋前的夾道與北邊聖屋的夾道長寬一樣；出入之處與北屋門的樣式相同。","notes":[]},{"n":12,"t":"正在牆前、夾道的東頭，有門可以進入，與向南聖屋的門一樣。","notes":[]},{"n":13,"t":"他對我說：「順著空地的南屋北屋，都是聖屋；親近耶和華的祭司當在那裏吃至聖的物，也當在那裏放至聖的物，就是素祭、贖罪祭，和贖愆祭，因此處為聖。","notes":[]},{"n":14,"t":"祭司進去出了聖所的時候，不可直到外院，但要在聖屋放下他們供職的衣服，因為是聖衣；要穿上別的衣服才可以到屬民的外院。」","notes":[]},{"n":15,"t":"他量完了內殿，就帶我出朝東的門，量院的四圍。","notes":[],"heads":["聖殿周圍的尺寸"]},{"n":16,"t":"他用量度的竿量四圍，量東面五百肘，","notes":["原文是竿；本章下同"]},{"n":17,"t":"用竿量北面五百肘，","notes":[]},{"n":18,"t":"用竿量南面五百肘，","notes":[]},{"n":19,"t":"又轉到西面，用竿量五百肘。","notes":[]},{"n":20,"t":"他量四面，四圍有牆，長五百肘，寬五百肘，為要分別聖地與俗地。","notes":[]}]},"43":{"heading":"耶和華回到聖殿","verses":[{"n":1,"t":"以後，他帶我到一座門，就是朝東的門。","notes":[]},{"n":2,"t":"以色列神的榮光從東而來。他的聲音如同多水的聲音；地就因他的榮耀發光。","notes":[]},{"n":3,"t":"其狀如從前他來滅城的時候我所見的異象，那異象如我在迦巴魯河邊所見的異象，我就俯伏在地。","notes":[]},{"n":4,"t":"耶和華的榮光從朝東的門照入殿中。","notes":[]},{"n":5,"t":"靈將我舉起，帶入內院，不料，耶和華的榮光充滿了殿。","notes":[]},{"n":6,"t":"我聽見有一位從殿中對我說話。有一人站在我旁邊。","notes":[]},{"n":7,"t":"他對我說：「人子啊，這是我寶座之地，是我腳掌所踏之地。我要在這裏住，在以色列人中直到永遠。以色列家和他們的君王必不再玷污我的聖名，就是行邪淫、在錫安的高處葬埋他們君王的屍首，","notes":[]},{"n":8,"t":"使他們的門檻挨近我的門檻，他們的門框挨近我的門框；他們與我中間僅隔一牆，並且行可憎的事，玷污了我的聖名，所以我發怒滅絕他們。","notes":[]},{"n":9,"t":"現在他們當從我面前遠除邪淫和他們君王的屍首，我就住在他們中間直到永遠。","notes":[]},{"n":10,"t":"「人子啊，你要將這殿指示以色列家，使他們因自己的罪孽慚愧，也要他們量殿的尺寸。","notes":[]},{"n":11,"t":"他們若因自己所行的一切事慚愧，你就將殿的規模、樣式、出入之處，和一切形狀、典章、禮儀、法則指示他們，在他們眼前寫上，使他們遵照殿的一切規模典章去做。","notes":[]},{"n":12,"t":"殿的法則乃是如此：殿在山頂上，四圍的全界要稱為至聖。這就是殿的法則。」","notes":[]},{"n":13,"t":"以下量祭壇，是以肘為度（這肘是一肘零一掌）。底座高一肘，邊寬一肘，四圍起邊高一掌，這是壇的座。","notes":[],"heads":["祭壇"]},{"n":14,"t":"從底座到下層磴臺，高二肘，邊寬一肘。從小磴臺到大磴臺，高四肘，邊寬一肘。","notes":[]},{"n":15,"t":"壇上的供臺，高四肘。供臺的四拐角上都有角。","notes":[]},{"n":16,"t":"供臺長十二肘，寬十二肘，四面見方。","notes":[]},{"n":17,"t":"磴臺長十四肘，寬十四肘，四面見方。四圍起邊高半肘，底座四圍的邊寬一肘。臺階朝東。","notes":[]},{"n":18,"t":"他對我說：「人子啊，主耶和華如此說：建造祭壇，為要在其上獻燔祭灑血，造成的時候典章如下：","notes":[],"heads":["奉獻祭壇"]},{"n":19,"t":"主耶和華說，你要將一隻公牛犢作為贖罪祭，給祭司利未人撒督的後裔，就是那親近我、事奉我的。","notes":[]},{"n":20,"t":"你要取些公牛的血，抹在壇的四角和磴臺的四拐角，並四圍所起的邊上。你這樣潔淨壇，壇就潔淨了。","notes":[]},{"n":21,"t":"你又要將那作贖罪祭的公牛犢燒在殿外、聖地之外預定之處。","notes":[]},{"n":22,"t":"次日，要將無殘疾的公山羊獻為贖罪祭；要潔淨壇，像用公牛犢潔淨的一樣。","notes":[]},{"n":23,"t":"潔淨了壇，就要將一隻無殘疾的公牛犢和羊群中一隻無殘疾的公綿羊","notes":[]},{"n":24,"t":"奉到耶和華前。祭司要撒鹽在其上，獻與耶和華為燔祭。","notes":[]},{"n":25,"t":"七日內，每日要預備一隻公山羊為贖罪祭，也要預備一隻公牛犢和羊群中的一隻公綿羊，都要沒有殘疾的。","notes":[]},{"n":26,"t":"七日祭司潔淨壇，壇就潔淨了；要這樣把壇分別為聖。","notes":[]},{"n":27,"t":"滿了七日，自八日以後，祭司要在壇上獻你們的燔祭和平安祭；我必悅納你們。這是主耶和華說的。」","notes":[]}]},"44":{"heading":"東門的使用","verses":[{"n":1,"t":"他又帶我回到聖地朝東的外門；那門關閉了。","notes":[]},{"n":2,"t":"耶和華對我說：「這門必須關閉，不可敞開，誰也不可由其中進入；因為耶和華－以色列的神已經由其中進入，所以必須關閉。","notes":[]},{"n":3,"t":"至於王，他必按王的位分，坐在其內，在耶和華面前吃餅。他必由這門的廊而入，也必由此而出。」","notes":[]},{"n":4,"t":"他又帶我由北門來到殿前。我觀看，見耶和華的榮光充滿耶和華的殿，我就俯伏在地。","notes":[],"heads":["進入聖殿的規則"]},{"n":5,"t":"耶和華對我說：「人子啊，我對你所說耶和華殿中的一切典章法則，你要放在心上，用眼看，用耳聽，並要留心殿宇和聖地一切出入之處。","notes":[]},{"n":6,"t":"你要對那悖逆的以色列家說，主耶和華如此說：以色列家啊，你們行一切可憎的事，當夠了吧！","notes":[]},{"n":7,"t":"你們把我的食物，就是脂油和血獻上的時候，將身心未受割禮的外邦人領進我的聖地，玷污了我的殿；又背了我的約，在你們一切可憎的事上，加上這一層。","notes":[]},{"n":8,"t":"你們也沒有看守我的聖物，卻派別人在聖地替你們看守我所吩咐你們的。","notes":[]},{"n":9,"t":"「主耶和華如此說：以色列中的外邦人，就是身心未受割禮的，都不可入我的聖地。」","notes":[]},{"n":10,"t":"「當以色列人走迷的時候，有利未人遠離我，就是走迷離開我、隨從他們的偶像，他們必擔當自己的罪孽。","notes":[],"heads":["不准當祭司的利未人"]},{"n":11,"t":"然而他們必在我的聖地當僕役，照管殿門，在殿中供職；必為民宰殺燔祭牲和平安祭牲，必站在民前伺候他們。","notes":[]},{"n":12,"t":"因為這些利未人曾在偶像前伺候這民，成了以色列家罪孽的絆腳石，所以我向他們起誓：他們必擔當自己的罪孽。這是主耶和華說的。","notes":[]},{"n":13,"t":"他們不可親近我，給我供祭司的職分，也不可挨近我的一件聖物，就是至聖的物；他們卻要擔當自己的羞辱和所行可憎之事的報應。","notes":[]},{"n":14,"t":"然而我要使他們看守殿宇，辦理其中的一切事，並做其內一切當做之工。」","notes":[]},{"n":15,"t":"「以色列人走迷離開我的時候，祭司利未人撒督的子孫仍看守我的聖所。他們必親近我，事奉我，並且侍立在我面前，將脂油與血獻給我。這是主耶和華說的。","notes":[],"heads":["祭司"]},{"n":16,"t":"他們必進入我的聖所，就近我的桌前事奉我，守我所吩咐的。","notes":[]},{"n":17,"t":"他們進內院門必穿細麻衣。在內院門和殿內供職的時候不可穿羊毛衣服。","notes":[]},{"n":18,"t":"他們頭上要戴細麻布裹頭巾，腰穿細麻布褲子；不可穿使身體出汗的衣服。","notes":[]},{"n":19,"t":"他們出到外院的民那裏，當脫下供職的衣服，放在聖屋內，穿上別的衣服，免得因聖衣使民成聖。","notes":[]},{"n":20,"t":"不可剃頭，也不可容髮綹長長，只可剪髮。","notes":[]},{"n":21,"t":"祭司進內院的時候都不可喝酒。","notes":[]},{"n":22,"t":"不可娶寡婦和被休的婦人為妻，只可娶以色列後裔中的處女，或是祭司遺留的寡婦。","notes":[]},{"n":23,"t":"他們要使我的民知道聖俗的分別，又使他們分辨潔淨的和不潔淨的。","notes":[]},{"n":24,"t":"有爭訟的事，他們應當站立判斷，要按我的典章判斷。在我一切的節期必守我的律法、條例，也必以我的安息日為聖日。","notes":[]},{"n":25,"t":"他們不可挨近死屍沾染自己，只可為父親、母親、兒子、女兒、弟兄，和未嫁人的姊妹沾染自己。","notes":[]},{"n":26,"t":"祭司潔淨之後，必再計算七日。","notes":[]},{"n":27,"t":"當他進內院，進聖所，在聖所中事奉的日子，要為自己獻贖罪祭。這是主耶和華說的。","notes":[]},{"n":28,"t":"「祭司必有產業，我是他們的產業。不可在以色列中給他們基業；我是他們的基業。","notes":[]},{"n":29,"t":"素祭、贖罪祭，和贖愆祭他們都可以吃，以色列中一切永獻的物都要歸他們。","notes":[]},{"n":30,"t":"首先初熟之物和一切所獻的供物都要歸給祭司。你們也要用初熟的麥子磨麵給祭司；這樣，福氣就必臨到你們的家了。","notes":[]},{"n":31,"t":"無論是鳥是獸，凡自死的，或是撕裂的，祭司都不可吃。」","notes":[]}]},"45":{"heading":"歸給耶和華的土地","verses":[{"n":1,"t":"你們拈鬮分地為業，要獻上一分給耶和華為聖供地，長二萬五千肘，寬一萬肘。這分以內，四圍都為聖地。","notes":[]},{"n":2,"t":"其中有作為聖所之地，長五百肘，寬五百肘，四面見方。四圍再有五十肘為郊野之地。","notes":[]},{"n":3,"t":"要以肘為度量地，長二萬五千肘，寬一萬肘。其中有聖所，是至聖的。","notes":[]},{"n":4,"t":"這是全地的一分聖地，要歸與供聖所職事的祭司，就是親近事奉耶和華的，作為他們房屋之地與聖所之聖地。","notes":[]},{"n":5,"t":"又有一分，長二萬五千肘，寬一萬肘，要歸與在殿中供職的利未人，作為二十間房屋之業。","notes":[]},{"n":6,"t":"也要分定屬城的地業，寬五千肘，長二萬五千肘，挨著那分聖供地，要歸以色列全家。","notes":[]},{"n":7,"t":"歸王之地要在聖供地和屬城之地的兩旁，就是聖供地和屬城之地的旁邊，西至西頭，東至東頭，從西到東，其長與每支派的分一樣。","notes":[],"heads":["君王的土地"]},{"n":8,"t":"這地在以色列中必歸王為業。我所立的王必不再欺壓我的民，卻要按支派將地分給以色列家。","notes":[]},{"n":9,"t":"主耶和華如此說：「以色列的王啊，你們應當知足，要除掉強暴和搶奪的事，施行公平和公義，不再勒索我的民。這是主耶和華說的。","notes":[],"heads":["君王應守的規例"]},{"n":10,"t":"「你們要用公道天平、公道伊法、公道罷特。","notes":[]},{"n":11,"t":"伊法與罷特大小要一樣。罷特可盛賀梅珥十分之一，伊法也可盛賀梅珥十分之一，都以賀梅珥的大小為準。","notes":[]},{"n":12,"t":"舍客勒是二十季拉；二十舍客勒，二十五舍客勒，十五舍客勒，為你們的彌那。","notes":[]},{"n":13,"t":"「你們當獻的供物乃是這樣：一賀梅珥麥子要獻伊法六分之一；一賀梅珥大麥要獻伊法六分之一。","notes":[]},{"n":14,"t":"你們獻所分定的油，按油的罷特，一柯珥油要獻罷特十分之一（原來十罷特就是一賀梅珥）。","notes":[]},{"n":15,"t":"從以色列滋潤的草場上每二百羊中，要獻一隻羊羔。這都可作素祭、燔祭、平安祭，為民贖罪。這是主耶和華說的。","notes":[]},{"n":16,"t":"此地的民都要奉上這供物給以色列中的王。","notes":[]},{"n":17,"t":"王的本分是在節期、月朔、安息日，就是以色列家一切的節期，奉上燔祭、素祭、奠祭。他要預備贖罪祭、素祭、燔祭，和平安祭，為以色列家贖罪。」","notes":[]},{"n":18,"t":"主耶和華如此說：「正月初一日，你要取無殘疾的公牛犢，潔淨聖所。","notes":[],"heads":["節期"]},{"n":19,"t":"祭司要取些贖罪祭牲的血，抹在殿的門柱上和壇磴臺的四角上，並內院的門框上。","notes":[]},{"n":20,"t":"本月初七日也要為誤犯罪的和愚蒙犯罪的如此行，為殿贖罪。","notes":["七十士譯本是七月初一日"]},{"n":21,"t":"「正月十四日，你們要守逾越節，守節七日，要吃無酵餅。","notes":[]},{"n":22,"t":"當日，王要為自己和國內的眾民預備一隻公牛作贖罪祭。","notes":[]},{"n":23,"t":"這節的七日，每日他要為耶和華預備無殘疾的公牛七隻、公綿羊七隻為燔祭。每日又要預備公山羊一隻為贖罪祭。","notes":[]},{"n":24,"t":"他也要預備素祭，就是為一隻公牛同獻一伊法細麵，為一隻公綿羊同獻一伊法細麵，每一伊法細麵加油一欣。","notes":[]},{"n":25,"t":"七月十五日守節的時候，七日他都要如此行，照逾越節的贖罪祭、燔祭、素祭，和油的條例一樣。」","notes":[]}]},"46":{"heading":"君王和節期","verses":[{"n":1,"t":"主耶和華如此說：「內院朝東的門，在辦理事務的六日內必須關閉；惟有安息日和月朔必須敞開。","notes":[]},{"n":2,"t":"王要從這門的廊進入，站在門框旁邊。祭司要為他預備燔祭和平安祭，他就要在門檻那裏敬拜，然後出去。這門直到晚上不可關閉。","notes":[]},{"n":3,"t":"在安息日和月朔，國內的居民要在這門口，耶和華面前敬拜。","notes":[]},{"n":4,"t":"安息日，王所獻與耶和華的燔祭要用無殘疾的羊羔六隻，無殘疾的公綿羊一隻；","notes":[]},{"n":5,"t":"同獻的素祭要為公綿羊獻一伊法細麵，為羊羔照他的力量而獻，一伊法細麵加油一欣。","notes":[]},{"n":6,"t":"當月朔，要獻無殘疾的公牛犢一隻，羊羔六隻，公綿羊一隻，都要無殘疾的。","notes":[]},{"n":7,"t":"他也要預備素祭，為公牛獻一伊法細麵，為公綿羊獻一伊法細麵，為羊羔照他的力量而獻，一伊法細麵加油一欣。","notes":[]},{"n":8,"t":"王進入的時候必由這門的廊而入，也必由此而出。","notes":[]},{"n":9,"t":"「在各節期，國內居民朝見耶和華的時候，從北門進入敬拜的，必由南門而出；從南門進入的，必由北門而出。不可從所入的門而出，必要直往前行，由對門而出。","notes":[]},{"n":10,"t":"民進入，王也要在民中進入；民出去，王也要一同出去。","notes":[]},{"n":11,"t":"「在節期和聖會的日子同獻的素祭，要為一隻公牛獻一伊法細麵，為一隻公綿羊獻一伊法細麵，為羊羔照他的力量而獻，一伊法細麵加油一欣。","notes":[]},{"n":12,"t":"王預備甘心獻的燔祭或平安祭，就是向耶和華甘心獻的，當有人為他開朝東的門。他就預備燔祭和平安祭，與安息日預備的一樣，獻畢就出去。他出去之後，當有人將門關閉。」","notes":[]},{"n":13,"t":"「每日，你要預備無殘疾一歲的羊羔一隻，獻與耶和華為燔祭；要每早晨預備。","notes":[],"heads":["每日的祭"]},{"n":14,"t":"每早晨也要預備同獻的素祭，細麵一伊法六分之一，並油一欣三分之一，調和細麵。這素祭要常獻與耶和華為永遠的定例。","notes":[]},{"n":15,"t":"每早晨要這樣預備羊羔、素祭，並油為常獻的燔祭。」","notes":[]},{"n":16,"t":"主耶和華如此說：「王若將產業賜給他的兒子，就成了他兒子的產業，那是他們承受為業的。","notes":[],"heads":["王和土地"]},{"n":17,"t":"倘若王將一分產業賜給他的臣僕，就成了他臣僕的產業；到自由之年仍要歸與王。至於王的產業，必歸與他的兒子。","notes":[]},{"n":18,"t":"王不可奪取民的產業，以致驅逐他們離開所承受的；他要從自己的地業中，將產業賜給他兒子，免得我的民分散，各人離開所承受的。」","notes":[]},{"n":19,"t":"那帶我的，將我從門旁進入之處、領進為祭司預備的聖屋，是朝北的，見後頭西邊有一塊地。","notes":[],"heads":["聖殿的廚房"]},{"n":20,"t":"他對我說：「這是祭司煮贖愆祭、贖罪祭，烤素祭之地，免得帶到外院，使民成聖。」","notes":[]},{"n":21,"t":"他又帶我到外院，使我經過院子的四拐角，見每拐角各有一個院子。","notes":[]},{"n":22,"t":"院子四拐角的院子，周圍有牆，每院長四十肘，寬三十肘。四拐角院子的尺寸都是一樣，","notes":[]},{"n":23,"t":"其中周圍有一排房子，房子內有煮肉的地方。","notes":[]},{"n":24,"t":"他對我說：「這都是煮肉的房子，殿內的僕役要在這裏煮民的祭物。」","notes":[]}]},"47":{"heading":"從聖殿流出的水","verses":[{"n":1,"t":"他帶我回到殿門，見殿的門檻下有水往東流出（原來殿面朝東）。這水從檻下，由殿的右邊，在祭壇的南邊往下流。","notes":[]},{"n":2,"t":"他帶我出北門，又領我從外邊轉到朝東的外門，見水從右邊流出。","notes":[]},{"n":3,"t":"他手拿準繩往東出去的時候，量了一千肘，使我蹚過水，水到踝子骨。","notes":[]},{"n":4,"t":"他又量了一千肘，使我蹚過水，水就到膝；再量了一千肘，使我蹚過水，水便到腰；","notes":[]},{"n":5,"t":"又量了一千肘，水便成了河，使我不能蹚過。因為水勢漲起，成為可洑的水，不可蹚的河。","notes":[]},{"n":6,"t":"他對我說：「人子啊，你看見了甚麼？」他就帶我回到河邊。","notes":[]},{"n":7,"t":"我回到河邊的時候，見在河這邊與那邊的岸上有極多的樹木。","notes":[]},{"n":8,"t":"他對我說：「這水往東方流去，必下到亞拉巴，直到海。所發出來的水必流入鹽海，使水變甜。","notes":["原文是得醫治；下同"]},{"n":9,"t":"這河水所到之處，凡滋生的動物都必生活，並且因這流來的水必有極多的魚，海水也變甜了。這河水所到之處，百物都必生活。","notes":[]},{"n":10,"t":"必有漁夫站在河邊，從隱‧基底直到隱‧以革蓮，都作曬網之處。那魚各從其類，好像大海的魚甚多。","notes":["或譯：張"]},{"n":11,"t":"只是泥濘之地與窪濕之處不得治好，必為鹽地。","notes":[]},{"n":12,"t":"在河這邊與那邊的岸上必生長各類的樹木；其果可作食物，葉子不枯乾，果子不斷絕。每月必結新果子，因為這水是從聖所流出來的。樹上的果子必作食物，葉子乃為治病。」","notes":[]},{"n":13,"t":"主耶和華如此說：「你們要照地的境界，按以色列十二支派分地為業。約瑟必得兩分。","notes":[],"heads":["地界"]},{"n":14,"t":"你們承受這地為業，要彼此均分；因為我曾起誓應許將這地賜與你們的列祖；這地必歸你們為業。","notes":[]},{"n":15,"t":"「地的四界乃是如此：北界從大海往希特倫，直到西達達口。","notes":[]},{"n":16,"t":"又往哈馬、比羅他、西伯蓮（西伯蓮在大馬士革與哈馬兩界中間），到浩蘭邊界的哈撒‧哈提干。","notes":[]},{"n":17,"t":"這樣，境界從海邊往大馬士革地界上的哈薩‧以難，北邊以哈馬地為界。這是北界。","notes":[]},{"n":18,"t":"「東界在浩蘭、大馬士革、基列，和以色列地的中間，就是約旦河。你們要從北界量到東海。這是東界。","notes":[]},{"n":19,"t":"「南界是從他瑪到米利巴‧加低斯的水，延到埃及小河，直到大海。這是南界。","notes":[]},{"n":20,"t":"「西界就是大海，從南界直到哈馬口對面之地。這是西界。","notes":[]},{"n":21,"t":"「你們要按著以色列的支派彼此分這地。","notes":[]},{"n":22,"t":"要拈鬮分這地為業，歸與自己和你們中間寄居的外人，就是在你們中間生養兒女的外人。你們要看他們如同以色列人中所生的一樣；他們在以色列支派中要與你們同得地業。","notes":[]},{"n":23,"t":"外人寄居在哪支派中，你們就在那裏分給他地業。這是主耶和華說的。」","notes":[]}]},"48":{"heading":"各支派分配土地","verses":[{"n":1,"t":"眾支派按名所得之地記在下面：從北頭，由希特倫往哈馬口，到大馬士革地界上的哈薩‧以難。北邊靠著哈馬地（各支派的地都有東西的邊界），是但的一分。","notes":[]},{"n":2,"t":"挨著但的地界，從東到西，是亞設的一分。","notes":[]},{"n":3,"t":"挨著亞設的地界，從東到西，是拿弗他利的一分。","notes":[]},{"n":4,"t":"挨著拿弗他利的地界，從東到西，是瑪拿西的一分。","notes":[]},{"n":5,"t":"挨著瑪拿西的地界，從東到西，是以法蓮的一分。","notes":[]},{"n":6,"t":"挨著以法蓮的地界，從東到西，是呂便的一分。","notes":[]},{"n":7,"t":"挨著呂便的地界，從東到西，是猶大的一分。","notes":[]},{"n":8,"t":"挨著猶大的地界，從東到西，必有你們所當獻的供地，寬二萬五千肘。從東界到西界，長短與各分之地相同，聖地當在其中。","notes":[],"heads":["中部特區"]},{"n":9,"t":"你們獻與耶和華的供地要長二萬五千肘，寬一萬肘。","notes":[]},{"n":10,"t":"這聖供地要歸與祭司，北長二萬五千肘，西寬一萬肘，東寬一萬肘，南長二萬五千肘。耶和華的聖地當在其中。","notes":[]},{"n":11,"t":"這地要歸與撒督的子孫中成為聖的祭司，就是那守我所吩咐的。當以色列人走迷的時候，他們不像那些利未人走迷了。","notes":[]},{"n":12,"t":"這要歸與他們為供地，是全地中至聖的。供地挨著利未人的地界。","notes":[]},{"n":13,"t":"利未人所得的地要長二萬五千肘，寬一萬肘，與祭司的地界相等，都長二萬五千肘，寬一萬肘。","notes":[]},{"n":14,"t":"這地不可賣，不可換，初熟之物也不可歸與別人，因為是歸耶和華為聖的。","notes":[]},{"n":15,"t":"這二萬五千肘前面所剩下五千肘寬之地要作俗用，作為造城蓋房郊野之地。城要在當中。","notes":[]},{"n":16,"t":"城的尺寸乃是如此：北面四千五百肘，南面四千五百肘，東面四千五百肘，西面四千五百肘。","notes":[]},{"n":17,"t":"城必有郊野，向北二百五十肘，向南二百五十肘，向東二百五十肘，向西二百五十肘。","notes":[]},{"n":18,"t":"靠著聖供地的餘地，東長一萬肘，西長一萬肘，要與聖供地相等；其中的土產要作城內工人的食物。","notes":[]},{"n":19,"t":"所有以色列支派中，在城內做工的，都要耕種這地。","notes":[]},{"n":20,"t":"你們所獻的聖供地連歸城之地，是四方的：長二萬五千肘，寬二萬五千肘。","notes":[]},{"n":21,"t":"聖供地連歸城之地，兩邊的餘地要歸與王。供地東邊，南北二萬五千肘，東至東界，西邊南北二萬五千肘，西至西界，與各分之地相同，都要歸王。聖供地和殿的聖地要在其中，","notes":[]},{"n":22,"t":"並且利未人之地，與歸城之地的東西兩邊延長之地（這兩地在王地中間），就是在猶大和便雅憫兩界中間，要歸與王。","notes":[]},{"n":23,"t":"論到其餘的支派，從東到西，是便雅憫的一分。","notes":[],"heads":["其他支派的土地"]},{"n":24,"t":"挨著便雅憫的地界，從東到西，是西緬的一分。","notes":[]},{"n":25,"t":"挨著西緬的地界，從東到西，是以薩迦的一分。","notes":[]},{"n":26,"t":"挨著以薩迦的地界，從東到西，是西布倫的一分。","notes":[]},{"n":27,"t":"挨著西布倫的地界，從東到西，是迦得的一分。","notes":[]},{"n":28,"t":"迦得地的南界是從他瑪到米利巴‧加低斯的水，延到埃及小河，直到大海。","notes":[]},{"n":29,"t":"這就是你們要拈鬮分給以色列支派為業之地，乃是他們各支派所得之分。這是主耶和華說的。","notes":[]},{"n":30,"t":"城的北面四千五百肘。出城之處如下；","notes":[],"heads":["耶路撒冷的城門"]},{"n":31,"t":"城的各門要按以色列支派的名字。北面有三門，一為呂便門，一為猶大門，一為利未門；","notes":[]},{"n":32,"t":"東面四千五百肘，有三門，一為約瑟門，一為便雅憫門，一為但門；","notes":[]},{"n":33,"t":"南面四千五百肘，有三門，一為西緬門，一為以薩迦門，一為西布倫門；","notes":[]},{"n":34,"t":"西面四千五百肘，有三門，一為迦得門，一為亞設門，一為拿弗他利門。","notes":[]},{"n":35,"t":"城四圍共一萬八千肘。從此以後，這城的名字必稱為「耶和華的所在」。","notes":[]}]}},"DAN":{"1":{"heading":"但以理和他的朋友們","verses":[{"n":1,"t":"猶大王約雅敬在位第三年，巴比倫王尼布甲尼撒來到耶路撒冷，將城圍困。","notes":[],"heads":["但以理在尼布甲尼撒的宮廷裏"]},{"n":2,"t":"主將猶大王約雅敬，並神殿中器皿的幾分交付他手。他就把這器皿帶到示拿地，收入他神的廟裏，放在他神的庫中。","notes":[]},{"n":3,"t":"王吩咐太監長亞施毗拿，從以色列人的宗室和貴冑中帶進幾個人來，","notes":[]},{"n":4,"t":"就是年少沒有殘疾、相貌俊美、通達各樣學問、知識聰明俱備、足能侍立在王宮裏的，要教他們迦勒底的文字言語。","notes":[]},{"n":5,"t":"王派定將自己所用的膳和所飲的酒，每日賜他們一分，養他們三年。滿了三年，好叫他們在王面前侍立。","notes":[]},{"n":6,"t":"他們中間有猶大族的人：但以理、哈拿尼雅、米沙利、亞撒利雅。","notes":[]},{"n":7,"t":"太監長給他們起名：稱但以理為伯提沙撒，稱哈拿尼雅為沙得拉，稱米沙利為米煞，稱亞撒利雅為亞伯尼歌。","notes":[]},{"n":8,"t":"但以理卻立志不以王的膳和王所飲的酒玷污自己，所以求太監長容他不玷污自己。","notes":[]},{"n":9,"t":"神使但以理在太監長眼前蒙恩惠，受憐憫。","notes":[]},{"n":10,"t":"太監長對但以理說：「我懼怕我主我王，他已經派定你們的飲食，倘若他見你們的面貌比你們同歲的少年人肌瘦，怎麼好呢？這樣，你們就使我的頭在王那裏難保。」","notes":[]},{"n":11,"t":"但以理對太監長所派管理但以理、哈拿尼雅、米沙利、亞撒利雅的委辦說：","notes":[]},{"n":12,"t":"「求你試試僕人們十天，給我們素菜吃，白水喝，","notes":[]},{"n":13,"t":"然後看看我們的面貌和用王膳那少年人的面貌，就照你所看的待僕人吧！」","notes":[]},{"n":14,"t":"委辦便允准他們這件事，試看他們十天。","notes":[]},{"n":15,"t":"過了十天，見他們的面貌比用王膳的一切少年人更加俊美肥胖。","notes":[]},{"n":16,"t":"於是委辦撤去派他們用的膳，飲的酒，給他們素菜吃。","notes":[]},{"n":17,"t":"這四個少年人，神在各樣文字學問上賜給他們聰明知識；但以理又明白各樣的異象和夢兆。","notes":["學問：原文是智慧"]},{"n":18,"t":"尼布甲尼撒王預定帶進少年人來的日期滿了，太監長就把他們帶到王面前。","notes":[]},{"n":19,"t":"王與他們談論，見少年人中無一人能比但以理、哈拿尼雅、米沙利、亞撒利雅，所以留他們在王面前侍立。","notes":[]},{"n":20,"t":"王考問他們一切事，就見他們的智慧聰明比通國的術士和用法術的勝過十倍。","notes":[]},{"n":21,"t":"到塞魯士王元年，但以理還在。","notes":[]}]},"2":{"heading":"神把夢的意思指示但以理","verses":[{"n":1,"t":"尼布甲尼撒在位第二年，他做了夢，心裏煩亂，不能睡覺。","notes":[]},{"n":2,"t":"王吩咐人將術士、用法術的、行邪術的，和迦勒底人召來，要他們將王的夢告訴王，他們就來站在王前。","notes":[]},{"n":3,"t":"王對他們說：「我做了一夢，心裏煩亂，要知道這是甚麼夢。」","notes":[]},{"n":4,"t":"迦勒底人用亞蘭的言語對王說：「願王萬歲！請將那夢告訴僕人，僕人就可以講解。」","notes":[]},{"n":5,"t":"王回答迦勒底人說：「夢我已經忘了，你們若不將夢和夢的講解告訴我，就必被凌遲，你們的房屋必成為糞堆；","notes":["或譯：我已定命；八節同"]},{"n":6,"t":"你們若將夢和夢的講解告訴我，就必從我這裏得贈品和賞賜，並大尊榮。現在你們要將夢和夢的講解告訴我。」","notes":[]},{"n":7,"t":"他們第二次對王說：「請王將夢告訴僕人，僕人就可以講解。」","notes":[]},{"n":8,"t":"王回答說：「我准知道你們是故意遲延，因為你們知道那夢我已經忘了。","notes":[]},{"n":9,"t":"你們若不將夢告訴我，只有一法待你們；因為你們預備了謊言亂語向我說，要等候時勢改變。現在你們要將夢告訴我，因我知道你們能將夢的講解告訴我。」","notes":[]},{"n":10,"t":"迦勒底人在王面前回答說：「世上沒有人能將王所問的事說出來；因為沒有君王、大臣、掌權的向術士，或用法術的，或迦勒底人問過這樣的事。","notes":[]},{"n":11,"t":"王所問的事甚難。除了不與世人同居的神明，沒有人在王面前能說出來。」","notes":[]},{"n":12,"t":"因此，王氣忿忿地大發烈怒，吩咐滅絕巴比倫所有的哲士。","notes":[]},{"n":13,"t":"於是命令發出，哲士將要見殺，人就尋找但以理和他的同伴，要殺他們。","notes":[]},{"n":14,"t":"王的護衛長亞略出來，要殺巴比倫的哲士，但以理就用婉言回答他，","notes":[]},{"n":15,"t":"向王的護衛長亞略說：「王的命令為何這樣緊急呢？」亞略就將情節告訴但以理。","notes":[]},{"n":16,"t":"但以理遂進去求王寬限，就可以將夢的講解告訴王。","notes":[]},{"n":17,"t":"但以理回到他的居所，將這事告訴他的同伴哈拿尼雅、米沙利、亞撒利雅，","notes":[]},{"n":18,"t":"要他們祈求天上的神施憐憫，將這奧祕的事指明，免得但以理和他的同伴與巴比倫其餘的哲士一同滅亡。","notes":[]},{"n":19,"t":"這奧祕的事就在夜間異象中給但以理顯明，但以理便稱頌天上的神。","notes":[]},{"n":20,"t":"但以理說：「神的名是應當稱頌的！從亙古直到永遠，因為智慧能力都屬乎他。","notes":[]},{"n":21,"t":"他改變時候、日期，廢王，立王，將智慧賜與智慧人，將知識賜與聰明人。","notes":[]},{"n":22,"t":"他顯明深奧隱秘的事，知道暗中所有的，光明也與他同居。","notes":[]},{"n":23,"t":"我列祖的神啊，我感謝你，讚美你；因你將智慧才能賜給我，允准我們所求的，把王的事給我們指明。」","notes":[]},{"n":24,"t":"於是，但以理進去見亞略，就是王所派滅絕巴比倫哲士的，對他說：「不要滅絕巴比倫的哲士，求你領我到王面前，我要將夢的講解告訴王。」","notes":[],"heads":["但以理為王解夢"]},{"n":25,"t":"亞略就急忙將但以理領到王面前，對王說：「我在被擄的猶大人中遇見一人，他能將夢的講解告訴王。」","notes":[]},{"n":26,"t":"王問稱為伯提沙撒的但以理說：「你能將我所做的夢和夢的講解告訴我嗎？」","notes":[]},{"n":27,"t":"但以理在王面前回答說：「王所問的那奧祕事，哲士、用法術的、術士、觀兆的都不能告訴王，","notes":[]},{"n":28,"t":"只有一位在天上的神能顯明奧祕的事。他已將日後必有的事指示尼布甲尼撒王。你的夢和你在床上腦中的異象是這樣：","notes":[]},{"n":29,"t":"王啊，你在床上想到後來的事，那顯明奧祕事的主把將來必有的事指示你。","notes":[]},{"n":30,"t":"至於那奧祕的事顯明給我，並非因我的智慧勝過一切活人，乃為使王知道夢的講解和心裏的思念。","notes":[]},{"n":31,"t":"「王啊，你夢見一個大像，這像甚高，極其光耀，站在你面前，形狀甚是可怕。","notes":[]},{"n":32,"t":"這像的頭是精金的，胸膛和膀臂是銀的，肚腹和腰是銅的，","notes":[]},{"n":33,"t":"腿是鐵的，腳是半鐵半泥的。","notes":[]},{"n":34,"t":"你觀看，見有一塊非人手鑿出來的石頭打在這像半鐵半泥的腳上，把腳砸碎；","notes":[]},{"n":35,"t":"於是金、銀、銅、鐵、泥都一同砸得粉碎，成如夏天禾場上的糠秕，被風吹散，無處可尋。打碎這像的石頭變成一座大山，充滿天下。","notes":[]},{"n":36,"t":"「這就是那夢；我們在王面前要講解那夢。","notes":[]},{"n":37,"t":"王啊，你是諸王之王。天上的神已將國度、權柄、能力、尊榮都賜給你。","notes":[]},{"n":38,"t":"凡世人所住之地的走獸，並天空的飛鳥，他都交付你手，使你掌管這一切。你就是那金頭。","notes":[]},{"n":39,"t":"在你以後必另興一國，不及於你；又有第三國，就是銅的，必掌管天下。","notes":[]},{"n":40,"t":"第四國，必堅壯如鐵，鐵能打碎剋制百物，又能壓碎一切，那國也必打碎壓制列國。","notes":[]},{"n":41,"t":"你既見像的腳和腳指頭，一半是窯匠的泥，一半是鐵，那國將來也必分開。你既見鐵與泥攙雜，那國也必有鐵的力量。","notes":[]},{"n":42,"t":"那腳指頭，既是半鐵半泥，那國也必半強半弱。","notes":[]},{"n":43,"t":"你既見鐵與泥攙雜，那國民也必與各種人攙雜，卻不能彼此相合，正如鐵與泥不能相合一樣。","notes":[]},{"n":44,"t":"當那列王在位的時候，天上的神必另立一國，永不敗壞，也不歸別國的人，卻要打碎滅絕那一切國，這國必存到永遠。","notes":[]},{"n":45,"t":"你既看見非人手鑿出來的一塊石頭從山而出，打碎金、銀、銅、鐵、泥，那就是至大的神把後來必有的事給王指明。這夢準是這樣，這講解也是確實的。」","notes":[]},{"n":46,"t":"當時，尼布甲尼撒王俯伏在地，向但以理下拜，並且吩咐人給他奉上供物和香品。","notes":[],"heads":["王獎賞但以理"]},{"n":47,"t":"王對但以理說：「你既能顯明這奧祕的事，你們的神誠然是萬神之神、萬王之主，又是顯明奧祕事的。」","notes":[]},{"n":48,"t":"於是王高抬但以理，賞賜他許多上等禮物，派他管理巴比倫全省，又立他為總理，掌管巴比倫的一切哲士。","notes":[]},{"n":49,"t":"但以理求王，王就派沙得拉、米煞、亞伯尼歌管理巴比倫省的事務，只是但以理常在朝中侍立。","notes":[]}]},"3":{"heading":"尼布甲尼撒下令拜金像","verses":[{"n":1,"t":"尼布甲尼撒王造了一個金像，高六十肘，寬六肘，立在巴比倫省杜拉平原。","notes":[]},{"n":2,"t":"尼布甲尼撒王差人將總督、欽差、巡撫、臬司、藩司、謀士、法官，和各省的官員都召了來，為尼布甲尼撒王所立的像行開光之禮。","notes":[]},{"n":3,"t":"於是總督、欽差、巡撫、臬司、藩司、謀士、法官，和各省的官員都聚集了來，要為尼布甲尼撒王所立的像行開光之禮，就站在尼布甲尼撒所立的像前。","notes":[]},{"n":4,"t":"那時傳令的大聲呼叫說：「各方、各國、各族的人哪，有令傳與你們：","notes":["原文是舌；下同"]},{"n":5,"t":"你們一聽見角、笛、琵琶、琴、瑟、笙，和各樣樂器的聲音，就當俯伏敬拜尼布甲尼撒王所立的金像。","notes":[]},{"n":6,"t":"凡不俯伏敬拜的，必立時扔在烈火的窯中。」","notes":[]},{"n":7,"t":"因此各方、各國、各族的人民一聽見角、笛、琵琶、琴、瑟，和各樣樂器的聲音，就都俯伏敬拜尼布甲尼撒王所立的金像。","notes":[]},{"n":8,"t":"那時，有幾個迦勒底人進前來控告猶大人。","notes":[],"heads":["但以理的三個朋友被控違令"]},{"n":9,"t":"他們對尼布甲尼撒王說：「願王萬歲！","notes":[]},{"n":10,"t":"王啊，你曾降旨說，凡聽見角、笛、琵琶、琴、瑟、笙，和各樣樂器聲音的都當俯伏敬拜金像。","notes":[]},{"n":11,"t":"凡不俯伏敬拜的，必扔在烈火的窯中。","notes":[]},{"n":12,"t":"現在有幾個猶大人，就是王所派管理巴比倫省事務的沙得拉、米煞、亞伯尼歌；王啊，這些人不理你，不事奉你的神，也不敬拜你所立的金像。」","notes":[]},{"n":13,"t":"當時，尼布甲尼撒沖沖大怒，吩咐人把沙得拉、米煞、亞伯尼歌帶過來，他們就把那些人帶到王面前。","notes":[]},{"n":14,"t":"尼布甲尼撒問他們說：「沙得拉、米煞、亞伯尼歌，你們不事奉我的神，也不敬拜我所立的金像，是故意的嗎？","notes":[]},{"n":15,"t":"你們再聽見角、笛、琵琶、琴、瑟、笙，和各樣樂器的聲音，若俯伏敬拜我所造的像，卻還可以；若不敬拜，必立時扔在烈火的窯中，有何神能救你們脫離我手呢？」","notes":[]},{"n":16,"t":"沙得拉、米煞、亞伯尼歌對王說：「尼布甲尼撒啊，這件事我們不必回答你，","notes":[]},{"n":17,"t":"即便如此，我們所事奉的神能將我們從烈火的窯中救出來。王啊，他也必救我們脫離你的手；","notes":[]},{"n":18,"t":"即或不然，王啊，你當知道我們決不事奉你的神，也不敬拜你所立的金像。」","notes":[]},{"n":19,"t":"當時，尼布甲尼撒怒氣填胸，向沙得拉、米煞、亞伯尼歌變了臉色，吩咐人把窯燒熱，比尋常更加七倍；","notes":[],"heads":["但以理的三個朋友被扔進火窯"]},{"n":20,"t":"又吩咐他軍中的幾個壯士，將沙得拉、米煞、亞伯尼歌捆起來，扔在烈火的窯中。","notes":[]},{"n":21,"t":"這三人穿著褲子、內袍、外衣，和別的衣服，被捆起來扔在烈火的窯中。","notes":[]},{"n":22,"t":"因為王命緊急，窯又甚熱，那抬沙得拉、米煞、亞伯尼歌的人都被火焰燒死。","notes":[]},{"n":23,"t":"沙得拉、米煞、亞伯尼歌這三個人都被捆著落在烈火的窯中。","notes":[]},{"n":24,"t":"那時，尼布甲尼撒王驚奇，急忙起來，對謀士說：「我們捆起來扔在火裏的不是三個人嗎？」他們回答王說：「王啊，是。」","notes":[]},{"n":25,"t":"王說：「看哪，我見有四個人，並沒有捆綁，在火中遊行，也沒有受傷；那第四個的相貌好像神子。」","notes":[]},{"n":26,"t":"於是，尼布甲尼撒就近烈火窯門，說：「至高神的僕人沙得拉、米煞、亞伯尼歌出來，上這裏來吧！」沙得拉、米煞、亞伯尼歌就從火中出來了。","notes":[],"heads":["三人獲釋且得高升"]},{"n":27,"t":"那些總督、欽差、巡撫，和王的謀士一同聚集看這三個人，見火無力傷他們的身體，頭髮也沒有燒焦，衣裳也沒有變色，並沒有火燎的氣味。","notes":[]},{"n":28,"t":"尼布甲尼撒說：「沙得拉、米煞、亞伯尼歌的神是應當稱頌的！他差遣使者救護倚靠他的僕人，他們不遵王命，捨去己身，在他們神以外不肯事奉敬拜別神。","notes":[]},{"n":29,"t":"現在我降旨，無論何方、何國、何族的人，謗讟沙得拉、米煞、亞伯尼歌之神的，必被凌遲，他的房屋必成糞堆，因為沒有別神能這樣施行拯救。」","notes":[]},{"n":30,"t":"那時王在巴比倫省，高升了沙得拉、米煞、亞伯尼歌。","notes":[]}]},"4":{"heading":"尼布甲尼撒的第二個夢","verses":[{"n":1,"t":"尼布甲尼撒王曉諭住在全地各方、各國、各族的人說：「願你們大享平安！","notes":[]},{"n":2,"t":"我樂意將至高的神向我所行的神蹟奇事宣揚出來。","notes":[]},{"n":3,"t":"他的神蹟何其大！他的奇事何其盛！他的國是永遠的；他的權柄存到萬代！","notes":[]},{"n":4,"t":"「我－尼布甲尼撒安居在宮中，平順在殿內。","notes":[]},{"n":5,"t":"我做了一夢，使我懼怕。我在床上的思念，並腦中的異象，使我驚惶。","notes":[]},{"n":6,"t":"所以我降旨召巴比倫的一切哲士到我面前，叫他們把夢的講解告訴我。","notes":[]},{"n":7,"t":"於是那些術士、用法術的、迦勒底人、觀兆的都進來，我將那夢告訴了他們，他們卻不能把夢的講解告訴我。","notes":[]},{"n":8,"t":"末後那照我神的名，稱為伯提沙撒的但以理來到我面前，他裏頭有聖神的靈，我將夢告訴他說：","notes":[]},{"n":9,"t":"『術士的領袖伯提沙撒啊，因我知道你裏頭有聖神的靈，甚麼奧祕的事都不能使你為難。現在要把我夢中所見的異象和夢的講解告訴我。』","notes":[]},{"n":10,"t":"「我在床上腦中的異象是這樣：我看見地當中有一棵樹，極其高大。","notes":[]},{"n":11,"t":"那樹漸長，而且堅固，高得頂天，從地極都能看見，","notes":[]},{"n":12,"t":"葉子華美，果子甚多，可作眾生的食物；田野的走獸臥在蔭下，天空的飛鳥宿在枝上；凡有血氣的都從這樹得食。","notes":[]},{"n":13,"t":"「我在床上腦中的異象，見有一位守望的聖者從天而降。","notes":[]},{"n":14,"t":"大聲呼叫說：『伐倒這樹！砍下枝子！搖掉葉子！拋散果子！使走獸離開樹下，飛鳥躲開樹枝。","notes":[]},{"n":15,"t":"樹墩卻要留在地內，用鐵圈和銅圈箍住，在田野的青草中讓天露滴濕，使他與地上的獸一同吃草，","notes":[]},{"n":16,"t":"使他的心改變，不如人心，給他一個獸心，使他經過七期。","notes":["期：或譯年；本章同"]},{"n":17,"t":"這是守望者所發的命，聖者所出的令，好叫世人知道至高者在人的國中掌權，要將國賜與誰就賜與誰，或立極卑微的人執掌國權。』","notes":[]},{"n":18,"t":"「這是我－尼布甲尼撒王所做的夢。伯提沙撒啊，你要說明這夢的講解；因為我國中的一切哲士都不能將夢的講解告訴我，惟獨你能，因你裏頭有聖神的靈。」","notes":[]},{"n":19,"t":"於是稱為伯提沙撒的但以理驚訝片時，心意驚惶。王說：「伯提沙撒啊，不要因夢和夢的講解驚惶。」伯提沙撒回答說：「我主啊，願這夢歸與恨惡你的人，講解歸與你的敵人。","notes":[],"heads":["但以理解夢"]},{"n":20,"t":"你所見的樹漸長，而且堅固，高得頂天，從地極都能看見；","notes":[]},{"n":21,"t":"葉子華美，果子甚多，可作眾生的食物；田野的走獸住在其下；天空的飛鳥宿在枝上。","notes":[]},{"n":22,"t":"「王啊，這漸長又堅固的樹就是你。你的威勢漸長及天，你的權柄管到地極。","notes":[]},{"n":23,"t":"王既看見一位守望的聖者從天而降，說：『將這樹砍伐毀壞，樹墩卻要留在地內，用鐵圈和銅圈箍住；在田野的青草中，讓天露滴濕，使他與地上的獸一同吃草，直到經過七期。』","notes":[]},{"n":24,"t":"「王啊，講解就是這樣：臨到我主我王的事是出於至高者的命。","notes":[]},{"n":25,"t":"你必被趕出離開世人，與野地的獸同居，吃草如牛，被天露滴濕，且要經過七期。等你知道至高者在人的國中掌權，要將國賜與誰就賜與誰。","notes":[]},{"n":26,"t":"守望者既吩咐存留樹墩，等你知道諸天掌權，以後你的國必定歸你。","notes":[]},{"n":27,"t":"王啊，求你悅納我的諫言，以施行公義斷絕罪過，以憐憫窮人除掉罪孽，或者你的平安可以延長。」","notes":[]},{"n":28,"t":"這事都臨到尼布甲尼撒王。","notes":[]},{"n":29,"t":"過了十二個月，他遊行在巴比倫王宮裏。","notes":["原文是上"]},{"n":30,"t":"他說：「這大巴比倫不是我用大能大力建為京都，要顯我威嚴的榮耀嗎？」","notes":[]},{"n":31,"t":"這話在王口中尚未說完，有聲音從天降下，說：「尼布甲尼撒王啊，有話對你說，你的國位離開你了。","notes":[]},{"n":32,"t":"你必被趕出離開世人，與野地的獸同居，吃草如牛，且要經過七期。等你知道至高者在人的國中掌權，要將國賜與誰就賜與誰。」","notes":[]},{"n":33,"t":"當時這話就應驗在尼布甲尼撒的身上，他被趕出離開世人，吃草如牛，身被天露滴濕，頭髮長長，好像鷹毛；指甲長長，如同鳥爪。","notes":[]},{"n":34,"t":"日子滿足，我－尼布甲尼撒舉目望天，我的聰明復歸於我，我便稱頌至高者，讚美尊敬活到永遠的神。他的權柄是永有的；他的國存到萬代。","notes":[],"heads":["尼布甲尼撒頌讚神"]},{"n":35,"t":"世上所有的居民都算為虛無；在天上的萬軍和世上的居民中，他都憑自己的意旨行事。無人能攔住他手，或問他說，你做甚麼呢？","notes":[]},{"n":36,"t":"那時，我的聰明復歸於我，為我國的榮耀、威嚴，和光耀也都復歸於我；並且我的謀士和大臣也來朝見我。我又得堅立在國位上，至大的權柄加增於我。","notes":[]},{"n":37,"t":"現在我－尼布甲尼撒讚美、尊崇、恭敬天上的王；因為他所做的全都誠實，他所行的也都公平。那行動驕傲的，他能降為卑。","notes":[]}]},"5":{"heading":"伯沙撒王的宴會","verses":[{"n":1,"t":"伯沙撒王為他的一千大臣設擺盛筵，與這一千人對面飲酒。","notes":[]},{"n":2,"t":"伯沙撒歡飲之間，吩咐人將他父尼布甲尼撒從耶路撒冷殿中所掠的金銀器皿拿來，王與大臣、皇后、妃嬪好用這器皿飲酒。","notes":["或譯：祖；下同"]},{"n":3,"t":"於是他們把耶路撒冷神殿庫房中所掠的金器皿拿來，王和大臣、皇后、妃嬪就用這器皿飲酒。","notes":[]},{"n":4,"t":"他們飲酒，讚美金、銀、銅、鐵、木、石所造的神。","notes":[]},{"n":5,"t":"當時，忽有人的指頭顯出，在王宮與燈臺相對的粉牆上寫字。王看見寫字的指頭","notes":[]},{"n":6,"t":"就變了臉色，心意驚惶，腰骨好像脫節，雙膝彼此相碰，","notes":[]},{"n":7,"t":"大聲吩咐將用法術的和迦勒底人並觀兆的領進來，對巴比倫的哲士說，誰能讀這文字，把講解告訴我，他必身穿紫袍，項帶金鍊，在我國中位列第三。","notes":[]},{"n":8,"t":"於是王的一切哲士都進來，卻不能讀那文字，也不能把講解告訴王。","notes":[]},{"n":9,"t":"伯沙撒王就甚驚惶，臉色改變，他的大臣也都驚奇。","notes":[]},{"n":10,"t":"太后因王和他大臣所說的話，就進入宴宮，說：「願王萬歲！你心意不要驚惶，臉面不要變色。","notes":["或譯：皇后；下同"]},{"n":11,"t":"在你國中有一人，他裏頭有聖神的靈，你父在世的日子，這人心中光明，又有聰明智慧，好像神的智慧。你父尼布甲尼撒王，就是王的父，立他為術士、用法術的，和迦勒底人，並觀兆的領袖。","notes":[]},{"n":12,"t":"在他裏頭有美好的靈性，又有知識聰明，能圓夢，釋謎語，解疑惑。這人名叫但以理，尼布甲尼撒王又稱他為伯提沙撒，現在可以召他來，他必解明這意思。」","notes":[]},{"n":13,"t":"但以理就被領到王前。王問但以理說：「你是被擄之猶大人中的但以理嗎？就是我父王從猶大擄來的嗎？","notes":[],"heads":["但以理解釋牆上的字"]},{"n":14,"t":"我聽說你裏頭有神的靈，心中光明，又有聰明和美好的智慧。","notes":[]},{"n":15,"t":"現在哲士和用法術的都領到我面前，為叫他們讀這文字，把講解告訴我，無奈他們都不能把講解說出來。","notes":[]},{"n":16,"t":"我聽說你善於講解，能解疑惑；現在你若能讀這文字，把講解告訴我，就必身穿紫袍，項戴金鍊，在我國中位列第三。」","notes":[]},{"n":17,"t":"但以理在王面前回答說：「你的贈品可以歸你自己，你的賞賜可以歸給別人；我卻要為王讀這文字，把講解告訴王。","notes":[]},{"n":18,"t":"王啊，至高的神曾將國位、大權、榮耀、威嚴賜與你父尼布甲尼撒；","notes":[]},{"n":19,"t":"因神所賜他的大權，各方、各國、各族的人都在他面前戰兢恐懼。他可以隨意生殺，隨意升降。","notes":[]},{"n":20,"t":"但他心高氣傲，靈也剛愎，甚至行事狂傲，就被革去王位，奪去榮耀。","notes":[]},{"n":21,"t":"他被趕出離開世人，他的心變如獸心，與野驢同居，吃草如牛，身被天露滴濕，等他知道至高的神在人的國中掌權，憑自己的意旨立人治國。","notes":[]},{"n":22,"t":"伯沙撒啊，你是他的兒子，你雖知道這一切，你心仍不自卑，","notes":["或譯：孫子"]},{"n":23,"t":"竟向天上的主自高，使人將他殿中的器皿拿到你面前，你和大臣、皇后、妃嬪用這器皿飲酒。你又讚美那不能看、不能聽、無知無識、金、銀、銅、鐵、木、石所造的神，卻沒有將榮耀歸與那手中有你氣息，管理你一切行動的神。","notes":[]},{"n":24,"t":"因此從神那裏顯出指頭來寫這文字。","notes":[]},{"n":25,"t":"「所寫的文字是：『彌尼，彌尼，提客勒，烏法珥新。』","notes":[]},{"n":26,"t":"講解是這樣：彌尼，就是神已經數算你國的年日到此完畢。","notes":[]},{"n":27,"t":"提客勒，就是你被稱在天平裏，顯出你的虧欠。","notes":[]},{"n":28,"t":"毗勒斯，就是你的國分裂，歸與米底亞人和波斯人。」","notes":["與烏法珥新同義"]},{"n":29,"t":"伯沙撒下令，人就把紫袍給但以理穿上，把金鍊給他戴在頸項上，又傳令使他在國中位列第三。","notes":[]},{"n":30,"t":"當夜，迦勒底王伯沙撒被殺。","notes":[]},{"n":31,"t":"米底亞人大流士年六十二歲，取了迦勒底國。","notes":[]}]},"6":{"heading":"但以理在獅子坑中","verses":[{"n":1,"t":"大流士隨心所願，立一百二十個總督，治理通國。","notes":[]},{"n":2,"t":"又在他們以上立總長三人（但以理在其中），使總督在他們三人面前回覆事務，免得王受虧損。","notes":[]},{"n":3,"t":"因這但以理有美好的靈性，所以顯然超乎其餘的總長和總督，王又想立他治理通國。","notes":[]},{"n":4,"t":"那時，總長和總督尋找但以理誤國的把柄，為要參他；只是找不著他的錯誤過失，因他忠心辦事，毫無錯誤過失。","notes":[]},{"n":5,"t":"那些人便說：「我們要找參這但以理的把柄，除非在他神的律法中就尋不著。」","notes":[]},{"n":6,"t":"於是，總長和總督紛紛聚集來見王，說：「願大流士王萬歲！","notes":[]},{"n":7,"t":"國中的總長、欽差、總督、謀士，和巡撫彼此商議，要立一條堅定的禁令，三十日內，不拘何人，若在王以外，或向神或向人求甚麼，就必扔在獅子坑中。","notes":["或譯：求王下旨要立一條<ins>.</ins>."]},{"n":8,"t":"王啊，現在求你立這禁令，加蓋玉璽，使禁令決不更改；照米底亞和波斯人的例是不可更改的。」","notes":[]},{"n":9,"t":"於是大流士王立這禁令，加蓋玉璽。","notes":[]},{"n":10,"t":"但以理知道這禁令蓋了玉璽，就到自己家裏（他樓上的窗戶開向耶路撒冷），一日三次，雙膝跪在他神面前，禱告感謝，與素常一樣。","notes":[]},{"n":11,"t":"那些人就紛紛聚集，見但以理在他神面前祈禱懇求。","notes":[]},{"n":12,"t":"他們便進到王前，提王的禁令，說：「王啊，三十日內不拘何人，若在王以外，或向神或向人求甚麼，必被扔在獅子坑中。王不是在這禁令上蓋了玉璽嗎？」王回答說：「實有這事，照米底亞和波斯人的例是不可更改的。」","notes":[]},{"n":13,"t":"他們對王說：「王啊，那被擄之猶大人中的但以理不理你，也不遵你蓋了玉璽的禁令，他竟一日三次祈禱。」","notes":[]},{"n":14,"t":"王聽見這話，就甚愁煩，一心要救但以理，籌劃解救他，直到日落的時候。","notes":[]},{"n":15,"t":"那些人就紛紛聚集來見王，說：「王啊，當知道米底亞人和波斯人有例，凡王所立的禁令和律例都不可更改。」","notes":[]},{"n":16,"t":"王下令，人就把但以理帶來，扔在獅子坑中。王對但以理說：「你所常事奉的神，他必救你。」","notes":[]},{"n":17,"t":"有人搬石頭放在坑口，王用自己的璽和大臣的印，封閉那坑，使懲辦但以理的事毫無更改。","notes":[]},{"n":18,"t":"王回宮，終夜禁食，無人拿樂器到他面前，並且睡不著覺。","notes":[]},{"n":19,"t":"次日黎明，王就起來，急忙往獅子坑那裏去。","notes":[]},{"n":20,"t":"臨近坑邊，哀聲呼叫但以理，對但以理說：「永生神的僕人但以理啊，你所常事奉的神能救你脫離獅子嗎？」","notes":[]},{"n":21,"t":"但以理對王說：「願王萬歲！","notes":[]},{"n":22,"t":"我的神差遣使者，封住獅子的口，叫獅子不傷我；因我在神面前無辜，我在王面前也沒有行過虧損的事。」","notes":[]},{"n":23,"t":"王就甚喜樂，吩咐人將但以理從坑裏繫上來。於是但以理從坑裏被繫上來，身上毫無傷損，因為信靠他的神。","notes":[]},{"n":24,"t":"王下令，人就把那些控告但以理的人，連他們的妻子兒女都帶來，扔在獅子坑中。他們還沒有到坑底，獅子就抓住他們，咬碎他們的骨頭。","notes":["原文是勝了"]},{"n":25,"t":"那時，大流士王傳旨，曉諭住在全地各方、各國、各族的人說：「願你們大享平安！","notes":[]},{"n":26,"t":"現在我降旨曉諭我所統轄的全國人民，要在但以理的神面前，戰兢恐懼。因為他是永遠長存的活神，他的國永不敗壞；他的權柄永存無極！","notes":[]},{"n":27,"t":"他護庇人，搭救人，在天上地下施行神蹟奇事，救了但以理脫離獅子的口。」","notes":[]},{"n":28,"t":"如此，這但以理，當大流士王在位的時候和波斯王塞魯士在位的時候，大享亨通。","notes":[]}]},"7":{"heading":"但以理敘述異象","verses":[{"n":1,"t":"巴比倫王伯沙撒元年，但以理在床上做夢，見了腦中的異象，就記錄這夢，述說其中的大意。","notes":[],"heads":["四獸的異象"]},{"n":2,"t":"但以理說：我夜裏見異象，看見天的四風陡起，颳在大海之上。","notes":[]},{"n":3,"t":"有四個大獸從海中上來，形狀各有不同：","notes":[]},{"n":4,"t":"頭一個像獅子，有鷹的翅膀；我正觀看的時候，獸的翅膀被拔去，獸從地上得立起來，用兩腳站立，像人一樣，又得了人心。","notes":[]},{"n":5,"t":"又有一獸如熊，就是第二獸，旁跨而坐，口齒內啣著三根肋骨。有吩咐這獸的說：「起來吞吃多肉。」","notes":[]},{"n":6,"t":"此後我觀看，又有一獸如豹，背上有鳥的四個翅膀；這獸有四個頭，又得了權柄。","notes":[]},{"n":7,"t":"其後我在夜間的異象中觀看，見第四獸甚是可怕，極其強壯，大有力量，有大鐵牙，吞吃嚼碎，所剩下的用腳踐踏。這獸與前三獸大不相同，頭有十角。","notes":[]},{"n":8,"t":"我正觀看這些角，見其中又長起一個小角；先前的角中有三角在這角前，連根被牠拔出來。這角有眼，像人的眼，有口說誇大的話。","notes":[]},{"n":9,"t":"我觀看，見有寶座設立，上頭坐著亙古常在者。他的衣服潔白如雪，頭髮如純淨的羊毛。寶座乃火焰，其輪乃烈火。","notes":[],"heads":["永存者的異象"]},{"n":10,"t":"從他面前有火，像河發出；事奉他的有千千，在他面前侍立的有萬萬；他坐著要行審判，案卷都展開了。","notes":[]},{"n":11,"t":"那時我觀看，見那獸因小角說誇大話的聲音被殺，身體損壞，扔在火中焚燒。","notes":[]},{"n":12,"t":"其餘的獸，權柄都被奪去，生命卻仍存留，直到所定的時候和日期。","notes":[]},{"n":13,"t":"我在夜間的異象中觀看，見有一位像人子的，駕著天雲而來，被領到亙古常在者面前，","notes":[]},{"n":14,"t":"得了權柄、榮耀、國度，使各方、各國、各族的人都事奉他。他的權柄是永遠的，不能廢去；他的國必不敗壞。","notes":[]},{"n":15,"t":"至於我－但以理，我的靈在我裏面愁煩，我腦中的異象使我驚惶。","notes":[],"heads":["解釋異象"]},{"n":16,"t":"我就近一位侍立者，問他這一切的真情。他就告訴我，將那事的講解給我說明：","notes":[]},{"n":17,"t":"這四個大獸就是四王將要在世上興起。","notes":[]},{"n":18,"t":"然而，至高者的聖民，必要得國享受，直到永永遠遠。","notes":[]},{"n":19,"t":"那時我願知道第四獸的真情，牠為何與那三獸的真情大不相同，甚是可怕，有鐵牙銅爪，吞吃嚼碎，所剩下的用腳踐踏；","notes":[]},{"n":20,"t":"頭有十角和那另長的一角，在這角前有三角被牠打落。這角有眼，有說誇大話的口，形狀強橫，過於牠的同類。","notes":[]},{"n":21,"t":"我觀看，見這角與聖民爭戰，勝了他們。","notes":[]},{"n":22,"t":"直到亙古常在者來給至高者的聖民伸冤，聖民得國的時候就到了。","notes":[]},{"n":23,"t":"那侍立者這樣說：第四獸就是世上必有的第四國，與一切國大不相同，必吞吃全地，並且踐踏嚼碎。","notes":[]},{"n":24,"t":"至於那十角，就是從這國中必興起的十王，後來又興起一王，與先前的不同；他必制伏三王。","notes":[]},{"n":25,"t":"他必向至高者說誇大的話，必折磨至高者的聖民，必想改變節期和律法。聖民必交付他手一載、二載、半載。","notes":[]},{"n":26,"t":"然而，審判者必坐著行審判；他的權柄必被奪去，毀壞，滅絕，一直到底。","notes":[]},{"n":27,"t":"國度、權柄，和天下諸國的大權必賜給至高者的聖民。他的國是永遠的；一切掌權的都必事奉他，順從他。","notes":[]},{"n":28,"t":"那事至此完畢。至於我－但以理，心中甚是驚惶，臉色也改變了，卻將那事存記在心。","notes":[]}]},"8":{"heading":"公綿羊、公山羊的異象","verses":[{"n":1,"t":"伯沙撒王在位第三年，有異象現與我－但以理，是在先前所見的異象之後。","notes":[]},{"n":2,"t":"我見了異象的時候，我以為在以攔省書珊城中；我見異象又如在烏萊河邊。","notes":["或譯：宮"]},{"n":3,"t":"我舉目觀看，見有雙角的公綿羊站在河邊，兩角都高。這角高過那角，更高的是後長的。","notes":[]},{"n":4,"t":"我見那公綿羊往西、往北、往南牴觸。獸在牠面前都站立不住，也沒有能救護脫離牠手的；但牠任意而行，自高自大。","notes":[]},{"n":5,"t":"我正思想的時候，見有一隻公山羊從西而來，遍行全地，腳不沾塵。這山羊兩眼當中有一非常的角。","notes":[]},{"n":6,"t":"牠往我所看見、站在河邊有雙角的公綿羊那裏去，大發忿怒，向牠直闖。","notes":[]},{"n":7,"t":"我見公山羊就近公綿羊，向牠發烈怒，牴觸牠，折斷牠的兩角。綿羊在牠面前站立不住；牠將綿羊觸倒在地，用腳踐踏，沒有能救綿羊脫離牠手的。","notes":[]},{"n":8,"t":"這山羊極其自高自大，正強盛的時候，那大角折斷了，又在角根上向天的四方長出四個非常的角來。","notes":["原文是風"]},{"n":9,"t":"四角之中有一角長出一個小角，向南、向東、向榮美之地，漸漸成為強大。","notes":[]},{"n":10,"t":"牠漸漸強大，高及天象，將些天象和星宿拋落在地，用腳踐踏。","notes":[]},{"n":11,"t":"並且牠自高自大，以為高及天象之君；除掉常獻給君的燔祭，毀壞君的聖所。","notes":[]},{"n":12,"t":"因罪過的緣故，有軍旅和常獻的燔祭交付牠。牠將真理拋在地上，任意而行，無不順利。","notes":[]},{"n":13,"t":"我聽見有一位聖者說話，又有一位聖者問那說話的聖者說：「這除掉常獻的燔祭和施行毀壞的罪過，將聖所與軍旅踐踏的異象，要到幾時才應驗呢？」","notes":["或譯：以色列的軍"]},{"n":14,"t":"他對我說：「到二千三百日，聖所就必潔淨。」","notes":[]},{"n":15,"t":"我－但以理見了這異象，願意明白其中的意思。忽有一位形狀像人的站在我面前。","notes":[],"heads":["天使加百列解釋異象"]},{"n":16,"t":"我又聽見烏萊河兩岸中有人聲呼叫說：「加百列啊，要使此人明白這異象。」","notes":[]},{"n":17,"t":"他便來到我所站的地方。他一來，我就驚慌俯伏在地；他對我說：「人子啊，你要明白，因為這是關乎末後的異象。」","notes":[]},{"n":18,"t":"他與我說話的時候，我面伏在地沉睡；他就摸我，扶我站起來，","notes":[]},{"n":19,"t":"說：「我要指示你惱怒臨完必有的事，因為這是關乎末後的定期。","notes":[]},{"n":20,"t":"你所看見雙角的公綿羊，就是米底亞和波斯王。","notes":[]},{"n":21,"t":"那公山羊就是希臘王；兩眼當中的大角就是頭一王。","notes":["希臘：原文是雅完；下同"]},{"n":22,"t":"至於那折斷了的角，在其根上又長出四角，這四角就是四國，必從這國裏興起來，只是權勢都不及他。","notes":[]},{"n":23,"t":"這四國末時，犯法的人罪惡滿盈，必有一王興起，面貌凶惡，能用雙關的詐語。","notes":[]},{"n":24,"t":"他的權柄必大，卻不是因自己的能力；他必行非常的毀滅，事情順利，任意而行；又必毀滅有能力的和聖民。","notes":[]},{"n":25,"t":"他用權術成就手中的詭計，心裏自高自大，在人坦然無備的時候，毀滅多人；又要站起來攻擊萬君之君，至終卻非因人手而滅亡。","notes":[]},{"n":26,"t":"所說二千三百日的異象是真的，但你要將這異象封住，因為關乎後來許多的日子。」","notes":[]},{"n":27,"t":"於是我－但以理昏迷不醒，病了數日，然後起來辦理王的事務。我因這異象驚奇，卻無人能明白其中的意思。","notes":[]}]},"9":{"heading":"但以理為同胞禱告","verses":[{"n":1,"t":"米底亞族亞哈隨魯的兒子大流士立為迦勒底國的王元年，","notes":[]},{"n":2,"t":"就是他在位第一年，我－但以理從書上得知耶和華的話臨到先知耶利米，論耶路撒冷荒涼的年數，七十年為滿。","notes":[]},{"n":3,"t":"我便禁食，披麻蒙灰，定意向主神祈禱懇求。","notes":[]},{"n":4,"t":"我向耶和華－我的神祈禱、認罪，說：「主啊，大而可畏的神，向愛主、守主誡命的人守約施慈愛。","notes":[]},{"n":5,"t":"我們犯罪作孽，行惡叛逆，偏離你的誡命典章，","notes":[]},{"n":6,"t":"沒有聽從你僕人眾先知奉你名向我們君王、首領、列祖，和國中一切百姓所說的話。","notes":[]},{"n":7,"t":"主啊，你是公義的，我們是臉上蒙羞的；因我們猶大人和耶路撒冷的居民，並以色列眾人，或在近處，或在遠處，被你趕到各國的人，都得罪了你，正如今日一樣。","notes":[]},{"n":8,"t":"主啊，我們和我們的君王、首領、列祖因得罪了你，就都臉上蒙羞。","notes":[]},{"n":9,"t":"主－我們的神是憐憫饒恕人的，我們卻違背了他，","notes":[]},{"n":10,"t":"也沒有聽從耶和華－我們神的話，沒有遵行他藉僕人眾先知向我們所陳明的律法。","notes":[]},{"n":11,"t":"以色列眾人都犯了你的律法，偏行，不聽從你的話；因此，在你僕人摩西律法上所寫的咒詛和誓言都傾在我們身上，因我們得罪了神。","notes":[]},{"n":12,"t":"他使大災禍臨到我們，成就了警戒我們和審判我們官長的話；原來在普天之下未曾行過像在耶路撒冷所行的。","notes":[]},{"n":13,"t":"這一切災禍臨到我們身上是照摩西律法上所寫的，我們卻沒有求耶和華－我們神的恩典，使我們回頭離開罪孽，明白你的真理。","notes":[]},{"n":14,"t":"所以耶和華留意使這災禍臨到我們身上，因為耶和華－我們的神在他所行的事上都是公義；我們並沒有聽從他的話。","notes":[]},{"n":15,"t":"主－我們的神啊，你曾用大能的手領你的子民出埃及地，使自己得了名，正如今日一樣。我們犯了罪，作了惡。","notes":[]},{"n":16,"t":"主啊，求你按你的大仁大義，使你的怒氣和忿怒轉離你的城耶路撒冷，就是你的聖山。耶路撒冷和你的子民，因我們的罪惡和我們列祖的罪孽被四圍的人羞辱。","notes":[]},{"n":17,"t":"我們的神啊，現在求你垂聽僕人的祈禱懇求，為自己使臉光照你荒涼的聖所。","notes":[]},{"n":18,"t":"我的神啊，求你側耳而聽，睜眼而看，眷顧我們荒涼之地和稱為你名下的城。我們在你面前懇求，原不是因自己的義，乃因你的大憐憫。","notes":[]},{"n":19,"t":"求主垂聽，求主赦免，求主應允而行，為你自己不要遲延。我的神啊，因這城和這民都是稱為你名下的。」","notes":[]},{"n":20,"t":"我說話，禱告，承認我的罪和本國之民以色列的罪，為我神的聖山，在耶和華－我神面前懇求。","notes":[],"heads":["加百列解釋預言"]},{"n":21,"t":"我正禱告的時候，先前在異象中所見的那位加百列，奉命迅速飛來，約在獻晚祭的時候，按手在我身上。","notes":[]},{"n":22,"t":"他指教我說：「但以理啊，現在我出來要使你有智慧，有聰明。","notes":[]},{"n":23,"t":"你初懇求的時候，就發出命令，我來告訴你，因你大蒙眷愛；所以你要思想明白這以下的事和異象。","notes":[]},{"n":24,"t":"「為你本國之民和你聖城，已經定了七十個七。要止住罪過，除淨罪惡，贖盡罪孽，引進永義，封住異象和預言，並膏至聖者。","notes":["或譯：彰顯","者：或譯所"]},{"n":25,"t":"你當知道，當明白，從出令重新建造耶路撒冷，直到有受膏君的時候，必有七個七和六十二個七。正在艱難的時候，耶路撒冷城連街帶濠都必重新建造。","notes":[]},{"n":26,"t":"過了六十二個七，那受膏者必被剪除，一無所有；必有一王的民來毀滅這城和聖所，至終必如洪水沖沒。必有爭戰，一直到底，荒涼的事已經定了。","notes":["或譯：有"]},{"n":27,"t":"一七之內，他必與許多人堅定盟約；一七之半，他必使祭祀與供獻止息。那行毀壞可憎的如飛而來，並且有忿怒傾在那行毀壞的身上，直到所定的結局。」","notes":["或譯：使地荒涼的","或譯：傾在那荒涼之地"]}]},"10":{"heading":"底格里斯大河邊的異象","verses":[{"n":1,"t":"波斯王塞魯士第三年，有事顯給稱為伯提沙撒的但以理。這事是真的，是指著大爭戰；但以理通達這事，明白這異象。","notes":[]},{"n":2,"t":"當那時，我－但以理悲傷了三個七日。","notes":[]},{"n":3,"t":"美味我沒有吃，酒肉沒有入我的口，也沒有用油抹我的身，直到滿了三個七日。","notes":[]},{"n":4,"t":"正月二十四日，我在底格里斯大河邊，","notes":[]},{"n":5,"t":"舉目觀看，見有一人身穿細麻衣，腰束烏法精金帶。","notes":[]},{"n":6,"t":"他身體如水蒼玉，面貌如閃電，眼目如火把，手和腳如光明的銅，說話的聲音如大眾的聲音。","notes":[]},{"n":7,"t":"這異象惟有我－但以理一人看見，同著我的人沒有看見。他們卻大大戰兢，逃跑隱藏，","notes":[]},{"n":8,"t":"只剩下我一人。我見了這大異象便渾身無力，面貌失色，毫無氣力。","notes":[]},{"n":9,"t":"我卻聽見他說話的聲音，一聽見就面伏在地沉睡了。","notes":[]},{"n":10,"t":"忽然，有一手按在我身上，使我用膝和手掌支持微起。","notes":[]},{"n":11,"t":"他對我說：「大蒙眷愛的但以理啊，要明白我與你所說的話，只管站起來，因為我現在奉差遣來到你這裏。」他對我說這話，我便戰戰兢兢地立起來。","notes":[]},{"n":12,"t":"他就說：「但以理啊，不要懼怕！因為從你第一日專心求明白將來的事，又在你神面前刻苦己心，你的言語已蒙應允；我是因你的言語而來。","notes":[]},{"n":13,"t":"但波斯國的魔君攔阻我二十一日。忽然有大君中的一位米迦勒來幫助我，我就停留在波斯諸王那裏。","notes":["就是天使長；二十一節同"]},{"n":14,"t":"現在我來，要使你明白本國之民日後必遭遇的事，因為這異象關乎後來許多的日子。」","notes":[]},{"n":15,"t":"他向我這樣說，我就臉面朝地，啞口無聲。","notes":[]},{"n":16,"t":"不料，有一位像人的，摸我的嘴唇，我便開口向那站在我面前的說：「我主啊，因見這異象，我大大愁苦，毫無氣力。","notes":[]},{"n":17,"t":"我主的僕人怎能與我主說話呢？我一見異象就渾身無力，毫無氣息。」","notes":[]},{"n":18,"t":"有一位形狀像人的又摸我，使我有力量。","notes":[]},{"n":19,"t":"他說：「大蒙眷愛的人哪，不要懼怕，願你平安！你總要堅強。」他一向我說話，我便覺得有力量，說：「我主請說，因你使我有力量。」","notes":[]},{"n":20,"t":"他就說：「你知道我為何來見你嗎？現在我要回去與波斯的魔君爭戰，我去後，希臘的魔君必來。","notes":["原文是雅完"]},{"n":21,"t":"但我要將那錄在真確書上的事告訴你。除了你們的大君米迦勒之外，沒有幫助我抵擋這兩魔君的。」","notes":[]}]},"11":{"heading":"南方王和北方王","verses":[{"n":1,"t":"又說：「當米底亞王大流士元年，我曾起來扶助米迦勒，使他堅強。」","notes":[]},{"n":2,"t":"現在我將真事指示你：「波斯還有三王興起，第四王必富足遠勝諸王。他因富足成為強盛，就必激動大眾攻擊希臘國。","notes":[]},{"n":3,"t":"必有一個勇敢的王興起，執掌大權，隨意而行。","notes":[]},{"n":4,"t":"他興起的時候，他的國必破裂，向天的四方分開，卻不歸他的後裔，治國的權勢也都不及他；因為他的國必被拔出，歸與他後裔之外的人。","notes":["方：原文是風"]},{"n":5,"t":"「南方的王必強盛，他將帥中必有一個比他更強盛，執掌權柄，他的權柄甚大。","notes":[]},{"n":6,"t":"過些年後，他們必互相連合，南方王的女兒必就了北方王來立約；但這女子幫助之力存立不住，王和他所倚靠之力也不能存立。這女子和引導她來的，並生她的，以及當時扶助她的，都必交與死地。","notes":[]},{"n":7,"t":"但這女子的本家必另生一子繼續王位，他必率領軍隊進入北方王的保障，攻擊他們，而且得勝；","notes":["原文是根","子：原文是枝"]},{"n":8,"t":"並將他們的神像和鑄成的偶像，與金銀的寶器掠到埃及去。數年之內，他不去攻擊北方的王。","notes":[]},{"n":9,"t":"北方的王必入南方王的國，卻要仍回本地。","notes":["原文是他"]},{"n":10,"t":"「北方王的二子必動干戈，招聚許多軍兵。這軍兵前去，如洪水氾濫，又必再去爭戰，直到南方王的保障。","notes":["原文是他"]},{"n":11,"t":"南方王必發烈怒，出來與北方王爭戰，擺列大軍；北方王的軍兵必交付他手。","notes":[]},{"n":12,"t":"他的眾軍高傲，他的心也必自高；他雖使數萬人仆倒，卻不得常勝。","notes":[]},{"n":13,"t":"「北方王必回來擺列大軍，比先前的更多。滿了所定的年數，他必率領大軍，帶極多的軍裝來。","notes":[]},{"n":14,"t":"那時，必有許多人起來攻擊南方王，並且你本國的強暴人必興起，要應驗那異象，他們卻要敗亡。","notes":[]},{"n":15,"t":"北方王必來築壘攻取堅固城；南方的軍兵必站立不住，就是選擇的精兵也無力站住。","notes":["原文是民"]},{"n":16,"t":"來攻擊他的，必任意而行，無人在北方王面前站立得住。他必站在那榮美之地，用手施行毀滅。","notes":["原文是他"]},{"n":17,"t":"「他必定意用全國之力而來，立公正的約，照約而行，將自己的女兒給南方王為妻，想要敗壞他，這計卻不得成就，與自己毫無益處。","notes":["或譯：埃及"]},{"n":18,"t":"其後他必轉回奪取了許多海島。但有一大帥，除掉他令人受的羞辱，並且使這羞辱歸他本身。","notes":[]},{"n":19,"t":"他就必轉向本地的保障，卻要絆跌仆倒，歸於無有。","notes":[]},{"n":20,"t":"「那時，必有一人興起接續他為王，使橫征暴斂的人通行國中的榮美地。這王不多日就必滅亡，卻不因忿怒，也不因爭戰。」","notes":[]},{"n":21,"t":"「必有一個卑鄙的人興起接續為王，人未曾將國的尊榮給他，他卻趁人坦然無備的時候，用諂媚的話得國。","notes":[],"heads":["北方的惡王"]},{"n":22,"t":"必有無數的軍兵勢如洪水，在他面前沖沒敗壞；同盟的君也必如此。","notes":[]},{"n":23,"t":"與那君結盟之後，他必行詭詐，因為他必上來以微小的軍成為強盛。","notes":["原文是民"]},{"n":24,"t":"趁人坦然無備的時候，他必來到國中極肥美之地，行他列祖和他列祖之祖所未曾行的，將擄物、掠物，和財寶散給眾人，又要設計攻打保障，然而這都是暫時的。","notes":[]},{"n":25,"t":"「他必奮勇向前，率領大軍攻擊南方王；南方王也必以極大極強的軍兵與他爭戰，卻站立不住，因為有人設計謀害南方王。","notes":[]},{"n":26,"t":"吃王膳的，必敗壞他；他的軍隊必被沖沒，而且被殺的甚多。","notes":[]},{"n":27,"t":"至於這二王，他們心懷惡計，同席說謊，計謀卻不成就；因為到了定期，事就了結。","notes":[]},{"n":28,"t":"北方王必帶許多財寶回往本國，他的心反對聖約，任意而行，回到本地。","notes":["原文是他"]},{"n":29,"t":"「到了定期，他必返回，來到南方。後一次卻不如前一次，","notes":[]},{"n":30,"t":"因為基提戰船必來攻擊他，他就喪膽而回，又要惱恨聖約，任意而行；他必回來聯絡背棄聖約的人。","notes":[]},{"n":31,"t":"他必興兵，這兵必褻瀆聖地，就是保障，除掉常獻的燔祭，設立那行毀壞可憎的。","notes":[]},{"n":32,"t":"作惡違背聖約的人，他必用巧言勾引；惟獨認識神的子民必剛強行事。","notes":[]},{"n":33,"t":"民間的智慧人必訓誨多人；然而他們多日必倒在刀下，或被火燒，或被擄掠搶奪。","notes":[]},{"n":34,"t":"他們仆倒的時候，稍得扶助，卻有許多人用諂媚的話親近他們。","notes":[]},{"n":35,"t":"智慧人中有些仆倒的，為要熬煉其餘的人，使他們清淨潔白，直到末了；因為到了定期，事就了結。","notes":[]},{"n":36,"t":"「王必任意而行，自高自大，超過所有的神，又用奇異的話攻擊萬神之神。他必行事亨通，直到主的忿怒完畢，因為所定的事必然成就。","notes":[]},{"n":37,"t":"他必不顧他列祖的神，也不顧婦女所羨慕的神，無論何神他都不顧；因為他必自大，高過一切。","notes":[]},{"n":38,"t":"他倒要敬拜保障的神，用金、銀、寶石和可愛之物敬奉他列祖所不認識的神。","notes":[]},{"n":39,"t":"他必靠外邦神的幫助，攻破最堅固的保障。凡承認他的，他必將榮耀加給他們，使他們管轄許多人，又為賄賂分地與他們。","notes":[]},{"n":40,"t":"「到末了，南方王要與他交戰。北方王必用戰車、馬兵，和許多戰船，勢如暴風來攻擊他，也必進入列國，如洪水氾濫。","notes":[]},{"n":41,"t":"又必進入那榮美之地，有許多國就被傾覆，但以東人、摩押人，和一大半亞捫人必脫離他的手。","notes":[]},{"n":42,"t":"他必伸手攻擊列國；埃及地也不得脫離。","notes":[]},{"n":43,"t":"他必把持埃及的金銀財寶和各樣的寶物。利比亞人和古實人都必跟從他。","notes":[]},{"n":44,"t":"但從東方和北方必有消息擾亂他，他就大發烈怒出去，要將多人殺滅淨盡。","notes":[]},{"n":45,"t":"他必在海和榮美的聖山中間設立他如宮殿的帳幕；然而到了他的結局，必無人能幫助他。」","notes":[]}]},"12":{"heading":"末日","verses":[{"n":1,"t":"「那時，保佑你本國之民的天使長米迦勒必站起來，並且有大艱難，從有國以來直到此時，沒有這樣的。你本國的民中，凡名錄在冊上的，必得拯救。","notes":["原文是大君"]},{"n":2,"t":"睡在塵埃中的，必有多人復醒。其中有得永生的，有受羞辱永遠被憎惡的。","notes":[]},{"n":3,"t":"智慧人必發光如同天上的光；那使多人歸義的，必發光如星，直到永永遠遠。","notes":[]},{"n":4,"t":"但以理啊，你要隱藏這話，封閉這書，直到末時。必有多人來往奔跑，知識就必增長。」","notes":["或譯：切心研究"]},{"n":5,"t":"我－但以理觀看，見另有兩個人站立：一個在河這邊，一個在河那邊。","notes":[]},{"n":6,"t":"有一個問那站在河水以上、穿細麻衣的說：「這奇異的事到幾時才應驗呢？」","notes":[]},{"n":7,"t":"我聽見那站在河水以上、穿細麻衣的，向天舉起左右手，指著活到永遠的主起誓說：「要到一載、二載、半載，打破聖民權力的時候，這一切事就都應驗了。」","notes":[]},{"n":8,"t":"我聽見這話，卻不明白，就說：「我主啊，這些事的結局是怎樣呢？」","notes":[]},{"n":9,"t":"他說：「但以理啊，你只管去；因為這話已經隱藏封閉，直到末時。","notes":[]},{"n":10,"t":"必有許多人使自己清淨潔白，且被熬煉；但惡人仍必行惡，一切惡人都不明白，惟獨智慧人能明白。","notes":[]},{"n":11,"t":"從除掉常獻的燔祭，並設立那行毀壞可憎之物的時候，必有一千二百九十日。","notes":[]},{"n":12,"t":"等到一千三百三十五日的，那人便為有福。","notes":[]},{"n":13,"t":"「你且去等候結局，因為你必安歇。到了末期，你必起來，享受你的福分。」","notes":[]}]}},"HOS":{"1":{"heading":"何西阿的妻子和兒女","verses":[{"n":1,"t":"當烏西雅、約坦、亞哈斯、希西家作猶大王，約阿施的兒子耶羅波安作以色列王的時候，耶和華的話臨到備利的兒子何西阿。","notes":[]},{"n":2,"t":"耶和華初次與何西阿說話，對他說：「你去娶淫婦為妻，也收那從淫亂所生的兒女；因為這地大行淫亂，離棄耶和華。」","notes":[]},{"n":3,"t":"於是，何西阿去娶了滴拉音的女兒歌篾。這婦人懷孕，給他生了一個兒子。","notes":[]},{"n":4,"t":"耶和華對何西阿說：「給他起名叫耶斯列；因為再過片時，我必討耶戶家在耶斯列殺人流血的罪，也必使以色列家的國滅絕。","notes":[]},{"n":5,"t":"到那日，我必在耶斯列平原折斷以色列的弓。」","notes":[]},{"n":6,"t":"歌篾又懷孕生了一個女兒，耶和華對何西阿說：「給她起名叫羅‧路哈瑪；因為我必不再憐憫以色列家，決不赦免他們。","notes":["就是不蒙憐憫的意思"]},{"n":7,"t":"我卻要憐憫猶大家，使他們靠耶和華－他們的神得救，不使他們靠弓、刀、爭戰、馬匹，與馬兵得救。」","notes":[]},{"n":8,"t":"歌篾給羅‧路哈瑪斷奶以後，又懷孕生了一個兒子。","notes":[]},{"n":9,"t":"耶和華說：「給他起名叫羅‧阿米；因為你們不作我的子民，我也不作你們的神。」","notes":["就是非我民的意思"]},{"n":10,"t":"然而，以色列的人數必如海沙，不可量，不可數。從前在甚麼地方對他們說「你們不是我的子民」，將來在那裏必對他們說「你們是永生神的兒子」。","notes":[],"heads":["以色列將要復興"]},{"n":11,"t":"猶大人和以色列人必一同聚集，為自己立一個首領，從這地上去，因為耶斯列的日子必為大日。","notes":["或譯：從被擄之地上來"]}]},"2":{"heading":"不貞的歌篾－不忠的以色列","verses":[{"n":1,"t":"你們要稱你們的弟兄為阿米，稱你們的姊妹為路哈瑪。","notes":["就是我民的意思","就是蒙憐憫的意思"]},{"n":2,"t":"你們要與你們的母親大大爭辯；因為她不是我的妻子，我也不是她的丈夫。叫她除掉臉上的淫像和胸間的淫態，","notes":[]},{"n":3,"t":"免得我剝她的衣服，使她赤體，與才生的時候一樣，使她如曠野，如乾旱之地，因渴而死。","notes":[]},{"n":4,"t":"我必不憐憫她的兒女，因為他們是從淫亂而生的。","notes":[]},{"n":5,"t":"他們的母親行了淫亂，懷他們的母做了可羞恥的事，因為她說：我要隨從所愛的；我的餅、水、羊毛、麻、油、酒都是他們給的。","notes":[]},{"n":6,"t":"因此，我必用荊棘堵塞她的道，築牆擋住她，使她找不著路。","notes":[]},{"n":7,"t":"她必追隨所愛的，卻追不上；她必尋找他們，卻尋不見，便說：我要歸回前夫，因我那時的光景比如今還好。","notes":[]},{"n":8,"t":"她不知道是我給她五穀、新酒，和油，又加增她的金銀；她卻以此供奉巴力。","notes":["或譯：製造"]},{"n":9,"t":"因此到了收割的日子，出酒的時候，我必將我的五穀、新酒收回，也必將她應當遮體的羊毛和麻奪回來。","notes":[]},{"n":10,"t":"如今我必在她所愛的眼前顯露她的醜態；必無人能救她脫離我的手。","notes":[]},{"n":11,"t":"我也必使她的宴樂、節期、月朔、安息日，並她的一切大會都止息了。","notes":[]},{"n":12,"t":"我也必毀壞她的葡萄樹和無花果樹，就是她說「這是我所愛的給我為賞賜」的。我必使這些樹變為荒林，為田野的走獸所吃。","notes":[]},{"n":13,"t":"我必追討她素日給諸巴力燒香的罪；那時她佩帶耳環和別樣妝飾，隨從她所愛的，卻忘記我。這是耶和華說的。","notes":[]},{"n":14,"t":"後來我必勸導她，領她到曠野，對她說安慰的話。","notes":[],"heads":["神對他子民的愛"]},{"n":15,"t":"她從那裏出來，我必賜她葡萄園，又賜她亞割谷作為指望的門。她必在那裏應聲，與幼年的日子一樣，與從埃及地上來的時候相同。","notes":["或譯：歌唱"]},{"n":16,"t":"耶和華說：「那日你必稱呼我伊施，不再稱呼我巴力；","notes":["就是我夫的意思","就是我主的意思"]},{"n":17,"t":"因為我必從我民的口中除掉諸巴力的名號，這名號不再提起。","notes":[]},{"n":18,"t":"當那日，我必為我的民，與田野的走獸和空中的飛鳥，並地上的昆蟲立約；又必在國中折斷弓刀，止息爭戰，使他們安然躺臥。","notes":[]},{"n":19,"t":"我必聘你永遠歸我為妻，以仁義、公平、慈愛、憐憫聘你歸我；","notes":[]},{"n":20,"t":"也以誠實聘你歸我，你就必認識我－耶和華。","notes":[]},{"n":21,"t":"耶和華說：那日我必應允，我必應允天，天必應允地；","notes":[]},{"n":22,"t":"地必應允五穀、新酒，和油，這些必應允耶斯列民。","notes":["_耶斯列_就是神栽種的意思"]},{"n":23,"t":"我必將她種在這地。素不蒙憐憫的，我必憐憫；本非我民的，我必對他說：你是我的民；他必說：你是我的神。」","notes":[]}]},"3":{"heading":"何西阿和那不貞的婦人","verses":[{"n":1,"t":"耶和華對我說：「你再去愛一個淫婦，就是她情人所愛的；好像以色列人，雖然偏向別神，喜愛葡萄餅，耶和華還是愛他們。」","notes":[]},{"n":2,"t":"我便用銀子十五舍客勒，大麥一賀梅珥半，買她歸我。","notes":[]},{"n":3,"t":"我對她說：「你當多日為我獨居，不可行淫，不可歸別人為妻，我向你也必這樣。」","notes":[]},{"n":4,"t":"以色列人也必多日獨居，無君王，無首領，無祭祀，無柱像，無以弗得，無家中的神像。","notes":[]},{"n":5,"t":"後來以色列人必歸回，尋求他們的神－耶和華和他們的王大衛。在末後的日子，必以敬畏的心歸向耶和華，領受他的恩惠。","notes":["或譯：回心轉意"]}]},"4":{"heading":"耶和華譴責以色列","verses":[{"n":1,"t":"以色列人哪，你們當聽耶和華的話。耶和華與這地的居民爭辯，因這地上無誠實，無良善，無人認識神。","notes":[]},{"n":2,"t":"但起假誓，不踐前言，殺害，偷盜，姦淫，行強暴，殺人流血，接連不斷。","notes":[]},{"n":3,"t":"因此，這地悲哀，其上的民、田野的獸、空中的鳥必都衰微，海中的魚也必消滅。","notes":[]},{"n":4,"t":"然而，人都不必爭辯，也不必指責，因為這民與抗拒祭司的人一樣。","notes":[],"heads":["譴責祭司"]},{"n":5,"t":"你這祭司必日間跌倒；先知也必夜間與你一同跌倒；我必滅絕你的母親。","notes":[]},{"n":6,"t":"我的民因無知識而滅亡。你棄掉知識，我也必棄掉你，使你不再給我作祭司。你既忘了你神的律法，我也必忘記你的兒女。","notes":[]},{"n":7,"t":"祭司越發增多，就越發得罪我；我必使他們的榮耀變為羞辱。","notes":[]},{"n":8,"t":"他們吃我民的贖罪祭，滿心願意我民犯罪。","notes":[]},{"n":9,"t":"將來民如何，祭司也必如何；我必因他們所行的懲罰他們，照他們所做的報應他們。","notes":[]},{"n":10,"t":"他們吃，卻不得飽；行淫，而不得立後；因為他們離棄耶和華，不遵他的命。","notes":[]},{"n":11,"t":"姦淫和酒，並新酒，奪去人的心。","notes":[],"heads":["譴責拜偶像的罪"]},{"n":12,"t":"我的民求問木偶，以為木杖能指示他們；因為他們的淫心使他們失迷，他們就行淫離棄神，不守約束，","notes":[]},{"n":13,"t":"在各山頂，各高岡的橡樹、楊樹、栗樹之下，獻祭燒香，因為樹影美好。所以，你們的女兒淫亂，你們的新婦行淫。","notes":["或譯：兒婦；下同"]},{"n":14,"t":"你們的女兒淫亂，你們的新婦行淫，我卻不懲罰她們；因為你們自己離群與娼妓同居，與妓女一同獻祭。這無知的民必致傾倒。","notes":[]},{"n":15,"t":"以色列啊，你雖然行淫，猶大卻不可犯罪。不要往吉甲去，不要上到伯‧亞文，也不要指著永生的耶和華起誓。","notes":[]},{"n":16,"t":"以色列倔強，猶如倔強的母牛；現在耶和華要放他們，如同放羊羔在寬闊之地。","notes":[]},{"n":17,"t":"以法蓮親近偶像，任憑他吧！","notes":[]},{"n":18,"t":"他們所喝的已經發酸，他們時常行淫，他們的官長最愛羞恥的事。","notes":[]},{"n":19,"t":"風把他們裹在翅膀裏；他們因所獻的祭必致蒙羞。","notes":[]}]},"5":{"heading":"何西阿警告拜偶像的人","verses":[{"n":1,"t":"眾祭司啊，要聽我的話！以色列家啊，要留心聽！王家啊，要側耳而聽！審判要臨到你們，因你們在米斯巴如網羅，在他泊山如鋪張的網。","notes":[]},{"n":2,"t":"這些悖逆的人肆行殺戮，罪孽極深；我卻斥責他們眾人。","notes":[]},{"n":3,"t":"以法蓮為我所知；以色列不能向我隱藏。以法蓮哪，現在你行淫了，以色列被玷污了。","notes":[]},{"n":4,"t":"他們所行的使他們不能歸向神；因有淫心在他們裏面，他們也不認識耶和華。","notes":[]},{"n":5,"t":"以色列的驕傲當面見證自己。故此，以色列和以法蓮必因自己的罪孽跌倒；猶大也必與他們一同跌倒。","notes":[]},{"n":6,"t":"他們必牽著牛羊去尋求耶和華，卻尋不見；他已經轉去離開他們。","notes":[]},{"n":7,"t":"他們向耶和華行事詭詐，生了私子。到了月朔，他們與他們的地業必被吞滅。","notes":[]},{"n":8,"t":"你們當在基比亞吹角，在拉瑪吹號，在伯‧亞文吹出大聲，說：便雅憫哪，有仇敵在你後頭！","notes":[],"heads":["猶大和以色列的戰爭"]},{"n":9,"t":"在責罰的日子，以法蓮必變為荒場；我在以色列支派中，指示將來必成的事。","notes":[]},{"n":10,"t":"猶大的首領如同挪移地界的人，我必將忿怒倒在他們身上，如水一般。","notes":[]},{"n":11,"t":"以法蓮因樂從人的命令，就受欺壓，被審判壓碎。","notes":[]},{"n":12,"t":"我使以法蓮如蟲蛀之物，使猶大家如朽爛之木。","notes":[]},{"n":13,"t":"以法蓮見自己有病，猶大見自己有傷，他們就打發人往亞述去見耶雷布王，他卻不能醫治你們，不能治好你們的傷。","notes":[]},{"n":14,"t":"我必向以法蓮如獅子，向猶大家如少壯獅子。我必撕裂而去，我要奪去，無人搭救。","notes":[]},{"n":15,"t":"我要回到原處，等他們自覺有罪，尋求我面；他們在急難的時候必切切尋求我。","notes":["或譯：承認己罪"]}]},"6":{"heading":"以色列無悔改誠意","verses":[{"n":1,"t":"來吧，我們歸向耶和華！他撕裂我們，也必醫治；他打傷我們，也必纏裹。","notes":[]},{"n":2,"t":"過兩天他必使我們甦醒，第三天他必使我們興起，我們就在他面前得以存活。","notes":[]},{"n":3,"t":"我們務要認識耶和華，竭力追求認識他。他出現確如晨光；他必臨到我們像甘雨，像滋潤田地的春雨。","notes":[]},{"n":4,"t":"主說：以法蓮哪，我可向你怎樣行呢？猶大啊，我可向你怎樣做呢？因為你們的良善如同早晨的雲霧，又如速散的甘露。","notes":[]},{"n":5,"t":"因此，我藉先知砍伐他們，以我口中的話殺戮他們；我施行的審判如光發出。","notes":[]},{"n":6,"t":"我喜愛良善，不喜愛祭祀；喜愛認識神，勝於燔祭。","notes":["或譯：憐恤"]},{"n":7,"t":"他們卻如亞當背約，在境內向我行事詭詐。","notes":[]},{"n":8,"t":"基列是作孽之人的城，被血沾染。","notes":[]},{"n":9,"t":"強盜成群，怎樣埋伏殺人，祭司結黨，也照樣在示劍的路上殺戮，行了邪惡。","notes":[]},{"n":10,"t":"在以色列家，我見了可憎的事；在以法蓮那裏有淫行，以色列被玷污。","notes":[]},{"n":11,"t":"猶大啊，我使被擄之民歸回的時候，必有為你所命定的收場。","notes":[]}]},"7":{"heading":"宮廷內亂","verses":[{"n":1,"t":"我想醫治以色列的時候，以法蓮的罪孽和撒馬利亞的罪惡就顯露出來。他們行事虛謊，內有賊人入室偷竊，外有強盜成群騷擾。","notes":[]},{"n":2,"t":"他們心裏並不思想我記念他們的一切惡；他們所行的現在纏繞他們，都在我面前。","notes":[]},{"n":3,"t":"他們行惡使君王歡喜，說謊使首領喜樂。","notes":[]},{"n":4,"t":"他們都是行淫的，像火爐被烤餅的燒熱，從摶麵到發麵的時候，暫不使火著旺。","notes":[]},{"n":5,"t":"在我們王宴樂的日子，首領因酒的烈性成病；王與褻慢人拉手。","notes":[]},{"n":6,"t":"首領埋伏的時候，心中熱如火爐，就如烤餅的整夜睡臥，到了早晨火氣炎炎。","notes":[]},{"n":7,"t":"眾民也熱如火爐，燒滅他們的官長。他們的君王都仆倒而死；他們中間無一人求告我。","notes":[]},{"n":8,"t":"以法蓮與列邦人攙雜；以法蓮是沒有翻過的餅。","notes":[],"heads":["以色列和列邦"]},{"n":9,"t":"外邦人吞吃他勞力得來的，他卻不知道；頭髮斑白，他也不覺得。","notes":[]},{"n":10,"t":"以色列的驕傲當面見證自己，雖遭遇這一切，他們仍不歸向耶和華－他們的神，也不尋求他。","notes":[]},{"n":11,"t":"以法蓮好像鴿子愚蠢無知；他們求告埃及，投奔亞述。","notes":[]},{"n":12,"t":"他們去的時候，我必將我的網撒在他們身上；我要打下他們，如同空中的鳥。我必按他們會眾所聽見的懲罰他們。","notes":[]},{"n":13,"t":"他們因離棄我，必定有禍；因違背我，必被毀滅。我雖要救贖他們，他們卻向我說謊。","notes":[]},{"n":14,"t":"他們並不誠心哀求我，乃在床上呼號；他們為求五穀新酒聚集，仍然悖逆我。","notes":[]},{"n":15,"t":"我雖教導他們，堅固他們的膀臂，他們竟圖謀抗拒我。","notes":[]},{"n":16,"t":"他們歸向，卻不歸向至上者；他們如同翻背的弓。他們的首領必因舌頭的狂傲倒在刀下；這在埃及地必作人的譏笑。","notes":[]}]},"8":{"heading":"以色列人因拜偶像被定罪","verses":[{"n":1,"t":"你用口吹角吧！敵人如鷹來攻打耶和華的家；因為這民違背我的約，干犯我的律法。","notes":[]},{"n":2,"t":"他們必呼叫我說：我的神啊，我們以色列認識你了。","notes":[]},{"n":3,"t":"以色列丟棄良善；仇敵必追逼他。","notes":["或譯：福分"]},{"n":4,"t":"他們立君王，卻不由我；他們立首領，我卻不認。他們用金銀為自己製造偶像，以致被剪除。","notes":[]},{"n":5,"t":"撒馬利亞啊，耶和華已經丟棄你的牛犢；我的怒氣向拜牛犢的人發作。他們到幾時方能無罪呢？","notes":[]},{"n":6,"t":"這牛犢出於以色列，是匠人所造的，並不是神。撒馬利亞的牛犢必被打碎。","notes":[]},{"n":7,"t":"他們所種的是風，所收的是暴風；所種的不成禾稼，就是發苗也不結實；即便結實，外邦人必吞吃。","notes":[]},{"n":8,"t":"以色列被吞吃；現今在列國中，好像人不喜悅的器皿。","notes":[]},{"n":9,"t":"他們投奔亞述，如同獨行的野驢；以法蓮賄買朋黨。","notes":[]},{"n":10,"t":"他們雖在列邦中賄買人，現在我卻要聚集懲罰他們；他們因君王和首領所加的重擔日漸衰微。","notes":[]},{"n":11,"t":"以法蓮增添祭壇取罪；因此，祭壇使他犯罪。","notes":[]},{"n":12,"t":"我為他寫了律法萬條，他卻以為與他毫無關涉。","notes":[]},{"n":13,"t":"至於獻給我的祭物，他們自食其肉，耶和華卻不悅納他們。現在必記念他們的罪孽，追討他們的罪惡；他們必歸回埃及。","notes":[]},{"n":14,"t":"以色列忘記造他的主，建造宮殿；猶大多造堅固城，我卻要降火焚燒他的城邑，燒滅其中的宮殿。","notes":[]}]},"9":{"heading":"何西阿宣布以色列受懲罰","verses":[{"n":1,"t":"以色列啊，不要像外邦人歡喜快樂；因為你行邪淫離棄你的神，在各穀場上如妓女喜愛賞賜。","notes":[]},{"n":2,"t":"穀場和酒醡都不夠以色列人使用；新酒也必缺乏。","notes":[]},{"n":3,"t":"他們必不得住耶和華的地；以法蓮卻要歸回埃及，必在亞述吃不潔淨的食物。","notes":[]},{"n":4,"t":"他們必不得向耶和華奠酒，即便奠酒也不蒙悅納。他們的祭物必如居喪者的食物，凡吃的必被玷污；因他們的食物只為自己的口腹，必不奉入耶和華的殿。","notes":[]},{"n":5,"t":"在大會的日子，到耶和華的節期，你們怎樣行呢？","notes":[]},{"n":6,"t":"看哪，他們逃避災難；埃及人必收殮他們的屍首，摩弗人必葬埋他們的骸骨。他們用銀子做的美物上必長蒺藜；他們的帳棚中必生荊棘。","notes":[]},{"n":7,"t":"以色列人必知道降罰的日子臨近，報應的時候來到。民說：作先知的是愚昧；受靈感的是狂妄，皆因他們多多作孽，大懷怨恨。","notes":[]},{"n":8,"t":"以法蓮曾作我神守望的；至於先知，在他一切的道上作為捕鳥人的網羅，在他神的家中懷怨恨。","notes":[]},{"n":9,"t":"以法蓮深深地敗壞，如在基比亞的日子一樣。耶和華必記念他們的罪孽，追討他們的罪惡。","notes":[]},{"n":10,"t":"主說：我遇見以色列如葡萄在曠野；我看見你們的列祖如無花果樹上春季初熟的果子。他們卻來到巴力‧毗珥專拜那可羞恥的，就成為可憎惡的，與他們所愛的一樣。","notes":[],"heads":["以色列的罪及其後果"]},{"n":11,"t":"至於以法蓮人，他們的榮耀必如鳥飛去，必不生產，不懷胎，不成孕。","notes":[]},{"n":12,"t":"縱然養大兒女，我卻必使他們喪子，甚至不留一個。我離棄他們，他們就有禍了。","notes":[]},{"n":13,"t":"我看以法蓮如泰爾栽於美地。以法蓮卻要將自己的兒女帶出來，交與行殺戮的人。","notes":[]},{"n":14,"t":"耶和華啊，求你加給他們－加甚麼呢？要使他們胎墜乳乾。","notes":[]},{"n":15,"t":"耶和華說：他們一切的惡事都在吉甲；我在那裏憎惡他們。因他們所行的惡，我必從我地上趕出他們去，不再憐愛他們；他們的首領都是悖逆的。","notes":[],"heads":["耶和華審判以色列"]},{"n":16,"t":"以法蓮受責罰，根本枯乾，必不能結果，即或生產，我必殺他們所生的愛子。","notes":[]},{"n":17,"t":"我的神必棄絕他們，因為他們不聽從他；他們也必飄流在列國中。","notes":[],"heads":["先知論以色列"]}]},"10":{"heading":"神審判以色列","verses":[{"n":1,"t":"以色列是茂盛的葡萄樹，結果繁多。果子越多，就越增添祭壇；地土越肥美，就越造美麗的柱像。","notes":[]},{"n":2,"t":"他們心懷二意，現今要定為有罪。耶和華必拆毀他們的祭壇，毀壞他們的柱像。","notes":[]},{"n":3,"t":"他們必說：我們沒有王，因為我們不敬畏耶和華。王能為我們做甚麼呢？","notes":[]},{"n":4,"t":"他們為立約說謊言，起假誓；因此，災罰如苦菜滋生在田間的犂溝中。","notes":[]},{"n":5,"t":"撒馬利亞的居民必因伯‧亞文的牛犢驚恐；崇拜牛犢的民和喜愛牛犢的祭司都必因榮耀離開它，為它悲哀。","notes":[]},{"n":6,"t":"人必將牛犢帶到亞述當作禮物，獻給耶雷布王。以法蓮必蒙羞；以色列必因自己的計謀慚愧。","notes":[]},{"n":7,"t":"至於撒馬利亞，她的王必滅沒，如水面的沫子一樣。","notes":[]},{"n":8,"t":"伯‧亞文的邱壇－就是以色列取罪的地方必被毀滅；荊棘和蒺藜必長在他們的祭壇上。他們必對大山說：遮蓋我們！對小山說：倒在我們身上！","notes":[]},{"n":9,"t":"以色列啊，你從基比亞的日子以來時常犯罪。你們的先人曾站在那裏，現今住基比亞的人以為攻擊罪孽之輩的戰事臨不到自己。","notes":[]},{"n":10,"t":"我必隨意懲罰他們。他們為兩樣的罪所纏；列邦的民必聚集攻擊他們。","notes":[]},{"n":11,"t":"以法蓮是馴良的母牛犢，喜愛踹穀，我卻將軛加在牠肥美的頸項上，我要使以法蓮拉套。猶大必耕田；雅各必耙地。","notes":["或譯：被騎"]},{"n":12,"t":"你們要為自己栽種公義，就能收割慈愛。現今正是尋求耶和華的時候；你們要開墾荒地，等他臨到，使公義如雨降在你們身上。","notes":[]},{"n":13,"t":"你們耕種的是奸惡，收割的是罪孽，吃的是謊話的果子。因你倚靠自己的行為，仰賴勇士眾多，","notes":[]},{"n":14,"t":"所以在這民中必有鬨嚷之聲，你一切的保障必被拆毀，就如沙勒幔在爭戰的日子拆毀伯‧亞比勒，將其中的母子一同摔死。","notes":[]},{"n":15,"t":"因他們的大惡，伯特利必使你們遭遇如此。到了黎明，以色列的王必全然滅絕。","notes":[]}]},"11":{"heading":"憐愛叛民","verses":[{"n":1,"t":"以色列年幼的時候，我愛他，就從埃及召出我的兒子來。","notes":[]},{"n":2,"t":"先知越發招呼他們，他們越發走開，向諸巴力獻祭，給雕刻的偶像燒香。","notes":[]},{"n":3,"t":"我原教導以法蓮行走，用膀臂抱著他們，他們卻不知道是我醫治他們。","notes":[]},{"n":4,"t":"我用慈繩愛索牽引他們；我待他們如人放鬆牛的兩腮夾板，把糧食放在他們面前。","notes":["慈：原文是人的"]},{"n":5,"t":"他們必不歸回埃及地，亞述人卻要作他們的王，因他們不肯歸向我。","notes":[]},{"n":6,"t":"刀劍必臨到他們的城邑，毀壞門閂，把人吞滅，都因他們隨從自己的計謀。","notes":[]},{"n":7,"t":"我的民偏要背道離開我；眾先知雖然招呼他們歸向至上的主，卻無人尊崇主。","notes":[]},{"n":8,"t":"以法蓮哪，我怎能捨棄你？以色列啊，我怎能棄絕你？我怎能使你如押瑪？怎能使你如洗扁？我回心轉意，我的憐愛大大發動。","notes":[]},{"n":9,"t":"我必不發猛烈的怒氣，也不再毀滅以法蓮。因我是神，並非世人，是你們中間的聖者；我必不在怒中臨到你們。","notes":[]},{"n":10,"t":"耶和華必如獅子吼叫，子民必跟隨他。他一吼叫，他們就從西方急速而來。","notes":[]},{"n":11,"t":"他們必如雀鳥從埃及急速而來，又如鴿子從亞述地來到。我必使他們住自己的房屋。這是耶和華說的。","notes":[]},{"n":12,"t":"以法蓮用謊話，以色列家用詭計圍繞我；猶大卻靠神掌權，向聖者有忠心。","notes":["或譯：_猶大_向神，向誠實的聖者猶疑不定"],"heads":["以色列和猶大受譴責"]}]},"12":{"heading":"其他的判詞","verses":[{"n":1,"t":"以法蓮吃風，且追趕東風，時常增添虛謊和強暴，與亞述立約，把油送到埃及。","notes":[]},{"n":2,"t":"耶和華與猶大爭辯，必照雅各所行的懲罰他，按他所做的報應他。","notes":[]},{"n":3,"t":"他在腹中抓住哥哥的腳跟，壯年的時候與神較力，","notes":[]},{"n":4,"t":"與天使較力，並且得勝，哭泣懇求，在伯特利遇見耶和華。耶和華－萬軍之神在那裏曉諭我們以色列人；耶和華是他可記念的名。","notes":[],"end":5},{"n":6,"t":"所以你當歸向你的神，謹守仁愛、公平，常常等候你的神。","notes":[]},{"n":7,"t":"以法蓮是商人，手裏有詭詐的天平，愛行欺騙。","notes":[]},{"n":8,"t":"以法蓮說：我果然成了富足，得了財寶；我所勞碌得來的，人必不見有甚麼不義，可算為罪的。","notes":[]},{"n":9,"t":"自從你出埃及地以來，我就是耶和華－你的神；我必使你再住帳棚，如在大會的日子一樣。","notes":[]},{"n":10,"t":"我已曉諭眾先知，並且加增默示，藉先知設立比喻。","notes":[]},{"n":11,"t":"基列人沒有罪孽嗎？他們全然是虛假的。人在吉甲獻牛犢為祭，他們的祭壇好像田間犂溝中的亂堆。","notes":[]},{"n":12,"t":"從前雅各逃到亞蘭地，以色列為得妻服事人，為得妻與人放羊。","notes":[]},{"n":13,"t":"耶和華藉先知領以色列從埃及上來；以色列也藉先知而得保存。","notes":[]},{"n":14,"t":"以法蓮大大惹動主怒，所以他流血的罪必歸在他身上。主必將那因以法蓮所受的羞辱歸還他。","notes":[]}]},"13":{"heading":"以色列最後的審判","verses":[{"n":1,"t":"從前以法蓮說話，人都戰兢，他在以色列中居處高位；但他在事奉巴力的事上犯罪就死了。","notes":[]},{"n":2,"t":"現今他們罪上加罪，用銀子為自己鑄造偶像，就是照自己的聰明製造，都是匠人的工作。有人論說，獻祭的人可以向牛犢親嘴。","notes":[]},{"n":3,"t":"因此，他們必如早晨的雲霧，又如速散的甘露，像場上的糠秕被狂風吹去，又像煙氣騰於窗外。","notes":[]},{"n":4,"t":"自從你出埃及地以來，我就是耶和華－你的神。在我以外，你不可認識別神；除我以外並沒有救主。","notes":[]},{"n":5,"t":"我曾在曠野乾旱之地認識你。","notes":[]},{"n":6,"t":"這些民照我所賜的食物得了飽足；既得飽足，心就高傲，忘記了我。","notes":[]},{"n":7,"t":"因此，我向他們如獅子，又如豹伏在道旁。","notes":[]},{"n":8,"t":"我遇見他們必像丟崽子的母熊，撕裂他們的胸膛。在那裏，我必像母獅吞吃他們；野獸必撕裂他們。","notes":["或譯：心膜"]},{"n":9,"t":"以色列啊，你與我反對，就是反對幫助你的，自取敗壞。","notes":[]},{"n":10,"t":"你曾求我說：給我立王和首領。現在你的王在哪裏呢？治理你的在哪裏呢？讓他在你所有的城中拯救你吧！","notes":[]},{"n":11,"t":"我在怒氣中將王賜你，又在烈怒中將王廢去。","notes":[]},{"n":12,"t":"以法蓮的罪孽包裹；他的罪惡收藏。","notes":[]},{"n":13,"t":"產婦的疼痛必臨到他身上；他是無智慧之子，到了產期不當遲延。","notes":[]},{"n":14,"t":"我必救贖他們脫離陰間，救贖他們脫離死亡。死亡啊，你的災害在哪裏呢？陰間哪，你的毀滅在哪裏呢？在我眼前絕無後悔之事。","notes":[]},{"n":15,"t":"他在弟兄中雖然茂盛，必有東風颳來，就是耶和華的風從曠野上來。他的泉源必乾；他的源頭必竭；仇敵必擄掠他所積蓄的一切寶器。","notes":[]},{"n":16,"t":"撒馬利亞必擔當自己的罪，因為悖逆她的神。她必倒在刀下；嬰孩必被摔死；孕婦必被剖開。","notes":[]}]},"14":{"heading":"何西阿勸告以色列人","verses":[{"n":1,"t":"以色列啊，你要歸向耶和華－你的神；你是因自己的罪孽跌倒了。","notes":[]},{"n":2,"t":"當歸向耶和華，用言語禱告他說：求你除淨罪孽，悅納善行；這樣，我們就把嘴唇的祭代替牛犢獻上。","notes":[]},{"n":3,"t":"我們不向亞述求救，不騎埃及的馬，也不再對我們手所造的說：你是我們的神。因為孤兒在你－耶和華那裏得蒙憐憫。","notes":[]},{"n":4,"t":"我必醫治他們背道的病，甘心愛他們；因為我的怒氣向他們轉消。","notes":[],"heads":["耶和華應許以色列新生命"]},{"n":5,"t":"我必向以色列如甘露；他必如百合花開放，如黎巴嫩的樹木扎根。","notes":[]},{"n":6,"t":"他的枝條必延長；他的榮華如橄欖樹；他的香氣如黎巴嫩的香柏樹。","notes":[]},{"n":7,"t":"曾住在他蔭下的必歸回，發旺如五穀，開花如葡萄樹。他的香氣如黎巴嫩的酒。","notes":[]},{"n":8,"t":"以法蓮必說：我與偶像還有甚麼關涉呢？我－耶和華回答他，也必顧念他。我如青翠的松樹；你的果子從我而得。","notes":[]},{"n":9,"t":"誰是智慧人？可以明白這些事；誰是通達人？可以知道這一切。因為，耶和華的道是正直的；義人必在其中行走，罪人卻在其上跌倒。","notes":[],"heads":["結束的話"]}]}},"JOL":{"1":{"heading":"百姓因收成受損壞而悲傷","verses":[{"n":1,"t":"耶和華的話臨到毗土珥的兒子約珥。","notes":[]},{"n":2,"t":"老年人哪，當聽我的話；國中的居民哪，都要側耳而聽。在你們的日子，或你們列祖的日子，曾有這樣的事嗎？","notes":[]},{"n":3,"t":"你們要將這事傳與子，子傳與孫，孫傳與後代。","notes":[]},{"n":4,"t":"剪蟲剩下的，蝗蟲來吃；蝗蟲剩下的，蝻子來吃；蝻子剩下的，螞蚱來吃。","notes":[]},{"n":5,"t":"酒醉的人哪，要清醒哭泣；好酒的人哪，都要為甜酒哀號，因為從你們的口中斷絕了。","notes":[]},{"n":6,"t":"有一隊蝗蟲又強盛又無數，侵犯我的地；牠的牙齒如獅子的牙齒，大牙如母獅的大牙。","notes":["原文是民"]},{"n":7,"t":"牠毀壞我的葡萄樹，剝了我無花果樹的皮，剝盡而丟棄，使枝條露白。","notes":[]},{"n":8,"t":"我的民哪，你當哀號，像處女腰束麻布，為幼年的丈夫哀號。","notes":[]},{"n":9,"t":"素祭和奠祭從耶和華的殿中斷絕；事奉耶和華的祭司都悲哀。","notes":[]},{"n":10,"t":"田荒涼，地悲哀；因為五穀毀壞，新酒乾竭，油也缺乏。","notes":[]},{"n":11,"t":"農夫啊，你們要慚愧；修理葡萄園的啊，你們要哀號；因為大麥小麥與田間的莊稼都滅絕了。","notes":[]},{"n":12,"t":"葡萄樹枯乾；無花果樹衰殘。石榴樹、棕樹、蘋果樹，連田野一切的樹木也都枯乾；眾人的喜樂盡都消滅。","notes":[]},{"n":13,"t":"祭司啊，你們當腰束麻布痛哭；伺候祭壇的啊，你們要哀號；事奉我神的啊，你們要來披上麻布過夜，因為素祭和奠祭從你們神的殿中斷絕了。","notes":[]},{"n":14,"t":"你們要分定禁食的日子，宣告嚴肅會，招聚長老和國中的一切居民到耶和華－你們神的殿，向耶和華哀求。","notes":[]},{"n":15,"t":"哀哉！耶和華的日子臨近了。這日來到，好像毀滅從全能者來到。","notes":[]},{"n":16,"t":"糧食不是在我們眼前斷絕了嗎？歡喜快樂不是從我們神的殿中止息了嗎？","notes":[]},{"n":17,"t":"穀種在土塊下朽爛；倉也荒涼，廩也破壞；因為五穀枯乾了。","notes":[]},{"n":18,"t":"牲畜哀鳴；牛群混亂，因為無草；羊群也受了困苦。","notes":[]},{"n":19,"t":"耶和華啊，我向你求告，因為火燒滅曠野的草場；火焰燒盡田野的樹木。","notes":[]},{"n":20,"t":"田野的走獸向你發喘；因為溪水乾涸，火也燒滅曠野的草場。","notes":[]}]},"2":{"heading":"以蝗蟲為耶和華日子的警告","verses":[{"n":1,"t":"你們要在錫安吹角，在我聖山吹出大聲。國中的居民都要發顫；因為耶和華的日子將到，已經臨近。","notes":[]},{"n":2,"t":"那日是黑暗、幽冥、密雲、烏黑的日子，好像晨光鋪滿山嶺。有一隊蝗蟲又大又強；從來沒有這樣的，以後直到萬代也必沒有。","notes":["原文是民"]},{"n":3,"t":"牠們前面如火燒滅，後面如火焰燒盡。未到以前，地如伊甸園；過去以後，成了荒涼的曠野；沒有一樣能躲避牠們的。","notes":[]},{"n":4,"t":"牠們的形狀如馬，奔跑如馬兵。","notes":[]},{"n":5,"t":"在山頂蹦跳的響聲如車輛的響聲，又如火焰燒碎稭的響聲，好像強盛的民擺陣預備打仗。","notes":[]},{"n":6,"t":"牠們一來，眾民傷慟，臉都變色。","notes":[]},{"n":7,"t":"牠們如勇士奔跑，像戰士爬城；各都步行，不亂隊伍。","notes":[]},{"n":8,"t":"彼此並不擁擠，向前各行其路，直闖兵器，不偏左右。","notes":[]},{"n":9,"t":"牠們蹦上城，躥上牆，爬上房屋，進入窗戶如同盜賊。","notes":[]},{"n":10,"t":"牠們一來，地震天動，日月昏暗，星宿無光。","notes":[]},{"n":11,"t":"耶和華在他軍旅前發聲，他的隊伍甚大；成就他命的是強盛者。因為耶和華的日子大而可畏，誰能當得起呢？","notes":[]},{"n":12,"t":"耶和華說：雖然如此，你們應當禁食、哭泣、悲哀，一心歸向我。","notes":[],"heads":["呼籲百姓悔改"]},{"n":13,"t":"你們要撕裂心腸，不撕裂衣服。歸向耶和華－你們的神；因為他有恩典，有憐憫，不輕易發怒，有豐盛的慈愛，並且後悔不降所說的災。","notes":[]},{"n":14,"t":"或者他轉意後悔，留下餘福，就是留下獻給耶和華－你們神的素祭和奠祭，也未可知。","notes":[]},{"n":15,"t":"你們要在錫安吹角，分定禁食的日子，宣告嚴肅會。","notes":[]},{"n":16,"t":"聚集眾民，使會眾自潔：招聚老者，聚集孩童和吃奶的；使新郎出離洞房，新婦出離內室。","notes":[]},{"n":17,"t":"事奉耶和華的祭司要在廊子和祭壇中間哭泣，說：耶和華啊，求你顧惜你的百姓，不要使你的產業受羞辱，列邦管轄他們。為何容列國的人說：「他們的神在哪裏」呢？","notes":[]},{"n":18,"t":"耶和華就為自己的地發熱心，憐恤他的百姓。","notes":[],"heads":["神再賜福澤"]},{"n":19,"t":"耶和華應允他的百姓說：我必賜給你們五穀、新酒，和油，使你們飽足；我也不再使你們受列國的羞辱；","notes":[]},{"n":20,"t":"卻要使北方來的軍隊遠離你們，將他們趕到乾旱荒廢之地：前隊趕入東海，後隊趕入西海；因為他們所行的大惡，臭氣上升，腥味騰空。","notes":["原文是事"]},{"n":21,"t":"地土啊，不要懼怕；要歡喜快樂，因為耶和華行了大事。","notes":[]},{"n":22,"t":"田野的走獸啊，不要懼怕；因為，曠野的草發生，樹木結果，無花果樹、葡萄樹也都效力。","notes":[]},{"n":23,"t":"錫安的民哪，你們要快樂，為耶和華－你們的神歡喜；因他賜給你們合宜的秋雨，為你們降下甘霖，就是秋雨、春雨，和先前一樣。","notes":[]},{"n":24,"t":"禾場必滿了麥子；酒醡與油醡必有新酒和油盈溢。","notes":[]},{"n":25,"t":"我打發到你們中間的大軍隊，就是蝗蟲、蝻子、螞蚱、剪蟲，那些年所吃的，我要補還你們。","notes":[]},{"n":26,"t":"你們必多吃而得飽足，就讚美為你們行奇妙事之耶和華－你們神的名。我的百姓必永遠不致羞愧。","notes":[]},{"n":27,"t":"你們必知道我是在以色列中間，又知道我是耶和華－你們的神；在我以外並無別神。我的百姓必永遠不致羞愧。","notes":[]},{"n":28,"t":"以後，我要將我的靈澆灌凡有血氣的。你們的兒女要說預言；你們的老年人要做異夢，少年人要見異象。","notes":[],"heads":["耶和華的日子"]},{"n":29,"t":"在那些日子，我要將我的靈澆灌我的僕人和使女。","notes":[]},{"n":30,"t":"「在天上地下，我要顯出奇事，有血，有火，有煙柱。","notes":[]},{"n":31,"t":"日頭要變為黑暗，月亮要變為血，這都在耶和華大而可畏的日子未到以前。","notes":[]},{"n":32,"t":"到那時候，凡求告耶和華名的就必得救；因為照耶和華所說的，在錫安山，耶路撒冷必有逃脫的人，在剩下的人中必有耶和華所召的。」","notes":[]}]},"3":{"heading":"神要審判萬民","verses":[{"n":1,"t":"「到那日，我使猶大和耶路撒冷被擄之人歸回的時候，","notes":[]},{"n":2,"t":"我要聚集萬民，帶他們下到約沙法谷，在那裏施行審判；因為他們將我的百姓，就是我的產業以色列，分散在列國中，又分取我的地土，","notes":[]},{"n":3,"t":"且為我的百姓拈鬮，將童子換妓女，賣童女買酒喝。","notes":[]},{"n":4,"t":"「泰爾、西頓，和非利士四境的人哪，你們與我何干？你們要報復我嗎？若報復我，我必使報應速速歸到你們的頭上。","notes":[]},{"n":5,"t":"你們既然奪取我的金銀，又將我可愛的寶物帶入你們宮殿，","notes":["或譯：廟中"]},{"n":6,"t":"並將猶大人和耶路撒冷人賣給希臘人，使他們遠離自己的境界。","notes":["原文是雅完人"]},{"n":7,"t":"我必激動他們離開你們所賣到之地，又必使報應歸到你們的頭上。","notes":[]},{"n":8,"t":"我必將你們的兒女賣在猶大人的手中，他們必賣給遠方示巴國的人。這是耶和華說的。」","notes":[]},{"n":9,"t":"當在萬民中宣告說：要預備打仗；激動勇士，使一切戰士上前來。","notes":[]},{"n":10,"t":"要將犂頭打成刀劍，將鐮刀打成戈矛；軟弱的要說：我有勇力。","notes":[]},{"n":11,"t":"四圍的列國啊，你們要速速地來，一同聚集。耶和華啊，求你使你的大能者降臨。","notes":[]},{"n":12,"t":"萬民都當興起，上到約沙法谷；因為我必坐在那裏，審判四圍的列國。","notes":[]},{"n":13,"t":"開鐮吧！因為莊稼熟了；踐踏吧！因為酒醡滿了。酒池盈溢；他們的罪惡甚大。","notes":[]},{"n":14,"t":"許多許多的人在斷定谷，因為耶和華的日子臨近斷定谷。","notes":[]},{"n":15,"t":"日月昏暗，星宿無光。","notes":[]},{"n":16,"t":"耶和華必從錫安吼叫，從耶路撒冷發聲，天地就震動。耶和華卻要作他百姓的避難所，作以色列人的保障。","notes":[],"heads":["神將賜福給他的子民"]},{"n":17,"t":"你們就知道我是耶和華－你們的神，且又住在錫安－我的聖山。那時，耶路撒冷必成為聖；外邦人不再從其中經過。","notes":[]},{"n":18,"t":"到那日，大山要滴甜酒；小山要流奶子；猶大溪河都有水流。必有泉源從耶和華的殿中流出來，滋潤什亭谷。","notes":[]},{"n":19,"t":"埃及必然荒涼，以東變為悽涼的曠野，都因向猶大人所行的強暴，又因在本地流無辜人的血。","notes":[]},{"n":20,"t":"但猶大必存到永遠；耶路撒冷必存到萬代。","notes":[]},{"n":21,"t":"我未曾報復流血的罪，現在我要報復，因為耶和華住在錫安。","notes":["或譯：洗除；下同"]}]}},"AMO":{"1":{"heading":"神審判以色列的鄰國","verses":[{"n":1,"t":"當猶大王烏西雅，以色列王約阿施的兒子耶羅波安在位的時候，大地震前二年，提哥亞牧人中的阿摩司得默示論以色列。","notes":[]},{"n":2,"t":"他說：耶和華必從錫安吼叫，從耶路撒冷發聲；牧人的草場要悲哀；迦密的山頂要枯乾。","notes":[]},{"n":3,"t":"耶和華如此說：大馬士革三番四次地犯罪，我必不免去她的刑罰；因為她以打糧食的鐵器打過基列。","notes":[]},{"n":4,"t":"我卻要降火在哈薛的家中，燒滅便‧哈達的宮殿。","notes":[]},{"n":5,"t":"我必折斷大馬士革的門閂，剪除亞文平原的居民和伯‧伊甸掌權的。亞蘭人必被擄到吉珥。這是耶和華說的。","notes":[]},{"n":6,"t":"耶和華如此說：迦薩三番四次地犯罪，我必不免去她的刑罰；因為她擄掠眾民交給以東。","notes":[]},{"n":7,"t":"我卻要降火在迦薩的城內，燒滅其中的宮殿。","notes":[]},{"n":8,"t":"我必剪除亞實突的居民和亞實基倫掌權的，也必反手攻擊以革倫。非利士人所餘剩的必都滅亡。這是主耶和華說的。","notes":[]},{"n":9,"t":"耶和華如此說：泰爾三番四次地犯罪，我必不免去她的刑罰；因為她將眾民交給以東，並不記念弟兄的盟約。","notes":[]},{"n":10,"t":"我卻要降火在泰爾的城內，燒滅其中的宮殿。","notes":[]},{"n":11,"t":"耶和華如此說：以東三番四次地犯罪，我必不免去她的刑罰；因為她拿刀追趕兄弟，毫無憐憫，發怒撕裂，永懷忿怒。","notes":[]},{"n":12,"t":"我卻要降火在提幔，燒滅波斯拉的宮殿。","notes":[]},{"n":13,"t":"耶和華如此說：亞捫人三番四次地犯罪，我必不免去他們的刑罰；因為他們剖開基列的孕婦，擴張自己的境界。","notes":[]},{"n":14,"t":"我卻要在爭戰吶喊的日子，旋風狂暴的時候，點火在拉巴的城內，燒滅其中的宮殿。","notes":[]},{"n":15,"t":"他們的王和首領必一同被擄去。這是耶和華說的。","notes":[]}]},"2":{"heading":"神審判以色列","verses":[{"n":1,"t":"耶和華如此說：摩押三番四次地犯罪，我必不免去她的刑罰；因為她將以東王的骸骨焚燒成灰。","notes":[]},{"n":2,"t":"我卻要降火在摩押，燒滅加略的宮殿。摩押必在鬨嚷吶喊吹角之中死亡。","notes":[]},{"n":3,"t":"我必剪除摩押中的審判者，將其中的一切首領和他一同殺戮。這是耶和華說的。","notes":[]},{"n":4,"t":"耶和華如此說：猶大人三番四次地犯罪，我必不免去他們的刑罰；因為他們厭棄耶和華的訓誨，不遵守他的律例。他們列祖所隨從虛假的偶像使他們走迷了。","notes":[]},{"n":5,"t":"我卻要降火在猶大，燒滅耶路撒冷的宮殿。","notes":[]},{"n":6,"t":"耶和華如此說：以色列人三番四次地犯罪，我必不免去他們的刑罰；因他們為銀子賣了義人，為一雙鞋賣了窮人。","notes":[]},{"n":7,"t":"他們見窮人頭上所蒙的灰也都垂涎，阻礙謙卑人的道路。父子同一個女子行淫，褻瀆我的聖名。","notes":[]},{"n":8,"t":"他們在各壇旁鋪人所當的衣服，臥在其上，又在他們神的廟中喝受罰之人的酒。","notes":[]},{"n":9,"t":"我從以色列人面前除滅亞摩利人。他雖高大如香柏樹，堅固如橡樹，我卻上滅他的果子，下絕他的根本。","notes":[]},{"n":10,"t":"我也將你們從埃及地領上來，在曠野引導你們四十年，使你們得亞摩利人之地為業。","notes":[]},{"n":11,"t":"我從你們子弟中興起先知，又從你們少年人中興起拿細耳人。以色列人哪，不是這樣嗎？這是耶和華說的。","notes":[]},{"n":12,"t":"你們卻給拿細耳人酒喝，囑咐先知說：不要說預言。","notes":[]},{"n":13,"t":"看哪，在你們所住之地，我必壓你們，如同裝滿禾捆的車壓物一樣。","notes":[]},{"n":14,"t":"快跑的不能逃脫；有力的不能用力；剛勇的也不能自救。","notes":[]},{"n":15,"t":"拿弓的不能站立；腿快的不能逃脫；騎馬的也不能自救。","notes":[]},{"n":16,"t":"到那日，勇士中最有膽量的，必赤身逃跑。這是耶和華說的。","notes":[]}]},"3":{"heading":"先知的任務","verses":[{"n":1,"t":"以色列人哪，你們全家是我從埃及地領上來的，當聽耶和華攻擊你們的話：","notes":[]},{"n":2,"t":"在地上萬族中，我只認識你們；因此，我必追討你們的一切罪孽。","notes":[]},{"n":3,"t":"二人若不同心，豈能同行呢？","notes":[]},{"n":4,"t":"獅子若非抓食，豈能在林中咆哮呢？少壯獅子若無所得，豈能從洞中發聲呢？","notes":[]},{"n":5,"t":"若沒有機檻，雀鳥豈能陷在網羅裏呢？網羅若無所得，豈能從地上翻起呢？","notes":[]},{"n":6,"t":"城中若吹角，百姓豈不驚恐呢？災禍若臨到一城，豈非耶和華所降的嗎？","notes":[]},{"n":7,"t":"主耶和華若不將奧祕指示他的僕人－眾先知，就一無所行。","notes":[]},{"n":8,"t":"獅子吼叫，誰不懼怕呢？主耶和華發命，誰能不說預言呢？","notes":[]},{"n":9,"t":"要在亞實突的宮殿中和埃及地的宮殿裏傳揚說：你們要聚集在撒馬利亞的山上，就看見城中有何等大的擾亂與欺壓的事。","notes":[],"heads":["撒馬利亞的結局"]},{"n":10,"t":"那些以強暴搶奪財物、積蓄在自己家中的人不知道行正直的事。這是耶和華說的。","notes":[]},{"n":11,"t":"所以主耶和華如此說：敵人必來圍攻這地，使你的勢力衰微，搶掠你的家宅。","notes":[]},{"n":12,"t":"耶和華如此說：「牧人怎樣從獅子口中搶回兩條羊腿或半個耳朵，住撒馬利亞的以色列人躺臥在床角上或鋪繡花毯的榻上，他們得救也不過如此。」","notes":[]},{"n":13,"t":"主耶和華－萬軍之神說：當聽這話，警戒雅各家。","notes":[]},{"n":14,"t":"我討以色列罪的日子，也要討伯特利祭壇的罪；壇角必被砍下，墜落於地。","notes":[]},{"n":15,"t":"我要拆毀過冬和過夏的房屋。象牙的房屋也必毀滅；高大的房屋都歸無有。這是耶和華說的。","notes":[]}]},"4":{"heading":"以色列的失敗","verses":[{"n":1,"t":"你們住撒馬利亞山如巴珊母牛的啊，當聽我的話－你們欺負貧寒的，壓碎窮乏的，對家主說：拿酒來，我們喝吧！","notes":[]},{"n":2,"t":"主耶和華指著自己的聖潔起誓說：日子快到，人必用鉤子將你們鉤去，用魚鉤將你們餘剩的鉤去。","notes":[]},{"n":3,"t":"你們各人必從破口直往前行，投入哈門。這是耶和華說的。","notes":[]},{"n":4,"t":"以色列人哪，任你們往伯特利去犯罪，到吉甲加增罪過；每日早晨獻上你們的祭物，每三日奉上你們的十分之一。","notes":[]},{"n":5,"t":"任你們獻有酵的感謝祭，把甘心祭宣傳報告給眾人，因為是你們所喜愛的。這是主耶和華說的。","notes":[]},{"n":6,"t":"我使你們在一切城中牙齒乾淨，在你們各處糧食缺乏，你們仍不歸向我。這是耶和華說的。","notes":[]},{"n":7,"t":"在收割的前三月，我使雨停止，不降在你們那裏；我降雨在這城，不降雨在那城；這塊地有雨，那塊地無雨；無雨的就枯乾了。","notes":[]},{"n":8,"t":"這樣，兩三城的人湊到一城去找水，卻喝不足；你們仍不歸向我。這是耶和華說的。","notes":[]},{"n":9,"t":"我以旱風、霉爛攻擊你們，你們園中許多菜蔬、葡萄樹、無花果樹、橄欖樹都被剪蟲所吃；你們仍不歸向我。這是耶和華說的。","notes":[]},{"n":10,"t":"我降瘟疫在你們中間，像在埃及一樣；用刀殺戮你們的少年人，使你們的馬匹被擄掠，營中屍首的臭氣撲鼻；你們仍不歸向我。這是耶和華說的。","notes":[]},{"n":11,"t":"我傾覆你們中間的城邑，如同我從前傾覆所多瑪、蛾摩拉一樣，使你們好像從火中抽出來的一根柴；你們仍不歸向我。這是耶和華說的。","notes":[]},{"n":12,"t":"以色列啊，我必向你如此行；以色列啊，我既這樣行，你當預備迎見你的神。","notes":[]},{"n":13,"t":"那創山、造風、將心意指示人、使晨光變為幽暗、腳踏在地之高處的，他的名是耶和華－萬軍之神。","notes":[]}]},"5":{"heading":"呼籲以色列人悔改","verses":[{"n":1,"t":"以色列家啊，要聽我為你們所作的哀歌：","notes":[]},{"n":2,"t":"以色列民跌倒，不得再起；躺在地上，無人攙扶。","notes":["原文是處女"]},{"n":3,"t":"主耶和華如此說：以色列家的城發出一千兵的，只剩一百；發出一百的，只剩十個。","notes":[]},{"n":4,"t":"耶和華向以色列家如此說：你們要尋求我，就必存活。","notes":[]},{"n":5,"t":"不要往伯特利尋求，不要進入吉甲，不要過到別是巴；因為吉甲必被擄掠，伯特利也必歸於無有。","notes":[]},{"n":6,"t":"要尋求耶和華，就必存活，免得他在約瑟家像火發出，在伯特利焚燒，無人撲滅。","notes":[]},{"n":7,"t":"你們這使公平變為茵蔯、將公義丟棄於地的，","notes":[]},{"n":8,"t":"要尋求那造昴星和參星，使死蔭變為晨光，使白日變為黑夜，命海水來澆在地上的－耶和華是他的名；","notes":[]},{"n":9,"t":"他使力強的忽遭滅亡，以致保障遭遇毀壞。","notes":[]},{"n":10,"t":"你們怨恨那在城門口責備人的，憎惡那說正直話的。","notes":[]},{"n":11,"t":"你們踐踏貧民，向他們勒索麥子；你們用鑿過的石頭建造房屋，卻不得住在其內；栽種美好的葡萄園，卻不得喝所出的酒。","notes":[]},{"n":12,"t":"我知道你們的罪過何等多，你們的罪惡何等大。你們苦待義人，收受賄賂，在城門口屈枉窮乏人。","notes":[]},{"n":13,"t":"所以通達人見這樣的時勢必靜默不言，因為時勢真惡。","notes":[]},{"n":14,"t":"你們要求善，不要求惡，就必存活。這樣，耶和華－萬軍之神必照你們所說的與你們同在。","notes":[]},{"n":15,"t":"要惡惡好善，在城門口秉公行義；或者耶和華－萬軍之神向約瑟的餘民施恩。","notes":[]},{"n":16,"t":"主耶和華－萬軍之神如此說：在一切寬闊處必有哀號的聲音；在各街市上必有人說：哀哉！哀哉！又必叫農夫來哭號，叫善唱哀歌的來舉哀。","notes":[]},{"n":17,"t":"在各葡萄園必有哀號的聲音，因為我必從你中間經過。這是耶和華說的。","notes":[]},{"n":18,"t":"想望耶和華日子來到的有禍了！你們為何想望耶和華的日子呢？那日黑暗沒有光明，","notes":[]},{"n":19,"t":"景況好像人躲避獅子又遇見熊，或是進房屋以手靠牆，就被蛇咬。","notes":[]},{"n":20,"t":"耶和華的日子不是黑暗沒有光明嗎？不是幽暗毫無光輝嗎？","notes":[]},{"n":21,"t":"我厭惡你們的節期，也不喜悅你們的嚴肅會。","notes":[]},{"n":22,"t":"你們雖然向我獻燔祭和素祭，我卻不悅納，也不顧你們用肥畜獻的平安祭；","notes":[]},{"n":23,"t":"要使你們歌唱的聲音遠離我，因為我不聽你們彈琴的響聲。","notes":[]},{"n":24,"t":"惟願公平如大水滾滾，使公義如江河滔滔。","notes":[]},{"n":25,"t":"「以色列家啊，你們在曠野四十年，豈是將祭物和供物獻給我呢？","notes":[]},{"n":26,"t":"你們抬著為自己所造之摩洛的帳幕和偶像的龕，並你們的神星。","notes":[]},{"n":27,"t":"所以我要把你們擄到大馬士革以外。」這是耶和華－名為萬軍之神說的。","notes":[]}]},"6":{"heading":"以色列的毀滅","verses":[{"n":1,"t":"國為列國之首，人最著名，且為以色列家所歸向，在錫安和撒馬利亞山安逸無慮的，有禍了！","notes":[]},{"n":2,"t":"你們要過到甲尼察看，從那裏往大城哈馬去，又下到非利士人的迦特，看那些國比你們的國還強嗎？境界比你們的境界還寬嗎？","notes":[]},{"n":3,"t":"你們以為降禍的日子還遠，坐在位上盡行強暴。","notes":["或譯：行強暴使審判臨近"]},{"n":4,"t":"你們躺臥在象牙床上，舒身在榻上，吃群中的羊羔，棚裏的牛犢；","notes":[]},{"n":5,"t":"彈琴鼓瑟唱消閑的歌曲，為自己製造樂器，如同大衛所造的；","notes":[]},{"n":6,"t":"以大碗喝酒，用上等的油抹身，卻不為約瑟的苦難擔憂。","notes":[]},{"n":7,"t":"所以這些人必在被擄的人中首先被擄；舒身的人荒宴之樂必消滅了。","notes":[]},{"n":8,"t":"主耶和華－萬軍之神指著自己起誓說：我憎惡雅各的榮華，厭棄他的宮殿；因此，我必將城和其中所有的都交付敵人。","notes":[]},{"n":9,"t":"那時，若在一房之內剩下十個人，也都必死。","notes":[]},{"n":10,"t":"死人的伯叔，就是燒他屍首的，要將這屍首搬到房外，問房屋內間的人說：「你那裏還有人沒有？」他必說：「沒有」；又說：「不要作聲，因為我們不可提耶和華的名。」","notes":[]},{"n":11,"t":"看哪，耶和華出令，大房就被攻破，小屋就被打裂。","notes":[]},{"n":12,"t":"馬豈能在崖石上奔跑？人豈能在那裏用牛耕種呢？你們卻使公平變為苦膽，使公義的果子變為茵蔯。","notes":[]},{"n":13,"t":"你們喜愛虛浮的事，自誇說：我們不是憑自己的力量取了角嗎？","notes":[]},{"n":14,"t":"耶和華、萬軍之神說：以色列家啊，我必興起一國攻擊你們；他們必欺壓你們，從哈馬口直到亞拉巴的河。","notes":[]}]},"7":{"heading":"蝗蟲的異象","verses":[{"n":1,"t":"主耶和華指示我一件事：為王割菜之後，菜又發生；剛發生的時候，主造蝗蟲。","notes":["或譯：草"]},{"n":2,"t":"蝗蟲吃盡那地的青物，我就說：「主耶和華啊，求你赦免；因為雅各微弱，他怎能站立得住呢？」","notes":[]},{"n":3,"t":"耶和華就後悔說：「這災可以免了。」","notes":[]},{"n":4,"t":"主耶和華又指示我一件事：他命火來懲罰以色列，火就吞滅深淵，險些將地燒滅。","notes":[],"heads":["火的異象"]},{"n":5,"t":"我就說：「主耶和華啊，求你止息；因為雅各微弱，他怎能站立得住呢？」","notes":[]},{"n":6,"t":"耶和華就後悔說：「這災也可免了。」","notes":[]},{"n":7,"t":"他又指示我一件事：有一道牆是按準繩建築的，主手拿準繩站在其上。","notes":[],"heads":["準繩的異象"]},{"n":8,"t":"耶和華對我說：「阿摩司啊，你看見甚麼？」我說：「看見準繩。」主說：「我要吊起準繩在我民以色列中，我必不再寬恕他們。","notes":[]},{"n":9,"t":"以撒的邱壇必然淒涼；以色列的聖所必然荒廢。我必興起，用刀攻擊耶羅波安的家。」","notes":[]},{"n":10,"t":"伯特利的祭司亞瑪謝打發人到以色列王耶羅波安那裏，說：「阿摩司在以色列家中圖謀背叛你；他所說的一切話，這國擔當不起；","notes":[],"heads":["阿摩司和亞瑪謝"]},{"n":11,"t":"因為阿摩司如此說：『耶羅波安必被刀殺；以色列民定被擄去離開本地。』」","notes":[]},{"n":12,"t":"亞瑪謝又對阿摩司說：「你這先見哪，要逃往猶大地去，在那裏糊口，在那裏說預言，","notes":[]},{"n":13,"t":"卻不要在伯特利再說預言；因為這裏有王的聖所，有王的宮殿。」","notes":[]},{"n":14,"t":"阿摩司對亞瑪謝說：「我原不是先知，也不是先知的門徒。我是牧人，又是修理桑樹的。","notes":["原文是兒子"]},{"n":15,"t":"耶和華選召我，使我不跟從羊群，對我說：『你去向我民以色列說預言。』","notes":[]},{"n":16,"t":"亞瑪謝啊，現在你要聽耶和華的話。你說：『不要向以色列說預言，也不要向以撒家滴下預言。』","notes":[]},{"n":17,"t":"所以耶和華如此說：『你的妻子必在城中作妓女；你的兒女必倒在刀下。你的地必有人用繩子量了分取；你自己必死在污穢之地。以色列民定被擄去離開本地。』」","notes":[]}]},"8":{"heading":"一筐水果的異象","verses":[{"n":1,"t":"主耶和華又指示我一件事：我看見一筐夏天的果子。","notes":[]},{"n":2,"t":"他說：「阿摩司啊，你看見甚麼？」我說：「看見一筐夏天的果子。」耶和華說：「我民以色列的結局到了，我必不再寬恕他們。」","notes":[]},{"n":3,"t":"主耶和華說：「那日，殿中的詩歌變為哀號；必有許多屍首在各處拋棄，無人作聲。」","notes":[]},{"n":4,"t":"你們這些要吞吃窮乏人、使困苦人衰敗的，當聽我的話！","notes":[],"heads":["以色列的結局"]},{"n":5,"t":"你們說：月朔幾時過去，我們好賣糧；安息日幾時過去，我們好擺開麥子；賣出用小升斗，收銀用大戥子，用詭詐的天平欺哄人，","notes":[]},{"n":6,"t":"好用銀子買貧寒人，用一雙鞋換窮乏人，將壞了的麥子賣給人。","notes":[]},{"n":7,"t":"耶和華指著雅各的榮耀起誓說：他們的一切行為，我必永遠不忘。","notes":[]},{"n":8,"t":"地豈不因這事震動？其上的居民不也悲哀嗎？地必全然像尼羅河漲起，如同埃及河湧上落下。","notes":[]},{"n":9,"t":"主耶和華說：到那日，我必使日頭在午間落下，使地在白晝黑暗。","notes":[]},{"n":10,"t":"我必使你們的節期變為悲哀，歌曲變為哀歌。眾人腰束麻布，頭上光禿，使這場悲哀如喪獨生子，至終如痛苦的日子一樣。","notes":[]},{"n":11,"t":"主耶和華說：日子將到，我必命饑荒降在地上。人飢餓非因無餅，乾渴非因無水，乃因不聽耶和華的話。","notes":[]},{"n":12,"t":"他們必飄流，從這海到那海，從北邊到東邊，往來奔跑，尋求耶和華的話，卻尋不著。","notes":[]},{"n":13,"t":"當那日，美貌的處女和少年的男子必因乾渴發昏。","notes":[]},{"n":14,"t":"那指著撒馬利亞牛犢起誓的說：但哪，我們指著你那裏的活神起誓；又說：我們指著別是巴的神道起誓。這些人都必仆倒，永不再起來。","notes":["原文是罪","神：原文是活"]}]},"9":{"heading":"耶和華的審判","verses":[{"n":1,"t":"我看見主站在祭壇旁邊；他說：你要擊打柱頂，使門檻震動，打碎柱頂，落在眾人頭上；所剩下的人，我必用刀殺戮，無一人能逃避，無一人能逃脫。","notes":[]},{"n":2,"t":"他們雖然挖透陰間，我的手必取出他們來；雖然爬上天去，我必拿下他們來；","notes":[]},{"n":3,"t":"雖然藏在迦密山頂，我必搜尋，捉出他們來；雖然從我眼前藏在海底，我必命蛇咬他們；","notes":[]},{"n":4,"t":"雖被仇敵擄去，我必命刀劍殺戮他們；我必向他們定住眼目，降禍不降福。","notes":[]},{"n":5,"t":"主－萬軍之耶和華摸地，地就消化，凡住在地上的都必悲哀。地必全然像尼羅河漲起，如同埃及河落下。","notes":[]},{"n":6,"t":"那在天上建造樓閣、在地上安定穹蒼、命海水澆在地上的－耶和華是他的名。","notes":[]},{"n":7,"t":"耶和華說：以色列人哪，我豈不看你們如古實人嗎？我豈不是領以色列人出埃及地，領非利士人出迦斐託，領亞蘭人出吉珥嗎？","notes":[]},{"n":8,"t":"主耶和華的眼目察看這有罪的國，必將這國從地上滅絕，卻不將雅各家滅絕淨盡。這是耶和華說的。","notes":[]},{"n":9,"t":"我必出令，將以色列家分散在列國中，好像用篩子篩穀，連一粒也不落在地上。","notes":[]},{"n":10,"t":"我民中的一切罪人說：災禍必追不上我們，也迎不著我們。他們必死在刀下。","notes":[]},{"n":11,"t":"到那日，我必建立大衛倒塌的帳幕，堵住其中的破口，把那破壞的建立起來，重新修造，像古時一樣，","notes":[],"heads":["以色列的未來復興"]},{"n":12,"t":"使以色列人得以東所餘剩的和所有稱為我名下的國。此乃行這事的耶和華說的。","notes":[]},{"n":13,"t":"耶和華說：日子將到，耕種的必接續收割的；踹葡萄的必接續撒種的；大山要滴下甜酒；小山都必流奶。","notes":["原文是消化，見約珥三章十八節"]},{"n":14,"t":"我必使我民以色列被擄的歸回；他們必重修荒廢的城邑居住，栽種葡萄園，喝其中所出的酒，修造果木園，吃其中的果子。","notes":[]},{"n":15,"t":"我要將他們栽於本地，他們不再從我所賜給他們的地上拔出來。這是耶和華－你的神說的。","notes":[]}]}},"OBA":{"1":{"heading":"耶和華要懲罰以東","verses":[{"n":1,"t":"俄巴底亞得了耶和華的默示。論以東說：我從耶和華那裏聽見信息，並有使者被差往列國去，說：起來吧，一同起來與以東爭戰！","notes":[]},{"n":2,"t":"我使你－以東在列國中為最小的，被人大大藐視。","notes":[]},{"n":3,"t":"住在山穴中、居所在高處的啊，你因狂傲自欺，心裏說：誰能將我拉下地去呢？","notes":[]},{"n":4,"t":"你雖如大鷹高飛，在星宿之間搭窩，我必從那裏拉下你來。這是耶和華說的。","notes":[]},{"n":5,"t":"盜賊若來在你那裏，或強盜夜間而來－你何竟被剪除－豈不偷竊直到夠了呢？摘葡萄的若來到你那裏，豈不剩下些葡萄呢？","notes":[]},{"n":6,"t":"以掃的隱密處何竟被搜尋？他隱藏的寶物何竟被查出？","notes":[]},{"n":7,"t":"與你結盟的都送你上路，直到交界；與你和好的欺騙你，且勝過你；與你一同吃飯的設下網羅陷害你；在你心裏毫無聰明。","notes":[]},{"n":8,"t":"耶和華說：到那日，我豈不從以東除滅智慧人？從以掃山除滅聰明人？","notes":[]},{"n":9,"t":"提幔哪，你的勇士必驚惶，甚至以掃山的人都被殺戮剪除。","notes":[]},{"n":10,"t":"因你向兄弟雅各行強暴，羞愧必遮蓋你，你也必永遠斷絕。","notes":[],"heads":["以東受罰的原因"]},{"n":11,"t":"當外人擄掠雅各的財物，外邦人進入他的城門，為耶路撒冷拈鬮的日子，你竟站在一旁，像與他們同夥。","notes":[]},{"n":12,"t":"你兄弟遭難的日子，你不當瞪眼看著；猶大人被滅的日子，你不當因此歡樂；他們遭難的日子，你不當說狂傲的話。","notes":[]},{"n":13,"t":"我民遭災的日子，你不當進他們的城門；他們遭災的日子，你不當瞪眼看著他們受苦；他們遭災的日子，你不當伸手搶他們的財物；","notes":[]},{"n":14,"t":"你不當站在岔路口剪除他們中間逃脫的；他們遭難的日子，你不當將他們剩下的人交付仇敵。","notes":[]},{"n":15,"t":"耶和華降罰的日子臨近萬國。你怎樣行，他也必照樣向你行；你的報應必歸到你頭上。","notes":[],"heads":["神要審判萬國"]},{"n":16,"t":"你們猶大人在我聖山怎樣喝了苦杯，萬國也必照樣常常地喝；且喝且咽，他們就歸於無有。","notes":[]},{"n":17,"t":"在錫安山必有逃脫的人，那山也必成聖；雅各家必得原有的產業。","notes":[],"heads":["以色列的勝利"]},{"n":18,"t":"雅各家必成為大火；約瑟家必為火焰；以掃家必如碎稭；火必將他燒著吞滅。以掃家必無餘剩的。這是耶和華說的。","notes":[]},{"n":19,"t":"南地的人必得以掃山；高原的人必得非利士地，也得以法蓮地和撒馬利亞地；便雅憫人必得基列。","notes":[]},{"n":20,"t":"在迦南人中被擄的以色列眾人必得地直到撒勒法；在西法拉中被擄的耶路撒冷人必得南地的城邑。","notes":[]},{"n":21,"t":"必有拯救者上到錫安山，審判以掃山；國度就歸耶和華了。","notes":[]}]}},"JON":{"1":{"heading":"約拿違背耶和華","verses":[{"n":1,"t":"耶和華的話臨到亞米太的兒子約拿，說：","notes":[]},{"n":2,"t":"「你起來往尼尼微大城去，向其中的居民呼喊，因為他們的惡達到我面前。」","notes":[]},{"n":3,"t":"約拿卻起來，逃往他施去躲避耶和華；下到約帕，遇見一隻船，要往他施去。他就給了船價，上了船，要與船上的人同往他施去躲避耶和華。","notes":[]},{"n":4,"t":"然而耶和華使海中起大風，海就狂風大作，甚至船幾乎破壞。","notes":[]},{"n":5,"t":"水手便懼怕，各人哀求自己的神。他們將船上的貨物拋在海中，為要使船輕些。約拿已下到底艙，躺臥沉睡。","notes":[]},{"n":6,"t":"船主到他那裏對他說：「你這沉睡的人哪，為何這樣呢？起來，求告你的神，或者神顧念我們，使我們不致滅亡。」","notes":[]},{"n":7,"t":"船上的人彼此說：「來吧，我們掣籤，看看這災臨到我們是因誰的緣故。」於是他們掣籤，掣出約拿來。","notes":[]},{"n":8,"t":"眾人對他說：「請你告訴我們，這災臨到我們是因誰的緣故？你以何事為業？你從哪裏來？你是哪一國？屬哪一族的人？」","notes":[]},{"n":9,"t":"他說：「我是希伯來人。我敬畏耶和華－那創造滄海旱地之天上的神。」","notes":[]},{"n":10,"t":"他們就大大懼怕，對他說：「你做的是甚麼事呢？」他們已經知道他躲避耶和華，因為他告訴了他們。","notes":[]},{"n":11,"t":"他們問他說：「我們當向你怎樣行，使海浪平靜呢？」這話是因海浪越發翻騰。","notes":[]},{"n":12,"t":"他對他們說：「你們將我抬起來，拋在海中，海就平靜了；我知道你們遭這大風是因我的緣故。」","notes":[]},{"n":13,"t":"然而那些人竭力盪槳，要把船攏岸，卻是不能，因為海浪越發向他們翻騰。","notes":[]},{"n":14,"t":"他們便求告耶和華說：「耶和華啊，我們懇求你，不要因這人的性命使我們死亡，不要使流無辜血的罪歸與我們；因為你－耶和華是隨自己的意旨行事。」","notes":[]},{"n":15,"t":"他們遂將約拿抬起，拋在海中，海的狂浪就平息了。","notes":[]},{"n":16,"t":"那些人便大大敬畏耶和華，向耶和華獻祭，並且許願。","notes":[]},{"n":17,"t":"耶和華安排一條大魚吞了約拿，他在魚腹中三日三夜。","notes":[]}]},"2":{"heading":"約拿的禱告","verses":[{"n":1,"t":"約拿在魚腹中禱告耶和華－他的神，","notes":[]},{"n":2,"t":"說：我遭遇患難求告耶和華，你就應允我；從陰間的深處呼求，你就俯聽我的聲音。","notes":[]},{"n":3,"t":"你將我投下深淵，就是海的深處；大水環繞我，你的波浪洪濤都漫過我身。","notes":[]},{"n":4,"t":"我說：我從你眼前雖被驅逐，我仍要仰望你的聖殿。","notes":[]},{"n":5,"t":"諸水環繞我，幾乎淹沒我；深淵圍住我；海草纏繞我的頭。","notes":[]},{"n":6,"t":"我下到山根，地的門將我永遠關住。耶和華－我的神啊，你卻將我的性命從坑中救出來。","notes":[]},{"n":7,"t":"我心在我裏面發昏的時候，我就想念耶和華。我的禱告進入你的聖殿，達到你的面前。","notes":[]},{"n":8,"t":"那信奉虛無之神的人，離棄憐愛他們的主；","notes":[]},{"n":9,"t":"但我必用感謝的聲音獻祭與你。我所許的願，我必償還。救恩出於耶和華。","notes":[]},{"n":10,"t":"耶和華吩咐魚，魚就把約拿吐在旱地上。","notes":[]}]},"3":{"heading":"約拿順服耶和華","verses":[{"n":1,"t":"耶和華的話二次臨到約拿說：","notes":[]},{"n":2,"t":"「你起來！往尼尼微大城去，向其中的居民宣告我所吩咐你的話。」","notes":[]},{"n":3,"t":"約拿便照耶和華的話起來，往尼尼微去。這尼尼微是極大的城，有三日的路程。","notes":[]},{"n":4,"t":"約拿進城走了一日，宣告說：「再等四十日，尼尼微必傾覆了！」","notes":[]},{"n":5,"t":"尼尼微人信服神，便宣告禁食，從最大的到至小的都穿麻衣。","notes":["或譯：披上麻布"]},{"n":6,"t":"這信息傳到尼尼微王的耳中，他就下了寶座，脫下朝服，披上麻布，坐在灰中。","notes":[]},{"n":7,"t":"他又使人遍告尼尼微通城，說：「王和大臣有令，人不可嘗甚麼，牲畜、牛羊不可吃草，也不可喝水。","notes":[]},{"n":8,"t":"人與牲畜都當披上麻布；人要切切求告神。各人回頭離開所行的惡道，丟棄手中的強暴。","notes":[]},{"n":9,"t":"或者神轉意後悔，不發烈怒，使我們不致滅亡，也未可知。」","notes":[]},{"n":10,"t":"於是神察看他們的行為，見他們離開惡道，他就後悔，不把所說的災禍降與他們了。","notes":[]}]},"4":{"heading":"約拿的忿怒和神的憐憫","verses":[{"n":1,"t":"這事約拿大大不悅，且甚發怒，","notes":[]},{"n":2,"t":"就禱告耶和華說：「耶和華啊，我在本國的時候豈不是這樣說嗎？我知道你是有恩典、有憐憫的神，不輕易發怒，有豐盛的慈愛，並且後悔不降所說的災，所以我急速逃往他施去。","notes":[]},{"n":3,"t":"耶和華啊，現在求你取我的命吧！因為我死了比活著還好。」","notes":[]},{"n":4,"t":"耶和華說：「你這樣發怒合乎理嗎？」","notes":[]},{"n":5,"t":"於是約拿出城，坐在城的東邊，在那裏為自己搭了一座棚，坐在棚的蔭下，要看看那城究竟如何。","notes":[]},{"n":6,"t":"耶和華神安排一棵蓖麻，使其發生高過約拿，影兒遮蓋他的頭，救他脫離苦楚；約拿因這棵蓖麻大大喜樂。","notes":[]},{"n":7,"t":"次日黎明，神卻安排一條蟲子咬這蓖麻，以致枯槁。","notes":[]},{"n":8,"t":"日頭出來的時候，神安排炎熱的東風，日頭曝曬約拿的頭，使他發昏，他就為自己求死，說：「我死了比活著還好！」","notes":[]},{"n":9,"t":"神對約拿說：「你因這棵蓖麻發怒合乎理嗎？」他說：「我發怒以至於死，都合乎理！」","notes":[]},{"n":10,"t":"耶和華說：「這蓖麻不是你栽種的，也不是你培養的；一夜發生，一夜乾死，你尚且愛惜；","notes":[]},{"n":11,"t":"何況這尼尼微大城，其中不能分辨左手右手的有十二萬多人，並有許多牲畜，我豈能不愛惜呢？」","notes":[]}]}},"MIC":{"1":{"heading":"為撒馬利亞和耶路撒冷唱哀歌","verses":[{"n":1,"t":"當猶大王約坦、亞哈斯、希西家在位的時候，摩利沙人彌迦得耶和華的默示，論撒馬利亞和耶路撒冷。","notes":[]},{"n":2,"t":"萬民哪，你們都要聽！地和其上所有的，也都要側耳而聽！主耶和華從他的聖殿要見證你們的不是。","notes":[]},{"n":3,"t":"看哪，耶和華出了他的居所，降臨步行地的高處。","notes":[]},{"n":4,"t":"眾山在他以下必消化，諸谷必崩裂，如蠟化在火中，如水沖下山坡。","notes":[]},{"n":5,"t":"這都因雅各的罪過，以色列家的罪惡。雅各的罪過在哪裏呢？豈不是在撒馬利亞嗎？猶大的邱壇在哪裏呢？豈不是在耶路撒冷嗎？","notes":[]},{"n":6,"t":"所以我必使撒馬利亞變為田野的亂堆，又作為種葡萄之處；也必將她的石頭倒在谷中，露出根基來。","notes":[]},{"n":7,"t":"她一切雕刻的偶像必被打碎；她所得的財物必被火燒；所有的偶像我必毀滅；因為是從妓女雇價所聚來的，後必歸為妓女的雇價。","notes":[]},{"n":8,"t":"先知說：因此我必大聲哀號，赤腳露體而行；又要呼號如野狗，哀鳴如鴕鳥。","notes":[]},{"n":9,"t":"因為撒馬利亞的傷痕無法醫治，延及猶大和耶路撒冷我民的城門。","notes":[]},{"n":10,"t":"不要在迦特報告這事，總不要哭泣；我在伯‧亞弗拉滾於灰塵之中。","notes":[],"heads":["敵人迫近耶路撒冷"]},{"n":11,"t":"沙斐的居民哪，你們要赤身蒙羞過去。撒南的居民不敢出來。伯‧以薛人的哀哭使你們無處可站。","notes":[]},{"n":12,"t":"瑪律的居民心甚憂急，切望得好處，因為災禍從耶和華那裏臨到耶路撒冷的城門。","notes":[]},{"n":13,"t":"拉吉的居民哪，要用快馬套車；錫安民的罪由你而起；以色列人的罪過在你那裏顯出。","notes":["原文是女子"]},{"n":14,"t":"猶大啊，你要將禮物送給摩利設‧迦特。亞革悉的眾族必用詭詐待以色列諸王。","notes":[]},{"n":15,"t":"瑪利沙的居民哪，我必使那奪取你的來到你這裏；以色列的尊貴人必到亞杜蘭。","notes":["原文是榮耀"]},{"n":16,"t":"猶大啊，要為你所喜愛的兒女剪除你的頭髮，使頭光禿，要大大地光禿，如同禿鷹，因為他們都被擄去離開你。","notes":[]}]},"2":{"heading":"欺壓者的命運","verses":[{"n":1,"t":"禍哉，那些在床上圖謀罪孽、造作奸惡的！天一發亮，因手有能力就行出來了。","notes":[]},{"n":2,"t":"他們貪圖田地就佔據，貪圖房屋便奪取；他們欺壓人，霸佔房屋和產業。","notes":[]},{"n":3,"t":"所以耶和華如此說：我籌劃災禍降與這族；這禍在你們的頸項上不能解脫；你們也不能昂首而行，因為這時勢是惡的。","notes":[]},{"n":4,"t":"到那日，必有人向你們提起悲慘的哀歌，譏刺說：我們全然敗落了！耶和華將我們的分轉歸別人，何竟使這分離開我們？他將我們的田地分給悖逆的人。","notes":[]},{"n":5,"t":"所以在耶和華的會中，你必沒有人拈鬮拉準繩。","notes":[]},{"n":6,"t":"他們說：你們不可說預言；不可向這些人說預言，不住地羞辱我們。","notes":["或譯：假先知"]},{"n":7,"t":"雅各家啊，豈可說耶和華的心不忍耐嗎？這些事是他所行的嗎？我－耶和華的言語豈不是與行動正直的人有益嗎？","notes":["或譯：心腸狹窄嗎"]},{"n":8,"t":"然而，近來我的民興起如仇敵，從那些安然經過不願打仗之人身上剝去外衣。","notes":[]},{"n":9,"t":"你們將我民中的婦人從安樂家中趕出，又將我的榮耀從她們的小孩子盡行奪去。","notes":[]},{"n":10,"t":"你們起來去吧！這不是你們安息之所；因為污穢使人毀滅，而且大大毀滅。","notes":["或譯：地"]},{"n":11,"t":"若有人心存虛假，用謊言說：我要向你們預言得清酒和濃酒。那人就必作這民的先知。","notes":[]},{"n":12,"t":"雅各家啊，我必要聚集你們，必要招聚以色列剩下的人，安置在一處，如波斯拉的羊，又如草場上的羊群；因為人數眾多就必大大喧嘩。","notes":[]},{"n":13,"t":"開路的在他們前面上去；他們直闖過城門，從城門出去。他們的王在前面行；耶和華引導他們。","notes":["或譯：破城的"]}]},"3":{"heading":"彌迦斥責以色列的領袖","verses":[{"n":1,"t":"我說：雅各的首領，以色列家的官長啊，你們要聽！你們不當知道公平嗎？","notes":[]},{"n":2,"t":"你們惡善好惡，從人身上剝皮，從人骨頭上剔肉，","notes":[]},{"n":3,"t":"吃我民的肉，剝他們的皮，打折他們的骨頭，分成塊子像要下鍋，又像釜中的肉。","notes":[]},{"n":4,"t":"到了遭災的時候，這些人必哀求耶和華，他卻不應允他們。那時他必照他們所行的惡事向他們掩面。","notes":[]},{"n":5,"t":"論到使我民走差路的先知－他們牙齒有所嚼的，他們就呼喊說：平安了！凡不供給他們吃的，他們就預備攻擊他－耶和華如此說：","notes":["預備攻擊他：或譯說必遭遇刀兵"]},{"n":6,"t":"你們必遭遇黑夜，以致不見異象；又必遭遇幽暗，以致不能占卜。日頭必向你們沉落，白晝變為黑暗。","notes":[]},{"n":7,"t":"先見必抱愧，占卜的必蒙羞，都必摀著嘴唇，因為神不應允他們。","notes":[]},{"n":8,"t":"至於我，我藉耶和華的靈，滿有力量、公平、才能，可以向雅各說明他的過犯，向以色列指出他的罪惡。","notes":[]},{"n":9,"t":"雅各家的首領、以色列家的官長啊，當聽我的話！你們厭惡公平，在一切事上屈枉正直；","notes":[]},{"n":10,"t":"以人血建立錫安，以罪孽建造耶路撒冷。","notes":[]},{"n":11,"t":"首領為賄賂行審判；祭司為雇價施訓誨；先知為銀錢行占卜。他們卻倚賴耶和華，說：耶和華不是在我們中間嗎？災禍必不臨到我們。","notes":[]},{"n":12,"t":"所以因你們的緣故，錫安必被耕種像一塊田，耶路撒冷必變為亂堆；這殿的山必像叢林的高處。","notes":[]}]},"4":{"heading":"耶和華作王，天下太平","verses":[{"n":1,"t":"末後的日子，耶和華殿的山必堅立，超乎諸山，高舉過於萬嶺；萬民都要流歸這山。","notes":[]},{"n":2,"t":"必有許多國的民前往，說：來吧，我們登耶和華的山，奔雅各神的殿。主必將他的道教訓我們；我們也要行他的路。因為訓誨必出於錫安；耶和華的言語必出於耶路撒冷。","notes":[]},{"n":3,"t":"他必在多國的民中施行審判，為遠方強盛的國斷定是非。他們要將刀打成犂頭，把槍打成鐮刀。這國不舉刀攻擊那國；他們也不再學習戰事。","notes":[]},{"n":4,"t":"人人都要坐在自己葡萄樹下和無花果樹下，無人驚嚇。這是萬軍之耶和華親口說的。","notes":[]},{"n":5,"t":"萬民各奉己神的名而行；我們卻永永遠遠奉耶和華－我們神的名而行。","notes":[]},{"n":6,"t":"耶和華說：到那日，我必聚集瘸腿的，招聚被趕出的和我所懲治的。","notes":[],"heads":["以色列人歸回本國"]},{"n":7,"t":"我必使瘸腿的為餘剩之民，使趕到遠方的為強盛之民。耶和華要在錫安山作王治理他們，從今直到永遠。","notes":[]},{"n":8,"t":"你這羊群的高臺、錫安城的山哪，從前的權柄－就是耶路撒冷民的國權－必歸與你。","notes":["原文是女子","原文是女子"]},{"n":9,"t":"現在你為何大聲哭號呢？疼痛抓住你彷彿產難的婦人，是因你中間沒有君王嗎？你的謀士滅亡了嗎？","notes":[]},{"n":10,"t":"錫安的民哪，你要疼痛劬勞，彷彿產難的婦人；因為你必從城裏出來，住在田野，到巴比倫去。在那裏要蒙解救；在那裏耶和華必救贖你脫離仇敵的手。","notes":["原文是女子"]},{"n":11,"t":"現在有許多國的民聚集攻擊你，說：願錫安被玷污！願我們親眼見她遭報！","notes":[]},{"n":12,"t":"他們卻不知道耶和華的意念，也不明白他的籌劃。他聚集他們，好像把禾捆聚到禾場一樣。","notes":[]},{"n":13,"t":"錫安的民哪，起來踹穀吧！我必使你的角成為鐵，使你的蹄成為銅。你必打碎多國的民，將他們的財獻與耶和華，將他們的貨獻與普天下的主。","notes":["原文是女子"]}]},"5":{"heading":"神應許一位掌權者出於伯利恆","verses":[{"n":1,"t":"成群的民哪，現在你要聚集成隊；因為仇敵圍攻我們，要用杖擊打以色列審判者的臉。","notes":["原文是女子"]},{"n":2,"t":"伯利恆的以法他啊，你在猶大諸城中為小，將來必有一位從你那裏出來，在以色列中為我作掌權的；他的根源從亙古，從太初就有。","notes":[]},{"n":3,"t":"耶和華必將以色列人交付敵人，直等那生產的婦人生下子來。那時掌權者其餘的弟兄必歸到以色列人那裏。","notes":["原文是他"]},{"n":4,"t":"他必起來，倚靠耶和華的大能，並耶和華－他神之名的威嚴，牧養他的羊群。他們要安然居住；因為他必日見尊大，直到地極。","notes":[]},{"n":5,"t":"這位必作我們的平安。當亞述人進入我們的地境，踐踏宮殿的時候，我們就立起七個牧者，八個首領攻擊他。","notes":[]},{"n":6,"t":"他們必用刀劍毀壞亞述地和寧錄地的關口。亞述人進入我們的地境踐踏的時候，他必拯救我們。","notes":[]},{"n":7,"t":"雅各餘剩的人必在多國的民中，如從耶和華那裏降下的露水，又如甘霖降在草上；不仗賴人力，也不等候世人之功。","notes":[]},{"n":8,"t":"雅各餘剩的人必在多國多民中，如林間百獸中的獅子，又如少壯獅子在羊群中。他若經過就必踐踏撕裂，無人搭救。","notes":[]},{"n":9,"t":"願你的手舉起，高過敵人！願你的仇敵都被剪除！","notes":[]},{"n":10,"t":"耶和華說：到那日，我必從你中間剪除馬匹，毀壞車輛，","notes":[]},{"n":11,"t":"也必從你國中除滅城邑，拆毀一切的保障，","notes":[]},{"n":12,"t":"又必除掉你手中的邪術；你那裏也不再有占卜的。","notes":[]},{"n":13,"t":"我必從你中間除滅雕刻的偶像和柱像，你就不再跪拜自己手所造的。","notes":[]},{"n":14,"t":"我必從你中間拔出木偶，又毀滅你的城邑。","notes":[]},{"n":15,"t":"我也必在怒氣和忿怒中向那不聽從的列國施報。","notes":[]}]},"6":{"heading":"耶和華譴責以色列","verses":[{"n":1,"t":"以色列人哪，當聽耶和華的話！要起來向山嶺爭辯，使岡陵聽你的話。","notes":[]},{"n":2,"t":"山嶺和地永久的根基啊，要聽耶和華爭辯的話！因為耶和華要與他的百姓爭辯，與以色列爭論。","notes":[]},{"n":3,"t":"我的百姓啊，我向你做了甚麼呢？我在甚麼事上使你厭煩？你可以對我證明。","notes":[]},{"n":4,"t":"我曾將你從埃及地領出來，從作奴僕之家救贖你；我也差遣摩西、亞倫，和米利暗在你前面行。","notes":[]},{"n":5,"t":"我的百姓啊，你們當追念摩押王巴勒所設的謀和比珥的兒子巴蘭回答他的話，並你們從什亭到吉甲所遇見的事，好使你們知道耶和華公義的作為。","notes":[]},{"n":6,"t":"我朝見耶和華，在至高神面前跪拜，當獻上甚麼呢？豈可獻一歲的牛犢為燔祭嗎？","notes":[],"heads":["耶和華的要求"]},{"n":7,"t":"耶和華豈喜悅千千的公羊，或是萬萬的油河嗎？我豈可為自己的罪過獻我的長子嗎？為心中的罪惡獻我身所生的嗎？","notes":[]},{"n":8,"t":"世人哪，耶和華已指示你何為善。他向你所要的是甚麼呢？只要你行公義，好憐憫，存謙卑的心，與你的神同行。","notes":[]},{"n":9,"t":"耶和華向這城呼叫，智慧人必敬畏他的名。你們當聽是誰派定刑杖的懲罰。","notes":[]},{"n":10,"t":"惡人家中不仍有非義之財和可惡的小升斗嗎？","notes":[]},{"n":11,"t":"我若用不公道的天平和囊中詭詐的法碼，豈可算為清潔呢？","notes":[]},{"n":12,"t":"城裏的富戶滿行強暴；其中的居民也說謊言，口中的舌頭是詭詐的。","notes":[]},{"n":13,"t":"因此，我擊打你，使你的傷痕甚重，使你因你的罪惡荒涼。","notes":[]},{"n":14,"t":"你要吃，卻吃不飽；你的虛弱必顯在你中間。你必挪去，卻不得救護；所救護的，我必交給刀劍。","notes":[]},{"n":15,"t":"你必撒種，卻不得收割；踹橄欖，卻不得油抹身；踹葡萄，卻不得酒喝。","notes":[]},{"n":16,"t":"因為你守暗利的惡規，行亞哈家一切所行的，順從他們的計謀；因此，我必使你荒涼，使你的居民令人嗤笑，你們也必擔當我民的羞辱。","notes":[]}]},"7":{"heading":"以色列人的腐敗","verses":[{"n":1,"t":"哀哉！我好像夏天的果子已被收盡，又像摘了葡萄所剩下的，沒有一掛可吃的；我心羨慕初熟的無花果。","notes":["或譯：以色列"]},{"n":2,"t":"地上虔誠人滅盡；世間沒有正直人；各人埋伏，要殺人流血，都用網羅獵取弟兄。","notes":[]},{"n":3,"t":"他們雙手作惡；君王徇情面，審判官要賄賂；位分大的吐出惡意，都彼此結聯行惡。","notes":[]},{"n":4,"t":"他們最好的，不過是蒺藜；最正直的，不過是荊棘籬笆。你守望者說，降罰的日子已經來到。他們必擾亂不安。","notes":[]},{"n":5,"t":"不要倚賴鄰舍；不要信靠密友。要守住你的口；不要向你懷中的妻提說。","notes":[]},{"n":6,"t":"因為，兒子藐視父親；女兒抗拒母親；媳婦抗拒婆婆；人的仇敵就是自己家裏的人。","notes":[]},{"n":7,"t":"至於我，我要仰望耶和華，要等候那救我的神；我的神必應允我。","notes":[]},{"n":8,"t":"我的仇敵啊，不要向我誇耀。我雖跌倒，卻要起來；我雖坐在黑暗裏，耶和華卻作我的光。","notes":[],"heads":["耶和華拯救他的子民"]},{"n":9,"t":"我要忍受耶和華的惱怒；因我得罪了他，直等他為我辨屈，為我伸冤。他必領我到光明中；我必得見他的公義。","notes":[]},{"n":10,"t":"那時我的仇敵，就是曾對我說「耶和華－你神在哪裏」的，他一看見這事就被羞愧遮蓋。我必親眼見他遭報；他必被踐踏，如同街上的泥土。","notes":[]},{"n":11,"t":"以色列啊，日子必到，你的牆垣必重修；到那日，你的境界必開展。","notes":["或譯：命令必傳到遠方"]},{"n":12,"t":"當那日，人必從亞述，從埃及的城邑，從埃及到大河，從這海到那海，從這山到那山，都歸到你這裏。","notes":[]},{"n":13,"t":"然而，這地因居民的緣故，又因他們行事的結果，必然荒涼。","notes":[]},{"n":14,"t":"求耶和華在迦密山的樹林中，用你的杖牧放你獨居的民，就是你產業的羊群。求你容他們在巴珊和基列得食物，像古時一樣。","notes":[],"heads":["耶和華憐憫以色列"]},{"n":15,"t":"耶和華說：我要把奇事顯給他們看，好像出埃及地的時候一樣。","notes":[]},{"n":16,"t":"列國看見這事就必為自己的勢力慚愧；他們必用手摀口，掩耳不聽。","notes":[]},{"n":17,"t":"他們必舔土如蛇，又如土中腹行的物，戰戰兢兢地出他們的營寨。他們必戰懼投降耶和華，也必因我們的神而懼怕。","notes":[]},{"n":18,"t":"神啊，有何神像你，赦免罪孽，饒恕你產業之餘民的罪過，不永遠懷怒，喜愛施恩？","notes":[]},{"n":19,"t":"必再憐憫我們，將我們的罪孽踏在腳下，又將我們的一切罪投於深海。","notes":[]},{"n":20,"t":"你必按古時起誓應許我們列祖的話，向雅各發誠實，向亞伯拉罕施慈愛。","notes":[]}]}},"NAM":{"1":{"heading":"耶和華向尼尼微發怒","verses":[{"n":1,"t":"論尼尼微的默示，就是伊勒歌斯人那鴻所得的默示。","notes":[]},{"n":2,"t":"耶和華是忌邪施報的神。耶和華施報大有忿怒；向他的敵人施報，向他的仇敵懷怒。","notes":[]},{"n":3,"t":"耶和華不輕易發怒，大有能力，萬不以有罪的為無罪。他乘旋風和暴風而來，雲彩為他腳下的塵土。","notes":[]},{"n":4,"t":"他斥責海，使海乾了，使一切江河乾涸。巴珊和迦密的樹林衰殘；黎巴嫩的花草也衰殘了。","notes":[]},{"n":5,"t":"大山因他震動；小山也都消化。大地在他面前突起；世界和住在其間的也都如此。","notes":[]},{"n":6,"t":"他發忿恨，誰能立得住呢？他發烈怒，誰能當得起呢？他的忿怒如火傾倒；磐石因他崩裂。","notes":[]},{"n":7,"t":"耶和華本為善，在患難的日子為人的保障，並且認得那些投靠他的人。","notes":[]},{"n":8,"t":"但他必以漲溢的洪水淹沒尼尼微，又驅逐仇敵進入黑暗。","notes":[]},{"n":9,"t":"尼尼微人哪，設何謀攻擊耶和華呢？他必將你們滅絕淨盡；災難不再興起。","notes":[]},{"n":10,"t":"你們像叢雜的荊棘，像喝醉了的人，又如枯乾的碎稭全然燒滅。","notes":[]},{"n":11,"t":"有一人從你那裏出來，圖謀邪惡，設惡計攻擊耶和華。","notes":[]},{"n":12,"t":"耶和華如此說：尼尼微雖然勢力充足，人數繁多，也被剪除，歸於無有。猶大啊，我雖然使你受苦，卻不再使你受苦。","notes":[]},{"n":13,"t":"現在我必從你頸項上折斷他的軛，扭開他的繩索。","notes":[]},{"n":14,"t":"耶和華已經出令，指著尼尼微說：你名下的人必不留後；我必從你神的廟中除滅雕刻的偶像和鑄造的偶像；我必因你鄙陋，使你歸於墳墓。","notes":[]},{"n":15,"t":"看哪，有報好信傳平安之人的腳登山，說：猶大啊，可以守你的節期，還你所許的願吧！因為那惡人不再從你中間經過，他已滅絕淨盡了。","notes":[]}]},"2":{"heading":"尼尼微的傾覆","verses":[{"n":1,"t":"尼尼微啊，那打碎邦國的上來攻擊你。你要看守保障，謹防道路，使腰強壯，大大勉力。","notes":[]},{"n":2,"t":"耶和華復興雅各的榮華，好像以色列的榮華一樣；因為使地空虛的，已經使雅各和以色列空虛，將他們的葡萄枝毀壞了。）","notes":[]},{"n":3,"t":"他勇士的盾牌是紅的，精兵都穿朱紅衣服。在他預備爭戰的日子，戰車上的鋼鐵閃爍如火，柏木把的槍也掄起來了。","notes":[]},{"n":4,"t":"車輛在街上急行，在寬闊處奔來奔去，形狀如火把，飛跑如閃電。","notes":["或譯：城外"]},{"n":5,"t":"尼尼微王招聚他的貴冑；他們步行絆跌，速上城牆，預備擋牌。","notes":[]},{"n":6,"t":"河閘開放，宮殿沖沒。","notes":[]},{"n":7,"t":"王后蒙羞，被人擄去；宮女搥胸，哀鳴如鴿。此乃命定之事。","notes":[]},{"n":8,"t":"尼尼微自古以來充滿人民，如同聚水的池子；現在居民卻都逃跑。雖有人呼喊說：站住！站住！卻無人回顧。","notes":[]},{"n":9,"t":"你們搶掠金銀吧！因為所積蓄的無窮，華美的寶器無數。","notes":[]},{"n":10,"t":"尼尼微現在空虛荒涼，人心消化，雙膝相碰，腰都疼痛，臉都變色。","notes":[]},{"n":11,"t":"獅子的洞和少壯獅子餵養之處在哪裏呢？公獅母獅小獅遊行、無人驚嚇之地在哪裏呢？","notes":[]},{"n":12,"t":"公獅為小獅撕碎許多食物，為母獅掐死活物，把撕碎的、掐死的充滿牠的洞穴。","notes":[]},{"n":13,"t":"萬軍之耶和華說：「我與你為敵，必將你的車輛焚燒成煙，刀劍也必吞滅你的少壯獅子。我必從地上除滅你所撕碎的，你使者的聲音必不再聽見。」","notes":[]}]},"3":{"heading":"","verses":[{"n":1,"t":"禍哉！這流人血的城，充滿謊詐和強暴－搶奪的事總不止息。","notes":[]},{"n":2,"t":"鞭聲響亮，車輪轟轟，馬匹踢跳，車輛奔騰，","notes":[]},{"n":3,"t":"馬兵爭先，刀劍發光，槍矛閃爍，被殺的甚多，屍首成了大堆，屍骸無數，人碰著而跌倒，","notes":[]},{"n":4,"t":"都因那美貌的妓女多有淫行，慣行邪術，藉淫行誘惑列國，用邪術誘惑多族。","notes":["原文是賣"]},{"n":5,"t":"萬軍之耶和華說：我與你為敵；我必揭起你的衣襟，蒙在你臉上，使列國看見你的赤體，使列邦觀看你的醜陋。","notes":[]},{"n":6,"t":"我必將可憎污穢之物拋在你身上，辱沒你，為眾目所觀。","notes":[]},{"n":7,"t":"凡看見你的，都必逃跑離開你，說：尼尼微荒涼了！有誰為你悲傷呢？我何處尋得安慰你的人呢？","notes":[]},{"n":8,"t":"你豈比挪亞們強呢？挪亞們坐落在眾河之間，周圍有水；海作她的濠溝，又作她的城牆。","notes":["指尼羅河"]},{"n":9,"t":"古實和埃及是她無窮的力量；弗人和路比族是她的幫手。","notes":[]},{"n":10,"t":"但她被遷移，被擄去；她的嬰孩在各市口上也被摔死。人為她的尊貴人拈鬮；她所有的大人都被鍊子鎖著。","notes":[]},{"n":11,"t":"你也必喝醉，必被埋藏，並因仇敵的緣故尋求避難所。","notes":[]},{"n":12,"t":"你一切保障必像無花果樹上初熟的無花果，若一搖撼就落在想吃之人的口中。","notes":[]},{"n":13,"t":"你地上的人民如同婦女；你國中的關口向仇敵敞開；你的門閂被火焚燒。","notes":[]},{"n":14,"t":"你要打水預備受困；要堅固你的保障，踹土和泥，修補磚窯。","notes":[]},{"n":15,"t":"在那裏，火必燒滅你；刀必殺戮你，吞滅你如同蝻子。任你加增人數多如蝻子，多如蝗蟲吧！","notes":[]},{"n":16,"t":"你增添商賈，多過天上的星；蝻子吃盡而去。","notes":[]},{"n":17,"t":"你的首領多如蝗蟲；你的軍長彷彿成群的螞蚱，天涼的時候齊落在籬笆上，日頭一出便都飛去，人不知道落在何處。","notes":[]},{"n":18,"t":"亞述王啊，你的牧人睡覺；你的貴冑安歇；你的人民散在山間，無人招聚。","notes":[]},{"n":19,"t":"你的損傷無法醫治；你的傷痕極其重大。凡聽你信息的必都因此向你拍掌。你所行的惡誰沒有時常遭遇呢？","notes":[]}]}},"HAB":{"1":{"heading":"哈巴谷為不公平而訴苦","verses":[{"n":1,"t":"先知哈巴谷所得的默示。","notes":[]},{"n":2,"t":"他說：耶和華啊！我呼求你，你不應允，要到幾時呢？我因強暴哀求你，你還不拯救。","notes":[]},{"n":3,"t":"你為何使我看見罪孽？你為何看著奸惡而不理呢？毀滅和強暴在我面前，又起了爭端和相鬥的事。","notes":[]},{"n":4,"t":"因此律法放鬆，公理也不顯明；惡人圍困義人，所以公理顯然顛倒。","notes":[]},{"n":5,"t":"耶和華說：你們要向列國中觀看，大大驚奇；因為在你們的時候，我行一件事，雖有人告訴你們，你們總是不信。","notes":[],"heads":["耶和華的回答"]},{"n":6,"t":"我必興起迦勒底人，就是那殘忍暴躁之民，通行遍地，佔據那不屬自己的住處。","notes":[]},{"n":7,"t":"他威武可畏，判斷和勢力都任意發出。","notes":[]},{"n":8,"t":"他的馬比豹更快，比晚上的豺狼更猛。馬兵踴躍爭先，都從遠方而來；他們飛跑如鷹抓食，","notes":[]},{"n":9,"t":"都為行強暴而來，定住臉面向前，將擄掠的人聚集，多如塵沙。","notes":[]},{"n":10,"t":"他們譏誚君王，笑話首領，嗤笑一切保障，築壘攻取。","notes":[]},{"n":11,"t":"他以自己的勢力為神，像風猛然掃過，顯為有罪。","notes":[]},{"n":12,"t":"耶和華－我的神，我的聖者啊，你不是從亙古而有嗎？我們必不致死。耶和華啊，你派定他為要刑罰人；磐石啊，你設立他為要懲治人。","notes":[],"heads":["哈巴谷又向耶和華訴苦"]},{"n":13,"t":"你眼目清潔，不看邪僻，不看奸惡；行詭詐的，你為何看著不理呢？惡人吞滅比自己公義的，你為何靜默不語呢？","notes":[]},{"n":14,"t":"你為何使人如海中的魚，又如沒有管轄的爬物呢？","notes":[]},{"n":15,"t":"他用鉤鉤住，用網捕獲，用拉網聚集他們；因此，他歡喜快樂，","notes":[]},{"n":16,"t":"就向網獻祭，向網燒香，因他由此得肥美的分和富裕的食物。","notes":[]},{"n":17,"t":"他豈可屢次倒空網羅，將列國的人時常殺戮，毫不顧惜呢？","notes":[]}]},"2":{"heading":"耶和華回答哈巴谷","verses":[{"n":1,"t":"我要站在守望所，立在望樓上觀看，看耶和華對我說甚麼話，我可用甚麼話向他訴冤。","notes":["向他訴冤：或譯回答所疑問的"]},{"n":2,"t":"他對我說：將這默示明明地寫在版上，使讀的人容易讀。","notes":["或譯：隨跑隨讀"]},{"n":3,"t":"因為這默示有一定的日期，快要應驗，並不虛謊。雖然遲延，還要等候；因為必然臨到，不再遲延。","notes":[]},{"n":4,"t":"迦勒底人自高自大，心不正直；惟義人因信得生。","notes":[]},{"n":5,"t":"迦勒底人因酒詭詐，狂傲，不住在家中，擴充心欲，好像陰間。他如死不能知足，聚集萬國，堆積萬民都歸自己。","notes":[],"heads":["不義的結局"]},{"n":6,"t":"這些國的民豈不都要提起詩歌並俗語譏刺他說：禍哉！迦勒底人，你增添不屬自己的財物，多多取人的當頭，要到幾時為止呢？","notes":[]},{"n":7,"t":"咬傷你的豈不忽然起來，擾害你的豈不興起，你就作他們的擄物嗎？","notes":[]},{"n":8,"t":"因你搶奪許多的國，殺人流血，向國內的城並城中一切居民施行強暴，所以各國剩下的民都必搶奪你。","notes":[]},{"n":9,"t":"為本家積蓄不義之財、在高處搭窩、指望免災的有禍了！","notes":[]},{"n":10,"t":"你圖謀剪除多國的民，犯了罪，使你的家蒙羞，自害己命。","notes":[]},{"n":11,"t":"牆裏的石頭必呼叫；房內的棟樑必應聲。","notes":[]},{"n":12,"t":"以人血建城、以罪孽立邑的有禍了！","notes":[]},{"n":13,"t":"眾民所勞碌得來的被火焚燒，列國由勞乏而得的歸於虛空，不都是出於萬軍之耶和華嗎？","notes":[]},{"n":14,"t":"認識耶和華榮耀的知識要充滿遍地，好像水充滿洋海一般。","notes":[]},{"n":15,"t":"給人酒喝、又加上毒物、使他喝醉、好看見他下體的有禍了！","notes":[]},{"n":16,"t":"你滿受羞辱，不得榮耀；你也喝吧，顯出是未受割禮的！耶和華右手的杯必傳到你那裏；你的榮耀就變為大大地羞辱。","notes":[]},{"n":17,"t":"你向黎巴嫩行強暴與殘害驚嚇野獸的事必遮蓋你；因你殺人流血，向國內的城並城中一切居民施行強暴。","notes":[]},{"n":18,"t":"雕刻的偶像，人將它刻出來，有甚麼益處呢？鑄造的偶像就是虛謊的師傅。製造者倚靠這啞巴偶像有甚麼益處呢？","notes":[]},{"n":19,"t":"對木偶說：醒起！對啞巴石像說：起來！那人有禍了！這個還能教訓人嗎？看哪，是包裹金銀的，其中毫無氣息。","notes":[]},{"n":20,"t":"惟耶和華在他的聖殿中；全地的人都當在他面前肅敬靜默。","notes":[]}]},"3":{"heading":"哈巴谷的祈禱","verses":[{"n":1,"t":"先知哈巴谷的禱告，調用流離歌。","notes":[]},{"n":2,"t":"耶和華啊，我聽見你的名聲就懼怕。耶和華啊，求你在這些年間復興你的作為，在這些年間顯明出來；在發怒的時候以憐憫為念。","notes":["或譯：言語"]},{"n":3,"t":"神從提幔而來；聖者從巴蘭山臨到。（細拉）他的榮光遮蔽諸天；頌讚充滿大地。","notes":[]},{"n":4,"t":"他的輝煌如同日光；從他手裏射出光線，在其中藏著他的能力。","notes":[]},{"n":5,"t":"在他前面有瘟疫流行；在他腳下有熱症發出。","notes":[]},{"n":6,"t":"他站立，量了大地，觀看，趕散萬民。永久的山崩裂；長存的嶺塌陷；他的作為與古時一樣。","notes":["或譯：使地震動"]},{"n":7,"t":"我見古珊的帳棚遭難，米甸的幔子戰兢。","notes":[]},{"n":8,"t":"耶和華啊，你乘在馬上，坐在得勝的車上，豈是不喜悅江河、向江河發怒氣、向洋海發憤恨嗎？","notes":[]},{"n":9,"t":"你的弓全然顯露，向眾支派所起的誓都是可信的。（細拉）你以江河分開大地。","notes":[]},{"n":10,"t":"山嶺見你，無不戰懼；大水氾濫過去，深淵發聲，洶湧翻騰。","notes":["原文是向上舉手"]},{"n":11,"t":"因你的箭射出發光，你的槍閃出光耀，日月都在本宮停住。","notes":[]},{"n":12,"t":"你發忿恨通行大地，發怒氣責打列國，如同打糧。","notes":[]},{"n":13,"t":"你出來要拯救你的百姓，拯救你的受膏者，打破惡人家長的頭，露出他的腳，直到頸項。（細拉）","notes":["原文是根基"]},{"n":14,"t":"你用敵人的戈矛刺透他戰士的頭；他們來如旋風，要將我們分散。他們所喜愛的是暗中吞吃貧民。","notes":[]},{"n":15,"t":"你乘馬踐踏紅海，就是踐踏洶湧的大水。","notes":[]},{"n":16,"t":"我聽見耶和華的聲音，身體戰兢，嘴唇發顫，骨中朽爛；我在所立之處戰兢。我只可安靜等候災難之日臨到，犯境之民上來。","notes":[]},{"n":17,"t":"雖然無花果樹不發旺，葡萄樹不結果，橄欖樹也不效力，田地不出糧食，圈中絕了羊，棚內也沒有牛；","notes":[]},{"n":18,"t":"然而，我要因耶和華歡欣，因救我的神喜樂。","notes":[]},{"n":19,"t":"主耶和華是我的力量；他使我的腳快如母鹿的蹄，又使我穩行在高處。這歌交與伶長，用絲弦的樂器。","notes":[]}]}},"ZEP":{"1":{"heading":"耶和華審判的日子","verses":[{"n":1,"t":"當猶大王亞們的兒子約西亞在位的時候，耶和華的話臨到希西家的玄孫，亞瑪利雅的曾孫，基大利的孫子，古示的兒子西番雅。","notes":[]},{"n":2,"t":"耶和華說：我必從地上除滅萬類。","notes":[]},{"n":3,"t":"我必除滅人和牲畜，與空中的鳥、海裏的魚，以及絆腳石和惡人；我必將人從地上剪除。這是耶和華說的。","notes":[]},{"n":4,"t":"我必伸手攻擊猶大和耶路撒冷的一切居民，也必從這地方剪除所剩下的巴力，並基瑪林的名和祭司，","notes":[]},{"n":5,"t":"與那些在房頂上敬拜天上萬象的，並那些敬拜耶和華指著他起誓，又指著瑪勒堪起誓的，","notes":[]},{"n":6,"t":"與那些轉去不跟從耶和華的，和不尋求耶和華也不訪問他的。","notes":[]},{"n":7,"t":"你要在主耶和華面前靜默無聲，因為耶和華的日子快到。耶和華已經預備祭物，將他的客分別為聖。","notes":[]},{"n":8,"t":"到了我－耶和華獻祭的日子，必懲罰首領和王子，並一切穿外邦衣服的。","notes":[]},{"n":9,"t":"到那日，我必懲罰一切跳過門檻、將強暴和詭詐得來之物充滿主人房屋的。","notes":[]},{"n":10,"t":"耶和華說：當那日，從魚門必發出悲哀的聲音，從二城發出哀號的聲音，從山間發出大破裂的響聲。","notes":[]},{"n":11,"t":"瑪革提施的居民哪，你們要哀號，因為迦南的商民都滅亡了！凡搬運銀子的都被剪除。","notes":[]},{"n":12,"t":"那時，我必用燈巡查耶路撒冷；我必懲罰那些如酒在渣滓上澄清的；他們心裏說：耶和華必不降福，也不降禍。","notes":[]},{"n":13,"t":"他們的財寶必成為掠物；他們的房屋必變為荒場。他們必建造房屋，卻不得住在其內；栽種葡萄園，卻不得喝所出的酒。","notes":[]},{"n":14,"t":"耶和華的大日臨近，臨近而且甚快，乃是耶和華日子的風聲；勇士必痛痛地哭號。","notes":[]},{"n":15,"t":"那日是忿怒的日子，是急難困苦的日子，是荒廢淒涼的日子，是黑暗幽冥、密雲烏黑的日子，","notes":[]},{"n":16,"t":"是吹角吶喊的日子，要攻擊堅固城和高大的城樓。","notes":[]},{"n":17,"t":"我必使災禍臨到人身上，使他們行走如同瞎眼的，因為得罪了我。他們的血必倒出如灰塵；他們的肉必拋棄如糞土。","notes":[]},{"n":18,"t":"當耶和華發怒的日子，他們的金銀不能救他們；他的忿怒如火必燒滅全地，毀滅這地的一切居民，而且大大毀滅。","notes":[]}]},"2":{"heading":"呼籲百姓悔改","verses":[{"n":1,"t":"不知羞恥的國民哪，你們應當聚集！趁命令沒有發出，日子過去如風前的糠，耶和華的烈怒未臨到你們，他發怒的日子未到以先，你們應當聚集前來。","notes":[],"end":2},{"n":3,"t":"世上遵守耶和華典章的謙卑人哪，你們都當尋求耶和華！當尋求公義謙卑，或者在耶和華發怒的日子可以隱藏起來。","notes":[]},{"n":4,"t":"迦薩必致見棄；亞實基倫必然荒涼。人在正午必趕出亞實突的民；以革倫也被拔出根來。","notes":[],"heads":["以色列鄰國的結局"]},{"n":5,"t":"住沿海之地的基利提族有禍了！迦南、非利士人之地啊，耶和華的話與你反對，說：我必毀滅你，以致無人居住。","notes":[]},{"n":6,"t":"沿海之地要變為草場，其上有牧人的住處和羊群的圈。","notes":[]},{"n":7,"t":"這地必為猶大家剩下的人所得；他們必在那裏牧放群羊，晚上必躺臥在亞實基倫的房屋中；因為耶和華－他們的神必眷顧他們，使他們被擄的人歸回。","notes":[]},{"n":8,"t":"我聽見摩押人的毀謗和亞捫人的辱罵，就是毀謗我的百姓，自誇自大，侵犯他們的境界。","notes":[]},{"n":9,"t":"萬軍之耶和華－以色列的神說：我指著我的永生起誓：摩押必像所多瑪，亞捫人必像蛾摩拉，都變為刺草、鹽坑、永遠荒廢之地。我百姓所剩下的必擄掠他們；我國中所餘剩的必得著他們的地。","notes":[]},{"n":10,"t":"這事臨到他們是因他們驕傲，自誇自大，毀謗萬軍之耶和華的百姓。","notes":[]},{"n":11,"t":"耶和華必向他們顯可畏之威，因他必叫世上的諸神瘦弱。列國海島的居民各在自己的地方敬拜他。","notes":[]},{"n":12,"t":"古實人哪，你們必被我的刀所殺。","notes":[]},{"n":13,"t":"耶和華必伸手攻擊北方，毀滅亞述，使尼尼微荒涼，又乾旱如曠野。","notes":[]},{"n":14,"t":"群畜，就是各國的走獸必臥在其中；鵜鶘和箭豬要宿在柱頂上。在窗戶內有鳴叫的聲音；門檻都必毀壞，香柏木已經露出。","notes":["國：或譯類"]},{"n":15,"t":"這是素來歡樂安然居住的城，心裏說：惟有我，除我以外再沒有別的；現在何竟荒涼成為野獸躺臥之處！凡經過的人都必搖手嗤笑她。","notes":[]}]},"3":{"heading":"耶路撒冷的罪惡和救贖","verses":[{"n":1,"t":"這悖逆、污穢、欺壓的城有禍了！","notes":[]},{"n":2,"t":"她不聽從命令，不領受訓誨，不倚靠耶和華，不親近她的神。","notes":[]},{"n":3,"t":"她中間的首領是咆哮的獅子；她的審判官是晚上的豺狼，一點食物也不留到早晨。","notes":[]},{"n":4,"t":"她的先知是虛浮詭詐的人；她的祭司褻瀆聖所，強解律法。","notes":[]},{"n":5,"t":"耶和華在她中間是公義的，斷不做非義的事，每早晨顯明他的公義，無日不然；只是不義的人不知羞恥。","notes":[]},{"n":6,"t":"我－耶和華已經除滅列國的民；他們的城樓毀壞。我使他們的街道荒涼，以致無人經過；他們的城邑毀滅，以致無人，也無居民。","notes":[]},{"n":7,"t":"我說：你只要敬畏我，領受訓誨；如此，你的住處不致照我所擬定的除滅。只是你們從早起來就在一切事上敗壞自己。","notes":[]},{"n":8,"t":"耶和華說：你們要等候我，直到我興起擄掠的日子；因為我已定意招聚列國，聚集列邦，將我的惱怒－就是我的烈怒都傾在她們身上。我的忿怒如火，必燒滅全地。","notes":[]},{"n":9,"t":"那時，我必使萬民用清潔的言語好求告我－耶和華的名，同心合意地事奉我。","notes":[]},{"n":10,"t":"祈禱我的，就是我所分散的民，必從古實河外來，給我獻供物。","notes":["原文是女子；下同"]},{"n":11,"t":"當那日，你必不因你一切得罪我的事自覺羞愧；因為那時我必從你中間除掉矜誇高傲之輩，你也不再於我的聖山狂傲。","notes":[]},{"n":12,"t":"我卻要在你中間留下困苦貧寒的民；他們必投靠我－耶和華的名。","notes":[]},{"n":13,"t":"以色列所剩下的人必不作罪孽，不說謊言，口中也沒有詭詐的舌頭；而且吃喝躺臥，無人驚嚇。","notes":[]},{"n":14,"t":"錫安的民哪，應當歌唱！以色列啊，應當歡呼！耶路撒冷的民哪，應當滿心歡喜快樂！","notes":[],"heads":["歡樂之歌"]},{"n":15,"t":"耶和華已經除去你的刑罰，趕出你的仇敵。以色列的王－耶和華在你中間；你必不再懼怕災禍。","notes":[]},{"n":16,"t":"當那日，必有話向耶路撒冷說：不要懼怕！錫安哪；不要手軟！","notes":[]},{"n":17,"t":"耶和華－你的神是施行拯救、大有能力的主。他在你中間必因你歡欣喜樂，默然愛你，且因你喜樂而歡呼。","notes":[]},{"n":18,"t":"那些屬你、為無大會愁煩、因你擔當羞辱的，我必聚集他們。","notes":[]},{"n":19,"t":"那時，我必罰辦一切苦待你的人，又拯救你瘸腿的，聚集你被趕出的。那些在全地受羞辱的，我必使他們得稱讚，有名聲。","notes":[]},{"n":20,"t":"那時，我必領你們進來，聚集你們；我使你們被擄之人歸回的時候，就必使你們在地上的萬民中有名聲，得稱讚。這是耶和華說的。","notes":[]}]}},"HAG":{"1":{"heading":"耶和華命令重建聖殿","verses":[{"n":1,"t":"大流士王第二年六月初一日，耶和華的話藉先知哈該向猶大省長撒拉鐵的兒子所羅巴伯和約撒答的兒子大祭司約書亞說：","notes":[]},{"n":2,"t":"萬軍之耶和華如此說：「這百姓說，建造耶和華殿的時候尚未來到。」","notes":[]},{"n":3,"t":"那時耶和華的話臨到先知哈該說：","notes":[]},{"n":4,"t":"「這殿仍然荒涼，你們自己還住天花板的房屋嗎？","notes":[]},{"n":5,"t":"現在萬軍之耶和華如此說：你們要省察自己的行為。","notes":[]},{"n":6,"t":"你們撒的種多，收的卻少；你們吃，卻不得飽；喝，卻不得足；穿衣服，卻不得暖；得工錢的，將工錢裝在破漏的囊中。」","notes":[]},{"n":7,"t":"萬軍之耶和華如此說：「你們要省察自己的行為。","notes":[]},{"n":8,"t":"你們要上山取木料，建造這殿，我就因此喜樂，且得榮耀。這是耶和華說的。","notes":[]},{"n":9,"t":"你們盼望多得，所得的卻少；你們收到家中，我就吹去。這是為甚麼呢？因為我的殿荒涼，你們各人卻顧自己的房屋。這是萬軍之耶和華說的。","notes":["原文是奔"]},{"n":10,"t":"所以為你們的緣故，天就不降甘露，地也不出土產。","notes":[]},{"n":11,"t":"我命乾旱臨到地土、山岡、五穀、新酒，和油，並地上的出產、人民、牲畜，以及人手一切勞碌得來的。」","notes":[]},{"n":12,"t":"那時，撒拉鐵的兒子所羅巴伯和約撒答的兒子大祭司約書亞，並剩下的百姓，都聽從耶和華－他們神的話和先知哈該奉耶和華－他們神差來所說的話；百姓也在耶和華面前存敬畏的心。","notes":[],"heads":["百姓順從耶和華的命令"]},{"n":13,"t":"耶和華的使者哈該奉耶和華差遣對百姓說：「耶和華說：我與你們同在。」","notes":[]},{"n":14,"t":"耶和華激動猶大省長撒拉鐵的兒子所羅巴伯和約撒答的兒子大祭司約書亞，並剩下之百姓的心，他們就來為萬軍之耶和華－他們神的殿做工。","notes":[]},{"n":15,"t":"這是在大流士王第二年六月二十四日。","notes":[]}]},"2":{"heading":"新殿的榮耀","verses":[{"n":1,"t":"七月二十一日，耶和華的話臨到先知哈該說：","notes":[]},{"n":2,"t":"「你要曉諭猶大省長撒拉鐵的兒子所羅巴伯和約撒答的兒子大祭司約書亞，並剩下的百姓，說：","notes":[]},{"n":3,"t":"你們中間存留的，有誰見過這殿從前的榮耀呢？現在你們看著如何？豈不在眼中看如無有嗎？」","notes":[]},{"n":4,"t":"耶和華說：「所羅巴伯啊，雖然如此，你當剛強！約撒答的兒子大祭司約書亞啊，你也當剛強！這地的百姓，你們都當剛強做工，因為我與你們同在。這是萬軍之耶和華說的。","notes":[]},{"n":5,"t":"這是照著你們出埃及我與你們立約的話。那時，我的靈住在你們中間，你們不要懼怕。」","notes":[]},{"n":6,"t":"萬軍之耶和華如此說：「過不多時，我必再一次震動天地、滄海，與旱地。","notes":[]},{"n":7,"t":"我必震動萬國；萬國的珍寶必都運來，我就使這殿滿了榮耀。這是萬軍之耶和華說的。」","notes":["或譯：萬國所羨慕的必來到"]},{"n":8,"t":"萬軍之耶和華說：「銀子是我的，金子也是我的。","notes":[]},{"n":9,"t":"這殿後來的榮耀必大過先前的榮耀；在這地方我必賜平安。這是萬軍之耶和華說的。」","notes":[]},{"n":10,"t":"大流士王第二年九月二十四日，耶和華的話臨到先知哈該說：","notes":[],"heads":["先知向祭司請教"]},{"n":11,"t":"萬軍之耶和華如此說：「你要向祭司問律法，","notes":[]},{"n":12,"t":"說：若有人用衣襟兜聖肉，這衣襟挨著餅，或湯，或酒，或油，或別的食物，便算為聖嗎？」祭司說：「不算為聖。」","notes":[]},{"n":13,"t":"哈該又說：「若有人因摸死屍染了污穢，然後挨著這些物的哪一樣，這物算污穢嗎？」祭司說：「必算污穢。」","notes":[]},{"n":14,"t":"於是哈該說：「耶和華說：這民這國，在我面前也是如此；他們手下的各樣工作都是如此；他們在壇上所獻的也是如此。」","notes":[]},{"n":15,"t":"現在你們要追想，此日以前，耶和華的殿沒有一塊石頭壘在石頭上的光景。","notes":[],"heads":["耶和華應許賜福"]},{"n":16,"t":"在那一切日子，有人來到穀堆，想得二十斗，只得了十斗。有人來到酒池，想得五十桶，只得了二十桶。","notes":[]},{"n":17,"t":"在你們手下的各樣工作上，我以旱風、霉爛、冰雹攻擊你們，你們仍不歸向我。這是耶和華說的。","notes":[]},{"n":18,"t":"你們要追想此日以前，就是從這九月二十四日起，追想到立耶和華殿根基的日子。","notes":[]},{"n":19,"t":"倉裏有穀種嗎？葡萄樹、無花果樹、石榴樹、橄欖樹都沒有結果子。從今日起，我必賜福與你們。","notes":[]},{"n":20,"t":"這月二十四日，耶和華的話二次臨到哈該說：","notes":[],"heads":["耶和華給所羅巴伯的應許"]},{"n":21,"t":"「你要告訴猶大省長所羅巴伯說：我必震動天地。","notes":[]},{"n":22,"t":"我必傾覆列國的寶座，除滅列邦的勢力，並傾覆戰車和坐在其上的。馬必跌倒，騎馬的敗落，各人被弟兄的刀所殺。","notes":[]},{"n":23,"t":"萬軍之耶和華說：我僕人撒拉鐵的兒子所羅巴伯啊，到那日，我必以你為印，因我揀選了你。這是萬軍之耶和華說的。」","notes":[]}]}},"ZEC":{"1":{"heading":"耶和華呼喚子民歸向他","verses":[{"n":1,"t":"大流士王第二年八月，耶和華的話臨到易多的孫子、比利家的兒子先知撒迦利亞，說：","notes":[]},{"n":2,"t":"「耶和華曾向你們列祖大大發怒。","notes":[]},{"n":3,"t":"所以你要對以色列人說，萬軍之耶和華如此說：你們要轉向我，我就轉向你們。這是萬軍之耶和華說的。","notes":[]},{"n":4,"t":"不要效法你們列祖。從前的先知呼叫他們說，萬軍之耶和華如此說：『你們要回頭離開你們的惡道惡行。』他們卻不聽，也不順從我。這是耶和華說的。","notes":[]},{"n":5,"t":"你們的列祖在哪裏呢？那些先知能永遠存活嗎？","notes":[]},{"n":6,"t":"只是我的言語和律例，就是所吩咐我僕人眾先知的，豈不臨到你們列祖嗎？他們就回頭，說：『萬軍之耶和華定意按我們的行動作為向我們怎樣行，他已照樣行了。』」","notes":[]},{"n":7,"t":"大流士第二年十一月，就是細罷特月二十四日，耶和華的話臨到易多的孫子、比利家的兒子先知撒迦利亞，說：","notes":[],"heads":["馬的異象"]},{"n":8,"t":"「我夜間觀看，見一人騎著紅馬，站在窪地番石榴樹中間。在他身後又有紅馬、黃馬，和白馬。」","notes":[]},{"n":9,"t":"我對與我說話的天使說：「主啊，這是甚麼意思？」他說：「我要指示你這是甚麼意思。」","notes":[]},{"n":10,"t":"那站在番石榴樹中間的人說：「這是奉耶和華差遣在遍地走來走去的。」","notes":[]},{"n":11,"t":"那些騎馬的對站在番石榴樹中間耶和華的使者說：「我們已在遍地走來走去，見全地都安息平靜。」","notes":[]},{"n":12,"t":"於是，耶和華的使者說：「萬軍之耶和華啊，你惱恨耶路撒冷和猶大的城邑已經七十年，你不施憐憫要到幾時呢？」","notes":[]},{"n":13,"t":"耶和華就用美善的安慰話回答那與我說話的天使。","notes":[]},{"n":14,"t":"與我說話的天使對我說：「你要宣告說，萬軍之耶和華如此說：我為耶路撒冷為錫安，心裏極其火熱。","notes":[]},{"n":15,"t":"我甚惱怒那安逸的列國，因我從前稍微惱怒我民，他們就加害過分。","notes":[]},{"n":16,"t":"所以耶和華如此說：現今我回到耶路撒冷，仍施憐憫，我的殿必重建在其中，準繩必拉在耶路撒冷之上。這是萬軍之耶和華說的。","notes":[]},{"n":17,"t":"你要再宣告說，萬軍之耶和華如此說：我的城邑必再豐盛發達。耶和華必再安慰錫安，揀選耶路撒冷。」","notes":[]},{"n":18,"t":"我舉目觀看，見有四角。","notes":[],"heads":["角的異象"]},{"n":19,"t":"我就問與我說話的天使說：「這是甚麼意思？」他回答說：「這是打散猶大、以色列，和耶路撒冷的角。」","notes":[]},{"n":20,"t":"耶和華又指四個匠人給我看。","notes":[]},{"n":21,"t":"我說：「他們來做甚麼呢？」他說：「這是打散猶大的角，使人不敢抬頭；但這些匠人來威嚇列國，打掉他們的角，就是舉起打散猶大地的角。」","notes":[]}]},"2":{"heading":"準繩的異象","verses":[{"n":1,"t":"我又舉目觀看，見一人手拿準繩。","notes":[]},{"n":2,"t":"我說：「你往哪裏去？」他對我說：「要去量耶路撒冷，看有多寬多長。」","notes":[]},{"n":3,"t":"與我說話的天使去的時候，又有一位天使迎著他來，","notes":[]},{"n":4,"t":"對他說：「你跑去告訴那少年人說，耶路撒冷必有人居住，好像無城牆的鄉村，因為人民和牲畜甚多。","notes":[]},{"n":5,"t":"耶和華說：我要作耶路撒冷四圍的火城，並要作其中的榮耀。」","notes":[]},{"n":6,"t":"耶和華說：「我從前分散你們在天的四方，現在你們要從北方之地逃回。這是耶和華說的。","notes":["原文是猶如天的四風"],"heads":["呼喚被擄者歸回"]},{"n":7,"t":"與巴比倫人同住的錫安民哪，應當逃脫。","notes":[]},{"n":8,"t":"萬軍之耶和華說，在顯出榮耀之後，差遣我去懲罰那擄掠你們的列國，摸你們的就是摸他眼中的瞳人。","notes":[]},{"n":9,"t":"看哪，我要向他們掄手，他們就必作服事他們之人的擄物，你們便知道萬軍之耶和華差遣我了。","notes":["或譯：他"]},{"n":10,"t":"錫安城啊，應當歡樂歌唱，因為我來要住在你中間。這是耶和華說的。」","notes":[]},{"n":11,"t":"那時，必有許多國歸附耶和華，作他的子民。他要住在你中間，你就知道萬軍之耶和華差遣我到你那裏去了。","notes":["原文是我","原文是我"]},{"n":12,"t":"耶和華必收回猶大作他聖地的分，也必再揀選耶路撒冷。","notes":[]},{"n":13,"t":"凡有血氣的都當在耶和華面前靜默無聲；因為他興起，從聖所出來了。","notes":[]}]},"3":{"heading":"大祭司的異象","verses":[{"n":1,"t":"天使又指給我看：大祭司約書亞站在耶和華的使者面前；撒但也站在約書亞的右邊，與他作對。","notes":["原文是他"]},{"n":2,"t":"耶和華向撒但說：「撒但哪，耶和華責備你！就是揀選耶路撒冷的耶和華責備你！這不是從火中抽出來的一根柴嗎？」","notes":[]},{"n":3,"t":"約書亞穿著污穢的衣服站在使者面前。","notes":[]},{"n":4,"t":"使者吩咐站在面前的說：「你們要脫去他污穢的衣服」；又對約書亞說：「我使你脫離罪孽，要給你穿上華美的衣服。」","notes":[]},{"n":5,"t":"我說：「要將潔淨的冠冕戴在他頭上。」他們就把潔淨的冠冕戴在他頭上，給他穿上華美的衣服，耶和華的使者在旁邊站立。","notes":[]},{"n":6,"t":"耶和華的使者告誡約書亞說：","notes":[]},{"n":7,"t":"「萬軍之耶和華如此說：你若遵行我的道，謹守我的命令，你就可以管理我的家，看守我的院宇；我也要使你在這些站立的人中間來往。","notes":[]},{"n":8,"t":"大祭司約書亞啊，你和坐在你面前的同伴都當聽。（他們是作預兆的。）我必使我僕人大衛的苗裔發出。","notes":[]},{"n":9,"t":"看哪，我在約書亞面前所立的石頭，在一塊石頭上有七眼。萬軍之耶和華說：我要親自雕刻這石頭，並要在一日之間除掉這地的罪孽。","notes":[]},{"n":10,"t":"當那日，你們各人要請鄰舍坐在葡萄樹和無花果樹下。這是萬軍之耶和華說的。」","notes":[]}]},"4":{"heading":"金燈臺的異象","verses":[{"n":1,"t":"那與我說話的天使又來叫醒我，好像人睡覺被喚醒一樣。","notes":[]},{"n":2,"t":"他問我說：「你看見了甚麼？」我說：「我看見了一個純金的燈臺，頂上有燈盞，燈臺上有七盞燈，每盞有七個管子。","notes":[]},{"n":3,"t":"旁邊有兩棵橄欖樹，一棵在燈盞的右邊，一棵在燈盞的左邊。」","notes":[]},{"n":4,"t":"我問與我說話的天使說：「主啊，這是甚麼意思？」","notes":[]},{"n":5,"t":"與我說話的天使回答我說：「你不知道這是甚麼意思嗎？」我說：「主啊，我不知道。」","notes":[]},{"n":6,"t":"他對我說：「這是耶和華指示所羅巴伯的。萬軍之耶和華說：不是倚靠勢力，不是倚靠才能，乃是倚靠我的靈方能成事。","notes":[],"heads":["神給所羅巴伯的應許"]},{"n":7,"t":"大山哪，你算甚麼呢？在所羅巴伯面前，你必成為平地。他必搬出一塊石頭，安在殿頂上。人且大聲歡呼說：『願恩惠恩惠歸與這殿！』」","notes":["殿：或譯石"]},{"n":8,"t":"耶和華的話又臨到我說：","notes":[]},{"n":9,"t":"「所羅巴伯的手立了這殿的根基，他的手也必完成這工，你就知道萬軍之耶和華差遣我到你們這裏來了。","notes":[]},{"n":10,"t":"誰藐視這日的事為小呢？這七眼乃是耶和華的眼睛，遍察全地，見所羅巴伯手拿線鉈就歡喜。」","notes":[]},{"n":11,"t":"我又問天使說：「這燈臺左右的兩棵橄欖樹是甚麼意思？」","notes":[]},{"n":12,"t":"我二次問他說：「這兩根橄欖枝在兩個流出金色油的金嘴旁邊是甚麼意思？」","notes":[]},{"n":13,"t":"他對我說：「你不知道這是甚麼意思嗎？」我說：「主啊，我不知道。」","notes":[]},{"n":14,"t":"他說：「這是兩個受膏者站在普天下主的旁邊。」","notes":[]}]},"5":{"heading":"飛卷的異象","verses":[{"n":1,"t":"我又舉目觀看，見有一飛行的書卷。","notes":[]},{"n":2,"t":"他問我說：「你看見甚麼？」我回答說：「我看見一飛行的書卷，長二十肘，寬十肘。」","notes":[]},{"n":3,"t":"他對我說：「這是發出行在遍地上的咒詛。凡偷竊的必按卷上這面的話除滅；凡起假誓的必按卷上那面的話除滅。","notes":[]},{"n":4,"t":"萬軍之耶和華說：我必使這書卷出去，進入偷竊人的家和指我名起假誓人的家，必常在他家裏，連房屋帶木石都毀滅了。」","notes":[]},{"n":5,"t":"與我說話的天使出來，對我說：「你要舉目觀看，見所出來的是甚麼？」","notes":[],"heads":["量器中婦人的異象"]},{"n":6,"t":"我說：「這是甚麼呢？」他說：「這出來的是量器。」他又說：「這是惡人在遍地的形狀。」","notes":[]},{"n":7,"t":"（我見有一片圓鉛被舉起來。）這坐在量器中的是個婦人。","notes":[]},{"n":8,"t":"天使說：「這是罪惡。」他就把婦人扔在量器中，將那片圓鉛扔在量器的口上。","notes":[]},{"n":9,"t":"我又舉目觀看，見有兩個婦人出來，在她們翅膀中有風，飛得甚快，翅膀如同鸛鳥的翅膀。她們將量器抬起來，懸在天地中間。","notes":[]},{"n":10,"t":"我問與我說話的天使說：「她們要將量器抬到哪裏去呢？」","notes":[]},{"n":11,"t":"他對我說：「要往示拿地去，為它蓋造房屋；等房屋齊備，就把它安置在自己的地方。」","notes":[]}]},"6":{"heading":"馬車的異象","verses":[{"n":1,"t":"我又舉目觀看，見有四輛車從兩山中間出來；那山是銅山。","notes":[]},{"n":2,"t":"第一輛車套著紅馬，第二輛車套著黑馬。","notes":[]},{"n":3,"t":"第三輛車套著白馬，第四輛車套著有斑點的壯馬。","notes":[]},{"n":4,"t":"我就問與我說話的天使說：「主啊，這是甚麼意思？」","notes":[]},{"n":5,"t":"天使回答我說：「這是天的四風，是從普天下的主面前出來的。」","notes":[]},{"n":6,"t":"套著黑馬的車往北方去，白馬跟隨在後；有斑點的馬往南方去。","notes":[]},{"n":7,"t":"壯馬出來，要在遍地走來走去。天使說：「你們只管在遍地走來走去。」牠們就照樣行了。","notes":[]},{"n":8,"t":"他又呼叫我說：「看哪，往北方去的已在北方安慰我的心。」","notes":[]},{"n":9,"t":"耶和華的話臨到我說：","notes":[],"heads":["為約書亞加冕"]},{"n":10,"t":"「你要從被擄之人中取黑玳、多比雅、耶大雅的金銀。這三人是從巴比倫來到西番雅的兒子約西亞的家裏。當日你要進他的家，","notes":[]},{"n":11,"t":"取這金銀做冠冕，戴在約撒答的兒子大祭司約書亞的頭上，","notes":[]},{"n":12,"t":"對他說，萬軍之耶和華如此說：看哪，那名稱為大衛苗裔的，他要在本處長起來，並要建造耶和華的殿。","notes":[]},{"n":13,"t":"他要建造耶和華的殿，並擔負尊榮，坐在位上掌王權；又必在位上作祭司，使兩職之間籌定和平。","notes":[]},{"n":14,"t":"這冠冕要歸希連、多比雅、耶大雅，和西番雅的兒子賢，放在耶和華的殿裏為記念。」","notes":["就是黑玳","就是約西亞"]},{"n":15,"t":"遠方的人也要來建造耶和華的殿，你們就知道萬軍之耶和華差遣我到你們這裏來。你們若留意聽從耶和華－你們神的話，這事必然成就。","notes":[]}]},"7":{"heading":"譴責不誠懇的禁食","verses":[{"n":1,"t":"大流士王第四年九月，就是基斯流月初四日，耶和華的話臨到撒迦利亞。","notes":[]},{"n":2,"t":"那時伯特利人已經打發沙利色和利堅米勒，並跟從他們的人，去懇求耶和華的恩，","notes":[]},{"n":3,"t":"並問萬軍之耶和華殿中的祭司和先知說：「我歷年以來，在五月間哭泣齋戒，現在還當這樣行嗎？」","notes":[]},{"n":4,"t":"萬軍之耶和華的話就臨到我說：","notes":[]},{"n":5,"t":"「你要宣告國內的眾民和祭司，說：『你們這七十年，在五月、七月禁食悲哀，豈是絲毫向我禁食嗎？","notes":[]},{"n":6,"t":"你們吃喝，不是為自己吃，為自己喝嗎？","notes":[]},{"n":7,"t":"當耶路撒冷和四圍的城邑有居民，正興盛，南地高原有人居住的時候，耶和華藉從前的先知所宣告的話，你們不當聽嗎？』」","notes":[]},{"n":8,"t":"耶和華的話又臨到撒迦利亞說：","notes":[],"heads":["被擄的原因是悖逆"]},{"n":9,"t":"「萬軍之耶和華曾對你們的列祖如此說：『要按至理判斷，各人以慈愛憐憫弟兄。","notes":[]},{"n":10,"t":"不可欺壓寡婦、孤兒、寄居的，和貧窮人。誰都不可心裏謀害弟兄。』」","notes":[]},{"n":11,"t":"他們卻不肯聽從，扭轉肩頭，塞耳不聽，","notes":[]},{"n":12,"t":"使心硬如金鋼石，不聽律法和萬軍之耶和華用靈藉從前的先知所說的話。故此，萬軍之耶和華大發烈怒。","notes":[]},{"n":13,"t":"萬軍之耶和華說：「我曾呼喚他們，他們不聽；將來他們呼求我，我也不聽！","notes":[]},{"n":14,"t":"我必以旋風吹散他們到素不認識的萬國中。這樣，他們的地就荒涼，甚至無人來往經過，因為他們使美好之地荒涼了。」","notes":[]}]},"8":{"heading":"耶和華應許復興耶路撒冷","verses":[{"n":1,"t":"萬軍之耶和華的話臨到我說：","notes":[]},{"n":2,"t":"「萬軍之耶和華如此說：我為錫安心裏極其火熱，我為她火熱，向她的仇敵發烈怒。","notes":[]},{"n":3,"t":"耶和華如此說：我現在回到錫安，要住在耶路撒冷中。耶路撒冷必稱為誠實的城，萬軍之耶和華的山必稱為聖山。","notes":[]},{"n":4,"t":"萬軍之耶和華如此說：將來必有年老的男女坐在耶路撒冷街上，因為年紀老邁就手拿柺杖。","notes":[]},{"n":5,"t":"城中街上必滿有男孩女孩玩耍。","notes":[]},{"n":6,"t":"萬軍之耶和華如此說：到那日，這事在餘剩的民眼中看為希奇，在我眼中也看為希奇嗎？這是萬軍之耶和華說的。","notes":[]},{"n":7,"t":"萬軍之耶和華如此說：我要從東方從西方救回我的民。","notes":[]},{"n":8,"t":"我要領他們來，使他們住在耶路撒冷中。他們要作我的子民，我要作他們的神，都憑誠實和公義。」","notes":[]},{"n":9,"t":"萬軍之耶和華如此說：「當建造萬軍之耶和華的殿，立根基之日的先知所說的話，現在你們聽見，應當手裏強壯。","notes":[]},{"n":10,"t":"那日以先，人得不著雇價，牲畜也是如此；且因敵人的緣故，出入之人不得平安，乃因我使眾人互相攻擊。","notes":[]},{"n":11,"t":"但如今，我待這餘剩的民必不像從前。這是萬軍之耶和華說的。","notes":[]},{"n":12,"t":"因為他們必平安撒種，葡萄樹必結果子，地土必有出產，天也必降甘露。我要使這餘剩的民享受這一切的福。","notes":[]},{"n":13,"t":"猶大家和以色列家啊，你們從前在列國中怎樣成為可咒詛的；照樣，我要拯救你們，使人稱你們為有福的。你們不要懼怕，手要強壯。」","notes":["或譯：使你們叫人得福"]},{"n":14,"t":"萬軍之耶和華如此說：「你們列祖惹我發怒的時候，我怎樣定意降禍，並不後悔。","notes":[]},{"n":15,"t":"現在我照樣定意施恩與耶路撒冷和猶大家，你們不要懼怕。","notes":[]},{"n":16,"t":"你們所當行的是這樣：各人與鄰舍說話誠實，在城門口按至理判斷，使人和睦。","notes":[]},{"n":17,"t":"誰都不可心裏謀害鄰舍，也不可喜愛起假誓，因為這些事都為我所恨惡。這是耶和華說的。」","notes":[]},{"n":18,"t":"萬軍之耶和華的話臨到我說：","notes":[]},{"n":19,"t":"「萬軍之耶和華如此說：四月、五月禁食的日子，七月、十月禁食的日子，必變為猶大家歡喜快樂的日子和歡樂的節期；所以你們要喜愛誠實與和平。」","notes":[]},{"n":20,"t":"萬軍之耶和華如此說：「將來必有列國的人和多城的居民來到。","notes":[]},{"n":21,"t":"這城的居民必到那城，說：『我們要快去懇求耶和華的恩，尋求萬軍之耶和華；我也要去。』","notes":[]},{"n":22,"t":"必有列邦的人和強國的民來到耶路撒冷尋求萬軍之耶和華，懇求耶和華的恩。","notes":[]},{"n":23,"t":"萬軍之耶和華如此說：在那些日子，必有十個人從列國諸族中出來，拉住一個猶大人的衣襟，說：『我們要與你們同去，因為我們聽見神與你們同在了。』」","notes":["原文是方言"]}]},"9":{"heading":"審判鄰國","verses":[{"n":1,"t":"耶和華的默示應驗在哈得拉地大馬士革－世人和以色列各支派的眼目都仰望耶和華－","notes":[]},{"n":2,"t":"和靠近的哈馬，並泰爾、西頓；因為這二城的人大有智慧。","notes":[]},{"n":3,"t":"泰爾為自己修築保障，積蓄銀子如塵沙，堆起精金如街上的泥土。","notes":[]},{"n":4,"t":"主必趕出她，打敗她海上的權利；她必被火燒滅。","notes":[]},{"n":5,"t":"亞實基倫看見必懼怕；迦薩看見甚痛苦；以革倫因失了盼望蒙羞。迦薩必不再有君王；亞實基倫也不再有居民。","notes":[]},{"n":6,"t":"私生子必住在亞實突；我必除滅非利士人的驕傲。","notes":["或譯：外族人"]},{"n":7,"t":"我必除去他口中帶血之肉和牙齒內可憎之物。他必作為餘剩的人歸與我們的神，必在猶大像族長；以革倫人必如耶布斯人。","notes":[]},{"n":8,"t":"我必在我家的四圍安營，使敵軍不得任意往來，暴虐的人也不再經過，因為我親眼看顧我的家。","notes":[]},{"n":9,"t":"錫安的民哪，應當大大喜樂；耶路撒冷的民哪，應當歡呼。看哪，你的王來到你這裏！他是公義的，並且施行拯救，謙謙和和地騎著驢，就是騎著驢的駒子。","notes":[],"heads":["未來的君王"]},{"n":10,"t":"我必除滅以法蓮的戰車和耶路撒冷的戰馬；爭戰的弓也必除滅。他必向列國講和平；他的權柄必從這海管到那海，從大河管到地極。","notes":[]},{"n":11,"t":"錫安哪，我因與你立約的血，將你中間被擄而囚的人從無水的坑中釋放出來。","notes":[],"heads":["神子民的復興"]},{"n":12,"t":"你們被囚而有指望的人都要轉回保障。我今日說明，我必加倍賜福給你們。","notes":[]},{"n":13,"t":"我拿猶大作上弦的弓；我拿以法蓮為張弓的箭。錫安哪，我要激發你的眾子，攻擊希臘的眾子，使你如勇士的刀。","notes":["原文是雅完"]},{"n":14,"t":"耶和華必顯現在他們以上；他的箭必射出像閃電。主耶和華必吹角，乘南方的旋風而行。","notes":[]},{"n":15,"t":"萬軍之耶和華必保護他們；他們必吞滅仇敵，踐踏彈石。他們必喝血吶喊，猶如飲酒；他們必像盛滿血的碗，又像壇的四角滿了血。","notes":[]},{"n":16,"t":"當那日，耶和華－他們的神必看他的民如群羊，拯救他們；因為他們必像冠冕上的寶石，高舉在他的地以上。","notes":["或譯：在他的地上發光輝"]},{"n":17,"t":"他的恩慈何等大！他的榮美何其盛！五穀健壯少男；新酒培養處女。","notes":[]}]},"10":{"heading":"耶和華應許解救","verses":[{"n":1,"t":"當春雨的時候，你們要向發閃電的耶和華求雨。他必為眾人降下甘霖，使田園生長菜蔬。","notes":[]},{"n":2,"t":"因為，家神所言的是虛空；卜士所見的是虛假；做夢者所說的是假夢。他們白白地安慰人，所以眾人如羊流離，因無牧人就受苦。","notes":[]},{"n":3,"t":"我的怒氣向牧人發作；我必懲罰公山羊；因我－萬軍之耶和華眷顧自己的羊群，就是猶大家，必使他們如駿馬在陣上。","notes":[]},{"n":4,"t":"房角石、釘子、爭戰的弓，和一切掌權的都從他而出。","notes":[]},{"n":5,"t":"他們必如勇士在陣上將仇敵踐踏在街上的泥土中。他們必爭戰，因為耶和華與他們同在；騎馬的也必羞愧。","notes":[]},{"n":6,"t":"我要堅固猶大家，拯救約瑟家，要領他們歸回。我要憐恤他們；他們必像未曾棄絕的一樣，都因我是耶和華－他們的神，我必應允他們的禱告。","notes":[]},{"n":7,"t":"以法蓮人必如勇士；他們心中暢快如同喝酒；他們的兒女必看見而快活；他們的心必因耶和華喜樂。","notes":[]},{"n":8,"t":"我要發嘶聲，聚集他們，因我已經救贖他們。他們的人數必加增，如從前加增一樣。","notes":[]},{"n":9,"t":"我雖然播散他們在列國中，他們必在遠方記念我。他們與兒女都必存活，且得歸回。","notes":["或譯：必"]},{"n":10,"t":"我必再領他們出埃及地，招聚他們出亞述，領他們到基列和黎巴嫩；這地尚且不夠他們居住。","notes":[]},{"n":11,"t":"耶和華必經過苦海，擊打海浪，使尼羅河的深處都枯乾。亞述的驕傲必致卑微；埃及的權柄必然滅沒。","notes":[]},{"n":12,"t":"我必使他們倚靠我，得以堅固；一舉一動必奉我的名。這是耶和華說的。","notes":[]}]},"11":{"heading":"暴君的沒落","verses":[{"n":1,"t":"黎巴嫩哪，開開你的門，任火燒滅你的香柏樹。","notes":[]},{"n":2,"t":"松樹啊，應當哀號；因為香柏樹傾倒，佳美的樹毀壞。巴珊的橡樹啊，應當哀號，因為茂盛的樹林已經倒了。","notes":[]},{"n":3,"t":"聽啊，有牧人哀號的聲音，因他們榮華的草場毀壞了。有少壯獅子咆哮的聲音，因約旦河旁的叢林荒廢了。","notes":[]},{"n":4,"t":"耶和華－我的神如此說：「你－撒迦利亞要牧養這將宰的群羊。","notes":[],"heads":["兩個牧人"]},{"n":5,"t":"買他們的宰了他們，以自己為無罪；賣他們的說：『耶和華是應當稱頌的，因我成為富足。』牧養他們的並不憐恤他們。","notes":[]},{"n":6,"t":"耶和華說：『我不再憐恤這地的居民，必將這民交給各人的鄰舍和他們王的手中。他們必毀滅這地，我也不救這民脫離他們的手。』」","notes":[]},{"n":7,"t":"於是，我牧養這將宰的群羊，就是群中最困苦的羊。我拿著兩根杖，一根我稱為「榮美」，一根我稱為「聯索」。這樣，我牧養了群羊。","notes":[]},{"n":8,"t":"一月之內，我除滅三個牧人，因為我的心厭煩他們；他們的心也憎嫌我。","notes":[]},{"n":9,"t":"我就說：「我不牧養你們。要死的，由他死；要喪亡的，由他喪亡；餘剩的，由他們彼此相食。」","notes":[]},{"n":10,"t":"我折斷那稱為「榮美」的杖，表明我廢棄與萬民所立的約。","notes":[]},{"n":11,"t":"當日就廢棄了。這樣，那些仰望我的困苦羊就知道所說的是耶和華的話。","notes":[]},{"n":12,"t":"我對他們說：「你們若以為美，就給我工價。不然，就罷了！」於是他們給了三十塊錢作為我的工價。","notes":[]},{"n":13,"t":"耶和華吩咐我說：「要把眾人所估定美好的價值丟給窯戶。」我便將這三十塊錢，在耶和華的殿中丟給窯戶了。","notes":[]},{"n":14,"t":"我又折斷稱為「聯索」的那根杖，表明我廢棄猶大與以色列弟兄的情誼。","notes":[]},{"n":15,"t":"耶和華又吩咐我說：「你再取愚昧牧人所用的器具，","notes":[]},{"n":16,"t":"因我要在這地興起一個牧人。他不看顧喪亡的，不尋找分散的，不醫治受傷的，也不牧養強壯的；卻要吃肥羊的肉，撕裂牠的蹄子。","notes":[]},{"n":17,"t":"無用的牧人丟棄羊群有禍了！刀必臨到他的膀臂和右眼上。他的膀臂必全然枯乾；他的右眼也必昏暗失明。」","notes":[]}]},"12":{"heading":"耶路撒冷將蒙拯救","verses":[{"n":1,"t":"耶和華論以色列的默示。鋪張諸天、建立地基、造人裏面之靈的耶和華說：","notes":[]},{"n":2,"t":"「我必使耶路撒冷被圍困的時候，向四圍列國的民成為令人昏醉的杯；這默示也論到猶大。","notes":["或譯：猶大也是如此"]},{"n":3,"t":"那日，我必使耶路撒冷向聚集攻擊他的萬民當作一塊重石頭；凡舉起的必受重傷。","notes":[]},{"n":4,"t":"耶和華說：到那日，我必使一切馬匹驚惶，使騎馬的顛狂。我必看顧猶大家，使列國的一切馬匹瞎眼。","notes":[]},{"n":5,"t":"猶大的族長必心裏說：『耶路撒冷的居民倚靠萬軍之耶和華－他們的神，就作我們的能力。』","notes":[]},{"n":6,"t":"「那日，我必使猶大的族長如火盆在木柴中，又如火把在禾捆裏；他們必左右燒滅四圍列國的民。耶路撒冷人必仍住本處，就是耶路撒冷。","notes":[]},{"n":7,"t":"「耶和華必先拯救猶大的帳棚，免得大衛家的榮耀和耶路撒冷居民的榮耀勝過猶大。","notes":[]},{"n":8,"t":"那日，耶和華必保護耶路撒冷的居民。他們中間軟弱的必如大衛；大衛的家必如神，如行在他們前面之耶和華的使者。","notes":[]},{"n":9,"t":"那日，我必定意滅絕來攻擊耶路撒冷各國的民。","notes":[]},{"n":10,"t":"「我必將那施恩叫人懇求的靈，澆灌大衛家和耶路撒冷的居民。他們必仰望我，就是他們所扎的；必為我悲哀，如喪獨生子，又為我愁苦，如喪長子。","notes":["或譯：他；本節同"]},{"n":11,"t":"那日，耶路撒冷必有大大的悲哀，如米吉多平原之哈達臨門的悲哀。","notes":[]},{"n":12,"t":"境內一家一家地都必悲哀。大衛家，男的獨在一處，女的獨在一處。拿單家，男的獨在一處，女的獨在一處。","notes":[]},{"n":13,"t":"利未家，男的獨在一處，女的獨在一處。示每家，男的獨在一處，女的獨在一處。","notes":[]},{"n":14,"t":"其餘的各家，男的獨在一處，女的獨在一處。","notes":[]}]},"13":{"heading":"牧人被殺","verses":[{"n":1,"t":"「那日，必給大衛家和耶路撒冷的居民開一個泉源，洗除罪惡與污穢。」","notes":[]},{"n":2,"t":"萬軍之耶和華說：「那日，我必從地上除滅偶像的名，不再被人記念；也必使這地不再有假先知與污穢的靈。","notes":[]},{"n":3,"t":"若再有人說預言，生他的父母必對他說：『你不得存活，因為你託耶和華的名說假預言。』生他的父母在他說預言的時候，要將他刺透。","notes":[]},{"n":4,"t":"那日，凡作先知說預言的必因他所論的異象羞愧，不再穿毛衣哄騙人。","notes":[]},{"n":5,"t":"他必說：『我不是先知，我是耕地的；我從幼年作人的奴僕。』","notes":[]},{"n":6,"t":"必有人問他說：『你兩臂中間是甚麼傷呢？』他必回答說：『這是我在親友家中所受的傷。』」","notes":[]},{"n":7,"t":"萬軍之耶和華說：刀劍哪，應當興起，攻擊我的牧人和我的同伴。擊打牧人，羊就分散；我必反手加在微小者的身上。","notes":[]},{"n":8,"t":"耶和華說：這全地的人，三分之二必剪除而死，三分之一仍必存留。","notes":[]},{"n":9,"t":"我要使這三分之一經火，熬煉他們，如熬煉銀子；試煉他們，如試煉金子。他們必求告我的名，我必應允他們。我要說：這是我的子民。他們也要說：耶和華是我們的神。","notes":[]}]},"14":{"heading":"耶路撒冷和列國","verses":[{"n":1,"t":"耶和華的日子臨近，你的財物必被搶掠，在你中間分散。","notes":[]},{"n":2,"t":"因為我必聚集萬國與耶路撒冷爭戰，城必被攻取，房屋被搶奪，婦女被玷污，城中的民一半被擄去；剩下的民仍在城中，不致剪除。","notes":[]},{"n":3,"t":"那時，耶和華必出去與那些國爭戰，好像從前爭戰一樣。","notes":[]},{"n":4,"t":"那日，他的腳必站在耶路撒冷前面朝東的橄欖山上。這山必從中間分裂，自東至西成為極大的谷。山的一半向北挪移，一半向南挪移。","notes":[]},{"n":5,"t":"你們要從我山的谷中逃跑，因為山谷必延到亞薩。你們逃跑，必如猶大王烏西雅年間的人逃避大地震一樣。耶和華－我的神必降臨，有一切聖者同來。","notes":[]},{"n":6,"t":"那日，必沒有光，三光必退縮。","notes":[]},{"n":7,"t":"那日，必是耶和華所知道的，不是白晝，也不是黑夜，到了晚上才有光明。","notes":[]},{"n":8,"t":"那日，必有活水從耶路撒冷出來，一半往東海流，一半往西海流；冬夏都是如此。","notes":[]},{"n":9,"t":"耶和華必作全地的王。那日耶和華必為獨一無二的，他的名也是獨一無二的。","notes":[]},{"n":10,"t":"全地，從迦巴直到耶路撒冷南方的臨門，要變為亞拉巴。耶路撒冷必仍居高位，就是從便雅憫門到第一門之處，又到角門，並從哈楠業樓，直到王的酒醡。","notes":[]},{"n":11,"t":"人必住在其中，不再有咒詛。耶路撒冷人必安然居住。","notes":[]},{"n":12,"t":"耶和華用災殃攻擊那與耶路撒冷爭戰的列國人，必是這樣：他們兩腳站立的時候，肉必消沒，眼在眶中乾癟，舌在口中潰爛。","notes":[]},{"n":13,"t":"那日，耶和華必使他們大大擾亂。他們各人彼此揪住，舉手攻擊。","notes":[]},{"n":14,"t":"猶大也必在耶路撒冷爭戰。那時四圍各國的財物，就是許多金銀衣服，必被收聚。","notes":[]},{"n":15,"t":"那臨到馬匹、騾子、駱駝、驢，和營中一切牲畜的災殃是與那災殃一般。","notes":[]},{"n":16,"t":"所有來攻擊耶路撒冷列國中剩下的人，必年年上來敬拜大君王－萬軍之耶和華，並守住棚節。","notes":[]},{"n":17,"t":"地上萬族中，凡不上耶路撒冷敬拜大君王－萬軍之耶和華的，必無雨降在他們的地上。","notes":[]},{"n":18,"t":"埃及族若不上來，雨也不降在他們的地上；凡不上來守住棚節的列國人，耶和華也必用這災攻擊他們。","notes":[]},{"n":19,"t":"這就是埃及的刑罰和那不上來守住棚節之列國的刑罰。","notes":[]},{"n":20,"t":"當那日，馬的鈴鐺上必有「歸耶和華為聖」的這句話。耶和華殿內的鍋必如祭壇前的碗一樣。","notes":[]},{"n":21,"t":"凡耶路撒冷和猶大的鍋都必歸萬軍之耶和華為聖。凡獻祭的都必來取這鍋，煮肉在其中。當那日，在萬軍之耶和華的殿中必不再有迦南人。","notes":[]}]}},"MAL":{"1":{"heading":"耶和華愛以色列","verses":[{"n":1,"t":"耶和華藉瑪拉基傳給以色列的默示。","notes":[]},{"n":2,"t":"耶和華說：「我曾愛你們。」你們卻說：「你在何事上愛我們呢？」耶和華說：「以掃不是雅各的哥哥嗎？我卻愛雅各，","notes":[]},{"n":3,"t":"惡以掃，使他的山嶺荒涼，把他的地業交給曠野的野狗。」","notes":[]},{"n":4,"t":"以東人說：「我們現在雖被毀壞，卻要重建荒廢之處。」萬軍之耶和華如此說：「任他們建造，我必拆毀；人必稱他們的地為『罪惡之境』；稱他們的民為『耶和華永遠惱怒之民』。」","notes":[]},{"n":5,"t":"你們必親眼看見，也必說：「願耶和華在以色列境界之外被尊為大！」","notes":[]},{"n":6,"t":"「藐視我名的祭司啊，萬軍之耶和華對你們說：兒子尊敬父親，僕人敬畏主人；我既為父親，尊敬我的在哪裏呢？我既為主人，敬畏我的在哪裏呢？你們卻說：『我們在何事上藐視你的名呢？』","notes":[],"heads":["斥責祭司"]},{"n":7,"t":"你們將污穢的食物獻在我的壇上，且說：『我們在何事上污穢你呢？』因你們說，耶和華的桌子是可藐視的。","notes":[]},{"n":8,"t":"你們將瞎眼的獻為祭物，這不為惡嗎？將瘸腿的、有病的獻上，這不為惡嗎？你獻給你的省長，他豈喜悅你，豈能看你的情面嗎？這是萬軍之耶和華說的。","notes":[]},{"n":9,"t":"「現在我勸你們懇求神，他好施恩與我們。這妄獻的事，既由你們經手，他豈能看你們的情面嗎？這是萬軍之耶和華說的。","notes":[]},{"n":10,"t":"甚願你們中間有一人關上殿門，免得你們徒然在我壇上燒火。萬軍之耶和華說：我不喜悅你們，也不從你們手中收納供物。","notes":[]},{"n":11,"t":"萬軍之耶和華說：從日出之地到日落之處，我的名在外邦中必尊為大。在各處，人必奉我的名燒香，獻潔淨的供物，因為我的名在外邦中必尊為大。","notes":[]},{"n":12,"t":"你們卻褻瀆我的名，說：『耶和華的桌子是污穢的，其上的食物是可藐視的。』","notes":[]},{"n":13,"t":"你們又說：『這些事何等煩瑣！』並嗤之以鼻。這是萬軍之耶和華說的。你們把搶奪的、瘸腿的、有病的拿來獻上為祭。我豈能從你們手中收納呢？這是耶和華說的。","notes":[]},{"n":14,"t":"行詭詐的在群中有公羊，他許願卻用有殘疾的獻給主，這人是可咒詛的。因為我是大君王，我的名在外邦中是可畏的。這是萬軍之耶和華說的。","notes":[]}]},"2":{"heading":"百姓對神不忠","verses":[{"n":1,"t":"「眾祭司啊，這誡命是傳給你們的。","notes":[]},{"n":2,"t":"萬軍之耶和華說：你們若不聽從，也不放在心上，將榮耀歸與我的名，我就使咒詛臨到你們，使你們的福分變為咒詛；因你們不把誡命放在心上，我已經咒詛你們了。","notes":[]},{"n":3,"t":"我必斥責你們的種子，又把你們犧牲的糞抹在你們的臉上；你們要與糞一同除掉。","notes":[]},{"n":4,"t":"你們就知道我傳這誡命給你們，使我與利未所立的約可以常存。這是萬軍之耶和華說的。","notes":["或譯：_利未_人"]},{"n":5,"t":"我曾與他立生命和平安的約。我將這兩樣賜給他，使他存敬畏的心，他就敬畏我，懼怕我的名。","notes":[]},{"n":6,"t":"真實的律法在他口中，他嘴裏沒有不義的話。他以平安和正直與我同行，使多人回頭離開罪孽。","notes":[]},{"n":7,"t":"祭司的嘴裏當存知識，人也當由他口中尋求律法，因為他是萬軍之耶和華的使者。","notes":[]},{"n":8,"t":"你們卻偏離正道，使許多人在律法上跌倒。你們廢棄我與利未所立的約。這是萬軍之耶和華說的。","notes":[]},{"n":9,"t":"所以我使你們被眾人藐視，看為下賤；因你們不守我的道，竟在律法上瞻徇情面。」","notes":[]},{"n":10,"t":"我們豈不都是一位父嗎？豈不是一位神所造的嗎？我們各人怎麼以詭詐待弟兄，背棄了神與我們列祖所立的約呢？","notes":[]},{"n":11,"t":"猶大人行事詭詐，並且在以色列和耶路撒冷中行一件可憎的事；因為猶大人褻瀆耶和華所喜愛的聖潔，娶事奉外邦神的女子為妻。","notes":["或譯：聖地"]},{"n":12,"t":"凡行這事的，無論何人，就是獻供物給萬軍之耶和華，耶和華也必從雅各的帳棚中剪除他。","notes":["何人：原文是叫醒的，答應的"]},{"n":13,"t":"你們又行了一件這樣的事，使前妻歎息哭泣的眼淚遮蓋耶和華的壇，以致耶和華不再看顧那供物，也不樂意從你們手中收納。","notes":[]},{"n":14,"t":"你們還說：「這是為甚麼呢？」因耶和華在你和你幼年所娶的妻中間作見證。她雖是你的配偶，又是你盟約的妻，你卻以詭詐待她。","notes":[]},{"n":15,"t":"雖然神有靈的餘力能造多人，他不是單造一人嗎？為何只造一人呢？乃是他願人得虔誠的後裔。所以當謹守你們的心，誰也不可以詭詐待幼年所娶的妻。","notes":[]},{"n":16,"t":"耶和華－以色列的神說：「休妻的事和以強暴待妻的人都是我所恨惡的！所以當謹守你們的心，不可行詭詐。」這是萬軍之耶和華說的。","notes":[]},{"n":17,"t":"你們用言語煩瑣耶和華，你們還說：「我們在何事上煩瑣他呢？」因為你們說：「凡行惡的，耶和華眼看為善，並且他喜悅他們」；或說：「公義的神在哪裏呢？」","notes":[],"heads":["審判之日已近"]}]},"3":{"heading":"十分之一捐獻","verses":[{"n":1,"t":"萬軍之耶和華說：「我要差遣我的使者在我前面預備道路。你們所尋求的主必忽然進入他的殿；立約的使者，就是你們所仰慕的，快要來到。」","notes":[]},{"n":2,"t":"他來的日子，誰能當得起呢？他顯現的時候，誰能立得住呢？因為他如煉金之人的火，如漂布之人的鹼。","notes":[]},{"n":3,"t":"他必坐下如煉淨銀子的，必潔淨利未人，熬煉他們像金銀一樣；他們就憑公義獻供物給耶和華。","notes":[]},{"n":4,"t":"那時，猶大和耶路撒冷所獻的供物必蒙耶和華悅納，彷彿古時之日、上古之年。","notes":[]},{"n":5,"t":"萬軍之耶和華說：「我必臨近你們，施行審判。我必速速作見證，警戒行邪術的、犯姦淫的、起假誓的、虧負人之工價的、欺壓寡婦孤兒的、屈枉寄居的，和不敬畏我的。」","notes":[]},{"n":6,"t":"「因我－耶和華是不改變的，所以你們雅各之子沒有滅亡。","notes":[]},{"n":7,"t":"萬軍之耶和華說：從你們列祖的日子以來，你們常常偏離我的典章而不遵守。現在你們要轉向我，我就轉向你們。你們卻問說：『我們如何才是轉向呢？』","notes":[]},{"n":8,"t":"人豈可奪取神之物呢？你們竟奪取我的供物。你們卻說：『我們在何事上奪取你的供物呢？』就是你們在當納的十分之一和當獻的供物上。","notes":[]},{"n":9,"t":"因你們通國的人都奪取我的供物，咒詛就臨到你們身上。","notes":[]},{"n":10,"t":"萬軍之耶和華說：你們要將當納的十分之一全然送入倉庫，使我家有糧，以此試試我，是否為你們敞開天上的窗戶，傾福與你們，甚至無處可容。","notes":[]},{"n":11,"t":"萬軍之耶和華說：我必為你們斥責蝗蟲，不容牠毀壞你們的土產。你們田間的葡萄樹在未熟之先也不掉果子。","notes":["原文是吞噬者"]},{"n":12,"t":"萬軍之耶和華說：萬國必稱你們為有福的，因你們的地必成為喜樂之地。」","notes":[]},{"n":13,"t":"耶和華說：「你們用話頂撞我，你們還說：『我們用甚麼話頂撞了你呢？』","notes":[],"heads":["神應許施憐憫"]},{"n":14,"t":"你們說：『事奉神是徒然的，遵守神所吩咐的，在萬軍之耶和華面前苦苦齋戒，有甚麼益處呢？","notes":[]},{"n":15,"t":"如今我們稱狂傲的人為有福，並且行惡的人得建立；他們雖然試探神，卻得脫離災難。』」","notes":[]},{"n":16,"t":"那時，敬畏耶和華的彼此談論，耶和華側耳而聽，且有紀念冊在他面前，記錄那敬畏耶和華、思念他名的人。","notes":[]},{"n":17,"t":"萬軍之耶和華說：「在我所定的日子，他們必屬我，特特歸我。我必憐恤他們，如同人憐恤服事自己的兒子。","notes":[]},{"n":18,"t":"那時你們必歸回，將善人和惡人，事奉神的和不事奉神的，分別出來。」","notes":[]}]},"4":{"heading":"耶和華的日子臨近","verses":[{"n":1,"t":"萬軍之耶和華說：「那日臨近，勢如燒著的火爐，凡狂傲的和行惡的必如碎稭，在那日必被燒盡，根本枝條一無存留。","notes":[]},{"n":2,"t":"但向你們敬畏我名的人必有公義的日頭出現，其光線有醫治之能。你們必出來跳躍如圈裏的肥犢。","notes":["原文是翅膀"]},{"n":3,"t":"你們必踐踏惡人；在我所定的日子，他們必如灰塵在你們腳掌之下。這是萬軍之耶和華說的。","notes":[]},{"n":4,"t":"「你們當記念我僕人摩西的律法，就是我在何烈山為以色列眾人所吩咐他的律例典章。","notes":[]},{"n":5,"t":"「看哪，耶和華大而可畏之日未到以前，我必差遣先知以利亞到你們那裏去。","notes":[]},{"n":6,"t":"他必使父親的心轉向兒女，兒女的心轉向父親，免得我來咒詛遍地。」","notes":[]}]}},"MAT":{"1":{"heading":"耶穌基督的家譜","verses":[{"n":1,"t":"亞伯拉罕的後裔，大衛的子孫，耶穌基督的家譜：","notes":["後裔，子孫：原文是兒子；下同"]},{"n":2,"t":"亞伯拉罕生以撒；以撒生雅各；雅各生猶大和他的弟兄；","notes":[]},{"n":3,"t":"猶大從她瑪氏生法勒斯和謝拉；法勒斯生希斯崙；希斯崙生亞蘭；","notes":[]},{"n":4,"t":"亞蘭生亞米拿達；亞米拿達生拿順；拿順生撒門；","notes":[]},{"n":5,"t":"撒門從喇合氏生波阿斯；波阿斯從路得氏生俄備得；俄備得生耶西；","notes":[]},{"n":6,"t":"耶西生大衛王。大衛從烏利亞的妻子生所羅門；","notes":[]},{"n":7,"t":"所羅門生羅波安；羅波安生亞比雅；亞比雅生亞撒；","notes":[]},{"n":8,"t":"亞撒生約沙法；約沙法生約蘭；約蘭生烏西雅；","notes":[]},{"n":9,"t":"烏西雅生約坦；約坦生亞哈斯；亞哈斯生希西家；","notes":[]},{"n":10,"t":"希西家生瑪拿西；瑪拿西生亞們；亞們生約西亞；","notes":[]},{"n":11,"t":"百姓被遷到巴比倫的時候，約西亞生耶哥尼雅和他的弟兄。","notes":[]},{"n":12,"t":"遷到巴比倫之後，耶哥尼雅生撒拉鐵；撒拉鐵生所羅巴伯；","notes":[]},{"n":13,"t":"所羅巴伯生亞比玉；亞比玉生以利亞敬；以利亞敬生亞所；","notes":[]},{"n":14,"t":"亞所生撒督；撒督生亞金；亞金生以律；","notes":[]},{"n":15,"t":"以律生以利亞撒；以利亞撒生馬但；馬但生雅各；","notes":[]},{"n":16,"t":"雅各生約瑟，就是馬利亞的丈夫。那稱為基督的耶穌是從馬利亞生的。","notes":[]},{"n":17,"t":"這樣，從亞伯拉罕到大衛共有十四代；從大衛到遷至巴比倫的時候也有十四代；從遷至巴比倫的時候到基督又有十四代。","notes":[]},{"n":18,"t":"耶穌基督降生的事記在下面：他母親馬利亞已經許配了約瑟，還沒有迎娶，馬利亞就從聖靈懷了孕。","notes":[],"heads":["耶穌基督降生"]},{"n":19,"t":"她丈夫約瑟是個義人，不願意明明地羞辱她，想要暗暗地把她休了。","notes":[]},{"n":20,"t":"正思念這事的時候，有主的使者向他夢中顯現，說：「大衛的子孫約瑟，不要怕！只管娶過你的妻子馬利亞來，因她所懷的孕是從聖靈來的。","notes":[]},{"n":21,"t":"她將要生一個兒子，你要給他起名叫耶穌，因他要將自己的百姓從罪惡裏救出來。」","notes":[]},{"n":22,"t":"這一切的事成就是要應驗主藉先知所說的話，","notes":[]},{"n":23,"t":"說：必有童女懷孕生子；人要稱他的名為以馬內利。（以馬內利翻出來就是「神與我們同在」。）","notes":[]},{"n":24,"t":"約瑟醒了，起來，就遵著主使者的吩咐把妻子娶過來；","notes":[]},{"n":25,"t":"只是沒有和她同房，等她生了兒子，就給他起名叫耶穌。","notes":["有古卷：等她生了頭胎的兒子"]}]},"2":{"heading":"博士朝拜","verses":[{"n":1,"t":"當希律王的時候，耶穌生在猶太的伯利恆。有幾個博士從東方來到耶路撒冷，說：","notes":[]},{"n":2,"t":"「那生下來作猶太人之王的在哪裏？我們在東方看見他的星，特來拜他。」","notes":[]},{"n":3,"t":"希律王聽見了，就心裏不安；耶路撒冷合城的人也都不安。","notes":[]},{"n":4,"t":"他就召齊了祭司長和民間的文士，問他們說：「基督當生在何處？」","notes":[]},{"n":5,"t":"他們回答說：「在猶太的伯利恆。因為有先知記著，說：","notes":[]},{"n":6,"t":"猶大地的伯利恆啊，你在猶大諸城中並不是最小的；因為將來有一位君王要從你那裏出來，牧養我以色列民。」","notes":[]},{"n":7,"t":"當下，希律暗暗地召了博士來，細問那星是甚麼時候出現的，","notes":[]},{"n":8,"t":"就差他們往伯利恆去，說：「你們去仔細尋訪那小孩子，尋到了就來報信，我也好去拜他。」","notes":[]},{"n":9,"t":"他們聽見王的話就去了。在東方所看見的那星忽然在他們前頭行，直行到小孩子的地方，就在上頭停住了。","notes":[]},{"n":10,"t":"他們看見那星，就大大地歡喜；","notes":[]},{"n":11,"t":"進了房子，看見小孩子和他母親馬利亞，就俯伏拜那小孩子，揭開寶盒，拿黃金、乳香、沒藥為禮物獻給他。","notes":[]},{"n":12,"t":"博士因為在夢中被主指示不要回去見希律，就從別的路回本地去了。","notes":[]},{"n":13,"t":"他們去後，有主的使者向約瑟夢中顯現，說：「起來！帶著小孩子同他母親逃往埃及，住在那裏，等我吩咐你；因為希律必尋找小孩子，要除滅他。」","notes":[],"heads":["逃往埃及"]},{"n":14,"t":"約瑟就起來，夜間帶著小孩子和他母親往埃及去，","notes":[]},{"n":15,"t":"住在那裏，直到希律死了。這是要應驗主藉先知所說的話，說：「我從埃及召出我的兒子來。」","notes":[]},{"n":16,"t":"希律見自己被博士愚弄，就大大發怒，差人將伯利恆城裏並四境所有的男孩，照著他向博士仔細查問的時候，凡兩歲以裏的，都殺盡了。","notes":[],"heads":["屠殺男孩"]},{"n":17,"t":"這就應了先知耶利米的話，說：","notes":[]},{"n":18,"t":"在拉瑪聽見號咷大哭的聲音，是拉結哭她兒女，不肯受安慰，因為他們都不在了。","notes":[]},{"n":19,"t":"希律死了以後，有主的使者在埃及向約瑟夢中顯現，說：","notes":[],"heads":["從埃及回來"]},{"n":20,"t":"「起來！帶著小孩子和他母親往以色列地去，因為要害小孩子性命的人已經死了。」","notes":[]},{"n":21,"t":"約瑟就起來，把小孩子和他母親帶到以色列地去；","notes":[]},{"n":22,"t":"只因聽見亞基老接著他父親希律作了猶太王，就怕往那裏去，又在夢中被主指示，便往加利利境內去了，","notes":[]},{"n":23,"t":"到了一座城，名叫拿撒勒，就住在那裏。這是要應驗先知所說，他將稱為拿撒勒人的話了。","notes":[]}]},"3":{"heading":"施洗約翰傳道","verses":[{"n":1,"t":"那時，有施洗的約翰出來，在猶太的曠野傳道，說：","notes":[]},{"n":2,"t":"「天國近了，你們應當悔改！」","notes":[]},{"n":3,"t":"這人就是先知以賽亞所說的。他說：「在曠野有人聲喊著說：預備主的道，修直他的路！」","notes":[]},{"n":4,"t":"這約翰身穿駱駝毛的衣服，腰束皮帶，吃的是蝗蟲、野蜜。","notes":[]},{"n":5,"t":"那時，耶路撒冷和猶太全地，並約旦河一帶地方的人，都出去到約翰那裏，","notes":[]},{"n":6,"t":"承認他們的罪，在約旦河裏受他的洗。","notes":[]},{"n":7,"t":"約翰看見許多法利賽人和撒都該人也來受洗，就對他們說：「毒蛇的種類！誰指示你們逃避將來的忿怒呢？","notes":[]},{"n":8,"t":"你們要結出果子來，與悔改的心相稱。","notes":[]},{"n":9,"t":"不要自己心裏說：『有亞伯拉罕為我們的祖宗。』我告訴你們，神能從這些石頭中給亞伯拉罕興起子孫來。","notes":[]},{"n":10,"t":"現在斧子已經放在樹根上，凡不結好果子的樹就砍下來，丟在火裏。","notes":[]},{"n":11,"t":"我是用水給你們施洗，叫你們悔改。但那在我以後來的，能力比我更大，我就是給他提鞋也不配。他要用聖靈與火給你們施洗。","notes":[]},{"n":12,"t":"他手裏拿著簸箕，要揚淨他的場，把麥子收在倉裏，把糠用不滅的火燒盡了。」","notes":[]},{"n":13,"t":"當下，耶穌從加利利來到約旦河，見了約翰，要受他的洗。","notes":[],"heads":["耶穌受洗"]},{"n":14,"t":"約翰想要攔住他，說：「我當受你的洗，你反倒上我這裏來嗎？」","notes":[]},{"n":15,"t":"耶穌回答說：「你暫且許我，因為我們理當這樣盡諸般的義。」於是約翰許了他。","notes":["或譯：禮"]},{"n":16,"t":"耶穌受了洗，隨即從水裏上來。天忽然為他開了，他就看見神的靈彷彿鴿子降下，落在他身上。","notes":[]},{"n":17,"t":"從天上有聲音說：「這是我的愛子，我所喜悅的。」","notes":[]}]},"4":{"heading":"耶穌受試探","verses":[{"n":1,"t":"當時，耶穌被聖靈引到曠野，受魔鬼的試探。","notes":[]},{"n":2,"t":"他禁食四十晝夜，後來就餓了。","notes":[]},{"n":3,"t":"那試探人的進前來，對他說：「你若是神的兒子，可以吩咐這些石頭變成食物。」","notes":[]},{"n":4,"t":"耶穌卻回答說：「經上記著說：人活著，不是單靠食物，乃是靠神口裏所出的一切話。」","notes":[]},{"n":5,"t":"魔鬼就帶他進了聖城，叫他站在殿頂上，","notes":["頂：原文是翅"]},{"n":6,"t":"對他說：「你若是神的兒子，可以跳下去，因為經上記著說：主要為你吩咐他的使者用手托著你，免得你的腳碰在石頭上。」","notes":[]},{"n":7,"t":"耶穌對他說：「經上又記著說：『不可試探主－你的神。』」","notes":[]},{"n":8,"t":"魔鬼又帶他上了一座最高的山，將世上的萬國與萬國的榮華都指給他看，","notes":[]},{"n":9,"t":"對他說：「你若俯伏拜我，我就把這一切都賜給你。」","notes":[]},{"n":10,"t":"耶穌說：「撒但，退去吧！因為經上記著說：當拜主－你的神，單要事奉他。」","notes":["就是抵擋的意思，乃魔鬼的別名"]},{"n":11,"t":"於是，魔鬼離了耶穌，有天使來伺候他。","notes":[]},{"n":12,"t":"耶穌聽見約翰下了監，就退到加利利去；","notes":[],"heads":["開始在加利利傳道"]},{"n":13,"t":"後又離開拿撒勒，往迦百農去，就住在那裏。那地方靠海，在西布倫和拿弗他利的邊界上。","notes":[]},{"n":14,"t":"這是要應驗先知以賽亞的話，","notes":[]},{"n":15,"t":"說：西布倫地，拿弗他利地，就是沿海的路，約旦河外，外邦人的加利利地－","notes":[]},{"n":16,"t":"那坐在黑暗裏的百姓看見了大光；坐在死蔭之地的人有光發現照著他們。","notes":[]},{"n":17,"t":"從那時候，耶穌就傳起道來，說：「天國近了，你們應當悔改！」","notes":[]},{"n":18,"t":"耶穌在加利利海邊行走，看見弟兄二人，就是那稱呼彼得的西門和他兄弟安得烈，在海裏撒網；他們本是打魚的。","notes":[],"heads":["呼召四個漁夫"]},{"n":19,"t":"耶穌對他們說：「來跟從我，我要叫你們得人如得魚一樣。」","notes":[]},{"n":20,"t":"他們就立刻捨了網，跟從了他。","notes":[]},{"n":21,"t":"從那裏往前走，又看見弟兄二人，就是西庇太的兒子雅各和他兄弟約翰，同他們的父親西庇太在船上補網，耶穌就招呼他們，","notes":[]},{"n":22,"t":"他們立刻捨了船，別了父親，跟從了耶穌。","notes":[]},{"n":23,"t":"耶穌走遍加利利，在各會堂裏教訓人，傳天國的福音，醫治百姓各樣的病症。","notes":[],"heads":["耶穌向廣大的群眾傳道"]},{"n":24,"t":"他的名聲就傳遍了敘利亞。那裏的人把一切害病的，就是害各樣疾病、各樣疼痛的和被鬼附的、癲癇的、癱瘓的，都帶了來，耶穌就治好了他們。","notes":[]},{"n":25,"t":"當下，有許多人從加利利、低加坡里、耶路撒冷、猶太、約旦河外來跟著他。","notes":[]}]},"5":{"heading":"山上寶訓","verses":[{"n":1,"t":"耶穌看見這許多的人，就上了山，既已坐下，門徒到他跟前來，","notes":[]},{"n":2,"t":"他就開口教訓他們，說：","notes":[]},{"n":3,"t":"虛心的人有福了！因為天國是他們的。","notes":[],"heads":["論福"]},{"n":4,"t":"哀慟的人有福了！因為他們必得安慰。","notes":[]},{"n":5,"t":"溫柔的人有福了！因為他們必承受地土。","notes":[]},{"n":6,"t":"飢渴慕義的人有福了！因為他們必得飽足。","notes":[]},{"n":7,"t":"憐恤人的人有福了！因為他們必蒙憐恤。","notes":[]},{"n":8,"t":"清心的人有福了！因為他們必得見神。","notes":[]},{"n":9,"t":"使人和睦的人有福了！因為他們必稱為神的兒子。","notes":[]},{"n":10,"t":"為義受逼迫的人有福了！因為天國是他們的。","notes":[]},{"n":11,"t":"「人若因我辱罵你們，逼迫你們，捏造各樣壞話毀謗你們，你們就有福了！","notes":[]},{"n":12,"t":"應當歡喜快樂，因為你們在天上的賞賜是大的。在你們以前的先知，人也是這樣逼迫他們。」","notes":[]},{"n":13,"t":"「你們是世上的鹽。鹽若失了味，怎能叫它再鹹呢？以後無用，不過丟在外面，被人踐踏了。","notes":[],"heads":["鹽和光"]},{"n":14,"t":"你們是世上的光。城造在山上是不能隱藏的。","notes":[]},{"n":15,"t":"人點燈，不放在斗底下，是放在燈臺上，就照亮一家的人。","notes":[]},{"n":16,"t":"你們的光也當這樣照在人前，叫他們看見你們的好行為，便將榮耀歸給你們在天上的父。」","notes":[]},{"n":17,"t":"「莫想我來要廢掉律法和先知。我來不是要廢掉，乃是要成全。","notes":[],"heads":["論律法"]},{"n":18,"t":"我實在告訴你們，就是到天地都廢去了，律法的一點一畫也不能廢去，都要成全。","notes":[]},{"n":19,"t":"所以，無論何人廢掉這誡命中最小的一條，又教訓人這樣做，他在天國要稱為最小的。但無論何人遵行這誡命，又教訓人遵行，他在天國要稱為大的。","notes":[]},{"n":20,"t":"我告訴你們，你們的義若不勝於文士和法利賽人的義，斷不能進天國。」","notes":[]},{"n":21,"t":"「你們聽見有吩咐古人的話，說：『不可殺人』；又說：『凡殺人的難免受審判。』","notes":[],"heads":["論發怒"]},{"n":22,"t":"只是我告訴你們，凡向弟兄動怒的，難免受審判；凡罵弟兄是拉加的，難免公會的審判；凡罵弟兄是魔利的，難免地獄的火。","notes":["有古卷在凡字下加：無緣無故地"]},{"n":23,"t":"所以，你在祭壇上獻禮物的時候，若想起弟兄向你懷怨，","notes":[]},{"n":24,"t":"就把禮物留在壇前，先去同弟兄和好，然後來獻禮物。","notes":[]},{"n":25,"t":"你同告你的對頭還在路上，就趕緊與他和息，恐怕他把你送給審判官，審判官交付衙役，你就下在監裏了。","notes":[]},{"n":26,"t":"我實在告訴你，若有一文錢沒有還清，你斷不能從那裏出來。」","notes":[]},{"n":27,"t":"「你們聽見有話說：『不可姦淫。』","notes":[],"heads":["論姦淫"]},{"n":28,"t":"只是我告訴你們，凡看見婦女就動淫念的，這人心裏已經與她犯姦淫了。","notes":[]},{"n":29,"t":"若是你的右眼叫你跌倒，就剜出來丟掉，寧可失去百體中的一體，不叫全身丟在地獄裏。","notes":[]},{"n":30,"t":"若是右手叫你跌倒，就砍下來丟掉，寧可失去百體中的一體，不叫全身下入地獄。」","notes":[]},{"n":31,"t":"「又有話說：『人若休妻，就當給她休書。』","notes":[],"heads":["論休妻"]},{"n":32,"t":"只是我告訴你們，凡休妻的，若不是為淫亂的緣故，就是叫她作淫婦了；人若娶這被休的婦人，也是犯姦淫了。」","notes":[]},{"n":33,"t":"「你們又聽見有吩咐古人的話，說：『不可背誓，所起的誓總要向主謹守。』","notes":[],"heads":["論起誓"]},{"n":34,"t":"只是我告訴你們，甚麼誓都不可起。不可指著天起誓，因為天是神的座位；","notes":[]},{"n":35,"t":"不可指著地起誓，因為地是他的腳凳；也不可指著耶路撒冷起誓，因為耶路撒冷是大君的京城；","notes":[]},{"n":36,"t":"又不可指著你的頭起誓，因為你不能使一根頭髮變黑變白了。","notes":[]},{"n":37,"t":"你們的話，是，就說是；不是，就說不是；若再多說就是出於那惡者 。」","notes":["或譯：就是從惡裏出來的"]},{"n":38,"t":"「你們聽見有話說：『以眼還眼，以牙還牙。』","notes":[],"heads":["論報復"]},{"n":39,"t":"只是我告訴你們，不要與惡人作對。有人打你的右臉，連左臉也轉過來由他打；","notes":[]},{"n":40,"t":"有人想要告你，要拿你的裏衣，連外衣也由他拿去；","notes":[]},{"n":41,"t":"有人強逼你走一里路，你就同他走二里；","notes":[]},{"n":42,"t":"有求你的，就給他；有向你借貸的，不可推辭。」","notes":[]},{"n":43,"t":"「你們聽見有話說：『當愛你的鄰舍，恨你的仇敵。』","notes":[],"heads":["論愛仇敵"]},{"n":44,"t":"只是我告訴你們，要愛你們的仇敵，為那逼迫你們的禱告。","notes":[]},{"n":45,"t":"這樣就可以作你們天父的兒子；因為他叫日頭照好人，也照歹人；降雨給義人，也給不義的人。","notes":[]},{"n":46,"t":"你們若單愛那愛你們的人，有甚麼賞賜呢？就是稅吏不也是這樣行嗎？","notes":[]},{"n":47,"t":"你們若單請你弟兄的安，比人有甚麼長處呢？就是外邦人不也是這樣行嗎？","notes":[]},{"n":48,"t":"所以，你們要完全，像你們的天父完全一樣。」","notes":[]}]},"6":{"heading":"論施捨","verses":[{"n":1,"t":"「你們要小心，不可將善事行在人的面前，故意叫他們看見，若是這樣，就不能得你們天父的賞賜了。","notes":[]},{"n":2,"t":"所以，你施捨的時候，不可在你前面吹號，像那假冒為善的人在會堂裏和街道上所行的，故意要得人的榮耀。我實在告訴你們，他們已經得了他們的賞賜。","notes":[]},{"n":3,"t":"你施捨的時候，不要叫左手知道右手所做的，","notes":[]},{"n":4,"t":"要叫你施捨的事行在暗中。你父在暗中察看，必然報答你 。」","notes":["有古卷：必在明處報答你"]},{"n":5,"t":"「你們禱告的時候，不可像那假冒為善的人，愛站在會堂裏和十字路口上禱告，故意叫人看見。我實在告訴你們，他們已經得了他們的賞賜。","notes":[],"heads":["論禱告"]},{"n":6,"t":"你禱告的時候，要進你的內屋，關上門，禱告你在暗中的父；你父在暗中察看，必然報答你。","notes":[]},{"n":7,"t":"你們禱告，不可像外邦人，用許多重複話，他們以為話多了必蒙垂聽。","notes":[]},{"n":8,"t":"你們不可效法他們；因為你們沒有祈求以先，你們所需用的，你們的父早已知道了。","notes":[]},{"n":9,"t":"所以，你們禱告要這樣說：我們在天上的父：願人都尊你的名為聖。","notes":[]},{"n":10,"t":"願你的國降臨；願你的旨意行在地上，如同行在天上。","notes":[]},{"n":11,"t":"我們日用的飲食，今日賜給我們。","notes":[]},{"n":12,"t":"免我們的債，如同我們免了人的債。","notes":[]},{"n":13,"t":"不叫我們遇見試探；救我們脫離凶惡 。因為國度、權柄、榮耀，全是你的，直到永遠。阿們 ！","notes":["或譯：脫離惡者","有古卷沒有因為…阿們等字"]},{"n":14,"t":"「你們饒恕人的過犯，你們的天父也必饒恕你們的過犯；","notes":[]},{"n":15,"t":"你們不饒恕人的過犯，你們的天父也必不饒恕你們的過犯。」","notes":[]},{"n":16,"t":"「你們禁食的時候，不可像那假冒為善的人，臉上帶著愁容；因為他們把臉弄得難看，故意叫人看出他們是禁食。我實在告訴你們，他們已經得了他們的賞賜。","notes":[],"heads":["論禁食"]},{"n":17,"t":"你禁食的時候，要梳頭洗臉，","notes":[]},{"n":18,"t":"不叫人看出你禁食來，只叫你暗中的父看見；你父在暗中察看，必然報答你。」","notes":[]},{"n":19,"t":"「不要為自己積攢財寶在地上；地上有蟲子咬，能銹壞，也有賊挖窟窿來偷。","notes":[],"heads":["論天上的財寶"]},{"n":20,"t":"只要積攢財寶在天上；天上沒有蟲子咬，不能銹壞，也沒有賊挖窟窿來偷。","notes":[]},{"n":21,"t":"因為你的財寶在哪裏，你的心也在那裏。」","notes":[]},{"n":22,"t":"「眼睛就是身上的燈。你的眼睛若瞭亮，全身就光明；","notes":[],"heads":["論心裏的光"]},{"n":23,"t":"你的眼睛若昏花，全身就黑暗。你裏頭的光若黑暗了，那黑暗是何等大呢！」","notes":[]},{"n":24,"t":"「一個人不能事奉兩個主；不是惡這個、愛那個，就是重這個、輕那個。你們不能又事奉神，又事奉瑪門 。」","notes":["瑪門：財利的意思"],"heads":["論神和財利"]},{"n":25,"t":"「所以我告訴你們，不要為生命憂慮吃甚麼，喝甚麼；為身體憂慮穿甚麼。生命不勝於飲食嗎？身體不勝於衣裳嗎？","notes":[],"heads":["不要憂慮"]},{"n":26,"t":"你們看那天上的飛鳥，也不種，也不收，也不積蓄在倉裏，你們的天父尚且養活牠。你們不比飛鳥貴重得多嗎？","notes":[]},{"n":27,"t":"你們哪一個能用思慮使壽數多加一刻呢 ？","notes":["或譯：使身量多加一肘呢"]},{"n":28,"t":"何必為衣裳憂慮呢？你想野地裏的百合花怎麼長起來；它也不勞苦，也不紡線。","notes":[]},{"n":29,"t":"然而我告訴你們，就是所羅門極榮華的時候，他所穿戴的，還不如這花一朵呢！","notes":[]},{"n":30,"t":"你們這小信的人哪！野地裏的草今天還在，明天就丟在爐裏，神還給它這樣的妝飾，何況你們呢！","notes":[]},{"n":31,"t":"所以，不要憂慮說，吃甚麼？喝甚麼？穿甚麼？","notes":[]},{"n":32,"t":"這都是外邦人所求的。你們需用的這一切東西，你們的天父是知道的。","notes":[]},{"n":33,"t":"你們要先求他的國和他的義，這些東西都要加給你們了。","notes":[]},{"n":34,"t":"所以，不要為明天憂慮，因為明天自有明天的憂慮；一天的難處一天當就夠了。」","notes":[]}]},"7":{"heading":"不要論斷人","verses":[{"n":1,"t":"「你們不要論斷人，免得你們被論斷。","notes":[]},{"n":2,"t":"因為你們怎樣論斷人，也必怎樣被論斷；你們用甚麼量器量給人，也必用甚麼量器量給你們。","notes":[]},{"n":3,"t":"為甚麼看見你弟兄眼中有刺，卻不想自己眼中有樑木呢？","notes":[]},{"n":4,"t":"你自己眼中有樑木，怎能對你弟兄說：『容我去掉你眼中的刺』呢？","notes":[]},{"n":5,"t":"你這假冒為善的人！先去掉自己眼中的樑木，然後才能看得清楚，去掉你弟兄眼中的刺。","notes":[]},{"n":6,"t":"不要把聖物給狗，也不要把你們的珍珠丟在豬前，恐怕牠踐踏了珍珠，轉過來咬你們。」","notes":[]},{"n":7,"t":"「你們祈求，就給你們；尋找，就尋見；叩門，就給你們開門。","notes":[],"heads":["祈求、尋找、叩門"]},{"n":8,"t":"因為凡祈求的，就得著；尋找的，就尋見；叩門的，就給他開門。","notes":[]},{"n":9,"t":"你們中間誰有兒子求餅，反給他石頭呢？","notes":[]},{"n":10,"t":"求魚，反給他蛇呢？","notes":[]},{"n":11,"t":"你們雖然不好，尚且知道拿好東西給兒女，何況你們在天上的父，豈不更把好東西給求他的人嗎？","notes":[]},{"n":12,"t":"所以，無論何事，你們願意人怎樣待你們，你們也要怎樣待人，因為這就是律法和先知的道理。」","notes":[]},{"n":13,"t":"「你們要進窄門。因為引到滅亡，那門是寬的，路是大的，進去的人也多；","notes":[],"heads":["窄門"]},{"n":14,"t":"引到永生，那門是窄的，路是小的，找著的人也少。」","notes":[]},{"n":15,"t":"「你們要防備假先知。他們到你們這裏來，外面披著羊皮，裏面卻是殘暴的狼。","notes":[],"heads":["兩種果樹"]},{"n":16,"t":"憑著他們的果子，就可以認出他們來。荊棘上豈能摘葡萄呢？蒺藜裏豈能摘無花果呢？","notes":[]},{"n":17,"t":"這樣，凡好樹都結好果子，惟獨壞樹結壞果子。","notes":[]},{"n":18,"t":"好樹不能結壞果子；壞樹不能結好果子。","notes":[]},{"n":19,"t":"凡不結好果子的樹就砍下來，丟在火裏。","notes":[]},{"n":20,"t":"所以，憑著他們的果子就可以認出他們來。」","notes":[]},{"n":21,"t":"「凡稱呼我『主啊，主啊』的人不能都進天國；惟獨遵行我天父旨意的人才能進去。","notes":[],"heads":["我不認識你們"]},{"n":22,"t":"當那日必有許多人對我說：『主啊，主啊，我們不是奉你的名傳道，奉你的名趕鬼，奉你的名行許多異能嗎？』","notes":[]},{"n":23,"t":"我就明明地告訴他們說：『我從來不認識你們，你們這些作惡的人，離開我去吧！』」","notes":[]},{"n":24,"t":"「所以，凡聽見我這話就去行的，好比一個聰明人，把房子蓋在磐石上；","notes":[],"heads":["兩種蓋房子的人"]},{"n":25,"t":"雨淋，水沖，風吹，撞著那房子，房子總不倒塌，因為根基立在磐石上。","notes":[]},{"n":26,"t":"凡聽見我這話不去行的，好比一個無知的人，把房子蓋在沙土上；","notes":[]},{"n":27,"t":"雨淋，水沖，風吹，撞著那房子，房子就倒塌了，並且倒塌得很大。」","notes":[]},{"n":28,"t":"耶穌講完了這些話，眾人都希奇他的教訓；","notes":[]},{"n":29,"t":"因為他教訓他們，正像有權柄的人，不像他們的文士。","notes":[]}]},"8":{"heading":"潔淨長大痲瘋的人","verses":[{"n":1,"t":"耶穌下了山，有許多人跟著他。","notes":[]},{"n":2,"t":"有一個長大痲瘋的來拜他，說：「主若肯，必能叫我潔淨了。」","notes":[]},{"n":3,"t":"耶穌伸手摸他，說：「我肯，你潔淨了吧！」他的大痲瘋立刻就潔淨了。","notes":[]},{"n":4,"t":"耶穌對他說：「你切不可告訴人，只要去把身體給祭司察看，獻上摩西所吩咐的禮物，對眾人作證據。」","notes":[]},{"n":5,"t":"耶穌進了迦百農，有一個百夫長進前來，求他說：","notes":[],"heads":["治好百夫長的僕人"]},{"n":6,"t":"「主啊，我的僕人害癱瘓病，躺在家裏，甚是疼苦。」","notes":[]},{"n":7,"t":"耶穌說：「我去醫治他。」","notes":[]},{"n":8,"t":"百夫長回答說：「主啊，你到我舍下，我不敢當；只要你說一句話，我的僕人就必好了。","notes":[]},{"n":9,"t":"因為我在人的權下，也有兵在我以下；對這個說『去！』他就去；對那個說『來！』他就來；對我的僕人說『你做這事！』他就去做。」","notes":[]},{"n":10,"t":"耶穌聽見就希奇，對跟從的人說：「我實在告訴你們，這麼大的信心，就是在以色列中，我也沒有遇見過。","notes":[]},{"n":11,"t":"我又告訴你們，從東從西，將有許多人來，在天國裏與亞伯拉罕、以撒、雅各一同坐席；","notes":[]},{"n":12,"t":"惟有本國的子民竟被趕到外邊黑暗裏去，在那裏必要哀哭切齒了。」","notes":[]},{"n":13,"t":"耶穌對百夫長說：「你回去吧！照你的信心，給你成全了。」那時，他的僕人就好了。","notes":[]},{"n":14,"t":"耶穌到了彼得家裏，見彼得的岳母害熱病躺著。","notes":[],"heads":["治好許多病人"]},{"n":15,"t":"耶穌把她的手一摸，熱就退了；她就起來服事耶穌。","notes":[]},{"n":16,"t":"到了晚上，有人帶著許多被鬼附的來到耶穌跟前，他只用一句話就把鬼都趕出去，並且治好了一切有病的人。","notes":[]},{"n":17,"t":"這是要應驗先知以賽亞的話，說：他代替我們的軟弱，擔當我們的疾病。","notes":[]},{"n":18,"t":"耶穌見許多人圍著他，就吩咐渡到那邊去。","notes":[],"heads":["要跟從耶穌的人"]},{"n":19,"t":"有一個文士來，對他說：「夫子，你無論往哪裏去，我要跟從你。」","notes":[]},{"n":20,"t":"耶穌說：「狐狸有洞，天空的飛鳥有窩，人子卻沒有枕頭的地方。」","notes":[]},{"n":21,"t":"又有一個門徒對耶穌說：「主啊，容我先回去埋葬我的父親。」","notes":[]},{"n":22,"t":"耶穌說：「任憑死人埋葬他們的死人；你跟從我吧！」","notes":[]},{"n":23,"t":"耶穌上了船，門徒跟著他。","notes":[],"heads":["平靜風和海"]},{"n":24,"t":"海裏忽然起了暴風，甚至船被波浪掩蓋；耶穌卻睡著了。","notes":[]},{"n":25,"t":"門徒來叫醒了他，說：「主啊，救我們，我們喪命啦！」","notes":[]},{"n":26,"t":"耶穌說：「你們這小信的人哪，為甚麼膽怯呢？」於是起來，斥責風和海，風和海就大大地平靜了。","notes":[]},{"n":27,"t":"眾人希奇，說：「這是怎樣的人？連風和海也聽從他了！」","notes":[]},{"n":28,"t":"耶穌既渡到那邊去，來到加大拉人的地方，就有兩個被鬼附的人從墳塋裏出來迎著他，極其凶猛，甚至沒有人能從那條路上經過。","notes":[],"heads":["治好加大拉被鬼附的人"]},{"n":29,"t":"他們喊著說：「神的兒子，我們與你有甚麼相干？時候還沒有到，你就上這裏來叫我們受苦嗎？」","notes":[]},{"n":30,"t":"離他們很遠，有一大群豬吃食。","notes":[]},{"n":31,"t":"鬼就央求耶穌，說：「若把我們趕出去，就打發我們進入豬群吧！」","notes":[]},{"n":32,"t":"耶穌說：「去吧！」鬼就出來，進入豬群。全群忽然闖下山崖，投在海裏淹死了。","notes":[]},{"n":33,"t":"放豬的就逃跑進城，將這一切事和被鬼附的人所遭遇的都告訴人。","notes":[]},{"n":34,"t":"合城的人都出來迎見耶穌，既見了就央求他離開他們的境界。","notes":[]}]},"9":{"heading":"治好癱瘓病人","verses":[{"n":1,"t":"耶穌上了船，渡過海，來到自己的城裏。","notes":[]},{"n":2,"t":"有人用褥子抬著一個癱子到耶穌跟前來。耶穌見他們的信心，就對癱子說：「小子，放心吧！你的罪赦了。」","notes":[]},{"n":3,"t":"有幾個文士心裏說：「這個人說僭妄的話了。」","notes":[]},{"n":4,"t":"耶穌知道他們的心意，就說：「你們為甚麼心裏懷著惡念呢？","notes":[]},{"n":5,"t":"或說『你的罪赦了』，或說『你起來行走』，哪一樣容易呢？","notes":[]},{"n":6,"t":"但要叫你們知道，人子在地上有赦罪的權柄」；就對癱子說：「起來！拿你的褥子回家去吧。」","notes":[]},{"n":7,"t":"那人就起來，回家去了。","notes":[]},{"n":8,"t":"眾人看見都驚奇，就歸榮耀與神，因為他將這樣的權柄賜給人。","notes":[]},{"n":9,"t":"耶穌從那裏往前走，看見一個人名叫馬太，坐在稅關上，就對他說：「你跟從我來。」他就起來跟從了耶穌。","notes":[],"heads":["呼召馬太"]},{"n":10,"t":"耶穌在屋裏坐席的時候，有好些稅吏和罪人來，與耶穌和他的門徒一同坐席。","notes":[]},{"n":11,"t":"法利賽人看見，就對耶穌的門徒說：「你們的先生為甚麼和稅吏並罪人一同吃飯呢？」","notes":[]},{"n":12,"t":"耶穌聽見，就說：「康健的人用不著醫生，有病的人才用得著。","notes":[]},{"n":13,"t":"經上說：『我喜愛憐恤，不喜愛祭祀。』這句話的意思，你們且去揣摩。我來本不是召義人，乃是召罪人。」","notes":[]},{"n":14,"t":"那時，約翰的門徒來見耶穌，說：「我們和法利賽人常常禁食，你的門徒倒不禁食，這是為甚麼呢？」","notes":[],"heads":["禁食的問題"]},{"n":15,"t":"耶穌對他們說：「新郎和陪伴之人同在的時候，陪伴之人豈能哀慟呢？但日子將到，新郎要離開他們，那時候他們就要禁食。","notes":[]},{"n":16,"t":"沒有人把新布補在舊衣服上；因為所補上的反帶壞了那衣服，破的就更大了。","notes":[]},{"n":17,"t":"也沒有人把新酒裝在舊皮袋裏；若是這樣，皮袋就裂開，酒漏出來，連皮袋也壞了。惟獨把新酒裝在新皮袋裏，兩樣就都保全了。」","notes":[]},{"n":18,"t":"耶穌說這話的時候，有一個管會堂的來拜他，說：「我女兒剛才死了，求你去按手在她身上，她就必活了。」","notes":[],"heads":["管會堂者的女兒和血漏的女人"]},{"n":19,"t":"耶穌便起來跟著他去；門徒也跟了去。","notes":[]},{"n":20,"t":"有一個女人，患了十二年的血漏 ，來到耶穌背後，摸他的衣裳繸子；","notes":[]},{"n":21,"t":"因為她心裏說：「我只摸他的衣裳，就必痊癒。」","notes":[]},{"n":22,"t":"耶穌轉過來，看見她，就說：「女兒，放心！你的信救了你。」從那時候，女人就痊癒了。","notes":[]},{"n":23,"t":"耶穌到了管會堂的家裏，看見有吹手，又有許多人亂嚷，","notes":[]},{"n":24,"t":"就說：「退去吧！這閨女不是死了，是睡著了。」他們就嗤笑他。","notes":[]},{"n":25,"t":"眾人既被攆出，耶穌就進去，拉著閨女的手，閨女便起來了。","notes":[]},{"n":26,"t":"於是這風聲傳遍了那地方。","notes":[]},{"n":27,"t":"耶穌從那裏往前走，有兩個瞎子跟著他，喊叫說：「大衛的子孫，可憐我們吧！」","notes":[],"heads":["兩個瞎子得醫治"]},{"n":28,"t":"耶穌進了房子，瞎子就來到他跟前。耶穌說：「你們信我能做這事嗎？」他們說：「主啊，我們信。」","notes":[]},{"n":29,"t":"耶穌就摸他們的眼睛，說：「照著你們的信給你們成全了吧。」","notes":[]},{"n":30,"t":"他們的眼睛就開了。耶穌切切地囑咐他們說：「你們要小心，不可叫人知道。」","notes":[]},{"n":31,"t":"他們出去，竟把他的名聲傳遍了那地方。","notes":[]},{"n":32,"t":"他們出去的時候，有人將鬼所附的一個啞巴帶到耶穌跟前來。","notes":[],"heads":["治好啞巴"]},{"n":33,"t":"鬼被趕出去，啞巴就說出話來。眾人都希奇，說：「在以色列中，從來沒有見過這樣的事。」","notes":[]},{"n":34,"t":"法利賽人卻說：「他是靠著鬼王趕鬼。」","notes":[]},{"n":35,"t":"耶穌走遍各城各鄉，在會堂裏教訓人，宣講天國的福音，又醫治各樣的病症。","notes":[],"heads":["耶穌的憐憫"]},{"n":36,"t":"他看見許多的人，就憐憫他們；因為他們困苦流離，如同羊沒有牧人一般。","notes":[]},{"n":37,"t":"於是對門徒說：「要收的莊稼多，做工的人少。","notes":[]},{"n":38,"t":"所以，你們當求莊稼的主打發工人出去收他的莊稼。」","notes":[]}]},"10":{"heading":"十二使徒","verses":[{"n":1,"t":"耶穌叫了十二個門徒來，給他們權柄，能趕逐污鬼，並醫治各樣的病症。","notes":[]},{"n":2,"t":"這十二使徒的名：頭一個叫西門（又稱彼得），還有他兄弟安得烈，西庇太的兒子雅各和雅各的兄弟約翰，","notes":[]},{"n":3,"t":"腓力和巴多羅買，多馬和稅吏馬太，亞勒腓的兒子雅各，和達太，","notes":[]},{"n":4,"t":"奮銳黨的西門，還有賣耶穌的加略人猶大。","notes":[]},{"n":5,"t":"耶穌差這十二個人去，吩咐他們說：「外邦人的路，你們不要走；撒馬利亞人的城，你們不要進；","notes":[],"heads":["十二使徒的使命"]},{"n":6,"t":"寧可往以色列家迷失的羊那裏去。","notes":[]},{"n":7,"t":"隨走隨傳，說『天國近了！』","notes":[]},{"n":8,"t":"醫治病人，叫死人復活，叫長大痲瘋的潔淨，把鬼趕出去。你們白白地得來，也要白白地捨去。","notes":[]},{"n":9,"t":"腰袋裏不要帶金銀銅錢；","notes":[]},{"n":10,"t":"行路不要帶口袋；不要帶兩件褂子，也不要帶鞋和柺杖。因為工人得飲食是應當的。","notes":[]},{"n":11,"t":"你們無論進哪一城，哪一村，要打聽那裏誰是好人，就住在他家，直住到走的時候。","notes":[]},{"n":12,"t":"進他家裏去，要請他的安。","notes":[]},{"n":13,"t":"那家若配得平安，你們所求的平安就必臨到那家；若不配得，你們所求的平安仍歸你們。","notes":[]},{"n":14,"t":"凡不接待你們、不聽你們話的人，你們離開那家，或是那城的時候，就把腳上的塵土跺下去。","notes":[]},{"n":15,"t":"我實在告訴你們，當審判的日子，所多瑪和蛾摩拉所受的，比那城還容易受呢！」","notes":[]},{"n":16,"t":"「我差你們去，如同羊進入狼群；所以你們要靈巧像蛇，馴良像鴿子。","notes":[],"heads":["將來的逼迫"]},{"n":17,"t":"你們要防備人；因為他們要把你們交給公會 ，也要在會堂裏鞭打你們，","notes":[]},{"n":18,"t":"並且你們要為我的緣故被送到諸侯君王面前，對他們和外邦人作見證。","notes":[]},{"n":19,"t":"你們被交的時候，不要思慮怎樣說話，或說甚麼話。到那時候，必賜給你們當說的話；","notes":[]},{"n":20,"t":"因為不是你們自己說的，乃是你們父的靈在你們裏頭說的。","notes":[]},{"n":21,"t":"弟兄要把弟兄，父親要把兒子，送到死地；兒女要與父母為敵，害死他們；","notes":[]},{"n":22,"t":"並且你們要為我的名被眾人恨惡。惟有忍耐到底的必然得救。","notes":[]},{"n":23,"t":"有人在這城裏逼迫你們，就逃到那城裏去。我實在告訴你們，以色列的城邑，你們還沒有走遍，人子就到了。","notes":[]},{"n":24,"t":"學生不能高過先生；僕人不能高過主人。","notes":[]},{"n":25,"t":"學生和先生一樣，僕人和主人一樣，也就罷了。人既罵家主是別西卜，何況他的家人呢？」","notes":["別西卜：是鬼王的名"]},{"n":26,"t":"「所以，不要怕他們；因為掩蓋的事沒有不露出來的，隱藏的事沒有不被人知道的。","notes":[],"heads":["該怕的是誰"]},{"n":27,"t":"我在暗中告訴你們的，你們要在明處說出來；你們耳中所聽的，要在房上宣揚出來。","notes":[]},{"n":28,"t":"那殺身體、不能殺靈魂的，不要怕他們；惟有能把身體和靈魂都滅在地獄裏的，正要怕他。","notes":[]},{"n":29,"t":"兩個麻雀不是賣一分銀子嗎？若是你們的父不許，一個也不能掉在地上；","notes":[]},{"n":30,"t":"就是你們的頭髮也都被數過了。","notes":[]},{"n":31,"t":"所以，不要懼怕，你們比許多麻雀還貴重！」","notes":[]},{"n":32,"t":"「凡在人面前認我的，我在我天上的父面前也必認他；","notes":[],"heads":["在人的面前承認基督"]},{"n":33,"t":"凡在人面前不認我的，我在我天上的父面前也必不認他。」","notes":[]},{"n":34,"t":"「你們不要想我來是叫地上太平；我來並不是叫地上太平，乃是叫地上動刀兵。","notes":[],"heads":["不是和平，而是刀劍"]},{"n":35,"t":"因為我來是叫人與父親生疏，女兒與母親生疏，媳婦與婆婆生疏。","notes":[]},{"n":36,"t":"人的仇敵就是自己家裏的人。","notes":[]},{"n":37,"t":"「愛父母過於愛我的，不配作我的門徒；愛兒女過於愛我的，不配作我的門徒；","notes":[]},{"n":38,"t":"不背著他的十字架跟從我的，也不配作我的門徒。","notes":[]},{"n":39,"t":"得著生命的，將要失喪生命；為我失喪生命的，將要得著生命。」","notes":[]},{"n":40,"t":"「人接待你們就是接待我；接待我就是接待那差我來的。","notes":[],"heads":["論報賞"]},{"n":41,"t":"人因為先知的名接待先知，必得先知所得的賞賜；人因為義人的名接待義人，必得義人所得的賞賜。","notes":[]},{"n":42,"t":"無論何人，因為門徒的名，只把一杯涼水給這小子裏的一個喝，我實在告訴你們，這人不能不得賞賜。」","notes":[]}]},"11":{"heading":"施洗約翰的門徒來見耶穌","verses":[{"n":1,"t":"耶穌吩咐完了十二個門徒，就離開那裏，往各城去傳道、教訓人。","notes":[]},{"n":2,"t":"約翰在監裏聽見基督所做的事，就打發兩個門徒去，","notes":[]},{"n":3,"t":"問他說：「那將要來的是你嗎？還是我們等候別人呢？」","notes":[]},{"n":4,"t":"耶穌回答說：「你們去，把所聽見、所看見的事告訴約翰。","notes":[]},{"n":5,"t":"就是瞎子看見，瘸子行走，長大痲瘋的潔淨，聾子聽見，死人復活，窮人有福音傳給他們。","notes":[]},{"n":6,"t":"凡不因我跌倒的就有福了！」","notes":[]},{"n":7,"t":"他們走的時候，耶穌就對眾人講論約翰說：「你們從前出到曠野是要看甚麼呢？要看風吹動的蘆葦嗎？","notes":[]},{"n":8,"t":"你們出去到底是要看甚麼？要看穿細軟衣服的人嗎？那穿細軟衣服的人是在王宮裏。","notes":[]},{"n":9,"t":"你們出去究竟是為甚麼？是要看先知嗎？我告訴你們，是的，他比先知大多了。","notes":[]},{"n":10,"t":"經上記著說：『我要差遣我的使者在你前面預備道路』，所說的就是這個人。","notes":[]},{"n":11,"t":"我實在告訴你們，凡婦人所生的，沒有一個興起來大過施洗約翰的；然而天國裏最小的比他還大。","notes":[]},{"n":12,"t":"從施洗約翰的時候到如今，天國是努力進入的，努力的人就得著了。","notes":[]},{"n":13,"t":"因為眾先知和律法說預言，到約翰為止。","notes":[]},{"n":14,"t":"你們若肯領受，這人就是那應當來的以利亞。","notes":[]},{"n":15,"t":"有耳可聽的，就應當聽！","notes":[]},{"n":16,"t":"我可用甚麼比這世代呢？好像孩童坐在街市上招呼同伴，說：","notes":[]},{"n":17,"t":"我們向你們吹笛，你們不跳舞；我們向你們舉哀，你們不捶胸。","notes":[]},{"n":18,"t":"約翰來了，也不吃也不喝，人就說他是被鬼附著的；","notes":[]},{"n":19,"t":"人子來了，也吃也喝，人又說他是貪食好酒的人，是稅吏和罪人的朋友。但智慧之子總以智慧為是 。」","notes":["有古卷：但智慧在行為上就顯為是"]},{"n":20,"t":"耶穌在諸城中行了許多異能，那些城的人終不悔改，就在那時候責備他們，說：","notes":[],"heads":["耶穌責備不悔改的城"]},{"n":21,"t":"「哥拉汛哪，你有禍了！伯賽大啊，你有禍了！因為在你們中間所行的異能，若行在泰爾、西頓，他們早已披麻蒙灰悔改了。","notes":[]},{"n":22,"t":"但我告訴你們，當審判的日子，泰爾、西頓所受的，比你們還容易受呢！","notes":[]},{"n":23,"t":"迦百農啊，你已經升到天上，將來必墜落陰間；因為在你那裏所行的異能，若行在所多瑪，它還可以存到今日。","notes":["或譯：你將要升到天上嗎"]},{"n":24,"t":"但我告訴你們，當審判的日子，所多瑪所受的，比你還容易受呢！」","notes":[]},{"n":25,"t":"那時，耶穌說：「父啊，天地的主，我感謝你！因為你將這些事向聰明通達人就藏起來，向嬰孩就顯出來。","notes":[],"heads":["到我這裏來"]},{"n":26,"t":"父啊，是的，因為你的美意本是如此。","notes":[]},{"n":27,"t":"一切所有的，都是我父交付我的；除了父，沒有人知道子；除了子和子所願意指示的，沒有人知道父。","notes":[]},{"n":28,"t":"凡勞苦擔重擔的人可以到我這裏來，我就使你們得安息。","notes":[]},{"n":29,"t":"我心裏柔和謙卑，你們當負我的軛，學我的樣式；這樣，你們心裏就必得享安息。","notes":[]},{"n":30,"t":"因為我的軛是容易的，我的擔子是輕省的。」","notes":[]}]},"12":{"heading":"安息日的問題","verses":[{"n":1,"t":"那時，耶穌在安息日從麥地經過。他的門徒餓了，就掐起麥穗來吃。","notes":[]},{"n":2,"t":"法利賽人看見，就對耶穌說：「看哪，你的門徒做安息日不可做的事了！」","notes":[]},{"n":3,"t":"耶穌對他們說：「經上記著大衛和跟從他的人飢餓之時所做的事，你們沒有念過嗎？","notes":[]},{"n":4,"t":"他怎麼進了神的殿，吃了陳設餅，這餅不是他和跟從他的人可以吃得，惟獨祭司才可以吃。","notes":[]},{"n":5,"t":"再者，律法上所記的，當安息日，祭司在殿裏犯了安息日還是沒有罪，你們沒有念過嗎？","notes":[]},{"n":6,"t":"但我告訴你們，在這裏有一人比殿更大。","notes":[]},{"n":7,"t":"『我喜愛憐恤，不喜愛祭祀。』你們若明白這話的意思，就不將無罪的當作有罪的了。","notes":[]},{"n":8,"t":"因為人子是安息日的主。」","notes":[]},{"n":9,"t":"耶穌離開那地方，進了一個會堂。","notes":[],"heads":["治好枯乾了一隻手的人"]},{"n":10,"t":"那裏有一個人枯乾了一隻手。有人問耶穌說：「安息日治病可以不可以？」意思是要控告他。","notes":[]},{"n":11,"t":"耶穌說：「你們中間誰有一隻羊，當安息日掉在坑裏，不把牠抓住、拉上來呢？","notes":[]},{"n":12,"t":"人比羊何等貴重呢！所以，在安息日做善事是可以的。」","notes":[]},{"n":13,"t":"於是對那人說：「伸出手來！」他把手一伸，手就復了原，和那隻手一樣。","notes":[]},{"n":14,"t":"法利賽人出去，商議怎樣可以除滅耶穌。","notes":[]},{"n":15,"t":"耶穌知道了，就離開那裏，有許多人跟著他。他把其中有病的人都治好了；","notes":[],"heads":["神所揀選的僕人"]},{"n":16,"t":"又囑咐他們，不要給他傳名。","notes":[]},{"n":17,"t":"這是要應驗先知以賽亞的話，說：","notes":[]},{"n":18,"t":"看哪！我的僕人，我所揀選、所親愛、心裏所喜悅的，我要將我的靈賜給他；他必將公理傳給外邦。","notes":[]},{"n":19,"t":"他不爭競，不喧嚷；街上也沒有人聽見他的聲音。","notes":[]},{"n":20,"t":"壓傷的蘆葦，他不折斷；將殘的燈火，他不吹滅；等他施行公理，叫公理得勝。","notes":[]},{"n":21,"t":"外邦人都要仰望他的名。","notes":[]},{"n":22,"t":"當下，有人將一個被鬼附著、又瞎又啞的人帶到耶穌那裏，耶穌就醫治他，甚至那啞巴又能說話，又能看見。","notes":[],"heads":["耶穌和別西卜"]},{"n":23,"t":"眾人都驚奇，說：「這不是大衛的子孫嗎？」","notes":[]},{"n":24,"t":"但法利賽人聽見，就說：「這個人趕鬼，無非是靠著鬼王別西卜啊。」","notes":[]},{"n":25,"t":"耶穌知道他們的意念，就對他們說：「凡一國自相紛爭，就成為荒場；一城一家自相紛爭，必站立不住；","notes":[]},{"n":26,"t":"若撒但趕逐撒但，就是自相紛爭，他的國怎能站得住呢？","notes":[]},{"n":27,"t":"我若靠著別西卜趕鬼，你們的子弟趕鬼又靠著誰呢？這樣，他們就要斷定你們的是非。","notes":[]},{"n":28,"t":"我若靠著神的靈趕鬼，這就是神的國臨到你們了。","notes":[]},{"n":29,"t":"人怎能進壯士家裏，搶奪他的家具呢？除非先捆住那壯士，才可以搶奪他的家財。","notes":[]},{"n":30,"t":"不與我相合的，就是敵我的；不同我收聚的，就是分散的。」","notes":[]},{"n":31,"t":"所以我告訴你們：「人一切的罪和褻瀆的話都可得赦免，惟獨褻瀆聖靈，總不得赦免。","notes":[]},{"n":32,"t":"凡說話干犯人子的，還可得赦免；惟獨說話干犯聖靈的，今世來世總不得赦免。」","notes":[]},{"n":33,"t":"「你們或以為樹好，果子也好；樹壞，果子也壞；因為看果子就可以知道樹。","notes":[],"heads":["樹和果子"]},{"n":34,"t":"毒蛇的種類！你們既是惡人，怎能說出好話來呢？因為心裏所充滿的，口裏就說出來。","notes":[]},{"n":35,"t":"善人從他心裏所存的善就發出善來；惡人從他心裏所存的惡就發出惡來。","notes":[]},{"n":36,"t":"我又告訴你們，凡人所說的閒話，當審判的日子，必要句句供出來；","notes":[]},{"n":37,"t":"因為要憑你的話定你為義，也要憑你的話定你有罪。」","notes":[]},{"n":38,"t":"當時，有幾個文士和法利賽人對耶穌說：「夫子，我們願意你顯個神蹟給我們看。」","notes":[],"heads":["要求神蹟"]},{"n":39,"t":"耶穌回答說：「一個邪惡淫亂的世代求看神蹟，除了先知約拿的神蹟以外，再沒有神蹟給他們看。","notes":[]},{"n":40,"t":"約拿三日三夜在大魚肚腹中，人子也要這樣三日三夜在地裏頭。","notes":[]},{"n":41,"t":"當審判的時候，尼尼微人要起來定這世代的罪，因為尼尼微人聽了約拿所傳的就悔改了。看哪，在這裏有一人比約拿更大！","notes":[]},{"n":42,"t":"當審判的時候，南方的女王要起來定這世代的罪； 因為她從地極而來，要聽所羅門的智慧話。看哪，在這裏有一人比所羅門更大！」","notes":[]},{"n":43,"t":"「污鬼離了人身，就在無水之地過來過去，尋求安歇之處，卻尋不著。","notes":[],"heads":["污鬼回來"]},{"n":44,"t":"於是說：『我要回到我所出來的屋裏去。』到了，就看見裏面空閒，打掃乾淨，修飾好了，","notes":[]},{"n":45,"t":"便去另帶了七個比自己更惡的鬼來，都進去住在那裏。那人末後的景況比先前更不好了。這邪惡的世代也要如此。」","notes":[]},{"n":46,"t":"耶穌還對眾人說話的時候，不料他母親和他弟兄站在外邊，要與他說話。","notes":[],"heads":["耶穌的母親和兄弟們"]},{"n":47,"t":"有人告訴他說：「看哪，你母親和你弟兄站在外邊，要與你說話。」","notes":[]},{"n":48,"t":"他卻回答那人說：「誰是我的母親？誰是我的弟兄？」","notes":[]},{"n":49,"t":"就伸手指著門徒，說：「看哪，我的母親，我的弟兄。","notes":[]},{"n":50,"t":"凡遵行我天父旨意的人，就是我的弟兄姊妹和母親了。」","notes":[]}]},"13":{"heading":"撒種的比喻","verses":[{"n":1,"t":"當那一天，耶穌從房子裏出來，坐在海邊。","notes":[]},{"n":2,"t":"有許多人到他那裏聚集，他只得上船坐下，眾人都站在岸上。","notes":[]},{"n":3,"t":"他用比喻對他們講許多道理，說：「有一個撒種的出去撒種；","notes":[]},{"n":4,"t":"撒的時候，有落在路旁的，飛鳥來吃盡了；","notes":[]},{"n":5,"t":"有落在土淺石頭地上的，土既不深，發苗最快，","notes":[]},{"n":6,"t":"日頭出來一曬，因為沒有根，就枯乾了；","notes":[]},{"n":7,"t":"有落在荊棘裏的，荊棘長起來，把它擠住了；","notes":[]},{"n":8,"t":"又有落在好土裏的，就結實，有一百倍的，有六十倍的，有三十倍的。","notes":[]},{"n":9,"t":"有耳可聽的，就應當聽！」","notes":[]},{"n":10,"t":"門徒進前來，問耶穌說：「對眾人講話，為甚麼用比喻呢？」","notes":[],"heads":["用比喻的目的"]},{"n":11,"t":"耶穌回答說：「因為天國的奧祕只叫你們知道，不叫他們知道。","notes":[]},{"n":12,"t":"凡有的，還要加給他，叫他有餘；凡沒有的，連他所有的，也要奪去。","notes":[]},{"n":13,"t":"所以我用比喻對他們講，是因他們看也看不見，聽也聽不見，也不明白。","notes":[]},{"n":14,"t":"在他們身上，正應了以賽亞的預言，說：你們聽是要聽見，卻不明白；看是要看見，卻不曉得；","notes":[]},{"n":15,"t":"因為這百姓油蒙了心，耳朵發沉，眼睛閉著，恐怕眼睛看見，耳朵聽見，心裏明白，回轉過來，我就醫治他們。","notes":[]},{"n":16,"t":"「但你們的眼睛是有福的，因為看見了；你們的耳朵也是有福的，因為聽見了。","notes":[]},{"n":17,"t":"我實在告訴你們，從前有許多先知和義人要看你們所看的，卻沒有看見，要聽你們所聽的，卻沒有聽見。」","notes":[]},{"n":18,"t":"「所以，你們當聽這撒種的比喻。","notes":[],"heads":["解明撒種的比喻"]},{"n":19,"t":"凡聽見天國道理不明白的，那惡者就來，把所撒在他心裏的奪了去；這就是撒在路旁的了。","notes":[]},{"n":20,"t":"撒在石頭地上的，就是人聽了道，當下歡喜領受，","notes":[]},{"n":21,"t":"只因心裏沒有根，不過是暫時的，及至為道遭了患難，或是受了逼迫，立刻就跌倒了。","notes":[]},{"n":22,"t":"撒在荊棘裏的，就是人聽了道，後來有世上的思慮、錢財的迷惑把道擠住了，不能結實。","notes":[]},{"n":23,"t":"撒在好地上的，就是人聽道明白了，後來結實，有一百倍的，有六十倍的，有三十倍的。」","notes":[]},{"n":24,"t":"耶穌又設個比喻對他們說：「天國好像人撒好種在田裏，","notes":[],"heads":["稗子的比喻"]},{"n":25,"t":"及至人睡覺的時候，有仇敵來，將稗子撒在麥子裏就走了。","notes":[]},{"n":26,"t":"到長苗吐穗的時候，稗子也顯出來。","notes":[]},{"n":27,"t":"田主的僕人來告訴他說：『主啊，你不是撒好種在田裏嗎？從哪裏來的稗子呢？』","notes":[]},{"n":28,"t":"主人說：『這是仇敵做的。』僕人說：『你要我們去薅出來嗎？』","notes":[]},{"n":29,"t":"主人說：『不必，恐怕薅稗子，連麥子也拔出來。","notes":[]},{"n":30,"t":"容這兩樣一齊長，等著收割。當收割的時候，我要對收割的人說，先將稗子薅出來，捆成捆，留著燒；惟有麥子要收在倉裏。』」","notes":[]},{"n":31,"t":"他又設個比喻對他們說：「天國好像一粒芥菜種，有人拿去種在田裏。","notes":[],"heads":["芥菜種和麵酵的比喻"]},{"n":32,"t":"這原是百種裏最小的，等到長起來，卻比各樣的菜都大，且成了樹，天上的飛鳥來宿在它的枝上。」","notes":[]},{"n":33,"t":"他又對他們講個比喻說：「天國好像麵酵，有婦人拿來，藏在三斗麵裏，直等全團都發起來。」","notes":[]},{"n":34,"t":"這都是耶穌用比喻對眾人說的話；若不用比喻，就不對他們說甚麼。","notes":[],"heads":["用比喻的原因"]},{"n":35,"t":"這是要應驗先知的話，說：我要開口用比喻，把創世以來所隱藏的事發明出來。","notes":[]},{"n":36,"t":"當下，耶穌離開眾人，進了房子。他的門徒進前來，說：「請把田間稗子的比喻講給我們聽。」","notes":[],"heads":["解明稗子的比喻"]},{"n":37,"t":"他回答說：「那撒好種的就是人子；","notes":[]},{"n":38,"t":"田地就是世界；好種就是天國之子；稗子就是那惡者之子；","notes":[]},{"n":39,"t":"撒稗子的仇敵就是魔鬼；收割的時候就是世界的末了；收割的人就是天使。","notes":[]},{"n":40,"t":"將稗子薅出來用火焚燒，世界的末了也要如此。","notes":[]},{"n":41,"t":"人子要差遣使者，把一切叫人跌倒的和作惡的，從他國裏挑出來，","notes":[]},{"n":42,"t":"丟在火爐裏；在那裏必要哀哭切齒了。","notes":[]},{"n":43,"t":"那時，義人在他們父的國裏，要發出光來，像太陽一樣。有耳可聽的，就應當聽！」","notes":[]},{"n":44,"t":"「天國好像寶貝藏在地裏，人遇見了就把它藏起來，歡歡喜喜地去變賣一切所有的，買這塊地。","notes":[],"heads":["藏寶、尋珠、撒網的比喻"]},{"n":45,"t":"天國又好像買賣人尋找好珠子，","notes":[]},{"n":46,"t":"遇見一顆重價的珠子，就去變賣他一切所有的，買了這顆珠子。","notes":[]},{"n":47,"t":"天國又好像網撒在海裏，聚攏各樣水族，","notes":[]},{"n":48,"t":"網既滿了，人就拉上岸來，坐下，揀好的收在器具裏，將不好的丟棄了。","notes":[]},{"n":49,"t":"世界的末了也要這樣。天使要出來，從義人中把惡人分別出來，","notes":[]},{"n":50,"t":"丟在火爐裏；在那裏必要哀哭切齒了。」","notes":[]},{"n":51,"t":"耶穌說：「這一切的話你們都明白了嗎？」他們說：「我們明白了。」","notes":[],"heads":["新舊的東西"]},{"n":52,"t":"他說：「凡文士受教作天國的門徒，就像一個家主從他庫裏拿出新舊的東西來。」","notes":[]},{"n":53,"t":"耶穌說完了這些比喻，就離開那裏，","notes":[],"heads":["拿撒勒人厭棄耶穌"]},{"n":54,"t":"來到自己的家鄉，在會堂裏教訓人，甚至他們都希奇，說：「這人從哪裏有這等智慧和異能呢？","notes":[]},{"n":55,"t":"這不是木匠的兒子嗎？他母親不是叫馬利亞嗎？他弟兄們不是叫雅各、約西 、 西門、猶大嗎？","notes":["有古卷：約瑟"]},{"n":56,"t":"他妹妹們不是都在我們這裏嗎？這人從哪裏有這一切的事呢？」","notes":[]},{"n":57,"t":"他們就厭棄他。耶穌對他們說：「大凡先知，除了本地本家之外，沒有不被人尊敬的。」","notes":["厭棄他：原文是因他跌倒"]},{"n":58,"t":"耶穌因為他們不信，就在那裏不多行異能了。","notes":[]}]},"14":{"heading":"施洗約翰的死","verses":[{"n":1,"t":"那時，分封的王希律聽見耶穌的名聲，","notes":[]},{"n":2,"t":"就對臣僕說：「這是施洗的約翰從死裏復活，所以這些異能從他裏面發出來。」","notes":[]},{"n":3,"t":"起先，希律為他兄弟腓力的妻子希羅底的緣故，把約翰拿住，鎖在監裏。","notes":[]},{"n":4,"t":"因為約翰曾對他說：「你娶這婦人是不合理的。」","notes":[]},{"n":5,"t":"希律就想要殺他，只是怕百姓，因為他們以約翰為先知。","notes":[]},{"n":6,"t":"到了希律的生日，希羅底的女兒在眾人面前跳舞，使希律歡喜。","notes":[]},{"n":7,"t":"希律就起誓，應許隨她所求的給她。","notes":[]},{"n":8,"t":"女兒被母親所使，就說：「請把施洗約翰的頭放在盤子裏，拿來給我。」","notes":[]},{"n":9,"t":"王便憂愁，但因他所起的誓，又因同席的人，就吩咐給她；","notes":[]},{"n":10,"t":"於是打發人去，在監裏斬了約翰，","notes":[]},{"n":11,"t":"把頭放在盤子裏，拿來給了女子；女子拿去給她母親。","notes":[]},{"n":12,"t":"約翰的門徒來，把屍首領去埋葬了，就去告訴耶穌。","notes":[]},{"n":13,"t":"耶穌聽見了，就上船從那裏獨自退到野地裏去。眾人聽見，就從各城裏步行跟隨他。","notes":[],"heads":["耶穌給五千人吃飽"]},{"n":14,"t":"耶穌出來，見有許多的人，就憐憫他們，治好了他們的病人。","notes":[]},{"n":15,"t":"天將晚的時候，門徒進前來，說：「這是野地，時候已經過了，請叫眾人散開，他們好往村子裏去，自己買吃的。」","notes":[]},{"n":16,"t":"耶穌說：「不用他們去，你們給他們吃吧！」","notes":[]},{"n":17,"t":"門徒說：「我們這裏只有五個餅，兩條魚。」","notes":[]},{"n":18,"t":"耶穌說：「拿過來給我。」","notes":[]},{"n":19,"t":"於是吩咐眾人坐在草地上，就拿著這五個餅，兩條魚，望著天祝福，擘開餅，遞給門徒，門徒又遞給眾人。","notes":[]},{"n":20,"t":"他們都吃，並且吃飽了，把剩下的零碎收拾起來，裝滿了十二個籃子。","notes":[]},{"n":21,"t":"吃的人，除了婦女孩子，約有五千。","notes":[]},{"n":22,"t":"耶穌隨即催門徒上船，先渡到那邊去，等他叫眾人散開。","notes":[],"heads":["耶穌在海面上行走"]},{"n":23,"t":"散了眾人以後，他就獨自上山去禱告。到了晚上，只有他一人在那裏。","notes":[]},{"n":24,"t":"那時船在海中，因風不順，被浪搖撼。","notes":[]},{"n":25,"t":"夜裏四更天，耶穌在海面上走，往門徒那裏去。","notes":[]},{"n":26,"t":"門徒看見他在海面上走，就驚慌了，說：「是個鬼怪！」便害怕，喊叫起來。","notes":[]},{"n":27,"t":"耶穌連忙對他們說：「你們放心，是我，不要怕！」","notes":[]},{"n":28,"t":"彼得說：「主，如果是你，請叫我從水面上走到你那裏去。」","notes":[]},{"n":29,"t":"耶穌說：「你來吧。」彼得就從船上下去，在水面上走，要到耶穌那裏去；","notes":[]},{"n":30,"t":"只因見風甚大，就害怕，將要沉下去，便喊著說：「主啊，救我！」","notes":[]},{"n":31,"t":"耶穌趕緊伸手拉住他，說：「你這小信的人哪，為甚麼疑惑呢？」","notes":[]},{"n":32,"t":"他們上了船，風就住了。","notes":[]},{"n":33,"t":"在船上的人都拜他，說：「你真是神的兒子了。」","notes":[]},{"n":34,"t":"他們過了海，來到革尼撒勒地方。","notes":[],"heads":["治好革尼撒勒的病人"]},{"n":35,"t":"那裏的人一認出是耶穌，就打發人到周圍地方去，把所有的病人帶到他那裏，","notes":[]},{"n":36,"t":"只求耶穌准他們摸他的衣裳繸子；摸著的人就都好了。","notes":[]}]},"15":{"heading":"古人的傳統","verses":[{"n":1,"t":"那時，有法利賽人和文士從耶路撒冷來見耶穌，說：","notes":[]},{"n":2,"t":"「你的門徒為甚麼犯古人的遺傳呢？因為吃飯的時候，他們不洗手。」","notes":[]},{"n":3,"t":"耶穌回答說：「你們為甚麼因著你們的遺傳犯神的誡命呢？","notes":[]},{"n":4,"t":"神說：『當孝敬父母』；又說：『咒罵父母的，必治死他。』","notes":[]},{"n":5,"t":"你們倒說：『無論何人對父母說：我所當奉給你的已經作了供獻，","notes":[]},{"n":6,"t":"他就可以不孝敬父母。』這就是你們藉著遺傳，廢了神的誡命。","notes":[]},{"n":7,"t":"假冒為善的人哪，以賽亞指著你們說的預言是不錯的。他說：","notes":[]},{"n":8,"t":"這百姓用嘴唇尊敬我，心卻遠離我；","notes":[]},{"n":9,"t":"他們將人的吩咐當作道理教導人，所以拜我也是枉然。」","notes":[]},{"n":10,"t":"耶穌就叫了眾人來，對他們說：「你們要聽，也要明白。","notes":[]},{"n":11,"t":"入口的不能污穢人，出口的乃能污穢人。」","notes":[]},{"n":12,"t":"當時，門徒進前來對他說：「法利賽人聽見這話，不服，你知道嗎？」","notes":["原文是跌倒"]},{"n":13,"t":"耶穌回答說：「凡栽種的物，若不是我天父栽種的，必要拔出來。","notes":[]},{"n":14,"t":"任憑他們吧！他們是瞎眼領路的；若是瞎子領瞎子，兩個人都要掉在坑裏。」","notes":[]},{"n":15,"t":"彼得對耶穌說：「請將這比喻講給我們聽。」","notes":[]},{"n":16,"t":"耶穌說：「你們到如今還不明白嗎？","notes":[]},{"n":17,"t":"豈不知凡入口的，是運到肚子裏，又落在茅廁裏嗎？","notes":[]},{"n":18,"t":"惟獨出口的，是從心裏發出來的，這才污穢人。","notes":[]},{"n":19,"t":"因為從心裏發出來的，有惡念、凶殺、姦淫、苟合、偷盜、妄證、謗讟。","notes":[]},{"n":20,"t":"這都是污穢人的；至於不洗手吃飯，那卻不污穢人。」","notes":[]},{"n":21,"t":"耶穌離開那裏，退到泰爾、西頓的境內去。","notes":[],"heads":["迦南婦人的信心"]},{"n":22,"t":"有一個迦南婦人，從那地方出來，喊著說：「主啊，大衛的子孫，可憐我！我女兒被鬼附得甚苦。」","notes":[]},{"n":23,"t":"耶穌卻一言不答。門徒進前來，求他說：「這婦人在我們後頭喊叫，請打發她走吧。」","notes":[]},{"n":24,"t":"耶穌說：「我奉差遣不過是到以色列家迷失的羊那裏去。」","notes":[]},{"n":25,"t":"那婦人來拜他，說：「主啊，幫助我！」","notes":[]},{"n":26,"t":"他回答說：「不好拿兒女的餅丟給狗吃。」","notes":[]},{"n":27,"t":"婦人說：「主啊，不錯；但是狗也吃牠主人桌子上掉下來的碎渣兒。」","notes":[]},{"n":28,"t":"耶穌說：「婦人，你的信心是大的！照你所要的，給你成全了吧。」從那時候，她女兒就好了。","notes":[]},{"n":29,"t":"耶穌離開那地方，來到靠近加利利的海邊，就上山坐下。","notes":[],"heads":["治好許多病人"]},{"n":30,"t":"有許多人到他那裏，帶著瘸子、瞎子、啞巴、有殘疾的，和好些別的病人，都放在他腳前；他就治好了他們。","notes":[]},{"n":31,"t":"甚至眾人都希奇；因為看見啞巴說話，殘疾的痊癒，瘸子行走，瞎子看見，他們就歸榮耀給以色列的神。","notes":[]},{"n":32,"t":"耶穌叫門徒來，說：「我憐憫這眾人；因為他們同我在這裏已經三天，也沒有吃的了。我不願意叫他們餓著回去，恐怕在路上困乏。」","notes":[],"heads":["耶穌給四千人吃飽"]},{"n":33,"t":"門徒說：「我們在這野地，哪裏有這麼多的餅叫這許多人吃飽呢？」","notes":[]},{"n":34,"t":"耶穌說：「你們有多少餅？」他們說：「有七個，還有幾條小魚。」","notes":[]},{"n":35,"t":"他就吩咐眾人坐在地上，","notes":[]},{"n":36,"t":"拿著這七個餅和幾條魚，祝謝了，擘開，遞給門徒；門徒又遞給眾人。","notes":[]},{"n":37,"t":"眾人都吃，並且吃飽了，收拾剩下的零碎，裝滿了七個筐子。","notes":[]},{"n":38,"t":"吃的人，除了婦女孩子，共有四千。","notes":[]},{"n":39,"t":"耶穌叫眾人散去，就上船，來到馬加丹的境界。","notes":[]}]},"16":{"heading":"求主顯個神蹟","verses":[{"n":1,"t":"法利賽人和撒都該人來試探耶穌，請他從天上顯個神蹟給他們看。","notes":[]},{"n":2,"t":"耶穌回答說：「晚上天發紅，你們就說：『天必要晴。』","notes":[]},{"n":3,"t":"早晨天發紅，又發黑，你們就說：『今日必有風雨。』你們知道分辨天上的氣色，倒不能分辨這時候的神蹟。","notes":[]},{"n":4,"t":"一個邪惡淫亂的世代求神蹟，除了約拿的神蹟以外，再沒有神蹟給他看。」耶穌就離開他們去了。","notes":[]},{"n":5,"t":"門徒渡到那邊去，忘了帶餅。","notes":[],"heads":["防備法利賽人和撒都該人的酵"]},{"n":6,"t":"耶穌對他們說：「你們要謹慎，防備法利賽人和撒都該人的酵。」","notes":[]},{"n":7,"t":"門徒彼此議論說：「這是因為我們沒有帶餅吧。」","notes":[]},{"n":8,"t":"耶穌看出來，就說：「你們這小信的人，為甚麼因為沒有餅彼此議論呢？","notes":[]},{"n":9,"t":"你們還不明白嗎？不記得那五個餅分給五千人、又收拾了多少籃子的零碎嗎？","notes":[]},{"n":10,"t":"也不記得那七個餅分給四千人、又收拾了多少筐子的零碎嗎？","notes":[]},{"n":11,"t":"我對你們說：『要防備法利賽人和撒都該人的酵』，這話不是指著餅說的，你們怎麼不明白呢？」","notes":[]},{"n":12,"t":"門徒這才曉得他說的不是叫他們防備餅的酵，乃是防備法利賽人和撒都該人的教訓。","notes":[]},{"n":13,"t":"耶穌到了凱撒利亞‧腓立比的境內，就問門徒說：「人說我－－人子是誰？」","notes":["有古卷沒有我字"],"heads":["彼得認耶穌為基督"]},{"n":14,"t":"他們說：「有人說是施洗的約翰；有人說是以利亞；又有人說是耶利米或是先知裏的一位。」","notes":[]},{"n":15,"t":"耶穌說：「你們說我是誰？」","notes":[]},{"n":16,"t":"西門‧彼得回答說：「你是基督，是永生神的兒子。」","notes":[]},{"n":17,"t":"耶穌對他說：「西門‧巴‧約拿，你是有福的！因為這不是屬血肉的指示你的，乃是我在天上的父指示的。","notes":[]},{"n":18,"t":"我還告訴你，你是彼得，我要把我的教會建造在這磐石上；陰間的權柄不能勝過他。","notes":["權柄：原文是門"]},{"n":19,"t":"我要把天國的鑰匙給你，凡你在地上所捆綁的，在天上也要捆綁；凡你在地上所釋放的，在天上也要釋放。」","notes":[]},{"n":20,"t":"當下，耶穌囑咐門徒，不可對人說他是基督。","notes":[]},{"n":21,"t":"從此，耶穌才指示門徒，他必須上耶路撒冷去，受長老、祭司長、文士許多的苦，並且被殺，第三日復活。","notes":[],"heads":["耶穌預言受難和復活"]},{"n":22,"t":"彼得就拉著他，勸他說：「主啊，萬不可如此！這事必不臨到你身上。」","notes":[]},{"n":23,"t":"耶穌轉過來，對彼得說：「撒但，退我後邊去吧！你是絆我腳的；因為你不體貼神的意思，只體貼人的意思。」","notes":[]},{"n":24,"t":"於是耶穌對門徒說：「若有人要跟從我，就當捨己，背起他的十字架來跟從我。","notes":[]},{"n":25,"t":"因為，凡要救自己生命的，必喪掉生命；凡為我喪掉生命的，必得著生命。","notes":["生命：或譯靈魂；下同"]},{"n":26,"t":"人若賺得全世界，賠上自己的生命，有甚麼益處呢？人還能拿甚麼換生命呢？","notes":[]},{"n":27,"t":"人子要在他父的榮耀裏，同著眾使者降臨；那時候，他要照各人的行為報應各人。","notes":[]},{"n":28,"t":"我實在告訴你們，站在這裏的，有人在沒嘗死味以前必看見人子降臨在他的國裏。」","notes":[]}]},"17":{"heading":"耶穌改變形像","verses":[{"n":1,"t":"過了六天，耶穌帶著彼得、雅各，和雅各的兄弟約翰，暗暗地上了高山，","notes":[]},{"n":2,"t":"就在他們面前變了形像，臉面明亮如日頭，衣裳潔白如光。","notes":[]},{"n":3,"t":"忽然，有摩西、以利亞向他們顯現，同耶穌說話。","notes":[]},{"n":4,"t":"彼得對耶穌說：「主啊，我們在這裏真好！你若願意，我就在這裏搭三座棚，一座為你，一座為摩西，一座為以利亞。」","notes":[]},{"n":5,"t":"說話之間，忽然有一朵光明的雲彩遮蓋他們，且有聲音從雲彩裏出來，說：「這是我的愛子，我所喜悅的。你們要聽他！」","notes":[]},{"n":6,"t":"門徒聽見，就俯伏在地，極其害怕。","notes":[]},{"n":7,"t":"耶穌進前來，摸他們，說：「起來，不要害怕！」","notes":[]},{"n":8,"t":"他們舉目不見一人，只見耶穌在那裏。","notes":[]},{"n":9,"t":"下山的時候，耶穌吩咐他們說：「人子還沒有從死裏復活，你們不要將所看見的告訴人。」","notes":[]},{"n":10,"t":"門徒問耶穌說：「文士為甚麼說以利亞必須先來？」","notes":[]},{"n":11,"t":"耶穌回答說：「以利亞固然先來，並要復興萬事；","notes":[]},{"n":12,"t":"只是我告訴你們，以利亞已經來了，人卻不認識他，竟任意待他。人子也將要這樣受他們的害。」","notes":[]},{"n":13,"t":"門徒這才明白耶穌所說的是指著施洗的約翰。","notes":[]},{"n":14,"t":"耶穌和門徒到了眾人那裏，有一個人來見耶穌，跪下，","notes":[],"heads":["治好被鬼附身的孩子"]},{"n":15,"t":"說：「主啊，憐憫我的兒子！他害癲癇的病很苦，屢次跌在火裏，屢次跌在水裏。","notes":[]},{"n":16,"t":"我帶他到你門徒那裏，他們卻不能醫治他。」","notes":[]},{"n":17,"t":"耶穌說：「噯！這又不信又悖謬的世代啊，我在你們這裏要到幾時呢？我忍耐你們要到幾時呢？把他帶到我這裏來吧！」","notes":[]},{"n":18,"t":"耶穌斥責那鬼，鬼就出來；從此孩子就痊癒了。","notes":[]},{"n":19,"t":"門徒暗暗地到耶穌跟前，說：「我們為甚麼不能趕出那鬼呢？」","notes":[]},{"n":20,"t":"耶穌說：「是因你們的信心小。我實在告訴你們，你們若有信心，像一粒芥菜種，就是對這座山說：『你從這邊挪到那邊』，它也必挪去；並且你們沒有一件不能做的事了。","notes":[]},{"n":21,"t":"至於這一類的鬼，若不禱告、禁食，他就不出來 。」","notes":["或譯：不能趕他出來"]},{"n":22,"t":"他們還住在加利利的時候，耶穌對門徒說：「人子將要被交在人手裏。","notes":[],"heads":["耶穌第二次預言受難和復活"]},{"n":23,"t":"他們要殺害他，第三日他要復活。」門徒就大大地憂愁。","notes":[]},{"n":24,"t":"到了迦百農，有收丁稅的人來見彼得，說：「你們的先生不納丁稅嗎？」","notes":["丁稅約有半塊錢"],"heads":["繳納殿稅"]},{"n":25,"t":"彼得說：「納。」他進了屋子，耶穌先向他說：「西門，你的意思如何？世上的君王向誰征收關稅、丁稅？是向自己的兒子呢？是向外人呢？」","notes":[]},{"n":26,"t":"彼得說：「是向外人。」耶穌說：「既然如此，兒子就可以免稅了。","notes":[]},{"n":27,"t":"但恐怕觸犯他們，你且往海邊去釣魚，把先釣上來的魚拿起來，開了牠的口，必得一塊錢，可以拿去給他們，作你我的稅銀。」","notes":["觸犯：原文是絆倒"]}]},"18":{"heading":"天國裏最偉大的人","verses":[{"n":1,"t":"當時，門徒進前來，問耶穌說：「天國裏誰是最大的？」","notes":[]},{"n":2,"t":"耶穌便叫一個小孩子來，使他站在他們當中，","notes":[]},{"n":3,"t":"說：「我實在告訴你們，你們若不回轉，變成小孩子的樣式，斷不得進天國。","notes":[]},{"n":4,"t":"所以，凡自己謙卑像這小孩子的，他在天國裏就是最大的。","notes":[]},{"n":5,"t":"凡為我的名接待一個像這小孩子的，就是接待我。」","notes":[]},{"n":6,"t":"「凡使這信我的一個小子跌倒的，倒不如把大磨石拴在這人的頸項上，沉在深海裏。","notes":[],"heads":["罪的誘惑"]},{"n":7,"t":"這世界有禍了，因為將人絆倒；絆倒人的事是免不了的，但那絆倒人的有禍了！","notes":[]},{"n":8,"t":"倘若你一隻手，或是一隻腳，叫你跌倒，就砍下來丟掉。你缺一隻手，或是一隻腳，進入永生，強如有兩手兩腳被丟在永火裏。","notes":[]},{"n":9,"t":"倘若你一隻眼叫你跌倒，就把它剜出來丟掉。你只有一隻眼進入永生，強如有兩隻眼被丟在地獄的火裏。」","notes":[]},{"n":10,"t":"「你們要小心，不可輕看這小子裏的一個；我告訴你們，他們的使者在天上，常見我天父的面。","notes":["有古卷加：11人子來，為要拯救失喪的人。"],"heads":["迷羊的比喻"]},{"n":12,"t":"一個人若有一百隻羊，一隻走迷了路，你們的意思如何？他豈不撇下這九十九隻，往山裏去找那隻迷路的羊嗎？","notes":[]},{"n":13,"t":"若是找著了，我實在告訴你們，他為這一隻羊歡喜，比為那沒有迷路的九十九隻歡喜還大呢！","notes":[]},{"n":14,"t":"你們在天上的父也是這樣，不願意這小子裏失喪一個。」","notes":[]},{"n":15,"t":"「倘若你的弟兄得罪你，你就去，趁著只有他和你在一處的時候，指出他的錯來。他若聽你，你便得了你的弟兄；","notes":[],"heads":["如何對待犯過錯的弟兄"]},{"n":16,"t":"他若不聽，你就另外帶一兩個人同去，要憑兩三個人的口作見證，句句都可定準。","notes":[]},{"n":17,"t":"若是不聽他們，就告訴教會；若是不聽教會，就看他像外邦人和稅吏一樣。","notes":[]},{"n":18,"t":"「我實在告訴你們，凡你們在地上所捆綁的，在天上也要捆綁；凡你們在地上所釋放的，在天上也要釋放。","notes":[]},{"n":19,"t":"我又告訴你們，若是你們中間有兩個人在地上同心合意地求甚麼事，我在天上的父必為他們成全。","notes":[]},{"n":20,"t":"因為無論在哪裏，有兩三個人奉我的名聚會，那裏就有我在他們中間。」","notes":[]},{"n":21,"t":"那時，彼得進前來，對耶穌說：「主啊，我弟兄得罪我，我當饒恕他幾次呢？到七次可以嗎？」","notes":[],"heads":["不饒恕人的惡僕"]},{"n":22,"t":"耶穌說：「我對你說，不是到七次，乃是到七十個七次。","notes":[]},{"n":23,"t":"天國好像一個王要和他僕人算帳。","notes":[]},{"n":24,"t":"才算的時候，有人帶了一個欠一千萬銀子的來。","notes":[]},{"n":25,"t":"因為他沒有甚麼償還之物，主人吩咐把他和他妻子兒女，並一切所有的都賣了償還。","notes":[]},{"n":26,"t":"那僕人就俯伏拜他，說：『主啊，寬容我，將來我都要還清。』","notes":[]},{"n":27,"t":"那僕人的主人就動了慈心，把他釋放了，並且免了他的債。","notes":[]},{"n":28,"t":"「那僕人出來，遇見他的一個同伴欠他十兩銀子，便揪著他，掐住他的喉嚨，說：『你把所欠的還我！』","notes":[]},{"n":29,"t":"他的同伴就俯伏央求他，說：『寬容我吧，將來我必還清。』","notes":[]},{"n":30,"t":"他不肯，竟去把他下在監裏，等他還了所欠的債。","notes":[]},{"n":31,"t":"眾同伴看見他所做的事就甚憂愁，去把這事都告訴了主人。","notes":[]},{"n":32,"t":"於是主人叫了他來，對他說：『你這惡奴才！你央求我，我就把你所欠的都免了，","notes":[]},{"n":33,"t":"你不應當憐恤你的同伴，像我憐恤你嗎？』","notes":[]},{"n":34,"t":"主人就大怒，把他交給掌刑的，等他還清了所欠的債。","notes":[]},{"n":35,"t":"你們各人若不從心裏饒恕你的弟兄，我天父也要這樣待你們了。」","notes":[]}]},"19":{"heading":"休妻的問題","verses":[{"n":1,"t":"耶穌說完了這些話，就離開加利利，來到猶太的境界約旦河外。","notes":[]},{"n":2,"t":"有許多人跟著他，他就在那裏把他們的病人治好了。","notes":[]},{"n":3,"t":"有法利賽人來試探耶穌，說：「人無論甚麼緣故都可以休妻嗎？」","notes":[]},{"n":4,"t":"耶穌回答說：「那起初造人的，是造男造女，","notes":[]},{"n":5,"t":"並且說：『因此，人要離開父母，與妻子連合，二人成為一體。』這經你們沒有念過嗎？","notes":[]},{"n":6,"t":"既然如此，夫妻不再是兩個人，乃是一體的了。所以，神配合的，人不可分開。」","notes":[]},{"n":7,"t":"法利賽人說：「這樣，摩西為甚麼吩咐給妻子休書，就可以休她呢？」","notes":[]},{"n":8,"t":"耶穌說：「摩西因為你們的心硬，所以許你們休妻，但起初並不是這樣。","notes":[]},{"n":9,"t":"我告訴你們，凡休妻另娶的，若不是為淫亂的緣故，就是犯姦淫了；有人娶那被休的婦人，也是犯姦淫了。」","notes":[]},{"n":10,"t":"門徒對耶穌說：「人和妻子既是這樣，倒不如不娶。」","notes":[]},{"n":11,"t":"耶穌說：「這話不是人都能領受的，惟獨賜給誰，誰才能領受。","notes":[]},{"n":12,"t":"因為有生來是閹人，也有被人閹的，並有為天國的緣故自閹的。這話誰能領受就可以領受。」","notes":[]},{"n":13,"t":"那時，有人帶著小孩子來見耶穌，要耶穌給他們按手禱告，門徒就責備那些人。","notes":[],"heads":["耶穌為小孩祝福"]},{"n":14,"t":"耶穌說：「讓小孩子到我這裏來，不要禁止他們；因為在天國的，正是這樣的人。」","notes":[]},{"n":15,"t":"耶穌給他們按手，就離開那地方去了。","notes":[]},{"n":16,"t":"有一個人來見耶穌，說：「夫子，我該做甚麼善事才能得永生？」","notes":["有古卷：良善的夫子"],"heads":["少年財主"]},{"n":17,"t":"耶穌對他說：「你為甚麼以善事問我呢？只有一位是善的。你若要進入永生，就當遵守誡命。」","notes":["有古卷：你為甚麼稱我是良善的？除了神以外，沒有一個良善的"]},{"n":18,"t":"他說：「甚麼誡命？」耶穌說：「就是不可殺人；不可姦淫；不可偷盜；不可作假見證；","notes":[]},{"n":19,"t":"當孝敬父母；又當愛人如己。」","notes":[]},{"n":20,"t":"那少年人說：「這一切我都遵守了，還缺少甚麼呢？」","notes":[]},{"n":21,"t":"耶穌說：「你若願意作完全人，可去變賣你所有的，分給窮人，就必有財寶在天上；你還要來跟從我。」","notes":[]},{"n":22,"t":"那少年人聽見這話，就憂憂愁愁地走了，因為他的產業很多。","notes":[]},{"n":23,"t":"耶穌對門徒說：「我實在告訴你們，財主進天國是難的。","notes":[]},{"n":24,"t":"我又告訴你們，駱駝穿過針的眼，比財主進神的國還容易呢！」","notes":[]},{"n":25,"t":"門徒聽見這話，就希奇得很，說：「這樣誰能得救呢？」","notes":[]},{"n":26,"t":"耶穌看著他們，說：「在人這是不能的，在神凡事都能。」","notes":[]},{"n":27,"t":"彼得就對他說：「看哪，我們已經撇下所有的跟從你，將來我們要得甚麼呢？」","notes":[]},{"n":28,"t":"耶穌說：「我實在告訴你們，你們這跟從我的人，到復興的時候，人子坐在他榮耀的寶座上，你們也要坐在十二個寶座上，審判以色列十二個支派。","notes":[]},{"n":29,"t":"凡為我的名撇下房屋，或是弟兄、姊妹、父親、母親、兒女、田地的，必要得著百倍，並且承受永生。","notes":["有古卷加：妻子、"]},{"n":30,"t":"然而，有許多在前的，將要在後；在後的，將要在前。」","notes":[]}]},"20":{"heading":"葡萄園的比喻","verses":[{"n":1,"t":"「因為天國好像家主清早去雇人進他的葡萄園做工，","notes":[]},{"n":2,"t":"和工人講定一天一錢銀子，就打發他們進葡萄園去。","notes":[]},{"n":3,"t":"約在巳初出去，看見市上還有閒站的人，","notes":[]},{"n":4,"t":"就對他們說：『你們也進葡萄園去，所當給的，我必給你們。』他們也進去了。","notes":[]},{"n":5,"t":"約在午正和申初又出去，也是這樣行。","notes":[]},{"n":6,"t":"約在酉初出去，看見還有人站在那裏，就問他們說：『你們為甚麼整天在這裏閒站呢？』","notes":[]},{"n":7,"t":"他們說：『因為沒有人雇我們。』他說：『你們也進葡萄園去。』","notes":[]},{"n":8,"t":"到了晚上，園主對管事的說：『叫工人都來，給他們工錢，從後來的起，到先來的為止。』","notes":[]},{"n":9,"t":"約在酉初雇的人來了，各人得了一錢銀子。","notes":[]},{"n":10,"t":"及至那先雇的來了，他們以為必要多得；誰知也是各得一錢。","notes":[]},{"n":11,"t":"他們得了，就埋怨家主說：","notes":[]},{"n":12,"t":"『我們整天勞苦受熱，那後來的只做了一小時，你竟叫他們和我們一樣嗎？』","notes":[]},{"n":13,"t":"家主回答其中的一人說：『朋友，我不虧負你，你與我講定的不是一錢銀子嗎？","notes":[]},{"n":14,"t":"拿你的走吧！我給那後來的和給你一樣，這是我願意的。","notes":[]},{"n":15,"t":"我的東西難道不可隨我的意思用嗎？因為我作好人，你就紅了眼嗎？』","notes":[]},{"n":16,"t":"這樣，那在後的，將要在前；在前的，將要在後了。 」","notes":["有古卷加：因為被召的人多，選上的人少。"]},{"n":17,"t":"耶穌上耶路撒冷去的時候，在路上把十二個門徒帶到一邊，對他們說：","notes":[],"heads":["耶穌第三次預言受難和復活"]},{"n":18,"t":"「看哪，我們上耶路撒冷去，人子要被交給祭司長和文士。他們要定他死罪，","notes":[]},{"n":19,"t":"又交給外邦人，將他戲弄，鞭打，釘在十字架上；第三日他要復活。」","notes":[]},{"n":20,"t":"那時，西庇太兒子的母親同她兩個兒子上前來拜耶穌，求他一件事。","notes":[],"heads":["母親的請求"]},{"n":21,"t":"耶穌說：「你要甚麼呢？」她說：「願你叫我這兩個兒子在你國裏，一個坐在你右邊，一個坐在你左邊。」","notes":[]},{"n":22,"t":"耶穌回答說：「你們不知道所求的是甚麼；我將要喝的杯，你們能喝嗎？」他們說：「我們能。」","notes":[]},{"n":23,"t":"耶穌說：「我所喝的杯，你們必要喝；只是坐在我的左右，不是我可以賜的，乃是我父為誰預備的，就賜給誰。」","notes":[]},{"n":24,"t":"那十個門徒聽見，就惱怒他們弟兄二人。","notes":[]},{"n":25,"t":"耶穌叫了他們來，說：「你們知道外邦人有君王為主治理他們，有大臣操權管束他們。","notes":[]},{"n":26,"t":"只是在你們中間，不可這樣；你們中間誰願為大，就必作你們的用人；","notes":[]},{"n":27,"t":"誰願為首，就必作你們的僕人。","notes":[]},{"n":28,"t":"正如人子來，不是要受人的服事，乃是要服事人，並且要捨命，作多人的贖價。」","notes":[]},{"n":29,"t":"他們出耶利哥的時候，有極多的人跟隨他。","notes":[],"heads":["治好兩個瞎子"]},{"n":30,"t":"有兩個瞎子坐在路旁，聽說是耶穌經過，就喊著說：「主啊，大衛的子孫，可憐我們吧！」","notes":[]},{"n":31,"t":"眾人責備他們，不許他們作聲；他們卻越發喊著說：「主啊，大衛的子孫，可憐我們吧！」","notes":[]},{"n":32,"t":"耶穌就站住，叫他們來，說：「要我為你們做甚麼？」","notes":[]},{"n":33,"t":"他們說：「主啊，要我們的眼睛能看見！」","notes":[]},{"n":34,"t":"耶穌就動了慈心，把他們的眼睛一摸，他們立刻看見，就跟從了耶穌。","notes":[]}]},"21":{"heading":"光榮地進耶路撒冷","verses":[{"n":1,"t":"耶穌和門徒將近耶路撒冷，到了伯法其，在橄欖山那裏。","notes":[]},{"n":2,"t":"耶穌就打發兩個門徒，對他們說：「你們往對面村子裏去，必看見一匹驢拴在那裏，還有驢駒同在一處；你們解開，牽到我這裏來。","notes":[]},{"n":3,"t":"若有人對你們說甚麼，你們就說：『主要用牠。』那人必立時讓你們牽來。","notes":[]},{"n":4,"t":"這事成就是要應驗先知的話，說：","notes":[]},{"n":5,"t":"要對錫安的居民說：看哪，你的王來到你這裏，是溫柔的，又騎著驢，就是騎著驢駒子。」","notes":["原文是女子"]},{"n":6,"t":"門徒就照耶穌所吩咐的去行，","notes":[]},{"n":7,"t":"牽了驢和驢駒來，把自己的衣服搭在上面，耶穌就騎上。","notes":[]},{"n":8,"t":"眾人多半把衣服鋪在路上；還有人砍下樹枝來鋪在路上。","notes":[]},{"n":9,"t":"前行後隨的眾人喊著說：和散那歸於大衛的子孫！奉主名來的是應當稱頌的！高高在上和散那！","notes":["原有求救的意思，在此是稱頌的話"]},{"n":10,"t":"耶穌既進了耶路撒冷，合城都驚動了，說：「這是誰？」","notes":[]},{"n":11,"t":"眾人說：「這是加利利拿撒勒的先知耶穌。」","notes":[]},{"n":12,"t":"耶穌進了神的殿，趕出殿裏一切做買賣的人，推倒兌換銀錢之人的桌子，和賣鴿子之人的凳子，","notes":[],"heads":["潔淨聖殿"]},{"n":13,"t":"對他們說：「經上記著說：我的殿必稱為禱告的殿，你們倒使它成為賊窩了。」","notes":[]},{"n":14,"t":"在殿裏有瞎子、瘸子到耶穌跟前，他就治好了他們。","notes":[]},{"n":15,"t":"祭司長和文士看見耶穌所行的奇事，又見小孩子在殿裏喊著說：「和散那歸於大衛的子孫！」就甚惱怒，","notes":[]},{"n":16,"t":"對他說：「這些人所說的，你聽見了嗎？」耶穌說：「是的。經上說『你從嬰孩和吃奶的口中完全了讚美』的話，你們沒有念過嗎？」","notes":[]},{"n":17,"t":"於是離開他們，出城到伯大尼去，在那裏住宿。","notes":[]},{"n":18,"t":"早晨回城的時候，他餓了，","notes":[],"heads":["咒詛無花果樹"]},{"n":19,"t":"看見路旁有一棵無花果樹，就走到跟前，在樹上找不著甚麼，不過有葉子，就對樹說：「從今以後，你永不結果子。」那無花果樹就立刻枯乾了。","notes":[]},{"n":20,"t":"門徒看見了，便希奇說：「無花果樹怎麼立刻枯乾了呢？」","notes":[]},{"n":21,"t":"耶穌回答說：「我實在告訴你們，你們若有信心，不疑惑，不但能行無花果樹上所行的事，就是對這座山說：『你挪開此地，投在海裏！』也必成就。","notes":[]},{"n":22,"t":"你們禱告，無論求甚麼，只要信，就必得著。」","notes":[]},{"n":23,"t":"耶穌進了殿，正教訓人的時候，祭司長和民間的長老來問他說：「你仗著甚麼權柄做這些事？給你這權柄的是誰呢？」","notes":[],"heads":["質問耶穌的權柄"]},{"n":24,"t":"耶穌回答說：「我也要問你們一句話，你們若告訴我，我就告訴你們我仗著甚麼權柄做這些事。","notes":[]},{"n":25,"t":"約翰的洗禮是從哪裏來的？是從天上來的？是從人間來的呢？」他們彼此商議說：「我們若說『從天上來』，他必對我們說：『這樣，你們為甚麼不信他呢？』","notes":[]},{"n":26,"t":"若說『從人間來』，我們又怕百姓，因為他們都以約翰為先知。」","notes":[]},{"n":27,"t":"於是回答耶穌說：「我們不知道。」耶穌說：「我也不告訴你們我仗著甚麼權柄做這些事。」","notes":[]},{"n":28,"t":"又說：「一個人有兩個兒子。他來對大兒子說：『我兒，你今天到葡萄園裏去做工。』","notes":[],"heads":["兩個兒子的比喻"]},{"n":29,"t":"他回答說：『我不去』，以後自己懊悔，就去了。","notes":[]},{"n":30,"t":"又來對小兒子也是這樣說。他回答說：『父啊，我去』，他卻不去。","notes":[]},{"n":31,"t":"你們想，這兩個兒子是哪一個遵行父命呢？」他們說：「大兒子。」耶穌說：「我實在告訴你們，稅吏和娼妓倒比你們先進神的國。","notes":[]},{"n":32,"t":"因為約翰遵著義路到你們這裏來，你們卻不信他；稅吏和娼妓倒信他。你們看見了，後來還是不懊悔去信他。」","notes":[]},{"n":33,"t":"「你們再聽一個比喻：有個家主栽了一個葡萄園，周圍圈上籬笆，裏面挖了一個壓酒池，蓋了一座樓，租給園戶，就往外國去了。","notes":[],"heads":["凶惡園戶的比喻"]},{"n":34,"t":"收果子的時候近了，就打發僕人到園戶那裏去收果子。","notes":[]},{"n":35,"t":"園戶拿住僕人，打了一個，殺了一個，用石頭打死一個。","notes":[]},{"n":36,"t":"主人又打發別的僕人去，比先前更多；園戶還是照樣待他們。","notes":[]},{"n":37,"t":"後來打發他的兒子到他們那裏去，意思說：『他們必尊敬我的兒子。』","notes":[]},{"n":38,"t":"不料，園戶看見他兒子，就彼此說：『這是承受產業的。來吧，我們殺他，佔他的產業！』","notes":[]},{"n":39,"t":"他們就拿住他，推出葡萄園外，殺了。","notes":[]},{"n":40,"t":"園主來的時候要怎樣處治這些園戶呢？」","notes":[]},{"n":41,"t":"他們說：「要下毒手除滅那些惡人，將葡萄園另租給那按著時候交果子的園戶。」","notes":[]},{"n":42,"t":"耶穌說：「經上寫著：匠人所棄的石頭已作了房角的頭塊石頭。這是主所做的，在我們眼中看為希奇。這經你們沒有念過嗎？","notes":[]},{"n":43,"t":"所以我告訴你們，神的國必從你們奪去，賜給那能結果子的百姓。","notes":[]},{"n":44,"t":"誰掉在這石頭上，必要跌碎；這石頭掉在誰的身上，就要把誰砸得稀爛。」","notes":[]},{"n":45,"t":"祭司長和法利賽人聽見他的比喻，就看出他是指著他們說的。","notes":[]},{"n":46,"t":"他們想要捉拿他，只是怕眾人，因為眾人以他為先知。","notes":[]}]},"22":{"heading":"喜筵的比喻","verses":[{"n":1,"t":"耶穌又用比喻對他們說：","notes":[]},{"n":2,"t":"「天國好比一個王為他兒子擺設娶親的筵席，","notes":[]},{"n":3,"t":"就打發僕人去，請那些被召的人來赴席，他們卻不肯來。","notes":[]},{"n":4,"t":"王又打發別的僕人，說：『你們告訴那被召的人，我的筵席已經預備好了，牛和肥畜已經宰了，各樣都齊備，請你們來赴席。』","notes":[]},{"n":5,"t":"那些人不理就走了；一個到自己田裏去；一個做買賣去；","notes":[]},{"n":6,"t":"其餘的拿住僕人，凌辱他們，把他們殺了。","notes":[]},{"n":7,"t":"王就大怒，發兵除滅那些兇手，燒毀他們的城。","notes":[]},{"n":8,"t":"於是對僕人說：『喜筵已經齊備，只是所召的人不配。","notes":[]},{"n":9,"t":"所以你們要往岔路口上去，凡遇見的，都召來赴席。』","notes":[]},{"n":10,"t":"那些僕人就出去，到大路上，凡遇見的，不論善惡都召聚了來，筵席上就坐滿了客。","notes":[]},{"n":11,"t":"王進來觀看賓客，見那裏有一個沒有穿禮服的，","notes":[]},{"n":12,"t":"就對他說：『朋友，你到這裏來怎麼不穿禮服呢？』那人無言可答。","notes":[]},{"n":13,"t":"於是王對使喚的人說：『捆起他的手腳來，把他丟在外邊的黑暗裏；在那裏必要哀哭切齒了。』","notes":[]},{"n":14,"t":"因為被召的人多，選上的人少。」","notes":[]},{"n":15,"t":"當時，法利賽人出去商議，怎樣就著耶穌的話陷害他，","notes":[],"heads":["納稅給凱撒的問題"]},{"n":16,"t":"就打發他們的門徒同希律黨的人去見耶穌，說：「夫子，我們知道你是誠實人，並且誠誠實實傳神的道，甚麼人你都不徇情面，因為你不看人的外貌。","notes":[]},{"n":17,"t":"請告訴我們，你的意見如何？納稅給凱撒可以不可以？」","notes":[]},{"n":18,"t":"耶穌看出他們的惡意，就說：「假冒為善的人哪，為甚麼試探我？","notes":[]},{"n":19,"t":"拿一個上稅的錢給我看！」他們就拿一個銀錢來給他。","notes":[]},{"n":20,"t":"耶穌說：「這像和這號是誰的？」","notes":[]},{"n":21,"t":"他們說：「是凱撒的。」耶穌說：「這樣，凱撒的物當歸給凱撒；神的物當歸給神。」","notes":[]},{"n":22,"t":"他們聽見就希奇，離開他走了。","notes":[]},{"n":23,"t":"撒都該人常說沒有復活的事。那天，他們來問耶穌說：","notes":[],"heads":["復活的問題"]},{"n":24,"t":"「夫子，摩西說：『人若死了，沒有孩子，他兄弟當娶他的妻，為哥哥生子立後。』","notes":[]},{"n":25,"t":"從前，在我們這裏有弟兄七人，第一個娶了妻，死了，沒有孩子，撇下妻子給兄弟。","notes":[]},{"n":26,"t":"第二、第三，直到第七個，都是如此。","notes":[]},{"n":27,"t":"末後，婦人也死了。","notes":[]},{"n":28,"t":"這樣，當復活的時候，她是七個人中哪一個的妻子呢？因為他們都娶過她。」","notes":[]},{"n":29,"t":"耶穌回答說：「你們錯了；因為不明白聖經，也不曉得神的大能。","notes":[]},{"n":30,"t":"當復活的時候，人也不娶也不嫁，乃像天上的使者一樣。","notes":[]},{"n":31,"t":"論到死人復活，神在經上向你們所說的，你們沒有念過嗎？","notes":[]},{"n":32,"t":"他說：『我是亞伯拉罕的神，以撒的神，雅各的神。』神不是死人的神，乃是活人的神。」","notes":[]},{"n":33,"t":"眾人聽見這話，就希奇他的教訓。","notes":[]},{"n":34,"t":"法利賽人聽見耶穌堵住了撒都該人的口，他們就聚集。","notes":[],"heads":["最大的誡命"]},{"n":35,"t":"內中有一個人是律法師，要試探耶穌，就問他說：","notes":[]},{"n":36,"t":"「夫子，律法上的誡命，哪一條是最大的呢？」","notes":[]},{"n":37,"t":"耶穌對他說：「你要盡心、盡性、盡意愛主－你的神。","notes":[]},{"n":38,"t":"這是誡命中的第一，且是最大的。","notes":[]},{"n":39,"t":"其次也相倣，就是要愛人如己。","notes":[]},{"n":40,"t":"這兩條誡命是律法和先知一切道理的總綱。」","notes":[]},{"n":41,"t":"法利賽人聚集的時候，耶穌問他們說：","notes":[],"heads":["大衛子孫的問題"]},{"n":42,"t":"「論到基督，你們的意見如何？他是誰的子孫呢？」他們回答說：「是大衛的子孫。」","notes":[]},{"n":43,"t":"耶穌說：「這樣，大衛被聖靈感動，怎麼還稱他為主，說：","notes":[]},{"n":44,"t":"主對我主說：你坐在我的右邊，等我把你仇敵放在你的腳下。","notes":[]},{"n":45,"t":"大衛既稱他為主，他怎麼又是大衛的子孫呢？」","notes":[]},{"n":46,"t":"他們沒有一個人能回答一言。從那日以後，也沒有人敢再問他甚麼。","notes":[]}]},"23":{"heading":"譴責文士和法利賽人","verses":[{"n":1,"t":"那時，耶穌對眾人和門徒講論，","notes":[]},{"n":2,"t":"說：「文士和法利賽人坐在摩西的位上，","notes":[]},{"n":3,"t":"凡他們所吩咐你們的，你們都要謹守遵行。但不要效法他們的行為；因為他們能說，不能行。","notes":[]},{"n":4,"t":"他們把難擔的重擔捆起來，擱在人的肩上，但自己一個指頭也不肯動。","notes":[]},{"n":5,"t":"他們一切所做的事都是要叫人看見，所以將佩戴的經文做寬了，衣裳的繸子做長了，","notes":[]},{"n":6,"t":"喜愛筵席上的首座，會堂裏的高位，","notes":[]},{"n":7,"t":"又喜愛人在街市上問他安，稱呼他拉比 。","notes":["拉比就是夫子"]},{"n":8,"t":"但你們不要受拉比的稱呼，因為只有一位是你們的夫子；你們都是弟兄。","notes":[]},{"n":9,"t":"也不要稱呼地上的人為父，因為只有一位是你們的父，就是在天上的父。","notes":[]},{"n":10,"t":"也不要受師尊的稱呼，因為只有一位是你們的師尊，就是基督。","notes":[]},{"n":11,"t":"你們中間誰為大，誰就要作你們的用人。","notes":[]},{"n":12,"t":"凡自高的，必降為卑；自卑的，必升為高。","notes":[]},{"n":13,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們正當人前，把天國的門關了，自己不進去，正要進去的人，你們也不容他們進去。","notes":["有古卷加：14你們這假冒為善的文士和法利賽人有禍了！因為你們侵吞寡婦的家產，假意做很長的禱告，所以要受更重的刑罰。"]},{"n":15,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們走遍洋海陸地，勾引一個人入教，既入了教，卻使他作地獄之子，比你們還加倍。","notes":[]},{"n":16,"t":"「你們這瞎眼領路的有禍了！你們說：『凡指著殿起誓的，這算不得甚麼；只是凡指著殿中金子起誓的，他就該謹守。』","notes":[]},{"n":17,"t":"你們這無知瞎眼的人哪，甚麼是大的？是金子呢？還是叫金子成聖的殿呢？","notes":[]},{"n":18,"t":"你們又說：『凡指著壇起誓的，這算不得甚麼；只是凡指著壇上禮物起誓的，他就該謹守。』","notes":[]},{"n":19,"t":"你們這瞎眼的人哪，甚麼是大的？是禮物呢？還是叫禮物成聖的壇呢？","notes":[]},{"n":20,"t":"所以，人指著壇起誓，就是指著壇和壇上一切所有的起誓；","notes":[]},{"n":21,"t":"人指著殿起誓，就是指著殿和那住在殿裏的起誓；","notes":[]},{"n":22,"t":"人指著天起誓，就是指著神的寶座和那坐在上面的起誓。","notes":[]},{"n":23,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們將薄荷、茴香、芹菜獻上十分之一，那律法上更重的事，就是公義、憐憫、信實，反倒不行了。這更重的是你們當行的；那也是不可不行的。","notes":[]},{"n":24,"t":"你們這瞎眼領路的，蠓蟲你們就濾出來，駱駝你們倒吞下去。","notes":[]},{"n":25,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們洗淨杯盤的外面，裏面卻盛滿了勒索和放蕩。","notes":[]},{"n":26,"t":"你這瞎眼的法利賽人，先洗淨杯盤的裏面，好叫外面也乾淨了。","notes":[]},{"n":27,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們好像粉飾的墳墓，外面好看，裏面卻裝滿了死人的骨頭和一切的污穢。","notes":[]},{"n":28,"t":"你們也是如此，在人前，外面顯出公義來，裏面卻裝滿了假善和不法的事。","notes":[]},{"n":29,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們建造先知的墳，修飾義人的墓，說：","notes":[]},{"n":30,"t":"『若是我們在我們祖宗的時候，必不和他們同流先知的血。』","notes":[]},{"n":31,"t":"這就是你們自己證明是殺害先知者的子孫了。","notes":[]},{"n":32,"t":"你們去充滿你們祖宗的惡貫吧！","notes":[]},{"n":33,"t":"你們這些蛇類、毒蛇之種啊，怎能逃脫地獄的刑罰呢？","notes":[]},{"n":34,"t":"所以我差遣先知和智慧人並文士到你們這裏來，有的你們要殺害，要釘十字架；有的你們要在會堂裏鞭打，從這城追逼到那城，","notes":[]},{"n":35,"t":"叫世上所流義人的血都歸到你們身上，從義人亞伯的血起，直到你們在殿和壇中間所殺的巴拉加的兒子撒迦利亞的血為止。","notes":[]},{"n":36,"t":"我實在告訴你們，這一切的罪都要歸到這世代了。」","notes":[]},{"n":37,"t":"「耶路撒冷啊，耶路撒冷啊，你常殺害先知，又用石頭打死那奉差遣到你這裏來的人。我多次願意聚集你的兒女，好像母雞把小雞聚集在翅膀底下，只是你們不願意。","notes":[],"heads":["為耶路撒冷哀哭"]},{"n":38,"t":"看哪，你們的家成為荒場留給你們。","notes":[]},{"n":39,"t":"我告訴你們，從今以後，你們不得再見我，直等到你們說：『奉主名來的是應當稱頌的。』」","notes":[]}]},"24":{"heading":"預言聖殿被毀","verses":[{"n":1,"t":"耶穌出了聖殿，正走的時候，門徒進前來，把殿宇指給他看。","notes":[]},{"n":2,"t":"耶穌對他們說：「你們不是看見這殿宇嗎？我實在告訴你們，將來在這裏沒有一塊石頭留在石頭上，不被拆毀了。」","notes":[]},{"n":3,"t":"耶穌在橄欖山上坐著，門徒暗暗地來說：「請告訴我們，甚麼時候有這些事？你降臨和世界的末了有甚麼預兆呢？」","notes":[],"heads":["災難的起頭"]},{"n":4,"t":"耶穌回答說：「你們要謹慎，免得有人迷惑你們。","notes":[]},{"n":5,"t":"因為將來有好些人冒我的名來，說：『我是基督』，並且要迷惑許多人。","notes":[]},{"n":6,"t":"你們也要聽見打仗和打仗的風聲，總不要驚慌；因為這些事是必須有的，只是末期還沒有到。","notes":[]},{"n":7,"t":"民要攻打民，國要攻打國；多處必有饑荒、地震。","notes":[]},{"n":8,"t":"這都是災難的起頭。","notes":["災難：原文是生產之難"]},{"n":9,"t":"那時，人要把你們陷在患難裏，也要殺害你們；你們又要為我的名被萬民恨惡。","notes":[]},{"n":10,"t":"那時，必有許多人跌倒，也要彼此陷害，彼此恨惡；","notes":[]},{"n":11,"t":"且有好些假先知起來，迷惑多人。","notes":[]},{"n":12,"t":"只因不法的事增多，許多人的愛心才漸漸冷淡了。","notes":[]},{"n":13,"t":"惟有忍耐到底的，必然得救。","notes":[]},{"n":14,"t":"這天國的福音要傳遍天下，對萬民作見證，然後末期才來到。」","notes":[]},{"n":15,"t":"「你們看見先知但以理所說的『那行毀壞可憎的』站在聖地（讀這經的人須要會意）。","notes":[],"heads":["大災難"]},{"n":16,"t":"那時，在猶太的，應當逃到山上；","notes":[]},{"n":17,"t":"在房上的，不要下來拿家裏的東西；","notes":[]},{"n":18,"t":"在田裏的，也不要回去取衣裳。","notes":[]},{"n":19,"t":"當那些日子，懷孕的和奶孩子的有禍了。","notes":[]},{"n":20,"t":"你們應當祈求，叫你們逃走的時候，不遇見冬天或是安息日。","notes":[]},{"n":21,"t":"因為那時必有大災難，從世界的起頭直到如今，沒有這樣的災難，後來也必沒有。","notes":[]},{"n":22,"t":"若不減少那日子，凡有血氣的總沒有一個得救的；只是為選民，那日子必減少了。","notes":[]},{"n":23,"t":"那時，若有人對你們說：『基督在這裏』，或說：『基督在那裏』，你們不要信！","notes":[]},{"n":24,"t":"因為假基督、假先知將要起來，顯大神蹟、大奇事，倘若能行，連選民也就迷惑了。","notes":[]},{"n":25,"t":"看哪，我預先告訴你們了。","notes":[]},{"n":26,"t":"若有人對你們說：『看哪，基督在曠野裏』，你們不要出去！或說：『看哪，基督在內屋中』，你們不要信！","notes":[]},{"n":27,"t":"閃電從東邊發出，直照到西邊。人子降臨也要這樣。","notes":[]},{"n":28,"t":"屍首在哪裏，鷹也必聚在那裏。」","notes":[]},{"n":29,"t":"「那些日子的災難一過去，日頭就變黑了，月亮也不放光，眾星要從天上墜落，天勢都要震動。","notes":[],"heads":["人子的降臨"]},{"n":30,"t":"那時，人子的兆頭要顯在天上，地上的萬族都要哀哭。他們要看見人子，有能力，有大榮耀，駕著天上的雲降臨。","notes":[]},{"n":31,"t":"他要差遣使者，用號筒的大聲，將他的選民，從四方，從天這邊到天那邊，都招聚了來。」","notes":["方：原文是風"]},{"n":32,"t":"「你們可以從無花果樹學個比方：當樹枝發嫩長葉的時候，你們就知道夏天近了。","notes":[],"heads":["從無花果樹學個比方"]},{"n":33,"t":"這樣，你們看見這一切的事，也該知道人子近了，正在門口了。","notes":[]},{"n":34,"t":"我實在告訴你們，這世代還沒有過去，這些事都要成就。","notes":[]},{"n":35,"t":"天地要廢去，我的話卻不能廢去。」","notes":[]},{"n":36,"t":"「但那日子，那時辰，沒有人知道，連天上的使者也不知道，子也不知道，惟獨父知道。","notes":[],"heads":["那日那時沒有人知道"]},{"n":37,"t":"挪亞的日子怎樣，人子降臨也要怎樣。","notes":[]},{"n":38,"t":"當洪水以前的日子，人照常吃喝嫁娶，直到挪亞進方舟的那日；","notes":[]},{"n":39,"t":"不知不覺洪水來了，把他們全都沖去。人子降臨也要這樣。","notes":[]},{"n":40,"t":"那時，兩個人在田裏，取去一個，撇下一個。","notes":[]},{"n":41,"t":"兩個女人推磨，取去一個，撇下一個。","notes":[]},{"n":42,"t":"所以，你們要警醒，因為不知道你們的主是哪一天來到。","notes":[]},{"n":43,"t":"家主若知道幾更天有賊來，就必警醒，不容人挖透房屋；這是你們所知道的。","notes":[]},{"n":44,"t":"所以，你們也要預備，因為你們想不到的時候，人子就來了。」","notes":[]},{"n":45,"t":"「誰是忠心有見識的僕人，為主人所派，管理家裏的人，按時分糧給他們呢？","notes":[],"heads":["忠心和不忠心的僕人"]},{"n":46,"t":"主人來到，看見他這樣行，那僕人就有福了。","notes":[]},{"n":47,"t":"我實在告訴你們，主人要派他管理一切所有的。","notes":[]},{"n":48,"t":"倘若那惡僕心裏說：『我的主人必來得遲』，","notes":[]},{"n":49,"t":"就動手打他的同伴，又和酒醉的人一同吃喝。","notes":[]},{"n":50,"t":"在想不到的日子，不知道的時辰，那僕人的主人要來，","notes":[]},{"n":51,"t":"重重地處治他，定他和假冒為善的人同罪；在那裏必要哀哭切齒了。」","notes":["或譯：把他腰斬了"]}]},"25":{"heading":"十童女的比喻","verses":[{"n":1,"t":"「那時，天國好比十個童女拿著燈出去迎接新郎。","notes":[]},{"n":2,"t":"其中有五個是愚拙的，五個是聰明的。","notes":[]},{"n":3,"t":"愚拙的拿著燈，卻不預備油；","notes":[]},{"n":4,"t":"聰明的拿著燈，又預備油在器皿裏。","notes":[]},{"n":5,"t":"新郎遲延的時候，她們都打盹，睡著了。","notes":[]},{"n":6,"t":"半夜有人喊著說：『新郎來了，你們出來迎接他！』","notes":[]},{"n":7,"t":"那些童女就都起來收拾燈。","notes":[]},{"n":8,"t":"愚拙的對聰明的說：『請分點油給我們， 因為我們的燈要滅了。』","notes":[]},{"n":9,"t":"聰明的回答說：『恐怕不夠你我用的；不如你們自己到賣油的那裏去買吧。』","notes":[]},{"n":10,"t":"她們去買的時候，新郎到了。那預備好了的，同他進去坐席，門就關了。","notes":[]},{"n":11,"t":"其餘的童女隨後也來了，說：『主啊，主啊，給我們開門！』","notes":[]},{"n":12,"t":"他卻回答說：『我實在告訴你們，我不認識你們。』","notes":[]},{"n":13,"t":"所以，你們要警醒；因為那日子，那時辰，你們不知道。」","notes":[]},{"n":14,"t":"「天國又好比一個人要往外國去，就叫了僕人來，把他的家業交給他們，","notes":[],"heads":["按才幹接受託付的比喻"]},{"n":15,"t":"按著各人的才幹給他們銀子：一個給了五千，一個給了二千，一個給了一千，就往外國去了。","notes":[]},{"n":16,"t":"那領五千的隨即拿去做買賣，另外賺了五千。","notes":[]},{"n":17,"t":"那領二千的也照樣另賺了二千。","notes":[]},{"n":18,"t":"但那領一千的去掘開地，把主人的銀子埋藏了。","notes":[]},{"n":19,"t":"過了許久，那些僕人的主人來了，和他們算帳。","notes":[]},{"n":20,"t":"那領五千銀子的又帶著那另外的五千來，說：『主啊，你交給我五千銀子。請看，我又賺了五千。』","notes":[]},{"n":21,"t":"主人說：『好，你這又良善又忠心的僕人，你在不多的事上有忠心，我要把許多事派你管理；可以進來享受你主人的快樂。』","notes":[]},{"n":22,"t":"那領二千的也來，說：『主啊，你交給我二千銀子。請看，我又賺了二千。』","notes":[]},{"n":23,"t":"主人說：『好，你這又良善又忠心的僕人，你在不多的事上有忠心，我要把許多事派你管理；可以進來享受你主人的快樂。』","notes":[]},{"n":24,"t":"那領一千的也來，說：『主啊，我知道你是忍心的人，沒有種的地方要收割，沒有散的地方要聚斂，","notes":[]},{"n":25,"t":"我就害怕，去把你的一千銀子埋藏在地裏。請看，你的原銀子在這裏。』","notes":[]},{"n":26,"t":"主人回答說：『你這又惡又懶的僕人，你既知道我沒有種的地方要收割，沒有散的地方要聚斂，","notes":[]},{"n":27,"t":"就當把我的銀子放給兌換銀錢的人，到我來的時候，可以連本帶利收回。","notes":[]},{"n":28,"t":"奪過他這一千來，給那有一萬的。","notes":[]},{"n":29,"t":"因為凡有的，還要加給他，叫他有餘；沒有的，連他所有的也要奪過來。","notes":[]},{"n":30,"t":"把這無用的僕人丟在外面黑暗裏；在那裏必要哀哭切齒了。』」","notes":[]},{"n":31,"t":"「當人子在他榮耀裏、同著眾天使降臨的時候，要坐在他榮耀的寶座上。","notes":[],"heads":["萬民受審判"]},{"n":32,"t":"萬民都要聚集在他面前。他要把他們分別出來，好像牧羊的分別綿羊山羊一般，","notes":[]},{"n":33,"t":"把綿羊安置在右邊，山羊在左邊。","notes":[]},{"n":34,"t":"於是王要向那右邊的說：『你們這蒙我父賜福的，可來承受那創世以來為你們所預備的國；","notes":[]},{"n":35,"t":"因為我餓了，你們給我吃，渴了，你們給我喝；我作客旅，你們留我住；","notes":[]},{"n":36,"t":"我赤身露體，你們給我穿；我病了，你們看顧我；我在監裏，你們來看我。』","notes":[]},{"n":37,"t":"義人就回答說：『主啊，我們甚麼時候見你餓了，給你吃，渴了，給你喝？","notes":[]},{"n":38,"t":"甚麼時候見你作客旅，留你住，或是赤身露體，給你穿？","notes":[]},{"n":39,"t":"又甚麼時候見你病了，或是在監裏，來看你呢？』","notes":[]},{"n":40,"t":"王要回答說：『我實在告訴你們，這些事你們既做在我這弟兄中一個最小的身上，就是做在我身上了。』","notes":[]},{"n":41,"t":"王又要向那左邊的說：『你們這被咒詛的人，離開我！進入那為魔鬼和他的使者所預備的永火裏去！","notes":[]},{"n":42,"t":"因為我餓了，你們不給我吃，渴了，你們不給我喝；","notes":[]},{"n":43,"t":"我作客旅，你們不留我住；我赤身露體，你們不給我穿；我病了，我在監裏，你們不來看顧我。』","notes":[]},{"n":44,"t":"他們也要回答說：『主啊，我們甚麼時候見你餓了，或渴了，或作客旅，或赤身露體，或病了，或在監裏，不伺候你呢？』","notes":[]},{"n":45,"t":"王要回答說：『我實在告訴你們，這些事你們既不做在我這弟兄中一個最小的身上，就是不做在我身上了。』","notes":[]},{"n":46,"t":"這些人要往永刑裏去；那些義人要往永生裏去。」","notes":[]}]},"26":{"heading":"殺害耶穌的陰謀","verses":[{"n":1,"t":"耶穌說完了這一切的話，就對門徒說：","notes":[]},{"n":2,"t":"「你們知道，過兩天是逾越節，人子將要被交給人，釘在十字架上。」","notes":[]},{"n":3,"t":"那時，祭司長和民間的長老聚集在大祭司稱為該亞法的院裏。","notes":[]},{"n":4,"t":"大家商議要用詭計拿住耶穌，殺他，","notes":[]},{"n":5,"t":"只是說：「當節的日子不可，恐怕民間生亂。」","notes":[]},{"n":6,"t":"耶穌在伯大尼長大痲瘋的西門家裏，","notes":[],"heads":["在伯大尼受膏"]},{"n":7,"t":"有一個女人拿著一玉瓶極貴的香膏來，趁耶穌坐席的時候，澆在他的頭上。","notes":[]},{"n":8,"t":"門徒看見就很不喜悅，說：「何用這樣的枉費呢！","notes":[]},{"n":9,"t":"這香膏可以賣許多錢，賙濟窮人。」","notes":[]},{"n":10,"t":"耶穌看出他們的意思，就說：「為甚麼難為這女人呢？她在我身上做的是一件美事。","notes":[]},{"n":11,"t":"因為常有窮人和你們同在；只是你們不常有我。","notes":[]},{"n":12,"t":"她將這香膏澆在我身上是為我安葬做的。","notes":[]},{"n":13,"t":"我實在告訴你們，普天之下，無論在甚麼地方傳這福音，也要述說這女人所行的，作個紀念。」","notes":[]},{"n":14,"t":"當下，十二門徒裏有一個稱為加略人猶大的，去見祭司長，","notes":[],"heads":["猶大出賣耶穌"]},{"n":15,"t":"說： 「我把他交給你們，你們願意給我多少錢？」他們就給了他三十塊錢。","notes":[]},{"n":16,"t":"從那時候，他就找機會要把耶穌交給他們。","notes":[]},{"n":17,"t":"除酵節的第一天，門徒來問耶穌說：「你吃逾越節的筵席，要我們在哪裏給你預備？」","notes":[],"heads":["和門徒同度逾越節"]},{"n":18,"t":"耶穌說：「你們進城去，到某人那裏，對他說：『夫子說：我的時候快到了，我與門徒要在你家裏守逾越節。』」","notes":[]},{"n":19,"t":"門徒遵著耶穌所吩咐的就去預備了逾越節的筵席。","notes":[]},{"n":20,"t":"到了晚上，耶穌和十二個門徒坐席。","notes":[]},{"n":21,"t":"正吃的時候，耶穌說：「我實在告訴你們，你們中間有一個人要賣我了。」","notes":[]},{"n":22,"t":"他們就甚憂愁，一個一個地問他說：「主，是我嗎？」","notes":[]},{"n":23,"t":"耶穌回答說：「同我蘸手在盤子裏的，就是他要賣我。","notes":[]},{"n":24,"t":"人子必要去世，正如經上指著他所寫的；但賣人子的人有禍了！那人不生在世上倒好。」","notes":[]},{"n":25,"t":"賣耶穌的猶大問他說：「拉比，是我嗎？」耶穌說：「你說的是。」","notes":[]},{"n":26,"t":"他們吃的時候，耶穌拿起餅來，祝福，就擘開，遞給門徒，說：「你們拿著吃，這是我的身體」；","notes":[],"heads":["設立主的晚餐"]},{"n":27,"t":"又拿起杯來，祝謝了，遞給他們，說：「你們都喝這個；","notes":[]},{"n":28,"t":"因為這是我立約的血，為多人流出來，使罪得赦。","notes":[]},{"n":29,"t":"但我告訴你們，從今以後，我不再喝這葡萄汁，直到我在我父的國裏同你們喝新的那日子。」","notes":[]},{"n":30,"t":"他們唱了詩，就出來往橄欖山去。","notes":[]},{"n":31,"t":"那時，耶穌對他們說：「今夜，你們為我的緣故都要跌倒。因為經上記著說：我要擊打牧人，羊就分散了。","notes":[],"heads":["預言彼得不認主"]},{"n":32,"t":"但我復活以後，要在你們以先往加利利去。」","notes":[]},{"n":33,"t":"彼得說：「眾人雖然為你的緣故跌倒，我卻永不跌倒。」","notes":[]},{"n":34,"t":"耶穌說：「我實在告訴你，今夜雞叫以先，你要三次不認我。」","notes":[]},{"n":35,"t":"彼得說：「我就是必須和你同死，也總不能不認你。」眾門徒都是這樣說。","notes":[]},{"n":36,"t":"耶穌同門徒來到一個地方，名叫客西馬尼，就對他們說：「你們坐在這裏，等我到那邊去禱告。」","notes":[],"heads":["在客西馬尼禱告"]},{"n":37,"t":"於是帶著彼得和西庇太的兩個兒子同去，就憂愁起來，極其難過，","notes":[]},{"n":38,"t":"便對他們說：「我心裏甚是憂傷，幾乎要死；你們在這裏等候，和我一同警醒。」","notes":[]},{"n":39,"t":"他就稍往前走，俯伏在地，禱告說：「我父啊，倘若可行，求你叫這杯離開我。然而，不要照我的意思，只要照你的意思。」","notes":[]},{"n":40,"t":"來到門徒那裏，見他們睡著了，就對彼得說：「怎麼樣？你們不能同我警醒片時嗎？","notes":[]},{"n":41,"t":"總要警醒禱告，免得入了迷惑。你們心靈固然願意，肉體卻軟弱了。」","notes":[]},{"n":42,"t":"第二次又去禱告說：「我父啊，這杯若不能離開我，必要我喝，就願你的意旨成全。」","notes":[]},{"n":43,"t":"又來，見他們睡著了，因為他們的眼睛困倦。","notes":[]},{"n":44,"t":"耶穌又離開他們去了。第三次禱告，說的話還是與先前一樣。","notes":[]},{"n":45,"t":"於是來到門徒那裏，對他們說：「現在你們仍然睡覺安歇吧！時候到了，人子被賣在罪人手裏了。","notes":["吧：或譯嗎？"]},{"n":46,"t":"起來！我們走吧。看哪，賣我的人近了！」","notes":[]},{"n":47,"t":"說話之間，那十二個門徒裏的猶大來了，並有許多人帶著刀棒，從祭司長和民間的長老那裏與他同來。","notes":[],"heads":["耶穌被捕"]},{"n":48,"t":"那賣耶穌的給了他們一個暗號，說：「我與誰親嘴，誰就是他。你們可以拿住他。」","notes":[]},{"n":49,"t":"猶大隨即到耶穌跟前，說：「請拉比安」，就與他親嘴。","notes":[]},{"n":50,"t":"耶穌對他說：「朋友，你來要做的事，就做吧。」於是那些人上前，下手拿住耶穌。","notes":[]},{"n":51,"t":"有跟隨耶穌的一個人伸手拔出刀來，將大祭司的僕人砍了一刀，削掉了他一個耳朵。","notes":[]},{"n":52,"t":"耶穌對他說：「收刀入鞘吧！凡動刀的，必死在刀下。","notes":[]},{"n":53,"t":"你想，我不能求我父現在為我差遣十二營多天使來嗎？","notes":[]},{"n":54,"t":"若是這樣，經上所說，事情必須如此的話怎麼應驗呢？」","notes":[]},{"n":55,"t":"當時，耶穌對眾人說：「你們帶著刀棒出來拿我，如同拿強盜嗎？我天天坐在殿裏教訓人，你們並沒有拿我。","notes":[]},{"n":56,"t":"但這一切的事成就了，為要應驗先知書上的話。」當下，門徒都離開他，逃走了。","notes":[]},{"n":57,"t":"拿耶穌的人把他帶到大祭司該亞法那裏去；文士和長老已經在那裏聚會。","notes":[],"heads":["耶穌在公會裏受審"]},{"n":58,"t":"彼得遠遠地跟著耶穌，直到大祭司的院子，進到裏面，就和差役同坐，要看這事到底怎樣。","notes":[]},{"n":59,"t":"祭司長和全公會尋找假見證控告耶穌，要治死他。","notes":[]},{"n":60,"t":"雖有好些人來作假見證，總得不著實據。末後有兩個人前來，說：","notes":[]},{"n":61,"t":"「這個人曾說：『我能拆毀神的殿，三日內又建造起來。』」","notes":[]},{"n":62,"t":"大祭司就站起來，對耶穌說：「你甚麼都不回答嗎？這些人作見證告你的是甚麼呢？」","notes":[]},{"n":63,"t":"耶穌卻不言語。大祭司對他說：「我指著永生神叫你起誓告訴我們，你是神的兒子基督不是？」","notes":[]},{"n":64,"t":"耶穌對他說：「你說的是。然而，我告訴你們，後來你們要看見人子坐在那權能者的右邊，駕著天上的雲降臨。」","notes":[]},{"n":65,"t":"大祭司就撕開衣服，說：「他說了僭妄的話，我們何必再用見證人呢？這僭妄的話，現在你們都聽見了。","notes":[]},{"n":66,"t":"你們的意見如何？」他們回答說：「他是該死的。」","notes":[]},{"n":67,"t":"他們就吐唾沫在他臉上，用拳頭打他，也有用手掌打他的，說：","notes":[]},{"n":68,"t":"「基督啊！你是先知，告訴我們打你的是誰？」","notes":[]},{"n":69,"t":"彼得在外面院子裏坐著，有一個使女前來，說：「你素來也是同那加利利人耶穌一夥的。」","notes":[],"heads":["彼得三次不認主"]},{"n":70,"t":"彼得在眾人面前卻不承認，說：「我不知道你說的是甚麼！」","notes":[]},{"n":71,"t":"既出去，到了門口，又有一個使女看見他，就對那裏的人說：「這個人也是同拿撒勒人耶穌一夥的。」","notes":[]},{"n":72,"t":"彼得又不承認，並且起誓說：「我不認得那個人。」","notes":[]},{"n":73,"t":"過了不多的時候，旁邊站著的人前來，對彼得說：「你真是他們一黨的，你的口音把你露出來了。」","notes":[]},{"n":74,"t":"彼得就發咒起誓地說：「我不認得那個人。」立時，雞就叫了。","notes":[]},{"n":75,"t":"彼得想起耶穌所說的話：「雞叫以先，你要三次不認我。」他就出去痛哭。","notes":[]}]},"27":{"heading":"耶穌被交給彼拉多","verses":[{"n":1,"t":"到了早晨，眾祭司長和民間的長老大家商議要治死耶穌，","notes":[]},{"n":2,"t":"就把他捆綁，解去，交給巡撫彼拉多。","notes":[]},{"n":3,"t":"這時候，賣耶穌的猶大看見耶穌已經定了罪，就後悔，把那三十塊錢拿回來給祭司長和長老，說：","notes":[],"heads":["猶大的死"]},{"n":4,"t":"「我賣了無辜之人的血是有罪了。」他們說：「那與我們有甚麼相干？你自己承當吧！」","notes":[]},{"n":5,"t":"猶大就把那銀錢丟在殿裏，出去吊死了。","notes":[]},{"n":6,"t":"祭司長拾起銀錢來，說：「這是血價，不可放在庫裏。」","notes":[]},{"n":7,"t":"他們商議，就用那銀錢買了窯戶的一塊田，為要埋葬外鄉人。","notes":[]},{"n":8,"t":"所以那塊田直到今日還叫做「血田」。","notes":[]},{"n":9,"t":"這就應了先知耶利米的話，說：「他們用那三十塊錢，就是被估定之人的價錢，是以色列人中所估定的，","notes":[]},{"n":10,"t":"買了窯戶的一塊田；這是照著主所吩咐我的。」","notes":[]},{"n":11,"t":"耶穌站在巡撫面前；巡撫問他說：「你是猶太人的王嗎？」耶穌說：「你說的是。」","notes":[],"heads":["耶穌在彼拉多面前受審"]},{"n":12,"t":"他被祭司長和長老控告的時候，甚麼都不回答。","notes":[]},{"n":13,"t":"彼拉多就對他說：「他們作見證告你這麼多的事，你沒有聽見嗎？」","notes":[]},{"n":14,"t":"耶穌仍不回答，連一句話也不說，以致巡撫甚覺希奇。","notes":[]},{"n":15,"t":"巡撫有一個常例，每逢這節期，隨眾人所要的釋放一個囚犯給他們。","notes":[],"heads":["耶穌被判死刑"]},{"n":16,"t":"當時有一個出名的囚犯叫巴拉巴。","notes":[]},{"n":17,"t":"眾人聚集的時候，彼拉多就對他們說：「你們要我釋放哪一個給你們？是巴拉巴呢？是稱為基督的耶穌呢？」","notes":[]},{"n":18,"t":"巡撫原知道他們是因為嫉妒才把他解了來。","notes":[]},{"n":19,"t":"正坐堂的時候，他的夫人打發人來說：「這義人的事，你一點不可管，因為我今天在夢中為他受了許多的苦。」","notes":[]},{"n":20,"t":"祭司長和長老挑唆眾人，求釋放巴拉巴，除滅耶穌。","notes":[]},{"n":21,"t":"巡撫對眾人說：「這兩個人，你們要我釋放哪一個給你們呢？」他們說：「巴拉巴。」","notes":[]},{"n":22,"t":"彼拉多說：「這樣，那稱為基督的耶穌我怎麼辦他呢？」他們都說：「把他釘十字架！」","notes":[]},{"n":23,"t":"巡撫說：「為甚麼呢？他做了甚麼惡事呢？」他們便極力地喊著說：「把他釘十字架！」","notes":[]},{"n":24,"t":"彼拉多見說也無濟於事，反要生亂，就拿水在眾人面前洗手，說：「流這義人的血，罪不在我，你們承當吧。」","notes":[]},{"n":25,"t":"眾人都回答說：「他的血歸到我們和我們的子孫身上。」","notes":[]},{"n":26,"t":"於是彼拉多釋放巴拉巴給他們，把耶穌鞭打了，交給人釘十字架。","notes":[]},{"n":27,"t":"巡撫的兵就把耶穌帶進衙門，叫全營的兵都聚集在他那裏。","notes":[],"heads":["兵丁戲弄耶穌"]},{"n":28,"t":"他們給他脫了衣服，穿上一件朱紅色袍子，","notes":[]},{"n":29,"t":"用荊棘編做冠冕，戴在他頭上，拿一根葦子放在他右手裏，跪在他面前，戲弄他，說：「恭喜，猶太人的王啊！」","notes":[]},{"n":30,"t":"又吐唾沫在他臉上，拿葦子打他的頭。","notes":[]},{"n":31,"t":"戲弄完了，就給他脫了袍子，仍穿上他自己的衣服，帶他出去，要釘十字架。","notes":[]},{"n":32,"t":"他們出來的時候，遇見一個古利奈人，名叫西門，就勉強他同去，好背著耶穌的十字架。","notes":[],"heads":["耶穌被釘十字架"]},{"n":33,"t":"到了一個地方名叫各各他，意思就是「髑髏地」。","notes":[]},{"n":34,"t":"兵丁拿苦膽調和的酒給耶穌喝；他嘗了，就不肯喝。","notes":[]},{"n":35,"t":"他們既將他釘在十字架上，就拈鬮分他的衣服，","notes":[]},{"n":36,"t":"又坐在那裏看守他。","notes":[]},{"n":37,"t":"在他頭以上安一個牌子，寫著他的罪狀，說：「這是猶太人的王耶穌。」","notes":[]},{"n":38,"t":"當時，有兩個強盜和他同釘十字架，一個在右邊，一個在左邊。","notes":[]},{"n":39,"t":"從那裏經過的人譏誚他，搖著頭，說：","notes":[]},{"n":40,"t":"「你這拆毀聖殿、三日又建造起來的，可以救自己吧！你如果是神的兒子，就從十字架上下來吧！」","notes":[]},{"n":41,"t":"祭司長和文士並長老也是這樣戲弄他，說：","notes":[]},{"n":42,"t":"「他救了別人，不能救自己。他是以色列的王，現在可以從十字架上下來，我們就信他。","notes":[]},{"n":43,"t":"他倚靠神，神若喜悅他，現在可以救他；因為他曾說：『我是神的兒子。』」","notes":[]},{"n":44,"t":"那和他同釘的強盜也是這樣地譏誚他。","notes":[]},{"n":45,"t":"從午正到申初，遍地都黑暗了。","notes":[],"heads":["耶穌的死"]},{"n":46,"t":"約在申初，耶穌大聲喊著說：「以利！以利！拉馬撒巴各大尼？」就是說：「我的神！我的神！為甚麼離棄我？」","notes":[]},{"n":47,"t":"站在那裏的人，有的聽見就說：「這個人呼叫以利亞呢！」","notes":[]},{"n":48,"t":"內中有一個人趕緊跑去，拿海絨蘸滿了醋，綁在葦子上，送給他喝。","notes":[]},{"n":49,"t":"其餘的人說：「且等著，看以利亞來救他不來。」","notes":[]},{"n":50,"t":"耶穌又大聲喊叫，氣就斷了。","notes":[]},{"n":51,"t":"忽然，殿裏的幔子從上到下裂為兩半，地也震動，磐石也崩裂，","notes":[]},{"n":52,"t":"墳墓也開了，已睡聖徒的身體多有起來的。","notes":[]},{"n":53,"t":"到耶穌復活以後，他們從墳墓裏出來，進了聖城，向許多人顯現。","notes":[]},{"n":54,"t":"百夫長和一同看守耶穌的人看見地震並所經歷的事，就極其害怕，說：「這真是神的兒子了！」","notes":[]},{"n":55,"t":"有好些婦女在那裏，遠遠地觀看；她們是從加利利跟隨耶穌來服事他的。","notes":[]},{"n":56,"t":"內中有抹大拉的馬利亞，又有雅各和約西的母親馬利亞，並有西庇太兩個兒子的母親。","notes":[]},{"n":57,"t":"到了晚上，有一個財主，名叫約瑟，是亞利馬太來的，他也是耶穌的門徒。","notes":[],"heads":["耶穌的安葬"]},{"n":58,"t":"這人去見彼拉多，求耶穌的身體；彼拉多就吩咐給他。","notes":[]},{"n":59,"t":"約瑟取了身體，用乾淨細麻布裹好，","notes":[]},{"n":60,"t":"安放在自己的新墳墓裏，就是他鑿在磐石裏的。他又把大石頭滾到墓門口，就去了。","notes":[]},{"n":61,"t":"有抹大拉的馬利亞和那個馬利亞在那裏，對著墳墓坐著。","notes":[]},{"n":62,"t":"次日，就是預備日的第二天，祭司長和法利賽人聚集來見彼拉多，說：","notes":[],"heads":["封石妥守"]},{"n":63,"t":"「大人，我們記得那誘惑人的還活著的時候曾說：『三日後我要復活。』","notes":[]},{"n":64,"t":"因此，請吩咐人將墳墓把守妥當，直到第三日，恐怕他的門徒來，把他偷了去，就告訴百姓說：『他從死裏復活了。』這樣，那後來的迷惑比先前的更利害了！」","notes":[]},{"n":65,"t":"彼拉多說：「你們有看守的兵，去吧！盡你們所能的把守妥當。」","notes":[]},{"n":66,"t":"他們就帶著看守的兵同去，封了石頭，將墳墓把守妥當。","notes":[]}]},"28":{"heading":"耶穌復活","verses":[{"n":1,"t":"安息日將盡，七日的頭一日，天快亮的時候，抹大拉的馬利亞和那個馬利亞來看墳墓。","notes":[]},{"n":2,"t":"忽然，地大震動；因為有主的使者從天上下來，把石頭滾開，坐在上面。","notes":[]},{"n":3,"t":"他的相貌如同閃電，衣服潔白如雪。","notes":[]},{"n":4,"t":"看守的人就因他嚇得渾身亂戰，甚至和死人一樣。","notes":[]},{"n":5,"t":"天使對婦女說：「不要害怕！我知道你們是尋找那釘十字架的耶穌。","notes":[]},{"n":6,"t":"他不在這裏，照他所說的，已經復活了。你們來看安放主的地方。","notes":[]},{"n":7,"t":"快去告訴他的門徒，說他從死裏復活了，並且在你們以先往加利利去，在那裏你們要見他。看哪，我已經告訴你們了。」","notes":[]},{"n":8,"t":"婦女們就急忙離開墳墓，又害怕，又大大地歡喜，跑去要報給他的門徒。","notes":[]},{"n":9,"t":"忽然，耶穌遇見她們，說：「願你們平安！」她們就上前抱住他的腳拜他。","notes":[]},{"n":10,"t":"耶穌對她們說：「不要害怕！你們去告訴我的弟兄，叫他們往加利利去，在那裏必見我。」","notes":[]},{"n":11,"t":"她們去的時候，看守的兵有幾個進城去，將所經歷的事都報給祭司長。","notes":[],"heads":["看守的兵報告祭司長"]},{"n":12,"t":"祭司長和長老聚集商議，就拿許多銀錢給兵丁，說：","notes":[]},{"n":13,"t":"「你們要這樣說：『夜間我們睡覺的時候，他的門徒來，把他偷去了。』","notes":[]},{"n":14,"t":"倘若這話被巡撫聽見，有我們勸他，保你們無事。」","notes":[]},{"n":15,"t":"兵丁受了銀錢，就照所囑咐他們的去行。這話就傳說在猶太人中間，直到今日。","notes":[]},{"n":16,"t":"十一個門徒往加利利去，到了耶穌約定的山上。","notes":[],"heads":["門徒奉差遣"]},{"n":17,"t":"他們見了耶穌就拜他，然而還有人疑惑。","notes":[]},{"n":18,"t":"耶穌進前來，對他們說：「天上地下所有的權柄都賜給我了。","notes":[]},{"n":19,"t":"所以，你們要去，使萬民作我的門徒，奉父、子、聖靈的名給他們施洗 。","notes":["或譯：給他們施洗，歸於父、子、聖靈的名"]},{"n":20,"t":"凡我所吩咐你們的，都教訓他們遵守，我就常與你們同在，直到世界的末了。」","notes":[]}]}},"MRK":{"1":{"heading":"施洗約翰傳道","verses":[{"n":1,"t":"神的兒子，耶穌基督福音的起頭。","notes":[]},{"n":2,"t":"正如先知以賽亞書上記著說：看哪，我要差遣我的使者在你前面，預備道路。","notes":["有古卷沒有以賽亞三個字"]},{"n":3,"t":"在曠野有人聲喊著說：預備主的道，修直他的路。","notes":[]},{"n":4,"t":"照這話，約翰來了，在曠野施洗，傳悔改的洗禮，使罪得赦。","notes":[]},{"n":5,"t":"猶太全地和耶路撒冷的人都出去到約翰那裏，承認他們的罪，在約旦河裏受他的洗。","notes":[]},{"n":6,"t":"約翰穿駱駝毛的衣服，腰束皮帶，吃的是蝗蟲、野蜜。","notes":[]},{"n":7,"t":"他傳道說：「有一位在我以後來的，能力比我更大，我就是彎腰給他解鞋帶也是不配的。","notes":[]},{"n":8,"t":"我是用水給你們施洗，他卻要用聖靈給你們施洗。」","notes":[]},{"n":9,"t":"那時，耶穌從加利利的拿撒勒來，在約旦河裏受了約翰的洗。","notes":[],"heads":["耶穌受洗"]},{"n":10,"t":"他從水裏一上來，就看見天裂開了，聖靈彷彿鴿子，降在他身上。","notes":[]},{"n":11,"t":"又有聲音從天上來，說：「你是我的愛子，我喜悅你。」","notes":[]},{"n":12,"t":"聖靈就把耶穌催到曠野裏去。","notes":[],"heads":["耶穌受試探"]},{"n":13,"t":"他在曠野四十天，受撒但的試探，並與野獸同在一處，且有天使來伺候他。","notes":[]},{"n":14,"t":"約翰下監以後，耶穌來到加利利，宣傳神的福音，","notes":[],"heads":["開始在加利利傳道"]},{"n":15,"t":"說：「日期滿了，神的國近了。你們當悔改，信福音！」","notes":[]},{"n":16,"t":"耶穌順著加利利的海邊走，看見西門和西門的兄弟安得烈在海裏撒網；他們本是打魚的。","notes":[],"heads":["呼召四個漁夫"]},{"n":17,"t":"耶穌對他們說：「來跟從我，我要叫你們得人如得魚一樣。」","notes":[]},{"n":18,"t":"他們就立刻捨了網，跟從了他。","notes":[]},{"n":19,"t":"耶穌稍往前走，又見西庇太的兒子雅各和雅各的兄弟約翰在船上補網。","notes":[]},{"n":20,"t":"耶穌隨即招呼他們，他們就把父親西庇太和雇工人留在船上，跟從耶穌去了。","notes":[]},{"n":21,"t":"到了迦百農，耶穌就在安息日進了會堂教訓人。","notes":[],"heads":["一個污鬼附身的人"]},{"n":22,"t":"眾人很希奇他的教訓；因為他教訓他們，正像有權柄的人，不像文士。","notes":[]},{"n":23,"t":"在會堂裏，有一個人被污鬼附著。他喊叫說：","notes":[]},{"n":24,"t":"「拿撒勒人耶穌，我們與你有甚麼相干？你來滅我們嗎？我知道你是誰，乃是神的聖者。」","notes":[]},{"n":25,"t":"耶穌責備他說：「不要作聲！從這人身上出來吧。」","notes":[]},{"n":26,"t":"污鬼叫那人抽了一陣瘋，大聲喊叫，就出來了。","notes":[]},{"n":27,"t":"眾人都驚訝，以致彼此對問說：「這是甚麼事？是個新道理啊！他用權柄吩咐污鬼，連污鬼也聽從了他。」","notes":[]},{"n":28,"t":"耶穌的名聲就傳遍了加利利的四方。","notes":[]},{"n":29,"t":"他們一出會堂，就同著雅各、約翰，進了西門和安得烈的家。","notes":[],"heads":["治好許多病人"]},{"n":30,"t":"西門的岳母正害熱病躺著，就有人告訴耶穌。","notes":[]},{"n":31,"t":"耶穌進前拉著她的手，扶她起來，熱就退了，她就服事他們。","notes":[]},{"n":32,"t":"天晚日落的時候，有人帶著一切害病的，和被鬼附的，來到耶穌跟前。","notes":[]},{"n":33,"t":"合城的人都聚集在門前。","notes":[]},{"n":34,"t":"耶穌治好了許多害各樣病的人，又趕出許多鬼，不許鬼說話，因為鬼認識他。","notes":[]},{"n":35,"t":"次日早晨，天未亮的時候，耶穌起來，到曠野地方去，在那裏禱告。","notes":[],"heads":["在加利利各會堂傳道"]},{"n":36,"t":"西門和同伴追了他去，","notes":[]},{"n":37,"t":"遇見了就對他說：「眾人都找你。」","notes":[]},{"n":38,"t":"耶穌對他們說：「我們可以往別處去，到鄰近的鄉村，我也好在那裏傳道，因為我是為這事出來的。」","notes":[]},{"n":39,"t":"於是在加利利全地，進了會堂，傳道，趕鬼。","notes":[]},{"n":40,"t":"有一個長大痲瘋的來求耶穌，向他跪下，說：「你若肯，必能叫我潔淨了。」","notes":[],"heads":["潔淨長大痲瘋的人"]},{"n":41,"t":"耶穌動了慈心，就伸手摸他，說：「我肯，你潔淨了吧！」","notes":[]},{"n":42,"t":"大痲瘋即時離開他，他就潔淨了。","notes":[]},{"n":43,"t":"耶穌嚴嚴地囑咐他，就打發他走，","notes":[]},{"n":44,"t":"對他說：「你要謹慎，甚麼話都不可告訴人，只要去把身體給祭司察看，又因為你潔淨了，獻上摩西所吩咐的禮物，對眾人作證據。」","notes":[]},{"n":45,"t":"那人出去，倒說許多的話，把這件事傳揚開了，叫耶穌以後不得再明明地進城，只好在外邊曠野地方。人從各處都就了他來。","notes":[]}]},"2":{"heading":"治好癱瘓病人","verses":[{"n":1,"t":"過了些日子，耶穌又進了迦百農。人聽見他在房子裏，","notes":[]},{"n":2,"t":"就有許多人聚集，甚至連門前都沒有空地；耶穌就對他們講道。","notes":[]},{"n":3,"t":"有人帶著一個癱子來見耶穌，是用四個人抬來的；","notes":[]},{"n":4,"t":"因為人多，不得近前，就把耶穌所在的房子，拆了房頂，既拆通了，就把癱子連所躺臥的褥子都縋下來。","notes":[]},{"n":5,"t":"耶穌見他們的信心，就對癱子說：「小子，你的罪赦了。」","notes":[]},{"n":6,"t":"有幾個文士坐在那裏，心裏議論，說：","notes":[]},{"n":7,"t":"「這個人為甚麼這樣說呢？他說僭妄的話了。除了神以外，誰能赦罪呢？」","notes":[]},{"n":8,"t":"耶穌心中知道他們心裏這樣議論，就說：「你們心裏為甚麼這樣議論呢？","notes":[]},{"n":9,"t":"或對癱子說『你的罪赦了』，或說『起來！拿你的褥子行走』，哪一樣容易呢？","notes":[]},{"n":10,"t":"但要叫你們知道，人子在地上有赦罪的權柄。」就對癱子說：","notes":[]},{"n":11,"t":"「我吩咐你，起來！拿你的褥子回家去吧。」","notes":[]},{"n":12,"t":"那人就起來，立刻拿著褥子，當眾人面前出去了，以致眾人都驚奇，歸榮耀與神，說：「我們從來沒有見過這樣的事！」","notes":[]},{"n":13,"t":"耶穌又出到海邊去，眾人都就了他來，他便教訓他們。","notes":[],"heads":["呼召利未"]},{"n":14,"t":"耶穌經過的時候，看見亞勒腓的兒子利未坐在稅關上，就對他說：「你跟從我來。」他就起來，跟從了耶穌。","notes":[]},{"n":15,"t":"耶穌在利未家裏坐席的時候，有好些稅吏和罪人與耶穌並門徒一同坐席；因為這樣的人多，他們也跟隨耶穌。","notes":[]},{"n":16,"t":"法利賽人中的文士看見耶穌和罪人並稅吏一同吃飯，就對他門徒說：「他和稅吏並罪人一同吃喝嗎？」","notes":["有古卷：文士和法利賽人"]},{"n":17,"t":"耶穌聽見，就對他們說：「康健的人用不著醫生，有病的人才用得著。我來本不是召義人，乃是召罪人。」","notes":[]},{"n":18,"t":"當下，約翰的門徒和法利賽人禁食。他們來問耶穌說：「約翰的門徒和法利賽人的門徒禁食，你的門徒倒不禁食，這是為甚麼呢？」","notes":[],"heads":["禁食的問題"]},{"n":19,"t":"耶穌對他們說：「新郎和陪伴之人同在的時候，陪伴之人豈能禁食呢？新郎還同在，他們不能禁食。","notes":[]},{"n":20,"t":"但日子將到，新郎要離開他們，那日他們就要禁食。","notes":[]},{"n":21,"t":"沒有人把新布縫在舊衣服上，恐怕所補上的新布帶壞了舊衣服，破的就更大了。","notes":[]},{"n":22,"t":"也沒有人把新酒裝在舊皮袋裏，恐怕酒把皮袋裂開，酒和皮袋就都壞了；惟把新酒裝在新皮袋裏。」","notes":[]},{"n":23,"t":"耶穌當安息日從麥地經過。他門徒行路的時候，掐了麥穗。","notes":[],"heads":["安息日的問題"]},{"n":24,"t":"法利賽人對耶穌說：「看哪，他們在安息日為甚麼做不可做的事呢？」","notes":[]},{"n":25,"t":"耶穌對他們說：「經上記著大衛和跟從他的人缺乏飢餓之時所做的事，你們沒有念過嗎？","notes":[]},{"n":26,"t":"他當亞比亞他作大祭司的時候，怎麼進了神的殿，吃了陳設餅，又給跟從他的人吃。這餅除了祭司以外，人都不可吃。」","notes":[]},{"n":27,"t":"又對他們說：「安息日是為人設立的，人不是為安息日設立的。","notes":[]},{"n":28,"t":"所以，人子也是安息日的主。」","notes":[]}]},"3":{"heading":"治好枯乾了一隻手的人","verses":[{"n":1,"t":"耶穌又進了會堂，在那裏有一個人枯乾了一隻手。","notes":[]},{"n":2,"t":"眾人窺探耶穌，在安息日醫治不醫治，意思是要控告耶穌。","notes":[]},{"n":3,"t":"耶穌對那枯乾一隻手的人說：「起來，站在當中。」","notes":[]},{"n":4,"t":"又問眾人說：「在安息日行善行惡，救命害命，哪樣是可以的呢？」他們都不作聲。","notes":[]},{"n":5,"t":"耶穌怒目周圍看他們，憂愁他們的心剛硬，就對那人說：「伸出手來！」他把手一伸，手就復了原。","notes":[]},{"n":6,"t":"法利賽人出去，同希律一黨的人商議怎樣可以除滅耶穌。","notes":[]},{"n":7,"t":"耶穌和門徒退到海邊去，有許多人從加利利跟隨他。","notes":[],"heads":["海邊的群眾"]},{"n":8,"t":"還有許多人聽見他所做的大事，就從猶太、耶路撒冷、以土買、約旦河外，並泰爾、西頓的四方來到他那裏。","notes":[]},{"n":9,"t":"他因為人多，就吩咐門徒叫一隻小船伺候著，免得眾人擁擠他。","notes":[]},{"n":10,"t":"他治好了許多人，所以凡有災病的，都擠進來要摸他。","notes":[]},{"n":11,"t":"污鬼無論何時看見他，就俯伏在他面前，喊著說：「你是神的兒子。」","notes":[]},{"n":12,"t":"耶穌再三地囑咐他們，不要把他顯露出來。","notes":[]},{"n":13,"t":"耶穌上了山，隨自己的意思叫人來；他們便來到他那裏。","notes":[],"heads":["設立十二門徒"]},{"n":14,"t":"他就設立十二個人，要他們常和自己同在，也要差他們去傳道，","notes":[]},{"n":15,"t":"並給他們權柄趕鬼。","notes":[]},{"n":16,"t":"這十二個人有西門（耶穌又給他起名叫彼得），","notes":[]},{"n":17,"t":"還有西庇太的兒子雅各和雅各的兄弟約翰（又給這兩個人起名叫半尼其，就是雷子的意思），","notes":[]},{"n":18,"t":"又有安得烈、腓力、巴多羅買、馬太、多馬、亞勒腓的兒子雅各，和達太，並奮銳黨的西門，","notes":[]},{"n":19,"t":"還有賣耶穌的加略人猶大。","notes":[]},{"n":20,"t":"耶穌進了一個屋子，眾人又聚集，甚至他連飯也顧不得吃。","notes":[],"heads":["耶穌和別西卜"]},{"n":21,"t":"耶穌的親屬聽見，就出來要拉住他，因為他們說他癲狂了。","notes":[]},{"n":22,"t":"從耶路撒冷下來的文士說：「他是被別西卜附著」；又說：「他是靠著鬼王趕鬼。」","notes":[]},{"n":23,"t":"耶穌叫他們來，用比喻對他們說：「撒但怎能趕出撒但呢？","notes":[]},{"n":24,"t":"若一國自相紛爭，那國就站立不住；","notes":[]},{"n":25,"t":"若一家自相紛爭，那家就站立不住。","notes":[]},{"n":26,"t":"若撒但自相攻打紛爭，他就站立不住，必要滅亡。","notes":[]},{"n":27,"t":"沒有人能進壯士家裏，搶奪他的家具；必先捆住那壯士，才可以搶奪他的家。","notes":[]},{"n":28,"t":"我實在告訴你們，世人一切的罪和一切褻瀆的話都可得赦免；","notes":[]},{"n":29,"t":"凡褻瀆聖靈的，卻永不得赦免，乃要擔當永遠的罪。」","notes":[]},{"n":30,"t":"這話是因為他們說：「他是被污鬼附著的。」","notes":[]},{"n":31,"t":"當下，耶穌的母親和弟兄來，站在外邊，打發人去叫他。","notes":[],"heads":["耶穌的母親和兄弟們"]},{"n":32,"t":"有許多人在耶穌周圍坐著，他們就告訴他說：「看哪，你母親和你弟兄在外邊找你。」","notes":[]},{"n":33,"t":"耶穌回答說：「誰是我的母親？誰是我的弟兄？」","notes":[]},{"n":34,"t":"就四面觀看那周圍坐著的人，說：「看哪，我的母親，我的弟兄。","notes":[]},{"n":35,"t":"凡遵行神旨意的人就是我的弟兄姊妹和母親了。」","notes":[]}]},"4":{"heading":"撒種的比喻","verses":[{"n":1,"t":"耶穌又在海邊教訓人。有許多人到他那裏聚集，他只得上船坐下。船在海裏，眾人都靠近海，站在岸上。","notes":[]},{"n":2,"t":"耶穌就用比喻教訓他們許多道理。在教訓之間，對他們說：","notes":[]},{"n":3,"t":"「你們聽啊！有一個撒種的出去撒種。","notes":[]},{"n":4,"t":"撒的時候，有落在路旁的，飛鳥來吃盡了；","notes":[]},{"n":5,"t":"有落在土淺石頭地上的，土既不深，發苗最快，","notes":[]},{"n":6,"t":"日頭出來一曬，因為沒有根，就枯乾了；","notes":[]},{"n":7,"t":"有落在荊棘裏的，荊棘長起來，把它 擠住了，就不結實；","notes":[]},{"n":8,"t":"又有落在好土裏的，就發生長大，結實有三十倍的，有六十倍的，有一百倍的」；","notes":[]},{"n":9,"t":"又說：「有耳可聽的，就應當聽！」","notes":[]},{"n":10,"t":"無人的時候，跟隨耶穌的人和十二個門徒問他這比喻的意思。","notes":[],"heads":["用比喻的目的"]},{"n":11,"t":"耶穌對他們說：「神國的奧祕只叫你們知道，若是對外人講，凡事就用比喻，","notes":[]},{"n":12,"t":"叫他們看是看見，卻不曉得；聽是聽見，卻不明白；恐怕他們回轉過來，就得赦免。」","notes":[]},{"n":13,"t":"又對他們說：「你們不明白這比喻嗎？這樣怎能明白一切的比喻呢？","notes":[],"heads":["解明撒種的比喻"]},{"n":14,"t":"撒種之人所撒的就是道。","notes":[]},{"n":15,"t":"那撒在路旁的，就是人聽了道，撒但立刻來，把撒在他心裏的道奪了去。","notes":[]},{"n":16,"t":"那撒在石頭地上的，就是人聽了道，立刻歡喜領受，","notes":[]},{"n":17,"t":"但他心裏沒有根，不過是暫時的，及至為道遭了患難，或是受了逼迫，立刻就跌倒了。","notes":[]},{"n":18,"t":"還有那撒在荊棘裏的，就是人聽了道，","notes":[]},{"n":19,"t":"後來有世上的思慮、錢財的迷惑，和別樣的私慾進來，把道擠住了，就不能結實。","notes":[]},{"n":20,"t":"那撒在好地上的，就是人聽道，又領受，並且結實，有三十倍的，有六十倍的，有一百倍的。」","notes":[]},{"n":21,"t":"耶穌又對他們說：「人拿燈來，豈是要放在斗底下，床底下，不放在燈臺上嗎？","notes":[],"heads":["斗底下的燈"]},{"n":22,"t":"因為掩藏的事，沒有不顯出來的；隱瞞的事，沒有不露出來的。","notes":[]},{"n":23,"t":"有耳可聽的，就應當聽！」","notes":[]},{"n":24,"t":"又說：「你們所聽的要留心。你們用甚麼量器量給人，也必用甚麼量器量給你們，並且要多給你們。","notes":[]},{"n":25,"t":"因為有的，還要給他；沒有的，連他所有的也要奪去。」","notes":[]},{"n":26,"t":"又說：「神的國如同人把種撒在地上。","notes":[],"heads":["種子長大的比喻"]},{"n":27,"t":"黑夜睡覺，白日起來，這種就發芽漸長，那人卻不曉得如何這樣。","notes":[]},{"n":28,"t":"地生五穀是出於自然的：先發苗，後長穗，再後穗上結成飽滿的子粒；","notes":[]},{"n":29,"t":"穀既熟了，就用鐮刀去割，因為收成的時候到了。」","notes":[]},{"n":30,"t":"又說：「神的國，我們可用甚麼比較呢？可用甚麼比喻表明呢？","notes":[],"heads":["芥菜種的比喻"]},{"n":31,"t":"好像一粒芥菜種，種在地裏的時候，雖比地上的百種都小，","notes":[]},{"n":32,"t":"但種上以後，就長起來，比各樣的菜都大，又長出大枝來，甚至天上的飛鳥可以宿在它 的蔭下。」","notes":[]},{"n":33,"t":"耶穌用許多這樣的比喻，照他們所能聽的，對他們講道。","notes":[],"heads":["耶穌用比喻講道"]},{"n":34,"t":"若不用比喻，就不對他們講；沒有人的時候，就把一切的道講給門徒聽。","notes":[]},{"n":35,"t":"當那天晚上，耶穌對門徒說：「我們渡到那邊去吧。」","notes":[],"heads":["平靜風和海"]},{"n":36,"t":"門徒離開眾人，耶穌仍在船上，他們就把他一同帶去；也有別的船和他同行。","notes":[]},{"n":37,"t":"忽然起了暴風，波浪打入船內，甚至船要滿了水。","notes":[]},{"n":38,"t":"耶穌在船尾上，枕著枕頭睡覺。門徒叫醒了他，說：「夫子！我們喪命，你不顧嗎？」","notes":[]},{"n":39,"t":"耶穌醒了，斥責風，向海說：「住了吧！靜了吧！」風就止住，大大地平靜了。","notes":[]},{"n":40,"t":"耶穌對他們說：「為甚麼膽怯？你們還沒有信心嗎？」","notes":[]},{"n":41,"t":"他們就大大地懼怕，彼此說：「這到底是誰，連風和海也聽從他了。」","notes":[]}]},"5":{"heading":"治好格拉森被鬼附的人","verses":[{"n":1,"t":"他們來到海那邊格拉森人的地方。","notes":[]},{"n":2,"t":"耶穌一下船，就有一個被污鬼附著的人從墳塋裏出來迎著他。","notes":[]},{"n":3,"t":"那人常住在墳塋裏，沒有人能捆住他，就是用鐵鍊也不能；","notes":[]},{"n":4,"t":"因為人屢次用腳鐐和鐵鍊捆鎖他，鐵鍊竟被他掙斷了，腳鐐也被他弄碎了；總沒有人能制伏他。","notes":[]},{"n":5,"t":"他晝夜常在墳塋裏和山中喊叫，又用石頭砍自己。","notes":[]},{"n":6,"t":"他遠遠地看見耶穌，就跑過去拜他，","notes":[]},{"n":7,"t":"大聲呼叫說：「至高神的兒子耶穌，我與你有甚麼相干？我指著神懇求你，不要叫我受苦！」","notes":[]},{"n":8,"t":"是因耶穌曾吩咐他說：「污鬼啊，從這人身上出來吧！」","notes":[]},{"n":9,"t":"耶穌問他說：「你名叫甚麼？」回答說：「我名叫『群』，因為我們多的緣故」；","notes":[]},{"n":10,"t":"就再三地求耶穌，不要叫他們離開那地方。","notes":[]},{"n":11,"t":"在那裏山坡上，有一大群豬吃食；","notes":[]},{"n":12,"t":"鬼就央求耶穌說：「求你打發我們往豬群裏，附著豬去。」","notes":[]},{"n":13,"t":"耶穌准了他們，污鬼就出來，進入豬裏去。於是那群豬闖下山崖，投在海裏，淹死了。豬的數目約有二千。","notes":[]},{"n":14,"t":"放豬的就逃跑了，去告訴城裏和鄉下的人。眾人就來，要看是甚麼事。","notes":[]},{"n":15,"t":"他們來到耶穌那裏，看見那被鬼附著的人，就是從前被群鬼所附的，坐著，穿上衣服，心裏明白過來，他們就害怕。","notes":[]},{"n":16,"t":"看見這事的，便將鬼附之人所遇見的和那群豬的事都告訴了眾人；","notes":[]},{"n":17,"t":"眾人就央求耶穌離開他們的境界。","notes":[]},{"n":18,"t":"耶穌上船的時候，那從前被鬼附著的人懇求和耶穌同在。","notes":[]},{"n":19,"t":"耶穌不許，卻對他說：「你回家去，到你的親屬那裏，將主為你所做的是何等大的事，是怎樣憐憫你，都告訴他們。」","notes":[]},{"n":20,"t":"那人就走了，在低加坡里傳揚耶穌為他做了何等大的事，眾人就都希奇。","notes":[]},{"n":21,"t":"耶穌坐船又渡到那邊去，就有許多人到他那裏聚集；他正在海邊上。","notes":[],"heads":["睚魯的女兒和血漏的女人"]},{"n":22,"t":"有一個管會堂的人，名叫睚魯，來見耶穌，就俯伏在他腳前，","notes":[]},{"n":23,"t":"再三地求他，說：「我的小女兒快要死了，求你去按手在她身上，使她痊癒，得以活了。」","notes":[]},{"n":24,"t":"耶穌就和他同去。有許多人跟隨擁擠他。","notes":[]},{"n":25,"t":"有一個女人，患了十二年的血漏，","notes":[]},{"n":26,"t":"在好些醫生手裏受了許多的苦，又花盡了她所有的，一點也不見好，病勢反倒更重了。","notes":[]},{"n":27,"t":"她聽見耶穌的事，就從後頭來，雜在眾人中間，摸耶穌的衣裳，","notes":[]},{"n":28,"t":"意思說：「我只摸他的衣裳，就必痊癒。」","notes":[]},{"n":29,"t":"於是她血漏的源頭立刻乾了；她便覺得身上的災病好了。","notes":[]},{"n":30,"t":"耶穌頓時心裏覺得有能力從自己身上出去，就在眾人中間轉過來，說：「誰摸我的衣裳？」","notes":[]},{"n":31,"t":"門徒對他說：「你看眾人擁擠你，還說『誰摸我』嗎？」","notes":[]},{"n":32,"t":"耶穌周圍觀看，要見做這事的女人。","notes":[]},{"n":33,"t":"那女人知道在自己身上所成的事，就恐懼戰兢，來俯伏在耶穌跟前，將實情全告訴他。","notes":[]},{"n":34,"t":"耶穌對她說：「女兒，你的信救了你，平平安安地回去吧！你的災病痊癒了。」","notes":[]},{"n":35,"t":"還說話的時候，有人從管會堂的家裏來，說：「你的女兒死了，何必還勞動先生呢？」","notes":[]},{"n":36,"t":"耶穌聽見所說的話，就對管會堂的說：「不要怕，只要信！」","notes":[]},{"n":37,"t":"於是帶著彼得、雅各，和雅各的兄弟約翰同去，不許別人跟隨他。","notes":[]},{"n":38,"t":"他們來到管會堂的家裏；耶穌看見那裏亂嚷，並有人大大地哭泣哀號，","notes":[]},{"n":39,"t":"進到裏面，就對他們說：「為甚麼亂嚷哭泣呢？孩子不是死了，是睡著了。」","notes":[]},{"n":40,"t":"他們就嗤笑耶穌。耶穌把他們都攆出去，就帶著孩子的父母和跟隨的人進了孩子所在的地方，","notes":[]},{"n":41,"t":"就拉著孩子的手，對她說：「大利大，古米！」（翻出來就是說：「閨女，我吩咐你起來！」）","notes":[]},{"n":42,"t":"那閨女立時起來走。他們就大大地驚奇；閨女已經十二歲了。","notes":[]},{"n":43,"t":"耶穌切切地囑咐他們，不要叫人知道這事，又吩咐給她東西吃。","notes":[]}]},"6":{"heading":"拿撒勒人厭棄耶穌","verses":[{"n":1,"t":"耶穌離開那裏，來到自己的家鄉；門徒也跟從他。","notes":[]},{"n":2,"t":"到了安息日，他在會堂裏教訓人。眾人聽見，就甚希奇，說：「這人從哪裏有這些事呢？所賜給他的是甚麼智慧？他手所做的是何等的異能呢？","notes":[]},{"n":3,"t":"這不是那木匠嗎？不是馬利亞的兒子雅各、約西、猶大、西門的長兄嗎？他妹妹們不也是在我們這裏嗎？」他們就厭棄他。","notes":["厭棄他：原文是因他跌倒"]},{"n":4,"t":"耶穌對他們說：「大凡先知，除了本地、親屬、本家之外，沒有不被人尊敬的。」","notes":[]},{"n":5,"t":"耶穌就在那裏不得行甚麼異能，不過按手在幾個病人身上，治好他們。","notes":[]},{"n":6,"t":"他也詫異他們不信，就往周圍鄉村教訓人去了。","notes":[]},{"n":7,"t":"耶穌叫了十二個門徒來，差遣他們兩個兩個地出去，也賜給他們權柄，制伏污鬼；","notes":[],"heads":["耶穌差遣十二門徒"]},{"n":8,"t":"並且囑咐他們：「行路的時候不要帶食物和口袋，腰袋裏也不要帶錢，除了柺杖以外，甚麼都不要帶；","notes":[]},{"n":9,"t":"只要穿鞋，也不要穿兩件褂子」；","notes":[]},{"n":10,"t":"又對他們說：「你們無論到何處，進了人的家，就住在那裏，直到離開那地方。","notes":[]},{"n":11,"t":"何處的人不接待你們，不聽你們，你們離開那裏的時候，就把腳上的塵土跺下去，對他們作見證。」","notes":[]},{"n":12,"t":"門徒就出去傳道，叫人悔改，","notes":[]},{"n":13,"t":"又趕出許多的鬼，用油抹了許多病人，治好他們。","notes":[]},{"n":14,"t":"耶穌的名聲傳揚出來。希律王聽見了，就說：「施洗的約翰從死裏復活了，所以這些異能由他裏面發出來。」","notes":[],"heads":["施洗約翰的死"]},{"n":15,"t":"但別人說：「是以利亞。」又有人說：「是先知，正像先知中的一位。」","notes":[]},{"n":16,"t":"希律聽見卻說：「是我所斬的約翰，他復活了。」","notes":[]},{"n":17,"t":"先是希律為他兄弟腓力的妻子希羅底的緣故，差人去拿住約翰，鎖在監裏，因為希律已經娶了那婦人。","notes":[]},{"n":18,"t":"約翰曾對希律說：「你娶你兄弟的妻子是不合理的。」","notes":[]},{"n":19,"t":"於是希羅底懷恨他，想要殺他，只是不能；","notes":[]},{"n":20,"t":"因為希律知道約翰是義人，是聖人，所以敬畏他，保護他，聽他講論，就多照著行，並且樂意聽他。","notes":["有古卷：游移不定"]},{"n":21,"t":"有一天，恰巧是希律的生日，希律擺設筵席，請了大臣和千夫長，並加利利作首領的。","notes":[]},{"n":22,"t":"希羅底的女兒進來跳舞，使希律和同席的人都歡喜。王就對女子說：「你隨意向我求甚麼，我必給你。」","notes":[]},{"n":23,"t":"又對她起誓說：「隨你向我求甚麼，就是我國的一半，我也必給你。」","notes":[]},{"n":24,"t":"她就出去對她母親說：「我可以求甚麼呢？」她母親說：「施洗約翰的頭。」","notes":[]},{"n":25,"t":"她就急忙進去見王，求他說：「我願王立時把施洗約翰的頭放在盤子裏給我。」","notes":[]},{"n":26,"t":"王就甚憂愁；但因他所起的誓，又因同席的人，就不肯推辭，","notes":[]},{"n":27,"t":"隨即差一個護衛兵，吩咐拿約翰的頭來。護衛兵就去，在監裏斬了約翰，","notes":[]},{"n":28,"t":"把頭放在盤子裏，拿來給女子，女子就給她母親。","notes":[]},{"n":29,"t":"約翰的門徒聽見了，就來把他的屍首領去，葬在墳墓裏。","notes":[]},{"n":30,"t":"使徒聚集到耶穌那裏，將一切所做的事、所傳的道全告訴他。","notes":[],"heads":["耶穌給五千人吃飽"]},{"n":31,"t":"他就說：「你們來，同我暗暗地到曠野地方去歇一歇。」這是因為來往的人多，他們連吃飯也沒有工夫。","notes":[]},{"n":32,"t":"他們就坐船，暗暗地往曠野地方去。","notes":[]},{"n":33,"t":"眾人看見他們去，有許多認識他們的，就從各城步行，一同跑到那裏，比他們先趕到了。","notes":[]},{"n":34,"t":"耶穌出來，見有許多的人，就憐憫他們，因為他們如同羊沒有牧人一般，於是開口教訓他們許多道理。","notes":[]},{"n":35,"t":"天已經晚了，門徒進前來，說：「這是野地，天已經晚了，","notes":[]},{"n":36,"t":"請叫眾人散開，他們好往四面鄉村裏去，自己買甚麼吃。」","notes":[]},{"n":37,"t":"耶穌回答說：「你們給他們吃吧。」門徒說：「我們可以去買二十兩銀子的餅給他們吃嗎？」","notes":[]},{"n":38,"t":"耶穌說：「你們有多少餅，可以去看看。」他們知道了，就說：「五個餅，兩條魚。」","notes":[]},{"n":39,"t":"耶穌吩咐他們，叫眾人一幫一幫地坐在青草地上。","notes":[]},{"n":40,"t":"眾人就一排一排地坐下，有一百一排的，有五十一排的。","notes":[]},{"n":41,"t":"耶穌拿著這五個餅，兩條魚，望著天祝福，擘開餅，遞給門徒，擺在眾人面前，也把那兩條魚分給眾人。","notes":[]},{"n":42,"t":"他們都吃，並且吃飽了。","notes":[]},{"n":43,"t":"門徒就把碎餅碎魚收拾起來，裝滿了十二個籃子。","notes":[]},{"n":44,"t":"吃餅的男人共有五千。","notes":[]},{"n":45,"t":"耶穌隨即催門徒上船，先渡到那邊伯賽大去，等他叫眾人散開。","notes":[],"heads":["耶穌在海上行走"]},{"n":46,"t":"他既辭別了他們，就往山上去禱告。","notes":[]},{"n":47,"t":"到了晚上，船在海中，耶穌獨自在岸上；","notes":[]},{"n":48,"t":"看見門徒因風不順，搖櫓甚苦。夜裏約有四更天，就在海面上走，往他們那裏去，意思要走過他們去。","notes":[]},{"n":49,"t":"但門徒看見他在海面上走，以為是鬼怪，就喊叫起來；","notes":[]},{"n":50,"t":"因為他們都看見了他，且甚驚慌。耶穌連忙對他們說：「你們放心！是我，不要怕！」","notes":[]},{"n":51,"t":"於是到他們那裏，上了船，風就住了；他們心裏十分驚奇。","notes":[]},{"n":52,"t":"這是因為他們不明白那分餅的事，心裏還是愚頑。","notes":[]},{"n":53,"t":"既渡過去，來到革尼撒勒地方，就靠了岸，","notes":[],"heads":["治好革尼撒勒的病人"]},{"n":54,"t":"一下船，眾人認得是耶穌，","notes":[]},{"n":55,"t":"就跑遍那一帶地方，聽見他在何處，便將有病的人用褥子抬到那裏。","notes":[]},{"n":56,"t":"凡耶穌所到的地方，或村中，或城裏，或鄉間，他們都將病人放在街市上，求耶穌只容他們摸他的衣裳繸子；凡摸著的人就都好了。","notes":[]}]},"7":{"heading":"古人的傳統","verses":[{"n":1,"t":"有法利賽人和幾個文士從耶路撒冷來，到耶穌那裏聚集。","notes":[]},{"n":2,"t":"他們曾看見他的門徒中有人用俗手，就是沒有洗的手，吃飯。（","notes":[]},{"n":3,"t":"原來法利賽人和猶太人都拘守古人的遺傳，若不仔細洗手就不吃飯；","notes":[]},{"n":4,"t":"從市上來，若不洗浴也不吃飯；還有好些別的規矩，他們歷代拘守，就是洗杯、罐、銅器等物。）","notes":[]},{"n":5,"t":"法利賽人和文士問他說：「你的門徒為甚麼不照古人的遺傳，用俗手吃飯呢？」","notes":[]},{"n":6,"t":"耶穌說：「以賽亞指著你們假冒為善之人所說的預言是不錯的。如經上說：這百姓用嘴唇尊敬我，心卻遠離我。","notes":[]},{"n":7,"t":"他們將人的吩咐當作道理教導人，所以拜我也是枉然。","notes":[]},{"n":8,"t":"你們是離棄神的誡命，拘守人的遺傳」；","notes":[]},{"n":9,"t":"又說：「你們誠然是廢棄神的誡命，要守自己的遺傳。","notes":[]},{"n":10,"t":"摩西說：『當孝敬父母』；又說：『咒罵父母的，必治死他。』","notes":[]},{"n":11,"t":"你們倒說：『人若對父母說：我所當奉給你的，已經作了各耳板』（各耳板就是供獻的意思），","notes":[]},{"n":12,"t":"以後你們就不容他再奉養父母。","notes":[]},{"n":13,"t":"這就是你們承接遺傳，廢了神的道。你們還做許多這樣的事。」","notes":[]},{"n":14,"t":"耶穌又叫眾人來，對他們說：「你們都要聽我的話，也要明白。","notes":[]},{"n":15,"t":"從外面進去的不能污穢人，惟有從裏面出來的乃能污穢人。」","notes":["有古卷加：16有耳可聽的，就應當聽！"]},{"n":17,"t":"耶穌離開眾人，進了屋子，門徒就問他這比喻的意思。","notes":[]},{"n":18,"t":"耶穌對他們說：「你們也是這樣不明白嗎？豈不曉得凡從外面進入的，不能污穢人，","notes":[]},{"n":19,"t":"因為不是入他的心，乃是入他的肚腹，又落到茅廁裏（ 這是說，各樣的食物都是潔淨的）」；","notes":[]},{"n":20,"t":"又說：「從人裏面出來的，那才能污穢人；","notes":[]},{"n":21,"t":"因為從裏面，就是從人心裏，發出惡念、苟合、","notes":[]},{"n":22,"t":"偷盜、凶殺、姦淫、貪婪、邪惡、詭詐、淫蕩、嫉妒、謗讟、驕傲、狂妄。","notes":[]},{"n":23,"t":"這一切的惡都是從裏面出來，且能污穢人。」","notes":[]},{"n":24,"t":"耶穌從那裏起身，往泰爾、西頓的境內去，進了一家，不願意人知道，卻隱藏不住。","notes":[],"heads":["一個婦人的信心"]},{"n":25,"t":"當下，有一個婦人，她的小女兒被污鬼附著，聽見耶穌的事，就來俯伏在他腳前。","notes":[]},{"n":26,"t":"這婦人是希臘人，屬敘利腓尼基族。她求耶穌趕出那鬼離開她的女兒。","notes":[]},{"n":27,"t":"耶穌對她說：「讓兒女們先吃飽，不好拿兒女的餅丟給狗吃。」","notes":[]},{"n":28,"t":"婦人回答說：「主啊，不錯；但是狗在桌子底下也吃孩子們的碎渣兒。」","notes":[]},{"n":29,"t":"耶穌對她說：「因這句話，你回去吧；鬼已經離開你的女兒了。」","notes":[]},{"n":30,"t":"她就回家去，見小孩子躺在床上，鬼已經出去了。","notes":[]},{"n":31,"t":"耶穌又離了泰爾的境界，經過西頓，就從低加坡里境內來到加利利 海。","notes":[],"heads":["耶穌治好耳聾舌結的人"]},{"n":32,"t":"有人帶著一個耳聾舌結的人來見耶穌，求他按手在他身上。","notes":[]},{"n":33,"t":"耶穌領他離開眾人，到一邊去，就用指頭探他的耳朵，吐唾沫抹他的舌頭，","notes":[]},{"n":34,"t":"望天歎息，對他說：「以法大！」就是說：「開了吧！」","notes":[]},{"n":35,"t":"他的耳朵就開了，舌結也解了，說話也清楚了。","notes":[]},{"n":36,"t":"耶穌囑咐他們不要告訴人；但他越發囑咐，他們越發傳揚開了。","notes":[]},{"n":37,"t":"眾人分外希奇，說：「他所做的事都好，他連聾子也叫他們聽見，啞巴也叫他們說話。」","notes":[]}]},"8":{"heading":"耶穌給四千人吃飽","verses":[{"n":1,"t":"那時，又有許多人聚集，並沒有甚麼吃的。耶穌叫門徒來，說：","notes":[]},{"n":2,"t":"「我憐憫這眾人；因為他們同我在這裏已經三天，也沒有吃的了。","notes":[]},{"n":3,"t":"我若打發他們餓著回家，就必在路上困乏，因為其中有從遠處來的。」","notes":[]},{"n":4,"t":"門徒回答說：「在這野地，從哪裏能得餅，叫這些人吃飽呢？」","notes":[]},{"n":5,"t":"耶穌問他們說：「你們有多少餅？」他們說：「七個。」","notes":[]},{"n":6,"t":"他吩咐眾人坐在地上，就拿著這七個餅祝謝了，擘開，遞給門徒，叫他們擺開，門徒就擺在眾人面前。","notes":[]},{"n":7,"t":"又有幾條小魚；耶穌祝了福，就吩咐也擺在眾人面前。","notes":[]},{"n":8,"t":"眾人都吃，並且吃飽了，收拾剩下的零碎，有七筐子。","notes":[]},{"n":9,"t":"人數約有四千。耶穌打發他們走了，","notes":[]},{"n":10,"t":"隨即同門徒上船，來到大瑪努他境內。","notes":[]},{"n":11,"t":"法利賽人出來盤問耶穌，求他從天上顯個神蹟給他們看，想要試探他。","notes":[],"heads":["求主顯個神蹟"]},{"n":12,"t":"耶穌心裏深深地歎息，說：「這世代為甚麼求神蹟呢？我實在告訴你們，沒有神蹟給這世代看。」","notes":[]},{"n":13,"t":"他就離開他們，又上船往海那邊去了。","notes":[]},{"n":14,"t":"門徒忘了帶餅；在船上除了一個餅，沒有別的食物。","notes":[],"heads":["防備法利賽人和希律的酵"]},{"n":15,"t":"耶穌囑咐他們說：「你們要謹慎，防備法利賽人的酵和希律的酵。」","notes":[]},{"n":16,"t":"他們彼此議論說：「這是因為我們沒有餅吧。」","notes":[]},{"n":17,"t":"耶穌看出來，就說：「你們為甚麼因為沒有餅就議論呢？你們還不省悟，還不明白嗎？你們的心還是愚頑嗎？","notes":[]},{"n":18,"t":"你們有眼睛，看不見嗎？有耳朵，聽不見嗎？也不記得嗎？","notes":[]},{"n":19,"t":"我擘開那五個餅分給五千人，你們收拾的零碎裝滿了多少籃子呢？」他們說：「十二個。」","notes":[]},{"n":20,"t":"「又擘開那七個餅分給四千人，你們收拾的零碎裝滿了多少筐子呢？」他們說：「七個。」","notes":[]},{"n":21,"t":"耶穌說：「你們還是不明白嗎？」","notes":[]},{"n":22,"t":"他們來到伯賽大，有人帶一個瞎子來，求耶穌摸他。","notes":[],"heads":["治好伯賽大的瞎子"]},{"n":23,"t":"耶穌拉著瞎子的手，領他到村外，就吐唾沫在他眼睛上，按手在他身上，問他說：「你看見甚麼了？」","notes":[]},{"n":24,"t":"他就抬頭一看，說：「我看見人了；他們好像樹木，並且行走。」","notes":[]},{"n":25,"t":"隨後又按手在他眼睛上，他定睛一看，就復了原，樣樣都看得清楚了。","notes":[]},{"n":26,"t":"耶穌打發他回家，說：「連這村子你也不要進去。」","notes":[]},{"n":27,"t":"耶穌和門徒出去，往凱撒利亞‧腓立比村莊去；在路上問門徒說：「人說我是誰？」","notes":[],"heads":["彼得認耶穌為基督"]},{"n":28,"t":"他們說：「有人說是施洗的約翰；有人說是以利亞；又有人說是先知裏的一位。」","notes":[]},{"n":29,"t":"又問他們說：「你們說我是誰？」彼得回答說：「你是基督。」","notes":[]},{"n":30,"t":"耶穌就禁戒他們，不要告訴人。","notes":[]},{"n":31,"t":"從此，他教訓他們說：「人子必須受許多的苦，被長老、祭司長，和文士棄絕，並且被殺，過三天復活。」","notes":[],"heads":["耶穌預言受難和復活"]},{"n":32,"t":"耶穌明明地說這話，彼得就拉著他，勸他。","notes":[]},{"n":33,"t":"耶穌轉過來，看著門徒，就責備彼得說：「撒但，退我後邊去吧！因為你不體貼神的意思，只體貼人的意思。」","notes":[]},{"n":34,"t":"於是叫眾人和門徒來，對他們說：「若有人要跟從我，就當捨己，背起他的十字架來跟從我。","notes":[]},{"n":35,"t":"因為，凡要救自己生命的，必喪掉生命；凡為我和福音喪掉生命的，必救了生命。","notes":["或譯：靈魂；下同"]},{"n":36,"t":"人就是賺得全世界，賠上自己的生命，有甚麼益處呢？","notes":[]},{"n":37,"t":"人還能拿甚麼換生命呢？","notes":[]},{"n":38,"t":"凡在這淫亂罪惡的世代，把我和我的道當作可恥的，人子在他父的榮耀裏，同聖天使降臨的時候，也要把那人當作可恥的。」","notes":[]}]},"9":{"heading":"耶穌改變形像","verses":[{"n":1,"t":"耶穌又對他們說：「我實在告訴你們，站在這裏的，有人在沒嘗死味以前，必要看見神的國大有能力臨到。」","notes":[]},{"n":2,"t":"過了六天，耶穌帶著彼得、雅各、約翰暗暗地上了高山，就在他們面前變了形像，","notes":[]},{"n":3,"t":"衣服放光，極其潔白，地上漂布的，沒有一個能漂得那樣白。","notes":[]},{"n":4,"t":"忽然，有以利亞同摩西向他們顯現，並且和耶穌說話。","notes":[]},{"n":5,"t":"彼得對耶穌說：「拉比，我們在這裏真好！可以搭三座棚，一座為你，一座為摩西，一座為以利亞。」","notes":["就是夫子"]},{"n":6,"t":"彼得不知道說甚麼才好，因為他們甚是懼怕。","notes":[]},{"n":7,"t":"有一朵雲彩來遮蓋他們；也有聲音從雲彩裏出來，說：「這是我的愛子，你們要聽他。」","notes":[]},{"n":8,"t":"門徒忽然周圍一看，不再見一人，只見耶穌同他們在那裏。","notes":[]},{"n":9,"t":"下山的時候，耶穌囑咐他們說：「人子還沒有從死裏復活，你們不要將所看見的告訴人。」","notes":[]},{"n":10,"t":"門徒將這話存記在心，彼此議論「從死裏復活」是甚麼意思。","notes":[]},{"n":11,"t":"他們就問耶穌說：「文士為甚麼說以利亞必須先來？」","notes":[]},{"n":12,"t":"耶穌說：「以利亞固然先來復興萬事；經上不是指著人子說，他要受許多的苦被人輕慢呢？","notes":[]},{"n":13,"t":"我告訴你們，以利亞已經來了，他們也任意待他，正如經上所指著他的話。」","notes":[]},{"n":14,"t":"耶穌到了門徒那裏，看見有許多人圍著他們，又有文士和他們辯論。","notes":[],"heads":["治好被污鬼附身的孩子"]},{"n":15,"t":"眾人一見耶穌，都甚希奇，就跑上去問他的安。","notes":[]},{"n":16,"t":"耶穌問他們說：「你們和他們辯論的是甚麼？」","notes":[]},{"n":17,"t":"眾人中間有一個人回答說：「夫子，我帶了我的兒子到你這裏來，他被啞巴鬼附著。","notes":[]},{"n":18,"t":"無論在哪裏，鬼捉弄他，把他摔倒，他就口中流沫，咬牙切齒，身體枯乾。我請過你的門徒把鬼趕出去，他們卻是不能。」","notes":[]},{"n":19,"t":"耶穌說：「噯！不信的世代啊，我在你們這裏要到幾時呢？我忍耐你們要到幾時呢？把他帶到我這裏來吧。」","notes":[]},{"n":20,"t":"他們就帶了他來。他一見耶穌，鬼便叫他重重地抽瘋，倒在地上，翻來覆去，口中流沫。","notes":[]},{"n":21,"t":"耶穌問他父親說：「他得這病有多少日子呢？」回答說：「從小的時候。","notes":[]},{"n":22,"t":"鬼屢次把他扔在火裏、水裏，要滅他。你若能做甚麼，求你憐憫我們，幫助我們。」","notes":[]},{"n":23,"t":"耶穌對他說：「你若能信，在信的人，凡事都能。」","notes":[]},{"n":24,"t":"孩子的父親立時喊著說：「我信！但我信不足，求主幫助。」","notes":["有古卷：立時流淚地喊著說"]},{"n":25,"t":"耶穌看見眾人都跑上來， 就斥責那污鬼，說：「你這聾啞的鬼，我吩咐你從他裏頭出來，再不要進去！」","notes":[]},{"n":26,"t":"那鬼喊叫，使孩子大大地抽了一陣瘋，就出來了。孩子好像死了一般，以致眾人多半說：「他是死了。」","notes":[]},{"n":27,"t":"但耶穌拉著他的手，扶他起來，他就站起來了。","notes":[]},{"n":28,"t":"耶穌進了屋子，門徒就暗暗地問他說：「我們為甚麼不能趕出他去呢？」","notes":[]},{"n":29,"t":"耶穌說：「非用禱告，這一類的鬼總不能出來。」","notes":["有古卷加：禁食二字","或譯：不能趕他 出來"]},{"n":30,"t":"他們離開那地方，經過加利利；耶穌不願意人知道。","notes":[],"heads":["耶穌第二次預言受難和復活"]},{"n":31,"t":"於是教訓門徒，說：「人子將要被交在人手裏，他們要殺害他；被殺以後，過三天他要復活。」","notes":[]},{"n":32,"t":"門徒卻不明白這話，又不敢問他。","notes":[]},{"n":33,"t":"他們來到迦百農。耶穌在屋裏問門徒說：「你們在路上議論的是甚麼？」","notes":[],"heads":["誰最偉大"]},{"n":34,"t":"門徒不作聲，因為他們在路上彼此爭論誰為大。","notes":[]},{"n":35,"t":"耶穌坐下，叫十二個門徒來，說：「若有人願意作首先的，他必作眾人末後的，作眾人的用人。」","notes":[]},{"n":36,"t":"於是領過一個小孩子來，叫他站在門徒中間，又抱起他來，對他們說：","notes":[]},{"n":37,"t":"「凡為我名接待一個像這小孩子的，就是接待我；凡接待我的，不是接待我，乃是接待那差我來的。」","notes":[]},{"n":38,"t":"約翰對耶穌說：「夫子，我們看見一個人奉你的名趕鬼，我們就禁止他，因為他不跟從我們。」","notes":[],"heads":["不敵擋我們就是幫助我們"]},{"n":39,"t":"耶穌說：「不要禁止他；因為沒有人奉我名行異能，反倒輕易毀謗我。","notes":[]},{"n":40,"t":"不敵擋我們的，就是幫助我們的。","notes":[]},{"n":41,"t":"凡因你們是屬基督，給你們一杯水喝的，我實在告訴你們，他不能不得賞賜。」","notes":[]},{"n":42,"t":"「凡使這信我的一個小子跌倒的，倒不如把大磨石拴在這人的頸項上，扔在海裏。","notes":[],"heads":["罪的誘惑"]},{"n":43,"t":"倘若你一隻手叫你跌倒，就把它砍下來；","notes":[]},{"n":44,"t":"你缺了肢體進入永生，強如有兩隻手落到地獄，入那不滅的火裏去。","notes":[]},{"n":45,"t":"倘若你一隻腳叫你跌倒，就把它 砍下來；","notes":[]},{"n":46,"t":"你瘸腿進入永生，強如有兩隻腳被丟在地獄裏。","notes":[]},{"n":47,"t":"倘若你一隻眼叫你跌倒，就去掉它；你只有一隻眼進入神的國，強如有兩隻眼被丟在地獄裏。","notes":[]},{"n":48,"t":"在那裏，蟲是不死的，火是不滅的。","notes":[]},{"n":49,"t":"因為必用火當鹽醃各人。","notes":["有古卷加：凡祭物必用鹽醃。"]},{"n":50,"t":"鹽本是好的，若失了味，可用甚麼叫它再鹹呢？你們裏頭應當有鹽，彼此和睦。」","notes":[]}]},"10":{"heading":"休妻的問題","verses":[{"n":1,"t":"耶穌從那裏起身，來到猶太的境界並約旦河外。眾人又聚集到他那裏，他又照常教訓他們。","notes":[]},{"n":2,"t":"有法利賽人來問他說：「人休妻可以不可以？」意思要試探他。","notes":[]},{"n":3,"t":"耶穌回答說：「摩西吩咐你們的是甚麼？」","notes":[]},{"n":4,"t":"他們說：「摩西許人寫了休書便可以休妻。」","notes":[]},{"n":5,"t":"耶穌說：「摩西因為你們的心硬，所以寫這條例給你們；","notes":[]},{"n":6,"t":"但從起初創造的時候，神造人是造男造女。","notes":[]},{"n":7,"t":"因此，人要離開父母，與妻子連合，二人成為一體。","notes":[]},{"n":8,"t":"既然如此，夫妻不再是兩個人，乃是一體的了。","notes":[]},{"n":9,"t":"所以，神配合的，人不可分開。」","notes":[]},{"n":10,"t":"到了屋裏，門徒就問他這事。","notes":[]},{"n":11,"t":"耶穌對他們說：「凡休妻另娶的，就是犯姦淫，辜負他的妻子；","notes":[]},{"n":12,"t":"妻子若離棄丈夫另嫁，也是犯姦淫了。」","notes":[]},{"n":13,"t":"有人帶著小孩子來見耶穌，要耶穌摸他們，門徒便責備那些人。","notes":[],"heads":["耶穌為小孩祝福"]},{"n":14,"t":"耶穌看見就惱怒，對門徒說：「讓小孩子到我這裏來，不要禁止他們；因為在神國的，正是這樣的人。","notes":[]},{"n":15,"t":"我實在告訴你們，凡要承受神國的，若不像小孩子，斷不能進去。」","notes":[]},{"n":16,"t":"於是抱著小孩子，給他們按手，為他們祝福。","notes":[]},{"n":17,"t":"耶穌出來行路的時候，有一個人跑來，跪在他面前，問他說：「良善的夫子，我當做甚麼事才可以承受永生？」","notes":[],"heads":["財主尋求永生之道"]},{"n":18,"t":"耶穌對他說：「你為甚麼稱我是良善的？除了神一位之外，再沒有良善的。","notes":[]},{"n":19,"t":"誡命你是曉得的：不可殺人；不可姦淫；不可偷盜；不可作假見證；不可虧負人；當孝敬父母。」","notes":[]},{"n":20,"t":"他對耶穌說：「夫子，這一切我從小都遵守了。」","notes":[]},{"n":21,"t":"耶穌看著他，就愛他，對他說：「你還缺少一件：去變賣你所有的，分給窮人，就必有財寶在天上；你還要來跟從我。」","notes":[]},{"n":22,"t":"他聽見這話，臉上就變了色，憂憂愁愁地走了，因為他的產業很多。","notes":[]},{"n":23,"t":"耶穌周圍一看，對門徒說：「有錢財的人進神的國是何等地難哪！」","notes":[]},{"n":24,"t":"門徒希奇他的話。耶穌又對他們說：「小子，倚靠錢財的人進神的國是何等地難哪！","notes":[]},{"n":25,"t":"駱駝穿過針的眼，比財主進神的國還容易呢。」","notes":[]},{"n":26,"t":"門徒就分外希奇，對他說：「這樣誰能得救呢？」","notes":[]},{"n":27,"t":"耶穌看著他們，說：「在人是不能，在神卻不然，因為神凡事都能。」","notes":[]},{"n":28,"t":"彼得就對他說：「看哪，我們已經撇下所有的跟從你了。」","notes":[]},{"n":29,"t":"耶穌說：「我實在告訴你們，人為我和福音撇下房屋，或是弟兄、姊妹、父母、兒女、田地，","notes":[]},{"n":30,"t":"沒有不在今世得百倍的，就是房屋、弟兄、姊妹、母親、兒女、田地，並且要受逼迫，在來世必得永生。","notes":[]},{"n":31,"t":"然而，有許多在前的，將要在後，在後的，將要在前。」","notes":[]},{"n":32,"t":"他們行路上耶路撒冷去。耶穌在前頭走，門徒就希奇，跟從的人也害怕。耶穌又叫過十二個門徒來，把自己將要遭遇的事告訴他們說：","notes":[],"heads":["耶穌第三次預言受難和復活"]},{"n":33,"t":"「看哪，我們上耶路撒冷去，人子將要被交給祭司長和文士，他們要定他死罪，交給外邦人。","notes":[]},{"n":34,"t":"他們要戲弄他，吐唾沫在他臉上，鞭打他，殺害他。過了三天，他要復活。」","notes":[]},{"n":35,"t":"西庇太的兒子雅各、約翰進前來，對耶穌說：「夫子，我們無論求你甚麼，願你給我們做。」","notes":[],"heads":["雅各和約翰的要求"]},{"n":36,"t":"耶穌說：「要我給你們做甚麼？」","notes":[]},{"n":37,"t":"他們說：「賜我們在你的榮耀裏，一個坐在你右邊，一個坐在你左邊。」","notes":[]},{"n":38,"t":"耶穌說：「你們不知道所求的是甚麼。我所喝的杯，你們能喝嗎？我所受的洗，你們能受嗎？」","notes":[]},{"n":39,"t":"他們說：「我們能。」耶穌說：「我所喝的杯，你們也要喝；我所受的洗，你們也要受；","notes":[]},{"n":40,"t":"只是坐在我的左右，不是我可以賜的，乃是為誰預備的，就賜給誰。」","notes":[]},{"n":41,"t":"那十個門徒聽見，就惱怒雅各、約翰。","notes":[]},{"n":42,"t":"耶穌叫他們來，對他們說：「你們知道，外邦人有尊為君王的，治理他們，有大臣操權管束他們。","notes":[]},{"n":43,"t":"只是在你們中間，不是這樣。你們中間，誰願為大，就必作你們的用人；","notes":[]},{"n":44,"t":"在你們中間，誰願為首，就必作眾人的僕人。","notes":[]},{"n":45,"t":"因為人子來，並不是要受人的服事，乃是要服事人，並且要捨命作多人的贖價。」","notes":[]},{"n":46,"t":"到了耶利哥；耶穌同門徒並許多人出耶利哥的時候，有一個討飯的瞎子，是底買的兒子巴底買，坐在路旁。","notes":[],"heads":["治好瞎子巴底買"]},{"n":47,"t":"他聽見是拿撒勒的耶穌，就喊著說：「大衛的子孫耶穌啊！可憐我吧！」","notes":[]},{"n":48,"t":"有許多人責備他，不許他作聲。他卻越發大聲喊著說：「大衛的子孫哪，可憐我吧！」","notes":[]},{"n":49,"t":"耶穌就站住，說：「叫過他來。」他們就叫那瞎子，對他說：「放心，起來！他叫你啦。」","notes":[]},{"n":50,"t":"瞎子就丟下衣服，跳起來，走到耶穌那裏。","notes":[]},{"n":51,"t":"耶穌說：「要我為你做甚麼？」瞎子說：「拉波尼，我要能看見。」","notes":["就是夫子"]},{"n":52,"t":"耶穌說：「你去吧！你的信救了你了。」瞎子立刻看見了，就在路上跟隨耶穌。","notes":[]}]},"11":{"heading":"光榮地進耶路撒冷","verses":[{"n":1,"t":"耶穌和門徒將近耶路撒冷，到了伯法其和伯大尼，在橄欖山那裏；耶穌就打發兩個門徒，","notes":[]},{"n":2,"t":"對他們說：「你們往對面村子裏去，一進去的時候，必看見一匹驢駒拴在那裏，是從來沒有人騎過的，可以解開，牽來。","notes":[]},{"n":3,"t":"若有人對你們說：『為甚麼做這事？』你們就說：『主要用牠。 』那人必立時讓你們牽來。」","notes":[]},{"n":4,"t":"他們去了，便看見一匹驢駒拴在門外街道上，就把牠解開。","notes":[]},{"n":5,"t":"在那裏站著的人，有幾個說：「你們解驢駒做甚麼？」","notes":[]},{"n":6,"t":"門徒照著耶穌所說的回答，那些人就任憑他們牽去了。","notes":[]},{"n":7,"t":"他們把驢駒牽到耶穌那裏，把自己的衣服搭在上面，耶穌就騎上。","notes":[]},{"n":8,"t":"有許多人把衣服鋪在路上，也有人把田間的樹枝砍下來，鋪在路上。","notes":[]},{"n":9,"t":"前行後隨的人都喊著說：和散那 ！奉主名來的是應當稱頌的！","notes":["和散那：原有求救的意思，在此乃是稱頌的話"]},{"n":10,"t":"那將要來的我祖大衛之國是應當稱頌的！高高在上和散那！","notes":[]},{"n":11,"t":"耶穌進了耶路撒冷，入了聖殿，周圍看了各樣物件。天色已晚，就和十二個門徒出城，往伯大尼去了。","notes":[]},{"n":12,"t":"第二天，他們從伯大尼出來，耶穌餓了。","notes":[],"heads":["咒詛無花果樹"]},{"n":13,"t":"遠遠地看見一棵無花果樹，樹上有葉子，就往那裏去，或者在樹上可以找著甚麼。到了樹下，竟找不著甚麼，不過有葉子，因為不是收無花果的時候。","notes":[]},{"n":14,"t":"耶穌就對樹說：「從今以後，永沒有人吃你的果子。」他的門徒也聽見了。","notes":[]},{"n":15,"t":"他們來到耶路撒冷。耶穌進入聖殿，趕出殿裏做買賣的人，推倒兌換銀錢之人的桌子和賣鴿子之人的凳子；","notes":[],"heads":["潔淨聖殿"]},{"n":16,"t":"也不許人拿著器具從殿裏經過；","notes":[]},{"n":17,"t":"便教訓他們說：「經上不是記著說：我的殿必稱為萬國禱告的殿嗎？你們倒使它 成為賊窩了。」","notes":[]},{"n":18,"t":"祭司長和文士聽見這話，就想法子要除滅耶穌，卻又怕他，因為眾人都希奇他的教訓。","notes":[]},{"n":19,"t":"每天晚上，耶穌出城去。","notes":[]},{"n":20,"t":"早晨，他們從那裏經過，看見無花果樹連根都枯乾了。","notes":[],"heads":["從無花果樹得教訓"]},{"n":21,"t":"彼得想起耶穌的話來，就對他說：「拉比，請看！你所咒詛的無花果樹已經枯乾了。」","notes":[]},{"n":22,"t":"耶穌回答說：「你們當信服神。","notes":[]},{"n":23,"t":"我實在告訴你們，無論何人對這座山說：『你挪開此地，投在海裏！』他若心裏不疑惑，只信他所說的必成，就必給他成了。","notes":[]},{"n":24,"t":"所以我告訴你們，凡你們禱告祈求的，無論是甚麼，只要信是得著的，就必得著。","notes":[]},{"n":25,"t":"你們站著禱告的時候，若想起有人得罪你們，就當饒恕他，好叫你們在天上的父也饒恕你們的過犯。","notes":[]},{"n":26,"t":"你們若不饒恕人，你們在天上的父也不饒恕你們的過犯。 」","notes":["有古卷無此節"]},{"n":27,"t":"他們又來到耶路撒冷。耶穌在殿裏行走的時候，祭司長和文士並長老進前來，","notes":[],"heads":["質問耶穌的權柄"]},{"n":28,"t":"問他說：「你仗著甚麼權柄做這些事？給你這權柄的是誰呢？」","notes":[]},{"n":29,"t":"耶穌對他們說：「我要問你們一句話，你們回答我，我就告訴你們我仗著甚麼權柄做這些事。","notes":[]},{"n":30,"t":"約翰的洗禮是從天上來的？是從人間來的呢？你們可以回答我。」","notes":[]},{"n":31,"t":"他們彼此商議說：「我們若說『從天上來』，他必說：『這樣，你們為甚麼不信他呢？』","notes":[]},{"n":32,"t":"若說『從人間來』，卻又怕百姓，因為眾人真以約翰為先知。」","notes":[]},{"n":33,"t":"於是回答耶穌說：「我們不知道。」耶穌說：「我也不告訴你們我仗著甚麼權柄做這些事。」","notes":[]}]},"12":{"heading":"凶惡園戶的比喻","verses":[{"n":1,"t":"耶穌就用比喻對他們說：「有人栽了一個葡萄園，周圍圈上籬笆，挖了一個壓酒池，蓋了一座樓，租給園戶，就往外國去了。","notes":[]},{"n":2,"t":"到了時候，打發一個僕人到園戶那裏，要從園戶收葡萄園的果子。","notes":[]},{"n":3,"t":"園戶拿住他，打了他，叫他空手回去。","notes":[]},{"n":4,"t":"再打發一個僕人到他們那裏。他們打傷他的頭，並且凌辱他。","notes":[]},{"n":5,"t":"又打發一個僕人去，他們就殺了他。後又打發好些僕人去，有被他們打的，有被他們殺的。","notes":[]},{"n":6,"t":"園主還有一位是他的愛子，末後又打發他去，意思說：『他們必尊敬我的兒子。』","notes":[]},{"n":7,"t":"不料，那些園戶彼此說：『這是承受產業的。來吧，我們殺他，產業就歸我們了！』","notes":[]},{"n":8,"t":"於是拿住他，殺了他，把他丟在園外。","notes":[]},{"n":9,"t":"這樣，葡萄園的主人要怎麼辦呢？他要來除滅那些園戶，將葡萄園轉給別人。","notes":[]},{"n":10,"t":"經上寫著說：匠人所棄的石頭已作了房角的頭塊石頭。","notes":[]},{"n":11,"t":"這是主所做的，在我們眼中看為希奇。這經你們沒有念過嗎？」","notes":[]},{"n":12,"t":"他們看出這比喻是指著他們說的，就想要捉拿他，只是懼怕百姓，於是離開他走了。","notes":[]},{"n":13,"t":"後來，他們打發幾個法利賽人和幾個希律黨的人到耶穌那裏，要就著他的話陷害他。","notes":[],"heads":["納稅給凱撒的問題"]},{"n":14,"t":"他們來了，就對他說：「夫子，我們知道你是誠實的，甚麼人你都不徇情面；因為你不看人的外貌，乃是誠誠實實傳神的道。納稅給凱撒可以不可以？","notes":[]},{"n":15,"t":"我們該納不該納？」耶穌知道他們的假意，就對他們說：「你們為甚麼試探我？拿一個銀錢來給我看！」","notes":[]},{"n":16,"t":"他們就拿了來。耶穌說：「這像和這號是誰的？」他們說：「是凱撒的。」","notes":[]},{"n":17,"t":"耶穌說：「凱撒的物當歸給凱撒，神的物當歸給神。」他們就很希奇他。","notes":[]},{"n":18,"t":"撒都該人常說沒有復活的事。他們來問耶穌說：","notes":[],"heads":["復活的問題"]},{"n":19,"t":"「夫子，摩西為我們寫著說：『人若死了，撇下妻子，沒有孩子，他兄弟當娶他的妻，為哥哥生子立後。』","notes":[]},{"n":20,"t":"有弟兄七人，第一個娶了妻，死了，沒有留下孩子。","notes":[]},{"n":21,"t":"第二個娶了她，也死了，沒有留下孩子。第三個也是這樣。","notes":[]},{"n":22,"t":"那七個人都沒有留下孩子；末了，那婦人也死了。","notes":[]},{"n":23,"t":"當復活的時候，她是哪一個的妻子呢？因為他們七個人都娶過她。」","notes":[]},{"n":24,"t":"耶穌說：「你們所以錯了，豈不是因為不明白聖經，不曉得神的大能嗎？","notes":[]},{"n":25,"t":"人從死裏復活，也不娶也不嫁，乃像天上的使者一樣。","notes":[]},{"n":26,"t":"論到死人復活，你們沒有念過摩西的書荊棘篇上所載的嗎？神對摩西說：『我是亞伯拉罕的神，以撒的神，雅各的神。』","notes":[]},{"n":27,"t":"神不是死人的神，乃是活人的神。你們是大錯了。」","notes":[]},{"n":28,"t":"有一個文士來，聽見他們辯論，曉得耶穌回答的好，就問他說：「誡命中哪是第一要緊的呢？」","notes":[],"heads":["最大的誡命"]},{"n":29,"t":"耶穌回答說：「第一要緊的就是說：『以色列啊，你要聽，主－我們神是獨一的主。","notes":[]},{"n":30,"t":"你要盡心、盡性、盡意、盡力愛主－你的神。』","notes":[]},{"n":31,"t":"其次就是說：『要愛人如己。 』再沒有比這兩條誡命更大的了。」","notes":[]},{"n":32,"t":"那文士對耶穌說：「夫子說，神是一位，實在不錯；除了他以外，再沒有別的神；","notes":[]},{"n":33,"t":"並且盡心、盡智、盡力愛他，又愛人如己，就比一切燔祭和各樣祭祀好的多。」","notes":[]},{"n":34,"t":"耶穌見他回答的有智慧，就對他說：「你離神的國不遠了。」從此以後，沒有人敢再問他甚麼。","notes":[]},{"n":35,"t":"耶穌在殿裏教訓人，就問他們說：「文士怎麼說基督是大衛的子孫呢？","notes":[],"heads":["大衛子孫的問題"]},{"n":36,"t":"大衛被聖靈感動，說：主對我主說：你坐在我的右邊，等我使你仇敵作你的腳凳。","notes":[]},{"n":37,"t":"大衛既自己稱他為主，他怎麼又是大衛的子孫呢？」眾人都喜歡聽他。","notes":[]},{"n":38,"t":"耶穌在教訓之間，說：「你們要防備文士；他們好穿長衣遊行，喜愛人在街市上問他們的安，","notes":[],"heads":["譴責文士"]},{"n":39,"t":"又喜愛會堂裏的高位，筵席上的首座。","notes":[]},{"n":40,"t":"他們侵吞寡婦的家產，假意作很長的禱告。這些人要受更重的刑罰！」","notes":[]},{"n":41,"t":"耶穌對銀庫坐著，看眾人怎樣投錢入庫。有好些財主往裏投了若干的錢。","notes":[],"heads":["寡婦的奉獻"]},{"n":42,"t":"有一個窮寡婦來，往裏投了兩個小錢，就是一個大錢。","notes":[]},{"n":43,"t":"耶穌叫門徒來，說：「我實在告訴你們，這窮寡婦投入庫裏的，比眾人所投的更多。","notes":[]},{"n":44,"t":"因為，他們都是自己有餘，拿出來投在裏頭；但這寡婦是自己不足，把她一切養生的都投上了。」","notes":[]}]},"13":{"heading":"預言聖殿被毀","verses":[{"n":1,"t":"耶穌從殿裏出來的時候，有一個門徒對他說：「夫子，請看，這是何等的石頭！何等的殿宇！」","notes":[]},{"n":2,"t":"耶穌對他說：「你看見這大殿宇嗎？將來在這裏沒有一塊石頭留在石頭上，不被拆毀了。」","notes":[]},{"n":3,"t":"耶穌在橄欖山上對聖殿而坐。彼得、雅各、約翰，和安得烈暗暗地問他說：","notes":[],"heads":["災難的起頭"]},{"n":4,"t":"「請告訴我們，甚麼時候有這些事呢？這一切事將成的時候有甚麼預兆呢？」","notes":[]},{"n":5,"t":"耶穌說：「你們要謹慎，免得有人迷惑你們。","notes":[]},{"n":6,"t":"將來有好些人冒我的名來，說：『我是基督』，並且要迷惑許多人。","notes":[]},{"n":7,"t":"你們聽見打仗和打仗的風聲，不要驚慌。這些事是必須有的，只是末期還沒有到。","notes":[]},{"n":8,"t":"民要攻打民，國要攻打國；多處必有地震、饑荒。這都是災難的起頭。","notes":["災難：原文是生產之難"]},{"n":9,"t":"但你們要謹慎；因為人要把你們交給公會， 並且你們在會堂裏要受鞭打，又為我的緣故站在諸侯與君王面前，對他們作見證。","notes":[]},{"n":10,"t":"然而，福音必須先傳給萬民。","notes":[]},{"n":11,"t":"人把你們拉去交官的時候，不要預先思慮說甚麼；到那時候，賜給你們甚麼話，你們就說甚麼；因為說話的不是你們，乃是聖靈。","notes":[]},{"n":12,"t":"弟兄要把弟兄，父親要把兒子，送到死地；兒女要起來與父母為敵，害死他們；","notes":[]},{"n":13,"t":"並且你們要為我的名被眾人恨惡。惟有忍耐到底的，必然得救。」","notes":[]},{"n":14,"t":"「你們看見那行毀壞可憎的，站在不當站的地方（讀這經的人須要會意）。那時，在猶太的，應當逃到山上；","notes":[],"heads":["大災難"]},{"n":15,"t":"在房上的，不要下來，也不要進去拿家裏的東西；","notes":[]},{"n":16,"t":"在田裏的，也不要回去取衣裳。","notes":[]},{"n":17,"t":"當那些日子，懷孕的和奶孩子的有禍了！","notes":[]},{"n":18,"t":"你們應當祈求，叫這些事不在冬天臨到。","notes":[]},{"n":19,"t":"因為在那些日子必有災難，自從神創造萬物直到如今，並沒有這樣的災難，後來也必沒有。","notes":[]},{"n":20,"t":"若不是主減少那日子，凡有血氣的，總沒有一個得救的；只是為主的選民，他將那日子減少了。","notes":[]},{"n":21,"t":"那時若有人對你們說：『看哪，基督在這裏』，或說：『基督在那裏』，你們不要信！","notes":[]},{"n":22,"t":"因為假基督、假先知將要起來，顯神蹟奇事，倘若能行，就把選民迷惑了。","notes":[]},{"n":23,"t":"你們要謹慎。看哪，凡事我都預先告訴你們了。」","notes":[]},{"n":24,"t":"「在那些日子，那災難以後，日頭要變黑了，月亮也不放光，","notes":[],"heads":["人子的降臨"]},{"n":25,"t":"眾星要從天上墜落，天勢都要震動。","notes":[]},{"n":26,"t":"那時，他們要看見人子有大能力、大榮耀，駕雲降臨。","notes":["馬太二十四章三十節是地上的萬族"]},{"n":27,"t":"他要差遣天使，把他的選民，從四方，從地極直到天邊，都招聚了來。」","notes":["方：原文是風"]},{"n":28,"t":"「你們可以從無花果樹學個比方：當樹枝發嫩長葉的時候，你們就知道夏天近了。","notes":[],"heads":["從無花果樹學個比方"]},{"n":29,"t":"這樣，你們幾時看見這些事成就，也該知道人子近了，正在門口了。","notes":["人子：或譯神的國"]},{"n":30,"t":"我實在告訴你們，這世代還沒有過去，這些事都要成就。","notes":[]},{"n":31,"t":"天地要廢去，我的話卻不能廢去。」","notes":[]},{"n":32,"t":"「但那日子，那時辰，沒有人知道，連天上的使者也不知道，子也不知道，惟有父知道。","notes":[],"heads":["那日那時沒有人知道"]},{"n":33,"t":"你們要謹慎，警醒祈禱，因為你們不曉得那日期幾時來到。","notes":[]},{"n":34,"t":"這事正如一個人離開本家，寄居外邦，把權柄交給僕人，分派各人當做的工，又吩咐看門的警醒。","notes":[]},{"n":35,"t":"所以，你們要警醒；因為你們不知道家主甚麼時候來，或晚上，或半夜，或雞叫，或早晨；","notes":[]},{"n":36,"t":"恐怕他忽然來到，看見你們睡著了。","notes":[]},{"n":37,"t":"我對你們所說的話，也是對眾人說：要警醒！」","notes":[]}]},"14":{"heading":"殺害耶穌的陰謀","verses":[{"n":1,"t":"過兩天是逾越節，又是除酵節，祭司長和文士想法子怎麼用詭計捉拿耶穌，殺他。","notes":[]},{"n":2,"t":"只是說：「當節的日子不可，恐怕百姓生亂。」","notes":[]},{"n":3,"t":"耶穌在伯大尼長大痲瘋的西門家裏坐席的時候，有一個女人拿著一玉瓶至貴的真哪噠香膏來，打破玉瓶，把膏澆在耶穌的頭上。","notes":[],"heads":["在伯大尼受膏"]},{"n":4,"t":"有幾個人心中很不喜悅，說：「何用這樣枉費香膏呢？","notes":[]},{"n":5,"t":"這香膏可以賣三十多兩銀子賙濟窮人。」他們就向那女人生氣。","notes":[]},{"n":6,"t":"耶穌說：「由她吧！為甚麼難為她呢？她在我身上做的是一件美事。","notes":[]},{"n":7,"t":"因為常有窮人和你們同在，要向他們行善隨時都可以；只是你們不常有我。","notes":[]},{"n":8,"t":"她所做的，是盡她所能的；她是為我安葬的事把香膏預先澆在我身上。","notes":[]},{"n":9,"t":"我實在告訴你們，普天之下，無論在甚麼地方傳這福音，也要述說這女人所做的，以為記念。」","notes":[]},{"n":10,"t":"十二門徒之中，有一個加略人猶大去見祭司長，要把耶穌交給他們。","notes":[],"heads":["猶大出賣耶穌"]},{"n":11,"t":"他們聽見就歡喜，又應許給他銀子；他就尋思如何得便把耶穌交給他們。","notes":[]},{"n":12,"t":"除酵節的第一天，就是宰逾越羊羔的那一天，門徒對耶穌說：「你吃逾越節的筵席要我們往哪裏去預備呢？」","notes":[],"heads":["和門徒同度逾越節"]},{"n":13,"t":"耶穌就打發兩個門徒，對他們說：「你們進城去，必有人拿著一瓶水迎面而來，你們就跟著他。","notes":[]},{"n":14,"t":"他進哪家去，你們就對那家的主人說：『夫子說：客房在哪裏？我與門徒好在那裏吃逾越節的筵席。』","notes":[]},{"n":15,"t":"他必指給你們擺設整齊的一間大樓，你們就在那裏為我們預備。」","notes":[]},{"n":16,"t":"門徒出去，進了城，所遇見的正如耶穌所說的。他們就預備了逾越節的筵席。","notes":[]},{"n":17,"t":"到了晚上，耶穌和十二個門徒都來了。","notes":[]},{"n":18,"t":"他們坐席正吃的時候，耶穌說：「我實在告訴你們，你們中間有一個與我同吃的人要賣我了。」","notes":[]},{"n":19,"t":"他們就憂愁起來，一個一個地問他說：「是我嗎？」","notes":[]},{"n":20,"t":"耶穌對他們說：「是十二個門徒中同我蘸手在盤子裏的那個人。","notes":[]},{"n":21,"t":"人子必要去世，正如經上指著他所寫的；但賣人子的人有禍了！那人不生在世上倒好。」","notes":[]},{"n":22,"t":"他們吃的時候，耶穌拿起餅來，祝了福，就擘開，遞給他們，說：「你們拿著吃，這是我的身體」；","notes":[],"heads":["設立主的晚餐"]},{"n":23,"t":"又拿起杯來，祝謝了，遞給他們；他們都喝了。","notes":[]},{"n":24,"t":"耶穌說：「這是我立約的血，為多人流出來的。","notes":[]},{"n":25,"t":"我實在告訴你們，我不再喝這葡萄汁，直到我在神的國裏喝新的那日子。」","notes":[]},{"n":26,"t":"他們唱了詩，就出來，往橄欖山去。","notes":[]},{"n":27,"t":"耶穌對他們說：「你們都要跌倒了，因為經上記著說：我要擊打牧人，羊就分散了。","notes":[],"heads":["預言彼得不認主"]},{"n":28,"t":"但我復活以後，要在你們以先往加利利去。」","notes":[]},{"n":29,"t":"彼得說：「眾人雖然跌倒，我總不能。」","notes":[]},{"n":30,"t":"耶穌對他說：「我實在告訴你，就在今天夜裏，雞叫兩遍以先，你要三次不認我。」","notes":[]},{"n":31,"t":"彼得卻極力地說：「我就是必須和你同死，也總不能不認你。」眾門徒都是這樣說。","notes":[]},{"n":32,"t":"他們來到一個地方，名叫客西馬尼。耶穌對門徒說：「你們坐在這裏，等我禱告。」","notes":[],"heads":["在客西馬尼禱告"]},{"n":33,"t":"於是帶著彼得、雅各、約翰同去，就驚恐起來，極其難過，","notes":[]},{"n":34,"t":"對他們說：「我心裏甚是憂傷，幾乎要死；你們在這裏等候，警醒。」","notes":[]},{"n":35,"t":"他就稍往前走，俯伏在地，禱告說：「倘若可行，便叫那時候過去。」","notes":[]},{"n":36,"t":"他說：「阿爸！父啊！在你凡事都能；求你將這杯撤去。然而，不要從我的意思，只要從你的意思。」","notes":[]},{"n":37,"t":"耶穌回來，見他們睡著了，就對彼得說：「西門，你睡覺嗎？不能警醒片時嗎？","notes":[]},{"n":38,"t":"總要警醒禱告，免得入了迷惑。你們心靈固然願意，肉體卻軟弱了。」","notes":[]},{"n":39,"t":"耶穌又去禱告，說的話還是與先前一樣，","notes":[]},{"n":40,"t":"又來見他們睡著了，因為他們的眼睛甚是困倦；他們也不知道怎麼回答。","notes":[]},{"n":41,"t":"第三次來，對他們說：「現在你們仍然睡覺安歇吧！夠了，時候到了。看哪，人子被賣在罪人手裏了。","notes":["吧：或譯嗎？"]},{"n":42,"t":"起來！我們走吧。看哪，那賣我的人近了！ 」","notes":[]},{"n":43,"t":"說話之間，忽然那十二個門徒裏的猶大來了，並有許多人帶著刀棒，從祭司長和文士並長老那裏與他同來。","notes":[],"heads":["耶穌被捕"]},{"n":44,"t":"賣耶穌的人曾給他們一個暗號，說：「我與誰親嘴，誰就是他。你們把他拿住，牢牢靠靠地帶去。」","notes":[]},{"n":45,"t":"猶大來了，隨即到耶穌跟前，說：「拉比」，便與他親嘴。","notes":[]},{"n":46,"t":"他們就下手拿住他。","notes":[]},{"n":47,"t":"旁邊站著的人，有一個拔出刀來，將大祭司的僕人砍了一刀，削掉了他一個耳朵。","notes":[]},{"n":48,"t":"耶穌對他們說：「你們帶著刀棒出來拿我，如同拿強盜嗎？","notes":[]},{"n":49,"t":"我天天教訓人，同你們在殿裏，你們並沒有拿我。但這事成就，為要應驗經上的話。」","notes":[]},{"n":50,"t":"門徒都離開他，逃走了。","notes":[]},{"n":51,"t":"有一個少年人，赤身披著一塊麻布，跟隨耶穌，眾人就捉拿他。","notes":[],"heads":["逃走的少年人"]},{"n":52,"t":"他卻丟了麻布，赤身逃走了。","notes":[]},{"n":53,"t":"他們把耶穌帶到大祭司那裏，又有眾祭司長和長老並文士都來和大祭司一同聚集。","notes":[],"heads":["耶穌在公會裏受審"]},{"n":54,"t":"彼得遠遠地跟著耶穌，一直進入大祭司的院裏，和差役一同坐在火光裏烤火。","notes":[]},{"n":55,"t":"祭司長和全公會尋找見證控告耶穌，要治死他，卻尋不著。","notes":[]},{"n":56,"t":"因為有好些人作假見證告他，只是他們的見證各不相合。","notes":[]},{"n":57,"t":"又有幾個人站起來作假見證告他，說：","notes":[]},{"n":58,"t":"「我們聽見他說：『我要拆毀這人手所造的殿，三日內就另造一座不是人手所造的。』」","notes":[]},{"n":59,"t":"他們就是這麼作見證，也是各不相合。","notes":[]},{"n":60,"t":"大祭司起來站在中間，問耶穌說：「你甚麼都不回答嗎？這些人作見證告你的是甚麼呢？」","notes":[]},{"n":61,"t":"耶穌卻不言語，一句也不回答。大祭司又問他說：「你是那當稱頌者的兒子基督不是？」","notes":[]},{"n":62,"t":"耶穌說：「我是。你們必看見人子坐在那權能者的右邊，駕著天上的雲降臨。」","notes":[]},{"n":63,"t":"大祭司就撕開衣服，說：「我們何必再用見證人呢？","notes":[]},{"n":64,"t":"你們已經聽見他這僭妄的話了。你們的意見如何？」他們都定他該死的罪。","notes":[]},{"n":65,"t":"就有人吐唾沫在他臉上，又蒙著他的臉，用拳頭打他，對他說：「你說預言吧！」差役接過他來，用手掌打他。","notes":[]},{"n":66,"t":"彼得在下邊院子裏；來了大祭司的一個使女，","notes":[],"heads":["彼得三次不認主"]},{"n":67,"t":"見彼得烤火，就看著他，說：「你素來也是同拿撒勒人耶穌一夥的。」","notes":[]},{"n":68,"t":"彼得卻不承認，說：「我不知道，也不明白你說的是甚麼。」於是出來，到了前院， 雞就叫了。","notes":[]},{"n":69,"t":"那使女看見他，又對旁邊站著的人說：「這也是他們一黨的。」","notes":[]},{"n":70,"t":"彼得又不承認。過了不多的時候，旁邊站著的人又對彼得說：「你真是他們一黨的！因為你是加利利人。」","notes":[]},{"n":71,"t":"彼得就發咒起誓地說：「我不認得你們說的這個人。」","notes":[]},{"n":72,"t":"立時雞叫了第二遍。彼得想起耶穌對他所說的話：「雞叫兩遍以先，你要三次不認我。」思想起來，就哭了。","notes":[]}]},"15":{"heading":"耶穌在彼拉多面前受審","verses":[{"n":1,"t":"一到早晨，祭司長和長老、文士、全公會的人大家商議，就把耶穌捆綁，解去交給彼拉多。","notes":[]},{"n":2,"t":"彼拉多問他說：「你是猶太人的王嗎？」耶穌回答說：「你說的是。」","notes":[]},{"n":3,"t":"祭司長告他許多的事。","notes":[]},{"n":4,"t":"彼拉多又問他說：「你看，他們告你這麼多的事，你甚麼都不回答嗎？」","notes":[]},{"n":5,"t":"耶穌仍不回答，以致彼拉多覺得希奇。","notes":[]},{"n":6,"t":"每逢這節期，巡撫照眾人所求的，釋放一個囚犯給他們。","notes":[],"heads":["耶穌被判死刑"]},{"n":7,"t":"有一個人名叫巴拉巴，和作亂的人一同捆綁。他們作亂的時候，曾殺過人。","notes":[]},{"n":8,"t":"眾人上去求巡撫，照常例給他們辦。","notes":[]},{"n":9,"t":"彼拉多說：「你們要我釋放猶太人的王給你們嗎？」","notes":[]},{"n":10,"t":"他原曉得，祭司長是因為嫉妒才把耶穌解了來。","notes":[]},{"n":11,"t":"只是祭司長挑唆眾人，寧可釋放巴拉巴給他們。","notes":[]},{"n":12,"t":"彼拉多又說：「那麼樣，你們所稱為猶太人的王，我怎麼辦他呢？」","notes":[]},{"n":13,"t":"他們又喊著說：「把他釘十字架！」","notes":[]},{"n":14,"t":"彼拉多說：「為甚麼呢？他做了甚麼惡事呢？」他們便極力地喊著說：「把他釘十字架！」","notes":[]},{"n":15,"t":"彼拉多要叫眾人喜悅，就釋放巴拉巴給他們，將耶穌鞭打了，交給人釘十字架。","notes":[]},{"n":16,"t":"兵丁把耶穌帶進衙門院裏，叫齊了全營的兵。","notes":[],"heads":["兵丁戲弄耶穌"]},{"n":17,"t":"他們給他穿上紫袍，又用荊棘編做冠冕給他戴上，","notes":[]},{"n":18,"t":"就慶賀他說：「恭喜，猶太人的王啊！」","notes":[]},{"n":19,"t":"又拿一根葦子打他的頭，吐唾沫在他臉上，屈膝拜他。","notes":[]},{"n":20,"t":"戲弄完了，就給他脫了紫袍，仍穿上他自己的衣服，帶他出去，要釘十字架。","notes":[]},{"n":21,"t":"有一個古利奈人西門，就是亞歷山大和魯孚的父親，從鄉下來，經過那地方，他們就勉強他同去，好背著耶穌的十字架。","notes":[],"heads":["耶穌被釘十字架"]},{"n":22,"t":"他們帶耶穌到了各各他地方（各各他翻出來就是髑髏地），","notes":[]},{"n":23,"t":"拿沒藥調和的酒給耶穌，他卻不受。","notes":[]},{"n":24,"t":"於是將他釘在十字架上，拈鬮分他的衣服，看是誰得甚麼。","notes":[]},{"n":25,"t":"釘他在十字架上是巳初的時候。","notes":[]},{"n":26,"t":"在上面有他的罪狀，寫的是：「猶太人的王。」","notes":[]},{"n":27,"t":"他們又把兩個強盜和他同釘十字架，一個在右邊，一個在左邊。","notes":["有古卷加：28這就應了經上的話說：他被列在罪犯之中。"]},{"n":29,"t":"從那裏經過的人辱罵他，搖著頭說：「咳！你這拆毀聖殿、三日又建造起來的，","notes":[]},{"n":30,"t":"可以救自己，從十字架上下來吧！」","notes":[]},{"n":31,"t":"祭司長和文士也是這樣戲弄他，彼此說：「他救了別人，不能救自己。","notes":[]},{"n":32,"t":"以色列的王基督，現在可以從十字架上下來，叫我們看見，就信了。」那和他同釘的人也是譏誚他。","notes":[]},{"n":33,"t":"從午正到申初，遍地都黑暗了。","notes":[],"heads":["耶穌的死"]},{"n":34,"t":"申初的時候，耶穌大聲喊著說：「以羅伊！以羅伊！拉馬撒巴各大尼？」（翻出來就是：我的神！我的神！為甚麼離棄我？）","notes":[]},{"n":35,"t":"旁邊站著的人，有的聽見就說：「看哪，他叫以利亞呢！」","notes":[]},{"n":36,"t":"有一個人跑去，把海絨蘸滿了醋，綁在葦子上，送給他喝，說：「且等著，看以利亞來不來把他取下。」","notes":[]},{"n":37,"t":"耶穌大聲喊叫，氣就斷了。","notes":[]},{"n":38,"t":"殿裏的幔子從上到下裂為兩半。","notes":[]},{"n":39,"t":"對面站著的百夫長看見耶穌這樣喊叫斷氣，就說：「這人真是神的兒子！」","notes":["有古卷沒有喊叫二字"]},{"n":40,"t":"還有些婦女遠遠地觀看；內中有抹大拉的馬利亞，又有小雅各和約西的母親馬利亞，並有撒羅米，","notes":[]},{"n":41,"t":"就是耶穌在加利利的時候，跟隨他、服事他的那些人，還有同耶穌上耶路撒冷的好些婦女在那裏觀看。","notes":[]},{"n":42,"t":"到了晚上，因為這是預備日，就是安息日的前一日，","notes":[],"heads":["耶穌的安葬"]},{"n":43,"t":"有亞利馬太的約瑟前來，他是尊貴的議士，也是等候神國的。他放膽進去見彼拉多，求耶穌的身體；","notes":[]},{"n":44,"t":"彼拉多詫異耶穌已經死了，便叫百夫長來，問他耶穌死了久不久。","notes":[]},{"n":45,"t":"既從百夫長得知實情，就把耶穌的屍首賜給約瑟。","notes":[]},{"n":46,"t":"約瑟買了細麻布，把耶穌取下來，用細麻布裹好，安放在磐石中鑿出來的墳墓裏，又滾過一塊石頭來擋住墓門。","notes":[]},{"n":47,"t":"抹大拉的馬利亞和約西的母親馬利亞都看見安放他的地方。","notes":[]}]},"16":{"heading":"耶穌復活","verses":[{"n":1,"t":"過了安息日，抹大拉的馬利亞和雅各的母親馬利亞並撒羅米，買了香膏要去膏耶穌的身體。","notes":[]},{"n":2,"t":"七日的第一日清早，出太陽的時候，她們來到墳墓那裏，","notes":[]},{"n":3,"t":"彼此說：「誰給我們把石頭從墓門滾開呢？」","notes":[]},{"n":4,"t":"那石頭原來很大，她們抬頭一看，卻見石頭已經滾開了。","notes":[]},{"n":5,"t":"她們進了墳墓，看見一個少年人坐在右邊，穿著白袍，就甚驚恐。","notes":[]},{"n":6,"t":"那少年人對她們說：「不要驚恐！你們尋找那釘十字架的拿撒勒人耶穌，他已經復活了，不在這裏。請看安放他的地方。","notes":[]},{"n":7,"t":"你們可以去告訴他的門徒和彼得，說：『他在你們以先往加利利去。在那裏你們要見他，正如他從前所告訴你們的。』」","notes":[]},{"n":8,"t":"她們就出來，從墳墓那裏逃跑，又發抖又驚奇，甚麼也不告訴人，因為她們害怕。","notes":[]},{"n":9,"t":"在七日的第一日清早，耶穌復活了，就先向抹大拉的馬利亞顯現（耶穌從她身上曾趕出七個鬼）。","notes":[],"heads":["向抹大拉的馬利亞顯現"]},{"n":10,"t":"她去告訴那向來跟隨耶穌的人；那時他們正哀慟哭泣。","notes":[]},{"n":11,"t":"他們聽見耶穌活了，被馬利亞看見，卻是不信。","notes":[]},{"n":12,"t":"這事以後，門徒中間有兩個人往鄉下去。走路的時候，耶穌變了形像，向他們顯現。","notes":[],"heads":["向兩個門徒顯現"]},{"n":13,"t":"他們就去告訴其餘的門徒；其餘的門徒也是不信。","notes":[]},{"n":14,"t":"後來，十一個門徒坐席的時候，耶穌向他們顯現，責備他們不信，心裏剛硬，因為他們不信那些在他復活以後看見他的人。","notes":[],"heads":["門徒奉差遣"]},{"n":15,"t":"他又對他們說：「你們往普天下去，傳福音給萬民聽。","notes":["萬民：原文是凡受造的"]},{"n":16,"t":"信而受洗的，必然得救；不信的，必被定罪。","notes":[]},{"n":17,"t":"信的人必有神蹟隨著他們，就是奉我的名趕鬼；說新方言；","notes":[]},{"n":18,"t":"手能拿蛇；若喝了甚麼毒物，也必不受害；手按病人，病人就必好了。」","notes":[]},{"n":19,"t":"主耶穌和他們說完了話，後來被接到天上，坐在神的右邊。","notes":[],"heads":["耶穌升天"]},{"n":20,"t":"門徒出去，到處宣傳福音。主和他們同工，用神蹟隨著，證實所傳的道。阿們！","notes":[]}]}},"LUK":{"1":{"heading":"寫給提阿非羅","verses":[{"n":1,"t":"提阿非羅大人哪，有好些人提筆作書，述說在我們中間所成就的事，是照傳道的人從起初親眼看見又傳給我們的。","notes":[],"end":2},{"n":3,"t":"這些事我既從起頭都詳細考察了，就定意要按著次序寫給你，","notes":[]},{"n":4,"t":"使你知道所學之道都是確實的。","notes":[]},{"n":5,"t":"當猶太王希律的時候，亞比雅班裏有一個祭司，名叫撒迦利亞；他妻子是亞倫的後人，名叫伊利莎白。","notes":[],"heads":["預言施洗約翰的誕生"]},{"n":6,"t":"他們二人在神面前都是義人，遵行主的一切誡命禮儀，沒有可指摘的，","notes":[]},{"n":7,"t":"只是沒有孩子；因為伊利莎白不生育，兩個人又年紀老邁了。","notes":[]},{"n":8,"t":"撒迦利亞按班次在神面前供祭司的職分，","notes":[]},{"n":9,"t":"照祭司的規矩掣籤，得進主殿燒香。","notes":[]},{"n":10,"t":"燒香的時候，眾百姓在外面禱告。","notes":[]},{"n":11,"t":"有主的使者站在香壇的右邊，向他顯現。","notes":[]},{"n":12,"t":"撒迦利亞看見，就驚慌害怕。","notes":[]},{"n":13,"t":"天使對他說：「撒迦利亞，不要害怕，因為你的祈禱已經被聽見了。你的妻子伊利莎白要給你生一個兒子，你要給他起名叫約翰。","notes":[]},{"n":14,"t":"你必歡喜快樂；有許多人因他出世，也必喜樂。","notes":[]},{"n":15,"t":"他在主面前將要為大，淡酒濃酒都不喝，從母腹裏就被聖靈充滿了。","notes":[]},{"n":16,"t":"他要使許多以色列人回轉，歸於主－他們的神。","notes":[]},{"n":17,"t":"他必有以利亞的心志能力，行在主的前面，叫為父的心轉向兒女，叫悖逆的人轉從義人的智慧，又為主預備合用的百姓。」","notes":[]},{"n":18,"t":"撒迦利亞對天使說：「我憑著甚麼可知道這事呢？我已經老了，我的妻子也年紀老邁了。」","notes":[]},{"n":19,"t":"天使回答說：「我是站在神面前的加百列，奉差而來對你說話，將這好信息報給你。","notes":[]},{"n":20,"t":"到了時候，這話必然應驗；只因你不信，你必啞巴，不能說話，直到這事成就的日子。」","notes":[]},{"n":21,"t":"百姓等候撒迦利亞，詫異他許久在殿裏。","notes":[]},{"n":22,"t":"及至他出來，不能和他們說話，他們就知道他在殿裏見了異象；因為他直向他們打手式，竟成了啞巴。","notes":[]},{"n":23,"t":"他供職的日子已滿，就回家去了。","notes":[]},{"n":24,"t":"這些日子以後，他的妻子伊利莎白懷了孕，就隱藏了五個月，","notes":[]},{"n":25,"t":"說：「主在眷顧我的日子，這樣看待我，要把我在人間的羞恥除掉。」","notes":[]},{"n":26,"t":"到了第六個月，天使加百列奉神的差遣往加利利的一座城去（這城名叫拿撒勒），","notes":[],"heads":["預言耶穌的降生"]},{"n":27,"t":"到一個童女那裏，是已經許配大衛家的一個人，名叫約瑟。童女的名字叫馬利亞；","notes":[]},{"n":28,"t":"天使進去，對她說：「蒙大恩的女子，我問你安，主和你同在了！」","notes":[]},{"n":29,"t":"馬利亞因這話就很驚慌，又反覆思想這樣問安是甚麼意思。","notes":[]},{"n":30,"t":"天使對她說：「馬利亞，不要怕！你在神面前已經蒙恩了。","notes":[]},{"n":31,"t":"你要懷孕生子，可以給他起名叫耶穌。","notes":[]},{"n":32,"t":"他要為大，稱為至高者的兒子；主神要把他祖大衛的位給他。","notes":[]},{"n":33,"t":"他要作雅各家的王，直到永遠；他的國也沒有窮盡。」","notes":[]},{"n":34,"t":"馬利亞對天使說：「我沒有出嫁，怎麼有這事呢？」","notes":[]},{"n":35,"t":"天使回答說：「聖靈要臨到你身上，至高者的能力要蔭庇你，因此所要生的聖者必稱為神的兒子 。","notes":["或譯：所要生的，必稱為聖，稱為神的兒子"]},{"n":36,"t":"況且你的親戚伊利莎白，在年老的時候也懷了男胎，就是那素來稱為不生育的，現在有孕六個月了。","notes":[]},{"n":37,"t":"因為，出於神的話，沒有一句不帶能力的。」","notes":[]},{"n":38,"t":"馬利亞說：「我是主的使女，情願照你的話成就在我身上。」天使就離開她去了。","notes":[]},{"n":39,"t":"那時候，馬利亞起身，急忙往山地裏去，來到猶大的一座城；","notes":[],"heads":["馬利亞訪問伊利莎白"]},{"n":40,"t":"進了撒迦利亞的家，問伊利莎白安。","notes":[]},{"n":41,"t":"伊利莎白一聽馬利亞問安，所懷的胎就在腹裏跳動。伊利莎白且被聖靈充滿，","notes":[]},{"n":42,"t":"高聲喊著說：「你在婦女中是有福的！你所懷的胎也是有福的！","notes":[]},{"n":43,"t":"我主的母到我這裏來，這是從哪裏得的呢？","notes":[]},{"n":44,"t":"因為你問安的聲音一入我耳，我腹裏的胎就歡喜跳動。","notes":[]},{"n":45,"t":"這相信的女子是有福的！因為主對她所說的話都要應驗。」","notes":[]},{"n":46,"t":"馬利亞說：我心尊主為大；","notes":[],"heads":["馬利亞的尊主頌"]},{"n":47,"t":"我靈以神我的救主為樂；","notes":[]},{"n":48,"t":"因為他顧念他使女的卑微；從今以後，萬代要稱我有福。","notes":[]},{"n":49,"t":"那有權能的，為我成就了大事；他的名為聖。","notes":[]},{"n":50,"t":"他憐憫敬畏他的人，直到世世代代。","notes":[]},{"n":51,"t":"他用膀臂施展大能；那狂傲的人正心裏妄想就被他趕散了。","notes":[]},{"n":52,"t":"他叫有權柄的失位，叫卑賤的升高；","notes":[]},{"n":53,"t":"叫飢餓的得飽美食，叫富足的空手回去。","notes":[]},{"n":54,"t":"他扶助了他的僕人以色列，","notes":[]},{"n":55,"t":"為要記念亞伯拉罕和他的後裔，施憐憫直到永遠，正如從前對我們列祖所說的話。","notes":[]},{"n":56,"t":"馬利亞和伊利莎白同住，約有三個月，就回家去了。","notes":[]},{"n":57,"t":"伊利莎白的產期到了，就生了一個兒子。","notes":[],"heads":["施洗約翰的出生"]},{"n":58,"t":"鄰里親族聽見主向她大施憐憫，就和她一同歡樂。","notes":[]},{"n":59,"t":"到了第八日，他們來要給孩子行割禮，並要照他父親的名字叫他撒迦利亞。","notes":[]},{"n":60,"t":"他母親說：「不可！要叫他約翰。」","notes":[]},{"n":61,"t":"他們說：「你親族中沒有叫這名字的。」","notes":[]},{"n":62,"t":"他們就向他父親打手式，問他要叫這孩子甚麼名字。","notes":[]},{"n":63,"t":"他要了一塊寫字的板，就寫上，說：「他的名字是約翰。」他們便都希奇。","notes":[]},{"n":64,"t":"撒迦利亞的口立時開了，舌頭也舒展了，就說出話來，稱頌神。","notes":[]},{"n":65,"t":"周圍居住的人都懼怕；這一切的事就傳遍了猶太的山地。","notes":[]},{"n":66,"t":"凡聽見的人都將這事放在心裏，說：「這個孩子將來怎麼樣呢？因為有主與他同在。」","notes":[]},{"n":67,"t":"他父親撒迦利亞被聖靈充滿了，就預言說：","notes":[],"heads":["撒迦利亞的預言"]},{"n":68,"t":"主－以色列的神是應當稱頌的！因他眷顧他的百姓，為他們施行救贖，","notes":[]},{"n":69,"t":"在他僕人大衛家中，為我們興起了拯救的角，","notes":[]},{"n":70,"t":"正如主藉著從創世以來聖先知的口所說的話，","notes":[]},{"n":71,"t":"拯救我們脫離仇敵和一切恨我們之人的手，","notes":[]},{"n":72,"t":"向我們列祖施憐憫，記念他的聖約－","notes":[]},{"n":73,"t":"就是他對我們祖宗亞伯拉罕所起的誓－","notes":[]},{"n":74,"t":"叫我們既從仇敵手中被救出來，","notes":[]},{"n":75,"t":"就可以終身在他面前，坦然無懼地用聖潔、公義事奉他。","notes":[]},{"n":76,"t":"孩子啊！你要稱為至高者的先知；因為你要行在主的前面，預備他的道路，","notes":[]},{"n":77,"t":"叫他的百姓因罪得赦，就知道救恩。","notes":[]},{"n":78,"t":"因我們神憐憫的心腸，叫清晨的日光從高天臨到我們，","notes":[]},{"n":79,"t":"要照亮坐在黑暗中死蔭裏的人，把我們的腳引到平安的路上。","notes":[]},{"n":80,"t":"那孩子漸漸長大，心靈強健，住在曠野，直到他顯明在以色列人面前的日子。","notes":[]}]},"2":{"heading":"耶穌降生","verses":[{"n":1,"t":"當那些日子，凱撒奧古斯都有旨意下來，叫天下人民都報名上冊。","notes":[]},{"n":2,"t":"這是居里扭作敘利亞巡撫的時候，頭一次行報名上冊的事。","notes":[]},{"n":3,"t":"眾人各歸各城，報名上冊。","notes":[]},{"n":4,"t":"約瑟也從加利利的拿撒勒城上猶太去，到了大衛的城，名叫伯利恆，因他本是大衛一族一家的人，","notes":[]},{"n":5,"t":"要和他所聘之妻馬利亞一同報名上冊。那時馬利亞的身孕已經重了。","notes":[]},{"n":6,"t":"他們在那裏的時候，馬利亞的產期到了，","notes":[]},{"n":7,"t":"就生了頭胎的兒子，用布包起來，放在馬槽裏，因為客店裏沒有地方。","notes":[]},{"n":8,"t":"在伯利恆之野地裏有牧羊的人，夜間按著更次看守羊群。","notes":[],"heads":["天使報喜訊給牧羊的人"]},{"n":9,"t":"有主的使者站在他們旁邊，主的榮光四面照著他們；牧羊的人就甚懼怕。","notes":[]},{"n":10,"t":"那天使對他們說：「不要懼怕！我報給你們大喜的信息，是關乎萬民的；","notes":[]},{"n":11,"t":"因今天在大衛的城裏，為你們生了救主，就是主基督。","notes":[]},{"n":12,"t":"你們要看見一個嬰孩，包著布，臥在馬槽裏，那就是記號了。」","notes":[]},{"n":13,"t":"忽然，有一大隊天兵同那天使讚美神說：","notes":[]},{"n":14,"t":"在至高之處榮耀歸與神！在地上平安歸與他所喜悅的人 ！","notes":["有古卷：喜悅歸與人"]},{"n":15,"t":"眾天使離開他們，升天去了。牧羊的人彼此說：「我們往伯利恆去，看看所成的事，就是主所指示我們的。」","notes":[]},{"n":16,"t":"他們急忙去了，就尋見馬利亞和約瑟，又有那嬰孩臥在馬槽裏；","notes":[]},{"n":17,"t":"既然看見，就把天使論這孩子的話傳開了。","notes":[]},{"n":18,"t":"凡聽見的，就詫異牧羊之人對他們所說的話。","notes":[]},{"n":19,"t":"馬利亞卻把這一切的事存在心裏，反覆思想。","notes":[]},{"n":20,"t":"牧羊的人回去了，因所聽見所看見的一切事，正如天使向他們所說的，就歸榮耀與神，讚美他。","notes":[]},{"n":21,"t":"滿了八天，就給孩子行割禮，與他起名叫耶穌；這就是沒有成胎以前，天使所起的名。","notes":[]},{"n":22,"t":"按摩西律法滿了潔淨的日子，他們帶著孩子上耶路撒冷去，要把他獻與主，（","notes":[],"heads":["在聖殿裏獻與主"]},{"n":23,"t":"正如主的律法上所記：「凡頭生的男子必稱聖歸主。」）","notes":[]},{"n":24,"t":"又要照主的律法上所說，或用一對斑鳩，或用兩隻雛鴿獻祭。","notes":[]},{"n":25,"t":"在耶路撒冷有一個人，名叫西面；這人又公義又虔誠，素常盼望以色列的安慰者來到，又有聖靈在他身上。","notes":[]},{"n":26,"t":"他得了聖靈的啟示，知道自己未死以前，必看見主所立的基督。","notes":[]},{"n":27,"t":"他受了聖靈的感動，進入聖殿，正遇見耶穌的父母抱著孩子進來，要照律法的規矩辦理。","notes":[]},{"n":28,"t":"西面就用手接過他來，稱頌神說：","notes":[]},{"n":29,"t":"主啊！如今可以照你的話，釋放僕人安然去世；","notes":[]},{"n":30,"t":"因為我的眼睛已經看見你的救恩－","notes":[]},{"n":31,"t":"就是你在萬民面前所預備的：","notes":[]},{"n":32,"t":"是照亮外邦人的光，又是你民以色列的榮耀。","notes":[]},{"n":33,"t":"孩子的父母因這論耶穌的話就希奇。","notes":[]},{"n":34,"t":"西面給他們祝福，又對孩子的母親馬利亞說：「這孩子被立，是要叫以色列中許多人跌倒，許多人興起；又要作毀謗的話柄，叫許多人心裏的意念顯露出來；你自己的心也要被刀刺透。」","notes":[],"end":35},{"n":36,"t":"又有女先知，名叫亞拿，是亞設支派法內力的女兒，年紀已經老邁，從作童女出嫁的時候，同丈夫住了七年就寡居了，","notes":[]},{"n":37,"t":"現在已經八十四歲，並不離開聖殿，禁食祈求，晝夜事奉神。","notes":["或譯：就寡居了八十四年"]},{"n":38,"t":"正當那時，她進前來稱謝神，將孩子的事對一切盼望耶路撒冷得救贖的人講說。","notes":[]},{"n":39,"t":"約瑟和馬利亞照主的律法辦完了一切的事，就回加利利，到自己的城拿撒勒去了。","notes":[],"heads":["回拿撒勒"]},{"n":40,"t":"孩子漸漸長大，強健起來，充滿智慧，又有神的恩在他身上。","notes":[]},{"n":41,"t":"每年到逾越節，他父母就上耶路撒冷去。","notes":[],"heads":["孩童耶穌在聖殿裏"]},{"n":42,"t":"當他十二歲的時候，他們按著節期的規矩上去。","notes":[]},{"n":43,"t":"守滿了節期，他們回去，孩童耶穌仍舊在耶路撒冷。他的父母並不知道，","notes":[]},{"n":44,"t":"以為他在同行的人中間，走了一天的路程，就在親族和熟識的人中找他，","notes":[]},{"n":45,"t":"既找不著，就回耶路撒冷去找他。","notes":[]},{"n":46,"t":"過了三天，就遇見他在殿裏，坐在教師中間，一面聽，一面問。","notes":[]},{"n":47,"t":"凡聽見他的，都希奇他的聰明和他的應對。","notes":[]},{"n":48,"t":"他父母看見就很希奇。他母親對他說：「我兒！為甚麼向我們這樣行呢？看哪，你父親和我傷心來找你！」","notes":[]},{"n":49,"t":"耶穌說：「為甚麼找我呢？豈不知我應當以我父的事為念嗎 ？」","notes":["或譯：豈不知我應當在我父的家裏嗎"]},{"n":50,"t":"他所說的這話，他們不明白。","notes":[]},{"n":51,"t":"他就同他們下去，回到拿撒勒，並且順從他們。他母親把這一切的事都存在心裏。","notes":[]},{"n":52,"t":"耶穌的智慧和身量，並神和人喜愛他的心，都一齊增長。","notes":["或譯：年紀"]}]},"3":{"heading":"施洗約翰傳道","verses":[{"n":1,"t":"凱撒提庇留在位第十五年，本丟‧彼拉多作猶太巡撫，希律作加利利分封的王，他兄弟腓力作以土利亞和特拉可尼地方分封的王，呂撒聶作亞比利尼分封的王，","notes":[]},{"n":2,"t":"亞那和該亞法作大祭司。那時，撒迦利亞的兒子約翰在曠野裏，神的話臨到他。","notes":[]},{"n":3,"t":"他就來到約旦河一帶地方，宣講悔改的洗禮，使罪得赦。","notes":[]},{"n":4,"t":"正如先知以賽亞書上所記的話，說：在曠野有人聲喊著說：預備主的道，修直他的路！","notes":[]},{"n":5,"t":"一切山窪都要填滿；大小山岡都要削平！彎彎曲曲的地方要改為正直；高高低低的道路要改為平坦！","notes":[]},{"n":6,"t":"凡有血氣的，都要見神的救恩！","notes":[]},{"n":7,"t":"約翰對那出來要受他洗的眾人說：「毒蛇的種類！誰指示你們逃避將來的忿怒呢？","notes":[]},{"n":8,"t":"你們要結出果子來，與悔改的心相稱。不要自己心裏說：『有亞伯拉罕為我們的祖宗。』我告訴你們，神能從這些石頭中，給亞伯拉罕興起子孫來。","notes":[]},{"n":9,"t":"現在斧子已經放在樹根上，凡不結好果子的樹就砍下來，丟在火裏。」","notes":[]},{"n":10,"t":"眾人問他說：「這樣，我們當做甚麼呢？」","notes":[]},{"n":11,"t":"約翰回答說：「有兩件衣裳的，就分給那沒有的；有食物的，也當這樣行。」","notes":[]},{"n":12,"t":"又有稅吏來要受洗，問他說：「夫子，我們當做甚麼呢？」","notes":[]},{"n":13,"t":"約翰說：「除了例定的數目，不要多取。」","notes":[]},{"n":14,"t":"又有兵丁問他說：「我們當做甚麼呢？」約翰說：「不要以強暴待人，也不要訛詐人，自己有錢糧就當知足。」","notes":[]},{"n":15,"t":"百姓指望基督來的時候，人都心裏猜疑，或者約翰是基督。","notes":[]},{"n":16,"t":"約翰說：「我是用水給你們施洗，但有一位能力比我更大的要來，我就是給他解鞋帶也不配。他要用聖靈與火給你們施洗。","notes":[]},{"n":17,"t":"他手裏拿著簸箕，要揚淨他的場，把麥子收在倉裏，把糠用不滅的火燒盡了。」","notes":[]},{"n":18,"t":"約翰又用許多別的話勸百姓，向他們傳福音。","notes":[]},{"n":19,"t":"只是分封的王希律，因他兄弟之妻希羅底的緣故，並因他所行的一切惡事，受了約翰的責備；","notes":[]},{"n":20,"t":"又另外添了一件，就是把約翰收在監裏。","notes":[]},{"n":21,"t":"眾百姓都受了洗，耶穌也受了洗。正禱告的時候，天就開了，","notes":[],"heads":["耶穌受洗"]},{"n":22,"t":"聖靈降臨在他身上，形狀彷彿鴿子；又有聲音從天上來，說：「你是我的愛子，我喜悅你。」","notes":[]},{"n":23,"t":"耶穌開頭傳道，年紀約有三十歲。依人看來，他是約瑟的兒子；約瑟是希里的兒子；","notes":[],"heads":["耶穌的家譜"]},{"n":24,"t":"希里是瑪塔的兒子；瑪塔是利未的兒子；利未是麥基的兒子；麥基是雅拿的兒子；雅拿是約瑟的兒子；","notes":[]},{"n":25,"t":"約瑟是瑪他提亞的兒子；瑪他提亞是亞摩斯的兒子；亞摩斯是拿鴻的兒子；拿鴻是以斯利的兒子；以斯利是拿該的兒子；","notes":[]},{"n":26,"t":"拿該是瑪押的兒子；瑪押是瑪他提亞的兒子；瑪他提亞是西美的兒子；西美是約瑟的兒子；約瑟是猶大的兒子；猶大是約亞拿的兒子；","notes":[]},{"n":27,"t":"約亞拿是利撒的兒子；利撒是所羅巴伯的兒子；所羅巴伯是撒拉鐵的兒子；撒拉鐵是尼利的兒子；尼利是麥基的兒子；","notes":[]},{"n":28,"t":"麥基是亞底的兒子；亞底是哥桑的兒子；哥桑是以摩當的兒子；以摩當是珥的兒子；珥是約細的兒子；","notes":[]},{"n":29,"t":"約細是以利以謝的兒子；以利以謝是約令的兒子；約令是瑪塔的兒子；瑪塔是利未的兒子；","notes":[]},{"n":30,"t":"利未是西緬的兒子；西緬是猶大的兒子；猶大是約瑟的兒子；約瑟是約南的兒子；約南是以利亞敬的兒子；","notes":[]},{"n":31,"t":"以利亞敬是米利亞的兒子；米利亞是買南的兒子；買南是瑪達他的兒子；瑪達他是拿單的兒子；拿單是大衛的兒子；","notes":[]},{"n":32,"t":"大衛是耶西的兒子；耶西是俄備得的兒子；俄備得是波阿斯的兒子；波阿斯是撒門的兒子；撒門是拿順的兒子；","notes":[]},{"n":33,"t":"拿順是亞米拿達的兒子；亞米拿達是亞蘭的兒子；亞蘭是希斯崙的兒子；希斯崙是法勒斯的兒子；法勒斯是猶大的兒子；","notes":[]},{"n":34,"t":"猶大是雅各的兒子；雅各是以撒的兒子；以撒是亞伯拉罕的兒子；亞伯拉罕是他拉的兒子；他拉是拿鶴的兒子；","notes":[]},{"n":35,"t":"拿鶴是西鹿的兒子；西鹿是拉吳的兒子；拉吳是法勒的兒子；法勒是希伯的兒子；希伯是沙拉的兒子；","notes":[]},{"n":36,"t":"沙拉是該南的兒子；該南是亞法撒的兒子；亞法撒是閃的兒子；閃是挪亞的兒子；挪亞是拉麥的兒子；","notes":[]},{"n":37,"t":"拉麥是瑪土撒拉的兒子；瑪土撒拉是以諾的兒子；以諾是雅列的兒子；雅列是瑪勒列的兒子；瑪勒列是該南的兒子；該南是以挪士的兒子；","notes":[]},{"n":38,"t":"以挪士是塞特的兒子；塞特是亞當的兒子；亞當是神的兒子。","notes":[]}]},"4":{"heading":"耶穌受試探","verses":[{"n":1,"t":"耶穌被聖靈充滿，從約旦河回來，聖靈將他引到曠野，","notes":[]},{"n":2,"t":"四十天受魔鬼的試探。那些日子沒有吃甚麼；日子滿了，他就餓了。","notes":[]},{"n":3,"t":"魔鬼對他說：「你若是神的兒子，可以吩咐這塊石頭變成食物。」","notes":[]},{"n":4,"t":"耶穌回答說：「經上記著說：『人活著不是單靠食物，乃是靠神口裏所出的一切話。』」","notes":[]},{"n":5,"t":"魔鬼又領他上了高山，霎時間把天下的萬國都指給他看，","notes":[]},{"n":6,"t":"對他說：「這一切權柄、榮華，我都要給你，因為這原是交付我的，我願意給誰就給誰。","notes":[]},{"n":7,"t":"你若在我面前下拜，這都要歸你。」","notes":[]},{"n":8,"t":"耶穌說：「經上記著說：當拜主－你的神，單要事奉他。」","notes":[]},{"n":9,"t":"魔鬼又領他到耶路撒冷去，叫他站在殿頂上，對他說：「你若是神的兒子，可以從這裏跳下去；","notes":["頂：原文是翅"]},{"n":10,"t":"因為經上記著說：主要為你吩咐他的使者保護你；","notes":[]},{"n":11,"t":"他們要用手托著你，免得你的腳碰在石頭上。」","notes":[]},{"n":12,"t":"耶穌對他說：「經上說：『不可試探主－你的神。』」","notes":[]},{"n":13,"t":"魔鬼用完了各樣的試探，就暫時離開耶穌。","notes":[]},{"n":14,"t":"耶穌滿有聖靈的能力，回到加利利；他的名聲就傳遍了四方。","notes":[],"heads":["開始在加利利傳道"]},{"n":15,"t":"他在各會堂裏教訓人，眾人都稱讚他。","notes":[]},{"n":16,"t":"耶穌來到拿撒勒，就是他長大的地方。在安息日，照他平常的規矩進了會堂，站起來要念聖經。","notes":[],"heads":["拿撒勒人厭棄耶穌"]},{"n":17,"t":"有人把先知以賽亞的書交給他，他就打開，找到一處寫著說：","notes":[]},{"n":18,"t":"主的靈在我身上，因為他用膏膏我，叫我傳福音給貧窮的人；差遣我報告：被擄的得釋放，瞎眼的得看見，叫那受壓制的得自由，","notes":[]},{"n":19,"t":"報告神悅納人的禧年。","notes":[]},{"n":20,"t":"於是把書捲起來，交還執事，就坐下。會堂裏的人都定睛看他。","notes":[]},{"n":21,"t":"耶穌對他們說：「今天這經應驗在你們耳中了。」","notes":[]},{"n":22,"t":"眾人都稱讚他，並希奇他口中所出的恩言；又說：「這不是約瑟的兒子嗎？」","notes":[]},{"n":23,"t":"耶穌對他們說：「你們必引這俗語向我說：『醫生，你醫治自己吧！我們聽見你在迦百農所行的事，也當行在你自己家鄉裏』」；","notes":[]},{"n":24,"t":"又說：「我實在告訴你們，沒有先知在自己家鄉被人悅納的。","notes":[]},{"n":25,"t":"我對你們說實話，當以利亞的時候，天閉塞了三年零六個月，遍地有大饑荒，那時，以色列中有許多寡婦，","notes":[]},{"n":26,"t":"以利亞並沒有奉差往她們一個人那裏去，只奉差往西頓的撒勒法一個寡婦那裏去。","notes":[]},{"n":27,"t":"先知以利沙的時候，以色列中有許多長大痲瘋的，但內中除了敘利亞國的乃縵，沒有一個得潔淨的。」","notes":[]},{"n":28,"t":"會堂裏的人聽見這話，都怒氣滿胸，","notes":[]},{"n":29,"t":"就起來攆他出城（他們的城造在山上）；他們帶他到山崖，要把他推下去。","notes":[]},{"n":30,"t":"他卻從他們中間直行，過去了。","notes":[]},{"n":31,"t":"耶穌下到迦百農，就是加利利的一座城，在安息日教訓眾人。","notes":[],"heads":["一個污鬼附身的人"]},{"n":32,"t":"他們很希奇他的教訓，因為他的話裏有權柄。","notes":[]},{"n":33,"t":"在會堂裏有一個人，被污鬼的精氣附著，大聲喊叫說：","notes":[]},{"n":34,"t":"「唉！拿撒勒的耶穌，我們與你有甚麼相干？你來滅我們嗎？我知道你是誰，乃是神的聖者。」","notes":[]},{"n":35,"t":"耶穌責備他說：「不要作聲，從這人身上出來吧！」鬼把那人摔倒在眾人中間，就出來了，卻也沒有害他。","notes":[]},{"n":36,"t":"眾人都驚訝，彼此對問說：「這是甚麼道理呢？因為他用權柄能力吩咐污鬼，污鬼就出來。」","notes":[]},{"n":37,"t":"於是耶穌的名聲傳遍了周圍地方。","notes":[]},{"n":38,"t":"耶穌出了會堂，進了西門的家。西門的岳母害熱病甚重，有人為她求耶穌。","notes":[],"heads":["治好許多病人"]},{"n":39,"t":"耶穌站在她旁邊，斥責那熱病，熱就退了。她立刻起來服事他們。","notes":[]},{"n":40,"t":"日落的時候，凡有病人的，不論害甚麼病，都帶到耶穌那裏。耶穌按手在他們各人身上，醫好他們。","notes":[]},{"n":41,"t":"又有鬼從好些人身上出來，喊著說：「你是神的兒子。」耶穌斥責他們，不許他們說話，因為他們知道他是基督。","notes":[]},{"n":42,"t":"天亮的時候，耶穌出來，走到曠野地方。眾人去找他，到了他那裏，要留住他，不要他離開他們。","notes":[],"heads":["在加利利各會堂傳道"]},{"n":43,"t":"但耶穌對他們說：「我也必須在別城傳神國的福音，因我奉差原是為此。」","notes":[]},{"n":44,"t":"於是耶穌在加利利的各會堂傳道。","notes":[]}]},"5":{"heading":"耶穌呼召頭幾個門徒","verses":[{"n":1,"t":"耶穌站在革尼撒勒湖邊，眾人擁擠他，要聽神的道。","notes":[]},{"n":2,"t":"他見有兩隻船灣在湖邊；打魚的人卻離開船洗網去了。","notes":[]},{"n":3,"t":"有一隻船是西門的，耶穌就上去，請他把船撐開，稍微離岸，就坐下，從船上教訓眾人。","notes":[]},{"n":4,"t":"講完了，對西門說：「把船開到水深之處，下網打魚。」","notes":[]},{"n":5,"t":"西門說：「夫子，我們整夜勞力，並沒有打著甚麼。但依從你的話，我就下網。」","notes":[]},{"n":6,"t":"他們下了網，就圈住許多魚，網險些裂開，","notes":[]},{"n":7,"t":"便招呼那隻船上的同伴來幫助。他們就來，把魚裝滿了兩隻船，甚至船要沉下去。","notes":[]},{"n":8,"t":"西門‧彼得看見，就俯伏在耶穌膝前，說：「主啊，離開我，我是個罪人！」","notes":[]},{"n":9,"t":"他和一切同在的人都驚訝這一網所打的魚。","notes":[]},{"n":10,"t":"他的夥伴西庇太的兒子雅各、約翰，也是這樣。耶穌對西門說：「不要怕！從今以後，你要得人了。」","notes":[]},{"n":11,"t":"他們把兩隻船攏了岸，就撇下所有的，跟從了耶穌。","notes":[]},{"n":12,"t":"有一回，耶穌在一個城裏，有人滿身長了大痲瘋，看見他，就俯伏在地，求他說：「主若肯，必能叫我潔淨了。」","notes":[],"heads":["潔淨長大痲瘋的人"]},{"n":13,"t":"耶穌伸手摸他，說：「我肯，你潔淨了吧！」大痲瘋立刻就離了他的身。","notes":[]},{"n":14,"t":"耶穌囑咐他：「你切不可告訴人，只要去把身體給祭司察看，又要為你得了潔淨，照摩西所吩咐的獻上禮物，對眾人作證據。」","notes":[]},{"n":15,"t":"但耶穌的名聲越發傳揚出去。有極多的人聚集來聽道，也指望醫治他們的病。","notes":[]},{"n":16,"t":"耶穌卻退到曠野去禱告。","notes":[]},{"n":17,"t":"有一天，耶穌教訓人，有法利賽人和教法師在旁邊坐著；他們是從加利利各鄉村和猶太並耶路撒冷來的。主的能力與耶穌同在，使他能醫治病人。","notes":[],"heads":["治好癱瘓病人"]},{"n":18,"t":"有人用褥子抬著一個癱子，要抬進去放在耶穌面前，","notes":[]},{"n":19,"t":"卻因人多，尋不出法子抬進去，就上了房頂，從瓦間把他連褥子縋到當中，正在耶穌面前。","notes":[]},{"n":20,"t":"耶穌見他們的信心，就對癱子說：「你的罪赦了。」","notes":[]},{"n":21,"t":"文士和法利賽人就議論說：「這說僭妄話的是誰？除了神以外，誰能赦罪呢？」","notes":[]},{"n":22,"t":"耶穌知道他們所議論的，就說：「你們心裏議論的是甚麼呢？","notes":[]},{"n":23,"t":"或說『你的罪赦了』，或說『你起來行走』，哪一樣容易呢？","notes":[]},{"n":24,"t":"但要叫你們知道，人子在地上有赦罪的權柄。」就對癱子說：「我吩咐你，起來，拿你的褥子回家去吧！」","notes":[]},{"n":25,"t":"那人當眾人面前立刻起來，拿著他所躺臥的褥子回家去，歸榮耀與神。","notes":[]},{"n":26,"t":"眾人都驚奇，也歸榮耀與神，並且滿心懼怕，說：「我們今日看見非常的事了。」","notes":[]},{"n":27,"t":"這事以後，耶穌出去，看見一個稅吏，名叫利未，坐在稅關上，就對他說：「你跟從我來。」","notes":[],"heads":["呼召利未"]},{"n":28,"t":"他就撇下所有的，起來，跟從了耶穌。","notes":[]},{"n":29,"t":"利未在自己家裏為耶穌大擺筵席，有許多稅吏和別人與他們一同坐席。","notes":[]},{"n":30,"t":"法利賽人和文士就向耶穌的門徒發怨言說：「你們為甚麼和稅吏並罪人一同吃喝呢？」","notes":[]},{"n":31,"t":"耶穌對他們說：「無病的人用不著醫生；有病的人才用得著。","notes":[]},{"n":32,"t":"我來本不是召義人悔改，乃是召罪人悔改。」","notes":[]},{"n":33,"t":"他們說：「約翰的門徒屢次禁食祈禱，法利賽人的門徒也是這樣；惟獨你的門徒又吃又喝。」","notes":[],"heads":["禁食的問題"]},{"n":34,"t":"耶穌對他們說：「新郎和陪伴之人同在的時候，豈能叫陪伴之人禁食呢？","notes":[]},{"n":35,"t":"但日子將到，新郎要離開他們，那日他們就要禁食了。」","notes":[]},{"n":36,"t":"耶穌又設一個比喻，對他們說：「沒有人把新衣服撕下一塊來補在舊衣服上；若是這樣，就把新的撕破了，並且所撕下來的那塊新的和舊的也不相稱。","notes":[]},{"n":37,"t":"也沒有人把新酒裝在舊皮袋裏；若是這樣，新酒必將皮袋裂開，酒便漏出來，皮袋也就壞了。","notes":[]},{"n":38,"t":"但新酒必須裝在新皮袋裏。","notes":[]},{"n":39,"t":"沒有人喝了陳酒又想喝新的；他總說陳的好。」","notes":[]}]},"6":{"heading":"安息日的問題","verses":[{"n":1,"t":"有一個安息日，耶穌從麥地經過。他的門徒掐了麥穗，用手搓著吃。","notes":[]},{"n":2,"t":"有幾個法利賽人說：「你們為甚麼做安息日不可做的事呢？」","notes":[]},{"n":3,"t":"耶穌對他們說：「經上記著大衛和跟從他的人飢餓之時所做的事，連這個你們也沒有念過嗎？","notes":[]},{"n":4,"t":"他怎麼進了神的殿，拿陳設餅吃，又給跟從的人吃？這餅除了祭司以外，別人都不可吃。」","notes":[]},{"n":5,"t":"又對他們說：「人子是安息日的主。」","notes":[]},{"n":6,"t":"又有一個安息日，耶穌進了會堂教訓人，在那裏有一個人右手枯乾了。","notes":[],"heads":["治好枯乾了一隻手的人"]},{"n":7,"t":"文士和法利賽人窺探耶穌，在安息日治病不治病，要得把柄去告他。","notes":[]},{"n":8,"t":"耶穌卻知道他們的意念，就對那枯乾一隻手的人說：「起來！站在當中。」那人就起來，站著。","notes":[]},{"n":9,"t":"耶穌對他們說：「我問你們，在安息日行善行惡，救命害命，哪樣是可以的呢？」","notes":[]},{"n":10,"t":"他就周圍看著他們眾人，對那人說：「伸出手來！」他把手一伸，手就復了原。","notes":[]},{"n":11,"t":"他們就滿心大怒，彼此商議怎樣處治耶穌。","notes":[]},{"n":12,"t":"那時，耶穌出去，上山禱告，整夜禱告神；","notes":[],"heads":["挑選十二門徒"]},{"n":13,"t":"到了天亮，叫他的門徒來，就從他們中間挑選十二個人，稱他們為使徒。","notes":[]},{"n":14,"t":"這十二個人有西門（耶穌又給他起名叫彼得），還有他兄弟安得烈，又有雅各和約翰，腓力和巴多羅買，","notes":[]},{"n":15,"t":"馬太和多馬，亞勒腓的兒子雅各和奮銳黨的西門，","notes":[]},{"n":16,"t":"雅各的兒子猶大，和賣主的加略人猶大。","notes":["或譯：兄弟"]},{"n":17,"t":"耶穌和他們下了山，站在一塊平地上；同站的有許多門徒，又有許多百姓，從猶太全地和耶路撒冷，並泰爾、西頓的海邊來，都要聽他講道，又指望醫治他們的病；","notes":[],"heads":["向群眾傳道"]},{"n":18,"t":"還有被污鬼纏磨的，也得了醫治。","notes":[]},{"n":19,"t":"眾人都想要摸他；因為有能力從他身上發出來，醫好了他們。","notes":[]},{"n":20,"t":"耶穌舉目看著門徒，說：你們貧窮的人有福了！因為神的國是你們的。","notes":[],"heads":["論福和禍"]},{"n":21,"t":"你們飢餓的人有福了！因為你們將要飽足。你們哀哭的人有福了！因為你們將要喜笑。","notes":[]},{"n":22,"t":"「人為人子恨惡你們，拒絕你們，辱罵你們，棄掉你們的名，以為是惡，你們就有福了！","notes":[]},{"n":23,"t":"當那日，你們要歡喜跳躍，因為你們在天上的賞賜是大的。他們的祖宗待先知也是這樣。","notes":[]},{"n":24,"t":"但你們富足的人有禍了！因為你們受過你們的安慰。","notes":[]},{"n":25,"t":"你們飽足的人有禍了！因為你們將要飢餓。你們喜笑的人有禍了！因為你們將要哀慟哭泣。","notes":[]},{"n":26,"t":"「人都說你們好的時候，你們就有禍了！因為他們的祖宗待假先知也是這樣。」","notes":[]},{"n":27,"t":"「只是我告訴你們這聽道的人，你們的仇敵，要愛他！恨你們的，要待他好！","notes":[],"heads":["論愛仇敵"]},{"n":28,"t":"咒詛你們的，要為他祝福！凌辱你們的，要為他禱告！","notes":[]},{"n":29,"t":"有人打你這邊的臉，連那邊的臉也由他打。有人奪你的外衣，連裏衣也由他拿去。","notes":[]},{"n":30,"t":"凡求你的，就給他。有人奪你的東西去，不用再要回來。","notes":[]},{"n":31,"t":"你們願意人怎樣待你們，你們也要怎樣待人。","notes":[]},{"n":32,"t":"你們若單愛那愛你們的人，有甚麼可酬謝的呢？就是罪人也愛那愛他們的人。","notes":[]},{"n":33,"t":"你們若善待那善待你們的人，有甚麼可酬謝的呢？就是罪人也是這樣行。","notes":[]},{"n":34,"t":"你們若借給人，指望從他收回，有甚麼可酬謝的呢？就是罪人也借給罪人，要如數收回。","notes":[]},{"n":35,"t":"你們倒要愛仇敵，也要善待他們，並要借給人不指望償還，你們的賞賜就必大了，你們也必作至高者的兒子，因為他恩待那忘恩的和作惡的。","notes":[]},{"n":36,"t":"你們要慈悲，像你們的父慈悲一樣。」","notes":[]},{"n":37,"t":"「你們不要論斷人，就不被論斷；你們不要定人的罪，就不被定罪；你們要饒恕人，就必蒙饒恕 ；","notes":["饒恕：原文是釋放"],"heads":["不要論斷人"]},{"n":38,"t":"你們要給人，就必有給你們的，並且用十足的升斗，連搖帶按，上尖下流地倒在你們懷裏；因為你們用甚麼量器量給人，也必用甚麼量器量給你們。」","notes":[]},{"n":39,"t":"耶穌又用比喻對他們說：「瞎子豈能領瞎子，兩個人不是都要掉在坑裏嗎？","notes":[]},{"n":40,"t":"學生不能高過先生；凡學成了的不過和先生一樣。","notes":[]},{"n":41,"t":"為甚麼看見你弟兄眼中有刺，卻不想自己眼中有樑木呢？","notes":[]},{"n":42,"t":"你不見自己眼中有樑木，怎能對你弟兄說：『容我去掉你眼中的刺』呢？你這假冒為善的人！先去掉自己眼中的樑木，然後才能看得清楚，去掉你弟兄眼中的刺。」","notes":[]},{"n":43,"t":"「因為，沒有好樹結壞果子，也沒有壞樹結好果子。","notes":[],"heads":["樹和果子"]},{"n":44,"t":"凡樹木看果子，就可以認出它來。人不是從荊棘上摘無花果，也不是從蒺藜裏摘葡萄。","notes":[]},{"n":45,"t":"善人從他心裏所存的善就發出善來；惡人從他心裏所存的惡就發出惡來；因為心裏所充滿的，口裏就說出來。」","notes":[]},{"n":46,"t":"「你們為甚麼稱呼我『主啊，主啊』卻不遵我的話行呢？","notes":[],"heads":["兩種蓋房子的人"]},{"n":47,"t":"凡到我這裏來，聽見我的話就去行的，我要告訴你們他像甚麼人：","notes":[]},{"n":48,"t":"他像一個人蓋房子，深深地挖地，把根基安在磐石上；到發大水的時候，水沖那房子，房子總不能搖動，因為根基立在磐石上 。","notes":["有古卷：因為蓋造得好"]},{"n":49,"t":"惟有聽見不去行的，就像一個人在土地上蓋房子，沒有根基；水一沖，隨即倒塌了，並且那房子壞的很大。」","notes":[]}]},"7":{"heading":"治好百夫長的僕人","verses":[{"n":1,"t":"耶穌對百姓講完了這一切的話，就進了迦百農。","notes":[]},{"n":2,"t":"有一個百夫長所寶貴的僕人害病，快要死了。","notes":[]},{"n":3,"t":"百夫長風聞耶穌的事，就託猶太人的幾個長老去求耶穌來救他的僕人。","notes":[]},{"n":4,"t":"他們到了耶穌那裏，就切切地求他說：「你給他行這事是他所配得的；","notes":[]},{"n":5,"t":"因為他愛我們的百姓，給我們建造會堂。」","notes":[]},{"n":6,"t":"耶穌就和他們同去。離那家不遠，百夫長託幾個朋友去見耶穌，對他說：「主啊！不要勞動；因你到我舍下，我不敢當。","notes":[]},{"n":7,"t":"我也自以為不配去見你，只要你說一句話，我的僕人就必好了。","notes":[]},{"n":8,"t":"因為我在人的權下，也有兵在我以下，對這個說：『去！』他就去；對那個說：『來！』他就來；對我的僕人說：『你做這事！』他就去做。」","notes":[]},{"n":9,"t":"耶穌聽見這話，就希奇他，轉身對跟隨的眾人說：「我告訴你們，這麼大的信心，就是在以色列中，我也沒有遇見過。」","notes":[]},{"n":10,"t":"那託來的人回到百夫長家裏，看見僕人已經好了。","notes":[]},{"n":11,"t":"過了不多時，耶穌往一座城去，這城名叫拿因，他的門徒和極多的人與他同行。","notes":["有古卷：次日"],"heads":["使拿因城寡婦之子復活"]},{"n":12,"t":"將近城門，有一個死人被抬出來。這人是他母親獨生的兒子；他母親又是寡婦。有城裏的許多人同著寡婦送殯。","notes":[]},{"n":13,"t":"主看見那寡婦，就憐憫她，對她說：「不要哭！」","notes":[]},{"n":14,"t":"於是進前按著槓，抬的人就站住了。耶穌說：「少年人，我吩咐你，起來！」","notes":[]},{"n":15,"t":"那死人就坐起，並且說話。耶穌便把他交給他母親。","notes":[]},{"n":16,"t":"眾人都驚奇，歸榮耀與神，說：「有大先知在我們中間興起來了！」又說：「神眷顧了他的百姓！」","notes":[]},{"n":17,"t":"他這事的風聲就傳遍了猶太和周圍地方。","notes":[]},{"n":18,"t":"約翰的門徒把這些事都告訴約翰。","notes":[],"heads":["施洗約翰的門徒來見耶穌"]},{"n":19,"t":"他便叫了兩個門徒來，打發他們到主那裏去，說：「那將要來的是你嗎？還是我們等候別人呢？」","notes":[]},{"n":20,"t":"那兩個人來到耶穌那裏，說：「施洗的約翰打發我們來問你：『那將要來的是你嗎？還是我們等候別人呢？』」","notes":[]},{"n":21,"t":"正當那時候，耶穌治好了許多有疾病的，受災患的，被惡鬼附著的，又開恩叫好些瞎子能看見。","notes":[]},{"n":22,"t":"耶穌回答說：「你們去，把所看見所聽見的事告訴約翰，就是瞎子看見，瘸子行走，長大痲瘋的潔淨，聾子聽見，死人復活，窮人有福音傳給他們。","notes":[]},{"n":23,"t":"凡不因我跌倒的，就有福了！」","notes":[]},{"n":24,"t":"約翰所差來的人既走了，耶穌就對眾人講論約翰說：「你們從前出去到曠野，是要看甚麼呢？要看風吹動的蘆葦嗎？","notes":[]},{"n":25,"t":"你們出去，到底是要看甚麼？要看穿細軟衣服的人嗎？那穿華麗衣服、宴樂度日的人是在王宮裏。","notes":[]},{"n":26,"t":"你們出去，究竟是要看甚麼？要看先知嗎？我告訴你們，是的，他比先知大多了。","notes":[]},{"n":27,"t":"經上記著說：『我要差遣我的使者在你前面預備道路』，所說的就是這個人。","notes":[]},{"n":28,"t":"我告訴你們，凡婦人所生的，沒有一個大過約翰的；然而神國裏最小的比他還大。」","notes":[]},{"n":29,"t":"眾百姓和稅吏既受過約翰的洗，聽見這話，就以神為義；","notes":[]},{"n":30,"t":"但法利賽人和律法師沒有受過約翰的洗，竟為自己廢棄了神的旨意。","notes":["29－30兩節或譯：眾百姓和稅吏聽見了約翰的話，就受了他的洗，便以神為義；但法利賽人和律法師不受約翰的洗，竟為自己廢棄了神的旨意。"]},{"n":31,"t":"主又說：「這樣，我可用甚麼比這世代的人呢？他們好像甚麼呢？","notes":[]},{"n":32,"t":"好像孩童坐在街市上，彼此呼叫說：我們向你們吹笛，你們不跳舞；我們向你們舉哀，你們不啼哭。","notes":[]},{"n":33,"t":"施洗的約翰來，不吃餅，不喝酒，你們說他是被鬼附著的。","notes":[]},{"n":34,"t":"人子來，也吃也喝，你們說他是貪食好酒的人，是稅吏和罪人的朋友。","notes":[]},{"n":35,"t":"但智慧之子都以智慧為是。」","notes":[]},{"n":36,"t":"有一個法利賽人請耶穌和他吃飯；耶穌就到法利賽人家裏去坐席。","notes":[],"heads":["有罪的女人得蒙赦免"]},{"n":37,"t":"那城裏有一個女人，是個罪人，知道耶穌在法利賽人家裏坐席，就拿著盛香膏的玉瓶，","notes":[]},{"n":38,"t":"站在耶穌背後，挨著他的腳哭，眼淚濕了耶穌的腳，就用自己的頭髮擦乾，又用嘴連連親他的腳，把香膏抹上。","notes":[]},{"n":39,"t":"請耶穌的法利賽人看見這事，心裏說：「這人若是先知，必知道摸他的是誰，是個怎樣的女人；乃是個罪人。」","notes":[]},{"n":40,"t":"耶穌對他說：「西門！我有句話要對你說。」西門說：「夫子，請說。」","notes":[]},{"n":41,"t":"耶穌說：「一個債主有兩個人欠他的債；一個欠五十兩銀子，一個欠五兩銀子；","notes":[]},{"n":42,"t":"因為他們無力償還，債主就開恩免了他們兩個人的債。這兩個人哪一個更愛他呢？」","notes":[]},{"n":43,"t":"西門回答說：「我想是那多得恩免的人。」耶穌說：「你斷的不錯。」","notes":[]},{"n":44,"t":"於是轉過來向著那女人，便對西門說：「你看見這女人嗎？我進了你的家，你沒有給我水洗腳；但這女人用眼淚濕了我的腳，用頭髮擦乾。","notes":[]},{"n":45,"t":"你沒有與我親嘴；但這女人從我進來的時候就不住地用嘴親我的腳。","notes":[]},{"n":46,"t":"你沒有用油抹我的頭；但這女人用香膏抹我的腳。","notes":[]},{"n":47,"t":"所以我告訴你，她許多的罪都赦免了，因為她的愛多；但那赦免少的，他的愛就少。」","notes":[]},{"n":48,"t":"於是對那女人說：「你的罪赦免了。」","notes":[]},{"n":49,"t":"同席的人心裏說：「這是甚麼人，竟赦免人的罪呢？」","notes":[]},{"n":50,"t":"耶穌對那女人說：「你的信救了你；平平安安回去吧！」","notes":[]}]},"8":{"heading":"跟從耶穌的婦女們","verses":[{"n":1,"t":"過了不多日，耶穌周遊各城各鄉傳道，宣講神國的福音。和他同去的有十二個門徒，","notes":[]},{"n":2,"t":"還有被惡鬼所附、被疾病所累、已經治好的幾個婦女，內中有稱為抹大拉的馬利亞（曾有七個鬼從她身上趕出來），","notes":[]},{"n":3,"t":"又有希律的家宰苦撒的妻子約亞拿，並蘇撒拿，和好些別的婦女，都是用自己的財物供給耶穌和門徒。","notes":[]},{"n":4,"t":"當許多人聚集、又有人從各城裏出來見耶穌的時候，耶穌就用比喻說：","notes":[],"heads":["撒種的比喻"]},{"n":5,"t":"「有一個撒種的出去撒種。撒的時候，有落在路旁的，被人踐踏，天上的飛鳥又來吃盡了。","notes":[]},{"n":6,"t":"有落在磐石上的，一出來就枯乾了，因為得不著滋潤。","notes":[]},{"n":7,"t":"有落在荊棘裏的，荊棘一同生長，把它擠住了。","notes":[]},{"n":8,"t":"又有落在好土裏的，生長起來，結實百倍。」耶穌說了這些話，就大聲說：「有耳可聽的，就應當聽！」","notes":[]},{"n":9,"t":"門徒問耶穌說：「這比喻是甚麼意思呢？」","notes":[],"heads":["用比喻的目的"]},{"n":10,"t":"他說：「神國的奧祕只叫你們知道；至於別人，就用比喻，叫他們看也看不見，聽也聽不明。」","notes":[]},{"n":11,"t":"「這比喻乃是這樣：種子就是神的道。","notes":[],"heads":["解明撒種的比喻"]},{"n":12,"t":"那些在路旁的，就是人聽了道，隨後魔鬼來，從他們心裏把道奪去，恐怕他們信了得救。","notes":[]},{"n":13,"t":"那些在磐石上的，就是人聽道，歡喜領受，但心中沒有根，不過暫時相信，及至遇見試煉就退後了。","notes":[]},{"n":14,"t":"那落在荊棘裏的，就是人聽了道，走開以後，被今生的思慮、錢財、宴樂擠住了，便結不出成熟的子粒來。","notes":[]},{"n":15,"t":"那落在好土裏的，就是人聽了道，持守在誠實善良的心裏，並且忍耐著結實。」","notes":[]},{"n":16,"t":"「沒有人點燈用器皿蓋上，或放在床底下，乃是放在燈臺上，叫進來的人看見亮光。","notes":[],"heads":["器皿下的燈"]},{"n":17,"t":"因為掩藏的事沒有不顯出來的；隱瞞的事沒有不露出來被人知道的。","notes":[]},{"n":18,"t":"所以，你們應當小心怎樣聽；因為凡有的，還要加給他；凡沒有的，連他自以為有的，也要奪去。」","notes":[]},{"n":19,"t":"耶穌的母親和他弟兄來了，因為人多，不得到他跟前。","notes":[],"heads":["耶穌的母親和兄弟們"]},{"n":20,"t":"有人告訴他說：「你母親和你弟兄站在外邊，要見你。」","notes":[]},{"n":21,"t":"耶穌回答說：「聽了神之道而遵行的人就是我的母親，我的弟兄了。」","notes":[]},{"n":22,"t":"有一天，耶穌和門徒上了船，對門徒說：「我們可以渡到湖那邊去。」他們就開了船。","notes":[],"heads":["平靜風浪"]},{"n":23,"t":"正行的時候，耶穌睡著了。湖上忽然起了暴風，船將滿了水，甚是危險。","notes":[]},{"n":24,"t":"門徒來叫醒了他，說：「夫子！夫子！我們喪命啦！」耶穌醒了，斥責那狂風大浪；風浪就止住，平靜了。","notes":[]},{"n":25,"t":"耶穌對他們說：「你們的信心在哪裏呢？」他們又懼怕又希奇，彼此說：「這到底是誰？他吩咐風和水，連風和水也聽從他了。」","notes":[]},{"n":26,"t":"他們到了格拉森人的地方，就是加利利的對面。","notes":["有古卷：加大拉"],"heads":["治好格拉森被鬼附的人"]},{"n":27,"t":"耶穌上了岸，就有城裏一個被鬼附著的人迎面而來。這個人許久不穿衣服，不住房子，只住在墳塋裏。","notes":[]},{"n":28,"t":"他見了耶穌，就俯伏在他面前，大聲喊叫，說：「至高神的兒子耶穌，我與你有甚麼相干？求你不要叫我受苦！」","notes":[]},{"n":29,"t":"是因耶穌曾吩咐污鬼從那人身上出來。原來這鬼屢次抓住他；他常被人看守，又被鐵鍊和腳鐐捆鎖，他竟把鎖鍊掙斷，被鬼趕到曠野去。","notes":[]},{"n":30,"t":"耶穌問他說：「你名叫甚麼？」他說：「我名叫『群』」；這是因為附著他的鬼多。","notes":[]},{"n":31,"t":"鬼就央求耶穌，不要吩咐他們到無底坑裏去。","notes":[]},{"n":32,"t":"那裏有一大群豬在山上吃食。鬼央求耶穌，准他們進入豬裏去。耶穌准了他們，","notes":[]},{"n":33,"t":"鬼就從那人出來，進入豬裏去。於是那群豬闖下山崖，投在湖裏淹死了。","notes":[]},{"n":34,"t":"放豬的看見這事就逃跑了，去告訴城裏和鄉下的人。","notes":[]},{"n":35,"t":"眾人出來要看是甚麼事；到了耶穌那裏，看見鬼所離開的那人，坐在耶穌腳前，穿著衣服，心裏明白過來，他們就害怕。","notes":[]},{"n":36,"t":"看見這事的便將被鬼附著的人怎麼得救告訴他們。","notes":[]},{"n":37,"t":"格拉森四圍的人，因為害怕得很，都求耶穌離開他們；耶穌就上船回去了。","notes":[]},{"n":38,"t":"鬼所離開的那人懇求和耶穌同在；耶穌卻打發他回去，說：","notes":[]},{"n":39,"t":"「你回家去，傳說神為你做了何等大的事。」他就去，滿城裏傳揚耶穌為他做了何等大的事。","notes":[]},{"n":40,"t":"耶穌回來的時候，眾人迎接他，因為他們都等候他。","notes":[],"heads":["睚魯的女兒和血漏的女人"]},{"n":41,"t":"有一個管會堂的，名叫睚魯，來俯伏在耶穌腳前，求耶穌到他家裏去；","notes":[]},{"n":42,"t":"因他有一個獨生女兒，約有十二歲，快要死了。耶穌去的時候，眾人擁擠他。","notes":[]},{"n":43,"t":"有一個女人，患了十二年的血漏，在醫生手裏花盡了她一切養生的，並沒有一人能醫好她。","notes":[]},{"n":44,"t":"她來到耶穌背後，摸他的衣裳繸子，血漏立刻就止住了。","notes":[]},{"n":45,"t":"耶穌說：「摸我的是誰？」眾人都不承認。彼得和同行的人都說：「夫子，眾人擁擁擠擠緊靠著你。 」","notes":["有古卷加：你還問摸我的是誰嗎？"]},{"n":46,"t":"耶穌說：「總有人摸我，因我覺得有能力從我身上出去。」","notes":[]},{"n":47,"t":"那女人知道不能隱藏，就戰戰兢兢地來俯伏在耶穌腳前，把摸他的緣故和怎樣立刻得好了，當著眾人都說出來。","notes":[]},{"n":48,"t":"耶穌對她說：「女兒，你的信救了你；平平安安地去吧！」","notes":[]},{"n":49,"t":"還說話的時候，有人從管會堂的家裏來，說：「你的女兒死了，不要勞動夫子。」","notes":[]},{"n":50,"t":"耶穌聽見就對他說：「不要怕，只要信！你的女兒就必得救。」","notes":[]},{"n":51,"t":"耶穌到了他的家，除了彼得、約翰、雅各，和女兒的父母，不許別人同他進去。","notes":[]},{"n":52,"t":"眾人都為這女兒哀哭捶胸。耶穌說：「不要哭！她不是死了，是睡著了。」","notes":[]},{"n":53,"t":"他們曉得女兒已經死了，就嗤笑耶穌。","notes":[]},{"n":54,"t":"耶穌拉著她的手，呼叫說：「女兒，起來吧！」","notes":[]},{"n":55,"t":"她的靈魂便回來，她就立刻起來了。耶穌吩咐給她東西吃。","notes":[]},{"n":56,"t":"她的父母驚奇得很；耶穌囑咐他們，不要把所做的事告訴人。","notes":[]}]},"9":{"heading":"耶穌差遣十二個門徒","verses":[{"n":1,"t":"耶穌叫齊了十二個門徒，給他們能力、權柄，制伏一切的鬼，醫治各樣的病，","notes":[]},{"n":2,"t":"又差遣他們去宣傳神國的道，醫治病人，","notes":[]},{"n":3,"t":"對他們說：「行路的時候，不要帶柺杖和口袋，不要帶食物和銀子，也不要帶兩件褂子。","notes":[]},{"n":4,"t":"無論進哪一家，就住在那裏，也從那裏起行。","notes":[]},{"n":5,"t":"凡不接待你們的，你們離開那城的時候，要把腳上的塵土跺下去，見證他們的不是。」","notes":[]},{"n":6,"t":"門徒就出去，走遍各鄉宣傳福音，到處治病。","notes":[]},{"n":7,"t":"分封的王希律聽見耶穌所做的一切事，就游移不定；因為有人說：「是約翰從死裏復活」；","notes":[],"heads":["希律的困惑"]},{"n":8,"t":"又有人說：「是以利亞顯現」；還有人說：「是古時的一個先知又活了。」","notes":[]},{"n":9,"t":"希律說：「約翰我已經斬了，這卻是甚麼人？我竟聽見他這樣的事呢？」就想要見他。","notes":[]},{"n":10,"t":"使徒回來，將所做的事告訴耶穌，耶穌就帶他們暗暗地離開那裏，往一座城去；那城名叫伯賽大。","notes":[],"heads":["耶穌給五千人吃飽"]},{"n":11,"t":"但眾人知道了，就跟著他去；耶穌便接待他們，對他們講論神國的道，醫治那些需醫的人。","notes":[]},{"n":12,"t":"日頭快要平西，十二個門徒來對他說：「請叫眾人散開，他們好往四面鄉村裏去借宿找吃的，因為我們這裏是野地。」","notes":[]},{"n":13,"t":"耶穌說：「你們給他們吃吧！」門徒說：「我們不過有五個餅，兩條魚，若不去為這許多人買食物就不夠。」","notes":[]},{"n":14,"t":"那時，人數約有五千。耶穌對門徒說：「叫他們一排一排地坐下，每排大約五十個人。」","notes":[]},{"n":15,"t":"門徒就如此行，叫眾人都坐下。","notes":[]},{"n":16,"t":"耶穌拿著這五個餅，兩條魚，望著天祝福，擘開，遞給門徒，擺在眾人面前。","notes":[]},{"n":17,"t":"他們就吃，並且都吃飽了；把剩下的零碎收拾起來，裝滿了十二籃子。","notes":[]},{"n":18,"t":"耶穌自己禱告的時候，門徒也同他在那裏。耶穌問他們說：「眾人說我是誰？」","notes":[],"heads":["彼得認耶穌為基督"]},{"n":19,"t":"他們說：「有人說是施洗的約翰；有人說是以利亞；還有人說是古時的一個先知又活了。」","notes":[]},{"n":20,"t":"耶穌說：「你們說我是誰？」彼得回答說：「是神所立的基督。」","notes":[]},{"n":21,"t":"耶穌切切地囑咐他們，不可將這事告訴人，","notes":[],"heads":["耶穌預言受難和復活"]},{"n":22,"t":"又說：「人子必須受許多的苦，被長老、祭司長，和文士棄絕，並且被殺，第三日復活。」","notes":[]},{"n":23,"t":"耶穌又對眾人說：「若有人要跟從我，就當捨己，天天背起他的十字架來跟從我。","notes":[]},{"n":24,"t":"因為，凡要救自己生命的，必喪掉生命；凡為我喪掉生命的，必救了生命。","notes":["生命：或譯靈魂；下同"]},{"n":25,"t":"人若賺得全世界，卻喪了自己，賠上自己，有甚麼益處呢？","notes":[]},{"n":26,"t":"凡把我和我的道當作可恥的，人子在自己的榮耀裏，並天父與聖天使的榮耀裏降臨的時候，也要把那人當作可恥的。","notes":[]},{"n":27,"t":"我實在告訴你們，站在這裏的，有人在沒嘗死味以前，必看見神的國。」","notes":[]},{"n":28,"t":"說了這話以後約有八天，耶穌帶著彼得、約翰、雅各上山去禱告。","notes":[],"heads":["耶穌改變形像"]},{"n":29,"t":"正禱告的時候，他的面貌就改變了，衣服潔白放光。","notes":[]},{"n":30,"t":"忽然有摩西、以利亞兩個人同耶穌說話；","notes":[]},{"n":31,"t":"他們在榮光裏顯現，談論耶穌去世的事，就是他在耶路撒冷將要成的事。","notes":[]},{"n":32,"t":"彼得和他的同伴都打盹，既清醒了，就看見耶穌的榮光，並同他站著的那兩個人。","notes":[]},{"n":33,"t":"二人正要和耶穌分離的時候，彼得對耶穌說：「夫子，我們在這裏真好！可以搭三座棚，一座為你，一座為摩西，一座為以利亞。」他卻不知道所說的是甚麼。","notes":[]},{"n":34,"t":"說這話的時候，有一朵雲彩來遮蓋他們；他們進入雲彩裏就懼怕。","notes":[]},{"n":35,"t":"有聲音從雲彩裏出來，說：「這是我的兒子，我所揀選的，你們要聽他。」","notes":["有古卷：這是我的愛子"]},{"n":36,"t":"聲音住了，只見耶穌一人在那裏。當那些日子，門徒不提所看見的事，一樣也不告訴人。","notes":[]},{"n":37,"t":"第二天，他們下了山，就有許多人迎見耶穌。","notes":[],"heads":["治好被污鬼附身的孩子"]},{"n":38,"t":"其中有一人喊叫說：「夫子！求你看顧我的兒子，因為他是我的獨生子。","notes":[]},{"n":39,"t":"他被鬼抓住就忽然喊叫；鬼又叫他抽瘋，口中流沫，並且重重地傷害他，難以離開他。","notes":[]},{"n":40,"t":"我求過你的門徒，把鬼趕出去，他們卻是不能。」","notes":[]},{"n":41,"t":"耶穌說：「噯！這又不信又悖謬的世代啊，我在你們這裏，忍耐你們要到幾時呢？將你的兒子帶到這裏來吧！」","notes":[]},{"n":42,"t":"正來的時候，鬼把他摔倒，叫他重重地抽瘋。耶穌就斥責那污鬼，把孩子治好了，交給他父親。","notes":[]},{"n":43,"t":"眾人都詫異神的大能 。耶穌所做的一切事，眾人正希奇的時候，耶穌對門徒說：","notes":["大能：或譯威榮"]},{"n":44,"t":"「你們要把這些話存在耳中，因為人子將要被交在人手裏。」","notes":[]},{"n":45,"t":"他們不明白這話，意思乃是隱藏的，叫他們不能明白，他們也不敢問這話的意思。","notes":[]},{"n":46,"t":"門徒中間起了議論，誰將為大。","notes":[],"heads":["誰最偉大"]},{"n":47,"t":"耶穌看出他們心中的議論，就領一個小孩子來，叫他站在自己旁邊，","notes":[]},{"n":48,"t":"對他們說：「凡為我名接待這小孩子的，就是接待我；凡接待我的，就是接待那差我來的。你們中間最小的，他便為大。」","notes":[]},{"n":49,"t":"約翰說：「夫子，我們看見一個人奉你的名趕鬼，我們就禁止他，因為他不與我們一同跟從你。」","notes":[],"heads":["不敵擋你們就是幫助你們"]},{"n":50,"t":"耶穌說：「不要禁止他；因為不敵擋你們的，就是幫助你們的。」","notes":[]},{"n":51,"t":"耶穌被接上升的日子將到，他就定意向耶路撒冷去，","notes":[],"heads":["不接待主的村莊"]},{"n":52,"t":"便打發使者在他前頭走。他們到了撒馬利亞的一個村莊，要為他預備。","notes":[]},{"n":53,"t":"那裏的人不接待他，因他面向耶路撒冷去。","notes":[]},{"n":54,"t":"他的門徒雅各、約翰看見了，就說：「主啊，你要我們吩咐火從天上降下來燒滅他們，像以利亞所做的嗎？」","notes":["有古卷沒有像以利亞所做的這幾個字"]},{"n":55,"t":"耶穌轉身責備兩個門徒，說：「你們的心如何，你們並不知道。","notes":[]},{"n":56,"t":"人子來不是要滅人的性命，是要救人的性命。」說著就往別的村莊去了。","notes":["性 命：或譯靈魂；下同","有古卷只有五十五節首句，五十六節末句"]},{"n":57,"t":"他們走路的時候，有一人對耶穌說：「你無論往哪裏去，我要跟從你。」","notes":[],"heads":["要跟從耶穌的人"]},{"n":58,"t":"耶穌說：「狐狸有洞，天空的飛鳥有窩，只是人子沒有枕頭的地方。」","notes":[]},{"n":59,"t":"又對一個人說：「跟從我來！」那人說：「主，容我先回去埋葬我的父親。」","notes":[]},{"n":60,"t":"耶穌說：「任憑死人埋葬他們的死人，你只管去傳揚神國的道。」","notes":[]},{"n":61,"t":"又有一人說：「主，我要跟從你，但容我先去辭別我家裏的人。」","notes":[]},{"n":62,"t":"耶穌說：「手扶著犂向後看的，不配進神的國。」","notes":[]}]},"10":{"heading":"主差遣七十人","verses":[{"n":1,"t":"這事以後，主又設立七十個人，差遣他們兩個兩個地在他前面，往自己所要到的各城各地方去，","notes":[]},{"n":2,"t":"就對他們說：「要收的莊稼多，做工的人少。所以，你們當求莊稼的主打發工人出去收他的莊稼。","notes":[]},{"n":3,"t":"你們去吧！我差你們出去，如同羊羔進入狼群。","notes":[]},{"n":4,"t":"不要帶錢囊，不要帶口袋，不要帶鞋；在路上也不要問人的安。","notes":[]},{"n":5,"t":"無論進哪一家，先要說：『願這一家平安。』","notes":[]},{"n":6,"t":"那裏若有當得平安的人，你們所求的平安就必臨到那家；不然，就歸與你們了。","notes":["當得平安的人：原文是平安之子"]},{"n":7,"t":"你們要住在那家，吃喝他們所供給的，因為工人得工價是應當的；不要從這家搬到那家。","notes":[]},{"n":8,"t":"無論進哪一城，人若接待你們，給你們擺上甚麼，你們就吃甚麼。","notes":[]},{"n":9,"t":"要醫治那城裏的病人，對他們說：『神的國臨近你們了。』","notes":[]},{"n":10,"t":"無論進哪一城，人若不接待你們，你們就到街上去，","notes":[]},{"n":11,"t":"說：『就是你們城裏的塵土黏在我們的腳上，我們也當著你們擦去。雖然如此，你們該知道神的國臨近了。』","notes":[]},{"n":12,"t":"我告訴你們，當審判的日子，所多瑪所受的，比那城還容易受呢！」","notes":[]},{"n":13,"t":"「哥拉汛哪，你有禍了！伯賽大啊，你有禍了！因為在你們中間所行的異能若行在泰爾、西頓，他們早已披麻蒙灰，坐在地上悔改了。","notes":[],"heads":["不悔改的城有禍了"]},{"n":14,"t":"當審判的日子，泰爾、西頓所受的，比你們還容易受呢！","notes":[]},{"n":15,"t":"迦百農啊，你已經升到天上，將來必推下陰間。」","notes":["或譯：你將要升到天上嗎"]},{"n":16,"t":"又對門徒說：「聽從你們的就是聽從我；棄絕你們的就是棄絕我；棄絕我的就是棄絕那差我來的。」","notes":[]},{"n":17,"t":"那七十個人歡歡喜喜地回來，說：「主啊！因你的名，就是鬼也服了我們。」","notes":[],"heads":["七十個人回來"]},{"n":18,"t":"耶穌對他們說：「我曾看見撒但從天上墜落，像閃電一樣。","notes":[]},{"n":19,"t":"我已經給你們權柄可以踐踏蛇和蠍子，又勝過仇敵一切的能力，斷沒有甚麼能害你們。","notes":[]},{"n":20,"t":"然而，不要因鬼服了你們就歡喜，要因你們的名記錄在天上歡喜。」","notes":[]},{"n":21,"t":"正當那時，耶穌被聖靈感動就歡樂，說：「父啊，天地的主，我感謝你！因為你將這些事向聰明通達人就藏起來，向嬰孩就顯出來。父啊！是的，因為你的美意本是如此。","notes":[],"heads":["耶穌的歡樂"]},{"n":22,"t":"一切所有的都是我父交付我的；除了父，沒有人知道子是誰；除了子和子所願意指示的，沒有人知道父是誰。」","notes":[]},{"n":23,"t":"耶穌轉身暗暗地對門徒說：「看見你們所看見的，那眼睛就有福了。","notes":[]},{"n":24,"t":"我告訴你們，從前有許多先知和君王要看你們所看的，卻沒有看見，要聽你們所聽的，卻沒有聽見。」","notes":[]},{"n":25,"t":"有一個律法師起來試探耶穌，說：「夫子！我該做甚麼才可以承受永生？」","notes":[],"heads":["好撒馬利亞人"]},{"n":26,"t":"耶穌對他說：「律法上寫的是甚麼？你念的是怎樣呢？」","notes":[]},{"n":27,"t":"他回答說：「你要盡心、盡性、盡力、盡意愛主－你的神；又要愛鄰舍如同自己。」","notes":[]},{"n":28,"t":"耶穌說：「你回答的是；你這樣行，就必得永生。」","notes":[]},{"n":29,"t":"那人要顯明自己有理，就對耶穌說：「誰是我的鄰舍呢？」","notes":[]},{"n":30,"t":"耶穌回答說：「有一個人從耶路撒冷下耶利哥去，落在強盜手中。他們剝去他的衣裳，把他打個半死，就丟下他走了。","notes":[]},{"n":31,"t":"偶然有一個祭司從這條路下來，看見他就從那邊過去了。","notes":[]},{"n":32,"t":"又有一個利未人來到這地方，看見他，也照樣從那邊過去了。","notes":[]},{"n":33,"t":"惟有一個撒馬利亞人行路來到那裏，看見他就動了慈心，","notes":[]},{"n":34,"t":"上前用油和酒倒在他的傷處，包裹好了，扶他騎上自己的牲口，帶到店裏去照應他。","notes":[]},{"n":35,"t":"第二天拿出二錢銀子來，交給店主，說：『你且照應他；此外所費用的，我回來必還你。』","notes":[]},{"n":36,"t":"你想，這三個人哪一個是落在強盜手中的鄰舍呢？」","notes":[]},{"n":37,"t":"他說：「是憐憫他的。」耶穌說：「你去照樣行吧。」","notes":[]},{"n":38,"t":"他們走路的時候，耶穌進了一個村莊。有一個女人，名叫馬大，接他到自己家裏。","notes":[],"heads":["耶穌探望馬大和馬利亞"]},{"n":39,"t":"她有一個妹子，名叫馬利亞，在耶穌腳前坐著聽他的道。","notes":[]},{"n":40,"t":"馬大伺候的事多，心裏忙亂，就進前來，說：「主啊，我的妹子留下我一個人伺候，你不在意嗎？請吩咐她來幫助我。」","notes":[]},{"n":41,"t":"耶穌回答說：「馬大！馬大！你為許多的事思慮煩擾，","notes":[]},{"n":42,"t":"但是不可少的只有一件；馬利亞已經選擇那上好的福分，是不能奪去的。」","notes":[]}]},"11":{"heading":"禱告的教訓","verses":[{"n":1,"t":"耶穌在一個地方禱告；禱告完了，有個門徒對他說：「求主教導我們禱告，像約翰教導他的門徒。」","notes":[]},{"n":2,"t":"耶穌說：「你們禱告的時候，要說：我們在天上的父：願人都尊你的名為聖。願你的國降臨；願你的旨意行在地上，如同行在天上。","notes":["有古卷：父啊","有古卷沒有願你的旨意…"]},{"n":3,"t":"我們日用的飲食，天天賜給我們。","notes":[]},{"n":4,"t":"赦免我們的罪，因為我們也赦免凡虧欠我們的人。不叫我們遇見試探；救我們脫離凶惡。」","notes":["有古卷沒有末句"]},{"n":5,"t":"耶穌又說：「你們中間誰有一個朋友半夜到他那裏去，說：『朋友！請借給我三個餅；","notes":[]},{"n":6,"t":"因為我有一個朋友行路，來到我這裏，我沒有甚麼給他擺上。』","notes":[]},{"n":7,"t":"那人在裏面回答說：『不要攪擾我，門已經關閉，孩子們也同我在床上了，我不能起來給你。』","notes":[]},{"n":8,"t":"我告訴你們，雖不因他是朋友起來給他，但因他情詞迫切地直求，就必起來照他所需用的給他。","notes":[]},{"n":9,"t":"我又告訴你們，你們祈求，就給你們；尋找，就尋見；叩門，就給你們開門。","notes":[]},{"n":10,"t":"因為，凡祈求的，就得著；尋找的，就尋見；叩門的，就給他開門。","notes":[]},{"n":11,"t":"你們中間作父親的，誰有兒子求餅，反給他石頭呢？求魚，反拿蛇當魚給他呢？","notes":[]},{"n":12,"t":"求雞蛋，反給他蠍子呢？","notes":[]},{"n":13,"t":"你們雖然不好，尚且知道拿好東西給兒女；何況天父，豈不更將聖靈給求他的人嗎？」","notes":[]},{"n":14,"t":"耶穌趕出一個叫人啞巴的鬼；鬼出去了，啞巴就說出話來；眾人都希奇。","notes":[],"heads":["耶穌和別西卜"]},{"n":15,"t":"內中卻有人說：「他是靠著鬼王別西卜趕鬼。」","notes":[]},{"n":16,"t":"又有人試探耶穌，向他求從天上來的神蹟。","notes":[]},{"n":17,"t":"他曉得他們的意念，便對他們說：「凡一國自相紛爭，就成為荒場；凡一家自相紛爭，就必敗落。","notes":[]},{"n":18,"t":"若撒但自相紛爭，他的國怎能站得住呢？因為你們說我是靠著別西卜趕鬼。","notes":[]},{"n":19,"t":"我若靠著別西卜趕鬼，你們的子弟趕鬼又靠著誰呢？這樣，他們就要斷定你們的是非。","notes":[]},{"n":20,"t":"我若靠著神的能力趕鬼，這就是神的國臨到你們了。","notes":[]},{"n":21,"t":"壯士披掛整齊，看守自己的住宅，他所有的都平安無事；","notes":[]},{"n":22,"t":"但有一個比他更壯的來，勝過他，就奪去他所倚靠的盔甲兵器，又分了他的贓。","notes":[]},{"n":23,"t":"不與我相合的，就是敵我的；不同我收聚的，就是分散的。」","notes":[]},{"n":24,"t":"「污鬼離了人身，就在無水之地過來過去，尋求安歇之處；既尋不著，便說：『我要回到我所出來的屋裏去。』","notes":[],"heads":["污鬼回來"]},{"n":25,"t":"到了，就看見裏面打掃乾淨，修飾好了，","notes":[]},{"n":26,"t":"便去另帶了七個比自己更惡的鬼來，都進去住在那裏。那人末後的景況比先前更不好了。」","notes":[]},{"n":27,"t":"耶穌正說這話的時候，眾人中間有一個女人大聲說：「懷你胎的和乳養你的有福了！」","notes":[],"heads":["真正的福"]},{"n":28,"t":"耶穌說：「是，卻還不如聽神之道而遵守的人有福。」","notes":[]},{"n":29,"t":"當眾人聚集的時候，耶穌開講說：「這世代是一個邪惡的世代。他們求看神蹟，除了約拿的神蹟以外，再沒有神蹟給他們看。","notes":[],"heads":["求神蹟的受責備"]},{"n":30,"t":"約拿怎樣為尼尼微人成了神蹟，人子也要照樣為這世代的人成了神蹟。","notes":[]},{"n":31,"t":"當審判的時候，南方的女王要起來定這世代的罪；因為她從地極而來，要聽所羅門的智慧話。看哪，在這裏有一人比所羅門更大。","notes":[]},{"n":32,"t":"當審判的時候，尼尼微人要起來定這世代的罪，因為尼尼微人聽了約拿所傳的就悔改了。看哪，在這裏有一人比約拿更大。」","notes":[]},{"n":33,"t":"「沒有人點燈放在地窨子裏，或是斗底下，總是放在燈臺上，使進來的人得見亮光。","notes":[],"heads":["論心裏的光"]},{"n":34,"t":"你眼睛就是身上的燈。你的眼睛若瞭亮，全身就光明；眼睛若昏花，全身就黑暗。","notes":[]},{"n":35,"t":"所以，你要省察，恐怕你裏頭的光或者黑暗了。","notes":[]},{"n":36,"t":"若是你全身光明，毫無黑暗，就必全然光明，如同燈的明光照亮你。」","notes":[]},{"n":37,"t":"說話的時候，有一個法利賽人請耶穌同他吃飯，耶穌就進去坐席。","notes":[],"heads":["譴責法利賽人和文士"]},{"n":38,"t":"這法利賽人看見耶穌飯前不洗手便詫異。","notes":[]},{"n":39,"t":"主對他說：「如今你們法利賽人洗淨杯盤的外面，你們裏面卻滿了勒索和邪惡。","notes":[]},{"n":40,"t":"無知的人哪，造外面的，不也造裏面嗎？","notes":[]},{"n":41,"t":"只要把裏面的施捨給人，凡物於你們就都潔淨了。","notes":[]},{"n":42,"t":"「你們法利賽人有禍了！因為你們將薄荷、芸香並各樣菜蔬獻上十分之一，那公義和愛神的事反倒不行了。這原是你們當行的；那也是不可不行的。","notes":[]},{"n":43,"t":"你們法利賽人有禍了！因為你們喜愛會堂裏的首位，又喜愛人在街市上問你們的安。","notes":[]},{"n":44,"t":"你們有禍了！因為你們如同不顯露的墳墓，走在上面的人並不知道。」","notes":[]},{"n":45,"t":"律法師中有一個回答耶穌說：「夫子！你這樣說也把我們糟蹋了。」","notes":[]},{"n":46,"t":"耶穌說：「你們律法師也有禍了！因為你們把難擔的擔子放在人身上，自己一個指頭卻不肯動。","notes":[]},{"n":47,"t":"你們有禍了！因為你們修造先知的墳墓，那先知正是你們的祖宗所殺的。","notes":[]},{"n":48,"t":"可見你們祖宗所做的事，你們又證明又喜歡；因為他們殺了先知，你們修造先知的墳墓。","notes":[]},{"n":49,"t":"所以神用智慧曾說：『我要差遣先知和使徒到他們那裏去，有的他們要殺害，有的他們要逼迫』，","notes":["用智慧：或譯的智者"]},{"n":50,"t":"使創世以來所流眾先知血的罪都要問在這世代的人身上，","notes":[]},{"n":51,"t":"就是從亞伯的血起，直到被殺在壇和殿中間撒迦利亞的血為止。我實在告訴你們，這都要問在這世代的人身上。","notes":[]},{"n":52,"t":"你們律法師有禍了！因為你們把知識的鑰匙奪了去，自己不進去，正要進去的人你們也阻擋他們。」","notes":[]},{"n":53,"t":"耶穌從那裏出來，文士和法利賽人就極力地催逼他，引動他多說話，","notes":[]},{"n":54,"t":"私下窺聽，要拿他的話柄。","notes":[]}]},"12":{"heading":"防備假冒為善","verses":[{"n":1,"t":"這時，有幾萬人聚集，甚至彼此踐踏。耶穌開講，先對門徒說：「你們要防備法利賽人的酵，就是假冒為善。","notes":[]},{"n":2,"t":"掩蓋的事沒有不露出來的；隱藏的事沒有不被人知道的。","notes":[]},{"n":3,"t":"因此，你們在暗中所說的，將要在明處被人聽見；在內室附耳所說的，將要在房上被人宣揚。」","notes":[]},{"n":4,"t":"「我的朋友，我對你們說，那殺身體以後不能再做甚麼的，不要怕他們。","notes":[],"heads":["該怕的是誰"]},{"n":5,"t":"我要指示你們當怕的是誰：當怕那殺了以後又有權柄丟在地獄裏的。我實在告訴你們，正要怕他。","notes":[]},{"n":6,"t":"五個麻雀不是賣二分銀子嗎？但在神面前，一個也不忘記；","notes":[]},{"n":7,"t":"就是你們的頭髮，也都被數過了。不要懼怕，你們比許多麻雀還貴重！」","notes":[]},{"n":8,"t":"「我又告訴你們，凡在人面前認我的，人子在神的使者面前也必認他；","notes":[],"heads":["在人的面前承認基督"]},{"n":9,"t":"在人面前不認我的，人子在神的使者面前也必不認他。","notes":[]},{"n":10,"t":"凡說話干犯人子的，還可得赦免；惟獨褻瀆聖靈的，總不得赦免。","notes":[]},{"n":11,"t":"人帶你們到會堂，並官府和有權柄的人面前，不要思慮怎麼分訴，說甚麼話；","notes":[]},{"n":12,"t":"因為正在那時候，聖靈要指教你們當說的話。」","notes":[]},{"n":13,"t":"眾人中有一個人對耶穌說：「夫子！請你吩咐我的兄長和我分開家業。」","notes":[],"heads":["無知財主的比喻"]},{"n":14,"t":"耶穌說：「你這個人！誰立我作你們斷事的官，給你們分家業呢？」","notes":[]},{"n":15,"t":"於是對眾人說：「你們要謹慎自守，免去一切的貪心，因為人的生命不在乎家道豐富。」","notes":[]},{"n":16,"t":"就用比喻對他們說：「有一個財主田產豐盛；","notes":[]},{"n":17,"t":"自己心裏思想說：『我的出產沒有地方收藏，怎麼辦呢？』","notes":[]},{"n":18,"t":"又說：『我要這麼辦：要把我的倉房拆了，另蓋更大的，在那裏好收藏我一切的糧食和財物，","notes":[]},{"n":19,"t":"然後要對我的靈魂說：靈魂哪，你有許多財物積存，可作多年的費用，只管安安逸逸地吃喝快樂吧！』","notes":[]},{"n":20,"t":"神卻對他說：『無知的人哪，今夜必要你的靈魂；你所預備的要歸誰呢？』","notes":[]},{"n":21,"t":"凡為自己積財，在神面前卻不富足的，也是這樣。」","notes":[]},{"n":22,"t":"耶穌又對門徒說：「所以我告訴你們，不要為生命憂慮吃甚麼，為身體憂慮穿甚麼；","notes":[],"heads":["不要憂慮"]},{"n":23,"t":"因為生命勝於飲食，身體勝於衣裳。","notes":[]},{"n":24,"t":"你想烏鴉，也不種也不收，又沒有倉又沒有庫，神尚且養活牠。你們比飛鳥是何等地貴重呢！","notes":[]},{"n":25,"t":"你們哪一個能用思慮使壽數多加一刻呢？","notes":["或譯：使身量多加一肘呢"]},{"n":26,"t":"這最小的事，你們尚且不能做，為甚麼還憂慮其餘的事呢？","notes":[]},{"n":27,"t":"你想百合花怎麼長起來；它也不勞苦，也不紡線。然而我告訴你們，就是所羅門極榮華的時候，他所穿戴的，還不如這花一朵呢！","notes":[]},{"n":28,"t":"你們這小信的人哪，野地裏的草今天還在，明天就丟在爐裏，神還給它這樣的妝飾，何況你們呢！","notes":[]},{"n":29,"t":"你們不要求吃甚麼，喝甚麼，也不要掛心；","notes":[]},{"n":30,"t":"這都是外邦人所求的。你們必須用這些東西，你們的父是知道的。","notes":[]},{"n":31,"t":"你們只要求他的國，這些東西就必加給你們了。","notes":[]},{"n":32,"t":"你們這小群，不要懼怕，因為你們的父樂意把國賜給你們。","notes":[]},{"n":33,"t":"你們要變賣所有的賙濟人，為自己預備永不壞的錢囊，用不盡的財寶在天上，就是賊不能近、蟲不能蛀的地方。","notes":[]},{"n":34,"t":"因為，你們的財寶在哪裏，你們的心也在那裏。」","notes":[]},{"n":35,"t":"「你們腰裏要束上帶，燈也要點著，","notes":[],"heads":["警醒的僕人"]},{"n":36,"t":"自己好像僕人等候主人從婚姻的筵席上回來。他來到，叩門，就立刻給他開門。","notes":[]},{"n":37,"t":"主人來了，看見僕人警醒，那僕人就有福了。我實在告訴你們，主人必叫他們坐席，自己束上帶，進前伺候他們。","notes":[]},{"n":38,"t":"或是二更天來，或是三更天來，看見僕人這樣，那僕人就有福了。","notes":[]},{"n":39,"t":"家主若知道賊甚麼時候來，就必警醒，不容賊挖透房屋，這是你們所知道的。","notes":[]},{"n":40,"t":"你們也要預備；因為你們想不到的時候，人子就來了。」","notes":[]},{"n":41,"t":"彼得說：「主啊，這比喻是為我們說的呢？還是為眾人呢？」","notes":[]},{"n":42,"t":"主說：「誰是那忠心有見識的管家，主人派他管理家裏的人，按時分糧給他們呢？","notes":[]},{"n":43,"t":"主人來到，看見僕人這樣行，那僕人就有福了。","notes":[]},{"n":44,"t":"我實在告訴你們，主人要派他管理一切所有的。","notes":[]},{"n":45,"t":"那僕人若心裏說：『我的主人必來得遲』，就動手打僕人和使女，並且吃喝醉酒；","notes":[]},{"n":46,"t":"在他想不到的日子，不知道的時辰，那僕人的主人要來，重重地處治他，定他和不忠心的人同罪。","notes":["或譯：把他腰斬了"]},{"n":47,"t":"僕人知道主人的意思，卻不預備，又不順他的意思行，那僕人必多受責打；","notes":[]},{"n":48,"t":"惟有那不知道的，做了當受責打的事，必少受責打；因為多給誰，就向誰多取；多託誰，就向誰多要。」","notes":[]},{"n":49,"t":"「我來要把火丟在地上，倘若已經著起來，不也是我所願意的嗎？","notes":[],"heads":["分裂的原因"]},{"n":50,"t":"我有當受的洗還沒有成就，我是何等地迫切呢？","notes":[]},{"n":51,"t":"你們以為我來，是叫地上太平嗎？我告訴你們，不是，乃是叫人紛爭。","notes":[]},{"n":52,"t":"從今以後，一家五個人將要紛爭：三個人和兩個人相爭，兩個人和三個人相爭；","notes":[]},{"n":53,"t":"父親和兒子相爭，兒子和父親相爭；母親和女兒相爭，女兒和母親相爭；婆婆和媳婦相爭，媳婦和婆婆相爭。」","notes":[]},{"n":54,"t":"耶穌又對眾人說：「你們看見西邊起了雲彩，就說：『要下一陣雨』；果然就有。","notes":[],"heads":["分辨 時候"]},{"n":55,"t":"起了南風，就說：『將要燥熱』；也就有了。","notes":[]},{"n":56,"t":"假冒為善的人哪，你們知道分辨天地的氣色，怎麼不知道分辨這時候呢？」","notes":[]},{"n":57,"t":"「你們又為何不自己審量甚麼是合理的呢？","notes":[],"heads":["同對頭和解"]},{"n":58,"t":"你同告你的對頭去見官，還在路上，務要盡力地和他了結；恐怕他拉你到官面前，官交付差役，差役把你下在監裏。","notes":[]},{"n":59,"t":"我告訴你，若有半文錢沒有還清，你斷不能從那裏出來。」","notes":[]}]},"13":{"heading":"悔改或滅亡","verses":[{"n":1,"t":"正當那時，有人將彼拉多使加利利人的血攙雜在他們祭物中的事告訴耶穌。","notes":[]},{"n":2,"t":"耶穌說：「你們以為這些加利利人比眾加利利人更有罪，所以受這害嗎？","notes":[]},{"n":3,"t":"我告訴你們，不是的！你們若不悔改，都要如此滅亡！","notes":[]},{"n":4,"t":"從前西羅亞樓倒塌了，壓死十八個人；你們以為那些人比一切住在耶路撒冷的人更有罪嗎？","notes":[]},{"n":5,"t":"我告訴你們，不是的！你們若不悔改，都要如此滅亡！」","notes":[]},{"n":6,"t":"於是用比喻說：「一個人有一棵無花果樹栽在葡萄園裏。他來到樹前找果子，卻找不著。","notes":[],"heads":["不結實的無花果樹"]},{"n":7,"t":"就對管園的說：『看哪，我這三年來到這無花果樹前找果子，竟找不著。把它砍了吧，何必白佔地土呢！』","notes":[]},{"n":8,"t":"管園的說：『 主啊，今年且留著，等我周圍掘開土，加上糞；","notes":[]},{"n":9,"t":"以後若結果子便罷，不然再把它砍了。』」","notes":[]},{"n":10,"t":"安息日，耶穌在會堂裏教訓人。","notes":[],"heads":["安息日治好駝背的女人"]},{"n":11,"t":"有一個女人被鬼附著，病了十八年，腰彎得一點直不起來。","notes":[]},{"n":12,"t":"耶穌看見，便叫過她來，對她說：「女人，你脫離這病了！」","notes":[]},{"n":13,"t":"於是用兩隻手按著她；她立刻直起腰來，就歸榮耀與神。","notes":[]},{"n":14,"t":"管會堂的因為耶穌在安息日治病，就氣忿忿地對眾人說：「有六日應當做工；那六日之內可以來求醫，在安息日卻不可。」","notes":[]},{"n":15,"t":"主說：「假冒為善的人哪，難道你們各人在安息日不解開槽上的牛、驢，牽去飲嗎？","notes":[]},{"n":16,"t":"況且這女人本是亞伯拉罕的後裔，被撒但捆綁了這十八年，不當在安息日解開她的綁嗎？」","notes":[]},{"n":17,"t":"耶穌說這話，他的敵人都慚愧了；眾人因他所行一切榮耀的事，就都歡喜了。","notes":[]},{"n":18,"t":"耶穌說：「神的國好像甚麼？我拿甚麼來比較呢？","notes":[],"heads":["芥菜種和麵酵的比喻"]},{"n":19,"t":"好像一粒芥菜種，有人拿去種在園子裏，長大成樹，天上的飛鳥宿在它的枝上。」","notes":[]},{"n":20,"t":"又說：「我拿甚麼來比神的國呢？","notes":[]},{"n":21,"t":"好比麵酵，有婦人拿來藏在三斗麵裏，直等全團都發起來。」","notes":[]},{"n":22,"t":"耶穌往耶路撒冷去，在所經過的各城各鄉教訓人。","notes":[],"heads":["當進窄門"]},{"n":23,"t":"有一個人問他說：「主啊，得救的人少嗎？」","notes":[]},{"n":24,"t":"耶穌對眾人說：「你們要努力進窄門。我告訴你們，將來有許多人想要進去，卻是不能。","notes":[]},{"n":25,"t":"及至家主起來關了門，你們站在外面叩門，說：『主啊，給我們開門！』他就回答說：『我不認識你們，不曉得你們是哪裏來的！』","notes":[]},{"n":26,"t":"那時，你們要說：『我們在你面前吃過喝過，你也在我們的街上教訓過人。』","notes":[]},{"n":27,"t":"他要說：『我告訴你們，我不曉得你們是哪裏來的。你們這一切作惡的人，離開我去吧！』","notes":[]},{"n":28,"t":"你們要看見亞伯拉罕、以撒、雅各，和眾先知都在神的國裏，你們卻被趕到外面，在那裏必要哀哭切齒了。","notes":[]},{"n":29,"t":"從東、從西、從南、從北將有人來，在神的國裏坐席。","notes":[]},{"n":30,"t":"只是有在後的，將要在前；有在前的，將要在後。」","notes":[]},{"n":31,"t":"正當那時，有幾個法利賽人來對耶穌說：「離開這裏去吧，因為希律想要殺你。」","notes":[],"heads":["為耶路撒冷哀哭"]},{"n":32,"t":"耶穌說：「你們去告訴那個狐狸說：『今天、明天我趕鬼治病，第三天我的事就成全了。』","notes":[]},{"n":33,"t":"雖然這樣，今天、明天、後天，我必須前行，因為先知在耶路撒冷之外喪命是不能的。","notes":[]},{"n":34,"t":"耶路撒冷啊！耶路撒冷啊！你常殺害先知，又用石頭打死那奉差遣到你這裏來的人。我多次願意聚集你的兒女，好像母雞把小雞聚集在翅膀底下；只是你們不願意。","notes":[]},{"n":35,"t":"看哪，你們的家成為荒場留給你們。我告訴你們，從今以後你們不得再見我，直等到你們說：『奉主名來的是應當稱頌的。』」","notes":[]}]},"14":{"heading":"在安息日治好臌脹的人","verses":[{"n":1,"t":"安息日，耶穌到一個法利賽人的首領家裏去吃飯，他們就窺探他。","notes":[]},{"n":2,"t":"在他面前有一個患水臌的人。","notes":[]},{"n":3,"t":"耶穌對律法師和法利賽人說：「安息日治病可以不可以？」","notes":[]},{"n":4,"t":"他們卻不言語。耶穌就治好那人，叫他走了；","notes":[]},{"n":5,"t":"便對他們說：「你們中間誰有驢或有牛，在安息日掉在井裏，不立時拉牠上來呢？」","notes":[]},{"n":6,"t":"他們不能對答這話。","notes":[]},{"n":7,"t":"耶穌見所請的客揀擇首位，就用比喻對他們說：","notes":[],"heads":["給客人和主人的教訓"]},{"n":8,"t":"「你被人請去赴婚姻的筵席，不要坐在首位上，恐怕有比你尊貴的客被他請來；","notes":[]},{"n":9,"t":"那請你們的人前來對你說：『讓座給這一位吧！』你就羞羞慚慚地退到末位上去了。","notes":[]},{"n":10,"t":"你被請的時候，就去坐在末位上，好叫那請你的人來對你說：『朋友，請上座。』那時，你在同席的人面前就有光彩了。","notes":[]},{"n":11,"t":"因為，凡自高的，必降為卑；自卑的，必升為高。」","notes":[]},{"n":12,"t":"耶穌又對請他的人說：「你擺設午飯或晚飯，不要請你的朋友、弟兄、親屬，和富足的鄰舍，恐怕他們也請你，你就得了報答。","notes":[]},{"n":13,"t":"你擺設筵席，倒要請那貧窮的、殘廢的、瘸腿的、瞎眼的，你就有福了！","notes":[]},{"n":14,"t":"因為他們沒有甚麼可報答你。到義人復活的時候，你要得著報答。」","notes":[]},{"n":15,"t":"同席的有一人聽見這話，就對耶穌說：「在神國裏吃飯的有福了！」","notes":[],"heads":["大筵席的比喻"]},{"n":16,"t":"耶穌對他說：「有一人擺設大筵席，請了許多客。","notes":[]},{"n":17,"t":"到了坐席的時候，打發僕人去對所請的人說：『請來吧！樣樣都齊備了。』","notes":[]},{"n":18,"t":"眾人一口同音地推辭。頭一個說：『我買了一塊地，必須去看看。請你准我辭了。』","notes":[]},{"n":19,"t":"又有一個說：『我買了五對牛，要去試一試。請你准我辭了。』","notes":[]},{"n":20,"t":"又有一個說：『我才娶了妻，所以不能去。』","notes":[]},{"n":21,"t":"那僕人回來，把這事都告訴了主人。家主就動怒，對僕人說：『快出去，到城裏大街小巷，領那貧窮的、殘廢的、瞎眼的、瘸腿的來。』","notes":[]},{"n":22,"t":"僕人說：『主啊，你所吩咐的已經辦了，還有空座。』","notes":[]},{"n":23,"t":"主人對僕人說：『你出去到路上和籬笆那裏，勉強人進來，坐滿我的屋子。","notes":[]},{"n":24,"t":"我告訴你們，先前所請的人沒有一個得嘗我的筵席。』」","notes":[]},{"n":25,"t":"有極多的人和耶穌同行。他轉過來對他們說：","notes":[],"heads":["作門徒的代價"]},{"n":26,"t":"「人到我這裏來，若不愛我勝過愛自己的父母、妻子、兒女、弟兄、姊妹，和自己的性命，就不能作我的門徒。","notes":["愛我勝過愛：原文是恨"]},{"n":27,"t":"凡不背著自己十字架跟從我的，也不能作我的門徒。","notes":[]},{"n":28,"t":"你們哪一個要蓋一座樓，不先坐下算計花費，能蓋成不能呢？","notes":[]},{"n":29,"t":"恐怕安了地基，不能成功，看見的人都笑話他，說：","notes":[]},{"n":30,"t":"『這個人開了工，卻不能完工。』","notes":[]},{"n":31,"t":"或是一個王出去和別的王打仗，豈不先坐下酌量，能用一萬兵去敵那領二萬兵來攻打他的嗎？","notes":[]},{"n":32,"t":"若是不能，就趁敵人還遠的時候，派使者去求和息的條款。","notes":[]},{"n":33,"t":"這樣，你們無論甚麼人，若不撇下一切所有的，就不能作我的門徒。」","notes":[]},{"n":34,"t":"「鹽本是好的；鹽若失了味，可用甚麼叫它再鹹呢？","notes":[],"heads":["失味的鹽"]},{"n":35,"t":"或用在田裏，或堆在糞裏，都不合式，只好丟在外面。有耳可聽的，就應當聽！」","notes":[]}]},"15":{"heading":"迷羊的比喻","verses":[{"n":1,"t":"眾稅吏和罪人都挨近耶穌，要聽他講道。","notes":[]},{"n":2,"t":"法利賽人和文士私下議論說：「這個人接待罪人，又同他們吃飯。」","notes":[]},{"n":3,"t":"耶穌就用比喻說：","notes":[]},{"n":4,"t":"「你們中間誰有一百隻羊失去一隻，不把這九十九隻撇在曠野、去找那失去的羊，直到找著呢？","notes":[]},{"n":5,"t":"找著了，就歡歡喜喜地扛在肩上，回到家裏，","notes":[]},{"n":6,"t":"就請朋友鄰舍來，對他們說：『我失去的羊已經找著了，你們和我一同歡喜吧！』","notes":[]},{"n":7,"t":"我告訴你們，一個罪人悔改，在天上也要這樣為他歡喜，較比為九十九個不用悔改的義人歡喜更大。」","notes":[]},{"n":8,"t":"「或是一個婦人有十塊錢，若失落一塊，豈不點上燈，打掃屋子，細細地找，直到找著嗎？","notes":[],"heads":["失錢的比喻"]},{"n":9,"t":"找著了，就請朋友鄰舍來，對他們說：『我失落的那塊錢已經找著了，你們和我一同歡喜吧！』","notes":[]},{"n":10,"t":"我告訴你們，一個罪人悔改，在神的使者面前也是這樣為他歡喜。」","notes":[]},{"n":11,"t":"耶穌又說：「一個人有兩個兒子。","notes":[],"heads":["浪子的比喻"]},{"n":12,"t":"小兒子對父親說：『父親，請你把我應得的家業分給我。』他父親就把產業分給他們。","notes":[]},{"n":13,"t":"過了不多幾日，小兒子就把他一切所有的都收拾起來，往遠方去了。在那裏任意放蕩，浪費資財。","notes":[]},{"n":14,"t":"既耗盡了一切所有的，又遇著那地方大遭饑荒，就窮苦起來。","notes":[]},{"n":15,"t":"於是去投靠那地方的一個人；那人打發他到田裏去放豬。","notes":[]},{"n":16,"t":"他恨不得拿豬所吃的豆莢充飢，也沒有人給他。","notes":[]},{"n":17,"t":"他醒悟過來，就說：『我父親有多少的雇工，口糧有餘，我倒在這裏餓死嗎？","notes":[]},{"n":18,"t":"我要起來，到我父親那裏去，向他說：父親！我得罪了天，又得罪了你；","notes":[]},{"n":19,"t":"從今以後，我不配稱為你的兒子，把我當作一個雇工吧！』","notes":[]},{"n":20,"t":"於是起來，往他父親那裏去。相離還遠，他父親看見，就動了慈心，跑去抱著他的頸項，連連與他親嘴。","notes":[]},{"n":21,"t":"兒子說：『父親！我得罪了天，又得罪了你；從今以後，我不配稱為你的兒子。』","notes":[]},{"n":22,"t":"父親卻吩咐僕人說：『把那上好的袍子快拿出來給他穿；把戒指戴在他指頭上；把鞋穿在他腳上；","notes":[]},{"n":23,"t":"把那肥牛犢牽來宰了，我們可以吃喝快樂；","notes":[]},{"n":24,"t":"因為我這個兒子是死而復活，失而又得的。』他們就快樂起來。","notes":[]},{"n":25,"t":"那時，大兒子正在田裏。他回來，離家不遠，聽見作樂跳舞的聲音，","notes":[]},{"n":26,"t":"便叫過一個僕人來，問是甚麼事。","notes":[]},{"n":27,"t":"僕人說：『你兄弟來了；你父親因為得他無災無病地回來，把肥牛犢宰了。』","notes":[]},{"n":28,"t":"大兒子卻生氣，不肯進去；他父親就出來勸他。","notes":[]},{"n":29,"t":"他對父親說：『我服事你這多年，從來沒有違背過你的命，你並沒有給我一隻山羊羔，叫我和朋友一同快樂。","notes":[]},{"n":30,"t":"但你這個兒子和娼妓吞盡了你的產業，他一來了，你倒為他宰了肥牛犢。』","notes":[]},{"n":31,"t":"父親對他說：『兒啊！你常和我同在，我一切所有的都是你的；","notes":[]},{"n":32,"t":"只是你這個兄弟是死而復活、失而又得的，所以我們理當歡喜快樂。』」","notes":[]}]},"16":{"heading":"不義的管家","verses":[{"n":1,"t":"耶穌又對門徒說：「有一個財主的管家，別人向他主人告他浪費主人的財物。","notes":[]},{"n":2,"t":"主人叫他來，對他說：『我聽見你這事怎麼樣呢？把你所經管的交代明白，因你不能再作我的管家。』","notes":[]},{"n":3,"t":"那管家心裏說：『主人辭我，不用我再作管家，我將來做甚麼？鋤地呢？無力；討飯呢？怕羞。","notes":[]},{"n":4,"t":"我知道怎麼行，好叫人在我不作管家之後，接我到他們家裏去。』","notes":[]},{"n":5,"t":"於是把欠他主人債的，一個一個地叫了來，問頭一個說：『你欠我主人多少？』","notes":[]},{"n":6,"t":"他說：『一百簍油。』管家說：『拿你的帳，快坐下，寫五十。』","notes":["每簍約五十斤"]},{"n":7,"t":"又問一個說：『你欠多少？』他說：『一百石麥子。』管家說：『拿你的帳，寫八十。』","notes":[]},{"n":8,"t":"主人就誇獎這不義的管家做事聰明；因為今世之子，在世事之上，較比光明之子更加聰明。","notes":[]},{"n":9,"t":"我又告訴你們，要藉著那不義的錢財結交朋友，到了錢財無用的時候，他們可以接你們到永存的帳幕裏去。","notes":[]},{"n":10,"t":"人在最小的事上忠心，在大事上也忠心；在最小的事上不義，在大事上也不義。","notes":[]},{"n":11,"t":"倘若你們在不義的錢財上不忠心，誰還把那真實的錢財託付你們呢？","notes":[]},{"n":12,"t":"倘若你們在別人的東西上不忠心，誰還把你們自己的東西給你們呢？","notes":[]},{"n":13,"t":"一個僕人不能事奉兩個主；不是惡這個愛那個，就是重這個輕那個。你們不能又事奉神，又事奉瑪門。」","notes":[]},{"n":14,"t":"法利賽人是貪愛錢財的；他們聽見這一切話，就嗤笑耶穌。","notes":[],"heads":["律法和神的國"]},{"n":15,"t":"耶穌對他們說：「你們是在人面前自稱為義的，你們的心，神卻知道；因為人所尊貴的，是神看為可憎惡的。","notes":[]},{"n":16,"t":"律法和先知到約翰為止，從此神國的福音傳開了，人人努力要進去。","notes":[]},{"n":17,"t":"天地廢去較比律法的一點一畫落空還容易。","notes":[]},{"n":18,"t":"凡休妻另娶的就是犯姦淫；娶被休之妻的也是犯姦淫。」","notes":[]},{"n":19,"t":"「有一個財主穿著紫色袍和細麻布衣服，天天奢華宴樂。","notes":[],"heads":["財主和拉撒路"]},{"n":20,"t":"又有一個討飯的，名叫拉撒路，渾身生瘡，被人放在財主門口，","notes":[]},{"n":21,"t":"要得財主桌子上掉下來的零碎充飢，並且狗來舔他的瘡。","notes":[]},{"n":22,"t":"後來那討飯的死了，被天使帶去放在亞伯拉罕的懷裏。財主也死了，並且埋葬了。","notes":[]},{"n":23,"t":"他在陰間受痛苦，舉目遠遠地望見亞伯拉罕，又望見拉撒路在他懷裏，","notes":[]},{"n":24,"t":"就喊著說：『我祖亞伯拉罕哪，可憐我吧！打發拉撒路來，用指頭尖蘸點水，涼涼我的舌頭；因為我在這火焰裏，極其痛苦。』","notes":[]},{"n":25,"t":"亞伯拉罕說：『兒啊，你該回想你生前享過福，拉撒路也受過苦；如今他在這裏得安慰，你倒受痛苦。","notes":[]},{"n":26,"t":"不但這樣，並且在你我之間，有深淵限定，以致人要從這邊過到你們那邊是不能的；要從那邊過到我們這邊也是不能的。』","notes":[]},{"n":27,"t":"財主說：『我祖啊！既是這樣，求你打發拉撒路到我父家去；","notes":[]},{"n":28,"t":"因為我還有五個弟兄，他可以對他們作見證，免得他們也來到這痛苦的地方。』","notes":[]},{"n":29,"t":"亞伯拉罕說：『他們有摩西和先知的話可以聽從。』","notes":[]},{"n":30,"t":"他說：『我祖亞伯拉罕哪，不是的，若有一個從死裏復活的，到他們那裏去的，他們必要悔改。』","notes":[]},{"n":31,"t":"亞伯拉罕說：『若不聽從摩西和先知的話，就是有一個從死裏復活的，他們也是不聽勸。』」","notes":[]}]},"17":{"heading":"罪，信心，僕人的本分","verses":[{"n":1,"t":"耶穌又對門徒說：「絆倒人的事是免不了的；但那絆倒人的有禍了。","notes":[]},{"n":2,"t":"就是把磨石拴在這人的頸項上，丟在海裏，還強如他把這小子裏的一個絆倒了。","notes":[]},{"n":3,"t":"你們要謹慎！若是你的弟兄得罪你，就勸戒他；他若懊悔，就饒恕他。","notes":[]},{"n":4,"t":"倘若他一天七次得罪你，又七次回轉，說：『我懊悔了』，你總要饒恕他。」","notes":[]},{"n":5,"t":"使徒對主說：「求主加增我們的信心。」","notes":[]},{"n":6,"t":"主說：「你們若有信心像一粒芥菜種，就是對這棵桑樹說：『你要拔起根來，栽在海裏』，它也必聽從你們。","notes":[]},{"n":7,"t":"你們誰有僕人耕地或是放羊，從田裏回來，就對他說：『你快來坐下吃飯』呢？","notes":[]},{"n":8,"t":"豈不對他說：『你給我預備晚飯，束上帶子伺候我，等我吃喝完了，你才可以吃喝』嗎？","notes":[]},{"n":9,"t":"僕人照所吩咐的去做，主人還謝謝他嗎？","notes":[]},{"n":10,"t":"這樣，你們做完了一切所吩咐的，只當說：『我們是無用的僕人，所做的本是我們應分做的。』」","notes":[]},{"n":11,"t":"耶穌往耶路撒冷去，經過撒馬利亞和加利利。","notes":[],"heads":["治好十個長大痲瘋的"]},{"n":12,"t":"進入一個村子，有十個長大痲瘋的，迎面而來，遠遠地站著，","notes":[]},{"n":13,"t":"高聲說：「耶穌，夫子，可憐我們吧！」","notes":[]},{"n":14,"t":"耶穌看見，就對他們說：「你們去把身體給祭司察看。」他們去的時候就潔淨了。","notes":[]},{"n":15,"t":"內中有一個見自己已經好了，就回來大聲歸榮耀與神，","notes":[]},{"n":16,"t":"又俯伏在耶穌腳前感謝他；這人是撒馬利亞人。","notes":[]},{"n":17,"t":"耶穌說：「潔淨了的不是十個人嗎？那九個在哪裏呢？","notes":[]},{"n":18,"t":"除了這外族人，再沒有別人回來歸榮耀與神嗎？」","notes":[]},{"n":19,"t":"就對那人說：「起來，走吧！你的信救了你了。 」","notes":[]},{"n":20,"t":"法利賽人問：「神的國幾時來到？」耶穌回答說：「神的國來到不是眼所能見的。","notes":[],"heads":["神國的來到"]},{"n":21,"t":"人也不得說：『看哪，在這裏！看哪，在那裏！』因為神的國就在你們心裏。」","notes":["心裏：或譯中間"]},{"n":22,"t":"他又對門徒說：「日子將到，你們巴不得看見人子的一個日子，卻不得看見。","notes":[]},{"n":23,"t":"人將要對你們說：『看哪，在那裏！看哪，在這裏！』你們不要出去，也不要跟隨他們！","notes":[]},{"n":24,"t":"因為人子在他降臨的日子，好像閃電從天這邊一閃直照到天那邊。","notes":[]},{"n":25,"t":"只是他必須先受許多苦，又被這世代棄絕。","notes":[]},{"n":26,"t":"挪亞的日子怎樣，人子的日子也要怎樣。","notes":[]},{"n":27,"t":"那時候的人又吃又喝，又娶又嫁，到挪亞進方舟的那日，洪水就來，把他們全都滅了。","notes":[]},{"n":28,"t":"又好像羅得的日子；人又吃又喝，又買又賣，又耕種又蓋造。","notes":[]},{"n":29,"t":"到羅得出所多瑪的那日，就有火與硫磺從天上降下來，把他們全都滅了。","notes":[]},{"n":30,"t":"人子顯現的日子也要這樣。","notes":[]},{"n":31,"t":"當那日，人在房上，器具在屋裏，不要下來拿；人在田裏，也不要回家。","notes":[]},{"n":32,"t":"你們要回想羅得的妻子。","notes":[]},{"n":33,"t":"凡想要保全生命的，必喪掉生命；凡喪掉生命的，必救活生命。","notes":[]},{"n":34,"t":"我對你們說，當那一夜，兩個人在一個床上，要取去一個，撇下一個。","notes":[]},{"n":35,"t":"兩個女人一同推磨，要取去一個，撇下一個。」","notes":["有古卷加：36兩個人在田裏，要取去一個，撇下一個。"]},{"n":37,"t":"門徒說：「主啊，在哪裏有這事呢？」耶穌說：「屍首在哪裏，鷹也必聚在那裏。」","notes":[]}]},"18":{"heading":"寡婦和法官的比喻","verses":[{"n":1,"t":"耶穌設一個比喻，是要人常常禱告，不可灰心。","notes":[]},{"n":2,"t":"說：「某城裏有一個官，不懼怕神，也不尊重世人。","notes":[]},{"n":3,"t":"那城裏有個寡婦，常到他那裏，說：『我有一個對頭，求你給我伸冤。』","notes":[]},{"n":4,"t":"他多日不准， 後來心裏說：『我雖不懼怕神，也不尊重世人，","notes":[]},{"n":5,"t":"只因這寡婦煩擾我，我就給她伸冤吧，免得她常來纏磨我！』」","notes":[]},{"n":6,"t":"主說：「你們聽這不義之官所說的話。","notes":[]},{"n":7,"t":"神的選民晝夜呼籲他，他縱然為他們忍了多時，豈不終久給他們伸冤嗎？","notes":[]},{"n":8,"t":"我告訴你們，要快快地給他們伸冤了。然而，人子來的時候，遇得見世上有信德嗎？」","notes":[]},{"n":9,"t":"耶穌向那些仗著自己是義人，藐視別人的，設一個比喻，","notes":[],"heads":["法利賽人和稅吏的禱告"]},{"n":10,"t":"說：「有兩個人上殿裏去禱告：一個是法利賽人，一個是稅吏。","notes":[]},{"n":11,"t":"法利賽人站著，自言自語地禱告說：『神啊，我感謝你，我不像別人勒索、不義、姦淫，也不像這個稅吏。","notes":[]},{"n":12,"t":"我一個禮拜禁食兩次，凡我所得的都捐上十分之一。』","notes":[]},{"n":13,"t":"那稅吏遠遠地站著，連舉目望天也不敢，只捶著胸說：『神啊，開恩可憐我這個罪人！』","notes":[]},{"n":14,"t":"我告訴你們，這人回家去比那人倒算為義了；因為，凡自高的，必降為卑；自卑的，必升為高。」","notes":[]},{"n":15,"t":"有人抱著自己的嬰孩來見耶穌，要他摸他們；門徒看見就責備那些人。","notes":[],"heads":["耶穌為小孩祝福"]},{"n":16,"t":"耶穌卻叫他們來，說：「讓小孩子到我這裏來，不要禁止他們，因為在神國的正是這樣的人。","notes":[]},{"n":17,"t":"我實在告訴你們，凡要承受神國的，若不像小孩子，斷不能進去。」","notes":[]},{"n":18,"t":"有一個官問耶穌說：「良善的夫子，我該做甚麼事才可以承受永生？」","notes":[],"heads":["富足的官尋求永生之道"]},{"n":19,"t":"耶穌對他說：「你為甚麼稱我是良善的？除了神一位之外，再沒有良善的。","notes":[]},{"n":20,"t":"誡命你是曉得的：『不可姦淫；不可殺人；不可偷盜；不可作假見證；當孝敬父母。』」","notes":[]},{"n":21,"t":"那人說：「這一切我從小都遵守了。」","notes":[]},{"n":22,"t":"耶穌聽見了，就說：「你還缺少一件：要變賣你一切所有的，分給窮人，就必有財寶在天上；你還要來跟從我。」","notes":[]},{"n":23,"t":"他聽見這話，就甚憂愁，因為他很富足。","notes":[]},{"n":24,"t":"耶穌看見他，就說：「有錢財的人進神的國是何等的難哪！","notes":[]},{"n":25,"t":"駱駝穿過針的眼比財主進神的國還容易呢！」","notes":[]},{"n":26,"t":"聽見的人說：「這樣，誰能得救呢？」","notes":[]},{"n":27,"t":"耶穌說：「在人所不能的事，在神卻能。」","notes":[]},{"n":28,"t":"彼得說：「看哪，我們已經撇下自己所有的跟從你了。」","notes":[]},{"n":29,"t":"耶穌說：「我實在告訴你們，人為神的國撇下房屋，或是妻子、弟兄、父母、兒女，","notes":[]},{"n":30,"t":"沒有在今世不得百倍，在來世不得永生的。」","notes":[]},{"n":31,"t":"耶穌帶著十二個門徒，對他們說：「看哪，我們上耶路撒冷去，先知所寫的一切事都要成就在人子身上。","notes":[],"heads":["耶穌第三次預言受難和復活"]},{"n":32,"t":"他將要被交給外邦人；他們要戲弄他，凌辱他，吐唾沫在他臉上，","notes":[]},{"n":33,"t":"並要鞭打他，殺害他；第三日他要復活。」","notes":[]},{"n":34,"t":"這些事門徒一樣也不懂得，意思乃是隱藏的；他們不曉得所說的是甚麼。","notes":[]},{"n":35,"t":"耶穌將近耶利哥的時候，有一個瞎子坐在路旁討飯。","notes":[],"heads":["治好耶利哥的瞎子"]},{"n":36,"t":"聽見許多人經過，就問是甚麼事。","notes":[]},{"n":37,"t":"他們告訴他，是拿撒勒人耶穌經過。","notes":[]},{"n":38,"t":"他就呼叫說：「大衛的子孫耶穌啊，可憐我吧！」","notes":[]},{"n":39,"t":"在前頭走的人就責備他，不許他作聲；他卻越發喊叫說：「大衛的子孫，可憐我吧！」","notes":[]},{"n":40,"t":"耶穌站住，吩咐把他領過來，到了跟前，就問他說：","notes":[]},{"n":41,"t":"「你要我為你做甚麼？」他說：「主啊，我要能看見。」","notes":[]},{"n":42,"t":"耶穌說：「你可以看見！你的信救了你了。」","notes":[]},{"n":43,"t":"瞎子立刻看見了，就跟隨耶穌，一路歸榮耀與神。眾人看見這事，也讚美神。","notes":[]}]},"19":{"heading":"耶穌和撒該","verses":[{"n":1,"t":"耶穌進了耶利哥，正經過的時候，","notes":[]},{"n":2,"t":"有一個人名叫撒該，作稅吏長，是個財主。","notes":[]},{"n":3,"t":"他要看看耶穌是怎樣的人；只因人多，他的身量又矮，所以不得看見，","notes":[]},{"n":4,"t":"就跑到前頭，爬上桑樹，要看耶穌，因為耶穌必從那裏經過。","notes":[]},{"n":5,"t":"耶穌到了那裏，抬頭一看，對他說：「撒該，快下來！今天我必住在你家裏。」","notes":[]},{"n":6,"t":"他就急忙下來，歡歡喜喜地接待耶穌。","notes":[]},{"n":7,"t":"眾人看見，都私下議論說：「他竟到罪人家裏去住宿。」","notes":[]},{"n":8,"t":"撒該站著對主說：「主啊，我把所有的一半給窮人；我若訛詐了誰，就還他四倍。」","notes":[]},{"n":9,"t":"耶穌說：「今天救恩到了這家，因為他也是亞伯拉罕的子孫。","notes":[]},{"n":10,"t":"人子來，為要尋找、拯救失喪的人。」","notes":[]},{"n":11,"t":"眾人正在聽見這些話的時候，耶穌因為將近耶路撒冷，又因他們以為神的國快要顯出來，就另設一個比喻，說：","notes":[],"heads":["十錠銀子的比喻"]},{"n":12,"t":"「有一個貴冑往遠方去，要得國回來，","notes":[]},{"n":13,"t":"便叫了他的十個僕人來，交給他們十錠銀子，說：『你們去做生意，直等我回來。』","notes":["錠：原文作彌拿，一彌拿約銀十兩"]},{"n":14,"t":"他本國的人卻恨他，打發使者隨後去，說：『我們不願意這個人作我們的王。』","notes":[]},{"n":15,"t":"他既得國回來，就吩咐叫那領銀子的僕人來，要知道他們做生意賺了多少。","notes":[]},{"n":16,"t":"頭一個上來，說：『主啊，你的一錠銀子已經賺了十錠。』","notes":[]},{"n":17,"t":"主人說：『好！良善的僕人，你既在最小的事上有忠心，可以有權柄管十座城。』","notes":[]},{"n":18,"t":"第二個來，說：『主啊， 你的一錠銀子已經賺了五錠。』","notes":[]},{"n":19,"t":"主人說：『你也可以管五座城。』","notes":[]},{"n":20,"t":"又有一個來說：『主啊，看哪，你的一錠銀子在這裏，我把它包在手巾裏存著。","notes":[]},{"n":21,"t":"我原是怕你，因為你是嚴厲的人；沒有放下的，還要去拿， 沒有種下的，還要去收。』","notes":[]},{"n":22,"t":"主人對他說：『你這惡僕，我要憑你的口定你的罪。你既知道我是嚴厲的人，沒有放下的，還要去拿，沒有種下的，還要去收，","notes":[]},{"n":23,"t":"為甚麼不把我的銀子交給銀行，等我來的時候，連本帶利都可以要回來呢？』","notes":[]},{"n":24,"t":"就對旁邊站著的人說：『奪過他這一錠來，給那有十錠的。』","notes":[]},{"n":25,"t":"他們說：『主啊，他已經有十錠了。』","notes":[]},{"n":26,"t":"主人說：『我告訴你們，凡有的，還要加給他；沒有的，連他所有的也要奪過來。","notes":[]},{"n":27,"t":"至於我那些仇敵，不要我作他們王的，把他們拉來，在我面前殺了吧！』」","notes":[]},{"n":28,"t":"耶穌說完了這話，就在前面走，上耶路撒冷去。","notes":[],"heads":["光榮地進耶路撒冷"]},{"n":29,"t":"將近伯法其和伯大尼，在一座山名叫橄欖山那裏，就打發兩個門徒，說：","notes":[]},{"n":30,"t":"「你們往對面村子裏去，進去的時候，必看見一匹驢駒拴在那裏，是從來沒有人騎過的，可以解開牽來。","notes":[]},{"n":31,"t":"若有人問為甚麼解牠，你們就說：『主要用牠。』」","notes":[]},{"n":32,"t":"打發的人去了，所遇見的正如耶穌所說的。","notes":[]},{"n":33,"t":"他們解驢駒的時候，主人問他們說：「解驢駒做甚麼？」","notes":[]},{"n":34,"t":"他們說：「主要用牠。」","notes":[]},{"n":35,"t":"他們牽到耶穌那裏，把自己的衣服搭在上面，扶著耶穌騎上。","notes":[]},{"n":36,"t":"走的時候，眾人把衣服鋪在路上。","notes":[]},{"n":37,"t":"將近耶路撒冷，正下橄欖山的時候，眾門徒因所見過的一切異能，都歡樂起來，大聲讚美神，","notes":[]},{"n":38,"t":"說：奉主名來的王是應當稱頌的！在天上有和平；在至高之處有榮光。","notes":[]},{"n":39,"t":"眾人中有幾個法利賽人對耶穌說：「夫子，責備你的門徒吧！」","notes":[]},{"n":40,"t":"耶穌說：「我告訴你們，若是他們閉口不說，這些石頭必要呼叫起來。」","notes":[]},{"n":41,"t":"耶穌快到耶路撒冷，看見城，就為它哀哭，","notes":[]},{"n":42,"t":"說：「巴不得你在這日子知道關係你平安的事；無奈這事現在是隱藏的，叫你的眼看不出來。","notes":[]},{"n":43,"t":"因為日子將到，你的仇敵必築起土壘，周圍環繞你，四面困住你，","notes":[]},{"n":44,"t":"並要掃滅你和你裏頭的兒女，連一塊石頭也不留在石頭上，因你不知道眷顧你的時候。」","notes":[]},{"n":45,"t":"耶穌進了殿，趕出裏頭做買賣的人，","notes":[],"heads":["潔淨聖殿"]},{"n":46,"t":"對他們說：「經上說：我的殿必作禱告的殿，你們倒使它成為賊窩了。」","notes":[]},{"n":47,"t":"耶穌天天在殿裏教訓人。祭司長和文士與百姓的尊長都想要殺他，","notes":[]},{"n":48,"t":"但尋不出法子來，因為百姓都側耳聽他。","notes":[]}]},"20":{"heading":"質問耶穌的權柄","verses":[{"n":1,"t":"有一天，耶穌在殿裏教訓百姓，講福音的時候，祭司長和文士並長老上前來，","notes":[]},{"n":2,"t":"問他說：「你告訴我們，你仗著甚麼權柄做這些事？給你這權柄的是誰呢？」","notes":[]},{"n":3,"t":"耶穌回答說：「我也要問你們一句話，你們且告訴我。","notes":[]},{"n":4,"t":"約翰的洗禮是從天上來的？是從人間來的呢？」","notes":[]},{"n":5,"t":"他們彼此商議說：「我們若說『從天上來』，他必說：『你們為甚麼不信他呢？』","notes":[]},{"n":6,"t":"若說『從人間來』，百姓都要用石頭打死我們，因為他們信約翰是先知。」","notes":[]},{"n":7,"t":"於是回答說：「不知道是從哪裏來的。」","notes":[]},{"n":8,"t":"耶穌說：「我也不告訴你們，我仗著甚麼權柄做這些事。」","notes":[]},{"n":9,"t":"耶穌就設比喻對百姓說：「有人栽了一個葡萄園，租給園戶，就往外國去住了許久。","notes":[],"heads":["凶惡園戶的比喻"]},{"n":10,"t":"到了時候，打發一個僕人到園戶那裏去，叫他們把園中當納的果子交給他；園戶竟打了他，叫他空手回去。","notes":[]},{"n":11,"t":"又打發一個僕人去，他們也打了他，並且凌辱他，叫他空手回去。","notes":[]},{"n":12,"t":"又打發第三個僕人去，他們也打傷了他，把他推出去了。","notes":[]},{"n":13,"t":"園主說：『我怎麼辦呢？我要打發我的愛子去，或者他們尊敬他。』","notes":[]},{"n":14,"t":"不料，園戶看見他，就彼此商量說：『這是承受產業的，我們殺他吧，使產業歸於我們！』","notes":[]},{"n":15,"t":"於是把他推出葡萄園外，殺了。這樣，葡萄園的主人要怎樣處治他們呢？","notes":[]},{"n":16,"t":"他要來除滅這些園戶，將葡萄園轉給別人。」聽見的人說：「這是萬不可的！」","notes":[]},{"n":17,"t":"耶穌看著他們說：「經上記著：匠人所棄的石頭已作了房角的頭塊石頭。這是甚麼意思呢？","notes":[]},{"n":18,"t":"凡掉在那石頭上的，必要跌碎；那石頭掉在誰的身上，就要把誰砸得稀爛。」","notes":[]},{"n":19,"t":"文士和祭司長看出這比喻是指著他們說的，當時就想要下手拿他，只是懼怕百姓。","notes":[],"heads":["納稅給凱撒的問題"]},{"n":20,"t":"於是窺探耶穌，打發奸細裝作好人，要在他的話上得把柄，好將他交在巡撫的政權之下。","notes":[]},{"n":21,"t":"奸細就問耶穌說：「夫子，我們曉得你所講所傳都是正道，也不取人的外貌，乃是誠誠實實傳神的道。","notes":[]},{"n":22,"t":"我們納稅給凱撒，可以不可以？」","notes":[]},{"n":23,"t":"耶穌看出他們的詭詐，就對他們說：","notes":[]},{"n":24,"t":"「拿一個銀錢來給我看。這像和這號是誰的？」他們說：「是凱撒的。」","notes":[]},{"n":25,"t":"耶穌說：「這樣，凱撒的物當歸給凱撒，神的物當歸給神。」","notes":[]},{"n":26,"t":"他們當著百姓，在這話上得不著把柄，又希奇他的應對，就閉口無言了。","notes":[]},{"n":27,"t":"撒都該人常說沒有復活的事。有幾個來問耶穌說：","notes":[],"heads":["復活的問題"]},{"n":28,"t":"「夫子！摩西為我們寫著說：『人若有妻無子就死了，他兄弟當娶他的妻，為哥哥生子立後。』","notes":[]},{"n":29,"t":"有弟兄七人，第一個娶了妻，沒有孩子死了；","notes":[]},{"n":30,"t":"第二個、第三個也娶過她；","notes":[]},{"n":31,"t":"那七個人都娶過她，沒有留下孩子就死了。","notes":[]},{"n":32,"t":"後來婦人也死了。","notes":[]},{"n":33,"t":"這樣，當復活的時候，她是哪一個的妻子呢？因為他們七個人都娶過她。」","notes":[]},{"n":34,"t":"耶穌說：「這世界的人有娶有嫁；","notes":[]},{"n":35,"t":"惟有算為配得那世界，與從死裏復活的人也不娶也不嫁；","notes":[]},{"n":36,"t":"因為他們不能再死，和天使一樣；既是復活的人，就為神的兒子。","notes":[]},{"n":37,"t":"至於死人復活，摩西在荊棘篇上，稱主是亞伯拉罕的神，以撒的神，雅各的神，就指示明白了。","notes":[]},{"n":38,"t":"神原不是死人的神，乃是活人的神；因為在他那裏，人都是活的。」","notes":["那裏：或譯看來"]},{"n":39,"t":"有幾個文士說：「夫子！你說得好。」","notes":[]},{"n":40,"t":"以後他們不敢再問他甚麼。","notes":[]},{"n":41,"t":"耶穌對他們說：「人怎麼說基督是大衛的子孫呢？","notes":[],"heads":["大衛子孫的問題"]},{"n":42,"t":"詩篇上大衛自己說：主對我主說：你坐在我的右邊，","notes":[]},{"n":43,"t":"等我使你仇敵作你的腳凳。","notes":[]},{"n":44,"t":"大衛既稱他為主，他怎麼又是大衛的子孫呢？」","notes":[]},{"n":45,"t":"眾百姓聽的時候，耶穌對門徒說：","notes":[],"heads":["譴責文士"]},{"n":46,"t":"「你們要防備文士。他們好穿長衣遊行，喜愛人在街市上問他們安，又喜愛會堂裏的高位，筵席上的首座；","notes":[]},{"n":47,"t":"他們侵吞寡婦的家產，假意作很長的禱告。這些人要受更重的刑罰！」","notes":[]}]},"21":{"heading":"寡婦的奉獻","verses":[{"n":1,"t":"耶穌抬頭觀看，見財主把捐項投在庫裏，","notes":[]},{"n":2,"t":"又見一個窮寡婦投了兩個小錢，","notes":[]},{"n":3,"t":"就說：「我實在告訴你們，這窮寡婦所投的比眾人還多；","notes":[]},{"n":4,"t":"因為眾人都是自己有餘，拿出來投在捐項裏，但這寡婦是自己不足，把她一切養生的都投上了。」","notes":[]},{"n":5,"t":"有人談論聖殿是用美石和供物妝飾的；","notes":[],"heads":["預言聖殿被毀"]},{"n":6,"t":"耶穌就說：「論到你們所看見的這一切，將來日子到了，在這裏沒有一塊石頭留在石頭上，不被拆毀了。」","notes":[]},{"n":7,"t":"他們問他說：「夫子！甚麼時候有這事呢？這事將到的時候有甚麼預兆呢？」","notes":[],"heads":["預兆和逼迫"]},{"n":8,"t":"耶穌說：「你們要謹慎，不要受迷惑；因為將來有好些人冒我的名來，說：『我是基督』，又說：『時候近了』，你們不要跟從他們！","notes":[]},{"n":9,"t":"你們聽見打仗和擾亂的事，不要驚惶；因為這些事必須先有，只是末期不能立時就到。」","notes":[]},{"n":10,"t":"當時，耶穌對他們說：「民要攻打民，國要攻打國；","notes":[]},{"n":11,"t":"地要大大震動，多處必有饑荒、瘟疫，又有可怕的異象和大神蹟從天上顯現。","notes":[]},{"n":12,"t":"但這一切的事以先，人要下手拿住你們，逼迫你們，把你們交給會堂，並且收在監裏，又為我的名拉你們到君王諸侯面前。","notes":[]},{"n":13,"t":"但這些事終必為你們的見證。","notes":[]},{"n":14,"t":"所以，你們當立定心意，不要預先思想怎樣分訴；","notes":[]},{"n":15,"t":"因為我必賜你們口才、智慧，是你們一切敵人所敵不住、駁不倒的。","notes":[]},{"n":16,"t":"連你們的父母、弟兄、親族、朋友也要把你們交官；你們也有被他們害死的。","notes":[]},{"n":17,"t":"你們要為我的名被眾人恨惡，","notes":[]},{"n":18,"t":"然而，你們連一根頭髮也必不損壞。","notes":[]},{"n":19,"t":"你們常存忍耐，就必保全靈魂。」","notes":["或譯：必得生命"]},{"n":20,"t":"「你們看見耶路撒冷被兵圍困，就可知道它成荒場的日子近了。","notes":[],"heads":["預言耶路撒冷被毀"]},{"n":21,"t":"那時，在猶太的應當逃到山上；在城裏的應當出來；在鄉下的不要進城；","notes":[]},{"n":22,"t":"因為這是報應的日子，使經上所寫的都得應驗。","notes":[]},{"n":23,"t":"當那些日子，懷孕的和奶孩子的有禍了！因為將有大災難降在這地方，也有震怒臨到這百姓。","notes":[]},{"n":24,"t":"他們要倒在刀下，又被擄到各國去。耶路撒冷要被外邦人踐踏，直到外邦人的日期滿了。」","notes":[]},{"n":25,"t":"「日、月、星辰要顯出異兆，地上的邦國也有困苦；因海中波浪的響聲，就慌慌不定。","notes":[],"heads":["人子的降臨"]},{"n":26,"t":"天勢都要震動，人想起那將要臨到世界的事，就都嚇得魂不附體。","notes":[]},{"n":27,"t":"那時，他們要看見人子有能力，有大榮耀駕雲降臨。","notes":[]},{"n":28,"t":"一有這些事，你們就當挺身昂首，因為你們得贖的日子近了。」","notes":[]},{"n":29,"t":"耶穌又設比喻對他們說：「你們看無花果樹和各樣的樹；它發芽的時候，你們一看見，自然曉得夏天近了。","notes":[],"end":30,"heads":["從無花果樹學功課"]},{"n":31,"t":"這樣，你們看見這些事漸漸地成就，也該曉得神的國近了。","notes":[]},{"n":32,"t":"我實在告訴你們，這世代還沒有過去，這些事都要成就。","notes":[]},{"n":33,"t":"天地要廢去，我的話卻不能廢去。」","notes":[]},{"n":34,"t":"「你們要謹慎，恐怕因貪食、醉酒，並今生的思慮累住你們的心，那日子就如同網羅忽然臨到你們；","notes":[],"heads":["勸告門徒警醒"]},{"n":35,"t":"因為那日子要這樣臨到全地上一切居住的人。","notes":[]},{"n":36,"t":"你們要時時警醒，常常祈求，使你們能逃避這一切要來的事，得以站立在人子面前。」","notes":[]},{"n":37,"t":"耶穌每日在殿裏教訓人，每夜出城在一座山，名叫橄欖山住宿。","notes":[]},{"n":38,"t":"眾百姓清早上聖殿，到耶穌那裏，要聽他講道。","notes":[]}]},"22":{"heading":"殺害耶穌的陰謀","verses":[{"n":1,"t":"除酵節（又名逾越節）近了。","notes":[]},{"n":2,"t":"祭司長和文士想法子怎麼才能殺害耶穌，是因他們懼怕百姓。","notes":[]},{"n":3,"t":"這時，撒但入了那稱為加略人猶大的心；他本是十二門徒裏的一個。","notes":[]},{"n":4,"t":"他去和祭司長並守殿官商量，怎麼可以把耶穌交給他們。","notes":[]},{"n":5,"t":"他們歡喜，就約定給他銀子。","notes":[]},{"n":6,"t":"他應允了，就找機會，要趁眾人不在跟前的時候把耶穌交給他們。","notes":[]},{"n":7,"t":"除酵節，須宰逾越羊羔的那一天到了。","notes":[],"heads":["預備逾越節的筵席"]},{"n":8,"t":"耶穌打發彼得、約翰，說：「你們去為我們預備逾越節的筵席，好叫我們吃。」","notes":[]},{"n":9,"t":"他們問他說：「要我們在哪裏預備？」","notes":[]},{"n":10,"t":"耶穌說：「你們進了城，必有人拿著一瓶水迎面而來，你們就跟著他，到他所進的房子裏去，","notes":[]},{"n":11,"t":"對那家的主人說：『夫子說：客房在哪裏？我與門徒好在那裏吃逾越節的筵席。』","notes":[]},{"n":12,"t":"他必指給你們擺設整齊的一間大樓，你們就在那裏預備。」","notes":[]},{"n":13,"t":"他們去了，所遇見的正如耶穌所說的；他們就預備了逾越節的筵席。","notes":[]},{"n":14,"t":"時候到了，耶穌坐席，使徒也和他同坐。","notes":[],"heads":["設立主的晚餐"]},{"n":15,"t":"耶穌對他們說：「我很願意在受害以先和你們吃這逾越節的筵席。","notes":[]},{"n":16,"t":"我告訴你們，我不再吃這筵席，直到成就在神的國裏。」","notes":[]},{"n":17,"t":"耶穌接過杯來，祝謝了，說：「你們拿這個，大家分著喝。","notes":[]},{"n":18,"t":"我告訴你們，從今以後，我不再喝這葡萄汁，直等神的國來到。」","notes":[]},{"n":19,"t":"又拿起餅來，祝謝了，就擘開，遞給他們，說：「這是我的身體，為你們捨的，你們也應當如此行，為的是記念我。」","notes":[]},{"n":20,"t":"飯後也照樣拿起杯來，說：「這杯是用我血所立的新約，是為你們流出來的。","notes":[]},{"n":21,"t":"看哪， 那賣我之人的手與我一同在桌子上。","notes":[]},{"n":22,"t":"人子固然要照所預定的去世，但賣人子的人有禍了！」","notes":[]},{"n":23,"t":"他們就彼此對問，是哪一個要做這事。","notes":[]},{"n":24,"t":"門徒起了爭論，他們中間哪一個可算為大。","notes":[],"heads":["爭論誰為大"]},{"n":25,"t":"耶穌說：「外邦人有君王為主治理他們，那掌權管他們的稱為恩主。","notes":[]},{"n":26,"t":"但你們不可這樣；你們裏頭為大的，倒要像年幼的，為首領的，倒要像服事人的。","notes":[]},{"n":27,"t":"是誰為大？是坐席的呢？是服事人的呢？不是坐席的大嗎？然而，我在你們中間如同服事人的。","notes":[]},{"n":28,"t":"我在磨煉之中，常和我同在的就是你們。","notes":[]},{"n":29,"t":"我將國賜給你們，正如我父賜給我一樣，","notes":[]},{"n":30,"t":"叫你們在我國裏，坐在我的席上吃喝，並且坐在寶座上，審判以色列十二個支派。」","notes":[]},{"n":31,"t":"主又說：「西門！西門！撒但想要得著你們，好篩你們像篩麥子一樣；","notes":[],"heads":["預言彼得不認主"]},{"n":32,"t":"但我已經為你祈求，叫你不至於失了信心。你回頭以後，要堅固你的弟兄。」","notes":[]},{"n":33,"t":"彼得說：「主啊，我就是同你下監，同你受死，也是甘心！」","notes":[]},{"n":34,"t":"耶穌說：「彼得，我告訴你，今日雞還沒有叫，你要三次說不認得我。」","notes":[]},{"n":35,"t":"耶穌又對他們說：「我差你們出去的時候，沒有錢囊，沒有口袋，沒有鞋，你們缺少甚麼沒有？」他們說：「沒有。」","notes":[],"heads":["錢囊、口袋、刀"]},{"n":36,"t":"耶穌說：「但如今有錢囊的可以帶著，有口袋的也可以帶著，沒有刀的要賣衣服買刀。","notes":[]},{"n":37,"t":"我告訴你們，經上寫著說：『他被列在罪犯之中。』這話必應驗在我身上，因為那關係我的事必然成就。」","notes":[]},{"n":38,"t":"他們說：「主啊，請看！這裏有兩把刀。」耶穌說：「夠了。」","notes":[]},{"n":39,"t":"耶穌出來，照常往橄欖山去，門徒也跟隨他。","notes":[],"heads":["在橄欖山上禱告"]},{"n":40,"t":"到了那地方，就對他們說：「你們要禱告，免得入了迷惑。」","notes":[]},{"n":41,"t":"於是離開他們約有扔一塊石頭那麼遠，跪下禱告，","notes":[]},{"n":42,"t":"說：「父啊！你若願意，就把這杯撤去；然而，不要成就我的意思，只要成就你的意思。」","notes":[]},{"n":43,"t":"有一位天使從天上顯現，加添他的力量。","notes":[]},{"n":44,"t":"耶穌極其傷痛，禱告更加懇切，汗珠如大血點滴在地上。","notes":[]},{"n":45,"t":"禱告完了，就起來，到門徒那裏，見他們因為憂愁都睡著了，","notes":[]},{"n":46,"t":"就對他們說：「你們為甚麼睡覺呢？起來禱告，免得入了迷惑！」","notes":[]},{"n":47,"t":"說話之間，來了許多人。那十二個門徒裏名叫猶大的，走在前頭，就近耶穌，要與他親嘴。","notes":[],"heads":["耶穌被捕"]},{"n":48,"t":"耶穌對他說：「猶大！你用親嘴的暗號賣人子嗎？」","notes":[]},{"n":49,"t":"左右的人見光景不好，就說：「主啊！我們拿刀砍可以不可以？」","notes":[]},{"n":50,"t":"內中有一個人把大祭司的僕人砍了一刀，削掉了他的右耳。","notes":[]},{"n":51,"t":"耶穌說：「到了這個地步，由他們吧！」就摸那人的耳朵，把他治好了。","notes":[]},{"n":52,"t":"耶穌對那些來拿他的祭司長和守殿官並長老說：「你們帶著刀棒出來拿我，如同拿強盜嗎？","notes":[]},{"n":53,"t":"我天天同你們在殿裏，你們不下手拿我。現在卻是你們的時候，黑暗掌權了。」","notes":[]},{"n":54,"t":"他們拿住耶穌，把他帶到大祭司的宅裏。彼得遠遠地跟著。","notes":[],"heads":["彼得三次不認主"]},{"n":55,"t":"他們在院子裏生了火，一同坐著；彼得也坐在他們中間。","notes":[]},{"n":56,"t":"有一個使女看見彼得坐在火光裏，就定睛看他，說：「這個人素來也是同那人一夥的。」","notes":[]},{"n":57,"t":"彼得卻不承認，說：「女子，我不認得他。」","notes":[]},{"n":58,"t":"過了不多的時候，又有一個人看見他，說：「你也是他們一黨的。」彼得說：「你這個人！我不是。」","notes":[]},{"n":59,"t":"約過了一小時，又有一個人極力地說：「他實在是同那人一夥的，因為他也是加利利人。」","notes":[]},{"n":60,"t":"彼得說：「你這個人！我不曉得你說的是甚麼！」正說話之間，雞就叫了。","notes":[]},{"n":61,"t":"主轉過身來看彼得，彼得便想起主對他所說的話：「今日雞叫以先，你要三次不認我。」","notes":[]},{"n":62,"t":"他就出去痛哭。","notes":[]},{"n":63,"t":"看守耶穌的人戲弄他，打他，","notes":[],"heads":["戲弄鞭打耶穌"]},{"n":64,"t":"又蒙著他的眼，問他說：「你是先知，告訴我們打你的是誰？」","notes":[]},{"n":65,"t":"他們還用許多別的話辱罵他。","notes":[]},{"n":66,"t":"天一亮，民間的眾長老連祭司長帶文士都聚會， 把耶穌帶到他們的公會裏，","notes":[],"heads":["耶穌在公會裏受審"]},{"n":67,"t":"說：「你若是基督，就告訴我們。」耶穌說：「我若告訴你們，你們也不信；","notes":[]},{"n":68,"t":"我若問你們，你們也不回答。","notes":[]},{"n":69,"t":"從今以後，人子要坐在神權能的右邊。」","notes":[]},{"n":70,"t":"他們都說：「這樣，你是神的兒子嗎？」耶穌說：「你們所說的是。」","notes":[]},{"n":71,"t":"他們說：「何必再用見證呢？他親口所說的，我們都親自聽見了。」","notes":[]}]},"23":{"heading":"耶穌在彼拉多面前受審","verses":[{"n":1,"t":"眾人都起來，把耶穌解到彼拉多面前，","notes":[]},{"n":2,"t":"就告他說：「我們見這人誘惑國民，禁止納稅給凱撒，並說自己是基督，是王。」","notes":[]},{"n":3,"t":"彼拉多問耶穌說：「你是猶太人的王嗎？」耶穌回答說：「你說的是。」","notes":[]},{"n":4,"t":"彼拉多對祭司長和眾人說：「我查不出這人有甚麼罪來。」","notes":[]},{"n":5,"t":"但他們越發極力地說：「他煽惑百姓，在猶太遍地傳道，從加利利起，直到這裏了。」","notes":[]},{"n":6,"t":"彼拉多一聽見，就問：「這人是加利利人嗎？」","notes":[],"heads":["希律藐視耶穌"]},{"n":7,"t":"既曉得耶穌屬希律所管，就把他送到希律那裏去。那時希律正在耶路撒冷。","notes":[]},{"n":8,"t":"希律看見耶穌，就很歡喜；因為聽見過他的事，久已想要見他，並且指望看他行一件神蹟，","notes":[]},{"n":9,"t":"於是問他許多的話，耶穌卻一言不答。","notes":[]},{"n":10,"t":"祭司長和文士都站著，極力地告他。","notes":[]},{"n":11,"t":"希律和他的兵丁就藐視耶穌，戲弄他，給他穿上華麗衣服，把他送回彼拉多那裏去。","notes":[]},{"n":12,"t":"從前希律和彼拉多彼此有仇，在那一天就成了朋友。","notes":[]},{"n":13,"t":"彼拉多傳齊了祭司長和官府並百姓，","notes":[],"heads":["耶穌被判死刑"]},{"n":14,"t":"就對他們說：「你們解這人到我這裏，說他是誘惑百姓的。看哪，我也曾將你們告他的事，在你們面前審問他，並沒有查出他甚麼罪來；","notes":[]},{"n":15,"t":"就是希律也是如此，所以把他送回來。可見他沒有做甚麼該死的事。","notes":[]},{"n":16,"t":"故此，我要責打他，把他釋放了。」","notes":["有古卷加：17每逢這節期，巡撫必須釋放一個囚犯給他們。"]},{"n":18,"t":"眾人卻一齊喊著說：「除掉這個人！釋放巴拉巴給我們！」","notes":[]},{"n":19,"t":"這巴拉巴是因在城裏作亂殺人，下在監裏的。","notes":[]},{"n":20,"t":"彼拉多願意釋放耶穌，就又勸解他們。","notes":[]},{"n":21,"t":"無奈他們喊著說：「釘他十字架！釘他十字架！」","notes":[]},{"n":22,"t":"彼拉多第三次對他們說：「為甚麼呢？這人做了甚麼惡事呢？我並沒有查出他甚麼該死的罪來。所以，我要責打他，把他釋放了。」","notes":[]},{"n":23,"t":"他們大聲催逼彼拉多，求他把耶穌釘在十字架上。他們的聲音就得了勝。","notes":[]},{"n":24,"t":"彼拉多這才照他們所求的定案，","notes":[]},{"n":25,"t":"把他們所求的那作亂殺人、下在監裏的釋放了，把耶穌交給他們，任憑他們的意思行。","notes":[]},{"n":26,"t":"帶耶穌去的時候，有一個古利奈人西門，從鄉下來；他們就抓住他，把十字架擱在他身上，叫他背著跟隨耶穌。","notes":[],"heads":["耶穌被釘十字架"]},{"n":27,"t":"有許多百姓跟隨耶穌，內中有好些婦女；婦女們為他號咷痛哭。","notes":[]},{"n":28,"t":"耶穌轉身對她們說：「耶路撒冷的女子，不要為我哭，當為自己和自己的兒女哭。","notes":[]},{"n":29,"t":"因為日子要到，人必說：『不生育的，和未曾懷胎的，未曾乳養嬰孩的，有福了！』","notes":[]},{"n":30,"t":"那時，人要向大山說：倒在我們身上！向小山說：遮蓋我們！","notes":[]},{"n":31,"t":"「這些事既行在有汁水的樹上，那枯乾的樹將來怎麼樣呢？」","notes":[]},{"n":32,"t":"又有兩個犯人，和耶穌一同帶來處死。","notes":[]},{"n":33,"t":"到了一個地方，名叫「髑髏地」，就在那裏把耶穌釘在十字架上，又釘了兩個犯人：一個在左邊，一個在右邊。","notes":[]},{"n":34,"t":"當下耶穌說：「父啊！赦免他們；因為他們所做的，他們不曉得。」兵丁就拈鬮分他的衣服。","notes":[]},{"n":35,"t":"百姓站在那裏觀看。官府也嗤笑他，說：「他救了別人；他若是基督，神所揀選的，可以救自己吧！」","notes":[]},{"n":36,"t":"兵丁也戲弄他，上前拿醋送給他喝，","notes":[]},{"n":37,"t":"說：「你若是猶太人的王，可以救自己吧！」","notes":[]},{"n":38,"t":"在耶穌以上有一個牌子寫著：「這是猶太人的王。」","notes":["有古卷加：用希臘、羅馬、希伯來的文字"]},{"n":39,"t":"那同釘的兩個犯人有一個譏笑他，說：「你不是基督嗎？可以救自己和我們吧！」","notes":[]},{"n":40,"t":"那一個就應聲責備他，說：「你既是一樣受刑的，還不怕神嗎？","notes":[]},{"n":41,"t":"我們是應該的，因我們所受的與我們所做的相稱，但這個人沒有做過一件不好的事。」","notes":[]},{"n":42,"t":"就說：「耶穌啊，你得國降臨的時候，求你記念我！」","notes":[]},{"n":43,"t":"耶穌對他說：「我實在告訴你，今日你要同我在樂園裏了。」","notes":[]},{"n":44,"t":"那時約有午正，遍地都黑暗了，直到申初，","notes":[],"heads":["耶穌的死"]},{"n":45,"t":"日頭變黑了；殿裏的幔子從當中裂為兩半。","notes":[]},{"n":46,"t":"耶穌大聲喊著說：「父啊！我將我的靈魂交在你手裏。」說了這話，氣就斷了。","notes":[]},{"n":47,"t":"百夫長看見所成的事，就歸榮耀與神，說：「這真是個義人！」","notes":[]},{"n":48,"t":"聚集觀看的眾人見了這所成的事都捶著胸回去了。","notes":[]},{"n":49,"t":"還有一切與耶穌熟識的人，和從加利利跟著他來的婦女們，都遠遠地站著看這些事。","notes":[]},{"n":50,"t":"有一個人名叫約瑟，是個議士，為人善良公義；","notes":[],"heads":["耶穌的安葬"]},{"n":51,"t":"眾人所謀所為，他並沒有附從。他本是猶太、亞利馬太城裏素常盼望神國的人。","notes":[]},{"n":52,"t":"這人去見彼拉多，求耶穌的身體，","notes":[]},{"n":53,"t":"就取下來，用細麻布裹好，安放在石頭鑿成的墳墓裏；那裏頭從來沒有葬過人。","notes":[]},{"n":54,"t":"那日是預備日，安息日也快到了。","notes":[]},{"n":55,"t":"那些從加利利和耶穌同來的婦女跟在後面，看見了墳墓和他的身體怎樣安放。","notes":[]},{"n":56,"t":"她們就回去，預備了香料香膏。她們在安息日，便遵著誡命安息了。","notes":[]}]},"24":{"heading":"耶穌復活","verses":[{"n":1,"t":"七日的頭一日，黎明的時候，那些婦女帶著所預備的香料來到墳墓前，","notes":[]},{"n":2,"t":"看見石頭已經從墳墓滾開了，","notes":[]},{"n":3,"t":"她們就進去，只是不見主耶穌的身體。","notes":[]},{"n":4,"t":"正在猜疑之間，忽然有兩個人站在旁邊，衣服放光。","notes":[]},{"n":5,"t":"婦女們驚怕，將臉伏地。那兩個人就對她們說：「為甚麼在死人中找活人呢？","notes":[]},{"n":6,"t":"他不在這裏，已經復活了。當記念他還在加利利的時候怎樣告訴你們，","notes":[]},{"n":7,"t":"說：『人子必須被交在罪人手裏，釘在十字架上，第三日復活。』」","notes":[]},{"n":8,"t":"她們就想起耶穌的話來，","notes":[]},{"n":9,"t":"便從墳墓那裏回去，把這一切的事告訴十一個使徒和其餘的人。","notes":[]},{"n":10,"t":"那告訴使徒的就是抹大拉的馬利亞和約亞拿，並雅各的母親馬利亞，還有與她們在一處的婦女。","notes":[]},{"n":11,"t":"她們這些話，使徒以為是胡言，就不相信。","notes":[]},{"n":12,"t":"彼得起來，跑到墳墓前，低頭往裏看，見細麻布獨在一處，就回去了，心裏希奇所成的事。","notes":[]},{"n":13,"t":"正當那日，門徒中有兩個人往一個村子去；這村子名叫以馬忤斯，離耶路撒冷約有二十五里。","notes":[],"heads":["在以馬忤斯的路上"]},{"n":14,"t":"他們彼此談論所遇見的這一切事。","notes":[]},{"n":15,"t":"正談論相問的時候，耶穌親自就近他們，和他們同行；","notes":[]},{"n":16,"t":"只是他們的眼睛迷糊了，不認識他。","notes":[]},{"n":17,"t":"耶穌對他們說：「你們走路彼此談論的是甚麼事呢？」他們就站住，臉上帶著愁容。","notes":[]},{"n":18,"t":"二人中有一個名叫革流巴的回答說：「你在耶路撒冷作客，還不知道這幾天在那裏所出的事嗎？」","notes":[]},{"n":19,"t":"耶穌說：「甚麼事呢？」他們說：「就是拿撒勒人耶穌的事。他是個先知，在神和眾百姓面前，說話行事都有大能。","notes":[]},{"n":20,"t":"祭司長和我們的官府竟把他解去，定了死罪，釘在十字架上。","notes":[]},{"n":21,"t":"但我們素來所盼望、要贖以色列民的就是他！不但如此，而且這事成就，現在已經三天了。","notes":[]},{"n":22,"t":"再者，我們中間有幾個婦女使我們驚奇；她們清早到了墳墓那裏，","notes":[]},{"n":23,"t":"不見他的身體，就回來告訴我們，說看見了天使顯現，說他活了。","notes":[]},{"n":24,"t":"又有我們的幾個人往墳墓那裏去，所遇見的正如婦女們所說的，只是沒有看見他。」","notes":[]},{"n":25,"t":"耶穌對他們說：「無知的人哪，先知所說的一切話，你們的心信得太遲鈍了。","notes":[]},{"n":26,"t":"基督這樣受害，又進入他的榮耀，豈不是應當的嗎？」","notes":[]},{"n":27,"t":"於是從摩西和眾先知起，凡經上所指著自己的話都給他們講解明白了。","notes":[]},{"n":28,"t":"將近他們所去的村子，耶穌好像還要往前行，","notes":[]},{"n":29,"t":"他們卻強留他，說：「時候晚了，日頭已經平西了，請你同我們住下吧！」耶穌就進去，要同他們住下。","notes":[]},{"n":30,"t":"到了坐席的時候，耶穌拿起餅來，祝謝了，擘開，遞給他們。","notes":[]},{"n":31,"t":"他們的眼睛明亮了，這才認出他來。忽然耶穌不見了。","notes":[]},{"n":32,"t":"他們彼此說：「在路上，他和我們說話，給我們講解聖經的時候，我們的心豈不是火熱的嗎？」","notes":[]},{"n":33,"t":"他們就立時起身，回耶路撒冷去，正遇見十一個使徒和他們的同人聚集在一處，","notes":[]},{"n":34,"t":"說：「主果然復活，已經現給西門看了。」","notes":[]},{"n":35,"t":"兩個人就把路上所遇見，和擘餅的時候怎麼被他們認出來的事，都述說了一遍。","notes":[]},{"n":36,"t":"正說這話的時候，耶穌親自站在他們當中，說：「願你們平安！」","notes":[],"heads":["向門徒顯現"]},{"n":37,"t":"他們卻驚慌害怕，以為所看見的是魂。","notes":[]},{"n":38,"t":"耶穌說：「你們為甚麼愁煩？為甚麼心裏起疑念呢？","notes":[]},{"n":39,"t":"你們看我的手，我的腳，就知道實在是我了。摸我看看！魂無骨無肉，你們看，我是有的。」","notes":[]},{"n":40,"t":"說了這話，就把手和腳給他們看。","notes":[]},{"n":41,"t":"他們正喜得不敢信，並且希奇；耶穌就說：「你們這裏有甚麼吃的沒有？」","notes":[]},{"n":42,"t":"他們便給他一片燒魚。","notes":["有古卷加：和一塊蜜房。"]},{"n":43,"t":"他接過來，在他們面前吃了。","notes":[]},{"n":44,"t":"耶穌對他們說：「這就是我從前與你們同在之時所告訴你們的話說：摩西的律法、先知的書，和詩篇上所記的，凡指著我的話都必須應驗。」","notes":[]},{"n":45,"t":"於是耶穌開他們的心竅，使他們能明白聖經，","notes":[]},{"n":46,"t":"又對他們說：「照經上所寫的，基督必受害，第三日從死裏復活，","notes":[]},{"n":47,"t":"並且人要奉他的名傳悔改、赦罪的道，從耶路撒冷起直傳到萬邦。","notes":[]},{"n":48,"t":"你們就是這些事的見證。","notes":[]},{"n":49,"t":"我要將我父所應許的降在你們身上，你們要在城裏等候，直到你們領受從上頭來的能力。」","notes":[]},{"n":50,"t":"耶穌領他們到伯大尼的對面，就舉手給他們祝福。","notes":[],"heads":["耶穌升天"]},{"n":51,"t":"正祝福的時候，他就離開他們，被帶到天上去了。","notes":[]},{"n":52,"t":"他們就拜他，大大地歡喜，回耶路撒冷去，","notes":[]},{"n":53,"t":"常在殿裏稱頌神。","notes":[]}]}},"JHN":{"1":{"heading":"道成肉身","verses":[{"n":1,"t":"太初有道，道與神同在，道就是神。","notes":[]},{"n":2,"t":"這道太初與神同在。","notes":[]},{"n":3,"t":"萬物是藉著他造的；凡被造的，沒有一樣不是藉著他造的。","notes":[]},{"n":4,"t":"生命在他裏頭，這生命就是人的光。","notes":[]},{"n":5,"t":"光照在黑暗裏，黑暗卻不接受光。","notes":[]},{"n":6,"t":"有一個人，是從神那裏差來的，名叫約翰。","notes":[]},{"n":7,"t":"這人來，為要作見證，就是為光作見證，叫眾人因他可以信。","notes":[]},{"n":8,"t":"他不是那光，乃是要為光作見證。","notes":[]},{"n":9,"t":"那光是真光，照亮一切生在世上的人。","notes":[]},{"n":10,"t":"他在世界，世界也是藉著他造的，世界卻不認識他。","notes":[]},{"n":11,"t":"他到自己的地方來，自己的人倒不接待他。","notes":[]},{"n":12,"t":"凡接待他的，就是信他名的人，他就賜他們權柄作神的兒女。","notes":[]},{"n":13,"t":"這等人不是從血氣生的，不是從情慾生的，也不是從人意生的，乃是從神生的。","notes":[]},{"n":14,"t":"道成了肉身，住在我們中間，充充滿滿地有恩典有真理。我們也見過他的榮光，正是父獨生子的榮光。","notes":[]},{"n":15,"t":"約翰為他作見證，喊著說：「這就是我曾說：『那在我以後來的，反成了在我以前的，因他本來在我以前。』」","notes":[]},{"n":16,"t":"從他豐滿的恩典裏，我們都領受了，而且恩上加恩。","notes":[]},{"n":17,"t":"律法本是藉著摩西傳的；恩典和真理都是由耶穌基督來的。","notes":[]},{"n":18,"t":"從來沒有人看見神，只有在父懷裏的獨生子將他表明出來。","notes":[]},{"n":19,"t":"約翰所作的見證記在下面：猶太人從耶路撒冷差祭司和利未人到約翰那裏，問他說：「你是誰？」","notes":[],"heads":["施洗約翰的見證"]},{"n":20,"t":"他就明說，並不隱瞞，明說：「我不是基督。」","notes":[]},{"n":21,"t":"他們又問他說：「這樣，你是誰呢？是以利亞嗎？」他說：「我不是。」「是那先知嗎？」他回答說：「不是。」","notes":[]},{"n":22,"t":"於是他們說：「你到底是誰，叫我們好回覆差我們來的人。你自己說，你是誰？」","notes":[]},{"n":23,"t":"他說：「我就是那在曠野有人聲喊著說：『修直主的道路』，正如先知以賽亞所說的。」","notes":[]},{"n":24,"t":"那些人是法利賽人差來的；","notes":["或譯：那差來的是法利賽人"]},{"n":25,"t":"他們就問他說：「你既不是基督，不是以利亞，也不是那先知，為甚麼施洗呢？」","notes":[]},{"n":26,"t":"約翰回答說：「我是用水施洗，但有一位站在你們中間，是你們不認識的，","notes":[]},{"n":27,"t":"就是那在我以後來的，我給他解鞋帶也不配。」","notes":[]},{"n":28,"t":"這是在約旦河外伯大尼，約翰施洗的地方作的見證。","notes":["有古卷：伯大巴喇"]},{"n":29,"t":"次日，約翰看見耶穌來到他那裏，就說：「看哪，神的羔羊，除去世人罪孽的！","notes":["或譯：背負"],"heads":["神的羔羊"]},{"n":30,"t":"這就是我曾說：『有一位在我以後來、反成了在我以前的，因他本來在我以前。』","notes":[]},{"n":31,"t":"我先前不認識他，如今我來用水施洗，為要叫他顯明給以色列人。」","notes":[]},{"n":32,"t":"約翰又作見證說：「我曾看見聖靈，彷彿鴿子從天降下，住在他的身上。","notes":[]},{"n":33,"t":"我先前不認識他，只是那差我來用水施洗的、對我說：『你看見聖靈降下來，住在誰的身上，誰就是用聖靈施洗的。』","notes":[]},{"n":34,"t":"我看見了，就證明這是神的兒子。」","notes":[]},{"n":35,"t":"再次日，約翰同兩個門徒站在那裏。","notes":[],"heads":["初次選召門徒"]},{"n":36,"t":"他見耶穌行走，就說：「看哪，這是神的羔羊！」","notes":[]},{"n":37,"t":"兩個門徒聽見他的話，就跟從了耶穌。","notes":[]},{"n":38,"t":"耶穌轉過身來，看見他們跟著，就問他們說：「你們要甚麼？」他們說：「拉比，在哪裏住？」（拉比翻出來就是夫子。）","notes":[]},{"n":39,"t":"耶穌說：「你們來看。」他們就去看他在哪裏住，這一天便與他同住；那時約有申正了。","notes":[]},{"n":40,"t":"聽見約翰的話跟從耶穌的那兩個人，一個是西門‧彼得的兄弟安得烈。","notes":[]},{"n":41,"t":"他先找著自己的哥哥西門，對他說：「我們遇見彌賽亞了。」（彌賽亞翻出來就是基督。）","notes":[]},{"n":42,"t":"於是領他去見耶穌。耶穌看著他，說：「你是約翰的兒子西門，你要稱為磯法。」（磯法翻出來就是彼得。）","notes":["約翰在馬太十六章十七節稱約拿"]},{"n":43,"t":"又次日，耶穌想要往加利利去，遇見腓力，就對他說：「來跟從我吧。」","notes":[],"heads":["呼召腓力和拿但業"]},{"n":44,"t":"這腓力是伯賽大人，和安得烈、彼得同城。","notes":[]},{"n":45,"t":"腓力找著拿但業，對他說：「摩西在律法上所寫的和眾先知所記的那一位，我們遇見了，就是約瑟的兒子拿撒勒人耶穌。」","notes":[]},{"n":46,"t":"拿但業對他說：「拿撒勒還能出甚麼好的嗎？」腓力說：「你來看！」","notes":[]},{"n":47,"t":"耶穌看見拿但業來，就指著他說：「看哪，這是個真以色列人，他心裏是沒有詭詐的。」","notes":[]},{"n":48,"t":"拿但業對耶穌說：「你從哪裏知道我呢？」耶穌回答說：「腓力還沒有招呼你，你在無花果樹底下，我就看見你了。」","notes":[]},{"n":49,"t":"拿但業說：「拉比，你是神的兒子，你是以色列的王！」","notes":[]},{"n":50,"t":"耶穌對他說：「因為我說『在無花果樹底下看見你』，你就信嗎？你將要看見比這更大的事」；","notes":[]},{"n":51,"t":"又說：「我實實在在地告訴你們，你們將要看見天開了，神的使者上去下來在人子身上。」","notes":[]}]},"2":{"heading":"迦拿的婚禮","verses":[{"n":1,"t":"第三日，在加利利的迦拿有娶親的筵席，耶穌的母親在那裏。","notes":[]},{"n":2,"t":"耶穌和他的門徒也被請去赴席。","notes":[]},{"n":3,"t":"酒用盡了，耶穌的母親對他說：「他們沒有酒了。」","notes":[]},{"n":4,"t":"耶穌說：「母親，我與你有甚麼相干？我的時候還沒有到。」","notes":["原文是婦人"]},{"n":5,"t":"他母親對用人說：「他告訴你們甚麼，你們就做甚麼。」","notes":[]},{"n":6,"t":"照猶太人潔淨的規矩，有六口石缸擺在那裏，每口可以盛兩三桶水。","notes":[]},{"n":7,"t":"耶穌對用人說：「把缸倒滿了水。」他們就倒滿了，直到缸口。","notes":[]},{"n":8,"t":"耶穌又說：「現在可以舀出來，送給管筵席的。」他們就送了去。","notes":[]},{"n":9,"t":"管筵席的嘗了那水變的酒，並不知道是哪裏來的，只有舀水的用人知道。管筵席的便叫新郎來，","notes":[]},{"n":10,"t":"對他說：「人都是先擺上好酒，等客喝足了，才擺上次的，你倒把好酒留到如今！」","notes":[]},{"n":11,"t":"這是耶穌所行的頭一件神蹟，是在加利利的迦拿行的，顯出他的榮耀來；他的門徒就信他了。","notes":[]},{"n":12,"t":"這事以後，耶穌與他的母親、弟兄，和門徒都下迦百農去，在那裏住了不多幾日。","notes":[]},{"n":13,"t":"猶太人的逾越節近了，耶穌就上耶路撒冷去。","notes":[],"heads":["潔淨聖殿"]},{"n":14,"t":"看見殿裏有賣牛、羊、鴿子的，並有兌換銀錢的人坐在那裏，","notes":[]},{"n":15,"t":"耶穌就拿繩子做成鞭子，把牛羊都趕出殿去，倒出兌換銀錢之人的銀錢，推翻他們的桌子，","notes":[]},{"n":16,"t":"又對賣鴿子的說：「把這些東西拿去！不要將我父的殿當作買賣的地方。」","notes":[]},{"n":17,"t":"他的門徒就想起經上記著說：「我為你的殿心裏焦急，如同火燒。」","notes":[]},{"n":18,"t":"因此猶太人問他說：「你既做這些事，還顯甚麼神蹟給我們看呢？」","notes":[]},{"n":19,"t":"耶穌回答說：「你們拆毀這殿，我三日內要再建立起來。」","notes":[]},{"n":20,"t":"猶太人便說：「這殿是四十六年才造成的，你三日內就再建立起來嗎？」","notes":[]},{"n":21,"t":"但耶穌這話是以他的身體為殿。","notes":[]},{"n":22,"t":"所以到他從死裏復活以後，門徒就想起他說過這話，便信了聖經和耶穌所說的。","notes":[]},{"n":23,"t":"當耶穌在耶路撒冷過逾越節的時候，有許多人看見他所行的神蹟，就信了他的名。","notes":[],"heads":["耶穌洞悉人心"]},{"n":24,"t":"耶穌卻不將自己交託他們；因為他知道萬人，","notes":[]},{"n":25,"t":"也用不著誰見證人怎樣，因他知道人心裏所存的。","notes":[]}]},"3":{"heading":"耶穌與尼哥德慕","verses":[{"n":1,"t":"有一個法利賽人，名叫尼哥德慕，是猶太人的官。","notes":[]},{"n":2,"t":"這人夜裏來見耶穌，說：「拉比，我們知道你是由神那裏來作師傅的；因為你所行的神蹟，若沒有神同在，無人能行。」","notes":[]},{"n":3,"t":"耶穌回答說：「我實實在在地告訴你，人若不重生，就不能見神的國。」","notes":[]},{"n":4,"t":"尼哥德慕說：「人已經老了，如何能重生呢？豈能再進母腹生出來嗎？」","notes":[]},{"n":5,"t":"耶穌說：「我實實在在地告訴你，人若不是從水和聖靈生的，就不能進神的國。","notes":[]},{"n":6,"t":"從肉身生的就是肉身；從靈生的就是靈。","notes":[]},{"n":7,"t":"我說：『你們必須重生』，你不要以為希奇。","notes":[]},{"n":8,"t":"風隨著意思吹，你聽見風的響聲，卻不曉得從哪裏來，往哪裏去；凡從聖靈生的，也是如此。」","notes":[]},{"n":9,"t":"尼哥德慕問他說：「怎能有這事呢？」","notes":[]},{"n":10,"t":"耶穌回答說：「你是以色列人的先生，還不明白這事嗎？","notes":[]},{"n":11,"t":"我實實在在地告訴你，我們所說的是我們知道的；我們所見證的是我們見過的；你們卻不領受我們的見證。","notes":[]},{"n":12,"t":"我對你們說地上的事，你們尚且不信，若說天上的事，如何能信呢？","notes":[]},{"n":13,"t":"除了從天降下、仍舊在天的人子，沒有人升過天。","notes":[]},{"n":14,"t":"摩西在曠野怎樣舉蛇，人子也必照樣被舉起來，","notes":[]},{"n":15,"t":"叫一切信他的都得永生。","notes":["或譯：叫一切信的人在他裏面得永生"]},{"n":16,"t":"「神愛世人，甚至將他的獨生子賜給他們，叫一切信他的，不致滅亡，反得永生。","notes":[]},{"n":17,"t":"因為神差他的兒子降世，不是要定世人的罪，乃是要叫世人因他得救。","notes":["或譯：審判世人；下同"]},{"n":18,"t":"信他的人，不被定罪；不信的人，罪已經定了，因為他不信神獨生子的名。","notes":[]},{"n":19,"t":"光來到世間，世人因自己的行為是惡的，不愛光，倒愛黑暗，定他們的罪就是在此。","notes":[]},{"n":20,"t":"凡作惡的便恨光，並不來就光，恐怕他的行為受責備。","notes":[]},{"n":21,"t":"但行真理的必來就光，要顯明他所行的是靠神而行。」","notes":[]},{"n":22,"t":"這事以後，耶穌和門徒到了猶太地，在那裏居住，施洗。","notes":[],"heads":["耶穌和施洗約翰"]},{"n":23,"t":"約翰在靠近撒冷的哀嫩也施洗；因為那裏水多，眾人都去受洗。（","notes":[]},{"n":24,"t":"那時約翰還沒有下在監裏。）","notes":[]},{"n":25,"t":"約翰的門徒和一個猶太人辯論潔淨的禮，","notes":[]},{"n":26,"t":"就來見約翰，說：「拉比，從前同你在約旦河外、你所見證的那位，現在施洗，眾人都往他那裏去了。」","notes":[]},{"n":27,"t":"約翰說：「若不是從天上賜的，人就不能得甚麼。","notes":[]},{"n":28,"t":"我曾說：『我不是基督，是奉差遣在他前面的』，你們自己可以給我作見證。","notes":[]},{"n":29,"t":"娶新婦的就是新郎；新郎的朋友站著，聽見新郎的聲音就甚喜樂。故此，我這喜樂滿足了。","notes":[]},{"n":30,"t":"他必興旺，我必衰微。」","notes":[]},{"n":31,"t":"「從天上來的是在萬有之上；從地上來的是屬乎地，他所說的也是屬乎地。從天上來的是在萬有之上。","notes":[],"heads":["從天上來的那一位"]},{"n":32,"t":"他將所見所聞的見證出來，只是沒有人領受他的見證。","notes":[]},{"n":33,"t":"那領受他見證的，就印上印，證明神是真的。","notes":[]},{"n":34,"t":"神所差來的就說神的話，因為神賜聖靈給他是沒有限量的。","notes":[]},{"n":35,"t":"父愛子，已將萬有交在他手裏。","notes":[]},{"n":36,"t":"信子的人有永生；不信子的人得不著永生，神的震怒常在他身上。」","notes":["原文是不得見永生"]}]},"4":{"heading":"耶穌和撒馬利亞婦人","verses":[{"n":1,"t":"主知道法利賽人聽見他收門徒，施洗，比約翰還多，（","notes":[]},{"n":2,"t":"其實不是耶穌親自施洗，乃是他的門徒施洗，）","notes":[]},{"n":3,"t":"他就離了猶太，又往加利利去。","notes":[]},{"n":4,"t":"必須經過撒馬利亞，","notes":[]},{"n":5,"t":"於是到了撒馬利亞的一座城，名叫敘加，靠近雅各給他兒子約瑟的那塊地。","notes":[]},{"n":6,"t":"在那裏有雅各井；耶穌因走路困乏，就坐在井旁。那時約有午正。","notes":[]},{"n":7,"t":"有一個撒馬利亞的婦人來打水。耶穌對她說：「請你給我水喝。」（","notes":[]},{"n":8,"t":"那時門徒進城買食物去了。）","notes":[]},{"n":9,"t":"撒馬利亞的婦人對他說：「你既是猶太人，怎麼向我一個撒馬利亞婦人要水喝呢？」原來猶太人和撒馬利亞人沒有來往。","notes":[]},{"n":10,"t":"耶穌回答說：「你若知道神的恩賜，和對你說『給我水喝』的是誰，你必早求他，他也必早給了你活水。」","notes":[]},{"n":11,"t":"婦人說：「先生，沒有打水的器具，井又深，你從哪裏得活水呢？","notes":[]},{"n":12,"t":"我們的祖宗雅各將這井留給我們，他自己和兒子並牲畜也都喝這井裏的水，難道你比他還大嗎？」","notes":[]},{"n":13,"t":"耶穌回答說：「凡喝這水的還要再渴；","notes":[]},{"n":14,"t":"人若喝我所賜的水就永遠不渴。我所賜的水要在他裏頭成為泉源，直湧到永生。」","notes":[]},{"n":15,"t":"婦人說：「先生，請把這水賜給我，叫我不渴，也不用來這麼遠打水。」","notes":[]},{"n":16,"t":"耶穌說：「你去叫你丈夫也到這裏來。」","notes":[]},{"n":17,"t":"婦人說：「我沒有丈夫。」耶穌說：「你說沒有丈夫是不錯的。","notes":[]},{"n":18,"t":"你已經有五個丈夫，你現在有的並不是你的丈夫。你這話是真的。」","notes":[]},{"n":19,"t":"婦人說：「先生，我看出你是先知。","notes":[]},{"n":20,"t":"我們的祖宗在這山上禮拜，你們倒說，應當禮拜的地方是在耶路撒冷。」","notes":[]},{"n":21,"t":"耶穌說：「婦人，你當信我。時候將到，你們拜父，也不在這山上，也不在耶路撒冷。","notes":[]},{"n":22,"t":"你們所拜的，你們不知道；我們所拜的，我們知道，因為救恩是從猶太人出來的。","notes":[]},{"n":23,"t":"時候將到，如今就是了，那真正拜父的，要用心靈和誠實拜他，因為父要這樣的人拜他。」","notes":[]},{"n":24,"t":"神是個靈，所以拜他的必須用心靈和誠實拜他。","notes":["或無個字"]},{"n":25,"t":"婦人說：「我知道彌賽亞（就是那稱為基督的）要來；他來了，必將一切的事都告訴我們。」","notes":[]},{"n":26,"t":"耶穌說：「這和你說話的就是他！」","notes":[]},{"n":27,"t":"當下門徒回來，就希奇耶穌和一個婦人說話；只是沒有人說：「你是要甚麼？」或說：「你為甚麼和她說話？」","notes":[]},{"n":28,"t":"那婦人就留下水罐子，往城裏去，對眾人說：","notes":[]},{"n":29,"t":"「你們來看！有一個人將我素來所行的一切事都給我說出來了，莫非這就是基督嗎？」","notes":[]},{"n":30,"t":"眾人就出城，往耶穌那裏去。","notes":[]},{"n":31,"t":"這其間，門徒對耶穌說：「拉比，請吃。」","notes":[]},{"n":32,"t":"耶穌說：「我有食物吃，是你們不知道的。」","notes":[]},{"n":33,"t":"門徒就彼此對問說：「莫非有人拿甚麼給他吃嗎？」","notes":[]},{"n":34,"t":"耶穌說：「我的食物就是遵行差我來者的旨意，做成他的工。","notes":[]},{"n":35,"t":"你們豈不說『到收割的時候還有四個月』嗎？我告訴你們，舉目向田觀看，莊稼已經熟了，可以收割了。","notes":["原文是發白"]},{"n":36,"t":"收割的人得工價，積蓄五穀到永生，叫撒種的和收割的一同快樂。","notes":[]},{"n":37,"t":"俗語說：『那人撒種，這人收割』，這話可見是真的。","notes":[]},{"n":38,"t":"我差你們去收你們所沒有勞苦的；別人勞苦，你們享受他們所勞苦的。」","notes":[]},{"n":39,"t":"那城裏有好些撒馬利亞人信了耶穌，因為那婦人作見證說：「他將我素來所行的一切事都給我說出來了。」","notes":[]},{"n":40,"t":"於是撒馬利亞人來見耶穌，求他在他們那裏住下，他便在那裏住了兩天。","notes":[]},{"n":41,"t":"因耶穌的話，信的人就更多了，","notes":[]},{"n":42,"t":"便對婦人說：「現在我們信，不是因為你的話，是我們親自聽見了，知道這真是救世主。」","notes":[]},{"n":43,"t":"過了那兩天，耶穌離了那地方，往加利利去。","notes":[],"heads":["耶穌治好大臣的兒子"]},{"n":44,"t":"因為耶穌自己作過見證說：「先知在本地是沒有人尊敬的。」","notes":[]},{"n":45,"t":"到了加利利，加利利人既然看見他在耶路撒冷過節所行的一切事，就接待他，因為他們也是上去過節。","notes":[]},{"n":46,"t":"耶穌又到了加利利的迦拿，就是他從前變水為酒的地方。有一個大臣，他的兒子在迦百農患病。","notes":[]},{"n":47,"t":"他聽見耶穌從猶太到了加利利，就來見他，求他下去醫治他的兒子，因為他兒子快要死了。","notes":[]},{"n":48,"t":"耶穌就對他說：「若不看見神蹟奇事，你們總是不信。」","notes":[]},{"n":49,"t":"那大臣說：「先生，求你趁著我的孩子還沒有死就下去。」","notes":[]},{"n":50,"t":"耶穌對他說：「回去吧，你的兒子活了！」那人信耶穌所說的話就回去了。","notes":[]},{"n":51,"t":"正下去的時候，他的僕人迎見他，說他的兒子活了。","notes":[]},{"n":52,"t":"他就問甚麼時候見好的。他們說：「昨日未時熱就退了。」","notes":[]},{"n":53,"t":"他便知道這正是耶穌對他說「你兒子活了」的時候；他自己和全家就都信了。","notes":[]},{"n":54,"t":"這是耶穌在加利利行的第二件神蹟，是他從猶太回去以後行的。","notes":[]}]},"5":{"heading":"在畢士大池邊治病","verses":[{"n":1,"t":"這事以後，到了猶太人的一個節期，耶穌就上耶路撒冷去。","notes":[]},{"n":2,"t":"在耶路撒冷，靠近羊門有一個池子，希伯來話叫作畢士大，旁邊有五個廊子；","notes":[]},{"n":3,"t":"裏面躺著瞎眼的、瘸腿的、血氣枯乾的許多病人。","notes":["有古卷加：等候水動；4因為有天使按時下池子攪動那水，水動之後，誰先下去，無論害甚麼病就痊癒了。"]},{"n":5,"t":"在那裏有一個人，病了三十八年。","notes":[]},{"n":6,"t":"耶穌看見他躺著，知道他病了許久，就問他說：「你要痊癒嗎？」","notes":[]},{"n":7,"t":"病人回答說：「先生，水動的時候，沒有人把我放在池子裏；我正去的時候，就有別人比我先下去。」","notes":[]},{"n":8,"t":"耶穌對他說：「起來，拿你的褥子走吧！」","notes":[]},{"n":9,"t":"那人立刻痊癒，就拿起褥子來走了。","notes":[]},{"n":10,"t":"那天是安息日，所以猶太人對那醫好的人說：「今天是安息日，你拿褥子是不可的。」","notes":[]},{"n":11,"t":"他卻回答說：「那使我痊癒的，對我說：『拿你的褥子走吧。』」","notes":[]},{"n":12,"t":"他們問他說：「對你說『拿褥子走』的是甚麼人？」","notes":[]},{"n":13,"t":"那醫好的人不知道是誰；因為那裏的人多，耶穌已經躲開了。","notes":[]},{"n":14,"t":"後來耶穌在殿裏遇見他，對他說：「你已經痊癒了，不要再犯罪，恐怕你遭遇的更加利害。」","notes":[]},{"n":15,"t":"那人就去告訴猶太人，使他痊癒的是耶穌。","notes":[]},{"n":16,"t":"所以猶太人逼迫耶穌，因為他在安息日做了這事。","notes":[]},{"n":17,"t":"耶穌就對他們說：「我父做事直到如今，我也做事。」","notes":[]},{"n":18,"t":"所以猶太人越發想要殺他；因他不但犯了安息日，並且稱神為他的父，將自己和神當作平等。","notes":[]},{"n":19,"t":"耶穌對他們說：「我實實在在地告訴你們，子憑著自己不能做甚麼，惟有看見父所做的，子才能做；父所做的事，子也照樣做。","notes":[],"heads":["子的權柄"]},{"n":20,"t":"父愛子，將自己所做的一切事指給他看，還要將比這更大的事指給他看，叫你們希奇。","notes":[]},{"n":21,"t":"父怎樣叫死人起來，使他們活著，子也照樣隨自己的意思使人活著。","notes":[]},{"n":22,"t":"父不審判甚麼人，乃將審判的事全交與子，","notes":[]},{"n":23,"t":"叫人都尊敬子如同尊敬父一樣。不尊敬子的，就是不尊敬差子來的父。","notes":[]},{"n":24,"t":"我實實在在地告訴你們，那聽我話、又信差我來者的，就有永生；不至於定罪，是已經出死入生了。","notes":[]},{"n":25,"t":"我實實在在地告訴你們，時候將到，現在就是了，死人要聽見神兒子的聲音，聽見的人就要活了。","notes":[]},{"n":26,"t":"因為父怎樣在自己有生命，就賜給他兒子也照樣在自己有生命，","notes":[]},{"n":27,"t":"並且因為他是人子，就賜給他行審判的權柄。","notes":[]},{"n":28,"t":"你們不要把這事看作希奇。時候要到，凡在墳墓裏的，都要聽見他的聲音，就出來：","notes":[]},{"n":29,"t":"行善的，復活得生；作惡的，復活定罪。","notes":[]},{"n":30,"t":"「我憑著自己不能做甚麼，我怎麼聽見就怎麼審判。我的審判也是公平的；因為我不求自己的意思，只求那差我來者的意思。」","notes":[]},{"n":31,"t":"「我若為自己作見證，我的見證就不真。","notes":[],"heads":["為耶穌作證"]},{"n":32,"t":"另有一位給我作見證，我也知道他給我作的見證是真的。","notes":[]},{"n":33,"t":"你們曾差人到約翰那裏，他為真理作過見證。","notes":[]},{"n":34,"t":"其實，我所受的見證不是從人來的；然而，我說這些話，為要叫你們得救。","notes":[]},{"n":35,"t":"約翰是點著的明燈，你們情願暫時喜歡他的光。","notes":[]},{"n":36,"t":"但我有比約翰更大的見證；因為父交給我要我成就的事，就是我所做的事，這便見證我是父所差來的。","notes":[]},{"n":37,"t":"差我來的父也為我作過見證。你們從來沒有聽見他的聲音，也沒有看見他的形像。","notes":[]},{"n":38,"t":"你們並沒有他的道存在心裏；因為他所差來的，你們不信。","notes":[]},{"n":39,"t":"你們查考聖經，因你們以為內中有永生；給我作見證的就是這經。","notes":["或譯：應當查考聖經"]},{"n":40,"t":"然而，你們不肯到我這裏來得生命。","notes":[]},{"n":41,"t":"「我不受從人來的榮耀。","notes":[]},{"n":42,"t":"但我知道，你們心裏沒有神的愛。","notes":[]},{"n":43,"t":"我奉我父的名來，你們並不接待我；若有別人奉自己的名來，你們倒要接待他。","notes":[]},{"n":44,"t":"你們互相受榮耀，卻不求從獨一之神來的榮耀，怎能信我呢？","notes":[]},{"n":45,"t":"不要想我在父面前要告你們；有一位告你們的，就是你們所仰賴的摩西。","notes":[]},{"n":46,"t":"你們如果信摩西，也必信我，因為他書上有指著我寫的話。","notes":[]},{"n":47,"t":"你們若不信他的書，怎能信我的話呢？」","notes":[]}]},"6":{"heading":"耶穌給五千人吃飽","verses":[{"n":1,"t":"這事以後，耶穌渡過加利利海，就是提比哩亞海。","notes":[]},{"n":2,"t":"有許多人因為看見他在病人身上所行的神蹟，就跟隨他。","notes":[]},{"n":3,"t":"耶穌上了山，和門徒一同坐在那裏。","notes":[]},{"n":4,"t":"那時猶太人的逾越節近了。","notes":[]},{"n":5,"t":"耶穌舉目看見許多人來，就對腓力說：「我們從哪裏買餅叫這些人吃呢？」（","notes":[]},{"n":6,"t":"他說這話是要試驗腓力；他自己原知道要怎樣行。）","notes":[]},{"n":7,"t":"腓力回答說：「就是二十兩銀子的餅，叫他們各人吃一點也是不夠的。」","notes":[]},{"n":8,"t":"有一個門徒，就是西門‧彼得的兄弟安得烈，對耶穌說：","notes":[]},{"n":9,"t":"「在這裏有一個孩童，帶著五個大麥餅、兩條魚，只是分給這許多人還算甚麼呢？」","notes":[]},{"n":10,"t":"耶穌說：「你們叫眾人坐下。」原來那地方的草多，眾人就坐下，數目約有五千。","notes":[]},{"n":11,"t":"耶穌拿起餅來，祝謝了，就分給那坐著的人；分魚也是這樣，都隨著他們所要的。","notes":[]},{"n":12,"t":"他們吃飽了，耶穌對門徒說：「把剩下的零碎收拾起來，免得有糟蹋的。」","notes":[]},{"n":13,"t":"他們便將那五個大麥餅的零碎，就是眾人吃了剩下的，收拾起來，裝滿了十二個籃子。","notes":[]},{"n":14,"t":"眾人看見耶穌所行的神蹟，就說：「這真是那要到世間來的先知！」","notes":[]},{"n":15,"t":"耶穌既知道眾人要來強逼他作王，就獨自又退到山上去了。","notes":[]},{"n":16,"t":"到了晚上，他的門徒下海邊去，","notes":[],"heads":["耶穌在海面上行走"]},{"n":17,"t":"上了船，要過海往迦百農去。天已經黑了，耶穌還沒有來到他們那裏。","notes":[]},{"n":18,"t":"忽然狂風大作，海就翻騰起來。","notes":[]},{"n":19,"t":"門徒搖櫓，約行了十里多路，看見耶穌在海面上走，漸漸近了船，他們就害怕。","notes":[]},{"n":20,"t":"耶穌對他們說：「是我，不要怕！」","notes":[]},{"n":21,"t":"門徒就喜歡接他上船，船立時到了他們所要去的地方。","notes":[]},{"n":22,"t":"第二日，站在海那邊的眾人知道那裏沒有別的船，只有一隻小船，又知道耶穌沒有同他的門徒上船，乃是門徒自己去的。","notes":[],"heads":["耶穌是生命的糧"]},{"n":23,"t":"然而，有幾隻小船從提比哩亞來，靠近主祝謝後分餅給人吃的地方。","notes":[]},{"n":24,"t":"眾人見耶穌和門徒都不在那裏，就上了船，往迦百農去找耶穌。","notes":[]},{"n":25,"t":"既在海那邊找著了，就對他說：「拉比，是幾時到這裏來的？」","notes":[]},{"n":26,"t":"耶穌回答說：「我實實在在地告訴你們，你們找我，並不是因見了神蹟，乃是因吃餅得飽。","notes":[]},{"n":27,"t":"不要為那必壞的食物勞力，要為那存到永生的食物勞力，就是人子要賜給你們的，因為人子是父神所印證的。」","notes":[]},{"n":28,"t":"眾人問他說：「我們當行甚麼才算做神的工呢？」","notes":[]},{"n":29,"t":"耶穌回答說：「信神所差來的，這就是做神的工。」","notes":[]},{"n":30,"t":"他們又說：「你行甚麼神蹟，叫我們看見就信你；你到底做甚麼事呢？","notes":[]},{"n":31,"t":"我們的祖宗在曠野吃過嗎哪，如經上寫著說：『他從天上賜下糧來給他們吃。』」","notes":[]},{"n":32,"t":"耶穌說：「我實實在在地告訴你們，那從天上來的糧不是摩西賜給你們的，乃是我父將天上來的真糧賜給你們。","notes":[]},{"n":33,"t":"因為神的糧就是那從天上降下來、賜生命給世界的。」","notes":[]},{"n":34,"t":"他們說：「主啊，常將這糧賜給我們！」","notes":[]},{"n":35,"t":"耶穌說：「我就是生命的糧。到我這裏來的，必定不餓；信我的，永遠不渴。","notes":[]},{"n":36,"t":"只是我對你們說過，你們已經看見我，還是不信。","notes":[]},{"n":37,"t":"凡父所賜給我的人必到我這裏來；到我這裏來的，我總不丟棄他。","notes":[]},{"n":38,"t":"因為我從天上降下來，不是要按自己的意思行，乃是要按那差我來者的意思行。","notes":[]},{"n":39,"t":"差我來者的意思就是：他所賜給我的，叫我一個也不失落，在末日卻叫他復活。","notes":[]},{"n":40,"t":"因為我父的意思是叫一切見子而信的人得永生，並且在末日我要叫他復活。」","notes":[]},{"n":41,"t":"猶太人因為耶穌說「我是從天上降下來的糧」，就私下議論他，","notes":[]},{"n":42,"t":"說：「這不是約瑟的兒子耶穌嗎？他的父母我們豈不認得嗎？他如今怎麼說『我是從天上降下來的』呢？」","notes":[]},{"n":43,"t":"耶穌回答說：「你們不要大家議論。","notes":[]},{"n":44,"t":"若不是差我來的父吸引人，就沒有能到我這裏來的；到我這裏來的，在末日我要叫他復活。","notes":[]},{"n":45,"t":"在先知書上寫著說：『他們都要蒙神的教訓。』凡聽見父之教訓又學習的，就到我這裏來。","notes":[]},{"n":46,"t":"這不是說有人看見過父，惟獨從神來的，他看見過父。","notes":[]},{"n":47,"t":"我實實在在地告訴你們，信的人有永生。","notes":[]},{"n":48,"t":"我就是生命的糧。","notes":[]},{"n":49,"t":"你們的祖宗在曠野吃過嗎哪，還是死了。","notes":[]},{"n":50,"t":"這是從天上降下來的糧，叫人吃了就不死。","notes":[]},{"n":51,"t":"我是從天上降下來生命的糧；人若吃這糧，就必永遠活著。我所要賜的糧就是我的肉，為世人之生命所賜的。」","notes":[]},{"n":52,"t":"因此，猶太人彼此爭論說：「這個人怎能把他的肉給我們吃呢？」","notes":[]},{"n":53,"t":"耶穌說：「我實實在在地告訴你們，你們若不吃人子的肉，不喝人子的血，就沒有生命在你們裏面。","notes":[]},{"n":54,"t":"吃我肉、喝我血的人就有永生，在末日我要叫他復活。","notes":[]},{"n":55,"t":"我的肉真是可吃的，我的血真是可喝的。","notes":[]},{"n":56,"t":"吃我肉、喝我血的人常在我裏面，我也常在他裏面。","notes":[]},{"n":57,"t":"永活的父怎樣差我來，我又因父活著；照樣，吃我肉的人也要因我活著。","notes":[]},{"n":58,"t":"這就是從天上降下來的糧。吃這糧的人就永遠活著，不像你們的祖宗吃過嗎哪還是死了。」","notes":[]},{"n":59,"t":"這些話是耶穌在迦百農會堂裏教訓人說的。","notes":[]},{"n":60,"t":"他的門徒中有好些人聽見了，就說：「這話甚難，誰能聽呢？」","notes":[],"heads":["永生的話語"]},{"n":61,"t":"耶穌心裏知道門徒為這話議論，就對他們說：「這話是叫你們厭棄嗎？","notes":["原文是跌倒"]},{"n":62,"t":"倘或你們看見人子升到他原來所在之處，怎麼樣呢？","notes":[]},{"n":63,"t":"叫人活著的乃是靈，肉體是無益的。我對你們所說的話就是靈，就是生命。","notes":[]},{"n":64,"t":"只是你們中間有不信的人。」耶穌從起頭就知道誰不信他，誰要賣他。","notes":[]},{"n":65,"t":"耶穌又說：「所以我對你們說過，若不是蒙我父的恩賜，沒有人能到我這裏來。」","notes":[]},{"n":66,"t":"從此，他門徒中多有退去的，不再和他同行。","notes":[]},{"n":67,"t":"耶穌就對那十二個門徒說：「你們也要去嗎？」","notes":[]},{"n":68,"t":"西門‧彼得回答說：「主啊，你有永生之道，我們還歸從誰呢？","notes":[]},{"n":69,"t":"我們已經信了，又知道你是神的聖者。」","notes":[]},{"n":70,"t":"耶穌說：「我不是揀選了你們十二個門徒嗎？但你們中間有一個是魔鬼。」","notes":[]},{"n":71,"t":"耶穌這話是指著加略人西門的兒子猶大說的；他本是十二個門徒裏的一個，後來要賣耶穌的。","notes":[]}]},"7":{"heading":"耶穌的兄弟不信","verses":[{"n":1,"t":"這事以後，耶穌在加利利遊行，不願在猶太遊行，因為猶太人想要殺他。","notes":[]},{"n":2,"t":"當時猶太人的住棚節近了。","notes":[]},{"n":3,"t":"耶穌的弟兄就對他說：「你離開這裏上猶太去吧，叫你的門徒也看見你所行的事。","notes":[]},{"n":4,"t":"人要顯揚名聲，沒有在暗處行事的；你如果行這些事，就當將自己顯明給世人看。」","notes":[]},{"n":5,"t":"因為連他的弟兄說這話，是因為不信他。","notes":[]},{"n":6,"t":"耶穌就對他們說：「我的時候還沒有到；你們的時候常是方便的。","notes":[]},{"n":7,"t":"世人不能恨你們，卻是恨我，因為我指證他們所做的事是惡的。","notes":[]},{"n":8,"t":"你們上去過節吧，我現在不上去過這節，因為我的時候還沒有滿。」","notes":[]},{"n":9,"t":"耶穌說了這話，仍舊住在加利利。","notes":[]},{"n":10,"t":"但他弟兄上去以後，他也上去過節，不是明去，似乎是暗去的。","notes":[],"heads":["耶穌過住棚節"]},{"n":11,"t":"正在節期，猶太人尋找耶穌，說：「他在哪裏？」","notes":[]},{"n":12,"t":"眾人為他紛紛議論，有的說：「他是好人。」有的說：「不然，他是迷惑眾人的。」","notes":[]},{"n":13,"t":"只是沒有人明明地講論他，因為怕猶太人。","notes":[]},{"n":14,"t":"到了節期，耶穌上殿裏去教訓人。","notes":[]},{"n":15,"t":"猶太人就希奇，說：「這個人沒有學過，怎麼明白書呢？」","notes":[]},{"n":16,"t":"耶穌說：「我的教訓不是我自己的，乃是那差我來者的。","notes":[]},{"n":17,"t":"人若立志遵著他的旨意行，就必曉得這教訓或是出於神，或是我憑著自己說的。","notes":[]},{"n":18,"t":"人憑著自己說，是求自己的榮耀；惟有求那差他來者的榮耀，這人是真的，在他心裏沒有不義。","notes":[]},{"n":19,"t":"摩西豈不是傳律法給你們嗎？你們卻沒有一個人守律法。為甚麼想要殺我呢？」","notes":[]},{"n":20,"t":"眾人回答說：「你是被鬼附著了！誰想要殺你？」","notes":[]},{"n":21,"t":"耶穌說：「我做了一件事，你們都以為希奇。","notes":[]},{"n":22,"t":"摩西傳割禮給你們（其實不是從摩西起的，乃是從祖先起的），因此你們也在安息日給人行割禮。","notes":[]},{"n":23,"t":"人若在安息日受割禮，免得違背摩西的律法，我在安息日叫一個人全然好了，你們就向我生氣嗎？","notes":[]},{"n":24,"t":"不可按外貌斷定是非，總要按公平斷定是非。」","notes":[]},{"n":25,"t":"耶路撒冷人中有的說：「這不是他們想要殺的人嗎？","notes":[],"heads":["這是基督嗎？"]},{"n":26,"t":"你看他還明明地講道，他們也不向他說甚麼，難道官長真知道這是基督嗎？","notes":[]},{"n":27,"t":"然而，我們知道這個人從哪裏來；只是基督來的時候，沒有人知道他從哪裏來。」","notes":[]},{"n":28,"t":"那時，耶穌在殿裏教訓人，大聲說：「你們也知道我，也知道我從哪裏來；我來並不是由於自己。但那差我來的是真的。你們不認識他，","notes":[]},{"n":29,"t":"我卻認識他；因為我是從他來的，他也是差了我來。」","notes":[]},{"n":30,"t":"他們就想要捉拿耶穌；只是沒有人下手，因為他的時候還沒有到。","notes":[]},{"n":31,"t":"但眾人中間有好些信他的，說：「基督來的時候，他所行的神蹟豈能比這人所行的更多嗎？」","notes":[]},{"n":32,"t":"法利賽人聽見眾人為耶穌這樣紛紛議論，祭司長和法利賽人就打發差役去捉拿他。","notes":[],"heads":["差役捉拿耶穌"]},{"n":33,"t":"於是耶穌說：「我還有不多的時候和你們同在，以後就回到差我來的那裏去。","notes":[]},{"n":34,"t":"你們要找我，卻找不著；我所在的地方你們不能到。」","notes":[]},{"n":35,"t":"猶太人就彼此對問說：「這人要往哪裏去，叫我們找不著呢？難道他要往散住希臘中的猶太人那裏去教訓希臘人嗎？","notes":[]},{"n":36,"t":"他說：『你們要找我，卻找不著；我所在的地方，你們不能到』，這話是甚麼意思呢？」","notes":[]},{"n":37,"t":"節期的末日，就是最大之日，耶穌站著高聲說：「人若渴了，可以到我這裏來喝。","notes":[],"heads":["活水的江河"]},{"n":38,"t":"信我的人就如經上所說：『從他腹中要流出活水的江河來。』」","notes":[]},{"n":39,"t":"耶穌這話是指著信他之人要受聖靈說的。那時還沒有賜下聖靈來，因為耶穌尚未得著榮耀。","notes":[]},{"n":40,"t":"眾人聽見這話，有的說：「這真是那先知。」","notes":[],"heads":["群眾因耶穌而紛爭"]},{"n":41,"t":"有的說：「這是基督。」但也有的說：「基督豈是從加利利出來的嗎？","notes":[]},{"n":42,"t":"經上豈不是說『基督是大衛的後裔，從大衛本鄉伯利恆出來的』嗎？」","notes":[]},{"n":43,"t":"於是眾人因著耶穌起了紛爭。","notes":[]},{"n":44,"t":"其中有人要捉拿他，只是無人下手。","notes":[]},{"n":45,"t":"差役回到祭司長和法利賽人那裏。他們對差役說：「你們為甚麼沒有帶他來呢？」","notes":[],"heads":["猶太領袖的不信"]},{"n":46,"t":"差役回答說：「從來沒有像他這樣說話的！」","notes":[]},{"n":47,"t":"法利賽人說：「你們也受了迷惑嗎？","notes":[]},{"n":48,"t":"官長或是法利賽人豈有信他的呢？","notes":[]},{"n":49,"t":"但這些不明白律法的百姓是被咒詛的！」","notes":[]},{"n":50,"t":"內中有尼哥德慕，就是從前去見耶穌的，對他們說：","notes":[]},{"n":51,"t":"「不先聽本人的口供，不知道他所做的事，難道我們的律法還定他的罪嗎？」","notes":[]},{"n":52,"t":"他們回答說：「你也是出於加利利嗎？你且去查考，就可知道加利利沒有出過先知。」","notes":[]}]},"8":{"heading":"行淫時被捉的女人","verses":[{"n":1,"t":"於是各人都回家去了；耶穌卻往橄欖山去，","notes":[]},{"n":2,"t":"清早又回到殿裏。眾百姓都到他那裏去，他就坐下，教訓他們。","notes":[]},{"n":3,"t":"文士和法利賽人帶著一個行淫時被拿的婦人來，叫她站在當中，","notes":[]},{"n":4,"t":"就對耶穌說：「夫子，這婦人是正行淫之時被拿的。","notes":[]},{"n":5,"t":"摩西在律法上吩咐我們把這樣的婦人用石頭打死。你說該把她怎麼樣呢？」","notes":[]},{"n":6,"t":"他們說這話，乃試探耶穌，要得著告他的把柄。耶穌卻彎著腰，用指頭在地上畫字。","notes":[]},{"n":7,"t":"他們還是不住地問他，耶穌就直起腰來，對他們說：「你們中間誰是沒有罪的，誰就可以先拿石頭打她。」","notes":[]},{"n":8,"t":"於是又彎著腰，用指頭在地上畫字。","notes":[]},{"n":9,"t":"他們聽見這話，就從老到少，一個一個地都出去了，只剩下耶穌一人，還有那婦人仍然站在當中。","notes":[]},{"n":10,"t":"耶穌就直起腰來，對她說：「婦人，那些人在哪裏呢？沒有人定你的罪嗎？」","notes":[]},{"n":11,"t":"她說：「主啊，沒有。」耶穌說：「我也不定你的罪。去吧，從此不要再犯罪了！」","notes":[]},{"n":12,"t":"耶穌又對眾人說：「我是世界的光。跟從我的，就不在黑暗裏走，必要得著生命的光。」","notes":[],"heads":["耶穌是世界的光"]},{"n":13,"t":"法利賽人對他說：「你是為自己作見證，你的見證不真。」","notes":[]},{"n":14,"t":"耶穌說：「我雖然為自己作見證，我的見證還是真的；因我知道我從哪裏來，往哪裏去；你們卻不知道我從哪裏來，往哪裏去。","notes":[]},{"n":15,"t":"你們是以外貌判斷人，我卻不判斷人。","notes":["原文是憑肉身"]},{"n":16,"t":"就是判斷人，我的判斷也是真的；因為不是我獨自在這裏，還有差我來的父與我同在。","notes":[]},{"n":17,"t":"你們的律法上也記著說：『兩個人的見證是真的。』","notes":[]},{"n":18,"t":"我是為自己作見證，還有差我來的父也是為我作見證。」","notes":[]},{"n":19,"t":"他們就問他說：「你的父在哪裏？」耶穌回答說：「你們不認識我，也不認識我的父；若是認識我，也就認識我的父。」","notes":[]},{"n":20,"t":"這些話是耶穌在殿裏的庫房、教訓人時所說的，也沒有人拿他，因為他的時候還沒有到。","notes":[]},{"n":21,"t":"耶穌又對他們說：「我要去了，你們要找我，並且你們要死在罪中。我所去的地方，你們不能到。」","notes":[],"heads":["我所去的地方你們不能到"]},{"n":22,"t":"猶太人說：「他說『我所去的地方，你們不能到』，難道他要自盡嗎？」","notes":[]},{"n":23,"t":"耶穌對他們說：「你們是從下頭來的，我是從上頭來的；你們是屬這世界的，我不是屬這世界的。","notes":[]},{"n":24,"t":"所以我對你們說，你們要死在罪中。你們若不信我是基督，必要死在罪中。」","notes":[]},{"n":25,"t":"他們就問他說：「你是誰？」耶穌對他們說：「就是我從起初所告訴你們的。","notes":[]},{"n":26,"t":"我有許多事講論你們，判斷你們；但那差我來的是真的，我在他那裏所聽見的，我就傳給世人。」","notes":[]},{"n":27,"t":"他們不明白耶穌是指著父說的。","notes":[]},{"n":28,"t":"所以耶穌說：「你們舉起人子以後，必知道我是基督，並且知道我沒有一件事是憑著自己做的。我說這些話乃是照著父所教訓我的。","notes":[]},{"n":29,"t":"那差我來的是與我同在；他沒有撇下我獨自在這裏，因為我常做他所喜悅的事。」","notes":[]},{"n":30,"t":"耶穌說這話的時候，就有許多人信他。","notes":[]},{"n":31,"t":"耶穌對信他的猶太人說：「你們若常常遵守我的道，就真是我的門徒；","notes":[],"heads":["真理必使你們得自由"]},{"n":32,"t":"你們必曉得真理，真理必叫你們得以自由。」","notes":[]},{"n":33,"t":"他們回答說：「我們是亞伯拉罕的後裔，從來沒有作過誰的奴僕。你怎麼說『你們必得以自由』呢？」","notes":[]},{"n":34,"t":"耶穌回答說：「我實實在在地告訴你們，所有犯罪的就是罪的奴僕。","notes":[]},{"n":35,"t":"奴僕不能永遠住在家裏；兒子是永遠住在家裏。","notes":[]},{"n":36,"t":"所以天父的兒子若叫你們自由，你們就真自由了。","notes":[]},{"n":37,"t":"我知道你們是亞伯拉罕的子孫，你們卻想要殺我，因為你們心裏容不下我的道。","notes":[]},{"n":38,"t":"我所說的是在我父那裏看見的；你們所行的是在你們的父那裏聽見的。」","notes":[]},{"n":39,"t":"他們說：「我們的父就是亞伯拉罕。」耶穌說：「你們若是亞伯拉罕的兒子，就必行亞伯拉罕所行的事。","notes":[],"heads":["你們的父是魔鬼"]},{"n":40,"t":"我將在神那裏所聽見的真理告訴了你們，現在你們卻想要殺我，這不是亞伯拉罕所行的事。","notes":[]},{"n":41,"t":"你們是行你們父所行的事。」他們說：「我們不是從淫亂生的；我們只有一位父，就是神。」","notes":[]},{"n":42,"t":"耶穌說：「倘若神是你們的父，你們就必愛我；因為我本是出於神，也是從神而來，並不是由著自己來，乃是他差我來。","notes":[]},{"n":43,"t":"你們為甚麼不明白我的話呢？無非是因你們不能聽我的道。","notes":[]},{"n":44,"t":"你們是出於你們的父魔鬼，你們父的私慾你們偏要行。他從起初是殺人的，不守真理，因他心裏沒有真理。他說謊是出於自己；因他本來是說謊的，也是說謊之人的父。","notes":[]},{"n":45,"t":"我將真理告訴你們，你們就因此不信我。","notes":[]},{"n":46,"t":"你們中間誰能指證我有罪呢？我既然將真理告訴你們，為甚麼不信我呢？","notes":[]},{"n":47,"t":"出於神的，必聽神的話；你們不聽，因為你們不是出於神。」","notes":[]},{"n":48,"t":"猶太人回答說：「我們說你是撒馬利亞人，並且是鬼附著的，這話豈不正對嗎？」","notes":[],"heads":["還沒有亞伯拉罕就有了我"]},{"n":49,"t":"耶穌說：「我不是鬼附著的；我尊敬我的父，你們倒輕慢我。","notes":[]},{"n":50,"t":"我不求自己的榮耀，有一位為我求榮耀、定是非的。","notes":[]},{"n":51,"t":"我實實在在地告訴你們，人若遵守我的道，就永遠不見死。」","notes":[]},{"n":52,"t":"猶太人對他說：「現在我們知道你是鬼附著的。亞伯拉罕死了，眾先知也死了，你還說：『人若遵守我的道，就永遠不嘗死味。』","notes":[]},{"n":53,"t":"難道你比我們的祖宗亞伯拉罕還大嗎？他死了，眾先知也死了，你將自己當作甚麼人呢？」","notes":[]},{"n":54,"t":"耶穌回答說：「我若榮耀自己，我的榮耀就算不得甚麼；榮耀我的乃是我的父，就是你們所說是你們的神。","notes":[]},{"n":55,"t":"你們未曾認識他；我卻認識他。我若說不認識他，我就是說謊的，像你們一樣；但我認識他，也遵守他的道。","notes":[]},{"n":56,"t":"你們的祖宗亞伯拉罕歡歡喜喜地仰望我的日子，既看見了就快樂。」","notes":[]},{"n":57,"t":"猶太人說：「你還沒有五十歲，豈見過亞伯拉罕呢？」","notes":[]},{"n":58,"t":"耶穌說：「我實實在在地告訴你們，還沒有亞伯拉罕就有了我。」","notes":[]},{"n":59,"t":"於是他們拿石頭要打他；耶穌卻躲藏，從殿裏出去了。","notes":[]}]},"9":{"heading":"治好生來瞎眼的","verses":[{"n":1,"t":"耶穌過去的時候，看見一個人生來是瞎眼的。","notes":[]},{"n":2,"t":"門徒問耶穌說：「拉比，這人生來是瞎眼的，是誰犯了罪？是這人呢？是他父母呢？」","notes":[]},{"n":3,"t":"耶穌回答說：「也不是這人犯了罪，也不是他父母犯了罪，是要在他身上顯出神的作為來。","notes":[]},{"n":4,"t":"趁著白日，我們必須做那差我來者的工；黑夜將到，就沒有人能做工了。","notes":[]},{"n":5,"t":"我在世上的時候，是世上的光。」","notes":[]},{"n":6,"t":"耶穌說了這話，就吐唾沫在地上，用唾沫和泥抹在瞎子的眼睛上，","notes":[]},{"n":7,"t":"對他說：「你往西羅亞池子裏去洗。」（西羅亞翻出來就是「奉差遣」。） 他去一洗，回頭就看見了。","notes":[]},{"n":8,"t":"他的鄰舍和那素常見他是討飯的，就說：「這不是那從前坐著討飯的人嗎？」","notes":[]},{"n":9,"t":"有人說：「是他」；又有人說：「不是，卻是像他。」他自己說：「是我。」","notes":[]},{"n":10,"t":"他們對他說：「你的眼睛是怎麼開的呢？」","notes":[]},{"n":11,"t":"他回答說：「有一個人，名叫耶穌，他和泥抹我的眼睛，對我說：『你往西羅亞池子去洗。』我去一洗，就看見了。」","notes":[]},{"n":12,"t":"他們說：「那個人在哪裏？」他說：「我不知道。」","notes":[]},{"n":13,"t":"他們把從前瞎眼的人帶到法利賽人那裏。","notes":[],"heads":["法利賽人盤問醫治的事"]},{"n":14,"t":"耶穌和泥開他眼睛的日子是安息日。","notes":[]},{"n":15,"t":"法利賽人也問他是怎麼得看見的。瞎子對他們說：「他把泥抹在我的眼睛上，我去一洗，就看見了。」","notes":[]},{"n":16,"t":"法利賽人中有的說：「這個人不是從神來的，因為他不守安息日。」又有人說：「一個罪人怎能行這樣的神蹟呢？」他們就起了紛爭。","notes":[]},{"n":17,"t":"他們又對瞎子說：「他既然開了你的眼睛，你說他是怎樣的人呢？」他說：「是個先知。」","notes":[]},{"n":18,"t":"猶太人不信他從前是瞎眼，後來能看見的，等到叫了他的父母來，","notes":[]},{"n":19,"t":"問他們說：「這是你們的兒子嗎？你們說他生來是瞎眼的，如今怎麼能看見了呢？」","notes":[]},{"n":20,"t":"他父母回答說：「他是我們的兒子，生來就瞎眼，這是我們知道的。","notes":[]},{"n":21,"t":"至於他如今怎麼能看見，我們卻不知道；是誰開了他的眼睛，我們也不知道。他已經成了人，你們問他吧，他自己必能說。」","notes":[]},{"n":22,"t":"他父母說這話，是怕猶太人；因為猶太人已經商議定了，若有認耶穌是基督的，要把他趕出會堂。","notes":[]},{"n":23,"t":"因此他父母說：「他已經成了人，你們問他吧。」","notes":[]},{"n":24,"t":"所以法利賽人第二次叫了那從前瞎眼的人來，對他說：「你該將榮耀歸給神，我們知道這人是個罪人。」","notes":[]},{"n":25,"t":"他說：「他是個罪人不是，我不知道；有一件事我知道，從前我是眼瞎的，如今能看見了。」","notes":[]},{"n":26,"t":"他們就問他說：「他向你做甚麼？是怎麼開了你的眼睛呢？」","notes":[]},{"n":27,"t":"他回答說：「我方才告訴你們，你們不聽，為甚麼又要聽呢？莫非你們也要作他的門徒嗎？」","notes":[]},{"n":28,"t":"他們就罵他說：「你是他的門徒；我們是摩西的門徒。","notes":[]},{"n":29,"t":"神對摩西說話是我們知道的；只是這個人，我們不知道他從哪裏來！」","notes":[]},{"n":30,"t":"那人回答說：「他開了我的眼睛，你們竟不知道他從哪裏來，這真是奇怪！","notes":[]},{"n":31,"t":"我們知道神不聽罪人，惟有敬奉神、遵行他旨意的，神才聽他。","notes":[]},{"n":32,"t":"從創世以來，未曾聽見有人把生來是瞎子的眼睛開了。","notes":[]},{"n":33,"t":"這人若不是從神來的，甚麼也不能做。」","notes":[]},{"n":34,"t":"他們回答說：「你全然生在罪孽中，還要教訓我們嗎？」於是把他趕出去了。","notes":[]},{"n":35,"t":"耶穌聽說他們把他趕出去，後來遇見他，就說：「你信神的兒子嗎？」","notes":[],"heads":["靈性的盲目"]},{"n":36,"t":"他回答說：「主啊，誰是神的兒子，叫我信他呢？」","notes":[]},{"n":37,"t":"耶穌說：「你已經看見他，現在和你說話的就是他。」","notes":[]},{"n":38,"t":"他說：「主啊，我信！」就拜耶穌。","notes":[]},{"n":39,"t":"耶穌說：「我為審判到這世上來，叫不能看見的，可以看見；能看見的，反瞎了眼。」","notes":[]},{"n":40,"t":"同他在那裏的法利賽人聽見這話，就說：「難道我們也瞎了眼嗎？」","notes":[]},{"n":41,"t":"耶穌對他們說：「你們若瞎了眼，就沒有罪了；但如今你們說『我們能看見』，所以你們的罪還在。」","notes":[]}]},"10":{"heading":"羊圈的比喻","verses":[{"n":1,"t":"「我實實在在地告訴你們，人進羊圈，不從門進去，倒從別處爬進去，那人就是賊，就是強盜。","notes":[]},{"n":2,"t":"從門進去的，才是羊的牧人。","notes":[]},{"n":3,"t":"看門的就給他開門；羊也聽他的聲音。他按著名叫自己的羊，把羊領出來。","notes":[]},{"n":4,"t":"既放出自己的羊來，就在前頭走，羊也跟著他，因為認得他的聲音。","notes":[]},{"n":5,"t":"羊不跟著生人；因為不認得他的聲音， 必要逃跑。」","notes":[]},{"n":6,"t":"耶穌將這比喻告訴他們，但他們不明白所說的是甚麼意思。","notes":[]},{"n":7,"t":"所以，耶穌又對他們說：「我實實在在地告訴你們，我就是羊的門。","notes":[],"heads":["好牧人耶穌"]},{"n":8,"t":"凡在我以先來的都是賊，是強盜；羊卻不聽他們。","notes":[]},{"n":9,"t":"我就是門；凡從我進來的，必然得救，並且出入得草吃。","notes":[]},{"n":10,"t":"盜賊來，無非要偷竊，殺害，毀壞；我來了，是要叫羊得生命，並且得的更豐盛。","notes":["或譯：人"]},{"n":11,"t":"我是好牧人；好牧人為羊捨命。","notes":[]},{"n":12,"t":"若是雇工，不是牧人，羊也不是他自己的，他看見狼來，就撇下羊逃走；狼抓住羊，趕散了羊群。","notes":[]},{"n":13,"t":"雇工逃走，因他是雇工，並不顧念羊。","notes":[]},{"n":14,"t":"我是好牧人；我認識我的羊，我的羊也認識我，","notes":[]},{"n":15,"t":"正如父認識我，我也認識父一樣；並且我為羊捨命。","notes":[]},{"n":16,"t":"我另外有羊，不是這圈裏的；我必須領他們來，他們也要聽我的聲音，並且要合成一群，歸一個牧人了。","notes":[]},{"n":17,"t":"我父愛我；因我將命捨去，好再取回來。","notes":[]},{"n":18,"t":"沒有人奪我的命去，是我自己捨的。我有權柄捨了，也有權柄取回來。這是我從我父所受的命令。」","notes":[]},{"n":19,"t":"猶太人為這些話又起了紛爭。","notes":[]},{"n":20,"t":"內中有好些人說：「他是被鬼附著，而且瘋了，為甚麼聽他呢？」","notes":[]},{"n":21,"t":"又有人說：「這不是鬼附之人所說的話。鬼豈能叫瞎子的眼睛開了呢？」","notes":[]},{"n":22,"t":"在耶路撒冷有修殿節，是冬天的時候。","notes":[],"heads":["被猶太人棄絕"]},{"n":23,"t":"耶穌在殿裏所羅門的廊下行走。","notes":[]},{"n":24,"t":"猶太人圍著他，說：「你叫我們猶疑不定到幾時呢？你若是基督，就明明地告訴我們。」","notes":[]},{"n":25,"t":"耶穌回答說：「我已經告訴你們，你們不信。我奉我父之名所行的事可以為我作見證；","notes":[]},{"n":26,"t":"只是你們不信，因為你們不是我的羊。","notes":[]},{"n":27,"t":"我的羊聽我的聲音，我也認識他們，他們也跟著我。","notes":[]},{"n":28,"t":"我又賜給他們永生；他們永不滅亡，誰也不能從我手裏把他們奪去。","notes":[]},{"n":29,"t":"我父把羊賜給我，他比萬有都大，誰也不能從我父手裏把他們奪去。","notes":[]},{"n":30,"t":"我與父原為一。」","notes":[]},{"n":31,"t":"猶太人又拿起石頭來要打他。","notes":[]},{"n":32,"t":"耶穌對他們說：「我從父顯出許多善事給你們看，你們是為哪一件拿石頭打我呢？」","notes":[]},{"n":33,"t":"猶太人回答說：「我們不是為善事拿石頭打你，是為你說僭妄的話；又為你是個人，反將自己當作神。」","notes":[]},{"n":34,"t":"耶穌說：「你們的律法上豈不是寫著『我曾說你們是神』嗎？","notes":[]},{"n":35,"t":"經上的話是不能廢的；若那些承受神道的人尚且稱為神，","notes":[]},{"n":36,"t":"父所分別為聖、又差到世間來的，他自稱是神的兒子，你們還向他說『你說僭妄的話』嗎？","notes":[]},{"n":37,"t":"我若不行我父的事，你們就不必信我；","notes":[]},{"n":38,"t":"我若行了，你們縱然不信我，也當信這些事，叫你們又知道又明白父在我裏面，我也在父裏面。」","notes":[]},{"n":39,"t":"他們又要拿他，他卻逃出他們的手走了。","notes":[]},{"n":40,"t":"耶穌又往約旦河外去，到了約翰起初施洗的地方，就住在那裏。","notes":[]},{"n":41,"t":"有許多人來到他那裏。他們說：「約翰一件神蹟沒有行過，但約翰指著這人所說的一切話都是真的。」","notes":[]},{"n":42,"t":"在那裏，信耶穌的人就多了。","notes":[]}]},"11":{"heading":"拉撒路的死","verses":[{"n":1,"t":"有一個患病的人，名叫拉撒路，住在伯大尼，就是馬利亞和她姊姊馬大的村莊。","notes":[]},{"n":2,"t":"這馬利亞就是那用香膏抹主，又用頭髮擦他腳的；患病的拉撒路是她的兄弟。","notes":[]},{"n":3,"t":"她姊妹兩個就打發人去見耶穌，說：「主啊，你所愛的人病了。」","notes":[]},{"n":4,"t":"耶穌聽見，就說：「這病不至於死，乃是為神的榮耀，叫神的兒子因此得榮耀。」","notes":[]},{"n":5,"t":"耶穌素來愛馬大和她妹子並拉撒路。","notes":[]},{"n":6,"t":"聽見拉撒路病了，就在所居之地仍住了兩天。","notes":[]},{"n":7,"t":"然後對門徒說：「我們再往猶太去吧。」","notes":[]},{"n":8,"t":"門徒說：「拉比，猶太人近來要拿石頭打你，你還往那裏去嗎？」","notes":[]},{"n":9,"t":"耶穌回答說：「白日不是有十二小時嗎？人在白日走路，就不致跌倒，因為看見這世上的光。","notes":[]},{"n":10,"t":"若在黑夜走路，就必跌倒，因為他沒有光。」","notes":[]},{"n":11,"t":"耶穌說了這話，隨後對他們說：「我們的朋友拉撒路睡了，我去叫醒他。」","notes":[]},{"n":12,"t":"門徒說：「主啊，他若睡了，就必好了。」","notes":[]},{"n":13,"t":"耶穌這話是指著他死說的，他們卻以為是說照常睡了。","notes":[]},{"n":14,"t":"耶穌就明明地告訴他們說：「拉撒路死了。","notes":[]},{"n":15,"t":"我沒有在那裏就歡喜，這是為你們的緣故，好叫你們相信。如今我們可以往他那裏去吧。」","notes":[]},{"n":16,"t":"多馬，又稱為低土馬，就對那同作門徒的說：「我們也去和他同死吧。」","notes":[]},{"n":17,"t":"耶穌到了，就知道拉撒路在墳墓裏已經四天了。","notes":[],"heads":["復活在我，生命在我"]},{"n":18,"t":"伯大尼離耶路撒冷不遠，約有六里路。","notes":[]},{"n":19,"t":"有好些猶太人來看馬大和馬利亞，要為她們的兄弟安慰她們。","notes":[]},{"n":20,"t":"馬大聽見耶穌來了，就出去迎接他；馬利亞卻仍然坐在家裏。","notes":[]},{"n":21,"t":"馬大對耶穌說：「主啊，你若早在這裏，我兄弟必不死。","notes":[]},{"n":22,"t":"就是現在，我也知道，你無論向神求甚麼，神也必賜給你。」","notes":[]},{"n":23,"t":"耶穌說：「你兄弟必然復活。」","notes":[]},{"n":24,"t":"馬大說：「我知道在末日復活的時候，他必復活。」","notes":[]},{"n":25,"t":"耶穌對她說：「復活在我，生命也在我。信我的人雖然死了，也必復活；","notes":[]},{"n":26,"t":"凡活著信我的人必永遠不死。你信這話嗎？」","notes":[]},{"n":27,"t":"馬大說：「主啊，是的，我信你是基督，是神的兒子，就是那要臨到世界的。」","notes":[]},{"n":28,"t":"馬大說了這話，就回去暗暗地叫她妹子馬利亞，說：「夫子來了，叫你。」","notes":[],"heads":["耶穌哭了"]},{"n":29,"t":"馬利亞聽見了，就急忙起來，到耶穌那裏去。","notes":[]},{"n":30,"t":"那時，耶穌還沒有進村子，仍在馬大迎接他的地方。","notes":[]},{"n":31,"t":"那些同馬利亞在家裏安慰她的猶太人，見她急忙起來出去，就跟著她，以為她要往墳墓那裏去哭。","notes":[]},{"n":32,"t":"馬利亞到了耶穌那裏，看見他，就俯伏在他腳前，說：「主啊，你若早在這裏，我兄弟必不死。」","notes":[]},{"n":33,"t":"耶穌看見她哭，並看見與她同來的猶太人也哭，就心裏悲歎，又甚憂愁，","notes":[]},{"n":34,"t":"便說：「你們把他安放在哪裏？」他們回答說：「請主來看。」","notes":[]},{"n":35,"t":"耶穌哭了。","notes":[]},{"n":36,"t":"猶太人就說：「你看他愛這人是何等懇切。」","notes":[]},{"n":37,"t":"其中有人說：「他既然開了瞎子的眼睛，豈不能叫這人不死嗎？」","notes":[]},{"n":38,"t":"耶穌又心裏悲歎，來到墳墓前；那墳墓是個洞，有一塊石頭擋著。","notes":[],"heads":["拉撒路復活"]},{"n":39,"t":"耶穌說：「你們把石頭挪開。」那死人的姊姊馬大對他說：「主啊，他現在必是臭了，因為他死了已經四天了。」","notes":[]},{"n":40,"t":"耶穌說：「我不是對你說過，你若信，就必看見神的榮耀嗎？」","notes":[]},{"n":41,"t":"他們就把石頭挪開。耶穌舉目望天，說：「父啊，我感謝你，因為你已經聽我。","notes":[]},{"n":42,"t":"我也知道你常聽我，但我說這話是為周圍站著的眾人，叫他們信是你差了我來。」","notes":[]},{"n":43,"t":"說了這話，就大聲呼叫說：「拉撒路出來！」","notes":[]},{"n":44,"t":"那死人就出來了，手腳裹著布，臉上包著手巾。耶穌對他們說：「解開，叫他走！」","notes":[]},{"n":45,"t":"那些來看馬利亞的猶太人見了耶穌所做的事，就多有信他的；","notes":[],"heads":["殺害耶穌的陰謀"]},{"n":46,"t":"但其中也有去見法利賽人的，將耶穌所做的事告訴他們。","notes":[]},{"n":47,"t":"祭司長和法利賽人聚集公會，說：「這人行好些神蹟，我們怎麼辦呢？","notes":[]},{"n":48,"t":"若這樣由著他，人人都要信他，羅馬人也要來奪我們的地土和我們的百姓。」","notes":[]},{"n":49,"t":"內中有一個人，名叫該亞法，本年作大祭司，對他們說：「你們不知道甚麼。","notes":[]},{"n":50,"t":"獨不想一個人替百姓死，免得通國滅亡，就是你們的益處。」","notes":[]},{"n":51,"t":"他這話不是出於自己，是因他本年作大祭司，所以預言耶穌將要替這一國死；","notes":[]},{"n":52,"t":"也不但替這一國死，並要將神四散的子民都聚集歸一。","notes":[]},{"n":53,"t":"從那日起，他們就商議要殺耶穌。","notes":[]},{"n":54,"t":"所以，耶穌不再顯然行在猶太人中間，就離開那裏往靠近曠野的地方去，到了一座城，名叫以法蓮，就在那裏和門徒同住。","notes":[]},{"n":55,"t":"猶太人的逾越節近了，有許多人從鄉下上耶路撒冷去，要在節前潔淨自己。","notes":[]},{"n":56,"t":"他們就尋找耶穌，站在殿裏彼此說：「你們的意思如何，他不來過節嗎？」","notes":[]},{"n":57,"t":"那時，祭司長和法利賽人早已吩咐說，若有人知道耶穌在哪裏，就要報明，好去拿他。","notes":[]}]},"12":{"heading":"在伯大尼受膏","verses":[{"n":1,"t":"逾越節前六日，耶穌來到伯大尼，就是他叫拉撒路從死裏復活之處。","notes":[]},{"n":2,"t":"有人在那裏給耶穌預備筵席；馬大伺候，拉撒路也在那同耶穌坐席的人中。","notes":[]},{"n":3,"t":"馬利亞就拿著一斤極貴的真哪噠香膏，抹耶穌的腳，又用自己頭髮去擦，屋裏就滿了膏的香氣。","notes":[]},{"n":4,"t":"有一個門徒，就是那將要賣耶穌的加略人猶大，","notes":[]},{"n":5,"t":"說：「這香膏為甚麼不賣三十兩銀子賙濟窮人呢？」","notes":[]},{"n":6,"t":"他說這話，並不是掛念窮人，乃因他是個賊，又帶著錢囊，常取其中所存的。","notes":[]},{"n":7,"t":"耶穌說：「由她吧！她是為我安葬之日存留的。","notes":[]},{"n":8,"t":"因為常有窮人和你們同在，只是你們不常有我。」","notes":[]},{"n":9,"t":"有許多猶太人知道耶穌在那裏，就來了，不但是為耶穌的緣故，也是要看他從死裏所復活的拉撒路。","notes":[],"heads":["殺害拉撒路的陰謀"]},{"n":10,"t":"但祭司長商議連拉撒路也要殺了；","notes":[]},{"n":11,"t":"因有好些猶太人為拉撒路的緣故，回去信了耶穌。","notes":[]},{"n":12,"t":"第二天，有許多上來過節的人聽見耶穌將到耶路撒冷，","notes":[],"heads":["光榮地進耶路撒冷"]},{"n":13,"t":"就拿著棕樹枝出去迎接他，喊著說：和散那！奉主名來的以色列王是應當稱頌的！","notes":[]},{"n":14,"t":"耶穌得了一個驢駒，就騎上，如經上所記的說：","notes":[]},{"n":15,"t":"錫安的民哪，不要懼怕！你的王騎著驢駒來了。","notes":["原文是女子"]},{"n":16,"t":"這些事門徒起先不明白，等到耶穌得了榮耀以後才想起這話是指著他寫的，並且眾人果然向他這樣行了。","notes":[]},{"n":17,"t":"當耶穌呼喚拉撒路，叫他從死復活出墳墓的時候，同耶穌在那裏的眾人就作見證。","notes":[]},{"n":18,"t":"眾人因聽見耶穌行了這神蹟，就去迎接他。","notes":[]},{"n":19,"t":"法利賽人彼此說：「看哪，你們是徒勞無益，世人都隨從他去了。」","notes":[]},{"n":20,"t":"那時，上來過節禮拜的人中，有幾個希臘人。","notes":[],"heads":["希臘人求見耶穌"]},{"n":21,"t":"他們來見加利利、伯賽大的腓力，求他說：「先生，我們願意見耶穌。」","notes":[]},{"n":22,"t":"腓力去告訴安得烈，安得烈同腓力去告訴耶穌。","notes":[]},{"n":23,"t":"耶穌說：「人子得榮耀的時候到了。","notes":[]},{"n":24,"t":"我實實在在地告訴你們，一粒麥子不落在地裏死了，仍舊是一粒，若是死了，就結出許多子粒來。","notes":[]},{"n":25,"t":"愛惜自己生命的，就失喪生命；在這世上恨惡自己生命的，就要保守生命到永生。","notes":[]},{"n":26,"t":"若有人服事我，就當跟從我；我在哪裏，服事我的人也要在那裏；若有人服事我，我父必尊重他。」","notes":[]},{"n":27,"t":"「我現在心裏憂愁，我說甚麼才好呢？父啊，救我脫離這時候；但我原是為這時候來的。","notes":[],"heads":["人子必須被舉起來"]},{"n":28,"t":"父啊，願你榮耀你的名！」當時就有聲音從天上來，說：「我已經榮耀了我的名，還要再榮耀。」","notes":[]},{"n":29,"t":"站在旁邊的眾人聽見，就說：「打雷了。」還有人說：「有天使對他說話。」","notes":[]},{"n":30,"t":"耶穌說：「這聲音不是為我，是為你們來的。","notes":[]},{"n":31,"t":"現在這世界受審判，這世界的王要被趕出去。","notes":[]},{"n":32,"t":"我若從地上被舉起來，就要吸引萬人來歸我。」","notes":[]},{"n":33,"t":"耶穌這話原是指著自己將要怎樣死說的。","notes":[]},{"n":34,"t":"眾人回答說：「我們聽見律法上有話說，基督是永存的，你怎麼說『人子必須被舉起來』呢？這人子是誰呢？」","notes":[]},{"n":35,"t":"耶穌對他們說：「光在你們中間還有不多的時候，應當趁著有光行走，免得黑暗臨到你們；那在黑暗裏行走的，不知道往何處去。","notes":[]},{"n":36,"t":"你們應當趁著有光，信從這光，使你們成為光明之子。」耶穌說了這話，就離開他們隱藏了。","notes":[]},{"n":37,"t":"他雖然在他們面前行了許多神蹟，他們還是不信他。","notes":[]},{"n":38,"t":"這是要應驗先知以賽亞的話，說：主啊，我們所傳的有誰信呢？主的膀臂向誰顯露呢？","notes":[]},{"n":39,"t":"他們所以不能信，因為以賽亞又說：","notes":[]},{"n":40,"t":"主叫他們瞎了眼，硬了心，免得他們眼睛看見，心裏明白，回轉過來，我就醫治他們。","notes":[]},{"n":41,"t":"以賽亞因為看見他的榮耀，就指著他說這話。","notes":[]},{"n":42,"t":"雖然如此，官長中卻有好些信他的，只因法利賽人的緣故，就不承認，恐怕被趕出會堂。","notes":[]},{"n":43,"t":"這是因他們愛人的榮耀過於愛神的榮耀。","notes":[]},{"n":44,"t":"耶穌大聲說：「信我的，不是信我，乃是信那差我來的。","notes":[],"heads":["耶穌的話要審判人"]},{"n":45,"t":"人看見我，就是看見那差我來的。","notes":[]},{"n":46,"t":"我到世上來，乃是光，叫凡信我的，不住在黑暗裏。","notes":[]},{"n":47,"t":"若有人聽見我的話不遵守，我不審判他。我來本不是要審判世界，乃是要拯救世界。","notes":[]},{"n":48,"t":"棄絕我、不領受我話的人，有審判他的－就是我所講的道在末日要審判他。","notes":[]},{"n":49,"t":"因為我沒有憑著自己講，惟有差我來的父已經給我命令，叫我說甚麼，講甚麼。","notes":[]},{"n":50,"t":"我也知道他的命令就是永生。故此，我所講的話正是照著父對我所說的。」","notes":[]}]},"13":{"heading":"耶穌為門徒洗腳","verses":[{"n":1,"t":"逾越節以前，耶穌知道自己離世歸父的時候到了。他既然愛世間屬自己的人，就愛他們到底。","notes":[]},{"n":2,"t":"吃晚飯的時候，魔鬼已將賣耶穌的意思放在西門的兒子加略人猶大心裏。","notes":[]},{"n":3,"t":"耶穌知道父已將萬有交在他手裏，且知道自己是從神出來的，又要歸到神那裏去，","notes":[]},{"n":4,"t":"就離席站起來，脫了衣服，拿一條手巾束腰，","notes":[]},{"n":5,"t":"隨後把水倒在盆裏，就洗門徒的腳，並用自己所束的手巾擦乾。","notes":[]},{"n":6,"t":"挨到西門‧彼得，彼得對他說：「主啊，你洗我的腳嗎？」","notes":[]},{"n":7,"t":"耶穌回答說：「我所做的，你如今不知道，後來必明白。」","notes":[]},{"n":8,"t":"彼得說：「你永不可洗我的腳！」耶穌說：「我若不洗你，你就與我無分了。」","notes":[]},{"n":9,"t":"西門‧彼得說：「主啊，不但我的腳，連手和頭也要洗。」","notes":[]},{"n":10,"t":"耶穌說：「凡洗過澡的人，只要把腳一洗，全身就乾淨了。你們是乾淨的，然而不都是乾淨的。」","notes":[]},{"n":11,"t":"耶穌原知道要賣他的是誰，所以說：「你們不都是乾淨的。」","notes":[]},{"n":12,"t":"耶穌洗完了他們的腳，就穿上衣服，又坐下，對他們說：「我向你們所做的，你們明白嗎？","notes":[]},{"n":13,"t":"你們稱呼我夫子，稱呼我主，你們說的不錯，我本來是。","notes":[]},{"n":14,"t":"我是你們的主，你們的夫子，尚且洗你們的腳，你們也當彼此洗腳。","notes":[]},{"n":15,"t":"我給你們作了榜樣，叫你們照著我向你們所做的去做。","notes":[]},{"n":16,"t":"我實實在在地告訴你們，僕人不能大於主人，差人也不能大於差他的人。","notes":[]},{"n":17,"t":"你們既知道這事，若是去行就有福了。","notes":[]},{"n":18,"t":"我這話不是指著你們眾人說的，我知道我所揀選的是誰。現在要應驗經上的話，說：『同我吃飯的人用腳踢我。』","notes":[]},{"n":19,"t":"如今事情還沒有成就，我要先告訴你們，叫你們到事情成就的時候可以信我是基督。","notes":[]},{"n":20,"t":"我實實在在地告訴你們，有人接待我所差遣的，就是接待我；接待我，就是接待那差遣我的。」","notes":[]},{"n":21,"t":"耶穌說了這話，心裏憂愁，就明說：「我實實在在地告訴你們，你們中間有一個人要賣我了。」","notes":[],"heads":["預言自己將被出賣"]},{"n":22,"t":"門徒彼此對看，猜不透所說的是誰。","notes":[]},{"n":23,"t":"有一個門徒，是耶穌所愛的，側身挨近耶穌的懷裏。","notes":[]},{"n":24,"t":"西門‧彼得點頭對他說：「你告訴我們，主是指著誰說的。」","notes":[]},{"n":25,"t":"那門徒便就勢靠著耶穌的胸膛，問他說：「主啊，是誰呢？」","notes":[]},{"n":26,"t":"耶穌回答說：「我蘸一點餅給誰，就是誰。」耶穌就蘸了一點餅，遞給加略人西門的兒子猶大。","notes":[]},{"n":27,"t":"他吃了以後，撒但就入了他的心。耶穌便對他說：「你所做的，快做吧！」","notes":[]},{"n":28,"t":"同席的人沒有一個知道是為甚麼對他說這話。","notes":[]},{"n":29,"t":"有人因猶大帶著錢囊，以為耶穌是對他說：「你去買我們過節所應用的東西」，或是叫他拿甚麼賙濟窮人。","notes":[]},{"n":30,"t":"猶大受了那點餅，立刻就出去。那時候是夜間了。","notes":[]},{"n":31,"t":"他既出去，耶穌就說：「如今人子得了榮耀，神在人子身上也得了榮耀。","notes":[],"heads":["新的命令"]},{"n":32,"t":"神要因自己榮耀人子，並且要快快地榮耀他。","notes":[]},{"n":33,"t":"小子們，我還有不多的時候與你們同在；後來你們要找我，但我所去的地方你們不能到。這話我曾對猶太人說過，如今也照樣對你們說。","notes":[]},{"n":34,"t":"我賜給你們一條新命令，乃是叫你們彼此相愛；我怎樣愛你們，你們也要怎樣相愛。","notes":[]},{"n":35,"t":"你們若有彼此相愛的心，眾人因此就認出你們是我的門徒了。」","notes":[]},{"n":36,"t":"西門‧彼得問耶穌說：「主往哪裏去？」耶穌回答說：「我所去的地方，你現在不能跟我去，後來卻要跟我去。」","notes":[],"heads":["預言彼得不認主"]},{"n":37,"t":"彼得說：「主啊，我為甚麼現在不能跟你去？我願意為你捨命！」","notes":[]},{"n":38,"t":"耶穌說：「你願意為我捨命嗎？我實實在在地告訴你，雞叫以先，你要三次不認我。」","notes":[]}]},"14":{"heading":"耶穌是道路、真理、生命","verses":[{"n":1,"t":"「你們心裏不要憂愁；你們信神，也當信我。","notes":[]},{"n":2,"t":"在我父的家裏有許多住處；若是沒有，我就早已告訴你們了。我去原是為你們預備地方去。","notes":[]},{"n":3,"t":"我若去為你們預備了地方，就必再來接你們到我那裏去，我在哪裏，叫你們也在那裏。","notes":[]},{"n":4,"t":"我往哪裏去，你們知道；那條路，你們也知道。」","notes":["有古卷：我往哪裏去，你們知道那條路"]},{"n":5,"t":"多馬對他說：「主啊，我們不知道你往哪裏去，怎麼知道那條路呢？」","notes":[]},{"n":6,"t":"耶穌說：「我就是道路、真理、生命；若不藉著我，沒有人能到父那裏去。","notes":[]},{"n":7,"t":"你們若認識我，也就認識我的父。從今以後，你們認識他，並且已經看見他。」","notes":[]},{"n":8,"t":"腓力對他說：「求主將父顯給我們看，我們就知足了。」","notes":[]},{"n":9,"t":"耶穌對他說：「腓力，我與你們同在這樣長久，你還不認識我嗎？人看見了我，就是看見了父；你怎麼說『將父顯給我們看』呢？","notes":[]},{"n":10,"t":"我在父裏面，父在我裏面，你不信嗎？我對你們所說的話，不是憑著自己說的，乃是住在我裏面的父做他自己的事。","notes":[]},{"n":11,"t":"你們當信我，我在父裏面，父在我裏面；即或不信，也當因我所做的事信我。","notes":[]},{"n":12,"t":"我實實在在地告訴你們，我所做的事，信我的人也要做，並且要做比這更大的事，因為我往父那裏去。","notes":[]},{"n":13,"t":"你們奉我的名無論求甚麼，我必成就，叫父因兒子得榮耀。","notes":[]},{"n":14,"t":"你們若奉我的名求甚麼，我必成就。」","notes":[]},{"n":15,"t":"「你們若愛我，就必遵守我的命令。","notes":[],"heads":["應許賜聖靈"]},{"n":16,"t":"我要求父，父就另外賜給你們一位保惠師，叫他永遠與你們同在，","notes":["或譯：訓慰師；下同"]},{"n":17,"t":"就是真理的聖靈，乃世人不能接受的；因為不見他，也不認識他。你們卻認識他，因他常與你們同在，也要在你們裏面。","notes":[]},{"n":18,"t":"我不撇下你們為孤兒，我必到你們這裏來。","notes":[]},{"n":19,"t":"還有不多的時候，世人不再看見我，你們卻看見我；因為我活著，你們也要活著。","notes":[]},{"n":20,"t":"到那日，你們就知道我在父裏面，你們在我裏面，我也在你們裏面。","notes":[]},{"n":21,"t":"有了我的命令又遵守的，這人就是愛我的；愛我的必蒙我父愛他，我也要愛他，並且要向他顯現。」","notes":[]},{"n":22,"t":"猶大（不是加略人猶大）問耶穌說：「主啊，為甚麼要向我們顯現，不向世人顯現呢？」","notes":[]},{"n":23,"t":"耶穌回答說：「人若愛我，就必遵守我的道；我父也必愛他，並且我們要到他那裏去，與他同住。","notes":[]},{"n":24,"t":"不愛我的人就不遵守我的道。你們所聽見的道不是我的，乃是差我來之父的道。","notes":[]},{"n":25,"t":"「我還與你們同住的時候，已將這些話對你們說了。","notes":[]},{"n":26,"t":"但保惠師，就是父因我的名所要差來的聖靈，他要將一切的事指教你們，並且要叫你們想起我對你們所說的一切話。","notes":[]},{"n":27,"t":"我留下平安給你們；我將我的平安賜給你們。我所賜的，不像世人所賜的。你們心裏不要憂愁，也不要膽怯。","notes":[]},{"n":28,"t":"你們聽見我對你們說了，我去還要到你們這裏來。你們若愛我，因我到父那裏去，就必喜樂，因為父是比我大的。","notes":[]},{"n":29,"t":"現在事情還沒有成就，我預先告訴你們，叫你們到事情成就的時候就可以信。","notes":[]},{"n":30,"t":"以後我不再和你們多說話，因為這世界的王將到。他在我裏面是毫無所有；","notes":[]},{"n":31,"t":"但要叫世人知道我愛父，並且父怎樣吩咐我，我就怎樣行。起來，我們走吧！」","notes":[]}]},"15":{"heading":"耶穌是真葡萄樹","verses":[{"n":1,"t":"「我是真葡萄樹，我父是栽培的人。","notes":[]},{"n":2,"t":"凡屬我不結果子的枝子，他就剪去；凡結果子的，他就修理乾淨，使枝子結果子更多。","notes":[]},{"n":3,"t":"現在你們因我講給你們的道，已經乾淨了。","notes":[]},{"n":4,"t":"你們要常在我裏面，我也常在你們裏面。枝子若不常在葡萄樹上，自己就不能結果子；你們若不常在我裏面，也是這樣。","notes":[]},{"n":5,"t":"我是葡萄樹，你們是枝子。常在我裏面的，我也常在他裏面，這人就多結果子；因為離了我，你們就不能做甚麼。","notes":[]},{"n":6,"t":"人若不常在我裏面，就像枝子丟在外面枯乾，人拾起來，扔在火裏燒了。","notes":[]},{"n":7,"t":"你們若常在我裏面，我的話也常在你們裏面，凡你們所願意的，祈求，就給你們成就。","notes":[]},{"n":8,"t":"你們多結果子，我父就因此得榮耀，你們也就是我的門徒了。","notes":[]},{"n":9,"t":"我愛你們，正如父愛我一樣；你們要常在我的愛裏。","notes":[]},{"n":10,"t":"你們若遵守我的命令，就常在我的愛裏，正如我遵守了我父的命令，常在他的愛裏。","notes":[]},{"n":11,"t":"「這些事我已經對你們說了，是要叫我的喜樂存在你們心裏，並叫你們的喜樂可以滿足。","notes":[]},{"n":12,"t":"你們要彼此相愛，像我愛你們一樣；這就是我的命令。","notes":[]},{"n":13,"t":"人為朋友捨命，人的愛心沒有比這個大的。","notes":[]},{"n":14,"t":"你們若遵行我所吩咐的，就是我的朋友了。","notes":[]},{"n":15,"t":"以後我不再稱你們為僕人，因僕人不知道主人所做的事。我乃稱你們為朋友；因我從我父所聽見的，已經都告訴你們了。","notes":[]},{"n":16,"t":"不是你們揀選了我，是我揀選了你們，並且分派你們去結果子，叫你們的果子常存，使你們奉我的名，無論向父求甚麼，他就賜給你們。","notes":[]},{"n":17,"t":"我這樣吩咐你們，是要叫你們彼此相愛。」","notes":[]},{"n":18,"t":"「世人若恨你們，你們知道，恨你們以先已經恨我了。","notes":["或譯：該知道"],"heads":["世人的憎恨"]},{"n":19,"t":"你們若屬世界，世界必愛屬自己的；只因你們不屬世界，乃是我從世界中揀選了你們，所以世界就恨你們。","notes":[]},{"n":20,"t":"你們要記念我從前對你們所說的話：『僕人不能大於主人。』他們若逼迫了我，也要逼迫你們；若遵守了我的話，也要遵守你們的話。","notes":[]},{"n":21,"t":"但他們因我的名要向你們行這一切的事，因為他們不認識那差我來的。","notes":[]},{"n":22,"t":"我若沒有來教訓他們，他們就沒有罪；但如今他們的罪無可推諉了。","notes":[]},{"n":23,"t":"恨我的，也恨我的父。","notes":[]},{"n":24,"t":"我若沒有在他們中間行過別人未曾行的事，他們就沒有罪；但如今連我與我的父，他們也看見也恨惡了。","notes":[]},{"n":25,"t":"這要應驗他們律法上所寫的話，說：『他們無故地恨我。』","notes":[]},{"n":26,"t":"但我要從父那裏差保惠師來，就是從父出來真理的聖靈；他來了，就要為我作見證。","notes":[]},{"n":27,"t":"你們也要作見證，因為你們從起頭就與我同在。」","notes":[]}]},"16":{"heading":"聖靈的工作","verses":[{"n":1,"t":"「我已將這些事告訴你們，使你們不至於跌倒。","notes":[]},{"n":2,"t":"人要把你們趕出會堂，並且時候將到，凡殺你們的就以為是事奉神。","notes":[]},{"n":3,"t":"他們這樣行，是因未曾認識父，也未曾認識我。","notes":[]},{"n":4,"t":"我將這事告訴你們，是叫你們到了時候可以想起我對你們說過了。」「我起先沒有將這事告訴你們，因為我與你們同在。","notes":[]},{"n":5,"t":"現今我往差我來的父那裏去，你們中間並沒有人問我：『你往哪裏去？』","notes":[]},{"n":6,"t":"只因我將這事告訴你們，你們就滿心憂愁。","notes":[]},{"n":7,"t":"然而，我將真情告訴你們，我去是與你們有益的；我若不去，保惠師就不到你們這裏來；我若去，就差他來。","notes":[]},{"n":8,"t":"他既來了，就要叫世人為罪、為義、為審判，自己責備自己。","notes":[]},{"n":9,"t":"為罪，是因他們不信我；","notes":[]},{"n":10,"t":"為義，是因我往父那裏去，你們就不再見我；","notes":[]},{"n":11,"t":"為審判，是因這世界的王受了審判。","notes":[]},{"n":12,"t":"「我還有好些事要告訴你們，但你們現在擔當不了。","notes":["或譯：不能領會"]},{"n":13,"t":"只等真理的聖靈來了，他要引導你們明白一切的真理；因為他不是憑自己說的，乃是把他所聽見的都說出來，並要把將來的事告訴你們。","notes":["原文是進入"]},{"n":14,"t":"他要榮耀我，因為他要將受於我的告訴你們。","notes":[]},{"n":15,"t":"凡父所有的，都是我的；所以我說，他要將受於我的告訴你們。」","notes":[]},{"n":16,"t":"「等不多時，你們就不得見我；再等不多時，你們還要見我。」","notes":[],"heads":["憂愁變為喜樂"]},{"n":17,"t":"有幾個門徒就彼此說：「他對我們說：『等不多時，你們就不得見我；再等不多時，你們還要見我』；又說：『因我往父那裏去。』這是甚麼意思呢？」","notes":[]},{"n":18,"t":"門徒彼此說：「他說『等不多時』到底是甚麼意思呢？我們不明白他所說的話。」","notes":[]},{"n":19,"t":"耶穌看出他們要問他，就說：「我說『等不多時，你們就不得見我；再等不多時，你們還要見我』，你們為這話彼此相問嗎？","notes":[]},{"n":20,"t":"我實實在在地告訴你們，你們將要痛哭、哀號，世人倒要喜樂；你們將要憂愁，然而你們的憂愁要變為喜樂。","notes":[]},{"n":21,"t":"婦人生產的時候就憂愁，因為她的時候到了；既生了孩子，就不再記念那苦楚，因為歡喜世上生了一個人。","notes":[]},{"n":22,"t":"你們現在也是憂愁，但我要再見你們，你們的心就喜樂了；這喜樂也沒有人能奪去。","notes":[]},{"n":23,"t":"到那日，你們甚麼也就不問我了。我實實在在地告訴你們，你們若向父求甚麼，他必因我的名賜給你們。","notes":[]},{"n":24,"t":"向來你們沒有奉我的名求甚麼，如今你們求，就必得著，叫你們的喜樂可以滿足。」","notes":[]},{"n":25,"t":"「這些事，我是用比喻對你們說的；時候將到，我不再用比喻對你們說，乃要將父明明地告訴你們。","notes":[],"heads":["我已經勝過世界"]},{"n":26,"t":"到那日，你們要奉我的名祈求；我並不對你們說，我要為你們求父。","notes":[]},{"n":27,"t":"父自己愛你們；因為你們已經愛我，又信我是從父出來的。","notes":[]},{"n":28,"t":"我從父出來，到了世界；我又離開世界，往父那裏去。」","notes":[]},{"n":29,"t":"門徒說：「如今你是明說，並不用比喻了。","notes":[]},{"n":30,"t":"現在我們曉得你凡事都知道，也不用人問你，因此我們信你是從神出來的。」","notes":[]},{"n":31,"t":"耶穌說：「現在你們信嗎？","notes":[]},{"n":32,"t":"看哪，時候將到，且是已經到了，你們要分散，各歸自己的地方去，留下我獨自一人；其實我不是獨自一人，因為有父與我同在。","notes":[]},{"n":33,"t":"我將這些事告訴你們，是要叫你們在我裏面有平安。在世上，你們有苦難；但你們可以放心，我已經勝了世界。」","notes":[]}]},"17":{"heading":"耶穌的禱告","verses":[{"n":1,"t":"耶穌說了這話，就舉目望天，說：「父啊，時候到了，願你榮耀你的兒子，使兒子也榮耀你；","notes":[]},{"n":2,"t":"正如你曾賜給他權柄管理凡有血氣的，叫他將永生賜給你所賜給他的人。","notes":[]},{"n":3,"t":"認識你－獨一的真神，並且認識你所差來的耶穌基督，這就是永生。","notes":[]},{"n":4,"t":"我在地上已經榮耀你，你所託付我的事，我已成全了。","notes":[]},{"n":5,"t":"父啊，現在求你使我同你享榮耀，就是未有世界以先，我同你所有的榮耀。","notes":[]},{"n":6,"t":"「你從世上賜給我的人，我已將你的名顯明與他們。他們本是你的，你將他們賜給我，他們也遵守了你的道。","notes":[]},{"n":7,"t":"如今他們知道，凡你所賜給我的，都是從你那裏來的；","notes":[]},{"n":8,"t":"因為你所賜給我的道，我已經賜給他們，他們也領受了，又確實知道，我是從你出來的，並且信你差了我來。","notes":[]},{"n":9,"t":"我為他們祈求，不為世人祈求，卻為你所賜給我的人祈求，因他們本是你的。","notes":[]},{"n":10,"t":"凡是我的，都是你的；你的也是我的，並且我因他們得了榮耀。","notes":[]},{"n":11,"t":"從今以後，我不在世上，他們卻在世上；我往你那裏去。聖父啊，求你因你所賜給我的名保守他們，叫他們合而為一像我們一樣。","notes":[]},{"n":12,"t":"我與他們同在的時候，因你所賜給我的名保守了他們，我也護衛了他們；其中除了那滅亡之子，沒有一個滅亡的，好叫經上的話得應驗。","notes":[]},{"n":13,"t":"現在我往你那裏去，我還在世上說這話，是叫他們心裏充滿我的喜樂。","notes":[]},{"n":14,"t":"我已將你的道賜給他們。世界又恨他們；因為他們不屬世界，正如我不屬世界一樣。","notes":[]},{"n":15,"t":"我不求你叫他們離開世界，只求你保守他們脫離那惡者。","notes":["或譯：脫離罪惡"]},{"n":16,"t":"他們不屬世界，正如我不屬世界一樣。","notes":[]},{"n":17,"t":"求你用真理使他們成聖；你的道就是真理。","notes":[]},{"n":18,"t":"你怎樣差我到世上，我也照樣差他們到世上。","notes":[]},{"n":19,"t":"我為他們的緣故，自己分別為聖，叫他們也因真理成聖。","notes":[]},{"n":20,"t":"「我不但為這些人祈求，也為那些因他們的話信我的人祈求，","notes":[]},{"n":21,"t":"使他們都合而為一。正如你父在我裏面，我在你裏面，使他們也在我們裏面，叫世人可以信你差了我來。","notes":[]},{"n":22,"t":"你所賜給我的榮耀，我已賜給他們，使他們合而為一，像我們合而為一。","notes":[]},{"n":23,"t":"我在他們裏面，你在我裏面，使他們完完全全地合而為一，叫世人知道你差了我來，也知道你愛他們如同愛我一樣。","notes":[]},{"n":24,"t":"父啊，我在哪裏，願你所賜給我的人也同我在那裏，叫他們看見你所賜給我的榮耀；因為創立世界以前，你已經愛我了。","notes":[]},{"n":25,"t":"公義的父啊，世人未曾認識你，我卻認識你；這些人也知道你差了我來。","notes":[]},{"n":26,"t":"我已將你的名指示他們，還要指示他們，使你所愛我的愛在他們裏面，我也在他們裏面。」","notes":[]}]},"18":{"heading":"耶穌被捕","verses":[{"n":1,"t":"耶穌說了這話，就同門徒出去，過了汲淪溪。在那裏有一個園子，他和門徒進去了。","notes":[]},{"n":2,"t":"賣耶穌的猶大也知道那地方，因為耶穌和門徒屢次上那裏去聚集。","notes":[]},{"n":3,"t":"猶大領了一隊兵，和祭司長並法利賽人的差役，拿著燈籠、火把、兵器，就來到園裏。","notes":[]},{"n":4,"t":"耶穌知道將要臨到自己的一切事，就出來對他們說：「你們找誰？」","notes":[]},{"n":5,"t":"他們回答說：「找拿撒勒人耶穌。」耶穌說：「我就是！」賣他的猶大也同他們站在那裏。","notes":[]},{"n":6,"t":"耶穌一說「我就是」，他們就退後倒在地上。","notes":[]},{"n":7,"t":"他又問他們說：「你們找誰？」他們說：「找拿撒勒人耶穌。」","notes":[]},{"n":8,"t":"耶穌說：「我已經告訴你們，我就是。你們若找我，就讓這些人去吧。」","notes":[]},{"n":9,"t":"這要應驗耶穌從前的話，說：「你所賜給我的人，我沒有失落一個。」","notes":[]},{"n":10,"t":"西門‧彼得帶著一把刀，就拔出來，將大祭司的僕人砍了一刀，削掉他的右耳；那僕人名叫馬勒古。","notes":[]},{"n":11,"t":"耶穌就對彼得說：「收刀入鞘吧，我父所給我的那杯，我豈可不喝呢？」","notes":[]},{"n":12,"t":"那隊兵和千夫長，並猶太人的差役就拿住耶穌，把他捆綁了，","notes":[],"heads":["耶穌被帶到亞那面前"]},{"n":13,"t":"先帶到亞那面前，因為亞那是本年作大祭司該亞法的岳父。","notes":[]},{"n":14,"t":"這該亞法就是從前向猶太人發議論說「一個人替百姓死是有益的」那位。","notes":[]},{"n":15,"t":"西門‧彼得跟著耶穌，還有一個門徒跟著。那門徒是大祭司所認識的，他就同耶穌進了大祭司的院子。","notes":[],"heads":["彼得不認耶穌"]},{"n":16,"t":"彼得卻站在門外。大祭司所認識的那個門徒出來，和看門的使女說了一聲，就領彼得進去。","notes":[]},{"n":17,"t":"那看門的使女對彼得說：「你不也是這人的門徒嗎？」他說：「我不是。」","notes":[]},{"n":18,"t":"僕人和差役因為天冷，就生了炭火，站在那裏烤火；彼得也同他們站著烤火。","notes":[]},{"n":19,"t":"大祭司就以耶穌的門徒和他的教訓盤問他。","notes":[],"heads":["大祭司盤問耶穌"]},{"n":20,"t":"耶穌回答說：「我從來是明明地對世人說話。我常在會堂和殿裏，就是猶太人聚集的地方教訓人；我在暗地裏並沒有說甚麼。","notes":[]},{"n":21,"t":"你為甚麼問我呢？可以問那聽見的人，我對他們說的是甚麼；我所說的，他們都知道。」","notes":[]},{"n":22,"t":"耶穌說了這話，旁邊站著的一個差役用手掌打他，說：「你這樣回答大祭司嗎？」","notes":[]},{"n":23,"t":"耶穌說：「我若說的不是，你可以指證那不是；我若說的是，你為甚麼打我呢？」","notes":[]},{"n":24,"t":"亞那就把耶穌解到大祭司該亞法那裏，仍是捆著解去的。","notes":[]},{"n":25,"t":"西門‧彼得正站著烤火，有人對他說：「你不也是他的門徒嗎？」彼得不承認，說：「我不是。」","notes":[],"heads":["彼得再次不認耶穌"]},{"n":26,"t":"有大祭司的一個僕人，是彼得削掉耳朵那人的親屬，說：「我不是看見你同他在園子裏嗎？」","notes":[]},{"n":27,"t":"彼得又不承認。立時雞就叫了。","notes":[]},{"n":28,"t":"眾人將耶穌從該亞法那裏往衙門內解去，那時天還早。他們自己卻不進衙門，恐怕染了污穢，不能吃逾越節的筵席。","notes":[],"heads":["耶穌在彼拉多面前受審"]},{"n":29,"t":"彼拉多就出來，到他們那裏，說：「你們告這人是為甚麼事呢？」","notes":[]},{"n":30,"t":"他們回答說：「這人若不是作惡的，我們就不把他交給你。」","notes":[]},{"n":31,"t":"彼拉多說：「你們自己帶他去，按著你們的律法審問他吧。」猶太人說：「我們沒有殺人的權柄。」","notes":[]},{"n":32,"t":"這要應驗耶穌所說自己將要怎樣死的話了。","notes":[]},{"n":33,"t":"彼拉多又進了衙門，叫耶穌來，對他說：「你是猶太人的王嗎？」","notes":[]},{"n":34,"t":"耶穌回答說：「這話是你自己說的，還是別人論我對你說的呢？」","notes":[]},{"n":35,"t":"彼拉多說：「我豈是猶太人呢？你本國的人和祭司長把你交給我。你做了甚麼事呢？」","notes":[]},{"n":36,"t":"耶穌回答說：「我的國不屬這世界；我的國若屬這世界，我的臣僕必要爭戰，使我不至於被交給猶太人。只是我的國不屬這世界。」","notes":[]},{"n":37,"t":"彼拉多就對他說：「這樣，你是王嗎？」耶穌回答說：「你說我是王。我為此而生，也為此來到世間，特為給真理作見證。凡屬真理的人就聽我的話。」","notes":[]},{"n":38,"t":"彼拉多說：「真理是甚麼呢？」說了這話，又出來到猶太人那裏，對他們說：「我查不出他有甚麼罪來。","notes":[]},{"n":39,"t":"但你們有個規矩，在逾越節要我給你們釋放一個人，你們要我給你們釋放猶太人的王嗎？」","notes":[]},{"n":40,"t":"他們又喊著說：「不要這人，要巴拉巴！」這巴拉巴是個強盜。","notes":[]}]},"19":{"heading":"耶穌被釘十字架","verses":[{"n":1,"t":"當下彼拉多將耶穌鞭打了。","notes":[]},{"n":2,"t":"兵丁用荊棘編做冠冕戴在他頭上，給他穿上紫袍，","notes":[]},{"n":3,"t":"又挨近他，說：「恭喜，猶太人的王啊！」他們就用手掌打他。","notes":[]},{"n":4,"t":"彼拉多又出來對眾人說：「我帶他出來見你們，叫你們知道我查不出他有甚麼罪來。」","notes":[]},{"n":5,"t":"耶穌出來，戴著荊棘冠冕，穿著紫袍。彼拉多對他們說：「你們看這個人！」","notes":[]},{"n":6,"t":"祭司長和差役看見他，就喊著說：「釘他十字架！釘他十字架！」彼拉多說：「你們自己把他釘十字架吧！我查不出他有甚麼罪來。」","notes":[]},{"n":7,"t":"猶太人回答說：「我們有律法，按那律法，他是該死的，因他以自己為神的兒子。」","notes":[]},{"n":8,"t":"彼拉多聽見這話，越發害怕，","notes":[]},{"n":9,"t":"又進衙門，對耶穌說：「你是哪裏來的？」耶穌卻不回答。","notes":[]},{"n":10,"t":"彼拉多說：「你不對我說話嗎？你豈不知我有權柄釋放你，也有權柄把你釘十字架嗎？」","notes":[]},{"n":11,"t":"耶穌回答說：「若不是從上頭賜給你的，你就毫無權柄辦我。所以，把我交給你的那人罪更重了。」","notes":[]},{"n":12,"t":"從此，彼拉多想要釋放耶穌，無奈猶太人喊著說：「你若釋放這個人，就不是凱撒的忠臣。凡以自己為王的，就是背叛凱撒了。」","notes":["原文是朋友"]},{"n":13,"t":"彼拉多聽見這話，就帶耶穌出來，到了一個地方，名叫「鋪華石處」，希伯來話叫厄巴大，就在那裏坐堂。","notes":[]},{"n":14,"t":"那日是預備逾越節的日子，約有午正。彼拉多對猶太人說：「看哪，這是你們的王！」","notes":[]},{"n":15,"t":"他們喊著說：「除掉他！除掉他！釘他在十字架上！」彼拉多說：「我可以把你們的王釘十字架嗎？」祭司長回答說：「除了凱撒，我們沒有王。」","notes":[]},{"n":16,"t":"於是彼拉多將耶穌交給他們去釘十字架。","notes":[]},{"n":17,"t":"他們就把耶穌帶了去。耶穌背著自己的十字架出來，到了一個地方，名叫「髑髏地」，希伯來話叫各各他。","notes":[]},{"n":18,"t":"他們就在那裏釘他在十字架上，還有兩個人和他一同釘著，一邊一個，耶穌在中間。","notes":[]},{"n":19,"t":"彼拉多又用牌子寫了一個名號，安在十字架上，寫的是：「猶太人的王，拿撒勒人耶穌。」","notes":[]},{"n":20,"t":"有許多猶太人念這名號；因為耶穌被釘十字架的地方與城相近，並且是用希伯來、羅馬、希臘三樣文字寫的。","notes":[]},{"n":21,"t":"猶太人的祭司長就對彼拉多說：「不要寫『猶太人的王』，要寫『他自己說：我是猶太人的王』。」","notes":[]},{"n":22,"t":"彼拉多說：「我所寫的，我已經寫上了。」","notes":[]},{"n":23,"t":"兵丁既然將耶穌釘在十字架上，就拿他的衣服分為四分，每兵一分；又拿他的裏衣，這件裏衣原來沒有縫兒，是上下一片織成的。","notes":[]},{"n":24,"t":"他們就彼此說：「我們不要撕開，只要拈鬮，看誰得著。」這要應驗經上的話說：他們分了我的外衣，為我的裏衣拈鬮。兵丁果然做了這事。","notes":[]},{"n":25,"t":"站在耶穌十字架旁邊的，有他母親與他母親的姊妹，並革羅罷的妻子馬利亞，和抹大拉的馬利亞。","notes":[]},{"n":26,"t":"耶穌見母親和他所愛的那門徒站在旁邊，就對他母親說：「母親，看，你的兒子！」","notes":["原文是婦人"]},{"n":27,"t":"又對那門徒說：「看，你的母親！」從此，那門徒就接她到自己家裏去了。","notes":[]},{"n":28,"t":"這事以後，耶穌知道各樣的事已經成了，為要使經上的話應驗，就說：「我渴了。」","notes":[],"heads":["耶穌的死"]},{"n":29,"t":"有一個器皿盛滿了醋，放在那裏；他們就拿海絨蘸滿了醋，綁在牛膝草上，送到他口。","notes":[]},{"n":30,"t":"耶穌嘗了那醋，就說：「成了！」便低下頭，將靈魂交付神了。","notes":["原文是受"]},{"n":31,"t":"猶太人因這日是預備日，又因那安息日是個大日，就求彼拉多叫人打斷他們的腿，把他們拿去，免得屍首當安息日留在十字架上。","notes":[],"heads":["肋旁被扎"]},{"n":32,"t":"於是兵丁來，把頭一個人的腿，並與耶穌同釘第二個人的腿，都打斷了。","notes":[]},{"n":33,"t":"只是來到耶穌那裏，見他已經死了，就不打斷他的腿。","notes":[]},{"n":34,"t":"惟有一個兵拿槍扎他的肋旁，隨即有血和水流出來。","notes":[]},{"n":35,"t":"看見這事的那人就作見證－他的見證也是真的，並且他知道自己所說的是真的－叫你們也可以信。","notes":[]},{"n":36,"t":"這些事成了，為要應驗經上的話說：「他的骨頭一根也不可折斷。」","notes":[]},{"n":37,"t":"經上又有一句說：「他們要仰望自己所扎的人。」","notes":[]},{"n":38,"t":"這些事以後，有亞利馬太人約瑟，是耶穌的門徒，只因怕猶太人，就暗暗地作門徒。他來求彼拉多，要把耶穌的身體領去。彼拉多允准，他就把耶穌的身體領去了。","notes":[],"heads":["耶穌的安葬"]},{"n":39,"t":"又有尼哥德慕，就是先前夜裏去見耶穌的，帶著沒藥和沉香約有一百斤前來。","notes":[]},{"n":40,"t":"他們就照猶太人殯葬的規矩，把耶穌的身體用細麻布加上香料裹好了。","notes":[]},{"n":41,"t":"在耶穌釘十字架的地方有一個園子，園子裏有一座新墳墓，是從來沒有葬過人的。","notes":[]},{"n":42,"t":"只因是猶太人的預備日，又因那墳墓近，他們就把耶穌安放在那裏。","notes":[]}]},"20":{"heading":"耶穌復活","verses":[{"n":1,"t":"七日的第一日清早，天還黑的時候，抹大拉的馬利亞來到墳墓那裏，看見石頭從墳墓挪開了，","notes":[]},{"n":2,"t":"就跑來見西門‧彼得和耶穌所愛的那個門徒，對他們說：「有人把主從墳墓裏挪了去，我們不知道放在哪裏。」","notes":[]},{"n":3,"t":"彼得和那門徒就出來，往墳墓那裏去。","notes":[]},{"n":4,"t":"兩個人同跑，那門徒比彼得跑得更快，先到了墳墓，","notes":[]},{"n":5,"t":"低頭往裏看，就見細麻布還放在那裏，只是沒有進去。","notes":[]},{"n":6,"t":"西門‧彼得隨後也到了，進墳墓裏去，就看見細麻布還放在那裏，","notes":[]},{"n":7,"t":"又看見耶穌的裹頭巾沒有和細麻布放在一處，是另在一處捲著。","notes":[]},{"n":8,"t":"先到墳墓的那門徒也進去，看見就信了。（","notes":[]},{"n":9,"t":"因為他們還不明白聖經的意思，就是耶穌必要從死裏復活。）","notes":[]},{"n":10,"t":"於是兩個門徒回自己的住處去了。","notes":[]},{"n":11,"t":"馬利亞卻站在墳墓外面哭。哭的時候，低頭往墳墓裏看，","notes":[],"heads":["向抹大拉的馬利亞顯現"]},{"n":12,"t":"就見兩個天使，穿著白衣，在安放耶穌身體的地方坐著，一個在頭，一個在腳。","notes":[]},{"n":13,"t":"天使對她說：「婦人，你為甚麼哭？」她說：「因為有人把我主挪了去，我不知道放在哪裏。」","notes":[]},{"n":14,"t":"說了這話，就轉過身來，看見耶穌站在那裏，卻不知道是耶穌。","notes":[]},{"n":15,"t":"耶穌問她說：「婦人，為甚麼哭？你找誰呢？」馬利亞以為是看園的，就對他說：「先生，若是你把他移了去，請告訴我，你把他放在哪裏，我便去取他。」","notes":[]},{"n":16,"t":"耶穌說：「馬利亞。」馬利亞就轉過來，用希伯來話對他說：「拉波尼！」（拉波尼就是夫子的意思。）","notes":[]},{"n":17,"t":"耶穌說：「不要摸我，因我還沒有升上去見我的父。你往我弟兄那裏去，告訴他們說，我要升上去見我的父，也是你們的父，見我的神，也是你們的神。」","notes":[]},{"n":18,"t":"抹大拉的馬利亞就去告訴門徒說：「我已經看見了主。」她又將主對她說的這話告訴他們。","notes":[]},{"n":19,"t":"那日（就是七日的第一日）晚上，門徒所在的地方，因怕猶太人，門都關了。耶穌來，站在當中，對他們說：「願你們平安！」","notes":[],"heads":["向門徒顯現"]},{"n":20,"t":"說了這話，就把手和肋旁指給他們看。門徒看見主，就喜樂了。","notes":[]},{"n":21,"t":"耶穌又對他們說：「願你們平安！父怎樣差遣了我，我也照樣差遣你們。」","notes":[]},{"n":22,"t":"說了這話，就向他們吹一口氣，說：「你們受聖靈！","notes":[]},{"n":23,"t":"你們赦免誰的罪，誰的罪就赦免了；你們留下誰的罪，誰的罪就留下了。」","notes":[]},{"n":24,"t":"那十二個門徒中，有稱為低土馬的多馬；耶穌來的時候，他沒有和他們同在。","notes":[],"heads":["耶穌和多馬"]},{"n":25,"t":"那些門徒就對他說：「我們已經看見主了。」多馬卻說：「我非看見他手上的釘痕，用指頭探入那釘痕，又用手探入他的肋旁，我總不信。」","notes":[]},{"n":26,"t":"過了八日，門徒又在屋裏，多馬也和他們同在，門都關了。耶穌來，站在當中說：「願你們平安！」","notes":[]},{"n":27,"t":"就對多馬說：「伸過你的指頭來，摸我的手；伸出你的手來，探入我的肋旁。不要疑惑，總要信！」","notes":["原文是看"]},{"n":28,"t":"多馬說：「我的主！我的神！」","notes":[]},{"n":29,"t":"耶穌對他說：「你因看見了我才信；那沒有看見就信的有福了。」","notes":[]},{"n":30,"t":"耶穌在門徒面前另外行了許多神蹟，沒有記在這書上。","notes":[],"heads":["本書的目的"]},{"n":31,"t":"但記這些事要叫你們信耶穌是基督，是神的兒子，並且叫你們信了他，就可以因他的名得生命。","notes":[]}]},"21":{"heading":"耶穌向七個門徒顯現","verses":[{"n":1,"t":"這些事以後，耶穌在提比哩亞海邊又向門徒顯現。他怎樣顯現記在下面：","notes":[]},{"n":2,"t":"有西門‧彼得和稱為低土馬的多馬，並加利利的迦拿人拿但業，還有西庇太的兩個兒子，又有兩個門徒，都在一處。","notes":[]},{"n":3,"t":"西門‧彼得對他們說：「我打魚去。」他們說：「我們也和你同去。」他們就出去，上了船；那一夜並沒有打著甚麼。","notes":[]},{"n":4,"t":"天將亮的時候，耶穌站在岸上，門徒卻不知道是耶穌。","notes":[]},{"n":5,"t":"耶穌就對他們說：「小子！你們有吃的沒有？」他們回答說：「沒有。」","notes":[]},{"n":6,"t":"耶穌說：「你們把網撒在船的右邊，就必得著。」他們便撒下網去，竟拉不上來了，因為魚甚多。","notes":[]},{"n":7,"t":"耶穌所愛的那門徒對彼得說：「是主！」那時西門‧彼得赤著身子，一聽見是主，就束上一件外衣，跳在海裏。","notes":[]},{"n":8,"t":"其餘的門徒離岸不遠，約有二百肘，就在小船上把那網魚拉過來。","notes":["古時以肘為尺，一肘約有今時尺半"]},{"n":9,"t":"他們上了岸，就看見那裏有炭火，上面有魚，又有餅。","notes":[]},{"n":10,"t":"耶穌對他們說：「把剛才打的魚拿幾條來。」","notes":[]},{"n":11,"t":"西門‧彼得就去，把網拉到岸上。那網滿了大魚，共一百五十三條；魚雖這樣多，網卻沒有破。","notes":["或譯：上船"]},{"n":12,"t":"耶穌說：「你們來吃早飯。」門徒中沒有一個敢問他：「你是誰？」因為知道是主。","notes":[]},{"n":13,"t":"耶穌就來拿餅和魚給他們。","notes":[]},{"n":14,"t":"耶穌從死裏復活以後，向門徒顯現，這是第三次。","notes":[]},{"n":15,"t":"他們吃完了早飯，耶穌對西門‧彼得說：「約翰的兒子西門，你愛我比這些更深嗎？」彼得說：「主啊，是的，你知道我愛你。」耶穌對他說：「你餵養我的小羊。」","notes":["在馬太十六章十七節稱約拿"],"heads":["耶穌和彼得"]},{"n":16,"t":"耶穌第二次又對他說：「約翰的兒子西門，你愛我嗎？」彼得說：「主啊，是的，你知道我愛你。」耶穌說：「你牧養我的羊。」","notes":[]},{"n":17,"t":"第三次對他說：「約翰的兒子西門，你愛我嗎？」彼得因為耶穌第三次對他說「你愛我嗎」，就憂愁，對耶穌說：「主啊，你是無所不知的；你知道我愛你。」耶穌說：「你餵養我的羊。","notes":[]},{"n":18,"t":"我實實在在地告訴你，你年少的時候，自己束上帶子，隨意往來；但年老的時候，你要伸出手來，別人要把你束上，帶你到不願意去的地方。」","notes":[]},{"n":19,"t":"（耶穌說這話是指著彼得要怎樣死，榮耀神。）說了這話，就對他說：「你跟從我吧！」","notes":[]},{"n":20,"t":"彼得轉過來，看見耶穌所愛的那門徒跟著，（就是在晚飯的時候，靠著耶穌胸膛說：「主啊，賣你的是誰？」的那門徒。）","notes":[],"heads":["耶穌和他所愛的那門徒"]},{"n":21,"t":"彼得看見他，就問耶穌說：「主啊，這人將來如何？」","notes":[]},{"n":22,"t":"耶穌對他說：「我若要他等到我來的時候，與你何干？你跟從我吧！」","notes":[]},{"n":23,"t":"於是這話傳在弟兄中間，說那門徒不死。其實，耶穌不是說他不死，乃是說：「我若要他等到我來的時候，與你何干？」","notes":[]},{"n":24,"t":"為這些事作見證，並且記載這些事的就是這門徒；我們也知道他的見證是真的。","notes":[]},{"n":25,"t":"耶穌所行的事還有許多，若是一一地都寫出來，我想，所寫的書就是世界也容不下了。","notes":[]}]}},"ACT":{"1":{"heading":"賜聖靈的應許","verses":[{"n":1,"t":"提阿非羅啊，我已經作了前書，論到耶穌開頭一切所行所教訓的，","notes":[]},{"n":2,"t":"直到他藉著聖靈吩咐所揀選的使徒，以後被接上升的日子為止。","notes":[]},{"n":3,"t":"他受害之後，用許多的憑據將自己活活地顯給使徒看，四十天之久向他們顯現，講說神國的事。","notes":[]},{"n":4,"t":"耶穌和他們聚集的時候，囑咐他們說：「不要離開耶路撒冷，要等候父所應許的，就是你們聽見我說過的。","notes":[]},{"n":5,"t":"約翰是用水施洗，但不多幾日，你們要受聖靈的洗。」","notes":[]},{"n":6,"t":"他們聚集的時候，問耶穌說：「主啊，你復興以色列國就在這時候嗎？」","notes":[],"heads":["耶穌升天"]},{"n":7,"t":"耶穌對他們說：「父憑著自己的權柄所定的時候、日期，不是你們可以知道的。","notes":[]},{"n":8,"t":"但聖靈降臨在你們身上，你們就必得著能力，並要在耶路撒冷、猶太全地，和撒馬利亞，直到地極，作我的見證。」","notes":[]},{"n":9,"t":"說了這話，他們正看的時候，他就被取上升，有一朵雲彩把他接去，便看不見他了。","notes":[]},{"n":10,"t":"當他往上去，他們定睛望天的時候，忽然有兩個人身穿白衣，站在旁邊，說：","notes":[]},{"n":11,"t":"「加利利人哪，你們為甚麼站著望天呢？這離開你們被接升天的耶穌，你們見他怎樣往天上去，他還要怎樣來。」","notes":[]},{"n":12,"t":"有一座山，名叫橄欖山，離耶路撒冷不遠，約有安息日可走的路程。當下，門徒從那裏回耶路撒冷去，","notes":[],"heads":["接替猶大職分的人"]},{"n":13,"t":"進了城，就上了所住的一間樓房；在那裏有彼得、約翰、雅各、安得烈、腓力、多馬、巴多羅買、馬太、亞勒腓的兒子雅各、奮銳黨的西門，和雅各的兒子猶大。","notes":["或譯：兄弟"]},{"n":14,"t":"這些人同著幾個婦人和耶穌的母親馬利亞，並耶穌的弟兄，都同心合意地恆切禱告。","notes":[]},{"n":15,"t":"那時，有許多人聚會，約有一百二十名，彼得就在弟兄中間站起來，","notes":[]},{"n":16,"t":"說：「弟兄們！聖靈藉大衛的口，在聖經上預言領人捉拿耶穌的猶大，這話是必須應驗的。","notes":[]},{"n":17,"t":"他本來列在我們數中，並且在使徒的職任上得了一分。","notes":[]},{"n":18,"t":"這人用他作惡的工價買了一塊田，以後身子仆倒，肚腹崩裂，腸子都流出來。","notes":[]},{"n":19,"t":"住在耶路撒冷的眾人都知道這事，所以按著他們那裏的話給那塊田起名叫亞革大馬，就是「血田」的意思。","notes":[]},{"n":20,"t":"因為詩篇上寫著，說：願他的住處變為荒場，無人在內居住；又說：願別人得他的職分。","notes":[]},{"n":21,"t":"所以，主耶穌在我們中間始終出入的時候，","notes":[]},{"n":22,"t":"就是從約翰施洗起，直到主離開我們被接上升的日子為止，必須從那常與我們作伴的人中立一位與我們同作耶穌復活的見證。」","notes":[]},{"n":23,"t":"於是選舉兩個人，就是那叫做巴撒巴，又稱呼猶士都的約瑟，和馬提亞。","notes":[]},{"n":24,"t":"眾人就禱告說：「主啊，你知道萬人的心，求你從這兩個人中，指明你所揀選的是誰，叫他得這使徒的位分。這位分猶大已經丟棄，往自己的地方去了。」","notes":[],"end":25},{"n":26,"t":"於是眾人為他們搖籤，搖出馬提亞來；他就和十一個使徒同列。","notes":[]}]},"2":{"heading":"聖靈降臨","verses":[{"n":1,"t":"五旬節到了，門徒都聚集在一處。","notes":[]},{"n":2,"t":"忽然，從天上有響聲下來，好像一陣大風吹過，充滿了他們所坐的屋子，","notes":[]},{"n":3,"t":"又有舌頭如火焰顯現出來，分開落在他們各人頭上。","notes":[]},{"n":4,"t":"他們就都被聖靈充滿，按著聖靈所賜的口才說起別國的話來。","notes":[]},{"n":5,"t":"那時，有虔誠的猶太人從天下各國來，住在耶路撒冷。","notes":[]},{"n":6,"t":"這聲音一響，眾人都來聚集，各人聽見門徒用眾人的鄉談說話，就甚納悶；","notes":[]},{"n":7,"t":"都驚訝希奇說：「看哪，這說話的不都是加利利人嗎？","notes":[]},{"n":8,"t":"我們各人怎麼聽見他們說我們生來所用的鄉談呢？","notes":[]},{"n":9,"t":"我們帕提亞人、米底亞人、以攔人，和住在美索不達米亞、猶太、加帕多家、本都、亞細亞、","notes":[]},{"n":10,"t":"弗呂家、旁非利亞、埃及的人，並靠近古利奈的利比亞一帶地方的人，從羅馬來的客旅中，或是猶太人，或是進猶太教的人，","notes":[]},{"n":11,"t":"克里特和阿拉伯人，都聽見他們用我們的鄉談，講說神的大作為。」","notes":[]},{"n":12,"t":"眾人就都驚訝猜疑，彼此說：「這是甚麼意思呢？」","notes":[]},{"n":13,"t":"還有人譏誚說：「他們無非是新酒灌滿了。」","notes":[]},{"n":14,"t":"彼得和十一個使徒站起，高聲說：「猶太人和一切住在耶路撒冷的人哪，這件事你們當知道，也當側耳聽我的話。","notes":[],"heads":["彼得在五旬節的講論"]},{"n":15,"t":"你們想這些人是醉了；其實不是醉了，因為時候剛到巳初。","notes":[]},{"n":16,"t":"這正是先知約珥所說的：","notes":[]},{"n":17,"t":"神說：在末後的日子，我要將我的靈澆灌凡有血氣的。你們的兒女要說預言；你們的少年人要見異象；老年人要做異夢。","notes":[]},{"n":18,"t":"在那些日子，我要將我的靈澆灌我的僕人和使女，他們就要說預言。","notes":[]},{"n":19,"t":"在天上，我要顯出奇事；在地下， 我要顯出神蹟；有血，有火，有煙霧。","notes":[]},{"n":20,"t":"日頭要變為黑暗，月亮要變為血；這都在主大而明顯的日子未到以前。","notes":[]},{"n":21,"t":"到那時候，凡求告主名的，就必得救。","notes":[]},{"n":22,"t":"「以色列人哪，請聽我的話：神藉著拿撒勒人耶穌在你們中間施行異能、奇事、神蹟，將他證明出來，這是你們自己知道的。","notes":[]},{"n":23,"t":"他既按著神的定旨先見被交與人，你們就藉著無法之人的手，把他釘在十字架上，殺了。","notes":[]},{"n":24,"t":"神卻將死的痛苦解釋了，叫他復活，因為他原不能被死拘禁。","notes":[]},{"n":25,"t":"大衛指著他說：我看見主常在我眼前；他在我右邊，叫我不至於搖動。","notes":[]},{"n":26,"t":"所以，我心裏歡喜，我的靈快樂；並且我的肉身要安居在指望中。","notes":["原文是舌"]},{"n":27,"t":"因你必不將我的靈魂撇在陰間，也不叫你的聖者見朽壞。","notes":[]},{"n":28,"t":"你已將生命的道路指示我，必叫我因見你的面得著滿足的快樂。","notes":["或譯：叫我在你面前"]},{"n":29,"t":"「弟兄們！先祖大衛的事，我可以明明地對你們說：他死了，也葬埋了，並且他的墳墓直到今日還在我們這裏。","notes":[]},{"n":30,"t":"大衛既是先知，又曉得神曾向他起誓，要從他的後裔中立一位坐在他的寶座上，","notes":[]},{"n":31,"t":"就預先看明這事，講論基督復活說：他的靈魂不撇在陰間；他的肉身也不見朽壞。","notes":[]},{"n":32,"t":"這耶穌，神已經叫他復活了，我們都為這事作見證。","notes":[]},{"n":33,"t":"他既被神的右手高舉，又從父受了所應許的聖靈，就把你們所看見所聽見的，澆灌下來。","notes":["或譯：他既高舉在神的右邊"]},{"n":34,"t":"大衛並沒有升到天上，但自己說：主對我主說：你坐在我的右邊，","notes":[]},{"n":35,"t":"等我使你仇敵作你的腳凳。","notes":[]},{"n":36,"t":"「故此，以色列全家當確實地知道，你們釘在十字架上的這位耶穌，神已經立他為主，為基督了。」","notes":[]},{"n":37,"t":"眾人聽見這話，覺得扎心，就對彼得和其餘的使徒說：「弟兄們，我們當怎樣行？」","notes":[]},{"n":38,"t":"彼得說：「你們各人要悔改，奉耶穌基督的名受洗，叫你們的罪得赦，就必領受所賜的聖靈；","notes":[]},{"n":39,"t":"因為這應許是給你們和你們的兒女，並一切在遠方的人，就是主－我們神所召來的。」","notes":[]},{"n":40,"t":"彼得還用許多話作見證，勸勉他們說：「你們當救自己脫離這彎曲的世代。」","notes":[]},{"n":41,"t":"於是領受他話的人就受了洗。那一天，門徒約添了三千人，","notes":[]},{"n":42,"t":"都恆心遵守使徒的教訓，彼此交接，擘餅，祈禱。","notes":[]},{"n":43,"t":"眾人都懼怕；使徒又行了許多奇事神蹟。","notes":[],"heads":["在聖徒中間的生活"]},{"n":44,"t":"信的人都在一處，凡物公用，","notes":[]},{"n":45,"t":"並且賣了田產、家業，照各人所需用的分給各人。","notes":[]},{"n":46,"t":"他們天天同心合意恆切地在殿裏，且在家中擘餅，存著歡喜、誠實的心用飯，","notes":[]},{"n":47,"t":"讚美神，得眾民的喜愛。主將得救的人天天加給他們。","notes":[]}]},"3":{"heading":"聖殿門口的瘸腿者得醫治","verses":[{"n":1,"t":"申初禱告的時候，彼得、約翰上聖殿去。","notes":[]},{"n":2,"t":"有一個人，生來是瘸腿的，天天被人抬來，放在殿的一個門口（那門名叫美門），要求進殿的人賙濟。","notes":[]},{"n":3,"t":"他看見彼得、約翰將要進殿，就求他們賙濟。","notes":[]},{"n":4,"t":"彼得、約翰定睛看他；彼得說：「你看我們！」","notes":[]},{"n":5,"t":"那人就留意看他們，指望得著甚麼。","notes":[]},{"n":6,"t":"彼得說：「金銀我都沒有，只把我所有的給你：我奉拿撒勒人耶穌基督的名，叫你起來行走！」","notes":[]},{"n":7,"t":"於是拉著他的右手，扶他起來；他的腳和踝子骨立刻健壯了，","notes":[]},{"n":8,"t":"就跳起來，站著，又行走，同他們進了殿，走著，跳著，讚美神。","notes":[]},{"n":9,"t":"百姓都看見他行走，讚美神；","notes":[]},{"n":10,"t":"認得他是那素常坐在殿的美門口求賙濟的，就因他所遇著的事滿心希奇、驚訝。","notes":[]},{"n":11,"t":"那人正在稱為所羅門的廊下，拉著彼得、約翰；眾百姓一齊跑到他們那裏，很覺希奇。","notes":[],"heads":["彼得在所羅門廊下的講論"]},{"n":12,"t":"彼得看見，就對百姓說：「以色列人哪，為甚麼把這事當作希奇呢？為甚麼定睛看我們，以為我們憑自己的能力和虔誠使這人行走呢？","notes":[]},{"n":13,"t":"亞伯拉罕、以撒、雅各的神，就是我們列祖的神，已經榮耀了他的僕人耶穌；你們卻把他交付彼拉多。彼拉多定意要釋放他，你們竟在彼拉多面前棄絕了他。","notes":["或譯：兒子"]},{"n":14,"t":"你們棄絕了那聖潔公義者，反求著釋放一個兇手給你們。","notes":[]},{"n":15,"t":"你們殺了那生命的主，神卻叫他從死裏復活了；我們都是為這事作見證。","notes":[]},{"n":16,"t":"我們因信他的名，他的名便叫你們所看見所認識的這人健壯了；正是他所賜的信心，叫這人在你們眾人面前全然好了。","notes":[]},{"n":17,"t":"弟兄們，我曉得你們做這事是出於不知，你們的官長也是如此。","notes":[]},{"n":18,"t":"但神曾藉眾先知的口，預言基督將要受害，就這樣應驗了。","notes":[]},{"n":19,"t":"所以，你們當悔改歸正，使你們的罪得以塗抹，","notes":[]},{"n":20,"t":"這樣，那安舒的日子就必從主面前來到；主也必差遣所預定給你們的基督（耶穌）降臨。","notes":[]},{"n":21,"t":"天必留他，等到萬物復興的時候，就是神從創世以來、藉著聖先知的口所說的。","notes":[]},{"n":22,"t":"摩西曾說：『主－神要從你們弟兄中間給你們興起一位先知像我，凡他向你們所說的，你們都要聽從。","notes":[]},{"n":23,"t":"凡不聽從那先知的，必要從民中全然滅絕。』","notes":[]},{"n":24,"t":"從撒母耳以來的眾先知，凡說預言的，也都說到這些日子。","notes":[]},{"n":25,"t":"你們是先知的子孫，也承受神與你們祖宗所立的約，就是對亞伯拉罕說：『地上萬族都要因你的後裔得福。』","notes":[]},{"n":26,"t":"神既興起他的僕人，就先差他到你們這裏來，賜福給你們，叫你們各人回轉，離開罪惡。」","notes":["或譯：兒子"]}]},"4":{"heading":"彼得、約翰在公會被查問","verses":[{"n":1,"t":"使徒對百姓說話的時候，祭司們和守殿官，並撒都該人忽然來了。","notes":[]},{"n":2,"t":"因他們教訓百姓，本著耶穌，傳說死人復活，就很煩惱，","notes":[]},{"n":3,"t":"於是下手拿住他們；因為天已經晚了，就把他們押到第二天。","notes":[]},{"n":4,"t":"但聽道之人有許多信的，男丁數目約到五千。","notes":[]},{"n":5,"t":"第二天，官府、長老，和文士在耶路撒冷聚會，","notes":[]},{"n":6,"t":"又有大祭司亞那和該亞法、約翰、亞歷山大，並大祭司的親族都在那裏，","notes":[]},{"n":7,"t":"叫使徒站在當中，就問他們說：「你們用甚麼能力，奉誰的名做這事呢？」","notes":[]},{"n":8,"t":"那時彼得被聖靈充滿，對他們說：","notes":[]},{"n":9,"t":"「治民的官府和長老啊，倘若今日因為在殘疾人身上所行的善事查問我們他是怎麼得了痊癒，","notes":[]},{"n":10,"t":"你們眾人和以色列百姓都當知道，站在你們面前的這人得痊癒是因你們所釘十字架、神叫他從死裏復活的拿撒勒人耶穌基督的名。","notes":[]},{"n":11,"t":"他是你們匠人所棄的石頭，已成了房角的頭塊石頭。","notes":[]},{"n":12,"t":"除他以外，別無拯救；因為在天下人間，沒有賜下別的名，我們可以靠著得救。」","notes":[]},{"n":13,"t":"他們見彼得、約翰的膽量，又看出他們原是沒有學問的小民，就希奇，認明他們是跟過耶穌的；","notes":[]},{"n":14,"t":"又看見那治好了的人和他們一同站著，就無話可駁。","notes":[]},{"n":15,"t":"於是吩咐他們從公會出去，就彼此商議說：","notes":[]},{"n":16,"t":"「我們當怎樣辦這兩個人呢？因為他們誠然行了一件明顯的神蹟，凡住耶路撒冷的人都知道，我們也不能說沒有。","notes":[]},{"n":17,"t":"惟恐這事越發傳揚在民間，我們必須恐嚇他們，叫他們不再奉這名對人講論。」","notes":[]},{"n":18,"t":"於是叫了他們來，禁止他們總不可奉耶穌的名講論教訓人。","notes":[]},{"n":19,"t":"彼得、約翰說：「聽從你們，不聽從神，這在神面前合理不合理，你們自己酌量吧！","notes":[]},{"n":20,"t":"我們所看見所聽見的，不能不說。」","notes":[]},{"n":21,"t":"官長為百姓的緣故，想不出法子刑罰他們，又恐嚇一番，把他們釋放了。這是因眾人為所行的奇事都歸榮耀與神。","notes":[]},{"n":22,"t":"原來藉著神蹟醫好的那人有四十多歲了。","notes":[]},{"n":23,"t":"二人既被釋放，就到會友那裏去，把祭司長和長老所說的話都告訴他們。","notes":[],"heads":["門徒求主賜膽量"]},{"n":24,"t":"他們聽見了，就同心合意地高聲向神說：「主啊！你是造天、地、海，和其中萬物的，","notes":[]},{"n":25,"t":"你曾藉著聖靈，託你僕人－我們祖宗大衛的口，說：外邦為甚麼爭鬧？萬民為甚麼謀算虛妄的事？","notes":[]},{"n":26,"t":"世上的君王一齊起來，臣宰也聚集，要敵擋主，並主的受膏者。","notes":["或譯：基督"]},{"n":27,"t":"希律和本丟‧彼拉多，外邦人和以色列民，果然在這城裏聚集，要攻打你所膏的聖僕耶穌，","notes":["僕：或譯子"]},{"n":28,"t":"成就你手和你意旨所預定必有的事。","notes":[]},{"n":29,"t":"他們恐嚇我們，現在求主鑒察，一面叫你僕人大放膽量講你的道，一面伸出你的手來醫治疾病，並且使神蹟奇事因著你聖僕耶穌的名行出來。」","notes":["僕：或譯子"],"end":30},{"n":31,"t":"禱告完了，聚會的地方震動，他們就都被聖靈充滿，放膽講論神的道。","notes":[]},{"n":32,"t":"那許多信的人都是一心一意的，沒有一人說他的東西有一樣是自己的，都是大家公用。","notes":[],"heads":["凡物公用"]},{"n":33,"t":"使徒大有能力，見證主耶穌復活；眾人也都蒙大恩。","notes":[]},{"n":34,"t":"內中也沒有一個缺乏的；因為人人將田產房屋都賣了，把所賣的價銀拿來，","notes":[]},{"n":35,"t":"放在使徒腳前，照各人所需用的，分給各人。","notes":[]},{"n":36,"t":"有一個利未人，生在塞浦路斯，名叫約瑟，使徒稱他為巴拿巴（巴拿巴翻出來就是勸慰子）。","notes":[]},{"n":37,"t":"他有田地，也賣了，把價銀拿來，放在使徒腳前。","notes":[]}]},"5":{"heading":"亞拿尼亞和撒非喇","verses":[{"n":1,"t":"有一個人，名叫亞拿尼亞，同他的妻子撒非喇賣了田產，","notes":[]},{"n":2,"t":"把價銀私自留下幾分，他的妻子也知道，其餘的幾分拿來放在使徒腳前。","notes":[]},{"n":3,"t":"彼得說：「亞拿尼亞！為甚麼撒但充滿了你的心，叫你欺哄聖靈，把田地的價銀私自留下幾分呢？","notes":[]},{"n":4,"t":"田地還沒有賣，不是你自己的嗎？既賣了，價銀不是你作主嗎？你怎麼心裏起這意念呢？你不是欺哄人，是欺哄神了。」","notes":[]},{"n":5,"t":"亞拿尼亞聽見這話，就仆倒，斷了氣；聽見的人都甚懼怕。","notes":[]},{"n":6,"t":"有些少年人起來，把他包裹，抬出去埋葬了。","notes":[]},{"n":7,"t":"約過了三小時，他的妻子進來，還不知道這事。","notes":[]},{"n":8,"t":"彼得對她說：「你告訴我，你們賣田地的價銀就是這些嗎？」她說：「就是這些。」","notes":[]},{"n":9,"t":"彼得說：「你們為甚麼同心試探主的靈呢？埋葬你丈夫之人的腳已到門口，他們也要把你抬出去。」","notes":[]},{"n":10,"t":"婦人立刻仆倒在彼得腳前，斷了氣。那些少年人進來，見她已經死了，就抬出去，埋在她丈夫旁邊。","notes":[]},{"n":11,"t":"全教會和聽見這事的人都甚懼怕。","notes":[]},{"n":12,"t":"主藉使徒的手在民間行了許多神蹟奇事；他們都同心合意地在所羅門的廊下。","notes":["或譯：信的人"],"heads":["主藉使徒行了許多神蹟奇事"]},{"n":13,"t":"其餘的人沒有一個敢貼近他們，百姓卻尊重他們。","notes":[]},{"n":14,"t":"信而歸主的人越發增添，連男帶女很多。","notes":[]},{"n":15,"t":"甚至有人將病人抬到街上，放在床上或褥子上，指望彼得過來的時候，或者得他的影兒照在甚麼人身上。","notes":[]},{"n":16,"t":"還有許多人帶著病人和被污鬼纏磨的，從耶路撒冷四圍的城邑來，全都得了醫治。","notes":[]},{"n":17,"t":"大祭司和他的一切同人，就是撒都該教門的人，都起來，滿心忌恨，","notes":[],"heads":["使徒受迫害"]},{"n":18,"t":"就下手拿住使徒，收在外監。","notes":[]},{"n":19,"t":"但主的使者夜間開了監門，領他們出來，","notes":[]},{"n":20,"t":"說：「你們去站在殿裏，把這生命的道都講給百姓聽。」","notes":[]},{"n":21,"t":"使徒聽了這話，天將亮的時候就進殿裏去教訓人。大祭司和他的同人來了，叫齊公會的人和以色列族的眾長老，就差人到監裏去，要把使徒提出來。","notes":[]},{"n":22,"t":"但差役到了，不見他們在監裏，就回來稟報說：","notes":[]},{"n":23,"t":"「我們看見監牢關得極妥當，看守的人也站在門外；及至開了門，裏面一個人都不見。」","notes":[]},{"n":24,"t":"守殿官和祭司長聽見這話，心裏犯難，不知這事將來如何。","notes":[]},{"n":25,"t":"有一個人來稟報說：「你們收在監裏的人，現在站在殿裏教訓百姓。」","notes":[]},{"n":26,"t":"於是守殿官和差役去帶使徒來，並沒有用強暴，因為怕百姓用石頭打他們。","notes":[]},{"n":27,"t":"帶到了，便叫使徒站在公會前；大祭司問他們說：","notes":[]},{"n":28,"t":"「我們不是嚴嚴地禁止你們，不可奉這名教訓人嗎？你們倒把你們的道理充滿了耶路撒冷，想要叫這人的血歸到我們身上！」","notes":[]},{"n":29,"t":"彼得和眾使徒回答說：「順從神，不順從人，是應當的。","notes":[]},{"n":30,"t":"你們掛在木頭上殺害的耶穌，我們祖宗的神已經叫他復活。","notes":[]},{"n":31,"t":"神且用右手將他高舉，叫他作君王，作救主，將悔改的心和赦罪的恩賜給以色列人。","notes":["或譯：他就是神高舉在自己的右邊"]},{"n":32,"t":"我們為這事作見證；神賜給順從之人的聖靈也為這事作見證。」","notes":[]},{"n":33,"t":"公會的人聽見就極其惱怒，想要殺他們。","notes":[]},{"n":34,"t":"但有一個法利賽人，名叫迦瑪列，是眾百姓所敬重的教法師，在公會中站起來，吩咐人把使徒暫且帶到外面去，","notes":[]},{"n":35,"t":"就對眾人說：「以色列人哪，論到這些人，你們應當小心怎樣辦理。","notes":[]},{"n":36,"t":"從前杜達起來，自誇為大，附從他的人約有四百，他被殺後，附從他的全都散了，歸於無有。","notes":[]},{"n":37,"t":"此後，報名上冊的時候，又有加利利的猶大起來，引誘些百姓跟從他；他也滅亡，附從他的人也都四散了。","notes":[]},{"n":38,"t":"現在，我勸你們不要管這些人，任憑他們吧！他們所謀的、所行的，若是出於人，必要敗壞；","notes":[]},{"n":39,"t":"若是出於神，你們就不能敗壞他們，恐怕你們倒是攻擊神了。」","notes":[]},{"n":40,"t":"公會的人聽從了他，便叫使徒來，把他們打了，又吩咐他們不可奉耶穌的名講道，就把他們釋放了。","notes":[]},{"n":41,"t":"他們離開公會，心裏歡喜，因被算是配為這名受辱。","notes":[]},{"n":42,"t":"他們就每日在殿裏、在家裏不住地教訓人，傳耶穌是基督。","notes":[]}]},"6":{"heading":"揀選七人辦理供給的事","verses":[{"n":1,"t":"那時，門徒增多，有說希臘話的猶太人向希伯來人發怨言，因為在天天的供給上忽略了他們的寡婦。","notes":[]},{"n":2,"t":"十二使徒叫眾門徒來，對他們說：「我們撇下神的道去管理飯食，原是不合宜的。","notes":[]},{"n":3,"t":"所以弟兄們，當從你們中間選出七個有好名聲、被聖靈充滿、智慧充足的人，我們就派他們管理這事。","notes":[]},{"n":4,"t":"但我們要專心以祈禱、傳道為事。」","notes":[]},{"n":5,"t":"大眾都喜悅這話，就揀選了司提反，乃是大有信心、聖靈充滿的人，又揀選腓利、伯羅哥羅、尼迦挪、提門、巴米拿，並進猶太教的安提阿人尼哥拉，","notes":[]},{"n":6,"t":"叫他們站在使徒面前。使徒禱告了，就按手在他們頭上。","notes":[]},{"n":7,"t":"神的道興旺起來；在耶路撒冷門徒數目加增的甚多，也有許多祭司信從了這道。","notes":[]},{"n":8,"t":"司提反滿得恩惠、能力，在民間行了大奇事和神蹟。","notes":[],"heads":["司提反被捕"]},{"n":9,"t":"當時有稱利百地拿會堂的幾個人，並有古利奈、亞歷山大、基利家、亞細亞各處會堂的幾個人，都起來和司提反辯論。","notes":[]},{"n":10,"t":"司提反是以智慧和聖靈說話，眾人敵擋不住，","notes":[]},{"n":11,"t":"就買出人來說：「我們聽見他說謗讟摩西和神的話。」","notes":[]},{"n":12,"t":"他們又聳動了百姓、長老，並文士，就忽然來捉拿他，把他帶到公會去，","notes":[]},{"n":13,"t":"設下假見證，說：「這個人說話，不住地糟踐聖所和律法。","notes":[]},{"n":14,"t":"我們曾聽見他說，這拿撒勒人耶穌要毀壞此地，也要改變摩西所交給我們的規條。」","notes":[]},{"n":15,"t":"在公會裏坐著的人都定睛看他，見他的面貌，好像天使的面貌。","notes":[]}]},"7":{"heading":"司提反當眾申訴","verses":[{"n":1,"t":"大祭司就說：「這些事果然有嗎？」","notes":[]},{"n":2,"t":"司提反說：「諸位父兄請聽！當日我們的祖宗亞伯拉罕在美索不達米亞還未住哈蘭的時候，榮耀的神向他顯現，","notes":[]},{"n":3,"t":"對他說：『你要離開本地和親族，往我所要指示你的地方去。』","notes":[]},{"n":4,"t":"他就離開迦勒底人之地，住在哈蘭。他父親死了以後，神使他從那裏搬到你們現在所住之地。","notes":[]},{"n":5,"t":"在這地方，神並沒有給他產業，連立足之地也沒有給他；但應許要將這地賜給他和他的後裔為業；那時他還沒有兒子。","notes":[]},{"n":6,"t":"神說：『他的後裔必寄居外邦，那裏的人要叫他們作奴僕，苦待他們四百年。』","notes":[]},{"n":7,"t":"神又說：『使他們作奴僕的那國，我要懲罰。以後他們要出來，在這地方事奉我。』","notes":[]},{"n":8,"t":"神又賜他割禮的約。於是亞伯拉罕生了以撒，第八日給他行了割禮。以撒生雅各；雅各生十二位先祖。","notes":[]},{"n":9,"t":"「先祖嫉妒約瑟，把他賣到埃及去；神卻與他同在，","notes":[]},{"n":10,"t":"救他脫離一切苦難，又使他在埃及王法老面前得恩典，有智慧。法老就派他作埃及國的宰相兼管全家。","notes":[]},{"n":11,"t":"後來埃及和迦南全地遭遇饑荒，大受艱難，我們的祖宗就絕了糧。","notes":[]},{"n":12,"t":"雅各聽見在埃及有糧，就打發我們的祖宗初次往那裏去。","notes":[]},{"n":13,"t":"第二次約瑟與弟兄們相認，他的親族也被法老知道了。","notes":[]},{"n":14,"t":"約瑟就打發弟兄請父親雅各和全家七十五個人都來。","notes":[]},{"n":15,"t":"於是雅各下了埃及，後來他和我們的祖宗都死在那裏；","notes":[]},{"n":16,"t":"又被帶到示劍，葬於亞伯拉罕在示劍用銀子從哈抹子孫買來的墳墓裏。","notes":[]},{"n":17,"t":"「及至神應許亞伯拉罕的日期將到，以色列民在埃及興盛眾多，","notes":[]},{"n":18,"t":"直到有不曉得約瑟的新王興起。","notes":[]},{"n":19,"t":"他用詭計待我們的宗族，苦害我們的祖宗，叫他們丟棄嬰孩，使嬰孩不能存活。","notes":[]},{"n":20,"t":"那時，摩西生下來，俊美非凡，在他父親家裏撫養了三個月。","notes":[]},{"n":21,"t":"他被丟棄的時候，法老的女兒拾了去，養為自己的兒子。","notes":[]},{"n":22,"t":"摩西學了埃及人一切的學問，說話行事都有才能。","notes":[]},{"n":23,"t":"「他將到四十歲，心中起意去看望他的弟兄以色列人；","notes":[]},{"n":24,"t":"到了那裏，見他們一個人受冤屈，就護庇他，為那受欺壓的人報仇，打死了那埃及人。","notes":[]},{"n":25,"t":"他以為弟兄必明白神是藉他的手搭救他們；他們卻不明白。","notes":[]},{"n":26,"t":"第二天，遇見兩個以色列人爭鬥，就勸他們和睦，說：『你們二位是弟兄，為甚麼彼此欺負呢？』","notes":[]},{"n":27,"t":"那欺負鄰舍的把他推開，說：『誰立你作我們的首領和審判官呢？","notes":[]},{"n":28,"t":"難道你要殺我，像昨天殺那埃及人嗎？』","notes":[]},{"n":29,"t":"摩西聽見這話就逃走了，寄居於米甸；在那裏生了兩個兒子。","notes":[]},{"n":30,"t":"「過了四十年，在西奈山的曠野，有一位天使從荊棘火焰中向摩西顯現。","notes":[]},{"n":31,"t":"摩西見了那異象，便覺希奇，正進前觀看的時候，有主的聲音說：","notes":[]},{"n":32,"t":"『我是你列祖的神，就是亞伯拉罕的神，以撒的神，雅各的神。』摩西戰戰兢兢，不敢觀看。","notes":[]},{"n":33,"t":"主對他說：『把你腳上的鞋脫下來，因為你所站之地是聖地。","notes":[]},{"n":34,"t":"我的百姓在埃及所受的困苦，我實在看見了，他們悲歎的聲音，我也聽見了。我下來要救他們。你來！我要差你往埃及去。』","notes":[]},{"n":35,"t":"這摩西就是百姓棄絕說『誰立你作我們的首領和審判官』的；神卻藉那在荊棘中顯現之使者的手差派他作首領、作救贖的。","notes":[]},{"n":36,"t":"這人領百姓出來，在埃及，在紅海，在曠野，四十年間行了奇事神蹟。","notes":[]},{"n":37,"t":"那曾對以色列人說『神要從你們弟兄中間給你們興起一位先知像我』的，就是這位摩西。","notes":[]},{"n":38,"t":"這人曾在曠野會中和西奈山上，與那對他說話的天使同在，又與我們的祖宗同在，並且領受活潑的聖言傳給我們。","notes":[]},{"n":39,"t":"我們的祖宗不肯聽從，反棄絕他，心裏歸向埃及，","notes":[]},{"n":40,"t":"對亞倫說：『你且為我們造些神像，在我們前面引路；因為領我們出埃及地的那個摩西，我們不知道他遭了甚麼事。』","notes":[]},{"n":41,"t":"那時，他們造了一個牛犢，又拿祭物獻給那像，歡喜自己手中的工作。","notes":[]},{"n":42,"t":"神就轉臉不顧，任憑他們事奉天上的日月星辰，正如先知書上所寫的說：以色列家啊，你們四十年間在曠野，豈是將犧牲和祭物獻給我嗎？","notes":[]},{"n":43,"t":"你們抬著摩洛的帳幕和理番神的星，就是你們所造為要敬拜的像。因此，我要把你們遷到巴比倫外去。","notes":[]},{"n":44,"t":"「我們的祖宗在曠野，有法櫃的帳幕，是神吩咐摩西叫他照所看見的樣式做的。","notes":[]},{"n":45,"t":"這帳幕，我們的祖宗相繼承受。當神在他們面前趕出外邦人去的時候，他們同約書亞把帳幕搬進承受為業之地，直存到大衛的日子。","notes":[]},{"n":46,"t":"大衛在神面前蒙恩，祈求為雅各的神預備居所；","notes":[]},{"n":47,"t":"卻是所羅門為神造成殿宇。","notes":[]},{"n":48,"t":"其實，至高者並不住人手所造的，就如先知所言：","notes":[]},{"n":49,"t":"主說：天是我的座位，地是我的腳凳；你們要為我造何等的殿宇？哪裏是我安息的地方呢？","notes":[]},{"n":50,"t":"這一切不都是我手所造的嗎？","notes":[]},{"n":51,"t":"「你們這硬著頸項、心與耳未受割禮的人，常時抗拒聖靈！你們的祖宗怎樣，你們也怎樣。","notes":[]},{"n":52,"t":"哪一個先知不是你們祖宗逼迫呢？他們也把預先傳說那義者要來的人殺了；如今你們又把那義者賣了，殺了。","notes":[]},{"n":53,"t":"你們受了天使所傳的律法，竟不遵守。」","notes":[]},{"n":54,"t":"眾人聽見這話就極其惱怒，向司提反咬牙切齒。","notes":[],"heads":["眾人用石頭打死司提反"]},{"n":55,"t":"但司提反被聖靈充滿，定睛望天，看見神的榮耀，又看見耶穌站在神的右邊，","notes":[]},{"n":56,"t":"就說：「我看見天開了，人子站在神的右邊。」","notes":[]},{"n":57,"t":"眾人大聲喊叫，摀著耳朵，齊心擁上前去，","notes":[]},{"n":58,"t":"把他推到城外，用石頭打他。作見證的人把衣裳放在一個少年人名叫掃羅的腳前。","notes":[]},{"n":59,"t":"他們正用石頭打的時候，司提反呼籲主說：「求主耶穌接收我的靈魂！」","notes":[]},{"n":60,"t":"又跪下大聲喊著說：「主啊，不要將這罪歸於他們！」說了這話，就睡了。掃羅也喜悅他被害。","notes":[]}]},"8":{"heading":"掃羅逼迫教會","verses":[{"n":1,"t":"從這日起，耶路撒冷的教會大遭逼迫，除了使徒以外，門徒都分散在猶太和撒馬利亞各處。","notes":[]},{"n":2,"t":"有虔誠的人把司提反埋葬了，為他捶胸大哭。","notes":[]},{"n":3,"t":"掃羅卻殘害教會，進各人的家，拉著男女下在監裏。","notes":[]},{"n":4,"t":"那些分散的人往各處去傳道。","notes":[],"heads":["福音傳到撒馬利亞"]},{"n":5,"t":"腓利下撒馬利亞城去，宣講基督。","notes":[]},{"n":6,"t":"眾人聽見了，又看見腓利所行的神蹟，就同心合意地聽從他的話。","notes":[]},{"n":7,"t":"因為有許多人被污鬼附著，那些鬼大聲呼叫，從他們身上出來；還有許多癱瘓的、瘸腿的，都得了醫治。","notes":[]},{"n":8,"t":"在那城裏，就大有歡喜。","notes":[]},{"n":9,"t":"有一個人，名叫西門，向來在那城裏行邪術，妄自尊大，使撒馬利亞的百姓驚奇；","notes":[]},{"n":10,"t":"無論大小都聽從他，說：「這人就是那稱為神的大能者。」","notes":[]},{"n":11,"t":"他們聽從他，因他久用邪術，使他們驚奇。","notes":[]},{"n":12,"t":"及至他們信了腓利所傳神國的福音和耶穌基督的名，連男帶女就受了洗。","notes":[]},{"n":13,"t":"西門自己也信了；既受了洗，就常與腓利在一處，看見他所行的神蹟和大異能，就甚驚奇。","notes":[]},{"n":14,"t":"使徒在耶路撒冷聽見撒馬利亞人領受了神的道，就打發彼得、約翰往他們那裏去。","notes":[]},{"n":15,"t":"兩個人到了，就為他們禱告，要叫他們受聖靈。","notes":[]},{"n":16,"t":"因為聖靈還沒有降在他們一個人身上，他們只奉主耶穌的名受了洗。","notes":[]},{"n":17,"t":"於是使徒按手在他們頭上，他們就受了聖靈。","notes":[]},{"n":18,"t":"西門看見使徒按手，便有聖靈賜下，就拿錢給使徒，","notes":[]},{"n":19,"t":"說：「把這權柄也給我，叫我手按著誰，誰就可以受聖靈。」","notes":[]},{"n":20,"t":"彼得說：「你的銀子和你一同滅亡吧！因你想神的恩賜是可以用錢買的。","notes":[]},{"n":21,"t":"你在這道上無分無關；因為在神面前，你的心不正。","notes":[]},{"n":22,"t":"你當懊悔你這罪惡，祈求主，或者你心裏的意念可得赦免。","notes":[]},{"n":23,"t":"我看出你正在苦膽之中，被罪惡捆綁。」","notes":[]},{"n":24,"t":"西門說：「願你們為我求主，叫你們所說的，沒有一樣臨到我身上。」","notes":[]},{"n":25,"t":"使徒既證明主道，而且傳講，就回耶路撒冷去，一路在撒馬利亞好些村莊傳揚福音。","notes":[]},{"n":26,"t":"有主的一個使者對腓利說：「起來！向南走，往那從耶路撒冷下迦薩的路上去。」那路是曠野。","notes":[],"heads":["腓利和衣索匹亞的太監"]},{"n":27,"t":"腓利就起身去了，不料，有一個衣索匹亞人，是個有大權的太監，在衣索匹亞女王甘大基的手下總管銀庫，他上耶路撒冷禮拜去了。","notes":["就是古實，見以賽亞十八章一節"]},{"n":28,"t":"現在回來，在車上坐著，念先知以賽亞的書。","notes":[]},{"n":29,"t":"聖靈對腓利說：「你去！貼近那車走。」","notes":[]},{"n":30,"t":"腓利就跑到太監那裏，聽見他念先知以賽亞的書，便問他說：「你所念的，你明白嗎？」","notes":[]},{"n":31,"t":"他說：「沒有人指教我，怎能明白呢？」於是請腓利上車，與他同坐。","notes":[]},{"n":32,"t":"他所念的那段經，說：他像羊被牽到宰殺之地，又像羊羔在剪毛的人手下無聲；他也是這樣不開口。","notes":[]},{"n":33,"t":"他卑微的時候，人不按公義審判他；誰能述說他的世代？因為他的生命從地上奪去。","notes":["原文是他的審判被奪去"]},{"n":34,"t":"太監對腓利說：「請問，先知說這話是指著誰？是指著自己呢？是指著別人呢？」","notes":[]},{"n":35,"t":"腓利就開口從這經上起，對他傳講耶穌。","notes":[]},{"n":36,"t":"二人正往前走，到了有水的地方，太監說：「看哪，這裏有水，我受洗有甚麼妨礙呢？」","notes":["有古卷加：37腓利說：「你若是一心相信，就可以。」他回答說：「我信耶穌基督是神的兒子。」"]},{"n":38,"t":"於是吩咐車站住，腓利和太監二人同下水裏去，腓利就給他施洗。","notes":[]},{"n":39,"t":"從水裏上來，主的靈把腓利提了去，太監也不再見他了，就歡歡喜喜地走路。","notes":[]},{"n":40,"t":"後來有人在亞鎖都遇見腓利；他走遍那地方，在各城宣傳福音，直到凱撒利亞。","notes":[]}]},"9":{"heading":"掃羅的轉變","verses":[{"n":1,"t":"掃羅仍然向主的門徒口吐威嚇凶煞的話，去見大祭司，","notes":[]},{"n":2,"t":"求文書給大馬士革的各會堂，若是找著信奉這道的人，無論男女，都准他捆綁帶到耶路撒冷。","notes":[]},{"n":3,"t":"掃羅行路，將到大馬士革，忽然從天上發光，四面照著他；","notes":[]},{"n":4,"t":"他就仆倒在地，聽見有聲音對他說：「掃羅！掃羅！你為甚麼逼迫我？」","notes":[]},{"n":5,"t":"他說：「主啊！你是誰？」主說：「我就是你所逼迫的耶穌。","notes":[]},{"n":6,"t":"起來！進城去，你所當做的事，必有人告訴你。」","notes":[]},{"n":7,"t":"同行的人站在那裏，說不出話來，聽見聲音，卻看不見人。","notes":[]},{"n":8,"t":"掃羅從地上起來，睜開眼睛，竟不能看見甚麼。有人拉他的手，領他進了大馬士革；","notes":[]},{"n":9,"t":"三日不能看見，也不吃也不喝。","notes":[]},{"n":10,"t":"當下，在大馬士革有一個門徒，名叫亞拿尼亞。主在異象中對他說：「亞拿尼亞。」他說：「主，我在這裏。」","notes":[]},{"n":11,"t":"主對他說：「起來！往直街去，在猶大的家裏，訪問一個大數人，名叫掃羅。他正禱告，","notes":[]},{"n":12,"t":"又看見了一個人，名叫亞拿尼亞，進來按手在他身上，叫他能看見。」","notes":[]},{"n":13,"t":"亞拿尼亞回答說：「主啊，我聽見許多人說，這人怎樣在耶路撒冷多多苦害你的聖徒，","notes":[]},{"n":14,"t":"並且他在這裏有從祭司長得來的權柄捆綁一切求告你名的人。」","notes":[]},{"n":15,"t":"主對亞拿尼亞說：「你只管去！他是我所揀選的器皿，要在外邦人和君王，並以色列人面前宣揚我的名。","notes":[]},{"n":16,"t":"我也要指示他，為我的名必須受許多的苦難。」","notes":[]},{"n":17,"t":"亞拿尼亞就去了，進入那家，把手按在掃羅身上，說：「兄弟掃羅，在你來的路上向你顯現的主，就是耶穌，打發我來，叫你能看見，又被聖靈充滿。」","notes":[]},{"n":18,"t":"掃羅的眼睛上，好像有鱗立刻掉下來，他就能看見。於是起來受了洗；","notes":[]},{"n":19,"t":"吃過飯就健壯了。掃羅和大馬士革的門徒同住了些日子，","notes":[]},{"n":20,"t":"就在各會堂裏宣傳耶穌，說他是神的兒子。","notes":[]},{"n":21,"t":"凡聽見的人都驚奇，說：「在耶路撒冷殘害求告這名的，不是這人嗎？並且他到這裏來，特要捆綁他們，帶到祭司長那裏。」","notes":[]},{"n":22,"t":"但掃羅越發有能力，駁倒住大馬士革的猶太人，證明耶穌是基督。","notes":[]},{"n":23,"t":"過了好些日子，猶太人商議要殺掃羅，","notes":[],"heads":["未受猶太人的謀害"]},{"n":24,"t":"但他們的計謀被掃羅知道了。他們又晝夜在城門守候，要殺他。","notes":[]},{"n":25,"t":"他的門徒就在夜間用筐子把他從城牆上縋下去。","notes":[]},{"n":26,"t":"掃羅到了耶路撒冷，想與門徒結交，他們卻都怕他，不信他是門徒。","notes":[],"heads":["掃羅在耶路撒冷"]},{"n":27,"t":"惟有巴拿巴接待他，領去見使徒，把他在路上怎麼看見主，主怎麼向他說話，他在大馬士革怎麼奉耶穌的名放膽傳道，都述說出來。","notes":[]},{"n":28,"t":"於是掃羅在耶路撒冷和門徒出入來往，","notes":[]},{"n":29,"t":"奉主的名放膽傳道，並與說希臘話的猶太人講論辯駁；他們卻想法子要殺他。","notes":[]},{"n":30,"t":"弟兄們知道了就送他下凱撒利亞，打發他往大數去。","notes":[]},{"n":31,"t":"那時，猶太、加利利、撒馬利亞各處的教會都得平安，被建立；凡事敬畏主，蒙聖靈的安慰，人數就增多了。","notes":[]},{"n":32,"t":"彼得周流四方的時候，也到了居住呂大的聖徒那裏；","notes":[],"heads":["以尼雅得醫治"]},{"n":33,"t":"遇見一個人，名叫以尼雅，得了癱瘓，在褥子上躺臥八年。","notes":[]},{"n":34,"t":"彼得對他說：「以尼雅，耶穌基督醫好你了， 起來！收拾你的褥子。」他就立刻起來了。","notes":[]},{"n":35,"t":"凡住呂大和沙崙的人都看見了他，就歸服主。","notes":[]},{"n":36,"t":"在約帕有一個女徒，名叫大比大，翻希臘話就是多加；她廣行善事，多施賙濟。","notes":["就是羚羊的意思"],"heads":["多加復活"]},{"n":37,"t":"當時，她患病而死，有人把她洗了，停在樓上。","notes":[]},{"n":38,"t":"呂大原與約帕相近；門徒聽見彼得在那裏，就打發兩個人去見他，央求他說：「快到我們那裏去，不要耽延。」","notes":[]},{"n":39,"t":"彼得就起身和他們同去；到了，便有人領他上樓。眾寡婦都站在彼得旁邊哭，拿多加與她們同在時所做的裏衣外衣給他看。","notes":[]},{"n":40,"t":"彼得叫她們都出去，就跪下禱告，轉身對著死人說：「大比大，起來！」她就睜開眼睛，見了彼得，便坐起來。","notes":[]},{"n":41,"t":"彼得伸手扶她起來，叫眾聖徒和寡婦進去，把多加活活地交給他們。","notes":[]},{"n":42,"t":"這事傳遍了約帕，就有許多人信了主。","notes":[]},{"n":43,"t":"此後，彼得在約帕一個硝皮匠西門的家裏住了多日。","notes":[]}]},"10":{"heading":"彼得和哥尼流","verses":[{"n":1,"t":"在凱撒利亞有一個人，名叫哥尼流，是「意大利營」的百夫長。","notes":[]},{"n":2,"t":"他是個虔誠人，他和全家都敬畏神，多多賙濟百姓，常常禱告神。","notes":[]},{"n":3,"t":"有一天，約在申初，他在異象中明明看見神的一個使者進去，到他那裏，說：「哥尼流。」","notes":[]},{"n":4,"t":"哥尼流定睛看他，驚怕說：「主啊，甚麼事呢？」天使說：「你的禱告和你的賙濟達到神面前，已蒙記念了。","notes":[]},{"n":5,"t":"現在你當打發人往約帕去，請那稱呼彼得的西門來。","notes":[]},{"n":6,"t":"他住在海邊一個硝皮匠西門的家裏，房子在海邊上。」","notes":[]},{"n":7,"t":"向他說話的天使去後，哥尼流叫了兩個家人和常伺候他的一個虔誠兵來，","notes":[]},{"n":8,"t":"把這事都述說給他們聽，就打發他們往約帕去。","notes":[]},{"n":9,"t":"第二天，他們行路將近那城。彼得約在午正，上房頂去禱告，","notes":[]},{"n":10,"t":"覺得餓了，想要吃。那家的人正預備飯的時候，彼得魂遊象外，","notes":[]},{"n":11,"t":"看見天開了，有一物降下，好像一塊大布，繫著四角，縋在地上，","notes":[]},{"n":12,"t":"裏面有地上各樣四足的走獸和昆蟲，並天上的飛鳥；","notes":[]},{"n":13,"t":"又有聲音向他說：「彼得，起來，宰了吃！」","notes":[]},{"n":14,"t":"彼得卻說：「主啊，這是不可的！凡俗物和不潔淨的物，我從來沒有吃過。」","notes":[]},{"n":15,"t":"第二次有聲音向他說：「神所潔淨的，你不可當作俗物。」","notes":[]},{"n":16,"t":"這樣一連三次，那物隨即收回天上去了。","notes":[]},{"n":17,"t":"彼得心裏正在猜疑之間，不知所看見的異象是甚麼意思。哥尼流所差來的人已經訪問到西門的家，站在門外，","notes":[]},{"n":18,"t":"喊著問：「有稱呼彼得的西門住在這裏沒有？」","notes":[]},{"n":19,"t":"彼得還思想那異象的時候，聖靈向他說：「有三個人來找你。","notes":[]},{"n":20,"t":"起來，下去，和他們同往，不要疑惑，因為是我差他們來的。」","notes":[]},{"n":21,"t":"於是彼得下去見那些人，說：「我就是你們所找的人。你們來是為甚麼緣故？」","notes":[]},{"n":22,"t":"他們說：「百夫長哥尼流是個義人，敬畏神，為猶太通國所稱讚。他蒙一位聖天使指示，叫他請你到他家裏去，聽你的話。」","notes":[]},{"n":23,"t":"彼得就請他們進去，住了一宿。次日，起身和他們同去，還有約帕的幾個弟兄同著他去；","notes":[]},{"n":24,"t":"又次日，他們進入凱撒利亞，哥尼流已經請了他的親屬密友等候他們。","notes":[]},{"n":25,"t":"彼得一進去，哥尼流就迎接他，俯伏在他腳前拜他。","notes":[]},{"n":26,"t":"彼得卻拉他，說：「你起來，我也是人。」","notes":[]},{"n":27,"t":"彼得和他說著話進去，見有好些人在那裏聚集，","notes":[]},{"n":28,"t":"就對他們說：「你們知道，猶太人和別國的人親近來往本是不合例的，但神已經指示我，無論甚麼人都不可看作俗而不潔淨的。","notes":[]},{"n":29,"t":"所以我被請的時候，就不推辭而來。現在請問：你們叫我來有甚麼意思呢？」","notes":[]},{"n":30,"t":"哥尼流說：「前四天，這個時候，我在家中守著申初的禱告，忽然有一個人穿著光明的衣裳，站在我面前，","notes":[]},{"n":31,"t":"說：『哥尼流，你的禱告已蒙垂聽，你的賙濟達到神面前已蒙記念了。","notes":[]},{"n":32,"t":"你當打發人往約帕去，請那稱呼彼得的西門來，他住在海邊一個硝皮匠西門的家裏。』","notes":[]},{"n":33,"t":"所以我立時打發人去請你。你來了很好；現今我們都在神面前，要聽主所吩咐你的一切話。」","notes":[]},{"n":34,"t":"彼得就開口說：「我真看出神是不偏待人。","notes":[],"heads":["在哥尼流家中講道"]},{"n":35,"t":"原來，各國中那敬畏主、行義的人都為主所悅納。","notes":[]},{"n":36,"t":"神藉著耶穌基督（他是萬有的主）傳和平的福音，將這道賜給以色列人。","notes":[]},{"n":37,"t":"這話在約翰宣傳洗禮以後，從加利利起，傳遍了猶太。","notes":[]},{"n":38,"t":"神怎樣以聖靈和能力膏拿撒勒人耶穌，這都是你們知道的。他周流四方，行善事，醫好凡被魔鬼壓制的人，因為神與他同在。","notes":[]},{"n":39,"t":"他在猶太人之地，並耶路撒冷所行的一切事，有我們作見證。他們竟把他掛在木頭上殺了。","notes":[]},{"n":40,"t":"第三日，神叫他復活，顯現出來；","notes":[]},{"n":41,"t":"不是顯現給眾人看，乃是顯現給神預先所揀選為他作見證的人看，就是我們這些在他從死裏復活以後和他同吃同喝的人。","notes":[]},{"n":42,"t":"他吩咐我們傳道給眾人，證明他是神所立定的，要作審判活人、死人的主。","notes":[]},{"n":43,"t":"眾先知也為他作見證說：『凡信他的人必因他的名得蒙赦罪。』」","notes":[]},{"n":44,"t":"彼得還說這話的時候，聖靈降在一切聽道的人身上。","notes":[],"heads":["外邦人領受聖靈"]},{"n":45,"t":"那些奉割禮、和彼得同來的信徒，見聖靈的恩賜也澆在外邦人身上，就都希奇；","notes":[]},{"n":46,"t":"因聽見他們說方言，稱讚神為大。","notes":[]},{"n":47,"t":"於是彼得說：「這些人既受了聖靈，與我們一樣，誰能禁止用水給他們施洗呢？」","notes":[]},{"n":48,"t":"就吩咐奉耶穌基督的名給他們施洗。他們又請彼得住了幾天。","notes":[]}]},"11":{"heading":"向耶路撒冷教會報告","verses":[{"n":1,"t":"使徒和在猶太的眾弟兄聽說外邦人也領受了神的道。","notes":[]},{"n":2,"t":"及至彼得上了耶路撒冷，那些奉割禮的門徒和他爭辯說：","notes":[]},{"n":3,"t":"「你進入未受割禮之人的家和他們一同吃飯了。」","notes":[]},{"n":4,"t":"彼得就開口把這事挨次給他們講解說：","notes":[]},{"n":5,"t":"「我在約帕城裏禱告的時候，魂遊象外，看見異象，有一物降下，好像一塊大布，繫著四角，從天縋下，直來到我跟前。","notes":[]},{"n":6,"t":"我定睛觀看，見內中有地上四足的牲畜和野獸、昆蟲，並天上的飛鳥。","notes":[]},{"n":7,"t":"我且聽見有聲音向我說：『彼得，起來，宰了吃！』","notes":[]},{"n":8,"t":"我說：『主啊，這是不可的！凡俗而不潔淨的物從來沒有入過我的口。』","notes":[]},{"n":9,"t":"第二次，有聲音從天上說：『神所潔淨的，你不可當作俗物。』","notes":[]},{"n":10,"t":"這樣一連三次，就都收回天上去了。","notes":[]},{"n":11,"t":"正當那時，有三個人站在我們所住的房門前，是從凱撒利亞差來見我的。","notes":[]},{"n":12,"t":"聖靈吩咐我和他們同去，不要疑惑。同著我去的，還有這六位弟兄，我們都進了那人的家。","notes":["或譯：不要分別等類"]},{"n":13,"t":"那人就告訴我們，他如何看見一位天使站在他屋裏，說：『你打發人往約帕去，請那稱呼彼得的西門來，","notes":[]},{"n":14,"t":"他有話告訴你，可以叫你和你的全家得救。』","notes":[]},{"n":15,"t":"我一開講，聖靈便降在他們身上，正像當初降在我們身上一樣。","notes":[]},{"n":16,"t":"我就想起主的話說：『約翰是用水施洗，但你們要受聖靈的洗。』","notes":[]},{"n":17,"t":"神既然給他們恩賜，像在我們信主耶穌基督的時候給了我們一樣；我是誰，能攔阻神呢？」","notes":[]},{"n":18,"t":"眾人聽見這話，就不言語了，只歸榮耀與神，說：「這樣看來，神也賜恩給外邦人，叫他們悔改得生命了。」","notes":[]},{"n":19,"t":"那些因司提反的事遭患難四散的門徒直走到腓尼基和塞浦路斯，並安提阿；他們不向別人講道，只向猶太人講。","notes":[],"heads":["安提阿的教會"]},{"n":20,"t":"但內中有塞浦路斯和古利奈人，他們到了安提阿也向希臘人傳講主耶穌。","notes":["有古卷：也向說希臘話的猶太人傳講主耶穌"]},{"n":21,"t":"主與他們同在，信而歸主的人就很多了。","notes":[]},{"n":22,"t":"這風聲傳到耶路撒冷教會人的耳中，他們就打發巴拿巴出去，走到安提阿為止。","notes":[]},{"n":23,"t":"他到了那裏，看見神所賜的恩就歡喜，勸勉眾人，立定心志，恆久靠主。","notes":[]},{"n":24,"t":"這巴拿巴原是個好人，被聖靈充滿，大有信心。於是有許多人歸服了主。","notes":[]},{"n":25,"t":"他又往大數去找掃羅，","notes":[]},{"n":26,"t":"找著了，就帶他到安提阿去。他們足有一年的工夫和教會一同聚集，教訓了許多人。門徒稱為「基督徒」是從安提阿起首。","notes":[]},{"n":27,"t":"當那些日子，有幾位先知從耶路撒冷下到安提阿。","notes":[]},{"n":28,"t":"內中有一位，名叫亞迦布，站起來，藉著聖靈指明天下將有大饑荒。（這事到克勞第年間果然有了。）","notes":[]},{"n":29,"t":"於是門徒定意照各人的力量捐錢，送去供給住在猶太的弟兄。","notes":[]},{"n":30,"t":"他們就這樣行，把捐項託巴拿巴和掃羅送到眾長老那裏。","notes":[]}]},"12":{"heading":"雅各被殺，彼得被囚","verses":[{"n":1,"t":"那時，希律王下手苦害教會中幾個人，","notes":[]},{"n":2,"t":"用刀殺了約翰的哥哥雅各。","notes":[]},{"n":3,"t":"他見猶太人喜歡這事，又去捉拿彼得。那時正是除酵的日子。","notes":[]},{"n":4,"t":"希律拿了彼得，收在監裏，交付四班兵丁看守，每班四個人，意思要在逾越節後把他提出來，當著百姓辦他。","notes":[]},{"n":5,"t":"於是彼得被囚在監裏；教會卻為他切切地禱告神。","notes":[]},{"n":6,"t":"希律將要提他出來的前一夜，彼得被兩條鐵鍊鎖著，睡在兩個兵丁當中；看守的人也在門外看守。","notes":[],"heads":["彼得獲救出獄"]},{"n":7,"t":"忽然，有主的一個使者站在旁邊，屋裏有光照耀，天使拍彼得的肋旁，拍醒了他，說：「快快起來！」那鐵鍊就從他手上脫落下來。","notes":[]},{"n":8,"t":"天使對他說：「束上帶子，穿上鞋。」他就那樣做。天使又說：「披上外衣，跟著我來。」","notes":[]},{"n":9,"t":"彼得就出來跟著他，不知道天使所做是真的，只當見了異象。","notes":[]},{"n":10,"t":"過了第一層第二層監牢，就來到臨街的鐵門，那門自己開了。他們出來，走過一條街，天使便離開他去了。","notes":[]},{"n":11,"t":"彼得醒悟過來，說：「我現在真知道主差遣他的使者，救我脫離希律的手和猶太百姓一切所盼望的。」","notes":[]},{"n":12,"t":"想了一想，就往那稱呼馬可的約翰、他母親馬利亞家去，在那裏有好些人聚集禱告。","notes":[]},{"n":13,"t":"彼得敲外門，有一個使女，名叫羅大，出來探聽，","notes":[]},{"n":14,"t":"聽得是彼得的聲音，就歡喜的顧不得開門，跑進去告訴眾人說：「彼得站在門外。」","notes":[]},{"n":15,"t":"他們說：「你是瘋了！」使女極力地說：「真是他！」他們說：「必是他的天使！」","notes":[]},{"n":16,"t":"彼得不住地敲門。他們開了門，看見他，就甚驚奇。","notes":[]},{"n":17,"t":"彼得擺手，不要他們作聲，就告訴他們主怎樣領他出監；又說：「你們把這事告訴雅各和眾弟兄。」於是出去，往別處去了。","notes":[]},{"n":18,"t":"到了天亮，兵丁擾亂得很，不知道彼得往哪裏去了。","notes":[]},{"n":19,"t":"希律找他，找不著，就審問看守的人，吩咐把他們拉去殺了。後來希律離開猶太，下凱撒利亞去，住在那裏。","notes":[]},{"n":20,"t":"希律惱怒泰爾、西頓的人。他們那一帶地方是從王的地土得糧，因此就託了王的內侍臣伯拉斯都的情，一心來求和。","notes":[],"heads":["希律的死"]},{"n":21,"t":"希律在所定的日子，穿上朝服，坐在位上，對他們講論一番。","notes":[]},{"n":22,"t":"百姓喊著說：「這是神的聲音，不是人的聲音。」","notes":[]},{"n":23,"t":"希律不歸榮耀給神，所以主的使者立刻罰他，他被蟲所咬，氣就絕了。","notes":[]},{"n":24,"t":"神的道日見興旺，越發廣傳。","notes":[]},{"n":25,"t":"巴拿巴和掃羅辦完了他們供給的事，就從耶路撒冷回來，帶著稱呼馬可的約翰同去。","notes":[]}]},"13":{"heading":"巴拿巴和掃羅奉差遣","verses":[{"n":1,"t":"在安提阿的教會中，有幾位先知和教師，就是巴拿巴和稱呼尼結的西面、古利奈人路求，與分封之王希律同養的馬念，並掃羅。","notes":[]},{"n":2,"t":"他們事奉主、禁食的時候，聖靈說：「要為我分派巴拿巴和掃羅，去做我召他們所做的工。」","notes":[]},{"n":3,"t":"於是禁食禱告，按手在他們頭上，就打發他們去了。","notes":[]},{"n":4,"t":"他們既被聖靈差遣，就下到西流基，從那裏坐船往塞浦路斯去。","notes":[],"heads":["在塞浦路斯傳道"]},{"n":5,"t":"到了撒拉米，就在猶太人各會堂裏傳講神的道，也有約翰作他們的幫手。","notes":[]},{"n":6,"t":"經過全島，直到帕弗，在那裏遇見一個有法術、假充先知的猶太人，名叫巴‧耶穌。","notes":[]},{"n":7,"t":"這人常和方伯士求‧保羅同在。士求‧保羅是個通達人，他請了巴拿巴和掃羅來，要聽神的道。","notes":[]},{"n":8,"t":"只是那行法術的以呂馬（這名翻出來就是行法術的意思）敵擋使徒，要叫方伯不信真道。","notes":[]},{"n":9,"t":"掃羅又名保羅，被聖靈充滿，定睛看他，","notes":[]},{"n":10,"t":"說：「你這充滿各樣詭詐奸惡，魔鬼的兒子，眾善的仇敵，你混亂主的正道還不止住嗎？","notes":[]},{"n":11,"t":"現在主的手加在你身上，你要瞎眼，暫且不見日光。」他的眼睛立刻昏蒙黑暗，四下裏求人拉著手領他。","notes":[]},{"n":12,"t":"方伯看見所做的事，很希奇主的道，就信了。","notes":[]},{"n":13,"t":"保羅和他的同人從帕弗開船，來到旁非利亞的別加，約翰就離開他們，回耶路撒冷去。","notes":[],"heads":["在彼西底的安提阿傳道"]},{"n":14,"t":"他們離了別加往前行，來到彼西底的安提阿，在安息日進會堂坐下。","notes":[]},{"n":15,"t":"讀完了律法和先知的書，管會堂的叫人過去，對他們說：「二位兄台，若有甚麼勸勉眾人的話，請說。」","notes":[]},{"n":16,"t":"保羅就站起來，舉手，說：「以色列人和一切敬畏神的人，請聽。","notes":[]},{"n":17,"t":"這以色列民的神揀選了我們的祖宗，當民寄居埃及的時候抬舉他們，用大能的手領他們出來；","notes":[]},{"n":18,"t":"又在曠野容忍他們，約有四十年。","notes":["或譯：撫養"]},{"n":19,"t":"既滅了迦南地七族的人，就把那地分給他們為業；","notes":[]},{"n":20,"t":"此後給他們設立士師，約有四百五十年，直到先知撒母耳的時候。","notes":[]},{"n":21,"t":"後來他們求一個王，神就將便雅憫支派中基士的兒子掃羅，給他們作王四十年。","notes":[]},{"n":22,"t":"既廢了掃羅，就選立大衛作他們的王，又為他作見證說：『我尋得耶西的兒子大衛，他是合我心意的人，凡事要遵行我的旨意。』","notes":[]},{"n":23,"t":"從這人的後裔中，神已經照著所應許的，為以色列人立了一位救主，就是耶穌。","notes":[]},{"n":24,"t":"在他沒有出來以先，約翰向以色列眾民宣講悔改的洗禮。","notes":[]},{"n":25,"t":"約翰將行盡他的程途說：『你們以為我是誰？我不是基督；只是有一位在我以後來的，我解他腳上的鞋帶也是不配的。』","notes":[]},{"n":26,"t":"「弟兄們，亞伯拉罕的子孫和你們中間敬畏神的人哪，這救世的道是傳給我們的。","notes":[]},{"n":27,"t":"耶路撒冷居住的人和他們的官長，因為不認識基督，也不明白每安息日所讀眾先知的書，就把基督定了死罪，正應了先知的預言；","notes":[]},{"n":28,"t":"雖然查不出他有當死的罪來，還是求彼拉多殺他；","notes":[]},{"n":29,"t":"既成就了經上指著他所記的一切話，就把他從木頭上取下來，放在墳墓裏。","notes":[]},{"n":30,"t":"神卻叫他從死裏復活。","notes":[]},{"n":31,"t":"那從加利利同他上耶路撒冷的人多日看見他，這些人如今在民間是他的見證。","notes":[]},{"n":32,"t":"我們也報好信息給你們，就是那應許祖宗的話，","notes":[]},{"n":33,"t":"神已經向我們這作兒女的應驗，叫耶穌復活了。正如詩篇第二篇上記著說：你是我的兒子，我今日生你。","notes":[]},{"n":34,"t":"論到神叫他從死裏復活，不再歸於朽壞，就這樣說：我必將所應許大衛那聖潔、可靠的恩典賜給你們。","notes":[]},{"n":35,"t":"又有一篇上說：你必不叫你的聖者見朽壞。","notes":[]},{"n":36,"t":"「大衛在世的時候遵行了神的旨意，就睡了，歸到他祖宗那裏，已見朽壞；","notes":["或譯：大衛按神的旨意服事了他那一世的人，就睡了"]},{"n":37,"t":"惟獨神所復活的，他並未見朽壞。","notes":[]},{"n":38,"t":"所以，弟兄們，你們當曉得：赦罪的道是由這人傳給你們的。","notes":[]},{"n":39,"t":"你們靠摩西的律法，在一切不得稱義的事上信靠這人，就都得稱義了。","notes":[]},{"n":40,"t":"所以，你們務要小心，免得先知書上所說的臨到你們。","notes":[]},{"n":41,"t":"主說：你們這輕慢的人要觀看，要驚奇，要滅亡；因為在你們的時候，我行一件事，雖有人告訴你們，你們總是不信。」","notes":[]},{"n":42,"t":"他們出會堂的時候，眾人請他們到下安息日再講這話給他們聽。","notes":[]},{"n":43,"t":"散會以後，猶太人和敬虔進猶太教的人多有跟從保羅、巴拿巴的。二人對他們講道，勸他們務要恆久在神的恩中。","notes":[]},{"n":44,"t":"到下安息日，合城的人幾乎都來聚集，要聽神的道。","notes":[]},{"n":45,"t":"但猶太人看見人這樣多，就滿心嫉妒，硬駁保羅所說的話，並且毀謗。","notes":[]},{"n":46,"t":"保羅和巴拿巴放膽說：「神的道先講給你們原是應當的；只因你們棄絕這道，斷定自己不配得永生，我們就轉向外邦人去。","notes":[]},{"n":47,"t":"因為主曾這樣吩咐我們說：我已經立你作外邦人的光，叫你施行救恩，直到地極。」","notes":[]},{"n":48,"t":"外邦人聽見這話，就歡喜了，讚美神的道；凡預定得永生的人都信了。","notes":[]},{"n":49,"t":"於是主的道傳遍了那一帶地方。","notes":[]},{"n":50,"t":"但猶太人挑唆虔敬、尊貴的婦女和城內有名望的人，逼迫保羅、巴拿巴，將他們趕出境外。","notes":[]},{"n":51,"t":"二人對著眾人跺下腳上的塵土，就往以哥念去了。","notes":[]},{"n":52,"t":"門徒滿心喜樂，又被聖靈充滿。","notes":[]}]},"14":{"heading":"在以哥念傳道","verses":[{"n":1,"t":"二人在以哥念同進猶太人的會堂，在那裏講的，叫猶太人和希臘人信的很多。","notes":[]},{"n":2,"t":"但那不順從的猶太人聳動外邦人，叫他們心裏惱恨弟兄。","notes":[]},{"n":3,"t":"二人在那裏住了多日，倚靠主放膽講道，主藉他們的手施行神蹟奇事，證明他的恩道。","notes":[]},{"n":4,"t":"城裏的眾人就分了黨，有附從猶太人的，有附從使徒的。","notes":[]},{"n":5,"t":"那時，外邦人和猶太人，並他們的官長，一齊擁上來，要凌辱使徒，用石頭打他們。","notes":[]},{"n":6,"t":"使徒知道了，就逃往呂高尼的路司得、特庇兩個城和周圍地方去，","notes":[]},{"n":7,"t":"在那裏傳福音。","notes":[]},{"n":8,"t":"路司得城裏坐著一個兩腳無力的人，生來是瘸腿的，從來沒有走過。","notes":[],"heads":["在路司得傳道"]},{"n":9,"t":"他聽保羅講道，保羅定睛看他，見他有信心，可得痊癒，","notes":[]},{"n":10,"t":"就大聲說：「你起來，兩腳站直！」那人就跳起來，而且行走。","notes":[]},{"n":11,"t":"眾人看見保羅所做的事，就用呂高尼的話大聲說：「有神藉著人形降臨在我們中間了。」","notes":[]},{"n":12,"t":"於是稱巴拿巴為宙斯，稱保羅為希耳米，因為他說話領首。","notes":[]},{"n":13,"t":"有城外宙斯廟的祭司牽著牛，拿著花圈，來到門前，要同眾人向使徒獻祭。","notes":[]},{"n":14,"t":"巴拿巴、保羅二使徒聽見，就撕開衣裳，跳進眾人中間，喊著說：","notes":[]},{"n":15,"t":"「諸君，為甚麼做這事呢？我們也是人，性情和你們一樣。我們傳福音給你們，是叫你們離棄這些虛妄，歸向那創造天、地、海，和其中萬物的永生神。","notes":[]},{"n":16,"t":"他在從前的世代，任憑萬國各行其道；","notes":[]},{"n":17,"t":"然而為自己未嘗不顯出證據來，就如常施恩惠，從天降雨，賞賜豐年，叫你們飲食飽足，滿心喜樂。」","notes":[]},{"n":18,"t":"二人說了這些話，僅僅地攔住眾人不獻祭與他們。","notes":[]},{"n":19,"t":"但有些猶太人從安提阿和以哥念來，挑唆眾人，就用石頭打保羅，以為他是死了，便拖到城外。","notes":[]},{"n":20,"t":"門徒正圍著他，他就起來，走進城去。第二天，同巴拿巴往特庇去，","notes":[]},{"n":21,"t":"對那城裏的人傳了福音，使好些人作門徒，就回路司得、以哥念、安提阿去，","notes":[]},{"n":22,"t":"堅固門徒的心，勸他們恆守所信的道；又說：「我們進入神的國，必須經歷許多艱難。」","notes":[]},{"n":23,"t":"二人在各教會中選立了長老，又禁食禱告，就把他們交託所信的主。","notes":[]},{"n":24,"t":"二人經過彼西底，來到旁非利亞。","notes":[]},{"n":25,"t":"在別加講了道，就下亞大利去，","notes":[]},{"n":26,"t":"從那裏坐船，往安提阿去。當初，他們被眾人所託、蒙神之恩、要辦現在所做之工，就是在這地方。","notes":[]},{"n":27,"t":"到了那裏，聚集了會眾，就述說神藉他們所行的一切事，並神怎樣為外邦人開了信道的門。","notes":[]},{"n":28,"t":"二人就在那裏同門徒住了多日。","notes":[]}]},"15":{"heading":"耶路撒冷會議","verses":[{"n":1,"t":"有幾個人從猶太下來，教訓弟兄們說：「你們若不按摩西的規條受割禮，不能得救。」","notes":[]},{"n":2,"t":"保羅、巴拿巴與他們大大地紛爭辯論；眾門徒就定規，叫保羅、巴拿巴和本會中幾個人，為所辯論的，上耶路撒冷去見使徒和長老。","notes":[]},{"n":3,"t":"於是教會送他們起行。他們經過腓尼基、撒馬利亞，隨處傳說外邦人歸主的事，叫眾弟兄都甚歡喜。","notes":[]},{"n":4,"t":"到了耶路撒冷，教會和使徒並長老都接待他們，他們就述說神同他們所行的一切事。","notes":[]},{"n":5,"t":"惟有幾個信徒， 是法利賽教門的人，起來說：「必須給外邦人行割禮，吩咐他們遵守摩西的律法。」","notes":[]},{"n":6,"t":"使徒和長老聚會商議這事；","notes":[]},{"n":7,"t":"辯論已經多了，彼得就起來，說：「諸位弟兄，你們知道神早已在你們中間揀選了我，叫外邦人從我口中得聽福音之道，而且相信。","notes":[]},{"n":8,"t":"知道人心的神也為他們作了見證，賜聖靈給他們，正如給我們一樣；","notes":[]},{"n":9,"t":"又藉著信潔淨了他們的心，並不分他們我們。","notes":[]},{"n":10,"t":"現在為甚麼試探神，要把我們祖宗和我們所不能負的軛放在門徒的頸項上呢？","notes":[]},{"n":11,"t":"我們得救乃是因主耶穌的恩，和他們一樣，這是我們所信的。」","notes":[]},{"n":12,"t":"眾人都默默無聲，聽巴拿巴和保羅述說神藉他們在外邦人中所行的神蹟奇事。","notes":[]},{"n":13,"t":"他們住了聲，雅各就說：「諸位弟兄，請聽我的話。","notes":[]},{"n":14,"t":"方才西門述說神當初怎樣眷顧外邦人，從他們中間選取百姓歸於自己的名下；","notes":[]},{"n":15,"t":"眾先知的話也與這意思相合。","notes":[]},{"n":16,"t":"正如經上所寫的：此後，我要回來，重新修造大衛倒塌的帳幕，把那破壞的重新修造建立起來，","notes":[]},{"n":17,"t":"叫餘剩的人，就是凡稱為我名下的外邦人，都尋求主。","notes":[]},{"n":18,"t":"這話是從創世以來顯明這事的主說的。","notes":[]},{"n":19,"t":"「所以據我的意見，不可難為那歸服神的外邦人；","notes":[]},{"n":20,"t":"只要寫信，吩咐他們禁戒偶像的污穢和姦淫，並勒死的牲畜和血。","notes":[]},{"n":21,"t":"因為從古以來，摩西的書在各城有人傳講，每逢安息日，在會堂裏誦讀。」","notes":[]},{"n":22,"t":"那時，使徒和長老並全教會定意從他們中間揀選人，差他們和保羅、巴拿巴同往安提阿去；所揀選的就是稱呼巴撒巴的猶大和西拉。這兩個人在弟兄中是作首領的。","notes":[],"heads":["會議的覆函"]},{"n":23,"t":"於是寫信交付他們，內中說：「使徒和作長老的弟兄們問安提阿、敘利亞、基利家外邦眾弟兄的安。","notes":[]},{"n":24,"t":"我們聽說，有幾個人從我們這裏出去，用言語攪擾你們，惑亂你們的心。其實我們並沒有吩咐他們。","notes":["有古卷加：你們必須受割禮，守摩西的律法。"]},{"n":25,"t":"所以，我們同心定意，揀選幾個人，差他們同我們所親愛的巴拿巴和保羅往你們那裏去。","notes":[]},{"n":26,"t":"這二人是為我主耶穌基督的名不顧性命的。","notes":[]},{"n":27,"t":"我們就差了猶大和西拉，他們也要親口訴說這些事。","notes":[]},{"n":28,"t":"因為聖靈和我們定意不將別的重擔放在你們身上，惟有幾件事是不可少的，","notes":[]},{"n":29,"t":"就是禁戒祭偶像的物和血，並勒死的牲畜和姦淫。這幾件你們若能自己禁戒不犯就好了。願你們平安！」","notes":[]},{"n":30,"t":"他們既奉了差遣，就下安提阿去，聚集眾人，交付書信。","notes":[]},{"n":31,"t":"眾人念了，因為信上安慰的話就歡喜了。","notes":[]},{"n":32,"t":"猶大和西拉也是先知，就用許多話勸勉弟兄，堅固他們。","notes":[]},{"n":33,"t":"住了些日子，弟兄們打發他們平平安安地回到差遣他們的人那裏去。","notes":["有古卷加：34惟有西拉定意仍住在那裏。"]},{"n":35,"t":"但保羅和巴拿巴仍住在安提阿，和許多別人一同教訓人，傳主的道。","notes":[]},{"n":36,"t":"過了些日子，保羅對巴拿巴說：「我們可以回到從前宣傳主道的各城，看望弟兄們景況如何。」","notes":[],"heads":["保羅和巴拿巴分手"]},{"n":37,"t":"巴拿巴有意要帶稱呼馬可的約翰同去；","notes":[]},{"n":38,"t":"但保羅因為馬可從前在旁非利亞離開他們，不和他們同去做工，就以為不可帶他去。","notes":[]},{"n":39,"t":"於是二人起了爭論，甚至彼此分開。巴拿巴帶著馬可，坐船往塞浦路斯去；","notes":[]},{"n":40,"t":"保羅揀選了西拉，也出去，蒙弟兄們把他交於主的恩中。","notes":[]},{"n":41,"t":"他就走遍敘利亞、基利家，堅固眾教會。","notes":[]}]},"16":{"heading":"提摩太跟保羅、西拉同工","verses":[{"n":1,"t":"保羅來到特庇，又到路司得。在那裏有一個門徒，名叫提摩太，是信主之猶太婦人的兒子，他父親卻是希臘人。","notes":[]},{"n":2,"t":"路司得和以哥念的弟兄都稱讚他。","notes":[]},{"n":3,"t":"保羅要帶他同去，只因那些地方的猶太人都知道他父親是希臘人，就給他行了割禮。","notes":[]},{"n":4,"t":"他們經過各城，把耶路撒冷使徒和長老所定的條規交給門徒遵守。","notes":[]},{"n":5,"t":"於是眾教會信心越發堅固，人數天天加增。","notes":[]},{"n":6,"t":"聖靈既然禁止他們在亞細亞講道，他們就經過弗呂家、加拉太一帶地方。","notes":[],"heads":["保羅看見馬其頓人的異象"]},{"n":7,"t":"到了每西亞的邊界，他們想要往庇推尼去，耶穌的靈卻不許。","notes":[]},{"n":8,"t":"他們就越過每西亞，下到特羅亞去。","notes":[]},{"n":9,"t":"在夜間有異象現與保羅。有一個馬其頓人站著求他說：「請你過到馬其頓來幫助我們。」","notes":[]},{"n":10,"t":"保羅既看見這異象，我們隨即想要往馬其頓去，以為神召我們傳福音給那裏的人聽。","notes":[]},{"n":11,"t":"於是從特羅亞開船，一直行到撒摩特喇，第二天到了尼亞坡里。","notes":[],"heads":["呂底亞歸主"]},{"n":12,"t":"從那裏來到腓立比，就是馬其頓這一方的頭一個城，也是羅馬的駐防城。我們在這城裏住了幾天。","notes":[]},{"n":13,"t":"當安息日，我們出城門，到了河邊，知道那裏有一個禱告的地方，我們就坐下對那聚會的婦女講道。","notes":[]},{"n":14,"t":"有一個賣紫色布疋的婦人，名叫呂底亞，是推雅推喇城的人，素來敬拜神。她聽見了，主就開導她的心，叫她留心聽保羅所講的話。","notes":[]},{"n":15,"t":"她和她一家既領了洗，便求我們說：「你們若以為我是真信主的，請到我家裏來住」；於是強留我們。","notes":["或譯：你們若以為我是忠心事主的"]},{"n":16,"t":"後來，我們往那禱告的地方去。有一個使女迎著面來，她被巫鬼所附，用法術，叫她主人們大得財利。","notes":[],"heads":["在腓立比被囚"]},{"n":17,"t":"她跟隨保羅和我們，喊著說：「這些人是至高神的僕人，對你們傳說救人的道。」","notes":[]},{"n":18,"t":"她一連多日這樣喊叫，保羅就心中厭煩，轉身對那鬼說：「我奉耶穌基督的名，吩咐你從她身上出來！」那鬼當時就出來了。","notes":[]},{"n":19,"t":"使女的主人們見得利的指望沒有了，便揪住保羅和西拉，拉他們到市上去見首領；","notes":[]},{"n":20,"t":"又帶到官長面前說：「這些人原是猶太人，竟騷擾我們的城，","notes":[]},{"n":21,"t":"傳我們羅馬人所不可受不可行的規矩。」","notes":[]},{"n":22,"t":"眾人就一同起來攻擊他們。官長吩咐剝了他們的衣裳，用棍打；","notes":[]},{"n":23,"t":"打了許多棍，便將他們下在監裏，囑咐禁卒嚴緊看守。","notes":[]},{"n":24,"t":"禁卒領了這樣的命，就把他們下在內監裏，兩腳上了木狗。","notes":[]},{"n":25,"t":"約在半夜，保羅和西拉禱告，唱詩讚美神，眾囚犯也側耳而聽。","notes":[]},{"n":26,"t":"忽然，地大震動，甚至監牢的地基都搖動了，監門立刻全開，眾囚犯的鎖鍊也都鬆開了。","notes":[]},{"n":27,"t":"禁卒一醒，看見監門全開，以為囚犯已經逃走，就拔刀要自殺。","notes":[]},{"n":28,"t":"保羅大聲呼叫說：「不要傷害自己！我們都在這裏。」","notes":[]},{"n":29,"t":"禁卒叫人拿燈來，就跳進去，戰戰兢兢地俯伏在保羅、西拉面前；","notes":[]},{"n":30,"t":"又領他們出來，說：「二位先生，我當怎樣行才可以得救？」","notes":[]},{"n":31,"t":"他們說：「當信主耶穌，你和你一家都必得救。」","notes":[]},{"n":32,"t":"他們就把主的道講給他和他全家的人聽。","notes":[]},{"n":33,"t":"當夜，就在那時候，禁卒把他們帶去，洗他們的傷；他和屬乎他的人立時都受了洗。","notes":[]},{"n":34,"t":"於是禁卒領他們上自己家裏去，給他們擺上飯。他和全家，因為信了神，都很喜樂。","notes":[]},{"n":35,"t":"到了天亮，官長打發差役來，說：「釋放那兩個人吧。」","notes":[]},{"n":36,"t":"禁卒就把這話告訴保羅說：「官長打發人來叫釋放你們，如今可以出監，平平安安地去吧。」","notes":[]},{"n":37,"t":"保羅卻說：「我們是羅馬人，並沒有定罪，他們就在眾人面前打了我們，又把我們下在監裏，現在要私下攆我們出去嗎？這是不行的。叫他們自己來領我們出去吧！」","notes":[]},{"n":38,"t":"差役把這話回稟官長。官長聽見他們是羅馬人，就害怕了，","notes":[]},{"n":39,"t":"於是來勸他們，領他們出來，請他們離開那城。","notes":[]},{"n":40,"t":"二人出了監，往呂底亞家裏去， 見了弟兄們，勸慰他們一番，就走了。","notes":[]}]},"17":{"heading":"帖撒羅尼迦的騷動","verses":[{"n":1,"t":"保羅和西拉經過暗妃坡里、亞波羅尼亞，來到帖撒羅尼迦，在那裏有猶太人的會堂。","notes":[]},{"n":2,"t":"保羅照他素常的規矩進去，一連三個安息日，本著聖經與他們辯論，","notes":[]},{"n":3,"t":"講解陳明基督必須受害，從死裏復活；又說：「我所傳與你們的這位耶穌就是基督。」","notes":[]},{"n":4,"t":"他們中間有些人聽了勸，就附從保羅和西拉，並有許多虔敬的希臘人，尊貴的婦女也不少。","notes":[]},{"n":5,"t":"但那不信的猶太人心裏嫉妒，招聚了些市井匪類，搭夥成群，聳動合城的人闖進耶孫的家，要將保羅、西拉帶到百姓那裏。","notes":[]},{"n":6,"t":"找不著他們，就把耶孫和幾個弟兄拉到地方官那裏，喊叫說：「那攪亂天下的也到這裏來了，","notes":[]},{"n":7,"t":"耶孫收留他們。這些人都違背凱撒的命令，說另有一個王耶穌。」","notes":[]},{"n":8,"t":"眾人和地方官聽見這話，就驚慌了；","notes":[]},{"n":9,"t":"於是取了耶孫和其餘之人的保狀，就釋放了他們。","notes":[]},{"n":10,"t":"弟兄們隨即在夜間打發保羅和西拉往庇哩亞去。二人到了，就進入猶太人的會堂。","notes":[],"heads":["使徒們在庇哩亞傳道"]},{"n":11,"t":"這地方的人賢於帖撒羅尼迦的人，甘心領受這道，天天考查聖經，要曉得這道是與不是。","notes":[]},{"n":12,"t":"所以他們中間多有相信的，又有希臘尊貴的婦女，男子也不少。","notes":[]},{"n":13,"t":"但帖撒羅尼迦的猶太人知道保羅又在庇哩亞傳神的道，也就往那裏去，聳動攪擾眾人。","notes":[]},{"n":14,"t":"當時弟兄們便打發保羅往海邊去，西拉和提摩太仍住在庇哩亞。","notes":[]},{"n":15,"t":"送保羅的人帶他到了雅典，既領了保羅的命，叫西拉和提摩太速速到他這裏來，就回去了。","notes":[]},{"n":16,"t":"保羅在雅典等候他們的時候，看見滿城都是偶像，就心裏著急；","notes":[],"heads":["保羅在雅典"]},{"n":17,"t":"於是在會堂裏與猶太人和虔敬的人，並每日在市上所遇見的人，辯論。","notes":[]},{"n":18,"t":"還有伊壁鳩魯和斯多亞兩門的學士，與他爭論。有的說：「這胡言亂語的要說甚麼？」有的說：「他似乎是傳說外邦鬼神的。」這話是因保羅傳講耶穌與復活的道。","notes":[]},{"n":19,"t":"他們就把他帶到亞略‧巴古，說：「你所講的這新道，我們也可以知道嗎？","notes":[]},{"n":20,"t":"因為你有些奇怪的事傳到我們耳中，我們願意知道這些事是甚麼意思。」（","notes":[]},{"n":21,"t":"雅典人和住在那裏的客人都不顧別的事，只將新聞說說聽聽。）","notes":[]},{"n":22,"t":"保羅站在亞略‧巴古當中，說：「眾位雅典人哪，我看你們凡事很敬畏鬼神。","notes":[]},{"n":23,"t":"我遊行的時候，觀看你們所敬拜的，遇見一座壇，上面寫著『未識之神』。你們所不認識而敬拜的，我現在告訴你們。","notes":[]},{"n":24,"t":"創造宇宙和其中萬物的神，既是天地的主，就不住人手所造的殿，","notes":[]},{"n":25,"t":"也不用人手服事，好像缺少甚麼；自己倒將生命、氣息、萬物，賜給萬人。","notes":[]},{"n":26,"t":"他從一本造出萬族的人，住在全地上，並且預先定準他們的年限和所住的疆界，","notes":["本：有古卷是血脈"]},{"n":27,"t":"要叫他們尋求神，或者可以揣摩而得，其實他離我們各人不遠；","notes":[]},{"n":28,"t":"我們生活、動作、存留，都在乎他。就如你們作詩的，有人說：『我們也是他所生的。』","notes":[]},{"n":29,"t":"我們既是神所生的，就不當以為神的神性像人用手藝、心思所雕刻的金、銀、石。","notes":[]},{"n":30,"t":"世人蒙昧無知的時候，神並不監察，如今卻吩咐各處的人都要悔改。","notes":[]},{"n":31,"t":"因為他已經定了日子，要藉著他所設立的人按公義審判天下，並且叫他從死裏復活，給萬人作可信的憑據。」","notes":[]},{"n":32,"t":"眾人聽見從死裏復活的話，就有譏誚他的；又有人說：「我們再聽你講這個吧！」","notes":[]},{"n":33,"t":"於是保羅從他們當中出去了。","notes":[]},{"n":34,"t":"但有幾個人貼近他，信了主，其中有亞略‧巴古的官丟尼修，並一個婦人，名叫大馬哩，還有別人一同信從。","notes":[]}]},"18":{"heading":"保羅在哥林多","verses":[{"n":1,"t":"這事以後，保羅離了雅典，來到哥林多。","notes":[]},{"n":2,"t":"遇見一個猶太人，名叫亞居拉，他生在本都；因為克勞第命猶太人都離開羅馬，新近帶著妻百基拉，從意大利來。保羅就投奔了他們。","notes":[]},{"n":3,"t":"他們本是製造帳棚為業。保羅因與他們同業，就和他們同住做工。","notes":[]},{"n":4,"t":"每逢安息日，保羅在會堂裏辯論，勸化猶太人和希臘人。","notes":[]},{"n":5,"t":"西拉和提摩太從馬其頓來的時候，保羅為道迫切，向猶太人證明耶穌是基督。","notes":[]},{"n":6,"t":"他們既抗拒、毀謗，保羅就抖著衣裳，說：「你們的罪歸到你們自己頭上，與我無干。從今以後，我要往外邦人那裏去。」","notes":["原文是血","原文是我卻乾淨"]},{"n":7,"t":"於是離開那裏，到了一個人的家中；這人名叫提多‧猶士都，是敬拜神的，他的家靠近會堂。","notes":[]},{"n":8,"t":"管會堂的基利司布和全家都信了主，還有許多哥林多人聽了，就相信受洗。","notes":[]},{"n":9,"t":"夜間，主在異象中對保羅說：「不要怕，只管講，不要閉口，","notes":[]},{"n":10,"t":"有我與你同在，必沒有人下手害你，因為在這城裏我有許多的百姓。」","notes":[]},{"n":11,"t":"保羅在那裏住了一年零六個月，將神的道教訓他們。","notes":[]},{"n":12,"t":"到迦流作亞該亞方伯的時候，猶太人同心起來攻擊保羅，拉他到公堂，","notes":[]},{"n":13,"t":"說：「這個人勸人不按著律法敬拜神。」","notes":[]},{"n":14,"t":"保羅剛要開口，迦流就對猶太人說：「你們這些猶太人！如果是為冤枉或奸惡的事，我理當耐性聽你們。","notes":[]},{"n":15,"t":"但所爭論的，若是關乎言語、名目，和你們的律法，你們自己去辦吧！這樣的事我不願意審問」；","notes":[]},{"n":16,"t":"就把他們攆出公堂。","notes":[]},{"n":17,"t":"眾人便揪住管會堂的所提尼，在堂前打他。這些事迦流都不管。","notes":[]},{"n":18,"t":"保羅又住了多日，就辭別了弟兄，坐船往敘利亞去；百基拉、亞居拉和他同去。他因為許過願，就在堅革哩剪了頭髮。","notes":[],"heads":["保羅回到安提阿"]},{"n":19,"t":"到了以弗所，保羅就把他們留在那裏，自己進了會堂，和猶太人辯論。","notes":[]},{"n":20,"t":"眾人請他多住些日子，他卻不允，","notes":[]},{"n":21,"t":"就辭別他們，說：「神若許我，我還要回到你們這裏」；於是開船離了以弗所。","notes":[]},{"n":22,"t":"在凱撒利亞下了船，就上耶路撒冷去問教會安，隨後下安提阿去。","notes":[]},{"n":23,"t":"住了些日子，又離開那裏，挨次經過加拉太和弗呂家地方，堅固眾門徒。","notes":[]},{"n":24,"t":"有一個猶太人，名叫亞波羅，來到以弗所。他生在亞歷山大，是有學問的，最能講解聖經。","notes":["或譯：口才"],"heads":["亞波羅在以弗所講道"]},{"n":25,"t":"這人已經在主的道上受了教訓，心裏火熱，將耶穌的事詳細講論教訓人；只是他單曉得約翰的洗禮。","notes":[]},{"n":26,"t":"他在會堂裏放膽講道；百基拉、亞居拉聽見，就接他來，將神的道給他講解更加詳細。","notes":[]},{"n":27,"t":"他想要往亞該亞去，弟兄們就勉勵他，並寫信請門徒接待他。他到了那裏，多幫助那蒙恩信主的人，","notes":["或譯：弟兄們就寫信勸門徒接待他"]},{"n":28,"t":"在眾人面前極有能力駁倒猶太人，引聖經證明耶穌是基督。","notes":[]}]},"19":{"heading":"保羅在以弗所","verses":[{"n":1,"t":"亞波羅在哥林多的時候，保羅經過了上邊一帶地方，就來到以弗所；在那裏遇見幾個門徒，","notes":[]},{"n":2,"t":"問他們說：「你們信的時候受了聖靈沒有？」他們回答說：「沒有，也未曾聽見有聖靈賜下來。」","notes":[]},{"n":3,"t":"保羅說：「這樣，你們受的是甚麼洗呢？」他們說：「是約翰的洗。」","notes":[]},{"n":4,"t":"保羅說：「約翰所行的是悔改的洗，告訴百姓當信那在他以後要來的，就是耶穌。」","notes":[]},{"n":5,"t":"他們聽見這話，就奉主耶穌的名受洗。","notes":[]},{"n":6,"t":"保羅按手在他們頭上，聖靈便降在他們身上，他們就說方言，又說預言。","notes":["或譯：又講道"]},{"n":7,"t":"一共約有十二個人。","notes":[]},{"n":8,"t":"保羅進會堂，放膽講道，一連三個月，辯論神國的事，勸化眾人。","notes":[]},{"n":9,"t":"後來，有些人心裏剛硬不信，在眾人面前毀謗這道，保羅就離開他們，也叫門徒與他們分離，便在推喇奴的學房天天辯論。","notes":[]},{"n":10,"t":"這樣有兩年之久，叫一切住在亞細亞的，無論是猶太人，是希臘人，都聽見主的道。","notes":[]},{"n":11,"t":"神藉保羅的手行了些非常的奇事；","notes":[],"heads":["士基瓦的兒子們"]},{"n":12,"t":"甚至有人從保羅身上拿手巾或圍裙放在病人身上，病就退了，惡鬼也出去了。","notes":[]},{"n":13,"t":"那時，有幾個遊行各處、念咒趕鬼的猶太人，向那被惡鬼附的人擅自稱主耶穌的名，說：「我奉保羅所傳的耶穌勅令你們出來！」","notes":[]},{"n":14,"t":"做這事的，有猶太祭司長士基瓦的七個兒子。","notes":[]},{"n":15,"t":"惡鬼回答他們說：「耶穌我認識，保羅我也知道。你們卻是誰呢？」","notes":[]},{"n":16,"t":"惡鬼所附的人就跳在他們身上，勝了其中二人，制伏他們，叫他們赤著身子受了傷，從那房子裏逃出去了。","notes":[]},{"n":17,"t":"凡住在以弗所的，無論是猶太人，是希臘人，都知道這事，也都懼怕；主耶穌的名從此就尊大了。","notes":[]},{"n":18,"t":"那已經信的，多有人來承認訴說自己所行的事。","notes":[]},{"n":19,"t":"平素行邪術的，也有許多人把書拿來，堆積在眾人面前焚燒。他們算計書價，便知道共合五萬塊錢。","notes":[]},{"n":20,"t":"主的道大大興旺，而且得勝，就是這樣。","notes":[]},{"n":21,"t":"這些事完了，保羅心裏定意經過了馬其頓、亞該亞，就往耶路撒冷去；又說：「我到了那裏以後，也必須往羅馬去看看。」","notes":[],"heads":["以弗所的暴動"]},{"n":22,"t":"於是從幫助他的人中打發提摩太、以拉都二人往馬其頓去，自己暫時等在亞細亞。","notes":[]},{"n":23,"t":"那時，因為這道起的擾亂不小。","notes":[]},{"n":24,"t":"有一個銀匠，名叫底米丟，是製造亞底米神銀龕的，他使這樣手藝人生意發達。","notes":[]},{"n":25,"t":"他聚集他們和同行的工人，說：「眾位，你們知道我們是倚靠這生意發財。","notes":[]},{"n":26,"t":"這保羅不但在以弗所，也幾乎在亞細亞全地，引誘迷惑許多人，說：『人手所做的，不是神。』這是你們所看見所聽見的。","notes":[]},{"n":27,"t":"這樣，不獨我們這事業被人藐視，就是大女神亞底米的廟也要被人輕忽，連亞細亞全地和普天下所敬拜的大女神之威榮也要消滅了。」","notes":[]},{"n":28,"t":"眾人聽見，就怒氣填胸，喊著說：「大哉，以弗所人的亞底米啊！」","notes":[]},{"n":29,"t":"滿城都轟動起來。眾人拿住與保羅同行的馬其頓人該猶和亞里達古，齊心擁進戲園裏去。","notes":[]},{"n":30,"t":"保羅想要進去，到百姓那裏，門徒卻不許他去。","notes":[]},{"n":31,"t":"還有亞細亞幾位首領，是保羅的朋友，打發人來勸他，不要冒險到戲園裏去。","notes":[]},{"n":32,"t":"聚集的人紛紛亂亂，有喊叫這個的，有喊叫那個的；大半不知道是為甚麼聚集。","notes":[]},{"n":33,"t":"有人把亞歷山大從眾人中帶出來，猶太人推他往前，亞歷山大就擺手，要向百姓分訴；","notes":[]},{"n":34,"t":"只因他們認出他是猶太人，就大家同聲喊著說：「大哉！以弗所人的亞底米啊。」如此約有兩小時。","notes":[]},{"n":35,"t":"那城裏的書記安撫了眾人，就說：「以弗所人哪，誰不知道以弗所人的城是看守大亞底米的廟和從宙斯那裏落下來的像呢？","notes":[]},{"n":36,"t":"這事既是駁不倒的，你們就當安靜，不可造次。","notes":[]},{"n":37,"t":"你們把這些人帶來，他們並沒有偷竊廟中之物，也沒有謗讟我們的女神。","notes":[]},{"n":38,"t":"若是底米丟和他同行的人有控告人的事，自有放告的日子，也有方伯可以彼此對告。","notes":["或譯：自有公堂"]},{"n":39,"t":"你們若問別的事，就可以照常例聚集斷定。","notes":[]},{"n":40,"t":"今日的擾亂本是無緣無故，我們難免被查問。論到這樣聚眾，我們也說不出所以然來。」","notes":[]},{"n":41,"t":"說了這話，便叫眾人散去。","notes":[]}]},"20":{"heading":"保羅再訪問馬其頓和希臘","verses":[{"n":1,"t":"亂定之後，保羅請門徒來，勸勉他們，就辭別起行，往馬其頓去。","notes":[]},{"n":2,"t":"走遍了那一帶地方，用許多話勸勉門徒，然後來到希臘。","notes":["或譯：眾人"]},{"n":3,"t":"在那裏住了三個月，將要坐船往敘利亞去，猶太人設計要害他，他就定意從馬其頓回去。","notes":[]},{"n":4,"t":"同他到亞細亞去的，有庇哩亞人畢羅斯的兒子所巴特，帖撒羅尼迦人亞里達古和西公都，還有特庇人該猶，並提摩太，又有亞細亞人推基古和特羅非摩。","notes":[]},{"n":5,"t":"這些人先走，在特羅亞等候我們。","notes":[]},{"n":6,"t":"過了除酵的日子，我們從腓立比開船，五天到了特羅亞，和他們相會，在那裏住了七天。","notes":[]},{"n":7,"t":"七日的第一日，我們聚會擘餅的時候，保羅因為要次日起行，就與他們講論，直講到半夜。","notes":[],"heads":["保羅最後一次訪問特羅亞"]},{"n":8,"t":"我們聚會的那座樓上，有好些燈燭。","notes":[]},{"n":9,"t":"有一個少年人，名叫猶推古，坐在窗臺上，困倦沉睡。保羅講了多時，少年人睡熟了，就從三層樓上掉下去；扶起他來，已經死了。","notes":[]},{"n":10,"t":"保羅下去，伏在他身上，抱著他，說：「你們不要發慌，他的靈魂還在身上。」","notes":[]},{"n":11,"t":"保羅又上去，擘餅，吃了，談論許久，直到天亮，這才走了。","notes":[]},{"n":12,"t":"有人把那童子活活地領來，得的安慰不小。","notes":[]},{"n":13,"t":"我們先上船，開往亞朔去，意思要在那裏接保羅；因為他是這樣安排的，他自己打算要步行。","notes":[],"heads":["從特羅亞到米利都"]},{"n":14,"t":"他既在亞朔與我們相會，我們就接他上船，來到米推利尼。","notes":[]},{"n":15,"t":"從那裏開船，次日到了基阿的對面；又次日，在撒摩靠岸；又次日，來到米利都。","notes":[]},{"n":16,"t":"乃因保羅早已定意越過以弗所，免得在亞細亞耽延，他急忙前走，巴不得趕五旬節能到耶路撒冷。","notes":[]},{"n":17,"t":"保羅從米利都打發人往以弗所去，請教會的長老來。","notes":[],"heads":["保羅向以弗所長老發表談話"]},{"n":18,"t":"他們來了，保羅就說：「你們知道，自從我到亞細亞的日子以來，在你們中間始終為人如何，","notes":[]},{"n":19,"t":"服事主，凡事謙卑，眼中流淚，又因猶太人的謀害，經歷試煉。","notes":[]},{"n":20,"t":"你們也知道，凡與你們有益的，我沒有一樣避諱不說的，或在眾人面前，或在各人家裏，我都教導你們；","notes":[]},{"n":21,"t":"又對猶太人和希臘人證明當向神悔改，信靠我主耶穌基督。","notes":[]},{"n":22,"t":"現在我往耶路撒冷去，心甚迫切，不知道在那裏要遇見甚麼事；","notes":["原文是心被捆綁"]},{"n":23,"t":"但知道聖靈在各城裏向我指證，說有捆鎖與患難等待我。","notes":[]},{"n":24,"t":"我卻不以性命為念，也不看為寶貴，只要行完我的路程，成就我從主耶穌所領受的職事，證明神恩惠的福音。","notes":[]},{"n":25,"t":"「我素常在你們中間來往，傳講神國的道；如今我曉得，你們以後都不得再見我的面了。","notes":[]},{"n":26,"t":"所以我今日向你們證明，你們中間無論何人死亡，罪不在我身上。","notes":["原文是我於眾人的血是潔淨的"]},{"n":27,"t":"因為神的旨意，我並沒有一樣避諱不傳給你們的。","notes":[]},{"n":28,"t":"聖靈立你們作全群的監督，你們就當為自己謹慎，也為全群謹慎，牧養神的教會，就是他用自己血所買來的。","notes":["或譯：救贖的"]},{"n":29,"t":"我知道，我去之後必有兇暴的豺狼進入你們中間，不愛惜羊群。","notes":[]},{"n":30,"t":"就是你們中間，也必有人起來說悖謬的話，要引誘門徒跟從他們。","notes":[]},{"n":31,"t":"所以你們應當警醒，記念我三年之久晝夜不住地流淚、勸戒你們各人。","notes":[]},{"n":32,"t":"如今我把你們交託神和他恩惠的道；這道能建立你們，叫你們和一切成聖的人同得基業。","notes":[]},{"n":33,"t":"我未曾貪圖一個人的金、銀、衣服。","notes":[]},{"n":34,"t":"我這兩隻手常供給我和同人的需用，這是你們自己知道的。","notes":[]},{"n":35,"t":"我凡事給你們作榜樣，叫你們知道應當這樣勞苦，扶助軟弱的人，又當記念主耶穌的話，說：『施比受更為有福。』」","notes":[]},{"n":36,"t":"保羅說完了這話，就跪下同眾人禱告。","notes":[]},{"n":37,"t":"眾人痛哭，抱著保羅的頸項，和他親嘴。","notes":[]},{"n":38,"t":"叫他們最傷心的，就是他說「以後不能再見我的面」那句話，於是送他上船去了。","notes":[]}]},"21":{"heading":"保羅上耶路撒冷","verses":[{"n":1,"t":"我們離別了眾人，就開船一直行到哥士。第二天到了羅底，從那裏到帕大喇，","notes":[]},{"n":2,"t":"遇見一隻船要往腓尼基去，就上船起行。","notes":[]},{"n":3,"t":"望見塞浦路斯，就從南邊行過，往敘利亞去，我們就在泰爾上岸，因為船要在那裏卸貨。","notes":[]},{"n":4,"t":"找著了門徒，就在那裏住了七天。他們被聖靈感動，對保羅說：「不要上耶路撒冷去。」","notes":[]},{"n":5,"t":"過了這幾天，我們就起身前行。他們眾人同妻子兒女，送我們到城外，我們都跪在岸上禱告，彼此辭別。","notes":[]},{"n":6,"t":"我們上了船，他們就回家去了。","notes":[]},{"n":7,"t":"我們從泰爾行盡了水路，來到多利買，就問那裏的弟兄安，和他們同住了一天。","notes":[]},{"n":8,"t":"第二天，我們離開那裏，來到凱撒利亞，就進了傳福音的腓利家裏，和他同住。他是那七個執事裏的一個。","notes":[]},{"n":9,"t":"他有四個女兒，都是處女，是說預言的。","notes":[]},{"n":10,"t":"我們在那裏多住了幾天，有一個先知，名叫亞迦布，從猶太下來，","notes":[]},{"n":11,"t":"到了我們這裏，就拿保羅的腰帶捆上自己的手腳，說：「聖靈說：猶太人在耶路撒冷，要如此捆綁這腰帶的主人，把他交在外邦人手裏。」","notes":[]},{"n":12,"t":"我們和那本地的人聽見這話，都苦勸保羅不要上耶路撒冷去。","notes":[]},{"n":13,"t":"保羅說：「你們為甚麼這樣痛哭，使我心碎呢？我為主耶穌的名，不但被人捆綁，就是死在耶路撒冷也是願意的。」","notes":[]},{"n":14,"t":"保羅既不聽勸，我們便住了口，只說：「願主的旨意成就」，便了。","notes":[]},{"n":15,"t":"過了幾日，我們收拾行李上耶路撒冷去。","notes":[]},{"n":16,"t":"有凱撒利亞的幾個門徒和我們同去，帶我們到一個久為門徒的家裏，叫我們與他同住；他名叫拿孫，是塞浦路斯人。","notes":["久為：或譯老"]},{"n":17,"t":"到了耶路撒冷，弟兄們歡歡喜喜地接待我們。","notes":[],"heads":["保羅訪問雅各"]},{"n":18,"t":"第二天，保羅同我們去見雅各；長老們也都在那裏。","notes":[]},{"n":19,"t":"保羅問了他們安，便將神用他傳教，在外邦人中間所行之事，一一地述說了。","notes":[]},{"n":20,"t":"他們聽見，就歸榮耀與神，對保羅說：「兄台，你看猶太人中信主的有多少萬，並且都為律法熱心。","notes":[]},{"n":21,"t":"他們聽見人說，你教訓一切在外邦的猶太人離棄摩西，對他們說，不要給孩子行割禮，也不要遵行條規。","notes":[]},{"n":22,"t":"眾人必聽見你來了，這可怎麼辦呢？","notes":[]},{"n":23,"t":"你就照著我們的話行吧！ 我們這裏有四個人，都有願在身。","notes":[]},{"n":24,"t":"你帶他們去，與他們一同行潔淨的禮，替他們拿出規費，叫他們得以剃頭。這樣，眾人就可知道，先前所聽見你的事都是虛的；並可知道，你自己為人，循規蹈矩，遵行律法。","notes":[]},{"n":25,"t":"至於信主的外邦人，我們已經寫信擬定，叫他們謹忌那祭偶像之物，和血，並勒死的牲畜，與姦淫。」","notes":[]},{"n":26,"t":"於是保羅帶著那四個人，第二天與他們一同行了潔淨的禮，進了殿，報明潔淨的日期滿足，只等祭司為他們各人獻祭。","notes":[]},{"n":27,"t":"那七日將完，從亞細亞來的猶太人看見保羅在殿裏，就聳動了眾人，下手拿他，","notes":[],"heads":["保羅在聖殿裏被捕"]},{"n":28,"t":"喊叫說：「以色列人來幫助，這就是在各處教訓眾人糟踐我們百姓和律法，並這地方的。他又帶著希臘人進殿，污穢了這聖地。」（","notes":[]},{"n":29,"t":"這話是因他們曾看見以弗所人特羅非摩同保羅在城裏，以為保羅帶他進了殿。）","notes":[]},{"n":30,"t":"合城都震動，百姓一齊跑來，拿住保羅，拉他出殿，殿門立刻都關了。","notes":[]},{"n":31,"t":"他們正想要殺他，有人報信給營裏的千夫長說：「耶路撒冷合城都亂了。」","notes":[]},{"n":32,"t":"千夫長立時帶著兵丁和幾個百夫長，跑下去到他們那裏。他們見了千夫長和兵丁，就止住不打保羅。","notes":[]},{"n":33,"t":"於是千夫長上前拿住他，吩咐用兩條鐵鍊捆鎖；又問他是甚麼人，做的是甚麼事。","notes":[]},{"n":34,"t":"眾人有喊叫這個的，有喊叫那個的；千夫長因為這樣亂嚷，得不著實情，就吩咐人將保羅帶進營樓去。","notes":[]},{"n":35,"t":"到了臺階上，眾人擠得兇猛，兵丁只得將保羅抬起來。","notes":[]},{"n":36,"t":"眾人跟在後面，喊著說：「除掉他！」","notes":[]},{"n":37,"t":"將要帶他進營樓，保羅對千夫長說：「我對你說句話可以不可以？」他說：「你懂得希臘話嗎？","notes":[],"heads":["保羅為自己辯護"]},{"n":38,"t":"你莫非是從前作亂、帶領四千兇徒往曠野去的那埃及人嗎？」","notes":[]},{"n":39,"t":"保羅說：「我本是猶太人，生在基利家的大數，並不是無名小城的人。求你准我對百姓說話。」","notes":[]},{"n":40,"t":"千夫長准了。保羅就站在臺階上，向百姓擺手，他們都靜默無聲，保羅便用希伯來話對他們說：","notes":[]}]},"22":{"heading":"保羅敘述歸主的經過","verses":[{"n":1,"t":"「諸位父兄請聽，我現在對你們分訴。」","notes":[]},{"n":2,"t":"眾人聽他說的是希伯來話，就更加安靜了。","notes":[]},{"n":3,"t":"保羅說：「我原是猶太人，生在基利家的大數，長在這城裏，在迦瑪列門下，按著我們祖宗嚴緊的律法受教，熱心事奉神，像你們眾人今日一樣。","notes":[]},{"n":4,"t":"我也曾逼迫奉這道的人，直到死地，無論男女都鎖拿下監。","notes":[]},{"n":5,"t":"這是大祭司和眾長老都可以給我作見證的。我又領了他們達與弟兄的書信，往大馬士革去，要把在那裏奉這道的人鎖拿，帶到耶路撒冷受刑。」","notes":[]},{"n":6,"t":"「我將到大馬士革，正走的時候，約在晌午，忽然從天上發大光，四面照著我。","notes":[]},{"n":7,"t":"我就仆倒在地，聽見有聲音對我說：『掃羅！掃羅！你為甚麼逼迫我？』","notes":[]},{"n":8,"t":"我回答說：『主啊，你是誰？』他說：『我就是你所逼迫的拿撒勒人耶穌。』","notes":[]},{"n":9,"t":"與我同行的人看見了那光，卻沒有聽明那位對我說話的聲音。","notes":[]},{"n":10,"t":"我說：『主啊，我當做甚麼？』主說：『起來，進大馬士革去，在那裏，要將所派你做的一切事告訴你。』","notes":[]},{"n":11,"t":"我因那光的榮耀不能看見，同行的人就拉著我手進了大馬士革。","notes":[]},{"n":12,"t":"那裏有一個人，名叫亞拿尼亞，按著律法是虔誠人，為一切住在那裏的猶太人所稱讚。","notes":[]},{"n":13,"t":"他來見我，站在旁邊，對我說：『兄弟掃羅，你可以看見。』我當時往上一看，就看見了他。","notes":[]},{"n":14,"t":"他又說：『我們祖宗的神揀選了你，叫你明白他的旨意，又得見那義者，聽他口中所出的聲音。","notes":[]},{"n":15,"t":"因為你要將所看見的，所聽見的，對著萬人為他作見證。","notes":[]},{"n":16,"t":"現在你為甚麼耽延呢？起來，求告他的名受洗，洗去你的罪。』」","notes":[]},{"n":17,"t":"「後來，我回到耶路撒冷，在殿裏禱告的時候，魂遊象外，","notes":[],"heads":["保羅奉召向外邦人傳道"]},{"n":18,"t":"看見主向我說：『你趕緊地離開耶路撒冷，不可遲延；因你為我作的見證，這裏的人必不領受。』","notes":[]},{"n":19,"t":"我就說：『主啊，他們知道我從前把信你的人收在監裏，又在各會堂裏鞭打他們。","notes":[]},{"n":20,"t":"並且你的見證人司提反被害流血的時候，我也站在旁邊歡喜；又看守害死他之人的衣裳。』","notes":[]},{"n":21,"t":"主向我說：『你去吧！我要差你遠遠地往外邦人那裏去。』」","notes":[]},{"n":22,"t":"眾人聽他說到這句話，就高聲說：「這樣的人，從世上除掉他吧！他是不當活著的。」","notes":[],"heads":["保羅與長官交涉"]},{"n":23,"t":"眾人喧嚷，摔掉衣裳，把塵土向空中揚起來。","notes":[]},{"n":24,"t":"千夫長就吩咐將保羅帶進營樓去，叫人用鞭子拷問他，要知道他們向他這樣喧嚷是為甚麼緣故。","notes":[]},{"n":25,"t":"剛用皮條捆上，保羅對旁邊站著的百夫長說：「人是羅馬人，又沒有定罪，你們就鞭打他，有這個例嗎？」","notes":[]},{"n":26,"t":"百夫長聽見這話，就去見千夫長，告訴他說：「你要做甚麼？這人是羅馬人。」","notes":[]},{"n":27,"t":"千夫長就來問保羅說：「你告訴我，你是羅馬人嗎？」保羅說：「是。」","notes":[]},{"n":28,"t":"千夫長說：「我用許多銀子才入了羅馬的民籍。」保羅說：「我生來就是。」","notes":[]},{"n":29,"t":"於是那些要拷問保羅的人就離開他去了。千夫長既知道他是羅馬人，又因為捆綁了他，也害怕了。","notes":[]},{"n":30,"t":"第二天，千夫長為要知道猶太人控告保羅的實情，便解開他，吩咐祭司長和全公會的人都聚集，將保羅帶下來，叫他站在他們面前。","notes":[],"heads":["保羅在公會前申訴"]}]},"23":{"heading":"殺害保羅的陰謀","verses":[{"n":1,"t":"保羅定睛看著公會的人，說：「弟兄們，我在神面前行事為人都是憑著良心，直到今日。」","notes":[]},{"n":2,"t":"大祭司亞拿尼亞就吩咐旁邊站著的人打他的嘴。","notes":[]},{"n":3,"t":"保羅對他說：「你這粉飾的牆，神要打你！你坐堂為的是按律法審問我，你竟違背律法，吩咐人打我嗎？」","notes":[]},{"n":4,"t":"站在旁邊的人說：「你辱罵神的大祭司嗎？」","notes":[]},{"n":5,"t":"保羅說：「弟兄們，我不曉得他是大祭司；經上記著說：『不可毀謗你百姓的官長。』」","notes":[]},{"n":6,"t":"保羅看出大眾一半是撒都該人，一半是法利賽人，就在公會中大聲說：「弟兄們，我是法利賽人，也是法利賽人的子孫。我現在受審問，是為盼望死人復活。」","notes":[]},{"n":7,"t":"說了這話，法利賽人和撒都該人就爭論起來，會眾分為兩黨。","notes":[]},{"n":8,"t":"因為撒都該人說，沒有復活，也沒有天使和鬼魂；法利賽人卻說，兩樣都有。","notes":[]},{"n":9,"t":"於是大大地喧嚷起來。有幾個法利賽黨的文士站起來爭辯說：「我們看不出這人有甚麼惡處，倘若有鬼魂或是天使對他說過話，怎麼樣呢？」","notes":[]},{"n":10,"t":"那時大起爭吵，千夫長恐怕保羅被他們扯碎了，就吩咐兵丁下去，把他從眾人當中搶出來，帶進營樓去。","notes":[]},{"n":11,"t":"當夜，主站在保羅旁邊，說：「放心吧！你怎樣在耶路撒冷為我作見證，也必怎樣在羅馬為我作見證。」","notes":[]},{"n":12,"t":"到了天亮，猶太人同謀起誓，說：「若不先殺保羅就不吃不喝。」","notes":[]},{"n":13,"t":"這樣同心起誓的有四十多人。","notes":[]},{"n":14,"t":"他們來見祭司長和長老，說：「我們已經起了一個大誓，若不先殺保羅就不吃甚麼。","notes":[]},{"n":15,"t":"現在你們和公會要知會千夫長，叫他帶下保羅到你們這裏來，假作要詳細察考他的事；我們已經預備好了，不等他來到跟前就殺他。」","notes":[]},{"n":16,"t":"保羅的外甥聽見他們設下埋伏，就來到營樓裏告訴保羅。","notes":[]},{"n":17,"t":"保羅請一個百夫長來，說：「你領這少年人去見千夫長，他有事告訴他。」","notes":[]},{"n":18,"t":"於是把他領去見千夫長，說：「被囚的保羅請我到他那裏，求我領這少年人來見你；他有事告訴你。」","notes":[]},{"n":19,"t":"千夫長就拉著他的手，走到一旁，私下問他說：「你有甚麼事告訴我呢？」","notes":[]},{"n":20,"t":"他說：「猶太人已經約定，要求你明天帶下保羅到公會裏去，假作要詳細查問他的事。","notes":[]},{"n":21,"t":"你切不要隨從他們；因為他們有四十多人埋伏，已經起誓說，若不先殺保羅就不吃不喝。現在預備好了，只等你應允。」","notes":[]},{"n":22,"t":"於是千夫長打發少年人走，囑咐他說：「不要告訴人你將這事報給我了。」","notes":[]},{"n":23,"t":"千夫長便叫了兩個百夫長來，說：「預備步兵二百，馬兵七十，長槍手二百，今夜亥初往凱撒利亞去；","notes":[],"heads":["保羅被解交腓力斯巡撫"]},{"n":24,"t":"也要預備牲口叫保羅騎上，護送到巡撫腓力斯那裏去。」","notes":[]},{"n":25,"t":"千夫長又寫了文書，","notes":[]},{"n":26,"t":"大略說：「克勞第‧呂西亞，請巡撫腓力斯大人安。","notes":[]},{"n":27,"t":"這人被猶太人拿住，將要殺害，我得知他是羅馬人，就帶兵丁下去救他出來。","notes":[]},{"n":28,"t":"因要知道他們告他的緣故，我就帶他下到他們的公會去，","notes":[]},{"n":29,"t":"便查知他被告是因他們律法的辯論，並沒有甚麼該死該綁的罪名。","notes":[]},{"n":30,"t":"後來有人把要害他的計謀告訴我，我就立時解他到你那裏去，又吩咐告他的人在你面前告他。」","notes":["有古卷加：願你平安！"]},{"n":31,"t":"於是，兵丁照所吩咐他們的，將保羅夜裏帶到安提帕底。","notes":[]},{"n":32,"t":"第二天，讓馬兵護送，他們就回營樓去。","notes":[]},{"n":33,"t":"馬兵來到凱撒利亞，把文書呈給巡撫，便叫保羅站在他面前。","notes":[]},{"n":34,"t":"巡撫看了文書，問保羅是哪省的人，既曉得他是基利家人，","notes":[]},{"n":35,"t":"就說：「等告你的人來到，我要細聽你的事」；便吩咐人把他看守在希律的衙門裏。","notes":[]}]},"24":{"heading":"猶太人控告保羅","verses":[{"n":1,"t":"過了五天，大祭司亞拿尼亞同幾個長老，和一個辯士帖土羅下來，向巡撫控告保羅。","notes":[]},{"n":2,"t":"保羅被提了來，帖土羅就告他說：","notes":[]},{"n":3,"t":"「腓力斯大人，我們因你得以大享太平，並且這一國的弊病，因著你的先見得以更正了；我們隨時隨地滿心感謝不盡。","notes":[]},{"n":4,"t":"惟恐多說，你嫌煩絮，只求你寬容聽我們說幾句話。","notes":[]},{"n":5,"t":"我們看這個人，如同瘟疫一般，是鼓動普天下眾猶太人生亂的，又是拿撒勒教黨裏的一個頭目，","notes":[]},{"n":6,"t":"連聖殿他也想要污穢；我們把他捉住了。","notes":["有古卷加：要按我們的律法審問，7不料，千夫長呂西亞前來，甚是強橫，從我們手中把他奪去，吩咐告他的人到你這裏來。"]},{"n":8,"t":"你自己究問他，就可以知道我們告他的一切事了。」","notes":[]},{"n":9,"t":"眾猶太人也隨著告他說：「事情誠然是這樣。」","notes":[]},{"n":10,"t":"巡撫點頭叫保羅說話。他就說：「我知道你在這國裏斷事多年，所以我樂意為自己分訴。","notes":[],"heads":["保羅為自己辯護"]},{"n":11,"t":"你查問就可以知道，從我上耶路撒冷禮拜到今日不過有十二天。","notes":[]},{"n":12,"t":"他們並沒有看見我在殿裏，或是在會堂裏，或是在城裏，和人辯論，聳動眾人。","notes":[]},{"n":13,"t":"他們現在所告我的事並不能對你證實了。","notes":[]},{"n":14,"t":"但有一件事，我向你承認，就是他們所稱為異端的道，我正按著那道事奉我祖宗的神，又信合乎律法的和先知書上一切所記載的，","notes":[]},{"n":15,"t":"並且靠著神，盼望死人，無論善惡，都要復活，就是他們自己也有這個盼望。","notes":[]},{"n":16,"t":"我因此自己勉勵，對神對人，常存無虧的良心。","notes":[]},{"n":17,"t":"過了幾年，我帶著賙濟本國的捐項和供獻的物上去。","notes":[]},{"n":18,"t":"正獻的時候，他們看見我在殿裏已經潔淨了，並沒有聚眾，也沒有吵嚷，惟有幾個從亞細亞來的猶太人。","notes":[]},{"n":19,"t":"他們若有告我的事，就應當到你面前來告我。","notes":[]},{"n":20,"t":"即或不然，這些人若看出我站在公會前，有妄為的地方，他們自己也可以說明。","notes":[]},{"n":21,"t":"縱然有，也不過一句話，就是我站在他們中間大聲說：『我今日在你們面前受審，是為死人復活的道理。』」","notes":[]},{"n":22,"t":"腓力斯本是詳細曉得這道，就支吾他們說：「且等千夫長呂西亞下來，我要審斷你們的事。」","notes":[]},{"n":23,"t":"於是吩咐百夫長看守保羅，並且寬待他，也不攔阻他的親友來供給他。","notes":[]},{"n":24,"t":"過了幾天，腓力斯和他夫人－猶太的女子土西拉－一同來到，就叫了保羅來，聽他講論信基督耶穌的道。","notes":[],"heads":["腓力斯留保羅在監裏"]},{"n":25,"t":"保羅講論公義、節制，和將來的審判。腓力斯甚覺恐懼，說：「你暫且去吧，等我得便再叫你來。」","notes":[]},{"n":26,"t":"腓力斯又指望保羅送他銀錢，所以屢次叫他來，和他談論。","notes":[]},{"n":27,"t":"過了兩年，波求‧非斯都接了腓力斯的任；腓力斯要討猶太人的喜歡，就留保羅在監裏。","notes":[]}]},"25":{"heading":"保羅要向凱撒上訴","verses":[{"n":1,"t":"非斯都到了任，過了三天，就從凱撒利亞上耶路撒冷去。","notes":[]},{"n":2,"t":"祭司長和猶太人的首領向他控告保羅，","notes":[]},{"n":3,"t":"又央告他，求他的情，將保羅提到耶路撒冷來，他們要在路上埋伏殺害他。","notes":[]},{"n":4,"t":"非斯都卻回答說：「保羅押在凱撒利亞，我自己快要往那裏去」；","notes":[]},{"n":5,"t":"又說：「你們中間有權勢的人與我一同下去，那人若有甚麼不是，就可以告他。」","notes":[]},{"n":6,"t":"非斯都在他們那裏住了不過十天八天，就下凱撒利亞去；第二天坐堂，吩咐將保羅提上來。","notes":[]},{"n":7,"t":"保羅來了，那些從耶路撒冷下來的猶太人周圍站著，將許多重大的事控告他，都是不能證實的。","notes":[]},{"n":8,"t":"保羅分訴說：「無論猶太人的律法，或是聖殿，或是凱撒，我都沒有干犯。」","notes":[]},{"n":9,"t":"但非斯都要討猶太人的喜歡，就問保羅說：「你願意上耶路撒冷去，在那裏聽我審斷這事嗎？」","notes":[]},{"n":10,"t":"保羅說：「我站在凱撒的堂前，這就是我應當受審的地方。我向猶太人並沒有行過甚麼不義的事，這也是你明明知道的。","notes":[]},{"n":11,"t":"我若行了不義的事，犯了甚麼該死的罪，就是死，我也不辭。他們所告我的事若都不實，就沒有人可以把我交給他們。我要上告於凱撒。」","notes":[]},{"n":12,"t":"非斯都和議會商量了，就說：「你既上告於凱撒，可以往凱撒那裏去。」","notes":[]},{"n":13,"t":"過了些日子，亞基帕王和百妮基氏來到凱撒利亞，問非斯都安。","notes":[],"heads":["保羅被帶到亞基帕王面前"]},{"n":14,"t":"在那裏住了多日，非斯都將保羅的事告訴王，說：「這裏有一個人，是腓力斯留在監裏的。","notes":[]},{"n":15,"t":"我在耶路撒冷的時候，祭司長和猶太的長老將他的事稟報了我，求我定他的罪。","notes":[]},{"n":16,"t":"我對他們說，無論甚麼人，被告還沒有和原告對質，未得機會分訴所告他的事，就先定他的罪，這不是羅馬人的條例。","notes":[]},{"n":17,"t":"及至他們都來到這裏，我就不耽延，第二天便坐堂，吩咐把那人提上來。","notes":[]},{"n":18,"t":"告他的人站著告他；所告的，並沒有我所逆料的那等惡事。","notes":[]},{"n":19,"t":"不過是有幾樣辯論，為他們自己敬鬼神的事，又為一個人名叫耶穌，是已經死了，保羅卻說他是活著的。","notes":[]},{"n":20,"t":"這些事當怎樣究問，我心裏作難，所以問他說：『你願意上耶路撒冷去，在那裏為這些事聽審嗎？』","notes":[]},{"n":21,"t":"但保羅求我留下他，要聽皇上審斷，我就吩咐把他留下，等我解他到凱撒那裏去。」","notes":[]},{"n":22,"t":"亞基帕對非斯都說：「我自己也願聽這人辯論。」非斯都說：「明天你可以聽。」","notes":[]},{"n":23,"t":"第二天，亞基帕和百妮基大張威勢而來，同著眾千夫長和城裏的尊貴人進了公廳。非斯都吩咐一聲，就有人將保羅帶進來。","notes":[]},{"n":24,"t":"非斯都說：「亞基帕王和在這裏的諸位啊，你們看這人，就是一切猶太人，在耶路撒冷和這裏，曾向我懇求、呼叫說：『不可容他再活著。』","notes":[]},{"n":25,"t":"但我查明他沒有犯甚麼該死的罪，並且他自己上告於皇帝，所以我定意把他解去。","notes":[]},{"n":26,"t":"論到這人，我沒有確實的事可以奏明主上。因此，我帶他到你們面前，也特意帶他到你亞基帕王面前，為要在查問之後有所陳奏。","notes":[]},{"n":27,"t":"據我看來，解送囚犯，不指明他的罪案是不合理的。」","notes":[]}]},"26":{"heading":"保羅在亞基帕王面前申辯","verses":[{"n":1,"t":"亞基帕對保羅說：「准你為自己辯明。」於是保羅伸手分訴，說：「","notes":[]},{"n":2,"t":"亞基帕王啊，猶太人所告我的一切事，今日得在你面前分訴，實為萬幸；","notes":[]},{"n":3,"t":"更可幸的，是你熟悉猶太人的規矩和他們的辯論；所以求你耐心聽我。","notes":[]},{"n":4,"t":"我從起初在本國的民中，並在耶路撒冷，自幼為人如何，猶太人都知道。","notes":[]},{"n":5,"t":"他們若肯作見證就曉得，我從起初是按著我們教中最嚴緊的教門作了法利賽人。","notes":[]},{"n":6,"t":"現在我站在這裏受審，是因為指望神向我們祖宗所應許的；","notes":[]},{"n":7,"t":"這應許，我們十二個支派，晝夜切切地事奉神，都指望得著。王啊，我被猶太人控告，就是因這指望。","notes":[]},{"n":8,"t":"神叫死人復活，你們為甚麼看作不可信的呢？","notes":[]},{"n":9,"t":"從前我自己以為應當多方攻擊拿撒勒人耶穌的名，","notes":[]},{"n":10,"t":"我在耶路撒冷也曾這樣行了。既從祭司長得了權柄，我就把許多聖徒囚在監裏。他們被殺，我也出名定案。","notes":[]},{"n":11,"t":"在各會堂，我屢次用刑強逼他們說褻瀆的話，又分外惱恨他們，甚至追逼他們，直到外邦的城邑。」","notes":[]},{"n":12,"t":"「那時，我領了祭司長的權柄和命令，往大馬士革去。","notes":[],"heads":["保羅敘述歸主經過"]},{"n":13,"t":"王啊，我在路上，晌午的時候，看見從天發光，比日頭還亮，四面照著我並與我同行的人。","notes":[]},{"n":14,"t":"我們都仆倒在地，我就聽見有聲音用希伯來話向我說：『掃羅！掃羅！為甚麼逼迫我？你用腳踢刺是難的！』","notes":[]},{"n":15,"t":"我說：『主啊，你是誰？』主說：『我就是你所逼迫的耶穌。","notes":[]},{"n":16,"t":"你起來站著，我特意向你顯現，要派你作執事，作見證，將你所看見的事和我將要指示你的事證明出來。","notes":[]},{"n":17,"t":"我也要救你脫離百姓和外邦人的手。","notes":[]},{"n":18,"t":"我差你到他們那裏去，要叫他們的眼睛得開，從黑暗中歸向光明，從撒但權下歸向神；又因信我，得蒙赦罪，和一切成聖的人同得基業。』」","notes":[]},{"n":19,"t":"「亞基帕王啊，我故此沒有違背那從天上來的異象；","notes":[],"heads":["保羅向猶太和外邦人作見證"]},{"n":20,"t":"先在大馬士革，後在耶路撒冷和猶太全地，以及外邦，勸勉他們應當悔改歸向神，行事與悔改的心相稱。","notes":[]},{"n":21,"t":"因此，猶太人在殿裏拿住我，想要殺我。","notes":[]},{"n":22,"t":"然而我蒙神的幫助，直到今日還站得住，對著尊貴、卑賤、老幼作見證；所講的並不外乎眾先知和摩西所說將來必成的事，","notes":[]},{"n":23,"t":"就是基督必須受害，並且因從死裏復活，要首先把光明的道傳給百姓和外邦人。」","notes":[]},{"n":24,"t":"保羅這樣分訴，非斯都大聲說：「保羅，你癲狂了吧。你的學問太大，反叫你癲狂了！」","notes":[],"heads":["保羅懇請亞基帕信主"]},{"n":25,"t":"保羅說：「非斯都大人，我不是癲狂，我說的乃是真實明白話。","notes":[]},{"n":26,"t":"王也曉得這些事，所以我向王放膽直言，我深信這些事沒有一件向王隱藏的，因都不是在背地裏做的。","notes":[]},{"n":27,"t":"亞基帕王啊，你信先知嗎？我知道你是信的。」","notes":[]},{"n":28,"t":"亞基帕對保羅說：「你想少微一勸，便叫我作基督徒啊！」","notes":["或譯：你這樣勸我，幾乎叫我作基督徒了"]},{"n":29,"t":"保羅說：「無論是少勸是多勸，我向神所求的，不但你一個人，就是今天一切聽我的，都要像我一樣，只是不要像我有這些鎖鍊。」","notes":[]},{"n":30,"t":"於是，王和巡撫並百妮基與同坐的人都起來，","notes":[]},{"n":31,"t":"退到裏面，彼此談論說：「這人並沒有犯甚麼該死該綁的罪。」","notes":[]},{"n":32,"t":"亞基帕又對非斯都說：「這人若沒有上告於凱撒，就可以釋放了。」","notes":[]}]},"27":{"heading":"保羅坐船往羅馬","verses":[{"n":1,"t":"非斯都既然定規了，叫我們坐船往意大利去，便將保羅和別的囚犯交給御營裏的一個百夫長，名叫猶流。","notes":[]},{"n":2,"t":"有一隻亞大米田的船，要沿著亞細亞一帶地方的海邊走，我們就上了那船開行；有馬其頓的帖撒羅尼迦人亞里達古和我們同去。","notes":[]},{"n":3,"t":"第二天，到了西頓；猶流寬待保羅，准他往朋友那裏去，受他們的照應。","notes":[]},{"n":4,"t":"從那裏又開船，因為風不順，就貼著塞浦路斯背風岸行去。","notes":[]},{"n":5,"t":"過了基利家、旁非利亞前面的海，就到了呂家的每拉。","notes":[]},{"n":6,"t":"在那裏，百夫長遇見一隻亞歷山大的船，要往意大利去，便叫我們上了那船。","notes":[]},{"n":7,"t":"一連多日，船行得慢，僅僅來到革尼土的對面。因為被風攔阻，就貼著克里特背風岸，從撒摩尼對面行過。","notes":[]},{"n":8,"t":"我們沿岸行走，僅僅來到一個地方，名叫佳澳；離那裏不遠，有拉西亞城。","notes":[]},{"n":9,"t":"走的日子多了，已經過了禁食的節期，行船又危險，保羅就勸眾人說：","notes":[]},{"n":10,"t":"「眾位，我看這次行船，不但貨物和船要受損傷，大遭破壞，連我們的性命也難保。」","notes":[]},{"n":11,"t":"但百夫長信從掌船的和船主，不信從保羅所說的。","notes":[]},{"n":12,"t":"且因在這海口過冬不便，船上的人就多半說，不如開船離開這地方，或者能到菲尼基過冬。菲尼基是克里特的一個海口，一面朝東北，一面朝東南。","notes":[]},{"n":13,"t":"這時，微微起了南風，他們以為得意，就起了錨，貼近克里特行去。","notes":[],"heads":["海上的風暴"]},{"n":14,"t":"不多幾時，狂風從島上撲下來；那風名叫「友拉革羅」。","notes":[]},{"n":15,"t":"船被風抓住，敵不住風，我們就任風颳去。","notes":[]},{"n":16,"t":"貼著一個小島的背風岸奔行，那島名叫高大，在那裏僅僅收住了小船。","notes":[]},{"n":17,"t":"既然把小船拉上來，就用纜索捆綁船底，又恐怕在賽耳底沙灘上擱了淺，就落下篷來，任船飄去。","notes":[]},{"n":18,"t":"我們被風浪逼得甚急，第二天眾人就把貨物拋在海裏。","notes":[]},{"n":19,"t":"到第三天，他們又親手把船上的器具拋棄了。","notes":[]},{"n":20,"t":"太陽和星辰多日不顯露，又有狂風大浪催逼，我們得救的指望就都絕了。","notes":[]},{"n":21,"t":"眾人多日沒有吃甚麼，保羅就出來站在他們中間，說：「眾位，你們本該聽我的話，不離開克里特，免得遭這樣的傷損破壞。","notes":[]},{"n":22,"t":"現在我還勸你們放心，你們的性命一個也不失喪，惟獨失喪這船。","notes":[]},{"n":23,"t":"因我所屬所事奉的神，他的使者昨夜站在我旁邊，說：","notes":[]},{"n":24,"t":"『保羅，不要害怕，你必定站在凱撒面前，並且與你同船的人，神都賜給你了。』","notes":[]},{"n":25,"t":"所以眾位可以放心，我信神他怎樣對我說，事情也要怎樣成就。","notes":[]},{"n":26,"t":"只是我們必要撞在一個島上。」","notes":[]},{"n":27,"t":"到了第十四天夜間，船在亞得里亞海飄來飄去。約到半夜，水手以為漸近旱地，","notes":[]},{"n":28,"t":"就探深淺，探得有十二丈；稍往前行，又探深淺，探得有九丈。","notes":[]},{"n":29,"t":"恐怕撞在石頭上，就從船尾拋下四個錨，盼望天亮。","notes":[]},{"n":30,"t":"水手想要逃出船去，把小船放在海裏，假作要從船頭拋錨的樣子。","notes":[]},{"n":31,"t":"保羅對百夫長和兵丁說：「這些人若不等在船上，你們必不能得救。」","notes":[]},{"n":32,"t":"於是兵丁砍斷小船的繩子，由它飄去。","notes":[]},{"n":33,"t":"天漸亮的時候，保羅勸眾人都吃飯，說：「你們懸望忍餓不吃甚麼，已經十四天了。","notes":[]},{"n":34,"t":"所以我勸你們吃飯，這是關乎你們救命的事；因為你們各人連一根頭髮也不至於損壞。」","notes":[]},{"n":35,"t":"保羅說了這話，就拿著餅，在眾人面前祝謝了神，擘開吃。","notes":[]},{"n":36,"t":"於是他們都放下心，也就吃了。","notes":[]},{"n":37,"t":"我們在船上的共有二百七十六個人。","notes":[]},{"n":38,"t":"他們吃飽了，就把船上的麥子拋在海裏，為要叫船輕一點。","notes":[]},{"n":39,"t":"到了天亮，他們不認識那地方，但見一個海灣，有岸可登，就商議能把船攏進去不能。","notes":[],"heads":["船擱了淺"]},{"n":40,"t":"於是砍斷纜索，棄錨在海裏；同時也鬆開舵繩，拉起頭篷，順著風向岸行去。","notes":[]},{"n":41,"t":"但遇著兩水夾流的地方，就把船擱了淺；船頭膠住不動，船尾被浪的猛力衝壞。","notes":[]},{"n":42,"t":"兵丁的意思要把囚犯殺了，恐怕有洑水脫逃的。","notes":[]},{"n":43,"t":"但百夫長要救保羅，不准他們任意而行，就吩咐會洑水的，跳下水去先上岸；","notes":[]},{"n":44,"t":"其餘的人可以用板子或船上的零碎東西上岸。這樣，眾人都得了救，上了岸。","notes":[]}]},"28":{"heading":"保羅在馬耳他島上","verses":[{"n":1,"t":"我們既已得救，才知道那島名叫馬耳他。","notes":[]},{"n":2,"t":"土人看待我們，有非常的情分；因為當時下雨，天氣又冷，就生火接待我們眾人。","notes":[]},{"n":3,"t":"那時，保羅拾起一捆柴，放在火上，有一條毒蛇，因為熱了出來，咬住他的手。","notes":[]},{"n":4,"t":"土人看見那毒蛇懸在他手上，就彼此說：「這人必是個兇手，雖然從海裏救上來，天理還不容他活著。」","notes":[]},{"n":5,"t":"保羅竟把那毒蛇甩在火裏，並沒有受傷。","notes":[]},{"n":6,"t":"土人想他必要腫起來，或是忽然仆倒死了；看了多時，見他無害，就轉念，說：「他是個神。」","notes":[]},{"n":7,"t":"離那地方不遠，有田產是島長部百流的；他接納我們，盡情款待三日。","notes":[]},{"n":8,"t":"當時，部百流的父親患熱病和痢疾躺著。保羅進去，為他禱告，按手在他身上，治好了他。","notes":[]},{"n":9,"t":"從此，島上其餘的病人也來，得了醫治。","notes":[]},{"n":10,"t":"他們又多方地尊敬我們；到了開船的時候，也把我們所需用的送到船上。","notes":[]},{"n":11,"t":"過了三個月，我們上了亞歷山大的船往前行；這船以「宙斯雙子」為記，是在那海島過了冬的。","notes":[],"heads":["保羅抵達羅馬"]},{"n":12,"t":"到了敘拉古，我們停泊三日；","notes":[]},{"n":13,"t":"又從那裏繞行，來到利基翁。過了一天，起了南風，第二天就來到部丟利。","notes":[]},{"n":14,"t":"在那裏遇見弟兄們，請我們與他們同住了七天。這樣，我們來到羅馬。","notes":[]},{"n":15,"t":"那裏的弟兄們一聽見我們的信息就出來，到亞比烏市和三館地方迎接我們。保羅見了他們，就感謝神，放心壯膽。","notes":[]},{"n":16,"t":"進了羅馬城，保羅蒙准和一個看守他的兵另住在一處。","notes":["有古卷加：百夫長把眾囚犯交給御營的統領，惟有"]},{"n":17,"t":"過了三天，保羅請猶太人的首領來。他們來了，就對他們說：「弟兄們，我雖沒有做甚麼事干犯本國的百姓和我們祖宗的規條，卻被鎖綁，從耶路撒冷解在羅馬人的手裏。","notes":[],"heads":["保羅在羅馬傳道"]},{"n":18,"t":"他們審問了我，就願意釋放我；因為在我身上，並沒有該死的罪。","notes":[]},{"n":19,"t":"無奈猶太人不服，我不得已，只好上告於凱撒，並非有甚麼事要控告我本國的百姓。","notes":[]},{"n":20,"t":"因此，我請你們來見面說話，我原為以色列人所指望的，被這鍊子捆鎖。」","notes":[]},{"n":21,"t":"他們說：「我們並沒有接著從猶太來論你的信，也沒有弟兄到這裏來報給我們說你有甚麼不好處。","notes":[]},{"n":22,"t":"但我們願意聽你的意見如何；因為這教門，我們曉得是到處被毀謗的。」","notes":[]},{"n":23,"t":"他們和保羅約定了日子，就有許多人到他的寓處來。保羅從早到晚，對他們講論這事，證明神國的道，引摩西的律法和先知的書，以耶穌的事勸勉他們。","notes":[]},{"n":24,"t":"他所說的話，有信的，有不信的。","notes":[]},{"n":25,"t":"他們彼此不合，就散了；未散以先，保羅說了一句話，說：「聖靈藉先知以賽亞向你們祖宗所說的話是不錯的。","notes":[]},{"n":26,"t":"他說：你去告訴這百姓說：你們聽是要聽見，卻不明白；看是要看見，卻不曉得；","notes":[]},{"n":27,"t":"因為這百姓油蒙了心，耳朵發沉，眼睛閉著；恐怕眼睛看見，耳朵聽見，心裏明白，回轉過來，我就醫治他們。","notes":[]},{"n":28,"t":"所以你們當知道，神這救恩，如今傳給外邦人，他們也必聽受。」","notes":["有古卷加：29_保羅_說了這話，_猶太_人議論紛紛地就走了。"]},{"n":30,"t":"保羅在自己所租的房子裏住了足足兩年。凡來見他的人，他全都接待，","notes":[]},{"n":31,"t":"放膽傳講神國的道，將主耶穌基督的事教導人，並沒有人禁止。","notes":[]}]}},"ROM":{"1":{"heading":"祝福","verses":[{"n":1,"t":"耶穌基督的僕人保羅，奉召為使徒，特派傳神的福音。","notes":[]},{"n":2,"t":"這福音是神從前藉眾先知在聖經上所應許的，","notes":[]},{"n":3,"t":"論到他兒子－我主耶穌基督。按肉體說，是從大衛後裔生的；","notes":[]},{"n":4,"t":"按聖善的靈說，因從死裏復活，以大能顯明是神的兒子。","notes":[]},{"n":5,"t":"我們從他受了恩惠並使徒的職分，在萬國之中叫人為他的名信服真道；","notes":[]},{"n":6,"t":"其中也有你們這蒙召屬耶穌基督的人。","notes":[]},{"n":7,"t":"我寫信給你們在羅馬、為神所愛、奉召作聖徒的眾人。願恩惠、平安從我們的父神並主耶穌基督歸與你們！","notes":[]},{"n":8,"t":"第一，我靠著耶穌基督，為你們眾人感謝我的神，因你們的信德傳遍了天下。","notes":[],"heads":["保羅有意訪問羅馬"]},{"n":9,"t":"我在他兒子福音上，用心靈所事奉的神可以見證，我怎樣不住地提到你們；","notes":[]},{"n":10,"t":"在禱告之間常常懇求，或者照神的旨意，終能得平坦的道路往你們那裏去。","notes":[]},{"n":11,"t":"因為我切切地想見你們，要把些屬靈的恩賜分給你們，使你們可以堅固；","notes":[]},{"n":12,"t":"這樣，我在你們中間，因你與我彼此的信心，就可以同得安慰。","notes":[]},{"n":13,"t":"弟兄們，我不願意你們不知道，我屢次定意往你們那裏去，要在你們中間得些果子，如同在其餘的外邦人中一樣；只是到如今仍有阻隔。","notes":[]},{"n":14,"t":"無論是希臘人、化外人、聰明人、愚拙人，我都欠他們的債，","notes":[]},{"n":15,"t":"所以情願盡我的力量，將福音也傳給你們在羅馬的人。","notes":[]},{"n":16,"t":"我不以福音為恥；這福音本是神的大能，要救一切相信的，先是猶太人，後是希臘人。","notes":[],"heads":["福音是神的大能"]},{"n":17,"t":"因為神的義正在這福音上顯明出來；這義是本於信，以至於信。如經上所記：「義人必因信得生。」","notes":[]},{"n":18,"t":"原來，神的忿怒從天上顯明在一切不虔不義的人身上，就是那些行不義阻擋真理的人。","notes":[],"heads":["人類的罪惡"]},{"n":19,"t":"神的事情，人所能知道的，原顯明在人心裏，因為神已經給他們顯明。","notes":[]},{"n":20,"t":"自從造天地以來，神的永能和神性是明明可知的，雖是眼不能見，但藉著所造之物就可以曉得，叫人無可推諉。","notes":[]},{"n":21,"t":"因為，他們雖然知道神，卻不當作神榮耀他，也不感謝他。他們的思念變為虛妄，無知的心就昏暗了。","notes":[]},{"n":22,"t":"自稱為聰明，反成了愚拙，","notes":[]},{"n":23,"t":"將不能朽壞之神的榮耀變為偶像，彷彿必朽壞的人和飛禽、走獸、昆蟲的樣式。","notes":[]},{"n":24,"t":"所以，神任憑他們逞著心裏的情慾行污穢的事，以致彼此玷辱自己的身體。","notes":[]},{"n":25,"t":"他們將神的真實變為虛謊，去敬拜事奉受造之物，不敬奉那造物的主－主乃是可稱頌的，直到永遠。阿們！","notes":[]},{"n":26,"t":"因此，神任憑他們放縱可羞恥的情慾。他們的女人把順性的用處變為逆性的用處；","notes":[]},{"n":27,"t":"男人也是如此，棄了女人順性的用處，慾火攻心，彼此貪戀，男和男行可羞恥的事，就在自己身上受這妄為當得的報應。","notes":[]},{"n":28,"t":"他們既然故意不認識神，神就任憑他們存邪僻的心，行那些不合理的事；","notes":[]},{"n":29,"t":"裝滿了各樣不義、邪惡、貪婪、惡毒；滿心是嫉妒、凶殺、爭競、詭詐、毒恨；","notes":["或譯：陰毒"]},{"n":30,"t":"又是讒毀的、背後說人的、怨恨神的、侮慢人的、狂傲的、自誇的、捏造惡事的、違背父母的、","notes":["或譯：被神所憎惡的"]},{"n":31,"t":"無知的、背約的、無親情的、不憐憫人的。","notes":[]},{"n":32,"t":"他們雖知道神判定行這樣事的人是當死的，然而他們不但自己去行，還喜歡別人去行。","notes":[]}]},"2":{"heading":"神的公義判斷","verses":[{"n":1,"t":"你這論斷人的，無論你是誰，也無可推諉。你在甚麼事上論斷人，就在甚麼事上定自己的罪；因你這論斷人的，自己所行卻和別人一樣。","notes":[]},{"n":2,"t":"我們知道這樣行的人，神必照真理審判他。","notes":[]},{"n":3,"t":"你這人哪，你論斷行這樣事的人，自己所行的卻和別人一樣，你以為能逃脫神的審判嗎？","notes":[]},{"n":4,"t":"還是你藐視他豐富的恩慈、寬容、忍耐，不曉得他的恩慈是領你悔改呢？","notes":[]},{"n":5,"t":"你竟任著你剛硬不悔改的心，為自己積蓄忿怒，以致神震怒，顯他公義審判的日子來到。","notes":[]},{"n":6,"t":"他必照各人的行為報應各人。","notes":[]},{"n":7,"t":"凡恆心行善、尋求榮耀、尊貴和不能朽壞之福的，就以永生報應他們；","notes":[]},{"n":8,"t":"惟有結黨、不順從真理、反順從不義的，就以忿怒、惱恨報應他們；","notes":[]},{"n":9,"t":"將患難、困苦加給一切作惡的人，先是猶太人，後是希臘人，","notes":[]},{"n":10,"t":"卻將榮耀、尊貴、平安加給一切行善的人，先是猶太人，後是希臘人。","notes":[]},{"n":11,"t":"因為神不偏待人。","notes":[]},{"n":12,"t":"凡沒有律法犯了罪的，也必不按律法滅亡；凡在律法以下犯了罪的，也必按律法受審判。（","notes":[]},{"n":13,"t":"原來在神面前，不是聽律法的為義，乃是行律法的稱義。","notes":[]},{"n":14,"t":"沒有律法的外邦人若順著本性行律法上的事，他們雖然沒有律法，自己就是自己的律法。","notes":[]},{"n":15,"t":"這是顯出律法的功用刻在他們心裏，他們是非之心同作見證，並且他們的思念互相較量，或以為是，或以為非。）","notes":[]},{"n":16,"t":"就在神藉耶穌基督審判人隱祕事的日子，照著我的福音所言。","notes":[]},{"n":17,"t":"你稱為猶太人，又倚靠律法，且指著神誇口；","notes":[],"heads":["猶太人與律法"]},{"n":18,"t":"既從律法中受了教訓，就曉得神的旨意，也能分別是非；","notes":["或譯：也喜愛那美好的事"]},{"n":19,"t":"又深信自己是給瞎子領路的，是黑暗中人的光，","notes":[]},{"n":20,"t":"是蠢笨人的師傅，是小孩子的先生，在律法上有知識和真理的模範。","notes":[]},{"n":21,"t":"你既是教導別人，還不教導自己嗎？你講說人不可偷竊，自己還偷竊嗎？","notes":[]},{"n":22,"t":"你說人不可姦淫，自己還姦淫嗎？你厭惡偶像，自己還偷竊廟中之物嗎？","notes":[]},{"n":23,"t":"你指著律法誇口，自己倒犯律法、玷辱神嗎？","notes":[]},{"n":24,"t":"神的名在外邦人中，因你們受了褻瀆，正如經上所記的。","notes":[]},{"n":25,"t":"你若是行律法的，割禮固然於你有益；若是犯律法的，你的割禮就算不得割禮。","notes":[]},{"n":26,"t":"所以那未受割禮的，若遵守律法的條例，他雖然未受割禮，豈不算是有割禮嗎？","notes":[]},{"n":27,"t":"而且那本來未受割禮的，若能全守律法，豈不是要審判你這有儀文和割禮竟犯律法的人嗎？","notes":[]},{"n":28,"t":"因為外面作猶太人的，不是真猶太人；外面肉身的割禮，也不是真割禮。","notes":[]},{"n":29,"t":"惟有裏面作的，才是真猶太人；真割禮也是心裏的，在乎靈，不在乎儀文。這人的稱讚不是從人來的，乃是從神來的。","notes":[]}]},"3":{"heading":"沒有義人","verses":[{"n":1,"t":"這樣說來，猶太人有甚麼長處？割禮有甚麼益處呢？","notes":[]},{"n":2,"t":"凡事大有好處：第一是神的聖言交託他們。","notes":[]},{"n":3,"t":"即便有不信的，這有何妨呢？難道他們的不信就廢掉神的信嗎？","notes":[]},{"n":4,"t":"斷乎不能！不如說，神是真實的，人都是虛謊的。如經上所記：你責備人的時候，顯為公義；被人議論的時候，可以得勝。","notes":[]},{"n":5,"t":"我且照著人的常話說，我們的不義若顯出神的義來，我們可以怎麼說呢？神降怒，是他不義嗎？","notes":[]},{"n":6,"t":"斷乎不是！若是這樣，神怎能審判世界呢？","notes":[]},{"n":7,"t":"若神的真實，因我的虛謊越發顯出他的榮耀，為甚麼我還受審判，好像罪人呢？","notes":[]},{"n":8,"t":"為甚麼不說，我們可以作惡以成善呢？這是毀謗我們的人說我們有這話。這等人定罪是該當的。","notes":[]},{"n":9,"t":"這卻怎麼樣呢？我們比他們強嗎？決不是的！因我們已經證明：猶太人和希臘人都在罪惡之下。","notes":[]},{"n":10,"t":"就如經上所記：沒有義人，連一個也沒有。","notes":[]},{"n":11,"t":"沒有明白的；沒有尋求神的；","notes":[]},{"n":12,"t":"都是偏離正路，一同變為無用。沒有行善的，連一個也沒有。","notes":[]},{"n":13,"t":"他們的喉嚨是敞開的墳墓；他們用舌頭弄詭詐，嘴唇裏有虺蛇的毒氣，","notes":[]},{"n":14,"t":"滿口是咒罵苦毒。","notes":[]},{"n":15,"t":"殺人流血，他們的腳飛跑，","notes":[]},{"n":16,"t":"所經過的路便行殘害暴虐的事。","notes":[]},{"n":17,"t":"平安的路，他們未曾知道；","notes":[]},{"n":18,"t":"他們眼中不怕神。","notes":[]},{"n":19,"t":"我們曉得律法上的話都是對律法以下之人說的，好塞住各人的口，叫普世的人都伏在神審判之下。","notes":[]},{"n":20,"t":"所以凡有血氣的，沒有一個因行律法能在神面前稱義，因為律法本是叫人知罪。","notes":[]},{"n":21,"t":"但如今，神的義在律法以外已經顯明出來，有律法和先知為證：","notes":[],"heads":["因信稱義"]},{"n":22,"t":"就是神的義，因信耶穌基督加給一切相信的人，並沒有分別。","notes":[]},{"n":23,"t":"因為世人都犯了罪，虧缺了神的榮耀；","notes":[]},{"n":24,"t":"如今卻蒙神的恩典，因基督耶穌的救贖，就白白地稱義。","notes":[]},{"n":25,"t":"神設立耶穌作挽回祭，是憑著耶穌的血，藉著人的信，要顯明神的義；因為他用忍耐的心寬容人先時所犯的罪，","notes":[]},{"n":26,"t":"好在今時顯明他的義，使人知道他自己為義，也稱信耶穌的人為義。","notes":[]},{"n":27,"t":"既是這樣，哪裏能誇口呢？沒有可誇的了。用何法沒有的呢？是用立功之法嗎？不是，乃用信主之法。","notes":[]},{"n":28,"t":"所以我們看定了：人稱義是因著信，不在乎遵行律法。","notes":["有古卷：因為"]},{"n":29,"t":"難道神只作猶太人的神嗎？不也是作外邦人的神嗎？是的，也作外邦人的神。","notes":[]},{"n":30,"t":"神既是一位，他就要因信稱那受割禮的為義，也要因信稱那未受割禮的為義。","notes":[]},{"n":31,"t":"這樣，我們因信廢了律法嗎？斷乎不是！更是堅固律法。","notes":[]}]},"4":{"heading":"以亞伯拉罕為例","verses":[{"n":1,"t":"如此說來，我們的祖宗亞伯拉罕憑著肉體得了甚麼呢？","notes":[]},{"n":2,"t":"倘若亞伯拉罕是因行為稱義，就有可誇的；只是在神面前並無可誇。","notes":[]},{"n":3,"t":"經上說甚麼呢？說：「亞伯拉罕信神，這就算為他的義。」","notes":[]},{"n":4,"t":"做工的得工價，不算恩典，乃是該得的；","notes":[]},{"n":5,"t":"惟有不做工的，只信稱罪人為義的神，他的信就算為義。","notes":[]},{"n":6,"t":"正如大衛稱那在行為以外蒙神算為義的人是有福的。","notes":[]},{"n":7,"t":"他說：得赦免其過、遮蓋其罪的，這人是有福的。","notes":[]},{"n":8,"t":"主不算為有罪的，這人是有福的。","notes":[]},{"n":9,"t":"如此看來，這福是單加給那受割禮的人嗎？不也是加給那未受割禮的人嗎？因我們所說，亞伯拉罕的信，就算為他的義，","notes":[]},{"n":10,"t":"是怎麼算的呢？是在他受割禮的時候呢？是在他未受割禮的時候呢？不是在受割禮的時候，乃是在未受割禮的時候。","notes":[]},{"n":11,"t":"並且他受了割禮的記號，作他未受割禮的時候因信稱義的印證，叫他作一切未受割禮而信之人的父，使他們也算為義；","notes":[]},{"n":12,"t":"又作受割禮之人的父，就是那些不但受割禮，並且按我們的祖宗亞伯拉罕未受割禮而信之蹤跡去行的人。","notes":[]},{"n":13,"t":"因為神應許亞伯拉罕和他後裔，必得承受世界，不是因律法，乃是因信而得的義。","notes":[],"heads":["應許因信而實現"]},{"n":14,"t":"若是屬乎律法的人才得為後嗣，信就歸於虛空，應許也就廢棄了。","notes":[]},{"n":15,"t":"因為律法是惹動忿怒的；哪裏沒有律法，那裏就沒有過犯。","notes":["或譯：叫人受刑的"]},{"n":16,"t":"所以人得為後嗣是本乎信，因此就屬乎恩，叫應許定然歸給一切後裔；不但歸給那屬乎律法的，也歸給那效法亞伯拉罕之信的。","notes":[]},{"n":17,"t":"亞伯拉罕所信的，是那叫死人復活、使無變為有的神，他在主面前作我們世人的父。如經上所記：「我已經立你作多國的父。」","notes":[]},{"n":18,"t":"他在無可指望的時候，因信仍有指望，就得以作多國的父，正如先前所說：「你的後裔將要如此。」","notes":[]},{"n":19,"t":"他將近百歲的時候，雖然想到自己的身體如同已死，撒拉的生育已經斷絕，他的信心還是不軟弱；","notes":[]},{"n":20,"t":"並且仰望神的應許，總沒有因不信心裏起疑惑，反倒因信心裏得堅固，將榮耀歸給神，","notes":[]},{"n":21,"t":"且滿心相信神所應許的必能做成。","notes":[]},{"n":22,"t":"所以，這就算為他的義。","notes":[]},{"n":23,"t":"「算為他義」的這句話不是單為他寫的，","notes":[]},{"n":24,"t":"也是為我們將來得算為義之人寫的，就是我們這信神使我們的主耶穌從死裏復活的人。","notes":[]},{"n":25,"t":"耶穌被交給人，是為我們的過犯；復活，是為叫我們稱義。","notes":["或譯：耶穌是為我們的過犯交付了，是為我們稱義復活了"]}]},"5":{"heading":"因信稱義的福","verses":[{"n":1,"t":"我們既因信稱義，就藉著我們的主耶穌基督得與神相和。","notes":[]},{"n":2,"t":"我們又藉著他，因信得進入現在所站的這恩典中，並且歡歡喜喜盼望神的榮耀。","notes":[]},{"n":3,"t":"不但如此，就是在患難中也是歡歡喜喜的；因為知道患難生忍耐，","notes":[]},{"n":4,"t":"忍耐生老練，老練生盼望；","notes":[]},{"n":5,"t":"盼望不至於羞恥，因為所賜給我們的聖靈將神的愛澆灌在我們心裏。","notes":[]},{"n":6,"t":"因我們還軟弱的時候，基督就按所定的日期為罪人死。","notes":[]},{"n":7,"t":"為義人死，是少有的；為仁人死， 或者有敢做的。","notes":[]},{"n":8,"t":"惟有基督在我們還作罪人的時候為我們死，神的愛就在此向我們顯明了。","notes":[]},{"n":9,"t":"現在我們既靠著他的血稱義，就更要藉著他免去神的忿怒。","notes":[]},{"n":10,"t":"因為我們作仇敵的時候，且藉著神兒子的死，得與神和好；既已和好，就更要因他的生得救了。","notes":[]},{"n":11,"t":"不但如此，我們既藉著我主耶穌基督得與神和好，也就藉著他以神為樂。","notes":[]},{"n":12,"t":"這就如罪是從一人入了世界，死又是從罪來的，於是死就臨到眾人，因為眾人都犯了罪。","notes":[],"heads":["亞當和基督"]},{"n":13,"t":"沒有律法之先，罪已經在世上；但沒有律法，罪也不算罪。","notes":[]},{"n":14,"t":"然而從亞當到摩西，死就作了王，連那些不與亞當犯一樣罪過的，也在他的權下。亞當乃是那以後要來之人的預像。","notes":[]},{"n":15,"t":"只是過犯不如恩賜，若因一人的過犯，眾人都死了，何況神的恩典，與那因耶穌基督一人恩典中的賞賜，豈不更加倍地臨到眾人嗎？","notes":[]},{"n":16,"t":"因一人犯罪就定罪，也不如恩賜，原來審判是由一人而定罪，恩賜乃是由許多過犯而稱義。","notes":[]},{"n":17,"t":"若因一人的過犯，死就因這一人作了王，何況那些受洪恩又蒙所賜之義的，豈不更要因耶穌基督一人在生命中作王嗎？","notes":[]},{"n":18,"t":"如此說來，因一次的過犯，眾人都被定罪；照樣，因一次的義行，眾人也就被稱義得生命了。","notes":[]},{"n":19,"t":"因一人的悖逆，眾人成為罪人；照樣，因一人的順從，眾人也成為義了。","notes":[]},{"n":20,"t":"律法本是外添的，叫過犯顯多；只是罪在哪裏顯多，恩典就更顯多了。","notes":[]},{"n":21,"t":"就如罪作王叫人死；照樣，恩典也藉著義作王，叫人因我們的主耶穌基督得永生。","notes":[]}]},"6":{"heading":"在罪上死，在基督裏活","verses":[{"n":1,"t":"這樣，怎麼說呢？我們可以仍在罪中、叫恩典顯多嗎？","notes":[]},{"n":2,"t":"斷乎不可！我們在罪上死了的人豈可仍在罪中活著呢？","notes":[]},{"n":3,"t":"豈不知我們這受洗歸入基督耶穌的人是受洗歸入他的死嗎？","notes":[]},{"n":4,"t":"所以，我們藉著洗禮歸入死，和他一同埋葬，原是叫我們一舉一動有新生的樣式，像基督藉著父的榮耀從死裏復活一樣。","notes":[]},{"n":5,"t":"我們若在他死的形狀上與他聯合，也要在他復活的形狀上與他聯合；","notes":[]},{"n":6,"t":"因為知道我們的舊人和他同釘十字架，使罪身滅絕，叫我們不再作罪的奴僕；","notes":[]},{"n":7,"t":"因為已死的人是脫離了罪。","notes":[]},{"n":8,"t":"我們若是與基督同死，就信必與他同活。","notes":[]},{"n":9,"t":"因為知道基督既從死裏復活，就不再死，死也不再作他的主了。","notes":[]},{"n":10,"t":"他死是向罪死了，只有一次；他活是向神活著。","notes":[]},{"n":11,"t":"這樣，你們向罪也當看自己是死的；向神在基督耶穌裏，卻當看自己是活的。","notes":[]},{"n":12,"t":"所以，不要容罪在你們必死的身上作王，使你們順從身子的私慾。","notes":[]},{"n":13,"t":"也不要將你們的肢體獻給罪作不義的器具；倒要像從死裏復活的人，將自己獻給神，並將肢體作義的器具獻給神。","notes":[]},{"n":14,"t":"罪必不能作你們的主；因你們不在律法之下，乃在恩典之下。","notes":[]},{"n":15,"t":"這卻怎麼樣呢？我們在恩典之下，不在律法之下，就可以犯罪嗎？斷乎不可！","notes":[],"heads":["義的奴僕"]},{"n":16,"t":"豈不曉得你們獻上自己作奴僕，順從誰，就作誰的奴僕嗎？或作罪的奴僕，以至於死；或作順命的奴僕，以致成義。","notes":[]},{"n":17,"t":"感謝神！因為你們從前雖然作罪的奴僕，現今卻從心裏順服了所傳給你們道理的模範。","notes":[]},{"n":18,"t":"你們既從罪裏得了釋放，就作了義的奴僕。","notes":[]},{"n":19,"t":"我因你們肉體的軟弱，就照人的常話對你們說。你們從前怎樣將肢體獻給不潔不法作奴僕，以至於不法；現今也要照樣將肢體獻給義作奴僕，以至於成聖。","notes":[]},{"n":20,"t":"因為你們作罪之奴僕的時候，就不被義約束了。","notes":[]},{"n":21,"t":"你們現今所看為羞恥的事，當日有甚麼果子呢？那些事的結局就是死。","notes":[]},{"n":22,"t":"但現今，你們既從罪裏得了釋放，作了神的奴僕，就有成聖的果子，那結局就是永生。","notes":[]},{"n":23,"t":"因為罪的工價乃是死；惟有神的恩賜，在我們的主基督耶穌裏，乃是永生。","notes":[]}]},"7":{"heading":"以婚姻關係為例","verses":[{"n":1,"t":"弟兄們，我現在對明白律法的人說，你們豈不曉得律法管人是在活著的時候嗎？","notes":[]},{"n":2,"t":"就如女人有了丈夫，丈夫還活著，就被律法約束；丈夫若死了，就脫離了丈夫的律法。","notes":[]},{"n":3,"t":"所以丈夫活著，她若歸於別人，便叫淫婦；丈夫若死了，她就脫離了丈夫的律法，雖然歸於別人，也不是淫婦。","notes":[]},{"n":4,"t":"我的弟兄們，這樣說來，你們藉著基督的身體，在律法上也是死了，叫你們歸於別人，就是歸於那從死裏復活的，叫我們結果子給神。","notes":[]},{"n":5,"t":"因為我們屬肉體的時候，那因律法而生的惡慾就在我們肢體中發動，以致結成死亡的果子。","notes":[]},{"n":6,"t":"但我們既然在捆我們的律法上死了，現今就脫離了律法，叫我們服事主，要按著心靈的新樣，不按著儀文的舊樣。","notes":["心靈：或譯聖靈"]},{"n":7,"t":"這樣，我們可說甚麼呢？律法是罪嗎？斷乎不是！只是非因律法，我就不知何為罪。非律法說「不可起貪心」，我就不知何為貪心。","notes":[],"heads":["內在的罪"]},{"n":8,"t":"然而，罪趁著機會， 就藉著誡命叫諸般的貪心在我裏頭發動；因為沒有律法，罪是死的。","notes":[]},{"n":9,"t":"我以前沒有律法是活著的；但是誡命來到，罪又活了，我就死了。","notes":[]},{"n":10,"t":"那本來叫人活的誡命，反倒叫我死；","notes":[]},{"n":11,"t":"因為罪趁著機會， 就藉著誡命引誘我，並且殺了我。","notes":[]},{"n":12,"t":"這樣看來，律法是聖潔的，誡命也是聖潔、公義、良善的。","notes":[]},{"n":13,"t":"既然如此，那良善的是叫我死嗎？斷乎不是！叫我死的乃是罪。但罪藉著那良善的叫我死，就顯出真是罪，叫罪因著誡命更顯出是惡極了。","notes":[]},{"n":14,"t":"我們原曉得律法是屬乎靈的，但我是屬乎肉體的，是已經賣給罪了。","notes":[]},{"n":15,"t":"因為我所做的，我自己不明白；我所願意的，我並不做；我所恨惡的，我倒去做。","notes":[]},{"n":16,"t":"若我所做的，是我所不願意的，我就應承律法是善的。","notes":[]},{"n":17,"t":"既是這樣，就不是我做的，乃是住在我裏頭的罪做的。","notes":[]},{"n":18,"t":"我也知道，在我裏頭，就是我肉體之中，沒有良善。因為，立志為善由得我，只是行出來由不得我。","notes":[]},{"n":19,"t":"故此，我所願意的善，我反不做；我所不願意的惡，我倒去做。","notes":[]},{"n":20,"t":"若我去做所不願意做的，就不是我做的，乃是住在我裏頭的罪做的。","notes":[]},{"n":21,"t":"我覺得有個律，就是我願意為善的時候，便有惡與我同在。","notes":[]},{"n":22,"t":"因為按著我裏面的意思，我是喜歡神的律；","notes":["原文是人"]},{"n":23,"t":"但我覺得肢體中另有個律和我心中的律交戰，把我擄去，叫我附從那肢體中犯罪的律。","notes":[]},{"n":24,"t":"我真是苦啊！誰能救我脫離這取死的身體呢？","notes":[]},{"n":25,"t":"感謝神，靠著我們的主耶穌基督就能脫離了。這樣看來，我以內心順服神的律，我肉體卻順服罪的律了。","notes":[]}]},"8":{"heading":"在聖靈裏的生活","verses":[{"n":1,"t":"如今，那些在基督耶穌裏的就不定罪了。","notes":[]},{"n":2,"t":"因為賜生命聖靈的律，在基督耶穌裏釋放了我，使我脫離罪和死的律了。","notes":[]},{"n":3,"t":"律法既因肉體軟弱，有所不能行的，神就差遣自己的兒子，成為罪身的形狀，作了贖罪祭，在肉體中定了罪案，","notes":[]},{"n":4,"t":"使律法的義成就在我們這不隨從肉體、只隨從聖靈的人身上。","notes":[]},{"n":5,"t":"因為，隨從肉體的人體貼肉體的事；隨從聖靈的人體貼聖靈的事。","notes":[]},{"n":6,"t":"體貼肉體的，就是死；體貼聖靈的，乃是生命、平安。","notes":[]},{"n":7,"t":"原來體貼肉體的，就是與神為仇；因為不服神的律法，也是不能服，","notes":[]},{"n":8,"t":"而且屬肉體的人不能得神的喜歡。","notes":[]},{"n":9,"t":"如果神的靈住在你們心裏，你們就不屬肉體，乃屬聖靈了。人若沒有基督的靈，就不是屬基督的。","notes":[]},{"n":10,"t":"基督若在你們心裏，身體就因罪而死，心靈卻因義而活。","notes":[]},{"n":11,"t":"然而，叫耶穌從死裏復活者的靈若住在你們心裏，那叫基督耶穌從死裏復活的，也必藉著住在你們心裏的聖靈，使你們必死的身體又活過來。","notes":[]},{"n":12,"t":"弟兄們，這樣看來，我們並不是欠肉體的債去順從肉體活著。","notes":[]},{"n":13,"t":"你們若順從肉體活著，必要死；若靠著聖靈治死身體的惡行，必要活著。","notes":[]},{"n":14,"t":"因為凡被神的靈引導的，都是神的兒子。","notes":[]},{"n":15,"t":"你們所受的，不是奴僕的心，仍舊害怕；所受的，乃是兒子的心，因此我們呼叫：「阿爸！父！」","notes":[]},{"n":16,"t":"聖靈與我們的心同證我們是神的兒女；","notes":[]},{"n":17,"t":"既是兒女，便是後嗣，就是神的後嗣，和基督同作後嗣。如果我們和他一同受苦，也必和他一同得榮耀。","notes":[]},{"n":18,"t":"我想，現在的苦楚若比起將來要顯於我們的榮耀就不足介意了。","notes":[],"heads":["將來的榮耀"]},{"n":19,"t":"受造之物切望等候神的眾子顯出來。","notes":[]},{"n":20,"t":"因為受造之物服在虛空之下，不是自己願意，乃是因那叫他如此的。","notes":[]},{"n":21,"t":"但受造之物仍然指望脫離敗壞的轄制，得享神兒女自由的榮耀。","notes":["享：原文是入"]},{"n":22,"t":"我們知道，一切受造之物一同歎息，勞苦，直到如今。","notes":[]},{"n":23,"t":"不但如此，就是我們這有聖靈初結果子的，也是自己心裏歎息，等候得著兒子的名分，乃是我們的身體得贖。","notes":[]},{"n":24,"t":"我們得救是在乎盼望；只是所見的盼望不是盼望，誰還盼望他所見的呢？","notes":["有古卷：人所看見的何必再盼望呢"]},{"n":25,"t":"但我們若盼望那所不見的，就必忍耐等候。","notes":[]},{"n":26,"t":"況且，我們的軟弱有聖靈幫助；我們本不曉得當怎樣禱告，只是聖靈親自用說不出來的歎息替我們禱告。","notes":[]},{"n":27,"t":"鑒察人心的，曉得聖靈的意思，因為聖靈照著神的旨意替聖徒祈求。","notes":[]},{"n":28,"t":"我們曉得萬事都互相效力，叫愛神的人得益處，就是按他旨意被召的人。","notes":[]},{"n":29,"t":"因為他預先所知道的人，就預先定下效法他兒子的模樣，使他兒子在許多弟兄中作長子。","notes":[]},{"n":30,"t":"預先所定下的人又召他們來；所召來的人又稱他們為義；所稱為義的人又叫他們得榮耀。","notes":[]},{"n":31,"t":"既是這樣，還有甚麼說的呢？神若幫助我們，誰能敵擋我們呢？","notes":[],"heads":["神的愛"]},{"n":32,"t":"神既不愛惜自己的兒子，為我們眾人捨了，豈不也把萬物和他一同白白地賜給我們嗎？","notes":[]},{"n":33,"t":"誰能控告神所揀選的人呢？有神稱他們為義了。","notes":["或譯：是稱他們為義的神嗎"]},{"n":34,"t":"誰能定他們的罪呢？有基督耶穌已經死了，而且從死裏復活，現今在神的右邊，也替我們祈求。","notes":["有基督<ins>.</ins>.或譯：是已經死了，而且從死裏復活，現今在神的右邊，也替我們祈求的基督耶穌嗎"]},{"n":35,"t":"誰能使我們與基督的愛隔絕呢？難道是患難嗎？是困苦嗎？是逼迫嗎？是飢餓嗎？是赤身露體嗎？是危險嗎？是刀劍嗎？","notes":[]},{"n":36,"t":"如經上所記：我們為你的緣故終日被殺；人看我們如將宰的羊。","notes":[]},{"n":37,"t":"然而，靠著愛我們的主，在這一切的事上已經得勝有餘了。","notes":[]},{"n":38,"t":"因為我深信無論是死，是生，是天使，是掌權的，是有能的，是現在的事，是將來的事，","notes":[]},{"n":39,"t":"是高處的，是低處的，是別的受造之物，都不能叫我們與神的愛隔絕；這愛是在我們的主基督耶穌裏的。","notes":[]}]},"9":{"heading":"神揀選以色列人","verses":[{"n":1,"t":"我在基督裏說真話，並不謊言，有我良心被聖靈感動，給我作見證：","notes":[]},{"n":2,"t":"我是大有憂愁，心裏時常傷痛；","notes":[]},{"n":3,"t":"為我弟兄，我骨肉之親，就是自己被咒詛，與基督分離，我也願意。","notes":[]},{"n":4,"t":"他們是以色列人；那兒子的名分、榮耀、諸約、律法、禮儀、應許都是他們的。","notes":[]},{"n":5,"t":"列祖就是他們的祖宗；按肉體說，基督也是從他們出來的。他是在萬有之上，永遠可稱頌的神。阿們！","notes":[]},{"n":6,"t":"這不是說神的話落了空。因為從以色列生的不都是以色列人，","notes":[]},{"n":7,"t":"也不因為是亞伯拉罕的後裔就都作他的兒女；惟獨「從以撒生的才要稱為你的後裔。」","notes":[]},{"n":8,"t":"這就是說，肉身所生的兒女不是神的兒女，惟獨那應許的兒女才算是後裔。","notes":[]},{"n":9,"t":"因為所應許的話是這樣說：「到明年這時候我要來，撒拉必生一個兒子。」","notes":[]},{"n":10,"t":"不但如此，還有利百加，既從一個人，就是從我們的祖宗以撒懷了孕，（","notes":[]},{"n":11,"t":"雙子還沒有生下來，善惡還沒有做出來，只因要顯明神揀選人的旨意，不在乎人的行為，乃在乎召人的主。）","notes":[]},{"n":12,"t":"神就對利百加說：「將來，大的要服事小的。」","notes":[]},{"n":13,"t":"正如經上所記：雅各是我所愛的；以掃是我所惡的。","notes":[]},{"n":14,"t":"這樣，我們可說甚麼呢？難道神有甚麼不公平嗎？斷乎沒有！","notes":[]},{"n":15,"t":"因他對摩西說：我要憐憫誰就憐憫誰，要恩待誰就恩待誰。","notes":[]},{"n":16,"t":"據此看來，這不在乎那定意的，也不在乎那奔跑的，只在乎發憐憫的神。","notes":[]},{"n":17,"t":"因為經上有話向法老說：「我將你興起來，特要在你身上彰顯我的權能，並要使我的名傳遍天下。」","notes":[]},{"n":18,"t":"如此看來，神要憐憫誰就憐憫誰，要叫誰剛硬就叫誰剛硬。","notes":[]},{"n":19,"t":"這樣，你必對我說：「他為甚麼還指責人呢？有誰抗拒他的旨意呢？」","notes":[],"heads":["神的忿怒和憐憫"]},{"n":20,"t":"你這個人哪，你是誰，竟敢向神強嘴呢？受造之物豈能對造他的說：「你為甚麼這樣造我呢？」","notes":[]},{"n":21,"t":"窯匠難道沒有權柄從一團泥裏拿一塊做成貴重的器皿，又拿一塊做成卑賤的器皿嗎？","notes":[]},{"n":22,"t":"倘若神要顯明他的忿怒，彰顯他的權能，就多多忍耐寬容那可怒、預備遭毀滅的器皿，","notes":[]},{"n":23,"t":"又要將他豐盛的榮耀彰顯在那蒙憐憫、早預備得榮耀的器皿上。","notes":[]},{"n":24,"t":"這器皿就是我們被神所召的，不但是從猶太人中，也是從外邦人中。這有甚麼不可呢？","notes":[]},{"n":25,"t":"就像神在何西阿書上說：那本來不是我子民的，我要稱為「我的子民」；本來不是蒙愛的，我要稱為「蒙愛的」。","notes":[]},{"n":26,"t":"從前在甚麼地方對他們說：你們不是我的子民，將來就在那裏稱他們為「永生神的兒子」。","notes":[]},{"n":27,"t":"以賽亞指著以色列人喊著說：「以色列人雖多如海沙，得救的不過是剩下的餘數；","notes":[]},{"n":28,"t":"因為主要在世上施行他的話，叫他的話都成全，速速地完結。」","notes":[]},{"n":29,"t":"又如以賽亞先前說過：若不是萬軍之主給我們存留餘種，我們早已像所多瑪、蛾摩拉的樣子了。","notes":[]},{"n":30,"t":"這樣，我們可說甚麼呢？那本來不追求義的外邦人反得了義，就是因信而得的義。","notes":[],"heads":["以色列人和福音"]},{"n":31,"t":"但以色列人追求律法的義，反得不著律法的義。","notes":[]},{"n":32,"t":"這是甚麼緣故呢？是因為他們不憑著信心求，只憑著行為求；他們正跌在那絆腳石上。","notes":[]},{"n":33,"t":"就如經上所記：我在錫安放一塊絆腳的石頭，跌人的磐石；信靠他的人必不至於羞愧。","notes":[]}]},"10":{"heading":"求告主名的必要得救","verses":[{"n":1,"t":"弟兄們，我心裏所願的，向神所求的，是要以色列人得救。","notes":[]},{"n":2,"t":"我可以證明，他們向神有熱心，但不是按著真知識；","notes":[]},{"n":3,"t":"因為不知道神的義，想要立自己的義，就不服神的義了。","notes":[]},{"n":4,"t":"律法的總結就是基督，使凡信他的都得著義。","notes":[]},{"n":5,"t":"摩西寫著說：「人若行那出於律法的義，就必因此活著。」","notes":[]},{"n":6,"t":"惟有出於信心的義如此說：「你不要心裏說：誰要升到天上去呢？（就是要領下基督來；）","notes":[]},{"n":7,"t":"誰要下到陰間去呢？（就是要領基督從死裏上來。）」","notes":[]},{"n":8,"t":"他到底怎麼說呢？他說：這道離你不遠，正在你口裏，在你心裏－（就是我們所傳信主的道。）","notes":[]},{"n":9,"t":"你若口裏認耶穌為主，心裏信神叫他從死裏復活，就必得救。","notes":[]},{"n":10,"t":"因為，人心裏相信就可以稱義，口裏承認就可以得救。","notes":[]},{"n":11,"t":"經上說：「凡信他的人必不至於羞愧。」","notes":[]},{"n":12,"t":"猶太人和希臘人並沒有分別，因為眾人同有一位主；他也厚待一切求告他的人。","notes":[]},{"n":13,"t":"因為「凡求告主名的就必得救」。","notes":[]},{"n":14,"t":"然而，人未曾信他，怎能求他呢？未曾聽見他，怎能信他呢？沒有傳道的，怎能聽見呢？","notes":[]},{"n":15,"t":"若沒有奉差遣，怎能傳道呢？如經上所記：「報福音、傳喜信的人，他們的腳蹤何等佳美！ 」","notes":[]},{"n":16,"t":"只是人沒有都聽從福音，因為以賽亞說：「主啊，我們所傳的有誰信呢？」","notes":[]},{"n":17,"t":"可見，信道是從聽道來的，聽道是從基督的話來的。","notes":[]},{"n":18,"t":"但我說，人沒有聽見嗎？誠然聽見了。他們的聲音傳遍天下；他們的言語傳到地極。","notes":[]},{"n":19,"t":"我再說，以色列人不知道嗎？先有摩西說：我要用那不成子民的惹動你們的憤恨；我要用那無知的民觸動你們的怒氣。","notes":[]},{"n":20,"t":"又有以賽亞放膽說：沒有尋找我的，我叫他們遇見；沒有訪問我的，我向他們顯現。","notes":[]},{"n":21,"t":"至於以色列人，他說：「我整天伸手招呼那悖逆頂嘴的百姓。」","notes":[]}]},"11":{"heading":"以色列的餘民","verses":[{"n":1,"t":"我且說，神棄絕了他的百姓嗎？斷乎沒有！因為我也是以色列人，亞伯拉罕的後裔，屬便雅憫支派的。","notes":[]},{"n":2,"t":"神並沒有棄絕他預先所知道的百姓。你們豈不曉得經上論到以利亞是怎麼說的呢？他在神面前怎樣控告以色列人說：","notes":[]},{"n":3,"t":"「主啊，他們殺了你的先知，拆了你的祭壇，只剩下我一個人；他們還要尋索我的命。」","notes":[]},{"n":4,"t":"神的回話是怎麼說的呢？他說：「我為自己留下七千人，是未曾向巴力屈膝的。」","notes":[]},{"n":5,"t":"如今也是這樣，照著揀選的恩典，還有所留的餘數。","notes":[]},{"n":6,"t":"既是出於恩典，就不在乎行為；不然，恩典就不是恩典了。","notes":[]},{"n":7,"t":"這是怎麼樣呢？以色列人所求的，他們沒有得著。惟有蒙揀選的人得著了；其餘的就成了頑梗不化的。","notes":[]},{"n":8,"t":"如經上所記：神給他們昏迷的心，眼睛不能看見，耳朵不能聽見，直到今日。","notes":[]},{"n":9,"t":"大衛也說：願他們的筵席變為網羅，變為機檻，變為絆腳石，作他們的報應。","notes":[]},{"n":10,"t":"願他們的眼睛昏矇，不得看見；願你時常彎下他們的腰。","notes":[]},{"n":11,"t":"我且說，他們失腳是要他們跌倒嗎？斷乎不是！反倒因他們的過失，救恩便臨到外邦人，要激動他們發憤。","notes":[],"heads":["外邦人得救"]},{"n":12,"t":"若他們的過失為天下的富足，他們的缺乏為外邦人的富足，何況他們的豐滿呢？","notes":[]},{"n":13,"t":"我對你們外邦人說這話；因我是外邦人的使徒，所以敬重我的職分，","notes":["原文是榮耀"]},{"n":14,"t":"或者可以激動我骨肉之親發憤，好救他們一些人。","notes":[]},{"n":15,"t":"若他們被丟棄，天下就得與神和好，他們被收納，豈不是死而復生嗎？","notes":[]},{"n":16,"t":"所獻的新麵若是聖潔，全團也就聖潔了；樹根若是聖潔，樹枝也就聖潔了。","notes":[]},{"n":17,"t":"若有幾根枝子被折下來，你這野橄欖得接在其中，一同得著橄欖根的肥汁，","notes":[]},{"n":18,"t":"你就不可向舊枝子誇口；若是誇口，當知道不是你托著根，乃是根托著你。","notes":[]},{"n":19,"t":"你若說，那枝子被折下來是特為叫我接上。","notes":[]},{"n":20,"t":"不錯！他們因為不信，所以被折下來；你因為信，所以立得住；你不可自高，反要懼怕。","notes":[]},{"n":21,"t":"神既不愛惜原來的枝子，也必不愛惜你。","notes":[]},{"n":22,"t":"可見，神的恩慈和嚴厲向那跌倒的人是嚴厲的，向你是有恩慈的，只要你長久在他的恩慈裏；不然，你也要被砍下來。","notes":[]},{"n":23,"t":"而且他們若不是長久不信，仍要被接上，因為神能夠把他們重新接上。","notes":[]},{"n":24,"t":"你是從那天生的野橄欖上砍下來的，尚且逆著性得接在好橄欖上，何況這本樹的枝子，要接在本樹上呢！","notes":[]},{"n":25,"t":"弟兄們，我不願意你們不知道這奧祕（恐怕你們自以為聰明），就是以色列人有幾分是硬心的，等到外邦人的數目添滿了，","notes":[],"heads":["以色列人的復興"]},{"n":26,"t":"於是以色列全家都要得救。如經上所記：必有一位救主從錫安出來，要消除雅各家的一切罪惡；","notes":[]},{"n":27,"t":"又說：我除去他們罪的時候，這就是我與他們所立的約。","notes":[]},{"n":28,"t":"就著福音說，他們為你們的緣故是仇敵；就著揀選說，他們為列祖的緣故是蒙愛的。","notes":[]},{"n":29,"t":"因為神的恩賜和選召是沒有後悔的。","notes":[]},{"n":30,"t":"你們從前不順服神，如今因他們的不順服，你們倒蒙了憐恤。","notes":[]},{"n":31,"t":"這樣，他們也是不順服，叫他們因著施給你們的憐恤，現在也就蒙憐恤。","notes":[]},{"n":32,"t":"因為神將眾人都圈在不順服之中，特意要憐恤眾人。","notes":[]},{"n":33,"t":"深哉，神豐富的智慧和知識！他的判斷何其難測！他的蹤跡何其難尋！","notes":[]},{"n":34,"t":"誰知道主的心？誰作過他的謀士呢？","notes":[]},{"n":35,"t":"誰是先給了他，使他後來償還呢？","notes":[]},{"n":36,"t":"因為萬有都是本於他，倚靠他，歸於他。願榮耀歸給他，直到永遠。阿們！","notes":[]}]},"12":{"heading":"基督裏的新生活","verses":[{"n":1,"t":"所以，弟兄們，我以神的慈悲勸你們，將身體獻上，當作活祭，是聖潔的，是神所喜悅的；你們如此事奉乃是理所當然的。","notes":[]},{"n":2,"t":"不要效法這個世界，只要心意更新而變化，叫你們察驗何為神的善良、純全、可喜悅的旨意。","notes":[]},{"n":3,"t":"我憑著所賜我的恩對你們各人說：不要看自己過於所當看的；要照著神所分給各人信心的大小，看得合乎中道。","notes":[]},{"n":4,"t":"正如我們一個身子上有好些肢體，肢體也不都是一樣的用處。","notes":[]},{"n":5,"t":"我們這許多人，在基督裏成為一身，互相聯絡作肢體，也是如此。","notes":[]},{"n":6,"t":"按我們所得的恩賜，各有不同。或說預言，就當照著信心的程度說預言；","notes":[]},{"n":7,"t":"或作執事，就當專一執事；或作教導的，就當專一教導；","notes":[]},{"n":8,"t":"或作勸化的，就當專一勸化；施捨的，就當誠實；治理的，就當殷勤；憐憫人的，就當甘心。","notes":[]},{"n":9,"t":"愛人不可虛假。惡，要厭惡；善，要親近。","notes":[],"heads":["基督徒的生活守則"]},{"n":10,"t":"愛弟兄，要彼此親熱；恭敬人，要彼此推讓。","notes":[]},{"n":11,"t":"殷勤，不可懶惰；要心裏火熱，常常服事主。","notes":[]},{"n":12,"t":"在指望中要喜樂；在患難中要忍耐；禱告要恆切。","notes":[]},{"n":13,"t":"聖徒缺乏，要幫補；客，要一味地款待。","notes":[]},{"n":14,"t":"逼迫你們的，要給他們祝福；只要祝福，不可咒詛。","notes":[]},{"n":15,"t":"與喜樂的人要同樂；與哀哭的人要同哭。","notes":[]},{"n":16,"t":"要彼此同心；不要志氣高大，倒要俯就卑微的人。不要自以為聰明。","notes":["人：或譯事"]},{"n":17,"t":"不要以惡報惡；眾人以為美的事要留心去做。","notes":[]},{"n":18,"t":"若是能行，總要盡力與眾人和睦。","notes":[]},{"n":19,"t":"親愛的弟兄，不要自己伸冤，寧可讓步，聽憑主怒；因為經上記著：「主說：『伸冤在我，我必報應。』」","notes":["或譯：讓人發怒"]},{"n":20,"t":"所以，「你的仇敵若餓了，就給他吃，若渴了，就給他喝；因為你這樣行就是把炭火堆在他的頭上。」","notes":[]},{"n":21,"t":"你不可為惡所勝，反要以善勝惡。","notes":[]}]},"13":{"heading":"順服掌權者","verses":[{"n":1,"t":"在上有權柄的，人人當順服他，因為沒有權柄不是出於神的。凡掌權的都是神所命的。","notes":[]},{"n":2,"t":"所以，抗拒掌權的就是抗拒神的命；抗拒的必自取刑罰。","notes":[]},{"n":3,"t":"作官的原不是叫行善的懼怕，乃是叫作惡的懼怕。你願意不懼怕掌權的嗎？你只要行善，就可得他的稱讚；","notes":[]},{"n":4,"t":"因為他是神的用人，是與你有益的。你若作惡，卻當懼怕，因為他不是空空地佩劍；他是神的用人，是伸冤的，刑罰那作惡的。","notes":[]},{"n":5,"t":"所以，你們必須順服，不但是因為刑罰，也是因為良心。","notes":[]},{"n":6,"t":"你們納糧，也為這個緣故；因他們是神的差役，常常特管這事。","notes":[]},{"n":7,"t":"凡人所當得的，就給他。當得糧的，給他納糧；當得稅的，給他上稅；當懼怕的，懼怕他；當恭敬的，恭敬他。","notes":[]},{"n":8,"t":"凡事都不可虧欠人，惟有彼此相愛要常以為虧欠，因為愛人的就完全了律法。","notes":[],"heads":["相愛如兄弟"]},{"n":9,"t":"像那不可姦淫，不可殺人，不可偷盜，不可貪婪，或有別的誡命，都包在愛人如己這一句話之內了。","notes":[]},{"n":10,"t":"愛是不加害與人的，所以愛就完全了律法。","notes":[]},{"n":11,"t":"再者，你們曉得，現今就是該趁早睡醒的時候；因為我們得救，現今比初信的時候更近了。","notes":[],"heads":["白晝將近"]},{"n":12,"t":"黑夜已深，白晝將近。我們就當脫去暗昧的行為，帶上光明的兵器。","notes":[]},{"n":13,"t":"行事為人要端正，好像行在白晝。不可荒宴醉酒；不可好色邪蕩；不可爭競嫉妒。","notes":[]},{"n":14,"t":"總要披戴主耶穌基督，不要為肉體安排，去放縱私慾。","notes":[]}]},"14":{"heading":"不可論斷弟兄","verses":[{"n":1,"t":"信心軟弱的，你們要接納，但不要辯論所疑惑的事。","notes":[]},{"n":2,"t":"有人信百物都可吃；但那軟弱的，只吃蔬菜。","notes":[]},{"n":3,"t":"吃的人不可輕看不吃的人；不吃的人不可論斷吃的人；因為神已經收納他了。","notes":[]},{"n":4,"t":"你是誰，竟論斷別人的僕人呢？他或站住或跌倒，自有他的主人在；而且他也必要站住，因為主能使他站住。","notes":[]},{"n":5,"t":"有人看這日比那日強；有人看日日都是一樣。只是各人心裏要意見堅定。","notes":[]},{"n":6,"t":"守日的人是為主守的。吃的人是為主吃的，因他感謝神；不吃的人是為主不吃的，也感謝神。","notes":[]},{"n":7,"t":"我們沒有一個人為自己活，也沒有一個人為自己死。","notes":[]},{"n":8,"t":"我們若活著，是為主而活；若死了，是為主而死。所以，我們或活或死總是主的人。","notes":[]},{"n":9,"t":"因此，基督死了，又活了，為要作死人並活人的主。","notes":[]},{"n":10,"t":"你這個人，為甚麼論斷弟兄呢？又為甚麼輕看弟兄呢？因我們都要站在神的臺前。","notes":[]},{"n":11,"t":"經上寫著：主說：我憑著我的永生起誓：萬膝必向我跪拜；萬口必向我承認。","notes":[]},{"n":12,"t":"這樣看來，我們各人必要將自己的事在神面前說明。","notes":[]},{"n":13,"t":"所以，我們不可再彼此論斷，寧可定意誰也不給弟兄放下絆腳跌人之物。","notes":[],"heads":["不可使弟兄跌倒"]},{"n":14,"t":"我憑著主耶穌確知深信，凡物本來沒有不潔淨的；惟獨人以為不潔淨的，在他就不潔淨了。","notes":[]},{"n":15,"t":"你若因食物叫弟兄憂愁，就不是按著愛人的道理行。基督已經替他死，你不可因你的食物叫他敗壞。","notes":[]},{"n":16,"t":"不可叫你的善被人毀謗；","notes":[]},{"n":17,"t":"因為神的國不在乎吃喝，只在乎公義、和平，並聖靈中的喜樂。","notes":[]},{"n":18,"t":"在這幾樣上服事基督的，就為神所喜悅，又為人所稱許。","notes":[]},{"n":19,"t":"所以，我們務要追求和睦的事與彼此建立德行的事。","notes":[]},{"n":20,"t":"不可因食物毀壞神的工程。凡物固然潔淨，但有人因食物叫人跌倒，就是他的罪了。","notes":[]},{"n":21,"t":"無論是吃肉是喝酒，是甚麼別的事，叫弟兄跌倒，一概不做才好。","notes":[]},{"n":22,"t":"你有信心，就當在神面前守著。人在自己以為可行的事上能不自責，就有福了。","notes":[]},{"n":23,"t":"若有疑心而吃的，就必有罪，因為他吃不是出於信心。凡不出於信心的都是罪。","notes":[]}]},"15":{"heading":"不求自己的喜悅，要叫鄰舍喜悅","verses":[{"n":1,"t":"我們堅固的人應該擔代不堅固人的軟弱，不求自己的喜悅。","notes":[]},{"n":2,"t":"我們各人務要叫鄰舍喜悅，使他得益處，建立德行。","notes":[]},{"n":3,"t":"因為基督也不求自己的喜悅，如經上所記：「辱罵你人的辱罵都落在我身上。」","notes":[]},{"n":4,"t":"從前所寫的聖經都是為教訓我們寫的，叫我們因聖經所生的忍耐和安慰可以得著盼望。","notes":[]},{"n":5,"t":"但願賜忍耐安慰的神叫你們彼此同心，效法基督耶穌，","notes":[]},{"n":6,"t":"一心一口榮耀神－我們主耶穌基督的父！","notes":[]},{"n":7,"t":"所以，你們要彼此接納，如同基督接納你們一樣，使榮耀歸與神。","notes":[],"heads":["神的福音一視同仁"]},{"n":8,"t":"我說，基督是為神真理作了受割禮人的執事，要證實所應許列祖的話，","notes":[]},{"n":9,"t":"並叫外邦人因他的憐憫榮耀神。如經上所記：因此，我要在外邦中稱讚你，歌頌你的名；","notes":[]},{"n":10,"t":"又說：你們外邦人當與主的百姓一同歡樂；","notes":[]},{"n":11,"t":"又說：外邦啊，你們當讚美主！萬民哪，你們都當頌讚他！","notes":[]},{"n":12,"t":"又有以賽亞說：將來有耶西的根，就是那興起來要治理外邦的；外邦人要仰望他。","notes":[]},{"n":13,"t":"但願使人有盼望的神，因信將諸般的喜樂、平安充滿你們的心，使你們藉著聖靈的能力大有盼望！","notes":[]},{"n":14,"t":"弟兄們，我自己也深信你們是滿有良善，充足了諸般的知識，也能彼此勸戒。","notes":[],"heads":["保羅的宣教使命"]},{"n":15,"t":"但我稍微放膽寫信給你們，是要提醒你們的記性，特因神所給我的恩典，","notes":[]},{"n":16,"t":"使我為外邦人作基督耶穌的僕役，作神福音的祭司，叫所獻上的外邦人，因著聖靈成為聖潔，可蒙悅納。","notes":[]},{"n":17,"t":"所以論到神的事，我在基督耶穌裏有可誇的。","notes":[]},{"n":18,"t":"除了基督藉我做的那些事，我甚麼都不敢提，只提他藉我言語作為，用神蹟奇事的能力，並聖靈的能力，使外邦人順服；","notes":[]},{"n":19,"t":"甚至我從耶路撒冷，直轉到以利哩古，到處傳了基督的福音。","notes":[]},{"n":20,"t":"我立了志向，不在基督的名被稱過的地方傳福音，免得建造在別人的根基上。","notes":[]},{"n":21,"t":"就如經上所記：未曾聞知他信息的，將要看見；未曾聽過的，將要明白。","notes":[]},{"n":22,"t":"我因多次被攔阻，總不得到你們那裏去。","notes":[],"heads":["保羅計劃訪問羅馬"]},{"n":23,"t":"但如今，在這裏再沒有可傳的地方，而且這好幾年，我切心想望到西班牙去的時候，可以到你們那裏，","notes":[]},{"n":24,"t":"盼望從你們那裏經過，得見你們，先與你們彼此交往，心裏稍微滿足，然後蒙你們送行。","notes":[]},{"n":25,"t":"但現在，我往耶路撒冷去供給聖徒。","notes":[]},{"n":26,"t":"因為馬其頓和亞該亞人樂意湊出捐項給耶路撒冷聖徒中的窮人。","notes":[]},{"n":27,"t":"這固然是他們樂意的，其實也算是所欠的債；因外邦人既然在他們屬靈的好處上有分，就當把養身之物供給他們。","notes":[]},{"n":28,"t":"等我辦完了這事，把這善果向他們交付明白，我就要路過你們那裏，往西班牙去。","notes":[]},{"n":29,"t":"我也曉得，去的時候必帶著基督豐盛的恩典而去。","notes":[]},{"n":30,"t":"弟兄們，我藉著我們主耶穌基督，又藉著聖靈的愛，勸你們與我一同竭力，為我祈求神，","notes":[]},{"n":31,"t":"叫我脫離在猶太不順從的人，也叫我為耶路撒冷所辦的捐項可蒙聖徒悅納，","notes":[]},{"n":32,"t":"並叫我順著神的旨意，歡歡喜喜地到你們那裏，與你們同得安息。","notes":[]},{"n":33,"t":"願賜平安的神常和你們眾人同在。阿們！","notes":[]}]},"16":{"heading":"問安","verses":[{"n":1,"t":"我對你們舉薦我們的姊妹非比；她是堅革哩教會中的女執事。","notes":[]},{"n":2,"t":"請你們為主接待她，合乎聖徒的體統。她在何事上要你們幫助，你們就幫助她；因她素來幫助許多人，也幫助了我。","notes":[]},{"n":3,"t":"問百基拉和亞居拉安。他們在基督耶穌裏與我同工，","notes":[]},{"n":4,"t":"也為我的命將自己的頸項置之度外。不但我感謝他們，就是外邦的眾教會也感謝他們。","notes":[]},{"n":5,"t":"又問在他們家中的教會安。問我所親愛的以拜尼土安；他在亞細亞是歸基督初結的果子。","notes":[]},{"n":6,"t":"又問馬利亞安；她為你們多受勞苦。","notes":[]},{"n":7,"t":"又問我親屬與我一同坐監的安多尼古和猶尼亞安；他們在使徒中是有名望的，也是比我先在基督裏。","notes":[]},{"n":8,"t":"又問我在主裏面所親愛的暗伯利安。","notes":[]},{"n":9,"t":"又問在基督裏與我們同工的耳巴奴，並我所親愛的士大古安。","notes":[]},{"n":10,"t":"又問在基督裏經過試驗的亞比利安。問亞利多布家裏的人安。","notes":[]},{"n":11,"t":"又問我親屬希羅天安。問拿其數家在主裏的人安。","notes":[]},{"n":12,"t":"又問為主勞苦的土非拿氏和土富撒氏安。問可親愛為主多受勞苦的彼息氏安。","notes":[]},{"n":13,"t":"又問在主蒙揀選的魯孚和他母親安；他的母親就是我的母親。","notes":[]},{"n":14,"t":"又問亞遜其土、弗勒干、黑米、八羅巴、黑馬，並與他們在一處的弟兄們安。","notes":[]},{"n":15,"t":"又問非羅羅古和猶利亞，尼利亞和他姊妹，同阿林巴並與他們在一處的眾聖徒安。","notes":[]},{"n":16,"t":"你們親嘴問安，彼此務要聖潔。基督的眾教會都問你們安。","notes":[]},{"n":17,"t":"弟兄們，那些離間你們、叫你們跌倒、背乎所學之道的人，我勸你們要留意躲避他們。","notes":[]},{"n":18,"t":"因為這樣的人不服事我們的主基督，只服事自己的肚腹，用花言巧語誘惑那些老實人的心。","notes":[]},{"n":19,"t":"你們的順服已經傳於眾人，所以我為你們歡喜；但我願意你們在善上聰明，在惡上愚拙。","notes":[]},{"n":20,"t":"賜平安的神快要將撒但踐踏在你們腳下。願我主耶穌基督的恩常和你們同在！","notes":[]},{"n":21,"t":"與我同工的提摩太，和我的親屬路求、耶孫、所西巴德，問你們安。","notes":[]},{"n":22,"t":"我這代筆寫信的德提，在主裏面問你們安。","notes":[]},{"n":23,"t":"那接待我、也接待全教會的該猶問你們安。","notes":[]},{"n":24,"t":"城內管銀庫的以拉都和兄弟括土問你們安。","notes":[]},{"n":25,"t":"惟有神能照我所傳的福音和所講的耶穌基督，並照永古隱藏不言的奧祕，堅固你們的心。","notes":[],"heads":["頌讚"]},{"n":26,"t":"這奧祕如今顯明出來，而且按著永生神的命令，藉眾先知的書指示萬國的民，使他們信服真道。","notes":[]},{"n":27,"t":"願榮耀，因耶穌基督，歸與獨一全智的神，直到永遠。阿們！","notes":[]}]}},"1CO":{"1":{"heading":"祝福和感謝","verses":[{"n":1,"t":"奉神旨意，蒙召作耶穌基督使徒的保羅，同兄弟所提尼，","notes":[]},{"n":2,"t":"寫信給在哥林多神的教會，就是在基督耶穌裏成聖、蒙召作聖徒的，以及所有在各處求告我主耶穌基督之名的人。基督是他們的主，也是我們的主。","notes":[]},{"n":3,"t":"願恩惠、平安從神我們的父並主耶穌基督歸與你們。","notes":[]},{"n":4,"t":"我常為你們感謝我的神，因神在基督耶穌裏所賜給你們的恩惠；","notes":[]},{"n":5,"t":"又因你們在他裏面凡事富足，口才、知識都全備，","notes":[]},{"n":6,"t":"正如我為基督作的見證，在你們心裏得以堅固，","notes":[]},{"n":7,"t":"以致你們在恩賜上沒有一樣不及人的，等候我們的主耶穌基督顯現。","notes":[]},{"n":8,"t":"他也必堅固你們到底，叫你們在我們主耶穌基督的日子無可責備。","notes":[]},{"n":9,"t":"神是信實的，你們原是被他所召，好與他兒子－我們的主耶穌基督一同得分。","notes":[]},{"n":10,"t":"弟兄們，我藉我們主耶穌基督的名勸你們都說一樣的話。你們中間也不可分黨，只要一心一意，彼此相合。","notes":[],"heads":["在教會中有紛爭"]},{"n":11,"t":"因為革來氏家裏的人曾對我提起弟兄們來，說你們中間有紛爭。","notes":[]},{"n":12,"t":"我的意思就是你們各人說：「我是屬保羅的」；「我是屬亞波羅的」；「我是屬磯法的」；「我是屬基督的」。","notes":[]},{"n":13,"t":"基督是分開的嗎？保羅為你們釘了十字架嗎？你們是奉保羅的名受了洗嗎？","notes":[]},{"n":14,"t":"我感謝神，除了基利司布並該猶以外，我沒有給你們一個人施洗，","notes":[]},{"n":15,"t":"免得有人說，你們是奉我的名受洗。","notes":[]},{"n":16,"t":"我也給司提法那家施過洗，此外給別人施洗沒有，我卻記不清。","notes":[]},{"n":17,"t":"基督差遣我，原不是為施洗，乃是為傳福音，並不用智慧的言語，免得基督的十字架落了空。","notes":[]},{"n":18,"t":"因為十字架的道理，在那滅亡的人為愚拙；在我們得救的人，卻為神的大能。","notes":[],"heads":["基督是神的能力和智慧"]},{"n":19,"t":"就如經上所記：我要滅絕智慧人的智慧，廢棄聰明人的聰明。","notes":[]},{"n":20,"t":"智慧人在哪裏？文士在哪裏？這世上的辯士在哪裏？神豈不是叫這世上的智慧變成愚拙嗎？","notes":[]},{"n":21,"t":"世人憑自己的智慧，既不認識神，神就樂意用人所當作愚拙的道理拯救那些信的人；這就是神的智慧了。","notes":[]},{"n":22,"t":"猶太人是要神蹟，希臘人是求智慧，","notes":[]},{"n":23,"t":"我們卻是傳釘十字架的基督，在猶太人為絆腳石，在外邦人為愚拙；","notes":[]},{"n":24,"t":"但在那蒙召的，無論是猶太人、希臘人，基督總為神的能力，神的智慧。","notes":[]},{"n":25,"t":"因神的愚拙總比人智慧，神的軟弱總比人強壯。","notes":[]},{"n":26,"t":"弟兄們哪，可見你們蒙召的，按著肉體有智慧的不多，有能力的不多，有尊貴的也不多。","notes":[]},{"n":27,"t":"神卻揀選了世上愚拙的，叫有智慧的羞愧；又揀選了世上軟弱的，叫那強壯的羞愧。","notes":[]},{"n":28,"t":"神也揀選了世上卑賤的，被人厭惡的，以及那無有的，為要廢掉那有的，","notes":[]},{"n":29,"t":"使一切有血氣的，在神面前一個也不能自誇。","notes":[]},{"n":30,"t":"但你們得在基督耶穌裏是本乎神，神又使他成為我們的智慧、公義、聖潔、救贖。","notes":[]},{"n":31,"t":"如經上所記：「誇口的，當指著主誇口。」","notes":[]}]},"2":{"heading":"傳揚釘十字架的基督","verses":[{"n":1,"t":"弟兄們，從前我到你們那裏去，並沒有用高言大智對你們宣傳神的奧祕。","notes":[]},{"n":2,"t":"因為我曾定了主意，在你們中間不知道別的，只知道耶穌基督並他釘十字架。","notes":[]},{"n":3,"t":"我在你們那裏，又軟弱，又懼怕又甚戰兢。","notes":[]},{"n":4,"t":"我說的話、講的道，不是用智慧委婉的言語，乃是用聖靈和大能的明證，","notes":[]},{"n":5,"t":"叫你們的信不在乎人的智慧，只在乎神的大能。","notes":[]},{"n":6,"t":"然而，在完全的人中，我們也講智慧。但不是這世上的智慧，也不是這世上有權有位、將要敗亡之人的智慧。","notes":[],"heads":["神藉著聖靈啟示我們"]},{"n":7,"t":"我們講的，乃是從前所隱藏、神奧祕的智慧，就是神在萬世以前預定使我們得榮耀的。","notes":[]},{"n":8,"t":"這智慧世上有權有位的人沒有一個知道的，他們若知道，就不把榮耀的主釘在十字架上了。","notes":[]},{"n":9,"t":"如經上所記：神為愛他的人所預備的是眼睛未曾看見，耳朵未曾聽見，人心也未曾想到的。","notes":[]},{"n":10,"t":"只有神藉著聖靈向我們顯明了，因為聖靈參透萬事，就是神深奧的事也參透了。","notes":[]},{"n":11,"t":"除了在人裏頭的靈，誰知道人的事？像這樣，除了神的靈，也沒有人知道神的事。","notes":[]},{"n":12,"t":"我們所領受的，並不是世上的靈，乃是從神來的靈，叫我們能知道神開恩賜給我們的事。","notes":[]},{"n":13,"t":"並且我們講說這些事，不是用人智慧所指教的言語，乃是用聖靈所指教的言語，將屬靈的話解釋屬靈的事 。","notes":["或譯：將屬靈的事講與屬靈的人"]},{"n":14,"t":"然而，屬血氣的人不領會神聖靈的事，反倒以為愚拙，並且不能知道，因為這些事惟有屬靈的人才能看透。","notes":[]},{"n":15,"t":"屬靈的人能看透萬事，卻沒有一人能看透了他。","notes":[]},{"n":16,"t":"誰曾知道主的心去教導他呢？但我們是有基督的心了。","notes":[]}]},"3":{"heading":"神的同工","verses":[{"n":1,"t":"弟兄們，我從前對你們說話，不能把你們當作屬靈的，只得把你們當作屬肉體，在基督裏為嬰孩的。","notes":[]},{"n":2,"t":"我是用奶餵你們，沒有用飯餵你們。那時你們不能吃，就是如今還是不能。","notes":[]},{"n":3,"t":"你們仍是屬肉體的，因為在你們中間有嫉妒、紛爭，這豈不是屬乎肉體、照著世人的樣子行嗎？","notes":[]},{"n":4,"t":"有說：「我是屬保羅的」；有說：「我是屬亞波羅的。」這豈不是你們和世人一樣嗎？","notes":[]},{"n":5,"t":"亞波羅算甚麼？保羅算甚麼？無非是執事，照主所賜給他們各人的，引導你們相信。","notes":[]},{"n":6,"t":"我栽種了，亞波羅澆灌了，惟有神叫他生長。","notes":[]},{"n":7,"t":"可見栽種的，算不得甚麼，澆灌的，也算不得甚麼；只在那叫他生長的神。","notes":[]},{"n":8,"t":"栽種的和澆灌的，都是一樣，但將來各人要照自己的工夫得自己的賞賜。","notes":[]},{"n":9,"t":"因為我們是與神同工的；你們是神所耕種的田地，所建造的房屋。","notes":[]},{"n":10,"t":"我照神所給我的恩，好像一個聰明的工頭，立好了根基，有別人在上面建造；只是各人要謹慎怎樣在上面建造。","notes":[]},{"n":11,"t":"因為那已經立好的根基就是耶穌基督，此外沒有人能立別的根基。","notes":[]},{"n":12,"t":"若有人用金、銀、寶石、草木、禾稭在這根基上建造，","notes":[]},{"n":13,"t":"各人的工程必然顯露，因為那日子要將它表明出來，有火發現；這火要試驗各人的工程怎樣。","notes":[]},{"n":14,"t":"人在那根基上所建造的工程若存得住，他就要得賞賜。","notes":[]},{"n":15,"t":"人的工程若被燒了，他就要受虧損，自己卻要得救；雖然得救，乃像從火裏經過的一樣。","notes":[]},{"n":16,"t":"豈不知你們是神的殿，神的靈住在你們裏頭嗎？","notes":[]},{"n":17,"t":"若有人毀壞神的殿，神必要毀壞那人；因為神的殿是聖的，這殿就是你們。","notes":[]},{"n":18,"t":"人不可自欺。你們中間若有人在這世界自以為有智慧，倒不如變作愚拙，好成為有智慧的。","notes":[]},{"n":19,"t":"因這世界的智慧，在神看是愚拙。如經上記著說：「主叫有智慧的，中了自己的詭計」；","notes":[]},{"n":20,"t":"又說：「主知道智慧人的意念是虛妄的。」","notes":[]},{"n":21,"t":"所以無論誰，都不可拿人誇口，因為萬有全是你們的。","notes":[]},{"n":22,"t":"或保羅，或亞波羅，或磯法，或世界，或生，或死，或現今的事，或將來的事，全是你們的；","notes":[]},{"n":23,"t":"並且你們是屬基督的，基督又是屬神的。","notes":[]}]},"4":{"heading":"使徒的工作","verses":[{"n":1,"t":"人應當以我們為基督的執事，為神奧祕事的管家。","notes":[]},{"n":2,"t":"所求於管家的，是要他有忠心。","notes":[]},{"n":3,"t":"我被你們論斷，或被別人論斷，我都以為極小的事；連我自己也不論斷自己。","notes":[]},{"n":4,"t":"我雖不覺得自己有錯，卻也不能因此得以稱義；但判斷我的乃是主。","notes":[]},{"n":5,"t":"所以，時候未到，甚麼都不要論斷，只等主來，他要照出暗中的隱情，顯明人心的意念。那時，各人要從神那裏得著稱讚。","notes":[]},{"n":6,"t":"弟兄們，我為你們的緣故，拿這些事轉比自己和亞波羅，叫你們效法我們不可過於聖經所記，免得你們自高自大，貴重這個，輕看那個。","notes":[]},{"n":7,"t":"使你與人不同的是誰呢？你有甚麼不是領受的呢？若是領受的，為何自誇，彷彿不是領受的呢？","notes":[]},{"n":8,"t":"你們已經飽足了！已經豐富了！不用我們，自己就作王了！我願意你們果真作王，叫我們也得與你們一同作王。","notes":[]},{"n":9,"t":"我想神把我們使徒明明列在末後，好像定死罪的囚犯；因為我們成了一臺戲，給世人和天使觀看。","notes":[]},{"n":10,"t":"我們為基督的緣故算是愚拙的，你們在基督裏倒是聰明的；我們軟弱，你們倒強壯；你們有榮耀，我們倒被藐視。","notes":[]},{"n":11,"t":"直到如今，我們還是又飢又渴，又赤身露體，又挨打，又沒有一定的住處，","notes":[]},{"n":12,"t":"並且勞苦，親手做工。被人咒罵，我們就祝福；被人逼迫，我們就忍受；","notes":[]},{"n":13,"t":"被人毀謗，我們就善勸。直到如今，人還把我們看作世界上的污穢，萬物中的渣滓。","notes":[]},{"n":14,"t":"我寫這話，不是叫你們羞愧，乃是警戒你們，好像我所親愛的兒女一樣。","notes":[]},{"n":15,"t":"你們學基督的，師傅雖有一萬，為父的卻是不多，因我在基督耶穌裏用福音生了你們。","notes":[]},{"n":16,"t":"所以，我求你們效法我。","notes":[]},{"n":17,"t":"因此我已打發提摩太到你們那裏去。他在主裏面，是我所親愛、有忠心的兒子。他必提醒你們，記念我在基督裏怎樣行事，在各處各教會中怎樣教導人。","notes":[]},{"n":18,"t":"有些人自高自大，以為我不到你們那裏去；","notes":[]},{"n":19,"t":"然而，主若許我，我必快到你們那裏去，並且我所要知道的，不是那些自高自大之人的言語，乃是他們的權能。","notes":[]},{"n":20,"t":"因為神的國不在乎言語，乃在乎權能。","notes":[]},{"n":21,"t":"你們願意怎麼樣呢？是願意我帶著刑杖到你們那裏去呢？還是要我存慈愛溫柔的心呢？","notes":[]}]},"5":{"heading":"判斷淫亂的事件","verses":[{"n":1,"t":"風聞在你們中間有淫亂的事。這樣的淫亂連外邦人中也沒有，就是有人收了他的繼母。","notes":[]},{"n":2,"t":"你們還是自高自大，並不哀痛，把行這事的人從你們中間趕出去。","notes":[]},{"n":3,"t":"我身子雖不在你們那裏，心卻在你們那裏，好像我親自與你們同在，已經判斷了行這事的人。","notes":[]},{"n":4,"t":"就是你們聚會的時候，我的心也同在。奉我們主耶穌的名，並用我們主耶穌的權能，","notes":[]},{"n":5,"t":"要把這樣的人交給撒但，敗壞他的肉體，使他的靈魂在主耶穌的日子可以得救。","notes":[]},{"n":6,"t":"你們這自誇是不好的。豈不知一點麵酵能使全團發起來嗎？","notes":[]},{"n":7,"t":"你們既是無酵的麵，應當把舊酵除淨，好使你們成為新團；因為我們逾越節的羔羊基督已經被殺獻祭了。","notes":[]},{"n":8,"t":"所以，我們守這節不可用舊酵，也不可用惡毒、邪惡的酵，只用誠實真正的無酵餅。","notes":["或譯：陰毒"]},{"n":9,"t":"我先前寫信給你們說，不可與淫亂的人相交。","notes":[]},{"n":10,"t":"此話不是指這世上一概行淫亂的，或貪婪的，勒索的，或拜偶像的；若是這樣，你們除非離開世界方可。","notes":[]},{"n":11,"t":"但如今我寫信給你們說，若有稱為弟兄是行淫亂的，或貪婪的，或拜偶像的，或辱罵的，或醉酒的，或勒索的，這樣的人不可與他相交，就是與他吃飯都不可。","notes":[]},{"n":12,"t":"因為審判教外的人與我何干？教內的人豈不是你們審判的嗎？","notes":[]},{"n":13,"t":"至於外人有神審判他們。你們應當把那惡人從你們中間趕出去。","notes":[]}]},"6":{"heading":"在不信主的人面前求審","verses":[{"n":1,"t":"你們中間有彼此相爭的事，怎敢在不義的人面前求審，不在聖徒面前求審呢？","notes":[]},{"n":2,"t":"豈不知聖徒要審判世界嗎？若世界為你們所審，難道你們不配審判這最小的事嗎？","notes":[]},{"n":3,"t":"豈不知我們要審判天使嗎？何況今生的事呢？","notes":[]},{"n":4,"t":"既是這樣，你們若有今生的事當審判，是派教會所輕看的人審判嗎？","notes":[]},{"n":5,"t":"我說這話是要叫你們羞恥。難道你們中間沒有一個智慧人能審斷弟兄們的事嗎？","notes":[]},{"n":6,"t":"你們竟是弟兄與弟兄告狀，而且告在不信主的人面前。","notes":[]},{"n":7,"t":"你們彼此告狀，這已經是你們的大錯了。為甚麼不情願受欺呢？為甚麼不情願吃虧呢？","notes":[]},{"n":8,"t":"你們倒是欺壓人、虧負人，況且所欺壓所虧負的就是弟兄。","notes":[]},{"n":9,"t":"你們豈不知不義的人不能承受神的國嗎？不要自欺！無論是淫亂的、拜偶像的、姦淫的、作孌童的、親男色的、","notes":[]},{"n":10,"t":"偷竊的、貪婪的、醉酒的、辱罵的、勒索的，都不能承受神的國。","notes":[]},{"n":11,"t":"你們中間也有人從前是這樣；但如今你們奉主耶穌基督的名，並藉著我們神的靈，已經洗淨，成聖，稱義了。","notes":[]},{"n":12,"t":"凡事我都可行，但不都有益處。凡事我都可行，但無論哪一件，我總不受它的轄制。","notes":[],"heads":["在身子上榮耀神"]},{"n":13,"t":"食物是為肚腹，肚腹是為食物；但神要叫這兩樣都廢壞。身子不是為淫亂，乃是為主；主也是為身子。","notes":[]},{"n":14,"t":"並且神已經叫主復活，也要用自己的能力叫我們復活。","notes":[]},{"n":15,"t":"豈不知你們的身子是基督的肢體嗎？我可以將基督的肢體作為娼妓的肢體嗎？斷乎不可！","notes":[]},{"n":16,"t":"豈不知與娼妓聯合的，便是與她成為一體嗎？因為主說：「二人要成為一體。」","notes":[]},{"n":17,"t":"但與主聯合的，便是與主成為一靈。","notes":[]},{"n":18,"t":"你們要逃避淫行。人所犯的，無論甚麼罪，都在身子以外，惟有行淫的，是得罪自己的身子。","notes":[]},{"n":19,"t":"豈不知你們的身子就是聖靈的殿嗎？這聖靈是從神而來，住在你們裏頭的；並且你們不是自己的人，","notes":[]},{"n":20,"t":"因為你們是重價買來的。所以，要在你們的身子上榮耀神。","notes":[]}]},"7":{"heading":"婚姻的問題","verses":[{"n":1,"t":"論到你們信上所提的事，我說男不近女倒好。","notes":[]},{"n":2,"t":"但要免淫亂的事，男子當各有自己的妻子；女子也當各有自己的丈夫。","notes":[]},{"n":3,"t":"丈夫當用合宜之分待妻子；妻子待丈夫也要如此。","notes":[]},{"n":4,"t":"妻子沒有權柄主張自己的身子，乃在丈夫；丈夫也沒有權柄主張自己的身子，乃在妻子。","notes":[]},{"n":5,"t":"夫妻不可彼此虧負，除非兩相情願，暫時分房，為要專心禱告方可；以後仍要同房，免得撒但趁著你們情不自禁，引誘你們。","notes":[]},{"n":6,"t":"我說這話，原是准你們的，不是命你們的。","notes":[]},{"n":7,"t":"我願意眾人像我一樣；只是各人領受神的恩賜，一個是這樣，一個是那樣。","notes":[]},{"n":8,"t":"我對著沒有嫁娶的和寡婦說，若他們常像我就好。","notes":[]},{"n":9,"t":"倘若自己禁止不住，就可以嫁娶。與其慾火攻心，倒不如嫁娶為妙。","notes":[]},{"n":10,"t":"至於那已經嫁娶的，我吩咐他們；其實不是我吩咐，乃是主吩咐說：妻子不可離開丈夫，","notes":[]},{"n":11,"t":"若是離開了，不可再嫁，或是仍同丈夫和好。丈夫也不可離棄妻子。","notes":[]},{"n":12,"t":"我對其餘的人說（不是主說）：倘若某弟兄有不信的妻子，妻子也情願和他同住，他就不要離棄妻子。","notes":[]},{"n":13,"t":"妻子有不信的丈夫，丈夫也情願和她同住，她就不要離棄丈夫。","notes":[]},{"n":14,"t":"因為不信的丈夫就因著妻子成了聖潔，並且不信的妻子就因著丈夫成了聖潔。不然，你們的兒女就不潔淨，但如今他們是聖潔的了。","notes":["原文是弟兄"]},{"n":15,"t":"倘若那不信的人要離去，就由他離去吧！無論是弟兄，是姊妹，遇著這樣的事都不必拘束。神召我們原是要我們和睦。","notes":[]},{"n":16,"t":"你這作妻子的，怎麼知道不能救你的丈夫呢？你這作丈夫的，怎麼知道不能救你的妻子呢？","notes":[]},{"n":17,"t":"只要照主所分給各人的，和神所召各人的而行。我吩咐各教會都是這樣。","notes":[],"heads":["照主分給各人的去行"]},{"n":18,"t":"有人已受割禮蒙召呢，就不要廢割禮；有人未受割禮蒙召呢，就不要受割禮。","notes":[]},{"n":19,"t":"受割禮算不得甚麼，不受割禮也算不得甚麼，只要守神的誡命就是了。","notes":[]},{"n":20,"t":"各人蒙召的時候是甚麼身分，仍要守住這身分。","notes":[]},{"n":21,"t":"你是作奴隸蒙召的嗎？不要因此憂慮；若能以自由，就求自由更好。","notes":[]},{"n":22,"t":"因為作奴僕蒙召於主的，就是主所釋放的人；作自由之人蒙召的，就是基督的奴僕。","notes":[]},{"n":23,"t":"你們是重價買來的，不要作人的奴僕。","notes":[]},{"n":24,"t":"弟兄們，你們各人蒙召的時候是甚麼身分，仍要在神面前守住這身分。","notes":[]},{"n":25,"t":"論到童身的人，我沒有主的命令，但我既蒙主憐恤能作忠心的人，就把自己的意見告訴你們。","notes":[],"heads":["未婚和寡居"]},{"n":26,"t":"因現今的艱難，據我看來，人不如守素安常才好。","notes":[]},{"n":27,"t":"你有妻子纏著呢，就不要求脫離；你沒有妻子纏著呢，就不要求妻子。","notes":[]},{"n":28,"t":"你若娶妻，並不是犯罪；處女若出嫁，也不是犯罪。然而這等人肉身必受苦難，我卻願意你們免這苦難。","notes":[]},{"n":29,"t":"弟兄們，我對你們說：時候減少了。從此以後，那有妻子的，要像沒有妻子；","notes":[]},{"n":30,"t":"哀哭的，要像不哀哭；快樂的，要像不快樂；置買的，要像無有所得；","notes":[]},{"n":31,"t":"用世物的，要像不用世物，因為這世界的樣子將要過去了。","notes":[]},{"n":32,"t":"我願你們無所掛慮。沒有娶妻的，是為主的事掛慮，想怎樣叫主喜悅。","notes":[]},{"n":33,"t":"娶了妻的，是為世上的事掛慮，想怎樣叫妻子喜悅。","notes":[]},{"n":34,"t":"婦人和處女也有分別。沒有出嫁的，是為主的事掛慮，要身體、靈魂都聖潔；已經出嫁的，是為世上的事掛慮，想怎樣叫丈夫喜悅。","notes":[]},{"n":35,"t":"我說這話是為你們的益處，不是要牢籠你們，乃是要叫你們行合宜的事，得以殷勤服事主，沒有分心的事。","notes":[]},{"n":36,"t":"若有人以為自己待他的女兒不合宜，女兒也過了年歲，事又當行，他就可隨意辦理，不算有罪，叫二人成親就是了。","notes":[]},{"n":37,"t":"倘若人心裏堅定，沒有不得已的事，並且由得自己作主，心裏又決定了留下女兒不出嫁，如此行也好。","notes":[]},{"n":38,"t":"這樣看來，叫自己的女兒出嫁是好，不叫她出嫁更是好。","notes":[]},{"n":39,"t":"丈夫活著的時候，妻子是被約束的；丈夫若死了，妻子就可以自由，隨意再嫁，只是要嫁這在主裏面的人。","notes":[]},{"n":40,"t":"然而按我的意見，若常守節更有福氣。我也想自己是被神的靈感動了。","notes":[]}]},"8":{"heading":"祭過偶像的食物","verses":[{"n":1,"t":"論到祭偶像之物，我們曉得我們都有知識。但知識是叫人自高自大，惟有愛心能造就人。","notes":[]},{"n":2,"t":"若有人以為自己知道甚麼，按他所當知道的，他仍是不知道。","notes":[]},{"n":3,"t":"若有人愛神，這人乃是神所知道的。","notes":[]},{"n":4,"t":"論到吃祭偶像之物，我們知道偶像在世上算不得甚麼，也知道神只有一位，再沒有別的神。","notes":[]},{"n":5,"t":"雖有稱為神的，或在天，或在地，就如那許多的神，許多的主；","notes":[]},{"n":6,"t":"然而我們只有一位神，就是父－萬物都本於他；我們也歸於他－並有一位主，就是耶穌基督－萬物都是藉著他有的；我們也是藉著他有的。","notes":[]},{"n":7,"t":"但人不都有這等知識。有人到如今因拜慣了偶像，就以為所吃的是祭偶像之物。他們的良心既然軟弱，也就污穢了。","notes":[]},{"n":8,"t":"其實食物不能叫神看中我們，因為我們不吃也無損，吃也無益。","notes":[]},{"n":9,"t":"只是你們要謹慎，恐怕你們這自由竟成了那軟弱人的絆腳石。","notes":[]},{"n":10,"t":"若有人見你這有知識的，在偶像的廟裏坐席，這人的良心若是軟弱，豈不放膽去吃那祭偶像之物嗎？","notes":[]},{"n":11,"t":"因此，基督為他死的那軟弱弟兄，也就因你的知識沉淪了。","notes":[]},{"n":12,"t":"你們這樣得罪弟兄們，傷了他們軟弱的良心，就是得罪基督。","notes":[]},{"n":13,"t":"所以，食物若叫我弟兄跌倒，我就永遠不吃肉，免得叫我弟兄跌倒了。","notes":[]}]},"9":{"heading":"使徒的權利","verses":[{"n":1,"t":"我不是自由的嗎？我不是使徒嗎？我不是見過我們的主耶穌嗎？你們不是我在主裏面所做之工嗎？","notes":[]},{"n":2,"t":"假若在別人，我不是使徒，在你們，我總是使徒，因為你們在主裏正是我作使徒的印證。","notes":[]},{"n":3,"t":"我對那盤問我的人就是這樣分訴：","notes":[]},{"n":4,"t":"難道我們沒有權柄靠福音吃喝嗎？","notes":[]},{"n":5,"t":"難道我們沒有權柄娶信主的姊妹為妻，帶著一同往來，彷彿其餘的使徒和主的弟兄並磯法一樣嗎？","notes":[]},{"n":6,"t":"獨有我與巴拿巴沒有權柄不做工嗎？","notes":[]},{"n":7,"t":"有誰當兵自備糧餉呢？有誰栽葡萄園不吃園裏的果子呢？有誰牧養牛羊不吃牛羊的奶呢？","notes":[]},{"n":8,"t":"我說這話，豈是照人的意見；律法不也是這樣說嗎？","notes":[]},{"n":9,"t":"就如摩西的律法記著說：「牛在場上踹穀的時候，不可籠住牠的嘴。」難道神所掛念的是牛嗎？","notes":[]},{"n":10,"t":"不全是為我們說的嗎？分明是為我們說的。因為耕種的當存著指望去耕種；打場的也當存得糧的指望去打場。","notes":[]},{"n":11,"t":"我們若把屬靈的種子撒在你們中間，就是從你們收割奉養肉身之物，這還算大事嗎？","notes":[]},{"n":12,"t":"若別人在你們身上有這權柄，何況我們呢？然而，我們沒有用過這權柄，倒凡事忍受，免得基督的福音被阻隔。","notes":[]},{"n":13,"t":"你們豈不知為聖事勞碌的就吃殿中的物嗎？伺候祭壇的就分領壇上的物嗎？","notes":[]},{"n":14,"t":"主也是這樣命定，叫傳福音的靠著福音養生。","notes":[]},{"n":15,"t":"但這權柄我全沒有用過。我寫這話，並非要你們這樣待我，因為我寧可死也不叫人使我所誇的落了空。","notes":[]},{"n":16,"t":"我傳福音原沒有可誇的，因為我是不得已的。若不傳福音，我便有禍了。","notes":[]},{"n":17,"t":"我若甘心做這事，就有賞賜；若不甘心，責任卻已經託付我了。","notes":[]},{"n":18,"t":"既是這樣，我的賞賜是甚麼呢？就是我傳福音的時候叫人不花錢得福音，免得用盡我傳福音的權柄。","notes":[]},{"n":19,"t":"我雖是自由的，無人轄管；然而我甘心作了眾人的僕人，為要多得人。","notes":[]},{"n":20,"t":"向猶太人，我就作猶太人，為要得猶太人；向律法以下的人，我雖不在律法以下，還是作律法以下的人，為要得律法以下的人。","notes":[]},{"n":21,"t":"向沒有律法的人，我就作沒有律法的人，為要得沒有律法的人；其實我在神面前，不是沒有律法；在基督面前，正在律法之下。","notes":[]},{"n":22,"t":"向軟弱的人，我就作軟弱的人，為要得軟弱的人。向甚麼樣的人，我就作甚麼樣的人。無論如何，總要救些人。","notes":[]},{"n":23,"t":"凡我所行的，都是為福音的緣故，為要與人同得這福音的好處。","notes":[]},{"n":24,"t":"豈不知在場上賽跑的都跑，但得獎賞的只有一人？你們也當這樣跑，好叫你們得著獎賞。","notes":[]},{"n":25,"t":"凡較力爭勝的，諸事都有節制，他們不過是要得能壞的冠冕；我們卻是要得不能壞的冠冕。","notes":[]},{"n":26,"t":"所以，我奔跑不像無定向的；我鬥拳不像打空氣的。","notes":[]},{"n":27,"t":"我是攻克己身，叫身服我，恐怕我傳福音給別人，自己反被棄絕了。","notes":[]}]},"10":{"heading":"警戒拜偶像的事","verses":[{"n":1,"t":"弟兄們，我不願意你們不曉得，我們的祖宗從前都在雲下，都從海中經過，","notes":[]},{"n":2,"t":"都在雲裏、海裏受洗歸了摩西；","notes":[]},{"n":3,"t":"並且都吃了一樣的靈食，","notes":[]},{"n":4,"t":"也都喝了一樣的靈水。所喝的，是出於隨著他們的靈磐石；那磐石就是基督。","notes":[]},{"n":5,"t":"但他們中間多半是神不喜歡的人，所以在曠野倒斃。","notes":[]},{"n":6,"t":"這些事都是我們的鑑戒，叫我們不要貪戀惡事，像他們那樣貪戀的；","notes":[]},{"n":7,"t":"也不要拜偶像，像他們有人拜的。如經上所記：「百姓坐下吃喝，起來玩耍。」","notes":[]},{"n":8,"t":"我們也不要行姦淫，像他們有人行的，一天就倒斃了二萬三千人；","notes":[]},{"n":9,"t":"也不要試探主，像他們有人試探的，就被蛇所滅。","notes":["有古卷：基督"]},{"n":10,"t":"你們也不要發怨言，像他們有發怨言的，就被滅命的所滅。","notes":[]},{"n":11,"t":"他們遭遇這些事都要作為鑑戒，並且寫在經上，正是警戒我們這末世的人。","notes":[]},{"n":12,"t":"所以，自己以為站得穩的，須要謹慎，免得跌倒。","notes":[]},{"n":13,"t":"你們所遇見的試探，無非是人所能受的。神是信實的，必不叫你們受試探過於所能受的；在受試探的時候，總要給你們開一條出路，叫你們能忍受得住。","notes":[]},{"n":14,"t":"我所親愛的弟兄啊，你們要逃避拜偶像的事。","notes":[]},{"n":15,"t":"我好像對明白人說的，你們要審察我的話。","notes":[]},{"n":16,"t":"我們所祝福的杯，豈不是同領基督的血嗎？我們所擘開的餅，豈不是同領基督的身體嗎？","notes":[]},{"n":17,"t":"我們雖多，仍是一個餅，一個身體，因為我們都是分受這一個餅。","notes":[]},{"n":18,"t":"你們看屬肉體的以色列人，那吃祭物的豈不是在祭壇上有分嗎？","notes":[]},{"n":19,"t":"我是怎麼說呢？豈是說祭偶像之物算得甚麼呢？或說偶像算得甚麼呢？","notes":[]},{"n":20,"t":"我乃是說，外邦人所獻的祭是祭鬼，不是祭神。我不願意你們與鬼相交。","notes":[]},{"n":21,"t":"你們不能喝主的杯又喝鬼的杯，不能吃主的筵席又吃鬼的筵席。","notes":[]},{"n":22,"t":"我們可惹主的憤恨嗎？我們比他還有能力嗎？","notes":[]},{"n":23,"t":"凡事都可行，但不都有益處。凡事都可行，但不都造就人。","notes":[],"heads":["凡事為榮耀神而行"]},{"n":24,"t":"無論何人，不要求自己的益處，乃要求別人的益處。","notes":[]},{"n":25,"t":"凡市上所賣的，你們只管吃，不要為良心的緣故問甚麼話，","notes":[]},{"n":26,"t":"因為地和其中所充滿的都屬乎主。","notes":[]},{"n":27,"t":"倘有一個不信的人請你們赴席，你們若願意去，凡擺在你們面前的，只管吃，不要為良心的緣故問甚麼話。","notes":[]},{"n":28,"t":"若有人對你們說：「這是獻過祭的物」，就要為那告訴你們的人，並為良心的緣故不吃。","notes":[]},{"n":29,"t":"我說的良心不是你的，乃是他的。我這自由為甚麼被別人的良心論斷呢？","notes":[]},{"n":30,"t":"我若謝恩而吃，為甚麼因我謝恩的物被人毀謗呢？","notes":[]},{"n":31,"t":"所以，你們或吃或喝，無論做甚麼，都要為榮耀神而行。","notes":[]},{"n":32,"t":"不拘是猶太人，是希臘人，是神的教會，你們都不要使他跌倒；","notes":[]},{"n":33,"t":"就好像我凡事都叫眾人喜歡，不求自己的益處，只求眾人的益處，叫他們得救。","notes":[]}]},"11":{"heading":"禮拜時蒙頭的問題","verses":[{"n":1,"t":"你們該效法我，像我效法基督一樣。","notes":[]},{"n":2,"t":"我稱讚你們，因你們凡事記念我，又堅守我所傳給你們的。","notes":[]},{"n":3,"t":"我願意你們知道，基督是各人的頭；男人是女人的頭；神是基督的頭。","notes":[]},{"n":4,"t":"凡男人禱告或是講道，若蒙著頭，就羞辱自己的頭。","notes":["或譯：說預言；下同"]},{"n":5,"t":"凡女人禱告或是講道，若不蒙著頭，就羞辱自己的頭，因為這就如同剃了頭髮一樣。","notes":[]},{"n":6,"t":"女人若不蒙著頭，就該剪了頭髮；女人若以剪髮、剃髮為羞愧，就該蒙著頭。","notes":[]},{"n":7,"t":"男人本不該蒙著頭，因為他是神的形像和榮耀；但女人是男人的榮耀。","notes":[]},{"n":8,"t":"起初，男人不是由女人而出，女人乃是由男人而出；","notes":[]},{"n":9,"t":"並且男人不是為女人造的，女人乃是為男人造的。","notes":[]},{"n":10,"t":"因此，女人為天使的緣故，應當在頭上有服權柄的記號。","notes":[]},{"n":11,"t":"然而照主的安排，女也不是無男，男也不是無女。","notes":[]},{"n":12,"t":"因為女人原是由男人而出，男人也是由女人而出；但萬有都是出乎神。","notes":[]},{"n":13,"t":"你們自己審察，女人禱告神，不蒙著頭是合宜的嗎？","notes":[]},{"n":14,"t":"你們的本性不也指示你們，男人若有長頭髮，便是他的羞辱嗎？","notes":[]},{"n":15,"t":"但女人有長頭髮，乃是她的榮耀，因為這頭髮是給她作蓋頭的。","notes":[]},{"n":16,"t":"若有人想要辯駁，我們卻沒有這樣的規矩，神的眾教會也是沒有的。","notes":[]},{"n":17,"t":"我現今吩咐你們的話，不是稱讚你們；因為你們聚會不是受益，乃是招損。","notes":[],"heads":["聖餐時的混亂"]},{"n":18,"t":"第一，我聽說，你們聚會的時候彼此分門別類，我也稍微地信這話。","notes":[]},{"n":19,"t":"在你們中間不免有分門結黨的事，好叫那些有經驗的人顯明出來。","notes":[]},{"n":20,"t":"你們聚會的時候，算不得吃主的晚餐；","notes":[]},{"n":21,"t":"因為吃的時候，各人先吃自己的飯，甚至這個飢餓，那個酒醉。","notes":[]},{"n":22,"t":"你們要吃喝，難道沒有家嗎？還是藐視神的教會，叫那沒有的羞愧呢？我向你們可怎麼說呢？可因此稱讚你們嗎？我不稱讚！","notes":[]},{"n":23,"t":"我當日傳給你們的，原是從主領受的，就是主耶穌被賣的那一夜，拿起餅來，","notes":[],"heads":["聖餐的設立"]},{"n":24,"t":"祝謝了，就擘開，說：「這是我的身體，為你們捨的，你們應當如此行，為的是記念我。」","notes":["有古卷：擘開"]},{"n":25,"t":"飯後，也照樣拿起杯來，說：「這杯是用我的血所立的新約，你們每逢喝的時候，要如此行，為的是記念我。」","notes":[]},{"n":26,"t":"你們每逢吃這餅，喝這杯，是表明主的死，直等到他來。","notes":[]},{"n":27,"t":"所以，無論何人，不按理吃主的餅，喝主的杯，就是干犯主的身、主的血了。","notes":[],"heads":["不按理吃主的晚餐"]},{"n":28,"t":"人應當自己省察，然後吃這餅、喝這杯。","notes":[]},{"n":29,"t":"因為人吃喝，若不分辨是主的身體，就是吃喝自己的罪了。","notes":[]},{"n":30,"t":"因此，在你們中間有好些軟弱的與患病的，死的也不少。","notes":["原文是睡"]},{"n":31,"t":"我們若是先分辨自己，就不至於受審。","notes":[]},{"n":32,"t":"我們受審的時候，乃是被主懲治，免得我們和世人一同定罪。","notes":[]},{"n":33,"t":"所以我弟兄們，你們聚會吃的時候，要彼此等待。","notes":[]},{"n":34,"t":"若有人飢餓，可以在家裏先吃，免得你們聚會，自己取罪。其餘的事，我來的時候再安排。","notes":[]}]},"12":{"heading":"屬靈的恩賜","verses":[{"n":1,"t":"弟兄們，論到屬靈的恩賜，我不願意你們不明白。","notes":[]},{"n":2,"t":"你們作外邦人的時候，隨事被牽引，受迷惑，去服事那啞巴偶像，這是你們知道的。","notes":[]},{"n":3,"t":"所以我告訴你們，被神的靈感動的，沒有說「耶穌是可咒詛」的；若不是被聖靈感動的，也沒有能說「耶穌是主」的。","notes":[]},{"n":4,"t":"恩賜原有分別，聖靈卻是一位。","notes":[]},{"n":5,"t":"職事也有分別，主卻是一位。","notes":[]},{"n":6,"t":"功用也有分別，神卻是一位，在眾人裏面運行一切的事。","notes":[]},{"n":7,"t":"聖靈顯在各人身上，是叫人得益處。","notes":[]},{"n":8,"t":"這人蒙聖靈賜他智慧的言語，那人也蒙這位聖靈賜他知識的言語，","notes":[]},{"n":9,"t":"又有一人蒙這位聖靈賜他信心，還有一人蒙這位聖靈賜他醫病的恩賜，","notes":[]},{"n":10,"t":"又叫一人能行異能，又叫一人能作先知，又叫一人能辨別諸靈，又叫一人能說方言，又叫一人能翻方言。","notes":[]},{"n":11,"t":"這一切都是這位聖靈所運行、隨己意分給各人的。","notes":[]},{"n":12,"t":"就如身子是一個，卻有許多肢體；而且肢體雖多，仍是一個身子；基督也是這樣。","notes":[],"heads":["一個身體有許多肢體"]},{"n":13,"t":"我們不拘是猶太人，是希臘人，是為奴的，是自主的，都從一位聖靈受洗，成了一個身體，飲於一位聖靈。","notes":[]},{"n":14,"t":"身子原不是一個肢體，乃是許多肢體。","notes":[]},{"n":15,"t":"設若腳說：「我不是手，所以不屬乎身子，」它不能因此就不屬乎身子。","notes":[]},{"n":16,"t":"設若耳說：「我不是眼，所以不屬乎身子，」它也不能因此就不屬乎身子。","notes":[]},{"n":17,"t":"若全身是眼，從哪裏聽聲呢？若全身是耳，從哪裏聞味呢？","notes":[]},{"n":18,"t":"但如今，神隨自己的意思把肢體俱各安排在身上了。","notes":[]},{"n":19,"t":"若都是一個肢體，身子在哪裏呢？","notes":[]},{"n":20,"t":"但如今肢體是多的，身子卻是一個。","notes":[]},{"n":21,"t":"眼不能對手說：「我用不著你。」頭也不能對腳說：「我用不著你。」","notes":[]},{"n":22,"t":"不但如此，身上肢體人以為軟弱的，更是不可少的。","notes":[]},{"n":23,"t":"身上肢體，我們看為不體面的，越發給它加上體面；不俊美的，越發得著俊美。","notes":[]},{"n":24,"t":"我們俊美的肢體，自然用不著裝飾；但神配搭這身子，把加倍的體面給那有缺欠的肢體，","notes":[]},{"n":25,"t":"免得身上分門別類，總要肢體彼此相顧。","notes":[]},{"n":26,"t":"若一個肢體受苦，所有的肢體就一同受苦；若一個肢體得榮耀，所有的肢體就一同快樂。","notes":[]},{"n":27,"t":"你們就是基督的身子，並且各自作肢體。","notes":[]},{"n":28,"t":"神在教會所設立的：第一是使徒，第二是先知，第三是教師，其次是行異能的，再次是得恩賜醫病的，幫助人的，治理事的，說方言的。","notes":[]},{"n":29,"t":"豈都是使徒嗎？豈都是先知嗎？豈都是教師嗎？豈都是行異能的嗎？","notes":[]},{"n":30,"t":"豈都是得恩賜醫病的嗎？豈都是說方言的嗎？豈都是翻方言的嗎？","notes":[]},{"n":31,"t":"你們要切切地求那更大的恩賜。我現今把最妙的道指示你們。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"我若能說萬人的方言，並天使的話語，卻沒有愛，我就成了鳴的鑼，響的鈸一般。","notes":[]},{"n":2,"t":"我若有先知講道之能，也明白各樣的奧祕，各樣的知識，而且有全備的信，叫我能夠移山，卻沒有愛，我就算不得甚麼。","notes":[]},{"n":3,"t":"我若將所有的賙濟窮人，又捨己身叫人焚燒，卻沒有愛，仍然與我無益。","notes":[]},{"n":4,"t":"愛是恆久忍耐，又有恩慈；愛是不嫉妒；愛是不自誇，不張狂，","notes":[]},{"n":5,"t":"不做害羞的事，不求自己的益處，不輕易發怒，不計算人的惡，","notes":[]},{"n":6,"t":"不喜歡不義，只喜歡真理；","notes":[]},{"n":7,"t":"凡事包容，凡事相信，凡事盼望，凡事忍耐。","notes":[]},{"n":8,"t":"愛是永不止息。先知講道之能終必歸於無有；說方言之能終必停止；知識也終必歸於無有。","notes":[]},{"n":9,"t":"我們現在所知道的有限，先知所講的也有限，","notes":[]},{"n":10,"t":"等那完全的來到，這有限的必歸於無有了。","notes":[]},{"n":11,"t":"我作孩子的時候，話語像孩子，心思像孩子，意念像孩子，既成了人，就把孩子的事丟棄了。","notes":[]},{"n":12,"t":"我們如今彷彿對著鏡子觀看，模糊不清，到那時就要面對面了。我如今所知道的有限，到那時就全知道，如同主知道我一樣。","notes":["原文是如同猜謎"]},{"n":13,"t":"如今常存的有信，有望，有愛這三樣，其中最大的是愛。","notes":[]}]},"14":{"heading":"說方言和作先知講道","verses":[{"n":1,"t":"你們要追求愛，也要切慕屬靈的恩賜，其中更要羨慕的，是作先知講道。","notes":["原文作：是說預言；下同"]},{"n":2,"t":"那說方言的，原不是對人說，乃是對神說，因為沒有人聽出來。然而，他在心靈裏卻是講說各樣的奧祕。","notes":[]},{"n":3,"t":"但作先知講道的，是對人說，要造就、安慰、勸勉人。","notes":[]},{"n":4,"t":"說方言的，是造就自己；作先知講道的，乃是造就教會。","notes":[]},{"n":5,"t":"我願意你們都說方言，更願意你們作先知講道；因為說方言的，若不翻出來，使教會被造就，那作先知講道的，就比他強了。","notes":[]},{"n":6,"t":"弟兄們，我到你們那裏去，若只說方言，不用啟示，或知識，或預言，或教訓，給你們講解，我與你們有甚麼益處呢？","notes":[]},{"n":7,"t":"就是那有聲無氣的物，或簫，或琴，若發出來的聲音沒有分別，怎能知道所吹所彈的是甚麼呢？","notes":[]},{"n":8,"t":"若吹無定的號聲，誰能預備打仗呢？","notes":[]},{"n":9,"t":"你們也是如此。舌頭若不說容易明白的話，怎能知道所說的是甚麼呢？這就是向空說話了。","notes":[]},{"n":10,"t":"世上的聲音，或者甚多，卻沒有一樣是無意思的。","notes":[]},{"n":11,"t":"我若不明白那聲音的意思，這說話的人必以我為化外之人，我也以他為化外之人。","notes":[]},{"n":12,"t":"你們也是如此，既是切慕屬靈的恩賜，就當求多得造就教會的恩賜。","notes":[]},{"n":13,"t":"所以那說方言的，就當求著能翻出來。","notes":[]},{"n":14,"t":"我若用方言禱告，是我的靈禱告，但我的悟性沒有果效。","notes":[]},{"n":15,"t":"這卻怎麼樣呢？我要用靈禱告，也要用悟性禱告；我要用靈歌唱，也要用悟性歌唱。","notes":[]},{"n":16,"t":"不然，你用靈祝謝，那在座不通方言的人，既然不明白你的話，怎能在你感謝的時候說「阿們」呢？","notes":[]},{"n":17,"t":"你感謝的固然是好，無奈不能造就別人。","notes":[]},{"n":18,"t":"我感謝神，我說方言比你們眾人還多。","notes":[]},{"n":19,"t":"但在教會中，寧可用悟性說五句教導人的話，強如說萬句方言。","notes":[]},{"n":20,"t":"弟兄們，在心志上不要作小孩子。然而，在惡事上要作嬰孩，在心志上總要作大人。","notes":[]},{"n":21,"t":"律法上記著：主說：我要用外邦人的舌頭和外邦人的嘴唇向這百姓說話；雖然如此，他們還是不聽從我。","notes":[]},{"n":22,"t":"這樣看來，說方言不是為信的人作證據，乃是為不信的人；作先知講道不是為不信的人作證據，乃是為信的人。","notes":[]},{"n":23,"t":"所以，全教會聚在一處的時候，若都說方言，偶然有不通方言的，或是不信的人進來，豈不說你們癲狂了嗎？","notes":[]},{"n":24,"t":"若都作先知講道，偶然有不信的，或是不通方言的人進來，就被眾人勸醒，被眾人審明，","notes":[]},{"n":25,"t":"他心裏的隱情顯露出來，就必將臉伏地，敬拜神，說：「神真是在你們中間了。」","notes":[]},{"n":26,"t":"弟兄們，這卻怎麼樣呢？你們聚會的時候，各人或有詩歌，或有教訓，或有啟示，或有方言，或有翻出來的話，凡事都當造就人。","notes":[],"heads":["凡事都要按次序行"]},{"n":27,"t":"若有說方言的，只好兩個人，至多三個人，且要輪流著說，也要一個人翻出來。","notes":[]},{"n":28,"t":"若沒有人翻，就當在會中閉口，只對自己和神說就是了。","notes":[]},{"n":29,"t":"至於作先知講道的，只好兩個人或是三個人，其餘的就當慎思明辨。","notes":[]},{"n":30,"t":"若旁邊坐著的得了啟示，那先說話的就當閉口不言。","notes":[]},{"n":31,"t":"因為你們都可以一個一個地作先知講道，叫眾人學道理，叫眾人得勸勉。","notes":[]},{"n":32,"t":"先知的靈原是順服先知的；","notes":[]},{"n":33,"t":"因為神不是叫人混亂，乃是叫人安靜。","notes":[]},{"n":34,"t":"婦女在會中要閉口不言，像在聖徒的眾教會一樣，因為不准她們說話。她們總要順服，正如律法所說的。","notes":[]},{"n":35,"t":"她們若要學甚麼，可以在家裏問自己的丈夫，因為婦女在會中說話原是可恥的。","notes":[]},{"n":36,"t":"神的道理豈是從你們出來嗎？豈是單臨到你們嗎？","notes":[]},{"n":37,"t":"若有人以為自己是先知，或是屬靈的，就該知道，我所寫給你們的是主的命令。","notes":[]},{"n":38,"t":"若有不知道的，就由他不知道吧！","notes":[]},{"n":39,"t":"所以我弟兄們，你們要切慕作先知講道，也不要禁止說方言。","notes":[]},{"n":40,"t":"凡事都要規規矩矩地按著次序行。","notes":[]}]},"15":{"heading":"基督的復活","verses":[{"n":1,"t":"弟兄們，我如今把先前所傳給你們的福音告訴你們知道；這福音你們也領受了，又靠著站立得住，","notes":[]},{"n":2,"t":"並且你們若不是徒然相信，能以持守我所傳給你們的，就必因這福音得救。","notes":[]},{"n":3,"t":"我當日所領受又傳給你們的：第一，就是基督照聖經所說，為我們的罪死了，","notes":[]},{"n":4,"t":"而且埋葬了；又照聖經所說，第三天復活了，","notes":[]},{"n":5,"t":"並且顯給磯法看，然後顯給十二使徒看；","notes":[]},{"n":6,"t":"後來一時顯給五百多弟兄看，其中一大半到如今還在，卻也有已經睡了的。","notes":[]},{"n":7,"t":"以後顯給雅各看，再顯給眾使徒看，","notes":[]},{"n":8,"t":"末了也顯給我看；我如同未到產期而生的人一般。","notes":[]},{"n":9,"t":"我原是使徒中最小的，不配稱為使徒，因為我從前逼迫神的教會。","notes":[]},{"n":10,"t":"然而，我今日成了何等人，是蒙神的恩才成的，並且他所賜我的恩不是徒然的。我比眾使徒格外勞苦；這原不是我，乃是神的恩與我同在。","notes":[]},{"n":11,"t":"不拘是我，是眾使徒，我們如此傳，你們也如此信了。","notes":[]},{"n":12,"t":"既傳基督是從死裏復活了，怎麼在你們中間有人說沒有死人復活的事呢？","notes":[],"heads":["死人的復活"]},{"n":13,"t":"若沒有死人復活的事，基督也就沒有復活了。","notes":[]},{"n":14,"t":"若基督沒有復活，我們所傳的便是枉然，你們所信的也是枉然；","notes":[]},{"n":15,"t":"並且明顯我們是為神妄作見證的，因我們見證神是叫基督復活了。若死人真不復活，神也就沒有叫基督復活了。","notes":[]},{"n":16,"t":"因為死人若不復活，基督也就沒有復活了。","notes":[]},{"n":17,"t":"基督若沒有復活，你們的信便是徒然，你們仍在罪裏。","notes":[]},{"n":18,"t":"就是在基督裏睡了的人也滅亡了。","notes":[]},{"n":19,"t":"我們若靠基督只在今生有指望，就算比眾人更可憐。","notes":[]},{"n":20,"t":"但基督已經從死裏復活，成為睡了之人初熟的果子。","notes":[]},{"n":21,"t":"死既是因一人而來，死人復活也是因一人而來。","notes":[]},{"n":22,"t":"在亞當裏眾人都死了；照樣，在基督裏眾人也都要復活。","notes":[]},{"n":23,"t":"但各人是按著自己的次序復活：初熟的果子是基督；以後，在他來的時候，是那些屬基督的。","notes":[]},{"n":24,"t":"再後，末期到了，那時基督既將一切執政的、掌權的、有能的都毀滅了，就把國交與父神。","notes":[]},{"n":25,"t":"因為基督必要作王，等神把一切仇敵都放在他的腳下。","notes":[]},{"n":26,"t":"儘末了所毀滅的仇敵就是死。","notes":[]},{"n":27,"t":"因為經上說：「神叫萬物都服在他的腳下。」既說萬物都服了他，明顯那叫萬物服他的，不在其內了。","notes":[]},{"n":28,"t":"萬物既服了他，那時子也要自己服那叫萬物服他的，叫神在萬物之上，為萬物之主。","notes":[]},{"n":29,"t":"不然，那些為死人受洗的，將來怎樣呢？若死人總不復活，因何為他們受洗呢？","notes":[]},{"n":30,"t":"我們又因何時刻冒險呢？","notes":[]},{"n":31,"t":"弟兄們，我在我主基督耶穌裏，指著你們所誇的口極力地說，我是天天冒死。","notes":[]},{"n":32,"t":"我若當日像尋常人，在以弗所同野獸戰鬥，那於我有甚麼益處呢？若死人不復活，我們就吃吃喝喝吧！因為明天要死了。","notes":[]},{"n":33,"t":"你們不要自欺；濫交是敗壞善行。","notes":[]},{"n":34,"t":"你們要醒悟為善，不要犯罪，因為有人不認識神。我說這話是要叫你們羞愧。","notes":[]},{"n":35,"t":"或有人問：「死人怎樣復活，帶著甚麼身體來呢？」","notes":[],"heads":["復活的身體"]},{"n":36,"t":"無知的人哪，你所種的，若不死就不能生。","notes":[]},{"n":37,"t":"並且你所種的不是那將來的形體，不過是子粒，即如麥子，或是別樣的穀。","notes":[]},{"n":38,"t":"但神隨自己的意思給他一個形體，並叫各等子粒各有自己的形體。","notes":[]},{"n":39,"t":"凡肉體各有不同：人是一樣，獸又是一樣，鳥又是一樣，魚又是一樣。","notes":[]},{"n":40,"t":"有天上的形體，也有地上的形體；但天上形體的榮光是一樣，地上形體的榮光又是一樣。","notes":[]},{"n":41,"t":"日有日的榮光，月有月的榮光，星有星的榮光；這星和那星的榮光也有分別。","notes":[]},{"n":42,"t":"死人復活也是這樣：所種的是必朽壞的，復活的是不朽壞的；","notes":[]},{"n":43,"t":"所種的是羞辱的，復活的是榮耀的；所種的是軟弱的，復活的是強壯的；","notes":[]},{"n":44,"t":"所種的是血氣的身體，復活的是靈性的身體。若有血氣的身體，也必有靈性的身體。","notes":[]},{"n":45,"t":"經上也是這樣記著說：「首先的人亞當成了有靈的活人」；末後的亞當成了叫人活的靈。","notes":["靈：或譯血氣"]},{"n":46,"t":"但屬靈的不在先，屬血氣的在先，以後才有屬靈的。","notes":[]},{"n":47,"t":"頭一個人是出於地，乃屬土；第二個人是出於天。","notes":[]},{"n":48,"t":"那屬土的怎樣，凡屬土的也就怎樣；屬天的怎樣，凡屬天的也就怎樣。","notes":[]},{"n":49,"t":"我們既有屬土的形狀，將來也必有屬天的形狀。","notes":[]},{"n":50,"t":"弟兄們，我告訴你們說，血肉之體不能承受神的國，必朽壞的不能承受不朽壞的。","notes":[]},{"n":51,"t":"我如今把一件奧祕的事告訴你們：我們不是都要睡覺，乃是都要改變，","notes":[]},{"n":52,"t":"就在一霎時，眨眼之間，號筒末次吹響的時候。因號筒要響，死人要復活成為不朽壞的，我們也要改變。","notes":[]},{"n":53,"t":"這必朽壞的總要變成不朽壞的，這必死的總要變成不死的。","notes":["變成：原文是穿；下同"]},{"n":54,"t":"這必朽壞的既變成不朽壞的，這必死的既變成不死的，那時經上所記「死被得勝吞滅」的話就應驗了。","notes":[]},{"n":55,"t":"死啊！你得勝的權勢在哪裏？死啊！你的毒鉤在哪裏？","notes":[]},{"n":56,"t":"死的毒鉤就是罪，罪的權勢就是律法。","notes":[]},{"n":57,"t":"感謝神，使我們藉著我們的主耶穌基督得勝。","notes":[]},{"n":58,"t":"所以，我親愛的弟兄們，你們務要堅固，不可搖動，常常竭力多做主工；因為知道，你們的勞苦在主裏面不是徒然的。","notes":[]}]},"16":{"heading":"捐助聖徒","verses":[{"n":1,"t":"論到為聖徒捐錢，我從前怎樣吩咐加拉太的眾教會，你們也當怎樣行。","notes":[]},{"n":2,"t":"每逢七日的第一日，各人要照自己的進項抽出來留著，免得我來的時候現湊。","notes":[]},{"n":3,"t":"及至我來到了，你們寫信舉薦誰，我就打發他們，把你們的捐資送到耶路撒冷去。","notes":[]},{"n":4,"t":"若我也該去，他們可以和我同去。","notes":[]},{"n":5,"t":"我要從馬其頓經過；既經過了，就要到你們那裏去，","notes":[],"heads":["行程的計劃"]},{"n":6,"t":"或者和你們同住幾時，或者也過冬。無論我往哪裏去，你們就可以給我送行。","notes":[]},{"n":7,"t":"我如今不願意路過見你們；主若許我，我就指望和你們同住幾時。","notes":[]},{"n":8,"t":"但我要仍舊住在以弗所，直等到五旬節；","notes":[]},{"n":9,"t":"因為有寬大又有功效的門為我開了，並且反對的人也多。","notes":[]},{"n":10,"t":"若是提摩太來到，你們要留心，叫他在你們那裏無所懼怕；因為他勞力做主的工，像我一樣。","notes":[]},{"n":11,"t":"所以，無論誰都不可藐視他，只要送他平安前行，叫他到我這裏來，因我指望他和弟兄們同來。","notes":[]},{"n":12,"t":"至於兄弟亞波羅，我再三地勸他同弟兄們到你們那裏去；但這時他決不願意去，幾時有了機會他必去。","notes":[]},{"n":13,"t":"你們務要警醒，在真道上站立得穩，要作大丈夫，要剛強。","notes":[],"heads":["請求和問安"]},{"n":14,"t":"凡你們所做的都要憑愛心而做。","notes":[]},{"n":15,"t":"弟兄們，你們曉得司提法那一家，是亞該亞初結的果子，並且他們專以服事聖徒為念。","notes":[]},{"n":16,"t":"我勸你們順服這樣的人，並一切同工同勞的人。","notes":[]},{"n":17,"t":"司提法那和福徒拿都，並亞該古到這裏來，我很喜歡；因為你們待我有不及之處，他們補上了。","notes":[]},{"n":18,"t":"他們叫我和你們心裏都快活。這樣的人，你們務要敬重。","notes":[]},{"n":19,"t":"亞細亞的眾教會問你們安。亞居拉和百基拉並在他們家裏的教會，因主多多地問你們安。","notes":[]},{"n":20,"t":"眾弟兄都問你們安。你們要親嘴問安，彼此務要聖潔。","notes":[]},{"n":21,"t":"我－保羅親筆問安。","notes":[]},{"n":22,"t":"若有人不愛主，這人可詛可咒。主必要來！","notes":[]},{"n":23,"t":"願主耶穌基督的恩常與你們眾人同在！","notes":[]},{"n":24,"t":"我在基督耶穌裏的愛與你們眾人同在。阿們！","notes":[]}]}},"2CO":{"1":{"heading":"問候","verses":[{"n":1,"t":"奉神旨意作基督耶穌使徒的保羅和兄弟提摩太，寫信給在哥林多神的教會，並亞該亞遍處的眾聖徒。","notes":[]},{"n":2,"t":"願恩惠、平安從神我們的父和主耶穌基督歸與你們！","notes":[]},{"n":3,"t":"願頌讚歸與我們的主耶穌基督的父神，就是發慈悲的父，賜各樣安慰的神。","notes":[],"heads":["保羅受患難後的感恩"]},{"n":4,"t":"我們在一切患難中，他就安慰我們，叫我們能用神所賜的安慰去安慰那遭各樣患難的人。","notes":[]},{"n":5,"t":"我們既多受基督的苦楚，就靠基督多得安慰。","notes":[]},{"n":6,"t":"我們受患難呢，是為叫你們得安慰，得拯救；我們得安慰呢，也是為叫你們得安慰；這安慰能叫你們忍受我們所受的那樣苦楚。","notes":[]},{"n":7,"t":"我們為你們所存的盼望是確定的，因為知道你們既是同受苦楚，也必同得安慰。","notes":[]},{"n":8,"t":"弟兄們，我們不要你們不曉得，我們從前在亞細亞遭遇苦難，被壓太重，力不能勝，甚至連活命的指望都絕了；","notes":[]},{"n":9,"t":"自己心裏也斷定是必死的，叫我們不靠自己，只靠叫死人復活的神。","notes":[]},{"n":10,"t":"他曾救我們脫離那極大的死亡，現在仍要救我們，並且我們指望他將來還要救我們。","notes":[]},{"n":11,"t":"你們以祈禱幫助我們，好叫許多人為我們謝恩，就是為我們因許多人所得的恩。","notes":[]},{"n":12,"t":"我們所誇的是自己的良心，見證我們憑著神的聖潔和誠實；在世為人不靠人的聰明，乃靠神的恩惠，向你們更是這樣。","notes":[],"heads":["保羅延期訪問哥林多"]},{"n":13,"t":"我們現在寫給你們的話，並不外乎你們所念的、所認識的，我也盼望你們到底還是要認識；","notes":[]},{"n":14,"t":"正如你們已經有幾分認識我們，以我們誇口，好像我們在我們主耶穌的日子以你們誇口一樣。","notes":[]},{"n":15,"t":"我既然這樣深信，就早有意到你們那裏去，叫你們再得益處；","notes":[]},{"n":16,"t":"也要從你們那裏經過，往馬其頓去，再從馬其頓回到你們那裏，叫你們給我送行往猶太去。","notes":[]},{"n":17,"t":"我有此意，豈是反覆不定嗎？我所起的意，豈是從情慾起的，叫我忽是忽非嗎？","notes":[]},{"n":18,"t":"我指著信實的神說，我們向你們所傳的道，並沒有是而又非的。","notes":[]},{"n":19,"t":"因為我和西拉並提摩太，在你們中間所傳神的兒子耶穌基督，總沒有是而又非的，在他只有一是。","notes":[]},{"n":20,"t":"神的應許，不論有多少，在基督都是是的。所以藉著他也都是實在的，叫神因我們得榮耀。","notes":["實在：原文是阿們"]},{"n":21,"t":"那在基督裏堅固我們和你們，並且膏我們的就是神。","notes":[]},{"n":22,"t":"他又用印印了我們，並賜聖靈在我們心裏作憑據。","notes":["原文是質"]},{"n":23,"t":"我呼籲神給我的心作見證，我沒有往哥林多去是為要寬容你們。","notes":[]},{"n":24,"t":"我們並不是轄管你們的信心，乃是幫助你們的快樂，因為你們憑信才站立得住。","notes":[]}]},"2":{"heading":"赦免犯過失的人","verses":[{"n":1,"t":"我自己定了主意再到你們那裏去，必須大家沒有憂愁。","notes":[]},{"n":2,"t":"倘若我叫你們憂愁，除了我叫那憂愁的人以外，誰能叫我快樂呢？","notes":[]},{"n":3,"t":"我曾把這事寫給你們，恐怕我到的時候，應該叫我快樂的那些人，反倒叫我憂愁。我也深信，你們眾人都以我的快樂為自己的快樂。","notes":[]},{"n":4,"t":"我先前心裏難過痛苦，多多地流淚，寫信給你們，不是叫你們憂愁，乃是叫你們知道我格外地疼愛你們。","notes":[]},{"n":5,"t":"若有叫人憂愁的，他不但叫我憂愁，也是叫你們眾人有幾分憂愁。我說幾分，恐怕說得太重。","notes":[]},{"n":6,"t":"這樣的人受了眾人的責罰也就夠了，","notes":[]},{"n":7,"t":"倒不如赦免他，安慰他，免得他憂愁太過，甚至沉淪了。","notes":[]},{"n":8,"t":"所以我勸你們，要向他顯出堅定不移的愛心來。","notes":[]},{"n":9,"t":"為此我先前也寫信給你們，要試驗你們，看你們凡事順從不順從。","notes":[]},{"n":10,"t":"你們赦免誰，我也赦免誰。我若有所赦免的，是在基督面前為你們赦免的，","notes":[]},{"n":11,"t":"免得撒但趁著機會勝過我們，因我們並非不曉得他的詭計。","notes":[]},{"n":12,"t":"我從前為基督的福音到了特羅亞，主也給我開了門。","notes":[],"heads":["保羅的憂愁和安慰"]},{"n":13,"t":"那時，因為沒有遇見兄弟提多，我心裏不安，便辭別那裏的人往馬其頓去了。","notes":[]},{"n":14,"t":"感謝神！常率領我們在基督裏誇勝，並藉著我們在各處顯揚那因認識基督而有的香氣。","notes":[]},{"n":15,"t":"因為我們在神面前，無論在得救的人身上或滅亡的人身上，都有基督馨香之氣。","notes":[]},{"n":16,"t":"在這等人，就作了死的香氣叫他死；在那等人，就作了活的香氣叫他活。這事誰能當得起呢？","notes":[]},{"n":17,"t":"我們不像那許多人，為利混亂神的道；乃是由於誠實，由於神，在神面前憑著基督講道。","notes":[]}]},"3":{"heading":"新約的執事","verses":[{"n":1,"t":"我們豈是又舉薦自己嗎？豈像別人用人的薦信給你們或用你們的薦信給人嗎？","notes":[]},{"n":2,"t":"你們就是我們的薦信，寫在我們的心裏，被眾人所知道所念誦的。","notes":[]},{"n":3,"t":"你們明顯是基督的信，藉著我們修成的。不是用墨寫的，乃是用永生神的靈寫的；不是寫在石版上，乃是寫在心版上。","notes":[]},{"n":4,"t":"我們因基督，所以在神面前才有這樣的信心。","notes":[]},{"n":5,"t":"並不是我們憑自己能承擔甚麼事；我們所能承擔的，乃是出於神。","notes":[]},{"n":6,"t":"他叫我們能承當這新約的執事，不是憑著字句，乃是憑著精意；因為那字句是叫人死，精意是叫人活。","notes":["或譯：聖靈"]},{"n":7,"t":"那用字刻在石頭上屬死的職事尚且有榮光，甚至以色列人因摩西面上的榮光，不能定睛看他的臉；這榮光原是漸漸退去的，","notes":[]},{"n":8,"t":"何況那屬靈的職事豈不更有榮光嗎？","notes":[]},{"n":9,"t":"若是定罪的職事有榮光，那稱義的職事榮光就越發大了。","notes":[]},{"n":10,"t":"那從前有榮光的，因這極大的榮光就算不得有榮光了；","notes":[]},{"n":11,"t":"若那廢掉的有榮光，這長存的就更有榮光了。","notes":[]},{"n":12,"t":"我們既有這樣的盼望，就大膽講說，","notes":[]},{"n":13,"t":"不像摩西將帕子蒙在臉上，叫以色列人不能定睛看到那將廢者的結局。","notes":[]},{"n":14,"t":"但他們的心地剛硬，直到今日誦讀舊約的時候，這帕子還沒有揭去。這帕子在基督裏已經廢去了。","notes":[]},{"n":15,"t":"然而直到今日，每逢誦讀摩西書的時候，帕子還在他們心上。","notes":[]},{"n":16,"t":"但他們的心幾時歸向主，帕子就幾時除去了。","notes":[]},{"n":17,"t":"主就是那靈；主的靈在哪裏，那裏就得以自由。","notes":[]},{"n":18,"t":"我們眾人既然敞著臉得以看見主的榮光，好像從鏡子裏返照，就變成主的形狀，榮上加榮，如同從主的靈變成的。","notes":[]}]},"4":{"heading":"在瓦器裏的寶貝","verses":[{"n":1,"t":"我們既然蒙憐憫，受了這職分，就不喪膽，","notes":[]},{"n":2,"t":"乃將那些暗昧可恥的事棄絕了；不行詭詐，不謬講神的道理，只將真理表明出來，好在神面前把自己薦與各人的良心。","notes":[]},{"n":3,"t":"如果我們的福音蒙蔽，就是蒙蔽在滅亡的人身上。","notes":[]},{"n":4,"t":"此等不信之人被這世界的神弄瞎了心眼，不叫基督榮耀福音的光照著他們。基督本是神的像。","notes":[]},{"n":5,"t":"我們原不是傳自己，乃是傳基督耶穌為主，並且自己因耶穌作你們的僕人。","notes":[]},{"n":6,"t":"那吩咐光從黑暗裏照出來的神，已經照在我們心裏，叫我們得知神榮耀的光顯在耶穌基督的面上。","notes":[]},{"n":7,"t":"我們有這寶貝放在瓦器裏，要顯明這莫大的能力是出於神，不是出於我們。","notes":[]},{"n":8,"t":"我們四面受敵，卻不被困住；心裏作難，卻不致失望；","notes":[]},{"n":9,"t":"遭逼迫，卻不被丟棄；打倒了，卻不致死亡。","notes":[]},{"n":10,"t":"身上常帶著耶穌的死，使耶穌的生也顯明在我們身上。","notes":[]},{"n":11,"t":"因為我們這活著的人是常為耶穌被交於死地，使耶穌的生在我們這必死的身上顯明出來。","notes":[]},{"n":12,"t":"這樣看來，死是在我們身上發動，生卻在你們身上發動。","notes":[]},{"n":13,"t":"但我們既有信心，正如經上記著說：「我因信，所以如此說話。」我們也信，所以也說話。","notes":[]},{"n":14,"t":"自己知道那叫主耶穌復活的，也必叫我們與耶穌一同復活，並且叫我們與你們一同站在他面前。","notes":[]},{"n":15,"t":"凡事都是為你們，好叫恩惠因人多越發加增，感謝格外顯多，以致榮耀歸與神。","notes":[]},{"n":16,"t":"所以，我們不喪膽。外體雖然毀壞，內心卻一天新似一天。","notes":[],"heads":["靠信心生活"]},{"n":17,"t":"我們這至暫至輕的苦楚，要為我們成就極重無比、永遠的榮耀。","notes":[]},{"n":18,"t":"原來我們不是顧念所見的，乃是顧念所不見的；因為所見的是暫時的，所不見的是永遠的。","notes":[]}]},"5":{"heading":"勸人與神和好的職分","verses":[{"n":1,"t":"我們原知道，我們這地上的帳棚若拆毀了，必得神所造，不是人手所造，在天上永存的房屋。","notes":[]},{"n":2,"t":"我們在這帳棚裏歎息，深想得那從天上來的房屋，好像穿上衣服；","notes":[]},{"n":3,"t":"倘若穿上，被遇見的時候就不至於赤身了。","notes":[]},{"n":4,"t":"我們在這帳棚裏歎息勞苦，並非願意脫下這個，乃是願意穿上那個，好叫這必死的被生命吞滅了。","notes":[]},{"n":5,"t":"為此，培植我們的就是神，他又賜給我們聖靈作憑據。","notes":["原文是質"]},{"n":6,"t":"所以，我們時常坦然無懼，並且曉得我們住在身內，便與主相離。","notes":[]},{"n":7,"t":"因我們行事為人是憑著信心，不是憑著眼見。","notes":[]},{"n":8,"t":"我們坦然無懼，是更願意離開身體與主同住。","notes":[]},{"n":9,"t":"所以，無論是住在身內，離開身外，我們立了志向，要得主的喜悅。","notes":[]},{"n":10,"t":"因為我們眾人必要在基督臺前顯露出來，叫各人按著本身所行的，或善或惡受報。","notes":[]},{"n":11,"t":"我們既知道主是可畏的，所以勸人。但我們在神面前是顯明的，盼望在你們的良心裏也是顯明的。","notes":[]},{"n":12,"t":"我們不是向你們再舉薦自己，乃是叫你們因我們有可誇之處，好對那憑外貌不憑內心誇口的人，有言可答。","notes":[]},{"n":13,"t":"我們若果顛狂，是為神；若果謹守，是為你們。","notes":[]},{"n":14,"t":"原來基督的愛激勵我們；因我們想，一人既替眾人死，眾人就都死了；","notes":[]},{"n":15,"t":"並且他替眾人死，是叫那些活著的人不再為自己活，乃為替他們死而復活的主活。","notes":[]},{"n":16,"t":"所以，我們從今以後，不憑著外貌認人了。雖然憑著外貌認過基督，如今卻不再這樣認他了。","notes":["原文是肉體；本節同"]},{"n":17,"t":"若有人在基督裏，他就是新造的人，舊事已過，都變成新的了。","notes":[]},{"n":18,"t":"一切都是出於神；他藉著基督使我們與他和好，又將勸人與他和好的職分賜給我們。","notes":[]},{"n":19,"t":"這就是神在基督裏，叫世人與自己和好，不將他們的過犯歸到他們身上，並且將這和好的道理託付了我們。","notes":[]},{"n":20,"t":"所以，我們作基督的使者，就好像神藉我們勸你們一般。我們替基督求你們與神和好。","notes":[]},{"n":21,"t":"神使那無罪的，替我們成為罪，好叫我們在他裏面成為神的義。","notes":["無罪：原文是不知罪"]}]},"6":{"heading":"永生神的殿","verses":[{"n":1,"t":"我們與神同工的，也勸你們不可徒受他的恩典。","notes":[]},{"n":2,"t":"因為他說：「在悅納的時候，我應允了你；在拯救的日子，我搭救了你。」看哪，現在正是悅納的時候！現在正是拯救的日子；","notes":[]},{"n":3,"t":"我們凡事都不叫人有妨礙，免得這職分被人毀謗；","notes":[]},{"n":4,"t":"反倒在各樣的事上表明自己是神的用人，就如在許多的忍耐、患難、窮乏、困苦、","notes":[]},{"n":5,"t":"鞭打、監禁、擾亂、勤勞、警醒、不食、","notes":[]},{"n":6,"t":"廉潔、知識、恆忍、恩慈、聖靈的感化、無偽的愛心、","notes":[]},{"n":7,"t":"真實的道理、神的大能；仁義的兵器在左在右；","notes":[]},{"n":8,"t":"榮耀、羞辱，惡名、美名；似乎是誘惑人的，卻是誠實的；","notes":[]},{"n":9,"t":"似乎不為人所知，卻是人所共知的；似乎要死，卻是活著的；似乎受責罰，卻是不致喪命的；","notes":[]},{"n":10,"t":"似乎憂愁，卻是常常快樂的；似乎貧窮，卻是叫許多人富足的；似乎一無所有，卻是樣樣都有的。","notes":[]},{"n":11,"t":"哥林多人哪，我們向你們，口是張開的，心是寬宏的。","notes":[]},{"n":12,"t":"你們狹窄，原不在乎我們，是在乎自己的心腸狹窄。","notes":[]},{"n":13,"t":"你們也要照樣用寬宏的心報答我。我這話正像對自己的孩子說的。","notes":[]},{"n":14,"t":"你們和不信的原不相配，不要同負一軛。義和不義有甚麼相交呢？光明和黑暗有甚麼相通呢？","notes":[]},{"n":15,"t":"基督和彼列有甚麼相和呢？信主的和不信主的有甚麼相干呢？","notes":["彼列就是撒但的別名"]},{"n":16,"t":"神的殿和偶像有甚麼相同呢？因為我們是永生神的殿，就如神曾說：我要在他們中間居住，在他們中間來往；我要作他們的神；他們要作我的子民。","notes":[]},{"n":17,"t":"又說：你們務要從他們中間出來，與他們分別；不要沾不潔淨的物，我就收納你們。","notes":[]},{"n":18,"t":"我要作你們的父；你們要作我的兒女。這是全能的主說的。","notes":[]}]},"7":{"heading":"保羅為教會悔改而歡樂","verses":[{"n":1,"t":"親愛的弟兄啊，我們既有這等應許，就當潔淨自己，除去身體、靈魂一切的污穢，敬畏神，得以成聖。","notes":[]},{"n":2,"t":"你們要心地寬大收納我們。我們未曾虧負誰，未曾敗壞誰，未曾佔誰的便宜。","notes":[]},{"n":3,"t":"我說這話，不是要定你們的罪。我已經說過，你們常在我們心裏，情願與你們同生同死。","notes":[]},{"n":4,"t":"我大大地放膽，向你們說話；我因你們多多誇口，滿得安慰；我們在一切患難中分外地快樂。","notes":[]},{"n":5,"t":"我們從前就是到了馬其頓的時候，身體也不得安寧，周圍遭患難，外有爭戰，內有懼怕。","notes":[]},{"n":6,"t":"但那安慰喪氣之人的神藉著提多來安慰了我們；","notes":[]},{"n":7,"t":"不但藉著他來，也藉著他從你們所得的安慰，安慰了我們；因他把你們的想念、哀慟，和向我的熱心，都告訴了我，叫我更加歡喜。","notes":[]},{"n":8,"t":"我先前寫信叫你們憂愁，我後來雖然懊悔，如今卻不懊悔；因我知道，那信叫你們憂愁不過是暫時的。","notes":[]},{"n":9,"t":"如今我歡喜，不是因你們憂愁，是因你們從憂愁中生出懊悔來。你們依著神的意思憂愁，凡事就不至於因我們受虧損了。","notes":[]},{"n":10,"t":"因為依著神的意思憂愁，就生出沒有後悔的懊悔來，以致得救；但世俗的憂愁是叫人死。","notes":[]},{"n":11,"t":"你看，你們依著神的意思憂愁，從此就生出何等的殷勤、自訴、自恨、恐懼、想念、熱心、責罰。在這一切事上，你們都表明自己是潔淨的。","notes":["或譯：自責"]},{"n":12,"t":"我雖然從前寫信給你們，卻不是為那虧負人的，也不是為那受人虧負的，乃要在神面前把你們顧念我們的熱心表明出來。","notes":[]},{"n":13,"t":"故此，我們得了安慰。並且在安慰之中，因你們眾人使提多心裏暢快歡喜，我們就更加歡喜了。","notes":[]},{"n":14,"t":"我若對提多誇獎了你們甚麼，也覺得沒有慚愧；因我對提多誇獎你們的話成了真的，正如我對你們所說的話也都是真的。","notes":[]},{"n":15,"t":"並且提多想起你們眾人的順服，是怎樣恐懼戰兢地接待他，他愛你們的心腸就越發熱了。","notes":[]},{"n":16,"t":"我如今歡喜，能在凡事上為你們放心。","notes":[]}]},"8":{"heading":"慷慨的捐助","verses":[{"n":1,"t":"弟兄們，我把神賜給馬其頓眾教會的恩告訴你們，","notes":[]},{"n":2,"t":"就是他們在患難中受大試煉的時候，仍有滿足的快樂，在極窮之間還格外顯出他們樂捐的厚恩。","notes":[]},{"n":3,"t":"我可以證明，他們是按著力量，而且也過了力量，自己甘心樂意地捐助，","notes":[]},{"n":4,"t":"再三地求我們，准他們在這供給聖徒的恩情上有分；","notes":[]},{"n":5,"t":"並且他們所做的，不但照我們所想望的，更照神的旨意先把自己獻給主，又歸附了我們。","notes":[]},{"n":6,"t":"因此我勸提多，既然在你們中間開辦這慈惠的事，就當辦成了。","notes":[]},{"n":7,"t":"你們既然在信心、口才、知識、熱心，和待我們的愛心上，都格外顯出滿足來，就當在這慈惠的事上也格外顯出滿足來。","notes":[]},{"n":8,"t":"我說這話，不是吩咐你們，乃是藉著別人的熱心試驗你們愛心的實在。","notes":[]},{"n":9,"t":"你們知道我們主耶穌基督的恩典：他本來富足，卻為你們成了貧窮，叫你們因他的貧窮，可以成為富足。","notes":[]},{"n":10,"t":"我在這事上把我的意見告訴你們，是與你們有益；因為你們下手辦這事，而且起此心意，已經有一年了，","notes":[]},{"n":11,"t":"如今就當辦成這事。既有願做的心，也當照你們所有的去辦成。","notes":[]},{"n":12,"t":"因為人若有願做的心，必蒙悅納，乃是照他所有的，並不是照他所無的。","notes":[]},{"n":13,"t":"我原不是要別人輕省，你們受累，","notes":[]},{"n":14,"t":"乃要均平，就是要你們的富餘，現在可以補他們的不足，使他們的富餘，將來也可以補你們的不足，這就均平了。","notes":[]},{"n":15,"t":"如經上所記：多收的也沒有餘；少收的也沒有缺。","notes":[]},{"n":16,"t":"多謝神，感動提多的心，叫他待你們殷勤，像我一樣。","notes":[],"heads":["提多和他的同工"]},{"n":17,"t":"他固然是聽了我的勸，但自己更是熱心，情願往你們那裏去。","notes":[]},{"n":18,"t":"我們還打發一位兄弟和他同去，這人在福音上得了眾教會的稱讚。","notes":[]},{"n":19,"t":"不但這樣，他也被眾教會挑選，和我們同行，把所託與我們的這捐資送到了，可以榮耀主，又表明我們樂意的心。","notes":[]},{"n":20,"t":"這就免得有人因我們收的捐銀很多，就挑我們的不是。","notes":[]},{"n":21,"t":"我們留心行光明的事，不但在主面前，就在人面前也是這樣。","notes":[]},{"n":22,"t":"我們又打發一位兄弟同去；這人的熱心，我們在許多事上屢次試驗過。現在他因為深信你們，就更加熱心了。","notes":[]},{"n":23,"t":"論到提多，他是我的同伴，一同為你們勞碌的。論到那兩位兄弟，他們是眾教會的使者，是基督的榮耀。","notes":[]},{"n":24,"t":"所以，你們務要在眾教會面前顯明你們愛心的憑據，並我所誇獎你們的憑據。","notes":[]}]},"9":{"heading":"幫助聖徒的捐款","verses":[{"n":1,"t":"論到供給聖徒的事，我不必寫信給你們；","notes":[]},{"n":2,"t":"因為我知道你們樂意的心，常對馬其頓人誇獎你們，說亞該亞人預備好了，已經有一年了；並且你們的熱心激動了許多人。","notes":[]},{"n":3,"t":"但我打發那幾位弟兄去，要叫你們照我的話預備妥當，免得我們在這事上誇獎你們的話落了空。","notes":[]},{"n":4,"t":"萬一有馬其頓人與我同去，見你們沒有預備，就叫我們所確信的，反成了羞愧；你們羞愧，更不用說了。","notes":[]},{"n":5,"t":"因此，我想不得不求那幾位弟兄先到你們那裏去，把從前所應許的捐資預備妥當，就顯出你們所捐的是出於樂意，不是出於勉強。","notes":[]},{"n":6,"t":"「少種的少收，多種的多收」，這話是真的。","notes":[]},{"n":7,"t":"各人要隨本心所酌定的，不要作難，不要勉強，因為捐得樂意的人是神所喜愛的。","notes":[]},{"n":8,"t":"神能將各樣的恩惠多多地加給你們，使你們凡事常常充足，能多行各樣善事。","notes":[]},{"n":9,"t":"如經上所記：他施捨錢財，賙濟貧窮；他的仁義存到永遠。","notes":[]},{"n":10,"t":"那賜種給撒種的，賜糧給人吃的，必多多加給你們種地的種子，又增添你們仁義的果子；","notes":[]},{"n":11,"t":"叫你們凡事富足，可以多多施捨，就藉著我們使感謝歸於神。","notes":[]},{"n":12,"t":"因為辦這供給的事，不但補聖徒的缺乏，而且叫許多人越發感謝神。","notes":[]},{"n":13,"t":"他們從這供給的事上得了憑據，知道你們承認基督順服他的福音，多多地捐錢給他們和眾人，便將榮耀歸與神。","notes":[]},{"n":14,"t":"他們也因神極大的恩賜顯在你們心裏，就切切地想念你們，為你們祈禱。","notes":[]},{"n":15,"t":"感謝神，因他有說不盡的恩賜！","notes":[]}]},"10":{"heading":"保羅為他的工作辯護","verses":[{"n":1,"t":"我－保羅，就是與你們見面的時候是謙卑的，不在你們那裏的時候向你們是勇敢的，如今親自藉著基督的溫柔、和平勸你們。","notes":[]},{"n":2,"t":"有人以為我是憑著血氣行事，我也以為必須用勇敢待這等人；求你們不要叫我在你們那裏的時候，有這樣的勇敢。","notes":[]},{"n":3,"t":"因為我們雖然在血氣中行事，卻不憑著血氣爭戰。","notes":[]},{"n":4,"t":"我們爭戰的兵器本不是屬血氣的，乃是在神面前有能力，可以攻破堅固的營壘，","notes":[]},{"n":5,"t":"將各樣的計謀，各樣攔阻人認識神的那些自高之事，一概攻破了，又將人所有的心意奪回，使他都順服基督。","notes":[]},{"n":6,"t":"並且我已經預備好了，等你們十分順服的時候，要責罰那一切不順服的人。","notes":[]},{"n":7,"t":"你們是看眼前的嗎？倘若有人自信是屬基督的，他要再想想，他如何屬基督，我們也是如何屬基督的。","notes":[]},{"n":8,"t":"主賜給我們權柄，是要造就你們，並不是要敗壞你們；我就是為這權柄稍微誇口，也不至於慚愧。","notes":[]},{"n":9,"t":"我說這話，免得你們以為我寫信是要威嚇你們；","notes":[]},{"n":10,"t":"因為有人說：「他的信又沉重又厲害，及至見面，卻是氣貌不揚，言語粗俗的。」","notes":[]},{"n":11,"t":"這等人當想，我們不在那裏的時候，信上的言語如何，見面的時候，行事也必如何。","notes":[]},{"n":12,"t":"因為我們不敢將自己和那自薦的人同列相比。他們用自己度量自己，用自己比較自己，乃是不通達的。","notes":[]},{"n":13,"t":"我們不願意分外誇口，只要照神所量給我們的界限搆到你們那裏。","notes":[]},{"n":14,"t":"我們並非過了自己的界限，好像搆不到你們那裏；因為我們早到你們那裏，傳了基督的福音。","notes":[]},{"n":15,"t":"我們不仗著別人所勞碌的，分外誇口；但指望你們信心增長的時候，所量給我們的界限，就可以因著你們更加開展，","notes":[],"heads":["當指著主誇口"]},{"n":16,"t":"得以將福音傳到你們以外的地方；並不是在別人界限之內，藉著他現成的事誇口。","notes":[]},{"n":17,"t":"但誇口的，當指著主誇口。","notes":[]},{"n":18,"t":"因為蒙悅納的，不是自己稱許的，乃是主所稱許的。","notes":[]}]},"11":{"heading":"保羅和假使徒","verses":[{"n":1,"t":"但願你們寬容我這一點愚妄，其實你們原是寬容我的。","notes":[]},{"n":2,"t":"我為你們起的憤恨，原是神那樣的憤恨。因為我曾把你們許配一個丈夫，要把你們如同貞潔的童女，獻給基督。","notes":[]},{"n":3,"t":"我只怕你們的心或偏於邪，失去那向基督所存純一清潔的心，就像蛇用詭詐誘惑了夏娃一樣。","notes":[]},{"n":4,"t":"假如有人來另傳一個耶穌，不是我們所傳過的；或者你們另受一個靈，不是你們所受過的；或者另得一個福音，不是你們所得過的；你們容讓他也就罷了。","notes":[]},{"n":5,"t":"但我想，我一點不在那些最大的使徒以下。","notes":[]},{"n":6,"t":"我的言語雖然粗俗，我的知識卻不粗俗。這是我們在凡事上向你們眾人顯明出來的。","notes":[]},{"n":7,"t":"我因為白白傳神的福音給你們，就自居卑微，叫你們高升，這算是我犯罪嗎？","notes":[]},{"n":8,"t":"我虧負了別的教會，向他們取了工價來給你們效力。","notes":[]},{"n":9,"t":"我在你們那裏缺乏的時候，並沒有累著你們一個人；因我所缺乏的，那從馬其頓來的弟兄們都補足了。我向來凡事謹守，後來也必謹守，總不至於累著你們。","notes":[]},{"n":10,"t":"既有基督的誠實在我裏面，就無人能在亞該亞一帶地方阻擋我這自誇。","notes":[]},{"n":11,"t":"為甚麼呢？是因我不愛你們嗎？這有神知道。","notes":[]},{"n":12,"t":"我現在所做的，後來還要做，為要斷絕那些尋機會人的機會，使他們在所誇的事上也不過與我們一樣。","notes":[]},{"n":13,"t":"那等人是假使徒，行事詭詐，裝作基督使徒的模樣。","notes":[]},{"n":14,"t":"這也不足為怪，因為連撒但也裝作光明的天使。","notes":[]},{"n":15,"t":"所以他的差役，若裝作仁義的差役，也不算希奇。他們的結局必然照著他們的行為。","notes":[]},{"n":16,"t":"我再說，人不可把我看作愚妄的。縱然如此，也要把我當作愚妄人接納，叫我可以略略自誇。","notes":[],"heads":["保羅作使徒所受的患難"]},{"n":17,"t":"我說的話不是奉主命說的，乃是像愚妄人放膽自誇；","notes":[]},{"n":18,"t":"既有好些人憑著血氣自誇，我也要自誇了。","notes":[]},{"n":19,"t":"你們既是精明人，就能甘心忍耐愚妄人。","notes":[]},{"n":20,"t":"假若有人強你們作奴僕，或侵吞你們，或擄掠你們，或侮慢你們，或打你們的臉，你們都能忍耐他。","notes":[]},{"n":21,"t":"我說這話是羞辱自己，好像我們從前是軟弱的。然而，人在何事上勇敢，（我說句愚妄話，）我也勇敢。","notes":[]},{"n":22,"t":"他們是希伯來人嗎？我也是。他們是以色列人嗎？我也是。他們是亞伯拉罕的後裔嗎？我也是。","notes":[]},{"n":23,"t":"他們是基督的僕人嗎？（我說句狂話，）我更是。我比他們多受勞苦，多下監牢，受鞭打是過重的，冒死是屢次有的。","notes":[]},{"n":24,"t":"被猶太人鞭打五次，每次四十減去一下；","notes":[]},{"n":25,"t":"被棍打了三次；被石頭打了一次；遇著船壞三次，一晝一夜在深海裏。","notes":[]},{"n":26,"t":"又屢次行遠路，遭江河的危險、盜賊的危險、同族的危險、外邦人的危險、城裏的危險、曠野的危險、海中的危險、假弟兄的危險。","notes":[]},{"n":27,"t":"受勞碌、受困苦，多次不得睡，又飢又渴，多次不得食，受寒冷，赤身露體。","notes":[]},{"n":28,"t":"除了這外面的事，還有為眾教會掛心的事，天天壓在我身上。","notes":[]},{"n":29,"t":"有誰軟弱，我不軟弱呢？有誰跌倒，我不焦急呢？","notes":[]},{"n":30,"t":"我若必須自誇，就誇那關乎我軟弱的事便了。","notes":[]},{"n":31,"t":"那永遠可稱頌之主耶穌的父神知道我不說謊。","notes":[]},{"n":32,"t":"在大馬士革的亞哩達王手下的提督把守大馬士革城，要捉拿我，","notes":[]},{"n":33,"t":"我就從窗戶中，在筐子裏，從城牆上被人縋下去，脫離了他的手。","notes":[]}]},"12":{"heading":"異象和啟示","verses":[{"n":1,"t":"我自誇固然無益，但我是不得已的。如今我要說到主的顯現和啟示。","notes":[]},{"n":2,"t":"我認得一個在基督裏的人，他前十四年被提到第三層天上去；（或在身內，我不知道；或在身外，我也不知道；只有神知道。）","notes":[]},{"n":3,"t":"我認得這人；（或在身內，或在身外，我都不知道，只有神知道。）","notes":[]},{"n":4,"t":"他被提到樂園裏，聽見隱祕的言語，是人不可說的。","notes":[]},{"n":5,"t":"為這人，我要誇口；但是為我自己，除了我的軟弱以外，我並不誇口。","notes":[]},{"n":6,"t":"我就是願意誇口也不算狂，因為我必說實話；只是我禁止不說，恐怕有人把我看高了，過於他在我身上所看見、所聽見的。","notes":[]},{"n":7,"t":"又恐怕我因所得的啟示甚大，就過於自高，所以有一根刺加在我肉體上，就是撒但的差役要攻擊我，免得我過於自高。","notes":[]},{"n":8,"t":"為這事，我三次求過主，叫這刺離開我。","notes":[]},{"n":9,"t":"他對我說：「我的恩典夠你用的，因為我的能力是在人的軟弱上顯得完全。」所以，我更喜歡誇自己的軟弱，好叫基督的能力覆庇我。","notes":[]},{"n":10,"t":"我為基督的緣故，就以軟弱、凌辱、急難、逼迫、困苦為可喜樂的；因我甚麼時候軟弱，甚麼時候就剛強了。","notes":[]},{"n":11,"t":"我成了愚妄人，是被你們強逼的。我本該被你們稱許才是。我雖算不了甚麼，卻沒有一件事在那些最大的使徒以下。","notes":[],"heads":["保羅關心哥林多教會"]},{"n":12,"t":"我在你們中間，用百般的忍耐，藉著神蹟、奇事、異能顯出使徒的憑據來。","notes":[]},{"n":13,"t":"除了我不累著你們這一件事，你們還有甚麼事不及別的教會呢？這不公之處，求你們饒恕我吧。","notes":[]},{"n":14,"t":"如今，我打算第三次到你們那裏去，也必不累著你們；因我所求的是你們，不是你們的財物。兒女不該為父母積財，父母該為兒女積財。","notes":[]},{"n":15,"t":"我也甘心樂意為你們的靈魂費財費力。難道我越發愛你們，就越發少得你們的愛嗎？","notes":[]},{"n":16,"t":"罷了，我自己並沒有累著你們，你們卻有人說，我是詭詐，用心計牢籠你們。","notes":[]},{"n":17,"t":"我所差到你們那裏去的人，我藉著他們一個人佔過你們的便宜嗎？","notes":[]},{"n":18,"t":"我勸了提多到你們那裏去，又差那位兄弟與他同去。提多佔過你們的便宜嗎？我們行事，不同是一個心靈嗎？不同是一個腳蹤嗎？","notes":["或譯：聖靈"]},{"n":19,"t":"你們到如今，還想我們是向你們分訴；我們本是在基督裏當神面前說話。親愛的弟兄啊，一切的事都是為造就你們。","notes":[]},{"n":20,"t":"我怕我再來的時候，見你們不合我所想望的，你們見我也不合你們所想望的；又怕有紛爭、嫉妒、惱怒、結黨、毀謗、讒言、狂傲、混亂的事。","notes":[]},{"n":21,"t":"且怕我來的時候，我的神叫我在你們面前慚愧，又因許多人從前犯罪，行污穢、姦淫、邪蕩的事不肯悔改，我就憂愁。","notes":[]}]},"13":{"heading":"警告和問候","verses":[{"n":1,"t":"這是我第三次要到你們那裏去。「憑兩三個人的口作見證，句句都要定準。」","notes":[]},{"n":2,"t":"我從前說過，如今不在你們那裏又說，正如我第二次見你們的時候所說的一樣，就是對那犯了罪的和其餘的人說：「我若再來，必不寬容。」","notes":[]},{"n":3,"t":"你們既然尋求基督在我裏面說話的憑據，我必不寬容。因為，基督在你們身上不是軟弱的，在你們裏面是有大能的。","notes":[]},{"n":4,"t":"他因軟弱被釘在十字架上，卻因神的大能仍然活著。我們也是這樣同他軟弱，但因神向你們所顯的大能，也必與他同活。","notes":[]},{"n":5,"t":"你們總要自己省察有信心沒有，也要自己試驗。豈不知你們若不是可棄絕的，就有耶穌基督在你們心裏嗎？","notes":[]},{"n":6,"t":"我卻盼望你們曉得，我們不是可棄絕的人。","notes":[]},{"n":7,"t":"我們求神，叫你們一件惡事都不做；這不是要顯明我們是蒙悅納的，是要你們行事端正，任憑人看我們是被棄絕的吧！","notes":[]},{"n":8,"t":"我們凡事不能敵擋真理，只能扶助真理。","notes":[]},{"n":9,"t":"即便我們軟弱，你們剛強，我們也歡喜；並且我們所求的，就是你們作完全人。","notes":[]},{"n":10,"t":"所以，我不在你們那裏的時候，把這話寫給你們，好叫我見你們的時候，不用照主所給我的權柄嚴厲地待你們。這權柄原是為造就人，並不是為敗壞人。","notes":[]},{"n":11,"t":"還有末了的話：願弟兄們都喜樂。要作完全人；要受安慰；要同心合意；要彼此和睦。如此，仁愛和平的神必常與你們同在。","notes":[]},{"n":12,"t":"你們親嘴問安，彼此務要聖潔。","notes":[]},{"n":13,"t":"眾聖徒都問你們安。","notes":[]},{"n":14,"t":"願主耶穌基督的恩惠、神的慈愛、聖靈的感動常與你們眾人同在！","notes":[]}]}},"GAL":{"1":{"heading":"問候","verses":[{"n":1,"t":"作使徒的保羅（不是由於人，也不是藉著人，乃是藉著耶穌基督，與叫他從死裏復活的父神）","notes":[]},{"n":2,"t":"和一切與我同在的眾弟兄，寫信給加拉太的各教會。","notes":[]},{"n":3,"t":"願恩惠、平安從父神與我們的主耶穌基督歸與你們！","notes":[]},{"n":4,"t":"基督照我們父神的旨意，為我們的罪捨己，要救我們脫離這罪惡的世代。","notes":[]},{"n":5,"t":"但願榮耀歸於神，直到永永遠遠。阿們！","notes":[]},{"n":6,"t":"我希奇你們這麼快離開那藉著基督之恩召你們的，去從別的福音。","notes":[],"heads":["沒有別的福音"]},{"n":7,"t":"那並不是福音，不過有些人攪擾你們，要把基督的福音更改了。","notes":[]},{"n":8,"t":"但無論是我們，是天上來的使者，若傳福音給你們，與我們所傳給你們的不同，他就應當被咒詛。","notes":[]},{"n":9,"t":"我們已經說了，現在又說，若有人傳福音給你們，與你們所領受的不同，他就應當被咒詛。","notes":[]},{"n":10,"t":"我現在是要得人的心呢？還是要得神的心呢？我豈是討人的喜歡嗎？若仍舊討人的喜歡，我就不是基督的僕人了。","notes":[]},{"n":11,"t":"弟兄們，我告訴你們，我素來所傳的福音不是出於人的意思。","notes":[],"heads":["保羅怎樣成為使徒"]},{"n":12,"t":"因為我不是從人領受的，也不是人教導我的，乃是從耶穌基督啟示來的。","notes":[]},{"n":13,"t":"你們聽見我從前在猶太教中所行的事，怎樣極力逼迫殘害神的教會。","notes":[]},{"n":14,"t":"我又在猶太教中，比我本國許多同歲的人更有長進，為我祖宗的遺傳更加熱心。","notes":[]},{"n":15,"t":"然而，那把我從母腹裏分別出來、又施恩召我的神，","notes":[]},{"n":16,"t":"既然樂意將他兒子啟示在我心裏，叫我把他傳在外邦人中，我就沒有與屬血氣的人商量，","notes":[]},{"n":17,"t":"也沒有上耶路撒冷去見那些比我先作使徒的，惟獨往阿拉伯去，後又回到大馬士革。","notes":[]},{"n":18,"t":"過了三年，才上耶路撒冷去見磯法，和他同住了十五天。","notes":[]},{"n":19,"t":"至於別的使徒，除了主的兄弟雅各，我都沒有看見。","notes":[]},{"n":20,"t":"我寫給你們的不是謊話，這是我在神面前說的。","notes":[]},{"n":21,"t":"以後我到了敘利亞和基利家境內。","notes":[]},{"n":22,"t":"那時，猶太信基督的各教會都沒有見過我的面。","notes":[]},{"n":23,"t":"不過聽說那從前逼迫我們的，現在傳揚他原先所殘害的真道。","notes":[]},{"n":24,"t":"他們就為我的緣故，歸榮耀給神。","notes":[]}]},"2":{"heading":"保羅被其他的使徒接納","verses":[{"n":1,"t":"過了十四年，我同巴拿巴又上耶路撒冷去，並帶著提多同去。","notes":[]},{"n":2,"t":"我是奉啟示上去的，把我在外邦人中所傳的福音對弟兄們陳說；卻是背地裏對那有名望之人說的，惟恐我現在，或是從前，徒然奔跑。","notes":[]},{"n":3,"t":"但與我同去的提多，雖是希臘人，也沒有勉強他受割禮；","notes":[]},{"n":4,"t":"因為有偷著引進來的假弟兄，私下窺探我們在基督耶穌裏的自由，要叫我們作奴僕。","notes":[]},{"n":5,"t":"我們就是一刻的工夫也沒有容讓順服他們，為要叫福音的真理仍存在你們中間。","notes":[]},{"n":6,"t":"至於那些有名望的，不論他是何等人，都與我無干。神不以外貌取人。那些有名望的，並沒有加增我甚麼，","notes":[]},{"n":7,"t":"反倒看見了主託我傳福音給那未受割禮的人，正如託彼得傳福音給那受割禮的人。（","notes":[]},{"n":8,"t":"那感動彼得、叫他為受割禮之人作使徒的，也感動我，叫我為外邦人作使徒；）","notes":[]},{"n":9,"t":"又知道所賜給我的恩典，那稱為教會柱石的雅各、磯法、約翰，就向我和巴拿巴用右手行相交之禮，叫我們往外邦人那裏去，他們往受割禮的人那裏去。","notes":[]},{"n":10,"t":"只是願意我們記念窮人；這也是我本來熱心去行的。","notes":[]},{"n":11,"t":"後來，磯法到了安提阿；因他有可責之處，我就當面抵擋他。","notes":[],"heads":["保羅在安提阿責備彼得"]},{"n":12,"t":"從雅各那裏來的人未到以先，他和外邦人一同吃飯，及至他們來到，他因怕奉割禮的人，就退去與外邦人隔開了。","notes":[]},{"n":13,"t":"其餘的猶太人也都隨著他裝假，甚至連巴拿巴也隨夥裝假。","notes":[]},{"n":14,"t":"但我一看見他們行的不正，與福音的真理不合，就在眾人面前對磯法說：「你既是猶太人，若隨外邦人行事，不隨猶太人行事，怎麼還勉強外邦人隨猶太人呢？」","notes":[]},{"n":15,"t":"我們這生來的猶太人，不是外邦的罪人；","notes":[],"heads":["猶太人和外邦人都因信得救"]},{"n":16,"t":"既知道人稱義不是因行律法，乃是因信耶穌基督，連我們也信了基督耶穌，使我們因信基督稱義，不因行律法稱義；因為凡有血氣的，沒有一人因行律法稱義。","notes":[]},{"n":17,"t":"我們若求在基督裏稱義，卻仍舊是罪人，難道基督是叫人犯罪的嗎？斷乎不是！","notes":[]},{"n":18,"t":"我素來所拆毀的，若重新建造，這就證明自己是犯罪的人。","notes":[]},{"n":19,"t":"我因律法，就向律法死了，叫我可以向神活著。","notes":[]},{"n":20,"t":"我已經與基督同釘十字架，現在活著的不再是我，乃是基督在我裏面活著；並且我如今在肉身活著，是因信神的兒子而活；他是愛我，為我捨己。","notes":[]},{"n":21,"t":"我不廢掉神的恩；義若是藉著律法得的，基督就是徒然死了。","notes":[]}]},"3":{"heading":"律法和信心","verses":[{"n":1,"t":"無知的加拉太人哪，耶穌基督釘十字架，已經活畫在你們眼前，誰又迷惑了你們呢？","notes":[]},{"n":2,"t":"我只要問你們這一件：你們受了聖靈，是因行律法呢？是因聽信福音呢？","notes":[]},{"n":3,"t":"你們既靠聖靈入門，如今還靠肉身成全嗎？你們是這樣的無知嗎？","notes":[]},{"n":4,"t":"你們受苦如此之多，都是徒然的嗎？難道果真是徒然的嗎？","notes":[]},{"n":5,"t":"那賜給你們聖靈，又在你們中間行異能的，是因你們行律法呢？是因你們聽信福音呢？","notes":[]},{"n":6,"t":"正如「亞伯拉罕信神，這就算為他的義」。","notes":[]},{"n":7,"t":"所以，你們要知道：那以信為本的人，就是亞伯拉罕的子孫。","notes":[]},{"n":8,"t":"並且聖經既然預先看明，神要叫外邦人因信稱義，就早已傳福音給亞伯拉罕，說：「萬國都必因你得福。」","notes":[]},{"n":9,"t":"可見那以信為本的人和有信心的亞伯拉罕一同得福。","notes":[]},{"n":10,"t":"凡以行律法為本的，都是被咒詛的；因為經上記著：「凡不常照律法書上所記一切之事去行的，就被咒詛。」","notes":[]},{"n":11,"t":"沒有一個人靠著律法在神面前稱義，這是明顯的；因為經上說：「義人必因信得生。」","notes":[]},{"n":12,"t":"律法原不本乎信，只說：「行這些事的，就必因此活著。」","notes":[]},{"n":13,"t":"基督既為我們受了咒詛，就贖出我們脫離律法的咒詛；因為經上記著：「凡掛在木頭上都是被咒詛的。」","notes":["原文是成"]},{"n":14,"t":"這便叫亞伯拉罕的福，因基督耶穌可以臨到外邦人，使我們因信得著所應許的聖靈。","notes":[]},{"n":15,"t":"弟兄們，我且照著人的常話說：雖然是人的文約，若已經立定了，就沒有能廢棄或加增的。","notes":[],"heads":["律法和應許"]},{"n":16,"t":"所應許的原是向亞伯拉罕和他子孫說的。神並不是說「眾子孫」，指著許多人，乃是說「你那一個子孫」，指著一個人，就是基督。","notes":[]},{"n":17,"t":"我是這麼說，神預先所立的約，不能被那四百三十年以後的律法廢掉，叫應許歸於虛空。","notes":[]},{"n":18,"t":"因為承受產業，若本乎律法，就不本乎應許；但神是憑著應許把產業賜給亞伯拉罕。","notes":[]},{"n":19,"t":"這樣說來，律法是為甚麼有的呢？原是為過犯添上的，等候那蒙應許的子孫來到，並且是藉天使經中保之手設立的。","notes":[]},{"n":20,"t":"但中保本不是為一面作的；神卻是一位。","notes":[]},{"n":21,"t":"這樣，律法是與神的應許反對嗎？斷乎不是！若曾傳一個能叫人得生的律法，義就誠然本乎律法了。","notes":[],"heads":["奴僕和兒子"]},{"n":22,"t":"但聖經把眾人都圈在罪裏，使所應許的福因信耶穌基督，歸給那信的人。","notes":[]},{"n":23,"t":"但這因信得救的理還未來以先，我們被看守在律法之下，直圈到那將來的真道顯明出來。","notes":[]},{"n":24,"t":"這樣，律法是我們訓蒙的師傅，引我們到基督那裏，使我們因信稱義。","notes":[]},{"n":25,"t":"但這因信得救的理既然來到，我們從此就不在師傅的手下了。","notes":[]},{"n":26,"t":"所以，你們因信基督耶穌都是神的兒子。","notes":[]},{"n":27,"t":"你們受洗歸入基督的都是披戴基督了。","notes":[]},{"n":28,"t":"並不分猶太人、希臘人，自主的、為奴的，或男或女，因為你們在基督耶穌裏都成為一了。","notes":[]},{"n":29,"t":"你們既屬乎基督，就是亞伯拉罕的後裔，是照著應許承受產業的了。","notes":[]}]},"4":{"heading":"保羅關懷加拉太人","verses":[{"n":1,"t":"我說那承受產業的，雖然是全業的主人，但為孩童的時候卻與奴僕毫無分別，","notes":[]},{"n":2,"t":"乃在師傅和管家的手下，直等他父親預定的時候來到。","notes":[]},{"n":3,"t":"我們為孩童的時候，受管於世俗小學之下，也是如此。","notes":[]},{"n":4,"t":"及至時候滿足，神就差遣他的兒子，為女子所生，且生在律法以下，","notes":[]},{"n":5,"t":"要把律法以下的人贖出來，叫我們得著兒子的名分。","notes":[]},{"n":6,"t":"你們既為兒子，神就差他兒子的靈進入你們的心，呼叫：「阿爸！父！」","notes":["原文是我們"]},{"n":7,"t":"可見，從此以後，你不是奴僕，乃是兒子了；既是兒子，就靠著神為後嗣。","notes":[]},{"n":8,"t":"但從前你們不認識神的時候，是給那些本來不是神的作奴僕；","notes":[]},{"n":9,"t":"現在你們既然認識神，更可說是被神所認識的，怎麼還要歸回那懦弱無用的小學，情願再給他作奴僕呢？","notes":[]},{"n":10,"t":"你們謹守日子、月份、節期、年份，","notes":[]},{"n":11,"t":"我為你們害怕，惟恐我在你們身上是枉費了工夫。","notes":[]},{"n":12,"t":"弟兄們，我勸你們要像我一樣，因為我也像你們一樣。你們一點沒有虧負我。","notes":[]},{"n":13,"t":"你們知道我頭一次傳福音給你們，是因為身體有疾病。","notes":[]},{"n":14,"t":"你們為我身體的緣故受試煉，沒有輕看我，也沒有厭棄我，反倒接待我，如同神的使者，如同基督耶穌。","notes":[]},{"n":15,"t":"你們當日所誇的福氣在哪裏呢？那時你們若能行，就是把自己的眼睛剜出來給我，也都情願。這是我可以給你們作見證的。","notes":[]},{"n":16,"t":"如今我將真理告訴你們，就成了你們的仇敵嗎？","notes":[]},{"n":17,"t":"那些人熱心待你們，卻不是好意，是要離間你們，叫你們熱心待他們。","notes":["原文是把你們關在外面"]},{"n":18,"t":"在善事上，常用熱心待人原是好的，卻不單我與你們同在的時候才這樣。","notes":[]},{"n":19,"t":"我小子啊，我為你們再受生產之苦，直等到基督成形在你們心裏。","notes":[]},{"n":20,"t":"我巴不得現今在你們那裏，改換口氣，因我為你們心裏作難。","notes":[]},{"n":21,"t":"你們這願意在律法以下的人，請告訴我，你們豈沒有聽見律法嗎？","notes":[],"heads":["夏甲和撒拉的例子"]},{"n":22,"t":"因為律法上記著，亞伯拉罕有兩個兒子，一個是使女生的，一個是自主之婦人生的。","notes":[]},{"n":23,"t":"然而，那使女所生的是按著血氣生的；那自主之婦人所生的是憑著應許生的。","notes":[]},{"n":24,"t":"這都是比方：那兩個婦人就是兩約。一約是出於西奈山，生子為奴，乃是夏甲。","notes":[]},{"n":25,"t":"這夏甲二字是指著阿拉伯的西奈山，與現在的耶路撒冷同類，因耶路撒冷和她的兒女都是為奴的。","notes":[]},{"n":26,"t":"但那在上的耶路撒冷是自主的，她是我們的母。","notes":[]},{"n":27,"t":"因為經上記著：不懷孕、不生養的，你要歡樂；未曾經過產難的，你要高聲歡呼；因為沒有丈夫的，比有丈夫的兒女更多。","notes":[]},{"n":28,"t":"弟兄們，我們是憑著應許作兒女，如同以撒一樣。","notes":[]},{"n":29,"t":"當時，那按著血氣生的逼迫了那按著聖靈生的，現在也是這樣。","notes":[]},{"n":30,"t":"然而經上是怎麼說的呢？是說：「把使女和她兒子趕出去！因為使女的兒子不可與自主婦人的兒子一同承受產業。」","notes":[]},{"n":31,"t":"弟兄們，這樣看來，我們不是使女的兒女，乃是自主婦人的兒女了。","notes":[]}]},"5":{"heading":"基督徒的自由","verses":[{"n":1,"t":"基督釋放了我們，叫我們得以自由。所以要站立得穩，不要再被奴僕的軛挾制。","notes":[]},{"n":2,"t":"我－保羅告訴你們，若受割禮，基督就與你們無益了。","notes":[]},{"n":3,"t":"我再指著凡受割禮的人確實地說，他是欠著行全律法的債。","notes":[]},{"n":4,"t":"你們這要靠律法稱義的，是與基督隔絕，從恩典中墜落了。","notes":[]},{"n":5,"t":"我們靠著聖靈，憑著信心，等候所盼望的義。","notes":[]},{"n":6,"t":"原來在基督耶穌裏，受割禮不受割禮全無功效，惟獨使人生發仁愛的信心才有功效。","notes":[]},{"n":7,"t":"你們向來跑得好，有誰攔阻你們，叫你們不順從真理呢？","notes":[]},{"n":8,"t":"這樣的勸導不是出於那召你們的。","notes":[]},{"n":9,"t":"一點麵酵能使全團都發起來。","notes":[]},{"n":10,"t":"我在主裏很信你們必不懷別樣的心；但攪擾你們的，無論是誰，必擔當他的罪名。","notes":[]},{"n":11,"t":"弟兄們，我若仍舊傳割禮，為甚麼還受逼迫呢？若是這樣，那十字架討厭的地方就沒有了。","notes":[]},{"n":12,"t":"恨不得那攪亂你們的人把自己割絕了。","notes":[]},{"n":13,"t":"弟兄們，你們蒙召是要得自由，只是不可將你們的自由當作放縱情慾的機會，總要用愛心互相服事。","notes":[]},{"n":14,"t":"因為全律法都包在「愛人如己」這一句話之內了。","notes":[]},{"n":15,"t":"你們要謹慎，若相咬相吞，只怕要彼此消滅了。","notes":[]},{"n":16,"t":"我說，你們當順著聖靈而行，就不放縱肉體的情慾了。","notes":[],"heads":["聖靈的果子和肉體的惡行"]},{"n":17,"t":"因為情慾和聖靈相爭，聖靈和情慾相爭，這兩個是彼此相敵，使你們不能做所願意做的。","notes":[]},{"n":18,"t":"但你們若被聖靈引導，就不在律法以下。","notes":[]},{"n":19,"t":"情慾的事都是顯而易見的，就如姦淫、污穢、邪蕩、","notes":[]},{"n":20,"t":"拜偶像、邪術、仇恨、爭競、忌恨、惱怒、結黨、紛爭、異端、","notes":[]},{"n":21,"t":"嫉妒、醉酒、荒宴等類。我從前告訴你們，現在又告訴你們，行這樣事的人必不能承受神的國。","notes":["有古卷加：凶殺二字"]},{"n":22,"t":"聖靈所結的果子，就是仁愛、喜樂、和平、忍耐、恩慈、良善、信實、","notes":[]},{"n":23,"t":"溫柔、節制。這樣的事沒有律法禁止。","notes":[]},{"n":24,"t":"凡屬基督耶穌的人，是已經把肉體連肉體的邪情私慾同釘在十字架上了。","notes":[]},{"n":25,"t":"我們若是靠聖靈得生，就當靠聖靈行事。","notes":[]},{"n":26,"t":"不要貪圖虛名，彼此惹氣，互相嫉妒。","notes":[]}]},"6":{"heading":"各人的重擔要互相擔當","verses":[{"n":1,"t":"弟兄們，若有人偶然被過犯所勝，你們屬靈的人就當用溫柔的心把他挽回過來；又當自己小心，恐怕也被引誘。","notes":[]},{"n":2,"t":"你們各人的重擔要互相擔當，如此，就完全了基督的律法。","notes":[]},{"n":3,"t":"人若無有，自己還以為有，就是自欺了。","notes":[]},{"n":4,"t":"各人應當察驗自己的行為；這樣，他所誇的就專在自己，不在別人了，","notes":[]},{"n":5,"t":"因為各人必擔當自己的擔子。","notes":[]},{"n":6,"t":"在道理上受教的，當把一切需用的供給施教的人。","notes":[]},{"n":7,"t":"不要自欺，神是輕慢不得的。人種的是甚麼，收的也是甚麼。","notes":[]},{"n":8,"t":"順著情慾撒種的，必從情慾收敗壞；順著聖靈撒種的，必從聖靈收永生。","notes":[]},{"n":9,"t":"我們行善，不可喪志；若不灰心，到了時候就要收成。","notes":[]},{"n":10,"t":"所以，有了機會就當向眾人行善，向信徒一家的人更當這樣。","notes":[]},{"n":11,"t":"請看我親手寫給你們的字是何等的大呢！","notes":[],"heads":["警告和祝福"]},{"n":12,"t":"凡希圖外貌體面的人都勉強你們受割禮，無非是怕自己為基督的十字架受逼迫。","notes":[]},{"n":13,"t":"他們那些受割禮的，連自己也不守律法；他們願意你們受割禮，不過要藉著你們的肉體誇口。","notes":[]},{"n":14,"t":"但我斷不以別的誇口，只誇我們主耶穌基督的十字架；因這十字架，就我而論，世界已經釘在十字架上；就世界而論，我已經釘在十字架上。","notes":[]},{"n":15,"t":"受割禮不受割禮都無關緊要，要緊的就是作新造的人。","notes":[]},{"n":16,"t":"凡照此理而行的，願平安、憐憫加給他們，和神的以色列民。","notes":[]},{"n":17,"t":"從今以後，人都不要攪擾我，因為我身上帶著耶穌的印記。","notes":[]},{"n":18,"t":"弟兄們，願我主耶穌基督的恩常在你們心裏。阿們！","notes":[]}]}},"EPH":{"1":{"heading":"問候","verses":[{"n":1,"t":"奉神旨意，作基督耶穌使徒的保羅，寫信給在以弗所的聖徒，就是在基督耶穌裏有忠心的人。","notes":[]},{"n":2,"t":"願恩惠、平安從神我們的父和主耶穌基督歸與你們！","notes":[]},{"n":3,"t":"願頌讚歸與我們主耶穌基督的父神！他在基督裏曾賜給我們天上各樣屬靈的福氣：","notes":[],"heads":["基督裏的屬靈福氣"]},{"n":4,"t":"就如神從創立世界以前，在基督裏揀選了我們，使我們在他面前成為聖潔，無有瑕疵；","notes":[]},{"n":5,"t":"又因愛我們，就按著自己的意旨所喜悅的，預定我們藉著耶穌基督得兒子的名分，","notes":[]},{"n":6,"t":"使他榮耀的恩典得著稱讚；這恩典是他在愛子裏所賜給我們的。","notes":[]},{"n":7,"t":"我們藉這愛子的血得蒙救贖，過犯得以赦免，乃是照他豐富的恩典。","notes":[]},{"n":8,"t":"這恩典是神用諸般智慧聰明，充充足足賞給我們的；","notes":[]},{"n":9,"t":"都是照他自己所預定的美意，叫我們知道他旨意的奧祕，","notes":[]},{"n":10,"t":"要照所安排的，在日期滿足的時候，使天上、地上、一切所有的都在基督裏面同歸於一。","notes":[]},{"n":11,"t":"我們也在他裏面得了基業；這原是那位隨己意行、做萬事的，照著他旨意所預定的，","notes":["得：或譯成"]},{"n":12,"t":"叫他的榮耀從我們這首先在基督裏有盼望的人可以得著稱讚。","notes":[]},{"n":13,"t":"你們既聽見真理的道，就是那叫你們得救的福音，也信了基督，既然信他，就受了所應許的聖靈為印記。","notes":[]},{"n":14,"t":"這聖靈是我們得基業的憑據，直等到神之民被贖，使他的榮耀得著稱讚。","notes":["原文是質","民：原文是產業"]},{"n":15,"t":"因此，我既聽見你們信從主耶穌，親愛眾聖徒，","notes":[],"heads":["保羅的禱告"]},{"n":16,"t":"就為你們不住地感謝神。禱告的時候，常提到你們，","notes":[]},{"n":17,"t":"求我們主耶穌基督的神，榮耀的父，將那賜人智慧和啟示的靈賞給你們，使你們真知道他，","notes":[]},{"n":18,"t":"並且照明你們心中的眼睛，使你們知道他的恩召有何等指望，他在聖徒中得的基業有何等豐盛的榮耀；","notes":[]},{"n":19,"t":"並知道他向我們這信的人所顯的能力是何等浩大，","notes":[]},{"n":20,"t":"就是照他在基督身上所運行的大能大力，使他從死裏復活，叫他在天上坐在自己的右邊，","notes":[]},{"n":21,"t":"遠超過一切執政的、掌權的、有能的、主治的，和一切有名的；不但是今世的，連來世的也都超過了。","notes":[]},{"n":22,"t":"又將萬有服在他的腳下，使他為教會作萬有之首。","notes":[]},{"n":23,"t":"教會是他的身體，是那充滿萬有者所充滿的。","notes":[]}]},"2":{"heading":"出死入生","verses":[{"n":1,"t":"你們死在過犯罪惡之中，他叫你們活過來。","notes":[]},{"n":2,"t":"那時，你們在其中行事為人，隨從今世的風俗，順服空中掌權者的首領，就是現今在悖逆之子心中運行的邪靈。","notes":[]},{"n":3,"t":"我們從前也都在他們中間，放縱肉體的私慾，隨著肉體和心中所喜好的去行，本為可怒之子，和別人一樣。","notes":[]},{"n":4,"t":"然而，神既有豐富的憐憫，因他愛我們的大愛，","notes":[]},{"n":5,"t":"當我們死在過犯中的時候，便叫我們與基督一同活過來。你們得救是本乎恩。","notes":[]},{"n":6,"t":"他又叫我們與基督耶穌一同復活，一同坐在天上，","notes":[]},{"n":7,"t":"要將他極豐富的恩典，就是他在基督耶穌裏向我們所施的恩慈，顯明給後來的世代看。","notes":[]},{"n":8,"t":"你們得救是本乎恩，也因著信；這並不是出於自己，乃是神所賜的；","notes":[]},{"n":9,"t":"也不是出於行為，免得有人自誇。","notes":[]},{"n":10,"t":"我們原是他的工作，在基督耶穌裏造成的，為要叫我們行善，就是神所預備叫我們行的。","notes":[]},{"n":11,"t":"所以你們應當記念：你們從前按肉體是外邦人，是稱為沒受割禮的；這名原是那些憑人手在肉身上稱為受割禮之人所起的。","notes":[],"heads":["在基督裏合一"]},{"n":12,"t":"那時，你們與基督無關，在以色列國民以外，在所應許的諸約上是局外人，並且活在世上沒有指望，沒有神。","notes":[]},{"n":13,"t":"你們從前遠離神的人，如今卻在基督耶穌裏，靠著他的血，已經得親近了。","notes":[]},{"n":14,"t":"因他使我們和睦，將兩下合而為一，拆毀了中間隔斷的牆；","notes":["原文是因他是我們的和睦"]},{"n":15,"t":"而且以自己的身體廢掉冤仇，就是那記在律法上的規條，為要將兩下藉著自己造成一個新人，如此便成就了和睦。","notes":[]},{"n":16,"t":"既在十字架上滅了冤仇，便藉這十字架使兩下歸為一體，與神和好了，","notes":[]},{"n":17,"t":"並且來傳和平的福音給你們遠處的人，也給那近處的人。","notes":[]},{"n":18,"t":"因為我們兩下藉著他被一個聖靈所感，得以進到父面前。","notes":[]},{"n":19,"t":"這樣，你們不再作外人和客旅，是與聖徒同國，是神家裏的人了；","notes":[]},{"n":20,"t":"並且被建造在使徒和先知的根基上，有基督耶穌自己為房角石，","notes":[]},{"n":21,"t":"各房靠他聯絡得合式，漸漸成為主的聖殿。","notes":["或譯：全"]},{"n":22,"t":"你們也靠他同被建造，成為神藉著聖靈居住的所在。","notes":[]}]},"3":{"heading":"保羅奉差向外邦人傳福音","verses":[{"n":1,"t":"因此，我－保羅為你們外邦人作了基督耶穌被囚的，替你們祈禱。","notes":["此句是照對十四節所加"]},{"n":2,"t":"諒必你們曾聽見神賜恩給我，將關切你們的職分託付我，","notes":[]},{"n":3,"t":"用啟示使我知道福音的奧祕，正如我以前略略寫過的。","notes":[]},{"n":4,"t":"你們念了，就能曉得我深知基督的奧祕。","notes":[]},{"n":5,"t":"這奧祕在以前的世代沒有叫人知道，像如今藉著聖靈啟示他的聖使徒和先知一樣。","notes":[]},{"n":6,"t":"這奧祕就是外邦人在基督耶穌裏，藉著福音，得以同為後嗣，同為一體，同蒙應許。","notes":[]},{"n":7,"t":"我作了這福音的執事，是照神的恩賜，這恩賜是照他運行的大能賜給我的。","notes":[]},{"n":8,"t":"我本來比眾聖徒中最小的還小，然而他還賜我這恩典，叫我把基督那測不透的豐富傳給外邦人，","notes":[]},{"n":9,"t":"又使眾人都明白，這歷代以來隱藏在創造萬物之神裏的奧祕是如何安排的，","notes":[]},{"n":10,"t":"為要藉著教會使天上執政的、掌權的，現在得知神百般的智慧。","notes":[]},{"n":11,"t":"這是照神從萬世以前，在我們主基督耶穌裏所定的旨意。","notes":[]},{"n":12,"t":"我們因信耶穌，就在他裏面放膽無懼，篤信不疑地來到神面前。","notes":[]},{"n":13,"t":"所以，我求你們不要因我為你們所受的患難喪膽，這原是你們的榮耀。","notes":[]},{"n":14,"t":"因此，我在父面前屈膝，（","notes":[],"heads":["明白基督的愛"]},{"n":15,"t":"天上地上的各家，都是從他得名。）","notes":["或譯：全"]},{"n":16,"t":"求他按著他豐盛的榮耀，藉著他的靈，叫你們心裏的力量剛強起來，","notes":[]},{"n":17,"t":"使基督因你們的信，住在你們心裏，叫你們的愛心有根有基，","notes":[]},{"n":18,"t":"能以和眾聖徒一同明白基督的愛是何等長闊高深，","notes":[]},{"n":19,"t":"並知道這愛是過於人所能測度的，便叫神一切所充滿的，充滿了你們。","notes":[]},{"n":20,"t":"神能照著運行在我們心裏的大力充充足足地成就一切，超過我們所求所想的。","notes":[]},{"n":21,"t":"但願他在教會中，並在基督耶穌裏，得著榮耀，直到世世代代，永永遠遠。阿們！","notes":[]}]},"4":{"heading":"身體的合一","verses":[{"n":1,"t":"我為主被囚的勸你們：既然蒙召，行事為人就當與蒙召的恩相稱。","notes":[]},{"n":2,"t":"凡事謙虛、溫柔、忍耐，用愛心互相寬容，","notes":[]},{"n":3,"t":"用和平彼此聯絡，竭力保守聖靈所賜合而為一的心。","notes":[]},{"n":4,"t":"身體只有一個，聖靈只有一個，正如你們蒙召同有一個指望。","notes":[]},{"n":5,"t":"一主，一信，一洗，","notes":[]},{"n":6,"t":"一神，就是眾人的父，超乎眾人之上，貫乎眾人之中，也住在眾人之內。","notes":[]},{"n":7,"t":"我們各人蒙恩，都是照基督所量給各人的恩賜。","notes":[]},{"n":8,"t":"所以經上說：他升上高天的時候，擄掠了仇敵，將各樣的恩賜賞給人。（","notes":[]},{"n":9,"t":"既說升上，豈不是先降在地下嗎？","notes":[]},{"n":10,"t":"那降下的，就是遠升諸天之上要充滿萬有的。）","notes":[]},{"n":11,"t":"他所賜的，有使徒，有先知，有傳福音的，有牧師和教師，","notes":[]},{"n":12,"t":"為要成全聖徒，各盡其職，建立基督的身體，","notes":[]},{"n":13,"t":"直等到我們眾人在真道上同歸於一，認識神的兒子，得以長大成人，滿有基督長成的身量，","notes":[]},{"n":14,"t":"使我們不再作小孩子，中了人的詭計和欺騙的法術，被一切異教之風搖動，飄來飄去，就隨從各樣的異端；","notes":[]},{"n":15,"t":"惟用愛心說誠實話，凡事長進，連於元首基督，","notes":[]},{"n":16,"t":"全身都靠他聯絡得合式，百節各按各職，照著各體的功用彼此相助，便叫身體漸漸增長，在愛中建立自己。","notes":[]},{"n":17,"t":"所以我說，且在主裏確實地說，你們行事不要再像外邦人存虛妄的心行事。","notes":[],"heads":["舊人和新人"]},{"n":18,"t":"他們心地昏昧，與神所賜的生命隔絕了，都因自己無知，心裏剛硬；","notes":[]},{"n":19,"t":"良心既然喪盡，就放縱私慾，貪行種種的污穢。","notes":[]},{"n":20,"t":"你們學了基督，卻不是這樣。","notes":[]},{"n":21,"t":"如果你們聽過他的道，領了他的教，學了他的真理，","notes":[]},{"n":22,"t":"就要脫去你們從前行為上的舊人，這舊人是因私慾的迷惑漸漸變壞的；","notes":[]},{"n":23,"t":"又要將你們的心志改換一新，","notes":[]},{"n":24,"t":"並且穿上新人；這新人是照著神的形像造的，有真理的仁義和聖潔。","notes":[]},{"n":25,"t":"所以，你們要棄絕謊言，各人與鄰舍說實話，因為我們是互相為肢體。","notes":[],"heads":["新生活的守則"]},{"n":26,"t":"生氣卻不要犯罪；不可含怒到日落，","notes":[]},{"n":27,"t":"也不可給魔鬼留地步。","notes":[]},{"n":28,"t":"從前偷竊的，不要再偷；總要勞力，親手做正經事，就可有餘分給那缺少的人。","notes":[]},{"n":29,"t":"污穢的言語一句不可出口，只要隨事說造就人的好話，叫聽見的人得益處。","notes":[]},{"n":30,"t":"不要叫神的聖靈擔憂；你們原是受了他的印記，等候得贖的日子來到。","notes":[]},{"n":31,"t":"一切苦毒、惱恨、忿怒、嚷鬧、毀謗，並一切的惡毒，都當從你們中間除掉；","notes":["或譯：陰毒"]},{"n":32,"t":"並要以恩慈相待，存憐憫的心，彼此饒恕，正如神在基督裏饒恕了你們一樣。","notes":[]}]},"5":{"heading":"行事為人當像光明的子女","verses":[{"n":1,"t":"所以，你們該效法神，好像蒙慈愛的兒女一樣。","notes":[]},{"n":2,"t":"也要憑愛心行事，正如基督愛我們，為我們捨了自己，當作馨香的供物和祭物，獻與神。","notes":[]},{"n":3,"t":"至於淫亂並一切污穢，或是貪婪，在你們中間連提都不可，方合聖徒的體統。","notes":[]},{"n":4,"t":"淫詞、妄語，和戲笑的話都不相宜；總要說感謝的話。","notes":[]},{"n":5,"t":"因為你們確實地知道，無論是淫亂的，是污穢的，是有貪心的，在基督和神的國裏都是無分的。有貪心的，就與拜偶像的一樣。","notes":[]},{"n":6,"t":"不要被人虛浮的話欺哄；因這些事，神的忿怒必臨到那悖逆之子。","notes":[]},{"n":7,"t":"所以，你們不要與他們同夥。","notes":[]},{"n":8,"t":"從前你們是暗昧的，但如今在主裏面是光明的，行事為人就當像光明的子女。","notes":[]},{"n":9,"t":"光明所結的果子就是一切良善、公義、誠實。","notes":[]},{"n":10,"t":"總要察驗何為主所喜悅的事。","notes":[]},{"n":11,"t":"那暗昧無益的事，不要與人同行，倒要責備行這事的人；","notes":[]},{"n":12,"t":"因為他們暗中所行的，就是提起來也是可恥的。","notes":[]},{"n":13,"t":"凡事受了責備，就被光顯明出來，因為一切能顯明的就是光。","notes":[]},{"n":14,"t":"所以主說：你這睡著的人當醒過來，從死裏復活！基督就要光照你了。","notes":[]},{"n":15,"t":"你們要謹慎行事，不要像愚昧人，當像智慧人。","notes":[]},{"n":16,"t":"要愛惜光陰，因為現今的世代邪惡。","notes":[]},{"n":17,"t":"不要作糊塗人，要明白主的旨意如何。","notes":[]},{"n":18,"t":"不要醉酒，酒能使人放蕩；乃要被聖靈充滿。","notes":[]},{"n":19,"t":"當用詩章、頌詞、靈歌彼此對說，口唱心和地讚美主。","notes":[]},{"n":20,"t":"凡事要奉我們主耶穌基督的名常常感謝父神。","notes":[]},{"n":21,"t":"又當存敬畏基督的心，彼此順服。","notes":[]},{"n":22,"t":"你們作妻子的，當順服自己的丈夫，如同順服主。","notes":[],"heads":["丈夫和妻子"]},{"n":23,"t":"因為丈夫是妻子的頭，如同基督是教會的頭；他又是教會全體的救主。","notes":[]},{"n":24,"t":"教會怎樣順服基督，妻子也要怎樣凡事順服丈夫。","notes":[]},{"n":25,"t":"你們作丈夫的，要愛你們的妻子，正如基督愛教會，為教會捨己。","notes":[]},{"n":26,"t":"要用水藉著道把教會洗淨，成為聖潔，","notes":[]},{"n":27,"t":"可以獻給自己，作個榮耀的教會，毫無玷污、皺紋等類的病，乃是聖潔沒有瑕疵的。","notes":[]},{"n":28,"t":"丈夫也當照樣愛妻子，如同愛自己的身子；愛妻子便是愛自己了。","notes":[]},{"n":29,"t":"從來沒有人恨惡自己的身子，總是保養顧惜，正像基督待教會一樣，","notes":[]},{"n":30,"t":"因我們是他身上的肢體。","notes":["有古卷加：就是他的骨他的肉"]},{"n":31,"t":"為這個緣故，人要離開父母，與妻子連合，二人成為一體。","notes":[]},{"n":32,"t":"這是極大的奧祕，但我是指著基督和教會說的。","notes":[]},{"n":33,"t":"然而，你們各人都當愛妻子，如同愛自己一樣。妻子也當敬重她的丈夫。","notes":[]}]},"6":{"heading":"兒女和父母","verses":[{"n":1,"t":"你們作兒女的，要在主裏聽從父母，這是理所當然的。","notes":[]},{"n":2,"t":"「要孝敬父母，使你得福，在世長壽。」這是第一條帶應許的誡命。","notes":[],"end":3},{"n":4,"t":"你們作父親的，不要惹兒女的氣，只要照著主的教訓和警戒養育他們。","notes":[]},{"n":5,"t":"你們作僕人的，要懼怕戰兢，用誠實的心聽從你們肉身的主人，好像聽從基督一般。","notes":[],"heads":["僕人和主人"]},{"n":6,"t":"不要只在眼前事奉，像是討人喜歡的，要像基督的僕人，從心裏遵行神的旨意。","notes":[]},{"n":7,"t":"甘心事奉，好像服事主，不像服事人。","notes":[]},{"n":8,"t":"因為曉得各人所行的善事，不論是為奴的，是自主的，都必按所行的得主的賞賜。","notes":[]},{"n":9,"t":"你們作主人的，待僕人也是一理，不要威嚇他們。因為知道，他們和你們同有一位主在天上；他並不偏待人。","notes":[]},{"n":10,"t":"我還有末了的話：你們要靠著主，倚賴他的大能大力作剛強的人。","notes":[],"heads":["與邪惡爭戰"]},{"n":11,"t":"要穿戴神所賜的全副軍裝，就能抵擋魔鬼的詭計。","notes":[]},{"n":12,"t":"因我們並不是與屬血氣的爭戰，乃是與那些執政的、掌權的、管轄這幽暗世界的，以及天空屬靈氣的惡魔爭戰。","notes":["原文是摔跤；下同"]},{"n":13,"t":"所以，要拿起神所賜的全副軍裝，好在磨難的日子抵擋仇敵，並且成就了一切，還能站立得住。","notes":[]},{"n":14,"t":"所以要站穩了，用真理當作帶子束腰，用公義當作護心鏡遮胸，","notes":[]},{"n":15,"t":"又用平安的福音當作預備走路的鞋穿在腳上。","notes":[]},{"n":16,"t":"此外，又拿著信德當作盾牌，可以滅盡那惡者一切的火箭；","notes":[]},{"n":17,"t":"並戴上救恩的頭盔，拿著聖靈的寶劍，就是神的道；","notes":[]},{"n":18,"t":"靠著聖靈，隨時多方禱告祈求；並要在此警醒不倦，為眾聖徒祈求，","notes":[]},{"n":19,"t":"也為我祈求，使我得著口才，能以放膽開口講明福音的奧祕，","notes":[]},{"n":20,"t":"（我為這福音的奧祕作了帶鎖鍊的使者，）並使我照著當盡的本分放膽講論。","notes":[]},{"n":21,"t":"今有所親愛、忠心事奉主的兄弟推基古，他要把我的事情，並我的景況如何全告訴你們，叫你們知道。","notes":[],"heads":["祝福"]},{"n":22,"t":"我特意打發他到你們那裏去，好叫你們知道我們的光景，又叫他安慰你們的心。","notes":[]},{"n":23,"t":"願平安、仁愛、信心從父神和主耶穌基督歸與弟兄們！","notes":[]},{"n":24,"t":"並願所有誠心愛我們主耶穌基督的人都蒙恩惠！","notes":[]}]}},"PHP":{"1":{"heading":"問候","verses":[{"n":1,"t":"基督耶穌的僕人保羅和提摩太寫信給凡住腓立比、在基督耶穌裏的眾聖徒，和諸位監督，諸位執事。","notes":[]},{"n":2,"t":"願恩惠、平安從神我們的父並主耶穌基督歸與你們！","notes":[]},{"n":3,"t":"我每逢想念你們，就感謝我的神；","notes":[],"heads":["保羅為腓立比信徒禱告"]},{"n":4,"t":"每逢為你們眾人祈求的時候，常是歡歡喜喜地祈求。","notes":[]},{"n":5,"t":"因為從頭一天直到如今，你們是同心合意地興旺福音。","notes":[]},{"n":6,"t":"我深信那在你們心裏動了善工的，必成全這工，直到耶穌基督的日子。","notes":[]},{"n":7,"t":"我為你們眾人有這樣的意念，原是應當的；因你們常在我心裏，無論我是在捆鎖之中，是辯明證實福音的時候，你們都與我一同得恩。","notes":[]},{"n":8,"t":"我體會基督耶穌的心腸，切切地想念你們眾人；這是神可以給我作見證的。","notes":[]},{"n":9,"t":"我所禱告的，就是要你們的愛心在知識和各樣見識上多而又多，","notes":[]},{"n":10,"t":"使你們能分別是非，作誠實無過的人，直到基督的日子；","notes":["或譯：喜愛那美好的事"]},{"n":11,"t":"並靠著耶穌基督結滿了仁義的果子，叫榮耀稱讚歸與神。","notes":[]},{"n":12,"t":"弟兄們，我願意你們知道，我所遭遇的事更是叫福音興旺，","notes":[],"heads":["我活著就是基督"]},{"n":13,"t":"以致我受的捆鎖在御營全軍和其餘的人中，已經顯明是為基督的緣故。","notes":[]},{"n":14,"t":"並且那在主裏的弟兄多半因我受的捆鎖就篤信不疑，越發放膽傳神的道，無所懼怕。","notes":[]},{"n":15,"t":"有的傳基督是出於嫉妒紛爭，也有的是出於好意。","notes":[]},{"n":16,"t":"這一等是出於愛心，知道我是為辯明福音設立的；","notes":[]},{"n":17,"t":"那一等傳基督是出於結黨，並不誠實，意思要加增我捆鎖的苦楚。","notes":[]},{"n":18,"t":"這有何妨呢？或是假意，或是真心，無論怎樣，基督究竟被傳開了。為此，我就歡喜，並且還要歡喜；","notes":[]},{"n":19,"t":"因為我知道，這事藉著你們的祈禱和耶穌基督之靈的幫助，終必叫我得救。","notes":[]},{"n":20,"t":"照著我所切慕、所盼望的，沒有一事叫我羞愧。只要凡事放膽，無論是生是死，總叫基督在我身上照常顯大。","notes":[]},{"n":21,"t":"因我活著就是基督，我死了就有益處。","notes":[]},{"n":22,"t":"但我在肉身活著，若成就我工夫的果子，我就不知道該挑選甚麼。","notes":[]},{"n":23,"t":"我正在兩難之間，情願離世與基督同在，因為這是好得無比的。","notes":[]},{"n":24,"t":"然而，我在肉身活著，為你們更是要緊的。","notes":[]},{"n":25,"t":"我既然這樣深信，就知道仍要住在世間，且與你們眾人同住，使你們在所信的道上又長進又喜樂，","notes":[]},{"n":26,"t":"叫你們在基督耶穌裏的歡樂，因我再到你們那裏去，就越發加增。","notes":[]},{"n":27,"t":"只要你們行事為人與基督的福音相稱，叫我或來見你們，或不在你們那裏，可以聽見你們的景況，知道你們同有一個心志，站立得穩，為所信的福音齊心努力。","notes":[]},{"n":28,"t":"凡事不怕敵人的驚嚇，這是證明他們沉淪，你們得救都是出於神。","notes":[]},{"n":29,"t":"因為你們蒙恩，不但得以信服基督，並要為他受苦。","notes":[]},{"n":30,"t":"你們的爭戰，就與你們在我身上從前所看見、現在所聽見的一樣。","notes":[]}]},"2":{"heading":"以基督的心為心","verses":[{"n":1,"t":"所以，在基督裏若有甚麼勸勉，愛心有甚麼安慰，聖靈有甚麼交通，心中有甚麼慈悲憐憫，","notes":[]},{"n":2,"t":"你們就要意念相同，愛心相同，有一樣的心思，有一樣的意念，使我的喜樂可以滿足。","notes":[]},{"n":3,"t":"凡事不可結黨，不可貪圖虛浮的榮耀；只要存心謙卑，各人看別人比自己強。","notes":[]},{"n":4,"t":"各人不要單顧自己的事，也要顧別人的事。","notes":[]},{"n":5,"t":"你們當以基督耶穌的心為心：","notes":[]},{"n":6,"t":"他本有神的形像，不以自己與神同等為強奪的；","notes":[]},{"n":7,"t":"反倒虛己，取了奴僕的形像，成為人的樣式；","notes":[]},{"n":8,"t":"既有人的樣子，就自己卑微，存心順服，以至於死，且死在十字架上。","notes":[]},{"n":9,"t":"所以，神將他升為至高，又賜給他那超乎萬名之上的名，","notes":[]},{"n":10,"t":"叫一切在天上的、地上的，和地底下的，因耶穌的名無不屈膝，","notes":[]},{"n":11,"t":"無不口稱「耶穌基督為主」，使榮耀歸與父神。","notes":[]},{"n":12,"t":"這樣看來，我親愛的弟兄，你們既是常順服的，不但我在你們那裏，就是我如今不在你們那裏，更是順服的，就當恐懼戰兢做成你們得救的工夫。","notes":[],"heads":["在這世上像明光照耀"]},{"n":13,"t":"因為你們立志行事都是神在你們心裏運行，為要成就他的美意。","notes":[]},{"n":14,"t":"凡所行的，都不要發怨言，起爭論，","notes":[]},{"n":15,"t":"使你們無可指摘，誠實無偽，在這彎曲悖謬的世代作神無瑕疵的兒女。你們顯在這世代中，好像明光照耀，","notes":[]},{"n":16,"t":"將生命的道表明出來，叫我在基督的日子好誇我沒有空跑，也沒有徒勞。","notes":[]},{"n":17,"t":"我以你們的信心為供獻的祭物，我若被澆奠在其上，也是喜樂，並且與你們眾人一同喜樂。","notes":[]},{"n":18,"t":"你們也要照樣喜樂，並且與我一同喜樂。","notes":[]},{"n":19,"t":"我靠主耶穌指望快打發提摩太去見你們，叫我知道你們的事，心裏就得著安慰。","notes":[],"heads":["提摩太和以巴弗提"]},{"n":20,"t":"因為我沒有別人與我同心，實在掛念你們的事。","notes":[]},{"n":21,"t":"別人都求自己的事，並不求耶穌基督的事。","notes":[]},{"n":22,"t":"但你們知道提摩太的明證；他興旺福音，與我同勞，待我像兒子待父親一樣。","notes":[]},{"n":23,"t":"所以，我一看出我的事要怎樣了結，就盼望立刻打發他去；","notes":[]},{"n":24,"t":"但我靠著主自信我也必快去。","notes":[]},{"n":25,"t":"然而，我想必須打發以巴弗提到你們那裏去。他是我的兄弟，與我一同做工，一同當兵，是你們所差遣的，也是供給我需用的。","notes":[]},{"n":26,"t":"他很想念你們眾人，並且極其難過，因為你們聽見他病了。","notes":[]},{"n":27,"t":"他實在是病了，幾乎要死；然而神憐恤他，不但憐恤他，也憐恤我，免得我憂上加憂。","notes":[]},{"n":28,"t":"所以我越發急速打發他去，叫你們再見他，就可以喜樂，我也可以少些憂愁。","notes":[]},{"n":29,"t":"故此，你們要在主裏歡歡樂樂地接待他，而且要尊重這樣的人；","notes":[]},{"n":30,"t":"因他為做基督的工夫，幾乎至死，不顧性命，要補足你們供給我的不及之處。","notes":[]}]},"3":{"heading":"真正的義","verses":[{"n":1,"t":"弟兄們，我還有話說，你們要靠主喜樂。我把這話再寫給你們，於我並不為難，於你們卻是妥當。","notes":[]},{"n":2,"t":"應當防備犬類，防備作惡的，防備妄自行割的。","notes":[]},{"n":3,"t":"因為真受割禮的，乃是我們這以神的靈敬拜、在基督耶穌裏誇口、不靠著肉體的。","notes":[]},{"n":4,"t":"其實，我也可以靠肉體；若是別人想他可以靠肉體，我更可以靠著了。","notes":[]},{"n":5,"t":"我第八天受割禮；我是以色列族、便雅憫支派的人，是希伯來人所生的希伯來人。就律法說，我是法利賽人；","notes":[]},{"n":6,"t":"就熱心說，我是逼迫教會的；就律法上的義說，我是無可指摘的。","notes":[]},{"n":7,"t":"只是我先前以為與我有益的，我現在因基督都當作有損的。","notes":[]},{"n":8,"t":"不但如此，我也將萬事當作有損的，因我以認識我主基督耶穌為至寶。我為他已經丟棄萬事，看作糞土，為要得著基督；","notes":[]},{"n":9,"t":"並且得以在他裏面，不是有自己因律法而得的義，乃是有信基督的義，就是因信神而來的義，","notes":[]},{"n":10,"t":"使我認識基督，曉得他復活的大能，並且曉得和他一同受苦，效法他的死，","notes":[]},{"n":11,"t":"或者我也得以從死裏復活。","notes":[]},{"n":12,"t":"這不是說我已經得著了，已經完全了；我乃是竭力追求，或者可以得著基督耶穌所以得著我的。","notes":["所以得著我的：或譯所要我得的"],"heads":["向著標竿直跑"]},{"n":13,"t":"弟兄們，我不是以為自己已經得著了；我只有一件事，就是忘記背後，努力面前的，","notes":[]},{"n":14,"t":"向著標竿直跑，要得神在基督耶穌裏從上面召我來得的獎賞。","notes":[]},{"n":15,"t":"所以我們中間，凡是完全人總要存這樣的心；若在甚麼事上存別樣的心，神也必以此指示你們。","notes":[]},{"n":16,"t":"然而，我們到了甚麼地步，就當照著甚麼地步行。","notes":[]},{"n":17,"t":"弟兄們，你們要一同效法我，也當留意看那些照我們榜樣行的人。","notes":[]},{"n":18,"t":"因為有許多人行事是基督十字架的仇敵。我屢次告訴你們，現在又流淚地告訴你們：","notes":[]},{"n":19,"t":"他們的結局就是沉淪；他們的神就是自己的肚腹。他們以自己的羞辱為榮耀，專以地上的事為念。","notes":[]},{"n":20,"t":"我們卻是天上的國民，並且等候救主，就是主耶穌基督從天上降臨。","notes":[]},{"n":21,"t":"他要按著那能叫萬有歸服自己的大能，將我們這卑賤的身體改變形狀，和他自己榮耀的身體相似。","notes":[]}]},"4":{"heading":"保羅的勸導","verses":[{"n":1,"t":"我所親愛、所想念的弟兄們，你們就是我的喜樂，我的冠冕。我親愛的弟兄，你們應當靠主站立得穩。","notes":[]},{"n":2,"t":"我勸友阿蝶和循都基，要在主裏同心。","notes":[]},{"n":3,"t":"我也求你這真實同負一軛的，幫助這兩個女人，因為她們在福音上曾與我一同勞苦；還有革利免，並其餘和我一同做工的，他們的名字都在生命冊上。","notes":[]},{"n":4,"t":"你們要靠主常常喜樂。我再說，你們要喜樂。","notes":[]},{"n":5,"t":"當叫眾人知道你們謙讓的心。主已經近了。","notes":[]},{"n":6,"t":"應當一無掛慮，只要凡事藉著禱告、祈求，和感謝，將你們所要的告訴神。","notes":[]},{"n":7,"t":"神所賜、出人意外的平安必在基督耶穌裏保守你們的心懷意念。","notes":[]},{"n":8,"t":"弟兄們，我還有未盡的話：凡是真實的、可敬的、公義的、清潔的、可愛的、有美名的，若有甚麼德行，若有甚麼稱讚，這些事你們都要思念。","notes":[]},{"n":9,"t":"你們在我身上所學習的，所領受的，所聽見的，所看見的，這些事你們都要去行，賜平安的神就必與你們同在。","notes":[]},{"n":10,"t":"我靠主大大地喜樂，因為你們思念我的心如今又發生；你們向來就思念我，只是沒得機會。","notes":[],"heads":["為餽送而致謝"]},{"n":11,"t":"我並不是因缺乏說這話；我無論在甚麼景況都可以知足，這是我已經學會了。","notes":[]},{"n":12,"t":"我知道怎樣處卑賤，也知道怎樣處豐富；或飽足，或飢餓；或有餘，或缺乏，隨事隨在，我都得了秘訣。","notes":[]},{"n":13,"t":"我靠著那加給我力量的，凡事都能做。","notes":[]},{"n":14,"t":"然而，你們和我同受患難原是美事。","notes":[]},{"n":15,"t":"腓立比人哪，你們也知道我初傳福音離了馬其頓的時候，論到授受的事，除了你們以外，並沒有別的教會供給我。","notes":[]},{"n":16,"t":"就是我在帖撒羅尼迦，你們也一次兩次地打發人供給我的需用。","notes":[]},{"n":17,"t":"我並不求甚麼餽送，所求的就是你們的果子漸漸增多，歸在你們的帳上。","notes":[]},{"n":18,"t":"但我樣樣都有，並且有餘。我已經充足，因我從以巴弗提受了你們的餽送，當作極美的香氣，為神所收納、所喜悅的祭物。","notes":[]},{"n":19,"t":"我的神必照他榮耀的豐富，在基督耶穌裏，使你們一切所需用的都充足。","notes":[]},{"n":20,"t":"願榮耀歸給我們的父神，直到永永遠遠。阿們！","notes":[]},{"n":21,"t":"請問在基督耶穌裏的各位聖徒安。在我這裏的眾弟兄都問你們安。","notes":[],"heads":["祝福"]},{"n":22,"t":"眾聖徒都問你們安。在凱撒家裏的人特特地問你們安。","notes":[]},{"n":23,"t":"願主耶穌基督的恩常在你們心裏！","notes":[]}]}},"COL":{"1":{"heading":"問候","verses":[{"n":1,"t":"奉神旨意，作基督耶穌使徒的保羅和兄弟提摩太","notes":[]},{"n":2,"t":"寫信給歌羅西的聖徒，在基督裏有忠心的弟兄。願恩惠、平安從神我們的父歸與你們！","notes":[]},{"n":3,"t":"我們感謝神我們主耶穌基督的父，常常為你們禱告；","notes":[],"heads":["為信徒感謝神"]},{"n":4,"t":"因聽見你們在基督耶穌裏的信心，並向眾聖徒的愛心，","notes":[]},{"n":5,"t":"是為那給你們存在天上的盼望；這盼望就是你們從前在福音真理的道上所聽見的。","notes":[]},{"n":6,"t":"這福音傳到你們那裏，也傳到普天之下，並且結果，增長，如同在你們中間，自從你們聽見福音，真知道神恩惠的日子一樣。","notes":[]},{"n":7,"t":"正如你們從我們所親愛、一同作僕人的以巴弗所學的。他為我們作了基督忠心的執事，","notes":["有古卷：你們"]},{"n":8,"t":"也把你們因聖靈所存的愛心告訴了我們。","notes":[]},{"n":9,"t":"因此，我們自從聽見的日子，也就為你們不住地禱告祈求，願你們在一切屬靈的智慧悟性上，滿心知道神的旨意；","notes":[],"heads":["基督的位格和工作"]},{"n":10,"t":"好叫你們行事為人對得起主，凡事蒙他喜悅，在一切善事上結果子，漸漸地多知道神；","notes":[]},{"n":11,"t":"照他榮耀的權能，得以在各樣的力上加力，好叫你們凡事歡歡喜喜地忍耐寬容；","notes":[]},{"n":12,"t":"又感謝父，叫我們能與眾聖徒在光明中同得基業。","notes":[]},{"n":13,"t":"他救了我們脫離黑暗的權勢，把我們遷到他愛子的國裏；","notes":[]},{"n":14,"t":"我們在愛子裏得蒙救贖，罪過得以赦免。","notes":[]},{"n":15,"t":"愛子是那不能看見之神的像，是首生的，在一切被造的以先。","notes":[]},{"n":16,"t":"因為萬有都是靠他造的，無論是天上的，地上的；能看見的，不能看見的；或是有位的，主治的，執政的，掌權的；一概都是藉著他造的，又是為他造的。","notes":[]},{"n":17,"t":"他在萬有之先；萬有也靠他而立。","notes":[]},{"n":18,"t":"他也是教會全體之首。他是元始，是從死裏首先復生的，使他可以在凡事上居首位。","notes":[]},{"n":19,"t":"因為父喜歡叫一切的豐盛在他裏面居住。","notes":[]},{"n":20,"t":"既然藉著他在十字架上所流的血成就了和平，便藉著他叫萬有－無論是地上的、天上的－都與自己和好了。","notes":[]},{"n":21,"t":"你們從前與神隔絕，因著惡行，心裏與他為敵。","notes":[]},{"n":22,"t":"但如今他藉著基督的肉身受死，叫你們與自己和好，都成了聖潔，沒有瑕疵，無可責備，把你們引到自己面前。","notes":[]},{"n":23,"t":"只要你們在所信的道上恆心，根基穩固，堅定不移，不致被引動失去福音的盼望。這福音就是你們所聽過的，也是傳與普天下萬人聽的，我－保羅也作了這福音的執事。","notes":["原文是離開","原文是凡受造的"]},{"n":24,"t":"現在我為你們受苦，倒覺歡樂；並且為基督的身體，就是為教會，要在我肉身上補滿基督患難的缺欠。","notes":[],"heads":["保羅為教會的工作"]},{"n":25,"t":"我照神為你們所賜我的職分作了教會的執事，要把神的道理傳得全備，","notes":[]},{"n":26,"t":"這道理就是歷世歷代所隱藏的奧祕；但如今向他的聖徒顯明了。","notes":[]},{"n":27,"t":"神願意叫他們知道，這奧祕在外邦人中有何等豐盛的榮耀，就是基督在你們心裏成了有榮耀的盼望。","notes":[]},{"n":28,"t":"我們傳揚他，是用諸般的智慧，勸戒各人，教導各人，要把各人在基督裏完完全全地引到神面前。","notes":[]},{"n":29,"t":"我也為此勞苦，照著他在我裏面運用的大能盡心竭力。","notes":[]}]},"2":{"heading":"基督裏生命的豐盛","verses":[{"n":1,"t":"我願意你們曉得，我為你們和老底嘉人，並一切沒有與我親自見面的人，是何等地盡心竭力；","notes":[]},{"n":2,"t":"要叫他們的心得安慰，因愛心互相聯絡，以致豐豐足足在悟性中有充足的信心，使他們真知神的奧祕，就是基督；","notes":[]},{"n":3,"t":"所積蓄的一切智慧知識，都在他裏面藏著。","notes":[]},{"n":4,"t":"我說這話，免得有人用花言巧語迷惑你們。","notes":[]},{"n":5,"t":"我身子雖與你們相離，心卻與你們同在，見你們循規蹈矩，信基督的心也堅固，我就歡喜了。","notes":[]},{"n":6,"t":"你們既然接受了主基督耶穌，就當遵他而行，","notes":[]},{"n":7,"t":"在他裏面生根建造，信心堅固，正如你們所領的教訓，感謝的心也更增長了。","notes":[]},{"n":8,"t":"你們要謹慎，恐怕有人用他的理學和虛空的妄言，不照著基督，乃照人間的遺傳和世上的小學就把你們擄去。","notes":[]},{"n":9,"t":"因為神本性一切的豐盛都有形有體地居住在基督裏面，","notes":[]},{"n":10,"t":"你們在他裏面也得了豐盛。他是各樣執政掌權者的元首。","notes":[]},{"n":11,"t":"你們在他裏面也受了不是人手所行的割禮，乃是基督使你們脫去肉體情慾的割禮。","notes":[]},{"n":12,"t":"你們既受洗與他一同埋葬，也就在此與他一同復活，都因信那叫他從死裏復活神的功用。","notes":[]},{"n":13,"t":"你們從前在過犯和未受割禮的肉體中死了，神赦免了你們一切過犯，便叫你們與基督一同活過來；","notes":["或譯：我們"]},{"n":14,"t":"又塗抹了在律例上所寫、攻擊我們、有礙於我們的字據，把它撤去，釘在十字架上。","notes":[]},{"n":15,"t":"既將一切執政的、掌權的擄來，明顯給眾人看，就仗著十字架誇勝。","notes":[]},{"n":16,"t":"所以，不拘在飲食上，或節期、月朔、安息日都不可讓人論斷你們。","notes":[]},{"n":17,"t":"這些原是後事的影兒；那形體卻是基督。","notes":[]},{"n":18,"t":"不可讓人因著故意謙虛和敬拜天使，就奪去你們的獎賞。這等人拘泥在所見過的，隨著自己的慾心，無故地自高自大，","notes":["有古卷：這等人窺察所沒有見過的"]},{"n":19,"t":"不持定元首。全身既然靠著他，筋節得以相助聯絡，就因神大得長進。","notes":[]},{"n":20,"t":"你們若是與基督同死，脫離了世上的小學，為甚麼仍像在世俗中活著、服從那「不可拿、不可嘗、不可摸」等類的規條呢？","notes":[],"end":21,"heads":["基督裏的新生活"]},{"n":22,"t":"這都是照人所吩咐、所教導的。說到這一切，正用的時候就都敗壞了。","notes":[]},{"n":23,"t":"這些規條使人徒有智慧之名，用私意崇拜，自表謙卑，苦待己身，其實在克制肉體的情慾上是毫無功效。","notes":[]}]},"3":{"heading":"新生活的本分","verses":[{"n":1,"t":"所以，你們若真與基督一同復活，就當求在上面的事；那裏有基督坐在神的右邊。","notes":[]},{"n":2,"t":"你們要思念上面的事，不要思念地上的事。","notes":[]},{"n":3,"t":"因為你們已經死了，你們的生命與基督一同藏在神裏面。","notes":[]},{"n":4,"t":"基督是我們的生命，他顯現的時候，你們也要與他一同顯現在榮耀裏。","notes":[]},{"n":5,"t":"所以，要治死你們在地上的肢體，就如淫亂、污穢、邪情、惡慾，和貪婪（貪婪就與拜偶像一樣）。","notes":[]},{"n":6,"t":"因這些事，神的忿怒必臨到那悖逆之子。","notes":[]},{"n":7,"t":"當你們在這些事中活著的時候，也曾這樣行過。","notes":[]},{"n":8,"t":"但現在你們要棄絕這一切的事，以及惱恨、忿怒、惡毒、毀謗，並口中污穢的言語。","notes":["或譯：陰毒"]},{"n":9,"t":"不要彼此說謊；因你們已經脫去舊人和舊人的行為，","notes":[]},{"n":10,"t":"穿上了新人。這新人在知識上漸漸更新，正如造他主的形像。","notes":[]},{"n":11,"t":"在此並不分希臘人、猶太人，受割禮的、未受割禮的，化外人、西古提人，為奴的、自主的，惟有基督是包括一切，又住在各人之內。","notes":[]},{"n":12,"t":"所以，你們既是神的選民，聖潔蒙愛的人，就要存憐憫、恩慈、謙虛、溫柔、忍耐的心。","notes":["原文是穿：下同"]},{"n":13,"t":"倘若這人與那人有嫌隙，總要彼此包容，彼此饒恕；主怎樣饒恕了你們，你們也要怎樣饒恕人。","notes":[]},{"n":14,"t":"在這一切之外，要存著愛心，愛心就是聯絡全德的。","notes":[]},{"n":15,"t":"又要叫基督的平安在你們心裏作主；你們也為此蒙召，歸為一體；且要存感謝的心。","notes":[]},{"n":16,"t":"當用各樣的智慧，把基督的道理豐豐富富地存在心裏，用詩章、頌詞、靈歌，彼此教導，互相勸戒，心被恩感，歌頌神。","notes":["或譯：當把基督的道理豐豐富富地存在心裏，以各樣的智慧"]},{"n":17,"t":"無論做甚麼，或說話或行事，都要奉主耶穌的名，藉著他感謝父神。","notes":[]},{"n":18,"t":"你們作妻子的，當順服自己的丈夫，這在主裏面是相宜的。","notes":[]},{"n":19,"t":"你們作丈夫的，要愛你們的妻子，不可苦待她們。","notes":[]},{"n":20,"t":"你們作兒女的，要凡事聽從父母，因為這是主所喜悅的。","notes":[]},{"n":21,"t":"你們作父親的，不要惹兒女的氣，恐怕他們失了志氣。","notes":[]},{"n":22,"t":"你們作僕人的，要凡事聽從你們肉身的主人，不要只在眼前事奉，像是討人喜歡的，總要存心誠實敬畏主。","notes":[]},{"n":23,"t":"無論做甚麼，都要從心裏做，像是給主做的，不是給人做的，","notes":[]},{"n":24,"t":"因你們知道從主那裏必得著基業為賞賜；你們所事奉的乃是主基督。","notes":[]},{"n":25,"t":"那行不義的必受不義的報應；主並不偏待人。","notes":[]}]},"4":{"heading":"勸導","verses":[{"n":1,"t":"你們作主人的，要公公平平地待僕人，因為知道你們也有一位主在天上。","notes":[]},{"n":2,"t":"你們要恆切禱告，在此警醒感恩。","notes":[]},{"n":3,"t":"也要為我們禱告，求神給我們開傳道的門，能以講基督的奧祕（我為此被捆鎖），","notes":[]},{"n":4,"t":"叫我按著所該說的話將這奧祕發明出來。","notes":[]},{"n":5,"t":"你們要愛惜光陰，用智慧與外人交往。","notes":[]},{"n":6,"t":"你們的言語要常常帶著和氣，好像用鹽調和，就可知道該怎樣回答各人。","notes":[]},{"n":7,"t":"有我親愛的兄弟推基古要將我一切的事都告訴你們。他是忠心的執事，和我一同作主的僕人。","notes":[],"heads":["最後的問候"]},{"n":8,"t":"我特意打發他到你們那裏去，好叫你們知道我們的光景，又叫他安慰你們的心。","notes":[]},{"n":9,"t":"我又打發一位親愛忠心的兄弟阿尼西謀同去；他也是你們那裏的人。他們要把這裏一切的事都告訴你們。","notes":[]},{"n":10,"t":"與我一同坐監的亞里達古問你們安。巴拿巴的表弟馬可也問你們安。（說到這馬可，你們已經受了吩咐；他若到了你們那裏，你們就接待他。）","notes":[]},{"n":11,"t":"耶數又稱為猶士都，也問你們安。奉割禮的人中，只有這三個人是為神的國與我一同做工的，也是叫我心裏得安慰的。","notes":[]},{"n":12,"t":"有你們那裏的人，作基督耶穌僕人的以巴弗問你們安。他在禱告之間，常為你們竭力地祈求，願你們在神一切的旨意上得以完全，信心充足，能站立得穩。","notes":[]},{"n":13,"t":"他為你們和老底嘉並希拉坡里的弟兄多多地勞苦，這是我可以給他作見證的。","notes":[]},{"n":14,"t":"所親愛的醫生路加和底馬問你們安。","notes":[]},{"n":15,"t":"請問老底嘉的弟兄和寧法，並她家裏的教會安。","notes":[]},{"n":16,"t":"你們念了這書信，便交給老底嘉的教會，叫他們也念；你們也要念從老底嘉來的書信。","notes":[]},{"n":17,"t":"要對亞基布說：「務要謹慎，盡你從主所受的職分。」","notes":[]},{"n":18,"t":"我－保羅親筆問你們安。你們要記念我的捆鎖。願恩惠常與你們同在！","notes":[]}]}},"1TH":{"1":{"heading":"問候","verses":[{"n":1,"t":"保羅、西拉、提摩太寫信給帖撒羅尼迦在父神和主耶穌基督裏的教會。願恩惠、平安歸與你們！","notes":[]},{"n":2,"t":"我們為你們眾人常常感謝神，禱告的時候提到你們，","notes":[],"heads":["帖撒羅尼迦信徒的信心和榜樣"]},{"n":3,"t":"在神－我們的父面前，不住地記念你們因信心所做的工夫，因愛心所受的勞苦，因盼望我們主耶穌基督所存的忍耐。","notes":[]},{"n":4,"t":"被神所愛的弟兄啊，我知道你們是蒙揀選的；","notes":[]},{"n":5,"t":"因為我們的福音傳到你們那裏，不獨在乎言語，也在乎權能和聖靈，並充足的信心。正如你們知道，我們在你們那裏，為你們的緣故是怎樣為人。","notes":[]},{"n":6,"t":"並且你們在大難之中，蒙了聖靈所賜的喜樂，領受真道就效法我們，也效法了主；","notes":[]},{"n":7,"t":"甚至你們作了馬其頓和亞該亞所有信主之人的榜樣。","notes":[]},{"n":8,"t":"因為主的道從你們那裏已經傳揚出來。你們向神的信心不但在馬其頓和亞該亞，就是在各處也都傳開了，所以不用我們說甚麼話。","notes":[]},{"n":9,"t":"因為他們自己已經報明我們是怎樣進到你們那裏，你們是怎樣離棄偶像，歸向神，要服事那又真又活的神，","notes":[]},{"n":10,"t":"等候他兒子從天降臨，就是他從死裏復活的－那位救我們脫離將來忿怒的耶穌。","notes":[]}]},"2":{"heading":"保羅在帖撒羅尼迦工作","verses":[{"n":1,"t":"弟兄們，你們自己原曉得我們進到你們那裏並不是徒然的。","notes":[]},{"n":2,"t":"我們從前在腓立比被害受辱，這是你們知道的；然而還是靠我們的神放開膽量，在大爭戰中把神的福音傳給你們。","notes":[]},{"n":3,"t":"我們的勸勉不是出於錯誤，不是出於污穢，也不是用詭詐。","notes":[]},{"n":4,"t":"但神既然驗中了我們，把福音託付我們，我們就照樣講，不是要討人喜歡，乃是要討那察驗我們心的神喜歡。","notes":[]},{"n":5,"t":"因為我們從來沒有用過諂媚的話，這是你們知道的；也沒有藏著貪心，這是神可以作見證的。","notes":[]},{"n":6,"t":"我們作基督的使徒，雖然可以叫人尊重，卻沒有向你們或向別人求榮耀；","notes":[]},{"n":7,"t":"只在你們中間存心溫柔，如同母親乳養自己的孩子。","notes":[]},{"n":8,"t":"我們既是這樣愛你們，不但願意將神的福音給你們，連自己的性命也願意給你們，因你們是我們所疼愛的。","notes":[]},{"n":9,"t":"弟兄們，你們記念我們的辛苦勞碌，晝夜做工，傳神的福音給你們，免得叫你們一人受累。","notes":[]},{"n":10,"t":"我們向你們信主的人，是何等聖潔、公義、無可指摘，有你們作見證，也有神作見證。","notes":[]},{"n":11,"t":"你們也曉得，我們怎樣勸勉你們，安慰你們，囑咐你們各人，好像父親待自己的兒女一樣，","notes":[]},{"n":12,"t":"要叫你們行事對得起那召你們進他國、得他榮耀的神。","notes":[]},{"n":13,"t":"為此，我們也不住地感謝神，因你們聽見我們所傳神的道就領受了；不以為是人的道，乃以為是神的道。這道實在是神的，並且運行在你們信主的人心中。","notes":[]},{"n":14,"t":"弟兄們，你們曾效法猶太中在基督耶穌裏神的各教會；因為你們也受了本地人的苦害，像他們受了猶太人的苦害一樣。","notes":[]},{"n":15,"t":"這猶太人殺了主耶穌和先知，又把我們趕出去。他們不得神的喜悅，且與眾人為敵，","notes":[]},{"n":16,"t":"不許我們傳道給外邦人使外邦人得救，常常充滿自己的罪惡。神的忿怒臨在他們身上已經到了極處。","notes":[]},{"n":17,"t":"弟兄們，我們暫時與你們離別，是面目離別，心裏卻不離別；我們極力地想法子，很願意見你們的面。","notes":[],"heads":["保羅希望再訪問帖撒羅尼迦教會"]},{"n":18,"t":"所以我們有意到你們那裏；我－保羅有一兩次要去，只是撒但阻擋了我們。","notes":[]},{"n":19,"t":"我們的盼望和喜樂，並所誇的冠冕是甚麼呢？豈不是我們主耶穌來的時候、你們在他面前站立得住嗎？","notes":[]},{"n":20,"t":"因為你們就是我們的榮耀，我們的喜樂。","notes":[]}]},"3":{"heading":"","verses":[{"n":1,"t":"我們既不能再忍，就願意獨自等在雅典，","notes":[]},{"n":2,"t":"打發我們的兄弟在基督福音上作神執事的 提摩太前去，堅固你們，並在你們所信的道上勸慰你們，","notes":["作神執事的：有古卷是與神同工的"]},{"n":3,"t":"免得有人被諸般患難搖動。因為你們自己知道，我們受患難原是命定的。","notes":[]},{"n":4,"t":"我們在你們那裏的時候，預先告訴你們，我們必受患難，以後果然應驗了，你們也知道。","notes":[]},{"n":5,"t":"為此，我既不能再忍，就打發人去，要曉得你們的信心如何，恐怕那誘惑人的到底誘惑了你們，叫我們的勞苦歸於徒然。","notes":[]},{"n":6,"t":"但提摩太剛才從你們那裏回來，將你們信心和愛心的好消息報給我們，又說你們常常記念我們，切切地想見我們，如同我們想見你們一樣。","notes":[]},{"n":7,"t":"所以，弟兄們，我們在一切困苦患難之中，因著你們的信心就得了安慰。","notes":[]},{"n":8,"t":"你們若靠主站立得穩，我們就活了。","notes":[]},{"n":9,"t":"我們在神面前，因著你們甚是喜樂；為這一切喜樂，可用何等的感謝為你們報答神呢？","notes":[]},{"n":10,"t":"我們晝夜切切地祈求，要見你們的面，補滿你們信心的不足。","notes":[]},{"n":11,"t":"願神－我們的父和我們的主耶穌一直引領我們到你們那裏去。","notes":[]},{"n":12,"t":"又願主叫你們彼此相愛的心，並愛眾人的心都能增長，充足，如同我們愛你們一樣，","notes":[]},{"n":13,"t":"好使你們當我們主耶穌同他眾聖徒來的時候，在我們父神面前，心裏堅固，成為聖潔，無可責備。","notes":[]}]},"4":{"heading":"神所悅納的生活","verses":[{"n":1,"t":"弟兄們，我還有話說：我們靠著主耶穌求你們，勸你們，你們既然受了我們的教訓，知道該怎樣行可以討神的喜悅，就要照你們現在所行的更加勉勵。","notes":[]},{"n":2,"t":"你們原曉得，我們憑主耶穌傳給你們甚麼命令。","notes":[]},{"n":3,"t":"神的旨意就是要你們成為聖潔，遠避淫行；","notes":[]},{"n":4,"t":"要你們各人曉得怎樣用聖潔、尊貴守著自己的身體，","notes":[]},{"n":5,"t":"不放縱私慾的邪情，像那不認識神的外邦人。","notes":[]},{"n":6,"t":"不要一個人在這事上越分，欺負他的弟兄；因為這一類的事，主必報應，正如我預先對你們說過、又切切囑咐你們的。","notes":[]},{"n":7,"t":"神召我們，本不是要我們沾染污穢，乃是要我們成為聖潔。","notes":[]},{"n":8,"t":"所以，那棄絕的，不是棄絕人，乃是棄絕那賜聖靈給你們的神。","notes":[]},{"n":9,"t":"論到弟兄們相愛，不用人寫信給你們；因為你們自己蒙了神的教訓，叫你們彼此相愛。","notes":[]},{"n":10,"t":"你們向馬其頓全地的眾弟兄固然是這樣行，但我勸弟兄們要更加勉勵。","notes":[]},{"n":11,"t":"又要立志作安靜人，辦自己的事，親手做工，正如我們從前所吩咐你們的，","notes":[]},{"n":12,"t":"叫你們可以向外人行事端正，自己也就沒有甚麼缺乏了。","notes":[]},{"n":13,"t":"論到睡了的人，我們不願意弟兄們不知道，恐怕你們憂傷，像那些沒有指望的人一樣。","notes":[],"heads":["主的降臨"]},{"n":14,"t":"我們若信耶穌死而復活了，那已經在耶穌裏睡了的人，神也必將他們與耶穌一同帶來。","notes":[]},{"n":15,"t":"我們現在照主的話告訴你們一件事：我們這活著還存留到主降臨的人，斷不能在那已經睡了的人之先。","notes":[]},{"n":16,"t":"因為主必親自從天降臨，有呼叫的聲音和天使長的聲音，又有神的號吹響；那在基督裏死了的人必先復活。","notes":[]},{"n":17,"t":"以後我們這活著還存留的人必和他們一同被提到雲裏，在空中與主相遇。這樣，我們就要和主永遠同在。","notes":[]},{"n":18,"t":"所以，你們當用這些話彼此勸慰。","notes":[]}]},"5":{"heading":"最後的勸勉與祝福","verses":[{"n":1,"t":"弟兄們，論到時候、日期，不用寫信給你們，","notes":[]},{"n":2,"t":"因為你們自己明明曉得，主的日子來到，好像夜間的賊一樣。","notes":[]},{"n":3,"t":"人正說「平安穩妥」的時候，災禍忽然臨到他們，如同產難臨到懷胎的婦人一樣，他們絕不能逃脫。","notes":[]},{"n":4,"t":"弟兄們，你們卻不在黑暗裏，叫那日子臨到你們像賊一樣。","notes":[]},{"n":5,"t":"你們都是光明之子，都是白晝之子。我們不是屬黑夜的，也不是屬幽暗的。","notes":[]},{"n":6,"t":"所以，我們不要睡覺像別人一樣，總要警醒謹守。","notes":[]},{"n":7,"t":"因為睡了的人是在夜間睡，醉了的人是在夜間醉。","notes":[]},{"n":8,"t":"但我們既然屬乎白晝，就應當謹守，把信和愛當作護心鏡遮胸，把得救的盼望當作頭盔戴上。","notes":[]},{"n":9,"t":"因為神不是預定我們受刑，乃是預定我們藉著我們主耶穌基督得救。","notes":[]},{"n":10,"t":"他替我們死，叫我們無論醒著，睡著，都與他同活。","notes":[]},{"n":11,"t":"所以，你們該彼此勸慰，互相建立，正如你們素常所行的。","notes":[]},{"n":12,"t":"弟兄們，我們勸你們敬重那在你們中間勞苦的人，就是在主裏面治理你們、勸戒你們的；","notes":[]},{"n":13,"t":"又因他們所做的工，用愛心格外尊重他們。你們也要彼此和睦。","notes":[]},{"n":14,"t":"我們又勸弟兄們，要警戒不守規矩的人，勉勵灰心的人，扶助軟弱的人，也要向眾人忍耐。","notes":[]},{"n":15,"t":"你們要謹慎，無論是誰都不可以惡報惡；或是彼此相待，或是待眾人，常要追求良善。","notes":[]},{"n":16,"t":"要常常喜樂，","notes":[]},{"n":17,"t":"不住地禱告，","notes":[]},{"n":18,"t":"凡事謝恩；因為這是神在基督耶穌裏向你們所定的旨意。","notes":[]},{"n":19,"t":"不要消滅聖靈的感動；","notes":[]},{"n":20,"t":"不要藐視先知的講論。","notes":[]},{"n":21,"t":"但要凡事察驗；善美的要持守，","notes":[]},{"n":22,"t":"各樣的惡事要禁戒不做。","notes":[]},{"n":23,"t":"願賜平安的神親自使你們全然成聖！又願你們的靈與魂與身子得蒙保守，在我們主耶穌基督降臨的時候，完全無可指摘！","notes":[]},{"n":24,"t":"那召你們的本是信實的，他必成就這事。","notes":[]},{"n":25,"t":"請弟兄們為我們禱告。","notes":[]},{"n":26,"t":"與眾弟兄親嘴問安，務要聖潔。","notes":[]},{"n":27,"t":"我指著主囑咐你們，要把這信念給眾弟兄聽。","notes":[]},{"n":28,"t":"願我主耶穌基督的恩常與你們同在！","notes":[]}]}},"2TH":{"1":{"heading":"問候","verses":[{"n":1,"t":"保羅、西拉、提摩太寫信給帖撒羅尼迦、在神－我們的父與主耶穌基督裏的教會。","notes":[]},{"n":2,"t":"願恩惠、平安從父神和主耶穌基督歸與你們！","notes":[]},{"n":3,"t":"弟兄們，我們該為你們常常感謝神，這本是合宜的；因你們的信心格外增長，並且你們眾人彼此相愛的心也都充足。","notes":[],"heads":["基督再來時的審判"]},{"n":4,"t":"甚至我們在神的各教會裏為你們誇口，都因你們在所受的一切逼迫患難中，仍舊存忍耐和信心。","notes":[]},{"n":5,"t":"這正是神公義判斷的明證，叫你們可算配得神的國；你們就是為這國受苦。","notes":[]},{"n":6,"t":"神既是公義的，就必將患難報應那加患難給你們的人，","notes":[]},{"n":7,"t":"也必使你們這受患難的人與我們同得平安。那時，主耶穌同他有能力的天使從天上在火焰中顯現，","notes":[]},{"n":8,"t":"要報應那不認識神和那不聽從我主耶穌福音的人。","notes":[]},{"n":9,"t":"他們要受刑罰，就是永遠沉淪，離開主的面和他權能的榮光。","notes":[]},{"n":10,"t":"這正是主降臨、要在他聖徒的身上得榮耀、又在一切信的人身上顯為希奇的那日子。我們對你們作的見證，你們也信了。","notes":[]},{"n":11,"t":"因此，我們常為你們禱告，願我們的神看你們配得過所蒙的召，又用大能成就你們一切所羨慕的良善和一切因信心所做的工夫，","notes":[]},{"n":12,"t":"叫我們主耶穌的名在你們身上得榮耀，你們也在他身上得榮耀，都照著我們的神並主耶穌基督的恩。","notes":[]}]},"2":{"heading":"不法的人","verses":[{"n":1,"t":"弟兄們，論到我們主耶穌基督降臨和我們到他那裏聚集，","notes":[]},{"n":2,"t":"我勸你們：無論有靈、有言語、有冒我名的書信，說主的日子現在到了，不要輕易動心，也不要驚慌。","notes":["現在：或譯就"]},{"n":3,"t":"人不拘用甚麼法子，你們總不要被他誘惑；因為那日子以前，必有離道反教的事，並有那大罪人，就是沉淪之子，顯露出來。","notes":[]},{"n":4,"t":"他是抵擋主，高抬自己，超過一切稱為神的和一切受人敬拜的，甚至坐在神的殿裏，自稱是神。","notes":[]},{"n":5,"t":"我還在你們那裏的時候，曾把這些事告訴你們，你們不記得嗎？","notes":[]},{"n":6,"t":"現在你們也知道，那攔阻他的是甚麼，是叫他到了的時候才可以顯露。","notes":[]},{"n":7,"t":"因為那不法的隱意已經發動，只是現在有一個攔阻的，等到那攔阻的被除去，","notes":[]},{"n":8,"t":"那時這不法的人必顯露出來。主耶穌要用口中的氣滅絕他，用降臨的榮光廢掉他。","notes":[]},{"n":9,"t":"這不法的人來，是照撒但的運動，行各樣的異能、神蹟，和一切虛假的奇事，","notes":[]},{"n":10,"t":"並且在那沉淪的人身上行各樣出於不義的詭詐；因他們不領受愛真理的心，使他們得救。","notes":[]},{"n":11,"t":"故此，神就給他們一個生發錯誤的心，叫他們信從虛謊，","notes":[]},{"n":12,"t":"使一切不信真理、倒喜愛不義的人都被定罪。","notes":[]},{"n":13,"t":"主所愛的弟兄們哪，我們本該常為你們感謝神；因為他從起初揀選了你們，叫你們因信真道，又被聖靈感動，成為聖潔，能以得救。","notes":[],"heads":["被揀選接受救恩"]},{"n":14,"t":"神藉我們所傳的福音召你們到這地步，好得著我們主耶穌基督的榮光。","notes":[]},{"n":15,"t":"所以，弟兄們，你們要站立得穩，凡所領受的教訓，不拘是我們口傳的，是信上寫的，都要堅守。","notes":[]},{"n":16,"t":"但願我們主耶穌基督和那愛我們、開恩將永遠的安慰並美好的盼望賜給我們的父神，","notes":[]},{"n":17,"t":"安慰你們的心，並且在一切善行善言上堅固你們。","notes":[]}]},"3":{"heading":"請為我們禱告","verses":[{"n":1,"t":"弟兄們，我還有話說：請你們為我們禱告，好叫主的道理快快行開，得著榮耀，正如在你們中間一樣，","notes":[]},{"n":2,"t":"也叫我們脫離無理之惡人的手；因為人不都是有信心。","notes":[]},{"n":3,"t":"但主是信實的，要堅固你們，保護你們脫離那惡者。","notes":["或譯：脫離凶惡"]},{"n":4,"t":"我們靠主深信，你們現在是遵行我們所吩咐的，後來也必要遵行。","notes":[]},{"n":5,"t":"願主引導你們的心，叫你們愛神，並學基督的忍耐！","notes":[]},{"n":6,"t":"弟兄們，我們奉主耶穌基督的名吩咐你們，凡有弟兄不按規矩而行，不遵守從我們所受的教訓，就當遠離他。","notes":[],"heads":["警戒懶惰的人"]},{"n":7,"t":"你們自己原知道應當怎樣效法我們。因為我們在你們中間，未嘗不按規矩而行，","notes":[]},{"n":8,"t":"也未嘗白吃人的飯，倒是辛苦勞碌，晝夜做工，免得叫你們一人受累。","notes":[]},{"n":9,"t":"這並不是因我們沒有權柄，乃是要給你們作榜樣，叫你們效法我們。","notes":[]},{"n":10,"t":"我們在你們那裏的時候，曾吩咐你們說，若有人不肯做工，就不可吃飯。","notes":[]},{"n":11,"t":"因我們聽說，在你們中間有人不按規矩而行，甚麼工都不做，反倒專管閒事。","notes":[]},{"n":12,"t":"我們靠主耶穌基督吩咐、勸戒這樣的人，要安靜做工，吃自己的飯。","notes":[]},{"n":13,"t":"弟兄們，你們行善不可喪志。","notes":[]},{"n":14,"t":"若有人不聽從我們這信上的話，要記下他，不和他交往，叫他自覺羞愧。","notes":[]},{"n":15,"t":"但不要以他為仇人，要勸他如弟兄。","notes":[]},{"n":16,"t":"願賜平安的主隨時隨事親自給你們平安！願主常與你們眾人同在！","notes":[],"heads":["祝福"]},{"n":17,"t":"我－保羅親筆問你們安。凡我的信都以此為記，我的筆跡就是這樣。","notes":[]},{"n":18,"t":"願我們主耶穌基督的恩常與你們眾人同在！","notes":[]}]}},"1TI":{"1":{"heading":"問候","verses":[{"n":1,"t":"奉我們救主神和我們的盼望基督耶穌之命，作基督耶穌使徒的保羅","notes":[]},{"n":2,"t":"寫信給那因信主作我真兒子的提摩太。願恩惠、憐憫、平安從父神和我們主基督耶穌歸與你！","notes":[]},{"n":3,"t":"我往馬其頓去的時候，曾勸你仍住在以弗所，好囑咐那幾個人不可傳異教，","notes":[],"heads":["警告虛偽的道理"]},{"n":4,"t":"也不可聽從荒謬無憑的話語和無窮的家譜；這等事只生辯論，並不發明神在信上所立的章程。","notes":[]},{"n":5,"t":"但命令的總歸就是愛；這愛是從清潔的心和無虧的良心，無偽的信心生出來的。","notes":[]},{"n":6,"t":"有人偏離這些，反去講虛浮的話，","notes":[]},{"n":7,"t":"想要作教法師，卻不明白自己所講說的所論定的。","notes":[]},{"n":8,"t":"我們知道律法原是好的，只要人用得合宜；","notes":[]},{"n":9,"t":"因為律法不是為義人設立的，乃是為不法和不服的，不虔誠和犯罪的，不聖潔和戀世俗的，弒父母和殺人的，","notes":[]},{"n":10,"t":"行淫和親男色的，搶人口和說謊話的，並起假誓的，或是為別樣敵正道的事設立的。","notes":[]},{"n":11,"t":"這是照著可稱頌之神交託我榮耀福音說的。","notes":[]},{"n":12,"t":"我感謝那給我力量的我們主基督耶穌，因他以我有忠心，派我服事他。","notes":[],"heads":["感謝神的憐憫"]},{"n":13,"t":"我從前是褻瀆神的，逼迫人的，侮慢人的；然而我還蒙了憐憫，因我是不信不明白的時候而做的。","notes":[]},{"n":14,"t":"並且我主的恩是格外豐盛，使我在基督耶穌裏有信心和愛心。","notes":[]},{"n":15,"t":"「基督耶穌降世，為要拯救罪人。」這話是可信的，是十分可佩服的。在罪人中我是個罪魁。","notes":[]},{"n":16,"t":"然而，我蒙了憐憫，是因耶穌基督要在我這罪魁身上顯明他一切的忍耐，給後來信他得永生的人作榜樣。","notes":[]},{"n":17,"t":"但願尊貴、榮耀歸與那不能朽壞、不能看見、永世的君王、獨一的神，直到永永遠遠。阿們！","notes":[]},{"n":18,"t":"我兒提摩太啊，我照從前指著你的預言，將這命令交託你，叫你因此可以打那美好的仗。","notes":[]},{"n":19,"t":"常存信心和無虧的良心。有人丟棄良心，就在真道上如同船破壞了一般。","notes":[]},{"n":20,"t":"其中有許米乃和亞歷山大；我已經把他們交給撒但，使他們受責罰就不再謗瀆了。","notes":[]}]},"2":{"heading":"有關禱告的指示","verses":[{"n":1,"t":"我勸你，第一要為萬人懇求、禱告、代求、祝謝；","notes":[]},{"n":2,"t":"為君王和一切在位的，也該如此，使我們可以敬虔、端正、平安無事地度日。","notes":[]},{"n":3,"t":"這是好的，在神我們救主面前可蒙悅納。","notes":[]},{"n":4,"t":"他願意萬人得救，明白真道。","notes":[]},{"n":5,"t":"因為只有一位神，在神和人中間，只有一位中保，乃是降世為人的基督耶穌；","notes":[]},{"n":6,"t":"他捨自己作萬人的贖價，到了時候，這事必證明出來。","notes":[]},{"n":7,"t":"我為此奉派作傳道的，作使徒，作外邦人的師傅，教導他們相信，學習真道。我說的是真話，並不是謊言。","notes":[]},{"n":8,"t":"我願男人無忿怒，無爭論，舉起聖潔的手，隨處禱告；","notes":["或譯：疑惑"]},{"n":9,"t":"又願女人廉恥、自守，以正派衣裳為妝飾，不以編髮、黃金、珍珠，和貴價的衣裳為妝飾，","notes":[]},{"n":10,"t":"只要有善行，這才與自稱是敬神的女人相宜。","notes":[]},{"n":11,"t":"女人要沉靜學道，一味地順服。","notes":[]},{"n":12,"t":"我不許女人講道，也不許她轄管男人，只要沉靜。","notes":[]},{"n":13,"t":"因為先造的是亞當，後造的是夏娃，","notes":[]},{"n":14,"t":"且不是亞當被引誘，乃是女人被引誘，陷在罪裏。","notes":[]},{"n":15,"t":"然而，女人若常存信心、愛心，又聖潔自守，就必在生產上得救。","notes":[]}]},"3":{"heading":"監督的資格","verses":[{"n":1,"t":"「人若想要得監督的職分，就是羨慕善工。」這話是可信的。","notes":[]},{"n":2,"t":"作監督的，必須無可指責，只作一個婦人的丈夫，有節制，自守，端正，樂意接待遠人，善於教導；","notes":[]},{"n":3,"t":"不因酒滋事，不打人，只要溫和，不爭競，不貪財；","notes":[]},{"n":4,"t":"好好管理自己的家，使兒女凡事端莊順服。","notes":["或譯：端端莊莊地使兒女順服"]},{"n":5,"t":"人若不知道管理自己的家，焉能照管神的教會呢？","notes":[]},{"n":6,"t":"初入教的不可作監督，恐怕他自高自大，就落在魔鬼所受的刑罰裏。","notes":[]},{"n":7,"t":"監督也必須在教外有好名聲，恐怕被人毀謗，落在魔鬼的網羅裏。","notes":[]},{"n":8,"t":"作執事的，也是如此：必須端莊，不一口兩舌，不好喝酒，不貪不義之財；","notes":[],"heads":["執事的資格"]},{"n":9,"t":"要存清潔的良心，固守真道的奧祕。","notes":[]},{"n":10,"t":"這等人也要先受試驗，若沒有可責之處，然後叫他們作執事。","notes":[]},{"n":11,"t":"女執事也是如此：必須端莊，不說讒言，有節制，凡事忠心。","notes":["原文是女人"]},{"n":12,"t":"執事只要作一個婦人的丈夫，好好管理兒女和自己的家。","notes":[]},{"n":13,"t":"因為善作執事的，自己就得到美好的地步，並且在基督耶穌裏的真道上大有膽量。","notes":[]},{"n":14,"t":"我指望快到你那裏去，所以先將這些事寫給你。","notes":[],"heads":["敬虔的奧祕"]},{"n":15,"t":"倘若我耽延日久，你也可以知道在神的家中當怎樣行。這家就是永生神的教會，真理的柱石和根基。","notes":[]},{"n":16,"t":"大哉，敬虔的奧祕，無人不以為然！就是神在肉身顯現，被聖靈稱義，被天使看見，被傳於外邦，被世人信服，被接在榮耀裏。","notes":["或譯：在靈性稱義"]}]},"4":{"heading":"預言有人離棄真道","verses":[{"n":1,"t":"聖靈明說，在後來的時候，必有人離棄真道，聽從那引誘人的邪靈和鬼魔的道理。","notes":[]},{"n":2,"t":"這是因為說謊之人的假冒；這等人的良心如同被熱鐵烙慣了一般。","notes":[]},{"n":3,"t":"他們禁止嫁娶，又禁戒食物，就是神所造、叫那信而明白真道的人感謝著領受的。","notes":["或譯：又叫人戒葷"]},{"n":4,"t":"凡神所造的物都是好的，若感謝著領受，就沒有一樣可棄的，","notes":[]},{"n":5,"t":"都因神的道和人的祈求成為聖潔了。","notes":[]},{"n":6,"t":"你若將這些事提醒弟兄們，便是基督耶穌的好執事，在真道的話語和你向來所服從的善道上得了教育。","notes":[],"heads":["基督耶穌的好執事"]},{"n":7,"t":"只是要棄絕那世俗的言語和老婦荒謬的話，在敬虔上操練自己。","notes":[]},{"n":8,"t":"「操練身體，益處還少；惟獨敬虔，凡事都有益處，因有今生和來生的應許。」","notes":[]},{"n":9,"t":"這話是可信的，是十分可佩服的。","notes":[]},{"n":10,"t":"我們勞苦努力，正是為此，因我們的指望在乎永生的神；他是萬人的救主，更是信徒的救主。","notes":[]},{"n":11,"t":"這些事，你要吩咐人，也要教導人。","notes":[]},{"n":12,"t":"不可叫人小看你年輕，總要在言語、行為、愛心、信心、清潔上，都作信徒的榜樣。","notes":[]},{"n":13,"t":"你要以宣讀、勸勉、教導為念，直等到我來。","notes":[]},{"n":14,"t":"你不要輕忽所得的恩賜，就是從前藉著預言、在眾長老按手的時候賜給你的。","notes":[]},{"n":15,"t":"這些事你要殷勤去做，並要在此專心，使眾人看出你的長進來。","notes":[]},{"n":16,"t":"你要謹慎自己和自己的教訓，要在這些事上恆心；因為這樣行，又能救自己，又能救聽你的人。","notes":[]}]},"5":{"heading":"對別人的本分","verses":[{"n":1,"t":"不可嚴責老年人，只要勸他如同父親；勸少年人如同弟兄；","notes":[]},{"n":2,"t":"勸老年婦女如同母親；勸少年婦女如同姊妹；總要清清潔潔的。","notes":[]},{"n":3,"t":"要尊敬那真為寡婦的。","notes":[]},{"n":4,"t":"若寡婦有兒女，或有孫子孫女，便叫他們先在自己家中學著行孝，報答親恩，因為這在神面前是可悅納的。","notes":[]},{"n":5,"t":"那獨居無靠、真為寡婦的，是仰賴神，晝夜不住地祈求禱告。","notes":[]},{"n":6,"t":"但那好宴樂的寡婦正活著的時候也是死的。","notes":[]},{"n":7,"t":"這些事你要囑咐她們，叫她們無可指責。","notes":[]},{"n":8,"t":"人若不看顧親屬，就是背了真道，比不信的人還不好，不看顧自己家裏的人，更是如此。","notes":[]},{"n":9,"t":"寡婦記在冊子上，必須年紀到六十歲，從來只作一個丈夫的妻子，","notes":[]},{"n":10,"t":"又有行善的名聲，就如養育兒女，接待遠人，洗聖徒的腳，救濟遭難的人，竭力行各樣善事。","notes":[]},{"n":11,"t":"至於年輕的寡婦，就可以辭她；因為她們的情慾發動，違背基督的時候就想要嫁人。","notes":[]},{"n":12,"t":"她們被定罪，是因廢棄了當初所許的願；","notes":[]},{"n":13,"t":"並且她們又習慣懶惰，挨家閒遊；不但是懶惰，又說長道短，好管閒事，說些不當說的話。","notes":[]},{"n":14,"t":"所以我願意年輕的寡婦嫁人，生養兒女，治理家務，不給敵人辱罵的把柄。","notes":[]},{"n":15,"t":"因為已經有轉去隨從撒但的。","notes":[]},{"n":16,"t":"信主的婦女，若家中有寡婦，自己就當救濟她們，不可累著教會，好使教會能救濟那真無倚靠的寡婦。","notes":[]},{"n":17,"t":"那善於管理教會的長老，當以為配受加倍的敬奉；那勞苦傳道教導人的，更當如此。","notes":[]},{"n":18,"t":"因為經上說：「牛在場上踹穀的時候，不可籠住牠的嘴」；又說：「工人得工價是應當的。」","notes":[]},{"n":19,"t":"控告長老的呈子，非有兩三個見證就不要收。","notes":[]},{"n":20,"t":"犯罪的人，當在眾人面前責備他，叫其餘的人也可以懼怕。","notes":[]},{"n":21,"t":"我在神和基督耶穌並蒙揀選的天使面前囑咐你：要遵守這些話，不可存成見，行事也不可有偏心。","notes":[]},{"n":22,"t":"給人行按手的禮，不可急促；不要在別人的罪上有分，要保守自己清潔。","notes":[]},{"n":23,"t":"因你胃口不清，屢次患病，再不要照常喝水，可以稍微用點酒。","notes":[]},{"n":24,"t":"有些人的罪是明顯的，如同先到審判案前；有些人的罪是隨後跟了去的。","notes":[]},{"n":25,"t":"這樣，善行也有明顯的，那不明顯的也不能隱藏。","notes":[]}]},"6":{"heading":"假道理和真財富","verses":[{"n":1,"t":"凡在軛下作僕人的，當以自己主人配受十分的恭敬，免得神的名和道理被人褻瀆。","notes":[]},{"n":2,"t":"僕人有信道的主人，不可因為與他是弟兄就輕看他；更要加意服事他；因為得服事之益處的，是信道蒙愛的。你要以此教訓人，勸勉人。","notes":[]},{"n":3,"t":"若有人傳異教，不服從我們主耶穌基督純正的話與那合乎敬虔的道理，","notes":[]},{"n":4,"t":"他是自高自大，一無所知，專好問難，爭辯言詞，從此就生出嫉妒、紛爭、毀謗、妄疑，","notes":[]},{"n":5,"t":"並那壞了心術、失喪真理之人的爭競。他們以敬虔為得利的門路。","notes":[]},{"n":6,"t":"然而，敬虔加上知足的心便是大利了；","notes":[]},{"n":7,"t":"因為我們沒有帶甚麼到世上來，也不能帶甚麼去。","notes":[]},{"n":8,"t":"只要有衣有食，就當知足。","notes":[]},{"n":9,"t":"但那些想要發財的人，就陷在迷惑、落在網羅和許多無知有害的私慾裏，叫人沉在敗壞和滅亡中。","notes":[]},{"n":10,"t":"貪財是萬惡之根。有人貪戀錢財，就被引誘離了真道，用許多愁苦把自己刺透了。","notes":[]},{"n":11,"t":"但你這屬神的人要逃避這些事，追求公義、敬虔、信心、愛心、忍耐、溫柔。","notes":[],"heads":["美好的仗"]},{"n":12,"t":"你要為真道打那美好的仗，持定永生。你為此被召，也在許多見證人面前，已經作了那美好的見證。","notes":[]},{"n":13,"t":"我在叫萬物生活的神面前，並在向本丟‧彼拉多作過那美好見證的基督耶穌面前囑咐你：","notes":[]},{"n":14,"t":"要守這命令，毫不玷污，無可指責，直到我們的主耶穌基督顯現。","notes":[]},{"n":15,"t":"到了日期，那可稱頌、獨有權能的萬王之王、萬主之主，","notes":[]},{"n":16,"t":"就是那獨一不死、住在人不能靠近的光裏，是人未曾看見、也是不能看見的，要將他顯明出來。但願尊貴和永遠的權能都歸給他。阿們！","notes":[]},{"n":17,"t":"你要囑咐那些今世富足的人，不要自高，也不要倚靠無定的錢財；只要倚靠那厚賜百物給我們享受的神。","notes":[]},{"n":18,"t":"又要囑咐他們行善，在好事上富足，甘心施捨，樂意供給人，","notes":["或譯：體貼"]},{"n":19,"t":"為自己積成美好的根基，預備將來，叫他們持定那真正的生命。","notes":[]},{"n":20,"t":"提摩太啊，你要保守所託付你的，躲避世俗的虛談和那敵真道、似是而非的學問。","notes":[]},{"n":21,"t":"已經有人自稱有這學問，就偏離了真道。願恩惠常與你們同在！","notes":[]}]}},"2TI":{"1":{"heading":"問候","verses":[{"n":1,"t":"奉神旨意，照著在基督耶穌裏生命的應許，作基督耶穌使徒的保羅","notes":[]},{"n":2,"t":"寫信給我親愛的兒子提摩太。願恩惠、憐憫、平安從父神和我們主基督耶穌歸與你！","notes":[]},{"n":3,"t":"我感謝神，就是我接續祖先用清潔的良心所事奉的神。祈禱的時候，不住的想念你，","notes":[],"heads":["忠於福音"]},{"n":4,"t":"記念你的眼淚，晝夜切切地想要見你，好叫我滿心快樂。","notes":[]},{"n":5,"t":"想到你心裏無偽之信，這信是先在你外祖母羅以和你母親友妮基心裏的，我深信也在你的心裏。","notes":[]},{"n":6,"t":"為此我提醒你，使你將神藉我按手所給你的恩賜再如火挑旺起來。","notes":[]},{"n":7,"t":"因為神賜給我們，不是膽怯的心，乃是剛強、仁愛、謹守的心。","notes":[]},{"n":8,"t":"你不要以給我們的主作見證為恥，也不要以我這為主被囚的為恥；總要按神的能力，與我為福音同受苦難。","notes":[]},{"n":9,"t":"神救了我們，以聖召召我們，不是按我們的行為，乃是按他的旨意和恩典；這恩典是萬古之先，在基督耶穌裏賜給我們的，","notes":[]},{"n":10,"t":"但如今藉著我們救主基督耶穌的顯現才表明出來了。他已經把死廢去，藉著福音，將不能壞的生命彰顯出來。","notes":[]},{"n":11,"t":"我為這福音奉派作傳道的，作使徒，作師傅。","notes":[]},{"n":12,"t":"為這緣故，我也受這些苦難。然而我不以為恥；因為知道我所信的是誰，也深信他能保全我所交付他的，直到那日。","notes":["或譯：他所交託我的"]},{"n":13,"t":"你從我聽的那純正話語的規模，要用在基督耶穌裏的信心和愛心，常常守著。","notes":[]},{"n":14,"t":"從前所交託你的善道，你要靠著那住在我們裏面的聖靈牢牢地守著。","notes":[]},{"n":15,"t":"凡在亞細亞的人都離棄我，這是你知道的，其中有腓吉路和黑摩其尼。","notes":[]},{"n":16,"t":"願主憐憫阿尼色弗一家的人；因他屢次使我暢快，不以我的鎖鍊為恥，","notes":[]},{"n":17,"t":"反倒在羅馬的時候，殷勤地找我，並且找著了。","notes":[]},{"n":18,"t":"願主使他在那日得主的憐憫。他在以弗所怎樣多多地服事我，是你明明知道的。","notes":[]}]},"2":{"heading":"基督耶穌的精兵","verses":[{"n":1,"t":"我兒啊，你要在基督耶穌的恩典上剛強起來。","notes":[]},{"n":2,"t":"你在許多見證人面前聽見我所教訓的，也要交託那忠心能教導別人的人。","notes":[]},{"n":3,"t":"你要和我同受苦難，好像基督耶穌的精兵。","notes":[]},{"n":4,"t":"凡在軍中當兵的，不將世務纏身，好叫那招他當兵的人喜悅。","notes":[]},{"n":5,"t":"人若在場上比武，非按規矩，就不能得冠冕。","notes":[]},{"n":6,"t":"勞力的農夫理當先得糧食。","notes":[]},{"n":7,"t":"我所說的話，你要思想，因為凡事主必給你聰明。","notes":[]},{"n":8,"t":"你要記念耶穌基督乃是大衛的後裔，他從死裏復活，正合乎我所傳的福音。","notes":[]},{"n":9,"t":"我為這福音受苦難，甚至被捆綁，像犯人一樣。然而神的道卻不被捆綁。","notes":[]},{"n":10,"t":"所以，我為選民凡事忍耐，叫他們也可以得著那在基督耶穌裏的救恩和永遠的榮耀。","notes":[]},{"n":11,"t":"有可信的話說：我們若與基督同死，也必與他同活；","notes":[]},{"n":12,"t":"我們若能忍耐，也必和他一同作王。我們若不認他，他也必不認我們；","notes":[]},{"n":13,"t":"我們縱然失信，他仍是可信的，因為他不能背乎自己。","notes":[]},{"n":14,"t":"你要使眾人回想這些事，在主面前囑咐他們：不可為言語爭辯；這是沒有益處的，只能敗壞聽見的人。","notes":[],"heads":["無愧的工人"]},{"n":15,"t":"你當竭力在神面前得蒙喜悅，作無愧的工人，按著正意分解真理的道。","notes":[]},{"n":16,"t":"但要遠避世俗的虛談，因為這等人必進到更不敬虔的地步。","notes":[]},{"n":17,"t":"他們的話如同毒瘡，越爛越大；其中有許米乃和腓理徒，","notes":[]},{"n":18,"t":"他們偏離了真道，說復活的事已過，就敗壞好些人的信心。","notes":[]},{"n":19,"t":"然而，神堅固的根基立住了；上面有這印記說：「主認識誰是他的人」；又說：「凡稱呼主名的人總要離開不義。」","notes":[]},{"n":20,"t":"在大戶人家，不但有金器銀器，也有木器瓦器；有作為貴重的，有作為卑賤的。","notes":[]},{"n":21,"t":"人若自潔，脫離卑賤的事，就必作貴重的器皿，成為聖潔，合乎主用，預備行各樣的善事。","notes":[]},{"n":22,"t":"你要逃避少年的私慾，同那清心禱告主的人追求公義、信德、仁愛、和平。","notes":[]},{"n":23,"t":"惟有那愚拙無學問的辯論，總要棄絕，因為知道這等事是起爭競的。","notes":[]},{"n":24,"t":"然而主的僕人不可爭競，只要溫溫和和地待眾人，善於教導，存心忍耐，","notes":[]},{"n":25,"t":"用溫柔勸戒那抵擋的人；或者神給他們悔改的心，可以明白真道，","notes":[]},{"n":26,"t":"叫他們這已經被魔鬼任意擄去的，可以醒悟，脫離他的網羅。","notes":[]}]},"3":{"heading":"末世的人性","verses":[{"n":1,"t":"你該知道，末世必有危險的日子來到。","notes":[]},{"n":2,"t":"因為那時，人要專顧自己，貪愛錢財，自誇，狂傲，謗讟，違背父母，忘恩負義，心不聖潔，","notes":[]},{"n":3,"t":"無親情，不解怨，好說讒言，不能自約，性情凶暴，不愛良善，","notes":[]},{"n":4,"t":"賣主賣友，任意妄為，自高自大，愛宴樂，不愛神，","notes":[]},{"n":5,"t":"有敬虔的外貌，卻背了敬虔的實意；這等人你要躲開。","notes":[]},{"n":6,"t":"那偷進人家、牢籠無知婦女的，正是這等人。這些婦女擔負罪惡，被各樣的私慾引誘，","notes":[]},{"n":7,"t":"常常學習，終久不能明白真道。","notes":[]},{"n":8,"t":"從前雅尼和佯庇怎樣敵擋摩西，這等人也怎樣敵擋真道。他們的心地壞了，在真道上是可廢棄的。","notes":[]},{"n":9,"t":"然而他們不能再這樣敵擋；因為他們的愚昧必在眾人面前顯露出來，像那二人一樣。","notes":[]},{"n":10,"t":"但你已經服從了我的教訓、品行、志向、信心、寬容、愛心、忍耐，","notes":[],"heads":["對提摩太的最後指示"]},{"n":11,"t":"以及我在安提阿、以哥念、路司得所遭遇的逼迫、苦難。我所忍受是何等的逼迫；但從這一切苦難中，主都把我救出來了。","notes":[]},{"n":12,"t":"不但如此，凡立志在基督耶穌裏敬虔度日的也都要受逼迫。","notes":[]},{"n":13,"t":"只是作惡的和迷惑人的，必越久越惡，他欺哄人，也被人欺哄。","notes":[]},{"n":14,"t":"但你所學習的，所確信的，要存在心裏；因為你知道是跟誰學的，","notes":[]},{"n":15,"t":"並且知道你是從小明白聖經，這聖經能使你因信基督耶穌，有得救的智慧。","notes":[]},{"n":16,"t":"聖經都是神所默示的，於教訓、督責、使人歸正、教導人學義都是有益的，","notes":["或譯：凡神所默示的聖經"]},{"n":17,"t":"叫屬神的人得以完全，預備行各樣的善事。","notes":[]}]},"4":{"heading":"私事的囑咐","verses":[{"n":1,"t":"我在神面前，並在將來審判活人死人的基督耶穌面前，憑著他的顯現和他的國度囑咐你：","notes":[]},{"n":2,"t":"務要傳道，無論得時不得時，總要專心，並用百般的忍耐、各樣的教訓責備人，警戒人，勸勉人。","notes":[]},{"n":3,"t":"因為時候要到，人必厭煩純正的道理，耳朵發癢，就隨從自己的情慾增添好些師傅，","notes":[]},{"n":4,"t":"並且掩耳不聽真道，偏向荒謬的言語。","notes":[]},{"n":5,"t":"你卻要凡事謹慎，忍受苦難，做傳道的工夫，盡你的職分。","notes":[]},{"n":6,"t":"我現在被澆奠，我離世的時候到了。","notes":[]},{"n":7,"t":"那美好的仗我已經打過了，當跑的路我已經跑盡了，所信的道我已經守住了。","notes":[]},{"n":8,"t":"從此以後，有公義的冠冕為我存留，就是按著公義審判的主到了那日要賜給我的；不但賜給我，也賜給凡愛慕他顯現的人。","notes":[]},{"n":9,"t":"你要趕緊地到我這裏來。","notes":[]},{"n":10,"t":"因為底馬貪愛現今的世界，就離棄我往帖撒羅尼迦去了；革勒士往加拉太去；提多往撻馬太去；","notes":[]},{"n":11,"t":"獨有路加在我這裏。你來的時候，要把馬可帶來，因為他在傳道的事上於我有益處。","notes":["或譯：服事我"]},{"n":12,"t":"我已經打發推基古往以弗所去。","notes":[]},{"n":13,"t":"我在特羅亞留於加布的那件外衣，你來的時候可以帶來，那些書也要帶來，更要緊的是那些皮卷。","notes":[]},{"n":14,"t":"銅匠亞歷山大多多地害我；主必照他所行的報應他。","notes":[]},{"n":15,"t":"你也要防備他，因為他極力敵擋了我們的話。","notes":[]},{"n":16,"t":"我初次申訴，沒有人前來幫助，竟都離棄我；但願這罪不歸與他們。","notes":[]},{"n":17,"t":"惟有主站在我旁邊，加給我力量，使福音被我盡都傳明，叫外邦人都聽見；我也從獅子口裏被救出來。","notes":[]},{"n":18,"t":"主必救我脫離諸般的凶惡，也必救我進他的天國。願榮耀歸給他，直到永永遠遠。阿們。","notes":[]},{"n":19,"t":"問百基拉、亞居拉，和阿尼色弗一家的人安。","notes":[],"heads":["問候與祝福"]},{"n":20,"t":"以拉都在哥林多住下了。特羅非摩病了，我就留他在米利都。","notes":[]},{"n":21,"t":"你要趕緊在冬天以前到我這裏來。有友布羅、布田、利奴、革老底亞，和眾弟兄都問你安。","notes":[]},{"n":22,"t":"願主與你的靈同在！願恩惠常與你們同在！","notes":[]}]}},"TIT":{"1":{"heading":"問候","verses":[{"n":1,"t":"神的僕人，耶穌基督的使徒保羅，憑著神選民的信心與敬虔真理的知識，","notes":[]},{"n":2,"t":"盼望那無謊言的神在萬古之先所應許的永生，","notes":[]},{"n":3,"t":"到了日期，藉著傳揚的工夫把他的道顯明了；這傳揚的責任是按著神－我們救主的命令交託了我。","notes":[]},{"n":4,"t":"現在寫信給提多，就是照著我們共信之道作我真兒子的。願恩惠、平安從父神和我們的救主基督耶穌歸與你！","notes":[]},{"n":5,"t":"我從前留你在克里特，是要你將那沒有辦完的事都辦整齊了，又照我所吩咐你的，在各城設立長老。","notes":[],"heads":["提多在克里特的工作"]},{"n":6,"t":"若有無可指責的人，只作一個婦人的丈夫，兒女也是信主的，沒有人告他們是放蕩不服約束的，就可以設立。","notes":[]},{"n":7,"t":"監督既是神的管家，必須無可指責，不任性，不暴躁，不因酒滋事，不打人，不貪無義之財；","notes":[]},{"n":8,"t":"樂意接待遠人，好善，莊重，公平，聖潔自持；","notes":[]},{"n":9,"t":"堅守所教真實的道理，就能將純正的教訓勸化人，又能把爭辯的人駁倒了。","notes":[]},{"n":10,"t":"因為有許多人不服約束，說虛空話欺哄人；那奉割禮的更是這樣。","notes":[]},{"n":11,"t":"這些人的口總要堵住。他們因貪不義之財，將不該教導的教導人，敗壞人的全家。","notes":[]},{"n":12,"t":"有克里特人中的一個本地先知說：「克里特人常說謊話，乃是惡獸，又饞又懶。」","notes":[]},{"n":13,"t":"這個見證是真的。所以，你要嚴嚴地責備他們，使他們在真道上純全無疵，","notes":[]},{"n":14,"t":"不聽猶太人荒謬的言語和離棄真道之人的誡命。","notes":[]},{"n":15,"t":"在潔淨的人，凡物都潔淨；在污穢不信的人，甚麼都不潔淨，連心地和天良也都污穢了。","notes":[]},{"n":16,"t":"他們說是認識神，行事卻和他相背；本是可憎惡的，是悖逆的，在各樣善事上是可廢棄的。","notes":[]}]},"2":{"heading":"純正的道理","verses":[{"n":1,"t":"但你所講的總要合乎那純正的道理。","notes":[]},{"n":2,"t":"勸老年人要有節制、端莊、自守，在信心、愛心、忍耐上都要純全無疵。","notes":[]},{"n":3,"t":"又勸老年婦人，舉止行動要恭敬，不說讒言，不給酒作奴僕，用善道教訓人，","notes":[]},{"n":4,"t":"好指教少年婦人，愛丈夫，愛兒女，","notes":[]},{"n":5,"t":"謹守，貞潔，料理家務，待人有恩，順服自己的丈夫，免得神的道理被毀謗。","notes":[]},{"n":6,"t":"又勸少年人要謹守。","notes":[]},{"n":7,"t":"你自己凡事要顯出善行的榜樣；在教訓上要正直、端莊，","notes":[]},{"n":8,"t":"言語純全，無可指責，叫那反對的人，既無處可說我們的不是，便自覺羞愧。","notes":[]},{"n":9,"t":"勸僕人要順服自己的主人，凡事討他的喜歡，不可頂撞他，","notes":[]},{"n":10,"t":"不可私拿東西，要顯為忠誠，以致凡事尊榮我們救主－神的道。","notes":[]},{"n":11,"t":"因為神救眾人的恩典已經顯明出來，","notes":[]},{"n":12,"t":"教訓我們除去不敬虔的心和世俗的情慾，在今世自守、公義、敬虔度日，","notes":[]},{"n":13,"t":"等候所盼望的福，並等候至大的神和我們救主耶穌基督的榮耀顯現。","notes":["或譯：神－我們"]},{"n":14,"t":"他為我們捨了自己，要贖我們脫離一切罪惡，又潔淨我們，特作自己的子民，熱心為善。","notes":[]},{"n":15,"t":"這些事你要講明，勸戒人，用各等權柄責備人；不可叫人輕看你。","notes":[]}]},"3":{"heading":"熱心行善","verses":[{"n":1,"t":"你要提醒眾人，叫他們順服作官的、掌權的，遵他的命，預備行各樣的善事。","notes":[]},{"n":2,"t":"不要毀謗，不要爭競，總要和平，向眾人大顯溫柔。","notes":[]},{"n":3,"t":"我們從前也是無知、悖逆、受迷惑、服事各樣私慾，和宴樂，常存惡毒嫉妒的心，是可恨的，又是彼此相恨。","notes":["或譯：陰毒"]},{"n":4,"t":"但到了神－我們救主的恩慈和他向人所施的慈愛顯明的時候，","notes":[]},{"n":5,"t":"他便救了我們；並不是因我們自己所行的義，乃是照他的憐憫，藉著重生的洗和聖靈的更新。","notes":[]},{"n":6,"t":"聖靈就是神藉著耶穌基督－我們救主厚厚澆灌在我們身上的，","notes":[]},{"n":7,"t":"好叫我們因他的恩得稱為義，可以憑著永生的盼望成為後嗣。","notes":["或譯：可以憑著盼望承受永生"]},{"n":8,"t":"這話是可信的。我也願你把這些事切切實實地講明，使那些已信神的人留心做正經事業。這都是美事，並且與人有益。","notes":["或譯：留心行善"]},{"n":9,"t":"要遠避無知的辯論和家譜的空談，以及紛爭，並因律法而起的爭競，因為這都是虛妄無益的。","notes":[]},{"n":10,"t":"分門結黨的人，警戒過一兩次，就要棄絕他。","notes":[]},{"n":11,"t":"因為知道這等人已經背道，犯了罪，自己明知不是，還是去做。","notes":[]},{"n":12,"t":"我打發亞提馬或是推基古到你那裏去的時候，你要趕緊往尼哥坡里去見我，因為我已經定意在那裏過冬。","notes":[],"heads":["個人的指示和問安"]},{"n":13,"t":"你要趕緊給律師西納和亞波羅送行，叫他們沒有缺乏。","notes":[]},{"n":14,"t":"並且我們的人要學習正經事業，預備所需用的，免得不結果子。","notes":["或譯：要學習行善"]},{"n":15,"t":"同我在一處的人都問你安。請代問那些因有信心愛我們的人安。願恩惠常與你們眾人同在！","notes":[]}]}},"PHM":{"1":{"heading":"問候","verses":[{"n":1,"t":"為基督耶穌被囚的保羅，同兄弟提摩太寫信給我們所親愛的同工腓利門，","notes":[]},{"n":2,"t":"和妹子亞腓亞並與我們同當兵的亞基布，以及在你家的教會。","notes":[]},{"n":3,"t":"願恩惠、平安從神我們的父和主耶穌基督歸與你們！","notes":[]},{"n":4,"t":"我禱告的時候提到你，常為你感謝我的神；","notes":[],"heads":["腓利門的愛心和信心"]},{"n":5,"t":"因聽說你的愛心並你向主耶穌和眾聖徒的信心。","notes":["或譯：因聽說你向主耶穌和眾聖徒有愛心有信心"]},{"n":6,"t":"願你與人所同有的信心顯出功效，使人知道你們各樣善事都是為基督做的。","notes":[]},{"n":7,"t":"兄弟啊，我為你的愛心，大有快樂，大得安慰，因眾聖徒的心從你得了暢快。","notes":[]},{"n":8,"t":"我雖然靠著基督能放膽吩咐你合宜的事，","notes":[],"heads":["保羅為阿尼西謀請求"]},{"n":9,"t":"然而像我這有年紀的保羅，現在又是為基督耶穌被囚的，寧可憑著愛心求你，","notes":[]},{"n":10,"t":"就是為我在捆鎖中所生的兒子阿尼西謀求你。","notes":["就是有益處的意思"]},{"n":11,"t":"他從前與你沒有益處，但如今與你我都有益處。","notes":[]},{"n":12,"t":"我現在打發他親自回你那裏去；他是我心上的人。","notes":[]},{"n":13,"t":"我本來有意將他留下，在我為福音所受的捆鎖中替你伺候我。","notes":[]},{"n":14,"t":"但不知道你的意思，我就不願意這樣行，叫你的善行不是出於勉強，乃是出於甘心。","notes":[]},{"n":15,"t":"他暫時離開你，或者是叫你永遠得著他，","notes":[]},{"n":16,"t":"不再是奴僕，乃是高過奴僕，是親愛的兄弟。在我實在是如此，何況在你呢！這也不拘是按肉體說，是按主說。","notes":[]},{"n":17,"t":"你若以我為同伴，就收納他，如同收納我一樣。","notes":[]},{"n":18,"t":"他若虧負你，或欠你甚麼，都歸在我的帳上；","notes":[]},{"n":19,"t":"我必償還，這是我－保羅親筆寫的。我並不用對你說，連你自己也是虧欠於我。","notes":[]},{"n":20,"t":"兄弟啊，望你使我在主裏因你得快樂，並望你使我的心在基督裏得暢快。","notes":["或譯：益處"]},{"n":21,"t":"我寫信給你，深信你必順服，知道你所要行的必過於我所說的。","notes":[]},{"n":22,"t":"此外你還要給我預備住處；因為我盼望藉著你們的禱告，必蒙恩到你們那裏去。","notes":[]},{"n":23,"t":"為基督耶穌與我同坐監的以巴弗問你安。","notes":[],"heads":["最後的問安"]},{"n":24,"t":"與我同工的馬可、亞里達古、底馬、路加也都問你安。","notes":[]},{"n":25,"t":"願我們主耶穌基督的恩常在你的心裏。阿們！","notes":[]}]}},"HEB":{"1":{"heading":"神藉著他兒子說話","verses":[{"n":1,"t":"神既在古時藉著眾先知多次多方地曉諭列祖，","notes":[]},{"n":2,"t":"就在這末世藉著他兒子曉諭我們；又早已立他為承受萬有的，也曾藉著他創造諸世界。","notes":[]},{"n":3,"t":"他是神榮耀所發的光輝，是神本體的真像，常用他權能的命令托住萬有。他洗淨了人的罪，就坐在高天至大者的右邊。","notes":[]},{"n":4,"t":"他所承受的名，既比天使的名更尊貴，就遠超過天使。","notes":[]},{"n":5,"t":"所有的天使，神從來對哪一個說：你是我的兒子，我今日生你？又指著哪一個說：我要作他的父，他要作我的子？","notes":[],"heads":["兒子遠超過天使"]},{"n":6,"t":"再者，神使長子到世上來的時候，就說：神的使者都要拜他。","notes":["或譯：神再使長子到世上來的時候"]},{"n":7,"t":"論到使者，又說：神以風為使者，以火焰為僕役；","notes":[]},{"n":8,"t":"論到子卻說：神啊，你的寶座是永永遠遠的；你的國權是正直的。","notes":[]},{"n":9,"t":"你喜愛公義，恨惡罪惡；所以神，就是你的神，用喜樂油膏你，勝過膏你的同伴；","notes":[]},{"n":10,"t":"又說：主啊，你起初立了地的根基；天也是你手所造的。","notes":[]},{"n":11,"t":"天地都要滅沒，你卻要長存。天地都要像衣服漸漸舊了；","notes":[]},{"n":12,"t":"你要將天地捲起來，像一件外衣，天地就都改變了。惟有你永不改變；你的年數沒有窮盡。","notes":[]},{"n":13,"t":"所有的天使，神從來對哪一個說：你坐在我的右邊，等我使你仇敵作你的腳凳？","notes":[]},{"n":14,"t":"天使豈不都是服役的靈、奉差遣為那將要承受救恩的人效力嗎？","notes":[]}]},"2":{"heading":"這麼大的救恩","verses":[{"n":1,"t":"所以，我們當越發鄭重所聽見的道理，恐怕我們隨流失去。","notes":[]},{"n":2,"t":"那藉著天使所傳的話既是確定的；凡干犯悖逆的都受了該受的報應。","notes":[]},{"n":3,"t":"我們若忽略這麼大的救恩，怎能逃罪呢？這救恩起先是主親自講的，後來是聽見的人給我們證實了。","notes":[]},{"n":4,"t":"神又按自己的旨意，用神蹟、奇事和百般的異能，並聖靈的恩賜，同他們作見證。","notes":[]},{"n":5,"t":"我們所說將來的世界，神原沒有交給天使管轄。","notes":[],"heads":["救恩的元帥"]},{"n":6,"t":"但有人在經上某處證明說：人算甚麼，你竟顧念他？世人算甚麼，你竟眷顧他？","notes":[]},{"n":7,"t":"你叫他比天使微小一點，賜他榮耀尊貴為冠冕，並將你手所造的都派他管理，","notes":["或譯：你叫他暫時比天使小"]},{"n":8,"t":"叫萬物都服在他的腳下。既叫萬物都服他，就沒有剩下一樣不服他的。只是如今我們還不見萬物都服他。","notes":[]},{"n":9,"t":"惟獨見那成為比天使小一點的耶穌；因為受死的苦，就得了尊貴榮耀為冠冕，叫他因著神的恩，為人人嘗了死味。","notes":["或譯：惟獨見耶穌暫時比天使小"]},{"n":10,"t":"原來那為萬物所屬、為萬物所本的，要領許多的兒子進榮耀裏去，使救他們的元帥，因受苦難得以完全，本是合宜的。","notes":[]},{"n":11,"t":"因那使人成聖的和那些得以成聖的，都是出於一。所以，他稱他們為弟兄也不以為恥，","notes":[]},{"n":12,"t":"說：我要將你的名傳與我的弟兄，在會中我要頌揚你；","notes":[]},{"n":13,"t":"又說：我要倚賴他；又說：看哪，我與神所給我的兒女。","notes":[]},{"n":14,"t":"兒女既同有血肉之體，他也照樣親自成了血肉之體，特要藉著死敗壞那掌死權的，就是魔鬼，","notes":[]},{"n":15,"t":"並要釋放那些一生因怕死而為奴僕的人。","notes":[]},{"n":16,"t":"他並不救拔天使，乃是救拔亞伯拉罕的後裔。","notes":[]},{"n":17,"t":"所以，他凡事該與他的弟兄相同，為要在神的事上成為慈悲忠信的大祭司，為百姓的罪獻上挽回祭。","notes":[]},{"n":18,"t":"他自己既然被試探而受苦，就能搭救被試探的人。","notes":[]}]},"3":{"heading":"耶穌超越摩西","verses":[{"n":1,"t":"同蒙天召的聖潔弟兄啊，你們應當思想我們所認為使者、為大祭司的耶穌。","notes":[]},{"n":2,"t":"他為那設立他的盡忠，如同摩西在神的全家盡忠一樣。","notes":[]},{"n":3,"t":"他比摩西算是更配多得榮耀，好像建造房屋的比房屋更尊榮；","notes":[]},{"n":4,"t":"因為房屋都必有人建造，但建造萬物的就是神。","notes":[]},{"n":5,"t":"摩西為僕人，在神的全家誠然盡忠，為要證明將來必傳說的事。","notes":[]},{"n":6,"t":"但基督為兒子，治理神的家；我們若將可誇的盼望和膽量堅持到底，便是他的家了。","notes":[]},{"n":7,"t":"聖靈有話說：你們今日若聽他的話，","notes":[],"heads":["神子民的安息"]},{"n":8,"t":"就不可硬著心，像在曠野惹他發怒、試探他的時候一樣。","notes":[]},{"n":9,"t":"在那裏，你們的祖宗試我探我，並且觀看我的作為有四十年之久。","notes":[]},{"n":10,"t":"所以，我厭煩那世代的人，說：他們心裏常常迷糊，竟不曉得我的作為！","notes":[]},{"n":11,"t":"我就在怒中起誓說：他們斷不可進入我的安息。","notes":[]},{"n":12,"t":"弟兄們，你們要謹慎，免得你們中間或有人存著不信的惡心，把永生神離棄了。","notes":[]},{"n":13,"t":"總要趁著還有今日，天天彼此相勸，免得你們中間有人被罪迷惑，心裏就剛硬了。","notes":[]},{"n":14,"t":"我們若將起初確實的信心堅持到底，就在基督裏有分了。","notes":[]},{"n":15,"t":"經上說：「你們今日若聽他的話，就不可硬著心，像惹他發怒的日子一樣。」","notes":[]},{"n":16,"t":"那時，聽見他話惹他發怒的是誰呢？豈不是跟著摩西從埃及出來的眾人嗎？","notes":[]},{"n":17,"t":"神四十年之久，又厭煩誰呢？豈不是那些犯罪、屍首倒在曠野的人嗎？","notes":[]},{"n":18,"t":"又向誰起誓，不容他們進入他的安息呢？豈不是向那些不信從的人嗎？","notes":[]},{"n":19,"t":"這樣看來，他們不能進入安息是因為不信的緣故了。","notes":[]}]},"4":{"heading":"大祭司耶穌","verses":[{"n":1,"t":"我們既蒙留下，有進入他安息的應許，就當畏懼，免得我們中間或有人似乎是趕不上了。","notes":["原文是你們"]},{"n":2,"t":"因為有福音傳給我們，像傳給他們一樣；只是所聽見的道與他們無益，因為他們沒有信心與所聽見的道調和。","notes":[]},{"n":3,"t":"但我們已經相信的人得以進入那安息，正如神所說：「我在怒中起誓說：『他們斷不可進入我的安息！』」其實造物之工，從創世以來已經成全了。","notes":[]},{"n":4,"t":"論到第七日，有一處說：「到第七日，神就歇了他一切的工。」","notes":[]},{"n":5,"t":"又有一處說：「他們斷不可進入我的安息！」","notes":[]},{"n":6,"t":"既有必進安息的人，那先前聽見福音的，因為不信從，不得進去。","notes":[]},{"n":7,"t":"所以過了多年，就在大衛的書上，又限定一日，如以上所引的說：「你們今日若聽他的話，就不可硬著心。」","notes":[]},{"n":8,"t":"若是約書亞已叫他們享了安息，後來神就不再提別的日子了。","notes":[]},{"n":9,"t":"這樣看來，必另有一安息日的安息為神的子民存留。","notes":[]},{"n":10,"t":"因為那進入安息的，乃是歇了自己的工，正如神歇了他的工一樣。","notes":[]},{"n":11,"t":"所以，我們務必竭力進入那安息，免得有人學那不信從的樣子跌倒了。","notes":[]},{"n":12,"t":"神的道是活潑的，是有功效的，比一切兩刃的劍更快，甚至魂與靈，骨節與骨髓，都能刺入、剖開，連心中的思念和主意都能辨明。","notes":[]},{"n":13,"t":"並且被造的沒有一樣在他面前不顯然的；原來萬物在那與我們有關係的主眼前，都是赤露敞開的。","notes":[]},{"n":14,"t":"我們既然有一位已經升入高天尊榮的大祭司，就是神的兒子耶穌，便當持定所承認的道。","notes":[]},{"n":15,"t":"因我們的大祭司並非不能體恤我們的軟弱。他也曾凡事受過試探，與我們一樣，只是他沒有犯罪。","notes":[]},{"n":16,"t":"所以，我們只管坦然無懼地來到施恩的寶座前，為要得憐恤，蒙恩惠，作隨時的幫助。","notes":[]}]},"5":{"heading":"警戒叛道的人","verses":[{"n":1,"t":"凡從人間挑選的大祭司，是奉派替人辦理屬神的事，為要獻上禮物和贖罪祭。","notes":["或譯：要為罪獻上禮物和祭物"]},{"n":2,"t":"他能體諒那愚蒙的和失迷的人，因為他自己也是被軟弱所困。","notes":[]},{"n":3,"t":"故此，他理當為百姓和自己獻祭贖罪。","notes":[]},{"n":4,"t":"這大祭司的尊榮，沒有人自取。惟要蒙神所召，像亞倫一樣。","notes":[]},{"n":5,"t":"如此，基督也不是自取榮耀作大祭司，乃是在乎向他說「你是我的兒子，我今日生你」的那一位；","notes":[]},{"n":6,"t":"就如經上又有一處說：「你是照著麥基洗德的等次永遠為祭司。」","notes":[]},{"n":7,"t":"基督在肉體的時候，既大聲哀哭，流淚禱告，懇求那能救他免死的主，就因他的虔誠蒙了應允。","notes":[]},{"n":8,"t":"他雖然為兒子，還是因所受的苦難學了順從。","notes":[]},{"n":9,"t":"他既得以完全，就為凡順從他的人成了永遠得救的根源，","notes":[]},{"n":10,"t":"並蒙神照著麥基洗德的等次稱他為大祭司。","notes":[]},{"n":11,"t":"論到麥基洗德，我們有好些話，並且難以解明，因為你們聽不進去。","notes":[]},{"n":12,"t":"看你們學習的工夫，本該作師傅，誰知還得有人將神聖言小學的開端另教導你們，並且成了那必須吃奶、不能吃乾糧的人。","notes":[]},{"n":13,"t":"凡只能吃奶的都不熟練仁義的道理，因為他是嬰孩；","notes":[]},{"n":14,"t":"惟獨長大成人的才能吃乾糧；他們的心竅習練得通達，就能分辨好歹了。","notes":[]}]},"6":{"heading":"神確切的應許","verses":[{"n":1,"t":"所以，我們應當離開基督道理的開端，竭力進到完全的地步，不必再立根基，就如那懊悔死行、信靠神、","notes":[]},{"n":2,"t":"各樣洗禮、按手之禮、死人復活，以及永遠審判各等教訓。","notes":[]},{"n":3,"t":"神若許我們，我們必如此行。","notes":[]},{"n":4,"t":"論到那些已經蒙了光照、嘗過天恩的滋味、又於聖靈有分，","notes":[]},{"n":5,"t":"並嘗過神善道的滋味、覺悟來世權能的人，","notes":[]},{"n":6,"t":"若是離棄道理，就不能叫他們重新懊悔了。因為他們把神的兒子重釘十字架，明明地羞辱他。","notes":[]},{"n":7,"t":"就如一塊田地，吃過屢次下的雨水，生長菜蔬，合乎耕種的人用，就從神得福；","notes":[]},{"n":8,"t":"若長荊棘和蒺藜，必被廢棄，近於咒詛，結局就是焚燒。","notes":[]},{"n":9,"t":"親愛的弟兄們，我們雖是這樣說，卻深信你們的行為強過這些，而且近乎得救。","notes":[]},{"n":10,"t":"因為神並非不公義，竟忘記你們所做的工和你們為他名所顯的愛心，就是先前伺候聖徒，如今還是伺候。","notes":[]},{"n":11,"t":"我們願你們各人都顯出這樣的殷勤，使你們有滿足的指望，一直到底。","notes":[]},{"n":12,"t":"並且不懈怠，總要效法那些憑信心和忍耐承受應許的人。","notes":[]},{"n":13,"t":"當初神應許亞伯拉罕的時候，因為沒有比自己更大可以指著起誓的，就指著自己起誓，說：","notes":[]},{"n":14,"t":"「論福，我必賜大福給你；論子孫，我必叫你的子孫多起來。」","notes":[]},{"n":15,"t":"這樣，亞伯拉罕既恆久忍耐，就得了所應許的。","notes":[]},{"n":16,"t":"人都是指著比自己大的起誓，並且以起誓為實據，了結各樣的爭論。","notes":[]},{"n":17,"t":"照樣，神願意為那承受應許的人格外顯明他的旨意是不更改的，就起誓為證。","notes":[]},{"n":18,"t":"藉這兩件不更改的事，神決不能說謊，好叫我們這逃往避難所、持定擺在我們前頭指望的人可以大得勉勵。","notes":[]},{"n":19,"t":"我們有這指望，如同靈魂的錨，又堅固又牢靠，且通入幔內。","notes":[]},{"n":20,"t":"作先鋒的耶穌，既照著麥基洗德的等次成了永遠的大祭司，就為我們進入幔內。","notes":[]}]},"7":{"heading":"麥基洗德的祭司等次","verses":[{"n":1,"t":"這麥基洗德就是撒冷王，又是至高神的祭司，本是長遠為祭司的。他當亞伯拉罕殺敗諸王回來的時候，就迎接他，給他祝福。","notes":[]},{"n":2,"t":"亞伯拉罕也將自己所得來的，取十分之一給他。他頭一個名翻出來就是仁義王，他又名撒冷王，就是平安王的意思。","notes":[]},{"n":3,"t":"他無父，無母，無族譜，無生之始，無命之終，乃是與神的兒子相似。","notes":[]},{"n":4,"t":"你們想一想，先祖亞伯拉罕將自己所擄來上等之物取十分之一給他，這人是何等尊貴呢！","notes":[]},{"n":5,"t":"那得祭司職任的利未子孫，領命照例向百姓取十分之一，這百姓是自己的弟兄，雖是從亞伯拉罕身中生的，還是照例取十分之一。","notes":["原文是腰"]},{"n":6,"t":"獨有麥基洗德，不與他們同譜，倒收納亞伯拉罕的十分之一，為那蒙應許的亞伯拉罕祝福。","notes":[]},{"n":7,"t":"從來位分大的給位分小的祝福，這是駁不倒的理。","notes":[]},{"n":8,"t":"在這裏收十分之一的都是必死的人；但在那裏收十分之一的，有為他作見證的說，他是活的；","notes":[]},{"n":9,"t":"並且可說那受十分之一的利未，也是藉著亞伯拉罕納了十分之一。","notes":[]},{"n":10,"t":"因為麥基洗德迎接亞伯拉罕的時候，利未已經在他先祖的身中。","notes":["原文是腰"]},{"n":11,"t":"從前百姓在利未人祭司職任以下受律法，倘若藉這職任能得完全，又何用另外興起一位祭司，照麥基洗德的等次，不照亞倫的等次呢？","notes":[]},{"n":12,"t":"祭司的職任既已更改，律法也必須更改。","notes":[]},{"n":13,"t":"因為這話所指的人本屬別的支派，那支派裏從來沒有一人伺候祭壇。","notes":[]},{"n":14,"t":"我們的主分明是從猶大出來的；但這支派，摩西並沒有提到祭司。","notes":[]},{"n":15,"t":"倘若照麥基洗德的樣式，另外興起一位祭司來，我的話更是顯而易見的了。","notes":[]},{"n":16,"t":"他成為祭司，並不是照屬肉體的條例，乃是照無窮之生命的大能。","notes":["原文是不能毀壞"]},{"n":17,"t":"因為有給他作見證的說：「你是照著麥基洗德的等次永遠為祭司。」","notes":[]},{"n":18,"t":"先前的條例，因軟弱無益，所以廢掉了，","notes":[]},{"n":19,"t":"（律法原來一無所成）就引進了更美的指望；靠這指望，我們便可以進到神面前。","notes":[]},{"n":20,"t":"再者，耶穌為祭司，並不是不起誓立的。","notes":[]},{"n":21,"t":"至於那些祭司，原不是起誓立的，只有耶穌是起誓立的；因為那立他的對他說：「主起了誓，決不後悔，你是永遠為祭司。」","notes":[]},{"n":22,"t":"既是起誓立的，耶穌就作了更美之約的中保。","notes":[]},{"n":23,"t":"那些成為祭司的，數目本來多，是因為有死阻隔，不能長久。","notes":[]},{"n":24,"t":"這位既是永遠常存的，他祭司的職任就長久不更換。","notes":[]},{"n":25,"t":"凡靠著他進到神面前的人，他都能拯救到底；因為他是長遠活著，替他們祈求。","notes":[]},{"n":26,"t":"像這樣聖潔、無邪惡、無玷污、遠離罪人、高過諸天的大祭司，原是與我們合宜的。","notes":[]},{"n":27,"t":"他不像那些大祭司，每日必須先為自己的罪，後為百姓的罪獻祭；因為他只一次將自己獻上，就把這事成全了。","notes":[]},{"n":28,"t":"律法本是立軟弱的人為大祭司；但在律法以後起誓的話，是立兒子為大祭司，乃是成全到永遠的。","notes":[]}]},"8":{"heading":"更美之約的大祭司","verses":[{"n":1,"t":"我們所講的事，其中第一要緊的，就是我們有這樣的大祭司，已經坐在天上至大者寶座的右邊，","notes":[]},{"n":2,"t":"在聖所，就是真帳幕裏，作執事；這帳幕是主所支的，不是人所支的。","notes":[]},{"n":3,"t":"凡大祭司都是為獻禮物和祭物設立的，所以這位大祭司也必須有所獻的。","notes":[]},{"n":4,"t":"他若在地上，必不得為祭司，因為已經有照律法獻禮物的祭司。","notes":[]},{"n":5,"t":"他們供奉的事本是天上事的形狀和影像，正如摩西將要造帳幕的時候，蒙神警戒他，說：「你要謹慎，作各樣的物件都要照著在山上指示你的樣式。」","notes":[]},{"n":6,"t":"如今耶穌所得的職任是更美的，正如他作更美之約的中保；這約原是憑更美之應許立的。","notes":[]},{"n":7,"t":"那前約若沒有瑕疵，就無處尋求後約了。","notes":[]},{"n":8,"t":"所以主指責他的百姓說：日子將到，我要與以色列家和猶大家另立新約，","notes":["或譯：所以主指前約的缺欠說"]},{"n":9,"t":"不像我拉著他們祖宗的手，領他們出埃及的時候，與他們所立的約。因為他們不恆心守我的約，我也不理他們。這是主說的。","notes":[]},{"n":10,"t":"主又說：那些日子以後，我與以色列家所立的約乃是這樣：我要將我的律法放在他們裏面，寫在他們心上；我要作他們的神；他們要作我的子民。","notes":[]},{"n":11,"t":"他們不用各人教導自己的鄉鄰和自己的弟兄，說：你該認識主；因為他們從最小的到至大的，都必認識我。","notes":[]},{"n":12,"t":"我要寬恕他們的不義，不再記念他們的罪愆。","notes":[]},{"n":13,"t":"既說新約，就以前約為舊了；但那漸舊漸衰的，就必快歸無有了。","notes":[]}]},"9":{"heading":"地上和天上的聖所","verses":[{"n":1,"t":"原來前約有禮拜的條例和屬世界的聖幕。","notes":[]},{"n":2,"t":"因為有預備的帳幕，頭一層叫作聖所，裏面有燈臺、桌子，和陳設餅。","notes":[]},{"n":3,"t":"第二幔子後又有一層帳幕，叫作至聖所，","notes":[]},{"n":4,"t":"有金香爐，有包金的約櫃，櫃裏有盛嗎哪的金罐和亞倫發過芽的杖，並兩塊約版；","notes":["爐：或譯壇"]},{"n":5,"t":"櫃上面有榮耀基路伯的影罩著施恩座。這幾件我現在不能一一細說。","notes":["施恩：原文是蔽罪"]},{"n":6,"t":"這些物件既如此預備齊了，眾祭司就常進頭一層帳幕，行拜神的禮。","notes":[]},{"n":7,"t":"至於第二層帳幕，惟有大祭司一年一次獨自進去，沒有不帶著血為自己和百姓的過錯獻上。","notes":[]},{"n":8,"t":"聖靈用此指明，頭一層帳幕仍存的時候，進入至聖所的路還未顯明。","notes":[]},{"n":9,"t":"那頭一層帳幕作現今的一個表樣，所獻的禮物和祭物，就著良心說，都不能叫禮拜的人得以完全。","notes":[]},{"n":10,"t":"這些事，連那飲食和諸般洗濯的規矩，都不過是屬肉體的條例，命定到振興的時候為止。","notes":[]},{"n":11,"t":"但現在基督已經來到，作了將來美事的大祭司，經過那更大更全備的帳幕，不是人手所造，也不是屬乎這世界的；","notes":[]},{"n":12,"t":"並且不用山羊和牛犢的血，乃用自己的血，只一次進入聖所，成了永遠贖罪的事。","notes":[]},{"n":13,"t":"若山羊和公牛的血，並母牛犢的灰，灑在不潔的人身上，尚且叫人成聖，身體潔淨，","notes":[]},{"n":14,"t":"何況基督藉著永遠的靈，將自己無瑕無疵獻給神，他的血豈不更能洗淨你們的心，除去你們的死行，使你們事奉那永生神嗎？","notes":["原文是良心"]},{"n":15,"t":"為此，他作了新約的中保，既然受死贖了人在前約之時所犯的罪過，便叫蒙召之人得著所應許永遠的產業。","notes":[]},{"n":16,"t":"凡有遺命必須等到留遺命的人死了；","notes":["遺命：原文與約字同"]},{"n":17,"t":"因為人死了，遺命才有效力，若留遺命的尚在，那遺命還有用處嗎？","notes":[]},{"n":18,"t":"所以，前約也不是不用血立的；","notes":[]},{"n":19,"t":"因為摩西當日照著律法將各樣誡命傳給眾百姓，就拿朱紅色絨和牛膝草，把牛犢山羊的血和水灑在書上，又灑在眾百姓身上，說：","notes":[]},{"n":20,"t":"「這血就是神與你們立約的憑據。」","notes":[]},{"n":21,"t":"他又照樣把血灑在帳幕和各樣器皿上。","notes":[]},{"n":22,"t":"按著律法，凡物差不多都是用血潔淨的；若不流血，罪就不得赦免了。","notes":[]},{"n":23,"t":"照著天上樣式做的物件必須用這些祭物去潔淨；但那天上的本物自然當用更美的祭物去潔淨。","notes":[],"heads":["基督獻己為祭除掉了罪"]},{"n":24,"t":"因為基督並不是進了人手所造的聖所（這不過是真聖所的影像），乃是進了天堂，如今為我們顯在神面前；","notes":[]},{"n":25,"t":"也不是多次將自己獻上，像那大祭司每年帶著牛羊的血進入聖所，","notes":["牛羊的血：原文作不是自己的血"]},{"n":26,"t":"如果這樣，他從創世以來，就必多次受苦了。但如今在這末世顯現一次，把自己獻為祭，好除掉罪。","notes":[]},{"n":27,"t":"按著定命，人人都有一死，死後且有審判。","notes":[]},{"n":28,"t":"像這樣，基督既然一次被獻，擔當了多人的罪，將來要向那等候他的人第二次顯現，並與罪無關，乃是為拯救他們。","notes":[]}]},"10":{"heading":"勸勉和警告","verses":[{"n":1,"t":"律法既是將來美事的影兒，不是本物的真像，總不能藉著每年常獻一樣的祭物叫那近前來的人得以完全。","notes":[]},{"n":2,"t":"若不然，獻祭的事豈不早已止住了嗎？因為禮拜的人，良心既被潔淨，就不再覺得有罪了。","notes":[]},{"n":3,"t":"但這些祭物是叫人每年想起罪來；","notes":[]},{"n":4,"t":"因為公牛和山羊的血，斷不能除罪。","notes":[]},{"n":5,"t":"所以基督到世上來的時候，就說：神啊，祭物和禮物是你不願意的；你曾給我預備了身體。","notes":[]},{"n":6,"t":"燔祭和贖罪祭是你不喜歡的。","notes":[]},{"n":7,"t":"那時我說：神啊，我來了，為要照你的旨意行；我的事在經卷上已經記載了。","notes":[]},{"n":8,"t":"以上說：「祭物和禮物，燔祭和贖罪祭，是你不願意的，也是你不喜歡的（這都是按著律法獻的）」；","notes":[]},{"n":9,"t":"後又說：「我來了為要照你的旨意行」；可見他是除去在先的，為要立定在後的。","notes":[]},{"n":10,"t":"我們憑這旨意，靠耶穌基督，只一次獻上他的身體，就得以成聖。","notes":[]},{"n":11,"t":"凡祭司天天站著事奉神，屢次獻上一樣的祭物，這祭物永不能除罪。","notes":[]},{"n":12,"t":"但基督獻了一次永遠的贖罪祭，就在神的右邊坐下了。","notes":[]},{"n":13,"t":"從此，等候他仇敵成了他的腳凳。","notes":[]},{"n":14,"t":"因為他一次獻祭，便叫那得以成聖的人永遠完全。","notes":[]},{"n":15,"t":"聖靈也對我們作見證；因為他既已說過：","notes":[]},{"n":16,"t":"主說：那些日子以後，我與他們所立的約乃是這樣：我要將我的律法寫在他們心上，又要放在他們的裏面。","notes":[]},{"n":17,"t":"以後就說：我不再記念他們的罪愆和他們的過犯。","notes":[]},{"n":18,"t":"這些罪過既已赦免，就不用再為罪獻祭了。","notes":[]},{"n":19,"t":"弟兄們，我們既因耶穌的血得以坦然進入至聖所，","notes":[]},{"n":20,"t":"是藉著他給我們開了一條又新又活的路，從幔子經過，這幔子就是他的身體。","notes":[]},{"n":21,"t":"又有一位大祭司治理神的家，","notes":[]},{"n":22,"t":"並我們心中天良的虧欠已經灑去，身體用清水洗淨了，就當存著誠心和充足的信心來到神面前；","notes":[]},{"n":23,"t":"也要堅守我們所承認的指望，不致搖動，因為那應許我們的是信實的。","notes":[]},{"n":24,"t":"又要彼此相顧，激發愛心，勉勵行善。","notes":[]},{"n":25,"t":"你們不可停止聚會，好像那些停止慣了的人，倒要彼此勸勉，既知道那日子臨近，就更當如此。","notes":["原文是看見"]},{"n":26,"t":"因為我們得知真道以後，若故意犯罪，贖罪的祭就再沒有了；","notes":[]},{"n":27,"t":"惟有戰懼等候審判和那燒滅眾敵人的烈火。","notes":[]},{"n":28,"t":"人干犯摩西的律法，憑兩三個見證人，尚且不得憐恤而死，","notes":[]},{"n":29,"t":"何況人踐踏神的兒子，將那使他成聖之約的血當作平常，又褻慢施恩的聖靈，你們想，他要受的刑罰該怎樣加重呢！","notes":[]},{"n":30,"t":"因為我們知道誰說：「伸冤在我，我必報應」；又說：「主要審判他的百姓。」","notes":[]},{"n":31,"t":"落在永生神的手裏，真是可怕的！","notes":[]},{"n":32,"t":"你們要追念往日，蒙了光照以後所忍受大爭戰的各樣苦難：","notes":[]},{"n":33,"t":"一面被毀謗，遭患難，成了戲景，叫眾人觀看；一面陪伴那些受這樣苦難的人。","notes":[]},{"n":34,"t":"因為你們體恤了那些被捆鎖的人，並且你們的家業被人搶去，也甘心忍受，知道自己有更美長存的家業。","notes":[]},{"n":35,"t":"所以，你們不可丟棄勇敢的心；存這樣的心必得大賞賜。","notes":[]},{"n":36,"t":"你們必須忍耐，使你們行完了神的旨意，就可以得著所應許的。","notes":[]},{"n":37,"t":"因為還有一點點時候，那要來的就來，並不遲延；","notes":[]},{"n":38,"t":"只是義人必因信得生。他若退後，我心裏就不喜歡他。","notes":["有古卷：我的義人"]},{"n":39,"t":"我們卻不是退後入沉淪的那等人，乃是有信心以致靈魂得救的人。","notes":[]}]},"11":{"heading":"論信","verses":[{"n":1,"t":"信就是所望之事的實底，是未見之事的確據。","notes":[]},{"n":2,"t":"古人在這信上得了美好的證據。","notes":[]},{"n":3,"t":"我們因著信，就知道諸世界是藉神話造成的；這樣，所看見的，並不是從顯然之物造出來的。","notes":[]},{"n":4,"t":"亞伯因著信，獻祭與神，比該隱所獻的更美，因此便得了稱義的見證，就是神指他禮物作的見證。他雖然死了，卻因這信，仍舊說話。","notes":[]},{"n":5,"t":"以諾因著信，被接去，不至於見死，人也找不著他，因為神已經把他接去了；只是他被接去以先，已經得了神喜悅他的明證。","notes":[]},{"n":6,"t":"人非有信，就不能得神的喜悅；因為到神面前來的人必須信有神，且信他賞賜那尋求他的人。","notes":[]},{"n":7,"t":"挪亞因著信，既蒙神指示他未見的事，動了敬畏的心，預備了一隻方舟，使他全家得救。因此就定了那世代的罪，自己也承受了那從信而來的義。","notes":[]},{"n":8,"t":"亞伯拉罕因著信，蒙召的時候就遵命出去，往將來要得為業的地方去；出去的時候，還不知往哪裏去。","notes":[]},{"n":9,"t":"他因著信，就在所應許之地作客，好像在異地居住帳棚，與那同蒙一個應許的以撒、雅各一樣。","notes":[]},{"n":10,"t":"因為他等候那座有根基的城，就是神所經營所建造的。","notes":[]},{"n":11,"t":"因著信，連撒拉自己，雖然過了生育的歲數，還能懷孕，因她以為那應許她的是可信的。","notes":[]},{"n":12,"t":"所以從一個彷彿已死的人就生出子孫，如同天上的星那樣眾多，海邊的沙那樣無數。","notes":[]},{"n":13,"t":"這些人都是存著信心死的，並沒有得著所應許的；卻從遠處望見，且歡喜迎接，又承認自己在世上是客旅，是寄居的。","notes":[]},{"n":14,"t":"說這樣話的人是表明自己要找一個家鄉。","notes":[]},{"n":15,"t":"他們若想念所離開的家鄉，還有可以回去的機會。","notes":[]},{"n":16,"t":"他們卻羨慕一個更美的家鄉，就是在天上的。所以神被稱為他們的神，並不以為恥，因為他已經給他們預備了一座城。","notes":[]},{"n":17,"t":"亞伯拉罕因著信，被試驗的時候，就把以撒獻上；這便是那歡喜領受應許的，將自己獨生的兒子獻上。","notes":[]},{"n":18,"t":"論到這兒子，曾有話說：「從以撒生的才要稱為你的後裔。」","notes":[]},{"n":19,"t":"他以為神還能叫人從死裏復活；他也彷彿從死中得回他的兒子來。","notes":[]},{"n":20,"t":"以撒因著信，就指著將來的事給雅各、以掃祝福。","notes":[]},{"n":21,"t":"雅各因著信，臨死的時候，給約瑟的兩個兒子各自祝福，扶著杖頭敬拜神。","notes":[]},{"n":22,"t":"約瑟因著信，臨終的時候，提到以色列族將來要出埃及，並為自己的骸骨留下遺命。","notes":[]},{"n":23,"t":"摩西生下來，他的父母見他是個俊美的孩子，就因著信，把他藏了三個月，並不怕王命。","notes":[]},{"n":24,"t":"摩西因著信，長大了就不肯稱為法老女兒之子。","notes":[]},{"n":25,"t":"他寧可和神的百姓同受苦害，也不願暫時享受罪中之樂。","notes":[]},{"n":26,"t":"他看為基督受的凌辱比埃及的財物更寶貴，因他想望所要得的賞賜。","notes":[]},{"n":27,"t":"他因著信，就離開埃及，不怕王怒；因為他恆心忍耐，如同看見那不能看見的主。","notes":[]},{"n":28,"t":"他因著信，就守逾越節，行灑血的禮，免得那滅長子的臨近以色列人。","notes":["或譯：立"]},{"n":29,"t":"他們因著信，過紅海如行乾地；埃及人試著要過去，就被吞滅了。","notes":[]},{"n":30,"t":"以色列人因著信，圍繞耶利哥城七日，城牆就倒塌了。","notes":[]},{"n":31,"t":"妓女喇合因著信，曾和和平平地接待探子，就不與那些不順從的人一同滅亡。","notes":[]},{"n":32,"t":"我又何必再說呢？若要一一細說，基甸、巴拉、參孫、耶弗他、大衛、撒母耳，和眾先知的事，時候就不夠了。","notes":[]},{"n":33,"t":"他們因著信，制伏了敵國，行了公義，得了應許，堵了獅子的口，","notes":[]},{"n":34,"t":"滅了烈火的猛勢，脫了刀劍的鋒刃；軟弱變為剛強，爭戰顯出勇敢，打退外邦的全軍。","notes":[]},{"n":35,"t":"有婦人得自己的死人復活。又有人忍受嚴刑，不肯苟且得釋放，為要得著更美的復活。","notes":["原文是贖"]},{"n":36,"t":"又有人忍受戲弄、鞭打、捆鎖、監禁、各等的磨煉，","notes":[]},{"n":37,"t":"被石頭打死，被鋸鋸死，受試探，被刀殺，披著綿羊、山羊的皮各處奔跑，受窮乏、患難、苦害，","notes":[]},{"n":38,"t":"在曠野、山嶺、山洞、地穴，飄流無定，本是世界不配有的人。","notes":[]},{"n":39,"t":"這些人都是因信得了美好的證據，卻仍未得著所應許的；","notes":[]},{"n":40,"t":"因為神給我們預備了更美的事，叫他們若不與我們同得，就不能完全。","notes":[]}]},"12":{"heading":"主的管教","verses":[{"n":1,"t":"我們既有這許多的見證人，如同雲彩圍著我們，就當放下各樣的重擔，脫去容易纏累我們的罪，存心忍耐，奔那擺在我們前頭的路程，","notes":[]},{"n":2,"t":"仰望為我們信心創始成終的耶穌。他因那擺在前面的喜樂，就輕看羞辱，忍受了十字架的苦難，便坐在神寶座的右邊。","notes":["或譯：仰望那將真道創始成終的耶穌"]},{"n":3,"t":"那忍受罪人這樣頂撞的，你們要思想，免得疲倦灰心。","notes":[]},{"n":4,"t":"你們與罪惡相爭，還沒有抵擋到流血的地步。","notes":[]},{"n":5,"t":"你們又忘了那勸你們如同勸兒子的話，說：我兒，你不可輕看主的管教，被他責備的時候也不可灰心；","notes":[]},{"n":6,"t":"因為主所愛的，他必管教，又鞭打凡所收納的兒子。","notes":[]},{"n":7,"t":"你們所忍受的，是神管教你們，待你們如同待兒子。焉有兒子不被父親管教的呢？","notes":[]},{"n":8,"t":"管教原是眾子所共受的。你們若不受管教，就是私子，不是兒子了。","notes":[]},{"n":9,"t":"再者，我們曾有生身的父管教我們，我們尚且敬重他，何況萬靈的父，我們豈不更當順服他得生嗎？","notes":[]},{"n":10,"t":"生身的父都是暫隨己意管教我們；惟有萬靈的父管教我們，是要我們得益處，使我們在他的聖潔上有分。","notes":[]},{"n":11,"t":"凡管教的事，當時不覺得快樂，反覺得愁苦；後來卻為那經練過的人結出平安的果子，就是義。","notes":[]},{"n":12,"t":"所以，你們要把下垂的手、發酸的腿挺起來；","notes":[]},{"n":13,"t":"也要為自己的腳，把道路修直了，使瘸子不致歪腳，反得痊癒。","notes":["或譯：差路"]},{"n":14,"t":"你們要追求與眾人和睦，並要追求聖潔；非聖潔沒有人能見主。","notes":[],"heads":["警告棄絕神恩典的人"]},{"n":15,"t":"又要謹慎，恐怕有人失了神的恩；恐怕有毒根生出來擾亂你們，因此叫眾人沾染污穢；","notes":[]},{"n":16,"t":"恐怕有淫亂的，有貪戀世俗如以掃的，他因一點食物把自己長子的名分賣了。","notes":[]},{"n":17,"t":"後來想要承受父所祝的福，竟被棄絕，雖然號哭切求，卻得不著門路使他父親的心意回轉。這是你們知道的。","notes":[]},{"n":18,"t":"你們原不是來到那能摸的山；此山有火焰、密雲、黑暗、暴風、","notes":[]},{"n":19,"t":"角聲與說話的聲音。那些聽見這聲音的，都求不要再向他們說話；","notes":[]},{"n":20,"t":"因為他們當不起所命他們的話，說：「靠近這山的，即便是走獸，也要用石頭打死。」","notes":[]},{"n":21,"t":"所見的極其可怕，甚至摩西說：「我甚是恐懼戰兢。」","notes":[]},{"n":22,"t":"你們乃是來到錫安山，永生神的城邑，就是天上的耶路撒冷。那裏有千萬的天使，","notes":[]},{"n":23,"t":"有名錄在天上諸長子之會所共聚的總會，有審判眾人的神和被成全之義人的靈魂，","notes":[]},{"n":24,"t":"並新約的中保耶穌，以及所灑的血；這血所說的比亞伯的血所說的更美。","notes":[]},{"n":25,"t":"你們總要謹慎，不可棄絕那向你們說話的。因為，那些棄絕在地上警戒他們的尚且不能逃罪，何況我們違背那從天上警戒我們的呢？","notes":[]},{"n":26,"t":"當時他的聲音震動了地，但如今他應許說：「再一次我不單要震動地，還要震動天。」","notes":[]},{"n":27,"t":"這再一次的話，是指明被震動的，就是受造之物都要挪去，使那不被震動的常存。","notes":[]},{"n":28,"t":"所以我們既得了不能震動的國，就當感恩，照神所喜悅的，用虔誠、敬畏的心事奉神。","notes":[]},{"n":29,"t":"因為我們的神乃是烈火。","notes":[]}]},"13":{"heading":"蒙神悅納的服務","verses":[{"n":1,"t":"你們務要常存弟兄相愛的心。","notes":[]},{"n":2,"t":"不可忘記用愛心接待客旅；因為曾有接待客旅的，不知不覺就接待了天使。","notes":[]},{"n":3,"t":"你們要記念被捆綁的人，好像與他們同受捆綁；也要記念遭苦害的人，想到自己也在肉身之內。","notes":[]},{"n":4,"t":"婚姻，人人都當尊重，床也不可污穢；因為苟合行淫的人，神必要審判。","notes":[]},{"n":5,"t":"你們存心不可貪愛錢財，要以自己所有的為足；因為主曾說：「我總不撇下你，也不丟棄你。」","notes":[]},{"n":6,"t":"所以我們可以放膽說：主是幫助我的，我必不懼怕；人能把我怎麼樣呢？","notes":[]},{"n":7,"t":"從前引導你們、傳神之道給你們的人，你們要想念他們，效法他們的信心，留心看他們為人的結局。","notes":[]},{"n":8,"t":"耶穌基督昨日、今日、一直到永遠，是一樣的。","notes":[]},{"n":9,"t":"你們不要被那諸般怪異的教訓勾引了去；因為人心靠恩得堅固才是好的，並不是靠飲食。那在飲食上專心的從來沒有得著益處。","notes":[]},{"n":10,"t":"我們有一祭壇，上面的祭物是那些在帳幕中供職的人不可同吃的。","notes":[]},{"n":11,"t":"原來牲畜的血被大祭司帶入聖所作贖罪祭；牲畜的身子被燒在營外。","notes":[]},{"n":12,"t":"所以，耶穌要用自己的血叫百姓成聖，也就在城門外受苦。","notes":[]},{"n":13,"t":"這樣，我們也當出到營外，就了他去，忍受他所受的凌辱。","notes":[]},{"n":14,"t":"我們在這裏本沒有常存的城，乃是尋求那將來的城。","notes":[]},{"n":15,"t":"我們應當靠著耶穌，常常以頌讚為祭獻給神，這就是那承認主名之人嘴唇的果子。","notes":[]},{"n":16,"t":"只是不可忘記行善和捐輸的事，因為這樣的祭是神所喜悅的。","notes":[]},{"n":17,"t":"你們要依從那些引導你們的，且要順服；因他們為你們的靈魂時刻警醒，好像那將來交帳的人。你們要使他們交的時候有快樂，不致憂愁；若憂愁就與你們無益了。","notes":[]},{"n":18,"t":"請你們為我們禱告，因我們自覺良心無虧，願意凡事按正道而行。","notes":[]},{"n":19,"t":"我更求你們為我禱告，使我快些回到你們那裏去。","notes":[]},{"n":20,"t":"但願賜平安的神，就是那憑永約之血、使群羊的大牧人－我主耶穌從死裏復活的神，","notes":[],"heads":["祝福和問安"]},{"n":21,"t":"在各樣善事上成全你們，叫你們遵行他的旨意；又藉著耶穌基督在你們心裏行他所喜悅的事。願榮耀歸給他，直到永永遠遠。阿們！","notes":[]},{"n":22,"t":"弟兄們，我略略寫信給你們，望你們聽我勸勉的話。","notes":[]},{"n":23,"t":"你們該知道，我們的兄弟提摩太已經釋放了；他若快來，我必同他去見你們。","notes":[]},{"n":24,"t":"請你們問引導你們的諸位和眾聖徒安。從意大利來的人也問你們安。","notes":[]},{"n":25,"t":"願恩惠常與你們眾人同在。阿們！","notes":[]}]}},"JAS":{"1":{"heading":"問候","verses":[{"n":1,"t":"作神和主耶穌基督僕人的雅各請散住十二個支派之人的安。","notes":[]},{"n":2,"t":"我的弟兄們，你們落在百般試煉中，都要以為大喜樂；","notes":[],"heads":["信心和智慧"]},{"n":3,"t":"因為知道你們的信心經過試驗，就生忍耐。","notes":[]},{"n":4,"t":"但忍耐也當成功，使你們成全、完備，毫無缺欠。","notes":[]},{"n":5,"t":"你們中間若有缺少智慧的，應當求那厚賜與眾人、也不斥責人的神，主就必賜給他。","notes":[]},{"n":6,"t":"只要憑著信心求，一點不疑惑；因為那疑惑的人，就像海中的波浪，被風吹動翻騰。","notes":[]},{"n":7,"t":"這樣的人不要想從主那裏得甚麼。","notes":[]},{"n":8,"t":"心懷二意的人，在他一切所行的路上都沒有定見。","notes":[]},{"n":9,"t":"卑微的弟兄升高，就該喜樂；","notes":[],"heads":["貧窮和富有"]},{"n":10,"t":"富足的降卑，也該如此；因為他必要過去，如同草上的花一樣。","notes":[]},{"n":11,"t":"太陽出來，熱風颳起，草就枯乾，花也凋謝，美容就消沒了；那富足的人，在他所行的事上也要這樣衰殘。","notes":[]},{"n":12,"t":"忍受試探的人是有福的，因為他經過試驗以後，必得生命的冠冕；這是主應許給那些愛他之人的。","notes":[],"heads":["考驗和試探"]},{"n":13,"t":"人被試探，不可說：「我是被神試探」；因為神不能被惡試探，他也不試探人。","notes":[]},{"n":14,"t":"但各人被試探，乃是被自己的私慾牽引誘惑的。","notes":[]},{"n":15,"t":"私慾既懷了胎，就生出罪來；罪既長成，就生出死來。","notes":[]},{"n":16,"t":"我親愛的弟兄們，不要看錯了。","notes":[]},{"n":17,"t":"各樣美善的恩賜和各樣全備的賞賜都是從上頭來的，從眾光之父那裏降下來的；在他並沒有改變，也沒有轉動的影兒。","notes":[]},{"n":18,"t":"他按自己的旨意，用真道生了我們，叫我們在他所造的萬物中好像初熟的果子。","notes":[]},{"n":19,"t":"我親愛的弟兄們，這是你們所知道的。但你們各人要快快地聽，慢慢地說，慢慢地動怒，","notes":[],"heads":["聽道和行道"]},{"n":20,"t":"因為人的怒氣並不成就神的義。","notes":[]},{"n":21,"t":"所以，你們要脫去一切的污穢和盈餘的邪惡，存溫柔的心領受那所栽種的道，就是能救你們靈魂的道。","notes":[]},{"n":22,"t":"只是你們要行道，不要單單聽道，自己欺哄自己。","notes":[]},{"n":23,"t":"因為聽道而不行道的，就像人對著鏡子看自己本來的面目，","notes":[]},{"n":24,"t":"看見，走後，隨即忘了他的相貌如何。","notes":[]},{"n":25,"t":"惟有詳細察看那全備、使人自由之律法的，並且時常如此，這人既不是聽了就忘，乃是實在行出來，就在他所行的事上必然得福。","notes":[]},{"n":26,"t":"若有人自以為虔誠，卻不勒住他的舌頭，反欺哄自己的心，這人的虔誠是虛的。","notes":[]},{"n":27,"t":"在神我們的父面前，那清潔沒有玷污的虔誠，就是看顧在患難中的孤兒寡婦，並且保守自己不沾染世俗。","notes":[]}]},"2":{"heading":"警告偏私","verses":[{"n":1,"t":"我的弟兄們，你們信奉我們榮耀的主耶穌基督，便不可按著外貌待人。","notes":[]},{"n":2,"t":"若有一個人帶著金戒指，穿著華美衣服，進你們的會堂去；又有一個窮人穿著骯髒衣服也進去；","notes":[]},{"n":3,"t":"你們就重看那穿華美衣服的人，說：「請坐在這好位上」；又對那窮人說：「你站在那裏」，或「坐在我腳凳下邊。」","notes":[]},{"n":4,"t":"這豈不是你們偏心待人，用惡意斷定人嗎？","notes":[]},{"n":5,"t":"我親愛的弟兄們，請聽，神豈不是揀選了世上的貧窮人，叫他們在信上富足，並承受他所應許給那些愛他之人的國嗎？","notes":[]},{"n":6,"t":"你們反倒羞辱貧窮人。那富足人豈不是欺壓你們、拉你們到公堂去嗎？","notes":[]},{"n":7,"t":"他們不是褻瀆你們所敬奉的尊名嗎？","notes":["所敬奉：或譯被稱"]},{"n":8,"t":"經上記著說：「要愛人如己。」你們若全守這至尊的律法才是好的。","notes":[]},{"n":9,"t":"但你們若按外貌待人，便是犯罪，被律法定為犯法的。","notes":[]},{"n":10,"t":"因為凡遵守全律法的，只在一條上跌倒，他就是犯了眾條。","notes":[]},{"n":11,"t":"原來那說「不可姦淫」的，也說「不可殺人」；你就是不姦淫，卻殺人，仍是成了犯律法的。","notes":[]},{"n":12,"t":"你們既然要按使人自由的律法受審判，就該照這律法說話行事。","notes":[]},{"n":13,"t":"因為那不憐憫人的，也要受無憐憫的審判；憐憫原是向審判誇勝。","notes":[]},{"n":14,"t":"我的弟兄們，若有人說自己有信心，卻沒有行為，有甚麼益處呢？這信心能救他嗎？","notes":[],"heads":["信心和行為"]},{"n":15,"t":"若是弟兄或是姊妹，赤身露體，又缺了日用的飲食；","notes":[]},{"n":16,"t":"你們中間有人對他們說：「平平安安地去吧！願你們穿得暖，吃得飽」，卻不給他們身體所需用的，這有甚麼益處呢？","notes":[]},{"n":17,"t":"這樣，信心若沒有行為就是死的。","notes":[]},{"n":18,"t":"必有人說：「你有信心，我有行為；你將你沒有行為的信心指給我看，我便藉著我的行為，將我的信心指給你看。」","notes":[]},{"n":19,"t":"你信神只有一位，你信的不錯；鬼魔也信，卻是戰驚。","notes":[]},{"n":20,"t":"虛浮的人哪，你願意知道沒有行為的信心是死的嗎？","notes":[]},{"n":21,"t":"我們的祖宗亞伯拉罕把他兒子以撒獻在壇上，豈不是因行為稱義嗎？","notes":[]},{"n":22,"t":"可見，信心是與他的行為並行，而且信心因著行為才得成全。","notes":[]},{"n":23,"t":"這就應驗經上所說：「亞伯拉罕信神，這就算為他的義。」他又得稱為神的朋友。","notes":[]},{"n":24,"t":"這樣看來，人稱義是因著行為，不是單因著信。","notes":[]},{"n":25,"t":"妓女喇合接待使者，又放他們從別的路上出去，不也是一樣因行為稱義嗎？","notes":[]},{"n":26,"t":"身體沒有靈魂是死的，信心沒有行為也是死的。","notes":[]}]},"3":{"heading":"論舌頭","verses":[{"n":1,"t":"我的弟兄們，不要多人作師傅，因為曉得我們要受更重的判斷。","notes":[]},{"n":2,"t":"原來我們在許多事上都有過失；若有人在話語上沒有過失，他就是完全人，也能勒住自己的全身。","notes":[]},{"n":3,"t":"我們若把嚼環放在馬嘴裏，叫牠順服，就能調動牠的全身。","notes":[]},{"n":4,"t":"看哪，船隻雖然甚大，又被大風催逼，只用小小的舵，就隨著掌舵的意思轉動。","notes":[]},{"n":5,"t":"這樣，舌頭在百體裏也是最小的，卻能說大話。看哪，最小的火能點著最大的樹林。","notes":[]},{"n":6,"t":"舌頭就是火，在我們百體中，舌頭是個罪惡的世界，能污穢全身，也能把生命的輪子點起來，並且是從地獄裏點著的。","notes":[]},{"n":7,"t":"各類的走獸、飛禽、昆蟲、水族，本來都可以制伏，也已經被人制伏了；","notes":[]},{"n":8,"t":"惟獨舌頭沒有人能制伏，是不止息的惡物，滿了害死人的毒氣。","notes":[]},{"n":9,"t":"我們用舌頭頌讚那為主、為父的，又用舌頭咒詛那照著神形像被造的人。","notes":[]},{"n":10,"t":"頌讚和咒詛從一個口裏出來！我的弟兄們，這是不應當的！","notes":[]},{"n":11,"t":"泉源從一個眼裏能發出甜苦兩樣的水嗎？","notes":[]},{"n":12,"t":"我的弟兄們，無花果樹能生橄欖嗎？葡萄樹能結無花果嗎？鹹水裏也不能發出甜水來。","notes":[]},{"n":13,"t":"你們中間誰是有智慧有見識的呢？他就當在智慧的溫柔上顯出他的善行來。","notes":[],"heads":["論從上頭來的智慧"]},{"n":14,"t":"你們心裏若懷著苦毒的嫉妒和紛爭，就不可自誇，也不可說謊話抵擋真道。","notes":[]},{"n":15,"t":"這樣的智慧不是從上頭來的，乃是屬地的，屬情慾的，屬鬼魔的。","notes":[]},{"n":16,"t":"在何處有嫉妒、紛爭，就在何處有擾亂和各樣的壞事。","notes":[]},{"n":17,"t":"惟獨從上頭來的智慧，先是清潔，後是和平，溫良柔順，滿有憐憫，多結善果，沒有偏見，沒有假冒。","notes":[]},{"n":18,"t":"並且使人和平的，是用和平所栽種的義果。","notes":[]}]},"4":{"heading":"不可與世俗為友","verses":[{"n":1,"t":"你們中間的爭戰鬥毆是從哪裏來的呢？不是從你們百體中戰鬥之私慾來的嗎？","notes":[]},{"n":2,"t":"你們貪戀，還是得不著；你們殺害嫉妒，又鬥毆爭戰，也不能得。你們得不著，是因為你們不求。","notes":[]},{"n":3,"t":"你們求也得不著，是因為你們妄求，要浪費在你們的宴樂中。","notes":[]},{"n":4,"t":"你們這些淫亂的人哪，豈不知與世俗為友就是與神為敵嗎？所以凡想要與世俗為友的，就是與神為敵了。","notes":["原文是淫婦"]},{"n":5,"t":"你們想經上所說是徒然的嗎？神所賜、住在我們裏面的靈，是戀愛至於嫉妒嗎？","notes":[]},{"n":6,"t":"但他賜更多的恩典，所以經上說：神阻擋驕傲的人，賜恩給謙卑的人。","notes":[]},{"n":7,"t":"故此，你們要順服神。務要抵擋魔鬼，魔鬼就必離開你們逃跑了。","notes":[]},{"n":8,"t":"你們親近神，神就必親近你們。有罪的人哪，要潔淨你們的手！心懷二意的人哪，要清潔你們的心！","notes":[]},{"n":9,"t":"你們要愁苦、悲哀、哭泣，將喜笑變作悲哀，歡樂變作愁悶。","notes":[]},{"n":10,"t":"務要在主面前自卑，主就必叫你們升高。","notes":[]},{"n":11,"t":"弟兄們，你們不可彼此批評。人若批評弟兄，論斷弟兄，就是批評律法，論斷律法。你若論斷律法，就不是遵行律法，乃是判斷人的。","notes":[],"heads":["不可論斷弟兄"]},{"n":12,"t":"設立律法和判斷人的，只有一位，就是那能救人也能滅人的。你是誰，竟敢論斷別人呢？","notes":[]},{"n":13,"t":"嗐！你們有話說：「今天明天我們要往某城裏去，在那裏住一年，做買賣得利。」","notes":[],"heads":["警戒自誇"]},{"n":14,"t":"其實明天如何，你們還不知道。你們的生命是甚麼呢？你們原來是一片雲霧，出現少時就不見了。","notes":[]},{"n":15,"t":"你們只當說：「主若願意，我們就可以活著，也可以做這事，或做那事。」","notes":[]},{"n":16,"t":"現今你們竟以張狂誇口；凡這樣誇口都是惡的。","notes":[]},{"n":17,"t":"人若知道行善，卻不去行，這就是他的罪了。","notes":[]}]},"5":{"heading":"警告富足的人","verses":[{"n":1,"t":"嗐！你們這些富足人哪，應當哭泣、號咷，因為將有苦難臨到你們身上。","notes":[]},{"n":2,"t":"你們的財物壞了，衣服也被蟲子咬了。","notes":[]},{"n":3,"t":"你們的金銀都長了銹；那銹要證明你們的不是，又要吃你們的肉，如同火燒。你們在這末世只知積攢錢財。","notes":[]},{"n":4,"t":"工人給你們收割莊稼，你們虧欠他們的工錢，這工錢有聲音呼叫，並且那收割之人的冤聲已經入了萬軍之主的耳了。","notes":[]},{"n":5,"t":"你們在世上享美福，好宴樂，當宰殺的日子竟嬌養你們的心。","notes":[]},{"n":6,"t":"你們定了義人的罪，把他殺害，他也不抵擋你們。","notes":[]},{"n":7,"t":"弟兄們哪，你們要忍耐，直到主來。看哪，農夫忍耐等候地裏寶貴的出產，直到得了秋雨春雨。","notes":[],"heads":["忍耐和禱告"]},{"n":8,"t":"你們也當忍耐，堅固你們的心，因為主來的日子近了。","notes":[]},{"n":9,"t":"弟兄們，你們不要彼此埋怨，免得受審判。看哪，審判的主站在門前了。","notes":[]},{"n":10,"t":"弟兄們，你們要把那先前奉主名說話的眾先知當作能受苦能忍耐的榜樣。","notes":[]},{"n":11,"t":"那先前忍耐的人，我們稱他們是有福的。你們聽見過約伯的忍耐，也知道主給他的結局，明顯主是滿心憐憫，大有慈悲。","notes":[]},{"n":12,"t":"我的弟兄們，最要緊的是不可起誓；不可指著天起誓，也不可指著地起誓，無論何誓都不可起。你們說話，是，就說是；不是，就說不是，免得你們落在審判之下。","notes":[]},{"n":13,"t":"你們中間有受苦的呢，他就該禱告；有喜樂的呢，他就該歌頌。","notes":[]},{"n":14,"t":"你們中間有病了的呢，他就該請教會的長老來；他們可以奉主的名用油抹他，為他禱告。","notes":[]},{"n":15,"t":"出於信心的祈禱要救那病人，主必叫他起來；他若犯了罪，也必蒙赦免。","notes":[]},{"n":16,"t":"所以你們要彼此認罪，互相代求，使你們可以得醫治。義人祈禱所發的力量是大有功效的。","notes":[]},{"n":17,"t":"以利亞與我們是一樣性情的人，他懇切禱告，求不要下雨，雨就三年零六個月不下在地上。","notes":[]},{"n":18,"t":"他又禱告，天就降下雨來，地也生出土產。","notes":[]},{"n":19,"t":"我的弟兄們，你們中間若有失迷真道的，有人使他回轉，","notes":[]},{"n":20,"t":"這人該知道：叫一個罪人從迷路上轉回便是救一個靈魂不死，並且遮蓋許多的罪。","notes":[]}]}},"1PE":{"1":{"heading":"問候","verses":[{"n":1,"t":"耶穌基督的使徒彼得寫信給那分散在本都、加拉太、加帕多家、亞細亞、庇推尼寄居的，","notes":[]},{"n":2,"t":"就是照父神的先見被揀選，藉著聖靈得成聖潔，以致順服耶穌基督，又蒙他血所灑的人。願恩惠、平安多多地加給你們。","notes":[]},{"n":3,"t":"願頌讚歸與我們主耶穌基督的父神！他曾照自己的大憐憫，藉耶穌基督從死裏復活，重生了我們，叫我們有活潑的盼望，","notes":[],"heads":["活的盼望"]},{"n":4,"t":"可以得著不能朽壞、不能玷污、不能衰殘、為你們存留在天上的基業。","notes":[]},{"n":5,"t":"你們這因信蒙神能力保守的人，必能得著所預備、到末世要顯現的救恩。","notes":[]},{"n":6,"t":"因此，你們是大有喜樂；但如今，在百般的試煉中暫時憂愁，","notes":[]},{"n":7,"t":"叫你們的信心既被試驗，就比那被火試驗仍然能壞的金子更顯寶貴，可以在耶穌基督顯現的時候得著稱讚、榮耀、尊貴。","notes":[]},{"n":8,"t":"你們雖然沒有見過他，卻是愛他；如今雖不得看見，卻因信他就有說不出來、滿有榮光的大喜樂；","notes":[]},{"n":9,"t":"並且得著你們信心的果效，就是靈魂的救恩。","notes":[]},{"n":10,"t":"論到這救恩，那預先說你們要得恩典的眾先知早已詳細地尋求考察，","notes":[]},{"n":11,"t":"就是考察在他們心裏基督的靈，預先證明基督受苦難，後來得榮耀，是指著甚麼時候，並怎樣的時候。","notes":[]},{"n":12,"t":"他們得了啟示，知道他們所傳講的一切事，不是為自己，乃是為你們。那靠著從天上差來的聖靈傳福音給你們的人，現在將這些事報給你們；天使也願意詳細察看這些事。","notes":["原文是服事"]},{"n":13,"t":"所以要約束你們的心，謹慎自守，專心盼望耶穌基督顯現的時候所帶來給你們的恩。","notes":["原文是束上你們心中的腰"],"heads":["應當過聖潔的生活"]},{"n":14,"t":"你們既作順命的兒女，就不要效法從前蒙昧無知的時候那放縱私慾的樣子。","notes":[]},{"n":15,"t":"那召你們的既是聖潔，你們在一切所行的事上也要聖潔。","notes":[]},{"n":16,"t":"因為經上記著說：「你們要聖潔，因為我是聖潔的。」","notes":[]},{"n":17,"t":"你們既稱那不偏待人、按各人行為審判人的主為父，就當存敬畏的心度你們在世寄居的日子，","notes":[]},{"n":18,"t":"知道你們得贖，脫去你們祖宗所傳流虛妄的行為，不是憑著能壞的金銀等物，","notes":[]},{"n":19,"t":"乃是憑著基督的寶血，如同無瑕疵、無玷污的羔羊之血。","notes":[]},{"n":20,"t":"基督在創世以前是預先被神知道的，卻在這末世才為你們顯現。","notes":[]},{"n":21,"t":"你們也因著他，信那叫他從死裏復活、又給他榮耀的神，叫你們的信心和盼望都在於神。","notes":[]},{"n":22,"t":"你們既因順從真理，潔淨了自己的心，以致愛弟兄沒有虛假，就當從心裏彼此切實相愛。","notes":["從心裏：有古卷是從清潔的心"]},{"n":23,"t":"你們蒙了重生，不是由於能壞的種子，乃是由於不能壞的種子，是藉著神活潑常存的道。","notes":[]},{"n":24,"t":"因為凡有血氣的，盡都如草；他的美榮都像草上的花。草必枯乾，花必凋謝；","notes":[]},{"n":25,"t":"惟有主的道是永存的。所傳給你們的福音就是這道。","notes":[]}]},"2":{"heading":"活石和聖潔的國度","verses":[{"n":1,"t":"所以，你們既除去一切的惡毒、詭詐，並假善、嫉妒，和一切毀謗的話，","notes":["或譯：陰毒"]},{"n":2,"t":"就要愛慕那純淨的靈奶，像才生的嬰孩愛慕奶一樣，叫你們因此漸長，以致得救。","notes":[]},{"n":3,"t":"你們若嘗過主恩的滋味，就必如此。","notes":[]},{"n":4,"t":"主乃活石，固然是被人所棄的，卻是被神所揀選、所寶貴的。","notes":[]},{"n":5,"t":"你們來到主面前，也就像活石，被建造成為靈宮，作聖潔的祭司，藉著耶穌基督奉獻神所悅納的靈祭。","notes":[]},{"n":6,"t":"因為經上說：看哪，我把所揀選、所寶貴的房角石安放在錫安；信靠他的人必不至於羞愧。","notes":[]},{"n":7,"t":"所以，他在你們信的人就為寶貴，在那不信的人有話說：匠人所棄的石頭已作了房角的頭塊石頭。","notes":[]},{"n":8,"t":"又說：作了絆腳的石頭，跌人的磐石。他們既不順從，就在道理上絆跌；他們這樣絆跌也是預定的。","notes":["或譯：他們絆跌都因不順從道理"]},{"n":9,"t":"惟有你們是被揀選的族類，是有君尊的祭司，是聖潔的國度，是屬神的子民，要叫你們宣揚那召你們出黑暗入奇妙光明者的美德。","notes":[]},{"n":10,"t":"你們從前算不得子民，現在卻作了神的子民；從前未曾蒙憐恤，現在卻蒙了憐恤。","notes":[]},{"n":11,"t":"親愛的弟兄啊，你們是客旅，是寄居的。我勸你們要禁戒肉體的私慾；這私慾是與靈魂爭戰的。","notes":[],"heads":["作神的僕人"]},{"n":12,"t":"你們在外邦人中，應當品行端正，叫那些毀謗你們是作惡的，因看見你們的好行為，便在鑒察的日子歸榮耀給神。","notes":["或譯：眷顧"]},{"n":13,"t":"你們為主的緣故，要順服人的一切制度，或是在上的君王，","notes":[]},{"n":14,"t":"或是君王所派罰惡賞善的臣宰。","notes":[]},{"n":15,"t":"因為神的旨意原是要你們行善，可以堵住那糊塗無知人的口。","notes":[]},{"n":16,"t":"你們雖是自由的，卻不可藉著自由遮蓋惡毒，總要作神的僕人。","notes":["或譯：陰毒"]},{"n":17,"t":"務要尊敬眾人，親愛教中的弟兄，敬畏神，尊敬君王。","notes":[]},{"n":18,"t":"你們作僕人的，凡事要存敬畏的心順服主人；不但順服那善良溫和的，就是那乖僻的也要順服。","notes":[],"heads":["基督受苦的榜樣"]},{"n":19,"t":"倘若人為叫良心對得住神，就忍受冤屈的苦楚，這是可喜愛的。","notes":[]},{"n":20,"t":"你們若因犯罪受責打，能忍耐，有甚麼可誇的呢？但你們若因行善受苦，能忍耐，這在神看是可喜愛的。","notes":[]},{"n":21,"t":"你們蒙召原是為此；因基督也為你們受過苦，給你們留下榜樣，叫你們跟隨他的腳蹤行。","notes":[]},{"n":22,"t":"他並沒有犯罪，口裏也沒有詭詐。","notes":[]},{"n":23,"t":"他被罵不還口；受害不說威嚇的話，只將自己交託那按公義審判人的主。","notes":[]},{"n":24,"t":"他被掛在木頭上，親身擔當了我們的罪，使我們既然在罪上死，就得以在義上活。因他受的鞭傷，你們便得了醫治。","notes":[]},{"n":25,"t":"你們從前好像迷路的羊，如今卻歸到你們靈魂的牧人監督了。","notes":[]}]},"3":{"heading":"妻子和丈夫","verses":[{"n":1,"t":"你們作妻子的要順服自己的丈夫；這樣，若有不信從道理的丈夫，他們雖然不聽道，也可以因妻子的品行被感化過來；","notes":[]},{"n":2,"t":"這正是因看見你們有貞潔的品行和敬畏的心。","notes":[]},{"n":3,"t":"你們不要以外面的辮頭髮，戴金飾，穿美衣為妝飾，","notes":[]},{"n":4,"t":"只要以裏面存著長久溫柔、安靜的心為妝飾；這在神面前是極寶貴的。","notes":[]},{"n":5,"t":"因為古時仰賴神的聖潔婦人正是以此為妝飾，順服自己的丈夫，","notes":[]},{"n":6,"t":"就如撒拉聽從亞伯拉罕，稱他為主。你們若行善，不因恐嚇而害怕，便是撒拉的女兒了。","notes":[]},{"n":7,"t":"你們作丈夫的也要按情理和妻子同住；因她比你軟弱，與你一同承受生命之恩的，所以要敬重她。這樣，便叫你們的禱告沒有阻礙。","notes":["原文是知識","比你軟弱：原文作是軟弱的器皿"]},{"n":8,"t":"總而言之，你們都要同心，彼此體恤，相愛如弟兄，存慈憐謙卑的心。","notes":[],"heads":["為義受苦"]},{"n":9,"t":"不以惡報惡，以辱罵還辱罵，倒要祝福；因你們是為此蒙召，好叫你們承受福氣。","notes":[]},{"n":10,"t":"因為經上說：人若愛生命，願享美福，須要禁止舌頭不出惡言，嘴唇不說詭詐的話；","notes":[]},{"n":11,"t":"也要離惡行善，尋求和睦，一心追趕。","notes":[]},{"n":12,"t":"因為，主的眼看顧義人；主的耳聽他們的祈禱。惟有行惡的人，主向他們變臉。","notes":[]},{"n":13,"t":"你們若是熱心行善，有誰害你們呢？","notes":[]},{"n":14,"t":"你們就是為義受苦，也是有福的。不要怕人的威嚇，也不要驚慌；","notes":["的威嚇：或譯所怕的"]},{"n":15,"t":"只要心裏尊主基督為聖。有人問你們心中盼望的緣由，就要常作準備，以溫柔、敬畏的心回答各人；","notes":[]},{"n":16,"t":"存著無虧的良心，叫你們在何事上被毀謗，就在何事上可以叫那誣賴你們在基督裏有好品行的人自覺羞愧。","notes":[]},{"n":17,"t":"神的旨意若是叫你們因行善受苦，總強如因行惡受苦。","notes":[]},{"n":18,"t":"因基督也曾一次為罪受苦，就是義的代替不義的，為要引我們到神面前。按著肉體說，他被治死；按著靈性說，他復活了。","notes":["有古卷：受死"]},{"n":19,"t":"他藉這靈曾去傳道給那些在監獄裏的靈聽，","notes":[]},{"n":20,"t":"就是那從前在挪亞預備方舟、神容忍等待的時候，不信從的人。當時進入方舟，藉著水得救的不多，只有八個人。","notes":[]},{"n":21,"t":"這水所表明的洗禮，現在藉著耶穌基督復活也拯救你們；這洗禮本不在乎除掉肉體的污穢，只求在神面前有無虧的良心。","notes":[]},{"n":22,"t":"耶穌已經進入天堂，在神的右邊；眾天使和有權柄的，並有能力的，都服從了他。","notes":[]}]},"4":{"heading":"神恩賜的好管家","verses":[{"n":1,"t":"基督既在肉身受苦，你們也當將這樣的心志作為兵器，因為在肉身受過苦的，就已經與罪斷絕了。","notes":[]},{"n":2,"t":"你們存這樣的心，從今以後就可以不從人的情慾，只從神的旨意在世度餘下的光陰。","notes":[]},{"n":3,"t":"因為往日隨從外邦人的心意行邪淫、惡慾、醉酒、荒宴、群飲，並可惡拜偶像的事，時候已經夠了。","notes":[]},{"n":4,"t":"他們在這些事上，見你們不與他們同奔那放蕩無度的路，就以為怪，毀謗你們。","notes":[]},{"n":5,"t":"他們必在那將要審判活人死人的主面前交帳。","notes":[]},{"n":6,"t":"為此，就是死人也曾有福音傳給他們，要叫他們的肉體按著人受審判，他們的靈性卻靠神活著。","notes":[]},{"n":7,"t":"萬物的結局近了。所以，你們要謹慎自守，警醒禱告。","notes":[]},{"n":8,"t":"最要緊的是彼此切實相愛，因為愛能遮掩許多的罪。","notes":[]},{"n":9,"t":"你們要互相款待，不發怨言。","notes":[]},{"n":10,"t":"各人要照所得的恩賜彼此服事，作神百般恩賜的好管家。","notes":[]},{"n":11,"t":"若有講道的，要按著神的聖言講；若有服事人的，要按著神所賜的力量服事，叫神在凡事上因耶穌基督得榮耀。原來榮耀、權能都是他的，直到永永遠遠。阿們！","notes":[]},{"n":12,"t":"親愛的弟兄啊，有火煉的試驗臨到你們，不要以為奇怪（似乎是遭遇非常的事），","notes":[],"heads":["為作基督徒受苦"]},{"n":13,"t":"倒要歡喜；因為你們是與基督一同受苦，使你們在他榮耀顯現的時候，也可以歡喜快樂。","notes":[]},{"n":14,"t":"你們若為基督的名受辱罵，便是有福的；因為神榮耀的靈常住在你們身上。","notes":[]},{"n":15,"t":"你們中間卻不可有人因為殺人、偷竊、作惡、好管閒事而受苦。","notes":[]},{"n":16,"t":"若為作基督徒受苦，卻不要羞恥，倒要因這名歸榮耀給神。","notes":[]},{"n":17,"t":"因為時候到了，審判要從神的家起首。若是先從我們起首，那不信從神福音的人將有何等的結局呢？","notes":[]},{"n":18,"t":"若是義人僅僅得救，那不虔敬和犯罪的人將有何地可站呢？","notes":[]},{"n":19,"t":"所以，那照神旨意受苦的人要一心為善，將自己靈魂交與那信實的造化之主。","notes":[]}]},"5":{"heading":"照管神的羊群","verses":[{"n":1,"t":"我這作長老、作基督受苦的見證、同享後來所要顯現之榮耀的，勸你們中間與我同作長老的人：","notes":[]},{"n":2,"t":"務要牧養在你們中間神的群羊，按著神旨意照管他們；不是出於勉強，乃是出於甘心；也不是因為貪財，乃是出於樂意；","notes":[]},{"n":3,"t":"也不是轄制所託付你們的，乃是作群羊的榜樣。","notes":[]},{"n":4,"t":"到了牧長顯現的時候，你們必得那永不衰殘的榮耀冠冕。","notes":[]},{"n":5,"t":"你們年幼的，也要順服年長的。就是你們眾人也都要以謙卑束腰，彼此順服；因為神阻擋驕傲的人，賜恩給謙卑的人。","notes":[]},{"n":6,"t":"所以，你們要自卑，服在神大能的手下，到了時候，他必叫你們升高。","notes":[]},{"n":7,"t":"你們要將一切的憂慮卸給神，因為他顧念你們。","notes":[]},{"n":8,"t":"務要謹守，警醒。因為你們的仇敵魔鬼，如同吼叫的獅子，遍地遊行，尋找可吞吃的人。","notes":[]},{"n":9,"t":"你們要用堅固的信心抵擋他，因為知道你們在世上的眾弟兄也是經歷這樣的苦難。","notes":[]},{"n":10,"t":"那賜諸般恩典的神曾在基督裏召你們，得享他永遠的榮耀，等你們暫受苦難之後，必要親自成全你們，堅固你們，賜力量給你們。","notes":[]},{"n":11,"t":"願權能歸給他，直到永永遠遠。阿們！","notes":[]},{"n":12,"t":"我略略地寫了這信，託我所看為忠心的兄弟西拉轉交你們，勸勉你們，又證明這恩是神的真恩。你們務要在這恩上站立得住。","notes":[],"heads":["問安"]},{"n":13,"t":"在巴比倫與你們同蒙揀選的教會問你們安。我兒子馬可也問你們安。","notes":[]},{"n":14,"t":"你們要用愛心彼此親嘴問安。願平安歸與你們凡在基督裏的人！","notes":[]}]}},"2PE":{"1":{"heading":"問候","verses":[{"n":1,"t":"作耶穌基督僕人和使徒的西門‧彼得寫信給那因我們的神和救主耶穌基督之義、與我們同得一樣寶貴信心的人。","notes":["有古卷沒有和字"]},{"n":2,"t":"願恩惠、平安，因你們認識神和我們主耶穌，多多地加給你們。","notes":[]},{"n":3,"t":"神的神能已將一切關乎生命和虔敬的事賜給我們，皆因我們認識那用自己榮耀和美德召我們的主。","notes":[],"heads":["信徒所蒙的恩召和揀選"]},{"n":4,"t":"因此，他已將又寶貴又極大的應許賜給我們，叫我們既脫離世上從情慾來的敗壞，就得與神的性情有分。","notes":[]},{"n":5,"t":"正因這緣故，你們要分外地殷勤；有了信心，又要加上德行；有了德行，又要加上知識；","notes":[]},{"n":6,"t":"有了知識，又要加上節制；有了節制，又要加上忍耐；有了忍耐，又要加上虔敬；","notes":[]},{"n":7,"t":"有了虔敬，又要加上愛弟兄的心；有了愛弟兄的心，又要加上愛眾人的心。","notes":[]},{"n":8,"t":"你們若充充足足地有這幾樣，就必使你們在認識我們的主耶穌基督上不至於閒懶不結果子了。","notes":[]},{"n":9,"t":"人若沒有這幾樣，就是眼瞎，只看見近處的，忘了他舊日的罪已經得了潔淨。","notes":[]},{"n":10,"t":"所以弟兄們，應當更加殷勤，使你們所蒙的恩召和揀選堅定不移。你們若行這幾樣，就永不失腳；","notes":[]},{"n":11,"t":"這樣，必叫你們豐豐富富地得以進入我們主－救主耶穌基督永遠的國。","notes":[]},{"n":12,"t":"你們雖然曉得這些事，並且在你們已有的真道上堅固，我卻要將這些事常常提醒你們。","notes":[]},{"n":13,"t":"我以為應當趁我還在這帳棚的時候提醒你們，激發你們；","notes":[]},{"n":14,"t":"因為知道我脫離這帳棚的時候快到了，正如我們主耶穌基督所指示我的。","notes":[]},{"n":15,"t":"並且，我要盡心竭力，使你們在我去世以後時常記念這些事。","notes":[]},{"n":16,"t":"我們從前將我們主耶穌基督的大能和他降臨的事告訴你們，並不是隨從乖巧捏造的虛言，乃是親眼見過他的威榮。","notes":[],"heads":["基督的榮耀和先知的預言"]},{"n":17,"t":"他從父神得尊貴榮耀的時候，從極大榮光之中有聲音出來，向他說：「這是我的愛子，我所喜悅的。」","notes":[]},{"n":18,"t":"我們同他在聖山的時候，親自聽見這聲音從天上出來。","notes":[]},{"n":19,"t":"我們並有先知更確的預言，如同燈照在暗處。你們在這預言上留意，直等到天發亮，晨星在你們心裏出現的時候，才是好的。","notes":[]},{"n":20,"t":"第一要緊的，該知道經上所有的預言沒有可隨私意解說的；","notes":[]},{"n":21,"t":"因為預言從來沒有出於人意的，乃是人被聖靈感動，說出神的話來。","notes":[]}]},"2":{"heading":"假先知和假師傅","verses":[{"n":1,"t":"從前在百姓中有假先知起來，將來在你們中間也必有假師傅，私自引進陷害人的異端，連買他們的主他們也不承認，自取速速地滅亡。","notes":[]},{"n":2,"t":"將有許多人隨從他們邪淫的行為，便叫真道因他們的緣故被毀謗。","notes":[]},{"n":3,"t":"他們因有貪心，要用捏造的言語在你們身上取利。他們的刑罰，自古以來並不遲延；他們的滅亡也必速速來到。","notes":["原文是也不打盹"]},{"n":4,"t":"就是天使犯了罪，神也沒有寬容，曾把他們丟在地獄，交在黑暗坑中，等候審判。","notes":[]},{"n":5,"t":"神也沒有寬容上古的世代，曾叫洪水臨到那不敬虔的世代，卻保護了傳義道的挪亞一家八口。","notes":[]},{"n":6,"t":"又判定所多瑪、蛾摩拉，將二城傾覆，焚燒成灰，作為後世不敬虔人的鑑戒；","notes":[]},{"n":7,"t":"只搭救了那常為惡人淫行憂傷的義人羅得。（","notes":[]},{"n":8,"t":"因為那義人住在他們中間，看見聽見他們不法的事，他的義心就天天傷痛。）","notes":[]},{"n":9,"t":"主知道搭救敬虔的人脫離試探，把不義的人留在刑罰之下，等候審判的日子。","notes":[]},{"n":10,"t":"那些隨肉身、縱污穢的情慾、輕慢主治之人的，更是如此。他們膽大任性，毀謗在尊位的，也不知懼怕。","notes":[]},{"n":11,"t":"就是天使，雖然力量權能更大，還不用毀謗的話在主面前告他們。","notes":[]},{"n":12,"t":"但這些人好像沒有靈性，生來就是畜類，以備捉拿宰殺的。他們毀謗所不曉得的事，正在敗壞人的時候，自己必遭遇敗壞。","notes":[]},{"n":13,"t":"行的不義，就得了不義的工價。這些人喜愛白晝宴樂，他們已被玷污，又有瑕疵，正與你們一同坐席，就以自己的詭詐為快樂。","notes":[]},{"n":14,"t":"他們滿眼是淫色，止不住犯罪，引誘那心不堅固的人，心中習慣了貪婪，正是被咒詛的種類。","notes":["原文是淫婦"]},{"n":15,"t":"他們離棄正路，就走差了，隨從比珥之子巴蘭的路。巴蘭就是那貪愛不義之工價的先知，","notes":[]},{"n":16,"t":"他卻為自己的過犯受了責備；那不能說話的驢以人言攔阻先知的狂妄。","notes":[]},{"n":17,"t":"這些人是無水的井，是狂風催逼的霧氣，有墨黑的幽暗為他們存留。","notes":[]},{"n":18,"t":"他們說虛妄矜誇的大話，用肉身的情慾和邪淫的事引誘那些剛才脫離妄行的人。","notes":[]},{"n":19,"t":"他們應許人得以自由，自己卻作敗壞的奴僕，因為人被誰制伏就是誰的奴僕。","notes":[]},{"n":20,"t":"倘若他們因認識主－救主耶穌基督，得以脫離世上的污穢，後來又在其中被纏住、制伏，他們末後的景況就比先前更不好了。","notes":[]},{"n":21,"t":"他們曉得義路，竟背棄了傳給他們的聖命，倒不如不曉得為妙。","notes":[]},{"n":22,"t":"俗語說得真不錯：狗所吐的，牠轉過來又吃；豬洗淨了又回到泥裏去滾；這話在他們身上正合式。","notes":[]}]},"3":{"heading":"主再來的應許","verses":[{"n":1,"t":"親愛的弟兄啊，我現在寫給你們的是第二封信。這兩封都是提醒你們，激發你們誠實的心，","notes":[]},{"n":2,"t":"叫你們記念聖先知預先所說的話和主救主的命令，就是使徒所傳給你們的。","notes":[]},{"n":3,"t":"第一要緊的，該知道在末世必有好譏誚的人隨從自己的私慾出來譏誚說：","notes":[]},{"n":4,"t":"「主要降臨的應許在哪裏呢？因為從列祖睡了以來，萬物與起初創造的時候仍是一樣。」","notes":[]},{"n":5,"t":"他們故意忘記，從太古，憑神的命有了天，並從水而出、藉水而成的地。","notes":[]},{"n":6,"t":"故此，當時的世界被水淹沒就消滅了。","notes":[]},{"n":7,"t":"但現在的天地還是憑著那命存留，直留到不敬虔之人受審判遭沉淪的日子，用火焚燒。","notes":[]},{"n":8,"t":"親愛的弟兄啊，有一件事你們不可忘記，就是主看一日如千年，千年如一日。","notes":[]},{"n":9,"t":"主所應許的尚未成就，有人以為他是耽延，其實不是耽延，乃是寬容你們，不願有一人沉淪，乃願人人都悔改。","notes":[]},{"n":10,"t":"但主的日子要像賊來到一樣。那日，天必大有響聲廢去，有形質的都要被烈火銷化，地和其上的物都要燒盡了。","notes":[]},{"n":11,"t":"這一切既然都要如此銷化，你們為人該當怎樣聖潔，怎樣敬虔，","notes":[]},{"n":12,"t":"切切仰望神的日子來到。在那日，天被火燒就銷化了，有形質的都要被烈火鎔化。","notes":[]},{"n":13,"t":"但我們照他的應許，盼望新天新地，有義居在其中。","notes":[]},{"n":14,"t":"親愛的弟兄啊，你們既盼望這些事，就當殷勤，使自己沒有玷污，無可指摘，安然見主；","notes":[]},{"n":15,"t":"並且要以我主長久忍耐為得救的因由，就如我們所親愛的兄弟保羅，照著所賜給他的智慧寫了信給你們。","notes":[]},{"n":16,"t":"他一切的信上也都是講論這事。信中有些難明白的，那無學問、不堅固的人強解，如強解別的經書一樣，就自取沉淪。","notes":[]},{"n":17,"t":"親愛的弟兄啊，你們既然預先知道這事，就當防備，恐怕被惡人的錯謬誘惑，就從自己堅固的地步上墜落。","notes":[]},{"n":18,"t":"你們卻要在我們主－救主耶穌基督的恩典和知識上有長進。願榮耀歸給他，從今直到永遠。阿們！","notes":[]}]}},"1JN":{"1":{"heading":"生命之道","verses":[{"n":1,"t":"論到從起初原有的生命之道，就是我們所聽見、所看見、親眼看過、親手摸過的。（","notes":[]},{"n":2,"t":"這生命已經顯現出來，我們也看見過，現在又作見證，將原與父同在、且顯現與我們那永遠的生命傳給你們。）","notes":[]},{"n":3,"t":"我們將所看見、所聽見的傳給你們，使你們與我們相交。我們乃是與父並他兒子耶穌基督相交的。","notes":[]},{"n":4,"t":"我們將這些話寫給你們，使你們的喜樂充足。","notes":["有古卷：我們"]},{"n":5,"t":"神就是光，在他毫無黑暗。這是我們從主所聽見、又報給你們的信息。","notes":[],"heads":["神就是光"]},{"n":6,"t":"我們若說是與神相交，卻仍在黑暗裏行，就是說謊話，不行真理了。","notes":[]},{"n":7,"t":"我們若在光明中行，如同神在光明中，就彼此相交，他兒子耶穌的血也洗淨我們一切的罪。","notes":[]},{"n":8,"t":"我們若說自己無罪，便是自欺，真理不在我們心裏了。","notes":[]},{"n":9,"t":"我們若認自己的罪，神是信實的，是公義的，必要赦免我們的罪，洗淨我們一切的不義。","notes":[]},{"n":10,"t":"我們若說自己沒有犯過罪，便是以神為說謊的，他的道也不在我們心裏了。","notes":[]}]},"2":{"heading":"我們的中保基督","verses":[{"n":1,"t":"我小子們哪，我將這些話寫給你們，是要叫你們不犯罪。若有人犯罪，在父那裏我們有一位中保，就是那義者耶穌基督。","notes":[]},{"n":2,"t":"他為我們的罪作了挽回祭，不是單為我們的罪，也是為普天下人的罪。","notes":[]},{"n":3,"t":"我們若遵守他的誡命，就曉得是認識他。","notes":[]},{"n":4,"t":"人若說「我認識他」，卻不遵守他的誡命，便是說謊話的，真理也不在他心裏了。","notes":[]},{"n":5,"t":"凡遵守主道的，愛神的心在他裏面實在是完全的。從此，我們知道我們是在主裏面。","notes":[]},{"n":6,"t":"人若說他住在主裏面，就該自己照主所行的去行。","notes":[]},{"n":7,"t":"親愛的弟兄啊，我寫給你們的，不是一條新命令，乃是你們從起初所受的舊命令；這舊命令就是你們所聽見的道。","notes":[],"heads":["新命令"]},{"n":8,"t":"再者，我寫給你們的，是一條新命令，在主是真的，在你們也是真的；因為黑暗漸漸過去，真光已經照耀。","notes":[]},{"n":9,"t":"人若說自己在光明中，卻恨他的弟兄，他到如今還是在黑暗裏。","notes":[]},{"n":10,"t":"愛弟兄的，就是住在光明中，在他並沒有絆跌的緣由。","notes":[]},{"n":11,"t":"惟獨恨弟兄的，是在黑暗裏，且在黑暗裏行，也不知道往哪裏去，因為黑暗叫他眼睛瞎了。","notes":[]},{"n":12,"t":"小子們哪，我寫信給你們，因為你們的罪藉著主名得了赦免。","notes":[]},{"n":13,"t":"父老啊，我寫信給你們，因為你們認識那從起初原有的。少年人哪，我寫信給你們，因為你們勝了那惡者。","notes":[]},{"n":14,"t":"小子們哪，我曾寫信給你們，因為你們認識父。父老啊，我曾寫信給你們，因為你們認識那從起初原有的。少年人哪，我曾寫信給你們；因為你們剛強，神的道常存在你們心裏；你們也勝了那惡者。","notes":[]},{"n":15,"t":"不要愛世界和世界上的事。人若愛世界，愛父的心就不在他裏面了。","notes":[]},{"n":16,"t":"因為，凡世界上的事，就像肉體的情慾、眼目的情慾，並今生的驕傲，都不是從父來的，乃是從世界來的。","notes":[]},{"n":17,"t":"這世界和其上的情慾都要過去，惟獨遵行神旨意的，是永遠常存。","notes":[]},{"n":18,"t":"小子們哪，如今是末時了。你們曾聽見說，那敵基督的要來；現在已經有好些敵基督的出來了，從此我們就知道如今是末時了。","notes":[],"heads":["敵基督者"]},{"n":19,"t":"他們從我們中間出去，卻不是屬我們的；若是屬我們的，就必仍舊與我們同在；他們出去，顯明都不是屬我們的。","notes":[]},{"n":20,"t":"你們從那聖者受了恩膏，並且知道這一切的事。","notes":["或譯：都有知識"]},{"n":21,"t":"我寫信給你們，不是因你們不知道真理，正是因你們知道，並且知道沒有虛謊是從真理出來的。","notes":[]},{"n":22,"t":"誰是說謊話的呢？不是那不認耶穌為基督的嗎？不認父與子的，這就是敵基督的。","notes":[]},{"n":23,"t":"凡不認子的，就沒有父；認子的，連父也有了。","notes":[]},{"n":24,"t":"論到你們，務要將那從起初所聽見的，常存在心裏。若將從起初所聽見的存在心裏，你們就必住在子裏面，也必住在父裏面。","notes":[]},{"n":25,"t":"主所應許我們的就是永生。","notes":[]},{"n":26,"t":"我將這些話寫給你們，是指著那引誘你們的人說的。","notes":[]},{"n":27,"t":"你們從主所受的恩膏常存在你們心裏，並不用人教訓你們，自有主的恩膏在凡事上教訓你們。這恩膏是真的，不是假的；你們要按這恩膏的教訓住在主裏面。","notes":[]},{"n":28,"t":"小子們哪，你們要住在主裏面。這樣，他若顯現，我們就可以坦然無懼；當他來的時候，在他面前也不至於慚愧。","notes":[],"heads":["神的兒女"]},{"n":29,"t":"你們若知道他是公義的，就知道凡行公義之人都是他所生的。","notes":[]}]},"3":{"heading":"彼此相愛","verses":[{"n":1,"t":"你看父賜給我們是何等的慈愛，使我們得稱為神的兒女；我們也真是他的兒女。世人所以不認識我們，是因未曾認識他。","notes":[]},{"n":2,"t":"親愛的弟兄啊，我們現在是神的兒女，將來如何，還未顯明；但我們知道，主若顯現，我們必要像他，因為必得見他的真體。","notes":[]},{"n":3,"t":"凡向他有這指望的，就潔淨自己，像他潔淨一樣。","notes":[]},{"n":4,"t":"凡犯罪的，就是違背律法；違背律法就是罪。","notes":[]},{"n":5,"t":"你們知道主曾顯現，是要除掉人的罪，在他並沒有罪。","notes":[]},{"n":6,"t":"凡住在他裏面的，就不犯罪；凡犯罪的，是未曾看見他，也未曾認識他。","notes":[]},{"n":7,"t":"小子們哪，不要被人誘惑。行義的才是義人，正如主是義的一樣。","notes":[]},{"n":8,"t":"犯罪的是屬魔鬼，因為魔鬼從起初就犯罪。神的兒子顯現出來，為要除滅魔鬼的作為。","notes":[]},{"n":9,"t":"凡從神生的，就不犯罪，因神的道存在他心裏；他也不能犯罪，因為他是由神生的。","notes":["原文是種"]},{"n":10,"t":"從此就顯出誰是神的兒女，誰是魔鬼的兒女。凡不行義的就不屬神，不愛弟兄的也是如此。","notes":[]},{"n":11,"t":"我們應當彼此相愛。這就是你們從起初所聽見的命令。","notes":[]},{"n":12,"t":"不可像該隱；他是屬那惡者，殺了他的兄弟。為甚麼殺了他呢？因自己的行為是惡的，兄弟的行為是善的。","notes":[]},{"n":13,"t":"弟兄們，世人若恨你們，不要以為希奇。","notes":[]},{"n":14,"t":"我們因為愛弟兄，就曉得是已經出死入生了。沒有愛心的，仍住在死中。","notes":[]},{"n":15,"t":"凡恨他弟兄的，就是殺人的；你們曉得凡殺人的，沒有永生存在他裏面。","notes":[]},{"n":16,"t":"主為我們捨命，我們從此就知道何為愛；我們也當為弟兄捨命。","notes":[]},{"n":17,"t":"凡有世上財物的，看見弟兄窮乏，卻塞住憐恤的心，愛神的心怎能存在他裏面呢？","notes":[]},{"n":18,"t":"小子們哪，我們相愛，不要只在言語和舌頭上，總要在行為和誠實上。","notes":[]},{"n":19,"t":"從此就知道我們是屬真理的，並且我們的心在神面前可以安穩。","notes":[],"heads":["在神面前安穩"]},{"n":20,"t":"我們的心若責備我們，神比我們的心大，一切事沒有不知道的。","notes":[]},{"n":21,"t":"親愛的弟兄啊，我們的心若不責備我們，就可以向神坦然無懼了。","notes":[]},{"n":22,"t":"並且我們一切所求的，就從他得著；因為我們遵守他的命令，行他所喜悅的事。","notes":[]},{"n":23,"t":"神的命令就是叫我們信他兒子耶穌基督的名，且照他所賜給我們的命令彼此相愛。","notes":[]},{"n":24,"t":"遵守神命令的，就住在神裏面，神也住在他裏面。我們所以知道神住在我們裏面是因他所賜給我們的聖靈。","notes":[]}]},"4":{"heading":"神的靈和敵基督者的靈","verses":[{"n":1,"t":"親愛的弟兄啊，一切的靈，你們不可都信，總要試驗那些靈是出於神的不是，因為世上有許多假先知已經出來了。","notes":[]},{"n":2,"t":"凡靈認耶穌基督是成了肉身來的，就是出於神的；從此你們可以認出神的靈來。","notes":[]},{"n":3,"t":"凡靈不認耶穌，就不是出於神，這是那敵基督者的靈。你們從前聽見他要來，現在已經在世上了。","notes":[]},{"n":4,"t":"小子們哪，你們是屬神的，並且勝了他們；因為那在你們裏面的，比那在世界上的更大。","notes":[]},{"n":5,"t":"他們是屬世界的，所以論世界的事，世人也聽從他們。","notes":[]},{"n":6,"t":"我們是屬神的，認識神的就聽從我們；不屬神的就不聽從我們。從此我們可以認出真理的靈和謬妄的靈來。","notes":[]},{"n":7,"t":"親愛的弟兄啊，我們應當彼此相愛，因為愛是從神來的。凡有愛心的，都是由神而生，並且認識神。","notes":[],"heads":["神就是愛"]},{"n":8,"t":"沒有愛心的，就不認識神，因為神就是愛。","notes":[]},{"n":9,"t":"神差他獨生子到世間來，使我們藉著他得生，神愛我們的心在此就顯明了。","notes":[]},{"n":10,"t":"不是我們愛神，乃是神愛我們，差他的兒子為我們的罪作了挽回祭，這就是愛了。","notes":[]},{"n":11,"t":"親愛的弟兄啊，神既是這樣愛我們，我們也當彼此相愛。","notes":[]},{"n":12,"t":"從來沒有人見過神，我們若彼此相愛，神就住在我們裏面，愛他的心在我們裏面得以完全了。","notes":[]},{"n":13,"t":"神將他的靈賜給我們，從此就知道我們是住在他裏面，他也住在我們裏面。","notes":[]},{"n":14,"t":"父差子作世人的救主；這是我們所看見且作見證的。","notes":[]},{"n":15,"t":"凡認耶穌為神兒子的，神就住在他裏面，他也住在神裏面。","notes":[]},{"n":16,"t":"神愛我們的心，我們也知道也信。神就是愛；住在愛裏面的，就是住在神裏面，神也住在他裏面。","notes":[]},{"n":17,"t":"這樣，愛在我們裏面得以完全，我們就可以在審判的日子坦然無懼。因為他如何，我們在這世上也如何。","notes":[]},{"n":18,"t":"愛裏沒有懼怕；愛既完全，就把懼怕除去。因為懼怕裏含著刑罰，懼怕的人在愛裏未得完全。","notes":[]},{"n":19,"t":"我們愛，因為神先愛我們。","notes":[]},{"n":20,"t":"人若說「我愛神」，卻恨他的弟兄，就是說謊話的；不愛他所看見的弟兄，就不能愛沒有看見的神。","notes":["有古卷：怎能愛沒有看見的神呢"]},{"n":21,"t":"愛神的，也當愛弟兄，這是我們從神所受的命令。","notes":[]}]},"5":{"heading":"勝了世界的就是信心","verses":[{"n":1,"t":"凡信耶穌是基督的，都是從神而生，凡愛生他之神的，也必愛從神生的。","notes":[]},{"n":2,"t":"我們若愛神，又遵守他的誡命，從此就知道我們愛神的兒女。","notes":[]},{"n":3,"t":"我們遵守神的誡命，這就是愛他了，並且他的誡命不是難守的。","notes":[]},{"n":4,"t":"因為凡從神生的，就勝過世界；使我們勝了世界的，就是我們的信心。","notes":[]},{"n":5,"t":"勝過世界的是誰呢？不是那信耶穌是神兒子的嗎？","notes":[]},{"n":6,"t":"這藉著水和血而來的，就是耶穌基督；不是單用水，乃是用水又用血，","notes":[],"heads":["神為他兒子作的見證"]},{"n":7,"t":"並且有聖靈作見證，因為聖靈就是真理。","notes":[]},{"n":8,"t":"作見證的原來有三：就是聖靈、水，與血，這三樣也都歸於一。","notes":[]},{"n":9,"t":"我們既領受人的見證，神的見證更該領受了，因神的見證是為他兒子作的。","notes":["該領受：原文是大"]},{"n":10,"t":"信神兒子的，就有這見證在他心裏；不信神的，就是將神當作說謊的，因不信神為他兒子作的見證。","notes":[]},{"n":11,"t":"這見證就是神賜給我們永生；這永生也是在他兒子裏面。","notes":[]},{"n":12,"t":"人有了神的兒子就有生命，沒有神的兒子就沒有生命。","notes":[]},{"n":13,"t":"我將這些話寫給你們信奉神兒子之名的人，要叫你們知道自己有永生。","notes":[],"heads":["知道自己有永生"]},{"n":14,"t":"我們若照他的旨意求甚麼，他就聽我們，這是我們向他所存坦然無懼的心。","notes":[]},{"n":15,"t":"既然知道他聽我們一切所求的，就知道我們所求於他的，無不得著。","notes":[]},{"n":16,"t":"人若看見弟兄犯了不至於死的罪，就當為他祈求，神必將生命賜給他；有至於死的罪，我不說當為這罪祈求。","notes":[]},{"n":17,"t":"凡不義的事都是罪，也有不至於死的罪。","notes":[]},{"n":18,"t":"我們知道凡從神生的，必不犯罪，從神生的，必保守自己，那惡者也就無法害他。","notes":["有古卷：那從神生的必保護他"]},{"n":19,"t":"我們知道，我們是屬神的，全世界都臥在那惡者手下。","notes":[]},{"n":20,"t":"我們也知道，神的兒子已經來到，且將智慧賜給我們，使我們認識那位真實的，我們也在那位真實的裏面，就是在他兒子耶穌基督裏面。這是真神，也是永生。","notes":[]},{"n":21,"t":"小子們哪，你們要自守，遠避偶像！","notes":[]}]}},"2JN":{"1":{"heading":"問候","verses":[{"n":1,"t":"作長老的寫信給蒙揀選的太太和她的兒女，就是我誠心所愛的；不但我愛，也是一切知道真理之人所愛的。","notes":["或譯：教會；下同"]},{"n":2,"t":"愛你們是為真理的緣故，這真理存在我們裏面，也必永遠與我們同在。","notes":[]},{"n":3,"t":"恩惠、憐憫、平安從父神和他兒子耶穌基督在真理和愛心上必常與我們同在！","notes":[]},{"n":4,"t":"我見你的兒女，有照我們從父所受之命令遵行真理的，就甚歡喜。","notes":[],"heads":["真理和愛"]},{"n":5,"t":"太太啊，我現在勸你，我們大家要彼此相愛。這並不是我寫一條新命令給你，乃是我們從起初所受的命令。","notes":[]},{"n":6,"t":"我們若照他的命令行，這就是愛。你們從起初所聽見當行的，就是這命令。","notes":[]},{"n":7,"t":"因為世上有許多迷惑人的出來，他們不認耶穌基督是成了肉身來的；這就是那迷惑人、敵基督的。","notes":[]},{"n":8,"t":"你們要小心，不要失去你們所做的工，乃要得著滿足的賞賜。","notes":["有古卷：我們"]},{"n":9,"t":"凡越過基督的教訓不常守著的，就沒有神；常守這教訓的，就有父又有子。","notes":[]},{"n":10,"t":"若有人到你們那裏，不是傳這教訓，不要接他到家裏，也不要問他的安；","notes":[]},{"n":11,"t":"因為問他安的，就在他的惡行上有分。","notes":[]},{"n":12,"t":"我還有許多事要寫給你們，卻不願意用紙墨寫出來，但盼望到你們那裏，與你們當面談論，使你們的喜樂滿足。","notes":[],"heads":["問安"]},{"n":13,"t":"你那蒙揀選之姊妹的兒女都問你安。","notes":[]}]}},"3JN":{"1":{"heading":"問候","verses":[{"n":1,"t":"作長老的寫信給親愛的該猶，就是我誠心所愛的。","notes":[]},{"n":2,"t":"親愛的兄弟啊，我願你凡事興盛，身體健壯，正如你的靈魂興盛一樣。","notes":[]},{"n":3,"t":"有弟兄來證明你心裏存的真理，正如你按真理而行，我就甚喜樂。","notes":[]},{"n":4,"t":"我聽見我的兒女們按真理而行，我的喜樂就沒有比這個大的。","notes":[]},{"n":5,"t":"親愛的兄弟啊，凡你向作客旅之弟兄所行的都是忠心的。","notes":[],"heads":["合作和反對"]},{"n":6,"t":"他們在教會面前證明了你的愛；你若配得過神，幫助他們往前行，這就好了。","notes":[]},{"n":7,"t":"因他們是為主的名出外，對於外邦人一無所取。","notes":["原文是那名"]},{"n":8,"t":"所以我們應該接待這樣的人，叫我們與他們一同為真理做工。","notes":[]},{"n":9,"t":"我曾略略地寫信給教會，但那在教會中好為首的丟特腓不接待我們。","notes":[]},{"n":10,"t":"所以我若去，必要提說他所行的事，就是他用惡言妄論我們。還不以此為足，他自己不接待弟兄，有人願意接待，他也禁止，並且將接待弟兄的人趕出教會。","notes":[]},{"n":11,"t":"親愛的兄弟啊，不要效法惡，只要效法善。行善的屬乎神；行惡的未曾見過神。","notes":[]},{"n":12,"t":"低米丟行善，有眾人給他作見證，又有真理給他作見證，就是我們也給他作見證。你也知道我們的見證是真的。","notes":[]},{"n":13,"t":"我原有許多事要寫給你，卻不願意用筆墨寫給你，","notes":[],"heads":["問安"]},{"n":14,"t":"但盼望快快地見你，我們就當面談論。","notes":[]},{"n":15,"t":"願你平安。眾位朋友都問你安。請你替我按著姓名問眾位朋友安。","notes":[]}]}},"JUD":{"1":{"heading":"假教師受刑罰","verses":[{"n":1,"t":"耶穌基督的僕人，雅各的弟兄猶大，寫信給那被召、在父神裏蒙愛、為耶穌基督保守的人。","notes":[]},{"n":2,"t":"願憐恤、平安、慈愛多多地加給你們。","notes":[]},{"n":3,"t":"親愛的弟兄啊，我想盡心寫信給你們，論我們同得救恩的時候，就不得不寫信勸你們，要為從前一次交付聖徒的真道竭力地爭辯。","notes":[]},{"n":4,"t":"因為有些人偷著進來，就是自古被定受刑罰的，是不虔誠的，將我們神的恩變作放縱情慾的機會，並且不認獨一的主宰－我們主耶穌基督。","notes":["或譯：和我們"]},{"n":5,"t":"從前主救了他的百姓出埃及地，後來就把那些不信的滅絕了。這一切的事，你們雖然都知道，我卻仍要提醒你們。","notes":[]},{"n":6,"t":"又有不守本位、離開自己住處的天使，主用鎖鍊把他們永遠拘留在黑暗裏，等候大日的審判。","notes":[]},{"n":7,"t":"又如所多瑪、蛾摩拉和周圍城邑的人，也照他們一味地行淫，隨從逆性的情慾，就受永火的刑罰，作為鑑戒。","notes":[]},{"n":8,"t":"這些做夢的人也像他們污穢身體，輕慢主治的，毀謗在尊位的。","notes":[]},{"n":9,"t":"天使長米迦勒為摩西的屍首與魔鬼爭辯的時候，尚且不敢用毀謗的話罪責他，只說：「主責備你吧！」。","notes":[]},{"n":10,"t":"但這些人毀謗他們所不知道的。他們本性所知道的事與那沒有靈性的畜類一樣，在這事上竟敗壞了自己。","notes":[]},{"n":11,"t":"他們有禍了！因為走了該隱的道路，又為利往巴蘭的錯謬裏直奔，並在可拉的背叛中滅亡了。","notes":[]},{"n":12,"t":"這樣的人在你們的愛席上與你們同吃的時候，正是礁石。他們作牧人，只知餵養自己，無所懼怕；是沒有雨的雲彩，被風飄蕩；是秋天沒有果子的樹，死而又死，連根被拔出來；","notes":["或譯：玷污"]},{"n":13,"t":"是海裏的狂浪，湧出自己可恥的沫子來；是流蕩的星，有墨黑的幽暗為他們永遠存留。","notes":[]},{"n":14,"t":"亞當的七世孫以諾曾預言這些人說：「看哪，主帶著他的千萬聖者降臨，","notes":[]},{"n":15,"t":"要在眾人身上行審判，證實那一切不敬虔的人所妄行一切不敬虔的事，又證實不敬虔之罪人所說頂撞他的剛愎話。」","notes":[]},{"n":16,"t":"這些人是私下議論，常發怨言的，隨從自己的情慾而行，口中說誇大的話，為得便宜諂媚人。","notes":[]},{"n":17,"t":"親愛的弟兄啊，你們要記念我們主耶穌基督之使徒從前所說的話。","notes":[],"heads":["警告和勸勉"]},{"n":18,"t":"他們曾對你們說過，末世必有好譏誚的人隨從自己不敬虔的私慾而行。","notes":[]},{"n":19,"t":"這就是那些引人結黨、屬乎血氣、沒有聖靈的人。","notes":[]},{"n":20,"t":"親愛的弟兄啊，你們卻要在至聖的真道上造就自己，在聖靈裏禱告，","notes":[]},{"n":21,"t":"保守自己常在神的愛中，仰望我們主耶穌基督的憐憫，直到永生。","notes":[]},{"n":22,"t":"有些人存疑心，你們要憐憫他們；","notes":[]},{"n":23,"t":"有些人你們要從火中搶出來，搭救他們；有些人你們要存懼怕的心憐憫他們，連那被情慾沾染的衣服也當厭惡。","notes":[]},{"n":24,"t":"那能保守你們不失腳、叫你們無瑕無疵、歡歡喜喜站在他榮耀之前的我們的救主－獨一的神，","notes":[],"heads":["祝福"]},{"n":25,"t":"願榮耀、威嚴、能力、權柄，因我們的主耶穌基督歸與他，從萬古以前並現今，直到永永遠遠。阿們！","notes":[]}]}},"REV":{"1":{"heading":"引言和致意","verses":[{"n":1,"t":"耶穌基督的啟示，就是神賜給他，叫他將必要快成的事指示他的眾僕人。他就差遣使者曉諭他的僕人約翰。","notes":[]},{"n":2,"t":"約翰便將神的道和耶穌基督的見證，凡自己所看見的都證明出來。","notes":[]},{"n":3,"t":"念這書上預言的和那些聽見又遵守其中所記載的，都是有福的，因為日期近了。","notes":[]},{"n":4,"t":"約翰寫信給亞細亞的七個教會。但願從那昔在、今在、以後永在的神，和他寶座前的七靈，","notes":[]},{"n":5,"t":"並那誠實作見證的、從死裏首先復活、為世上君王元首的耶穌基督，有恩惠、平安歸與你們！他愛我們，用自己的血使我們脫離罪惡，","notes":["有古卷：洗去"]},{"n":6,"t":"又使我們成為國民，作他父神的祭司。但願榮耀、權能歸給他，直到永永遠遠。阿們！","notes":[]},{"n":7,"t":"看哪，他駕雲降臨！眾目要看見他，連刺他的人也要看見他；地上的萬族都要因他哀哭。這話是真實的。阿們！","notes":[]},{"n":8,"t":"主神說：「我是阿拉法，我是俄梅戛，是昔在、今在、以後永在的全能者。」","notes":["阿拉法，俄梅戛：是希臘字母首末二字"]},{"n":9,"t":"我－約翰就是你們的弟兄，和你們在耶穌的患難、國度、忍耐裏一同有分，為神的道，並為給耶穌作的見證，曾在那名叫拔摩的海島上。","notes":[],"heads":["基督的異象"]},{"n":10,"t":"當主日，我被聖靈感動，聽見在我後面有大聲音如吹號，說：","notes":[]},{"n":11,"t":"「你所看見的當寫在書上，達與以弗所、士每拿、別迦摩、推雅推喇、撒狄、非拉鐵非、老底嘉那七個教會。」","notes":[]},{"n":12,"t":"我轉過身來，要看是誰發聲與我說話；既轉過來，就看見七個金燈臺。","notes":[]},{"n":13,"t":"燈臺中間有一位好像人子，身穿長衣，直垂到腳，胸間束著金帶。","notes":[]},{"n":14,"t":"他的頭與髮皆白，如白羊毛，如雪；眼目如同火焰；","notes":[]},{"n":15,"t":"腳好像在爐中鍛鍊光明的銅；聲音如同眾水的聲音。","notes":[]},{"n":16,"t":"他右手拿著七星，從他口中出來一把兩刃的利劍；面貌如同烈日放光。","notes":[]},{"n":17,"t":"我一看見，就仆倒在他腳前，像死了一樣。他用右手按著我，說：「不要懼怕！我是首先的，我是末後的，","notes":[]},{"n":18,"t":"又是那存活的；我曾死過，現在又活了，直活到永永遠遠；並且拿著死亡和陰間的鑰匙。","notes":[]},{"n":19,"t":"所以你要把所看見的，和現在的事，並將來必成的事，都寫出來。","notes":[]},{"n":20,"t":"論到你所看見、在我右手中的七星和七個金燈臺的奧祕，那七星就是七個教會的使者，七燈臺就是七個教會。」","notes":[]}]},"2":{"heading":"給以弗所教會的信","verses":[{"n":1,"t":"「你要寫信給以弗所教會的使者，說：『那右手拿著七星、在七個金燈臺中間行走的，說：","notes":[]},{"n":2,"t":"我知道你的行為、勞碌、忍耐，也知道你不能容忍惡人。你也曾試驗那自稱為使徒卻不是使徒的，看出他們是假的來。","notes":[]},{"n":3,"t":"你也能忍耐，曾為我的名勞苦，並不乏倦。","notes":[]},{"n":4,"t":"然而有一件事我要責備你，就是你把起初的愛心離棄了。","notes":[]},{"n":5,"t":"所以，應當回想你是從哪裏墜落的，並要悔改，行起初所行的事。你若不悔改，我就臨到你那裏，把你的燈臺從原處挪去。","notes":[]},{"n":6,"t":"然而你還有一件可取的事，就是你恨惡尼哥拉一黨人的行為，這也是我所恨惡的。","notes":[]},{"n":7,"t":"聖靈向眾教會所說的話，凡有耳的，就應當聽！得勝的，我必將神樂園中生命樹的果子賜給他吃。』」","notes":[]},{"n":8,"t":"「你要寫信給士每拿教會的使者，說：『那首先的、末後的、死過又活的，說：","notes":[],"heads":["給士每拿教會的信"]},{"n":9,"t":"我知道你的患難，你的貧窮（你卻是富足的），也知道那自稱是猶太人所說的毀謗話，其實他們不是猶太人，乃是撒但一會的人。","notes":[]},{"n":10,"t":"你將要受的苦你不用怕。魔鬼要把你們中間幾個人下在監裏，叫你們被試煉，你們必受患難十日。你務要至死忠心，我就賜給你那生命的冠冕。","notes":[]},{"n":11,"t":"聖靈向眾教會所說的話，凡有耳的，就應當聽！得勝的，必不受第二次死的害。』」","notes":[]},{"n":12,"t":"「你要寫信給別迦摩教會的使者，說：『那有兩刃利劍的，說：","notes":[],"heads":["給別迦摩教會的信"]},{"n":13,"t":"我知道你的居所，就是有撒但座位之處；當我忠心的見證人安提帕在你們中間、撒但所住的地方被殺之時，你還堅守我的名，沒有棄絕我的道。","notes":[]},{"n":14,"t":"然而，有幾件事我要責備你：因為在你那裏有人服從了巴蘭的教訓；這巴蘭曾教導巴勒將絆腳石放在以色列人面前，叫他們吃祭偶像之物，行姦淫的事。","notes":[]},{"n":15,"t":"你那裏也有人照樣服從了尼哥拉一黨人的教訓。","notes":[]},{"n":16,"t":"所以，你當悔改；若不悔改，我就快臨到你那裏，用我口中的劍攻擊他們。","notes":[]},{"n":17,"t":"聖靈向眾教會所說的話，凡有耳的，就應當聽！得勝的，我必將那隱藏的嗎哪賜給他，並賜他一塊白石，石上寫著新名；除了那領受的以外，沒有人能認識。』」","notes":[]},{"n":18,"t":"「你要寫信給推雅推喇教會的使者，說：『那眼目如火焰、腳像光明銅的神之子說：","notes":[],"heads":["給推雅推喇教會的信"]},{"n":19,"t":"我知道你的行為、愛心、信心、勤勞、忍耐，又知道你末後所行的善事，比起初所行的更多。","notes":[]},{"n":20,"t":"然而，有一件事我要責備你，就是你容讓那自稱是先知的婦人耶洗別教導我的僕人，引誘他們行姦淫，吃祭偶像之物。","notes":[]},{"n":21,"t":"我曾給她悔改的機會，她卻不肯悔改她的淫行。","notes":[]},{"n":22,"t":"看哪，我要叫她病臥在床。那些與她行淫的人，若不悔改所行的，我也要叫他們同受大患難。","notes":[]},{"n":23,"t":"我又要殺死她的黨類，叫眾教會知道，我是那察看人肺腑心腸的，並要照你們的行為報應你們各人。","notes":["原文是兒女"]},{"n":24,"t":"至於你們推雅推喇其餘的人，就是一切不從那教訓、不曉得他們素常所說撒但深奧之理的人，我告訴你們，我不將別的擔子放在你們身上。","notes":[]},{"n":25,"t":"但你們已經有的，總要持守，直等到我來。","notes":[]},{"n":26,"t":"那得勝又遵守我命令到底的，我要賜給他權柄制伏列國；","notes":[]},{"n":27,"t":"他必用鐵杖轄管他們，將他們如同窯戶的瓦器打得粉碎，像我從我父領受的權柄一樣。","notes":["轄管：原文是牧"]},{"n":28,"t":"我又要把晨星賜給他。","notes":[]},{"n":29,"t":"聖靈向眾教會所說的話，凡有耳的，就應當聽！』」","notes":[]}]},"3":{"heading":"給撒狄教會的信","verses":[{"n":1,"t":"「你要寫信給撒狄教會的使者，說：『那有神的七靈和七星的，說：我知道你的行為，按名你是活的，其實是死的。","notes":[]},{"n":2,"t":"你要警醒，堅固那剩下將要衰微的；因我見你的行為，在我神面前，沒有一樣是完全的。","notes":["原文是死"]},{"n":3,"t":"所以要回想你是怎樣領受、怎樣聽見的，又要遵守，並要悔改。若不警醒，我必臨到你那裏，如同賊一樣。我幾時臨到，你也決不能知道。","notes":[]},{"n":4,"t":"然而在撒狄，你還有幾名是未曾污穢自己衣服的，他們要穿白衣與我同行，因為他們是配得過的。","notes":[]},{"n":5,"t":"凡得勝的必這樣穿白衣，我也必不從生命冊上塗抹他的名；且要在我父面前，和我父眾使者面前，認他的名。","notes":[]},{"n":6,"t":"聖靈向眾教會所說的話，凡有耳的，就應當聽！』」","notes":[]},{"n":7,"t":"「你要寫信給非拉鐵非教會的使者，說：『那聖潔、真實、拿著大衛的鑰匙、開了就沒有人能關、關了就沒有人能開的，說：","notes":[],"heads":["給非拉鐵非教會的信"]},{"n":8,"t":"我知道你的行為，你略有一點力量，也曾遵守我的道，沒有棄絕我的名。看哪，我在你面前給你一個敞開的門，是無人能關的。","notes":[]},{"n":9,"t":"那撒但一會的，自稱是猶太人，其實不是猶太人，乃是說謊話的，我要使他們來，在你腳前下拜，也使他們知道我是已經愛你了。","notes":[]},{"n":10,"t":"你既遵守我忍耐的道，我必在普天下人受試煉的時候，保守你免去你的試煉。","notes":[]},{"n":11,"t":"我必快來，你要持守你所有的，免得人奪去你的冠冕。","notes":[]},{"n":12,"t":"得勝的，我要叫他在我神殿中作柱子，他也必不再從那裏出去。我又要將我神的名和我神城的名（這城就是從天上、從我神那裏降下來的新耶路撒冷），並我的新名，都寫在他上面。","notes":[]},{"n":13,"t":"聖靈向眾教會所說的話，凡有耳的，就應當聽！』」","notes":[]},{"n":14,"t":"「你要寫信給老底嘉教會的使者，說：『那為阿們的，為誠信真實見證的，在神創造萬物之上為元首的，說：","notes":[],"heads":["給老底嘉教會的信"]},{"n":15,"t":"我知道你的行為，你也不冷也不熱；我巴不得你或冷或熱。","notes":[]},{"n":16,"t":"你既如溫水，也不冷也不熱，所以我必從我口中把你吐出去。","notes":[]},{"n":17,"t":"你說：我是富足，已經發了財，一樣都不缺；卻不知道你是那困苦、可憐、貧窮、瞎眼、赤身的。","notes":[]},{"n":18,"t":"我勸你向我買火煉的金子，叫你富足；又買白衣穿上，叫你赤身的羞恥不露出來；又買眼藥擦你的眼睛，使你能看見。","notes":[]},{"n":19,"t":"凡我所疼愛的，我就責備管教他；所以你要發熱心，也要悔改。","notes":[]},{"n":20,"t":"看哪，我站在門外叩門，若有聽見我聲音就開門的，我要進到他那裏去，我與他，他與我一同坐席。","notes":[]},{"n":21,"t":"得勝的，我要賜他在我寶座上與我同坐，就如我得了勝，在我父的寶座上與他同坐一般。","notes":[]},{"n":22,"t":"聖靈向眾教會所說的話，凡有耳的，就應當聽！』」","notes":[]}]},"4":{"heading":"天上的敬拜","verses":[{"n":1,"t":"此後，我觀看，見天上有門開了。我初次聽見好像吹號的聲音，對我說：「你上到這裏來，我要將以後必成的事指示你。」","notes":[]},{"n":2,"t":"我立刻被聖靈感動，見有一個寶座安置在天上，又有一位坐在寶座上。","notes":[]},{"n":3,"t":"看那坐著的，好像碧玉和紅寶石；又有虹圍著寶座，好像綠寶石。","notes":[]},{"n":4,"t":"寶座的周圍又有二十四個座位；其上坐著二十四位長老，身穿白衣，頭上戴著金冠冕。","notes":[]},{"n":5,"t":"有閃電、聲音、雷轟從寶座中發出；又有七盞火燈在寶座前點著；這七燈就是神的七靈。","notes":[]},{"n":6,"t":"寶座前好像一個玻璃海，如同水晶。寶座中和寶座周圍有四個活物，前後遍體都滿了眼睛。","notes":[]},{"n":7,"t":"第一個活物像獅子，第二個像牛犢，第三個臉面像人，第四個像飛鷹。","notes":[]},{"n":8,"t":"四活物各有六個翅膀，遍體內外都滿了眼睛。他們晝夜不住地說：聖哉！聖哉！聖哉！主神是昔在、今在、以後永在的全能者。","notes":[]},{"n":9,"t":"每逢四活物將榮耀、尊貴、感謝歸給那坐在寶座上、活到永永遠遠者的時候，","notes":[]},{"n":10,"t":"那二十四位長老就俯伏在坐寶座的面前敬拜那活到永永遠遠的，又把他們的冠冕放在寶座前，說：","notes":[]},{"n":11,"t":"我們的主，我們的神，你是配得榮耀、尊貴、權柄的；因為你創造了萬物，並且萬物是因你的旨意被創造而有的。","notes":[]}]},"5":{"heading":"書卷和羔羊","verses":[{"n":1,"t":"我看見坐寶座的右手中有書卷，裏外都寫著字，用七印封嚴了。","notes":[]},{"n":2,"t":"我又看見一位大力的天使大聲宣傳說：「有誰配展開那書卷，揭開那七印呢？」","notes":[]},{"n":3,"t":"在天上、地上、地底下，沒有能展開、能觀看那書卷的。","notes":[]},{"n":4,"t":"因為沒有配展開、配觀看那書卷的，我就大哭。","notes":[]},{"n":5,"t":"長老中有一位對我說：「不要哭！看哪，猶大支派中的獅子，大衛的根，他已得勝，能以展開那書卷，揭開那七印。」","notes":[]},{"n":6,"t":"我又看見寶座與四活物，並長老之中有羔羊站立，像是被殺過的，有七角七眼，就是神的七靈，奉差遣往普天下去的。","notes":[]},{"n":7,"t":"這羔羊前來，從坐寶座的右手裏拿了書卷。","notes":[]},{"n":8,"t":"他既拿了書卷，四活物和二十四位長老就俯伏在羔羊面前，各拿著琴和盛滿了香的金爐；這香就是眾聖徒的祈禱。","notes":[]},{"n":9,"t":"他們唱新歌，說：你配拿書卷，配揭開七印；因為你曾被殺，用自己的血從各族、各方、各民、各國中買了人來，叫他們歸於神，","notes":[]},{"n":10,"t":"又叫他們成為國民，作祭司歸於神，在地上執掌王權。","notes":[]},{"n":11,"t":"我又看見且聽見，寶座與活物並長老的周圍有許多天使的聲音；他們的數目有千千萬萬，","notes":[]},{"n":12,"t":"大聲說：曾被殺的羔羊是配得權柄、豐富、智慧、能力、尊貴、榮耀、頌讚的。","notes":[]},{"n":13,"t":"我又聽見在天上、地上、地底下、滄海裏，和天地間一切所有被造之物，都說：但願頌讚、尊貴、榮耀、權勢都歸給坐寶座的和羔羊，直到永永遠遠！","notes":[]},{"n":14,"t":"四活物就說：「阿們！」眾長老也俯伏敬拜。","notes":[]}]},"6":{"heading":"揭開封嚴的印","verses":[{"n":1,"t":"我看見羔羊揭開七印中第一印的時候，就聽見四活物中的一個活物，聲音如雷，說：「你來！」","notes":[]},{"n":2,"t":"我就觀看，見有一匹白馬；騎在馬上的，拿著弓，並有冠冕賜給他。他便出來，勝了又要勝。","notes":[]},{"n":3,"t":"揭開第二印的時候，我聽見第二個活物說：「你來！」","notes":[]},{"n":4,"t":"就另有一匹馬出來，是紅的，有權柄給了那騎馬的，可以從地上奪去太平，使人彼此相殺；又有一把大刀賜給他。","notes":[]},{"n":5,"t":"揭開第三印的時候，我聽見第三個活物說：「你來！」我就觀看，見有一匹黑馬；騎在馬上的，手裏拿著天平。","notes":[]},{"n":6,"t":"我聽見在四活物中似乎有聲音說：「一錢銀子買一升麥子，一錢銀子買三升大麥；油和酒不可糟蹋。」","notes":[]},{"n":7,"t":"揭開第四印的時候，我聽見第四個活物說：「你來！」","notes":[]},{"n":8,"t":"我就觀看，見有一匹灰色馬；騎在馬上的，名字叫作死，陰府也隨著他；有權柄賜給他們，可以用刀劍、饑荒、瘟疫、野獸，殺害地上四分之一的人。","notes":["或譯：死亡"]},{"n":9,"t":"揭開第五印的時候，我看見在祭壇底下，有為神的道、並為作見證被殺之人的靈魂，","notes":[]},{"n":10,"t":"大聲喊著說：「聖潔真實的主啊，你不審判住在地上的人，給我們伸流血的冤，要等到幾時呢？」","notes":[]},{"n":11,"t":"於是有白衣賜給他們各人；又有話對他們說，還要安息片時，等著一同作僕人的和他們的弟兄也像他們被殺，滿足了數目。","notes":[]},{"n":12,"t":"揭開第六印的時候，我又看見地大震動，日頭變黑像毛布，滿月變紅像血，","notes":[]},{"n":13,"t":"天上的星辰墜落於地，如同無花果樹被大風搖動，落下未熟的果子一樣。","notes":[]},{"n":14,"t":"天就挪移，好像書卷被捲起來；山嶺海島都被挪移離開本位。","notes":[]},{"n":15,"t":"地上的君王、臣宰、將軍、富戶、壯士，和一切為奴的、自主的，都藏在山洞和巖石穴裏，","notes":[]},{"n":16,"t":"向山和巖石說：「倒在我們身上吧！把我們藏起來，躲避坐寶座者的面目和羔羊的忿怒；","notes":[]},{"n":17,"t":"因為他們忿怒的大日到了，誰能站得住呢？」","notes":[]}]},"7":{"heading":"以色列人十四萬四千被印","verses":[{"n":1,"t":"此後，我看見四位天使站在地的四角，執掌地上四方的風，叫風不吹在地上、海上，和樹上。","notes":[]},{"n":2,"t":"我又看見另有一位天使，從日出之地上來，拿著永生神的印。他就向那得著權柄能傷害地和海的四位天使大聲喊著說：","notes":[]},{"n":3,"t":"「地與海並樹木，你們不可傷害，等我們印了我們神眾僕人的額。」","notes":[]},{"n":4,"t":"我聽見以色列人各支派中受印的數目有十四萬四千。","notes":[]},{"n":5,"t":"猶大支派中受印的有一萬二千；呂便支派中有一萬二千；迦得支派中有一萬二千；","notes":[]},{"n":6,"t":"亞設支派中有一萬二千；拿弗他利支派中有一萬二千；瑪拿西支派中有一萬二千；","notes":[]},{"n":7,"t":"西緬支派中有一萬二千；利未支派中有一萬二千；以薩迦支派中有一萬二千；","notes":[]},{"n":8,"t":"西布倫支派中有一萬二千；約瑟支派中有一萬二千；便雅憫支派中受印的有一萬二千。","notes":[]},{"n":9,"t":"此後，我觀看，見有許多的人，沒有人能數過來，是從各國、各族、各民、各方來的，站在寶座和羔羊面前，身穿白衣，手拿棕樹枝，","notes":[],"heads":["無數的人從各國各族而來"]},{"n":10,"t":"大聲喊著說：「願救恩歸與坐在寶座上我們的神，也歸與羔羊！」","notes":[]},{"n":11,"t":"眾天使都站在寶座和眾長老並四活物的周圍，在寶座前，面伏於地，敬拜神，","notes":[]},{"n":12,"t":"說：阿們！頌讚、榮耀、智慧、感謝、尊貴、權柄、大力都歸與我們的神，直到永永遠遠。阿們！","notes":[]},{"n":13,"t":"長老中有一位問我說：「這些穿白衣的是誰？是從哪裏來的？」","notes":[]},{"n":14,"t":"我對他說：「我主，你知道。」他向我說：「這些人是從大患難中出來的，曾用羔羊的血把衣裳洗白淨了。","notes":[]},{"n":15,"t":"所以，他們在神寶座前，晝夜在他殿中事奉他。坐寶座的要用帳幕覆庇他們。","notes":[]},{"n":16,"t":"他們不再飢，不再渴；日頭和炎熱也必不傷害他們。","notes":[]},{"n":17,"t":"因為寶座中的羔羊必牧養他們，領他們到生命水的泉源；神也必擦去他們一切的眼淚。」","notes":[]}]},"8":{"heading":"第七印和香爐","verses":[{"n":1,"t":"羔羊揭開第七印的時候，天上寂靜約有二刻。","notes":[]},{"n":2,"t":"我看見那站在神面前的七位天使，有七枝號賜給他們。","notes":[]},{"n":3,"t":"另有一位天使，拿著金香爐來，站在祭壇旁邊。有許多香賜給他，要和眾聖徒的祈禱一同獻在寶座前的金壇上。","notes":[]},{"n":4,"t":"那香的煙和眾聖徒的祈禱從天使的手中一同升到神面前。","notes":[]},{"n":5,"t":"天使拿著香爐，盛滿了壇上的火，倒在地上；隨有雷轟、大聲、閃電、地震。","notes":[]},{"n":6,"t":"拿著七枝號的七位天使就預備要吹。","notes":[],"heads":["七號"]},{"n":7,"t":"第一位天使吹號，就有雹子與火攙著血丟在地上；地的三分之一和樹的三分之一被燒了，一切的青草也被燒了。","notes":[]},{"n":8,"t":"第二位天使吹號，就有彷彿火燒著的大山扔在海中；海的三分之一變成血，","notes":[]},{"n":9,"t":"海中的活物死了三分之一，船隻也壞了三分之一。","notes":[]},{"n":10,"t":"第三位天使吹號，就有燒著的大星，好像火把從天上落下來，落在江河的三分之一和眾水的泉源上。","notes":[]},{"n":11,"t":"（這星名叫「茵蔯」。）眾水的三分之一變為茵蔯，因水變苦，就死了許多人。","notes":[]},{"n":12,"t":"第四位天使吹號，日頭的三分之一、月亮的三分之一、星辰的三分之一都被擊打，以致日月星的三分之一黑暗了，白晝的三分之一沒有光，黑夜也是這樣。","notes":[]},{"n":13,"t":"我又看見一個鷹飛在空中，並聽見牠大聲說：「三位天使要吹那其餘的號。你們住在地上的民，禍哉！禍哉！禍哉！」","notes":[]}]},"9":{"heading":"","verses":[{"n":1,"t":"第五位天使吹號，我就看見一個星從天落到地上，有無底坑的鑰匙賜給它。","notes":[]},{"n":2,"t":"它開了無底坑，便有煙從坑裏往上冒，好像大火爐的煙；日頭和天空都因這煙昏暗了。","notes":[]},{"n":3,"t":"有蝗蟲從煙中出來，飛到地上；有能力賜給牠們，好像地上蠍子的能力一樣，","notes":[]},{"n":4,"t":"並且吩咐牠們說，不可傷害地上的草和各樣青物，並一切樹木，惟獨要傷害額上沒有神印記的人。","notes":[]},{"n":5,"t":"但不許蝗蟲害死他們，只叫他們受痛苦五個月。這痛苦就像蠍子螫人的痛苦一樣。","notes":[]},{"n":6,"t":"在那些日子，人要求死，決不得死；願意死，死卻遠避他們。","notes":[]},{"n":7,"t":"蝗蟲的形狀，好像預備出戰的馬一樣，頭上戴的好像金冠冕，臉面好像男人的臉面，","notes":[]},{"n":8,"t":"頭髮像女人的頭髮，牙齒像獅子的牙齒。","notes":[]},{"n":9,"t":"胸前有甲，好像鐵甲。牠們翅膀的聲音，好像許多車馬奔跑上陣的聲音。","notes":[]},{"n":10,"t":"有尾巴像蠍子，尾巴上的毒鉤能傷人五個月。","notes":[]},{"n":11,"t":"有無底坑的使者作牠們的王，按著希伯來話，名叫亞巴頓，希臘話，名叫亞玻倫。","notes":[]},{"n":12,"t":"第一樣災禍過去了，還有兩樣災禍要來。","notes":[]},{"n":13,"t":"第六位天使吹號，我就聽見有聲音從神面前金壇的四角出來，","notes":[]},{"n":14,"t":"吩咐那吹號的第六位天使，說：「把那捆綁在幼發拉底大河的四個使者釋放了。」","notes":[]},{"n":15,"t":"那四個使者就被釋放；他們原是預備好了，到某年某月某日某時，要殺人的三分之一。","notes":[]},{"n":16,"t":"馬軍有二萬萬；他們的數目我聽見了。","notes":[]},{"n":17,"t":"我在異象中看見那些馬和騎馬的，騎馬的胸前有甲如火，與紫瑪瑙並硫磺。馬的頭好像獅子頭，有火、有煙、有硫磺從馬的口中出來。","notes":[]},{"n":18,"t":"口中所出來的火與煙並硫磺，這三樣災殺了人的三分之一。","notes":[]},{"n":19,"t":"這馬的能力是在口裏和尾巴上；因這尾巴像蛇，並且有頭用以害人。","notes":[]},{"n":20,"t":"其餘未曾被這些災所殺的人仍舊不悔改自己手所做的，還是去拜鬼魔和那些不能看、不能聽、不能走，金、銀、銅、木、石的偶像，","notes":[]},{"n":21,"t":"又不悔改他們那些凶殺、邪術、姦淫、偷竊的事。","notes":[]}]},"10":{"heading":"天使和小書卷","verses":[{"n":1,"t":"我又看見另有一位大力的天使從天降下，披著雲彩，頭上有虹，臉面像日頭，兩腳像火柱。","notes":[]},{"n":2,"t":"他手裏拿著小書卷，是展開的。他右腳踏海，左腳踏地，","notes":[]},{"n":3,"t":"大聲呼喊，好像獅子吼叫。呼喊完了，就有七雷發聲。","notes":[]},{"n":4,"t":"七雷發聲之後，我正要寫出來，就聽見從天上有聲音說：「七雷所說的，你要封上，不可寫出來。」","notes":[]},{"n":5,"t":"我所看見的那踏海踏地的天使向天舉起右手來，","notes":[]},{"n":6,"t":"指著那創造天和天上之物，地和地上之物，海和海中之物，直活到永永遠遠的，起誓說：「不再有時日了。」","notes":["或譯：不再耽延了"]},{"n":7,"t":"但在第七位天使吹號發聲的時候，神的奧祕就成全了，正如神所傳給他僕人眾先知的佳音。","notes":[]},{"n":8,"t":"我先前從天上所聽見的那聲音又吩咐我說：「你去，把那踏海踏地之天使手中展開的小書卷取過來。」","notes":[]},{"n":9,"t":"我就走到天使那裏，對他說：「請你把小書卷給我。」他對我說：「你拿著吃盡了，便叫你肚子發苦，然而在你口中要甜如蜜。」","notes":[]},{"n":10,"t":"我從天使手中把小書卷接過來，吃盡了，在我口中果然甜如蜜，吃了以後，肚子覺得發苦了。","notes":[]},{"n":11,"t":"天使對我說：「你必指著多民、多國、多方、多王再說預言。」","notes":["原文是他們"]}]},"11":{"heading":"兩個見證人","verses":[{"n":1,"t":"有一根葦子賜給我，當作量度的杖；且有話說：「起來！將神的殿和祭壇，並在殿中禮拜的人都量一量。","notes":[]},{"n":2,"t":"只是殿外的院子要留下不用量，因為這是給了外邦人的；他們要踐踏聖城四十二個月。","notes":[]},{"n":3,"t":"我要使我那兩個見證人，穿著毛衣，傳道一千二百六十天。」","notes":[]},{"n":4,"t":"他們就是那兩棵橄欖樹，兩個燈臺，立在世界之主面前的。","notes":[]},{"n":5,"t":"若有人想要害他們，就有火從他們口中出來，燒滅仇敵。凡想要害他們的都必這樣被殺。","notes":[]},{"n":6,"t":"這二人有權柄，在他們傳道的日子叫天閉塞不下雨；又有權柄叫水變為血，並且能隨時隨意用各樣的災殃攻擊世界。","notes":[]},{"n":7,"t":"他們作完見證的時候，那從無底坑裏上來的獸必與他們交戰，並且得勝，把他們殺了。","notes":[]},{"n":8,"t":"他們的屍首就倒在大城裏的街上；這城按著靈意叫所多瑪，又叫埃及，就是他們的主釘十字架之處。","notes":[]},{"n":9,"t":"從各民、各族、各方、各國中，有人觀看他們的屍首三天半，又不許把屍首放在墳墓裏。","notes":[]},{"n":10,"t":"住在地上的人就為他們歡喜快樂，互相餽送禮物，因這兩位先知曾叫住在地上的人受痛苦。","notes":[]},{"n":11,"t":"過了這三天半，有生氣從神那裏進入他們裏面，他們就站起來；看見他們的人甚是害怕。","notes":[]},{"n":12,"t":"兩位先知聽見有大聲音從天上來，對他們說：「上到這裏來。」他們就駕著雲上了天，他們的仇敵也看見了。","notes":[]},{"n":13,"t":"正在那時候，地大震動，城就倒塌了十分之一，因地震而死的有七千人；其餘的都恐懼，歸榮耀給天上的神。","notes":[]},{"n":14,"t":"第二樣災禍過去，第三樣災禍快到了。","notes":[]},{"n":15,"t":"第七位天使吹號，天上就有大聲音說：世上的國成了我主和主基督的國；他要作王，直到永永遠遠。","notes":[],"heads":["第七號"]},{"n":16,"t":"在神面前，坐在自己位上的二十四位長老，就面伏於地，敬拜神，","notes":[]},{"n":17,"t":"說：昔在、今在的主神－全能者啊，我們感謝你！因你執掌大權作王了。","notes":[]},{"n":18,"t":"外邦發怒，你的忿怒也臨到了；審判死人的時候也到了。你的僕人眾先知和眾聖徒，凡敬畏你名的人，連大帶小得賞賜的時候也到了。你敗壞那些敗壞世界之人的時候也就到了。","notes":[]},{"n":19,"t":"當時，神天上的殿開了，在他殿中現出他的約櫃。隨後有閃電、聲音、雷轟、地震、大雹。","notes":[]}]},"12":{"heading":"婦人和龍","verses":[{"n":1,"t":"天上現出大異象來：有一個婦人身披日頭，腳踏月亮，頭戴十二星的冠冕。","notes":[]},{"n":2,"t":"她懷了孕，在生產的艱難中疼痛呼叫。","notes":[]},{"n":3,"t":"天上又現出異象來：有一條大紅龍，七頭十角；七頭上戴著七個冠冕。","notes":[]},{"n":4,"t":"牠的尾巴拖拉著天上星辰的三分之一，摔在地上。龍就站在那將要生產的婦人面前，等她生產之後，要吞吃她的孩子。","notes":[]},{"n":5,"t":"婦人生了一個男孩子，是將來要用鐵杖轄管萬國的；她的孩子被提到神寶座那裏去了。","notes":["轄管：原文是牧"]},{"n":6,"t":"婦人就逃到曠野，在那裏有神給她預備的地方，使她被養活一千二百六十天。","notes":[]},{"n":7,"t":"在天上就有了爭戰。米迦勒同他的使者與龍爭戰，龍也同牠的使者去爭戰，","notes":[]},{"n":8,"t":"並沒有得勝，天上再沒有牠們的地方。","notes":[]},{"n":9,"t":"大龍就是那古蛇，名叫魔鬼，又叫撒但，是迷惑普天下的。牠被摔在地上，牠的使者也一同被摔下去。","notes":[]},{"n":10,"t":"我聽見在天上有大聲音說：「我神的救恩、能力、國度，並他基督的權柄，現在都來到了！因為那在我們神面前晝夜控告我們弟兄的，已經被摔下去了。","notes":[]},{"n":11,"t":"弟兄勝過牠，是因羔羊的血和自己所見證的道。他們雖至於死，也不愛惜性命。","notes":[]},{"n":12,"t":"所以，諸天和住在其中的，你們都快樂吧！只是地與海有禍了！因為魔鬼知道自己的時候不多，就氣忿忿地下到你們那裏去了。」","notes":[]},{"n":13,"t":"龍見自己被摔在地上，就逼迫那生男孩子的婦人。","notes":[]},{"n":14,"t":"於是有大鷹的兩個翅膀賜給婦人，叫她能飛到曠野，到自己的地方，躲避那蛇；她在那裏被養活一載二載半載。","notes":[]},{"n":15,"t":"蛇就在婦人身後，從口中吐出水來，像河一樣，要將婦人沖去。","notes":[]},{"n":16,"t":"地卻幫助婦人，開口吞了從龍口吐出來的水。","notes":["原文是河"]},{"n":17,"t":"龍向婦人發怒，去與她其餘的兒女爭戰，這兒女就是那守神誡命、為耶穌作見證的。","notes":[]},{"n":18,"t":"那時龍就站在海邊的沙上。","notes":[]}]},"13":{"heading":"兩個獸","verses":[{"n":1,"t":"我又看見一個獸從海中上來，有十角七頭，在十角上戴著十個冠冕，七頭上有褻瀆的名號。","notes":[]},{"n":2,"t":"我所看見的獸，形狀像豹，腳像熊的腳，口像獅子的口。那龍將自己的能力、座位，和大權柄都給了牠。","notes":[]},{"n":3,"t":"我看見獸的七頭中，有一個似乎受了死傷，那死傷卻醫好了。全地的人都希奇跟從那獸，","notes":[]},{"n":4,"t":"又拜那龍－因為牠將自己的權柄給了獸，也拜獸，說：「誰能比這獸，誰能與牠交戰呢？」","notes":[]},{"n":5,"t":"又賜給牠說誇大褻瀆話的口，又有權柄賜給牠，可以任意而行四十二個月。","notes":[]},{"n":6,"t":"獸就開口向神說褻瀆的話，褻瀆神的名並他的帳幕，以及那些住在天上的。","notes":[]},{"n":7,"t":"又任憑牠與聖徒爭戰，並且得勝；也把權柄賜給牠，制伏各族、各民、各方、各國。","notes":[]},{"n":8,"t":"凡住在地上、名字從創世以來沒有記在被殺之羔羊生命冊上的人，都要拜牠。","notes":[]},{"n":9,"t":"凡有耳的，就應當聽！","notes":[]},{"n":10,"t":"擄掠人的，必被擄掠；用刀殺人的，必被刀殺。聖徒的忍耐和信心就是在此。","notes":[]},{"n":11,"t":"我又看見另有一個獸從地中上來，有兩角如同羊羔，說話好像龍。","notes":[]},{"n":12,"t":"牠在頭一個獸面前，施行頭一個獸所有的權柄，並且叫地和住在地上的人拜那死傷醫好的頭一個獸。","notes":[]},{"n":13,"t":"又行大奇事，甚至在人面前，叫火從天降在地上。","notes":[]},{"n":14,"t":"牠因賜給牠權柄在獸面前能行奇事，就迷惑住在地上的人，說：「要給那受刀傷還活著的獸作個像。」","notes":[]},{"n":15,"t":"又有權柄賜給牠，叫獸像有生氣，並且能說話，又叫所有不拜獸像的人都被殺害。","notes":[]},{"n":16,"t":"牠又叫眾人，無論大小、貧富、自主的、為奴的，都在右手上或是在額上受一個印記。","notes":[]},{"n":17,"t":"除了那受印記、有了獸名或有獸名數目的，都不得做買賣。","notes":[]},{"n":18,"t":"在這裏有智慧：凡有聰明的，可以算計獸的數目；因為這是人的數目，它的數目是六百六十六。","notes":[]}]},"14":{"heading":"十四萬四千人的歌","verses":[{"n":1,"t":"我又觀看，見羔羊站在錫安山，同他又有十四萬四千人，都有他的名和他父的名寫在額上。","notes":[]},{"n":2,"t":"我聽見從天上有聲音，像眾水的聲音和大雷的聲音，並且我所聽見的好像彈琴的所彈的琴聲。","notes":[]},{"n":3,"t":"他們在寶座前，並在四活物和眾長老前唱歌，彷彿是新歌；除了從地上買來的那十四萬四千人以外，沒有人能學這歌。","notes":[]},{"n":4,"t":"這些人未曾沾染婦女，他們原是童身。羔羊無論往哪裏去，他們都跟隨他。他們是從人間買來的，作初熟的果子歸與神和羔羊。","notes":[]},{"n":5,"t":"在他們口中察不出謊言來；他們是沒有瑕疵的。","notes":[]},{"n":6,"t":"我又看見另有一位天使飛在空中，有永遠的福音要傳給住在地上的人，就是各國、各族、各方、各民。","notes":[],"heads":["三位天使的信息"]},{"n":7,"t":"他大聲說：「應當敬畏神，將榮耀歸給他！因他施行審判的時候已經到了。應當敬拜那創造天地海和眾水泉源的。」","notes":[]},{"n":8,"t":"又有第二位天使接著說：「叫萬民喝邪淫、大怒之酒的巴比倫大城傾倒了！傾倒了！」","notes":[]},{"n":9,"t":"又有第三位天使接著他們，大聲說：「若有人拜獸和獸像，在額上或在手上受了印記，","notes":[]},{"n":10,"t":"這人也必喝神大怒的酒；此酒斟在神忿怒的杯中純一不雜。他要在聖天使和羔羊面前，在火與硫磺之中受痛苦。","notes":[]},{"n":11,"t":"他受痛苦的煙往上冒，直到永永遠遠。那些拜獸和獸像，受牠名之印記的，晝夜不得安寧。」","notes":[]},{"n":12,"t":"聖徒的忍耐就在此；他們是守神誡命和耶穌真道的。","notes":[]},{"n":13,"t":"我聽見從天上有聲音說：「你要寫下：從今以後，在主裏面而死的人有福了！」聖靈說：「是的，他們息了自己的勞苦，做工的果效也隨著他們。」","notes":[]},{"n":14,"t":"我又觀看，見有一片白雲，雲上坐著一位好像人子，頭上戴著金冠冕，手裏拿著快鐮刀。","notes":[],"heads":["地上的收割"]},{"n":15,"t":"又有一位天使從殿中出來，向那坐在雲上的大聲喊著說：「伸出你的鐮刀來收割；因為收割的時候已經到了，地上的莊稼已經熟透了。」","notes":[]},{"n":16,"t":"那坐在雲上的，就把鐮刀扔在地上，地上的莊稼就被收割了。","notes":[]},{"n":17,"t":"又有一位天使從天上的殿中出來，他也拿著快鐮刀。","notes":[]},{"n":18,"t":"又有一位天使從祭壇中出來，是有權柄管火的，向拿著快鐮刀的大聲喊著說：「伸出快鐮刀來，收取地上葡萄樹的果子，因為葡萄熟透了！」","notes":[]},{"n":19,"t":"那天使就把鐮刀扔在地上，收取了地上的葡萄，丟在神忿怒的大酒醡中。","notes":[]},{"n":20,"t":"那酒醡踹在城外，就有血從酒醡裏流出來，高到馬的嚼環，遠有六百里。","notes":[]}]},"15":{"heading":"七位天使掌管最後的災","verses":[{"n":1,"t":"我又看見在天上有異象，大而且奇，就是七位天使掌管末了的七災，因為神的大怒在這七災中發盡了。","notes":[]},{"n":2,"t":"我看見彷彿有玻璃海，其中有火攙雜。又看見那些勝了獸和獸的像並牠名字數目的人，都站在玻璃海上，拿著神的琴，","notes":[]},{"n":3,"t":"唱神僕人摩西的歌和羔羊的歌，說：主神－全能者啊，你的作為大哉！奇哉！萬世之王啊，你的道途義哉！誠哉！","notes":["或譯：國"]},{"n":4,"t":"主啊，誰敢不敬畏你，不將榮耀歸與你的名呢？因為獨有你是聖的。萬民都要來在你面前敬拜，因你公義的作為已經顯出來了。","notes":[]},{"n":5,"t":"此後，我看見在天上那存法櫃的殿開了。","notes":[]},{"n":6,"t":"那掌管七災的七位天使從殿中出來，穿著潔白光明的細麻衣，胸間束著金帶。","notes":["細麻衣：有古卷是寶石"]},{"n":7,"t":"四活物中有一個把盛滿了活到永永遠遠之神大怒的七個金碗給了那七位天使。","notes":[]},{"n":8,"t":"因神的榮耀和能力，殿中充滿了煙。於是沒有人能以進殿，直等到那七位天使所降的七災完畢了。","notes":[]}]},"16":{"heading":"神大怒的碗","verses":[{"n":1,"t":"我聽見有大聲音從殿中出來，向那七位天使說：「你們去，把盛神大怒的七碗倒在地上。」","notes":[]},{"n":2,"t":"第一位天使便去，把碗倒在地上，就有惡而且毒的瘡生在那些有獸印記、拜獸像的人身上。","notes":[]},{"n":3,"t":"第二位天使把碗倒在海裏，海就變成血，好像死人的血，海中的活物都死了。","notes":[]},{"n":4,"t":"第三位天使把碗倒在江河與眾水的泉源裏，水就變成血了。","notes":[]},{"n":5,"t":"我聽見掌管眾水的天使說：昔在、今在的聖者啊，你這樣判斷是公義的；","notes":[]},{"n":6,"t":"他們曾流聖徒與先知的血，現在你給他們血喝；這是他們所該受的。","notes":[]},{"n":7,"t":"我又聽見祭壇中有聲音說：是的，主神－全能者啊，你的判斷義哉！誠哉！","notes":[]},{"n":8,"t":"第四位天使把碗倒在日頭上，叫日頭能用火烤人。","notes":[]},{"n":9,"t":"人被大熱所烤，就褻瀆那有權掌管這些災的神之名，並不悔改將榮耀歸給神。","notes":[]},{"n":10,"t":"第五位天使把碗倒在獸的座位上，獸的國就黑暗了。人因疼痛就咬自己的舌頭；","notes":[]},{"n":11,"t":"又因所受的疼痛，和生的瘡，就褻瀆天上的神，並不悔改所行的。","notes":[]},{"n":12,"t":"第六位天使把碗倒在幼發拉底大河上，河水就乾了，要給那從日出之地所來的眾王預備道路。","notes":[]},{"n":13,"t":"我又看見三個污穢的靈，好像青蛙，從龍口、獸口並假先知的口中出來。","notes":[]},{"n":14,"t":"他們本是鬼魔的靈，施行奇事，出去到普天下眾王那裏，叫他們在神全能者的大日聚集爭戰。（","notes":[]},{"n":15,"t":"看哪，我來像賊一樣。那警醒、看守衣服、免得赤身而行、叫人見他羞恥的有福了！）","notes":[]},{"n":16,"t":"那三個鬼魔便叫眾王聚集在一處，希伯來話叫作哈米吉多頓。","notes":[]},{"n":17,"t":"第七位天使把碗倒在空中，就有大聲音從殿中的寶座上出來，說：「成了！」","notes":[]},{"n":18,"t":"又有閃電、聲音、雷轟、大地震，自從地上有人以來，沒有這樣大、這樣厲害的地震。","notes":[]},{"n":19,"t":"那大城裂為三段，列國的城也都倒塌了；神也想起巴比倫大城來，要把那盛自己烈怒的酒杯遞給他。","notes":[]},{"n":20,"t":"各海島都逃避了，眾山也不見了。","notes":[]},{"n":21,"t":"又有大雹子從天落在人身上，每一個約重一他連得。為這雹子的災極大，人就褻瀆神。","notes":["一他連得約有九十斤"]}]},"17":{"heading":"大淫婦和獸","verses":[{"n":1,"t":"拿著七碗的七位天使中，有一位前來對我說：「你到這裏來，我將坐在眾水上的大淫婦所要受的刑罰指給你看。","notes":[]},{"n":2,"t":"地上的君王與她行淫，住在地上的人喝醉了她淫亂的酒。」","notes":[]},{"n":3,"t":"我被聖靈感動，天使帶我到曠野去，我就看見一個女人騎在朱紅色的獸上；那獸有七頭十角，遍體有褻瀆的名號。","notes":[]},{"n":4,"t":"那女人穿著紫色和朱紅色的衣服，用金子、寶石、珍珠為妝飾；手拿金杯，杯中盛滿了可憎之物，就是她淫亂的污穢。","notes":[]},{"n":5,"t":"在她額上有名寫著說：「奧祕哉！大巴比倫，作世上的淫婦和一切可憎之物的母。」","notes":[]},{"n":6,"t":"我又看見那女人喝醉了聖徒的血和為耶穌作見證之人的血。我看見她，就大大地希奇。","notes":[]},{"n":7,"t":"天使對我說：「你為甚麼希奇呢？我要將這女人和馱著她的那七頭十角獸的奧祕告訴你。","notes":[]},{"n":8,"t":"你所看見的獸，先前有，如今沒有，將要從無底坑裏上來，又要歸於沉淪。凡住在地上、名字從創世以來沒有記在生命冊上的，見先前有、如今沒有、以後再有的獸，就必希奇。","notes":[]},{"n":9,"t":"智慧的心在此可以思想。那七頭就是女人所坐的七座山，","notes":[]},{"n":10,"t":"又是七位王；五位已經傾倒了，一位還在，一位還沒有來到；他來的時候，必須暫時存留。","notes":[]},{"n":11,"t":"那先前有如今沒有的獸，就是第八位；他也和那七位同列，並且歸於沉淪。","notes":[]},{"n":12,"t":"你所看見的那十角就是十王；他們還沒有得國，但他們一時之間要和獸同得權柄，與王一樣。","notes":[]},{"n":13,"t":"他們同心合意將自己的能力、權柄給那獸。","notes":[]},{"n":14,"t":"他們與羔羊爭戰，羔羊必勝過他們，因為羔羊是萬主之主、萬王之王。同著羔羊的，就是蒙召、被選、有忠心的，也必得勝。」","notes":[]},{"n":15,"t":"天使又對我說：「你所看見那淫婦坐的眾水，就是多民、多人、多國、多方。","notes":[]},{"n":16,"t":"你所看見的那十角與獸必恨這淫婦，使她冷落赤身，又要吃她的肉，用火將她燒盡。","notes":[]},{"n":17,"t":"因為神使諸王同心合意，遵行他的旨意，把自己的國給那獸，直等到神的話都應驗了。","notes":[]},{"n":18,"t":"你所看見的那女人就是管轄地上眾王的大城。」","notes":[]}]},"18":{"heading":"巴比倫傾倒","verses":[{"n":1,"t":"此後，我看見另有一位有大權柄的天使從天降下，地就因他的榮耀發光。","notes":[]},{"n":2,"t":"他大聲喊著說：巴比倫大城傾倒了！傾倒了！成了鬼魔的住處和各樣污穢之靈的巢穴，並各樣污穢可憎之雀鳥的巢穴。","notes":["或譯：牢獄；下同"]},{"n":3,"t":"因為列國都被她邪淫大怒的酒傾倒了。地上的君王與她行淫；地上的客商因她奢華太過就發了財。","notes":[]},{"n":4,"t":"我又聽見從天上有聲音說：我的民哪，你們要從那城出來，免得與她一同有罪，受她所受的災殃；","notes":[]},{"n":5,"t":"因她的罪惡滔天；她的不義，神已經想起來了。","notes":[]},{"n":6,"t":"她怎樣待人，也要怎樣待她，按她所行的加倍地報應她；用她調酒的杯加倍地調給她喝。","notes":[]},{"n":7,"t":"她怎樣榮耀自己，怎樣奢華，也當叫她照樣痛苦悲哀，因她心裏說：我坐了皇后的位，並不是寡婦，決不至於悲哀。","notes":[]},{"n":8,"t":"所以在一天之內，她的災殃要一齊來到，就是死亡、悲哀、饑荒。她又要被火燒盡了，因為審判她的主神大有能力。","notes":[]},{"n":9,"t":"地上的君王，素來與她行淫、一同奢華的，看見燒她的煙，就必為她哭泣哀號。","notes":[]},{"n":10,"t":"因怕她的痛苦，就遠遠地站著說：哀哉！哀哉！巴比倫大城，堅固的城啊，一時之間你的刑罰就來到了。","notes":[]},{"n":11,"t":"地上的客商也都為她哭泣悲哀，因為沒有人再買他們的貨物了；","notes":[]},{"n":12,"t":"這貨物就是金、銀、寶石、珍珠、細麻布、紫色料、綢子、朱紅色料、各樣香木、各樣象牙的器皿、各樣極寶貴的木頭，和銅、鐵、漢白玉的器皿，","notes":[]},{"n":13,"t":"並肉桂、荳蔻、香料、香膏、乳香、酒、油、細麵、麥子、牛、羊、車、馬，和奴僕、人口。","notes":[]},{"n":14,"t":"巴比倫哪，你所貪愛的果子離開了你；你一切的珍饈美味和華美的物件也從你中間毀滅，決不能再見了。","notes":[]},{"n":15,"t":"販賣這些貨物、藉著她發了財的客商，因怕她的痛苦，就遠遠地站著哭泣悲哀，說：","notes":[]},{"n":16,"t":"哀哉！哀哉！這大城啊，素常穿著細麻、紫色、朱紅色的衣服，又用金子、寶石，和珍珠為妝飾。","notes":[]},{"n":17,"t":"一時之間，這麼大的富厚就歸於無有了。凡船主和坐船往各處去的，並眾水手，連所有靠海為業的，都遠遠地站著，","notes":[]},{"n":18,"t":"看見燒她的煙，就喊著說：「有何城能比這大城呢？」","notes":[]},{"n":19,"t":"他們又把塵土撒在頭上，哭泣悲哀，喊著說：哀哉！哀哉！這大城啊。凡有船在海中的，都因她的珍寶成了富足！她在一時之間就成了荒場！","notes":[]},{"n":20,"t":"天哪，眾聖徒、眾使徒、眾先知啊，你們都要因她歡喜，因為神已經在她身上伸了你們的冤。","notes":[]},{"n":21,"t":"有一位大力的天使舉起一塊石頭，好像大磨石，扔在海裏，說：巴比倫大城也必這樣猛力地被扔下去，決不能再見了。","notes":[]},{"n":22,"t":"彈琴、作樂、吹笛、吹號的聲音，在你中間決不能再聽見；各行手藝人在你中間決不能再遇見；推磨的聲音在你中間決不能再聽見；","notes":[]},{"n":23,"t":"燈光在你中間決不能再照耀；新郎和新婦的聲音，在你中間決不能再聽見。你的客商原來是地上的尊貴人；萬國也被你的邪術迷惑了。","notes":[]},{"n":24,"t":"先知和聖徒，並地上一切被殺之人的血，都在這城裏看見了。","notes":[]}]},"19":{"heading":"羔羊的婚筵","verses":[{"n":1,"t":"此後，我聽見好像群眾在天上大聲說：哈利路亞！救恩、榮耀、權能都屬乎我們的神！","notes":["就是要讚美耶和華的意思"]},{"n":2,"t":"他的判斷是真實公義的；因他判斷了那用淫行敗壞世界的大淫婦，並且向淫婦討流僕人血的罪，給他們伸冤。","notes":[]},{"n":3,"t":"又說：哈利路亞！燒淫婦的煙往上冒，直到永永遠遠。","notes":[]},{"n":4,"t":"那二十四位長老與四活物就俯伏敬拜坐寶座的神，說：阿們！哈利路亞！","notes":[]},{"n":5,"t":"有聲音從寶座出來說：神的眾僕人哪，凡敬畏他的，無論大小，都要讚美我們的神！","notes":[]},{"n":6,"t":"我聽見好像群眾的聲音，眾水的聲音，大雷的聲音，說：哈利路亞！因為主－我們的神、全能者作王了。","notes":[]},{"n":7,"t":"我們要歡喜快樂，將榮耀歸給他。因為，羔羊婚娶的時候到了；新婦也自己預備好了，","notes":[]},{"n":8,"t":"就蒙恩得穿光明潔白的細麻衣。（這細麻衣就是聖徒所行的義。）","notes":[]},{"n":9,"t":"天使吩咐我說：「你要寫上：凡被請赴羔羊之婚筵的有福了！」又對我說：「這是神真實的話。」","notes":[]},{"n":10,"t":"我就俯伏在他腳前要拜他。他說：「千萬不可！我和你，並你那些為耶穌作見證的弟兄同是作僕人的，你要敬拜神。」因為預言中的靈意乃是為耶穌作見證。","notes":[]},{"n":11,"t":"我觀看，見天開了。有一匹白馬，騎在馬上的稱為誠信真實，他審判，爭戰，都按著公義。","notes":[],"heads":["騎白馬者"]},{"n":12,"t":"他的眼睛如火焰，他頭上戴著許多冠冕；又有寫著的名字，除了他自己沒有人知道。","notes":[]},{"n":13,"t":"他穿著濺了血的衣服；他的名稱為神之道。","notes":[]},{"n":14,"t":"在天上的眾軍騎著白馬，穿著細麻衣，又白又潔，跟隨他。","notes":[]},{"n":15,"t":"有利劍從他口中出來，可以擊殺列國。他必用鐵杖轄管他們，並要踹全能神烈怒的酒醡。","notes":["轄管：原文是牧"]},{"n":16,"t":"在他衣服和大腿上有名寫著說：「萬王之王，萬主之主。」","notes":[]},{"n":17,"t":"我又看見一位天使站在日頭中，向天空所飛的鳥大聲喊著說：「你們聚集來赴神的大筵席，","notes":[]},{"n":18,"t":"可以吃君王與將軍的肉，壯士與馬和騎馬者的肉，並一切自主的為奴的，以及大小人民的肉。」","notes":[]},{"n":19,"t":"我看見那獸和地上的君王，並他們的眾軍都聚集，要與騎白馬的並他的軍兵爭戰。","notes":[]},{"n":20,"t":"那獸被擒拿；那在獸面前曾行奇事、迷惑受獸印記和拜獸像之人的假先知，也與獸同被擒拿。他們兩個就活活地被扔在燒著硫磺的火湖裏；","notes":[]},{"n":21,"t":"其餘的被騎白馬者口中出來的劍殺了；飛鳥都吃飽了他們的肉。","notes":[]}]},"20":{"heading":"一千年","verses":[{"n":1,"t":"我又看見一位天使從天降下，手裏拿著無底坑的鑰匙和一條大鍊子。","notes":[]},{"n":2,"t":"他捉住那龍，就是古蛇，又叫魔鬼，也叫撒但，把牠捆綁一千年，","notes":[]},{"n":3,"t":"扔在無底坑裏，將無底坑關閉，用印封上，使牠不得再迷惑列國。等到那一千年完了，以後必須暫時釋放牠。","notes":[]},{"n":4,"t":"我又看見幾個寶座，也有坐在上面的，並有審判的權柄賜給他們。我又看見那些因為給耶穌作見證，並為神之道被斬者的靈魂，和那沒有拜過獸與獸像，也沒有在額上和手上受過他印記之人的靈魂，他們都復活了，與基督一同作王一千年。","notes":[]},{"n":5,"t":"這是頭一次的復活。（其餘的死人還沒有復活，直等那一千年完了。）","notes":[]},{"n":6,"t":"在頭一次復活有分的有福了，聖潔了！第二次的死在他們身上沒有權柄。他們必作神和基督的祭司，並要與基督一同作王一千年。","notes":[]},{"n":7,"t":"那一千年完了，撒但必從監牢裏被釋放，","notes":[],"heads":["擊敗撒但"]},{"n":8,"t":"出來要迷惑地上四方的列國，就是歌革和瑪各，叫他們聚集爭戰。他們的人數多如海沙。","notes":["原文是角"]},{"n":9,"t":"他們上來遍滿了全地，圍住聖徒的營與蒙愛的城，就有火從天降下，燒滅了他們。","notes":[]},{"n":10,"t":"那迷惑他們的魔鬼被扔在硫磺的火湖裏，就是獸和假先知所在的地方。他們必晝夜受痛苦，直到永永遠遠。","notes":[]},{"n":11,"t":"我又看見一個白色的大寶座與坐在上面的；從他面前天地都逃避，再無可見之處了。","notes":[],"heads":["末日的審判"]},{"n":12,"t":"我又看見死了的人，無論大小，都站在寶座前。案卷展開了，並且另有一卷展開，就是生命冊。死了的人都憑著這些案卷所記載的，照他們所行的受審判。","notes":[]},{"n":13,"t":"於是海交出其中的死人；死亡和陰間也交出其中的死人；他們都照各人所行的受審判。","notes":[]},{"n":14,"t":"死亡和陰間也被扔在火湖裏；這火湖就是第二次的死。","notes":[]},{"n":15,"t":"若有人名字沒記在生命冊上，他就被扔在火湖裏。","notes":[]}]},"21":{"heading":"新天新地","verses":[{"n":1,"t":"我又看見一個新天新地；因為先前的天地已經過去了，海也不再有了。","notes":[]},{"n":2,"t":"我又看見聖城新耶路撒冷由神那裏從天而降，預備好了，就如新婦妝飾整齊，等候丈夫。","notes":[]},{"n":3,"t":"我聽見有大聲音從寶座出來說：「看哪，神的帳幕在人間。他要與人同住，他們要作他的子民。神要親自與他們同在，作他們的神。","notes":[]},{"n":4,"t":"神要擦去他們一切的眼淚；不再有死亡，也不再有悲哀、哭號、疼痛，因為以前的事都過去了。」","notes":[]},{"n":5,"t":"坐寶座的說：「看哪，我將一切都更新了！」又說：「你要寫上；因這些話是可信的，是真實的。」","notes":[]},{"n":6,"t":"他又對我說：「都成了！我是阿拉法，我是俄梅戛；我是初，我是終。我要將生命泉的水白白賜給那口渴的人喝。","notes":[]},{"n":7,"t":"得勝的，必承受這些為業：我要作他的神，他要作我的兒子。","notes":[]},{"n":8,"t":"惟有膽怯的、不信的、可憎的、殺人的、淫亂的、行邪術的、拜偶像的，和一切說謊話的，他們的分就在燒著硫磺的火湖裏；這是第二次的死。」","notes":[]},{"n":9,"t":"拿著七個金碗、盛滿末後七災的七位天使中，有一位來對我說：「你到這裏來，我要將新婦，就是羔羊的妻，指給你看。」","notes":[],"heads":["新耶路撒冷"]},{"n":10,"t":"我被聖靈感動，天使就帶我到一座高大的山，將那由神那裏、從天而降的聖城耶路撒冷指示我。","notes":[]},{"n":11,"t":"城中有神的榮耀；城的光輝如同極貴的寶石，好像碧玉，明如水晶。","notes":[]},{"n":12,"t":"有高大的牆，有十二個門，門上有十二位天使，門上又寫著以色列十二個支派的名字。","notes":[]},{"n":13,"t":"東邊有三門，北邊有三門，南邊有三門，西邊有三門。","notes":[]},{"n":14,"t":"城牆有十二根基，根基上有羔羊十二使徒的名字。","notes":[]},{"n":15,"t":"對我說話的，拿著金葦子當尺，要量那城和城門城牆。","notes":[]},{"n":16,"t":"城是四方的，長寬一樣。天使用葦子量那城，共有四千里，長、寬、高都是一樣；","notes":[]},{"n":17,"t":"又量了城牆，按著人的尺寸，就是天使的尺寸，共有一百四十四肘。","notes":[]},{"n":18,"t":"牆是碧玉造的；城是精金的，如同明淨的玻璃。","notes":[]},{"n":19,"t":"城牆的根基是用各樣寶石修飾的：第一根基是碧玉；第二是藍寶石；第三是綠瑪瑙；第四是綠寶石；","notes":[]},{"n":20,"t":"第五是紅瑪瑙；第六是紅寶石；第七是黃璧璽；第八是水蒼玉；第九是紅璧璽；第十是翡翠；第十一是紫瑪瑙；第十二是紫晶。","notes":[]},{"n":21,"t":"十二個門是十二顆珍珠，每門是一顆珍珠。城內的街道是精金，好像明透的玻璃。","notes":[]},{"n":22,"t":"我未見城內有殿，因主神－全能者和羔羊為城的殿。","notes":[]},{"n":23,"t":"那城內又不用日月光照；因有神的榮耀光照，又有羔羊為城的燈。","notes":[]},{"n":24,"t":"列國要在城的光裏行走；地上的君王必將自己的榮耀歸與那城。","notes":[]},{"n":25,"t":"城門白晝總不關閉，在那裏原沒有黑夜。","notes":[]},{"n":26,"t":"人必將列國的榮耀、尊貴歸與那城。","notes":[]},{"n":27,"t":"凡不潔淨的，並那行可憎與虛謊之事的，總不得進那城；只有名字寫在羔羊生命冊上的才得進去。","notes":[]}]},"22":{"heading":"基督再臨","verses":[{"n":1,"t":"天使又指示我在城內街道當中一道生命水的河，明亮如水晶，從神和羔羊的寶座流出來。","notes":[]},{"n":2,"t":"在河這邊與那邊有生命樹，結十二樣果子，每月都結果子；樹上的葉子乃為醫治萬民。","notes":["或譯：回"]},{"n":3,"t":"以後再沒有咒詛；在城裏有神和羔羊的寶座；他的僕人都要事奉他，","notes":[]},{"n":4,"t":"也要見他的面。他的名字必寫在他們的額上。","notes":[]},{"n":5,"t":"不再有黑夜；他們也不用燈光、日光，因為主神要光照他們。他們要作王，直到永永遠遠。","notes":[]},{"n":6,"t":"天使又對我說：「這些話是真實可信的。主就是眾先知被感之靈的神，差遣他的使者，將那必要快成的事指示他僕人。」","notes":[]},{"n":7,"t":"「看哪，我必快來！凡遵守這書上預言的有福了！」","notes":[]},{"n":8,"t":"這些事是我－約翰所聽見、所看見的；我既聽見、看見了，就在指示我的天使腳前俯伏要拜他。","notes":[]},{"n":9,"t":"他對我說：「千萬不可！我與你和你的弟兄眾先知，並那些守這書上言語的人，同是作僕人的。你要敬拜神。」","notes":[]},{"n":10,"t":"他又對我說：「不可封了這書上的預言，因為日期近了。","notes":[]},{"n":11,"t":"不義的，叫他仍舊不義；污穢的，叫他仍舊污穢；為義的，叫他仍舊為義；聖潔的，叫他仍舊聖潔。」","notes":[]},{"n":12,"t":"「看哪，我必快來！賞罰在我，要照各人所行的報應他。","notes":[]},{"n":13,"t":"我是阿拉法，我是俄梅戛；我是首先的，我是末後的；我是初，我是終。」","notes":[]},{"n":14,"t":"那些洗淨自己衣服的有福了！可得權柄能到生命樹那裏，也能從門進城。","notes":[]},{"n":15,"t":"城外有那些犬類、行邪術的、淫亂的、殺人的、拜偶像的，並一切喜好說謊言、編造虛謊的。","notes":[]},{"n":16,"t":"「我－耶穌差遣我的使者為眾教會將這些事向你們證明。我是大衛的根，又是他的後裔。我是明亮的晨星。」","notes":[]},{"n":17,"t":"聖靈和新婦都說：「來！」聽見的人也該說：「來！」口渴的人也當來；願意的，都可以白白取生命的水喝。","notes":[]},{"n":18,"t":"我向一切聽見這書上預言的作見證，若有人在這預言上加添甚麼，神必將寫在這書上的災禍加在他身上；","notes":[],"heads":["警戒增減這書上的預言"]},{"n":19,"t":"這書上的預言，若有人刪去甚麼，神必從這書上所寫的生命樹和聖城刪去他的分。","notes":[]},{"n":20,"t":"證明這事的說：「是了，我必快來！」阿們！主耶穌啊，我願你來！","notes":[]},{"n":21,"t":"願主耶穌的恩惠常與眾聖徒同在。阿們！","notes":[]}]}}}},"rcuv-shen":{"simplified":{"GEN":{"1":{"heading":"神的创造","verses":[{"n":1,"t":"起初，神创造天地。","notes":["本节或译“起初，神创造天地的时候，”"]},{"n":2,"t":"地是空虚混沌，深渊上面一片黑暗；神的灵 运行在水面上。","notes":["“神的灵”或译“神的风”。","“起初，神创造...水面上”或译“起初，当神创造天地，地是空虚混沌，深渊的表面黑暗，神的灵运行在水面上的时候，”"]},{"n":3,"t":"神说：“要有光”，就有了光。","notes":[]},{"n":4,"t":"神看光是好的，于是神就把光和暗分开。","notes":[]},{"n":5,"t":"神称光为“昼”，称暗为“夜”。有晚上，有早晨，这是第一日。","notes":[]},{"n":6,"t":"神说：“众水之间要有穹苍，把水和水分开。”","notes":[]},{"n":7,"t":"神就造了穹苍，把穹苍以下的水和穹苍以上的水分开。事就这样成了。","notes":[]},{"n":8,"t":"神称穹苍为“天”。有晚上，有早晨，这是第二日。","notes":[]},{"n":9,"t":"神说：“天下面的水要聚集在一处，使干地露出来。”事就这样成了。","notes":[]},{"n":10,"t":"神称干地为“地”，称聚集在一起的水为“海”。神看为好的。","notes":[]},{"n":11,"t":"神说：“地要长出植物，就是含种子的五谷菜蔬，和会结果子、果子里有种子的树，在地上各从其类。”事就这样成了。","notes":[]},{"n":12,"t":"于是地长出了植物：含种子的五谷菜蔬，各从其类；会结果子、果子里有种子的树，各从其类。神看为好的。","notes":[]},{"n":13,"t":"有晚上，有早晨，这是第三日。","notes":[]},{"n":14,"t":"神说：“天上要有光体来分昼夜，让它们作记号，定季节、日子、年份，","notes":[]},{"n":15,"t":"它们要在天空发光，照在地上。”事就这样成了。","notes":[]},{"n":16,"t":"于是神造了两个大光体，大的管昼，小的管夜，又造了星辰。","notes":[]},{"n":17,"t":"神把这些光体摆列在天空，照在地上，","notes":[]},{"n":18,"t":"管理昼夜，分别光暗。神看为好的。","notes":[]},{"n":19,"t":"有晚上，有早晨，这是第四日。","notes":[]},{"n":20,"t":"神说：“水要滋生众多有生命之物；要有鸟飞在地面以上，天空之中。”","notes":[]},{"n":21,"t":"神就创造了大鱼和在水里滋生的各样活动的生物，各从其类，以及各样有翅膀的鸟，各从其类。神看为好的。","notes":[]},{"n":22,"t":"神就赐福给这一切，说：“要繁殖增多，充满在海的水里；飞鸟也要在地上增多。”","notes":[]},{"n":23,"t":"有晚上，有早晨，这是第五日。","notes":[]},{"n":24,"t":"神说：“地要生出有生命之物，各从其类，就是牲畜、爬行动物、地上的走兽，各从其类。”事就这样成了。","notes":[]},{"n":25,"t":"于是神造了地上的走兽，各从其类；牲畜，各从其类；和地上一切的爬行动物，各从其类。神看为好的。","notes":[]},{"n":26,"t":"神说：“我们要照着我们的形像，按着我们的样式造人，使他们管理海里的鱼、天空的鸟、地上的牲畜和全地，以及地上爬的一切爬行动物。”","notes":[]},{"n":27,"t":"神就照着他的形像创造人，照着神的形像创造他们；他创造了他们，有男有女。","notes":["“他们”：原文是“他”。"]},{"n":28,"t":"神赐福给他们，神对他们说：“要生养众多，遍满这地，治理它；要管理海里的鱼、天空的鸟和地上各样活动的生物。”","notes":[]},{"n":29,"t":"神说：“看哪，我把全地一切含种子的五谷菜蔬和一切会结果子、果子里有种子的树，都赐给你们；这些都可作食物。","notes":[]},{"n":30,"t":"至于地上一切的走兽、天空一切的飞鸟，并一切在地上爬行的，有生命的动物，我把绿色植物赐给它们作食物。”事就这样成了。","notes":[]},{"n":31,"t":"神看一切所造的，看哪，都非常好。有晚上，有早晨，这是第六日。","notes":[]}]},"2":{"heading":"创造的另一记载","verses":[{"n":1,"t":"天和地，以及万象都完成了。","notes":[]},{"n":2,"t":"到第七日，神已经完成了造物之工，就在第七日安息了，歇了他所做一切的工。","notes":[]},{"n":3,"t":"神赐福给第七日，将它分别为圣，因为在这日，神安息了，歇了他所做一切创造的工。","notes":[]},{"n":4,"t":"这就是天地创造的来历。在耶和华神造地和天的时候，","notes":[]},{"n":5,"t":"地上还没有田野的草木，田间的菜蔬还没有长出来，因为耶和华神还没有降雨在地上，也没有人耕种土地。","notes":[]},{"n":6,"t":"但是，有雾气从地上腾，滋润整个土地的表面。","notes":[]},{"n":7,"t":"耶和华神用地上的尘土造人，将生命之气吹进他的鼻孔，这人就成了有灵的活人。","notes":["“有灵的活人”或译“有生命的人”；参林前15．45。"]},{"n":8,"t":"耶和华神在东方的伊甸栽了一个园子，把所造的人安置在那里。","notes":[]},{"n":9,"t":"耶和华神使各样的树从土地里长出来，可以悦人的眼目，好作食物。园子当中有生命树和知善恶的树 。","notes":["“知善恶的树”或译“赐一切知识的树”；下同。"]},{"n":10,"t":"有一条河从伊甸流出来，滋润那园子，从那里分成四个源头：","notes":[]},{"n":11,"t":"第一条名叫比逊，它环绕哈腓拉全地，在那里有金子。","notes":[]},{"n":12,"t":"那地的金子很好，在那里也有珍珠和红玛瑙。","notes":["“珍珠”也可能指一种可作香料的珍贵树脂；参民11．7。"]},{"n":13,"t":"第二条河名叫基训，它环绕古实全地。","notes":[]},{"n":14,"t":"第三条河名叫底格里斯，它流到亚述的东边。第四条河就是幼发拉底。","notes":[]},{"n":15,"t":"耶和华神把那人安置在伊甸园，让他耕耘看管。","notes":[]},{"n":16,"t":"耶和华神吩咐那人说：“园中各样树上所出的，你可以随意吃，","notes":[]},{"n":17,"t":"只是知善恶的树所出的，你不可吃，因为你吃它的日子必定死！”","notes":[]},{"n":18,"t":"耶和华神说：“那人单独一个不好，我要为他造一个配偶帮助他。”","notes":[]},{"n":19,"t":"耶和华神用泥土造了野地各样的走兽和天空各样的飞鸟，都带到那人面前，看他叫什么。那人怎样叫各样的动物，那就是它的名字。","notes":[]},{"n":20,"t":"那人就给一切牲畜、天空的飞鸟和野地各样的走兽都起了名。只是亚当没有找到配偶帮助他。","notes":["“亚当”或译“那人”。"]},{"n":21,"t":"耶和华神使他沉睡，他就睡了；于是取下他的一根肋骨，又在原处把肉合起来。","notes":[]},{"n":22,"t":"耶和华神就用那人身上所取的肋骨造了一个女人，带她到那人面前。","notes":[]},{"n":23,"t":"那人说：“这是我骨中的骨，肉中的肉，可以称她为女人，因为她是从男人身上取出来的。”","notes":[]},{"n":24,"t":"因此，人要离开父母，与妻子结合，二人成为一体。","notes":[]},{"n":25,"t":"当时夫妻二人赤身露体，并不觉得羞耻。","notes":[]}]},"3":{"heading":"人违背命令","verses":[{"n":1,"t":"耶和华神所造的，惟有蛇比田野一切的走兽更狡猾。蛇对女人说：“神岂是真说，你们不可吃园中任何树上所出的吗？”","notes":[]},{"n":2,"t":"女人对蛇说：“园中树上的果子，我们都可以吃；","notes":[]},{"n":3,"t":"只是园子中间那棵树的果子，神曾说：‘你们不可吃，也不可摸，免得你们死。’”","notes":[]},{"n":4,"t":"蛇对女人说：“你们不一定死；","notes":[]},{"n":5,"t":"因为神知道，你们吃的日子眼睛就开了，你们就像神一样知道善恶。”","notes":[]},{"n":6,"t":"于是女人见那棵树好作食物，又悦人的眼目，那树令人喜爱，能使人有智慧，她就摘下果子吃了，又给了与她一起的丈夫，他也吃了。","notes":[]},{"n":7,"t":"他们二人的眼睛就开了，知道自己赤身露体，就编织无花果树的叶子，为自己做成裙子。","notes":[]},{"n":8,"t":"天起了凉风，那人和他妻子听见耶和华神在园中来回行走的声音，就藏在园里的树木中，躲避耶和华神的面。","notes":[]},{"n":9,"t":"耶和华神呼唤那人，对他说：“你在哪里？”","notes":[]},{"n":10,"t":"他说：“我在园中听见你的声音，我就害怕；因为我赤身露体，我就藏了起来。”","notes":[]},{"n":11,"t":"耶和华神说：“谁告诉你，你是赤身露体呢？莫非你吃了那树上所出的，就是我吩咐你不可吃的吗？”","notes":[]},{"n":12,"t":"那人说：“你赐给我、与我一起的女人，是她把那树上所出的给我，我就吃了。”","notes":[]},{"n":13,"t":"耶和华神对女人说：“你怎么会做这种事呢？”女人说：“那蛇引诱我，我就吃了。”","notes":[]},{"n":14,"t":"耶和华神对蛇说：“你既做了这事，就必受诅咒，比一切的牲畜和野兽更重。你必用肚子行走，终生吃土。","notes":[],"heads":["神的宣判"]},{"n":15,"t":"我要使你和女人彼此为仇，你的后裔和女人的后裔也彼此为仇。他要伤你的头，你要伤他的脚跟。 ”","notes":[]},{"n":16,"t":"又对女人说：“我必多多加增你怀胎的痛苦，你生儿女时必多受痛苦。你必恋慕你丈夫，他必管辖你。”","notes":[]},{"n":17,"t":"又对亚当说：“你既听从你妻子的话，吃了那树上所出的，就是我吩咐你不可吃的，土地必因你的缘故受诅咒；你必终生劳苦才能从土地得吃的。","notes":[]},{"n":18,"t":"土地必给你长出荆棘和蒺藜来；你也要吃田间的五谷菜蔬。","notes":[]},{"n":19,"t":"你必汗流满面才有食物可吃，直到你归了土地，因为你是从土地而出的。你本是尘土，仍要归回尘土。”","notes":[]},{"n":20,"t":"那人给他妻子起名叫夏娃，因为她是众生之母 。","notes":["“众生之母”或译“人类的母亲”。"]},{"n":21,"t":"耶和华神用兽皮做衣服给亚当和他的妻子穿。","notes":[]},{"n":22,"t":"耶和华神说：“看哪，那人已经像我们中间的一个，知道善恶，现在恐怕他又伸手摘生命树所出的来吃，就永远活着。”","notes":[],"heads":["亚当和夏娃被赶出伊甸园"]},{"n":23,"t":"耶和华神就驱逐他出伊甸园，使他耕种土地，他原是从土地里被取出来的。","notes":[]},{"n":24,"t":"耶和华神把那人赶出去，就在伊甸园东边安设基路伯和发出火焰转动的剑，把守生命树的道路。","notes":[]}]},"4":{"heading":"该隐和亚伯","verses":[{"n":1,"t":"那人和他妻子夏娃同房，夏娃就怀孕，生了该隐 ，她说：“我靠耶和华得了一个男的。”","notes":["“该隐”意思是“得”。"]},{"n":2,"t":"她又生了该隐的弟弟亚伯。亚伯是牧羊的；该隐是耕地的。","notes":[]},{"n":3,"t":"过了一些日子，该隐拿地里的出产为供物献给耶和华；","notes":[]},{"n":4,"t":"亚伯也把他羊群中头生的和羊的脂肪献上。耶和华看中了亚伯和他的供物，","notes":[]},{"n":5,"t":"却看不中该隐和他的供物。该隐就非常生气，沉下脸来。","notes":[]},{"n":6,"t":"耶和华对该隐说：“你为什么生气呢？你为什么沉下脸来呢？","notes":[]},{"n":7,"t":"你若做得对，岂不仰起头来吗？你若做得不对，罪就伏在门前。它想要控制你，你却要制伏它。”","notes":[]},{"n":8,"t":"该隐与他弟弟亚伯说话 。 二人正在田间时，该隐起来攻击他弟弟亚伯，把他杀了。","notes":["“该隐...说话。”撒玛利亚五经、七十士译本和其他古译本是“该隐对他弟弟亚伯说：‘让我们到田间去吧！’”"]},{"n":9,"t":"耶和华对该隐说：“你弟弟亚伯在哪里？”他说：“我不知道！我岂是看守我弟弟的吗？”","notes":[]},{"n":10,"t":"耶和华说：“你做了什么事呢？你弟弟血的声音从地里向我哀号。","notes":[]},{"n":11,"t":"现在你必从这地受诅咒，这地开了口，从你手里接受你弟弟的血。","notes":[]},{"n":12,"t":"你耕种土地，它不再给你效力；你必流离飘荡在地上。”","notes":[]},{"n":13,"t":"该隐对耶和华说：“我的惩罚太重，过于我所能承当的。","notes":[]},{"n":14,"t":"看哪，今日你赶我离开这块土地，不能见你的面；我必流离飘荡在地上，凡遇见我的必杀我。”","notes":[]},{"n":15,"t":"耶和华对他说：“既然如此 ，凡杀该隐的，必遭报七倍。”耶和华就给该隐立一个记号，免得人遇见他就杀他。","notes":[]},{"n":16,"t":"于是该隐离开了耶和华的面，去住在伊甸东边挪得之地。","notes":["“挪得” 意思是“流荡”。"]},{"n":17,"t":"该隐与妻子同房，她就怀孕，生了以诺。该隐建造一座城，就照他儿子的名字称那城为以诺。","notes":[],"heads":["该隐的后代"]},{"n":18,"t":"以诺生以拿，以拿生米户雅利，米户雅利生玛土撒利，玛土撒利生拉麦。","notes":[]},{"n":19,"t":"拉麦娶了两个妻子：一个名叫亚大，一个名叫洗拉。","notes":[]},{"n":20,"t":"亚大生雅八；雅八是住帐棚、牧养牲畜之人的祖师。","notes":[]},{"n":21,"t":"雅八的兄弟名叫犹八；他是所有弹琴吹箫之人的祖师。","notes":[]},{"n":22,"t":"洗拉又生了土八．该隐；他是打造各样铜器铁器的工匠。土八．该隐的妹妹是拿玛。","notes":[]},{"n":23,"t":"拉麦对他两个妻子说：亚大、洗拉啊，听我的声音；拉麦的妻子啊，侧耳听我的言语：大人伤我，我把他杀了；小孩损我，我把他害了。","notes":["“大人...害了”或译“我杀大人却伤自己，我害小孩却损本身”。"]},{"n":24,"t":"若杀该隐，遭报七倍，杀拉麦的，必遭报七十七倍。","notes":[]},{"n":25,"t":"亚当又与妻子同房，她就生了一个儿子，给他起名叫塞特，说：“神给我立了另一个子嗣代替亚伯，因为该隐杀了他。”","notes":[],"heads":["塞特和以挪士"]},{"n":26,"t":"塞特也生了一个儿子，起名叫以挪士。那时候，人开始求告耶和华的名。","notes":[]}]},"5":{"heading":"亚当的后代","verses":[{"n":1,"t":"这是亚当后代的家谱。当神造人的日子，他照着自己的样式造人。","notes":[]},{"n":2,"t":"他造男造女。在他们被造的日子，神赐福给他们，称他们为人。","notes":[]},{"n":3,"t":"亚当活到一百三十岁，生了一个儿子，形像样式和自己相似，就给他起名叫塞特。","notes":[]},{"n":4,"t":"亚当生塞特之后，又活了八百年，并且生儿育女。","notes":[]},{"n":5,"t":"亚当共活了九百三十年，就死了。","notes":[]},{"n":6,"t":"塞特活到一百零五岁，生了以挪士。","notes":[]},{"n":7,"t":"塞特生以挪士之后，又活了八百零七年，并且生儿育女。","notes":[]},{"n":8,"t":"塞特共活了九百一十二年，就死了。","notes":[]},{"n":9,"t":"以挪士活到九十岁，生了该南。","notes":[]},{"n":10,"t":"以挪士生该南之后，又活了八百一十五年，并且生儿育女。","notes":[]},{"n":11,"t":"以挪士共活了九百零五年，就死了。","notes":[]},{"n":12,"t":"该南活到七十岁，生了玛勒列。","notes":[]},{"n":13,"t":"该南生玛勒列之后，又活了八百四十年，并且生儿育女。","notes":[]},{"n":14,"t":"该南共活了九百一十年，就死了。","notes":[]},{"n":15,"t":"玛勒列活到六十五岁，生了雅列。","notes":[]},{"n":16,"t":"玛勒列生雅列之后，又活了八百三十年，并且生儿育女。","notes":[]},{"n":17,"t":"玛勒列共活了八百九十五年，就死了。","notes":[]},{"n":18,"t":"雅列活到一百六十二岁，生了以诺。","notes":[]},{"n":19,"t":"雅列生以诺之后，又活了八百年，并且生儿育女。","notes":[]},{"n":20,"t":"雅列共活了九百六十二年，就死了。","notes":[]},{"n":21,"t":"以诺活到六十五岁，生了玛土撒拉。","notes":[]},{"n":22,"t":"以诺生玛土撒拉之后，与神同行三百年，并且生儿育女。","notes":[]},{"n":23,"t":"以诺共活了三百六十五年。","notes":[]},{"n":24,"t":"以诺与神同行，神把他接去，他就不在了。","notes":[]},{"n":25,"t":"玛土撒拉活到一百八十七岁，生了拉麦。","notes":[]},{"n":26,"t":"玛土撒拉生拉麦之后，又活了七百八十二年，并且生儿育女。","notes":[]},{"n":27,"t":"玛土撒拉共活了九百六十九年，就死了。","notes":[]},{"n":28,"t":"拉麦活到一百八十二岁，生了一个儿子，","notes":[]},{"n":29,"t":"给他起名叫挪亚，说：“在耶和华所诅咒的地上，这个儿子必使我们从工作和手中的劳苦得到安慰。”","notes":[]},{"n":30,"t":"拉麦生挪亚之后，又活了五百九十五年，并且生儿育女。","notes":[]},{"n":31,"t":"拉麦共活了七百七十七年，就死了。","notes":[]},{"n":32,"t":"挪亚活到五百岁，生了闪、含和雅弗。","notes":[]}]},"6":{"heading":"人类的邪恶","verses":[{"n":1,"t":"当人开始在地面上增多、又生女儿的时候，","notes":[]},{"n":2,"t":"神的儿子们看见人的女子美貌，就随意挑选，娶来为妻。","notes":[]},{"n":3,"t":"耶和华说：“人既属乎血气，我的灵就不永远住在他里面；然而他的年岁还可到一百二十年。”","notes":[]},{"n":4,"t":"那时候有巨人在地上，后来也有；神的儿子们和人的女子们交合，生了孩子。那些人就是古代的勇士，有名的人物。","notes":[]},{"n":5,"t":"耶和华见人在地上罪大恶极，终日心里所想的尽都是恶事，","notes":[]},{"n":6,"t":"耶和华就因造人在地上感到遗憾，心中忧伤。","notes":[]},{"n":7,"t":"耶和华说：“我要把所造的人和走兽，爬行动物，以及天空的飞鸟，都从地面上除灭，因为我造了他们感到遗憾。”","notes":[]},{"n":8,"t":"只有挪亚在耶和华眼前蒙恩。","notes":[]},{"n":9,"t":"这是挪亚的后代。挪亚是个义人，在他的世代中是个完全人。挪亚与神同行。","notes":[],"heads":["挪亚造方舟"]},{"n":10,"t":"挪亚生了三个儿子，就是闪、含和雅弗。","notes":[]},{"n":11,"t":"这地在神面前败坏了，地上充满了暴力。","notes":[]},{"n":12,"t":"神观看这地，看哪，它败坏了，因为凡血肉之躯在地上的行为都败坏了。","notes":[]},{"n":13,"t":"神对挪亚说：“在我面前，凡血肉之躯的结局已经临到，因着他们，地上充满了暴力。看哪，我要把他们和这地一起毁灭。","notes":[]},{"n":14,"t":"你要为自己用歌斐木造一艘方舟，并在方舟内造房间，内外都要抹上沥青。","notes":[]},{"n":15,"t":"方舟的造法是这样：要长三百肘，宽五十肘，高三十肘。","notes":[]},{"n":16,"t":"方舟上面要造天窗，向上一肘。方舟的门要开在旁边。方舟要分上、中、下三层。","notes":[]},{"n":17,"t":"看哪，我要使洪水泛滥在地上，毁灭天下凡有生命气息的血肉之躯，地上的一切都要灭亡。","notes":[]},{"n":18,"t":"但我要与你立约；你同你的儿子、妻子和媳妇都要进入方舟。","notes":[]},{"n":19,"t":"凡有血肉的动物，每样一对，一公一母，你要带进方舟，好跟你一起保全生命。","notes":[]},{"n":20,"t":"飞鸟各从其类，牲畜各从其类，地上的爬行动物各从其类，每样一对，都要到你那里，好保全生命。","notes":[]},{"n":21,"t":"你要拿各样可吃的食物，储存在你那里，作你和它们的粮食。”","notes":[]},{"n":22,"t":"挪亚就去做了；凡神吩咐他的，他都照样去做。","notes":[]}]},"7":{"heading":"洪水","verses":[{"n":1,"t":"耶和华对挪亚说：“你和你的全家都要进入方舟，因为在这世代中，我看你在我面前是个义人。","notes":[]},{"n":2,"t":"凡洁净的牲畜，你要各取七公七母；不洁净的牲畜，你要各取一公一母；","notes":[]},{"n":3,"t":"天空的飞鸟也要各取七公七母，为了要留种，活在全地面上。","notes":[]},{"n":4,"t":"因为再过七天，我要降雨在地上四十昼夜，把我所造的一切生物从地面上除灭。”","notes":[]},{"n":5,"t":"挪亚就遵照耶和华吩咐他的去做。","notes":[]},{"n":6,"t":"当洪水在地上泛滥的时候，挪亚已六百岁。","notes":["“洪水”：原文是“洪水的水”。"]},{"n":7,"t":"挪亚同他的儿子、妻子和媳妇都进入方舟，躲避洪水。","notes":[]},{"n":8,"t":"洁净的牲畜和不洁净的牲畜，飞鸟及所有爬行在土地上的，","notes":[]},{"n":9,"t":"都一对一对，有公有母，到挪亚那里，进入方舟，正如神所吩咐挪亚的。","notes":[]},{"n":10,"t":"过了七天，洪水泛滥在地上。","notes":[]},{"n":11,"t":"挪亚六百岁那一年的二月十七日，就在那一天，大深渊的泉源都裂开，天上的窗户也敞开了，","notes":[]},{"n":12,"t":"四十昼夜有大雨降在地上。","notes":[]},{"n":13,"t":"正在那日，挪亚和他的儿子闪、含、雅弗，以及挪亚的妻子和三个媳妇，都一同进入方舟。","notes":[]},{"n":14,"t":"他们和一切走兽，各从其类；一切牲畜，各从其类；地上爬的一切爬行动物，各从其类；一切的鸟，就是一切有翅膀的飞禽，各从其类；","notes":[]},{"n":15,"t":"凡有生命气息的血肉之躯，都一对一对到挪亚那里，进入方舟。","notes":[]},{"n":16,"t":"凡有血肉的，都一公一母进入方舟，正如神所吩咐挪亚的。耶和华就把他关在方舟里。","notes":[]},{"n":17,"t":"洪水在地上泛滥四十天，水往上涨，使方舟浮起，方舟就从地上漂起来。","notes":[]},{"n":18,"t":"水势汹涌，在地上大大上涨，方舟在水面上漂荡。","notes":[]},{"n":19,"t":"水势在地上极其浩大，普天下所有的高山都淹没了。","notes":[]},{"n":20,"t":"水势汹涌，比山高出十五肘 ，山岭都淹没了。","notes":[]},{"n":21,"t":"凡有血肉在地上行动的，就是飞鸟、牲畜、走兽和地上成群的群聚动物，以及所有的人，都死了。","notes":[]},{"n":22,"t":"在干地上凡鼻孔里有生命气息的都死了。","notes":[]},{"n":23,"t":"耶和华除灭了地面上各类的生物，包括人和牲畜、爬行动物，以及天空的飞鸟；他们就都从地上除灭了，只剩下挪亚和那些与他同在方舟里的。","notes":[]},{"n":24,"t":"水势汹涌，在地上共一百五十天。","notes":[]}]},"8":{"heading":"洪水消退","verses":[{"n":1,"t":"神记念挪亚和挪亚方舟里的一切走兽牲畜。神使风吹地，水势渐落。","notes":[]},{"n":2,"t":"深渊的泉源和天上的窗户都关闭了，雨不再从天降下。","notes":[]},{"n":3,"t":"水从地上逐渐消退。过了一百五十天，水就退了。","notes":[]},{"n":4,"t":"七月十七日，方舟停在亚拉腊山上。","notes":[]},{"n":5,"t":"水继续退去，直到十月；十月初一，山顶都露出来了。","notes":[]},{"n":6,"t":"过了四十天，挪亚打开他所造的方舟的窗户，","notes":[]},{"n":7,"t":"放出一只乌鸦。那乌鸦飞来飞去，直到地上的水都干了。","notes":[]},{"n":8,"t":"他又从他那里放出一只鸽子，要看水从地面上退了没有。","notes":[]},{"n":9,"t":"但全地面都是水，鸽子找不到落脚之地，就回到方舟挪亚那里。挪亚伸手接了鸽子，把它带进方舟。","notes":[]},{"n":10,"t":"挪亚又另外等了七天，再把鸽子从方舟放出去。","notes":[]},{"n":11,"t":"到了晚上，鸽子回到他那里，看哪，嘴里有一片刚啄下来的橄榄叶，挪亚就知道水已经从地上退了。","notes":[]},{"n":12,"t":"他又另外等了七天，再放出鸽子，这次鸽子不再回到他那里了。","notes":[]},{"n":13,"t":"当挪亚六百零一岁，正月初一的时候，地上的水都干了。挪亚打开方舟的盖观看，看哪，地面干了。","notes":[]},{"n":14,"t":"到了二月二十七日，地就都干了。","notes":[]},{"n":15,"t":"神对挪亚说：","notes":[]},{"n":16,"t":"“你同你的妻子、儿子、媳妇都要出方舟。","notes":[]},{"n":17,"t":"凡与你一起有血肉的生物，就是飞鸟、牲畜和地上爬的一切爬行动物，都要带出来。 它们要在地上滋生，繁殖增多。”","notes":[]},{"n":18,"t":"于是挪亚同他的儿子、妻子、媳妇都出来了。","notes":[]},{"n":19,"t":"一切走兽、爬行动物和飞鸟，地上所有的动物，各从其类，也都出了方舟。","notes":[]},{"n":20,"t":"挪亚为耶和华筑了一座坛，拿各种洁净的牲畜和各种洁净的飞鸟，献在坛上为燔祭。","notes":[],"heads":["挪亚献祭"]},{"n":21,"t":"耶和华闻了那馨香之气，耶和华心里说：“我不再因人的缘故诅咒土地，因为人从幼年就心里怀着恶念；我也不再照我曾做的毁灭一切生物了。","notes":[]},{"n":22,"t":"地还存在的时候，撒种、收割、寒暑、冬夏、昼夜都永不止息。”","notes":[]}]},"9":{"heading":"神与挪亚立约","verses":[{"n":1,"t":"神赐福给挪亚和他的儿子，对他们说：“你们要生养众多，遍满这地。","notes":[]},{"n":2,"t":"地上一切的走兽、天空一切的飞鸟、所有爬行在土地上的和海里一切的鱼都必怕你们，畏惧你们，它们都要交在你们手里。","notes":[]},{"n":3,"t":"凡活的动物都可作你们的食物。这一切我都赐给你们，如同绿色的菜蔬一样。","notes":[]},{"n":4,"t":"只是带着生命的肉，就是带着血的，你们不可吃。","notes":[]},{"n":5,"t":"流你们血、害你们命的，我必向他追讨；我要向一切走兽追讨，向人和向人的弟兄追讨人命。","notes":[]},{"n":6,"t":"凡流人血的，他的血也必被人所流，因为神造人，是照自己的形像造的。","notes":[]},{"n":7,"t":"你们要生养众多，在地上繁衍昌盛。”","notes":[]},{"n":8,"t":"神对挪亚和同他一起的儿子说：","notes":[]},{"n":9,"t":"“看哪，我要与你们和你们后裔立我的约，","notes":[]},{"n":10,"t":"包括和你们一起所有的生物，就是飞鸟、牲畜、地上一切的走兽，凡从方舟里出来地上一切的生物。","notes":[]},{"n":11,"t":"我与你们立我的约：凡有血肉的，不再被洪水灭绝，也不再有洪水毁坏这地了。”","notes":[]},{"n":12,"t":"神说：“这是我与你们，以及和你们一起的一切生物所立之约的记号，直到万代：","notes":[]},{"n":13,"t":"我把彩虹放在云中，这就是我与地立约的记号了。","notes":[]},{"n":14,"t":"我使云遮地的时候，会有彩虹出现在云中，","notes":[]},{"n":15,"t":"我就记念我与你们，以及各样有血肉的生物所立的约：不再有洪水泛滥去毁灭一切有血肉的了。","notes":[]},{"n":16,"t":"彩虹出现在云中，我看见了，就要记念神与地上一切有血肉的生物所立的永约。”","notes":[]},{"n":17,"t":"神对挪亚说：“这就是我与地上一切有血肉的立约的记号。”","notes":[]},{"n":18,"t":"挪亚的儿子，从方舟出来的，有闪、含和雅弗。含是迦南的父亲。","notes":[],"heads":["挪亚和他的儿子们"]},{"n":19,"t":"这是挪亚的三个儿子，他们的后裔散布全地。","notes":[]},{"n":20,"t":"挪亚是农夫，是他开始栽葡萄园的。","notes":[]},{"n":21,"t":"他喝了一些酒就醉了，在他的帐棚里赤着身子。","notes":[]},{"n":22,"t":"迦南的父亲含看见他父亲赤身，就到外面告诉他的两个兄弟。","notes":[]},{"n":23,"t":"于是闪和雅弗拿了外衣搭在二人肩上，倒退着进去，遮盖父亲的赤身；他们背着脸，看不见父亲的赤身。","notes":[]},{"n":24,"t":"挪亚酒醒以后，知道小儿子向他所做的事，","notes":[]},{"n":25,"t":"就说：“迦南当受诅咒，必给他弟兄作奴仆的奴仆。”","notes":[]},{"n":26,"t":"又说：“耶和华—闪的神是应当称颂的！愿迦南作闪的奴仆。","notes":[]},{"n":27,"t":"愿神使雅弗扩张，愿他住在闪的帐棚里；愿迦南作他的奴仆。”","notes":[]},{"n":28,"t":"洪水以后，挪亚又活了三百五十年。","notes":[]},{"n":29,"t":"挪亚共活了九百五十年，就死了。","notes":[]}]},"10":{"heading":"闪、含、雅弗的后代","verses":[{"n":1,"t":"这是挪亚的儿子闪、含、雅弗的后代。洪水以后，他们都生了儿子。","notes":[]},{"n":2,"t":"雅弗的儿子是歌篾、玛各、玛代、雅完、土巴、米设、提拉。","notes":[]},{"n":3,"t":"歌篾的儿子是亚实基拿、利法、陀迦玛。","notes":[]},{"n":4,"t":"雅完的儿子是以利沙、他施、基提、罗单人。","notes":["“罗单人”是根据一些古卷、撒玛利亚五经和七十士译本，原文是“多单人”；参代上1．7。"]},{"n":5,"t":"从这些人中有沿海国家的人散居各处，有自己的土地，各有各的语言、宗族、国家。","notes":[]},{"n":6,"t":"含的儿子是古实、麦西、弗、迦南。","notes":[]},{"n":7,"t":"古实的儿子是西巴、哈腓拉、撒弗他、拉玛、撒弗提迦。拉玛的儿子是示巴、底但。","notes":[]},{"n":8,"t":"古实又生宁录，他是地上第一个勇士。","notes":[]},{"n":9,"t":"他在耶和华面前是个英勇的猎人，所以有话说：“像宁录在耶和华面前是个英勇的猎人。”","notes":[]},{"n":10,"t":"他王国的开始是在巴别、以力、亚甲、甲尼，都在示拿地。","notes":[]},{"n":11,"t":"他从那地出来往亚述去，建造了尼尼微、利河伯、迦拉，","notes":[]},{"n":12,"t":"以及尼尼微和迦拉之间的利鲜，那是座大城。","notes":[]},{"n":13,"t":"麦西生路低人、亚拿米人、利哈比人、拿弗土希人、","notes":[]},{"n":14,"t":"帕斯鲁细人、迦斯路希人、迦斐托人；非利士人是从迦斐托人出来的。","notes":["“迦斐托人”：原文是“迦斯路希人”。"]},{"n":15,"t":"迦南生了长子西顿，又生赫","notes":[]},{"n":16,"t":"和耶布斯人、亚摩利人、革迦撒人、","notes":[]},{"n":17,"t":"希未人、亚基人、西尼人、","notes":[]},{"n":18,"t":"亚瓦底人、洗玛利人、哈马人，后来迦南的家族散开了。","notes":[]},{"n":19,"t":"迦南的疆界是从西顿到基拉耳，直到迦萨，又到所多玛、蛾摩拉、押玛、洗扁，直到拉沙。","notes":[]},{"n":20,"t":"这就是含的后裔，各有自己的宗族、语言、土地和国家。","notes":[]},{"n":21,"t":"闪也生了儿子，他是雅弗的哥哥，是希伯人的祖先。","notes":["“雅弗的哥哥”：七十士译本是“雅弗的弟弟”。"]},{"n":22,"t":"闪的儿子是以拦、亚述、亚法撒、路德、亚兰。","notes":[]},{"n":23,"t":"亚兰的儿子是乌斯、户勒、基帖、玛施。","notes":[]},{"n":24,"t":"亚法撒生沙拉，沙拉生希伯。","notes":[]},{"n":25,"t":"希伯生了两个儿子，一个名叫法勒 ，因为那时人分地居住；法勒的兄弟名叫约坍。","notes":["“法勒”意思是“分”。"]},{"n":26,"t":"约坍生亚摩答、沙列、哈萨玛非、耶拉、","notes":[]},{"n":27,"t":"哈多兰、乌萨、德拉、","notes":[]},{"n":28,"t":"俄巴路、亚比玛利、示巴、","notes":[]},{"n":29,"t":"阿斐、哈腓拉、约巴，这些都是约坍的儿子。","notes":[]},{"n":30,"t":"他们所住的地方是从米沙直到西发，到东边的山。","notes":[]},{"n":31,"t":"这就是闪的后裔，各有自己的宗族、语言、土地和国家。","notes":[]},{"n":32,"t":"这些是挪亚儿子的宗族，按着他们的后代立国。洪水以后，邦国就从他们散布在地上。","notes":[]}]},"11":{"heading":"巴别塔","verses":[{"n":1,"t":"那时，全地只有一种语言，都说一样的话。","notes":[]},{"n":2,"t":"他们向东迁移的时候，在示拿地找到一片平原，就住在那里。","notes":[]},{"n":3,"t":"他们彼此商量说：“来，让我们来做砖，把砖烧透了。”他们就拿砖当石头，又拿柏油当泥浆。","notes":[]},{"n":4,"t":"他们说：“来，让我们建造一座城和一座塔，塔顶通天。我们要为自己立名，免得我们分散在全地面上。”","notes":[]},{"n":5,"t":"耶和华降临，要看世人所建造的城和塔。","notes":[]},{"n":6,"t":"耶和华说：“看哪，他们成了同一个民族，都有一样的语言。这只是他们开始做的事，现在他们想要做的任何事，就没有什么可拦阻他们了。","notes":[]},{"n":7,"t":"来，我们下去，在那里变乱他们的语言，使他们彼此语言不通。”","notes":[]},{"n":8,"t":"于是耶和华使他们从那里分散在全地面上；他们就停止建造那城了。","notes":[]},{"n":9,"t":"因为耶和华在那里变乱了全地的语言，把人从那里分散在全地面上，所以那城名叫巴别 。","notes":["“巴别”意思是“变乱”。"]},{"n":10,"t":"这是闪的后代。洪水以后二年，闪一百岁生了亚法撒。","notes":[],"heads":["闪的后代"]},{"n":11,"t":"闪生亚法撒之后又活了五百年，并且生儿育女。","notes":[]},{"n":12,"t":"亚法撒活到三十五岁，生了沙拉。","notes":[]},{"n":13,"t":"亚法撒生沙拉之后又活了四百零三年，并且生儿育女。","notes":[]},{"n":14,"t":"沙拉活到三十岁，生了希伯。","notes":[]},{"n":15,"t":"沙拉生希伯之后又活了四百零三年，并且生儿育女。","notes":[]},{"n":16,"t":"希伯活到三十四岁，生了法勒。","notes":[]},{"n":17,"t":"希伯生法勒之后又活了四百三十年，并且生儿育女。","notes":[]},{"n":18,"t":"法勒活到三十岁，生了拉吴。","notes":[]},{"n":19,"t":"法勒生拉吴之后又活了二百零九年，并且生儿育女。","notes":[]},{"n":20,"t":"拉吴活到三十二岁，生了西鹿。","notes":[]},{"n":21,"t":"拉吴生西鹿之后又活了二百零七年，并且生儿育女。","notes":[]},{"n":22,"t":"西鹿活到三十岁，生了拿鹤。","notes":[]},{"n":23,"t":"西鹿生拿鹤之后又活了二百年，并且生儿育女。","notes":[]},{"n":24,"t":"拿鹤活到二十九岁，生了他拉。","notes":[]},{"n":25,"t":"拿鹤生他拉之后又活了一百一十九年，并且生儿育女。","notes":[]},{"n":26,"t":"他拉活到七十岁，生了亚伯兰、拿鹤和哈兰。","notes":[]},{"n":27,"t":"这是他拉的后代。他拉生亚伯兰、拿鹤和哈兰；哈兰生罗得。","notes":[],"heads":["他拉的后代"]},{"n":28,"t":"哈兰死在他父亲他拉的面前，死在他的出生地迦勒底的吾珥。","notes":[]},{"n":29,"t":"亚伯兰、拿鹤各娶了妻。亚伯兰的妻子名叫撒莱，拿鹤的妻子名叫密迦，是哈兰的女儿。哈兰是密迦和亦迦的父亲。","notes":[]},{"n":30,"t":"撒莱不生育，没有孩子。","notes":[]},{"n":31,"t":"他拉带着他儿子亚伯兰和他孙子，哈兰的儿子罗得，以及他的媳妇，亚伯兰的妻子撒莱，一同出了迦勒底的吾珥，要往迦南地去；他们来到哈兰，就住在那里。","notes":[]},{"n":32,"t":"他拉共活了二百零五年，就死在哈兰。","notes":[]}]},"12":{"heading":"神呼召亚伯兰","verses":[{"n":1,"t":"耶和华对亚伯兰说：“你要离开本地、本族、父家，往我所要指示你的地去。","notes":[]},{"n":2,"t":"我必使你成为大国，我必赐福给你，使你的名为大；你要使别人得福。","notes":["“你要使别人得福”：原文是“你要成为福气”。"]},{"n":3,"t":"为你祝福的，我必赐福给他；诅咒你的，我必诅咒他。地上的万族都必因你得福。”","notes":[]},{"n":4,"t":"亚伯兰就遵照耶和华的吩咐去了；罗得也和他同去。亚伯兰离开哈兰的时候年七十五岁。","notes":[]},{"n":5,"t":"亚伯兰带着他妻子撒莱和侄儿罗得，以及他们在哈兰积蓄的财物、获得的人口，往迦南地去。他们就来到了迦南地。","notes":[]},{"n":6,"t":"亚伯兰经过那地，直到示剑地方，摩利橡树那里；当时迦南人住在那地。","notes":[]},{"n":7,"t":"耶和华向亚伯兰显现，说：“我要把这地赐给你的后裔。”亚伯兰就在那里为向他显现的耶和华筑了一座坛。","notes":[]},{"n":8,"t":"从那里他又迁到伯特利东边的山，支搭帐棚；西边是伯特利，东边是艾。他在那里又为耶和华筑了一座坛，求告耶和华的名。","notes":[]},{"n":9,"t":"后来亚伯兰渐渐迁往尼革夫去。","notes":["“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”；本卷书下同。"]},{"n":10,"t":"那地遭遇饥荒。亚伯兰因那地的饥荒严重，就下到埃及，要在那里寄居。","notes":[],"heads":["亚伯兰到埃及"]},{"n":11,"t":"将近埃及，他对妻子撒莱说：“看哪，我知道你是美貌的女人。","notes":[]},{"n":12,"t":"埃及人看见你会说：‘这是他的妻子’，他们就会杀我，却让你活着。","notes":[]},{"n":13,"t":"所以，请你说你是我的妹妹，使我可以因你得平安，我的性命也因你存活。”","notes":[]},{"n":14,"t":"亚伯兰到达埃及时，埃及人看见那女人极其美貌。","notes":[]},{"n":15,"t":"法老的臣仆看见了她，就在法老面前称赞她。那女人就被带进法老的宫中。","notes":[]},{"n":16,"t":"法老就因她厚待亚伯兰，给了亚伯兰许多牛、羊、公驴、奴仆、婢女、母驴、骆驼。","notes":[]},{"n":17,"t":"耶和华因亚伯兰妻子撒莱的缘故，降大灾击打法老和他的全家。","notes":[]},{"n":18,"t":"法老召了亚伯兰来，说：“你向我做的是什么事呢？为什么没有告诉我她是你的妻子？","notes":[]},{"n":19,"t":"为什么说‘她是我的妹妹’，以致我把她接来要作我的妻子呢？现在 ，看哪，你的妻子在这里，带她走吧！”","notes":[]},{"n":20,"t":"于是法老吩咐人把亚伯兰和他妻子，以及他一切所有的都送走了。","notes":[]}]},"13":{"heading":"亚伯兰跟罗得分手","verses":[{"n":1,"t":"亚伯兰带着他的妻子与罗得，以及一切所有的，从埃及上尼革夫去。","notes":[]},{"n":2,"t":"亚伯兰的牲畜和金银极多。","notes":[]},{"n":3,"t":"他从尼革夫渐渐往伯特利去，到了伯特利和艾的中间，当初他支搭帐棚的地方，","notes":[]},{"n":4,"t":"也是他起先筑坛的地方。亚伯兰在那里求告耶和华的名。","notes":[]},{"n":5,"t":"与亚伯兰同行的罗得也有牛群、羊群、帐棚。","notes":[]},{"n":6,"t":"那地容不下他们住在一起；因为他们的财物非常多，使他们不能同住一起。","notes":[]},{"n":7,"t":"当时，迦南人与比利洗人在那地居住。亚伯兰的牧人和罗得的牧人之间起了争端。","notes":[]},{"n":8,"t":"亚伯兰就对罗得说：“你我不可以相争，你的牧人和我的牧人也不可以相争，因为我们是一家人。","notes":[]},{"n":9,"t":"遍地不都在你眼前吗？请你离开我吧！你向左，我就向右；你向右，我就向左。”","notes":[]},{"n":10,"t":"罗得举目，看见约旦河整个平原，直到琐珥，都是水源充足之地。在耶和华未毁灭所多玛、蛾摩拉以前，那地好像耶和华的园子，又像埃及地。","notes":[]},{"n":11,"t":"于是罗得选择了约旦河整个平原。罗得往东迁移，他们就彼此分开了。","notes":[]},{"n":12,"t":"亚伯兰住在迦南地；罗得住在平原的城镇，他渐渐迁移帐棚，直到所多玛。","notes":[]},{"n":13,"t":"所多玛人在耶和华面前罪大恶极。","notes":[]},{"n":14,"t":"罗得离开亚伯兰以后，耶和华对亚伯兰说：“你要从你所在的地方，举目向东西南北观看；","notes":[],"heads":["亚伯兰迁往希伯仑"]},{"n":15,"t":"你所看见一切的地，我都要把它赐给你和你的后裔，直到永远。","notes":[]},{"n":16,"t":"我要使你的后裔好像地上的尘沙，人若能数地上的尘沙，才能数你的后裔。","notes":[]},{"n":17,"t":"你起来，纵横走遍这地，因为我必把这地赐给你。”","notes":[]},{"n":18,"t":"亚伯兰就迁移帐棚，来到希伯仑，幔利的橡树那里居住，在那里为耶和华筑了一座坛。","notes":[]}]},"14":{"heading":"亚伯兰抢救罗得","verses":[{"n":1,"t":"当暗拉非作示拿王，亚略作以拉撒王，基大老玛作以拦王，提达作戈印王的时候，","notes":[]},{"n":2,"t":"他们攻打所多玛王比拉、蛾摩拉王比沙、押玛王示纳、洗扁王善以别和比拉王，比拉就是琐珥。","notes":[]},{"n":3,"t":"这些王都会合在西订谷，西订谷就是盐海。","notes":[]},{"n":4,"t":"他们已经服事基大老玛十二年，第十三年就背叛了。","notes":[]},{"n":5,"t":"第十四年，基大老玛和与他结盟的王都来了，在亚特律．加宁击败利乏音人，在哈麦击败苏西人，在沙微．基列亭击败以米人，","notes":[]},{"n":6,"t":"在何利人的西珥山击败何利人，一直到靠近旷野的伊勒．巴兰。","notes":[]},{"n":7,"t":"他们转回，来到安．密巴，就是加低斯，击败了亚玛力全地的人，以及住在哈洗逊．他玛的亚摩利人。","notes":[]},{"n":8,"t":"于是所多玛王、蛾摩拉王、押玛王、洗扁王和比拉王，比拉就是琐珥，都出来，在西订谷摆阵，与他们交战，","notes":[]},{"n":9,"t":"就是与以拦王基大老玛、戈印王提达、示拿王暗拉非、以拉撒王亚略交战；这就是四王对五王之战。","notes":[]},{"n":10,"t":"西订谷有许多柏油坑。所多玛王和蛾摩拉王逃跑，掉在坑里，其余的人都往山上逃跑。","notes":[]},{"n":11,"t":"四王就把所多玛和蛾摩拉所有的财物和所有的粮食都掳掠去了；","notes":[]},{"n":12,"t":"他们也把亚伯兰的侄儿罗得和罗得的财物都掳掠去了。当时罗得住在所多玛。","notes":[]},{"n":13,"t":"有一个逃脱的人来告诉希伯来人亚伯兰；亚伯兰正住在亚摩利人幔利的橡树那里。幔利、以实各和亚乃都是弟兄，曾与亚伯兰结盟。","notes":[]},{"n":14,"t":"亚伯兰听见他侄儿 被掳去，就把三百一十八个生在他家中、受过训练的壮丁全都出动去追，一直到但。","notes":["“侄儿”：原文是“弟兄”；下同。","“就把...全都出动”：有古卷是“就率领三百一十八个生在他家中、受过训练的壮丁”。"]},{"n":15,"t":"在夜间，他和他的仆人分队击败了敌人，并且追杀他们，直到大马士革北边的何把。","notes":[]},{"n":16,"t":"他把一切被掳掠的财物夺回，也把他侄儿罗得和他的财物，以及人和妇女都夺回来。","notes":[]},{"n":17,"t":"亚伯兰击败基大老玛和与他结盟的王回来的时候，所多玛王出来，在沙微谷迎接他，沙微谷就是王的谷。","notes":[],"heads":["麦基洗德祝福亚伯兰"]},{"n":18,"t":"又有撒冷王麦基洗德带着饼和酒出来；他是至高神的祭司。","notes":[]},{"n":19,"t":"他为亚伯兰祝福，说：“愿至高的神、天地的主赐福给亚伯兰！","notes":[]},{"n":20,"t":"至高的神把敌人交在你手里，他是应当称颂的！”亚伯兰就把所有的拿出十分之一给他。","notes":[]},{"n":21,"t":"所多玛王对亚伯兰说：“你把人还给我，财物你自己拿去吧！”","notes":[]},{"n":22,"t":"亚伯兰对所多玛王说：“我指着耶和华—至高的神、天地的主起誓：","notes":[]},{"n":23,"t":"凡是你的东西，就是一根线、一条鞋带，我都不拿，免得你说：‘是我使亚伯兰富足！’","notes":[]},{"n":24,"t":"我什么都不要，只是仆人所吃的，以及与我同去的亚乃、以实各、幔利所应得的份，让他们拿去吧！”","notes":[]}]},"15":{"heading":"神与亚伯兰立约","verses":[{"n":1,"t":"这些事以后，耶和华的话在异象中临到亚伯兰，说：“亚伯兰哪，不要惧怕！我是你的盾牌，你必得丰富的赏赐。”","notes":[]},{"n":2,"t":"亚伯兰说：“主耶和华啊，我还没有儿子，你能赐我什么呢？承受我家业的是大马士革人以利以谢。”","notes":[]},{"n":3,"t":"亚伯兰又说：“看哪，你没有给我后嗣。你看，那生在我家中的人要继承我。”","notes":[]},{"n":4,"t":"看哪，耶和华的话又临到他，说：“这人不会继承你，你本身所生的才会继承你。”","notes":[]},{"n":5,"t":"于是耶和华带他到外面，说：“你向天观看，去数星星，你能数得清吗？”又对他说：“你的后裔将要如此。”","notes":[]},{"n":6,"t":"亚伯兰信耶和华，耶和华就以此算他为义。","notes":[]},{"n":7,"t":"耶和华又对他说：“我是耶和华，曾领你出迦勒底的吾珥，为要把这地赐你为业。”","notes":[]},{"n":8,"t":"亚伯兰说：“主耶和华啊，我怎能知道我必得这地为业呢？”","notes":[]},{"n":9,"t":"耶和华对他说：“你为我取一头三岁的母牛犊，一只三岁的母山羊，一只三岁的公绵羊，一只斑鸠和一只雏鸽。”","notes":[]},{"n":10,"t":"亚伯兰就把这些都取来，每样从中间劈成两半，一半对着另一半排列，只有鸟没有劈开。","notes":[]},{"n":11,"t":"当鸷鸟下来，落在这些尸体上时，亚伯兰就把它们赶走了。","notes":[]},{"n":12,"t":"日落的时候，亚伯兰沉睡了。看哪，有大而可怕的黑暗落在他身上。","notes":[]},{"n":13,"t":"耶和华对亚伯兰说：“你要确实知道，你的后裔必寄居在别人的地，服事那地的人；那地的人要虐待他们四百年。","notes":[]},{"n":14,"t":"但我要惩罚他们所服事的那国，以后他们必带着许多财物从那里出来。","notes":[]},{"n":15,"t":"至于你，你要平平安安归到你祖先那里，必享长寿，被人埋葬。","notes":[]},{"n":16,"t":"到了第四代，他们必回到这里，因为亚摩利人的罪恶到现在还没有满盈。”","notes":[]},{"n":17,"t":"日落天黑的时候，看哪，有冒烟的炉和烧着的火把从那些肉块中经过。","notes":[]},{"n":18,"t":"在那日，耶和华与亚伯兰立约，说：“我已赐给你的后裔这一片地，从埃及河直到大河，幼发拉底河，","notes":[]},{"n":19,"t":"就是基尼人、基尼洗人、甲摩尼人、","notes":[]},{"n":20,"t":"赫人、比利洗人、利乏音人、","notes":[]},{"n":21,"t":"亚摩利人、迦南人、革迦撒人、耶布斯人的地。”","notes":[]}]},"16":{"heading":"夏甲与以实玛利","verses":[{"n":1,"t":"亚伯兰的妻子撒莱没有为他生孩子。撒莱有一个婢女，是埃及人，名叫夏甲。","notes":[]},{"n":2,"t":"撒莱对亚伯兰说：“看哪，耶和华使我不能生育。你来和我的婢女同房，也许我可以从她得孩子 。”亚伯兰听从了撒莱的话。","notes":["“得孩子”：原文是“被建立”。"]},{"n":3,"t":"于是亚伯兰的妻子撒莱把她的婢女，埃及人夏甲，给了丈夫为妾；那时亚伯兰在迦南已经住了十年。","notes":[]},{"n":4,"t":"亚伯兰与夏甲同房，夏甲就怀了孕。她看见自己有孕，就轻视她的女主人。","notes":[]},{"n":5,"t":"撒莱对亚伯兰说：“我因你受了委屈。我把我的婢女放在你怀中，她见自己怀了孕，就轻视我。愿耶和华在你我之间判断。”","notes":[]},{"n":6,"t":"亚伯兰对撒莱说：“看哪，婢女在你手里，你可以照你看为好的对待她。”于是，撒莱虐待她，她就从撒莱面前逃走了。","notes":[]},{"n":7,"t":"耶和华的使者在旷野的水泉旁，在书珥路上的水泉旁遇见夏甲，","notes":[]},{"n":8,"t":"对她说：“撒莱的婢女夏甲，你从哪里来？要到哪里去？”她说：“我从我的女主人撒莱面前逃出来。”","notes":[]},{"n":9,"t":"耶和华的使者对她说：“你要回到你的女主人那里，屈服在她手下。”","notes":[]},{"n":10,"t":"耶和华的使者对她说：“我必使你的后裔极其繁多，多到不可胜数。”","notes":[]},{"n":11,"t":"耶和华的使者又对她说：“看哪，你已怀孕，要生一个儿子。你要给他起名叫以实玛利 ，因为耶和华听见了你的苦楚。","notes":["“以实玛利”意思是“神听见”。"]},{"n":12,"t":"他为人必像野驴。他的手要攻打人，人的手也要攻打他；他必常与他的众弟兄作对 。”","notes":["“他必...作对”或译“他必住在众弟兄的对面”。"]},{"n":13,"t":"夏甲就称那向她说话的耶和华为“你是看见的神”，因为她说：“他看见了我之后，我还能在这里看见他吗？”","notes":["“看见”或译“看顾”。"]},{"n":14,"t":"所以这井名叫庇耳．拉海．莱，看哪，它位于加低斯和巴列的中间。","notes":["“庇耳．拉海．莱”意思是“‘看见我的永活者’之井”。"]},{"n":15,"t":"后来夏甲为亚伯兰生了一个儿子；亚伯兰给夏甲生的儿子起名叫以实玛利。","notes":[]},{"n":16,"t":"夏甲为亚伯兰生以实玛利的时候，亚伯兰年八十六岁。","notes":[]}]},"17":{"heading":"割礼为立约的记号","verses":[{"n":1,"t":"亚伯兰九十九岁时，耶和华向他显现，对他说：“我是全能的神。你当在我面前行走，作完全的人，","notes":[]},{"n":2,"t":"我要与你立约，使你的后裔极其繁多。”","notes":[]},{"n":3,"t":"亚伯兰脸伏于地；神又对他说：","notes":[]},{"n":4,"t":"“看哪，这就是我与你立的约，你要成为多国的父。","notes":[]},{"n":5,"t":"从今以后，你的名字不再叫亚伯兰，要叫亚伯拉罕，因为我已经立你作多国之父。","notes":[]},{"n":6,"t":"我必使你生养极其繁多；国度要从你而立，君王要从你而出。","notes":[]},{"n":7,"t":"我要与你，以及你世世代代的后裔坚立我的约，成为永远的约，是要作你和你后裔的神。","notes":[]},{"n":8,"t":"我要把你现在寄居的地，就是迦南全地，赐给你和你的后裔永远为业；我也必作他们的神。”","notes":[]},{"n":9,"t":"神又对亚伯拉罕说：“你和你的后裔一定要世世代代遵守我的约。","notes":[]},{"n":10,"t":"这就是我与你，以及你的后裔所立的约，是你们所当遵守的，你们所有的男子都要受割礼。","notes":[]},{"n":11,"t":"你们要割去肉体的包皮，这是我与你们立约的记号。","notes":[]},{"n":12,"t":"你们世世代代的男子，无论是在家里生的，或是用银子从外人买来而不是你后裔生的，都要在生下来的第八日受割礼。","notes":[]},{"n":13,"t":"你家里生的和你用银子买的，都必须受割礼。这样，我的约就在你们肉体上成为永远的约。","notes":[]},{"n":14,"t":"不受割礼的男子都必从民中剪除，因他违背了我的约。”","notes":[]},{"n":15,"t":"神又对亚伯拉罕说：“至于你的妻子撒莱，不可再叫她撒莱，她的名要叫撒拉。","notes":[]},{"n":16,"t":"我必赐福给她，也要从她赐一个儿子给你。我必赐福给撒拉，她要兴起多国；必有百姓的君王从她而出。”","notes":[]},{"n":17,"t":"亚伯拉罕就脸伏于地窃笑，心里想：“一百岁的人还能有孩子吗？撒拉已经九十岁了，还能生育吗？”","notes":[]},{"n":18,"t":"亚伯拉罕对神说：“但愿以实玛利活在你面前。”","notes":[]},{"n":19,"t":"神说：“不！你妻子撒拉必为你生一个儿子，你要给他起名叫以撒。我要与他坚立我的约，成为他后裔永远的约。","notes":[]},{"n":20,"t":"至于以实玛利，我已听见你了：看哪，我必赐福给他，使他兴旺，极其繁多。他必生十二个族长，我要使他成为大国。","notes":[]},{"n":21,"t":"到明年所定的时候，撒拉必为你生以撒，我要与他坚立我的约。”","notes":[]},{"n":22,"t":"神和亚伯拉罕说完了话，就离开他上升去了。","notes":[]},{"n":23,"t":"在那一天，亚伯拉罕遵照神所说的，给他的儿子以实玛利和家里所有的男丁，无论是在家里生的，或是用银子买来的，都行了割礼。","notes":["“行了割礼”：原文是“割了肉体的包皮”；24、 25节的“割礼”同。"]},{"n":24,"t":"亚伯拉罕受割礼时，年九十九岁。","notes":[]},{"n":25,"t":"他儿子以实玛利受割礼时，年十三岁。","notes":[]},{"n":26,"t":"在那一天，亚伯拉罕和他儿子以实玛利一同受了割礼。","notes":[]},{"n":27,"t":"家里所有的男人，无论是在家里生的，或是用银子从外人买来的，也都一同受了割礼。","notes":[]}]},"18":{"heading":"亚伯拉罕得儿子的应许","verses":[{"n":1,"t":"耶和华在幔利橡树那里向亚伯拉罕显现。天正热的时候，亚伯拉罕坐在帐棚门口。","notes":[]},{"n":2,"t":"他举目观看，看哪，有三个人站在他附近。他一看见，就从帐棚门口跑去迎接他们，俯伏在地，","notes":[]},{"n":3,"t":"说：“我主，我若在你眼前蒙恩，请不要离开你的仆人走过去。","notes":[]},{"n":4,"t":"容我拿点水来，请你们洗脚，在树下休息。","notes":[]},{"n":5,"t":"既然你们来到仆人这里了，我再拿点饼来，让你们恢复心力，然后再走。”他们说：“就照你说的去做吧。”","notes":[]},{"n":6,"t":"亚伯拉罕急忙进帐棚到撒拉那里，说：“你赶快拿三细亚细面，揉面做饼。”","notes":[]},{"n":7,"t":"亚伯拉罕又跑到牛群里，牵了一头又嫩又好的牛犊来，交给仆人，仆人就急忙去预备。","notes":[]},{"n":8,"t":"亚伯拉罕取了乳酪和奶，以及预备好了的牛犊来，摆在他们面前，自己在树下站在旁边，他们就吃了。","notes":[]},{"n":9,"t":"他们对亚伯拉罕说：“你妻子撒拉在哪里？”他说：“看哪，在帐棚里。”","notes":[]},{"n":10,"t":"有一位说：“明年这时候 ，我一定会回到你这里。看哪，你的妻子撒拉会生一个儿子。”撒拉在那人后面的帐棚门口也听见了。","notes":["“明年这时候”：原文是“生命足月的时候”；14节同。"]},{"n":11,"t":"亚伯拉罕和撒拉都年纪老迈，撒拉的月经已停了。","notes":[]},{"n":12,"t":"撒拉心里窃笑，说：“我已衰老，我的主也老了，怎能有这喜事呢？”","notes":[]},{"n":13,"t":"耶和华对亚伯拉罕说：“撒拉为什么窃笑，说：‘我已年老，果真能生育吗？’","notes":[]},{"n":14,"t":"耶和华岂有难成的事吗？到了所定的时候，我必回到你这里。明年这时候，撒拉会生一个儿子。”","notes":[]},{"n":15,"t":"撒拉因为害怕，就不承认，说：“我没有笑。”那人说：“不，你的确笑了。”","notes":[]},{"n":16,"t":"三人从那里起程，面向所多玛观望，亚伯拉罕与他们同行，要送他们一程。","notes":[],"heads":["亚伯拉罕为所多玛祈求"]},{"n":17,"t":"耶和华说：“我所要做的事岂可瞒着亚伯拉罕呢？","notes":[]},{"n":18,"t":"亚伯拉罕必要成为强大的国；地上的万国都必因他得福。","notes":[]},{"n":19,"t":"我拣选他，为要叫他命令他的子孙和后代家属遵行耶和华的道，秉公行义，使耶和华所应许亚伯拉罕的话都实现了。”","notes":["“拣选他”：原文是“认识他”。"]},{"n":20,"t":"耶和华说：“所多玛和蛾摩拉罪恶极其严重，控告他们的声音很大。","notes":[]},{"n":21,"t":"我要下去察看他们所做的，是否真的像那达到我这里的声音一样；如果不是，我也要知道。”","notes":[]},{"n":22,"t":"二人转身离开那里，往所多玛去；但亚伯拉罕仍然站在耶和华面前。","notes":[]},{"n":23,"t":"亚伯拉罕近前来，说：“你真的要把义人和恶人一同剿灭吗？","notes":[]},{"n":24,"t":"假若那城里有五十个义人，你真的还要剿灭，不因城里这五十个义人饶了那地方吗？","notes":[]},{"n":25,"t":"你绝不会做这样的事，把义人与恶人一同杀了，使义人与恶人一样。你绝不会这样！审判全地的主岂不做公平的事吗？”","notes":[]},{"n":26,"t":"耶和华说：“我若在所多玛城里找到五十个义人，我就为他们的缘故饶恕那整个地方。”","notes":[]},{"n":27,"t":"亚伯拉罕回答说：“看哪，我虽只是尘土灰烬，还敢向主说话。","notes":[]},{"n":28,"t":"假若这五十个义人少了五个，你就因为少了五个而毁灭全城吗？”他说：“我在那里若找到四十五个，就不毁灭。”","notes":[]},{"n":29,"t":"亚伯拉罕又对他说：“假若在那里找到四十个呢？”他说：“为这四十个的缘故，我也不做。”","notes":[]},{"n":30,"t":"亚伯拉罕说：“求主不要生气，容我说，假若在那里找到三十个呢？”他说：“我在那里若找到三十个，我也不做。”","notes":[]},{"n":31,"t":"亚伯拉罕说：“看哪，我还敢向主说，假若在那里找到二十个呢？”他说：“为这二十个的缘故，我也不毁灭。”","notes":[]},{"n":32,"t":"亚伯拉罕说：“求主不要生气，我再说一次，假若在那里找到十个呢？”他说：“为这十个的缘故，我也不毁灭。”","notes":[]},{"n":33,"t":"耶和华与亚伯拉罕说完了话就走了；亚伯拉罕也回到自己的地方去了。","notes":[]}]},"19":{"heading":"所多玛的罪恶","verses":[{"n":1,"t":"两个天使在傍晚到了所多玛，罗得正坐在所多玛的城门口。罗得一看见，就起身迎接他们，脸伏于地下拜，","notes":[]},{"n":2,"t":"说：“看哪，我主，请你们转到仆人家里过夜，洗你们的脚，清早起来再上路。”他们说：“不！我们要在广场上过夜。”","notes":[]},{"n":3,"t":"罗得恳切地请他们，他们就转向他，进到他屋里。罗得为他们预备宴席，烤无酵饼，他们就吃了。","notes":[]},{"n":4,"t":"他们还没有躺下，所多玛城的人，连老带少所有的人，个个都来围住那屋子。","notes":[]},{"n":5,"t":"他们呼叫罗得，对他说：“今天晚上到你这里来的人在哪里？把他们带出来，让我们亲近他们。”","notes":[]},{"n":6,"t":"罗得出了门，把身后的门关上，到众人那里，","notes":[]},{"n":7,"t":"说：“我的弟兄们，请你们不要做这恶事。","notes":[]},{"n":8,"t":"看哪，我有两个女儿，还没有亲近过男人，让我领她们出来给你们，就照你们看为好的对待她们吧！只是这两个人既然到我舍下，请不要向他们做这事。”","notes":[]},{"n":9,"t":"众人说：“站到一边去吧！”又说：“这个人来寄居，还想扮审判官呢！现在我们要害你比害他们更厉害。”众人就往前冲向罗得，要攻破大门。","notes":[]},{"n":10,"t":"那两个人伸出手来，把罗得拉进屋子他们那里，就关上门。","notes":[]},{"n":11,"t":"他们击打门外的人，无论老少，都眼睛迷糊，找门找得很烦躁。","notes":[]},{"n":12,"t":"那两个人对罗得说：“你这里还有什么人吗？无论是女婿，是儿女，这城中所有属你的人，你都要把他们从这地方带出去。","notes":[],"heads":["罗得离开所多玛"]},{"n":13,"t":"我们要毁灭这地方，因为控告城内百姓的声音在耶和华面前非常大，耶和华派我们来毁灭这城。”","notes":[]},{"n":14,"t":"罗得出去，告诉娶了他女儿的女婿们说：“起来，离开这地方，因为耶和华要毁灭这城。”他的女婿们却以为他说的是笑话。","notes":["“娶了”或译“将要娶”。"]},{"n":15,"t":"天亮了，天使催逼罗得说：“起来！带着你的妻子和你这里的两个女儿出去，免得你因这城的罪孽同被剿灭。”","notes":[]},{"n":16,"t":"但罗得迟延不走。二人因为耶和华怜悯罗得，就拉着他的手和他妻子的手，以及他两个女儿的手，把他们领出来，安置在城外；","notes":[]},{"n":17,"t":"领他们出来以后，就说：“逃命吧！不可回头看，也不可在平原站住。要往山上逃跑，免得你被剿灭。”","notes":[]},{"n":18,"t":"罗得对他们说：“我主啊，不要这样！","notes":[]},{"n":19,"t":"看哪，你仆人已经在你眼前蒙恩，你又向我大施慈爱，救我的性命。但是我不能逃到山上去，恐怕这灾祸追上我，我就死了。","notes":[]},{"n":20,"t":"看哪，这城又近又小，比较容易逃到那里。这不是一座小城吗？求你容我逃到那里，使我的性命可以存活。”","notes":[]},{"n":21,"t":"天使对他说：“看哪，这事我也应允你，不倾覆你所说的这城。","notes":[]},{"n":22,"t":"你要赶快逃到那城，因为你还没有到那里，我不能做什么。”因此那城名叫琐珥 。","notes":["“琐珥”意思是“小”。"]},{"n":23,"t":"罗得到了琐珥，太阳已经升出地面。","notes":[],"heads":["所多玛蛾摩拉的毁灭"]},{"n":24,"t":"当时，耶和华把硫磺与火，从天上耶和华那里降与所多玛和蛾摩拉，","notes":[]},{"n":25,"t":"把那些城和全平原，城里所有的居民和土地上生长的，都毁灭了。","notes":[]},{"n":26,"t":"罗得的妻子在他后边回头一看，就变成了一根盐柱。","notes":[]},{"n":27,"t":"亚伯拉罕清早起来，到了他先前站在耶和华面前的地方，","notes":[]},{"n":28,"t":"面向所多玛和蛾摩拉，以及平原全地观望。他观看，看哪，那地有浓烟上腾，好像烧窑的浓烟。","notes":[]},{"n":29,"t":"当神毁灭平原诸城的时候，他记念亚伯拉罕；在倾覆罗得所住之城的时候，就把罗得从倾覆中带出来。","notes":[]},{"n":30,"t":"罗得因为怕住在琐珥，就同他两个女儿从琐珥上去，住在山上。他和两个女儿住在一个洞里。","notes":[],"heads":["摩押人和亚扪人的起源"]},{"n":31,"t":"大女儿对小女儿说：“我们的父亲老了，这地又没有男人可以照世上的礼俗来与我们结合。","notes":[]},{"n":32,"t":"来！我们叫父亲喝酒，然后与他同寝。这样，我们可以从我们的父亲存留后裔。”","notes":[]},{"n":33,"t":"于是，那晚她们叫父亲喝酒，大女儿就进去和她父亲同寝；她几时躺下，几时起来，父亲都不知道。","notes":[]},{"n":34,"t":"第二天，大女儿对小女儿说：“看哪，我昨夜与父亲同寝。今晚我们再叫他喝酒，你进去与他同寝。这样，我们可以从父亲存留后裔。”","notes":[]},{"n":35,"t":"于是，那晚她们又叫父亲喝酒，小女儿起来与她父亲同寝；她几时躺下，几时起来，父亲都不知道。","notes":[]},{"n":36,"t":"这样，罗得的两个女儿都从她们的父亲怀了孕。","notes":[]},{"n":37,"t":"大女儿生了儿子，给他起名叫摩押，就是现今摩押人的始祖。","notes":[]},{"n":38,"t":"小女儿也生了儿子，给他起名叫便．亚米，就是现今亚扪人的始祖。","notes":[]}]},"20":{"heading":"亚伯拉罕和亚比米勒","verses":[{"n":1,"t":"亚伯拉罕从那里往尼革夫迁移，寄居在加低斯和书珥之间的基拉耳。","notes":[]},{"n":2,"t":"亚伯拉罕称他的妻子撒拉为妹妹。基拉耳王亚比米勒派人把撒拉带走。","notes":[]},{"n":3,"t":"夜间，神在梦中来到亚比米勒那里，对他说：“看哪，你要死了，因为你带来的女人，她是有丈夫的女子！”","notes":[]},{"n":4,"t":"亚比米勒还未亲近撒拉；他说：“主啊，连公义的国，你也要毁灭吗？","notes":[]},{"n":5,"t":"那人岂不是自己对我说‘她是我妹妹’吗？连这女人自己也说：‘他是我哥哥。’我做这事是心正手洁的。”","notes":[]},{"n":6,"t":"神在梦中对他说：“我也知道你做这事是心中正直的；是我拦阻了你，免得你得罪我。所以我不让你侵犯她。","notes":[]},{"n":7,"t":"现在你当把这人的妻子归还给他；因为他是先知，他要为你祷告，使你存活。你若不归还，你当知道，你和你所有的人都必定死。”","notes":[]},{"n":8,"t":"亚比米勒清早起来，叫了他的众臣仆来，把这一切事说给他们听，他们就很害怕。","notes":[]},{"n":9,"t":"亚比米勒召了亚伯拉罕来，对他说：“你怎么向我这样做呢？我什么事得罪你，你竟使我和我的国陷在大罪中呢？你对我做了不该做的事了！”","notes":[]},{"n":10,"t":"亚比米勒对亚伯拉罕说：“你看见什么才做这事呢？”","notes":[]},{"n":11,"t":"亚伯拉罕说：“我以为这地方的人根本不敬畏神，必为我妻子的缘故杀我。","notes":[]},{"n":12,"t":"况且她也真是我的妹妹；她与我是同父异母的，后来作了我的妻子。","notes":[]},{"n":13,"t":"当神叫我离开父家、飘流在外的时候，我对她说：我们无论走到什么地方，你要对人说：‘他是我哥哥’，这就是你以慈爱待我了。”","notes":[]},{"n":14,"t":"亚比米勒把牛、羊、奴仆、婢女送给亚伯拉罕，也把他的妻子撒拉归还给他。","notes":[]},{"n":15,"t":"亚比米勒说：“看哪，我的地都在你面前，你看为好的地方就居住吧。”","notes":[]},{"n":16,"t":"他对撒拉说：“看哪，我给你哥哥一千银子。看哪，这要在你全家人面前遮羞，向众人证实你是清白的。”","notes":["“羞”：原文是“眼”。"]},{"n":17,"t":"亚伯拉罕向神祷告，神就医好亚比米勒和他的妻子，以及他的使女们，他们就能生育。","notes":[]},{"n":18,"t":"因耶和华为亚伯拉罕的妻子撒拉的缘故，已经使亚比米勒家中的妇人不能怀孕。","notes":[]}]},"21":{"heading":"以撒出生","verses":[{"n":1,"t":"耶和华照着他所说的眷顾撒拉，耶和华实现了他对撒拉的应许。","notes":[]},{"n":2,"t":"亚伯拉罕年老，到神对他说的那所定的时候，撒拉怀了孕，给他生了一个儿子。","notes":[]},{"n":3,"t":"亚伯拉罕给撒拉所生的儿子起名叫以撒。","notes":[]},{"n":4,"t":"以撒出生后第八日，亚伯拉罕遵照神所吩咐的，为以撒行割礼。","notes":[]},{"n":5,"t":"他儿子以撒出生的时候，亚伯拉罕年一百岁。","notes":[]},{"n":6,"t":"撒拉说：“神使我欢笑，凡听见的人必与我一同欢笑”，","notes":[]},{"n":7,"t":"又说：“谁能预先对亚伯拉罕说，撒拉要乳养孩子呢？因为在他年老的时候，我为他生了一个儿子。”","notes":[]},{"n":8,"t":"孩子渐渐长大，就断了奶。以撒断奶的那一天，亚伯拉罕摆设丰盛的宴席。","notes":[]},{"n":9,"t":"那时，撒拉看见埃及人夏甲为亚伯拉罕所生的儿子戏笑，","notes":[],"heads":["夏甲和以实玛利被逐"]},{"n":10,"t":"就对亚伯拉罕说：“你把这使女和她儿子赶出去！因为这使女的儿子不可与我的儿子以撒一同承受产业。”","notes":[]},{"n":11,"t":"亚伯拉罕为这事非常忧愁，因为关乎他的儿子。","notes":[]},{"n":12,"t":"神对亚伯拉罕说：“你不必为这孩子和你的使女忧愁。撒拉对你说的话，你都要听从；因为从以撒生的，才要称为你的后裔。","notes":[]},{"n":13,"t":"至于使女的儿子，我也必使他成为一国，因为他是你的后裔。”","notes":[]},{"n":14,"t":"亚伯拉罕清早起来，拿饼和一皮袋水，给了夏甲，搭在她肩上，把她和孩子一起送走。夏甲就走了，但她却在别是巴的旷野流浪。","notes":[]},{"n":15,"t":"皮袋的水用完了，夏甲就把孩子放在一棵小树下，","notes":[]},{"n":16,"t":"自己走开约有一箭之远，相对而坐，说：“我不忍心看见孩子死”。她就坐在对面，放声大哭。","notes":[]},{"n":17,"t":"神听见孩子的声音，神的使者就从天上呼叫夏甲说：“夏甲，你为何这样呢？不要害怕，神已经听见孩子在那里的声音了。","notes":[]},{"n":18,"t":"起来！把孩子扶起来，用你的手握住他，因我必使他成为大国。”","notes":[]},{"n":19,"t":"神开了夏甲的眼睛，她就看见一口水井。她就去，把皮袋装满了水，给孩子喝。","notes":[]},{"n":20,"t":"神与这孩子同在，他就渐渐长大，住在旷野，成了一个弓箭手。","notes":[]},{"n":21,"t":"他住在巴兰的旷野；他母亲从埃及地为他娶了一个妻子。","notes":[]},{"n":22,"t":"那时候，亚比米勒和他的将军非各对亚伯拉罕说：“凡你所做的事，神都与你同在。","notes":[],"heads":["亚伯拉罕与亚比米勒立约"]},{"n":23,"t":"我愿你如今在这里指着神对我起誓，不要亏待我和我的儿子，以及我的子孙。我怎样忠诚待你，你也要照样忠诚待我和你所寄居的这地。”","notes":[]},{"n":24,"t":"亚伯拉罕说：“我愿意起誓。”","notes":[]},{"n":25,"t":"先前，亚比米勒的仆人霸占了一口水井，亚伯拉罕为这事责备亚比米勒。","notes":[]},{"n":26,"t":"亚比米勒说：“我不知道谁做了这事，你也没有告诉我，我到今日才听到。”","notes":[]},{"n":27,"t":"亚伯拉罕把羊和牛给了亚比米勒，二人就彼此立约。","notes":[]},{"n":28,"t":"亚伯拉罕把七只小母羊另放在一处。","notes":[]},{"n":29,"t":"亚比米勒对亚伯拉罕说：“你把这七只小母羊另放一处是什么意思呢？”","notes":[]},{"n":30,"t":"他说：“你要从我手里接受这七只小母羊，作我挖了这口井的证据。”","notes":[]},{"n":31,"t":"所以他给那地方起名叫别是巴，因为他们二人在那里起了誓。","notes":["“别是巴”意思是“盟誓的井”。"]},{"n":32,"t":"他们在别是巴立了约，亚比米勒就和他的将军非各起身回非利士人的地去了。","notes":[]},{"n":33,"t":"亚伯拉罕就在别是巴种了一棵柳树，在那里求告耶和华—永恒神的名。","notes":[]},{"n":34,"t":"亚伯拉罕在非利士人的地寄居了许多日子。","notes":[]}]},"22":{"heading":"亚伯拉罕献以撒","verses":[{"n":1,"t":"这些事以后，神考验亚伯拉罕，对他说：“亚伯拉罕！”他说：“我在这里。”","notes":[]},{"n":2,"t":"神说：“你要带你的儿子，就是你所爱的独子以撒，往摩利亚地去，在我指示你的一座山上，把他献为燔祭。”","notes":[]},{"n":3,"t":"亚伯拉罕清早起来，预备了驴，带着跟他一起的两个仆人和他儿子以撒，劈好了燔祭的柴，就起身往神指示他的地方去了。","notes":[]},{"n":4,"t":"到了第三日，亚伯拉罕举目遥望那地方。","notes":[]},{"n":5,"t":"亚伯拉罕对他的仆人说：“你们和驴留在这里，我和孩子要去那里敬拜，然后回到你们这里来。”","notes":[]},{"n":6,"t":"亚伯拉罕把燔祭的柴放在他儿子以撒身上，自己手里拿着火与刀；于是二人同行。","notes":[]},{"n":7,"t":"以撒对他父亲亚伯拉罕说：“我父啊！”亚伯拉罕说：“我儿，我在这里。”以撒说：“看哪，火与柴都有了，但燔祭的羔羊在哪里呢？”","notes":[]},{"n":8,"t":"亚伯拉罕说：“我儿，神必自己预备燔祭的羔羊。”于是二人同行。","notes":[]},{"n":9,"t":"他们到了神指示他的地方，亚伯拉罕在那里筑坛，把柴摆好，绑了他儿子以撒，放在坛的柴上。","notes":[]},{"n":10,"t":"亚伯拉罕就伸手拿刀，要杀他的儿子。","notes":[]},{"n":11,"t":"耶和华的使者从天上呼唤他说：“亚伯拉罕！亚伯拉罕！”他说：“我在这里。”","notes":[]},{"n":12,"t":"天使说：“不可在这孩子身上下手！一点也不可伤害他！现在我知道你是敬畏神的人了，因为你没有把你的儿子，就是你的独子，留下不给我。”","notes":[]},{"n":13,"t":"亚伯拉罕举目观看，看哪，一只公绵羊两角缠在灌木丛中。亚伯拉罕就去牵了那只公绵羊，献为燔祭，代替他的儿子。","notes":[]},{"n":14,"t":"亚伯拉罕给那地方起名叫“耶和华以勒” 。直到今日人还说：“在耶和华的山上必有预备。”","notes":["“耶和华以勒”意思是“耶和华必预备”。"]},{"n":15,"t":"耶和华的使者第二次从天上呼唤亚伯拉罕，","notes":[]},{"n":16,"t":"说：“耶和华说：‘你既行了这事，没有留下你的儿子，就是你的独子，我指着自己起誓：","notes":[]},{"n":17,"t":"我必多多赐福给你，我必使你的后裔大大增多，如同天上的星、海边的沙。你的后裔必得仇敌的城门，","notes":[]},{"n":18,"t":"并且地上的万国都必因你的后裔得福，因为你听从了我的话。’”","notes":[]},{"n":19,"t":"于是亚伯拉罕回到他仆人那里。他们一同起身，往别是巴去，亚伯拉罕就住在别是巴。","notes":[]},{"n":20,"t":"这些事以后，有人告诉亚伯拉罕说：“看哪，密迦也为你兄弟拿鹤生了几个儿子：","notes":[],"heads":["拿鹤的后代"]},{"n":21,"t":"长子乌斯、他的兄弟布斯、亚兰的父亲基摩利、","notes":[]},{"n":22,"t":"基薛、哈琐、必达、益拉和彼土利。”","notes":[]},{"n":23,"t":"彼土利生利百加。这八个人都是密迦为亚伯拉罕的兄弟拿鹤生的。","notes":[]},{"n":24,"t":"拿鹤的妾名叫流玛，她也生了提八、迦含、他辖和玛迦。","notes":[]}]},"23":{"heading":"亚伯拉罕买坟地葬撒拉","verses":[{"n":1,"t":"撒拉享寿一百二十七岁，这是撒拉一生的岁数。","notes":["七十士译本没有“这是...岁数”。"]},{"n":2,"t":"撒拉死在迦南地的基列．亚巴，就是希伯仑。亚伯拉罕来哀悼撒拉，为她哭泣。","notes":[]},{"n":3,"t":"然后，亚伯拉罕起来，离开死人面前，对赫人说：","notes":[]},{"n":4,"t":"“我在你们中间是外人，是寄居的。请给我你们那里的一块坟地，我好埋葬我的亡妻，使她不在我的面前。”","notes":[]},{"n":5,"t":"赫人回答亚伯拉罕说：","notes":[]},{"n":6,"t":"“我主请听。你在我们中间是一位尊贵的王子，只管在我们最好的坟地里埋葬你的死人；我们没有一人会拒绝你在他的坟地里埋葬你的死人。”","notes":[]},{"n":7,"t":"于是，亚伯拉罕起来，向当地的百姓赫人下拜，","notes":[]},{"n":8,"t":"对他们说：“你们若愿意让我埋葬我的亡妻，使她不在我面前，就请听我，为我求琐辖的儿子以弗仑，","notes":[]},{"n":9,"t":"把他田地尽头的麦比拉洞卖给我。他可以按照足价卖给我，作为我在你们中间的坟地。”","notes":[]},{"n":10,"t":"那时，以弗仑正坐在赫人中间。赫人以弗仑就回答亚伯拉罕，说给所有出入城门的赫人听：","notes":[]},{"n":11,"t":"“不，我主请听。我要把这块田送给你，连田间的洞也送给你，在我同族的人眼前都给你，让你埋葬你的死人。”","notes":[]},{"n":12,"t":"亚伯拉罕就在当地的百姓面前下拜，","notes":[]},{"n":13,"t":"对以弗仑说，也给当地百姓听：“你若应允，请你听我。我要把田的价钱给你，请你收下，我就在那里埋葬我的死人。”","notes":[]},{"n":14,"t":"以弗仑回答亚伯拉罕说：","notes":[]},{"n":15,"t":"“我主请听。四百舍客勒银子的地，在你我中间算什么呢？只管埋葬你的死人吧！”","notes":[]},{"n":16,"t":"亚伯拉罕听从了以弗仑。亚伯拉罕就照着他说给赫人听的，把买卖通用的银子，秤了四百舍客勒银子给以弗仑。","notes":[]},{"n":17,"t":"于是，以弗仑把那块位于幔利对面的麦比拉田，和其中的洞，以及田间周围的树木都成交了，","notes":[]},{"n":18,"t":"在所有出入城门的赫人眼前，卖给亚伯拉罕作为他的产业。","notes":[]},{"n":19,"t":"后来，亚伯拉罕把他妻子撒拉安葬在迦南地幔利对面的麦比拉田间的洞里，幔利就是希伯仑。","notes":[]},{"n":20,"t":"从此，那块田和田间的洞就从赫人移交给亚伯拉罕作坟地的产业。","notes":[]}]},"24":{"heading":"以撒娶妻","verses":[{"n":1,"t":"亚伯拉罕年纪老迈，耶和华在一切事上都赐福给他。","notes":[]},{"n":2,"t":"亚伯拉罕对他家中管理他一切产业最老的仆人说：“把你的手放在我大腿底下。","notes":[]},{"n":3,"t":"我要叫你指着耶和华—天和地的神起誓，不要为我儿子娶我所居住的迦南地的女子为妻。","notes":[]},{"n":4,"t":"你要往我的本地本族去，为我的儿子以撒娶妻。”","notes":[]},{"n":5,"t":"仆人对他说：“如果那女子不肯跟我来到这地，我必须把你的儿子带回到你出来的地方吗？”","notes":[]},{"n":6,"t":"亚伯拉罕对他说：“你要谨慎，不可带我儿子回那里去。","notes":[]},{"n":7,"t":"耶和华—天上的神曾带领我离开父家和本族的地，对我说话，向我起誓说：‘我要将这地赐给你的后裔。’他要差遣使者在你面前，你就可以从那里为我儿子娶妻。","notes":[]},{"n":8,"t":"倘若那女子不肯跟你来，我叫你起的誓就与你无关了，只是你不可带我的儿子回到那里去。”","notes":[]},{"n":9,"t":"仆人就把手放在他主人亚伯拉罕的大腿底下，为这事向他起誓。","notes":[]},{"n":10,"t":"那仆人从他主人的骆驼中取了十匹骆驼，他手中也带着他主人各样的贵重物品离开，起身往美索不达米亚去，到了拿鹤的城。","notes":["七十士译本没有“离开”。"]},{"n":11,"t":"傍晚时，众女子出来打水，他就让骆驼跪在城外的水井旁。","notes":[]},{"n":12,"t":"他说：“耶和华—我主人亚伯拉罕的神啊，求你施恩给我的主人亚伯拉罕，让我今日就遇见吧！","notes":[]},{"n":13,"t":"看哪，我站在井旁，城内居民的女子们正出来打水。","notes":[]},{"n":14,"t":"我向哪一个少女说：‘请你放下水瓶来，给我水喝’，她若说：‘请喝！我也给你的骆驼喝’，愿她作你所选定给你仆人以撒的妻。这样，我就知道你施恩给我的主人了。”","notes":[]},{"n":15,"t":"话还没说完，看哪，利百加肩头上扛着水瓶出来。利百加是彼土利所生的；彼土利是亚伯拉罕的兄弟拿鹤妻子密迦的儿子。","notes":[]},{"n":16,"t":"那少女容貌极其美丽，是未曾与人亲近的童女。她下到井旁，打满了瓶子的水，就上来。","notes":[]},{"n":17,"t":"仆人跑上前去迎着她，说：“请你让我喝你瓶子里的一点水。”","notes":[]},{"n":18,"t":"少女说：“我主请喝！”就急忙拿下瓶子托在手上，给他喝水。","notes":[]},{"n":19,"t":"那少女给他喝足了，又说：“我也为你的骆驼打水，直到骆驼喝足了。”","notes":[]},{"n":20,"t":"她就急忙把瓶子里的水倒在槽里，又跑到井旁打水，为所有的骆驼打了水。","notes":[]},{"n":21,"t":"那人定睛看着少女，一句话也不说，要知道耶和华是否使他的道路亨通。","notes":[]},{"n":22,"t":"骆驼喝足了，那人就拿出一个比加重的金环，一对十舍客勒重的金手镯，","notes":["“比加”：重量单位；参“度量衡表”。"]},{"n":23,"t":"说：“请告诉我，你是谁的女儿？你父亲家里有没有地方可以让我们过夜？”","notes":[]},{"n":24,"t":"少女说：“我是密迦为拿鹤生的儿子彼土利的女儿。”","notes":[]},{"n":25,"t":"又说：“我们家里有充足的干草和饲料，也有住宿的地方。”","notes":[]},{"n":26,"t":"那人就低头向耶和华敬拜，","notes":[]},{"n":27,"t":"说：“耶和华—我主人亚伯拉罕的神是应当称颂的，因他不断以慈爱信实待我主人。至于我，耶和华一路引领我，直到我主人的兄弟家里。”","notes":[]},{"n":28,"t":"那少女跑去，把这些话告诉她母亲家里的人。","notes":[]},{"n":29,"t":"利百加有一个哥哥，名叫拉班，拉班就跑到外面井旁那人那里。","notes":[]},{"n":30,"t":"当他看见金环和戴在他妹妹手上的金镯，又听见他妹妹利百加说的话：“那人如此对我说”，他就来到那人面前，看哪，他还站在井旁的骆驼旁边，","notes":[]},{"n":31,"t":"就对他说：“你这蒙耶和华赐福的人，请进来吧！为什么站在外面？我已经收拾了房屋，也为骆驼预备了地方。”","notes":[]},{"n":32,"t":"那人就进了拉班的家。拉班卸了骆驼，用饲料喂它们，拿水给那人和随从他的人洗脚，","notes":[]},{"n":33,"t":"把食物摆在他面前，请他吃。他却说：“我不吃，等我把我的事情说完了再吃。”拉班说：“请说。”","notes":[]},{"n":34,"t":"他说：“我是亚伯拉罕的仆人。","notes":[]},{"n":35,"t":"耶和华大大地赐福给我主人，使他发达，赐给他羊群、牛群、金银、奴仆、婢女、骆驼和驴。","notes":[]},{"n":36,"t":"我主人的妻子撒拉年老的时候为我主人生了一个儿子；我主人把他一切所有的都给了他。","notes":[]},{"n":37,"t":"我主人叫我起誓说：‘不要为我儿子娶我所居住的迦南地的女子为妻。","notes":[]},{"n":38,"t":"你要往我父家、我本族那里去，为我的儿子娶妻。’","notes":[]},{"n":39,"t":"我对我主人说：‘恐怕那女子不肯跟我来。’","notes":[]},{"n":40,"t":"他就说：‘我所事奉的耶和华必要差遣他的使者与你同去，使你的道路亨通，你就可以在我父家、我本族那里，为我的儿子娶妻。","notes":[]},{"n":41,"t":"只要你到了我本族那里，我叫你起的誓就与你无关。他们若不把女子交给你，我叫你起的誓也与你无关。’","notes":[]},{"n":42,"t":"“我今日到了井旁，就说：‘耶和华—我主人亚伯拉罕的神啊，愿你使我所行的道路亨通。","notes":[]},{"n":43,"t":"看哪，我站在井旁，对哪一个出来打水的女子说：请你让我喝你瓶子里的一点水，","notes":[]},{"n":44,"t":"她若说：你只管喝，我也为你的骆驼打水；愿那女子作耶和华给我主人儿子所选定的妻子。’","notes":[]},{"n":45,"t":"“我心里的话还没有说完，看哪，利百加肩头上扛着水瓶出来，下到井旁打水。我对她说：‘请你给我水喝。’","notes":[]},{"n":46,"t":"她就急忙从肩头上拿下瓶子来，说：‘请喝！我也给你的骆驼喝。’我就喝了；她也给我的骆驼喝了。","notes":[]},{"n":47,"t":"我问她说：‘你是谁的女儿？’她说：‘我是彼土利的女儿，彼土利是密迦和拿鹤生的儿子。’我就把环子戴在她鼻子上，把镯子戴在她双手上。","notes":[]},{"n":48,"t":"然后我低头向耶和华敬拜，称颂耶和华—我主人亚伯拉罕的神，因为他引导我走合适的道路，使我得着我主人兄弟的孙女，给我主人的儿子为妻。","notes":[]},{"n":49,"t":"现在你们若愿以慈爱诚信待我主人，就告诉我；若不然，也告诉我，使我可以或向左，或向右。”","notes":[]},{"n":50,"t":"拉班和彼土利回答说：“这事既然出于耶和华，我们不能向你说好说歹。","notes":[]},{"n":51,"t":"看哪，利百加就在你面前，可以将她带去，遵照耶和华所说的，给你主人的儿子为妻。”","notes":[]},{"n":52,"t":"亚伯拉罕的仆人听见他们这些话，就向耶和华俯伏在地。","notes":[]},{"n":53,"t":"仆人拿出金器、银器和衣服送给利百加，又将贵重的物品送给她哥哥和她母亲。","notes":[]},{"n":54,"t":"然后，仆人和随从的人才吃喝，并且住了一夜。早晨起来，仆人说：“请让我回我主人那里去吧。”","notes":[]},{"n":55,"t":"利百加的哥哥和母亲说：“让她同我们再住几天，也许十天，然后她可以去。”","notes":[]},{"n":56,"t":"仆人对他们说：“耶和华既然使我道路亨通，你们就不要耽误我，请让我走，回我主人那里去吧！”","notes":[]},{"n":57,"t":"他们说：“我们把她叫来问问她。”","notes":["“她”：原文是“她的口”。"]},{"n":58,"t":"他们就叫了利百加来，对她说：“你和这人同去吗？”她说：“我去。”","notes":[]},{"n":59,"t":"于是他们送他们的妹妹利百加和她的奶妈，同亚伯拉罕的仆人，以及随从他的人走了。","notes":[]},{"n":60,"t":"他们就为利百加祝福，对她说：“我们的妹妹啊，愿你作千万人的母亲！愿你的后裔得着仇敌的城门！”","notes":[]},{"n":61,"t":"利百加和她的女仆们起来，骑上骆驼，跟着那人去。仆人就带着利百加走了。","notes":[]},{"n":62,"t":"那时，以撒住在尼革夫。他刚从庇耳．拉海．莱回来。","notes":[]},{"n":63,"t":"傍晚时，以撒出来，到田间默想。他举目一看，看哪，来了一队骆驼。","notes":[]},{"n":64,"t":"利百加举目看见以撒，就急忙下了骆驼，","notes":[]},{"n":65,"t":"对那仆人说：“这从田间走来迎接我们的人是谁？”仆人说：“他是我的主人。”利百加就拿面纱盖住自己。","notes":[]},{"n":66,"t":"仆人把他所做的一切事都告诉以撒。","notes":[]},{"n":67,"t":"以撒就领利百加进了母亲撒拉的帐棚，娶了她为妻，并且爱她。以撒自从母亲离世以后，这才得了安慰。","notes":[]}]},"25":{"heading":"亚伯拉罕的其他后代","verses":[{"n":1,"t":"亚伯拉罕再娶了一个妻子，名叫基土拉。","notes":[]},{"n":2,"t":"她为他生了心兰、约珊、米但、米甸、伊施巴和书亚。","notes":[]},{"n":3,"t":"约珊生了示巴和底但。底但的子孙是亚书利族、利都是族和利乌米族。","notes":[]},{"n":4,"t":"米甸的儿子是以法、以弗、哈诺、亚比大和以勒大。这些都是基土拉的子孙。","notes":[]},{"n":5,"t":"亚伯拉罕把他一切所有的都给了以撒。","notes":[]},{"n":6,"t":"至于亚伯拉罕妾的儿子，亚伯拉罕趁着自己还活着的时候把财物分给他们，打发他们离开他的儿子以撒，往东方去，直到东方之地。","notes":[]},{"n":7,"t":"这是亚伯拉罕一生的年日，他活了一百七十五年。","notes":[],"heads":["亚伯拉罕的死和安葬"]},{"n":8,"t":"亚伯拉罕寿高年迈，安享天年，息劳而终，归到他祖先 那里。","notes":["“他祖先”：原文是“他百姓”；下同。"]},{"n":9,"t":"他两个儿子以撒、以实玛利把他安葬在麦比拉洞里。这洞在幔利的对面、赫人琐辖的儿子以弗仑的田中，","notes":[]},{"n":10,"t":"就是亚伯拉罕向赫人买的那块田。亚伯拉罕和他妻子撒拉都葬在那里。","notes":[]},{"n":11,"t":"亚伯拉罕死了以后，神赐福给他的儿子以撒。以撒住在庇耳．拉海．莱附近。","notes":[]},{"n":12,"t":"这是撒拉的婢女、埃及人夏甲为亚伯拉罕生的儿子以实玛利的后代。","notes":[],"heads":["以实玛利的后代"]},{"n":13,"t":"以实玛利儿子们的名字，按着他们后代的名字如下：以实玛利的长子尼拜约，又有基达、亚德别、米比衫、","notes":[]},{"n":14,"t":"米施玛、度玛、玛撒、","notes":[]},{"n":15,"t":"哈大、提玛、伊突、拿非施和基底玛。","notes":[]},{"n":16,"t":"这些都是以实玛利的儿子们。他们的村庄和营寨按着他们命名；他们作了十二族的族长。","notes":[]},{"n":17,"t":"以实玛利一生的岁数是一百三十七岁，断气而死，归到他祖先那里。","notes":[]},{"n":18,"t":"他的子孙住在哈腓拉，直到埃及东边的书珥，向着亚述，在他众弟兄的对面安顿下来。","notes":["“安顿下来”：原文是“落下”。"]},{"n":19,"t":"这是亚伯拉罕的儿子以撒的后代。亚伯拉罕生以撒。","notes":[],"heads":["以扫和雅各的出生"]},{"n":20,"t":"以撒四十岁时娶利百加为妻。利百加是巴旦．亚兰地的亚兰人彼土利的女儿，是亚兰人拉班的妹妹。","notes":[]},{"n":21,"t":"以撒因他妻子不生育，就为她祈求耶和华。耶和华应允他的祈求，他的妻子利百加就怀了孕。","notes":[]},{"n":22,"t":"胎儿们在她腹中彼此相争，她就说：“若是如此，我为什么会这样呢？”她就去求问耶和华。","notes":["“我为什么会这样呢”：叙利亚译本是“我为什么要活着呢”。"]},{"n":23,"t":"耶和华对她说：两国在你腹中；两族要从你身上分立。这族必强于那族；将来大的要服侍小的。","notes":[]},{"n":24,"t":"到了生产的日期，看哪，腹中是对双胞胎。","notes":[]},{"n":25,"t":"先出生的身体带红，浑身有毛，好像皮衣；他们就给他起名叫以扫。","notes":["“以扫”与“多毛”的希伯来话发音略为相近。"]},{"n":26,"t":"随后，以扫的弟弟也出生，他的手抓住以扫的脚跟，因此给他起名叫雅各。两个儿子出生时，以撒六十岁。","notes":["“雅各”与“脚跟”的希伯来话发音相近。"]},{"n":27,"t":"两个孩子渐渐长大，以扫善于打猎，常在田野；雅各为人安静，常住在帐棚里。","notes":[],"heads":["以扫出卖长子的名分"]},{"n":28,"t":"以撒爱以扫，因为常吃他的野味；利百加却爱雅各。","notes":[]},{"n":29,"t":"有一天，雅各熬了汤，以扫从田野回来，疲惫不堪。","notes":[]},{"n":30,"t":"以扫对雅各说：“我累死了，请你让我吃这红的，这红的汤吧！”因此以扫又叫以东。","notes":["“以东”意思是“红”。"]},{"n":31,"t":"雅各说：“你今日把长子的名分卖给我吧。”","notes":[]},{"n":32,"t":"以扫说：“看哪，我快要死了，这长子的名分对我有什么用呢？”","notes":[]},{"n":33,"t":"雅各说：“你今日对我起誓吧。”以扫就向他起誓，把长子的名分卖给了雅各。","notes":[]},{"n":34,"t":"于是雅各把饼和豆汤给了以扫，以扫吃喝以后，起来走了。这样，以扫轻看他长子的名分。","notes":[]}]},"26":{"heading":"以撒住在基拉耳","verses":[{"n":1,"t":"那地有了饥荒，不是亚伯拉罕的时候曾有过的那次饥荒，以撒就到基拉耳，非利士人的王亚比米勒那里去。","notes":[]},{"n":2,"t":"耶和华向以撒显现，说：“你不要下埃及去，要住在我所指示你的地。","notes":[]},{"n":3,"t":"你要寄居在这地，我必与你同在，赐福给你，因为我要将这一切的地都赐给你和你的后裔。我必坚定我向你父亲亚伯拉罕所起的誓。","notes":[]},{"n":4,"t":"我要使你的后裔增多，好像天上的星，又要将这一切的地赐给你的后裔，并且地上的万国都必因你的后裔得福，","notes":[]},{"n":5,"t":"因为亚伯拉罕听从我的话，遵守我的吩咐、诫令、律例和教导。”","notes":[]},{"n":6,"t":"于是，以撒住在基拉耳。","notes":[]},{"n":7,"t":"那地方的人问起他的妻子，他就说：“她是我的妹妹。”原来他害怕说“我的妻子”。他想：“或许这地方的人会因利百加杀我，因为她容貌美丽。”","notes":[]},{"n":8,"t":"他在那里住了一段很长的日子。有一天，非利士人的王亚比米勒从窗户往外观看，看哪，以撒在抚爱他的妻子利百加。","notes":[]},{"n":9,"t":"亚比米勒召以撒来，说：“看哪，她实在是你的妻子，你怎么说‘她是我的妹妹’呢？”以撒对他说：“因为我想，恐怕我会因她而死。”","notes":[]},{"n":10,"t":"亚比米勒说：“你向我们做的是什么事呢？百姓中有一个人几乎要和你的妻子同寝，你就把我们陷在罪中了。”","notes":[]},{"n":11,"t":"于是亚比米勒命令众百姓说：“凡侵犯这个人，或他妻子的，必要把他处死。”","notes":[]},{"n":12,"t":"以撒在那地耕种，那一年有百倍的收成。耶和华赐福给他，","notes":[]},{"n":13,"t":"他就发达，日渐昌盛，成了大富翁。","notes":[]},{"n":14,"t":"他有羊群牛群，又有许多仆人，非利士人就嫉妒他。","notes":[]},{"n":15,"t":"他父亲亚伯拉罕在世的时候，他父亲的仆人所挖的井，非利士人全都塞住，填满了土。","notes":[]},{"n":16,"t":"亚比米勒对以撒说：“你离开我们去吧，因为你比我们强盛得多。”","notes":[]},{"n":17,"t":"以撒就离开那里，在基拉耳谷支搭帐棚，住在那里。","notes":[]},{"n":18,"t":"他父亲亚伯拉罕在世的时候所挖的水井，在亚伯拉罕死后，都被非利士人塞住了，以撒就重新把井挖出来，仍照他父亲所取的名为它们命名。","notes":[]},{"n":19,"t":"以撒的仆人在谷中挖井，就在那里得了一口活水井。","notes":[]},{"n":20,"t":"基拉耳的牧人与以撒的牧人相争，说：“这水是我们的。”以撒就给那井起名叫埃色，因为他们和他相争。","notes":["“埃色”意思是“相争”。"]},{"n":21,"t":"以撒的仆人又挖了一口井，他们又为这井相争，以撒就给这井起名叫西提拿。","notes":["“西提拿”意思是“为敌”。"]},{"n":22,"t":"以撒离开那里，又挖了一口井，他们不再为这井相争了，他就给那井起名叫利河伯。他说：“耶和华现在给我们宽阔之地，我们必在这地兴旺。”","notes":["“利河伯”意思是“宽阔”。"]},{"n":23,"t":"以撒从那里上别是巴去。","notes":[]},{"n":24,"t":"当夜耶和华向他显现，说：“我是你父亲亚伯拉罕的神。不要惧怕，因为我与你同在，要赐福给你，也要为我仆人亚伯拉罕的缘故，使你的后裔增多。”","notes":[]},{"n":25,"t":"以撒就在那里筑了一座坛，求告耶和华的名，并且在那里支搭帐棚；他的仆人就在那里挖了一口井。","notes":[]},{"n":26,"t":"亚比米勒同他的顾问亚户撒和他军队的元帅非各，从基拉耳来到以撒那里。","notes":[],"heads":["以撒与亚比米勒立约"]},{"n":27,"t":"以撒对他们说：“你们既然恨我，赶我离开你们，为什么又到我这里来呢？”","notes":[]},{"n":28,"t":"他们说：“我们明明看见耶和华与你同在；因此就说，让我们双方彼此起誓，我们跟你立约，","notes":[]},{"n":29,"t":"使你不加害我们，正如我们未曾侵犯你，素来善待你，并且送你平平安安地走。你是蒙耶和华赐福的！”","notes":[]},{"n":30,"t":"以撒为他们摆设宴席，他们就一起吃喝。","notes":[]},{"n":31,"t":"他们清早起来，彼此起誓。以撒送他们走，他们就平平安安地离开他去了。","notes":[]},{"n":32,"t":"那一天，以撒的仆人来，把挖井的消息告诉他，说：“我们得到水了。”","notes":[]},{"n":33,"t":"他就给那井起名叫示巴，因此那城名叫别是巴，直到今日。","notes":["“示巴”与“起誓”的希伯来话发音相近。","“别是巴”意思是“起誓的井”或“七井”。"]},{"n":34,"t":"以扫四十岁的时候娶了赫人比利的女儿犹滴，和赫人以伦的女儿巴实抹为妻。","notes":[],"heads":["以扫的外族妻子"]},{"n":35,"t":"她们使以撒和利百加心里愁烦。","notes":[]}]},"27":{"heading":"以撒祝福雅各","verses":[{"n":1,"t":"以撒年老，眼睛昏花，不能看见，就叫他大儿子以扫来，对他说：“我儿。”以扫对他说：“我在这里。”","notes":[]},{"n":2,"t":"他说：“看哪，我老了，不知道哪一天死。","notes":[]},{"n":3,"t":"现在拿你打猎的工具，就是箭囊和弓，到田野去为我打猎，","notes":[]},{"n":4,"t":"照我所爱的做成美味，拿来给我吃，好让我在未死之前为你祝福。”","notes":[]},{"n":5,"t":"以撒对他儿子以扫说话的时候，利百加听见了。以扫往田野去打猎，要把猎物带回来。","notes":[]},{"n":6,"t":"利百加就对她儿子雅各说：“看哪，我听见你父亲对你哥哥以扫说：","notes":[]},{"n":7,"t":"‘你去把猎物带回来，做成美味给我吃，让我在未死之前，在耶和华面前为你祝福。’","notes":[]},{"n":8,"t":"现在，我儿，你要听我的话，照我所吩咐你的，","notes":[]},{"n":9,"t":"到羊群里去，从那里牵两只肥美的小山羊来给我，我就照你父亲所爱的，把它们做成美味给他。","notes":[]},{"n":10,"t":"然后，你拿到你父亲那里给他吃，好让他在未死之前为你祝福。”","notes":[]},{"n":11,"t":"雅各对他母亲利百加说：“看哪，我哥哥以扫浑身都有毛，我身上却是光滑的；","notes":[]},{"n":12,"t":"倘若父亲摸着我，我在他眼中就是骗子了。这样，我就自招诅咒，而不是祝福。”","notes":[]},{"n":13,"t":"他母亲对他说：“我儿，你所受的诅咒临到我身上吧！你只管听我的话，去牵小山羊来给我。”","notes":[]},{"n":14,"t":"他就去牵来，交给他母亲。他母亲就照他父亲所爱的，做成美味。","notes":[]},{"n":15,"t":"利百加把大儿子以扫在家里最好的衣服给她小儿子雅各穿，","notes":[]},{"n":16,"t":"又用小山羊的皮包在雅各的手上和颈项光滑的地方，","notes":[]},{"n":17,"t":"就把所做的美味和饼交在她儿子雅各的手里。","notes":[]},{"n":18,"t":"雅各来到他父亲那里，说：“我的父亲！”他说：“我在这里。我儿，你是谁？”","notes":[]},{"n":19,"t":"雅各对他父亲说：“我是你的长子以扫。我已照你吩咐我的做了。请起来坐着，吃我的野味，你好为我祝福。”","notes":[]},{"n":20,"t":"以撒对他儿子说：“我儿，你怎么这样快就找到了呢？”他说：“因为这是耶和华—你的神使我遇见的。”","notes":[]},{"n":21,"t":"以撒对雅各说：“我儿，靠近一点，让我摸摸你，你真的是我的儿子以扫吗？”","notes":[]},{"n":22,"t":"雅各就靠近他父亲以撒。以撒摸着他，说：“声音是雅各的声音，手却是以扫的手。”","notes":[]},{"n":23,"t":"以撒认不出他来，因为他手上有毛，像他哥哥以扫的手一样。于是，以撒就为他祝福。","notes":[]},{"n":24,"t":"以撒说：“你真的是我儿子以扫吗？”他说：“我是。”","notes":[]},{"n":25,"t":"以撒说：“拿给我，让我吃我儿子的野味，我好为你祝福。”雅各拿给他，他就吃了，又拿酒给他，他也喝了。","notes":[]},{"n":26,"t":"他父亲以撒对他说：“我儿，靠近一点来亲我！”","notes":[]},{"n":27,"t":"他就近前亲吻父亲。他父亲一闻他衣服上的香气，就为他祝福，说：“看，我儿的香气好像耶和华赐福之田地的香气。","notes":[]},{"n":28,"t":"愿神赐你天上的甘露，地上的肥土，和丰富的五谷新酒。","notes":[]},{"n":29,"t":"愿万民事奉你，万族向你下拜。愿你作你弟兄的主，你母亲的儿子向你下拜。诅咒你的，愿他受诅咒；祝福你的，愿他蒙祝福。”","notes":[]},{"n":30,"t":"以撒为雅各祝福完毕，雅各才从他父亲那里出来，他哥哥以扫正打猎回来。","notes":[],"heads":["以扫求以撒祝福"]},{"n":31,"t":"以扫也做了美味，拿来给他父亲，对他父亲说：“父亲，请起来，吃你儿子的野味，你好为我祝福。”","notes":[]},{"n":32,"t":"他父亲以撒对他说：“你是谁？”他说：“我是你的儿子，你的长子以扫。”","notes":[]},{"n":33,"t":"以撒就大大战兢，说：“那么，是谁打了猎物拿来给我呢？你未来之前我已经吃了，也为他祝福了，他将来就必蒙福。”","notes":[]},{"n":34,"t":"以扫听了他父亲的话，就大声痛哭，对他父亲说：“我父啊，求你也为我祝福！”","notes":[]},{"n":35,"t":"以撒说：“你弟弟已经用诡计来把你的福分夺去了。”","notes":[]},{"n":36,"t":"以扫说：“他名叫雅各，岂不是这样吗？他欺骗了我两次：他先前夺了我长子的名分，看哪，他现在又夺了我的福分。”以扫又说：“你没有留下给我的祝福吗？”","notes":["“雅各”与“欺骗”的希伯来话发音相近。"]},{"n":37,"t":"以撒回答以扫说：“看哪，我已立他作你的主，使他的弟兄都给他作仆人，并赐他五谷新酒可以养生。我儿，那么，现在我还能为你做什么呢？”","notes":[]},{"n":38,"t":"以扫对他父亲说：“我父啊，你只有一个祝福吗？我父啊，求你也为我祝福！”以扫就放声而哭。","notes":[]},{"n":39,"t":"他父亲以撒回答说：“看哪，你所住的地方必缺乏肥沃的土地，缺乏天上的甘露。","notes":["“你所住...甘露”或译“地上的肥土必为你所住；天上的甘露必为你所得”。"]},{"n":40,"t":"你必倚靠刀剑度日，又必服侍你的兄弟；到你强盛的时候，必从你颈项上挣开他的轭。","notes":[]},{"n":41,"t":"以扫因他父亲给雅各的祝福，就怨恨雅各，心里说：“为我父亲居丧的时候近了，到那时候，我要杀我的弟弟雅各。”","notes":[]},{"n":42,"t":"有人把利百加大儿子以扫的话告诉利百加，她就派人去，叫了她小儿子雅各来，对他说：“看哪，你哥哥以扫想要杀你来泄恨。","notes":[]},{"n":43,"t":"现在，我儿，听我的话，起来，逃往哈兰，到我哥哥拉班那里去，","notes":[]},{"n":44,"t":"同他住一段日子，直等到你哥哥的怒气消了。","notes":[]},{"n":45,"t":"等到你哥哥向你消了怒气，忘了你向他所做的事，我就派人去，把你从那里带回来。我何必在一天之内丧失你们二人呢？”","notes":[]},{"n":46,"t":"利百加对以撒说：“我因这赫人的女子活得不耐烦了；倘若雅各也从本地女子中娶像这样的赫人女子为妻，我为什么要活着呢？”","notes":[],"heads":["以撒差雅各到拉班的家"]}]},"28":{"heading":"以扫另娶一妻","verses":[{"n":1,"t":"以撒叫了雅各来，为他祝福，并吩咐他说：“你不要娶迦南的女子为妻。","notes":[]},{"n":2,"t":"你起身往巴旦．亚兰去，到你外祖父彼土利的家，从你舅父拉班的女儿中娶一位作你的妻子。","notes":[]},{"n":3,"t":"愿全能的神赐福给你，使你生养众多，成为许多民族，","notes":[]},{"n":4,"t":"将应许亚伯拉罕的福赐给你和你的后裔，使你承受你所寄居的地为业，就是神赐给亚伯拉罕的地。”","notes":[]},{"n":5,"t":"以撒送雅各走了，雅各就往巴旦．亚兰去，到亚兰人彼土利的儿子拉班那里，拉班是利百加的哥哥，利百加是雅各和以扫的母亲。","notes":[]},{"n":6,"t":"以扫见以撒已经为雅各祝福，而且送他往巴旦．亚兰去，在那里娶妻，并且见以撒祝福雅各的时候吩咐他说：“不要娶迦南的女子为妻”，","notes":[]},{"n":7,"t":"又见雅各听从父母的话往巴旦．亚兰去了，","notes":[]},{"n":8,"t":"以扫就看出他父亲以撒看迦南女子不顺眼。","notes":[]},{"n":9,"t":"于是他往以实玛利那里去，在两个妻子之外， 又娶了玛哈拉为妻，她是亚伯拉罕儿子以实玛利的女儿，是尼拜约的妹妹。","notes":[]},{"n":10,"t":"雅各离开别是巴，往哈兰去。","notes":[],"heads":["雅各在伯特利做的梦"]},{"n":11,"t":"到了一个地方，因为已经日落，就在那里过夜。他拾起那地方的一块石头枕在头下，就躺在那地方。","notes":[]},{"n":12,"t":"他做梦，看哪，一个梯子立在地上，梯子的顶端直伸到天；看哪，神的使者在梯子上，上去下来。","notes":[]},{"n":13,"t":"看哪，耶和华站在梯子上面 ，说：“我是耶和华—你祖父亚伯拉罕的神，以撒的神。你现在躺卧之地，我要将它赐给你和你的后裔。","notes":["“站在梯子上面”或译“站在他旁边”。"]},{"n":14,"t":"你的后裔必像地上的尘沙，必向东西南北开展；地上万族必因你和你的后裔得福。","notes":[]},{"n":15,"t":"看哪，我必与你同在，无论你往哪里去，我必保佑你，领你归回这地。我总不离弃你，直到我实现了对你所说的话。”","notes":[]},{"n":16,"t":"雅各睡醒了，说：“耶和华真的在这里，我竟不知道！”","notes":[]},{"n":17,"t":"他就惧怕，说：“这地方何等可畏！这不是别的，是神的殿，是天的门。”","notes":[]},{"n":18,"t":"雅各清早起来，拿起枕在头下的石头，立作柱子，浇油在上面。","notes":[]},{"n":19,"t":"他给那地方起名叫伯特利 ；那地方原先名叫路斯。","notes":["“伯特利”意思是“神的殿”。"]},{"n":20,"t":"雅各许愿说：“神若与我同在，在我所行的路上保佑我，给我食物吃，衣服穿，","notes":[]},{"n":21,"t":"使我平平安安回到我父亲的家，我就必以耶和华为我的神。","notes":[]},{"n":22,"t":"我所立为柱子的这块石头必作神的殿；凡你所赐给我的，我必将十分之一献给你。”","notes":[]}]},"29":{"heading":"雅各到拉班的家","verses":[{"n":1,"t":"雅各起行，到了东方人之地。","notes":[]},{"n":2,"t":"他观看，看哪，田间有一口井，看哪，有三群羊卧在井旁；因为人都取那井里的水给羊喝。井口上的那块石头很大。","notes":[]},{"n":3,"t":"羊群都在那里聚集，人就把石头移开井口，取水给羊喝，然后又把石头放回井口原处。","notes":[]},{"n":4,"t":"雅各对他们说：“弟兄们，你们从哪里来？”他们说：“我们是从哈兰来的。”","notes":[]},{"n":5,"t":"他对他们说：“你们认识拿鹤的孙子拉班吗？”他们说：“我们认识。”","notes":[]},{"n":6,"t":"雅各对他们说：“他平安吗？”他们说：“平安。看哪，他女儿拉结和羊一起来了。”","notes":[]},{"n":7,"t":"雅各说：“看哪，日正当中，不是牲畜聚集的时候。你们取水给羊喝，再去牧放吧！”","notes":[]},{"n":8,"t":"他们说：“我们不能这样，必须等所有的羊群聚集，人把石头移开井口，我们才可以取水给羊喝。”","notes":[]},{"n":9,"t":"雅各正和他们说话的时候，拉结和她父亲的羊来了，因为她是牧羊的。","notes":[]},{"n":10,"t":"雅各看见他舅父拉班的女儿拉结和舅父拉班的羊群，就上前把石头移开井口，取水给舅父拉班的羊喝。","notes":[]},{"n":11,"t":"雅各亲了拉结，就放声大哭。","notes":[]},{"n":12,"t":"雅各告诉拉结，自己是她父亲的亲戚，是利百加的儿子。拉结就跑去告诉她父亲。","notes":["“亲戚”：原文是“兄弟”；下同。"]},{"n":13,"t":"拉班听见外甥雅各的消息，就跑去迎接他，抱着他，亲他，带他到自己的家。雅各把这一切的事告诉拉班。","notes":[]},{"n":14,"t":"拉班对他说：“你实在是我的骨肉。”雅各就和他同住了一个月。","notes":[]},{"n":15,"t":"拉班对雅各说：“虽然你是我的亲戚，怎么可以让你白白服事我呢？告诉我，你要什么作工资呢？”","notes":[],"heads":["雅各为拉结和利亚服事拉班"]},{"n":16,"t":"拉班有两个女儿，大的名叫利亚，小的名叫拉结。","notes":[]},{"n":17,"t":"利亚的双眼无神，拉结却长得美貌秀丽。","notes":[]},{"n":18,"t":"雅各爱拉结，就说：“我愿为你的小女儿拉结服事你七年。”","notes":[]},{"n":19,"t":"拉班说：“我把她给你，胜过给别人，你与我同住吧！”","notes":[]},{"n":20,"t":"雅各就为拉结服事了七年；他因为爱拉结，就看这七年如同几天。","notes":[]},{"n":21,"t":"雅各对拉班说：“日期已经满了，请把我的妻子给我，我好与她同房。”","notes":[]},{"n":22,"t":"拉班就摆设宴席，请了当地所有的人。","notes":[]},{"n":23,"t":"到了晚上，拉班带女儿利亚来送给雅各，雅各就与她同房。","notes":[]},{"n":24,"t":"拉班也把自己的婢女悉帕给女儿利亚作婢女。","notes":[]},{"n":25,"t":"到了早晨，看哪，她是利亚，雅各对拉班说：“你向我做的是什么事呢？我服事你，不是为拉结吗？你为什么欺骗我呢？”","notes":[]},{"n":26,"t":"拉班说：“大女儿还没有给人就先把小女儿给人，我们这地方没有这样的规矩。","notes":[]},{"n":27,"t":"你先为这个满了七日，我们就把那个也给你，不过你要另外再服事我七年。”","notes":[]},{"n":28,"t":"雅各就这样做了。满了利亚的七日，拉班就把女儿拉结给雅各为妻。","notes":[]},{"n":29,"t":"拉班又把自己的婢女辟拉给女儿拉结作婢女。","notes":[]},{"n":30,"t":"雅各也与拉结同房，并且爱拉结胜过爱利亚，于是他又服事了拉班七年。","notes":[]},{"n":31,"t":"耶和华见利亚失宠，就使她生育，拉结却不生育。","notes":["“失宠”：原文是“被恨”；下同。"],"heads":["雅各的儿女"]},{"n":32,"t":"利亚怀孕生子，给他起名叫吕便，因为她说：“耶和华看见我的苦情，如今我的丈夫必爱我。”","notes":["“吕便”意思是“看见儿子”。"]},{"n":33,"t":"她又怀孕生子，给他起名叫西缅，说：“耶和华因为听见我失宠，所以又赐给我这个儿子。”","notes":["“西缅”意思是“听见”。"]},{"n":34,"t":"她又怀孕生子，说：“我给丈夫生了三个儿子，现在，这次他必亲近我了。”因此，雅各给他起名叫利未。","notes":["“利未”意思是“亲近”。"]},{"n":35,"t":"她又怀孕生子，说：“这次我要赞美耶和华。”因此给他起名叫犹大。于是她停了生育。","notes":["“犹大”意思是“赞美”。"]}]},"30":{"heading":"雅各和拉班定工资","verses":[{"n":1,"t":"拉结见自己不给雅各生孩子，就嫉妒她姊姊，对雅各说：“你给我孩子，不然，让我死了吧。”","notes":[]},{"n":2,"t":"雅各对拉结生气，说：“是我代替神使你生不出孩子的吗？”","notes":[]},{"n":3,"t":"拉结说：“看哪，我的使女辟拉在这里，你可以与她同房，使她生子归在我膝下，我也可以藉着她得孩子。”","notes":["“得孩子”：原文是“被建立”。"]},{"n":4,"t":"拉结就把她的婢女辟拉给丈夫为妾，雅各与她同房。","notes":[]},{"n":5,"t":"辟拉怀孕，为雅各生了一个儿子。","notes":[]},{"n":6,"t":"拉结给他起名叫但，说：“神为我伸冤，也听了我的声音，赐给我一个儿子。”","notes":["“但”意思是“伸冤、审判”。"]},{"n":7,"t":"拉结的婢女辟拉又怀孕，为雅各生了第二个儿子。","notes":[]},{"n":8,"t":"拉结给他起名叫拿弗他利，说：“我与我姊姊大大较力，并且得胜了。”","notes":["“拿弗他利”意思是“较力”。"]},{"n":9,"t":"利亚见自己停了生育，就把她的婢女悉帕给雅各为妾。","notes":[]},{"n":10,"t":"利亚的婢女悉帕为雅各生了一个儿子。","notes":[]},{"n":11,"t":"利亚给他起名叫迦得，说：“真是幸运！”","notes":["“迦得”意思是“幸运”。"]},{"n":12,"t":"利亚的婢女悉帕又为雅各生了第二个儿子。","notes":[]},{"n":13,"t":"利亚给他起名叫亚设，说：“我真有福啊，众女子都要称我有福。”","notes":["“亚设”意思是“有福”。"]},{"n":14,"t":"收割麦子的时候，吕便到田里去，找到曼陀罗草，就拿给他的母亲利亚。拉结对利亚说：“请你给我一些你儿子的曼陀罗草吧。”","notes":["“曼陀罗草”或译“爱情花”；下同。"]},{"n":15,"t":"利亚对她说：“你夺走了我的丈夫还是小事吗？你还要夺取我儿子的曼陀罗草吗？”拉结说：“今夜他可以与你同寝，来交换你儿子的曼陀罗草。”","notes":[]},{"n":16,"t":"到了晚上，雅各从田里回来，利亚出来迎接他，说：“你要与我同寝，因为我真的用我儿子的曼陀罗草把你雇下了。”那一夜，雅各就与她同寝。","notes":[]},{"n":17,"t":"神应允了利亚，她就怀孕，为雅各生了第五个儿子。","notes":[]},{"n":18,"t":"利亚给他起名叫以萨迦，说：“神给了我工价，因为我把婢女给了我的丈夫。”","notes":["“以萨迦”意思是“工价”。"]},{"n":19,"t":"利亚又怀孕，为雅各生了第六个儿子。","notes":[]},{"n":20,"t":"利亚给他起名叫西布伦，说：“神赐给我厚礼了；这次，我丈夫必看重我，因为我为他生了六个儿子。”","notes":["“西布伦”意思是“看重、同住”。"]},{"n":21,"t":"后来她又生了一个女儿，给她起名叫底拿。","notes":[]},{"n":22,"t":"神顾念拉结，应允她，使她能生育。","notes":[]},{"n":23,"t":"拉结怀孕生子，说：“神除去了我的羞耻。”","notes":[]},{"n":24,"t":"拉结就给他起名叫约瑟，说：“愿耶和华再增添一个儿子给我。”","notes":["“约瑟”意思是“增添”。"]},{"n":25,"t":"拉结生约瑟之后，雅各对拉班说：“请让我走，回到我的本乡本土去。","notes":[]},{"n":26,"t":"请你把我服事你所得的妻子和孩子给我，让我走吧！我怎样服事你，你都知道。”","notes":[]},{"n":27,"t":"拉班对他说：“愿你看得起我，因我占卜得知，耶和华赐福给我是因你的缘故。”","notes":[]},{"n":28,"t":"又说：“请为我定你的工资，我就给你。”","notes":[]},{"n":29,"t":"雅各对他说：“我怎样服事你，你的牲畜在我这里变得怎样，你都知道。","notes":[]},{"n":30,"t":"我未来以前，你拥有的很少，现在却已大量增加，因为耶和华随着我的脚步赐福给你。现在，我到什么时候才可以成家立业呢？”","notes":[]},{"n":31,"t":"拉班说：“我该给你什么呢？”雅各说：“你什么也不必给我，只要你为我做这件事，我就继续牧放你的羊群。","notes":[]},{"n":32,"t":"今天我要走遍你的羊群，把绵羊中凡有点的、有斑的，和小绵羊中凡是黑色的羊；以及山羊中凡有斑的、有点的，都从那里挑出来，作为我的工资。","notes":[]},{"n":33,"t":"以后你来当面查看我的工资，任何我这里的山羊不是有点有斑的，小绵羊不是黑色的，就算是我偷的。这就可以证明我是正直的。”","notes":[]},{"n":34,"t":"拉班说：“看哪，就照你所说的做吧。”","notes":[]},{"n":35,"t":"当日，拉班把有纹的、有斑的公山羊，一切有点的、有斑的、有少许白色的母山羊，以及小绵羊中所有黑色的，都挑出来，交在他儿子们的手里，","notes":["“白色”与“拉班”的希伯来文同字。","“所有黑色的”或译“全黑的”；40节同。"]},{"n":36,"t":"又使自己和雅各相隔三天的路程。雅各就牧放拉班其余的羊。","notes":[]},{"n":37,"t":"雅各拿杨树、杏树、枫树的嫩枝，把皮剥出白色的条纹，使枝子露出白色来。","notes":[]},{"n":38,"t":"他把剥了皮的枝子对着羊群，插在羊喝水的水沟和水槽里。羊来喝水的时候，它们彼此交配。","notes":[]},{"n":39,"t":"羊对着枝子交配，就生下有纹的、有点的、有斑的来。","notes":[]},{"n":40,"t":"雅各把小绵羊分出来，让羊对着拉班羊群中有纹的和所有黑色的。于是他把自己的羊群分开，不叫它们和拉班的羊混在一起。","notes":[]},{"n":41,"t":"当肥壮的羊交配的时候，雅各就把枝子插在水沟里，使羊对着枝子交配。","notes":[]},{"n":42,"t":"可是当瘦弱的羊交配的时候，他就不插枝子。这样，瘦弱的就归拉班，肥壮的就归雅各。","notes":[]},{"n":43,"t":"于是这人极其发达，拥有许多的羊群、奴仆、婢女、骆驼和驴。","notes":[]}]},"31":{"heading":"雅各逃离拉班","verses":[{"n":1,"t":"雅各听见拉班儿子们的话，说：“雅各把我们父亲所有的都夺去了！他从我们父亲所拥有的获得这一切的财富。”","notes":[]},{"n":2,"t":"雅各见拉班的脸色，看哪，待他不如从前了。","notes":[]},{"n":3,"t":"耶和华对雅各说：“你要回你祖先之地，到你本族那里去，我必与你同在。”","notes":[]},{"n":4,"t":"雅各就派人叫拉结和利亚到田野他的羊群那里去，","notes":[]},{"n":5,"t":"对她们说：“我看你们父亲待我的脸色不如从前了，但我父亲的神向来与我同在。","notes":[]},{"n":6,"t":"你们也知道，我尽了全力服事你们的父亲。","notes":[]},{"n":7,"t":"可是你们的父亲欺骗我，十次更改我的工资，但神不容许他害我。","notes":[]},{"n":8,"t":"他若说：‘有点的归给你作工资’，羊群所生的都是有点的；他若说：‘有纹的归给你作工资’，羊群所生的都是有纹的。","notes":[]},{"n":9,"t":"这样，神把你们父亲的牲畜拿来赐给我了。","notes":[]},{"n":10,"t":"“羊群交配的时候，我在梦中举目一看，看哪，跳母羊的公羊都是有纹的、有点的、有花斑的。","notes":[]},{"n":11,"t":"神的使者在梦中呼叫我说：‘雅各。’我说：‘我在这里。’","notes":[]},{"n":12,"t":"他说：‘你举目观看，跳母羊的公羊都是有纹的、有点的、有花斑的。拉班向你所做的一切，我都看见了。","notes":[]},{"n":13,"t":"我是伯特利的神；你曾在那里用油膏过柱子，向我许过愿。现在你起来，离开这地，回你本族之地去吧！’”","notes":[]},{"n":14,"t":"拉结和利亚回答雅各说：“在我们父亲家里还有我们可分得的产业吗？","notes":[]},{"n":15,"t":"我们不是被他看作外人吗？因为他卖了我们，还吞吃了我们的银钱。","notes":[]},{"n":16,"t":"神从我们父亲所拿走的一切财物，都是我们和我们孩子的。现在，凡神所吩咐你的，你只管去做吧！”","notes":[]},{"n":17,"t":"雅各起来，叫他的孩子和妻子都骑上骆驼，","notes":[]},{"n":18,"t":"又赶着他一切的牲畜和他所得的一切财物，就是他在巴旦．亚兰所得的，他拥有的牲畜，往迦南地他父亲以撒那里去了。","notes":["“又赶着他一切的牲畜...他拥有的牲畜”：七十士译本是“又带着他拥有的一切和所有的家具，都是他在美索不达米亚获得的”。"]},{"n":19,"t":"当时拉班去剪羊毛，拉结偷了他父亲家中的神像。","notes":[]},{"n":20,"t":"雅各瞒住亚兰人拉班，不通知他就逃走了。","notes":[]},{"n":21,"t":"雅各带着他所有的逃走了；他起程，渡过大河，面向着基列山。","notes":[]},{"n":22,"t":"到第三天，有人告诉拉班，雅各逃跑了。","notes":[],"heads":["拉班追赶雅各"]},{"n":23,"t":"拉班带着他的弟兄们去追他，追了七天，就在基列山追上了。","notes":[]},{"n":24,"t":"夜间，神来到亚兰人拉班那里，在梦中对他说：“你要小心，不可对雅各说好说歹。”","notes":[]},{"n":25,"t":"拉班追上雅各。雅各在山上支搭帐棚；拉班和他的弟兄们也在基列山上支搭帐棚。","notes":[]},{"n":26,"t":"拉班对雅各说：“你做的是什么事呢？你瞒着我把我的女儿们带走，好像用刀剑掳去一般。","notes":[]},{"n":27,"t":"你为什么暗暗地逃跑，瞒着我，不通知我一声，叫我可以欢乐、唱歌、击鼓、弹琴送你回去呢？","notes":[]},{"n":28,"t":"为什么不容许我与外孙和女儿吻别呢？你现在所做的真是愚蠢！","notes":[]},{"n":29,"t":"我的手本有能力害你，只是你父亲的神昨夜对我说：‘你要小心，不可对雅各说好说歹。’","notes":[]},{"n":30,"t":"现在你既然这么想念你的父家，不得不去，为什么又偷了我的神明呢？”","notes":[]},{"n":31,"t":"雅各回答拉班说：“因为我害怕，我想，恐怕你把你的女儿从我这里夺走。","notes":[]},{"n":32,"t":"至于你的神明，你若在谁那里搜出来，就不让谁活。当着我们弟兄面前，你认一认在我这里有什么东西是你的，你就拿去吧。”原来雅各并不知道拉结偷了神明。","notes":[]},{"n":33,"t":"拉班进了雅各、利亚，以及两个使女的帐棚，却没有找到，就从利亚的帐棚出来，进入拉结的帐棚。","notes":[]},{"n":34,"t":"拉结拿了神像，藏在骆驼的鞍子里，自己坐在上面。拉班搜遍了那帐棚，并没有找到。","notes":[]},{"n":35,"t":"拉结对她父亲说：“请我主不要生气，因为我恰有月事，不能在你面前起来。”拉班搜寻，却找不到神像。","notes":[]},{"n":36,"t":"于是雅各发怒，斥责拉班。雅各对拉班说：“我有什么过犯，有什么罪恶，你竟这样火速地追我？","notes":[]},{"n":37,"t":"你搜遍了我一切的物件，你找到什么呢？可以放在你我弟兄面前，叫他们在我们两个之间评评理。","notes":[]},{"n":38,"t":"我在你那里这二十年，你的母绵羊、母山羊没有掉过胎。你羊群中的公绵羊，我没有吃过；","notes":[]},{"n":39,"t":"被野兽撕裂的，我没有带来给你，是我自己赔偿的。无论是白日被偷的，或是黑夜被偷的，你都从我手中索取。","notes":[]},{"n":40,"t":"我常常白日受尽炎热，黑夜受尽寒霜，不得合眼入睡。","notes":[]},{"n":41,"t":"我这二十年在你家里，为你两个女儿服事了你十四年，为你的羊群服事了你六年，你却十次更改我的工资。","notes":[]},{"n":42,"t":"若不是我父亲以撒所敬畏的神，就是亚伯拉罕的神与我同在，你如今必定打发我空手而去。神看见我的苦情和我手的辛劳，就在昨夜责备了你。”","notes":[]},{"n":43,"t":"拉班回答雅各说：“这两个女儿是我的女儿，这些孩子是我的孩子，这些羊群也都是我的羊群；凡你所看见的都是我的。我的女儿和她们所生的孩子，我今日还能对他们做什么呢？","notes":[],"heads":["雅各和拉班立约"]},{"n":44,"t":"现在，来吧！让我和你立约，作你我之间的证据。”","notes":[]},{"n":45,"t":"雅各就拿一块石头立作柱子，","notes":[]},{"n":46,"t":"对弟兄们说：“大家来堆积石头。”他们拿石头堆成一堆，于是在那里，在石堆旁边吃喝。","notes":[]},{"n":47,"t":"拉班称那石堆为伊迦尔．撒哈杜他，雅各却称那石堆为迦累得 。","notes":["“伊迦尔．撒哈杜他”是亚兰文，“迦累得”是希伯来文，都是“石堆为证”的意思。"]},{"n":48,"t":"拉班说：“今日这石堆成为你我之间的证据。”因此这地方名叫迦累得，","notes":[]},{"n":49,"t":"又叫米斯巴，因为他说：“我们彼此离别以后，愿耶和华在你我中间鉴察 。","notes":["“鉴察”与“米斯巴”的希伯来话发音相近。"]},{"n":50,"t":"你若苦待我的女儿，或在我的女儿以外另娶妻，虽没有人在场，你看，有神在你我中间作证。”","notes":[]},{"n":51,"t":"拉班又对雅各说：“看哪，这石堆，看哪，这柱子，是我在你我中间所立的。","notes":[]},{"n":52,"t":"这石堆是证据，这柱子也是证据。我必不越过这石堆去害你；你也不可越过这石堆和柱子来害我。","notes":[]},{"n":53,"t":"愿亚伯拉罕的神和拿鹤的神，就是他们父亲的神，在你我中间判断。”雅各就指着他父亲以撒所敬畏的神起誓，","notes":["有些古卷和七十士译本没有“就是他们父亲的神”。"]},{"n":54,"t":"又在山上献祭，请弟兄们来吃饭。他们吃了饭，就在山上过夜。","notes":[]},{"n":55,"t":"拉班清早起来，与他外孙和女儿亲吻，为他们祝福，就回到自己的地方去了。","notes":[]}]},"32":{"heading":"雅各准备迎见以扫","verses":[{"n":1,"t":"雅各继续行路，神的使者遇见他。","notes":[]},{"n":2,"t":"雅各看见他们就说：“这是神的军营。”于是给那地方起名叫玛哈念 。","notes":["“玛哈念”意思是“两个军营”。"]},{"n":3,"t":"雅各派使者在他前面到西珥地，就是以东地他哥哥以扫那里。","notes":[]},{"n":4,"t":"他吩咐他们说：“你们要对我主以扫说：‘你的仆人雅各这样说：我在拉班那里寄居，延迟到如今。","notes":[]},{"n":5,"t":"我有牛、驴、羊群、奴仆、婢女，现在派人来报告我主，为了要在你眼前蒙恩。’”","notes":[]},{"n":6,"t":"使者回到雅各那里，说：“我们到了你哥哥以扫那里。他正迎着你来，并且有四百人和他一起。”","notes":[]},{"n":7,"t":"雅各就很惧怕，而且愁烦。他把跟他同行的人和羊群、牛群、骆驼分成两队，","notes":[]},{"n":8,"t":"说：“以扫若来击杀其中一队，剩下的另一队还可以逃脱。”","notes":[]},{"n":9,"t":"雅各说：“耶和华—我祖父亚伯拉罕的神，我父亲以撒的神啊，你曾对我说：‘回你本地本族去，我要厚待你。’","notes":[]},{"n":10,"t":"你向仆人所施的一切慈爱和信实，我一点也不配得。我先前只用我的一根杖过这约旦河，如今我却成了两队。","notes":[]},{"n":11,"t":"求你救我脱离我哥哥的手，脱离以扫的手，因为我怕他来杀我，连母亲和儿女都不放过。","notes":[]},{"n":12,"t":"你曾说：‘我必定厚待你，使你的后裔如同海边的沙，多得不可胜数。’”","notes":[]},{"n":13,"t":"当夜，雅各在那里住宿，就从他手中所拥有的拿礼物要送给他哥哥以扫，","notes":[]},{"n":14,"t":"就是二百只母山羊、二十只公山羊、二百只母绵羊、二十只公绵羊、","notes":[]},{"n":15,"t":"三十匹哺乳的母骆驼和它们的小骆驼、四十头母牛、十头公牛、二十匹母驴和十匹公驴。","notes":[]},{"n":16,"t":"他把每种牲畜各分一群，交在仆人手中，对仆人说：“你们要在我的前头过去，使群和群之间保持一段距离”。","notes":[]},{"n":17,"t":"他又吩咐领头的人说：“我哥哥以扫遇见你的时候，问你说：‘你是谁的人？要往哪里去？你前面这些是谁的？’","notes":[]},{"n":18,"t":"你就说：‘是你仆人雅各的，是送给我主以扫的礼物。看哪，他自己也在我们后面。’”","notes":[]},{"n":19,"t":"他又吩咐第二、第三和所有赶畜群的人说：“你们遇见以扫的时候要照这样的话对他说，","notes":[]},{"n":20,"t":"你们还要说：‘看哪，你仆人雅各在我们后面。’”因雅各说：“我藉着在我前面送去的礼物给他面子，然后再见他的面，或许他会宽容我。”","notes":[]},{"n":21,"t":"于是礼物在他前面过去了；那夜，雅各在营中住宿。","notes":[]},{"n":22,"t":"他夜间起来，带着两个妻子，两个婢女和十一个孩子，过了雅博渡口。","notes":[],"heads":["雅各在毗努伊勒摔跤"]},{"n":23,"t":"他带着他们，送他们过河，他所有的一切也都过去，","notes":[]},{"n":24,"t":"只剩下雅各一人。有一个人来和他摔跤，直到黎明。","notes":[]},{"n":25,"t":"那人见自己胜不过他，就摸了他的大腿窝一下。雅各的大腿窝就在和那人摔跤的时候扭了。","notes":[]},{"n":26,"t":"那人说：“天快亮了，让我走吧！”雅各说：“你不给我祝福，我就不让你走。”","notes":[]},{"n":27,"t":"那人说：“你叫什么名字？”他说：“雅各。”","notes":[]},{"n":28,"t":"那人说：“你的名字不要再叫雅各，要叫以色列，因为你与神和人较力，都得胜了。”","notes":[]},{"n":29,"t":"雅各问他说：“请告诉我你的名字。”那人说：“何必问我的名字呢？”于是他在那里为雅各祝福。","notes":[]},{"n":30,"t":"雅各就给那地方起名叫毗努伊勒 ，说：“我面对面见了神，我的性命仍得保全。”","notes":["“毗努伊勒”意思是“神之面”。"]},{"n":31,"t":"太阳刚出来的时候，雅各经过毗努伊勒，他的大腿就瘸了。","notes":[]},{"n":32,"t":"因此，以色列人不吃大腿窝的筋，直到今日，因为那人摸了雅各大腿窝的筋。","notes":[]}]},"33":{"heading":"雅各和以扫相见","verses":[{"n":1,"t":"雅各举目观看，看哪，以扫来了，有四百人和他一起。雅各就把孩子们分开交给利亚、拉结和两个婢女。","notes":[]},{"n":2,"t":"他叫两个婢女和她们的孩子走在前头，利亚和她的孩子跟在后面，而拉结和约瑟在最后。","notes":[]},{"n":3,"t":"他自己却走到他们前面，一连七次俯伏在地才挨近他哥哥。","notes":[]},{"n":4,"t":"以扫跑来迎接他，将他抱住，伏在他的颈项上亲他，他们都哭了。","notes":[]},{"n":5,"t":"以扫举目看见妇人和孩子，就说：“这些和你一起的是谁呢？”雅各说：“这些孩子是神施恩给你仆人的。”","notes":[]},{"n":6,"t":"于是两个婢女和她们的孩子前来下拜，","notes":[]},{"n":7,"t":"利亚和她的孩子也前来下拜，随后约瑟和拉结也前来下拜。","notes":[]},{"n":8,"t":"以扫说：“我所遇见的这些畜群是什么意思呢？”雅各说：“是为了要在我主眼前蒙恩。”","notes":[]},{"n":9,"t":"以扫说：“弟弟啊，我的已经够了，你的你自己留着吧！”","notes":[]},{"n":10,"t":"雅各说：“不，我若在你眼前蒙恩，就请你从我手里收下这礼物；因为我见了你的面，如同见了神的面，并且你也宽容了我。","notes":[]},{"n":11,"t":"请你收下我带来给你的礼物，因为神恩待我，使我一切都充足。”雅各再三求他，他才收下。","notes":[]},{"n":12,"t":"以扫说：“让我们起身前行，我和你一起走吧。”","notes":[]},{"n":13,"t":"雅各对他说：“我主知道孩子们还年幼娇嫩，我的牛羊也正在哺乳中，只要催赶一天，群羊都会死了。","notes":[]},{"n":14,"t":"请我主在仆人前面先走，我要按着在我面前的牲畜和孩子的步伐慢慢前进，直走到西珥我主那里。”","notes":[]},{"n":15,"t":"以扫说：“让我把跟随我的人留几个在你这里。”雅各说：“何必这样呢？只要能在我主眼前蒙恩就够了。”","notes":[]},{"n":16,"t":"于是，以扫当日起行，回西珥去了。","notes":[]},{"n":17,"t":"雅各就往疏割去，在那里为自己盖房屋，又为牲畜搭棚，因此那地方叫疏割 。","notes":["“疏割”意思是“棚”。"]},{"n":18,"t":"雅各从巴旦．亚兰平安地回到迦南地的示剑城，他在城的前面支搭帐棚。","notes":[]},{"n":19,"t":"他用一百可锡塔从示剑的父亲哈抹的众子手中买了搭帐棚的那块地。","notes":["“可锡塔”：古希伯来钱币单位；参“度量衡表”。"]},{"n":20,"t":"雅各在那里筑了一座坛，起名叫伊利．伊罗伊．以色列。","notes":["“伊利．伊罗伊．以色列”意思是“神─以色列的神”。"]}]},"34":{"heading":"底拿受辱","verses":[{"n":1,"t":"利亚给雅各所生的女儿底拿出去，要探望那地的女子们。","notes":[]},{"n":2,"t":"那地的族长希未人哈抹的儿子示剑看见她，就拉住她，与她同寝，玷辱了她。","notes":[]},{"n":3,"t":"示剑的心喜欢雅各的女儿底拿，爱上这少女，甜言蜜语地安慰她。","notes":[]},{"n":4,"t":"示剑对他父亲哈抹说：“求你为我聘这女孩为妻。”","notes":[]},{"n":5,"t":"雅各听见示剑污辱了他的女儿底拿。那时他的儿子们正和牲畜在田野，雅各就沉默，等他们回来。","notes":[]},{"n":6,"t":"示剑的父亲哈抹出来，到雅各那里，要和他讲话。","notes":[]},{"n":7,"t":"雅各的儿子们听见这事，就从田野回来，人人悲愤，十分恼怒，因示剑在以色列中做了丑事，与雅各的女儿同寝，这本是不该做的事。","notes":[]},{"n":8,"t":"哈抹和他们谈话，说：“我儿子示剑的心喜欢你们家的女儿，请你们把她嫁给我的儿子。","notes":[]},{"n":9,"t":"你们与我们彼此结亲；你们可以把你们家的女儿嫁给我们，也可以娶我们家的女儿。","notes":[]},{"n":10,"t":"你们与我们同住吧！这地都在你们面前，只管在这里居住，做买卖，置产业。”","notes":[]},{"n":11,"t":"示剑对女子的父亲和兄弟们说：“愿你们看得起我，你们向我要什么，我必给你们，","notes":[]},{"n":12,"t":"无论向我要多贵重的聘金和礼物，我必照你们所说的给你们，只要你们将这少女嫁给我。”","notes":[]},{"n":13,"t":"雅各的儿子们因示剑污辱了他们的妹妹底拿，就用诡诈的话回答示剑和他父亲哈抹，","notes":[]},{"n":14,"t":"对他们说：“我们不能做这样的事，把我们的妹妹嫁给没有受割礼的人为妻，因为那是我们的羞耻。","notes":[]},{"n":15,"t":"惟有一个条件，我们才答应你们，就是你们所有的男丁都要受割礼，和我们一样，","notes":[]},{"n":16,"t":"我们就把我们家的女儿嫁给你们，也娶你们家的女儿；我们就与你们同住，大家成为一族人。","notes":[]},{"n":17,"t":"倘若你们不听从我们受割礼，我们就带我们家的女儿走了。”","notes":[]},{"n":18,"t":"这些话在哈抹和他儿子示剑的眼中看为美。","notes":[]},{"n":19,"t":"那年轻人毫不迟延做这事，因为他爱上了雅各的女儿；他在他父亲家中也是最受人尊重的。","notes":[]},{"n":20,"t":"哈抹和他儿子示剑到他们的城门口，对城里的人讲说：","notes":[]},{"n":21,"t":"“这些人对我们友善，不如允许他们在这地居住，做买卖；看哪，这地宽阔，足以容纳他们。我们可以娶他们家的女儿，也可以把我们家的女儿嫁给他们。","notes":[]},{"n":22,"t":"惟有一个条件，这些人才答应和我们同住，成为一族人，就是我们中间所有的男丁都要受割礼，和他们一样。","notes":[]},{"n":23,"t":"他们的牲畜、财物和一切的牲口岂不都归给我们吗？只要答应他们，他们就与我们同住。”","notes":[]},{"n":24,"t":"凡从城门出入的人都听从了哈抹和他儿子示剑的话。于是，凡从城门出入的男丁都受了割礼。","notes":[]},{"n":25,"t":"到第三天，他们正疼痛的时候，雅各的两个儿子，就是底拿的哥哥西缅和利未，各拿刀剑，不动声色地来到城中，把所有的男丁都杀了，","notes":[]},{"n":26,"t":"又用刀杀了哈抹和他儿子示剑，把底拿从示剑家里带走，就离开了。","notes":[]},{"n":27,"t":"雅各的儿子们因为他们的妹妹受污辱，就来到被杀的人那里，洗劫那城，","notes":[]},{"n":28,"t":"夺走了他们的羊群、牛群和驴，以及城里和田间所有的；","notes":[]},{"n":29,"t":"又俘掳抢劫他们一切的财物、孩童、妇女，以及房屋中所有的。","notes":[]},{"n":30,"t":"雅各对西缅和利未说：“你们连累了我，使我在这地的居民中，就是在迦南人和比利洗人中坏了名声。我的人丁稀少，他们必聚集来击杀我，我和全家的人都要被灭绝。”","notes":[]},{"n":31,"t":"他们却说：“他岂可待我们的妹妹如同妓女呢？”","notes":[]}]},"35":{"heading":"神在伯特利赐福雅各","verses":[{"n":1,"t":"神对雅各说：“起来！上伯特利去，住在那里。在那里筑一座坛给神，就是你逃避你哥哥以扫的时候向你显现的神。”","notes":[]},{"n":2,"t":"雅各就对他家中的人，以及所有和他一起的人说：“除掉你们中间外邦的神明，要自洁，更换衣服。","notes":[]},{"n":3,"t":"我们要起来，上伯特利去，在那里我要筑一座坛给神，就是在我遭难的日子应允我，在我行走的路上与我同在的神。”","notes":[]},{"n":4,"t":"他们就把手中所有外邦的神明和自己耳朵上的环子交给雅各；雅各把它们埋在示剑那里的橡树下。","notes":[]},{"n":5,"t":"他们起行。神使周围城镇的人都惊恐，就不追赶雅各的儿子们了。","notes":[]},{"n":6,"t":"于是雅各和所有与他一起的人到了迦南地的路斯，就是伯特利。","notes":[]},{"n":7,"t":"他在那里筑了一座坛，给那地方起名叫伊勒．伯特利，因为他逃避他哥哥的时候，神曾在那里向他显现。","notes":["“伊勒．伯特利”意思是“伯特利之神”。"]},{"n":8,"t":"利百加的奶妈底波拉死了，葬在伯特利下边的橡树下；那棵树名叫亚伦．巴古。","notes":[]},{"n":9,"t":"雅各从巴旦．亚兰回来，神又向他显现，赐福给他。","notes":[]},{"n":10,"t":"神对他说：“你的名原是雅各，从今以后不要再叫雅各，你的名要叫以色列。”于是，神就叫他的名为以色列。","notes":[]},{"n":11,"t":"神又对他说：“我是全能的神；你要生养众多，将来有一国和许多的国从你而来，又有许多君王从你生出。","notes":["“从你生出”：原文是“从你腰间而出”。"]},{"n":12,"t":"至于我赐给亚伯拉罕和以撒的地，我必赐给你；我必赐这地给你的后裔。”","notes":[]},{"n":13,"t":"神就从与雅各说话的那地方升上去了。","notes":[]},{"n":14,"t":"雅各就在神与他说话的地方立了一根柱子，就是石柱，在它上面献浇酒祭，又浇油。","notes":[]},{"n":15,"t":"雅各就给神与他说话的那地方起名叫伯特利。","notes":[]},{"n":16,"t":"他们从伯特利起行，到以法他还有一段路程，拉结生产，生得十分艰难。","notes":[],"heads":["拉结去世"]},{"n":17,"t":"她生得十分艰难的时候，接生婆对她说：“不要怕，你又要有一个儿子了。”","notes":[]},{"n":18,"t":"她快要死，还有一口气的时候，就给她儿子起名叫便．俄尼；他父亲却给他起名叫便雅悯。","notes":["“便．俄尼”意思是“我忧伤之子”。","“便雅悯”意思是“我右手之子”。"]},{"n":19,"t":"拉结死了，葬在往以法他的路旁；以法他就是伯利恒。","notes":[]},{"n":20,"t":"雅各在她的坟上立了一块碑，就是拉结的墓碑，到今日还在。","notes":[]},{"n":21,"t":"以色列起行，在以得台的那一边支搭帐棚。","notes":[]},{"n":22,"t":"以色列住在那地的时候，吕便去与他父亲的妾辟拉同寝，以色列也听见了这件事。雅各共有十二个儿子。","notes":["“以色列也听见了这件事”：七十士译本是“以色列听见这事，就看为恶”。"],"heads":["雅各的儿子们"]},{"n":23,"t":"利亚的儿子是雅各的长子吕便，还有西缅、利未、犹大、以萨迦、西布伦。","notes":[]},{"n":24,"t":"拉结的儿子是约瑟、便雅悯。","notes":[]},{"n":25,"t":"拉结的婢女辟拉的儿子是但、拿弗他利。","notes":[]},{"n":26,"t":"利亚的婢女悉帕的儿子是迦得、亚设。这是雅各在巴旦．亚兰所生的儿子。","notes":[]},{"n":27,"t":"雅各来到他父亲以撒那里，到了幔利，基列．亚巴，就是希伯仑，是亚伯拉罕和以撒寄居的地方。","notes":[],"heads":["以撒的死"]},{"n":28,"t":"以撒共活了一百八十年。","notes":[]},{"n":29,"t":"以撒年纪老迈，安享天年，息劳而终，归到他祖先那里。他两个儿子以扫和雅各把他安葬了。","notes":["“他祖先”：原文是“他百姓”。"]}]},"36":{"heading":"以扫的后代","verses":[{"n":1,"t":"这是以扫的后代，以扫就是以东。","notes":[]},{"n":2,"t":"以扫娶迦南的女子为妻，就是赫人以伦的女儿亚大和希未人祭便的孙女，亚拿的女儿阿何利巴玛，","notes":[]},{"n":3,"t":"又娶了以实玛利的女儿，尼拜约的妹妹巴实抹。","notes":[]},{"n":4,"t":"亚大为以扫生了以利法；巴实抹生了流珥；","notes":[]},{"n":5,"t":"阿何利巴玛生了耶乌施、雅兰、可拉。这些都是以扫的儿子，是在迦南地生的。","notes":[]},{"n":6,"t":"以扫带着他的妻子、儿女和家中所有的人，以及他的牛羊、牲畜和一切财物，就是他在迦南地所得的，往别处去，离开了他的兄弟雅各。","notes":[]},{"n":7,"t":"因为他们拥有的很多，不能住在一起。因为牲畜的缘故，寄居的地方容不下他们。","notes":[]},{"n":8,"t":"于是以扫住在西珥山；以扫就是以东。","notes":[]},{"n":9,"t":"这是以扫的后代，他是西珥山里以东人的始祖。","notes":[]},{"n":10,"t":"以扫子孙的名字如下：以扫的妻子亚大生以利法；以扫的妻子巴实抹生流珥。","notes":[]},{"n":11,"t":"以利法的儿子是提幔、阿抹、洗玻、迦坦、基纳斯。","notes":[]},{"n":12,"t":"亭纳是以扫儿子以利法的妾，她为以利法生了亚玛力。这是以扫的妻子亚大的子孙。","notes":[]},{"n":13,"t":"流珥的儿子是拿哈、谢拉、沙玛、米撒。这是以扫妻子巴实抹的子孙。","notes":[]},{"n":14,"t":"以扫的妻子阿何利巴玛是祭便的孙女，亚拿的女儿。她为以扫生了耶乌施、雅兰、可拉。","notes":[]},{"n":15,"t":"这是以扫子孙中作族长的：以扫的长子以利法的子孙中，有提幔族长、阿抹族长、洗玻族长、基纳斯族长、","notes":[]},{"n":16,"t":"可拉族长、迦坦族长、亚玛力族长。这是在以东地，从以利法所出的族长，是亚大的子孙。","notes":[]},{"n":17,"t":"以扫的儿子流珥的子孙中，有拿哈族长、谢拉族长、沙玛族长、米撒族长。这是在以东地，从流珥所出的族长，是以扫妻子巴实抹的子孙。","notes":[]},{"n":18,"t":"以扫的妻子阿何利巴玛的子孙中，有耶乌施族长、雅兰族长、可拉族长。这是从以扫的妻子，亚拿的女儿阿何利巴玛的子孙中所出的族长。","notes":[]},{"n":19,"t":"以上的族长都是以扫的子孙；以扫就是以东。","notes":[]},{"n":20,"t":"这是那地原来的居民，何利人西珥的子孙：罗坍、朔巴、祭便、亚拿、","notes":[],"heads":["西珥的子孙"]},{"n":21,"t":"底顺、以察、底珊。这是在以东地，从何利人西珥子孙中所出的族长。","notes":[]},{"n":22,"t":"罗坍的儿子是何利、希幔，罗坍的妹妹是亭纳。","notes":[]},{"n":23,"t":"朔巴的儿子是亚勒文、玛拿辖、以巴录、示玻、阿南。","notes":[]},{"n":24,"t":"祭便的儿子是爱亚、亚拿，当时在旷野牧放他父亲祭便的驴，发现温泉的就是这亚拿。","notes":[]},{"n":25,"t":"亚拿的儿子是底顺，亚拿的女儿是阿何利巴玛。","notes":[]},{"n":26,"t":"底顺的儿子是欣但、伊是班、益兰、基兰。","notes":[]},{"n":27,"t":"以察的儿子是辟罕、撒番、亚干。","notes":[]},{"n":28,"t":"底珊的儿子是乌斯、亚兰。","notes":[]},{"n":29,"t":"这是从何利人所出的族长：罗坍族长、朔巴族长、祭便族长、亚拿族长、","notes":[]},{"n":30,"t":"底顺族长、以察族长、底珊族长。这是从何利人所出的族长，都在西珥地，按着族长来分。","notes":["“族长”：七十士译本是“宗族”。"]},{"n":31,"t":"以色列未有君王治理之前，这些是在以东地作王的。","notes":[],"heads":["以东诸王"]},{"n":32,"t":"比珥的儿子比拉在以东作王，他的城名叫亭哈巴。","notes":[]},{"n":33,"t":"比拉死了，波斯拉人谢拉的儿子约巴接续他作王。","notes":[]},{"n":34,"t":"约巴死了，提幔人之地的户珊接续他作王。","notes":[]},{"n":35,"t":"户珊死了，比达的儿子哈达接续他作王，哈达曾在摩押地击败米甸人，他的城名叫亚未得。","notes":[]},{"n":36,"t":"哈达死了，玛士利加人桑拉接续他作王。","notes":[]},{"n":37,"t":"桑拉死了，大河边的利河伯人扫罗接续他作王。","notes":[]},{"n":38,"t":"扫罗死了，亚革波的儿子巴勒．哈南接续他作王。","notes":[]},{"n":39,"t":"亚革波的儿子巴勒．哈南死了，哈达尔接续他作王，他的城名叫巴乌。他的妻子名叫米希她别，是米．萨合的孙女，玛特列的女儿。","notes":["“哈达尔”：有古卷是“哈达”；参代上1．50。"]},{"n":40,"t":"这是以扫的族长，按着他们的宗族、住处和名字：亭纳族长、亚勒瓦族长、耶帖族长、","notes":[]},{"n":41,"t":"阿何利巴玛族长、以拉族长、比嫩族长、","notes":[]},{"n":42,"t":"基纳斯族长、提幔族长、米比萨族长、","notes":[]},{"n":43,"t":"玛基叠族长、以兰族长。这些是以东人在所得为业的地上，按着他们住处的族长。以扫是以东人的始祖。","notes":[]}]},"37":{"heading":"约瑟和他的兄弟","verses":[{"n":1,"t":"雅各住在迦南地，就是他父亲寄居的地。","notes":[]},{"n":2,"t":"这是雅各的事迹。约瑟十七岁与他哥哥们一同牧羊。他是个少年，与他父亲的妾辟拉和悉帕的儿子们常在一起。约瑟把他们的恶行报给父亲。","notes":[]},{"n":3,"t":"以色列爱约瑟过于其他的儿子，因为约瑟是他年老生的；他给约瑟做了一件长袍。","notes":["“长袍”：七十士译本和其他古译本是“彩衣”；下同。"]},{"n":4,"t":"哥哥们见父亲爱约瑟过于他们，就恨约瑟，不与他说友善的话。","notes":[]},{"n":5,"t":"约瑟做了一个梦，告诉他哥哥们，他们就更加恨他。","notes":[]},{"n":6,"t":"约瑟对他们说：“请听我做的这个梦：","notes":[]},{"n":7,"t":"看哪，我们在田里捆禾稼；看哪，我的捆起来站着；看哪，你们的捆围着我的捆下拜。”","notes":[]},{"n":8,"t":"他的哥哥们对他说：“难道你真的要作我们的王吗？难道你真的要统治我们吗？”他们就因他的梦和他的话更加恨他。","notes":[]},{"n":9,"t":"后来他又做了另一个梦，告诉他哥哥们说：“看哪，我又做了一个梦；看哪，太阳、月亮和十一颗星都向我下拜。”","notes":[]},{"n":10,"t":"约瑟告诉他父亲和哥哥们，他父亲就责备他说：“你做的这是什么梦！难道我和你母亲、你的兄弟真的要俯伏在地，来向你下拜吗？”","notes":[]},{"n":11,"t":"他的哥哥们都嫉妒他，他父亲却把这事存在心里。","notes":[]},{"n":12,"t":"约瑟的哥哥们到示剑去放他们父亲的羊。","notes":[],"heads":["约瑟被卖到埃及"]},{"n":13,"t":"以色列对约瑟说：“你哥哥们不是在示剑放羊吗？来，我派你到他们那里去。”约瑟对他说：“我在这里。”","notes":[]},{"n":14,"t":"以色列对他说：“你去看看你哥哥们是否平安，羊群是否平安，再回来告诉我。”于是他派约瑟出希伯仑谷，约瑟就往示剑去了。","notes":[]},{"n":15,"t":"有人遇见他，看哪，他在田野走迷了路。那人问他说：“你找什么？”","notes":[]},{"n":16,"t":"他说：“我找我的哥哥们，请告诉我，他们在哪里放羊。”","notes":[]},{"n":17,"t":"那人说：“他们已经离开这里走了，我听见他们说：‘我们往多坍去。’”约瑟就去追哥哥们，在多坍找到了他们。","notes":[]},{"n":18,"t":"他们远远看见他，趁他还没有走近他们，就图谋要杀死他。","notes":[]},{"n":19,"t":"他们彼此说：“看哪！那做梦的来了。","notes":[]},{"n":20,"t":"现在，来吧！我们把他杀了，丢在一个坑里，就说有恶兽把他吃了。我们且看他的梦将来怎么样。”","notes":[]},{"n":21,"t":"吕便听见了，要救约瑟脱离他们的手，说：“我们不可害他的性命”；","notes":[]},{"n":22,"t":"吕便又对他们说：“不可流他的血，可以把他丢在这旷野的坑里，不可下手害他。”吕便要救他脱离他们的手，把他还给他父亲。","notes":[]},{"n":23,"t":"约瑟到了他哥哥们那里，他们就剥去他的外衣，就是他身上那件长袍。","notes":[]},{"n":24,"t":"他们抓住他，把他丢在坑里。那坑是空的，里头没有水。","notes":[]},{"n":25,"t":"他们坐下吃饭，举目观看，看哪，有一群以实玛利人从基列来，用骆驼驮着香料、乳香、没药，要带下埃及去。","notes":[]},{"n":26,"t":"犹大对他的兄弟们说：“我们杀我们的弟弟，遮掩他的血有什么好处呢？","notes":[]},{"n":27,"t":"来，我们把他卖给以实玛利人，不要下手害他，因为他是我们的弟弟，我们的骨肉。”他的兄弟们就听从了他。","notes":[]},{"n":28,"t":"那时，有些米甸的商人从那里经过，就把约瑟从坑里拉上来。他们以二十块银子把约瑟卖给以实玛利人，他们就把约瑟带到埃及去了。","notes":[]},{"n":29,"t":"吕便回到坑旁，看哪，约瑟不在坑里，就撕裂自己的衣服，","notes":[]},{"n":30,"t":"回到他兄弟们那里，说：“孩子不在了。我往哪里去才好呢？”","notes":[]},{"n":31,"t":"于是，他们宰了一只公山羊，拿了约瑟的那件外衣染上了血，","notes":[]},{"n":32,"t":"派人把长袍送到他们的父亲那里，说：“我们发现这个， 请认一认，是不是你儿子的外衣？”","notes":[]},{"n":33,"t":"他认出来，就说：“这是我儿子的外衣，恶兽把他吃了，约瑟一定被撕碎了！”","notes":[]},{"n":34,"t":"雅各就撕裂衣服，腰间围上麻布，为他儿子哀伤了多日。","notes":[]},{"n":35,"t":"他的儿女都起来安慰他，他却不肯受安慰，说：“我必哀伤着下阴间，到我儿子那里。”约瑟的父亲就为他哀哭。","notes":[]},{"n":36,"t":"米甸人把约瑟卖到埃及，给法老的官员，就是护卫长波提乏。","notes":[]}]},"38":{"heading":"犹大和她玛","verses":[{"n":1,"t":"那时，犹大离开他兄弟们下去，到一个名叫希拉的亚杜兰人的家附近支搭帐棚。","notes":[]},{"n":2,"t":"犹大在那里看见一个名叫拔．书亚的迦南女子，就娶她为妻，与她同房，","notes":[]},{"n":3,"t":"她就怀孕生了儿子，犹大给他起名叫珥。","notes":[]},{"n":4,"t":"她又怀孕生了儿子，给他起名叫俄南。","notes":[]},{"n":5,"t":"她又再生了儿子，给他起名叫示拉。她生示拉的时候，犹大正在基悉。","notes":[]},{"n":6,"t":"犹大为长子珥娶妻，名叫她玛。","notes":[]},{"n":7,"t":"犹大的长子珥在耶和华眼中看为恶，耶和华就杀死了他。","notes":[]},{"n":8,"t":"犹大对俄南说：“你当与你哥哥的妻子同房，向她尽你的本分，为你哥哥生子立后。”","notes":[]},{"n":9,"t":"俄南知道如果与嫂嫂同房，所生的孩子不属于自己，就泄在地上，不为哥哥生子立后。","notes":[]},{"n":10,"t":"俄南所做的在耶和华眼中看为恶，耶和华也杀死了他。","notes":[]},{"n":11,"t":"犹大对他媳妇她玛说：“你去住在你父亲家里守寡，等我儿子示拉长大。”因为他说：“恐怕示拉也像两个哥哥一样死去。”她玛就去，住在她父亲家里。","notes":[]},{"n":12,"t":"过了一段很长的日子，犹大的妻子，书亚的女儿死了。犹大受到了安慰，就和他朋友亚杜兰人希拉上亭拿去，到他的剪羊毛的人那里。","notes":[]},{"n":13,"t":"有人告诉她玛说：“看哪，你的公公上亭拿剪羊毛去了。”","notes":[]},{"n":14,"t":"她玛见示拉已经长大，却还没有娶她为妻，就脱去她寡妇的衣裳，用面纱蒙着，盖住自己，坐在往亭拿的路上，伊拿印城门口。","notes":[]},{"n":15,"t":"犹大看见她，以为是妓女，因为她蒙着脸。","notes":[]},{"n":16,"t":"犹大就转到路边她那里，说：“来吧！让我与你同寝。”他并不知道她就是他的媳妇。她玛说：“你要与我同寝，把什么给我呢？”","notes":[]},{"n":17,"t":"犹大说：“我从羊群里取一只小山羊，派人送来给你。”她玛说：“在未送之前，你能给我一个信物吗？”","notes":[]},{"n":18,"t":"他说：“我给你什么信物呢？”她玛说：“你的印、你的带子和你手里的杖。”于是犹大给了她，与她同寝，她就从犹大怀了孕。","notes":["“带子”指“系印的带子”；下同。"]},{"n":19,"t":"她玛起来走了，除去面纱，照常穿上寡妇的衣裳。","notes":[]},{"n":20,"t":"犹大托他朋友亚杜兰人送一只小山羊去，要从那女人手里取回信物，却找不到她。","notes":[]},{"n":21,"t":"他问那地方的人说：“伊拿印路旁的神庙娼妓在哪里？”他们说：“这里没有神庙娼妓。”","notes":[]},{"n":22,"t":"他回到犹大那里说：“我找不到她，并且那地方的人说：‘这里没有神庙娼妓。’”","notes":[]},{"n":23,"t":"犹大说：“让她拿去吧，免得我们被人讥笑。看哪，我把这小山羊送去了，可是你找不到她。”","notes":[]},{"n":24,"t":"大约过了三个月，有人告诉犹大说：“你的媳妇她玛行淫，并且，看哪，她因行淫而怀了孕。”犹大说：“拉她出来，把她烧了！”","notes":[]},{"n":25,"t":"她玛被拉出来的时候，就派人到她公公那里，对他说：“这些东西是谁的，我就是从谁怀了孕。”她又说：“请你认一认，这印、这带子和这杖是谁的？”","notes":[]},{"n":26,"t":"犹大承认说：“她比我更有理，因为我没有把她给我的儿子示拉。”犹大再也不跟她同寝。","notes":[]},{"n":27,"t":"她玛生产的时候到了，看哪，腹里怀的是双胞胎。","notes":[]},{"n":28,"t":"生产的时候，一个孩子伸出手来；接生婆拿红线绑在他手上，说：“这是头生的。”","notes":[]},{"n":29,"t":"这孩子把手收回去，看哪，他哥哥生出来了；接生婆说：“你竟然为自己冲出一个裂缝！”于是，他的名字叫法勒斯。","notes":["“法勒斯”意思是“裂缝”。"]},{"n":30,"t":"后来，那手上有红线的兄弟也生出来，他的名字叫谢拉。","notes":["“谢拉”意思是“明亮”，也许暗示“鲜红”。"]}]},"39":{"heading":"约瑟和波提乏之妻","verses":[{"n":1,"t":"约瑟被带下埃及去。有一个埃及人波提乏，是法老的官员，是护卫长，他从那些带约瑟下来的以实玛利人手中把约瑟买了去。","notes":[]},{"n":2,"t":"约瑟在他埃及主人的家中，耶和华与他同在，他是一个通达的人。","notes":[]},{"n":3,"t":"他主人见耶和华与他同在，又见耶和华使他手里所办的事都顺利，","notes":[]},{"n":4,"t":"约瑟就在主人眼前蒙恩，伺候他主人，主人派他管理家务，把一切所有的都交在他手里。","notes":[]},{"n":5,"t":"自从主人派约瑟管理家务和他一切所有的，耶和华就因约瑟的缘故赐福给那埃及人的家；凡家里和田间一切所有的，都蒙耶和华赐福。","notes":[]},{"n":6,"t":"波提乏把他一切所有的都交在约瑟手中，除了自己所吃的食物，其他的事一概不知。约瑟英俊健美。","notes":[]},{"n":7,"t":"这些事以后，约瑟主人的妻子以目送情给约瑟，说：“你与我同寝吧！”","notes":[]},{"n":8,"t":"约瑟拒绝，对他主人的妻子说：“看哪，一切家务我主人一概不知，他把所有的都交在我手里。","notes":[]},{"n":9,"t":"在这家里没有人比我更大，除你以外，他也没有留下一样不交给我，因为你是他的妻子。我怎能行这么大的恶，得罪神呢？”","notes":[]},{"n":10,"t":"她天天这样对约瑟说，约瑟却不听从她，不与她同寝，也不和她在一起。","notes":[]},{"n":11,"t":"有一天，约瑟进屋里去办事，家里没有一个人在那屋子里，","notes":[]},{"n":12,"t":"妇人就拉住他的衣服，说：“你与我同寝吧！”约瑟把衣服留在她手里，逃出外面去了。","notes":[]},{"n":13,"t":"妇人看见约瑟把衣服留在她手里逃到外面，","notes":[]},{"n":14,"t":"就叫了家里的人来，对他们说：“看，他带了一个希伯来人到我们这里戏弄我们。他到我这里来，要与我同寝，我就大声喊叫。","notes":[]},{"n":15,"t":"他听见我放声大喊，就把他的衣服留在我这里，逃出外面去了。”","notes":[]},{"n":16,"t":"妇人把约瑟的衣服放在身边，直到他主人回家，","notes":[]},{"n":17,"t":"就用这样的话对他说：“你带到我们这里来的那希伯来仆人进来要调戏我，","notes":[]},{"n":18,"t":"我放声大喊，他就把衣服留在我身边，逃到外面。”","notes":[]},{"n":19,"t":"主人听见他妻子对他说的话，说：“你的仆人就是这样对待我”，就非常生气。","notes":[]},{"n":20,"t":"约瑟的主人把他抓起来，关在监狱里，就是王的囚犯被关的地方。于是约瑟在那里坐牢。","notes":[]},{"n":21,"t":"但耶和华与约瑟同在，向他施恩，使他在监狱长的眼前蒙恩。","notes":[]},{"n":22,"t":"监狱长就把监狱里所有的囚犯都交在约瑟手下；在那里的一切事都由他处理。","notes":[]},{"n":23,"t":"任何交在约瑟手中的事，监狱长一概不察，因为耶和华与约瑟同在，耶和华使他所做的都顺利。","notes":[]}]},"40":{"heading":"约瑟为囚犯解梦","verses":[{"n":1,"t":"这些事以后，埃及王的司酒长和司膳长得罪了他们的主埃及王。","notes":[]},{"n":2,"t":"法老就对司酒长和司膳长两个官员发怒，","notes":[]},{"n":3,"t":"把他们关在护卫长府内的监狱里，就是约瑟被囚的地方。","notes":[]},{"n":4,"t":"护卫长把他们交给约瑟，约瑟就伺候他们。他们被关了一段日子。","notes":[]},{"n":5,"t":"关在监狱里的这两个人，就是埃及王的司酒长和司膳长，在同一个晚上各自做了一个梦，每个梦都有自己的解释。","notes":[]},{"n":6,"t":"到了早晨，约瑟来到他们那里看他们，看哪，他们很忧愁。","notes":[]},{"n":7,"t":"他就问一同关在他主人府内法老的官员，说：“你们今日为什么面带愁容呢？”","notes":[]},{"n":8,"t":"他们对他说：“我们各自做了一个梦，却没有人能讲解。”约瑟对他们说：“解梦不是出于神吗？请你们把梦告诉我。”","notes":[]},{"n":9,"t":"司酒长就把梦告诉约瑟，对他说：“在我的梦中，看哪，有一棵葡萄树在我面前，","notes":[]},{"n":10,"t":"树上有三根枝子。枝子发了芽，开了花，结出串串成熟的葡萄。","notes":[]},{"n":11,"t":"法老的杯在我手中，我就拿葡萄挤在法老的杯里，把杯递到他手中。”","notes":[]},{"n":12,"t":"约瑟对他说：“梦的解释是这样：三根枝子就是三天；","notes":[]},{"n":13,"t":"三天之内，法老要让你抬起头来，叫你官复原职。你仍要递杯在法老的手中，像先前作他的司酒长一样。","notes":[]},{"n":14,"t":"但你得福的时候，请你记得我，向我施慈爱，在法老面前提起我，救我出这监牢。","notes":[]},{"n":15,"t":"我实在是从希伯来人之地被拐来的，我在这里也没有做过什么，好叫他们把我关在牢里。”","notes":[]},{"n":16,"t":"司膳长见梦解得好，就对约瑟说：“在我梦中，看哪，我头上顶着三个装饼的篮子；","notes":[]},{"n":17,"t":"最上面的篮子里有为法老烤的各样食物，有飞鸟来吃我头上篮子里的食物。”","notes":[]},{"n":18,"t":"约瑟说：“梦的解释是这样：三个篮子就是三天；","notes":[]},{"n":19,"t":"三天之内，法老要让你抬起头来，身首异处，把你挂在木架上，必有飞鸟来吃你身上的肉。”","notes":[]},{"n":20,"t":"到了第三天，正是法老的生日，他为众臣仆摆设宴席，使司酒长和司膳长从众臣仆中抬起头来，","notes":[]},{"n":21,"t":"让司酒长官复原职，仍旧递杯在法老手中，","notes":[]},{"n":22,"t":"却把司膳长挂起来，正如约瑟向他们所讲解的。","notes":[]},{"n":23,"t":"然而，司酒长不记得约瑟，竟忘了他。","notes":[]}]},"41":{"heading":"约瑟为法老解梦","verses":[{"n":1,"t":"过了两年，法老做梦，看哪，自己站在尼罗河边，","notes":[]},{"n":2,"t":"看哪，有七头母牛从尼罗河里上来，长相俊美，肌肉肥壮，在芦苇中吃草。","notes":[]},{"n":3,"t":"看哪，随后又有七头母牛从尼罗河里上来，长相丑陋，肌肉干瘦，与那七头母牛一同站在河边。","notes":[]},{"n":4,"t":"这长相丑陋，肌肉干瘦的七头母牛吃了那长相俊美又肥壮的七头母牛。法老就醒了。","notes":[]},{"n":5,"t":"他又睡着，第二次做梦，看哪，一株麦杆长了七个穗子，又肥大又佳美，","notes":[]},{"n":6,"t":"看哪，随后又长出七个穗子，又细弱又被东风吹焦了。","notes":[]},{"n":7,"t":"这细弱的穗子吞了那七个又肥大又饱满的穗子。法老醒了，看哪，是个梦。","notes":[]},{"n":8,"t":"到了早晨，法老心里不安，就派人把埃及所有的术士和智慧人都召来。法老把所做的梦告诉他们，但是没有人能为法老解梦。","notes":[]},{"n":9,"t":"那时司酒长对法老说：“我今日想起我的罪来。","notes":[]},{"n":10,"t":"从前法老对臣仆发怒，把我和司膳长关在护卫长府内的监牢里。","notes":[]},{"n":11,"t":"我们两人在同一晚上各做一梦，每个梦都有各自的解释。","notes":[]},{"n":12,"t":"同我们在一起有一个希伯来的年轻人，是护卫长的仆人。我们告诉他，他就为我们解梦，照着各人的梦讲解。","notes":[]},{"n":13,"t":"后来事情正如他给我们讲解的实现了，我官复原职，司膳长被挂起来了。”","notes":[]},{"n":14,"t":"于是法老派人去召约瑟，他们就急忙把他从牢里提出来。他就剃头刮脸，换衣服，进到法老面前。","notes":[]},{"n":15,"t":"法老对约瑟说：“我做了一个梦，没有人能讲解。我听人说，你听了梦就能讲解。”","notes":[]},{"n":16,"t":"约瑟回答法老说：“这不在乎我。神必应允法老平安。”","notes":[]},{"n":17,"t":"法老对约瑟说：“在我的梦中，看哪，我站在尼罗河边，","notes":[]},{"n":18,"t":"看哪，有七头母牛从尼罗河里上来，肌肉肥壮，外形俊美，在芦苇中吃草。","notes":[]},{"n":19,"t":"看哪，随后又有七头母牛上来，虚弱，外形很丑陋，肌肉又干瘦，在埃及全地，我没有见过这样丑陋的牛。","notes":[]},{"n":20,"t":"这干瘦又丑陋的母牛吃了那先前的七头肥母牛，","notes":[]},{"n":21,"t":"进了肚子以后却看不出已经进了肚子，那丑陋的长相仍旧和先前一样。我就醒了。","notes":[]},{"n":22,"t":"我又在梦中观看，看哪，一株麦杆长了七个穗子，又饱满又佳美，","notes":[]},{"n":23,"t":"看哪，随后又长出七个穗子，枯槁，细弱，又被东风吹焦了。","notes":[]},{"n":24,"t":"这些细弱的穗子吞了那七个佳美的穗子。我告诉术士，却没有人能为我讲解。”","notes":[]},{"n":25,"t":"约瑟对法老说：“法老的梦是同一个。神已把要做的事指示法老了。","notes":[]},{"n":26,"t":"七头好母牛是七年，七个佳美的穗子也是七年，这是同一个梦。","notes":[]},{"n":27,"t":"那随后上来的七头干瘦又丑陋的母牛是七年；那七个空心，被东风吹焦的穗子也一样，都是七个荒年。","notes":[]},{"n":28,"t":"这就是我对法老所说，神已把要做的事显明给法老了。","notes":[]},{"n":29,"t":"看哪，必有七个大丰年来到埃及全地，","notes":[]},{"n":30,"t":"随后又有七个荒年，甚至埃及地的人都忘了先前的丰收，这地必被饥荒所灭。","notes":[]},{"n":31,"t":"因为那后来的饥荒非常严重，就不觉得这地先前有丰收。","notes":[]},{"n":32,"t":"至于法老两次做梦，是因为神已经确定这事，神必速速成就。","notes":[]},{"n":33,"t":"现在，请法老选一个聪明又有智慧的人，委派他治理埃及地。","notes":[]},{"n":34,"t":"请法老这样做，委派官员治理这地，在七个丰年的期间，征收埃及地出产的五分之一，","notes":[]},{"n":35,"t":"叫他们聚集未来丰年一切的粮食，积存五谷归在法老的手下作粮食，储藏在各城里。","notes":[]},{"n":36,"t":"这粮食可以为这地作储备，为了埃及地要来的七个荒年，免得这地被饥荒所灭。”","notes":[]},{"n":37,"t":"这事在法老和他众臣仆眼中都觉得好。","notes":[],"heads":["约瑟被立为埃及的宰相"]},{"n":38,"t":"法老对臣仆说：“像这样的人，有神的灵在他里面，我们岂能找得着呢？”","notes":[]},{"n":39,"t":"法老对约瑟说：“神既指示你这一切事，就没有人像你这样聪明又有智慧。","notes":[]},{"n":40,"t":"你可以治理我的家；我的百姓都必服从你口中的命令。惟独在宝座上，我比你大。”","notes":[]},{"n":41,"t":"法老又对约瑟说：“看，我委派你治理埃及全地。”","notes":[]},{"n":42,"t":"法老就脱下手上带印的戒指，戴在约瑟的手上，给他穿上细麻衣，把金链戴在他的颈项上，","notes":[]},{"n":43,"t":"又给约瑟坐他的副座车，在他前面有人呼叫说：“跪下。”于是，法老委派他治理埃及全地。","notes":["“跪下”或译“让开”。"]},{"n":44,"t":"法老对约瑟说：“我是法老，若没有你的命令，埃及全地的人都不可擅自办事。”","notes":["“擅自办事”：原文是“动手动脚”。"]},{"n":45,"t":"法老给约瑟起名叫撒发那特．巴内亚，又将安城的祭司波提．非拉的女儿亚西纳给他为妻。约瑟就出去治理埃及地。","notes":[]},{"n":46,"t":"约瑟在埃及王法老面前侍立的时候年三十岁。约瑟从法老面前出去，巡行埃及全地。","notes":[]},{"n":47,"t":"七个丰年之内，地的出产极其丰盛，","notes":["“极其丰盛”：原文是“一把一把的”。"]},{"n":48,"t":"约瑟聚集埃及地七年一切的粮食，把粮食积存在各城里，就是把各城周围田地的粮食都积存在该城里。","notes":[]},{"n":49,"t":"约瑟积存的五谷很多，如同海边的沙，无法计算，数也数不清。","notes":[]},{"n":50,"t":"荒年未到以前，安城的祭司波提．非拉的女儿亚西纳为约瑟生了两个儿子。","notes":[]},{"n":51,"t":"约瑟给长子起名叫玛拿西，因为他说：“神使我忘了一切的困苦和我父的全家。”","notes":["“玛拿西”意思是“使忘记”。"]},{"n":52,"t":"他给次子起名叫以法莲，因为他说：“神使我在受苦的地方兴盛。”","notes":["“以法莲”意思是“兴盛”。"]},{"n":53,"t":"埃及地的七个丰年一过，","notes":[]},{"n":54,"t":"七个荒年就来了，正如约瑟所说的。各地都有饥荒，惟独埃及全地有粮食。","notes":[]},{"n":55,"t":"等到埃及全地也有了饥荒，众百姓就向法老哀求粮食。法老对所有的埃及人说：“你们到约瑟那里去，凡他所说的，你们都要做。”","notes":[]},{"n":56,"t":"当时饥荒遍满了全地，约瑟就开了各处的粮仓，卖粮食给埃及人。埃及地的饥荒非常严重。","notes":["“各处的粮仓”是根据七十士译本和其他古译本；原文是“所有在它们里面的”。"]},{"n":57,"t":"各地的人都去埃及，到约瑟那里买粮食，因为全地的饥荒非常严重。","notes":[]}]},"42":{"heading":"约瑟的哥哥到埃及买粮","verses":[{"n":1,"t":"雅各见埃及有粮，就对儿子们说：“你们为什么彼此对看呢？”","notes":[]},{"n":2,"t":"他又说：“看哪，我听见埃及有粮，你们可以下到那里，从那里为我们买些粮来，我们就可以存活，不至于死。”","notes":[]},{"n":3,"t":"于是，约瑟的十个哥哥都下去，到埃及买粮食。","notes":[]},{"n":4,"t":"至于约瑟的弟弟便雅悯，雅各没有派他和哥哥们同去，因为雅各说：“恐怕他遭难。”","notes":[]},{"n":5,"t":"以色列的儿子们来了，在前来的人当中，为要买粮食，因为迦南地也有饥荒。","notes":[]},{"n":6,"t":"当时在埃及地掌权的人是约瑟，卖粮给各地众百姓的就是他。约瑟的哥哥们来了，脸伏于地，向他下拜。","notes":[]},{"n":7,"t":"约瑟看见他哥哥们，就认出他们，却对他们装作陌生人，向他们说严厉的话，对他们说：“你们从哪里来？”他们说：“我们从迦南地来买粮。”","notes":[]},{"n":8,"t":"约瑟认得他哥哥们，他们却不认得他。","notes":[]},{"n":9,"t":"约瑟想起从前所做的那两个梦，就对他们说：“你们是奸细，你们来是要窥探这地的虚实。”","notes":[]},{"n":10,"t":"他们对他说：“我主啊，不是的，仆人们是来买粮的。","notes":[]},{"n":11,"t":"我们都是同一个人的儿子，我们是诚实的人。仆人们并不是奸细。”","notes":[]},{"n":12,"t":"约瑟对他们说：“不，你们一定是窥探这地的虚实来的。”","notes":[]},{"n":13,"t":"他们说：“仆人们本是兄弟十二人，我们都是迦南地同一个人的儿子。看哪，最小的今日在我们父亲那里，有一个不在了。”","notes":[]},{"n":14,"t":"约瑟对他们说：“我刚才对你们说过了，你们是奸细！","notes":[]},{"n":15,"t":"我指着法老的性命起誓，若是你们最小的弟弟不到这里来，你们就不可以离开这里；这样你们就可以证实自己了。","notes":[]},{"n":16,"t":"要派你们当中的一个人去，把你们的弟弟带来。至于你们，都要关在这里，好证实你们的话是不是真的。若不是，我指着法老的性命起誓，你们一定是奸细。”","notes":[]},{"n":17,"t":"于是约瑟把他们一起都关在监里三天。","notes":[]},{"n":18,"t":"第三天，约瑟对他们说：“我是敬畏神的，你们这么做就可以活。","notes":[]},{"n":19,"t":"如果你们是诚实的人，留你们兄弟中的一个关在监牢里，你们带粮食回去，救你们家的饥荒，","notes":[]},{"n":20,"t":"再把你们最小的弟弟带到我这里来。如此，你们的话就是真的了，你们也不至于死。”他们就照样做了。","notes":[]},{"n":21,"t":"他们彼此说：“我们在弟弟身上实在犯了罪。他哀求我们的时候，我们看见他的痛苦，却不肯听，所以这场苦难临到我们。”","notes":[]},{"n":22,"t":"吕便回答他们说：“我不是对你们说过，不可伤害那孩子吗？只是你们不肯听，看哪，他的血在追讨了。”","notes":[]},{"n":23,"t":"他们不知道约瑟在听，因为在他们之间有传译官。","notes":[]},{"n":24,"t":"约瑟转身离开他们，哭了一场，又回来对他们说话，就从他们中间抓了西缅，在他们眼前捆绑他。","notes":[]},{"n":25,"t":"约瑟吩咐人把他们的器皿装满粮食，把各人的银子退还在各人的袋里，又给他们路上需用的食物。人就为他们这样做了。","notes":[],"heads":["约瑟的哥哥回迦南地"]},{"n":26,"t":"他们把粮食驮在驴上，离开那里去了。","notes":[]},{"n":27,"t":"到了住宿的地方，有一个人打开袋子，要拿饲料喂驴，就看见自己的银子，看哪，仍在袋口上。","notes":[]},{"n":28,"t":"他对兄弟们说：“我的银子退回来了，看哪，还在我袋子里！”他们战战兢兢，心都快跳出来了，彼此说：“神向我们做的是什么呢？”","notes":[]},{"n":29,"t":"他们来到迦南地他们的父亲雅各那里，把所遭遇的事都告诉他，说：","notes":[]},{"n":30,"t":"“那地的主对我们说严厉的话，把我们当作窥探那地的奸细。","notes":[]},{"n":31,"t":"我们对他说：‘我们是诚实的人，并不是奸细。","notes":[]},{"n":32,"t":"我们本是兄弟十二人，都是同一个父亲的儿子，有一个不在了，最小的今日和我们父亲在迦南地。’","notes":[]},{"n":33,"t":"那地的主对我们说：‘只有这样我才知道你们是诚实的人：留你们兄弟中的一个在我这里，你们带粮食回去，救你们家的饥荒，","notes":[]},{"n":34,"t":"再把你们最小的弟弟带到我这里来，我就知道你们不是奸细，是诚实的人。然后，我就把你们的兄弟交还你们，你们也可以在此地做买卖。’”","notes":[]},{"n":35,"t":"后来他们倒空袋子，看哪，各人的银囊都在袋子里。他们和父亲看见银囊就都害怕。","notes":[]},{"n":36,"t":"他们的父亲雅各对他们说：“你们害我丧失了我的儿子：约瑟不在了，西缅也不在了，你们还要带走便雅悯！这些事都临到我身上了。”","notes":[]},{"n":37,"t":"吕便对他父亲说：“我若不带他回来给你，你可以杀我的两个儿子。只管把他交在我手里，我必带他回来给你。”","notes":[]},{"n":38,"t":"雅各说：“我的儿子不可与你们一同下去。他哥哥死了，只剩下他。他若在你们行走的路上遭难，你们就害我白发苍苍、悲悲惨惨下阴间去了。”","notes":[]}]},"43":{"heading":"约瑟的哥哥带便雅悯到埃及","verses":[{"n":1,"t":"那地的饥荒非常严重。","notes":[]},{"n":2,"t":"他们从埃及带来的粮食吃完了，父亲对他们说：“你们再去给我们买些粮来。”","notes":[]},{"n":3,"t":"犹大对他说：“那人严厉地警告我们说：‘你们的弟弟若不和你们同来，你们就不要来见我的面。’","notes":[]},{"n":4,"t":"你若派我们的弟弟跟我们同去，我们就下去给你买粮；","notes":[]},{"n":5,"t":"你若不派他去，我们就不下去，因为那人对我们说：‘你们的弟弟若不和你们同来，你们就不要来见我的面。’”","notes":[]},{"n":6,"t":"以色列说：“你们为什么这样害我，告诉那人你们还有弟弟呢？”","notes":[]},{"n":7,"t":"他们说：“那人详细问到我们和我们的家人，说：‘你们的父亲还在吗？你们还有兄弟吗？’我们就按着他的这些话告诉他，我们怎么知道他会说：‘把你们的弟弟带下来’呢？”","notes":[]},{"n":8,"t":"犹大又对他父亲以色列说：“请派这年轻人和我同去，我们就动身前去，好叫我们和你，以及我们的孩子都得存活，不至于死。","notes":[]},{"n":9,"t":"我为他担保，你可以从我手中要人，我若不带他回来交在你面前，我就对你永远担当这罪。","notes":[]},{"n":10,"t":"我们若没有耽搁，现在第二趟都回来了。”","notes":[]},{"n":11,"t":"父亲以色列对他们说：“如果必须如此，你们要这样做：把本地土产中最好的乳香、蜂蜜、香料、没药、坚果、杏仁各取一点，放在器皿里，带下去送给那人作礼物。","notes":[]},{"n":12,"t":"手里要带双倍的银子，把退还在你们袋口的银子亲手带回去；或许那是个失误。","notes":[]},{"n":13,"t":"带着你们的弟弟，动身再去见那人。","notes":[]},{"n":14,"t":"愿全能的神使你们在那人面前蒙怜悯，放你们另一个兄弟和便雅悯回来。我若要失丧儿子，就丧了吧！”","notes":[]},{"n":15,"t":"于是，他们拿着那些礼物，手里也带双倍的银子，并且带着便雅悯，动身下到埃及，站在约瑟面前。","notes":[]},{"n":16,"t":"约瑟见便雅悯和他们同来，就对管家说：“把这些人领到屋里。要宰杀牲畜，预备宴席，因为中午这些人要跟我吃饭。”","notes":[]},{"n":17,"t":"那人就照约瑟所说的去做，领他们进约瑟的屋里。","notes":[]},{"n":18,"t":"这些人因为被领到约瑟的屋里，就害怕，说：“领我们到这里来，必是因为当初退还在我们袋里的银子，要设计害我们，抓我们去当奴隶，抢夺我们的驴。”","notes":[]},{"n":19,"t":"他们就挨近约瑟的管家，在屋子门口和他说话，","notes":[]},{"n":20,"t":"说：“我主啊，求求你，我们当初下来，真的是要买粮食。","notes":[]},{"n":21,"t":"后来到了住宿的地方，我们打开袋子，看哪，各人的银子还在自己的袋口上，银子的分量一点不少。现在我们亲手把它带回来，","notes":[]},{"n":22,"t":"我们手里又带了另外的银子来买粮食。我们不知道是谁把银子放在我们袋里的。”","notes":[]},{"n":23,"t":"他说：“你们平安！不要害怕，是你们的神和你们父亲的神把财宝放在你们的袋里。你们的银子，我已经收了。”他就把西缅带出来，交给他们。","notes":[]},{"n":24,"t":"那人领这些人进约瑟的屋里，给他们水洗脚，又给他们饲料喂驴。","notes":[]},{"n":25,"t":"他们预备好礼物，等候约瑟中午来，因为他们听说他们要在那里吃饭。","notes":[]},{"n":26,"t":"约瑟来到家里，他们就把手中的礼物拿进屋里给他，俯伏在地，向他下拜。","notes":[]},{"n":27,"t":"约瑟问他们安，又说：“你们的父亲，就是你们所说的那位老人家平安吗？他还在吗？”","notes":[]},{"n":28,"t":"他们说：“你仆人，我们的父亲平安，他还在。”于是他们低头下拜。","notes":[]},{"n":29,"t":"约瑟举目看见他同母的弟弟便雅悯，就说：“你们向我所说那最小的弟弟就是这位吗？”又说：“我儿啊，愿神赐恩给你！”","notes":[]},{"n":30,"t":"约瑟爱弟之情激动，就急忙找个地方去哭。他进入自己的房间，哭了一场。","notes":[]},{"n":31,"t":"他洗了脸出来，勉强忍住，就说：“开饭吧！”","notes":[]},{"n":32,"t":"他们为约瑟单独摆了一席，为那些人又摆了一席，也为和约瑟同吃饭的埃及人另摆了一席，因为埃及人不和希伯来人一同吃饭；那是埃及人所厌恶的。","notes":[]},{"n":33,"t":"兄弟们被安排在约瑟面前坐席，都按着长幼的次序，这些人彼此感到诧异。","notes":[]},{"n":34,"t":"约瑟把他面前的食物分给他们，但便雅悯所得的比别人多五倍。他们就喝酒，和约瑟一同畅饮。","notes":[]}]},"44":{"heading":"约瑟用计留住便雅悯","verses":[{"n":1,"t":"约瑟吩咐管家说：“按照他们的驴子所能驮的，把这些人的袋子装满粮食，再把各人的银子放在各人的袋口上，","notes":[]},{"n":2,"t":"我的杯，就是那个银杯，要和买粮的银子一同放在最年轻的那个人的袋口上。”管家就照约瑟所说的话去做了。","notes":[]},{"n":3,"t":"天一亮，这些人和他们的驴子就被送走了。","notes":[]},{"n":4,"t":"他们出城走了不远，约瑟对管家说：“起来，去追那些人，追上了就对他们说：‘你们为什么以恶报善呢？","notes":[]},{"n":5,"t":"这不是我主人用来饮酒，确实用它来占卜的吗？你们这么做是不对的！’”","notes":[]},{"n":6,"t":"管家追上他们，把这些话对他们说了。","notes":[]},{"n":7,"t":"他们对他说：“我主为什么说这样的话呢？你仆人们绝不会做这样的事。","notes":[]},{"n":8,"t":"看哪，我们从前在袋口上发现的银子，尚且从迦南地带来还你，我们又怎么会从你主人家里偷窃金银呢？","notes":[]},{"n":9,"t":"你仆人中无论在谁那里找到杯子，就叫他死，我们也要作我主的奴隶。”","notes":[]},{"n":10,"t":"管家说：“现在就照你们的话做吧！在谁那里找到杯子，谁就作我的奴隶，其余的人都没有罪。”","notes":[]},{"n":11,"t":"于是他们各人急忙把袋子卸在地上，各人打开自己的袋子。","notes":[]},{"n":12,"t":"管家就搜查，从年长的开始到年幼的为止，那杯竟在便雅悯的袋子里找到了。","notes":[]},{"n":13,"t":"他们就撕裂衣服，各人把驮子抬在驴上，回城去了。","notes":[]},{"n":14,"t":"犹大和他兄弟们来到约瑟的屋里，约瑟还在那里，他们就在他面前俯伏于地。","notes":[]},{"n":15,"t":"约瑟对他们说：“你们做的是什么事呢？你们岂不知像我这样的人必懂得占卜吗？”","notes":[]},{"n":16,"t":"犹大说：“我们对我主能说什么呢？还有什么话可说呢？我们还能为自己表白吗？神已经查出你仆人的罪孽了。看哪，我们与那在他手中找到杯子的人都是我主的奴隶。”","notes":[]},{"n":17,"t":"约瑟说：“我绝不能做这样的事！谁的手中找到杯子，谁就作我的奴隶。至于你们，可以平平安安上到你们父亲那里去。”","notes":[]},{"n":18,"t":"犹大挨近他，说：“我主啊，求求你，让仆人说一句话给我主听，不要向仆人发烈怒，因为你如同法老一样。","notes":[],"heads":["犹大替便雅悯哀求"]},{"n":19,"t":"我主曾问仆人们说：‘你们有父亲、兄弟没有？’","notes":[]},{"n":20,"t":"我们对我主说：‘我们有父亲，他已经年老，还有他老年所生的一个小儿子。他哥哥死了，他的母亲只剩下他一个孩子，父亲也疼爱他。’","notes":[]},{"n":21,"t":"你对仆人说：‘把他带下到我这里来，让我亲眼看看他。’","notes":[]},{"n":22,"t":"我们对我主说：‘这年轻人不能离开他父亲，若是离开，父亲就会死。’","notes":[]},{"n":23,"t":"你对仆人说：‘你们最小的弟弟若不和你们一同下来，你们就不要来见我的面。’","notes":[]},{"n":24,"t":"我们上到你仆人，我们父亲那里，就把我主的话告诉了他。","notes":[]},{"n":25,"t":"后来，我们的父亲说：‘你们再去给我买些粮来。’","notes":[]},{"n":26,"t":"我们说：‘我们不能下去。最小的弟弟若和我们同去，我们就可以下去。因为，最小的弟弟若不和我们同去，我们必不能见那人的面。’","notes":[]},{"n":27,"t":"你仆人，我父亲对我们说：‘你们知道我的妻子给我生了两个儿子。","notes":[]},{"n":28,"t":"一个离开我走了，我说他必是被野兽撕碎了，直到如今我再没有见过他；","notes":[]},{"n":29,"t":"现在你们又要把这个从我面前带走。倘若他遭难，那么你们就害我白发苍苍、悲悲惨惨下阴间去了。’","notes":[]},{"n":30,"t":"如今我回到你仆人，我父亲那里，若没有这年轻人和我们同去，我父亲的命是与这年轻人的命相连的，","notes":[]},{"n":31,"t":"当我们的父亲看见没有了这年轻人，他就会死。这样，我们就害你仆人，我们的父亲白发苍苍、悲悲惨惨下阴间去了。","notes":[]},{"n":32,"t":"仆人曾向我父亲为这年轻人担保，说：‘我若不带他回来交给父亲，我就在父亲面前永远担当这罪。’","notes":[]},{"n":33,"t":"现在，求你把仆人留下，代替这年轻人作我主的奴隶，让这年轻人和他哥哥们一同上去。","notes":[]},{"n":34,"t":"若这年轻人不和我一起，我怎能上到我父亲那里呢？恐怕我要看到灾祸临到我父亲了。”","notes":[]}]},"45":{"heading":"约瑟和兄弟相认","verses":[{"n":1,"t":"约瑟在所有侍立在他旁边的人面前情不自禁，就喊叫说：“每一个人都离开我，出去吧！”约瑟和兄弟相认的时候没有一人站在他那里。","notes":[]},{"n":2,"t":"他放声大哭，埃及人听见了，法老家中的人也听见了。","notes":[]},{"n":3,"t":"约瑟对他兄弟们说：“我就是约瑟。我的父亲还在吗？”他兄弟们不敢回答他，因为他们在他面前都很惊惶。","notes":[]},{"n":4,"t":"约瑟又对他兄弟们说：“靠近我一点。”他们就近前来。他说：“我是被你们卖到埃及的兄弟约瑟。","notes":[]},{"n":5,"t":"现在，不要因为把我卖到这里而忧伤，对自己生气，因为神差我在你们以先来，为要保全性命。","notes":[]},{"n":6,"t":"现在这地的饥荒已经二年了，还有五年不能耕种，没有收成。","notes":[]},{"n":7,"t":"神差我在你们以先来，为要给你们在世上存留余种，大施拯救，保全你们的性命。","notes":[]},{"n":8,"t":"这样看来，差我到这里来的不是你们，而是神。他又使我如同法老之父，作他全家之主，和埃及全地掌权的人。","notes":[]},{"n":9,"t":"你们要赶紧上到我父亲那里，对他说：‘你儿子约瑟这样说：神已立我作全埃及之主，请你下到我这里来，不要耽搁。","notes":[]},{"n":10,"t":"你和你的儿子孙子，羊群牛群，以及一切所有的，都可以住在歌珊地，与我相近。","notes":[]},{"n":11,"t":"我要在那里奉养你，因为还有五年的饥荒，免得你和你的家属，以及一切所有的，都陷入穷困中。’","notes":[]},{"n":12,"t":"看哪，你们的眼睛和我弟弟便雅悯的眼睛都看见，是我亲口对你们说话。","notes":[]},{"n":13,"t":"你们要把我在埃及一切的尊荣和你们所有看见的事情都告诉我父亲，也要赶紧请我父亲下到这里来。”","notes":[]},{"n":14,"t":"于是约瑟伏在他弟弟便雅悯的颈项上哭，便雅悯也在他的颈项上哭。","notes":[]},{"n":15,"t":"他又亲众兄弟，伏着他们哭。过后，他的兄弟就和他说话。","notes":[]},{"n":16,"t":"这消息传到法老的宫里，说：“约瑟的兄弟们来了。”法老和他的臣仆眼中都看为好。","notes":[]},{"n":17,"t":"法老对约瑟说：“你要吩咐你的兄弟们说：‘你们要这样做：把驮子抬在牲口上，动身到迦南地去，","notes":[]},{"n":18,"t":"请你们的父亲和你们的家属都到我这里来，我要把埃及地的美物赐给你们，你们也要吃这地肥美的出产。’","notes":[]},{"n":19,"t":"你要吩咐他们：‘要这样做：从埃及地带着车辆去，把你们的孩子和妻子，以及你们的父亲都接来。","notes":[]},{"n":20,"t":"你们的眼不要顾惜你们的家具，因为埃及全地的美物都是你们的。’”","notes":[]},{"n":21,"t":"以色列的儿子们就照样做了。约瑟遵照法老的吩咐，给他们车辆和路上需用的食物。","notes":[]},{"n":22,"t":"他又给所有哥哥每人一套衣服， 却给便雅悯三百银子，五套衣服。","notes":[]},{"n":23,"t":"他也送给父亲十匹公驴，驮着埃及的美物，以及十匹母驴，驮着给他父亲在路上需用的谷物、饼和粮食。","notes":[]},{"n":24,"t":"于是约瑟送他的兄弟们回去，对他们说：“你们不要在路上争吵。”","notes":[]},{"n":25,"t":"他们从埃及上去，来到迦南地他们的父亲雅各那里，","notes":[]},{"n":26,"t":"告诉他说：“约瑟还活着，并且作了埃及全地掌权的人。”雅各心里冰凉，因为不信他们。","notes":[]},{"n":27,"t":"他们就把约瑟对他们所说一切的话都告诉了他。他看见约瑟派来接他的车辆，他们父亲雅各的灵就苏醒了。","notes":[]},{"n":28,"t":"以色列说：“够了！我的儿子约瑟还活着，我要趁我未死之前去见他。”","notes":[]}]},"46":{"heading":"雅各带家属到埃及","verses":[{"n":1,"t":"以色列带着一切所有的，起程到别是巴去，献祭给他父亲以撒的神。","notes":[]},{"n":2,"t":"夜间，神在异象中对以色列说：“雅各！雅各！”他说：“我在这里。”","notes":[]},{"n":3,"t":"神说：“我是神，你父亲的神。不要害怕下埃及去，因为我必使你在那里成为大国。","notes":[]},{"n":4,"t":"我要和你同下埃及去，也必定带你上来；约瑟要亲手合上你的眼睛。”","notes":[]},{"n":5,"t":"雅各就从别是巴起行。以色列的儿子让他们的父亲雅各和他们的孩子、妻子都坐在法老为雅各派来的车上。","notes":[]},{"n":6,"t":"他们也带着迦南地所得的牲畜和财物来到埃及。雅各和他所有的子孙都一同来了。","notes":[]},{"n":7,"t":"他把他的儿子、孙子、女儿、孙女，他所有的子孙一同带到埃及。","notes":[]},{"n":8,"t":"这些是来到埃及的以色列人，雅各和他子孙的名字：雅各的长子是吕便。","notes":[]},{"n":9,"t":"吕便的儿子是哈诺、法路、希斯伦、迦米。","notes":[]},{"n":10,"t":"西缅的儿子是耶母利、雅悯、阿辖、雅斤、琐辖，还有迦南女子生的儿子扫罗。","notes":[]},{"n":11,"t":"利未的儿子是革顺、哥辖、米拉利。","notes":[]},{"n":12,"t":"犹大的儿子是珥、俄南、示拉、法勒斯、谢拉；珥与俄南死在迦南地。法勒斯的儿子是希斯仑、哈母勒。","notes":[]},{"n":13,"t":"以萨迦的儿子是陀拉、普瓦、约伯、伸仑。","notes":[]},{"n":14,"t":"西布伦的儿子是西烈、以伦、雅利。","notes":[]},{"n":15,"t":"这是利亚在巴旦．亚兰为雅各所生的儿孙，还有女儿底拿，儿孙共三十三人。","notes":[]},{"n":16,"t":"迦得的儿子是洗非芸、哈基、书尼、以斯本、以利、亚罗底、亚列利。","notes":[]},{"n":17,"t":"亚设的儿子是音拿、亦施瓦、亦施韦、比利亚，还有他们的妹妹西拉。比利亚的儿子是希别、玛结。","notes":[]},{"n":18,"t":"这是拉班给他女儿利亚的婢女悉帕的儿孙，她为雅各所生的共有十六人。","notes":[]},{"n":19,"t":"雅各之妻拉结的儿子是约瑟和便雅悯。","notes":[]},{"n":20,"t":"约瑟在埃及地生了玛拿西和以法莲，是安城的祭司波提非拉的女儿亚西纳为约瑟生的。","notes":[]},{"n":21,"t":"便雅悯的儿子是比拉、比结、亚实别、基拉、乃幔、以希、罗实、母平、户平、亚勒。","notes":[]},{"n":22,"t":"这是拉结为雅各所生的儿孙，共有十四人。","notes":[]},{"n":23,"t":"但的儿子是户伸。","notes":[]},{"n":24,"t":"拿弗他利的儿子是雅薛、沽尼、耶色、示冷。","notes":[]},{"n":25,"t":"这是拉班给他女儿拉结的婢女辟拉的儿孙，她为雅各所生的共有七人。","notes":[]},{"n":26,"t":"那与雅各同到埃及的，除了他媳妇之外，凡从他生的共有六十六人。","notes":[]},{"n":27,"t":"还有约瑟在埃及所生的两个儿子。到埃及的雅各全家共有七十人。","notes":[]},{"n":28,"t":"雅各派犹大先到约瑟那里，请他先指示到歌珊去的路；于是他们来到了歌珊地。","notes":[],"heads":["雅各和家属在歌珊"]},{"n":29,"t":"约瑟备好座车，上歌珊去迎接他的父亲以色列。他见到父亲，就伏在父亲的颈项上，在父亲的颈项上哭了许久。","notes":[]},{"n":30,"t":"以色列对约瑟说：“我见了你的面，知道你还活着，现在我可以死了。”","notes":[]},{"n":31,"t":"约瑟对他兄弟和他父亲的全家说：“我要上去告诉法老，对他说：‘我在迦南地的兄弟和我父亲的全家，都到我这里来了。","notes":[]},{"n":32,"t":"他们是牧羊人，是牧放牲畜的人；他们把羊群牛群和一切所有的都带来了。’","notes":[]},{"n":33,"t":"等到法老召见你们，说：‘你们是做什么的？’","notes":[]},{"n":34,"t":"你们就说：‘你的仆人，从幼年直到现在，都是牧放牲畜的人，我们和我们的祖宗都是这样。’如此，你们就可以住在歌珊地，因为凡牧羊的都被埃及人厌恶。”","notes":[]}]},"47":{"heading":"严重的饥荒","verses":[{"n":1,"t":"约瑟进去告诉法老说：“我的父亲和我的兄弟带着羊群牛群，以及他们一切所有的，从迦南地来了。看哪，他们正在歌珊地。”","notes":[]},{"n":2,"t":"约瑟从他所有兄弟中挑选五个人，引他们到法老面前。","notes":[]},{"n":3,"t":"法老对约瑟的兄弟说：“你们是做什么的？”他们对法老说：“你仆人是牧羊的，我们和我们的祖宗都是这样。”","notes":[]},{"n":4,"t":"他们又对法老说：“迦南地的饥荒非常严重，仆人的羊群没有牧草，所以我们来到这地寄居。现在求你准许仆人住在歌珊地。”","notes":[]},{"n":5,"t":"法老对约瑟说：“你的父亲和你的兄弟到你这里来了，","notes":[]},{"n":6,"t":"埃及地都在你面前，只管让你父亲和你兄弟住在最好的地，他们可以住在歌珊地。你若知道他们中间有能干的人，就派他们看管我的牲畜。”","notes":[]},{"n":7,"t":"约瑟带他父亲雅各来，站在法老面前，雅各就为法老祝福。","notes":[]},{"n":8,"t":"法老对雅各说：“你平生的年日是多少呢？”","notes":[]},{"n":9,"t":"雅各对法老说：“我在世寄居的年日是一百三十年，我一生的岁月又短又苦，比不上我祖先在世寄居的年日。”","notes":[]},{"n":10,"t":"雅各又为法老祝福，就从法老面前退出去了。","notes":[]},{"n":11,"t":"约瑟安顿他的父亲和兄弟，遵照法老的命令，把埃及境内最好的地，就是兰塞地，给他们作为产业。","notes":[]},{"n":12,"t":"约瑟用粮食供给他父亲和兄弟们，以及他父亲全家的人，照扶养亲属的人口供给。","notes":[]},{"n":13,"t":"饥荒非常严重，全地都绝了粮，埃及地和迦南地都因饥荒耗损了。","notes":[]},{"n":14,"t":"约瑟收集了埃及地和迦南地所有的银子，就是众人买粮的银子，约瑟就把那些银子都带到法老的宫里。","notes":[]},{"n":15,"t":"埃及地和迦南地的银子都花光了，埃及众人到约瑟那里，说：“我们的银子都用完了，求你给我们粮食吧！我们为什么要死在你面前呢？”","notes":[]},{"n":16,"t":"约瑟说：“银子若是用完了，可以把你们的牲畜卖给我，我就以你们的牲畜换粮食给你们。”","notes":[]},{"n":17,"t":"于是他们把牲畜带到约瑟那里，约瑟就拿粮食换了他们的马、羊、牛、驴；那一年他因换他们一切的牲畜，用粮食养活他们。","notes":[]},{"n":18,"t":"那一年过去，第二年他们又来到约瑟那里，对他说：“不瞒我主，我们的银子都花光了，牲畜也都归于我主了。我们在我主面前，除了自己的身体和土地以外，一无所剩。","notes":[]},{"n":19,"t":"你为什么要眼看着我们人死地荒呢？求你用粮食买我们和我们的地，我们和我们的地就要为法老效力。求你给我们种子，使我们可以存活，不致死亡，土地也不致荒芜。”","notes":[]},{"n":20,"t":"于是，约瑟为法老买了埃及所有的土地，埃及人因饥荒所迫，都卖了自己的田地；那些地都归给法老了。","notes":[]},{"n":21,"t":"至于百姓，从埃及边界的一端到另一端，约瑟使他们作奴隶。","notes":["本节是根据撒玛利亚五经和七十士译本；原文是“至于百姓，约瑟把他们迁移到城镇中，从埃及边界的一端到另一端。”"]},{"n":22,"t":"只有祭司的土地，约瑟没有买，因为祭司从法老领取薪俸，靠法老的薪俸过活，所以没有卖自己的土地。","notes":[]},{"n":23,"t":"约瑟对百姓说：“看哪，我今日为法老买了你们和你们的土地。看哪，这些种子是给你们的，你们可以耕种土地。","notes":[]},{"n":24,"t":"将来收割的时候，你们要把五分之一纳给法老，另外四分可以给你们作田地的种子，作你们和你们全家大小的食物。”","notes":[]},{"n":25,"t":"他们说：“你救了我们的性命，愿我们在我主眼前蒙恩，我们情愿作法老的奴隶。”","notes":[]},{"n":26,"t":"于是约瑟为埃及的土地立下定例，直到今日，就是收成的五分之一要归法老。惟独祭司的土地例外，不归于法老。","notes":[]},{"n":27,"t":"以色列人住在埃及境内的歌珊地。他们在那里得了产业，并且生养众多。","notes":[],"heads":["雅各最后的吩咐"]},{"n":28,"t":"雅各住在埃及地十七年。雅各一生的年日是一百四十七年。","notes":[]},{"n":29,"t":"以色列的死期快到了，就叫了他儿子约瑟来，对他说：“我若在你眼前蒙恩，把你的手放在我大腿底下，以慈爱和诚实向我承诺，必不将我葬在埃及。","notes":[]},{"n":30,"t":"我与我祖先同睡的时候，你要将我带出埃及，把我葬在他们所葬的地方。”约瑟说：“我必遵照你的吩咐去做。”","notes":[]},{"n":31,"t":"雅各说：“你向我起誓吧！”约瑟就向他起了誓。于是以色列在床头敬拜。","notes":["“在床头”或译“扶着杖头”。"]}]},"48":{"heading":"雅各祝福约瑟的两个儿子","verses":[{"n":1,"t":"这些事以后，有人告诉约瑟说：“看哪，你的父亲病了。”他就带着两个儿子玛拿西和以法莲同去。","notes":[]},{"n":2,"t":"有人告诉雅各说：“看哪，你的儿子约瑟到你这里来了。”以色列就勉强在床上坐起来。","notes":[]},{"n":3,"t":"雅各对约瑟说：“全能的神曾在迦南地的路斯向我显现，赐福给我，","notes":[]},{"n":4,"t":"对我说：‘看哪，我必使你生养众多，成为许多民族，又要将这地赐给你的后裔，永远为业。’","notes":[]},{"n":5,"t":"我未到埃及你那里之前，你在埃及地所生的以法莲和玛拿西这两个儿子，现在他们是我的，正如吕便和西缅是我的一样。","notes":[]},{"n":6,"t":"你在他们以后所生的后裔就是你的，这些后裔可以在自己兄弟的名下得产业。","notes":[]},{"n":7,"t":"至于我，我从巴旦回来的时候，拉结在我身旁死了，就是在往迦南地的路上，离以法他还有一段路程。我就把她葬在往以法他的路旁；以法他就是伯利恒。”","notes":[]},{"n":8,"t":"以色列看见约瑟的儿子，就说：“这些是谁？”","notes":[]},{"n":9,"t":"约瑟对他父亲说：“这是神在这里赐给我的儿子。”以色列说：“领他们到我跟前，我要为他们祝福。”","notes":[]},{"n":10,"t":"以色列年纪老迈，眼睛昏花，不能看见。约瑟领他们到他跟前，他就和他们亲吻，抱着他们。","notes":[]},{"n":11,"t":"以色列对约瑟说：“我没有想到能够见你的面。看哪，神还让我看见你的儿子。”","notes":[]},{"n":12,"t":"约瑟把他们从以色列两膝中间领出来，自己脸伏于地下拜。","notes":[]},{"n":13,"t":"然后，约瑟牵着他们两个，带到父亲跟前，右手牵以法莲到以色列的左边，左手牵玛拿西到以色列的右边。","notes":[]},{"n":14,"t":"以色列却伸出右手来，按在次子以法莲的头上，又交叉伸出左手来，按在长子玛拿西的头上。","notes":[]},{"n":15,"t":"他就为约瑟祝福说：“愿我祖父亚伯拉罕和我父亲以撒所事奉的神，就是一生牧养我直到今日的神，","notes":[]},{"n":16,"t":"救赎我脱离一切患难的那位使者，赐福给这两个孩子。愿我的名，我祖父亚伯拉罕和我父亲以撒的名藉着他们得以流传。又愿他们在全地上多多繁衍。”","notes":[]},{"n":17,"t":"约瑟见父亲把右手按在以法莲的头上，他看为不好，就提起他父亲的手，要从以法莲的头上移到玛拿西的头上。","notes":[]},{"n":18,"t":"约瑟对父亲说：“我父，不是这样。这个才是长子，请你把右手按在他头上。”","notes":[]},{"n":19,"t":"他父亲却不肯，说：“我知道，我儿，我知道。他也要成为一族，也要强大。可是他的弟弟将来比他还要强大；他弟弟的后裔要成为许多国家。”","notes":[]},{"n":20,"t":"以色列就在当日为他们祝福，说：“以色列人要指着你们祝福，说：‘愿神使你如以法莲、玛拿西一样。’”于是他立以法莲在玛拿西之上。","notes":[]},{"n":21,"t":"以色列又对约瑟说：“看哪，我快要死了，但神必与你们同在，领你们回到你们祖先之地。","notes":[]},{"n":22,"t":"从前我用刀用弓从亚摩利人手下夺取的那一份，我要把它赐给你，使你比你的兄弟多得一份。”","notes":["“比你的兄弟多得一份”或译“使你拥有示剑城，超过你的兄弟”。"]}]},"49":{"heading":"雅各的遗言","verses":[{"n":1,"t":"雅各叫了他的儿子来，说：“你们都来聚集，让我把你们日后要遇到的事告诉你们。","notes":[]},{"n":2,"t":"雅各的儿子们，你们要聚集，要聆听，听你们父亲以色列的话。","notes":[]},{"n":3,"t":"吕便啊，你是我的长子，我的力量，我壮年头生之子，极有尊荣，权力超群。","notes":[]},{"n":4,"t":"你却放纵如水，必不得居首位；因为你上了你父亲的床，你上了我的榻，污辱了它！","notes":["“你”是根据七十士译本和其他古译本；原文是“他”。"]},{"n":5,"t":"西缅和利未是兄弟；他们的刀剑是残暴的兵器。","notes":[]},{"n":6,"t":"愿我的心不与他们同谋，愿我的灵不与他们合伙；因为他们在烈怒中杀人，任意割断牛腿的筋。","notes":["“灵”：原文是“荣耀”。"]},{"n":7,"t":"他们火爆的烈怒可诅，他们凶残的愤恨可咒！我要把他们分散在雅各中，使他们散居在以色列。","notes":[]},{"n":8,"t":"犹大啊，你的兄弟必赞美你，你的手必掐住仇敌的颈项，你父亲的儿子要向你下拜。","notes":[]},{"n":9,"t":"犹大是只小狮子；我儿啊，你捕获了猎物就上去。他蹲伏，他躺卧，如公狮，又如母狮，谁敢惹他呢？","notes":[]},{"n":10,"t":"权杖必不离犹大，统治者的杖必不离他两脚之间，直等细罗来到，万民都要归顺他。","notes":["“细罗”意思不清楚，可指“贡物”或“那应得权杖者”。"]},{"n":11,"t":"犹大把小驴拴在葡萄树上，把驴驹拴在佳美的葡萄树上。他在葡萄酒中洗衣服，在葡萄汁中洗长袍。","notes":["“汁”：原文是“血”。"]},{"n":12,"t":"他的眼睛比酒红润，他的牙齿比奶洁白。","notes":["“比”或译“因”；下同。"]},{"n":13,"t":"西布伦必住在海边，必成为停船的港口；他的疆界必延到西顿。","notes":[]},{"n":14,"t":"以萨迦是匹强壮的驴，卧在羊圈之中。","notes":[]},{"n":15,"t":"他看见居所安舒，土地肥美，就屈肩负重，成为服劳役的仆人。","notes":[]},{"n":16,"t":"但必为他的百姓伸冤，作为以色列支派之一。","notes":["“伸冤”与“但”的希伯来话发音相近。"]},{"n":17,"t":"但必作道旁的蛇，路边的毒蛇，咬伤马蹄，使骑马的人向后坠落。","notes":[]},{"n":18,"t":"耶和华啊，我等候你的救恩。","notes":[]},{"n":19,"t":"迦得必被袭击者袭击，他却要袭击他们的脚跟。","notes":["“袭击”与“迦得”的希伯来话发音相近。"]},{"n":20,"t":"亚设必出丰盛的粮食，要供应君王的佳肴。","notes":[]},{"n":21,"t":"拿弗他利是被释放的母鹿，他要生出可爱的小鹿。","notes":["“可爱的小鹿”或译“佳美的言语”。"]},{"n":22,"t":"约瑟是多结果子的树枝，是泉旁多结果的枝子；他的枝条伸出墙外。","notes":[]},{"n":23,"t":"弓箭手恶意攻击他，敌对他，向他射箭。","notes":[]},{"n":24,"t":"但他的弓仍旧坚硬，他的手臂灵活敏捷，这是因雅各的大能者的手，从那里，他是以色列的牧者，以色列的磐石。","notes":["“从那里...磐石”：原文另译“因为以色列的牧者，以色列的磐石的名”；七十士译本是“从那里他降服了以色列”。"]},{"n":25,"t":"你父亲的神必帮助你；全能者必赐福给你：天上的福，深渊下面蕴藏的福，以及生育哺养的福。","notes":[]},{"n":26,"t":"你父亲的福胜过我祖先的福，直到永世山岭的极限。这些福必降在约瑟的头上，临到那与兄弟有分别之人的头顶上。","notes":[]},{"n":27,"t":"便雅悯是只抓撕掠物的狼，早晨要吃他的猎物，晚上要分他的掳物。”","notes":[]},{"n":28,"t":"这一切是以色列的十二个支派。这是他们的父亲对他们所说的话，他按照各人的福分为他们祝福。","notes":[]},{"n":29,"t":"他又吩咐他们说：“我快要归到我祖先那里。你们要将我葬在赫人以弗仑田间的洞里，与我的祖先在一处，","notes":["“我祖先”：原文是“我百姓”。"],"heads":["雅各的死和安葬"]},{"n":30,"t":"就是在迦南地幔利对面的麦比拉田间的洞里，那田是亚伯拉罕向赫人以弗仑买来作坟地的产业。","notes":[]},{"n":31,"t":"亚伯拉罕和他的妻子撒拉葬在那里；以撒和他的妻子利百加也葬在那里。我也在那里葬了利亚。","notes":[]},{"n":32,"t":"那块田和田间的洞是向赫人买的。”","notes":[]},{"n":33,"t":"雅各嘱咐众子完毕后，就把脚收在床上断了气，归到他祖先那里去了。","notes":["“他祖先”：原文是“他百姓”。"]}]},"50":{"heading":"约瑟安慰哥哥们","verses":[{"n":1,"t":"约瑟伏在他父亲的脸上，在他脸上哭，又亲他。","notes":[]},{"n":2,"t":"约瑟吩咐伺候他的医生们用香料涂他父亲，医生就用香料涂了以色列。","notes":[]},{"n":3,"t":"四十天满了，就是涂香料所规定的日子满了。埃及人为他哀哭了七十天。","notes":[]},{"n":4,"t":"过了哀悼的日子，约瑟对法老家中的人说：“我若在你们眼前蒙恩，请你们对法老说：","notes":[]},{"n":5,"t":"‘我父亲曾叫我起誓说：看哪，我快要死了，你要将我葬在迦南地，在我为自己所掘的坟墓里。’现在求你准我上去葬我父亲，然后我必回来。”","notes":[]},{"n":6,"t":"法老说：“你可以上去，照你父亲叫你起的誓，将他安葬。”","notes":[]},{"n":7,"t":"于是约瑟上去葬他父亲。与他一同上去的有法老的众臣仆和法老家中的长老，以及埃及地所有的长老，","notes":[]},{"n":8,"t":"还有约瑟的全家和他的兄弟们，以及他父亲的家属；只留下他们的孩子和羊群牛群在歌珊地。","notes":[]},{"n":9,"t":"又有车辆和驾驶兵和他一同上去，队伍非常庞大。","notes":[]},{"n":10,"t":"他们到了约旦河东亚达的禾场，就在那里大大地号啕痛哭。约瑟为他父亲哀哭了七天。","notes":[]},{"n":11,"t":"迦南的居民看见亚达禾场上的哀哭，就说：“这是埃及人一场极大的哀哭。”因此那地方名叫亚伯．麦西，是在约旦河东。","notes":["“亚伯．麦西”意思是“埃及人的哀哭”。"]},{"n":12,"t":"雅各的儿子们遵照父亲的吩咐去办了，","notes":[]},{"n":13,"t":"他们把他送到迦南地，葬在幔利对面的麦比拉田间的洞里；那田是亚伯拉罕向赫人以弗仑买来作坟地的产业。","notes":[]},{"n":14,"t":"约瑟葬了他父亲以后，就和他的兄弟，以及所有同他上去葬他父亲的人，都回埃及去了。","notes":[]},{"n":15,"t":"约瑟的哥哥们见父亲死了，就说：“也许约瑟仍然怀恨我们，会照我们从前待他一切的恶，重重报复我们。”","notes":[]},{"n":16,"t":"他们就传口信给约瑟说：“你父亲未死之前曾吩咐说：","notes":[]},{"n":17,"t":"‘你们要对约瑟这样说：从前你哥哥们恶待你，你要饶恕他们的过犯和罪恶。’现在求你饶恕你父亲的神之仆人们的过犯。”他们对约瑟说了这话，约瑟就哭了。","notes":[]},{"n":18,"t":"他的哥哥们又来俯伏在他面前，说：“看哪，我们是你的奴隶。”","notes":[]},{"n":19,"t":"约瑟对他们说：“不要怕，我岂能代替神呢？","notes":[]},{"n":20,"t":"从前你们的意思是要害我，但神的意思原是好的，要使许多百姓得以存活，成就今日的光景。","notes":[]},{"n":21,"t":"现在你们不要害怕，我必养活你们和你们的孩子。”于是约瑟安慰他们，讲了使他们安心的话。","notes":[]},{"n":22,"t":"约瑟和他父亲的家属都住在埃及。约瑟活了一百一十年。","notes":[],"heads":["约瑟的死"]},{"n":23,"t":"约瑟看到以法莲第三代的子孙。玛拿西的孙子，玛吉的儿子，出生时都放在约瑟的膝上。","notes":[]},{"n":24,"t":"约瑟对他的兄弟说：“我快要死了，但神必定看顾你们，领你们从这地上去，到他起誓应许给亚伯拉罕、以撒、雅各之地。”","notes":[]},{"n":25,"t":"约瑟叫以色列的子孙起誓：“神必定眷顾你们，你们要把我的骸骨从这里带上去。”","notes":[]},{"n":26,"t":"约瑟死了，那时他一百一十岁。人用香料涂了他，把他收殓在棺材里，停放在埃及。","notes":[]}]}},"EXO":{"1":{"heading":"以色列人生养众多","verses":[{"n":1,"t":"以色列的众儿子各带着家眷，和雅各一同来到埃及，他们的名字如下：","notes":[]},{"n":2,"t":"吕便、西缅、利未、犹大、","notes":[]},{"n":3,"t":"以萨迦、西布伦、便雅悯、","notes":[]},{"n":4,"t":"但、拿弗他利、迦得、亚设。","notes":[]},{"n":5,"t":"凡从雅各生的，共有七十人。那时，约瑟已经在埃及。","notes":[]},{"n":6,"t":"约瑟和他所有的兄弟，以及那一代的人都死了。","notes":[]},{"n":7,"t":"然而，以色列人生养众多，繁衍昌盛，极其强盛，遍满了那地。","notes":[]},{"n":8,"t":"有一位不认识约瑟的新王兴起，统治埃及。","notes":[],"heads":["以色列人受虐待"]},{"n":9,"t":"他对自己的百姓说：“看哪，以色列人的百姓比我们还多，又比我们强盛。","notes":[]},{"n":10,"t":"来吧，让我们机巧地待他们，恐怕他们增多起来，将来若有战争，他们就联合我们的仇敌来攻击我们，然后离开这地去了。”","notes":[]},{"n":11,"t":"于是埃及人派监工管辖他们，用劳役苦待他们。他们为法老建造储货城，就是比东和兰塞。","notes":[]},{"n":12,"t":"可是越苦待他们，他们就越发增多，更加繁衍，埃及人就因以色列人愁烦。","notes":[]},{"n":13,"t":"埃及人严厉地强迫以色列人做工，","notes":[]},{"n":14,"t":"使他们因苦工而生活痛苦；无论是和泥，是做砖，是做田间各样的工，一切的工埃及人都严厉地对待他们。","notes":[]},{"n":15,"t":"埃及王又对希伯来的接生婆，一个名叫施弗拉，另一个名叫普阿的说：","notes":[]},{"n":16,"t":"“你们为希伯来妇人接生，临盆的时候要注意，若是男的，就把他杀了，若是女的，就让她活。”","notes":["“临盆的时候要注意”：原文直译“要注意那石凳”或“要注意那两颗石头”。"]},{"n":17,"t":"但是接生婆敬畏神，不照埃及王的吩咐去做，却让男孩活着。","notes":[]},{"n":18,"t":"埃及王召了接生婆来，对她们说：“你们为什么做这事，让男孩活着呢？”","notes":[]},{"n":19,"t":"接生婆对法老说：“因为希伯来妇人与埃及妇人不同；希伯来妇人健壮，接生婆还没有到，她们已经生产了。”","notes":[]},{"n":20,"t":"神恩待接生婆；以色列人增多起来，极其强盛。","notes":[]},{"n":21,"t":"接生婆因为敬畏神，神就叫她们成立家室。","notes":[]},{"n":22,"t":"法老吩咐他的众百姓说：“把所生的每一个男孩都丢到尼罗河里去，让所有的女孩存活。”","notes":["“所生的”：有些古卷、七十士译本和其他古译本是“希伯来人所生的”。"]}]},"2":{"heading":"摩西的出生","verses":[{"n":1,"t":"有一个利未家的人娶了一个利未女子为妻。","notes":[]},{"n":2,"t":"那女人怀孕，生了一个儿子，见他俊美，就把他藏了三个月，","notes":[]},{"n":3,"t":"后来不能再藏，就取了一个蒲草箱，抹上柏油和树脂，将孩子放在里面，把箱子搁在尼罗河边的芦苇中。","notes":[]},{"n":4,"t":"孩子的姊姊远远站着，要知道他究竟会怎样。","notes":[]},{"n":5,"t":"法老的女儿来到尼罗河边洗澡，她的女仆们在河边行走。她看见在芦苇中的箱子，就派一个使女把它拿来。","notes":[]},{"n":6,"t":"她打开箱子，看见那孩子。看哪，男孩在哭，她就可怜他，说：“这是希伯来人的一个孩子。”","notes":[]},{"n":7,"t":"孩子的姊姊对法老的女儿说：“我去叫一个希伯来妇人来作奶妈，替你乳养这孩子，好吗？”","notes":[]},{"n":8,"t":"法老的女儿对她说：“去吧！”那女孩就去叫了孩子的母亲来。","notes":[]},{"n":9,"t":"法老的女儿对她说：“你把这孩子抱去，替我乳养这孩子，我必给你工钱。”那妇人就把孩子接过来，乳养他。","notes":[]},{"n":10,"t":"孩子长大了，妇人把他带到法老的女儿那里，就作了她的儿子。她给孩子起名叫摩西，说：“因我把他从水里拉出来。”","notes":[]},{"n":11,"t":"过了一段日子，摩西长大了，他出去到他同胞那里，看见他们的劳役。他看见一个埃及人打他的同胞，一个希伯来人。","notes":[],"heads":["摩西逃往米甸"]},{"n":12,"t":"他左右观看，见没有人，就把埃及人打死了，藏在沙土里。","notes":[]},{"n":13,"t":"第二天他出去，看哪，有两个希伯来人在打架，他就对那凶恶的人说：“你为什么打你同族的人呢？”","notes":[]},{"n":14,"t":"那人说：“谁立你作我们的领袖和审判官呢？难道你要杀我，像杀那埃及人一样吗？”摩西就惧怕，说：“这事一定是让人知道了。”","notes":[]},{"n":15,"t":"法老听见这事，就设法要杀摩西。于是摩西逃走，躲避法老，到了米甸地，坐在井旁。","notes":[]},{"n":16,"t":"米甸的祭司有七个女儿；她们来打水，打满了槽，要给父亲的羊群喝水。","notes":[]},{"n":17,"t":"有一些牧羊人来，把她们赶走，摩西却起来帮助她们，取水给她们的羊群喝。","notes":[]},{"n":18,"t":"她们回到父亲流珥那里；他说：“今日你们为何这么快就回来了呢？”","notes":[]},{"n":19,"t":"她们说：“有一个埃及人来救我们脱离牧羊人的手，他甚至打水给我们的羊群喝。”","notes":[]},{"n":20,"t":"他对女儿们说：“那人在哪里？你们为什么撇下他呢？去请他来吃饭吧！”","notes":[]},{"n":21,"t":"摩西愿意和那人同住， 那人就把女儿西坡拉给摩西为妻。","notes":[]},{"n":22,"t":"西坡拉生了一个儿子，摩西给他起名叫革舜，因他说：“我在外地作了寄居者。”","notes":[]},{"n":23,"t":"过了许多年，埃及王死了。以色列人因做苦工，就叹息哀求；他们因苦工所发出的哀声达于神。","notes":[]},{"n":24,"t":"神听见他们的哀声，就记念他与亚伯拉罕、以撒、雅各所立的约。","notes":[]},{"n":25,"t":"神看顾以色列人，神是知道的。","notes":["“神是知道的”：七十士译本是“神是他们所知道的”。"]}]},"3":{"heading":"神呼召摩西","verses":[{"n":1,"t":"摩西牧放他岳父米甸祭司叶特罗的羊群，他领羊群往旷野的那一边去，到了神的山，就是何烈山。","notes":[]},{"n":2,"t":"耶和华的使者在荆棘的火焰中向他显现。摩西观看，看哪，荆棘在火中焚烧，却没有烧毁。","notes":[]},{"n":3,"t":"摩西说：“我要转过去看这大异象，这荆棘为何没有烧毁呢？”","notes":[]},{"n":4,"t":"耶和华见摩西转过去看，神就从荆棘里呼叫他说：“摩西！摩西！”他说：“我在这里。”","notes":[]},{"n":5,"t":"神说：“不要靠近这里。把你脚上的鞋脱下来，因为你所站的地方是圣地”。","notes":[]},{"n":6,"t":"他又说：“我是你父亲的神，是亚伯拉罕的神，以撒的神，雅各的神。”摩西蒙上脸，因为怕看神。","notes":[]},{"n":7,"t":"耶和华说：“我确实看见了我百姓在埃及所受的困苦，我也听见了他们因受监工苦待所发的哀声；我确实知道他们的痛苦。","notes":[]},{"n":8,"t":"我下来是要救他们脱离埃及人的手，领他们从那地上来，到美好与宽阔之地，到流奶与蜜之地，就是迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人之地。","notes":[]},{"n":9,"t":"现在，看哪，以色列人的哀声达到我这里，我也看见埃及人怎样欺压他们。","notes":[]},{"n":10,"t":"现在，你去，我要差派你到法老那里，把我的百姓以色列人从埃及领出来。”","notes":[]},{"n":11,"t":"摩西对神说：“我是什么人，竟能去见法老，把以色列人从埃及领出来呢？”","notes":[]},{"n":12,"t":"神说：“我必与你同在。这就是我差派你去，给你的凭据：你把百姓从埃及领出来之后，你们必在这山上事奉神。”","notes":[]},{"n":13,"t":"摩西对神说：“看哪，我到以色列人那里，对他们说：‘你们祖宗的神差派我到你们这里来。’他们若对我说：‘他叫什么名字？’我要对他们说什么呢？”","notes":[]},{"n":14,"t":"神对摩西说：“我是自有永有的”；又说：“你要对以色列人这样说：‘那自有永有的差派我到你们这里来。’”","notes":[]},{"n":15,"t":"神又对摩西说：“你要对以色列人这样说：‘耶和华－你们祖宗的神，就是亚伯拉罕的神，以撒的神，雅各的神差派我到你们这里来。’这是我的名，直到永远；这也是我的称号，直到万代。","notes":["“称号”或译“纪念”。"]},{"n":16,"t":"你去召集以色列的长老，对他们说：‘耶和华－你们祖宗的神，就是亚伯拉罕的神，以撒的神，雅各的神向我显现，说：我实在眷顾了你们，眷顾你们在埃及的遭遇。","notes":[]},{"n":17,"t":"我也曾说：要把你们从埃及的困苦中领出来，往迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人的地去，就是到流奶与蜜之地。’","notes":[]},{"n":18,"t":"他们必听你的话。你和以色列的长老要到埃及王那里，对他说：‘耶和华－希伯来人的神向我们显现，现在求你让我们往旷野去，走三天的路程，为要向耶和华我们的神献祭。’","notes":[]},{"n":19,"t":"我知道若不用大能的手，埃及王不会放你们走。","notes":[]},{"n":20,"t":"因此，我必伸出我的手，在埃及施行我一切的神迹，击打这地，然后，他才放你们走。","notes":[]},{"n":21,"t":"我必使埃及人看得起你们，你们离开的时候就不至于空手而去。","notes":[]},{"n":22,"t":"每一个妇女必向她的邻舍，以及寄居在她家里的女人，索取金器、银器和衣裳，给你们的儿女穿戴。这样你们就掠夺了埃及人。”","notes":[]}]},"4":{"heading":"摩西行神迹的权能","verses":[{"n":1,"t":"摩西回答说：“看哪！他们不会信我，也不会听我的话，因为他们必说：‘耶和华并没有向你显现。’”","notes":[]},{"n":2,"t":"耶和华对摩西说：“你手里的是什么？”他说：“是杖。”","notes":[]},{"n":3,"t":"耶和华说：“把它丢在地上！”他一丢在地上，杖就变成一条蛇；摩西逃走避开它。","notes":[]},{"n":4,"t":"耶和华对摩西说：“伸出手来，拿住它的尾巴─摩西就伸出手，抓住它，它就在摩西的手掌中变为杖─","notes":[]},{"n":5,"t":"为了要使他们信耶和华他们祖宗的神，就是亚伯拉罕的神，以撒的神，雅各的神，曾向你显现了。”","notes":[]},{"n":6,"t":"耶和华又对他说：“把手放进怀里。”他就把手放进怀里。当他把手抽出来，看哪，手竟然长了麻风，像雪一样白。","notes":["“麻风”泛指传染性皮肤病。"]},{"n":7,"t":"耶和华说：“把手放回怀里─他就把手放回怀里。当他把手从怀里再抽出来，看哪，手复原了，与全身的肉一样─","notes":[]},{"n":8,"t":"倘若他们不信你，也不听第一个神迹的声音，他们会信第二个神迹的声音。","notes":[]},{"n":9,"t":"倘若他们不信这两个神迹，不听你的话，你就从尼罗河里取些水，倒在干的地上。你从尼罗河里所取的水必在干地上变成血。”","notes":[]},{"n":10,"t":"摩西对耶和华说：“主啊，求求你，我并不是一个能言善道的人，以前这样，就是你对仆人说话以后也是这样，因为我是拙口笨舌的。”","notes":[]},{"n":11,"t":"耶和华对他说：“谁造人的口呢？谁使人口哑、耳聋、目明、眼瞎呢？岂不是我－耶和华吗？","notes":[]},{"n":12,"t":"现在，去吧，我必赐你口才，指教你应当说的。”","notes":[]},{"n":13,"t":"摩西说：“主啊，求求你，你要藉着谁的手，就差派谁去吧！”","notes":[]},{"n":14,"t":"耶和华的怒气向摩西发作，说：“你不是有一个哥哥利未人亚伦吗？我知道他是个能言善道的人。看哪，他正出来迎接你。他一见到你，心里就欢喜。","notes":[]},{"n":15,"t":"你要跟他说话，把话放在他的口里，我要赐你口才，也要赐他口才，又要教你们做当做的事。","notes":[]},{"n":16,"t":"他要替你向百姓说话；他要当你的口，你要当他的神。","notes":[]},{"n":17,"t":"你手里要拿这杖，用它来行神迹。”","notes":[]},{"n":18,"t":"于是，摩西回到他岳父叶特罗那里，对他说：“请你让我回埃及我同胞那里，看他们还在不在。”叶特罗对摩西说：“平平安安地去吧！”","notes":[],"heads":["摩西返回埃及"]},{"n":19,"t":"耶和华在米甸对摩西说：“你要回埃及去，因为那些寻索你命的人都死了。”","notes":[]},{"n":20,"t":"摩西就带着妻子和两个儿子，让他们骑上驴，回埃及地去。摩西手里拿着神的杖。","notes":[]},{"n":21,"t":"耶和华对摩西说：“你回到埃及去的时候，要留意将我交在你手中的一切奇事行在法老面前。但我要任凭他的心刚硬，他必不放百姓走。","notes":[]},{"n":22,"t":"你要对法老说：‘耶和华如此说：以色列是我的儿子，我的长子。","notes":[]},{"n":23,"t":"我对你说过：放我的儿子走，好事奉我。你还是不肯放他走。看哪，我要杀你头生的儿子。’”","notes":[]},{"n":24,"t":"在路上住宿的地方，耶和华遇见摩西，想要杀他。","notes":[]},{"n":25,"t":"西坡拉就拿一块火石，割下她儿子的包皮，碰触摩西的脚，说：“你真是我血的新郎了。”","notes":["“碰触...新郎了。”或译“碰触她儿子的脚，说：‘你真是我受割礼的孩子了。’”"]},{"n":26,"t":"这样，耶和华才放了他。那时，西坡拉说：“你因割礼就是血的新郎了”。","notes":["“血的新郎”或译“受割礼的孩子”。"]},{"n":27,"t":"耶和华对亚伦说：“你往旷野去迎接摩西。”他就去，在神的山遇见摩西，就亲他。","notes":[]},{"n":28,"t":"摩西将耶和华差派他所说的话和吩咐他所行的神迹都告诉了亚伦。","notes":[]},{"n":29,"t":"摩西和亚伦就去召集以色列的众长老。","notes":[]},{"n":30,"t":"亚伦将耶和华对摩西所说的一切话述说了一遍，又在百姓眼前行了那些神迹，","notes":[]},{"n":31,"t":"百姓就信了。他们听见耶和华眷顾以色列人，鉴察他们的困苦，就低头敬拜。","notes":[]}]},"5":{"heading":"摩西和亚伦见埃及法老","verses":[{"n":1,"t":"后来，摩西和亚伦去对法老说：“耶和华－以色列的神这样说：‘放我的百姓走，好让他们在旷野向我守节。’”","notes":[]},{"n":2,"t":"法老说：“耶和华是谁，要我听他的话，让以色列人去？我不认识耶和华，也不放以色列人走！”","notes":[]},{"n":3,"t":"他们说：“希伯来人的神已向我们显现了。求你让我们往旷野去，走三天的路程，向耶和华我们的神献祭，免得他用瘟疫、刀剑攻击我们。”","notes":[]},{"n":4,"t":"埃及王对他们说：“摩西、亚伦！你们为什么叫百姓不做工呢？去，服你们的劳役吧！”","notes":[]},{"n":5,"t":"他又说：“看哪，这地的以色列人如今这么多，你们竟然叫他们歇下劳役！”","notes":[]},{"n":6,"t":"当天，法老吩咐监工和工头说：","notes":[]},{"n":7,"t":"“你们不可照以前一样提供草给百姓做砖，要叫他们自己去捡草。","notes":[]},{"n":8,"t":"他们平时做砖的数目，你们仍旧向他们要，一点不可减少，因为他们是懒惰的，所以才呼求说：‘让我们去向我们的神献祭。’","notes":[]},{"n":9,"t":"你们要把更重的工作加在这些人身上，使他们在其中劳碌，不去理会谎言。”","notes":[]},{"n":10,"t":"监工和工头出来对百姓说：“法老这样说：‘我不给你们草，","notes":[]},{"n":11,"t":"你们自己在哪里能找到草，就往哪里去找吧！但你们的工作一点也不可减少。’”","notes":[]},{"n":12,"t":"于是，百姓分散在埃及全地，捡碎秸当草用。","notes":[]},{"n":13,"t":"监工催逼他们，说：“你们每天要做完一天的工，与先前有草一样。”","notes":[]},{"n":14,"t":"法老的监工击打他们所派的以色列工头，说：“为什么昨天和今天你们没有按照以前做砖的数目，完成你们的工作呢？”","notes":[]},{"n":15,"t":"以色列人的工头来哀求法老说：“为什么这样待你的仆人呢？","notes":[]},{"n":16,"t":"监工不把草给仆人，并且对我们说：‘做砖吧！’看哪，你仆人挨了打，其实是你百姓的错。”","notes":[]},{"n":17,"t":"法老却说：“懒惰，你们真是懒惰！所以你们说：‘让我们去向耶和华献祭吧。’","notes":[]},{"n":18,"t":"现在，去做工吧！草是不会给你们，砖却要如数交纳。”","notes":[]},{"n":19,"t":"以色列人的工头听见“你们每天做砖的工作一点也不可减少”，就知道惹上祸了。","notes":[]},{"n":20,"t":"他们离开法老出来，正遇见摩西和亚伦站在那里等候他们，","notes":[]},{"n":21,"t":"就向他们说：“愿耶和华鉴察你们，施行判断，因为你们使我们在法老和他臣仆面前有了臭名，把刀递在他们手中来杀我们。”","notes":[]},{"n":22,"t":"摩西回到耶和华那里，说：“主啊，你为什么苦待这百姓呢？为什么差派我呢？","notes":[]},{"n":23,"t":"自从我到法老那里，奉你的名说话，他就苦待这百姓，你却一点也没有拯救你的百姓。”","notes":[]}]},"6":{"heading":"神应许拯救以色列","verses":[{"n":1,"t":"耶和华对摩西说：“现在你必看见我向法老所行的事，使他因我大能的手放以色列人走，因我大能的手把他们赶出他的地。”","notes":[]},{"n":2,"t":"神吩咐摩西，对他说：“我是耶和华。","notes":[]},{"n":3,"t":"我从前向亚伯拉罕、以撒、雅各显现为全能的神；至于我的名耶和华，我未曾让他们知道。","notes":[]},{"n":4,"t":"我要与他们坚立我的约，要把迦南地，他们寄居的地赐给他们。","notes":[]},{"n":5,"t":"我听见以色列人被埃及人奴役的哀声，我就记念我的约。","notes":[]},{"n":6,"t":"所以你要对以色列人说：‘我是耶和华；我要除去埃及人加给你们的劳役，救你们脱离他们的奴役。我要用伸出来的膀臂，藉严厉的惩罚救赎你们。","notes":[]},{"n":7,"t":"我要以你们为我的百姓，我也要作你们的神。我除去埃及人加给你们的劳役，你们就知道我是耶和华你们的神。","notes":[]},{"n":8,"t":"我起誓应许给亚伯拉罕、以撒、雅各的地，我要领你们进去，将那地赐给你们为业。我是耶和华。’”","notes":[]},{"n":9,"t":"摩西把这话告诉以色列人，但是他们因心里愁烦，又因苦工，就不肯听摩西的话。","notes":[]},{"n":10,"t":"耶和华吩咐摩西说：","notes":[]},{"n":11,"t":"“你去对埃及王法老说，让以色列人离开他的地。”","notes":[]},{"n":12,"t":"摩西在耶和华面前说：“看哪，以色列人尚且不听我，法老怎么会听我这不会讲话的人呢？”","notes":[]},{"n":13,"t":"耶和华吩咐摩西和亚伦，命令他们到以色列人和埃及王法老那里，把以色列人从埃及地领出来。","notes":[]},{"n":14,"t":"以色列人族长的名字如下：以色列长子吕便的儿子是哈诺、法路、希斯伦、迦米；这是吕便的家族。","notes":[],"heads":["亚伦和摩西的家谱"]},{"n":15,"t":"西缅的儿子是耶母利、雅悯、阿辖、雅斤、琐辖，和迦南女子生的儿子扫罗；这是西缅的家族。","notes":[]},{"n":16,"t":"以下是利未的儿子按着家谱的名字：革顺、哥辖、米拉利。利未一生的岁数是一百三十七岁。","notes":[]},{"n":17,"t":"革顺的儿子按着家族是立尼、示每。","notes":[]},{"n":18,"t":"哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛。哥辖一生的岁数是一百三十三岁。","notes":[]},{"n":19,"t":"米拉利的儿子是抹利和母示；这是利未按着家谱的家族。","notes":[]},{"n":20,"t":"暗兰娶了他父亲的妹妹约基别为妻，她为他生了亚伦和摩西。暗兰一生的岁数是一百三十七岁。","notes":[]},{"n":21,"t":"以斯哈的儿子是可拉、尼斐、细基利。","notes":[]},{"n":22,"t":"乌薛的儿子是米沙利、以利撒反、西提利。","notes":[]},{"n":23,"t":"亚伦娶了亚米拿达的女儿，拿顺的妹妹，以利沙巴为妻，她为他生了拿答、亚比户、以利亚撒、以他玛。","notes":[]},{"n":24,"t":"可拉的儿子是亚惜、以利加拿、亚比亚撒；这是可拉的家族。","notes":[]},{"n":25,"t":"亚伦的儿子以利亚撒娶了普铁的一个女儿为妻，她为他生了非尼哈。这是利未人按着家族的族长。","notes":[]},{"n":26,"t":"这就是曾听见耶和华说“把以色列人按着队伍从埃及地领出来”的亚伦和摩西，","notes":[]},{"n":27,"t":"对埃及王法老说要将以色列人从埃及领出来的，也是这摩西和亚伦。","notes":[]},{"n":28,"t":"当耶和华在埃及地对摩西说话的时候，","notes":[],"heads":["摩西和亚伦奉命去见法老"]},{"n":29,"t":"耶和华对摩西说：“我是耶和华；我对你所说的一切话，你都要告诉埃及王法老。”","notes":[]},{"n":30,"t":"摩西在耶和华面前说：“看哪，我是不会讲话的人，法老怎么会听我呢？”","notes":[]}]},"7":{"heading":"亚伦的杖","verses":[{"n":1,"t":"耶和华对摩西说：“我使你在法老面前像神一样，你的哥哥亚伦是你的代言人。","notes":["“代言人”：原文是“先知”。"]},{"n":2,"t":"凡我所吩咐你的，你都要说。你的哥哥亚伦要对法老说，让以色列人离开他的地。","notes":[]},{"n":3,"t":"我要使法老的心固执，我也要在埃及地多行神迹奇事。","notes":[]},{"n":4,"t":"法老必不听从你们，因此我要伸手严厉地惩罚埃及，把我的军队，就是我的百姓以色列人从埃及地领出来。","notes":[]},{"n":5,"t":"我伸手攻击埃及，把以色列人从他们中间领出来的时候，埃及人就知道我是耶和华。”","notes":[]},{"n":6,"t":"摩西和亚伦就去做；他们照耶和华吩咐的去做了。","notes":[]},{"n":7,"t":"摩西和亚伦与法老说话的时候，摩西八十岁，亚伦八十三岁。","notes":[]},{"n":8,"t":"耶和华对摩西和亚伦说：","notes":[]},{"n":9,"t":"“法老若吩咐你们说：‘你们行一件奇事吧！’你就对亚伦说：‘把杖丢在法老面前！杖会变成蛇。’”","notes":[]},{"n":10,"t":"摩西和亚伦到法老那里去，照耶和华所吩咐的去做。亚伦把杖丢在法老和他臣仆面前，杖就变成蛇。","notes":[]},{"n":11,"t":"法老也召了智慧人和行邪术的人来，这些埃及术士也用邪术照样做。","notes":[]},{"n":12,"t":"他们各人丢下自己的杖，杖就变成蛇；但亚伦的杖吞了他们的杖。","notes":[]},{"n":13,"t":"法老心里刚硬，不听摩西和亚伦，正如耶和华所说的。","notes":[]},{"n":14,"t":"耶和华对摩西说：“法老心硬，不肯放百姓走。","notes":[],"heads":["第一灾：水变血"]},{"n":15,"t":"明天早晨你要到法老那里去，看哪，他出来往水边去，你要到尼罗河边去迎见他，手里拿着那根变过蛇的杖。","notes":[]},{"n":16,"t":"你要对他说：‘耶和华－希伯来人的神差派我到你这里，说：放我的百姓走，到旷野事奉我。看哪，到如今你还是不听。","notes":[]},{"n":17,"t":"耶和华如此说：看哪，我要用我手里的杖击打尼罗河中的水，水就变成血；这样，你就知道我是耶和华。","notes":[]},{"n":18,"t":"河里的鱼必死，河也要发臭，埃及人就厌恶喝这河里的水。’”","notes":[]},{"n":19,"t":"耶和华对摩西说：“你要对亚伦说：‘拿你的杖，伸出你的手在埃及所有的水上，在他们的江、河、池塘，所有水聚集的地方上，叫水变成血。在埃及全地，无论在木器中，石器中，都必有血。’”","notes":[]},{"n":20,"t":"摩西和亚伦就照耶和华所吩咐的去做。亚伦在法老和他臣仆眼前举杖击打尼罗河里的水，河里的水都变成血了。","notes":[]},{"n":21,"t":"河里的鱼死了，河也臭了，埃及人就不能喝这河里的水；埃及遍地都有了血。","notes":[]},{"n":22,"t":"但是，埃及的术士也用邪术照样做了；法老心里刚硬，不听摩西和亚伦，正如耶和华所说的。","notes":[]},{"n":23,"t":"法老转身回宫去，并不把这事放在心上。","notes":[]},{"n":24,"t":"所有的埃及人都沿着尼罗河边挖掘，要找水喝，因为他们不能喝河里的水。","notes":[]},{"n":25,"t":"耶和华击打尼罗河后，过了七天。","notes":[]}]},"8":{"heading":"第二灾：蛙灾","verses":[{"n":1,"t":"耶和华对摩西说：“你要到法老那里，对他说：‘耶和华如此说：放我的百姓走，好事奉我。","notes":[]},{"n":2,"t":"你若不肯放他们走，看哪，我必以青蛙之灾击打你的疆土。","notes":[]},{"n":3,"t":"尼罗河要滋生青蛙；这青蛙要上来进你的宫殿和你的卧房，上你的床榻，进你臣仆的房屋，上你百姓的身上，进你的炉灶和你的揉面盆。","notes":[]},{"n":4,"t":"这些青蛙要跳上你、你百姓和你众臣仆的身上。’”","notes":[]},{"n":5,"t":"耶和华对摩西说：“你要对亚伦说：‘伸出你手里的杖在江、河、池塘上，把青蛙带上埃及地来。’”","notes":[]},{"n":6,"t":"亚伦伸手在埃及的众水上，青蛙就上来，遮满了埃及地。","notes":[]},{"n":7,"t":"术士也用他们的邪术照样去做，把青蛙带上埃及地。","notes":[]},{"n":8,"t":"法老召摩西和亚伦来，说：“请你们祈求耶和华使这些青蛙离开我和我的百姓，我就让这百姓去向耶和华献祭。”","notes":[]},{"n":9,"t":"摩西对法老说：“悉听尊便，告诉我何时为你、你臣仆和你的百姓祈求，使青蛙被剪除，离开你和你的宫殿，只留在尼罗河里。”","notes":[]},{"n":10,"t":"他说：“明天。”摩西说：“就照你的话吧，为要叫你知道没有像耶和华我们神的，","notes":[]},{"n":11,"t":"青蛙必会离开你、你宫殿、你臣仆和你的百姓，只留在尼罗河里。”","notes":[]},{"n":12,"t":"于是摩西和亚伦离开法老出去。摩西为了青蛙的事呼求耶和华，因为他带来青蛙搅扰法老。","notes":[]},{"n":13,"t":"耶和华就照摩西的请求去做；在屋里、院中、田间的青蛙都死了。","notes":[]},{"n":14,"t":"众人把青蛙聚拢成堆，地就发出臭气。","notes":[]},{"n":15,"t":"但法老见灾祸舒缓了，就硬着心，不听从他们，正如耶和华所说的。","notes":[]},{"n":16,"t":"耶和华对摩西说：“你要对亚伦说：‘伸出你的杖击打地上的尘土，使尘土在埃及全地变成蚊子。’”","notes":["“蚊子”：有古译本是“虱子”或“虼蚤”或“虫”；下同。"],"heads":["第三灾：蚊灾"]},{"n":17,"t":"他们就照样做了。亚伦伸出他手里的杖，击打地上的尘土，人和牲畜身上就有了蚊子；埃及全地的尘土都变成蚊子了。","notes":[]},{"n":18,"t":"术士也用邪术要照样产生蚊子，却做不成。于是人和牲畜的身上都有了蚊子。","notes":[]},{"n":19,"t":"术士对法老说：“这是神的手指。”法老心里刚硬，不听摩西和亚伦，正如耶和华所说的。","notes":[]},{"n":20,"t":"耶和华对摩西说：“你要清早起来，站在法老面前。看哪，法老来到水边，你就对他说：‘耶和华如此说：放我的百姓走，好事奉我。","notes":[],"heads":["第四灾： 蝇灾"]},{"n":21,"t":"你若不放我的百姓走，看哪，我要派成群的苍蝇到你、你臣仆和你百姓身上，进你的宫殿；埃及人的房屋和他们所住的地都要满了成群的苍蝇。","notes":[]},{"n":22,"t":"那一日，我必把我百姓所住的歌珊地分别出来，使那里没有成群的苍蝇，好叫你知道我─耶和华是在全地之中。","notes":[]},{"n":23,"t":"我要施行救赎，区隔我的百姓和你的百姓。明天必有这神迹。’”","notes":[]},{"n":24,"t":"耶和华就这样做了。大群的苍蝇进入法老的宫殿和他臣仆的房屋；在埃及全地，地就因这成群的苍蝇毁坏了。","notes":[]},{"n":25,"t":"法老召了摩西和亚伦来，说：“去，在此地向你们的神献祭。”","notes":[]},{"n":26,"t":"摩西说：“这样做是不妥的，因为我们要献给耶和华－我们神的祭物是埃及人所厌恶的；看哪，我们在埃及人眼前献他们所厌恶的，他们岂不拿石头打死我们吗？","notes":[]},{"n":27,"t":"我们要遵照耶和华－我们神所吩咐我们的，往旷野去，走三天路程，向他献祭。”","notes":[]},{"n":28,"t":"法老说：“我可以放你们走，在旷野向耶和华－你们的神献祭，只是不可走得太远。你们要为我祈祷。”","notes":[]},{"n":29,"t":"摩西说：“看哪，我要从你这里出去祈求耶和华，使成群的苍蝇明天离开法老、法老的臣仆和法老的百姓；法老却不可再欺骗，不让百姓去向耶和华献祭。”","notes":[]},{"n":30,"t":"于是摩西离开法老，去祈求耶和华。","notes":[]},{"n":31,"t":"耶和华就照摩西的请求去做，使成群的苍蝇离开法老、他的臣仆和他的百姓，一只也没有留下。","notes":[]},{"n":32,"t":"但这一次法老又硬着心，不放百姓走。","notes":[]}]},"9":{"heading":"第五灾：瘟灾","verses":[{"n":1,"t":"耶和华对摩西说：“你要到法老那里，对他说：‘耶和华－希伯来人的神如此说：放我的百姓走，好事奉我。","notes":[]},{"n":2,"t":"你若不肯放他们走，仍要强留他们，","notes":[]},{"n":3,"t":"看哪，耶和华的手必以严重的瘟疫加在你田间的牲畜上，就是在马、驴、骆驼、牛群和羊群的身上。","notes":[]},{"n":4,"t":"耶和华却要分别以色列的牲畜和埃及的牲畜，凡属以色列人的，一只都不死。’”","notes":[]},{"n":5,"t":"耶和华就设定时间，说：“明天耶和华必在此地行这事。”","notes":[]},{"n":6,"t":"第二天，耶和华行了这事。埃及的牲畜全都死了，只是以色列人的牲畜，一只都没有死。","notes":[]},{"n":7,"t":"法老派人去，看哪，以色列人的牲畜连一只都没有死。可是法老硬着心，不放百姓走。","notes":[]},{"n":8,"t":"耶和华对摩西和亚伦说：“你们从炉里满满捧出炉灰，摩西要在法老眼前把它撒在空中。","notes":[],"heads":["第六灾：疮灾"]},{"n":9,"t":"这灰要在埃及全地变成尘土，使埃及全地的人和牲畜身上起泡生疮。”","notes":[]},{"n":10,"t":"摩西和亚伦取了炉灰，站在法老面前。摩西把它撒在空中，人和牲畜的身上就起泡生疮了。","notes":[]},{"n":11,"t":"因为这疮，术士在摩西面前站立不住，术士和所有埃及人的身上都生了疮。","notes":[]},{"n":12,"t":"但耶和华任凭法老的心刚硬，不听摩西和亚伦，正如耶和华对摩西所说的。","notes":[]},{"n":13,"t":"耶和华对摩西说：“你要清早起来，站在法老面前，对他说：‘耶和华－希伯来人的神如此说：放我的百姓走，好事奉我。","notes":[],"heads":["第七灾：雹灾"]},{"n":14,"t":"因为这一次我要使一切的灾祸临到你自己，你臣仆和你百姓的身上，为要叫你知道在全地没有像我的。","notes":[]},{"n":15,"t":"现在，我若伸手用瘟疫攻击你和你的百姓，你就会从地上除灭了。","notes":[]},{"n":16,"t":"然而，我让你存活，是为了要使你看见我的大能，并要使我的名传遍全地。","notes":[]},{"n":17,"t":"可是你仍然向我的百姓自高自大，不放他们走。","notes":[]},{"n":18,"t":"看哪，明天大约这时候，我必使大量的冰雹降下，这是从埃及立国直到如今没有出现过的。","notes":[]},{"n":19,"t":"现在，你要派人把你的牲畜和你田间一切所有的带去躲避；任何在田间，无论是人是牲畜没有回到屋内的，冰雹必降在他们身上，他们就必死。’”","notes":[]},{"n":20,"t":"法老的臣仆中，惧怕耶和华这话的，就让他的奴仆和牲畜逃进屋里。","notes":[]},{"n":21,"t":"但那不把耶和华这话放在心上的，就把他的奴仆和牲畜留在田里。","notes":[]},{"n":22,"t":"耶和华对摩西说：“你向天伸出你的手，使冰雹降在埃及全地，降在埃及地的人和牲畜身上，以及田间各样菜蔬上。”","notes":[]},{"n":23,"t":"摩西向天伸杖，耶和华就打雷下雹，有火降到地上；耶和华下雹在埃及地上。","notes":[]},{"n":24,"t":"那时，有雹，也有火在雹中闪烁，极其严重；自从埃及立国以来，全地没有像这样的。","notes":[]},{"n":25,"t":"在埃及全地，冰雹击打田间所有的人和牲畜，击打一切的菜蔬，也打坏了田间一切的树木。","notes":[]},{"n":26,"t":"惟独以色列人所住的歌珊地没有冰雹。","notes":[]},{"n":27,"t":"法老差派人去召摩西和亚伦来，对他们说：“这一次我犯罪了。耶和华是公义的；我和我的百姓是邪恶的。","notes":[]},{"n":28,"t":"请你们祈求耶和华，因神的雷轰和冰雹已经够了。我要放你们走，你们不用再留下来了。”","notes":[]},{"n":29,"t":"摩西对他说：“我一出城就向耶和华举起双手；雷必止住，也不再有冰雹，叫你知道地是属于耶和华的。","notes":[]},{"n":30,"t":"至于你和你的臣仆，我知道你们仍然不敬畏耶和华神。”","notes":[]},{"n":31,"t":"那时，亚麻和大麦被摧毁了，因为大麦已经吐穗，亚麻也开了花。","notes":[]},{"n":32,"t":"只是小麦和粗麦没有被摧毁，因为它们还没有长成。","notes":[]},{"n":33,"t":"摩西离开法老出了城，向耶和华举起双手，雷和雹就止住，雨也不再下在地上了。","notes":[]},{"n":34,"t":"法老见雨、雹、雷止住，又再犯罪；他和他的臣仆都硬着心。","notes":[]},{"n":35,"t":"法老的心刚硬，不放以色列人走，正如耶和华藉着摩西所说的。","notes":[]}]},"10":{"heading":"第八灾：蝗灾","verses":[{"n":1,"t":"耶和华对摩西说：“你要到法老那里，因我使他硬着心，也使他臣仆硬着心，为要在他们中间显出我的这些神迹来，","notes":["“在他们中间”是根据七十士译本；原文是“在他中间”。"]},{"n":2,"t":"并要叫你将我严厉对付埃及的事，和在他们中间所行的神迹，传于儿子和孙子的耳中，好叫你们知道我是耶和华。”","notes":[]},{"n":3,"t":"摩西和亚伦就到法老那里，对他说：“耶和华－希伯来人的神这样说：‘你在我面前不肯谦卑要到几时呢？放我的百姓走，好事奉我。","notes":[]},{"n":4,"t":"你若不肯放我的百姓走，看哪，明天我要使蝗虫进入你的境内，","notes":[]},{"n":5,"t":"遮满地面，甚至地也看不见了。它们要吃那冰雹后所剩，就是留给你们的；并且要吃那生长在田间的一切树木。","notes":["“地面”：原文是“地的眼睛”；15节同。"]},{"n":6,"t":"你的宫殿和你众臣仆的房屋，以及一切埃及人的房屋，都要被蝗虫占满；你祖宗和你祖宗的祖宗在世以来，直到今日都没有见过。’”摩西就转身离开法老出去。","notes":[]},{"n":7,"t":"法老的臣仆对法老说：“这家伙成为我们的罗网要到几时呢？让这些人去事奉耶和华－他们的神吧！埃及快要灭亡了，你还不知道吗？”","notes":[]},{"n":8,"t":"于是摩西和亚伦被召回来见法老。法老对他们说：“去，事奉耶和华－你们的神吧！但要去的是哪些人呢？”","notes":[]},{"n":9,"t":"摩西说：“我们要带着年老的和年少的同去，要带着我们的儿子和女儿，以及我们的羊群牛群一起去，因为我们要向耶和华守节。”","notes":[]},{"n":10,"t":"法老对他们说：“愿耶和华与你们同在吧！我若让你们带着你们的孩子同去，看，灾祸就在你们面前！","notes":["“灾祸就在你们面前”或译“你们存着恶意”。"]},{"n":11,"t":"不可都去！你们壮年人去事奉耶和华吧，因为这是你们所求的。”于是法老把他们从自己面前赶出去。","notes":[]},{"n":12,"t":"耶和华对摩西说：“你向埃及地伸出你的手，使蝗虫上到埃及地，吃地上冰雹后所剩一切的植物。”","notes":[]},{"n":13,"t":"摩西就向埃及地伸杖；整整一昼一夜，耶和华使东风刮在埃及地上，到了早晨，东风把蝗虫刮了来。","notes":[]},{"n":14,"t":"蝗虫上到埃及全地，落在埃及全境，非常厉害；蝗虫这么多，是空前绝后的。","notes":[]},{"n":15,"t":"蝗虫遮满地面，地上一片黑暗。它们吃尽了地上一切的植物和冰雹过后所剩树上的果子。埃及全地，无论是树木，是田间的植物，连一点绿的也没有留下。","notes":[]},{"n":16,"t":"于是法老急忙召了摩西和亚伦来，说：“我得罪了耶和华－你们的神，又得罪了你们。","notes":[]},{"n":17,"t":"现在求你，就这一次，饶恕我的罪，祈求耶和华－你们的神救我脱离这次的死亡。”","notes":[]},{"n":18,"t":"摩西就离开法老，去祈求耶和华。","notes":[]},{"n":19,"t":"耶和华转变风向，使强劲的西风吹来，把蝗虫刮起，吹入红海；在埃及全境连一只也没有留下。","notes":["“红海”是根据七十士译本，原文是“芦苇海”；本卷书下同。"]},{"n":20,"t":"但耶和华任凭法老的心刚硬，不放以色列人走。","notes":[]},{"n":21,"t":"耶和华对摩西说：“你向天伸出你的手，使黑暗笼罩埃及地；这黑暗甚至可以摸得到。”","notes":[],"heads":["第九灾：黑暗之灾"]},{"n":22,"t":"摩西向天伸出他的手，浓密的黑暗就笼罩了埃及全地三天之久。","notes":[]},{"n":23,"t":"三天内，人人彼此看不见，谁也不敢起身离开原地；但所有以色列人住的地方却有光。","notes":[]},{"n":24,"t":"法老就召摩西来，说：“去，事奉耶和华吧！只是你们的羊群牛群要留下来。你们的孩子可以和你们同去。”","notes":[]},{"n":25,"t":"摩西说：“你必须把祭物和燔祭牲交在我们手中，让我们可以向耶和华我们的神献祭。","notes":[]},{"n":26,"t":"我们的牲畜也要与我们同去，连一蹄也不留下，因为我们要从牲畜中挑选来事奉耶和华－我们的神。未到那里之前，我们还不知道要用什么来事奉耶和华。”","notes":[]},{"n":27,"t":"但耶和华任凭法老的心刚硬，法老不肯放他们走。","notes":[]},{"n":28,"t":"法老对摩西说：“离开我去吧！你要小心，不要再见我的面，因为再见我面的那日，你就必死！”","notes":[]},{"n":29,"t":"摩西说：“就照你说的，我也不要再见你的面了！”","notes":[]}]},"11":{"heading":"最后一灾的警告","verses":[{"n":1,"t":"耶和华对摩西说：“我要再降一个灾祸给法老和埃及，然后他必让你们离开这里。他放你们走的时候，一定会赶你们全都离开这里。","notes":[]},{"n":2,"t":"你要传于百姓耳中，叫他们男的女的各向邻舍索取金器银器。”","notes":[]},{"n":3,"t":"耶和华使埃及人看得起他的百姓，并且摩西在埃及地，在法老臣仆和百姓眼中看为伟大。","notes":["“他的百姓”是根据七十士译本；原文是“百姓”。"]},{"n":4,"t":"摩西说：“耶和华如此说：‘约到半夜，我必出去走遍埃及。","notes":[]},{"n":5,"t":"凡在埃及地，从坐宝座的法老到推磨的婢女所生的长子，以及一切头生的牲畜，都必死。","notes":["“推磨”：原文是“在石磨后”。"]},{"n":6,"t":"埃及全地必有大大的哀号，这将是空前绝后的。","notes":[]},{"n":7,"t":"至于以色列人中，无论是人是牲畜，连狗也不敢向他们吠叫，使你们知道耶和华区别埃及和以色列。’","notes":[]},{"n":8,"t":"你所有的这些臣仆都要下到我这里，向我下拜说：‘请你和跟从你的百姓都离开吧！’然后我才离开。”于是，摩西气愤愤地离开法老出去了。","notes":[]},{"n":9,"t":"耶和华对摩西说：“法老必不听你们，为了要使我在埃及地多行奇事。”","notes":[]},{"n":10,"t":"摩西和亚伦在法老面前行了这一切奇事，但耶和华任凭法老的心刚硬，不让以色列人离开他的地。","notes":[]}]},"12":{"heading":"耶和华的逾越","verses":[{"n":1,"t":"耶和华在埃及地对摩西和亚伦说：","notes":[]},{"n":2,"t":"“你们要以本月为正月，为一年之首。","notes":[]},{"n":3,"t":"你们要吩咐以色列全会众说：本月初十，各人要按着家庭取羔羊，一家一只羔羊。","notes":["“家庭”：原文是“父家(以父为主的家庭)”。"]},{"n":4,"t":"若一家的人太少，吃不了一只羔羊，就要按照人数和隔壁的邻舍共取一只；你们要按每人的食量来估算羔羊。","notes":[]},{"n":5,"t":"你们要从绵羊或山羊中取一只无残疾、一岁的公羔羊，","notes":[]},{"n":6,"t":"要把它留到本月十四日；那日黄昏的时候，以色列全会众要把羔羊宰了。","notes":[]},{"n":7,"t":"他们要取一些血，涂在他们吃羔羊的房屋两边的门框上和门楣上。","notes":[]},{"n":8,"t":"当晚要吃羔羊的肉；要用火烤了，与无酵饼和苦菜一起吃。","notes":[]},{"n":9,"t":"不可吃生的，或用水煮的，要把羔羊连头带腿和内脏用火烤了吃。","notes":[]},{"n":10,"t":"一点也不可留到早晨；若有留到早晨的，要用火烧了。","notes":[]},{"n":11,"t":"你们要这样吃羔羊：腰间束带，脚上穿鞋，手中拿杖，快快地吃。这是耶和华的逾越。","notes":[]},{"n":12,"t":"因为那夜我要走遍埃及地，把埃及地一切头生的，无论是人是牲畜，都击杀了；我要对埃及所有的神明施行审判。我是耶和华。","notes":[]},{"n":13,"t":"这血要在你们所住的房屋上作记号；我一见这血，就逾越你们。我击打埃及地的时候，灾殃必不临到你们身上施行毁灭。”","notes":[]},{"n":14,"t":"“你们要记念这日，世世代代守这日为耶和华的节日，作为你们永远的定例。","notes":[],"heads":["除酵节"]},{"n":15,"t":"你们要吃无酵饼七日。第一日要把酵从你们各家中除去，因为从第一日到第七日，任何吃有酵之物的，必从以色列中剪除。","notes":[]},{"n":16,"t":"第一日当有圣会，第七日也当有圣会。在这两日，任何工作都不可做，只能预备各人的食物，这是惟一可做的工作。","notes":[]},{"n":17,"t":"你们要守除酵节，因为我在这一日把你们的军队从埃及地领出来。所以，你们要世世代代守这日，立为永远的定例。","notes":[]},{"n":18,"t":"从正月十四日晚上，直到二十一日晚上，你们要吃无酵饼。","notes":[]},{"n":19,"t":"在你们各家中，七日之内不可有酵，因为凡吃有酵之物的，无论是寄居的，是本地的，必从以色列的会中剪除。","notes":[]},{"n":20,"t":"任何有酵的物，你们都不可吃；在你们一切的住处要吃无酵饼。”","notes":[]},{"n":21,"t":"于是，摩西召了以色列的众长老来，对他们说：“你们要为家人取羔羊，把逾越的羔羊宰了。","notes":[],"heads":["逾越节的建立"]},{"n":22,"t":"要拿一把牛膝草，蘸盆里的血，把盆里的血涂在门楣上和两边的门框上。直到早晨你们谁也不可出自己家里的门。","notes":[]},{"n":23,"t":"因为耶和华要走遍埃及，施行击杀，他看见血在门楣上和两边的门框上，耶和华就必逾越那门，不让灭命者进你们的家，施行击杀。","notes":[]},{"n":24,"t":"你们要守这命令，作为你们和你们子孙永远的定例。","notes":[]},{"n":25,"t":"日后，你们到了耶和华所应许赐给你们的那地，就要守这礼仪。","notes":[]},{"n":26,"t":"你们的儿女对你们说：‘这礼仪是什么意思呢？’","notes":[]},{"n":27,"t":"你们就说：‘这是献给耶和华逾越节的祭物。当耶和华击杀埃及人的时候，他逾越了以色列人在埃及的房屋，救了我们各家。’”于是百姓低头敬拜。","notes":[]},{"n":28,"t":"以色列人就去做；他们照耶和华吩咐摩西和亚伦的去做了。","notes":[]},{"n":29,"t":"到了半夜，耶和华把埃及地所有头生的，就是从坐宝座的法老，到关在牢里的人的长子，以及一切头生的牲畜，尽都杀了。","notes":[],"heads":["第十灾：头生的被杀"]},{"n":30,"t":"法老和他众臣仆，以及所有的埃及人，都在夜间起来了。在埃及有大大的哀号，因为没有一家不死人的。","notes":[]},{"n":31,"t":"夜间，法老召了摩西和亚伦来，说：“起来！你们和以色列人，都离开我的百姓出去，照你们所说的，去事奉耶和华吧！","notes":[]},{"n":32,"t":"照你们所说的，连羊群牛群也带走，也为我祝福吧！”","notes":[]},{"n":33,"t":"埃及人催促百姓赶快离开那地，因为埃及人说：“我们都快死了。”","notes":[]},{"n":34,"t":"百姓就拿着没有发酵的生面，把揉面盆包在衣服中，扛在肩上。","notes":[]},{"n":35,"t":"以色列人照摩西的话去做，向埃及人索取金器、银器和衣裳。","notes":[]},{"n":36,"t":"耶和华使埃及人看得起他的百姓，埃及人就给了他们所要的。他们就掠夺了埃及人。","notes":[]},{"n":37,"t":"以色列人从兰塞起程，往疏割去。除了小孩，步行的男人约有六十万。","notes":[],"heads":["出埃及"]},{"n":38,"t":"又有许多不同族群的人，以及众多的羊群牛群，和他们一同上去。","notes":[]},{"n":39,"t":"他们用埃及带出来的生面烤成无酵饼。这生面是没有发酵的；因为他们被催促离开埃及，不能耽延，就没有为自己预备食物。","notes":[]},{"n":40,"t":"以色列人住在埃及共四百三十年。","notes":[]},{"n":41,"t":"正满四百三十年的那一天，耶和华的全军从埃及地出来了。","notes":[]},{"n":42,"t":"这是向耶和华守的夜，他领他们出埃及地；这是以色列众人世世代代要向耶和华守的夜。","notes":[]},{"n":43,"t":"耶和华对摩西和亚伦说：“逾越节的条例是这样：外邦人不可吃这羔羊。","notes":[],"heads":["逾越节的条例"]},{"n":44,"t":"但是你们用银子买来，又受过割礼的奴仆可以吃。","notes":[]},{"n":45,"t":"寄居的和雇工都不可吃。","notes":[]},{"n":46,"t":"应当在一个屋子里吃，不可把肉带到屋外，骨头一根也不可折断。","notes":[]},{"n":47,"t":"以色列全会众都要守这礼仪。","notes":[]},{"n":48,"t":"若有外人寄居在你那里，要向耶和华守逾越节，他所有的男子务要先受割礼，然后才可以当他是本地人，容许他守这礼仪。但未受割礼的都不可吃这羔羊。","notes":[]},{"n":49,"t":"本地人和寄居在你们中间的外人当守同一个条例。”","notes":[]},{"n":50,"t":"以色列众人就去做，他们照耶和华吩咐摩西和亚伦的去做了。","notes":[]},{"n":51,"t":"正当那日，耶和华将以色列人按着他们的队伍从埃及地领了出来。","notes":[]}]},"13":{"heading":"头生的分别为圣","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“头生的要分别为圣归我；以色列中凡头生的，无论是人是牲畜，都是我的。”","notes":[]},{"n":3,"t":"摩西对百姓说：“你们要记念从埃及为奴之家出来的这日，因为耶和华用大能的手将你们从这地领出来。有酵之物都不可吃。","notes":[],"heads":["除酵节"]},{"n":4,"t":"亚笔月的这一日你们走出来了。","notes":[]},{"n":5,"t":"将来耶和华领你进迦南人、赫人、亚摩利人、希未人、耶布斯人之地，就是他向你祖宗起誓应许给你的那流奶与蜜之地，那时你要在这一个月守这礼仪。","notes":[]},{"n":6,"t":"你要吃无酵饼七日，在第七日要向耶和华守节。","notes":[]},{"n":7,"t":"这七日之内，要吃无酵饼；在你的全境内不可见有酵之物，也不可见酵母。","notes":[]},{"n":8,"t":"当那日，你要告诉你的儿子说：‘这样做是因为耶和华在我出埃及的时候为我所做的事。’","notes":[]},{"n":9,"t":"这要在你手上作记号，在你额上作纪念，使耶和华的教导常在你口中，因为耶和华用大能的手将你从埃及领出来。","notes":["“额上”：原文是“两眼之间”；16节同。"]},{"n":10,"t":"所以你每年要按着日期守这条例。”","notes":[]},{"n":11,"t":"“当耶和华照他向你和你祖宗所起的誓将你领进迦南人之地，把那地赐给你的时候，","notes":[],"heads":["头生的献给主"]},{"n":12,"t":"你要将一切头生的献给耶和华；你牲畜中头生的，公的都归耶和华。","notes":[]},{"n":13,"t":"然而，凡头生的驴，你要用羔羊赎回；若不赎它，就要打断它的颈项。你儿子中的长子都要赎出来。","notes":[]},{"n":14,"t":"日后，你的儿子问你说：‘这是什么意思？’你就说：‘耶和华用大能的手将我们从埃及为奴之家领出来。","notes":[]},{"n":15,"t":"那时法老固执，不肯放我们走，耶和华就把埃及地所有头生的，无论是人是牲畜，都杀了。因此，我把一切头生的公的牲畜献给耶和华为祭，却将所有头生的儿子赎出来。","notes":[]},{"n":16,"t":"这要在你手上作记号，在你额上作经匣，因为耶和华用大能的手将我们从埃及领出来。’”","notes":["“经匣”指“把经文放在皮制的匣中作额饰”。"]},{"n":17,"t":"法老放百姓走的时候，非利士人之地的路虽近，神却不领他们从那里走，因为神说：“恐怕百姓遇见战争就后悔，转回埃及去。”","notes":[],"heads":["云柱和火柱"]},{"n":18,"t":"神领百姓绕道而行，走旷野的路到红海。以色列人出埃及地，都带着兵器上去。","notes":["“以色列人...都带着兵器上去”：七十士译本是“以色列中第五代的人也出埃及地上去”。"]},{"n":19,"t":"摩西把约瑟的骸骨一起带走；因为约瑟曾叫以色列人郑重地起誓，对他们说：“神必定眷顾你们，你们要把我的骸骨从这里一起带上去。”","notes":[]},{"n":20,"t":"他们从疏割起程，在旷野边上的以倘安营。","notes":[]},{"n":21,"t":"耶和华走在他们前面，日间用云柱引领他们的路，夜间用火柱照亮他们，使他们日夜都可以行走。","notes":[]},{"n":22,"t":"日间的云柱，夜间的火柱，总不离开百姓的面前。","notes":[]}]},"14":{"heading":"过红海","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你吩咐以色列人转回，要在比．哈希录前面，密夺和海的中间，巴力．洗分的前面安营。你们要在对面，靠近海边安营。","notes":[]},{"n":3,"t":"以色列人这样做，法老必说：‘他们在此地迷了路，旷野把他们困住了。’","notes":[]},{"n":4,"t":"我要任凭法老的心刚硬，他要追赶他们。我必在法老和他全军身上得荣耀，埃及人就知道我是耶和华。”于是以色列人照样做了。","notes":[]},{"n":5,"t":"有人报告埃及王说：“百姓逃跑了！”法老和他的臣仆对百姓改变了心意，说：“我们放以色列人走，不再服事我们，我们怎么会做这种事呢？”","notes":[]},{"n":6,"t":"法老就预备战车，带领他的军兵同去，","notes":[]},{"n":7,"t":"他带了六百辆特选的战车和埃及所有的战车，每辆都有军官。","notes":[]},{"n":8,"t":"耶和华任凭埃及王法老的心刚硬，他就追赶以色列人；以色列人却抬起头来出去了。","notes":["“抬起头”：原文是“举起手”。"]},{"n":9,"t":"埃及人追赶他们，法老一切的马匹、战车、战车长，与军兵就在海边上，靠近比．哈希录，在巴力．洗分的前面，在他们安营的地方追上了。","notes":[]},{"n":10,"t":"法老逼近的时候，以色列人举目，看哪，埃及人追来了，就非常惧怕，以色列人向耶和华哀求。","notes":[]},{"n":11,"t":"他们对摩西说：“难道埃及没有坟地，你要把我们带来死在旷野吗？你为什么这样待我们，将我们从埃及领出来呢？","notes":[]},{"n":12,"t":"我们在埃及岂没有对你说过，不要搅扰我们，让我们服事埃及人吗？因为服事埃及人总比死在旷野好。”","notes":[]},{"n":13,"t":"摩西对百姓说：“不要怕，要站稳，看耶和华今天向你们所要施行的拯救，因为你们今天所看见的埃及人必永远不再看见了。","notes":[]},{"n":14,"t":"耶和华必为你们争战，你们要安静！”","notes":[]},{"n":15,"t":"耶和华对摩西说：“你为什么向我哀求呢？你吩咐以色列人往前走。","notes":[]},{"n":16,"t":"你举手向海伸杖，把水分开。以色列人要下到海中，走在干地上。","notes":[]},{"n":17,"t":"看哪，我要任凭埃及人的心刚硬，他们就跟着下去。我要在法老和他的全军、战车、战车长身上得荣耀。","notes":[]},{"n":18,"t":"我在法老和他的战车、战车长身上得荣耀的时候，埃及人就知道我是耶和华。”","notes":[]},{"n":19,"t":"在以色列营前行走的神的使者移动，走到他们后面；云也从他们的前面移动，站在他们后面。","notes":[]},{"n":20,"t":"它来到埃及营和以色列营的中间：一边有云和黑暗，另一边它照亮夜晚，整夜彼此不得接近。","notes":[]},{"n":21,"t":"摩西向海伸手，耶和华就用强劲的东风，使海水在一夜间退去，海就成了干地；水分开了。","notes":[]},{"n":22,"t":"以色列人下到海中，走在干地上，水在他们左右成了墙壁。","notes":[]},{"n":23,"t":"埃及人追赶他们，法老一切的马匹、战车和战车长都跟着下到海中。","notes":[]},{"n":24,"t":"破晓时分，耶和华从云柱、火柱中瞭望埃及的军兵，使埃及的军兵混乱。","notes":[]},{"n":25,"t":"他使他们的车轮脱落，难以前行，埃及人说：“我们从以色列人面前逃跑吧！因耶和华为他们作战，攻击埃及了。”","notes":["“脱落”：撒玛利亚五经、七十士译本和其他古译本是“受阻”。"]},{"n":26,"t":"耶和华对摩西说：“你要向海伸手，使水回流到埃及人，他们的战车和战车长身上。”","notes":[]},{"n":27,"t":"摩西就向海伸手，到了天亮的时候，海恢复原状。埃及人逃避水的时候，耶和华把他们推入海中。","notes":[]},{"n":28,"t":"海水回流，淹没了战车和战车长，以及那些跟着以色列人下到海中的法老全军，连一个也没有剩下。","notes":[]},{"n":29,"t":"以色列人却在海中走干地，水在他们的左右成了墙壁。","notes":[]},{"n":30,"t":"那一日，耶和华拯救以色列脱离埃及人的手。以色列人看见埃及人死在海边。","notes":[]},{"n":31,"t":"以色列人看见耶和华向埃及人所施展的大能，百姓就敬畏耶和华，并且信服耶和华和他的仆人摩西。","notes":[]}]},"15":{"heading":"摩西之歌","verses":[{"n":1,"t":"那时，摩西和以色列人向耶和华唱这歌，说：“我要向耶和华歌唱，因他大大得胜，将马和骑马的投在海中。","notes":[]},{"n":2,"t":"耶和华是我的力量，是我的诗歌，他也成了我的拯救。这是我的神，我要赞美他；我父亲的神，我要尊崇他。","notes":[]},{"n":3,"t":"耶和华是战士；耶和华是他的名。","notes":[]},{"n":4,"t":"“法老的战车、军兵，他已抛在海中；法老精选的军官都沉于红海。","notes":[]},{"n":5,"t":"深水淹没他们；他们好像石头坠到深处。","notes":[]},{"n":6,"t":"耶和华啊，你的右手施展能力，大显荣耀；耶和华啊，你的右手摔碎仇敌。","notes":[]},{"n":7,"t":"你大发威严，摧毁了你的敌人；你发出烈怒，吞灭他们如同碎秸。","notes":[]},{"n":8,"t":"因你鼻中的气，水就聚成堆，大水竖立如垒，海的中心深水凝结。","notes":[]},{"n":9,"t":"仇敌说：‘我要追赶，我要追上，我要分掳物，在他们身上满足我的心愿，我要拔刀，亲手毁灭他们。’","notes":[]},{"n":10,"t":"你用风一吹，海水就淹没他们；他们像铅沉在大水之中。","notes":[]},{"n":11,"t":"“耶和华啊，众神明中，谁能像你？谁能像你，至圣至荣，可颂可畏，施行奇事！","notes":[]},{"n":12,"t":"你伸出右手，地就吞灭他们。","notes":[]},{"n":13,"t":"“你以慈爱引领你所救赎的百姓；你以能力引导他们到你的圣所。","notes":[]},{"n":14,"t":"万民听见就战抖；疼痛抓住非利士的居民。","notes":[]},{"n":15,"t":"那时，以东的族长惊惶，摩押的英雄被战兢抓住，迦南所有的居民都融化。","notes":[]},{"n":16,"t":"惊骇恐惧临到他们；耶和华啊，因你膀臂的大能，他们如石头寂静不动，等候你百姓过去，等候你所赎的百姓过去。","notes":[]},{"n":17,"t":"你要将他们领进去，栽在你产业的山上，耶和华啊，就是你为自己所造的住处，主啊，就是你手所建立的圣所。","notes":[]},{"n":18,"t":"耶和华必作王，直到永永远远！”","notes":[]},{"n":19,"t":"法老的马匹、战车和战车长下到海中，耶和华使海水回流到他们身上；以色列人却走在海中的干地上。","notes":[]},{"n":20,"t":"那时，米利暗女先知，亚伦的姊姊，手里拿着铃鼓；众妇女也跟她出去打鼓跳舞。","notes":[],"heads":["米利暗的歌"]},{"n":21,"t":"米利暗回应他们：“你们要歌颂耶和华，因他大大得胜，将马和骑马的投在海中。”","notes":[]},{"n":22,"t":"摩西领以色列人从红海起程，到了书珥的旷野，在旷野走了三天，找不到水。","notes":[],"heads":["苦水变甜"]},{"n":23,"t":"到了玛拉，他们不能喝玛拉的水，因为水是苦的；所以那地名叫玛拉。","notes":[]},{"n":24,"t":"百姓就向摩西发怨言，说：“我们喝什么呢？”","notes":[]},{"n":25,"t":"摩西呼求耶和华，耶和华指示他一棵树。他把树丢在水里，水就变甜了。耶和华在那里为他们定了律例、典章，在那里考验他们。","notes":["“一棵树”或译“一块木头”。"]},{"n":26,"t":"他说：“你若留心听从耶和华－你神的话，行我眼中看为正的事，侧耳听我的诫令，遵守我一切的律例，我就不将所加于埃及人的疾病加在你身上，因为我是医治你的耶和华。”","notes":[]},{"n":27,"t":"他们到了以琳，在那里有十二股水泉，七十棵棕树；他们就在那里的水边安营。","notes":[]}]},"16":{"heading":"吗哪和鹌鹑","verses":[{"n":1,"t":"以色列全会众从以琳起程，在出埃及之后第二个月十五日到了以琳和西奈中间，汛的旷野。","notes":[]},{"n":2,"t":"以色列全会众在旷野向摩西和亚伦发怨言。","notes":[]},{"n":3,"t":"以色列人对他们说：“我们宁愿在埃及地死在耶和华手中！那时我们坐在肉锅旁，吃饼得饱。你们却将我们领出来，到这旷野，要叫这全会众都饿死啊！”","notes":[]},{"n":4,"t":"耶和华对摩西说：“看哪，我要从天降食物给你们。百姓可以出去，每天收集当天的分量。这样，我就可以考验他们是否遵行我的指示。","notes":[]},{"n":5,"t":"到第六天，他们预备食物，所收集的分量要比每天所收的多一倍。”","notes":[]},{"n":6,"t":"摩西和亚伦对以色列众人说：“到了晚上，你们就知道是耶和华将你们从埃及地领出来的。","notes":[]},{"n":7,"t":"早晨，你们要看见耶和华的荣耀，因为耶和华听见你们向他所发的怨言了。我们算什么，你们竟然向我们发怨言呢？”","notes":[]},{"n":8,"t":"摩西又说：“耶和华晚上必给你们肉吃，早晨必给你们食物得饱，因为耶和华已经听见你们向他所发的怨言。我们算什么呢？你们的怨言不是向我们发的，而是向耶和华发的。”","notes":[]},{"n":9,"t":"摩西对亚伦说：“你对以色列全会众说：‘你们来到耶和华面前，因为他已经听见你们的怨言了。’”","notes":[]},{"n":10,"t":"亚伦正对以色列全会众说话的时候，他们转向旷野，看哪，耶和华的荣光在云中显现。","notes":[]},{"n":11,"t":"耶和华吩咐摩西说：","notes":[]},{"n":12,"t":"“我已经听见以色列人的怨言了。你要对他们说：‘到黄昏的时候，你们要吃肉，早晨也必有食物得饱。你们就知道我是耶和华－你们的神。’”","notes":["“黄昏的时候”：原文是“两个黄昏之间”。"]},{"n":13,"t":"到了晚上，有鹌鹑上来，遮满营地；早晨，营地周围有一层露水。","notes":[]},{"n":14,"t":"那一层露水蒸发之后，看哪，旷野的表面出现了小圆物，好像地上的薄霜一样。","notes":[]},{"n":15,"t":"以色列人看见了，不知道是什么，就彼此说：“这是什么？”摩西对他们说：“这是耶和华给你们吃的食物。","notes":["“这是什么？”是根据七十士译本；原文是“这是吗哪。”"]},{"n":16,"t":"耶和华所吩咐的是这样：‘你们每个人要按自己的食量收集，各人要为帐棚里的人收集，按照人口数每个人一俄梅珥。’”","notes":[]},{"n":17,"t":"以色列人就照样去做；有的收多，有的收少。","notes":[]},{"n":18,"t":"用俄梅珥量一量，多收的没有余，少收的也没有缺；各人都按着自己的食量收集。","notes":[]},{"n":19,"t":"摩西对他们说：“任何人都不可以把所收的留到早晨。”","notes":[]},{"n":20,"t":"然而他们不听从摩西，当中有人把食物留到早晨，食物就生虫发臭了。摩西就向他们发怒。","notes":[]},{"n":21,"t":"他们每日早晨按着各人的食量收集；太阳一发热，食物就融化了。","notes":[]},{"n":22,"t":"到第六天，他们收集了双倍的食物，每个人二俄梅珥。会众的官长来告诉摩西，","notes":[]},{"n":23,"t":"摩西对他们说：“耶和华吩咐：‘明天是安息日，是向耶和华守的圣安息日。你们要烤的就烤，要煮的就煮，所剩下的都留到早晨。’”","notes":[]},{"n":24,"t":"他们就照摩西的吩咐把剩下的留到早晨，这些食物既不发臭，里头也没有生虫。","notes":[]},{"n":25,"t":"摩西说：“你们今天就吃这些吧！因为今天是向耶和华守的安息日，你们在野外必找不着食物了。","notes":[]},{"n":26,"t":"六天可以收集，第七天是安息日，这一天什么也没有了。”","notes":[]},{"n":27,"t":"第七天，百姓中有人出去收，什么也找不着。","notes":[]},{"n":28,"t":"耶和华对摩西说：“你们不肯遵守我的诫令和教导，要到几时呢？","notes":[]},{"n":29,"t":"你们看，耶和华既然将安息日赐给你们，所以第六天他就赐给你们两天的食物，第七天各人都要留在自己的地方，不许任何人从这里出去。”","notes":[]},{"n":30,"t":"于是百姓在第七天安息了。","notes":[]},{"n":31,"t":"以色列家给这食物取名叫吗哪，它的样子像芫荽子，颜色是白的，吃起来像和蜜的薄饼。","notes":[]},{"n":32,"t":"摩西说：“耶和华所吩咐的是这样：‘要装满一俄梅珥的吗哪留给你们的后代，使他们可以看见我领你们出埃及地的时候，在旷野所给你们吃的食物。’”","notes":[]},{"n":33,"t":"摩西对亚伦说：“你拿一个罐子，装满一俄梅珥的吗哪，存在耶和华面前，留给你们的后代。”","notes":[]},{"n":34,"t":"耶和华怎么吩咐摩西，亚伦就照样做，把吗哪存留作见证。","notes":["“作见证”或译“在法柜前”。"]},{"n":35,"t":"以色列人吃吗哪共四十年，直到进入有人居住的地方；他们吃吗哪，直到迦南地的边境。","notes":[]},{"n":36,"t":"一俄梅珥是一伊法的十分之一。","notes":[]}]},"17":{"heading":"磐石出水","verses":[{"n":1,"t":"以色列全会众遵照耶和华的吩咐，从汛的旷野一段一段地往前行。他们在利非订安营，但百姓没有水喝。","notes":[]},{"n":2,"t":"百姓就与摩西争闹，说：“给我们水喝吧！”摩西对他们说：“你们为什么与我争闹呢？你们为什么试探耶和华呢？”","notes":[]},{"n":3,"t":"百姓在那里口渴要喝水，就向摩西发怨言，说：“你为什么把我们从埃及领出来，使我们和我们的儿女，以及牲畜都渴死呢？”","notes":[]},{"n":4,"t":"摩西就呼求耶和华说：“我要怎样对待这百姓呢？他们差一点就要拿石头打死我了。”","notes":[]},{"n":5,"t":"耶和华对摩西说：“你带着以色列的几个长老，走在百姓前面，手里拿着你先前击打尼罗河的杖，去吧！","notes":[]},{"n":6,"t":"看哪，我要在何烈的磐石那里，站在你面前。你要击打磐石，水就会从磐石流出来，给百姓喝。”摩西就在以色列的长老眼前这样做了。","notes":[]},{"n":7,"t":"他给那地方起名叫玛撒，又叫米利巴，因为以色列人在那里争闹，并且试探耶和华，说：“耶和华是否在我们中间呢？”","notes":["“玛撒”意思是“试探”。","“米利巴”意思是“争闹”。"]},{"n":8,"t":"那时，亚玛力来到利非订，和以色列争战。","notes":[],"heads":["击败亚玛力人"]},{"n":9,"t":"摩西对约书亚说：“你为我们选出人来，出去和亚玛力争战。明天我要站在山顶上，手里拿着神的杖。”","notes":[]},{"n":10,"t":"于是，约书亚照着摩西对他所说的话去做，和亚玛力争战。摩西、亚伦和户珥都上了山顶。","notes":[]},{"n":11,"t":"摩西何时举手，以色列就得胜；何时垂手，亚玛力就得胜。","notes":[]},{"n":12,"t":"但摩西的双手沉重，他们就搬一块石头来放在他下面，他就坐在上面。亚伦与户珥扶着他的手，一个在这边，一个在那边，他的手就稳住，直到日落。","notes":[]},{"n":13,"t":"约书亚用刀打败了亚玛力和他的百姓。","notes":[]},{"n":14,"t":"耶和华对摩西说：“你要把这事记录在书上作纪念，又念给约书亚听：我要把亚玛力的名字从天下全然涂去。”","notes":[]},{"n":15,"t":"摩西筑了一座坛，起名叫“耶和华尼西”。","notes":["“耶和华尼西”意思是“耶和华是我的旌旗”。"]},{"n":16,"t":"他说：“我指着耶和华的宝座发誓，耶和华必世世代代和亚玛力争战。”","notes":["“我指着...发誓”：原文直译“向耶和华的宝座举手”。"]}]},"18":{"heading":"叶特罗的探视","verses":[{"n":1,"t":"摩西的岳父，米甸祭司叶特罗，听见神为摩西和为他百姓以色列所行的一切事，就是耶和华将以色列从埃及领了出来。","notes":[]},{"n":2,"t":"摩西的岳父叶特罗带着西坡拉，就是摩西先前送回家的妻子，","notes":[]},{"n":3,"t":"又带着她的两个儿子：一个名叫革舜，因为摩西说：“我在外地作了寄居者”；","notes":[]},{"n":4,"t":"另一个名叫以利以谢，因为他说：“我父亲的神帮助我，救我脱离法老的刀。”","notes":[]},{"n":5,"t":"摩西的岳父叶特罗带着摩西的妻子和两个儿子来到神的山，就是摩西在旷野安营的地方。","notes":[]},{"n":6,"t":"他对摩西说：“我是你岳父叶特罗，带着你的妻子和两个儿子来到你这里。”","notes":["“他对摩西说：我是”：撒玛利亚五经、七十士译本和其他古译本是“有人对摩西说：看哪”。"]},{"n":7,"t":"摩西迎接他的岳父，向他下拜，亲他，彼此问安，然后进入帐棚。","notes":[]},{"n":8,"t":"摩西将耶和华为以色列的缘故向法老和埃及人所行的一切事，他们在路上遭遇的一切艰难，以及耶和华怎样搭救他们，都述说给他的岳父听。","notes":[]},{"n":9,"t":"叶特罗因耶和华待以色列的一切恩惠，就是拯救他们脱离埃及人的手，就非常喜乐。","notes":[]},{"n":10,"t":"叶特罗说：“耶和华是应当称颂的，他救了你们脱离埃及人和法老的手，将这百姓从埃及人的手里救出来。","notes":["七十士译本没有“将这百姓从埃及人的手里救出来”。"]},{"n":11,"t":"现在，从埃及人狂傲地对待以色列人这件事上，我知道耶和华比万神更大。”","notes":[]},{"n":12,"t":"摩西的岳父叶特罗把燔祭和祭物献给神。亚伦和以色列的众长老都来了，与摩西的岳父在神面前吃饭。","notes":[]},{"n":13,"t":"第二天，摩西坐着审判百姓，百姓从早到晚站在摩西的旁边。","notes":[],"heads":["选立百姓的官长"]},{"n":14,"t":"摩西的岳父看见他为百姓所做的一切事，就说：“你为百姓所做的，这是什么事呢？你为什么独自一人坐着，而众百姓从早到晚都站在你旁边呢？”","notes":[]},{"n":15,"t":"摩西对岳父说：“这是因为百姓到我这里来求问神。","notes":[]},{"n":16,"t":"他们有事的时候，就到我这里来，我就在双方之间作判决；我又叫他们知道神的律例和法度。”","notes":[]},{"n":17,"t":"摩西的岳父对他说：“你这样做不好。","notes":[]},{"n":18,"t":"你和这些与你在一起的百姓都必疲惫，因为这事太重，你独自一人做不了。","notes":[]},{"n":19,"t":"现在，听我的话，我给你出个主意，愿神与你同在。你要代替百姓到神面前，将事件带到神那里，","notes":[]},{"n":20,"t":"又要用律例和法度警戒他们，指示他们当行的道，当做的事。","notes":[]},{"n":21,"t":"你也要从百姓中选出有才能的人，敬畏神、诚实可靠、恨恶不义之财的人，派他们作千夫长、百夫长、五十夫长、十夫长来管理百姓。","notes":[]},{"n":22,"t":"他们要随时审判百姓；重大的事要送到你这里，小事就由他们自行判决。这样，你就可以轻省一些，他们可以与你分担。","notes":[]},{"n":23,"t":"你若这样做，神也这样吩咐你，你就能承受得住，众百姓也可以和睦地回到自己的地方。”","notes":[]},{"n":24,"t":"摩西听了他岳父的话，照着他所说的一切去做。","notes":[]},{"n":25,"t":"摩西从以色列人中选出有才能的人，立他们为百姓的领袖，作千夫长、百夫长、五十夫长、十夫长。","notes":[]},{"n":26,"t":"他们随时审判百姓：难断的事就送到摩西那里，各样小事就由他们自行判决。","notes":[]},{"n":27,"t":"于是，摩西给他的岳父送行，他就回到本地去了。","notes":[]}]},"19":{"heading":"以色列人在西奈山","verses":[{"n":1,"t":"以色列人出埃及地以后，第三个月的初一，就在那一天他们来到了西奈的旷野。","notes":[]},{"n":2,"t":"他们从利非订起程，来到西奈的旷野，在那里的山下安营。","notes":[]},{"n":3,"t":"摩西到神那里，耶和华从山上呼唤他说：“你要这样告诉雅各家，对以色列人说：","notes":[]},{"n":4,"t":"‘我向埃及人所行的事，你们都看见了， 我如鹰将你们背在翅膀上，带你们来归我。","notes":[]},{"n":5,"t":"如今你们若真的听从我的话，遵守我的约，就要在万民中作属我的子民，因为全地都是我的。","notes":["“子民”：原文是“宝贵的产业”。"]},{"n":6,"t":"你们要归我作祭司的国度，为神圣的国民。’这些话你要告诉以色列人。”","notes":[]},{"n":7,"t":"摩西去召了百姓中的长老来，将耶和华吩咐他的话当面告诉他们。","notes":[]},{"n":8,"t":"百姓都同声回答：“凡耶和华所说的，我们一定遵行。”摩西就将百姓的话回覆耶和华。","notes":[]},{"n":9,"t":"耶和华对摩西说：“看哪，我要在密云中临到你那里，叫百姓在我与你说话的时候可以听见，就可以永远相信你了。”于是，摩西将百姓的话禀告耶和华。","notes":[]},{"n":10,"t":"耶和华对摩西说：“你往百姓那里去，使他们今天明天分别为圣，又叫他们洗衣服。","notes":[]},{"n":11,"t":"第三天要预备好，因为第三天耶和华要在众百姓眼前降临在西奈山。","notes":[]},{"n":12,"t":"你要在山的周围给百姓划定界限，说：‘你们当谨慎，不可上山去，也不可摸山的边界。凡摸这山的，必被处死。","notes":[]},{"n":13,"t":"不可用手碰他，要用石头打死，或射死；无论是人是牲畜，都不可活。’到角声拉长的时候，他们才可到山脚来。”","notes":[]},{"n":14,"t":"摩西下山到百姓那里去，使他们分别为圣，他们就洗衣服。","notes":[]},{"n":15,"t":"他对百姓说：“第三天要预备好；不可亲近女人。”","notes":[]},{"n":16,"t":"到了第三天早晨，山上有雷轰、闪电和密云，并且角声非常响亮，营中的百姓尽都战抖。","notes":[]},{"n":17,"t":"摩西率领百姓出营迎见神，都站在山下。","notes":[]},{"n":18,"t":"西奈山全山冒烟，因为耶和华在火中降临山上。山的烟雾上腾，仿佛烧窑，整座山剧烈震动。","notes":[]},{"n":19,"t":"角声越来越响，摩西说话，神以声音回答他。","notes":[]},{"n":20,"t":"耶和华降临在西奈山顶上，耶和华召摩西上山顶，摩西就上去了。","notes":[]},{"n":21,"t":"耶和华对摩西说：“你下去警告百姓，免得他们闯过来看耶和华，就会有许多人死亡。","notes":[]},{"n":22,"t":"那些亲近耶和华的祭司也要把自己分别为圣，免得耶和华忽然出来击杀他们。”","notes":[]},{"n":23,"t":"摩西对耶和华说：“百姓不能上西奈山，因为你已经警告我们说：‘要在山的周围划定界限，使山成圣。’”","notes":[]},{"n":24,"t":"耶和华对他说：“下去吧，你要和亚伦一起上来；只是祭司和百姓不可闯上来到耶和华这里，免得耶和华忽然出来击杀他们。”","notes":[]},{"n":25,"t":"于是，摩西下到百姓那里告诉他们。","notes":[]}]},"20":{"heading":"十诫","verses":[{"n":1,"t":"神吩咐这一切的话，说：","notes":[]},{"n":2,"t":"“我是耶和华－你的神，曾将你从埃及地为奴之家领出来。","notes":[]},{"n":3,"t":"“除了我以外，你不可有别的神。","notes":[]},{"n":4,"t":"“不可为自己雕刻偶像，也不可做什么形像，仿佛上天、下地和地底下水中的百物。","notes":[]},{"n":5,"t":"不可跪拜那些像，也不可事奉它们，因为我耶和华─你的神是忌邪的神。恨我的，我必惩罚他们的罪，自父及子，直到三、四代；","notes":["“忌邪”：原文是“妒忌”，意思是“不容许有对立的神明”。"]},{"n":6,"t":"爱我，守我诫命的，我必向他们施慈爱，直到千代。","notes":[]},{"n":7,"t":"“不可妄称耶和华－你神的名，因为妄称耶和华名的，耶和华必不以他为无罪。","notes":[]},{"n":8,"t":"“当记念安息日，守为圣日。","notes":[]},{"n":9,"t":"六日要劳碌做你一切的工，","notes":[]},{"n":10,"t":"但第七日是向耶和华─你的神当守的安息日。这一日你和你的儿女、奴仆、婢女、牲畜，以及你城里寄居的客旅，都不可做任何的工。","notes":[]},{"n":11,"t":"因为六日之内，耶和华造天、地、海和其中的万物，第七日就安息了；所以耶和华赐福与安息日，定为圣日。","notes":[]},{"n":12,"t":"“当孝敬父母，使你的日子在耶和华－你神所赐你的地上得以长久。","notes":[]},{"n":13,"t":"“不可杀人。","notes":[]},{"n":14,"t":"“不可奸淫。","notes":[]},{"n":15,"t":"“不可偷盗。","notes":[]},{"n":16,"t":"“不可做假见证陷害你的邻舍。","notes":[]},{"n":17,"t":"“不可贪恋你邻舍的房屋；不可贪恋你邻舍的妻子、奴仆、婢女、牛驴，以及他一切所有的。”","notes":[]},{"n":18,"t":"众百姓见雷轰、闪电、角声、山上冒烟，百姓看见就都战抖，远远站着。","notes":["“看见”：撒玛利亚五经、七十士译本和其他古译本是“害怕”。"],"heads":["众民战惧"]},{"n":19,"t":"他们对摩西说：“请你向我们说话，我们必听；不要让神向我们说话，免得我们死亡。”","notes":[]},{"n":20,"t":"摩西对百姓说：“不要害怕；因为神降临是要考验你们，要你们敬畏他，不致犯罪。”","notes":[]},{"n":21,"t":"于是百姓远远站着，但摩西却挨近神所在的幽暗中。","notes":[]},{"n":22,"t":"耶和华对摩西说：“你要向以色列人这样说：‘你们亲自看见我从天上向你们说话了。","notes":[],"heads":["祭坛的条例"]},{"n":23,"t":"你们不可为我制造偶像，不可为自己造任何金银的神像。","notes":[]},{"n":24,"t":"你要为我筑一座土坛，在上面献牛羊为燔祭和平安祭。凡在我叫你记念我名的地方，我必到那里赐福给你。","notes":[]},{"n":25,"t":"你若为我筑一座石坛，不可用凿过的石头，因为你在石头上动了工具，就使坛污秽了。","notes":[]},{"n":26,"t":"你不可用台阶上我的坛，免得露出你的下体来。’”","notes":[]}]},"21":{"heading":"奴婢的条例","verses":[{"n":1,"t":"“你在百姓面前所要立的典章是这样：","notes":[]},{"n":2,"t":"“你若买希伯来人作奴仆，他服事你六年，第七年他可以自由，白白地离去。","notes":[]},{"n":3,"t":"他若单身来就可以单身去；他若是有妻子的，他的妻子可以同他离去。","notes":[]},{"n":4,"t":"若他主人给他娶了妻，妻子为他生了儿子或女儿，妻子和儿女要归主人，他要独自离去。","notes":[]},{"n":5,"t":"倘若奴仆声明：‘我爱我的主人和我的妻子儿女，不愿意自由离去。’","notes":[]},{"n":6,"t":"他的主人就要带他到审判官前，再带他到门或门框那里，用锥子穿他的耳朵，他就要永远服事主人。","notes":["“审判官”或译“神”；22节同。"]},{"n":7,"t":"“人若卖女儿作婢女，婢女不可像男的奴仆那样离去。","notes":[]},{"n":8,"t":"主人若选定她归自己，后来看不顺眼，就要允许她赎身；主人既然对她失信，就没有权柄把她卖给外邦人。","notes":[]},{"n":9,"t":"主人若选定她给自己的儿子，就当照女儿的规矩对待她。","notes":[]},{"n":10,"t":"若另娶一个，她的饮食、衣服和房事不可减少。","notes":[]},{"n":11,"t":"若不向她行这三样，她就可以白白离去，不必付赎金。”","notes":[]},{"n":12,"t":"“打人致死的，必被处死。","notes":[],"heads":["惩罚暴行的条例"]},{"n":13,"t":"他若不是出于预谋，而是神交在他手中，我就设立一个地方，让他可以逃到那里。","notes":["“出于预谋”：原文直译“埋伏”。"]},{"n":14,"t":"人若蓄意用诡计杀了他的邻舍，就是逃到我的坛那里，也当把他捉去处死。","notes":[]},{"n":15,"t":"“打父母的，必被处死。","notes":[]},{"n":16,"t":"“诱拐人口的，无论是把人卖了，或是扣留在他手中，必被处死。","notes":[]},{"n":17,"t":"“咒骂父母的，必被处死。","notes":[]},{"n":18,"t":"“人若彼此争吵，一个用石头或拳头打另一个，被打的人没有死去，却要躺卧在床，","notes":[]},{"n":19,"t":"若他还能起来扶杖行走，那打他的可免处刑，却要赔偿他不能工作的损失，并要把他完全医好。","notes":[]},{"n":20,"t":"“人若用棍子打奴仆或婢女，当场死在他的手下，他必受报应。","notes":[]},{"n":21,"t":"若能撑过一两天，主人就不必受惩罚，因为那是他的财产。","notes":[]},{"n":22,"t":"“人若彼此打斗，伤害有孕的妇人，以致胎儿掉了出来，随后却无别的伤害，那伤害她的人，总要按妇人的丈夫所提出的，照审判官所裁定的赔偿。","notes":[]},{"n":23,"t":"若有别的伤害，就要以命抵命，","notes":[]},{"n":24,"t":"以眼还眼，以牙还牙，以手还手，以脚还脚，","notes":[]},{"n":25,"t":"以灼伤还灼伤，以损伤还损伤，以鞭打还鞭打。","notes":[]},{"n":26,"t":"“人若打奴仆或婢女的眼睛，毁了一只，就要因他的眼让他自由离去。","notes":[]},{"n":27,"t":"若打掉了奴仆或婢女的一颗牙，就要因他的牙让他自由离去。”","notes":[]},{"n":28,"t":"“牛若抵死男人或女人，总要用石头打死那牛，却不可吃它的肉；牛的主人可免处刑。","notes":[],"heads":["物主的责任"]},{"n":29,"t":"倘若那牛向来是抵人的，牛的主人虽然受过警告，仍不把它拴好，以致把男人或女人抵死，牛要用石头打死，主人也要被处死。","notes":[]},{"n":30,"t":"若罚他付赎命的赔款，他就要照所罚的数目赎他的命。","notes":[]},{"n":31,"t":"牛若抵了男孩或女孩，也要照这条例处理。","notes":[]},{"n":32,"t":"牛若抵了奴仆或婢女，就要把三十舍客勒银子给奴仆的主人，牛要用石头打死。","notes":[]},{"n":33,"t":"“人若敞开井口，或挖井不盖住它，有牛或驴掉进井里，","notes":[]},{"n":34,"t":"井的主人要拿钱赔偿牲畜的主人，死牲畜要归自己。","notes":[]},{"n":35,"t":"“人的牛若抵死邻舍的牛，他们就要卖了那活牛，平分价钱；也要平分死牛。","notes":[]},{"n":36,"t":"若这牛向来是以好抵人出名的，主人竟不把牛拴好，他必要以牛赔牛，死牛却归自己。”","notes":[]}]},"22":{"heading":"赔偿的条例","verses":[{"n":1,"t":"“人若偷牛或羊，无论是宰了或卖了，他就要以五牛赔一牛， 四羊赔一羊。","notes":[]},{"n":2,"t":"贼挖洞，若被发现而被打死，打的人没有流血的罪。","notes":[]},{"n":3,"t":"若太阳已经出来，打的人就有流血的罪。贼总要赔偿，若他一无所有，就要被卖来还他所偷的东西。","notes":[]},{"n":4,"t":"若发现他所偷的，无论是牛、驴，或羊，在他手中还活着，他就要加倍赔偿。","notes":[]},{"n":5,"t":"“人若在田间或葡萄园里牧放牲畜，任凭牲畜上别人田里去吃，他就要拿自己田间和葡萄园里上好的赔偿。","notes":["“去吃”：七十士译本是“去吃，他要拿自己田里的作物来赔偿；倘若牲畜把整片作物吃光了”。"]},{"n":6,"t":"“若火冒出，延烧到荆棘，以致将堆积的禾捆，直立的庄稼，或田地，都烧尽了，那点火的必要赔偿。","notes":[]},{"n":7,"t":"“人若将银钱或物件托邻舍保管，东西从这人的家中被偷去，若找到了贼，贼要加倍赔偿；","notes":[]},{"n":8,"t":"若找不到贼，这家的主人就要到审判官那里，声明自己没有伸手拿邻舍的物件。","notes":["“审判官”或译“神”；9节同。","“声明”或译“宣誓作证”。"]},{"n":9,"t":"“关于任何侵害的案件，无论是为牛、驴、羊、衣服，或任何失物，有一人说：‘这是我的’，双方就要将案件带到审判官面前，审判官定谁有罪，谁就要加倍赔偿给他的邻舍。","notes":[]},{"n":10,"t":"“人将驴、牛、羊，或别的牲畜托邻舍看管，若牲畜死亡，受了伤，或被抢走，无人看见，","notes":[]},{"n":11,"t":"双方要在耶和华前起誓，受托人要表明自己没有伸手拿邻舍的东西，原主要接受誓言，受托人不必赔偿。","notes":[]},{"n":12,"t":"牲畜若从受托人那里被偷去，他就要赔偿原主；","notes":[]},{"n":13,"t":"若被野兽撕碎，受托人要带回来作证据，被撕碎的就不必赔偿。","notes":[]},{"n":14,"t":"“人若向邻舍借牲畜，所借的或伤或死，原主没有在场，借的人总要赔偿。","notes":["原文没有“牲畜”。"]},{"n":15,"t":"若原主在场，借的人不必赔偿；若是租用的，只要付租金。”","notes":["“只要付租金”：原文是“它来是为了租金”。"]},{"n":16,"t":"“人若引诱没有订婚的处女，与她同寝，他就必须交出聘礼，娶她为妻。","notes":[],"heads":["道德和宗教的条例"]},{"n":17,"t":"若女子的父亲坚决不将女子给他，他就要按着处女的聘礼交出钱来。","notes":[]},{"n":18,"t":"“行邪术的女人，不可让她存活。","notes":[]},{"n":19,"t":"“凡与兽交合的，必被处死。","notes":[]},{"n":20,"t":"“向别神献祭，不单单献给耶和华的，那人必要灭绝。","notes":[]},{"n":21,"t":"“不可亏待寄居的，也不可欺压他，因为你们在埃及地也作过寄居的。","notes":[]},{"n":22,"t":"不可苛待寡妇和孤儿；","notes":[]},{"n":23,"t":"若你确实苛待他，他向我苦苦哀求，我一定会听他的呼求，","notes":[]},{"n":24,"t":"并要发烈怒，用刀杀你们，使你们的妻子成为寡妇，儿女成为孤儿。","notes":[]},{"n":25,"t":"“我的子民中有困苦人在你那里，你若借钱给他，不可如放债的向他取利息。","notes":[]},{"n":26,"t":"你果真拿了邻舍的外衣作抵押，也要在日落前还给他；","notes":[]},{"n":27,"t":"因为他只有这一件用来作被子，是他蔽体的衣服。他还可以拿什么睡觉呢？当他哀求我，我就应允，因为我是有恩惠的。","notes":[]},{"n":28,"t":"“不可毁谤神；也不可诅咒你百姓的领袖。","notes":[]},{"n":29,"t":"“不可迟延献你的庄稼、酒和油。“要将你头生的儿子归给我。","notes":["“你的庄稼、酒和油”：原文直译“你的丰收和你的汁液”。"]},{"n":30,"t":"你的牛羊也要照样做：七天当跟着它母亲，第八天你要把它归给我。","notes":[]},{"n":31,"t":"“你们要分别为圣归给我。因此，田间被野兽撕裂的肉，你们不可吃，要把它丢给狗。”","notes":[]}]},"23":{"heading":"正义和公正","verses":[{"n":1,"t":"“不可散布谣言；不可与恶人连手作恶意的见证。","notes":[]},{"n":2,"t":"不可附和群众作恶；不可在诉讼中附和群众歪曲公正，作歪曲的见证；","notes":[]},{"n":3,"t":"也不可在诉讼中偏袒贫寒人。","notes":[]},{"n":4,"t":"“若遇见你仇敌的牛或驴迷了路，务必牵回来交给他。","notes":[]},{"n":5,"t":"若看见恨你的人的驴被压在重驮之下，不可走开，务要和他一同卸下驴的重驮。","notes":[]},{"n":6,"t":"“不可在贫穷人的诉讼中屈枉正直。","notes":[]},{"n":7,"t":"当远离诬告的事。不可杀害无辜和义人，因我必不以恶人为义。","notes":[]},{"n":8,"t":"不可接受贿赂，因为贿赂能使明眼人变瞎，又能曲解义人的证词。","notes":[]},{"n":9,"t":"“不可欺压寄居的，因为你们在埃及地作过寄居的，知道寄居者的心情。”","notes":[]},{"n":10,"t":"“六年你要耕种田地，收集地的出产。","notes":[],"heads":["安息年和安息日"]},{"n":11,"t":"只是第七年你要让地歇息，不耕不种，使你百姓中的贫穷人有吃的；他们吃剩的，野兽可以吃。你的葡萄园和橄榄园也要照样办理。","notes":[]},{"n":12,"t":"“六日你要做工，第七日要安息，使牛、驴可以歇息，也让你使女的儿子和寄居的可以恢复精力。","notes":[]},{"n":13,"t":"“凡我对你们说的话，你们都要谨守。别神的名，你不可提，也不可用口说给人听。”","notes":[]},{"n":14,"t":"“一年三次，你要向我守节。","notes":[],"heads":["三大节期"]},{"n":15,"t":"你要守除酵节，照我所吩咐你的，在亚笔月内所定的日期吃无酵饼七天，因为你是在这月离开了埃及。谁也不可空手来朝见我。","notes":[]},{"n":16,"t":"你要守收割节，收田间所种、劳碌所得初熟之物。你年底收藏田间劳碌所得时，要守收藏节。","notes":[]},{"n":17,"t":"所有的男丁都要一年三次朝见主耶和华。","notes":[]},{"n":18,"t":"“不可将我祭牲的血和有酵之物一同献上，也不可将我节期中祭牲的脂肪留到早晨。","notes":[]},{"n":19,"t":"“要把地里最好的初熟之物带到耶和华－你神的殿中。“不可用母山羊的奶来煮它的小山羊。”","notes":[]},{"n":20,"t":"“看哪，我要差遣使者在你前面，在路上保护你，领你到我所预备的地方。","notes":[],"heads":["应许和警戒"]},{"n":21,"t":"你们要在他面前谨慎，听从他的话。不可抗拒他，否则他必不赦免你们的过犯，因为我的名在他身上。","notes":["“抗拒”：原文是“使他受苦”。"]},{"n":22,"t":"“你若真的听从他的话，照我一切所说的去做，我就以你的仇敌为仇敌，以你的敌人为敌人。","notes":[]},{"n":23,"t":"“我的使者要走在你前面，领你到亚摩利人、赫人、比利洗人、迦南人、希未人、耶布斯人那里，我必将他们除灭。","notes":[]},{"n":24,"t":"你不可跪拜事奉他们的神明，也不可随从他们的习俗，却要彻底废除，完全打碎他们的柱像。","notes":[]},{"n":25,"t":"你们要事奉耶和华－你们的神，他必赐福给你的粮食和水，也必从你中间除去疾病。","notes":[]},{"n":26,"t":"你境内必没有流产的、不生育的。我要使你享满你年日的数目。","notes":[]},{"n":27,"t":"凡你所到的地方，我要使那里的众百姓在你面前惊慌失措，又要使你所有的仇敌转身逃跑。","notes":[]},{"n":28,"t":"我要派瘟疫在你的前面，把希未人、迦南人、赫人从你面前赶出去。","notes":["“瘟疫”或译“黄蜂”。"]},{"n":29,"t":"我不在一年之内把他们从你面前赶出去，恐怕地会荒废，野地的走兽增多危害你。","notes":[]},{"n":30,"t":"我要逐渐把他们从你面前赶出去，直到你的人数增多，承受那地为业。","notes":[]},{"n":31,"t":"我要定你的疆界，从红海直到非利士海，从旷野直到大河。我要把那地的居民交在你手中，你要把他们从你面前赶出去。","notes":[]},{"n":32,"t":"不可跟他们和他们的神明立约。","notes":[]},{"n":33,"t":"他们不可住在你的地上，免得他们使你得罪我。你若事奉他们的神明，必成为你的圈套。”","notes":[]}]},"24":{"heading":"立约的血","verses":[{"n":1,"t":"耶和华对摩西说：“你和亚伦、拿答、亚比户，以及以色列长老中的七十人，都要上到耶和华这里来，远远地下拜。","notes":[]},{"n":2,"t":"只有摩西可以接近耶和华，其他的人却不可接近；百姓也不可和他一同上来。”","notes":[]},{"n":3,"t":"摩西下山，向百姓陈述耶和华一切的命令和典章。众百姓齐声说：“耶和华所吩咐的一切，我们都必遵行。”","notes":[]},{"n":4,"t":"摩西将耶和华一切的命令都写下来。他清早起来，在山脚筑了一座坛，按着以色列十二支派立了十二根石柱。","notes":[]},{"n":5,"t":"他差派以色列的年轻人去献燔祭，又宰牛献给耶和华为平安祭。","notes":[]},{"n":6,"t":"摩西将血的一半盛在盆中，另一半洒在坛上。","notes":[]},{"n":7,"t":"然后，他拿起约书来，念给百姓听。他们说：“耶和华所吩咐的一切，我们都必遵行，也必听从。”","notes":[]},{"n":8,"t":"摩西把血洒在百姓身上，说：“看哪！这是立约的血，是耶和华按照这一切的命令和你们立约的凭据。”","notes":[]},{"n":9,"t":"摩西、亚伦、拿答、亚比户，以及以色列长老中的七十人都上去，","notes":[]},{"n":10,"t":"看见了以色列的神。在他的脚下，仿佛有蓝宝石铺道，明净如天。","notes":[]},{"n":11,"t":"他不把手伸在以色列领袖的身上。他们瞻仰神，又吃又喝。","notes":[]},{"n":12,"t":"耶和华对摩西说：“你上山到我这里来，就在那里，我要将石版，就是我所写的律法和诫命赐给你，使你可以教导他们。”","notes":[],"heads":["摩西在西奈山上"]},{"n":13,"t":"摩西和他的助手约书亚站起来；摩西上了神的山。","notes":[]},{"n":14,"t":"摩西对长老们说：“你们在这里等我们，直到我们再回到你们这里。看哪，亚伦和户珥与你们同在。谁有诉讼，可以去找他们。”","notes":[]},{"n":15,"t":"摩西上山，有云彩把山遮盖。","notes":[]},{"n":16,"t":"耶和华的荣耀驻在西奈山，云彩遮盖了山六天，第七天他从云中呼叫摩西。","notes":[]},{"n":17,"t":"耶和华的荣耀在山顶上，在以色列人眼前，形状如吞噬的火。","notes":[]},{"n":18,"t":"摩西进入云中，登上了山。摩西在山上四十昼夜。","notes":[]}]},"25":{"heading":"为圣所奉献","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人献礼物给我。凡甘心乐意献给我的礼物，你们都可以收下。","notes":[]},{"n":3,"t":"要从他们收的礼物是：金、银、铜，","notes":[]},{"n":4,"t":"蓝色、紫色、朱红色纱，细麻，山羊毛，","notes":["原文没有“纱”；本卷书下同。"]},{"n":5,"t":"染红的公羊皮、精美的皮料，金合欢木，","notes":[]},{"n":6,"t":"点灯的油，做膏油的香料、做香的香料，","notes":[]},{"n":7,"t":"红玛瑙与宝石，可以镶嵌在以弗得和胸袋上。","notes":[]},{"n":8,"t":"他们要为我造圣所，使我住在他们中间。","notes":[]},{"n":9,"t":"你们要按照我指示你的，帐幕和其中一切器具的样式，照样去做。”","notes":[]},{"n":10,"t":"“他们要用金合欢木做一个柜子，长二肘半，宽一肘半，高一肘半。","notes":[],"heads":["约柜"]},{"n":11,"t":"你要把它里里外外包上纯金，四围要镶上金边。","notes":[]},{"n":12,"t":"要铸造四个金环，安在柜子的四脚上；这边两个环，那边两个环。","notes":[]},{"n":13,"t":"要用金合欢木做两根杠，包上金子。","notes":[]},{"n":14,"t":"要把杠穿过柜旁的环，以便抬柜。","notes":[]},{"n":15,"t":"这杠要留在柜的环内，不可抽出来。","notes":[]},{"n":16,"t":"要把我所要赐给你的法版放在柜里。","notes":["“法版”：原文是“见证”，指“立约的法度”；下同。"]},{"n":17,"t":"要用纯金做一个柜盖，长二肘半，宽一肘半。","notes":["“柜盖”：原意“盖住”，指“盖住罪”，后来也称为“施恩座”；本卷书下同。"]},{"n":18,"t":"要造两个用金子锤出的基路伯，从柜盖的两端锤出它们。","notes":[]},{"n":19,"t":"这端锤出一个基路伯，那端锤出一个基路伯；从柜盖的两端锤出两个基路伯。","notes":[]},{"n":20,"t":"二基路伯的翅膀要向上张开，用翅膀遮住柜盖，脸要彼此相对；基路伯的脸要朝向柜盖。","notes":[]},{"n":21,"t":"要把柜盖安在柜的上边，又要把我所要赐给你的法版放在柜里。","notes":[]},{"n":22,"t":"我要在那里与你相会，并要从法版之柜的柜盖上，两个基路伯的中间，将我要吩咐以色列人的一切事告诉你。”","notes":[]},{"n":23,"t":"“你要用金合欢木做一张供桌，长二肘，宽一肘，高一肘半，","notes":[],"heads":["供桌"]},{"n":24,"t":"把它包上纯金，四围镶上金边。","notes":[]},{"n":25,"t":"供桌的四围各做一掌宽的边缘，边缘周围要镶上金边。","notes":[]},{"n":26,"t":"要为供桌做四个金环，把环安在四个桌脚的四角上。","notes":[]},{"n":27,"t":"环要靠近边缘，以便穿杠抬供桌。","notes":[]},{"n":28,"t":"要用金合欢木做两根杠，包上金子，用来抬供桌。","notes":[]},{"n":29,"t":"要用纯金做桌上的盘、碟，以及浇酒祭的壶和杯。","notes":[]},{"n":30,"t":"要把供饼摆在桌上，常在我面前。”","notes":[]},{"n":31,"t":"“你要造一座用纯金锤出的灯台。灯台的座、干、杯、花萼和花瓣，都要和灯台接连一块。","notes":[],"heads":["灯台"]},{"n":32,"t":"灯台两旁要伸出六根枝子：这边三根，那边三根。","notes":[]},{"n":33,"t":"这边枝子上有三个杯，形状像杏花，有花萼有花瓣；那边枝子上也有三个杯，形状像杏花，有花萼有花瓣。从灯台伸出来的六根枝子都是如此。","notes":[]},{"n":34,"t":"灯台本身要有四个杯，形状像杏花，有花萼有花瓣。","notes":[]},{"n":35,"t":"灯台的第一对枝子下面有花萼，灯台的第二对枝子下面有花萼，灯台的第三对枝子下面也有花萼；灯台伸出的六根枝子都是如此。","notes":[]},{"n":36,"t":"花萼和枝子都要和灯台接连一块，全是从一块纯金锤出来的。","notes":[]},{"n":37,"t":"要做灯台的七盏灯，灯要点燃，照亮前面。","notes":[]},{"n":38,"t":"要用纯金做灯剪和灯盘。","notes":[]},{"n":39,"t":"做灯台和这一切的器具要用一他连得纯金。","notes":[]},{"n":40,"t":"要谨慎，照着在山上指示你的样式去做。”","notes":[]}]},"26":{"heading":"帐幕","verses":[{"n":1,"t":"“你要用十幅幔子做帐幕。这些幔子要用搓的细麻和蓝色、紫色、朱红色纱织成，并且以刺绣的手艺绣上基路伯。","notes":[]},{"n":2,"t":"每幅幔子要长二十八肘，每幅幔子宽四肘，全部的幔子尺寸都要一样。","notes":[]},{"n":3,"t":"这五幅幔子要彼此相连；那五幅幔子也彼此相连。","notes":[]},{"n":4,"t":"在这一组相连幔子的末幅边上要缝蓝色的钮环；在另一组相连幔子的末幅边上也要照样做。","notes":[]},{"n":5,"t":"这幅幔子上要缝五十个钮环，另一组相连幔子的末幅上也缝五十个钮环，环环相对。","notes":[]},{"n":6,"t":"要做五十个金钩，用钩子使幔子彼此相连，成为一个帐幕。","notes":[]},{"n":7,"t":"“你要用山羊毛织十一幅幔子来作帐幕的罩棚。","notes":[]},{"n":8,"t":"每幅幔子要长三十肘，每幅幔子宽四肘；十一幅幔子的尺寸都要一样。","notes":[]},{"n":9,"t":"要把五幅幔子连成一幅，又把六幅幔子连成一幅，这第六幅幔子要在罩棚的前面摺上去。","notes":[]},{"n":10,"t":"在这一组相连幔子的末幅边上要缝五十个钮环；在另一组相连幔子的末幅边上也缝五十个钮环。","notes":[]},{"n":11,"t":"要做五十个铜钩，钩在钮环中，使罩棚相连成为一个。","notes":[]},{"n":12,"t":"罩棚幔子余下垂着的，那余下的半幅要垂在帐幕的背面。","notes":[]},{"n":13,"t":"罩棚的幔子两旁所余下的，这边一肘，那边一肘，要垂在帐幕的两边，盖住帐幕。","notes":[]},{"n":14,"t":"要用染红的公羊皮做罩棚的盖，再用精美皮料做外层的盖。","notes":[]},{"n":15,"t":"“你要用金合欢木做竖立帐幕的木板，","notes":[]},{"n":16,"t":"木板要长十肘，每块板宽一肘半，","notes":[]},{"n":17,"t":"每块板有两个榫头可以彼此衔接。帐幕一切的板都要这样做。","notes":[]},{"n":18,"t":"你要做帐幕的木板：南面，就是面向南方的那一边，要做二十块板。","notes":[]},{"n":19,"t":"在这二十块板底下要做四十个带卯眼的银座；两个卯眼接连这块板上的两个榫头，另外两个卯眼接连那块板上的两个榫头。","notes":[]},{"n":20,"t":"帐幕的第二边，就是北面，也要做二十块板，","notes":[]},{"n":21,"t":"和四十个带卯眼的银座；这块板底下有两个卯眼，那块板底下也有两个卯眼。","notes":[]},{"n":22,"t":"帐幕的后面，就是西面，要做六块板。","notes":[]},{"n":23,"t":"帐幕后面的角落要做两块板。","notes":[]},{"n":24,"t":"下端的板是成双的，上端要连在一起，直到顶端的第一个环子；两块板都要这样，做成两个角落。","notes":[]},{"n":25,"t":"一共有八块板和十六个带卯眼的银座；这块板底下有两个卯眼，那块板底下也有两个卯眼。","notes":[]},{"n":26,"t":"“你要用金合欢木做横木：为帐幕这面的板做五根横木，","notes":[]},{"n":27,"t":"为帐幕那面的板做五根横木，又为帐幕后面，就是朝西的板做五根横木。","notes":[]},{"n":28,"t":"板腰间的横木，要从一头通到另一头。","notes":[]},{"n":29,"t":"板要包上金子，又要做板上的金环来套横木；横木也要包上金子。","notes":[]},{"n":30,"t":"要照着在山上所指示你的样式，把帐幕竖立起来。","notes":[]},{"n":31,"t":"“你要用蓝色、紫色、朱红色纱，和搓的细麻织幔子，以刺绣的手艺绣上基路伯。","notes":[]},{"n":32,"t":"要把幔子挂在四根包金的金合欢木柱子上，柱子有金钩，并且安在四个带卯眼的银座上。","notes":[]},{"n":33,"t":"要把幔子垂挂在钩子上，把法柜抬进幔子内；这幔子要将圣所和至圣所隔开。","notes":[]},{"n":34,"t":"又要把柜盖安在至圣所内的法柜上，","notes":[]},{"n":35,"t":"把供桌安在幔子的外面，供桌在北面，灯台在帐幕的南面，和供桌相对。","notes":[]},{"n":36,"t":"“你要用蓝色、紫色、朱红色纱，和搓的细麻，以刺绣的手艺为帐幕织门帘。","notes":[]},{"n":37,"t":"要用金合欢木为帘子做五根柱子，包上金子。柱子有金钩，又为柱子铸造五个带卯眼的铜座。”","notes":[]}]},"27":{"heading":"祭坛","verses":[{"n":1,"t":"“你要用金合欢木做祭坛，长五肘，宽五肘，这坛是正方形的，高三肘。","notes":[]},{"n":2,"t":"要在坛的四角做四个翘角，与坛接连一块；要把坛包上铜。","notes":[]},{"n":3,"t":"要做桶子来盛坛上的灰，又要做铲子、盘子、肉叉和火盆；坛上一切的器具都要用铜做。","notes":[]},{"n":4,"t":"要为坛做一个铜网，在网的四角做四个铜环，","notes":[]},{"n":5,"t":"把网安在坛四围的边的下面，使网垂到坛的半腰。","notes":[]},{"n":6,"t":"又要用金合欢木为坛做杠，包上铜。","notes":[]},{"n":7,"t":"这杠要穿过坛两旁的环子，用来抬坛。","notes":[]},{"n":8,"t":"要用板做坛，坛的中心是空的，都照着在山上所指示你的样式做。”","notes":[]},{"n":9,"t":"“你要做帐幕的院子。南面，就是面向南方的那一边，要用搓的细麻做院子的帷幔，长一百肘，","notes":[],"heads":["院子"]},{"n":10,"t":"院子要有二十根柱子，二十个带卯眼的铜座。要用银做柱子的钩和箍。","notes":[]},{"n":11,"t":"北面的长度也一样，帷幔长一百肘，要有二十根柱子，二十个带卯眼的铜座。要用银做柱子的钩和箍。","notes":[]},{"n":12,"t":"院子的西面有帷幔，宽五十肘，帷幔要有十根柱子，十个带卯眼的座。","notes":[]},{"n":13,"t":"院子的东面，就是面向东方的那一边，宽五十肘。","notes":[]},{"n":14,"t":"一边的帷幔有十五肘，要有三根柱子，三个带卯眼的座。","notes":[]},{"n":15,"t":"另一边的帷幔也有十五肘，要有三根柱子，三个带卯眼的座。","notes":[]},{"n":16,"t":"院子的门要有二十肘长的帘子，用蓝色、紫色、朱红色纱，和搓的细麻，以刺绣的手艺织成；要有四根柱子，四个带卯眼的座。","notes":[]},{"n":17,"t":"院子四围一切的柱子都要用银子箍着，要用银做柱子的钩子，用铜做带卯眼的座。","notes":[]},{"n":18,"t":"院子要长一百肘，宽五十肘，高五肘。要用搓的细麻做帷幔，用铜做带卯眼的座。","notes":["“五十肘”是根据撒玛利亚五经；原文是“五十、五十”，指从南到北都是五十。"]},{"n":19,"t":"帐幕中各样用途的器具，以及帐幕一切的橛子和院子里一切的橛子，都要用铜做。”","notes":[]},{"n":20,"t":"“你要吩咐以色列人，把捣成的纯橄榄油拿来给你，用以点灯，使灯经常点着；","notes":[],"heads":["燃灯的条例"]},{"n":21,"t":"在会幕中法柜前的幔子外，亚伦和他的儿子要从晚上到早晨，在耶和华面前照管这灯。这要成为以色列人世世代代永远的定例。”","notes":[]}]},"28":{"heading":"祭司的圣服","verses":[{"n":1,"t":"“你要从以色列人中，叫你的哥哥亚伦和他的儿子拿答、亚比户、以利亚撒、以他玛一同亲近你，作事奉我的祭司。","notes":[]},{"n":2,"t":"你要为你哥哥亚伦做圣衣，以示尊严和华美。","notes":[]},{"n":3,"t":"要吩咐一切心中有智慧的，就是我用智慧的灵所充满的人，为亚伦做衣服，使他分别为圣，作事奉我的祭司。","notes":[]},{"n":4,"t":"所要做的是胸袋、以弗得、外袍、织成的内袍、礼冠和腰带。他们要为你哥哥亚伦和他的儿子做圣衣，使他们作祭司事奉我。","notes":[]},{"n":5,"t":"要用金色、蓝色、紫色、朱红色纱，和细麻去缝制。”","notes":[]},{"n":6,"t":"“他们要用金色、蓝色、紫色、朱红色纱，和搓的细麻，以刺绣的手艺做以弗得。","notes":[],"heads":["以弗得"]},{"n":7,"t":"以弗得当有两条肩带，接上两端，使它相连。","notes":[]},{"n":8,"t":"以弗得的精致带子，要以一样的手艺，用金色、蓝色、紫色、朱红色纱，和搓的细麻缝制，与以弗得接连在一起。","notes":[]},{"n":9,"t":"要取两块红玛瑙，在上面刻以色列儿子的名字：","notes":[]},{"n":10,"t":"六个名字在一块宝石上，六个名字在另一块宝石上，都按照他们出生的次序。","notes":[]},{"n":11,"t":"要以雕刻宝石的手艺，如同刻印章，把以色列儿子的名字刻在这两块宝石上，并把宝石镶在金槽里。","notes":[]},{"n":12,"t":"要把这两块宝石安在以弗得的两条肩带上，为以色列人作纪念石。亚伦要在耶和华面前把他们的名字带在两肩上，作为纪念。","notes":[]},{"n":13,"t":"要用金子做两个槽，","notes":[]},{"n":14,"t":"再用纯金打两条链子，像编成的绳子一样，把这编成的金链扣在槽上。”","notes":[]},{"n":15,"t":"“你要以刺绣的手艺做一个决断的胸袋，和做以弗得的方法一样，用金色、蓝色、紫色、朱红色纱，和搓的细麻缝制。","notes":[],"heads":["胸袋"]},{"n":16,"t":"胸袋是正方形的，叠成两层，长一虎口，宽一虎口。","notes":[]},{"n":17,"t":"要在上面镶四行宝石：第一行是红宝石、红璧玺、红玉；","notes":[]},{"n":18,"t":"第二行是绿宝石、蓝宝石、金刚石；","notes":[]},{"n":19,"t":"第三行是紫玛瑙、白玛瑙、紫晶；","notes":[]},{"n":20,"t":"第四行是水苍玉、红玛瑙、碧玉。这些都要镶在金槽中。","notes":[]},{"n":21,"t":"这些宝石要有以色列十二个儿子的名字，如同刻印章，每一颗有自己的名字，代表十二个支派。","notes":[]},{"n":22,"t":"要在胸袋上用纯金打链子，像编成的绳子一样。","notes":[]},{"n":23,"t":"要为胸袋做两个金环，把这两个环安在胸袋的两端。","notes":[]},{"n":24,"t":"要把那两条编成的金链系在胸袋两端的两个环上。","notes":[]},{"n":25,"t":"又要把链子的另外两端扣在两个槽上，安在以弗得前面的肩带上。","notes":[]},{"n":26,"t":"要做两个金环，安在胸袋的两端，在以弗得里面的边上。","notes":[]},{"n":27,"t":"再做两个金环，安在以弗得前面两条肩带的下边，靠近接缝处，在以弗得精致带子的上面。","notes":[]},{"n":28,"t":"要用蓝色的带子把胸袋的环与以弗得的环系住，使胸袋绑在以弗得的精致带子上，不致松脱。","notes":[]},{"n":29,"t":"亚伦进圣所的时候，要把刻着以色列儿子名字的决断胸袋带着，放在心上，在耶和华面前常作纪念。","notes":[]},{"n":30,"t":"又要将乌陵和土明放在决断胸袋里；亚伦进到耶和华面前的时候，要放在心上。这样，亚伦在耶和华面前要把以色列人的决断胸袋常常带着，放在心上。”","notes":["“乌陵和土明”指祭司用以求问神旨意的神器。"]},{"n":31,"t":"“你要做以弗得的外袍，颜色全是蓝的。","notes":[],"heads":["祭司的其他圣服"]},{"n":32,"t":"袍上方的中间要留一个领口，领口周围的领边要以手艺编织而成，好像铠甲的领口，免得破裂。","notes":[]},{"n":33,"t":"袍子下摆，就是下摆的周围要用蓝色、紫色、朱红色纱做石榴，周围的石榴中间要有金铃铛：","notes":[]},{"n":34,"t":"一个金铃铛一个石榴，一个金铃铛一个石榴，在袍子下摆的周围。","notes":[]},{"n":35,"t":"亚伦供职的时候要穿这袍。他进入圣所到耶和华面前，以及出来的时候，袍上的铃声必被听见，使他不至于死。","notes":[]},{"n":36,"t":"“你要用纯金做一面牌，如同刻印章，在上面刻‘归耶和华为圣’。","notes":[]},{"n":37,"t":"要用蓝色的带子把牌系在礼冠上，在礼冠的正前面。","notes":[]},{"n":38,"t":"这牌必在亚伦的额上，亚伦要担当干犯圣物的罪孽；这圣物是以色列人在一切圣礼物上所分别为圣的。这牌要常在他的额上，使他们可以在耶和华面前蒙悦纳。","notes":[]},{"n":39,"t":"要用细麻编织内袍，用细麻做礼冠，又以刺绣的手艺做腰带。","notes":[]},{"n":40,"t":"“你要为亚伦的儿子做内袍、腰带、头巾，以示尊严和华美。","notes":[]},{"n":41,"t":"要把这些给你哥哥亚伦和他的儿子穿戴，又要膏他们，授予圣职，使他们分别为圣，作事奉我的祭司。","notes":[]},{"n":42,"t":"要用细麻布给他们做裤子来遮掩下体，从腰间直到大腿。","notes":[]},{"n":43,"t":"亚伦和他儿子进入会幕，或接近祭坛，在圣所供职的时候要穿上裤子，免得担当罪孽而死。这要成为亚伦和他后裔永远的定例。”","notes":[]}]},"29":{"heading":"祭司的圣职礼","verses":[{"n":1,"t":"“这是你使他们分别为圣，作事奉我的祭司时要做的事：取一头公牛犊，两只无残疾的公绵羊，","notes":[]},{"n":2,"t":"无酵饼、用油调和的无酵饼，和抹油的无酵薄饼；这些饼都要用细麦面做成。","notes":[]},{"n":3,"t":"这些饼要装在一个篮子里，用篮子带来，又把公牛和两只公绵羊牵来。","notes":[]},{"n":4,"t":"要带亚伦和他儿子到会幕的门口，用水洗他们。","notes":[]},{"n":5,"t":"要拿服装，给亚伦穿上内袍和以弗得的外袍，以及以弗得，又带上胸袋，束上以弗得精致的带子。","notes":[]},{"n":6,"t":"要把礼冠戴在他头上，将圣冕加在礼冠上，","notes":[]},{"n":7,"t":"把膏油倒在他头上膏他。","notes":[]},{"n":8,"t":"要带他的儿子来，给他们穿上内袍。","notes":[]},{"n":9,"t":"要给亚伦和他的儿子束上腰带，裹上头巾，他们就凭永远的定例得祭司的职分。又要授圣职给亚伦和他的儿子。","notes":[]},{"n":10,"t":"“你要把公牛牵到会幕前，亚伦和他的儿子要按手在公牛的头上。","notes":[]},{"n":11,"t":"你要在耶和华面前，在会幕的门口宰这公牛。","notes":[]},{"n":12,"t":"要取些公牛的血，用指头抹在祭坛的四个翘角上，把其余的血全倒在坛的底座上。","notes":[]},{"n":13,"t":"要把所有包着内脏的脂肪、肝上的网油、两个肾和肾上的脂肪，都烧在坛上。","notes":[]},{"n":14,"t":"只是公牛的肉、皮、粪都要在营外用火焚烧；这牛是赎罪祭。","notes":[]},{"n":15,"t":"“你要牵一只公绵羊来，亚伦和他儿子要按手在这羊的头上。","notes":[]},{"n":16,"t":"你要宰这羊，把血洒在祭坛的周围。","notes":[]},{"n":17,"t":"再把羊切成肉块，洗净内脏和腿，连肉块和头放在一处。","notes":[]},{"n":18,"t":"要把全羊烧在坛上。这是献给耶和华的燔祭，是献给耶和华馨香的火祭。”","notes":[]},{"n":19,"t":"“你要把第二只公绵羊牵来，亚伦和他儿子要按手在这羊的头上。","notes":[]},{"n":20,"t":"你要宰这羊，取些血抹在亚伦的右耳垂和他儿子的右耳垂上，又抹在他们右手的大拇指和右脚的大脚趾上，然后把其余的血洒在坛的周围。","notes":[]},{"n":21,"t":"你要取些膏油和坛上的血，弹在亚伦和他的衣服上，以及他儿子和他们的衣服上；亚伦和他的衣服，他儿子和他们的衣服都成为圣了。","notes":[]},{"n":22,"t":"“你要取这羊的脂肪，肥尾巴、包着内脏的脂肪、肝上的网油、两个肾、肾上的脂肪和右腿，这是圣职礼所献的公绵羊；","notes":[]},{"n":23,"t":"再从耶和华面前那装无酵饼的篮子中取一个饼、一个油饼和一个薄饼，","notes":[]},{"n":24,"t":"把它们都放在亚伦的手和他儿子的手上，在耶和华面前摇一摇，作为摇祭。","notes":[]},{"n":25,"t":"然后，你要从他们手中接过来，放在燔祭上，一起烧在坛上，作为耶和华面前馨香之气；这是献给耶和华的火祭。","notes":[]},{"n":26,"t":"“你要取亚伦圣职礼所献公绵羊的胸，在耶和华面前摇一摇，作为摇祭；这份就是你的。","notes":[]},{"n":27,"t":"那摇祭的胸和举祭的腿，就是圣职礼献公绵羊时所摇的、所举的，你要使它们分别为圣，是归给亚伦和他儿子的。","notes":[]},{"n":28,"t":"这是亚伦和他子孙凭永远的定例从以色列人中所应得的；因为这是举祭，是从以色列人的平安祭中取出，作为献给耶和华的举祭。","notes":[]},{"n":29,"t":"“亚伦的圣衣要传给他的子孙，使他们在受膏和承接圣职的时候穿上。","notes":[]},{"n":30,"t":"他的子孙接续他当祭司的，每逢进入会幕在圣所供职的时候，要穿这圣衣七天。","notes":[]},{"n":31,"t":"“你要拿圣职礼所献的公绵羊，在圣处煮它的肉。","notes":[]},{"n":32,"t":"亚伦和他儿子要在会幕的门口吃这羊的肉和篮子里的饼。","notes":[]},{"n":33,"t":"他们要吃那些用来赎罪之物，好承接圣职，使他们分别为圣。外人不可吃，因为这是圣物。","notes":[]},{"n":34,"t":"那圣职礼所献的肉或饼，若有剩余留到早晨，就要把剩下的用火烧了，不可再吃，因为这是圣物。","notes":[]},{"n":35,"t":"“你要这样照我一切所吩咐的，向亚伦和他儿子行授圣职礼七天。","notes":[]},{"n":36,"t":"为了赎罪，每天要献一头公牛为赎罪祭。你要为祭坛赎罪，使坛洁净，并要用膏抹坛，使坛成为圣。","notes":[]},{"n":37,"t":"要为坛赎罪七天，使坛成为圣，坛就成为至圣。凡触摸坛的都成为圣。”","notes":[]},{"n":38,"t":"“这是你要献在坛上的：每天不可间断地献两只一岁的羔羊；","notes":[],"heads":["每天当献的祭"]},{"n":39,"t":"早晨献第一只羔羊，黄昏献第二只羔羊。","notes":[]},{"n":40,"t":"献第一只羔羊时，要同时献上十分之一伊法细面，调和四分之一欣捣成的油，再献四分之一欣酒作浇酒祭。","notes":[]},{"n":41,"t":"黄昏你献第二只羔羊，要照早晨的素祭和同献的浇酒祭献上，作为献给耶和华馨香的火祭。","notes":[]},{"n":42,"t":"这要在耶和华面前，在会幕的门口，作为你们世世代代经常献的燔祭。我要在那里与你们相会，和你说话。","notes":["“你们”：七十士译本是“你”。"]},{"n":43,"t":"我要在那里与以色列人相会，会幕就要因我的荣耀成为圣。","notes":[]},{"n":44,"t":"我要使会幕和祭坛分别为圣，也要使亚伦和他的儿子分别为圣，作事奉我的祭司。","notes":[]},{"n":45,"t":"我要住在以色列人中，作他们的神。","notes":[]},{"n":46,"t":"他们必知道我是耶和华－他们的神，是将他们从埃及地领出来的，为要住在他们中间。我是耶和华－他们的神 。”","notes":[]}]},"30":{"heading":"香坛","verses":[{"n":1,"t":"“你要用金合欢木做一座烧香的坛，","notes":[]},{"n":2,"t":"长一肘，宽一肘，这坛是正方形的，高二肘。坛的四个翘角与坛接连一块。","notes":[]},{"n":3,"t":"要把坛的上面与坛的四围，以及坛的四个翘角包上纯金；又要在坛的四围镶上金边。","notes":[]},{"n":4,"t":"要在坛的两个对侧，金边下面做两个金环，用来穿杠抬坛。","notes":[]},{"n":5,"t":"要用金合欢木做杠，包上金子。","notes":[]},{"n":6,"t":"要把坛放在法柜前的幔子外，对着法柜上的柜盖，就是我与你相会的地方。","notes":[]},{"n":7,"t":"亚伦要在坛上烧芬芳的香；每早晨整理灯的时候，他都要烧这香。","notes":[]},{"n":8,"t":"黄昏点灯的时候，亚伦也要烧这香。这是你们世世代代在耶和华面前常烧的香。","notes":[]},{"n":9,"t":"在这坛上不可烧别样的香，不可献燔祭、素祭，也不可献浇酒祭。","notes":[]},{"n":10,"t":"亚伦每年一次要为坛的四个翘角赎罪。他每年一次要用赎罪祭的血为坛赎罪，作为世世代代的定例。这坛在耶和华面前是至圣的。”","notes":[]},{"n":11,"t":"耶和华吩咐摩西说：","notes":[],"heads":["赎命的礼物"]},{"n":12,"t":"“你数点以色列人，计算人头时，被数的每一个人要把他生命的赎价献给耶和华，免得灾殃在数点中临到他们。","notes":[]},{"n":13,"t":"每一个被数的人要按照圣所的舍客勒，付半舍客勒，一舍客勒是二十季拉；这半舍客勒是献给耶和华的礼物。","notes":[]},{"n":14,"t":"每一个被数的人，就是二十岁以上的，要将这礼物献给耶和华。","notes":[]},{"n":15,"t":"富有的不必多付，贫穷的也不可少出，各人都要献半舍客勒给耶和华，作你们生命的赎价。","notes":[]},{"n":16,"t":"你要向以色列人收这赎罪的银子，用在会幕的事工。这要在耶和华面前为以色列人作纪念，作你们生命的赎价。”","notes":[]},{"n":17,"t":"耶和华吩咐摩西说：","notes":[],"heads":["铜盆"]},{"n":18,"t":"“你要用铜做洗濯盆和盆座，用来洗濯。要将盆放在会幕和祭坛的中间，盆里盛水。","notes":[]},{"n":19,"t":"亚伦和他的儿子要用这盆洗手洗脚。","notes":[]},{"n":20,"t":"他们进会幕，或是走近坛前供职，献火祭给耶和华的时候，必须用水洗濯，免得死亡；","notes":[]},{"n":21,"t":"他们要洗手洗脚，免得死亡。这是亚伦和他的后裔世世代代永远的定例。”","notes":[]},{"n":22,"t":"耶和华吩咐摩西说：","notes":[],"heads":["圣膏油"]},{"n":23,"t":"“你要取上等的香料，就是五百舍客勒流质的没药、二百五十香肉桂、二百五十香菖蒲，","notes":[]},{"n":24,"t":"和五百桂皮，都按照圣所的舍客勒；再取一欣橄榄油，","notes":[]},{"n":25,"t":"以做香的方法调和制成圣膏油，它就成为圣膏油。","notes":[]},{"n":26,"t":"要用这膏油抹会幕和法柜，","notes":[]},{"n":27,"t":"供桌和供桌的一切器具，灯台和灯台的器具，以及香坛、","notes":["“器具”：有古卷和七十士译本是“一切器具”。"]},{"n":28,"t":"燔祭坛和坛的一切器具，洗濯盆和盆座。","notes":[]},{"n":29,"t":"你要使这些分别为圣，成为至圣；凡触摸它们的都成为圣。","notes":[]},{"n":30,"t":"要膏亚伦和他的儿子，使他们分别为圣，作事奉我的祭司。","notes":[]},{"n":31,"t":"你要吩咐以色列人说：‘你们要世世代代以这油为我的圣膏油。","notes":[]},{"n":32,"t":"不可把这油倒在别人身上，也不可用配制这膏油的方法制成同样的膏油。这膏油是圣的，你们要以它为圣。","notes":[]},{"n":33,"t":"凡调和与此类似的膏油，或将它膏在别人身上的，这人要从百姓中剪除。’”","notes":[]},{"n":34,"t":"耶和华吩咐摩西说：“你要取香料，就是拿他弗、施喜列、喜利比拿，这些香料再加纯乳香，每样都要相同的分量。","notes":[],"heads":["香的做法"]},{"n":35,"t":"你要用这些加上盐，以配制香料的方法，制成纯净又神圣的香。","notes":[]},{"n":36,"t":"要取一点这香，捣成细的粉，放在会幕中的法柜前，就是我和你相会的地方。你们要以这香为至圣。","notes":[]},{"n":37,"t":"你们不可用这配制的方法为自己做香；要以这香为圣，归于耶和华。","notes":[]},{"n":38,"t":"为要闻香味而配制同样的香的，这人要从百姓中剪除。”","notes":[]}]},"31":{"heading":"会幕的技工","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你看，我已经题名召犹大支派中户珥的孙子，乌利的儿子比撒列。","notes":[]},{"n":3,"t":"我以神的灵充满他，使他有智慧，有聪明，有知识，能做各样的工，","notes":[]},{"n":4,"t":"能设计图案，用金、银、铜制造各物，","notes":[]},{"n":5,"t":"又能雕刻镶嵌用的宝石，雕刻木头，做各样的工。","notes":[]},{"n":6,"t":"看哪，我委派但支派中亚希撒抹的儿子亚何利亚伯与他同工。凡心里有智慧的，我更要赐给他们智慧的心，能做我所吩咐的一切，","notes":[]},{"n":7,"t":"就是会幕、法柜和其上的柜盖、会幕中一切的器具、","notes":[]},{"n":8,"t":"供桌和供桌的器具、纯金的灯台和灯台的一切器具、香坛、","notes":[]},{"n":9,"t":"燔祭坛和坛的一切器具、洗濯盆与盆座、","notes":[]},{"n":10,"t":"供祭司职分用的精致礼服，亚伦祭司的圣衣和他儿子的衣服，","notes":[]},{"n":11,"t":"以及膏油和圣所用的芬芳的香。他们都要照我所吩咐的一切去做。”","notes":[]},{"n":12,"t":"耶和华对摩西说：","notes":[],"heads":["要守安息日"]},{"n":13,"t":"“你要吩咐以色列人说：‘你们务要守我的安息日，因为这是你我之间世世代代的记号，叫你们知道我是耶和华，是使你们分别为圣的。","notes":[]},{"n":14,"t":"你们要守安息日，以它为圣日。凡干犯这日的，必被处死；凡在这日做工的，那人必从百姓中剪除。","notes":[]},{"n":15,"t":"六日要做工，但第七日是向耶和华守完全安息的安息圣日。凡在安息日做工的，必被处死。’","notes":[]},{"n":16,"t":"以色列人要守安息日，世世代代守安息日为永远的约。","notes":[]},{"n":17,"t":"这是我和以色列人之间永远的记号，因为六日之内耶和华造天地，第七日就安息舒畅。”","notes":[]},{"n":18,"t":"耶和华在西奈山和摩西说完了话，就把两块法版交给他，是神用指头写的石版。","notes":[]}]},"32":{"heading":"金牛犊","verses":[{"n":1,"t":"百姓见摩西迟迟不下山，就聚集到亚伦那里，对他说：“起来！为我们造神明，在我们前面引路，因为领我们出埃及地的那个摩西，我们不知道他遭遇了什么事。”","notes":[]},{"n":2,"t":"亚伦对他们说：“你们去摘下你们妻子、儿女耳上的金环，拿来给我。”","notes":[]},{"n":3,"t":"众百姓就摘下他们耳上的金环，拿来给亚伦。","notes":[]},{"n":4,"t":"亚伦从他们手里接过来，用模子塑造它，把它铸成一头牛犊。他们就说：“以色列啊，这是领你出埃及地的神明！”","notes":[]},{"n":5,"t":"亚伦看见，就在牛犊面前筑坛。亚伦宣告说：“明日要向耶和华守节。”","notes":[]},{"n":6,"t":"次日清早，百姓起来献燔祭和平安祭，就坐下吃喝，起来玩乐。","notes":[]},{"n":7,"t":"耶和华吩咐摩西：“下去吧，因为你从埃及领上来的百姓已经败坏了。","notes":[]},{"n":8,"t":"他们这么快偏离了我所吩咐的道，为自己铸了一头牛犊，向它跪拜，向它献祭，说：‘以色列啊，这就是领你出埃及地的神明。’”","notes":[]},{"n":9,"t":"耶和华对摩西说：“我看这百姓，看哪，他们真是硬着颈项的百姓。","notes":[]},{"n":10,"t":"现在，你且由着我，我要向他们发烈怒，灭绝他们，但我要使你成为大国。”","notes":[]},{"n":11,"t":"摩西就恳求耶和华－他的神，说：“耶和华啊，你为什么向你的百姓发烈怒呢？这百姓是你用大能大力的手从埃及地领出来的！","notes":[]},{"n":12,"t":"为什么让埃及人说：‘他领他们出去，是要降灾祸给他们，在山中把他们杀了，将他们从地上除灭’呢？求你回心转意，不发你的烈怒，不降灾祸给你的百姓。","notes":[]},{"n":13,"t":"求你记念你的仆人亚伯拉罕、以撒、以色列。你曾向他们指着自己起誓说：‘我必使你们的后裔像天上的星那样多，并且我要将所应许的这全地赐给你们的后裔，让他们永远承受为业。’”","notes":[]},{"n":14,"t":"于是耶和华改变心意，不把所说的灾祸降给他的百姓。","notes":[]},{"n":15,"t":"摩西转身下山，手里拿着两块法版。这版的两面都写着字，正面背面都有字。","notes":[]},{"n":16,"t":"版是神的工作，字是神写的字，刻在版上。","notes":[]},{"n":17,"t":"约书亚一听见百姓呼喊的声音，就对摩西说：“在营里有战争的声音。”","notes":[]},{"n":18,"t":"摩西说：“这不是打胜仗的声音，也不是打败仗的声音，我听见的是歌唱的声音。”","notes":[]},{"n":19,"t":"摩西走近营前，看见牛犊，又看见人在跳舞，就发烈怒，把两块版从手中扔到山下摔碎了。","notes":[]},{"n":20,"t":"他将他们所铸的牛犊用火焚烧，磨得粉碎，撒在水面上，叫以色列人喝。","notes":[]},{"n":21,"t":"摩西对亚伦说：“这百姓向你做了什么呢？你竟使他们陷入大罪中！”","notes":[]},{"n":22,"t":"亚伦说：“求我主不要发烈怒。你知道这百姓，他们是向恶的。","notes":[]},{"n":23,"t":"他们对我说：‘你为我们造神明，在我们前面引路，因为领我们出埃及地的那个摩西，我们不知道他遭遇了什么事。’","notes":[]},{"n":24,"t":"我对他们说：‘凡有金环的可以摘下来’，他们就给了我。我把金环扔在火中，这牛犊就出来了。”","notes":[]},{"n":25,"t":"摩西见百姓放肆，因亚伦纵容他们，使这事成了敌人的笑柄，","notes":[]},{"n":26,"t":"就站在营门前，说：“凡属耶和华的人，都到我这里来！”于是利未人都聚集到他那里。","notes":[]},{"n":27,"t":"他对他们说：“耶和华－以色列的神这样说：‘你们各人把刀佩在腰间，从这门到那门，来回走遍全营，各人要杀自己的弟兄、邻舍和亲人。’”","notes":[]},{"n":28,"t":"利未人遵照摩西的话做了。那一天百姓中倒下的约有三千人。","notes":[]},{"n":29,"t":"摩西说：“今天你们要奉献自己来事奉耶和华，因为各人牺牲自己的儿子和弟兄，使耶和华今天赐福给你们。”","notes":["“你们要奉献自己”：七十士译本是“你们已奉献自己”。"]},{"n":30,"t":"第二天，摩西对百姓说：“你们犯了大罪。我如今要上耶和华那里去，或许可以为你们赎罪。”","notes":[]},{"n":31,"t":"摩西回到耶和华那里，说：“唉！这百姓犯了大罪，为自己造了金的神明。","notes":[]},{"n":32,"t":"现在，求你赦免他们的罪；不然，就把我从你所写的册上除名。”","notes":[]},{"n":33,"t":"耶和华对摩西说：“谁得罪我，我就把他从我的册上除去。","notes":[]},{"n":34,"t":"现在你去，领这百姓往我所告诉你的地方去，看哪，我的使者必在你的前面引路。到了该惩罚的时候，我必惩罚他们的罪。”","notes":[]},{"n":35,"t":"耶和华降灾与百姓，因为他们和亚伦一起造了牛犊。","notes":[]}]},"33":{"heading":"起程的吩咐","verses":[{"n":1,"t":"耶和华吩咐摩西说：“去，离开这里，你和你从埃及地领出来的百姓要上到我起誓应许给亚伯拉罕、以撒和雅各之地去；我曾对他们说：‘我要将这地赐给你的后裔’。","notes":[]},{"n":2,"t":"我要差遣使者在你前面，把迦南人、亚摩利人、赫人、比利洗人、希未人、耶布斯人赶出","notes":[]},{"n":3,"t":"那流奶与蜜之地。但我不与你们上去，因为你们是硬着颈项的百姓，免得我在路上把你们灭绝。”","notes":[]},{"n":4,"t":"百姓一听见这坏的信息，他们就悲哀，没有人佩戴首饰。","notes":[]},{"n":5,"t":"耶和华对摩西说：“你对以色列人说：‘你们是硬着颈项的百姓，我若在你们中间一起上去，只一瞬间，就必把你们灭绝。现在把你们身上的首饰摘下来，我好知道该怎样处置你们。’”","notes":[]},{"n":6,"t":"以色列人离开何烈山以后，就把身上的首饰摘下来。","notes":[]},{"n":7,"t":"摩西拿一个帐棚支搭在营外，离营有一段距离，他称这帐棚为会幕。凡求问耶和华的，就到营外的会幕那里去。","notes":[],"heads":["摩西进会幕"]},{"n":8,"t":"当摩西出营到会幕去的时候，百姓就都起来，各人站在自己帐棚的门口，望着摩西，直到他进了会幕。","notes":[]},{"n":9,"t":"摩西进会幕的时候，云柱就降下来，停在会幕的门前，耶和华就与摩西说话。","notes":[]},{"n":10,"t":"众百姓看见云柱停在会幕的门前，就都起来，各人在自己帐棚的门口下拜。","notes":[]},{"n":11,"t":"耶和华与摩西面对面说话，好像人与朋友说话。摩西回到营里去，他的年轻助手嫩的儿子约书亚却没有离开会幕。","notes":[]},{"n":12,"t":"摩西对耶和华说：“看，你曾对我说：‘将这百姓领上去’；却没有让我知道你要差派谁与我同去。你还说：‘我按你的名认识你，你也在我眼前蒙了恩。’","notes":[],"heads":["耶和华应许跟百姓同去"]},{"n":13,"t":"我如今若在你眼前蒙恩，求你将你的道指示我，使我可以认识你，并在你眼前蒙恩。求你顾念这国是你的子民。”","notes":[]},{"n":14,"t":"耶和华说：“我必亲自去，让你安心。”","notes":[]},{"n":15,"t":"摩西说：“你若不亲自去，就不要把我们从这里领上去。","notes":[]},{"n":16,"t":"现在，人如何得知我和你的百姓在你眼前蒙恩呢？岂不是因为你与我们同去，使我和你的百姓与地面上的万民有分别吗？”","notes":[]},{"n":17,"t":"耶和华对摩西说：“你所说的这件事，我也会去做，因为你在我眼前蒙了恩，并且我按你的名认识你。”","notes":[]},{"n":18,"t":"摩西说：“求你显出你的荣耀给我看。”","notes":[]},{"n":19,"t":"耶和华说：“我要显示我一切的美善，在你面前经过，并要在你面前宣告耶和华的名。我要恩待谁就恩待谁，要怜悯谁就怜悯谁。”","notes":[]},{"n":20,"t":"他又说：“只是你不能看见我的面，因为没有人看见我还可以存活。”","notes":[]},{"n":21,"t":"耶和华说：“看哪，靠近我这里有个地方，你可以站在这磐石上。","notes":[]},{"n":22,"t":"当我的荣耀经过的时候，我必将你放在磐石缝里，用我的手掌遮掩你，等我过去，","notes":[]},{"n":23,"t":"然后我要将我的手掌收回，你就可以看见我的背，却看不到我的面。”","notes":[]}]},"34":{"heading":"复造法版","verses":[{"n":1,"t":"耶和华对摩西说：“你要凿出两块石版，和先前的一样；我要把你摔碎的那版上先前所写的字，写在这版上。","notes":[]},{"n":2,"t":"明日早晨，你要预备好了，上西奈山，在山顶那里站在我面前。","notes":[]},{"n":3,"t":"谁也不可和你上去，整座山都不可见到人，也不可有羊群牛群在山下吃草。”","notes":[]},{"n":4,"t":"摩西就凿出两块石版，和先前的一样。他清晨起来，遵照耶和华吩咐他的，上西奈山去，手里拿着两块石版。","notes":[]},{"n":5,"t":"耶和华在云中降临，与摩西一同站在那里，宣告耶和华的名。","notes":[]},{"n":6,"t":"耶和华在他面前经过，宣告：“耶和华，耶和华，有怜悯，有恩惠的神，不轻易发怒，且有丰盛的慈爱和信实，","notes":[]},{"n":7,"t":"为千代的人存留慈爱，赦免罪孽、过犯和罪恶，万不以有罪的为无罪，必惩罚人的罪，自父及子，直到三、四代。”","notes":[]},{"n":8,"t":"摩西急忙俯伏在地敬拜，","notes":[]},{"n":9,"t":"说：“主啊，我若在你眼前蒙恩，求主在我们中间同行。虽然这是硬着颈项的百姓，求你赦免我们的罪孽和罪恶，接纳我们为你的产业。”","notes":[]},{"n":10,"t":"耶和华说：“看哪，我要立约，要在你众百姓面前行奇妙的事，是在全地万国中未曾做过的。你周围的万民要看见我藉着你所行，耶和华可畏惧的作为。","notes":[],"heads":["重新立约"]},{"n":11,"t":"“我今天所吩咐你的，你要谨守。看哪，我要从你面前赶出亚摩利人、迦南人、赫人、比利洗人、希未人、耶布斯人。","notes":[]},{"n":12,"t":"你要谨慎，不可与你所要去那地的居民立约，免得他们成为你中间的圈套。","notes":[]},{"n":13,"t":"你要拆毁他们的祭坛，打碎他们的柱像，砍断他们的亚舍拉。","notes":[]},{"n":14,"t":"不可敬拜别神，因为耶和华是忌邪的神，他的名是忌邪者。","notes":["“忌邪”：原文是“妒忌”，意思是“不容许有对立的神明”。"]},{"n":15,"t":"你不可与那地的居民立约，因为他们随从自己的神明行淫；祭他们神明的时候，有人邀请你参加，你就会吃他的祭物。","notes":[]},{"n":16,"t":"你为你儿子娶他们的女儿为妻，他们的女儿因着随从她们的神明行淫，就引诱你的儿子也随从她们的神明行淫。","notes":[]},{"n":17,"t":"“不可为自己铸造神像。","notes":[]},{"n":18,"t":"“你要守除酵节，照我所吩咐你的，在亚笔月内所定的日期吃无酵饼七天，因为你是在亚笔月内出了埃及。","notes":[]},{"n":19,"t":"“凡头生的都是我的；无论是牛是羊，一切头生的公的牲畜都要分别出来。","notes":["“一切头生...分别出来”或译“一切头生的牲畜都要被记念”。"]},{"n":20,"t":"头生的驴可以用羔羊代赎。若不赎它，就要打断它的颈项。凡头生的儿子都要赎出来。没有人可以空手来朝见我。","notes":[]},{"n":21,"t":"“六日你要做工，第七日要安息，即使在耕种或收割的时候也要安息。","notes":[]},{"n":22,"t":"在收割初熟麦子的时候要守七七节，又要在年底守收藏节。","notes":[]},{"n":23,"t":"你所有的男丁要一年三次朝见主耶和华－以色列的神。","notes":[]},{"n":24,"t":"我要从你面前赶走列国，扩张你的疆界。你一年三次上去朝见耶和华－你神的时候，必没有人贪图你的地。","notes":[]},{"n":25,"t":"“不可将我祭牲的血和有酵之物一同献上。逾越节的祭牲也不可留到早晨。","notes":[]},{"n":26,"t":"土地里上好的初熟之物要奉到耶和华－你神的殿。不可用母山羊的奶来煮它的小山羊。”","notes":[]},{"n":27,"t":"耶和华对摩西说：“你要将这些话写上，因为我按这话与你和以色列人立约。”","notes":[]},{"n":28,"t":"摩西在耶和华那里四十昼夜，不吃饭不喝水。他把这约的话，那十条诫命，写在版上。","notes":["“十条诫命”：原文是“十句话”。"]},{"n":29,"t":"摩西下西奈山。摩西从山上下来的时候，手里拿着两块法版。摩西不知道自己脸上的皮肤因耶和华和他说话而发光。","notes":[],"heads":["摩西下西奈山"]},{"n":30,"t":"亚伦和以色列众人看见摩西，看哪，他脸上的皮肤发光，他们就怕靠近他。","notes":[]},{"n":31,"t":"摩西叫他们来，亚伦和会众的官长回到他那里，摩西就跟他们说话。","notes":[]},{"n":32,"t":"随后以色列众人都近前来，他就把耶和华在西奈山与他所说的一切话都吩咐他们。","notes":[]},{"n":33,"t":"摩西跟他们说完了话，就用面纱蒙上脸。","notes":[]},{"n":34,"t":"但摩西进到耶和华面前与他说话的时候，就把面纱揭下，直到出来。摩西出来，将所吩咐他的话告诉以色列人。","notes":[]},{"n":35,"t":"以色列人看见摩西的脸，他脸上的皮肤发光。摩西就用面纱蒙上脸，直到他进去与耶和华说话才揭下。","notes":[]}]},"35":{"heading":"安息日的条例","verses":[{"n":1,"t":"摩西召集以色列全会众，对他们说：“这是耶和华吩咐你们遵行的事：","notes":[]},{"n":2,"t":"六日要做工，第七日你们要奉为向耶和华守完全安息的安息圣日。凡在这日做工的，要被处死。","notes":[]},{"n":3,"t":"在安息日这一天，不可在你们一切的住处生火。”","notes":[]},{"n":4,"t":"摩西对以色列全会众说：“这是耶和华所吩咐的话，说：","notes":[],"heads":["为会幕奉献"]},{"n":5,"t":"要从你们当中拿礼物献给耶和华；凡甘心乐意的，可以把耶和华的礼物拿来，就是金、银、铜，","notes":[]},{"n":6,"t":"蓝色、紫色、朱红色纱，细麻，山羊毛，","notes":[]},{"n":7,"t":"染红的公羊皮，精美的皮料，金合欢木，","notes":[]},{"n":8,"t":"点灯的油，做膏油的香料、做香的香料，","notes":[]},{"n":9,"t":"红玛瑙与宝石，可以镶嵌在以弗得和胸袋上。”","notes":[]},{"n":10,"t":"“你们当中凡心里有智慧的都要来，制造一切耶和华所吩咐的，","notes":[],"heads":["会幕的器具"]},{"n":11,"t":"就是帐幕、帐幕的罩棚、帐幕的盖、钩子、竖板、横木、柱子和带卯眼的座，","notes":[]},{"n":12,"t":"柜子、柜子的杠、柜盖和遮掩的幔子，","notes":[]},{"n":13,"t":"供桌、供桌的杠、供桌一切的器具和供饼，","notes":[]},{"n":14,"t":"灯台、灯台的器具、灯和点灯的油，","notes":[]},{"n":15,"t":"香坛、坛的杠、膏油和芬芳的香，帐幕门口的门帘，","notes":[]},{"n":16,"t":"燔祭坛、坛的铜网、坛的杠和坛的一切器具，洗濯盆和盆座，","notes":[]},{"n":17,"t":"院子的帷幔、柱子、带卯眼的座和院子的门帘，","notes":[]},{"n":18,"t":"帐幕的橛子、院子的橛子和绳子，","notes":[]},{"n":19,"t":"以及圣所事奉用的精致礼服，亚伦祭司的圣衣和他儿子的衣服，供祭司职分用。”","notes":[]},{"n":20,"t":"以色列全会众从摩西的面前出去。","notes":[],"heads":["百姓奉献礼物"]},{"n":21,"t":"凡心受感动，灵被驱策的，都带耶和华的礼物来，为要造会幕和其中一切的器具，以及缝制圣衣。","notes":[]},{"n":22,"t":"凡甘心乐意的，连男带女都来了，各将金器，就是胸针、耳环、打印的戒指，和项链带来，摇着金器的摇祭献给耶和华。","notes":[]},{"n":23,"t":"凡有蓝色、紫色、朱红色纱、细麻、山羊毛、染红的公羊皮、精美皮料的，都拿了来；","notes":[]},{"n":24,"t":"凡愿意献银和铜作礼物的，都拿礼物来献给耶和华；凡有金合欢木可做各种用途的也都拿了来。","notes":[]},{"n":25,"t":"凡心中有智慧，可以亲手纺织的妇女，也把所纺的蓝色、紫色、朱红色纱，和细麻都拿了来。","notes":[]},{"n":26,"t":"凡有智慧，心里受感动的妇女都来纺山羊毛。","notes":[]},{"n":27,"t":"众官长把红玛瑙和宝石，可以镶嵌在以弗得与胸袋上的，都拿了来，","notes":[]},{"n":28,"t":"又拿做香，做膏油，和点灯所需的香料和油来。","notes":[]},{"n":29,"t":"以色列人，无论男女，凡心里受感动的，都带甘心祭来献给耶和华，为要做耶和华藉摩西所吩咐的一切工。","notes":[]},{"n":30,"t":"摩西对以色列人说：“看，犹大支派中户珥的孙子，乌利的儿子比撒列，耶和华已经题名召他，","notes":[],"heads":["造会幕的技工"]},{"n":31,"t":"又以神的灵充满他，使他有智慧、聪明、知识，能做各样的工，","notes":[]},{"n":32,"t":"能设计图案，用金、银、铜制造各物，","notes":[]},{"n":33,"t":"又能雕刻镶嵌用的宝石，雕刻木头，做各样精巧的工。","notes":[]},{"n":34,"t":"耶和华又赐给他和但支派中，亚希撒抹的儿子亚何利亚伯能教导人的心。","notes":[]},{"n":35,"t":"耶和华使他们的心满有智慧，能做各样的工，无论是雕刻的工，图案设计的工，用蓝色、紫色、朱红色纱，和细麻作刺绣的工，以及编织的工，他们都能胜任，也能设计图案。”","notes":[]}]},"36":{"heading":"百姓的奉献","verses":[{"n":1,"t":"比撒列和亚何利亚伯，以及一切心里有智慧，蒙耶和华赐智慧和聪明，懂得做圣所各样用途之工的人，都照耶和华所吩咐的去做。","notes":[]},{"n":2,"t":"摩西把比撒列和亚何利亚伯，以及那些蒙耶和华赐他心里有智慧，心受感动愿意前来做工的人都召来。","notes":[]},{"n":3,"t":"这些人就从摩西收了以色列人为建造圣所，以及圣所各用途之工而奉献的礼物。每天早晨，百姓继续把甘心祭拿来。","notes":[]},{"n":4,"t":"凡有智慧能做圣所一切工的人，都各自离开他们原本的工作前来，","notes":[]},{"n":5,"t":"对摩西说：“百姓送来的礼物很多，已经超过耶和华吩咐建造之工所需要的了。”","notes":[]},{"n":6,"t":"摩西吩咐，他们就在营中传令说：“无论男女，不必再为圣所的礼物做任何的工。”这样才使百姓停止，不再拿礼物来，","notes":[]},{"n":7,"t":"他们所有的材料已经足够整个工程之用，而且有余。","notes":[]},{"n":8,"t":"做工的人当中，凡心里有智慧的，用十幅幔子做帐幕，幔子是用搓的细麻和蓝色、紫色、朱红色纱织成的，并且以刺绣的手艺绣上基路伯。","notes":[],"heads":["造帐幕"]},{"n":9,"t":"每幅幔子长二十八肘，每幅幔子宽四肘，全部的幔子都是一样的尺寸。","notes":[]},{"n":10,"t":"他使这五幅幔子彼此相连，又使那五幅幔子彼此相连。","notes":[]},{"n":11,"t":"他在这一组相连幔子的末幅边上缝了蓝色的钮环；在另一组相连幔子的末幅边上也照样做。","notes":[]},{"n":12,"t":"他在这幅幔子上缝五十个钮环，在另一组相连幔子的末幅上也缝五十个钮环，环环相对。","notes":[]},{"n":13,"t":"他又做了五十个金钩，用钩子使幔子彼此相连，成为一个帐幕。","notes":[]},{"n":14,"t":"他用山羊毛织十一幅幔子，作为帐幕上的罩棚。","notes":[]},{"n":15,"t":"每幅幔子长三十肘，每幅幔子宽四肘；十一幅幔子都是一样的尺寸。","notes":[]},{"n":16,"t":"他把五幅幔子连成一幅，又把六幅幔子连成一幅。","notes":[]},{"n":17,"t":"他在这一组相连幔子的末幅边上缝了五十个钮环；在另一组相连幔子的末幅边上也缝了五十个钮环。","notes":[]},{"n":18,"t":"他又做五十个铜钩，使罩棚相连成为一个。","notes":[]},{"n":19,"t":"他用染红的公羊皮做罩棚的盖，再用精美皮料做外层的盖。","notes":[]},{"n":20,"t":"他用金合欢木做竖立帐幕的木板，","notes":[]},{"n":21,"t":"木板长十肘，每块板宽一肘半，","notes":[]},{"n":22,"t":"每块板有两个榫头可以彼此衔接。帐幕一切的板都是这样做。","notes":[]},{"n":23,"t":"他做帐幕的木板：南面，就是面向南方的那一边，做二十块板，","notes":[]},{"n":24,"t":"在这二十块板底下做了四十个带卯眼的银座：两个卯眼接连这块板上的两个榫头，另外两个卯眼接连那块板上的两个榫头。","notes":[]},{"n":25,"t":"他在帐幕的第二边，就是北面，也做二十块板，","notes":[]},{"n":26,"t":"和四十个带卯眼的银座；这块板底下有两个卯眼，那块板底下也有两个卯眼。","notes":[]},{"n":27,"t":"他在帐幕的后面，就是西面，做六块板，","notes":[]},{"n":28,"t":"在帐幕后面的角落做两块板。","notes":[]},{"n":29,"t":"下端的板是成双的，上端连在一起，直到顶端的第一个环子；两块板都是这样，做成两个角落。","notes":[]},{"n":30,"t":"一共有八块板和十六个带卯眼的银座，每块板底下有两个卯眼。","notes":[]},{"n":31,"t":"他用金合欢木做横木：为帐幕这面的板做五根横木，","notes":[]},{"n":32,"t":"为帐幕那面的板做五根横木，又为帐幕后面，就是朝西的板做五根横木，","notes":[]},{"n":33,"t":"他做了板腰间的横木，从一头通到另一头。","notes":[]},{"n":34,"t":"他将板包上金子，又做板上的金环来套横木；横木也包上金子。","notes":[]},{"n":35,"t":"他用蓝色、紫色、朱红色纱，和搓的细麻织幔子，以刺绣的手艺绣上基路伯。","notes":[]},{"n":36,"t":"他又用金合欢木为幔子做四根柱子，包上金子，柱子有金钩，又为柱子铸了四个带卯眼的银座。","notes":[]},{"n":37,"t":"他用蓝色、紫色、朱红色纱，和搓的细麻，以刺绣的手艺为帐幕织门帘，","notes":[]},{"n":38,"t":"又为帘子做五根柱子和柱子的钩子，把柱顶和柱子的箍包上金子。柱子有五个带卯眼的铜座。","notes":[]}]},"37":{"heading":"造约柜","verses":[{"n":1,"t":"比撒列用金合欢木做一个柜子，长二肘半，宽一肘半，高一肘半。","notes":[]},{"n":2,"t":"里里外外包上纯金，四围镶上金边。","notes":[]},{"n":3,"t":"他又铸了四个金环，安在柜子的四脚上；这边两个环，那边两个环。","notes":[]},{"n":4,"t":"他用金合欢木做了两根杠，包上金子，","notes":[]},{"n":5,"t":"又把杠穿过柜旁的环，以便抬柜。","notes":[]},{"n":6,"t":"他用纯金做了一个柜盖，长二肘半，宽一肘半，","notes":[]},{"n":7,"t":"他造两个用金子锤出的基路伯，从柜盖的两端锤出它们。","notes":[]},{"n":8,"t":"这端一个基路伯，那端一个基路伯；从柜盖的两端锤出两个基路伯。","notes":[]},{"n":9,"t":"二基路伯的翅膀向上张开，用翅膀遮住柜盖，脸彼此相对；基路伯的脸朝向柜盖。","notes":[]},{"n":10,"t":"他用金合欢木做了一张供桌，长二肘，宽一肘，高一肘半，","notes":[],"heads":["造供桌"]},{"n":11,"t":"把它包上纯金，四围镶上金边。","notes":[]},{"n":12,"t":"供桌的四围各做了一掌宽的边缘，边缘镶上金边。","notes":[]},{"n":13,"t":"他又铸了四个金环，把环安在四个桌脚的四角上。","notes":[]},{"n":14,"t":"环靠近边缘，以便穿杠抬供桌。","notes":[]},{"n":15,"t":"他用金合欢木做了两根杠，包上金子，用来抬供桌。","notes":[]},{"n":16,"t":"他又用纯金做了桌上的器具，就是盘、碟，以及浇酒祭的杯和壶。","notes":[]},{"n":17,"t":"他造一座用纯金锤出的灯台；灯台的座、干、杯、花萼和花瓣，都和灯台接连一块。","notes":[],"heads":["造灯台"]},{"n":18,"t":"灯台两旁伸出六根枝子：这边三根，那边三根。","notes":[]},{"n":19,"t":"这边的枝子上有三个杯，形状像杏花，有花萼有花瓣；那边的枝子上也有三个杯，形状像杏花，有花萼有花瓣。从灯台伸出来的六根枝子都是如此。","notes":[]},{"n":20,"t":"灯台本身有四个杯，形状像杏花，有花萼有花瓣。","notes":[]},{"n":21,"t":"灯台的第一对枝子下面有花萼，灯台的第二对枝子下面有花萼，灯台的第三对枝子下面也有花萼；灯台伸出的六根枝子都是如此。","notes":[]},{"n":22,"t":"花萼和枝子都和灯台接连一块，全是从一块纯金锤出来的。","notes":[]},{"n":23,"t":"他用纯金做灯台的七盏灯，以及灯剪和灯盘。","notes":[]},{"n":24,"t":"他用一他连得的纯金做灯台和灯台的一切器具。","notes":[]},{"n":25,"t":"他用金合欢木做香坛，长一肘，宽一肘，这坛是正方形的，高二肘。坛的四个翘角与坛接连一块。","notes":[],"heads":["造香坛"]},{"n":26,"t":"他把坛的上面与坛的四围，以及坛的四个翘角包上纯金，又在坛的四围镶上金边。","notes":[]},{"n":27,"t":"他在坛的两个对侧，金边下面做了两个金环，用来穿杠抬坛。","notes":[]},{"n":28,"t":"他又用金合欢木做杠，包上金子。","notes":[]},{"n":29,"t":"他按配制香料的方法制成圣膏油和芬芳的纯香。","notes":[],"heads":["造圣膏油和香"]}]},"38":{"heading":"造燔祭坛","verses":[{"n":1,"t":"他用金合欢木做燔祭坛，长五肘，宽五肘，是正方形的，高三肘。","notes":[]},{"n":2,"t":"在坛的四角做四个翘角，与坛接连一块，把坛包上铜。","notes":[]},{"n":3,"t":"他做坛的一切器具，就是桶子、铲子、盘子、肉叉和火盆；这一切器具都是用铜做的。","notes":[]},{"n":4,"t":"他又为坛做一个铜网，安在坛四围的边的下面，垂到坛的半腰。","notes":[]},{"n":5,"t":"他在铜网的四角上铸了四个环，用来穿杠。","notes":[]},{"n":6,"t":"他用金合欢木做杠，包上铜，","notes":[]},{"n":7,"t":"把杠穿过坛两旁的环子，用来抬坛。他用板做坛，坛的中心是空的。","notes":[]},{"n":8,"t":"他用铜做洗濯盆和盆座，是用会幕门前事奉之妇人的铜镜做的。","notes":[],"heads":["造洗濯盆"]},{"n":9,"t":"他又做院子，在南面，就是面向南方的那一边，用搓的细麻做院子的帷幔，一百肘。","notes":[],"heads":["造院子"]},{"n":10,"t":"帷幔有二十根柱子，二十个带卯眼的铜座；柱子的钩和箍都是银的。","notes":[]},{"n":11,"t":"北面的帷幔一百肘。帷幔有二十根柱子，二十个带卯眼的铜座；柱子的钩和箍都是银的。","notes":[]},{"n":12,"t":"西面的帷幔五十肘。帷幔有十根柱子，十个带卯眼的座；柱子的钩和箍都是银的。","notes":[]},{"n":13,"t":"院子的东面，就是面向东方的那一边，五十肘。","notes":[]},{"n":14,"t":"一边的帷幔有十五肘，有三根柱子，三个带卯眼的座。","notes":[]},{"n":15,"t":"另一边也一样，院子门口左右的帷幔也有十五肘，有三根柱子，三个带卯眼的座。","notes":[]},{"n":16,"t":"院子四面的帷幔都是用搓的细麻做的。","notes":[]},{"n":17,"t":"柱子带卯眼的座是铜的，柱子的钩和箍是银的，柱顶是用银包的。院子一切的柱子都是用银子箍着的。","notes":[]},{"n":18,"t":"院子的门帘是以刺绣的手艺，用蓝色、紫色、朱红色纱，和搓的细麻织的，长二十肘，宽也就是高五肘，与院子帷幔的高度相同。","notes":[]},{"n":19,"t":"门帘有四根柱子，四个带卯眼的铜座；柱子上的钩和箍是银的，柱顶是用银包的。","notes":[]},{"n":20,"t":"帐幕一切的橛子和院子四围的橛子都是铜的。","notes":[]},{"n":21,"t":"这是帐幕，就是法柜帐幕中物件的总数，是照摩西的吩咐，亚伦祭司的儿子以他玛经手，利未人数点的。","notes":[],"heads":["造会幕所用的金属"]},{"n":22,"t":"凡耶和华吩咐摩西的，都是由犹大支派中户珥的孙子，乌利的儿子比撒列去做的；","notes":[]},{"n":23,"t":"与他同工的有但支派中亚希撒抹的儿子亚何利亚伯；他是雕刻师，也是设计师，又是用蓝色、紫色、朱红色纱，和细麻的刺绣师。","notes":[]},{"n":24,"t":"为圣所一切工作用的金子，就是所奉献的金子，按圣所的舍客勒，一共是二十九他连得，七百三十舍客勒。","notes":[]},{"n":25,"t":"会中被数的人所献的银子，按圣所的舍客勒，一共是一百他连得，一千七百七十五舍客勒。","notes":[]},{"n":26,"t":"凡曾被数的，就是二十岁以上的人，共有六十万零三千五百五十人。按圣所的舍客勒，每人半舍客勒，就是一比加。","notes":[]},{"n":27,"t":"一百他连得银子是用来铸造圣所带卯眼的座和幔子下带卯眼的座；用一百他连得铸造一百个带卯眼的座，每个带卯眼的座一他连得。","notes":[]},{"n":28,"t":"一千七百七十五舍客勒是用来铸造柱子的钩，包柱顶，以及箍着柱子。","notes":[]},{"n":29,"t":"所奉献的铜共有七十他连得，二千四百舍客勒。","notes":[]},{"n":30,"t":"这些铜是用来做会幕门口带卯眼的座，铜坛、坛的铜网和坛的一切器具，","notes":[]},{"n":31,"t":"院子四围带卯眼的座和院子门口带卯眼的座，以及帐幕一切的橛子和院子四围所有的橛子。","notes":[]}]},"39":{"heading":"为祭司制圣服","verses":[{"n":1,"t":"他们用蓝色、紫色、朱红色纱缝制精致的礼服，在圣所用以供职；他们为亚伦做圣衣，是照耶和华所吩咐摩西的。","notes":[]},{"n":2,"t":"以弗得是用金色、蓝色、紫色、朱红色纱，和搓的细麻做的。","notes":[]},{"n":3,"t":"他们把金子锤成薄片，剪成细线，与蓝色、紫色、朱红色纱，以刺绣的手艺织在一起。","notes":[]},{"n":4,"t":"他们又为以弗得做两条相连的肩带，接连在以弗得的两端。","notes":[]},{"n":5,"t":"以弗得的精致带子以一样的手艺，用金色、蓝色、紫色、朱红色纱，和搓的细麻缝制，与以弗得接连在一起，是照耶和华所吩咐摩西的。","notes":[]},{"n":6,"t":"他们琢出两块红玛瑙，镶在金槽里，如同刻印章，刻上以色列众子的名字。","notes":[]},{"n":7,"t":"他把这两块宝石安在以弗得的两条肩带上，为以色列人作纪念石，是照耶和华所吩咐摩西的。","notes":[]},{"n":8,"t":"胸袋是以刺绣的手艺，如同以弗得的做法，用金色、蓝色、紫色、朱红色纱，和搓的细麻缝制。","notes":[]},{"n":9,"t":"胸袋是正方形的，他们把它做成两层，这两层各长一虎口，宽一虎口。","notes":[]},{"n":10,"t":"他们在上面镶四行宝石：第一行是红宝石、红璧玺、红玉；","notes":[]},{"n":11,"t":"第二行是绿宝石、蓝宝石、金刚石；","notes":[]},{"n":12,"t":"第三行是紫玛瑙、白玛瑙、紫晶；","notes":[]},{"n":13,"t":"第四行是水苍玉、红玛瑙、碧玉。这些都镶在金槽中。","notes":[]},{"n":14,"t":"这些宝石有以色列十二个儿子的名字，如同刻印章，每一颗有自己的名字，代表十二个支派。","notes":[]},{"n":15,"t":"他们在胸袋上用纯金打链子，像编成的绳子一样。","notes":[]},{"n":16,"t":"他们又做了两个金槽和两个金环，把这两个环安在胸袋的两端。","notes":[]},{"n":17,"t":"他们把那两条编成的金链系在胸袋两端的两个环上，","notes":[]},{"n":18,"t":"又把链子的另外两端扣在两个槽上，安在以弗得前面的肩带上。","notes":[]},{"n":19,"t":"他们做了两个金环，安在胸袋的两端，在以弗得里面的边上，","notes":[]},{"n":20,"t":"又做两个金环，安在以弗得前面两条肩带的下边，靠近接缝处，在精致带子的上面。","notes":[]},{"n":21,"t":"他们用蓝色的带子把胸袋的环与以弗得的环系住，使胸袋绑在以弗得精致的带子上，不致松脱，是照耶和华所吩咐摩西的。","notes":[]},{"n":22,"t":"以弗得的外袍是以编织的手艺做的，颜色全是蓝的。","notes":[]},{"n":23,"t":"袍上方的中间留了一个领口，领口的周围织出领边，好像铠甲的领口，免得破裂。","notes":[]},{"n":24,"t":"他们在袍子下摆用蓝色、紫色、朱红色纱，和搓的细麻做石榴，","notes":["原文没有“细麻”。"]},{"n":25,"t":"又用纯金铸了铃铛，把铃铛钉在石榴中间，袍子下摆周围的石榴中间：","notes":[]},{"n":26,"t":"一个铃铛一个石榴，一个铃铛一个石榴，在袍子下摆的周围，用以供职，是照耶和华所吩咐摩西的。","notes":[]},{"n":27,"t":"他们用编织的工为亚伦和他的儿子做细麻布内袍、","notes":[]},{"n":28,"t":"细麻布礼冠、细麻布精致头巾，和搓的细麻布裤子，","notes":[]},{"n":29,"t":"又用蓝色、紫色、朱红色纱，和搓的细麻，以刺绣的手艺做腰带，是照耶和华所吩咐摩西的。","notes":[]},{"n":30,"t":"他们用纯金做一面圣冠上的牌，如同刻印章，在上面写着“归耶和华为圣”，","notes":[]},{"n":31,"t":"又用蓝色的带子把牌系在礼冠上，是照耶和华所吩咐摩西的。","notes":[]},{"n":32,"t":"会幕的帐幕一切的工程就这样做完了。凡耶和华所吩咐摩西的，以色列人都照样做了。","notes":[],"heads":["会幕完工"]},{"n":33,"t":"他们把帐幕运到摩西那里，帐幕和帐幕的一切器具，就是钩、板、横木、柱子、带卯眼的座，","notes":[]},{"n":34,"t":"染红公羊皮的盖、精美皮料的盖、遮掩的幔子，","notes":[]},{"n":35,"t":"法柜、柜的杠、柜盖，","notes":[]},{"n":36,"t":"供桌、供桌的一切器具、供饼，","notes":[]},{"n":37,"t":"纯金的灯台、摆列的灯、灯台的一切器具、点灯的油，","notes":[]},{"n":38,"t":"金坛、膏油、芬芳的香、帐幕的门帘，","notes":[]},{"n":39,"t":"铜坛、坛的铜网、坛的杠、坛的一切器具，洗濯盆和盆座，","notes":[]},{"n":40,"t":"院子的帷幔、柱子、带卯眼的座、院子的门帘、绳子、橛子，帐幕，就是会幕使用的一切器具，","notes":[]},{"n":41,"t":"以及圣所事奉用的精致礼服，亚伦祭司的圣衣和他儿子的衣服，供祭司职分用。","notes":[]},{"n":42,"t":"这一切工作都是以色列人照耶和华所吩咐摩西做的。","notes":[]},{"n":43,"t":"摩西看见这一切的工，看哪，耶和华怎样吩咐，他们就照样做了，摩西就为他们祝福。","notes":[]}]},"40":{"heading":"耶和华会幕的建立和奉献","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“正月初一，你要立起会幕的帐幕，","notes":[]},{"n":3,"t":"把法柜安放在里面，用幔子将柜遮掩。","notes":[]},{"n":4,"t":"把供桌搬进去，摆设桌上的器具。又把灯台搬进去，点上灯。","notes":[]},{"n":5,"t":"把金香坛安在法柜前，挂上帐幕的门帘。","notes":[]},{"n":6,"t":"把燔祭坛安在会幕的帐幕门前。","notes":[]},{"n":7,"t":"把洗濯盆安在会幕和坛的中间，在盆里盛水。","notes":[]},{"n":8,"t":"又要在院子周围支起帷幔，把院子的门帘挂上。","notes":[]},{"n":9,"t":"你要用膏油抹帐幕和其中所有的，使帐幕和一切器具分别为圣，就都成为圣。","notes":[]},{"n":10,"t":"又要抹燔祭坛和坛的一切器具，使坛分别为圣，坛就成为至圣。","notes":[]},{"n":11,"t":"要抹洗濯盆和盆座，使盆分别为圣。","notes":[]},{"n":12,"t":"你要带亚伦和他儿子到会幕门口，用水洗身。","notes":[]},{"n":13,"t":"要给亚伦穿上圣衣，又膏他，使他分别为圣，作事奉我的祭司。","notes":[]},{"n":14,"t":"又要带他的儿子来，给他们穿上内袍。","notes":[]},{"n":15,"t":"你怎样膏他们的父亲，也要照样膏他们，使他们成为事奉我的祭司。他们受了膏，就必世世代代永远得祭司的职分。”","notes":[]},{"n":16,"t":"摩西这样做了；耶和华怎样吩咐摩西，他就照样做了。","notes":[]},{"n":17,"t":"第二年正月初一，帐幕就立起来。","notes":[]},{"n":18,"t":"摩西支起帐幕，安上带卯眼的座，安上板，穿上横木，立起柱子。","notes":[]},{"n":19,"t":"他在帐幕的上面搭上罩棚，把罩棚外层的盖子盖在其上，是照着耶和华所吩咐他的。","notes":[]},{"n":20,"t":"他把法版放在柜里，把杠穿在柜的两旁，把柜盖安在柜上。","notes":[]},{"n":21,"t":"把柜抬进帐幕，挂上遮掩柜的幔子，把法柜遮盖了，是照耶和华所吩咐摩西的。","notes":[]},{"n":22,"t":"他把供桌安在会幕内，在帐幕的北边，幔子的外面。","notes":[]},{"n":23,"t":"把饼摆设在供桌上，在耶和华面前，是照耶和华所吩咐摩西的。","notes":[]},{"n":24,"t":"他把灯台安在会幕内，在帐幕的南边，供桌的对面，","notes":[]},{"n":25,"t":"并在耶和华面前点灯，是照耶和华所吩咐摩西的。","notes":[]},{"n":26,"t":"他把金坛安在会幕内，幔子的前面，","notes":[]},{"n":27,"t":"又在坛上烧芬芳的香，是照耶和华所吩咐摩西的。","notes":[]},{"n":28,"t":"他又挂上帐幕的门帘。","notes":[]},{"n":29,"t":"在会幕的帐幕门口安设燔祭坛，把燔祭和素祭献在坛上，是照耶和华所吩咐摩西的。","notes":[]},{"n":30,"t":"他又把洗濯盆安在会幕和祭坛的中间，盆里盛水，以便洗濯。","notes":[]},{"n":31,"t":"摩西和亚伦，以及亚伦的儿子用这盆洗手洗脚。","notes":[]},{"n":32,"t":"他们进会幕或走近坛的时候，就都洗濯，是照耶和华所吩咐摩西的。","notes":[]},{"n":33,"t":"他在帐幕和祭坛的四围支起院子的帷幔，把院子的门帘挂上。这样，摩西就做完了工。","notes":[]},{"n":34,"t":"那时，云彩遮盖会幕，耶和华的荣光充满了帐幕。","notes":[],"heads":["云彩和荣光"]},{"n":35,"t":"摩西不能进会幕，因为云彩停在其上，耶和华的荣光充满了帐幕。","notes":[]},{"n":36,"t":"每逢云彩从帐幕升上去，以色列人就起程前行；","notes":[]},{"n":37,"t":"云彩若不升上去，他们就不起程，直等到云彩升上去。","notes":[]},{"n":38,"t":"在他们所行的路上，在以色列全家的眼前，白天，耶和华的云彩在帐幕上，黑夜，有火在云彩中。","notes":[]}]}},"LEV":{"1":{"heading":"燔祭的条例","verses":[{"n":1,"t":"耶和华从会幕中呼叫摩西，吩咐他说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人，对他们说：你们中间若有人要献供物给耶和华，可以从牛群羊群中献牲畜为供物。","notes":[]},{"n":3,"t":"“他的供物若以牛为燔祭，要献一头没有残疾的公牛，献在会幕的门口，他就可以在耶和华面前蒙悦纳。","notes":[]},{"n":4,"t":"他要按手在燔祭牲的头上，为自己赎罪，就蒙悦纳。","notes":[]},{"n":5,"t":"他要在耶和华面前宰公牛犊；亚伦子孙作祭司的要献上血，把血洒在会幕门口坛的周围。","notes":[]},{"n":6,"t":"他要剥去燔祭牲的皮，把燔祭牲切成块。","notes":[]},{"n":7,"t":"亚伦祭司的子孙要在坛上生火，把柴摆在火上。","notes":[]},{"n":8,"t":"亚伦子孙作祭司的要把肉块连头和脂肪，摆在坛上烧着火的柴上。","notes":[]},{"n":9,"t":"燔祭牲的内脏与小腿要用水洗净，祭司要把整只全烧在坛上，当作燔祭，是献给耶和华为馨香的火祭。","notes":[]},{"n":10,"t":"“人的供物若以绵羊或山羊为燔祭，要献一只没有残疾的公羊。","notes":[]},{"n":11,"t":"他要在坛的北边，在耶和华面前宰羊；亚伦子孙作祭司的要把血洒在坛的周围。","notes":[]},{"n":12,"t":"他要把燔祭牲切成块，祭司就要把肉块连头和脂肪，摆在坛上烧着火的柴上。","notes":[]},{"n":13,"t":"内脏与小腿要用水洗净，祭司要把整只献上，全烧在坛上。这是燔祭，是献给耶和华为馨香的火祭。","notes":[]},{"n":14,"t":"“人献给耶和华的供物若以鸟为燔祭，就要献斑鸠或雏鸽为他的供物。","notes":[]},{"n":15,"t":"祭司要把鸟拿到坛前，扭断它的头，把鸟烧在坛上，鸟的血要流在坛的旁边；","notes":[]},{"n":16,"t":"又要把鸟的嗉囊和里面的脏物除掉，丢在坛东边倒灰的地方。","notes":["“脏物”或译“羽毛”。"]},{"n":17,"t":"他要拿着鸟的两个翅膀，把鸟撕开，却不可撕断；祭司要把它摆在坛上烧着火的柴上焚烧。这是燔祭，是献给耶和华为馨香的火祭。”","notes":[]}]},"2":{"heading":"素祭的条例","verses":[{"n":1,"t":"“若有人献素祭为供物给耶和华，就要献细面为供物，把油浇在上面，加上乳香，","notes":[]},{"n":2,"t":"带到亚伦子孙作祭司的那里。祭司要从细面中取出满满的一把，又取些油和所有的乳香，把这些作为纪念的烧在坛上，是献给耶和华为馨香的火祭。","notes":[]},{"n":3,"t":"素祭所剩的要归给亚伦和他的子孙；在献给耶和华的火祭中，这是至圣的。","notes":[]},{"n":4,"t":"“若献炉中烤的素祭为供物，要用调了油的无酵细面饼，或抹了油的无酵薄饼。","notes":[]},{"n":5,"t":"若以铁盘上的素祭为供物，就要用调了油的无酵细面，","notes":[]},{"n":6,"t":"分成小块，浇上油；这是素祭。","notes":[]},{"n":7,"t":"若以煎锅煎的素祭为供物，就要用油与细面做成。","notes":[]},{"n":8,"t":"要把这样做成的素祭带到耶和华面前，拿给祭司，祭司要带到坛前。","notes":[]},{"n":9,"t":"祭司要从素祭中取出作为纪念的烧在坛上，是献给耶和华为馨香的火祭。","notes":[]},{"n":10,"t":"素祭所剩的要归给亚伦和他的子孙；在献给耶和华的火祭中，这是至圣的。","notes":[]},{"n":11,"t":"“凡献给耶和华的素祭都不可以有酵，因为你们不可把任何的酵或蜜烧了，当作火祭献给耶和华。","notes":[]},{"n":12,"t":"你们可以把这些献给耶和华当作初熟的供物，但是不可献在坛上作为馨香的祭。","notes":[]},{"n":13,"t":"凡献为素祭的供物都要用盐调和；在素祭中，不可缺少你与神立约的盐。一切的供物都要加盐献上。","notes":[]},{"n":14,"t":"“你若献初熟之物给耶和华为素祭，就要献在火中烘过的新麦穗，就是磨碎的新谷物，当作初熟之物的素祭。","notes":[]},{"n":15,"t":"你要加上油和乳香；这是素祭。","notes":[]},{"n":16,"t":"祭司要把供物中作为纪念的，就是一些磨碎的新谷物和一些油，以及所有的乳香，都焚烧，是献给耶和华的火祭。”","notes":[]}]},"3":{"heading":"平安祭的条例","verses":[{"n":1,"t":"“人献平安祭为供物，若是从牛群中献，无论是公的母的，要用没有残疾的，献在耶和华面前。","notes":[]},{"n":2,"t":"他要按手在供物的头上，在会幕的门口宰了它。亚伦子孙作祭司的，要把血洒在坛的周围。","notes":[]},{"n":3,"t":"从平安祭中，他要把火祭献给耶和华，就是包着内脏的脂肪和内脏上所有的脂肪，","notes":[]},{"n":4,"t":"两个肾和肾上的脂肪，即靠近肾两旁的脂肪，以及肝上的网油，连同肾一起取下。","notes":[]},{"n":5,"t":"亚伦的子孙要把这些摆在烧着火的柴上，烧在坛的燔祭上，是献给耶和华为馨香的火祭。","notes":[]},{"n":6,"t":"“人向耶和华献平安祭为供物，若是从羊群中献，无论是公的母的，要用没有残疾的。","notes":[]},{"n":7,"t":"若他献一只绵羊为供物，就要把它献在耶和华面前。","notes":[]},{"n":8,"t":"要按手在供物的头上，在会幕前宰了它。亚伦的子孙要把血洒在坛的周围。","notes":[]},{"n":9,"t":"从平安祭中，他要取脂肪当作火祭献给耶和华，就是靠近脊骨处取下的整条肥尾巴，包着内脏的脂肪和内脏上所有的脂肪，","notes":[]},{"n":10,"t":"两个肾和肾上的脂肪，即靠近肾两旁的脂肪，以及肝上的网油，连同肾一起取下。","notes":[]},{"n":11,"t":"祭司要把这些烧在坛上，是献给耶和华为食物的火祭。","notes":[]},{"n":12,"t":"“人的供物若是山羊，就要把它献在耶和华面前。","notes":[]},{"n":13,"t":"要按手在它的头上，在会幕前宰了它。亚伦的子孙要把血洒在坛的周围，","notes":[]},{"n":14,"t":"又要从供物中把火祭献给耶和华，就是包着内脏的脂肪和内脏上所有的脂肪，","notes":[]},{"n":15,"t":"两个肾和肾上的脂肪，即靠近肾两旁的脂肪，以及肝上的网油，连同肾一起取下。","notes":[]},{"n":16,"t":"祭司要把这些烧在坛上，作为馨香火祭的食物；所有的脂肪都是耶和华的。","notes":[]},{"n":17,"t":"在你们一切的住处，脂肪和血都不可吃，这要成为你们世世代代永远的定例。”","notes":[]}]},"4":{"heading":"赎罪祭的条例","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人说：若有人无意中犯罪，在任何事上犯了一条耶和华所吩咐的禁令，","notes":[]},{"n":3,"t":"或是受膏的祭司犯了罪，使百姓陷在罪里，他就当为自己所犯的罪，把没有残疾的公牛犊献给耶和华为赎罪祭。","notes":[]},{"n":4,"t":"他要把公牛牵到会幕的门口，在耶和华面前按手在牛的头上，把牛宰于耶和华面前。","notes":[]},{"n":5,"t":"受膏的祭司要取些公牛的血，带到会幕那里。","notes":[]},{"n":6,"t":"祭司要把手指蘸在血中，在耶和华面前对着圣所的幔子弹血七次，","notes":[]},{"n":7,"t":"又要把一些血抹在会幕内，耶和华面前香坛的四个翘角上，再把公牛其余的血全倒在会幕门口燔祭坛的底座上；","notes":[]},{"n":8,"t":"又要取出这头赎罪祭公牛所有的脂肪，就是包着内脏的脂肪和内脏上所有的脂肪，","notes":[]},{"n":9,"t":"两个肾和肾上的脂肪，即靠近肾两旁的脂肪，以及肝上的网油，连同肾一起取下，","notes":[]},{"n":10,"t":"正如从平安祭的牛身上所取的，祭司要把这些烧在燔祭坛上。","notes":[]},{"n":11,"t":"但公牛的皮和所有的肉，以及头、腿、内脏、粪，","notes":[]},{"n":12,"t":"就是全公牛，要搬到营外清洁的地方倒灰之处，放在柴上用火焚烧。","notes":[]},{"n":13,"t":"“以色列全会众若犯了错，在任何事上犯了一条耶和华所吩咐的禁令，而有了罪，会众看不出这隐藏的事；","notes":[]},{"n":14,"t":"他们一知道犯了罪，就要献一头公牛犊为赎罪祭，牵它到会幕前。","notes":[]},{"n":15,"t":"会众的长老要在耶和华面前按手在公牛的头上，把牛宰于耶和华面前。","notes":[]},{"n":16,"t":"受膏的祭司要取些公牛的血，带到会幕那里。","notes":[]},{"n":17,"t":"祭司要用手指蘸一些血，在耶和华面前对着幔子弹七次，","notes":[]},{"n":18,"t":"又要把一些血抹在会幕内，耶和华面前坛的四个翘角上，再把其余的血全倒在会幕门口燔祭坛的底座上。","notes":[]},{"n":19,"t":"他要取出公牛所有的脂肪，烧在坛上。","notes":[]},{"n":20,"t":"他要处理这牛，正如处理那头赎罪祭的公牛一样，他要如此去做。祭司要为他们赎罪，他们就蒙赦免。","notes":[]},{"n":21,"t":"他要把牛搬到营外烧了，像烧前一头公牛一样；这是会众的赎罪祭。","notes":[]},{"n":22,"t":"“官长若犯罪，在任何事上无意中犯了一条耶和华－他的神所吩咐的禁令，而有了罪，","notes":[]},{"n":23,"t":"他一知道自己犯了罪，就要牵一只没有残疾的公山羊为供物。","notes":[]},{"n":24,"t":"他要按手在羊的头上，在耶和华面前宰燔祭牲的地方把它宰了；这是赎罪祭。","notes":[]},{"n":25,"t":"祭司要用手指蘸一些赎罪祭牲的血，抹在燔祭坛的四个翘角上，再把其余的血倒在燔祭坛的底座上。","notes":[]},{"n":26,"t":"祭牲所有的脂肪都要烧在坛上，正如平安祭的脂肪一样。祭司要为他的罪赎了他，他就蒙赦免。","notes":[]},{"n":27,"t":"“这地的百姓若有人无意中犯罪，在任何事上犯了一条耶和华所吩咐的禁令，而有了罪，","notes":[]},{"n":28,"t":"他一知道自己犯了罪，就要为所犯的罪牵一只没有残疾的母山羊为供物。","notes":[]},{"n":29,"t":"他要按手在赎罪祭牲的头上，在燔祭牲的地方把它宰了。","notes":[]},{"n":30,"t":"祭司要用手指蘸一些祭牲的血，抹在燔祭坛的四个翘角上，再把其余的血全倒在坛的底座上；","notes":[]},{"n":31,"t":"又要把祭牲所有的脂肪都取下，正如取平安祭牲的脂肪一样。祭司要把脂肪烧在坛上，在耶和华面前作为馨香的祭。祭司要为他赎罪，他就蒙赦免。","notes":[]},{"n":32,"t":"“人若牵一只绵羊为赎罪祭作供物，就要牵一只没有残疾的母羊。","notes":[]},{"n":33,"t":"他要按手在赎罪祭牲的头上，在宰燔祭牲的地方宰了它，作为赎罪祭。","notes":[]},{"n":34,"t":"祭司要用手指蘸一些赎罪祭牲的血，抹在燔祭坛的四个翘角上，再把其余的血全倒在坛的底座上；","notes":[]},{"n":35,"t":"又要把祭牲所有的脂肪都取下，正如取平安祭的羊的脂肪一样。祭司要按献给耶和华火祭的条例，把脂肪烧在坛上。祭司要为他所犯的罪赎了他，他就蒙赦免。”","notes":[]}]},"5":{"heading":"赎愆祭的条例","verses":[{"n":1,"t":"“若有人犯了罪，就是听见了誓言，他本来可以作证，却不把所看见、所知道的说出来，必须担当他的罪孽。","notes":[]},{"n":2,"t":"若有人摸了任何不洁之物，无论是野兽的不洁尸体，家畜的不洁尸体，或是群聚动物的不洁尸体，他虽不察觉，也是不洁净，就有罪了。","notes":[]},{"n":3,"t":"或是他摸了人的不洁之物，就是任何使人成为不洁的不洁之物，他虽不察觉，但一知道，就有罪了。","notes":[]},{"n":4,"t":"若有人随口发誓，或出于恶意，或出于善意，这人无论在什么事上随意发誓，虽不察觉，但一知道，就在这其中的一件事上有罪了。","notes":[]},{"n":5,"t":"当他在这其中的一件事上有罪的时候，就要承认所犯的罪，","notes":[]},{"n":6,"t":"并要为所犯的罪，把他的赎愆祭牲，就是羊群中的一只母绵羊或母山羊，献给耶和华为赎罪祭，祭司要为他的罪赎了他。","notes":[]},{"n":7,"t":"“若他的力量不够献一只绵羊，就要为所犯的罪，把两只斑鸠或是两只雏鸽献给耶和华为赎愆祭：一只作赎罪祭，一只作燔祭。","notes":[]},{"n":8,"t":"他要把这些带到祭司那里，祭司就先把赎罪祭献上，从鸟的颈项上扭断它的头，但不把鸟撕断。","notes":[]},{"n":9,"t":"祭司要把一些赎罪祭牲的血弹在祭坛的边上，其余的血要倒在坛的底座上；这是赎罪祭。","notes":[]},{"n":10,"t":"他要依照条例献第二只鸟为燔祭。祭司要为他所犯的罪赎了他，他就蒙赦免。","notes":[]},{"n":11,"t":"“他的力量若不够献两只斑鸠或两只雏鸽，就要为所犯的罪把供物，就是十分之一伊法细面，献上为赎罪祭；不可加上油，也不可加上乳香，因为这是赎罪祭。","notes":[]},{"n":12,"t":"他要把细面带到祭司那里，祭司要取出满满的一把，作为纪念，按照献火祭给耶和华的条例把它烧在坛上；这是赎罪祭。","notes":[]},{"n":13,"t":"至于他在这几件事中所犯的任何罪，祭司要为他赎了，他就蒙赦免。剩下的都归给祭司，和素祭一样。”","notes":[]},{"n":14,"t":"耶和华吩咐摩西说：","notes":[]},{"n":15,"t":"“若有人在耶和华的圣物上无意中犯了罪，有了过犯，就要献羊群中一只没有残疾的公绵羊给耶和华为赎愆祭，或依圣所的舍客勒所估定的银子，作为赎愆祭。","notes":[]},{"n":16,"t":"他要为在圣物上的疏忽赔偿，另外加五分之一，把这些都交给祭司。祭司要用赎愆祭的公绵羊为他赎罪，他就蒙赦免。","notes":[]},{"n":17,"t":"“若有人犯罪，在任何事上犯了一条耶和华所吩咐的禁令，他虽不察觉，仍算有罪，必须担当自己的罪孽。","notes":[]},{"n":18,"t":"他要牵羊群中一只没有残疾的公绵羊，或照你所估定的价值，给祭司作赎愆祭。祭司要为他赎他因不知道而无意中所犯的罪，他就蒙赦免。","notes":[]},{"n":19,"t":"这是赎愆祭；因他确实得罪了耶和华。”","notes":[]}]},"6":{"heading":"祭司献燔祭的责任","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“若有人犯罪，得罪了耶和华，就是在邻舍寄托他的东西或抵押品上行诡诈，或抢夺，或欺压邻舍，","notes":[]},{"n":3,"t":"或是捡了失物行了诡诈，起了假誓，在人所做的任何事上犯了罪；","notes":[]},{"n":4,"t":"他既犯了罪，有了过犯，就要归还他所抢夺的，或是因欺压所得的，或是别人寄托他的，或是他所捡到的失物，","notes":[]},{"n":5,"t":"或是起假誓得来的任何东西，就要全数归还，另外再加五分之一。在查出他有罪的日子，就要立刻赔还给原主。","notes":[]},{"n":6,"t":"他要献羊群中一只没有残疾的公绵羊，给耶和华为赎愆祭，或照你所估定的价值，给祭司作赎愆祭。","notes":["七十士译本没有“给祭司”。"]},{"n":7,"t":"祭司要在耶和华面前为他赎罪；他无论做了什么事，以致有了罪，都必蒙赦免。”","notes":[]},{"n":8,"t":"耶和华吩咐摩西说：","notes":[]},{"n":9,"t":"“你要吩咐亚伦和他的子孙说，燔祭的条例是这样：燔祭要放在坛的底盘上，从晚上到天亮，坛上的火要不断地烧着。","notes":[]},{"n":10,"t":"祭司要穿上细麻布衣服，又要把细麻布裤子穿在身上，把在坛上烧剩的燔祭灰收起来，放在坛的旁边。","notes":[]},{"n":11,"t":"然后，他要脱去这衣服，穿上别的衣服，把灰拿到营外洁净之处。","notes":[]},{"n":12,"t":"坛上的火要不断地烧着，不可熄灭。每日早晨，祭司要在坛上烧柴，把燔祭摆在坛上，并烧平安祭牲的脂肪。","notes":[]},{"n":13,"t":"坛上的火要不断地烧着，不可熄灭。”","notes":[]},{"n":14,"t":"“素祭的条例是这样：亚伦的子孙要在坛前把这祭献在耶和华面前。","notes":[],"heads":["祭司献素祭的责任"]},{"n":15,"t":"祭司要从素祭中的细面取出一把，再取些油和素祭上所有的乳香，把这些作为纪念的烧在坛上，是献给耶和华为馨香的祭。","notes":[]},{"n":16,"t":"亚伦和他子孙要吃素祭剩下的；要在圣处吃这无酵饼，在会幕的院子里吃。","notes":[]},{"n":17,"t":"烤饼不可加酵。这是从献给我的火祭中归给他们的一份；如赎罪祭和赎愆祭一样，这份是至圣的。","notes":[]},{"n":18,"t":"亚伦子孙中的男丁都要吃，因为这是你们世世代代从献给耶和华的火祭中，他们永远应得的份。凡摸这些祭物的都要成为圣。”","notes":[]},{"n":19,"t":"耶和华吩咐摩西说：","notes":[]},{"n":20,"t":"“这是亚伦受膏的日子，他和他的子孙所要献给耶和华的供物：十分之一伊法细面，如他们经常献的素祭，早晨一半，晚上一半。","notes":[]},{"n":21,"t":"要在铁盘上用油调和，调匀后，就拿去烤。素祭烤熟了要分成小块，作为献给耶和华馨香的祭。","notes":[]},{"n":22,"t":"亚伦子孙中接续他受膏为祭司的，要把这素祭献上，全烧给耶和华。这是永远的定例。","notes":[]},{"n":23,"t":"祭司一切的素祭要全部烧了，不可以吃。”","notes":[]},{"n":24,"t":"耶和华吩咐摩西说：","notes":[],"heads":["祭司献赎罪祭的责任"]},{"n":25,"t":"“你要吩咐亚伦和他的子孙说，赎罪祭的条例是这样：要在耶和华面前宰燔祭牲的地方宰赎罪祭牲；这是至圣的。","notes":[]},{"n":26,"t":"献赎罪祭的祭司要吃这祭物；要在圣处，就是在会幕的院子里吃。","notes":[]},{"n":27,"t":"凡摸这祭肉的都要成为圣；这祭牲的血若溅在衣服上，你要在圣处洗净那溅到血的衣服。","notes":["“你要...衣服”：原文另译“那溅到血的地方要在圣处洗净”。"]},{"n":28,"t":"煮这祭物的瓦器要打碎；若祭物是在铜器里煮，要把这铜器擦净，用水冲洗。","notes":[]},{"n":29,"t":"祭司中所有的男丁都可以吃；这是至圣的。","notes":[]},{"n":30,"t":"若将任何赎罪祭的血带进会幕，为要在圣所赎罪，那肉就不可吃，要用火焚烧。”","notes":[]}]},"7":{"heading":"祭司献赎愆祭的责任","verses":[{"n":1,"t":"“赎愆祭的条例是这样：这祭是至圣的。","notes":[]},{"n":2,"t":"人在哪里宰燔祭牲，也要在哪里宰赎愆祭牲；其血，祭司要洒在坛的周围。","notes":[]},{"n":3,"t":"祭司要献上它所有的脂肪，把肥尾巴和包着内脏的脂肪，","notes":[]},{"n":4,"t":"两个肾和肾上的脂肪，即靠近肾两旁的脂肪，以及肝上的网油，连同肾一起取下。","notes":[]},{"n":5,"t":"祭司要把这些烧在坛上，献给耶和华为火祭，作为赎愆祭。","notes":[]},{"n":6,"t":"祭司中所有的男丁都可以吃这祭物，要在圣处吃；这是至圣的。","notes":[]},{"n":7,"t":"赎罪祭怎样，赎愆祭也是怎样，都有一样的条例，用赎愆祭赎罪的祭司要得这祭物。","notes":[]},{"n":8,"t":"献燔祭的祭司，无论为谁献，所献燔祭牲的皮要归给那祭司，那是他的。","notes":[]},{"n":9,"t":"任何素祭，无论是在炉中烤的，用煎锅或铁盘做成的，都要归给献祭的祭司。","notes":[]},{"n":10,"t":"任何素祭，无论是用油调和的，是干的，都要归亚伦的子孙，大家均分。”","notes":[]},{"n":11,"t":"“献给耶和华平安祭的条例是这样：","notes":[],"heads":["祭司献平安祭的责任"]},{"n":12,"t":"若有人为感谢献祭，就要把用油调和的无酵饼、抹了油的无酵薄饼，和用油调匀细面做成的饼，与感谢祭一同献上。","notes":[]},{"n":13,"t":"要用有酵的饼，和那为感谢而献的平安祭，与供物一同献上。","notes":[]},{"n":14,"t":"他要从每一种供物中拿一个饼，献给耶和华为举祭，是要归给那洒平安祭牲血的祭司。","notes":[]},{"n":15,"t":"为感谢而献的平安祭的肉，要在献祭当天吃，一点也不可留到早晨。","notes":[]},{"n":16,"t":"若所献的是还愿祭或甘心祭，要在献祭当天吃，剩下的，第二天也可以吃。","notes":[]},{"n":17,"t":"第三天，所剩下的祭肉要用火焚烧。","notes":[]},{"n":18,"t":"第三天若吃平安祭的肉，必不蒙悦纳，所献的也不算为祭；这祭物是不洁净的，凡吃这祭物的，必担当自己的罪孽。","notes":[]},{"n":19,"t":"“沾了不洁净之物的肉就不可吃，要用火焚烧。至于其他的肉，凡洁净的人都可以吃这肉；","notes":[]},{"n":20,"t":"但不洁净的人若吃了献给耶和华平安祭的肉，这人必从民中剪除。","notes":[]},{"n":21,"t":"若有人摸了不洁之物，无论是人体的不洁净，或是不洁的牲畜，或是不洁的可憎之物 ，再吃了献给耶和华平安祭的肉，这人必从民中剪除。”","notes":["“可憎之物”：有古卷是“群聚动物”。"]},{"n":22,"t":"耶和华吩咐摩西说：","notes":[]},{"n":23,"t":"“你要吩咐以色列人说：牛、绵羊、山羊的脂肪，你们都不可吃。","notes":[]},{"n":24,"t":"自然死去的或被野兽撕裂的，那脂肪可以作别的用途，你们却万不可吃。","notes":[]},{"n":25,"t":"任何人吃了献给耶和华作火祭祭牲的脂肪，这人必从民中剪除。","notes":[]},{"n":26,"t":"在你们一切的住处，无论是鸟或兽的血，你们都不可吃。","notes":[]},{"n":27,"t":"无论谁吃了血，这人必从民中剪除。”","notes":[]},{"n":28,"t":"耶和华吩咐摩西说：","notes":[]},{"n":29,"t":"“你要吩咐以色列人说：献平安祭给耶和华的，要从他的平安祭中取些供物来献给耶和华。","notes":[]},{"n":30,"t":"他要亲手把献给耶和华的火祭带来，要把脂肪和胸带来，把胸在耶和华面前摇一摇，作为摇祭。","notes":[]},{"n":31,"t":"祭司要把脂肪烧在坛上，但胸要归给亚伦和他的子孙。","notes":[]},{"n":32,"t":"你们要从平安祭牲中把右腿作为举祭，送给祭司。","notes":[]},{"n":33,"t":"亚伦子孙中献平安祭牲的血和脂肪的，要得这右腿，作为他当得的份。","notes":[]},{"n":34,"t":"因为我从以色列人的平安祭中，把这摇祭的胸和这举祭的腿给亚伦祭司和他子孙，作为他们在以色列人中永远当得的份。”","notes":[]},{"n":35,"t":"这是从耶和华的火祭中取出，作为亚伦和他子孙受膏的份，就是摩西叫他们前来，给耶和华供祭司职分的那一天开始的。","notes":[],"heads":["祭司责任的结语"]},{"n":36,"t":"这是在摩西膏他们的日子，耶和华吩咐给他们的，作为他们在以色列人中世世代代永远当得的份。","notes":[]},{"n":37,"t":"这就是燔祭、素祭、赎罪祭、赎愆祭、圣职礼和平安祭的条例，","notes":[]},{"n":38,"t":"都是耶和华在西奈山上吩咐摩西的，也是他在西奈旷野吩咐以色列人献供物给耶和华的日子所说的。","notes":[]}]},"8":{"heading":"祭司的条例","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你领亚伦和他儿子前来，并将圣衣、膏油，与赎罪祭的一头公牛、两只公绵羊、一筐无酵饼都一同带来；","notes":[]},{"n":3,"t":"又要召集全会众到会幕的门口。”","notes":[]},{"n":4,"t":"摩西就遵照耶和华的吩咐做了，于是会众聚集在会幕的门口。","notes":[]},{"n":5,"t":"摩西对会众说：“这是耶和华所吩咐当做的事。”","notes":[]},{"n":6,"t":"摩西领了亚伦和他儿子前来，用水洗他们。","notes":[]},{"n":7,"t":"他给亚伦穿上内袍，束上腰带，套上外袍，加上以弗得，再束上精致的带子，把以弗得系在他身上。","notes":[]},{"n":8,"t":"他又给亚伦戴上胸袋，把乌陵和土明放在胸袋内。","notes":[]},{"n":9,"t":"他把礼冠戴在亚伦的头上，礼冠前面安上金牌，成为圣冕，是照耶和华所吩咐摩西的。","notes":[]},{"n":10,"t":"摩西用膏油抹帐幕和其中所有的，使它们成为圣。","notes":[]},{"n":11,"t":"他又用膏油在祭坛上弹了七次，抹了坛和坛的一切器皿，以及洗濯盆和盆座，使它们成为圣。","notes":[]},{"n":12,"t":"他把膏油倒在亚伦的头上膏他，使他成为圣。","notes":[]},{"n":13,"t":"摩西带了亚伦的儿子来，给他们穿上内袍，束上腰带，裹上头巾，是照耶和华所吩咐摩西的。","notes":[]},{"n":14,"t":"他把赎罪祭的公牛牵来，亚伦和他儿子按手在赎罪祭公牛的头上，","notes":[]},{"n":15,"t":"就宰了公牛。摩西取了血，用指头抹在祭坛周围的四个翘角上，使坛洁净，再把其余的血倒在坛的底座上，使坛成为圣，为坛赎罪。","notes":[]},{"n":16,"t":"摩西把内脏所有的脂肪和肝上的网油，以及两个肾与肾上的脂肪取出，都烧在坛上。","notes":[]},{"n":17,"t":"至于公牛，连皮带肉和粪，他都用火烧在营外，是照耶和华所吩咐摩西的。","notes":[]},{"n":18,"t":"他把燔祭的公绵羊牵来，亚伦和他儿子按手在羊的头上，","notes":[]},{"n":19,"t":"就宰了公羊。摩西把血洒在祭坛的周围，","notes":[]},{"n":20,"t":"把羊切成块，把头和肉块，以及脂肪拿去烧，","notes":[]},{"n":21,"t":"他用水洗了内脏和腿之后，就把全羊烧在坛上，作为馨香的燔祭，是献给耶和华的火祭，都是照耶和华所吩咐摩西的。","notes":[]},{"n":22,"t":"他又牵来第二只公绵羊，就是圣职礼的羊，亚伦和他儿子按手在羊的头上，","notes":[]},{"n":23,"t":"就宰了羊。摩西把一些血抹在亚伦的右耳垂上，右手的大拇指上和右脚的大脚趾上。","notes":[]},{"n":24,"t":"他领了亚伦的儿子来，把一些血抹在他们的右耳垂上，右手的大拇指上和右脚的大脚趾上。摩西把其余的血洒在坛的周围。","notes":[]},{"n":25,"t":"他把脂肪，肥尾巴、内脏所有的脂肪、肝上的网油、两个肾、肾上的脂肪，和右腿取下，","notes":[]},{"n":26,"t":"再从耶和华面前那装无酵饼的篮子中取一个无酵饼、一个油饼和一个薄饼，把这些放在脂肪和右腿上。","notes":[]},{"n":27,"t":"他把这一切放在亚伦和他儿子的手上，在耶和华面前摇一摇，作为摇祭。","notes":[]},{"n":28,"t":"摩西从他们的手上把这些祭物拿来，放在坛的燔祭上烧，这就是圣职礼中献给耶和华馨香的火祭。","notes":[]},{"n":29,"t":"摩西拿羊的胸，在耶和华面前摇一摇，作为摇祭，这是圣职礼的羊归给摩西的一份，是照耶和华所吩咐摩西的。","notes":[]},{"n":30,"t":"摩西取些膏油和坛上的血，弹在亚伦和他的衣服上，以及他儿子和他们的衣服上，使亚伦和他的衣服，他儿子和他们的衣服都成为圣。","notes":[]},{"n":31,"t":"摩西对亚伦和他儿子说：“你们要在会幕的门口把肉煮了，在那里吃这肉和圣职礼中篮子里的饼，按我所吩咐的说：‘这是亚伦和他儿子当吃的。’","notes":[]},{"n":32,"t":"剩下的肉和饼，你们要用火焚烧。","notes":[]},{"n":33,"t":"这七天，你们不可走出会幕的门口，直等到你们圣职礼的日子满了，因为授予你们圣职需要七天。","notes":["“授予...七天”或译“主叫你们七天承接圣职”。"]},{"n":34,"t":"今天所做的，都是耶和华吩咐要做的，好为你们赎罪。","notes":[]},{"n":35,"t":"这七天，你们要昼夜留在会幕门内，遵守耶和华所吩咐的，免得你们死亡，因为所吩咐我的就是这样。”","notes":[]},{"n":36,"t":"于是，亚伦和他的儿子就做了耶和华藉着摩西所吩咐的一切事。","notes":[]}]},"9":{"heading":"亚伦献祭","verses":[{"n":1,"t":"到了第八天，摩西召亚伦和他儿子，以及以色列的众长老来，","notes":[]},{"n":2,"t":"对亚伦说：“你当取一头公牛犊作赎罪祭，一只公绵羊作燔祭，都要没有残疾的，献在耶和华面前。","notes":[]},{"n":3,"t":"你要对以色列人说：‘你们当取一只公山羊作赎罪祭，再取一头牛犊和一只小绵羊，都要一岁没有残疾的，作燔祭；","notes":[]},{"n":4,"t":"又当取一头公牛，一只公绵羊作平安祭，宰杀献在耶和华面前，再加上调油的素祭。因为今天耶和华要向你们显现。’”","notes":[]},{"n":5,"t":"于是，他们把摩西所吩咐的带到会幕前；全会众都近前来，站在耶和华面前。","notes":[]},{"n":6,"t":"摩西说：“这是耶和华吩咐你们当做的事，耶和华的荣光要向你们显现。”","notes":[]},{"n":7,"t":"摩西对亚伦说：“你靠近祭坛前，献你的赎罪祭和燔祭，为自己与百姓赎罪，再献上百姓的供物，为他们赎罪，都是照耶和华所吩咐的。”","notes":[]},{"n":8,"t":"于是，亚伦靠近坛前，宰了那头为自己赎罪的牛犊。","notes":[]},{"n":9,"t":"亚伦的儿子把血递给他，他就把指头蘸在血中，抹在坛的四个翘角上，再把其余的血倒在坛的底座上。","notes":[]},{"n":10,"t":"他把赎罪祭的脂肪和肾，以及肝上的网油，烧在坛上，是照耶和华所吩咐摩西的。","notes":[]},{"n":11,"t":"他用火将肉和皮烧在营外。","notes":[]},{"n":12,"t":"亚伦把燔祭牲宰了，他儿子把血递给他，他就把血洒在坛的周围。","notes":[]},{"n":13,"t":"他们又把燔祭一块一块地，连头递给他，他就烧在坛上。","notes":[]},{"n":14,"t":"他又洗了内脏和腿，放在坛的燔祭上烧。","notes":[]},{"n":15,"t":"然后，他奉上百姓的供物。他牵来给百姓作赎罪祭的公山羊，把它宰了，献为赎罪祭，和先前的一样。","notes":[]},{"n":16,"t":"他也奉上燔祭，按照条例献上。","notes":[]},{"n":17,"t":"除了早晨的燔祭以外，他又献上素祭，用手取了满满的一把，烧在坛上。","notes":[]},{"n":18,"t":"亚伦宰了那给百姓作平安祭的公牛和公绵羊，他儿子把血递给他，他就把血洒在坛的周围；","notes":[]},{"n":19,"t":"他们把公牛和公绵羊的脂肪、肥尾巴，包着内脏的脂肪，肾和肝上的网油，都递给他。","notes":[]},{"n":20,"t":"他们把脂肪放在祭牲的胸上，他就把脂肪烧在坛上。","notes":[]},{"n":21,"t":"亚伦把祭牲的胸和右腿在耶和华面前摇一摇，作为摇祭，是照摩西所吩咐的。","notes":[]},{"n":22,"t":"亚伦向百姓举手，为他们祝福。他献了赎罪祭、燔祭、平安祭就下来了。","notes":[]},{"n":23,"t":"摩西和亚伦进了会幕。他们出来，为百姓祝福；耶和华的荣光向全体百姓显现。","notes":[]},{"n":24,"t":"有火从耶和华面前出来，焚烧了坛上的燔祭和脂肪；全体百姓一看见，就都欢呼，脸伏于地。","notes":[]}]},"10":{"heading":"拿答和亚比户","verses":[{"n":1,"t":"亚伦的儿子拿答和亚比户各拿着自己的香炉，把火放在炉里，加上香，在耶和华面前献上凡火，是耶和华没有吩咐他们的。","notes":[]},{"n":2,"t":"有火从耶和华面前出来，把他们吞灭，他们就死在耶和华面前。","notes":[]},{"n":3,"t":"于是，摩西对亚伦说：“这就是耶和华所吩咐的，说：‘我在那亲近我的人中要显为圣；在全体百姓面前，我要得着荣耀。’”亚伦就默默不言。","notes":[]},{"n":4,"t":"摩西召亚伦的叔父乌薛的儿子米沙利和以利撒反前来，对他们说：“过来，把你们的亲属从圣所前抬到营外。”","notes":[]},{"n":5,"t":"于是，二人过来把尸体连袍子一起抬到营外，是照摩西所吩咐的。","notes":[]},{"n":6,"t":"摩西对亚伦和他儿子以利亚撒和以他玛说：“不可蓬头散发，也不可撕裂衣服，免得你们死亡，免得耶和华向全会众发怒。但你们的弟兄以色列全家却要为耶和华发出的火哀哭。","notes":[]},{"n":7,"t":"你们也不可出会幕的门口，免得你们死亡，因为耶和华的膏油在你们身上。”他们就遵照摩西的话去做了。","notes":[]},{"n":8,"t":"耶和华吩咐亚伦说：","notes":[]},{"n":9,"t":"“你和你儿子进会幕的时候，清酒烈酒都不可喝，免得你们死亡，这要作你们世世代代永远的定例。","notes":[]},{"n":10,"t":"你们必须分辨圣的俗的，洁净的和不洁净的，","notes":[]},{"n":11,"t":"也要将耶和华藉摩西吩咐以色列人的一切律例教导他们。”","notes":[]},{"n":12,"t":"摩西对亚伦和他剩下的儿子以利亚撒和以他玛说：“献给耶和华的火祭中所剩下的素祭，你们要拿来，在祭坛旁吃这无酵饼，因为它是至圣的。","notes":[]},{"n":13,"t":"你们要在圣处吃，因为在献给耶和华的火祭中，这是你和你儿子当得的份；所吩咐我的就是这样。","notes":[]},{"n":14,"t":"这摇祭的胸和这举祭的腿，你要在洁净的地方和你的儿女一同吃，因为这些是从以色列人的平安祭中归给你，作为你和你儿子当得的份。","notes":[]},{"n":15,"t":"他们要把举祭的腿、摇祭的胸和火祭的脂肪一同带来，在耶和华面前摇一摇，作为摇祭。这些要归给你和你儿子，作永远当得的份，都是照耶和华所吩咐的。”","notes":[]},{"n":16,"t":"那时，摩西急切地寻找那只赎罪祭的公山羊，看哪，它已经烧掉了。他向亚伦剩下的儿子以利亚撒和以他玛发怒，说：","notes":[]},{"n":17,"t":"“你们为何没有在圣所吃这赎罪祭呢？它是至圣的，是耶和华给你们的，为了除掉会众的罪孽，在耶和华面前为他们赎罪。","notes":[]},{"n":18,"t":"看哪，这祭牲的血没有拿到圣所里去！你们应当照我所吩咐的，在圣所里吃这祭肉。”","notes":[]},{"n":19,"t":"亚伦对摩西说：“看哪，他们今天在耶和华面前献上赎罪祭和燔祭，但是我却遭遇这样的灾难。我若今天吃这赎罪祭，耶和华岂能看为美呢？”","notes":[]},{"n":20,"t":"摩西听了，就看为美。","notes":[]}]},"11":{"heading":"洁净与不洁净的食物","verses":[{"n":1,"t":"耶和华吩咐摩西和亚伦，对他们说：","notes":[]},{"n":2,"t":"“你们要吩咐以色列人说，地上一切的走兽中可吃的动物是这些：","notes":[]},{"n":3,"t":"凡蹄分两瓣，分趾蹄而又反刍食物的走兽，你们都可以吃。","notes":[]},{"n":4,"t":"但那反刍或分蹄之中不可吃的是：骆驼，反刍却不分蹄，对你们是不洁净的；","notes":[]},{"n":5,"t":"石獾，反刍却不分蹄，对你们是不洁净的；","notes":[]},{"n":6,"t":"兔子，反刍却不分蹄，对你们是不洁净的；","notes":[]},{"n":7,"t":"猪，蹄分两瓣，分趾蹄却不反刍，对你们是不洁净的。","notes":[]},{"n":8,"t":"这些兽的肉，你们不可吃；它们的尸体，你们也不可摸，对你们都是不洁净的。","notes":[]},{"n":9,"t":"“水中可吃的是这些：凡在水里，无论是海或河，有鳍有鳞的，都可以吃。","notes":[]},{"n":10,"t":"凡在海里、河里和水里滋生的动物，就是在水里所有的动物，无鳍无鳞的，对你们是可憎的。","notes":[]},{"n":11,"t":"它们对你们都是可憎的。你们不可吃它们的肉；它们的尸体，也当以为可憎。","notes":[]},{"n":12,"t":"凡在水里无鳍无鳞的，对你们是可憎的。","notes":[]},{"n":13,"t":"“飞鸟中你们当以为可憎，不可吃且可憎的是：雕、狗头雕、红头雕，","notes":[]},{"n":14,"t":"鹞鹰、小鹰的类群，","notes":[]},{"n":15,"t":"所有乌鸦的类群，","notes":[]},{"n":16,"t":"鸵鸟、夜鹰、鱼鹰、鹰的类群，","notes":[]},{"n":17,"t":"鸮鸟、鸬鹚、猫头鹰，","notes":[]},{"n":18,"t":"角鸱、鹈鹕、秃雕，","notes":[]},{"n":19,"t":"鹳、鹭鸶的类群，戴鵀与蝙蝠。","notes":[]},{"n":20,"t":"“凡有翅膀却用四足爬行的群聚动物，对你们是可憎的。","notes":[]},{"n":21,"t":"只是有翅膀却用四足爬行的群聚动物中，足上有腿在地上跳的，你们还可以吃；","notes":[]},{"n":22,"t":"其中你们可以吃的有蝗虫的类群，蚂蚱的类群，蟋蟀的类群和蚱蜢的类群。","notes":[]},{"n":23,"t":"其余有翅膀有四足的群聚动物，对你们都是可憎的。","notes":[]},{"n":24,"t":"“这些都能使你们不洁净。凡摸它们尸体的，必不洁净到晚上。","notes":[]},{"n":25,"t":"任何人搬动了它们的尸体，要把衣服洗净，必不洁净到晚上。","notes":[]},{"n":26,"t":"凡蹄分两瓣却不分趾或不反刍食物的走兽，对你们是不洁净的；谁摸了它们就不洁净。","notes":[]},{"n":27,"t":"凡用脚掌行走，四足行走的动物，对你们是不洁净的；凡摸它们尸体的，必不洁净到晚上。","notes":[]},{"n":28,"t":"谁搬动了它们的尸体，要把衣服洗净，必不洁净到晚上。这些对你们是不洁净的。","notes":[]},{"n":29,"t":"“在地上成群的群聚动物中，对你们不洁净的是这些：鼬鼠、鼫鼠、蜥蜴的类群，","notes":[]},{"n":30,"t":"壁虎、龙子、守宫、蛇医、蝘蜓。","notes":[]},{"n":31,"t":"这些群聚动物对你们都是不洁净的。在它们死后，凡摸了它们尸体的，必不洁净到晚上。","notes":[]},{"n":32,"t":"其中死了的，若掉在任何东西上，这东西就不洁净，无论是木器、衣服、皮革、麻袋，或是任何工作需用的器皿，都要泡在水中，必不洁净到晚上，然后才是洁净的。","notes":[]},{"n":33,"t":"若有一点掉在瓦器里，里面的任何东西就不洁净了； 你们要把这瓦器打破。","notes":[]},{"n":34,"t":"其中一切可吃的食物，沾到那水的就不洁净；器皿里可喝的东西，也必不洁净。","notes":[]},{"n":35,"t":"它们的尸体，只要有一点掉在任何物件上，那物件就不洁净。无论是烤炉或炉灶，都要打碎；它们不洁净，而且对你们也不洁净。","notes":[]},{"n":36,"t":"但是水泉或池子，就是聚水的地方，仍是洁净的；凡摸这些尸体的才不洁净。","notes":[]},{"n":37,"t":"若它们的尸体有一点掉在要播的种子上，种子仍是洁净的；","notes":[]},{"n":38,"t":"若水已经浇在种子上，它们的尸体有一点掉在上面，这种子对你们就是不洁净的了。","notes":[]},{"n":39,"t":"“你们可吃的走兽中若有死了的，谁摸了它的尸体，就必不洁净到晚上。","notes":[]},{"n":40,"t":"人若吃了那已死的走兽，要把衣服洗净，必不洁净到晚上。人若搬动了那已死的走兽，要把衣服洗净，必不洁净到晚上。","notes":[]},{"n":41,"t":"“凡在地上成群的群聚动物都是可憎的，都不可吃。","notes":[]},{"n":42,"t":"凡用肚子爬行或用四脚爬行，或是用多足的，地上一切群聚的动物，你们都不可吃，因为是可憎的。","notes":[]},{"n":43,"t":"你们不可因任何群聚的动物使自己成为可憎的，也不可因它们成为不洁净，染了污秽。","notes":[]},{"n":44,"t":"我是耶和华－你们的神。你们要使自己分别为圣，要成为圣，因为我是神圣的。你们不可因地上爬行的群聚动物使自己不洁净。","notes":[]},{"n":45,"t":"我是把你们从埃及地领出来的耶和华，要作你们的神。你们要成为圣，因为我是神圣的。”","notes":[]},{"n":46,"t":"这是走兽、飞鸟、水中一切游动的生物和地上一切爬行的动物的条例，","notes":[]},{"n":47,"t":"为要使你们能分辨洁净的和不洁净的，可吃的和不可吃的动物。","notes":[]}]},"12":{"heading":"产妇洁净的条例","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人说：妇人若怀孕生男孩，就不洁净七天，像在月经污秽的期间不洁净一样。","notes":[]},{"n":3,"t":"第八天，要给婴孩行割礼。","notes":[]},{"n":4,"t":"妇人产后流血的洁净，要家居三十三天。她洁净的日子未满，不可摸圣物，也不可进入圣所。","notes":[]},{"n":5,"t":"她若生女孩，就不洁净两个七天，像经期中一样。她产后流血的洁净，要家居六十六天。","notes":[]},{"n":6,"t":"“洁净的日子满了，无论生儿子或女儿，她要把一只一岁的羔羊作燔祭，一只雏鸽或一只斑鸠作赎罪祭，带到会幕的门口交给祭司。","notes":[]},{"n":7,"t":"祭司要把这祭物献在耶和华面前，为她赎罪。这样，她就从流血中得洁净了。这是为生男或生女之妇人的条例。","notes":[]},{"n":8,"t":"妇人的能力若不足，无法献一只羔羊，她就要取两只斑鸠或两只雏鸽，一只为燔祭，一只为赎罪祭。祭司要为她赎罪，她就洁净了。”","notes":[]}]},"13":{"heading":"有关皮肤病的条例","verses":[{"n":1,"t":"耶和华吩咐摩西和亚伦说：","notes":[]},{"n":2,"t":"“人身上的皮肤若肿胀，或发疹，或有斑点，可能成为麻风 的灾病，就要把他带到亚伦祭司或亚伦的一个作祭司的子孙那里。","notes":["“麻风”泛指传染性皮肤病；下同。"]},{"n":3,"t":"祭司要检查他身上皮肤的患处，若患处的毛已经变白，灾病的现象深入身上皮肤内，这就是麻风的灾病。祭司检查后，要宣布他为不洁净。","notes":[]},{"n":4,"t":"若这人身上的皮肤有白斑，看起来并没有深入皮肤内，其上的毛也没有变白，祭司就要将这病人隔离七天。","notes":[]},{"n":5,"t":"第七天，祭司要检查他，看哪，若灾病在祭司眼前止住了，没有在皮肤上扩散，要将他再隔离七天。","notes":[]},{"n":6,"t":"到了第七天，祭司要再检查他。看哪，若灾病减轻，没有在皮肤上扩散，祭司就要宣布他为洁净，因为他患的不过是疹子。那人要洗自己的衣服，就洁净了。","notes":[]},{"n":7,"t":"他给祭司检查宣布为洁净后，疹子若在皮肤上大大扩散，他就要再给祭司检查。","notes":[]},{"n":8,"t":"祭司要检查，看哪，疹子若在皮肤上扩散了，祭司就要宣布他为不洁净，是麻风病。","notes":[]},{"n":9,"t":"“人若得了麻风的灾病，就要把他带到祭司那里。","notes":[]},{"n":10,"t":"祭司要检查，看哪，若皮肤有白色肿块，使毛变白，肿块里有嫩的新长的肉，","notes":[]},{"n":11,"t":"这就是他身上皮肤慢性的麻风病。祭司要宣布他为不洁净，不必将他隔离，因为他已是不洁净了。","notes":[]},{"n":12,"t":"若麻风在皮肤四处扩散，长满在患灾病之人的皮肤上，据祭司察看，从头到脚无处不有，","notes":[]},{"n":13,"t":"祭司就要检查，看哪，若这病人全身已长满了麻风，就要宣布他为洁净；他全身都变白了，他是洁净的。","notes":[]},{"n":14,"t":"但他身上一旦出现新长的肉，就不洁净了。","notes":[]},{"n":15,"t":"祭司一见新长的肉，就要宣布他为不洁净。新长的肉是不洁净的，这就是麻风病。","notes":[]},{"n":16,"t":"新长的肉若变白了，他就要到祭司那里。","notes":[]},{"n":17,"t":"祭司要检查，看哪，患处若变白了，祭司就要宣布那患灾病的人为洁净，他就洁净了。","notes":[]},{"n":18,"t":"“人身上的皮肤若长了疮，却已经好了，","notes":["“人身上的皮肤”：撒玛利亚五经是“人身上”。"]},{"n":19,"t":"在长疮之处又发肿变白，或是出现白中带红的斑点，就要给祭司检查。","notes":[]},{"n":20,"t":"祭司要检查，看哪，若灾病的现象已深入皮肤内，其上的毛也变白了，祭司就要宣布他为不洁净，有麻风的灾病生在疮中。","notes":[]},{"n":21,"t":"祭司若检查，看哪，其上没有白毛，也没有深入皮肤内，而且灾病减轻，祭司就要将他隔离七天。","notes":[]},{"n":22,"t":"若在皮肤上大大扩散，祭司就要宣布他为不洁净，这是灾病。","notes":[]},{"n":23,"t":"斑点若留在原处，没有扩散，这就是疮的疤痕，祭司就要宣布他为洁净。","notes":[]},{"n":24,"t":"“人身上的皮肤若被火烧伤，伤口新长的肉有了斑点，无论是白中带红，或是全白，","notes":[]},{"n":25,"t":"祭司就要检查，看哪，斑点上的毛若变白了，现象又深入皮肤内，这就是麻风长在烧伤处；祭司就要宣布他为不洁净，是麻风的灾病。","notes":[]},{"n":26,"t":"若祭司检查，看哪，斑点上没有白毛，也没有深入皮肤内，而且灾病减轻，祭司就要将他隔离七天。","notes":[]},{"n":27,"t":"第七天，祭司要检查他。斑点若在皮肤上大大扩散，祭司就要宣布他为不洁净，是患了麻风的灾病。","notes":[]},{"n":28,"t":"斑点若留在原处，没有在皮肤上扩散，并减轻了，它只是烧伤的肿块，祭司要宣布他为洁净，这不过是烧伤后的疤痕。","notes":[]},{"n":29,"t":"“无论男女，若在头上或下巴有灾病，","notes":[]},{"n":30,"t":"祭司就要检查这灾病，看哪，若灾病的现象深入皮肤内，其上有黄色的细毛，祭司就要宣布他为不洁净，这是疥疮，是头上或下巴的麻风病。","notes":[]},{"n":31,"t":"祭司要检查这疥疮的灾病，看哪，现象若未深入皮肤内，其上也没有黑毛，祭司就要将长疥疮的人隔离七天。","notes":[]},{"n":32,"t":"第七天，祭司要检查这灾病，看哪，若疥疮没有扩散，其上没有黄色的毛，疥疮的现象也没有深入皮肤内，","notes":[]},{"n":33,"t":"那人就要剃去须发，但不可剃长疥疮之处。祭司要将那长疥疮的人，再隔离七天。","notes":[]},{"n":34,"t":"第七天，祭司要检查疥疮，看哪，疥疮若没有在皮肤上扩散，现象也未深入在皮肤内，祭司就要宣布他为洁净；那人要洗自己的衣服，就洁净了。","notes":[]},{"n":35,"t":"但他被宣布为洁净后，疥疮若在皮肤上大大扩散，","notes":[]},{"n":36,"t":"祭司就要检查他。看哪，疥疮若在皮肤上扩散，祭司就不必找黄色的毛，这人是不洁净了。","notes":[]},{"n":37,"t":"若疥疮在祭司眼前止住了，其上长了黑毛，疥疮就已痊愈了，那人是洁净的，祭司要宣布他为洁净。","notes":[]},{"n":38,"t":"“无论男女，身上的皮肤若有斑点，是白色的斑点，","notes":[]},{"n":39,"t":"祭司就要检查，看哪，若皮肤的斑点是暗白色的，这是皮肤长了斑；那人是洁净的。","notes":[]},{"n":40,"t":"“人的头发若掉了，变成秃头，他是洁净的。","notes":[]},{"n":41,"t":"他头顶的前面若掉了头发，以致顶门光秃，他是洁净的。","notes":[]},{"n":42,"t":"头秃处或顶门秃处，若有白中带红的灾病，这就是麻风长在他的头秃处或顶门秃处。","notes":[]},{"n":43,"t":"祭司要检查他，看哪，若头秃处或顶门秃处的灾病肿块白中带红，像身上皮肤麻风病的现象一样，","notes":[]},{"n":44,"t":"那人就是患了麻风病，是不洁净的。祭司要宣布他为不洁净；他的灾病是生在头上。","notes":[]},{"n":45,"t":"“患有麻风灾病的人，他的衣服要撕裂，也要蓬头散发，遮住上唇，喊着说：‘不洁净！不洁净！’","notes":[]},{"n":46,"t":"灾病还在他身上的时候，他就是不洁净的；既然不洁净，他就要独居，住在营外。”","notes":[]},{"n":47,"t":"“衣服若发霉了，无论是羊毛衣服、麻布衣服，","notes":["“霉”：原文与“麻风的灾病”相同；下同。"],"heads":["衣服发霉的条例"]},{"n":48,"t":"无论是经线、纬线，是麻布的、羊毛的，是皮革，或是任何皮制的物件；","notes":[]},{"n":49,"t":"若是衣服、皮革、经线、纬线，或是任何皮制的物件呈现绿色或红色，这就是发霉，必须给祭司检查。","notes":[]},{"n":50,"t":"祭司要检查这霉，把发霉的物件隔离七天。","notes":[]},{"n":51,"t":"第七天，他要检查这霉。若霉在衣服上，无论是经线、纬线，或任何用途的皮制物件上扩散，这是侵蚀性的霉，是不洁净的。","notes":[]},{"n":52,"t":"发霉的衣服，无论在经线、纬线，羊毛的、麻布的，或是任何皮制物件，都要把它烧掉；因为这是侵蚀性的霉，必须用火焚烧。","notes":[]},{"n":53,"t":"祭司检查，看哪，霉若在衣服上，无论是经线、纬线，或在任何的皮制物件上没有扩散，","notes":[]},{"n":54,"t":"祭司就要吩咐人把发霉的物件洗了，再隔离七天。","notes":[]},{"n":55,"t":"洗过之后，祭司要检查，看哪，若那霉在他眼前没有变色，霉虽没有扩散，也是不洁净的。这是侵蚀性的灾病，无论是在正面或反面，都要用火焚烧那物件。","notes":[]},{"n":56,"t":"祭司若检查，看哪，那霉在洗过之后已经褪色，他就要从衣服，皮革，或经线、纬线，把发霉的部分撕去。","notes":[]},{"n":57,"t":"若霉再出现在衣服上，无论是经线、纬线、或在任何皮制物件上，这就是旧霉复发，必须用火将那发霉的物件焚烧。","notes":[]},{"n":58,"t":"洗过的衣服，或是经线，纬线，或是任何皮制的物件，若霉已经消失了，仍要再洗，这衣服就洁净了。”","notes":[]},{"n":59,"t":"这就是衣服发霉的条例。无论是羊毛衣服，麻布衣服，或是经线、纬线，或任何皮制的物件，都按照这条例宣布为洁净或不洁净。","notes":[]}]},"14":{"heading":"痊愈后的洁净条例","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“这是患麻风病的人得洁净时的条例：要带他到祭司那里，","notes":[]},{"n":3,"t":"祭司要出到营外，检查那患麻风病的人，看哪，他的麻风灾病已经痊愈了，","notes":[]},{"n":4,"t":"祭司就要吩咐人为那求洁净的人带两只洁净的活鸟和香柏木、朱红色纱，以及牛膝草来。","notes":[]},{"n":5,"t":"祭司要吩咐用瓦器盛清水，把第一只鸟宰在上面。","notes":[]},{"n":6,"t":"至于那只活鸟，祭司要把它和香柏木、朱红色纱，以及牛膝草，一同蘸在宰于清水上的鸟血中。","notes":[]},{"n":7,"t":"他要向那从麻风病中得洁净的人身上弹血七次，宣布他为洁净，然后把那活鸟在野地里放走。","notes":[]},{"n":8,"t":"求洁净的人要洗衣服，剃去所有的毛发，用水洗澡，他就洁净了。然后，他可以进营，不过仍要在自己的帐棚外居住七天。","notes":[]},{"n":9,"t":"到了第七天，他要剃所有的毛发，头发、胡须、眼睛的眉毛，他全身的毛都剃了；然后，他要洗衣服，用水洗身，才洁净了。","notes":[]},{"n":10,"t":"“第八天，他要取两只没有残疾的小公羊和一只没有残疾、一岁的小母羊，以及作为素祭的十分之三伊法调了油的细面和一罗革的油。","notes":[]},{"n":11,"t":"宣布洁净的祭司要将那求洁净的人，连同这些东西，安置在耶和华面前，会幕的门口。","notes":[]},{"n":12,"t":"祭司要取一只小公羊献为赎愆祭，又取一罗革的油，把它们在耶和华面前摇一摇，作为摇祭；","notes":[]},{"n":13,"t":"再把小公羊宰于圣处，就是宰赎罪祭牲和燔祭牲的地方。赎愆祭要归给祭司，与赎罪祭一样，是至圣的。","notes":[]},{"n":14,"t":"祭司要取一些赎愆祭牲的血，抹在求洁净的人的右耳垂上、右手的大拇指上和右脚的大脚趾上。","notes":[]},{"n":15,"t":"祭司要从那一罗革的油中，取一些倒在自己的左手掌里，","notes":[]},{"n":16,"t":"祭司要用右手指蘸在他左手掌的油里，在耶和华面前用手指弹七次。","notes":[]},{"n":17,"t":"祭司要把手掌里剩下的油抹在那求洁净的人的右耳垂上、右手的大拇指上和右脚的大脚趾上，在赎愆祭牲之血抹过的上面。","notes":[]},{"n":18,"t":"祭司手掌里剩下的油要抹在那求洁净的人的头上，祭司就在耶和华面前为他赎罪。","notes":[]},{"n":19,"t":"祭司要献赎罪祭，为那从不洁净中得洁净的人赎罪，然后要宰燔祭牲，","notes":[]},{"n":20,"t":"祭司要把燔祭和素祭献在坛上，祭司要为他赎罪，他就洁净了。","notes":[]},{"n":21,"t":"“他若贫穷，手头财力不及，就要取一只小公羊作赎愆祭，作摇祭为他赎罪。他也要把作为素祭的十分之一伊法调了油的细面，和一罗革的油，一同取来。","notes":[]},{"n":22,"t":"他又要照手头财力所及，取两只斑鸠或两只雏鸽，一只作赎罪祭，一只作燔祭。","notes":[]},{"n":23,"t":"第八天，为了使自己洁净，他要把这些祭物带到耶和华面前，在会幕的门口交给祭司。","notes":[]},{"n":24,"t":"祭司要把赎愆祭的羔羊和那一罗革的油一同在耶和华面前摇一摇，作为摇祭。","notes":[]},{"n":25,"t":"祭司要宰赎愆祭的羔羊，取一些赎愆祭牲的血，抹在那求洁净的人的右耳垂上、右手的大拇指上和右脚的大脚趾上。","notes":[]},{"n":26,"t":"祭司要把一些油倒在自己的左手掌里，","notes":[]},{"n":27,"t":"祭司要用右手指，把他左手掌里的油在耶和华面前弹七次。","notes":[]},{"n":28,"t":"祭司要把手掌里的油抹一些在那求洁净的人的右耳垂上、右手的大拇指上和右脚的大脚趾上，在赎愆祭牲之血抹过之处的上面。","notes":[]},{"n":29,"t":"祭司手掌里剩下的油要抹在那求洁净的人的头上，在耶和华面前为他赎罪。","notes":[]},{"n":30,"t":"那人又要照他手头财力所及，献上斑鸠中的一只或雏鸽中的一只，","notes":[]},{"n":31,"t":"照他手头财力所及，一只为赎罪祭，一只为燔祭，与素祭一同献上。祭司就在耶和华面前为他赎罪。","notes":[]},{"n":32,"t":"这是为患麻风灾病，手头财力不及而求洁净的人所定的条例。”","notes":[]},{"n":33,"t":"耶和华吩咐摩西和亚伦说：","notes":[],"heads":["房屋发霉的条例"]},{"n":34,"t":"“你们到了我所赐给你们为业的迦南地，我若使你们所得为业之地的房屋发霉，","notes":["“霉”：原文与“麻风的灾病”相同；下同。"]},{"n":35,"t":"屋主就要去告诉祭司说：‘据我看，房屋似乎发霉了。’","notes":[]},{"n":36,"t":"祭司进去检查这霉之前，要吩咐把屋内的东西全部搬走，免得屋子里所有的东西成为不洁净。然后，祭司要进去检查房屋。","notes":[]},{"n":37,"t":"他要检查这霉，看哪，若屋子墙上的霉有发绿或发红凹入的斑纹，其现象深入墙内，","notes":[]},{"n":38,"t":"祭司就要出到屋子的门外，把屋子封锁七天。","notes":[]},{"n":39,"t":"第七天，祭司要再去检查，看哪，霉若在屋子的墙上扩散，","notes":[]},{"n":40,"t":"祭司要吩咐把发霉的石头挖出来，扔在城外不洁净之处。","notes":[]},{"n":41,"t":"他也要叫人刮屋内的四围，把刮出来的灰泥倒在城外不洁净之处。","notes":[]},{"n":42,"t":"他们要用别的石头取代挖出来的石头，用别的灰泥涂抹屋子。","notes":[]},{"n":43,"t":"“他挖出石头，刮了屋子，涂抹以后，霉若又在屋子里出现，","notes":[]},{"n":44,"t":"祭司就要进去检查，看哪，霉若在屋子里扩散，那就是有侵蚀性的霉在屋子里，是不洁净的。","notes":[]},{"n":45,"t":"他要拆毁屋子，把石头、木料和所有的灰泥都搬到城外不洁净之处。","notes":[]},{"n":46,"t":"屋子封锁的任何时候，进去的人必不洁净到晚上。","notes":[]},{"n":47,"t":"在屋子里躺卧的人必须把衣服洗净，在屋子里吃饭的人也必须把衣服洗净。","notes":[]},{"n":48,"t":"“屋子涂抹了之后，祭司若进去检查，看哪，霉没有在屋内扩散，就要宣布这房屋为洁净，因为霉已经消除了。","notes":[]},{"n":49,"t":"他要为洁净房屋取两只鸟和香柏木、朱红色纱，以及牛膝草，","notes":[]},{"n":50,"t":"用瓦器盛清水，把一只鸟宰在上面。","notes":[]},{"n":51,"t":"他要把香柏木、牛膝草、朱红色纱和那一只活鸟，都蘸在被宰的鸟血和清水中，用来弹屋子七次。","notes":[]},{"n":52,"t":"他要用鸟血、清水、活鸟、香柏木、牛膝草和朱红色纱洁净那房屋。","notes":[]},{"n":53,"t":"他要把活鸟在城外野地里放走。他要为房屋赎罪，房屋就洁净了。”","notes":[]},{"n":54,"t":"这条例是为麻风灾病和疥疮，","notes":[]},{"n":55,"t":"衣服和房屋发霉，","notes":[]},{"n":56,"t":"以及皮肤肿胀、发疹、有斑点等，","notes":[]},{"n":57,"t":"用以分辨何时洁净，何时不洁净。这是麻风病的条例。","notes":[]}]},"15":{"heading":"患漏症的条例","verses":[{"n":1,"t":"耶和华吩咐摩西和亚伦说：","notes":[]},{"n":2,"t":"“你们要吩咐以色列人，对他们说：人若身体患了漏症，他因这症就不洁净了。","notes":["“身体”指“下体”；下同。"]},{"n":3,"t":"这就是他因漏症而有的不洁净：无论是身体流出液体，或身体已经止住不再有液体，他都是不洁净的。","notes":[]},{"n":4,"t":"那患漏症的人所躺的床都不洁净，所坐的任何东西也不洁净。","notes":[]},{"n":5,"t":"凡摸他床的人，要洗衣服，用水洗澡，必不洁净到晚上。","notes":[]},{"n":6,"t":"人坐了漏症患者坐过的东西，他要洗衣服，用水洗澡，必不洁净到晚上。","notes":[]},{"n":7,"t":"人摸了漏症患者，他要洗衣服，用水洗澡，必不洁净到晚上。","notes":[]},{"n":8,"t":"若漏症患者吐唾沫在洁净的人身上，这人要洗衣服，用水洗澡，必不洁净到晚上。","notes":[]},{"n":9,"t":"漏症患者所骑的任何鞍子也不洁净。","notes":[]},{"n":10,"t":"凡摸了他坐过的任何东西，必不洁净到晚上；拿了这些东西的，要洗衣服，用水洗澡，必不洁净到晚上。","notes":[]},{"n":11,"t":"漏症患者若没有用水冲洗他的手，无论摸了谁，谁就要洗衣服，用水洗澡，必不洁净到晚上。","notes":[]},{"n":12,"t":"漏症患者所摸的瓦器必要打破；他所摸的一切木器必要用水冲洗。","notes":[]},{"n":13,"t":"“漏症患者的漏症痊愈了，就要为洁净自己计算七天，也要洗衣服，用清水洗身，就洁净了。","notes":[]},{"n":14,"t":"第八天，他要带两只斑鸠或两只雏鸽，来到耶和华面前，在会幕门口把鸟交给祭司。","notes":[]},{"n":15,"t":"祭司要献上一只为赎罪祭，一只为燔祭。祭司要因这人所患的漏症，在耶和华面前为他赎罪。","notes":[]},{"n":16,"t":"“人若遗精，他要用水洗全身，必不洁净到晚上。","notes":[]},{"n":17,"t":"无论是衣服或皮革，若沾染了精液，要用水洗净，必不洁净到晚上。","notes":[]},{"n":18,"t":"女人，若有男人与她同寝，沾染了精液，二人要用水洗澡，必不洁净到晚上。”","notes":[]},{"n":19,"t":"“女人月经期间，有血从体内流出，她必不洁净七天；凡摸她的，必不洁净到晚上。","notes":[],"heads":["月经的条例"]},{"n":20,"t":"在不洁净期间，女人所躺的东西都不洁净，所坐的任何东西也不洁净。","notes":[]},{"n":21,"t":"凡摸她床的，要洗衣服，用水洗澡，必不洁净到晚上；","notes":[]},{"n":22,"t":"凡摸她坐过的东西的，要洗衣服，用水洗澡，必不洁净到晚上；","notes":[]},{"n":23,"t":"不论是床，或她坐过的东西，人摸了，必不洁净到晚上。","notes":[]},{"n":24,"t":"男人若和这女人同寝，沾了她的不洁净，就不洁净七天，所躺的床也都不洁净。","notes":[]},{"n":25,"t":"“女人若在经期之外仍然流血多日，或是经期过长，她在流血的一切日子都不洁净，和她在经期的日子不洁净一样。","notes":[]},{"n":26,"t":"在流血的日子，她所躺的床、所坐的任何东西都不洁净，和在月经期间不洁净一样。","notes":[]},{"n":27,"t":"凡摸这些东西的，就不洁净；他要洗衣服，用水洗澡，必不洁净到晚上。","notes":[]},{"n":28,"t":"这女人的血漏若痊愈了，就要计算七天，然后才洁净。","notes":[]},{"n":29,"t":"第八天，她要取两只斑鸠或两只雏鸽，带到会幕门口祭司那里。","notes":[]},{"n":30,"t":"祭司要献一只为赎罪祭，一只为燔祭。祭司要因这女人血漏的不洁净，在耶和华面前为她赎罪。","notes":[]},{"n":31,"t":"“你们要使以色列人与他们的不洁净隔离，免得他们玷污我在他们中间的帐幕，因自己的不洁净死亡。”","notes":[]},{"n":32,"t":"这条例是为漏症患者或遗精而不洁净者，","notes":[]},{"n":33,"t":"女人经期的不洁，男女患漏症，以及男人与不洁净女人同寝而立的。","notes":[]}]},"16":{"heading":"赎罪日","verses":[{"n":1,"t":"亚伦的两个儿子靠近耶和华面前，死了。他们死后，耶和华吩咐摩西；","notes":[]},{"n":2,"t":"耶和华对摩西说：“你要吩咐你哥哥亚伦，不可随时进入圣所的幔子内、到柜盖前，免得他死亡，因为我在柜盖上的云中显现。","notes":["“盖”：原意“盖住”，指“盖住罪”，后来也称为“施恩座”；下同。"]},{"n":3,"t":"亚伦进圣所要带这些：一头公牛犊为赎罪祭，一只公绵羊为燔祭。","notes":[]},{"n":4,"t":"他要穿上细麻布圣内袍，把细麻布裤子穿在身上，腰束细麻布带子，头戴细麻布礼冠；这些都是圣服。他要用水洗身，然后穿上圣服。","notes":[]},{"n":5,"t":"他要从以色列会众中取两只公山羊为赎罪祭，一只公绵羊为燔祭。","notes":[]},{"n":6,"t":"“亚伦要把他自己赎罪祭的公牛献上，为自己和家人赎罪；","notes":[]},{"n":7,"t":"也要把两只公山羊牵到耶和华面前，安置在会幕的门口。","notes":[]},{"n":8,"t":"亚伦要为那两只山羊抽签，一签归给耶和华，一签归给阿撒泻勒。","notes":[]},{"n":9,"t":"亚伦要把那抽中归给耶和华的山羊牵来献为赎罪祭，","notes":[]},{"n":10,"t":"至于抽中归给阿撒泻勒的山羊，却要活着安放在耶和华面前，用以赎罪，然后送到旷野去，归给阿撒泻勒。","notes":[]},{"n":11,"t":"“亚伦要把他自己赎罪祭的公牛献上，为自己和家人赎罪，他要宰作自己赎罪祭的公牛。","notes":[]},{"n":12,"t":"他要从耶和华面前的坛上取盛满火炭的香炉，再拿一捧捣细的香料，把这些都带入幔子内。","notes":[]},{"n":13,"t":"在耶和华面前，他要把香放在火上，使香的烟云遮着法柜上的盖子，免得他死亡。","notes":[]},{"n":14,"t":"他要取一些公牛的血，用手指弹在柜盖的前面，就是东面，又在柜盖的前面用手指弹血七次。","notes":[]},{"n":15,"t":"“他要宰那只为百姓作赎罪祭的公山羊，把羊的血带入幔子内，把血弹在柜盖的上面和前面，好像弹公牛的血一样。","notes":[]},{"n":16,"t":"因以色列人的不洁净和过犯，就是他们一切的罪，他要为圣所赎罪；因会幕在他们不洁净之中，他也要为会幕照样做。","notes":[]},{"n":17,"t":"他进圣所赎罪的时候，会幕里都不准有人，直等到他为自己和家人，以及以色列全会众赎了罪出来。","notes":[]},{"n":18,"t":"他出来后，要到耶和华面前的祭坛那里，为坛赎罪。他要取一些公牛的血和公山羊的血，抹在坛周围的四个翘角上。","notes":[]},{"n":19,"t":"他也要用手指把血弹在坛上七次，使坛从以色列人的不洁净中得以洁净，成为圣。”","notes":[]},{"n":20,"t":"“亚伦为圣所和会幕，以及祭坛赎罪后，就要把那只活的公山羊牵来。","notes":[],"heads":["代罪的山羊"]},{"n":21,"t":"他的双手要按在活的山羊的头上，承认以色列人所有的罪孽过犯，就是他们一切的罪，把这些罪都归在羊的头上，再指派一个人把它送到旷野去。","notes":[]},{"n":22,"t":"这羊要担当他们一切的罪孽，带到无人之地；那人要把羊送到旷野去。","notes":[]},{"n":23,"t":"“亚伦要进入会幕，把他进圣所时所穿的细麻布衣服脱下，放在那里，","notes":[]},{"n":24,"t":"又要在圣处用水洗身，穿上衣服出来，把自己的燔祭和百姓的燔祭献上，为自己和百姓赎罪。","notes":[]},{"n":25,"t":"赎罪祭牲的脂肪要烧在坛上。","notes":[]},{"n":26,"t":"那放走山羊归给阿撒泻勒的人要洗衣服，用水洗身，然后才可以回到营里。","notes":[]},{"n":27,"t":"作赎罪祭的公牛和作赎罪祭的公山羊的血被带入圣所赎罪之后，就要把这牛羊搬到营外，皮、肉、粪都用火焚烧。","notes":[]},{"n":28,"t":"焚烧的人要洗衣服，用水洗身，然后才可以回到营里。”","notes":[]},{"n":29,"t":"“这是你们永远的定例：每年七月初十，你们要刻苦己心；无论是本地人，是寄居在你们中间的外人，任何工都不可做。","notes":[],"heads":["赎罪日"]},{"n":30,"t":"因为这日要为你们赎罪，洁净你们，使你们脱离一切的罪，在耶和华面前得以洁净。","notes":[]},{"n":31,"t":"这日你们要守完全安息的安息日，刻苦己心；这是永远的定例。","notes":[]},{"n":32,"t":"那受膏接续他父亲担任圣职的祭司要赎罪，穿上细麻布衣服，就是圣衣，","notes":[]},{"n":33,"t":"为至圣所和会幕赎罪，为祭坛赎罪，并要为祭司和会众的全体百姓赎罪。","notes":[]},{"n":34,"t":"这要作你们永远的定例：因以色列人一切的罪，要一年一次为他们赎罪。”于是，亚伦照耶和华所吩咐摩西的做了 。","notes":["“于是...做了”或译“摩西做了，正如耶和华所吩咐他的”。"]}]},"17":{"heading":"宰祭牲的条例","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐亚伦和他儿子，以及以色列众人，对他们说，耶和华所吩咐的话是这样：","notes":[]},{"n":3,"t":"凡以色列家中的人宰公牛，或小绵羊，或山羊，无论是在营内或营外，","notes":[]},{"n":4,"t":"若不把牲畜牵到会幕门口耶和华的帐幕前，献给耶和华为供物，所流的血必归到那人身上。他既使血流出，就要从百姓中剪除。","notes":[]},{"n":5,"t":"这是为要使以色列人把他们在野地里所宰的祭牲带来，带到耶和华前，会幕门口祭司那里，宰杀这些祭牲，把它们献给耶和华为平安祭。","notes":[]},{"n":6,"t":"祭司要在会幕门口，把血洒在耶和华的祭坛上，把脂肪焚烧，献给耶和华为馨香的祭。","notes":[]},{"n":7,"t":"他们不可再宰杀祭牲献给他们行淫所随从的山羊鬼魔。这要作他们世世代代永远的定例。","notes":[]},{"n":8,"t":"“你要对他们说：凡以色列家中的任何人，或寄居在他们中间的外人献燔祭或祭物，","notes":[]},{"n":9,"t":"若不带到会幕门口献给耶和华，那人必从百姓中剪除。”","notes":[]},{"n":10,"t":"“凡以色列家中的任何人，或寄居在他们中间的外人，吃任何的血，我必向那吃血的人变脸，把他从百姓中剪除。","notes":[],"heads":["不可吃血"]},{"n":11,"t":"因为动物的生命是在血中。我把这血赐给你们，可以在祭坛上为你们的生命赎罪；因为血就是生命，能够赎罪。","notes":[]},{"n":12,"t":"因此，我对以色列人说：你们都不可吃血；寄居在你们中间的外人也不可吃血。","notes":[]},{"n":13,"t":"凡以色列人，或寄居在他们中间的外人，猎取了可吃的飞禽走兽，必须把它的血放出来，用土掩盖。","notes":[]},{"n":14,"t":"“因一切动物的生命，它的血就是它的生命。所以我对以色列人说：无论什么动物的血，你们都不可吃，因为一切动物的生命就是它的血。凡吃血的必被剪除。","notes":[]},{"n":15,"t":"无论是本地人，是寄居的，若吃了自然死去或被野兽撕裂的动物，要洗衣服，用水洗澡，必不洁净到晚上，晚上就洁净了。","notes":[]},{"n":16,"t":"但他若不洗衣服，也不洗身，就要担当自己的罪孽。”","notes":[]}]},"18":{"heading":"淫乱的禁令","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人，对他们说：我是耶和华－你们的神。","notes":[]},{"n":3,"t":"你们不可做你们从前住埃及地的人所做的，也不可做我要领你们去的迦南地的人所做的。你们不可照他们的习俗行。","notes":[]},{"n":4,"t":"你们要遵行我的典章，谨守我的律例，按此而行。我是耶和华－你们的神。","notes":[]},{"n":5,"t":"你们要谨守我的律例典章；遵行的人就必因此得生。我是耶和华。","notes":[]},{"n":6,"t":"“任何人都不可亲近骨肉之亲，露其下体。我是耶和华。","notes":[]},{"n":7,"t":"你父亲的下体，就是你母亲的下体，你不可露；她是你的母亲，不可露她的下体。","notes":[]},{"n":8,"t":"不可露你继母的下体，就是你父亲的下体。","notes":[]},{"n":9,"t":"你姊妹的下体，或是同父异母的，或是同母异父的，无论生在家或生在外的，都不可露她们的下体。","notes":[]},{"n":10,"t":"不可露你孙女或外孙女的下体，因为她们的下体就是你自己的下体。","notes":[]},{"n":11,"t":"你继母为你父亲所生的女儿是你的姊妹，不可露她的下体。","notes":[]},{"n":12,"t":"不可露你姑母的下体；她是你父亲的骨肉之亲。","notes":[]},{"n":13,"t":"不可露你姨母的下体；她是你母亲的骨肉之亲。","notes":[]},{"n":14,"t":"不可露你叔伯的下体，不可亲近他的妻子；她是你的叔母、伯母。","notes":[]},{"n":15,"t":"不可露你媳妇的下体，她是你儿子的妻，不可露她的下体。","notes":[]},{"n":16,"t":"不可露你兄弟妻子的下体，这是你兄弟的下体。","notes":[]},{"n":17,"t":"不可露妇人的下体，又露她女儿的下体，也不可娶她的孙女或外孙女，露她们的下体；她们是骨肉之亲。这是邪恶的事。","notes":["“骨肉之亲”：原文另译“她的骨肉之亲”；七十士译本是“你的骨肉之亲”。"]},{"n":18,"t":"你妻子还活着的时候，不可另娶她的姊妹与她作对，露她姊妹的下体。","notes":[]},{"n":19,"t":"“不可亲近经期中不洁净的女人，露她的下体。","notes":[]},{"n":20,"t":"不可跟邻舍的妻交合，因她玷污自己。","notes":[]},{"n":21,"t":"不可使你儿女经火献给摩洛，也不可亵渎你神的名。我是耶和华。","notes":[]},{"n":22,"t":"不可跟男人同寝，像跟女人同寝；这是可憎恶的事。","notes":[]},{"n":23,"t":"不可跟兽交合，因它玷污自己。女人也不可站在兽前，与它交合；这是逆性的事。","notes":[]},{"n":24,"t":"“在这一切的事上，你们都不可玷污自己，因为我在你们面前所逐出的列国，在这一切的事上玷污了自己。","notes":[]},{"n":25,"t":"连地也玷污了，我惩罚那地的罪孽，地就吐出它的居民来。","notes":[]},{"n":26,"t":"但你们要遵守我的律例典章。这一切可憎恶的事，无论是本地人或寄居在你们中间的外人，都不可以做。","notes":[]},{"n":27,"t":"在你们之前居住那地的人做了这一切可憎恶的事，地就玷污了。","notes":[]},{"n":28,"t":"不要让地因你们玷污了它而把你们吐出来，像吐出在你们之前的国一样。","notes":[]},{"n":29,"t":"无论是谁，若做了这其中一件可憎恶的事，必从百姓中剪除。","notes":[]},{"n":30,"t":"你们要遵守我的吩咐，免得你们随从那些可憎的习俗，就是在你们之前的人所做的，玷污了自己。我是耶和华－你们的神。”","notes":[]}]},"19":{"heading":"成圣和公正的条例","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列全会众，对他们说：你们要成为圣，因为我耶和华－你们的神是神圣的。","notes":[]},{"n":3,"t":"你们各人都当孝敬父母，也要守我的安息日。我是耶和华－你们的神。","notes":[]},{"n":4,"t":"你们不可转向虚无的神明，也不可为自己铸造神像。我是耶和华－你们的神。","notes":[]},{"n":5,"t":"“你们宰杀祭牲献平安祭给耶和华的时候，要献得使你们可蒙悦纳。","notes":[]},{"n":6,"t":"这祭物要在献的当天或第二天吃；若有剩到第三天的，就要用火焚烧。","notes":[]},{"n":7,"t":"第三天若再吃，这祭物是不洁净的，必不蒙悦纳。","notes":[]},{"n":8,"t":"吃的人必担当自己的罪孽，因为他亵渎了耶和华的圣物，这人必从百姓中剪除。","notes":[]},{"n":9,"t":"“你们在自己的地收割庄稼时，不可割尽田的角落，也不可拾取庄稼所掉落的。","notes":[]},{"n":10,"t":"不可摘尽葡萄园的葡萄，也不可拾取葡萄园中掉落的葡萄，要把它们留给穷人和寄居的。我是耶和华－你们的神。","notes":[]},{"n":11,"t":"“你们不可偷盗，不可欺骗，也不可彼此说谎。","notes":[]},{"n":12,"t":"不可指着我的名起假誓，亵渎你神的名。我是耶和华。","notes":[]},{"n":13,"t":"“不可欺压你的邻舍，也不可偷盗。雇工的工钱不可在你那里过夜，留到早晨。","notes":[]},{"n":14,"t":"不可咒骂聋子，也不可将绊脚石放在盲人面前。你要敬畏你的神。我是耶和华。","notes":[]},{"n":15,"t":"“你们审判的时候，不可不公正；不可偏护贫穷人，也不可看重有权势人的脸，总要公平审判你的邻舍。","notes":[]},{"n":16,"t":"不可在百姓中到处搬弄是非，不可陷害邻舍的性命。我是耶和华。","notes":["“陷害...性命”：原文直译“站在邻舍的血上”。"]},{"n":17,"t":"“不可心里恨你的弟兄；要指摘你的邻舍，免得因他承担罪过。","notes":[]},{"n":18,"t":"不可报仇，也不可埋怨你本国的子民。你要爱邻如己。我是耶和华。","notes":[]},{"n":19,"t":"“你们要遵守我的律例。不可使你的牲畜与异类交配；不可在你的田地播下两样的种子；也不可穿两种原料做成的衣服。","notes":[]},{"n":20,"t":"“若有人与女子同寝交合，而她是婢女，许配了丈夫，尚未被赎或得自由，就要受到惩罚，却不可把他们处死，因为婢女还没有得自由。","notes":[]},{"n":21,"t":"男的要把赎愆祭，就是一只公绵羊牵到耶和华面前，会幕的门口。","notes":[]},{"n":22,"t":"祭司要用赎愆祭的羊在耶和华面前为他所犯的罪赎罪，他所犯的罪就必蒙赦免。","notes":[]},{"n":23,"t":"“你们到了迦南地，栽种各样的果树，就要把所结的果子当作不洁净的；三年之内，你们要把它视为不洁净，是不可吃的。","notes":["“不洁净的”：原文是“未受割礼的”；下同。"]},{"n":24,"t":"但第四年所结的果子全是圣的，用以赞美耶和华。","notes":["“用以赞美耶和华”：撒玛利亚五经是“作一般用途的启用典礼的供物，献给耶和华”。"]},{"n":25,"t":"第五年，你们就可以吃树上的果子，使树给你们结出更多的果子。我是耶和华－你们的神。","notes":[]},{"n":26,"t":"“你们不可吃带血的食物。不可占卜，也不可观星象。","notes":[]},{"n":27,"t":"头的周围不可剃，胡须的周围不可损坏。","notes":["“头的周围”或译“两鬓”。"]},{"n":28,"t":"不可为死人割划自己的身体，也不可在身上刺花纹。我是耶和华。","notes":[]},{"n":29,"t":"“不可侮辱你的女儿，使她沦为娼妓，免得这地行淫乱，地就充满了邪恶。","notes":[]},{"n":30,"t":"你们要谨守我的安息日，敬畏我的圣所。我是耶和华。","notes":[]},{"n":31,"t":"“不可转向招魂的，也不可求问行巫术的，免得被他们玷污。我是耶和华－你们的神。","notes":[]},{"n":32,"t":"“在白发的人面前，你要站起来，要尊敬老人；要敬畏你的神，我是耶和华。","notes":[]},{"n":33,"t":"“若有外人寄居在你们的地上和你同住，不可欺负他。","notes":[]},{"n":34,"t":"寄居在你们那里的外人，你们要看他如本地人，并要爱他如己，因为你们在埃及地也作过寄居的。我是耶和华－你们的神。","notes":[]},{"n":35,"t":"“你们审判的时候，不可用不公正的度量衡。","notes":[]},{"n":36,"t":"你们要用公正的天平、公正的法码、公正的伊法和公正的欣。我是耶和华－你们的神，曾把你们从埃及地领出来。","notes":[]},{"n":37,"t":"你们要谨守我一切的律例典章，遵行它们。我是耶和华。”","notes":[]}]},"20":{"heading":"惩罚的条例","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要对以色列人说：凡以色列人，或是寄居在以色列的外人，把自己儿女献给摩洛的，必被处死；本地的百姓要用石头打死他。","notes":[]},{"n":3,"t":"我也要向那人变脸，把他从百姓中剪除，因为他把儿女献给摩洛，玷污了我的圣所，亵渎了我的圣名。","notes":[]},{"n":4,"t":"那人把儿女献给摩洛，本地的百姓若假装没看见，不把他处死，","notes":[]},{"n":5,"t":"我就要向这人和他的家人变脸，把他和所有跟随他与摩洛行淫的人都从百姓中剪除。","notes":[]},{"n":6,"t":"“人若转向招魂的和行巫术的，随从他们行淫，我就要向这人变脸，把他从百姓中剪除。","notes":[]},{"n":7,"t":"你们要使自己分别为圣，要成为圣，因为我是耶和华－你们的神。","notes":[]},{"n":8,"t":"你们要谨守我的律例，遵行它们；我是使你们分别为圣的耶和华。","notes":[]},{"n":9,"t":"凡咒骂父母的，必被处死；他咒骂了父母，他的血要归在他身上。","notes":[]},{"n":10,"t":"“凡与有夫之妇行奸淫，就是与邻舍的妻子行奸淫的，奸夫淫妇必被处死。","notes":[]},{"n":11,"t":"人若与继母同寝，就是露了父亲的下体，二人必被处死，血要归在他们身上。","notes":[]},{"n":12,"t":"人若与媳妇同寝，二人必被处死；他们行了乱伦的事，血要归在他们身上。","notes":[]},{"n":13,"t":"男人若跟男人同寝，像跟女人同寝，他们二人行了可憎恶的事，必被处死，血要归在他们身上。","notes":[]},{"n":14,"t":"人若娶妻，又娶妻子的母亲，这是邪恶的事；要把这三人用火焚烧，在你们中间除去这邪恶。","notes":[]},{"n":15,"t":"人若与兽交合，必被处死；你们也要杀死那兽。","notes":[]},{"n":16,"t":"女人若与兽亲近，与它交合，你要把那女人和兽杀死；他们必被处死，血要归在他们身上。","notes":[]},{"n":17,"t":"“人若娶自己的姊妹，或是同父异母的，或是同母异父的，彼此见了下体，这是可耻的事；他们必在自己百姓眼前被剪除。他露了姊妹的下体，必担当自己的罪孽。","notes":[]},{"n":18,"t":"若有人跟经期中的妇人同寝，露了她的下体，暴露妇人的血源，妇人也露了自己的血源，二人必从百姓中剪除。","notes":[]},{"n":19,"t":"不可露姨母或姑母的下体，因为这是露了骨肉之亲的下体，他们必担当自己的罪孽。","notes":[]},{"n":20,"t":"人若与叔伯之妻同寝，就露了他叔伯的下体，他们必担当自己的罪，必没有子女而死。","notes":[]},{"n":21,"t":"人若娶了自己兄弟的妻子，就露了他兄弟的下体，这是不洁净的事，他们必没有子女。","notes":[]},{"n":22,"t":"“你们要谨守我一切的律例典章，遵行它们，免得我领你们去住的那地把你们吐出来。","notes":[]},{"n":23,"t":"我在你们面前所逐出的国民，你们不可随从他们的风俗。因为他们行了这一切的事，所以我厌恶他们。","notes":[]},{"n":24,"t":"但我对你们说过，你们要承受他们的土地；我要把这流奶与蜜之地赐给你们，作为你们的产业。我是耶和华－你们的神，是把你们从万民中分别出来的。","notes":[]},{"n":25,"t":"你们要分辨洁净和不洁净的飞禽走兽；不可因我定为不洁净的飞禽走兽，或爬行在土地上的任何生物，使自己成为可憎恶的。","notes":[]},{"n":26,"t":"你们要归我为圣，因为－我耶和华是神圣的；我把你们从万民中分别出来，作我的子民。","notes":[]},{"n":27,"t":"“无论男女，是招魂的或行巫术的，他们必被处死。人要用石头打死他们，血要归在他们身上。”","notes":[]}]},"21":{"heading":"祭司成圣的条例","verses":[{"n":1,"t":"耶和华对摩西说：“你要告诉亚伦子孙作祭司的，对他们说：祭司不可为自己百姓中的死人玷污自己，","notes":[]},{"n":2,"t":"除非是他的骨肉之亲，他的父母、儿女、兄弟、","notes":[]},{"n":3,"t":"或未出嫁还是处女的姊妹，因她是至亲，才可以玷污自己。","notes":[]},{"n":4,"t":"祭司既然在自己百姓中为首，就不可从俗玷污自己。","notes":["“祭司...玷污自己”：原文另译“祭司虽然作为丈夫，也不可为姻亲从俗玷污自己”。"]},{"n":5,"t":"“不可使头光秃，不可剃除胡须的边缘，也不可割划自己的身体。","notes":[]},{"n":6,"t":"他们要归神为圣，不可亵渎他们神的名，因为耶和华的火祭，就是神的食物，是他们献的，所以他们要成为圣。","notes":[]},{"n":7,"t":"“祭司不可娶妓女，或被玷污的女人为妻，也不可娶被休的妇人为妻，因为他是归神为圣的。","notes":[]},{"n":8,"t":"你要使祭司分别为圣，因为他献你神的食物。你要以他为圣，因为我是使你们分别为圣的耶和华，是神圣的。","notes":["“使你们分别为圣”：撒玛利亚五经和七十士译本是“使他们分别为圣”。"]},{"n":9,"t":"“祭司的女儿若行淫玷污自己，就侮辱了父亲，要用火将她焚烧。","notes":[]},{"n":10,"t":"“在弟兄中作大祭司的，头上倒了膏油，承接圣职，穿了圣衣，不可蓬头散发，也不可撕裂衣服；","notes":[]},{"n":11,"t":"不可挨近任何死尸，即使为了父母也不可玷污自己。","notes":[]},{"n":12,"t":"他不可出圣所，免得亵渎了神的圣所，因为在他身上有神的膏油为圣冕。我是耶和华。","notes":[]},{"n":13,"t":"他要娶处女为妻。","notes":[]},{"n":14,"t":"大祭司不可娶寡妇，被休的妇人，或被玷污的妓女为妻；他只可以娶自己百姓中的处女为妻。","notes":[]},{"n":15,"t":"他不可在自己百姓中侮辱他的儿女，因为我是使他分别为圣的耶和华。”","notes":[]},{"n":16,"t":"耶和华吩咐摩西说：","notes":[]},{"n":17,"t":"“你吩咐亚伦说：你世世代代的后裔，凡有残疾的都不可近前来献神的食物。","notes":[]},{"n":18,"t":"因为凡有残疾的，无论是失明的、瘸腿的、五官不正的、肢体之一过长的、","notes":[]},{"n":19,"t":"断脚的、断手的、","notes":[]},{"n":20,"t":"驼背的、侏儒的、有眼疾的、长癣的、长疥的，或是睾丸压伤的，都不可近前来。","notes":[]},{"n":21,"t":"亚伦祭司的后裔，凡有残疾的都不可近前来献耶和华的火祭。他有残疾，不可近前来献神的食物。","notes":[]},{"n":22,"t":"神的食物，无论是圣的，或是至圣的，他都可以吃。","notes":[]},{"n":23,"t":"但他不可进到幔子前，也不可挨近祭坛前，因为他有残疾，免得他亵渎我的圣所。我是使他们分别为圣的耶和华。”","notes":[]},{"n":24,"t":"于是，摩西吩咐了亚伦和他的儿子，以及以色列众人。","notes":[]}]},"22":{"heading":"吃圣物的条例","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐亚伦和他子孙说：你们要谨慎处理以色列人所分别为圣，归给我的圣物，免得亵渎我的圣名。我是耶和华。","notes":["“谨慎处理”：原文是“远离”。"]},{"n":3,"t":"你要对他们说：你们世世代代的后裔，凡不洁净的，却挨近以色列人所分别为圣，归给耶和华的圣物，那人必从我面前剪除。我是耶和华。","notes":[]},{"n":4,"t":"亚伦的后裔中，凡有麻风病的，或患漏症的，都不可吃圣物，直等他洁净了。无论谁摸了那因尸体而不洁净的东西，或遗精的人，","notes":[]},{"n":5,"t":"或摸到任何使他不洁净的群聚动物或使他不洁净的人，无论那人有什么不洁净，","notes":[]},{"n":6,"t":"摸了这些的人必不洁净到晚上；若不用水洗身，就不可吃圣物。","notes":[]},{"n":7,"t":"日落的时候，他就洁净了，然后可以吃圣物，因为这是他的食物。","notes":[]},{"n":8,"t":"自然死去的或被野兽撕裂的，他不可吃，免得玷污自己。我是耶和华。","notes":[]},{"n":9,"t":"他们要遵守我的吩咐，免得因亵渎圣物，担当自己的罪而死。我是使他们分别为圣的耶和华。","notes":["“圣物”：原文是“它”。"]},{"n":10,"t":"“任何外人都不可吃圣物；寄居在祭司家的，或雇工，都不可吃圣物。","notes":[]},{"n":11,"t":"若是祭司用自己的银钱买来的人，就可以吃圣物；在他家出生的人也可以吃他的食物。","notes":[]},{"n":12,"t":"祭司的女儿若嫁给外人，就不可吃举祭的圣物。","notes":[]},{"n":13,"t":"但祭司的女儿若成为寡妇或被休，又没有后裔，她回到父家，好像年轻的时候，就可以吃她父亲的食物。只是任何外人都不可吃它。","notes":[]},{"n":14,"t":"若有人误吃了圣物，要把圣物加上五分之一交给祭司。","notes":[]},{"n":15,"t":"祭司不可亵渎以色列人献给耶和华的圣物，","notes":[]},{"n":16,"t":"免得他们因吃圣物而自取罪孽。我是使他们分别为圣的耶和华。”","notes":[]},{"n":17,"t":"耶和华吩咐摩西说：","notes":[],"heads":["蒙悦纳的祭物"]},{"n":18,"t":"“你要吩咐亚伦和他子孙，以及以色列众人，对他们说：以色列家中的人，或在以色列中寄居的 ，若要献供物给耶和华作燔祭，无论是为所许的愿或是甘心献的，","notes":["“寄居的”：有古卷和撒玛利亚五经是“寄居的外人”。"]},{"n":19,"t":"就要将一头公的，没有残疾的牛，或绵羊，或山羊献上，这样你们才蒙悦纳。","notes":[]},{"n":20,"t":"凡有残疾的，你们不可献上，因为这样你们必不蒙悦纳。","notes":[]},{"n":21,"t":"若有人从牛群或羊群中，将平安祭献给耶和华，无论是为还所许特别的愿，或是甘心献的，所献的必须是健康、无任何残疾的，才蒙悦纳。","notes":[]},{"n":22,"t":"凡瞎眼的、受伤的、断腿的、溃烂的、长癣的、长疥的，都不可献给耶和华，不可在坛上作为火祭献给耶和华。","notes":[]},{"n":23,"t":"无论是公牛或小绵羊，若一条腿太长或太短，只可作甘心祭献上；若用来还愿，就不蒙悦纳。","notes":[]},{"n":24,"t":"凡睾丸损伤，或压碎，或破裂，或阉割的，都不可献给耶和华；不可在你们的地上行这事。","notes":[]},{"n":25,"t":"从外人的手里得到任何这类的动物，也不可献上作你们神的食物；因为它们有缺陷，有残疾，它们必不为你们而蒙悦纳。”","notes":[]},{"n":26,"t":"耶和华吩咐摩西说：","notes":[]},{"n":27,"t":"“刚出生的公牛，或绵羊，或山羊，七天当跟着它的母亲；从第八天起，可以当供物作为耶和华的火祭，这是蒙悦纳的。","notes":[]},{"n":28,"t":"无论是牛或羊，不可在同一日宰它和它的小牛小羊。","notes":[]},{"n":29,"t":"你们宰杀祭牲献感谢祭给耶和华，要献得使你们可蒙悦纳；","notes":[]},{"n":30,"t":"要在当天吃，一点也不可留到早晨。我是耶和华。","notes":[]},{"n":31,"t":"“你们要谨守我的诫命，遵行它们。我是耶和华。","notes":[]},{"n":32,"t":"你们不可亵渎我的圣名；我在以色列人中要被尊为圣。我是使你们分别为圣的耶和华，","notes":[]},{"n":33,"t":"曾把你们从埃及地领出来，作你们的神。我是耶和华。”","notes":[]}]},"23":{"heading":"耶和华的节期","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人，对他们说：以下是我的节期，是你们要宣告为圣会的耶和华的节期。”","notes":[]},{"n":3,"t":"“六日要做工，第七日是完全安息的安息日，要有圣会；你们任何工都不可做。这是在你们一切的住处向耶和华当守的安息日。”","notes":[],"heads":["安息日"]},{"n":4,"t":"“以下是你们要按时宣告为圣会的耶和华的节期。”","notes":[]},{"n":5,"t":"“正月十四日黄昏的时候，是向耶和华守的逾越节。","notes":["“黄昏的时候”：原文是“两个黄昏之间”。"],"heads":["逾越节和除酵节"]},{"n":6,"t":"这月的十五日是向耶和华守的除酵节；你们要吃无酵饼七日。","notes":[]},{"n":7,"t":"第一日要有圣会，任何劳动的工都不可做；","notes":[]},{"n":8,"t":"要将火祭献给耶和华七日。第七日要有圣会，任何劳动的工都不可做。”","notes":[]},{"n":9,"t":"耶和华吩咐摩西说：","notes":[],"heads":["初熟庄稼的奉献"]},{"n":10,"t":"“你要吩咐以色列人，对他们说：你们到了我赐给你们的地，收割庄稼的时候，要把初熟庄稼中的一捆拿来给祭司。","notes":[]},{"n":11,"t":"他要把这捆在耶和华面前摇一摇，使你们蒙悦纳。祭司要在安息日的次日把这捆摇一摇。","notes":[]},{"n":12,"t":"摇这捆的那一日，你们要献一只一岁没有残疾的小公绵羊，给耶和华作燔祭。","notes":[]},{"n":13,"t":"同献的素祭是十分之二伊法调了油的细面，作为献给耶和华馨香的火祭；同献的浇酒祭是四分之一欣酒。","notes":[]},{"n":14,"t":"无论是饼，是烘熟的谷物，是新穗子，你们都不可吃；直等到你们把这供物带来献给你们神的那一天，才可以吃。在你们一切的住处，这要成为你们世世代代永远的定例。”","notes":[]},{"n":15,"t":"“你们要从安息日的次日，就是献那捆庄稼为摇祭的那日起，计算足足的七个安息日。","notes":[],"heads":["七七收获节"]},{"n":16,"t":"到第七个安息日的次日，共计五十天，你们要将新的素祭献给耶和华。","notes":[]},{"n":17,"t":"要从你们的住处取十分之二伊法细面，加酵烤成两个摇祭的饼，作为初熟之物献给耶和华。","notes":[]},{"n":18,"t":"又要将七只一岁没有残疾的羔羊、一头公牛犊、两只公绵羊和饼一同奉上。这些要和素祭和浇酒祭一同作为燔祭献给耶和华，作馨香的火祭献给耶和华。","notes":[]},{"n":19,"t":"你们要献一只公山羊为赎罪祭，两只一岁的小公绵羊为平安祭。","notes":[]},{"n":20,"t":"祭司要把这些和初熟庄稼做成的饼，与两只小公绵羊一同在耶和华面前摇一摇，作为摇祭。这些献给耶和华的圣物是归给祭司的。","notes":[]},{"n":21,"t":"在这一日，你们要宣告圣会；任何劳动的工都不可做。在你们一切的住处，这要成为你们世世代代永远的定例。","notes":[]},{"n":22,"t":"“你们在自己的地收割庄稼时，不可割尽田的角落，也不可拾取庄稼所掉落的，要把它们留给穷人和寄居的。我是耶和华－你们的神。”","notes":[]},{"n":23,"t":"耶和华吩咐摩西说：","notes":[],"heads":["新年"]},{"n":24,"t":"“你要吩咐以色列人说：七月初一，你们要守为完全安息的日子，要吹角作纪念，当有圣会。","notes":[]},{"n":25,"t":"任何劳动的工都不可做；要将火祭献给耶和华。”","notes":[]},{"n":26,"t":"耶和华吩咐摩西说：","notes":[],"heads":["赎罪日"]},{"n":27,"t":"“但是，七月初十是赎罪日；你们要守为圣会，刻苦己心，并要将火祭献给耶和华。","notes":[]},{"n":28,"t":"在这一日，任何工都不可做；因为这是赎罪日，要在耶和华－你们的神面前赎罪。","notes":[]},{"n":29,"t":"在这一日，凡不刻苦己心的，必从百姓中剪除。","notes":[]},{"n":30,"t":"凡在这一日做任何工的，我必将他从百姓中除灭。","notes":[]},{"n":31,"t":"任何工你们都不可做。在你们一切的住处，这要成为你们世世代代永远的定例。","notes":[]},{"n":32,"t":"你们要守这日为完全安息的安息日，刻苦己心；从这月初九晚上到次日晚上，你们要守为安息日。”","notes":[]},{"n":33,"t":"耶和华吩咐摩西说：","notes":[],"heads":["住棚节"]},{"n":34,"t":"“你要吩咐以色列人说：这七月十五日是住棚节，要向耶和华守这节七日。","notes":[]},{"n":35,"t":"第一日当有圣会，任何劳动的工都不可做。","notes":[]},{"n":36,"t":"要将火祭献给耶和华七日。第八日当守圣会，并要献火祭给耶和华。这是严肃会，任何劳动的工都不可做。","notes":[]},{"n":37,"t":"“这是耶和华的节期，就是你们要宣告为圣会的节期；要将火祭，就是燔祭、素祭、祭物和浇酒祭，按照每日的规定献给耶和华。","notes":[]},{"n":38,"t":"除此之外，还有耶和华的安息日，你们献给耶和华的供物，一切的还愿祭，和一切的甘心祭。","notes":[]},{"n":39,"t":"“但是，从七月十五日起，你们收藏了地的出产之后，要守耶和华的节期七日。第一日为要完全安息，第八日也要完全安息。","notes":[]},{"n":40,"t":"第一日，你们要拿美好树上的果子、棕树枝、树叶茂密的枝条和河边的柳枝，在耶和华－你们的神面前欢乐七日。","notes":[]},{"n":41,"t":"每年你们要向耶和华守这节七日。你们在七月里所守的节，要成为世世代代永远的定例。","notes":[]},{"n":42,"t":"你们要住在棚里七日；凡以色列家出生的人都要住在棚里，","notes":[]},{"n":43,"t":"好叫你们世世代代知道，我领以色列人出埃及地的时候，曾使他们住在棚里。我是耶和华－你们的神。”","notes":[]},{"n":44,"t":"于是，摩西向以色列人颁布了耶和华的节期。","notes":[]}]},"24":{"heading":"点灯","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人，把那捣成的纯橄榄油拿来给你，用以点灯，使灯经常点着。","notes":[]},{"n":3,"t":"在会幕中法柜前的幔子外，亚伦从晚上到早晨要在耶和华面前照管这灯。这要成为你们世世代代永远的定例。","notes":[]},{"n":4,"t":"他要在耶和华面前经常照管纯金灯台上的灯。”","notes":["“纯金”：原文是“纯”；下同。"]},{"n":5,"t":"“你要取细面，烤成十二个饼，每个用十分之二伊法。","notes":[],"heads":["供饼"]},{"n":6,"t":"要把饼排成两行，每行六个，供在耶和华面前的纯金桌子上。","notes":["“行”或译“堆”；下同。"]},{"n":7,"t":"再把纯乳香撒在每行饼上，作为纪念，是献给耶和华为食物的火祭。","notes":[]},{"n":8,"t":"每个安息日，亚伦要把饼不间断地供在耶和华面前。这是以色列人永远的约。","notes":[]},{"n":9,"t":"这饼要归给亚伦和他的子孙。他们要在圣处吃这饼，因为在献给耶和华的火祭中，这饼是至圣的，归给他作永远当得的份。”","notes":[]},{"n":10,"t":"有一个以色列妇人的儿子，他父亲是埃及人。有一日他出去，到以色列人中。这以色列妇人的儿子和一个以色列人在营里争吵。","notes":[],"heads":["亵渎罪的判例"]},{"n":11,"t":"以色列妇人的儿子诅咒，亵渎了圣名。有人把他送到摩西那里。他的母亲名叫示罗密，是但支派底伯利的女儿。","notes":[]},{"n":12,"t":"他们把这人收押在监里，等候耶和华指示的话。","notes":[]},{"n":13,"t":"耶和华吩咐摩西说：","notes":[]},{"n":14,"t":"“把那诅咒的人带到营外。凡听见的人都要把手放在他头上，全会众要用石头打死他。","notes":[]},{"n":15,"t":"你要吩咐以色列人说：凡诅咒神的，必要担当自己的罪。","notes":[]},{"n":16,"t":"亵渎耶和华名的，必被处死；全会众必须用石头打死他。无论是寄居的，是本地人，他亵渎圣名的时候必被处死。","notes":[]},{"n":17,"t":"“打死人的，必被处死；","notes":[]},{"n":18,"t":"打死牲畜的，必赔上牲畜，以命偿命。","notes":[]},{"n":19,"t":"人若伤害邻舍以致残疾，他怎样做，也要照样向他做：","notes":[]},{"n":20,"t":"以伤还伤，以眼还眼，以牙还牙。他怎样使人有残疾，也要照样向他做。","notes":[]},{"n":21,"t":"打死牲畜的，必赔上牲畜；打死人的，必被处死。","notes":[]},{"n":22,"t":"无论是寄居的，是本地人，都依照同一条例。我是耶和华－你们的神。”","notes":[]},{"n":23,"t":"于是，摩西吩咐以色列人，他们就把那诅咒的人带到营外，用石头打死。以色列人就照耶和华所吩咐摩西的做了。","notes":[]}]},"25":{"heading":"安息年","verses":[{"n":1,"t":"耶和华在西奈山吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人，对他们说：你们到了我所赐你们那地的时候，地要休耕，向耶和华守安息。","notes":[]},{"n":3,"t":"你们六年要耕种田地，六年要修整葡萄园，收藏地的出产。","notes":[]},{"n":4,"t":"第七年，地要守完全安息的安息年，就是向耶和华守安息。你们不可耕种田地，也不可修整葡萄园。","notes":[]},{"n":5,"t":"不可收割自然生长的庄稼，也不可摘取没有修剪的葡萄树上的葡萄。这年，地要完全安息。","notes":[]},{"n":6,"t":"地在安息年所长出的，要给你和你的奴仆、使女、雇工，以及寄居在你那里的外人作食物。","notes":[]},{"n":7,"t":"所有的出产也要给你的牲畜和你地上的走兽作食物。”","notes":[]},{"n":8,"t":"“你要计算七个安息年，就是七个七年。这就成为你的七个安息年，一共四十九年。","notes":[],"heads":["禧年"]},{"n":9,"t":"七月初十，你要大声吹角；这是赎罪日，你要在全地吹角。","notes":[]},{"n":10,"t":"你们要以第五十年为圣年，在全地向所有的居民宣告自由。这是你们的禧年，各人的产业要归还自己，各人要归回自己的家。","notes":[]},{"n":11,"t":"第五十年要作为你们的禧年。你们不可耕种，不可收割自然生长的庄稼，也不可摘取没有修剪的葡萄树上的葡萄。","notes":[]},{"n":12,"t":"因为这是禧年，是你们的圣年；你们要吃地中自然生长的农作物。","notes":[]},{"n":13,"t":"“这禧年，你们各人的产业要归还自己。","notes":[]},{"n":14,"t":"无论你卖什么给邻舍，或从邻舍的手中买什么，彼此不可亏负。","notes":[]},{"n":15,"t":"你要按照禧年后的年数向邻舍买；他要按照可收成的年数卖给你；","notes":[]},{"n":16,"t":"年数越多，价钱就越高；年数越少，价钱就越低，因为他卖给你的是收成的数量。","notes":[]},{"n":17,"t":"你们彼此不可亏负，只要敬畏你的神，因为我是耶和华－你们的神。”","notes":[]},{"n":18,"t":"“你们要遵行我的律例，谨守我的典章，遵行它们，就可以在那地上安然居住。","notes":[],"heads":["安息年的食物"]},{"n":19,"t":"地必出产果实，你们可以吃饱，在那地上安然居住。","notes":[]},{"n":20,"t":"你们若说：‘看哪，第七年我们不耕种，也不收藏农作物，我们吃什么呢？’","notes":[]},{"n":21,"t":"我必在第六年发令赐福给你们，地就长出三年的农作物来。","notes":[]},{"n":22,"t":"第八年你们要耕种，也要吃陈粮；等到第九年农作物收成的时候，你们还有陈粮吃。”","notes":[]},{"n":23,"t":"“地不可以卖断，因为地是我的；你们在我面前是客旅，是寄居的。","notes":[],"heads":["赎房地产的条例"]},{"n":24,"t":"在你们所得为业的全地，要准许人有权将地赎回。","notes":[]},{"n":25,"t":"“你的弟兄若渐渐贫穷，卖了他的一些产业，他的至亲就要来把弟兄所卖的赎回。","notes":[]},{"n":26,"t":"若没有人能为他赎回，他的手头渐渐宽裕，能够赎回，","notes":[]},{"n":27,"t":"就要计算卖后的年数，把剩余年数的价钱归还给那买主，他的地业便归还自己。","notes":[]},{"n":28,"t":"若他手头的财力不够赎回，所卖的地就要留在买主的手里，直到禧年。到了禧年，地业要归还卖主。","notes":[]},{"n":29,"t":"“人若卖城墙内的住宅，卖了以后，一整年内他有权赎回；这是他可以赎回的期限。","notes":[]},{"n":30,"t":"若他在一整年内不赎回，这有墙之城的房屋就确定永归买主，直到世世代代；在禧年也不必归还。","notes":[]},{"n":31,"t":"但周围无城墙之村庄的房屋，要看为乡下的田地，可以赎回；到了禧年就要归还。","notes":[]},{"n":32,"t":"至于利未人所得为业的城镇，利未人可以随时赎回他们城镇中的房屋。","notes":[]},{"n":33,"t":"在所得为业的城镇，利未人若卖了房屋，又不赎回，到了禧年仍要归还原主，因为利未人城镇的房屋是他们在以色列人中的产业。","notes":[]},{"n":34,"t":"但是利未人各城郊外之地是不可卖的，因为这是他们永远的产业。”","notes":[]},{"n":35,"t":"“你的弟兄在你那里若渐渐贫穷，手头缺乏，你就要帮补他，使他与你一同生活，像外人和寄居的一样。","notes":[],"heads":["借贷给穷人的条例"]},{"n":36,"t":"不可向他取利息，也不可向他索取高利；要敬畏你的神，使你的弟兄与你一同生活。","notes":[]},{"n":37,"t":"你不可为了利息借钱给他，也不可为了高利而借粮。","notes":[]},{"n":38,"t":"我是耶和华－你们的神，曾领你们从埃及地出来，为要把迦南地赐给你们，要作你们的神。","notes":[]},{"n":39,"t":"“你的弟兄在你那里若渐渐贫穷，将自己卖给你，你不可叫他像奴仆服事你。","notes":[]},{"n":40,"t":"他在你那里要像雇工和寄居的，服事你直到禧年。","notes":[]},{"n":41,"t":"他和他儿女要离开你，一同出去，归回自己的家，回到他祖宗的地业去。","notes":[]},{"n":42,"t":"因为他们是我的仆人，是我从埃及地领出来的。他们不可被卖为奴仆。","notes":[]},{"n":43,"t":"不可苛刻管辖他，只要敬畏你的神。","notes":[]},{"n":44,"t":"至于你所要的奴仆和使女，可以来自你们四围的列国，你们可以从他们中买奴仆和使女。","notes":[]},{"n":45,"t":"那些寄居在你们中间的外人和他们的家属，就是在你们地上所生的，你们可以从其中买人；他们要作你们的产业。","notes":[]},{"n":46,"t":"你们可以把他们遗留给你们后代的子孙，作为永远继承的产业；你们可以使他们作奴仆。至于你们的弟兄以色列人，你们彼此不可苛刻管辖。","notes":[]},{"n":47,"t":"“住在你那里的外人或寄居的，若手头渐渐宽裕，你的弟兄却渐渐贫穷，将自己卖给那外人或寄居的，或外人家族的一支，","notes":[]},{"n":48,"t":"卖了以后，有权把自己赎回。他弟兄中的一位可以把他赎回。","notes":[]},{"n":49,"t":"他的叔伯或叔伯的儿子可以赎他。他家族中的骨肉之亲也可以赎他。他自己若手头渐渐宽裕，也可以赎回自己。","notes":[]},{"n":50,"t":"他要跟买主计算，从卖自己的那年起，算到禧年；所卖的价钱要按照年数计算，就是雇工跟买主在一起的日子。","notes":[]},{"n":51,"t":"若剩余的年数多，就要按着年数从买价中偿还他的赎价。","notes":[]},{"n":52,"t":"若到禧年只剩下几年，就要按着年数跟买主计算，偿还他的赎价。","notes":[]},{"n":53,"t":"他和买主同住，要像按年雇用的工人，买主不可苛刻管辖他。","notes":[]},{"n":54,"t":"他若不这样被赎，到了禧年，仍要和他的儿女一同出去。","notes":[]},{"n":55,"t":"因为以色列人都是我的仆人，他们是我的仆人，是我领他们从埃及地出来的。我是耶和华－你们的神。”","notes":[]}]},"26":{"heading":"遵行诫命者蒙福","verses":[{"n":1,"t":"“你们不可为自己造虚无的神明，不可竖立雕刻的偶像或柱像，也不可在你们的地上安放石像，向它跪拜，因为我是耶和华－你们的神。","notes":[]},{"n":2,"t":"你们要谨守我的安息日，敬畏我的圣所。我是耶和华。","notes":[]},{"n":3,"t":"“你们若遵行我的律例，谨守我的诫命，实行它们，","notes":[]},{"n":4,"t":"我必按时降雨给你们，使地长出农作物，田野的树结出果实。","notes":[]},{"n":5,"t":"你们打谷物要打到摘葡萄的时候，摘葡萄要摘到播种的时候。你们要吃粮食得饱足，在你们的地上安然居住。","notes":[]},{"n":6,"t":"我要赐平安在地上；你们躺卧，无人惊吓。我要使你们地上的恶兽消灭，刀剑必不穿越你们的地。","notes":[]},{"n":7,"t":"你们要追赶仇敌，他们必倒在你们刀下。","notes":[]},{"n":8,"t":"你们五个人要追赶一百人，一百人要追赶一万人；仇敌必在你们面前倒在刀下。","notes":[]},{"n":9,"t":"我要眷顾你们，使你们生养众多，也要与你们坚立我的约。","notes":[]},{"n":10,"t":"你们要吃储存的陈粮，又要为新粮清理陈粮。","notes":[]},{"n":11,"t":"我要在你们中间立我的帐幕，我的心也不厌恶你们。","notes":[]},{"n":12,"t":"我要行走在你们中间，作你们的神，你们要作我的子民。","notes":[]},{"n":13,"t":"我是耶和华－你们的神，曾将你们从埃及地领出来，使你们不再作埃及人的奴仆；我曾折断你们所负的轭，使你们挺身前行。”","notes":[]},{"n":14,"t":"“你们若不听从我，不遵行我这一切的诫命，","notes":[],"heads":["违反诫命者遭祸"]},{"n":15,"t":"厌弃我的律例，心中厌恶我的典章，不遵行我一切的诫命，背弃了我的约，","notes":[]},{"n":16,"t":"我就要这样对待你们：我必使惊惶临到你们，使你们患痨病，害热病，以致眼睛失明，身体衰弱。你们要白白撒种，因为仇敌要吃尽你们所种的。","notes":[]},{"n":17,"t":"我要向你们变脸，使你们败在仇敌的面前。恨恶你们的必管辖你们；无人追赶，你们却要逃跑。","notes":[]},{"n":18,"t":"如果这样，你们还不听从我，我就要因你们的罪，加重七倍惩罚你们。","notes":[]},{"n":19,"t":"我必粉碎你们因势力而有的骄傲，又要使你们的天坚如铁，地硬如铜。","notes":[]},{"n":20,"t":"你们劳力却白费，因为你们的地没有出产，地上的树也不结果实。","notes":[]},{"n":21,"t":"“你们行事若与我作对，不肯听从我，我就要因你们的罪，加重七倍灾祸击打你们。","notes":[]},{"n":22,"t":"我要打发野地的走兽到你们中间，夺去你们的儿女，吞灭你们的牲畜，使你们人数减少，道路荒凉。","notes":[]},{"n":23,"t":"“如果这样，你们还不接受管教归向我，行事与我作对，","notes":[]},{"n":24,"t":"我就要行事与你们作对，因你们的罪，加重七倍击打你们。","notes":[]},{"n":25,"t":"我要使刀剑临到你们，报复你们的背约。你们若被赶入城中，我要降瘟疫在你们中间，把你们交在仇敌手中。","notes":[]},{"n":26,"t":"我要断绝你们粮食的供应，使十个女人用一个烤炉给你们烤饼，按配给的定量秤给你们。你们要吃，却吃不饱。","notes":["“粮食的供应”：原文直译“粮食的杖”。"]},{"n":27,"t":"“如果这样，你们还不听从我，行事与我作对，","notes":[]},{"n":28,"t":"我就要向你们发烈怒，行事与你们作对，因你们的罪，加重七倍惩罚你们。","notes":[]},{"n":29,"t":"你们要吃你们儿子的肉，也要吃你们女儿的肉。","notes":[]},{"n":30,"t":"我要摧毁你们的丘坛，砍掉你们的香坛，把你们的尸首扔在你们偶像的残骸上。我的心也必厌恶你们，","notes":[]},{"n":31,"t":"使你们的城镇变成废墟，你们的众圣所变荒凉，我也不闻你们芬芳的香气。","notes":[]},{"n":32,"t":"我要使这地变荒凉，甚至占领这地的敌人都惊讶。","notes":[]},{"n":33,"t":"我要把你们驱散到列国中，也要拔刀追赶你们。你们的地要成为荒凉，你们的城镇要变成废墟。","notes":[]},{"n":34,"t":"“当你们在敌人之地的时候，你们的地要在一切荒凉的日子重享安息；在那时候，地要休息，重享安息。","notes":[]},{"n":35,"t":"地在一切荒凉的日子都要安息，这是你们住在其上的时候所不能得的安息。","notes":[]},{"n":36,"t":"至于你们幸存的人，我要使他们在敌人之地心中惊慌，甚至风吹落叶的声音也把他们吓跑。他们要逃避，像人逃避刀剑，虽无人追赶，却要跌倒。","notes":[]},{"n":37,"t":"虽然无人追赶，他们却要彼此绊倒，像逃避刀剑一样。你们在仇敌面前必站立不住。","notes":[]},{"n":38,"t":"你们要在列国中灭亡，敌人之地要吞灭你们，","notes":[]},{"n":39,"t":"你们幸存的人必因自己的罪孽在敌人之地衰残，也要因祖先的罪孽衰残。","notes":[]},{"n":40,"t":"“他们要承认自己的罪孽和祖先的罪孽，就是背叛我，行事与我作对的过犯。","notes":[]},{"n":41,"t":"我也行事与他们作对，把他们遣送到敌人之地。那时，他们未受割礼的心若肯谦卑，也服了罪孽的惩罚，","notes":[]},{"n":42,"t":"我就要记念我与雅各的约，记念我与以撒的约，与亚伯拉罕的约；我也要记念这地。","notes":[]},{"n":43,"t":"地被他们离弃，因他们不在而荒凉的时候，就要重享安息。他们服了罪孽的惩罚，因为他们厌弃我的典章，心中厌恶我的律例。","notes":[]},{"n":44,"t":"虽然如此，当他们在敌人之地时，我却不厌弃他们，不厌恶他们，将他们全然灭绝，也不背弃我与他们的约，因为我是耶和华－他们的神。","notes":[]},{"n":45,"t":"我要为他们的缘故记念我与他们祖先的约；我在列国眼前曾把他们的祖先从埃及地领出来，为要作他们的神。我是耶和华。”","notes":[]},{"n":46,"t":"这些律例、典章和法度是耶和华在西奈山上藉着摩西与以色列人立的。","notes":[]}]},"27":{"heading":"还愿和估价的条例","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人，对他们说：人向耶和华许特别的愿，要按照你所估一个人的价钱。","notes":[]},{"n":3,"t":"你所估的是：二十岁到六十岁男的，按照圣所的舍客勒，估价是五十舍客勒银子。","notes":[]},{"n":4,"t":"若是女的，估价是三十舍客勒。","notes":[]},{"n":5,"t":"五岁到二十岁男的，估价是二十舍客勒，女的十舍客勒。","notes":[]},{"n":6,"t":"一个月到五岁男的，估价是五舍客勒，女的三舍客勒。","notes":[]},{"n":7,"t":"六十岁以上男的，估价是十五舍客勒，女的十舍客勒。","notes":[]},{"n":8,"t":"他若贫穷，不能按照你的估价，就要把他带到祭司面前，让祭司为他估价；祭司要按许愿者手头财力所及估价。","notes":[]},{"n":9,"t":"“许愿要献给耶和华的供物若是牲畜，凡这类献给耶和华的都要成为圣。","notes":[]},{"n":10,"t":"不可更换，也不可用另一只取代，无论是好的换坏的，或是坏的换好的，都不可。若一定要以牲畜取代牲畜，所许的与所取代的都要成为圣。","notes":[]},{"n":11,"t":"若牲畜不洁净，不可献给耶和华为供物，就要把牲畜带到祭司面前。","notes":[]},{"n":12,"t":"祭司要估价；牲畜是好是坏，祭司怎样估定，就是你的估价。","notes":[]},{"n":13,"t":"许愿者若一定要把它赎回，就要在你的估价上加五分之一。","notes":[]},{"n":14,"t":"“人将房屋分别为圣，归给耶和华为圣，祭司就要估价。房屋是好是坏，祭司怎样估定，就要以他的估价为准。","notes":[]},{"n":15,"t":"将房屋分别为圣的人，若要赎回房屋，必须付你所估定的价钱，再加上五分之一，房屋才可以归还给他。","notes":[]},{"n":16,"t":"“人若将所继承的一块田地分别为圣，归给耶和华，就要按照这地撒种多少来估价；能撒一贺梅珥大麦种子的，是五十舍客勒银子。","notes":[]},{"n":17,"t":"他若从禧年起将地分别为圣，就要以你的估价为准。","notes":[]},{"n":18,"t":"倘若他在禧年以后将地分别为圣，祭司就要按照从那时到下一个禧年所剩的年数推算，从你的估价中减掉。","notes":[]},{"n":19,"t":"将地分别为圣的人若要把地赎回，必须付你所估定的价钱，再加上五分之一，地才可以归还给他。","notes":[]},{"n":20,"t":"他若不赎回那地，或是将地卖给别人，就不能再赎了。","notes":[]},{"n":21,"t":"到了禧年，那田地要从买主手中退还，归耶和华为圣，和永献的地一样，要归祭司为业。","notes":[]},{"n":22,"t":"若分别为圣归耶和华的田地不是继承的，而是买来的，","notes":[]},{"n":23,"t":"祭司就要依照你的估价，推算到禧年。当天，这人要将你所估的归给耶和华为圣。","notes":[]},{"n":24,"t":"到了禧年，那田地要退还给卖主，就是继承那地的原主。","notes":[]},{"n":25,"t":"凡你所估的价钱都要按照圣所的舍客勒：二十季拉是一舍客勒。","notes":[]},{"n":26,"t":"“头生的，就是牲畜中头生属耶和华的，人不可再将它分别为圣，无论是牛是羊都是耶和华的。","notes":[]},{"n":27,"t":"头生的牲畜若是不洁净的，就要按照所估定的价钱，再加上五分之一，把它赎回。若不赎回，就要按照你的估价把它卖了。","notes":[]},{"n":28,"t":"“但一切永献作当灭的，就是人从他所有永献给耶和华作当灭的，无论是人，是牲畜，是他继承的田地，都不可卖，也不可赎。凡永献作当灭的都归耶和华为至圣。","notes":[]},{"n":29,"t":"凡从人中永献作当灭的都不可赎，必被处死。","notes":[]},{"n":30,"t":"“地上所有的，无论是地上的种子，是树上的果子，十分之一是耶和华的，是归耶和华为圣的。","notes":[]},{"n":31,"t":"人若要赎回这十分之一，就要另加五分之一。","notes":[]},{"n":32,"t":"凡牛群羊群中的十分之一，就是一切从牧人杖下经过的，每第十只要归耶和华为圣。","notes":[]},{"n":33,"t":"不可追究是好是坏，也不可取代；若一定要取代，所取代的和本来当献的牲畜都要成为圣，不可赎回。”","notes":[]},{"n":34,"t":"这些是耶和华在西奈山为以色列人所吩咐摩西的命令。","notes":[]}]}},"NUM":{"1":{"heading":"第一次人口普查","verses":[{"n":1,"t":"以色列人出埃及地后第二年二月初一，耶和华在西奈旷野，在会幕中吩咐摩西说：","notes":[]},{"n":2,"t":"“你要按宗族、父家、人名的数目计算以色列全会众，数点所有的男丁。","notes":[]},{"n":3,"t":"以色列中凡二十岁以上能出去打仗的，你和亚伦要按照他们的队伍数点。","notes":[]},{"n":4,"t":"每支派要有一个人，就是父家的家长跟你们一起。","notes":[]},{"n":5,"t":"这是帮助你们的人的名字：属吕便的，示丢珥的儿子以利蓿；","notes":[]},{"n":6,"t":"属西缅的，苏利沙代的儿子示路蔑；","notes":[]},{"n":7,"t":"属犹大的，亚米拿达的儿子拿顺；","notes":[]},{"n":8,"t":"属以萨迦的，苏押的儿子拿坦业；","notes":[]},{"n":9,"t":"属西布伦的，希伦的儿子以利押；","notes":[]},{"n":10,"t":"约瑟子孙、属以法莲的，亚米忽的儿子以利沙玛；属玛拿西的，比大蓿的儿子迦玛列；","notes":[]},{"n":11,"t":"属便雅悯的，基多尼的儿子亚比但；","notes":[]},{"n":12,"t":"属但的，亚米沙代的儿子亚希以谢；","notes":[]},{"n":13,"t":"属亚设的，俄兰的儿子帕结；","notes":[]},{"n":14,"t":"属迦得的，丢珥的儿子以利雅萨；","notes":[]},{"n":15,"t":"属拿弗他利的，以南的儿子亚希拉。”","notes":[]},{"n":16,"t":"这些是从会众中选出来的父系支派的领袖，是以色列部队的官长。","notes":[]},{"n":17,"t":"于是，摩西和亚伦带着这些按名指定的人，","notes":[]},{"n":18,"t":"在二月初一召集全会众。会众就照他们的宗族、父家、人名的数目，登记二十岁以上的人口。","notes":[]},{"n":19,"t":"耶和华怎样吩咐摩西，他就照样在西奈的旷野数点他们。","notes":[]},{"n":20,"t":"以色列的长子，吕便子孙的后代，照着宗族、父家、人名的数目，他们的人口凡二十岁以上能出去打仗的男丁，","notes":[]},{"n":21,"t":"吕便支派被数的共有四万六千五百名。","notes":[]},{"n":22,"t":"西缅子孙的后代，照着宗族、父家、被数人名的数目，他们的人口凡二十岁以上能出去打仗的男丁，","notes":["有古卷、七十士译本和其他古译本没有“被数”。"]},{"n":23,"t":"西缅支派被数的共有五万九千三百名。","notes":[]},{"n":24,"t":"迦得子孙的后代，照着宗族、父家、人名的数目，凡二十岁以上能出去打仗的，","notes":[]},{"n":25,"t":"迦得支派被数的共有四万五千六百五十名。","notes":[]},{"n":26,"t":"犹大子孙的后代，照着宗族、父家、人名的数目，凡二十岁以上能出去打仗的，","notes":[]},{"n":27,"t":"犹大支派被数的共有七万四千六百名。","notes":[]},{"n":28,"t":"以萨迦子孙的后代，照着宗族、父家、人名的数目，凡二十岁以上能出去打仗的，","notes":[]},{"n":29,"t":"以萨迦支派被数的共有五万四千四百名。","notes":[]},{"n":30,"t":"西布伦子孙的后代，照着宗族、父家、人名的数目，凡二十岁以上能出去打仗的，","notes":[]},{"n":31,"t":"西布伦支派被数的共有五万七千四百名。","notes":[]},{"n":32,"t":"约瑟子孙属以法莲子孙的后代，照着宗族、父家、人名的数目，凡二十岁以上能出去打仗的，","notes":[]},{"n":33,"t":"以法莲支派被数的共有四万零五百名。","notes":[]},{"n":34,"t":"玛拿西子孙的后代，照着宗族、父家、人名的数目，凡二十岁以上能出去打仗的，","notes":[]},{"n":35,"t":"玛拿西支派被数的共有三万二千二百名。","notes":[]},{"n":36,"t":"便雅悯子孙的后代，照着宗族、父家、人名的数目，凡二十岁以上能出去打仗的，","notes":[]},{"n":37,"t":"便雅悯支派被数的共有三万五千四百名。","notes":[]},{"n":38,"t":"但子孙的后代，照着宗族、父家、人名的数目，凡二十岁以上能出去打仗的，","notes":[]},{"n":39,"t":"但支派被数的共有六万二千七百名。","notes":[]},{"n":40,"t":"亚设子孙的后代，照着宗族、父家、人名的数目，凡二十岁以上能出去打仗的，","notes":[]},{"n":41,"t":"亚设支派被数的共有四万一千五百名。","notes":[]},{"n":42,"t":"拿弗他利子孙的后代，照着宗族、父家、人名的数目，凡二十岁以上能出去打仗的，","notes":[]},{"n":43,"t":"拿弗他利支派被数的共有五万三千四百名。","notes":[]},{"n":44,"t":"这些就是被数点的，是摩西、亚伦和以色列十二个领袖所数点的；每一个领袖代表他们的父家。","notes":[]},{"n":45,"t":"以色列人被数点的总数，以色列中照着父家，凡二十岁以上能出去打仗的，","notes":[]},{"n":46,"t":"他们被数点的总数是六十万三千五百五十名。","notes":[]},{"n":47,"t":"利未人却没有按照父系支派数在其中。","notes":[]},{"n":48,"t":"耶和华吩咐摩西说：","notes":[]},{"n":49,"t":"“惟独利未支派你不可数点，也不可在以色列人中计算他们的人口。","notes":[]},{"n":50,"t":"你要派利未人管理法柜的帐幕和其中一切的器具，以及属帐幕的一切。他们要抬帐幕和其中一切的器具，并要办理帐幕的事务，在帐幕的四围安营。","notes":[]},{"n":51,"t":"帐幕将往前行的时候，利未人要拆卸；将驻扎的时候，利未人要支搭帐幕。近前来的外人必被处死。","notes":[]},{"n":52,"t":"以色列人要按照各自的队伍安营，各归本营，各归本旗。","notes":[]},{"n":53,"t":"但利未人要在法柜帐幕的四围安营，免得愤怒临到以色列会众；利未人要负责看守法柜的帐幕。”","notes":[]},{"n":54,"t":"以色列人就这样做了。凡耶和华所吩咐摩西的，他们都照样做了。","notes":[]}]},"2":{"heading":"安营和行军的次序","verses":[{"n":1,"t":"耶和华吩咐摩西和亚伦说：","notes":[]},{"n":2,"t":"“以色列人各人要在自己的旗帜下，按照自己父家的旗号安营，对着会幕的四围安营。","notes":[]},{"n":3,"t":"“在东边，向日出的方向，犹大营按照他们的队伍，在它的旗帜下安营。犹大人的领袖是亚米拿达的儿子拿顺，","notes":[]},{"n":4,"t":"他的军队被数的有七万四千六百名。","notes":[]},{"n":5,"t":"在他旁边安营的是以萨迦支派。以萨迦人的领袖是苏押的儿子拿坦业，","notes":[]},{"n":6,"t":"他的军队被数的有五万四千四百名。","notes":[]},{"n":7,"t":"还有西布伦支派，西布伦人的领袖是希伦的儿子以利押，","notes":[]},{"n":8,"t":"他的军队被数的有五万七千四百名。","notes":[]},{"n":9,"t":"凡属犹大营，照他们队伍被数的共有十八万六千四百名；他们要作第一队往前行。","notes":[]},{"n":10,"t":"“在南边，按照他们的队伍是吕便营的旗帜。吕便人的领袖是示丢珥的儿子以利蓿，","notes":[]},{"n":11,"t":"他的军队被数的有四万六千五百名。","notes":[]},{"n":12,"t":"在他旁边安营的是西缅支派。西缅人的领袖是苏利沙代的儿子示路蔑，","notes":[]},{"n":13,"t":"他的军队被数的有五万九千三百名。","notes":[]},{"n":14,"t":"还有迦得支派，迦得人的领袖是丢珥的儿子以利雅萨，","notes":[]},{"n":15,"t":"他的军队被数的有四万五千六百五十名。","notes":[]},{"n":16,"t":"凡属吕便营，照他们队伍被数的共有十五万一千四百五十名；他们要作第二队往前行。","notes":[]},{"n":17,"t":"“会幕与利未营在诸营中间往前行。他们怎样安营就怎样往前行，各按本位，各归本旗。","notes":[]},{"n":18,"t":"“在西边，按照他们的队伍是以法莲营的旗帜。以法莲人的领袖是亚米忽的儿子以利沙玛，","notes":[]},{"n":19,"t":"他的军队被数的有四万零五百名。","notes":[]},{"n":20,"t":"在他旁边的是玛拿西支派。玛拿西人的领袖是比大蓿的儿子迦玛列，","notes":[]},{"n":21,"t":"他的军队被数的有三万二千二百名。","notes":[]},{"n":22,"t":"还有便雅悯支派，便雅悯人的领袖是基多尼的儿子亚比但，","notes":[]},{"n":23,"t":"他的军队被数的有三万五千四百名。","notes":[]},{"n":24,"t":"凡属以法莲营，照他们队伍被数的共有十万八千一百名；他们要作第三队往前行。","notes":[]},{"n":25,"t":"“在北边，按照他们的队伍是但营的旗帜。但人的领袖是亚米沙代的儿子亚希以谢，","notes":[]},{"n":26,"t":"他的军队被数的有六万二千七百名。","notes":[]},{"n":27,"t":"在他旁边安营的是亚设支派。亚设人的领袖是俄兰的儿子帕结，","notes":[]},{"n":28,"t":"他的军队被数的有四万一千五百名。","notes":[]},{"n":29,"t":"还有拿弗他利支派，拿弗他利人的领袖是以南的儿子亚希拉，","notes":[]},{"n":30,"t":"他的军队被数的有五万三千四百名。","notes":[]},{"n":31,"t":"凡属但营被数的共有十五万七千六百名；他们随着自己的旗帜行在最后。”","notes":[]},{"n":32,"t":"以上是以色列人按照各自的父家被数的，在诸营中按照各自的队伍被数的，共有六十万三千五百五十名。","notes":[]},{"n":33,"t":"但利未人没有数在以色列人中，正如耶和华所吩咐摩西的。","notes":[]},{"n":34,"t":"以色列人就照着耶和华所吩咐摩西的做了，在各自的旗帜下安营，随着各自的宗族、父家起行。","notes":[]}]},"3":{"heading":"亚伦的儿子","verses":[{"n":1,"t":"耶和华在西奈山与摩西说话的日子，亚伦和摩西的后代如下：","notes":[]},{"n":2,"t":"这些是亚伦儿子的名字，长子拿答，及亚比户、以利亚撒、以他玛。","notes":[]},{"n":3,"t":"这些是亚伦儿子的名字，都是受膏的祭司，是摩西授圣职使他们担任祭司职分的。","notes":[]},{"n":4,"t":"拿答、亚比户在西奈的旷野向耶和华献上凡火的时候，死在耶和华面前。他们没有儿子。以利亚撒和以他玛在他们的父亲亚伦面前担任祭司的职分。","notes":[]},{"n":5,"t":"耶和华吩咐摩西说：","notes":[],"heads":["利未人的职责"]},{"n":6,"t":"“你要带利未支派近前来，站在亚伦祭司面前伺候他。","notes":[]},{"n":7,"t":"他们要替他，又替全会众，在会幕前执行任务，办理帐幕的事。","notes":[]},{"n":8,"t":"他们要看守会幕一切的器具，为以色列人执行任务，办理帐幕的事。","notes":[]},{"n":9,"t":"你要把利未人给亚伦和他的儿子；他们是从以色列人中选出来完全给他的。","notes":[]},{"n":10,"t":"你要指派亚伦和他的儿子谨守祭司的职分；近前来的外人必被处死。”","notes":[]},{"n":11,"t":"耶和华吩咐摩西说：","notes":[]},{"n":12,"t":"“看哪，我从以色列人中选了利未人，代替以色列人中所有头胎的长子；利未人要归我。","notes":[]},{"n":13,"t":"因为凡头生的是我的；我在埃及地击杀所有头生的那日，就把以色列中所有头生的，无论是人或牲畜，都分别为圣归我；他们定要属我。我是耶和华。”","notes":[]},{"n":14,"t":"耶和华在西奈的旷野吩咐摩西说：","notes":[],"heads":["利未人的人口调查"]},{"n":15,"t":"“你要照父家、宗族计算利未人。凡一个月以上的男子都要数点。”","notes":[]},{"n":16,"t":"于是摩西遵照耶和华的吩咐，按所指示的数点他们。","notes":[]},{"n":17,"t":"利未儿子的名字是革顺、哥辖、米拉利。","notes":[]},{"n":18,"t":"按照宗族，革顺儿子的名字是立尼、示每。","notes":[]},{"n":19,"t":"按照宗族，哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛。","notes":[]},{"n":20,"t":"按照宗族，米拉利的儿子是抹利、母示。按照父家，这些都是利未人的宗族。","notes":[]},{"n":21,"t":"属革顺的有立尼族、示每族，他们是革顺人的宗族。","notes":[]},{"n":22,"t":"他们被数的，一个月以上所有男子的数目共有七千五百名。","notes":[]},{"n":23,"t":"这革顺人的宗族要在西边，在帐幕后面安营。","notes":[]},{"n":24,"t":"革顺人父家的领袖是拉伊勒的儿子以利雅萨。","notes":[]},{"n":25,"t":"革顺的子孙在会幕中要看守的是帐幕、罩棚、罩棚的盖、会幕的门帘、","notes":[]},{"n":26,"t":"帐幕和祭坛周围院子的帷幔和门帘，以及所有需用的绳子。","notes":[]},{"n":27,"t":"属哥辖的有暗兰族、以斯哈族、希伯伦族、乌薛族，他们是哥辖人的宗族。","notes":[]},{"n":28,"t":"一个月以上所有男子的数目共有八千六百名；他们负责看守圣所。","notes":["“八千六百”：七十士译本的一个抄本是“八千三百”。"]},{"n":29,"t":"哥辖子孙的宗族要在帐幕的南边安营。","notes":[]},{"n":30,"t":"哥辖人父家宗族的领袖是乌薛的儿子以利撒反。","notes":[]},{"n":31,"t":"他们要看守的是约柜、供桌、灯台、祭坛、香坛、祭司在圣所内用的器皿、帘子，与一切相关事奉的物件。","notes":[]},{"n":32,"t":"亚伦祭司的儿子以利亚撒是利未人众领袖的主管，他要监督那些负责看守圣所的人。","notes":[]},{"n":33,"t":"属米拉利的有抹利族、母示族，他们是米拉利的宗族。","notes":[]},{"n":34,"t":"他们被数的，一个月以上所有男子的数目共有六千二百名。","notes":[]},{"n":35,"t":"米拉利宗族的领袖是亚比亥的儿子苏列，他们要在帐幕的北边安营。","notes":[]},{"n":36,"t":"米拉利子孙的职分是看守帐幕的竖板、横木、柱子、带卯眼的座和一切的器具，就是一切相关事奉的物件，","notes":[]},{"n":37,"t":"以及院子四围的柱子、其上带卯眼的座、橛子和绳子。","notes":[]},{"n":38,"t":"在帐幕前东边，向日出的方向，安营的是摩西、亚伦和亚伦的儿子。他们负责看守圣所，是为以色列人看守的。近前来的外人必被处死。","notes":[]},{"n":39,"t":"凡被数的利未人，就是摩西、亚伦照耶和华所指示、按宗族所数的，一个月以上所有的男子共有二万二千名。","notes":[]},{"n":40,"t":"耶和华对摩西说：“你要数点以色列人中凡一个月以上头生的男子，登记他们的名字。","notes":[],"heads":["利未人代替长子"]},{"n":41,"t":"我是耶和华。你要拣选利未人归我，代替所有头生的以色列人，也取利未人的牲畜代替以色列人所有头生的牲畜。”","notes":[]},{"n":42,"t":"摩西就遵照耶和华所吩咐的，把所有以色列人头生的都数点了。","notes":[]},{"n":43,"t":"按人名的数目，凡一个月以上头生的男子共有二万二千二百七十三名。","notes":[]},{"n":44,"t":"耶和华吩咐摩西说：","notes":[]},{"n":45,"t":"“你要拣选利未人代替所有头生的以色列人，也要取利未人的牲畜代替以色列人的牲畜。利未人要归我，我是耶和华。","notes":[]},{"n":46,"t":"以色列人头生的男子比利未人多了二百七十三名，必须把他们赎出来；","notes":[]},{"n":47,"t":"按照人丁，照圣所的舍客勒，每人当付五舍客勒，一舍客勒是二十季拉。","notes":[]},{"n":48,"t":"你要把这些多出来的人的赎银交给亚伦和他的儿子。”","notes":[]},{"n":49,"t":"于是摩西从那被利未人所赎以外多出来的人取了赎银。","notes":[]},{"n":50,"t":"从头生的以色列人所取的银子，按照圣所的舍客勒，共计一千三百六十五舍客勒。","notes":[]},{"n":51,"t":"摩西遵照耶和华指示的话，把赎银交给亚伦和他的儿子，正如耶和华所吩咐的。","notes":[]}]},"4":{"heading":"哥辖的子孙","verses":[{"n":1,"t":"耶和华吩咐摩西和亚伦说：","notes":[]},{"n":2,"t":"“你要照宗族、父家计算利未人中哥辖子孙的人口，","notes":[]},{"n":3,"t":"就是从三十岁到五十岁，凡前来任职，在会幕里事奉的人。","notes":[]},{"n":4,"t":"这是哥辖子孙在会幕里有关至圣之物的职责。","notes":[]},{"n":5,"t":"“拔营的时候，亚伦和他儿子要进去，把遮掩的幔子取下，用它来遮盖法柜，","notes":[]},{"n":6,"t":"又用精美皮料盖在上面，铺上纯蓝色的布，再把杠穿上。","notes":[]},{"n":7,"t":"他们要用蓝色的布铺在供饼的桌上，将盘、碟，以及浇酒祭的杯和壶摆在上面；经常供的饼也要留在桌上。","notes":[]},{"n":8,"t":"他们要在这些东西的上面铺上朱红色的布，把精美皮料盖在上面，再把杠穿上。","notes":[]},{"n":9,"t":"他们要用蓝色的布遮盖供职用的灯台、灯台上的灯盏、灯剪、灯盘，以及所有盛油的器皿；","notes":[]},{"n":10,"t":"又要用精美皮料把灯台和灯台的一切器具包好，放在抬架上。","notes":[]},{"n":11,"t":"他们要用蓝色的布铺在金坛上，用精美皮料盖在上面，再把杠穿上。","notes":[]},{"n":12,"t":"要用蓝色的布把圣所供职用的一切器具包好，再用精美皮料盖在上面，放在抬架上。","notes":[]},{"n":13,"t":"他们要清理祭坛上的灰，用紫色的布铺在坛上；","notes":[]},{"n":14,"t":"又要把供职用的一切器具，就是祭坛一切的器具，火盆、肉叉、铲子和盘子，都摆在坛上，铺上精美皮料，再把杠穿上。","notes":[]},{"n":15,"t":"“拔营的时候，亚伦和他儿子把圣所和圣所一切的器具盖好之后，哥辖的子孙才好来抬，免得他们摸圣物而死；这是哥辖子孙在会幕里所当抬的。","notes":[]},{"n":16,"t":"“祭司亚伦的儿子以利亚撒所要照管的是点灯的油和香料，以及常献的素祭和膏油。他要照管整个帐幕和其中所有的，以及圣所和圣所的器具。”","notes":[]},{"n":17,"t":"耶和华吩咐摩西和亚伦说：","notes":[]},{"n":18,"t":"“你们不可使哥辖人宗族的这一支从利未人中剪除。","notes":[]},{"n":19,"t":"他们挨近至圣之物的时候，要向他们这样做，使他们存活，不致死亡；亚伦和他的儿子要进去，分派各人当做的，当抬的。","notes":[]},{"n":20,"t":"但是他们不可进去观看圣所的拆卸，免得死亡。”","notes":["“观看圣所的拆卸”：七十士译本是“观看圣物片刻”。"]},{"n":21,"t":"耶和华吩咐摩西说：","notes":[],"heads":["革顺的子孙"]},{"n":22,"t":"“你要照父家、宗族计算革顺子孙的人口；","notes":[]},{"n":23,"t":"从三十岁到五十岁，凡前来任职，在会幕里事奉的，都要数点。","notes":[]},{"n":24,"t":"这是革顺人宗族的职责，要做的事，要抬的东西如下：","notes":[]},{"n":25,"t":"他们要抬帐幕的幔子、会幕和会幕的盖、外层精美皮料的盖、会幕的门帘、","notes":[]},{"n":26,"t":"帐幕和祭坛周围院子的帷幔和门帘、绳子，以及所有需用的器具；一切与这些东西相关的事务，他们要尽职。","notes":[]},{"n":27,"t":"革顺人的子孙一切的事奉，就是所当抬的，所当做的，都要遵照亚伦和他儿子的指示；他们所当抬的，你们要派他们负责。","notes":[]},{"n":28,"t":"这是革顺人子孙的宗族在会幕里的事奉；他们要在亚伦祭司的儿子以他玛的手下尽职。”","notes":[]},{"n":29,"t":"“至于米拉利的子孙，你要照宗族、父家数点他们；","notes":[],"heads":["米拉利的子孙"]},{"n":30,"t":"从三十岁到五十岁，凡前来任职，在会幕里事奉的，你都要数点。","notes":[]},{"n":31,"t":"这是他们在会幕里的事奉，他们负责要抬的是帐幕的竖板、横木、柱子和带卯眼的座，","notes":[]},{"n":32,"t":"院子四围的柱子和其上带卯眼的座、橛子、绳子和一切的器具，与一切相关事奉的物件。你们要按名指定他们要抬的器具。","notes":[]},{"n":33,"t":"这是米拉利子孙的宗族在会幕里的事奉，都在亚伦祭司的儿子以他玛的手下。”","notes":[]},{"n":34,"t":"摩西、亚伦和会众的领袖按照宗族、父家数点哥辖人的子孙；","notes":[],"heads":["利未人男丁的调查"]},{"n":35,"t":"从三十岁到五十岁，凡前来任职，在会幕里事奉的，","notes":[]},{"n":36,"t":"按照宗族被数的共有二千七百五十名。","notes":[]},{"n":37,"t":"这是所有在会幕里事奉的哥辖人宗族中被数的，是摩西和亚伦遵照耶和华藉摩西所指示数点的。","notes":[]},{"n":38,"t":"革顺子孙被数的，按照宗族、父家，","notes":[]},{"n":39,"t":"从三十岁到五十岁，凡前来任职，在会幕里事奉的，","notes":[]},{"n":40,"t":"按照宗族、父家被数的共有二千六百三十名。","notes":[]},{"n":41,"t":"这是所有在会幕里事奉的革顺子孙宗族中被数的，是摩西和亚伦遵照耶和华的指示所数点的。","notes":[]},{"n":42,"t":"米拉利子孙宗族被数的，按照宗族、父家，","notes":[]},{"n":43,"t":"从三十岁到五十岁，凡前来任职，在会幕里事奉的，","notes":[]},{"n":44,"t":"按照宗族被数的共有三千二百名。","notes":[]},{"n":45,"t":"这是米拉利子孙宗族中被数的，是摩西和亚伦遵照耶和华藉摩西所指示数点的。","notes":[]},{"n":46,"t":"摩西、亚伦和以色列领袖按照宗族、父家数点利未人，","notes":[]},{"n":47,"t":"从三十岁到五十岁，凡前来任职，在会幕里事奉，做抬物之工的，","notes":[]},{"n":48,"t":"他们被数的共有八千五百八十名。","notes":[]},{"n":49,"t":"按照耶和华藉摩西所指示的来分派，各人都有自己所做的事、所抬的物；他们就这样被数点，正如耶和华所吩咐摩西的。","notes":[]}]},"5":{"heading":"不洁净的人","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人，把一切患麻风的、患漏症的和因尸体而不洁净的，都送到营外去。","notes":["“麻风”泛指传染性皮肤病。"]},{"n":3,"t":"无论男女你都要送，把他们送到营外，免得他们玷污了他们的营，这是我住在他们中间的地方。”","notes":[]},{"n":4,"t":"以色列人就照样做，把他们送到营外去。耶和华怎样吩咐摩西，以色列人就照样做了。","notes":[]},{"n":5,"t":"耶和华吩咐摩西说：","notes":[],"heads":["认罪和赔偿"]},{"n":6,"t":"“你要吩咐以色列人：无论男女，若犯了人所常犯的任何罪，以致干犯耶和华，那人就有了罪。","notes":["“若犯了人所常犯的任何罪”或译“若犯了任何亏负人的罪”。"]},{"n":7,"t":"他要承认所犯的罪，将所亏负人的如数赔偿，另外再加五分之一，交给所亏负的人。","notes":[]},{"n":8,"t":"那人若没有至亲可接受所赔偿的，所赔偿的就要归耶和华，交给祭司；另外还要献一只赎罪的公羊为他赎罪。","notes":[]},{"n":9,"t":"以色列人一切的圣物中，所奉给祭司的一切礼物都要归给祭司。","notes":[]},{"n":10,"t":"各人自己的圣物归自己，给祭司的要归给祭司。”","notes":[]},{"n":11,"t":"耶和华吩咐摩西说：","notes":[],"heads":["疑妻不贞的案件"]},{"n":12,"t":"“你要吩咐以色列人，对他们说：若任何人的妻子背离妇道，对丈夫不贞，","notes":[]},{"n":13,"t":"有人与她同寝交合，这事瞒过她的丈夫，没有被发现；她玷污自己，没有证人指控她，也没有被捉住；","notes":[]},{"n":14,"t":"丈夫若生了疑忌的心，对妻子起了疑忌，认为她玷污自己；或是丈夫生了疑忌的心，对妻子起了疑忌，虽然她没有玷污自己，","notes":[]},{"n":15,"t":"这人要带妻子到祭司那里，同时为她带十分之一伊法大麦面粉作供物。不可浇上油，也不可加乳香，因为这是疑忌的素祭，是纪念的素祭，使人记得罪孽。","notes":[]},{"n":16,"t":"“祭司要使那妇人近前来，站在耶和华面前。","notes":[]},{"n":17,"t":"祭司要把圣水盛在瓦器里，从帐幕的地上取些尘土，放在水中。","notes":[]},{"n":18,"t":"祭司要带那妇人站在耶和华面前，使她蓬头散发，再把纪念的素祭，就是疑忌的素祭，放在她的手掌，祭司手里捧着致诅咒的苦水。","notes":[]},{"n":19,"t":"祭司要叫妇人起誓，对她说：‘若没有人与你同寝，若你未曾背着丈夫做污秽的事，你就能免去这致诅咒的苦水。","notes":[]},{"n":20,"t":"但你背着丈夫，玷污自己，跟丈夫以外的人同寝。’","notes":[]},{"n":21,"t":"祭司叫妇人赌咒起誓，祭司对她说：‘当耶和华使你大腿萎缩，肚腹肿胀时，愿耶和华使你在你百姓中成为诅咒和咒骂；","notes":[]},{"n":22,"t":"愿这致诅咒的水进入你体内，使你肚腹肿胀，大腿萎缩。’妇人要说：‘阿们，阿们。’","notes":[]},{"n":23,"t":"“祭司要把这诅咒写在册上，然后用苦水涂去，","notes":[]},{"n":24,"t":"又叫妇人喝这致诅咒的苦水，这诅咒的水要进入她里面，令她痛苦。","notes":[]},{"n":25,"t":"祭司要从妇人手中取那疑忌的素祭，把素祭在耶和华面前摇一摇，拿到祭坛前；","notes":[]},{"n":26,"t":"又要从素祭中取出一把，作为纪念，烧在坛上，然后叫妇人喝这水。","notes":[]},{"n":27,"t":"祭司叫她喝了以后，她若玷污自己，确实对丈夫不贞，这致诅咒的水必进入她里面，令她痛苦，她的肚腹就要肿胀起来，大腿萎缩；这妇人就在她百姓中成为诅咒。","notes":[]},{"n":28,"t":"这妇人若没有玷污自己，是贞洁的，就要免受这灾，并且能够生育。","notes":[]},{"n":29,"t":"“这是疑忌的条例。妻子背离丈夫玷污自己，","notes":[]},{"n":30,"t":"或是丈夫生了疑忌的心，对妻子起了疑忌，祭司要使那妇人站在耶和华面前，在她身上照这条例而行。","notes":[]},{"n":31,"t":"男人可免罪责；女人必须担当自己的罪孽。”","notes":[]}]},"6":{"heading":"拿细耳人的条例","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人，对他们说：无论男女，若许了特别的愿，就是拿细耳人的愿，愿意离俗归耶和华，","notes":[]},{"n":3,"t":"他就要远离清酒烈酒，也不可喝任何清酒烈酒做的醋；不可喝任何葡萄汁，也不可吃鲜葡萄和干葡萄。","notes":[]},{"n":4,"t":"在一切离俗的日子，任何葡萄树上所结的，甚至果核和果皮，都不可吃。","notes":[]},{"n":5,"t":"“在他一切许愿离俗的日子，不可用剃刀剃头。在离俗归耶和华的日子未满之前，他要成为圣，要任由头上的发绺生长。","notes":[]},{"n":6,"t":"在他一切离俗归耶和华的日子，不可挨近死尸。","notes":[]},{"n":7,"t":"即使他的父母或兄弟姊妹死了，他也不可因他们使自己不洁净，因为他头上有离俗归神的记号 。","notes":["原文没有“记号”。"]},{"n":8,"t":"在他一切离俗的日子，他是归耶和华为圣的。","notes":[]},{"n":9,"t":"“若在他旁边忽然有人死了，因而玷污了他离俗的头，他要在第七日，得洁净的日子剃头。","notes":[]},{"n":10,"t":"第八日，他要把两只斑鸠或两只雏鸽带到会幕门口，交给祭司。","notes":[]},{"n":11,"t":"祭司要献一只作赎罪祭，一只作燔祭，为他赎因尸体而有的罪，并要在当日使他的头分别为圣。","notes":[]},{"n":12,"t":"他要另选离俗归耶和华的日子，牵一只一岁的小公羊来作赎愆祭。先前的那段日子算为无效，因为他在离俗期间被玷污了。","notes":[]},{"n":13,"t":"“拿细耳人的条例是这样的：离俗的日子满了，祭司要领他到会幕门口，","notes":[]},{"n":14,"t":"他要将供物献给耶和华，就是一只没有残疾的一岁小公羊作燔祭，一只没有残疾的一岁小母羊作赎罪祭，和一只没有残疾的公绵羊作平安祭，","notes":[]},{"n":15,"t":"一篮用油调和的无酵细面饼和抹了油的无酵薄饼，以及同献的素祭和浇酒祭。","notes":[]},{"n":16,"t":"祭司要来到耶和华面前，献上那人的赎罪祭和燔祭。","notes":[]},{"n":17,"t":"祭司要把公绵羊和那篮无酵饼献给耶和华作平安祭，又要献上同献的素祭和浇酒祭。","notes":[]},{"n":18,"t":"拿细耳人要在会幕门口剃离俗的头，把离俗头上的发放在平安祭下的火上。","notes":[]},{"n":19,"t":"他剃了离俗的头以后，祭司要取那煮好的公绵羊的一条前腿，连同篮子里的一块无酵饼和一块无酵薄饼，放在他手掌上。","notes":[]},{"n":20,"t":"祭司要拿这些在耶和华面前摇一摇，作为摇祭；这和所摇的胸、所举的腿一样是圣物，是归给祭司的。然后拿细耳人才可以喝酒。","notes":[]},{"n":21,"t":"“这是拿细耳人许愿的条例，除了他手头财力所及之外，他要为离俗献供物给耶和华。他怎样许愿，就当照离俗的条例做。”","notes":[]},{"n":22,"t":"耶和华吩咐摩西说：","notes":[],"heads":["祭司的祝福"]},{"n":23,"t":"“你要吩咐亚伦和他儿子说：你们要这样为以色列人祝福，对他们说：","notes":[]},{"n":24,"t":"‘愿耶和华赐福给你，保护你。","notes":[]},{"n":25,"t":"愿耶和华使他的脸光照你，赐恩给你。","notes":[]},{"n":26,"t":"愿耶和华向你仰脸，赐你平安。’","notes":[]},{"n":27,"t":"“他们要如此奉我的名为以色列人祝福；我也要赐福给他们。”","notes":[]}]},"7":{"heading":"各族长的奉献","verses":[{"n":1,"t":"摩西竖立帐幕后，就用膏抹了帐幕，使它分别为圣，又用膏抹其中的一切器具，以及祭坛和坛上的一切器具，使它们分别为圣。","notes":[]},{"n":2,"t":"以色列的领袖，各父家的家长，都前来奉献。他们是各支派的领袖，管理那些被数的人。","notes":[]},{"n":3,"t":"他们把自己的供物送到耶和华面前，就是六辆篷车和十二头公牛。每两个领袖奉献一辆车，每个领袖奉献一头牛。他们把这些都带到帐幕前。","notes":[]},{"n":4,"t":"耶和华对摩西说：","notes":[]},{"n":5,"t":"“你要从他们收下这些，作为会幕事奉的用途，照着利未人所事奉的交给他们各人。”","notes":[]},{"n":6,"t":"于是摩西收了车和牛，交给利未人。","notes":[]},{"n":7,"t":"他把两辆车和四头牛，照着革顺子孙所事奉的交给他们，","notes":[]},{"n":8,"t":"又把四辆车和八头牛，照着米拉利子孙所事奉的交给他们。他们都在亚伦祭司的儿子以他玛的手下。","notes":[]},{"n":9,"t":"但没有交给哥辖子孙任何东西，因为他们所事奉的是圣物，必须抬在肩头上。","notes":[]},{"n":10,"t":"用膏抹祭坛的那一天，众领袖前来为献坛奉献；众领袖都在祭坛前献供物。","notes":[]},{"n":11,"t":"耶和华对摩西说：“众领袖为献坛奉献供物，每天要有一个领袖前来奉献。”","notes":[]},{"n":12,"t":"第一天献供物的是犹大支派的亚米拿达的儿子拿顺。","notes":[]},{"n":13,"t":"他的供物是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":14,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":15,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":16,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":17,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是亚米拿达的儿子拿顺的供物。","notes":[]},{"n":18,"t":"第二天来献的是以萨迦的领袖，苏押的儿子拿坦业。","notes":[]},{"n":19,"t":"他献为供物的是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":20,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":21,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":22,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":23,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是苏押的儿子拿坦业的供物。","notes":[]},{"n":24,"t":"第三天是西布伦子孙的领袖，希伦的儿子以利押。","notes":[]},{"n":25,"t":"他的供物是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":26,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":27,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":28,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":29,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是希伦的儿子以利押的供物。","notes":[]},{"n":30,"t":"第四天是吕便子孙的领袖，示丢珥的儿子以利蓿。","notes":[]},{"n":31,"t":"他的供物是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":32,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":33,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":34,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":35,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是示丢珥的儿子以利蓿的供物。","notes":[]},{"n":36,"t":"第五天是西缅子孙的领袖，苏利沙代的儿子示路蔑。","notes":[]},{"n":37,"t":"他的供物是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":38,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":39,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":40,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":41,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是苏利沙代的儿子示路蔑的供物。","notes":[]},{"n":42,"t":"第六天是迦得子孙的领袖，丢珥的儿子以利雅萨。","notes":[]},{"n":43,"t":"他的供物是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":44,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":45,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":46,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":47,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是丢珥的儿子以利雅萨的供物。","notes":[]},{"n":48,"t":"第七天是以法莲子孙的领袖，亚米忽的儿子以利沙玛。","notes":[]},{"n":49,"t":"他的供物是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":50,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":51,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":52,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":53,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是亚米忽的儿子以利沙玛的供物。","notes":[]},{"n":54,"t":"第八天是玛拿西子孙的领袖，比大蓿的儿子迦玛列。","notes":[]},{"n":55,"t":"他的供物是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":56,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":57,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":58,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":59,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是比大蓿的儿子迦玛列的供物。","notes":[]},{"n":60,"t":"第九天是便雅悯子孙的领袖，基多尼的儿子亚比但。","notes":[]},{"n":61,"t":"他的供物是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":62,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":63,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":64,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":65,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是基多尼的儿子亚比但的供物。","notes":[]},{"n":66,"t":"第十天是但子孙的领袖，亚米沙代的儿子亚希以谢。","notes":[]},{"n":67,"t":"他的供物是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":68,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":69,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":70,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":71,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是亚米沙代的儿子亚希以谢的供物。","notes":[]},{"n":72,"t":"第十一天是亚设子孙的领袖，俄兰的儿子帕结。","notes":[]},{"n":73,"t":"他的供物是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":74,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":75,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":76,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":77,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是俄兰的儿子帕结的供物。","notes":[]},{"n":78,"t":"第十二天是拿弗他利子孙的领袖，以南儿子亚希拉。","notes":[]},{"n":79,"t":"他的供物是：一个重一百三十舍客勒的银盘，一个重七十舍客勒的银碗，都是按照圣所的舍客勒，里面盛满了调油的细面作素祭；","notes":[]},{"n":80,"t":"一个重十舍客勒的金碟子，盛满了香；","notes":[]},{"n":81,"t":"一头公牛犊、一只公绵羊、一只一岁的小公羊作燔祭；","notes":[]},{"n":82,"t":"一只公山羊作赎罪祭；","notes":[]},{"n":83,"t":"两头公牛、五只公绵羊、五只公山羊、五只一岁的小公羊作平安祭。这是以南的儿子亚希拉的供物。","notes":[]},{"n":84,"t":"用膏抹祭坛的那一天，以色列的众领袖为献坛所献的是：银盘十二个、银碗十二个、金碟子十二个；","notes":[]},{"n":85,"t":"一个银盘重一百三十，一个碗七十。一切器皿的银子，按照圣所的舍客勒共二千四百舍客勒。","notes":[]},{"n":86,"t":"十二个金碟子盛满了香，按照圣所的舍客勒，一个碟子重十舍客勒，所有碟子的金子共一百二十舍客勒。","notes":[]},{"n":87,"t":"作燔祭的共有公牛十二头、公羊十二只、一岁的小公羊十二只，和同献的素祭，以及作赎罪祭的公山羊十二只；","notes":[]},{"n":88,"t":"作平安祭的共有公牛二十四头、公绵羊六十只、公山羊六十只、一岁的小公羊六十只。这就是用膏抹坛之后，为献坛的奉献。","notes":[]},{"n":89,"t":"摩西进会幕要与耶和华说话的时候，听见法柜的柜盖以上二基路伯中间有对他说话的声音。耶和华向他说话。","notes":[]}]},"8":{"heading":"七盏灯","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐亚伦，对他说：点灯的时候，七盏灯都要照亮灯台前面。”","notes":[]},{"n":3,"t":"亚伦就照样做了；他点灯，照亮了灯台前面，正如耶和华所吩咐摩西的。","notes":[]},{"n":4,"t":"灯台是这样造的：灯台是用金子锤出来的，连座带花都是锤出来的。摩西照着耶和华所指示的样式造了灯台。","notes":[]},{"n":5,"t":"耶和华吩咐摩西说：","notes":[],"heads":["利未人的洁净礼和奉献礼"]},{"n":6,"t":"“你要从以色列人中选出利未人来，洁净他们。","notes":[]},{"n":7,"t":"你要这样做来洁净他们：要用洁净的水弹在他们身上，又叫他们用剃刀剃刮全身，洗净衣服，洁净自己。","notes":[]},{"n":8,"t":"然后他们要取一头公牛犊，以及同献的素祭，就是调油的细面。你要另取一头公牛犊作赎罪祭。","notes":[]},{"n":9,"t":"你要带利未人到会幕前，并且要召集以色列全会众。","notes":[]},{"n":10,"t":"你要把利未人带到耶和华面前，以色列人要为利未人按手。","notes":[]},{"n":11,"t":"亚伦要从以色列人中将利未人奉献在耶和华面前，作为摇祭，使他们事奉耶和华。","notes":["“奉献”：原文直译“摇一摇”；下同。"]},{"n":12,"t":"利未人要按手在那两头牛的头上；你要将一头作赎罪祭，一头作燔祭，献给耶和华，为利未人赎罪。","notes":[]},{"n":13,"t":"你也要使利未人站在亚伦和他儿子面前，将他们奉献给耶和华，作为摇祭。","notes":[]},{"n":14,"t":"“你从以色列人中将利未人分别出来，利未人就归我了。","notes":[]},{"n":15,"t":"你洁净了利未人，奉献他们作为摇祭之后，他们就可以进会幕事奉。","notes":[]},{"n":16,"t":"因为他们是从以色列人中全然献给我的；我选他们归我，代替以色列人中所有头胎的长子。","notes":[]},{"n":17,"t":"因为以色列人中凡头生的，无论是人或牲畜，都是我的。我在埃及地击杀所有头生的那日，已将他们分别为圣归我。","notes":[]},{"n":18,"t":"我选利未人代替以色列人中所有头生的。","notes":[]},{"n":19,"t":"我从以色列人中将利未人给亚伦和他的儿子作为赏赐，在会幕中为以色列人事奉，又为以色列人赎罪，免得以色列人因挨近圣所而遭受灾祸。”","notes":[]},{"n":20,"t":"摩西、亚伦和以色列全会众就向利未人这样做。关于利未人，凡耶和华怎样吩咐摩西，以色列人就向他们照样做了。","notes":[]},{"n":21,"t":"于是利未人从罪中洁净自己，洗净衣服。亚伦将他们奉献在耶和华面前，作为摇祭，又为他们赎罪，洁净他们。","notes":[]},{"n":22,"t":"然后利未人进去，在亚伦和他儿子面前，在会幕中事奉。关于利未人，耶和华怎样吩咐摩西，他们就向利未人照样做了。","notes":[]},{"n":23,"t":"耶和华吩咐摩西说：","notes":[]},{"n":24,"t":"“这是有关利未人的：二十五岁以上的人都要前来任职，在会幕里事奉。","notes":[]},{"n":25,"t":"到了五十岁，他们就要从事奉的工作中退休，不再事奉，","notes":[]},{"n":26,"t":"只可在会幕里辅助他们的弟兄尽责，他们自己不再事奉了。关于利未人的职责，你要向他们这样做。”","notes":[]}]},"9":{"heading":"在西奈山守逾越节","verses":[{"n":1,"t":"以色列人出埃及地以后，第二年正月，耶和华在西奈的旷野吩咐摩西说：","notes":[]},{"n":2,"t":"“以色列人应当在所定的日期守逾越节。","notes":[]},{"n":3,"t":"你们要在本月十四日黄昏的时候，在所定的日期守这节，按照一切的律例典章守节。”","notes":["“黄昏的时候”：原文是“两个黄昏之间”；下同。"]},{"n":4,"t":"于是摩西吩咐以色列人守逾越节。","notes":[]},{"n":5,"t":"正月十四日黄昏的时候，他们就在西奈的旷野守逾越节。凡耶和华所吩咐摩西的，以色列人都照样做了。","notes":[]},{"n":6,"t":"有几个人因尸体成了不洁净，不能在那日守逾越节。当天他们到摩西、亚伦面前。","notes":[]},{"n":7,"t":"那些人对他说：“我们因尸体而不洁净，为何禁止我们，不能和以色列人在所定的日期献供物给耶和华呢？”","notes":[]},{"n":8,"t":"摩西对他们说：“你们稍等，让我去听耶和华对你们有什么吩咐。”","notes":[]},{"n":9,"t":"耶和华吩咐摩西说：","notes":[]},{"n":10,"t":"“你要吩咐以色列人说：你们和你们后代中，若有人因尸体成了不洁净，或出外远行，仍然要向耶和华守逾越节，","notes":[]},{"n":11,"t":"他们就要在二月十四日黄昏的时候守节，要吃羔羊，以及无酵饼和苦菜。","notes":[]},{"n":12,"t":"他们不可留一点食物到早晨；羔羊的骨头一根也不可折断。他们要照逾越节的一切律例守这节。","notes":[]},{"n":13,"t":"但洁净又不出外远行的人若不守逾越节，那人要从百姓中剪除，因为他没有在所定的日期献供物给耶和华，必须担当自己的罪。","notes":[]},{"n":14,"t":"若有寄居在你们那里的外人要向耶和华守逾越节，他要照逾越节的律例和典章做。无论是寄居的或是本地人，都用同样的律例。”","notes":[]},{"n":15,"t":"立起帐幕的那日，有云彩遮盖帐幕，就是法柜的帐幕；从晚上到早晨，云彩在帐幕上，形状如火。","notes":[],"heads":["云彩遮盖帐幕"]},{"n":16,"t":"经常都是这样：云彩遮盖帐幕，夜间云彩形状如火。","notes":[]},{"n":17,"t":"云彩几时从帐幕上升，以色列人就几时起行；云彩在哪里停住，以色列人就在哪里安营。","notes":[]},{"n":18,"t":"以色列人遵照耶和华的指示起行，也遵照耶和华的指示安营。云彩在帐幕上停留多久，他们就留在营里多久。","notes":[]},{"n":19,"t":"云彩在帐幕上停留许多日子，以色列人就遵照耶和华的吩咐不起行。","notes":[]},{"n":20,"t":"有时云彩在帐幕上只停了几天，他们就遵照耶和华的指示留在营里，也遵照耶和华的指示起行。","notes":[]},{"n":21,"t":"有时云彩从晚上留到早晨；早晨云彩上升，他们就起行。无论是白天是黑夜，当云彩上升的时候，他们就要起行。","notes":[]},{"n":22,"t":"云彩停留在帐幕上，无论是两天，一个月，或更长的日子，以色列人就留在营里不起行；但云彩一上升，他们就起行。","notes":[]},{"n":23,"t":"他们遵照耶和华的指示安营，也遵照耶和华的指示起行。他们遵守耶和华的吩咐，是耶和华藉摩西所指示的话。","notes":[]}]},"10":{"heading":"银号筒","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要用银子做两枝号筒，把它们锤出来，给你用来召集会众，拔营起行。","notes":[]},{"n":3,"t":"吹号的时候，全会众要到你那里，聚集在会幕的门口。","notes":[]},{"n":4,"t":"若只吹一枝，众领袖，就是以色列部队的官长，要到你那里聚集。","notes":[]},{"n":5,"t":"你们大声吹号的时候，东边安营的要起行。","notes":[]},{"n":6,"t":"第二次大声吹号的时候，南边安营的要起行。起行的时候，要大声吹号；","notes":[]},{"n":7,"t":"但召集会众的时候，你们要吹号，却不要吹出大声。","notes":[]},{"n":8,"t":"亚伦子孙作祭司的要吹这号筒，作为你们世世代代永远的定例。","notes":[]},{"n":9,"t":"当你们在自己的土地上，与欺压你们的敌人打仗时，要用号筒吹出大声。你们就在耶和华－你们的神面前得蒙记念，也必蒙拯救脱离仇敌。","notes":[]},{"n":10,"t":"在快乐的日子，节期和初一，献燔祭与平安祭的时候，你们要吹号筒，在你们的神面前作为纪念。我是耶和华－你们的神。”","notes":[]},{"n":11,"t":"第二年二月二十日，云彩从法柜的帐幕上升。","notes":[],"heads":["离开西奈山"]},{"n":12,"t":"以色列人离开西奈的旷野，一段一段地往前行，云彩停在巴兰的旷野。","notes":[]},{"n":13,"t":"他们遵照耶和华藉摩西所指示的，初次往前行。","notes":[]},{"n":14,"t":"按照队伍首先起行的是犹大营旗帜下的人，带队的是亚米拿达的儿子拿顺。","notes":[]},{"n":15,"t":"以萨迦支派带队的是苏押的儿子拿坦业。","notes":[]},{"n":16,"t":"西布伦支派带队的是希伦的儿子以利押。","notes":[]},{"n":17,"t":"帐幕拆卸了，革顺的子孙和米拉利的子孙就抬着帐幕往前行。","notes":[]},{"n":18,"t":"按照队伍往前行的是吕便营旗帜下的人，带队的是示丢珥的儿子以利蓿。","notes":[]},{"n":19,"t":"西缅支派带队的是苏利沙代的儿子示路蔑。","notes":[]},{"n":20,"t":"迦得支派带队的是丢珥的儿子以利雅萨。","notes":[]},{"n":21,"t":"哥辖人抬着圣物往前行。他们未到以前，帐幕已经立好了。","notes":[]},{"n":22,"t":"按照队伍往前行的是以法莲营旗帜下的人，带队的是亚米忽的儿子以利沙玛。","notes":[]},{"n":23,"t":"玛拿西支派带队的是比大蓿的儿子迦玛列。","notes":[]},{"n":24,"t":"便雅悯支派带队的是基多尼的儿子亚比但。","notes":[]},{"n":25,"t":"作全营后卫，按队伍往前行的是但营旗帜下的人，带队的是亚米沙代的儿子亚希以谢。","notes":[]},{"n":26,"t":"亚设支派带队的是俄兰的儿子帕结。","notes":[]},{"n":27,"t":"拿弗他利支派带队的是以南的儿子亚希拉。","notes":[]},{"n":28,"t":"以色列人就这样按着队伍往前行。","notes":[]},{"n":29,"t":"摩西对他岳父米甸人流珥的儿子何巴说：“我们要往前行，到耶和华所说的地方；他曾说：‘我要将这地赐给你们。’现在请你和我们同去，我们必善待你，因为耶和华已经应许赐福气给以色列人。”","notes":["“岳父”或译“内兄”。"]},{"n":30,"t":"何巴对他说：“我不去，我要回本地本族去。”","notes":[]},{"n":31,"t":"摩西说：“请你不要离开我们，因为你知道我们要在旷野安营，你可以当我们的眼目。","notes":[]},{"n":32,"t":"你若和我们同去，将来耶和华以什么福气恩待我们，我们也必这样善待你。”","notes":[]},{"n":33,"t":"以色列人离开耶和华的山，往前行了三天的路程。耶和华的约柜在前面行了三天的路程，为他们寻找安歇的地方。","notes":[],"heads":["约柜和百姓往前行"]},{"n":34,"t":"他们拔营往前行，日间有耶和华的云彩在他们上面。","notes":[]},{"n":35,"t":"约柜往前行的时候，摩西说：“耶和华啊，求你兴起！愿你的仇敌溃散！愿恨你的人从你面前逃跑！”","notes":[]},{"n":36,"t":"约柜停住的时候，他说：“以色列千万人的耶和华啊，求你回来！”","notes":["“以色列...回来”或译“耶和华啊，求你回到以色列的千万人中”。"]}]},"11":{"heading":"在旷野发怨言","verses":[{"n":1,"t":"百姓发怨言，恶言传达到耶和华的耳中。耶和华听见了就怒气发作，耶和华的火在他们中间焚烧，烧毁营的外围。","notes":[]},{"n":2,"t":"百姓向摩西哀求，摩西祈求耶和华，火就熄了。","notes":[]},{"n":3,"t":"那地方就叫做他备拉，因为耶和华的火曾在他们中间焚烧。","notes":[]},{"n":4,"t":"他们中间的闲杂人动了贪欲的心；以色列人又再哭着说：“谁给我们肉吃呢？","notes":[]},{"n":5,"t":"我们记得在埃及的时候，不花钱就可以吃鱼，还有黄瓜、西瓜、韭菜、葱、蒜。","notes":[]},{"n":6,"t":"现在我们的精力枯干了。除了这吗哪以外，在我们眼前什么都没有。”","notes":[]},{"n":7,"t":"吗哪好像芫荽子，看上去如同树脂的样子。","notes":[]},{"n":8,"t":"百姓四处走动捡取吗哪，把它用磨磨碎或用臼捣成粉，在锅中煮了做成饼，滋味好像油烤饼的滋味。","notes":[]},{"n":9,"t":"夜间露水降在营中，吗哪也随着降下。","notes":[]},{"n":10,"t":"摩西听见百姓家家户户在帐棚门口哀哭。因此， 耶和华的怒气大大发作，摩西看了也不高兴。","notes":[]},{"n":11,"t":"摩西对耶和华说：“你为何苦待仆人？我为何不在你眼前蒙恩，竟把这众百姓的担子加在我身上呢？","notes":[]},{"n":12,"t":"这众百姓岂是我怀的胎，岂是我生下来的呢？你竟对我说：‘把他们抱在怀里，如养育之父抱着吃奶的婴孩，一直抱到你起誓应许给他们祖宗的土地去。’","notes":[]},{"n":13,"t":"我从哪里拿肉给这众百姓吃呢？他们都向我哭着说：‘给我们肉吃！’","notes":[]},{"n":14,"t":"我不能独自带领这众百姓，这对我太沉重了。","notes":[]},{"n":15,"t":"如果你这样待我，倒不如立刻把我杀了吧！我若在你眼前蒙恩，求你不要让我再受这样的苦。”","notes":[]},{"n":16,"t":"耶和华对摩西说：“你要从以色列的长老中为我召集七十个人，就是你所认识，作百姓的长老和官长的，领他们到会幕，使他们和你一同站在那里。","notes":[],"heads":["七十个长老"]},{"n":17,"t":"我要在那里降临，与你说话，把降给你的灵分给他们。他们就和你分担带领百姓的担子，免得你独自承担。","notes":[]},{"n":18,"t":"你要对百姓说：‘你们要为了明天使自己分别为圣，你们将有肉吃。因你们哭着说：谁给我们肉吃呢？我们在埃及多么好！这声音传到了耶和华的耳中，所以他必给你们肉吃。","notes":[]},{"n":19,"t":"你们不只吃一天、两天、五天、十天、二十天，","notes":[]},{"n":20,"t":"而是整整一个月，直到肉从你们的鼻孔喷出来，使你们厌恶。因为你们厌弃那住在你们中间的耶和华，在他面前哭着说：我们为何出埃及呢？’”","notes":[]},{"n":21,"t":"摩西说：“跟我在一起的百姓，步行的男人就有六十万，你还说：‘我要把肉赐给他们，使他们可以整整吃一个月。’","notes":[]},{"n":22,"t":"难道宰了羊群牛群，就够给他们吗？或者把海中所有的鱼都捕来，就够给他们吗？”","notes":[]},{"n":23,"t":"耶和华对摩西说：“耶和华的膀臂岂是缩短了吗？现在你要看我的话向你应验不应验。”","notes":["“膀臂”：原文是“手”。"]},{"n":24,"t":"摩西出去，把耶和华的话告诉百姓，并从百姓的长老中召集七十个人来，叫他们站在会幕的四围。","notes":[]},{"n":25,"t":"耶和华在云中降临，对摩西说话，把降给他的灵分给那七十个长老。灵停在他们身上的时候，他们就说预言，以后却没有再说了。","notes":[]},{"n":26,"t":"但有两个人仍在营里，一个名叫伊利达，一个名叫米达。他们本是在那些登记的人中，却没有到会幕那里去。灵停在他们身上，他们就在营里说预言。","notes":[]},{"n":27,"t":"有一个年轻人跑来告诉摩西说：“伊利达和米达在营里说预言。”","notes":[]},{"n":28,"t":"嫩的儿子约书亚，年轻时就作摩西的助手，说：“请我主摩西禁止他们。”","notes":["“年轻时...助手”：七十士译本是“被选辅助摩西的那人”。"]},{"n":29,"t":"摩西对他说：“你为我的缘故嫉妒吗？惟愿耶和华的百姓都是先知，愿耶和华把他的灵降在他们身上！”","notes":[]},{"n":30,"t":"于是，摩西回到营里去，以色列的长老也回去了。","notes":[]},{"n":31,"t":"有一阵风从耶和华那里刮起，把鹌鹑从海上刮来，散落在营地和周围；一边约有一天的路程，另一边也约有一天的路程，离地面约有二肘。","notes":[],"heads":["鹌鹑"]},{"n":32,"t":"百姓起来，整天整夜，甚至次日一整天，都在捕捉鹌鹑。每人至少捉到十贺梅珥，各自摆在营的四围。","notes":[]},{"n":33,"t":"但肉在他们牙间还未咀嚼时，耶和华的怒气向百姓发作，用极重的灾祸击杀百姓。","notes":[]},{"n":34,"t":"那地方就叫基博罗．哈他瓦 ，因为他们在那里埋葬了贪欲的百姓。","notes":["“基博罗．哈他瓦”意思是“贪欲之人的坟墓”。"]},{"n":35,"t":"百姓从基博罗．哈他瓦起程，到哈洗录，就住在哈洗录。","notes":[]}]},"12":{"heading":"米利暗和亚伦批评摩西","verses":[{"n":1,"t":"摩西娶了古实女子为妻。米利暗和亚伦因他娶了古实女子就批评他，","notes":[]},{"n":2,"t":"他们说：“难道耶和华只与摩西说话吗？他不也与我们说话吗？”耶和华听见了。","notes":[]},{"n":3,"t":"摩西为人极其谦和，胜过地面上的任何人。","notes":[]},{"n":4,"t":"忽然，耶和华对摩西、亚伦和米利暗说：“你们三个人都出来，到会幕这里。”他们三个人就出来了。","notes":[]},{"n":5,"t":"耶和华在云柱中降临，停在会幕门口，叫亚伦和米利暗。二人就出来，","notes":[]},{"n":6,"t":"耶和华说：“你们要听我的话：你们中间若有先知，我－耶和华必在异象中向他显现，在梦中与他说话；","notes":[]},{"n":7,"t":"但我的仆人摩西不是这样，他在我全家是尽忠的。","notes":[]},{"n":8,"t":"我与他面对面说话，清清楚楚，不用谜语，他甚至看见我的形像。你们为何批评我的仆人摩西而不惧怕呢？”","notes":[]},{"n":9,"t":"耶和华向他们怒气发作，就离开了。","notes":[]},{"n":10,"t":"当云彩从帐幕上离开时，看哪，米利暗长了麻风，像雪那么白。亚伦转向米利暗，看哪，她长了麻风。","notes":[]},{"n":11,"t":"亚伦对摩西说：“我主啊，求你不要因我们愚昧，因我们犯罪，就将这罪加在我们身上。","notes":[]},{"n":12,"t":"求你不要使她像那一出母腹、肉已侵蚀了一半的死胎。”","notes":[]},{"n":13,"t":"于是摩西哀求耶和华说：“神啊，求你医治她！”","notes":[]},{"n":14,"t":"耶和华对摩西说：“她父亲若吐唾沫在她脸上，她岂不蒙羞七天吗？现在要把她隔离在营外七天，然后才领她回来。”","notes":[]},{"n":15,"t":"于是米利暗被隔离在营外七天；百姓没有起程，直等到米利暗回来。","notes":[]},{"n":16,"t":"以后百姓从哈洗录起行，来到巴兰的旷野安营。","notes":[]}]},"13":{"heading":"派遣探子进迦南","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要派人去窥探我所赐给以色列人的迦南地；每个父系支派要派一个人，是他们中间的族长。”","notes":[]},{"n":3,"t":"摩西就遵照耶和华的指示，从巴兰旷野差派他们去；他们都是以色列人中的领袖。","notes":[]},{"n":4,"t":"这是他们的名字：属吕便支派的，撒刻的儿子沙母亚。","notes":[]},{"n":5,"t":"属西缅支派的，何利的儿子沙法。","notes":[]},{"n":6,"t":"属犹大支派的，耶孚尼的儿子迦勒。","notes":[]},{"n":7,"t":"属以萨迦支派的，约色的儿子以迦。","notes":[]},{"n":8,"t":"属以法莲支派的，嫩的儿子何西阿。","notes":["“何西阿”和何西阿先知同名；下同。"]},{"n":9,"t":"属便雅悯支派的，拉孚的儿子帕提。","notes":[]},{"n":10,"t":"属西布伦支派的，梭底的儿子迦叠。","notes":[]},{"n":11,"t":"属约瑟支派，就是玛拿西支派的，稣西的儿子迦底。","notes":[]},{"n":12,"t":"属但支派的，基玛利的儿子亚米利。","notes":[]},{"n":13,"t":"属亚设支派的，米迦勒的儿子西帖。","notes":[]},{"n":14,"t":"属拿弗他利支派的，缚西的儿子拿比。","notes":[]},{"n":15,"t":"属迦得支派的，玛基的儿子臼利。","notes":[]},{"n":16,"t":"这些是摩西差派去窥探那地之人的名字。摩西叫嫩的儿子何西阿为约书亚。","notes":[]},{"n":17,"t":"摩西差派他们去窥探迦南地，对他们说：“你们上到尼革夫那里，上到山区去，","notes":["“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”；本卷书下同。"]},{"n":18,"t":"看看那地如何：住那里的百姓是强是弱，是多是少，","notes":[]},{"n":19,"t":"他们所住的地是好是坏，所住的城镇是营地还是堡垒，","notes":[]},{"n":20,"t":"那地是肥沃还是贫瘠，当中有树木没有。你们要放胆，把那地的果子带些回来。”那时正是葡萄初熟的季节。","notes":[]},{"n":21,"t":"他们上去窥探那地，从寻的旷野到利合，直到哈马口。","notes":[]},{"n":22,"t":"他们从尼革夫上去，到了希伯仑。在那里有亚衲族的亚希幔人、示筛人和挞买人。希伯仑的建造比埃及的琐安早七年。","notes":[]},{"n":23,"t":"他们到了以实各谷，从那里砍下葡萄树枝，上面有一挂葡萄，两个人用杠抬着，又带了一些石榴和无花果。","notes":[]},{"n":24,"t":"以色列人从那里砍下一挂葡萄，所以那地方就叫以实各谷。","notes":[]},{"n":25,"t":"他们窥探那地四十天之后，就回来了。","notes":[],"heads":["探子的报告"]},{"n":26,"t":"他们来到巴兰旷野的加低斯，摩西、亚伦，以及以色列全会众那里，向他们和全会众报告，又把那地的果子给他们看。","notes":[]},{"n":27,"t":"他们告诉摩西说：“我们到了你派我们去的那地，果然是流奶与蜜之地；这就是那地的果子。","notes":[]},{"n":28,"t":"但是住那地的百姓很强悍，城镇又大又坚固，我们也在那里看见了亚衲族人。","notes":[]},{"n":29,"t":"亚玛力人住在尼革夫；赫人、耶布斯人和亚摩利人住在山区；迦南人住在沿海一带和约旦河旁。”","notes":[]},{"n":30,"t":"迦勒在摩西面前安抚百姓，说：“我们立刻上去得那地吧！我们必能征服它。”","notes":[]},{"n":31,"t":"但那些和他同去的人却说：“我们不能上去攻打那些百姓，因为他们比我们强大。”","notes":[]},{"n":32,"t":"于是探子中有人向以色列人散布有关所窥探之地的谣言，说：“我们所走过、所窥探之地是吞没居民之地，并且我们在那里所看见的百姓都身材高大。","notes":[]},{"n":33,"t":"我们在那里看见巨人，就是巨人中的亚衲族人。我们在自己眼中像蚱蜢一样，而在他们眼中，我们也确是这样。”","notes":[]}]},"14":{"heading":"以色列人抱怨","verses":[{"n":1,"t":"全会众大声喧嚷，那夜百姓哭号。","notes":[]},{"n":2,"t":"以色列众人向摩西和亚伦发怨言，全会众对他们说：“我们宁愿死在埃及地，宁愿死在这旷野！","notes":[]},{"n":3,"t":"耶和华为什么要把我们领到那地，让我们倒在刀下呢？我们的妻子和孩子必成为掳物。我们回埃及去岂不更好吗？”","notes":[]},{"n":4,"t":"他们彼此说：“我们不如选一个领袖，回埃及去吧！”","notes":[]},{"n":5,"t":"摩西和亚伦在以色列全会众面前脸伏于地。","notes":[]},{"n":6,"t":"窥探那地的人中，嫩的儿子约书亚和耶孚尼的儿子迦勒撕裂衣服，","notes":[]},{"n":7,"t":"对以色列全会众说：“我们所走过、所窥探之地是极美之地。","notes":[]},{"n":8,"t":"耶和华若喜爱我们，就必领我们进入那地，把这流奶与蜜之地赐给我们。","notes":[]},{"n":9,"t":"但你们不可背叛耶和华，也不要怕那地的百姓，因为他们是我们的食物。保护他们的已经离开他们，耶和华却与我们同在。不要怕他们！”","notes":[]},{"n":10,"t":"当全会众正说着要拿石头打死他们的时候，耶和华的荣光在会幕中向以色列众人显现。","notes":[]},{"n":11,"t":"耶和华对摩西说：“这百姓藐视我要到几时呢？我在他们中间行了这一切神迹，他们还不信我要到几时呢？","notes":[],"heads":["摩西为以色列人祷告"]},{"n":12,"t":"我要用瘟疫击杀他们，使他们不得承受那地。我要使你成为大国，比他们强大。”","notes":[]},{"n":13,"t":"摩西对耶和华说：“埃及人必听见，因你曾施展大能，领这百姓从他们中间出来。","notes":[]},{"n":14,"t":"埃及人要告诉这地的居民，他们已经听见你─耶和华是在这百姓中间，因为你─耶和华面对面显示自己，你的云彩停在他们以上。你日间在云柱中，夜间在火柱中，在他们的前面行。","notes":["“面对面”：原文是“眼对眼”。"]},{"n":15,"t":"你若把这百姓杀了，好像杀一个人那样，那听见你名声的列国必说：","notes":[]},{"n":16,"t":"‘耶和华因为不能把这百姓领进他向他们起誓应许之地，所以在旷野把他们杀了。’","notes":[]},{"n":17,"t":"现在求主显出大能，照你说过的话说：","notes":[]},{"n":18,"t":"‘耶和华不轻易发怒，且有丰盛的慈爱。他赦免罪孽和过犯，万不以有罪的为无罪，必惩罚人的罪，从父到子，直到三、四代。’","notes":[]},{"n":19,"t":"求你照你的大慈爱赦免这百姓的罪孽，好像你从埃及到如今饶恕这百姓一样。”","notes":[]},{"n":20,"t":"耶和华说：“我照着你的话赦免他们。","notes":[]},{"n":21,"t":"然而，我指着我的永生与遍地充满了耶和华的荣耀起誓：","notes":[]},{"n":22,"t":"这些人虽然都看过我的荣耀和我在埃及与旷野所行的神迹，仍然这十次试探我，不听从我的话，","notes":[]},{"n":23,"t":"他们绝不能看见我向他们祖宗所起誓应许之地；凡藐视我的，一个也不得看见。","notes":[]},{"n":24,"t":"惟独我的仆人迦勒，因他另有一个心志，专心跟从我，我要领他进入他所去过的那地；他的后裔必得那地为业。","notes":[]},{"n":25,"t":"亚玛力人和迦南人住在谷中，明天你们要转回去，沿着红海的路往旷野去。”","notes":["“红海”是根据七十士译本，原文是“芦苇海”；本卷书下同。"]},{"n":26,"t":"耶和华对摩西和亚伦说：","notes":[],"heads":["以色列人受惩罚"]},{"n":27,"t":"“这邪恶的会众向我发怨言要到几时呢？以色列人向我发的怨言，我都听见了。","notes":[]},{"n":28,"t":"你要告诉他们，耶和华说：‘我指着我的永生起誓，我必照你们在我耳中所说的待你们。","notes":[]},{"n":29,"t":"你们的尸体必倒在这旷野中。你们中间被数点，凡二十岁以上向我发怨言的，","notes":[]},{"n":30,"t":"必不得进我所起誓应许给你们居住的那地。惟有耶孚尼的儿子迦勒和嫩的儿子约书亚才能进去。","notes":[]},{"n":31,"t":"你们的孩子，就是你们说要成为掳物的，我必领他们进去，他们就得知你们所厌弃的那地。","notes":[]},{"n":32,"t":"至于你们，你们的尸体必倒在这旷野中；","notes":[]},{"n":33,"t":"你们的儿女必在旷野游牧四十年，担当你们不信的罪，直到你们的尸体在旷野消灭为止。","notes":["“不信的罪”：原文是“淫行”。"]},{"n":34,"t":"按你们窥探那地的四十日，一年抵一日，你们要担当你们的罪孽四十年，你们就知道我疏远你们了。’","notes":[]},{"n":35,"t":"我－耶和华说过，我必这样对待这一切聚集对抗我的邪恶会众。他们必在这旷野中消灭，死在这里。”","notes":[]},{"n":36,"t":"摩西所差派去窥探那地的人回来，散布有关那地的谣言，使全会众向摩西发怨言，","notes":[]},{"n":37,"t":"这些散布谣言的人都遭受瘟疫，死在耶和华面前。","notes":[]},{"n":38,"t":"窥探那地的人中，惟有嫩的儿子约书亚和耶孚尼的儿子迦勒得以存活。","notes":[]},{"n":39,"t":"摩西把这些话告诉以色列众人，他们都极其悲哀。","notes":[],"heads":["进攻迦南却被击退"]},{"n":40,"t":"他们清晨起来，上到山顶，说：“看哪，我们要上到耶和华所说的地方；因为我们犯了罪。”","notes":[]},{"n":41,"t":"摩西说：“你们为何要这样违背耶和华的指示呢？这事必不能顺利。","notes":[]},{"n":42,"t":"不要上去，因为耶和华不在你们中间，恐怕你们在仇敌面前被击败。","notes":[]},{"n":43,"t":"亚玛力人和迦南人都在你们面前，你们必倒在刀下。因为你们背离不跟从耶和华，耶和华必不与你们同在。”","notes":[]},{"n":44,"t":"他们却擅自上到山顶。但耶和华的约柜和摩西都没有离开营地。","notes":[]},{"n":45,"t":"于是亚玛力人和住在那山区的迦南人下来，击败他们，追击他们直到何珥玛。","notes":[]}]},"15":{"heading":"献祭的条例","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人，对他们说：你们到了我所赐给你们居住的地，","notes":[]},{"n":3,"t":"你们要从牛群羊群中取牲畜献给耶和华为火祭，无论是燔祭或祭物，为要还所许特别的愿或甘心祭，或节期的祭，作为献给耶和华的馨香之祭，","notes":[]},{"n":4,"t":"那献供物的要将十分之一伊法细面和四分之一欣油调和作素祭，献给耶和华。","notes":[]},{"n":5,"t":"无论是燔祭或祭物，要为每只小绵羊预备四分之一欣酒作浇酒祭。","notes":[]},{"n":6,"t":"要为每只公绵羊预备十分之二伊法细面，和三分之一欣油调和作素祭，","notes":[]},{"n":7,"t":"又用三分之一欣酒作浇酒祭，献给耶和华为馨香之祭。","notes":[]},{"n":8,"t":"你预备公牛献给耶和华作燔祭或祭物，为要还所许特别的愿，或平安祭，","notes":[]},{"n":9,"t":"就要把十分之三伊法细面和半欣油调和作素祭，和公牛一同献上，","notes":[]},{"n":10,"t":"又用半欣酒作浇酒祭，献给耶和华为馨香的火祭。","notes":[]},{"n":11,"t":"“献公牛、或公绵羊、或小绵羊、或小山羊，每只都要这样处理；","notes":[]},{"n":12,"t":"无论你们所献的数目多少，照着数目每只都要这样处理。","notes":[]},{"n":13,"t":"凡本地人将馨香的火祭献给耶和华，都要照样处理。","notes":[]},{"n":14,"t":"若有外人寄居在你们那里，或有人世世代代住在你们中间，愿意将馨香的火祭献给耶和华，你们怎样处理，他也要照样处理。","notes":[]},{"n":15,"t":"至于会众，无论是你们或寄居的外人都要遵守同一条例；这是你们世世代代永远的定例。在耶和华面前，你们怎样，寄居的也要怎样。","notes":[]},{"n":16,"t":"你们和寄居在你们那里的外人要遵守同一律法，同一典章。”","notes":[]},{"n":17,"t":"耶和华吩咐摩西说：","notes":[]},{"n":18,"t":"“你要吩咐以色列人，对他们说：你们到了我领你们进去的那地，","notes":[]},{"n":19,"t":"吃那地的粮食时，要把举祭献给耶和华。","notes":[]},{"n":20,"t":"你们要用初熟的麦子磨面，做成饼当举祭献上。你们要举上，如同举禾场的举祭。","notes":[]},{"n":21,"t":"你们世世代代要用初熟的麦子磨面，当举祭献给耶和华。","notes":[]},{"n":22,"t":"“你们若犯了错，不遵守耶和华所吩咐摩西的这一切命令，","notes":[]},{"n":23,"t":"就是耶和华藉摩西一切所命令你们的，从耶和华命令的那日直到你们的世世代代，","notes":[]},{"n":24,"t":"会众因没有察觉而犯了无心之过，全会众就要将一头公牛犊作燔祭，遵照典章把素祭和浇酒祭一同献给耶和华为馨香的祭，又要献一只公山羊作赎罪祭。","notes":[]},{"n":25,"t":"祭司要为以色列全会众赎罪，他们就必蒙赦免，因为这是无心之过。他们要因自己的无心之过，把供物，就是向耶和华当献的火祭和赎罪祭，带到耶和华面前。","notes":[]},{"n":26,"t":"以色列全会众和寄居在他们中间的外人就必蒙赦免，因为这是众百姓的无心之过。","notes":[]},{"n":27,"t":"“若有一个人无意中犯了罪，他就要献一只一岁的母山羊作赎罪祭。","notes":[]},{"n":28,"t":"这误犯罪的人因无意中犯了罪，祭司要在耶和华面前为他赎罪，他就必蒙赦免。","notes":[]},{"n":29,"t":"以色列中的本地人和寄居在他们中间的外人，若无意中犯了罪，都要遵守同一律法。","notes":[]},{"n":30,"t":"但那故意犯罪的人，无论是本地人是寄居的，亵渎了耶和华，这人必从百姓中剪除。","notes":[]},{"n":31,"t":"因为他藐视耶和华的话，违背耶和华的命令，这人一定要剪除；他的罪孽要归到自己身上。”","notes":[]},{"n":32,"t":"以色列人还在旷野的时候，发现有一个人在安息日捡柴。","notes":[],"heads":["违反安息日的人"]},{"n":33,"t":"发现他捡柴的人把他带到摩西、亚伦以及全会众那里。","notes":[]},{"n":34,"t":"他们把他收押在监里，因为还不知道要怎样惩罚他。","notes":[]},{"n":35,"t":"耶和华吩咐摩西说：“这人应当处死；全会众要在营外用石头打死他。”","notes":[]},{"n":36,"t":"于是全会众把他带到营外，用石头打死他，是照耶和华所吩咐摩西的。","notes":[]},{"n":37,"t":"耶和华对摩西说：","notes":[],"heads":["有关衣服繸子的条例"]},{"n":38,"t":"“你吩咐以色列人，对他们说，他们世世代代要在衣服边上缝繸子，并在边上的繸子钉一条蓝色带子。","notes":[]},{"n":39,"t":"你们要佩带这繸子，好叫你们看见它就记起耶和华一切的命令，并且遵行，不随从自己内心和眼目的情欲而跟着行淫。","notes":[]},{"n":40,"t":"这样，你们就必记得并遵行我一切的命令，成为圣，归你们的神。","notes":[]},{"n":41,"t":"“我是耶和华－你们的神，曾把你们从埃及地领出来，要作你们的神。我是耶和华－你们的神。”","notes":[]}]},"16":{"heading":"可拉、大坍、亚比兰和安的叛变","verses":[{"n":1,"t":"利未的曾孙，哥辖的孙子，以斯哈的儿子可拉，连同吕便子孙中以利押的儿子大坍和亚比兰，与比勒的儿子安，带了","notes":[]},{"n":2,"t":"以色列人中的二百五十个领袖，就是有名望、从会众中选出来的人，在摩西面前一同起来，","notes":[]},{"n":3,"t":"聚集攻击摩西、亚伦，说：“你们太过分了！全会众人人都成为圣，耶和华也在他们中间。你们为什么抬高自己，在耶和华的会众之上呢？”","notes":[]},{"n":4,"t":"摩西听见就脸伏于地，","notes":[]},{"n":5,"t":"对可拉和他所有同伙的人说：“到了早晨，耶和华必指示谁是属他的，谁是成为圣的，就准许谁亲近他。他要叫自己所拣选的人亲近他。","notes":[]},{"n":6,"t":"可拉和你所有同伙的人哪，你们要这样做：要拿着香炉，","notes":[]},{"n":7,"t":"明天在耶和华面前把火盛在炉中，把香放在上面。耶和华拣选谁，谁就成为圣。利未的子孙哪，你们太过分了！”","notes":[]},{"n":8,"t":"摩西又对可拉说：“利未的子孙，听吧！","notes":[]},{"n":9,"t":"以色列的神将你们从以色列会众中分别出来，使你们亲近他，在耶和华的帐幕中事奉，并且站在会众面前替他们供职。这对你们岂是小事吗？","notes":[]},{"n":10,"t":"耶和华已经准许你和你所有的弟兄，就是利未的子孙，一同亲近他，你们还要求祭司的职分吗？","notes":[]},{"n":11,"t":"所以，你和你所有同伙的人聚集是在攻击耶和华。亚伦算什么，你们竟向他发怨言？”","notes":[]},{"n":12,"t":"摩西派人去叫以利押的儿子大坍和亚比兰。他们却说：“我们不上去！","notes":[]},{"n":13,"t":"你把我们从流奶与蜜之地领出来，让我们死在旷野，这岂是小事？你还要自立为王管辖我们吗？","notes":[]},{"n":14,"t":"你根本没有领我们到流奶与蜜之地，也没有给我们田地和葡萄园作为产业。难道你想要挖这些人的眼睛吗？我们不上去！”","notes":[]},{"n":15,"t":"摩西非常生气，就对耶和华说：“求你不要接受他们的供物。我并没有夺过他们一匹驴，也没有害过他们中任何一个人。”","notes":[]},{"n":16,"t":"摩西对可拉说：“明天，你和你所有同伙的人，以及亚伦，都要站在耶和华面前。","notes":[]},{"n":17,"t":"你们各人要拿一个香炉，把香放在上面，各人带香炉到耶和华面前，共二百五十个；你和亚伦也各拿自己的香炉。”","notes":[]},{"n":18,"t":"于是他们各人拿一个香炉，盛着火，加上香，和摩西、亚伦一同站在会幕的门口。","notes":[]},{"n":19,"t":"可拉召集全会众到会幕门口攻击摩西和亚伦。这时，耶和华的荣光向全会众显现。","notes":[]},{"n":20,"t":"耶和华吩咐摩西和亚伦说：","notes":[]},{"n":21,"t":"“你们离开这会众，我好立刻把他们灭绝。”","notes":[]},{"n":22,"t":"摩西、亚伦脸伏于地，说：“神，赐万人气息的神啊，一人犯罪，你就要向全会众发怒吗？”","notes":[]},{"n":23,"t":"耶和华吩咐摩西说：","notes":[]},{"n":24,"t":"“你吩咐会众说：‘你们远离可拉、大坍和亚比兰帐棚的周围。’”","notes":[]},{"n":25,"t":"摩西起来，到大坍、亚比兰那里去；以色列的长老也都跟着他去。","notes":[]},{"n":26,"t":"他吩咐会众说：“你们离开这些恶人的帐棚吧！不可碰他们的任何东西，免得你们因他们一切的罪而消灭。”","notes":[]},{"n":27,"t":"于是会众远离了可拉、大坍和亚比兰的帐棚。大坍和亚比兰带着妻子、儿女和小孩子出来，站在自己的帐棚门口。","notes":[]},{"n":28,"t":"摩西说：“因这件事，你们就必知道这一切事是耶和华差派我做的，并非出于我的心意。","notes":[]},{"n":29,"t":"这些人的死若和世人无异，或者他们所遭遇的和其他人相同，那么耶和华就不曾差派我了。","notes":[]},{"n":30,"t":"但是，倘若耶和华创作一件新事，使地开了裂口，把他们和一切属他们的都吞下去，叫他们活活坠落阴间，你们就知道是这些人藐视了耶和华。”","notes":[]},{"n":31,"t":"摩西刚说完这些话，他们脚下的地就裂开，","notes":[]},{"n":32,"t":"地开了裂口，把他们和他们的家眷，以及一切属可拉的人和财物，都吞了下去。","notes":[]},{"n":33,"t":"他们和一切属他们的，都活活坠落阴间；地在他们上面又合拢起来，他们就从会众中灭亡了。","notes":[]},{"n":34,"t":"在他们四围的以色列众人听见他们的叫声，就都逃跑，说：“恐怕地也要把我们吞下去了！”","notes":[]},{"n":35,"t":"有火从耶和华那里出来，吞灭了那上香的二百五十人。","notes":[]},{"n":36,"t":"耶和华吩咐摩西说：","notes":[]},{"n":37,"t":"“你要对亚伦祭司的儿子以利亚撒说，把香炉从火中移开，再把炭火撒在别处，因为这些香炉是分别为圣的。","notes":[]},{"n":38,"t":"要把那些犯罪自丧己命之人的香炉锤成薄片，用以包祭坛；因为这些本是他们在耶和华面前献过，分别为圣的，可以给以色列人作记号。”","notes":[]},{"n":39,"t":"于是以利亚撒祭司把被烧死的人所献的铜香炉拿来；它们被锤出来，用以包坛，","notes":[]},{"n":40,"t":"给以色列人作纪念，为要叫亚伦子孙之外的人不得近前来，在耶和华面前烧香，免得他和可拉与同他一伙的人一样，正如耶和华藉摩西所吩咐的。","notes":[]},{"n":41,"t":"第二天，以色列全会众都向摩西、亚伦发怨言说：“你们杀了耶和华的百姓了。”","notes":[]},{"n":42,"t":"会众聚集攻击摩西、亚伦的时候，摩西和亚伦转向会幕，看哪，云彩遮盖会幕，耶和华的荣光显现。","notes":[]},{"n":43,"t":"摩西、亚伦就来到会幕前。","notes":[]},{"n":44,"t":"耶和华吩咐摩西说：","notes":[]},{"n":45,"t":"“你们离开这会众，我好立刻把他们灭绝。”他们二人就脸伏于地。","notes":[]},{"n":46,"t":"摩西对亚伦说：“拿你的香炉，把祭坛的火盛在里面，加上香，赶快带到会众那里，为他们赎罪。因为有愤怒从耶和华面前发出，瘟疫已经开始了。”","notes":[]},{"n":47,"t":"亚伦照摩西所说的拿了香炉，跑到会众中。看哪，瘟疫已经在百姓中开始了。他就加上香，为百姓赎罪。","notes":[]},{"n":48,"t":"他站在活人和死人之间，瘟疫就止住了。","notes":[]},{"n":49,"t":"除了因可拉事件死的以外，遭瘟疫死的共有一万四千七百人。","notes":[]},{"n":50,"t":"亚伦回到会幕门口 ，到摩西那里，瘟疫已经止住了。","notes":[]}]},"17":{"heading":"亚伦的杖","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人，从他们当中取杖，每父家一根；从他们所有的领袖，按着父家，共取十二根。你要把各人的名字写在他的杖上，","notes":[]},{"n":3,"t":"并要把亚伦的名字写在利未的杖上，因为各父家的家长都有一根杖。","notes":[]},{"n":4,"t":"你要把这些杖放在会幕里法柜前，我与你们相会的地方。","notes":["“与你们”：有古卷和七十士译本是“与你”。"]},{"n":5,"t":"我所拣选的人，他的杖必发芽。我就平息了以色列人向你们所发的怨言，不再达到我这里。”","notes":[]},{"n":6,"t":"于是，摩西吩咐以色列人，他们的众领袖就把杖给他，一个领袖一根杖，按照父家一个领袖一根杖，共有十二根；亚伦的杖也在其中。","notes":[]},{"n":7,"t":"摩西把这些杖放在耶和华面前，在法柜的帐幕里。","notes":[]},{"n":8,"t":"第二天，摩西进到法柜的帐幕去，看哪，利未族亚伦的杖已经发芽，长了花苞，开了花，也结出熟的杏子！","notes":[]},{"n":9,"t":"摩西把所有的杖从耶和华面前拿出来，给以色列众人看。他们都看见了，各领袖就把自己的杖拿去。","notes":[]},{"n":10,"t":"耶和华吩咐摩西说：“把亚伦的杖放回法柜前，给这些背叛之子留作记号。你就可以平息他们向我所发的怨言，他们也不会死亡。”","notes":[]},{"n":11,"t":"摩西就照样做了；耶和华怎样吩咐他，他就照样做。","notes":[]},{"n":12,"t":"以色列人对摩西说：“看哪，我们死啦！我们灭亡啦！我们全都灭亡啦！","notes":[]},{"n":13,"t":"凡挨近耶和华帐幕的，就必死亡。我们都要消灭而死吗？”","notes":[]}]},"18":{"heading":"祭司和利未人的职责","verses":[{"n":1,"t":"耶和华对亚伦说：“你和你的儿子，以及你父家的人，要一同担当干犯圣所的罪孽；你和你的儿子也要担当干犯祭司职分的罪孽。","notes":[]},{"n":2,"t":"你也要带你弟兄利未人，就是你父系支派的人前来，与你联合，服事你。你和你的儿子要一起在法柜的帐幕前；","notes":[]},{"n":3,"t":"他们要遵守你的吩咐，负责看守整个帐幕，只是不可挨近圣所的器具和祭坛，免得他们和你们都死亡。","notes":[]},{"n":4,"t":"他们要与你联合，负责看守会幕和帐幕一切的事；只是外人不可挨近你们。","notes":[]},{"n":5,"t":"你们要负责看守圣所和祭坛，免得愤怒再临到以色列人。","notes":[]},{"n":6,"t":"看哪，我已从以色列人中选了你们的弟兄利未人，交给你们为赏赐，归给耶和华，为要在会幕里事奉。","notes":[]},{"n":7,"t":"你和你的儿子要谨守祭司的职分，负责一切关于祭坛和幔子内的事。我把祭司的职分赐给你们，作为赏赐好事奉我；凡挨近的外人必被处死。”","notes":[]},{"n":8,"t":"耶和华吩咐亚伦说：“看哪，我已将归我的举祭，就是以色列人一切分别为圣之物，交给你照管；我把受膏的份赐给你和你的子孙，作为永远当得的份。","notes":[],"heads":["祭司和利未人应得的份"]},{"n":9,"t":"这是至圣供物中所给你的，一切献给我为至圣的素祭、赎罪祭、赎愆祭，其中所有不被火烧的供物，都要归你和你的子孙。","notes":[]},{"n":10,"t":"你要把它当作至圣之物吃；凡男丁都可以吃。你要以这祭物为圣。","notes":["“你要...吃”或译“你要在至圣的地方吃”。"]},{"n":11,"t":"这也是你的，以色列人所献的举祭和摇祭，我已赐给你和你的儿女，作为永远当得的份；你家中任何洁净的人都可以吃。","notes":[]},{"n":12,"t":"凡最好的新油、最好的新酒和五谷，就是以色列人献给耶和华的初熟之物，我都赐给你。","notes":[]},{"n":13,"t":"凡他们从地上所带来给耶和华的初熟之物也都要归给你。你家中任何洁净的人都可以吃。","notes":[]},{"n":14,"t":"以色列中一切永献的都必归给你。","notes":[]},{"n":15,"t":"他们所有奉给耶和华的，无论是人是牲畜，凡头胎的，都要归给你；但是人的长子，一定要赎出来。不洁净牲畜中头生的，也要赎出来。","notes":[]},{"n":16,"t":"其中一个月以上所当赎的，要照你的估价，按圣所的舍客勒，付五舍客勒银子将他赎回，一舍客勒是二十季拉。","notes":[]},{"n":17,"t":"但是头生的牛，或头生的绵羊，或头生的山羊，却不可赎，因为它们都是圣的。要把它们的血洒在祭坛上，把它们的脂肪焚烧，当作馨香的火祭献给耶和华。","notes":[]},{"n":18,"t":"它们的肉必归你，像被摇的胸、被举的右腿归你一样。","notes":[]},{"n":19,"t":"凡以色列人所献给耶和华圣物中的举祭，我都赐给你和你的儿女，作为永远当得的份。这要成为你和你的后裔在耶和华面前永远的盐约。","notes":["“盐”指“不废坏”的意思。"]},{"n":20,"t":"耶和华对亚伦说：“你在以色列人的境内不可有产业，在他们中间也不可有份。在以色列人中，我是你的份，你的产业。","notes":[]},{"n":21,"t":"“至于利未的子孙，看哪，我已赐给他们以色列所有出产的十分之一为业，作为他们在会幕中事奉的酬劳。","notes":[]},{"n":22,"t":"以色列人不可再挨近会幕，免得他们担当罪而死。","notes":[]},{"n":23,"t":"惟独利未人要在会幕中事奉，他们要担当罪孽，作为你们世世代代永远的定例。他们在以色列人中不可有产业；","notes":[]},{"n":24,"t":"因为以色列人出产的十分之一，就是献给耶和华为举祭的，我已赐给利未人为业。所以我对他们说，他们不可在以色列人中有产业。”","notes":[]},{"n":25,"t":"耶和华吩咐摩西说：","notes":[],"heads":["利未人的十一奉献"]},{"n":26,"t":"“你要吩咐利未人，对他们说：你们从以色列人中所取的十分之一，就是我给你们为业的，要从这十分之一中取十分之一，作为献给耶和华的举祭。","notes":[]},{"n":27,"t":"这可算为你们的举祭，如同禾场上的谷，酒池中盛满的酒。","notes":[]},{"n":28,"t":"这样，从以色列人中所收取所有的十分之一，你们要从其中取举祭献给耶和华；你们要把献给耶和华的举祭归给亚伦祭司。","notes":[]},{"n":29,"t":"你们要将给你们一切礼物中最好的，就是分别为圣的，献给耶和华为举祭。","notes":[]},{"n":30,"t":"你要对利未人说：当你们把其中最好的献上为举祭之后，这剩下的就算是你们禾场上的农作物，酒池中的酒。","notes":[]},{"n":31,"t":"你们和你们的家人可以在任何地方吃；这本是你们的赏赐，是你们在会幕里事奉的酬劳。","notes":[]},{"n":32,"t":"当你们把其中最好的献上为举祭，就不致于因它担当罪。你们不可玷污以色列人的圣物，免得死亡。”","notes":[]}]},"19":{"heading":"红母牛祭礼","verses":[{"n":1,"t":"耶和华吩咐摩西和亚伦说：","notes":[]},{"n":2,"t":"“耶和华所吩咐的律法中，其中一条律例这样说：要吩咐以色列人，把一头健康、没有残疾、未曾负轭的红母牛牵到你这里来，","notes":[]},{"n":3,"t":"交给以利亚撒祭司。他要把牛牵到营外，人就在他面前把牛宰了。","notes":[]},{"n":4,"t":"以利亚撒祭司要用指头蘸这牛的血，向会幕前面弹七次。","notes":[]},{"n":5,"t":"人要在他眼前焚烧这母牛，牛的皮、肉、血和粪都要焚烧。","notes":[]},{"n":6,"t":"祭司要把香柏木、牛膝草和朱红色纱都丢在焚烧牛的火中。","notes":[]},{"n":7,"t":"祭司要洗衣服，用水洗身，然后才可以进营；祭司必不洁净到晚上。","notes":[]},{"n":8,"t":"焚烧牛的人也要用水洗衣服，用水洗身，必不洁净到晚上。","notes":[]},{"n":9,"t":"一个洁净的人要收母牛的灰，存放在营外洁净的地方，为以色列会众留作除污秽的水之用。这是为除罪用的。","notes":[]},{"n":10,"t":"收取母牛灰的人要洗衣服，必不洁净到晚上。这要成为以色列人和寄居在他们中间的外人永远的定例。","notes":[]},{"n":11,"t":"“摸了任何人死尸的，必不洁净七天。","notes":[]},{"n":12,"t":"那人要在第三天和第七天洁净自己，他就洁净了。若他不在第三天和第七天洁净自己，他就不洁净了。","notes":[]},{"n":13,"t":"凡摸了死尸，就是死了的人的尸体，又不洁净自己的，就玷污了耶和华的帐幕，这人必从以色列中剪除；因为那除污秽的水没有洒在他身上，他就不洁净，污秽还在他身上。","notes":[]},{"n":14,"t":"“若有人死在帐棚里，条例是这样：凡进那帐棚的，和所有在帐棚里的人，都必不洁净七天。","notes":[]},{"n":15,"t":"凡敞开的，没有用绳子扎好盖子的器皿，也不洁净。","notes":[]},{"n":16,"t":"任何人在田野里摸了被刀杀的，或自然死的，或人的骨头，或坟墓，就必不洁净七天。","notes":[]},{"n":17,"t":"要为这不洁净的人拿一些烧好的除罪灰放在器皿里，倒上清水。","notes":[]},{"n":18,"t":"一个洁净的人要拿牛膝草蘸在这水中，把水弹在帐棚上，和一切器皿以及帐棚内的人身上，又要弹在那摸了骨头，或摸了被杀的或自然死的，或摸了坟墓的人身上。","notes":[]},{"n":19,"t":"那洁净的人要在第三天和第七天把水弹在不洁净的人身上，在第七天洁净那人。那人要洗衣服，用水洗澡，到晚上就洁净了。","notes":[]},{"n":20,"t":"但任何不洁净的人，他若不洁净自己，那人要从会中剪除，因为他玷污了耶和华的圣所，除污秽的水没有洒在他身上，他是不洁净的。","notes":[]},{"n":21,"t":"这要成为你们永远的定例。此外，那弹除污秽水的人也要洗衣服。凡碰除污秽水的，必不洁净到晚上。","notes":[]},{"n":22,"t":"不洁净的人所摸的任何东西都不洁净；摸了这东西的人必不洁净到晚上。”","notes":[]}]},"20":{"heading":"米利巴水","verses":[{"n":1,"t":"正月间，以色列全会众到了寻的旷野；百姓住在加低斯。米利暗死在那里，也葬在那里。","notes":[]},{"n":2,"t":"会众没有水，就聚集反对摩西和亚伦。","notes":[]},{"n":3,"t":"百姓与摩西争闹，说：“我们恨不得与我们的弟兄一同死在耶和华面前。","notes":[]},{"n":4,"t":"你们为什么领耶和华的会众到这旷野，使我们和我们的牲畜都死在这里呢？","notes":[]},{"n":5,"t":"你们为什么领我们从埃及上来，把我们带到这坏的地方呢？这地方不能撒种，没有无花果树、葡萄树、石榴树，也没有水喝。”","notes":[]},{"n":6,"t":"摩西、亚伦离开会众面前，到会幕的门口，脸伏于地；耶和华的荣光向他们显现。","notes":[]},{"n":7,"t":"耶和华吩咐摩西说：","notes":[]},{"n":8,"t":"“你拿着杖去，和你的哥哥亚伦召集会众，在他们眼前吩咐磐石涌出水来，水就会从磐石流出，给会众和他们的牲畜喝。”","notes":[]},{"n":9,"t":"于是摩西遵照耶和华所吩咐他的，从耶和华面前拿了杖去。","notes":[]},{"n":10,"t":"摩西和亚伦召集会众到磐石前。摩西对他们说：“听着，你们这些悖逆的人！我们要叫这磐石流出水来给你们吗？”","notes":[]},{"n":11,"t":"摩西举起手来，用杖击打磐石两下，就有许多水流出来，会众和他们的牲畜都喝了。","notes":[]},{"n":12,"t":"但是耶和华对摩西、亚伦说：“因为你们不信我，没有在以色列人眼前尊我为圣，所以你们必不能领这会众进入我所要赐给他们的地去。”","notes":[]},{"n":13,"t":"这就是米利巴水，因以色列人与耶和华争闹，耶和华在他们面前显为圣。","notes":["“米利巴”意思是“争闹”。"]},{"n":14,"t":"摩西从加低斯差遣使者到以东王那里，说：“你的弟兄以色列这样说：‘你知道我们所遭遇的一切困难。","notes":[],"heads":["以东王不准过境"]},{"n":15,"t":"我们的祖先曾下到埃及，我们也在埃及住了很多年。然而，埃及人却恶待我们和我们的祖先。","notes":[]},{"n":16,"t":"我们哀求耶和华，他垂听了我们的声音，差遣使者把我们从埃及领出来。看哪，我们到了你边界的加低斯城。","notes":[]},{"n":17,"t":"求你让我们穿越你的地。我们不走田间和葡萄园，也不喝井里的水。我们只走王的大道，不偏左右，直到过了你的边界。’”","notes":[]},{"n":18,"t":"但是，以东对他说：“你不可从我这里穿越！否则，我要带刀出去攻击你。”","notes":[]},{"n":19,"t":"以色列人对他说：“我们只上大道。如果我和我的牲畜喝了你的水，我必付钱给你。我不求别的事，只求让我步行过去。”","notes":[]},{"n":20,"t":"以东说：“你不可经过！”他就率领一大群军队，以强硬的手出来攻击以色列。","notes":[]},{"n":21,"t":"这样，以东不肯让以色列穿越他的境内，以色列就转去，离开他了。","notes":[]},{"n":22,"t":"以色列全会众从加低斯起行，到了何珥山。","notes":[],"heads":["亚伦逝世"]},{"n":23,"t":"耶和华在以东地边界的何珥山对摩西、亚伦说：","notes":[]},{"n":24,"t":"“亚伦要归到他祖先那里。他必不得进入我所赐给以色列人的地，因为你们在米利巴水的事上违背了我的指示。","notes":["“他祖先”：原文是“他百姓”。"]},{"n":25,"t":"你要带亚伦和他的儿子以利亚撒上何珥山，","notes":[]},{"n":26,"t":"把亚伦的圣衣脱下，给他的儿子以利亚撒穿上。亚伦必归去，死在那里。”","notes":[]},{"n":27,"t":"摩西就遵照耶和华的吩咐去做，他们在全会众的眼前上了何珥山。","notes":[]},{"n":28,"t":"摩西把亚伦的圣衣脱下，给他的儿子以利亚撒穿上，亚伦就死在山顶那里。于是，摩西和以利亚撒下了山。","notes":[]},{"n":29,"t":"全会众见亚伦死了，以色列全家就为亚伦举哀三十天。","notes":[]}]},"21":{"heading":"战胜迦南人","verses":[{"n":1,"t":"住尼革夫的迦南人的亚拉得王，听说以色列从亚他林路来，就和以色列交战，掳去他们一些人。","notes":[]},{"n":2,"t":"以色列向耶和华许愿说：“你若把这百姓真的交在我手中，我就把他们的城镇彻底毁灭。”","notes":[]},{"n":3,"t":"耶和华垂听了以色列的声音，把迦南人交出来。以色列就把迦南人和他们的城镇彻底毁灭。因此，那地方名叫何珥玛 。","notes":["“何珥玛”意思是“毁灭”。"]},{"n":4,"t":"他们从何珥山起行，绕过以东地往红海那条路走。在路上，百姓心中烦躁。","notes":[],"heads":["铜制的蛇"]},{"n":5,"t":"百姓向神和摩西发怨言，说：“你们为什么把我们从埃及领上来，使我们死在旷野呢？这里没有粮食，没有水，我们厌恶这淡而无味的食物。”","notes":["“你们...领上来”：七十士译本是“你为什么把我们从埃及领出来”。"]},{"n":6,"t":"耶和华派火蛇进入百姓当中去咬他们，于是以色列中死了许多百姓。","notes":[]},{"n":7,"t":"百姓到摩西那里，说：“我们有罪了，因为我们向耶和华和你发怨言。求你向耶和华祷告，叫蛇离开我们。”于是摩西为百姓祷告。","notes":[]},{"n":8,"t":"耶和华对摩西说：“你要造一条火蛇，挂在杆子上。凡被咬的，一望这蛇就必存活。”","notes":[]},{"n":9,"t":"摩西就造了一条铜蛇，挂在杆子上。凡被蛇咬的，一望这铜蛇就活了。","notes":[]},{"n":10,"t":"以色列人起行，安营在阿伯。","notes":[],"heads":["从何珥山到摩押谷"]},{"n":11,"t":"又从阿伯起行，安营在以耶．亚巴琳，在摩押对面的旷野，向日出的方向。","notes":[]},{"n":12,"t":"又从那里起行，安营在撒烈谷。","notes":[]},{"n":13,"t":"从那里再起行，安营在亚嫩河的另一边。这亚嫩河在旷野，从亚摩利人的境内流出来；亚嫩河是摩押的边界，在摩押和亚摩利人之间。","notes":[]},{"n":14,"t":"所以《耶和华的战记》中提到：“苏法的哇哈伯，亚嫩河谷，","notes":[]},{"n":15,"t":"以及亚珥地区众河床的斜坡，都靠近摩押的边境。”","notes":[]},{"n":16,"t":"以色列人从那里起行，到了比珥 。从前耶和华对摩西说：“召集百姓，我要给他们水”，说的就是这井。","notes":["“比珥”意思是“井”。"]},{"n":17,"t":"当时，以色列人唱这首歌：“井啊，涌出水来！你们要向它歌唱！","notes":[]},{"n":18,"t":"这井是领袖用权杖所挖，是百姓中的贵族用手杖所掘。”以色列人从旷野往玛他拿去，","notes":[]},{"n":19,"t":"从玛他拿到拿哈列，从拿哈列到巴末，","notes":[]},{"n":20,"t":"从巴末到摩押地的谷，又到那可以瞭望旷野的毗斯迦山顶。","notes":[]},{"n":21,"t":"以色列差遣使者到亚摩利人的王西宏那里，说：","notes":[],"heads":["战胜亚摩利王和巴珊王"]},{"n":22,"t":"“求你让我们穿越你的地；我们不岔进田间和葡萄园，也不喝井里的水，只走王的大道，直到过了你的边界。”","notes":[]},{"n":23,"t":"但西宏不让以色列人穿越他的境内，就召集他的众百姓出到旷野，要攻击以色列，到了雅杂与以色列交战。","notes":[]},{"n":24,"t":"以色列人用刀杀了他，占领了他的地，从亚嫩河到雅博河，直到亚扪人的边界，因为亚扪人的边防坚固。","notes":[]},{"n":25,"t":"以色列人夺取这里所有的城镇，就住在亚摩利人的城镇中，包括希实本和所属的一切乡镇。","notes":["“乡镇”：原文直译“女子们”；本卷书下同。"]},{"n":26,"t":"希实本是亚摩利王西宏的首都；西宏曾与先前的摩押王交战，从他手中夺取了他所有的地，直到亚嫩河。","notes":[]},{"n":27,"t":"所以那些作诗歌的说：你们到希实本来吧；愿西宏的城被修造建立。","notes":[]},{"n":28,"t":"因为有火从希实本发出，有火焰从西宏的城冒出，烧毁了摩押的亚珥，亚嫩河丘坛的主。","notes":["“亚嫩河丘坛的主”：原文另译“亚嫩河丘坛的诸巴力”；七十士译本是“亚嫩河的柱像”。"]},{"n":29,"t":"摩押啊，你有祸了！基抹的百姓啊，你们灭亡了！基抹的男子逃亡，女子被掳，交给了亚摩利王西宏。","notes":[]},{"n":30,"t":"我们射了他们；希实本直到底本尽都毁灭。我们劫掠，直到挪法；这挪法直延到米底巴。","notes":["“我们...毁灭”：七十士译本是“他们的后代灭亡，从希实本直到底本”。"]},{"n":31,"t":"这样，以色列人就住在亚摩利人的地。","notes":[]},{"n":32,"t":"摩西差派人去窥探雅谢；以色列人占领了雅谢附近的乡村，赶出那里的亚摩利人。","notes":[]},{"n":33,"t":"后来，以色列人转回，往上巴珊的路去。巴珊王噩率领他的众百姓出来，在以得来与他们交战。","notes":[]},{"n":34,"t":"耶和华对摩西说：“不要怕他！因为我已将他和他的众百姓，以及他的地都交在你手中。你要待他如同待住在希实本的亚摩利王西宏一样。”","notes":[]},{"n":35,"t":"于是他们杀了巴珊王和他的众子，以及他的众百姓，没有留下一个幸存者，并且占领了他的地。","notes":[]}]},"22":{"heading":"摩押王召巴兰","verses":[{"n":1,"t":"以色列人起行，在摩押平原，约旦河东，对着耶利哥安营。","notes":[]},{"n":2,"t":"西拨的儿子巴勒看见以色列向亚摩利人所做的一切。","notes":[]},{"n":3,"t":"摩押因以色列百姓这么多，非常惧怕。摩押因以色列人的缘故就忧惧。","notes":[]},{"n":4,"t":"摩押对米甸的长老说：“现在这群人要舔尽我们四围的一切，好像牛舔尽田间的草一样。”那时，西拨的儿子巴勒作摩押王。","notes":[]},{"n":5,"t":"他派使者往大河附近的毗夺去，到比珥的儿子巴兰的家乡，召巴兰来，说：“看哪，有一群百姓从埃及出来；看哪，他们遮满地面，住在我的对面。","notes":["“家乡”：有古译本是“亚茅人的地”。"]},{"n":6,"t":"现在请你来，为我诅咒这百姓，因为他们比我强大，或许我能打败他们，把他们赶出此地。因为我知道，你为谁祝福，谁就得福；你诅咒谁，谁就受诅咒。”","notes":[]},{"n":7,"t":"摩押的长老和米甸的长老手里拿着占卜的礼金到巴兰那里，将巴勒的话告诉他。","notes":[]},{"n":8,"t":"巴兰对他们说：“今晚你们在这里过夜，我必照着耶和华向我说的话给你们答覆。”摩押的官员就在巴兰那里住下。","notes":[]},{"n":9,"t":"神临到巴兰那里，说：“你这里的这些人是谁？”","notes":[]},{"n":10,"t":"巴兰对神说：“摩押王西拨的儿子巴勒送信给我：","notes":[]},{"n":11,"t":"‘看哪，从埃及出来的百姓遮满了地面，现在请你来，为我诅咒他们，或许我能打败他们，把他们赶走。’”","notes":[]},{"n":12,"t":"神对巴兰说：“你不可跟他们去，也不可诅咒这百姓，因为他们是蒙福的。”","notes":[]},{"n":13,"t":"巴兰早晨起来，对巴勒的官员说：“你们回本地去吧，因为耶和华不允许我和你们一起去。”","notes":[]},{"n":14,"t":"摩押的官员就起来，到巴勒那里，说：“巴兰不肯和我们一起来。”","notes":[]},{"n":15,"t":"巴勒又差遣比这些更多，更尊贵的官员。","notes":[]},{"n":16,"t":"他们来到巴兰那里，对他说：“西拨的儿子巴勒这样说：‘请你不要再推辞到我这里来！","notes":[]},{"n":17,"t":"我必使你得极大的尊荣，无论你向我要什么，我都给你。只求你来为我诅咒这百姓。’”","notes":[]},{"n":18,"t":"巴兰回答巴勒的臣仆说：“巴勒就是将他满屋的金银给我，我也不能做任何大小的事，违背耶和华－我神的指示。","notes":[]},{"n":19,"t":"现在请你们今晚也在这里住下，我好知道耶和华还要对我说什么。”","notes":[]},{"n":20,"t":"神在夜里临到巴兰那里，说：“这些人若来求你，你就起来跟他们去吧，只是你必须照着我对你说的话去做。”","notes":[]},{"n":21,"t":"巴兰早晨起来，备了驴，就和摩押的官员一同去了。","notes":[],"heads":["巴兰和他的驴"]},{"n":22,"t":"神因他去就怒气发作；耶和华的使者站在路中间敌对他。他骑着驴，有两个仆人跟随他。","notes":[]},{"n":23,"t":"驴看见耶和华的使者站在路中间，手里有拔出来的刀，就离开了路，岔入田间。巴兰就打驴，要它回到路上。","notes":[]},{"n":24,"t":"耶和华的使者站在葡萄园的窄路上，这边有墙，那边也有墙。","notes":[]},{"n":25,"t":"驴看见耶和华的使者，就往墙挤去，把巴兰的脚挤到墙上；巴兰再打驴。","notes":[]},{"n":26,"t":"耶和华的使者又往前去，站在狭窄的地方，那里左右都无路可转。","notes":[]},{"n":27,"t":"驴看见耶和华的使者，就伏在巴兰底下。巴兰怒气发作，用杖打驴。","notes":[]},{"n":28,"t":"耶和华使驴开口，对巴兰说：“我向你做了什么，你竟打我这三次呢？”","notes":[]},{"n":29,"t":"巴兰对驴说：“因为你戏弄我，我恨不得手中有刀，现在就把你杀了。”","notes":[]},{"n":30,"t":"驴对巴兰说：“我不是你从小直到今天所骑的驴吗？我平时有这样待过你吗？”巴兰说：“没有。”","notes":[]},{"n":31,"t":"耶和华使巴兰的眼目明亮，他看见耶和华的使者站在路中间，手里有拔出来的刀；巴兰就低头俯伏下拜。","notes":[]},{"n":32,"t":"耶和华的使者对他说：“你为什么这三次打你的驴呢？看哪，我出来敌对你，因为这路在我面前已经偏离了。","notes":[]},{"n":33,"t":"驴看见我就从我面前回避了这三次；驴若没有回避我，我早把你杀了，留它存活。”","notes":[]},{"n":34,"t":"巴兰对耶和华的使者说：“我有罪了。我不知道你站在路中间阻挡我；现在你若看为不好，我就回去。”","notes":[]},{"n":35,"t":"耶和华的使者对巴兰说：“你和这些人去吧！你只要说我对你说的话。”于是巴兰和巴勒的官员一同去了。","notes":[]},{"n":36,"t":"巴勒听见巴兰来了，就到摩押的城去迎接他；这城是在边界的亚嫩河旁。","notes":["“摩押的城”：原文另译“亚珥．摩押”。"],"heads":["巴勒欢迎巴兰"]},{"n":37,"t":"巴勒对巴兰说：“我不是急切地派人到你那里去召你吗？你为何不到我这里来呢？我岂不能使你得尊荣吗？”","notes":[]},{"n":38,"t":"巴兰对巴勒说：“看哪，我已经到你这里来了！现在我岂能擅自说什么呢？神将什么话放在我口中，我就说什么。”","notes":[]},{"n":39,"t":"巴兰和巴勒同去，来到基列．胡琐。","notes":[]},{"n":40,"t":"巴勒宰了牛羊为祭物，送给巴兰和陪伴他的官员。","notes":[]},{"n":41,"t":"到了早晨，巴勒领巴兰到巴末．巴力，从那里可以看到一部分以色列的百姓。","notes":[],"heads":["巴兰首次预言"]}]},"23":{"heading":"巴兰第二次预言","verses":[{"n":1,"t":"巴兰对巴勒说：“你要在这里为我筑七座坛，又要在这里为我预备七头公牛、七只公羊。”","notes":[]},{"n":2,"t":"巴勒照巴兰的话做了。巴勒和巴兰在每座坛上献一头公牛、一只公羊。","notes":[]},{"n":3,"t":"巴兰对巴勒说：“你站在你的燔祭旁边，我要往前去，或许耶和华会向我显现。他指示我什么事，我必告诉你。”于是巴兰上到一个光秃的高地。","notes":[]},{"n":4,"t":"神向巴兰显现。巴兰对他说：“我预备了七座坛，在每座坛上献了一头公牛、一只公羊。”","notes":[]},{"n":5,"t":"耶和华把话放在巴兰口中，说：“你回到巴勒那里，要这样说。”","notes":[]},{"n":6,"t":"他就回到巴勒那里，看哪，巴勒和摩押的众官员站在燔祭旁边。","notes":[]},{"n":7,"t":"巴兰唱起诗歌说：“巴勒领我出亚兰，摩押王领我出东方的山脉：‘来啊，为我诅咒雅各；来啊，怒骂以色列。’","notes":[]},{"n":8,"t":"神没有诅咒的，我焉能诅咒？耶和华没有怒骂的，我岂能怒骂？","notes":[]},{"n":9,"t":"我从磐石的巅峰看到他，我从山丘望见他。看哪，这是独居的民，不算在列国中。","notes":[]},{"n":10,"t":"谁能数点雅各的尘土？谁能计算以色列的尘沙 ？我愿如正直人之死而死；我愿如正直人之终而终。”","notes":["“尘沙”或译“四分之一”。"]},{"n":11,"t":"巴勒对巴兰说：“你向我做的是什么呢？我带你来诅咒我的仇敌，看哪，你竟为他们祝福。”","notes":[]},{"n":12,"t":"他回答说：“耶和华放在我口中的话，我岂能不谨慎地说呢？”","notes":[]},{"n":13,"t":"巴勒对他说：“请你跟我到别的地方，在那里可以看见他们。你只能看见他们的一部分，却不能看见全部。请你在那里为我诅咒他们。”","notes":[]},{"n":14,"t":"于是巴勒领巴兰到了琐腓的田野，上了毗斯迦山顶，筑了七座坛，在每座坛上献一头公牛、一只公羊。","notes":["“到了...顶”或译“到了毗斯迦山顶上的瞭望台”。"]},{"n":15,"t":"巴兰对巴勒说：“你站在你的燔祭旁边，我要到那边去看看。”","notes":[]},{"n":16,"t":"耶和华向巴兰显现，把话放在他口中，说：“你回到巴勒那里，要这样说。”","notes":[]},{"n":17,"t":"他回到巴勒那里，看哪，巴勒站在燔祭旁边，摩押的官员也和他在一起。巴勒对他说：“耶和华说了什么呢？”","notes":[]},{"n":18,"t":"巴兰唱起诗歌说：“巴勒啊，起来，听；西拨的儿子啊，侧耳听我。","notes":[]},{"n":19,"t":"神非人，必不致说谎，也非人子，必不致后悔。他说了岂不照着做呢？他发了言岂不实现呢？","notes":[]},{"n":20,"t":"看哪，我奉命祝福；神赐福，我不能扭转。","notes":[]},{"n":21,"t":"他未见雅各中有灾难 ，也未见以色列中有祸患。耶和华－他的神和他同在；在他中间有欢呼王的声音。","notes":["“灾难”或译“罪孽”。","“祸患”或译“奸恶”。"]},{"n":22,"t":"神领他们出埃及，为以色列有如野牛的角。","notes":[]},{"n":23,"t":"绝没有法术可以伤雅各，没有占卜可以害以色列。现在，人论及雅各，论及以色列必说：‘神成就了何等的事啊！’","notes":[]},{"n":24,"t":"看哪，这百姓兴起如母狮，挺身像公狮，未曾吃猎物，未曾喝被杀者的血，绝不躺卧。”","notes":[]},{"n":25,"t":"巴勒对巴兰说：“你一点也不要诅咒他们，一点也不要为他们祝福！”","notes":[]},{"n":26,"t":"巴兰回答巴勒说：“我不是告诉过你：‘凡耶和华所说的，我必须遵行’吗？”","notes":[]},{"n":27,"t":"巴勒对巴兰说：“来，我领你到别的地方，或许神喜欢你在那里为我诅咒他们。”","notes":[]},{"n":28,"t":"巴勒就领巴兰到那可瞭望旷野的毗珥山顶。","notes":[]},{"n":29,"t":"巴兰对巴勒说：“你要在这里为我筑七座坛，又要在这里为我预备七头公牛、七只公羊。”","notes":[]},{"n":30,"t":"巴勒就照巴兰的话做，在每座坛上献一头公牛、一只公羊。","notes":[]}]},"24":{"heading":"巴兰第三次预言","verses":[{"n":1,"t":"巴兰见耶和华喜欢赐福给以色列，就不像前两次去求法术，却面向旷野。","notes":[]},{"n":2,"t":"巴兰举目，看见以色列人照着支派扎营。神的灵就临到他身上，","notes":[]},{"n":3,"t":"他唱起诗歌说：“比珥的儿子巴兰说，眼目关闭的人说，","notes":["“关闭”：七十士译本是“看得清楚”；下同。"]},{"n":4,"t":"听见神的言语，得见全能者的异象，俯伏着，眼睛却睁开的人说：","notes":[]},{"n":5,"t":"雅各啊，你的帐棚何等华美！以色列啊，你的帐幕何其华丽！","notes":[]},{"n":6,"t":"如连绵的山谷，如河畔的园子，如耶和华栽种的沉香树，又如水边的香柏木。","notes":[]},{"n":7,"t":"水要从他的桶里流出，种子要撒在多水之处。他的王必超越亚甲，他的国必要振兴。","notes":[]},{"n":8,"t":"神领他出埃及，为他有如野牛的角。他要吞灭那敌对他的国，压碎他们的骨头，用箭射透他们。","notes":[]},{"n":9,"t":"他蹲如公狮，卧如母狮，谁敢惹他？凡为你祝福的，愿他蒙福；凡诅咒你的，愿他受诅咒。”","notes":[]},{"n":10,"t":"巴勒向巴兰怒气发作，就紧握拳头。巴勒对巴兰说：“我召你来诅咒我的仇敌，看哪，你竟然这三次为他们祝福。","notes":["“紧握拳头”：原文直译“击掌”。"],"heads":["巴兰第四次预言"]},{"n":11,"t":"如今你赶快回本地去吧！我想使你大得尊荣，看哪，耶和华却阻止你得尊荣。”","notes":[]},{"n":12,"t":"巴兰对巴勒说：“我不是对你所差遣到我那里的使者说：","notes":[]},{"n":13,"t":"‘巴勒就是把他满屋的金银给我，我也不能违背耶和华的指示，随自己的心意做好做歹。耶和华说什么，我就说什么。’","notes":[]},{"n":14,"t":"现在，看哪，我要回到我的百姓那里。来，让我告诉你这百姓日后要怎样对待你的百姓。”","notes":[]},{"n":15,"t":"他就唱起诗歌说：“比珥的儿子巴兰说，眼目关闭的人说，","notes":[]},{"n":16,"t":"听见神的言语，明白至高者的知识，看见全能者的异象，俯伏着，眼睛却睁开的人说：","notes":[]},{"n":17,"t":"我看见他，却不在现时；我望见他，却不在近处。有星出于雅各，有杖从以色列兴起，必打破摩押的额头，必毁坏所有的塞特人 。","notes":["“必毁坏...塞特人”：有古卷是“所有塞特人的头顶”。"]},{"n":18,"t":"以东将成为产业，西珥将成为它敌人的产业；但以色列却要得胜。","notes":["“以东...它敌人的产业”或译“他必得以东为产业，又得仇敌之地西珥为产业”。"]},{"n":19,"t":"有一位出于雅各的，必掌大权，他要除灭城中的幸存者。”","notes":[]},{"n":20,"t":"巴兰看见亚玛力人，就唱起诗歌说：“亚玛力是诸国之首，但它终必永远沉沦。”","notes":["“但它终必永远沉沦”：撒玛利亚五经是“直到它终于沉沦”。"]},{"n":21,"t":"巴兰看见基尼人，就唱起诗歌说：“你的住处坚固；你的巢窝造在岩石中。","notes":[]},{"n":22,"t":"然而基尼族必被吞灭，直到何时亚述把你掳去？”","notes":["“基尼族”与“巢窝”的希伯来话发音相近。","“然而...掳去？”七十士译本是“虽然比珥有造得坚固的巢窝，亚述人必把你掳去。”"]},{"n":23,"t":"巴兰又唱起诗歌说：“哀哉！若神做这事，谁能存活呢？","notes":["“若神...存活呢？”原文另译“聚集在北方的那些人是谁呢？”"]},{"n":24,"t":"有船只从基提边界来到，要压制亚述，要压制希伯；他也必永远沉沦。”","notes":["“有船只”：七十士译本是“有人”。","“他也必永远沉沦”：撒玛利亚五经是“直到他沉沦”。"]},{"n":25,"t":"于是巴兰起来，回本地去；巴勒也回他的路去了。","notes":[]}]},"25":{"heading":"在毗珥拜巴力","verses":[{"n":1,"t":"以色列人住在什亭，百姓开始与摩押女子行淫。","notes":[]},{"n":2,"t":"这些女子请百姓一同为她们的神明献祭，百姓吃了祭物，跪拜她们的神明。","notes":[]},{"n":3,"t":"以色列与巴力．毗珥联合，耶和华的怒气就向以色列发作。","notes":[]},{"n":4,"t":"耶和华对摩西说：“拿下百姓中所有的领袖，对着太阳把他们悬挂在我面前，使我向以色列所发的怒气可以平息。”","notes":[]},{"n":5,"t":"于是摩西对以色列的审判官说：“你们的人若有与巴力．毗珥联合的，你们各人就要把他们杀了。”","notes":[]},{"n":6,"t":"摩西和以色列全会众在会幕门口哭泣的时候，看哪，有一个以色列人，在他们眼前带着一个米甸女子，到他弟兄那里。","notes":[]},{"n":7,"t":"亚伦祭司的孙子，以利亚撒的儿子非尼哈看见了，就从会众中起来，手里拿着枪，","notes":[]},{"n":8,"t":"跟这以色列人进入帐棚，刺穿了二人，就是以色列人和那女子的肚腹。这样，以色列人遭受的瘟疫就停止了。","notes":[]},{"n":9,"t":"遭瘟疫死的，有二万四千人。","notes":[]},{"n":10,"t":"耶和华吩咐摩西说：","notes":[]},{"n":11,"t":"“亚伦祭司的孙子，以利亚撒的儿子非尼哈，使我的愤怒转离以色列人，因为在他们中间，他以我的妒忌为他的妒忌，使我不在妒忌中毁灭以色列人。","notes":[]},{"n":12,"t":"因此，你要说：‘看哪，我将我平安的约赐给他。","notes":[]},{"n":13,"t":"这是他和他的后裔永远当祭司职任的约，因他为了神而妒忌，他为以色列人赎罪。’”","notes":[]},{"n":14,"t":"那与米甸女子一起被杀的以色列人，名叫心利，是撒路的儿子，是西缅一个父家的领袖。","notes":[]},{"n":15,"t":"那被杀的米甸女子，名叫哥斯比，是苏珥的女儿；苏珥是米甸一个父家的领袖。","notes":[]},{"n":16,"t":"耶和华吩咐摩西说：","notes":[]},{"n":17,"t":"“你要苦害米甸人，击杀他们；","notes":[]},{"n":18,"t":"因为他们用诡计苦害你们，在毗珥的事上和他们的姊妹，米甸领袖的女儿哥斯比的事上，欺骗了你们；在瘟疫的日子，这女子因毗珥的事件被杀了。”","notes":[]}]},"26":{"heading":"第二次人口普查","verses":[{"n":1,"t":"瘟疫过了之后，耶和华对摩西和亚伦祭司的儿子以利亚撒说：","notes":[]},{"n":2,"t":"“你们要将以色列全会众，按他们的父家，凡二十岁以上能出去为以色列打仗的，计算总数。”","notes":[]},{"n":3,"t":"摩西和以利亚撒祭司在摩押平原与耶利哥相对的约旦河边吩咐他们说：","notes":[]},{"n":4,"t":"“计算你们中间从二十岁以上的人数。”正如耶和华所吩咐摩西的。从埃及地出来的以色列人如下：","notes":[]},{"n":5,"t":"以色列的长子是吕便。吕便的众子：属哈诺的，有哈诺族；属法路的，有法路族；","notes":[]},{"n":6,"t":"属希斯伦的，有希斯伦族；属迦米的，有迦米族。","notes":[]},{"n":7,"t":"这就是吕便的各族；被数的共有四万三千七百三十名。","notes":[]},{"n":8,"t":"法路的儿子是以利押。","notes":[]},{"n":9,"t":"以利押的儿子是尼母利、大坍、亚比兰。这大坍、亚比兰，就是从会中选出来，当可拉一伙的人向耶和华争闹的时候，一起向摩西、亚伦争闹的；","notes":[]},{"n":10,"t":"地开了裂口，吞了他们和可拉，可拉一伙的人也一同死亡。当时火吞灭了二百五十个人；他们就成为鉴戒。","notes":[]},{"n":11,"t":"然而可拉的众子没有死亡。","notes":[]},{"n":12,"t":"按着宗族，西缅的众子：属尼母利的，有尼母利族；属雅悯的，有雅悯族；属雅斤的，有雅斤族；","notes":[]},{"n":13,"t":"属谢拉的，有谢拉族；属扫罗的，有扫罗族。","notes":[]},{"n":14,"t":"这就是西缅的各族，共有二万二千二百名。","notes":[]},{"n":15,"t":"按着宗族，迦得的众子：属洗分的，有洗分族；属哈基的，有哈基族；属书尼的，有书尼族；","notes":[]},{"n":16,"t":"属阿斯尼的，有阿斯尼族；属以利的，有以利族；","notes":[]},{"n":17,"t":"属亚律的，有亚律族；属亚列利的，有亚列利族。","notes":[]},{"n":18,"t":"这就是迦得子孙的各族；他们被数的共有四万零五百名。","notes":[]},{"n":19,"t":"犹大的儿子是珥和俄南。珥和俄南死在迦南地。","notes":[]},{"n":20,"t":"按着宗族，犹大的众子：属示拉的，有示拉族；属法勒斯的，有法勒斯族；属谢拉的，有谢拉族。","notes":[]},{"n":21,"t":"法勒斯的众子：属希斯仑的，有希斯仑族；属哈母勒的，有哈母勒族。","notes":[]},{"n":22,"t":"这就是犹大的各族；他们被数的共有七万六千五百名。","notes":[]},{"n":23,"t":"按着宗族，以萨迦的众子：属陀拉的，有陀拉族；属普瓦的，有普瓦族；","notes":[]},{"n":24,"t":"属雅述的，有雅述族；属伸仑的，有伸仑族。","notes":[]},{"n":25,"t":"这就是以萨迦的各族；他们被数的共有六万四千三百名。","notes":[]},{"n":26,"t":"按着宗族，西布伦的众子：属西烈的，有西烈族；属以伦的，有以伦族；属雅利的，有雅利族。","notes":[]},{"n":27,"t":"这就是西布伦的各族；他们被数的共有六万零五百名。","notes":[]},{"n":28,"t":"按着宗族，约瑟的儿子有玛拿西、以法莲。","notes":[]},{"n":29,"t":"玛拿西的众子：属玛吉的，有玛吉族；玛吉生基列；属基列的，有基列族。","notes":[]},{"n":30,"t":"这就是基列的众子：属伊以谢的，有伊以谢族；属希勒的，有希勒族；","notes":[]},{"n":31,"t":"属亚斯烈的，有亚斯烈族；属示剑的，有示剑族；","notes":[]},{"n":32,"t":"属示米大的，有示米大族；属希弗的，有希弗族。","notes":[]},{"n":33,"t":"希弗的儿子西罗非哈没有儿子，只有女儿。西罗非哈的女儿的名字是玛拉、挪阿、曷拉、密迦、得撒。","notes":[]},{"n":34,"t":"这就是玛拿西的各族；他们被数的共有五万二千七百名。","notes":[]},{"n":35,"t":"这就是按着宗族，以法莲的众子：属书提拉的，有书提拉族；属比结的，有比结族；属他罕的，有他罕族。","notes":[]},{"n":36,"t":"这就是书提拉的众子：属以兰的，有以兰族。","notes":[]},{"n":37,"t":"这就是以法莲子孙的各族；他们被数的共有三万二千五百名。按着宗族，以上这些都是约瑟的子孙。","notes":[]},{"n":38,"t":"按着宗族，便雅悯的众子：属比拉的，有比拉族；属亚实别的，有亚实别族；属亚希兰的，有亚希兰族；","notes":[]},{"n":39,"t":"属书反的，有书反族；属户反的，有户反族。","notes":[]},{"n":40,"t":"比拉的儿子是亚勒、乃幔；属亚勒的，有亚勒族；属乃幔的，有乃幔族。","notes":["“属亚勒的”是根据某些古卷和七十士译本，原文没有。"]},{"n":41,"t":"按着宗族，这就是便雅悯的子孙；他们被数的共有四万五千六百名。","notes":[]},{"n":42,"t":"这就是按着宗族，但的众子：属书含的，有书含族。按着宗族，这就是但的各族。","notes":[]},{"n":43,"t":"按照他们被数的，书含全宗族共有六万四千四百名。","notes":[]},{"n":44,"t":"按着宗族，亚设的众子：属音拿的，有音拿族；属亦施韦的，有亦施韦族；属比利亚的，有比利亚族。","notes":[]},{"n":45,"t":"比利亚的众子：属希别的，有希别族；属玛结的，有玛结族。","notes":[]},{"n":46,"t":"亚设的女儿名叫西拉。","notes":[]},{"n":47,"t":"这就是亚设子孙的各族；他们被数的共有五万三千四百名。","notes":[]},{"n":48,"t":"按着宗族，拿弗他利的众子：属雅薛的，有雅薛族；属沽尼的，有沽尼族；","notes":[]},{"n":49,"t":"属耶色的，有耶色族；属示冷的，有示冷族。","notes":[]},{"n":50,"t":"按着宗族，这就是拿弗他利的各族；他们被数的共有四万五千四百名。","notes":[]},{"n":51,"t":"这就是以色列人中被数的，共有六十万零一千七百三十名。","notes":[]},{"n":52,"t":"耶和华吩咐摩西说：","notes":[]},{"n":53,"t":"“你要按着人名的数目，将地分给这些人为产业。","notes":[]},{"n":54,"t":"人多的要多给他们产业，人少的要少给他们产业；各照被数的人数分配产业。","notes":[]},{"n":55,"t":"此外，要以抽签来分地，按着父系各支派的名字承受产业。","notes":[]},{"n":56,"t":"要根据抽签，看人数的多寡，给他们分配产业。”","notes":[]},{"n":57,"t":"这就是按着宗族，被数的利未人：属革顺的，有革顺族；属哥辖的，有哥辖族；属米拉利的，有米拉利族。","notes":[]},{"n":58,"t":"这就是利未的宗族：立尼族、希伯伦族、玛利族、母示族、可拉族。哥辖生暗兰。","notes":[]},{"n":59,"t":"暗兰的妻子名叫约基别，是利未的女儿，是利未在埃及所生的。她给暗兰生了亚伦、摩西，和他们的姊姊米利暗。","notes":[]},{"n":60,"t":"亚伦生拿答、亚比户、以利亚撒、以他玛。","notes":[]},{"n":61,"t":"拿答、亚比户在耶和华面前献凡火的时候死了。","notes":[]},{"n":62,"t":"利未人中，凡一个月以上所有被数的男子，共有二万三千名。他们没有数在以色列人中；因为在以色列人中，没有分给他们产业。","notes":[]},{"n":63,"t":"这些是摩西和以利亚撒祭司所数的；他们在摩押平原与耶利哥相对的约旦河边数点以色列人。","notes":[]},{"n":64,"t":"这些被数的人中，没有一个是摩西和亚伦祭司先前在西奈旷野所数的以色列人，","notes":[]},{"n":65,"t":"因为耶和华论到他们说：“他们必死在旷野。”所以，除了耶孚尼的儿子迦勒和嫩的儿子约书亚以外，他们一个也没有存留。","notes":[]}]},"27":{"heading":"西罗非哈的女儿","verses":[{"n":1,"t":"约瑟的儿子玛拿西的宗族中，有玛拿西的玄孙，玛吉的曾孙，基列的孙子，希弗的儿子西罗非哈的女儿，名叫玛拉、挪阿、曷拉、密迦、得撒。她们前来，","notes":[]},{"n":2,"t":"站在会幕门口，在摩西和以利亚撒祭司，以及众领袖与全会众面前，说：","notes":[]},{"n":3,"t":"“我们的父亲死在旷野。他没有与可拉同伙聚集攻击耶和华，是在自己的罪中死的；他没有儿子。","notes":[]},{"n":4,"t":"为什么因我们的父亲没有儿子就把他的名从他族中除掉呢？求你们在我们父亲的兄弟中分给我们产业。”","notes":[]},{"n":5,"t":"于是，摩西将她们的案件呈到耶和华面前。","notes":[]},{"n":6,"t":"耶和华对摩西说：","notes":[]},{"n":7,"t":"“西罗非哈的女儿说得有理。你定要在她们父亲的兄弟中，把地分给她们为业，把她们父亲的产业传给她们。","notes":[]},{"n":8,"t":"你也要吩咐以色列人说：‘人死了，若没有儿子，就要把他的产业传给他的女儿。","notes":[]},{"n":9,"t":"他若没有女儿，就要把他的产业给他的兄弟。","notes":[]},{"n":10,"t":"他若没有兄弟，就要把他的产业给他父亲的兄弟。","notes":[]},{"n":11,"t":"他父亲若没有兄弟，就要把他的产业给他族中最近的亲属继承为业。’”这要作以色列人的律例典章，是照耶和华所吩咐摩西的。","notes":[]},{"n":12,"t":"耶和华对摩西说：“你上这亚巴琳山脉，看我所赐给以色列人的地。","notes":[],"heads":["约书亚被选为摩西的继承人"]},{"n":13,"t":"看了以后，你也必归到你祖先那里，像你哥哥亚伦归去一样。","notes":["“你祖先”：原文是“你百姓”。"]},{"n":14,"t":"因为你们在寻的旷野，当会众争闹的时候，违背了我的命令，在取水之事上没有在会众眼前尊我为圣。”这水就是寻的旷野中，加低斯的米利巴水。","notes":[]},{"n":15,"t":"摩西对耶和华说：","notes":[]},{"n":16,"t":"“愿耶和华，赐万人气息的神，立一个人治理会众，","notes":[]},{"n":17,"t":"可以在他们面前出入，引导他们进出，免得耶和华的会众如同没有牧人的羊群一般。”","notes":[]},{"n":18,"t":"耶和华对摩西说：“嫩的儿子约书亚是一个有圣灵的人；你要领他来，为他按手，","notes":[]},{"n":19,"t":"使他站在以利亚撒祭司和全会众面前，在他们眼前委派他，","notes":[]},{"n":20,"t":"又将你的尊荣给他一些，好使以色列全会众都听从他。","notes":[]},{"n":21,"t":"他要站在以利亚撒祭司面前；以利亚撒要凭乌陵的判断，在耶和华面前为他求问。他和以色列全会众都要照以利亚撒的指示出入。”","notes":[]},{"n":22,"t":"于是摩西照耶和华所吩咐他的，将约书亚领来，使他站在以利亚撒祭司和全会众面前，","notes":[]},{"n":23,"t":"为他按手，委派他，是照耶和华藉摩西所说的。","notes":[]}]},"28":{"heading":"每日经常献的祭","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人说：‘你们要按时把我的供物，就是献给我作馨香火祭的食物，献给我。’","notes":[]},{"n":3,"t":"要对他们说：‘这是当献给耶和华的火祭：每天两只没有残疾一岁的小公羊，作为经常献的燔祭。","notes":[]},{"n":4,"t":"早晨献第一只小公羊，黄昏献第二只小公羊；","notes":[]},{"n":5,"t":"又用十分之一伊法细面和四分之一欣捣成的油，调和作为素祭。","notes":[]},{"n":6,"t":"这是在西奈山上规定为经常献的燔祭，是献给耶和华为馨香的火祭。","notes":[]},{"n":7,"t":"为每只小公羊，要有四分之一欣的浇酒祭；在圣所中，你要将醇酒献给耶和华作浇酒祭。","notes":[]},{"n":8,"t":"黄昏你献第二只小公羊，要照早晨的素祭和同献的浇酒祭献上，作为馨香的火祭，献给耶和华。’”","notes":[]},{"n":9,"t":"“在安息日，要献两只没有残疾，一岁的小公羊、十分之二伊法调了油的细面为素祭，和同献的浇酒祭。","notes":[],"heads":["安息日献的祭"]},{"n":10,"t":"除了经常献的燔祭和同献的浇酒祭之外，这是每一个安息日当献的燔祭。”","notes":[]},{"n":11,"t":"“每月初一，要将两头公牛犊、一只公绵羊、七只没有残疾一岁的小公羊，献给耶和华为燔祭。","notes":[],"heads":["初一献的祭"]},{"n":12,"t":"为每头公牛，要用十分之三伊法调了油的细面作为素祭；为那只公绵羊，要用十分之二伊法调了油的细面作为素祭；","notes":[]},{"n":13,"t":"为每只小公羊，要用十分之一伊法调了油的细面作为素祭。这是馨香的燔祭，是献给耶和华的火祭。","notes":[]},{"n":14,"t":"每头公牛要有半欣的浇酒祭，每只公绵羊三分之一欣的浇酒祭，每只小公羊四分之一欣的浇酒祭。这是一年之中每月初一当献的燔祭。","notes":[]},{"n":15,"t":"除了经常献的燔祭和同献的浇酒祭之外，又要将一只公山羊，献给耶和华为赎罪祭。”","notes":[]},{"n":16,"t":"“正月十四日是向耶和华守的逾越节。","notes":[],"heads":["逾越节献的祭"]},{"n":17,"t":"这月十五日是节期，要吃无酵饼七日。","notes":[]},{"n":18,"t":"第一日要有圣会，任何劳动的工都不可做。","notes":[]},{"n":19,"t":"要把火祭，就是两头公牛犊，一只公绵羊、七只一岁的小公羊，都要没有残疾的，献给耶和华为燔祭。","notes":[]},{"n":20,"t":"要同时献调了油的细面为素祭：每头公牛要献十分之三伊法；每只公绵羊要献十分之二伊法；","notes":[]},{"n":21,"t":"为那七只小公羊，每只要献十分之一伊法。","notes":[]},{"n":22,"t":"此外，要献一只公山羊作赎罪祭，为你们赎罪。","notes":[]},{"n":23,"t":"除了早晨经常献的燔祭之外，你们也要献这些祭。","notes":[]},{"n":24,"t":"一连七天，在经常献的燔祭和同献的浇酒祭之外，每天要这样把馨香火祭的食物献给耶和华。","notes":[]},{"n":25,"t":"第七日要有圣会，任何劳动的工都不可做。”","notes":[]},{"n":26,"t":"“七七初熟节，就是你们献初熟谷物给耶和华为素祭的那一天，要宣告圣会；任何劳动的工都不可做。","notes":[],"heads":["七七初熟节献的祭"]},{"n":27,"t":"要将两头公牛犊，一只公绵羊，七只一岁的小公羊，作为馨香的燔祭献给耶和华。","notes":[]},{"n":28,"t":"要同时献调了油的细面为素祭：每头公牛要献十分之三伊法；每只公绵羊要献十分之二伊法；","notes":[]},{"n":29,"t":"为那七只小公羊，每只要献十分之一伊法。","notes":[]},{"n":30,"t":"此外，要献一只公山羊为你们赎罪。","notes":[]},{"n":31,"t":"除了经常献的燔祭和同献的素祭，你们也要献上这些没有残疾的，和同献的浇酒祭。”","notes":[]}]},"29":{"heading":"新年献的祭","verses":[{"n":1,"t":"“七月初一，你们当有圣会；任何劳动的工都不可做，是你们当守为吹角的日子。","notes":[]},{"n":2,"t":"你们要将一头公牛犊、一只公绵羊、七只一岁的小公羊，都是没有残疾的，献给耶和华为馨香的燔祭。","notes":[]},{"n":3,"t":"要同时献调了油的细面为素祭：每头公牛要献十分之三伊法；每只公绵羊要献十分之二伊法；","notes":[]},{"n":4,"t":"为那七只小公羊，每只要献十分之一伊法。","notes":[]},{"n":5,"t":"此外，要献一只公山羊作赎罪祭，为你们赎罪。","notes":[]},{"n":6,"t":"除了初一的燔祭和同献的素祭、经常献的燔祭与同献的素祭，以及同献的浇酒祭以外，这些都照例作为馨香的火祭献给耶和华。”","notes":[]},{"n":7,"t":"“七月初十，你们当有圣会；要刻苦己心，任何工都不可做。","notes":[],"heads":["赎罪日献的祭"]},{"n":8,"t":"要将一头公牛犊、一只公绵羊、七只一岁的小公羊，都是没有残疾的，献给耶和华为馨香的燔祭。","notes":[]},{"n":9,"t":"要同时献调了油的细面为素祭：每头公牛要献十分之三伊法；每只公绵羊要献十分之二伊法；","notes":[]},{"n":10,"t":"为那七只小公羊，每只要献十分之一伊法。","notes":[]},{"n":11,"t":"又要献一只公山羊为赎罪祭。这是在赎罪祭和经常献的燔祭，以及同献的素祭和浇酒祭以外所献的。”","notes":[]},{"n":12,"t":"“七月十五日，你们当有圣会；任何劳动的工都不可做，要向耶和华守节七天。","notes":[],"heads":["住棚节献的祭"]},{"n":13,"t":"要将十三头公牛犊、两只公绵羊、十四只一岁的小公羊，都是没有残疾的，献上作火祭，是献给耶和华馨香的燔祭。","notes":[]},{"n":14,"t":"要同时献调了油的细面为素祭：为那十三头公牛犊，每头要献十分之三伊法；为那两只公绵羊，每只要献十分之二伊法；","notes":[]},{"n":15,"t":"为那十四只小公羊，每只要献十分之一伊法。","notes":[]},{"n":16,"t":"又要献一只公山羊为赎罪祭。这是在经常献的燔祭、同献的素祭和浇酒祭以外所献的。","notes":[]},{"n":17,"t":"“第二日要献十二头公牛犊、两只公绵羊、十四只一岁的小公羊，都是没有残疾的，","notes":[]},{"n":18,"t":"并为公牛、公绵羊和小公羊，按数照例奉献同献的素祭和浇酒祭。","notes":[]},{"n":19,"t":"又要献一只公山羊为赎罪祭。这是在经常献的燔祭、同献的素祭和浇酒祭以外所献的。","notes":[]},{"n":20,"t":"“第三日要献十一头公牛、两只公绵羊、十四只一岁的小公羊，都是没有残疾的，","notes":[]},{"n":21,"t":"并为公牛、公绵羊和小公羊，按数照例奉献同献的素祭和浇酒祭。","notes":[]},{"n":22,"t":"又要献一只公山羊为赎罪祭。这是在经常献的燔祭、同献的素祭和浇酒祭以外所献的。","notes":[]},{"n":23,"t":"“第四日要献十头公牛、两只公绵羊、十四只一岁的小公羊，都是没有残疾的，","notes":[]},{"n":24,"t":"并为公牛、公绵羊和小公羊，按数照例奉献同献的素祭和浇酒祭。","notes":[]},{"n":25,"t":"又要献一只公山羊为赎罪祭。这是在经常献的燔祭、同献的素祭和浇酒祭以外所献的。","notes":[]},{"n":26,"t":"“第五日要献九头公牛、两只公绵羊、十四只一岁的小公羊，都是没有残疾的，","notes":[]},{"n":27,"t":"并为公牛、公绵羊和小公羊，按数照例奉献同献的素祭和浇酒祭。","notes":[]},{"n":28,"t":"又要献一只公山羊为赎罪祭。这是在经常献的燔祭、同献的素祭和浇酒祭以外所献的。","notes":[]},{"n":29,"t":"“第六日要献八头公牛、两只公绵羊、十四只一岁的小公羊，都是没有残疾的，","notes":[]},{"n":30,"t":"并为公牛、公绵羊和小公羊，按数照例奉献同献的素祭和浇酒祭。","notes":[]},{"n":31,"t":"又要献一只公山羊为赎罪祭。这是在经常献的燔祭、同献的素祭和浇酒祭以外所献的。","notes":[]},{"n":32,"t":"“第七日要献七头公牛、两只公绵羊、十四只一岁的小公羊，都是没有残疾的，","notes":[]},{"n":33,"t":"并为公牛、公绵羊和小公羊，按数照例奉献同献的素祭和浇酒祭。","notes":[]},{"n":34,"t":"又要献一只公山羊为赎罪祭。这是在经常献的燔祭、同献的素祭和浇酒祭以外所献的。","notes":[]},{"n":35,"t":"“第八日你们当有严肃会；任何劳动的工都不可做；","notes":[]},{"n":36,"t":"要将一头公牛、一只公绵羊、七只一岁的小公羊，都是没有残疾的，献上作火祭，是献给耶和华馨香的燔祭。","notes":[]},{"n":37,"t":"要为公牛、公绵羊和小公羊，按数照例奉献同献的素祭和浇酒祭。","notes":[]},{"n":38,"t":"又要献一只公山羊为赎罪祭。这是在经常献的燔祭、同献的素祭和浇酒祭以外所献的。","notes":[]},{"n":39,"t":"“这些祭要在你们的节期献给耶和华，都是在所许的愿和甘心献的以外所献的，作为你们的燔祭、素祭、浇酒祭和平安祭。”","notes":[]},{"n":40,"t":"于是，摩西照耶和华所吩咐他的一切话告诉以色列人。","notes":[]}]},"30":{"heading":"许愿的条例","verses":[{"n":1,"t":"摩西对以色列各支派的领袖说：“这是耶和华所吩咐的话：","notes":[]},{"n":2,"t":"人若向耶和华许愿或起誓，要约束自己，就不可食言，必须照口中所出的一切话去做。","notes":[]},{"n":3,"t":"女子年轻，还在父家的时候，若向耶和华许愿，要约束自己，","notes":[]},{"n":4,"t":"她父亲听见她所许的愿和约束自己的话，却向她默默不言，她所许的愿和约束自己的话就都有效。","notes":[]},{"n":5,"t":"但是，若她父亲在听见的日子不允许她一切所许的愿和约束自己的话，这就不算为有效；耶和华也必赦免她，因为她的父亲不允许。","notes":[]},{"n":6,"t":"她若已出嫁，有愿在身，或口中出了约束自己的冒失话，","notes":[]},{"n":7,"t":"她丈夫听见了，却在听见的日子向她默默不言，她所许的愿和约束自己的话就都有效。","notes":[]},{"n":8,"t":"但是，若她丈夫在听见的日子不允许，丈夫就废了她所许的愿和口中所出约束自己的冒失话；耶和华也必赦免她。","notes":[]},{"n":9,"t":"寡妇或被休的妇人所许的愿，她所有约束自己的话，都是有效的。","notes":[]},{"n":10,"t":"她若在丈夫家里许了愿或起了誓，要约束自己，","notes":[]},{"n":11,"t":"丈夫听见了，却向她默默不言，没有不允许，她所许的愿和约束自己的话就都有效。","notes":[]},{"n":12,"t":"她丈夫听见的日子，若把这些全废了，她口中一切所许的愿或约束自己的话就不算为有效。她丈夫已把这些都废了，耶和华也必赦免她。","notes":[]},{"n":13,"t":"凡她所许的愿和刻苦约束自己所起的誓，丈夫可以坚立，也可以废去。","notes":[]},{"n":14,"t":"倘若她丈夫天天向她默默不言，这就算是坚立她一切所许的愿或约束自己的话；因为丈夫在听见的日子向她默默不言，就算是坚立了这些话。","notes":[]},{"n":15,"t":"但她丈夫听见了，以后若再废了这些话，就要担当妇人的罪孽。”","notes":[]},{"n":16,"t":"这是关于丈夫待妻子，父亲待女儿，女儿年轻还在父家，耶和华所吩咐摩西的条例。","notes":[]}]},"31":{"heading":"战胜米甸人","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要为以色列人向米甸人报仇，然后归到你祖先那里。”","notes":["“你祖先”：原文是“你百姓”。"]},{"n":3,"t":"摩西吩咐百姓说：“要在你们中间叫人带兵器去攻击米甸，为耶和华向米甸报仇。","notes":[]},{"n":4,"t":"从以色列众支派中，每支派要派一千人去打仗。”","notes":[]},{"n":5,"t":"于是从以色列千万人中，每支派征召一千人，一共一万二千名，带着兵器预备打仗。","notes":[]},{"n":6,"t":"摩西派他们去打仗，每支派一千人；又派以利亚撒祭司的儿子非尼哈同去；非尼哈手里拿着圣所的器皿和吹号的号筒。","notes":[]},{"n":7,"t":"他们遵照耶和华所吩咐摩西的，与米甸打仗，杀了所有的男丁。","notes":[]},{"n":8,"t":"在所杀的人中，他们杀了米甸的王，就是以未、利金、苏珥、户珥、利巴五个米甸的王，又用刀杀了比珥的儿子巴兰。","notes":[]},{"n":9,"t":"以色列人掳了米甸的妇女和孩童，抢夺他们一切的牲畜、牛羊和所有的财物，","notes":[]},{"n":10,"t":"又用火焚烧了他们所住的一切城镇和所有的营寨。","notes":[]},{"n":11,"t":"以色列人把一切掳物和掠物，连人和牲畜都带走，","notes":[]},{"n":12,"t":"将俘虏、掠物、掳物带到摩押平原，在约旦河边与耶利哥相对的营地，交给摩西和以利亚撒祭司，以及以色列的会众。","notes":[]},{"n":13,"t":"摩西和以利亚撒祭司，以及会众中所有的领袖，都出营迎接他们。","notes":[],"heads":["军队返回"]},{"n":14,"t":"摩西向打仗回来的军官，就是千夫长和百夫长发怒。","notes":[]},{"n":15,"t":"摩西对他们说：“你们要让这所有的妇女活着吗？","notes":[]},{"n":16,"t":"看哪，正是这些妇女，因巴兰的话，在毗珥的事上导致以色列人背叛耶和华，以致耶和华的会众遭遇瘟疫。","notes":[]},{"n":17,"t":"现在，你们要杀所有的男孩，也要把所有曾与男人同房共寝的女子都杀了。","notes":[]},{"n":18,"t":"但那些未曾与男人同房共寝的女孩，你们可以让她们存活。","notes":[]},{"n":19,"t":"你们和你们所掳来的人，要住在营外七天；凡杀了人的，和一切摸了尸体的，要在第三日和第七日洁净自己。","notes":[]},{"n":20,"t":"你们也要洁净一切的衣服，以及用皮革、山羊毛和木头做的任何东西。”","notes":[]},{"n":21,"t":"以利亚撒祭司对打仗回来的士兵说：“耶和华所吩咐摩西律法中的条例是这样：","notes":[]},{"n":22,"t":"金、银、铜、铁、锡、铅，","notes":[]},{"n":23,"t":"凡能耐火的，你们要使它经过火，它就洁净，然而还要用除污秽的水来洁净它；凡不能耐火的，你们要使它经过水。","notes":[]},{"n":24,"t":"第七日，你们要洗衣服，才为洁净，然后可以进营。”","notes":[]},{"n":25,"t":"耶和华对摩西说：","notes":[],"heads":["分战利品"]},{"n":26,"t":"“你和以利亚撒祭司，以及会众的各父系家长，要计算所掳掠的人和牲畜的总数。","notes":[]},{"n":27,"t":"要把所掳掠的分成两半：一半给那出去打仗的精兵，一半给全会众。","notes":[]},{"n":28,"t":"再从那出去打仗的战士所得的人、牛、驴、羊中，每五百取一，献给耶和华为贡物。","notes":[]},{"n":29,"t":"要从他们那一半中取出这些，交给以利亚撒祭司，作为耶和华的举祭。","notes":[]},{"n":30,"t":"又要从以色列人的那一半中，就是从人、牛、驴、羊，各样牲畜中，每五十取一，交给照管耶和华帐幕的利未人。”","notes":[]},{"n":31,"t":"于是摩西和以利亚撒祭司遵照耶和华所吩咐摩西的做了。","notes":[]},{"n":32,"t":"除了士兵所夺的财物以外，所掳来的有羊六十七万五千只，","notes":[]},{"n":33,"t":"牛七万二千头，","notes":[]},{"n":34,"t":"驴六万一千匹；","notes":[]},{"n":35,"t":"至于人，就是未曾与男人同房共寝的女子，总共三万二千名。","notes":[]},{"n":36,"t":"出去打仗之人的那份，就是他们所得的一半，共计羊三十三万七千五百只，","notes":[]},{"n":37,"t":"其中归耶和华为贡物的羊，六百七十五只；","notes":[]},{"n":38,"t":"牛三万六千头，其中归耶和华为贡物的七十二头；","notes":[]},{"n":39,"t":"驴三万零五百匹，其中归耶和华为贡物的六十一匹；","notes":[]},{"n":40,"t":"人一万六千名，其中归耶和华的三十二名。","notes":[]},{"n":41,"t":"摩西把贡物，就是归给耶和华的举祭，交给以利亚撒祭司，是照耶和华所吩咐摩西的。","notes":[]},{"n":42,"t":"以色列人所得的另一半，是摩西从打仗的人取来分给他们的。","notes":[]},{"n":43,"t":"会众的这一半有羊三十三万七千五百只，","notes":[]},{"n":44,"t":"牛三万六千头，","notes":[]},{"n":45,"t":"驴三万零五百匹，","notes":[]},{"n":46,"t":"人一万六千名。","notes":[]},{"n":47,"t":"无论是人或牲畜，摩西都每五十取一，交给照管耶和华帐幕的利未人，是照耶和华所吩咐摩西的。","notes":[]},{"n":48,"t":"带领众军队的军官，就是千夫长、百夫长，进到摩西那里，","notes":[]},{"n":49,"t":"对他说：“你的仆人已经计算属下战士的总数，一个也没有少。","notes":[]},{"n":50,"t":"如今我们把各人所得的金器，就是脚链子、手镯、打印的戒指、耳环、项链，都送给耶和华为供物，好在耶和华面前为我们赎罪。”","notes":[]},{"n":51,"t":"摩西和以利亚撒祭司就收了他们的金子，就是各样的首饰。","notes":[]},{"n":52,"t":"千夫长、百夫长所献给耶和华为举祭的金子共有一万六千七百五十舍客勒。","notes":[]},{"n":53,"t":"打仗的人都把自己所掠夺的各自留下。","notes":[]},{"n":54,"t":"摩西和以利亚撒祭司收了千夫长、百夫长的金子，就带进会幕，好使以色列人在耶和华面前蒙记念。","notes":[]}]},"32":{"heading":"约旦河东的支派","verses":[{"n":1,"t":"吕便子孙和迦得子孙的牲畜极其众多。他们看到雅谢地和基列地；看哪，这是可牧放牲畜的地方。","notes":[]},{"n":2,"t":"吕便子孙和迦得子孙就到摩西和以利亚撒祭司，以及会众的领袖那里，说：","notes":[]},{"n":3,"t":"“亚他录、底本、雅谢、宁拉、希实本、以利亚利、示班、尼波、比稳，","notes":[]},{"n":4,"t":"就是耶和华在以色列会众面前所攻取之地，是可牧放牲畜之地，而你的仆人也有牲畜。”","notes":[]},{"n":5,"t":"又说：“我们若在你眼前蒙恩，求你把这地给我们为业；不要领我们过约旦河。”","notes":[]},{"n":6,"t":"摩西对迦得子孙和吕便子孙说：“难道你们的弟兄去打仗，你们却留在这里吗？","notes":[]},{"n":7,"t":"你们为什么使以色列人灰心，不渡过去，进入耶和华所赐给他们的那地呢？","notes":[]},{"n":8,"t":"我从加低斯．巴尼亚派你们的父执之辈去窥探那地时，他们就曾这样做过。","notes":[]},{"n":9,"t":"他们上到以实各谷，窥探了那地之后，竟然使以色列人灰心，不愿进入耶和华所赐给他们的地。","notes":[]},{"n":10,"t":"当日，耶和华的怒气发作，起誓说：","notes":[]},{"n":11,"t":"‘凡从埃及上来二十岁以上的人，断不得看见我对亚伯拉罕、以撒、雅各起誓应许之地，因为他们没有专心跟从我；","notes":[]},{"n":12,"t":"惟有基尼洗族耶孚尼的儿子迦勒，还有嫩的儿子约书亚可以看见，因为他们专心跟从耶和华。’","notes":[]},{"n":13,"t":"耶和华的怒气向以色列发作，使他们在旷野飘流四十年，直到在耶和华眼前作恶的那一代都消灭了。","notes":[]},{"n":14,"t":"看哪，你们这一伙罪人，竟然接续你们父执之辈，再增加耶和华对以色列所发的怒气。","notes":[]},{"n":15,"t":"你们若转离不跟从他，他要再把以色列人撇在旷野；这样，你们就使这众百姓灭亡了。”","notes":[]},{"n":16,"t":"他们挨近摩西，说：“我们要在这里为牲畜筑圈，为孩童建城。","notes":[]},{"n":17,"t":"我们自己却要带兵器，急速行在以色列人的前面，领他们直到他们的地方。我们的孩童可以留在坚固的城内，躲避当地的居民。","notes":[]},{"n":18,"t":"我们必不回自己的家，直等到以色列人各自承受了自己的产业。","notes":[]},{"n":19,"t":"我们不和他们在约旦河那边分产业，因为我们的产业是在约旦河的东边。”","notes":[]},{"n":20,"t":"摩西对他们说：“你们若要这么做，若要在耶和华面前带着兵器出去打仗，","notes":[]},{"n":21,"t":"你们中间所有带兵器的人都要在耶和华面前过约旦河，直到耶和华把仇敌从他面前赶出去。","notes":[]},{"n":22,"t":"那地在耶和华面前被征服以后，你们方可回来。这样，你们向耶和华和以色列才算为无罪，这地也必在耶和华面前归你们为业。","notes":[]},{"n":23,"t":"倘若你们不这样做，看哪，你们就得罪了耶和华，当知道你们的罪必找上你们。","notes":[]},{"n":24,"t":"如今你们可以为孩童建城，为羊群筑圈，但你们口所讲出来的话，必须实践。”","notes":[]},{"n":25,"t":"迦得子孙和吕便子孙对摩西说：“你的仆人们必照我主所吩咐的去做。","notes":[]},{"n":26,"t":"我们的孩子、妻子、牛羊和所有的牲畜都要留在基列的各城。","notes":[]},{"n":27,"t":"但你的仆人，凡能带兵器上战场的，都要照我主所说的话，在耶和华面前渡过去打仗。”","notes":[]},{"n":28,"t":"于是，摩西为他们吩咐以利亚撒祭司和嫩的儿子约书亚，以及以色列人各支派父系的领袖。","notes":[]},{"n":29,"t":"摩西对他们说：“迦得子孙和吕便子孙，凡带兵器在耶和华面前去打仗的，若与你们一同渡过约旦河，那地被你们征服以后，你们就要把基列地给他们为业。","notes":[]},{"n":30,"t":"倘若他们不带兵器与你们一同渡过去，他们就要在迦南地你们中间得产业。”","notes":[]},{"n":31,"t":"迦得子孙和吕便子孙回答说：“耶和华怎样吩咐仆人，我们就必照样做。","notes":[]},{"n":32,"t":"我们自己必带着兵器，在耶和华面前渡过去，进入迦南地，好使我们在约旦河这边得到我们的产业。”","notes":[]},{"n":33,"t":"摩西把亚摩利王西宏的国和巴珊王噩的国，就是他们的国土和周围的城镇，都给了迦得子孙和吕便子孙，以及约瑟的儿子玛拿西半个支派。","notes":[]},{"n":34,"t":"迦得子孙建造了底本、亚他录、亚罗珥、","notes":[]},{"n":35,"t":"亚他录．朔反、雅谢、约比哈、","notes":[]},{"n":36,"t":"伯．宁拉、伯．哈兰，都是坚固城，并筑有羊圈。","notes":[]},{"n":37,"t":"吕便子孙建造了希实本、以利亚利、基列亭、","notes":[]},{"n":38,"t":"尼波、巴力．免（名字是改了的）、西比玛；他们给建造的城另起别名。","notes":[]},{"n":39,"t":"玛拿西的儿子玛吉的子孙往基列去，占了那地，赶出那里的亚摩利人。","notes":[]},{"n":40,"t":"摩西把基列赐给玛拿西的儿子玛吉，他就住在那里。","notes":[]},{"n":41,"t":"玛拿西的子孙睚珥占了基列的城镇，就称这些城镇为哈倭特．睚珥。","notes":[]},{"n":42,"t":"挪巴占了基纳和基纳的乡镇，就照自己的名字称基纳为挪巴。","notes":[]}]},"33":{"heading":"从埃及到摩押","verses":[{"n":1,"t":"这是以色列人按着队伍，在摩西、亚伦的手下，出埃及地的行程。","notes":[]},{"n":2,"t":"摩西遵照耶和华的指示记录他们每段行程的起点，这些行程的起点如下：","notes":[]},{"n":3,"t":"第一个月，就是正月十五日，逾越的第二天，他们从兰塞起行，在所有埃及人的眼前抬起头来出去了。","notes":["“抬起头”：原文是“举起手”。"]},{"n":4,"t":"那时，埃及人正埋葬他们的长子，就是耶和华在他们中间所击杀的；耶和华也惩治了他们的众神明。","notes":[]},{"n":5,"t":"以色列人从兰塞起行，安营在疏割。","notes":[]},{"n":6,"t":"从疏割起行，安营在旷野边上的以倘。","notes":[]},{"n":7,"t":"从以倘起行，转向巴力．洗分对面的比．哈希录，安营在密夺。","notes":[]},{"n":8,"t":"从比．哈希录起行，经过海，进入旷野，在以倘的旷野走了三天的路程，就安营在玛拉。","notes":[]},{"n":9,"t":"从玛拉起行，来到以琳，以琳有十二股水泉，七十棵棕树，就安营在那里。","notes":[]},{"n":10,"t":"从以琳起行，安营在红海边。","notes":[]},{"n":11,"t":"从红海边起行，安营在汛的旷野。","notes":[]},{"n":12,"t":"从汛的旷野起行，安营在脱加。","notes":[]},{"n":13,"t":"从脱加起行，安营在亚录。","notes":[]},{"n":14,"t":"从亚录起行，安营在利非订；在那里，百姓没有水喝。","notes":[]},{"n":15,"t":"从利非订起行，安营在西奈的旷野。","notes":[]},{"n":16,"t":"从西奈的旷野起行，安营在基博罗．哈他瓦。","notes":[]},{"n":17,"t":"从基博罗．哈他瓦起行，安营在哈洗录。","notes":[]},{"n":18,"t":"从哈洗录起行，安营在利提玛。","notes":[]},{"n":19,"t":"从利提玛起行，安营在临门．帕烈。","notes":[]},{"n":20,"t":"从临门．帕烈起行，安营在立拿。","notes":[]},{"n":21,"t":"从立拿起行，安营在勒撒。","notes":[]},{"n":22,"t":"从勒撒起行，安营在基希拉他。","notes":[]},{"n":23,"t":"从基希拉他起行，安营在沙斐山。","notes":[]},{"n":24,"t":"从沙斐山起行，安营在哈拉大。","notes":[]},{"n":25,"t":"从哈拉大起行，安营在玛吉希录。","notes":[]},{"n":26,"t":"从玛吉希录起行，安营在他哈。","notes":[]},{"n":27,"t":"从他哈起行，安营在他拉。","notes":[]},{"n":28,"t":"从他拉起行，安营在密加。","notes":[]},{"n":29,"t":"从密加起行，安营在哈摩拿。","notes":[]},{"n":30,"t":"从哈摩拿起行，安营在摩西录。","notes":[]},{"n":31,"t":"从摩西录起行，安营在比尼．亚干。","notes":[]},{"n":32,"t":"从比尼．亚干起行，安营在曷．哈及甲。","notes":[]},{"n":33,"t":"从曷．哈及甲起行，安营在约巴他。","notes":[]},{"n":34,"t":"从约巴他起行，安营在阿博拿。","notes":[]},{"n":35,"t":"从阿博拿起行，安营在以旬．迦别。","notes":[]},{"n":36,"t":"从以旬．迦别起行，安营在寻的旷野，就是加低斯。","notes":[]},{"n":37,"t":"从加低斯起行，安营在以东地边界的何珥山。","notes":[]},{"n":38,"t":"以色列人出埃及地后四十年，五月初一，亚伦祭司遵照耶和华的指示，上何珥山，死在那里。","notes":[]},{"n":39,"t":"亚伦死在何珥山的时候一百二十三岁。","notes":[]},{"n":40,"t":"住在迦南地尼革夫的迦南人亚拉得王听说以色列人来了。","notes":[]},{"n":41,"t":"以色列人从何珥山起行，安营在撒摩拿。","notes":[]},{"n":42,"t":"从撒摩拿起行，安营在普嫩。","notes":[]},{"n":43,"t":"从普嫩起行，安营在阿伯。","notes":[]},{"n":44,"t":"从阿伯起行，安营在摩押境内的以耶．亚巴琳。","notes":[]},{"n":45,"t":"从以耶．亚巴琳起行，安营在底本．迦得。","notes":[]},{"n":46,"t":"从底本．迦得起行，安营在亚门．低比拉太音。","notes":[]},{"n":47,"t":"从亚门．低比拉太音起行，安营在尼波前面的亚巴琳山脉。","notes":[]},{"n":48,"t":"从亚巴琳山脉起行，安营在约旦河边，耶利哥对面的摩押平原。","notes":[]},{"n":49,"t":"他们在摩押平原，沿着约旦河安营，从伯．耶施末直到亚伯．什亭。","notes":[]},{"n":50,"t":"耶和华在约旦河边，耶利哥对面的摩押平原吩咐摩西说：","notes":[],"heads":["过约旦河前的指示"]},{"n":51,"t":"“你要吩咐以色列人说：你们过约旦河进迦南地的时候，","notes":[]},{"n":52,"t":"要从你们面前赶出那地所有的居民，摧毁他们一切的石像和铸成的偶像，也要拆毁他们一切的丘坛。","notes":[]},{"n":53,"t":"你们要占领那地，住在那里，因我已把那地赐给你们为业。","notes":[]},{"n":54,"t":"你们要按照宗族抽签，承受土地：人多的要多给他们产业；人少的要少给他们产业。抽到何地给何人，那地就属于他。你们要按照父系的支派承受产业。","notes":[]},{"n":55,"t":"倘若你们不把那地的居民从你们面前赶出去，那留下的居民就必成为你们眼中的刺，肋下的荆棘，也必在你们所住的地上扰乱你们；","notes":[]},{"n":56,"t":"我想要怎样待他们，也必照样待你们。”","notes":[]}]},"34":{"heading":"迦南的地界","verses":[{"n":1,"t":"耶和华吩咐摩西说：","notes":[]},{"n":2,"t":"“你要吩咐以色列人，对他们说：你们到了迦南地，这就是归你们为业的地，迦南地和它四周的边界：","notes":[]},{"n":3,"t":"你们的南边是从寻的旷野起，沿着以东的边界；南边的地界从盐海东边开始，","notes":[]},{"n":4,"t":"绕过亚克拉滨斜坡的南边，经过寻，直通到加低斯．巴尼亚的南边，又通到哈萨．亚达，经过押们，","notes":[]},{"n":5,"t":"从押们转向埃及溪谷，直通到海。","notes":[]},{"n":6,"t":"“你们西边的地界要以大海为边界；这就是你们西边的地界。","notes":[]},{"n":7,"t":"“你们北边的地界要从大海开始划界，直到何珥山，","notes":[]},{"n":8,"t":"从何珥山划到哈马口，直通到西达达，","notes":[]},{"n":9,"t":"又通到西斐仑，直达哈萨．以难。这就是你们北边的地界。","notes":[]},{"n":10,"t":"“东边的地界，你们要从哈萨．以难开始划界，直到示番，","notes":[]},{"n":11,"t":"这地界要从示番下到亚延东边的利比拉，这地界要下延到基尼烈海的东边，","notes":[]},{"n":12,"t":"这地界又下到约旦河，直通到盐海。这就是你们的地和它四围的边界。”","notes":[]},{"n":13,"t":"摩西吩咐以色列人说：“这就是耶和华吩咐抽签给九个半支派承受为业的地。","notes":[]},{"n":14,"t":"因为吕便子孙的支派按着父家、迦得子孙的支派按着父家，和玛拿西半个支派已经得到了他们的产业：","notes":[]},{"n":15,"t":"这两个半支派已经在耶利哥对面，约旦河东边，向日出的方向承受了产业。”","notes":[]},{"n":16,"t":"耶和华吩咐摩西说：","notes":[],"heads":["负责分地的领袖"]},{"n":17,"t":"“这是为你们分地为业的人的名字：以利亚撒祭司和嫩的儿子约书亚。","notes":[]},{"n":18,"t":"你要从每个支派中选一个领袖来分配产业。","notes":[]},{"n":19,"t":"这些人的名字如下：犹大支派，耶孚尼的儿子迦勒。","notes":[]},{"n":20,"t":"西缅子孙的支派，亚米忽的儿子示母利。","notes":[]},{"n":21,"t":"便雅悯支派，基斯伦的儿子以利达。","notes":[]},{"n":22,"t":"但子孙支派的领袖，约利的儿子布基。","notes":[]},{"n":23,"t":"约瑟的子孙，玛拿西子孙支派的领袖：以弗的儿子汉尼业。","notes":[]},{"n":24,"t":"以法莲子孙支派的领袖：拾弗但的儿子基摩利。","notes":[]},{"n":25,"t":"西布伦子孙支派的领袖：帕纳的儿子以利撒番。","notes":[]},{"n":26,"t":"以萨迦子孙支派的领袖：阿散的儿子帕铁。","notes":[]},{"n":27,"t":"亚设子孙支派的领袖：示罗米的儿子亚希忽。","notes":[]},{"n":28,"t":"拿弗他利子孙支派的领袖：亚米忽的儿子比大黑。”","notes":[]},{"n":29,"t":"这些就是耶和华所吩咐，在迦南地为以色列人分产业的人。","notes":[]}]},"35":{"heading":"利未人的城","verses":[{"n":1,"t":"耶和华在约旦河边，耶利哥对面的摩押平原吩咐摩西说：","notes":[]},{"n":2,"t":"“你吩咐以色列人，要从所得为业的地中把一些城给利未人居住，也要把这些城四围的郊野给利未人。","notes":[]},{"n":3,"t":"这些城镇要归他们居住，郊外可以给他们牧放牛羊、牲畜和所有的动物。","notes":[]},{"n":4,"t":"你们给利未人城的郊外，要从城墙量起，四围往外量一千肘。","notes":[]},{"n":5,"t":"你们要往东量二千肘，往南量二千肘，往西量二千肘，往北量二千肘为边界，以城为中心；这城镇的郊外要归给他们。”","notes":[]},{"n":6,"t":"“你们给利未人的城镇中，要设立六座逃城，让误杀人的可以逃到那里。此外还要给他们四十二座城。","notes":[],"heads":["逃城的设立和条例"]},{"n":7,"t":"所以，给利未人的城一共有四十八座，连同城的郊外都给他们。","notes":[]},{"n":8,"t":"从以色列人所得的产业中给利未人的这些城镇，多的要多给，少的要少给；各支派要按照所承受为业之地的多少把城镇给利未人。”","notes":[]},{"n":9,"t":"耶和华吩咐摩西说：","notes":[]},{"n":10,"t":"“你要吩咐以色列人，对他们说：你们过了约旦河，进入迦南地，","notes":[]},{"n":11,"t":"要指定几座城，作为你们的逃城，使误杀人的可以逃到那里。","notes":[]},{"n":12,"t":"这些城要作为逃避报仇者的城，使误杀人的不至于死，等他站在会众面前受审判。","notes":[]},{"n":13,"t":"“你们指定的城，是要作你们的六座逃城。","notes":[]},{"n":14,"t":"约旦河东指定三座，迦南地也指定三座，作为逃城。","notes":[]},{"n":15,"t":"这六座城要给以色列人和他们中间的外人，以及寄居者，作为逃城，让误杀人的可以逃到那里。","notes":[]},{"n":16,"t":"“倘若人用铁器打死人，他是故意杀人的；故意杀人的必被处死。","notes":[]},{"n":17,"t":"若用手中可以致命的石头打死人，他是故意杀人的；故意杀人的必被处死。","notes":[]},{"n":18,"t":"若用手中可以致命的木器打死人，他是故意杀人的；故意杀人的必被处死。","notes":[]},{"n":19,"t":"报血仇者可以亲自杀死那故意杀人的；他一找到凶手，就可以杀死他。","notes":[]},{"n":20,"t":"人若因怨恨把人推倒，或埋伏等着丢东西砸人，以至于死，","notes":[]},{"n":21,"t":"或因仇恨用手打死人，打人的必被处死，他是故意杀人的；报血仇者一遇见凶手就可以杀死他。","notes":[]},{"n":22,"t":"“人若不是出于仇恨，把人推倒，或不是埋伏等着丢东西砸人，","notes":[]},{"n":23,"t":"或是在不注意的时候，用可以致命的石头扔在人身上，以至于死，彼此没有仇恨，也无意害对方，","notes":[]},{"n":24,"t":"会众就要照着这些典章，在杀人者和报血仇者中间审判。","notes":[]},{"n":25,"t":"会众要救这误杀人的脱离报血仇者的手，送他回到他曾逃入的逃城那里。他要住在城中，直到受圣膏的大祭司去世。","notes":[]},{"n":26,"t":"但误杀人的，无论什么时候，若离开了他所逃入的逃城边界，","notes":[]},{"n":27,"t":"报血仇者在逃城边界外遇见他，把凶手杀了，报血仇者就没有流人血之罪。","notes":[]},{"n":28,"t":"因为误杀人的应该住在逃城里，直到大祭司去世。大祭司去世以后，误杀人的才可以回到他所得为业之地。","notes":[]},{"n":29,"t":"在你们一切的住处，这些都要作为你们世世代代的律例典章。","notes":[]},{"n":30,"t":"“无论谁杀了人，必须凭几个证人的口，才可把那故意杀人的处死；只凭一个证人，不足以判人死。","notes":[]},{"n":31,"t":"那犯死罪的杀人犯，你们不可收赎价来代替他的命；他必须被处死。","notes":[]},{"n":32,"t":"那逃到逃城的人，你们不可向他收赎价，使他在大祭司未死以先回本地居住。","notes":[]},{"n":33,"t":"这样，你们就不会污秽所住之地，因为血能使地污秽；若有血流在地上，除非流那杀人者的血，否则那地就不得洁净。","notes":[]},{"n":34,"t":"你们不可玷污所住之地，就是我住在当中的地，因为我－耶和华住在以色列人中间。”","notes":[]}]},"36":{"heading":"女继承人的结婚条例","verses":[{"n":1,"t":"约瑟子孙的宗族，玛拿西的孙子，玛吉的儿子基列，他父系宗族的领袖来到摩西和作领袖的以色列众父系家长面前，说：","notes":[]},{"n":2,"t":"“耶和华曾吩咐我主抽签分地给以色列人为业，我主也遵照耶和华的吩咐，把我们兄弟西罗非哈的产业给他的女儿。","notes":[]},{"n":3,"t":"她们若嫁给以色列别个支派的人，必拿走我们祖宗所遗留的产业，加在她们丈夫支派的产业上。这样，我们抽签所得的产业就要减少了。","notes":[]},{"n":4,"t":"到了以色列人的禧年，她们的产业就必加在她们丈夫支派的产业上。这样，我们祖宗支派的产业就要减少了。”","notes":[]},{"n":5,"t":"摩西照耶和华的指示吩咐以色列人说：“约瑟子孙支派的人说得有理。","notes":[]},{"n":6,"t":"关于西罗非哈的女儿们，这是耶和华吩咐的话说：‘她们可以随意嫁人，只是必须嫁给同宗，她们父亲支派的人。","notes":[]},{"n":7,"t":"这样，以色列人的产业就不会从这支派转到另一个支派，因为以色列人要各自守住祖宗支派的产业。","notes":[]},{"n":8,"t":"凡在以色列支派中得了产业的女儿，必须嫁给同宗，她们父亲支派的人，好使以色列人各自承受他们祖宗的产业。","notes":[]},{"n":9,"t":"产业不可从一个支派转到另一个支派，因为以色列支派的人要各自守住自己的产业。’”","notes":[]},{"n":10,"t":"耶和华怎样吩咐摩西，西罗非哈的女儿就照样做。","notes":[]},{"n":11,"t":"西罗非哈的女儿玛拉、得撒、曷拉、密迦、挪阿都嫁给她们叔伯的儿子。","notes":[]},{"n":12,"t":"她们嫁给了约瑟儿子玛拿西子孙宗族的人；她们的产业保留在同宗，她们父亲的支派中。","notes":[]},{"n":13,"t":"这是耶和华在约旦河边，耶利哥对面的摩押平原，藉着摩西吩咐以色列人的命令和典章。","notes":[]}]}},"DEU":{"1":{"heading":"摩西的回忆","verses":[{"n":1,"t":"以下是摩西在约旦河东的旷野，疏弗对面的亚拉巴，就是在巴兰、陀弗、拉班、哈洗录、底撒哈之间，向以色列众人所说的话。","notes":[]},{"n":2,"t":"从何烈山经过西珥山到加低斯．巴尼亚要十一天的路程。","notes":[]},{"n":3,"t":"第四十年十一月初一，摩西照耶和华所吩咐他一切有关以色列人的话，都告诉他们。","notes":[]},{"n":4,"t":"那时，他已经击败了住希实本的亚摩利王西宏和住亚斯她录、以得来的巴珊王噩。","notes":[]},{"n":5,"t":"摩西在约旦河东的摩押地讲解这律法，说：","notes":[]},{"n":6,"t":"“耶和华－我们的神在何烈山吩咐我们说：你们住在这山上已经够久了。","notes":[]},{"n":7,"t":"要起行，转到亚摩利人的山区和附近的地区，就是亚拉巴、山区、谢非拉、尼革夫、沿海一带，迦南人的地和黎巴嫩，直到大河，就是幼发拉底河。","notes":["“谢非拉”是音译，意思是“低地”。","“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”；本卷书下同。"]},{"n":8,"t":"看，我将这地摆在你们面前。你们要进去得这地，就是耶和华向你们列祖亚伯拉罕、以撒、雅各起誓要赐给他们和他们后裔为业之地。”","notes":[]},{"n":9,"t":"“那时，我对你们说：‘我独自一人无法承担你们的事。","notes":[],"heads":["选立审判官"]},{"n":10,"t":"耶和华－你们的神使你们增多。看哪，你们今日好像天上的星那样多。","notes":[]},{"n":11,"t":"惟愿耶和华－你们列祖的神使你们更增加千倍，照他所应许你们的赐福给你们。","notes":[]},{"n":12,"t":"但你们的担子，你们的重任，以及你们的争讼，我独自一人怎能承担呢？","notes":[]},{"n":13,"t":"你们要按着各支派选出有智慧、明辨是非、为人所知的人来，我就立他们为你们的领袖。’","notes":[]},{"n":14,"t":"你们回答我说：‘你说要做的事很好！’","notes":[]},{"n":15,"t":"我就将你们各支派的领袖，就是有智慧、为人所知的人，立他们为领袖，作你们各支派的千夫长、百夫长、五十夫长、十夫长等官长，来管理你们。","notes":[]},{"n":16,"t":"“当时，我吩咐你们的审判官说：‘你们听讼，无论是弟兄之间的诉讼，或与寄居者之间的诉讼，都要秉公判断。","notes":[]},{"n":17,"t":"审判的时候不可看人的情面；无论大小，你们都要听讼。不可因人而惧怕，因为审判是神的事。你们当中若有难断的案件，可以呈到我这里，让我来听讼。’","notes":[]},{"n":18,"t":"那时，我已经把你们所当做的事都吩咐你们了。”","notes":[]},{"n":19,"t":"“我们照着耶和华－我们神所吩咐的，从何烈山起行，经过你们所看见那一切大而可怕的旷野，往亚摩利人的山区去，到了加低斯．巴尼亚。","notes":[],"heads":["以色列人拒进迦南"]},{"n":20,"t":"我对你们说：‘你们已经到了耶和华－我们神所赐给我们的亚摩利人之山区。","notes":[]},{"n":21,"t":"看，耶和华－你的神已将那地摆在你面前，你要照耶和华－你列祖的神所说的，上去得那地为业。不要惧怕，也不要惊惶。’","notes":[]},{"n":22,"t":"你们都来到我这里，说：‘让我们先派人去，为我们窥探那地，把我们上去该走的路线和该进的城镇回报我们。’","notes":[]},{"n":23,"t":"这话我看为美，就从你们中间选取十二个人，每支派一人。","notes":[]},{"n":24,"t":"于是他们起身上山区去，到以实各谷，窥探那地。","notes":[]},{"n":25,"t":"他们的手带着那地的一些果子，下到我们这里，回报我们说：‘耶和华－我们的神所赐给我们的是美地。’","notes":[]},{"n":26,"t":"“你们却不肯上去，竟违背了耶和华─你们神的指示，","notes":[]},{"n":27,"t":"在帐棚内发怨言说：‘耶和华因为恨我们，所以将我们从埃及地领出来，要把我们交在亚摩利人的手中，除灭我们。","notes":[]},{"n":28,"t":"我们上哪里去呢？我们的弟兄使我们胆战心惊，说那里的百姓比我们又大又高 ，那里的城镇又大，城墙又坚固，如天一样高，并且我们在那里看见亚衲族人。’","notes":["“胆战心惊”：原文直译“心消化了”。","“高”：有古卷是“多”。"]},{"n":29,"t":"我就对你们说：‘不要惊惶，也不要怕他们。","notes":[]},{"n":30,"t":"在你们前面行的耶和华－你们的神必为你们争战，正如他在埃及，在你们眼前为你们所做的一样；","notes":[]},{"n":31,"t":"并且你们在旷野所行的一切路上，也看见了耶和华─你们的神背着你们，如同人背自己的儿子一样，直到你们来到这地方。’","notes":[]},{"n":32,"t":"你们在这事上却不信耶和华─你们的神。","notes":[]},{"n":33,"t":"他一路行在你们前面，为你们寻找安营的地方；他夜间在火中，日间在云中，指示你们当走的路。”","notes":[]},{"n":34,"t":"“耶和华听见你们的怨言，就发怒，起誓说：","notes":[],"heads":["以色列人受惩罚"]},{"n":35,"t":"‘这邪恶世代的人，一个也不得看见我起誓要赐给你们列祖的美地；","notes":[]},{"n":36,"t":"惟有耶孚尼的儿子迦勒必得看见，并且我要将他所踏过的地赐给他和他的子孙，因为他专心跟从我。’","notes":[]},{"n":37,"t":"耶和华也因你们的缘故向我发怒，说：‘你也不得进入那地。","notes":[]},{"n":38,"t":"那侍候你，嫩的儿子约书亚必得进入那地。你要勉励他，因为他要使以色列承受那地为业。","notes":[]},{"n":39,"t":"你们的孩子，你们说要成为掳物的，就是今日尚不知善恶的儿女，必进入那地。我要将那地赐给他们，他们必得为业。","notes":[]},{"n":40,"t":"至于你们，要转回，从红海的路往旷野去。’","notes":["“红海”是根据七十士译本，原文是“芦苇海”；本卷书下同。"]},{"n":41,"t":"“你们回答我说：‘我们得罪了耶和华！现在我们愿遵照耶和华─我们神一切所吩咐的上去争战。’于是你们各人带着兵器，以为很容易就能上到山区去。","notes":[]},{"n":42,"t":"耶和华对我说：‘你对他们说：不要上去，也不要争战，因我不在你们中间，恐怕你们在仇敌面前被击败。’","notes":[]},{"n":43,"t":"我就告诉了你们，你们却不听从，竟违背耶和华的指示，擅自上到山区去。","notes":[]},{"n":44,"t":"住在那山区的亚摩利人像蜂群一样出来迎击你们，追赶你们，在西珥击败你们，直到何珥玛。","notes":[]},{"n":45,"t":"你们就回来，在耶和华面前哭泣；耶和华却不听你们的声音，也不向你们侧耳。","notes":[]},{"n":46,"t":"你们照着所停留的日子，在加低斯停留了许多日子。”","notes":[]}]},"2":{"heading":"在旷野流浪","verses":[{"n":1,"t":"“我们转回，从红海的路往旷野去，正如耶和华所吩咐我的。我们在西珥山绕行了许多日子。","notes":[]},{"n":2,"t":"耶和华对我说：","notes":[]},{"n":3,"t":"‘你们绕行这山已经够久了，要转向北方。","notes":[]},{"n":4,"t":"你要吩咐百姓说：你们弟兄以扫的子孙住在西珥，你们要经过他们的边界。他们必惧怕你们，但你们要分外谨慎。","notes":[]},{"n":5,"t":"不可向他们挑战；他们的地，连脚掌可踏之处，我都不给你们，因我已将西珥山赐给以扫为业。","notes":[]},{"n":6,"t":"你们要用钱向他们买粮吃，也要用钱向他们买水喝。","notes":[]},{"n":7,"t":"因为耶和华─你的神在你手里所做的一切事上已赐福给你。你走这大旷野，他都知道。这四十年，耶和华─你的神与你同在，因此你一无所缺。’","notes":[]},{"n":8,"t":"“于是，我们经过我们弟兄以扫子孙所住的西珥，从亚拉巴的路，经过以拉他、以旬．迦别，转向摩押旷野的路去。","notes":[]},{"n":9,"t":"耶和华对我说：‘不可侵犯摩押，也不可向他们挑战。他们的地，我不赐给你为业，因我已将亚珥赐给罗得的子孙为业。’","notes":[]},{"n":10,"t":"先前，以米人住在那里，百姓又大又多，像亚衲人一样高大。","notes":[]},{"n":11,"t":"他们跟亚衲人一样，也算是利乏音人，但摩押人却称他们为以米人。","notes":[]},{"n":12,"t":"从前，何利人也住在西珥，但以扫的子孙把他们除灭，占领了他们的地，接续他们在那里居住，如同以色列在耶和华赐给他们为业之地所做的一样。","notes":[]},{"n":13,"t":"‘现在，起来，过撒烈溪！’于是我们过了撒烈溪。","notes":[]},{"n":14,"t":"从离开加低斯．巴尼亚到渡过撒烈溪，这段时期共三十八年，直到这一代的战士都从营中灭尽，正如耶和华向他们所起的誓。","notes":[]},{"n":15,"t":"耶和华的手也攻击他们，将他们从营中除灭，直到灭尽。","notes":[]},{"n":16,"t":"“百姓中所有的战士灭尽死亡以后，","notes":[]},{"n":17,"t":"耶和华吩咐我说：","notes":[]},{"n":18,"t":"‘你今日要经过摩押的边界亚珥，","notes":[]},{"n":19,"t":"走到亚扪人之地。不可侵犯他们，也不可向他们挑战。亚扪人的地，我不赐给你们为业，因我已将那地赐给罗得的子孙为业。’","notes":[]},{"n":20,"t":"那地也算是利乏音人之地，因为先前利乏音人住在那里，亚扪人称他们为散送冥人。","notes":[]},{"n":21,"t":"那里的百姓又大又多，像亚衲人一样高大，但耶和华从亚扪人面前除灭他们，亚扪人就占领他们的地，接续他们在那里居住。","notes":[]},{"n":22,"t":"这正如耶和华从前为住在西珥的以扫子孙，将何利人从他们面前除灭，使他们得了何利人的地，接续他们在那里居住，直到今日一样。","notes":[]},{"n":23,"t":"亚卫人先前住在乡村直到迦萨；从迦斐托出来的迦斐托人将亚卫人除灭，接续他们在那里居住。","notes":[]},{"n":24,"t":"你们起来往前去，过亚嫩谷。看，我已将亚摩利人希实本王西宏和他的地交在你手中，你要开始去得他的地为业，向他挑战。","notes":[]},{"n":25,"t":"从今日起，我要让天下万民惊慌惧怕你，听见你的名声，就因你发颤伤恸。”","notes":[]},{"n":26,"t":"“我从基底莫的旷野派遣使者到希实本王西宏那里，用和平的话说：","notes":[],"heads":["打败希实本王西宏"]},{"n":27,"t":"‘求你让我穿越你的地，我走路的时候，只走大路，不偏左右。","notes":[]},{"n":28,"t":"你可以卖粮给我吃，卖水给我喝；只要让我步行过去，","notes":[]},{"n":29,"t":"就如住在西珥的以扫子孙和住在亚珥的摩押人待我一样，等我过了约旦河，进入耶和华－我们神所赐给我们的地。’","notes":[]},{"n":30,"t":"但希实本王西宏不肯让我们从他那里经过，因为耶和华－你的神使他性情顽梗，内心刚硬，为要把他交在你手中，像今日一样。","notes":[]},{"n":31,"t":"耶和华对我说：‘看，我已开始把西宏和他的地交给你了，你要开始得他的地为业。’","notes":[]},{"n":32,"t":"“西宏和他的众百姓出来迎击我们，在雅杂与我们交战。","notes":[]},{"n":33,"t":"耶和华－我们的神把他交给我们，我们就杀了他和他的众儿子，以及他所有的百姓。","notes":[]},{"n":34,"t":"那时，我们夺了他一切的城镇，毁灭各城的男人、女人、孩子，没有留下一个幸存者。","notes":[]},{"n":35,"t":"只有牲畜和所夺各城的财物，我们都取为自己的掠物。","notes":[]},{"n":36,"t":"从亚嫩谷旁的亚罗珥和谷中的城，直到基列，没有一座城是高得我们不能攻取的；耶和华－我们的神把它们全都交给我们了。","notes":[]},{"n":37,"t":"只有亚扪人之地，雅博河沿岸，以及山区的城镇，你没有挨近，这全是耶和华－我们神所吩咐的。”","notes":[]}]},"3":{"heading":"打败巴珊王噩","verses":[{"n":1,"t":"“我们又转回，朝巴珊的路上去。巴珊王噩和他的众百姓出来迎击我们，在以得来与我们交战。","notes":[]},{"n":2,"t":"耶和华对我说：‘不要怕他！因我已把他和他的众百姓，以及他的地，都交在你手中；你要待他像从前待住在希实本的亚摩利王西宏一样。’","notes":[]},{"n":3,"t":"于是耶和华－我们的神也把巴珊王噩和他的众百姓都交在我们手中；我们杀了他，没有给他留下一个幸存者。","notes":[]},{"n":4,"t":"那时，我们夺了他一切的城镇，共六十座，没有一座城不被我们所夺，这是亚珥歌伯的全境，巴珊王噩的国度。","notes":[]},{"n":5,"t":"这些坚固的城都有高的城墙，有门有闩，此外，还有许多无城墙的乡村。","notes":[]},{"n":6,"t":"我们把这些都毁灭了，像从前待希实本王西宏一样，毁灭各城的男人、女人、孩子；","notes":[]},{"n":7,"t":"只有一切牲畜和城中的财物，我们取为自己的掠物。","notes":[]},{"n":8,"t":"那时，我们从两个亚摩利王的手里把约旦河东边的地夺过来，从亚嫩谷直到黑门山，","notes":[]},{"n":9,"t":"这黑门山，西顿人称为西连，亚摩利人称为示尼珥。","notes":[]},{"n":10,"t":"我们夺了平原的各城、基列全地、巴珊全地，直到撒迦和以得来，都是巴珊王噩国内的城镇。","notes":[]},{"n":11,"t":"利乏音人所剩下的只有巴珊王噩。看哪，他的床是铁床，按照人肘的度量，长九肘，宽四肘，现今不是在亚扪人的拉巴吗？”","notes":[]},{"n":12,"t":"“那时，我们得了这地。从亚嫩谷旁的亚罗珥起，连同基列山区的一半和境内的城镇，我都给了吕便人和迦得人。","notes":[],"heads":["约旦河东土地的分配"]},{"n":13,"t":"基列其余的地和巴珊全地，就是噩的国度，我给了玛拿西半支派。亚珥歌伯全境就是巴珊全地，也称为利乏音人之地。","notes":[]},{"n":14,"t":"玛拿西的子孙睚珥占领了亚珥歌伯全境，直到基述人和玛迦人的边界，就按自己的名字称这些地，就是巴珊，为哈倭特．睚珥，直到今日。","notes":[]},{"n":15,"t":"我又将基列给了玛吉。","notes":[]},{"n":16,"t":"我给了吕便人和迦得人从基列到亚嫩谷，以谷的中央为界，直到亚扪人边界的雅博河；","notes":[]},{"n":17,"t":"还有亚拉巴和靠近约旦河之地，从基尼烈直到亚拉巴海，就是盐海，以及毗斯迦山斜坡的山脚东边之地。","notes":[]},{"n":18,"t":"“那时，我吩咐你们说：‘耶和华－你们的神已将这地赐给你们为业；你们所有的勇士都要带着兵器，在你们的弟兄以色列人前面过去。","notes":[]},{"n":19,"t":"但你们的妻子、孩子、牲畜，可以住在我所赐给你们的各城里，我知道你们有许多牲畜。","notes":[]},{"n":20,"t":"等到耶和华让你们的弟兄像你们一样，得享太平，他们在约旦河另一边，也得了耶和华－你们的神所赐给他们的地，你们各人才可以回到我所赐给你们为业之地。’","notes":[]},{"n":21,"t":"那时，我吩咐约书亚说：‘你亲眼看见了耶和华－你们的神向这两个王一切所做的事，耶和华也必向你所要去的各国照样做。","notes":[]},{"n":22,"t":"不要怕他们，因为那为你们争战的是耶和华－你们的神。’”","notes":[]},{"n":23,"t":"“那时，我恳求耶和华说：","notes":[],"heads":["摩西不得进入迦南"]},{"n":24,"t":"‘主耶和华啊，你已开始将你的伟大和你大能的手显给你仆人看。在天上，在地下，有什么神明能像你行事，像你有大能的作为呢？","notes":[]},{"n":25,"t":"求你让我过去，看约旦河另一边的美地，就是那佳美的山区和黎巴嫩。’","notes":[]},{"n":26,"t":"但耶和华因你们的缘故向我发怒，不应允我。耶和华对我说：‘你够了吧！不要再向我提这事。","notes":[]},{"n":27,"t":"你上毗斯迦山顶去，向东、西、南、北举目，用你的眼睛观看，因为你必不能过这约旦河。","notes":[]},{"n":28,"t":"你却要吩咐约书亚，勉励他，使他壮胆，因为他必在这百姓前面过去，使他们承受你所要观看之地。’","notes":[]},{"n":29,"t":"于是我们停留在伯．毗珥对面的谷中。”","notes":[]}]},"4":{"heading":"摩西劝以色列人遵守律法","verses":[{"n":1,"t":"“现在，以色列啊，听我所教导你们的律例典章，要遵行，好使你们存活，得以进入耶和华－你们列祖之神所赐给你们的地，承受为业。","notes":[]},{"n":2,"t":"我吩咐你们的话，你们不可加添，也不可删减，好叫你们遵守耶和华－你们神的命令，就是我所吩咐你们的。","notes":[]},{"n":3,"t":"你们已亲眼看见耶和华因巴力．毗珥所做的。凡随从巴力．毗珥的人，耶和华－你的神都从你中间除灭了。","notes":[]},{"n":4,"t":"只有你们这紧紧跟随耶和华－你们神的人，今日全都存活。","notes":[]},{"n":5,"t":"看，我照着耶和华－我的神所吩咐我的，将律例和典章教导你们，使你们在所要进去得为业的地上遵行。","notes":[]},{"n":6,"t":"你们要谨守遵行；这就是你们在万民眼前的智慧和聪明。他们听见这一切律例，必说：‘这大国的人真是有智慧，有聪明！’","notes":[]},{"n":7,"t":"哪一大国有神明与他们相近，像耶和华－我们的神在我们求告他的时候与我们相近呢？","notes":[]},{"n":8,"t":"哪一大国有这样公义的律例典章，像我今日在你们面前所颁布的这一切律法呢？","notes":[]},{"n":9,"t":"“但你要谨慎，殷勤保守你的心灵，免得忘记你亲眼所看见的事，又免得在你一生的年日这些事离开你的心，总要把它们传给你的子子孙孙。","notes":[]},{"n":10,"t":"你在何烈山站在耶和华－你神面前的那日，耶和华对我说：‘你为我召集百姓，我要叫他们听见我的话，使他们活在世上的日子，可以学习敬畏我，又可以教导他们的儿女。’","notes":[]},{"n":11,"t":"那时，你们近前来，站在山下；山上有火燃烧，直冲天顶，并有黑暗、密云、幽暗。","notes":[]},{"n":12,"t":"耶和华从火焰中对你们说话，你们听见说话的声音，只有声音，却没有看见形像。","notes":[]},{"n":13,"t":"他将所吩咐你们当守的约指示你们，就是十条诫命，并将诫命写在两块石版上。","notes":["“十条诫命”：原文是“十句话”；10．4同。"]},{"n":14,"t":"那时，耶和华吩咐我将律例典章教导你们，使你们在所要过去得为业的地上遵行。”","notes":[]},{"n":15,"t":"“所以，你们为自己的缘故要分外谨慎；因为耶和华在何烈山，从火中对你们说话的那日，你们没有看见任何形像。","notes":[],"heads":["禁拜偶像"]},{"n":16,"t":"惟恐你们的行为败坏，为自己雕刻任何形状的偶像，无论是男像或女像，","notes":[]},{"n":17,"t":"或地上任何走兽的像，或任何飞在空中有翅膀的鸟的像，","notes":[]},{"n":18,"t":"或地上任何爬行动物的像，或地底下任何水中鱼的像。","notes":[]},{"n":19,"t":"又恐怕你向天举目，看见耶和华－你的神为天下万民所摆列的日月星辰，就是天上的万象，就被诱惑去敬拜它们，事奉它们。","notes":[]},{"n":20,"t":"耶和华将你们从埃及带领出来，脱离铁炉，是要你们成为他产业的子民，像今日一样。","notes":[]},{"n":21,"t":"“耶和华又因你们的缘故向我发怒，起誓不容我过约旦河，不让我进入耶和华－你神所赐你为业的那美地。","notes":[]},{"n":22,"t":"我只好死在这地，不能过约旦河；但你们必过去得那美地。","notes":[]},{"n":23,"t":"你们要谨慎，免得忘记耶和华－你们的神与你们所立的约，为自己雕刻任何形状的偶像，就是耶和华－你神所禁止的，","notes":[]},{"n":24,"t":"因为耶和华－你的神是吞灭的火，是忌邪的神。","notes":["“忌邪”：原文是“妒忌”，意思是“不容许有对立的神明”。"]},{"n":25,"t":"“你们在那地住久了，生子生孙，若行为败坏，为自己雕刻任何形状的偶像，行耶和华－你神眼中看为恶的事，惹他发怒，","notes":[]},{"n":26,"t":"我今日呼天唤地向你们作见证，你们在过约旦河得为业的地上必迅速灭亡！你们在那地的日子必不长久，必全然灭绝。","notes":[]},{"n":27,"t":"耶和华必将你们分散在万民中；在耶和华领你们到的列国中，你们剩下的人丁稀少。","notes":[]},{"n":28,"t":"在那里，你们必事奉人手所造的神明，它们是木头，是石头，不能看，不能听，不能吃，不能闻。","notes":[]},{"n":29,"t":"你们在那里必寻求耶和华－你的神。你若尽心尽性寻求他，就必寻见。","notes":[]},{"n":30,"t":"日后你在患难中，当这一切的事临到你，你必归回耶和华－你的神，听从他的话。","notes":[]},{"n":31,"t":"耶和华－你的神是有怜悯的神，他不撇下你，不灭绝你，也不忘记他起誓与你列祖所立的约。","notes":[]},{"n":32,"t":"“你去问，在你先前的时代，自从神造人在地上以来，从天这边到天那边，曾有过或听过这样的大事吗？","notes":[]},{"n":33,"t":"有哪些百姓听见神在火中说话的声音，像你听见了还能存活呢？","notes":[]},{"n":34,"t":"神何曾为自己尝试从别的国中领出一国的子民来，用考验、神迹、奇事、战争、大能的手、伸出来的膀臂和大可畏的事，像耶和华－你们的神在埃及，在你们眼前为你们所做的一切事呢？","notes":[]},{"n":35,"t":"这是要显给你看，使你知道，惟有耶和华他是神，除他以外，再没有别的了。","notes":[]},{"n":36,"t":"他从天上使你听见他的声音，为要教导你，又在地上使你看见他的烈火，并且听见他从火中所说的话。","notes":[]},{"n":37,"t":"因为他爱你的列祖，拣选他们的后裔，亲自用大能领你出了埃及，","notes":["“他们的后裔”是根据撒玛利亚五经、七十士译本和其他古译本；原文是“他”，“他”指雅各。"]},{"n":38,"t":"要将比你强大的列国从你面前赶出，领你进去，把他们的地赐你为业，像今日一样。","notes":[]},{"n":39,"t":"所以，今日你要知道，也要记在心里，天上地下惟有耶和华他是神，再没有别的了。","notes":[]},{"n":40,"t":"我今日吩咐你的律例诫命，你要遵守，使你和你的后裔可以得福，并使你的日子一直在耶和华－你神赐你的地上得以长久。”","notes":[]},{"n":41,"t":"“那时，摩西在约旦河东边，向日出的方向，指定三座城，","notes":[],"heads":["约旦河东的三座逃城"]},{"n":42,"t":"使那素无仇恨、无意中杀了邻舍的凶手，可以逃到这三座城中的一座，就得存活：","notes":[]},{"n":43,"t":"属吕便人的是旷野平坦之地的比悉，属迦得人的是基列的拉末，属玛拿西人的是巴珊的哥兰。”","notes":[]},{"n":44,"t":"这是摩西在以色列人面前颁布的律法。","notes":[],"heads":["摩西颁布神的律法"]},{"n":45,"t":"这些法度、律例、典章是摩西在以色列人出埃及后对他们说的，","notes":[]},{"n":46,"t":"在约旦河东伯．毗珥对面的谷中，在住希实本的亚摩利王西宏之地；这西宏是摩西和以色列人出埃及后所击杀的。","notes":[]},{"n":47,"t":"他们得了他的地，又得了巴珊王噩的地，就是两个亚摩利王，在约旦河东，向日出方向的地：","notes":[]},{"n":48,"t":"从亚嫩谷旁的亚罗珥，直到西云山，就是黑门山，","notes":[]},{"n":49,"t":"还有约旦河东的整个亚拉巴，向日出方向，直到亚拉巴海，靠近毗斯迦山斜坡的山脚。","notes":[]}]},"5":{"heading":"十诫","verses":[{"n":1,"t":"摩西召集以色列众人，对他们说：“以色列啊，要听我今日在你们耳中所吩咐的律例典章，要学习，谨守遵行。","notes":[]},{"n":2,"t":"耶和华－我们的神在何烈山与我们立约。","notes":[]},{"n":3,"t":"这约耶和华不是与我们列祖立的，而是与我们，就是今日在这里还活着的人立的。","notes":[]},{"n":4,"t":"耶和华在山上，从火中，面对面与你们说话。","notes":[]},{"n":5,"t":"那时我站在耶和华和你们之间，要将耶和华的话传给你们，因为你们惧怕那火，没有上山。他说：","notes":[]},{"n":6,"t":"“‘我是耶和华－你的神，曾将你从埃及地为奴之家领出来。","notes":[]},{"n":7,"t":"“‘除了我以外，你不可有别的神。","notes":[]},{"n":8,"t":"“‘不可为自己雕刻偶像，也不可做什么形像，仿佛上天、下地和地底下水中的百物。","notes":[]},{"n":9,"t":"不可跪拜那些像，也不可事奉它们，因为我耶和华－你的神是忌邪的神。恨我的，我必惩罚他们的罪，自父及子，直到三、四代；","notes":["“忌邪”：原文是“妒忌”，意思是“不容许有对立的神明”。"]},{"n":10,"t":"爱我、守我诫命的，我必向他们施慈爱，直到千代。","notes":[]},{"n":11,"t":"“‘不可妄称耶和华－你神的名，因为妄称耶和华名的，耶和华必不以他为无罪。","notes":[]},{"n":12,"t":"“‘当守安息日为圣日，正如耶和华－你神所吩咐的。","notes":[]},{"n":13,"t":"六日要劳碌做你一切的工，","notes":[]},{"n":14,"t":"但第七日是向耶和华－你的神当守的安息日。这一日，你和你的儿女、仆婢、牛、驴、牲畜，以及你城里寄居的客旅，都不可做任何的工，使你的仆婢可以和你一样休息。","notes":[]},{"n":15,"t":"你要记念你在埃及地作过奴仆，耶和华－你的神用大能的手和伸出来的膀臂领你从那里出来。因此，耶和华－你的神吩咐你守安息日。","notes":[]},{"n":16,"t":"“‘当孝敬父母，正如耶和华－你神所吩咐的，使你得福，并使你的日子在耶和华－你神所赐给你的地上得以长久。","notes":[]},{"n":17,"t":"“‘不可杀人。","notes":[]},{"n":18,"t":"“‘不可奸淫。","notes":[]},{"n":19,"t":"“‘不可偷盗。","notes":[]},{"n":20,"t":"“‘不可做假见证陷害你的邻舍。","notes":[]},{"n":21,"t":"“‘不可贪恋你邻舍的妻子；也不可贪图你邻舍的房屋、田地、仆婢、牛驴，以及他一切所有的。’","notes":[]},{"n":22,"t":"“这些话是耶和华在山上，从火焰、密云、幽暗中，大声吩咐你们全会众的，再没有加添别的话了。他把这些话写在两块石版上，交给我。","notes":[],"heads":["摩西传达律法"]},{"n":23,"t":"山被火焰烧着，你们听见从黑暗中发出的声音，那时，你们各支派的领袖和长老都挨近我。","notes":[]},{"n":24,"t":"你们说：‘看哪，耶和华－我们的神将他的荣耀和他的伟大显给我们看，我们也听见他从火中发出的声音。今日我们看到神与人说话，人还活着。","notes":[]},{"n":25,"t":"现在这大火将要吞灭我们，我们何必死呢？若再听见耶和华我们神的声音，我们就必死。","notes":[]},{"n":26,"t":"凡血肉之躯，有谁像我们一样，听见了永生神从火中讲话的声音还能活着呢？","notes":[]},{"n":27,"t":"求你近前去，听耶和华－我们神所要说的一切话，将耶和华－我们神对你说的话都传给我们，我们就听从遵行。’","notes":[]},{"n":28,"t":"“你们对我说的话，耶和华都听见了。耶和华对我说：‘这百姓对你说的话，我听见了；他们所说的都对。","notes":[]},{"n":29,"t":"惟愿他们存这样的心敬畏我，常遵守我一切的诫命，使他们和他们的子孙永远得福。","notes":[]},{"n":30,"t":"你去对他们说：你们回帐棚去吧！","notes":[]},{"n":31,"t":"至于你，可以站在我这里，我要将一切诫命、律例、典章传给你。你要教导他们，使他们在我赐他们为业的地上遵行。’","notes":[]},{"n":32,"t":"所以，你们要照耶和华－你们神所吩咐的谨守遵行，不可偏离左右。","notes":[]},{"n":33,"t":"你们要走耶和华－你们的神所吩咐的一切道路，使你们可以存活得福，并使你们的日子在所要承受的地上得以长久。”","notes":[]}]},"6":{"heading":"","verses":[{"n":1,"t":"“这是耶和华－你们的神所吩咐要教导你们的诫命、律例、典章，叫你们在所要过去得为业的地上遵行，","notes":[]},{"n":2,"t":"好叫你和你的子孙在一生的日子都敬畏耶和华－你的神，谨守他的一切律例、诫命，就是我所吩咐你的，使你的日子得以长久。","notes":[]},{"n":3,"t":"以色列啊，你要听，要谨守遵行，使你可以在那流奶与蜜之地得福，人数极其增多，正如耶和华－你列祖的神所应许你的。","notes":[]},{"n":4,"t":"“以色列啊，你要听！耶和华－我们的神是独一的主。","notes":["“主”：原文是“耶和华”。"]},{"n":5,"t":"你要尽心、尽性、尽力爱耶和华－你的神。","notes":[]},{"n":6,"t":"我今日吩咐你的这些话都要记在心上，","notes":[]},{"n":7,"t":"也要殷勤教导你的儿女。无论你坐在家里，走在路上，躺下，起来，都要吟诵。","notes":[]},{"n":8,"t":"要系在手上作记号，戴在额上作经匣；","notes":["“额上”：原文是“两眼之间”。","“经匣”指“把经文放在皮制的匣中作额饰”；11．18同。"]},{"n":9,"t":"又要写在你房屋的门框上和你的城门上。","notes":[]},{"n":10,"t":"“耶和华－你的神必领你进他向你列祖亚伯拉罕、以撒、雅各起誓要给你的地。那里有又大又美的城镇，不是你建造的；","notes":[]},{"n":11,"t":"有装满各样美物的房屋，不是你装满的；有挖成的水井，不是你挖的；有葡萄园、橄榄园，不是你栽植的；你吃了而且饱足。","notes":[]},{"n":12,"t":"你要谨慎，免得你忘记领你从埃及地为奴之家出来的耶和华。","notes":[]},{"n":13,"t":"你要敬畏耶和华－你的神，事奉他，奉他的名起誓。","notes":[]},{"n":14,"t":"不可随从别神，就是你们四围民族的众神明，","notes":[]},{"n":15,"t":"因为在你中间的耶和华－你的神是忌邪的神，恐怕耶和华－你神的怒气向你发作，把你从地上除灭。","notes":["“忌邪”：原文是“妒忌”，意思是“不容许有对立的神明”。"]},{"n":16,"t":"“你们不可试探耶和华－你们的神，像你们在玛撒那样试探他。","notes":[]},{"n":17,"t":"要谨慎遵守耶和华－你们神的诫命，和他所吩咐的法度、律例。","notes":[]},{"n":18,"t":"耶和华眼中看为正直和美善的事，你都要遵行，使你得福，可以进去得耶和华向你列祖起誓应许的美地，","notes":[]},{"n":19,"t":"可以从你面前赶出你所有的仇敌，正如耶和华所说的。","notes":[]},{"n":20,"t":"“日后，你的儿子问你说：‘耶和华－我们神吩咐你们的法度、律例、典章是什么意思呢？’","notes":[]},{"n":21,"t":"你要告诉你的儿子说：‘我们在埃及作过法老的奴仆，耶和华用大能的手将我们从埃及领出来。","notes":[]},{"n":22,"t":"在我们眼前，他施行重大可怕的神迹奇事对付埃及、法老和他的全家。","notes":[]},{"n":23,"t":"他将我们从那里领出来，为要领我们进入他向我们列祖起誓应许之地，把这地赐给我们。","notes":[]},{"n":24,"t":"耶和华又吩咐我们遵行这一切的律例，敬畏耶和华－我们的神，使我们一生得福，得以存活，像今日一样。","notes":[]},{"n":25,"t":"我们若照耶和华－我们神所吩咐的，在他面前谨守遵行这一切诫命，这就是我们的义了。’”","notes":[]}]},"7":{"heading":"选民","verses":[{"n":1,"t":"“耶和华－你的神领你进入你要得为业之地，从你面前赶出许多国家，就是比你更强大的七个国家：赫人、革迦撒人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人。","notes":[]},{"n":2,"t":"当耶和华－你的神把他们交给你，你击杀他们的时候，你要完全消灭他们，不可与他们立约，也不可怜惜他们。","notes":[]},{"n":3,"t":"不可与他们结亲；不可将你的女儿嫁给他的儿子，也不可叫你的儿子娶他的女儿。","notes":[]},{"n":4,"t":"因为他必使你的儿女离弃我，去事奉别神，以致耶和华的怒气向你们发作，迅速将你除灭。","notes":[]},{"n":5,"t":"你们却要这样处置他们：拆毁他们的祭坛，打碎他们的柱像，砍断他们的亚舍拉，用火焚烧他们雕刻的偶像。","notes":[]},{"n":6,"t":"“因为你是属于耶和华－你神神圣的子民；耶和华－你的神从地面上的万民中拣选你，作自己宝贵的子民。","notes":[]},{"n":7,"t":"耶和华专爱你们，拣选你们，并非因你们人数比任何民族多，其实你们的人数在各民族中是最少的。","notes":[]},{"n":8,"t":"因为耶和华爱你们，又因要遵守他向你们列祖所起的誓，耶和华就用大能的手领你们出来，救赎你脱离为奴之家，脱离埃及王法老的手。","notes":[]},{"n":9,"t":"所以，你知道耶和华－你的神，他是神，是信实的神。他向爱他、守他诫命的人守约施慈爱，直到千代；","notes":[]},{"n":10,"t":"向恨他的人，他必当面报应，消灭他们。凡恨他的，他必当面报应，绝不迟延。","notes":[]},{"n":11,"t":"所以，你要谨守我今日所吩咐你的诫命、律例、典章，遵行它们。”","notes":[]},{"n":12,"t":"“你们若听从这些典章，谨守遵行，耶和华－你的神必照他向你列祖所起的誓，对你守约，施慈爱。","notes":[],"heads":["遵行诫命必蒙福"]},{"n":13,"t":"他必爱你，赐福给你，使你人数增多，也必在他向你列祖起誓要给你的地上赐福给你身所生的，你地所产的，你的五谷、新酒和新的油，以及你的牛犊、羔羊。","notes":[]},{"n":14,"t":"你必蒙福胜过万民；你没有不育的男人和不孕的女人，牲畜也没有不生育的。","notes":[]},{"n":15,"t":"耶和华必使一切的疾病远离你；你所知道埃及各样的恶疾，他不加在你身上，反要加在所有恨你的人身上。","notes":[]},{"n":16,"t":"你要吞灭耶和华－你的神交给你的各民族，你的眼目不可顾惜他们。你也不可事奉他们的神明，因为这必成为你的圈套。","notes":[]},{"n":17,"t":"“你若心里说，这些国的人数比我多，我怎能赶出他们呢？","notes":[]},{"n":18,"t":"你不必怕他们，要牢牢记住耶和华－你神向法老和埃及全地所行的事，","notes":[]},{"n":19,"t":"你亲眼见过的大考验、神迹、奇事、大能的手和伸出来的膀臂，都是耶和华－你神领你出来所施行的。耶和华－你的神也必照样处置你所惧怕的各民族，","notes":[]},{"n":20,"t":"并且耶和华－你的神必派瘟疫 攻击他们，直到那剩下而躲起来的人都从你面前灭亡。","notes":["“瘟疫”或译“黄蜂”。"]},{"n":21,"t":"不要因他们惊恐，因为耶和华－你的神在你中间是大而可畏的神。","notes":[]},{"n":22,"t":"耶和华－你的神必将这些国从你面前渐渐赶出；你不可迅速把他们消灭，免得野地的走兽多起来危害你。","notes":[]},{"n":23,"t":"耶和华－你的神必将他们交给你，大大扰乱他们，直到他们被除灭。","notes":[]},{"n":24,"t":"他又要将他们的君王交在你手中，你必从天下除去他们的名；必无一人能在你面前站立得住，直到你把他们除灭了。","notes":[]},{"n":25,"t":"你们要用火焚烧他们神明的雕刻偶像；不可贪爱偶像上的金银，也不可私自收起来，免得你因此陷入圈套，因为这是耶和华－你神所憎恶的。","notes":[]},{"n":26,"t":"你不可把可憎之物带进你的家，否则，你就像它一样成为当毁灭的。你要彻底憎恨它，极其厌恶它，因为这是当毁灭的。”","notes":[]}]},"8":{"heading":"将得美地","verses":[{"n":1,"t":"“我今日所吩咐你的一切诫命，你们要谨守遵行，好使你们存活，人数增多，可以进去得耶和华向你们列祖起誓应许的那地。","notes":[]},{"n":2,"t":"你要记得，这四十年耶和华─你的神在旷野一路引导你，是要磨炼你，考验你，为要知道你的心如何，是否愿意遵守他的诫命。","notes":[]},{"n":3,"t":"他磨炼你，任你饥饿，将你和你列祖所不认识的吗哪赐给你吃，使你知道，人活着，不是单靠食物，乃是靠耶和华口里所出的一切话。","notes":[]},{"n":4,"t":"这四十年，你身上的衣服没有穿破，你的脚也没有肿。","notes":[]},{"n":5,"t":"你心里要知道，耶和华─你的神管教你，像人管教儿女一样。","notes":[]},{"n":6,"t":"你要谨守耶和华─你神的诫命，遵行他的道，敬畏他。","notes":[]},{"n":7,"t":"“耶和华─你的神必领你进入美地，那地有河流，有泉源和深渊的水从谷中和山上流出。","notes":[]},{"n":8,"t":"那地有小麦、大麦、葡萄树、无花果树、石榴树，那地也有橄榄油和蜂蜜。","notes":[]},{"n":9,"t":"那地没有缺乏，你在那里有食物吃，一无所缺；那地的石头是铁，山中可以挖铜。","notes":[]},{"n":10,"t":"你吃得饱足，要称颂耶和华─你的神，因为他将那美地赐给你。”","notes":[]},{"n":11,"t":"“你要谨慎，免得忘记耶和华─你的神，不守他的诫命、典章、律例，就是我今日吩咐你的。","notes":[],"heads":["不可忘记耶和华"]},{"n":12,"t":"免得你吃得饱足，建造上好的房屋，住在其中，","notes":[]},{"n":13,"t":"你的牛羊增多，你的金银增多，你拥有的一切全都增多，","notes":[]},{"n":14,"t":"于是你的心高傲，忘记耶和华─你的神。他曾将你从埃及地为奴之家领出来，","notes":[]},{"n":15,"t":"曾引领你经过那大而可怕的旷野，有火蛇、蝎子、干旱无水之地。他也曾为你使水从坚硬的磐石中流出来，","notes":[]},{"n":16,"t":"又在旷野将你列祖所不认识的吗哪赐给你吃，为要磨炼你，考验你，终久使你享福。","notes":[]},{"n":17,"t":"你心里说：‘这财富是我的力量、我手的能力得来的。’","notes":[]},{"n":18,"t":"你要记得耶和华─你的神，因为得财富的能力是他给你的，为要坚守他向你列祖起誓所立的约，像今日一样。","notes":[]},{"n":19,"t":"你若忘记耶和华─你的神，随从别神，事奉它们，敬拜它们，我今日警告你们，你们必定灭亡。","notes":[]},{"n":20,"t":"耶和华在你们面前怎样使列国灭亡，你们也必照样灭亡，因为你们不听从耶和华─你们神的话。”","notes":[]}]},"9":{"heading":"百姓悖逆","verses":[{"n":1,"t":"“以色列啊，你要听！你今日要过约旦河，进去占领比你更强大的列国，那里的城镇又大，城墙又坚固，如天一样高。","notes":[]},{"n":2,"t":"那里的百姓是亚衲族人，又高又壮，是你所知道的；你也听说过：‘谁能在亚衲族人面前站立得住呢？’","notes":[]},{"n":3,"t":"你今日应当知道，耶和华─你的神在你前面渡过去，如同吞噬的火，要除灭他们，并要在你面前将他们制伏，使你可以赶出他们，速速消灭他们，正如耶和华向你所说的。","notes":[]},{"n":4,"t":"“耶和华─你的神将他们从你面前赶出以后，你心里不可说：‘耶和华领我得这地是因我的义。’其实，耶和华将这些国家从你面前赶出去是因他们的恶。","notes":[]},{"n":5,"t":"你能进去得他们的地，并不是因你的义，也不是因你心里正直，而是因这些国家的恶，耶和华─你的神才把他们从你面前赶出去，为了应验耶和华向你列祖亚伯拉罕、以撒、雅各起誓应许的话。”","notes":[]},{"n":6,"t":"“你当知道，耶和华─你的神将这美地赐你为业，并不是因你的义；你本是硬着颈项的百姓。","notes":[],"heads":["金牛犊"]},{"n":7,"t":"你要记得，不要忘记，你在旷野怎样惹耶和华－你的神发怒。自从你出了埃及地的那日，直到你们来到这地方，你们常常悖逆耶和华。","notes":[]},{"n":8,"t":"你们在何烈山惹耶和华发怒，耶和华对你们动怒，甚至要除灭你们。","notes":[]},{"n":9,"t":"我上了山，要领受两块石版，就是耶和华与你们立约的版。那时我在山上住了四十昼夜，没有吃饭，也没有喝水。","notes":[]},{"n":10,"t":"耶和华把那两块石版交给我，是神用指头写成的；版上是耶和华在大会的那一天，在山上从火中对你们所说的一切话。","notes":[]},{"n":11,"t":"过了四十昼夜，耶和华把那两块石版，就是约版，交给我。","notes":[]},{"n":12,"t":"耶和华对我说：‘起来，赶快从这里下去！因为你从埃及领出来的百姓已经败坏了；他们这么快偏离了我所吩咐的道，为自己铸造偶像。’","notes":[]},{"n":13,"t":"“耶和华对我说：‘我看这百姓，看哪，他们是硬着颈项的百姓。","notes":[]},{"n":14,"t":"你且由着我，我要除灭他们，从天下涂去他们的名，我要使你成为比他们更大更强的国。’","notes":[]},{"n":15,"t":"于是我转身下山，山上有火燃烧，两块约版在我双手中。","notes":[]},{"n":16,"t":"我观看，看哪，你们得罪了耶和华－你们的神，为自己铸成了一头牛犊，迅速偏离了耶和华所吩咐你们的道，","notes":[]},{"n":17,"t":"我拿着那两块石版，从我双手中扔出去，在你们眼前把它们摔碎了。","notes":[]},{"n":18,"t":"因为你们所犯的一切罪，做了耶和华眼中看为恶的事，惹他发怒，我就像从前一样俯伏在耶和华面前四十昼夜，没有吃饭，没有喝水。","notes":[]},{"n":19,"t":"我很害怕，因为耶和华向你们大发烈怒，要除灭你们。但那一次耶和华又应允了我。","notes":[]},{"n":20,"t":"耶和华也向亚伦非常生气，甚至要除灭他；那时我也为亚伦祈祷。","notes":[]},{"n":21,"t":"我把那使你们犯罪所铸的牛犊拿来，用火焚烧，捣碎后再磨成粉末，好像灰尘。我把这灰尘撒在从山上流下来的溪水中。","notes":[]},{"n":22,"t":"“你们在他备拉、玛撒、基博罗．哈他瓦又惹耶和华发怒。","notes":[]},{"n":23,"t":"耶和华叫你们离开加低斯．巴尼亚，说：‘你们上去得我所赐给你们的地。’那时，你们违背了耶和华－你们神的指示，不信服他，不听从他的话。","notes":[]},{"n":24,"t":"自从我认识你们的日子以来，你们常常悖逆耶和华。","notes":["本节撒玛利亚五经和七十士译本是“自从主认识你们的日子以来，你们常常悖逆他。”"]},{"n":25,"t":"“我因耶和华说要除灭你们，就在耶和华面前俯伏四十昼夜，像我以前俯伏一样。","notes":[]},{"n":26,"t":"我向耶和华祈祷，说：‘主耶和华啊，求你不要灭绝你的百姓，你的产业。他们是你用大能救赎，用你强有力的手从埃及领出来的。","notes":[]},{"n":27,"t":"求你记念你的仆人亚伯拉罕、以撒、雅各，不看这百姓的顽梗、邪恶、罪愆，","notes":[]},{"n":28,"t":"免得你领我们出来的那地之人说：耶和华因为不能将这百姓领进他所应许之地，又因恨他们，所以领他们出去，要在旷野杀他们。","notes":[]},{"n":29,"t":"其实他们是你的百姓，你的产业，是你用大能和伸出的膀臂领出来的。’”","notes":[]}]},"10":{"heading":"摩西重新接受诫命","verses":[{"n":1,"t":"“那时，耶和华对我说：‘你要凿出两块石版，和先前的一样，上山到我这里来。你也要造一个木柜。","notes":[]},{"n":2,"t":"我要把你先前摔碎的版上所写的字，写在这版上；你要把这版放在柜里。’","notes":[]},{"n":3,"t":"于是我用金合欢木造了一个柜子，又凿出两块石版，和先前的一样。我手里拿着这两块版上山。","notes":[]},{"n":4,"t":"耶和华将那大会之日、在山上从火中所吩咐你们的十条诫命，照先前所写的写在这版上。耶和华把它们交给我。","notes":[]},{"n":5,"t":"我转身下山，将这版放在我所造的柜里，现今这版还在那里，正如耶和华所吩咐我的。","notes":[]},{"n":6,"t":"（以色列人从比罗比尼．亚干起行，来到摩西拉，亚伦死在那里，就葬在那里。他的儿子以利亚撒接续他担任祭司的职分。","notes":["“比罗比尼．亚干”或译“比尼．亚干井”。"]},{"n":7,"t":"他们从那里起行，来到谷歌大，又从谷歌大来到约巴他，有溪水之地。","notes":[]},{"n":8,"t":"那时，耶和华将利未支派分别出来，抬耶和华的约柜，又侍立在耶和华面前事奉他，奉他的名祝福，直到今日。","notes":[]},{"n":9,"t":"因此，利未没有像他的弟兄有产业，耶和华是他的产业，正如耶和华－你神所应许他的。）","notes":[]},{"n":10,"t":"“我又像先前一样在山上停留了四十昼夜。这一次耶和华也应允我，不将你灭绝。","notes":[]},{"n":11,"t":"耶和华对我说：‘起来，走在百姓前面，领他们进去得我向他们列祖起誓要给他们的地。’”","notes":[]},{"n":12,"t":"“以色列啊，现在耶和华－你的神向你要的是什么呢？只要你敬畏耶和华－你的神，遵行他一切的道，爱他，尽心尽性事奉耶和华－你的神，","notes":[],"heads":["神的要求"]},{"n":13,"t":"遵守耶和华的诫命律例，就是我今日所吩咐你的，为要使你得福。","notes":[]},{"n":14,"t":"看哪，天和天上的天，地和地上所有的，都属耶和华－你的神。","notes":[]},{"n":15,"t":"然而，耶和华专爱你的列祖，爱他们，从万民中拣选你们，就是他们的后裔，像今日一样。","notes":[]},{"n":16,"t":"所以你们的心要受割礼，不可再硬着颈项。","notes":[]},{"n":17,"t":"因为耶和华－你们的神是万神之神，万主之主，是伟大、强有力、可畏的神，不看人的情面，也不受贿赂。","notes":[]},{"n":18,"t":"他为孤儿寡妇伸冤，爱护寄居的，赐给他衣食。","notes":[]},{"n":19,"t":"所以你们要爱护寄居的，因为你们在埃及地也作过寄居的。","notes":[]},{"n":20,"t":"你要敬畏耶和华－你的神，事奉他，紧紧跟随他，奉他的名起誓。","notes":[]},{"n":21,"t":"他是你当赞美的，是你的神，为你做了大而可畏的事，这些是你亲眼见过的。","notes":[]},{"n":22,"t":"你的列祖七十人下埃及，现在耶和华－你的神却使你如同天上的星那样多。”","notes":[]}]},"11":{"heading":"神的伟大","verses":[{"n":1,"t":"“你要爱耶和华－你的神，天天遵守他的吩咐、律例、典章、诫命。","notes":[]},{"n":2,"t":"今日你们应当知道，而不是你们的儿女，因为他们不知道，也没有见过耶和华─你们神的管教、他的伟大、他大能的手和伸出来的膀臂，","notes":[]},{"n":3,"t":"以及他在埃及向埃及王法老和其全地所行的神迹奇事；","notes":[]},{"n":4,"t":"他怎样对待埃及的军队、马和战车，他们追赶你们的时候，耶和华怎样用红海的水淹没他们，消灭了他们，直到今日；","notes":[]},{"n":5,"t":"他在旷野怎样待你们，直到你们来到这地方，","notes":[]},{"n":6,"t":"以及他怎样待吕便子孙，以利押的儿子大坍、亚比兰，地怎样在以色列人中开了裂口，吞了他们和他们的家眷，帐棚，以及跟他们在一起所有活着的。","notes":[]},{"n":7,"t":"惟有你们亲眼见过耶和华所做的一切大事。”","notes":[]},{"n":8,"t":"“所以，你们要遵守我今日所吩咐的一切诫命，使你们刚强，可以进去得你们所要得的那地，就是你们将过河到那里要得的，","notes":[],"heads":["应许之地的福泽"]},{"n":9,"t":"也使你们的日子，在耶和华向你们列祖起誓要给他们和他们后裔的地上得以长久，那是流奶与蜜之地。","notes":[]},{"n":10,"t":"你要进去得为业的那地，不像你出来的埃及地。在埃及，你撒种后，要用脚浇灌，像浇灌菜园一样。","notes":[]},{"n":11,"t":"你们要过去得为业的那地乃是有山有谷、天上的雨水滋润之地，","notes":[]},{"n":12,"t":"是耶和华－你神所眷顾的地；从岁首到年终，耶和华－你神的眼目时常看顾那地。","notes":[]},{"n":13,"t":"“你们若留心听从我今日所吩咐你们的诫命，爱耶和华－你们的神，尽心尽性事奉他，","notes":[]},{"n":14,"t":"我必按时降下雨水在你们的地上，就是秋雨和春雨，使你们可以收藏五谷、新酒和新的油，","notes":["“我”：撒玛利亚五经、七十士译本和其他古译本是“他”。"]},{"n":15,"t":"也必使田野为你的牲畜长出草来；这样，你必吃得饱足。","notes":[]},{"n":16,"t":"你们要谨慎，免得心受诱惑，转去事奉别神，敬拜它们，","notes":[]},{"n":17,"t":"以致耶和华的怒气向你们发作，使天封闭不下雨，使地不出产，使你们在耶和华所赐给你们的美地上速速灭亡。","notes":[]},{"n":18,"t":"“你们要将我这些话存在心里，留在意念中，系在手上作记号，戴在额上作经匣。","notes":["“额上”：原文是“两眼之间”。"]},{"n":19,"t":"你们也要将这些话教导你们的儿女，无论坐在家里，行在路上，躺下，起来，都要讲论，","notes":[]},{"n":20,"t":"又要写在房屋的门框上和你的城门上。","notes":[]},{"n":21,"t":"这样，你们和你们子孙的日子必在耶和华向你们列祖起誓要给他们的地上得以增多，如天地之长久。","notes":[]},{"n":22,"t":"你们若留心谨守遵行我所吩咐这一切的诫命，爱耶和华－你们的神，遵行他一切的道，紧紧跟随他，","notes":[]},{"n":23,"t":"他必从你们面前赶出这一切国家，你们也要占领比你们更大更强的国家。","notes":[]},{"n":24,"t":"凡你们脚掌所踏之地都必归于你们；从旷野到黎巴嫩，从幼发拉底大河，直到西边的海，都要成为你们的疆土。","notes":[]},{"n":25,"t":"必无一人能在你们面前站立得住；耶和华－你们的神必照他所说的，使惧怕惊恐临到你们所踏的全地。","notes":[]},{"n":26,"t":"“看，我今日将祝福与诅咒都陈明在你们面前。","notes":[]},{"n":27,"t":"你们若听从耶和华─你们神的诫命，就是我今日所吩咐你们的，就必蒙福。","notes":[]},{"n":28,"t":"你们若不听从耶和华─你们神的诫命，偏离我今日所吩咐你们的道，去随从你们所不认识的别神，就必受诅咒。","notes":[]},{"n":29,"t":"当耶和华－你的神领你进入要得为业的那地，你就要在基利心山上宣布祝福，在以巴路山上宣布诅咒。","notes":[]},{"n":30,"t":"这二座山岂不是在约旦河的那边，日落的方向，在住亚拉巴的迦南人之地，吉甲的前面，靠近摩利橡树吗？","notes":[]},{"n":31,"t":"你们过约旦河，进去得耶和华－你们的神所赐你们为业之地；当你们占领它，在那地居住的时候，","notes":[]},{"n":32,"t":"你们要谨守遵行我今日在你们面前颁布的一切律例典章。”","notes":[]}]},"12":{"heading":"惟一的敬拜场所","verses":[{"n":1,"t":"“你们活在世上的日子，在耶和华─你列祖的神所赐你为业的地上，你们要谨守遵行这些律例典章：","notes":[]},{"n":2,"t":"你们占领的国家所事奉他们众神明的地方，无论是在高山，在小山，在一切的青翠树下，你们要彻底毁坏；","notes":[]},{"n":3,"t":"要拆毁他们的祭坛，打碎他们的柱像，用火焚烧他们的亚舍拉，砍断他们神明的雕刻偶像，并要从那地方除去他们的名。","notes":[]},{"n":4,"t":"你们不可那样敬拜耶和华－你们的神。","notes":[]},{"n":5,"t":"但耶和华－你们的神在你们各支派中选择何处作为立他名的居所，你们就要到那里求问，","notes":[]},{"n":6,"t":"将你们的燔祭、祭物、十一奉献、手中的举祭、还愿祭、甘心祭，以及牛群羊群中头生的，都带到那里。","notes":[]},{"n":7,"t":"在那里，你们和你们的全家都可以在耶和华─你们神的面前吃，并且因你们手所做的一切蒙耶和华－你的神赐福而欢乐。","notes":[]},{"n":8,"t":"你们不可做像我们今日在这里所做的，各人行自己眼中看为正的一切事；","notes":[]},{"n":9,"t":"因为你们现在还没有进入耶和华－你神所赐你的安息，所给你的产业。","notes":[]},{"n":10,"t":"你们过了约旦河，住在耶和华─你们神给你们承受为业的地；他又使你们得享太平，不受四围一切仇敌扰乱，使你们安然居住。","notes":[]},{"n":11,"t":"那时你们要将我所吩咐你们的燔祭、祭物、十一奉献、手中的举祭，和向耶和华许愿的一切上好的祭，都带到耶和华─你们神所选择立他名的居所。","notes":[]},{"n":12,"t":"你们和儿女、仆婢，以及住在你们城里，没有与你们一起分得产业的利未人，都要在耶和华－你们的神面前欢乐。","notes":[]},{"n":13,"t":"你要谨慎，不可在自己所看中的各处献燔祭。","notes":[]},{"n":14,"t":"惟独耶和华从你的一个支派中所选择的地方，你要在那里献燔祭，在那里遵行我一切所吩咐你的。","notes":[]},{"n":15,"t":"“然而，你在各城里都可以照着耶和华－你神所赐给你的福分，随心所欲宰牲吃肉；无论洁净的人不洁净的人都可以吃，就如吃羚羊和鹿的肉一样。","notes":[]},{"n":16,"t":"只是血，你不可吃，要把它倒在地上，如同倒水一样。","notes":[]},{"n":17,"t":"你的五谷、新酒和新油的十分之一，或是牛群羊群中头生的，或是你的许愿祭、甘心祭和手中的举祭，都不可在你的城里吃，","notes":[]},{"n":18,"t":"必须在耶和华－你的神面前吃，在耶和华－你神所选择的地方，你和儿女、仆婢，以及住在你城里的利未人都可以吃，并要因你手所做的一切，在耶和华－你神面前欢乐。","notes":[]},{"n":19,"t":"你要谨慎，在你所住的地上，你永不可离弃利未人。","notes":[]},{"n":20,"t":"“耶和华－你的神照他的应许扩张你疆土的时候，你心里想要吃肉，说：‘我要吃肉’，就可以随心所欲吃肉。","notes":[]},{"n":21,"t":"耶和华－你神选择立他名的地方若离你太远，你可以照我所吩咐的，将耶和华赐给你的牛羊取些宰了，随心所欲在你的城里吃。","notes":[]},{"n":22,"t":"其实，就如吃羚羊和鹿的肉一样，你要这样吃它，无论洁净的人不洁净的人都可以一起吃。","notes":[]},{"n":23,"t":"但是你要坚定，不可吃血，因为血是生命；不可将生命与肉一起吃。","notes":[]},{"n":24,"t":"你不可吃血，要把它倒在地上，如同倒水一样。","notes":[]},{"n":25,"t":"不可吃血，好让你和你的子孙可以得福，因为你行了耶和华眼中看为正的事。","notes":[]},{"n":26,"t":"只是你分别为圣的物和你所还的愿，都要带到耶和华所选择的地方去。","notes":[]},{"n":27,"t":"你的燔祭，连肉带血，都要献在耶和华－你神的坛上。祭物的血要倒在耶和华－你神的坛上；肉你可以吃。","notes":[]},{"n":28,"t":"你要谨守听从我所吩咐的一切话，好让你和你的子孙可以永远得福，因为你行耶和华－你神眼中看为善、看为正的事。”","notes":[]},{"n":29,"t":"“耶和华－你神把你要进去赶出的列国从你面前剪除，并且你得了他们的地为业居住，","notes":[],"heads":["不可敬拜别神"]},{"n":30,"t":"那时你要谨慎，在他们从你面前被除灭之后，你不可受引诱随从他们，也不可求问他们的神明，说：‘这些国家怎样事奉他们的神明，我也要照样做。’","notes":[]},{"n":31,"t":"你不可向耶和华－你的神这样做，因为他们向他们的神明做了耶和华所憎恨、所厌恶的一切事，甚至将自己的儿女用火焚烧，献给他们的神明。","notes":[]},{"n":32,"t":"凡我所吩咐你们的事，你们都要谨守遵行，不可加添，也不可删减。”","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"“你中间若有先知或是做梦的人起来，向你显神迹奇事，","notes":[]},{"n":2,"t":"他对你说的神迹奇事应验了，说：‘我们去随从别神，事奉它们吧。’那是你不认识的。","notes":[]},{"n":3,"t":"你不可听那先知或是那做梦之人的话，因为这是耶和华－你们的神考验你们，要知道你们是否尽心尽性爱耶和华－你们的神。","notes":[]},{"n":4,"t":"你们要顺从耶和华－你们的神，敬畏他，谨守他的诫命，听从他的话，事奉他，紧紧跟随他。","notes":[]},{"n":5,"t":"那先知或那做梦的人要被处死，因为他出言悖逆那领你们出埃及地、救赎你脱离为奴之家的耶和华－你们的神，要引诱你离开耶和华－你神吩咐你要行的道。这样，你就把恶从你中间除掉。","notes":[]},{"n":6,"t":"“你的同胞兄弟，或是你的儿女，或是你怀中的妻，或是如同自己性命的朋友，若暗中引诱你，说：‘我们去事奉别神吧。’那是你和你列祖所不认识的，","notes":[]},{"n":7,"t":"你四围列国的神明，无论是离你近或离你远，从地这边到地那边，","notes":[]},{"n":8,"t":"你都不可附和他，也不要听从他。你的眼不可顾惜他，不可怜悯他，也不可袒护他。","notes":[]},{"n":9,"t":"你务必杀他；你先下手，然后众百姓才下手，把他处死。","notes":[]},{"n":10,"t":"要用石头打死他，因为他想引诱你离开那领你出埃及地为奴之家的耶和华－你的神。","notes":[]},{"n":11,"t":"全以色列都要听见而害怕，不敢在你中间再行这样的恶事了。","notes":[]},{"n":12,"t":"“若你听见人说，在耶和华－你神所赐给你居住的城镇中的一座，","notes":[]},{"n":13,"t":"有些无赖之徒从你中间出来，引诱本城的居民，说：‘我们去事奉别神吧。’那是你们不认识的，","notes":[]},{"n":14,"t":"你就要调查，探听，细心询问。看哪，是真的，确实有这可憎的事在你中间发生，","notes":[]},{"n":15,"t":"你务必用刀杀那城里的居民，把城里所有的，连牲畜都用刀灭尽。","notes":[]},{"n":16,"t":"你要把从城里所夺取的一切财物堆在广场中，用火将那城和其中夺取的一切财物全烧给耶和华－你的神。那城要永远成为废墟，不得重建。","notes":[]},{"n":17,"t":"那当毁灭的物一点都不可粘你的手，好让耶和华转回，不向你发烈怒，却恩待你，怜悯你，照他向你列祖所起的誓使你人数增多；","notes":[]},{"n":18,"t":"因为你听从耶和华－你神的话，遵守我今日所吩咐你的一切诫命，行耶和华－你神眼中看为正的事。”","notes":[]}]},"14":{"heading":"举哀时的禁例","verses":[{"n":1,"t":"“你们是耶和华─你们神的儿女。不可为了死人割划自己，也不可使额上光秃；","notes":["“额上”：原文是“两眼之间”。"]},{"n":2,"t":"因为你是属于耶和华－你神神圣的子民，耶和华从地面上的万民中拣选了你，作自己宝贵的子民。”","notes":[]},{"n":3,"t":"“凡可憎的物， 你都不可吃。","notes":[],"heads":["洁净和不洁净的食物"]},{"n":4,"t":"可吃的牲畜是：牛、绵羊、山羊、","notes":[]},{"n":5,"t":"鹿、羚、麃子、野山羊、瞪羚、羚羊、山绵羊。","notes":[]},{"n":6,"t":"凡蹄分两瓣，分趾蹄而又反刍食物的牲畜，你们都可以吃。","notes":[]},{"n":7,"t":"但那反刍或分蹄之中不可吃的是：骆驼、兔子、石獾，虽然反刍却不分蹄，对你们是不洁净的；","notes":[]},{"n":8,"t":"猪，虽然分蹄却不反刍，对你们也是不洁净的。它们的肉，你们一点都不可吃；它们的尸体，你们也不可摸。","notes":[]},{"n":9,"t":"“水中可吃的是这些：凡有鳍有鳞的都可以吃；","notes":[]},{"n":10,"t":"凡无鳍无鳞的都不可吃，对你们是不洁净的。","notes":[]},{"n":11,"t":"“凡洁净的鸟，你们都可以吃。","notes":[]},{"n":12,"t":"不可吃的是：雕、狗头雕、红头雕、","notes":[]},{"n":13,"t":"鹯、小鹰、鹞鹰的类群，","notes":[]},{"n":14,"t":"各种乌鸦的类群、","notes":[]},{"n":15,"t":"鸵鸟、夜鹰、鱼鹰、鹰的类群、","notes":[]},{"n":16,"t":"鸮鸟、猫头鹰、角鸱、","notes":[]},{"n":17,"t":"鹈鹕、秃雕、鸬鹚、","notes":[]},{"n":18,"t":"鹳、鹭鸶的类群、戴鵀与蝙蝠。","notes":[]},{"n":19,"t":"凡有翅膀却爬行的群聚动物对你们是不洁净的，都不可吃。","notes":[]},{"n":20,"t":"凡洁净的鸟，你们都可以吃。","notes":[]},{"n":21,"t":"“凡自然死去的动物，你们都不可吃，可以给城里寄居的人吃，或卖给外人，因为你是属于耶和华－你神神圣的子民。“不可用母山羊的奶来煮它的小山羊。”","notes":[]},{"n":22,"t":"“每年，你务必从你播种的一切收成，田地所出产的，取十分之一献上。","notes":[],"heads":["十一奉献的条例"]},{"n":23,"t":"要在耶和华－你神面前，就是他选择那里作为他名居所的地方，吃你所献十分之一的五谷、新酒和新的油，以及牛群羊群中头生的，好让你天天学习敬畏耶和华－你的神。","notes":[]},{"n":24,"t":"当耶和华－你的神赐福给你的时候，耶和华－你神选择立他名的地方若离你太远，路途太长，使你不能把这东西带到那里去，","notes":[]},{"n":25,"t":"你可以把它换成银子，把银子包起来，拿在手中，往耶和华－你神所选择的地方去。","notes":[]},{"n":26,"t":"在那里，你可以随心所欲用银子或买牛羊，或买清酒烈酒，或买任何你心所想的。你和你的全家要在耶和华－你神面前吃喝欢乐。","notes":[]},{"n":27,"t":"“住在你城里的利未人，你不可离弃他，因为他在你那里没有分得产业。","notes":[]},{"n":28,"t":"每三年的最后一年，你要把那一年收成的十分之一取出来，积存在你的城中；","notes":[]},{"n":29,"t":"那没有与你一起分得产业的利未人，和城里的寄居者，以及孤儿寡妇，都可以前来，吃得饱足，好让耶和华－你的神在你手里所做的一切事上赐福给你。”","notes":[]}]},"15":{"heading":"安息年的条例","verses":[{"n":1,"t":"“每七年的最后一年，你要施行豁免。","notes":[]},{"n":2,"t":"豁免的方式是这样：凡债主要把手里所借给邻舍的全豁免，不可向邻舍和弟兄追讨，因为耶和华的豁免已经宣告了。","notes":[]},{"n":3,"t":"你可以向外邦人追讨；但你弟兄欠你的，无论是什么，你都要放手豁免。","notes":[]},{"n":4,"t":"其实，在你中间不会有贫穷人；因为在耶和华－你神所赐你为业的地上，耶和华必大大赐福给你。","notes":[]},{"n":5,"t":"只要你留心听从耶和华－你神的话，谨守遵行我今日所吩咐你这一切的命令，","notes":[]},{"n":6,"t":"因为耶和华－你的神会照他所应许你的赐福给你，你必借给许多国家，却不需要去借贷；你要管辖许多国家，它们却不能管辖你。","notes":[]},{"n":7,"t":"“在耶和华－你神所赐给你的地上，任何一座城里，你弟兄中若有一个贫穷人，你不可硬着心，袖手不帮助你贫穷的弟兄。","notes":[]},{"n":8,"t":"你总要伸手帮助他，照他所缺乏的借给他，补他的不足。","notes":[]},{"n":9,"t":"你要谨慎，不可心起恶念，说：‘第七年的豁免年快到了’，你就冷眼看你贫穷的弟兄，什么都不给他。他若为你的缘故求告耶和华，你就有罪了。","notes":[]},{"n":10,"t":"你要慷慨解囊，给他的时候不要心疼，因为耶和华－你的神必为这事，在你一切的工作上和你手所做的一切赐福给你。","notes":[]},{"n":11,"t":"因为地上的贫穷人永远不会断绝，所以我吩咐你说：‘总要伸手帮助你地上困苦贫穷的弟兄。’”","notes":[]},{"n":12,"t":"“你弟兄中，若有一个希伯来男人或希伯来女人卖给你，已服事你六年，到了第七年就要让他自由离开你。","notes":[],"heads":["奴婢的条例"]},{"n":13,"t":"你让他自由离开的时候，不可让他空手而去，","notes":[]},{"n":14,"t":"要从你的羊群、禾场、压酒池中取一些，慷慨地送给他；耶和华－你的神怎样赐福给你，你也要照样给他。","notes":[]},{"n":15,"t":"要记得你在埃及地作过奴仆，耶和华－你的神救赎了你。为此，我今日将这事吩咐你。","notes":[]},{"n":16,"t":"他若对你说：‘我不愿意离开你’，因为他爱你和你的家，并且他在你那里很好，","notes":[]},{"n":17,"t":"你要拿锥子在门上穿透他的耳朵，他就永远成为你的奴仆了。你待婢女也要这样。","notes":[]},{"n":18,"t":"你让他从你那里自由离开的时候，不要看作困难，因为他已服事你六年，相当于雇工双倍的工钱。这样，耶和华－你的神必在你所做的一切事上赐福给你。”","notes":[]},{"n":19,"t":"“你牛群羊群中头生的，凡是公的，都要分别为圣，归给耶和华－你的神。头生的牛，不可用它来耕作；头生的羊，不可剪它的毛。","notes":[],"heads":["头生牛羊的条例"]},{"n":20,"t":"这头生的，你和你全家每年要到耶和华所选择的地方，在耶和华－你神面前吃。","notes":[]},{"n":21,"t":"这头生的若有残疾，瘸腿的或瞎眼的，若有任何严重缺陷，都不可献给耶和华－你的神。","notes":[]},{"n":22,"t":"你们可以在城里吃，洁净的人和不洁净的人都可以吃，就如吃羚羊和鹿一样。","notes":[]},{"n":23,"t":"只是它的血，你不可吃，要倒在地上，如同倒水一样。”","notes":[]}]},"16":{"heading":"逾越节","verses":[{"n":1,"t":"“你要守亚笔月，向耶和华－你的神守逾越节，因为在亚笔月，耶和华－你的神在夜间领你出埃及。","notes":[]},{"n":2,"t":"你当在那里，耶和华选择作为他名居所的地方，从羊群牛群中，将逾越节的祭牲献给耶和华－你的神。","notes":[]},{"n":3,"t":"这祭牲不可和有酵的东西一起吃。因为你曾匆忙离开埃及地，你要吃无酵饼，就是困苦饼七日，好让你一生的年日记得你从埃及地出来的那一日。","notes":[]},{"n":4,"t":"在你全境内，七日不可见到酵母。第一日晚上所献的肉，一点也不可留到早晨。","notes":[]},{"n":5,"t":"你不可在耶和华－你神所赐的各城中，任何一座城里，献逾越节的祭，","notes":[]},{"n":6,"t":"只可在那里，耶和华－你神选择作为他名居所的地方，在晚上日落的时候，就是你出埃及的时候，献逾越节的祭。","notes":[]},{"n":7,"t":"你要在耶和华－你神所选择的地方把肉烤来吃，次日早晨就回到你的帐棚去。","notes":[]},{"n":8,"t":"你要吃无酵饼六日，第七日要向耶和华－你的神守严肃会，不可做工。”","notes":[]},{"n":9,"t":"“你要计算七个七日：从你用镰刀开始收割庄稼时算起，一共七个七日。","notes":[],"heads":["七七收获节"]},{"n":10,"t":"你要向耶和华－你的神守七七节，按照耶和华－你神所赐你的福，献上你手里的甘心祭。","notes":[]},{"n":11,"t":"你和你的儿女、仆婢，以及住在你城里的利未人、在你中间寄居的和孤儿寡妇，都要在那里，耶和华－你神选择作为他名居所的地方，在耶和华－你神面前欢乐。","notes":[]},{"n":12,"t":"你要记得你在埃及作过奴仆，也要谨守遵行这些律例。”","notes":[]},{"n":13,"t":"“你收藏了禾场和压酒池的出产以后，就要守住棚节七日。","notes":[],"heads":["住棚节"]},{"n":14,"t":"在节期中，你和你的儿女、仆婢，以及住在你城里的利未人、寄居的和孤儿寡妇，都要欢乐。","notes":[]},{"n":15,"t":"在耶和华所选择的地方，你要向耶和华－你的神守节七日，因为耶和华－你的神要在你一切的收成上和你手里所做的一切赐福给你，你就非常欢乐。","notes":[]},{"n":16,"t":"“你所有的男丁要在除酵节、七七节、住棚节，一年三次，在耶和华－你神所选择的地方朝见他，不可空手朝见耶和华。","notes":[]},{"n":17,"t":"各人要按自己手中的能力，照耶和华－你神所赐你的福，奉献礼物。”","notes":[]},{"n":18,"t":"“你要在耶和华－你神所赐的各城中，为各支派设立审判官和官长。他们要按公义的判断审判百姓，","notes":[],"heads":["秉公审断"]},{"n":19,"t":"不可屈枉正直，不可看人的情面，也不可接受贿赂，因为贿赂能使智慧人的眼睛变瞎，又能曲解义人的证词。","notes":[]},{"n":20,"t":"公正！你要追求公正，好使你存活，承受耶和华－你神所赐你的地。”","notes":[]},{"n":21,"t":"“你为耶和华－你的神筑坛，不可在坛旁栽种任何树木作亚舍拉，","notes":[],"heads":["神所憎恶的敬拜"]},{"n":22,"t":"也不可为自己设立柱像，这是耶和华－你的神所憎恨的。”","notes":[]}]},"17":{"heading":"立王的指示","verses":[{"n":1,"t":"“凡有残疾，有任何恶疾的牛羊，你都不可献给耶和华－你的神，因为这是耶和华－你神所憎恶的。","notes":[]},{"n":2,"t":"“在你中间，在耶和华－你神所赐你的各城中，任何一座城里，若有男人或女人做了耶和华－你神眼中看为恶的事，违背了他的约，","notes":[]},{"n":3,"t":"去事奉别神，敬拜它们，或拜太阳，或拜月亮，或拜天上的万象，是我不曾吩咐的。","notes":["“我”：七十士译本是“他”。"]},{"n":4,"t":"有人告诉你，你也听见了，就要细心探听。看哪，是真的，确实有这可憎的事在以色列中发生，","notes":[]},{"n":5,"t":"你就要将行这恶事的男人或女人拉到城门外，用石头把这男人或女人处死。","notes":[]},{"n":6,"t":"要凭两个证人或三个证人的口，才可以把他处死，不可只凭一个证人的口处死他。","notes":[]},{"n":7,"t":"证人要先动手，然后众百姓也动手把他处死。这样，你就把恶从你中间除掉。","notes":[]},{"n":8,"t":"“你城中若有难以判断的案件，涉及流血，诉讼，或殴打等争讼的事，你就要起来，上到那里，耶和华－你神所选择的地方，","notes":[]},{"n":9,"t":"去见利未家的祭司和当时的审判官，求问他们，他们必将判决指示你。","notes":[]},{"n":10,"t":"他们在耶和华所选择的地方指示你的判决，你要执行，谨守遵行他们一切所教导你的。","notes":[]},{"n":11,"t":"要按照所教导你的律法、所告诉你的典章去执行；他们指示你的判决，你不可偏离左右。","notes":[]},{"n":12,"t":"若有人擅自行事，不听从那侍立在耶和华－你神那里事奉的祭司，或不听从审判官，那人就要处死。这样，你就把恶从以色列中除掉。","notes":[]},{"n":13,"t":"众百姓听见了都要害怕，不再擅自行事了。”","notes":[]},{"n":14,"t":"“你到了耶和华－你神所赐你的地，得了那地居住在其中的时候，若说：‘我要立王治理我，像我四围所有的国家一样’，","notes":[]},{"n":15,"t":"你一定要立耶和华－你神所拣选的人为你的王。要从你弟兄中立一人为你的王，不可立你弟兄之外的外邦人治理你。","notes":[]},{"n":16,"t":"只是王不可为自己加添马匹，也不可为加添马匹使百姓回埃及去，因耶和华曾对你们说：‘不可再回那条路去。’","notes":[]},{"n":17,"t":"王不可为自己多立妃嫔，免得他的心偏离；也不可为自己多积金银。","notes":[]},{"n":18,"t":"他登了国度的王位之后，要在利未家的祭司面前，将这律法书为自己抄写一份在书卷上。","notes":[]},{"n":19,"t":"这书要存在他那里，他一生的年日要诵读，好使他学习敬畏耶和华－他的神，谨守遵行这律法书上的一切话和这些律例，","notes":[]},{"n":20,"t":"免得他的心向弟兄高傲，偏离了这诫命，或向右或向左。这样，他和他的子孙就可以长久作王治理以色列。”","notes":[]}]},"18":{"heading":"祭司和利未人应得的份","verses":[{"n":1,"t":"“利未家的祭司和利未全支派在以色列中没有分得产业；他们可以吃耶和华的火祭，那是他的产业。","notes":[]},{"n":2,"t":"他在弟兄中没有产业；耶和华是他的产业，正如耶和华所应许他的。","notes":[]},{"n":3,"t":"祭司从百姓当得的权益是这样：凡献牛或羊为祭物的，要把前腿、两腮和胃给祭司。","notes":[]},{"n":4,"t":"初收的五谷、新酒和新的油，以及初剪的羊毛，也要给他。","notes":[]},{"n":5,"t":"因为耶和华－你的神从你众支派中拣选他，使他和他子孙永远奉耶和华的名侍立、事奉。","notes":[]},{"n":6,"t":"“利未人若离开他在以色列中所居住的任何一座城，一心愿意到耶和华所选择的地方，","notes":[]},{"n":7,"t":"就要在那里奉耶和华－他神的名事奉，正如他的众弟兄利未人在耶和华面前侍立一样。","notes":[]},{"n":8,"t":"除了卖祖产所得的以外，他们要吃同等分量的祭物。”","notes":["“他们”：撒玛利亚五经和七十士译本是“他”。"]},{"n":9,"t":"“你到了耶和华－你神所赐你之地，不可学那些国家行可憎恶的事。","notes":[],"heads":["禁止异教的习俗"]},{"n":10,"t":"你中间不可有人使儿女经火，也不可有占卜的、观星象的、行法术的 、行邪术的、","notes":[]},{"n":11,"t":"施符咒的、招魂的、行巫术的和求问死人的。","notes":[]},{"n":12,"t":"凡做这些事的都是耶和华所憎恶的；因这可憎恶的事，耶和华－你的神把他们从你面前赶出去。","notes":[]},{"n":13,"t":"你要向耶和华－你的神作完全人。","notes":[]},{"n":14,"t":"你所要赶出的那些国家都听从观星象的和占卜的，但是耶和华－你的神从来不准你这样做。”","notes":[]},{"n":15,"t":"“耶和华－你的神要从你弟兄中给你兴起一位先知像我，你们要听他。","notes":[],"heads":["兴起像摩西的先知"]},{"n":16,"t":"这正如你在何烈山大会的那日向耶和华－你的神所求的一切，说：‘求你不要再叫我听见耶和华－我神的声音，也不要再叫我看见这大火，免得我死亡。’","notes":[]},{"n":17,"t":"耶和华对我说：‘他们说得对。","notes":[]},{"n":18,"t":"我必在他们弟兄中给他们兴起一位先知像你。我要将当说的话放在他口里；他要将我一切所吩咐的都告诉他们。","notes":[]},{"n":19,"t":"谁不听从他奉我名所说的话，我必亲自向他追究。","notes":[]},{"n":20,"t":"若有先知擅自奉我的名说了我未曾吩咐他说的话，或是奉别神的名说话，那先知就必处死。’","notes":[]},{"n":21,"t":"你心里若说：‘我们怎能知道那话是耶和华未曾吩咐的呢？’","notes":[]},{"n":22,"t":"先知奉耶和华的名说话，所说的若没有实现，或不应验，这话就是耶和华未曾吩咐的，而是那先知擅自说的，你不必怕他。”","notes":[]}]},"19":{"heading":"逃城的设立","verses":[{"n":1,"t":"“耶和华－你的神将列国剪除，他们的地耶和华－你神已赐给你，你又赶出他们，并且住在他们的城镇和房屋，","notes":[]},{"n":2,"t":"那时，你要在耶和华－你神所赐你为业的地上，为自己指定三座城。","notes":[]},{"n":3,"t":"你要预备道路，将耶和华－你神使你承受为业的地分为三区，使任何一个杀人的可以逃到那里去。","notes":[]},{"n":4,"t":"“杀人的逃到那里得以存活的案例是这样：凡素无仇恨，无意中杀了邻舍的，","notes":[]},{"n":5,"t":"就如人与邻舍同入林中伐木，手拿斧子一砍，本想砍下树木，斧头却脱了把，飞落在邻舍身上，以致那人死去，这人就可以逃到那些城中的一座，得以存活，","notes":[]},{"n":6,"t":"免得报血仇的心中发火，去追赶那杀了人的，因为路途遥远就能追上他，把他杀死。其实他是不该死的，因为他与被杀者素无仇恨。","notes":[]},{"n":7,"t":"所以我吩咐你说，要为自己指定三座城。","notes":[]},{"n":8,"t":"耶和华－你的神若照他向你列祖所起的誓扩张你的疆土，将所应许赐你列祖的全地给你，","notes":[]},{"n":9,"t":"你若谨守遵行我今日所吩咐的这一切诫命，爱耶和华－你的神，天天遵行他的道，就要在这三座城之外，再添三座城，","notes":[]},{"n":10,"t":"免得无辜人的血流在耶和华－你神所赐你为业的地中间，血就归到你身上了。","notes":[]},{"n":11,"t":"“若有人恨他的邻舍，埋伏等着，起来击杀他，把他杀死，然后逃到这些城中的一座，","notes":[]},{"n":12,"t":"他本城的长老就要派人去，从那里把他带出来，交在报血仇者的手中，把他处死。","notes":[]},{"n":13,"t":"你的眼不可顾惜他，要从以色列中除掉流无辜血的罪，使你得福。”","notes":[]},{"n":14,"t":"“在耶和华－你神所赐你承受为业，所分得的地上，不可挪移你邻舍的地界，因为这是前人所定的。”","notes":[],"heads":["地界"]},{"n":15,"t":"“人无论犯什么罪，作什么恶，不可单凭一个人的见证，总要凭两个证人的口或三个证人的口才可定案。","notes":[],"heads":["证人的条例"]},{"n":16,"t":"若有人怀恶意，起来作证，控告他人犯法，","notes":[]},{"n":17,"t":"这两个争讼的人就要站在耶和华面前，和当时的祭司与审判官面前，","notes":[]},{"n":18,"t":"审判官要细心调查。看哪，证人作的是伪证，要用伪证陷害弟兄，","notes":[]},{"n":19,"t":"你们就要对付他如同他想要对付的弟兄一样。这样，你就把恶从你中间除掉。","notes":[]},{"n":20,"t":"其他的人听见就害怕，不敢在你中间再行这样的恶事了。","notes":[]},{"n":21,"t":"你的眼不可顾惜，要以命偿命，以眼还眼，以牙还牙，以手还手，以脚还脚。”","notes":[]}]},"20":{"heading":"战争的条例","verses":[{"n":1,"t":"“你出去与仇敌作战，若看见马匹、战车，以及比你更多的士兵，不要怕他们，因为领你出埃及地的耶和华－你的神与你同在。","notes":[]},{"n":2,"t":"你们将要上阵的时候，祭司要来，向士兵宣告，","notes":[]},{"n":3,"t":"对他们说：‘以色列啊，要听！你们今日将要与仇敌作战，不要心惊胆战，不要惧怕战兢，也不要因他们惊慌，","notes":[]},{"n":4,"t":"因为与你们同去的是耶和华－你们的神，他要为你们与仇敌作战，拯救你们。’","notes":[]},{"n":5,"t":"官长也要向士兵宣告说：‘谁建了新的房屋尚未奉献，他可以回家去，免得他阵亡，别人去奉献。","notes":[]},{"n":6,"t":"谁栽植了葡萄园尚未享用所结的果子，他可以回家去，免得他阵亡，别人去享用。","notes":[]},{"n":7,"t":"谁与女子订了婚尚未迎娶，他可以回家去，免得他阵亡，别人去娶。’","notes":[]},{"n":8,"t":"官长要继续对士兵说：‘谁惧怕，心惊胆战，可以回家去，免得他弟兄的心像他的心一样消沉。’","notes":[]},{"n":9,"t":"官长向士兵宣告完毕，军官就率领士兵去了。","notes":[]},{"n":10,"t":"“你来到一座城，要攻城之前，先向它宣告和平。","notes":[]},{"n":11,"t":"那城若愿意以和平回应，给你开城，城里所有的人就要为你做苦工，服事你。","notes":[]},{"n":12,"t":"若那城拒绝和平，却要与你打仗，你就要围困那城。","notes":[]},{"n":13,"t":"耶和华－你的神把那城交在你手里时，你就要用刀杀尽城里的男丁。","notes":[]},{"n":14,"t":"至于妇女、孩童、牲畜和城里所有的，你都可以取为自己的掠物。从仇敌所掠夺的，就是耶和华－你神所赐给你的，你都可以享用。","notes":[]},{"n":15,"t":"离你很远的各城，就是不属于这些国家的城镇，你都要这样对待他们。","notes":[]},{"n":16,"t":"但是这些民族的城镇，就是耶和华－你神所赐给你的产业，其中凡有气息的，一个都不可存留。","notes":[]},{"n":17,"t":"你要照耶和华－你神所吩咐的，将这些赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人全都灭绝，","notes":[]},{"n":18,"t":"免得他们教导你们去行一切可憎恶的事，就是他们向自己神明所行的，使你们得罪耶和华－你们的神。","notes":[]},{"n":19,"t":"“你若围困一座城，需要攻打许多日子才能夺取，就不可用斧头砍坏树木。你可以吃树上的果子，却不可把树砍下来。田间的树木岂是人，让你去围攻的吗？","notes":[]},{"n":20,"t":"只有那些你知道不能生产食物的树才可以毁坏；你可以把它们砍下来造攻城的工具，攻打那与你打仗的城，直到把城攻下。”","notes":[]}]},"21":{"heading":"未结案的谋杀案件","verses":[{"n":1,"t":"“在耶和华－你神所赐你为业的地上，若发现有人被杀，暴尸野地，不知道是谁杀的，","notes":[]},{"n":2,"t":"长老和审判官就要出去，从尸体那里量起，量到四围的城镇，","notes":["“审判官”：撒玛利亚五经是“官长”。"]},{"n":3,"t":"看哪一座城最靠近这尸体，那城的几位长老就要取一头未曾耕地、未曾负轭的母牛犊；","notes":[]},{"n":4,"t":"那城的长老要把这母牛犊牵到流着溪水、未曾耕耘、未曾撒种的山谷去，在谷中打断它的颈项。","notes":[]},{"n":5,"t":"利未人祭司要近前来，因为耶和华－你的神拣选他们来事奉他，奉耶和华的名祝福，并且有任何的争讼和殴打，都由他们的口判决。","notes":[]},{"n":6,"t":"离尸体最近的那座城的每位长老要在山谷中，在颈项被打断的母牛犊上面洗手，","notes":[]},{"n":7,"t":"声明说：‘我们的手未曾流这人的血；我们的眼也未曾看见这事。","notes":[]},{"n":8,"t":"耶和华啊，求你赦免你所救赎的百姓以色列，不要让无辜的血归在你的百姓以色列中间。’这样，他们流血的罪就必得赦免。","notes":[]},{"n":9,"t":"你行了耶和华眼中看为正的事，就可以从你中间除掉无辜的血。”","notes":[]},{"n":10,"t":"“你出去与仇敌作战的时候，耶和华－你的神将他交在你手中，你就掳了他为俘虏。","notes":[],"heads":["娶女俘虏的条例"]},{"n":11,"t":"若你在被掳的人中看见美丽的女子，喜欢她，要娶她为妻，","notes":[]},{"n":12,"t":"就可以带她到你家去。她要剪头发，修指甲，","notes":[]},{"n":13,"t":"脱去被掳时所穿的衣服，住在你家里为自己父母哀哭一个月。然后，你就可以与她同房；你作她的丈夫，她作你的妻子。","notes":[]},{"n":14,"t":"以后你若不喜欢她，就要让她自由离开，绝不可为钱把她卖了，也不可把她当奴隶看待，因为你已经占有过她。”","notes":[]},{"n":15,"t":"“人若有两个妻子，一个是他宠爱的，另一个是失宠的，她们都给他生了儿子，但长子是他失宠妻子生的；","notes":["“失宠的”：原文是“被恨的”；下同。"],"heads":["长子的继承权"]},{"n":16,"t":"到了分产业给儿子的时候，不可将自己宠爱的妻子所生的儿子立为长子，在他失宠妻子所生的长子之上。","notes":[]},{"n":17,"t":"他必须认失宠妻子所生的儿子为长子，在所有的产业中给他双分，因为这儿子是他壮年时生的，长子的名分应当是他的。”","notes":[]},{"n":18,"t":"“人若有顽梗忤逆的儿子，不听从父母的话，他们虽然惩戒他，他还是不听从他们，","notes":[],"heads":["逆子的处置"]},{"n":19,"t":"父母就要抓住他，带他出去到当地的城门，本城的长老那里，","notes":[]},{"n":20,"t":"对本城的长老说：‘我们这个儿子顽梗忤逆，不听从我们的话，是贪食好酒的人。’","notes":[]},{"n":21,"t":"然后，城里的众人就要用石头将他打死。这样，你就把恶从你中间除掉，全以色列听见了都要害怕。”","notes":[]},{"n":22,"t":"“人若犯了死罪被处死，你把他挂在木头上，","notes":[],"heads":["其他条例"]},{"n":23,"t":"不可让尸体留在木头上过夜，一定要当日把他埋葬，因为被挂的人是神所诅咒的。你不可玷污耶和华－你神所赐你为业的地。”","notes":[]}]},"22":{"heading":"贞洁的条例","verses":[{"n":1,"t":"“你若看见弟兄的牛或羊迷了路，不可避开它们，总要把它们牵回来交给你的弟兄。","notes":[]},{"n":2,"t":"你弟兄若离你远，或是你不认识他，你就要牵到你家，留在你那里，等你的弟兄来寻找就还给他。","notes":[]},{"n":3,"t":"你弟兄所失落的，无论是驴，衣服，或任何东西，你若发现，都要这样做，不能避开。","notes":[]},{"n":4,"t":"你若看见你弟兄的牛或驴在路上跌倒了，不可避开它们，总要帮助他把牛或驴拉起来。","notes":[]},{"n":5,"t":"“妇女不可穿戴男子所穿戴的，男人也不可穿妇女的衣服，因为这样做是耶和华－你神所憎恶的。","notes":[]},{"n":6,"t":"“你若路上看见鸟窝，无论在树上或地上，里头有小鸟或有蛋，母鸟伏在小鸟或蛋上，你不可连母鸟带小鸟一起拿去。","notes":[]},{"n":7,"t":"总要放母鸟走，只可以取小鸟。这样你就可以享福，日子得以长久。","notes":[]},{"n":8,"t":"“你若建造新房屋，要在屋顶安栏杆，免得有人从屋顶掉下来，血就归于你家。","notes":[]},{"n":9,"t":"“不可在你的葡萄园里栽种别的种子，免得你栽种所结的和葡萄园的果子都成了圣物。","notes":[]},{"n":10,"t":"不可并用牛和驴来耕地。","notes":[]},{"n":11,"t":"不可穿羊毛和细麻混合做成的衣服。","notes":[]},{"n":12,"t":"“你要在所披外衣的四个边上缝繸子。”","notes":[]},{"n":13,"t":"“人若娶妻，与她同房后恨恶她，","notes":[]},{"n":14,"t":"捏造她行可耻的事，把丑名加在她身上，说：‘我娶了这女人，亲近她，却发现她没有贞洁的凭据’。","notes":[]},{"n":15,"t":"女方的父母就要把这女子贞洁的凭据拿出去，到城门的本城长老那里。","notes":[]},{"n":16,"t":"女方的父亲要对长老说：‘我把女儿嫁给这人，他却恨恶她，","notes":[]},{"n":17,"t":"看哪，他捏造可耻的事，说：我发现你女儿没有贞洁的凭据。但是，这就是我女儿贞洁的凭据。’父母要把那布铺在本城长老的面前。","notes":[]},{"n":18,"t":"那城的长老要拿住那人，惩罚他，","notes":[]},{"n":19,"t":"罚他一百银子，给女方的父亲，因为他把丑名加在以色列一个少女身上。这女子仍是他的妻子，那人终身不可休她。","notes":[]},{"n":20,"t":"但若这事是真的，找不到女子贞洁的凭据，","notes":[]},{"n":21,"t":"他们就要把这女子带到她父家的门口，城里的人要用石头打死她，因为她在父家犯了淫乱，在以色列中做了可耻的事。这样，你就把恶从你中间除掉。","notes":[]},{"n":22,"t":"“若发现有人与有夫之妇同寝，就要将奸夫淫妇一起处死。这样，你就把恶从以色列中除掉。","notes":[]},{"n":23,"t":"“若一女子是处女，已经许配了人，有男子在城里遇见她，与她同寝，","notes":[]},{"n":24,"t":"你们就要把这二人带到那城的城门口，用石头打死他们。处死女子是因为她虽然在城里， 却没有喊叫；处死男子是因为他玷污了邻舍的妻子。这样，你就把恶从你中间除掉。","notes":[]},{"n":25,"t":"“若有男子在野地遇见已经许配人的女子，抓住她与她同寝，只要处死那与女子同寝的男子。","notes":[]},{"n":26,"t":"不可对女子处刑，这女子没有该死的罪。这案件就好比人起来攻击邻舍，把他杀了一样。","notes":[]},{"n":27,"t":"因为男子是在野地遇见她，这已经许配了人的女子虽然喊叫，却没有人救她。","notes":[]},{"n":28,"t":"“若有男子遇见没有许配人的少女，抓住她与她同寝，被人发现，","notes":[]},{"n":29,"t":"这男子就要拿五十银子给女子的父亲，并要娶她为妻，终身不可休她，因为他玷污了这女子。","notes":[]},{"n":30,"t":"“人不可娶继母为妻，不可掀开父亲衣服的下边。”","notes":["“掀开...下边”意思是“侵犯父亲的权益”；27．20同。"]}]},"23":{"heading":"不可进入圣会的人","verses":[{"n":1,"t":"“凡外肾损伤的，或被阉割的，不可入耶和华的会。","notes":[]},{"n":2,"t":"“私生子不可入耶和华的会；甚至到第十代，也不可入耶和华的会。","notes":[]},{"n":3,"t":"“亚扪人或摩押人不可入耶和华的会；甚至到第十代，也永不可入耶和华的会。","notes":[]},{"n":4,"t":"因为你们出埃及的时候，他们没有拿食物和水在路上迎接你们，并且雇了美索不达米亚的毗夺人，比珥的儿子巴兰来诅咒你。","notes":[]},{"n":5,"t":"然而耶和华－你的神不愿听巴兰，耶和华－你的神为你使诅咒变为祝福，因为耶和华－你的神爱你。","notes":[]},{"n":6,"t":"你一生一世永不可为他们求平安和福气。","notes":[]},{"n":7,"t":"“不可憎恶以东人，因为他是你的弟兄。不可憎恶埃及人，因为你曾在他的地上作过寄居的。","notes":[]},{"n":8,"t":"他们所生的第三代子孙可以入耶和华的会。”","notes":[]},{"n":9,"t":"“你出兵攻打敌人，要远离一切恶事。","notes":[],"heads":["军营的卫生"]},{"n":10,"t":"“你中间若有人因夜间梦遗而不洁净，就要出到营外，不可入营。","notes":[]},{"n":11,"t":"到了傍晚，他要用水洗澡，等到日落才可以入营。","notes":[]},{"n":12,"t":"“你要在营外划定一个地方，你可以出去在那里方便。","notes":[]},{"n":13,"t":"在你器械中当有一把锹；你出营外便溺以后，要用它挖洞，转身掩盖排泄物。","notes":[]},{"n":14,"t":"因为耶和华－你的神在你营中走动，要拯救你，将仇敌交给你，所以你的营应当圣洁，免得他见你那里有污秽之物就转身离开你。”","notes":[]},{"n":15,"t":"“你不可把从主人身边逃到你那里的奴仆，交回给他的主人，","notes":[],"heads":["一般条例"]},{"n":16,"t":"要让他在你那里与你同住，由他在你的城镇中选择一个自己喜欢的地方居住，不可欺负他。","notes":[]},{"n":17,"t":"“以色列的女子中不可作神庙娼妓；以色列的男子中也不可作神庙娼妓。","notes":[]},{"n":18,"t":"妓女和男娼的赏金，都不可带进耶和华－你神的殿中还愿，因为两者都是耶和华－你神所憎恶的。","notes":["“男娼”：原文是“狗”。"]},{"n":19,"t":"“你借给你弟兄的，无论是钱财是粮食，或任何可生利息的财物，都不可取利。","notes":[]},{"n":20,"t":"借给外邦人可以取利，但借给你的弟兄就不可取利；好让耶和华－你的神在你去得为业的地上和你手里所做的一切，赐福给你。","notes":[]},{"n":21,"t":"“你向耶和华－你的神许愿，不可迟延还愿，因为耶和华－你的神必定向你追讨，你就有罪了。","notes":[]},{"n":22,"t":"你若不许愿，倒没有罪。","notes":[]},{"n":23,"t":"你嘴唇所说的，你亲口承诺的，要照你甘心向耶和华－你神许的愿谨守遵行。","notes":[]},{"n":24,"t":"“你进入邻舍的葡萄园，可以随意吃葡萄，直到饱足，却不可装在器皿中。","notes":[]},{"n":25,"t":"你进入邻舍的庄稼中，可以用手摘麦穗，却不可用镰刀割取庄稼。”","notes":[]}]},"24":{"heading":"休妻和再婚的条例","verses":[{"n":1,"t":"“人若娶妻，作了她的丈夫，发现她有不合宜的事不喜欢她，而写休书交在她手中，打发她离开夫家，","notes":[]},{"n":2,"t":"妇人若离开夫家以后，去嫁别人，","notes":[]},{"n":3,"t":"后夫若恨恶她，写休书交在她手中，打发她离开夫家，又或者娶她为妻的后夫死了，","notes":[]},{"n":4,"t":"那休她的前夫就不可在妇人玷污之后再娶她为妻，因为这是耶和华所憎恶的。不可使耶和华－你神所赐为业之地蒙受玷污。","notes":[]},{"n":5,"t":"“人若娶了新娘，不可从军出征，也不可派他办理任何事情。他可以在家清闲一年，使他所娶的妻快活。","notes":[],"heads":["一般条例"]},{"n":6,"t":"“不可拿人的石磨或上面的磨石作抵押，因为这是拿人的命作抵押。","notes":[]},{"n":7,"t":"“若发现有人绑架以色列人中的一个弟兄，把他当奴隶对待，或把他卖了，那绑架人的就必处死。这样，你就把恶从你中间除掉。","notes":[]},{"n":8,"t":"“关于麻风的灾病，你们要谨慎，照利未家的祭司一切所指教你们的留心遵行。我怎样吩咐他们，你们要照样遵行。","notes":["“麻风”泛指传染性皮肤病。"]},{"n":9,"t":"要记得，在你们出埃及后的路途中，耶和华－你的神向米利暗所做的事。","notes":[]},{"n":10,"t":"“你借给邻舍，无论是什么，不可进他家拿抵押品。","notes":[]},{"n":11,"t":"要站在外面，等那借贷的人把抵押品拿出来交给你。","notes":[]},{"n":12,"t":"他若是困苦的人，你不可用他的抵押品盖着睡觉。","notes":[]},{"n":13,"t":"日落的时候，总要把抵押品还给他，让他用那件外衣盖着睡觉，他就为你祝福。这在耶和华－你的神面前就是你的义行了。","notes":[]},{"n":14,"t":"“困苦贫穷的雇工，无论是你的弟兄，或是住在你境内，在你城里寄居的，你都不可欺负他。","notes":["“欺负他”：七十士译本是“扣留他的工钱”。"]},{"n":15,"t":"要当日给他工钱，不可等到日落，因为他困苦，需要靠工钱过活，免得他因你的缘故求告耶和华，罪就归于你了。","notes":[]},{"n":16,"t":"“不可因儿子处死父亲，也不可因父亲处死儿子；各人要因自己的罪被处死。","notes":[]},{"n":17,"t":"“不可对寄居的和孤儿屈枉正直，也不可拿寡妇的衣服作抵押。","notes":[]},{"n":18,"t":"要记得你曾在埃及作过奴仆，耶和华－你的神从那里救赎了你，所以我吩咐你遵行这事。","notes":[]},{"n":19,"t":"“你在田间收割庄稼，若忘了一捆在田间，就不要再回去拿，要留给寄居的、孤儿和寡妇；好让耶和华－你的神在你手里所做的一切，赐福给你。","notes":[]},{"n":20,"t":"你打了橄榄树，枝上剩下的不可再打，要留给寄居的、孤儿和寡妇。","notes":[]},{"n":21,"t":"你摘葡萄园的葡萄，掉落的不可拾取，要留给寄居的、孤儿和寡妇。","notes":[]},{"n":22,"t":"你要记得你曾在埃及地作过奴仆，所以我吩咐你遵行这事。","notes":[]}]},"25":{"heading":"为去世的兄弟传宗接代","verses":[{"n":1,"t":"“人与人若有争讼，要求审判，当宣判义人为义，恶人有罪的时候，","notes":[]},{"n":2,"t":"恶人若该受责打，审判官就要叫他当着面，伏在地上，按他的罪照数责打。","notes":[]},{"n":3,"t":"只能打四十下，不可加多；多过这数目就是在你眼中作贱你的弟兄了。","notes":[]},{"n":4,"t":"“牛在踹谷的时候，不可笼住它的嘴。”","notes":[]},{"n":5,"t":"“兄弟住在一起，若其中一个死了，没有儿子，死者的妻子就不可出去嫁给陌生人。她丈夫的兄弟应当尽兄弟的本分，娶她为妻，与她同房。","notes":[]},{"n":6,"t":"妇人生的长子要归在已故兄弟的名下，免得他的名在以色列中涂去了。","notes":[]},{"n":7,"t":"那人若不情愿娶他兄弟的妻子，他兄弟的妻子就要上到城门长老那里，说：‘我丈夫的兄弟拒绝在以色列中为他的兄弟留名，不愿意为我尽兄弟的本分。’","notes":[]},{"n":8,"t":"本城的长老就要召那人来，跟他谈话。若他坚持说：‘我不情愿娶她。’","notes":[]},{"n":9,"t":"他兄弟的妻子就要在长老眼前来到那人跟前，脱下他脚上的鞋，吐唾沫在他脸上，回应说：‘凡不为兄弟建立家室的都要这样待他。’","notes":[]},{"n":10,"t":"在以色列中，他要以‘脱鞋之家’闻名。”","notes":[]},{"n":11,"t":"“若有人和弟兄争斗，其中一人的妻子近前去，为了救丈夫脱离那打丈夫之人的手，伸手抓住那人的下体，","notes":[],"heads":["其他条例"]},{"n":12,"t":"你就要砍断妇人的手，你的眼不可顾惜。","notes":[]},{"n":13,"t":"“你袋中不可有一大一小两样的法码。","notes":[]},{"n":14,"t":"你家里不可有一大一小两样的伊法。","notes":["“伊法”是量固体的量器或单位；下同。"]},{"n":15,"t":"当用准确公正的法码和伊法，好使你的日子在耶和华－你神所赐你的地上得以长久。","notes":[]},{"n":16,"t":"因为行这一切不义之事的人都是耶和华－你神所憎恶的。”","notes":[]},{"n":17,"t":"“你要记得你们出埃及的时候，亚玛力在路上怎样对待你，","notes":[],"heads":["命令消灭亚玛力人"]},{"n":18,"t":"在路上迎击你，趁你疲乏困倦时击杀所有在你后面软弱的人；并不敬畏神。","notes":[]},{"n":19,"t":"所以，当耶和华－你的神使你不被四围一切仇敌扰乱，在耶和华－你神赐你为业的地上得享平静的时候，你要把亚玛力的名从天下涂去；你不可忘记这事。”","notes":[]}]},"26":{"heading":"奉献初熟的土产","verses":[{"n":1,"t":"“你进去得了耶和华－你神所赐你为业的地，并且居住在那里的时候，","notes":[]},{"n":2,"t":"就要从耶和华－你神所赐你的地上，将收成的各种初熟土产取一些来，盛在筐子里，带到那里，耶和华－你神选择作为他名居所的地方，","notes":[]},{"n":3,"t":"到当时的祭司那里，对他说：‘我今日向耶和华－你的神宣认，我已来到耶和华向我们列祖起誓要赐给我们的地。’","notes":[]},{"n":4,"t":"祭司就从你手里把筐子接过来，供在耶和华－你神的祭坛前。","notes":[]},{"n":5,"t":"你要在耶和华－你神面前告白说：‘我的祖先原是一个流亡的亚兰人，带着稀少的人丁下到埃及寄居。在那里，他却成了又大又强、人数众多的国。","notes":[]},{"n":6,"t":"埃及人恶待我们，迫害我们，将苦工加在我们身上。","notes":[]},{"n":7,"t":"于是我们哀求耶和华我们列祖的神。耶和华听见我们的声音，看见我们所受的困苦、劳役和欺压，","notes":[]},{"n":8,"t":"耶和华就用大能的手和伸出来的膀臂，以及大而可畏的事和神迹奇事，领我们出了埃及，","notes":[]},{"n":9,"t":"将我们领进这地方，把这流奶与蜜之地赐给我们。","notes":[]},{"n":10,"t":"耶和华啊，看哪，现在我把你所赐我地上初熟的土产供上。’随后你要把筐子供在耶和华－你神面前，向耶和华－你的神下拜。","notes":[]},{"n":11,"t":"你和利未人，以及在你中间寄居的，要因耶和华－你神所赐你和你家的一切福分欢乐。","notes":[]},{"n":12,"t":"“每逢第三年，就是捐十分之一的那年，你从你一切土产中取了十分之一，要分给利未人、寄居的、孤儿和寡妇，使他们在你的城镇中可以吃得饱足。","notes":[]},{"n":13,"t":"你又要在耶和华－你神面前说：‘我已将圣物从家里拿出来，给了利未人、寄居的、孤儿和寡妇，是遵照你吩咐我的一切命令。你的命令，我没有违背，也没有忘记。","notes":[]},{"n":14,"t":"我守丧的时候，没有吃这圣物，不洁净的时候，也没有拿出来，又没有把它献给死人。我听从了耶和华－我神的话，都照你一切所吩咐的做了。","notes":[]},{"n":15,"t":"求你从天上，从你的圣所垂看，赐福给你的百姓以色列和你向我们列祖起誓所赐给我们的这片土地，就是流奶与蜜之地。’”","notes":[]},{"n":16,"t":"“耶和华－你的神今日吩咐你遵行这些律例典章，所以你要尽心尽性谨守遵行。","notes":[],"heads":["作神圣的子民"]},{"n":17,"t":"你今日宣认耶和华为你的神，承诺遵行他的道，谨守他的律例、诫命、典章，听从他的话。","notes":[]},{"n":18,"t":"耶和华今日照他所应许你的，也认你为他宝贵的子民，叫你谨守他的一切诫命，","notes":[]},{"n":19,"t":"要使你得称赞、美名、尊荣，超乎他所造的万国之上，并且照他所应许的，使你归耶和华－你的神为神圣的子民。”","notes":[]}]},"27":{"heading":"写在石头上的律法和石坛","verses":[{"n":1,"t":"摩西和以色列的众长老吩咐百姓说：“你们要遵守我今日所吩咐的一切诫命。","notes":[]},{"n":2,"t":"你们过了约旦河，到耶和华－你神所赐给你的地，当日要竖立几块大石头，涂上石灰。","notes":[]},{"n":3,"t":"当你过了河，进入耶和华－你神所赐给你流奶与蜜之地，正如耶和华－你列祖的神所应许你的，你要把这律法的一切话写在石头上。","notes":[]},{"n":4,"t":"你们过了约旦河，就要在基利心山上照我今日所吩咐的，把这些石头竖立起来，涂上石灰。","notes":["“基利心山”是根据撒玛利亚五经和一些古译本；原文是“以巴路山”。"]},{"n":5,"t":"你在那里要为耶和华－你的神筑一座石坛，却不可动用铁器在石头上。","notes":[]},{"n":6,"t":"要用没有凿过的石头筑耶和华－你神的坛，在坛上将燔祭献给耶和华－你的神，","notes":[]},{"n":7,"t":"又要献平安祭，在那里吃，在耶和华－你的神面前欢乐。","notes":[]},{"n":8,"t":"你要将这律法的一切话清楚地写在石头上。”","notes":[]},{"n":9,"t":"摩西和利未家的祭司吩咐以色列众人说：“以色列啊，你要静默倾听！你今日已成为耶和华－你神的子民了。","notes":[]},{"n":10,"t":"你要听从耶和华－你神的话，遵行他的诫命律例，就是我今日所吩咐你的。”","notes":[]},{"n":11,"t":"当日，摩西吩咐百姓说：","notes":[],"heads":["违命必受诅咒"]},{"n":12,"t":"“你们过了约旦河，西缅、利未、犹大、以萨迦、约瑟和便雅悯等支派的人要站在基利心山上为百姓祝福。","notes":[]},{"n":13,"t":"吕便、迦得、亚设、西布伦、但和拿弗他利等支派的人要站在以巴路山上宣布诅咒。","notes":[]},{"n":14,"t":"利未人要大声对以色列众人说：","notes":[]},{"n":15,"t":"“‘凡制造耶和华所憎恶的偶像，无论是雕刻的，是铸造的，就是工匠用手造的，或暗中设置的，这人必受诅咒！’众百姓要回应说：‘阿们！’","notes":[]},{"n":16,"t":"“‘轻慢父母的，必受诅咒！’众百姓要说：‘阿们！’","notes":[]},{"n":17,"t":"“‘挪移邻舍地界的，必受诅咒！’众百姓要说：‘阿们！’","notes":[]},{"n":18,"t":"“‘引领瞎子走错路的，必受诅咒！’众百姓要说：‘阿们！’","notes":[]},{"n":19,"t":"“‘对寄居的、孤儿和寡妇屈枉正直的，必受诅咒！’众百姓要说：‘阿们！’","notes":[]},{"n":20,"t":"“‘与继母同寝的，必受诅咒！因为他掀开父亲衣服的下边。’众百姓要说：‘阿们！’","notes":[]},{"n":21,"t":"“‘与兽交合的，必受诅咒！’众百姓要说：‘阿们！’","notes":[]},{"n":22,"t":"“‘与同父异母，或同母异父的姊妹同寝的，必受诅咒！’众百姓要说：‘阿们！’","notes":[]},{"n":23,"t":"“‘与岳母同寝的，必受诅咒！’众百姓要说：‘阿们！’","notes":[]},{"n":24,"t":"“‘暗中击杀邻舍的，必受诅咒！’众百姓要说：‘阿们！’","notes":[]},{"n":25,"t":"“‘受贿赂击杀人而流无辜之血的，必受诅咒！’众百姓要说：‘阿们！’","notes":[]},{"n":26,"t":"“‘不坚守遵行这律法之话的，必受诅咒！’众百姓要说：‘阿们！’”","notes":[]}]},"28":{"heading":"遵行诫命蒙福","verses":[{"n":1,"t":"“你若留心听从耶和华－你神的话，谨守遵行他的一切诫命，就是我今日所吩咐你的，他必使你超乎地上的万国之上。","notes":[]},{"n":2,"t":"你若听从耶和华－你神的话，这一切的福气必临到你身上，追随你：","notes":[]},{"n":3,"t":"你在城里必蒙福，在田间也必蒙福。","notes":[]},{"n":4,"t":"你身所生的，你地所产的，你牲畜所生的，牛犊、羔羊，都必蒙福。","notes":[]},{"n":5,"t":"你的筐子和你的揉面盆都必蒙福。","notes":[]},{"n":6,"t":"你出也蒙福，入也蒙福。","notes":[]},{"n":7,"t":"“耶和华必使那起来攻击你的仇敌在你面前溃败。他们从一条路来攻击你，必在你面前从七条路逃跑。","notes":[]},{"n":8,"t":"在你仓房里，以及你手所做的一切，耶和华必发令赐福给你。耶和华－你神也必在所赐你的地上赐福给你。","notes":[]},{"n":9,"t":"你若谨守耶和华－你神的诫命，遵行他的道，他必照他向你所起的誓立你为自己神圣的子民。","notes":[]},{"n":10,"t":"地上的万民见你归在耶和华的名下，就必惧怕你。","notes":[]},{"n":11,"t":"在耶和华向你列祖起誓应许赐你的土地上，他必使你身所生的，牲畜所生的，地所产的，都丰富有余。","notes":[]},{"n":12,"t":"耶和华必为你敞开天上的宝库，按时降雨在你的地上。他必赐福你手里所做的一切。你必借给许多国家，却不必去借贷。","notes":[]},{"n":13,"t":"你若听从耶和华－你神的诫命，就是我今日所吩咐你的，谨守遵行，耶和华就必使你作首不作尾，居上不居下，","notes":[]},{"n":14,"t":"只要你不偏左右，不背离我今日所吩咐你的一切话，也不随从别神，事奉它们。”","notes":[]},{"n":15,"t":"“你若不听从耶和华－你神的话，不谨守遵行他的一切诫命律例，就是我今日所吩咐你的，这一切的诅咒必临到你身上，追随你：","notes":[],"heads":["违反诫命遭祸"]},{"n":16,"t":"你在城里必受诅咒，在田间也必受诅咒。","notes":[]},{"n":17,"t":"你的筐子和你的揉面盆都必受诅咒。","notes":[]},{"n":18,"t":"你身所生的，你地所产的，以及牛犊、羔羊，都必受诅咒。","notes":[]},{"n":19,"t":"你出也受诅咒，入也受诅咒。","notes":[]},{"n":20,"t":"耶和华因你作恶离弃他，必在你手里所做的一切，使诅咒、困扰、责罚临到你，直到你被除灭，直到你迅速灭亡。","notes":[]},{"n":21,"t":"耶和华必使瘟疫紧贴着你，直到他把你从所进去得为业的地上灭绝。","notes":[]},{"n":22,"t":"耶和华要用痨病、热病、发炎、高烧、刀剑、焚风和霉烂攻击你；这些要追赶你，直到你灭亡。","notes":["“刀剑”：原文另译“干旱”。","“焚风”或译“虫害”。"]},{"n":23,"t":"你头上的天要变成铜，下面的地要化为铁。","notes":[]},{"n":24,"t":"耶和华要使那降在你地上的雨变为灰尘，尘土从天落在你身上，直到你被除灭。","notes":[]},{"n":25,"t":"“耶和华必使你在仇敌面前溃败。你从一条路去攻击他们，必从七条路逃跑。地上万国必因你而惊骇。","notes":[]},{"n":26,"t":"你的尸首必给空中的飞鸟和地上的走兽作食物，却无人哄赶。","notes":[]},{"n":27,"t":"耶和华必用埃及人的疮、溃疡、癣和疥攻击你，使你不得医治。","notes":[]},{"n":28,"t":"耶和华必用癫狂、眼瞎、心惊攻击你。","notes":[]},{"n":29,"t":"你必在午间摸索，好像盲人在黑暗中摸索。你的道路必不亨通，天天受人欺压、抢夺，无人搭救。","notes":[]},{"n":30,"t":"你聘了妻子，别人必与她同寝；你建了房屋，却不得住在其内；你栽植了葡萄园，却不得享用所结的果子。","notes":[]},{"n":31,"t":"你的牛在你眼前宰了，你吃不到它的肉；你的驴在你眼前被人抢夺，却讨不回来；你的羊被敌人拿走，无人帮助你。","notes":[]},{"n":32,"t":"你的儿女被交给别国的民；你的眼目终日切望，甚至失明，你的手却无能为力。","notes":[]},{"n":33,"t":"你地所产的和你劳力所得的，必被你所不认识的百姓吃尽。你天天只被欺负，受压制，","notes":[]},{"n":34,"t":"甚至你因眼中所见的景象而疯狂。","notes":[]},{"n":35,"t":"耶和华必攻击你，使你膝上腿上，从脚掌到头顶，都长满了毒疮，无法医治。","notes":[]},{"n":36,"t":"“耶和华必将你和你所立统治你的王，领到你和你列祖不认识的国去；在那里你必事奉别神，就是木头和石头。","notes":[]},{"n":37,"t":"你在耶和华赶你到的万民中，要令人惊骇，成为笑柄，被人讥诮。","notes":[]},{"n":38,"t":"你撒在田里的种子虽多，收的却少，因为蝗虫把它吃光了。","notes":[]},{"n":39,"t":"你栽植修整葡萄园，却没有酒喝，也不得储存，因为虫子把它吃了。","notes":[]},{"n":40,"t":"你全境有橄榄树，却得不到油抹身，因为你的橄榄都掉光了。","notes":[]},{"n":41,"t":"你生儿育女，却不属于你，因为他们必被掳去。","notes":[]},{"n":42,"t":"你所有的树木和你地里的出产必被蝗虫吃尽了。","notes":[]},{"n":43,"t":"在你中间寄居的必上升高过你，高而又高；你必下降，低而又低。","notes":[]},{"n":44,"t":"他必借给你，你却不能借给他；他必作首，你必作尾。","notes":[]},{"n":45,"t":"这一切的诅咒必临到你，追赶你，赶上你，直到把你除灭，因为你不听从耶和华－你神的话，不遵守他吩咐的诫命律例。","notes":[]},{"n":46,"t":"这些诅咒必在你和你后裔身上成为神迹奇事，直到永远！","notes":[]},{"n":47,"t":"因为你富裕的时候，不以欢喜快乐的心事奉耶和华－你的神，","notes":[]},{"n":48,"t":"所以你必在饥饿、干渴、赤身、缺乏中事奉仇敌，那是耶和华派来攻击你的。他必把铁轭加在你的颈项上，直到把你除灭。","notes":[]},{"n":49,"t":"耶和华要从远方、地极之处带一国来，如鹰飞来攻击你；这国的语言，你听不懂。","notes":[]},{"n":50,"t":"这国的人面貌凶恶，不给长者面子，也不恩待年轻人。","notes":[]},{"n":51,"t":"他们必吃你牲畜所生的和你土地所产的，直到你被除灭。你的五谷、新酒和新的油，以及牛犊、羔羊，他都不给你留下，直到使你灭亡。","notes":[]},{"n":52,"t":"他们必在你的各城围困你，直到你在全地所倚靠、高大坚固的城墙都倒塌。他们必在耶和华－你神所赐给你全地的各城围困你。","notes":[]},{"n":53,"t":"你在仇敌围困的窘迫中，必吃你本身所生的，就是耶和华－你神所赐给你的儿女之肉。","notes":[]},{"n":54,"t":"你中间，连那温和文雅的人都必冷眼恶待自己的兄弟和怀中的妻子，以及他所剩下其余的儿女，","notes":[]},{"n":55,"t":"不把所吃儿女的肉分一点给他们任何一个人，因为在被仇敌围困、陷入窘迫的各城中，他已经一无所剩了。","notes":[]},{"n":56,"t":"你中间柔顺娇嫩的妇人，甚至因柔顺娇嫩脚不肯踏地的妇人，也必冷眼恶待她怀中的丈夫和自己的儿女。","notes":[]},{"n":57,"t":"在被仇敌围困、陷入窘迫的城镇中，她因缺乏一切，就要暗中把从她两腿中间出来的胞衣和所生下的儿女吃了。","notes":[]},{"n":58,"t":"“这书上所写律法的一切话，是叫你敬畏耶和华－你神尊荣可畏的名，你若不谨守遵行，","notes":[]},{"n":59,"t":"耶和华就必将奇异的灾害，就是严重持久的灾害和长期难治的疾病，加在你和你后裔的身上。","notes":[]},{"n":60,"t":"他必使你所畏惧、埃及一切的疾病临到你，紧贴着你，","notes":[]},{"n":61,"t":"没有写在这律法书上的各样疾病、灾害，耶和华也必降在你身上，直到你被除灭。","notes":[]},{"n":62,"t":"你们虽然曾像天上的星那样多，却因不听从耶和华－你神的话，所剩的人丁就稀少了。","notes":[]},{"n":63,"t":"耶和华先前怎样喜爱善待你们，使你们增多，耶和华也要照样喜爱消灭你们，使你们灭绝。你们必从所要进去得为业的地上被拔除。","notes":[]},{"n":64,"t":"耶和华必把你们分散在万民中，从地的这边到地的另一边，在那里你必事奉你和你列祖不认识的神明，就是木头和石头。","notes":[]},{"n":65,"t":"在那些国中，你必得不到安宁，脚掌也没有安歇之处；耶和华却要使你在那里心中发颤，眼目失明，精神沮丧。","notes":[]},{"n":66,"t":"你的一生悬空不安；你昼夜恐惧，生命没有保障。","notes":[]},{"n":67,"t":"你因心中的恐惧，眼睛所见的景象，早晨必说：‘但愿现在是晚上！’晚上必说：‘但愿现在是早晨！’","notes":[]},{"n":68,"t":"耶和华要用船把你送回埃及去，走那我曾告诉你不再看见的路；在那里你们必卖身给你的仇敌作奴婢，却没有人要买。”","notes":[]}]},"29":{"heading":"在摩押重新立约","verses":[{"n":1,"t":"耶和华在何烈山与以色列人立约以外，这是耶和华在摩押地吩咐摩西与以色列人立约的话。","notes":[]},{"n":2,"t":"摩西召全以色列来，对他们说：“耶和华在埃及地，在你们眼前向法老和他众臣仆，以及他的全地所做的一切事，你们都看见了，","notes":[]},{"n":3,"t":"就是你亲眼看见的大考验，那些神迹和大奇事。","notes":[]},{"n":4,"t":"但耶和华到今日还没有使你们心能明白，眼能看见，耳能听见。","notes":[]},{"n":5,"t":"我领你们在旷野四十年，你们身上的衣服没有穿破，脚上的鞋也没有穿坏；","notes":[]},{"n":6,"t":"你们没有吃饼，也没有喝清酒烈酒，好让你们知道‘我─耶和华是你们的神’。","notes":[]},{"n":7,"t":"你们来到这地方，希实本王西宏和巴珊王噩出来迎击我们，与我们交战，我们击败了他们，","notes":[]},{"n":8,"t":"取了他们的地，给吕便支派、迦得支派和玛拿西半支派为业。","notes":[]},{"n":9,"t":"所以你们要谨守这约的话，遵行它们，好使你们在一切所做的事上亨通。","notes":[]},{"n":10,"t":"“今日你们全都要站在耶和华－你们的神面前，就是各领袖、族长、长老、官长、以色列所有的男子、","notes":["“族长”：原文是“支派”。"]},{"n":11,"t":"你们的妻子儿女、你营中寄居的，从为你砍柴到为你挑水的人，","notes":[]},{"n":12,"t":"为要使你进入耶和华－你神的约，就是耶和华－你神今日向你起誓所立的；","notes":[]},{"n":13,"t":"这样，他今日要立你作他的子民，他作你的神，是照他向你所应许的，又照他向你列祖亚伯拉罕、以撒、雅各所起的誓。","notes":[]},{"n":14,"t":"我不单单与你们立这约，起这誓，","notes":[]},{"n":15,"t":"就是今日与我们一同站在耶和华－我们神面前的，而且也包括今日不在我们这里的人。","notes":[]},{"n":16,"t":"“你们知道，我们曾住过埃及地，也经过列国，从他们中间穿越。","notes":[]},{"n":17,"t":"你们也见过他们的可憎之物，他们木、石、金、银的偶像。","notes":[]},{"n":18,"t":"惟恐你们中间有人，或男或女，或宗族或支派，今日心里偏离耶和华－我们的神，去事奉那些国的神明，又怕你们中间有根长出苦菜和茵陈来。","notes":[]},{"n":19,"t":"这样的人听见这诅咒的话，心里还庆幸，说：‘我虽然随着顽固的心行事，却还是平安无事。’以致有水的和无水的都消灭了。","notes":[]},{"n":20,"t":"耶和华必不愿饶恕他；耶和华的怒气与妒忌必向他如烟冒出，将这书上所写的一切诅咒都加在他身上，耶和华也要从天下涂去他的名。","notes":[]},{"n":21,"t":"耶和华又必照着写在律法书上，约中的一切诅咒，将他从以色列众支派中分别出来，使他遭受祸害。","notes":[]},{"n":22,"t":"你们的后代，就是接续你们兴起的子孙，和远方来的外邦人，看见这地的灾祸，以及耶和华所降于这地的疾病，","notes":[]},{"n":23,"t":"遍地都被硫磺和盐所侵蚀，不能耕种，没有出产，连草都长不出来，好像耶和华在怒气和愤怒中所倾覆的所多玛、蛾摩拉、押玛、洗扁一样，","notes":[]},{"n":24,"t":"万国必说：‘耶和华为什么向此地这样做呢？为什么要大发烈怒呢？’","notes":[]},{"n":25,"t":"人必说：‘这是因为这地的人离弃了耶和华─他们列祖的神领他们出埃及地的时候与他们所立的约，","notes":[]},{"n":26,"t":"去事奉别神，敬拜他们所不认识的神明，这是耶和华未曾允许的。","notes":[]},{"n":27,"t":"所以耶和华的怒气向这地发作，将这书上所写的一切诅咒都降在这地上。","notes":[]},{"n":28,"t":"耶和华在怒气、愤怒、大恼恨中将他们从本地拔出来，扔到别的地上，像今日一样。’","notes":[]},{"n":29,"t":"“隐秘的事是属耶和华─我们神的，但明显的事是永远属我们和我们子孙的，为要叫我们遵行这律法上的一切话。”","notes":[]}]},"30":{"heading":"回转和蒙福","verses":[{"n":1,"t":"“当这一切的事，就是我摆在你面前的祝福和诅咒临到你的时候，你在耶和华－你神赶逐你去的万国中，心里回想这些事，","notes":[]},{"n":2,"t":"你和你的子孙若尽心尽性归向耶和华－你的神，照我今日一切所吩咐你的，听从他的话，","notes":[]},{"n":3,"t":"耶和华－你的神就必怜悯你，使你这被掳的子民归回。耶和华－你的神必转回，从分散你到的万民中把你召集回来。","notes":[]},{"n":4,"t":"你就是被赶逐到天涯，耶和华－你的神也必从那里召集你，从那里领你回来。","notes":[]},{"n":5,"t":"耶和华－你的神必领你进入你列祖所得的地，你必得着这地为业。他必善待你，使你增多，胜过你的列祖。","notes":[]},{"n":6,"t":"耶和华－你的神要使你的心和你后裔的心受割礼，好叫你尽心尽性爱耶和华－你的神，使你可以存活。","notes":[]},{"n":7,"t":"耶和华－你的神必将这一切诅咒加在你仇敌和恨恶你、迫害你的人身上。","notes":[]},{"n":8,"t":"你必回转，听从耶和华的话，遵行他的一切诫命，就是我今日所吩咐你的。","notes":[]},{"n":9,"t":"耶和华－你的神必使你手里所做的一切，以及你身所生的，牲畜所生的，土地所产的都丰富有余，而且顺利；耶和华必再喜爱善待你，正如他喜爱你的列祖一样，","notes":[]},{"n":10,"t":"只要你听从耶和华－你神的话，谨守这律法书上所写的诫命律例，尽心尽性归向耶和华－你的神。”","notes":[]},{"n":11,"t":"“我今日所吩咐你的诫命，对你并不困难，也不太远；","notes":[],"heads":["生命之道"]},{"n":12,"t":"不是在天上，使你说：‘谁为我们上天去取来给我们，使我们听了可以遵行呢？’","notes":[]},{"n":13,"t":"也不是在海的那边，使你说：‘谁为我们渡海到另一边，去取来给我们，使我们听了可以遵行呢？’","notes":[]},{"n":14,"t":"因这话离你很近，就在你口中，在你心里，使你可以遵行。","notes":[]},{"n":15,"t":"“看，我今日将生死祸福摆在你面前。","notes":[]},{"n":16,"t":"我今日所吩咐你的，就是要爱耶和华－你的神，遵行他的道，谨守他的诫命、律例、典章，使你可以存活，增多，而且耶和华－你的神必在你所要进去得为业的地上赐福给你。","notes":["“我今日所吩咐你的”：七十士译本是“如果你遵行主－你神的诫命，就是我今日所吩咐你的”。"]},{"n":17,"t":"倘若你的心偏离，不肯听从，却被引诱去敬拜别神，事奉它们，","notes":[]},{"n":18,"t":"我今日向你们申明，你们必定灭亡；在你过约旦河进去得为业的地上，你的日子必不长久。","notes":[]},{"n":19,"t":"我今日呼天唤地向你作见证：我已经将生与死，祝福与诅咒，摆在你面前。所以你要拣选生命，好使你和你的后裔都得存活。","notes":[]},{"n":20,"t":"要爱耶和华－你的神，听从他的话，紧紧跟随他，因为他是你的生命，必使你的日子得以长久，可以在耶和华向你列祖亚伯拉罕、以撒、雅各起誓要给他们的地上居住。”","notes":[]}]},"31":{"heading":"约书亚继承摩西","verses":[{"n":1,"t":"摩西去把这些话吩咐以色列众人，","notes":["“去...众人”：死海古卷和七十士译本是“对以色列众人说完了这一切话”。"]},{"n":2,"t":"对他们说：“我已经一百二十岁了，现在不能照常出入。耶和华曾对我说：‘你不得过这约旦河。’","notes":[]},{"n":3,"t":"耶和华－你的神必在你面前过河，把这些国从你面前除灭，你就必得他们的地。约书亚要在你面前过河，是照耶和华所吩咐的。","notes":[]},{"n":4,"t":"耶和华必对待他们，如同从前待他所除灭的亚摩利人的王西宏与噩，以及他们的国一样。","notes":[]},{"n":5,"t":"耶和华必将他们交在你们面前，你们要照我所吩咐的一切命令待他们。","notes":[]},{"n":6,"t":"你们当刚强壮胆，不要害怕，也不要畏惧他们，因为耶和华－你的神必与你同去；他必不撇下你，也不丢弃你。”","notes":[]},{"n":7,"t":"摩西召了约书亚来，在以色列众人眼前对他说：“你当刚强壮胆！因为你要和这百姓一同进入耶和华向他们列祖起誓要给他们的地，你也要使他们承受那地为业。","notes":["“和这百姓一同进入”：撒玛利亚五经和一些古卷是“领这百姓进入”。"]},{"n":8,"t":"耶和华必在你前面行，他必亲自与你同在，必不撇下你，也不丢弃你。你不要惧怕，也不要惊惶。”","notes":[]},{"n":9,"t":"摩西写下这律法，交给抬耶和华约柜的利未人祭司和以色列的众长老。","notes":[],"heads":["每七年要诵读律法一次"]},{"n":10,"t":"摩西吩咐他们说：“每逢七年的最后一年，就是定期的豁免年，在住棚节的时候，","notes":[]},{"n":11,"t":"当以色列众人来到耶和华－你神所选择的地方朝见他的时候，你要在以色列众人面前念这律法给他们听。","notes":[]},{"n":12,"t":"要召集百姓，男人、女人、孩子，和在你城里寄居的，叫他们都得以听见，好学习敬畏耶和华－你们的神，谨守遵行这律法的一切话。","notes":[]},{"n":13,"t":"他们的儿女，就是那未曾认识的，也可以听，学习敬畏耶和华－你们的神；你们一生的日子，在你们过约旦河得为业的地上，都要这样做。”","notes":[]},{"n":14,"t":"耶和华对摩西说：“看哪，你的死期已近了。要召约书亚来，和你一起站在会幕里，我好吩咐他。”于是摩西和约书亚去站在会幕里。","notes":[],"heads":["对摩西最后的指示"]},{"n":15,"t":"耶和华在会幕里，在云柱中显现，云柱停在会幕门口的上面。","notes":[]},{"n":16,"t":"耶和华对摩西说：“看哪，你必和你的祖先同睡。这百姓要起来，在他们所要去的地上，在那地的人中，随从外邦的神明行淫，离弃我，违背我与他们所立的约。","notes":[]},{"n":17,"t":"那时，我的怒气必向他们发作，我必离弃他们，转脸不顾他们，以致他们被吞灭，并有许多的祸患灾难临到他们。在那日，人必说：‘这些祸患临到我，岂不是因为我的神不在我中间吗？’","notes":[]},{"n":18,"t":"在那日，因人偏向别神所行的一切恶事，我必定转脸不顾。","notes":[]},{"n":19,"t":"现在你们要写下这首歌，教导以色列人，放在他们口中，使这首歌成为我指责以色列人的见证。","notes":[]},{"n":20,"t":"因为我将他们领进我向他们列祖起誓应许那流奶与蜜之地，他们在那里吃得饱足，长得肥胖，就偏向别神，事奉它们，藐视我，背弃我的约。","notes":[]},{"n":21,"t":"当许多祸患灾难临到他们的时候，这首歌必在他们面前作见证，因为他们后裔的口必吟诵不忘。我未领他们到我所起誓应许之地以先，他们所怀的意念我都知道了。”","notes":[]},{"n":22,"t":"当日摩西就写了一首歌，教导以色列人。","notes":[]},{"n":23,"t":"耶和华吩咐嫩的儿子约书亚说：“你当刚强壮胆，因为你必领以色列人进入我所起誓应许他们的地，我必与你同在。”","notes":[]},{"n":24,"t":"当摩西把这律法的话写完在书上，到完成的时候，","notes":[]},{"n":25,"t":"摩西吩咐抬耶和华约柜的利未人说：","notes":[]},{"n":26,"t":"“把这律法书拿来，放在耶和华－你们神的约柜旁，可以在那里作指责你们的见证。","notes":[]},{"n":27,"t":"因为我知道你们是悖逆的，是硬着颈项的。看哪，我今日还活着与你们同在，你们尚且悖逆耶和华，何况我死后呢？","notes":[]},{"n":28,"t":"你们要召集你们支派的众长老和官长到我这里来，我好把这些话说给他们听，并且呼唤天地见证他们的不是。","notes":[]},{"n":29,"t":"我知道我死后你们必全然败坏，偏离我所吩咐你们的道。日后必有祸患临到你们，因为你们做了耶和华眼中看为恶的事，以你们手中所做的惹他发怒。”","notes":[]},{"n":30,"t":"摩西把这首歌的话，从头到尾吟诵给以色列全会众听。","notes":[],"heads":["摩西之歌"]}]},"32":{"heading":"预告摩西的死","verses":[{"n":1,"t":"“诸天哪，要侧耳听我说话；愿地聆听我口中的言语。","notes":[]},{"n":2,"t":"我的教导要淋漓如雨，我的言语要滴落如露，如细雨降在嫩草上，如甘霖降在蔬菜中。","notes":[]},{"n":3,"t":"因为我要宣扬耶和华的名，你们要把伟大归给我们的神。","notes":[]},{"n":4,"t":"“他是磐石，他的作为完全，他一切所行的都公平；他是信实无伪的神，又公义，又正直。","notes":[]},{"n":5,"t":"这乖僻弯曲的世代向他行了败坏的事；因着他们的弊病，不再是他的儿女。","notes":[]},{"n":6,"t":"愚昧无知的百姓啊，你们这样报答耶和华吗？他岂不是你的父，创造了你吗？他造了你，坚立你。","notes":[]},{"n":7,"t":"你当回想上古之日，思念历代之年；问你的父亲，他必告诉你；问你的长者，他必向你述说。","notes":[]},{"n":8,"t":"至高者将地业赐给列国，将世人分开，他按照神明的数目，为万民划定疆界。","notes":["“神明”是根据死海古卷，直译“神的众子”；原文是“以色列人”；七十士译本是“天使”。"]},{"n":9,"t":"因为耶和华的份是他的百姓，他的产业就是雅各。","notes":[]},{"n":10,"t":"“耶和华在旷野之地，在空旷，野兽吼叫之荒地遇见他，就环绕他，看顾他，保护他，如同保护眼中的瞳人。","notes":[]},{"n":11,"t":"鹰怎样搅动巢窝，在雏鹰上面飞翔，展开双翅接住雏鹰，背在两翼之上，","notes":[]},{"n":12,"t":"耶和华也照样独自引导他，并无外邦神明与他同在。","notes":[]},{"n":13,"t":"耶和华使他驰骋在地的高处，他吃田间的出产；耶和华使他从岩石中吃蜜，从坚石中吸油，","notes":[]},{"n":14,"t":"也吃牛的乳酪、羊的奶、羔羊的脂肪，巴珊所出的公绵羊和山羊，和上好的麦子。你要喝葡萄汁酿的美酒。","notes":[]},{"n":15,"t":"“耶书仑渐渐肥胖，能踼跳。你长得肥胖，粗壮，丰润。他离弃造他的神，轻看救他的磐石。","notes":["死海古卷、撒玛利亚五经、其他古卷和七十士译本在此加：“雅各吃了而且饱足”。"]},{"n":16,"t":"他们用外邦神明惹神妒忌，以可憎之物惹他发怒。","notes":[]},{"n":17,"t":"他们祭祀鬼魔，而非神，是他们不认识的神明，是近来新兴的，是你们列祖所不畏惧的。","notes":[]},{"n":18,"t":"你轻忽生你的磐石，忘记生产你的神。","notes":[]},{"n":19,"t":"“耶和华看见了，因他儿女惹动他就抛弃他们，","notes":[]},{"n":20,"t":"说：‘我要转脸离开他们，看他们的结局如何。他们是极乖谬的世代，是不忠实的儿女。","notes":[]},{"n":21,"t":"他们以那不是神的激起我妒忌，以虚无的神明惹我发怒。我要以不成国的激起你们嫉妒，我要以愚顽的国惹起你们发怒。","notes":["“虚无的神明”：原文是“虚无”。"]},{"n":22,"t":"因为我的怒火焚烧，直烧到极深的阴间，吞噬地和地的出产，连山的根基也烧着了。","notes":[]},{"n":23,"t":"“‘我要把祸患堆在他们身上，我用尽我的箭射向他们：","notes":[]},{"n":24,"t":"饿死人的饥荒、灼人的热症、痛苦的灾害。我要叫野兽用牙齿咬他们，叫土中爬行的用毒液害他们。","notes":[]},{"n":25,"t":"外有刀剑使人丧亡，内有惊恐，少男少女是如此，吃奶的、白发的也是如此。","notes":[]},{"n":26,"t":"我曾说，我要粉碎他们，使他们的名从人间消失。","notes":["“名”：原文是“纪念”。"]},{"n":27,"t":"惟恐仇敌挑衅，他们的敌人误解，说，我们的手得胜了，这一切并非耶和华做的。’","notes":[]},{"n":28,"t":"“因为他们是缺乏智谋的国家，他们里面毫无聪明。","notes":[]},{"n":29,"t":"惟愿他们有智慧，能明白这事，他们就会想到自己的结局。","notes":[]},{"n":30,"t":"若非他们的磐石卖了他们，若非耶和华交出他们，一人岂能追赶千人，二人焉能使万人逃跑呢？","notes":[]},{"n":31,"t":"甚至我们的仇敌都承认，他们的磐石不如我们的磐石。","notes":[]},{"n":32,"t":"他们的葡萄树是所多玛的葡萄树，是蛾摩拉田园所长的；他们的葡萄是毒葡萄，整串都是苦的。","notes":[]},{"n":33,"t":"他们的酒是大蛇的毒液，是毒蛇剧烈的毒汁。","notes":[]},{"n":34,"t":"“这岂不都存放在我这里，封存在我库房中吗？","notes":[]},{"n":35,"t":"伸冤报应在我，到了时候他们会失脚。因为他们遭难的日子近了，他们的厄运快要临到。","notes":["“伸冤报应在我”：撒玛利亚五经和七十士译本是“伸冤的日子我必报应”。"]},{"n":36,"t":"耶和华见他的百姓毫无能力，无论是为奴的、自由的，都没有存留，就必为他们伸冤，为自己的仆人发怜悯。","notes":[]},{"n":37,"t":"他必说：‘他们的神明，他们所投靠的磐石，在哪里呢？","notes":[]},{"n":38,"t":"吃了他们祭牲脂肪的，喝了他们浇酒祭之酒的，叫那些神明站出来帮助你们，作为你们的保障吧！","notes":[]},{"n":39,"t":"“‘如今，看！我，惟有我是神；我以外并无别神。我使人死，我使人活；我击伤人，也医治人，没有人能从我手中救出来。","notes":["“神”：原文直译“他”。"]},{"n":40,"t":"我向天举手，我凭我的永生起誓说：","notes":[]},{"n":41,"t":"我若磨我闪亮的刀，我的手掌握审判权，就必报复我的敌人，报应那些恨我的人。","notes":[]},{"n":42,"t":"我要使我的箭饮血而醉，就是被杀被掳之人的血；我的刀也要吃肉，就是仇敌披发头颅的肉。’","notes":["“头颅”或译“领袖”。"]},{"n":43,"t":"“列国啊，当与耶和华的子民一同欢呼；因为他要为他仆人所流的血伸冤，报应他的敌人，救赎他的土地和他的子民 。”","notes":["“列国...欢呼”：死海古卷是“诸天啊，当与他一同欢乐；神的众子都要拜他”；七十士译本是“诸天啊，当与他一同欢乐；神的众子都要拜他；外邦人哪，你们要与他的子民一同欢乐；神的众天使都加添力量给他”。","“他仆人”：死海古卷和七十士译本是“他儿女”。","“报应他的敌人”：死海古卷和七十士译本是“报应他的敌人，报应那些恨他的人”。","“他的土地和他的子民”：死海古卷、撒玛利亚五经和七十士译本是“他百姓的土地”。"]},{"n":44,"t":"摩西和嫩的儿子约书亚前来把这首歌的一切话吟诵给百姓听。","notes":["“约书亚”是根据撒玛利亚五经、七十士译本和其他古译本；原文是“何西阿”。"]},{"n":45,"t":"摩西向以色列众人吟诵完了这一切话，","notes":[]},{"n":46,"t":"对他们说：“我今日以这一切话警戒你们，你们都要记在心中，要吩咐你们的子孙谨守遵行这律法上一切的话。","notes":[]},{"n":47,"t":"因为这不是与你们无关的空话，而是你们的生命；因遵行这话，你们的日子必在你们过约旦河得为业的地上得以长久。”","notes":[]},{"n":48,"t":"就在那日，耶和华吩咐摩西说：","notes":[]},{"n":49,"t":"“你上摩押地的亚巴琳山脉，到面对耶利哥的尼波山去，看我所要赐给以色列人为业的迦南地。","notes":[]},{"n":50,"t":"你必死在你所登的山上，归到你祖先那里，像你哥哥亚伦死在何珥山上，归到他祖先那里一样。","notes":["“你祖先”：原文是“你百姓”。","“他祖先”：原文是“他百姓”。"]},{"n":51,"t":"因为你们在以色列人中得罪了我，在寻的旷野，加低斯的米利巴水那里，在以色列人中没有尊我为圣。","notes":[]},{"n":52,"t":"我所赐给以色列人的地，你只可从对面观看，却不得进到那里去。”","notes":[]}]},"33":{"heading":"摩西祝福以色列众支派","verses":[{"n":1,"t":"这是神人摩西未死以前为以色列人的祝福。","notes":[]},{"n":2,"t":"他说：“耶和华从西奈来，从西珥向他们显现，从巴兰山发出光辉；从万万圣者中来临，从他右手向他们发出烈火的律法。","notes":["“从万万圣者中来临”：撒玛利亚五经、七十士译本和其他古译本是“有万万圣者在一起”。","“从...律法”或译“从他右手有烈火照耀他们”。"]},{"n":3,"t":"他实在疼爱万民。他的众圣徒都在你手中，他们坐在你的脚下，领受你的言语。”","notes":[]},{"n":4,"t":"摩西将律法传给我们，作为雅各会众的产业。","notes":[]},{"n":5,"t":"“耶和华在耶书仑作王；百姓的众领袖和以色列各支派一同欢聚。","notes":["“耶和华”：原文是“他”。"]},{"n":6,"t":"愿吕便存活，不致死亡，虽然他的人丁稀少。","notes":[]},{"n":7,"t":"关于犹大，他这么说：‘耶和华啊，求你垂听犹大的声音，引导他归回他的百姓中。他曾用手为自己争战，你必帮助他攻击敌人。’","notes":[]},{"n":8,"t":"关于利未，他说：‘愿你的土明和乌陵都在你的虔诚人那里。你在玛撒曾考验他，在米利巴水与他争论。","notes":["“愿你的...那里”：死海古卷和七十士译本是“愿你的土明给利未人，你的乌陵给虔诚人”。"]},{"n":9,"t":"关于自己的父母，他说：我未曾关注。他的弟兄，他不承认，他的儿女，他也不认识，因为利未人遵行你的话，谨守你的约。","notes":[]},{"n":10,"t":"他们将你的典章教导雅各，将你的律法教导以色列。他们奉上香让你闻，把全牲的燔祭献在你坛上。","notes":[]},{"n":11,"t":"求耶和华赐福给他的财物，悦纳他手里的工作。求你刺透起来攻击他的人的腰，使那些恨恶他的人不再起来。’","notes":["“财物”或译“力量”。"]},{"n":12,"t":"关于便雅悯，他说：‘耶和华所亲爱的必同耶和华安然居住，耶和华终日庇护他，他也住在耶和华两肩之中。’","notes":["“他也住在...之中”或译“耶和华也住在他的两座山之间”。"]},{"n":13,"t":"关于约瑟，他说：‘愿他的地蒙耶和华赐福，得天上的甘露，地下的泉源；","notes":[]},{"n":14,"t":"得太阳下的美果，月光中的佳谷；","notes":[]},{"n":15,"t":"得古老山岳的至宝，永恒山岭的宝物；","notes":[]},{"n":16,"t":"得地的宝物和其中所充满的，得住在荆棘中者的喜悦。愿这些福都临到约瑟的头上，临到那与兄弟有分别之人的头顶上。","notes":[]},{"n":17,"t":"他是牛群中头生的，大有威严；他的双角是野牛的角，用以抵触万民，直到地极。这对角是以法莲的万万，这对角是玛拿西的千千。’","notes":[]},{"n":18,"t":"关于西布伦，他说：‘西布伦哪，你出外可以欢喜。以萨迦啊，你在帐棚里可以快乐。","notes":[]},{"n":19,"t":"他们要召集万民到山上，在那里献公义的祭。因为他们要吸取海里的财富，沙中隐藏的珍宝。’","notes":[]},{"n":20,"t":"关于迦得，他说：‘那使迦得扩张的，当受称颂！迦得卧如母狮，撕裂膀臂和头皮。","notes":[]},{"n":21,"t":"他为自己看中了最好的，因为那是为掌权者所存留的一份。他与百姓的领袖同来，执行耶和华的公义和耶和华为以色列所立的典章。’","notes":["“因为...同来”：原文另译“因为那是掌权者的份，他与百姓的领袖一同聚集”。"]},{"n":22,"t":"关于但，他说：‘但是小狮子，从巴珊跳出来。’","notes":[]},{"n":23,"t":"关于拿弗他利，他说：‘拿弗他利啊，你享足恩宠，满得耶和华的福，可以得西方和南方为业。’","notes":[]},{"n":24,"t":"关于亚设，他说：‘愿亚设在众子中蒙福，愿他得他弟兄的喜悦，可以把脚蘸在油中。","notes":["“愿亚设在众子中蒙福”或译“众子中最蒙福的是亚设”。"]},{"n":25,"t":"你的门闩是铁的，是铜的。只要你有多少日子，你就有多少力量。’","notes":["“只要...力量”或译“你的日子如何，你的力量也必如何”。"]},{"n":26,"t":"“耶书仑哪，没有谁能比神！他腾云，大显威荣，从天空来帮助你。","notes":[]},{"n":27,"t":"亘古的神是避难所，下面有永久的膀臂。他从你面前赶走仇敌，说：‘毁灭吧！’","notes":[]},{"n":28,"t":"因此，以色列独自安然居住，雅各的泉源在五谷新酒之地，他的天也滴下露水。","notes":[]},{"n":29,"t":"以色列啊，你有福了！蒙耶和华拯救的百姓啊，谁能像你？他是帮助你的盾牌，是你威荣的刀剑。你的仇敌要屈身就你；你却要践踏他们的背脊。”","notes":["“背脊”或译“高处”。"]}]},"34":{"heading":"摩西的死","verses":[{"n":1,"t":"摩西从摩押平原登上尼波山，到了耶利哥对面的毗斯迦山顶。耶和华把全地指给他看：从基列到但，","notes":[]},{"n":2,"t":"拿弗他利全地，以法莲、玛拿西的地，犹大全地直到西边的海，","notes":[]},{"n":3,"t":"尼革夫，从棕树城耶利哥的平原到琐珥。","notes":[]},{"n":4,"t":"耶和华对他说：“这就是我向亚伯拉罕、以撒、雅各起誓应许之地，说：‘我必将这地赐给你的后裔。’现在我使你亲眼看见了，你却不得过到那里去。”","notes":[]},{"n":5,"t":"于是耶和华的仆人摩西死在摩押地那里，正如耶和华所说的。","notes":[]},{"n":6,"t":"耶和华将他葬在摩押地，伯．毗珥对面的谷中，只是到今日，没有人知道他的坟墓。","notes":[]},{"n":7,"t":"摩西死的时候一百二十岁，眼目没有昏花，力量没有衰退。","notes":[]},{"n":8,"t":"以色列人在摩押平原为摩西哀哭了三十天，为摩西哀哭居丧的日期才结束。","notes":[]},{"n":9,"t":"嫩的儿子约书亚，因为摩西曾为他按手，他就被智慧的灵充满。以色列人听从他，照着耶和华所吩咐摩西的去做。","notes":[]},{"n":10,"t":"以后，以色列中再没有兴起一位先知像摩西的，他是耶和华面对面所认识的。","notes":[]},{"n":11,"t":"耶和华差派他在埃及地，向法老和他的一切臣仆，以及他的全地，行了各样神迹奇事，","notes":[]},{"n":12,"t":"又在以色列众人眼前显出大能的手，行了一切大而可畏的事。","notes":[]}]}},"JOS":{"1":{"heading":"神命令约书亚征服迦南","verses":[{"n":1,"t":"耶和华的仆人摩西死了以后，耶和华对摩西的助手嫩的儿子约书亚说：","notes":[]},{"n":2,"t":"“我的仆人摩西死了。现在你要起来，和众百姓过这约旦河，往我所要赐给以色列人的地去。","notes":[]},{"n":3,"t":"凡你们脚掌所踏之地，我都照我所应许摩西的话赐给你们了。","notes":[]},{"n":4,"t":"从旷野和这黎巴嫩，直到大河，就是幼发拉底河，赫人的全地，又到大海日落的方向，都要作你们的疆土。","notes":[]},{"n":5,"t":"你一生的日子，必无人能在你面前站立得住。我怎样与摩西同在，也必照样与你同在；我必不撇下你，也不丢弃你。","notes":[]},{"n":6,"t":"你当刚强壮胆，因为你必使这百姓承受那地为业，就是我向他们列祖起誓要给他们的地。","notes":[]},{"n":7,"t":"只要刚强，大大壮胆，谨守遵行我仆人摩西所吩咐你的一切律法，不可偏离左右，使你无论往哪里去， 都可以顺利。","notes":[]},{"n":8,"t":"这律法书不可离开你的口，总要昼夜思想，好使你谨守遵行这书上所写的一切话。如此，你的道路就可以亨通，凡事顺利。","notes":["“思想”或译“默念”。"]},{"n":9,"t":"我岂没有吩咐你吗？你当刚强壮胆，不要惧怕，也不要惊惶，因为你无论往哪里去，耶和华你的神必与你同在。”","notes":[]},{"n":10,"t":"于是，约书亚吩咐百姓的官长说：","notes":[],"heads":["准备过约旦河"]},{"n":11,"t":"“你们要走遍营中，吩咐百姓说：‘当预备食物， 因为三日之内你们要过这约旦河，进去得耶和华－你们神赐给你们为业之地。’”","notes":[]},{"n":12,"t":"约书亚对吕便人、迦得人和玛拿西半支派的人说：","notes":[]},{"n":13,"t":"“你们要记得耶和华的仆人摩西所吩咐你们的话说：‘耶和华－你们的神使你们得享安宁，必将这地赐给你们。’","notes":[]},{"n":14,"t":"你们的妻子、孩子和牲畜可以留在约旦河东、摩西所给你们的地。但你们中间所有大能的勇士都要带着兵器，在你们的弟兄前面过去，你们要帮助他们。","notes":[]},{"n":15,"t":"等到耶和华使你们的弟兄和你们一样得享平静，并且得着耶和华－你们神所赐他们为业之地的时候，你们才可以回到你们所得之地，承受为业，就是耶和华的仆人摩西在约旦河东、向日出的方向所给你们的地。”","notes":[]},{"n":16,"t":"他们回答约书亚说：“凡你吩咐我们的，我们都必做；凡你差我们去的地方，我们都必去。","notes":[]},{"n":17,"t":"我们在一切事上怎样听从摩西，也必照样听从你。惟愿耶和华－你的神与你同在，像与摩西同在一样。","notes":[]},{"n":18,"t":"无论什么人违背你的命令，不听从你所吩咐他的一切话，就必处死。你只要刚强壮胆！”","notes":[]}]},"2":{"heading":"派探子进耶利哥","verses":[{"n":1,"t":"嫩的儿子约书亚从什亭暗中派两个人作探子，说：“你们去窥探那地和耶利哥。”于是二人去了，来到一个名叫喇合的妓女家里，在那里睡觉。","notes":[]},{"n":2,"t":"有人告诉耶利哥王说：“看哪，今夜有以色列人到这里来窥探此地。”","notes":[]},{"n":3,"t":"耶利哥王派人到喇合那里， 说：“你要交出那来到你这里、进了你家的人，因为他们来是要窥探全地。”","notes":[]},{"n":4,"t":"但女人已把二人藏起来，却说：“那两个人确实到我这里来过，他们从哪里来，我却不知道。","notes":[]},{"n":5,"t":"天黑、要关城门的时候，他们就出去了。他们往哪里去我也不知道。你们赶快去追他们，就必追上。”","notes":[]},{"n":6,"t":"其实，这女人已经领二人上了屋顶，把他们藏在她摆列在屋顶的亚麻梗中。","notes":[]},{"n":7,"t":"那些人就往约旦河的路上追赶他们，直到渡口。追赶他们的人一出去，城门就关了。","notes":[]},{"n":8,"t":"二人还没有睡之前，女人就上屋顶，到他们那里，","notes":[]},{"n":9,"t":"对他们说：“我知道耶和华已经把这地赐给你们了，并且我们也都惧怕你们。这地所有的居民在你们面前都融化了。","notes":[]},{"n":10,"t":"因为我们听见你们出埃及的时候，耶和华怎样在你们前面使红海的水干了，并且你们怎样处置约旦河东的两个亚摩利王，西宏和噩，把他们完全消灭。","notes":["“红海”是根据七十士译本，原文是“芦苇海”；本卷书下同。"]},{"n":11,"t":"我们一听见就胆战心惊，人人因你们的缘故勇气全失。耶和华－你们的神是天上地下的神。","notes":["“胆战心惊”：原文是“心消化了”；本卷书下同。"]},{"n":12,"t":"现在我既然恩待你们，求你们指着耶和华向我起誓，你们也要恩待我的父家。请你们给我一个确实的凭据，","notes":[]},{"n":13,"t":"要救活我的父母、兄弟、姊妹，和所有属他们的，拯救我们的性命脱离死亡。”","notes":[]},{"n":14,"t":"那二人对她说：“我们愿意以性命来替你们死。你们若不泄漏我们这件事，当耶和华将这地赐给我们的时候，我们必以慈爱和诚信待你。”","notes":[]},{"n":15,"t":"于是女人用绳子把二人从窗户缒下去，因为她的屋子是在城墙边上，她也住在城墙上。","notes":[]},{"n":16,"t":"她对他们说：“你们暂且往山上去，免得追赶的人遇见你们。要在那里躲藏三天，等追赶的人回来，你们才可以走自己的路。”","notes":[]},{"n":17,"t":"二人对她说：“你叫我们所起的誓与我们无关，","notes":[]},{"n":18,"t":"除非，看哪，当我们来到这地的时候，你把这条朱红线绳子系在缒我们下去的窗户上，并要叫你的父母、兄弟和你父的全家都聚集在你家中。","notes":[]},{"n":19,"t":"凡离开你家门往街上去的，他的血必归到自己头上，与我们无关；凡在你家里的，若有人下手害他，他的血就归到我们头上。","notes":[]},{"n":20,"t":"你若泄漏我们这件事，你叫我们所起的誓就与我们无关了。”","notes":["“你叫我们所起的誓”：七十士译本是“你这个誓言”。"]},{"n":21,"t":"女人说：“就照你们的话吧！”于是她送他们走了，就把朱红绳子系在窗户上。","notes":[]},{"n":22,"t":"二人离开，到山上去，在那里停留三天，直等到追赶的人回去。追赶的人一路寻找，却找不着。","notes":[]},{"n":23,"t":"二人回来，下了山，过了河，来到嫩的儿子约书亚那里，向他报告他们所遭遇的一切事。","notes":[]},{"n":24,"t":"他们对约书亚说：“耶和华果然将那全地交在我们手中了，并且那地所有的居民在我们面前都融化了。”","notes":[]}]},"3":{"heading":"以色列人过约旦河","verses":[{"n":1,"t":"约书亚清早起来，和以色列众人起行，离开什亭，来到约旦河，过河以前住在那里。","notes":[]},{"n":2,"t":"过了三天，官长走遍营中，","notes":[]},{"n":3,"t":"吩咐百姓说：“当你们看见利未家的祭司抬着耶和华－你们神的约柜的时候，你们就要起行离开所住的地方，跟着约柜走，","notes":[]},{"n":4,"t":"使你们知道所当走的路，因为这条路是你们从来没有走过的。只是你们要与约柜相隔约二千肘，不可太靠近约柜。”","notes":[]},{"n":5,"t":"约书亚吩咐百姓说：“你们要使自己分别为圣，因为明天耶和华必在你们中间行奇事。”","notes":[]},{"n":6,"t":"约书亚对祭司说：“你们抬起约柜，在百姓的前面过去。”于是他们抬起约柜，走在百姓前面。","notes":[]},{"n":7,"t":"耶和华对约书亚说：“从今日起，我必使你在以色列众人眼前被尊为大，使他们知道我怎样与摩西同在，也必照样与你同在。","notes":[]},{"n":8,"t":"你要吩咐抬约柜的祭司说：‘你们到了约旦河的水边，要在约旦河中站着。’”","notes":[]},{"n":9,"t":"约书亚对以色列人说：“你们近前，到这里来，听耶和华－你们神的话。”","notes":[]},{"n":10,"t":"约书亚说：“你们因这事会知道永生的神在你们中间，他必从你们面前赶出迦南人、赫人、希未人、比利洗人、革迦撒人、亚摩利人、耶布斯人。","notes":[]},{"n":11,"t":"看哪！全地之主的约柜必在你们的前面过去，到约旦河里。","notes":[]},{"n":12,"t":"现在， 你们要从以色列支派中选出十二个人，每支派一人。","notes":[]},{"n":13,"t":"当抬耶和华全地之主约柜的祭司，脚掌踏入约旦河水里的时候，约旦河的水，就是从上往下流的水，必然中断，竖立成垒。”","notes":[]},{"n":14,"t":"百姓起行离开帐棚过约旦河的时候，抬约柜的祭司在百姓的前面。","notes":[]},{"n":15,"t":"那时正是收割的日子，约旦河的水涨满两岸。抬约柜的人到了约旦河，抬约柜的祭司脚一入水边，","notes":[]},{"n":16,"t":"那从上往下流的水就在很远的地方，在撒拉但旁边的亚当城那里停住，竖立成垒；那往亚拉巴海，就是盐海下流的水全然中断。于是，百姓在耶利哥的对面过了河。","notes":[]},{"n":17,"t":"抬耶和华约柜的祭司在约旦河中的干地上稳稳站着，以色列众人都从干地上过去，直到全国都过了约旦河。","notes":[]}]},"4":{"heading":"立石为记","verses":[{"n":1,"t":"当全民都过了约旦河，耶和华对约书亚说：","notes":[]},{"n":2,"t":"“你要从百姓中选出十二个人，每支派一人，","notes":[]},{"n":3,"t":"吩咐他们说：‘你们从这里，从约旦河中祭司的脚稳稳站立的地方，取十二块石头，一起带过去，放在你们今夜住宿的地方。’”","notes":["“从约旦河中...石头”：七十士译本是“从约旦河中取十二块准备好的石头”。"]},{"n":4,"t":"于是约书亚召集了他从以色列人中所选的十二个人，每支派一人。","notes":[]},{"n":5,"t":"约书亚对他们说：“你们要过去，到约旦河中，耶和华－你们神的约柜前面，按以色列人支派的数目，每人各取一块石头扛在肩上。","notes":[]},{"n":6,"t":"这些石头在你们中间将成为记号。日后，你们的子孙问你们说：‘这些石头对你们有什么意思呢？’","notes":[]},{"n":7,"t":"你们就对他们说：‘这是因为约旦河的水在耶和华的约柜前中断；约柜过约旦河的时候，约旦河的水就中断了。这些石头要作以色列人永远的纪念。’”","notes":[]},{"n":8,"t":"以色列人就照约书亚所吩咐的做了。他们按以色列人支派的数目，从约旦河中取了十二块石头，正如耶和华所吩咐约书亚的。他们把石头带过去，到他们所住宿的地方，就放在那里。","notes":[]},{"n":9,"t":"约书亚另外把十二块石头立在约旦河的中间，在抬约柜祭司的脚站立的地方；直到今日，石头还在那里。","notes":[]},{"n":10,"t":"抬约柜的祭司站在约旦河的中间，直到耶和华命令约书亚告诉百姓的一切事办完为止，正如摩西所吩咐约书亚的一切话。于是，百姓急速过了河。","notes":[]},{"n":11,"t":"全体百姓都过了河之后，耶和华的约柜和祭司才过去，到百姓的前面。","notes":[]},{"n":12,"t":"吕便人、迦得人、玛拿西半支派的人都照摩西所吩咐他们的，带着兵器在以色列人的前面过去。","notes":[]},{"n":13,"t":"约有四万带兵器的军队在耶和华面前过去，到耶利哥的平原，准备上阵。","notes":[]},{"n":14,"t":"在那日，耶和华使约书亚在以色列众人眼前被尊为大。在他一生的年日中，百姓敬服他，像从前敬服摩西一样。","notes":[]},{"n":15,"t":"耶和华对约书亚说：","notes":[]},{"n":16,"t":"“你吩咐抬法柜的祭司从约旦河上来。”","notes":[]},{"n":17,"t":"约书亚就吩咐祭司说：“你们从约旦河上来。”","notes":[]},{"n":18,"t":"抬耶和华约柜的祭司从约旦河中上来，脚掌一落干地，约旦河的水就流回原处，仍旧涨满两岸。","notes":[]},{"n":19,"t":"正月初十，百姓从约旦河上来，就在耶利哥东边的吉甲安营。","notes":[]},{"n":20,"t":"约书亚把他们从约旦河取来的那十二块石头立在吉甲，","notes":[]},{"n":21,"t":"对以色列人说：“日后，你们的子孙问他们的父亲说：‘这些石头是什么意思呢？’","notes":[]},{"n":22,"t":"你们就让你们的子孙知道，说：‘以色列人曾走干地过这约旦河。’","notes":[]},{"n":23,"t":"因为耶和华－你们的神在你们前面使约旦河的水干了，直到你们过来，就如耶和华－你们的神从前在我们前面使红海干了，直到我们过来一样，","notes":[]},{"n":24,"t":"要使地上万民都知道，耶和华的手大有能力，也要使你们天天敬畏耶和华－你们的神。”","notes":[]}]},"5":{"heading":"在吉甲行割礼","verses":[{"n":1,"t":"约旦河西亚摩利人的众王和靠海迦南人的众王，听见耶和华在以色列人前面使约旦河的水干了，直到他们过了河，众王因以色列人的缘故都胆战心惊，勇气全失。","notes":["“他们过了河”：原文另译“我们过了河”。"]},{"n":2,"t":"那时，耶和华对约书亚说：“你要造火石刀，第二次为以色列人行割礼。”","notes":[]},{"n":3,"t":"约书亚就造了火石刀，在哈尔拉勒山为以色列人行割礼。","notes":["“哈尔拉勒山”意思是“包皮山”。"]},{"n":4,"t":"约书亚行割礼的原因是这样：从埃及出来的众百姓，所有能打仗的男丁，出了埃及以后，都死在旷野的路上。","notes":[]},{"n":5,"t":"这些从埃及出来的众百姓都受过割礼；但是那些出埃及以后，在旷野的路上所生的众百姓却没有受过割礼。","notes":[]},{"n":6,"t":"以色列人在旷野走了四十年，直到那从埃及出来，全国能打仗的人都消灭了，因为他们没有听从耶和华的话。耶和华曾向他们起誓，必不容许他们看见耶和华向他们列祖起誓要给我们的地，就是流奶与蜜之地。","notes":[]},{"n":7,"t":"他们的子孙，就是耶和华兴起接续他们的，都没有受过割礼；因为在路上他们没有受割礼，约书亚就为他们行割礼。","notes":[]},{"n":8,"t":"全国的人都受了割礼，留在营中自己的地方，直到痊愈。","notes":[]},{"n":9,"t":"耶和华对约书亚说：“我今日将埃及的羞辱从你们身上除掉了。”因此，那地方名叫吉甲，直到今日。","notes":["“吉甲”意思是“除掉、滚离”。"]},{"n":10,"t":"以色列人在吉甲安营。正月十四日晚上，他们在耶利哥的平原守逾越节。","notes":[],"heads":["在吉甲守逾越节"]},{"n":11,"t":"逾越节的第二日，他们吃了当地的出产，就在那一天，吃了无酵饼和烘过的谷物。","notes":[]},{"n":12,"t":"他们吃了当地出产的第二日，吗哪就停止了。以色列人不再有吗哪了。那一年，他们就吃迦南地的出产。","notes":[]},{"n":13,"t":"约书亚靠近耶利哥的时候，举目观看，看哪，有一个人站在他对面，手里拿着拔出来的刀。约书亚到他那里，对他说：“你是属我们的，还是属我们敌人的呢？”","notes":[],"heads":["耶和华军队的元帅"]},{"n":14,"t":"他说：“不，我现在来是要作耶和华军队的元帅。”约书亚就脸伏于地下拜，说：“我主有什么话，请吩咐仆人吧！”","notes":[]},{"n":15,"t":"耶和华军队的元帅对约书亚说：“把你脚上的鞋脱下来，因为你所站的地方是圣的。”约书亚就照着做了。","notes":[]}]},"6":{"heading":"耶利哥城陷落","verses":[{"n":1,"t":"耶利哥的城门因以色列人的缘故，关得严紧，无人出入。","notes":[]},{"n":2,"t":"耶和华对约书亚说：“看，我已经把耶利哥城和耶利哥王，以及大能的勇士，都交在你手中。","notes":[]},{"n":3,"t":"你们要围绕这城，所有的士兵绕城一次，六日你都要这样做。","notes":[]},{"n":4,"t":"七个祭司要拿七个羊角走在约柜前。到了第七日，你们要围绕这城七次，祭司也要吹角。","notes":[]},{"n":5,"t":"羊角声拖长的时候，你们一听见角声，众百姓要大声呼喊，城墙就必倒塌，各人要往前直上。”","notes":[]},{"n":6,"t":"嫩的儿子约书亚召了祭司来，对他们说：“你们抬起约柜来，要有七个祭司拿七个羊角在耶和华的约柜前。”","notes":[]},{"n":7,"t":"他又对百姓说：“你们向前去围绕那城，带兵器的要在耶和华的约柜前过去。”","notes":[]},{"n":8,"t":"按照约书亚对百姓所说的，七个祭司拿了七个羊角在耶和华面前过去，他们吹着角，耶和华的约柜在他们后面跟着。","notes":[]},{"n":9,"t":"带兵器的走在吹角的祭司前面，后队跟着约柜走，号角继续在吹。","notes":[]},{"n":10,"t":"约书亚吩咐百姓说：“你们不可呼喊，不可让人听见你们的声音，连一句话也不可出你们的口，直到我对你们说‘呼喊’的那日，你们才呼喊。”","notes":[]},{"n":11,"t":"这样，约书亚使耶和华的约柜围绕那城，把城绕了一次。然后，众人回到营里，就在营里住宿。","notes":[]},{"n":12,"t":"约书亚清早起来，祭司又抬起耶和华的约柜。","notes":[]},{"n":13,"t":"七个祭司拿七个羊角，走在耶和华的约柜前，他们吹着角；带兵器的走在他们前面，后队跟着耶和华的约柜走，号角继续在吹。","notes":[]},{"n":14,"t":"第二日，他们再把城围绕一次，就回营里去。六日都是这样做。","notes":[]},{"n":15,"t":"第七日清早黎明时，他们起来，以同样的方式围绕城七次；惟独这一日他们围绕城七次。","notes":[]},{"n":16,"t":"到了第七次，祭司吹角的时候，约书亚对百姓说：“呼喊吧，因为耶和华已经把城交给你们了！","notes":[]},{"n":17,"t":"这城和其中所有的都要永献给耶和华作当毁灭的，只有妓女喇合与她家中所有的可以存活，因为她隐藏了我们所派的使者。","notes":[]},{"n":18,"t":"但你们务必谨慎，不可取那当灭的物，免得你们受诅咒，取了那当灭的物，使以色列全营成为诅咒而遭受灾祸。","notes":[]},{"n":19,"t":"只有金子、银子和铜铁的器皿都要归耶和华为圣，放入耶和华的库房中。”","notes":[]},{"n":20,"t":"于是百姓呼喊，祭司吹角。百姓一听见角声就大声呼喊，城墙随着倒塌。百姓上去进城，各人往前直上，把城夺取。","notes":[]},{"n":21,"t":"他们把城中所有的，无论男女老少，牛羊和驴，都用刀杀尽。","notes":[]},{"n":22,"t":"约书亚对窥探这地的两个人说：“你们进那妓女的家，照你们向她所起的誓，将那女人和她所有的都从那里带出来。”","notes":[]},{"n":23,"t":"两个作过探子的青年进去，把喇合与她的父母、兄弟，和她所有的带出来，他们把她所有的亲属都带出来，安置在以色列的营外。","notes":[]},{"n":24,"t":"他们用火焚烧了那城和其中所有的，只有金子、银子和铜铁的器皿都放在耶和华殿的库房中。","notes":[]},{"n":25,"t":"至于妓女喇合和她父家，以及她所有的，约书亚保存了他们的性命。她就住在以色列中，直到今日，因为她隐藏了约书亚派来窥探耶利哥的使者。","notes":[]},{"n":26,"t":"当时，约书亚叫众人起誓说：“凡兴起重修这耶利哥城的，当在耶和华面前受诅咒。他立根基的时候，必丧长子，安城门的时候，必丧幼子。”","notes":["“这耶利哥城”：七十士译本是“这城”。"]},{"n":27,"t":"耶和华与约书亚同在，约书亚的名声传遍全地。","notes":[]}]},"7":{"heading":"亚干犯罪","verses":[{"n":1,"t":"以色列人在当灭之物上犯了罪。犹大支派中，谢拉的曾孙，撒底的孙子，迦米的儿子亚干取了当灭之物，耶和华的怒气就向以色列人发作。","notes":[]},{"n":2,"t":"约书亚从耶利哥派人往伯特利东边，靠近伯．亚文的艾城去，对他们说：“你们上去窥探那地。”那些人就上去窥探艾城。","notes":["七十士译本没有“靠近伯．亚文”。"]},{"n":3,"t":"他们回到约书亚那里，对他说：“众百姓不必都上去，只要二、三千人上去就能攻取艾城；不必劳动众百姓都上去，因为他们人少。”","notes":[]},{"n":4,"t":"于是百姓中约有三千人上那里去，但他们竟在艾城的人面前逃跑。","notes":[]},{"n":5,"t":"艾城的人击杀他们约三十六人，从城门前追赶他们，直到示巴琳，在下坡的地方击败他们。他们都胆战心惊，融化如水。","notes":[]},{"n":6,"t":"约书亚和以色列的长老就撕裂衣服，在耶和华的约柜前脸伏于地，直到晚上。他们把灰撒在头上。","notes":[]},{"n":7,"t":"约书亚说：“唉！主耶和华啊，你为什么领这百姓过约旦河，把我们交在亚摩利人手中，使我们灭亡呢？我们不如住在约旦河的那边！","notes":[]},{"n":8,"t":"主啊，求求你，以色列人既在仇敌面前转身逃跑，我还有什么可说的呢？","notes":[]},{"n":9,"t":"迦南人和这地所有的居民听见了就必围困我们，把我们的名从地上除去。那时，你为你至大的名要怎样做呢？”","notes":[]},{"n":10,"t":"耶和华对约书亚说：“起来！你的脸为何这样俯伏呢？","notes":[]},{"n":11,"t":"以色列犯了罪，又违背了我所吩咐他们的约，又取了当灭之物。他们又偷窃，又行诡诈，又把那当灭的物与自己的器皿放在一起。","notes":[]},{"n":12,"t":"因此，以色列人在仇敌面前站立不住。他们在仇敌面前转身逃跑，因为他们成了当灭的物。你们若不把当灭的物从你们中间除掉，我就不再与你们同在了。","notes":[]},{"n":13,"t":"你起来，去叫百姓分别为圣，说：‘你们要为了明天使自己分别为圣，因为耶和华－以色列的神这样说：以色列啊，在你中间有当灭的物；你们若不把你们中间当灭之物除掉，你在仇敌面前必站立不住！’","notes":[]},{"n":14,"t":"到了早晨，你们要按着支派近前来。耶和华所选的支派，要按着宗族近前来；耶和华所选的宗族，要按着家族近前来；耶和华所选的家族，要按着男丁，一个一个近前来。","notes":[]},{"n":15,"t":"被选的人有当灭之物在他那里，他和他所有的必被火焚烧，因为他违背了耶和华的约，又因他在以色列中做了愚妄的事。”","notes":[]},{"n":16,"t":"于是，约书亚清早起来，召以色列按着支派近前来。选出来的是犹大支派。","notes":[]},{"n":17,"t":"他召犹大的宗族近前来，选出来的是谢拉宗族。他召谢拉宗族，按着男丁，一个一个近前来，选出来的是撒底。","notes":["“按着男丁”：有古卷和古译本是“按着家族”。"]},{"n":18,"t":"他召撒底的家族，按着男丁，一个一个近前来，就选出犹大支派，谢拉的曾孙，撒底的孙子，迦米的儿子亚干。","notes":[]},{"n":19,"t":"约书亚对亚干说：“我儿，我劝你将荣耀归给耶和华－以色列的神，在他面前认罪，把你所做的事告诉我，不可向我隐瞒。”","notes":[]},{"n":20,"t":"亚干回答约书亚说：“我实在得罪了耶和华－以色列的神。这是我所做的：","notes":[]},{"n":21,"t":"我在所夺取的财物中看见一件美好的示拿外袍，二百舍客勒银子，一条重五十舍客勒的金子。我贪爱这些物件，就拿去了。看哪，这些东西都埋在我帐棚内的地里，银子在外袍底下。”","notes":[]},{"n":22,"t":"约书亚就派使者跑到亚干的帐棚里。看哪，那件外袍藏在他的帐棚里，银子在外袍底下。","notes":[]},{"n":23,"t":"他们从帐棚里把这些东西取出来，拿到约书亚和以色列众人那里，倒在耶和华面前。","notes":["“众人”：七十士译本是“长老”。"]},{"n":24,"t":"约书亚和以色列众人把谢拉的曾孙亚干和那银子、那件外袍、那条金子，以及亚干的儿女、牛、驴、羊、帐棚，和他所有的，都带着上到亚割谷去。","notes":["“亚割谷”意思是“灾祸谷”。"]},{"n":25,"t":"约书亚说：“你为什么给我们招惹灾祸呢？今日耶和华必使你遭受灾祸。”于是以色列众人用石头打死他，用火焚烧他们，把石头扔在其上。","notes":[]},{"n":26,"t":"众人在亚干身上堆了一大堆石头，直存到今日。于是耶和华转意，不发他的烈怒。因此，那地方名叫亚割谷，直到今日。","notes":[]}]},"8":{"heading":"攻取艾城","verses":[{"n":1,"t":"耶和华对约书亚说：“不要惧怕，也不要惊惶。你起来，率领所有作战的士兵上艾城去。看，我已经把艾城的王和他的百姓、他的城，以及他的地，都交在你手里。","notes":[]},{"n":2,"t":"你怎样处置耶利哥和耶利哥的王，也当照样处置艾城和艾城的王。只是城内所夺的财物和牲畜，你们可以取为自己的掠物。你要在城的后面设下伏兵。","notes":[]},{"n":3,"t":"于是，约书亚和所有作战的士兵都起来，上艾城去。约书亚选了三万大能的勇士，夜间派遣他们前去，","notes":[]},{"n":4,"t":"吩咐他们说：“看，你们要在城的后面埋伏，不可离城太远，各人都要准备。","notes":[]},{"n":5,"t":"我与我所带领的众士兵要向城前进。城里的人像上一次那样出来迎击我们的时候，我们就在他们面前逃跑。","notes":[]},{"n":6,"t":"他们会出来追赶我们，直到我们引诱他们远离那城。因为他们必说：‘这些人像上次那样在我们面前逃跑。’所以我们要在他们面前逃跑。","notes":["七十士译本没有“所以我们要在他们面前逃跑”。"]},{"n":7,"t":"那时，你们就从埋伏的地方起来，夺取那城，因为耶和华－你们的神必把城交在你们的手里。","notes":[]},{"n":8,"t":"你们夺了城以后，要放火烧城，照耶和华的话去做。看，这是我吩咐你们的。”","notes":[]},{"n":9,"t":"于是，约书亚派遣他们前去。他们行军到埋伏的地方，伏在伯特利和艾城的中间，就是艾城的西边。这夜，约书亚在士兵中间过夜。","notes":[]},{"n":10,"t":"约书亚清早起来，点齐士兵。他和以色列的长老在百姓前面上艾城去。","notes":[]},{"n":11,"t":"所有跟他一起作战的士兵都上去，向前逼近，来到城前，就在艾城北边安营。约书亚与艾城之间隔着一个山谷。","notes":[]},{"n":12,"t":"他选了约五千人，安排他们埋伏在伯特利和艾城的中间，就是艾城的西边。","notes":[]},{"n":13,"t":"于是，他们布署军队，就是城北的全军和城西的伏兵。当夜约书亚进入山谷之中。","notes":[]},{"n":14,"t":"艾城的王看见了，就和城里的人清早起来，急忙出去，他和所有的士兵到了所定的地点，在亚拉巴前，迎击以色列，与之交战；王并不知道城的后面有伏兵。","notes":[]},{"n":15,"t":"约书亚和以色列众人在他们面前装败，往旷野的路逃跑。","notes":[]},{"n":16,"t":"城内所有的百姓都被召来追赶他们。艾城的人追赶约书亚的时候，就被引诱远离了城。","notes":[]},{"n":17,"t":"艾城和伯特利没有一人不出来追赶以色列人的。他们撇下敞开的城门，去追赶以色列人。","notes":[]},{"n":18,"t":"耶和华对约书亚说：“你向艾城伸出手里的标枪，因为我要把那城交在你手里。”约书亚就向那城伸出手里的标枪。","notes":[]},{"n":19,"t":"他一伸手，伏兵立刻从埋伏的地方冲出来，直攻入城，夺了它，立刻放火烧城。","notes":[]},{"n":20,"t":"艾城的人回头，往后一看，看哪，城中烟气冲天，他们向这边或那边都无处可逃。往旷野逃跑的百姓就转身攻击那些追赶他们的人。","notes":[]},{"n":21,"t":"约书亚和以色列众人见伏兵已经夺了城，城中烟气上腾，就转身击杀艾城的人。","notes":[]},{"n":22,"t":"伏兵也出城追击他们，他们就被以色列人前后夹攻，四面受敌。于是以色列人击杀他们，没有留下一个幸存者，也没有一个逃脱。","notes":[]},{"n":23,"t":"以色列人生擒了艾城的王，把他解到约书亚那里。","notes":[]},{"n":24,"t":"以色列人在田间和旷野杀尽了追赶他们的艾城所有的居民。他们全倒在刀下，直到灭尽。以色列众人就回到艾城，用刀杀了城中的人。","notes":[]},{"n":25,"t":"当日杀死的人，连男带女共有一万二千，这也是艾城所有的人。","notes":[]},{"n":26,"t":"约书亚没有收回手里所伸出来的标枪，直到他灭绝艾城所有的居民。","notes":[]},{"n":27,"t":"只是牲畜和城内所夺的财物，以色列人都照耶和华所吩咐约书亚的话，取为自己的掠物。","notes":[]},{"n":28,"t":"约书亚焚烧艾城，使城成为永远的废墟，直到今日还是荒凉。","notes":[]},{"n":29,"t":"他把艾城的王挂在树上，直到晚上。日落的时候，约书亚吩咐人把尸首从树上取下来，丢在城门口，并在尸首上堆了一大堆石头，直存到今日。","notes":[]},{"n":30,"t":"那时，约书亚在以巴路山上为耶和华－以色列的神筑一座坛。","notes":[],"heads":["在以巴路山上宣读律法"]},{"n":31,"t":"这坛是照耶和华的仆人摩西吩咐以色列人，用没有动过铁器的整块石头所筑的，正如摩西律法书上所写的。他们在这坛上给耶和华奉献燔祭，又宰牲作为平安祭。","notes":[]},{"n":32,"t":"约书亚在那里，当着以色列人面前，将摩西所写的律法抄写在石头上。","notes":[]},{"n":33,"t":"以色列众人，无论是本地人或寄居的，都和他们的长老、官长和审判官，站在约柜两旁，在抬耶和华约柜的利未家的祭司面前，一半对着基利心山，一半对着以巴路山，照耶和华的仆人摩西先前所吩咐的，为以色列百姓祝福。","notes":[]},{"n":34,"t":"随后，约书亚将律法上祝福和诅咒的话，照着律法书上一切所写的，宣读一遍。","notes":[]},{"n":35,"t":"摩西所吩咐的一切话，约书亚在以色列全会众和妇女、孩童，以及住在他们中间的外人面前，没有一句不宣读的。","notes":[]}]},"9":{"heading":"基遍人欺骗约书亚","verses":[{"n":1,"t":"约旦河西，住山区、低地和沿大海一带直到黎巴嫩的诸王，就是赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人的诸王，听见这事，","notes":[]},{"n":2,"t":"就都聚集，同心合意要与约书亚和以色列人作战。","notes":[]},{"n":3,"t":"基遍的居民听见约书亚向耶利哥和艾城所做的事，","notes":[]},{"n":4,"t":"就设诡计，假扮使者出去。他们拿旧布袋和破裂补过的旧皮酒袋驮在驴上，","notes":["“假扮使者”：有古卷、七十士译本和其他古译本是“带着粮食”。"]},{"n":5,"t":"将补过的旧鞋穿在脚上，把旧衣服穿在身上，作食物的饼都又干又长了霉。","notes":["“长了霉”或译“碎”；下同。"]},{"n":6,"t":"他们到吉甲营中约书亚那里，对他和以色列人说：“我们是从远地来的，现在求你与我们立约。”","notes":[]},{"n":7,"t":"以色列人对希未人说：“或许你是住在我附近的。若是这样，我怎能和你立约呢？”","notes":[]},{"n":8,"t":"他们对约书亚说：“我们是你的仆人。”约书亚对他们说：“你们是什么人？是从哪里来的？”","notes":[]},{"n":9,"t":"他们对他说：“你的仆人是因耶和华－你神的名从极远之地来的。我们听见他的名声，他在埃及所做的一切，","notes":[]},{"n":10,"t":"以及他向约旦河东的两个亚摩利王，希实本王西宏和在亚斯她录的巴珊王噩所做的一切。","notes":[]},{"n":11,"t":"我们的长老和我们当地所有的居民对我们说：‘你们手里要带着路上用的干粮去迎接以色列人，对他们说：我们是你们的仆人。现在求你们与我们立约。’","notes":[]},{"n":12,"t":"我们出来要往你们这里来的那日，这从我们家里带出来的饼是热的；看哪，现在这饼又干又长了霉。","notes":[]},{"n":13,"t":"这些皮酒袋，我们盛酒的时候还是新的；看哪，现在已经破裂了。我们这些衣服和鞋，因为路途非常遥远，也都穿旧了。”","notes":[]},{"n":14,"t":"以色列人收下他们的一些食物，但是没有求问耶和华的指示。","notes":[]},{"n":15,"t":"于是约书亚与他们建立和好关系，与他们立约，让他们存活；会众的领袖也向他们起誓。","notes":[]},{"n":16,"t":"以色列人与他们立约之后，过了三天才听说他们是近邻，住在附近。","notes":[]},{"n":17,"t":"以色列人起行，第三天就到了他们的城镇，他们的城镇是基遍、基非拉、比录和基列．耶琳。","notes":[]},{"n":18,"t":"因为会众的领袖已经指着耶和华－以色列的神向他们起誓，所以以色列人不击杀他们。全会众就向领袖发怨言。","notes":[]},{"n":19,"t":"众领袖对全会众说：“我们已经指着耶和华－以色列的神向他们起誓，现在我们不能碰他们。","notes":[]},{"n":20,"t":"我们要这样对待他们，让他们存活，免得因我们向他们所起的誓而愤怒临到我们。”","notes":[]},{"n":21,"t":"领袖对会众说：“让他们活着吧。”于是他们照领袖所说的，为全会众作劈柴挑水的人。","notes":[]},{"n":22,"t":"约书亚召了他们来，对他们说：“你们为什么欺骗我们说：‘我们离你们很远’呢？其实你们就住在我们附近。","notes":[]},{"n":23,"t":"现在你们当受诅咒！你们中间必不断有人作奴仆，为我神的殿作劈柴挑水的人。”","notes":[]},{"n":24,"t":"他们回答约书亚说：“因为确实有人告诉你的仆人，耶和华－你的神曾吩咐他的仆人摩西，把这全地赐给你们，并要在你们面前除灭这地所有的居民。我们因你们的缘故很怕自己丧命，就做了这事。","notes":[]},{"n":25,"t":"现在，看哪，我们在你手中，你看怎样待我们是好的，是对的，就这样做吧！”","notes":[]},{"n":26,"t":"于是约书亚就这样对待他们，他救了他们脱离以色列人的手，以色列人没有杀他们。","notes":[]},{"n":27,"t":"那日，约书亚分派他们到耶和华选择的地方，为会众和耶和华的坛劈柴挑水，直到今日。","notes":[]}]},"10":{"heading":"击败亚摩利人","verses":[{"n":1,"t":"耶路撒冷王亚多尼．洗德听见约书亚夺了艾城，彻底毁灭，处置艾城和艾城的王像处置耶利哥和耶利哥的王一样，又听见基遍的居民与以色列人立了和约，住在他们中间，","notes":[]},{"n":2,"t":"耶路撒冷人就很惧怕，因为基遍是一座大城，如京城一样，比艾城更大，并且城内的人都是勇士。","notes":[]},{"n":3,"t":"耶路撒冷王亚多尼．洗德派人去见希伯仑王何咸、耶末王毗兰、拉吉王雅非亚和伊矶伦王底璧，说：","notes":[]},{"n":4,"t":"“求你们上来帮助我，我们好攻打基遍，因为它与约书亚和以色列人立了和约。”","notes":[]},{"n":5,"t":"于是五个亚摩利王，就是耶路撒冷王、希伯仑王、耶末王、拉吉王和伊矶伦王，联合上去，率领他们所有的军队，对着基遍安营，要攻打基遍。","notes":[]},{"n":6,"t":"基遍人就派人到吉甲的营中约书亚那里，说：“不要袖手不顾你的仆人，求你赶快上来拯救我们，帮助我们，因为住山区亚摩利人的诸王已经联合来攻击我们。”","notes":[]},{"n":7,"t":"于是约书亚和所有跟他一起作战的士兵，以及大能的勇士，从吉甲上去。","notes":[]},{"n":8,"t":"耶和华对约书亚说：“不要怕他们， 因为我已将他们交在你手里，他们没有一人能在你面前站立得住。”","notes":[]},{"n":9,"t":"约书亚就连夜从吉甲上去，猛然袭击他们。","notes":[]},{"n":10,"t":"耶和华使他们在以色列人面前溃乱。约书亚在基遍大大击杀他们，在伯．和仑的上坡路上追赶他们，击杀他们，直到亚西加和玛基大。","notes":[]},{"n":11,"t":"他们在以色列人面前逃跑。正在伯．和仑下坡的时候，耶和华从天上降下大冰雹在他们身上，直降到亚西加，打死他们。被冰雹打死的，比以色列人用刀杀死的还多。","notes":["“冰雹”：原文是“石头”。"]},{"n":12,"t":"当耶和华将亚摩利人交给以色列人的那一日，约书亚向耶和华说话，在以色列人眼前说：“太阳啊，停在基遍；月亮啊，停在亚雅仑谷。”","notes":[]},{"n":13,"t":"太阳就停住，月亮就止住，直到国家向敌人报仇。这事岂不是写在《雅煞珥书》上吗？太阳停在天空当中，没有急速落下，约有一整天。","notes":[]},{"n":14,"t":"在这日以前，这日以后，耶和华听人的声音，没有像这日的，这是因为耶和华为以色列作战。","notes":[]},{"n":15,"t":"约书亚和跟他一起的以色列众人回到吉甲的营中。","notes":[]},{"n":16,"t":"那五个王逃跑，躲在玛基大洞里。","notes":[],"heads":["生擒亚摩利的五王"]},{"n":17,"t":"有人告诉约书亚说：“那五个王已经找到了，都躲在玛基大洞里。”","notes":[]},{"n":18,"t":"约书亚说：“你们把几块大石头滚到洞口，派人在那里看守他们。","notes":[]},{"n":19,"t":"你们却不可停留，要追赶你们的仇敌，从后面攻击他们，不让他们进到自己的城镇，因为耶和华－你们的神已经把他们交在你们手里。”","notes":[]},{"n":20,"t":"约书亚和以色列人彻底击败他们，直到把他们灭尽，只剩下少许的人逃进坚固的城。","notes":[]},{"n":21,"t":"众百姓就安然回到玛基大营中，到约书亚那里。没有人敢向以色列人饶舌。","notes":["七十士译本没有“营中”。"]},{"n":22,"t":"约书亚说：“打开洞口，把那五个王从洞里带出来，到我这里。”","notes":[]},{"n":23,"t":"众人就这样做，把那五个王，就是耶路撒冷王、希伯仑王、耶末王、拉吉王和伊矶伦王，从洞里带出来，到约书亚那里。","notes":[]},{"n":24,"t":"他们带出那五个王到约书亚那里的时候，约书亚就召了以色列众人来，对和他同去的军官说：“你们近前来，把脚踏在这些王的颈项上。”他们就近前来，把脚踏在这些王的颈项上。","notes":[]},{"n":25,"t":"约书亚对他们说：“你们不要惧怕，也不要惊惶。当刚强壮胆，因为耶和华必这样处置你们要攻打的所有仇敌。”","notes":[]},{"n":26,"t":"随后，约书亚把这五个王杀死，挂在五棵树上。他们就被挂在树上，直到晚上。","notes":[]},{"n":27,"t":"日落的时候，约书亚吩咐人把尸首从树上取下来，丢在他们躲过的洞里，把几块大石头放在洞口，直存到今日。","notes":[]},{"n":28,"t":"当日，约书亚夺了玛基大，用刀击杀城中的人和王，把城中所有人完全灭尽，没有留下一个幸存者。他处置玛基大王，像从前处置耶利哥王一样。","notes":[],"heads":["攻取更多的城镇"]},{"n":29,"t":"约书亚和跟他一起的以色列众人从玛基大往立拿去，攻打立拿。","notes":[]},{"n":30,"t":"耶和华将立拿和立拿的王也交在以色列人手里。约书亚攻打这城，用刀击杀了城中所有的人，没有留下一个幸存者。他处置立拿王，像从前处置耶利哥王一样。","notes":[]},{"n":31,"t":"约书亚和跟他一起的以色列众人从立拿往拉吉去，对着拉吉安营，攻打这城。","notes":[]},{"n":32,"t":"耶和华将拉吉交在以色列人的手里。第二日约书亚就夺了拉吉，用刀击杀了城中所有的人，正如他向立拿一切所做的。","notes":[]},{"n":33,"t":"那时基色王何兰上来帮助拉吉，约书亚就把他和他的百姓都击杀了，没有留下一个幸存者。","notes":[]},{"n":34,"t":"约书亚和跟他一起的以色列众人从拉吉往伊矶伦去，对着伊矶伦安营，攻打这城。","notes":[]},{"n":35,"t":"当日约书亚就夺了城，用刀击杀了城中的人。那日，约书亚把城中所有的人完全灭尽，正如他向拉吉一切所做的。","notes":[]},{"n":36,"t":"约书亚和跟他一起的以色列众人从伊矶伦上希伯仑去，攻打这城，","notes":[]},{"n":37,"t":"夺了希伯仑，用刀击败希伯仑、它的王和属它的一切城镇，以及城中所有的人；他没有留下一个幸存者，正如他向伊矶伦所做的，把城中所有的人完全灭尽。","notes":[]},{"n":38,"t":"约书亚和跟他一起的以色列众人回到底璧，攻打这城，","notes":[]},{"n":39,"t":"夺了底璧和属它的一切城镇，又擒获它的王，用刀把城中所有的人完全灭尽，没有留下一个幸存者。他处置底璧和它的王，像从前处置希伯仑，处置立拿和它的王一样。","notes":[]},{"n":40,"t":"这样，约书亚击败全地的人，就是山区、尼革夫、低地、山坡的人，和那里的众王，没有留下一个幸存者。他把凡有气息的完全灭尽，正如耶和华－以色列的神所吩咐的。","notes":["“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”；本卷书下同。"]},{"n":41,"t":"约书亚从加低斯．巴尼亚攻到迦萨，又攻打歌珊全地，直到基遍。","notes":[]},{"n":42,"t":"约书亚一举击败了这些王，夺了他们的地，因为耶和华－以色列的神为以色列作战。","notes":[]},{"n":43,"t":"于是约书亚和跟他一起的以色列众人回到吉甲的营中。","notes":[]}]},"11":{"heading":"击败众王的联军","verses":[{"n":1,"t":"夏琐王耶宾听见了，就派人到玛顿王约巴、伸仑王、押煞王，","notes":["“玛顿”：七十士译本是“玛伦”。","“伸仑”：七十士译本是“伸门”。"]},{"n":2,"t":"和北方山区、基尼烈南边的亚拉巴、低地、西边多珥山冈的诸王，","notes":["“山冈”或译“全境”。"]},{"n":3,"t":"以及东方和西方的迦南人、山区的亚摩利人、赫人、比利洗人、耶布斯人，和黑门山下米斯巴地的希未人那里。","notes":[]},{"n":4,"t":"他们和他们的众军都出来，一大队人马，多如海边的沙，并有极多的战车战马。","notes":[]},{"n":5,"t":"众王组成联军，来到米伦水边一同安营，要与以色列作战。","notes":[]},{"n":6,"t":"耶和华对约书亚说：“你不要怕他们。明日这时，我必把他们全部交给以色列人杀灭。你要砍断他们马的蹄筋，用火焚烧他们的战车。”","notes":[]},{"n":7,"t":"于是约书亚和所有跟他一起作战的士兵，来到米伦水边，突然攻击他们。","notes":[]},{"n":8,"t":"耶和华将他们交在以色列人手里，以色列人就击杀他们，追赶他们到西顿大城，到米斯利弗．玛音，直到东边米斯巴的山谷。以色列人击杀他们，没有留下一个幸存者。","notes":[]},{"n":9,"t":"约书亚照耶和华所吩咐他的去做，砍断他们马的蹄筋，用火焚烧他们的战车。","notes":[]},{"n":10,"t":"那时，约书亚转回，夺了夏琐，用刀杀了夏琐王。先前夏琐在这些王国中是为首的。","notes":[]},{"n":11,"t":"以色列人用刀击杀城中所有的人，把他们完全灭尽；凡有气息的，没有留下一个。约书亚又用火焚烧夏琐。","notes":[]},{"n":12,"t":"约书亚夺了这些王的一切城镇，擒获了这些王，用刀杀了他们，把他们完全灭尽，正如耶和华的仆人摩西所吩咐的。","notes":[]},{"n":13,"t":"至于造在山冈上的城镇，除了夏琐以外，以色列人都没有焚烧。约书亚只焚烧了夏琐。","notes":[]},{"n":14,"t":"从那些城镇所夺的财物和牲畜，以色列人都取为自己的掠物。至于所有的人，他们都用刀杀了，直到灭尽；凡有气息的，没有留下一个。","notes":[]},{"n":15,"t":"耶和华怎样吩咐他的仆人摩西，摩西就这样吩咐约书亚，约书亚也照样做了。凡耶和华所吩咐摩西的，约书亚没有一件偏离不做的。","notes":[]},{"n":16,"t":"约书亚夺了那全地，就是山区、整个尼革夫、歌珊全地、低地、亚拉巴、以色列的山区和山下的低地，","notes":[],"heads":["占领的土地"]},{"n":17,"t":"从上西珥的哈拉山，直到黑门山下面黎巴嫩平原的巴力．迦得。他擒获了那里的众王，把他们杀死。","notes":[]},{"n":18,"t":"约书亚和这些王作战了很长的一段日子。","notes":[]},{"n":19,"t":"除了希未人基遍的居民之外，没有一城与以色列人讲和，都是以色列人作战夺来的。","notes":[]},{"n":20,"t":"因为耶和华的意思是要使他们的心刚硬，来与以色列人作战，好使他们全被杀灭，不蒙怜悯，反被除灭，正如耶和华所吩咐摩西的。","notes":[]},{"n":21,"t":"那时约书亚来到，剪除了住山区、希伯仑、底璧、亚拿伯、整个犹大山区和以色列山区的亚衲族人。约书亚把他们和他们的城镇尽都毁灭。","notes":[]},{"n":22,"t":"以色列人的地中没有留下一个亚衲族人，只有一些还留在迦萨、迦特和亚实突。","notes":[]},{"n":23,"t":"这样，约书亚照着耶和华所吩咐摩西的一切话夺了那全地，就按着以色列支派所得的份把地分给他们为业。于是国中太平，没有战争了。","notes":[]}]},"12":{"heading":"摩西击败的诸王","verses":[{"n":1,"t":"这些是以色列人在约旦河东，向日出的方向，从亚嫩谷直到黑门山，以及东边亚拉巴的整个地区所击杀的王和所得的地：","notes":[]},{"n":2,"t":"有住希实本的亚摩利王西宏，他统治的地从亚嫩谷边的亚罗珥起，包括谷中之城和基列的一半，直到亚扪人边界的雅博河，","notes":[]},{"n":3,"t":"以及从东边的亚拉巴，直到基尼烈海，又向东通过伯．耶施末的路，直到亚拉巴的海，就是盐海，再往南直到毗斯迦山斜坡的山脚。","notes":[]},{"n":4,"t":"又有巴珊王噩，他是利乏音人所剩下的，住在亚斯她录和以得来。","notes":["“又有巴珊王噩”是根据七十士译本；原文是“以下是巴珊王噩的疆土”。"]},{"n":5,"t":"他统治的地是黑门山、撒迦、巴珊全地，直到基述人和玛迦人的边界，以及基列的一半，直到希实本王西宏的边界。","notes":[]},{"n":6,"t":"这两个王是耶和华的仆人摩西和以色列人所击杀的。耶和华的仆人摩西把他们的地赐给吕便人、迦得人和玛拿西半支派的人为业。","notes":[]},{"n":7,"t":"这些是约书亚和以色列人在约旦河西所击杀的诸王，他们的地从黎巴嫩平原的巴力．迦得，直上到西珥的哈拉山。约书亚按着以色列支派所得的份把这地分给他们为业，","notes":[],"heads":["约书亚击败的诸王"]},{"n":8,"t":"就是赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人的地，包括山区、低地、亚拉巴、山坡、旷野和尼革夫。","notes":[]},{"n":9,"t":"这些王是：耶利哥王一人，靠近伯特利的艾城王一人，","notes":[]},{"n":10,"t":"耶路撒冷王一人，希伯仑王一人，","notes":[]},{"n":11,"t":"耶末王一人，拉吉王一人，","notes":[]},{"n":12,"t":"伊矶伦王一人，基色王一人，","notes":[]},{"n":13,"t":"底璧王一人，基德王一人，","notes":[]},{"n":14,"t":"何珥玛王一人，亚拉得王一人，","notes":[]},{"n":15,"t":"立拿王一人，亚杜兰王一人，","notes":[]},{"n":16,"t":"玛基大王一人，伯特利王一人，","notes":[]},{"n":17,"t":"他普亚王一人，希弗王一人，","notes":[]},{"n":18,"t":"亚弗王一人，拉沙仑王一人，","notes":[]},{"n":19,"t":"玛顿王一人，夏琐王一人，","notes":[]},{"n":20,"t":"伸仑．米仑王一人，押煞王一人，","notes":["“伸仑．米仑王一人”：七十士译本是“伸门王一人，米仑王一人”。"]},{"n":21,"t":"他纳王一人，米吉多王一人，","notes":[]},{"n":22,"t":"基低斯王一人，靠近迦密的约念王一人，","notes":[]},{"n":23,"t":"多珥山冈的多珥王一人，吉甲的戈印王一人，","notes":["“山冈”或译“全境”。","“吉甲的”：七十士译本是“加利利的”。"]},{"n":24,"t":"得撒王一人，共三十一个王。","notes":[]}]},"13":{"heading":"未得之地","verses":[{"n":1,"t":"约书亚年纪老迈，耶和华对他说：“你年纪老迈了，还有极多剩下的未得之地。","notes":[]},{"n":2,"t":"这是剩下的地：非利士人的全境和一切属于基述人的，","notes":[]},{"n":3,"t":"是从埃及东边的西曷河往北，直到以革伦的边界，算是属迦南人的地，那里有非利士人五个领袖统治迦萨人、亚实突人、亚实基伦人、迦特人、以革伦人；还有属于亚卫人的，","notes":[]},{"n":4,"t":"在南边；还有迦南人的全地，以及西顿人的米亚拉到亚弗，直到亚摩利人的边界；","notes":["“西顿人的米亚拉”：原文另译“从西顿人的亚拉”。"]},{"n":5,"t":"还有迦巴勒人的地，以及向日出方向的黎巴嫩全地，从黑门山下的巴力．迦得，直到哈马口；","notes":[]},{"n":6,"t":"从黎巴嫩直到米斯利弗．玛音，一切山区的居民，就是所有的西顿人，我必在以色列人面前赶走他们。你只管照我所吩咐的，抽签将这地分给以色列人为业。","notes":[]},{"n":7,"t":"现在你要把这地分给九个支派和玛拿西半个支派为业。」","notes":[]},{"n":8,"t":"吕便、迦得二支派已经和玛拿西另外半个支派得了产业，就是耶和华的仆人摩西在约旦河东所赐给他们的：","notes":[],"heads":["约旦河东之地的分配"]},{"n":9,"t":"从亚嫩谷边的亚罗珥和谷中之城，米底巴的整个平原，直到底本；","notes":[]},{"n":10,"t":"还有在希实本作王的亚摩利王西宏的诸城，直到亚扪人的边界；","notes":[]},{"n":11,"t":"还有基列，基述人和玛迦人的边界，整个黑门山、整个巴珊，直到撒迦；","notes":[]},{"n":12,"t":"还有在亚斯她录和以得来作王的巴珊王噩的整个国土，噩是利乏音人惟一存留的。摩西击败了这些人，把他们赶走。","notes":[]},{"n":13,"t":"以色列人却没有赶走基述人和玛迦人；基述人和玛迦人仍住在以色列中，直到今日。","notes":[]},{"n":14,"t":"只是利未支派，摩西没有分产业给他们。他们的产业是献给耶和华－以色列神的火祭，正如耶和华对他们说的。","notes":[]},{"n":15,"t":"摩西按着吕便支派的宗族分产业给他们。","notes":[],"heads":["分给吕便的土地"]},{"n":16,"t":"他们的地界是亚嫩谷边的亚罗珥和谷中之城，靠近米底巴的整个平原；","notes":[]},{"n":17,"t":"还有希实本和属希实本平原的各城，底本、巴末．巴力、伯．巴力．勉、","notes":[]},{"n":18,"t":"雅杂、基底莫、米法押、","notes":[]},{"n":19,"t":"基列亭、西比玛、谷中山冈上的细列．沙辖、","notes":[]},{"n":20,"t":"伯．毗珥、毗斯迦山斜坡、伯．耶施末；","notes":[]},{"n":21,"t":"还有平原的各城，和亚摩利王西宏的整个国土。这西宏曾在希实本作王，摩西把他和米甸的族长以未、利金、苏珥、户珥、利巴击杀了；他们都是属西宏的领袖，曾住在这地。","notes":[]},{"n":22,"t":"以色列人杀了这些人时，也用刀杀了比珥的儿子占卜的巴兰。","notes":[]},{"n":23,"t":"吕便人的地界就是约旦河和靠近约旦河的地。以上是吕便人按着宗族所得为业的城镇和所属的村庄。","notes":[]},{"n":24,"t":"摩西按着迦得支派的宗族分产业给他们。","notes":[],"heads":["分给迦得的土地"]},{"n":25,"t":"他们的地界是雅谢和基列的各城，以及亚扪人之地的一半，直到拉巴前面的亚罗珥；","notes":[]},{"n":26,"t":"还有从希实本到拉抹．米斯巴和比多宁，又从玛哈念到底璧的边界，","notes":["“底璧”：原文另译“罗．底巴”。"]},{"n":27,"t":"和谷中的伯．亚兰、伯．宁拉、疏割、撒分，就是希实本王西宏国土中其余的地，以及约旦河与靠近约旦河的地，直到基尼烈海的边缘，都在约旦河东。","notes":[]},{"n":28,"t":"以上是迦得人按着宗族所得为业的城镇和所属的村庄。","notes":[]},{"n":29,"t":"摩西分产业给玛拿西半支派，这是按着玛拿西半支派的宗族分的。","notes":[],"heads":["分给玛拿西半支派的土地"]},{"n":30,"t":"他们的地界是从玛哈念起，包括整个巴珊全地，就是巴珊王噩的整个国土，以及在巴珊、睚珥的一切城镇，共六十个；","notes":[]},{"n":31,"t":"还有基列的一半，以及巴珊国的王噩的亚斯她录和以得来两座城。这些地是按着宗族分给玛拿西儿子玛吉子孙的，就是给玛吉一半子孙的。","notes":[]},{"n":32,"t":"以上是摩西在约旦河东，耶利哥对面的摩押平原所分配的产业。","notes":[]},{"n":33,"t":"只是利未支派，摩西没有把产业分给他们。耶和华－以色列的神是他们的产业，正如耶和华对他们说的。","notes":[]}]},"14":{"heading":"约旦河西之地的分配","verses":[{"n":1,"t":"这是以色列人在迦南地所得的产业，就是祭司以利亚撒和嫩的儿子约书亚，以及以色列人各支派父系的领袖所分给他们的。","notes":[]},{"n":2,"t":"他们照耶和华藉摩西所吩咐的，抽签分产业给九个半支派。","notes":[]},{"n":3,"t":"摩西在约旦河东已经分了产业给另外两个半支派。但是，他在他们中间没有分产业给利未人。","notes":[]},{"n":4,"t":"因约瑟的子孙成了两个支派，就是玛拿西和以法莲。虽然他们没有分地给利未人，却给利未人城镇居住，以及城镇的郊外供他们牧养牲畜，安置财物。","notes":[]},{"n":5,"t":"耶和华怎样吩咐摩西，以色列人就照样做，把地分了。","notes":[]},{"n":6,"t":"犹大人来到吉甲，约书亚那里，基尼洗族耶孚尼的儿子迦勒对约书亚说：“耶和华在加低斯．巴尼亚指着我和你对神人摩西所说的话，你都知道。","notes":[],"heads":["迦勒分得希伯仑"]},{"n":7,"t":"耶和华的仆人摩西从加低斯．巴尼亚差派我窥探这地的时候，我刚四十岁。我把心里的话向他报告。","notes":[]},{"n":8,"t":"虽然同我上去的众弟兄使百姓胆战心惊，我仍然专心跟从耶和华－我的神。","notes":[]},{"n":9,"t":"那日，摩西起誓说：‘你脚所踏之地必要归你和你的子孙永远为业，因为你专心跟从耶和华－我的神。’","notes":[]},{"n":10,"t":"现在，看哪，耶和华照他所说的使我活了这四十五年。当以色列人在旷野飘流的时候，耶和华曾对摩西说了这话。现在，看哪，我已经八十五岁了。","notes":[]},{"n":11,"t":"现今我还很健壮，像摩西差派我去的那天一样；无论是战争，是出入，我现在的力量和那时的力量一样。","notes":[]},{"n":12,"t":"请你将耶和华那日所说的这山区给我。那日你也曾听说，这里有亚衲族人，以及宽大坚固的城，或许耶和华会照他所说的与我同在，我就把他们赶出去。”","notes":[]},{"n":13,"t":"于是约书亚为耶孚尼的儿子迦勒祝福，把希伯仑给他为业。","notes":[]},{"n":14,"t":"所以希伯仑成了基尼洗族耶孚尼的儿子迦勒的产业，直到今日，因为他专心跟从耶和华－以色列的神。","notes":[]},{"n":15,"t":"希伯仑从前名叫基列．亚巴；亚巴是亚衲族最尊贵的人。于是国中太平，没有战争了。","notes":["“亚巴”：原文是“他”，“亚巴”是人名。"]}]},"15":{"heading":"分给犹大的土地","verses":[{"n":1,"t":"犹大支派按着宗族抽签所得之地是在最南端，到以东的边界，往南直到寻的旷野。","notes":[]},{"n":2,"t":"他们南边的地界是从盐海的顶端，就是朝南的海湾开始，","notes":[]},{"n":3,"t":"通到亚克拉滨斜坡的南边，经过寻，上到加低斯．巴尼亚的南边，又经过希斯仑，上到亚达珥，转到甲加，","notes":[]},{"n":4,"t":"再经过押们，顺着埃及溪谷，这地界直通到海为止。这就是你们南边的地界。","notes":["“你们”：七十士译本是“他们”。"]},{"n":5,"t":"东边的地界是从盐海到约旦河口。北边的地界是从约旦河口的海湾开始，","notes":[]},{"n":6,"t":"这地界上到伯．曷拉，经过伯．亚拉巴的北边，这地界上到吕便之子波罕的磐石。","notes":[]},{"n":7,"t":"这地界是从亚割谷往北上到底璧，直向亚都冥斜坡对面的吉甲，就是河的南边，这地界再经过隐．示麦泉，直通到隐．罗结。","notes":[]},{"n":8,"t":"这地界又上到欣嫩子谷，耶布斯斜坡的南方，耶布斯就是耶路撒冷，这地界又上到欣嫩谷西边对面的山顶，就是在利乏音谷的最北端。","notes":[]},{"n":9,"t":"这地界又从山顶延伸到尼弗多亚水泉，通到以弗仑山的城镇，这地界又延伸到巴拉，巴拉就是基列．耶琳。","notes":[]},{"n":10,"t":"这地界又从巴拉往西绕到西珥山，经过耶琳山斜坡的北边，耶琳就是基撒仑，从那里又下到伯．示麦，经过亭拿，","notes":[]},{"n":11,"t":"这地界通到以革伦斜坡的北边。这地界又延伸到施基仑，经过巴拉山到雅比聂，这地界直通到海为止。","notes":[]},{"n":12,"t":"西边的地界就是大海和沿海一带之地。这是犹大人按着宗族所得之地四围的边界。","notes":[]},{"n":13,"t":"约书亚照耶和华所指示的，把犹大人中的一份土地，就是基列．亚巴，分给耶孚尼的儿子迦勒。亚巴是亚衲族的祖先，基列．亚巴就是希伯仑。","notes":[],"heads":["迦勒攻占的土地"]},{"n":14,"t":"迦勒从那里赶出亚衲的三族，就是亚衲族的示筛人、亚希幔人和挞买人。","notes":[]},{"n":15,"t":"他又从那里上去，攻击底璧的居民，这底璧从前名叫基列．西弗。","notes":[]},{"n":16,"t":"迦勒说：“谁能攻打基列．西弗，夺取那城，我就把我女儿押撒嫁给他。”","notes":[]},{"n":17,"t":"迦勒兄弟基纳斯的儿子俄陀聂夺取了那城，迦勒就把女儿押撒嫁给他。","notes":[]},{"n":18,"t":"押撒来的时候，催促丈夫向她父亲要一块田。押撒一下驴，迦勒就对她说：“你要什么？”","notes":[]},{"n":19,"t":"她说：“求你给我福分；你既然把我安置在尼革夫地，求你也给我水泉。”她父亲就把上泉和下泉都赐给她。","notes":[]},{"n":20,"t":"这是犹大支派按着宗族所得的产业。","notes":[],"heads":["犹大分得的城镇"]},{"n":21,"t":"犹大支派最南端，靠近以东边界的城镇，是甲薛、以得、雅姑珥、","notes":[]},{"n":22,"t":"基拿、底摩拿、亚大达、","notes":[]},{"n":23,"t":"基低斯、夏琐、以提楠、","notes":[]},{"n":24,"t":"西弗、提鍊、比亚绿、","notes":[]},{"n":25,"t":"夏琐．哈大他、加略．希斯仑，加略．希斯仑就是夏琐，","notes":[]},{"n":26,"t":"亚曼、示玛、摩拉大、","notes":[]},{"n":27,"t":"哈萨．迦大、黑实门、伯．帕列、","notes":[]},{"n":28,"t":"哈萨．书亚、别是巴、比斯约他、","notes":[]},{"n":29,"t":"巴拉、以因、以森、","notes":[]},{"n":30,"t":"伊勒多腊、基失、何珥玛、","notes":[]},{"n":31,"t":"洗革拉、麦玛拿、三撒拿、","notes":[]},{"n":32,"t":"利巴勿、实忻、亚因、临门，共二十九座城，还有所属的村庄。","notes":[]},{"n":33,"t":"在低地有以实陶、琐拉、亚实拿、","notes":[]},{"n":34,"t":"撒挪亚、隐．干宁、他普亚、以楠、","notes":[]},{"n":35,"t":"耶末、亚杜兰、梭哥、亚西加、","notes":[]},{"n":36,"t":"沙拉音、亚底他音、基底拉、基底罗他音，共十四座城，还有所属的村庄。","notes":[]},{"n":37,"t":"又有洗楠、哈大沙、麦大．迦得、","notes":[]},{"n":38,"t":"底连、米斯巴、约帖、","notes":[]},{"n":39,"t":"拉吉、波斯加、伊矶伦、","notes":[]},{"n":40,"t":"迦本、拉幔、基提利、","notes":[]},{"n":41,"t":"基低罗、伯．大衮、拿玛、玛基大，共十六座城，还有所属的村庄。","notes":[]},{"n":42,"t":"又有立拿、以帖、亚珊、","notes":[]},{"n":43,"t":"益弗他、亚实拿、尼悉、","notes":[]},{"n":44,"t":"基伊拉、亚革悉、玛利沙，共九座城，还有所属的村庄。","notes":[]},{"n":45,"t":"又有以革伦和所属的乡镇与村庄，","notes":["“乡镇”：原文直译“女子们”；本卷书下同。"]},{"n":46,"t":"从以革伦直到海，一切靠近亚实突之地，以及所属的村庄、","notes":[]},{"n":47,"t":"亚实突和所属的乡镇与村庄，迦萨和所属的乡镇与村庄，到埃及溪谷，直到大海以及沿海一带之地。","notes":[]},{"n":48,"t":"在山区有沙密、雅提珥、梭哥、","notes":[]},{"n":49,"t":"大拿、基列．萨拿，基列．萨拿就是底璧，","notes":[]},{"n":50,"t":"亚拿伯、以实提莫、亚念、","notes":[]},{"n":51,"t":"歌珊、何仑、基罗，共十一座城，还有所属的村庄。","notes":[]},{"n":52,"t":"又有亚拉、度玛、以珊、","notes":[]},{"n":53,"t":"雅农、伯．他普亚、亚非加、","notes":[]},{"n":54,"t":"宏他、基列．亚巴，基列．亚巴就是希伯仑，洗珥，共九座城，还有所属的村庄。","notes":[]},{"n":55,"t":"又有玛云、迦密、西弗、淤他、","notes":[]},{"n":56,"t":"耶斯列、约甸、撒挪亚、","notes":[]},{"n":57,"t":"该隐、基比亚、亭拿，共十座城，还有所属的村庄。","notes":[]},{"n":58,"t":"又有哈忽、伯．夙、基突、","notes":[]},{"n":59,"t":"玛腊、伯．亚诺、伊勒提君，共六座城，还有所属的村庄。","notes":[]},{"n":60,"t":"又有基列．巴力，基列．巴力就是基列．耶琳，拉巴，共两座城，还有所属的村庄。","notes":[]},{"n":61,"t":"在旷野有伯．亚拉巴、密丁、西迦迦、","notes":[]},{"n":62,"t":"匿珊、盐城、隐．基底，共六座城，还有所属的村庄。","notes":[]},{"n":63,"t":"至于住耶路撒冷的耶布斯人，犹大人不能把他们赶出去。于是，耶布斯人与犹大人同住在耶路撒冷，直到今日。","notes":[]}]},"16":{"heading":"分给约瑟子孙的土地","verses":[{"n":1,"t":"约瑟的子孙抽签所得之地是从靠近耶利哥的约旦河起，以耶利哥东边的河水为边界，经过旷野，从耶利哥上去，直到伯特利的山区；","notes":[]},{"n":2,"t":"从伯特利又到路斯，经过亚基人的边界，直到亚大录；","notes":[]},{"n":3,"t":"又往西，下到押利提人的边界，到下伯．和仑的边界，到基色，直通到海为止。","notes":[]},{"n":4,"t":"约瑟的儿子玛拿西、以法莲得了地业。","notes":[]},{"n":5,"t":"以法莲子孙的地界，按着宗族所得的如下：他们地业的东界，是从亚大录．亚达到上伯．和仑，","notes":[],"heads":["分给以法莲的土地"]},{"n":6,"t":"这地界直通到海。在北边，这地界是从密米他，向东绕到他纳．示罗，又经过雅挪哈的东边，","notes":[]},{"n":7,"t":"从雅挪哈下到亚大录和拿拉，再到耶利哥，直到约旦河为止。","notes":[]},{"n":8,"t":"这地界又从他普亚，顺着加拿河往西延伸，直通到海为止。这就是以法莲支派按着宗族所得的地业。","notes":[]},{"n":9,"t":"在玛拿西人地业的一切城镇和所属的村庄中，也保留一些城镇给以法莲的子孙。","notes":[]},{"n":10,"t":"他们却没有赶出住在基色的迦南人。迦南人就住在以法莲人中，成为服劳役的仆人，直到今日。","notes":[]}]},"17":{"heading":"分给西玛拿西半支派的土地","verses":[{"n":1,"t":"玛拿西是约瑟的长子，这是他的支派抽签所得之地。玛拿西的长子，基列的父亲玛吉，因为是勇士，就得了基列和巴珊。","notes":[]},{"n":2,"t":"玛拿西其余的子孙，就是亚比以谢的子孙，希勒的子孙，亚斯烈的子孙，示剑的子孙，希弗的子孙，示米大的子孙，都按着宗族抽签得了地。这都是约瑟的儿子玛拿西子孙中各宗族的男丁。","notes":[]},{"n":3,"t":"玛拿西的玄孙，玛吉的曾孙，基列的孙子，希弗的儿子西罗非哈没有儿子，只有女儿。他的女儿名叫玛拉、挪阿、曷拉、密迦、得撒。","notes":[]},{"n":4,"t":"她们来到以利亚撒祭司和嫩的儿子约书亚以及众领袖面前，说：“耶和华曾吩咐摩西在我们兄弟中分产业给我们。”于是约书亚照耶和华的指示，在她们叔伯中，把产业分给她们。","notes":[]},{"n":5,"t":"除了约旦河东的基列和巴珊地之外，还有十份的地业是属于玛拿西的，","notes":[]},{"n":6,"t":"因为玛拿西支派的女子也在男子中分得产业。基列地属于玛拿西其余的子孙。","notes":[]},{"n":7,"t":"玛拿西的地界是从亚设起，到示剑前面的密米他，往右到隐．他普亚居民之地。","notes":["“往右”或译“往南”。"]},{"n":8,"t":"他普亚地归于玛拿西，只是玛拿西边界的他普亚城却归于以法莲子孙。","notes":[]},{"n":9,"t":"这地界从那里下到加拿河。河南边的城镇虽然在玛拿西境内，却是属于以法莲的。玛拿西的地界是在河的北边直通到海为止。","notes":[]},{"n":10,"t":"南边属于以法莲，北边属于玛拿西，以海为界；北边达到亚设，东边达到以萨迦。","notes":[]},{"n":11,"t":"玛拿西在以萨迦和亚设境内，有伯．善和所属的乡镇，以伯莲和所属的乡镇，多珥和所属乡镇的居民；还有隐．多珥和所属乡镇的居民，他纳和所属乡镇的居民，米吉多和所属乡镇的居民，共三个山冈。","notes":["“共三个山冈”：原文另译“第三个是山冈”。"]},{"n":12,"t":"只是玛拿西的子孙不能赶出这些城镇的居民，迦南人仍坚持住在那地。","notes":[]},{"n":13,"t":"以色列人强盛的时候，就叫迦南人做苦工，没有把他们全然赶走。","notes":[]},{"n":14,"t":"约瑟的子孙对约书亚说：“耶和华到如今这样赐福给我，我百姓众多，你为什么只给我抽一签，分一份的土地为业呢？”","notes":[],"heads":["约瑟的子孙要求更多土地"]},{"n":15,"t":"约书亚对他们说：“如果你百姓众多，而以法莲山区太窄小，那么你可以上比利洗人和利乏音人之地的树林中，在那里开垦。”","notes":[]},{"n":16,"t":"约瑟的子孙说：“那山区容不下我们，而且住平原的迦南人，就是住伯．善和所属的乡镇，以及住在耶斯列平原的人，都有铁的战车。”","notes":[]},{"n":17,"t":"约书亚对约瑟家，就是以法莲和玛拿西人，说：“你百姓众多，并且强大，不可只有一签而已。","notes":[]},{"n":18,"t":"那山区也要归你，虽然是树林，你可以去开垦，边缘之地也必归你。迦南人纵然强盛，有铁的战车，你也能把他们赶出去。”","notes":[]}]},"18":{"heading":"其余支派的土地分配","verses":[{"n":1,"t":"以色列全会众都聚集在示罗，把会幕设立在那里。那地已经被他们征服了。","notes":[]},{"n":2,"t":"以色列人中剩下七个支派还没有分得他们的地业。","notes":[]},{"n":3,"t":"约书亚对以色列人说：“耶和华－你们列祖的神所赐给你们的地，你们耽延不去得，要到几时呢？","notes":[]},{"n":4,"t":"你们每支派要选三个人，我好派他们去，他们要起身走遍那地，按照各支派应得的地业写明，然后回到我这里来。","notes":[]},{"n":5,"t":"他们要把地分成七份。犹大在南方，住在他的境内。约瑟家在北方，住在他们的境内。","notes":[]},{"n":6,"t":"你们把地划成七份之后，就要把所写的带到我这里来。我要在耶和华－我们的神面前，为你们抽签。","notes":[]},{"n":7,"t":"利未人在你们中间没有分得地业，因为耶和华祭司的职分就是他们的产业。迦得支派、吕便支派和玛拿西半支派已经在约旦河东得了地业，是耶和华的仆人摩西给他们的。”","notes":[]},{"n":8,"t":"那些去划地的人起来正要去的时候，约书亚吩咐他们说：“你们去走遍那地，把地划分以后，就回到我这里来。我要在示罗这里，在耶和华面前为你们抽签。”","notes":[]},{"n":9,"t":"那些人就去了，走遍那地，按照城镇把地划成七份，写在册上，回到示罗营中约书亚那里。","notes":["“回到”：七十士译本是“带回到”。"]},{"n":10,"t":"约书亚就在示罗，在耶和华面前为他们抽签。约书亚按照以色列人的支派，在那里把地分给他们。","notes":[]},{"n":11,"t":"便雅悯支派，按着宗族抽签所得之地，是在犹大子孙和约瑟子孙之间。","notes":[],"heads":["分给便雅悯的土地"]},{"n":12,"t":"他们北边的地界是从约旦河起，上到耶利哥斜坡的北边，再往西上到山区，直到伯．亚文的旷野。","notes":[]},{"n":13,"t":"这地界从那里往南经过路斯，直到路斯的斜坡，路斯就是伯特利，又下到亚他录．亚达，直到下伯．和仑南边的山。","notes":[]},{"n":14,"t":"这地界往西延伸，又转向南，从伯．和仑南边对面的山，直通到犹大人的城基列．巴力，基列．巴力就是基列．耶琳。这就是西边的地界。","notes":[]},{"n":15,"t":"南边是从基列．耶琳的顶端为起点，这地界往西通到尼弗多亚水泉，","notes":["“这地界往西”：七十士译本是“这地界向迦萨”。"]},{"n":16,"t":"这地界又下到欣嫩子谷对面山的边缘，就是利乏音谷的北边；又下到欣嫩谷，沿着耶布斯斜坡的南边，下到隐．罗结；","notes":[]},{"n":17,"t":"又往北转弯，通到隐．示麦，直到亚都冥斜坡对面的基利绿，又下到吕便之子波罕的磐石，","notes":[]},{"n":18,"t":"又往北经过亚拉巴对面的斜坡，下到亚拉巴。","notes":["“亚拉巴对面的斜坡”：七十士译本是“伯．亚拉巴的斜坡”。"]},{"n":19,"t":"这地界又经过伯．曷拉斜坡的北边，直通到盐海的北湾，就是约旦河的南端为止。这就是南边的地界。","notes":[]},{"n":20,"t":"东边的地界是约旦河。这是便雅悯人按着宗族，照着他们四围的边界所得的地业。","notes":[]},{"n":21,"t":"便雅悯支派按着宗族所得的城镇就是：耶利哥、伯．曷拉、伊麦．基悉、","notes":[],"heads":["便雅悯分得的城镇"]},{"n":22,"t":"伯．亚拉巴、洗玛脸、伯特利、","notes":[]},{"n":23,"t":"亚文、巴拉、俄弗拉、","notes":[]},{"n":24,"t":"基法．阿摩尼、俄弗尼和迦巴，共十二座城，以及所属的村庄；","notes":[]},{"n":25,"t":"又有基遍、拉玛、比录、","notes":[]},{"n":26,"t":"米斯巴、基非拉、摩撒、","notes":[]},{"n":27,"t":"利坚、伊利毗勒、他拉拉、","notes":[]},{"n":28,"t":"洗拉、以利弗、耶布斯，耶布斯就是耶路撒冷，基比亚、基列，共十四座城，以及所属的村庄。这是便雅悯人按着宗族所得的地业。","notes":[]}]},"19":{"heading":"分给西缅的土地","verses":[{"n":1,"t":"第二签是西缅，是西缅支派的人按着宗族抽出的，他们所得的地业是在犹大人地业的中间。","notes":[]},{"n":2,"t":"他们所得为业之地是：别是巴，或名示巴，摩拉大、","notes":[]},{"n":3,"t":"哈萨．书亚、巴拉、以森、","notes":[]},{"n":4,"t":"伊勒多腊、比土力、何珥玛、","notes":[]},{"n":5,"t":"洗革拉、伯．玛加博、哈萨．苏撒、","notes":[]},{"n":6,"t":"伯．利巴勿、沙鲁险，共十三座城，还有所属的村庄；","notes":[]},{"n":7,"t":"又有亚因、利门、以帖、亚珊，共四座城，还有所属的村庄；","notes":[]},{"n":8,"t":"以及这些城镇周围一切的村庄，直到巴拉．比珥，就是尼革夫的拉玛。这是西缅支派的人按着宗族所得的地业。","notes":[]},{"n":9,"t":"西缅人的地业取自犹大人的土地，因为犹大人所得的份过多，所以西缅人从犹大人的地业中取了地业。","notes":[]},{"n":10,"t":"第三签是西布伦人按着宗族抽到的。他们地业的边界延伸到撒立。","notes":[],"heads":["分给西布伦的土地"]},{"n":11,"t":"他们的地界往西，上到玛拉拉，达到大巴设，又达到约念前面的河。","notes":[]},{"n":12,"t":"又从撒立往东转到向日出的方向，经过吉斯绿．他泊的边界，到大比拉，又上到雅非亚。","notes":[]},{"n":13,"t":"又从那里往东，经过迦特．希弗，到以特．加汛，通到临门，延伸到尼亚。","notes":[]},{"n":14,"t":"这地界在北边绕过尼亚，到哈拿顿，直通到伊弗他．伊勒谷，","notes":[]},{"n":15,"t":"包括加他、拿哈拉、伸仑、以大拉、伯利恒，共十二座城，还有所属的村庄。","notes":[]},{"n":16,"t":"这些城镇和所属的村庄是西布伦人按着宗族所得的地业。","notes":[]},{"n":17,"t":"第四签是以萨迦，是以萨迦人按着宗族抽出的。","notes":[],"heads":["分给以萨迦的土地"]},{"n":18,"t":"他们的地界是到耶斯列、基苏律、书念、","notes":[]},{"n":19,"t":"哈弗连、示按、亚拿哈拉、","notes":[]},{"n":20,"t":"拉璧、基善、亚别、","notes":[]},{"n":21,"t":"利篾、隐．干宁、隐．哈大、伯．帕薛。","notes":[]},{"n":22,"t":"这地界达到他泊、沙哈洗玛、伯．示麦，他们的地界直通到约旦河为止，共十六座城，还有所属的村庄。","notes":[]},{"n":23,"t":"这些城镇和所属的村庄是以萨迦支派的人按着宗族所得的地业。","notes":[]},{"n":24,"t":"第五签是亚设支派的人按着宗族抽出的。","notes":[],"heads":["分给亚设的土地"]},{"n":25,"t":"他们的地界是黑甲、哈利、比田、押煞、","notes":[]},{"n":26,"t":"亚拉米勒、亚末、米沙勒，往西达到迦密，又到希曷．立纳，","notes":[]},{"n":27,"t":"又转到向日出方向的伯．大衮，达到细步纶；又往北到伊弗他．伊勒谷，到伯．以墨和尼业，也通到迦步勒的左边，","notes":["“左边”或译“北边”。"]},{"n":28,"t":"又到义伯仑、利合、哈们、加拿，直到西顿大城。","notes":[]},{"n":29,"t":"这地界转到拉玛，直到坚固的推罗城。这地界又转到何萨，靠近亚革悉一带的地方，直通到海为止。","notes":["“靠近亚革悉一带的地方”：原文另译“亚革悉、玛哈拉”。"]},{"n":30,"t":"又有乌玛、亚弗、利合，共二十二座城，还有所属的村庄。","notes":[]},{"n":31,"t":"这些城镇和所属的村庄是亚设支派的人按着宗族所得的地业。","notes":[]},{"n":32,"t":"第六签是拿弗他利人，是拿弗他利人按着宗族抽出的。","notes":[],"heads":["分给拿弗他利的土地"]},{"n":33,"t":"他们的地界是从希利弗，从撒拿音的橡树、亚大米．尼吉和雅比聂，直到拉共，直通到约旦河为止。","notes":[]},{"n":34,"t":"这地界往西转到亚斯纳．他泊，从那里通到户割，南边达到西布伦，西边达到亚设，向日出的方向达到约旦河的犹大。","notes":[]},{"n":35,"t":"坚固的城有西丁、侧耳、哈末、拉甲、基尼烈、","notes":[]},{"n":36,"t":"亚大玛、拉玛、夏琐、","notes":[]},{"n":37,"t":"基低斯、以得来、隐．夏琐、","notes":[]},{"n":38,"t":"以利稳、密大．伊勒、和琏、伯．亚纳、伯．示麦，共十九座城，还有所属的村庄。","notes":[]},{"n":39,"t":"这些城镇和所属的村庄是拿弗他利支派的人按着宗族所得的地业。","notes":[]},{"n":40,"t":"但支派，按着宗族，抽到第七签。","notes":[],"heads":["分给但的土地"]},{"n":41,"t":"他们地业的边界是琐拉、以实陶、伊珥．示麦、","notes":[]},{"n":42,"t":"沙拉宾、亚雅仑、伊提拉、","notes":[]},{"n":43,"t":"以伦、亭拿、以革伦、","notes":[]},{"n":44,"t":"伊利提基、基比顿、巴拉、","notes":[]},{"n":45,"t":"伊胡得、比尼．比拉、迦特．临门、","notes":[]},{"n":46,"t":"美．耶昆、拉昆，以及约帕对面的地界。","notes":[]},{"n":47,"t":"当但的子孙失去他们疆土的时候，就上去攻取利善，用刀击杀城中的人，得了那城，住在城中，以他们祖先但的名字将利善改名为但。","notes":[]},{"n":48,"t":"这些城镇和所属的村庄是但支派的人按着宗族所得的地业。","notes":[]},{"n":49,"t":"以色列人按着疆土完成了地业的分配，就在他们中间把地给嫩的儿子约书亚为业。","notes":[],"heads":["给约书亚的城"]},{"n":50,"t":"他们照着耶和华的指示，把约书亚所要的城，就是以法莲山区的亭拿．西拉给了他。约书亚修建那城，住在城中。","notes":[]},{"n":51,"t":"这就是以利亚撒祭司和嫩的儿子约书亚，以及以色列人各支派父系的领袖，在示罗会幕的门口，耶和华面前抽签所分的地业。这样， 他们就完成了分地的事。","notes":[]}]},"20":{"heading":"设立逃城","verses":[{"n":1,"t":"耶和华吩咐约书亚说：","notes":[]},{"n":2,"t":"“你吩咐以色列人说：‘你们要照我藉摩西所吩咐你们的，为自己设立逃城，","notes":[]},{"n":3,"t":"使那无意中误杀人的，可以逃到那里。这些要作为你们逃避报血仇者的城。","notes":[]},{"n":4,"t":"杀人者要逃到这些城中的一座，站在城门口，把他的事情陈诉给那城的长老听。他们就要接他入城，给他地方，让他住在他们中间。","notes":[]},{"n":5,"t":"若是报血仇者追上了他，长老不可把他交在报血仇者的手里，因为他是无意中杀了邻舍的，并非过去彼此之间有仇恨。","notes":[]},{"n":6,"t":"他要住在那城里，直到他站在会众面前受审判；等到当时的大祭司死后，杀人者才可以回到本城本家，就是他所逃出来的那城。’”","notes":[]},{"n":7,"t":"于是，以色列人划分拿弗他利山区加利利的基低斯、以法莲山区的示剑和犹大山区的基列．亚巴，基列．亚巴就是希伯仑。","notes":[]},{"n":8,"t":"他们在约旦河的另一边，就是耶利哥的东边，从吕便支派中，在旷野的平原设立比悉，从迦得支派中设立基列的拉末，从玛拿西支派中设立巴珊的哥兰。","notes":[]},{"n":9,"t":"这都是为以色列众人和在他们中间寄居的外人所指定的城镇，使凡误杀人者可以逃到那里，不至于死在报血仇者的手中，直到他站在会众面前受审判。","notes":["“受审判”是根据七十士译本，原文没有。"]}]},"21":{"heading":"利未人的城","verses":[{"n":1,"t":"利未人的众族长近前来到以利亚撒祭司和嫩的儿子约书亚，以及以色列人各支派父系的领袖那里，","notes":[]},{"n":2,"t":"在迦南地的示罗对他们说：“从前耶和华曾藉着摩西吩咐给我们城镇居住，以及城镇的郊外供我们牧养牲畜。”","notes":[]},{"n":3,"t":"于是以色列人照耶和华的指示，从自己的地业中，把这些城镇和城镇的郊外给了利未人。","notes":[]},{"n":4,"t":"哥辖族抽了签。利未人中亚伦祭司的子孙，从犹大支派、西缅支派、便雅悯支派的地业中，抽签得了十三座城。","notes":[]},{"n":5,"t":"哥辖其余的子孙，从以法莲支派、但支派、玛拿西半支派宗族的地业中，抽签得了十座城。","notes":[]},{"n":6,"t":"革顺的子孙，从以萨迦支派、亚设支派、拿弗他利支派、住巴珊的玛拿西半支派宗族的地业中，抽签得了十三座城。","notes":[]},{"n":7,"t":"米拉利的子孙，按着宗族，从吕便支派、迦得支派、西布伦支派的地业中，得了十二座城。","notes":[]},{"n":8,"t":"以色列人照耶和华藉摩西所吩咐的，把这些城镇和城镇的郊外，抽签给利未人。","notes":[]},{"n":9,"t":"他们从犹大支派和西缅支派的地业中，给了以下所记名字的各城，","notes":[]},{"n":10,"t":"就是给利未人哥辖宗族的亚伦子孙，因为他们抽到第一签：","notes":[]},{"n":11,"t":"把犹大山区的基列．亚巴，就是希伯仑，和四围的郊野给了他们。亚巴是亚衲族的祖先。","notes":[]},{"n":12,"t":"但是，这城的田地和所属的村庄却给了耶孚尼的儿子迦勒为业。","notes":[]},{"n":13,"t":"他们把希伯仑，就是误杀人的逃城和城的郊外，给了亚伦祭司的子孙；又给了立拿和城的郊外、","notes":[]},{"n":14,"t":"雅提珥和城的郊外、以实提莫和城的郊外、","notes":[]},{"n":15,"t":"何仑和城的郊外、底璧和城的郊外、","notes":[]},{"n":16,"t":"亚因和城的郊外、淤他和城的郊外，以及伯．示麦和城的郊外，共九座城，都是从这二支派中分出来的。","notes":[]},{"n":17,"t":"又从便雅悯支派的地业中给了基遍和城的郊外、迦巴和城的郊外、","notes":[]},{"n":18,"t":"亚拿突和城的郊外，以及亚勒们和城的郊外，共四座城。","notes":[]},{"n":19,"t":"亚伦子孙作祭司的共有十三座城，以及城的郊外。","notes":[]},{"n":20,"t":"利未人哥辖的宗族，就是哥辖其余的子孙，抽签所得的城是从以法莲支派来的。","notes":[]},{"n":21,"t":"他们把以法莲山区的示剑，就是误杀人的逃城和城的郊外给了哥辖其余的子孙；又给了基色和城的郊外、","notes":[]},{"n":22,"t":"基伯先和城的郊外，以及伯．和仑和城的郊外，共四座城。","notes":[]},{"n":23,"t":"又从但支派的地业中给了伊利提基和城的郊外、基比顿和城的郊外、","notes":[]},{"n":24,"t":"亚雅仑和城的郊外，以及迦特．临门和城的郊外，共四座城。","notes":[]},{"n":25,"t":"又从玛拿西半支派的地业中给了他纳和城的郊外，以及迦特．临门和城的郊外，共两座城。","notes":[]},{"n":26,"t":"哥辖其余的子孙共有十座城，以及城的郊外。","notes":[]},{"n":27,"t":"利未人宗族中革顺的子孙，从玛拿西半支派的地业中所得的是巴珊的哥兰，就是误杀人的逃城和城的郊外，以及比．施提拉和城的郊外，共两座城。","notes":[]},{"n":28,"t":"从以萨迦支派的地业中所得的是基善和城的郊外、大比拉和城的郊外、","notes":[]},{"n":29,"t":"耶末和城的郊外，以及隐．干宁和城的郊外，共四座城。","notes":[]},{"n":30,"t":"从亚设支派的地业中所得的是米沙勒和城的郊外、押顿和城的郊外、","notes":[]},{"n":31,"t":"黑甲和城的郊外，以及利合和城的郊外，共四座城。","notes":[]},{"n":32,"t":"从拿弗他利支派的地业中所得的是加利利的基低斯，就是误杀人的逃城和城的郊外、哈末．多珥和城的郊外，以及加珥坦和城的郊外，共三座城。","notes":[]},{"n":33,"t":"革顺人按着宗族共有十三个城，以及城的郊外。","notes":[]},{"n":34,"t":"其余的利未人，就是米拉利的子孙，按着宗族从西布伦支派的地业中所得的是约念和城的郊外、加珥他和城的郊外、","notes":[]},{"n":35,"t":"丁拿和城的郊外，以及拿哈拉和城的郊外，共四座城。","notes":[]},{"n":36,"t":"从吕便支派的地业中所得的是比悉和城的郊外、雅杂和城的郊外、","notes":[]},{"n":37,"t":"基底莫和城的郊外，以及米法押和城的郊外，共四座城。","notes":[]},{"n":38,"t":"从迦得支派的地业中所得的是基列的拉末，就是误杀人的逃城和城的郊外、玛哈念和城的郊外、","notes":[]},{"n":39,"t":"希实本和城的郊外，以及雅谢和城的郊外，共四座城。","notes":[]},{"n":40,"t":"利未宗族其余的人，就是米拉利的子孙，按着宗族抽签所得的，共十二座城。","notes":[]},{"n":41,"t":"利未人在以色列人的地业中所得的城，共四十八个，还有城的郊外。","notes":[]},{"n":42,"t":"这些城的四围都有郊野，每个城都是如此。","notes":[]},{"n":43,"t":"这样，耶和华将从前向他们列祖起誓要给他们的全地赐给以色列人，他们就得了为业，住在其中。","notes":[],"heads":["以色列人得地为业"]},{"n":44,"t":"耶和华照着向他们列祖起誓所应许的一切，赐给他们全境安宁。他们所有的仇敌，没有一个能在他们面前站立得住。耶和华把所有仇敌都交在他们手中。","notes":[]},{"n":45,"t":"耶和华应许赐福给以色列家的话，一句都没有落空，全都应验了。","notes":[]}]},"22":{"heading":"东岸的支派回去","verses":[{"n":1,"t":"此后，约书亚召了吕便人、迦得人和玛拿西半支派的人来，","notes":[]},{"n":2,"t":"对他们说：“耶和华的仆人摩西所吩咐你们的，你们都遵守了；我吩咐你们的话，你们也都听从了。","notes":[]},{"n":3,"t":"你们这许多日子，都没有撇弃你们的弟兄，直到今日，并且遵守了耶和华你们神所吩咐的命令。","notes":[]},{"n":4,"t":"如今耶和华－你们的神已经照着他所应许的，使你们的弟兄得享安宁。你们现在可以返回自己的帐棚，回到耶和华的仆人摩西在约旦河东所赐给你们为业之地。","notes":[]},{"n":5,"t":"只是务要谨守遵行耶和华的仆人摩西所吩咐你们的诫命和律法，爱耶和华－你们的神，行他一切的道，守他的诫命，紧紧跟随他，尽心尽性事奉他。”","notes":[]},{"n":6,"t":"于是约书亚为他们祝福，送他们回去，他们就回到自己的帐棚去了。","notes":[]},{"n":7,"t":"摩西在巴珊曾把地业分给玛拿西的半支派；然后约书亚在约旦河的西岸，在他们弟兄中，又把地业分给玛拿西的另外半支派。约书亚送他们回帐棚的时候，为他们祝福，","notes":[]},{"n":8,"t":"对他们说：“你们要把许多财物，许多牲畜，和金、银、铜、铁，以及许多衣服，带回你们的帐棚去，要把你们从仇敌夺来的东西分给你们的众弟兄。”","notes":[]},{"n":9,"t":"于是吕便人、迦得人、玛拿西半支派的人从迦南地的示罗起行，离开以色列人，回到他们已得为业的基列地，就是他们照耶和华藉摩西所吩咐而得的。","notes":[]},{"n":10,"t":"吕便人、迦得人和玛拿西半支派的人到了迦南地的约旦河一带地方，就在约旦河那里筑了一座坛，一座高大壮观的坛。","notes":[],"heads":["约旦河旁的祭坛"]},{"n":11,"t":"以色列人听见了，说：“看哪，吕便人、迦得人、玛拿西半支派的人在迦南地对面，约旦河一带地方，以色列人的境内，筑了一座坛。”","notes":[]},{"n":12,"t":"以色列人一听见，全会众的以色列人就聚集在示罗，要上去攻打他们。","notes":[]},{"n":13,"t":"以色列人派以利亚撒祭司的儿子非尼哈，往基列地，到吕便人、迦得人和玛拿西半支派的人那里。","notes":[]},{"n":14,"t":"和他同去的还有十个领袖，以色列每个支派在父家中各派一个领袖，这些人每一个在以色列族系中都是父家的领袖。","notes":[]},{"n":15,"t":"他们来到基列地，到吕便人、迦得人和玛拿西半支派的人那里，对他们说：","notes":[]},{"n":16,"t":"“耶和华全会众这样说：‘你们今日离弃耶和华不跟从他，干犯以色列的神，悖逆耶和华，为自己筑了一座坛，你们所犯的是何等的罪！","notes":[]},{"n":17,"t":"从前我们在毗珥犯的罪孽，导致瘟疫临到耶和华的会众，甚至到今日都还没有洗净，这还算小事吗？","notes":[]},{"n":18,"t":"你们今日竟然离弃耶和华不跟从他！你们今日既然悖逆耶和华，明日他必向以色列全会众发怒。","notes":[]},{"n":19,"t":"若你们认为所得为业之地不洁净，可以过来，到耶和华之地，就是耶和华的帐幕所居住之地，在我们中间得地业。你们却不可悖逆耶和华，也不可背叛我们，在耶和华－我们神的坛以外为自己筑坛。","notes":[]},{"n":20,"t":"从前谢拉的曾孙亚干岂不是在那当灭的物上犯了罪，导致愤怒临到以色列全会众吗？死在他所犯的罪中的，不只是他一个人而已！’”","notes":[]},{"n":21,"t":"于是吕便人、迦得人、玛拿西半支派的人回答以色列族系的领袖，说：","notes":[]},{"n":22,"t":"“大能者神耶和华！大能者神耶和华！他已知道，愿以色列人也知道，我们若有悖逆的行为，或是干犯耶和华，你今日就不要让我们活着！","notes":[]},{"n":23,"t":"若我们为自己筑坛，离弃耶和华不跟从他，或将燔祭、素祭、平安祭献在坛上，愿耶和华亲自追究。","notes":[]},{"n":24,"t":"不是这样！我们做这事的原因是惧怕将来你们的子孙对我们的子孙说：‘你们与耶和华－以色列的神有什么关系呢？","notes":[]},{"n":25,"t":"因为耶和华以约旦河作我们和你们吕便人、迦得人的交界，所以你们在耶和华里无份。’这样，你们的子孙就使我们的子孙不再敬畏耶和华了。","notes":[]},{"n":26,"t":"因此我们说：‘不如为自己筑一座坛，不是为献燔祭，也不是为献别样的祭，","notes":[]},{"n":27,"t":"而是为你我之间和后代子孙之间作证据，好使我们也在耶和华面前献我们的燔祭、平安祭和别样的祭来事奉他，免得你们的子孙将来对我们的子孙说，你们在耶和华里无份。’","notes":[]},{"n":28,"t":"所以我们说：‘将来他们若对我们，或对我们的子孙这样说，我们就可以回答说：你们看，我们列祖所筑的坛是耶和华坛的样式，这并不是为献燔祭，也不是为献别样的祭，而是作为你们和我们之间的证据。’","notes":[]},{"n":29,"t":"除了耶和华－我们神帐幕前的坛以外，我们绝没有意思要为着献燔祭、素祭和别样的祭而另外筑一座坛，悖逆耶和华，今日离弃不跟从他。”","notes":[]},{"n":30,"t":"非尼哈祭司与会众中的领袖，就是与他同来那些以色列族系的领袖，听见吕便人、迦得人、玛拿西人所说的话，就都看为美。","notes":[]},{"n":31,"t":"以利亚撒祭司的儿子非尼哈对吕便人、迦得人、玛拿西人说：“今日我们知道耶和华在我们中间，因为你们没有向他犯悖逆的罪。现在你们把以色列人从耶和华的手中救出来了。”","notes":[]},{"n":32,"t":"以利亚撒祭司的儿子非尼哈与众领袖离开了吕便人和迦得人，从基列地回迦南地，到了以色列人那里，就把这事向他们回报。","notes":[]},{"n":33,"t":"以色列人看这事为美；以色列人就称颂神，不再说要上去攻打吕便人和迦得人，毁坏他们所住的地了。","notes":[]},{"n":34,"t":"吕便人和迦得人给这坛起了名，因为这坛在我们之间见证耶和华是神。","notes":[]}]},"23":{"heading":"约书亚的遗言","verses":[{"n":1,"t":"耶和华使以色列人从四围所有的仇敌中得享安宁，已经有很多日子了。约书亚年纪老迈，","notes":[]},{"n":2,"t":"就召了全以色列的众长老、领袖、审判官和官长来，对他们说：“我年纪已经老迈。","notes":[]},{"n":3,"t":"耶和华－你们的神因你们的缘故向这些国家所做的一切，你们都亲眼看见了，那为你们作战的是耶和华－你们的神。","notes":[]},{"n":4,"t":"看，我已经把所剩下的列国，连同从约旦河起到大海日落的方向，我所剪除的列国，都抽签分给你们各支派为业了。","notes":[]},{"n":5,"t":"耶和华－你们的神必将他们从你们面前赶出去，使他们离开你们，你们就必得他们的地为业，正如耶和华－你们的神向你们所应许的。","notes":[]},{"n":6,"t":"你们要大大壮胆，谨守遵行写在摩西律法书上的一切话，不可偏离左右。","notes":[]},{"n":7,"t":"不可与你们中间所剩下的这些国家往来。你们不可提他们神明的名，不可指着它们起誓，不可事奉它们，也不可敬拜它们。","notes":[]},{"n":8,"t":"只要紧紧跟随耶和华－你们的神，就像你们直到今日所做的。","notes":[]},{"n":9,"t":"因为耶和华已经把又大又强的列国从你们面前赶出；直到今日，没有一人能在你们面前站立得住。","notes":[]},{"n":10,"t":"你们一人必追赶千人，因为耶和华－你们的神照他向你们所应许的，为你们作战。","notes":[]},{"n":11,"t":"你们要分外谨慎，爱耶和华－你们的神。","notes":[]},{"n":12,"t":"你们若断然转离，紧紧跟随你们中间所剩下的这些国家，彼此结亲，互相往来，","notes":[]},{"n":13,"t":"就要确实知道，耶和华－你们的神必不再将他们从你们面前赶出；他们却要成为你们的罗网、圈套、肋上的鞭、眼中的刺，直到你们在耶和华－你们神所赐的这美地上灭亡。","notes":[]},{"n":14,"t":"“看哪，我今日要走世人必走的路了。你们要一心一意知道，耶和华－你们神所应许要赐给你们的一切福气，没有一件落空，都应验在你们身上了。","notes":[]},{"n":15,"t":"耶和华－你们的神所应许的一切福气怎样临到你们身上，耶和华也必照样使各样灾祸临到你们身上，直到他把你们从耶和华－你们神所赐给你们的这美地上除灭。","notes":[]},{"n":16,"t":"你们若违背耶和华－你们神吩咐你们所守的约，去事奉别神，敬拜它们，耶和华的怒气必向你们发作，使你们在他所赐给你们的美地上迅速灭亡。”","notes":[]}]},"24":{"heading":"约书亚在示剑最后的讲话","verses":[{"n":1,"t":"约书亚召集以色列的众支派到示剑，他召了以色列的长老、领袖、审判官和官长来；他们都站在神面前。","notes":[]},{"n":2,"t":"约书亚对众百姓说：“耶和华－以色列的神如此说：‘古时你们的列祖，就是亚伯拉罕和拿鹤的父亲他拉，住在大河那边事奉别神。","notes":[]},{"n":3,"t":"我将你们的祖宗亚伯拉罕从大河那边带出来，领他走遍迦南全地，又使他的子孙众多。我把以撒赐给他，","notes":[]},{"n":4,"t":"我又把雅各和以扫赐给以撒，将西珥山赐给以扫为业。但雅各和他的子孙下到埃及去了。","notes":[]},{"n":5,"t":"我差遣摩西和亚伦，照我在埃及中间所做的，降灾与埃及，然后把你们领出来。","notes":[]},{"n":6,"t":"我领你们的祖宗出埃及，你们就到了红海。埃及人带领战车骑兵，追赶你们的祖宗到红海。","notes":[]},{"n":7,"t":"你们的祖宗哀求耶和华，他就用黑暗把你们和埃及人隔开了，又使海水冲向埃及人，淹没他们。我在埃及所做的，你们都亲眼见过。你们在旷野住了很多日子。","notes":[]},{"n":8,"t":"我领你们到约旦河东亚摩利人所住之地。他们与你们争战，我把他们交在你们手中，你们就得了他们的地为业。我也在你们面前灭绝他们。","notes":[]},{"n":9,"t":"那时，摩押王西拨的儿子巴勒起来攻击以色列人，派人去召比珥的儿子巴兰来诅咒你们。","notes":[]},{"n":10,"t":"但我不愿听巴兰，所以他反而为你们连连祝福。这样，我救了你们脱离他的手。","notes":[]},{"n":11,"t":"你们过了约旦河，来到耶利哥。耶利哥人、亚摩利人、比利洗人、迦南人、赫人、革迦撒人、希未人、耶布斯人都与你们争战，我却把他们交在你们手里。","notes":[]},{"n":12,"t":"我派遣瘟疫在你们前面，将亚摩利人的两个王从你们面前赶出，并不是用你的刀，也不是用你的弓。","notes":["“瘟疫”或译“黄蜂”。"]},{"n":13,"t":"我赐给你们的地，不是你们开垦的；我赐给你们的城镇，不是你们建造的。你们却住在其中，又得吃那不是你们栽植的葡萄园和橄榄园的果子。’","notes":[]},{"n":14,"t":"“现在你们要敬畏耶和华，诚心诚意事奉他，除掉你们列祖在大河那边和在埃及事奉的神明，事奉耶和华。","notes":[]},{"n":15,"t":"若你们认为事奉耶和华不好，今日就可以选择所要事奉的：是你们列祖在大河那边所事奉的神明，或是你们所住这地亚摩利人的神明呢？至于我和我家，我们必定事奉耶和华。”","notes":[]},{"n":16,"t":"百姓回答说：“我们绝不离弃耶和华去事奉别神。","notes":[]},{"n":17,"t":"因为耶和华－我们的神曾领我们和我们的祖宗从埃及地为奴之家出来，在我们眼前行了那些大神迹，并在我们所行的一切路上，和所经过的各民族中保护了我们。","notes":[]},{"n":18,"t":"耶和华又把各民族和住此地的亚摩利人都从我们面前赶出去。所以，我们也必事奉耶和华，因为他是我们的神。”","notes":[]},{"n":19,"t":"约书亚对百姓说：“你们不能事奉耶和华，因为他是神圣的神，是忌邪的神，必不赦免你们的过犯罪恶。","notes":["“忌邪”：原文是“妒忌”，意思是“不容许有对立的神明”。"]},{"n":20,"t":"你们若离弃耶和华去事奉外邦的神明，耶和华在降福之后，必转而降祸给你们，把你们灭绝。”","notes":[]},{"n":21,"t":"百姓对约书亚说：“不，我们要事奉耶和华。”","notes":[]},{"n":22,"t":"约书亚对百姓说：“你们选择耶和华，要事奉他，你们自己作证吧！”他们说：“我们愿意作证。”","notes":[]},{"n":23,"t":"“现在，你们要除掉你们中间外邦的神明，专心归向耶和华－以色列的神。”","notes":[]},{"n":24,"t":"百姓对约书亚说：“我们必事奉耶和华－我们的神，听从他的话。”","notes":[]},{"n":25,"t":"那日，约书亚就与百姓立约，在示剑为他们制定律例典章。","notes":[]},{"n":26,"t":"约书亚把这些话写在神的律法书上，又拿一块大石头立在橡树下耶和华圣所的旁边。","notes":[]},{"n":27,"t":"约书亚对众百姓说：“看哪，这石头可以向我们作见证，因为它听见了耶和华所吩咐我们的一切话；这石头将向你们作见证，免得你们背叛你们的神。”","notes":[]},{"n":28,"t":"于是约书亚解散百姓，各自回到自己的地业去了。","notes":[]},{"n":29,"t":"这些事以后，耶和华的仆人，嫩的儿子约书亚死了，那时他一百一十岁。","notes":[],"heads":["约书亚和以利亚撒去世"]},{"n":30,"t":"以色列人把他葬在他自己地业的境内，以法莲山区的亭拿．西拉，在迦实山的北边。","notes":[]},{"n":31,"t":"约书亚在世的日子和他死了以后，那些知道耶和华为以色列所做一切事的长老还在世的时候，以色列人事奉耶和华。","notes":[]},{"n":32,"t":"以色列人把从埃及所带来约瑟的骸骨安葬在示剑，就是雅各从前用一百可锡塔向示剑的父亲哈抹的众子所买的那块地；这块地就成了约瑟子孙的产业。","notes":["“可锡塔”：古希伯来钱币单位；参“度量衡表”。"]},{"n":33,"t":"亚伦的儿子以利亚撒也死了，他们把他葬在他儿子非尼哈所得以法莲山区的小山上。","notes":["“小山上”或译“基比亚”。"]}]}},"JDG":{"1":{"heading":"犹大和西缅打败亚多尼．比色","verses":[{"n":1,"t":"约书亚死后，以色列人求问耶和华说：“我们中间谁当首先上去攻打迦南人，与他们争战呢？”","notes":[]},{"n":2,"t":"耶和华说：“犹大要先上去。看哪，我已将那地交在他手中。”","notes":[]},{"n":3,"t":"犹大对他哥哥西缅说：“请你同我上到我抽签所得之地，与迦南人争战；我也同你去你抽签所得之地。”于是西缅与他同去。","notes":[]},{"n":4,"t":"犹大就上去，耶和华把迦南人和比利洗人交在他们手中。他们在比色击杀了一万人。","notes":[]},{"n":5,"t":"他们在比色遇见亚多尼．比色，与他争战，击败了迦南人和比利洗人。","notes":[]},{"n":6,"t":"亚多尼．比色逃跑，他们追赶他，捉住他，砍断他大拇指和大脚趾。","notes":[]},{"n":7,"t":"亚多尼．比色说：“从前有七十个王，大拇指和大脚趾都被我砍断，在我桌子底下拾取零碎食物。现在神照着我所做的报应我了。”他们把亚多尼．比色带到耶路撒冷，他就死在那里。","notes":[]},{"n":8,"t":"犹大人攻打耶路撒冷，夺取了它，用刀杀城内的人，并且放火烧城。","notes":[]},{"n":9,"t":"后来犹大人下去，与住山区、尼革夫和低地的迦南人争战。","notes":["“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”；下同。"]},{"n":10,"t":"犹大去攻打住希伯仑的迦南人，杀了示筛、亚希幔、挞买。希伯仑从前名叫基列．亚巴。","notes":[]},{"n":11,"t":"犹大从那里去攻击底壁的居民。底壁从前名叫基列．西弗。","notes":[]},{"n":12,"t":"迦勒说：“谁能攻打基列．西弗，夺取那城，我就把我女儿押撒嫁给他。”","notes":[]},{"n":13,"t":"迦勒的弟弟基纳斯的儿子俄陀聂夺取了那城，迦勒就把女儿押撒嫁给他。","notes":[]},{"n":14,"t":"押撒来的时候，催促丈夫向她父亲要一块田。押撒一下驴，迦勒就对她说：“你要什么？”","notes":["“催促丈夫”：七十士译本是“俄陀聂催促她”。"]},{"n":15,"t":"她对迦勒说：“求你赐我福分；你既然把尼革夫给了我，求你也给我水泉。”迦勒就把上泉和下泉都赐给她。","notes":[]},{"n":16,"t":"摩西的岳父是基尼人，他的子孙与犹大人一起上到棕树城，往亚拉得以南的犹大旷野去，住在百姓当中。","notes":["“亚拉得以南的犹大旷野”：七十士译本是“犹大南方亚拉得斜坡下的旷野”。","“在百姓当中”有古译本是“在亚玛力人当中”；另有古译本是“亚玛力人去住在他们当中”。"],"heads":["犹大和便雅悯的胜利"]},{"n":17,"t":"犹大和他哥哥西缅同去，击杀了住洗法的迦南人，将城彻底毁灭。因此，那城名叫何珥玛。","notes":[]},{"n":18,"t":"犹大攻取了迦萨和所属的领土，亚实基伦和所属的领土，以革伦和所属的领土。","notes":[]},{"n":19,"t":"耶和华与犹大同在，犹大取得了山区，却不能赶出平原的居民，因为他们有铁的战车。","notes":[]},{"n":20,"t":"以色列人照摩西所说的，把希伯仑给了迦勒。迦勒从那里赶出亚衲的三支后裔。","notes":[]},{"n":21,"t":"至于住耶路撒冷的耶布斯人，便雅悯人没有把他们赶出。于是，耶布斯人与便雅悯人同住在耶路撒冷，直到今日。","notes":[]},{"n":22,"t":"约瑟家也上到伯特利去，耶和华与他们同在。","notes":[],"heads":["以法莲和玛拿西攻取伯特利"]},{"n":23,"t":"约瑟家去窥探伯特利，那城起先名叫路斯。","notes":[]},{"n":24,"t":"探子看见一个人从城里出来，就对他说：“请你把进城的路指示我们，我们会厚待你。”","notes":[]},{"n":25,"t":"那人把进城的路指示他们。他们就用刀击杀了城中的居民，却放走那人和他的全家。","notes":[]},{"n":26,"t":"那人往赫人之地去，建造了一座城，起名叫路斯。那城到如今还叫这名。","notes":[]},{"n":27,"t":"玛拿西没有赶出伯˙善和所属乡镇的居民，他纳和所属乡镇的居民，多珥和所属乡镇的居民，以伯莲和所属乡镇的居民，米吉多和所属乡镇的居民；迦南人仍坚持住在这地。","notes":["“乡镇”：原文直译“女子们”；本卷书下同。"],"heads":["以色列未赶出的民"]},{"n":28,"t":"以色列强盛的时候，就叫迦南人做苦工，没有把他们全然赶走。","notes":[]},{"n":29,"t":"以法莲没有赶出住基色的迦南人。于是迦南人仍住在基色，在以法莲中间。","notes":[]},{"n":30,"t":"西布伦没有赶出基伦的居民和拿哈拉的居民。于是迦南人仍住在西布伦中间，成了服劳役的人。","notes":[]},{"n":31,"t":"亚设没有赶出亚柯的居民和西顿的居民，以及亚黑拉、亚革悉、黑巴、亚弗革和利合的居民。","notes":[]},{"n":32,"t":"亚设人因为没有赶出那地的居民迦南人，就住在他们中间。","notes":[]},{"n":33,"t":"拿弗他利没有赶出伯˙示麦和伯˙亚纳的居民。于是拿弗他利就住在那地的居民迦南人中，而伯˙示麦和伯˙亚纳的居民却成了为他们服劳役的人。","notes":[]},{"n":34,"t":"亚摩利人强逼但人住在山区，不准他们下到平原。","notes":[]},{"n":35,"t":"亚摩利人仍坚持住在希烈山、亚雅仑和沙宾；然而约瑟家权势强盛的时候，他们成为服劳役的人。","notes":[]},{"n":36,"t":"亚摩利人的地界是从亚克拉滨斜坡，从西拉延伸而上。","notes":["“亚摩利人”：七十士译本的一些抄本是“亚摩利人即以东人”。"]}]},"2":{"heading":"耶和华的使者在波金","verses":[{"n":1,"t":"耶和华的使者从吉甲上到波金，说：“我领你们从埃及上来，带你们到我向你们列祖起誓应许之地。我曾说：‘我永不废弃我与你们的约。","notes":[]},{"n":2,"t":"你们不可与这地的居民立约，要拆毁他们的祭坛。’你们竟没有听从我的话。你们为何这样做呢！","notes":[]},{"n":3,"t":"因此我说：‘我必不将他们从你们面前赶出。他们必作你们肋下的荆棘，他们的神明必成为你们的圈套。’”","notes":["“肋下的荆棘”：原文是“肋旁”；原文另译“敌人”。"]},{"n":4,"t":"耶和华的使者向以色列众人说这些话的时候，百姓放声大哭。","notes":[]},{"n":5,"t":"于是他们给那地方起名叫波金，并在那里向耶和华献祭。","notes":["“波金”意思是“哭”。"]},{"n":6,"t":"约书亚解散百姓，以色列人回到自己的地业，占各自的地。","notes":[],"heads":["约书亚去世"]},{"n":7,"t":"约书亚在世的日子和他死了以后，那些见过耶和华为以色列所做一切大事的长老还在世的时候，百姓都事奉耶和华。","notes":[]},{"n":8,"t":"耶和华的仆人，嫩的儿子约书亚死了，那时他一百一十岁。","notes":[]},{"n":9,"t":"以色列人把他葬在他自己地业的境内，以法莲山区的亭拿．希烈，在迦实山的北边。","notes":[]},{"n":10,"t":"那世代的人也都归到自己的列祖。后来兴起的另一世代不认识耶和华，也不知道他为以色列所做的事。","notes":[]},{"n":11,"t":"以色列人行耶和华眼中看为恶的事，去事奉诸巴力。","notes":[],"heads":["以色列离弃耶和华"]},{"n":12,"t":"他们离弃领他们出埃及地的耶和华－他们列祖的神，去随从别神，就是四围列国的神明，向它们叩拜，惹耶和华发怒。","notes":[]},{"n":13,"t":"他们离弃了耶和华，去事奉巴力和亚斯她录。","notes":[]},{"n":14,"t":"耶和华的怒气向以色列发作，把他们交在抢夺他们的人手中，又把他们交给四围仇敌的手中，以致他们在仇敌面前再也不能站立得住。","notes":["“交给<ins>.手中”：原文是“卖给</ins>.手中”；本卷书下同。"]},{"n":15,"t":"他们无论往何处去，耶和华的手都以灾祸攻击他们，正如耶和华所说的，又如耶和华向他们所起的誓；他们就极其困苦。","notes":[]},{"n":16,"t":"耶和华兴起士师，士师就拯救他们脱离抢夺他们之人的手。","notes":[]},{"n":17,"t":"然而，他们却不听从士师，竟随从别神而行淫，向它们叩拜。他们列祖所行的道，所听从耶和华的命令，他们都速速偏离了，并不照样遵行。","notes":[]},{"n":18,"t":"耶和华为他们兴起士师，耶和华与士师同在。士师在世的一切日子，耶和华拯救他们脱离仇敌的手。耶和华因他们受欺压迫害所发出的哀声，就怜悯他们。","notes":[]},{"n":19,"t":"但士师一死，他们又转去行恶，比他们祖宗更坏，去随从别神，事奉叩拜它们，总不放弃他们的恶习和顽梗的行为。","notes":[]},{"n":20,"t":"于是耶和华的怒气向以色列发作，说：“因为这国违背我吩咐他们列祖当守的约，不听从我的话，","notes":[]},{"n":21,"t":"约书亚死的时候所剩下的各国，我必不再从他们面前赶出任何一个，","notes":[]},{"n":22,"t":"为要藉此考验以色列是否肯谨守遵行耶和华的道，像他们列祖一样地谨守。”","notes":[]},{"n":23,"t":"耶和华留下那些国家，不将他们速速赶出，也不把他们交在约书亚的手中。","notes":[]}]},"3":{"heading":"留下来的国家","verses":[{"n":1,"t":"耶和华留下这些国家，为要考验所有未曾经历迦南任何战役的以色列人，","notes":[]},{"n":2,"t":"只是为了要以色列人的后代认识战争，教导他们，尤其那些未曾认识这些事的人。","notes":[]},{"n":3,"t":"留下的有非利士的五个领袖，所有的迦南人，西顿人，以及从巴力．黑门山到哈马口，住黎巴嫩山的希未人。","notes":[]},{"n":4,"t":"他们是为了要考验以色列，好知道他们是否肯听从耶和华藉摩西吩咐他们列祖的命令。","notes":[]},{"n":5,"t":"以色列人住在迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人中间，","notes":[]},{"n":6,"t":"娶他们的女儿，将自己的女儿嫁给他们的儿子，并事奉他们的神明。","notes":[]},{"n":7,"t":"以色列人行耶和华眼中看为恶的事，忘记耶和华－他们的神，去事奉诸巴力和亚舍拉，","notes":[],"heads":["俄陀聂"]},{"n":8,"t":"所以耶和华的怒气向以色列发作，把他们交给美索不达米亚王古珊．利萨田的手中。以色列人服事古珊．利萨田八年。","notes":["“美索不达米亚”或译“两河间的亚兰”。"]},{"n":9,"t":"以色列人呼求耶和华，耶和华就为以色列人兴起一位拯救者来救他们，就是迦勒的弟弟基纳斯的儿子俄陀聂。","notes":[]},{"n":10,"t":"耶和华的灵降在他身上，他就作了以色列的士师。他出去争战，耶和华将亚兰王古珊．利萨田交在他手中，他的手战胜了古珊．利萨田。","notes":[]},{"n":11,"t":"于是这地太平四十年。基纳斯的儿子俄陀聂死了。","notes":[]},{"n":12,"t":"以色列人又行耶和华眼中看为恶的事。耶和华使摩押王伊矶伦强大，攻击以色列，因为他们行耶和华眼中看为恶的事。","notes":[],"heads":["以笏"]},{"n":13,"t":"伊矶伦召集亚扪人和亚玛力人到他那里，他就去攻打以色列，占据了棕树城。","notes":[]},{"n":14,"t":"于是以色列人服事摩押王伊矶伦十八年。","notes":[]},{"n":15,"t":"以色列人呼求耶和华，耶和华就为他们兴起一位拯救者，便雅悯人基拉的儿子以笏，他是个惯用左手的人。以色列人托他送礼物给摩押王伊矶伦。","notes":["“惯用左手的人”：原文直译“右手绑着的人”；“便雅悯”与“右手”希伯来话发音相近；七十士译本是“左右手兼用的人”; 20．16同。"]},{"n":16,"t":"以笏打造了一把两刃的剑，长一短肘，绑在右腿上衣服里面。","notes":["“短肘”或译“肘”；参“度量衡表”。"]},{"n":17,"t":"他把礼物献给摩押王伊矶伦。伊矶伦是个很肥胖的人。","notes":[]},{"n":18,"t":"以笏献完礼物的时候，就把抬礼物的人送走。","notes":[]},{"n":19,"t":"但他自己却从靠近吉甲的雕像那里转回来，说：“王啊，我有一件机密的事要奏告你。”王说：“回避吧！”于是所有侍立在他左右的人都退去了。","notes":[]},{"n":20,"t":"以笏来到王那里，那时他独自一人坐在阴凉的顶楼。以笏说：“我有神的话向你报告。”王就从座位上站起来。","notes":[]},{"n":21,"t":"以笏伸出左手，从右腿上拔出剑来，刺入王的肚腹。","notes":[]},{"n":22,"t":"剑柄连同剑刃都刺进去了，肥肉夹住了剑刃。他没有把剑从王的肚腹拔出来，粪便就流出来了。","notes":["“粪便就流出来了”或译“剑就穿通了后身”，或“就从后门出去了”。"]},{"n":23,"t":"以笏出到门廊，把王关在楼门里面，就上了锁。","notes":[]},{"n":24,"t":"以笏出来之后，王的仆人就来了。他们观看，看哪，楼门锁住，就说：“他必是在阴凉的房间里大解。”","notes":[]},{"n":25,"t":"他们等得不耐烦，看哪，楼门仍然不开，就拿钥匙打开楼门，看哪，他们的主人已经倒在地上死了。","notes":[]},{"n":26,"t":"他们耽延的时候，以笏就逃跑了。他经过雕像那里，逃到西伊拉。","notes":[]},{"n":27,"t":"他到了那里，就在以法莲山区吹角。以色列人跟随他从山区下来，他在他们前面引路，","notes":[]},{"n":28,"t":"对他们说：“紧跟着我！因为耶和华已经把你们的仇敌摩押交在你们手中。”于是他们跟着他下去，占据了摩押对面约旦河的渡口，不准一人过去。","notes":[]},{"n":29,"t":"那时，他们击杀了约一万摩押人，都是强壮的勇士，连一个也没有逃脱。","notes":[]},{"n":30,"t":"那日，摩押在以色列手下制伏了。于是这地太平八十年。","notes":[]},{"n":31,"t":"以笏之后，有亚拿的儿子珊迦，他用赶牛的棍子打死六百非利士人。他也拯救了以色列。","notes":[],"heads":["珊迦"]}]},"4":{"heading":"底波拉和巴拉","verses":[{"n":1,"t":"以笏死后，以色列人又行耶和华眼中看为恶的事。","notes":[]},{"n":2,"t":"耶和华把他们交给在夏琐作王的迦南王耶宾手中；他的将军是西西拉，住在夏罗设．哈歌印。","notes":["“夏罗设．哈歌印”或译“外邦人的夏罗设”；下同。"]},{"n":3,"t":"以色列人呼求耶和华，因为耶宾王有铁的战车九百辆，并且残酷欺压以色列人二十年。","notes":[]},{"n":4,"t":"有一位女先知底波拉，是拉比多的妻子，当时作以色列的士师。","notes":[]},{"n":5,"t":"她住在以法莲山区拉玛和伯特利的中间，在底波拉的棕树下。以色列人都上到她那里去听审判。","notes":[]},{"n":6,"t":"她派人从拿弗他利的基低斯把亚比挪庵的儿子巴拉召来，对他说：“耶和华－以色列的神吩咐你：‘你要率领一万拿弗他利人和西布伦人上他泊山去。","notes":[]},{"n":7,"t":"我必使耶宾的将军西西拉率领他的战车和全军往基顺河，到你那里去，我必把他交在你手中。’”","notes":[]},{"n":8,"t":"巴拉对她说：“你若同我去，我就去；你若不同我去，我就不去。”","notes":[]},{"n":9,"t":"底波拉说：“我一定会与你同去，然而你在所行的路上必得不着荣耀，因为耶和华要把西西拉交给一个妇人的手里。”于是底波拉起来，与巴拉一同往基低斯去了。","notes":[]},{"n":10,"t":"巴拉召集西布伦人和拿弗他利人到基低斯，跟他上去的有一万人。底波拉也同他上去。","notes":[]},{"n":11,"t":"摩西岳父何巴的后裔，基尼人希百离开了基尼族，到靠近基低斯的撒拿音橡树旁支搭帐棚。","notes":[]},{"n":12,"t":"有人告诉西西拉：“亚比挪庵的儿子巴拉已经上了他泊山。”","notes":[]},{"n":13,"t":"西西拉就召集所有的铁战车九百辆和随从的全军，从夏罗设．哈歌印出来，到了基顺河。","notes":[]},{"n":14,"t":"底波拉对巴拉说：“起来，今日就是耶和华把西西拉交在你手中的日子。耶和华岂不在你前面行吗总”于是巴拉下了他泊山，跟随他的有一万人。","notes":[]},{"n":15,"t":"耶和华使西西拉和他一切的战车，以及全军溃乱，在巴拉面前倒在刀下。西西拉下了车，徒步逃跑。","notes":[]},{"n":16,"t":"巴拉追赶战车、军队，直到夏罗设．哈歌印。西西拉的全军都倒在刀下，一个也没有留下。","notes":[]},{"n":17,"t":"只有西西拉徒步逃跑到基尼人希百之妻雅亿的帐棚，因为夏琐王耶宾与基尼人的希百家和平共处。","notes":[]},{"n":18,"t":"雅亿出来迎接西西拉，对他说：“请我主进来，进到我这里来，不要怕。”西西拉就进了她的帐棚，雅亿用被子将他盖住。","notes":[]},{"n":19,"t":"西西拉对雅亿说：“我渴了，求你给我一点水喝。”雅亿就打开装奶的皮袋，给他喝，再把他盖住。","notes":[]},{"n":20,"t":"西西拉对雅亿说：“请你站在帐棚门口，若有人来问你说：‘有人在这里吗？’你就说：‘没有。’”","notes":[]},{"n":21,"t":"西西拉疲乏沉睡了。希百的妻雅亿取了帐棚的橛子，手拿着锤子，静悄悄地到他那里，将橛子从他的太阳穴钉进去，直钉到地里。西西拉就死了。","notes":[]},{"n":22,"t":"看哪，巴拉追赶西西拉，雅亿出来迎接他，对他说：“来，我给你看你要找的人。”他就进入帐棚，看哪，西西拉已经倒在地上死了，橛子还在他的太阳穴中。","notes":[]},{"n":23,"t":"那日，神在以色列人面前制伏了迦南王耶宾。","notes":[]},{"n":24,"t":"从此，以色列人的手对迦南王耶宾越来越强硬，直到将迦南王耶宾剪除。","notes":[]}]},"5":{"heading":"底波拉之歌","verses":[{"n":1,"t":"那日，底波拉和亚比挪庵的儿子巴拉唱歌，说：","notes":[]},{"n":2,"t":"“以色列有领袖率领，百姓甘心牺牲自己，你们当称颂耶和华！","notes":["“有领袖率领”或译“任由发绺垂下”。"]},{"n":3,"t":"“君王啊，要听！王子啊，要侧耳！我要，我要向耶和华歌唱；我要歌颂耶和华－以色列的神。","notes":[]},{"n":4,"t":"“耶和华啊，你从西珥出来，从以东田野向前行，地震动天滴下，云也滴下雨水。","notes":[]},{"n":5,"t":"众山在耶和华面前摇动，西奈山在耶和华－以色列神面前也摇动。","notes":[]},{"n":6,"t":"“在亚拿之子珊迦的时候，在雅亿的日子，大道无人行走，过路人绕道而行。","notes":[]},{"n":7,"t":"以色列农村荒芜，空无一人，直到我底波拉兴起，兴起作以色列之母！","notes":[]},{"n":8,"t":"以色列人选择新的诸神，战争就临到城门。以色列四万人中，看得见盾牌枪矛吗？","notes":[]},{"n":9,"t":"我心向往以色列的领袖，他们在民中甘心牺牲自己。你们应当称颂耶和华！","notes":[]},{"n":10,"t":"“骑浅色母驴的、坐绣花毯子的、行走在路上的，你们都当思想！","notes":[]},{"n":11,"t":"打水的声音胜过弓箭的响声，那里，人要述说耶和华公义的作为，他对以色列乡民公义的作为。“那时，耶和华的子民下到城门。","notes":[]},{"n":12,"t":"“底波拉啊，兴起！兴起！当兴起，兴起，唱歌！巴拉啊，你当兴起！亚比挪庵的儿子啊，当俘掳你的俘虏！","notes":[]},{"n":13,"t":"那时，贵族中的幸存者前进，耶和华的百姓为我前进攻击勇士。","notes":[]},{"n":14,"t":"源自亚玛力的人从以法莲下来，跟着你，你的族人便雅悯；有领袖从玛吉下来，手握官员权杖的从西布伦下来。","notes":["“源自...下来”：有希腊文译本是“从以法莲来的人进入山谷”。"]},{"n":15,"t":"以萨迦的领袖与底波拉一起；巴拉怎样，以萨迦也怎样；他跟随巴拉冲下平原。吕便支派有胸怀大志的人。","notes":["“跟随巴拉”或译“徒步”。","“吕便支派”或译“在吕便的溪水旁”；下同。"]},{"n":16,"t":"你为何坐在羊圈内，听羊群中吹笛的声音呢？吕便支派具心有大谋的人。","notes":[]},{"n":17,"t":"基列安居在约旦河东。但为何住在船上呢？亚设在海边居住，它在港口安居。","notes":[]},{"n":18,"t":"西布伦是拚命敢死的百姓，拿弗他利在田野的高处也是如此。","notes":[]},{"n":19,"t":"“君王都来争战；那时迦南诸王在米吉多水旁的他纳争战，却得不到掳掠的银钱。","notes":[]},{"n":20,"t":"星宿从天上争战，从它们的轨道攻击西西拉。","notes":[]},{"n":21,"t":"基顺的急流冲走他们，古老的急流，基顺的急流。我的灵啊，努力前进！","notes":[]},{"n":22,"t":"“那时马蹄踢踏，壮马奔驰飞腾。","notes":[]},{"n":23,"t":"“耶和华的使者说：‘要诅咒米罗斯，重重诅咒其中的居民，因为他们不来帮助耶和华，不来帮助耶和华攻击壮士。’","notes":[]},{"n":24,"t":"“愿基尼人希百的妻子雅亿比众妇人多得福气，比帐棚中的妇人更蒙福祉。","notes":[]},{"n":25,"t":"西西拉求水，雅亿给他奶，用贵重的碗装乳酪给他。","notes":[]},{"n":26,"t":"雅亿左手拿着帐棚的橛子，右手拿着工匠的锤子，击打西西拉，打碎他的头，打破穿透他的太阳穴。","notes":[]},{"n":27,"t":"西西拉在她脚下曲身，仆倒，躺卧，在她脚下曲身，仆倒；他在哪里曲身，就在哪里仆倒，死亡。","notes":[]},{"n":28,"t":"“西西拉的母亲从窗户里往外观看，她在窗格子中哀号：‘他的战车为何迟迟未归？他的车轮为何走得那么慢呢？’","notes":[]},{"n":29,"t":"她聪明的宫女回答她，她也自言自语说：","notes":[]},{"n":30,"t":"‘或许他们得了战利品而分，每个壮士得了一两个女子？西西拉得了彩衣为掳物，得了绣花的彩衣为掠物，这两面绣花的彩衣，披在颈项上作为战利品。’","notes":[]},{"n":31,"t":"“耶和华啊，愿你的仇敌都这样灭亡！愿爱你的人如太阳上升，大发光辉！”于是这地太平四十年。","notes":[]}]},"6":{"heading":"基甸","verses":[{"n":1,"t":"以色列人又行耶和华眼中看为恶的事，耶和华就把他们交在米甸手里七年。","notes":[]},{"n":2,"t":"米甸的手战胜以色列；以色列人躲避米甸人，就在山中挖洞穴，挖洞建营寨。","notes":[]},{"n":3,"t":"每当以色列人撒种之后，米甸、亚玛力和东边的人都上来攻打他们，","notes":[]},{"n":4,"t":"对着他们安营，毁坏那地的农作物，直到迦萨，没有给以色列留下食物，牛、羊、驴也没有留下。","notes":[]},{"n":5,"t":"因为那些人带着他们的牲畜和帐棚上来，像蝗虫那样多；人和骆驼无数，都进入境内，毁坏全地。","notes":[]},{"n":6,"t":"以色列因米甸的缘故极其穷乏，以色列人就呼求耶和华。","notes":[]},{"n":7,"t":"以色列人因米甸的缘故呼求耶和华的时候，","notes":[]},{"n":8,"t":"耶和华就差遣先知到以色列人那里，对他们说：“耶和华－以色列的神如此说：‘我曾领你们从埃及上来，从为奴之家出来，","notes":[]},{"n":9,"t":"救你们脱离埃及人的手，脱离一切欺压你们之人的手。我从你们面前赶出他们，把他们的地赐给你们。","notes":[]},{"n":10,"t":"我对你们说，我是耶和华－你们的神。你们住在亚摩利人的地，不可敬畏他们的神明，但你们却不听从我的话。’”","notes":[]},{"n":11,"t":"耶和华的使者到了俄弗拉，坐在亚比以谢族约阿施的橡树下。约阿施的儿子基甸正在榨酒池那里打麦子，为了躲避米甸人。","notes":[],"heads":["基甸蒙选召"]},{"n":12,"t":"耶和华的使者向基甸显现，对他说：“大能的勇士啊，耶和华与你同在！”","notes":[]},{"n":13,"t":"基甸对他说：“主啊，请容许我说，耶和华若与我们同在，我们怎么会遭遇这一切事呢？我们的列祖告诉我们：‘耶和华领我们从埃及上来’，他那奇妙的作为在哪里呢？现在耶和华却丢弃了我们，把我们交在米甸人的手掌中。”","notes":[]},{"n":14,"t":"耶和华转向基甸，说：“去，靠着你这能力拯救以色列脱离米甸人的手掌。我岂不是已经差遣了你吗？”","notes":[]},{"n":15,"t":"基甸对他说：“主啊，请容许我说，我怎能拯救以色列呢？看哪，我这一支在玛拿西支派中是最贫寒的，我在我父家又是最微小的。”","notes":[]},{"n":16,"t":"耶和华对他说：“我与你同在，你就必击败米甸，如击打一个人。”","notes":[]},{"n":17,"t":"基甸对他说：“我若在你眼前蒙恩，求你给我一个证据，证明是你在跟我说话。","notes":[]},{"n":18,"t":"求你不要离开这里，等我回来，将供物带来，供在你面前。”他说：“我必等你回来。”","notes":[]},{"n":19,"t":"基甸去预备一只小山羊，用一伊法细面做了无酵饼，将肉放在篮子里，将汤盛在壶中，带到他那里，在橡树下献上。","notes":[]},{"n":20,"t":"神的使者对基甸说：“将肉和无酵饼放在这磐石上，把汤倒出来。”他就照样做了。","notes":[]},{"n":21,"t":"耶和华的使者伸出手里的杖，杖头一碰到肉和无酵饼，就有火从磐石中出来，吞灭了肉和无酵饼。耶和华的使者就从他眼前消失了。","notes":[]},{"n":22,"t":"基甸见他是耶和华的使者，就说：“哎呀！主耶和华啊！因为我真的面对面看见了耶和华的使者。”","notes":[]},{"n":23,"t":"耶和华对他说：“安心吧，不要怕，你不会死。”","notes":[]},{"n":24,"t":"于是基甸在那里为耶和华筑了一座坛，起名叫“耶和华沙龙”。这坛至今还在亚比以谢族的俄弗拉。","notes":["“耶和华沙龙”意思是“耶和华赐平安”。"]},{"n":25,"t":"那夜，耶和华对基甸说：“你要把你父亲的公牛，就是那七岁的第二头公牛取来，并拆毁你父亲为巴力筑的坛，砍下坛旁的亚舍拉，","notes":["“就是”或译“和”。"]},{"n":26,"t":"在这堡垒顶上整整齐齐地为耶和华－你的神筑一座坛，将第二头公牛献为燔祭，用你所砍下的亚舍拉当柴。”","notes":[]},{"n":27,"t":"基甸就从他仆人中选了十个人，照耶和华吩咐他的做了。他因怕父家和本城的人，不敢在白天做这事，就在夜间做。","notes":[]},{"n":28,"t":"城里的人清早起来，看哪，巴力的坛被拆毁，坛旁的亚舍拉被砍下，第二头公牛献在筑好的坛上，","notes":[],"heads":["基甸拆毁巴力的坛"]},{"n":29,"t":"就彼此问：“这是谁做的事呢？”他们寻找查访之后，就说：“这是约阿施的儿子基甸做的事。”","notes":[]},{"n":30,"t":"城里的人对约阿施说：“把你的儿子交出来，我们要处死他，因为他拆毁了巴力的坛，砍下了坛旁的亚舍拉。”","notes":[]},{"n":31,"t":"约阿施对站着敌对他的众人说：“你们是为巴力辩护吗？你们要救它吗？谁为它辩护，就在早晨把谁处死吧！巴力如果是神，有人拆毁了它的坛，就让它为自己辩护吧！”","notes":[]},{"n":32,"t":"所以那日人称基甸为耶路巴力，意思是：“他拆毁了巴力的坛，让巴力与他争辩吧。”","notes":[]},{"n":33,"t":"那时，所有的米甸人、亚玛力人和东边的人都聚集在一起，过了河，在耶斯列平原安营。","notes":[]},{"n":34,"t":"耶和华的灵降在基甸身上；他吹角，亚比以谢族都聚集跟随他。","notes":[]},{"n":35,"t":"他派使者走遍玛拿西，玛拿西人也聚集跟随他。他又派使者到亚设、西布伦、拿弗他利，他们也都上来会合。","notes":[]},{"n":36,"t":"基甸对神说：“你如果真的照你所说的，藉我的手拯救以色列，","notes":[],"heads":["羊毛的神迹"]},{"n":37,"t":"看哪，我把一团羊毛放在禾场上，若单是羊毛上有露水，遍地都是干的，我就知道你必照你所说的，藉我的手拯救以色列。”","notes":[]},{"n":38,"t":"一切果然发生了。次日早晨基甸起来，把羊毛拧一拧，从羊毛中挤出露水来，装满一碗的水。","notes":[]},{"n":39,"t":"基甸又对神说：“求你不要向我发怒，我再说一次，让我用羊毛再试一次，但愿羊毛是干的，遍地都有露水。”","notes":[]},{"n":40,"t":"这夜，神也照样做，遍地都有露水，只有羊毛是干的。","notes":[]}]},"7":{"heading":"基甸击败米甸人","verses":[{"n":1,"t":"耶路巴力，就是基甸，和所有跟随他的人早晨起来，在哈律泉旁安营。米甸营在他北边，靠近摩利冈的平原。","notes":[]},{"n":2,"t":"耶和华对基甸说：“跟随你的人太多，我不能把米甸交在他们手中，免得以色列向我自夸，说：‘是我自己的手救了我。’","notes":[]},{"n":3,"t":"现在你要向这百姓宣告说：‘凡惧怕战兢的，可以离开基列山回去。’”于是有二万二千人回去，只剩下一万人。","notes":[]},{"n":4,"t":"耶和华对基甸说：“人还是太多。你要带他们下到水旁，我好在那里为你试试他们。我指着谁对你说：‘这人可以跟你去’，他就可以跟你去；我指着谁对你说：‘这人不可跟你去’，他就不可跟你去。”","notes":[]},{"n":5,"t":"基甸就带百姓下到水旁。耶和华对基甸说：“凡用舌头舔水像狗一样舔的，要使他单独站在一处；那些用双膝跪下喝水的，也要使他单独站在一处。”","notes":[]},{"n":6,"t":"用手捧到嘴边舔水的数目有三百人，其余的百姓都用双膝跪下喝水。","notes":[]},{"n":7,"t":"耶和华对基甸说：“我要用这舔水的三百人拯救你们，把米甸交在你手中；其余的百姓都可以各回自己的地方去。”","notes":[]},{"n":8,"t":"百姓手里拿着食物和角；其余的以色列人，基甸都打发他们各自回到自己的帐棚，只留下这三百人。米甸营在他下边的平原上。","notes":[]},{"n":9,"t":"那夜，耶和华对基甸说：“起来，下去攻营，因我已把它交在你手中。","notes":[]},{"n":10,"t":"倘若你害怕下去，可以带你的仆人普拉下到那营里去，","notes":[]},{"n":11,"t":"你必听见他们所说的，这样你的手就有力量下去攻营。”于是基甸带着仆人普拉下到军营里带着兵器的人边上。","notes":[]},{"n":12,"t":"米甸人、亚玛力人和所有东边的人都散布在平原，如同蝗虫那样多。他们的骆驼无数，多如海边的沙。","notes":[]},{"n":13,"t":"基甸到了那里，看哪，有一人把梦告诉同伴说：“看哪，我做了一个梦。看哪，一个大麦饼滚入米甸营中，来到帐幕，把帐幕撞倒，帐幕就翻转倒塌了。”","notes":[]},{"n":14,"t":"同伴回答说：“这不是别的，而是以色列人约阿施的儿子基甸的刀。神已把米甸和全军都交在他手中了。”","notes":[]},{"n":15,"t":"基甸听见这梦的叙述和梦的解释，就敬拜神。他回到以色列营中，说：“起来吧！耶和华已把米甸军队交在你们手中了。”","notes":[]},{"n":16,"t":"于是基甸将三百人分成三队，把角和空瓶交在每个人手中，瓶内有火把。","notes":[]},{"n":17,"t":"他对他们说：“看着我，你们要照样做。看哪，我来到营边，我怎样做，你们也要照样做。","notes":[]},{"n":18,"t":"我和所有跟随我的人吹角的时候，你们也要在营的四围吹角，喊叫：‘为耶和华！为基甸！’”","notes":[]},{"n":19,"t":"基甸和跟随他的一百人，在半夜之初换岗哨的时候来到营旁。他们就吹角，打破手中的瓶；","notes":[]},{"n":20,"t":"三队的人都吹角，打破瓶子。他们左手拿着火把，右手拿着吹的角，喊叫：“耶和华和基甸的刀！”","notes":[]},{"n":21,"t":"他们围着军营，各人站在自己的地方；全营的人都逃窜，一面喊，一面逃跑。","notes":[]},{"n":22,"t":"三百人就吹角，耶和华使全营的人用刀自相击杀。全营的人逃往西利拉的伯．哈示他，一直逃到靠近他巴的亚伯．米何拉。","notes":[]},{"n":23,"t":"从拿弗他利、亚设和玛拿西全地来的以色列人被召来，追赶米甸人。","notes":[]},{"n":24,"t":"基甸也派人走遍以法莲山区，说：“你们下来迎击米甸人，在他们的前面沿着约旦河把守渡口，直到伯．巴拉。”于是以法莲众人聚集，沿着约旦河把守渡口，直到伯．巴拉。","notes":[]},{"n":25,"t":"他们捉住了米甸的两个领袖，俄立和西伊伯。他们在俄立磐石上杀了俄立，在西伊伯酒池那里杀了西伊伯。他们追赶米甸人，把俄立和西伊伯的首级带到约旦河对岸，到基甸那里。","notes":[]}]},"8":{"heading":"基甸追赶米甸王","verses":[{"n":1,"t":"以法莲人对基甸说：“你去与米甸争战，没有召我们同去，你为什么这样待我们呢？”他们就和基甸激烈地争吵。","notes":[]},{"n":2,"t":"基甸对他们说：“我现在所做的怎么与你们所做的相比呢？以法莲拾取剩下的葡萄不强过亚比以谢族所摘的葡萄吗？","notes":[]},{"n":3,"t":"神已把米甸的两个领袖俄立和西伊伯交在你们手中；我所做的怎能与你们所做的相比呢？”基甸说了这话，他们对他的怒气就消了。","notes":[]},{"n":4,"t":"基甸和跟随他的三百人来到约旦河，渡了过去；他们虽然疲乏，还是追赶。","notes":[]},{"n":5,"t":"基甸对疏割人说：“请你们拿几块饼来给跟随我的百姓，因为他们疲乏了。我正在追击米甸王西巴和撒慕拿。”","notes":[]},{"n":6,"t":"疏割人的领袖回答说：“西巴和撒慕拿的手掌现在已经在你手里，因此我们该将饼送给你的军队吗？”","notes":[]},{"n":7,"t":"基甸说：“好吧！耶和华将西巴和撒慕拿交在我手之后，我必用旷野的荆棘和枳条鞭打你们。”","notes":[]},{"n":8,"t":"基甸从那里上到毗努伊勒，对那里的人也提出同样的请求；毗努伊勒人给他的答覆跟疏割人的答覆一样。","notes":[]},{"n":9,"t":"他也对毗努伊勒人说：“我平平安安回来的时候，必拆毁这城楼。”","notes":[]},{"n":10,"t":"那时西巴和撒慕拿，以及跟随他们的军队都在加各，约有一万五千人，是东边的人全军所剩下的，因为拿刀战死的约有十二万人。","notes":[]},{"n":11,"t":"基甸从挪巴和约比哈的东边，从住帐棚人的路上去，趁米甸的军兵以为安全的时候攻击他们。","notes":["“住帐棚人”意思是“商队”。"]},{"n":12,"t":"西巴和撒慕拿逃跑；基甸追赶他们，捉住米甸的两个王西巴和撒慕拿，使他们全军溃散。","notes":[]},{"n":13,"t":"约阿施的儿子基甸从战场，沿着希列斯斜坡回来，","notes":[]},{"n":14,"t":"捉住疏割人的一个少年，查问他。他就为基甸写下疏割的领袖和长老的名字，共七十七人。","notes":[]},{"n":15,"t":"基甸到了疏割人那里，说：“你们从前讥笑我说：‘西巴和撒慕拿的手掌现在已经在你手里，因此我们该将饼送给跟随你的疲乏的人吗？’看哪，西巴和撒慕拿在这里。”","notes":[]},{"n":16,"t":"于是他拿住城内的长老，用旷野的荆棘和枳条责打疏割人。","notes":["“责打”是根据七十士译本；原文是“教训”。"]},{"n":17,"t":"他又拆了毗努伊勒的城楼，杀了城里的人。","notes":[]},{"n":18,"t":"基甸对西巴和撒慕拿说：“你们在他泊山所杀的人是什么样子的？”他们说：“他们很像你，个个都有王子的样子。”","notes":[]},{"n":19,"t":"基甸说：“他们都是我的兄弟，我母亲的儿子。我指着永生的耶和华起誓，你们若存留他们的性命，我就不杀你们了。”","notes":[]},{"n":20,"t":"他对他的长子益帖说：“你起来杀他们！”但是这少年害怕，不敢拔刀，因为他还是个少年。","notes":[]},{"n":21,"t":"西巴和撒慕拿说：“你自己起来杀我们吧！因为人如何，力量也如何。”基甸就起来，杀了西巴和撒慕拿，取了他们骆驼颈项上的月牙圈。","notes":[]},{"n":22,"t":"以色列人对基甸说：“你既然救我们脱离米甸的手，愿你治理我们，你的儿子孙子也治理我们。”","notes":[],"heads":["基甸在俄弗拉设立以弗得"]},{"n":23,"t":"基甸对他们说：“我不治理你们，我的儿子也不治理你们，耶和华会治理你们。”","notes":[]},{"n":24,"t":"基甸又对他们说：“我有一件事求你们，请你们各人把所夺的耳环给我。”因敌人都戴金耳环，他们是以实玛利人。","notes":[]},{"n":25,"t":"以色列人说：“我们情愿送给你！”他们就铺开一件外衣，各人将所夺的耳环丢在上面。","notes":[]},{"n":26,"t":"基甸所要求的金耳环，重一千七百舍客勒金子。此外还有米甸王所戴的月牙圈、耳环，和所穿的紫色衣服，以及骆驼颈项上的链子。","notes":[]},{"n":27,"t":"基甸以此造了一个以弗得，设立在他的本城俄弗拉。全以色列就在那里拜这以弗得行淫，这就成了基甸和他全家的圈套。","notes":[]},{"n":28,"t":"这样，米甸就被以色列人制伏了，再也不能抬头。基甸还在的日子，这地太平四十年。","notes":[]},{"n":29,"t":"约阿施的儿子耶路巴力回去，住在自己家里。","notes":[],"heads":["基甸去世"]},{"n":30,"t":"基甸有七十个亲生的儿子，因为他有许多妻子。","notes":[]},{"n":31,"t":"他在示剑的妾也为他生了一个儿子，基甸给他起名叫亚比米勒。","notes":[]},{"n":32,"t":"约阿施的儿子基甸年纪老迈而死，葬在亚比以谢族的俄弗拉，他父亲约阿施的坟墓里。","notes":[]},{"n":33,"t":"基甸死后，以色列人又去随从诸巴力而行淫，以巴力．比利土为他们的神明。","notes":[]},{"n":34,"t":"以色列人不记得耶和华－他们的神，就是那位拯救他们脱离四围仇敌之手的，","notes":[]},{"n":35,"t":"也不照着耶路巴力，就是基甸向以色列所施的恩惠善待他的家。","notes":[]}]},"9":{"heading":"亚比米勒","verses":[{"n":1,"t":"耶路巴力的儿子亚比米勒到示剑他的母舅那里，对他们和他外祖父全家的人说：","notes":[]},{"n":2,"t":"“请你们问示剑所有的居民：‘是耶路巴力的众儿子七十人都治理你们好，还是一人治理你们好呢？’你们要记得，我是你们的骨肉。”","notes":[]},{"n":3,"t":"他的母舅们为他把这一切话说给示剑所有的居民听，他们的心就倾向亚比米勒，因为他们说：“他是我们的弟兄。”","notes":[]},{"n":4,"t":"他们从巴力．比利土的庙中取了七十银子给亚比米勒，亚比米勒用这些钱雇了一些无赖匪徒跟随他。","notes":[]},{"n":5,"t":"他来到俄弗拉他父亲的家，在一块磐石上把他的兄弟，就是耶路巴力的七十个儿子都杀了，只剩下耶路巴力的小儿子约坦，因为他躲了起来。","notes":[]},{"n":6,"t":"示剑所有的居民和全伯．米罗都聚集在一起，到示剑橡树旁的柱子那里，立亚比米勒为王。","notes":[]},{"n":7,"t":"有人将这事告诉约坦，他就去站在基利心山顶上，高声喊叫，对他们说：“示剑的居民哪，你们要听我，神也就会听你们。","notes":[]},{"n":8,"t":"有一次，树木要膏一王治理他们，就去对橄榄树说：‘请你来作王治理我们！’","notes":[]},{"n":9,"t":"橄榄树对它们说：‘我岂可停止生产使神明和人得尊荣的油，而行走飘摇在众树之上呢？’","notes":[]},{"n":10,"t":"树木对无花果树说：‘请你来作王治理我们！’","notes":[]},{"n":11,"t":"无花果树对它们说：‘我岂可停止结甜美的果子，而行走飘摇在众树之上呢？’","notes":[]},{"n":12,"t":"树木对葡萄树说：‘请你来作王治理我们！’","notes":[]},{"n":13,"t":"葡萄树对它们说：‘我岂可停止出产使神明和人欢乐的新酒，而行走飘摇在众树之上呢。’","notes":[]},{"n":14,"t":"众树对荆棘说：‘请你来作王治理我们！’","notes":[]},{"n":15,"t":"荆棘对众树说：‘你们若真的要膏我作王治理你们，就要来到我的荫下寻求庇护；不然，愿火从荆棘里出来，吞灭黎巴嫩的香柏树。’","notes":[]},{"n":16,"t":"“现在你们若以诚实正直立亚比米勒为王，若善待耶路巴力和他的家，若照他手所做的回报他─","notes":[]},{"n":17,"t":"从前我父为你们争战，冒生命的危险救你们脱离米甸的手，","notes":[]},{"n":18,"t":"但是你们如今起来攻击我的父家，在一块磐石上把他的七十个儿子全杀了，又立他使女所生的儿子亚比米勒为示剑居民的王，因为他是你们的弟兄─","notes":[]},{"n":19,"t":"你们如今若以诚实正直对待耶路巴力和他的家，就可以因亚比米勒欢乐，他也可以因你们欢乐；","notes":[]},{"n":20,"t":"不然，愿火从亚比米勒发出，吞灭示剑居民和伯．米罗，又愿火从示剑居民和伯．米罗发出，吞灭亚比米勒。”","notes":[]},{"n":21,"t":"约坦因躲避他的兄弟亚比米勒就逃跑，去到比珥，住在那里。","notes":[]},{"n":22,"t":"亚比米勒治理以色列三年。","notes":[]},{"n":23,"t":"神派邪灵到亚比米勒和示剑居民中间，示剑居民就以诡诈待亚比米勒。","notes":[]},{"n":24,"t":"这是要使耶路巴力七十个儿子受害所流的血，归于他们的兄弟亚比米勒，因他杀害他们，也归于那些出手帮助他杀害兄弟的示剑居民。","notes":[]},{"n":25,"t":"示剑居民在山顶上设下埋伏，等候亚比米勒。凡沿着那条路，从他们那里经过的人，他们就抢劫。有人把这事告诉亚比米勒。","notes":[]},{"n":26,"t":"以别的儿子迦勒和他的弟兄经过，来到示剑，示剑居民都信任他。","notes":[]},{"n":27,"t":"他们出到田间，摘下葡萄，踹酒，作乐。他们进入他们神明的庙中吃喝，诅咒亚比米勒。","notes":[]},{"n":28,"t":"以别的儿子迦勒说：“亚比米勒是谁，我们示剑人是谁，叫我们服事他呢？他不是耶路巴力的儿子吗？他的助手不是西布勒吗？你们应当服事示剑的父亲哈抹的后裔！我们为何要服事亚比米勒呢？","notes":[]},{"n":29,"t":"惟愿这民归到我的手下，我就除掉亚比米勒。”他就对亚比米勒说：“增加你的军兵，出来吧！”","notes":["本节七十士译本是“惟愿这民归到我的手下，我就除掉亚比米勒。我对亚比米勒说：‘增加你的军兵，出来吧！’”"]},{"n":30,"t":"西布勒市长听见以别的儿子迦勒的话，就怒气大发。","notes":[]},{"n":31,"t":"他悄悄地派一些使者到亚比米勒那里，说：“看哪，以别的儿子迦勒和他的弟兄到了示剑。看哪，他们煽动那城攻击你。","notes":[]},{"n":32,"t":"现在，你和跟随你的百姓要夜间起来，在田间埋伏。","notes":[]},{"n":33,"t":"早晨太阳一出，你就趁早攻城。看哪，迦勒和跟随他的百姓出来攻击你的时候，你就全力对付他们。”","notes":[]},{"n":34,"t":"于是，亚比米勒和跟随他的众百姓夜间起来，兵分四队，埋伏攻击示剑。","notes":[]},{"n":35,"t":"以别的儿子迦勒出去，站在城门口。亚比米勒和跟随他的百姓从埋伏之处起来。","notes":[]},{"n":36,"t":"迦勒看见百姓，就对西布勒说：“看哪，有百姓从山顶上下来。”西布勒对他说：“你把山的影子看作是人了。”","notes":[]},{"n":37,"t":"迦勒又继续讲，他说：“看哪，有百姓从地的高处下来，又有一队从米恶尼尼橡树的路前来。”","notes":["“米恶尼尼橡树”或译“占卜者的橡树”。"]},{"n":38,"t":"西布勒对他说：“你所夸口的在哪里呢？你曾说：‘亚比米勒是谁，叫我们服事他呢？’这不是你所藐视的百姓吗？你现在出去，与他们交战吧！”","notes":[]},{"n":39,"t":"于是迦勒率领示剑居民出去，与亚比米勒交战。","notes":[]},{"n":40,"t":"亚比米勒追赶迦勒，迦勒在他面前逃跑。有许多人被刺伤仆倒，直到城门口。","notes":[]},{"n":41,"t":"亚比米勒住在亚鲁玛。西布勒赶出迦勒和他的弟兄，不准他们住在示剑。","notes":[]},{"n":42,"t":"次日，百姓出到田间，有人告诉亚比米勒，","notes":[]},{"n":43,"t":"他就带领百姓，把他们分成三队，埋伏在田间窥探。看哪，示剑居民从城里出来，他就起来击杀他们。","notes":[]},{"n":44,"t":"亚比米勒和跟随他的一队向前冲，站在城门口；另外两队直冲向田间，击杀了众人。","notes":[]},{"n":45,"t":"亚比米勒攻城一整天，将城夺取，杀了其中的百姓，把城拆毁，撒上了盐。","notes":[]},{"n":46,"t":"示剑城楼里所有的居民听见了，就进入伊勒．比利土庙的地窖里。","notes":[]},{"n":47,"t":"有人告诉亚比米勒，示剑城楼里所有的居民都聚在一起。","notes":[]},{"n":48,"t":"亚比米勒和所有跟随他的百姓都上撒们山去。亚比米勒手拿斧子，砍下一根树枝，举起来，扛在肩上，对跟随他的百姓说：“你们看我做什么，就赶快照样做。”","notes":[]},{"n":49,"t":"众百姓也都各砍一根树枝，跟亚比米勒走，把树枝堆在地窖上，放火烧地窖。这样，示剑城楼里所有的人都死了，男女约有一千。","notes":[]},{"n":50,"t":"亚比米勒到提备斯，对着提备斯安营，攻取了那城。","notes":[]},{"n":51,"t":"城中有一座坚固的楼；城里所有的居民，无论男女，都逃到那里，关上门，上了楼顶。","notes":[]},{"n":52,"t":"亚比米勒到了楼前，攻打它。他挨近楼门，要放火焚烧。","notes":[]},{"n":53,"t":"有一个妇人把一块上磨石抛在亚比米勒的头上，打破了他的头盖骨。","notes":[]},{"n":54,"t":"他就急忙叫拿他兵器的青年来，对他说：“拔出你的刀来，杀了我吧！免得有人提到我说：‘他被一个妇人杀了。’”于是那青年把他刺透，他就死了。","notes":[]},{"n":55,"t":"以色列人见亚比米勒死了，就各回自己的地方去了。","notes":[]},{"n":56,"t":"这样，神报应了亚比米勒向他父亲所做的恶事，就是杀了自己七十个兄弟。","notes":[]},{"n":57,"t":"示剑人的一切恶事，神也都报应在他们头上；耶路巴力的儿子约坦的诅咒都临到他们身上了。","notes":[]}]},"10":{"heading":"陀拉","verses":[{"n":1,"t":"亚比米勒以后，陀拉兴起，拯救以色列，他是朵多的孙子，普瓦的儿子，以萨迦人，住在以法莲山区的沙密。","notes":[]},{"n":2,"t":"陀拉作以色列的士师二十三年。他死了，葬在沙密。","notes":[]},{"n":3,"t":"陀拉以后有基列人睚珥兴起，作以色列的士师二十二年。","notes":[],"heads":["睚珥"]},{"n":4,"t":"他有三十个儿子，骑着三十匹驴驹。他们有三十座城，叫作哈倭特．睚珥，直到如今，都在基列地。","notes":[]},{"n":5,"t":"睚珥死了，葬在加们。","notes":[]},{"n":6,"t":"以色列人又行耶和华眼中看为恶的事，去事奉诸巴力和亚斯她录，以及亚兰的神明、西顿的神明、摩押的神明、亚扪人的神明、非利士人的神明。他们离弃耶和华，不事奉他。","notes":[],"heads":["耶弗他"]},{"n":7,"t":"耶和华的怒气向以色列发作，把他们交给非利士人和亚扪人的手中。","notes":[]},{"n":8,"t":"从那年起，他们欺压迫害以色列人，在约旦河东，亚摩利人境内，基列一带所有的以色列人，长达十八年。","notes":[]},{"n":9,"t":"亚扪人渡过约旦河去攻打犹大和便雅悯，以及以法莲家族。以色列的处境非常困苦。","notes":[]},{"n":10,"t":"以色列人哀求耶和华说：“我们得罪了你，因为我们离弃了我们的神，去事奉诸巴力。”","notes":[]},{"n":11,"t":"耶和华对以色列人说：“我岂没有救你们脱离埃及人、亚摩利人、亚扪人和非利士人吗？","notes":[]},{"n":12,"t":"西顿人、亚玛力人和马云人欺压你们，你们哀求我，我也拯救你们脱离他们的手。","notes":["“马云人”：七十士译本是“米甸人”。"]},{"n":13,"t":"你们竟离弃我去事奉别神！所以我不再救你们了。","notes":[]},{"n":14,"t":"你们去哀求你们所选择的神明；你们遭遇急难的时候，让它们救你们吧！”","notes":[]},{"n":15,"t":"以色列人对耶和华说：“我们犯罪了，照你看为好的待我们，只求你今日拯救我们吧！”","notes":[]},{"n":16,"t":"以色列人就除掉他们中间的外邦神明，事奉耶和华。耶和华因以色列所受的苦难而心里焦急。","notes":[]},{"n":17,"t":"亚扪人被召来，在基列安营；以色列人也聚集，在米斯巴安营。","notes":[]},{"n":18,"t":"基列百姓中的领袖彼此说：“谁领先出去攻打亚扪人，谁就作基列所有居民的领袖。”","notes":[]}]},"11":{"heading":"耶弗他的出生","verses":[{"n":1,"t":"基列人耶弗他是个大能的勇士，是妓女的儿子。基列生了耶弗他。","notes":[]},{"n":2,"t":"基列的妻子也给他生了几个儿子。他妻子生的儿子长大后，就把耶弗他赶出去，说：“你不可在我们父家继承产业，因为你是别的女人生的儿子。”","notes":[]},{"n":3,"t":"耶弗他就逃离他的兄弟，住在陀伯地。有些无赖的人聚集在他那里，与他一同出入。","notes":[]},{"n":4,"t":"过了些日子，亚扪人攻打以色列。","notes":[]},{"n":5,"t":"亚扪人攻打以色列的时候，基列的长老去请耶弗他从陀伯地回来。","notes":[]},{"n":6,"t":"他们对耶弗他说：“请你来作我们的指挥官，好让我们跟亚扪人打仗。”","notes":[]},{"n":7,"t":"耶弗他对基列的长老说：“你们不是恨我，把我赶出父家吗？现在你们遭遇急难，为何到我这里来呢？”","notes":[]},{"n":8,"t":"基列的长老对耶弗他说：“现在我们回到你这里，是要请你同我们去跟亚扪人打仗，作基列所有居民的领袖。”","notes":[]},{"n":9,"t":"耶弗他对基列的长老说：“若你们请我回去跟亚扪人打仗，耶和华把他们交给我，我就作你们的领袖。”","notes":[]},{"n":10,"t":"基列的长老对耶弗他说：“有耶和华在你我之间作证，我们必定照你的话做。”","notes":[]},{"n":11,"t":"于是耶弗他与基列的长老同去，百姓就立耶弗他作他们的领袖和指挥官。耶弗他在米斯巴将他一切的事陈述在耶和华面前。","notes":[]},{"n":12,"t":"耶弗他派使者到亚扪人的王那里，说：“你与我有什么相干，竟来到我这里攻打我的地呢？”","notes":[]},{"n":13,"t":"亚扪人的王对耶弗他的使者说：“因为以色列从埃及上来的时候占据我的地，从亚嫩河到雅博河，直到约旦河。现在你要和平归还这些地方！”","notes":[]},{"n":14,"t":"耶弗他又派使者到亚扪人的王那里，","notes":[]},{"n":15,"t":"对他说：“耶弗他如此说：以色列并没有占据摩押地和亚扪人的地。","notes":[]},{"n":16,"t":"以色列人从埃及上来，是经过旷野到红海，来到加低斯。","notes":["“红海”：原文是“芦苇海”。"]},{"n":17,"t":"那时，以色列派使者去以东王那里，说：‘求你让我穿越你的地。’以东王却不听。以色列又照样派使者去摩押王那里，他也不肯。于是以色列人就住在加低斯。","notes":[]},{"n":18,"t":"他们又经过旷野，绕过以东地和摩押地，到摩押地的东边，在亚嫩河边安营，并没有进入摩押的境内，因为亚嫩河是摩押的边界。","notes":["“东边”：原文是“日出的方向”。"]},{"n":19,"t":"以色列派使者去亚摩利王，就是希实本王西宏那里；以色列对他说：‘求你让我们穿越你的地，到我自己的地方去。’","notes":[]},{"n":20,"t":"西宏却不信任以色列，不让他们穿越他的疆界。他召集了他的众百姓在雅杂安营，与以色列争战。","notes":[]},{"n":21,"t":"耶和华－以色列的神将西宏和他的众百姓都交在以色列手中，以色列人就击杀他们，占领了那地居民亚摩利人的全地。","notes":[]},{"n":22,"t":"他们占领了亚摩利人所有的疆土，从亚嫩河到雅博河，从旷野直到约旦河。","notes":[]},{"n":23,"t":"耶和华－以色列的神如今从他百姓以色列面前赶出亚摩利人，你竟要占领它吗？","notes":[]},{"n":24,"t":"你不是已经得了你的神明基抹赐给你的地为业吗？耶和华－我们的神在我们面前所赶出的，我们也要得它为业。","notes":[]},{"n":25,"t":"现在你比西拨的儿子摩押王巴勒还强吗？他真的曾与以色列争执，或是真的与他们争战了吗？","notes":[]},{"n":26,"t":"以色列人住希实本和所属的乡镇，亚罗珥和所属的乡镇，以及沿着亚嫩河的一切城镇，已经有三百年了。在这期间，你们为什么不取回呢？","notes":[]},{"n":27,"t":"我并没有得罪你，你却要攻打我，加害于我。愿审判人的耶和华今日在以色列人和亚扪人之间判断是非。”","notes":[]},{"n":28,"t":"但亚扪人的王不听耶弗他传达给他的话。","notes":[]},{"n":29,"t":"耶和华的灵降在耶弗他身上，他就经过基列和玛拿西，经过基列的米斯巴，又从基列的米斯巴过到亚扪人那里。","notes":[]},{"n":30,"t":"耶弗他向耶和华许愿，说：“你若真的将亚扪人交在我手中，","notes":[]},{"n":31,"t":"我从亚扪人那里平平安安回来的时候，无论谁先从我家门出来迎接我，就要归给耶和华，我必将他献上作为燔祭。”","notes":[]},{"n":32,"t":"于是耶弗他往亚扪人那里去，与他们争战。耶和华将他们交在他手中，","notes":[]},{"n":33,"t":"他就彻底击败他们，从亚罗珥到米匿，直到亚备勒．基拉明，攻取了二十座城。这样，亚扪人就在以色列人面前被制伏了。","notes":[]},{"n":34,"t":"耶弗他回米斯巴去，到了自己的家，看哪，他女儿拿着手鼓跳舞出来迎接他。她是耶弗他的独生女，除她以外，没有别的儿女。","notes":[],"heads":["耶弗他的女儿"]},{"n":35,"t":"耶弗他一看见她，就撕裂衣服，说：“哀哉！我的女儿啊，你使我非常悲痛，叫我十分为难了。因为我已经向耶和华开了口，不能收回。”","notes":[]},{"n":36,"t":"他女儿对他说：“我的父亲啊，你既向耶和华开了口，就当照你口中所说的向我行，因为耶和华已经在你的仇敌亚扪人身上为你报了仇。”","notes":[]},{"n":37,"t":"她又对父亲说：“我只求你这一件事，给我两个月，让我和同伴下到山里，好为我的童贞哀哭。”","notes":[]},{"n":38,"t":"耶弗他说：“你去吧！”他就让她离开两个月。她和同伴去了，在山里为她的童贞哀哭。","notes":[]},{"n":39,"t":"过了两个月，她回到父亲那里，父亲就照所许的愿向她行了。她从来没有亲近男人。于是以色列中有个风俗，","notes":[]},{"n":40,"t":"每年按着日期以色列的女子要去为基列人耶弗他的女儿哀哭四天。","notes":[]}]},"12":{"heading":"耶弗他与以法莲人交战","verses":[{"n":1,"t":"以法莲人被召来，渡河来到撒分。他们对耶弗他说：“你去与亚扪人争战，为什么没有召我们同去呢？我们必用火将你和你的家烧了。”","notes":["“撒分”或译“北方”。"]},{"n":2,"t":"耶弗他对他们说：“我和我的百姓与亚扪人有极大的冲突；我曾召你们来，你们却没有来救我脱离他们的手。","notes":[]},{"n":3,"t":"我见你们不来救我，就拚了命前去攻打亚扪人，耶和华就将他们交在我手中。你们今日为什么上我这里来攻打我呢？”","notes":[]},{"n":4,"t":"于是耶弗他召集基列所有的人，要与以法莲人争战。基列人击杀以法莲人，因以法莲人曾说：“你们基列人在以法莲和玛拿西中，不过是以法莲逃亡的人而已。”","notes":[]},{"n":5,"t":"基列人把守约旦河的渡口，不许以法莲人过去。逃跑的以法莲人若说：“让我过河。”基列人就问他说：“你是不是以法莲人？”他若说：“不是”，","notes":[]},{"n":6,"t":"基列人就对他说：“你说‘示播列’。”以法莲人因为发音不准，就会说成“西播列”。基列人就捉住他，在约旦河的渡口把他杀了。那时，以法莲人被杀的有四万二千人。","notes":[]},{"n":7,"t":"耶弗他作以色列的士师六年。基列人耶弗他死了，葬在基列的城里。","notes":["“基列的城里”：七十士译本是“他的城基列”。"]},{"n":8,"t":"耶弗他以后，有伯利恒人以比赞作以色列的士师。","notes":[],"heads":["以比赞、以伦、押顿"]},{"n":9,"t":"他有三十个儿子。他把三十个女儿都嫁出去了，也为他的儿子从外面娶了三十个媳妇。他作以色列的士师七年。","notes":[]},{"n":10,"t":"以比赞死了，葬在伯利恒。","notes":[]},{"n":11,"t":"以比赞以后，有西布伦人以伦作以色列的士师，他作以色列的士师十年。","notes":[]},{"n":12,"t":"西布伦人以伦死了，葬在西布伦地的亚雅仑。","notes":[]},{"n":13,"t":"以伦以后，有比拉顿人希列的儿子押顿作以色列的士师。","notes":[]},{"n":14,"t":"他有四十个儿子，三十个孙子，骑着七十匹驴驹。押顿作以色列的士师八年。","notes":[]},{"n":15,"t":"比拉顿人希列的儿子押顿死了，葬在以法莲地的比拉顿，就在亚玛力人的山区。","notes":[]}]},"13":{"heading":"参孙","verses":[{"n":1,"t":"以色列人又行耶和华眼中看为恶的事，耶和华将他们交在非利士人手中四十年。","notes":[]},{"n":2,"t":"那时，有一个但支派的琐拉人，名叫玛挪亚。他的妻子不怀孕，不生育。","notes":[],"heads":["参孙出生"]},{"n":3,"t":"耶和华的使者向那妇人显现，对她说：“看哪，以前你不怀孕，不生育，如今你必怀孕生一个儿子。","notes":[]},{"n":4,"t":"现在你要谨慎，清酒烈酒都不可喝，任何不洁之物都不可吃，","notes":[]},{"n":5,"t":"看哪，你必怀孕，生一个儿子。不可用剃刀剃他的头，因为这孩子一出母胎就归给神作拿细耳人。他必开始拯救以色列脱离非利士人的手。”","notes":[]},{"n":6,"t":"那妇人来对丈夫说：“有一个神人到我这里来，他的容貌如神使者的容貌，非常可畏。我没有问他从哪里来，他也没有把他的名字告诉我。","notes":[]},{"n":7,"t":"他对我说：‘看哪，你要怀孕，生一个儿子 。现在，清酒烈酒都不可喝，任何不洁之物都不可吃，因为这孩子从出母胎一直到死的那一天，要归给神作拿细耳人。’”","notes":[]},{"n":8,"t":"玛挪亚祈求耶和华说：“主啊，求你再差遣那神人到我们这里来，指示我们对这将要生的孩子该怎样作。”","notes":[]},{"n":9,"t":"神垂听了玛挪亚的声音。那妇人坐在田间的时候，神的使者又到她那里，但是她的丈夫玛挪亚没有同她在一起。","notes":[]},{"n":10,"t":"妇人急忙跑去告诉丈夫，对他说：“看哪，那日到我这里来的人又向我显现了。”","notes":[]},{"n":11,"t":"玛挪亚起来，跟随他的妻子来到那人那里，对他说：“你就是跟这妇人说话的那个人吗？”他说：“是我。”","notes":[]},{"n":12,"t":"玛挪亚说：“现在，愿你的话应验！这孩子该如何管教呢？他当做什么呢？”","notes":[]},{"n":13,"t":"耶和华的使者对玛挪亚说：“我告诉这妇人的一切事，她都要遵守。","notes":[]},{"n":14,"t":"葡萄树所结的不可吃，清酒烈酒都不可喝，任何不洁之物也不可吃。凡我所吩咐的，她都当遵守。”","notes":[]},{"n":15,"t":"玛挪亚对耶和华的使者说：“请容许我们留你下来，好为你预备一只小山羊。”","notes":[]},{"n":16,"t":"耶和华的使者对玛挪亚说：“你虽然留我，我却不吃你的食物。你若预备燔祭，就当献给耶和华。”因玛挪亚不知道他是耶和华的使者。","notes":[]},{"n":17,"t":"玛挪亚对耶和华的使者说：“请问大名？好让我们在你的话应验的时候尊敬你。”","notes":[]},{"n":18,"t":"耶和华的使者对他说：“你何必问我的名字呢？我的名字是奇妙的。”","notes":[]},{"n":19,"t":"玛挪亚取一只小山羊和素祭，在磐石上献给耶和华。他行奇妙的事，玛挪亚和他的妻子观看，","notes":[]},{"n":20,"t":"火焰从坛上往上升，耶和华的使者也在坛上的火焰中升上去了。玛挪亚和他的妻子看见，就脸伏于地。","notes":[]},{"n":21,"t":"耶和华的使者不再向玛挪亚和他的妻子显现了。那时，玛挪亚才知道他是耶和华的使者。","notes":[]},{"n":22,"t":"玛挪亚对他的妻子说：“我们一定会死，因为我们看见了神。”","notes":[]},{"n":23,"t":"他的妻子却对他说：“耶和华若有意要我们死，就不会从我们手中接受燔祭和素祭，不会将这一切事指示我们，这时也不会让我们听到这话。”","notes":[]},{"n":24,"t":"后来妇人生了一个儿子，给他起名叫参孙。孩子渐渐长大，耶和华赐福给他。","notes":[]},{"n":25,"t":"在琐拉和以实陶之间的玛哈尼．但，耶和华的灵开始感动参孙。","notes":["“玛哈尼．但”意思是“但支派的营中”。"]}]},"14":{"heading":"参孙娶妻","verses":[{"n":1,"t":"参孙下到亭拿，在亭拿看见一个女子，是非利士人的女儿。","notes":[]},{"n":2,"t":"他上来告诉他父母说：“我在亭拿看见一个女子，是非利士人的女儿，现在请你们给我娶她为妻。”","notes":[]},{"n":3,"t":"他父母对他说：“在你弟兄的女儿中，或在本族所有的人中，难道没有女子吗？你何必在未受割礼的非利士人中去娶妻呢？”参孙对他父亲说：“请你给我娶那女子，因为我喜欢她。”","notes":[]},{"n":4,"t":"他的父母并不知道这事是出于耶和华，因为他在找机会攻击非利士人。那时，非利士人辖制以色列人。","notes":[]},{"n":5,"t":"参孙跟他父母下亭拿去，他们到了亭拿的葡萄园。看哪，有一只少壮狮子对着他吼叫。","notes":[]},{"n":6,"t":"耶和华的灵大大感动参孙，他就手无寸铁撕裂狮子，如撕裂小山羊一样。他做这事，并没有告诉他的父母亲。","notes":[]},{"n":7,"t":"参孙下去跟那女子说话，看着就喜欢她。","notes":[]},{"n":8,"t":"过了些日子，他回来要娶那女子，绕道去看狮子的残骸，看哪，有一群蜜蜂在狮子的尸体内，也有蜜在里面。","notes":[]},{"n":9,"t":"他就取了蜜，放在手掌上，边走边吃。他到了父母那里，给他们蜜，他们也吃了。但他没有告诉他们，这蜜是从狮子的尸体内取来的。","notes":[]},{"n":10,"t":"他父亲下到女子那里去。参孙在那里摆设宴席， 因为这是当时年轻人的习俗。","notes":[]},{"n":11,"t":"他们看见参孙，就请了三十个人陪伴他。","notes":[]},{"n":12,"t":"参孙对他们说：“我给你们出个谜语，你们若能在七日宴席之内，猜出谜底告诉我，我就给你们三十件细麻内衣和三十套更换的衣服。","notes":[]},{"n":13,"t":"但你们若不能告诉我，你们就给我三十件细麻内衣和三十套更换的衣服。”他们对他说：“请把谜语说给我们听。”","notes":[]},{"n":14,"t":"参孙对他们说：“吃的从吃者出来；甜的从强者出来”。三日之久，他们都猜不出谜语来。","notes":[]},{"n":15,"t":"第七日，他们对参孙的妻子说：“你哄骗你的丈夫，为我们探出谜底来，否则我们就用火烧你和你的父家。你们请我们来，是不是要夺走我们所有的呢？”","notes":["“第七日”：七十士译本和其他古译本是“第四日”。"]},{"n":16,"t":"参孙的妻子在丈夫面前哭哭啼啼说：“你只是恨我，并不爱我。你给我本族的人出谜语，却不把谜底告诉我。”参孙对她说：“看哪，连我的父母我都没有说，我怎么可以告诉你呢？”","notes":[]},{"n":17,"t":"在七日宴席中，她一直在丈夫面前哭哭啼啼。第七日，参孙因妻子的催逼就把谜底告诉了她。她把谜底告诉了她本族的人。","notes":[]},{"n":18,"t":"第七日日落以前，那城里的人对参孙说：“有什么比蜜还甜呢？有什么比狮子更强呢？”参孙对他们说：“你们若不用我的母牛犊耕地，就无法猜出我的谜底来。”","notes":[]},{"n":19,"t":"耶和华的灵大大感动参孙，他就下到亚实基伦，击杀了三十个人，夺了他们身上的衣服，把衣服给了猜出谜语的人。参孙怒气大发，就上他父亲的家去了。","notes":[]},{"n":20,"t":"参孙的妻子就归了参孙的一个同伴，就是作过他伴郎的。","notes":[]}]},"15":{"heading":"参孙击败非利士人","verses":[{"n":1,"t":"过了些日子，在割麦子的时候，参孙带着一只小山羊去探望他的妻子，说：“我要进内室到我妻子那里。”他岳父不许他进去。","notes":[]},{"n":2,"t":"他岳父说：“我以为你极其恨她，因此我把她给了你的同伴。她妹妹不是比她更美丽吗？你可以娶来代替她！”","notes":[]},{"n":3,"t":"参孙对他们说：“这一次我若加害非利士人，就不算是我的错了。”","notes":[]},{"n":4,"t":"于是参孙去捉了三百只狐狸，把它们的尾巴一对一对地绑住，再将火把绑在两条尾巴中间。","notes":[]},{"n":5,"t":"他点着火把，把狐狸放进非利士人直立的庄稼，把堆积的禾捆和直立的庄稼，葡萄园、橄榄园全都烧了。","notes":[]},{"n":6,"t":"非利士人说：“这事是谁做的呢？”有人说：“是亭拿人的女婿参孙做的，因为他岳父把他的妻子给了他的同伴。”于是非利士人上去，用火烧了女子和她的父亲。","notes":[]},{"n":7,"t":"参孙对他们说：“你们既然这么做，我必向你们报仇才肯罢休。”","notes":[]},{"n":8,"t":"参孙狠狠击杀他们，把他们连腿带腰都砍了。过后，他就下去，住在以坦岩的石洞里。","notes":[]},{"n":9,"t":"非利士人上去，安营在犹大，侵犯利希。","notes":[]},{"n":10,"t":"犹大人说：“你们为何上来攻击我们呢？”他们说：“我们上来是要捆绑参孙，照他向我们所做的对待他。”","notes":[]},{"n":11,"t":"于是，三千犹大人下到以坦岩的石洞里，对参孙说：“非利士人辖制我们，你不知道吗？你向我们做的是什么事呢？”他说：“他们向我怎样做，我也要向他们怎样做。”","notes":[]},{"n":12,"t":"犹大人对他说：“我们下来是要捆绑你，把你交在非利士人手中。”参孙说：“你们要向我起誓，你们自己不杀害我。”","notes":[]},{"n":13,"t":"他们说：“我们绝不杀你，只把你捆绑，交在非利士人手中。”于是他们用两条新绳绑住参孙，把他从以坦岩带上去。","notes":[]},{"n":14,"t":"参孙到了利希，非利士人对着他喊叫。耶和华的灵大大感动参孙，他手臂上的绳子就像着火的麻一样，绑他的绳子从他手上脱落下来。","notes":[]},{"n":15,"t":"他找到一块未干的驴腮骨，就伸手拾起来，用它杀了一千人。","notes":[]},{"n":16,"t":"参孙说：“用驴腮骨，一堆又一堆；用驴腮骨，我杀了一千人。”","notes":["“一堆又一堆”：七十士译本是“我把他们完全除掉”。"]},{"n":17,"t":"说完这话，就把那腮骨从手里抛出去。因此，那地叫作拉末．利希。","notes":["“拉末．利希”意思是“腮骨冈”。"]},{"n":18,"t":"参孙非常口渴，就求告耶和华说：“你既藉仆人的手施行这么大的拯救，现在我要渴死，落在未受割礼的人手中吗？”","notes":[]},{"n":19,"t":"神就使利希的洼地裂开，从中涌出水来。参孙喝了，精神恢复。因此那泉名叫隐．哈歌利，直到今日它仍在利希。","notes":["“隐．哈歌利”意思是“呼求者的水泉”。"]},{"n":20,"t":"在非利士人辖制的时候，参孙作以色列的士师二十年。","notes":[]}]},"16":{"heading":"参孙和大利拉","verses":[{"n":1,"t":"参孙到了迦萨，在那里看见一个妓女，就与她亲近。","notes":[]},{"n":2,"t":"有人告诉迦萨人说：“参孙到这里来了！”他们就包围起来，整夜在城门埋伏等着他。他们整夜静悄悄地，说：“等到天一亮我们就杀他。”","notes":[]},{"n":3,"t":"参孙睡到半夜，在半夜起来，抓住城门的门扇和两个门框，把它们和门闩一起拆下来，扛在肩上，抬到希伯仑前面的山顶上。","notes":[]},{"n":4,"t":"这事以后，参孙在梭烈谷爱上了一个女子，名叫大利拉。","notes":[]},{"n":5,"t":"非利士人的领袖上去，到那女子那里，对她说：“请你哄骗参孙，探出他为何有这么大的力气，以及我们要用什么方法才能胜他，将他捆绑制伏。我们就每人给你一千一百块银子。”","notes":[]},{"n":6,"t":"大利拉对参孙说：“请你告诉我，你为何有这么大的力气，要用什么方法才能捆绑制伏你。”","notes":[]},{"n":7,"t":"参孙对她说：“若用七条未干的新绳子捆绑我，我就像平常人一样软弱。”","notes":[]},{"n":8,"t":"于是非利士人的领袖拿了七条未干的新绳子来，交给她，她就用绳子捆绑参孙。","notes":[]},{"n":9,"t":"当时，埋伏的人正在她的内室等着。她对参孙说：“参孙，非利士人来捉你了！”参孙就挣断绳子，绳子如遇到火的麻线断裂一样。这样，人还是不知道他的力量从哪里来。","notes":[]},{"n":10,"t":"大利拉对参孙说：“看哪，你欺骗我，对我说谎。现在请你告诉我，要用什么方法才能捆绑你。”","notes":[]},{"n":11,"t":"参孙对她说：“若用未曾用过的新绳子捆绑我，我就像平常人一样软弱。”","notes":[]},{"n":12,"t":"大利拉就用新绳子捆绑他，对他说：“参孙，非利士人来捉你了！”当时，埋伏的人在内室等着。参孙挣断手臂上的绳子，如挣断一条线一样。","notes":[]},{"n":13,"t":"大利拉对参孙说：“你到现在还是欺骗我，对我说谎。请你告诉我，要用什么方法才能捆绑你。”参孙对她说：“只要用织布的线将我头上的七条发绺编织起来就可以了”。","notes":[]},{"n":14,"t":"于是大利拉用梭子将他的发绺钉住，对他说：“参孙，非利士人来捉你了！”参孙从睡中醒来，将织布机上的梭子和织布的线一齐都拔出来了。","notes":[]},{"n":15,"t":"大利拉对参孙说：“你既不与我同心，怎么能说‘我爱你’呢？你这三次欺骗我，不告诉我，你为什么有这么大的力气。”","notes":[]},{"n":16,"t":"大利拉天天用话催逼他，纠缠他，他就心里烦得要死，","notes":[]},{"n":17,"t":"终于把心中的一切都告诉她。参孙对她说：“从来没有人用剃刀剃我的头，因为我一出母胎就归给神作拿细耳人。若有人剃了我的头发，我的力气就会离开我，我就像平常人一样软弱。”","notes":[]},{"n":18,"t":"大利拉见他说出了心中的一切，就派人去召非利士人的领袖，说：“请再上来一次，因为他已经说出了心中的一切。”于是非利士人的领袖手里拿着银子，上到她那里。","notes":[]},{"n":19,"t":"大利拉哄参孙睡在她的膝上，叫一个人来剃掉参孙头上的七条发绺。于是大利拉开始制伏参孙，他的力气就离开他了。","notes":[]},{"n":20,"t":"大利拉说：“参孙，非利士人来捉你了！”参孙从睡中醒来，说：“我要像前几次一样脱身而去。”他却不知道耶和华已经离开他了。","notes":[]},{"n":21,"t":"非利士人逮住他，挖了他的眼睛，带他下到迦萨，用铜链锁住他，叫他在监狱里推磨。","notes":[]},{"n":22,"t":"然而他的头发被剃以后，又开始长起来了。","notes":[]},{"n":23,"t":"非利士人的领袖聚集，要向他们的神明大衮献大祭，并且庆祝，说：“我们的神明把我们的仇敌参孙交在我们手中了。”","notes":[],"heads":["参孙的死"]},{"n":24,"t":"众人看见参孙，就赞美他们的神明说：“我们的神明把那毁坏我们的地、杀害我们许多人的仇敌交在我们手中了。”","notes":[]},{"n":25,"t":"他们心里高兴的时候，就说：“叫参孙来，逗我们欢乐。”于是他们把参孙从监狱里提出来，在他们面前戏耍。他们叫他站在两根柱子中间。","notes":[]},{"n":26,"t":"参孙对牵他手的僮仆说：“让我摸摸支撑这庙宇的柱子，我要靠一靠。”","notes":[]},{"n":27,"t":"那时庙宇内充满男女，非利士人的众领袖也都在那里，屋顶上约有三千男女观看参孙逗他们欢乐。","notes":[]},{"n":28,"t":"参孙求告耶和华说：“主耶和华啊，求你眷念我。神啊，就这一次，求你赐给我力量，使我向非利士人报那挖我双眼的仇。”","notes":[]},{"n":29,"t":"参孙抱住中间支撑庙宇的两根柱子，左手抱一根，右手抱一根。","notes":[]},{"n":30,"t":"然后他说：“让我与非利士人一起死吧！”他尽力弯腰，庙宇就倒塌了，压住领袖和庙宇内的众人。这样，参孙死的时候所杀的人比活着所杀的还多。","notes":[]},{"n":31,"t":"他的兄弟和他父亲的全家都下去收他的尸首，抬上去，葬在琐拉和以实陶中间、他父亲玛挪亚的坟墓里。参孙作以色列的士师二十年。","notes":[]}]},"17":{"heading":"米迦的偶像","verses":[{"n":1,"t":"以法莲山区有一个人，名叫米迦。","notes":[]},{"n":2,"t":"他对母亲说：“你的一千一百块银子被人拿走了，为此你发咒起誓，也说给我听。看哪，银子在我这里，是我拿的。”他母亲说：“愿我儿蒙耶和华赐福！”","notes":[]},{"n":3,"t":"米迦把这一千一百块银子还他母亲。他母亲说：“我把这银子分别为圣，亲手献给耶和华，为我儿子造一尊雕刻的像，以及一尊铸成的像。现在我把银子交给你。”","notes":[]},{"n":4,"t":"米迦把银子还他母亲，他母亲把二百块银子交给银匠，去造一尊雕刻的像，以及一尊铸成的像，安置在米迦的房子里。","notes":[]},{"n":5,"t":"米迦这个人有了神堂，又造了以弗得和家中的神像，派他的一个儿子作祭司。","notes":[]},{"n":6,"t":"那时，以色列中没有王，各人照自己眼中看为对的去做。","notes":[]},{"n":7,"t":"犹大的伯利恒有一个年轻人，是犹大族的人。他是利未人，寄居在那里。","notes":[]},{"n":8,"t":"这人离开犹大的伯利恒城，要找一个可住的地方。他来到以法莲山区米迦的家，还要往前走。","notes":[]},{"n":9,"t":"米迦对他说：“你从哪里来？”他说：“我从犹大的伯利恒来。我是利未人，要找一个可住的地方。”","notes":[]},{"n":10,"t":"米迦说：“你就住在我这里吧！我以你为父为祭司，每年给你十块银子和一套衣服，以及生活所需的食物。”利未人就来了。","notes":[]},{"n":11,"t":"利未人愿意和这人同住；他待这年轻人如自己的儿子一样。","notes":[]},{"n":12,"t":"米迦授这年轻的利未人祭司的职任，他就住在米迦的家里。","notes":[]},{"n":13,"t":"米迦说：“现在我知道耶和华必恩待我，因为我有利未人作我的祭司。”","notes":[]}]},"18":{"heading":"但支派的迁移","verses":[{"n":1,"t":"那时，以色列中没有王。但支派的人还在觅地居住，因为直到那日，他们还没有在以色列支派中抽签得地为业。","notes":[]},{"n":2,"t":"但人从琐拉和以实陶派本族中的五个勇士，去窥探侦察那地，对他们说：“你们去侦察那地。”他们来到以法莲山区米迦的家中，就在那里住宿。","notes":[]},{"n":3,"t":"他们临近米迦的家，听出那年轻的利未人的口音，就绕到那里，对他说：“谁领你到这里来？你在这里做什么？你在这里得了什么？”","notes":[]},{"n":4,"t":"他对他们说：“米迦如此如此待我，他雇用我，我就作了他的祭司。”","notes":[]},{"n":5,"t":"他们对他说：“请你求问神，使我们知道所走的道路是否通达。”","notes":[]},{"n":6,"t":"祭司对他们说：“你们平平安安去吧，你们所行的道路是在耶和华面前的。”","notes":[]},{"n":7,"t":"五人就走了，来到拉亿，见那里的人安居，像西顿人的生活一样安宁无虑，那地无人羞辱他们，无人夺取侵略。他们离西顿人很远，与世无争。","notes":["“与世无争”：七十士译本是“与叙利亚没有争执”；下同。"]},{"n":8,"t":"五人回到琐拉和以实陶他们的弟兄那里。他们的弟兄对他们说：“你们怎么了？”","notes":[]},{"n":9,"t":"他们说：“起来，我们上去攻打他们吧！我们已经窥探了那地，看哪，那地非常好。你们还要待在这里吗？不要再迟延了，立刻出发去得那地为业吧！","notes":[]},{"n":10,"t":"你们去，必来到安居的百姓和两边辽阔的地。神已将那地方交在你们手中了；那里不缺地上的任何东西。”","notes":[]},{"n":11,"t":"于是但族的六百人，各带兵器，从琐拉和以实陶出发，","notes":[]},{"n":12,"t":"上到犹大的基列．耶琳，在那里安营。因此那地方名叫玛哈尼．但，直到今日。看哪，它在基列．耶琳的西边。","notes":[]},{"n":13,"t":"他们从那里往以法莲山区去，来到米迦的家。","notes":[]},{"n":14,"t":"先前窥探拉亿地的五个人对他们的弟兄说：“你们知道吗？这些屋子里有以弗得和家中的神像，以及一尊雕刻的像与一尊铸成的像。现在你们要知道该怎么做。”","notes":[]},{"n":15,"t":"五人转身，进入米迦的家，来到那年轻利未人的房间，向他问安。","notes":[]},{"n":16,"t":"六百但人各带兵器，站在门口。","notes":[]},{"n":17,"t":"那窥探这地的五个人上前去，进入里面，拿走雕刻的像、以弗得、家中的神像，以及铸成的像。祭司和带兵器的六百人一同站在门口。","notes":[]},{"n":18,"t":"当五个人进入米迦的家，拿走雕刻的像、以弗得、家中的神像，以及铸成的像，祭司对他们说：“你们做什么呢？”","notes":[]},{"n":19,"t":"他们对他说：“不要作声，用手捂口，跟我们去吧！我们必以你为父为祭司。你作一家的祭司好呢？还是作以色列一支派一族的祭司好呢？”","notes":[]},{"n":20,"t":"祭司心里欢喜，拿着以弗得和家中的神像，以及雕刻的像，跟这些百姓走了。","notes":[]},{"n":21,"t":"他们转身离开那里，把孩子、牲畜、财物安排在前头。","notes":[]},{"n":22,"t":"他们离了米迦的家已远，米迦家附近的邻居被召来，追赶但人。","notes":[]},{"n":23,"t":"他们呼叫但人，但人回头对米迦说：“你召集这许多人来做什么呢？”","notes":[]},{"n":24,"t":"米迦说：“你们把我所造的神像，还有祭司，都带走了，我还有什么呢？你怎么还对我说‘你在做什么’呢？”","notes":[]},{"n":25,"t":"但人对米迦说：“你不要让我们再听见你的声音，恐怕这群恼怒成性的人会攻击你们，你和你的全家就会丧命。”","notes":[]},{"n":26,"t":"但人仍走他们的路。米迦见他们的势力比自己强，就转身回家去了。","notes":[]},{"n":27,"t":"但人把米迦造的神像和他的祭司带走，来到拉亿安宁无虑的百姓那里，用刀杀了他们，放火烧了那城。","notes":[]},{"n":28,"t":"没有人来搭救，因为这城离西顿很远，他们又与世无争；这城在靠近伯．利合的平原。但人建造这城，在那里居住，","notes":[]},{"n":29,"t":"并照着他们祖先以色列之子但的名字，给这城起名叫但。原先这城名叫拉亿。","notes":[]},{"n":30,"t":"但人为自己设立了那雕刻的像。摩西的孙子，革舜的儿子约拿单和他的子孙作但支派的祭司，直到那地遭掳掠的日子。","notes":[]},{"n":31,"t":"神的家在示罗多少日子，但人为自己设立米迦所雕刻的像也在但多少日子。","notes":[]}]},"19":{"heading":"一个利未人和他的妾","verses":[{"n":1,"t":"当以色列中没有王的时候，有一个利未人寄居以法莲山区的边界，他娶了一个犹大伯利恒的女子为妾。","notes":[]},{"n":2,"t":"这妾对丈夫生气，离开丈夫，回到犹大伯利恒的父家，在那里住了四个月。","notes":["“对丈夫生气”或译“行淫，对丈夫不忠”。"]},{"n":3,"t":"她的丈夫起来，带着一个仆人、两匹驴跟着她去，要用好话劝她回来。女子就带丈夫进到父亲家里。女子的父亲看见了他，就欢欢喜喜地迎接他。","notes":[]},{"n":4,"t":"这岳父，就是女子的父亲，留他住了三天。他们在那里吃喝，住宿。","notes":[]},{"n":5,"t":"第四日，他们清早起来，利未人起身要走，女子的父亲对女婿说：“先吃点东西，加添心力，然后你们才走。”","notes":[]},{"n":6,"t":"于是二人坐下，一同吃喝。女子的父亲对那人说：“请你答应再住一夜，使你的心舒畅。”","notes":[]},{"n":7,"t":"那人起身要走，他岳父挽留他，他就留下，在那里又住了一夜。","notes":[]},{"n":8,"t":"第五日，他清早起来要走，女子的父亲说：“来，请加添心力，留到太阳偏西吧。”于是二人一同再吃。","notes":[]},{"n":9,"t":"那人同他的妾和仆人起身要走，但他岳父，就是女子的父亲，对他说：“看哪，太阳下山，天快晚了，你们再住一夜吧。看哪，太阳偏西了，就在这里住宿，使你的心舒畅，明天你们一早起来上路，回你的帐棚去。”","notes":[]},{"n":10,"t":"那人不愿再住一夜，就备上两匹驴，带着他的妾起身走了，来到耶布斯的对面，耶布斯就是耶路撒冷。","notes":[]},{"n":11,"t":"将近耶布斯的时候，太阳快下山了，仆人对主人说：“来吧，我们进这耶布斯人的城，在这里住宿。”","notes":[]},{"n":12,"t":"主人对他说：“我们不可进入外邦人的城，那不是以色列人的地方，我们越过这里到基比亚去吧。”","notes":[]},{"n":13,"t":"他又对仆人说：“来，让我们到基比亚或拉玛的一个地方住宿。”","notes":[]},{"n":14,"t":"于是他们越过那里往前走，将到便雅悯的基比亚的时候，太阳已经下山了。","notes":[]},{"n":15,"t":"他们进入基比亚要在那里住宿。他来坐在城里的广场上，但没有人接待他们到家里住宿。","notes":[]},{"n":16,"t":"看哪，晚上有一个老人从田间做工回来。他是以法莲山区的人，寄居在基比亚；那地方的人是便雅悯人。","notes":[]},{"n":17,"t":"老人举目看见那过路的人在城里的广场上，就说：“你从哪里来？要到哪里去？”","notes":[]},{"n":18,"t":"他对他说：“我们从犹大的伯利恒过来，要到以法莲山区的边界去。我是那里的人，去了犹大的伯利恒，现在要到耶和华的家去，却没有人接待我到他的家。","notes":[]},{"n":19,"t":"其实我有饲料草料可以喂驴，我和你的使女，以及与我们在一起的仆人都有饼有酒，什么都不缺。”","notes":[]},{"n":20,"t":"老人说：“愿你平安！你所需用的我都会给你们，只是不可在广场上过夜。”","notes":[]},{"n":21,"t":"于是老人领他到家里，喂上驴。他们洗了脚，就吃喝起来。","notes":[]},{"n":22,"t":"他们心里欢乐的时候，看哪，城中的无赖围住房子，连连叩门，对老人，这家的主人说：“把那进你家的人带出来，我们要与他交合。”","notes":[],"heads":["基比亚的恶行"]},{"n":23,"t":"这家的主人出来对他们说：“弟兄们，不要做这样的恶事。这人既然进了我的家，你们就不要做这样可耻的事。","notes":[]},{"n":24,"t":"看哪，我有个女儿还是处女，还有这人的妾，我把她们领出来任由你们污辱她们，就照你们看为好的对待她们吧！但对这人你们不要做这样可耻的事。”","notes":[]},{"n":25,"t":"那些人却不肯听从他。那人抓住他的妾，把她拉出去给他们。他们强奸了她，整夜凌辱她，直到早晨，天色快亮才放她走。","notes":[]},{"n":26,"t":"到了早晨，妇人回来，仆倒在留她主人住宿的那人的家门前，直到天亮。","notes":[]},{"n":27,"t":"早晨，她的主人起来开了门，出去要上路。看哪，那妇人，他的妾倒在屋子门前，双手搭在门槛上。","notes":[]},{"n":28,"t":"他对妇人说：“起来，我们走吧！”妇人却没有回应。那人就将她驮在驴上，起身回自己的地方去了。","notes":[]},{"n":29,"t":"到了家里，他拿刀，抓住他的妾，把她的尸身切成十二块，分送到以色列全境。","notes":[]},{"n":30,"t":"凡看见的人都说：“自从以色列人离开埃及地上来，直到今日，像这样的事还没有发生过，也没有见过。大家应当想一想，商讨一下再说。”","notes":[]}]},"20":{"heading":"以色列人准备打仗","verses":[{"n":1,"t":"于是以色列众人从但到别是巴，以及从基列地出来，如同一人，聚集在米斯巴耶和华那里。","notes":[]},{"n":2,"t":"以色列各支派中众百姓的领袖，都站在神百姓的会中。拿刀的步兵共有四十万。","notes":[]},{"n":3,"t":"便雅悯人听见以色列人上了米斯巴。以色列人说：“请说，这恶事是怎么发生的呢？”","notes":[]},{"n":4,"t":"那利未人，就是被害妇人的丈夫，回答说：“我和我的妾来到便雅悯的基比亚住宿。","notes":[]},{"n":5,"t":"基比亚人夜间起来攻击我，包围我住的屋子。他们想要杀我，并把我的妾污辱致死。","notes":[]},{"n":6,"t":"我把我的妾切成块，分送到以色列得为业的全地，因为基比亚人在以色列中做了邪恶可耻的事。","notes":[]},{"n":7,"t":"看哪，你们大家，以色列人哪，在此提出你们的建议和对策吧！”","notes":[]},{"n":8,"t":"众百姓都起来如同一人，说：“我们谁也不回自己的帐棚，谁也不回自己的家去！","notes":[]},{"n":9,"t":"现在，我们要这样对付基比亚，照所抽的签去攻打他们。","notes":[]},{"n":10,"t":"我们要在以色列各支派中，一百人选十人，一千人选一百人，一万人选一千人，为那到便雅悯的迦巴去的士兵运粮；因为基比亚在以色列中行了可耻的事。”","notes":[]},{"n":11,"t":"于是以色列众人彼此联合如同一人，聚集攻击那城。","notes":[]},{"n":12,"t":"以色列众支派派人去，问便雅悯支派的各家说：“你们中间怎么做了这样的恶事呢？","notes":[]},{"n":13,"t":"现在你们要把基比亚的那些无赖交出来，我们好处死他们，从以色列中除掉这恶。”便雅悯人却不肯听从他们弟兄以色列人的话。","notes":[]},{"n":14,"t":"便雅悯人从各城聚集到基比亚，出来要与以色列人打仗。","notes":[]},{"n":15,"t":"那日，便雅悯人从各城里征召了拿刀的士兵，共有二万六千，另外还从基比亚居民中征召七百个精兵。","notes":[]},{"n":16,"t":"全军中有特选的七百个精兵，都是惯用左手的，个个能用机弦甩石，毫发不差。","notes":[]},{"n":17,"t":"以色列人，除了便雅悯之外，共征召了四十万拿刀的，个个都是战士。","notes":[]},{"n":18,"t":"以色列人起来，上到伯特利去求问神说：“我们中间谁当首先上去与便雅悯人争战呢？”耶和华说：“犹大先上去。”","notes":[],"heads":["以色列人击败便雅悯人"]},{"n":19,"t":"以色列人早晨起来，对着基比亚安营。","notes":[]},{"n":20,"t":"以色列人出来与便雅悯人打仗，以色列人在基比亚对着他们摆阵。","notes":[]},{"n":21,"t":"便雅悯人从基比亚出来，当日把以色列中二万二千人杀倒在地。","notes":[]},{"n":22,"t":"以色列人的士兵鼓起勇气，在第一日摆阵的地方又摆阵。","notes":[]},{"n":23,"t":"因以色列人上去，在耶和华面前哀哭，直到晚上。他们求问耶和华说：“我可以再出兵与我弟兄便雅悯人打仗吗？”耶和华说：“可以上去攻打他们。”","notes":[]},{"n":24,"t":"第二日，以色列人就上前攻击便雅悯人。","notes":[]},{"n":25,"t":"便雅悯人也在第二日从基比亚出来与他们交战，又把以色列人一万八千个拿刀的士兵杀倒在地。","notes":[]},{"n":26,"t":"以色列众人和全体士兵上到伯特利，坐在耶和华面前哭泣。那日，他们禁食直到晚上，又在耶和华面前献燔祭和平安祭。","notes":[]},{"n":27,"t":"以色列人去求问耶和华；那时，神的约柜在那里。","notes":[]},{"n":28,"t":"那时，亚伦的孙子，以利亚撒的儿子非尼哈侍立在约柜前。他们说：“我可以再出去与我弟兄便雅悯人打仗吗？还是停战呢？”耶和华说：“你们可以上去，因为明日我必把他交在你手中。”","notes":[]},{"n":29,"t":"以色列在基比亚的四围设下埋伏。","notes":[]},{"n":30,"t":"第三日，以色列人又上去攻击便雅悯人，在基比亚前摆阵，与前两次一样。","notes":[]},{"n":31,"t":"便雅悯人也出来迎敌，就被引诱出城外。在田间的两条路上，一条通往伯特利，一条通往基比亚，他们像前两次一样，动手杀了约三十个以色列人。","notes":[]},{"n":32,"t":"便雅悯人说：“他们仍像以前一样败在我们面前。”但以色列人说：“让我们逃跑，引诱他们离开城到路上来。”","notes":[]},{"n":33,"t":"以色列众人都起来，在巴力．他玛摆阵，以色列的伏兵从马利．迦巴埋伏的地方冲上前去。","notes":[]},{"n":34,"t":"全以色列中的一万精兵来到基比亚前，战争十分激烈。便雅悯人却不知道灾祸临近了。","notes":[]},{"n":35,"t":"耶和华在以色列面前击打便雅悯。那日，以色列人歼灭二万五千一百个便雅悯人，都是拿刀的士兵。","notes":[]},{"n":36,"t":"便雅悯人看到自己战败了。以色列人因为信任在基比亚前所设的伏兵，就在便雅悯人面前假装撤退。","notes":[],"heads":["以色列人得胜"]},{"n":37,"t":"伏兵迅速闯进基比亚；他们继续前进，用刀杀死全城的人。","notes":[]},{"n":38,"t":"以色列人预先与伏兵约定在城内放火，以上腾的烟为信号。","notes":[]},{"n":39,"t":"以色列人从阵上撤退，便雅悯人动手杀死以色列人，约有三十个，就说：“他们仍像以前一样败在我们面前。”","notes":[]},{"n":40,"t":"当烟如柱一般从城中上腾的时候，便雅悯人回头，看哪，全城已经浓烟冲天了。","notes":[]},{"n":41,"t":"以色列人又转身回来，便雅悯人就很惊惶，因为看见灾祸临到自己了。","notes":[]},{"n":42,"t":"他们在以色列人面前转身往旷野逃跑，战况对他们不利，那从城里出来的也去夹攻，杀灭他们。","notes":[]},{"n":43,"t":"以色列人围攻便雅悯人，追赶他们，在他们歇脚之处，直到向日出方向的基比亚的对面，践踏他们。","notes":[]},{"n":44,"t":"便雅悯人倒下的有一万八千名，这些全都是勇士。","notes":[]},{"n":45,"t":"其余的人转身往旷野逃跑，到临门岩去。以色列人在路上杀了五千人，如拾穗一样，紧追他们直到基顿，又杀了二千人。","notes":[]},{"n":46,"t":"那日便雅悯人倒下的有二万五千名，这些全都是拿刀的勇士。","notes":[]},{"n":47,"t":"有六百人转身往旷野逃跑，到了临门岩，在临门岩住了四个月。","notes":[]},{"n":48,"t":"以色列人又转回去攻击便雅悯人，凡经过的各城，其中的人和牲畜都用刀杀了，又放火烧了所经过的一切城镇。","notes":[]}]},"21":{"heading":"为便雅悯人找妻子","verses":[{"n":1,"t":"以色列人在米斯巴曾起誓说：“我们中谁都不把女儿嫁给便雅悯人。”","notes":[]},{"n":2,"t":"以色列人来到伯特利，坐在那里直到晚上，在神面前放声大哭，","notes":[]},{"n":3,"t":"说：“耶和华－以色列的神啊，为何以色列中会发生这样的事，使以色列今日缺了一个支派呢？”","notes":[]},{"n":4,"t":"次日，百姓清早起来，在那里筑了一座坛，献燔祭和平安祭。","notes":[]},{"n":5,"t":"以色列人说：“以色列各支派中，谁没有同会众一起上到耶和华那里呢？”因为以色列人曾起重誓说：“凡不上米斯巴到耶和华那里的，必被处死。”","notes":[]},{"n":6,"t":"以色列人怜悯他们的弟兄便雅悯，说：“如今以色列中断绝一个支派了。","notes":[]},{"n":7,"t":"我们既然向耶和华起誓说，必不把我们的女儿嫁给便雅悯人，现在我们该怎么办，使他们剩下的人可以娶妻呢？”","notes":[]},{"n":8,"t":"他们又说：“以色列支派中谁没有上米斯巴到耶和华那里呢？”看哪，基列的雅比没有一人进营到会众那里，","notes":[]},{"n":9,"t":"百姓被数点的时候，看哪，基列的雅比居民没有一人在那里。","notes":[]},{"n":10,"t":"会众就派一万二千名大勇士，吩咐他们说：“你们去用刀把基列的雅比居民连妇女带孩子都杀了。","notes":[]},{"n":11,"t":"这是你们当做的事：要把所有男人和曾与男人同房共寝的女人全都杀了。”","notes":[]},{"n":12,"t":"他们在基列的雅比居民中，找到四百个未曾与男人同房共寝的处女，就带她们到迦南地的示罗营里。","notes":[]},{"n":13,"t":"全会众派人到临门岩的便雅悯人那里，与他们讲和。","notes":[]},{"n":14,"t":"当时便雅悯人回来了，以色列人就把所留下，基列的雅比活着的女子嫁给他们，可是还是不够。","notes":[]},{"n":15,"t":"百姓怜悯便雅悯人，因为耶和华使以色列支派中有一个缺口。","notes":[]},{"n":16,"t":"会众中的长老说：“便雅悯中的女子既然都除灭了，我们该怎么办，使剩下的人可以娶妻呢？”","notes":[]},{"n":17,"t":"他们又说：“便雅悯逃脱的人应当有地业，免得以色列中的一个支派被涂去。","notes":[]},{"n":18,"t":"只是我们不能把自己的女儿嫁给他们。”因为以色列人曾起誓说：“把女儿嫁给便雅悯人的必受诅咒。”","notes":[]},{"n":19,"t":"他们又说：“看哪，一年一度耶和华的节期正在示罗举行。”示罗位于利波拿的南边，伯特利的北边，从伯特利往示剑大路的东边。","notes":[]},{"n":20,"t":"他们吩咐便雅悯人说：“你们去，躲在葡萄园中，","notes":[]},{"n":21,"t":"观看；看哪，若示罗的女子出来跳舞，你们就从葡萄园出来，各人从示罗的女子中抢一个为妻，然后到便雅悯地去。","notes":[]},{"n":22,"t":"他们的父亲或兄弟若来与我们争论，我们就对他们说：‘请看我们的情面恩待这些人吧！因为我们在战争的时候没有给他们任何人留下女子为妻。这次也不是你们给他们的，若是你们给的，就算有罪了。’”","notes":[]},{"n":23,"t":"于是便雅悯人就照样做了，按照他们的人数，把从跳舞女子中抢来的娶为妻子，带回自己的地业，重建城镇，居住在其中。","notes":[]},{"n":24,"t":"那时以色列人离开那里，各自回到自己的支派、宗族；他们从那里起行，各自回到自己的地业去了。","notes":[]},{"n":25,"t":"那时，以色列中没有王，各人照自己眼中看为对的去做。","notes":[]}]}},"RUT":{"1":{"heading":"以利米勒全家迁往摩押","verses":[{"n":1,"t":"士师统治的时候，国中有饥荒。在犹大的伯利恒，有一个人带着妻子和两个儿子往摩押地去寄居。","notes":[]},{"n":2,"t":"这人名叫以利米勒，他的妻子名叫拿娥米；他两个儿子，一个名叫玛伦，一个名叫基连，都是犹大伯利恒的以法他人。他们到了摩押地，就住在那里。","notes":[]},{"n":3,"t":"后来拿娥米的丈夫以利米勒死了，剩下她和两个儿子。","notes":[]},{"n":4,"t":"两个儿子娶了摩押女子，一个名叫俄珥巴，第二个名叫路得，在那里住了约有十年。","notes":[]},{"n":5,"t":"玛伦和基连二人也死了，剩下拿娥米，没有丈夫，也没有儿子。","notes":[]},{"n":6,"t":"拿娥米与两个媳妇起身，要从摩押地回去，因为她在摩押地听见耶和华眷顾自己的百姓，赐粮食给他们。","notes":[],"heads":["路得跟拿娥米回伯利恒"]},{"n":7,"t":"她和两个媳妇就起行，离开所住的地方，上路回犹大地去。","notes":[]},{"n":8,"t":"拿娥米对两个媳妇说：“你们各自回娘家去吧！愿耶和华恩待你们，像你们待已故的人和我一样。","notes":[]},{"n":9,"t":"愿耶和华使你们各自在新的丈夫家中得归宿！”于是拿娥米与她们亲吻，她们就放声大哭，","notes":[]},{"n":10,"t":"对她说：“不，我们要与你一同回你的百姓那里去。”","notes":[]},{"n":11,"t":"拿娥米说：“我的女儿啊，回去吧！为何要跟我去呢？我还能生儿子作你们的丈夫吗？","notes":[]},{"n":12,"t":"我的女儿啊，回去吧！我年纪老了，不能再有丈夫。就算我还有希望，今夜有丈夫，而且也生了儿子，","notes":[]},{"n":13,"t":"你们岂能等着他们长大呢？你们能守住自己不嫁人吗？我的女儿啊，不要这样。我比你们更苦，因为耶和华伸手击打我。”","notes":[]},{"n":14,"t":"两个媳妇又放声大哭，俄珥巴与婆婆吻别，但是路得却紧跟着拿娥米。","notes":[]},{"n":15,"t":"拿娥米说：“看哪，你嫂嫂已经回她的百姓和她的神明那里去了，你也跟你嫂嫂回去吧！”","notes":[]},{"n":16,"t":"路得说：“不要劝我离开你，转去不跟随你。你往哪里去，我也往哪里去；你在哪里住，我也在哪里住；你的百姓就是我的百姓；你的神就是我的神。","notes":[]},{"n":17,"t":"你死在哪里，我也死在哪里，葬在哪里。只有死能使你我分离；不然，愿耶和华重重惩罚我！”","notes":[]},{"n":18,"t":"拿娥米见路得决意要跟自己去，就不再对她说什么了。","notes":[]},{"n":19,"t":"于是二人同行，来到伯利恒。她们到了伯利恒，全城因她们骚动起来。妇女们说：“这是拿娥米吗？”","notes":[]},{"n":20,"t":"拿娥米对她们说：“不要叫我拿娥米，要叫我玛拉，因为全能者使我受尽了苦。","notes":["“拿娥米”意思是“甜”。","“玛拉”意思是“苦”。"]},{"n":21,"t":"我满满地出去，耶和华使我空空地回来。耶和华使我受苦，全能者降祸于我。你们为何还叫我拿娥米呢？”","notes":[]},{"n":22,"t":"拿娥米从摩押地回来了，她的媳妇摩押女子路得跟她在一起。她们到了伯利恒，正是开始收割大麦的时候。","notes":[]}]},"2":{"heading":"路得在田间遇见波阿斯","verses":[{"n":1,"t":"拿娥米有一个亲戚，是她丈夫以利米勒本族的人，名叫波阿斯，是个大财主。","notes":[]},{"n":2,"t":"摩押女子路得对拿娥米说：“让我到田里去拾取麦穗，我在谁的眼中蒙恩，就跟在谁的身后。”拿娥米说：“女儿啊，你去吧。”","notes":[]},{"n":3,"t":"路得就去了。她来到田间，在收割的人身后拾取麦穗。她恰巧来到以利米勒本族的人波阿斯那块田里。","notes":[]},{"n":4,"t":"看哪，波阿斯正从伯利恒来，对收割的人说：“愿耶和华与你们同在！”他们对他说：“愿耶和华赐福给你！”","notes":[]},{"n":5,"t":"波阿斯对监督收割的仆人说：“那是谁家的女子？”","notes":[]},{"n":6,"t":"监督收割的仆人回答说：“她是摩押女子，跟随拿娥米从摩押地回来的。","notes":[]},{"n":7,"t":"她说：‘请你容许我拾取麦穗，在收割的人身后捡禾捆中掉落的麦穗。’她就来了，从早晨直到如今，除了在屋子里坐一会儿，她都留在这里。”","notes":[]},{"n":8,"t":"波阿斯对路得说：“女儿啊，听我说，不要到别人田里去拾取麦穗，也不要离开这里，要紧跟着我的女仆们。","notes":[]},{"n":9,"t":"你要看好我的仆人正在哪块田收割，就跟着女仆们去。我已经吩咐仆人不可侵犯你。你渴了，可以到水缸那里喝仆人打来的水。”","notes":[]},{"n":10,"t":"路得就脸伏于地叩拜，对他说：“我既是外邦女子，怎么会在你眼中蒙恩，使你这样照顾我呢？”","notes":[]},{"n":11,"t":"波阿斯回答她说：“自从你丈夫死后，凡你向婆婆所行的，以及你离开父母和你的出生地，到素不相识的百姓中，这些事人都告诉我了。","notes":[]},{"n":12,"t":"愿耶和华照你所行的报偿你。你来投靠在耶和华－以色列神的翅膀下，愿你满得他的报偿。”","notes":[]},{"n":13,"t":"路得说：“我主啊，愿我在你眼前蒙恩。我虽然不及你的一个婢女，你还安慰我，对你的婢女说关心的话。”","notes":[]},{"n":14,"t":"吃饭的时候，波阿斯对路得说：“你到这里来吃些饼，把你的一块蘸在醋里。”路得就在收割的人旁边坐下。波阿斯把烘了的穗子递给她。她吃饱了，还有剩余的。","notes":[]},{"n":15,"t":"她又起来拾取麦穗，波阿斯吩咐仆人说：“她即使在禾捆中拾取麦穗，也不可羞辱她。","notes":[]},{"n":16,"t":"你们还要从捆里抽一些出来，留给她拾取，不可责备她。”","notes":[]},{"n":17,"t":"这样，路得在田间拾取麦穗，直到晚上。她把所拾取的麦穗打了约有一伊法的大麦。","notes":[]},{"n":18,"t":"路得把所拾取的带进城去给婆婆看，又把她吃饱所剩的拿出来，给了婆婆。","notes":[]},{"n":19,"t":"婆婆问她说：“你今日在哪里拾取麦穗？在哪里做工呢？愿那照顾你的得福。”路得告诉婆婆，她在谁那里做工，说：“我今日在一个名叫波阿斯的人那里做工。”","notes":[]},{"n":20,"t":"拿娥米对媳妇说：“愿那人蒙耶和华赐福，因为他不断地恩待活人死人。”拿娥米又对她说：“那人是我们本族的人，是一个可以赎我们产业的至亲。”","notes":[]},{"n":21,"t":"摩押女子路得说：“他还对我说：‘你要紧跟着我的仆人拾取麦穗，直到他们把我所有的庄稼收割完毕。’”","notes":[]},{"n":22,"t":"拿娥米对媳妇路得说：“女儿啊，你要跟着他的女仆出去，免得你在别人的田间受人骚扰。”","notes":[]},{"n":23,"t":"于是路得紧跟着波阿斯的女仆拾取麦穗，直到大麦和小麦收割完毕。路得仍与婆婆同住。","notes":[]}]},"3":{"heading":"拿娥米为路得找归宿","verses":[{"n":1,"t":"路得的婆婆拿娥米对她说：“女儿啊，我不该为你找个归宿，使你享福吗？","notes":[]},{"n":2,"t":"你与波阿斯的女仆常在一处，现在，波阿斯不是我们的亲人吗？看哪，他今夜将在禾场簸大麦。","notes":[]},{"n":3,"t":"你要沐浴抹膏，穿上外衣，下到禾场，一直到那人吃喝完了，都不要让他认出你来。","notes":[]},{"n":4,"t":"他躺下的时候，你看准他躺卧的地方，就进去掀露他的脚，躺卧在那里，他必告诉你所当做的事。”","notes":[]},{"n":5,"t":"路得说：“凡你所吩咐我的，我必遵行。”","notes":[]},{"n":6,"t":"路得就下到禾场，照她婆婆吩咐她的一切去做。","notes":[]},{"n":7,"t":"波阿斯吃喝完了，心情畅快，就去躺卧在麦堆旁边。路得悄悄走来，掀露他的脚，躺卧在那里。","notes":[]},{"n":8,"t":"到了半夜，那人惊醒，翻过身来，看哪，有个女子躺在他的脚旁。","notes":[]},{"n":9,"t":"他就说：“你是谁？”路得说：“我是你的使女路得。请你用你衣服的边来遮盖你的使女，因为你是可以赎我产业的至亲。”","notes":[]},{"n":10,"t":"波阿斯说：“女儿啊，愿你蒙耶和华赐福。你后来的忠诚比先前的更美，因为无论贫富的年轻人，你都没有跟从。","notes":[]},{"n":11,"t":"女儿啊，现在不要惧怕，凡你所说的，我必为你做，因为我城里的百姓都知道你是个贤德的女子。","notes":[]},{"n":12,"t":"现在，我的确是一个可以赎你产业的至亲，可是还有一个人比我更亲。","notes":[]},{"n":13,"t":"你今夜在这里住宿，明早他若肯为你尽至亲的本分，很好，就由他吧！倘若他不肯，我指着永生的耶和华起誓，我必为你尽上至亲的本分。你只管躺到早晨。”","notes":[]},{"n":14,"t":"路得就在他脚旁躺到早晨，在人还无法彼此辨认的时候就起来了。波阿斯说：“不可让人知道有女子到禾场来。”","notes":[]},{"n":15,"t":"他又对路得说：“把你所披的外衣拿来，握紧它。”她就握紧外衣，波阿斯量了六簸箕的大麦，帮路得扛上，他就进城去了。”","notes":["“他就进城去了”：有古卷和其他古译本是“她就进城去了”。"]},{"n":16,"t":"路得回到婆婆那里，婆婆说：“女儿啊，怎么样了？”路得就把那人向她所做的一切都告诉了婆婆，","notes":["“怎么样了”：原文直译“你是谁”。"]},{"n":17,"t":"又说：“那人给了我这六簸箕的大麦，对我说：‘你不可空手回去见婆婆。’”","notes":[]},{"n":18,"t":"婆婆说：“女儿啊，等着吧，看这事结果如何，因为那人今日不办妥这事，必不罢休。”","notes":[]}]},"4":{"heading":"波阿斯娶路得","verses":[{"n":1,"t":"波阿斯上到城门，坐在那里，看哪，波阿斯所说那个可以赎产业的至亲经过。波阿斯说：“某某先生，请你转回来，坐在这里。”他就转回来坐下。","notes":[]},{"n":2,"t":"波阿斯又请了本城的十个长老来，对他们说：“请你们坐在这里。”他们就都坐下。","notes":[]},{"n":3,"t":"波阿斯对那至亲说：“从摩押地回来的拿娥米，现在要卖我们弟兄以利米勒的那块地。","notes":[]},{"n":4,"t":"我想我应该向你说清楚：你可以买那块地，当着在座的众人和我百姓的长老面前，你若要赎就赎吧！倘若你不赎就告诉我，让我知道，因为除了你以外，没有人可以先赎，在你之后才轮到我。”那人说：“我要赎。”","notes":["“你不赎”是根据一些古卷和七十士译本；原文是“他不赎”。"]},{"n":5,"t":"波阿斯说：“你从拿娥米和摩押女子路得手中买这地的时候，也当买死人的妻子，使死人在产业上留名。”","notes":[]},{"n":6,"t":"那至亲说：“这样我就不能赎了，免得对我的产业有损。你尽管去赎我所当赎的吧，我不能赎了！”","notes":[]},{"n":7,"t":"从前，在以色列中要确认任何交易，无论是赎业或买卖，一方必须脱鞋给另一方。以色列中都以此为证。","notes":[]},{"n":8,"t":"那至亲对波阿斯说：“你自己买吧！”于是把鞋脱了下来。","notes":[]},{"n":9,"t":"波阿斯对长老和所有在场的百姓说：“你们今日都是证人；凡属以利米勒，以及基连和玛伦的，我都从拿娥米手中买下来了。","notes":[]},{"n":10,"t":"我也娶玛伦的妻子摩押女子路得，好让死人可以在产业上留名，免得他的名在本族本乡的城门中消失了。你们今日都是证人。”","notes":[]},{"n":11,"t":"在城门坐着的所有百姓和长老说：“我们都是证人。愿耶和华使进你家的这女子，像建立以色列家的拉结和利亚二人一样。又愿你在以法他得亨通，在伯利恒有名声。","notes":[]},{"n":12,"t":"愿耶和华从这年轻女子赐你后裔，使你的家像她玛从犹大所生法勒斯的家一样。”","notes":[]},{"n":13,"t":"于是，波阿斯娶了路得为妻，与她同房。耶和华使她怀孕生了一个儿子。","notes":[],"heads":["大卫的家谱"]},{"n":14,"t":"妇女们对拿娥米说：“耶和华是应当称颂的！因为他今日没有使你断绝可以赎产业的至亲。愿这孩子在以色列中得名声。","notes":[]},{"n":15,"t":"他必振奋你的精神，奉养你的晚年，因为他是爱慕你的媳妇所生的。有这样的媳妇，比有七个儿子更好！”","notes":[]},{"n":16,"t":"拿娥米接过孩子来，抱在怀中抚养他。","notes":[]},{"n":17,"t":"邻居的妇人给孩子起名，说：“拿娥米得了一个孩子了！”她们就给他起名叫俄备得。俄备得是耶西的父亲，是大卫的祖父。","notes":[]},{"n":18,"t":"这是法勒斯的后代：法勒斯生希斯仑；","notes":[]},{"n":19,"t":"希斯仑生兰；兰生亚米拿达；","notes":[]},{"n":20,"t":"亚米拿达生拿顺；拿顺生撒门；","notes":[]},{"n":21,"t":"撒门生波阿斯；波阿斯生俄备得；","notes":[]},{"n":22,"t":"俄备得生耶西；耶西生大卫。","notes":[]}]}},"1SA":{"1":{"heading":"以利加拿和他的家眷","verses":[{"n":1,"t":"以法莲山区有一个拉玛的琐非人，名叫以利加拿，他是苏弗的玄孙，托户的曾孙，以利户的孙子，耶罗罕的儿子，是以法莲人。","notes":["“拉玛的琐非人”或译“拉玛．琐非人”。"]},{"n":2,"t":"他有两个妻子：一个名叫哈拿，另一个名叫毗尼拿。毗尼拿有孩子，哈拿却没有孩子。","notes":[]},{"n":3,"t":"这人每年从本城上到示罗，敬拜万军之耶和华，向他献祭。在那里有以利的两个儿子何弗尼和非尼哈当耶和华的祭司。","notes":[]},{"n":4,"t":"每逢献祭的日子，以利加拿把祭肉分给他的妻子毗尼拿和毗尼拿所生的儿女。","notes":[]},{"n":5,"t":"他给哈拿的却是双分，因为他爱哈拿。耶和华却不使哈拿生育。","notes":[]},{"n":6,"t":"她的对头毗尼拿因耶和华不使哈拿生育，就常常惹她发怒，要使她生气。","notes":[]},{"n":7,"t":"年年都是如此。每当她上到耶和华殿的时候，毗尼拿就这样惹她发怒，以致她哭泣不吃饭。","notes":[]},{"n":8,"t":"她丈夫以利加拿对她说：“哈拿，你为何哭泣？为何不吃饭？为何伤心难过呢？有我不比有十个儿子更好吗？”","notes":[]},{"n":9,"t":"他们在示罗吃喝完了，哈拿就站起来。祭司以利坐在耶和华殿门框旁边的位子上。","notes":[],"heads":["哈拿和以利"]},{"n":10,"t":"哈拿心里愁苦，就痛痛哭泣，向耶和华祈祷。","notes":[]},{"n":11,"t":"她许愿说：“万军之耶和华啊，你若垂顾你使女的苦情，眷念不忘你的使女，赐你的使女一个子嗣，我必使他终生归给耶和华，不用剃刀剃他的头。”","notes":[]},{"n":12,"t":"哈拿在耶和华面前不住地祈祷，以利注意她的嘴。","notes":[]},{"n":13,"t":"哈拿心中默祷，只动嘴唇，听不到她的声音，因此以利以为她喝醉了。","notes":[]},{"n":14,"t":"以利对她说：“你要醉到几时呢？不要再喝酒了！”","notes":[]},{"n":15,"t":"哈拿回答说：“我主啊，不是这样。我是心里愁苦的妇人，清酒烈酒都没有喝，只在耶和华面前倾心吐意。","notes":[]},{"n":16,"t":"不要将你的使女看作不正经的女子。我因极其难过和生气，所以一直祷告到如今。”","notes":[]},{"n":17,"t":"以利回答说：“平平安安地回去吧。愿以色列的神允准你向他所求的！”","notes":[]},{"n":18,"t":"哈拿说：“愿你的婢女在你眼前蒙恩。”于是妇人上路，去吃饭，脸上不再带愁容了。","notes":[]},{"n":19,"t":"他们清早起来，在耶和华面前敬拜，就回去，往拉玛自己的家里。以利加拿和妻子哈拿同房，耶和华顾念哈拿。","notes":[],"heads":["撒母耳出生和奉献"]},{"n":20,"t":"时候到了，哈拿怀孕生了一个儿子，给他起名叫撒母耳，说：“这是我从耶和华那里求来的。”","notes":[]},{"n":21,"t":"以利加拿和他全家都上去，要向耶和华献年祭和还愿祭。","notes":[]},{"n":22,"t":"哈拿却没有上去，因为她对丈夫说：“等孩子断了奶，我就带他上去朝见耶和华，让他永远住在那里。”","notes":[]},{"n":23,"t":"她丈夫以利加拿对她说：“就照你看为好的去做吧！可以留到儿子断了奶，愿耶和华应验他的话。”于是妇人留在家里乳养儿子，直到他断了奶。","notes":[]},{"n":24,"t":"断奶之后，她就带着孩子，连同一头三岁的公牛，一伊法细面，一皮袋酒，上示罗耶和华的殿去。那时，孩子还小。","notes":["“一头三岁的公牛”是根据死海古卷、七十士译本和其他古译本；原文是“三头公牛”。","“一伊法细面”：七十士译本和其他古译本是“饼和一伊法细面”。"]},{"n":25,"t":"他们宰了公牛，就领孩子到以利面前。","notes":[]},{"n":26,"t":"妇人说：“我主啊，请容许我说，我向你，我的主起誓，从前在你这里站着祈求耶和华的那妇人就是我。","notes":[]},{"n":27,"t":"我祈求为要得这孩子，耶和华已将我向他所求的赐给我了。","notes":[]},{"n":28,"t":"所以，我将这孩子献给耶和华，使他终生归给耶和华。”他就在那里敬拜耶和华。","notes":[]}]},"2":{"heading":"哈拿的祷告","verses":[{"n":1,"t":"哈拿祷告说：“我的心因耶和华快乐，我的角因耶和华高举。我的口向仇敌张开；我因你的救恩欢欣。","notes":[]},{"n":2,"t":"“没有一位圣者像耶和华，除你以外没有别的了，也没有磐石像我们的神。","notes":[]},{"n":3,"t":"不要夸口说骄傲的话，也不要口出狂妄的言语，因耶和华是有知识的神，人的行为被他衡量。","notes":[]},{"n":4,"t":"勇士的弓折断，跌倒的人以力量束腰。","notes":[]},{"n":5,"t":"饱足的人作雇工求食；饥饿的人也不再饥饿。不生育的生了七个；儿女多的反倒孤独。","notes":[]},{"n":6,"t":"耶和华使人死，也使人活，使人下阴间，也使人往上升。","notes":[]},{"n":7,"t":"耶和华使人贫穷，也使人富足；使人降卑，也使人升高。","notes":[]},{"n":8,"t":"他从灰尘里抬举贫寒人，从粪堆中提拔贫穷人，使他们与贵族同坐，继承荣耀的座位。地的柱子属耶和华，他将世界立在其上。","notes":[]},{"n":9,"t":"“他必保护他圣民的脚步，但恶人却在黑暗中毁灭，因为人不是靠力量得胜。","notes":[]},{"n":10,"t":"与耶和华相争的，必被打碎；他必从天上打雷攻击他们。耶和华审判地极的人，将力量赐给所立的王，高举受膏者的角。”","notes":[]},{"n":11,"t":"以利加拿往拉玛回自己的家去了。那孩子在以利祭司面前事奉耶和华。","notes":[]},{"n":12,"t":"以利的两个儿子是无赖，不认识耶和华。","notes":[],"heads":["以利的两个儿子"]},{"n":13,"t":"这二祭司对待百姓的规矩是这样：凡有人献祭，正煮肉的时候，祭司的仆人就手拿三齿的叉子来，","notes":[]},{"n":14,"t":"将叉子往盆里，或锅里，或釜里，或壶里一插，插上来的肉，祭司都拿了去。他们对所有上到示罗的以色列人都这样做。","notes":[]},{"n":15,"t":"甚至在未烧脂肪之前，祭司的仆人就来对献祭的人说：“把肉给祭司，让他烤吧。他不要拿你煮过的肉，要生的。”","notes":[]},{"n":16,"t":"献祭的人若说：“他们必须先烧脂肪，然后你才可以随意拿。”仆人就说：“不，你立刻给我，不然我就要抢了。”","notes":[]},{"n":17,"t":"这些年轻人的罪在耶和华面前非常严重，因为这些人藐视耶和华的祭物。","notes":[]},{"n":18,"t":"那时，撒母耳还是孩子，穿着细麻布的以弗得，侍立在耶和华面前。","notes":[],"heads":["撒母耳在示罗"]},{"n":19,"t":"他母亲每年为他做一件小外袍，同丈夫上来献年祭的时候带来给他。","notes":[]},{"n":20,"t":"以利为以利加拿和他妻子祝福，说：“愿耶和华由这妇人再赐你后裔，代替从耶和华求来的孩子。”他们就回自己的地方去了。","notes":[]},{"n":21,"t":"耶和华眷顾哈拿，她就怀孕生了三个儿子，两个女儿。那孩子撒母耳在耶和华面前渐渐长大。","notes":[]},{"n":22,"t":"以利年纪老迈，听见他两个儿子对以色列众人所做一切的事，又听见他们与会幕门前伺候的妇人同寝，","notes":[],"heads":["预言以利家遭祸"]},{"n":23,"t":"就对他们说：“你们为何做这样的事呢？我从这众百姓听见了你们的恶行。","notes":[]},{"n":24,"t":"我儿啊，不可这样！我听到耶和华的百姓传出你们不好的名声。","notes":["“我听到...名声”或译“我听到你们的名声不好，你们使耶和华的百姓犯了罪”。"]},{"n":25,"t":"人若得罪人，有神可以裁决；人若得罪耶和华，谁能为他代求呢？”然而他们还是不听父亲的话，因为耶和华想要他们死。","notes":["“神”或译“审判官”。"]},{"n":26,"t":"撒母耳这孩子渐渐长大，耶和华与人越发喜爱他。","notes":[]},{"n":27,"t":"有神人来见以利，对他说：“耶和华如此说：‘你祖宗的家在埃及法老家的时候，我不是向他们显现吗？","notes":["“法老家”：死海古卷和七十士译本是“法老家作奴仆”。"]},{"n":28,"t":"在以色列众支派中，我不是拣选他作我的祭司，上我的祭坛，烧香，在我面前穿以弗得吗？我不是将以色列人所献的火祭都赐给你祖宗的家吗？","notes":[]},{"n":29,"t":"你们为何践踏我所吩咐献在我居所的祭物和供物呢？你为何尊重你的儿子过于尊重我，将我百姓以色列所献美好的祭物都拿去养肥你们自己呢？’","notes":["“你们为何<ins>.呢”：七十士译本是“你们为何贪婪地注视着我所吩咐献的祭物和供物呢”。"]},{"n":30,"t":"因此，耶和华－以色列的神说：‘我确实说过，你和你祖宗的家必永远行在我面前，但现在耶和华却说，我绝不会这样做。因为尊重我的，我必尊重他；藐视我的，他必被轻视。","notes":[]},{"n":31,"t":"看哪，日子将到，我要折断你的膀臂和你祖宗家的膀臂，使你家中没有一个老年人。","notes":[]},{"n":32,"t":"你在以色列人享福的时候必看见我居所的衰败，你家中必永远没有一个老年人。","notes":["“你在</ins>.衰败”：七十士译本的一些抄本是“你必在痛苦中以贪婪的眼睛看着以色列人享福”。"]},{"n":33,"t":"你家中的人，我没有从我坛前剪除的，必使你眼睛失明，心中忧伤。你家中所添的人口都必夭折。","notes":[]},{"n":34,"t":"你的两个儿子何弗尼、非尼哈所遭遇的事是给你的预兆：他们二人必在同一日死亡。","notes":[]},{"n":35,"t":"我要为自己立一个忠心的祭司，他行事必照我的心、如我的意。我要为他建立坚固的家，他必天天行走在我受膏者的面前。","notes":[]},{"n":36,"t":"你家所剩下的人都必来叩拜他，求一块银子，一个饼，说：求你给我一个祭司的职分，好使我得点饼吃。’”","notes":[]}]},"3":{"heading":"耶和华向撒母耳显现","verses":[{"n":1,"t":"那孩子撒母耳在以利面前事奉耶和华。在那些日子，耶和华的言语稀少，不常有异象。","notes":[]},{"n":2,"t":"那时，以利在自己的地方睡觉；他眼目开始昏花，不能看见。","notes":[]},{"n":3,"t":"神的灯还没有熄灭，撒母耳睡在耶和华的殿内，神的约柜就在那里。","notes":[]},{"n":4,"t":"耶和华呼唤撒母耳，撒母耳说：“我在这里！”","notes":[]},{"n":5,"t":"他跑到以利那里，说：“你叫我吗？我在这里。”以利说：“我没有叫你，回去睡吧。”他就回去睡了。","notes":[]},{"n":6,"t":"耶和华又呼唤撒母耳。撒母耳起来，到以利那里，说：“你叫我吗？我在这里。”以利说：“我儿，我没有叫你，回去睡吧。”","notes":[]},{"n":7,"t":"那时撒母耳还未认识耶和华，耶和华的话也未曾向他启示。","notes":[]},{"n":8,"t":"耶和华第三次再呼唤撒母耳。撒母耳起来，到以利那里，说：“你叫我吗？我在这里。”以利才明白是耶和华呼唤这小孩。","notes":[]},{"n":9,"t":"以利对撒母耳说：“你回去睡吧。他若再叫你，你就说：‘耶和华啊，请说，仆人敬听！’”撒母耳就回去，仍睡在原处。","notes":[]},{"n":10,"t":"耶和华来站着，像前几次呼唤：“撒母耳！撒母耳！”撒母耳说：“请说，仆人敬听！”","notes":[]},{"n":11,"t":"耶和华对撒母耳说：“看哪，我在以色列中必行一件事，凡听见的人都必双耳齐鸣。","notes":[]},{"n":12,"t":"我指着以利家所说的话，到了时候，必从头到尾应验在以利身上。","notes":[]},{"n":13,"t":"我曾告诉他，我必永远惩罚他的家，因为他知道自己的儿子作恶，亵渎神，却不禁止他们。","notes":["“亵渎神”是根据七十士译本和其他古译本；原文是“自招诅咒”。"]},{"n":14,"t":"所以我向以利家起誓：‘以利家的罪孽，就是献祭物和供物，也永不得赎。’”","notes":[]},{"n":15,"t":"撒母耳睡到天亮，就开了耶和华殿的门。撒母耳害怕，不敢将异象告诉以利。","notes":[]},{"n":16,"t":"以利呼唤撒母耳说：“我儿撒母耳！”撒母耳说：“我在这里！”","notes":[]},{"n":17,"t":"以利说：“他对你说了什么话，你不要向我隐瞒。你若将他对你所说的话向我隐瞒一句，愿神重重惩罚你。”","notes":[]},{"n":18,"t":"撒母耳就把一切话都告诉以利，并没有隐瞒。以利说：“他是耶和华，愿他照他看为好的去做。”","notes":[]},{"n":19,"t":"撒母耳长大了，耶和华与他同在，使他所说的话一句都不落空。","notes":[]},{"n":20,"t":"从但到别是巴，所有的以色列人都知道耶和华立撒母耳为先知。","notes":[]},{"n":21,"t":"耶和华又在示罗显现，因为耶和华在示罗藉他的话向撒母耳启示他自己。","notes":[]}]},"4":{"heading":"约柜被掳","verses":[{"n":1,"t":"撒母耳的话传遍了全以色列。以色列人出去与非利士人打仗，安营在以便．以谢，非利士人安营在亚弗。","notes":[]},{"n":2,"t":"非利士人向以色列人摆阵。两军交战的时候，以色列人败在非利士人面前；非利士人在战场上杀了他们约四千人。","notes":[]},{"n":3,"t":"百姓回到营里，以色列的长老说：“耶和华今日为何使我们败在非利士人面前呢？我们要将耶和华的约柜从示罗抬到我们这里来，好让他来到我们中间，救我们脱离敌人的手掌。”","notes":[]},{"n":4,"t":"于是百姓派人到示罗，从那里将坐在二基路伯上万军之耶和华的约柜抬来。以利的两个儿子何弗尼、非尼哈也与神的约柜同来。","notes":[]},{"n":5,"t":"耶和华的约柜到了营中，全以色列就大声欢呼，连地都震动。","notes":[]},{"n":6,"t":"非利士人听见欢呼的声音，就说：“为何希伯来人在营里这么大声欢呼呢？”他们知道耶和华的约柜到了营中。","notes":[]},{"n":7,"t":"非利士人就惧怕，说：“有神明到了他们营中。”又说：“我们有祸了！从来不曾有这样的事。","notes":[]},{"n":8,"t":"我们有祸了！谁能救我们脱离这些大能之神明的手呢？从前在旷野用各样灾祸击打埃及人的，就是这些神明。","notes":[]},{"n":9,"t":"非利士人哪，要刚强，要作大丈夫，免得作希伯来人的奴仆，如同他们作你们的奴仆一样。你们要作大丈夫，与他们争战。”","notes":[]},{"n":10,"t":"非利士人进攻，以色列人败了，各往自己的家逃跑。被杀的人很多，以色列倒下的步兵有三万。","notes":[]},{"n":11,"t":"神的约柜被掳去，以利的两个儿子何弗尼、非尼哈也都被杀了。","notes":[]},{"n":12,"t":"有一个便雅悯人从战场上逃跑，衣服撕裂，头蒙灰尘，当日来到示罗。","notes":[],"heads":["以利的死"]},{"n":13,"t":"他到了的时候，看哪，以利正坐在路旁的位子上观望，为神的约柜心里担忧。那人进城报信，全城的人就都呼喊起来。","notes":[]},{"n":14,"t":"以利听见呼喊的声音就说：“这喧嚷的声音是什么呢？”那人急忙来报信给以利。","notes":[]},{"n":15,"t":"那时以利九十八岁了，两眼发直，不能看见。","notes":[]},{"n":16,"t":"那人对以利说：“我是从战场上来的，今日刚从战场上逃回来。”以利说：“我儿，事情怎样了？”","notes":[]},{"n":17,"t":"报信的回答说：“以色列人在非利士人面前逃跑，百姓中被杀的很多！你的两个儿子何弗尼和非尼哈也都死了，并且神的约柜已经被掳去了。”","notes":[]},{"n":18,"t":"他一提到神的约柜，以利就从城门旁自己的位子上往后跌倒，折断颈项而死，因为他年纪老迈，身体沉重。以利作以色列的士师四十年。","notes":[]},{"n":19,"t":"以利的媳妇，非尼哈的妻子怀孕将到产期，她听见神的约柜被掳，公公和丈夫都死了，就曲身生产，极其疼痛。","notes":[],"heads":["非尼哈遗孀的死"]},{"n":20,"t":"她将要死的时候，旁边站着的妇人们对她说：“不要怕！你生了男孩了。”她不回答，也不放在心上。","notes":[]},{"n":21,"t":"她给孩子起名叫以迦博，说：“荣耀离开以色列了！”这是因为神的约柜被掳去，又因为她公公和丈夫都死了。","notes":["“以迦博”意思是“没有荣耀”。"]},{"n":22,"t":"她又说：“荣耀离开以色列，因为神的约柜被掳去了。”","notes":[]}]},"5":{"heading":"约柜在非利士人当中","verses":[{"n":1,"t":"非利士人掳去神的约柜，从以便．以谢带到亚实突。","notes":[]},{"n":2,"t":"非利士人掳了神的约柜，带进大衮庙，放在大衮的旁边。","notes":[]},{"n":3,"t":"次日，亚实突人清早起来，看哪，大衮仆倒在耶和华的约柜前，脸伏于地，他们就扶起大衮，把它放回原处。","notes":[]},{"n":4,"t":"又次日，他们清早起来，看哪，大衮仆倒在耶和华的约柜前，脸伏于地，并且大衮的头和两手都在门槛上折断，只剩下大衮的躯干。","notes":[]},{"n":5,"t":"因此，大衮的祭司和所有进大衮庙的人，都不踏亚实突的大衮庙的门槛，直到今日。","notes":[]},{"n":6,"t":"耶和华的手重重击打亚实突人，使他们恐惧，使亚实突和亚实突周围的人都生痔疮。","notes":[]},{"n":7,"t":"亚实突人见这情况，就说：“以色列神的约柜不可留在我们这里，因为他的手重重击打我们和我们的神明大衮”。","notes":[]},{"n":8,"t":"他们就派人去请非利士的众领袖来聚集，对他们说：“我们向以色列神的约柜应当怎样做呢？”他们说：“可以把以色列神的约柜运到迦特去。”于是他们把以色列神的约柜运到那里。","notes":[]},{"n":9,"t":"运到之后，耶和华的手击打那城，使那城的人非常惊慌，无论大小都生痔疮。","notes":[]},{"n":10,"t":"他们就把神的约柜送到以革伦。神的约柜到了以革伦，以革伦人就呼喊说：“他们把以色列神的约柜运到我这里，要害我和我的百姓！”","notes":[]},{"n":11,"t":"于是他们派人去请非利士的众领袖来，说：“请你们把以色列神的约柜送回原处，免得害死我和我的百姓！”原来神的手重重攻击那城，死亡的恐惧弥漫全城，","notes":[]},{"n":12,"t":"没有死的人都受痔疮的折磨。城里的哀声上达于天。","notes":[]}]},"6":{"heading":"送回约柜","verses":[{"n":1,"t":"耶和华的约柜在非利士人之地七个月。","notes":[]},{"n":2,"t":"非利士人召了祭司和占卜的来，说：“我们向耶和华的约柜应当怎样做呢？请指示我们要用什么方法把约柜送回原处。”","notes":[]},{"n":3,"t":"他们说：“若要将以色列神的约柜送回去，不可空手送回，一定要给他献赔罪的礼物，然后你们才可以得痊愈，并且知道他的手为何不离开你们。”","notes":[]},{"n":4,"t":"非利士人说：“应当用什么献为赔罪的礼物呢？”他们说：“当按照非利士领袖的数目，献五个金痔疮和五个金老鼠，因为你们众人和领袖所遭遇的都是一样的灾祸。","notes":[]},{"n":5,"t":"当制造你们痔疮的像和毁坏田地老鼠的像，并要将荣耀归给以色列的神，或者他向你们和你们的神明，以及你们的田地，把手放轻些。","notes":[]},{"n":6,"t":"你们为何硬着心，像埃及人和法老硬着心一样呢？神岂不是严厉对付埃及，使埃及人释放以色列人，他们就走了吗？","notes":[]},{"n":7,"t":"现在你们应当造一辆新车，把两头未曾负轭，还在哺乳的母牛套在车上，赶牛犊离开母牛，回家去。","notes":[]},{"n":8,"t":"你们要把耶和华的约柜放在车上，把所献赔罪的金器装在匣子里，放在柜旁，送走柜子，让它去。","notes":[]},{"n":9,"t":"你们要观察：车若直行过以色列的边界，上到伯．示麦去，这大灾祸就是耶和华降在我们身上的；若不然，我们就知道，这不是他的手击打我们，而是我们偶然遭遇的。”","notes":[]},{"n":10,"t":"非利士人就照样做了。他们取了两头哺乳的母牛套在车上，把牛犊关在家里，","notes":[]},{"n":11,"t":"把耶和华的约柜和装金老鼠以及金痔疮像的匣子都放在车上。","notes":[]},{"n":12,"t":"牛直行大路，在往伯．示麦的一条大道上，一面走一面叫，不偏左右。非利士的领袖跟在后面，直到伯．示麦的地界。","notes":[]},{"n":13,"t":"那时，伯．示麦人正在平原收割麦子，举目看见约柜，就欢欢喜喜地迎见它。","notes":[]},{"n":14,"t":"车到了伯．示麦人约书亚的田间，就在那里停了。在那里有一块大磐石，他们把车的木头劈了，把两头母牛献给耶和华为燔祭。","notes":[]},{"n":15,"t":"利未人将耶和华的约柜和柜子旁边装金器的匣子拿下来，放在大磐石上。当日伯．示麦人献上燔祭，又献其他祭物给耶和华。","notes":[]},{"n":16,"t":"非利士人的五个领袖看见了，当日就回以革伦去。","notes":[]},{"n":17,"t":"非利士人献给耶和华作赔罪的金痔疮像如下：一个为亚实突，一个为迦萨，一个为亚实基伦，一个为迦特，一个为以革伦。","notes":[]},{"n":18,"t":"金老鼠的数目是按照非利士五个领袖的城镇，就是坚固的城镇和乡村，以及大磐石。这磐石是安放耶和华约柜的，到今日还在伯．示麦人约书亚的田间。","notes":[]},{"n":19,"t":"耶和华击杀伯．示麦人，因为他们观看他的约柜。他击杀了百姓七十人 。百姓因耶和华大大击杀他们，就哀哭了。","notes":["“七十人”是根据一些古卷；原文是“七十人，五万人”，可能指“七十人加五万人”或“五万人中的七十人”。","“耶和华...七十人”：七十士译本是“主击杀耶哥尼雅的子孙七十人，因为他们没有和伯．示麦人欢欢喜喜地迎见约柜”。"],"heads":["约柜在基列．耶琳"]},{"n":20,"t":"伯．示麦人说：“谁能在耶和华这位圣洁的神面前侍立呢？这约柜可以从我们这里上到谁那里去呢？”","notes":[]},{"n":21,"t":"于是他们派使者到基列．耶琳的居民那里，说：“非利士人将耶和华的约柜送回来了，你们下来将约柜接了，上到你们那里去吧！”","notes":[]}]},"7":{"heading":"撒母耳治理以色列","verses":[{"n":1,"t":"基列．耶琳人就来了，将耶和华的约柜接上去，抬到山上亚比拿达的家中，将他儿子以利亚撒分别为圣，看守耶和华的约柜。","notes":[]},{"n":2,"t":"从约柜留在基列．耶琳的那天起，经过了许多日子，有二十年；以色列全家都哀哭归向耶和华。","notes":[]},{"n":3,"t":"撒母耳对以色列全家说：“你们若全心回转归向耶和华，就要从你们中间除掉外邦的神明和亚斯她录，预备你们的心归向耶和华，单单事奉他，他必救你们脱离非利士人的手。”","notes":[]},{"n":4,"t":"以色列人就除掉诸巴力和亚斯她录，单单事奉耶和华。","notes":[]},{"n":5,"t":"撒母耳说：“要召集以色列众人到米斯巴去，我好为你们向耶和华祷告。”","notes":[]},{"n":6,"t":"他们就聚集在米斯巴，打水浇在耶和华面前。当日他们禁食，说：“我们得罪了耶和华。”撒母耳在米斯巴作以色列人的士师。","notes":[]},{"n":7,"t":"非利士人听见以色列人聚集在米斯巴，非利士的领袖就上来要攻击以色列。以色列人听见，就惧怕非利士人。","notes":[]},{"n":8,"t":"以色列人对撒母耳说：“愿你不住为我们呼求耶和华－我们的神，救我们脱离非利士人的手。”","notes":[]},{"n":9,"t":"撒母耳就把一只吃奶的羔羊献给耶和华作全牲的燔祭，为以色列人呼求耶和华，耶和华就应允他。","notes":[]},{"n":10,"t":"撒母耳正献燔祭的时候，非利士人前来要与以色列争战。当日，耶和华打雷，发出极大的声音，使非利士人溃乱，他们就败在以色列面前。","notes":[]},{"n":11,"t":"以色列人从米斯巴出来，追赶非利士人，击杀他们，直到伯．甲的下边。","notes":[]},{"n":12,"t":"撒母耳拿一块石头立在米斯巴和善的中间，给石头起名叫以便．以谢，说：“到如今耶和华都帮助我们。”","notes":[]},{"n":13,"t":"因此，非利士人被制伏了，不再入侵以色列境内。撒母耳有生之年，耶和华的手攻击非利士人。","notes":[]},{"n":14,"t":"非利士人所夺取以色列的城镇，从以革伦直到迦特，都归回以色列了。以色列也从非利士人手中收回这些城所属的地界。那时以色列与亚摩利人和平相处。","notes":[]},{"n":15,"t":"撒母耳一生作以色列的士师。","notes":[]},{"n":16,"t":"他每年巡行到伯特利、吉甲、米斯巴，在这些地方审判以色列人。","notes":[]},{"n":17,"t":"随后他回到拉玛，因为他的家在那里；他在那里审判以色列人，并且在那里为耶和华筑了一座坛。","notes":[]}]},"8":{"heading":"以色列人要求立王","verses":[{"n":1,"t":"撒母耳年纪老迈，就立他的儿子作以色列的士师。","notes":[]},{"n":2,"t":"他的长子名叫约珥，次子名叫亚比亚；他们在别是巴作士师。","notes":[]},{"n":3,"t":"他的儿子不行他的道，贪图财利，收取贿赂，屈枉正直。","notes":[]},{"n":4,"t":"以色列的长老都聚集在拉玛，来到撒母耳那里，","notes":[]},{"n":5,"t":"对他说：“看哪，你年纪老了，你的儿子又不行你的道。现在请你为我们立一个王治理我们，像列国一样。”","notes":[]},{"n":6,"t":"撒母耳不喜悦他们说“立一个王治理我们”，他就向耶和华祷告。","notes":[]},{"n":7,"t":"耶和华对撒母耳说：“你只管听从百姓向你说的一切话，因为他们不是厌弃你，而是厌弃我，不要我作他们的王。","notes":[]},{"n":8,"t":"自从我领他们出埃及的日子到如今，他们离弃我，事奉别神；正像他们从前所做的一切事，现在他们也照样向你做了。","notes":[]},{"n":9,"t":"现在你只管听从他们的话，不过要严厉警告他们，告诉他们将来王会用什么方式管辖他们。”","notes":[]},{"n":10,"t":"撒母耳将耶和华一切的话转告求他立王的百姓。","notes":[]},{"n":11,"t":"他说：“管辖你们的王必用这样的方式：他必派你们的儿子为他驾车，赶马，在他的战车前奔跑。","notes":[]},{"n":12,"t":"他要为自己立千夫长、五十夫长；耕种他的田地，收割他的庄稼；打造他的兵器和车上的器械。","notes":[]},{"n":13,"t":"他必叫你们的女儿为他制造香膏，作厨师与烤饼的，","notes":[]},{"n":14,"t":"也必取你们最好的田地、葡萄园、橄榄园，赐给他的臣仆。","notes":[]},{"n":15,"t":"你们的粮食和葡萄园所出产的，他必征收十分之一给他的官员和臣仆，","notes":[]},{"n":16,"t":"又必叫你们的仆人婢女，健壮的青年和你们的驴为他做工。","notes":[]},{"n":17,"t":"你们的羊群，他必征收十分之一，你们自己也必作他的仆人。","notes":[]},{"n":18,"t":"那日，你们必因自己所选的王哀求耶和华，但那日耶和华却不应允你们。”","notes":[]},{"n":19,"t":"百姓却不肯听撒母耳的话，说：“不！我们一定要一个王治理我们，","notes":[]},{"n":20,"t":"使我们像列国一样，有王治理我们，率领我们，为我们争战。”","notes":[]},{"n":21,"t":"撒母耳听见百姓这一切话，就禀告给耶和华听。","notes":[]},{"n":22,"t":"耶和华对撒母耳说：“你只管听从他们的话，为他们立一个王。”撒母耳对以色列人说：“去，你们各归各城吧！”","notes":[]}]},"9":{"heading":"扫罗见撒母耳","verses":[{"n":1,"t":"有一个便雅悯人名叫基士，是便雅悯人亚斐亚的玄孙，比歌拉的曾孙，洗罗的孙子，亚别的儿子，是个大能的勇士。","notes":["“大能的勇士”或译“大财主”。"]},{"n":2,"t":"他有一个儿子名叫扫罗，又健壮、又英俊，在以色列人中没有一个可以与他相比；他比众百姓高出一个头。","notes":["“他比众百姓高出一个头”：原文直译“从他的肩膀及以上，他都比众百姓高”；10．23同。"]},{"n":3,"t":"扫罗的父亲基士丢失了几匹母驴，他就吩咐儿子扫罗说：“起来，带一个仆人去寻找驴子。”","notes":[]},{"n":4,"t":"扫罗走过以法莲山区，又过沙利沙地，都没有找着。他们走过沙琳地，驴不在那里，又走过便雅悯地，也没有找到。","notes":[]},{"n":5,"t":"到了苏弗地，扫罗对跟随他的仆人说：“我们不如回去，免得我父亲不为驴挂虑，反为我们担忧。”","notes":[]},{"n":6,"t":"仆人对他说：“看哪，这城里有一位神人，受人敬重，凡他所说的全都应验。现在让我们到他那里去，或者他能指示我们当走的路。”","notes":[]},{"n":7,"t":"扫罗对仆人说：“看哪，我们若去，送什么给那人呢？我们袋子里的食物都吃完了，也没有礼物可以送给神人，我们还有些什么呢？”","notes":[]},{"n":8,"t":"仆人又回答扫罗说：“看哪，我手里还有四分之一舍客勒的银子，可以送给神人，请他指示我们当走的路。”","notes":[]},{"n":9,"t":"从前以色列中，若有人去求问神，就这么说：“来，我们到先见那里去吧！”因现在的先知，从前称为先见。","notes":[]},{"n":10,"t":"扫罗对仆人说：“好主意！来，我们去吧。”于是他们往神人所住的城里去了。","notes":[]},{"n":11,"t":"他们上坡要进城，遇见几个少女出来打水，就问她们说：“先见有没有在这里呢？”","notes":[]},{"n":12,"t":"她们回答说：“有的，看哪，他就在你们前面。快！他今日正来到城里，因为今日百姓要在丘坛献祭。","notes":[]},{"n":13,"t":"你们一进城，他还没有上丘坛吃祭物之前，就会遇见他。因为他没有到，百姓不能吃，必须等他先为祭物祝谢，然后受邀的人才可以吃。现在就上去吧，因为这时候你们会遇见他。”","notes":[]},{"n":14,"t":"他们就上到那城，进入城中的时候，看哪，撒母耳正迎着他们来，要上丘坛去。","notes":[]},{"n":15,"t":"扫罗还没有到的前一日，耶和华已经对撒母耳启示说：","notes":[]},{"n":16,"t":"“明日这时候，我必使一个人从便雅悯地到你这里来，你要膏他作我百姓以色列的君王。他必救我的百姓脱离非利士人的手，因为我眷顾我的百姓，他们的哀声已上达于我。”","notes":["“我眷顾我的百姓”：七十士译本是“我已看到我百姓的困苦”。"]},{"n":17,"t":"撒母耳看见扫罗的时候，耶和华对他说：“看哪，这就是我对你所说的人，他必治理我的百姓。”","notes":[]},{"n":18,"t":"扫罗在城门中走到撒母耳跟前，说：“请告诉我，先见的家在哪里？”","notes":[]},{"n":19,"t":"撒母耳回答扫罗说：“我就是先见。你在我前面先上丘坛去，因为你们今日必跟我同席。明日早晨我送你走，会把你心里一切的事都告诉你。","notes":[]},{"n":20,"t":"至于你前三日所丢失的几匹母驴，你心里不必挂虑，都已经找到了。以色列众人所仰慕的是谁呢？不是仰慕你和你父的全家吗？”","notes":[]},{"n":21,"t":"扫罗回答说：“我不是以色列支派中最小的便雅悯人吗？我的家族不是便雅悯支派中最小的家族吗？你为何对我说这样的话呢？”","notes":[]},{"n":22,"t":"撒母耳领扫罗和他的仆人进了大厅，使他们在受邀的人中坐首位；受邀者约有三十个。","notes":[]},{"n":23,"t":"撒母耳对厨师说：“我交给你的那一份祭肉，吩咐你收存的，现在可以拿来。”","notes":[]},{"n":24,"t":"厨师就举起祭肉的腿和腿上的部分，摆在扫罗面前。撒母耳说：“看哪，所存留的摆在你面前了。吃吧！因为这是为你保留到这特定的时候的，好让你说，是我请了这百姓来。”当日，扫罗就与撒母耳同席。","notes":["“祭肉的腿和腿上的部分”：原文另译“祭肉的腿和肥尾巴”。"]},{"n":25,"t":"他们从丘坛下来进城，撒母耳和扫罗在房顶上说话。","notes":[],"heads":["撒母耳膏扫罗作王"]},{"n":26,"t":"次日他们清早起来。黎明的时候，撒母耳呼叫在房顶上的扫罗，说：“起来，我好送你回去。”扫罗就起来，和撒母耳二人一同到外面去。","notes":[]},{"n":27,"t":"二人下到城边，撒母耳对扫罗说：“你要吩咐仆人先走，仆人走了以后， 你要留在这里，这时候我要将神的话传给你听。”","notes":[]}]},"10":{"heading":"扫罗受感说话","verses":[{"n":1,"t":"撒母耳拿一瓶膏油倒在扫罗的头上，亲吻他，说：“耶和华岂不是膏你作他产业的君王吗？","notes":["“耶和华...君王吗？”七十士译本是“主膏你治理他百姓以色列。你要治理主的百姓，救他们脱离四围敌人的手。这就是主膏你作他产业的君王的证据。”"]},{"n":2,"t":"你今日离开我之后，会在便雅悯境内的谢撒，靠近拉结的坟墓，遇见两个人。他们会对你说：‘你要找的几匹母驴已经找到了。看哪，你父亲不为驴子的事挂虑，反为你担忧，说：我为儿子该做些什么呢？’","notes":[]},{"n":3,"t":"你从那里往前走，到了他泊的橡树那里，会遇见三个往伯特利去敬拜神的人：一个带着三只小山羊，一个带着三个饼，一个带着一皮袋酒。","notes":[]},{"n":4,"t":"他们会向你问安，给你两个饼，你就从他们手中接过来。","notes":[]},{"n":5,"t":"然后你要到神的山去，在那里有非利士的驻军。你到了城里的时候，会遇见一队先知从丘坛下来，前面有鼓瑟的、击鼓的、吹笛的、弹琴的，他们都受感说话。","notes":[]},{"n":6,"t":"耶和华的灵必大大感动你，你就与他们一同受感说话，转变成另一个人。","notes":[]},{"n":7,"t":"这征兆临到你，你就要趁机做该做的事，因为神与你同在。","notes":[]},{"n":8,"t":"你要在我以先下到吉甲。看哪，我必下到你那里献燔祭和平安祭。你要等候七日，等我到你那里指示你当做的事。”","notes":[]},{"n":9,"t":"扫罗转身离开撒母耳，神就改变他，赐给他另一颗心。当日这一切征兆都应验了。","notes":[]},{"n":10,"t":"他们来到那座山，看哪，有一队先知遇见扫罗。神的灵大大感动他，他就在先知中受感说话。","notes":[]},{"n":11,"t":"所有先前认识扫罗的人看见了，看哪，他和先知一同受感说话，百姓就彼此说：“基士的儿子遇见了什么呢？扫罗也在先知中吗？”","notes":[]},{"n":12,"t":"那地方有一个人说：“这些人的父亲是谁呢？”因此就有一句俗语说：“扫罗也在先知中吗？”","notes":[]},{"n":13,"t":"扫罗受感说完了话，就上丘坛去了。","notes":[]},{"n":14,"t":"扫罗的叔叔问扫罗和他的仆人说：“你们到哪里去了？”他说：“我们找驴子去了。但我们找不到，就去了撒母耳那里。”","notes":[]},{"n":15,"t":"扫罗的叔叔说：“告诉我撒母耳对你们说了些什么。”","notes":[]},{"n":16,"t":"扫罗对他的叔叔说：“他明明告诉我们，驴子已经找到了。”至于撒母耳所说君王的事，扫罗没有告诉叔叔。","notes":[]},{"n":17,"t":"撒母耳召集百姓到米斯巴耶和华那里。","notes":[],"heads":["抽签得扫罗为王"]},{"n":18,"t":"他对以色列众人说：“耶和华－以色列的神如此说：‘我领以色列出埃及，救你们脱离埃及人的手，以及脱离欺压你们各国之人的手。’","notes":[]},{"n":19,"t":"你们今日却厌弃救你们脱离一切灾祸和患难的神，对他说：‘求你立一个王治理我们。’现在你们应当按支派和宗族站在耶和华面前。”","notes":[]},{"n":20,"t":"于是，撒母耳叫以色列众支派近前来抽签，抽到了便雅悯支派。","notes":[]},{"n":21,"t":"然后，他叫便雅悯支派按宗族近前来，抽到了玛特利族，接着又抽到了基士的儿子扫罗。众人寻找他却找不到，","notes":[]},{"n":22,"t":"就再问耶和华说：“那人来到这里了没有？”耶和华说：“看哪，他藏在物品堆中。”","notes":[]},{"n":23,"t":"众人就跑去从那里领他出来。他站在百姓中间，比众百姓高出一个头。","notes":[]},{"n":24,"t":"撒母耳对众百姓说：“你们看到了耶和华所拣选的人吗？众百姓中没有人可以与他相比。”众百姓就欢呼说：“愿王万岁！”","notes":[]},{"n":25,"t":"撒母耳将君王的典章对百姓说明，又记在书上，放在耶和华面前，然后撒母耳遣散众百姓，各回自己的家去了。","notes":[]},{"n":26,"t":"扫罗也往基比亚自己的家去，有一群心中被神感动的勇士跟随他。","notes":[]},{"n":27,"t":"但有些无赖之辈说：“这人怎么能救我们呢？”他们就藐视他，不送礼物给他。扫罗却保持沉默。","notes":[]}]},"11":{"heading":"扫罗击败亚扪人","verses":[{"n":1,"t":"亚扪人拿辖上来，对着基列的雅比安营。雅比众人对拿辖说：“你与我们立约，我们就服事你。”","notes":[]},{"n":2,"t":"亚扪人拿辖对他们说：“你们若由我挖出你们各人的右眼，以此凌辱以色列众人，我就与你们立约。”","notes":[]},{"n":3,"t":"雅比的长老对他说：“求你宽容我们七日，等我们派人到以色列的全境去。若没有人来救我们，我们就出来归顺你。”","notes":[]},{"n":4,"t":"使者到了扫罗住的基比亚，把这事说给百姓听，众百姓就都放声大哭。","notes":[]},{"n":5,"t":"看哪，扫罗正从田间赶牛回来，说：“百姓为什么哭呢？”众人把雅比人的话告诉他。","notes":[]},{"n":6,"t":"扫罗听见这些话，就被神的灵催逼，大发怒气。","notes":[]},{"n":7,"t":"他把一对牛切成小块，吩咐使者传送到以色列全境，说：“凡不出来跟随扫罗和撒母耳的，就必这样待他的牛。”耶和华使百姓惧怕，他们就都出来如同一人。","notes":[]},{"n":8,"t":"扫罗在比色数点他们：以色列人有三十万，犹大人有三万。","notes":[]},{"n":9,"t":"他们对那些来的使者说：“你们要对基列的雅比人这样说，明天太阳快到中午的时候，你们必得解救。”使者回去告诉雅比人，他们就欢喜了。","notes":[]},{"n":10,"t":"于是雅比人对亚扪人说：“明日我们出来归顺你们，可以照你们看为好的待我们。”","notes":[]},{"n":11,"t":"第二日，扫罗把百姓分为三队，在清晨换岗哨的时候入侵亚扪人的军营，击杀他们直到中午的时候。逃脱的人都分散了，甚至没有两个人同在一起。","notes":[]},{"n":12,"t":"百姓对撒母耳说：“那说‘扫罗岂能作我们的王’的是谁呢？把他们交出来，我们好处死他们。”","notes":[]},{"n":13,"t":"扫罗说：“今日耶和华在以色列中施行拯救，所以今日不可处死人。”","notes":[]},{"n":14,"t":"撒母耳对百姓说：“来，我们到吉甲去，在那里开始新的王国。”","notes":[]},{"n":15,"t":"众百姓到了吉甲那里，在耶和华面前拥立扫罗为王，又在耶和华面前献平安祭。扫罗和以色列众人在那里都非常欢喜。","notes":[]}]},"12":{"heading":"撒母耳临别赠言","verses":[{"n":1,"t":"撒母耳对以色列众人说：“看哪，我已听了你们对我所说一切的话，为你们立了一个王。","notes":[]},{"n":2,"t":"现在，看哪，有这王行走在你们前面。我已年老发白，看哪，我的儿子都在你们这里。我从幼年直到今日都行走在你们前面。","notes":[]},{"n":3,"t":"我在这里，你们要在耶和华和他的受膏者面前为我作证，我夺过谁的牛，抢过谁的驴，欺负过谁，虐待过谁，从谁手里收过贿赂而蒙蔽自己的眼目呢？若有，我必偿还。”","notes":[]},{"n":4,"t":"众人说：“你未曾欺负我们，虐待我们，也未曾从任何人手里收过任何东西。”","notes":[]},{"n":5,"t":"撒母耳对他们说：“你们在我手里没有找着什么，有耶和华在你们中间作证，也有他的受膏者今日作证。”他们说：“愿耶和华作证。”","notes":["“他们说”是根据七十士译本；原文是“他说”。"]},{"n":6,"t":"撒母耳对百姓说：“从前立摩西和亚伦，又领你们祖先出埃及地的是耶和华。","notes":[]},{"n":7,"t":"现在你们要站住，让我在耶和华面前，以耶和华向你们和你们祖先所行一切公义的事来和你们争辩。","notes":[]},{"n":8,"t":"从前雅各到了埃及，后来你们的祖先呼求耶和华，耶和华就差遣摩西和亚伦领你们的祖先出埃及，来到这地方居住。","notes":[]},{"n":9,"t":"他们却忘记耶和华－他们的神，他就把他们交给夏琐将军西西拉的手中，以及非利士人和摩押王的手中。于是这些人常来攻击他们。","notes":["“交给<ins>.手中”：原文是“卖给</ins>.手中”。"]},{"n":10,"t":"他们呼求耶和华说：‘我们离弃了耶和华去事奉诸巴力和亚斯她录，我们有罪了。现在求你救我们脱离仇敌的手，我们必事奉你。’","notes":[]},{"n":11,"t":"耶和华就差遣耶路巴力、比但、耶弗他、撒母耳救你们脱离四围仇敌的手，你们才安然居住。","notes":[]},{"n":12,"t":"你们见亚扪人的王拿辖来攻击你们，就对我说：‘不，要有一个王治理我们。’其实耶和华－你们的神是你们的王。","notes":[]},{"n":13,"t":"现在，看哪，这就是你们所选的、你们所求的王。看哪，耶和华已经为你们立王了。","notes":[]},{"n":14,"t":"你们若敬畏耶和华，事奉他，听从他的话，不违背耶和华的命令，你们和治理你们的王也都跟从耶和华－你们的神就好了。","notes":[]},{"n":15,"t":"倘若不听从耶和华的话，违背他的命令，耶和华的手必攻击你们，像从前攻击你们祖先一样。","notes":[]},{"n":16,"t":"现在你们要站住，看耶和华在你们眼前要行的一件大事。","notes":[]},{"n":17,"t":"这不是割麦子的时候吗？我求告耶和华，他必打雷降雨，让你们知道并且看出，你们为自己求立王的事在耶和华眼前是犯大罪了。”","notes":[]},{"n":18,"t":"于是撒母耳求告耶和华，耶和华就在这日打雷降雨，众百姓就非常惧怕耶和华和撒母耳。","notes":[]},{"n":19,"t":"众百姓对撒母耳说：“请你为仆人向耶和华－你的神祷告，免得我们死亡，因为我们求立王的事，正是罪上加罪了。”","notes":[]},{"n":20,"t":"撒母耳对百姓说：“不要惧怕！你们虽然行了这恶，却不要偏离耶和华，只要尽心事奉他。","notes":[]},{"n":21,"t":"不可偏离去随从那没有益处、不能救人的虚无的神明，因为它们是虚无的。","notes":["“虚无的神明”：原文是“虚无”。"]},{"n":22,"t":"耶和华必因他大名的缘故不撇弃他的子民，因为耶和华喜悦你们作他的子民。","notes":[]},{"n":23,"t":"至于我，我如果停止为你们祷告，就得罪耶和华了，我绝不会这样做。我必以善道正路指教你们。","notes":[]},{"n":24,"t":"但你们要敬畏耶和华，诚诚实实地尽心事奉他，因你们要留意，他向你们所行的事何等大。","notes":[]},{"n":25,"t":"你们若不断作恶，你们和你们的王必一同灭亡。”","notes":[]}]},"13":{"heading":"与非利士人争战","verses":[{"n":1,"t":"扫罗登基的时候年三十岁，作以色列王二年。","notes":["“三十”是根据七十士译本的一些后期抄本，原文没有。","“二年”指大卫受膏以前的年数，根据徒13．21，扫罗作王四十年。"]},{"n":2,"t":"扫罗从以色列中选出三千人：二千跟随扫罗在密抹和伯特利山区，一千跟随约拿单在便雅悯的基比亚。其余的百姓，扫罗打发他们各自回自己的帐棚去了。","notes":[]},{"n":3,"t":"约拿单攻击非利士人在迦巴的驻军，非利士人听见了这事。扫罗就在遍地吹角，说：“让希伯来人都听见。”","notes":["“非利士人听见了...都听见。”原文另译“非利士人听见了这事，说：‘希伯来人反叛了！’扫罗就在遍地吹角。”"]},{"n":4,"t":"以色列众人听见扫罗攻击非利士的驻军，又听见以色列为非利士人所憎恶，百姓就跟随扫罗，在吉甲集合。","notes":[]},{"n":5,"t":"非利士人集合，要与以色列人作战。他们有战车三万辆，骑兵六千，士兵像海边的沙那样多。他们上来，在伯．亚文东边的密抹安营。","notes":[]},{"n":6,"t":"以色列人见自己危急，军队被围攻，百姓就藏在山洞、丛林、岩隙、地窖和深坑中。","notes":[]},{"n":7,"t":"有些希伯来人过了约旦河，逃到迦得和基列地。扫罗还在吉甲，所有的人都战战兢兢地跟随他。","notes":[]},{"n":8,"t":"扫罗照着撒母耳所定的日期等了七日。但是，撒母耳还没有来到吉甲，百姓就离开扫罗散去了。","notes":[],"heads":["扫罗不合法的献祭"]},{"n":9,"t":"于是扫罗说：“把燔祭和平安祭带到我这里来。”扫罗就献上燔祭。","notes":[]},{"n":10,"t":"他刚献完燔祭，看哪，撒母耳就到了。扫罗出去迎接他，向他问安。","notes":[]},{"n":11,"t":"撒母耳说：“你做了什么事啊？”扫罗说：“因为我见百姓离开我散去，你又不照所定的日期来到，而且非利士人已在密抹集合；","notes":[]},{"n":12,"t":"我说：‘现在非利士人已经下到吉甲来攻击我，可是我还没有向耶和华祷告。’所以我就勉强献上燔祭。”","notes":[]},{"n":13,"t":"撒母耳对扫罗说：“你做了糊涂事了，没有遵守耶和华－你神吩咐你的命令。不然，耶和华会在以色列中坚立你的国度，直到永远。","notes":[]},{"n":14,"t":"现在你的国度必不长久。耶和华已经寻着一个合他心意的人，立他作百姓的君王，因为你没有遵守耶和华所吩咐你的。”","notes":[]},{"n":15,"t":"撒母耳就起来，从吉甲上到便雅悯的基比亚。扫罗数点跟随他的百姓，约有六百人。","notes":[]},{"n":16,"t":"扫罗和他儿子约拿单，以及跟随他们的百姓，都住在便雅悯的迦巴，非利士人却在密抹安营。","notes":[]},{"n":17,"t":"有突击队从非利士营中出来，分成三队：一队往俄弗拉到书亚地去，","notes":[]},{"n":18,"t":"一队往伯．和仑去，一队往边界，下望朝着旷野的洗波音谷。","notes":[]},{"n":19,"t":"那时，以色列全地找不到一个铁匠，因为非利士人说：“恐怕希伯来人制造刀枪。”","notes":[]},{"n":20,"t":"以色列众人要磨锄、犁、斧、铲，就各自下到非利士人那里去磨。","notes":[]},{"n":21,"t":"磨锄或犁的价钱是三分之二舍客勒，磨斧或修整刺棒的价钱是三分之一舍客勒。","notes":[]},{"n":22,"t":"所以到了战争的日子，所有跟随扫罗和约拿单的百姓找不到一个手里有刀有枪的，惟扫罗和他儿子约拿单有。","notes":[]},{"n":23,"t":"非利士人的一队驻军出来，到密抹的隘口。","notes":[]}]},"14":{"heading":"约拿单的战绩","verses":[{"n":1,"t":"有一日，扫罗的儿子约拿单对拿他兵器的青年说：“来，我们过去到非利士的驻军那里。”但他没有告诉父亲。","notes":[]},{"n":2,"t":"扫罗在基比亚的郊外，坐在米矶仑的石榴树下，跟随他的百姓约有六百人。","notes":[]},{"n":3,"t":"在那里有亚希突的儿子亚希亚，穿着以弗得。亚希突是以迦博的哥哥，非尼哈的儿子，以利的孙子。以利从前在示罗作耶和华的祭司。约拿单去了，百姓却不知道。","notes":[]},{"n":4,"t":"约拿单要从隘口过到非利士驻军那里去。这隘口两边各有一座齿状峭壁：一座名叫播薛，另一座名叫西尼；","notes":[]},{"n":5,"t":"一座向北，对着密抹，一座向南，对着迦巴。","notes":[]},{"n":6,"t":"约拿单对拿兵器的青年说：“来，我们过去到那些未受割礼之人的驻军那里，或者耶和华为我们施展能力，因为耶和华使人得胜，不在乎人多人少。”","notes":["“因为<ins>.人少”：原文直译“不论人多人少，都不能拦阻耶和华拯救我们。”"]},{"n":7,"t":"拿兵器的对他说：“随你的心意做吧。你上去，看哪，我一定跟随你，与你同心。”","notes":[]},{"n":8,"t":"约拿单说：“看哪，我们要过去到那些人那里，在他们那里展现我们自己。","notes":[]},{"n":9,"t":"他们若对我们这么说：‘站住，等我们到你们那里去’，我们就站在原地，不上他们那里去；","notes":[]},{"n":10,"t":"但他们若这么说：‘上到我们这里来吧’，我们就上去，因为耶和华把他们交在我们手里了。这就是我们的凭据。”","notes":[]},{"n":11,"t":"二人就让非利士的驻军看见。非利士人说：“看哪，希伯来人从躲藏的洞穴里出来了！”","notes":[]},{"n":12,"t":"站岗的士兵对约拿单和拿兵器的人说：“上到这里来，我们有一件事要告诉你们。”约拿单就对拿兵器的人说：“跟我上去，因为耶和华把他们交在以色列人手里了。”","notes":[]},{"n":13,"t":"约拿单手脚并用爬上去，拿兵器的人跟随他。非利士人仆倒在约拿单面前，拿兵器的人跟着他，杀死他们。","notes":[]},{"n":14,"t":"约拿单和拿兵器的人第一次击杀的约有二十人，都在一亩 地的半犁沟之内。","notes":["“亩”：原文音译“策密德”，古希伯来面积单位；参“度量衡表”。"]},{"n":15,"t":"于是在军营、在田野、在众百姓中，人心惶惶，驻军和突击队都战兢；地也震动，这是从神那里来的惊恐。","notes":["“这是</ins>.惊恐”或译“战兢之势甚大”。"]},{"n":16,"t":"在便雅悯的基比亚，扫罗的哨兵观看，看哪，非利士全军溃乱，四处乱窜。","notes":[],"heads":["非利士人败退"]},{"n":17,"t":"扫罗就对跟随他的百姓说：“你们去数点人数，看是谁从我们这里出去。”他们一数点，看哪，约拿单和拿兵器的人不在其中。","notes":[]},{"n":18,"t":"那时神的约柜在以色列人那里。扫罗对亚希亚说：“你把神的约柜请到这里来。”","notes":["“神的约柜”：七十士译本是“以弗得”。"]},{"n":19,"t":"扫罗正与祭司说话的时候，非利士营中的骚乱越来越剧烈；扫罗就对祭司说：“停手吧！”","notes":[]},{"n":20,"t":"扫罗和所有跟随他的百姓都集合，来到战场，看哪，非利士人用刀互相击杀，大大混乱。","notes":[]},{"n":21,"t":"那先前由四方来跟随非利士人、在他们营中的希伯来人，现在也转过来帮助跟随扫罗和约拿单的以色列人了。","notes":[]},{"n":22,"t":"那藏在以法莲山区的以色列众人听说非利士人逃跑，就出来紧紧地追击他们。","notes":[]},{"n":23,"t":"那日，耶和华使以色列人得胜，战争一直打到伯．亚文。","notes":[]},{"n":24,"t":"那日，以色列人非常困惫，因为扫罗叫百姓起誓说：“凡不等到晚上我向敌人报完了仇就吃东西的，必受诅咒。”因此所有的百姓都没有尝食物。","notes":[],"heads":["扫罗草率的誓言"]},{"n":25,"t":"所有的百姓进入树林，见地面上有蜜。","notes":["“百姓”：原文是“地”。"]},{"n":26,"t":"百姓进了树林，看哪，有蜜流出来，却没有人敢用手取蜜入口，因为百姓怕那誓言。","notes":[]},{"n":27,"t":"约拿单没有听见他父亲叫百姓起誓，所以他伸出手中的杖，以杖头蘸在蜂房里，用手取回送入口内，他的眼睛就明亮了。","notes":[]},{"n":28,"t":"百姓中有一人对他说：“你父亲曾叫百姓严严地起誓说，今日吃东西的人必受诅咒；因此百姓就疲乏了。”","notes":[]},{"n":29,"t":"约拿单说：“我父亲给这地添麻烦了。你们看，我尝了这一点蜜，眼睛就明亮了。","notes":[]},{"n":30,"t":"今日百姓若随意吃了从仇敌夺来的东西，现在击杀的非利士人岂不更多吗？”","notes":[]},{"n":31,"t":"这日，以色列人击杀非利士人，从密抹直到亚雅仑。但百姓非常疲乏，","notes":[]},{"n":32,"t":"就急着扑向掠物，夺取牛羊和牛犊，宰于地上，连肉带血吃了。","notes":[]},{"n":33,"t":"有人告诉扫罗说：“看哪，百姓吃带血的肉，得罪耶和华了。”扫罗说：“你们行了诡诈，今日把一块大石头滚到我这里来吧。”","notes":[]},{"n":34,"t":"扫罗又说：“你们分散到百姓中，对他们说，你们各人把牛羊牵到我这里来宰了吃，不可吃带血的肉得罪耶和华。”那夜，所有的百姓把自己手中的牛牵到那里宰了。","notes":["“自己手中的牛”：七十士译本是“自己手中所有的”。"]},{"n":35,"t":"扫罗为耶和华筑了一座坛，这是他开始为耶和华筑的坛。","notes":[]},{"n":36,"t":"扫罗说：“我们要在夜里下去追赶非利士人，抢掠他们，直到天亮，不给他们留下一人。”众百姓说：“你看怎样好就做吧！”祭司说：“我们要先在这里亲近神。”","notes":[]},{"n":37,"t":"扫罗求问神说：“我可以下去追赶非利士人吗？你把他们交在以色列人手里吗？”这日神没有回答他。","notes":[]},{"n":38,"t":"扫罗说：“百姓中的众领袖，你们都要近前来到这里，查明今日这罪是怎样发生的。","notes":[]},{"n":39,"t":"我指着拯救以色列的永生的耶和华起誓，就是我儿子约拿单犯了罪，他也必被处死。”但众百姓中无人回答他。","notes":[]},{"n":40,"t":"扫罗对以色列众人说：“你们站在一边，我与我儿子约拿单也站在一边。”百姓对扫罗说：“你看怎样好就做吧！”","notes":[]},{"n":41,"t":"扫罗向耶和华－以色列的神祷告说：“求你指示正确的答案。”抽中的是扫罗和约拿单，百姓尽都无事。","notes":[]},{"n":42,"t":"扫罗说：“你们再抽签，看是我，还是我儿子约拿单。”抽中的是约拿单。","notes":[]},{"n":43,"t":"扫罗对约拿单说：“你告诉我，你做了什么事？”约拿单说：“我只是用手中的杖，以杖头蘸了一点蜜尝尝，看哪，我就要死吗？”","notes":[]},{"n":44,"t":"扫罗说：“约拿单哪，你一定要死！若不然，愿神重重惩罚我。”","notes":[]},{"n":45,"t":"百姓对扫罗说：“约拿单在以色列中大行拯救，岂可死呢？绝对不可！我们指着永生的耶和华起誓，连他的一根头发也不可落地，因为他今日与神一同做事。”于是百姓救约拿单免了死亡。","notes":[]},{"n":46,"t":"扫罗上去，不追赶非利士人，非利士人也回本地去了。","notes":[]},{"n":47,"t":"扫罗执掌以色列的国权，攻打他四围所有的仇敌，就是摩押人、亚扪人、以东人和琐巴诸王，以及非利士人。他无论往何处去，都打败他们。","notes":[],"heads":["扫罗的王权和家眷"]},{"n":48,"t":"扫罗奋勇作战，击败亚玛力人，救了以色列脱离抢掠他们之人的手。","notes":[]},{"n":49,"t":"扫罗的儿子是约拿单、亦施韦、麦基．舒亚。他的两个女儿：长女名叫米拉，次女名叫米甲。","notes":[]},{"n":50,"t":"扫罗的妻子名叫亚希暖，是亚希玛斯的女儿。扫罗军队的元帅名叫押尼珥，是扫罗的叔叔尼珥的儿子。","notes":[]},{"n":51,"t":"扫罗的父亲基士，押尼珥的父亲尼珥，都是亚别的儿子。","notes":[]},{"n":52,"t":"扫罗有生之年常与非利士人激烈争战，他看到任何有能力的人或勇士，都招募来跟随他。","notes":[]}]},"15":{"heading":"与亚玛力人争战","verses":[{"n":1,"t":"撒母耳对扫罗说：“耶和华差遣我膏你为王，治理他的百姓以色列，现在你要听从耶和华的话。","notes":[]},{"n":2,"t":"万军之耶和华如此说：‘以色列人从埃及上来的时候，在路上亚玛力人怎样待他们，怎样抵挡他们，我都要惩罚。","notes":[]},{"n":3,"t":"现在你要去攻打亚玛力人，灭尽他们所有的，不可怜惜他们，将男女、孩童、吃奶的，以及牛、羊、骆驼和驴全都杀死。’”","notes":[]},{"n":4,"t":"于是扫罗在提拉因召集百姓，数点他们，共有二十万步兵和一万犹大人。","notes":[]},{"n":5,"t":"扫罗到了亚玛力的京城，在谷中设下埋伏。","notes":[]},{"n":6,"t":"扫罗对基尼人说：“你们离开亚玛力人下去吧，免得我把你们和亚玛力人一同杀灭，因为以色列众人从埃及上来的时候，你们曾恩待他们。”于是基尼人离开了亚玛力人。","notes":[]},{"n":7,"t":"扫罗攻打亚玛力人，从哈腓拉直到埃及东边的书珥，","notes":[]},{"n":8,"t":"生擒了亚玛力王亚甲，用刀杀尽亚玛力的众百姓。","notes":[]},{"n":9,"t":"扫罗和百姓却怜惜亚甲，爱惜上好的牛、羊、牛犊、羔羊，以及一切美物，不肯灭绝。但是凡看不上眼和没有价值的，他们尽都杀了。","notes":[]},{"n":10,"t":"耶和华的话临到撒母耳说：","notes":[],"heads":["扫罗被废"]},{"n":11,"t":"“我立扫罗为王，我感到遗憾，因为他转去不跟从我，不遵守我的命令。”撒母耳就很生气，终夜哀求耶和华。","notes":[]},{"n":12,"t":"撒母耳清早起来，去见扫罗。有人告诉撒母耳说：“扫罗到了迦密，看哪，他在那里为自己立了纪念碑，又转身下到吉甲。”","notes":[]},{"n":13,"t":"撒母耳到了扫罗那里，扫罗对他说：“愿耶和华赐福给你，耶和华的命令我已遵守了。”","notes":[]},{"n":14,"t":"撒母耳说：“我耳中听见有羊叫、牛鸣的声音，又是什么呢？”","notes":[]},{"n":15,"t":"扫罗说：“这是百姓从亚玛力人那里带来的，因为他们爱惜上好的牛羊，要献给耶和华－你的神。其余的，我们都灭尽了。”","notes":[]},{"n":16,"t":"撒母耳对扫罗说：“住口吧！等我把耶和华昨夜向我所说的话告诉你。”扫罗说：“请说。”","notes":[]},{"n":17,"t":"撒母耳说：“你虽然看自己为小，你岂不是作了以色列诸支派的元首吗？耶和华膏你作了以色列的王。","notes":[]},{"n":18,"t":"耶和华差遣你，吩咐你说：‘你去除灭那些犯罪的亚玛力人，攻打他们，直到把他们完全灭尽。’","notes":[]},{"n":19,"t":"你为何没有听从耶和华的话呢？你为何急着扑向掠物，行耶和华眼中看为恶的事呢？”","notes":[]},{"n":20,"t":"扫罗对撒母耳说：“我听从了耶和华的话，行了耶和华派我行的路，擒了亚玛力王亚甲来，灭尽了亚玛力人。","notes":[]},{"n":21,"t":"百姓却从掠物中取了牛羊，是当灭之物中最好的，要在吉甲献给耶和华－你的神。”","notes":[]},{"n":22,"t":"撒母耳说：“耶和华喜爱燔祭和祭物，岂如喜爱人听从他的话呢？看哪，听命胜于献祭，顺从胜于公羊的脂肪。","notes":[]},{"n":23,"t":"悖逆与占卜的罪相等，顽梗与拜偶像的罪孽相同。因为你厌弃耶和华的命令，耶和华也厌弃你作王。”","notes":[]},{"n":24,"t":"扫罗对撒母耳说：“我有罪了！我违背了耶和华的指示和你的命令；因为我惧怕百姓，听从了他们的话。","notes":[],"heads":["扫罗认罪"]},{"n":25,"t":"现在求你赦免我的罪，同我回去，我好敬拜耶和华。”","notes":[]},{"n":26,"t":"撒母耳对扫罗说：“我不同你回去，因为你厌弃耶和华的命令，耶和华也厌弃你作以色列的王。”","notes":[]},{"n":27,"t":"撒母耳转身要走，扫罗抓住他外袍的衣角，外袍就断裂了。","notes":[]},{"n":28,"t":"撒母耳对他说：“今日耶和华使以色列国与你断绝，把这国赐给另一个比你更好的人。","notes":[]},{"n":29,"t":"以色列的大能者必不说谎，也不后悔，因为他不是世人，绝不后悔。”","notes":[]},{"n":30,"t":"扫罗说：“我有罪了。现在求你在我百姓的长老和以色列人面前尊重我，同我回去，我好敬拜耶和华－你的神。”","notes":[]},{"n":31,"t":"于是撒母耳转身跟随扫罗回去，扫罗就敬拜耶和华。","notes":[]},{"n":32,"t":"撒母耳说：“把亚玛力王亚甲带到我这里来。”亚甲就欢欢喜喜地来到他面前，说：“死亡的苦难必定过去了。”","notes":["“就欢欢喜喜地...过去了。”死海古卷和七十士译本是“就战战兢兢地来到他面前，说：‘这真是死亡的苦难。’”"]},{"n":33,"t":"撒母耳说：“你既用刀使妇人丧子，你母亲在妇人中也必照样丧子。”于是，撒母耳在吉甲耶和华面前把亚甲砍碎了。","notes":[]},{"n":34,"t":"撒母耳回了拉玛。扫罗上他所住的基比亚，回自己的家去了。","notes":[]},{"n":35,"t":"撒母耳直到死的日子，再没有见扫罗。但撒母耳为扫罗悲伤，因为耶和华遗憾立扫罗为以色列的王。","notes":[]}]},"16":{"heading":"大卫被膏立为王","verses":[{"n":1,"t":"耶和华对撒母耳说：“我既厌弃扫罗作以色列的王，你为他悲伤要到几时呢？你将膏油盛满了角；来，我差遣你到伯利恒人耶西那里去，因为我在他儿子中已看中了一个为我作王的。”","notes":[]},{"n":2,"t":"撒母耳说：“我怎么能去呢？扫罗一听见，就会杀我。”耶和华说：“你可以手里牵一头小母牛去，说：‘我来是要向耶和华献祭。’","notes":[]},{"n":3,"t":"你要请耶西来一同献祭，我会指示你当做的事。我对你说的那个人，你要为我膏他。”","notes":[]},{"n":4,"t":"撒母耳遵照耶和华的话去做，来到伯利恒，城里的长老都战战兢兢出来迎接他，有人问他说：“你是为平安来的吗？”","notes":[]},{"n":5,"t":"他说：“为平安来的，我来是要向耶和华献祭。你们要使自己分别为圣，来跟我一同献祭。”撒母耳把耶西和他众儿子分别为圣，请他们来一同献祭。","notes":[]},{"n":6,"t":"他们来的时候，撒母耳看见以利押，就心里说，耶和华的受膏者一定在耶和华面前了。","notes":[]},{"n":7,"t":"耶和华却对撒母耳说：“不要只看他的外貌和他身材高大，我不拣选他。因为耶和华不像人看人，人是看外貌，耶和华是看内心。”","notes":["“外貌”：原文直译“眼睛看得到的”。"]},{"n":8,"t":"耶西叫亚比拿达从撒母耳面前经过，撒母耳说：“耶和华也不拣选他。”","notes":[]},{"n":9,"t":"耶西又叫沙玛经过，撒母耳说：“耶和华也不拣选他。”","notes":[]},{"n":10,"t":"耶西叫他七个儿子都从撒母耳面前经过，撒母耳对耶西说：“这些都不是耶和华所拣选的。”","notes":[]},{"n":11,"t":"撒母耳对耶西说：“你的儿子都在这里了吗？”他说：“还有一个最小的，看哪，他正在放羊。”撒母耳对耶西说：“你派人去叫他来；他若不来这里，我们必不坐席。”","notes":[]},{"n":12,"t":"耶西就派人去叫他来。他面色红润，双目清秀，容貌俊美。耶和华说：“起来，膏他，因为这就是他了。”","notes":[]},{"n":13,"t":"撒母耳就用角里的膏油，在他的兄长中膏了他。从这日起，耶和华的灵就大大感动大卫。撒母耳起身回拉玛去了。","notes":[]},{"n":14,"t":"耶和华的灵离开扫罗，有邪灵从耶和华那里来扰乱他。","notes":[],"heads":["大卫在扫罗的宫里"]},{"n":15,"t":"扫罗的臣仆对他说：“看哪，有邪灵从神那里来扰乱你。","notes":[]},{"n":16,"t":"我们的主可以吩咐你面前的臣仆，去找一个善于弹琴的来。神那里来的邪灵临到你身上的时候，他用手弹琴，你就会感觉爽快。”","notes":[]},{"n":17,"t":"扫罗对臣仆说：“你们给我找一个善于弹琴的，带到我这里来。”","notes":[]},{"n":18,"t":"仆人中有一个回答说：“看哪，我曾见伯利恒人耶西的一个儿子善于弹琴，是大能的勇士，说话合宜，容貌俊美，耶和华也与他同在。”","notes":[]},{"n":19,"t":"于是扫罗差遣使者到耶西那里，说：“叫你放羊的儿子大卫到我这里来。”","notes":[]},{"n":20,"t":"耶西把几个饼和一皮袋酒，以及一只小山羊，驮在驴上，由儿子大卫的手送给扫罗。","notes":[]},{"n":21,"t":"大卫到了扫罗那里，就侍立在扫罗面前。扫罗很喜欢他，他就作了扫罗拿兵器的人。","notes":[]},{"n":22,"t":"扫罗派人到耶西那里，说：“让大卫侍立在我面前，因为他在我眼前蒙了恩宠。”","notes":[]},{"n":23,"t":"从神那里来的邪灵临到扫罗身上的时候，大卫就拿琴，用手弹奏，使扫罗舒畅，感觉爽快，那邪灵就离开他了。","notes":[]}]},"17":{"heading":"大卫和歌利亚","verses":[{"n":1,"t":"非利士人召集他们的军队来争战。他们聚集在犹大的梭哥，在梭哥和亚西加中间的以弗．大悯安营。","notes":[]},{"n":2,"t":"扫罗和以色列人也聚集，在以拉谷安营，摆阵迎战，要与非利士人打仗。","notes":[]},{"n":3,"t":"非利士人站在这边的山上，以色列人站在那边的山上，当中有谷。","notes":[]},{"n":4,"t":"从非利士营中出来一个挑战的人，名叫歌利亚，是迦特人，身高六肘一虎口。","notes":[]},{"n":5,"t":"他头戴铜盔，身穿铠甲，甲重五千舍客勒铜。","notes":[]},{"n":6,"t":"他腿上有铜护膝，两肩之中背负铜矛。","notes":[]},{"n":7,"t":"他的枪杆粗如织布机的轴，枪头的铁重六百舍客勒。有一个拿盾牌的人走在他前面。","notes":[]},{"n":8,"t":"歌利亚站着，对以色列的军队喊叫，对他们说：“你们出来摆阵作战是为了什么呢？我不是非利士人吗？你们不是扫罗的仆人吗？你们选一个人出来，叫他下来到我这里吧。","notes":[]},{"n":9,"t":"他若能与我决斗，把我杀死，我们就作你们的奴隶；我若胜了他，把他杀死，你们就作我们的奴隶，服事我们。”","notes":[]},{"n":10,"t":"那非利士人又说：“我今日向以色列的军队骂阵。你们叫一个人出来，跟我决斗吧。”","notes":[]},{"n":11,"t":"扫罗和以色列众人听见非利士人这些话就惊惶，非常害怕。","notes":[]},{"n":12,"t":"大卫是犹大伯利恒的以法他人耶西的儿子，耶西有八个儿子。在扫罗的时候，这人年老，在众人中受敬重。","notes":["“这人...受敬重”：七十士译本和其他古译本是“这人已经年纪老迈了”。"]},{"n":13,"t":"耶西最大的三个儿子跟随扫罗出征。出征的三个儿子名字是：长子以利押，次子亚比拿达，三子沙玛。","notes":[]},{"n":14,"t":"大卫是最小的，最大的三个儿子跟随扫罗。","notes":[]},{"n":15,"t":"大卫有时离开扫罗，回伯利恒为他父亲放羊。","notes":[]},{"n":16,"t":"那非利士人早晚都出来站着，共四十日。","notes":[]},{"n":17,"t":"耶西对他儿子大卫说：“你拿一伊法烘了的穗子和十个饼，跑到营里去，交给你的哥哥，","notes":[]},{"n":18,"t":"再拿这十块奶饼，送给他们的千夫长，并要问你哥哥好，向他们要个凭据回来。”","notes":[]},{"n":19,"t":"扫罗和大卫的三个哥哥，以及以色列众人，都在以拉谷与非利士人打仗。","notes":[]},{"n":20,"t":"大卫早晨起来，把羊交托一个看守的人，照耶西所吩咐的带着食物去了。到了军营，军队刚出到战场，呐喊叫阵。","notes":[]},{"n":21,"t":"以色列人和非利士人都摆列阵势，彼此相对。","notes":[]},{"n":22,"t":"大卫把东西留在看守物件的人手中，跑到战场，问他哥哥好。","notes":[]},{"n":23,"t":"他与他们说话的时候，看哪，那挑战的人，就是迦特的非利士人歌利亚，从非利士队伍中上来，说了同样的话，大卫听见了。","notes":[]},{"n":24,"t":"以色列众人看见那人就非常害怕，从他面前逃跑。","notes":[]},{"n":25,"t":"以色列人说：“这上来的人你看见了吗？他上来是要向以色列人骂阵。若有人能杀他，王必赏赐他大财，将自己的女儿嫁给他，并在以色列人中免除他父家纳粮服役。”","notes":[]},{"n":26,"t":"大卫对站在旁边的人说：“若有人杀这非利士人，除掉以色列人的羞辱，他会怎样呢？这未受割礼的非利士人是谁，竟敢向永生神的军队骂阵！”","notes":[]},{"n":27,"t":"百姓照同样的话对他说：“若有人杀了那人，必这样待他。”","notes":[]},{"n":28,"t":"大卫的长兄以利押听见大卫与他们所说的话，就向他发怒，说：“你下来做什么呢？在旷野的那几只羊，你交托谁了呢？我知道你的骄傲和你心里的恶意，你下来只是为了看战争！”","notes":[]},{"n":29,"t":"大卫说：“我现在做了什么呢？只是问一句话也不可以吗？”","notes":[]},{"n":30,"t":"大卫离开他转向别人，问了同样的事，百姓也照先前的话回答他。","notes":[]},{"n":31,"t":"有人听见大卫所说的话，就在扫罗面前报告；扫罗就派人叫他来。","notes":[]},{"n":32,"t":"大卫对扫罗说：“人不必因那非利士人灰心。你的仆人要去与他决斗。”","notes":[]},{"n":33,"t":"扫罗对大卫说：“你不能去与那非利士人决斗，因为你年纪太轻，他从小就是战士。”","notes":[]},{"n":34,"t":"大卫对扫罗说：“你仆人为父亲放羊，有时狮子来了，有时熊来了，从群中抓走一只羔羊。","notes":[]},{"n":35,"t":"我就追赶它，击打它，把羔羊从它口中救出来。它起来攻击我，我就揪它的胡子，打死它。","notes":[]},{"n":36,"t":"你仆人曾打死狮子和熊，这未受割礼的非利士人必像狮子和熊一样，因为他向永生神的军队骂阵。”","notes":[]},{"n":37,"t":"大卫又说：“耶和华救我脱离狮子和熊的爪，他必救我脱离这非利士人的手。”扫罗对大卫说：“你去吧！耶和华必与你同在。”","notes":[]},{"n":38,"t":"扫罗把自己的战衣给大卫穿上，将铜盔戴在他头上，又给他穿上铠甲。","notes":[]},{"n":39,"t":"大卫佩刀在战衣上，试着走走看。因大卫没有试过，就对扫罗说：“我穿戴这些不能走路，因为我没有试过。”于是他脱下身上的这些军装。","notes":[]},{"n":40,"t":"他手中拿杖，又在溪中挑选了五块光滑的石子，放在袋里，就是牧人带的囊里，手里拿着甩石的机弦，迎向那非利士人。","notes":[]},{"n":41,"t":"那非利士人渐渐走近大卫，拿盾牌的人在他前面。","notes":[]},{"n":42,"t":"非利士人观看，见了大卫，就藐视他，因为他年轻，面色红润，容貌俊美。","notes":[]},{"n":43,"t":"非利士人对大卫说：“你拿着杖到我这里来，我岂是狗吗？”非利士人就指着自己的神明诅咒大卫。","notes":[]},{"n":44,"t":"非利士人又对大卫说：“来吧！我要把你的肉给空中的飞鸟和田野的走兽。”","notes":[]},{"n":45,"t":"大卫对非利士人说：“你来攻击我，是靠着刀枪和铜矛，但我来攻击你，是靠着万军之耶和华的名，就是你所辱骂、带领以色列军队的神。","notes":[]},{"n":46,"t":"今日耶和华必将你交在我手里。我必杀你，砍下你的头，今日我要把非利士军兵的尸体给空中的飞鸟和地上的野兽，使全地的人都知道以色列中有神，","notes":[]},{"n":47,"t":"又使这里的全会众知道，耶和华使人得胜，不是用刀用枪，因为战争全在乎耶和华。他必将你们交在我们手里。”","notes":[]},{"n":48,"t":"那非利士人起来，迎向大卫，走近前来。大卫急忙往战场，迎向非利士人跑去。","notes":[]},{"n":49,"t":"大卫伸手入囊中，从里面掏出一块石子来，用机弦甩去，击中非利士人的前额，石子进入额内，他就仆倒，面伏于地。","notes":[]},{"n":50,"t":"这样，大卫用机弦和石子胜了那非利士人，击中了他，把他杀死；大卫手中没有刀。","notes":[]},{"n":51,"t":"大卫跑去，站在那非利士人身旁，把他的刀从鞘中拔出来，杀死他，用刀割下他的头。非利士众人看见他们的勇士死了，就都逃跑。","notes":[]},{"n":52,"t":"以色列人和犹大人就起来呐喊，追赶非利士人，直到该和以革伦的城门。被杀的非利士人倒在路上，从沙拉音直到迦特和以革伦。","notes":["“该”：七十士译本和其他古译本是“迦特”。"]},{"n":53,"t":"以色列人追赶非利士人回来，抢夺了他们的军营。","notes":[]},{"n":54,"t":"大卫拿着那非利士人的头带到耶路撒冷，却把那非利士人的军装放在自己的帐棚里。","notes":[]},{"n":55,"t":"扫罗看见大卫去迎战非利士人，就问押尼珥元帅说：“押尼珥，那年轻人是谁的儿子？”押尼珥说：“王啊，我在你面前起誓，我不知道。”","notes":[],"heads":["大卫觐见扫罗"]},{"n":56,"t":"王说：“你可以问问那孩子是谁的儿子。”","notes":[]},{"n":57,"t":"大卫打死那非利士人回来，押尼珥领他到扫罗面前，大卫手中拿着非利士人的头。","notes":[]},{"n":58,"t":"扫罗问他说：“年轻人，你是谁的儿子？”大卫说：“我是你仆人伯利恒人耶西的儿子。”","notes":[]}]},"18":{"heading":"大卫与约拿单","verses":[{"n":1,"t":"大卫对扫罗说完了话，约拿单的心与大卫的心深相契合。约拿单爱大卫，如同爱自己的性命。","notes":[]},{"n":2,"t":"那日扫罗留住大卫，不让他回父家。","notes":[]},{"n":3,"t":"约拿单爱大卫如同爱自己的性命，就与他立约。","notes":[]},{"n":4,"t":"约拿单从身上脱下外袍，给了大卫，又把战衣、刀、弓、腰带都给了他。","notes":[]},{"n":5,"t":"扫罗无论差遣大卫往何处去，他都做事精明。扫罗立他作军队的指挥官，众百姓和扫罗的臣仆都看为美。","notes":[]},{"n":6,"t":"大卫打死了那非利士人，同众人回来的时候，妇女们从以色列各城里出来，欢欢喜喜，打鼓奏乐，唱歌跳舞，迎接扫罗王。","notes":[],"heads":["扫罗妒忌大卫"]},{"n":7,"t":"众妇女欢乐唱和，说：“扫罗杀死千千，大卫杀死万万。”","notes":[]},{"n":8,"t":"扫罗非常愤怒，不喜欢这话。他说：“将万万归给大卫，千千归给我，只剩下王国没有给他！”","notes":[]},{"n":9,"t":"从这日起，扫罗就敌视大卫。","notes":[]},{"n":10,"t":"次日，从神来的邪灵紧抓住扫罗，他就在家中胡言乱语。大卫照常弹琴，扫罗手里拿着枪。","notes":[]},{"n":11,"t":"扫罗把枪一掷，心里说：“我要将大卫刺透，钉在墙上。”大卫闪避了他两次。","notes":[]},{"n":12,"t":"扫罗惧怕大卫，因为耶和华离开自己，与大卫同在。","notes":[]},{"n":13,"t":"所以扫罗叫大卫离开自己，立他为千夫长，他就领兵出入。","notes":[]},{"n":14,"t":"大卫所做的每一件事都精明，耶和华也与他同在。","notes":[]},{"n":15,"t":"扫罗见大卫做事精明，就更怕他。","notes":[]},{"n":16,"t":"但以色列和犹大众人都爱大卫，因为他领他们出入。","notes":[]},{"n":17,"t":"扫罗对大卫说：“看哪，我将大女儿米拉嫁给你，只要你作我的勇士，为耶和华争战。”扫罗心里说：“我不好亲手害他，要藉非利士人的手害他。”","notes":[],"heads":["大卫娶扫罗的女儿"]},{"n":18,"t":"大卫对扫罗说：“我是谁，我是什么出身，我父家在以色列中算什么，岂敢作王的女婿呢？”","notes":[]},{"n":19,"t":"扫罗的女儿米拉到了当嫁给大卫的时候，扫罗却将她嫁给了米何拉人亚得列。","notes":[]},{"n":20,"t":"扫罗的女儿米甲爱大卫。有人告诉扫罗，这件事在扫罗眼中看为合宜。","notes":[]},{"n":21,"t":"扫罗心里说：“我把这女儿嫁给大卫，作他的圈套，好藉非利士人的手害他。”所以扫罗第二次对大卫说：“你今日可以作我的女婿。”","notes":[]},{"n":22,"t":"扫罗吩咐臣仆：“你们暗中对大卫说：‘看哪，王喜欢你，王的臣仆也都爱戴你，现在你就作王的女婿吧。’”","notes":[]},{"n":23,"t":"扫罗的臣仆照这话说给大卫听。大卫说：“你们把作王的女婿看为小事吗？我是贫穷卑微的人。”","notes":[]},{"n":24,"t":"扫罗的臣仆回奏说，大卫说了这样的话。","notes":[]},{"n":25,"t":"扫罗说：“你们要对大卫这样说：‘王不要什么聘礼，只要一百非利士人的包皮，好在王的仇敌身上报仇。’”扫罗的意图是要大卫落在非利士人的手中。","notes":[]},{"n":26,"t":"扫罗的臣仆把这话告诉大卫，大卫就欢喜作王的女婿。日期还没有到，","notes":[]},{"n":27,"t":"大卫和跟随他的人起来前往，杀了二百非利士人，将包皮足数交给王，为要作王的女婿。于是扫罗将女儿米甲嫁给大卫。","notes":["“二百”：七十士译本是“一百”。"]},{"n":28,"t":"扫罗见耶和华与大卫同在，女儿米甲又爱大卫，","notes":[]},{"n":29,"t":"就更怕大卫，常常与大卫为敌。","notes":[]},{"n":30,"t":"每逢非利士的军官出来打仗，大卫做事比扫罗任何臣仆更精明，因此他的名极受尊重。","notes":[]}]},"19":{"heading":"扫罗迫害大卫","verses":[{"n":1,"t":"扫罗吩咐他儿子约拿单和众臣仆要杀大卫，但扫罗的儿子约拿单却很喜爱大卫。","notes":[]},{"n":2,"t":"约拿单告诉大卫说：“我父扫罗想要杀你，现在你要小心，明日早晨留在一个僻静的地方藏起来。","notes":[]},{"n":3,"t":"我会出去，到你所藏的田里，站在我父亲旁边，与父亲谈论到你。我看情形怎样，会告诉你。”","notes":[]},{"n":4,"t":"约拿单向他父亲扫罗说大卫的好话，对他说：“王不可得罪王的仆人大卫，因为他未曾得罪你，他所行的对你都很有益处。","notes":[]},{"n":5,"t":"他拚了命杀那非利士人，并且耶和华为全以色列大施拯救。那时你看见，也很欢喜，现在为何要犯罪，流无辜人的血，无缘无故杀大卫呢？”","notes":[]},{"n":6,"t":"扫罗听了约拿单的话，就指着永生的耶和华起誓：“我绝不杀他。”","notes":[]},{"n":7,"t":"约拿单叫大卫来，把这一切事告诉他。约拿单带他去见扫罗，他就像以前一样侍立在扫罗面前。","notes":[]},{"n":8,"t":"此后又有战争，大卫出去与非利士人打仗。他大大击败他们，他们就在他面前逃跑。","notes":[]},{"n":9,"t":"从耶和华来的邪灵又降在扫罗身上，扫罗手里拿枪坐在屋里，大卫正用手弹琴。","notes":[]},{"n":10,"t":"扫罗想要用枪刺透大卫，把他钉在墙上，他却躲开扫罗，扫罗的枪刺入墙内。当夜大卫逃走，躲起来了。","notes":[]},{"n":11,"t":"扫罗派一些使者到大卫的房屋那里守着他，等到天亮要杀他。大卫的妻子米甲对大卫说：“你今夜若不逃命，明日就要被杀。”","notes":[]},{"n":12,"t":"于是米甲将大卫从窗户缒下去，让他走；大卫就逃走，躲起来了。","notes":[]},{"n":13,"t":"米甲把家中的神像放在床上，头枕在山羊毛的枕头上，用衣服盖起来。","notes":[]},{"n":14,"t":"扫罗派一些使者去捉拿大卫，米甲说：“他病了。”","notes":[]},{"n":15,"t":"扫罗又派一些使者去看大卫，说：“把他连床一起抬到我这里，我好杀他。”","notes":[]},{"n":16,"t":"使者进去，看哪，神像在床上，头枕在山羊毛的枕头上。","notes":[]},{"n":17,"t":"扫罗对米甲说：“你为什么这样欺骗我，放我仇敌逃走呢？”米甲对扫罗说：“他对我说：‘你放我走吧，我何必要杀你呢？’”","notes":[]},{"n":18,"t":"大卫逃跑躲避，来到拉玛的撒母耳那里，把扫罗向他所行的事全告诉他。他和撒母耳就去，住在拿约。","notes":[]},{"n":19,"t":"有人告诉扫罗说：“看哪，大卫在拉玛的拿约”。","notes":[]},{"n":20,"t":"扫罗派一些使者去捉拿大卫。去的人见一队先知受感说话，撒母耳站在当中领导他们，扫罗派去的使者也受神的灵感动说话。","notes":[]},{"n":21,"t":"有人把这事告诉扫罗，他又派另一些使者去，他们也受感说话。扫罗第三次派使者去，他们也受感说话。","notes":[]},{"n":22,"t":"然后扫罗亲自往拉玛去，到了西沽的大井，问人说：“撒母耳和大卫在哪里？”有人说：“看哪，在拉玛的拿约。”","notes":[]},{"n":23,"t":"他就往那里去，到了拉玛的拿约。神的灵也临到他，他一面走一面受感说话，直到拉玛的拿约。","notes":[]},{"n":24,"t":"他也脱了衣服，也在撒母耳面前受感说话，一日一夜赤身躺卧。因此有人说：“扫罗也在先知中吗？”","notes":[]}]},"20":{"heading":"约拿单帮助大卫","verses":[{"n":1,"t":"大卫从拉玛的拿约逃跑，来到约拿单面前，对他说：“我做了什么，有什么罪孽，在你父亲面前犯了什么罪，他竟要寻索我的性命呢？”","notes":[]},{"n":2,"t":"约拿单对他说：“绝无此事！你必不至于死。看哪，我父做事，无论大小，没有不告诉我的。我父亲为什么要隐瞒我这件事呢？不会这样的！”","notes":[]},{"n":3,"t":"大卫又起誓说：“你父亲确实知道我在你眼前蒙恩。所以他说，‘这事不要让约拿单知道，免得他愁烦。’我指着永生的耶和华起誓，又指着你的性命起誓，我离死只差一步而已。”","notes":[]},{"n":4,"t":"约拿单对大卫说：“你心里所求的，我必为你成就。”","notes":[]},{"n":5,"t":"大卫对约拿单说：“看哪，明日是初一，我必须与王同席用餐，求你让我去藏在田野，直到第三日傍晚。","notes":[]},{"n":6,"t":"你父亲若见我不在席上，你就说：‘大卫恳求我允许他赶回本城伯利恒去，因为他全家在那里献年祭。’","notes":[]},{"n":7,"t":"你父亲若说好，你的仆人就平安了；他若大怒，你就知道他决意行恶。","notes":[]},{"n":8,"t":"求你施恩于仆人，因你在耶和华面前曾与仆人立约。我若有罪孽，你就亲自杀死我，何必把我交给你父亲呢？”","notes":[]},{"n":9,"t":"约拿单说：“绝无此事！我若确实知道我父亲决意害你，怎么会不告诉你呢？”","notes":[]},{"n":10,"t":"大卫对约拿单说：“你父亲若严厉回答你，谁来告诉我呢？”","notes":[]},{"n":11,"t":"约拿单对大卫说：“来，让我们到田野去。”二人就往田野去了。","notes":[]},{"n":12,"t":"约拿单对大卫说：“愿耶和华－以色列的神作证。明日约在这时候，或第三日，我一探出我父亲的心意，看哪，若对大卫是好意，我怎么会不派人来告诉你呢？","notes":[]},{"n":13,"t":"我父亲若有意害你，而我不告诉你，送你平安地离开，愿耶和华重重惩罚约拿单。愿耶和华与你同在，如同从前与我父亲同在一样。","notes":[]},{"n":14,"t":"你要照耶和华的慈爱恩待我，不但我活着的时候免我死亡，","notes":[]},{"n":15,"t":"就是耶和华从地面逐一剪除大卫仇敌的时候，你也永不可向我家断绝恩惠。”","notes":[]},{"n":16,"t":"于是约拿单与大卫家立约：“愿耶和华从大卫仇敌的手来追讨。”","notes":["“大卫仇敌”是“大卫子孙”的委婉用语，避免诅咒大卫的子孙。"]},{"n":17,"t":"约拿单因爱大卫如同爱自己的性命，就叫他再起誓。","notes":[]},{"n":18,"t":"约拿单对他说：“明日是初一，你的座位空着，人必察觉你不在。","notes":[]},{"n":19,"t":"到第三日，就要走一段长路下去，去到你遇事那天所藏的地方，在以色磐石的旁边等候。","notes":["“就要走一段长路下去”：七十士译本是“人家更会察觉”。","“以色磐石”：七十士译本是“石堆”。"]},{"n":20,"t":"我会向磐石旁边射三箭，如同射箭靶一样。","notes":[]},{"n":21,"t":"看哪，我会派僮仆，说：‘去把箭找来。’我若对僮仆喊说：‘看哪，箭在你的这边，把箭拿来’，你就可以平安回来；我指着永生的耶和华起誓，你一定没有事。","notes":[]},{"n":22,"t":"我若对孩子说：‘看哪，箭在你的前方’，你就要离开，因为是耶和华差你去的。","notes":[]},{"n":23,"t":"至于你和我，我们所说的话，看哪，耶和华在你我中间作证，直到永远。”","notes":[]},{"n":24,"t":"大卫就去藏在田野。到了初一，王要坐席用餐。","notes":[]},{"n":25,"t":"王照常坐在靠墙的位子上，约拿单在对面，押尼珥坐在扫罗旁边，大卫的座位却是空的。","notes":["“在对面”是根据七十士译本；原文是“起身”。"]},{"n":26,"t":"这日扫罗没有说什么，因为他说：“大卫或许有事，偶染不洁，还未得洁净。”","notes":[]},{"n":27,"t":"初二，大卫的座位还空着。扫罗对他儿子约拿单说：“耶西的儿子为何昨日、今日都没有来用餐呢？”","notes":[]},{"n":28,"t":"约拿单回答扫罗说：“大卫恳求我允许他回伯利恒去，","notes":[]},{"n":29,"t":"说：‘求你让我去，因为我家在城里有献祭的事，我哥哥吩咐我去。如今我若在你眼前蒙恩，求你让我去见我的兄弟。’所以大卫没有来赴王的筵席。”","notes":[]},{"n":30,"t":"扫罗向约拿单怒气大发，对他说：“你这顽梗悖逆之妇人所生的，我怎么会不知道你选择耶西的儿子，自取羞辱，也使你母亲露体蒙羞呢？","notes":["“选择耶西的儿子”：七十士译本是“作耶西儿子的朋友”。"]},{"n":31,"t":"只要耶西的儿子还活在世上一天，你和你的国必保不住。现在你要派人去，把他带到我这里来，因为他是该死的。”","notes":[]},{"n":32,"t":"约拿单回答父亲扫罗说：“他为什么该死呢？他做了什么呢？”","notes":[]},{"n":33,"t":"扫罗向约拿单掷枪要刺他，约拿单就知道他父亲决意要杀死大卫。","notes":[]},{"n":34,"t":"于是约拿单气愤愤地从席上起来。他在初二这天没有吃饭，因为他为大卫愁烦，又因为他父亲羞辱了他。","notes":[]},{"n":35,"t":"次日早晨，约拿单按着与大卫约定的时候到田野去，有一个小僮仆跟随他。","notes":[]},{"n":36,"t":"约拿单对僮仆说：“你跑去把我所射的箭找来。”僮仆跑去，约拿单就把箭射在僮仆的前方。","notes":[]},{"n":37,"t":"僮仆到了约拿单落箭之地，约拿单呼叫僮仆说：“箭不是在你的前方吗？”","notes":[]},{"n":38,"t":"约拿单又呼叫僮仆说：“快去，不要站在那里！”僮仆就捡起箭来，回到主人那里。","notes":[]},{"n":39,"t":"僮仆不知道这是什么意思，只有约拿单和大卫知道这事。","notes":[]},{"n":40,"t":"约拿单把他的弓箭交给僮仆，吩咐他说：“你拿到城里去。”","notes":[]},{"n":41,"t":"僮仆一去，大卫就从南边出来，俯伏在地，拜了三拜。他们彼此亲吻，一起哭泣，大卫哭得更悲哀。","notes":["“南边”：七十士译本是“石堆的旁边”。"]},{"n":42,"t":"约拿单对大卫说：“你平平安安地去吧！因为我们二人曾指着耶和华的名起誓说：‘愿耶和华在你我中间，以及你我后裔中间作证，直到永远。’”大卫就起身走了，约拿单也回城里去了。","notes":[]}]},"21":{"heading":"大卫逃离扫罗","verses":[{"n":1,"t":"大卫到了挪伯的亚希米勒祭司那里，亚希米勒战战兢兢地出来迎接他，对他说：“你为什么独自一人，没有人跟随你呢？”","notes":[]},{"n":2,"t":"大卫对亚希米勒祭司说：“王吩咐我一件事，对我说：‘我差遣你，吩咐你的这件事，不可让任何人知道。’因此我已告诉一些仆人到某处去。","notes":["“告诉...去”：死海古卷和一些其他古译本是“和一些仆人约在某处相会”。"]},{"n":3,"t":"现在你手中有什么？请你给我五个饼或是可以找到的食物。”","notes":[]},{"n":4,"t":"祭司对大卫说：“我手中没有普通的饼，只有圣饼，只能给没有亲近妇人的年轻人。”","notes":[]},{"n":5,"t":"大卫回答祭司说：“我们确实没有亲近妇人，如同往常我出征的时候一样。平常行路，仆人的身体都还分别为圣，何况今日岂不更使自己分别为圣吗？”","notes":["“身体”：原文是“器皿”。"]},{"n":6,"t":"祭司拿圣饼给他，因为在那里没有别的饼，只有那从耶和华面前撤下的供饼，就是换上热饼的日子取下来的。","notes":[]},{"n":7,"t":"当日，有扫罗的一个臣仆在那里，他留在耶和华的面前，名叫多益，是以东人，作扫罗的畜牧长。","notes":[]},{"n":8,"t":"大卫对亚希米勒说：“你手中有没有枪或刀？因为王的事紧急，连刀剑兵器我都没有带。”","notes":[]},{"n":9,"t":"祭司说：“你在以拉谷所杀的非利士人歌利亚的那刀，看哪，裹在布中，放在以弗得后边。你若要可以拿去，除此以外，再没有别的了。”大卫说：“没有什么可以跟它比的了！请你给我。”","notes":[]},{"n":10,"t":"那日大卫起来，躲避扫罗，逃到迦特王亚吉那里。","notes":[]},{"n":11,"t":"亚吉的臣仆对他说：“这不是那地的国王大卫吗？那里的人跳舞唱和：‘扫罗杀死千千，大卫杀死万万’，不是指着他说的吗？”","notes":[]},{"n":12,"t":"大卫把这些话放在心里，就很惧怕迦特王亚吉。","notes":[]},{"n":13,"t":"于是他在众人眼前一反常态，在他们中间装疯作癫，在城门的门扇上胡写乱画，任由唾沫流在胡子上。","notes":["“在他们中间”：原文是“在他们手中”。"]},{"n":14,"t":"亚吉对臣仆说：“看哪，你们看这人疯了，为什么带他到我这里来呢？","notes":[]},{"n":15,"t":"我岂缺少疯子，你们竟然带这人到我面前疯癫吗？这个人可以进我的家吗？”","notes":[]}]},"22":{"heading":"扫罗残杀祭司","verses":[{"n":1,"t":"大卫离开那里，逃到亚杜兰洞。他的兄弟和他父亲全家听见了，都下到他那里去。","notes":[]},{"n":2,"t":"凡生活窘迫的、欠债的、心里苦恼的都聚集到大卫那里，他就作他们的领袖，跟随他的约有四百人。","notes":[]},{"n":3,"t":"大卫从那里往摩押的米斯巴去，对摩押王说：“请你让我父母搬来，跟你们在一起，等我知道神要为我怎样做。”","notes":[]},{"n":4,"t":"大卫领他父母到摩押王面前。大卫住山寨一切的日子，他父母也都住在摩押王那里。","notes":["“领他父母到”：有些古译本是“留他父母在”。"]},{"n":5,"t":"先知迦得对大卫说：“你不要住在山寨，要到犹大地去。”大卫就去，来到哈列的树林。","notes":[]},{"n":6,"t":"扫罗听见大卫和跟随他之人的下落，扫罗正在基比亚，坐在山顶的柳树下，手里拿着枪，众臣仆侍立在左右。","notes":["“山顶”或译“拉玛”。"]},{"n":7,"t":"扫罗对左右侍立的臣仆说：“便雅悯人哪，听着！耶西的儿子也能把田地和葡萄园赐给你们各人吗？他能立你们各人作千夫长和百夫长吗？","notes":[]},{"n":8,"t":"你们竟都结党害我！我儿子与耶西的儿子立约的时候，无人告诉我；我儿子挑唆我的臣仆谋害我，像今日这样，也无人告诉我，为我忧虑。”","notes":[]},{"n":9,"t":"那时以东人多益站在扫罗的臣仆中，回答说：“我曾看见耶西的儿子往挪伯去，到了亚希突的儿子亚希米勒那里。","notes":[]},{"n":10,"t":"亚希米勒为他求问耶和华，给他食物，又把非利士人歌利亚的刀给了他。”","notes":[]},{"n":11,"t":"王就派人把亚希突的儿子亚希米勒祭司和他父亲的全家，就是在挪伯的祭司都召了来，他们都来到王那里。","notes":[]},{"n":12,"t":"扫罗说：“亚希突的儿子，听着！”他说：“我主，我在这里。”","notes":[]},{"n":13,"t":"扫罗对他说：“你为什么与耶西的儿子结党害我，把食物和刀给他，又为他求问神，使他起来谋害我，像今日这样？”","notes":[]},{"n":14,"t":"亚希米勒回答王说：“王的众臣仆中有谁比大卫忠心呢？他是王的女婿，又是你的侍卫长，并且是你宫中受敬重的人。","notes":["“又是你的侍卫长”是根据七十士译本和其他古译本；原文是“他离开你的侍卫”。"]},{"n":15,"t":"我今日才开始为他求问神吗？绝非如此！王不要归罪于我和我父全家，因为这事，无论大小，仆人都不知情。”","notes":[]},{"n":16,"t":"王说：“亚希米勒，你和你父全家都是该死的！”","notes":[]},{"n":17,"t":"王吩咐左右的侍卫说：“你们转身去杀耶和华的祭司吧！因为他们帮助大卫，知道大卫逃跑却不告诉我。”但王的臣仆都不愿动手杀耶和华的祭司。","notes":[]},{"n":18,"t":"王吩咐多益说：“你转身去杀祭司吧！”以东人多益就转身去杀祭司，那日杀了穿细麻布以弗得的，共八十五人，","notes":[]},{"n":19,"t":"又用刀把祭司城挪伯中的男女、孩童和吃奶的都杀了，又用刀杀了牛、羊和驴子。","notes":[]},{"n":20,"t":"亚希突的儿子亚希米勒有一个儿子逃脱了；他名叫亚比亚他，逃到大卫那里。","notes":[]},{"n":21,"t":"亚比亚他把扫罗杀耶和华祭司的事告诉大卫。","notes":[]},{"n":22,"t":"大卫对亚比亚他说：“那日我见以东人多益在那里，就知道他一定会告诉扫罗。你父的全家丧命，都是因我的缘故。","notes":[]},{"n":23,"t":"你可以住在我这里，不要惧怕。因为寻索你命的也要寻索我的命，你在我这里可得保护。”","notes":[]}]},"23":{"heading":"大卫救了基伊拉城","verses":[{"n":1,"t":"有人告诉大卫说：“看哪，非利士人攻击基伊拉，抢夺禾场。”","notes":[]},{"n":2,"t":"大卫求问耶和华说：“我可以去吗？我可以去攻打那些非利士人吗？”耶和华对大卫说：“你可以去攻打非利士人，拯救基伊拉。”","notes":[]},{"n":3,"t":"大卫的人对他说：“看哪，我们在犹大这里尚且惧怕，何况到基伊拉去攻打非利士人的军队呢？”","notes":[]},{"n":4,"t":"大卫又再求问耶和华，耶和华回答说：“你起身下基伊拉去，我必将非利士人交在你手里。”","notes":[]},{"n":5,"t":"于是大卫和他的人往基伊拉去，与非利士人打仗，大大击败他们，夺取他们的牲畜。这样，大卫救了基伊拉的居民。","notes":[]},{"n":6,"t":"亚希米勒的儿子亚比亚他逃往基伊拉到大卫那里的时候，手里拿着以弗得。","notes":[]},{"n":7,"t":"有人告诉扫罗，大卫到了基伊拉。扫罗说：“神将他交在我手里了，因为他进了有门有闩的城，把自己关起来了。”","notes":[]},{"n":8,"t":"于是扫罗召集众百姓，要下去攻打基伊拉，围困大卫和他的人。","notes":[]},{"n":9,"t":"大卫知道扫罗设计陷害他，就对亚比亚他祭司说：“把以弗得拿过来。”","notes":[]},{"n":10,"t":"大卫说：“耶和华－以色列的神啊，你仆人确实听见扫罗设法要到基伊拉来，为我的缘故毁灭这城。","notes":[]},{"n":11,"t":"基伊拉人会把我交在扫罗手里吗？扫罗会下来，正如你仆人所听见的吗？耶和华－以色列的神啊，求你指示仆人！”耶和华说：“他会下来。”","notes":[]},{"n":12,"t":"大卫又说：“基伊拉人会把我和我的人交在扫罗手里吗？”耶和华说：“他们会交出来。”","notes":[]},{"n":13,"t":"于是大卫和他的人约有六百名起身离开基伊拉，往他们所能去的地方去。有人告诉扫罗，大卫离开基伊拉逃走了，扫罗就停止出发了。","notes":[]},{"n":14,"t":"大卫住在旷野的山寨里，在西弗旷野的山区。扫罗天天寻索大卫，神却不将大卫交在他手里。","notes":[],"heads":["大卫在旷野躲避扫罗"]},{"n":15,"t":"大卫看到扫罗出来寻索他的命。那时，他住在西弗旷野的树林里；","notes":["“树林里”或音译“何列施”；下同。"]},{"n":16,"t":"扫罗的儿子约拿单起身，到树林里去见大卫，使他的手倚靠神得以坚固，","notes":[]},{"n":17,"t":"对他说：“不要惧怕！我父扫罗的手无法害你 ，你必作以色列的王，我必作你的宰相。我父扫罗也知道这事。”","notes":[]},{"n":18,"t":"于是二人在耶和华面前立约。大卫仍住在树林里，约拿单就回家去了。","notes":[]},{"n":19,"t":"西弗人上基比亚到扫罗那里，说：“大卫不是在我们那里，在树林里的山寨中，在荒野南边的哈基拉山藏着吗？","notes":["“荒野”或音译“约斯门”；下同。"]},{"n":20,"t":"现在，王啊，请随你的心愿要下来，就请下来；至于我们，一定会把他交在王的手里。”","notes":[]},{"n":21,"t":"扫罗说：“愿耶和华赐福给你们，因为你们体恤我。","notes":[]},{"n":22,"t":"请你们回去，再确定一下，调查并看清楚他落脚的地方，是谁看见他在那里，因为有人告诉我他很狡猾。","notes":["“调查...在那里”：七十士译本是“快快调查并看清楚他落脚的地方在哪里”。"]},{"n":23,"t":"你们要看清楚，调查他藏匿的每一个地方，回来给我确实的报告，我就与你们同去。他若在境内，我必从犹大的千门万户中搜出他来。”","notes":[]},{"n":24,"t":"西弗人动身，在扫罗以先往西弗去。大卫和他的人却在玛云旷野，在荒野南边的亚拉巴。","notes":[]},{"n":25,"t":"扫罗和他的人去寻索大卫。有人告诉大卫，他就下到岩石那里，留在玛云的旷野。扫罗听见了，就在玛云的旷野追赶大卫。","notes":[]},{"n":26,"t":"扫罗在山的这一边走，大卫和他的人在山的那一边。大卫急忙躲避扫罗，扫罗和他的人正四面围住大卫和他的人，要捉拿他们。","notes":[]},{"n":27,"t":"有使者来对扫罗说：“非利士人入境抢掠，请快快回去！”","notes":[]},{"n":28,"t":"于是扫罗不再追赶大卫，回去迎击非利士人。因此那地方名叫西拉．哈玛希罗结。","notes":["“西拉．哈玛希罗结”意思是“隔离岩”。"]},{"n":29,"t":"大卫从那里上去，住在隐．基底的山寨里。","notes":[]}]},"24":{"heading":"大卫饶扫罗的命","verses":[{"n":1,"t":"扫罗追赶非利士人回来，有人告诉他说：“看哪，大卫在隐．基底的旷野。”","notes":[]},{"n":2,"t":"扫罗就从全以色列中挑选三千精兵，往野山羊磐石的东边去，寻索大卫和他的人。","notes":["“东边”或译“前面”。"]},{"n":3,"t":"到了路旁的羊圈，在那里有个洞，扫罗进去大解。大卫和他的人正藏在洞里的深处。","notes":[]},{"n":4,"t":"大卫的人对大卫说：“看哪，这日子到了！耶和华曾对你说：‘看哪，我要将你的仇敌交在你手里，你可以照你看为好的对待他。’”大卫就起来，悄悄地割下扫罗外袍的衣角。","notes":[]},{"n":5,"t":"随后大卫心中自责，因为他割下了扫罗的衣角。","notes":[]},{"n":6,"t":"他对他的人说：“耶和华绝不允许我对我的主，耶和华的受膏者做这事，伸手害他，因为他是耶和华的受膏者。”","notes":[]},{"n":7,"t":"大卫用这话劝阻他的人，不许他们起来害扫罗。扫罗起来，从洞里出去，预备上路。","notes":[]},{"n":8,"t":"然后大卫也起来，从洞里出去，呼唤扫罗说：“我主，我王！”扫罗回头观看，大卫就屈身，脸伏于地下拜。","notes":[]},{"n":9,"t":"大卫对扫罗说：“你为何听信人的谗言，说‘看哪，大卫想要害你’呢？","notes":[]},{"n":10,"t":"看哪，今日你亲眼看见，在洞中耶和华将你交在我手里。有人要我杀你，我却爱惜你，说：‘我不敢伸手害我的主，因为他是耶和华的受膏者。’","notes":[]},{"n":11,"t":"我父啊，请看，看你外袍的衣角在我手中。我割下你外袍的衣角，却没有杀你。你知道，并且看见我没有恶意要悖逆你。你虽然要猎取我的命，我却没有得罪你。","notes":[]},{"n":12,"t":"愿耶和华在你我中间判断，愿耶和华在你身上为我伸冤，我却不亲手加害于你。","notes":[]},{"n":13,"t":"古人有句俗语说：‘恶事出于恶人。’我却不亲手加害于你。","notes":[]},{"n":14,"t":"以色列王出来要寻找谁呢？你要追赶谁呢？不过是一条死狗，一只跳蚤而已。","notes":[]},{"n":15,"t":"愿耶和华作仲裁者，在你我中间判断。愿他鉴察，为我伸冤，救我脱离你的手。”","notes":[]},{"n":16,"t":"大卫向扫罗说完了这些话，扫罗说：“我儿大卫，这是你的声音吗？”于是扫罗放声大哭，","notes":[]},{"n":17,"t":"对大卫说：“你比我公义，因为你以善待我，我却以恶待你。","notes":[]},{"n":18,"t":"今日你已显明是以善待我，因为耶和华将我交在你手里，你却没有杀我。","notes":[]},{"n":19,"t":"人若遇见仇敌，岂肯放他平安上路呢？愿耶和华因你今日向我所做的，以善回报你。","notes":[]},{"n":20,"t":"现在，看哪，我知道你一定会作王，以色列的国必要坚立在你手里。","notes":[]},{"n":21,"t":"现在你要指着耶和华向我起誓，你必不剪除我的后裔，必不从我父家除去我的名。”","notes":[]},{"n":22,"t":"于是大卫向扫罗起誓，扫罗就回家去，大卫和他的人也上山寨去了。","notes":[]}]},"25":{"heading":"撒母耳去世","verses":[{"n":1,"t":"撒母耳死了，以色列众人聚集，为他哀哭，把他葬在拉玛他的家里。大卫动身，下到巴兰的旷野。","notes":[]},{"n":2,"t":"在玛云有一个人，他的产业在迦密。这人是一个大富翁，有三千只绵羊，一千只山羊；他正在迦密剪羊毛。","notes":[]},{"n":3,"t":"这人名叫拿八，他的妻子名叫亚比该。拿八的妻子有美好的见识，又有美丽的容貌，但拿八为人刚愎凶恶，是迦勒族的人。","notes":[]},{"n":4,"t":"大卫在旷野听见拿八正在剪羊毛，","notes":[]},{"n":5,"t":"就派十个仆人，对他们说：“你们上迦密到拿八那里，提我的名向他问安。","notes":[]},{"n":6,"t":"你们要如此说：‘愿你来年平安，愿你家平安，愿你一切所有的都平安。","notes":["“你们要...来年平安”：有古译本是“你们要向我的弟兄如此说：愿你平安”。"]},{"n":7,"t":"现在我听说你有剪羊毛的人，你的牧人和我们在一起，他们在迦密一切的日子，我们没有欺负过他们，他们也未曾失去什么。","notes":[]},{"n":8,"t":"你问你的仆人，他们会告诉你。愿我的仆人在你眼前得欢心，因为我们是在好日子来的。请你随手分点食物给仆人和你儿子大卫。’”","notes":[]},{"n":9,"t":"大卫的仆人到了，就提大卫的名，把这一切话告诉拿八，他们就停顿下来。","notes":[]},{"n":10,"t":"拿八回答大卫的仆人说：“大卫是谁？耶西的儿子是谁？今日悖逆主人奔逃的仆人很多。","notes":[]},{"n":11,"t":"我岂可把饮食，以及我为剪羊毛的人所宰的肉给那些我不知道从哪里来的人呢？”","notes":[]},{"n":12,"t":"大卫的仆人转身从原路回去，照这一切的话告诉大卫。","notes":[]},{"n":13,"t":"大卫对他的人说：“你们各人都要佩上刀！”各人就都佩上刀，大卫也佩上刀。跟随大卫上去的约有四百人，留下二百人看守物件。","notes":[]},{"n":14,"t":"拿八的一个仆人告诉拿八的妻子亚比该说：“看哪，大卫从旷野派使者来向我主人问安，主人却辱骂他们。","notes":[]},{"n":15,"t":"但是那些人待我们真好；我们在田野与他们一切来往的日子，没有受他们欺负，也未曾失去什么。","notes":[]},{"n":16,"t":"我们在他们那里牧羊，一切的日子他们昼夜保护我们。","notes":["“保护我们”：原文直译“作我们的墙壁”。"]},{"n":17,"t":"现在，你当知道，看怎样做才好。不然，祸患必定临到我主人和他全家。他性情凶暴，无人敢与他说话。”","notes":[]},{"n":18,"t":"亚比该急忙将二百个饼，两皮袋酒，五只宰好的羊，五细亚烘熟的穗子，一百个葡萄干饼，二百个无花果饼，都驮在驴上，","notes":[]},{"n":19,"t":"对仆人说：“你们在我前面走，看哪，我跟着你们去。”她却没有告诉丈夫拿八。","notes":[]},{"n":20,"t":"亚比该骑着驴，正下山坡，看哪，大卫和他的人正迎着亚比该下来，她就去迎接他们。","notes":[]},{"n":21,"t":"大卫曾说：“我在旷野为那人看守他一切所有的，以致他未失去任何一样东西，实在是徒然了！他竟然向我以恶报善。","notes":[]},{"n":22,"t":"凡属拿八的男丁，我若留一个到明日早晨，愿神重重惩罚大卫！”","notes":["“大卫”是根据七十士译本；原文是“大卫的仇敌”。"]},{"n":23,"t":"亚比该看见大卫，就急忙下驴，在大卫面前脸伏于地叩拜。","notes":[]},{"n":24,"t":"她俯伏在大卫的脚前，说：“我主啊，愿这罪归于我！求你容许使女向你进言，更求你听使女的话。","notes":[]},{"n":25,"t":"我主不必理会拿八这性情凶暴的人，他就像他的名字一样；他名叫拿八，为人也真是愚顽。至于我，你的使女并没有看见我主所派来的仆人。","notes":["“拿八”意思是“愚顽”。"]},{"n":26,"t":"现在，我主啊，耶和华既然阻止你亲手报仇，避免流人的血，我指着永生的耶和华起誓，又指着你的性命起誓：‘现在，愿你的仇敌和谋害我主的人都像拿八一样。’","notes":[]},{"n":27,"t":"现在求我主把婢女送来的礼物给跟随我主的仆人。","notes":[]},{"n":28,"t":"求你原谅使女的冒犯。耶和华必为我主建立坚固的家，因为我主为耶和华争战，并且你一生的日子查不出有什么恶来。","notes":[]},{"n":29,"t":"虽有人起来追逼你，要寻索你的性命，我主的性命在耶和华－你的神那里，如同藏在生命的宝藏中。至于你仇敌的性命，耶和华必甩去，如用机弦甩石一样。","notes":[]},{"n":30,"t":"耶和华照所应许你的福气赐给我主，立你作以色列王的时候，","notes":[]},{"n":31,"t":"我主就不至于因为亲手报仇，流了无辜人的血，而心里不安，良心有亏了。耶和华赐福给我主的时候，求你记得你的使女。”","notes":[]},{"n":32,"t":"大卫对亚比该说：“耶和华－以色列的神是应当称颂的，因为他今日派你来迎接我。","notes":[]},{"n":33,"t":"你和你的见识也配得称赞，因为你今日拦阻我亲手报仇、流人的血。","notes":[]},{"n":34,"t":"我指着阻止我加害于你的耶和华－以色列永生的神起誓，若不是你很快地来迎接我，到早晨天亮的时候，凡属拿八的男丁，必定一个也不留。”","notes":[]},{"n":35,"t":"大卫从亚比该手中收了她带来的礼物，对她说：“平平安安上你的家去吧！你看，我看了你的情面，听了你的话。”","notes":[]},{"n":36,"t":"亚比该到拿八那里，看哪，他在家里摆设宴席，如同王的宴席。拿八心情舒畅，酩酊大醉。所以亚比该大小事都没有告诉他，直等到早晨天亮的时候。","notes":[]},{"n":37,"t":"到了早晨，拿八酒醒了，他的妻子把这些事都告诉他，他就发心脏病快死了，僵如石头。","notes":[]},{"n":38,"t":"过了十天，耶和华击打拿八，他就死了。","notes":[]},{"n":39,"t":"大卫听见拿八死了，就说：“耶和华是应当称颂的，因为我从拿八手中受了羞辱，他为我伸冤，又阻止他的仆人行恶；耶和华使拿八的恶归到他自己头上。”于是大卫派人去向亚比该说，要娶她为妻。","notes":[]},{"n":40,"t":"大卫的仆人来到迦密，到亚比该那里，对她说：“大卫派我们到你这里，要娶你作他的妻子。”","notes":[]},{"n":41,"t":"亚比该起来叩拜，俯伏在地，说：“看哪，你的使女情愿作婢女，为我主的仆人洗脚。”","notes":[]},{"n":42,"t":"亚比该立刻起身，骑上驴，五个女仆跟着她走。她跟从大卫的使者去，就作了大卫的妻子。","notes":[]},{"n":43,"t":"大卫先前娶了耶斯列人亚希暖，她们二人都作了他的妻子。","notes":[]},{"n":44,"t":"扫罗已把他的女儿米甲，就是大卫的妻子，给了迦琳人拉亿的儿子帕提为妻。","notes":[]}]},"26":{"heading":"大卫又饶扫罗的命","verses":[{"n":1,"t":"西弗人来到基比亚，到扫罗那里，说：“大卫不是在荒野东边的哈基拉山藏着吗？”","notes":["“荒野”或音译“约斯门”；下同。","“东边”或译“前面”；下同。"]},{"n":2,"t":"扫罗动身，带领以色列人中挑选的三千精兵下到西弗的旷野，要在那里寻索大卫。","notes":[]},{"n":3,"t":"扫罗在荒野东边的哈基拉山，在路旁安营。那时大卫住在旷野，看见扫罗到旷野来追赶他，","notes":[]},{"n":4,"t":"大卫就派人去探听，知道扫罗果然来了。","notes":[]},{"n":5,"t":"大卫起来，到扫罗安营的地方，看见扫罗和尼珥的儿子押尼珥元帅躺卧之处；扫罗睡在军营里，士兵安营在他周围。","notes":[]},{"n":6,"t":"大卫对赫人亚希米勒和洗鲁雅的儿子约押的兄弟亚比筛说：“谁同我下到扫罗营里去？”亚比筛说：“我同你下去。”","notes":[]},{"n":7,"t":"于是大卫和亚比筛夜间到了士兵那里；看哪，扫罗睡在军营里，他的枪在头旁，插在地上。押尼珥和士兵睡在他周围。","notes":[]},{"n":8,"t":"亚比筛对大卫说：“神将你的仇敌交在你手里，现在让我拿枪把他刺透在地上，一刺就成，不用再刺他了。”","notes":[]},{"n":9,"t":"大卫对亚比筛说：“不可杀害他！有谁伸手害耶和华的受膏者而无罪呢？”","notes":[]},{"n":10,"t":"大卫又说：“我指着永生的耶和华起誓，他或被耶和华击杀，或死期到了，或出战阵亡，","notes":[]},{"n":11,"t":"耶和华绝不允许我伸手害耶和华的受膏者。现在你可以把他头旁的枪和水壶拿来，我们就走。”","notes":[]},{"n":12,"t":"大卫从扫罗的头旁拿了枪和水壶，他们就走了。没有人看见，没有人知道，也没有人醒过来。他们都睡着了，因为耶和华使他们沉睡了。","notes":[]},{"n":13,"t":"大卫过到另一边去，远远地站在山顶上，与他们相离很远。","notes":[]},{"n":14,"t":"大卫呼叫百姓和尼珥的儿子押尼珥说：“押尼珥，你为何不回答呢？”押尼珥回答说：“你是谁？竟敢呼唤王呢？”","notes":[]},{"n":15,"t":"大卫对押尼珥说：“你不是个大丈夫吗？以色列中谁能比你呢？百姓中有一个人进来要害死你主你王，你为何没有保护你主你王呢？","notes":[]},{"n":16,"t":"你做的这件事不好！我指着永生的耶和华起誓，你们都是该死的，因为你们没有保护你们的主，就是耶和华的受膏者。现在你看，王头旁的枪和水壶在哪里？”","notes":[]},{"n":17,"t":"扫罗认出大卫的声音，就说：“我儿大卫，这是你的声音吗？”大卫说：“我主我王啊，是我的声音。”","notes":[]},{"n":18,"t":"又说：“我主为何要追赶仆人呢？我做了什么？我手做了什么恶事呢？","notes":[]},{"n":19,"t":"现在求我主我王听仆人的话：若是耶和华激发你来攻击我，愿耶和华悦纳供物；若是出于人，愿他们在耶和华面前受诅咒，因为他们今日赶逐我，不让我在耶和华的产业中有分，说：‘你去事奉别神吧！’","notes":[]},{"n":20,"t":"现在不要使我的血流在远离耶和华面的地上。因为以色列王出来，只不过是寻找一只跳蚤，如同人在山上猎取一只鹧鸪。”","notes":[]},{"n":21,"t":"扫罗说：“我有罪了！我儿大卫，回来吧！我必不再加害于你，因为你今日看我的性命为宝贵。看哪，我是个糊涂人，大大错了。”","notes":[]},{"n":22,"t":"大卫回答说：“看哪，这是王的枪，可以吩咐一个仆人过来拿去。","notes":[]},{"n":23,"t":"今日耶和华将王交在我手里，我却不肯伸手害耶和华的受膏者。耶和华必照各人的公义诚实报应他。","notes":[]},{"n":24,"t":"看哪，我今日看重你的性命，愿耶和华也照样看重我的性命，并且拯救我脱离一切患难。”","notes":[]},{"n":25,"t":"扫罗对大卫说：“我儿大卫，愿你得福！你必做大事，也必得胜。”于是大卫上路，扫罗也回自己的地方去了。","notes":[]}]},"27":{"heading":"大卫在非利士人中","verses":[{"n":1,"t":"大卫心里说：“总有一天我会死在扫罗手里，现在我最好逃到非利士人的地去，扫罗就会绝望，不会继续在以色列全境内寻索我了。这样，我才可以脱离他的手。”","notes":[]},{"n":2,"t":"于是大卫动身，和跟随他的六百人投奔玛俄的儿子迦特王亚吉去了。","notes":[]},{"n":3,"t":"大卫和他的两个妻子，就是耶斯列人亚希暖和作过拿八妻子的迦密人亚比该，以及他的人，连同各人的眷属，都住在迦特的亚吉那里。","notes":[]},{"n":4,"t":"有人告诉扫罗：“大卫逃到迦特。”扫罗就不再寻索他了。","notes":[]},{"n":5,"t":"大卫对亚吉说：“我若蒙你看得起，求你在郊外的城镇中赐我一个地方，让我住在那里。仆人何必与王同住京城呢？”","notes":[]},{"n":6,"t":"当日亚吉把洗革拉赐给他，因此洗革拉属于犹大王，直到今日。","notes":[]},{"n":7,"t":"大卫在非利士人的地，住的期间有一年四个月。","notes":[]},{"n":8,"t":"大卫和他的人上去，侵夺基述人、基色人、亚玛力人，这些是从帖兰经过书珥直到埃及地的居民。","notes":["“这些是<ins>.的居民”是根据七十士译本；原文是“这些居民历来就在那地，从书珥直到埃及地”。"]},{"n":9,"t":"大卫攻击那地，无论男女没有留下一个活口，又夺获牛、羊、驴、骆驼和衣服，回来到亚吉那里。","notes":[]},{"n":10,"t":"亚吉说：“今日你们没有去抢夺什么地方吧？”大卫说：“侵夺了犹大、耶拉篾、基尼等地的南方。”","notes":["“今日</ins>.地方吧”：死海古卷和一些古译本是“你们今日侵夺了谁呢”。"]},{"n":11,"t":"无论男女，大卫没有留下一个活口带到迦特来。他说：“恐怕他们把我们的事告诉人，说：‘大卫如此做了。’”这是他住在非利士人之地一切日子的惯例。","notes":[]},{"n":12,"t":"亚吉信了大卫，说：“大卫已经使本族以色列人憎恶他，所以他必永远作我的仆人了。”","notes":[]}]},"28":{"heading":"扫罗求问女巫","verses":[{"n":1,"t":"那时，非利士人召集军队，要与以色列打仗。亚吉对大卫说：“你当知道，你和你的人都要随我出征。”","notes":[]},{"n":2,"t":"大卫对亚吉说：“好，仆人所能做的事，王都知道。”亚吉对大卫说：“好，我立你终生作我的侍卫。”","notes":["“我”：原文是“我的头”。"]},{"n":3,"t":"那时撒母耳已经死了，以色列众人为他哀哭，把他葬在他的本城拉玛。扫罗曾在国内驱除招魂的和行巫术的人。","notes":[]},{"n":4,"t":"非利士人集合，来到书念安营；扫罗集合以色列众人在基利波安营。","notes":[]},{"n":5,"t":"扫罗看见非利士的军队，就惧怕，心中大大战兢。","notes":[]},{"n":6,"t":"扫罗求问耶和华，耶和华却不藉梦，或乌陵，或先知回答他。","notes":[]},{"n":7,"t":"扫罗吩咐臣仆说：“为我找一个招魂的妇人，我好去问她。”臣仆对他说：“看哪，在隐．多珥有一个招魂的妇人。”","notes":[]},{"n":8,"t":"于是扫罗改了装，穿上别的衣服，带着两个人，夜里去见那妇人。扫罗说：“请你用招魂的法术，把我所告诉你的死人，为我招上来。”","notes":[]},{"n":9,"t":"妇人对他说：“看哪，你知道扫罗所做的，他从国中剪除招魂的和行巫术的。你为何为我的性命设下罗网，要害死我呢？”","notes":[]},{"n":10,"t":"扫罗向妇人指着耶和华起誓说：“我指着永生的耶和华起誓，你必不因这事受罚。”","notes":[]},{"n":11,"t":"妇人说：“我为你招谁上来呢？”他说：“为我招撒母耳上来。”","notes":[]},{"n":12,"t":"妇人看见撒母耳，就大声喊叫。妇人对扫罗说：“你是扫罗，为什么欺骗我呢？”","notes":[]},{"n":13,"t":"王对妇人说：“不要惧怕，你看见什么呢？”妇人对扫罗说：“我看见有神明从地里上来。”","notes":[]},{"n":14,"t":"扫罗说：“他是怎样的形状？”妇人说：“有一个老人上来，身穿长袍。”扫罗知道是撒母耳，就屈身，脸伏于地下拜。","notes":[]},{"n":15,"t":"撒母耳对扫罗说：“你为什么搅扰我，招我上来呢？”扫罗说：“我十分为难，因为非利士人攻击我，神离开我，不再藉先知或梦回答我。因此请你上来，好指示我应当怎样做。”","notes":[]},{"n":16,"t":"撒母耳说：“耶和华已经离开你，与你为敌，你何必问我呢？","notes":[]},{"n":17,"t":"耶和华照他藉我所说的话为他自己实现了。耶和华已经从你手里夺去国权，赐给别人，就是大卫。","notes":["“为他自己”：七十士译本是“向你”。"]},{"n":18,"t":"因为你没有听从耶和华的话，没有执行他对亚玛力人的恼怒，所以今日耶和华向你做这事。","notes":[]},{"n":19,"t":"耶和华也必将你和以色列交在非利士人手里。明日你和你儿子们必与我在一处了；耶和华也必将以色列的军兵交在非利士人手里。”","notes":[]},{"n":20,"t":"扫罗突然全身仆倒在地，因为撒母耳的话令他十分惧怕。他毫无气力，因为他一日一夜都没有吃什么。","notes":[]},{"n":21,"t":"妇人到扫罗面前，见他极其惊恐，对他说：“看哪，婢女听从了你，不顾惜自己的性命，遵从你吩咐我的话。","notes":[]},{"n":22,"t":"现在求你也听婢女的话，让我在你面前摆上一点食物，你吃了才有气力上路。”","notes":[]},{"n":23,"t":"扫罗不肯，说：“我不吃。”但他的仆人和那妇人再三劝他，他才听他们的话，从地上起来，坐在床上。","notes":[]},{"n":24,"t":"妇人急忙把家里的一只肥牛犊宰了，又拿面来揉，烤成无酵饼，","notes":[]},{"n":25,"t":"摆在扫罗和他仆人面前。他们吃了，当夜就起身走了。","notes":[]}]},"29":{"heading":"非利士人拒绝大卫","verses":[{"n":1,"t":"非利士人聚集他们所有的军队到亚弗；以色列人在耶斯列的泉旁安营。","notes":[]},{"n":2,"t":"非利士人的领袖各率队伍，或百或千的前进；大卫和他的人同亚吉跟在后边前进。","notes":[]},{"n":3,"t":"非利士人的领袖说：“这些希伯来人在这里做什么呢？”亚吉对非利士人的领袖说：“这不是以色列王扫罗的臣仆大卫吗？他在我这里有些年日了。自从他投降直到今日，我未曾见他有什么过错。”","notes":[]},{"n":4,"t":"非利士人的领袖向亚吉发怒，对他说：“叫这人回去！叫他回到你指派他的地方去，不可让他同我们出征，免得他在阵上反成为我们的敌人。他用什么与他主人复和呢？岂不是用我们这些人的首级吗？","notes":[]},{"n":5,"t":"有人跳舞唱和说：‘扫罗杀死千千，大卫杀死万万’，不就是这个大卫吗？”","notes":[]},{"n":6,"t":"亚吉叫大卫来，对他说：“我指着永生的耶和华起誓，你是个正直人。你随我在军中出入，我也很满意。自从你投奔我到如今，我未曾看见你有什么过失，但是众领袖看你不顺眼。","notes":[]},{"n":7,"t":"现在你平平安安地回去，不要做非利士人领袖眼中看为恶的事。”","notes":[]},{"n":8,"t":"大卫对亚吉说：“但我做了什么呢？自从仆人到你面前，直到今日，你查出我有什么过错，使我不去攻击我主我王的仇敌呢？”","notes":[]},{"n":9,"t":"亚吉回答大卫说：“我知道你在我眼中是好人，如同神的使者一样，只是非利士人的领袖说：‘这人不可同我们上战场。’","notes":[]},{"n":10,"t":"现在，你和跟随你来的，就是你主人的仆人，清晨要早早起来，回到我所指派你的地方去，不要把中伤的话放在心上，因为你在我面前很好。你们清晨早早起来，天一亮就回去吧！”","notes":["“回到...很好”是根据七十士译本；原文没有。"]},{"n":11,"t":"于是大卫和他的人清晨早早起来，回到非利士人的地去。非利士人也上耶斯列去了。","notes":[]}]},"30":{"heading":"与亚玛力人争战","verses":[{"n":1,"t":"第三日，大卫和他的人到了洗革拉。亚玛力人已经侵夺尼革夫和洗革拉。他们攻破洗革拉，用火焚烧。","notes":[]},{"n":2,"t":"他们掳去城内的妇女和城中的大小人口，一个都没有杀，全都带走，他们就上路去了。","notes":[]},{"n":3,"t":"大卫和他的人到了那城，看哪，城已被火烧毁，他们的妻子儿女都被掳去了。","notes":[]},{"n":4,"t":"大卫和跟随他的百姓就放声大哭，直到没有气力再哭。","notes":[]},{"n":5,"t":"大卫的两个妻子，耶斯列人亚希暖和作过拿八妻子的迦密人亚比该，也被掳去了。","notes":[]},{"n":6,"t":"大卫非常焦急，因为众百姓为自己的儿女痛心，说要用石头打死他。大卫却倚靠耶和华─他的神，坚定自己。","notes":[]},{"n":7,"t":"大卫对亚希米勒的儿子亚比亚他祭司说：“请你把以弗得拿来给我。”亚比亚他就把以弗得拿给大卫。","notes":[]},{"n":8,"t":"大卫求问耶和华说：“我追赶这群人，是否追得上呢？”耶和华对他说：“你可以追，一定追得上，也一定救得回来。”","notes":[]},{"n":9,"t":"于是，大卫出发，他和跟随他的六百人来到比梭溪，那些不能前去的就留在那里。","notes":[]},{"n":10,"t":"大卫带着四百人往前追赶；有二百人疲乏，不能过比梭溪，留在那里。","notes":[]},{"n":11,"t":"这四百人在田野遇见一个埃及人，就带他到大卫面前，给他饼吃，给他水喝，","notes":[]},{"n":12,"t":"又给他一块无花果饼，两个葡萄干饼。他吃了，精神就恢复了，因为他三日三夜没有吃饼，没有喝水。","notes":[]},{"n":13,"t":"大卫对他说：“你是谁的人？你从哪里来？”他说：“我是埃及的青年，是亚玛力人的奴仆。因为我三天前生病，我主人就把我撇弃了。","notes":[]},{"n":14,"t":"我们侵夺了基利提的南方和属犹大的地，以及迦勒地的南方，又用火烧了洗革拉。”","notes":[]},{"n":15,"t":"大卫对他说：“你肯领我们下到那群人那里吗？”他说：“你要向我指着神起誓，你不杀我，也不把我交在我主人手里，我就领你下到那群人那里。”","notes":[]},{"n":16,"t":"那人领大卫下去，看哪，他们分散在全地面，吃喝跳舞，因为他们从非利士人的地和犹大地掳来的财物非常多。","notes":[]},{"n":17,"t":"大卫击杀他们，从黎明直到次日晚上，除了四百个骑骆驼逃走的青年之外，一个也没有逃脱。","notes":[]},{"n":18,"t":"亚玛力人所掳去的财物，大卫全都夺回，并救回他的两个妻子。","notes":[]},{"n":19,"t":"凡亚玛力人所掳去的，无论大小、儿女、掠物和一切被掳去的，大卫全都夺回来。","notes":[]},{"n":20,"t":"大卫所夺来的牛群羊群，有人赶在群畜前面，说：“这是大卫的掠物。”","notes":[]},{"n":21,"t":"大卫到了那疲乏不能跟随、留在比梭溪的二百人那里。他们出来迎接大卫和跟随他的百姓。大卫上前向他们问安。","notes":[]},{"n":22,"t":"跟随大卫去的人中，每一个恶人和无赖都说：“这些人既然没有和我同去，我们所夺的财物就不分给他们，只把他们各人的妻子儿女给他们，让他们带回去就好了。”","notes":[]},{"n":23,"t":"大卫说：“我的弟兄，耶和华所赐给我们的，你们不可这么做，因为他保佑了我们，把那群来攻击我们的人交在我们手里。","notes":[]},{"n":24,"t":"谁肯在这事上听你们呢？上阵的分得多少，留下看守物件的也分得多少，大家应当平分。”","notes":[]},{"n":25,"t":"从那日起，大卫定此为以色列的律例典章，直到今日。","notes":[]},{"n":26,"t":"大卫到了洗革拉，从掠物中取些送给他的朋友，就是犹大的长老，说：“看哪，这是从耶和华仇敌那里夺来的，送给你们作礼物。”","notes":[]},{"n":27,"t":"有在伯特利的，尼革夫之拉末的，雅提珥的，","notes":["“伯特利”可能是“彼土利”；参代上 4．30。"]},{"n":28,"t":"有在亚罗珥的，息末的，以实提莫的，","notes":[]},{"n":29,"t":"有在拉哈勒的，耶拉篾各城的，基尼各城的，","notes":[]},{"n":30,"t":"有在何珥玛的，坡拉珊的，亚挞的，","notes":["“坡拉珊”：有古卷是“歌拉珊”。"]},{"n":31,"t":"有在希伯仑的，以及大卫和跟随他的人经常进出之处的。","notes":[]}]},"31":{"heading":"扫罗和他儿子的死","verses":[{"n":1,"t":"非利士人攻打以色列。以色列人在非利士人面前逃跑，很多人在基利波山被杀仆倒。","notes":["“很多人”：原文是“他们”。"]},{"n":2,"t":"非利士人紧追扫罗和他的儿子，杀了扫罗的儿子约拿单、亚比拿达、麦基．舒亚。","notes":[]},{"n":3,"t":"攻击扫罗的战事激烈，弓箭手追上他，他被弓箭手射中，伤势很重。","notes":["“他被...伤势很重”或译“他在弓箭手前浑身战抖”。"]},{"n":4,"t":"扫罗吩咐拿他兵器的人说：“你拔出刀来，把我刺死，免得那些未受割礼的人来刺我，凌辱我。”但拿兵器的人不肯，因为他非常惧怕。于是扫罗拿起刀来，伏在刀上。","notes":[]},{"n":5,"t":"拿兵器的人见扫罗已死，也伏在刀上跟他一起死。","notes":[]},{"n":6,"t":"这样，扫罗和他三个儿子，与拿他兵器的人，以及他所有的人，都在那日一起死了。","notes":["七十士译本没有“以及他所有的人”。"]},{"n":7,"t":"住平原那边和约旦河那边的以色列人，见以色列军兵逃跑，扫罗和他儿子都死了，就弃城逃跑。非利士人前来住在其中。","notes":[]},{"n":8,"t":"次日，非利士人来剥那些被杀之人的衣服，看见扫罗和他三个儿子仆倒在基利波山。","notes":[]},{"n":9,"t":"他们割下他的首级，剥了他的盔甲，派人到非利士人之地的四境，报信给他们庙里的偶像和众百姓。","notes":[]},{"n":10,"t":"他们将扫罗的盔甲放在亚斯她录庙里，把他的尸身钉在伯．珊的城墙上。","notes":[]},{"n":11,"t":"基列的雅比居民听见非利士人向扫罗所行的事，","notes":[]},{"n":12,"t":"他们所有的勇士就起身，走了一夜，把扫罗和他儿子的尸身从伯．珊城墙上取下来，送到雅比，在那里用火烧了，","notes":[]},{"n":13,"t":"把骸骨葬在雅比的柳树下，并且禁食七日。","notes":[]}]}},"2SA":{"1":{"heading":"大卫为扫罗和约拿单悲泣","verses":[{"n":1,"t":"扫罗死后，大卫击杀亚玛力人回来，在洗革拉住了两天。","notes":[]},{"n":2,"t":"第三天，看哪，有一人从扫罗的营里出来，衣服撕裂，头蒙灰尘，到大卫面前伏地叩拜。","notes":[]},{"n":3,"t":"大卫对他说：“你从哪里来？”他说：“我从以色列的营里逃来。”","notes":[]},{"n":4,"t":"大卫又对他说：“事情怎么样？请你告诉我。”他说：“士兵从阵上逃跑，也有许多士兵仆倒死亡，扫罗和他儿子约拿单也死了。”","notes":[]},{"n":5,"t":"大卫问报信的青年说：“你怎么知道扫罗和他儿子约拿单死了呢？”","notes":[]},{"n":6,"t":"报信的青年说：“我恰巧到基利波山，看哪，扫罗靠在自己的枪上，看哪，有战车、骑兵紧紧地追他。","notes":[]},{"n":7,"t":"他回头看见我，就呼叫我。我说：‘我在这里。’","notes":[]},{"n":8,"t":"他问我说：‘你是什么人？’我说：‘我是亚玛力人。’","notes":[]},{"n":9,"t":"他对我说：‘请你站到我这里来，把我杀死，因为我非常痛苦，只剩下一口气。’","notes":[]},{"n":10,"t":"我就站到他那里，杀了他，因为我知道他一倒下就活不了。然后，我把他头上的冠冕和臂上的镯子拿到我主这里来。”","notes":[]},{"n":11,"t":"大卫就抓着自己的衣服，把衣服撕裂，所有跟随他的人也都如此。","notes":[]},{"n":12,"t":"他们为扫罗和他儿子约拿单，以及耶和华的百姓和以色列家的人悲哀哭泣，禁食到晚上，因为他们都倒在刀下。","notes":[]},{"n":13,"t":"大卫问报信的青年说：“你是哪里人？”他说：“我是一个寄居者的儿子，是亚玛力人。”","notes":[]},{"n":14,"t":"大卫对他说：“你动手杀害耶和华的受膏者，怎么不畏惧呢？”","notes":[]},{"n":15,"t":"大卫叫了一个仆人来，说：“来，杀了他！”仆人击杀他，他就死了。","notes":[]},{"n":16,"t":"大卫对他说：“你的血归到你自己头上，因为你亲口作证控诉自己，说：‘我杀了耶和华的受膏者。’”","notes":[]},{"n":17,"t":"大卫作了这首哀歌，哀悼扫罗和他儿子约拿单，","notes":[],"heads":["大卫为扫罗和约拿单作哀歌"]},{"n":18,"t":"并吩咐人把这首“弓歌”教导犹大人，看哪，它写在《雅煞珥书》上：","notes":[]},{"n":19,"t":"以色列啊，尊荣者在你的高处被杀！大英雄竟然仆倒！","notes":[]},{"n":20,"t":"不要在迦特报告，不要在亚实基伦街上传扬，免得非利士的女子欢喜，免得未受割礼之人的女子欢乐。","notes":[]},{"n":21,"t":"基利波山哪，愿你那里没有雨，没有露！愿你的田地无土产可作供物！因为英雄的盾牌在那里受辱，扫罗的盾牌没有抹油。","notes":[]},{"n":22,"t":"在被杀者的血前，在勇士的脂肪前，约拿单的弓绝不退缩，扫罗的刀断不虚回。","notes":[]},{"n":23,"t":"扫罗和约拿单生时相悦相爱，死时也不分离。他们比鹰更快，比狮子还强。","notes":[]},{"n":24,"t":"以色列的女子啊，当为扫罗哭泣！他曾使你们穿朱红色的美衣，使你们衣服有黄金的妆饰。","notes":[]},{"n":25,"t":"英雄竟然在阵上仆倒！约拿单竟然在你的高处被杀！","notes":[]},{"n":26,"t":"我兄约拿单哪，我为你悲伤！我甚喜爱你！你对我的爱何等奇妙，过于妇女的爱情。","notes":[]},{"n":27,"t":"英雄竟然仆倒！兵器竟然废弃！","notes":[]}]},"2":{"heading":"大卫受膏为犹大王","verses":[{"n":1,"t":"此后，大卫求问耶和华说：“我可以上犹大的一个城去吗？”耶和华对他说：“可以上去。”大卫说：“我上哪一个城去呢？”耶和华说：“希伯仑。”","notes":[]},{"n":2,"t":"于是大卫和他的两个妻子，一个是耶斯列人亚希暖，一个是作过迦密人拿八妻子的亚比该，都上那里去了。","notes":[]},{"n":3,"t":"大卫也把跟随他的人和他们各人的眷属一同带上去，住在希伯仑的城镇中。","notes":[]},{"n":4,"t":"犹大人来，在那里膏大卫作犹大家的王。有人告诉大卫说：“埋葬扫罗的是基列的雅比人。”","notes":[]},{"n":5,"t":"大卫就派使者到基列的雅比人那里，对他们说：“愿耶和华赐福给你们！因为你们忠心对待你们的主扫罗，埋葬了他。","notes":[]},{"n":6,"t":"你们既做了这事，愿耶和华以慈爱和信实待你们，我也要为此厚待你们。","notes":[]},{"n":7,"t":"现在，你们的主扫罗死了，犹大家也已经膏我作他们的王，你们的手要坚强，要作英勇的人。”","notes":[]},{"n":8,"t":"扫罗军队的元帅，尼珥的儿子押尼珥，曾将扫罗的儿子伊施．波设带过河，到玛哈念，","notes":["“伊施．波设”又名“伊施巴力”；参代上8．33，9．39；又名“亦施韦”，参撒上14．49；本卷书下同。"],"heads":["伊施．波设作以色列王"]},{"n":9,"t":"立他作王，治理基列、亚书利、耶斯列、以法莲、便雅悯和以色列众人。","notes":[]},{"n":10,"t":"扫罗的儿子伊施．波设登基的时候年四十岁，作以色列王二年，但是犹大家却随从大卫。","notes":[]},{"n":11,"t":"大卫在希伯仑作犹大家的王，共七年六个月。","notes":[]},{"n":12,"t":"尼珥的儿子押尼珥和扫罗的儿子伊施．波设的仆人从玛哈念出来，往基遍去。","notes":[],"heads":["扫罗家和大卫家争战"]},{"n":13,"t":"洗鲁雅的儿子约押和大卫的仆人也出来，在基遍池旁与他们相遇；一队坐在池的这边，一队坐在池的那边。","notes":[]},{"n":14,"t":"押尼珥对约押说：“让年轻人起来，在我们面前较量一下吧！”约押说：“让他们起来吧。”","notes":[]},{"n":15,"t":"他们就起来，点了人数过来：属扫罗儿子伊施．波设的有便雅悯人十二名，大卫的仆人也有十二名。","notes":[]},{"n":16,"t":"每人抓住对方的头，用刀刺对方的肋旁，一同仆倒。所以，那地叫做希利甲．哈素林，就在基遍。","notes":[]},{"n":17,"t":"那日战况激烈，押尼珥和以色列人败在大卫的仆人面前。","notes":[]},{"n":18,"t":"在那里有洗鲁雅的三个儿子：约押、亚比筛、亚撒黑。亚撒黑的脚快如野地里的羚羊；","notes":[]},{"n":19,"t":"亚撒黑追赶押尼珥，直追赶他不偏左右。","notes":[]},{"n":20,"t":"押尼珥回头说：“亚撒黑，是你吗？”他说：“是我。”","notes":[]},{"n":21,"t":"押尼珥对他说：“你转左或转右，去抓一个年轻人，剥去他的战衣吧。”亚撒黑却不肯转开而不追赶他。","notes":[]},{"n":22,"t":"押尼珥又对亚撒黑说：“转开，不要再追我了！我何必把你击杀在地上呢？我若杀了你，怎么有脸见你哥哥约押呢？”","notes":[]},{"n":23,"t":"亚撒黑仍不肯转开，押尼珥就用回马枪刺入他的肚腹，甚至枪从背后穿出，亚撒黑就仆倒在那里，当场死了。众人赶到亚撒黑仆倒而死的地方，就都站住。","notes":["“用回马枪”或译“用枪的后端”。"]},{"n":24,"t":"约押和亚比筛追赶押尼珥。日落的时候，他们到了通往基遍旷野的路旁，基亚对面的亚玛山。","notes":[]},{"n":25,"t":"便雅悯人聚集在押尼珥后面，成为一队，站在一座山顶上。","notes":[]},{"n":26,"t":"押尼珥呼叫约押说：“刀剑岂可永远吞噬呢？你岂不知，结局必是痛苦的吗？你要等到何时才叫百姓回去，不追赶他们的弟兄呢？”","notes":[]},{"n":27,"t":"约押说：“我指着永生的神起誓：你若没有这么说，百姓就必继续追赶弟兄，直到早晨。”","notes":["“你若没有这么说...早晨”或译“你若不曾那么说，百姓就不会从早晨起来追赶他们的弟兄了。”"]},{"n":28,"t":"于是约押吹角，众百姓就站住，不再追赶以色列人，也不再打仗了。","notes":[]},{"n":29,"t":"押尼珥和他的人整夜行过亚拉巴。他们过了约旦河，走过毕伦，到了玛哈念。","notes":["“走过毕伦”或译“走了一个上午”。"]},{"n":30,"t":"约押追赶押尼珥回来，聚集众百姓，大卫的仆人中缺少了十九个人和亚撒黑。","notes":[]},{"n":31,"t":"但大卫的仆人杀了押尼珥的人，便雅悯人三百六十名。","notes":[]},{"n":32,"t":"他们把亚撒黑送到伯利恒，葬在他父亲的坟墓里。约押和他的人走了一整夜，天亮的时候他们才到希伯仑。","notes":[]}]},"3":{"heading":"大卫的儿子","verses":[{"n":1,"t":"扫罗家和大卫家争战许久。大卫家日见强盛，扫罗家却日见衰弱。","notes":[]},{"n":2,"t":"大卫在希伯仑生了几个儿子：长子暗嫩是耶斯列人亚希暖所生的；","notes":[]},{"n":3,"t":"次子基利押是作过迦密人拿八的妻子亚比该所生的；三子押沙龙是基述王达买的女儿玛迦所生的；","notes":["“基利押”：代上3．1称“但以利”。"]},{"n":4,"t":"四子亚多尼雅是哈及所生的；五子示法提雅是亚比她所生的；","notes":[]},{"n":5,"t":"六子以特念是大卫的妻子以格拉所生的。大卫这六个儿子都是在希伯仑生的。","notes":[]},{"n":6,"t":"扫罗家和大卫家争战的时候，押尼珥在扫罗家大有权势。","notes":[],"heads":["押尼珥投效大卫"]},{"n":7,"t":"扫罗有一妃子，名叫利斯巴，是爱亚的女儿。一日，伊施．波设对押尼珥说：“你为什么与我父的妃子同寝呢？”","notes":[]},{"n":8,"t":"押尼珥因伊施．波设的话非常生气，说：“我岂是狗的头，向着犹大呢？我今日忠心对待你父扫罗的家和他的弟兄、朋友，不将你交在大卫手里，今日你竟为这妇人责备我吗？","notes":[]},{"n":9,"t":"愿神重重惩罚押尼珥！我要照着耶和华起誓应许大卫的话为他成就，","notes":[]},{"n":10,"t":"废去扫罗家的国度，建立大卫的王位，使他治理以色列和犹大，从但直到别是巴。”","notes":[]},{"n":11,"t":"伊施．波设惧怕押尼珥，一句话也不能回答。","notes":[]},{"n":12,"t":"押尼珥派使者到大卫所在的地方，说：“这地归谁呢？”又说：“你与我立约，看哪，我必帮助你，使全以色列都拥护你。”","notes":["“大卫所在的地方”：七十士译本是“希伯仑大卫那里”。"]},{"n":13,"t":"大卫说：“好！我与你立约。但有一件事我要求你，你来见我面的时候，除非把扫罗的女儿米甲带来，就不必来见我的面了。”","notes":[]},{"n":14,"t":"大卫派使者到扫罗的儿子伊施．波设那里，说：“你要把我的妻子米甲归还我；她是我从前用一百非利士人的包皮所聘定的。”","notes":[]},{"n":15,"t":"伊施．波设就派人去，把米甲从拉亿的儿子，她丈夫帕铁那里带来。","notes":["“帕铁”又名“帕提”；参撒上25．44。"]},{"n":16,"t":"米甲的丈夫跟着她，一面走一面哭，直跟到巴户琳。押尼珥对他说：“你回去吧！”帕铁就回去了。","notes":[]},{"n":17,"t":"押尼珥与以色列长老商议，说：“从前你们企盼大卫作王治理你们，","notes":[]},{"n":18,"t":"现在你们可以这样做了。因为耶和华曾论到大卫说：‘我必藉我仆人大卫的手，救我民以色列脱离非利士人和众仇敌的手。’”","notes":[]},{"n":19,"t":"押尼珥也说给便雅悯人听。押尼珥又到希伯仑，把以色列人和便雅悯全家所看为好的，说给大卫听。","notes":[]},{"n":20,"t":"押尼珥带着二十个人来到希伯仑大卫那里，大卫就为押尼珥和他带来的人摆设宴席。","notes":[]},{"n":21,"t":"押尼珥对大卫说：“我要起身去召集全以色列，来到我主我王这里，与你立约，你就可以照你的心愿作王，统治一切。”于是大卫送走押尼珥，他就平安地去了。","notes":[]},{"n":22,"t":"看哪，大卫的仆人和约押突击回来，带回许多掠物。那时押尼珥不在希伯仑大卫那里，因大卫已经送他走，他也平安地去了。","notes":[],"heads":["押尼珥被杀"]},{"n":23,"t":"约押和跟随他的全军到了，有人告诉约押说：“尼珥的儿子押尼珥来到王这里，王送走他，他也平安地去了。”","notes":[]},{"n":24,"t":"约押到王那里，说：“你这是做什么呢？看哪，押尼珥来到你这里，你为何送他走，让他去了呢？","notes":[]},{"n":25,"t":"你知道，尼珥的儿子押尼珥来，是要骗你，要打听你的出入，知道你一切所行的事。”","notes":[]},{"n":26,"t":"约押从大卫那里出来，派些使者去追押尼珥，从西拉井那里带他回来，大卫却不知道。","notes":[]},{"n":27,"t":"押尼珥回到希伯仑，约押领他到城门中间，要与他私下交谈，就在那里刺穿了他的肚腹。他就死了，因为他流了约押兄弟亚撒黑的血。","notes":[]},{"n":28,"t":"这事以后，大卫听见了，说：“流尼珥儿子押尼珥的血，我和我的国在耶和华面前永远是无辜的。","notes":[]},{"n":29,"t":"愿这血归到约押头上和他父的全家；又愿约押家不断有患漏症的，长麻风的，架柺杖而行的，仆倒在刀下的，缺乏食物的。”","notes":["“麻风”泛指传染性皮肤病。","“架柺杖而行的”是根据七十士译本；原文直译“把着纺车的”，意思是男人只能做当时女人做的工作。"]},{"n":30,"t":"约押和他弟弟亚比筛杀了押尼珥，是因为在基遍战争的时候，押尼珥杀了他们的弟弟亚撒黑。","notes":[]},{"n":31,"t":"大卫对约押和跟随他的众百姓说：“你们当撕裂衣服，腰束麻布，在押尼珥前面哀哭。”大卫王也跟在棺木后面。","notes":[],"heads":["安葬押尼珥"]},{"n":32,"t":"他们把押尼珥葬在希伯仑。王在押尼珥的墓旁放声大哭，众百姓也都哭了。","notes":[]},{"n":33,"t":"王为押尼珥举哀，说：押尼珥怎么会像愚顽人一样地死呢？","notes":[]},{"n":34,"t":"你手未曾被捆绑，脚未曾被脚镣锁住。你仆倒，如仆倒在凶恶之子手下一样。于是众百姓又为押尼珥哀哭。","notes":[]},{"n":35,"t":"白天的时候，众百姓来劝大卫吃饭，但大卫起誓说：“我若在太阳未下山以前吃饭，或吃任何东西，愿神重重惩罚我！”","notes":[]},{"n":36,"t":"众百姓知道了就看为好。凡王所做的，众百姓都看为好。","notes":[]},{"n":37,"t":"那日，以色列众百姓才知道杀尼珥的儿子押尼珥并非出于王意。","notes":[]},{"n":38,"t":"王对臣仆说：“你们岂不知今日在以色列中倒了一个作元帅的大人物吗？","notes":[]},{"n":39,"t":"我虽然受膏为王，今日还是软弱。洗鲁雅的两个儿子，这些人比我强硬。愿耶和华照着恶人所行的恶报应他。”","notes":[]}]},"4":{"heading":"伊施．波设被杀","verses":[{"n":1,"t":"扫罗的儿子伊施．波设听见押尼珥死在希伯仑，手就发软，全以色列也都惊惶。","notes":[]},{"n":2,"t":"扫罗的儿子伊施．波设有两个军官，一个叫巴拿，第二个叫利甲，都是便雅悯支派比录人临门的儿子；因为比录也算是属于便雅悯的。","notes":[]},{"n":3,"t":"比录人先前逃到基他音，在那里寄居，直到今日。","notes":[]},{"n":4,"t":"扫罗的儿子约拿单有一个儿子，名叫米非波设，是瘸腿的。扫罗和约拿单的消息从耶斯列传来的时候，他才五岁。他的奶妈抱着他逃跑；因为跑得太急，孩子掉在地上，腿就瘸了。","notes":["“米非波设”：代上8．34，9．40称“米力．巴力”；七十士译本的一些抄本是“米非巴力”；本卷书下同。"]},{"n":5,"t":"比录人临门的两个儿子利甲和巴拿出去，天正热的时候到了伊施．波设的家。那时，伊施．波设在睡午觉。","notes":[]},{"n":6,"t":"妇人进到房子中间，要取麦子。利甲和他的哥哥巴拿刺穿了伊施．波设的肚腹，然后逃跑了。","notes":["本节七十士译本是“看哪，看门的妇人清理麦子，累了就睡着了。利甲和巴拿两兄弟就溜进去。”"]},{"n":7,"t":"他们进到房子的时候，伊施．波设正躺在卧房的床上，他们就把他杀死，割了他的首级，拿着首级在亚拉巴的路上走了一整夜。","notes":[]},{"n":8,"t":"他们把伊施．波设的首级拿到希伯仑大卫那里，对王说：“王的仇敌扫罗曾寻索你的性命。看哪，这是他儿子伊施．波设的首级；耶和华今日为我主我王在扫罗和他后裔身上报了仇。”","notes":[]},{"n":9,"t":"大卫回答比录人临门的儿子利甲和他哥哥巴拿说：“我指着救我性命脱离一切苦难、永生的耶和华起誓：","notes":[]},{"n":10,"t":"从前有人告诉我说：‘看哪，扫罗死了。’他自以为报好消息，我就拿住他，把他杀在洗革拉，作为他报消息的赏赐。","notes":[]},{"n":11,"t":"更何况恶人把义人杀在他家的床上，我岂不从你们手中追讨他的血，从地上除灭你们吗？”","notes":[]},{"n":12,"t":"于是大卫吩咐仆人把他们杀了，砍断他们的手脚，挂在希伯仑的池旁。然后，他们把伊施．波设的首级葬在希伯仑押尼珥的坟墓里。","notes":[]}]},"5":{"heading":"大卫作全以色列的王","verses":[{"n":1,"t":"以色列众支派来到希伯仑见大卫，说：“看哪，我们是你的骨肉。","notes":[]},{"n":2,"t":"从前扫罗作我们王的时候，率领以色列人出入的是你。耶和华也曾对你说：‘你必牧养我的百姓以色列，你必作以色列的君王。’”","notes":[]},{"n":3,"t":"于是以色列的众长老都来到希伯仑见王 。大卫在希伯仑，在耶和华面前与他们立约，他们就膏大卫作以色列的王。","notes":[]},{"n":4,"t":"大卫登基的时候年三十岁，作王四十年。","notes":[]},{"n":5,"t":"他在希伯仑作犹大王七年六个月，在耶路撒冷作以色列和犹大王三十三年。","notes":[]},{"n":6,"t":"王和他的人到了耶路撒冷，要攻打住那地方的耶布斯人。耶布斯人对大卫说：“你必不能进到这里，就是盲人、瘸子都可以把你击退。”就是说：“大卫绝不能进到这里。”","notes":[]},{"n":7,"t":"然而大卫攻取了锡安的堡垒，就是大卫的城。","notes":[]},{"n":8,"t":"当日，大卫说：“谁攻打耶布斯人，就要从水道上去，攻打我心里所恨恶的瘸子、盲人。”因此有人说：“盲人和瘸子不得进殿里去。”","notes":["“我心里所恨恶的”：原文另译“那些恨恶大卫的”。"]},{"n":9,"t":"大卫住在堡垒里，给它起名叫大卫城。大卫又从米罗往内，周围建筑。","notes":["“米罗”是音译，指“土堆的防御工事”。"]},{"n":10,"t":"大卫日见强大，耶和华－万军之神与他同在。","notes":[]},{"n":11,"t":"推罗王希兰派使者把香柏木运到大卫那里，又派木匠和石匠给大卫建造宫殿。","notes":[]},{"n":12,"t":"大卫知道耶和华坚立他作以色列王，又为自己百姓以色列的缘故，使他的国兴盛。","notes":[]},{"n":13,"t":"大卫离开希伯仑之后，在耶路撒冷又立后妃，又生儿女。","notes":[]},{"n":14,"t":"在耶路撒冷所生的孩子的名字是沙母亚、朔罢、拿单、所罗门、","notes":[]},{"n":15,"t":"益辖、以利书亚、尼斐、雅非亚、","notes":[]},{"n":16,"t":"以利沙玛、以利雅大、以利法列。","notes":[]},{"n":17,"t":"非利士人听见大卫受膏作以色列王，非利士众人就上来寻索大卫。大卫听见了，就下到堡垒去。","notes":[],"heads":["战胜非利士人"]},{"n":18,"t":"非利士人来了，散布在利乏音谷。","notes":[]},{"n":19,"t":"大卫求问耶和华说：“我可以上去攻打非利士人吗？你将他们交在我手里吗？”耶和华对大卫说：“你可以上去，我必将非利士人交在你手里。”","notes":[]},{"n":20,"t":"大卫来到巴力．毗拉心，在那里击败了非利士人。他说：“耶和华在我面前冲破敌人，如水冲破一样。”因此他称那地方为巴力．毗拉心。","notes":[]},{"n":21,"t":"非利士人把偶像抛弃在那里，大卫和他的人拿去了。","notes":[]},{"n":22,"t":"非利士人又上来，散布在利乏音谷。","notes":[]},{"n":23,"t":"大卫求问耶和华；耶和华说：“不要直上，要绕到他们后头，从桑树林对面攻打他们。","notes":[]},{"n":24,"t":"你听见桑树梢上有脚步的声音，就要急速前去，因为那时耶和华已经出去，在你前头攻打非利士人的军队了。”","notes":[]},{"n":25,"t":"大卫就遵照耶和华所吩咐的去做，攻打非利士人，从迦巴直到基色。","notes":[]}]},"6":{"heading":"接约柜到耶路撒冷","verses":[{"n":1,"t":"大卫又聚集以色列中所有挑选的人，共三万名。","notes":[]},{"n":2,"t":"大卫起身，和跟随他的众百姓前往，要从巴拉．犹大那里将神的约柜接上来；这约柜是以坐在二基路伯上万军之耶和华的名所命名的。","notes":[]},{"n":3,"t":"他们将神的约柜从山冈上亚比拿达的家里抬出来，放在新车上；亚比拿达的儿子乌撒和亚希约赶这新车。","notes":[]},{"n":4,"t":"他们将神的约柜从山冈上亚比拿达家里抬出来，亚希约在约柜前行走。","notes":["“赶这新车...抬出来”：七十士译本是“赶这新车，神的约柜在上面”。"]},{"n":5,"t":"大卫和以色列全家在耶和华面前，随着松木制造的各样乐器和琴、瑟、鼓、钹、锣跳舞。","notes":["“随着松木制造的各样乐器”：死海古卷一份抄本和七十士译本是“竭尽力量，随着诗歌”；参代上13．8。"]},{"n":6,"t":"到了拿艮的禾场，因为牛失前蹄 ，乌撒就伸手扶住神的约柜。","notes":["“拿艮”：代上13．9是“基顿”。","“失前蹄”或译“惊跳”。"]},{"n":7,"t":"耶和华的怒气向乌撒发作；神因这冒犯在那里击打他，他就死在那里，在神的约柜旁。","notes":[]},{"n":8,"t":"大卫因耶和华突然冲出撞死乌撒就生气，称那地方为毗列斯．乌撒，直到今日。","notes":[]},{"n":9,"t":"那日，大卫惧怕耶和华，说：“耶和华的约柜怎可到我这里来呢？”","notes":[]},{"n":10,"t":"于是大卫不愿将耶和华的约柜接进大卫城他自己的地方，却转送到迦特人俄别．以东的家中。","notes":[]},{"n":11,"t":"耶和华的约柜停在迦特人俄别．以东家中三个月，耶和华赐福给俄别．以东和他的全家。","notes":[]},{"n":12,"t":"有人告诉大卫王说：“耶和华因约柜的缘故赐福给俄别．以东的家和一切属他的。”大卫就去，欢欢喜喜地将神的约柜从俄别．以东家中接上来，到大卫城里。","notes":[]},{"n":13,"t":"抬耶和华约柜的人走了六步，大卫就献牛与肥畜为祭。","notes":[]},{"n":14,"t":"大卫穿着细麻布以弗得，在耶和华面前极力跳舞。","notes":[]},{"n":15,"t":"这样，大卫和以色列全家欢呼吹角，将耶和华的约柜接了上来。","notes":[]},{"n":16,"t":"耶和华的约柜进大卫城的时候，扫罗的女儿米甲从窗户里往外观看，见大卫王在耶和华面前踊跃跳舞，心里就轻视他。","notes":[]},{"n":17,"t":"众人将耶和华的约柜请进去，安放在所预备的地方，就是大卫为它搭的帐幕中。大卫在耶和华面前献燔祭和平安祭。","notes":[]},{"n":18,"t":"大卫献完了燔祭和平安祭，就奉万军之耶和华的名祝福百姓，","notes":[]},{"n":19,"t":"并且分给以色列众人，所有的百姓，无论男女，每人一个饼，一个枣子饼，一个葡萄饼。众人就各自回家去了。","notes":["“一个枣子饼”：有古译本是“一块肉”。"]},{"n":20,"t":"大卫回去要为家里的人祝福，扫罗的女儿米甲出来迎接他，说：“以色列王今日有好大的荣耀啊！他今日在臣仆的使女眼前露体，如同一个无赖赤身露体一样。”","notes":[]},{"n":21,"t":"大卫对米甲说：“这是在耶和华面前的。耶和华已拣选我，在你父和你父的全家之上，立我作耶和华百姓以色列的君王，所以我在耶和华面前跳舞，","notes":[]},{"n":22,"t":"我也必更加卑微，自己看为低贱。至于你所说的那些使女，她们反而尊重我。”","notes":["“自己看为低贱”：七十士译本是“被你看为低贱”。"]},{"n":23,"t":"扫罗的女儿米甲，直到死的那日没有孩子。","notes":[]}]},"7":{"heading":"拿单传信息给大卫","verses":[{"n":1,"t":"王住在自己宫中，耶和华使他平静，不被四围的仇敌扰乱。","notes":[]},{"n":2,"t":"王对拿单先知说：“你看，我住在香柏木的宫中，神的约柜却停在幔子里。”","notes":[]},{"n":3,"t":"拿单对王说：“你可以完全照你的心意去做，因为耶和华与你同在。”","notes":[]},{"n":4,"t":"当夜耶和华的话临到拿单，说：","notes":[]},{"n":5,"t":"“你去对我仆人大卫说：‘耶和华如此说：你要建造殿宇给我居住吗？","notes":[]},{"n":6,"t":"自从我领以色列人从埃及上来，直到今日，我未曾住过殿宇，却在会幕和帐幕中行走。","notes":[]},{"n":7,"t":"凡我同以色列人所走的地方，我何曾向以色列任何一个领袖，就是我吩咐牧养我百姓以色列的，说过这话：你们为何不给我建造香柏木的殿宇呢？’","notes":["“领袖”：原文是“支派”。"]},{"n":8,"t":"现在，你要对我仆人大卫这样说：‘万军之耶和华如此说：我从羊圈中将你召来，叫你不再牧放羊群，立你作我百姓以色列的君王。","notes":[]},{"n":9,"t":"你无论往哪里去，我都与你同在，剪除你所有的仇敌。我必使你得大名，好像世上伟人的名一样。","notes":[]},{"n":10,"t":"我必为我百姓以色列选定一个地方，栽植他们，使他们住自己的地方，不再受搅扰；凶恶之子也不像从前那样苦待他们，","notes":[]},{"n":11,"t":"并不像我命令士师治理我百姓以色列的日子。我必使你平静，不受任何仇敌搅扰，并且耶和华应许你，耶和华必为你建立家室。","notes":[]},{"n":12,"t":"当你寿数满足、与你祖先同睡的时候，我必使你身所生的后裔接续你；我也必坚定他的国。","notes":[]},{"n":13,"t":"他必为我的名建造殿宇，我必坚定他国度的王位，直到永远。","notes":[]},{"n":14,"t":"我要作他的父，他要作我的子；他若犯了罪，我必用人的杖，用世人的鞭责罚他。","notes":[]},{"n":15,"t":"但我的慈爱仍不离开他，像离开在你面前所废的扫罗一样。","notes":[]},{"n":16,"t":"你的家和你的国必在你面前永远坚立，你的王位也必坚定，直到永远。’”","notes":["“你”：有古卷和七十士译本是“我”。"]},{"n":17,"t":"拿单就按这一切话，照这一切异象告诉大卫。","notes":[]},{"n":18,"t":"于是大卫王进去，坐在耶和华面前，说：“主耶和华啊，我是谁，我的家算什么，你竟带领我到这地步呢？","notes":[],"heads":["大卫的祈祷和感恩"]},{"n":19,"t":"主耶和华啊，这在你眼中还看为小，你又说到你仆人的家将来的情况。主耶和华啊，这岂是人的常理吗？","notes":[]},{"n":20,"t":"大卫还有什么可以对你说呢？主耶和华啊，你是知道你仆人的。","notes":[]},{"n":21,"t":"你行这一切大事，使你的仆人明白，是因你应许的缘故，也照着你的心意。","notes":[]},{"n":22,"t":"因此，主耶和华啊，你本为大；照我们耳中一切所听见的，没有可比你的，除你以外再没有神。","notes":[]},{"n":23,"t":"谁像你的百姓以色列呢？神亲自去救赎世上的一国，作自己的子民，显出他的大名；为了你的地，从列国和他们的神明中，在你亲自从埃及赎出来的子民面前，为自己行了大而可畏的事。","notes":["“谁像<ins>.一国”：七十士译本是“世上有何国能比你的百姓以色列呢？神亲自去救赎”。","“为了你的地</ins>.大而可畏的事”：七十士译本是“在你亲自从埃及赎出来的子民面前，为自己行了大而可畏的事，驱逐了列国和他们的神明”。"]},{"n":24,"t":"你曾坚立你的百姓以色列作你的子民，直到永远；你－耶和华也作他们的神。","notes":[]},{"n":25,"t":"现在，耶和华神啊，你所应许仆人和仆人家的话，求你坚定，直到永远；求你照你所说的而行。","notes":[]},{"n":26,"t":"愿人永远尊你的名为大，说：‘万军之耶和华是治理以色列的神。’这样，你仆人大卫的家必在你面前坚立。","notes":[]},{"n":27,"t":"万军之耶和华－以色列的神啊，因你启示你的仆人说：‘我必为你建立家室’，所以仆人大胆向你如此祈祷。","notes":[]},{"n":28,"t":"现在，主耶和华啊，惟有你是神！你的话是真实的，你也应许将这福气赐给仆人。","notes":[]},{"n":29,"t":"现在，求你赐福给你仆人的家，可以永存在你面前。主耶和华啊，因为这是你所应许的。愿你的福分永远赐给你仆人的家，使之蒙福！”","notes":[]}]},"8":{"heading":"耶和华使大卫得胜","verses":[{"n":1,"t":"此后，大卫攻打非利士人，制伏了他们。大卫从非利士人手中夺取了京城的治理权。","notes":["“京城的治理权”：原文音译“米特．雅玛”，意思是“母城的嚼环”。"]},{"n":2,"t":"他又攻打摩押人，使他们躺卧在地上，用绳来量，量二绳的杀了，量一绳的活着。摩押人就臣服大卫，向他进贡。","notes":[]},{"n":3,"t":"利合的儿子琐巴王哈大底谢往幼发拉底河去，要夺回他的国权，大卫就攻打他，","notes":[]},{"n":4,"t":"俘掳了他的骑兵一千七百人，步兵二万人。大卫把所有战马的蹄筋砍断，只留下一百辆战车。","notes":[]},{"n":5,"t":"大马士革的亚兰人来帮助琐巴王哈大底谢，大卫杀了亚兰人二万二千。","notes":[]},{"n":6,"t":"于是大卫在大马士革的亚兰设立军营，亚兰人就臣服大卫，向他进贡。大卫无论往哪里去，耶和华都使他得胜。","notes":[]},{"n":7,"t":"大卫夺了哈大底谢臣仆拥有的金盾牌，带到耶路撒冷。","notes":[]},{"n":8,"t":"大卫王又从哈大底谢的比他和比罗他二城夺取了许多的铜。","notes":[]},{"n":9,"t":"哈马王陀以听见大卫击败哈大底谢的全军，","notes":[]},{"n":10,"t":"就派他儿子约兰到大卫王那里，向他请安，为他祝福，因他与哈大底谢争战，并且击败了他；原来哈大底谢与陀以常常争战。约兰手里带了金银铜的器皿来。","notes":["“约兰”：有古卷是“哈多兰”；参代上18．10。"]},{"n":11,"t":"大卫王把这些器皿分别为圣，连同他制伏各国所分别为圣的金银，献给耶和华，","notes":[]},{"n":12,"t":"就是从亚兰、摩押、亚扪人、非利士人、亚玛力人，以及从利合的儿子琐巴王哈大底谢所掠之物。","notes":["“亚兰”：有古卷、七十士译本和其他古译本是“以东”。"]},{"n":13,"t":"大卫得了名声。当他回来的时候，在盐谷击杀了一万八千以东人。","notes":["“以东”是根据七十士译本；原文是“亚兰”。"]},{"n":14,"t":"大卫在以东设立军营；他在全以东设立军营，以东人就都臣服他。大卫无论往哪里去，耶和华都使他得胜。","notes":[]},{"n":15,"t":"大卫作全以色列的王，又向众百姓秉公行义。","notes":[]},{"n":16,"t":"洗鲁雅的儿子约押作元帅；亚希律的儿子约沙法作史官；","notes":[]},{"n":17,"t":"亚希突的儿子撒督和亚比亚他的儿子亚希米勒作祭司；西莱雅作书记；","notes":[]},{"n":18,"t":"耶何耶大的儿子比拿雅管辖基利提人和比利提人。大卫的众子都作祭司。","notes":["“管辖”是根据有些古卷和古译本；参代上18．17；原文没有。"]}]},"9":{"heading":"大卫和米非波设","verses":[{"n":1,"t":"大卫说：“扫罗家还有剩下的人没有？我要因约拿单的缘故向他施恩。”","notes":[]},{"n":2,"t":"扫罗家有一个仆人名叫洗巴，有人叫他来到大卫那里。王对他说：“你是洗巴吗？”他说：“仆人是。”","notes":[]},{"n":3,"t":"王说：“扫罗家还有没有剩下的人？我要照神的慈爱恩待他。”洗巴对王说：“还有约拿单的一个儿子，双腿是瘸的。”","notes":[]},{"n":4,"t":"王对他说：“他在哪里？”洗巴对王说：“看哪，他在罗．底巴，亚米利的儿子玛吉家里。”","notes":[]},{"n":5,"t":"于是大卫王派人去，从罗．底巴，亚米利的儿子玛吉家里召了他来。","notes":[]},{"n":6,"t":"扫罗的孙子，约拿单的儿子米非波设来到大卫那里，脸伏于地叩拜。大卫说：“米非波设！”米非波设说：“看哪，仆人在此。”","notes":[]},{"n":7,"t":"大卫对他说：“你不要惧怕，我必因你父亲约拿单的缘故向你施恩，把你祖父扫罗的一切田地都归还你，你也可以常与我同席吃饭。”","notes":[]},{"n":8,"t":"米非波设叩拜，说：“你的仆人算什么，不过如死狗一般，竟蒙你这样眷顾！”","notes":[]},{"n":9,"t":"王召了扫罗的仆人洗巴来，对他说：“我已把属扫罗和他的一切家产都赐给你主人的儿子了。","notes":[]},{"n":10,"t":"你、你的众子和仆人要为你主人的儿子耕种田地，把所收获的拿来供他食用；你主人的儿子米非波设却要常与我同席吃饭。”洗巴有十五个儿子和二十个仆人。","notes":[]},{"n":11,"t":"洗巴对王说：“凡我主我王吩咐仆人的，仆人都必遵行。”于是米非波设与王同席吃饭，如王的儿子一样。","notes":["“王”：原文是“我”。"]},{"n":12,"t":"米非波设有一个小儿子，名叫米迦。凡住在洗巴家里的人都作了米非波设的仆人。","notes":[]},{"n":13,"t":"米非波设住在耶路撒冷，常与王同席吃饭。他两腿都是瘸的。","notes":[]}]},"10":{"heading":"击败亚扪人和亚兰人","verses":[{"n":1,"t":"此后，亚扪人的王死了，他儿子哈嫩接续他作王。","notes":[]},{"n":2,"t":"大卫说：“哈嫩的父亲拿辖怎样向我施恩，我也要怎样向哈嫩施恩。”于是大卫派臣仆为他的父亲安慰他。当大卫的臣仆到了亚扪人的境内，","notes":[]},{"n":3,"t":"亚扪人的领袖对他们的主哈嫩说：“大卫派人来安慰你，你看他是要尊敬你父亲吗？大卫派臣仆到你这里，不是为了要窥探侦察，而倾覆这城吗？”","notes":[]},{"n":4,"t":"哈嫩就抓住大卫的臣仆，把他们的胡须剃去一半，又割断他们下半截的袍子，露出下体，然后放了他们。","notes":[]},{"n":5,"t":"有人告诉大卫，他就派人去迎接他们，因为这些人觉得很羞耻。王说：“可以住在耶利哥，等到胡须长出来再回来。”","notes":[]},{"n":6,"t":"亚扪人看到大卫憎恶他们，就派人去雇用伯．利合的亚兰人和琐巴的亚兰人，步兵二万，以及玛迦王的人一千、陀伯人一万二千。","notes":[]},{"n":7,"t":"大卫听见了，就派约押和所有勇猛的军队出去。","notes":[]},{"n":8,"t":"亚扪人出来，在城门前摆阵；琐巴与利合的亚兰人、陀伯人，以及玛迦人另外在郊野摆阵。","notes":[]},{"n":9,"t":"约押看见战阵对着他前后摆列，就把从以色列所有精兵中挑选出来的，摆阵迎战亚兰人。","notes":[]},{"n":10,"t":"他把其余的兵交在他兄弟亚比筛手里，亚比筛就摆阵迎战亚扪人。","notes":[]},{"n":11,"t":"约押对亚比筛说：“亚兰人若强过我，你就来帮助我；亚扪人若强过你，我就去帮助你。","notes":[]},{"n":12,"t":"你要刚强，我们要为自己的百姓，为我们神的城镇奋勇。愿耶和华照他所看为好的去做！”","notes":[]},{"n":13,"t":"于是，约押和跟随他的士兵前进攻打亚兰人；亚兰人在他面前逃跑。","notes":[]},{"n":14,"t":"亚扪人见亚兰人逃跑，他们也在亚比筛面前逃跑进城。约押就离开亚扪人，回耶路撒冷去了。","notes":[]},{"n":15,"t":"亚兰人见自己被以色列打败，就集合起来。","notes":[]},{"n":16,"t":"哈大底谢派人去，把大河那边的亚兰人调来；他们到了希兰，由哈大底谢的将军朔法在他们前面率领。","notes":[]},{"n":17,"t":"有人告诉大卫，他就聚集以色列众人过约旦河，来到希兰。亚兰人迎着大卫摆阵，与他打仗。","notes":[]},{"n":18,"t":"亚兰人在以色列人面前逃跑。大卫杀了亚兰七百辆战车的士兵，四万骑兵，又击杀亚兰的将军朔法，他就死在那里。","notes":["“骑兵”：七十士译本的一些抄本是“步兵”；参代上19．18。"]},{"n":19,"t":"哈大底谢属下的诸王见自己被以色列打败，就与以色列讲和，臣服他们。于是亚兰人害怕，不再帮助亚扪人了。","notes":[]}]},"11":{"heading":"大卫和拔示巴","verses":[{"n":1,"t":"过了一年，正是诸王出战的时候，大卫派约押率领臣仆和以色列众人出去。他们打败亚扪人，围攻拉巴。大卫仍然留在耶路撒冷。","notes":[]},{"n":2,"t":"黄昏的时候，大卫从床上起来，在王宫的平顶上散步。他从平顶上看见一个妇人沐浴，这妇人容貌非常美丽。","notes":[]},{"n":3,"t":"大卫派人打听那妇人是谁。有人说：“她不是以连的女儿，赫人乌利亚的妻子拔示巴吗？”","notes":[]},{"n":4,"t":"大卫派使者去把妇人接来；她来到大卫那里，那时她的月经刚洁净，大卫与她同寝。她就回家去了。","notes":[]},{"n":5,"t":"那妇人怀了孕，派人去告诉大卫说：“我怀孕了。”","notes":[]},{"n":6,"t":"大卫派人告诉约押：“你派赫人乌利亚到我这里来。”约押就派乌利亚到大卫那里。","notes":[]},{"n":7,"t":"乌利亚来到大卫那里，大卫问约押好，也问士兵好，又问战争的情况。","notes":[]},{"n":8,"t":"大卫对乌利亚说：“下到你家去，洗洗脚吧！”乌利亚出了王宫，随后王送他一份礼物。","notes":[]},{"n":9,"t":"乌利亚却和他主人所有的仆人一同睡在王宫门口，没有下到他家去。","notes":[]},{"n":10,"t":"有人告诉大卫说：“乌利亚没有下到他的家。”大卫就对乌利亚说：“你不是从远路上来吗？为什么不下到你家去呢？”","notes":[]},{"n":11,"t":"乌利亚对大卫说：“约柜，以色列和犹大都留在棚里，我主约押和我主的仆人都在田野安营，我岂可回家吃喝，与妻子同房呢？我指着王和王的性命起誓：‘我绝不做这事！’”","notes":[]},{"n":12,"t":"大卫对乌利亚说：“你今日仍留在这里，明日我打发你去。”于是乌利亚那日留在耶路撒冷。次日，","notes":[]},{"n":13,"t":"大卫召了乌利亚来，叫他在自己面前吃喝，使他喝醉。黄昏的时候，乌利亚出去，躺卧在自己的床上；与他主的仆人在一起，并没有下到他的家去。","notes":[]},{"n":14,"t":"早晨，大卫写信给约押，交乌利亚亲手带去。","notes":[],"heads":["大卫谋杀乌利亚"]},{"n":15,"t":"他在信内写着说：“要派乌利亚到战争激烈的前线去，然后你们撤退离开他，使他被击杀而死。”","notes":[]},{"n":16,"t":"约押侦察城的时候，知道敌人哪里有勇士，就派乌利亚到那地方。","notes":[]},{"n":17,"t":"城里的人出来和约押打仗，大卫的仆人中有几个士兵被杀，赫人乌利亚也死了。","notes":[]},{"n":18,"t":"于是，约押派人去将战争的一切事奏告大卫，","notes":[]},{"n":19,"t":"又吩咐使者说：“你把战争的一切事对王说完了，","notes":[]},{"n":20,"t":"王若发怒，对你说：‘你们打仗为什么挨近城呢？岂不知敌人会从城墙上射箭吗？","notes":[]},{"n":21,"t":"从前击杀耶路比设的儿子亚比米勒的是谁呢？岂不是一个妇人从城墙上抛下一块上磨石来，打在他身上，他就死在提备斯吗？你们为什么挨近城墙呢？’你就说：‘你的仆人赫人乌利亚也死了。’”","notes":["“耶路比设”：七十士译本是“耶路巴力”；参士9．1；撒上12．11。"]},{"n":22,"t":"使者就去，照着约押所吩咐的一切话来奏告大卫。","notes":["七十士译本在此加：“大卫对约押发怒，对使者说：‘你们打仗为什么挨近城呢？岂不知你们会从城墙受到伤害吗？从前击杀耶路巴力的儿子亚比米勒的是谁呢？岂不是一个妇人从城墙上抛下一块上磨石来，打在他身上，他就死在提备斯吗？你们为什么挨近城墙呢？’”"]},{"n":23,"t":"使者对大卫说：“敌人强过我们，出到郊外攻打我们，我们把他们赶回到城门口。","notes":[]},{"n":24,"t":"弓箭手从城墙上射你的仆人，射死几个王的仆人，你的仆人赫人乌利亚也死了。”","notes":[]},{"n":25,"t":"大卫向使者说：“你对约押这样说：‘不要为这事难过，因为刀剑可能吞灭这人或那人。你只管竭力攻城，将城倾覆。’你要勉励约押。”","notes":[]},{"n":26,"t":"乌利亚的妻听见丈夫乌利亚死了，就为丈夫哀哭。","notes":[]},{"n":27,"t":"居丧的日子过了，大卫派人把她接到宫里，她就作了大卫的妻子，给大卫生了一个儿子。但大卫做的这事，耶和华的眼中看为恶。","notes":[]}]},"12":{"heading":"拿单的信息和大卫的悔改","verses":[{"n":1,"t":"耶和华差遣拿单到大卫那里。拿单到了他那里，对他说：“在一座城里有两个人，一个是富翁，一个是穷人。","notes":[]},{"n":2,"t":"富翁有极多的牛群羊群；","notes":[]},{"n":3,"t":"穷人除了所买来养活的一只小母羊之外，一无所有。小羊在他家里和他儿女一同长大，吃他所吃的，喝他所喝的，睡在他怀中，在他看来如同女儿一样。","notes":[]},{"n":4,"t":"有一客人来到这富翁那里，富翁舍不得从自己的牛群羊群中取一只招待来到他那里的旅客，却取了穷人的小母羊，招待来到他那里的人。”","notes":[]},{"n":5,"t":"大卫就非常恼怒那人，对拿单说：“我指着永生的耶和华起誓，做这事的人该死！","notes":[]},{"n":6,"t":"他必须偿还小母羊四倍，因为他做这事，没有怜悯的心。”","notes":[]},{"n":7,"t":"拿单对大卫说：“你就是那人！耶和华－以色列的神如此说：‘我膏你作以色列的王，我救你脱离扫罗的手；","notes":[]},{"n":8,"t":"我将你主人的家业赐给你，将你主人的妃嫔交在你怀里，又将以色列和犹大家赐给你；若还嫌少，我也会如此这般加倍赐给你。","notes":[]},{"n":9,"t":"你为什么藐视耶和华的命令，做他眼中看为恶的事呢？你用刀击杀赫人乌利亚，又娶了他的妻子为妻，借亚扪人的刀杀死他。","notes":[]},{"n":10,"t":"现在刀剑必永不离开你的家，因你藐视我，娶了赫人乌利亚的妻子为妻。’","notes":[]},{"n":11,"t":"耶和华如此说：‘看哪，我必从你家中兴起灾祸攻击你；我必在你眼前把你的妃嫔赐给你身边的人，他要在光天化日下与你的妃嫔同寝。","notes":[]},{"n":12,"t":"你在暗中做那事，我却要在以色列众人面前，在日光之下做这事。’”","notes":[]},{"n":13,"t":"大卫对拿单说：“我得罪耶和华了！”拿单说：“耶和华已经除去你的罪，你必不至于死。","notes":[]},{"n":14,"t":"只是在这事上，你大大藐视耶和华，因此，你生的孩子必定要死。”","notes":["“耶和华”：原文是“耶和华的仇敌”；此句可能指“叫耶和华的仇敌大得亵渎的机会”。"]},{"n":15,"t":"拿单就回家去了。耶和华击打乌利亚的妻子为大卫生的孩子，他就得了重病。","notes":[]},{"n":16,"t":"大卫为这孩子恳求神。大卫刻苦禁食，到里面去，躺在地上过夜。","notes":[]},{"n":17,"t":"他家中的老臣来到他旁边，要把他从地上扶起来，他却不肯，也不同他们吃饭。","notes":[]},{"n":18,"t":"到第七日，孩子死了。大卫的臣仆不敢告诉他孩子死了，因他们说：“看哪，孩子还活着的时候，我们劝他，他尚且不听我们的话，我们怎么能告诉他孩子死了，让他做出不好的事呢？”","notes":[]},{"n":19,"t":"大卫见臣仆彼此低声说话，就知道孩子死了。他问臣仆说：“孩子死了吗？”他们说：“死了。”","notes":[]},{"n":20,"t":"大卫就从地上起来，沐浴，抹膏，换了衣服，进耶和华的殿敬拜。然后他回宫，吩咐人为他摆饭，他就吃了。","notes":[]},{"n":21,"t":"臣仆对他说：“你所做的是什么事呢？孩子活着的时候，你为他禁食哭泣；孩子死了，你却起来吃饭。”","notes":[]},{"n":22,"t":"大卫说：“孩子还活着，我禁食哭泣，因为我想，或许耶和华怜悯我，会让孩子活下来。","notes":[]},{"n":23,"t":"现在孩子死了，我何必禁食呢？我能使他回来吗？我必往他那里去，他却不能回到我这里来。”","notes":[]},{"n":24,"t":"大卫安慰他的妻子拔示巴，与她同房，她就生了儿子，给他起名叫所罗门。耶和华喜爱他，","notes":[],"heads":["所罗门出生"]},{"n":25,"t":"就藉拿单先知赐他一个名字，叫耶底底亚；这是为了耶和华的缘故。","notes":["“耶底底亚”意思是“耶和华所爱的”。"]},{"n":26,"t":"约押攻打亚扪人的拉巴，攻占了京城。","notes":[],"heads":["大卫攻取拉巴"]},{"n":27,"t":"约押派使者到大卫那里，说：“我攻打拉巴， 也攻占了水城。","notes":[]},{"n":28,"t":"现在你要召集其余的军兵，安营围攻这城，攻占它，免得我攻占这城，人就以我的名叫这城。”","notes":[]},{"n":29,"t":"于是大卫召集全军，往拉巴去攻城，就攻占了它。","notes":[]},{"n":30,"t":"他也夺了米勒公头上所戴的冠冕，其上的金子重一他连得，又嵌着宝石。这冠冕就戴在大卫头上。大卫又从城里夺了许多财物，","notes":["“米勒公”是根据七十士译本和其他古译本，亚扪人神明的名字，又名“摩洛”；原文是“他们的王”，音译“玛勒堪”。"]},{"n":31,"t":"把城里的百姓拉出来，叫他们用锯，用铁耙，用铁斧做工，派他们在砖窑中服役；大卫待亚扪各城的居民都是如此。于是，大卫和全军都回耶路撒冷去了。","notes":[]}]},"13":{"heading":"暗嫩和她玛","verses":[{"n":1,"t":"后来发生了一件事。大卫的儿子押沙龙有一个美貌的妹妹，名叫她玛。大卫的儿子暗嫩爱上了她。","notes":[]},{"n":2,"t":"暗嫩为他妹妹她玛苦恋成疾，因为她玛还是处女，暗嫩眼看难以向她行事。","notes":[]},{"n":3,"t":"暗嫩有一个密友，名叫约拿达，是大卫长兄示米亚的儿子。这约拿达为人极其狡猾。","notes":[]},{"n":4,"t":"他对暗嫩说：“王的儿子啊，你何不告诉我，为何你一天比一天憔悴呢？”暗嫩对他说：“我爱上了我兄弟押沙龙的妹妹她玛。”","notes":[]},{"n":5,"t":"约拿达对他说：“你躺在床上装病，等你父亲来看你，就对他说：‘请让我妹妹她玛来，给我东西吃，在我眼前预备食物，使我可以看见，好从她手里接过来吃。’”","notes":[]},{"n":6,"t":"于是暗嫩躺着装病，王来看他。暗嫩对王说：“请让我妹妹她玛来，在我眼前为我做两个饼，我好从她手里接过来吃。”","notes":[]},{"n":7,"t":"大卫就派人去宫里，到她玛那里，说：“你到你哥哥暗嫩的屋里去，为他预备食物。”","notes":[]},{"n":8,"t":"她玛就到她哥哥暗嫩的屋里，那时暗嫩正躺着。她玛拿了面团揉面，在他眼前做饼，把饼烤熟了。","notes":[]},{"n":9,"t":"她玛拿了锅子，在他面前把饼倒出来，他却不肯吃。暗嫩说：“每一个人都离开我，出去吧！”众人就都离开他，出去了。","notes":[]},{"n":10,"t":"暗嫩对她玛说：“你把食物拿进卧房，我好从你手里接过来吃。”她玛就把所做的饼拿进卧房，到她哥哥暗嫩那里。","notes":[]},{"n":11,"t":"她玛上前去给他吃，他就拉住她玛，对她说：“我妹妹，你来与我同寝。”","notes":[]},{"n":12,"t":"她玛对他说：“哥哥，不可以！不要玷辱我！以色列中不可以这样做，你不要做这丑事！","notes":[]},{"n":13,"t":"我蒙受耻辱，该往那里去呢？至于你，你在以色列中也成了一个愚顽人。现在你可以求王，他必不禁止我归你。”","notes":[]},{"n":14,"t":"但暗嫩不肯听她的话，因他比她更有力，就玷辱她，与她同寝。","notes":[]},{"n":15,"t":"随后，暗嫩极其恨她，恨她的心比先前爱她的心更甚，就对她说：“你起来，去吧！”","notes":[]},{"n":16,"t":"她玛对暗嫩说：“不要这样！你赶我出去的这恶比你刚才向我所做的更严重！”但暗嫩不肯听她，","notes":[]},{"n":17,"t":"就叫伺候自己的仆人来，说：“把这女子从我这里赶出去！她一出去，你就闩上门。”","notes":[]},{"n":18,"t":"那时她玛穿着彩衣，因为没有出嫁的公主都穿这样的外袍。暗嫩的仆人把她赶出去，她一出去，仆人就闩上门。","notes":[]},{"n":19,"t":"她玛把灰尘撒在头上，撕裂所穿的彩衣，以手抱头，一面走一面哭喊。","notes":[]},{"n":20,"t":"她胞兄押沙龙对她说：“你哥哥暗嫩与你亲近了吗？妹妹，现在暂且不要作声，他是你的哥哥，不要把这事放在心上。”她玛就孤孤单单地住在她胞兄押沙龙的家里。","notes":[]},{"n":21,"t":"大卫王听见这一切的事，就非常愤怒。","notes":["七十士译本在此加：“但他没有为他儿子暗嫩的灵而忧愁，因为暗嫩是他所宠爱的长子。”"]},{"n":22,"t":"押沙龙却不和暗嫩说好说歹；因为暗嫩玷辱他妹妹她玛，所以押沙龙恨恶他。","notes":[]},{"n":23,"t":"过了二年，有人在靠近以法莲的巴力．夏琐为押沙龙剪羊毛。押沙龙请了王所有的儿子来。","notes":[],"heads":["押沙龙为妹报仇"]},{"n":24,"t":"押沙龙来到王那里，说：“看哪，有人正为你的仆人剪羊毛，请王和王的臣仆与你的仆人同去。”","notes":[]},{"n":25,"t":"王对押沙龙说：“不，我儿，我们不必都去，免得成了你的负担。”押沙龙再三请王，王仍是不肯去，只为他祝福。","notes":[]},{"n":26,"t":"押沙龙说：“王若不去，请让我哥哥暗嫩与我们同去。”王对他说：“为何要他与你同去呢？”","notes":[]},{"n":27,"t":"押沙龙再三求王，王就派暗嫩和王所有的儿子与他同去。","notes":[]},{"n":28,"t":"押沙龙吩咐仆人说：“你们注意， 暗嫩开怀畅饮的时候，我对你们说击杀暗嫩，你们就杀他。不要惧怕，这不是我吩咐你们的吗？你们要刚强，作勇士！”","notes":[]},{"n":29,"t":"押沙龙的仆人就照押沙龙所吩咐的，向暗嫩行了。王所有的儿子都起来，各人骑上骡子逃跑了。","notes":[]},{"n":30,"t":"他们还在路上，就有风声传到大卫那里，说：“押沙龙击杀了王所有的儿子，没有留下一个。”","notes":[]},{"n":31,"t":"王就起来，撕裂衣服，躺在地上。王的臣仆全都撕裂衣服，站在旁边。","notes":[]},{"n":32,"t":"大卫的长兄示米亚的儿子约拿达说：“我主，不要以为他们把所有的年轻人，就是王的儿子都杀了，只有暗嫩一个人死了。自从暗嫩玷辱了押沙龙的妹妹她玛那日，押沙龙已经决定这事了。","notes":[]},{"n":33,"t":"现在，我主我王，不要把这事放在心上，以为王所有的儿子都死了。其实，只有暗嫩一人死了。”","notes":[]},{"n":34,"t":"押沙龙逃跑了。守望的年轻人举目观看，看哪，有许多人从何罗念山坡的路上来。","notes":["“何罗念”是参照七十士译本；原文是“他后面”；“何罗念”在此指“上伯．和仑”和“下伯．和仑”。"]},{"n":35,"t":"约拿达对王说：“看哪，王的儿子都来了，正如你仆人所说的，事情就这样发生了。”","notes":[]},{"n":36,"t":"话刚说完，看哪，王的儿子都到了，放声大哭。王和他的众臣仆也都号啕痛哭。","notes":[]},{"n":37,"t":"押沙龙逃到亚米忽的儿子基述王达买那里去了。大卫天天为他儿子悲哀。","notes":[]},{"n":38,"t":"押沙龙逃到基述去了，在那里住了三年。","notes":[]},{"n":39,"t":"王想要出去对付押沙龙的心化解了，因为王对暗嫩之死这事已经得了安慰。","notes":["“王想要...化解了”是根据一些古卷、死海古卷和七十士译本；原文是“大卫王停止出去对付押沙龙”。"]}]},"14":{"heading":"约押设计让押沙龙返回","verses":[{"n":1,"t":"洗鲁雅的儿子约押知道王心里想念押沙龙。","notes":[]},{"n":2,"t":"他派人往提哥亚去，从那里叫了一个有智慧的妇人来，对她说：“请你装作居丧的人，穿上丧服，不用膏抹身，装作为死者悲哀多日的妇人。","notes":[]},{"n":3,"t":"你到王那里，对王如此如此说。”于是约押把当说的话放在她口中。","notes":[]},{"n":4,"t":"提哥亚妇人到王面前，脸伏于地叩拜，说：“王啊，求你拯救！”","notes":["“到王面前”：有古卷是“奏告王”。"]},{"n":5,"t":"王对她说：“你有什么事呢？”她说：“我实在是个寡妇，我丈夫死了。","notes":[]},{"n":6,"t":"婢女有两个儿子，二人在田间打架，没有人从中劝解，一个击杀另一个，把他打死了。","notes":[]},{"n":7,"t":"看哪，全家族都起来攻击婢女，说：‘把那打死兄弟的交出来，我们好处死他，为他所打死的兄弟偿命，灭绝那承受家业的。’这样，他们要把我剩下的炭火灭尽，不给我丈夫留名或留后在地面上。”","notes":[]},{"n":8,"t":"王对妇人说：“你回家去吧！我必为你下个命令。”","notes":[]},{"n":9,"t":"提哥亚妇人又对王说：“我主我王，愿这罪孽归我和我的父家，与王和王的位无关。”","notes":[]},{"n":10,"t":"王说：“有人说话难为你，你就带他到我这里来，他必不再搅扰你。”","notes":[]},{"n":11,"t":"妇人说：“愿王对耶和华－你的神发誓，不许报血仇的人施行毁灭，免得他们灭绝我的儿子。”王说：“我指着永生的耶和华起誓：你的儿子连一根头发也不致落在地上。”","notes":[]},{"n":12,"t":"妇人说：“求我主我王容许婢女再说一句话。”王说：“你说吧！”","notes":[]},{"n":13,"t":"妇人说：“王为何起意做这事，要害神的百姓呢？王不使那逃亡的人回来，王说这话就证实自己错了！","notes":[]},{"n":14,"t":"我们都必死，如同水泼在地上，不能收回。神不会让人不死，但仍设法使逃亡的人不致成为赶出、回不来的人。","notes":["“但仍设法”：七十士译本是“愿王设法”。"]},{"n":15,"t":"现在我来将这话告诉我主我王，是因百姓使我惧怕。婢女想：‘不如告诉王，或者王会成就使女所求的。","notes":[]},{"n":16,"t":"人要把我和我儿子从神的地业上一同除灭，王必应允救使女脱离他的手。’","notes":[]},{"n":17,"t":"婢女想：‘我主我王的话必安慰我’；因为我主我王能辨别是非，如同神的使者一样。惟愿耶和华－你的神与你同在！”","notes":[]},{"n":18,"t":"王回答妇人说：“我问你一句话，你一点也不可瞒我。”妇人说：“我主我王，请说。”","notes":[]},{"n":19,"t":"王说：“这一切莫非是约押的手指使你的吗？”妇人回答说：“我敢在我主我王面前起誓：我主我王所说的一切不偏左右，这是王的仆人约押吩咐我的，这一切话是他放在婢女口中的。","notes":[]},{"n":20,"t":"王的仆人约押做这事，为要扭转局面。我主的智慧却如神使者的智慧，能知地上一切的事。”","notes":[]},{"n":21,"t":"王对约押说：“看哪，我应允这事。你去，把那年轻人押沙龙带回来。”","notes":[]},{"n":22,"t":"约押脸伏于地叩拜，为王祝福，说：“王既应允仆人这件事，仆人今日知道在我主我王眼前蒙恩宠了。”","notes":[]},{"n":23,"t":"于是约押起身往基述去，把押沙龙带回耶路撒冷。","notes":[]},{"n":24,"t":"王说：“让他回自己的家去，不要来见我的面。”押沙龙就回自己的家去，没有见王的面。","notes":[]},{"n":25,"t":"全以色列中，无人像押沙龙那样俊美，得人称赞，从脚底到头顶毫无瑕疵。","notes":[],"heads":["大卫饶恕押沙龙"]},{"n":26,"t":"他的头发很重，每到年底剪发一次，所剪下来的，按王的秤称一称，重二百舍客勒。","notes":[]},{"n":27,"t":"押沙龙生了三个儿子，一个女儿。女儿名叫她玛，是个容貌美丽的女子。","notes":[]},{"n":28,"t":"押沙龙住在耶路撒冷，足足有二年没有见王的面。","notes":[]},{"n":29,"t":"押沙龙派人去叫约押来，要托他到王那里去，约押却不肯来。押沙龙第二次派人去叫他，他仍不肯来。","notes":[]},{"n":30,"t":"于是押沙龙对仆人说：“你们看，约押有一块田靠近我的田，其中有大麦，你们去放火把它烧了。”押沙龙的仆人就去放火烧了那田。","notes":["七十士译本在此加：“约押的仆人来到约押那里，衣服撕裂，说：‘押沙龙的仆人放火烧了你的田。’”"]},{"n":31,"t":"于是约押起来，到了押沙龙家里，对他说：“你的仆人为何放火烧我的田呢？”","notes":[]},{"n":32,"t":"押沙龙对约押说：“看哪，我派人去请你来，好托你到王那里去，说：‘我为何从基述回来呢？我仍在那里比较好。’现在让我去见王的面；我若有罪孽，就任凭王杀了我吧。”","notes":[]},{"n":33,"t":"于是约押到王那里，奏告王，王就叫押沙龙来。押沙龙到王那里，在王面前脸伏于地，王就亲吻押沙龙。","notes":[]}]},"15":{"heading":"押沙龙阴谋造反","verses":[{"n":1,"t":"此后，押沙龙为自己预备车马，又派五十人在他前头奔跑。","notes":[]},{"n":2,"t":"押沙龙常常早晨起来，站在城门的路旁，任何人有争讼要去求王判决，押沙龙就叫他过来，说：“你是哪一城的人？”他说：“仆人是以色列某支派的人。”","notes":[]},{"n":3,"t":"押沙龙就对他说：“看，你的案件合情合理，无奈王没有委派人听你申诉。”","notes":[]},{"n":4,"t":"押沙龙又说：“恨不得我作这地的审判官！凡有争讼的人可以到我这里来，我必秉公判断。”","notes":["“恨不得...审判官！”原文直译“谁能立我作这地的审判官呢？”"]},{"n":5,"t":"若有人近前来要拜押沙龙，押沙龙就伸手拉住他，亲吻他。","notes":[]},{"n":6,"t":"以色列中，凡到王那里求判决的，押沙龙都这么做。这样，押沙龙暗中赢得了以色列人的心。","notes":[]},{"n":7,"t":"过了四年，押沙龙对王说：“求你准我往希伯仑去，还我向耶和华所许的愿。","notes":["“四年”是根据一些抄本和古译本；原文是“四十年”；有古卷是“四十天”。"]},{"n":8,"t":"因为仆人住在亚兰的基述时，曾许愿说：‘耶和华若使我再回耶路撒冷，我必事奉他。’”","notes":["“我必事奉他”：七十士译本的一些抄本是“我必在希伯仑事奉他”。"]},{"n":9,"t":"王对他说：“你平安地去吧！”押沙龙就动身，往希伯仑去了。","notes":[]},{"n":10,"t":"押沙龙派密使走遍以色列各支派，说：“你们一听见角声就说：‘押沙龙在希伯仑作王了！’”","notes":[]},{"n":11,"t":"押沙龙在耶路撒冷请了二百人与他同去，都是诚心诚意去的，一点也不知道实情。","notes":[]},{"n":12,"t":"押沙龙献祭的时候，派人去把大卫的谋士，基罗人亚希多弗从他本城基罗请来。于是叛乱越发强大，因为随从押沙龙的百姓日渐增多。","notes":["“派人...请来”是根据七十士译本和死海古卷；原文是“委派大卫的谋士，来自基罗城的基罗人亚希多弗”。"]},{"n":13,"t":"报信的人来到大卫那里，说：“以色列人的心都归向押沙龙了！”","notes":[],"heads":["大卫逃离耶路撒冷"]},{"n":14,"t":"大卫就对耶路撒冷所有跟随他的臣仆说：“起来，我们逃吧！否则，我们来不及逃避押沙龙。要快点离开，免得他很快追上我们，加害于我们，用刀击杀城里的人。”","notes":[]},{"n":15,"t":"王的臣仆对王说：“我主我王所决定的一切，看哪，仆人都愿遵行。”","notes":[]},{"n":16,"t":"于是王出去了，他的全家都跟随他，但留下十个妃嫔看守宫殿。","notes":[]},{"n":17,"t":"王出去，众百姓都跟随他；到了最后一座屋子，他们就停下来。","notes":["“最后一座屋子”或译“伯．墨哈”。"]},{"n":18,"t":"王的众臣仆都在他旁边过去。基利提人、比利提人，和从迦特跟随王来的六百个迦特人，也都在王面前过去。","notes":[]},{"n":19,"t":"王对迦特人以太说：“你是外邦人，从你本地逃来的，为什么与我们同去呢？你回去留在新王那里吧！","notes":[]},{"n":20,"t":"你昨天才到，我今日怎好叫你与我们一同流亡，而我却要到处飘流呢？回去吧，你带你的弟兄回去吧！愿主用慈爱信实待你。”","notes":["“你带你的弟兄...待你”是根据七十士译本；原文是“你用慈爱和诚实带你的弟兄回去吧”。"]},{"n":21,"t":"以太回答王说：“我指着永生的耶和华起誓，又敢在王面前起誓：无论生死，王在哪里，你的仆人也必在哪里。”","notes":[]},{"n":22,"t":"大卫对以太说：“去，过去吧！”于是迦特人以太带着所有跟随他的人和孩子过去了。","notes":[]},{"n":23,"t":"众百姓过去时，当地的人全都放声大哭。王过了汲沦溪，众百姓就往旷野的路上去了。","notes":[]},{"n":24,"t":"看哪，撒督和所有抬神约柜的利未人也一同来了。他们将神的约柜放下，亚比亚他上来，直到众百姓从城里出来走过去为止。","notes":["“放下...上来”：原文另译“放在亚比亚他的旁边”。"]},{"n":25,"t":"王对撒督说：“你将神的约柜请回城去。我若在耶和华眼前蒙恩，他必使我回来，再见到约柜和他的居所。","notes":[]},{"n":26,"t":"倘若他说：‘我不喜爱你’；我在这里，就照他眼中看为好的待我！”","notes":[]},{"n":27,"t":"王对撒督祭司说：“你不是先见吗？你可以平安地回城，你儿子亚希玛斯和亚比亚他的儿子约拿单，你们二人的儿子可以与你们同去。","notes":[]},{"n":28,"t":"看，我在旷野的渡口那里等，直到你们来报信给我。”","notes":[]},{"n":29,"t":"于是撒督和亚比亚他将神的约柜请回耶路撒冷，他们就留在那里。","notes":[]},{"n":30,"t":"大卫蒙头赤脚走上橄榄山的斜坡，一面上一面哭。所有跟随他的百姓也都各自蒙头哭着上去；","notes":[]},{"n":31,"t":"有人告诉大卫说：“亚希多弗也在叛党之中，随从押沙龙。”大卫说：“耶和华啊，求你使亚希多弗的计谋变为愚拙！”","notes":["“有人告诉大卫说”是根据七十士译本和死海古卷；原文是“大卫说”。"]},{"n":32,"t":"大卫到了山顶，敬拜神的地方，看哪，亚基人户筛衣服撕裂，头蒙灰尘来迎见他。","notes":[]},{"n":33,"t":"大卫对他说：“你若与我一同过去，必拖累我；","notes":[]},{"n":34,"t":"你若回城去，对押沙龙说：‘王啊，我愿作你的仆人。我向来作你父亲的仆人，现在我也愿意作你的仆人。’你就可以为我破坏亚希多弗的计谋。","notes":[]},{"n":35,"t":"撒督和亚比亚他二位祭司岂不都在你那里吗？你在王宫里听见什么，就要告诉撒督和亚比亚他二位祭司。","notes":[]},{"n":36,"t":"看哪，撒督的儿子亚希玛斯，亚比亚他的儿子约拿单，也跟二位祭司在那里。凡你们所听见的事，可以托这二人来向我报告。”","notes":[]},{"n":37,"t":"于是，大卫的朋友户筛进了城，押沙龙也进了耶路撒冷。","notes":[]}]},"16":{"heading":"大卫和洗巴","verses":[{"n":1,"t":"大卫刚过山顶，看哪，米非波设的仆人洗巴拉着装好鞍子的两匹驴，驴上驮着二百个面饼，一百个葡萄饼，一百个夏天的果饼，一皮袋酒来迎接他。","notes":[]},{"n":2,"t":"王对洗巴说：“你的这些东西是什么意思呢？”洗巴说：“驴是给王的家眷骑的，面饼和夏天的果饼是给年轻人吃的，酒是给在旷野疲乏的人喝的。”","notes":[]},{"n":3,"t":"王说：“你主人的儿子在哪里呢？”洗巴对王说：“看哪，他留在耶路撒冷，因他说：‘以色列家今日必将我父的国归还我。’”","notes":[]},{"n":4,"t":"王对洗巴说：“看哪，凡属米非波设的都是你的了。”洗巴说：“我叩拜我主我王，愿我在你眼前蒙恩宠。”","notes":[]},{"n":5,"t":"大卫王到了巴户琳，看哪，有一个人从那里出来，是扫罗家族中基拉的儿子，名叫示每。他一面走一面咒骂，","notes":[],"heads":["大卫和示每"]},{"n":6,"t":"又向大卫王和王的众臣仆扔石头；众百姓和勇士都在王的左右。","notes":[]},{"n":7,"t":"示每这样咒骂说：“你这好流人血的，你这无赖，滚吧！滚吧！","notes":[]},{"n":8,"t":"你流了扫罗全家的血，接续他作王，耶和华把这罪归在你身上。耶和华将这国交在你儿子押沙龙的手中。看哪，你咎由自取，因为你是好流人血的人。”","notes":[]},{"n":9,"t":"洗鲁雅的儿子亚比筛对王说：“这死狗为何咒骂我主我王呢？让我过去，割下他的头来。”","notes":[]},{"n":10,"t":"王说：“洗鲁雅的儿子，我与你们有何相干呢？他这样咒骂是因耶和华吩咐他：‘你要咒骂大卫。’如此，谁敢说：‘你为什么这样做呢？’”","notes":[]},{"n":11,"t":"大卫又对亚比筛和众臣仆说：“看哪，我亲生的儿子尚且寻索我的性命，何况现在这便雅悯人呢？由他咒骂吧！因为这是耶和华吩咐他的。","notes":[]},{"n":12,"t":"或者耶和华见我遭难，因我今日被这人咒骂而向我施恩。”","notes":["“我遭难”是根据一些古卷、七十士译本和其他古译本；原文是“我的眼睛”或“我的罪孽”。"]},{"n":13,"t":"于是大卫和他的人在路上走。示每走在大卫对面的山坡，一面走一面咒骂，又向他扔石头，扬起尘土。","notes":[]},{"n":14,"t":"王和跟随他的众百姓来了，非常疲乏，就在那里歇息。","notes":[]},{"n":15,"t":"押沙龙和以色列众百姓来到耶路撒冷，亚希多弗也与他同来。","notes":[],"heads":["押沙龙在耶路撒冷"]},{"n":16,"t":"大卫的朋友亚基人户筛来到押沙龙那里，对他说：“愿王万岁！愿王万岁！”","notes":[]},{"n":17,"t":"押沙龙对户筛说：“你这样做是忠诚对待你的朋友吗？为什么不与你的朋友同去呢？”","notes":[]},{"n":18,"t":"户筛对押沙龙说：“不，谁是耶和华和这百姓，以及以色列众人所拣选的，我必归顺他，留在他那里。","notes":[]},{"n":19,"t":"再者，我当服事谁呢？岂不是前王的儿子吗？我怎样服事你父亲，也必照样服事你。”","notes":[]},{"n":20,"t":"押沙龙对亚希多弗说：“你们出个主意，我们该怎么做？”","notes":[]},{"n":21,"t":"亚希多弗对押沙龙说：“你父亲所留下看守宫殿的妃嫔，你可以与她们亲近。以色列众人听见你敢惹你父亲憎恶你，凡归顺你人的手就更坚强了。”","notes":[]},{"n":22,"t":"于是他们为押沙龙在屋顶上支搭帐棚，押沙龙就在以色列众人眼前，与他父亲的妃嫔亲近。","notes":[]},{"n":23,"t":"那时亚希多弗所出的主意好像人从神求问得来的话一样；他给大卫，给押沙龙所出的一切主意，都是这样。","notes":[]}]},"17":{"heading":"户筛破坏亚希多弗的计谋","verses":[{"n":1,"t":"亚希多弗对押沙龙说：“请让我挑选一万二千人，今夜起身追赶大卫。","notes":[]},{"n":2,"t":"我必趁他疲乏手软的时候追上他，使他惊惶。跟随他的众百姓必都逃跑，我就只杀王一个人。","notes":[]},{"n":3,"t":"我必使众百姓都归顺你，正如众人归顺你所追杀的人一样，众百姓就都平安无事了。”","notes":["“正如...一样”：七十士译本是“如同新娘归回丈夫一样，你单追杀一人”。"]},{"n":4,"t":"这话在押沙龙和以色列众长老的眼中都看为好。","notes":[]},{"n":5,"t":"押沙龙说：“把亚基人户筛也召来，我们也要听他怎么说。”","notes":[]},{"n":6,"t":"户筛到了押沙龙那里，押沙龙向他说：“亚希多弗说了这样的话，我们要照他的话做吗？若不可，你就说吧！”","notes":[]},{"n":7,"t":"户筛对押沙龙说：“亚希多弗这次所出的主意不好。”","notes":[]},{"n":8,"t":"户筛又说：“你知道，你父亲和他的人都是勇士，他们心里恼怒，如同田野中失去小熊的母熊一样；而且你父亲是个战士，必不和百姓一同住宿。","notes":[]},{"n":9,"t":"看哪，他现今或藏在一个坑中或在别处，若我们有人首先被杀，听见的必说：‘跟随押沙龙的百姓被杀了。’","notes":["“我们”是根据七十士译本的一些抄本；原文是“他们”。"]},{"n":10,"t":"虽有勇士胆大如狮子，他的心也必定融化，因为全以色列都知道你父亲是英雄，跟随他的人都是勇士。","notes":[]},{"n":11,"t":"依我之计，要把如同海边的沙那样多的以色列众人，从但直到别是巴，聚集到你这里来，由你亲自率领他们出战。","notes":[]},{"n":12,"t":"我们到他那里，在任何地方遇见他，就突然临到他，如同露水滴在泥土上。这样，他和所有跟随他的人，一个也不留。","notes":[]},{"n":13,"t":"他若撤退到一座城，以色列众人必带绳子去那城，把城拉到河里，甚至连一块小石子也找不到。”","notes":[]},{"n":14,"t":"押沙龙和以色列众人都说：“亚基人户筛的计谋比亚希多弗的更好！”这是因为耶和华定意破坏亚希多弗的良谋，为的是耶和华要降祸给押沙龙。","notes":[]},{"n":15,"t":"户筛对撒督和亚比亚他二位祭司说：“亚希多弗为押沙龙和以色列的长老出的主意是如此如此，我出的主意是如此如此。","notes":[],"heads":["大卫获警告而逃脱"]},{"n":16,"t":"现在你们要急速派人去告诉大卫说：‘今夜不可在旷野的渡口住宿，务要过河，免得王和所有跟随他的百姓都被吞灭。’”","notes":[]},{"n":17,"t":"约拿单和亚希玛斯在隐．罗结等候，不敢进城，恐怕被人看见。有一个婢女出来，把这话告诉他们，他们就去报信给大卫王。","notes":[]},{"n":18,"t":"然而有一个僮仆看见他们，就去告诉押沙龙。他们二人急忙离开，跑到巴户琳一个人的家里。那人院中有一口井，他们就下到那里。","notes":[]},{"n":19,"t":"那家的妇人用盖盖上井口，又在上头铺上碎麦，事情就没有泄漏。","notes":[]},{"n":20,"t":"押沙龙的仆人来到妇人的家，说：“亚希玛斯和约拿单在哪里？”妇人对他们说：“他们过了河了。”仆人搜寻，却找不着，就回耶路撒冷去了。","notes":[]},{"n":21,"t":"他们走后，二人从井里上来，去告诉大卫王。他们对大卫说：“亚希多弗出这样的主意要害你，你们起来，快快过河。”","notes":[]},{"n":22,"t":"于是大卫和所有跟随他的百姓都起来，过约旦河。到了天亮，无一人不过约旦河的。","notes":[]},{"n":23,"t":"亚希多弗见他的计谋不被接纳，就备上驴，动身归回本城，到了自己的家。他留下遗嘱给他的家，就上吊死了，葬在他父亲的坟墓里。","notes":[]},{"n":24,"t":"大卫到了玛哈念，押沙龙和跟随他的以色列众人也都过了约旦河。","notes":[]},{"n":25,"t":"押沙龙立亚玛撒作元帅，取代约押。亚玛撒是以实玛利人以特拉的儿子。以特拉曾与拿辖的女儿亚比该亲近；这亚比该与约押的母亲洗鲁雅是姊妹。","notes":["“以实玛利人”是根据七十士译本的一些抄本；原文是“以色列人”；参代上2．17。","“拿辖”：七十士译本是“耶西”；参代上2．16。"]},{"n":26,"t":"押沙龙和以色列人安营在基列地。","notes":[]},{"n":27,"t":"大卫到了玛哈念，亚扪族的拉巴人拿辖的儿子朔比，罗．底巴人亚米利的儿子玛吉，来自罗基琳的基列人巴西莱，","notes":[]},{"n":28,"t":"带着被褥、盆、瓦器，还有小麦、大麦、麦面、烤熟的谷穗、豆子、红豆、炒豆、","notes":[]},{"n":29,"t":"蜂蜜、奶油、绵羊、奶饼，供给大卫和跟随他的人吃，因为他们想：“百姓在旷野中，必定又饥渴又疲乏。”","notes":[]}]},"18":{"heading":"押沙龙败亡","verses":[{"n":1,"t":"大卫数点跟随他的百姓，立千夫长、百夫长率领他们。","notes":[]},{"n":2,"t":"大卫把军兵分为三队：三分之一在约押手下，三分之一在洗鲁雅的儿子约押弟弟亚比筛手下，三分之一在迦特人以太手下。王对军兵说：“我必与你们一同出战。”","notes":["“把军兵分为三队”是根据七十士译本的一些抄本；原文是“派遣军兵”。"]},{"n":3,"t":"军兵却说：“你不可出战。若是我们逃跑，敌人不会把心放在我们身上；我们阵亡一半，敌人也不会把心放在我们身上。但现在你一人抵过我们万人，所以你最好留在城里支援我们。”","notes":[]},{"n":4,"t":"王对他们说：“你们看怎样好，我就怎样做。”于是王站在城门旁，所有的军兵成百成千地挨次出战去了。","notes":[]},{"n":5,"t":"王嘱咐约押、亚比筛、以太说：“你们要为我的缘故宽待那年轻人押沙龙。”王为押沙龙的事嘱咐众将领的话，所有的军兵都听见了。","notes":[]},{"n":6,"t":"军兵出到田野迎战以色列，在以法莲的树林里交战。","notes":[]},{"n":7,"t":"在那里，以色列百姓败在大卫的臣仆面前。那日在那里阵亡的很多，共有二万人。","notes":[]},{"n":8,"t":"战争蔓延到整个地面，那日被树林吞噬的军兵比被刀剑吞噬的更多。","notes":[]},{"n":9,"t":"押沙龙刚好遇见了大卫的臣仆。押沙龙骑着骡子，从大橡树密枝底下经过，他的头被橡树夹住，悬挂在空中，所骑的骡子就离他去了。","notes":["“空中”：原文直译“天和地之间”。"]},{"n":10,"t":"有个人看见，就告诉约押说：“看哪，我看见押沙龙挂在橡树上了。”","notes":[]},{"n":11,"t":"约押对报信的人说：“看哪，你既看见了，为什么不当场把他击杀在地呢？我必赏你十个银子和一条带子。”","notes":[]},{"n":12,"t":"那人对约押说：“即使我手里得了一千银子，也不敢伸手害王的儿子，因为我们听见王嘱咐你、亚比筛、以太说：‘你们要谨慎，不可害那年轻人押沙龙。’","notes":[]},{"n":13,"t":"我若冒着生命危险做这傻事，无论何事都瞒不过王，你自己也必远远站在一旁。”","notes":["“我若...这傻事”：原文另译“我若妄为害了他的性命”。"]},{"n":14,"t":"约押说：“我不能在你面前这样耗下去！”约押手拿三枝短枪，趁押沙龙在橡树上还活着，就刺透他的心。","notes":["“在橡树上”：原文直译“在橡树的心”。"]},{"n":15,"t":"给约押拿兵器的十个青年围着押沙龙，击杀他，将他杀死。","notes":[]},{"n":16,"t":"约押吹角，军兵就回来，不去追赶以色列人，因为约押制止了军兵。","notes":[]},{"n":17,"t":"他们拿下押沙龙，把他丢在树林中一个大坑里，上头堆起一大堆石头。以色列众人都逃跑，各回自己的帐棚去了。","notes":[]},{"n":18,"t":"押沙龙活着的时候，曾在王谷立了一根柱子，因他说：“我没有儿子为我留名。”他就以自己的名字称那柱子为押沙龙碑，直到今日。","notes":[]},{"n":19,"t":"撒督的儿子亚希玛斯说：“让我跑去报信给王，耶和华已经为王伸冤，使他脱离仇敌的手了。”","notes":[],"heads":["大卫听闻押沙龙死讯"]},{"n":20,"t":"约押对他说：“你今日不可作报信的人，改日再去报信；因为今日王的儿子死了，所以你不可去报信。”","notes":[]},{"n":21,"t":"约押对古实人说：“你去把你所看见的告诉王。”古实人向约押叩拜后，就跑去了。","notes":[]},{"n":22,"t":"撒督的儿子亚希玛斯又对约押说：“无论怎样，让我随着古实人跑去吧！”约押说：“我儿，你报这信息，既不得赏赐，何必要跑去呢？”","notes":[]},{"n":23,"t":"他说：“无论怎样，我要跑去。”约押对他说：“你跑去吧！”亚希玛斯就从平原的路往前跑，越过了古实人。","notes":[]},{"n":24,"t":"大卫正坐在内外城门之间。守望的人上到城墙，在城门的顶上举目观看，看哪，有一个人独自跑来。","notes":[]},{"n":25,"t":"守望的人就大声告诉王。王说：“他若独自来，必是报口信的。”那人跑得越来越近了。","notes":[]},{"n":26,"t":"守望的人又见一人跑来，就对守城门的人喊说：“看哪，又有一人独自跑来。”王说：“这也是报信的。”","notes":[]},{"n":27,"t":"守望的人说：“我看前面那人的跑法，好像撒督的儿子亚希玛斯的跑法。”王说：“他是个好人，是来报好消息的。”","notes":[]},{"n":28,"t":"亚希玛斯向王呼叫说：“平安了！”他就脸伏于地向王叩拜，说：“耶和华－你的神是应当称颂的，他已把那些举手攻击我主我王的人交出来了。”","notes":[]},{"n":29,"t":"王说：“年轻人押沙龙平安吗？”亚希玛斯说：“约押派王的仆人，就是你的仆人时，我看见一阵大骚动，却不知道是什么事。”","notes":[]},{"n":30,"t":"王说：“你退去，站在这里。”他就退去，站着。","notes":[]},{"n":31,"t":"看哪，古实人也来到，说：“有信息报给我主我王！耶和华今日为你伸冤，使你脱离一切起来攻击你之人的手。”","notes":[]},{"n":32,"t":"王对古实人说：“年轻人押沙龙平安吗？”古实人说：“愿我主我王的仇敌，和一切起来恶意要害你的人，都像那年轻人一样。”","notes":[]},{"n":33,"t":"王战抖，就上城门的楼房去痛哭，一面走一面说：“我儿押沙龙啊！我儿，我儿押沙龙啊！我恨不得替你死，押沙龙啊，我儿！我儿！”","notes":[]}]},"19":{"heading":"约押劝谏王","verses":[{"n":1,"t":"有人告诉约押：“看哪，王为押沙龙悲哀哭泣。”","notes":[]},{"n":2,"t":"那日众军兵听说王为他儿子悲伤，他们得胜的日子变成悲哀了。","notes":[]},{"n":3,"t":"那日军兵暗暗地进城，如同战场上逃跑、羞愧的士兵一般。","notes":[]},{"n":4,"t":"王蒙着脸，大声哭号说：“我儿押沙龙啊！押沙龙，我儿，我儿啊！”","notes":[]},{"n":5,"t":"约押进了宫到王那里，说：“你今日使你众臣仆的脸面羞愧了！他们今日救了你的性命和你儿女妻妾的性命，","notes":[]},{"n":6,"t":"你却爱那些恨你的人，恨那些爱你的人。今日你摆明了不以将帅、臣仆为念。我今日看得出，若押沙龙活着，我们今日全都死了，你就高兴了。","notes":[]},{"n":7,"t":"现在你要起来，出去安慰你臣仆的心。我指着耶和华起誓：你若不出去，今夜必没有一人跟你在一起了。这祸患比你从幼年到如今所遭受的更严重！”","notes":[]},{"n":8,"t":"于是王起来，坐在城门口。有人告诉众军兵说：“看哪，王坐在城门口。”众军兵就都到王的面前。那时，以色列人已经逃跑，各回自己的帐棚去了。","notes":[]},{"n":9,"t":"以色列众支派的百姓都议论纷纷，说：“王曾救我们脱离仇敌的手，又救我们脱离非利士人的手，现在他为了押沙龙逃离这地了。","notes":[]},{"n":10,"t":"我们所膏治理我们的押沙龙已经阵亡。现在你们为什么沉默，不请王回来呢？”","notes":[]},{"n":11,"t":"大卫王派人到撒督和亚比亚他二位祭司那里，说：“你们当向犹大长老说：‘以色列众人已经有话到了王那里，你们为什么最后才请王回宫呢？","notes":["“到了王那里”是根据七十士译本；原文是“到了王那里，到了宫里”。"]},{"n":12,"t":"你们是我的弟兄，是我的骨肉，为什么最后才请王回来呢？’","notes":[]},{"n":13,"t":"你们要对亚玛撒说：‘你不是我的骨肉吗？我若不立你在我面前取代约押永久作元帅，愿神重重惩罚我！’”","notes":[]},{"n":14,"t":"这样，他挽回了犹大众人的心，如同一人。他们就派人到王那里，说：“请王和王的众臣仆回来。”","notes":[]},{"n":15,"t":"王回来了，到约旦河。犹大人来到吉甲，去迎接王，请王过约旦河。","notes":[]},{"n":16,"t":"来自巴户琳的便雅悯人基拉的儿子示每急忙与犹大人一同下去迎接大卫王。","notes":[]},{"n":17,"t":"跟从示每的有一千个便雅悯人，还有扫罗家的仆人洗巴和他十五个儿子、二十个随从仆人，他们都赶紧过约旦河到王的面前。","notes":[]},{"n":18,"t":"渡船就渡王的家眷过河，照王看为好的去做。王过约旦河的时候，基拉的儿子示每俯伏在王面前，","notes":["“渡船...过河”：七十士译本是“他们过到渡口，把王的家眷渡过河”。"]},{"n":19,"t":"对王说：“我主我王离开耶路撒冷的那日，仆人行了悖逆的事，现在求我主不要因此加罪于仆人，不要记得，也不要放在心上。","notes":[]},{"n":20,"t":"仆人明知自己有罪，看哪，约瑟全家之中，今日我首先下来迎接我主我王。”","notes":[]},{"n":21,"t":"洗鲁雅的儿子亚比筛回答说：“示每既然咒骂耶和华的受膏者，不应当为这缘故处死他吗？”","notes":[]},{"n":22,"t":"大卫说：“洗鲁雅的儿子，我与你们有何相干，你们今日要跟我作对吗？今日在以色列中岂可把任何人处死呢？我岂不知今日我是以色列的王吗？”","notes":[]},{"n":23,"t":"于是王对示每说：“你必不死。”王就向他起誓。","notes":[]},{"n":24,"t":"扫罗的孙子米非波设也下去迎接王。他自从王离开的那一日，直到王平安回耶路撒冷的日子，没有修脚，没有剃胡须，也没有洗衣服。","notes":[],"heads":["大卫善待米非波设"]},{"n":25,"t":"他来迎接王的时候，王对他说：“米非波设，你为什么没有与我同去呢？”","notes":["“直到王平安回耶路撒冷的日子...迎接王的时候”：原文是“直到王平安回来的日子，没有修脚，没有剃胡须，也没有洗衣服。他来到耶路撒冷迎接王的时候”。"]},{"n":26,"t":"他说：“我主我王啊，我的仆人欺骗了我。那日仆人想要备驴骑上，与王同去，因为仆人是瘸腿的。","notes":[]},{"n":27,"t":"他却在我主我王面前毁谤仆人。然而我主我王如同神的使者一样，你看怎样好，就怎样做吧！","notes":[]},{"n":28,"t":"因为我祖全家的人，在我主我王面前不过是该死的人，王却使仆人列在王的席上吃饭的人当中，我现在还有什么权利能向王请求呢？”","notes":[]},{"n":29,"t":"王对他说：“你何必再提你的事呢？我说，你与洗巴要平分土地。”","notes":[]},{"n":30,"t":"米非波设对王说：“我主我王既然平安地回宫，甚至让洗巴全都拿去也没关系。”","notes":[]},{"n":31,"t":"基列人巴西莱从罗基琳下来，要护送王过约旦河，就跟王一同过约旦河。","notes":[],"heads":["大卫善待巴西莱"]},{"n":32,"t":"巴西莱年纪老迈，已经八十岁了。王住在玛哈念的时候，他拿食物来供给王，因他是个大富翁。","notes":[]},{"n":33,"t":"王对巴西莱说：“你与我一同渡过去，我要在耶路撒冷我的身边奉养你。”","notes":[]},{"n":34,"t":"巴西莱对王说：“我还能活多少年日，可以与王一同上耶路撒冷呢？","notes":[]},{"n":35,"t":"今日我已八十岁了，还能辨别美丑吗？仆人还能尝出饮食的滋味吗？还能听男女歌唱的声音吗？仆人何必拖累我主我王呢？","notes":[]},{"n":36,"t":"仆人护送王过约旦河只是一件小事，王何必用这样的赏赐来报答我呢？","notes":[]},{"n":37,"t":"请让我回去，死在我本城，葬在我父母的墓旁。看哪，这里有金罕作王的仆人，让他同我主我王过去，你看怎样好，就怎样对待他吧。”","notes":[]},{"n":38,"t":"王说：“金罕可以与我一同过去，我必照你看为好的待他。你要我做的，我都会为你做。”","notes":[]},{"n":39,"t":"于是众百姓过了约旦河，王也过去了。王亲吻巴西莱，为他祝福，巴西莱就回自己的地方去了。","notes":[]},{"n":40,"t":"王渡过去，到了吉甲，金罕也跟他过去。犹大众百姓和以色列百姓的一半也都送王过去。","notes":["“王渡过去”：七十士译本是“王继续前进”。"]},{"n":41,"t":"看哪，以色列众人来到王那里，对王说：“我们的弟兄犹大人为什么暗暗地送王和王的家眷，以及所有跟随王的人，过约旦河呢？”","notes":[],"heads":["以色列人和犹大人为王起争论"]},{"n":42,"t":"犹大众人回答以色列人说：“因为王与我们是亲属，你们为何因这事发怒呢？我们靠王吃了什么呢？王真正给了我们什么赏赐呢？”","notes":[]},{"n":43,"t":"以色列人回答犹大人说：“我们与王有十倍的关系，就是在大卫身上，我们也比你们更有权利。你们为何藐视我们呢？我们不是最先提议请王回来的吗？”但犹大人的话比以色列人的话更强硬。","notes":["“我们也比你们更有权利”：原文是“我也比你更有权利”；七十士译本是“我也比你年长”。"]}]},"20":{"heading":"示巴反叛","verses":[{"n":1,"t":"在那里恰巧有一个无赖，名叫示巴，是便雅悯人比基利的儿子。他吹角，说：“我们与大卫无份，与耶西的儿子无关。以色列啊，各回自己的帐棚去吧！”","notes":[]},{"n":2,"t":"于是以色列众人都离弃大卫去跟随比基利的儿子示巴，但犹大人从约旦河直到耶路撒冷，都紧紧跟随他们的王。","notes":[]},{"n":3,"t":"大卫王来到耶路撒冷，进了宫，就把从前留下看守宫殿的十个妃嫔软禁在冷宫，养活她们，却不与她们亲近。她们被关起来，活着如同寡妇，直到死的日子。","notes":[]},{"n":4,"t":"王对亚玛撒说：“你要在三日之内召集犹大人到我这里来，你自己也要留在这里。”","notes":[]},{"n":5,"t":"亚玛撒就去召集犹大人，不过他却耽延，过了王所定的期限。","notes":[]},{"n":6,"t":"大卫对亚比筛说：“现在比基利的儿子示巴对我们的危害恐怕比押沙龙更大。你要带领你主的一些仆人追赶他，免得他得了坚固的城镇，在我们眼前逃脱。”","notes":["“在我们眼前逃脱”：原文另译“带给我们麻烦”。"]},{"n":7,"t":"约押的人和基利提人、比利提人，以及所有的勇士都跟着亚比筛，从耶路撒冷出去追赶比基利的儿子示巴。","notes":[]},{"n":8,"t":"他们到了基遍的大石头那里，亚玛撒来迎接他们。那时约押穿着战衣，腰束佩刀的带子，刀在鞘内。约押前行时，刀从鞘内掉出来。","notes":[]},{"n":9,"t":"约押对亚玛撒说：“我的弟兄，你平安吗？”他就用右手抓住亚玛撒的胡子，要亲吻他。","notes":[]},{"n":10,"t":"亚玛撒没有防备约押手里拿着的刀；约押用刀刺入他的肚腹，他的肠子流在地上，约押没有再刺，他就死了。约押和他弟弟亚比筛往前追赶比基利的儿子示巴。","notes":[]},{"n":11,"t":"有约押的一个仆人站在亚玛撒尸体的旁边，说：“谁喜爱约押，谁归顺大卫，就当跟随约押。”","notes":[]},{"n":12,"t":"亚玛撒浑身是血，躺在路中间。那人见众百姓都站住，就把亚玛撒的尸体从路上移到田间，把衣服盖在他身上，因为他看见众人经过时都站住。","notes":[]},{"n":13,"t":"尸体从路上移走之后，众人就都跟随约押去追赶比基利的儿子示巴。","notes":[]},{"n":14,"t":"示巴走遍以色列各支派，直到伯．玛迦的亚比拉；所有精选的人都聚集跟随他。","notes":["“精选的人”：原文是“比利人”。"]},{"n":15,"t":"跟随约押的众百姓到了伯．玛迦的亚比拉，围困示巴，对着城建土堆，与城郭相对。他们猛撞城墙，要使城倒塌。","notes":[]},{"n":16,"t":"一个有智慧的妇人从城上呼叫：“听啊，听啊，请你们告诉约押：‘近前来到这里，我好与你说话。’”","notes":[]},{"n":17,"t":"约押就近前到她那里，妇人对他说：“你是约押吗？”他说：“我是。”妇人对他说：“请你听使女的话。”约押说：“我正在听。”","notes":[]},{"n":18,"t":"妇人说：“古时有话说，当在亚比拉求问，事情就可以解决。","notes":[]},{"n":19,"t":"我在以色列中是和平、忠诚的。你现在想要毁坏这城，以色列的根源，为何你要吞灭耶和华的产业呢？”","notes":["“根源”：原文是“母亲”。"]},{"n":20,"t":"约押回答说：“不，我绝不吞灭和毁坏！","notes":[]},{"n":21,"t":"话不是这么说的，只是因为有一个以法莲山区的人，就是比基利的儿子名叫示巴，他举手攻击大卫王；你们只要把他一人交出来，我就离城而去。”妇人对约押说：“看哪，他的首级必从城墙上丢给你。”","notes":[]},{"n":22,"t":"妇人凭她的智慧去劝众百姓，他们就割下比基利的儿子示巴的首级，丢给约押。约押吹角，众人就离城散开，各回自己的帐棚去了。约押回耶路撒冷，到王那里。","notes":[]},{"n":23,"t":"约押统管以色列全军；耶何耶大的儿子比拿雅统管基利提人和比利提人；","notes":[]},{"n":24,"t":"亚多兰管理劳役的人；亚希律的儿子约沙法作史官；","notes":[]},{"n":25,"t":"示法作书记；撒督和亚比亚他作祭司；","notes":[]},{"n":26,"t":"睚珥人以拉也作大卫的祭司。","notes":[]}]},"21":{"heading":"扫罗的后代被处死","verses":[{"n":1,"t":"大卫在位年间有饥荒，一连三年，大卫求问耶和华，耶和华说：“扫罗和他家犯了流人血之罪，因为他杀死了基遍人。”","notes":[]},{"n":2,"t":"大卫王召了基遍人来，跟他们说话。基遍人不是以色列人，而是亚摩利人中所剩下的人。以色列人曾向他们起誓，扫罗却为以色列人和犹大人大发热心，追杀他们，为了要消灭他们。","notes":[]},{"n":3,"t":"大卫对基遍人说：“我当为你们做什么呢？要用什么赎这罪，使你们为耶和华的产业祝福呢？”","notes":[]},{"n":4,"t":"基遍人对他说：“我们和扫罗以及他家的事与金银无关，也不要因我们的缘故杀任何以色列人。”大卫说：“你们怎样说，我就为你们怎样做。”","notes":[]},{"n":5,"t":"他们对王说：“那谋害我们、要消灭我们、使我们不得住以色列境内的人，","notes":[]},{"n":6,"t":"请把他的子孙七人交给我们，我们好在耶和华面前，把他们悬挂在基比亚，就是耶和华拣选扫罗的地方。”王说：“我必交给你们。”","notes":[]},{"n":7,"t":"王顾惜扫罗的孙子，约拿单的儿子米非波设，因为在大卫和扫罗的儿子约拿单之间，有指着耶和华的誓言。","notes":[]},{"n":8,"t":"王却把爱亚的女儿利斯巴为扫罗所生的两个儿子亚摩尼和米非波设，以及扫罗的女儿米拉为米何拉人巴西莱儿子亚得列所生的五个儿子","notes":["“米拉”是根据有些古卷和其他古译本；原文是“米甲”。"]},{"n":9,"t":"交在基遍人的手里。基遍人在耶和华面前把他们悬挂在山上，这七人就一起死了。他们被杀的时候正是收割的头几天，就是开始收割大麦的时候。","notes":[]},{"n":10,"t":"爱亚的女儿利斯巴用麻布铺在磐石上搭棚，从收割的开始直到天降雨在尸体上，她白日不许空中的飞鸟落在尸体上，夜间不让田野的走兽前来。","notes":[]},{"n":11,"t":"有人把扫罗的妃子爱亚女儿利斯巴所做的事告诉大卫。","notes":[]},{"n":12,"t":"大卫就去，从基列的雅比人那里把扫罗和他儿子约拿单的骸骨搬来。先前非利士人在基利波杀了扫罗，把尸体悬挂在伯．珊的广场上，后来基列的雅比人把尸体偷走。","notes":[]},{"n":13,"t":"大卫把扫罗和他儿子约拿单的骸骨从那里搬上来，又收殓了被悬挂的那些人的骸骨。","notes":[]},{"n":14,"t":"他们将扫罗和他儿子约拿单的骸骨葬在便雅悯的洗拉，在扫罗父亲基士的坟墓里。他们遵照王所吩咐的一切做了。此后神垂听了为那地的祈求。","notes":[]},{"n":15,"t":"非利士人与以色列人打仗。大卫带领仆人下去，与非利士人交战，大卫就疲乏了。","notes":[],"heads":["攻打非利士巨人"]},{"n":16,"t":"巨人族的后裔以实．比诺说要杀大卫；他的铜枪重三百舍客勒，腰间又佩着新刀。","notes":["原文没有“刀”。"]},{"n":17,"t":"但洗鲁雅的儿子亚比筛帮助大卫攻击非利士人，杀死了他。当日，大卫的人向大卫起誓说：“你不可再与我们一同出战，免得以色列的灯熄灭了。”","notes":[]},{"n":18,"t":"后来，在歌伯又与非利士人打仗，那时户沙人西比该杀了巨人族的后裔撒弗。","notes":[]},{"n":19,"t":"他们又在歌伯与非利士人打仗，伯利恒人雅雷的儿子伊勒哈难杀了迦特人歌利亚；这人的枪杆粗如织布机的轴。","notes":["“雅雷”：原文是“雅雷．俄珥金”；原文另译“睚珥”；参代上20．5。"]},{"n":20,"t":"又有一次，他们在迦特打仗。那里有一个身材高大的人，双手各有六根手指，双脚各有六根脚趾，共有二十四根；他也是巨人族的后裔。","notes":[]},{"n":21,"t":"他向以色列骂阵，大卫的哥哥示米亚的儿子约拿单就杀了他。","notes":[]},{"n":22,"t":"这四个人是迦特巨人族的后裔，都仆倒在大卫和他仆人的手下。","notes":[]}]},"22":{"heading":"大卫的凯歌","verses":[{"n":1,"t":"当耶和华救大卫脱离所有仇敌和扫罗之手的日子，他用这诗的歌词向耶和华说话。","notes":[]},{"n":2,"t":"他说：耶和华是我的岩石、我的山寨、我的救主、","notes":[]},{"n":3,"t":"我的神、我的磐石、我所投靠的。他是我的盾牌，是拯救我的角，是我的碉堡，是我的避难所，是我的救主，救我脱离凶暴的。","notes":[]},{"n":4,"t":"我要求告当赞美的耶和华，我必从仇敌手中被救出来。","notes":[]},{"n":5,"t":"死亡的波浪环绕我，毁灭的急流惊吓我，","notes":[]},{"n":6,"t":"阴间的绳索缠绕我，死亡的圈套临到我。","notes":[]},{"n":7,"t":"我在急难中求告耶和华，向我的神呼求。他从殿中听了我的声音；我的呼求进入他的耳中。","notes":[]},{"n":8,"t":"那时，因他发怒地就摇撼震动；天的根基也战抖摇撼。","notes":[]},{"n":9,"t":"他的鼻孔冒烟上腾；他的口发火焚烧，连煤炭也烧着了。","notes":[]},{"n":10,"t":"他使天下垂，亲自降临；黑云在他脚下。","notes":[]},{"n":11,"t":"他乘坐基路伯飞行，在风的翅膀上显现。","notes":[]},{"n":12,"t":"他以黑暗和聚集的水、天空的密云为四围的行宫。","notes":[]},{"n":13,"t":"因他发出光辉，火炭都烧着了。","notes":[]},{"n":14,"t":"耶和华在天上打雷；至高者发出声音。","notes":[]},{"n":15,"t":"他射出箭来，使仇敌四散；发出闪电，击溃他们。","notes":[]},{"n":16,"t":"耶和华的斥责一发，鼻孔的气一出，海底就显现，大地的根基也暴露。","notes":[]},{"n":17,"t":"他从高天伸手抓住我，把我从大水中拉上来。","notes":[]},{"n":18,"t":"他救我脱离我的强敌，脱离那些恨我的人，因为他们比我强盛。","notes":[]},{"n":19,"t":"我遭遇灾难的日子，他们来攻击我；但耶和华是我的倚靠。","notes":[]},{"n":20,"t":"他领我到宽阔之处，他救拔我，因他喜爱我。","notes":[]},{"n":21,"t":"耶和华必按我的公义报答我，按我手中的清洁赏赐我。","notes":[]},{"n":22,"t":"因为我遵守耶和华的道，未曾作恶离开我的神。","notes":[]},{"n":23,"t":"他的一切典章在我面前，他的律例我也未曾丢弃。","notes":[]},{"n":24,"t":"我在他面前作了完全人，我也持守自己远离罪孽。","notes":[]},{"n":25,"t":"所以耶和华按我的公义，在他眼前按我的清洁赏赐我。","notes":[]},{"n":26,"t":"慈爱的人，你以慈爱待他；完全的人，你以完善待他；","notes":[]},{"n":27,"t":"清洁的人，你以清洁待他；歪曲的人，你以弯曲待他。","notes":[]},{"n":28,"t":"困苦的百姓，你必拯救；但你的眼目察看高傲的人，使他们降卑。","notes":[]},{"n":29,"t":"耶和华啊，你是我的灯；耶和华必照明我的黑暗。","notes":[]},{"n":30,"t":"我藉着你冲入敌军，藉着我的神跳过城墙。","notes":[]},{"n":31,"t":"至于神，他的道是完全的；耶和华的话是纯净的。凡投靠他的，他就作他们的盾牌。","notes":[]},{"n":32,"t":"除了耶和华，谁是神呢？除了我们的神，谁是磐石呢？","notes":[]},{"n":33,"t":"神是我坚固的保障，他为我开完全的路。","notes":[]},{"n":34,"t":"他使我的脚快如母鹿，使我站稳在高处。","notes":[]},{"n":35,"t":"他教导我的手能争战，我的膀臂能开铜造的弓。","notes":[]},{"n":36,"t":"你赐救恩给我作盾牌，你的庇护使我为大。","notes":["“庇护”或译“温和”。"]},{"n":37,"t":"你使我脚步宽阔，我的脚踝未曾滑跌。","notes":[]},{"n":38,"t":"我追赶我的仇敌，消灭他们；若不将他们灭绝，我总不归回。","notes":[]},{"n":39,"t":"我灭绝了他们，打伤了他们，使他们站不起来；他们都倒在我的脚下。","notes":[]},{"n":40,"t":"你曾以力量束我的腰，使我能争战；也曾使那起来攻击我的，都服在我以下。","notes":[]},{"n":41,"t":"你又使我的仇敌在我面前转身逃跑，使我能歼灭那恨我的人。","notes":[]},{"n":42,"t":"他们仰望，却无人拯救；就是呼求耶和华，他也不应允。","notes":[]},{"n":43,"t":"我捣碎他们，如同地上的灰尘；践踏压碎他们，如同街上的泥土。","notes":[]},{"n":44,"t":"你救我脱离我百姓的纷争，保护我作列国的元首；我素不认识的百姓必事奉我。","notes":["“我百姓”：有古卷和七十士译本是“百姓”。"]},{"n":45,"t":"外邦人要向我投降，一听见我的名声就必顺从我。","notes":[]},{"n":46,"t":"外邦人要丧胆，战战兢兢地出营寨。","notes":[]},{"n":47,"t":"耶和华永远活着。愿我的磐石被称颂，愿神－救我的磐石受尊崇。","notes":[]},{"n":48,"t":"这位神为我伸冤，使万民服在我以下。","notes":[]},{"n":49,"t":"他救我脱离仇敌，又把我举起，高过那些起来攻击我的人，救我脱离残暴的人。","notes":[]},{"n":50,"t":"耶和华啊，因此我要在列国中称谢你，歌颂你的名。","notes":[]},{"n":51,"t":"耶和华赐极大的救恩给他所立的王，施慈爱给他的受膏者，就是给大卫和他的后裔，直到永远！","notes":[]}]},"23":{"heading":"大卫的遗言","verses":[{"n":1,"t":"以下是大卫末了的话：“耶西的儿子大卫的话，得居高位的，雅各的神所膏的，以色列所喜爱的诗人的话。","notes":[]},{"n":2,"t":"耶和华的灵藉着我说话，他的言语在我的舌头上。","notes":[]},{"n":3,"t":"以色列的神说，以色列的磐石向我说：‘那以公义治理人，以敬畏神来治理的，","notes":[]},{"n":4,"t":"他必像晨光，如无云清晨的日出，如雨后的光辉，在嫩草地上。’","notes":[]},{"n":5,"t":"我的家在神面前不是如此吗？神与我立永远的约，这约既全备又稳妥。我的一切救恩和我一切所想望的，他岂不成全吗？","notes":[]},{"n":6,"t":"但无赖全都像被丢弃的荆棘；它们不能用手去拿；","notes":[]},{"n":7,"t":"碰它们的人必须用铁器和枪杆，它们必在那里被火烧尽。”","notes":[]},{"n":8,"t":"大卫勇士的名字如下：哈革摩尼人约设．巴设，他是三勇士之首；他又名叫伊斯尼人亚底挪，曾一次就击杀了八百人。","notes":["“哈革摩尼人”是根据可能较早的读法；原文是“他革扪人”；参代上11．11。","“他又名...八百人”：七十士译本是“他曾一次举枪击杀了八百人”；参代上11．11。"],"heads":["大卫的勇士"]},{"n":9,"t":"跟随大卫的三勇士中，其次是亚何亚人朵多的儿子以利亚撒。从前非利士人聚集要打仗，他们向非利士人骂阵。以色列人上去的时候，","notes":[]},{"n":10,"t":"他起来击杀非利士人，直到手臂疲乏，手粘住刀把。那日耶和华大获全胜，百姓跟在以利亚撒后面只顾夺取掠物。","notes":[]},{"n":11,"t":"再其次是哈拉人亚基的儿子沙玛。一次，非利士人聚集在利希，在一块长满红豆的田里，百姓在非利士人面前逃跑。","notes":["“亚基”：原文另译“以拉”。","“在利希”是根据可能是较早的读法；原文是“成群”。"]},{"n":12,"t":"沙玛却站在那田的中间，防守那田，击败了非利士人。耶和华大获全胜。","notes":[]},{"n":13,"t":"开始收割的时候，三个侍卫下到亚杜兰洞，到大卫那里。非利士的军兵在利乏音谷安营。","notes":["“三个”：原文另译“三十个”。","“侍卫”是根据可能是较早的读法；原文是“三十”。"]},{"n":14,"t":"那时大卫在山寨，非利士人的驻军在伯利恒。","notes":[]},{"n":15,"t":"大卫渴想着说：“但愿有人从伯利恒城门旁的井里打水来给我喝！”","notes":[]},{"n":16,"t":"这三个勇士就闯过非利士人的军营，从伯利恒城门旁的井里打水，拿来给大卫喝。他却不肯喝，将水浇在耶和华面前，","notes":[]},{"n":17,"t":"说：“耶和华啊，我绝不做这事！这三个人冒生命的危险，这不是他们的血吗？”大卫不肯喝这水。这是三个勇士所做的事。","notes":[]},{"n":18,"t":"洗鲁雅的儿子，约押的兄弟亚比筛是这三个勇士的领袖；他曾举枪杀了三百人，就在三个勇士中得了名。","notes":[]},{"n":19,"t":"他在这三个勇士中是最有名望的，所以作他们的领袖，只是不及前三个勇士。","notes":["“三个”：原文另译“三十个”。"]},{"n":20,"t":"耶何耶大的儿子比拿雅是来自甲薛的勇士，曾行了大事。他杀了摩押人亚利伊勒的两个儿子，又在下雪的时候下到坑里去，杀了一只狮子。","notes":[]},{"n":21,"t":"他又杀了一个魁梧的埃及人；埃及人手里拿着枪。比拿雅只拿着棍子下到他那里去，从埃及人手里夺过枪来，用那枪杀死了他。","notes":[]},{"n":22,"t":"这些是耶何耶大的儿子比拿雅所做的事，就在三个勇士里得了名。","notes":[]},{"n":23,"t":"他比那三十个勇士更有名望，只是不及前三个勇士。大卫立他作护卫长。","notes":["“那三十个勇士”：有古卷是“那些侍卫”。"]},{"n":24,"t":"三十个勇士中有约押的兄弟亚撒黑，伯利恒人朵多的儿子伊勒哈难，","notes":[]},{"n":25,"t":"哈律人沙玛，哈律人以利加，","notes":[]},{"n":26,"t":"帕勒提人希利斯，提哥亚人益吉的儿子以拉，","notes":[]},{"n":27,"t":"亚拿突人亚比以谢，户沙人米本乃，","notes":[]},{"n":28,"t":"亚何亚人撒们，尼陀法人玛哈莱，","notes":[]},{"n":29,"t":"尼陀法人巴拿的儿子希立，便雅悯族基比亚人利拜的儿子以太，","notes":[]},{"n":30,"t":"比拉顿人比拿雅，迦实溪人希太，","notes":[]},{"n":31,"t":"亚拉巴人亚比．亚本，巴鲁米人押斯玛弗，","notes":[]},{"n":32,"t":"沙本人以利雅哈巴，雅善儿子中的约拿单，","notes":[]},{"n":33,"t":"哈拉人沙玛，哈拉人沙拉的儿子亚希暗，","notes":["“雅善儿子中...沙玛”：原文另译“沽尼族的雅善，哈拉人沙玛的儿子约拿单”。"]},{"n":34,"t":"玛迦人亚哈拜的儿子以利法列，基罗人亚希多弗的儿子以连，","notes":[]},{"n":35,"t":"迦密人希斯莱，亚巴人帕莱，","notes":[]},{"n":36,"t":"琐巴人拿单的儿子以甲，迦得人巴尼，","notes":[]},{"n":37,"t":"亚扪人洗勒，比录人拿哈莱，是给洗鲁雅的儿子约押拿兵器的，","notes":[]},{"n":38,"t":"以帖人以拉，以帖人迦立，","notes":[]},{"n":39,"t":"赫人乌利亚，共三十七人。","notes":[]}]},"24":{"heading":"大卫调查人口","verses":[{"n":1,"t":"耶和华的怒气又向以色列发作，激起大卫来对付他们，说：“去，数点以色列人和犹大人。”","notes":[]},{"n":2,"t":"大卫对跟随他的约押元帅说：“你来回走遍以色列众支派，从但直到别是巴，数点百姓，我好知道百姓的数目。”","notes":[]},{"n":3,"t":"约押对王说：“愿耶和华－你的神使百姓的数目增加百倍，使我主我王亲眼得见。我主我王何必要做这事呢？”","notes":[]},{"n":4,"t":"但王坚持他对约押和众军官的命令。约押和众军官就从王面前出去，数点以色列的百姓。","notes":[]},{"n":5,"t":"他们过约旦河，在迦得谷中、城的右边亚罗珥安营，与雅谢相对。","notes":[]},{"n":6,"t":"他们来到基列，到了他停．合示地，又来到但．雅安，绕到西顿。","notes":["“他停．合示地”：七十士译本的一些抄本是“赫人的加低斯”。"]},{"n":7,"t":"他们来到推罗的堡垒，以及希未人和迦南人的各城，又出来，到犹大尼革夫的别是巴。","notes":["“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”。"]},{"n":8,"t":"他们来回走遍全地，过了九个月又二十天，就回到耶路撒冷。","notes":[]},{"n":9,"t":"约押向王报告百姓的总数：以色列拿刀的勇士有八十万；犹大有五十万人。","notes":[]},{"n":10,"t":"大卫数点百姓以后，心中自责。大卫向耶和华说：“我做这事大大有罪了。耶和华啊，现在求你除掉仆人的罪孽，因我所做的非常愚昧。”","notes":[]},{"n":11,"t":"大卫早晨起来，耶和华的话临到迦得先知，就是大卫的先见，说：","notes":[]},{"n":12,"t":"“你去告诉大卫：‘耶和华如此说：我向你提出三样，随你选择一样，我好降给你。’”","notes":[]},{"n":13,"t":"于是迦得来到大卫那里告诉他，问他：“你要国中有七年的饥荒呢？或是你在敌人面前逃跑，被追赶三个月呢？或是在你国中有三日的瘟疫呢？现在你要考虑思量，我怎样去回覆那差我来的。”","notes":["“七”：七十士译本是“三”；参代上21．12。"]},{"n":14,"t":"大卫对迦得说：“我很为难。我们宁愿落在耶和华的手里，因为他有丰盛的怜悯；我不愿落在人的手里。”","notes":[]},{"n":15,"t":"于是，耶和华降瘟疫给以色列。自早晨到所定的时候，从但直到别是巴，百姓中死了七万人。","notes":[]},{"n":16,"t":"天使向耶路撒冷伸手要毁灭这城的时候，耶和华改变心意，不降那灾难，就对那在百姓中施行毁灭的天使说：“够了！住手吧！”耶和华的使者正在耶布斯人亚劳拿的禾场那里。","notes":[]},{"n":17,"t":"大卫看见那在百姓中施行毁灭的天使，就向耶和华说：“看哪，我犯了罪，行了恶，但这群羊做了什么呢？愿你的手攻击我和我的父家。”","notes":[]},{"n":18,"t":"当日，迦得来到大卫那里，对他说：“你上去，在耶布斯人亚劳拿的禾场上为耶和华立一座坛。”","notes":[]},{"n":19,"t":"大卫就照着迦得的话，照着耶和华所吩咐的上去了。","notes":[]},{"n":20,"t":"亚劳拿观看，看见王和臣仆向他走过来。亚劳拿就出去，脸伏于地，向王下拜。","notes":[]},{"n":21,"t":"亚劳拿说：“我主我王为何来到仆人这里呢？”大卫说：“我要买你这禾场，为耶和华筑一座坛，使瘟疫在百姓中停止。”","notes":[]},{"n":22,"t":"亚劳拿对大卫说：“我主我王，你眼中看为好，就拿去献祭。看，这里有牛可以作燔祭，有打粮的器具和套牛的轭可以当作柴。","notes":[]},{"n":23,"t":"王啊，这一切，亚劳拿都献给王。”亚劳拿又对王说：“愿耶和华－你的神悦纳你。”","notes":[]},{"n":24,"t":"王对亚劳拿说：“不，我一定要按价钱向你买；我不能用白白得来的东西作燔祭献给耶和华－我的神。”大卫就用五十舍客勒银子买了那禾场与牛。","notes":[]},{"n":25,"t":"大卫在那里为耶和华筑了一座坛，献燔祭和平安祭。耶和华垂听了为那地的祈求，瘟疫就在以色列中停止了。","notes":[]}]}},"1KI":{"1":{"heading":"大卫王的晚年","verses":[{"n":1,"t":"大卫王年纪老迈，虽然盖着外袍，仍不够暖和。","notes":[]},{"n":2,"t":"臣仆对他说：“不如为我主我王找一个年轻的少女，侍立在王面前，照顾王，睡在王的怀中，好使我主我王得暖。”","notes":[]},{"n":3,"t":"于是他们在以色列全境寻找美貌的少女，找到了一个书念女子亚比煞，带到王那里。","notes":[]},{"n":4,"t":"这少女极其美貌，她照顾王，伺候王，王却没有与她亲近。","notes":[]},{"n":5,"t":"那时，哈及的儿子亚多尼雅妄自尊大，说：“我要作王”，就为自己预备座车、骑兵，又派五十人在他前头奔跑。","notes":[],"heads":["亚多尼雅谋篡王位"]},{"n":6,"t":"他父亲从来没有责怪他，说：“你为何这么做？”他非常俊美，生在押沙龙之后。","notes":[]},{"n":7,"t":"亚多尼雅与洗鲁雅的儿子约押和亚比亚他祭司商议；他们就顺从亚多尼雅，帮助他。","notes":[]},{"n":8,"t":"但撒督祭司、耶何耶大的儿子比拿雅、拿单先知、示每、利以，以及大卫自己的勇士都不顺从亚多尼雅。","notes":["“利以，以及大卫自己的勇士”：原文另译“他的同伴，大卫自己的勇士”。"]},{"n":9,"t":"亚多尼雅在隐．罗结旁琐希列磐石那里献牛羊、肥犊为祭，请了他的众兄弟，就是王的众儿子，以及所有作王臣仆的犹大人。","notes":[]},{"n":10,"t":"但他没有邀请拿单先知、比拿雅和勇士们，以及他的弟弟所罗门。","notes":[]},{"n":11,"t":"拿单对所罗门的母亲拔示巴说：“哈及的儿子亚多尼雅作王了，你没有听见吗？我们的主大卫却不知道。","notes":[],"heads":["所罗门被立为王"]},{"n":12,"t":"现在，来，我给你出个主意，好保全你和你儿子所罗门的性命。","notes":[]},{"n":13,"t":"你去，进到大卫王那里，对他说：‘我主我王啊，你不是曾向使女起誓说：你儿子所罗门必接续我作王，他必坐在我的王位上吗？亚多尼雅怎么作了王呢？’","notes":[]},{"n":14,"t":"看哪，你还在那里与王说话的时候，我会随后进去，证实你的话。”","notes":[]},{"n":15,"t":"拔示巴进入内室，到王那里。那时，王很老了，书念女子亚比煞正伺候着王。","notes":[]},{"n":16,"t":"拔示巴向王屈身下拜，王说：“你要什么？”","notes":[]},{"n":17,"t":"她对王说：“我主啊，你曾向使女指着耶和华－你的神起誓：‘你儿子所罗门必接续我作王，他必坐在我的王位上。’","notes":[]},{"n":18,"t":"现在，看哪，亚多尼雅作王了，你，我主我王却不知道。","notes":["“你”是根据一些古卷和七十士译本；原文是“现在”。"]},{"n":19,"t":"他献许多牛羊、肥犊为祭，请了王的众儿子和亚比亚他祭司，以及约押元帅，他却没有请王的仆人所罗门。","notes":[]},{"n":20,"t":"但你，我主我王啊，以色列众人的眼目都仰望你，等你告诉他们，在我主我王之后谁坐你的王位。","notes":["“你”：有些古卷和其他古译本是“现在”。"]},{"n":21,"t":"若不然，我主我王与祖先同睡的时候，我和我儿子所罗门必列为罪犯了。”","notes":[]},{"n":22,"t":"看哪，拔示巴还与王说话的时候，拿单先知也进来了。","notes":[]},{"n":23,"t":"有人奏告王说：“看哪，拿单先知来了。”拿单进到王面前，脸伏于地，向王叩拜。","notes":[]},{"n":24,"t":"拿单说：“我主我王，你果真说过‘亚多尼雅必接续我作王，他要坐在我的王位上’吗？","notes":[]},{"n":25,"t":"他今日下去，献了许多牛羊、肥犊为祭，请了王的众儿子和军官们，以及亚比亚他祭司；看哪，他们正在亚多尼雅面前吃喝，说：‘亚多尼雅王万岁！’","notes":[]},{"n":26,"t":"至于我，就是你的仆人，和撒督祭司、耶何耶大的儿子比拿雅、王的仆人所罗门，他都没有请。","notes":[]},{"n":27,"t":"这事果真出于我主我王吗？王却没有告诉仆人们，在我主我王之后谁坐你的王位。”","notes":[]},{"n":28,"t":"大卫王回答说：“召拔示巴到我这里来。”拔示巴就来，站在王面前。","notes":[]},{"n":29,"t":"王起誓说：“我指着救我性命脱离一切苦难的永生的耶和华起誓。","notes":[]},{"n":30,"t":"我既然指着耶和华－以色列的神向你起誓说：你儿子所罗门必接续我作王，他必继承我坐在我的王位上，我今日必这样做。”","notes":[]},{"n":31,"t":"于是，拔示巴屈身，脸伏于地，向王叩拜，说：“我主大卫王万岁！”","notes":[]},{"n":32,"t":"大卫王又说：“召撒督祭司、拿单先知、耶何耶大的儿子比拿雅到我这里来！”他们就都来到王面前。","notes":[]},{"n":33,"t":"王对他们说：“要带领你们主的仆人，让我儿子所罗门骑我自己的骡子，送他下到基训。","notes":[]},{"n":34,"t":"在那里，撒督祭司和拿单先知要膏他作以色列的王；你们也要吹角，说：‘所罗门王万岁！’","notes":[]},{"n":35,"t":"你们要跟随他上来，使他坐在我的王位上，他要接续我作王。我已立他作以色列和犹大的君王。”","notes":[]},{"n":36,"t":"耶何耶大的儿子比拿雅回应王说：“阿们！愿耶和华－我主我王的神这样说。","notes":[]},{"n":37,"t":"耶和华怎样与我主我王同在，愿他照样与所罗门同在，使他的王位比我主大卫王的王位更大。”","notes":[]},{"n":38,"t":"于是，撒督祭司、拿单先知、耶何耶大的儿子比拿雅，以及基利提人和比利提人都下去，让所罗门骑上大卫王的骡子，送他到基训。","notes":[]},{"n":39,"t":"撒督祭司从帐幕中取了盛膏油的角来，膏所罗门。他们就吹角，众百姓都说：“所罗门王万岁！”","notes":[]},{"n":40,"t":"众百姓跟随他上来，吹着笛，大大欢呼，地被他们的声音震裂。","notes":[]},{"n":41,"t":"亚多尼雅和所有的宾客刚吃完，听见这声音；约押听见角声就说：“城中为何有这响声呢？”","notes":[]},{"n":42,"t":"他正说话的时候，看哪，亚比亚他祭司的儿子约拿单来了。亚多尼雅说：“进来吧！你是个贤明的人，必是来报好消息的。”","notes":[]},{"n":43,"t":"约拿单回答亚多尼雅说：“我们的主大卫王已经立所罗门为王了！","notes":[]},{"n":44,"t":"王派撒督祭司、拿单先知、耶何耶大的儿子比拿雅，以及基利提人和比利提人和所罗门一起去，叫他骑上王的骡子。","notes":[]},{"n":45,"t":"撒督祭司和拿单先知已经在基训膏他作王了。他们从那里欢呼着上来，城都震动，这就是你们所听见的声音。","notes":[]},{"n":46,"t":"所罗门也已经登上国度的王位了。","notes":[]},{"n":47,"t":"王的臣仆也来为我们的主大卫王祝福，说：‘愿神使所罗门的名比你的名更尊荣，使他的王位比你的王位更大。’王在床上屈身敬拜，","notes":[]},{"n":48,"t":"王也这样说：‘耶和华－以色列的神是应当称颂的，因他今日赏赐一个人坐在我的王位上，我也亲眼看见了。’”","notes":[]},{"n":49,"t":"亚多尼雅所有的宾客都战兢，起来，各走各路去了。","notes":[]},{"n":50,"t":"亚多尼雅惧怕所罗门，就起来，去抓住祭坛的翘角。","notes":[]},{"n":51,"t":"有人告诉所罗门说：“看哪，亚多尼雅惧怕所罗门王。看哪，他抓住祭坛的翘角，说：‘愿所罗门王先向我起誓，必不用刀杀死仆人。’”","notes":[]},{"n":52,"t":"所罗门说：“他若作贤明的人，连一根头发也不致落在地上；他若作恶，必要死亡。”","notes":[]},{"n":53,"t":"于是所罗门王派人叫亚多尼雅从坛上下来，他就来向所罗门王下拜。所罗门对他说：“你回家去吧！”","notes":[]}]},"2":{"heading":"大卫给所罗门的遗训","verses":[{"n":1,"t":"大卫的死期临近了，就吩咐他儿子所罗门说：","notes":[]},{"n":2,"t":"“我要走世人必走的路了。你当刚强，作大丈夫，","notes":[]},{"n":3,"t":"遵守耶和华－你神所吩咐的，照着摩西律法上所写的行耶和华的道，谨守他的律例、诫命、典章、法度，好让你无论做什么，不拘往何处去，尽都亨通。","notes":[]},{"n":4,"t":"耶和华必成就他所说关于我的话，说：‘你的子孙若谨慎自己的行为，尽心尽意凭信实行在我面前，就不断有人坐以色列的王位。’","notes":[]},{"n":5,"t":"你也知道洗鲁雅的儿子约押向我所做的事，他对付以色列的两个元帅，尼珥的儿子押尼珥和益帖的儿子亚玛撒，杀了他们。他在太平之时，如同战争一般，流这二人的血，把这战争的血染了他腰间束的带和脚上穿的鞋。","notes":[]},{"n":6,"t":"所以你要照你的智慧去做，不让他白发安然下阴间。","notes":[]},{"n":7,"t":"你当恩待基列人巴西莱的众儿子，请他们常与你同席吃饭，因为我躲避你哥哥押沙龙的时候，他们亲近我。","notes":[]},{"n":8,"t":"看哪，在你这里有来自巴户琳的便雅悯人，基拉的儿子示每。我到玛哈念去的那日，他用狠毒的言语咒骂我。后来他却下约旦河迎接我，我就指着耶和华向他起誓说：‘我必不用刀杀死你。’","notes":[]},{"n":9,"t":"但现在你不要以他为无罪。你是有智慧的人，必知道怎样待他，使他白发流血下阴间。”","notes":[]},{"n":10,"t":"大卫与他祖先同睡，葬在大卫城。","notes":[],"heads":["大卫寿终"]},{"n":11,"t":"大卫作以色列王四十年：在希伯仑作王七年，在耶路撒冷作王三十三年。","notes":[]},{"n":12,"t":"所罗门坐他父亲大卫的王位，他的国度非常稳固。","notes":[]},{"n":13,"t":"哈及的儿子亚多尼雅到所罗门的母亲拔示巴那里，拔示巴问他说：“你是为平安来的吗？”他说：“为平安来的。”","notes":[],"heads":["亚多尼雅的死"]},{"n":14,"t":"他又说：“我有话对你说。”拔示巴说：“你说吧。”","notes":[]},{"n":15,"t":"亚多尼雅说：“你知道这国原是归我的，全以色列也都期望我作王。然而，这国反归了我兄弟，因这国归了他是出乎耶和华。","notes":[]},{"n":16,"t":"现在我有一件事求你，请你不要推辞。”拔示巴对他说：“你说吧。”","notes":[]},{"n":17,"t":"他说：“求你请所罗门王把书念女子亚比煞赐我为妻，因他必不拒绝你。”","notes":[]},{"n":18,"t":"拔示巴说：“好，我必为你对王提说。”","notes":[]},{"n":19,"t":"于是，拔示巴来到所罗门王那里，要为亚多尼雅说话。王起来迎接，向她下拜，然后坐在自己的位上，又为王的母亲设一座位，她就坐在王的右边。","notes":[]},{"n":20,"t":"拔示巴说：“我要向你提出一个小小的请求，请你不要回绝我。”王对她说：“母亲，请提出来，我必不回绝你。”","notes":[]},{"n":21,"t":"拔示巴说：“请你把书念女子亚比煞赐给你哥哥亚多尼雅为妻。”","notes":[]},{"n":22,"t":"所罗门王回答母亲说：“为何替亚多尼雅求书念女子亚比煞呢？可以为他求王国吧！他是我的兄长，不但为他，也为亚比亚他祭司和洗鲁雅的儿子约押求吧！”","notes":["“不但为他...求吧!”有古译本是“亚比亚他祭司和洗鲁雅的儿子约押也拥护他。”"]},{"n":23,"t":"所罗门王指着耶和华起誓说：“亚多尼雅讲这话是自己送命，不然，愿神重重惩罚我。","notes":[]},{"n":24,"t":"耶和华坚立我，使我坐在父亲大卫的王位上，照着他所应许的为我建立家室；现在我指着永生的耶和华起誓，亚多尼雅今日必被处死。”","notes":[]},{"n":25,"t":"于是所罗门王派耶何耶大的儿子比拿雅去击杀亚多尼雅，他就死了。","notes":[]},{"n":26,"t":"王对亚比亚他祭司说：“你回亚拿突归自己的田地去吧！你本是该死的，但因你在我父亲大卫面前抬过主耶和华的约柜，又与我父亲同受一切苦难，所以我今日不杀死你。”","notes":[],"heads":["亚比亚他被废和约押的死"]},{"n":27,"t":"所罗门就革除亚比亚他，不让他作耶和华的祭司。这就应验了耶和华在示罗论以利家所说的话。","notes":[]},{"n":28,"t":"虽然约押没有拥护押沙龙，却拥护了亚多尼雅；这消息传到约押那里，他就逃到耶和华的帐幕，抓住祭坛的翘角。","notes":[]},{"n":29,"t":"有人告诉所罗门王：“约押逃到耶和华的帐幕，看哪，他在祭坛的旁边。”所罗门就派耶何耶大的儿子比拿雅，说：“去，杀了他。”","notes":["七十士译本在此加“所罗门派人到约押那里，说：‘你为何要逃到祭坛那里？’约押说：‘因为我怕你，所以我逃到主那里。’”"]},{"n":30,"t":"比拿雅来到耶和华的帐幕，对约押说：“王这样吩咐：‘你出来吧！’”他说：“不，我要死在这里。”比拿雅就去回覆王，说：“约押这样说，他这样回答我。”","notes":[]},{"n":31,"t":"王对他说：“你可以照着他的话去做，杀了他，把他葬了，好叫约押流无辜人血的罪不归在我和我的父家。","notes":[]},{"n":32,"t":"耶和华必使约押的血归到他自己头上，因为他击杀两个比他又公义又良善的人，就是尼珥的儿子以色列的元帅押尼珥和益帖的儿子犹大的元帅亚玛撒，用刀杀了他们，我父亲大卫却不知道。","notes":[]},{"n":33,"t":"这二人的血必归到约押和他后裔头上，直到永远；惟有大卫和他的后裔，以及他的家与王位，必从耶和华那里得平安，直到永远。”","notes":[]},{"n":34,"t":"于是耶何耶大的儿子比拿雅上去，击杀约押，杀死他，把他葬在旷野约押自己的家里。","notes":[]},{"n":35,"t":"王就立耶何耶大的儿子比拿雅作元帅，代替约押，又使撒督祭司代替亚比亚他。","notes":[]},{"n":36,"t":"王派人召示每来，对他说：“你要在耶路撒冷为自己建造房屋，住在那里，不可从那里出来到任何地方去。","notes":[],"heads":["示每的死"]},{"n":37,"t":"你当确实知道，你何日出来过汲沦溪，就必定死！你的血必归到自己头上。”","notes":[]},{"n":38,"t":"示每对王说：“这话很好！我主我王怎样说，仆人必照样做。”于是示每住在耶路撒冷许多日子。","notes":[]},{"n":39,"t":"过了三年，示每的两个奴仆逃到玛迦的儿子迦特王亚吉那里去。有人告诉示每说：“看哪，你的奴仆在迦特。”","notes":[]},{"n":40,"t":"示每起来，备上驴，往迦特到亚吉那里去找他的奴仆，从迦特带他的奴仆回来。","notes":[]},{"n":41,"t":"有人告诉所罗门：“示每出耶路撒冷到迦特去，又回来了。”","notes":[]},{"n":42,"t":"王就派人召示每来，对他说：“我岂不是叫你指着耶和华起誓，并且警告你说‘你当确实知道，你何日出来到任何地方去，就必定死’吗？你也对我说：‘这话很好，我必听从。’","notes":[]},{"n":43,"t":"你为何不遵守你对耶和华的誓言和我吩咐你的命令呢？”","notes":[]},{"n":44,"t":"王又对示每说：“你向我父亲大卫所做的一切恶事，你自己心里都知道，耶和华必使你的罪恶归到你自己的头上。","notes":[]},{"n":45,"t":"但所罗门王必蒙福，大卫的王位必在耶和华面前坚立，直到永远。”","notes":[]},{"n":46,"t":"于是王吩咐耶何耶大的儿子比拿雅，他就出去，击杀示每，示每就死了。这样，国度在所罗门的手中巩固了。","notes":[]}]},"3":{"heading":"所罗门的祈祷","verses":[{"n":1,"t":"所罗门与埃及王法老结亲，娶了法老的女儿，接她进入大卫城，直等到建完了自己的宫和耶和华的殿，以及耶路撒冷周围的城墙。","notes":[]},{"n":2,"t":"当那些日子，百姓仍在丘坛献祭，因为还没有为耶和华的名建殿。","notes":[]},{"n":3,"t":"所罗门爱耶和华，遵行他父亲大卫的律例，只是还在丘坛献祭烧香。","notes":[]},{"n":4,"t":"所罗门王到基遍，在那里献祭，因为基遍有极大的丘坛。所罗门在那坛上献了一千祭牲为燔祭。","notes":[]},{"n":5,"t":"在基遍，耶和华夜间在梦中向所罗门显现；神说：“你愿我赐你什么，你可以求。”","notes":[]},{"n":6,"t":"所罗门说：“你曾向你仆人我父亲大卫大施慈爱，因为他用忠信、公义、正直的心行在你面前。你又为他存留大慈爱，赐他一个儿子坐在他的王位上，正如今日一样。","notes":[]},{"n":7,"t":"现在，耶和华－我的神啊，你使仆人接续我父亲大卫作王；但我是幼小的孩子，不知道应当怎样出入。","notes":[]},{"n":8,"t":"仆人住在你拣选的百姓中，这百姓之多，多得不可点，不可算。","notes":[]},{"n":9,"t":"所以求你赐仆人善于了解的心，可以判断你的百姓，辨别是非。不然，谁能判断你这么多的百姓呢？”","notes":[]},{"n":10,"t":"所罗门因为求这事，就蒙主喜悦。","notes":[]},{"n":11,"t":"神对他说：“你既然求这事，不为自己求寿、求富，也不求灭绝你仇敌的性命，只求能明辨，可以听讼，","notes":[]},{"n":12,"t":"看哪，我会照你的话去做，看哪，我会赐你智慧和明辨的心，在你以前没有像你的，在你以后也没有兴起像你的。","notes":[]},{"n":13,"t":"你没有求的，我也赐给你，就是富足、尊荣，使你在世一切的日子，列王中没有一个能比你的。","notes":[]},{"n":14,"t":"你若遵行我的道，谨守我的律例、诫命，正如你父亲大卫所行的，我必使你长寿。”","notes":[]},{"n":15,"t":"所罗门醒了，看哪，是个梦。他就来到耶路撒冷，站在耶和华的约柜前，献燔祭和平安祭，又为众臣仆摆设宴席。","notes":[]},{"n":16,"t":"那时，有两个妓女来，站在王面前。","notes":[],"heads":["所罗门审疑难的案件"]},{"n":17,"t":"一个妇人说：“我主啊，我和这妇人同住一屋。她在屋子里的时候，我生了一个孩子。","notes":[]},{"n":18,"t":"我生了以后第三天，这妇人也生了。我们是一起的，屋子里除了我们二人之外，再没有别人在屋子里。","notes":[]},{"n":19,"t":"夜间，这妇人的儿子死了，因为她压在她的儿子身上。","notes":[]},{"n":20,"t":"她半夜起来，趁你使女睡着的时候，从我旁边把我儿子抱走，放在她怀里，又把她死的儿子放在我怀里。","notes":[]},{"n":21,"t":"清早，我起来要给我的儿子吃奶，看哪，他死了；早晨我仔细察看他，看哪，他不是我所生的儿子。”","notes":[]},{"n":22,"t":"另一个妇人说：“不！我的儿子是活的，你的儿子是死的。”但这一个说：“不！你的儿子是死的，我的儿子是活的。”她们就在王面前争吵。","notes":[]},{"n":23,"t":"王说：“这妇人说：‘这是我的儿子，他是活的，你的儿子是死的。’那妇人说：‘不！你的儿子是死的，我的儿子是活的。’”","notes":[]},{"n":24,"t":"王就说：“给我拿刀来！”人就把刀拿到王面前来。","notes":[]},{"n":25,"t":"王说：“把活孩子劈成两半，一半给这妇人，一半给那妇人。”","notes":[]},{"n":26,"t":"活孩子的母亲为自己的儿子心急如焚，对王说：“求我主把活孩子给那妇人吧，万不可杀死他！”那妇人说：“这孩子也不归我，也不归你，你们就劈了吧！”","notes":[]},{"n":27,"t":"王回应说：“把活孩子给这妇人，万不可杀死他，因为这妇人是他的母亲。”","notes":[]},{"n":28,"t":"全以色列听见王这样判断，就都敬畏王，因为他们看见他心中有神的智慧，能够断案。","notes":[]}]},"4":{"heading":"所罗门的臣仆","verses":[{"n":1,"t":"所罗门作全以色列的王。","notes":[]},{"n":2,"t":"这些是他的官员：撒督的儿子亚撒利雅作祭司，","notes":[]},{"n":3,"t":"示沙的两个儿子以利何烈、亚希亚作书记，亚希律的儿子约沙法作史官，","notes":[]},{"n":4,"t":"耶何耶大的儿子比拿雅作元帅，撒督和亚比亚他作祭司，","notes":[]},{"n":5,"t":"拿单的儿子亚撒利雅作宰相，拿单的儿子撒布得作祭司和王的顾问，","notes":[]},{"n":6,"t":"亚希煞作管家，亚比大的儿子亚多尼兰掌管服劳役的工人。","notes":[]},{"n":7,"t":"所罗门在全以色列有十二个官员，供给王和王室的食物，每年各人供给一个月。","notes":[]},{"n":8,"t":"这些是他们的名字：在以法莲山区有便．户珥；","notes":[]},{"n":9,"t":"在玛迦斯、沙宾、伯．示麦、以伦．伯．哈南有便．底甲；","notes":[]},{"n":10,"t":"在亚鲁泊有便．希悉，他管理梭哥和希弗全地；","notes":[]},{"n":11,"t":"在多珥山冈有便．亚比拿达，他娶了所罗门的女儿她法为妻；","notes":["“山冈”或译“全境”。"]},{"n":12,"t":"在他纳和米吉多，以及靠近撒拉他拿、耶斯列下边的伯．善全地，从伯．善到亚伯．米何拉直到约缅的另一边有亚希律的儿子巴拿；","notes":[]},{"n":13,"t":"在基列的拉末有便．基别，他管理在基列的玛拿西子孙睚珥的城镇，巴珊的亚珥歌伯地的六十座大城，各有城墙和铜闩；","notes":[]},{"n":14,"t":"在玛哈念有易多的儿子亚希拿达；","notes":[]},{"n":15,"t":"在拿弗他利有亚希玛斯，他也娶了所罗门的一个女儿巴实抹为妻；","notes":[]},{"n":16,"t":"在亚设和亚禄有户筛的儿子巴拿；","notes":[]},{"n":17,"t":"在以萨迦有帕路亚的儿子约沙法；","notes":[]},{"n":18,"t":"在便雅悯有以拉的儿子示每；","notes":[]},{"n":19,"t":"在基列地，就是亚摩利王西宏和巴珊王噩之地，有乌利的儿子基别，他一个官员管理这地 。","notes":["“有乌利的儿子基别，他一个官员管理这地”或译“有乌利的儿子基别。另有一个官员管理这地”；后者的“这地”指犹大。"]},{"n":20,"t":"犹大人和以色列人如同海边的沙那样多，都吃喝快乐。","notes":[],"heads":["所罗门的富强"]},{"n":21,"t":"所罗门统治诸国，从大河到非利士地，直到埃及的边界。所罗门在世的日子，这些国都向他进贡，服事他。","notes":[]},{"n":22,"t":"所罗门每日所用的食物：三十歌珥细面，六十歌珥粗面，","notes":[]},{"n":23,"t":"十头肥牛，二十头草场的牛，一百只羊，还有鹿、羚羊、麃子，以及肥禽。","notes":[]},{"n":24,"t":"所罗门管理整个大河西边，从提弗萨直到迦萨，以及大河西边的诸王，属他的四境尽都平安。","notes":[]},{"n":25,"t":"所罗门在世的日子，从但到别是巴，犹大和以色列各人都在自己的葡萄树下和无花果树下安然居住。","notes":[]},{"n":26,"t":"所罗门拥有给战车用的四万个马棚，还有一万二千名骑兵。","notes":["“四万个”：原文另译“四千个”；参代下9．25。"]},{"n":27,"t":"这些官员各按自己的月份供给所罗门王，以及一切与他同席之人的食物，一无所缺。","notes":[]},{"n":28,"t":"他们各按其分，把给马与快马吃的大麦和干草送到指定的地方去。","notes":[]},{"n":29,"t":"神赐给所罗门极大的智慧和聪明，以及宽阔的心，如同海边的沙。","notes":[],"heads":["所罗门的智慧"]},{"n":30,"t":"所罗门的智慧超过所有东方人的智慧，和埃及人一切的智慧。","notes":[]},{"n":31,"t":"他的智慧胜过万人，胜过以斯拉人以探，以及玛曷的儿子希幔、甲各、达大。他的名声传遍四围的列国。","notes":[]},{"n":32,"t":"他作箴言三千句，诗歌一千零五首。","notes":[]},{"n":33,"t":"他讲论草木，从黎巴嫩的香柏树直到墙上长的牛膝草，又讲论飞禽、走兽、爬行动物和鱼类。","notes":[]},{"n":34,"t":"地上凡曾听过他智慧的君王，都派人来；万民都有人来听所罗门的智慧。","notes":[]}]},"5":{"heading":"所罗门准备建殿","verses":[{"n":1,"t":"推罗王希兰是大卫平生的好友。希兰听见以色列人膏所罗门接续他父亲作王，就派臣仆到他那里。","notes":[]},{"n":2,"t":"所罗门也派人到希兰那里，说：","notes":[]},{"n":3,"t":"“你知道我父亲大卫因四围的战争，不能为耶和华－他神的名建殿，直等到耶和华使仇敌都服在他脚下。","notes":[]},{"n":4,"t":"现在耶和华－我的神使我四围太平，没有仇敌，没有灾祸。","notes":[]},{"n":5,"t":"看哪，我吩咐要为耶和华－我神的名建殿，是照耶和华向我父亲大卫说的：‘我必使你儿子接续你，坐你的王位，他必为我的名建殿。’","notes":[]},{"n":6,"t":"现在，请吩咐人在黎巴嫩为我砍伐香柏木，我的仆人必帮助你的仆人。至于你仆人的工钱，我必照你所定的给你。你知道，在我们中间没有人像西顿人那样擅长砍伐树木。”","notes":[]},{"n":7,"t":"希兰听见所罗门的话，就很高兴，说：“今日耶和华是应当称颂的，因为他赐给大卫一个有智慧的儿子，治理这众多的百姓。”","notes":[]},{"n":8,"t":"希兰送信给所罗门，说：“你派人向我所提的那事，我已听见了；论到香柏木和松木，我必照你一切的心愿去做。","notes":[]},{"n":9,"t":"我的仆人必把这木料从黎巴嫩运到海里，我会把它们扎成筏子浮在海上，运到你告诉我的地方，在那里拆开，你就可以收取；你也要照我的心愿做，把食物给我的家。”","notes":[]},{"n":10,"t":"于是希兰照所罗门的心愿，给他香柏木和松木；","notes":[]},{"n":11,"t":"所罗门给希兰二万歌珥麦子，二十歌珥捣成的油，作他家的食物。所罗门每年都是这样给希兰。","notes":["“二十歌珥”：七十士译本是“二万罢特”；参代下2．10。"]},{"n":12,"t":"耶和华照着所应许的赐智慧给所罗门。希兰与所罗门和平相处，二人彼此立约。","notes":[]},{"n":13,"t":"所罗门王从全以色列挑取服劳役的人，征来的人有三万，","notes":[]},{"n":14,"t":"派他们轮流每月一万人上黎巴嫩去；一个月在黎巴嫩，两个月在家里。亚多尼兰管理他们。","notes":[]},{"n":15,"t":"所罗门有七万扛抬的，八万在山上凿石头的。","notes":[]},{"n":16,"t":"此外，所罗门有三千三百个监督工作的官长，监管百姓做工。","notes":[]},{"n":17,"t":"王下令，他们就凿出又大又贵重的石头来，用以立殿的根基。","notes":[]},{"n":18,"t":"所罗门的工匠和希兰的工匠，以及迦巴勒人，把石头凿好，预备了木料和石头来建殿。","notes":[]}]},"6":{"heading":"所罗门建造圣殿","verses":[{"n":1,"t":"以色列人出埃及地后四百八十年，所罗门作以色列王第四年西弗月，就是二月，他开工建造耶和华的殿。","notes":[]},{"n":2,"t":"所罗门王为耶和华所建的殿，长六十肘，宽二十肘，高三十肘。","notes":[]},{"n":3,"t":"殿的正堂前走廊长二十肘，与殿的宽度一样，殿前宽十肘；","notes":[]},{"n":4,"t":"他为殿做了有框嵌壁式的窗户。","notes":[]},{"n":5,"t":"靠着殿墙，围着外殿和内殿的墙，周围建造了厢房；","notes":[]},{"n":6,"t":"下层宽五肘，中层宽六肘，第三层宽七肘。他在殿墙的周围造坎，免得梁木插入殿墙里。","notes":[]},{"n":7,"t":"殿是用山中凿成的石头建的，所以建殿的时候，锤子、斧子和别样铁器的响声都没有听见。","notes":[]},{"n":8,"t":"在殿右边当中的厢房有门，可以从螺旋梯上到中层，再从中层上到第三层。","notes":[]},{"n":9,"t":"所罗门完成殿的建造。他用香柏木作梁木和横板，遮盖殿顶。","notes":[]},{"n":10,"t":"靠着整个殿所造的厢房，每层高五肘，香柏木的梁板搁在殿的墙坎上。","notes":[]},{"n":11,"t":"耶和华的话临到所罗门，说：","notes":[],"heads":["耶和华的约"]},{"n":12,"t":"“论到你所建的这殿，你若遵行我的律例，谨守我的典章，遵从我的一切诫命，行在其中，我必向你应验我所应许你父亲大卫的话。","notes":[]},{"n":13,"t":"我必住在以色列人中间，并不丢弃我的百姓以色列。”","notes":[]},{"n":14,"t":"所罗门完成殿的建造。","notes":[],"heads":["殿内的设备"]},{"n":15,"t":"他用香柏木板建造殿的内墙，从殿的地到墙顶都贴上木板，又用松木板铺地。","notes":["“墙顶”：原文另译“天花板的椽子”。"]},{"n":16,"t":"他在殿的后部建了一间内殿，长二十肘，从地到墙用香柏木板，作为至圣所。","notes":["“墙”：原文另译“椽子”。"]},{"n":17,"t":"殿，就在内殿的前面，长四十肘。","notes":["“就在内殿的前面”：原文另译“就是至圣所前面的内殿”。"]},{"n":18,"t":"殿里一点石头都不显露，一概用香柏木遮蔽；香柏木上刻着野瓜和绽开的花。","notes":[]},{"n":19,"t":"他在殿的中间预备内殿，在那里安放耶和华的约柜。","notes":[]},{"n":20,"t":"内殿长二十肘，宽二十肘，高二十肘，都贴上纯金。他又用香柏木做坛。","notes":["“内殿”：原文是“内殿的前面”。"]},{"n":21,"t":"所罗门用纯金贴殿内，又用金链子挂在内殿前，内殿也贴上金子。","notes":[]},{"n":22,"t":"整个殿都贴上金子，直到贴满；内殿前的整个坛，也都包上金子。","notes":[]},{"n":23,"t":"他在内殿里用橄榄木做两个基路伯，各高十肘。","notes":[],"heads":["造二基路伯"]},{"n":24,"t":"这基路伯的一个翅膀长五肘，另一个翅膀长五肘，从一个翅膀尖到另一个翅膀尖共有十肘；","notes":[]},{"n":25,"t":"第二个基路伯也是十肘；两个基路伯的尺寸、形状都一样。","notes":[]},{"n":26,"t":"这一个基路伯高十肘，第二个基路伯也是如此。","notes":[]},{"n":27,"t":"他把两个基路伯安在内殿中间。基路伯的翅膀是张开的，这基路伯的一个翅膀挨着这边的墙，第二个基路伯的一个翅膀挨着那边的墙，向内的两个翅膀在殿中间彼此相接。","notes":[]},{"n":28,"t":"二基路伯都包上金子。","notes":[]},{"n":29,"t":"殿周围的墙上全都刻着基路伯、棕树和绽开的花，内外都是如此。","notes":[],"heads":["殿的装饰"]},{"n":30,"t":"殿的地板都贴上金子，内外都是如此。","notes":[]},{"n":31,"t":"他用橄榄木制造内殿的入口、门楣和五边形的门柱。","notes":[]},{"n":32,"t":"在橄榄木做的两门扇上刻着基路伯、棕树和绽开的花，都贴上金子。基路伯和棕树上也洒上金子。","notes":[]},{"n":33,"t":"他又为外殿的入口，用橄榄木制造门柱，是四边形的。","notes":[]},{"n":34,"t":"他用松木做两扇门。这一扇有两叶摺叠，第二扇也有两叶摺叠。","notes":["“叶”：原文是“帷幕”。"]},{"n":35,"t":"上面刻着基路伯、棕树和绽开的花，雕刻物都均匀地贴上金子。","notes":[]},{"n":36,"t":"他又用三层凿成的石头、香柏木一层建造内院。","notes":[]},{"n":37,"t":"所罗门在位第四年西弗月，立了耶和华殿的根基。","notes":[]},{"n":38,"t":"到十一年布勒月，就是八月，殿和一切属殿的都按着样式造成。他建殿共用了七年。","notes":[]}]},"7":{"heading":"所罗门的王宫","verses":[{"n":1,"t":"所罗门为自己建造宫殿，十三年方才建成整座宫殿。","notes":[]},{"n":2,"t":"他建造黎巴嫩林宫，长一百肘，宽五十肘，高三十肘，有四行香柏木柱，柱上有香柏木横梁；","notes":[]},{"n":3,"t":"厢房以上覆盖着香柏木，在四十五根柱子之上，每行十五根。","notes":[]},{"n":4,"t":"窗户有三排，三排的窗与窗相对。","notes":[]},{"n":5,"t":"所有的门和门柱都有四方形的框，共有三行，彼此相对。","notes":[]},{"n":6,"t":"他建造有柱子的厅，长五十肘，宽三十肘。在这前面有走廊，前面有柱子和顶盖。","notes":["“顶盖”或译“台阶”。"]},{"n":7,"t":"他又建造一个有座位的厅，就是审判厅，他在那里审判；这厅的地板从这边到那边都铺上香柏木。","notes":[]},{"n":8,"t":"厅后面的院内有所罗门自己住的宫殿，都用同样的建造方式。所罗门又为所娶法老的女儿建造一座宫，建造方式与这厅一样。","notes":[]},{"n":9,"t":"建造这一切所用的石头都是贵重的，按着尺寸凿成，用锯子里外锯齐；从根基直到房檐，从外头直到大院，都是如此。","notes":[]},{"n":10,"t":"根基是贵重的大石头，有长十肘的，有长八肘的；","notes":[]},{"n":11,"t":"上面有香柏木和按着尺寸凿成的贵重石头。","notes":[]},{"n":12,"t":"大院周围有凿成的石头三层、香柏木板一层，都照耶和华殿的内院和殿的走廊的样式。","notes":[]},{"n":13,"t":"所罗门王派人从推罗把户兰接来。","notes":["“户兰”：原文是“希兰”；下同。"],"heads":["户兰的工作"]},{"n":14,"t":"他是拿弗他利支派中一个寡妇的儿子，父亲是推罗人，是作铜匠的。户兰满有智慧、聪明、技能，善作各样的铜器。他来到所罗门王那里，为王做一切的工。","notes":[]},{"n":15,"t":"户兰制造两根铜柱，一根高十八肘，第二根柱子用绳子量，周围是十二肘；","notes":["“一根...十二肘”：原文另译“一根高十八肘，用绳子量，周围是十二肘，第二根柱子也一样”。"],"heads":["两根铜柱"]},{"n":16,"t":"他做了两个柱顶安在柱上，是用铜铸造的，一个柱顶高五肘，第二个柱顶也高五肘。","notes":[]},{"n":17,"t":"柱子顶上有装饰的网子和编成的链子，一个柱顶有七个，第二个柱顶也有七个。","notes":[]},{"n":18,"t":"他做了柱子，第一根柱子的柱顶上，周围有两行网子在柱子上面遮盖柱顶，第二根柱顶也是这样做。","notes":["“柱子”：有些古卷是“石榴”。","“柱子”是根据许多古卷；原文是“石榴”。"]},{"n":19,"t":"走廊柱子顶上的柱顶高四肘，刻着百合花。","notes":[]},{"n":20,"t":"两根柱子上面有柱顶，柱顶靠近网子的圆凸面上，有石榴的行列环绕着，共二百个，第二个柱顶也是如此。","notes":[]},{"n":21,"t":"他把两根柱子立在殿的走廊前：右边立一根，起名叫雅斤；左边立一根，起名叫波阿斯。","notes":[]},{"n":22,"t":"柱顶上刻着百合花。这样，柱子的工程就完毕了。","notes":[]},{"n":23,"t":"他又铸一个铜海，周围是圆的，直径十肘，高五肘，用绳子量周围是三十肘。","notes":[],"heads":["铜海"]},{"n":24,"t":"铜海边缘下面的周围有野瓜的形状，每肘十个，共两行，绕着铜海，是造铜海的时候铸上去的。","notes":[]},{"n":25,"t":"铜海安在十二头铜牛上：三头向北，三头向西，三头向南，三头向东。铜海安在牛上，牛尾都向内。","notes":[]},{"n":26,"t":"铜海厚一掌，边如杯边，像百合花，容量是二千罢特。","notes":[]},{"n":27,"t":"他用铜制造十个盆座，每座长四肘，宽四肘，高三肘。","notes":[],"heads":["铜座"]},{"n":28,"t":"铜座的造法是这样：周围各有嵌边，嵌边装在框架中。","notes":[]},{"n":29,"t":"装在框架中的嵌边上有狮子和牛，以及基路伯。框架上有小座，狮子和牛的上面和下面有锤成的花纹浮雕。","notes":[]},{"n":30,"t":"每座有四个铜轮和铜轴，它有四个支架在盆以下，这些支架是铸成的，各边都有花纹。","notes":[]},{"n":31,"t":"它的口在柱顶里，向上高一肘，口是圆的，做法如座一样，直径是一肘半，口上也有雕工。嵌边是方形的，不是圆的。","notes":[]},{"n":32,"t":"四个轮子在嵌边以下，轮轴与座相连，每轮高一肘半。","notes":[]},{"n":33,"t":"轮的样式如同车的轮子；轴、辋、辐、毂都是铸成的。","notes":[]},{"n":34,"t":"每个座四边有四个盆形的支架，这些支架是与座从一整块铸成的。","notes":[]},{"n":35,"t":"座顶有圆架，高半肘；座顶有支柱和嵌边，是与座从一整块铸成的。","notes":[]},{"n":36,"t":"他在支柱和嵌边上，每个空处刻上基路伯、狮子和棕树，周围有花纹。","notes":[]},{"n":37,"t":"他按照这样的做法造了十个盆座，它们的铸法、尺寸、样式全都相同。","notes":[]},{"n":38,"t":"他又造十个铜盆，每盆的容量四十罢特，直径四肘。在十个座上，每座安设一盆。","notes":[]},{"n":39,"t":"他把五个安置在殿的右边，五个安置在殿的左边，又把铜海安置在殿的右旁，在东南边。","notes":[]},{"n":40,"t":"户兰又造了盆、铲子和盘子。这样，户兰为所罗门王做完了耶和华殿一切的工：","notes":[],"heads":["圣殿设备清单"]},{"n":41,"t":"两根柱子和柱子顶上两个如碗的柱顶，以及盖着如碗柱顶的两个网子；","notes":[]},{"n":42,"t":"四百个石榴，安在两个网子上，每网两行石榴，盖着柱子上面两个如碗的柱顶；","notes":[]},{"n":43,"t":"十个盆座和其上的十个盆；","notes":[]},{"n":44,"t":"铜海和其下的十二头牛；","notes":[]},{"n":45,"t":"盆、铲子、盘子。户兰给所罗门王为耶和华殿造的这一切器皿都是用光亮的铜，","notes":[]},{"n":46,"t":"是王在约旦平原、疏割和撒拉但中间的泥巴地铸成的。","notes":[]},{"n":47,"t":"所罗门允许这一切器皿不过秤，因为所用的铜太多，重量无法计算。","notes":[]},{"n":48,"t":"所罗门又为耶和华的殿造了各样的器皿：金坛和献供饼的金供桌；","notes":[]},{"n":49,"t":"内殿前的纯金灯台，右边五个，左边五个，以及其上的花、灯盏、灯剪，都是金的；","notes":[]},{"n":50,"t":"纯金的杯、钳子、盘子、勺子 、火盆，以及圣殿的最里面，就是至圣所的门枢和外殿的门枢，都是金的。","notes":[]},{"n":51,"t":"所罗门王做完了耶和华殿一切的工，就把他父亲大卫分别为圣的金银和器皿都带来，放在耶和华殿的库房里。","notes":[],"heads":["殿工告竣"]}]},"8":{"heading":"接约柜入殿","verses":[{"n":1,"t":"那时，所罗门召集以色列的长老、各支派的领袖和以色列人的族长到耶路撒冷，所罗门王那里，要把耶和华的约柜从大卫城，就是锡安，接上来。","notes":[]},{"n":2,"t":"以他念月，就是七月，在节期时，所有的以色列人都聚集到所罗门王那里。","notes":[]},{"n":3,"t":"以色列众长老一来到，祭司就抬起约柜。","notes":[]},{"n":4,"t":"祭司和利未人将耶和华的约柜请上来，又把会幕和会幕一切的圣器皿都带上来。","notes":[]},{"n":5,"t":"所罗门王和聚集到他那里的以色列全会众一同在约柜前献牛羊为祭，多得不可胜数，无法计算。","notes":[]},{"n":6,"t":"祭司将耶和华的约柜请进内殿，就是至圣所，安置在两个基路伯的翅膀底下约柜的地方。","notes":[]},{"n":7,"t":"基路伯张开翅膀在约柜上面的地方，从上面遮住约柜和抬柜的杠。","notes":[]},{"n":8,"t":"这杠很长，从内殿前的圣所可以看见杠头，从外面却看不见。这杠直到今日还在那里。","notes":[]},{"n":9,"t":"约柜里没有别的，只有两块石版，就是以色列人出埃及地，耶和华与他们立约的时候，摩西在何烈山放在那里的。","notes":[]},{"n":10,"t":"祭司从圣所出来的时候，有云充满耶和华的殿，","notes":[]},{"n":11,"t":"祭司因云彩的缘故不能站立供职，因为耶和华的荣光充满了耶和华的殿。","notes":[]},{"n":12,"t":"那时，所罗门说：“耶和华曾说要住在幽暗之处。","notes":["“耶和华...幽暗之处”：七十士译本是“主曾安置太阳在天空，却说要住在幽暗之处”；本句七十士译本放在53节。"]},{"n":13,"t":"我的确为你建了一座雄伟的殿宇，作为你永远居住的地方。”","notes":[]},{"n":14,"t":"王转过脸来为以色列全会众祝福，以色列全会众都站立。","notes":[],"heads":["所罗门向百姓讲话"]},{"n":15,"t":"所罗门说：“耶和华－以色列的神是应当称颂的！因他亲口向我父大卫应许的，也亲手成就了；他曾说：","notes":[]},{"n":16,"t":"‘自从那日我领我百姓以色列出埃及以来，我未曾在以色列各支派中选择一城，在那里为我的名建造殿宇，但我拣选大卫治理我的百姓以色列。’","notes":[]},{"n":17,"t":"我父大卫的心意是要为耶和华－以色列神的名建殿。","notes":[]},{"n":18,"t":"耶和华却对我父大卫说：‘你有心为我的名建殿，这心意是好的；","notes":[]},{"n":19,"t":"但你不可建殿，惟有你亲生的儿子才可为我的名建殿。’","notes":[]},{"n":20,"t":"现在耶和华实现了他所应许的话，使我接续我父大卫坐以色列的王位，正如耶和华所说的，我也为耶和华－以色列神的名建造了这殿。","notes":[]},{"n":21,"t":"我也在那里为约柜预备一处。约柜那里有耶和华的约，就是他领我们列祖出埃及地的时候，与他们所立的约。”","notes":[]},{"n":22,"t":"所罗门当着以色列全会众，站在耶和华的坛前，向天举手，","notes":[],"heads":["所罗门的祷告"]},{"n":23,"t":"说：“耶和华－以色列的神啊，天上地下没有神明可与你相比！你向那些尽心行在你面前的仆人守约施慈爱，","notes":[]},{"n":24,"t":"这约是你向你仆人大卫守的，是你应许他的。你亲口应许，亲手成就，正如今日一样。","notes":[]},{"n":25,"t":"耶和华－以色列的神啊，你向你仆人我父大卫应许说：‘你的子孙若谨慎自己的行为，在我面前行事像你所行的一样，就不断有人在我面前坐以色列的王位。’现在求你信守这话。","notes":[]},{"n":26,"t":"以色列的神啊，现在求你成就向你仆人我父大卫所应许的话。","notes":[]},{"n":27,"t":"“神果真住在地上吗？看哪，天和天上的天尚且不足容纳你，何况我所建的这殿呢？","notes":[]},{"n":28,"t":"惟求耶和华－我的神垂顾仆人的祷告祈求，俯听仆人今日在你面前的祈祷呼求。","notes":[]},{"n":29,"t":"愿你的眼目昼夜看顾这殿，就是你说要作为你名的居所；求你垂听祷告，你仆人向此处的祷告。","notes":[]},{"n":30,"t":"你仆人和你百姓以色列向此处祈祷的时候，求你在你天上的居所垂听，垂听而赦免。","notes":[]},{"n":31,"t":"“人若得罪邻舍，有人强迫他，要他起誓，他来到这殿，在你的坛前起誓，","notes":[]},{"n":32,"t":"求你在天上垂听、处理，向你的仆人施行审判，定恶人有罪，照他所行的报应在他头上；定义人为义，照他的义赏赐他。","notes":[]},{"n":33,"t":"“你的百姓以色列若得罪你，败在仇敌面前，却又归向你，宣认你的名，在这殿里向你祈求祷告，","notes":[]},{"n":34,"t":"求你在天上垂听，赦免你百姓以色列的罪，使他们归回你赐给他们列祖的地。","notes":[]},{"n":35,"t":"“你的百姓若得罪了你，你使天闭塞不下雨；他们若向此处祷告，宣认你的名，因你的惩罚而离开他们的罪，","notes":[]},{"n":36,"t":"求你在天上垂听，赦免你仆人你百姓以色列的罪，将当行的善道教导他们，并降雨在你的地，就是你赐给你百姓为业之地。","notes":[]},{"n":37,"t":"“这地若有饥荒、瘟疫、焚风、霉烂、蝗虫、蚂蚱，或有仇敌围困这地的城门，无论遭遇什么灾祸疾病，","notes":["“焚风”或译“虫害”。","“这地的”：七十士译本和其他古译本是“任何一个”。"]},{"n":38,"t":"你的百姓以色列，或众人或一人，内心知道有祸，向这殿举手，无论祈求什么，祷告什么，","notes":[]},{"n":39,"t":"求你在天上你的居所垂听、赦免、处理。因为你知道人心，惟有你知道世人的心，求你照各人所行的一切待他们，","notes":[]},{"n":40,"t":"使他们在你赐给我们列祖的土地上一生一世敬畏你。","notes":[]},{"n":41,"t":"“论到不属你百姓以色列的外邦人，若为你的名从远方而来，","notes":[]},{"n":42,"t":"他们因听见你的大名和大能的手，以及伸出来的膀臂，来向这殿祷告，","notes":[]},{"n":43,"t":"求你在天上你的居所垂听，照着外邦人向你所求的一切而行，使地上万民都认识你的名，敬畏你，像你的百姓以色列一样，又使他们知道我所建造的是称为你名下的殿。","notes":[]},{"n":44,"t":"“你的百姓若奉你的派遣出去，无论往何处与仇敌争战，他们若向耶和华所选择的城，以及我为你名所建造的这殿祷告，","notes":[]},{"n":45,"t":"求你在天上垂听他们的祷告祈求，为他们伸张正义。","notes":[]},{"n":46,"t":"“你的百姓若得罪你，因为没有人不犯罪，你向他们发怒，把他们交在仇敌面前，掳他们的人把他们带到仇敌之地，或远或近，","notes":[]},{"n":47,"t":"他们若在被掳之地那里回心转意，在掳掠者之地悔改，向你恳求说：‘我们有罪了，我们悖逆了，我们作恶了’；","notes":[]},{"n":48,"t":"他们若在掳他们的仇敌之地尽心尽性归向你，又向自己的地，就是你赐给他们列祖的地和你所选择的城，以及我为你名所建造的这殿祷告，","notes":[]},{"n":49,"t":"求你在天上你的居所垂听他们的祷告祈求，为他们伸张正义，","notes":[]},{"n":50,"t":"饶恕得罪你的子民，赦免他们向你所犯一切的过犯，使他们在掳他们的人面前蒙怜悯。","notes":[]},{"n":51,"t":"因为他们是你的子民，你的产业，是你从埃及，从铁炉中领出来的。","notes":[]},{"n":52,"t":"愿你的眼目看顾仆人和你百姓以色列的祈求；他们无论何时向你呼求，愿你垂听。","notes":[]},{"n":53,"t":"主耶和华啊，你将他们从地上万民中分别出来作你的产业，是照着你领我们列祖出埃及的时候，藉你仆人摩西所应许的。”","notes":[]},{"n":54,"t":"所罗门在耶和华的坛前屈膝跪着，向天举手；他在耶和华面前祷告祈求完毕的时候，就起来，","notes":[],"heads":["为民祝福"]},{"n":55,"t":"站着，大声为以色列全会众祝福，说：","notes":[]},{"n":56,"t":"“耶和华是应当称颂的！因为他照着一切所应许的赐平安给他的百姓以色列，凡藉他仆人摩西应许赐福的话，一句都没有落空。","notes":[]},{"n":57,"t":"愿耶和华－我们的神与我们同在，像与我们列祖同在一样，不撇下我们，不丢弃我们，","notes":[]},{"n":58,"t":"使我们的心归向他，遵行他一切的道，谨守他吩咐我们列祖的诫命、律例、典章。","notes":[]},{"n":59,"t":"愿我在耶和华面前祈求的这些话，昼夜靠近耶和华－我们的神，好让他每日为他仆人和他百姓以色列伸张正义，","notes":[]},{"n":60,"t":"使地上的万民都知道惟独耶和华是神，没有别的了。","notes":[]},{"n":61,"t":"所以你们当向耶和华－我们的神存纯正的心，遵行他的律例，谨守他的诫命，如同今日一样。”","notes":[]},{"n":62,"t":"王和全以色列一同在耶和华面前献祭。","notes":[],"heads":["奉献圣殿"]},{"n":63,"t":"所罗门向耶和华献平安祭，二万二千头牛，十二万只羊。这样，王和全以色列为耶和华的殿行了奉献之礼。","notes":[]},{"n":64,"t":"当日，王因耶和华殿前的铜坛太小，容不下燔祭、素祭和平安祭牲的脂肪，就将耶和华殿前院子的中间分别为圣，在那里献燔祭、素祭和平安祭牲的脂肪。","notes":[]},{"n":65,"t":"那时所罗门守节，从哈马口直到埃及溪谷的以色列众人都与他同在一起，成了一个盛大的会，在耶和华－我们的神面前七日又七日，共十四日。","notes":[]},{"n":66,"t":"第八日，王遣散百姓；他们都为王祝福。他们为耶和华向他仆人大卫和他百姓以色列所施的一切恩惠都心中喜乐，愉快地各回自己的帐棚去了。","notes":[]}]},"9":{"heading":"耶和华再向所罗门显现","verses":[{"n":1,"t":"所罗门建造耶和华的殿和王宫，以及一切所想要建造的都完毕了，","notes":[]},{"n":2,"t":"耶和华第二次向所罗门显现，如先前在基遍向他显现一样。","notes":[]},{"n":3,"t":"耶和华对他说：“我已听了你在我面前的祷告和祈求，将你所建的这殿分别为圣，使我的名永远立在那里；我的眼、我的心也必时常在那里。","notes":[]},{"n":4,"t":"你若以纯正的心和正直行在我面前，效法你父大卫所行的，遵行我一切所吩咐你的，谨守我的律例典章，","notes":[]},{"n":5,"t":"我就必坚固你在以色列国度的王位，直到永远，正如我应许你父大卫说：‘你的子孙必不断有人坐以色列的王位。’","notes":[]},{"n":6,"t":"倘若你们和你们的子孙转去不跟从我，不守我摆在你们面前的诫命律例，去事奉别神，敬拜它们，","notes":[]},{"n":7,"t":"我就必把以色列从我赐给他们的地上剪除，也必从我面前舍弃那为我名所分别为圣的殿，使以色列在万民中成为笑柄，被人讥诮。","notes":[]},{"n":8,"t":"这殿虽然崇高，将来凡经过的人必惊讶，嗤笑，说：‘耶和华为何向这地和这殿如此行呢？’","notes":["“虽然崇高”：有古译本是“必成为废墟”。"]},{"n":9,"t":"人必说：‘因为此地的人离弃领他们祖先出埃及地的耶和华－他们的神，去亲近别神，敬拜事奉它们，所以耶和华使这一切灾祸临到他们。’”","notes":[]},{"n":10,"t":"所罗门建造耶和华殿和王宫这两座殿宇，用了二十年才完成。","notes":[],"heads":["所罗门跟希兰订约"]},{"n":11,"t":"推罗王希兰曾照所罗门所要的资助他香柏木、松木和金子，所罗门王就把加利利地的二十座城给了希兰。","notes":[]},{"n":12,"t":"希兰从推罗出来，察看所罗门给他的城镇，看不顺眼，","notes":[]},{"n":13,"t":"就说：“我兄啊，你给我的是什么城镇呢？”他就给这些城镇起名叫迦步勒地，直到今日。","notes":["“迦步勒”意思是“没有价值”。"]},{"n":14,"t":"希兰曾给所罗门一百二十他连得金子。","notes":[]},{"n":15,"t":"所罗门王挑取服劳役的工人，为要建造耶和华的殿、自己的宫、米罗、耶路撒冷的城墙、夏琐、米吉多和基色。","notes":["“米罗”是音译，指“土堆的防御工事”；本卷书下同。"],"heads":["所罗门其他政绩"]},{"n":16,"t":"先前埃及王法老上来攻取基色，用火焚烧，杀了城内居住的迦南人，把城赐给他的女儿，就是所罗门的妻子，作为嫁妆。","notes":[]},{"n":17,"t":"所罗门建造基色、下伯．和仑、","notes":[]},{"n":18,"t":"巴拉，和位于境内旷野的达莫。","notes":[]},{"n":19,"t":"所罗门建造一切的储货城、战车城、战马城，以及他所想要建造的，在耶路撒冷、黎巴嫩和自己治理全国中的一切建设。","notes":[]},{"n":20,"t":"至于所有剩下的百姓，不属以色列人的亚摩利人、赫人、比利洗人、希未人、耶布斯人，","notes":[]},{"n":21,"t":"那些以色列人在当地不能灭尽的人，所罗门征召他们剩下的后代作服劳役的奴仆，直到今日。","notes":[]},{"n":22,"t":"惟有以色列人，所罗门不使他们作奴仆，而是作他的战士、臣仆、官长、军官、战车长、骑兵长。","notes":[]},{"n":23,"t":"这些是所罗门工程的五百五十个监工，他们在百姓中监管作工的人。","notes":[]},{"n":24,"t":"法老的女儿从大卫城上到所罗门为她建造的宫里。那时，所罗门才建造米罗。","notes":[]},{"n":25,"t":"所罗门每年三次在他为耶和华所筑的坛上献燔祭和平安祭，又在耶和华面前的坛上烧香。这样，他完成了建殿。","notes":[]},{"n":26,"t":"所罗门王在以东地红海边，靠近以禄的以旬．迦别制造船只。","notes":[]},{"n":27,"t":"希兰派他的仆人，就是熟悉航海的船员，与所罗门的仆人一同坐船航海。","notes":[]},{"n":28,"t":"他们到了俄斐，从那里得了四百二十他连得金子，运到所罗门王那里。","notes":[]}]},"10":{"heading":"示巴女王拜访所罗门","verses":[{"n":1,"t":"示巴女王听见所罗门因耶和华的名所得的名声，就来要用难题考问所罗门。","notes":[]},{"n":2,"t":"她带着很多的随从来到耶路撒冷，有骆驼驮着香料、极多金子和宝石。她来到所罗门那里，向他提出心中所有的问题。","notes":[]},{"n":3,"t":"所罗门回答了她所有的问题，没有一个问题太难，王不能向她解答的。","notes":[]},{"n":4,"t":"示巴女王看见所罗门一切的智慧，和他所建造的宫殿，","notes":[]},{"n":5,"t":"席上的食物，坐着的群臣，侍立的仆人，他们的服装，和他的司酒长，以及他在耶和华殿里所献的燔祭，就诧异得神不守舍。","notes":["“他在耶和华...燔祭”或译“他上耶和华殿的台阶”。"]},{"n":6,"t":"她对王说：“我在本国所听到的话，论到你的事和你的智慧是真的！","notes":[]},{"n":7,"t":"我本来不信那些话，及至我来亲眼看见了，看哪，人所告诉我的还不到一半，你的智慧和你的福分超过我所听见的传闻。","notes":[]},{"n":8,"t":"你的人是有福的！你这些仆人常侍立在你面前、听你智慧的话是有福的！","notes":["“你的人”：七十士译本和其他古译本是“你的后妃”。"]},{"n":9,"t":"耶和华－你的神是应当称颂的！他喜爱你，使你坐以色列的王位，因为他永远爱以色列，所以立你作王，使你秉公行义。”","notes":[]},{"n":10,"t":"于是，示巴女王把一百二十他连得金子、极多的香料和宝石送给所罗门王；送来的香料，从来没有像示巴女王送给他的那么多。","notes":[]},{"n":11,"t":"希兰的船只也从俄斐运了金子来，又从俄斐运了许多檀香木和宝石来。","notes":[]},{"n":12,"t":"王用檀香木为耶和华的殿和王宫做栏杆，又为歌唱的人做琴瑟。以后再没有这样的檀香木运进来，也再没有人见过，直到如今。","notes":[]},{"n":13,"t":"所罗门王除了照自己的厚意馈赠示巴女王之外，凡她所提出的一切要求，所罗门王都送给她。于是女王和她臣仆转回，到本国去了。","notes":[]},{"n":14,"t":"所罗门每年所得的金子，重六百六十六他连得；","notes":[],"heads":["所罗门的财富"]},{"n":15,"t":"另外还有来自商人和做生意的商品，以及阿拉伯诸王和各地省长的。","notes":["“商人”：原文直译“商人的人”或“商人的税金”；七十士译本是“臣民的贡品”。"]},{"n":16,"t":"所罗门王用锤出来的金子打成二百面盾牌，每面盾牌用六百舍客勒金子；","notes":[]},{"n":17,"t":"又用锤出来的金子打成三百面小盾牌，每面小盾牌用三弥那金子。王把它们放在黎巴嫩林宫里。","notes":[]},{"n":18,"t":"王又制造一个大的象牙宝座，包上纯金。","notes":[]},{"n":19,"t":"宝座有六层台阶，座的后背是圆的，座位之处两旁有扶手，靠近扶手有两只狮子站立。","notes":[]},{"n":20,"t":"六层台阶上有十二只狮子站立，分站左边和右边；任何国度都没有这样做的。","notes":[]},{"n":21,"t":"所罗门王一切的饮器都是金的，黎巴嫩林宫里所有的器皿都是纯金的。在所罗门的日子，银子算不了什么。","notes":[]},{"n":22,"t":"王有他施船只与希兰的船只一同航海，他施船只每三年一次把金、银、象牙、猿猴、孔雀运回来。","notes":["“孔雀”或译“狒狒”。"]},{"n":23,"t":"所罗门王的财宝与智慧胜过地上的众王。","notes":[]},{"n":24,"t":"全地都求见所罗门的面，要听神放在他心里的智慧。","notes":[]},{"n":25,"t":"他们各带贡物，就是银器、金器、衣服、兵器、香料、马、骡子，每年都有一定的数量。","notes":[]},{"n":26,"t":"所罗门聚集战车骑兵；他有一千四百辆战车，一万二千名骑兵，安置在屯车城，在耶路撒冷的王那里。","notes":[],"heads":["所罗门的兵力和财力"]},{"n":27,"t":"王在耶路撒冷使银子多如石头，香柏木多如谢非拉的桑树。","notes":["“谢非拉”是音译，意思是“低地”。"]},{"n":28,"t":"所罗门的马是从埃及和科威运来的，是王的商人按着定价从科威买来的。","notes":["“埃及”不是南方的埃及，而是美索不达米亚北方的一国；下同。","“科威”可能是“基利亚”，是北方埃及的邻国；下同。"]},{"n":29,"t":"从埃及进口的战车，每辆六百舍客勒银子，马每匹一百五十舍客勒；赫人众王和亚兰诸王的战车和马，也是经由他们的手出口的。","notes":[]}]},"11":{"heading":"所罗门离弃神","verses":[{"n":1,"t":"所罗门王在法老的女儿之外，又宠爱许多外邦女子，就是摩押女子、亚扪女子、以东女子、西顿女子、赫人女子。","notes":[]},{"n":2,"t":"论到这些国的人，耶和华曾吩咐以色列人说：“你们不可跟他们通婚，他们也不可跟你们在一起，因为他们一定会诱惑你们的心去随从他们的神明。”所罗门却为了爱，紧紧跟从他们。","notes":[]},{"n":3,"t":"所罗门娶七百个公主，三百个妃嫔。这些妻妾诱惑他的心。","notes":[]},{"n":4,"t":"所罗门年老的时候，他的妻妾诱惑他的心去随从别神，不像他父亲大卫以纯正的心顺服耶和华－他的神。","notes":[]},{"n":5,"t":"所罗门随从西顿人的女神亚斯她录和亚扪人可憎的米勒公。","notes":[]},{"n":6,"t":"所罗门行耶和华眼中看为恶的事，不像他父亲大卫专心顺从耶和华。","notes":[]},{"n":7,"t":"那时，所罗门为摩押可憎的基抹和亚扪人可憎的摩洛，在耶路撒冷对面的山上建造丘坛。","notes":[]},{"n":8,"t":"他为所有的妻妾，就是那些向自己神明烧香献祭的外邦女子，也是这样做。","notes":[]},{"n":9,"t":"耶和华向所罗门发怒，因为他的心偏离了向他显现两次的耶和华－以色列的神。","notes":[]},{"n":10,"t":"耶和华曾吩咐他这件事，不可随从别神，他却没有遵守耶和华所吩咐的。","notes":[]},{"n":11,"t":"所以耶和华对他说：“你既然是这样，不遵守我所吩咐你守的约和律例，我必定把国度撕裂离开你，将它赐给你的大臣。","notes":[]},{"n":12,"t":"然而，因你父亲大卫的缘故，我不在你的日子行这事，而要从你儿子的手中撕裂这国。","notes":[]},{"n":13,"t":"只是我不撕裂全国，却要因我仆人大卫和我所选择的耶路撒冷，保留一个支派给你的儿子。”","notes":[]},{"n":14,"t":"耶和华使以东人哈达兴起，作所罗门的敌人；他是以东王的后裔。","notes":[],"heads":["所罗门的敌人"]},{"n":15,"t":"大卫在以东的时候，约押元帅上去埋葬阵亡的人，杀了以东所有的男丁。","notes":[]},{"n":16,"t":"约押和以色列众人在以东住了六个月，直到把以东的男丁尽都剪除。","notes":[]},{"n":17,"t":"那时哈达还是幼童；他和他父亲的臣仆，以及几个以东人逃往埃及。","notes":[]},{"n":18,"t":"他们从米甸起行，到了巴兰，再从巴兰带着几个人来到埃及，到埃及王法老那里。法老给他房屋，吩咐给他粮食，又把地赐给他。","notes":[]},{"n":19,"t":"哈达在法老眼前大蒙恩宠，法老就把王后答比匿的妹妹嫁给他。","notes":[]},{"n":20,"t":"答比匿的妹妹给哈达生了一个儿子，叫基努拔。答比匿使基努拔在法老的宫里断奶，基努拔就与法老的众子一同住在法老的宫里。","notes":[]},{"n":21,"t":"哈达在埃及听见大卫与他祖先同睡，约押元帅也死了，就对法老说：“请你让我走，我要回本国去。”","notes":[]},{"n":22,"t":"法老对他说：“你在我这里有什么缺乏？看哪，你竟想要回你本国去！”他说：“我没有缺乏什么，只是恳求王准我回去。”","notes":[]},{"n":23,"t":"神又使以利亚大的儿子利逊兴起，作所罗门的敌人。他曾逃避主人琐巴王哈大底谢。","notes":[]},{"n":24,"t":"大卫击杀琐巴人的时候，利逊召集了一群人，自己作他们的领袖。他们往大马士革，住在那里，在大马士革建立王国。","notes":[]},{"n":25,"t":"所罗门活着的时候，除了哈达为患之外，利逊也作以色列的敌人。他憎恨以色列，作了亚兰人的王。","notes":[]},{"n":26,"t":"尼八的儿子耶罗波安也举起手来攻击王。他是所罗门的臣仆，以法莲支派的洗利达人；他母亲是个寡妇，名叫洗鲁阿。","notes":[],"heads":["神给耶罗波安的应许"]},{"n":27,"t":"他举手攻击王是因先前所罗门建造米罗，修补他父亲大卫城缺口的这件事。","notes":[]},{"n":28,"t":"耶罗波安是个大有才能的人。所罗门见这青年殷勤，就派他监管约瑟家所有服劳役的工人。","notes":[]},{"n":29,"t":"那时，耶罗波安出了耶路撒冷，示罗人亚希雅先知在路上遇见他；亚希雅身上穿着一件新衣。田野中只有他们二人，没有其他的人。","notes":[]},{"n":30,"t":"亚希雅拿起穿在自己身上的新衣，把它撕成十二片，","notes":[]},{"n":31,"t":"对耶罗波安说：“你可以拿十片。耶和华－以色列的神如此说：‘看哪，我必从所罗门手里撕裂这国，把十个支派赐给你。","notes":[]},{"n":32,"t":"我因我仆人大卫和我在以色列众支派中所选择的耶路撒冷城的缘故，仍为所罗门留一个支派。","notes":[]},{"n":33,"t":"因为他们离弃我，敬拜西顿人的女神亚斯她录、摩押的神明基抹和亚扪人的神明米勒公，没有像他父亲大卫一样遵从我的道，行我眼中看为正的事，守我的律例典章。","notes":["“他们”：七十士译本是“他”。"]},{"n":34,"t":"但我不从他手里夺走整个国家，却使他在活着的日子作君王，是因我所拣选的仆人大卫遵守我的诫命律例。","notes":[]},{"n":35,"t":"我必从他儿子手里将王国夺走，赐给你十个支派，","notes":[]},{"n":36,"t":"只留一个支派给他的儿子，使我仆人大卫在我所选择立我名的耶路撒冷城那里，在我面前常有灯光。","notes":[]},{"n":37,"t":"我选你，使你照你心里一切所愿的作王，成为以色列的王。","notes":[]},{"n":38,"t":"你若听从我一切所吩咐你的，遵行我的道，行我眼中看为正的事，谨守我的律例诫命，像我仆人大卫所行的，我就与你同在，为你立坚固的家，像我为大卫所立的一样，将以色列赐给你。","notes":[]},{"n":39,"t":"我必因这事使大卫的后裔遭受患难，但不是永远的。’”","notes":[]},{"n":40,"t":"所罗门想要杀耶罗波安，耶罗波安起身逃往埃及。他到了埃及王示撒那里，就住在埃及，直到所罗门死了。","notes":[]},{"n":41,"t":"所罗门其余的事，凡他所做的和他的智慧，不都写在《所罗门记》上吗？","notes":[],"heads":["所罗门去世"]},{"n":42,"t":"所罗门在耶路撒冷作全以色列的王四十年。","notes":[]},{"n":43,"t":"所罗门与他祖先同睡，葬在他父亲大卫的城里，他儿子罗波安接续他作王。","notes":[]}]},"12":{"heading":"北方支派的反叛","verses":[{"n":1,"t":"罗波安往示剑去，因以色列众人都到了示剑，要立他作王。","notes":[]},{"n":2,"t":"尼八的儿子耶罗波安先前躲避所罗门王，逃往埃及，住在那里。他还在埃及，听见了这事，","notes":["“住在那里...这事”：七十士译本和其他古译本是“他还在埃及，听见了这事，就从埃及回来”。"]},{"n":3,"t":"以色列人派人去请他来。耶罗波安就和以色列全会众来，与罗波安谈话，说：","notes":[]},{"n":4,"t":"“你父亲使我们负重轭，现在求你减轻你父亲所加给我们的苦工和重轭，我们就服事你。”","notes":[]},{"n":5,"t":"罗波安对他们说：“你们走吧，过三天再来见我。”百姓就走了。","notes":[]},{"n":6,"t":"罗波安的父亲所罗门在世的日子，有侍立在他面前的长者，罗波安王和他们商议，说：“你们出个主意，好把话带回给这百姓。”","notes":[]},{"n":7,"t":"他们对他说：“现在王若像仆人一样服事这百姓，用好话回覆他们，他们就永远作王的仆人了。”","notes":[]},{"n":8,"t":"王不采纳长者给他出的主意，却和那些与他一同长大、在他面前侍立的年轻人商议。","notes":[]},{"n":9,"t":"他对他们说：“这百姓对我说：‘你父亲使我们负重轭，求你减轻一些。’你们出个什么主意，我们好把话带回给他们。”","notes":[]},{"n":10,"t":"那些与他一同长大的年轻人对他说：“这百姓对王说：‘你父亲使我们负重轭，求你给我们减轻一些。’王要对他们如此说：‘我的小指头比我父亲的腰还粗呢！","notes":[]},{"n":11,"t":"我父亲使你们负重轭，现在我必使你们负更重的轭！我父亲用鞭子惩罚你们，我要用蝎子惩罚你们！’”","notes":[]},{"n":12,"t":"耶罗波安和众百姓遵照王所说“你们第三天再来见我”的话，第三天来到罗波安那里。","notes":[]},{"n":13,"t":"王严厉地回答百姓，不采纳长者给他出的主意。","notes":[]},{"n":14,"t":"他照着年轻人所出的主意对他们说：“我父亲使你们负重轭，我必使你们负更重的轭！我父亲用鞭子惩罚你们，我却要用蝎子惩罚你们！”","notes":[]},{"n":15,"t":"王不依从百姓，因这事件是出于耶和华，为要应验耶和华藉示罗人亚希雅对尼八的儿子耶罗波安所说的话。","notes":[]},{"n":16,"t":"以色列众人见王不依从他们，百姓就回话给王，说：“我们在大卫中有什么份呢？我们在耶西的儿子中没有产业！以色列啊，回你的帐棚去吧！大卫啊，现在你顾自己的家吧！”于是，以色列人都回自己的帐棚去了；","notes":[]},{"n":17,"t":"至于住犹大城镇的以色列人，罗波安仍作他们的王。","notes":[]},{"n":18,"t":"罗波安王派监管劳役的亚多兰去，以色列众人用石头打他，他就死了。罗波安王急忙上车，逃回耶路撒冷去了。","notes":[]},{"n":19,"t":"这样，以色列背叛大卫家，直到今日。","notes":[]},{"n":20,"t":"以色列众人听见耶罗波安回来了，就派人去请他到会众那里，立他作全以色列的王。除了犹大支派，没有跟从大卫家的。","notes":[]},{"n":21,"t":"罗波安来到耶路撒冷，召集了犹大全家和便雅悯支派的人共十八万，都是精选的战士，要与以色列家打仗，好将王国夺回，归所罗门的儿子罗波安。","notes":[],"heads":["示玛雅的预言"]},{"n":22,"t":"但神的话临到神人示玛雅，说：","notes":[]},{"n":23,"t":"“你去告诉所罗门的儿子犹大王罗波安，犹大和便雅悯全家，以及其余的百姓，说：","notes":[]},{"n":24,"t":"‘耶和华如此说：你们不可上去与你们的弟兄以色列人打仗。你们各自回家去吧！因为这事是出于我。’”众人就听从耶和华的话，遵照耶和华的话回去了。","notes":[]},{"n":25,"t":"耶罗波安在以法莲山区建了示剑，住在其中，又从示剑出去，建了毗努伊勒。","notes":[],"heads":["耶罗波安离弃神"]},{"n":26,"t":"耶罗波安心里说：“现在，这国恐怕仍会归大卫家；","notes":[]},{"n":27,"t":"这百姓若上耶路撒冷去，在耶和华的殿里献祭，他们的心必归向他们的主犹大王罗波安。他们会杀了我，仍归犹大王罗波安。”","notes":[]},{"n":28,"t":"耶罗波安王就筹划，铸造了两个金牛犊，对众百姓说：“你们上耶路撒冷去实在够久了。以色列啊，看哪，这是领你出埃及地的神明。”","notes":[]},{"n":29,"t":"他把一个安置在伯特利，另一个安置在但。","notes":[]},{"n":30,"t":"这事使百姓陷入罪里，因为他们甚至到但去拜那牛犊。","notes":[]},{"n":31,"t":"耶罗波安在一些丘坛建神殿，立不属利未人的平民百姓为祭司。","notes":[]},{"n":32,"t":"耶罗波安定八月十五日为节期，像在犹大的节期一样，自己上坛献祭。他在伯特利这样做，向他所铸的牛犊献祭，又把他所立丘坛的祭司安置在伯特利。","notes":[],"heads":["在伯特利的敬拜被定罪"]},{"n":33,"t":"他在八月十五日，就是他自己心中所定的月份，在伯特利上到自己所造的祭坛；他为以色列人定了一个节期，亲自上坛烧香。","notes":[]}]},"13":{"heading":"伯特利的老先知","verses":[{"n":1,"t":"看哪，有一个神人遵照耶和华的话从犹大来到伯特利。耶罗波安正站在坛旁烧香；","notes":[]},{"n":2,"t":"神人遵照耶和华的话向坛呼叫，说：“坛哪，坛哪！耶和华如此说：‘看哪，大卫家必生一个儿子，名叫约西亚，他必将在你上面烧香的丘坛祭司，宰杀在你上面，人的骨头也必烧在你上面。’”","notes":[]},{"n":3,"t":"当日，神人设个预兆，说：“这是耶和华说的预兆：‘看哪，这坛必破裂，坛上的灰必倾倒出来。’”","notes":[]},{"n":4,"t":"耶罗波安王听见神人向伯特利的坛呼叫的话，就从坛上伸手，说：“拿住他！”王向神人所伸的手却萎缩了，不能弯回。","notes":[]},{"n":5,"t":"坛也破裂了，坛上的灰倾倒出来，正如神人遵照耶和华的话所设的预兆。","notes":[]},{"n":6,"t":"王对神人说：“请你为我祷告，向耶和华－你的神恳求恩惠，使我的手复原。”于是神人向耶和华恳求，王的手就复原了，如平常一样。","notes":[]},{"n":7,"t":"王对神人说：“请你跟我回宫，让你恢复心力，我必给你赏赐。”","notes":[]},{"n":8,"t":"神人对王说：“你就是把你一半的王宫给我，我也不跟你进去，也不在这地方吃饭喝水，","notes":[]},{"n":9,"t":"因为耶和华的话这样吩咐我说：‘不可吃饭喝水，也不可从你去的原路回来。’”","notes":[]},{"n":10,"t":"于是神人从别的路回去，不从他到伯特利来的原路回去。","notes":[]},{"n":11,"t":"有一个老先知住在伯特利，他的儿子来，把神人当日在伯特利所做的一切事和他向王所说的话，都告诉了父亲。","notes":[]},{"n":12,"t":"父亲对他们说：“神人从哪条路去了呢？”他的儿子都看到从犹大来的神人所去的路。","notes":["“看到”：七十士译本是“指给他看”。"]},{"n":13,"t":"老先知吩咐儿子说：“你们为我备驴。”他们备好了驴，他就骑上，","notes":[]},{"n":14,"t":"去追神人，遇见神人坐在橡树底下，就对他说：“你是不是从犹大来的神人？”他说：“是我。”","notes":[]},{"n":15,"t":"老先知对他说：“请你跟我一起回家吃饭。”","notes":[]},{"n":16,"t":"神人说：“我不能跟你回去，与你同行，也不能在这地方跟你一起吃饭喝水，","notes":[]},{"n":17,"t":"因为有耶和华的话吩咐我说：‘你在那里不可吃饭喝水，也不可从你去的原路回来。’”","notes":[]},{"n":18,"t":"老先知对他说：“我也是先知，和你一样。有天使遵照耶和华的话对我说：‘你去带他一同回你的家，给他吃饭喝水。’”老先知在欺骗他。","notes":[]},{"n":19,"t":"于是神人跟老先知回去，在他家里吃饭喝水。","notes":[]},{"n":20,"t":"他们坐席的时候，耶和华的话临到那带神人回来的先知，","notes":[]},{"n":21,"t":"他就对从犹大来的神人宣告说：“耶和华如此说：‘你既违背耶和华的指示，不遵守耶和华－你神的命令，","notes":[]},{"n":22,"t":"反倒回来，在耶和华禁止你吃饭喝水的地方吃了饭喝了水，因此你的尸体必不得葬在你祖先的坟墓里。’”","notes":[]},{"n":23,"t":"神人吃喝完了，老先知为他带回来的先知备驴。","notes":[]},{"n":24,"t":"神人就去了，在路上有只狮子遇见他，把他咬死。他的尸体倒在路上，驴站在尸体旁边，狮子也站在尸体旁边。","notes":[]},{"n":25,"t":"看哪，有人经过，看见尸体倒在路上，狮子站在尸体旁边，就来到老先知所住的城里述说这事。","notes":[]},{"n":26,"t":"那带神人回来的先知听见了，就说：“这是那违背了耶和华指示的神人，所以耶和华把他交给狮子；狮子撕裂他，咬死他，正如耶和华对他说的话。”","notes":[]},{"n":27,"t":"老先知吩咐他儿子说：“你们为我备驴。”他们就备了驴。","notes":[]},{"n":28,"t":"他去了，发现神人的尸体倒在路上，驴和狮子站在尸体旁边，狮子却没有吃尸体，也没有撕裂驴。","notes":[]},{"n":29,"t":"老先知把神人的尸体抬起，驮在驴上，带回自己的城里，要为他哀哭，为他安葬。","notes":[]},{"n":30,"t":"老先知把尸体葬在自己的坟里，为他哀哭，说：“哀哉！我的弟兄啊！”","notes":[]},{"n":31,"t":"安葬之后，老先知对他儿子说：“我死了，你们要把我葬在神人所葬的坟里，使我的尸骨在他的尸骨旁边，","notes":[]},{"n":32,"t":"因为他遵照耶和华的话，指着伯特利的坛和撒玛利亚各城丘坛神殿所宣告的话必定应验。”","notes":[]},{"n":33,"t":"这事以后，耶罗波安仍不离开他的恶道，立平民百姓为丘坛的祭司；凡愿意的，他都分别为圣，立为丘坛的祭司。","notes":[],"heads":["耶罗波安的严重罪行"]},{"n":34,"t":"这事使耶罗波安的家陷入罪里，甚至他的家被剪除，从地面上消灭了。","notes":[]}]},"14":{"heading":"耶罗波安的儿子去世","verses":[{"n":1,"t":"那时，耶罗波安的儿子亚比雅病了。","notes":[]},{"n":2,"t":"耶罗波安对他的妻子说：“你起来改装，使人认不出你是耶罗波安的妻子。你往示罗去，看哪，那里有先知亚希雅，他曾告诉我说，你必作这百姓的王。","notes":[]},{"n":3,"t":"现在你手里要带十个饼、几个薄饼和一瓶蜜到他那里去，他必告诉你，孩子会怎样。”","notes":[]},{"n":4,"t":"耶罗波安的妻子就照样做，起身往示罗去，到了亚希雅的家。亚希雅因年纪老迈，两眼发直，不能看见。","notes":[]},{"n":5,"t":"耶和华对亚希雅说：“看哪，耶罗波安的妻子来问你她儿子的事，因她儿子病了，你当如此如此告诉她。她进来的时候会扮成别的妇人。”","notes":[]},{"n":6,"t":"她刚进门，亚希雅听见她的脚步声，就说：“耶罗波安的妻子，进来吧！你为何扮成别的妇人呢？我奉差遣将凶信告诉你。","notes":[]},{"n":7,"t":"你回去告诉耶罗波安说：‘耶和华－以色列的神如此说：我从百姓中提拔了你，立你作我百姓以色列的君王，","notes":[]},{"n":8,"t":"将大卫家的国撕裂，赐给你，你却不效法我仆人大卫，遵守我的诫命，全心顺从我，行我眼中看为正的事。","notes":[]},{"n":9,"t":"你反倒行恶，比在你之前所有的人更严重；你离开了我，为自己立了别神，铸了偶像，惹我发怒，将我丢在背后。","notes":[]},{"n":10,"t":"因此，看哪，我必使灾祸临到耶罗波安的家，把属耶罗波安的男丁，无论是奴役的、自由的，都从以色列中剪除。我必除灭耶罗波安的家，如同人扫除粪土，直到消灭。","notes":[]},{"n":11,"t":"凡属耶罗波安的人，死在城中的必被狗吃，死在田野的必被空中的鸟吃。这是耶和华说的。’","notes":[]},{"n":12,"t":"你起身回家去吧！你的脚一进城，孩子就死了。","notes":[]},{"n":13,"t":"以色列众人必为他哀哭，为他安葬。凡属耶罗波安的人，只有他可以葬入坟墓，因为在耶罗波安的家中，只有他向耶和华－以色列的神表现出好的行为。","notes":[]},{"n":14,"t":"耶和华必另立一王治理以色列，这一天，他必剪除耶罗波安的家；什么时候呢？现在就是了。","notes":[]},{"n":15,"t":"耶和华必击打以色列，使他们摇动，像水中的芦苇一样，又将他们从耶和华赐给他们列祖的美地上拔出来，分散在大河那边，因为他们造了亚舍拉，惹耶和华发怒。","notes":[]},{"n":16,"t":"因耶罗波安所犯的罪，又因他使以色列陷入罪里，耶和华必将以色列交出来。”","notes":[]},{"n":17,"t":"耶罗波安的妻子起身回去，到了得撒，刚到门槛，孩子就死了。","notes":[]},{"n":18,"t":"以色列众人为他安葬，为他哀哭，正如耶和华藉他仆人亚希雅先知所说的话。","notes":[]},{"n":19,"t":"耶罗波安其余的事，他怎样打仗，怎样作王，看哪，都写在《以色列诸王记》上。","notes":[],"heads":["耶罗波安去世"]},{"n":20,"t":"耶罗波安作王二十二年，就与他祖先同睡，他儿子拿答接续他作王。","notes":[]},{"n":21,"t":"所罗门的儿子罗波安作犹大王。他登基的时候年四十一岁，在耶路撒冷，就是耶和华从以色列众支派中所选择立他名的城，作王十七年。罗波安的母亲名叫拿玛，是亚扪人。","notes":[],"heads":["犹大王罗波安"]},{"n":22,"t":"犹大人行耶和华眼中看为恶的事，以所犯的罪惹动他的妒忌，比他们的祖先所犯的一切更严重。","notes":[]},{"n":23,"t":"因为他们在各高冈上，各青翠树下筑丘坛，立柱像和亚舍拉。","notes":[]},{"n":24,"t":"国中也有男的庙妓。他们效法耶和华在以色列人面前所赶出的外邦人，行一切可憎恶的事。","notes":[]},{"n":25,"t":"罗波安王第五年，埃及王示撒上来攻打耶路撒冷，","notes":[]},{"n":26,"t":"夺了耶和华殿和王宫里的宝物，尽都带走，又夺走所罗门制造的一切金盾牌。","notes":[]},{"n":27,"t":"罗波安王制造铜盾牌代替那些金盾牌，交给看守王宫宫门的护卫长看管。","notes":[]},{"n":28,"t":"每逢王进耶和华的殿，护卫兵就举起这些盾牌；随后仍将盾牌送回护卫室。","notes":[]},{"n":29,"t":"罗波安其余的事，凡他所做的，不都写在《犹大列王记》上吗？","notes":[]},{"n":30,"t":"罗波安与耶罗波安时常交战。","notes":[]},{"n":31,"t":"罗波安与他祖先同睡，与他祖先同葬在大卫城。他母亲名叫拿玛，是亚扪人，他儿子亚比央接续他作王。","notes":["“亚比央”又名“亚比雅”，本卷书下同；参代上3．10，代下12．16。"]}]},"15":{"heading":"犹大王亚比央","verses":[{"n":1,"t":"尼八的儿子耶罗波安王十八年，亚比央登基作犹大王，","notes":[]},{"n":2,"t":"在耶路撒冷作王三年。他母亲名叫玛迦，是押沙龙的女儿。","notes":[]},{"n":3,"t":"亚比央行他父亲从前所犯一切的罪，他的心不像他曾祖父大卫以纯正的心顺服耶和华－他的神。","notes":[]},{"n":4,"t":"然而耶和华－他的神因大卫的缘故，仍使大卫在耶路撒冷有灯光，立他儿子接续他作王，又坚立耶路撒冷。","notes":[]},{"n":5,"t":"因为大卫除了赫人乌利亚那件事，都行耶和华眼中看为正的事，一生没有违背耶和华一切所吩咐的。","notes":[]},{"n":6,"t":"罗波安在世的日子常与耶罗波安交战。","notes":[]},{"n":7,"t":"亚比央其余的事，凡他所做的，不都写在《犹大列王记》上吗？亚比央常与耶罗波安交战。","notes":[]},{"n":8,"t":"亚比央与他祖先同睡，葬在大卫城，他儿子亚撒接续他作王。","notes":[]},{"n":9,"t":"以色列王耶罗波安第二十年，亚撒登基作犹大王，","notes":[],"heads":["犹大王亚撒"]},{"n":10,"t":"在耶路撒冷作王四十一年。他祖母名叫玛迦，是押沙龙的女儿。","notes":[]},{"n":11,"t":"亚撒效法他的高祖父大卫行耶和华眼中看为正的事，","notes":[]},{"n":12,"t":"从国中除去男的庙妓，又除掉他祖先所造的一切偶像。","notes":[]},{"n":13,"t":"他甚至废了他祖母玛迦太后的位，因玛迦造了可憎的亚舍拉。亚撒砍下她的偶像，在汲沦溪边烧了，","notes":[]},{"n":14,"t":"只是丘坛还没有废去。亚撒一生向耶和华存纯正的心。","notes":[]},{"n":15,"t":"亚撒将他父亲所分别为圣与自己所分别为圣的金银和器皿都奉到耶和华的殿里。","notes":[]},{"n":16,"t":"亚撒和以色列王巴沙在世的日子常常交战。","notes":[]},{"n":17,"t":"以色列王巴沙上来攻击犹大，修筑拉玛，不许人从犹大王亚撒那里出入。","notes":[]},{"n":18,"t":"于是亚撒把耶和华殿和王宫府库里所剩下的金银都交在他臣仆手中，派他们到住在大马士革的亚兰王，就是希旬的孙子，他伯利门的儿子便．哈达那里去，说：","notes":[]},{"n":19,"t":"“你父曾与我父立约，我与你也要这样立约。看哪，我把金银送给你作礼物，请你废掉你与以色列王巴沙所立的约，使他从我这里撤退。”","notes":[]},{"n":20,"t":"便．哈达听从了亚撒王，就派遣他的军官去攻打以色列的城镇，攻下了以云、但、亚伯．伯．玛迦、全基尼烈、拿弗他利全地。","notes":[]},{"n":21,"t":"巴沙听见了，就停工不修筑拉玛，仍住在得撒。","notes":[]},{"n":22,"t":"于是亚撒王向犹大众人宣布，不准任何人推辞，吩咐他们运走巴沙修筑拉玛所用的石头和木料。亚撒王用它们来修筑便雅悯的迦巴和米斯巴。","notes":[]},{"n":23,"t":"亚撒其余的事，他英勇的事迹，凡他所做的，以及他所建筑的城镇，不都写在《犹大列王记》上吗？只是亚撒年老的时候患有脚疾。","notes":[]},{"n":24,"t":"亚撒与他祖先同睡，与他祖先同葬在大卫城，他儿子约沙法接续他作王。","notes":[]},{"n":25,"t":"犹大王亚撒第二年，耶罗波安的儿子拿答登基作以色列王二年，","notes":[],"heads":["以色列王拿答"]},{"n":26,"t":"拿答行耶和华眼中看为恶的事，行他父亲所行的道，犯他父亲使以色列陷入罪里的那罪。","notes":[]},{"n":27,"t":"以萨迦人亚希雅的儿子巴沙背叛拿答，在非利士人的基比顿杀了他，那时拿答和以色列众人正围困基比顿。","notes":[],"heads":["以色列王巴沙"]},{"n":28,"t":"犹大王亚撒第三年，巴沙杀了拿答，篡了他的位。","notes":[]},{"n":29,"t":"巴沙一作王就杀了耶罗波安全家，耶罗波安家凡有气息的，一个也没有留下，都杀灭了，正如耶和华藉他仆人示罗人亚希雅所说的话。","notes":[]},{"n":30,"t":"这是因为耶罗波安所犯的罪，他使以色列陷入罪里，激怒了耶和华－以色列的神。","notes":[]},{"n":31,"t":"拿答其余的事，凡他所做的，不都写在《以色列诸王记》上吗？","notes":[]},{"n":32,"t":"亚撒和以色列王巴沙在世的日子常常交战。","notes":[]},{"n":33,"t":"犹大王亚撒第三年，亚希雅的儿子巴沙在得撒登基，作全以色列的王二十四年。","notes":[]},{"n":34,"t":"他行耶和华眼中看为恶的事，行耶罗波安所行的道，犯他使以色列陷入罪里的那罪。","notes":[]}]},"16":{"heading":"以色列王以拉","verses":[{"n":1,"t":"耶和华的话临到哈拿尼的儿子耶户，责备巴沙说：","notes":[]},{"n":2,"t":"“我既从尘埃中提拔你，立你作我百姓以色列的君王，你竟行耶罗波安所行的道，使我的百姓以色列陷入罪里，以他们的罪惹我发怒，","notes":[]},{"n":3,"t":"看哪，我必除尽巴沙和他的家，使你的家像尼八的儿子耶罗波安的家一样。","notes":[]},{"n":4,"t":"凡属巴沙的人，死在城中的必被狗吃，死在田野的必被空中的鸟吃。”","notes":[]},{"n":5,"t":"巴沙其余的事，凡他所做的和他英勇的事迹，不都写在《以色列诸王记》上吗？","notes":[]},{"n":6,"t":"巴沙与他祖先同睡，葬在得撒，他儿子以拉接续他作王。","notes":[]},{"n":7,"t":"耶和华的话临到哈拿尼的儿子耶户先知，责备巴沙和他的家，因他行耶和华眼中看为恶的一切事，以他手所做的惹耶和华发怒，像耶罗波安的家一样，又因他杀了耶罗波安全家。","notes":[]},{"n":8,"t":"犹大王亚撒第二十六年，巴沙的儿子以拉在得撒登基，作以色列王二年。","notes":[]},{"n":9,"t":"他的大臣心利，就是管理他一半战车的军官背叛他。当他在得撒，在王宫的管家亚杂家里喝醉的时候，","notes":[]},{"n":10,"t":"心利进去击杀他，把他杀死，篡了他的位。这是犹大王亚撒第二十七年的事。","notes":[]},{"n":11,"t":"心利一坐上王位就杀了巴沙全家，连他的亲属和朋友，一个男丁也没有留下。","notes":[]},{"n":12,"t":"心利灭绝巴沙全家，正如耶和华藉耶户先知责备巴沙的话。","notes":[]},{"n":13,"t":"这是因为巴沙和他儿子以拉的一切罪，就是他们使以色列陷入罪里的那罪，以虚无的神明惹耶和华－以色列的神发怒。","notes":["“虚无的神明”：原文是“虚无”；26节同。"]},{"n":14,"t":"以拉其余的事，凡他所做的，不都写在《以色列诸王记》上吗？","notes":[]},{"n":15,"t":"犹大王亚撒第二十七年，心利在得撒作王七日。那时军兵正安营围攻非利士人的基比顿。","notes":[],"heads":["以色列王心利"]},{"n":16,"t":"军兵在营中听说心利已经背叛，杀了王，以色列众人当日就在营中立暗利元帅作以色列王。","notes":[]},{"n":17,"t":"暗利率领以色列众人，从基比顿上去，围困得撒。","notes":[]},{"n":18,"t":"心利见城被攻陷，就进了王宫的堡垒，放火焚烧宫殿，自焚而死。","notes":[]},{"n":19,"t":"这是因为他犯罪，行耶和华眼中看为恶的事，行耶罗波安所行的道，犯他使以色列陷入罪里的那罪。","notes":[]},{"n":20,"t":"心利其余的事和他背叛的事，不都写在《以色列诸王记》上吗？","notes":[]},{"n":21,"t":"那时，以色列百姓分为两半：一半随从基纳的儿子提比尼，要拥立他作王；另一半随从暗利。","notes":[],"heads":["以色列王暗利"]},{"n":22,"t":"但随从暗利的百姓胜过随从基纳儿子提比尼的百姓。提比尼死了，暗利就作了王。","notes":[]},{"n":23,"t":"犹大王亚撒第三十一年，暗利登基作以色列王十二年；他在得撒作王六年。","notes":[]},{"n":24,"t":"暗利用二他连得银子向撒玛买了撒玛利亚山，在山上建城，按着山的原主撒玛的名，给所建的城起名叫撒玛利亚。","notes":[]},{"n":25,"t":"暗利行耶和华眼中看为恶的事，比他以前所有的王作恶更严重。","notes":[]},{"n":26,"t":"因为他行了尼八的儿子耶罗波安所行的道，犯他使以色列陷入罪里的那罪，以虚无的神明惹耶和华－以色列的神发怒。","notes":[]},{"n":27,"t":"暗利其余的事，他所做的和所显出的英勇事迹，不都写在《以色列诸王记》上吗？","notes":[]},{"n":28,"t":"暗利与他祖先同睡，葬在撒玛利亚，他儿子亚哈接续他作王。","notes":[]},{"n":29,"t":"犹大王亚撒第三十八年，暗利的儿子亚哈登基作以色列王。暗利的儿子亚哈在撒玛利亚作以色列王二十二年。","notes":[],"heads":["以色列王亚哈"]},{"n":30,"t":"暗利的儿子亚哈行耶和华眼中看为恶的事，比他以前所有的王更严重。","notes":[]},{"n":31,"t":"他犯了尼八的儿子耶罗波安所犯的罪，还当作是小事，又娶了西顿王谒巴力的女儿耶洗别为妻，去事奉巴力，敬拜它，","notes":[]},{"n":32,"t":"又在撒玛利亚建巴力庙，在庙里为巴力筑坛。","notes":[]},{"n":33,"t":"亚哈又造亚舍拉，他所做的惹耶和华－以色列的神发怒，比他以前所有的以色列王更严重。","notes":[]},{"n":34,"t":"亚哈的日子，伯特利人希伊勒重修耶利哥。立根基的时候，他丧了长子亚比兰；安门的时候，他丧了幼子西割，正如耶和华藉嫩的儿子约书亚所说的话。","notes":[]}]},"17":{"heading":"以利亚和旱灾","verses":[{"n":1,"t":"住在基列的提斯比人以利亚对亚哈说：“我指着所事奉永生的耶和华－以色列的神起誓，这几年我若不祷告，必不降露水，也不下雨。”","notes":[]},{"n":2,"t":"耶和华的话临到以利亚，说：","notes":[]},{"n":3,"t":"“你离开这里往东去，躲在约旦河东边的基立溪旁。","notes":[]},{"n":4,"t":"你要喝那溪里的水，我已吩咐乌鸦在那里供养你。”","notes":[]},{"n":5,"t":"于是以利亚去了，他遵照耶和华的话做，去住在约旦河东的基立溪旁。","notes":[]},{"n":6,"t":"乌鸦早上给他叼饼和肉来，晚上也有饼和肉，他又喝溪里的水。","notes":[]},{"n":7,"t":"过了些日子溪水干了，因为雨没有下在地上。","notes":[]},{"n":8,"t":"耶和华的话临到他，说：","notes":[],"heads":["以利亚和撒勒法的寡妇"]},{"n":9,"t":"“你起身到西顿的撒勒法去，住在那里，看哪，我已吩咐那里的一个寡妇供养你。”","notes":[]},{"n":10,"t":"以利亚就起身往撒勒法去。他到了城门，看哪，有一个寡妇在那里捡柴。以利亚呼唤她说：“请你用器皿取点水来给我喝。”","notes":[]},{"n":11,"t":"她去取水的时候，以利亚又呼唤她说：“请你手里也拿点饼来给我。”","notes":[]},{"n":12,"t":"她说：“我指着永生的耶和华－你的神起誓，我没有饼，坛内只有一把面，瓶里只有一点油。看哪，我去找两根柴，带回家为我和我儿子做饼。我们吃了，就等死吧！”","notes":[]},{"n":13,"t":"以利亚对她说：“不要怕！你去照你所说的做吧！只要先为我做一个小饼，拿来给我，然后为你和你的儿子做饼；","notes":[]},{"n":14,"t":"因为耶和华－以色列的神如此说：‘坛内的面必不用尽，瓶里的油必不短缺，直到耶和华使雨降在地上的日子。’”","notes":[]},{"n":15,"t":"妇人就照以利亚的话去做。她和以利亚，以及她家中的人，吃了许多日子。","notes":[]},{"n":16,"t":"坛内的面果然没有用尽，瓶里的油也不短缺，正如耶和华藉以利亚所说的话。","notes":[]},{"n":17,"t":"这事以后，那妇人，就是那家的女主人，她的儿子病了，病得很重，甚至没有气息。","notes":[]},{"n":18,"t":"妇人对以利亚说：“神人哪，我跟你有什么关系，你竟到我这里来，使神记起我的罪，以致我的儿子死了呢？”","notes":[]},{"n":19,"t":"以利亚对她说：“把你儿子交给我。”以利亚就从妇人怀中接过孩子来，抱到他所住的顶楼，放在自己的床上。","notes":[]},{"n":20,"t":"他求告耶和华说：“耶和华－我的神啊，我寄居在这寡妇的家里，你却降祸于她，使她的儿子死了吗？”","notes":[]},{"n":21,"t":"以利亚三次伏在孩子的身上，求告耶和华说：“耶和华－我的神啊，求你使这孩子的生命归回给他吧！”","notes":[]},{"n":22,"t":"耶和华听了以利亚的呼求，孩子的生命归回给他，他就活了。","notes":[]},{"n":23,"t":"以利亚把孩子从楼上抱下来，进了房间交给他母亲，说：“看，你的儿子活了！”","notes":[]},{"n":24,"t":"妇人对以利亚说：“现在我知道你是神人，耶和华藉你口所说的话是真的。”","notes":[]}]},"18":{"heading":"以利亚和巴力的先知","verses":[{"n":1,"t":"过了许多日子，到了第三年，耶和华的话临到以利亚，说：“你去，让亚哈看见你，我要降雨在地面上。”","notes":[]},{"n":2,"t":"以利亚就去，要让亚哈见到他。那时，撒玛利亚的饥荒非常严重。","notes":[]},{"n":3,"t":"亚哈召来他的管家俄巴底。俄巴底非常敬畏耶和华。","notes":[]},{"n":4,"t":"耶洗别杀耶和华先知的时候，俄巴底把一百个先知藏了，每五十人藏在一个洞里，拿饼和水供养他们。","notes":[]},{"n":5,"t":"亚哈对俄巴底说：“我们要走遍这地，到一切水泉旁和一切溪边，或者能找到青草，可以救活马和骡子，免得丧失一些牲畜。”","notes":[]},{"n":6,"t":"于是二人分地巡查，亚哈独自走一路，俄巴底独自走另一路。","notes":[]},{"n":7,"t":"俄巴底在路上时，看哪，以利亚遇见他。俄巴底认出他来，就脸伏于地，说：“你是我主以利亚吗？”","notes":[]},{"n":8,"t":"以利亚对他说：“我是。你去，告诉你主人说：‘看哪，以利亚在这里。’”","notes":[]},{"n":9,"t":"俄巴底说：“仆人犯了什么罪，你竟要把我交在亚哈手里，使他杀我呢？","notes":[]},{"n":10,"t":"我指着永生的耶和华－你的神起誓，无论哪一邦哪一国，我主都派人去找你。若他们说：‘不在这里’，他就叫那邦那国的人起誓说，他们实在找不到你。","notes":[]},{"n":11,"t":"现在你说：‘你去告诉你主人说，看哪，以利亚在这里’；","notes":[]},{"n":12,"t":"恐怕我一离开你，耶和华的灵就把你提到我所不知道的地方去。这样，我去告诉亚哈，他若找不到你，就必杀我。仆人是自幼敬畏耶和华的。","notes":[]},{"n":13,"t":"耶洗别杀耶和华先知的时候，我把耶和华的一百个先知藏了，每五十人藏在一个洞里，拿饼和水供养他们，难道没有人把我做的这事告诉我主吗？","notes":[]},{"n":14,"t":"现在你说：‘你去告诉你主人说，看哪，以利亚在这里’，他一定会杀我。”","notes":[]},{"n":15,"t":"以利亚说：“我指着所事奉永生的万军之耶和华起誓，我今日要让亚哈见到我。”","notes":[]},{"n":16,"t":"于是俄巴底去迎见亚哈，告诉他这事。亚哈就去见以利亚。","notes":[]},{"n":17,"t":"亚哈见了以利亚，就说：“真的是你吗？你这使以色列遭殃的人！”","notes":[]},{"n":18,"t":"以利亚说：“使以色列遭殃的不是我，而是你和你的父家，因为你们离弃耶和华的诫命，去随从巴力。","notes":["“耶和华的诫命”：七十士译本是“你们的主神”。"]},{"n":19,"t":"现在你要派人去召集以色列众人，以及耶洗别所供养的四百五十个巴力的先知和四百个亚舍拉的先知，叫他们都上迦密山到我这里来。”","notes":[]},{"n":20,"t":"亚哈就派人到以色列众人那里，召集先知上迦密山。","notes":[]},{"n":21,"t":"以利亚近前来对众百姓说：“你们心持二意要到几时呢？如果耶和华是神，就当顺从耶和华；如果是巴力，就当顺从巴力。”百姓一言不答。","notes":[]},{"n":22,"t":"以利亚对百姓说：“作耶和华先知的只剩下我一个；巴力的先知却有四百五十人。","notes":[]},{"n":23,"t":"请给我们两头牛犊，巴力的先知可以为自己挑选一头牛犊，切成小块，放在柴上，不要点火；我也预备一头牛犊放在柴上，也不点火。","notes":[]},{"n":24,"t":"你们求告你们神明的名，我也求告耶和华的名。那应允祷告降火的就是神。”众百姓回答说：“好主意。”","notes":[]},{"n":25,"t":"以利亚对巴力的先知说：“因为你们人多，先挑选一头牛犊，预备好了，求告你们神明的名，却不要点火。”","notes":[]},{"n":26,"t":"他们把所给他们的牛犊预备好了，从早晨到中午，求告巴力的名说：“巴力啊，求你应允我们！”却没有声音，也没有回应。他们就在所筑的坛四围蹦跳。","notes":[]},{"n":27,"t":"到了正午，以利亚嘲笑他们，说：“大声求告吧！因为它是神明，它或许在默想，或许正忙着，或许在路上，或许在睡觉，它该醒过来了。”","notes":["“正忙着”或译“在大解”。"]},{"n":28,"t":"他们大声求告，按着他们的仪式，用刀枪刺割自己，直到浑身流血。","notes":[]},{"n":29,"t":"中午过去了，他们狂呼乱叫，直到献晚祭的时候，却没有声音，没有回应的，也没有理睬的。","notes":[]},{"n":30,"t":"以利亚对众百姓说：“你们到我这里来。”众百姓就到他那里，他把那已经毁坏了的耶和华的坛修好。","notes":[]},{"n":31,"t":"以利亚按照雅各子孙支派的数目，取了十二块石头；耶和华的话曾临到雅各，说：“你的名要叫以色列。”","notes":[]},{"n":32,"t":"以利亚用这些石头为耶和华的名筑一座坛，在坛的四围挖沟，可容纳二细亚谷种。","notes":[]},{"n":33,"t":"他又在坛上摆好了柴，把牛犊切成小块放在柴上，说：“你们用四个桶盛满水，倒在燔祭和柴上。”","notes":[]},{"n":34,"t":"他又说：“倒第二次。”他们就倒第二次。他又说：“倒第三次。”他们就倒第三次。","notes":[]},{"n":35,"t":"水流到坛的四围，沟里也满了水。","notes":[]},{"n":36,"t":"到了献晚祭的时候，先知以利亚近前来，说：“耶和华－亚伯拉罕、以撒、以色列的神啊，求你今日使人知道你是以色列的神，我是你的仆人，我遵照你的话做这一切事。","notes":[]},{"n":37,"t":"求你应允我，耶和华啊，应允我，使这百姓知道你－耶和华是神，是你叫他们回心转意的。”","notes":[]},{"n":38,"t":"于是，耶和华降下火来，烧尽燔祭、木柴、石头、尘土，又烧干了沟里的水。","notes":[]},{"n":39,"t":"众百姓看见了，就脸伏于地，说：“耶和华是神！耶和华是神！”","notes":[]},{"n":40,"t":"以利亚对他们说：“拿住巴力的先知，不让任何人逃走！”众人就拿住他们。以利亚带他们到基顺河边，在那里杀了他们。","notes":[]},{"n":41,"t":"以利亚对亚哈说：“你现在可以上去吃喝，因为有暴雨的响声了。”","notes":[],"heads":["旱灾停止"]},{"n":42,"t":"亚哈就上去吃喝。以利亚上了迦密山顶，屈身在地，把脸伏在两膝之中。","notes":[]},{"n":43,"t":"他对仆人说：“你上去，向海观看。”仆人就上去观看，说：“没有什么。”以利亚说：“你再去。”如此七次。","notes":[]},{"n":44,"t":"第七次，仆人说：“看哪，有一小片云从海里上来，好像人的手掌那么大。”以利亚说：“你上去告诉亚哈，当套车下去，免得被雨阻挡。”","notes":[]},{"n":45,"t":"霎时间，天因风云黑暗，降下大雨。亚哈就坐上车，往耶斯列去了。","notes":[]},{"n":46,"t":"耶和华的手按在以利亚身上，他就束上腰，奔在亚哈前头，一路到耶斯列。","notes":[]}]},"19":{"heading":"以利亚在何烈山上","verses":[{"n":1,"t":"亚哈把以利亚一切所做的和他用刀杀众先知的事都告诉耶洗别。","notes":[]},{"n":2,"t":"耶洗别就派使者到以利亚那里，说：“明日约这时候，我若不使你的性命像那些人的性命一样，愿神明重重惩罚我。”","notes":[]},{"n":3,"t":"以利亚害怕，就起来逃命，到了犹大的别是巴，把仆人留在那里。","notes":["“害怕”是根据一些古卷和七十士译本；原文是“看见”。"]},{"n":4,"t":"他自己在旷野走了一日的路程，来到一棵罗腾树下，就坐在那里求死，说：“耶和华啊，现在够了！求你取我的性命吧，因为我不比我的祖先好。”","notes":["“罗腾”是音译，小树名，松类；下同。"]},{"n":5,"t":"他躺在罗腾树下睡着了。看哪，有一个天使拍他，对他说：“起来吃吧！”","notes":[]},{"n":6,"t":"他观看，看哪，头旁有烧热的石头烤的饼和一壶水，他就吃了喝了，又再躺下。","notes":[]},{"n":7,"t":"耶和华的使者回来，第二次拍他，说：“起来吃吧！因为你要走的路很远。”","notes":[]},{"n":8,"t":"他就起来吃了喝了，仗着这饮食的力走了四十昼夜，到了神的山，就是何烈山。","notes":[]},{"n":9,"t":"他在那里进了一个洞，在洞中过夜。看哪，耶和华的话临到他，说：“以利亚，你在这里做什么？”","notes":[]},{"n":10,"t":"他说：“我为耶和华－万军之神大发热心，因为以色列人背弃了你的约，毁坏了你的坛，用刀杀了你的先知，只剩下我一人，他们还要追杀我。”","notes":[]},{"n":11,"t":"耶和华说：“你出来站在山上，在耶和华面前。”看哪，耶和华从那里经过。在耶和华面前有烈风大作，山崩石裂，耶和华却不在风中；风后有地震，耶和华也不在其中；","notes":[]},{"n":12,"t":"地震后有火，耶和华也不在火中；火以后，有轻微细小的声音。","notes":[]},{"n":13,"t":"以利亚听见，就用外衣蒙脸，出来站在洞口。听啊，有声音向他说：“以利亚，你在这里做什么？”","notes":[]},{"n":14,"t":"他说：“我为耶和华－万军之神大发热心，因为以色列人背弃了你的约，毁坏了你的坛，用刀杀了你的先知，只剩下我一人，他们还要追杀我。”","notes":[]},{"n":15,"t":"耶和华对他说：“去吧，从原路回去，往大马士革的旷野去。到了那里，你要膏哈薛作亚兰王，","notes":[]},{"n":16,"t":"又膏宁示的孙子耶户作以色列王，并膏亚伯．米何拉人沙法的儿子以利沙作先知接续你。","notes":[]},{"n":17,"t":"将来逃过哈薛之刀的，必被耶户所杀；逃过耶户之刀的，必被以利沙所杀。","notes":[]},{"n":18,"t":"但我在以色列中留下七千人，是未曾向巴力屈膝，未曾亲吻巴力的。”","notes":[]},{"n":19,"t":"于是，以利亚离开那里走了，遇见沙法的儿子以利沙；他正在耕田，在他前头有十二对牛，自己赶着第十二对。以利亚经过他，把自己的外衣搭在他身上。","notes":[],"heads":["以利沙蒙选召"]},{"n":20,"t":"以利沙就离开牛，跑到以利亚那里，说：“请你让我先与父母吻别，然后我就跟随你。”以利亚对他说：“因我对你所做的事，你去吧，然后回来。”","notes":["“因我...回来。”或译“你去吧，然后回来，我向你做了什么呢？”"]},{"n":21,"t":"以利沙离开他回去，宰了一对牛，用套牛的器具煮肉给百姓吃，随后就起身跟随以利亚，服事他。","notes":[]}]},"20":{"heading":"与亚兰人争战","verses":[{"n":1,"t":"亚兰王便．哈达召集他的全军，率领三十二个王，带着马和战车，上来围困撒玛利亚，要攻打它。","notes":[]},{"n":2,"t":"他派使者进城到以色列王亚哈那里，对他说：“便．哈达如此说：","notes":[]},{"n":3,"t":"‘你的金银都要归我，你妻妾儿女中最美的也要归我。’”","notes":[]},{"n":4,"t":"以色列王回答说：“我主我王啊，就照着你的话，我和我所有的都归你。”","notes":[]},{"n":5,"t":"使者又来说：“便．哈达如此说：‘我已派人到你那里，要你把你的金银、妻妾、儿女都归我。’","notes":[]},{"n":6,"t":"但明日约在这时候，我还要派臣仆到你那里，搜查你的家和你仆人的家，你眼中一切所喜爱的都由他们的手拿走。”","notes":[]},{"n":7,"t":"以色列王召了国内所有的长老来，说：“你们要知道，看，这人是来找麻烦的！他派人到我这里来，要我的妻妾、儿女和金银，我并没有拒绝他。”","notes":[]},{"n":8,"t":"所有的长老和众百姓对王说：“不要听从他，也不要答应他。”","notes":[]},{"n":9,"t":"以色列王对便．哈达的使者说：“你们告诉我主我王说：‘王头一次派人向仆人所要的一切，仆人都依从，但这事我不能依从。’”使者就去回覆便．哈达。","notes":[]},{"n":10,"t":"便．哈达又派人到亚哈那里，说：“撒玛利亚的尘土若足够跟从我的军兵每人手拿一把，愿神明重重惩罚我！”","notes":[]},{"n":11,"t":"以色列王回答说：“你们告诉他说，‘刚束上腰带的，不要像已卸下的那样夸口。’”","notes":[]},{"n":12,"t":"便．哈达和诸王正在帐幕里喝酒，听见这话，就对他臣仆说：“摆阵吧！”他们就摆阵攻城。","notes":[]},{"n":13,"t":"看哪，一个先知靠近以色列王亚哈，说：“耶和华如此说：‘这一大群人你看见了吗？看哪，今日我必把他们交在你手里，你就知道我是耶和华。’”","notes":[]},{"n":14,"t":"亚哈说：“藉着谁呢？”他说：“耶和华如此说：‘藉着跟从省长的年轻人。’”亚哈说：“谁要开战呢？”他说：“你！”","notes":[]},{"n":15,"t":"于是亚哈数点跟从省长的年轻人，共二百三十二名，然后又数点以色列的众军兵，共七千名。","notes":[]},{"n":16,"t":"中午，他们出了城；便．哈达和帮助他的三十二个王正在帐幕里畅饮。","notes":[]},{"n":17,"t":"跟从省长的年轻人先出城。便．哈达派人去，他们回报说：“有人从撒玛利亚出来了。”","notes":[]},{"n":18,"t":"他说：“他们若为求和出来，要活捉他们，若为打仗出来，也要活捉他们。”","notes":[]},{"n":19,"t":"跟从省长的年轻人，和跟随他们的军兵，都出了城，","notes":[]},{"n":20,"t":"各人遇见敌人就击杀。亚兰人逃跑，以色列人追赶他们；亚兰王便．哈达骑着马和骑兵一同逃跑。","notes":[]},{"n":21,"t":"以色列王出城攻击马和战车，大大击杀亚兰人。","notes":["“攻击”：七十士译本是“掳获一切的”。"]},{"n":22,"t":"那先知靠近以色列王，对他说：“去吧，你当自强，看清楚，也要知道你所要做的事，因为再过一年，亚兰王会上来攻击你。”","notes":[]},{"n":23,"t":"亚兰王的臣仆对他说：“他们的神是山神，所以他们胜过我们。但在平原与他们打仗，我们一定胜过他们。","notes":[],"heads":["亚兰人第二次来犯"]},{"n":24,"t":"王当做这样的事，把诸王革去，派军官代替他们，","notes":[]},{"n":25,"t":"又照着王丧失军兵的数目，再招募一支军队，马补马，车补车。然后在平原与他们打仗，我们一定胜过他们。”王就听臣仆的话，照样去做。","notes":[]},{"n":26,"t":"过了一年，便．哈达果然召集亚兰人上亚弗去，要与以色列人打仗。","notes":[]},{"n":27,"t":"以色列人也召集军兵，预备食物，去迎战亚兰人。 以色列人对着他们安营，好像两小群的山羊；亚兰人却布满了地面。","notes":[]},{"n":28,"t":"有神人靠近，对以色列王说：“耶和华如此说：‘亚兰人既说我－耶和华是山神，不是平原之神，我必将这一大群人全都交在你手中，你们就知道我是耶和华。’”","notes":[]},{"n":29,"t":"以色列人与亚兰人相对安营七日，到第七日两军开战。那一日以色列人杀了亚兰的十万步兵，","notes":[]},{"n":30,"t":"其余的都逃向亚弗，到了城里，城墙倒塌，压死了剩下的二万七千人。便．哈达也逃入城内，藏在严密的内室里。","notes":[]},{"n":31,"t":"他的臣仆对他说：“看哪，我们听说以色列家的王都是仁慈的王；让我们腰束麻布，头套绳索，出去到以色列王那里，也许他会存留王的性命。”","notes":[]},{"n":32,"t":"于是他们腰束麻布，头套绳索，来到以色列王那里，说：“王的仆人便．哈达说：‘求王饶我一命。’”亚哈说：“他还活着吗？他是我的兄弟。”","notes":[]},{"n":33,"t":"这些人正在探测吉凶，就立即抓住他的话说：“便．哈达是王的兄弟！”王说：“你们去请他来。”便．哈达出来到王那里，王就请他上车。","notes":[]},{"n":34,"t":"便．哈达对王说：“我父从你父那里所夺的城镇，我必归还给你。你可以在大马士革为你自己设立街市，像我父在撒玛利亚所设立的一样。”亚哈说：“我照此立约，放你回去。”王就与他立约，放了他。","notes":[]},{"n":35,"t":"有一个人是先知的门徒，遵照耶和华的话对他同伴说：“你打我吧！”那人不肯打他。","notes":[],"heads":["先知责亚哈纵敌"]},{"n":36,"t":"他就对那人说：“你既不听从耶和华的话，看哪，你一离开我，必有狮子咬死你。”那人一离开他，果然遇见狮子，把他咬死了。","notes":[]},{"n":37,"t":"先知的门徒又遇见一个人，对他说：“你打我吧！”那人就打他，把他打伤。","notes":[]},{"n":38,"t":"那先知就去了，用头巾蒙眼，改了装，在路旁等候王。","notes":[]},{"n":39,"t":"王从那里经过，他向王呼叫说：“仆人出战的时候，看哪，有人转过来，带了一个人到我这里来，说：‘你要看守这人，若他真的失踪了，你的性命必代替他的性命，否则，你就要交出一他连得银子来。’","notes":[]},{"n":40,"t":"仆人正在到处忙碌的时候，那人就不见了。”以色列王对他说：“你自己决定了，就必照样判你。”","notes":[]},{"n":41,"t":"他急忙除掉蒙眼的头巾，以色列王就认出他是一个先知。","notes":[]},{"n":42,"t":"他对王说：“耶和华如此说：‘因你把我决定要消灭的人从你手中放走，所以你的命必代替他的命，你的百姓必代替他的百姓。’”","notes":[]},{"n":43,"t":"于是以色列王生气，忧闷地回撒玛利亚，到自己的宫去了。","notes":[]}]},"21":{"heading":"拿伯的葡萄园","verses":[{"n":1,"t":"这些事以后，又有一事。耶斯列人拿伯在耶斯列有一个葡萄园，靠近撒玛利亚，亚哈王的宫。","notes":[]},{"n":2,"t":"亚哈对拿伯说：“把你的葡萄园给我作菜园，因为它靠近我的宫，我就把更好的葡萄园换给你。你若要银子，我就按着价钱给你。”","notes":[]},{"n":3,"t":"拿伯对亚哈说：“耶和华不准我把我祖先留下的产业给你。”","notes":[]},{"n":4,"t":"亚哈因耶斯列人拿伯说“我不把我祖先留下的产业给你”，就生气，忧闷地回宫，躺在床上，脸转向内，也不吃饭。","notes":[]},{"n":5,"t":"耶洗别王后来对他说：“你为什么心里这样生气，不吃饭呢？”","notes":[]},{"n":6,"t":"他对王后说：“我向耶斯列人拿伯说：‘把你的葡萄园按价钱卖给我，或是你愿意，我可以把别的葡萄园换给你。’他却说：‘我不把我的葡萄园给你。’”","notes":[]},{"n":7,"t":"耶洗别王后对王说：“你现在是不是治理以色列国呢？只管起来，心里畅畅快快地吃饭，我会把耶斯列人拿伯的葡萄园给你。”","notes":[]},{"n":8,"t":"于是王后以亚哈的名义写信，盖上王的印，把信送给那些与拿伯同城居住的长老和贵族。","notes":[]},{"n":9,"t":"她在信上写着说：“你们当宣告禁食，叫拿伯坐在百姓的高位上，","notes":[]},{"n":10,"t":"又叫两个无赖坐在拿伯对面，作证告他说：‘你诅咒了神和王。’然后把他拉出去用石头打死。”","notes":[]},{"n":11,"t":"那些与拿伯同城居住的长老和贵族，照耶洗别送给他们的信去做。正如她送的信上所写，","notes":[]},{"n":12,"t":"他们宣告禁食，叫拿伯坐在百姓的高位上。","notes":[]},{"n":13,"t":"有两个无赖来，坐在拿伯对面。无赖当着百姓作证告他说：“拿伯诅咒神和王了！”众人就把他拉到城外，用石头打他，他就死了。","notes":[]},{"n":14,"t":"于是他们派人到耶洗别那里，说：“拿伯被石头打死了。”","notes":[]},{"n":15,"t":"耶洗别听见拿伯被石头打死，就对亚哈说：“你起来，去取得耶斯列人拿伯不肯出价卖给你的葡萄园吧！因为拿伯不在了，他已经死了。”","notes":[]},{"n":16,"t":"亚哈听见拿伯死了，就起来，下去要取得耶斯列人拿伯的葡萄园。","notes":[]},{"n":17,"t":"耶和华的话临到提斯比人以利亚，说：","notes":[]},{"n":18,"t":"“你起来，去见在撒玛利亚的以色列王亚哈。看哪，他下去要取得拿伯的葡萄园，他正在那园里。","notes":[]},{"n":19,"t":"你要对他说：‘耶和华如此说：你杀了人，还要取得他的产业吗？’又要对他说：‘耶和华如此说：狗在何处舔拿伯的血，狗也必在何处舔你的血。’”","notes":[]},{"n":20,"t":"亚哈对以利亚说：“我的仇敌啊，你找到我了吗？”他说：“我找到你了。因为你出卖自己，行了耶和华眼中看为恶的事。","notes":[]},{"n":21,"t":"耶和华说：‘看哪，我必使灾祸临到你，把你除灭。以色列中凡属亚哈的男丁，无论是奴役的、自由的，我都要剪除。","notes":[]},{"n":22,"t":"我必使你的家像尼八的儿子耶罗波安的家，又像亚希雅的儿子巴沙的家，因为你惹我发怒，又使以色列陷入罪里。’","notes":[]},{"n":23,"t":"论到耶洗别，耶和华说：‘狗必在耶斯列的城郭吃耶洗别。","notes":["“城郭”：有些古卷和古译本是“田间”。"]},{"n":24,"t":"凡属亚哈的人，死在城中的必被狗吃，死在田野的必被空中的鸟吃。’”","notes":[]},{"n":25,"t":"（只是从来没有像亚哈的，因他受耶洗别王后的唆使，出卖自己，行了耶和华眼中看为恶的事。","notes":[]},{"n":26,"t":"他行了最可憎的事，随从偶像，正如耶和华在以色列人面前赶出的亚摩利人所行的一切。）","notes":[]},{"n":27,"t":"亚哈听见这些话，就撕裂衣服，禁食，贴身穿着麻布，也睡在麻布上，沮丧地走来走去。","notes":[]},{"n":28,"t":"耶和华的话临到提斯比人以利亚，说：","notes":[]},{"n":29,"t":"“亚哈在我面前这样谦卑，你看见了吗？因为他在我面前谦卑，所以在他的日子，我不降这祸；到他儿子的时候，我必降这祸于他的家。”","notes":[]}]},"22":{"heading":"米该雅警告亚哈","verses":[{"n":1,"t":"亚兰和以色列之间连续三年没有战争。","notes":[]},{"n":2,"t":"到了第三年，犹大王约沙法下去见以色列王。","notes":[]},{"n":3,"t":"以色列王对臣仆说：“你们不知道基列的拉末是属我们的吗？我们岂可不采取行动，把它从亚兰王手里夺回来呢？”","notes":[]},{"n":4,"t":"亚哈问约沙法说：“你肯同我去攻打基列的拉末吗？”约沙法对以色列王说：“你我不分彼此，我的军队就是你的军队，我的马就是你的马。”","notes":[]},{"n":5,"t":"约沙法对以色列王说：“请你先求问耶和华的话。”","notes":[]},{"n":6,"t":"于是以色列王召集先知，约有四百人，问他们说：“我可以上去攻打基列的拉末吗？还是不要上去呢？”他们说：“可以上去，因为主必将那城交在王的手里。”","notes":[]},{"n":7,"t":"约沙法说：“这里还有没有耶和华的先知，我们好求问他呢？”","notes":[]},{"n":8,"t":"以色列王对约沙法说：“还有一个人，是音拉的儿子米该雅，我们可以托他求问耶和华。只是我真的很恨他，因为他对我说预言，从不说吉言，总是说凶信。”约沙法说：“请王不要这么说。”","notes":[]},{"n":9,"t":"以色列王召了一个官员来，说：“你快去，把音拉的儿子米该雅召来。”","notes":[]},{"n":10,"t":"以色列王和犹大王约沙法在撒玛利亚城门前的禾场，各穿朝服，坐在宝座上，所有的先知都在他们面前说预言。","notes":[]},{"n":11,"t":"基拿拿的儿子西底家造了铁角，说：“耶和华如此说：‘你要用这些角抵触亚兰人，直到将他们灭尽。’”","notes":[]},{"n":12,"t":"所有的先知也都这样预言说：“可以上基列的拉末去，必然得胜，因为耶和华必将那城交在王的手中。”","notes":[]},{"n":13,"t":"那去召米该雅的使者对他说：“看哪，众先知都异口同声向王说吉言，你也跟他们说一样的话，说吉言吧！”","notes":[]},{"n":14,"t":"米该雅说：“我指着永生的耶和华起誓，耶和华向我说什么，我就说什么。”","notes":[]},{"n":15,"t":"米该雅来到王那里，王问他：“米该雅，我们可以上去攻打基列的拉末吗？还是不要上去呢？”他对王说：“你可以上去，必然得胜，耶和华必将那城交在王的手中。”","notes":[]},{"n":16,"t":"王对他说：“我要你发誓多少次，你才会奉耶和华的名向我说实话呢？”","notes":[]},{"n":17,"t":"米该雅说：“我看见以色列众人散布在山上，如同没有牧人的羊群一般。耶和华说：‘这些人没有主人，他们可以平安地各自回家去。’”","notes":[]},{"n":18,"t":"以色列王对约沙法说：“我岂没有告诉你，这人对我说预言，从不说吉言，只说凶信吗？”","notes":[]},{"n":19,"t":"米该雅说：“因此你要听耶和华的话！我看见耶和华坐在宝座上，天上的万军侍立在他左右。","notes":[]},{"n":20,"t":"耶和华说：‘谁去引诱亚哈上基列的拉末去阵亡呢？’这个这样说，那个那样说。","notes":[]},{"n":21,"t":"随后有一个灵出来，站在耶和华面前，说：‘我去引诱他。’","notes":[]},{"n":22,"t":"耶和华问他：‘用什么方法呢？’他说：‘我要出去，在他众先知的口中成为谎言的灵。’耶和华说：‘这样，你去引诱他，必能成功。你出去，照样做吧！’","notes":[]},{"n":23,"t":"现在，看哪，耶和华使谎言的灵入了你所有的这些先知的口，并且耶和华已经宣告要降祸于你。”","notes":[]},{"n":24,"t":"基拿拿的儿子西底家前来，打米该雅一巴掌，说：“耶和华的灵从哪里离开我向你说话呢？”","notes":[]},{"n":25,"t":"米该雅说：“看哪，你进入严密的内室躲藏的那日，就必看见。”","notes":[]},{"n":26,"t":"以色列王说：“把米该雅带走，交回给亚们市长和约阿施王子。","notes":[]},{"n":27,"t":"你们要说：‘王如此说，把这个人关在监狱里，使他受苦，吃不饱喝不足，直等到我平安回来。’”","notes":[]},{"n":28,"t":"米该雅说：“你若真的能平安回来，那就是耶和华没有藉我说这话了。”他又说：“众百姓啊，你们都要听！”","notes":[]},{"n":29,"t":"以色列王和犹大王约沙法上基列的拉末去。","notes":[],"heads":["亚哈阵亡"]},{"n":30,"t":"以色列王对约沙法说：“我要改装上阵，你可以仍穿王袍。”以色列王就改装上阵去了。","notes":[]},{"n":31,"t":"亚兰王吩咐他的三十二个战车长说：“你们不要与他们的大将或小兵交战，只要单单攻击以色列王。”","notes":[]},{"n":32,"t":"那些战车长看见约沙法就说：“这一定是以色列王！”他们转过去与他交战，约沙法就呼喊起来。","notes":[]},{"n":33,"t":"战车长见他不是以色列王，就转身不追他了。","notes":[]},{"n":34,"t":"有一人开弓，并不知情，箭恰巧射入以色列王铠甲的缝里。王对驾车的说：“我受重伤了，你掉过车来，载我离开战场！”","notes":[]},{"n":35,"t":"那日，战况越来越猛，有人扶着王站在战车上，面对亚兰人。到了傍晚，王就死了，血从伤处流入车底。","notes":[]},{"n":36,"t":"约在日落的时候，有喊声传遍军中，说：“大家各归本城，各归本地吧！”","notes":[]},{"n":37,"t":"王死了，人把他送到撒玛利亚，葬在撒玛利亚。","notes":[]},{"n":38,"t":"他们在撒玛利亚的水池旁洗他的车，有狗来舔他的血，有妓女在那里洗澡，正如耶和华所说的话。","notes":[]},{"n":39,"t":"亚哈其余的事，凡他所做的、他所修造的象牙宫和所建筑的一切城镇，不都写在《以色列诸王记》上吗？","notes":[]},{"n":40,"t":"亚哈与他祖先同睡，他儿子亚哈谢接续他作王。","notes":[]},{"n":41,"t":"以色列王亚哈第四年，亚撒的儿子约沙法登基作犹大王。","notes":[],"heads":["犹大王约沙法"]},{"n":42,"t":"约沙法登基的时候年三十五岁，在耶路撒冷作王二十五年。他母亲名叫阿苏巴，是示利希的女儿。","notes":[]},{"n":43,"t":"约沙法效法他父亲亚撒所行的道，不偏离左右，行耶和华眼中看为正的事。只是丘坛还没有废去，百姓仍在那里献祭烧香。","notes":[]},{"n":44,"t":"约沙法与以色列王和平相处。","notes":[]},{"n":45,"t":"约沙法其余的事和他所行的英勇事迹，以及他的战役，不都写在《犹大列王记》上吗？","notes":[]},{"n":46,"t":"约沙法把他父亲亚撒的日子所剩下男的庙妓都从国中除去了。","notes":[]},{"n":47,"t":"那时以东没有立王，由总督治理。","notes":[]},{"n":48,"t":"约沙法造了他施船只，要往俄斐去，把金子运来，却没有启航，因为船在以旬．迦别毁坏了。","notes":[]},{"n":49,"t":"亚哈的儿子亚哈谢对约沙法说：“让我的仆人和你的仆人坐船同去吧！”约沙法却不肯。","notes":[]},{"n":50,"t":"约沙法与他祖先同睡，与他祖先同葬在大卫城，他儿子约兰接续他作王。","notes":[]},{"n":51,"t":"犹大王约沙法第十七年，亚哈的儿子亚哈谢在撒玛利亚登基作以色列王；他作以色列王二年。","notes":[],"heads":["以色列王亚哈谢"]},{"n":52,"t":"他行耶和华眼中看为恶的事，行他父母的道，又行尼八的儿子耶罗波安的道，使以色列陷入罪里。","notes":[]},{"n":53,"t":"他事奉巴力，敬拜它，惹耶和华－以色列的神发怒，正如他父亲一切所行的。","notes":[]}]}},"2KI":{"1":{"heading":"以利亚和亚哈谢王","verses":[{"n":1,"t":"亚哈死后，摩押背叛以色列。","notes":[]},{"n":2,"t":"亚哈谢在撒玛利亚，一日从楼上的栏杆跌下来，就病了。于是他派使者，对他们说：“你们去问以革伦的神明巴力．西卜，我这病是否能痊愈。”","notes":[]},{"n":3,"t":"但耶和华的使者对提斯比人以利亚说：“你起来，上去迎见撒玛利亚王的使者，对他们说：‘你们去问以革伦的神明巴力．西卜，是因为以色列中没有神吗？’","notes":[]},{"n":4,"t":"所以耶和华如此说：‘你必不能下你所上的床，因为你一定会死！’”以利亚就去了。","notes":[]},{"n":5,"t":"使者回到王那里，王对他们说：“你们为什么回来了呢？”","notes":[]},{"n":6,"t":"他们对王说：“有一个人上来迎见我们，对我们说：‘去，回到差你们来的王那里，对他说：耶和华如此说，你派人去问以革伦的神明巴力．西卜，是因为以色列中没有神吗？所以你必不能下所上的床，你一定会死。’”","notes":[]},{"n":7,"t":"王对他们说：“上来迎见你们，告诉你们这些话的人是什么样子呢？”","notes":[]},{"n":8,"t":"他们对王说：“这人身穿毛衣，腰束皮带。”王说：“他一定是提斯比人以利亚。”","notes":["“身穿毛衣”或译“全身长毛”。"]},{"n":9,"t":"于是，王派了一个五十夫长，带领五十人到以利亚那里。他上来，看哪，以利亚正坐在山顶上。五十夫长对他说：“神人哪，王吩咐你下来！”","notes":[]},{"n":10,"t":"以利亚回答五十夫长说：“我若是神人，愿火从天上降下来，吞灭你和你的五十个人！”于是有火从天上降下来，吞灭五十夫长和他的五十个人。","notes":[]},{"n":11,"t":"王又派另一个五十夫长，带领五十人到以利亚那里。五十夫长对他说：“神人哪，王这样吩咐，快快下来！”","notes":[]},{"n":12,"t":"以利亚回答他们说：“我若是神人，愿火从天上降下来，吞灭你和你的五十个人！”于是神的火从天上降下来，吞灭五十夫长和他的五十个人。","notes":["“神的火”或译“大火”。"]},{"n":13,"t":"王第三次又派一个五十夫长，带领五十人去。第三个五十夫长上去，双膝跪在以利亚面前，哀求他说：“神人哪，愿我的性命和你这五十个仆人的性命在你眼中看为宝贵！","notes":[]},{"n":14,"t":"看哪，已经有火从天上降下来，吞灭前两次来的五十夫长和他们的五十个人，现在愿我的性命在你眼中看为宝贵！”","notes":[]},{"n":15,"t":"耶和华的使者对以利亚说：“你跟他下去，不要怕他！”以利亚就起来，跟他下到王那里去。","notes":[]},{"n":16,"t":"他对王说：“耶和华如此说：‘你派人去问以革伦的神明巴力．西卜，是因为以色列中没有神可以让你求问他的话吗？所以你必不能下所上的床，你一定会死！’”","notes":[]},{"n":17,"t":"亚哈谢死了，正如耶和华藉以利亚所说的话。犹大王约沙法的儿子约兰第二年，亚哈谢的兄弟约兰接续他作王，因亚哈谢没有儿子。","notes":["“亚哈谢的兄弟”是根据七十士译本的一些抄本和其他古译本；原文没有。"],"heads":["亚哈谢死后约兰继位"]},{"n":18,"t":"亚哈谢其余所做的事，不都写在《以色列诸王记》上吗？","notes":[]}]},"2":{"heading":"以利亚被接升天","verses":[{"n":1,"t":"耶和华要用旋风接以利亚升天的时候，以利亚与以利沙从吉甲往前行。","notes":[]},{"n":2,"t":"以利亚对以利沙说：“耶和华差遣我往伯特利去，你可以留在这里。”以利沙说：“我指着永生的耶和华，又指着你的性命起誓，我必不离开你。”于是二人下到伯特利。","notes":[]},{"n":3,"t":"在伯特利的先知的门徒出来，到以利沙那里，对他说：“耶和华今日要接你的师父离开你，你知不知道？”他说：“我知道，你们不要作声。”","notes":["“要接你的师父离开你”：原文直译“要从你头上接走你的师父”；下同。"]},{"n":4,"t":"以利亚对以利沙说：“耶和华差遣我往耶利哥去，你可以留在这里。”以利沙说：“我指着永生的耶和华，又指着你的性命起誓，我必不离开你。”于是二人到了耶利哥。","notes":[]},{"n":5,"t":"在耶利哥的先知的门徒来靠近以利沙，对他说：“耶和华今日要接你的师父离开你，你知不知道？”他说：“我知道，你们不要作声。”","notes":[]},{"n":6,"t":"以利亚对以利沙说：“耶和华差遣我往约旦河去，你可以留在这里。”以利沙说：“我指着永生的耶和华，又指着你的性命起誓，我必不离开你。”于是二人一同往前行。","notes":[]},{"n":7,"t":"有五十个先知的门徒同去，远远地站在他们对面；他们二人在约旦河边站住。","notes":[]},{"n":8,"t":"以利亚卷起自己的外衣，用来打水，水就左右分开，二人走干地过去。","notes":[]},{"n":9,"t":"过去之后，以利亚对以利沙说：“我未被接去离开你以前，你要我为你做什么，只管求。”以利沙说：“愿感动你的灵双倍感动我。”","notes":[]},{"n":10,"t":"以利亚说：“你求的是一件难事。我被接去离开你的时候，你若看见我，就必得着；若不然，就得不着了。”","notes":[]},{"n":11,"t":"他们边走边说话的时候，看哪，有火马和火焰车出现，把二人隔开，以利亚就乘旋风升天去了。","notes":[],"heads":["以利亚乘旋风升天"]},{"n":12,"t":"以利沙看见，就呼叫说：“我父啊！我父啊！以色列的战车骑兵啊！”以利沙不再看见他的时候，就把自己的衣服撕为两片。","notes":[]},{"n":13,"t":"他拾起以利亚身上掉下来的外衣，回去站在约旦河边。","notes":[]},{"n":14,"t":"他用以利亚身上掉下来的外衣打水，说：“耶和华－以利亚的神在哪里呢？”打水之后，水也左右分开，以利沙就过去了。","notes":[]},{"n":15,"t":"在耶利哥的先知的门徒从对面看见他，说：“感动以利亚的灵临到以利沙身上了。”他们就来迎接他，俯伏于地，向他下拜，","notes":[]},{"n":16,"t":"对他说：“看哪，仆人这里有五十个壮士，请你让他们去寻找你师父，或者耶和华的灵将他提起来，投在某山某谷。”以利沙说：“你们不必派人去。”","notes":[]},{"n":17,"t":"他们再三催促，直到他不好意思，就说：“你们派人去吧！”他们就派了五十个人去，寻找了三天，也没有找着他。","notes":[]},{"n":18,"t":"以利沙仍然留在耶利哥，他们回到他那里，他对他们说：“我不是告诉你们不必去吗？”","notes":[]},{"n":19,"t":"耶利哥城的人对以利沙说：“看哪，这城的地势美好，正如我主所看见的，只是水质恶劣，地也没有生产。”","notes":[],"heads":["以利沙的神迹"]},{"n":20,"t":"以利沙说：“你们拿一个新的瓶子来，里面装盐。”他们就拿给他。","notes":[]},{"n":21,"t":"他出去到了水源，把盐倒在那里，说：“耶和华如此说：‘我治好了这水，从那里不会再有死亡和不生产的事了。’”","notes":[]},{"n":22,"t":"于是那水治好了，直到今日，正如以利沙所说的话。","notes":[]},{"n":23,"t":"以利沙从那里上伯特利去。正上路的时候，有些孩童从城里出来，讥笑他，对他说：“秃头的，上去吧！秃头的，上去吧！”","notes":[]},{"n":24,"t":"他转过身来瞪着他们，奉耶和华的名诅咒他们。于是有两只母熊从林中出来，撕裂他们当中的四十二个孩童。","notes":[]},{"n":25,"t":"以利沙从伯特利上迦密山，又从那里回到撒玛利亚。","notes":[]}]},"3":{"heading":"以色列与摩押打仗","verses":[{"n":1,"t":"犹大王约沙法第十八年，亚哈的儿子约兰在撒玛利亚登基，作以色列王十二年。","notes":[]},{"n":2,"t":"他行耶和华眼中看为恶的事，但不致像他父母所行的，因为他除掉他父所造巴力的柱像。","notes":[]},{"n":3,"t":"然而，他依恋尼八的儿子耶罗波安使以色列陷入罪里的那罪，总不离开。","notes":[]},{"n":4,"t":"摩押王米沙牧养许多羊，曾向以色列王进贡十万羔羊和十万公绵羊的毛。","notes":[]},{"n":5,"t":"亚哈死后，摩押王背叛以色列王。","notes":[]},{"n":6,"t":"那时约兰王出撒玛利亚，数点以色列众人。","notes":[]},{"n":7,"t":"他向前行，派人到犹大王约沙法那里，说：“摩押王背叛我，你肯同我去攻打摩押吗？”约沙法说：“我肯上去，你我不分彼此，我的军队就是你的军队，我的马就是你的马。”","notes":[]},{"n":8,"t":"然后约沙法说：“我们从哪条路上去呢？”约兰说：“从以东旷野的路上去。”","notes":[]},{"n":9,"t":"于是，以色列王和犹大王，以及以东王，都一同去。他们绕行了七日的路程，军队和所带的牲畜都没有水喝。","notes":[]},{"n":10,"t":"以色列王说：“哀哉！耶和华召集我们这三王，是要交在摩押人的手里。”","notes":[]},{"n":11,"t":"约沙法说：“这里不是有耶和华的先知吗？我们可以托他求问耶和华。”以色列王的一个大臣回答说：“这里有沙法的儿子以利沙，就是从前服事以利亚的。”","notes":["“服事以利亚的”：原文直译“倒水在以利亚手上的”。"]},{"n":12,"t":"约沙法说：“他必有耶和华的话。”于是以色列王、约沙法和以东王都下去见他。","notes":[]},{"n":13,"t":"以利沙对以色列王说：“我跟你有什么关系呢？去问你父亲的先知和你母亲的先知吧！”以色列王对他说：“不，因为耶和华召集我们这三王，是要交在摩押人的手里。”","notes":[]},{"n":14,"t":"以利沙说：“我指着所事奉永生的万军之耶和华起誓，我若不看犹大王约沙法的情面，必不理你，不睬你。","notes":[]},{"n":15,"t":"现在你们给我找一个弹琴的人来。”弹琴的人弹奏的时候，耶和华的手就按在以利沙身上。","notes":[]},{"n":16,"t":"他就说：“耶和华如此说：‘你们要在这谷中到处挖沟。’","notes":[]},{"n":17,"t":"因为耶和华如此说：‘你们虽不见风，也不见雨，这谷却必满了水，使你们和你们的牛羊牲畜都有水喝。’","notes":[]},{"n":18,"t":"在耶和华眼中这还算是小事，他也必将摩押人交在你们手中。","notes":[]},{"n":19,"t":"你们必攻破一切堡垒和美好的城镇，砍伐各种好树，塞住一切水泉，用石头毁坏一切良田。”","notes":[]},{"n":20,"t":"到了早晨，约在献祭的时候，看哪，有水从以东而来，遍地就满了水。","notes":[]},{"n":21,"t":"摩押众人听见这三王上来要与他们打仗，凡能束上腰带的，无论老少，都被召集站在边界上。","notes":[],"heads":["摩押人败遁"]},{"n":22,"t":"摩押人清早起来，日光照在水上，他们看见对面水红如血，","notes":[]},{"n":23,"t":"就说：“这是血啊！必是三王互相击杀，全都灭亡了。摩押人哪，我们现在去抢夺财物吧！”","notes":[]},{"n":24,"t":"摩押人到了以色列营，以色列人起来攻打他们，他们就在以色列人面前逃跑。以色列人追杀摩押人，直杀入摩押境内。","notes":["“以色列人追杀...境内”：原文另译“以色列人前进，击杀摩押人”。"]},{"n":25,"t":"他们拆毁摩押的城镇，各人抛石头填满一切良田，塞住一切水泉，砍伐各种好树，只剩下吉珥．哈列设的石墙，但甩石的兵仍然包围攻打那城。","notes":[]},{"n":26,"t":"摩押王见战事激烈，对他不利，就率领七百个拿刀的兵，想突围逃到以东王那里，却没有成功。","notes":["“以东”：原文另译“亚兰”。"]},{"n":27,"t":"于是他在城墙上，把那应当接续他作王的长子献为燔祭。 有极大的愤怒临到以色列，于是三王离开摩押王，各自回本地去了。","notes":[]}]},"4":{"heading":"以利沙帮助穷寡妇","verses":[{"n":1,"t":"有个先知门徒的妻子哀求以利沙说：“你的仆人，我丈夫死了，他敬畏耶和华是你所知道的。现在有债主来，要带走我的两个孩子给他作奴隶。”","notes":[]},{"n":2,"t":"以利沙对她说：“我可以为你做什么呢？告诉我，你家里有什么？”她说：“婢女家中除了一瓶油之外，什么也没有。”","notes":[]},{"n":3,"t":"以利沙说：“你到外面去向所有的邻舍借器皿，要空的器皿，不要少借。","notes":[]},{"n":4,"t":"然后你回家，关上门，你和你儿子在里面把油倒在所有的器皿里，倒满了就放在一边。”","notes":[]},{"n":5,"t":"于是妇人离开以利沙去了。她关上门，把自己和儿子关在家里。他们把器皿拿给她，她就倒油。","notes":[]},{"n":6,"t":"器皿都满了，她对儿子说：“再给我拿器皿来。”儿子对她说：“没有器皿了。”油就止住了。","notes":[]},{"n":7,"t":"妇人去告诉神人，神人说：“你去卖了油还债，你和你两个儿子可以靠着所剩的过活。”","notes":[]},{"n":8,"t":"一日，以利沙经过书念，在那里有一个富有的妇人强留他吃饭。此后，以利沙每次经过就转到那里去吃饭。","notes":[],"heads":["书念妇人接待以利沙"]},{"n":9,"t":"妇人对丈夫说：“看哪，我知道那常从我们这里经过的是神圣的神人。","notes":[]},{"n":10,"t":"我们可以为他盖一间有墙的小阁楼，里面安放床榻、桌子、椅子、灯台。每当他来到我们这里，就可以住在那里。”","notes":[]},{"n":11,"t":"一日，以利沙来到那里，转进那阁楼，躺卧在那里。","notes":[]},{"n":12,"t":"以利沙吩咐仆人基哈西说：“你叫这书念妇人来。”他把妇人叫了来，妇人就站在以利沙面前。","notes":[]},{"n":13,"t":"以利沙吩咐仆人说：“你对她说：‘看哪，你为我们费了许多心思，我可以为你做什么呢？我可以为你向王或元帅求什么呢？’”她说：“我已住在自己百姓之中。”","notes":[]},{"n":14,"t":"以利沙说：“究竟可以为她做什么呢？”基哈西说：“她真的没有儿子，她丈夫也老了。”","notes":[]},{"n":15,"t":"以利沙说：“叫她回来。”于是他叫了她来，她就站在门口。","notes":[]},{"n":16,"t":"以利沙说：“明年这时候，你必抱一个儿子。”她说：“神人，我主啊，不要这样欺哄婢女。”","notes":["“明年这时候”：原文是“生命足月的时候”。"]},{"n":17,"t":"妇人果然怀孕，到了明年那时候，生了一个儿子，正如以利沙向她所说的。","notes":[]},{"n":18,"t":"孩子长大，一日出去到他父亲和收割的人那里。","notes":[]},{"n":19,"t":"他对父亲说：“我的头啊，我的头啊！”他父亲对仆人说：“把他抱到他母亲那里。”","notes":[]},{"n":20,"t":"仆人抱去，交给他母亲。孩子坐在母亲的膝上，到中午就死了。","notes":[]},{"n":21,"t":"他母亲上去，把他放在神人的床上，关了门出来，","notes":[]},{"n":22,"t":"呼叫她丈夫说：“你叫一个仆人给我牵一匹驴来，我要赶去见神人，然后回来。”","notes":[]},{"n":23,"t":"丈夫说：“今日不是初一，也不是安息日，你为何要到他那里去呢？”妇人说：“平安无事。”","notes":[]},{"n":24,"t":"于是她备上驴，对仆人说：“走，赶紧走，除非我吩咐你，不要为了我而慢下来。”","notes":[]},{"n":25,"t":"妇人往迦密山去，到了神人那里。神人远远看见她，对仆人基哈西说：“看哪，书念的妇人来了！","notes":[]},{"n":26,"t":"现在你跑去迎接她，对她说，你平安吗？你丈夫平安吗？孩子平安吗？”她说：“平安。”","notes":[]},{"n":27,"t":"妇人上了山，到神人那里，就抱住神人的脚。基哈西前来要推开她，神人说：“由她吧！因为她心里愁苦。但耶和华向我隐瞒这事，没有告诉我。”","notes":[]},{"n":28,"t":"妇人说：“我何尝向我主求过儿子呢？我岂不是说过，不要欺哄我吗？”","notes":[]},{"n":29,"t":"以利沙吩咐基哈西说：“你束上腰，手拿我的杖前去。若遇见人，不要向他问安，人若向你问安，也不要回答。要把我的杖放在孩子脸上。”","notes":[]},{"n":30,"t":"孩子的母亲说：“我指着永生的耶和华，又指着你的性命起誓，我必不离开你。”于是以利沙起身，随着她去了。","notes":[]},{"n":31,"t":"基哈西在他们以先去了，把杖放在孩子脸上，却没有声音，也没有动静。基哈西回去，迎见以利沙，告诉他说：“孩子还没有醒过来。”","notes":[]},{"n":32,"t":"以利沙进了屋子，看哪，孩子死了，放在自己的床上。","notes":[]},{"n":33,"t":"他进去，关上门，只有他们两个人，他就向耶和华祈祷。","notes":[]},{"n":34,"t":"他上去伏在孩子身上，口对口，眼对眼，手对手。他伏在孩子身上，孩子的身体就渐渐暖和了。","notes":[]},{"n":35,"t":"然后他下来，在屋里来回走了一趟，又上去伏在孩子身上。孩子打了七个喷嚏，眼睛就睁开了。","notes":[]},{"n":36,"t":"以利沙叫基哈西说：“你叫这书念妇人来。”于是他叫了她来。妇人来到以利沙那里，以利沙说：“把你儿子抱起来。”","notes":[]},{"n":37,"t":"妇人就进来，在以利沙脚前俯伏于地，向他下拜，然后抱起她儿子出去了。","notes":[]},{"n":38,"t":"以利沙回到吉甲，那地正有饥荒。先知的门徒坐在他面前，他吩咐仆人说：“你把大锅放在火上，给先知的门徒熬汤。”","notes":[],"heads":["两件神迹"]},{"n":39,"t":"有一个人去到田野摘菜，发现一棵野瓜藤，就摘了满满一兜的野瓜回来，切了放进熬汤的锅中，并不知道那是什么。","notes":[]},{"n":40,"t":"他们把汤倒出来给大家吃。他们吃汤里东西的时候，喊叫说：“神人哪，锅子里的东西会死人！”所以他们不能吃了。","notes":[]},{"n":41,"t":"以利沙说：“拿点面来。”他把面撒在锅中，说：“倒出来，给大家吃吧！”锅中就没有毒了。","notes":[]},{"n":42,"t":"有一个人从巴力．沙利沙来，带着初熟果子的食物、二十个大麦做的饼和新麦穗，装在袋子里送给神人。神人说：“把这些给大家吃。”","notes":[]},{"n":43,"t":"仆人说：“这些岂可摆在一百人面前呢？”以利沙说：“你只管给大家吃吧！因为耶和华如此说，他们必吃了，还有剩下的。”","notes":[]},{"n":44,"t":"仆人就摆在他们面前，他们吃了，还有剩下，正如耶和华所说的。","notes":[]}]},"5":{"heading":"乃缦得医治","verses":[{"n":1,"t":"亚兰王的元帅乃缦在他主人面前是一个伟大的人，得王的喜悦，因为耶和华曾藉他使亚兰人得胜。他虽然是大能的勇士，却染上了麻风。","notes":["“麻风”泛指传染性皮肤病；本卷书下同。"]},{"n":2,"t":"亚兰人成群出征的时候，从以色列地掳了一个小女孩，她就服事乃缦的妻子。","notes":[]},{"n":3,"t":"她对女主人说：“我希望主人去见撒玛利亚的先知，他必能治好主人的麻风。”","notes":[]},{"n":4,"t":"乃缦去告诉他主人说，从以色列地来的女孩如此如此说。","notes":[]},{"n":5,"t":"亚兰王说：“你可以去，我也会送信给以色列王。”于是乃缦手里带十他连得银子、六千舍客勒金子和十套衣裳去了。","notes":[]},{"n":6,"t":"他带着这信给以色列王，说：“现在你接到这信，看哪，我派臣仆乃缦到你这里来，你要治好他的麻风。”","notes":[]},{"n":7,"t":"以色列王读了信就撕裂衣服，说：“我岂是神，能使人死使人活呢？这人竟派人来，叫我治好一个人的麻风。你们要知道，看，这人是找机会来跟我吵架的。”","notes":[]},{"n":8,"t":"神人以利沙听见以色列王撕裂衣服，就派人到王那里，说：“你为什么撕裂衣服呢？让那人到我这里来，他会知道以色列中有先知。”","notes":[]},{"n":9,"t":"于是乃缦带着车马到了以利沙的家，站在门前。","notes":[]},{"n":10,"t":"以利沙派一个使者，对乃缦说：“去，在约旦河中沐浴七次，你的肉就必复原，你会得洁净。”","notes":[]},{"n":11,"t":"乃缦却发怒走了。他说：“看哪，我以为他必定会出来，到我这里，站着求告耶和华－他神的名，在患处上摇手，治好这麻风。","notes":[]},{"n":12,"t":"大马士革的亚玛拿河和法珥法河岂不比以色列的一切水更好吗？我难道不可以在那里沐浴而得洁净吗？”于是他生气，转身走了。","notes":["“亚玛拿”：原文另译“亚罢拿”。"]},{"n":13,"t":"他的仆人近前来，对他说：“我父啊，先知若吩咐你做一件大事，你岂不做吗？何况是吩咐你去沐浴，得洁净呢？”","notes":[]},{"n":14,"t":"于是乃缦下去，照着神人的话，在约旦河里浸了七次。他的肉复原，好像小孩的肉，他就洁净了。","notes":[]},{"n":15,"t":"乃缦带着所有跟随他的人，回到神人那里，站在他面前，说：“看哪，我知道，除了以色列，全地没有神。现在请你收下仆人的礼物。”","notes":[]},{"n":16,"t":"以利沙说：“我指着所事奉永生的耶和华起誓，我必不接受。”乃缦再三请他收下，他却不肯。","notes":[]},{"n":17,"t":"乃缦说：“你若不肯，请把两匹骡子能驮的土赐给仆人，仆人必不再把燔祭或祭物献给别神，只献给耶和华。","notes":[]},{"n":18,"t":"惟有一件事，愿耶和华饶恕你仆人：我主人进临门庙在那里叩拜的时候，他总是扶着我的手，所以我也在临门庙叩拜。我在临门庙叩拜的这事，愿耶和华饶恕你仆人。”","notes":[]},{"n":19,"t":"以利沙对他说：“你平安地回去吧！”乃缦离开他去了。走了一小段路，","notes":[]},{"n":20,"t":"神人以利沙的仆人基哈西说：“看哪，我主人不愿从这亚兰人乃缦手里接受他带来的礼物，我指着永生的耶和华起誓，我必跑去追上他，向他拿些东西。”","notes":[]},{"n":21,"t":"于是基哈西去追乃缦。乃缦看见有人追来，就下车迎着他，说：“都平安吗？”","notes":[]},{"n":22,"t":"他说：“都平安！我主人派我来说：‘看哪，现在有两个年轻人，是先知的门徒，从以法莲山区来到我这里，请你给他们一他连得银子，两套衣裳。’”","notes":[]},{"n":23,"t":"乃缦说：“好啊，请收下二他连得。”他再三请求，就把二他连得银子装在两个袋子里，连同两套衣裳交给两个仆人；他们就在基哈西前头抬着走。","notes":[]},{"n":24,"t":"到了山冈，基哈西从他们手中接过来，放在屋里，打发这些人走了。","notes":[]},{"n":25,"t":"基哈西进去，站在主人面前。以利沙对他说：“基哈西，你从哪里来？”他说：“仆人哪里也没去。”","notes":[]},{"n":26,"t":"以利沙对他说：“那人下车转过来迎着你的时候，我的心岂没有去呢？这岂是接受银子，接受衣裳、橄榄园、葡萄园、牛羊、仆婢的时候呢？","notes":[]},{"n":27,"t":"因此，乃缦的麻风必紧随你和你的后裔，直到永远。”基哈西从以利沙面前出去，就长了麻风，像雪一样。","notes":[]}]},"6":{"heading":"找回斧子的头","verses":[{"n":1,"t":"先知的门徒对以利沙说：“看哪，我们在你面前居住的地方，那里对我们太窄小了。","notes":[]},{"n":2,"t":"让我们往约旦河去，各人从那里取一根木料，在那里为自己建造居住的地方。”他说：“你们去吧！”","notes":[]},{"n":3,"t":"有一人说：“请你与仆人同去。”他说：“我可以去。”","notes":[]},{"n":4,"t":"于是以利沙与他们同去。到了约旦河，他们砍伐树木。","notes":[]},{"n":5,"t":"有一人砍树的时候，斧子的头掉在水里，他就喊着说：“不好了！我主啊，斧子是借来的。”","notes":[]},{"n":6,"t":"神人说：“掉在哪里了？”他把那地方指给以利沙看。以利沙砍了一块木头，抛在水里，就使斧子的头浮上来了。","notes":[]},{"n":7,"t":"以利沙说：“拿起来吧！”那人就伸手拿起来了。","notes":[]},{"n":8,"t":"亚兰王与以色列作战，他和臣仆商议说：“我要在某处某处安营。”","notes":["“安营”或译“攻击”。"],"heads":["亚兰军队进攻受挫"]},{"n":9,"t":"神人派人到以色列王那里，说：“你要小心，不要从某处经过，因为亚兰人下到那里去了。”","notes":[]},{"n":10,"t":"以色列王派人到神人告诉他的地方去。神人警告他，他就在那里有所防备，不止一两次。","notes":[]},{"n":11,"t":"亚兰王因这事心里气愤，召了臣仆来，对他们说：“我们当中有谁帮助以色列王，你们不告诉我吗？”","notes":[]},{"n":12,"t":"有一个臣仆说：“不，我主，我王！只有以色列中的先知以利沙，把王在卧房所说的话告诉以色列王。”","notes":[]},{"n":13,"t":"王说：“你们去查看他在哪里，我好派人去捉拿他。”有人告诉王说：“看哪，他在多坍。”","notes":[]},{"n":14,"t":"王就派遣车马和大军往那里去，夜间他们到了，围困那城。","notes":[]},{"n":15,"t":"神人的仆人清早起来出去，看哪，车马军兵围困了城。仆人对神人说：“不好了！我主啊，我们该怎么办呢？”","notes":[]},{"n":16,"t":"神人说：“不要惧怕！因与我们同在的比与他们同在的更多。”","notes":[]},{"n":17,"t":"以利沙祷告说：“耶和华啊，求你开他的眼目，使他能看见。”耶和华开了这年轻人的眼目，他就看见了，看哪，满山有火马和火焰车围绕以利沙。","notes":[]},{"n":18,"t":"亚兰人下到以利沙那里，以利沙向耶和华祷告说：“求你击打这国，使他们眼目失明。”耶和华就照以利沙的话，击打他们，使他们眼目失明。","notes":[]},{"n":19,"t":"以利沙对他们说：“这不是那条路，也不是那座城。你们跟我走，我必领你们到你们要寻找的人那里。”于是他领他们到了撒玛利亚。","notes":[]},{"n":20,"t":"他们进了撒玛利亚，以利沙说：“耶和华啊，求你开这些人的眼目，使他们能看见。”耶和华开了他们的眼目，他们就看见了，看哪，是在撒玛利亚城中。","notes":[]},{"n":21,"t":"以色列王看见他们，就对以利沙说：“我父啊，我真的可以击杀他们吗？”","notes":[]},{"n":22,"t":"他说：“不可击杀！这些人岂是你用刀用弓掳来给你击杀的呢？当在他们面前摆设饮食给他们吃喝，让他们回到他们主人那里。”","notes":[]},{"n":23,"t":"王为他们预备了盛大的宴席。他们吃喝完了，王就送他们回到他们主人那里。此后，亚兰的军队不再侵犯以色列地了。","notes":[]},{"n":24,"t":"此后，亚兰王便．哈达召集他的全军，上来围困撒玛利亚。","notes":[],"heads":["围困撒玛利亚"]},{"n":25,"t":"看哪，被围困的时候，撒玛利亚有大饥荒，甚至一个驴头值八十舍客勒，四分之一卡布 的鸽子粪值五舍客勒。","notes":["“卡布”：容量单位；参“度量衡表”。"]},{"n":26,"t":"一日，以色列王在城墙上经过，有一个妇人向他呼叫说：“我主，我王啊！求你帮助。”","notes":[]},{"n":27,"t":"王说：“耶和华不帮助你，我从哪里帮助你呢？是从禾场，或从压酒池吗？”","notes":[]},{"n":28,"t":"王对妇人说：“你有什么事？”她说：“这妇人对我说：‘把你的儿子交出来，我们今日可以吃他，明日可以吃我的儿子。’","notes":[]},{"n":29,"t":"我们就煮了我的儿子吃了。次日我对她说：‘要把你的儿子交出来，我们可以吃。’她却把她的儿子藏起来。”","notes":[]},{"n":30,"t":"王听见妇人的话，就撕裂衣服；那时，王在城墙上经过，百姓看见了，看哪，王贴身穿着麻布。","notes":[]},{"n":31,"t":"王说：“我今日若容许沙法的儿子以利沙的头还留在他身上，愿神重重惩罚我！”","notes":[]},{"n":32,"t":"那时，以利沙正坐在家中，有长老与他同坐。王派一个人先去，使者还没有到，以利沙对长老说：“你们看，这凶手之子派人来斩我的头。你们注意，当使者来到，你们就关上门，把他关在门外。在他后头不就是他主人的脚步声吗？”","notes":[]},{"n":33,"t":"正与他们说话的时候，看哪，使者下到他那里，说：“看哪，这灾祸是从耶和华来的，我何必再仰望耶和华呢？”","notes":["“使者”：原文另译“王”。"]}]},"7":{"heading":"亚兰军队弃营逃命","verses":[{"n":1,"t":"以利沙说：“你们要听耶和华的话，耶和华如此说：明日约这时候，在撒玛利亚城门口，一细亚细面只卖一舍客勒，二细亚大麦也卖一舍客勒。”","notes":[]},{"n":2,"t":"有一个搀扶王的军官回答神人说：“看哪，即使耶和华打开天上的窗户，也不可能有这事。”以利沙说：“看哪，你必亲眼看见，在那里却吃不到什么。”","notes":[]},{"n":3,"t":"在城门口有四个长麻风的人，他们彼此说：“我们为何坐在这里等死呢？","notes":[]},{"n":4,"t":"我们若说要进城去，城里有饥荒，我们必死在那里。若我们在这里坐着不动，也必死。现在，来吧，我们去向亚兰人的军队投降。若他们饶我们的命，我们就活着；若杀我们，我们就死吧！”","notes":[]},{"n":5,"t":"黄昏的时候，他们起来往亚兰人的军营去；到了营边，看哪，没有一人在那里。","notes":[]},{"n":6,"t":"因为主使亚兰人的军队听见战车战马的声音，大军的声音，他们就彼此说：“看哪，这必是以色列王雇用赫人诸王和埃及诸王来攻击我们。”","notes":[]},{"n":7,"t":"所以，在黄昏的时候他们起来逃跑，撇下帐棚、马、驴，把军营留在原处，只顾逃命。","notes":[]},{"n":8,"t":"那些长麻风的人到了营边，进了一座帐棚，吃了喝了，从当中拿走金银和衣服，收藏起来。他们又回来，进了另一座帐棚，从当中拿走财物去收藏。","notes":[]},{"n":9,"t":"那时，他们彼此说：“我们所做的不对了！这一天是有好消息的日子，我们竟不作声！若等到天亮，我们就有罪了。现在，来，我们去向王室报信吧！”","notes":[]},{"n":10,"t":"他们就去叫守城门的人，告诉他们说：“我们到了亚兰人的军营，看哪，没有一人在那里，也无人声，只有拴着的马和驴，帐棚都留在原处。”","notes":[]},{"n":11,"t":"守城门的人就呼叫，他们向城内的王室报信。","notes":[]},{"n":12,"t":"王夜间起来，对臣仆说：“我告诉你们亚兰人向我们做的事。他们知道我们饥饿，所以离营，埋伏在田野，说：‘以色列人出城的时候，我们活捉他们，我们就可以进到城里去。’”","notes":[]},{"n":13,"t":"王的一个臣仆回答说：“不如叫人从城里剩下的马中取五匹，看哪，这些马像以色列大众一样，快要灭亡了；我们派人去窥探吧！”","notes":["“不如叫人...一样”是根据一些古卷；原文是“不如叫人从城里剩下的，从城里剩下的马中取五匹，看哪，这些马像以色列大众一样，看哪，这些马像以色列大众一样”。"]},{"n":14,"t":"于是他们取了两辆车和马，王派人去跟踪亚兰人的军队，说：“你们去窥探吧。”","notes":[]},{"n":15,"t":"他们去跟踪亚兰人，直到约旦河。看哪，整条路上都是亚兰人匆忙逃跑时所丢弃的衣服和器具，使者就回来向王报告。","notes":[]},{"n":16,"t":"百姓就出去，掳掠亚兰人的军营。于是一细亚细面只卖一舍客勒，二细亚大麦也卖一舍客勒，正如耶和华所说的。","notes":[]},{"n":17,"t":"王派搀扶他的那军官在城门指挥，百姓在城门把他踩死了，正如神人在王下到他那里的时候所说的。","notes":[]},{"n":18,"t":"神人曾对王说：“明日约这时候，在撒玛利亚城门口，二细亚大麦只卖一舍客勒，一细亚细面也卖一舍客勒。”","notes":[]},{"n":19,"t":"那军官回答神人说：“看哪，即使耶和华打开天上的窗户，也不可能有这事。”神人说：“看哪，你必亲眼看见，在那里却吃不到什么。”","notes":[]},{"n":20,"t":"这话果然应验在他身上，因为百姓在城门把他踩死了。","notes":[]}]},"8":{"heading":"书念的妇人回原住地","verses":[{"n":1,"t":"以利沙曾对他救活的孩子的母亲说：“你和你的全家要起身，往你可住的地方去住，因为耶和华已令饥荒降在这地七年。”","notes":[]},{"n":2,"t":"妇人就起身，照神人的话去做，带着全家往非利士人的地去，寄居了七年。","notes":[]},{"n":3,"t":"过了七年，那妇人从非利士人的地回来，就出去为自己的房屋田地哀求王。","notes":[]},{"n":4,"t":"那时王正与神人的仆人基哈西谈话，说：“你把以利沙所做的一切大事告诉我。”","notes":[]},{"n":5,"t":"基哈西告诉王以利沙如何使死人复活，看哪，以利沙所救活的孩子的母亲正为自己的房屋田地来哀求王。基哈西说：“我主我王，这就是那妇人，这是她的儿子，就是以利沙所救活的。”","notes":[]},{"n":6,"t":"王问那妇人，她就把事情告诉王。于是王为她派一个官员，说：“凡属这妇人的都还给她，自从她离开本地直到今日，她田地的出产也都还给她。”","notes":[]},{"n":7,"t":"以利沙来到大马士革，亚兰王便．哈达正患病。有人告诉王说：“神人来到这里了。”","notes":[],"heads":["以利沙和便．哈达王"]},{"n":8,"t":"王就吩咐哈薛说：“你带着礼物去见神人，托他求问耶和华，我这病能不能好？”","notes":[]},{"n":9,"t":"于是哈薛用四十匹骆驼，驮着大马士革的各样美物为礼物，去迎见以利沙。哈薛到了那里，站在他面前，说：“你儿子亚兰王便．哈达派我到你这里，问说：‘我这病会不会好？’”","notes":[]},{"n":10,"t":"以利沙对哈薛说：“你回去告诉他说：‘你一定会好。’但耶和华指示我，他必定会死。”","notes":[]},{"n":11,"t":"神人定睛看着哈薛，直到他感到羞愧。神人就哭了。","notes":[]},{"n":12,"t":"哈薛说：“我主为什么哭？”他说：“因为我知道你必虐待以色列人，用火焚烧他们的堡垒，用刀杀死他们的壮丁，摔死他们的婴孩，剖开他们的孕妇。”","notes":[]},{"n":13,"t":"哈薛说：“仆人算什么，不过是一条狗，怎么能行这大事呢？”以利沙说：“耶和华指示我，你必作亚兰王。”","notes":[]},{"n":14,"t":"哈薛离开以利沙，回到他主人那里。主人对他说：“以利沙对你说了什么？”他说：“他告诉我你必能好。”","notes":[]},{"n":15,"t":"次日，哈薛拿被子浸在水中，蒙住王的脸，王就死了。于是哈薛篡了他的位。","notes":[]},{"n":16,"t":"亚哈的儿子以色列王约兰第五年－约沙法曾作犹大王－犹大王约沙法的儿子约兰登基作了犹大王。","notes":["有些古卷、七十士译本和其他古译本没有“约沙法曾作犹大王”。"],"heads":["犹大王约兰"]},{"n":17,"t":"约兰登基的时候年三十二岁，在耶路撒冷作王八年。","notes":[]},{"n":18,"t":"他行以色列诸王的道，正如亚哈家所行的，因他娶了亚哈的女儿为妻，行耶和华眼中看为恶的事。","notes":[]},{"n":19,"t":"耶和华却因他仆人大卫的缘故，不肯灭绝犹大，要照他所应许的，永远赐灯光给大卫和他的子孙。","notes":[]},{"n":20,"t":"约兰在位期间，以东背叛，自己立王治理他们，脱离犹大的权势。","notes":[]},{"n":21,"t":"约兰率领所有的战车过到撒益去。他夜间起来，攻打围困他的以东人和战车长；犹大军兵逃跑，各回自己的帐棚去了；","notes":[]},{"n":22,"t":"这样，以东背叛，脱离犹大的权势，直到今日。那时立拿也背叛了。","notes":[]},{"n":23,"t":"约兰其余的事，凡他所做的，不都写在《犹大列王记》上吗？","notes":[]},{"n":24,"t":"约兰与他祖先同睡，与他祖先同葬在大卫城，他儿子亚哈谢接续他作王。","notes":[]},{"n":25,"t":"亚哈的儿子以色列王约兰第十二年，犹大王约兰的儿子亚哈谢登基。","notes":[],"heads":["犹大王亚哈谢"]},{"n":26,"t":"他登基的时候年二十二岁，在耶路撒冷作王一年。他母亲名叫亚她利雅，是以色列王暗利的孙女。","notes":[]},{"n":27,"t":"亚哈谢行亚哈家的道，行耶和华眼中看为恶的事，与亚哈家一样，因为他是亚哈家的女婿。","notes":[]},{"n":28,"t":"他与亚哈的儿子约兰同往基列的拉末去，与亚兰王哈薛交战。亚兰人打伤了约兰，","notes":[]},{"n":29,"t":"约兰王回到耶斯列，医治在拉末与亚兰王哈薛打仗时，被亚兰人击打所受的伤。约兰的儿子犹大王亚哈谢因为亚哈的儿子约兰病了，就下到耶斯列看望他。","notes":["“拉末”是根据七十士译本；原文是“拉玛”，可能是“基列的拉末”的简称。"]}]},"9":{"heading":"耶户被膏为以色列王","verses":[{"n":1,"t":"以利沙先知叫了一个先知的门徒来，吩咐他：“你束上腰，手拿这瓶膏油往基列的拉末去。","notes":[]},{"n":2,"t":"你到了那里，要在那里寻找宁示的孙子，约沙法的儿子耶户。你去，使他从弟兄中起来，带他进最里面的内室，","notes":[]},{"n":3,"t":"把瓶里的膏油倒在他头上，说：‘耶和华如此说：我膏你作以色列王。’然后你就开门逃跑，不要等候。”","notes":[]},{"n":4,"t":"于是那青年，那年轻的先知往基列的拉末去了。","notes":[]},{"n":5,"t":"他到了那里，看哪，众军官都坐着，就说：“长官，我有话对你说。”耶户说：“你要对我们哪一个说呢？”他说：“长官，我要对你说。”","notes":[]},{"n":6,"t":"耶户就起来，进了内室，那青年把膏油倒在他头上，对他说：“耶和华－以色列的神如此说：‘我膏你作耶和华百姓以色列的王。","notes":[]},{"n":7,"t":"你要击杀你主人亚哈的全家，我好在耶洗别身上，为我仆人众先知和耶和华所有仆人的血伸冤。","notes":[]},{"n":8,"t":"亚哈全家都必灭亡，凡属亚哈的男丁，无论是奴役的、自由的，我必从以色列中剪除。","notes":[]},{"n":9,"t":"我必使亚哈的家像尼八儿子耶罗波安的家，又像亚希雅儿子巴沙的家。","notes":[]},{"n":10,"t":"至于耶洗别，狗必在耶斯列田里吃她，无人埋葬。’”于是那青年就开门逃跑了。","notes":[]},{"n":11,"t":"耶户出来，回到他主人的臣仆那里，有一人问他说：“平安吗？这疯狂的人为什么到你这里来呢？”他对他们说：“你们认得那人，也知道他在胡说。”","notes":[]},{"n":12,"t":"他们说：“说谎！告诉我们吧。”他说：“他如此如此对我说：‘耶和华如此说：我膏你作以色列的王。’”","notes":[]},{"n":13,"t":"他们各人就急忙把自己的衣服铺在台阶的上层，在耶户的下面；他们吹角，说：“耶户作王了！”","notes":[]},{"n":14,"t":"这样，宁示的孙子，约沙法的儿子耶户背叛了约兰。先前约兰和以色列众人因为亚兰王哈薛的缘故，把守基列的拉末。","notes":[],"heads":["以色列王约兰被杀"]},{"n":15,"t":"后来约兰王回到耶斯列，医治他与亚兰王哈薛打仗时，被亚兰人击打所受的伤。耶户说：“若你们有这样的意思，就不要让人溜出城，到耶斯列去报信。”","notes":[]},{"n":16,"t":"于是耶户驾战车往耶斯列去，因为约兰卧病在那里。犹大王亚哈谢已经下去看望他。","notes":[]},{"n":17,"t":"有一个守望的人站在耶斯列的城楼上，看见耶户带着一队人来，就说：“我看见一队人。”约兰说：“派一个骑兵去迎接他们，问说：‘平安吗？’”","notes":[]},{"n":18,"t":"骑兵就去迎接耶户，说：“王如此说：‘平安吗？’”耶户说：“平安不平安跟你有什么关系呢？转身跟在我后面吧！”守望的人说：“使者到了他们那里，却不回来。”","notes":[]},{"n":19,"t":"王又派第二个骑兵去。这人到了他们那里，说：“王如此说：‘平安吗？’”耶户说：“平安不平安跟你有什么关系呢？转身跟在我后面吧！”","notes":[]},{"n":20,"t":"守望的人又说：“他到了他们那里，也不回来。车驾得很凶猛，好像宁示的孙子耶户在驾车。”","notes":[]},{"n":21,"t":"约兰吩咐说：“套车！”人就给他套车。以色列王约兰和犹大王亚哈谢各坐自己的车出去迎接耶户，在耶斯列人拿伯的田那里遇见他。","notes":[]},{"n":22,"t":"约兰见耶户就说：“耶户，平安吗？”耶户说：“你母亲耶洗别的淫行邪术这样多，怎么能平安呢？”","notes":[]},{"n":23,"t":"约兰用手转过车来逃跑，对亚哈谢说：“亚哈谢啊，反了！”","notes":[]},{"n":24,"t":"耶户全力拉弓，射中约兰两臂中间，箭从心窝穿出，约兰就仆倒在车上。","notes":[]},{"n":25,"t":"耶户对他的军官毕甲说：“把他抛在耶斯列人拿伯的田里。你当记得，你我一同驾车跟随他父亲亚哈的时候，耶和华对亚哈说了预言，","notes":[]},{"n":26,"t":"耶和华说：‘我昨日看见拿伯的血和他众子的血，我发誓我必在这块田上报应你。’这是耶和华说的。现在你要照着耶和华的话，把他抛在这田里。”","notes":[]},{"n":27,"t":"犹大王亚哈谢看见了，就沿着伯．哈干的路逃跑。耶户追赶他，说：“把这人也击杀在车上，在靠近以伯莲的姑珥坡上。”他逃到米吉多，就死在那里。","notes":["“把这人...坡上”：七十士译本是“‘把这人也击杀了！’有一人就在靠近以伯莲的盖坡上把他击杀在车上。”"],"heads":["犹大王亚哈谢被杀"]},{"n":28,"t":"他的臣仆用车把他的尸体运回耶路撒冷，与他祖先同葬在大卫城，他自己的坟墓里。","notes":[]},{"n":29,"t":"亚哈的儿子约兰第十一年，亚哈谢登基作了犹大王。","notes":[]},{"n":30,"t":"耶户到了耶斯列。耶洗别听见了，就画眼影、梳头，从窗户往外观看。","notes":[],"heads":["耶洗别王后被杀"]},{"n":31,"t":"耶户进了城门，耶洗别说：“杀主人的心利啊，平安吗？”","notes":[]},{"n":32,"t":"耶户向窗户抬头，说：“有谁顺从我？谁？”有两三个太监向外看他。","notes":[]},{"n":33,"t":"耶户说：“把她抛下来！”他们就把她抛下来。她的血溅在墙上和马上，耶户践踏在她身上。","notes":[]},{"n":34,"t":"耶户进去，吃了喝了，说：“你们去处理这被诅咒的妇人，埋了她，因为她是王的女儿。”","notes":[]},{"n":35,"t":"他们去了，要埋葬她，却只找到她的头骨和脚，以及手掌。","notes":[]},{"n":36,"t":"他们回来报告耶户，耶户说：“这正应验耶和华藉他仆人提斯比人以利亚所说的话，说：‘在耶斯列田里，狗必吃耶洗别的肉，","notes":[]},{"n":37,"t":"耶洗别的尸体必在耶斯列田里的地面上如同粪土，甚至没有人可说：这是耶洗别。’”","notes":[]}]},"10":{"heading":"耶户的信","verses":[{"n":1,"t":"亚哈有七十个儿子在撒玛利亚。耶户写信送到撒玛利亚，给耶斯列的领袖和长老，以及教养亚哈众儿子的人，说：","notes":["“耶斯列的领袖和长老”：有古卷是“耶斯列的领袖，就是长老”。"]},{"n":2,"t":"“你们主人的众儿子既然在你们那里，你们又有战车、马匹、兵器、坚固城，现在你们接了这信，","notes":[]},{"n":3,"t":"可以在你们主人的众儿子中选一个贤能正直的，使他坐他父亲的王位，你们也可以为你们主人的家作战。”","notes":[]},{"n":4,"t":"他们却非常惧怕，说：“看哪，两个王在他面前尚且站立不住，我们怎能站立得住呢？”","notes":[]},{"n":5,"t":"王宫总管、市长和长老，并教养众儿子的人，派人到耶户那里，说：“我们是你的仆人，凡你所吩咐的，我们都必遵行。我们不立谁作王，你看怎样好就怎样做吧。”","notes":[]},{"n":6,"t":"耶户写第二封信给他们，说：“你们若归顺我，听从我的话，明日这时候，要带着你们主人众儿子的首级，来到耶斯列我这里。”那时王的儿子七十人都住在城中教养他们的那些尊贵人家里。","notes":[],"heads":["亚哈的众儿子被杀"]},{"n":7,"t":"信一到他们那里，他们就把王的七十个儿子杀了，将首级装在筐里，送到耶斯列，耶户那里。","notes":[]},{"n":8,"t":"有使者来告诉耶户说：“他们把王众儿子的首级送来了。”耶户说：“把首级分成两堆，放在城门口，直到早晨。”","notes":[]},{"n":9,"t":"次日早晨，耶户出来，站着对众百姓说：“你们都是公义的！看哪，我背叛了我的主人，把他杀了，但这所有的人又是谁杀的呢？","notes":[]},{"n":10,"t":"由此可知，耶和华指着亚哈家所说的话一句也没有落空，因为耶和华实现了他藉他仆人以利亚所说的话。”","notes":[]},{"n":11,"t":"凡亚哈家在耶斯列所剩下的，他的大臣、密友、祭司，耶户全都杀了，没有留下一个幸存者。","notes":[]},{"n":12,"t":"耶户起身往撒玛利亚去。路途中，在牧人聚集的伯．艾克特，","notes":[],"heads":["亚哈谢的亲属被杀"]},{"n":13,"t":"耶户遇见犹大王亚哈谢的兄弟，说：“你们是谁？”他们说：“我们是亚哈谢的兄弟，现在下去要向王和太后的众儿子问安。”","notes":[]},{"n":14,"t":"耶户说：“活捉他们！”人就活捉了他们，把他们杀在伯．艾克特的坑边，共四十二人，一个也没有留下。","notes":[]},{"n":15,"t":"耶户从那里往前行，遇见利甲的儿子约拿达来迎接他，耶户向他问安，对他说：“你的心，像我的心待你的心那样正直吗？”约拿达说：“是。”耶户说：“若是这样，请你伸出手来。”他伸出手，耶户就拉他上车。","notes":["“你的心”：七十士译本是“你的心待我的心”。"]},{"n":16,"t":"耶户说：“你和我同去，看我为耶和华怎样热心。”于是他们请他坐在车上。","notes":[]},{"n":17,"t":"到了撒玛利亚，耶户把亚哈家在撒玛利亚剩下的人全都杀了，直到灭尽，正如耶和华对以利亚所说的话。","notes":[]},{"n":18,"t":"耶户召集众百姓，对他们说：“亚哈事奉巴力还不够热心，耶户更要热心。","notes":[],"heads":["拜巴力的人被杀"]},{"n":19,"t":"现在你们召集巴力的众先知和所有拜巴力的人，以及巴力的众祭司，都到我这里来，一个也不可缺少，因为我要给巴力献大祭；凡不来的必不得活。”耶户行诡诈，为要消灭拜巴力的人。","notes":[]},{"n":20,"t":"耶户说：“要为巴力召集严肃会！”于是他们宣告了。","notes":[]},{"n":21,"t":"耶户派人走遍以色列；凡拜巴力的人都来齐了，没有留下一个不来的。他们进了巴力庙，巴力庙中前后都挤满了人。","notes":[]},{"n":22,"t":"耶户对掌管服装的人说：“拿出袍子来，给所有拜巴力的人穿。”他就拿出礼服来给了他们。","notes":[]},{"n":23,"t":"耶户和利甲的儿子约拿达进了巴力庙，对拜巴力的人说：“你们要搜查察看，不可以有耶和华的仆人在你们这里，只可以有拜巴力的人。”","notes":[]},{"n":24,"t":"他们进去，献上祭物和燔祭，耶户先安排八十人在庙外，说：“我把这些人交在你们手中，谁放走其中一人，谁就要以命偿命！”","notes":[]},{"n":25,"t":"耶户献完了燔祭，就对护卫兵和众军官说：“进去杀他们，不要让一人逃脱！”护卫兵和军官用刀杀了他们，将尸体抛出去，然后进入巴力庙的堡垒，","notes":[]},{"n":26,"t":"将巴力庙中的柱像都拿出来焚烧。","notes":["“柱像都”：七十士译本和其他古译本是“那根柱像”。"]},{"n":27,"t":"他们毁坏巴力的柱像，拆毁了巴力庙当厕所，直到今日。","notes":[]},{"n":28,"t":"这样，耶户在以色列中消灭了巴力。","notes":[]},{"n":29,"t":"只是耶户不离开尼八的儿子耶罗波安使以色列人陷入罪里的那罪，就是拜伯特利和但的金牛犊。","notes":[]},{"n":30,"t":"耶和华对耶户说：“因你办好我眼中看为正的事，照我的心意待亚哈家，你的子孙必接续你坐以色列的王位，直到第四代。”","notes":[]},{"n":31,"t":"只是耶户不尽心遵守耶和华－以色列神的律法，不离开耶罗波安使以色列人陷入罪里的那罪。","notes":[]},{"n":32,"t":"在那些日子，耶和华开始削弱以色列。哈薛在以色列各边界攻击他们，","notes":[],"heads":["耶户去世"]},{"n":33,"t":"就是约旦河东基列全地，从靠近亚嫩谷边的亚罗珥起，包括基列和巴珊，就是迦得人、吕便人、玛拿西人的地。","notes":[]},{"n":34,"t":"耶户其余的事，凡他所做的和他英勇的事迹，不都写在《以色列诸王记》上吗？","notes":[]},{"n":35,"t":"耶户与他祖先同睡，葬在撒玛利亚，他儿子约哈斯接续他作王。","notes":[]},{"n":36,"t":"耶户在撒玛利亚作以色列王二十八年。","notes":[]}]},"11":{"heading":"亚她利雅篡位","verses":[{"n":1,"t":"亚哈谢的母亲亚她利雅见她儿子死了，就起来剿灭王室所有的后裔。","notes":[]},{"n":2,"t":"但约兰王的女儿，亚哈谢的妹妹约示巴，将亚哈谢的儿子约阿施从被杀的王子中偷出来，把他和他的奶妈藏在卧房里，躲避了亚她利雅，没有被杀。","notes":[]},{"n":3,"t":"亚她利雅治理这地的时候，约阿施和他的奶妈在耶和华的殿里藏了六年。","notes":[]},{"n":4,"t":"第七年，耶何耶大派人叫迦利人和护卫兵的众百夫长来，领他们进耶和华的殿，与他们立约，使他们在耶和华殿里起誓，又把王的儿子指给他们看，","notes":[]},{"n":5,"t":"吩咐他们说：“你们要这样做：你们当中在安息日值班的，三分之一要把守王宫，","notes":[]},{"n":6,"t":"三分之一要在苏珥门，三分之一要在护卫兵院的后门；你们要这样轮流把守王宫。","notes":[]},{"n":7,"t":"你们安息日所有不值班的两队人员要在耶和华的殿里护卫王；","notes":[]},{"n":8,"t":"各人手拿兵器，四围保护王。凡擅自闯入你们行列的，要被处死。王出入的时候，你们当跟随他。”","notes":[]},{"n":9,"t":"众百夫长就照着耶何耶大祭司一切所吩咐的去做，各带自己的人，无论安息日值班或不值班的，都到耶何耶大祭司那里。","notes":[]},{"n":10,"t":"祭司就把耶和华殿里所藏大卫王的枪和盾牌交给百夫长。","notes":[]},{"n":11,"t":"护卫兵手中各拿兵器，在祭坛和殿那里，从殿南到殿北，站在王的四围。","notes":[]},{"n":12,"t":"耶何耶大领约阿施 出来，给他戴上冠冕，把律法书交给他，膏他作王；众人都鼓掌说：“愿王万岁！”","notes":["“约阿施”：原文是“王的儿子”。"]},{"n":13,"t":"亚她利雅听见护卫兵和百姓的声音，就进耶和华的殿，到百姓那里。","notes":[]},{"n":14,"t":"她观看，看哪，王照仪式站在柱旁，百夫长和号手在王旁边，国中的众百姓欢乐吹号。亚她利雅就撕裂衣服，喊着说：“反了！反了！”","notes":[]},{"n":15,"t":"耶何耶大祭司吩咐管军兵的百夫长，对他们说：“把她从行列之间赶出去，凡跟随她的必用刀杀死！”因为祭司说：“不可在耶和华殿里杀她。”","notes":[]},{"n":16,"t":"他们就下手拿住她；她进入通往王宫的马门，就在那里被杀。","notes":[]},{"n":17,"t":"耶何耶大使王和百姓与耶和华立约，作耶和华的子民，又使王与百姓立约。","notes":[],"heads":["耶何耶大的改革"]},{"n":18,"t":"于是国中的众百姓都到巴力庙去，拆毁了庙，彻底打碎祭坛和偶像，又在坛前把巴力的祭司玛坦杀了。耶何耶大祭司派官员看守耶和华的殿，","notes":[]},{"n":19,"t":"又率领百夫长，迦利人和护卫兵，以及国中的众百姓，请王从耶和华的殿下来，由护卫兵的门进入王宫，他就坐上王位。","notes":[]},{"n":20,"t":"国中的众百姓都欢乐，合城也都平静。他们已将亚她利雅在王宫那里用刀杀了。","notes":[]},{"n":21,"t":"约阿施登基的时候年方七岁。","notes":[]}]},"12":{"heading":"犹大王约阿施","verses":[{"n":1,"t":"耶户第七年，约阿施登基，在耶路撒冷作王四十年。他母亲名叫西比亚，是别是巴人。","notes":[]},{"n":2,"t":"约阿施在耶何耶大祭司教导他的一切日子，行耶和华眼中看为正的事。","notes":[]},{"n":3,"t":"只是丘坛还没有废去，百姓仍在丘坛献祭烧香。","notes":[]},{"n":4,"t":"约阿施对众祭司说：“凡献到耶和华殿分别为圣的银子，无论是人的赎价，各人生命的赎价， 或自愿献给耶和华殿的银子，","notes":[]},{"n":5,"t":"祭司可以各自从认识的人收取，用来修理殿的破坏之处，就是在那里发现的一切破坏之处。”","notes":[]},{"n":6,"t":"然而，到了约阿施王第二十三年，祭司仍未修理殿的破坏之处。","notes":[]},{"n":7,"t":"所以约阿施王召了耶何耶大祭司和众祭司来，对他们说：“你们怎么不修理殿的破坏之处呢？现在，不要再从认识的人收银子了，但要为了殿的破坏之处，把银子交出来。”","notes":[]},{"n":8,"t":"众祭司答应不再收百姓的银子，也不再修理殿的破坏之处。","notes":[]},{"n":9,"t":"耶何耶大祭司取了一个柜子，在柜盖上钻了一个洞，放在祭坛旁，在进耶和华殿的右边；守门的祭司将献到耶和华殿的一切银子投在柜里。","notes":[]},{"n":10,"t":"他们见柜里的银子多了，就叫王的书记和大祭司上来，将耶和华殿里所得的银子数点了，包起来。","notes":[]},{"n":11,"t":"他们把秤好了的银子交在管理耶和华殿督工的手里，督工就支付给木匠和建造耶和华殿的工人，","notes":[]},{"n":12,"t":"瓦匠和石匠，又买木料和凿成的石头，用来修理耶和华殿的破坏之处，以及其他修理殿的各项费用。","notes":[]},{"n":13,"t":"但这些献到耶和华殿的银子，并没有用来造耶和华殿里的银杯、钳子、盘子、号筒和其他的金银器皿。","notes":[]},{"n":14,"t":"他们把这银子交给工人，用来整修耶和华的殿。","notes":[]},{"n":15,"t":"他们不用跟这些经手接受银子去支付工人的人算账，因为这些人办事诚实。","notes":[]},{"n":16,"t":"赎愆祭和赎罪祭的银子没有献到耶和华的殿里，都归给祭司。","notes":[]},{"n":17,"t":"那时，亚兰王哈薛上来攻打迦特，攻取了它。哈薛就定意上来攻打耶路撒冷。","notes":[]},{"n":18,"t":"犹大王约阿施将他祖先犹大王约沙法、约兰、亚哈谢所分别为圣的物和自己所分别为圣的物，以及耶和华殿与王宫府库里所有的金子都送给亚兰王哈薛；哈薛就不上耶路撒冷来了。","notes":[]},{"n":19,"t":"约阿施其余的事，凡他所做的，不都写在《犹大列王记》上吗？","notes":[]},{"n":20,"t":"约阿施的臣仆起来背叛，在下到悉拉路上的米罗宫那里把他杀了。","notes":[]},{"n":21,"t":"杀他的臣仆就是示米押的儿子约撒拔和朔默的儿子约萨拔。他与祖先同葬在大卫城，他儿子亚玛谢接续他作王。","notes":["“约撒拔”：有古卷是“约撒甲”。"]}]},"13":{"heading":"以色列王约哈斯","verses":[{"n":1,"t":"亚哈谢的儿子犹大王约阿施第二十三年，耶户的儿子约哈斯在撒玛利亚登基作以色列王十七年。","notes":[]},{"n":2,"t":"约哈斯行耶和华眼中看为恶的事，效法尼八的儿子耶罗波安使以色列陷入罪里的那罪，总不离开。","notes":[]},{"n":3,"t":"于是，耶和华的怒气向以色列发作，将他们屡次交在亚兰王哈薛和他儿子便．哈达的手里。","notes":[]},{"n":4,"t":"约哈斯恳求耶和华，耶和华就应允他，因为耶和华看见以色列所受的欺压，因亚兰王欺压他们。","notes":[]},{"n":5,"t":"耶和华赐给以色列一位拯救者，使他们脱离亚兰人的手，于是以色列人仍旧安居在自己的帐棚里。","notes":[]},{"n":6,"t":"然而他们不离开耶罗波安家使以色列陷入罪里的那罪，仍行在罪中，并且在撒玛利亚留下亚舍拉。","notes":[]},{"n":7,"t":"亚兰王灭绝约哈斯的军队，践踏他们如禾场上的尘沙，只给约哈斯留下五十骑兵，十辆战车，一万步兵。","notes":[]},{"n":8,"t":"约哈斯其余的事，凡他所做的和他英勇的事迹，不都写在《以色列诸王记》上吗？","notes":[]},{"n":9,"t":"约哈斯与他祖先同睡，葬在撒玛利亚，他儿子约阿施接续他作王。","notes":[]},{"n":10,"t":"犹大王约阿施第三十七年，约哈斯的儿子约阿施在撒玛利亚登基作以色列王十六年。","notes":[],"heads":["以色列王约阿施"]},{"n":11,"t":"他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列陷入罪里的一切罪，仍行在罪中。","notes":[]},{"n":12,"t":"约阿施其余的事，凡他所做的和他与犹大王亚玛谢交战的英勇事迹，不都写在《以色列诸王记》上吗？","notes":[]},{"n":13,"t":"约阿施与他祖先同睡，耶罗波安坐上他的王位。约阿施与以色列诸王一同葬在撒玛利亚。","notes":[]},{"n":14,"t":"以利沙得了致命的病，以色列王约阿施下来看他，伏在他脸上哭泣，说：“我父啊！我父啊！以色列的战车和骑兵啊！”","notes":[],"heads":["以利沙去世"]},{"n":15,"t":"以利沙对他说：“把弓箭拿来。”王就拿了弓箭来。","notes":[]},{"n":16,"t":"以利沙对以色列王说：“你用手开弓。”王就用手开弓。以利沙按手在王的手上，","notes":[]},{"n":17,"t":"说：“打开朝东的窗户。”他就打开。以利沙说：“射箭！”他就射箭。以利沙说：“这是耶和华得胜的箭，是战胜亚兰人的箭，因为你必在亚弗攻打亚兰人，直到灭尽他们。”","notes":[]},{"n":18,"t":"以利沙又说：“拿几枝箭来。”他就拿了来。以利沙对以色列王说：“打地吧！”他打了三次，就停止了。","notes":[]},{"n":19,"t":"神人向他发怒，说：“你应当击打五六次，就能攻打亚兰人直到灭尽；现在你只能打败亚兰人三次。”","notes":[]},{"n":20,"t":"以利沙死了，人把他埋葬了。新的一年，摩押人成群结队入侵境内。","notes":[]},{"n":21,"t":"有人正在埋葬死人，看哪，他们看见一群人来，就把死人抛在以利沙的坟墓里，逃跑了。死人一碰到以利沙的骸骨，就活过来，用脚站了起来。","notes":[]},{"n":22,"t":"约哈斯在位年间，亚兰王哈薛屡次欺压以色列。","notes":[],"heads":["以色列与亚兰争战"]},{"n":23,"t":"耶和华却因与亚伯拉罕、以撒、雅各所立的约，仍施恩给以色列人，怜悯他们，眷顾他们，不肯灭尽他们，直到现在仍不赶逐他们离开自己面前。","notes":["七十士译本没有“直到现在”。"]},{"n":24,"t":"亚兰王哈薛死了，他儿子便．哈达接续他作王。","notes":[]},{"n":25,"t":"从前哈薛和约阿施的父亲约哈斯交战，攻取了些城镇，现在约哈斯的儿子约阿施三次打败哈薛的儿子便．哈达，从他手中收回了以色列的城镇。","notes":[]}]},"14":{"heading":"犹大王亚玛谢","verses":[{"n":1,"t":"约哈斯的儿子以色列王约阿施第二年，犹大王约阿施的儿子亚玛谢登基。","notes":[]},{"n":2,"t":"他登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫约耶但，是耶路撒冷人。","notes":[]},{"n":3,"t":"亚玛谢行耶和华眼中看为正的事，但不如他祖先大卫。他效法他父亲约阿施一切所行的。","notes":[]},{"n":4,"t":"只是丘坛还没有废去，百姓仍在丘坛献祭烧香。","notes":[]},{"n":5,"t":"王国在他手里巩固的时候，他就把杀他父王的臣仆杀了，","notes":[]},{"n":6,"t":"却没有处死杀王凶手的儿子，正如摩西律法书上耶和华所吩咐的说：“不可因子杀父，也不可因父杀子，各人要为自己的罪而死。”","notes":[]},{"n":7,"t":"亚玛谢在盐谷杀了一万以东人，又在战役中攻取了西拉，称它为约帖，直到今日。","notes":[]},{"n":8,"t":"那时，亚玛谢派使者到耶户的孙子，约哈斯的儿子以色列王约阿施那里，说：“来，让我们面对面较量吧！”","notes":[]},{"n":9,"t":"以色列王约阿施派人去见犹大王亚玛谢，说：“黎巴嫩的蒺藜派人去见黎巴嫩的香柏树，说：‘将你的女儿嫁给我的儿子。’但有一只野兽经过黎巴嫩，把蒺藜践踏了。","notes":[]},{"n":10,"t":"你果然打败了以东，就心高气傲。你以此为荣，就待在自己家里算了吧，为何要惹祸，使自己和犹大一同败亡呢？”","notes":[]},{"n":11,"t":"亚玛谢却不肯听从。于是以色列王约阿施上来，在犹大的伯．示麦与犹大王亚玛谢面对面较量。","notes":[]},{"n":12,"t":"犹大败在以色列面前，他们逃跑，各人逃回自己的帐棚去了。","notes":[]},{"n":13,"t":"以色列王约阿施在伯．示麦擒住亚哈谢的孙子，约阿施的儿子犹大王亚玛谢，就来到耶路撒冷，拆毁耶路撒冷的城墙，从以法莲门直到角门共四百肘。","notes":[]},{"n":14,"t":"他又拿了耶和华殿里与王宫府库里所有的金银和器皿，并带着人质，回撒玛利亚去了。","notes":[]},{"n":15,"t":"约阿施其余所做的事和他英勇的事迹，以及他与犹大王亚玛谢交战的事，不都写在《以色列诸王记》上吗？","notes":[]},{"n":16,"t":"约阿施与他祖先同睡，与以色列诸王一同葬在撒玛利亚，他儿子耶罗波安接续他作王。","notes":[]},{"n":17,"t":"约哈斯的儿子以色列王约阿施死后，犹大王约阿施的儿子亚玛谢又活了十五年。","notes":[],"heads":["犹大王亚玛谢去世"]},{"n":18,"t":"亚玛谢其余的事，不都写在《犹大列王记》上吗？","notes":[]},{"n":19,"t":"耶路撒冷有人背叛亚玛谢，亚玛谢逃往拉吉；他们却派人追到拉吉，在那里杀了他。","notes":[]},{"n":20,"t":"有人用马将他驮回，葬在耶路撒冷，与他祖先一同葬在大卫城。","notes":[]},{"n":21,"t":"犹大众百姓立亚撒利雅接续他父亲亚玛谢作王，那时他年十六岁。","notes":["“亚撒利雅”又名“乌西雅”，下同；参王下15．13。"]},{"n":22,"t":"亚玛谢王与他祖先同睡之后，亚撒利雅收复以拉他回归犹大，又重新整修。","notes":[]},{"n":23,"t":"约阿施的儿子犹大王亚玛谢第十五年，以色列王约阿施的儿子耶罗波安在撒玛利亚登基，作王四十一年。","notes":[],"heads":["以色列王耶罗波安二世"]},{"n":24,"t":"他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列陷入罪里的一切罪。","notes":[]},{"n":25,"t":"他收回以色列边界之地，从哈马口直到亚拉巴海，正如耶和华－以色列的神藉他仆人迦特．希弗人亚米太的儿子约拿先知所说的。","notes":[]},{"n":26,"t":"因耶和华看见以色列非常艰苦的困境；没有奴役的，没有自由的，也没有人来帮助以色列。","notes":[]},{"n":27,"t":"耶和华并没有说要将以色列的名从天下涂抹，却要藉约阿施的儿子耶罗波安拯救他们。","notes":[]},{"n":28,"t":"耶罗波安其余的事，凡他所做的和他英勇的事迹，他怎样作战，怎样收复大马士革和先前属犹大的哈马回归以色列，不都写在《以色列诸王记》上吗？","notes":[]},{"n":29,"t":"耶罗波安与他祖先以色列诸王同睡，他儿子撒迦利雅接续他作王。","notes":[]}]},"15":{"heading":"犹大王亚撒利雅","verses":[{"n":1,"t":"以色列王耶罗波安第二十七年，犹大王亚玛谢的儿子亚撒利雅登基。","notes":[]},{"n":2,"t":"他登基的时候年十六岁，在耶路撒冷作王五十二年。他母亲名叫耶可利雅，是耶路撒冷人。","notes":[]},{"n":3,"t":"亚撒利雅行耶和华眼中看为正的事，效法他父亲亚玛谢一切所行的。","notes":[]},{"n":4,"t":"只是丘坛还没有废去，百姓仍在丘坛献祭烧香。","notes":[]},{"n":5,"t":"耶和华降灾于王，使他长了麻风，直到死的那日。他住在隔离的行宫里，他儿子约坦管理王的家，治理这地的百姓。","notes":[]},{"n":6,"t":"亚撒利雅其余的事，凡他所做的，不都写在《犹大列王记》上吗？","notes":[]},{"n":7,"t":"亚撒利雅与他祖先同睡，与他祖先同葬在大卫城，他儿子约坦接续他作王。","notes":[]},{"n":8,"t":"犹大王亚撒利雅第三十八年，耶罗波安的儿子撒迦利雅登基，在撒玛利亚作以色列王六个月。","notes":[],"heads":["以色列王撒迦利雅"]},{"n":9,"t":"他行耶和华眼中看为恶的事，效法他祖先所行的，不离开尼八的儿子耶罗波安使以色列陷入罪里的那罪。","notes":[]},{"n":10,"t":"雅比的儿子沙龙背叛他，在百姓面前击杀他，篡了他的位。","notes":["“在百姓面前”：七十士译本的一些抄本是“在以伯莲”。"]},{"n":11,"t":"撒迦利雅其余的事，看哪，都写在《以色列诸王记》上。","notes":[]},{"n":12,"t":"这就是耶和华应许耶户的话：“你的子孙必坐以色列的王位，直到第四代。”这事果然发生了。","notes":[]},{"n":13,"t":"犹大王乌西雅第三十九年，雅比的儿子沙龙登基，在撒玛利亚作王一个月。","notes":["“乌西雅”又名“亚撒利雅”，下同；参王下14．21。"],"heads":["以色列王沙龙"]},{"n":14,"t":"迦底的儿子米拿现从得撒上撒玛利亚，杀了雅比的儿子沙龙，篡了他的位。","notes":[]},{"n":15,"t":"沙龙其余的事和他阴谋背叛的事，看哪，都写在《以色列诸王记》上。","notes":[]},{"n":16,"t":"那时，米拿现从得撒起击杀提斐萨和城中所有的人，以及它周围的地区，因为他们没有给他开城门。他击杀他们，剖开其中所有的孕妇。","notes":["“提斐萨”：七十士译本的一些抄本是“他普亚”。"]},{"n":17,"t":"犹大王亚撒利雅第三十九年，迦底的儿子米拿现登基，在撒玛利亚作以色列王十年。","notes":[],"heads":["以色列王米拿现"]},{"n":18,"t":"他行耶和华眼中看为恶的事，终生不离开尼八的儿子耶罗波安使以色列陷入罪里的那罪。","notes":[]},{"n":19,"t":"亚述王普勒来攻击这地，米拿现给他一千他连得银子，为了请普勒帮助他巩固他所掌握的国度。","notes":[]},{"n":20,"t":"米拿现向以色列所有的富豪索取银子，要他们各出五十舍客勒，交给亚述王。于是亚述王回去了，不在境内停留。","notes":[]},{"n":21,"t":"米拿现其余的事，凡他所做的，不都写在《以色列诸王记》上吗？","notes":[]},{"n":22,"t":"米拿现与他祖先同睡，他儿子比加辖接续他作王。","notes":[]},{"n":23,"t":"犹大王亚撒利雅第五十年，米拿现的儿子比加辖登基，在撒玛利亚作以色列王二年。","notes":[],"heads":["以色列王比加辖"]},{"n":24,"t":"他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列陷入罪里的那罪。","notes":[]},{"n":25,"t":"比加辖的将军，利玛利的儿子比加背叛他，在撒玛利亚王宫的堡垒杀了他。亚珥歌伯和亚利耶并基列的五十人帮助比加；比加击杀他，篡了他的位。","notes":[]},{"n":26,"t":"比加辖其余的事，凡他所做的，看哪，都写在《以色列诸王记》上。","notes":[]},{"n":27,"t":"犹大王亚撒利雅第五十二年，利玛利的儿子比加登基，在撒玛利亚作以色列王二十年。","notes":[],"heads":["以色列王比加"]},{"n":28,"t":"他行耶和华眼中看为恶的事，不离开尼八的儿子耶罗波安使以色列陷入罪里的那罪。","notes":[]},{"n":29,"t":"在以色列王比加的日子，亚述王提革拉．毗列色来夺取以云、亚伯．伯．玛迦、亚挪、基低斯、夏琐、基列、加利利和拿弗他利全地，把这些地方的居民都掳到亚述去了。","notes":["“提革拉．毗列色”又名“普勒”；参19节。"]},{"n":30,"t":"乌西雅的儿子约坦第二十年，以拉的儿子何细亚背叛利玛利的儿子比加，击杀他，篡了他的位。","notes":[]},{"n":31,"t":"比加其余的事，凡他所做的，看哪，都写在《以色列诸王记》上。","notes":[]},{"n":32,"t":"利玛利的儿子以色列王比加第二年，犹大王乌西雅的儿子约坦登基。","notes":[],"heads":["犹大王约坦"]},{"n":33,"t":"他登基的时候年二十五岁，在耶路撒冷作王十六年。他母亲名叫耶路沙，是撒督的女儿。","notes":[]},{"n":34,"t":"约坦行耶和华眼中看为正的事，效法他父亲乌西雅一切所行的。","notes":[]},{"n":35,"t":"只是丘坛还没有废去，百姓仍在丘坛献祭烧香。约坦建了耶和华殿的上门。","notes":[]},{"n":36,"t":"约坦其余的事，凡他所做的，不都写在《犹大列王记》上吗？","notes":[]},{"n":37,"t":"在那些日子，耶和华开始差亚兰王利汛和利玛利的儿子比加去攻击犹大。","notes":[]},{"n":38,"t":"约坦与他祖先同睡，与他祖先同葬在大卫城，他儿子亚哈斯接续他作王。","notes":[]}]},"16":{"heading":"犹大王亚哈斯","verses":[{"n":1,"t":"利玛利的儿子比加第十七年，犹大王约坦的儿子亚哈斯登基。","notes":[]},{"n":2,"t":"他登基的时候年二十岁，在耶路撒冷作王十六年。他不像他祖先大卫行耶和华－他神眼中看为正的事，","notes":[]},{"n":3,"t":"却行以色列诸王的道，又照着耶和华从以色列人面前赶出的外邦人所行可憎的事，使他的儿子经火，","notes":[]},{"n":4,"t":"并在丘坛上、山冈上、各青翠树下献祭烧香。","notes":[]},{"n":5,"t":"那时，亚兰王利汛和利玛利的儿子以色列王比加上来攻打耶路撒冷，围困亚哈斯，却不能打胜。","notes":[]},{"n":6,"t":"当时亚兰王利汛收复以拉他回归亚兰，把犹大人从以拉他赶出去。以东人来到以拉他，住在那里，直到今日。","notes":[]},{"n":7,"t":"亚哈斯派使者到亚述王提革拉．毗列色那里，说：“我是你的仆人，你的儿子。现在亚兰王和以色列王攻击我，求你上来，救我脱离他们的手。”","notes":[]},{"n":8,"t":"亚哈斯将耶和华殿里和王宫府库里所有的金银都送给亚述王为礼物。","notes":[]},{"n":9,"t":"亚述王答应了他，上去攻打大马士革，攻下了城，杀了利汛，把居民掳到吉珥。","notes":[]},{"n":10,"t":"亚哈斯王到大马士革迎接亚述王提革拉．毗列色，在大马士革看见一座坛。亚哈斯王把坛的规模和样式，以及作法的细节，送到乌利亚祭司那里。","notes":[]},{"n":11,"t":"乌利亚祭司照着亚哈斯王从大马士革所送来的一切，在亚哈斯王还未从大马士革回来之前，筑了一座坛。","notes":[]},{"n":12,"t":"王从大马士革回来，看见坛，走近坛前，在坛上献祭。","notes":[]},{"n":13,"t":"他烧燔祭和素祭，献浇酒祭，将平安祭牲的血洒在坛上。","notes":[]},{"n":14,"t":"他移动耶和华面前的铜坛，从殿的前面，新坛和耶和华殿的中间，搬到新坛的北边。","notes":[]},{"n":15,"t":"亚哈斯王吩咐乌利亚祭司说：“早晨的燔祭、晚上的素祭，王的燔祭、素祭，国内众百姓的燔祭、素祭、浇酒祭都要烧在大坛上。燔祭牲和其他祭牲的血全都要洒在这坛上。至于铜坛，我要作求问之用。”","notes":[]},{"n":16,"t":"乌利亚祭司就照着亚哈斯王所吩咐的一切做了。","notes":[]},{"n":17,"t":"亚哈斯王把盆座四面的嵌边拆下来，把盆从座上挪下来，又将铜海从驮铜海的铜牛上搬下来，放在石板铺的地上。","notes":[]},{"n":18,"t":"他为了亚述王的缘故，在耶和华的殿里移动殿里为安息日所盖的遮棚和王从外面进来的入口。","notes":["“在耶和华的殿里移动”：有些古译本是“从耶和华的殿移走”。","“为安息日所盖的遮棚”：七十士译本是“宝座的底座”。"]},{"n":19,"t":"亚哈斯其余所做的事，不都写在《犹大列王记》上吗？","notes":[]},{"n":20,"t":"亚哈斯与他祖先同睡， 与他祖先同葬在大卫城，他儿子希西家接续他作王。","notes":[]}]},"17":{"heading":"以色列王何细亚","verses":[{"n":1,"t":"犹大王亚哈斯第十二年，以拉的儿子何细亚在撒玛利亚登基作以色列王九年。","notes":[]},{"n":2,"t":"他行耶和华眼中看为恶的事，只是不像在他以前的以色列诸王。","notes":[]},{"n":3,"t":"亚述王撒缦以色上来攻击何细亚，何细亚就服事他，向他进贡。","notes":[]},{"n":4,"t":"何细亚背叛，派使者到埃及王梭那里，不照往年所行的向亚述王进贡。亚述王知道了，就逮捕他，把他囚在监里。","notes":["“到埃及王梭那里”或译“到梭，埃及王那里”。"]},{"n":5,"t":"亚述王上来攻击以色列全地，上到撒玛利亚，围困这城三年。","notes":[]},{"n":6,"t":"何细亚第九年，亚述王攻取了撒玛利亚，把以色列人掳到亚述，安置在哈腊与歌散的哈博河边，以及玛代人的城镇。","notes":[]},{"n":7,"t":"这是因为以色列人得罪了那领他们出埃及地、脱离埃及王法老之手的耶和华－他们的神，去敬畏别神，","notes":[]},{"n":8,"t":"随从耶和华在以色列人面前所赶出外邦人的风俗和以色列诸王所立的规条。","notes":[]},{"n":9,"t":"以色列人暗中行不正的事，违背耶和华－他们的神，在他们所有的城镇，从瞭望楼直到坚固城，建筑丘坛；","notes":[]},{"n":10,"t":"在各高冈上、各青翠树下立柱像和亚舍拉；","notes":[]},{"n":11,"t":"在各丘坛上烧香，效法耶和华在他们面前赶出的外邦人所行的，又行恶事，惹耶和华发怒。","notes":[]},{"n":12,"t":"他们事奉偶像，耶和华对他们说：“你们不可做这事。”","notes":[]},{"n":13,"t":"耶和华藉众先知、先见劝戒以色列和犹大说：“当离开你们的恶行，谨守我的诫命律例，遵行我吩咐你们祖先、藉我仆人众先知所传给你们的一切律法。”","notes":[]},{"n":14,"t":"他们却不听从，竟硬着颈项，像他们祖先一样，不信服耶和华－他们的神。","notes":[]},{"n":15,"t":"他们厌弃他的律例，和他与他们列祖所立的约，以及他劝戒他们的话，去随从虚无的神明，自己成为虚妄，效法周围的列国，就是耶和华嘱咐他们不可效法的。","notes":["“虚无的神明”：原文是“虚无”。"]},{"n":16,"t":"他们离弃耶和华－他们神的一切诫命，为自己铸造了两个牛犊的像，立了亚舍拉，敬拜天上的万象，事奉巴力，","notes":[]},{"n":17,"t":"使他们的儿女经火，占卜，行法术，出卖自己，行耶和华眼中看为恶的事，惹他发怒。","notes":[]},{"n":18,"t":"所以耶和华向以色列大大发怒，从自己面前赶出他们，只剩下犹大一个支派。","notes":[]},{"n":19,"t":"但是，犹大也不遵守耶和华－他们神的诫命，效法以色列所立的规条。","notes":[]},{"n":20,"t":"耶和华就厌弃以色列所有的后裔，使他们受苦，把他们交在抢夺他们的人手中，直到他把他们从自己面前赶出去。","notes":[]},{"n":21,"t":"当他使以色列从大卫家分离出来的时候，他们立尼八的儿子耶罗波安作王。耶罗波安引诱以色列不随从耶和华，陷入大罪中。","notes":[]},{"n":22,"t":"以色列人行耶罗波安所犯的一切罪，总不离开，","notes":[]},{"n":23,"t":"以致耶和华把他们从自己面前赶出去，正如他藉他仆人众先知所说的。这样，以色列人从自己的土地被掳到亚述，直到今日。","notes":[]},{"n":24,"t":"亚述王从巴比伦、古他、亚瓦、哈马和西法瓦音迁移人来，安置在撒玛利亚的城镇，代替以色列人；他们就占据了撒玛利亚，住在城中。","notes":[],"heads":["亚述人定居于撒玛利亚"]},{"n":25,"t":"他们开始住在那里的时候，不敬畏耶和华，所以耶和华叫狮子进入他们中间，咬死了一些人。","notes":[]},{"n":26,"t":"有人对亚述王说：“你所迁移安置在撒玛利亚城镇的各国的人，他们不知道那地之神的规矩，所以他叫狮子进入他们中间。看哪，狮子咬死了他们，因为他们不知道那地之神的规矩。”","notes":[]},{"n":27,"t":"亚述王吩咐说：“当派一个从那里掳来的祭司回去，叫他住在那里，将那地之神的规矩指导他们。”","notes":[]},{"n":28,"t":"于是有一个从撒玛利亚掳去的祭司回来，住在伯特利，教导他们怎样敬畏耶和华。","notes":[]},{"n":29,"t":"然而，各国的人在所住的城里为自己制造神像，安置在撒玛利亚人所建有丘坛的庙中。","notes":[]},{"n":30,"t":"巴比伦人造疏割．比讷像；古他人造匿甲像；哈马人造亚示玛像；","notes":[]},{"n":31,"t":"亚瓦人造匿哈和他珥他像；西法瓦音人用火焚烧儿女，献给西法瓦音的神明亚得米勒和亚拿米勒。","notes":[]},{"n":32,"t":"他们惧怕耶和华，却从他们中间立丘坛的祭司，在丘坛的庙中为他们献祭。","notes":[]},{"n":33,"t":"他们惧怕耶和华，但又事奉自己的神明，从何邦迁来，就随从那里的风俗，","notes":[]},{"n":34,"t":"直到如今仍照先前的风俗去行。他们不敬畏耶和华，不遵守耶和华吩咐雅各后裔的律例、典章、律法、诫命；雅各就是从前耶和华起名叫以色列的。","notes":[]},{"n":35,"t":"耶和华曾与他们立约，吩咐他们说：“不可敬畏别神，不可跪拜事奉它们，也不可向它们献祭。","notes":[]},{"n":36,"t":"惟有那用大能和伸出来的膀臂领你们出埃及地的耶和华，你们当敬畏他，向他跪拜，向他献祭。","notes":[]},{"n":37,"t":"他给你们写的律例、典章、律法、诫命，你们应当永远谨守遵行。你们不可敬畏别神。","notes":[]},{"n":38,"t":"你们不可忘记我与你们所立的约，也不可敬畏别神。","notes":[]},{"n":39,"t":"只要敬畏耶和华－你们的神，他必救你们脱离一切仇敌的手。”","notes":[]},{"n":40,"t":"他们却不听从，仍照先前的风俗去行。","notes":[]},{"n":41,"t":"这样，这些国家又惧怕耶和华，又事奉他们的偶像。他们子子孙孙也都照样行，效法他们的祖宗，直到今日。","notes":[]}]},"18":{"heading":"犹大王希西家","verses":[{"n":1,"t":"以拉的儿子以色列王何细亚第三年，犹大王亚哈斯的儿子希西家登基。","notes":[]},{"n":2,"t":"他登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫亚比，是撒迦利雅的女儿。","notes":[]},{"n":3,"t":"希西家行耶和华眼中看为正的事，效法他祖先大卫一切所行的。","notes":[]},{"n":4,"t":"他废去丘坛，毁坏柱像，砍下亚舍拉，打碎摩西所造的铜蛇，因为到那时以色列人仍向铜蛇烧香。人叫铜蛇为尼忽士但。","notes":["“尼忽士但”是音译，发音与“蛇”和“铜”相近。"]},{"n":5,"t":"希西家倚靠耶和华－以色列的神，在他之前和在他之后的犹大列王中没有一个像他一样的。","notes":[]},{"n":6,"t":"因为他紧紧跟随耶和华，谨守耶和华所吩咐摩西的诫命，总不离开。","notes":[]},{"n":7,"t":"耶和华与他同在，他无论往何处去尽都亨通。他背叛亚述王，不服事他。","notes":[]},{"n":8,"t":"希西家攻击非利士人，直到迦萨，以及所属的领土，从瞭望楼到坚固城。","notes":[]},{"n":9,"t":"希西家王第四年，也就是以拉的儿子以色列王何细亚第七年，亚述王撒缦以色上来围困撒玛利亚。","notes":[]},{"n":10,"t":"过了三年，他们攻取了城。希西家第六年，以色列王何细亚第九年，撒玛利亚被攻取了。","notes":[]},{"n":11,"t":"亚述王把以色列人掳到亚述，安置在哈腊与歌散的哈博河边，以及玛代人的城镇。","notes":[]},{"n":12,"t":"这是因为他们不听从耶和华－他们的神的话，违背了他的约；他们既不听从，也不遵行耶和华仆人摩西一切所吩咐的。","notes":[]},{"n":13,"t":"希西家王十四年，亚述王西拿基立上来攻击犹大的一切坚固的城，将城攻取。","notes":[],"heads":["亚述威胁耶路撒冷"]},{"n":14,"t":"犹大王希西家派人到拉吉，亚述王那里，说：“我错了，求你撤退离开我；凡你罚我的，我必承当。”于是亚述王罚犹大王希西家三百他连得银子，三十他连得金子。","notes":[]},{"n":15,"t":"希西家把耶和华殿里和王宫府库里所有的银子都给了他。","notes":[]},{"n":16,"t":"那时，犹大王希西家将耶和华殿门上的金子和他自己包在柱子上的金子都刮下来，给了亚述王。","notes":[]},{"n":17,"t":"亚述王从拉吉差遣元帅、太监长和将军率领大军前往耶路撒冷，到希西家王那里去。他们上来，到耶路撒冷。他们上来之后，站在上池的水沟旁，在往漂布地的大路上。","notes":["“元帅”：原文是亚述的官职“他珥探”。","“太监长”：原文是亚述的官职“拉伯．撒利”。","“将军”：原文是亚述的官职“拉伯．沙基”，司令官；下同。"]},{"n":18,"t":"他们呼叫王，希勒家的儿子以利亚敬宫廷总管，舍伯那书记和亚萨的儿子约亚史官就出来见他们。","notes":[]},{"n":19,"t":"将军对他们说：“你们去告诉希西家，大王亚述王如此说：‘你倚靠什么，让你如此自信满满？","notes":[]},{"n":20,"t":"你说，你有打仗的计谋和能力，我看不过是空话。你到底倚靠谁，竟敢背叛我呢？","notes":[]},{"n":21,"t":"现在，看哪，你自己所倚靠的埃及是那断裂的苇杖，人若倚靠这杖，它就刺进他的手，穿透它。埃及王法老向所有倚靠他的人都是这样。","notes":[]},{"n":22,"t":"你们若对我说：我们倚靠耶和华－我们的神，希西家岂不是将神的丘坛和祭坛废去，并且吩咐犹大和耶路撒冷的人说：你们当在耶路撒冷这坛前敬拜吗？","notes":[]},{"n":23,"t":"现在你与我主亚述王打赌，我给你两千匹马，看你能否派得出骑士来骑它们。","notes":[]},{"n":24,"t":"若不然，怎能使我主臣仆中最小的一个军官转脸而逃呢？你难道要倚靠埃及的战车和骑兵吗？","notes":[]},{"n":25,"t":"现在我上来攻击毁灭这地方，岂不是出于耶和华吗？耶和华吩咐我说，你上去攻击这地，毁灭它吧！’”","notes":[]},{"n":26,"t":"希勒家的儿子以利亚敬，舍伯那和约亚对将军说：“求你用亚兰话对仆人说，因为我们听得懂；不要用犹大话对我们说，免得传到城墙上百姓的耳中。”","notes":[]},{"n":27,"t":"将军对他们说：“我主差遣我来，岂是单对你和你的主人说这些话吗？不也是对这些坐在城墙上、要与你们一同吃自己粪、喝自己尿的人说的吗？”","notes":[]},{"n":28,"t":"于是亚述将军站着，用犹大话大声喊着说：“你们当听大王亚述王的话，","notes":[]},{"n":29,"t":"王如此说：‘你们不要被希西家欺哄了，因他不能救你们脱离我的手。","notes":[]},{"n":30,"t":"不要听凭希西家说服你们倚靠耶和华，他说，耶和华必要拯救我们，这城必不交在亚述王的手中。’","notes":[]},{"n":31,"t":"你们不要听希西家的话！因亚述王如此说：‘你们要与我讲和，出来投降我，各人就可以吃自己葡萄树和无花果树的果子，喝自己井里的水，","notes":[]},{"n":32,"t":"等我来领你们到一个地方，与你们本地一样，就是有五谷和新酒之地，有粮食和葡萄园之地，有橄榄树和蜂蜜之地，好使你们存活，不至于死。不要听希西家的话，因为他误导你们说：耶和华必拯救我们。","notes":[]},{"n":33,"t":"列国的神明有哪一个曾救它本国脱离亚述王的手呢？","notes":[]},{"n":34,"t":"哈马、亚珥拔的神明在哪里呢？西法瓦音、希拿、以瓦的神明在哪里呢？它们曾救撒玛利亚脱离我的手吗？","notes":["七十士译本的一些抄本和其他古译本有“撒玛利亚地的神明在哪里呢？”"]},{"n":35,"t":"这些国的神明有谁曾救自己的国脱离我的手呢？难道耶和华能救耶路撒冷脱离我的手吗？’”","notes":[]},{"n":36,"t":"百姓静默不言，一句不答，因为希西家王曾吩咐说：“不要回答他。”","notes":[]},{"n":37,"t":"当下，希勒家的儿子以利亚敬宫廷总管、舍伯那书记和亚萨的儿子约亚史官，都撕裂衣服，来到希西家那里，将亚述将军的话告诉他。","notes":[]}]},"19":{"heading":"希西家王派人问以赛亚","verses":[{"n":1,"t":"希西家王听见了，就撕裂衣服，披上麻布，进了耶和华的殿。","notes":[]},{"n":2,"t":"他差遣以利亚敬宫廷总管和舍伯那书记，并祭司中年长的，都披上麻布，到亚摩斯的儿子以赛亚先知那里去。","notes":[]},{"n":3,"t":"他们对他说：“希西家如此说：‘今日是急难、惩罚、凌辱的日子，就如婴孩快要出生，却没有力气生产。","notes":[]},{"n":4,"t":"或许耶和华－你的神听见亚述将军一切的话，就是他主人亚述王差他来辱骂永生神的话，耶和华－你的神就斥责所听见的这些话。求你为幸存的余民扬声祷告。’”","notes":[]},{"n":5,"t":"希西家王的臣仆来到以赛亚那里的时候，","notes":[]},{"n":6,"t":"以赛亚对他们说：“要对你们的主人这样说，耶和华如此说：‘你听见亚述王的仆人亵渎我的话，不要惧怕。","notes":[]},{"n":7,"t":"看哪，我必惊动他的心，他要听见风声就归回本地，在那里我必使他倒在刀下。’”","notes":["“惊动他的心”：原文是“使灵进入他里面”。"]},{"n":8,"t":"亚述将军听见亚述王已拔营离开拉吉，就启程返回，正遇见亚述王去攻打立拿。","notes":[],"heads":["亚述王再度威胁"]},{"n":9,"t":"亚述王听见有人谈论古实王特哈加说：“看哪，他出来要与你争战。”于是亚述王又差使者去见希西家，说：","notes":[]},{"n":10,"t":"“你们要对犹大王希西家如此说：‘不要听你所倚靠的神欺哄你说：耶路撒冷必不交在亚述王的手中。","notes":[]},{"n":11,"t":"看哪，你总听说亚述诸王向列国所行的是尽行灭绝，难道你能幸免吗？","notes":[]},{"n":12,"t":"我祖先所毁灭的，就是歌散、哈兰、利色和提．拉撒的伊甸人；这些国的神明何曾拯救他们呢？","notes":[]},{"n":13,"t":"哈马的王，亚珥拔的王，西法瓦音城的王，希拿和以瓦的王，都在哪里呢？’”","notes":[]},{"n":14,"t":"希西家从使者手里接过书信，读完了，就上耶和华的殿，在耶和华面前展开书信。","notes":[]},{"n":15,"t":"希西家向耶和华祷告说：“坐在基路伯之上耶和华－以色列的神啊，你，惟有你是地上万国的神，你创造了天和地。","notes":[]},{"n":16,"t":"耶和华啊，求你侧耳而听；耶和华啊，求你睁眼而看，听西拿基立差遣使者辱骂永生神的话。","notes":[]},{"n":17,"t":"耶和华啊，亚述诸王果然使列国和列国之地变为荒芜，","notes":[]},{"n":18,"t":"将列国的神像扔在火里，因为它们不是神，是人手所造的，是木头、石头，所以被灭绝了。","notes":[]},{"n":19,"t":"耶和华－我们的神啊，现在求你救我们脱离亚述王的手，使地上万国都知道惟独你－耶和华是神！”","notes":[]},{"n":20,"t":"亚摩斯的儿子以赛亚差人去见希西家，说：“耶和华－以色列的神如此说：你因亚述王西拿基立的事向我祈求，我已听见了。","notes":[],"heads":["以赛亚给王的信息"]},{"n":21,"t":"耶和华论他这样说：‘少女锡安藐视你，嘲笑你；耶路撒冷向你摇头。","notes":["“少女锡安”：原文直译“少女锡安女子”。","“耶路撒冷”：原文直译“ 耶路撒冷女子”。"]},{"n":22,"t":"‘你辱骂谁，亵渎谁，扬起声来，高举眼目攻击谁呢？你攻击的是以色列的圣者。","notes":[]},{"n":23,"t":"你藉你的使者辱骂主说：我率领许多战车登上高山，到黎巴嫩的顶端；我要砍伐其中高大的香柏树和上好的松树；我必进到极遥远的住所，进入最茂盛的森林里。","notes":[]},{"n":24,"t":"我已经在外邦挖井喝水；我必用脚掌踏干埃及一切的河流。","notes":[]},{"n":25,"t":"‘你岂没有听见我早先所定、古时所立、现今实现的事吗？就是让你去毁坏坚固的城镇，使它们变为废墟；","notes":[]},{"n":26,"t":"城里的居民力量微小，他们惊惶羞愧；像野草，像青菜，如房顶上的草，又如未长成而枯干的禾稼。","notes":[]},{"n":27,"t":"‘你坐下，你出去，你进来，你向我发烈怒，我都知道。","notes":[]},{"n":28,"t":"因你向我发烈怒，你的狂傲上达我耳中，我要用钩子钩住你的鼻子，将嚼环放在你口里，使你从原路转回去。’","notes":[]},{"n":29,"t":"“这是给你的预兆：你们今年要吃野生的，明年也要吃自长的；后年，你们就要耕种收割，栽葡萄园，吃其中的果子。","notes":[]},{"n":30,"t":"犹大家所逃脱剩余的，仍要往下扎根，向上结果。","notes":[]},{"n":31,"t":"必有剩余的民从耶路撒冷而出，有逃脱的人从锡安山而来。万军之耶和华的热心必成就这事。","notes":[]},{"n":32,"t":"“所以耶和华论亚述王如此说：他必不得来到这城，也不在这里射箭，不得拿盾牌到城前，也不建土堆攻城。","notes":[]},{"n":33,"t":"他从哪条路来，必从那条路回去，必不得来到这城。这是耶和华说的。","notes":[]},{"n":34,"t":"因我为自己的缘故，又为我仆人大卫的缘故，必保护拯救这城。”","notes":[]},{"n":35,"t":"当夜，耶和华的使者出去，在亚述营中杀了十八万五千人。清早有人起来，看哪，都是死尸。","notes":[]},{"n":36,"t":"亚述王西拿基立就拔营回去，住在尼尼微。","notes":[]},{"n":37,"t":"一日，他在他的神明尼斯洛庙里叩拜，他儿子亚得米勒和沙利色用刀杀了他，然后逃到亚拉腊地；他儿子以撒．哈顿接续他作王。","notes":[]}]},"20":{"heading":"希西家病重康复","verses":[{"n":1,"t":"那些日子，希西家病得要死，亚摩斯的儿子以赛亚先知来见他，对他说：“耶和华如此说：‘你当留遗嘱给你的家，因为你必死，不能活了。’”","notes":[]},{"n":2,"t":"希西家转脸朝墙，向耶和华祷告说：","notes":[]},{"n":3,"t":"“耶和华啊，求你记念我在你面前怎样存完全的心，按诚实行事，又做你眼中看为善的事。”希西家就痛哭。","notes":[]},{"n":4,"t":"以赛亚出来，还没有离开中院，耶和华的话就临到他，说：","notes":[]},{"n":5,"t":"“你回去告诉我百姓的君王希西家说：耶和华－你祖先大卫的神如此说：‘我听见了你的祷告，看见了你的眼泪。看哪，我必医治你；到第三日，你必上到耶和华的殿。","notes":[]},{"n":6,"t":"我必加添你十五年的寿数，并且我要救你和这城脱离亚述王的手。我为自己和我仆人大卫的缘故，必保护这城。’”","notes":[]},{"n":7,"t":"以赛亚说：“取一块无花果饼来。”人就取了来，贴在疮上，王就痊愈了。","notes":[]},{"n":8,"t":"希西家对以赛亚说：“耶和华必医治我，到第三日我能上耶和华的殿，有什么预兆呢？”","notes":[]},{"n":9,"t":"以赛亚说：“耶和华必成就他所说的这话。这是耶和华给你的预兆：你要日影向前进十度呢？或是要往后退十度呢？”","notes":[]},{"n":10,"t":"希西家说：“日影向前进十度容易；不，让日影往后退十度吧。”","notes":[]},{"n":11,"t":"以赛亚先知求告耶和华，耶和华就使亚哈斯日晷上照下来的日影，往后退了十度。","notes":[]},{"n":12,"t":"那时，巴拉但的儿子，巴比伦王米罗达．巴拉但听见希西家生病了，就送书信和礼物给他。","notes":[],"heads":["巴比伦来的使者"]},{"n":13,"t":"希西家听使者的话，就将自己一切宝库里的金子、银子、香料、贵重的膏油和他军械库里的兵器，以及他所有的财宝，都给他们看；在他家中和全国之内，希西家没有一样东西不给他们看的。","notes":["“听使者的话”：有古卷、七十士译本和其他古译本是“因他们而欢喜”。"]},{"n":14,"t":"于是以赛亚先知到希西家王那里去，对他说：“这些人说了些什么？他们从哪里来见你？”希西家说：“他们从远方的巴比伦来。”","notes":[]},{"n":15,"t":"以赛亚说：“他们在你家里看见了什么？”希西家说：“凡我家中所有的，他们都看见了；我财宝中没有一样东西不给他们看的。”","notes":[]},{"n":16,"t":"以赛亚对希西家说：“你要听耶和华的话：","notes":[]},{"n":17,"t":"耶和华说：‘看哪，日子将到，凡你家里所有的，并你祖先积蓄到如今的一切，都要被掳到巴比伦去，不留下一样；","notes":[]},{"n":18,"t":"从你本身所生的孩子，其中必有被掳到巴比伦王宫当太监的。’”","notes":[]},{"n":19,"t":"希西家对以赛亚说：“你所说耶和华的话甚好。”因为他想：“在我有生之年岂不是有太平和安稳吗？”","notes":[]},{"n":20,"t":"希西家其余的事和他一切英勇的事迹，他怎样造池、挖沟、引水入城，不都写在《犹大列王记》上吗？","notes":[],"heads":["希西家逝世"]},{"n":21,"t":"希西家与他祖先同睡，他儿子玛拿西接续他作王。","notes":[]}]},"21":{"heading":"犹大王玛拿西","verses":[{"n":1,"t":"玛拿西登基的时候年十二岁，在耶路撒冷作王五十五年。他母亲名叫协西巴。","notes":[]},{"n":2,"t":"玛拿西行耶和华眼中看为恶的事，效法耶和华在以色列人面前赶出的列国那些可憎的事。","notes":[]},{"n":3,"t":"他重新建筑他父亲希西家所毁坏的丘坛，又为巴力筑坛，造亚舍拉，效法以色列王亚哈所行的，敬拜天上的万象，事奉它们。","notes":[]},{"n":4,"t":"他在耶和华殿中筑坛，耶和华曾指着这殿说：“我必立我的名在耶路撒冷。”","notes":[]},{"n":5,"t":"他在耶和华殿的两个院子为天上的万象筑坛，","notes":[]},{"n":6,"t":"并使他的儿子经火，又观星象，行法术，求问招魂的和行巫术的，多行耶和华眼中看为恶的事，惹他发怒。","notes":[]},{"n":7,"t":"他又把自己所造的亚舍拉雕像立在殿内，耶和华曾对大卫和他儿子所罗门说：“我在以色列众支派中所选择的耶路撒冷和这殿，必立我的名，直到永远。","notes":[]},{"n":8,"t":"只要以色列人谨守遵行我一切所吩咐的和我仆人摩西所吩咐的一切律法，我就不再使他们的脚挪移，离开我所赐给他们列祖之地。”","notes":[]},{"n":9,"t":"他们却不听从，并且玛拿西引诱他们行恶，比耶和华在以色列人面前所灭的列国更严重。","notes":[]},{"n":10,"t":"耶和华藉他仆人众先知说：","notes":[]},{"n":11,"t":"“因犹大王玛拿西行这些可憎的恶事，比先前亚摩利人所行的一切更坏，使犹大人拜偶像，陷入罪里，","notes":[]},{"n":12,"t":"所以耶和华－以色列的神如此说：看哪，我必降祸于耶路撒冷和犹大，凡听见的人都必双耳齐鸣。","notes":[]},{"n":13,"t":"我必用量撒玛利亚的准绳和亚哈家的铅垂线拉在耶路撒冷之上；我必擦拭耶路撒冷，如人擦盘子，把盘子翻过来。","notes":[]},{"n":14,"t":"我必撇弃我产业中的余民，把他们交在仇敌手中，使他们成为所有仇敌的掳物和掠物，","notes":[]},{"n":15,"t":"因为自从他们的祖先出埃及的那日直到今日，他们常行我眼中看为恶的事，惹我发怒。”","notes":[]},{"n":16,"t":"玛拿西行耶和华眼中看为恶的事，使犹大陷入罪里，又流许多无辜人的血，直到这血充满了耶路撒冷，从这边到那边。","notes":[]},{"n":17,"t":"玛拿西其余的事，凡他所做的和他所犯的罪，不都写在《犹大列王记》上吗？","notes":[]},{"n":18,"t":"玛拿西与他祖先同睡，葬在自己王宫的园子，乌撒园里，他儿子亚们接续他作王。","notes":[]},{"n":19,"t":"亚们登基的时候年二十二岁，在耶路撒冷作王二年。他母亲名叫米舒利密，是约提巴人哈鲁斯的女儿。","notes":[],"heads":["犹大王亚们"]},{"n":20,"t":"亚们行耶和华眼中看为恶的事，效法他父亲玛拿西所行的。","notes":[]},{"n":21,"t":"他行他父亲一切所行的道，事奉他父亲所事奉的偶像，敬拜它们，","notes":[]},{"n":22,"t":"离弃耶和华－他列祖的神，不遵行耶和华的道。","notes":[]},{"n":23,"t":"亚们的臣仆背叛他，在宫里杀了王。","notes":[]},{"n":24,"t":"但这地的百姓杀了所有背叛亚们王的人；这地的百姓立他儿子约西亚接续他作王。","notes":[]},{"n":25,"t":"亚们其余所做的事，不都写在《犹大列王记》上吗？","notes":[]},{"n":26,"t":"亚们葬在乌撒园内自己的坟墓里，他儿子约西亚接续他作王。","notes":[]}]},"22":{"heading":"犹大王约西亚","verses":[{"n":1,"t":"约西亚登基的时候年八岁，在耶路撒冷作王三十一年。他母亲名叫耶底大，是波斯加人亚大雅的女儿。","notes":[]},{"n":2,"t":"约西亚行耶和华眼中看为正的事，行他祖先大卫一切所行的道，不偏左右。","notes":[]},{"n":3,"t":"约西亚王十八年，王派米书兰的孙子，亚萨利雅的儿子沙番书记上耶和华殿去，说：","notes":[],"heads":["发现律法书"]},{"n":4,"t":"“你上到希勒家大祭司那里，请他把奉献到耶和华殿的银子，就是门口的守卫从百姓中收来的银子，结算清楚，","notes":[]},{"n":5,"t":"交在管理耶和华殿督工的手里，由他们支付给在耶和华殿里做工的人，好修理殿的破坏之处，","notes":[]},{"n":6,"t":"就是木匠、工人和瓦匠，又买木料和凿成的石头，来整修殿宇。","notes":[]},{"n":7,"t":"但他们不用跟这些经手接受银子的人算帐，因为这些人办事诚实。”","notes":[]},{"n":8,"t":"希勒家大祭司对沙番书记说：“我在耶和华殿里发现了律法书。”希勒家把书递给沙番，沙番就读了。","notes":[]},{"n":9,"t":"沙番书记到王那里，把这事回覆王说：“你的仆人已把殿里所发现的银子倒出来，交在管理耶和华殿督工的手里了。”","notes":[]},{"n":10,"t":"沙番书记又向王报告说：“希勒家祭司递给我一卷书。”沙番就在王面前朗读那书。","notes":[]},{"n":11,"t":"王听见律法书上的话，就撕裂衣服。","notes":[]},{"n":12,"t":"王吩咐希勒家祭司与沙番的儿子亚希甘、米该亚的儿子亚革波、沙番书记和王的臣仆亚撒雅，说：","notes":[]},{"n":13,"t":"“你们去，以所发现这书上的话，为我、为百姓、为全犹大求问耶和华；因为我们祖先没有听从这书上的话，没有遵照一切所写有关我们的去行，耶和华就向我们大发烈怒。”","notes":["“所写有关我们的”：有古卷和七十士译本是“它上面所写的”；参代下34．21。"]},{"n":14,"t":"于是，希勒家祭司和亚希甘、亚革波、沙番、亚撒雅都去见户勒大女先知，她是掌管礼服的沙龙的妻子；沙龙是哈珥哈斯的孙子，特瓦的儿子。户勒大住在耶路撒冷第二区。他们向她请教。","notes":[]},{"n":15,"t":"她对他们说：“耶和华－以色列的神如此说：‘你们可以回覆那派你们来见我的人说，","notes":[]},{"n":16,"t":"耶和华如此说：看哪，我必照着犹大王所读那书上的一切话，降祸于这地方和其上的居民。","notes":[]},{"n":17,"t":"因为他们离弃我，向别神烧香，用他们手所做的一切惹我发怒，所以我的愤怒必向这地方发作，总不止息。’","notes":[]},{"n":18,"t":"然而，派你们来求问耶和华的犹大王，你们要这样回覆他：‘耶和华－以色列的神如此说：至于你所听见的话，","notes":[]},{"n":19,"t":"就是听见我指着这地方和其上的居民说，要使这地方变为荒芜、百姓受诅咒的话，你的心就软化，在耶和华面前谦卑下来，撕裂衣服，向我哭泣，因此我应允你。这是耶和华说的。","notes":[]},{"n":20,"t":"因此，看哪，我必使你归到你祖先那里，平安地进入坟墓；我要降于这地方的一切灾祸，你不会亲眼看见。’”他们就去把这话回覆王。","notes":[]}]},"23":{"heading":"约西亚的改革","verses":[{"n":1,"t":"王派人召集犹大和耶路撒冷的众长老来。","notes":[]},{"n":2,"t":"王和犹大众人、耶路撒冷的居民、祭司、先知，以及所有的百姓，无论大小，都一同上到耶和华的殿去；王把耶和华殿里所发现的约书上一切的话读给他们听。","notes":[]},{"n":3,"t":"王站在柱子旁边，在耶和华面前立约，要尽心尽性跟从耶和华，遵守他的诫命、法度、律例，实行这书上所写这约的话。全体百姓都愿遵守所立的约。","notes":[]},{"n":4,"t":"王吩咐希勒家大祭司和副祭司，以及把守殿门的，把那些为巴力和亚舍拉，以及天上万象所造的器皿，都从耶和华殿里搬出来，在耶路撒冷外汲沦的田间烧了，把灰拿到伯特利去。","notes":[]},{"n":5,"t":"从前犹大列王所立拜偶像的祭司，在犹大城镇的丘坛和耶路撒冷周围烧香，现在王都废去，他们是向巴力和日、月、行星，以及天上万象烧香的人。","notes":[]},{"n":6,"t":"他把亚舍拉从耶和华殿里搬到耶路撒冷外的汲沦溪，在汲沦溪边焚烧，打碎成灰，把灰撒在平民的坟上。","notes":[]},{"n":7,"t":"他又拆毁耶和华殿里男的庙妓的屋子，就是妇女在那里为亚舍拉编织衣服的屋子。","notes":[]},{"n":8,"t":"他从犹大的城镇将众祭司带来，从迦巴直到别是巴，玷污祭司烧香的丘坛。他又拆毁城门旁的丘坛，这丘坛是在约书亚市长的城门前，在人进城门的左边。","notes":[]},{"n":9,"t":"只是丘坛的祭司不登耶路撒冷耶和华的坛，仅在他们弟兄中间吃无酵饼。","notes":[]},{"n":10,"t":"他又玷污欣嫩子谷的陀斐特，不许人在那里使儿女经火献给摩洛。","notes":[]},{"n":11,"t":"他把在耶和华殿门旁、靠近拿单．米勒官员走廊的屋子，犹大列王献给太阳的马废去，且用火焚烧献给太阳的战车。","notes":[]},{"n":12,"t":"犹大列王在亚哈斯楼房顶上所筑的坛和玛拿西在耶和华殿两院中所筑的坛，王都拆毁，从那里移走，把灰倒在汲沦溪中。","notes":["“移走”：原文直译“跑走”。"]},{"n":13,"t":"从前以色列王所罗门在耶路撒冷东边、邪僻山南边为西顿人可憎的亚斯她录、摩押人可憎的基抹、亚扪人可憎的米勒公所筑的丘坛，王都玷污了，","notes":["“邪僻山”就是“橄榄山”。"]},{"n":14,"t":"又打碎柱像，砍下亚舍拉，用人的骨头填满那地方。","notes":[]},{"n":15,"t":"此外，在伯特利丘坛的坛，就是尼八的儿子耶罗波安所筑、使以色列人陷入罪里的，他也把这坛和丘坛都拆毁了，又焚烧丘坛，打碎成灰，并焚烧了亚舍拉。","notes":["“又焚烧丘坛”：七十士译本是“把石头拆下来”。"]},{"n":16,"t":"约西亚转头，看见山上的坟墓，就派人取出坟墓里的骸骨，烧在坛上，玷污了坛，正如从前耶罗波安在节期中站在坛旁时，耶和华藉神人所宣告的话。约西亚转头看见了宣告这些话的神人的坟墓。","notes":["“正如从前...坟墓”是根据七十士译本；原文是“正如耶和华从前藉宣告这些事的神人所宣告的话”。"]},{"n":17,"t":"他说：“我看见的这碑是什么呢？”那城里的人对他说：“这是神人的坟墓，他从犹大来，宣告了王向伯特利的坛所做的这些事。”","notes":[]},{"n":18,"t":"约西亚说：“让他安息吧！不要挪移他的骸骨。”他们就保存了他的骸骨和从撒玛利亚来的那先知的骸骨。","notes":[]},{"n":19,"t":"从前以色列诸王在撒玛利亚的城镇所建一切惹动怒气的丘坛的庙，约西亚也都废去了，正如他在伯特利所做的。","notes":[]},{"n":20,"t":"他又把在那里所有丘坛的祭司都杀在坛上，并在坛上烧人的骨头。于是他回耶路撒冷去了。","notes":[]},{"n":21,"t":"王吩咐众百姓说：“你们当照这约书上所写的，向耶和华－你们的神守逾越节。”","notes":[],"heads":["约西亚守逾越节"]},{"n":22,"t":"自从士师治理以色列，到以色列诸王、犹大列王在位的一切日子，从来没有守过这样的逾越节，","notes":[]},{"n":23,"t":"只有在约西亚王十八年，才在耶路撒冷向耶和华守这逾越节。","notes":[]},{"n":24,"t":"此外，在犹大地和耶路撒冷所见那些招魂的、行巫术的，家中的神像和偶像，以及一切可憎之物，约西亚尽都除掉，实行了希勒家祭司在耶和华殿里所发现的律法书上所写的话。","notes":[],"heads":["约西亚的其他改革"]},{"n":25,"t":"在约西亚以前，没有王像他尽心、尽性、尽力地归向耶和华，遵行摩西的一切律法；在他以后，也没有兴起一个王像他。","notes":[]},{"n":26,"t":"然而，耶和华向犹大所发猛烈的怒气仍不止息，因为玛拿西种种的恶事激怒了他。","notes":[]},{"n":27,"t":"耶和华说：“我也必将犹大从我面前赶出，如同赶出以色列一样。我必撇弃我从前所选择的这城耶路撒冷和我所说我的名必留在那里的殿。”","notes":[]},{"n":28,"t":"约西亚其余的事，凡他所做的，不都写在《犹大列王记》上吗？","notes":[],"heads":["约西亚逝世"]},{"n":29,"t":"约西亚的日子，埃及王法老尼哥上到幼发拉底河，到亚述王那里；约西亚王去迎击他。埃及王在米吉多看见约西亚，就杀了他。","notes":[]},{"n":30,"t":"他的臣仆用车把他的尸体从米吉多送到耶路撒冷，葬在他自己的坟墓里。这地的百姓选约西亚的儿子约哈斯，膏立他，接续他父亲作王。","notes":[]},{"n":31,"t":"约哈斯登基的时候年二十三岁，在耶路撒冷作王三个月。他母亲名叫哈慕她，是立拿人耶利米的女儿。","notes":[],"heads":["犹大王约哈斯"]},{"n":32,"t":"约哈斯行耶和华眼中看为恶的事，效法他祖先一切所行的。","notes":[]},{"n":33,"t":"法老尼哥把约哈斯监禁在哈马地的利比拉，不许他在耶路撒冷作王，又罚这地一百他连得银子，一他连得金子。","notes":["“法老尼哥...作王”：原文另译“当约哈斯在耶路撒冷作王的时候，法老尼哥把他监禁在哈马地的利比拉”。"]},{"n":34,"t":"法老尼哥立约西亚的儿子以利雅敬接续他父亲约西亚作王，给他改名叫约雅敬，却把约哈斯带到埃及，他就死在那里。","notes":[]},{"n":35,"t":"约雅敬进贡金银给法老，照着法老的指示在这地征收银子，向这地的百姓按各人的能力索取金银，要送给法老尼哥。","notes":[],"heads":["犹大王约雅敬"]},{"n":36,"t":"约雅敬登基的时候年二十五岁，在耶路撒冷作王十一年。他母亲名叫西布大，是鲁玛人毗大雅的女儿。","notes":[]},{"n":37,"t":"约雅敬行耶和华眼中看为恶的事，效法他祖先一切所行的。","notes":[]}]},"24":{"heading":"犹大王约雅斤","verses":[{"n":1,"t":"约雅敬的日子，巴比伦王尼布甲尼撒上来；约雅敬服事他三年，以后又背叛他。","notes":[]},{"n":2,"t":"耶和华派迦勒底、亚兰、摩押和亚扪人的军队来攻击约雅敬；耶和华派他们来攻击犹大，要毁灭它，正如耶和华藉他仆人众先知所说的话。","notes":[]},{"n":3,"t":"这事临到犹大，诚然是出于耶和华的命令，要把犹大从自己面前赶出去，是因玛拿西所犯的一切罪，","notes":["“命令”：七十士译本和其他古译本是“愤怒”。"]},{"n":4,"t":"又因他流无辜人的血，使无辜人的血充满耶路撒冷；耶和华不愿赦免。","notes":[]},{"n":5,"t":"约雅敬其余的事，凡他所做的，不都写在《犹大列王记》上吗？","notes":[]},{"n":6,"t":"约雅敬与他祖先同睡，他儿子约雅斤接续他作王。","notes":[]},{"n":7,"t":"埃及王不再从他的国出征，因为巴比伦王把埃及王所管之地，从埃及溪谷直到幼发拉底河都夺去了。","notes":[]},{"n":8,"t":"约雅斤登基的时候年十八岁，在耶路撒冷作王三个月。他母亲名叫尼护施她，是耶路撒冷人以利拿单的女儿。","notes":[]},{"n":9,"t":"约雅斤行耶和华眼中看为恶的事，效法他父亲一切所行的。","notes":[]},{"n":10,"t":"那时，巴比伦王尼布甲尼撒的军兵上到耶路撒冷，城被围困。","notes":[]},{"n":11,"t":"当他的军兵围困城的时候，巴比伦王尼布甲尼撒亲自来到耶路撒冷。","notes":[]},{"n":12,"t":"犹大王约雅斤和他母亲、臣仆、王子、官员一同出来，向巴比伦王投降。巴比伦王俘掳了他，那时是巴比伦王第八年。","notes":[]},{"n":13,"t":"巴比伦王把耶和华殿里和王宫里一切的宝物从那里拿走，又把以色列王所罗门所造耶和华殿里一切的金器都毁坏了，正如耶和华所说的。","notes":[]},{"n":14,"t":"他把全耶路撒冷众领袖和所有大能的勇士，共一万人，连同所有的木匠和铁匠都掳了去，只留下这地最贫穷的百姓。","notes":[]},{"n":15,"t":"他把约雅斤和他的母亲、后妃、官员，以及这地的贵族，都从耶路撒冷掳到巴比伦去了，","notes":[]},{"n":16,"t":"又把所有的勇士七千人，木匠和铁匠一千人，全是能上阵的勇士，都掳到巴比伦去了。","notes":[]},{"n":17,"t":"巴比伦王立约雅斤的叔父玛探雅取代他作王，给玛探雅改名叫西底家。","notes":[]},{"n":18,"t":"西底家登基的时候年二十一岁，在耶路撒冷作王十一年。他母亲名叫哈慕她，是立拿人耶利米的女儿。","notes":[],"heads":["犹大王西底家"]},{"n":19,"t":"西底家行耶和华眼中看为恶的事，正如约雅敬一切所行的。","notes":[]},{"n":20,"t":"因此，耶和华向耶路撒冷和犹大发怒，以致把他们从自己面前赶出去。西底家背叛巴比伦王。","notes":[]}]},"25":{"heading":"圣殿被毁","verses":[{"n":1,"t":"西底家作王第九年十月初十，巴比伦王尼布甲尼撒率领全军前来攻击耶路撒冷，对城安营，四围筑堡垒攻城。","notes":[]},{"n":2,"t":"城被围困，直到西底家王十一年。","notes":[]},{"n":3,"t":"四月初九，城里的饥荒非常严重，当地的百姓都没有粮食。","notes":[]},{"n":4,"t":"城被攻破，士兵全都在夜间从靠近王的花园、两城墙中间的门逃跑。迦勒底人正在四围攻城，王就往亚拉巴逃去。","notes":[]},{"n":5,"t":"迦勒底的军队追赶王，在耶利哥的平原追上他；他的全军都离开他溃散了。","notes":[]},{"n":6,"t":"迦勒底人就拿住王，带他到利比拉的巴比伦王那里；他们就判他的罪。","notes":[]},{"n":7,"t":"他们在西底家眼前杀了他的儿女，挖了西底家的眼睛，用铜链锁着他，带到巴比伦去。","notes":[]},{"n":8,"t":"巴比伦王尼布甲尼撒十九年五月初七，巴比伦王的臣仆尼布撒拉旦护卫长进入耶路撒冷，","notes":[]},{"n":9,"t":"他焚烧了耶和华的殿、王宫和耶路撒冷一切的房屋；用火焚烧所有大户人家的房屋。","notes":[]},{"n":10,"t":"跟从护卫长的迦勒底全军拆毁了耶路撒冷四围的城墙。","notes":[]},{"n":11,"t":"那时尼布撒拉旦护卫长将城里剩下的百姓和那些投降巴比伦王的人，以及其余的众人，都掳去了。","notes":[]},{"n":12,"t":"但护卫长留下一些当地最穷的人，叫他们修整葡萄园，耕种田地。","notes":[]},{"n":13,"t":"耶和华殿的铜柱并殿内的盆座和铜海，迦勒底人都打碎了，把那些铜运到巴比伦去。","notes":[]},{"n":14,"t":"他们又带走锅、铲子、钳子、勺子和供奉用的一切铜器；","notes":[]},{"n":15,"t":"火盆和碗，无论金的银的，护卫长都带走了；","notes":[]},{"n":16,"t":"还有所罗门为耶和华殿所造的两根柱子、一个铜海和盆座，这一切器皿的铜多得无法可秤。","notes":[]},{"n":17,"t":"这一根柱子高十八肘，柱上有铜顶，铜顶高三肘；铜顶的周围有网子和石榴，也都是铜的。第二根柱子与此相同，也有网子。","notes":[]},{"n":18,"t":"护卫长拿住西莱雅大祭司、西番亚副祭司和门口的三个守卫，","notes":[],"heads":["犹大人被掳到巴比伦"]},{"n":19,"t":"又从城中拿住一个管理士兵的官，并在城里所找到王面前的五个亲信，和召募当地百姓之将军的书记官，以及在城中找到的六十个当地百姓。","notes":["“官”或译“太监”。"]},{"n":20,"t":"尼布撒拉旦护卫长把这些人带到利比拉的巴比伦王那里。","notes":[]},{"n":21,"t":"巴比伦王击杀他们，在哈马地的利比拉把他们处死。这样，犹大人就被掳去离开本地。","notes":[]},{"n":22,"t":"至于犹大地剩下的百姓，就是巴比伦王尼布甲尼撒所留下的，巴比伦王立了沙番的孙子，亚希甘的儿子基大利作他们的省长。","notes":[],"heads":["基大利出任省长"]},{"n":23,"t":"所有的军官和属他们的人听见巴比伦王立了基大利作省长，尼探雅的儿子以实玛利、加利亚的儿子约哈难、尼陀法人单户蔑的儿子西莱雅、玛迦人的儿子雅撒尼亚，和属他们的人，都来到米斯巴的基大利那里。","notes":[]},{"n":24,"t":"基大利向他们和属他们的人起誓说：“你们不必惧怕迦勒底臣仆，只管住在这地，服事巴比伦王，就可以得福。”","notes":[]},{"n":25,"t":"七月中，王室后裔以利沙玛的孙子，尼探雅的儿子以实玛利带着十个人来，击杀了基大利和同他在米斯巴的犹大人与迦勒底人，把他们杀死。","notes":[]},{"n":26,"t":"于是众人，无论大小，连同军官，因为惧怕迦勒底人，都起身逃到埃及去了。","notes":[]},{"n":27,"t":"巴比伦王以未．米罗达作王的元年，就是犹大王约雅斤被掳后三十七年，十二月二十七日，他使犹大王约雅斤抬起头来，提他出监，","notes":[],"heads":["约雅斤被释放"]},{"n":28,"t":"对他说好话，使他的位高过与他一同被掳在巴比伦众王的位；","notes":[]},{"n":29,"t":"又给他脱了囚服，使他终身常在巴比伦王面前吃饭。","notes":[]},{"n":30,"t":"王赐给他日常需用的食物，每日一份，终身都是这样。","notes":[]}]}},"1CH":{"1":{"heading":"从亚当到亚伯拉罕","verses":[{"n":1,"t":"亚当，塞特，以挪士，","notes":[]},{"n":2,"t":"该南，玛勒列，雅列，","notes":[]},{"n":3,"t":"以诺，玛土撒拉，拉麦，","notes":[]},{"n":4,"t":"挪亚，闪，含，雅弗。","notes":[]},{"n":5,"t":"雅弗的儿子是歌篾、玛各、玛代、雅完、土巴、米设和提拉。","notes":[]},{"n":6,"t":"歌篾的儿子是亚实基拿、低法和陀迦玛。","notes":["“低法”：有古卷是“利法”；参创 10．3。"]},{"n":7,"t":"雅完的儿子是以利沙、他施、基提和罗单人。","notes":["“罗单人”：参创10．4。"]},{"n":8,"t":"含的儿子是古实、麦西、弗和迦南。","notes":["“麦西”即“埃及”；下同。"]},{"n":9,"t":"古实的儿子是西巴、哈腓拉、撒弗他、拉玛和撒弗提迦。拉玛的儿子是示巴和底但。","notes":[]},{"n":10,"t":"古实又生宁录，他是地上第一个勇士。","notes":[]},{"n":11,"t":"麦西生路低人、亚拿米人、利哈比人、拿弗土希人、","notes":[]},{"n":12,"t":"帕斯鲁细人、迦斯路希人和迦斐托人；非利士人是从迦斐托人出来的。","notes":["“迦斐托人”：原文是“迦斯路希人”。"]},{"n":13,"t":"迦南生了长子西顿，又生赫","notes":[]},{"n":14,"t":"和耶布斯人、亚摩利人、革迦撒人、","notes":[]},{"n":15,"t":"希未人、亚基人、西尼人、","notes":[]},{"n":16,"t":"亚瓦底人、洗玛利人和哈马人。","notes":[]},{"n":17,"t":"闪的儿子是以拦、亚述、亚法撒、路德、亚兰、乌斯、户勒、基帖和米设。","notes":["“米设”：创10．23是“玛施”。"]},{"n":18,"t":"亚法撒生沙拉；沙拉生希伯。","notes":[]},{"n":19,"t":"希伯生了两个儿子：一个名叫法勒，因为那时人分地居住；法勒的兄弟名叫约坍。","notes":["“法勒”意思是“分”。"]},{"n":20,"t":"约坍生亚摩答、沙列、哈萨玛非、耶拉、","notes":[]},{"n":21,"t":"哈多兰、乌萨、德拉、","notes":[]},{"n":22,"t":"以巴录、亚比玛利、示巴、","notes":["“以巴录”：创10．28称“俄巴路”。"]},{"n":23,"t":"阿斐、哈腓拉和约巴。这些都是约坍的儿子。","notes":[]},{"n":24,"t":"闪，亚法撒，沙拉，","notes":[]},{"n":25,"t":"希伯，法勒，拉吴，","notes":[]},{"n":26,"t":"西鹿，拿鹤，他拉，","notes":[]},{"n":27,"t":"亚伯兰，亚伯兰就是亚伯拉罕。","notes":[]},{"n":28,"t":"亚伯拉罕的儿子是以撒和以实玛利。","notes":[],"heads":["以实玛利的后裔"]},{"n":29,"t":"以实玛利的后代如下：以实玛利的长子是尼拜约，又有基达、亚德别、米比衫、","notes":[]},{"n":30,"t":"米施玛、度玛、玛撒、哈大、提玛、","notes":[]},{"n":31,"t":"伊突、拿非施和基底玛。这些都是以实玛利的儿子。","notes":[]},{"n":32,"t":"亚伯拉罕的妾基土拉所生的儿子，就是心兰、约珊、米但、米甸、伊施巴和书亚。约珊的儿子是示巴和底但。","notes":[]},{"n":33,"t":"米甸的儿子是以法、以弗、哈诺、亚比大和以勒大。这些都是基土拉的子孙。","notes":[]},{"n":34,"t":"亚伯拉罕生以撒；以撒的儿子是以扫和以色列。","notes":[],"heads":["以扫的后裔"]},{"n":35,"t":"以扫的儿子是以利法、流珥、耶乌施、雅兰和可拉。","notes":[]},{"n":36,"t":"以利法的儿子是提幔、阿抹、洗玻、迦坦、基纳斯、亭纳和亚玛力。","notes":[]},{"n":37,"t":"流珥的儿子是拿哈、谢拉、沙玛和米撒。","notes":[]},{"n":38,"t":"西珥的儿子是罗坍、朔巴、祭便、亚拿、底顺、以察和底珊。","notes":[],"heads":["西珥的后裔"]},{"n":39,"t":"罗坍的儿子是何利和荷幔；罗坍的妹妹是亭纳。","notes":["“荷幔”：创36．22称“希幔”。"]},{"n":40,"t":"朔巴的儿子是亚勒文、玛拿辖、以巴录、示非和阿南。祭便的儿子是爱亚和亚拿。","notes":["“示非”：创36．23称“示玻”。"]},{"n":41,"t":"亚拿的儿子是底顺。底顺的儿子是哈默兰、伊是班、益兰和基兰。","notes":["“哈默兰”：创36．26称“欣但”。"]},{"n":42,"t":"以察的儿子是辟罕、撒番和亚干。底珊的儿子是乌斯和亚兰。","notes":["“亚干”是根据一些古卷和七十士译本；原文是“约亚干”；参创36．27。","“底珊”：原文是“底顺”。"]},{"n":43,"t":"以色列人未有君王治理之前，这些是在以东地作王的。有比珥的儿子比拉，他的城名叫亭哈巴。","notes":[],"heads":["以东诸王"]},{"n":44,"t":"比拉死了，波斯拉人谢拉的儿子约巴接续他作王。","notes":[]},{"n":45,"t":"约巴死了，提幔人之地的户珊接续他作王。","notes":[]},{"n":46,"t":"户珊死了，比达的儿子哈达接续他作王，哈达曾在摩押地击败米甸人，他的城名叫亚未得。","notes":[]},{"n":47,"t":"哈达死了，玛士利加人桑拉接续他作王。","notes":[]},{"n":48,"t":"桑拉死了，大河边的利河伯人扫罗接续他作王。","notes":[]},{"n":49,"t":"扫罗死了，亚革波的儿子巴勒．哈南接续他作王。","notes":[]},{"n":50,"t":"巴勒．哈南死了，哈达接续他作王，他的城名叫巴伊。他的妻子名叫米希她别，是米．萨合的孙女，玛特列的女儿。","notes":["“巴伊”：创36．39称“巴乌”。"]},{"n":51,"t":"哈达死了。以东的族长有：亭纳族长、亚勒瓦族长、耶帖族长、","notes":[]},{"n":52,"t":"阿何利巴玛族长、以拉族长、比嫩族长、","notes":[]},{"n":53,"t":"基纳斯族长、提幔族长、米比萨族长、","notes":[]},{"n":54,"t":"玛基叠族长、以兰族长。这些都是以东的族长。","notes":[]}]},"2":{"heading":"犹大的后裔","verses":[{"n":1,"t":"以色列的儿子是吕便、西缅、利未、犹大、以萨迦、西布伦、","notes":[]},{"n":2,"t":"但、约瑟、便雅悯、拿弗他利、迦得和亚设。","notes":[]},{"n":3,"t":"犹大的儿子是珥、俄南和示拉，这三人是迦南女子拔．书亚所生的。犹大的长子珥在耶和华眼中看为恶，耶和华就杀死了他。","notes":[]},{"n":4,"t":"犹大的媳妇她玛为犹大生了法勒斯和谢拉。犹大共有五个儿子。","notes":[]},{"n":5,"t":"法勒斯的儿子是希斯仑和哈母勒。","notes":[]},{"n":6,"t":"谢拉的儿子是心利、以探、希幔、甲各和大拉，共五人。","notes":["“大拉”：七十士译本的一些抄本和其他古译本是“达大”；参王上4．31。"]},{"n":7,"t":"迦米的儿子是亚迦，他在当灭的物上犯了罪，连累了以色列人。","notes":["“亚迦”：有古卷是“亚干”；参书7．18。"]},{"n":8,"t":"以探的儿子是亚撒利雅。","notes":[]},{"n":9,"t":"希斯仑所生的儿子是耶拉篾、兰和基路拜。","notes":[],"heads":["大卫王的家谱"]},{"n":10,"t":"兰生亚米拿达；亚米拿达生拿顺，拿顺是犹大人的领袖。","notes":[]},{"n":11,"t":"拿顺生撒门；撒门生波阿斯；","notes":[]},{"n":12,"t":"波阿斯生俄备得；俄备得生耶西；","notes":[]},{"n":13,"t":"耶西生长子以利押，次子亚比拿达，三子示米亚，","notes":["“示米亚”：撒上16．9称“沙玛”。"]},{"n":14,"t":"四子拿坦业，五子拉代，","notes":[]},{"n":15,"t":"六子阿鲜，七子大卫。","notes":[]},{"n":16,"t":"他们的姊妹是洗鲁雅和亚比该。洗鲁雅的儿子是亚比筛、约押和亚撒黑，共三人。","notes":[]},{"n":17,"t":"亚比该生亚玛撒；亚玛撒的父亲是以实玛利人益帖。","notes":[]},{"n":18,"t":"希斯仑的儿子迦勒娶阿苏巴和耶略为妻，阿苏巴的儿子是耶设、朔罢和押墩。","notes":[],"heads":["希斯仑的后裔"]},{"n":19,"t":"阿苏巴死了，迦勒又娶以法她，生了户珥。","notes":[]},{"n":20,"t":"户珥生乌利；乌利生比撒列。","notes":[]},{"n":21,"t":"后来，希斯仑六十岁时娶了基列的父亲玛吉的女儿，与她同房；玛吉的女儿为他生了西割；","notes":[]},{"n":22,"t":"西割生睚珥。睚珥在基列地有二十三座城。","notes":[]},{"n":23,"t":"后来基述和亚兰夺了哈倭特．睚珥，以及基纳和所属的乡镇，共六十个。这些城镇的人全都是基列的父亲玛吉的子孙。","notes":["“乡镇”：原文直译“女子们”；本卷书下同。"]},{"n":24,"t":"希斯仑在迦勒．以法他死后，他的妻子亚比雅为他生了提哥亚的父亲亚施户。","notes":["本节七十士译本是“希斯仑死后，迦勒到了以法他。希斯仑的妻子是亚比雅，为他生了提哥亚的父亲亚施户。”"]},{"n":25,"t":"希斯仑的长子耶拉篾的儿子有长子兰、布拿、阿连、阿鲜和亚希雅。","notes":[],"heads":["耶拉篾的后裔"]},{"n":26,"t":"耶拉篾又娶一妻名叫亚她拉，是阿南的母亲。","notes":[]},{"n":27,"t":"耶拉篾的长子兰的儿子有玛斯、雅悯和以结。","notes":[]},{"n":28,"t":"阿南的儿子是沙买和雅大。沙买的儿子是拿答和亚比述。","notes":[]},{"n":29,"t":"亚比述的妻子名叫亚比孩，为他生了亚办和摩利。","notes":[]},{"n":30,"t":"拿答的儿子是西列和亚遍；西列死了，没有儿子。","notes":[]},{"n":31,"t":"亚遍的儿子是以示；以示的儿子是示珊；示珊的儿子是亚来。","notes":[]},{"n":32,"t":"沙买的兄弟雅大的儿子是益帖和约拿单；益帖死了，没有儿子。","notes":[]},{"n":33,"t":"约拿单的儿子是比勒和撒萨。这些都是耶拉篾的子孙。","notes":[]},{"n":34,"t":"示珊没有儿子，只有女儿。示珊有一个仆人名叫耶哈，是埃及人。","notes":[]},{"n":35,"t":"示珊把女儿嫁给仆人耶哈，她为他生了亚太。","notes":[]},{"n":36,"t":"亚太生拿单；拿单生撒拔；","notes":[]},{"n":37,"t":"撒拔生以弗拉；以弗拉生俄备得；","notes":[]},{"n":38,"t":"俄备得生耶户；耶户生亚撒利雅；","notes":[]},{"n":39,"t":"亚撒利雅生希利斯；希利斯生以利亚萨；","notes":[]},{"n":40,"t":"以利亚萨生西斯买；西斯买生沙龙；","notes":[]},{"n":41,"t":"沙龙生耶加米雅；耶加米雅生以利沙玛。","notes":[]},{"n":42,"t":"耶拉篾的兄弟迦勒的众儿子：长子是米沙，米沙是西弗的父亲，还有希伯伦的父亲玛利沙的众儿子。","notes":[],"heads":["迦勒的其余后裔"]},{"n":43,"t":"希伯伦的儿子是可拉、他普亚、利肯和示玛。","notes":[]},{"n":44,"t":"示玛生拉含，是约干之祖。利肯生沙买。","notes":["“约干”：原文另译“约甸”；参书15．56。"]},{"n":45,"t":"沙买的儿子是玛云；玛云是伯．夙的父亲。","notes":[]},{"n":46,"t":"迦勒的妾以法生哈兰、摩撒和迦谢；哈兰生迦卸。","notes":[]},{"n":47,"t":"雅代的儿子是利健、约坦、基珊、毗力、以法和沙亚弗。","notes":[]},{"n":48,"t":"迦勒的妾玛迦生示别和特哈拿，","notes":[]},{"n":49,"t":"又生麦玛拿的父亲沙亚弗，又生抹比拿和基比亚的父亲示法。迦勒的女儿是押撒。","notes":[]},{"n":50,"t":"这些都是迦勒的子孙。以法她的长子户珥的子孙：基列．耶琳之祖朔巴，","notes":[]},{"n":51,"t":"伯利恒之祖萨玛，伯．迦得之祖哈勒。","notes":[]},{"n":52,"t":"基列．耶琳之祖朔巴的子孙是哈罗以和一半的米努哈人。","notes":["“米努哈人”就是“玛拿哈人”；参54节。"]},{"n":53,"t":"基列．耶琳的宗族有以帖人、布特人、舒玛人、密来人，又从这些宗族生出琐拉人和以实陶人。","notes":[]},{"n":54,"t":"萨玛的子孙有伯利恒人、尼陀法人、亚他绿．伯．约押人、一半的玛拿哈人、琐利人。","notes":[]},{"n":55,"t":"住雅比斯的文士的宗族有特拉人、示米押人和苏甲人。这些都是利甲家之祖哈末所生的基尼人。","notes":[]}]},"3":{"heading":"大卫的儿女","verses":[{"n":1,"t":"大卫在希伯仑所生的儿子如下：长子暗嫩是耶斯列人亚希暖生的。次子但以利是迦密人亚比该生的。","notes":["“但以利”：撒下3．3称“基利押”。"]},{"n":2,"t":"三子押沙龙是基述王达买的女儿玛迦生的。四子亚多尼雅是哈及生的。","notes":[]},{"n":3,"t":"五子示法提雅是亚比她生的。六子以特念是大卫的妻子以格拉生的。","notes":[]},{"n":4,"t":"这六人都是大卫在希伯仑生的。大卫在希伯仑作王七年六个月，在耶路撒冷作王三十三年。","notes":[]},{"n":5,"t":"大卫在耶路撒冷所生的儿子是示米亚、朔罢、拿单和所罗门。这四人是亚米利的女儿拔．书亚生的。","notes":["“示米亚”：撒下5．14，代上14．4称“沙母亚”。"]},{"n":6,"t":"还有益辖、以利沙玛、以利法列、","notes":["“以利沙玛”：撒下5．15，代上14．5称“以利书亚”。","“以利法列”：代上14．5称“以法列”。"]},{"n":7,"t":"挪迦、尼斐、雅非亚、","notes":[]},{"n":8,"t":"以利沙玛、以利雅大、以利法列，共九人。","notes":["“以利雅大”：代上14．7称“比利雅大”。"]},{"n":9,"t":"这些全都是大卫的儿子，妃嫔的儿子不在其内；她玛是他们的妹妹。","notes":[]},{"n":10,"t":"所罗门的后裔如下：罗波安，他的儿子亚比雅，他的儿子亚撒，他的儿子约沙法，","notes":["“亚比雅”：王上14．31称“亚比央”。"],"heads":["所罗门的后裔"]},{"n":11,"t":"他的儿子约兰，他的儿子亚哈谢，他的儿子约阿施，","notes":[]},{"n":12,"t":"他的儿子亚玛谢，他的儿子亚撒利雅，他的儿子约坦；","notes":[]},{"n":13,"t":"他的儿子亚哈斯，他的儿子希西家，他的儿子玛拿西，","notes":[]},{"n":14,"t":"他的儿子亚们，他的儿子约西亚，","notes":[]},{"n":15,"t":"他的长子约哈难，次子约雅敬，三子西底家，四子沙龙。","notes":["“沙龙”：王下23．30称“约哈斯”。"]},{"n":16,"t":"约雅敬的后裔：他的儿子耶哥尼雅，他的儿子西底家。","notes":["“耶哥尼雅”：王下24．6称“约雅斤”。"]},{"n":17,"t":"被掳的耶哥尼雅的后裔如下：他的儿子撒拉铁、","notes":[],"heads":["耶哥尼雅的后裔"]},{"n":18,"t":"玛基兰、毗大雅、示拿萨、耶加米、何沙玛和尼大比雅。","notes":[]},{"n":19,"t":"毗大雅的儿子是所罗巴伯和示每。所罗巴伯的儿子是米书兰和哈拿尼雅，示罗密是他们的妹妹；","notes":[]},{"n":20,"t":"还有哈舒巴、阿黑、比利家、哈撒底、于沙．希悉，共五人。","notes":["“还有哈舒巴...于沙．希悉”可能是所罗巴伯被掳归回后所生，也可能是另一妻所生；原文另译“米书兰的儿子是哈舒巴、阿黑、比利家、哈撒底、于沙．希悉”。"]},{"n":21,"t":"哈拿尼雅的儿子是毗拉提和耶筛亚。还有利法雅的众儿子，亚珥难的众儿子，俄巴底亚的众儿子，示迦尼的众儿子。","notes":["本节七十士译本是“哈拿尼雅的后裔如下：毗拉提，他的儿子耶筛亚，他的儿子利法雅，他的儿子亚珥难，他的儿子俄巴底亚，他的儿子示迦尼。”"]},{"n":22,"t":"示迦尼的后裔：示玛雅，示玛雅的儿子哈突、以甲、巴利亚、尼利雅、沙法，共六人。","notes":["“示玛雅的儿子哈突”：原文另译“哈突”。"]},{"n":23,"t":"尼利雅的儿子是以利约乃、希西家、亚斯利干，共三人。","notes":[]},{"n":24,"t":"以利约乃的儿子是何大雅、以利亚实、毗莱雅、阿谷、约哈难、第莱雅、阿拿尼，共七人。","notes":[]}]},"4":{"heading":"复记犹大的后裔","verses":[{"n":1,"t":"犹大的儿子是法勒斯、希斯仑、迦米、户珥和朔巴。","notes":[]},{"n":2,"t":"朔巴的儿子利亚雅生雅哈；雅哈生亚户买和拉哈。这些是琐拉人的宗族。","notes":[],"heads":["－朔巴"]},{"n":3,"t":"以坦之祖是耶斯列、伊施玛和伊得巴；他们的妹妹名叫哈悉勒玻尼。","notes":["“以坦之祖”：七十士译本是“以坦的儿子”。"],"heads":["－户珥"]},{"n":4,"t":"基多之祖是毗努伊勒。户沙之祖是以谢珥。这些都是伯利恒之祖，以法她的长子户珥的后裔。","notes":[]},{"n":5,"t":"提哥亚的父亲亚施户有两个妻子，希拉和拿拉。","notes":[],"heads":["－亚施户"]},{"n":6,"t":"拿拉为亚施户生亚户撒、希弗、提米尼和哈辖斯他利。这些都是拿拉的儿子。","notes":[]},{"n":7,"t":"希拉生的是洗列、琐辖和伊提南。","notes":[]},{"n":8,"t":"哥斯生亚诺、琐比巴和哈仑的儿子亚哈黑的宗族。","notes":[]},{"n":9,"t":"雅比斯比他众兄弟更尊贵，他母亲给他起名叫雅比斯，意思说：“我生他甚是痛苦。”","notes":[]},{"n":10,"t":"雅比斯求告以色列的神说：“甚愿你赐福与我，扩张我的疆界，你的手常与我同在，保佑我不遭患难，不受艰苦。”神就应允他所求的。","notes":[]},{"n":11,"t":"书哈的兄弟基绿生米黑，米黑是伊施屯的父亲。","notes":[],"heads":["－迦勒"]},{"n":12,"t":"伊施屯生伯拉巴、巴西亚和珥．拿辖之祖提欣拿。这些都是利迦人。","notes":[]},{"n":13,"t":"基纳斯的儿子是俄陀聂和西莱雅。俄陀聂的儿子是哈塔。","notes":[]},{"n":14,"t":"悯挪太生俄弗拉；西莱雅生革．夏纳欣之祖约押。他们都是工匠。","notes":[]},{"n":15,"t":"耶孚尼的儿子迦勒的后裔：以路、以拉和拿安。以拉的儿子是基纳斯。","notes":[]},{"n":16,"t":"耶哈利勒的儿子是西弗、西法、提利和亚撒列。","notes":[]},{"n":17,"t":"以斯拉的儿子是益帖、米列、以弗和雅伦。米列所娶法老的女儿比提雅的后裔如下：她怀了米利暗、沙买，和以实提摩之祖益巴。米列的犹大妻子生基多之祖雅列，梭哥之祖希伯，和撒挪亚之祖耶古铁。","notes":[],"end":18},{"n":19,"t":"拿含的妹妹，荷第雅的妻子所生的是达利亚，迦米人基伊拉和玛迦人以实提摩的祖先。","notes":["“达利亚”是根据七十士译本的一些抄本；原文没有。"]},{"n":20,"t":"示门的儿子是暗嫩、林拿、便．哈南和提伦。以示的儿子是梭黑和便．梭黑。","notes":[]},{"n":21,"t":"犹大的儿子示拉的后裔：利迦之祖珥，玛利沙之祖拉大，和住在伯．亚实比织细麻布的各宗族。","notes":[],"heads":["－示拉"]},{"n":22,"t":"还有约敬、哥西巴人、约阿施，和那在摩押娶妻，回到利恒的萨拉。这都是古时的记载。","notes":["“在摩押...萨拉”是根据一些古译本；原文是“在摩押和雅叔比．利恒掌权的萨拉”。"]},{"n":23,"t":"这些人都是陶匠，是尼他应和基底拉的居民。他们住在王那里，为王做工。","notes":[]},{"n":24,"t":"西缅的后裔如下：尼母利、雅悯、雅立、谢拉和扫罗；","notes":[],"heads":["西缅的后裔"]},{"n":25,"t":"他的儿子沙龙，他的儿子米比衫，他的儿子米施玛；","notes":[]},{"n":26,"t":"米施玛的后裔：他的儿子哈母利，他的儿子撒刻，他的儿子示每。","notes":[]},{"n":27,"t":"示每有十六个儿子和六个女儿，但他兄弟的儿女不多，他们各家族也不如犹大族那样人丁兴旺。","notes":[]},{"n":28,"t":"西缅人住在别是巴、摩拉大、哈萨．书亚、","notes":[]},{"n":29,"t":"辟拉、以森、陀腊、","notes":[]},{"n":30,"t":"彼土利、何珥玛、洗革拉、","notes":[]},{"n":31,"t":"伯．玛加博、哈萨．苏撒、伯．比利和沙拉音，这些城镇直到大卫作王的时候都是属西缅人的；","notes":[]},{"n":32,"t":"还有所属的村庄以坦、亚因、临门、陀健、亚珊，共五个城镇；","notes":[]},{"n":33,"t":"连同环绕这些城镇的一切乡村，直到巴力。这是他们的住处，他们都有家谱。","notes":[]},{"n":34,"t":"还有米所巴、雅米勒、亚玛谢的儿子约沙、","notes":[]},{"n":35,"t":"约珥，和亚薛的曾孙，西莱雅的孙子，约示比的儿子耶户。","notes":[]},{"n":36,"t":"还有以利约乃、雅哥巴、约朔海、亚帅雅、亚底业、耶西篾、比拿雅、","notes":[]},{"n":37,"t":"细撒；细撒是示非的儿子，示非是亚龙的儿子，亚龙是耶大雅的儿子，耶大雅是申利的儿子，申利是示玛雅的儿子。","notes":[]},{"n":38,"t":"以上所记的人名都是作族长的，他们父系的家属大量增加。","notes":[]},{"n":39,"t":"他们往平原东边基多口去，寻找牧放羊群的草场，","notes":["“基多口”：七十士译本是“基拉耳口”。"]},{"n":40,"t":"找到了肥沃优美的草场，又宽阔又平静安宁之地；从前住那里的是含族的人。","notes":[]},{"n":41,"t":"以上纪录上有名的人，在犹大王希西家的日子，来攻击含族人的帐棚和那里所有的米乌尼人，把他们灭尽，就住在他们的地方，直到今日，因为那里有草场可以牧放羊群。","notes":[]},{"n":42,"t":"这些西缅人中有五百人上西珥山，率领他们的是以示的儿子毗拉提、尼利雅、利法雅和乌薛。","notes":[]},{"n":43,"t":"他们杀了亚玛力剩下的残存之民，就住在那里，直到今日。","notes":[]}]},"5":{"heading":"吕便的后裔","verses":[{"n":1,"t":"以色列的长子吕便的后裔。吕便玷污了父亲的床，他长子的名分就归了以色列的儿子约瑟的后裔；因此，家谱就不按出生顺序登录。","notes":[]},{"n":2,"t":"虽然犹大比他兄弟强盛，君王也从他而出，然而长子的名分却归约瑟。","notes":[]},{"n":3,"t":"以色列长子吕便的后裔如下：哈诺、法路、希斯伦和迦米。","notes":[]},{"n":4,"t":"约珥的后裔：他的儿子示玛雅，他的儿子歌革，他的儿子示每，","notes":[]},{"n":5,"t":"他的儿子米迦，他的儿子利亚雅，他的儿子巴力，","notes":[]},{"n":6,"t":"他的儿子备拉；这备拉作吕便支派的领袖，被亚述王提革拉．毗列色掳去。","notes":[]},{"n":7,"t":"他的弟兄照着宗族，按着家谱作族长的是耶利、撒迦利雅、","notes":[]},{"n":8,"t":"比拉；比拉是亚撒的儿子，亚撒是示玛的儿子，示玛是约珥的儿子；约珥住在亚罗珥，直到尼波和巴力．免。","notes":[]},{"n":9,"t":"他也住在东边，直到幼发拉底河这边的旷野边界，因为他们在基列地牲畜增多。","notes":[]},{"n":10,"t":"扫罗年间，他们与夏甲人争战，夏甲人倒在他们手下，他们就在基列东边的全地，住在夏甲人的帐棚里。","notes":[]},{"n":11,"t":"迦得的后裔在吕便对面，住在巴珊地，延伸到撒迦：","notes":[],"heads":["迦得的后裔"]},{"n":12,"t":"有作族长的约珥，有作副族长的沙番，还有雅乃和住在巴珊的沙法。","notes":[]},{"n":13,"t":"按着家族，他们的弟兄是米迦勒、米书兰、示巴、约赖、雅干、细亚和希伯，共七人。","notes":[]},{"n":14,"t":"这些都是亚比孩的儿子；亚比孩是户利的儿子，户利是耶罗亚的儿子，耶罗亚是基列的儿子，基列是米迦勒的儿子，米迦勒是耶示筛的儿子，耶示筛是耶哈多的儿子，耶哈多是布斯的儿子；","notes":[]},{"n":15,"t":"古尼的孙子，押比叠的儿子亚希是他们的族长。","notes":[]},{"n":16,"t":"他们住在基列、巴珊和所属的乡镇，以及沙仑一切的郊野，直到四围的交界。","notes":[]},{"n":17,"t":"这些人在犹大王约坦和以色列王耶罗波安年间，都载入家谱。","notes":[]},{"n":18,"t":"吕便人、迦得人和玛拿西半支派的人，能拿盾牌和刀剑、拉弓、出征善战的勇士共有四万四千七百六十名。","notes":[],"heads":["吕便迦得玛拿西族的军队"]},{"n":19,"t":"他们与夏甲人、伊突人、拿非施人、挪答人打仗。","notes":[]},{"n":20,"t":"他们在打仗的时候得了神的帮助，夏甲人和所有跟随夏甲人的人都交在他们手中；因为他们在阵上呼求神，倚赖他，他就应允他们。","notes":[]},{"n":21,"t":"他们掳掠了夏甲人的牲畜，有五万匹骆驼，二十五万只羊，二千匹驴，又有十万人；","notes":[]},{"n":22,"t":"被杀仆倒的很多，因为这战争是出乎神。他们就住在夏甲人的地上，直到被掳的时候。","notes":[]},{"n":23,"t":"玛拿西半支派的人住在那地，从巴珊延到巴力．黑门、示尼珥和黑门山，他们人数增多。","notes":["“人数增多”：七十士译本是“他们在黎巴嫩人数增多”。"],"heads":["玛拿西半支派"]},{"n":24,"t":"他们的族长如下：以弗、以示、以利业、亚斯列、耶利米、何达威雅和雅叠；他们都是大能的勇士，有名的人，是作族长的。","notes":[]},{"n":25,"t":"但他们得罪了他们列祖的神，随从当地百姓的神明而行淫，这百姓就是神在他们面前所除灭的。","notes":[]},{"n":26,"t":"因此，以色列的神激发亚述王普勒，就是亚述王提革拉．毗列色的心，他掳掠了吕便人、迦得人、玛拿西半支派的人，把他们带到哈腊、哈博、哈拉与歌散河边，直到今日。","notes":["七十士译本没有“哈拉”。"]}]},"6":{"heading":"利未的后裔","verses":[{"n":1,"t":"利未的后裔：革顺、哥辖和米拉利。","notes":[]},{"n":2,"t":"哥辖的儿子是暗兰、以斯哈、希伯伦和乌薛。","notes":[]},{"n":3,"t":"暗兰的儿女是亚伦、摩西和米利暗。亚伦的儿子是拿答、亚比户、以利亚撒和以他玛。","notes":[]},{"n":4,"t":"以利亚撒生非尼哈；非尼哈生亚比书；","notes":[]},{"n":5,"t":"亚比书生布基；布基生乌西；","notes":[]},{"n":6,"t":"乌西生西拉希雅；西拉希雅生米拉约；","notes":[]},{"n":7,"t":"米拉约生亚玛利雅；亚玛利雅生亚希突；","notes":[]},{"n":8,"t":"亚希突生撒督；撒督生亚希玛斯；","notes":[]},{"n":9,"t":"亚希玛斯生亚撒利雅；亚撒利雅生约哈难；","notes":[]},{"n":10,"t":"约哈难生亚撒利雅，亚撒利雅在所罗门建造的耶路撒冷殿中担任祭司的职分；","notes":[]},{"n":11,"t":"亚撒利雅生亚玛利雅；亚玛利雅生亚希突；","notes":[]},{"n":12,"t":"亚希突生撒督；撒督生沙龙；","notes":[]},{"n":13,"t":"沙龙生希勒家；希勒家生亚撒利雅；","notes":[]},{"n":14,"t":"亚撒利雅生西莱雅；西莱雅生约萨答。","notes":[]},{"n":15,"t":"当耶和华藉尼布甲尼撒的手掳掠犹大和耶路撒冷的时候，约萨答也被掳去。","notes":[]},{"n":16,"t":"利未的后裔：革顺、哥辖和米拉利。","notes":[],"heads":["利未其余的后裔"]},{"n":17,"t":"革顺的儿子名叫立尼和示每。","notes":[]},{"n":18,"t":"哥辖的儿子是暗兰、以斯哈、希伯伦和乌薛。","notes":[]},{"n":19,"t":"米拉利的儿子是抹利和母示。这是按着父系所分利未人的宗族。","notes":[]},{"n":20,"t":"属革顺的：他的儿子立尼，他的儿子雅哈，他的儿子薪玛，","notes":[]},{"n":21,"t":"他的儿子约亚，他的儿子易多，他的儿子谢拉，他的儿子耶特赖。","notes":[]},{"n":22,"t":"哥辖的后裔：他的儿子亚米拿达，他的儿子可拉，他的儿子亚惜，","notes":[]},{"n":23,"t":"他的儿子以利加拿，他的儿子以比雅撒，他的儿子亚惜，","notes":[]},{"n":24,"t":"他的儿子他哈，他的儿子乌列，他的儿子乌西雅，他的儿子少罗。","notes":[]},{"n":25,"t":"以利加拿的儿子是亚玛赛、亚希摩、","notes":[]},{"n":26,"t":"以利加拿。以利加拿的后裔：他的儿子琐菲，他的儿子拿哈，","notes":["“以利加拿。以利加拿的后裔：他的儿子琐菲”：七十士译本是“他的儿子以利加拿，他的儿子琐菲”。"]},{"n":27,"t":"他的儿子以利押，他的儿子耶罗罕，他的儿子以利加拿，他的儿子撒母耳。","notes":[]},{"n":28,"t":"撒母耳的儿子是长子约珥和次子亚比亚。","notes":["“长子约珥和次子亚比亚”是根据七十士译本和其他古译本，原文是“长子瓦希尼和亚比亚”；参本章33节，撒上8．2。"]},{"n":29,"t":"米拉利的后裔：抹利，他的儿子立尼，他的儿子示每，他的儿子乌撒，","notes":[]},{"n":30,"t":"他的儿子示米亚，他的儿子哈基雅，他的儿子亚帅雅。","notes":[]},{"n":31,"t":"这些是约柜安设之后，大卫派在耶和华殿中管理歌唱事奉的人。","notes":[],"heads":["圣殿中的歌唱者"]},{"n":32,"t":"他们在会幕前负责歌唱的事奉，及至所罗门在耶路撒冷建造了耶和华的殿，他们就按着班次供职。","notes":[]},{"n":33,"t":"供职的人和他们的子孙如下：哥辖的子孙中有歌唱的希幔；希幔是约珥的儿子，约珥是撒母耳的儿子，","notes":[]},{"n":34,"t":"撒母耳是以利加拿的儿子，以利加拿是耶罗罕的儿子，耶罗罕是以利业的儿子，以利业是陀亚的儿子，","notes":[]},{"n":35,"t":"陀亚是苏弗的儿子，苏弗是以利加拿的儿子，以利加拿是玛哈的儿子，玛哈是亚玛赛的儿子，","notes":[]},{"n":36,"t":"亚玛赛是以利加拿的儿子，以利加拿是约珥的儿子，约珥是亚撒利雅的儿子，亚撒利雅是西番雅的儿子，","notes":[]},{"n":37,"t":"西番雅是他哈的儿子，他哈是亚惜的儿子，亚惜是以比雅撒的儿子，以比雅撒是可拉的儿子，","notes":[]},{"n":38,"t":"可拉是以斯哈的儿子，以斯哈是哥辖的儿子，哥辖是利未的儿子，利未是以色列的儿子。","notes":[]},{"n":39,"t":"希幔的弟兄亚萨在希幔的右边供职；亚萨是比利家的儿子，比利家是示米亚的儿子，","notes":[]},{"n":40,"t":"示米亚是米迦勒的儿子，米迦勒是巴西雅的儿子，巴西雅是玛基雅的儿子，","notes":[]},{"n":41,"t":"玛基雅是伊特尼的儿子，伊特尼是谢拉的儿子，谢拉是亚大雅的儿子，","notes":[]},{"n":42,"t":"亚大雅是以探的儿子，以探是薪玛的儿子，薪玛是示每的儿子，","notes":[]},{"n":43,"t":"示每是雅哈的儿子，雅哈是革顺的儿子，革顺是利未的儿子。","notes":[]},{"n":44,"t":"他们的弟兄米拉利的子孙，在他们左边供职的有以探；以探是基示的儿子，基示是亚伯底的儿子，亚伯底是玛鹿的儿子，","notes":[]},{"n":45,"t":"玛鹿是哈沙比雅的儿子，哈沙比雅是亚玛谢的儿子，亚玛谢是希勒家的儿子，","notes":[]},{"n":46,"t":"希勒家是暗西的儿子，暗西是巴尼的儿子，巴尼是沙麦的儿子，","notes":[]},{"n":47,"t":"沙麦是末力的儿子，末力是母示的儿子，母示是米拉利的儿子，米拉利是利未的儿子。","notes":[]},{"n":48,"t":"他们的弟兄利未人也被派办理神殿中帐幕的一切事务。","notes":[]},{"n":49,"t":"亚伦和他的子孙在燔祭坛和香坛上献祭烧香，办理至圣所一切的事，为以色列赎罪，正如神仆人摩西所吩咐的一切。","notes":[],"heads":["亚伦的后裔"]},{"n":50,"t":"亚伦的后裔如下：他的儿子以利亚撒，他的儿子非尼哈，他的儿子亚比书，","notes":[]},{"n":51,"t":"他的儿子布基，他的儿子乌西，他的儿子西拉希雅，","notes":[]},{"n":52,"t":"他的儿子米拉约，他的儿子亚玛利雅，他的儿子亚希突，","notes":[]},{"n":53,"t":"他的儿子撒督，他的儿子亚希玛斯。","notes":[]},{"n":54,"t":"他们的住处按着境内的营寨如下：亚伦的子孙哥辖族先抽签得地，","notes":[],"heads":["利未支派居住地"]},{"n":55,"t":"得了犹大地的希伯仑和四围的郊野；","notes":[]},{"n":56,"t":"只是这城的田地和所属的村庄都为耶孚尼的儿子迦勒所得。","notes":[]},{"n":57,"t":"亚伦的子孙所得逃城如下：希伯仑、立拿与其郊野、雅提珥、以实提莫与其郊野、","notes":[]},{"n":58,"t":"希仑与其郊野、底璧与其郊野、","notes":["“希仑”是根据七十士译本，原文是“希列兹”，原文另译“何仑”；参书21．15。"]},{"n":59,"t":"亚珊与其郊野、伯．示麦与其郊野。","notes":[]},{"n":60,"t":"他们也从便雅悯支派中得了迦巴与其郊野、阿勒篾与其郊野、亚拿突与其郊野。他们宗族所得的城共十三座。","notes":[]},{"n":61,"t":"哥辖族其余的人抽签，按支派的宗族，从半个支派，就是玛拿西半支派中得了十座城。","notes":[]},{"n":62,"t":"革顺族按着宗族，从以萨迦支派、亚设支派、拿弗他利支派、巴珊内的玛拿西支派中，得了十三座城。","notes":[]},{"n":63,"t":"米拉利族按着宗族抽签，从吕便支派、迦得支派、西布伦支派中，得了十二座城。","notes":[]},{"n":64,"t":"以色列人把这些城与其郊野给了利未人。","notes":[]},{"n":65,"t":"以色列人用抽签的方式，从犹大人、西缅人、便雅悯人三支派中，把以上提到名字的城给了他们。","notes":[]},{"n":66,"t":"哥辖子孙中有几个宗族从以法莲支派中也得了城镇作为他们的区域。","notes":[]},{"n":67,"t":"他们在以法莲山区所得的逃城：示剑与其郊野、基色与其郊野、","notes":[]},{"n":68,"t":"约缅与其郊野、伯．和仑与其郊野、","notes":[]},{"n":69,"t":"亚雅仑与其郊野、迦特．临门与其郊野。","notes":[]},{"n":70,"t":"哥辖其余的子孙从玛拿西半支派中得了亚乃与其郊野、比连与其郊野。","notes":[]},{"n":71,"t":"革顺子孙从玛拿西半支派中得了巴珊的哥兰与其郊野、亚斯她录与其郊野；","notes":[]},{"n":72,"t":"从以萨迦支派中得了基低斯与其郊野、大比拉与其郊野、","notes":[]},{"n":73,"t":"拉末与其郊野、亚年与其郊野；","notes":[]},{"n":74,"t":"从亚设支派中得了玛沙与其郊野、押顿与其郊野、","notes":[]},{"n":75,"t":"户割与其郊野、利合与其郊野；","notes":[]},{"n":76,"t":"从拿弗他利支派中得了加利利的基低斯与其郊野、哈们与其郊野、基列亭与其郊野。","notes":[]},{"n":77,"t":"米拉利其余的子孙从西布伦支派中得了临摩挪与其郊野、他泊与其郊野；","notes":["“临摩挪”：书19．13称“临门”。"]},{"n":78,"t":"又在耶利哥的约旦河东，从吕便支派中得了旷野的比悉与其郊野、雅杂与其郊野，","notes":[]},{"n":79,"t":"基底莫与其郊野、米法押与其郊野；","notes":[]},{"n":80,"t":"又从迦得支派中得了基列的拉末与其郊野、玛哈念与其郊野、","notes":[]},{"n":81,"t":"希实本与其郊野、雅谢与其郊野。","notes":[]}]},"7":{"heading":"以萨迦的后裔","verses":[{"n":1,"t":"以萨迦的后裔：陀拉、普瓦、雅述和伸仑，共四人。","notes":["“雅述”：创46．13称“约伯”。"]},{"n":2,"t":"陀拉的后裔：乌西、利法雅、耶勒、雅买、易伯散和示母利，都是陀拉的族长，在他们世代中是大能的勇士。到大卫年间，他们的人数共有二万二千六百名。","notes":[]},{"n":3,"t":"乌西的后裔：伊斯拉希，伊斯拉希的儿子米迦勒、俄巴底亚、约珥和伊示雅，共五人，全都是族长。","notes":[]},{"n":4,"t":"他们所率领的，按着家谱，照着父家，可作战的军队共有三万六千人，因为他们的妻子和儿子众多。","notes":[]},{"n":5,"t":"他们的弟兄在以萨迦各族中的大能勇士，登记在家谱中的全部共有八万七千人。","notes":[]},{"n":6,"t":"便雅悯：比拉、比结和耶叠，共三人。","notes":["“便雅悯”：七十士译本的一些抄本是“便雅悯的儿子”。"],"heads":["便雅悯的后裔"]},{"n":7,"t":"比拉的儿子：以斯本、乌西、乌薛、耶利末和以利，共五人，都是族长，是大能的勇士。登记在家谱中的人共有二万二千零三十四人。","notes":[]},{"n":8,"t":"比结的儿子：细米拉、约阿施、以利以谢、以利约乃、暗利、耶利末、亚比雅、亚拿突和亚拉篾；这些全都是比结的儿子。","notes":[]},{"n":9,"t":"登记在家谱中，按家谱的族长，大能的勇士，共有二万零二百人。","notes":[]},{"n":10,"t":"耶叠的后裔：比勒罕，比勒罕的儿子耶乌施、便雅悯、以笏、基拿拿、细坦、他施和亚希沙哈。","notes":[]},{"n":11,"t":"这些全都是耶叠的后裔，都是族长，是大能的勇士，能上阵打仗的共有一万七千二百人。","notes":[]},{"n":12,"t":"还有以珥的儿子书品和户品，以及亚黑的儿子户伸。","notes":[]},{"n":13,"t":"拿弗他利的后裔：雅薛、沽尼、耶色和沙龙，都是辟拉的子孙。","notes":[],"heads":["拿弗他利的后裔"]},{"n":14,"t":"玛拿西的儿子亚斯烈是他的妾亚兰女子所生的；她又生了玛吉，是基列的父亲。","notes":[],"heads":["玛拿西的后裔"]},{"n":15,"t":"玛吉为户品和书品各娶了一妻，他的姊妹名叫玛迦。第二个名叫西罗非哈；西罗非哈只有女儿。","notes":[]},{"n":16,"t":"玛吉的妻子玛迦生了一个儿子，玛迦给他起名叫毗利施。毗利施的弟弟名叫示利施；示利施的儿子是乌兰和利金。","notes":[]},{"n":17,"t":"乌兰的儿子是比但。这些都是基列的子孙；基列是玛吉的儿子，玛吉是玛拿西的儿子。","notes":[]},{"n":18,"t":"基列的妹妹哈摩利吉生了伊施荷、亚比以谢和玛拉。","notes":[]},{"n":19,"t":"示米大的儿子是亚现、示剑、利克希和阿尼安。","notes":[]},{"n":20,"t":"以法莲的后裔：书提拉，他的儿子比列，他的儿子他哈，他的儿子以拉大，他的儿子他哈，","notes":[],"heads":["以法莲的后裔"]},{"n":21,"t":"他的儿子撒拔，他的儿子书提拉。以法莲又生以谢和以列；这二人因为下去夺取迦特人的牲畜，被本地的迦特人杀了。","notes":[]},{"n":22,"t":"他们的父亲以法莲为他们悲哀了多日，他的兄弟都来安慰他。","notes":[]},{"n":23,"t":"以法莲与妻子同房，妻子怀孕生了一子，以法莲因为家里遭祸，就给这儿子起名叫比利亚。","notes":[]},{"n":24,"t":"他的女儿名叫舍伊拉，舍伊拉建筑了上伯．和仑、下伯．和仑和乌羡．舍伊拉。","notes":[]},{"n":25,"t":"他的儿子利法和利悉，他的儿子他拉，他的儿子他罕，","notes":[]},{"n":26,"t":"他的儿子拉但，他的儿子亚米忽，他的儿子以利沙玛，","notes":[]},{"n":27,"t":"他的儿子嫩，他的儿子约书亚。","notes":[]},{"n":28,"t":"以法莲人的地业和住处是伯特利和所属的乡镇，东边拿兰，西边基色和所属的乡镇，示剑和所属的乡镇，直到艾雅和所属的乡镇；","notes":[]},{"n":29,"t":"还有靠近玛拿西人的边界，伯．善和所属的乡镇，他纳和所属的乡镇，米吉多和所属的乡镇，多珥和所属的乡镇。以色列儿子约瑟的子孙住在这些地方。","notes":[]},{"n":30,"t":"亚设的后裔：音拿、亦施瓦、亦施韦和比利亚，还有他们的妹妹西拉。","notes":[],"heads":["亚设的后裔"]},{"n":31,"t":"比利亚的儿子是希别和玛结；玛结是比撒威的父亲。","notes":[]},{"n":32,"t":"希别生雅弗勒、朔默、何坦和他们的妹妹书雅。","notes":[]},{"n":33,"t":"雅弗勒的儿子是巴萨、宾哈和亚施法；这些都是雅弗勒的儿子。","notes":[]},{"n":34,"t":"朔默的儿子是亚希、罗迦、耶户巴和亚兰。","notes":[]},{"n":35,"t":"朔默的兄弟希连的儿子是琐法、音那、示利斯和亚抹。","notes":[]},{"n":36,"t":"琐法的儿子是书亚、哈尼弗、书阿勒、比利、音拉、","notes":[]},{"n":37,"t":"比悉、河得、珊玛、施沙、益兰和比拉。","notes":[]},{"n":38,"t":"益帖的儿子是耶孚尼、毗斯巴和亚拉。","notes":[]},{"n":39,"t":"乌拉的儿子是亚拉、汉尼业和利写。","notes":[]},{"n":40,"t":"这些全都是亚设的子孙，都是族长，是精壮大能的勇士，也是领袖中的领袖。登记在家谱中，能上阵打仗的共有二万六千人。","notes":[]}]},"8":{"heading":"便雅悯的后裔","verses":[{"n":1,"t":"便雅悯生长子比拉，次子亚实别，三子亚哈拉，","notes":[]},{"n":2,"t":"四子挪哈，五子拉法。","notes":[]},{"n":3,"t":"比拉的儿子是亚大、基拉、亚比忽、","notes":[]},{"n":4,"t":"亚比书、乃幔、亚何亚、","notes":[]},{"n":5,"t":"基拉、示孚汛和户兰。","notes":[]},{"n":6,"t":"以忽的后裔如下，他们是迦巴居民的族长，曾被掳到玛拿辖：","notes":[]},{"n":7,"t":"乃幔、亚希亚、基拉；他掳了他们，又生了乌撒和亚希忽。","notes":[]},{"n":8,"t":"沙哈连休了两个妻子户伸和巴拉之后，在摩押地生了儿子。","notes":[]},{"n":9,"t":"他与妻子贺得生了约巴、洗比雅、米沙、玛拉干、","notes":[]},{"n":10,"t":"耶乌斯、沙迦和米玛；这些是他的儿子，都是族长。","notes":[]},{"n":11,"t":"户伸为他生了亚比突和以利巴力。","notes":[]},{"n":12,"t":"以利巴力的儿子是希伯、米珊和沙麦；沙麦建立阿挪、罗德和所属的乡镇。","notes":[]},{"n":13,"t":"比利亚和示玛是亚雅仑居民的族长，他们驱逐了迦特的居民。","notes":[]},{"n":14,"t":"亚希约、沙煞、耶利末、","notes":["“亚希约、沙煞”：七十士译本是“他们的弟兄是沙煞”。"]},{"n":15,"t":"西巴第雅、亚拉得、亚得、","notes":[]},{"n":16,"t":"米迦勒、伊施巴和约哈都是比利亚的儿子。","notes":[]},{"n":17,"t":"西巴第雅、米书兰、希西基、希伯、","notes":[]},{"n":18,"t":"伊施米莱、伊斯利亚和约巴都是以利巴力的儿子。","notes":[]},{"n":19,"t":"雅金、细基利、撒底、","notes":[]},{"n":20,"t":"以利乃、洗勒太、以利业、","notes":[]},{"n":21,"t":"亚大雅、比拉雅和申拉都是示每的儿子。","notes":[]},{"n":22,"t":"伊施班、希伯、以利业、","notes":[]},{"n":23,"t":"亚伯顿、细基利、哈难、","notes":[]},{"n":24,"t":"哈拿尼雅、以拦、安陀提雅、","notes":[]},{"n":25,"t":"伊弗底雅、毗努伊勒都是沙煞的儿子。","notes":[]},{"n":26,"t":"珊示莱、示哈利、亚他利雅、","notes":[]},{"n":27,"t":"雅利西、以利亚和细基利都是耶罗罕的儿子。","notes":[]},{"n":28,"t":"这些人按照他们的家谱都是族长，是领袖，都住在耶路撒冷。","notes":[]},{"n":29,"t":"在基遍住的有基遍的父亲耶利，他的妻子名叫玛迦；","notes":[],"heads":["扫罗王的家族"]},{"n":30,"t":"他的长子是亚伯顿，还有苏珥、基士、巴力、拿答、","notes":["“巴力”：七十士译本的一些抄本是“巴力、尼珥”；参代上9．36。"]},{"n":31,"t":"基多、亚希约和撒迦。","notes":["七十士译本在此加“米基罗”；参代上9．37。"]},{"n":32,"t":"米基罗生示米暗。这些人在他们弟兄的对面，和他们的弟兄同住在耶路撒冷。","notes":[]},{"n":33,"t":"尼珥生基士；基士生扫罗；扫罗生约拿单、麦基．舒亚、亚比拿达和伊施巴力。","notes":["“伊施巴力”又名“伊施．波设”，见撒下2．8；又名“亦施韦”，见撒上14．49；代上9．39同。"]},{"n":34,"t":"约拿单的儿子是米力．巴力；米力．巴力生米迦。","notes":["“米力．巴力”：撒下4．4称“米非波设”；代上9．40同。"]},{"n":35,"t":"米迦的儿子是毗敦、米勒、他利亚和亚哈斯；","notes":[]},{"n":36,"t":"亚哈斯生耶何阿达；耶何阿达生亚拉篾、亚斯玛威和心利；心利生摩撒；","notes":[]},{"n":37,"t":"摩撒生比尼亚；比尼亚的儿子是拉法，拉法的儿子是以利亚萨，以利亚萨的儿子是亚悉。","notes":[]},{"n":38,"t":"亚悉有六个儿子，他们的名字是亚斯利干、波基路、以实玛利、示亚利雅、俄巴底雅和哈难；这些全都是亚悉的儿子。","notes":["“亚斯利干、波基路”：七十士译本是“他的长子亚斯利干”。"]},{"n":39,"t":"亚悉兄弟以设的儿子：长子是乌兰，次子是耶乌施，三子是以利法列。","notes":[]},{"n":40,"t":"乌兰的儿子都是大能的勇士，是弓箭手，他们有许多的子孙，共一百五十名，都是便雅悯人。","notes":[]}]},"9":{"heading":"被掳归回的人","verses":[{"n":1,"t":"以色列众人按家谱登记，看哪，都写在《以色列诸王记》上。犹大人因背叛被掳到巴比伦。","notes":[]},{"n":2,"t":"从巴比伦先回来，住在自己地业城镇中的有以色列人、祭司、利未人和殿役。","notes":[]},{"n":3,"t":"住在耶路撒冷的有犹大人、便雅悯人、以法莲人和玛拿西人：","notes":[]},{"n":4,"t":"犹大儿子法勒斯的子孙中有乌太，乌太是亚米忽的儿子，亚米忽是暗利的儿子，暗利是音利的儿子，音利是巴尼的儿子；","notes":[]},{"n":5,"t":"示罗人中有长子亚帅雅和他的众儿子；","notes":[]},{"n":6,"t":"谢拉的子孙中有耶乌利和他的弟兄，共六百九十人；","notes":[]},{"n":7,"t":"便雅悯人中有哈西努亚的曾孙，何达威雅的孙子，米书兰的儿子撒路；","notes":[]},{"n":8,"t":"又有耶罗罕的儿子伊比内雅；米基立的孙子，乌西的儿子以拉；伊比尼雅的曾孙，流珥的孙子，示法提雅的儿子米书兰；","notes":[]},{"n":9,"t":"和他们的弟兄，按着家谱登记，共有九百五十六名；这些人都是族长。","notes":[]},{"n":10,"t":"祭司中有耶大雅、耶何雅立、雅斤，","notes":[],"heads":["住耶路撒冷的祭司"]},{"n":11,"t":"还有管理神殿的亚撒利雅，亚撒利雅是希勒家的儿子，希勒家是米书兰的儿子，米书兰是撒督的儿子，撒督是米拉约的儿子，米拉约是亚希突的儿子。","notes":[]},{"n":12,"t":"还有玛基雅的曾孙，巴施户珥的孙子，耶罗罕的儿子亚大雅；又有玛赛，玛赛是亚第业的儿子，亚第业是雅希细拉的儿子，雅希细拉是米书兰的儿子，米书兰是米实利密的儿子，米实利密是音麦的儿子。","notes":[]},{"n":13,"t":"他们和他们的弟兄都是族长，共有一千七百六十人，都善于做神殿的事工。","notes":[]},{"n":14,"t":"利未人米拉利的子孙中有哈沙比雅的曾孙，押利甘的孙子，哈述的儿子示玛雅；","notes":[],"heads":["住耶路撒冷的利未人"]},{"n":15,"t":"有拔巴甲、黑勒施、加拉和亚萨的曾孙，细基利的孙子，米迦的儿子玛探雅；","notes":[]},{"n":16,"t":"又有耶杜顿的曾孙，加拉的孙子，示玛雅的儿子俄巴底，还有以利加拿的孙子，亚撒的儿子比利家。他们都住在尼陀法人的村庄。","notes":[]},{"n":17,"t":"守卫是沙龙、亚谷、达们、亚希幔和他们的弟兄；沙龙是领袖。","notes":[],"heads":["住耶路撒冷的圣殿守卫"]},{"n":18,"t":"从前这些人看守朝东的王门，如今是利未人营中的守卫。","notes":[]},{"n":19,"t":"可拉的曾孙，以比雅撒的孙子，可利的儿子沙龙，和他父家的弟兄可拉人管理事务，看守会幕的门。他们的祖宗曾管理耶和华的军营，把守营的入口。","notes":[]},{"n":20,"t":"从前以利亚撒的儿子非尼哈管理他们，耶和华也与他同在。","notes":[]},{"n":21,"t":"米施利米雅的儿子撒迦利雅是看守会幕门口的。","notes":[]},{"n":22,"t":"被选作门口守卫的总共有二百一十二名。他们在自己的村庄，按着家谱登记，是大卫和撒母耳先见所派担当这受托之职任的。","notes":[]},{"n":23,"t":"他们和他们的子孙看守耶和华殿的门，就是会幕的门口。","notes":[]},{"n":24,"t":"在东西南北，四方都有守卫。","notes":["“四方”：原文是“四风”。"]},{"n":25,"t":"他们的弟兄住在村庄，每七日来与他们换班。","notes":[]},{"n":26,"t":"这些守卫的四个领袖都是利未人，各有受托的职任，看守神殿的房间和宝库。","notes":[]},{"n":27,"t":"他们住在神殿的四围，受托看守圣殿，负责每日早晨开门。","notes":[]},{"n":28,"t":"利未人中有人管理所使用的器皿，拿出拿入都按数目点算。","notes":[],"heads":["其余的利未人"]},{"n":29,"t":"又有人管理器具和圣所一切的器皿，以及细面、酒、油、乳香和香料。","notes":[]},{"n":30,"t":"祭司的子孙中有人用香料做膏油。","notes":[]},{"n":31,"t":"利未人玛他提雅是可拉族沙龙的长子，他受托做烤饼。","notes":[]},{"n":32,"t":"他们弟兄哥辖子孙中，有人负责每安息日排列供饼。","notes":[]},{"n":33,"t":"歌唱的有利未人的族长，住在殿的房间，昼夜供职，不做别样的工。","notes":[]},{"n":34,"t":"以上都是利未人的族长，按各世系作领袖，他们都住在耶路撒冷。","notes":[]},{"n":35,"t":"在基遍住的有基遍的父亲耶利，他的妻子名叫玛迦；","notes":[],"heads":["扫罗王的祖先和后代"]},{"n":36,"t":"他的长子是亚伯顿，还有苏珥、基士、巴力、尼珥、拿答、","notes":[]},{"n":37,"t":"基多、亚希约、撒迦利雅和米基罗。","notes":["“撒迦利雅”：代上8．31称“撒迦”。"]},{"n":38,"t":"米基罗生示米暗。这些人在他们弟兄的对面，和他们的弟兄同住在耶路撒冷。","notes":[]},{"n":39,"t":"尼珥生基士；基士生扫罗；扫罗生约拿单、麦基．舒亚、亚比拿达和伊施巴力。","notes":[]},{"n":40,"t":"约拿单的儿子是米力．巴力；米力．巴力生米迦。","notes":[]},{"n":41,"t":"米迦的儿子是毗敦、米勒、他利亚和亚哈斯。","notes":["原文没有“亚哈斯”；参代上8．35。"]},{"n":42,"t":"亚哈斯生雅拉；雅拉生亚拉篾、亚斯玛威和心利；心利生摩撒；","notes":["“雅拉”：代上8．36称“耶何阿达”。"]},{"n":43,"t":"摩撒生比尼亚；比尼亚的儿子是利法雅，利法雅的儿子是以利亚萨，以利亚萨的儿子是亚悉。","notes":["“利法雅”：代上8．37称“拉法”。"]},{"n":44,"t":"亚悉有六个儿子，他们的名字是亚斯利干、波基路、以实玛利、示亚利雅、俄巴底雅和哈难；这些都是亚悉的儿子。","notes":["“亚斯利干、波基路”：七十士译本是“他的长子亚斯利干”。"]}]},"10":{"heading":"扫罗逝世","verses":[{"n":1,"t":"非利士人攻打以色列。以色列人在非利士人面前逃跑，很多人在基利波山被杀仆倒。","notes":["“很多人”：原文是“他们”。"]},{"n":2,"t":"非利士人紧追扫罗和他的儿子，杀了扫罗的儿子约拿单、亚比拿达、麦基．舒亚。","notes":[]},{"n":3,"t":"攻击扫罗的战事激烈，扫罗被弓箭手射中，被他们射伤。","notes":[]},{"n":4,"t":"扫罗吩咐拿他兵器的人说：“你拔出刀来，把我刺死，免得那些未受割礼的人来凌辱我。”但拿兵器的人非常惧怕，不肯刺他。于是扫罗拿起刀来，伏在刀上。","notes":[]},{"n":5,"t":"拿兵器的人见扫罗已死，也伏在刀上死了。","notes":[]},{"n":6,"t":"这样，扫罗和他三个儿子，以及他的全家都一起阵亡了。","notes":[]},{"n":7,"t":"住平原的以色列众人见以色列军兵逃跑，扫罗和他儿子都死了，就弃城逃跑。非利士人前来，占据了他们的城。","notes":["“以色列军兵”：原文是“他们”。"]},{"n":8,"t":"次日，非利士人来剥那些被杀之人的衣服，看见扫罗和他儿子仆倒在基利波山。","notes":[]},{"n":9,"t":"他们剥了他的军装，拿着他的首级和盔甲，派人到非利士人之地的四境，报信给他们的偶像和百姓。","notes":[]},{"n":10,"t":"他们将扫罗的盔甲放在他们神明的庙里，把他的首级钉在大衮庙中。","notes":[]},{"n":11,"t":"基列的雅比居民听见非利士人向扫罗所行的一切事，","notes":[]},{"n":12,"t":"他们中间所有的勇士就起身，把扫罗和他儿子的尸身送到雅比，把他们的尸骨葬在雅比的橡树下，禁食七日。","notes":[]},{"n":13,"t":"这样，扫罗为了他的不忠死了；因为他干犯耶和华，没有遵守耶和华的话，又因他求问招魂的妇人，","notes":[]},{"n":14,"t":"不求问耶和华，所以耶和华使他被杀，把王国给了耶西的儿子大卫。","notes":[]}]},"11":{"heading":"大卫作全以色列的王","verses":[{"n":1,"t":"以色列众人聚集到希伯仑见大卫，说：“看哪，我们是你的骨肉。","notes":[]},{"n":2,"t":"从前扫罗作王的时候，率领以色列人出入的是你；耶和华－你的神也曾对你说：‘你必牧养我的百姓以色列，你必作我百姓以色列的君王。’”","notes":[]},{"n":3,"t":"于是以色列的众长老都来到希伯仑见王。大卫在希伯仑，在耶和华面前与他们立约，他们就膏大卫作以色列的王，正如耶和华藉撒母耳所说的话。","notes":[]},{"n":4,"t":"大卫和以色列众人到了耶路撒冷，就是耶布斯；那时耶布斯人住在那里。","notes":[]},{"n":5,"t":"耶布斯人对大卫说：“你必不能进到这里。”然而大卫攻取了锡安的堡垒，就是大卫的城。","notes":[]},{"n":6,"t":"大卫说：“谁先攻打耶布斯人，必作领袖，作元帅。”洗鲁雅的儿子约押先上去，就作了领袖。","notes":[]},{"n":7,"t":"大卫住在堡垒里，所以那堡垒叫作大卫城。","notes":[]},{"n":8,"t":"大卫又从米罗起，四围建筑城墙，其余的由约押修建。","notes":["“米罗”是音译，指“土堆的防御工事”。"]},{"n":9,"t":"大卫日见强大，万军之耶和华与他同在。","notes":[]},{"n":10,"t":"以下是跟随大卫勇士的领袖；他们奋勇帮助他得到国度，并照着耶和华吩咐以色列的话，与以色列众人一同立他作王。","notes":[],"heads":["大卫的勇士"]},{"n":11,"t":"大卫勇士的名单如下：哈革摩尼的儿子雅朔班，他是军官的统领，曾一次举枪杀了三百人。","notes":["“军官的统领”：原文另译“三十勇士之首”；有古译本是“三勇士之首”。"]},{"n":12,"t":"其次是亚何亚人朵多的儿子以利亚撒，他是三个勇士里的一个。","notes":[]},{"n":13,"t":"他从前与大卫在巴斯．大悯，非利士人聚集要打仗。那里有一块长满大麦的田。百姓在非利士人面前逃跑，","notes":[]},{"n":14,"t":"他们却站在那块田的中间，防守那田，击败了非利士人。耶和华大获全胜。","notes":["“他们”：七十士译本是“他”。"]},{"n":15,"t":"三十个领袖中的三个人下到磐石那里，进了亚杜兰洞见大卫；非利士的军队在利乏音谷安营。","notes":[]},{"n":16,"t":"那时大卫在山寨，非利士人的驻军在伯利恒。","notes":[]},{"n":17,"t":"大卫渴想着说：“但愿有人从伯利恒城门旁的井里打水来给我喝！”","notes":[]},{"n":18,"t":"这三个勇士就闯过非利士人的军营，从伯利恒城门旁的井里打水，拿来给大卫喝。大卫却不肯喝，将水浇在耶和华面前，","notes":[]},{"n":19,"t":"说：“我的神啊，我绝不做这事！这些人冒死去打水，这水是他们用生命换来的，我怎能喝他们的血呢？”大卫不肯喝这水。这是三个勇士所做的事。","notes":[]},{"n":20,"t":"约押的兄弟亚比筛是这三个勇士的领袖；他曾举枪杀了三百人，就在三个勇士中得了名。","notes":["“三个”：有古译本是“三十个”。"]},{"n":21,"t":"他在这三个勇士里比其他两个更有名望，所以作他们的领袖，只是不及前三个勇士。","notes":[]},{"n":22,"t":"耶何耶大的儿子比拿雅是来自甲薛的勇士，曾行了大事。他杀了摩押人亚利伊勒的两个儿子，又在下雪的时候下到坑里去，杀了一只狮子。","notes":[]},{"n":23,"t":"他又杀了一个身高五肘的埃及人；埃及人手里拿着枪，枪杆粗如织布机的轴。比拿雅只拿着棍子下到他那里去，从埃及人手里夺过枪来，用那枪杀死了他。","notes":[]},{"n":24,"t":"这些是耶何耶大的儿子比拿雅所做的事，就在三个勇士里得了名。","notes":[]},{"n":25,"t":"看哪，他比那三十个勇士更有名望，只是不及前三个勇士。大卫立他作护卫长。","notes":[]},{"n":26,"t":"军中的勇士有约押的兄弟亚撒黑，伯利恒人朵多的儿子伊勒哈难，","notes":[]},{"n":27,"t":"哈律人沙玛，比伦人希利斯，","notes":[]},{"n":28,"t":"提哥亚人益吉的儿子以拉，亚拿突人亚比以谢，","notes":[]},{"n":29,"t":"户沙人西比该，亚何亚人以来，","notes":[]},{"n":30,"t":"尼陀法人玛哈莱，尼陀法人巴拿的儿子希立，","notes":[]},{"n":31,"t":"便雅悯族基比亚人利拜的儿子以太，比拉顿人比拿雅，","notes":[]},{"n":32,"t":"迦实溪人户莱，亚拉巴人亚比，","notes":[]},{"n":33,"t":"巴路米人押斯玛弗，沙本人以利雅哈巴，","notes":[]},{"n":34,"t":"基孙人哈深的众儿子，哈拉人沙基的儿子约拿单，","notes":[]},{"n":35,"t":"哈拉人沙甲的儿子亚希暗，吾珥的儿子以利法勒，","notes":[]},{"n":36,"t":"米基拉人希弗，比伦人亚希雅，","notes":[]},{"n":37,"t":"迦密人希斯罗，伊斯拜的儿子拿莱，","notes":[]},{"n":38,"t":"拿单的兄弟约珥，哈基利的儿子弥伯哈，","notes":[]},{"n":39,"t":"亚扪人洗勒，比录人拿哈莱，他是给洗鲁雅的儿子约押拿兵器的，","notes":[]},{"n":40,"t":"以帖人以拉，以帖人迦立，","notes":[]},{"n":41,"t":"赫人乌利亚，亚莱的儿子撒拔，","notes":[]},{"n":42,"t":"吕便人示撒的儿子亚第拿，是吕便支派中的一个领袖，率领三十人，","notes":[]},{"n":43,"t":"玛迦的儿子哈难，弥特尼人约沙法，","notes":[]},{"n":44,"t":"亚施他拉人乌西亚，亚罗珥人何坦的儿子沙玛和耶利，","notes":[]},{"n":45,"t":"提洗人申利的儿子耶叠和他的兄弟约哈，","notes":[]},{"n":46,"t":"玛哈未人以利业，伊利拿安的儿子耶利拜和约沙未雅，摩押人伊特玛、","notes":[]},{"n":47,"t":"以利业、俄备得，以及米琐八人雅西业。","notes":[]}]},"12":{"heading":"早期跟随大卫的便雅悯人","verses":[{"n":1,"t":"以下是大卫因基士的儿子扫罗的缘故被放逐到洗革拉的时候，到他那里帮助他打仗的勇士；","notes":[]},{"n":2,"t":"他们是弓箭手，能左右甩石，开弓射箭，都是便雅悯人扫罗同族的弟兄：","notes":[]},{"n":3,"t":"为首的是亚希以谢，其次是约阿施，都是基比亚人示玛的儿子。还有亚斯玛威的儿子耶薛和毗力，比拉迦，亚拿突人耶户，","notes":[]},{"n":4,"t":"基遍人以实买雅，他在三十人中是勇士，管理这三十人，又有耶利米，雅哈悉，约哈难，基底拉人约撒拔，","notes":[]},{"n":5,"t":"伊利乌赛，耶利末，比亚利雅，示玛利雅，哈律弗人示法提雅，","notes":[]},{"n":6,"t":"可拉人以利加拿、耶西亚、亚萨列、约以谢、雅朔班，","notes":[]},{"n":7,"t":"基多人耶罗罕的儿子犹拉和西巴第雅。","notes":[]},{"n":8,"t":"迦得人中有人到旷野的山寨投奔大卫，都是大能的勇士，能拿盾牌和枪的战士。他们的面貌好像狮子，敏捷如山上的鹿。","notes":[],"heads":["跟随大卫的迦得人"]},{"n":9,"t":"第一以薛，第二俄巴底雅，第三以利押，","notes":[]},{"n":10,"t":"第四弥施玛拿，第五耶利米，","notes":[]},{"n":11,"t":"第六亚太，第七以利业，","notes":[]},{"n":12,"t":"第八约哈难，第九以利萨巴，","notes":[]},{"n":13,"t":"第十耶利米，第十一末巴奈。","notes":[]},{"n":14,"t":"这些都是迦得人中的军官，小的能抵一百人，大的能抵一千人。","notes":["“小的能抵...一千人”或译“较小的率领一百人，较大的率领一千人”。"]},{"n":15,"t":"正月，约旦河水涨过两岸的时候，他们过河，使所有住河谷的人东奔西逃。","notes":[]},{"n":16,"t":"便雅悯人和犹大人中有人来到山寨大卫那里。","notes":[],"heads":["跟随大卫的便雅悯人和犹大人"]},{"n":17,"t":"大卫出去迎接他们，回答他们说：“你们若和平地来帮助我，我的心就与你们契合；但你们若把我这双手无辜的人卖给敌人，愿我们列祖的神察看责罚。”","notes":[]},{"n":18,"t":"那时军官的领袖亚玛撒受灵的感动说：“大卫啊，我们归向你！耶西的儿子啊，我们帮助你！愿你平平安安，愿帮助你的也都平安！因为你的神帮助你。”大卫就收留他们，派他们作军官。","notes":["“军官”：原文另译“那三十个勇士”。"]},{"n":19,"t":"大卫从前与非利士人同去，要与扫罗争战，有些玛拿西人来投奔大卫。其实他们并没有帮助非利士人，因为非利士人的领袖商议，打发他回去，说：“恐怕大卫拿我们的首级去向他的主人扫罗投诚。”","notes":[],"heads":["跟随大卫的玛拿西人"]},{"n":20,"t":"大卫往洗革拉去的时候，有玛拿西人的千夫长押拿、约撒拔、耶叠、米迦勒、约撒拔、以利户、洗勒太都来投奔他。","notes":[]},{"n":21,"t":"他们帮助大卫攻击敌军；因为他们都是大能的勇士，又作军官。","notes":[]},{"n":22,"t":"那时天天有人来帮助大卫，以致成了强大的军队，如神的军队一样。","notes":[]},{"n":23,"t":"以下是来到希伯仑见大卫，要照耶和华的话把扫罗的国位归给大卫的武装士兵的数目：","notes":[],"heads":["大卫的军力"]},{"n":24,"t":"犹大人，拿盾牌和枪的武装战士有六千八百人。","notes":[]},{"n":25,"t":"西缅人中，能上阵的大能勇士有七千一百人。","notes":[]},{"n":26,"t":"利未人中，有四千六百人。","notes":[]},{"n":27,"t":"耶何耶大是亚伦家的领袖，跟从他的有三千七百人。","notes":[]},{"n":28,"t":"还有大能的青年勇士撒督，同他本族的二十二个军官。","notes":[]},{"n":29,"t":"便雅悯人中，扫罗同族的弟兄也有三千人；直到现在他们大部分仍然效忠扫罗家。","notes":[]},{"n":30,"t":"以法莲人中，在本族中著名的大能勇士有二万零八百人。","notes":[]},{"n":31,"t":"玛拿西半支派，册上有名来拥立大卫作王的，有一万八千人。","notes":[]},{"n":32,"t":"以萨迦人中，通达时务，知道以色列所当行，同族弟兄也都听从他们命令的族长有二百人。","notes":[]},{"n":33,"t":"西布伦中，能上阵用各样作战的兵器、不生二心帮助打仗的有五万人。","notes":[]},{"n":34,"t":"拿弗他利中，有一千个军官；跟从他们、拿盾牌和枪的有三万七千人。","notes":[]},{"n":35,"t":"但人中，能摆阵的有二万八千六百人。","notes":[]},{"n":36,"t":"亚设中，能上阵打仗的有四万人。","notes":[]},{"n":37,"t":"约旦河东的吕便人、迦得人、玛拿西半支派，拿各样兵器打仗的有十二万人。","notes":[]},{"n":38,"t":"以上都是能列队上阵的战士，他们都全心来到希伯仑，要拥立大卫作全以色列的王。以色列其余的人也都一心要拥立大卫作王。","notes":[]},{"n":39,"t":"他们在那里三日，与大卫一同吃喝，因为他们同族的弟兄已经为他们预备好了。","notes":[]},{"n":40,"t":"他们附近的人，以及以萨迦、西布伦、拿弗他利人，都将食物，许多面饼、无花果饼、干葡萄、酒、油，用驴、骆驼、骡子、牛驮来，又带了许多的牛和羊来，因为在以色列中充满了欢乐。","notes":[]}]},"13":{"heading":"约柜迁出基列．耶琳","verses":[{"n":1,"t":"大卫与千夫长、百夫长，以及所有的领袖商议。","notes":[]},{"n":2,"t":"大卫对以色列全会众说：“你们若以为好，见这事是出于耶和华－我们的神，我们就派人到远近各处去见仍留在以色列各地我们的弟兄，以及住在有郊野之城的祭司和利未人，使他们都到我们这里来聚集。","notes":[]},{"n":3,"t":"我们要把神的约柜接到这里来；因为在扫罗年间，我们没有去寻求约柜。”","notes":["“约柜”或译“神”。"]},{"n":4,"t":"全会众都说可以这么做，因这事在众百姓眼中都看为好。","notes":[]},{"n":5,"t":"于是，大卫把以色列众人从埃及的西曷河直到哈马口都召集了来，要从基列．耶琳将神的约柜接来。","notes":[]},{"n":6,"t":"大卫率领以色列众人上到巴拉，就是属犹大的基列．耶琳，要将耶和华神的约柜从那里接上来，他坐在二基路伯之上，这约柜是以他的名来命名的。","notes":[]},{"n":7,"t":"他们将神的约柜从亚比拿达的家里抬出来，放在新车上，由乌撒和亚希约赶车。","notes":[]},{"n":8,"t":"大卫和以色列众人在神面前随着诗歌、琴、瑟、鼓、钹、号，极力跳舞。","notes":[]},{"n":9,"t":"到了基顿的禾场，因为牛失前蹄，乌撒就伸手扶住约柜。","notes":["“基顿”：撒下6．6是“拿艮”。","“失前蹄”或译“惊跳”。"]},{"n":10,"t":"耶和华的怒气向乌撒发作，因他伸手扶住约柜而击杀他，他就死在那里，在神面前。","notes":[]},{"n":11,"t":"大卫因耶和华突然冲出撞死乌撒就生气，称那地方为毗列斯．乌撒，直到今日。","notes":[]},{"n":12,"t":"那日，大卫惧怕神，说：“我怎能将神的约柜接到我这里来呢？”","notes":[]},{"n":13,"t":"于是大卫不将约柜接进大卫城他自己的地方，却转送到迦特人俄别．以东的家中。","notes":[]},{"n":14,"t":"神的约柜停在俄别．以东家中三个月，耶和华赐福给俄别．以东的家和他一切所有的。","notes":[]}]},"14":{"heading":"大卫在耶路撒冷的活动","verses":[{"n":1,"t":"推罗王希兰派使者把香柏木运到大卫那里，又派石匠和木匠给大卫建造宫殿。","notes":[]},{"n":2,"t":"大卫知道耶和华坚立他作以色列王，又为自己百姓以色列的缘故，使他的国兴盛。","notes":[]},{"n":3,"t":"大卫在耶路撒冷又立后妃，又生儿女。","notes":[]},{"n":4,"t":"在耶路撒冷所生的孩子名字是沙母亚、朔罢、拿单、所罗门、","notes":["“沙母亚”：代上3．5称“示米亚”。"]},{"n":5,"t":"益辖、以利书亚、以法列、","notes":["“以利书亚”：代上3．6称“以利沙玛”。","“以法列”：代上3．6称“以利法列”。"]},{"n":6,"t":"挪迦、尼斐、雅非亚、","notes":[]},{"n":7,"t":"以利沙玛、比利雅大、以利法列。","notes":["“比利雅大”：撒下5．16，代上3．8称“以利雅大”。"]},{"n":8,"t":"非利士人听见大卫受膏作全以色列的王，非利士众人就上来寻索大卫。大卫听见了，就出去迎敌。","notes":[],"heads":["战胜非利士人"]},{"n":9,"t":"非利士人来了，侵犯利乏音谷。","notes":[]},{"n":10,"t":"大卫求问神说：“我可以上去攻打非利士人吗？你将他们交在我手里吗？”耶和华对他说：“你可以上去，我必将他们交在你手里。”","notes":[]},{"n":11,"t":"非利士人上到巴力．毗拉心，大卫在那里击败他们。大卫说：“神藉我的手冲破敌人，如水冲破一样。”因此那地方称为巴力．毗拉心。","notes":[]},{"n":12,"t":"非利士人把神像抛弃在那里，大卫吩咐人用火焚烧了。","notes":[]},{"n":13,"t":"非利士人又侵犯利乏音谷。","notes":[]},{"n":14,"t":"大卫再求问神。神对他说：“不要从他们后头追上去，要绕道离开他们，从桑树林对面攻打他们。","notes":[]},{"n":15,"t":"你听见桑树梢上有脚步的声音，那时你就要出战，因为神已经出去，在你前头攻打非利士人的军队了。”","notes":[]},{"n":16,"t":"大卫就遵照神所吩咐的去做，攻打非利士人的军队，从基遍直到基色。","notes":[]},{"n":17,"t":"于是大卫的名传扬到万邦，耶和华使万国都惧怕他。","notes":[]}]},"15":{"heading":"准备迎接约柜","verses":[{"n":1,"t":"大卫在大卫城为自己建造宫殿，又为神的约柜预备地方，支搭帐幕。","notes":[]},{"n":2,"t":"那时大卫说：“除了利未人之外，无人可抬神的约柜，因为耶和华拣选他们抬神的约柜，永远事奉他。”","notes":[]},{"n":3,"t":"大卫召集以色列众人到耶路撒冷，要将耶和华的约柜接到他所预备的地方。","notes":[]},{"n":4,"t":"大卫又召集亚伦的子孙和利未人：","notes":[]},{"n":5,"t":"哥辖子孙中有领袖乌列和他的弟兄一百二十人，","notes":[]},{"n":6,"t":"米拉利子孙中有领袖亚帅雅和他的弟兄二百二十人，","notes":[]},{"n":7,"t":"革顺子孙中有领袖约珥和他的弟兄一百三十人，","notes":[]},{"n":8,"t":"以利撒反子孙中有领袖示玛雅和他的弟兄二百人，","notes":[]},{"n":9,"t":"希伯伦子孙中有领袖以利业和他的弟兄八十人，","notes":[]},{"n":10,"t":"乌薛子孙中有领袖亚米拿达和他的弟兄一百一十二人。","notes":[]},{"n":11,"t":"大卫召来撒督和亚比亚他二位祭司，以及利未人乌列、亚帅雅、约珥、示玛雅、以利业、亚米拿达，","notes":[]},{"n":12,"t":"对他们说：“你们是利未人的族长，你们和你们的弟兄应当使自己分别为圣，好将耶和华－以色列神的约柜接到我所预备的地方。","notes":[]},{"n":13,"t":"因为你们上一次没有抬这约柜，并且我们没有按规矩求问耶和华－我们的神，所以他冲出来攻击我们。”","notes":[]},{"n":14,"t":"于是祭司和利未人使自己分别为圣，将耶和华－以色列神的约柜接上来。","notes":[]},{"n":15,"t":"利未子孙用杠，把神的约柜抬在肩上，正如摩西按照耶和华的话所吩咐的。","notes":[]},{"n":16,"t":"大卫吩咐利未人的领袖派他们歌唱的弟兄用琴瑟和钹的乐器奏乐，欢欢喜喜地大声歌颂。","notes":[]},{"n":17,"t":"于是利未人派约珥的儿子希幔和他弟兄中比利家的儿子亚萨，以及他们同族弟兄米拉利子孙里古沙雅的儿子以探。","notes":[]},{"n":18,"t":"其次还有跟随他们的弟兄撒迦利雅、便．雅薛、示米拉末、耶歇、乌尼、以利押、比拿雅、玛西雅、玛他提雅、以利斐利户、弥克尼雅，以及门口的守卫俄别．以东和耶利。","notes":["“便．雅薛”：有古卷和七十士译本是“雅薛”。"]},{"n":19,"t":"歌唱的希幔、亚萨和以探，敲铜钹，声音响亮；","notes":[]},{"n":20,"t":"撒迦利雅、雅薛、示米拉末、耶歇、乌尼、以利押、玛西雅、比拿雅鼓瑟，调用女音；","notes":[]},{"n":21,"t":"玛他提雅、以利斐利户、弥克尼雅、俄别．以东、耶利、亚撒西雅用琴指挥，调用第八。","notes":[]},{"n":22,"t":"基拿尼雅是利未人圣咏团的领袖，又教导人唱歌，因为他精通此事。","notes":[]},{"n":23,"t":"比利家和以利加拿是约柜的守卫。","notes":[]},{"n":24,"t":"示巴尼、约沙法、拿坦业、亚玛赛、撒迦利雅、比拿亚、以利以谢众祭司在神的约柜前吹号。俄别．以东和耶希亚也是约柜的守卫。","notes":[]},{"n":25,"t":"于是，大卫和以色列的长老，以及千夫长都去，欢欢喜喜地将耶和华的约柜从俄别．以东家中接上来。","notes":[],"heads":["约柜迁入耶路撒冷"]},{"n":26,"t":"神赐恩给抬耶和华约柜的利未人，他们就献上七头公牛、七只公羊。","notes":[]},{"n":27,"t":"大卫和所有抬约柜的利未人，以及圣咏团的领袖基拿尼雅和歌唱的人，都穿着细麻布外袍；大卫另外穿着细麻布以弗得。","notes":[]},{"n":28,"t":"这样，以色列众人欢呼、吹角、吹号、敲钹、鼓瑟、弹琴，声音响亮，将耶和华的约柜接上来。","notes":[]},{"n":29,"t":"耶和华的约柜进大卫城的时候，扫罗的女儿米甲从窗户里往外观看，见大卫王踊跃跳舞，心里就轻视他。","notes":[]}]},"16":{"heading":"颂赞之歌","verses":[{"n":1,"t":"众人将神的约柜请进去，安放在大卫为它搭的帐幕中，就在神面前献燔祭和平安祭。","notes":[]},{"n":2,"t":"大卫献完了燔祭和平安祭，就奉耶和华的名祝福百姓，","notes":[]},{"n":3,"t":"并且分给每一个以色列人，无论男女，每人一个饼，一个枣子饼，一个葡萄饼。","notes":["“一个枣子饼”：有古译本是“一块肉”。"]},{"n":4,"t":"大卫派几个利未人在耶和华的约柜前事奉，颂扬，称谢，赞美耶和华－以色列的神：","notes":[]},{"n":5,"t":"为首的是亚萨，其次是撒迦利雅、耶利、示米拉末、耶歇、玛他提雅、以利押、比拿雅、俄别．以东、耶利；他们鼓瑟弹琴，亚萨敲钹，声音响亮；","notes":["“耶利”：原文另译“雅薛”；参代上15．18，20。"]},{"n":6,"t":"比拿雅和雅哈悉二位祭司常在神的约柜前吹号。","notes":[]},{"n":7,"t":"那日，大卫初次指派亚萨和他的弟兄称谢耶和华。","notes":[]},{"n":8,"t":"你们要称谢耶和华，求告他的名，在万民中传扬他的作为！","notes":[]},{"n":9,"t":"要向他唱诗，向他歌颂，述说他一切奇妙的作为！","notes":[]},{"n":10,"t":"要夸耀他的圣名！愿寻求耶和华的人心中欢喜！","notes":[]},{"n":11,"t":"要寻求耶和华与他的能力，时常寻求他的面。","notes":[]},{"n":12,"t":"他仆人以色列的后裔，他所拣选雅各的子孙哪，要记念他奇妙的作为和他的奇事，并他口中的判语。","notes":[],"end":13},{"n":14,"t":"他是耶和华－我们的神，全地都有他的判断。","notes":[]},{"n":15,"t":"要记念他的约，直到永远；记念他吩咐的话，直到千代，","notes":[]},{"n":16,"t":"就是他与亚伯拉罕所立的约，向以撒所起的誓。","notes":[]},{"n":17,"t":"他将这约向雅各定为律例，向以色列定为永远的约，","notes":[]},{"n":18,"t":"说：“我必将迦南地赐给你，作你们应得的产业。”","notes":[]},{"n":19,"t":"当时，你们人丁有限，数目稀少，在那地寄居。","notes":[]},{"n":20,"t":"他们从这邦游到那邦，从这国去到另一民族。","notes":[]},{"n":21,"t":"他不容人欺负他们，为他们的缘故责备君王：","notes":[]},{"n":22,"t":"“不可伤害我的受膏者，也不可恶待我的先知。”","notes":[]},{"n":23,"t":"全地都要向耶和华歌唱！天天传扬他的救恩！","notes":[]},{"n":24,"t":"在列国中述说他的荣耀！在万民中述说他的奇事！","notes":[]},{"n":25,"t":"因耶和华本为大，当受极大的赞美；他在万神之上，当受敬畏。","notes":[]},{"n":26,"t":"因万民的神明都属虚无；惟独耶和华创造诸天。","notes":[]},{"n":27,"t":"有尊荣和威严在他面前，有能力和喜乐在他自己的地方。","notes":[]},{"n":28,"t":"民中的万族啊，要将荣耀、能力归给耶和华，都归给耶和华！","notes":[]},{"n":29,"t":"要将耶和华的名所当得的荣耀归给他，拿供物来献在他面前；当敬拜神圣荣耀的耶和华。","notes":["“当敬拜...耶和华”或译“当以圣洁的妆饰敬拜耶和华”。"]},{"n":30,"t":"全地都要在他面前战抖！世界坚定，不得动摇。","notes":[]},{"n":31,"t":"愿天欢喜，愿地快乐！愿人在列国中说：“耶和华作王了！”","notes":[]},{"n":32,"t":"愿海和其中所充满的澎湃！愿田和其中所有的都欢乐！","notes":[]},{"n":33,"t":"那时，林中的树木都要在耶和华面前欢呼，因为他来要审判全地。","notes":[]},{"n":34,"t":"你们要称谢耶和华，因他本为善，他的慈爱永远长存！","notes":[]},{"n":35,"t":"你们要说：“拯救我们的神啊，求你拯救我们，聚集我们，救我们脱离列国，我们好颂扬你的圣名，以赞美你为夸胜。","notes":[]},{"n":36,"t":"耶和华－以色列的神是应当称颂的，从亘古直到永远。”全体百姓都说：“阿们！”并且赞美耶和华。","notes":[]},{"n":37,"t":"大卫把亚萨和他的弟兄留在耶和华的约柜那里，经常在约柜前事奉，天天尽本分供职，","notes":[],"heads":["在耶路撒冷和基遍的敬拜"]},{"n":38,"t":"又有俄别．以东和他的弟兄六十八人；耶杜顿的儿子俄别．以东，以及何萨作门口的守卫。","notes":[]},{"n":39,"t":"还有撒督祭司和他弟兄众祭司在基遍的丘坛、耶和华的帐幕前，","notes":[]},{"n":40,"t":"在燔祭坛上，每日早晚，照着写在耶和华律法书上所吩咐以色列的，经常献燔祭给耶和华。","notes":[]},{"n":41,"t":"与他们一同的还有希幔、耶杜顿，和其余被选、名字录在册上的，为要称谢耶和华，因他的慈爱永远长存。","notes":[]},{"n":42,"t":"希幔、耶杜顿同他们吹号、敲钹，声音响亮，并用其他乐器配合，歌颂神。耶杜顿的子孙作门口的守卫。","notes":[]},{"n":43,"t":"于是众百姓各自回家，大卫也回去为家人祝福。","notes":[]}]},"17":{"heading":"拿单传给大卫的信息","verses":[{"n":1,"t":"大卫住在自己宫中，对拿单先知说：“看哪，我住在香柏木的宫中，耶和华的约柜却在幔子里。”","notes":[]},{"n":2,"t":"拿单对大卫说：“你可以完全照你的心意去做，因为神与你同在。”","notes":[]},{"n":3,"t":"当夜神的话临到拿单，说：","notes":[]},{"n":4,"t":"“你去对我仆人大卫说：‘耶和华如此说：你不可建造殿宇给我居住。","notes":[]},{"n":5,"t":"自从我领以色列人上来，直到今日，我未曾住过殿宇；我从这会幕到那会幕，从这帐幕到那帐幕。","notes":["原文没有“到那帐幕”。"]},{"n":6,"t":"凡我同以色列人所走的地方，我何曾向以色列的一个士师，就是我吩咐牧养我百姓的，说过这话：你们为何不给我建造香柏木的殿宇呢？’","notes":[]},{"n":7,"t":"现在，你要对我仆人大卫这样说：‘万军之耶和华如此说：我从羊圈中将你召来，叫你不再牧放羊群，立你作我百姓以色列的君王。","notes":[]},{"n":8,"t":"你无论往哪里去，我都与你同在，剪除你所有的仇敌。我必使你得大名，好像世上伟人的名一样。","notes":[]},{"n":9,"t":"我必为我百姓以色列选定一个地方，栽植他们，使他们住自己的地方，不再受搅扰；凶恶之子也不再像从前那样扰乱他们，","notes":[]},{"n":10,"t":"并不像我命令士师治理我百姓以色列的日子。我必制伏你所有的仇敌，并且我应许你，耶和华必为你建立家室。","notes":["“我应许你”：七十士译本是“我要使你为大”。"]},{"n":11,"t":"当你寿数满足归你祖先的时候，我必使你的后裔，你自己的儿子接续你；我也必坚定他的国。","notes":[]},{"n":12,"t":"他必为我建造殿宇，我必坚定他的王位，直到永远。","notes":[]},{"n":13,"t":"我要作他的父，他要作我的子；我必不使我的慈爱离开他，像离开在你以前的那位一样。","notes":[]},{"n":14,"t":"我要永远坚立他在我的家和我的国里；他的王位也必坚定，直到永远。’”","notes":[]},{"n":15,"t":"拿单就按这一切话，照这一切异象告诉大卫。","notes":[]},{"n":16,"t":"于是大卫王进去，坐在耶和华面前，说：“耶和华神啊，我是谁，我的家算什么，你竟带领我到这地步呢？","notes":[],"heads":["感恩的祷告"]},{"n":17,"t":"神啊，这在你眼中还看为小，你又说到你仆人的家将来的情况。耶和华神啊，你看顾我好像看顾尊贵的人。","notes":[]},{"n":18,"t":"你加于仆人的尊荣，大卫还有什么可以对你说呢？你是知道你仆人的。","notes":[]},{"n":19,"t":"耶和华啊，因你仆人的缘故，也照着你的心意，你行这一切大事，为了显明这一切伟大的事。","notes":[]},{"n":20,"t":"耶和华啊，照我们耳中一切所听见的，没有可比你的，除你以外再没有神。","notes":[]},{"n":21,"t":"世上有何国能比你的百姓以色列呢？神亲自去救赎世上的一国，作自己的子民，又行大而可畏的事，显出你的大名，在你从埃及赎出来的子民面前驱逐了列国。","notes":["“世上...一国”：七十士译本是“世上没有另一国能比你的百姓以色列，是神亲自去救赎”。"]},{"n":22,"t":"你使你的百姓以色列作你的子民，直到永远；你－耶和华也作他们的神。","notes":[]},{"n":23,"t":"现在，耶和华啊，你所应许仆人和仆人家的话，求你坚定，直到永远；求你照你所说的而行。","notes":[]},{"n":24,"t":"愿你的名永远坚立，被尊为大，人要说：‘万军之耶和华－以色列的神，是以色列的神。’这样，你仆人大卫的家必在你面前坚立。","notes":[]},{"n":25,"t":"我的神啊，因你启示你的仆人，要为他建立家室，所以仆人大胆在你面前祈祷。","notes":[]},{"n":26,"t":"现在，耶和华啊，惟有你是神！你应许将这福气赐给仆人。","notes":[]},{"n":27,"t":"现在，你喜悦赐福给仆人的家，可以永存在你面前。耶和华啊，因你已经赐福，还要赐福到永远。”","notes":[]}]},"18":{"heading":"耶和华使大卫得胜","verses":[{"n":1,"t":"此后，大卫攻打非利士人，制伏了他们，从非利士人手中夺取了迦特和所属的乡镇。","notes":[]},{"n":2,"t":"他又攻打摩押，摩押人就臣服大卫，向他进贡。","notes":[]},{"n":3,"t":"琐巴王哈大底谢往幼发拉底河去，要巩固自己的国权。大卫攻打他，直到哈马，","notes":["“哈大底谢”：有许多抄本是“哈大利谢”；本卷书下同。"]},{"n":4,"t":"夺了他的战车一千，俘掳了骑兵七千人，步兵二万人。大卫把所有战马的蹄筋砍断，只留下一百辆战车。","notes":[]},{"n":5,"t":"大马士革的亚兰人来帮助琐巴王哈大底谢，大卫杀了亚兰人二万二千。","notes":[]},{"n":6,"t":"于是大卫在大马士革的亚兰地设立军营，亚兰人就臣服大卫，向他进贡。大卫无论往哪里去，耶和华都使他得胜。","notes":["“设立军营”是根据一些古卷和七十士译本，原文没有“军营”；参撒下8．6。"]},{"n":7,"t":"大卫夺了哈大底谢臣仆拥有的金盾牌，带到耶路撒冷。","notes":[]},{"n":8,"t":"大卫又从哈大底谢的提巴和均二城夺取了许多的铜；后来所罗门用这些铜制造铜海、铜柱和铜器。","notes":[]},{"n":9,"t":"哈马王陀乌听见大卫击败琐巴王哈大底谢的全军，","notes":["“陀乌”：撒下8．9称“陀以”；下同。"]},{"n":10,"t":"就派他儿子哈多兰到大卫王那里，向他请安，为他祝福，因他与哈大底谢争战，并且击败了他；原来哈大底谢与陀乌常常争战。哈多兰带了金银铜的各样器皿来。","notes":["“哈多兰”：撒下8．10称“约兰”。"]},{"n":11,"t":"大卫王把这些器皿，以及从各国夺来的金银，就是从以东、摩押、亚扪人、非利士人、亚玛力所夺来的，都分别为圣献给耶和华。","notes":[]},{"n":12,"t":"洗鲁雅的儿子亚比筛在盐谷击杀了一万八千以东人。","notes":[]},{"n":13,"t":"大卫在以东设立军营，以东人就都臣服他。大卫无论往哪里去，耶和华都使他得胜。","notes":[]},{"n":14,"t":"大卫作全以色列的王，又向众百姓秉公行义。","notes":[]},{"n":15,"t":"洗鲁雅的儿子约押作元帅；亚希律的儿子约沙法作史官；","notes":[]},{"n":16,"t":"亚希突的儿子撒督和亚比亚他的儿子亚希米勒作祭司；沙威沙作书记；","notes":[]},{"n":17,"t":"耶何耶大的儿子比拿雅管辖基利提人和比利提人。大卫的众儿子都在王的左右作领袖。","notes":[]}]},"19":{"heading":"击败亚扪人和亚兰人","verses":[{"n":1,"t":"此后，亚扪人的王拿辖死了，他儿子接续他作王。","notes":[]},{"n":2,"t":"大卫说：“哈嫩的父亲拿辖怎样向我施恩，我也要怎样向哈嫩施恩。”于是大卫派使者为他的父亲安慰他。大卫的臣仆到了亚扪人的境内来见哈嫩，要安慰他。","notes":[]},{"n":3,"t":"但亚扪人的领袖对哈嫩说：“大卫派人来安慰你，你看他是要尊敬你父亲吗？他的臣仆来见你，不是为了要窥探侦察，而倾覆这地吗？”","notes":[]},{"n":4,"t":"哈嫩就抓住大卫的臣仆，剃去他们的胡须，又割断他们下半截的衣服，露出臀部，然后放了他们。","notes":[]},{"n":5,"t":"他们走了，有人把臣仆所遭遇的事告诉大卫，他就派人去迎接他们，因为这些人觉得很羞耻。王说：“可以住在耶利哥，等到胡须长出来再回来。”","notes":[]},{"n":6,"t":"亚扪人看到大卫憎恶他们，哈嫩和亚扪人就派人拿一千他连得银子，从美索不达米亚、亚兰．玛迦、琐巴雇用战车和骑兵。","notes":[]},{"n":7,"t":"他们雇了三万二千辆战车，以及玛迦王和他的军兵；这些部队来安营在米底巴前。亚扪人也从他们的城里出来，聚集预备作战。","notes":[]},{"n":8,"t":"大卫听见了，就派约押和所有勇猛的军队出去。","notes":[]},{"n":9,"t":"亚扪人出来，在城门前摆阵，前来的诸王另在郊野摆阵。","notes":[]},{"n":10,"t":"约押看见战阵对着他前后摆列，就把从以色列所有精兵中挑选出来的，摆阵迎战亚兰人。","notes":[]},{"n":11,"t":"他把其余的兵交在他兄弟亚比筛手里，他们就摆阵迎战亚扪人。","notes":[]},{"n":12,"t":"约押说：“亚兰人若强过我，你就来帮助我；亚扪人若强过你，我就去帮助你。","notes":[]},{"n":13,"t":"你要刚强，我们要为自己的百姓，为我们神的城镇奋勇。愿耶和华照他所看为好的去做！”","notes":[]},{"n":14,"t":"于是，约押和跟随他的士兵前进攻打亚兰人；亚兰人在他面前逃跑。","notes":[]},{"n":15,"t":"亚扪人见亚兰人逃跑，他们也在约押的兄弟亚比筛面前逃跑进城。约押就回耶路撒冷去了。","notes":[]},{"n":16,"t":"亚兰人见自己被以色列打败，就派使者把大河那边的亚兰人调来，由哈大底谢的将军朔法在他们前面率领。","notes":[]},{"n":17,"t":"有人告诉大卫，他就聚集以色列众人过约旦河，来到亚兰人那里，迎着他们摆阵。大卫摆阵攻击亚兰人，亚兰人就与他打仗。","notes":[]},{"n":18,"t":"亚兰人在以色列人面前逃跑。大卫杀了亚兰七千辆战车的士兵，四万步兵，又杀死亚兰的将军朔法。","notes":[]},{"n":19,"t":"哈大底谢的臣仆见自己被以色列打败，就与大卫讲和，臣服他。于是亚兰人不愿再帮助亚扪人了。","notes":[]}]},"20":{"heading":"大卫攻取拉巴","verses":[{"n":1,"t":"到了年初，诸王出征的时候，约押率领军兵蹂躏亚扪人的地，前来围攻拉巴；大卫仍住在耶路撒冷。约押攻打拉巴，把它毁坏。","notes":[]},{"n":2,"t":"大卫夺了米勒公所戴的冠冕，其上的金子重一他连得，又嵌着宝石。这冠冕就戴在大卫头上。大卫又从城里夺了许多财物，","notes":["“米勒公”是根据七十士译本和其他古译本，亚扪人神明的名字，又名“摩洛”；原文是“他们的王”，音译“玛勒堪”。"]},{"n":3,"t":"把城里的百姓拉出来，放在锯下，或铁耙下，或斧的下面；大卫待亚扪各城的居民都是如此。于是，大卫和全军都回耶路撒冷去了。","notes":["“斧”是根据一些古卷；原文是“锯”。"]},{"n":4,"t":"后来，以色列人在基色与非利士人打仗。户沙人西比该杀了巨人族的后裔细派，非利士人就被制伏了。","notes":[],"heads":["与非利士巨人争战"]},{"n":5,"t":"他们又与非利士人打仗。睚珥的儿子伊勒哈难杀了迦特人歌利亚的兄弟拉哈米；这人的枪杆粗如织布机的轴。","notes":[]},{"n":6,"t":"又有一次，他们在迦特打仗。那里有一个身材高大的人，手指脚趾都是六根，共有二十四根；他也是巨人族的后裔。","notes":[]},{"n":7,"t":"他向以色列骂阵，大卫的哥哥示米亚的儿子约拿单就杀了他。","notes":[]},{"n":8,"t":"这些人是迦特巨人族的后裔，都仆倒在大卫和他仆人的手下。","notes":[]}]},"21":{"heading":"大卫数点以色列民","verses":[{"n":1,"t":"撒但起来攻击以色列，激起大卫数点以色列人。","notes":[]},{"n":2,"t":"大卫对约押和百姓的领袖说：“去，数点以色列人，从别是巴直到但，回来告诉我，我好知道他们的数目。”","notes":[]},{"n":3,"t":"约押说：“愿耶和华使他的百姓比现在加增百倍。我主我王啊，他们不都是我主的仆人吗？我主为何吩咐行这事，为何使以色列陷入罪里呢？”","notes":[]},{"n":4,"t":"但王坚持他对约押的命令。约押就出去，来回走遍以色列，然后回到耶路撒冷。","notes":[]},{"n":5,"t":"约押向大卫报告百姓的总数：全以色列拿刀的有一百一十万人；犹大拿刀的有四十七万人。","notes":[]},{"n":6,"t":"惟有利未人和便雅悯人没有算在其中，因为约押厌恶王的这命令。","notes":[]},{"n":7,"t":"这件事在神眼中看为恶，神就降灾给以色列。","notes":[]},{"n":8,"t":"大卫对神说：“我做这事大大有罪了。现在求你除掉仆人的罪孽，因为我所做的非常愚昧。”","notes":[]},{"n":9,"t":"耶和华吩咐迦得，大卫的先见，说：","notes":[]},{"n":10,"t":"“你去告诉大卫说：‘耶和华如此说：我列出三样灾祸给你，随你选择一样，我好降与你。’”","notes":[]},{"n":11,"t":"于是，迦得来到大卫那里，对他说：“耶和华如此说：‘你可以随意选择：","notes":[]},{"n":12,"t":"三年的饥荒，或败在敌人面前，被敌人的刀追杀三个月，或在国中三日有耶和华的刀，就是瘟疫，让耶和华的使者在以色列全境施行毁灭呢？’现在你要想一想，我怎样去回覆那差我来的。”","notes":[]},{"n":13,"t":"大卫对迦得说：“我很为难。我宁愿落在耶和华的手里，因为他有丰盛的怜悯；我不愿落在人的手里。”","notes":[]},{"n":14,"t":"于是，耶和华降瘟疫给以色列，以色列中死了七万人。","notes":[]},{"n":15,"t":"神派遣使者去毁灭耶路撒冷，刚要毁灭的时候，耶和华看见就改变心意，不降这灾了。他吩咐那灭城的天使说：“够了，住手吧！”耶和华的使者正站在耶布斯人阿珥楠的禾场那里。","notes":["“阿珥楠”：撒下24．16称“亚劳拿”；下同。"]},{"n":16,"t":"大卫举目，看见耶和华的使者站在天和地之间，手里有拔出来的刀，伸在耶路撒冷以上。大卫和长老都披上麻布，脸伏于地。","notes":[]},{"n":17,"t":"大卫向神说：“吩咐数点百姓的不是我吗？是我犯了罪，行了大恶，但这群羊做了什么呢？耶和华－我的神啊，愿你的手攻击我和我的父家，不要降瘟疫给你的百姓。”","notes":[]},{"n":18,"t":"耶和华的使者吩咐迦得去告诉大卫，叫他上去，在耶布斯人阿珥楠的禾场上为耶和华立一座坛。","notes":[]},{"n":19,"t":"大卫就照着迦得奉耶和华名所说的话上去。","notes":[]},{"n":20,"t":"阿珥楠回头看见天使，跟他在一起的四个儿子都藏起来了，阿珥楠继续打麦子。","notes":[]},{"n":21,"t":"大卫到了阿珥楠那里，阿珥楠观看，看见大卫，就从禾场上出去，脸伏于地，向他下拜。","notes":[]},{"n":22,"t":"大卫对阿珥楠说：“你把这禾场的地方给我，照着十足的价钱卖给我，我好在其上为耶和华筑一座坛，使瘟疫在百姓中停止。”","notes":[]},{"n":23,"t":"阿珥楠对大卫说：“请用这禾场吧，愿我主我王照你眼中看为好的去做。看，我提供牛作燔祭，打粮的器具作柴，麦子作素祭，这一切我全都提供。”","notes":[]},{"n":24,"t":"大卫王对阿珥楠说：“不，我一定要按十足的价钱买；因我不能用你的东西献给耶和华，也不能用白得之物献为燔祭。”","notes":[]},{"n":25,"t":"于是大卫为那个地方付了六百舍客勒重的金子给阿珥楠。","notes":[]},{"n":26,"t":"大卫在那里为耶和华筑了一座坛，献燔祭和平安祭，求告耶和华。耶和华就应允他，使火从天降在燔祭坛上。","notes":[]},{"n":27,"t":"耶和华吩咐使者，他就收刀入鞘。","notes":[]},{"n":28,"t":"那时，大卫见耶和华在耶布斯人阿珥楠的禾场上应允了他，就在那里献祭。","notes":[]},{"n":29,"t":"摩西在旷野所造之耶和华的帐幕和燔祭坛，当时都在基遍的丘坛，","notes":[]},{"n":30,"t":"只是大卫不能前去求问神，因为他惧怕耶和华使者的刀。","notes":[]}]},"22":{"heading":"筹备建殿","verses":[{"n":1,"t":"大卫说：“这是耶和华神的殿，这是以色列献燔祭的坛。”","notes":[]},{"n":2,"t":"大卫吩咐人召集住以色列地的寄居者，又派石匠凿石头，要建造神的殿。","notes":[]},{"n":3,"t":"大卫预备许多铁，要做门上的钉子和钩子，又预备许多铜，多得无法可秤；","notes":[]},{"n":4,"t":"还有无数的香柏木，因为西顿人和推罗人给大卫运了许多香柏木来。","notes":[]},{"n":5,"t":"大卫说：“我儿子所罗门还年幼脆弱，要为耶和华建造的殿宇必须高大辉煌，使名声荣耀传遍万国，所以我要为殿预备。”于是，大卫在未死之前预备了许多材料。","notes":[]},{"n":6,"t":"大卫召了他儿子所罗门来，吩咐他为耶和华－以色列的神建造殿宇。","notes":[]},{"n":7,"t":"大卫对所罗门说：“我儿啊，我心里本想为耶和华－我神的名建造殿宇，","notes":[]},{"n":8,"t":"可是耶和华的话临到我说：‘你流了许多的血，打了多次大仗；你不可为我的名建造殿宇，因为你在我面前使许多血流在地上。","notes":[]},{"n":9,"t":"看哪，你要生一个儿子，他必成为安宁的人；我必使他得享安宁，不被四围仇敌扰乱。他的名字要叫所罗门，在他的日子，我必使以色列平安康泰。","notes":["“所罗门”意思是“平安”。"]},{"n":10,"t":"他必为我的名建造殿宇。他要作我的子，我要作他的父。我必坚定他国度的王位，使他治理以色列，直到永远。’","notes":[]},{"n":11,"t":"我儿啊，现今愿耶和华与你同在，使你亨通，建造耶和华－你神的殿，正如他指着你所说的。","notes":[]},{"n":12,"t":"但愿耶和华赐你聪明智慧，好按着他吩咐你的去治理以色列，遵行耶和华－你神的律法。","notes":[]},{"n":13,"t":"那时候，你若谨守遵行耶和华藉摩西吩咐以色列的律例典章，就得亨通。你当刚强壮胆，不要惧怕，也不要惊惶。","notes":[]},{"n":14,"t":"看哪，我辛苦地为耶和华的殿预备了十万他连得金子，一百万他连得银子，铜和铁多得无法可秤；我也预备了木头、石头，你还可以增添。","notes":[]},{"n":15,"t":"你有许多工匠，就是石匠、木匠，和一切能做各样工的巧匠，","notes":[]},{"n":16,"t":"以及无数的金银铜铁。你当起来做工，愿耶和华与你同在。”","notes":[]},{"n":17,"t":"大卫又吩咐以色列的众官长帮助他儿子所罗门：","notes":[]},{"n":18,"t":"“耶和华－你们的神不是与你们同在吗？他不是使你们四围都平安吗？因他已将这地的居民交在我手中，这地已在耶和华与他百姓面前制伏了。","notes":[]},{"n":19,"t":"现在你们应当立定心意，寻求耶和华－你们的神。你们当起来建造耶和华神的圣所，好将耶和华的约柜和神神圣的器皿都搬进为耶和华的名建造的殿里。”","notes":[]}]},"23":{"heading":"利未人的职务","verses":[{"n":1,"t":"大卫年纪老迈，日子满足，就立他儿子所罗门作以色列的王。","notes":[]},{"n":2,"t":"大卫召集以色列的众领袖、祭司和利未人。","notes":[]},{"n":3,"t":"利未人三十岁以上的都被数点，他们男丁的数目共有三万八千；","notes":[]},{"n":4,"t":"其中有二万四千人管理耶和华殿的事务，有六千人作官长和审判官，","notes":[]},{"n":5,"t":"有四千人作门口的守卫，又有四千人颂赞耶和华，用大卫造的乐器来颂赞。","notes":["“大卫”：原文是“我”。"]},{"n":6,"t":"大卫把利未人革顺、哥辖、米拉利的子孙分了班次。","notes":[]},{"n":7,"t":"属革顺的有拉但和示每。","notes":[]},{"n":8,"t":"拉但的长子是耶歇，还有西坦和约珥，共三人。","notes":[]},{"n":9,"t":"示每的儿子是示罗密、哈薛、哈兰三人。这是拉但族的族长。","notes":[]},{"n":10,"t":"示每的儿子是雅哈、细拿、耶乌施、比利亚，这四人是示每的儿子。","notes":["“细拿”:有古卷、七十士译本和其他古译本是“细撒”。"]},{"n":11,"t":"雅哈是长子，细撒是次子。但耶乌施和比利亚的子孙不多，所以算为一族。","notes":[]},{"n":12,"t":"哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛，共四人。","notes":[]},{"n":13,"t":"暗兰的儿子是亚伦和摩西。亚伦被分别出来，把至圣之物分别为圣，使他和他的子孙在耶和华面前烧香、事奉他，奉他的名祝福，直到永远。","notes":[]},{"n":14,"t":"至于神人摩西，他的子孙记名在利未支派下。","notes":[]},{"n":15,"t":"摩西的儿子是革舜和以利以谢。","notes":[]},{"n":16,"t":"革舜的儿子，长子是细布业；","notes":[]},{"n":17,"t":"以利以谢的儿子，长子是利哈比雅。以利以谢没有别的儿子，但利哈比雅的子孙很多。","notes":[]},{"n":18,"t":"以斯哈的儿子，长子是示罗密。","notes":[]},{"n":19,"t":"希伯伦的儿子，长子是耶利雅，次子是亚玛利亚，三子是雅哈悉，四子是耶加面。","notes":[]},{"n":20,"t":"乌薛的儿子，长子是米迦，次子是耶西雅。","notes":[]},{"n":21,"t":"米拉利的儿子是抹利和母示。抹利的儿子是以利亚撒和基士。","notes":[]},{"n":22,"t":"以利亚撒死了，没有儿子，只有女儿，他们本族基士的几个儿子娶了她们为妻。","notes":[]},{"n":23,"t":"母示的儿子是末力、以得、耶利末，共三人。","notes":[]},{"n":24,"t":"以上是利未子孙作族长的，按着父系、照着男丁的数目，二十岁以上登记的，都办理耶和华殿的事务。","notes":[]},{"n":25,"t":"大卫说：“耶和华－以色列的神已经使他的百姓得享安宁，他永远住在耶路撒冷。","notes":[]},{"n":26,"t":"因此，利未人不必再抬帐幕和其中所使用的一切器皿了。”","notes":[]},{"n":27,"t":"照着大卫临终的话，利未人二十岁以上的都被数点。","notes":[]},{"n":28,"t":"他们的职务是作亚伦子孙的帮手，在耶和华的殿事奉，照管院子和屋子，洁净一切圣物，办理神殿的事务。","notes":[]},{"n":29,"t":"他们负责预备供饼、素祭的细面和无酵薄饼，或用盘烤，或用油调和的祭物，确认其数量和大小。","notes":[]},{"n":30,"t":"每日早晚、安息日、初一，以及节期，按数照例，经常献燔祭给耶和华的时候，他们站立称谢赞美耶和华。","notes":[],"end":31},{"n":32,"t":"他们照管会幕和圣所，服事他们的弟兄亚伦的子孙，办理耶和华殿的事务。","notes":[]}]},"24":{"heading":"祭司的职务","verses":[{"n":1,"t":"亚伦子孙的班次如下：亚伦的儿子是拿答、亚比户、以利亚撒、以他玛。","notes":[]},{"n":2,"t":"拿答和亚比户死在他们父亲之先，没有留下儿子；因此，以利亚撒和以他玛担任祭司的职分。","notes":[]},{"n":3,"t":"大卫和以利亚撒的子孙撒督，以及以他玛的子孙亚希米勒，把他们按照任务分成班次，","notes":[]},{"n":4,"t":"发现以利亚撒子孙中作领袖的，比以他玛子孙中作领袖的更多，就分班如下：以利亚撒的子孙中有十六个族长，以他玛的子孙中有八个族长。","notes":[]},{"n":5,"t":"他们抽签分配，彼此一样。在圣所和神面前作领袖的有以利亚撒的子孙，也有以他玛的子孙。","notes":[]},{"n":6,"t":"作书记的利未人拿坦业的儿子示玛雅在王和领袖，与撒督祭司、亚比亚他的儿子亚希米勒，以及祭司和利未人的族长面前记录他们的名字；在以利亚撒的子孙中取一族，在以他玛的子孙中也取一族。","notes":[]},{"n":7,"t":"抽签的时候，第一签抽到的是耶何雅立，第二是耶大雅，","notes":[]},{"n":8,"t":"第三是哈琳，第四是梭琳，","notes":[]},{"n":9,"t":"第五是玛基雅，第六是米雅民，","notes":[]},{"n":10,"t":"第七是哈歌斯，第八是亚比雅，","notes":[]},{"n":11,"t":"第九是耶书亚，第十是示迦尼，","notes":[]},{"n":12,"t":"第十一是以利亚实，第十二是雅金，","notes":[]},{"n":13,"t":"第十三是胡巴，第十四是耶是比押，","notes":[]},{"n":14,"t":"第十五是璧迦，第十六是音麦，","notes":[]},{"n":15,"t":"第十七是希悉，第十八是哈辟悉，","notes":[]},{"n":16,"t":"第十九是毗他希雅，第二十是以西结，","notes":[]},{"n":17,"t":"第二十一是雅斤，第二十二是迦末，","notes":[]},{"n":18,"t":"第二十三是第来雅，第二十四是玛西亚。","notes":[]},{"n":19,"t":"这就是他们事奉的班次，要照耶和华－以色列的神藉他们祖宗亚伦所吩咐的条例，进入耶和华的殿办理事务。","notes":[]},{"n":20,"t":"利未其余的子孙如下：暗兰的子孙中有书巴业；书巴业的子孙中有耶希底亚。","notes":[],"heads":["利未人名单"]},{"n":21,"t":"属利哈比雅，利哈比雅的儿子中有长子伊示雅。","notes":[]},{"n":22,"t":"属以斯哈人的有示罗摩；示罗摩的子孙中有雅哈。","notes":[]},{"n":23,"t":"希伯伦的儿子中有长子耶利雅，次子亚玛利亚，三子雅哈悉，四子耶加面。","notes":["“希伯伦...耶利雅”：原文是“我的儿子中有耶利雅”，有古卷是“耶利雅的儿子”；参代上23．19。"]},{"n":24,"t":"乌薛的子孙中有米迦；米迦的子孙中有沙密。","notes":[]},{"n":25,"t":"米迦的兄弟是伊示雅；伊示雅的子孙中有撒迦利雅。","notes":[]},{"n":26,"t":"米拉利的儿子是抹利和母示；雅西雅的子孙中有比挪；","notes":[]},{"n":27,"t":"米拉利的子孙中有属雅西雅的比挪、朔含、撒刻、伊比利。","notes":[]},{"n":28,"t":"属抹利的有以利亚撒；以利亚撒没有儿子。","notes":[]},{"n":29,"t":"属基士，基士的子孙中有耶拉篾。","notes":[]},{"n":30,"t":"母示的儿子是末力、以得、耶利末。按着宗族，这些都是利未的子孙。","notes":[]},{"n":31,"t":"他们在大卫王和撒督，以及亚希米勒与祭司和利未人的族长面前也抽签，正如他们弟兄亚伦的子孙一样。各族的族长与最年轻的兄弟都一样。","notes":[]}]},"25":{"heading":"圣殿中的圣乐人员","verses":[{"n":1,"t":"大卫和事奉团队的众领袖分派亚萨、希幔，以及耶杜顿的子孙唱歌，以弹琴、鼓瑟、敲钹伴奏。他们供职的人数如下：","notes":["“唱歌”：原文是“说预言”；下同。"]},{"n":2,"t":"亚萨的儿子撒刻、约瑟、尼探雅、亚萨利拉，亚萨的儿子都在亚萨的指导下，遵王的指示唱歌。","notes":[]},{"n":3,"t":"属耶杜顿，耶杜顿的儿子基大利、西利、耶筛亚、示每、哈沙比雅、玛他提雅共六人，都在他们父亲耶杜顿的指导下唱歌，以弹琴伴奏，称谢，颂赞耶和华。","notes":["“示每”是根据一些古卷和七十士译本的一些抄本；原文没有。"]},{"n":4,"t":"属希幔，希幔的儿子是布基雅、玛探雅、乌薛、细布业、耶利末、哈拿尼雅、哈拿尼、以利亚他、基大利提、罗幔提．以谢、约施比加沙、玛罗提、何提、玛哈秀。","notes":[]},{"n":5,"t":"这些都是希幔的儿子；希幔奉神之命作王的先见，吹角颂赞。神赐给希幔十四个儿子，三个女儿，","notes":[]},{"n":6,"t":"他们都在父亲的指导下，在耶和华的殿唱歌，以敲钹、弹琴、鼓瑟伴奏，遵从王的指示，在神的殿里事奉。亚萨、耶杜顿、希幔，","notes":[]},{"n":7,"t":"他们和他们的弟兄学习颂赞耶和华，精通者的数目共有二百八十八人。","notes":[]},{"n":8,"t":"这些人无论大小，为师的、为徒的，都一同抽签分了班次。","notes":[]},{"n":9,"t":"抽签的时候，第一签抽到的是亚萨的儿子约瑟。第二是基大利；他和他兄弟，以及儿子共十二人。","notes":[]},{"n":10,"t":"第三是撒刻，他儿子和他兄弟共十二人。","notes":[]},{"n":11,"t":"第四是伊洗利，他儿子和他兄弟共十二人。","notes":[]},{"n":12,"t":"第五是尼探雅，他儿子和他兄弟共十二人。","notes":[]},{"n":13,"t":"第六是布基雅，他儿子和他兄弟共十二人。","notes":[]},{"n":14,"t":"第七是耶萨利拉，他儿子和他兄弟共十二人。","notes":[]},{"n":15,"t":"第八是耶筛亚，他儿子和他兄弟共十二人。","notes":[]},{"n":16,"t":"第九是玛探雅，他儿子和他兄弟共十二人。","notes":[]},{"n":17,"t":"第十是示每，他儿子和他兄弟共十二人。","notes":[]},{"n":18,"t":"第十一是亚萨烈，他儿子和他兄弟共十二人。","notes":[]},{"n":19,"t":"第十二是哈沙比雅，他儿子和他兄弟共十二人。","notes":[]},{"n":20,"t":"第十三是书巴业，他儿子和他兄弟共十二人。","notes":[]},{"n":21,"t":"第十四是玛他提雅，他儿子和他兄弟共十二人。","notes":[]},{"n":22,"t":"第十五是耶利末，他儿子和他兄弟共十二人。","notes":[]},{"n":23,"t":"第十六是哈拿尼雅，他儿子和他兄弟共十二人。","notes":[]},{"n":24,"t":"第十七是约施比加沙，他儿子和他兄弟共十二人。","notes":[]},{"n":25,"t":"第十八是哈拿尼，他儿子和他兄弟共十二人。","notes":[]},{"n":26,"t":"第十九是玛罗提，他儿子和他兄弟共十二人。","notes":[]},{"n":27,"t":"第二十是以利亚他，他儿子和他兄弟共十二人。","notes":[]},{"n":28,"t":"第二十一是何提，他儿子和他兄弟共十二人。","notes":[]},{"n":29,"t":"第二十二是基大利提，他儿子和他兄弟共十二人。","notes":[]},{"n":30,"t":"第二十三是玛哈秀，他儿子和他兄弟共十二人。","notes":[]},{"n":31,"t":"第二十四是罗幔提．以谢，他儿子和他兄弟共十二人。","notes":[]}]},"26":{"heading":"圣殿的守卫","verses":[{"n":1,"t":"门口守卫的班次如下：可拉族以比雅撒的子孙中，有可利的儿子米施利米雅。","notes":["“以比雅撒”是根据七十士译本，原文是“亚萨”；参代上9．19。"]},{"n":2,"t":"米施利米雅的长子是撒迦利亚，次子是耶叠，三子是西巴第雅，四子是耶提聂，","notes":[]},{"n":3,"t":"五子是以拦，六子是约哈难，七子是以利约乃。","notes":[]},{"n":4,"t":"俄别．以东的长子是示玛雅，次子是约萨拔，三子是约亚，四子是沙甲，五子是拿坦业，","notes":[]},{"n":5,"t":"六子是亚米利，七子是以萨迦，八子是毗乌利太，因为神赐福给俄别．以东。","notes":[]},{"n":6,"t":"他的儿子示玛雅生了几个儿子，都是大能的勇士，管理父亲的家。","notes":[]},{"n":7,"t":"示玛雅的儿子是俄得尼、利法益、俄备得、以利萨巴。以利萨巴的兄弟以利户和西玛迦是能人。","notes":[]},{"n":8,"t":"这些都是俄别．以东的子孙，他们和他们的儿子，以及兄弟，都是善于办事的能人。属俄别．以东的共六十二人。","notes":[]},{"n":9,"t":"米施利米雅的儿子和兄弟都是能人，共十八人。","notes":[]},{"n":10,"t":"米拉利子孙中的何萨有几个儿子：为首的是申利；他原不是长子，是他父亲立他为首的，","notes":[]},{"n":11,"t":"次子是希勒家，三子是底巴利雅，四子是撒迦利亚。何萨的儿子和兄弟共十三人。","notes":[]},{"n":12,"t":"这些是门口守卫的班次，各随他们的班长，与他们的兄弟一同在耶和华殿里按班供职。","notes":[]},{"n":13,"t":"他们无论大小，都按着父系抽签，分守各门。","notes":[]},{"n":14,"t":"抽到东门的是示利米雅；他的儿子撒迦利亚是精明的谋士，抽到北门。","notes":[]},{"n":15,"t":"俄别．以东守南门，他的儿子守仓库。","notes":[]},{"n":16,"t":"书聘与何萨守西门，在靠近沙利基门、通往上去的街道上，守卫与守卫相对。","notes":[]},{"n":17,"t":"东门有六个利未人，北门每日有四人，南门每日有四人，库房有两人轮流替换。","notes":["“东门有六个利未人”：七十士译本是“东门每日有六人”。"]},{"n":18,"t":"至于走廊，在西面街道上有四人，在走廊上有两人。","notes":[]},{"n":19,"t":"以上是可拉子孙和米拉利子孙门口守卫的班次。","notes":[]},{"n":20,"t":"利未人中有亚希雅管理神殿的库房和圣物的库房。","notes":["“亚希雅”：七十士译本是“他们的弟兄”。"],"heads":["其他职务"]},{"n":21,"t":"拉但子孙中，革顺族属拉但、作族长的是革顺族属拉但的耶希伊利。","notes":[]},{"n":22,"t":"耶希伊利的儿子西坦和他兄弟约珥管理耶和华殿的库房。","notes":[]},{"n":23,"t":"暗兰人、以斯哈人、希伯伦人、乌薛人也有职务。","notes":[]},{"n":24,"t":"摩西的孙子，革舜的儿子细布业管理库房。","notes":[]},{"n":25,"t":"还有他的弟兄：以利以谢，以利以谢的儿子利哈比雅，利哈比雅的儿子耶筛亚，耶筛亚的儿子约兰，约兰的儿子细基利，细基利的儿子示罗密。","notes":[]},{"n":26,"t":"这示罗密和他的兄弟管理一切库房的圣物，就是大卫王和众族长、千夫长、百夫长，以及军官所分别为圣之物。","notes":[]},{"n":27,"t":"他们把打仗时夺取的一些财物分别为圣，用来修造耶和华的殿。","notes":[]},{"n":28,"t":"凡撒母耳先见、基士的儿子扫罗、尼珥的儿子押尼珥、洗鲁雅的儿子约押分别为圣的，一切分别为圣之物都归示罗密和他的兄弟掌管。","notes":[]},{"n":29,"t":"以斯哈人有基拿尼雅和他众儿子作官长和审判官，管理以色列对外的事务。","notes":[],"heads":["其余利未人的职务"]},{"n":30,"t":"希伯伦人有哈沙比雅和他弟兄一千七百人，都是能人，在约旦河西监督以色列人，办理耶和华的一切工作和王的事务。","notes":[]},{"n":31,"t":"希伯伦人中有耶利雅作族长。大卫作王第四十年在各族各家从事寻访，在基列的雅谢，从这族中发现大能的勇士。","notes":[]},{"n":32,"t":"耶利雅的弟兄有二千七百人，都是能人，又是族长；大卫王派他们在吕便人、迦得人、玛拿西半支派中管理神和王的一切事务。","notes":[]}]},"27":{"heading":"军官的名单","verses":[{"n":1,"t":"以色列人的族长、千夫长、百夫长和官长都分配班次，每班二万四千人，整年按月轮流出入，按班次服事王。","notes":[]},{"n":2,"t":"正月第一班的班长是撒巴第业的儿子雅朔班；他班内有二万四千人。","notes":[]},{"n":3,"t":"他是法勒斯的后裔，统管正月军队所有的官长。","notes":[]},{"n":4,"t":"二月的班长是亚何亚人朵代，他的班有总长密基罗；他班内有二万四千人。","notes":[]},{"n":5,"t":"三月第三班的班长是耶何耶大祭司长的儿子比拿雅；他班内有二万四千人。","notes":[]},{"n":6,"t":"这比拿雅是那三十人中的勇士，管理那三十人；他班内又有他儿子暗米萨拔。","notes":["“他班内又有他儿子暗米萨拔”：七十士译本和其他古译本是“他儿子暗米萨拔管理他的班”。"]},{"n":7,"t":"四月第四班的班长是约押的兄弟亚撒黑。接续他的是他儿子西巴第雅；他班内有二万四千人。","notes":[]},{"n":8,"t":"五月第五班的班长是伊斯拉人珊合；他班内有二万四千人。","notes":[]},{"n":9,"t":"六月第六班的班长是提哥亚人益吉的儿子以拉；他班内有二万四千人。","notes":[]},{"n":10,"t":"七月第七班的班长是以法莲族比伦人希利斯；他班内有二万四千人。","notes":[]},{"n":11,"t":"八月第八班的班长是谢拉族户沙人西比该；他班内有二万四千人。","notes":[]},{"n":12,"t":"九月第九班的班长是便雅悯族亚拿突人亚比以谢；他班内有二万四千人。","notes":[]},{"n":13,"t":"十月第十班的班长是谢拉族尼陀法人玛哈莱；他班内有二万四千人。","notes":[]},{"n":14,"t":"十一月第十一班的班长是以法莲族比拉顿人比拿雅；他班内有二万四千人。","notes":[]},{"n":15,"t":"十二月第十二班的班长是俄陀聂族尼陀法人黑玳；他班内有二万四千人。","notes":[]},{"n":16,"t":"管理以色列众支派的如下：管吕便人的是细基利的儿子以利以谢；管西缅人的是玛迦的儿子示法提雅；","notes":[],"heads":["以色列各支派的行政长官"]},{"n":17,"t":"管利未的是基摩利的儿子哈沙比雅；管亚伦子孙的是撒督；","notes":[]},{"n":18,"t":"管犹大的是大卫的一个哥哥以利户；管以萨迦的是米迦勒的儿子暗利；","notes":[]},{"n":19,"t":"管西布伦的是俄巴第雅的儿子伊施玛雅；管拿弗他利的是亚斯列的儿子耶利摩；","notes":[]},{"n":20,"t":"管以法莲的是阿撒细雅的儿子何细亚；管玛拿西半支派的是毗大雅的儿子约珥；","notes":[]},{"n":21,"t":"管基列地玛拿西半支派的是撒迦利亚的儿子易多；管便雅悯的是押尼珥的儿子雅西业；","notes":[]},{"n":22,"t":"管但的是耶罗罕的儿子亚萨列。以上是以色列众支派的领袖。","notes":[]},{"n":23,"t":"以色列人二十岁以下的，大卫没有记其数目；因耶和华曾应许，必加增以色列人如天上的星那样多。","notes":[]},{"n":24,"t":"洗鲁雅的儿子约押开始数点，却还没有数完。为了这事，烈怒临到以色列，数点的数目也没有写在《大卫王记》上。","notes":[]},{"n":25,"t":"管理王的库房的是亚叠的儿子押斯马威。管理田野、城镇、村庄、堡垒之仓库的是乌西雅的儿子约拿单。","notes":[],"heads":["管理王产的官员"]},{"n":26,"t":"管理耕田种地的是基绿的儿子以斯利。","notes":[]},{"n":27,"t":"管理葡萄园的是拉玛人示每。管理葡萄园酒窖的是实弗米人撒巴底。","notes":[]},{"n":28,"t":"管理谢非拉橄榄树和桑树的是基第利人巴勒．哈南。管理油库的是约阿施。","notes":["“谢非拉”是音译，意思是“低地”。"]},{"n":29,"t":"管理沙仑牧放牛群的是沙仑人施提莱。管理山谷牧养牛群的是亚第莱的儿子沙法。","notes":[]},{"n":30,"t":"管理骆驼群的是以实玛利人阿比勒。管理驴群的是米仑人耶希底亚。管理羊群的是夏甲人雅悉。","notes":[]},{"n":31,"t":"这些都是为大卫王管理产业的领袖。","notes":[]},{"n":32,"t":"大卫的叔父约拿单作谋士；这人有智慧，又作书记。哈摩尼的儿子耶歇陪伴王的众儿子。","notes":[],"heads":["大卫的谋士"]},{"n":33,"t":"亚希多弗作王的谋士。亚基人户筛作王的顾问。","notes":[]},{"n":34,"t":"亚希多弗之后，有比拿雅的儿子耶何耶大，以及亚比亚他接续他。约押作王的元帅。","notes":[]}]},"28":{"heading":"大卫对建殿的指示","verses":[{"n":1,"t":"大卫召集以色列所有的领袖，各支派的领袖、轮班服事王的官长、千夫长、百夫长、掌管王和王子一切产业牲畜的、宫廷官员、勇士，和所有大能的勇士，都到耶路撒冷来。","notes":[]},{"n":2,"t":"大卫王站起来，说：“我的弟兄，我的百姓啊，请听我说！我心里本想建造殿宇，安放耶和华的约柜，作为我们神的脚凳，并且我已经预备了建造的材料。","notes":[]},{"n":3,"t":"只是神对我说：‘你不可为我的名建造殿宇，因你是战士，流了人的血。’","notes":[]},{"n":4,"t":"然而，耶和华－以色列的神在我父的全家拣选我作以色列的王，直到永远。因他拣选犹大为领袖，在犹大家中拣选我父家，在我父的众儿子里喜悦我，立我作全以色列的王。","notes":[]},{"n":5,"t":"耶和华赐我许多儿子，在我儿子中拣选我儿子所罗门坐耶和华国度的王位，治理以色列。","notes":[]},{"n":6,"t":"耶和华对我说：‘你儿子所罗门必建造我的殿和院宇，因为我拣选他作我的子，我也必作他的父。","notes":[]},{"n":7,"t":"他若恒久遵行我的诫命典章如今日一样，我就必坚定他的国，直到永远。’","notes":[]},{"n":8,"t":"现今在以色列众人眼前，在耶和华的会中，在我们神的垂听下，你们务要遵行并寻求耶和华－你们神的一切诫命，如此你们就可以承受这美地，并留给你们的子孙，永远为业。","notes":[]},{"n":9,"t":"“我儿所罗门哪，你当认识耶和华－你父的神，全心乐意地事奉他，因为耶和华鉴察众人的心，知道一切心思意念。你若寻求他，他必使你寻见；你若离弃他，他必永远丢弃你。","notes":[]},{"n":10,"t":"现在你当谨慎，因耶和华拣选你建造殿宇作为圣所。你当刚强去做。”","notes":[]},{"n":11,"t":"大卫指示他儿子所罗门有关殿的走廊、屋子、库房、楼房、内殿和柜盖之处的样式，","notes":["“柜盖”：原意“盖住”，指“盖住罪”，后来也称为“施恩座”。"]},{"n":12,"t":"被灵感动所得的一切样式：耶和华殿的院子、周围一切的房屋、神殿的库房和圣物库房；","notes":[]},{"n":13,"t":"祭司和利未人的班次，耶和华殿里各样事奉的工作，耶和华殿里一切事奉用的器皿，","notes":[]},{"n":14,"t":"以及各样事奉所用金器的重量，和各样事奉所用银器的重量，","notes":[]},{"n":15,"t":"金灯台和金灯的重量，按每一个灯台和灯的重量；银灯台和银灯的重量，按每一个灯台和灯的重量，都按照每一个灯台的用途；","notes":[]},{"n":16,"t":"每张供饼桌子的金子重量，和银桌子的银子重量，","notes":[]},{"n":17,"t":"纯金的肉叉子、盘子，和壶的重量，金碗，按每个金碗的重量，和银碗，按每个银碗的重量，","notes":[]},{"n":18,"t":"纯金香坛的重量，金基路伯座车的样式，基路伯张开翅膀，遮盖耶和华的约柜。","notes":[]},{"n":19,"t":"大卫说：“这一切，所有工作的样式，是耶和华用手写的文件使我明白的。”","notes":[]},{"n":20,"t":"大卫又对他儿子所罗门说：“你当刚强壮胆去做！不要惧怕，也不要惊惶，因为耶和华神，我的神与你同在。他必不撇下你，也不丢弃你，直到耶和华殿的工作都完毕。","notes":[]},{"n":21,"t":"看哪，有祭司和利未人的班次，为要办理神殿各样的事务，又有擅长做各样事务的人，乐意在各样工作上帮助你，并且领袖和众百姓也都听从你的一切命令。”","notes":[]}]},"29":{"heading":"为建殿而献的礼物","verses":[{"n":1,"t":"大卫王对全会众说：“我儿子所罗门是神特选的，还年幼脆弱，但这工程浩大，因这殿不是为人，而是为耶和华神建造的。","notes":[]},{"n":2,"t":"我为我神的殿已经尽力，预备金子做金器，银子做银器，铜做铜器，铁做铁器，木做木器，还有红玛瑙、可镶嵌的宝石、彩石、各样的宝石和许多大理石。","notes":[]},{"n":3,"t":"此外，因我爱慕我神的殿，在预备建造圣殿的一切材料之外，又将我自己积蓄的金银献给我神的殿，","notes":[]},{"n":4,"t":"就是三千他连得俄斐金子、七千他连得纯银，用来贴殿的墙；","notes":[]},{"n":5,"t":"金子做金器，银子做银器，并藉工匠的手做一切的工。今日有谁愿意将自己献给耶和华呢？”","notes":[]},{"n":6,"t":"于是，众族长和以色列各支派的领袖、千夫长、百夫长，以及监管王工作的官长，都乐意奉献。","notes":[]},{"n":7,"t":"他们为神殿的工程献上五千他连得又一万达利克金子，一万他连得银子，一万八千他连得铜，十万他连得铁。","notes":["“达利克”：古波斯金币；参“度量衡表”。"]},{"n":8,"t":"凡有宝石的都送入耶和华殿的库房，由革顺人耶歇的手管理。","notes":[]},{"n":9,"t":"因这些人全心乐意献给耶和华，百姓就欢喜，大卫王也大大欢喜。","notes":[]},{"n":10,"t":"大卫在全会众眼前称颂耶和华；大卫说：“耶和华－以色列的神，我们的父，你是应当称颂的，直到永永远远！","notes":[],"heads":["大卫称颂耶和华"]},{"n":11,"t":"耶和华啊，尊大、能力、荣耀、胜利、威严都是你的；天上地下的一切都是你的；耶和华啊，国度是你的，并且你为至高，为万有之首。","notes":[]},{"n":12,"t":"丰富尊荣都从你而来，你也治理万物。在你手里有大能大力，你的手使人尊大强盛。","notes":[]},{"n":13,"t":"我们的神啊，现在我们称谢你，赞美你荣耀之名！","notes":[]},{"n":14,"t":"“我算什么，我的百姓算什么，竟然能够如此乐意奉献？因为万物都从你而来，我们把从你的手得来的献给你。","notes":[]},{"n":15,"t":"我们在你面前是客旅，是寄居的，与我们的列祖一样。我们在世的日子如影子，没有盼望。","notes":[]},{"n":16,"t":"耶和华－我们的神啊，我们预备这许多材料，要为你的圣名建造殿宇，都是从你的手而来，都是属你的。","notes":[]},{"n":17,"t":"我的神啊，我知道你察验人心，喜悦正直；我以正直的心乐意献上这一切。现在我欢喜见你的百姓在此乐意奉献给你。","notes":[]},{"n":18,"t":"耶和华－我们列祖亚伯拉罕、以撒、以色列的神啊，求你使你的百姓心中常存这样的心思意念，坚定他们的心归向你，","notes":[]},{"n":19,"t":"又求你赐我儿子所罗门全心遵守你的命令、法度、律例，成就这一切的事，用我所预备的建造殿宇。”","notes":[]},{"n":20,"t":"大卫对全会众说：“你们应当称颂耶和华－你们的神。”于是全会众称颂耶和华－他们列祖的神，低头向耶和华和王下拜。","notes":[]},{"n":21,"t":"次日，他们向耶和华献平安祭和燔祭，献一千头公牛、一千只公绵羊、一千只羔羊，以及同献的浇酒祭，并为以色列众人献许多的祭。","notes":[]},{"n":22,"t":"那日，他们在耶和华面前吃喝，大大欢乐。他们再次立大卫的儿子所罗门作王，膏他归耶和华作君王，又膏撒督作祭司。","notes":[]},{"n":23,"t":"于是所罗门坐在耶和华所赐的王位上，接续他父亲大卫作王；他万事亨通，全以色列都听从他。","notes":[]},{"n":24,"t":"众领袖和勇士，以及大卫王的众儿子，都顺服所罗门王。","notes":[]},{"n":25,"t":"耶和华使所罗门在以色列众人眼前非常尊大，赐他君王的威严，胜过他以前任何一位以色列王。","notes":[]},{"n":26,"t":"耶西的儿子大卫作全以色列的王。","notes":[],"heads":["大卫政绩简述"]},{"n":27,"t":"他作以色列王的时期共四十年：在希伯仑作王七年，在耶路撒冷作王三十三年。","notes":[]},{"n":28,"t":"他死的时候年纪老迈，日子满足，享尽荣华富贵。他的儿子所罗门接续他作王。","notes":[]},{"n":29,"t":"大卫王自始至终的事迹，看哪，都写在撒母耳先见的书上、拿单先知的书上和迦得先见的书上，","notes":[]},{"n":30,"t":"包括他治国的一切和他英勇的事迹，以及他和以色列与世上列国所经历的事。","notes":[]}]}},"2CH":{"1":{"heading":"所罗门祈求智慧","verses":[{"n":1,"t":"大卫的儿子所罗门巩固他的国度；耶和华－他的神与他同在，使他极其尊大。","notes":[]},{"n":2,"t":"所罗门吩咐全以色列，就是千夫长、百夫长、审判官、全以色列的众领袖和族长前来。","notes":[]},{"n":3,"t":"所罗门率领全会众往基遍的丘坛去，因那里有神的会幕，就是耶和华的仆人摩西在旷野所造的。","notes":[]},{"n":4,"t":"只是神的约柜，大卫已经从基列．耶琳接到他所预备的地方，因他曾在耶路撒冷为约柜支搭了帐幕，","notes":[]},{"n":5,"t":"把户珥的孙子，乌利的儿子比撒列所造的铜坛摆在基遍耶和华的会幕前。所罗门和会众求告耶和华。","notes":["“把户珥...摆在基遍”：有古卷、七十士译本和其他古译本是“户珥的孙子，乌利亚的儿子比撒列所造的铜坛在基遍那里”。"]},{"n":6,"t":"所罗门上到耶和华面前会幕的铜坛那里，在坛上献一千祭牲为燔祭。","notes":[]},{"n":7,"t":"当夜，神向所罗门显现，对他说：“你愿我赐你什么，你可以求。”","notes":[]},{"n":8,"t":"所罗门对神说：“你曾向我父亲大卫大施慈爱，使我接续他作王。","notes":[]},{"n":9,"t":"耶和华神啊，现在求你实现向我父亲大卫所应许的话；因你立我作这百姓的王，他们如同地上的尘沙那样多。","notes":[]},{"n":10,"t":"现在，求你赐我智慧聪明，好在这百姓面前出入；不然，谁能判断你这么多的百姓呢？”","notes":[]},{"n":11,"t":"神对所罗门说：“你有这心意，不求资财、丰富、尊荣，也不求灭绝恨你之人的性命，又不求长寿；我既立你作我百姓的王，你只求智慧聪明，好审判我的百姓，","notes":[]},{"n":12,"t":"我必赐你智慧聪明，也必赐你资财、丰富、尊荣，在你以前的列王未曾有过，在你以后也不会再有。”","notes":[]},{"n":13,"t":"于是，所罗门从基遍丘坛会幕前回到耶路撒冷，治理以色列。","notes":[]},{"n":14,"t":"所罗门聚集战车骑兵；他有一千四百辆战车，一万二千名骑兵，安置在屯车城，在耶路撒冷的王那里。","notes":[],"heads":["所罗门的兵力和财力"]},{"n":15,"t":"王在耶路撒冷使金银多如石头，香柏木多如谢非拉的桑树。","notes":["“谢非拉”是音译，意思是“低地”；本卷书下同。"]},{"n":16,"t":"所罗门的马是从埃及和科威运来的，是王的商人按着定价从科威买来的。","notes":["“埃及”可能不是南方的埃及，而是美索不达米亚北方的一国；下同。","“科威”可能是“基利家”。"]},{"n":17,"t":"他们从埃及进口战车，每辆六百舍客勒银子，马每匹一百五十舍客勒；赫人众王和亚兰诸王的战车和马，也是经由他们的手出口的。","notes":[]}]},"2":{"heading":"所罗门准备建殿","verses":[{"n":1,"t":"所罗门吩咐要为耶和华的名建造殿宇，又为自己的王国建造宫殿。","notes":[]},{"n":2,"t":"所罗门征召七万名扛抬的，八万个在山上凿石头的人，三千六百个监工。","notes":[]},{"n":3,"t":"所罗门派人去见推罗王希兰，说：“你曾运香柏木给我父亲大卫建造宫殿居住，请你也这样待我。","notes":["“希兰”：原文是“户兰”；下同。"]},{"n":4,"t":"看哪，我要为耶和华－我神的名建造殿宇，分别为圣献给他，在他面前烧芬芳的香，经常献供饼，每早晚、安息日、初一，以及耶和华－我们神所定的节期献燔祭。这是以色列人永远的定例。","notes":[]},{"n":5,"t":"我所要建造的殿宇宏大，因为我们的神至大，超乎众神。","notes":[]},{"n":6,"t":"天和天上的天，尚且不足他居住，谁能为他建造殿宇呢？我是谁，能为他建造殿宇吗？不过在他面前烧香而已！","notes":[]},{"n":7,"t":"现在请你派一个巧匠来，就是善用金、银、铜、铁，和紫色、朱红色、蓝色线做工，并精于雕刻之工的巧匠，与跟我一起在犹大和耶路撒冷、我父亲大卫所预备的巧匠一同做工；","notes":[]},{"n":8,"t":"又请你从黎巴嫩运香柏木、松木、檀香木到我这里来，因我知道你的仆人擅长砍伐黎巴嫩的树木。看哪，我的仆人必帮助你的仆人，","notes":[]},{"n":9,"t":"好为我预备许多的木料，因我要建造的殿宇高大出奇。","notes":[]},{"n":10,"t":"看哪，我必给你仆人，就是砍伐树木的伐木工，二万歌珥压碎的小麦，二万歌珥大麦，二万罢特酒，二万罢特油。”","notes":["“二万歌珥压碎的小麦”：七十士译本是“食物：二万歌珥小麦”。"]},{"n":11,"t":"推罗王希兰写信回答所罗门说：“耶和华因为爱他的百姓，所以立你作他们的王。”","notes":[]},{"n":12,"t":"又说：“创造天和地的耶和华－以色列的神是应当称颂的！他赐给大卫王一个有智慧的儿子，使他有见识，有聪明，可以为耶和华建造殿宇，又为自己的王国建造宫殿。","notes":[]},{"n":13,"t":"“现在我派一个精巧聪明的人去，他是我的师父户兰，","notes":[]},{"n":14,"t":"是但支派一个妇人的儿子，父亲是推罗人。他善用金、银、铜、铁、石、木，和紫色、蓝色、细麻和朱红色线制造各物，并精于雕刻，又能设计各样交给他做的图案。我派这人与你的巧匠和你父亲－我主大卫的巧匠一同做工。","notes":[]},{"n":15,"t":"我主所说的小麦、大麦、酒、油，请运来给众仆人。","notes":[]},{"n":16,"t":"我们必照你所需用的，从黎巴嫩砍伐树木，扎成筏子，浮海运到约帕；你可以从那里运到耶路撒冷。”","notes":[]},{"n":17,"t":"所罗门仿照他父亲大卫数点所有在以色列地寄居的外邦人，共有十五万三千六百名。","notes":[]},{"n":18,"t":"他叫其中的七万人作扛抬，八万人在山上凿石头，三千六百人监督百姓工作。","notes":[]}]},"3":{"heading":"圣殿工程动工","verses":[{"n":1,"t":"所罗门在耶路撒冷开工建造耶和华的殿，就在耶和华向他父亲大卫显现的摩利亚山上，耶布斯人阿珥楠的禾场，大卫指定的地方。","notes":[]},{"n":2,"t":"所罗门作王第四年二月初二开工建造。","notes":["有古卷、七十士译本和其他古译本没有“初二”；参王上6．1。"]},{"n":3,"t":"所罗门所建筑的神殿的根基是这样：长六十肘，宽二十肘，都按着古时的尺寸。","notes":[]},{"n":4,"t":"前面的走廊长二十肘，与殿的宽度一样，高一百二十肘；里面贴上纯金。","notes":["“前面的”：七十士译本是“殿前的”。"]},{"n":5,"t":"大殿的墙都用松木板遮蔽，又贴上纯金，上面刻着棕树和链子。","notes":[]},{"n":6,"t":"他用宝石装饰这殿，使殿华美；金子都是巴瓦音的金子。","notes":[]},{"n":7,"t":"他用金子贴殿和殿的栋梁、门槛、墙壁、门扇；墙上刻着基路伯。","notes":[]},{"n":8,"t":"他建造至圣所，长二十肘，与殿的宽度一样，宽二十肘，都贴上纯金，共用了六百他连得金子。","notes":[]},{"n":9,"t":"金的钉子重五十舍客勒。楼房都贴上金子。","notes":[]},{"n":10,"t":"他又在至圣所用雕刻的手艺造两个基路伯，包上金子。","notes":[]},{"n":11,"t":"两个基路伯的翅膀共长二十肘。这基路伯的一个翅膀长五肘，挨着殿这边的墙；另一个翅膀也长五肘，与那基路伯翅膀相接。","notes":[]},{"n":12,"t":"那基路伯的一个翅膀长五肘，挨着殿那边的墙；另一个翅膀也长五肘，与这基路伯的翅膀相接。","notes":[]},{"n":13,"t":"这两个基路伯张开翅膀，共长二十肘，用脚站立，脸面向殿。","notes":[]},{"n":14,"t":"他又用蓝色、紫色、朱红色线和细麻织幔子，在其上绣基路伯。","notes":[]},{"n":15,"t":"他在殿前造了两根柱子，高三十五肘；柱子上面的柱顶高五肘。","notes":[],"heads":["两根铜柱"]},{"n":16,"t":"他造链子在内殿里，安在柱顶上，又做一百个石榴，安在链子上。","notes":[]},{"n":17,"t":"他把两根柱子立在殿前，一根在右边，一根在左边；右边的起名叫雅斤，左边的起名叫波阿斯。","notes":[]}]},"4":{"heading":"圣殿的设备","verses":[{"n":1,"t":"他造一座铜坛，长二十肘，宽二十肘，高十肘。","notes":[]},{"n":2,"t":"他又铸一个铜海，周围是圆的，直径十肘，高五肘，用绳子量周围是三十肘。","notes":[]},{"n":3,"t":"铜海下面的周围有牛的样式，有十肘，绕着铜海；牛有两行，是造铜海的时候铸上去的。","notes":[]},{"n":4,"t":"铜海安在十二头铜牛上：三头向北，三头向西，三头向南，三头向东。铜海安在牛上，牛尾都向内。","notes":[]},{"n":5,"t":"铜海厚一掌，边如杯边，像百合花，容量是三千罢特。","notes":[]},{"n":6,"t":"他又造十个盆：五个放在右边，五个放在左边，作洗涤之用。献燔祭所用之物都洗在盆内；但铜海是为祭司洗涤用的。","notes":[]},{"n":7,"t":"他照所定的样式造十个金灯台，放在殿里：五个在右边，五个在左边。","notes":[]},{"n":8,"t":"他造十张桌子，放在殿里：五张在右边，五张在左边。他又造一百个金碗。","notes":[]},{"n":9,"t":"他建造祭司院和大院，以及院门，门扇包上铜。","notes":[]},{"n":10,"t":"他把铜海安在殿的右边，就是东南边。","notes":[]},{"n":11,"t":"户兰又造了盆、铲子和盘子。这样，户兰为所罗门王做完了神殿的工：","notes":[]},{"n":12,"t":"两根柱子和柱子顶上两个如碗的柱顶，以及盖着如碗柱顶的两个网子；","notes":[]},{"n":13,"t":"四百个石榴，安在两个网子上，每网两行石榴，盖着柱子上面两个如碗的柱顶。","notes":[]},{"n":14,"t":"他造盆座，又造其上的盆；","notes":[]},{"n":15,"t":"铜海和其下的十二头牛；","notes":[]},{"n":16,"t":"盆、铲子、肉叉。巧匠户兰给所罗门王为耶和华殿造的这一切器皿都是用磨亮的铜，","notes":[]},{"n":17,"t":"是王在约旦平原、疏割和撒利但中间的泥巴地铸成的。","notes":[]},{"n":18,"t":"所罗门造这一切器皿，数量很多，铜的重量无法计算。","notes":[]},{"n":19,"t":"所罗门又为神的殿造了各样的器皿：金坛和献供饼的供桌；","notes":[]},{"n":20,"t":"纯金的灯台和灯盏，可以照定例点在内殿前；","notes":[]},{"n":21,"t":"灯台上的花和灯盏，以及灯剪，都是金的，而且是纯金的；","notes":[]},{"n":22,"t":"纯金的钳子、盘子、勺子、火盆。至于殿门和至圣所的门扇，以及殿的门扇，都是金的。","notes":[]}]},"5":{"heading":"接约柜入殿","verses":[{"n":1,"t":"所罗门王做完了耶和华殿一切的工，就把他父亲大卫分别为圣的金银和一切器皿都带来，放在神殿的库房里。","notes":[]},{"n":2,"t":"于是，所罗门召集以色列的长老、各支派的领袖和以色列人的族长到耶路撒冷，要把耶和华的约柜从大卫城，就是锡安，接上来。","notes":[]},{"n":3,"t":"在七月节期的时候，所有的以色列人都聚集到王那里。","notes":[]},{"n":4,"t":"以色列众长老一来到，利未人就抬起约柜。","notes":[]},{"n":5,"t":"祭司和利未人将约柜请上来，又把会幕和会幕一切的圣器皿都带上来。","notes":[]},{"n":6,"t":"所罗门王和聚集到他那里的以色列全会众都在约柜前献牛羊为祭，多得不可胜数，无法计算。","notes":[]},{"n":7,"t":"祭司将耶和华的约柜请进内殿，就是至圣所，安置在两个基路伯的翅膀底下约柜自己的地方。","notes":[]},{"n":8,"t":"基路伯张开翅膀在约柜上面的地方，从上面遮住约柜和抬柜的杠。","notes":[]},{"n":9,"t":"这杠很长，从内殿前的约柜可以看见杠头，从外面却看不见。这杠直到今日还在那里。","notes":[]},{"n":10,"t":"约柜里没有别的，只有两块石版，就是以色列人出埃及，耶和华与他们立约的时候，摩西在何烈山所放的。","notes":[]},{"n":11,"t":"当时，所有在那里的祭司，不论哪个班次供职的，都使自己分别为圣。祭司从圣所出来的时候，","notes":[],"heads":["神的荣光"]},{"n":12,"t":"所有歌唱的利未人，亚萨、希幔、耶杜顿，和他们的众儿子、众弟兄都穿细麻布衣服，站在祭坛的东边敲钹，鼓瑟，弹琴，和他们一起的还有一百二十个吹号的祭司。","notes":[]},{"n":13,"t":"吹号的、歌唱的都合一齐声，赞美称谢耶和华。他们配合号筒、铙钹和其他乐器，扬声赞美耶和华：“耶和华本为善，他的慈爱永远长存！”那时，耶和华的殿充满了云彩。","notes":[]},{"n":14,"t":"祭司因云彩的缘故不能站立供职，因为耶和华的荣光充满了神的殿。","notes":[]}]},"6":{"heading":"所罗门向百姓讲话","verses":[{"n":1,"t":"那时，所罗门说：“耶和华曾说要住在幽暗之处。","notes":[]},{"n":2,"t":"我为你建了一座雄伟的殿宇，作为你永远居住的地方。”","notes":[]},{"n":3,"t":"王转过脸来为以色列全会众祝福，以色列全会众都站立。","notes":[]},{"n":4,"t":"所罗门说：“耶和华－以色列的神是应当称颂的！因他亲口向我父大卫应许的，也亲手成就了；他曾说：","notes":[]},{"n":5,"t":"‘自从那日我领我百姓出埃及地以来，我未曾在以色列各支派中选择一城，在那里为我的名建造殿宇，也未曾拣选一人作我百姓以色列的君王。","notes":[]},{"n":6,"t":"但我选择耶路撒冷，使我的名留在那里，又拣选大卫治理我的百姓以色列。’","notes":[]},{"n":7,"t":"我父大卫的心意是要为耶和华－以色列神的名建殿。","notes":[]},{"n":8,"t":"耶和华却对我父大卫说：‘你有心为我的名建殿，这心意是好的；","notes":[]},{"n":9,"t":"但你不可建殿，惟有你亲生的儿子才可为我的名建殿。’","notes":[]},{"n":10,"t":"现在耶和华实现了他所应许的话，使我接续我父大卫坐以色列的王位，正如耶和华所说的，我也为耶和华－以色列神的名建造了这殿。","notes":[]},{"n":11,"t":"我将约柜安置在那里，柜内有耶和华的约，就是他与以色列人所立的约。”","notes":[]},{"n":12,"t":"所罗门当着以色列全会众，站在耶和华的坛前，举起手来。","notes":[],"heads":["所罗门的祷告"]},{"n":13,"t":"所罗门曾造一个铜台，长五肘，宽五肘，高三肘，放在院中。他站在台上，当着以色列全会众双膝跪下，向天举手，","notes":[]},{"n":14,"t":"说：“耶和华－以色列的神啊，天上地下没有神明可与你相比！你向那些尽心行在你面前的仆人守约施慈爱，","notes":[]},{"n":15,"t":"这约是你向你仆人大卫守的，是你应许他的。你亲口应许，亲手成就，正如今日一样。","notes":[]},{"n":16,"t":"耶和华－以色列的神啊，你向你仆人我父大卫应许说：‘你的子孙若谨慎自己的行为，遵行我的律法，像你在我面前所行的，就不断有人在我面前坐以色列的王位。’现在求你信守这话。","notes":[]},{"n":17,"t":"耶和华－以色列的神啊，现在求你成就向你仆人大卫所应许的话。","notes":[]},{"n":18,"t":"“神果真与世人同住在地上吗？看哪，天和天上的天尚且不足容纳你，何况我所建的这殿呢？","notes":[]},{"n":19,"t":"惟求耶和华－我的神垂顾仆人的祷告祈求，俯听仆人在你面前的祈祷呼求。","notes":[]},{"n":20,"t":"愿你的眼目昼夜看顾这殿，就是你应许立为你名的居所；求你垂听祷告，你仆人向此处的祷告。","notes":[]},{"n":21,"t":"你仆人和你百姓以色列向此处祈祷的时候，求你从天上你的居所垂听，垂听而赦免。","notes":[]},{"n":22,"t":"“人若得罪邻舍，有人强迫他，要他起誓，他来到这殿，在你的坛前起誓，","notes":[]},{"n":23,"t":"求你从天上垂听、处理，向你的仆人施行审判，定恶人有罪，照他所行的报应在他头上；定义人为义，照他的义赏赐他。","notes":[]},{"n":24,"t":"“你的百姓以色列若得罪你，败在仇敌面前，却又归向你，宣认你的名，在这殿里向你祈求祷告，","notes":[]},{"n":25,"t":"求你从天上垂听，赦免你百姓以色列的罪，使他们归回你赐给他们和他们列祖之地。","notes":[]},{"n":26,"t":"“你的百姓若得罪了你，你使天闭塞不下雨；他们若向此处祷告，宣认你的名，因你的惩罚而离开他们的罪，","notes":[]},{"n":27,"t":"求你在天上垂听，赦免你仆人你百姓以色列的罪，将当行的善道教导他们，并降雨在你的地，就是你赐给你百姓为业之地。","notes":[]},{"n":28,"t":"“这地若有饥荒、瘟疫、焚风、霉烂、蝗虫、蚂蚱，或有仇敌围困这地的城门，无论遭遇什么灾祸疾病，","notes":["“焚风”或译“虫害”。"]},{"n":29,"t":"你的百姓以色列，或众人或一人，自觉灾祸困苦，向这殿举手，无论祈求什么，祷告什么，","notes":[]},{"n":30,"t":"求你从天上你的居所垂听赦免。因为你知道人心，惟有你知道世人的心，求你照各人所行的一切待他们，","notes":[]},{"n":31,"t":"使他们在你赐给我们列祖的土地上一生一世敬畏你，遵行你的道。","notes":[]},{"n":32,"t":"“论到不属你百姓以色列的外邦人，若为你的大名和大能的手，以及伸出来的膀臂，从远方而来，来向这殿祷告，","notes":[]},{"n":33,"t":"求你从天上你的居所垂听，照着外邦人向你所求的一切而行，使地上万民都认识你的名，敬畏你，像你的百姓以色列一样，又使他们知道我所建造的是称为你名下的殿。","notes":[]},{"n":34,"t":"“你的百姓若奉你的派遣出去，无论往何处与仇敌争战，他们若向你所选择的这城和我为你名所建造的殿祷告，","notes":[]},{"n":35,"t":"求你从天上垂听他们的祷告祈求，为他们伸张正义。","notes":[]},{"n":36,"t":"“你的百姓若得罪你，因为没有人不犯罪，你向他们发怒，把他们交在仇敌面前，掳他们的人把他们带到或远或近之地；","notes":[]},{"n":37,"t":"他们若在被掳之地那里回心转意，在被掳之地悔改，向你恳求说：‘我们有罪了，我们悖逆了，我们作恶了’；","notes":[]},{"n":38,"t":"他们若在被掳之地尽心尽性归向你，又向自己的地，就是你赐给他们列祖的地和你所选择的城，以及我为你名所建造的这殿祷告，","notes":[]},{"n":39,"t":"求你从天上你的居所垂听他们的祷告祈求，为他们伸张正义，赦免你的百姓向你犯的罪。","notes":[]},{"n":40,"t":"我的神啊，现在求你睁眼看，侧耳听在此处所献的祷告。","notes":[]},{"n":41,"t":"“耶和华神啊，现在求你兴起，与你有能力的约柜同入安歇之所。耶和华神啊，愿你的祭司披上救恩，愿你的圣民蒙福欢乐。","notes":[]},{"n":42,"t":"耶和华神啊，求你不要厌弃你的受膏者，要记得向你仆人大卫所施的慈爱。”","notes":[]}]},"7":{"heading":"圣殿的奉献礼","verses":[{"n":1,"t":"所罗门祈祷完毕，就有火从天降下来，烧尽燔祭和祭物。耶和华的荣光充满了殿；","notes":[]},{"n":2,"t":"因耶和华的荣光充满了耶和华的殿，所以祭司不能进耶和华的殿。","notes":[]},{"n":3,"t":"那火降下、耶和华的荣光在殿上的时候，以色列众人看见，就在石板地俯伏敬拜，称谢耶和华：“耶和华本为善，他的慈爱永远长存！”","notes":[]},{"n":4,"t":"王和众百姓在耶和华面前献祭。","notes":[]},{"n":5,"t":"所罗门王献二万二千头牛、十二万只羊为祭。这样，王和众百姓为神的殿行了奉献之礼。","notes":[]},{"n":6,"t":"祭司各供其职侍立，利未人拿着耶和华的乐器，就是大卫王所造、为要颂赞耶和华的乐器，因他的慈爱永远长存；他们为大卫的赞美诗奏乐；祭司在众人面前吹号，以色列众人都站立。","notes":[]},{"n":7,"t":"所罗门因他所造的铜坛容不下燔祭、素祭和脂肪，就将耶和华殿前院子的中间分别为圣，在那里献燔祭和平安祭牲的脂肪。","notes":[]},{"n":8,"t":"那时所罗门守节七日，从哈马口直到埃及溪谷的以色列众人都与他同在一起，成了一个极其盛大的会。","notes":[]},{"n":9,"t":"第八日他们举行严肃会，行奉献坛的礼七日，守节七日。","notes":[]},{"n":10,"t":"七月二十三日，王差遣百姓回自己的帐棚去；他们为耶和华向大卫和所罗门，以及他百姓以色列所施的恩惠，心里都欢喜快乐。","notes":[]},{"n":11,"t":"所罗门建完了耶和华的殿和王宫；在耶和华的殿和王宫的工程上，凡他心中所要做的，都顺利做成了。","notes":[],"heads":["神再次向所罗门显现"]},{"n":12,"t":"夜间耶和华向所罗门显现，对他说：“我已听了你的祷告，也选择这地方归我作献祭的殿宇。","notes":[]},{"n":13,"t":"我若使天闭塞不下雨，或使蝗虫吃这地的出产，或降瘟疫在我子民中，","notes":[]},{"n":14,"t":"这称为我名下的子民，若是谦卑自己，祷告，寻求我的面，转离他们的恶行，我必从天上垂听，赦免他们的罪，医治他们的地。","notes":[]},{"n":15,"t":"我必睁眼看，侧耳听在此处所献的祷告。","notes":[]},{"n":16,"t":"现在我已选择这殿，分别为圣，使我的名永在其中；我的眼、我的心也必时常在那里。","notes":[]},{"n":17,"t":"你若行在我面前，效法你父大卫所行的，遵行我一切所吩咐你的，谨守我的律例典章，","notes":[]},{"n":18,"t":"我就必坚固你国度的王位，正如我与你父大卫所立的约，说：‘你的子孙必不断有人治理以色列。’","notes":[]},{"n":19,"t":"“倘若你们转去，离弃我摆在你们面前的律例诫命，去事奉别神，敬拜它们，","notes":[]},{"n":20,"t":"我就必把以色列人从我赐给他们的地上连根拔起，也必从我面前舍弃那为我名所分别为圣的殿，使它在万民中成为笑柄，被人讥诮。","notes":[]},{"n":21,"t":"这殿虽然崇高，将来凡经过的人必惊讶说：‘耶和华为何向这地和这殿如此行呢？’","notes":[]},{"n":22,"t":"人必说：‘因为此地的人离弃领他们祖先出埃及地的耶和华－他们的神，去亲近别神，敬拜事奉它们，所以耶和华使这一切灾祸临到他们。’”","notes":[]}]},"8":{"heading":"所罗门的成就","verses":[{"n":1,"t":"所罗门建造耶和华的殿和王宫，用了二十年才完成。","notes":[]},{"n":2,"t":"所罗门修筑希兰送给他的城镇，使以色列人住在那里。","notes":[]},{"n":3,"t":"所罗门往哈马．琐巴去，攻取了那地方。","notes":[]},{"n":4,"t":"所罗门建造旷野的达莫，建造哈马一切的储货城，","notes":[]},{"n":5,"t":"又建造上伯．和仑、下伯．和仑，成为有墙、门、闩的堡垒城。","notes":[]},{"n":6,"t":"所罗门建造巴拉和一切的储货城、战车城、战马城，以及他所想要建造的，在耶路撒冷、黎巴嫩，和自己所治理全国中的一切建设。","notes":[]},{"n":7,"t":"至于所有剩下的百姓，不属以色列的赫人、亚摩利人、比利洗人、希未人、耶布斯人，","notes":[]},{"n":8,"t":"那些以色列人在当地不能灭尽的人，所罗门征召他们剩下的后代服劳役，直到今日。","notes":[]},{"n":9,"t":"惟有以色列人，所罗门不使他们当奴仆做工，而是作他的战士、军官、战车长、骑兵长。","notes":[]},{"n":10,"t":"这些是所罗门王的监工，共有二百五十名百姓的监工。","notes":[]},{"n":11,"t":"所罗门把法老的女儿迁出大卫城，上到他为她建造的宫里，因所罗门说：“耶和华约柜所到之处都是圣地，所以我的妻子不可住在以色列王大卫的宫里。”","notes":[]},{"n":12,"t":"那时，所罗门在走廊前他所筑的耶和华的坛上，向耶和华献燔祭，","notes":[]},{"n":13,"t":"又遵照摩西的吩咐，在安息日、初一，以及每年在除酵节、七七节、住棚节三个节期，献每日所当献上的祭。","notes":[]},{"n":14,"t":"所罗门照着他父亲大卫所定的条例，分派祭司的班次，担任他们的职务，又分派利未人的任务，负责颂赞，并在祭司面前做每日当做的事，又派门口的守卫按着班次看守各门，因为神人大卫是这样吩咐的。","notes":[]},{"n":15,"t":"王对众祭司和利未人的吩咐，无论是管理库房或任何事务，他们都不违背。","notes":[]},{"n":16,"t":"所罗门所有的工作都准备就绪，从立耶和华殿的根基直到完工的日子。耶和华的殿就完成了。","notes":[]},{"n":17,"t":"那时，所罗门往以东地海岸的以旬．迦别和以禄去。","notes":[]},{"n":18,"t":"希兰派他的臣仆，把船只和熟悉航海的仆人送到所罗门那里。他们同所罗门的仆人到了俄斐，从那里得了四百五十他连得金子，运到所罗门王那里。","notes":[]}]},"9":{"heading":"示巴女王拜访所罗门","verses":[{"n":1,"t":"示巴女王听见所罗门的名声，就来到耶路撒冷，要用难题考问所罗门。她带着很多的随从，有骆驼驮着香料、许多金子和宝石。她来到所罗门那里，向他提出心中所有的问题。","notes":[]},{"n":2,"t":"所罗门回答了她所有的问题，没有一个问题太难，是所罗门不能向她解答的。","notes":[]},{"n":3,"t":"示巴女王看见所罗门的智慧和他所建造的宫殿，","notes":[]},{"n":4,"t":"席上的食物，坐着的群臣，侍立的仆人和他们的服装，司酒长和他们的服装，以及他上耶和华殿的台阶，就诧异得神不守舍。","notes":["“台阶”或译“楼房”；“他上耶和华殿的台阶”：七十士译本和其他古译本是“他在耶和华殿里所献的燔祭”；参王上10．5。"]},{"n":5,"t":"她对王说：“我在本国所听到的话，论到你的事和你的智慧是真的！","notes":[]},{"n":6,"t":"我本来不信那些话，及至我来亲眼看见了，看哪，人所告诉我的，还不及你丰富智慧的一半，超过我所听见的传闻。","notes":[]},{"n":7,"t":"你的人是有福的！你这些常侍立在你面前、听你智慧话的仆人是有福的！","notes":[]},{"n":8,"t":"耶和华－你的神是应当称颂的！他喜爱你，使你坐他的王位，为耶和华－你的神作王；因为你的神爱以色列，要永远坚立它，所以立你作他们的王，使你秉公行义。”","notes":[]},{"n":9,"t":"于是示巴女王把一百二十他连得金子、极多的香料和宝石送给所罗门王；从来没有像示巴女王送给所罗门王那么多的香料。","notes":[]},{"n":10,"t":"希兰的仆人和所罗门的仆人也从俄斐运了金子来，又运了檀香木和宝石来。","notes":[]},{"n":11,"t":"王用檀香木为耶和华的殿和王宫做阶梯，又为歌唱的人做琴瑟；犹大地从来没有见过这样的。","notes":[]},{"n":12,"t":"所罗门王除了回赠示巴女王所带来的，凡她所提出的一切要求，所罗门王都送给她。于是女王和她臣仆转回，到本国去了。","notes":[]},{"n":13,"t":"所罗门每年所得的金子，重六百六十六他连得，","notes":[],"heads":["所罗门的财富"]},{"n":14,"t":"另外还有从商人和贸易所收到的，以及阿拉伯诸王和各地的省长进贡给所罗门的金银。","notes":[]},{"n":15,"t":"所罗门王用锤出来的金子打成二百面盾牌，每面盾牌用六百舍客勒锤出来的金子；","notes":[]},{"n":16,"t":"又用锤出来的金子打成三百面小盾牌，每面小盾牌用三百舍客勒金子。王把它们放在黎巴嫩林宫里。","notes":[]},{"n":17,"t":"王又制造一个大的象牙宝座，包上纯金。","notes":[]},{"n":18,"t":"宝座有六层台阶，又有金脚凳，与宝座相连。座位之处两旁有扶手，靠近扶手有两只狮子站立。","notes":[]},{"n":19,"t":"六层台阶上有十二只狮子站立，分站左边和右边；任何国度都没有这样做的。","notes":[]},{"n":20,"t":"所罗门王一切的饮器都是金的，黎巴嫩林宫里所有的器皿都是纯金的。在所罗门的日子，银子算不了什么。","notes":[]},{"n":21,"t":"因王的船只与希兰的仆人一同往他施去，他施船只每三年一次把金、银、象牙、猿猴、孔雀运回来。","notes":["“孔雀”或译“狒狒”。"]},{"n":22,"t":"所罗门王的财宝与智慧胜过地上的众王。","notes":[]},{"n":23,"t":"地上的众王都求见所罗门的面，要听神放在他心里的智慧。","notes":[]},{"n":24,"t":"他们各带贡物，就是银器、金器、衣服、兵器、香料、马、骡子，每年都有一定的数量。","notes":[]},{"n":25,"t":"所罗门拥有给战车和马用的四千个棚子，还有一万二千名骑兵，安置在屯车城，在耶路撒冷的王那里。","notes":[]},{"n":26,"t":"所罗门统管诸王，从大河到非利士人的地，直到埃及的边界。","notes":[]},{"n":27,"t":"王在耶路撒冷使银子多如石头，香柏木多如谢非拉的桑树。","notes":[]},{"n":28,"t":"有人从埃及和各国为所罗门把马匹运来。","notes":["“埃及”可能不是南方的埃及，而是美索不达米亚北方的一国。"]},{"n":29,"t":"所罗门其余的事，自始至终，不都写在拿单先知的书上和示罗人亚希雅的《预言书》上，以及易多先见论尼八儿子耶罗波安的《默示书》上吗？","notes":[],"heads":["所罗门去世"]},{"n":30,"t":"所罗门在耶路撒冷作全以色列的王四十年。","notes":[]},{"n":31,"t":"所罗门与他祖先同睡，葬在他父亲大卫的城里，他儿子罗波安接续他作王。","notes":[]}]},"10":{"heading":"北方支派的反叛","verses":[{"n":1,"t":"罗波安往示剑去，因以色列众人都到了示剑，要立他作王。","notes":[]},{"n":2,"t":"尼八的儿子耶罗波安先前躲避所罗门王，逃往埃及，住在那里；他听见这事，就从埃及回来。","notes":[]},{"n":3,"t":"以色列人派人去请他来。耶罗波安就和以色列众人来，与罗波安谈话，说：","notes":[]},{"n":4,"t":"“你父亲使我们负重轭，现在求你减轻你父亲所加给我们的苦工和重轭，我们就服事你。”","notes":[]},{"n":5,"t":"罗波安对他们说：“过三天再来见我吧！”百姓就走了。","notes":[]},{"n":6,"t":"罗波安的父亲所罗门在世的时候，有侍立在他面前的长者，罗波安王和他们商议，说：“你们出个主意，好把话带回给这百姓。”","notes":[]},{"n":7,"t":"他们对他说：“王若恩待这百姓，使他们喜悦，跟他们说好话，他们就永远作王的仆人了。”","notes":[]},{"n":8,"t":"王不采纳长者给他出的主意，却和那些与他一同长大、在他面前侍立的年轻人商议。","notes":[]},{"n":9,"t":"他对他们说：“这百姓对我说：‘你父亲使我们负重轭，求你减轻一些。’你们出个什么主意，我们好把话带回给他们。”","notes":[]},{"n":10,"t":"那些与他一同长大的年轻人对他说：“这些百姓对王说：‘你父亲使我们负重轭，求你给我们减轻一些。’王要对他们如此说：‘我的小指头比我父亲的腰还粗呢！","notes":[]},{"n":11,"t":"我父亲使你们负重轭，现在我必使你们负更重的轭！我父亲用鞭子惩罚你们，我却要用蝎子！’”","notes":[]},{"n":12,"t":"耶罗波安和众百姓遵照王所说“你们第三天再来见我”的话，第三天来到罗波安那里。","notes":[]},{"n":13,"t":"王严厉地回答他们。罗波安王不采纳长者所出的主意，","notes":[]},{"n":14,"t":"却照着年轻人所出的主意对他们说：“我使你们负重轭，我必使你们负更重的轭！我父亲用鞭子惩罚你们，我却要用蝎子！”","notes":["“我”：有些古卷、七十士译本和其他古译本是“我父亲”；参王上12．14。"]},{"n":15,"t":"王不依从百姓，因这事件是出于神，为要应验耶和华藉示罗人亚希雅对尼八的儿子耶罗波安所说的话。","notes":[]},{"n":16,"t":"以色列众人见王不依从他们，百姓就回覆王说：“我们在大卫中有什么分呢？我们在耶西的儿子中没有产业！以色列啊，各回自己的帐棚去吧！大卫啊，现在你顾自己的家吧！”于是，以色列众人都回自己的帐棚去了；","notes":[]},{"n":17,"t":"至于住犹大城镇的以色列人，罗波安仍作他们的王。","notes":[]},{"n":18,"t":"罗波安王派监管劳役的哈多兰去，以色列人用石头打他，他就死了。罗波安王急忙上车，逃回耶路撒冷去了。","notes":["“哈多兰”：王上12．18称“亚多兰”。"]},{"n":19,"t":"这样，以色列背叛大卫家，直到今日。","notes":[]}]},"11":{"heading":"示玛雅的预言","verses":[{"n":1,"t":"罗波安来到耶路撒冷，召集犹大家和便雅悯家，共十八万人，都是精选的战士，要与以色列争战，好将国夺回再归自己。","notes":[]},{"n":2,"t":"但耶和华的话临到神人示玛雅，说：","notes":[]},{"n":3,"t":"“你去告诉所罗门的儿子犹大王罗波安和住犹大、便雅悯的以色列众人，说：","notes":[]},{"n":4,"t":"‘耶和华如此说：你们不可上去与你们的弟兄争战。各自回家去吧！因为这事是出于我。’”众人就听从耶和华的话回去，不去与耶罗波安争战。","notes":[]},{"n":5,"t":"罗波安住在耶路撒冷，在犹大为防御修筑城镇，","notes":[],"heads":["罗波安修筑诸城"]},{"n":6,"t":"他修筑伯利恒、以坦、提哥亚、","notes":[]},{"n":7,"t":"伯．夙、梭哥、亚杜兰、","notes":[]},{"n":8,"t":"迦特、玛利沙、西弗、","notes":[]},{"n":9,"t":"亚多莱音、拉吉、亚西加、","notes":[]},{"n":10,"t":"琐拉、亚雅仑、希伯仑。这都是犹大和便雅悯的坚固城。","notes":[]},{"n":11,"t":"罗波安又巩固这些堡垒，在其中安置军官，储备粮食、油和酒。","notes":[]},{"n":12,"t":"他在各城里预备盾牌和枪，使城极其坚固。犹大和便雅悯都归了他。","notes":[]},{"n":13,"t":"全以色列的祭司和利未人都从四方来归罗波安。","notes":[],"heads":["祭司和利未人都归犹大"]},{"n":14,"t":"利未人放弃他们的郊野和产业，来到犹大与耶路撒冷，因为耶罗波安和他的儿子拒绝他们，不许他们担任祭司事奉耶和华。","notes":[]},{"n":15,"t":"耶罗波安为丘坛，为山羊鬼魔，为自己所造的牛犊设立祭司。","notes":[]},{"n":16,"t":"以色列各支派中，凡立定心意寻求耶和华－以色列神的，都随从利未人来到耶路撒冷献祭给耶和华－他们列祖的神。","notes":[]},{"n":17,"t":"这就巩固了犹大王国，使所罗门的儿子罗波安强盛三年，因为这三年他们遵行大卫和所罗门的道。","notes":["“他们遵行”：七十士译本是“他遵行”。"]},{"n":18,"t":"罗波安娶大卫儿子耶利末的女儿玛哈拉为妻，又娶耶西儿子以利押的女儿亚比孩为妻，","notes":[],"heads":["罗波安的家室"]},{"n":19,"t":"从她生了几个儿子，就是耶乌施、示玛利雅和撒罕。","notes":[]},{"n":20,"t":"后来他又娶押沙龙的女儿玛迦，从她生了亚比雅、亚太、细撒和示罗密。","notes":[]},{"n":21,"t":"罗波安有十八个妻和六十个妾，生了二十八个儿子，六十个女儿；他却爱押沙龙的女儿玛迦，过于爱其他的妻妾。","notes":[]},{"n":22,"t":"罗波安立玛迦的儿子亚比雅作太子，在他兄弟中为首，因为要立他作王。","notes":[]},{"n":23,"t":"罗波安办事精明，把他众儿子分散在犹大和便雅悯全地各坚固城里，赐他们大量的粮食，又给他们娶许多妻子。","notes":[]}]},"12":{"heading":"埃及侵犯犹大","verses":[{"n":1,"t":"罗波安的王国稳固，他强盛的时候就离弃耶和华的律法，全以色列都跟从他。","notes":[]},{"n":2,"t":"罗波安王第五年，埃及王示撒上来攻打耶路撒冷，因为他们背叛了耶和华。","notes":[]},{"n":3,"t":"示撒带着一千二百辆战车，六万名骑兵，以及跟随他从埃及出来的路比人、苏基人和古实人的军队，多得不可胜数。","notes":[]},{"n":4,"t":"他攻取了犹大的坚固城，来到耶路撒冷。","notes":[]},{"n":5,"t":"那时，犹大的领袖因为示撒的缘故聚集在耶路撒冷，有先知示玛雅去见罗波安和众领袖，对他们说：“耶和华如此说：‘你们离弃了我，所以我也离弃你们，把你们交在示撒手里。’”","notes":[]},{"n":6,"t":"于是以色列的领袖和王都谦卑说：“耶和华是公义的。”","notes":[]},{"n":7,"t":"耶和华见他们谦卑，耶和华的话就临到示玛雅，说：“他们既谦卑，我必不灭绝他们；我要使他们暂时得拯救，不藉着示撒的手将我的怒气倒在耶路撒冷。","notes":[]},{"n":8,"t":"然而他们必作示撒的仆人，好叫他们知道，服事我与服事地上邦国有何分别。”","notes":[]},{"n":9,"t":"于是，埃及王示撒上来攻取耶路撒冷，夺了耶和华殿和王宫里的宝物，尽都带走，又夺走所罗门制造的金盾牌。","notes":[]},{"n":10,"t":"罗波安王制造铜盾牌代替那些金盾牌，交给看守王宫宫门的护卫长看管。","notes":[]},{"n":11,"t":"每逢王进耶和华的殿，护卫兵就来，举起这些盾牌；随后仍将盾牌送回护卫室。","notes":[]},{"n":12,"t":"王谦卑的时候，耶和华的怒气就转消了，不全然灭尽，并且在犹大中，情况也有好转。","notes":[]},{"n":13,"t":"罗波安王自强，在耶路撒冷作王。他登基的时候年四十一岁，在耶路撒冷，就是耶和华从以色列众支派中所选择立他名的城，作王十七年。罗波安的母亲名叫拿玛，是亚扪人。","notes":[],"heads":["罗波安政绩简述"]},{"n":14,"t":"罗波安行恶，因他没有立定心意寻求耶和华。","notes":[]},{"n":15,"t":"罗波安的事迹，自始至终不都写在示玛雅先知和易多先见的《史记》上吗？罗波安与耶罗波安时常交战。","notes":[]},{"n":16,"t":"罗波安与他祖先同睡，葬在大卫城，他的儿子亚比雅接续他作王。","notes":["“亚比雅”：王上14．31称“亚比央”。"]}]},"13":{"heading":"亚比雅与耶罗波安争战","verses":[{"n":1,"t":"耶罗波安王十八年，亚比雅登基作犹大王，","notes":[]},{"n":2,"t":"在耶路撒冷作王三年。他母亲名叫米该亚，是基比亚人乌列的女儿。亚比雅常与耶罗波安交战。","notes":["“米该亚...乌列的女儿”：11．20称“押沙龙的女儿玛迦”。"]},{"n":3,"t":"有一次亚比雅率领四十万精选的士兵出战，他们都是勇敢的战士；耶罗波安也率领八十万精选的大能勇士，迎着亚比雅摆阵。","notes":[]},{"n":4,"t":"亚比雅站在以法莲山区中的洗玛脸山上，说：“耶罗波安和以色列众人哪，要听我说！","notes":[]},{"n":5,"t":"耶和华－以色列的神曾立盐约，将以色列国永远赐给大卫和他的子孙，你们不知道吗？","notes":[]},{"n":6,"t":"但大卫儿子所罗门的臣仆、尼八的儿子耶罗波安起来背叛他的主人。","notes":[]},{"n":7,"t":"有些无赖的歹徒聚集跟从他，逞强攻击所罗门的儿子罗波安；那时罗波安还年轻，心志软弱，不能抵挡他们。","notes":[]},{"n":8,"t":"“现在你们说要抗拒大卫子孙手下所治理的耶和华的国，你们的人数众多，你们那里又有耶罗波安为你们所造当作神明的金牛犊。","notes":[]},{"n":9,"t":"你们不是驱逐耶和华的祭司亚伦的后裔和利未人吗？不是照着外邦人的恶俗为自己立祭司吗？无论何人牵一头公牛犊、七只公绵羊将自己分别出来，就可作虚无神明的祭司。","notes":[]},{"n":10,"t":"至于我们，耶和华是我们的神，我们并没有离弃他。我们有事奉耶和华的祭司，都是亚伦的后裔，并有利未人各尽其职。","notes":[]},{"n":11,"t":"他们每日早晚向耶和华献燔祭，烧芬芳的香，又在纯金的供桌上摆供饼，每晚点燃金灯台上的灯盏，因为我们遵守耶和华－我们神的命令，但你们却离弃了他。","notes":["“纯金的”：原文没有“金”；或译“洁净的”。"]},{"n":12,"t":"看哪，率领我们的是神，又有他的祭司拿号向你们吹出响声。以色列人哪，不要与耶和华－你们列祖的神争战，因你们必不能得胜。”","notes":[]},{"n":13,"t":"耶罗波安却在犹大人的后头设伏兵。这样，以色列人在犹大人的前头，伏兵在犹大人的后头。","notes":[]},{"n":14,"t":"犹大人转过来，看哪，前后都有战事，就呼求耶和华，祭司也吹号。","notes":[]},{"n":15,"t":"于是犹大人呐喊。犹大人呐喊的时候，神就击打耶罗波安和以色列众人，使他们败在亚比雅与犹大人面前。","notes":[]},{"n":16,"t":"以色列人在犹大人面前逃跑，神将他们交在犹大人手里。","notes":[]},{"n":17,"t":"亚比雅和他的军兵大大击杀以色列人，以色列人被杀仆倒的精兵有五十万。","notes":[]},{"n":18,"t":"那时，以色列人被制伏了。犹大人得胜，因为他们倚靠耶和华－他们列祖的神。","notes":[]},{"n":19,"t":"亚比雅追赶耶罗波安，攻取了他的几座城，就是伯特利和所属的乡镇，耶沙拿和所属的乡镇，以法拉音和所属的乡镇。","notes":["“乡镇”：原文直译“女子们”；本卷书下同。","“以法拉音”：原文另译“以弗仑”。"]},{"n":20,"t":"亚比雅在世的时候，耶罗波安不再强盛；耶和华击打他，他就死了。","notes":[]},{"n":21,"t":"亚比雅却渐渐强盛。他娶了十四个妻妾，生了二十二个儿子，十六个女儿。","notes":[]},{"n":22,"t":"亚比雅其余的事和他的言行都写在易多先知的评传上。","notes":[]}]},"14":{"heading":"亚撒王击败古实人","verses":[{"n":1,"t":"亚比雅与他祖先同睡，葬在大卫城，他的儿子亚撒接续他作王。亚撒在位期间，国中太平十年。","notes":[]},{"n":2,"t":"亚撒行耶和华－他神眼中看为善为正的事，","notes":[]},{"n":3,"t":"除掉外邦的祭坛和丘坛，打碎柱像，砍下亚舍拉，","notes":[]},{"n":4,"t":"吩咐犹大人寻求耶和华－他们列祖的神，遵行他的律法和诫命，","notes":[]},{"n":5,"t":"又在犹大各城镇除掉丘坛和香坛。在他治理下，国中太平。","notes":[]},{"n":6,"t":"他在犹大建造了几座坚固城。那些年间，国中太平，没有战争，因为耶和华赐他平安。","notes":[]},{"n":7,"t":"他对犹大人说：“我们要建造这些城镇，四围筑墙，盖城楼，安门，做闩；地仍属于我们，因为我们寻求耶和华－我们的神；我们寻求他，他就赐我们四境平安。”于是他们建造城镇，诸事亨通。","notes":[]},{"n":8,"t":"亚撒的军兵，出自犹大拿盾牌拿枪的三十万人，出自便雅悯拿小盾牌拉弓的二十八万人；这些全都是大能的勇士。","notes":[]},{"n":9,"t":"古实人谢拉率领一百万军兵，三百辆战车，出来攻击犹大人，到了玛利沙。","notes":[]},{"n":10,"t":"亚撒出去迎战，在玛利沙的洗法谷彼此摆阵。","notes":[]},{"n":11,"t":"亚撒呼求耶和华－他的神说：“耶和华啊，在强弱之间，惟有你能帮助。耶和华－我们的神啊，求你帮助我们，因为我们仰赖你，奉你的名来抵挡这大军。耶和华啊，你是我们的神，不要让人胜过你。”","notes":[]},{"n":12,"t":"于是耶和华击打古实人，使他们败在亚撒和犹大人面前，古实人就逃跑了。","notes":[]},{"n":13,"t":"亚撒和跟随他的军兵追赶他们，直到基拉耳。古实人被杀的很多，无法复原，因为他们在耶和华与他军兵面前被击溃。犹大人夺了许多财物，","notes":[]},{"n":14,"t":"又攻打基拉耳四围一切的城镇；城中的人都惧怕耶和华。犹大人掳掠了一切的城镇，因其中的财物很多，","notes":[]},{"n":15,"t":"又毁坏了群畜的圈，夺取许多的羊和骆驼，就回耶路撒冷去了。","notes":[]}]},"15":{"heading":"亚撒的改革","verses":[{"n":1,"t":"神的灵临到俄德的儿子亚撒利雅。","notes":[]},{"n":2,"t":"他出来迎接亚撒，对他说：“亚撒，犹大和便雅悯众人哪，要听我说：你们若顺从耶和华，耶和华必与你们同在；你们若寻求他，就必寻见；你们若离弃他，他必离弃你们。","notes":[]},{"n":3,"t":"以色列人不信真神，没有训诲的祭司，也没有律法，已经许多日子了。","notes":[]},{"n":4,"t":"但他们在急难的时候归向耶和华－以色列的神，寻求他，他就被他们寻见。","notes":[]},{"n":5,"t":"那时，出入的人不得平安，各地的居民都遭大乱；","notes":[]},{"n":6,"t":"他们被破坏殆尽，这国攻击那国，这城攻击那城，因为神用各样灾难扰乱他们。","notes":[]},{"n":7,"t":"现在你们要刚强，不要手软，因你们所行的必得赏赐。”","notes":[]},{"n":8,"t":"亚撒听见这些话和俄德先知的预言，就壮起胆来，在犹大和便雅悯全地，以及以法莲山区所夺的各城，把其中的可憎之物尽都除掉，又在耶和华殿的走廊前重新修筑耶和华的坛。","notes":[]},{"n":9,"t":"他又召集犹大和便雅悯众人，以及他们中间寄居的以法莲人、玛拿西人、西缅人。有许多以色列人归顺亚撒，因为他们看见耶和华－他的神与他同在。","notes":[]},{"n":10,"t":"亚撒作王第十五年三月，他们都聚集在耶路撒冷。","notes":[]},{"n":11,"t":"那日他们从所取的掳物中，将七百头牛和七千只羊献给耶和华。","notes":[]},{"n":12,"t":"他们立约，要尽心尽性寻求耶和华－他们列祖的神。","notes":[]},{"n":13,"t":"凡不寻求耶和华－以色列神的，无论大小、男女，必被处死。","notes":[]},{"n":14,"t":"他们就大声欢呼，吹号吹角，向耶和华起誓。","notes":[]},{"n":15,"t":"犹大众人为所起的誓欢喜，因他们尽心起誓，尽意寻求耶和华，耶和华就被他们寻见，且赐他们四境平安。","notes":[]},{"n":16,"t":"亚撒王甚至废了他祖母玛迦太后的位，因玛迦造了可憎的亚舍拉。亚撒砍下她的偶像，捣得粉碎，在汲沦溪边烧了，","notes":[]},{"n":17,"t":"只是丘坛还没有从以色列中废去，然而亚撒一生有纯正的心。","notes":[]},{"n":18,"t":"亚撒将他父亲所分别为圣与自己所分别为圣的金银和器皿都奉到神的殿里。","notes":[]},{"n":19,"t":"亚撒作王直到第三十五年，都没有战事。","notes":[]}]},"16":{"heading":"犹大与以色列争战","verses":[{"n":1,"t":"亚撒作王第三十六年，以色列王巴沙上来攻击犹大，修筑拉玛，不许人从犹大王亚撒那里出入。","notes":[]},{"n":2,"t":"于是亚撒从耶和华殿和王宫的府库里拿出金银来，送给住在大马士革的亚兰王便．哈达，说：","notes":[]},{"n":3,"t":"“你父曾与我父立约，我与你也要这样立约。看哪，我把金银送给你，请你废掉你与以色列王巴沙所立的约，使他从我这里撤退。”","notes":[]},{"n":4,"t":"便．哈达听从了亚撒王，就派遣他的军官去攻打以色列的城镇。他们攻下了以云、但、亚伯．玛音和拿弗他利一切的储货城。","notes":[]},{"n":5,"t":"巴沙听见了，就停工不修筑拉玛，任由他的工程停止。","notes":[]},{"n":6,"t":"于是亚撒王率领犹大众人，运走巴沙修筑拉玛所用的石头和木料，用以修筑迦巴和米斯巴。","notes":[]},{"n":7,"t":"那时，哈拿尼先见来见犹大王亚撒，对他说：“因你仰赖亚兰王，没有仰赖耶和华－你的神，所以亚兰王的军兵逃脱了你的手。","notes":[],"heads":["哈拿尼先见"]},{"n":8,"t":"古实人和路比人的军队不是非常强大吗？他们的战车骑兵不是极多吗？只因你仰赖耶和华，他就将他们交在你手里。","notes":[]},{"n":9,"t":"因为耶和华的眼目遍察全地，要坚固向他存纯正之心的人。你在这事上行得愚昧；因此，以后你必有战争。”","notes":[]},{"n":10,"t":"亚撒恼恨先见，为了这事向他发怒，将他囚在监里。那时亚撒也虐待一些百姓。","notes":[]},{"n":11,"t":"亚撒自始至终的事迹，看哪，都写在《犹大和以色列诸王记》上。","notes":[],"heads":["亚撒逝世"]},{"n":12,"t":"亚撒作王三十九年的时候患了脚疾，非常严重。他生病的时候没有求耶和华，只求医生。","notes":[]},{"n":13,"t":"他作王四十一年死了，与他祖先同睡，","notes":[]},{"n":14,"t":"葬在大卫城自己所凿的坟墓里。人把他放在床上，床上堆满各样馨香的香料，就是按做香的作法调和的香料，又为他生一堆大火志哀。","notes":[]}]},"17":{"heading":"犹大王约沙法","verses":[{"n":1,"t":"亚撒的儿子约沙法接续他作王，奋勇自强，防备以色列。","notes":[]},{"n":2,"t":"他安置军兵在犹大一切坚固城里，又安置驻军在犹大地和他父亲亚撒所得以法莲的城镇中。","notes":[]},{"n":3,"t":"耶和华与约沙法同在，因为他行他祖先大卫从前所行的道，不去寻求诸巴力，","notes":["有些抄本和七十士译本没有“大卫”。"]},{"n":4,"t":"只寻求他父亲的神，遵行他的诫命，不效法以色列人的行为。","notes":[]},{"n":5,"t":"所以耶和华坚定约沙法手中的国，犹大众人给他进贡；约沙法大有财富和尊荣。","notes":[]},{"n":6,"t":"他乐意遵行耶和华的道，并且从犹大再次除掉一切丘坛和亚舍拉。","notes":[]},{"n":7,"t":"他作王第三年，差遣官员便．亥伊勒、俄巴底、撒迦利雅、拿坦业、米该亚往犹大各城去教导百姓。","notes":[]},{"n":8,"t":"跟他们一同去的有利未人示玛雅、尼探雅、西巴第雅、亚撒黑、示米拉末、约拿单、亚多尼雅、多比雅、驼．巴多尼雅；跟他们一同的又有以利沙玛和约兰二位祭司。","notes":[]},{"n":9,"t":"他们在犹大教导，带着耶和华的律法书，走遍犹大各城教导百姓。","notes":[]},{"n":10,"t":"犹大四围地上的邦国都惧怕耶和华，不敢与约沙法争战。","notes":[],"heads":["约沙法的功绩"]},{"n":11,"t":"有些非利士人送礼物，进贡银子给约沙法。阿拉伯人也送他七千七百只公绵羊，七千七百只公山羊。","notes":[]},{"n":12,"t":"约沙法日渐强大，他在犹大建造堡垒和储货城。","notes":[]},{"n":13,"t":"他在犹大城镇中有许多工程，在耶路撒冷又有战士，就是大能的勇士。","notes":[]},{"n":14,"t":"他们按着父家的数目如下：犹大族的千夫长以押拿为首，率领三十万大能的勇士；","notes":[]},{"n":15,"t":"其次是约哈难千夫长，率领二十八万；","notes":[]},{"n":16,"t":"其次是细基利的儿子亚玛斯雅，他是一个自愿奉献给耶和华的人，率领二十万大能的勇士。","notes":[]},{"n":17,"t":"便雅悯族有大能的勇士以利雅大，率领二十万拿弓箭和盾牌的人；","notes":[]},{"n":18,"t":"其次是约萨拔，率领十八万预备打仗的人。","notes":[]},{"n":19,"t":"这些都是伺候王的，还有王在全犹大的坚固城所安置的不在其内。","notes":[]}]},"18":{"heading":"米该雅警告亚哈","verses":[{"n":1,"t":"约沙法大有财富和尊荣，他与亚哈结亲。","notes":[]},{"n":2,"t":"过了几年，他下到撒玛利亚去见亚哈；亚哈为他和跟从他的人宰了许多牛羊，劝他一同上去攻打基列的拉末。","notes":[]},{"n":3,"t":"以色列王亚哈问犹大王约沙法说：“你肯同我去攻打基列的拉末吗？”他回答说：“你我不分彼此，我的军队就是你的军队，我们必与你一同去争战。”","notes":[]},{"n":4,"t":"约沙法对以色列王说：“请你先求问耶和华的话。”","notes":[]},{"n":5,"t":"于是以色列王召集先知四百人，问他们说：“我可以上去攻打基列的拉末吗？还是不要上去呢？”他们说：“可以上去，因为神必将那城交在王的手里。”","notes":[]},{"n":6,"t":"约沙法说：“这里还有没有耶和华的先知，我们好求问他呢？”","notes":[]},{"n":7,"t":"以色列王对约沙法说：“还有一个人，是音拉的儿子米该雅，我们可以托他求问耶和华。只是我真的很恨他，因为他对我说预言，从不说吉言，总是说凶信。”约沙法说：“请王不要这么说。”","notes":[]},{"n":8,"t":"以色列王就召了一个官员来，说：“你快去，把音拉的儿子米该雅召来。”","notes":[]},{"n":9,"t":"以色列王和犹大王约沙法在撒玛利亚城门前的禾场，各穿朝服，坐在宝座上，所有的先知都在他们面前说预言。","notes":[]},{"n":10,"t":"基拿拿的儿子西底家为自己造了铁角，说：“耶和华如此说：‘你要用这些角抵触亚兰人，直到将他们灭尽。’”","notes":[]},{"n":11,"t":"所有的先知也都这样预言说：“可以上基列的拉末去，必然得胜，因为耶和华必将那城交在王的手中。”","notes":[]},{"n":12,"t":"那去召米该雅的使者对他说：“看哪，众先知都异口同声向王说吉言，你也跟他们说一样的话，说吉言吧！”","notes":[]},{"n":13,"t":"米该雅说：“我指着永生的耶和华起誓，我的神说什么，我就说什么。”","notes":[]},{"n":14,"t":"米该雅来到王那里，王问他：“米该雅啊，我们可以上去攻打基列的拉末吗？还是不要上去呢？”他说：“可以上去，必然得胜，敌人必交在你们手里。”","notes":[]},{"n":15,"t":"王对他说：“我要你发誓多少次，你才会奉耶和华的名向我说实话呢？”","notes":[]},{"n":16,"t":"米该雅说：“我看见以色列众人散布在山上，如同没有牧人的羊群一般。耶和华说：‘这些人没有主人，他们可以平安地各自回家去。’”","notes":[]},{"n":17,"t":"以色列王对约沙法说：“我岂没有告诉你，这人对我说预言，从不说吉言，只说凶信吗？”","notes":[]},{"n":18,"t":"米该雅说：“因此你们要听耶和华的话！我看见耶和华坐在宝座上，天上的万军侍立在他左右。","notes":[]},{"n":19,"t":"耶和华说：‘谁去引诱以色列王亚哈上基列的拉末去阵亡呢？’这个这样说，那个那样说。","notes":[]},{"n":20,"t":"随后有一个灵出来，站在耶和华面前，说：‘我去引诱他。’耶和华问他：‘用什么方法呢？’","notes":[]},{"n":21,"t":"他说：‘我要出去，在他众先知的口中成为谎言的灵。’耶和华说：‘这样，你去引诱他，必能成功。你出去，照样做吧！’","notes":[]},{"n":22,"t":"现在，看哪，耶和华使谎言的灵入了你的这些先知的口，并且耶和华已经宣告要降祸于你。”","notes":[]},{"n":23,"t":"基拿拿的儿子西底家前来打米该雅一巴掌，说：“耶和华的灵从哪里离开我向你说话呢？”","notes":[]},{"n":24,"t":"米该雅说：“看哪，你进入严密的内室躲藏的那日，就必看见。”","notes":[]},{"n":25,"t":"以色列王说：“把米该雅带走，交回给亚们市长和约阿施王子。","notes":[]},{"n":26,"t":"你们要说：‘王如此说：把这个人关在监狱里，使他受苦，吃不饱喝不足，直等到我平安回来。’”","notes":[]},{"n":27,"t":"米该雅说：“你若真的能平安回来，那就是耶和华没有藉我说话了。”他又说：“众百姓啊，你们都要听！”","notes":[]},{"n":28,"t":"以色列王和犹大王约沙法上基列的拉末去。","notes":[],"heads":["亚哈阵亡"]},{"n":29,"t":"以色列王对约沙法说：“我要改装上阵，你可以仍穿王服。”于是以色列王改装，他们上阵去了。","notes":[]},{"n":30,"t":"亚兰王吩咐他的战车长说：“你们不要与他们的大将或小兵交战，只要单单攻击以色列王。”","notes":[]},{"n":31,"t":"那些战车长看见约沙法就说：“这一定是以色列王！”他们转过去与他交战。约沙法一呼喊，耶和华就帮助他，神使他们转离他。","notes":[]},{"n":32,"t":"战车长见他不是以色列王，就转身不追他了。","notes":[]},{"n":33,"t":"有一人开弓，并不知情，箭恰巧射入以色列王铠甲的缝里。王对驾车的说：“我受重伤了，你掉过车来，载我离开战场！”","notes":[]},{"n":34,"t":"那日，战况越来越猛，以色列王勉强站在战车上，面对亚兰人，直到傍晚。日落的时候，王就死了。","notes":[]}]},"19":{"heading":"先知斥责约沙法","verses":[{"n":1,"t":"犹大王约沙法平安回耶路撒冷，到自己的宫里。","notes":[]},{"n":2,"t":"哈拿尼的儿子耶户先见出来迎接约沙法王，对他说：“你怎么可以帮助恶人，爱那恨耶和华的人呢？因此耶和华的愤怒临到你了。","notes":[]},{"n":3,"t":"然而你还有善行，因你从国中除掉亚舍拉，立定心意寻求神。”","notes":[]},{"n":4,"t":"约沙法住在耶路撒冷，以后又出巡民间，从别是巴直到以法莲山区，引导百姓归向耶和华－他们列祖的神。","notes":[],"heads":["约沙法的改革"]},{"n":5,"t":"他在国中，在犹大一切坚固城设立审判官，各城都是如此。","notes":[]},{"n":6,"t":"他对审判官说：“你们应当谨慎所做的事，因为你们审判不是为人，而是为耶和华。在审判的事上，他必与你们同在。","notes":[]},{"n":7,"t":"现在，你们应当敬畏耶和华，谨慎办事，因为耶和华－我们的神没有不义，不看人的情面，也不受贿赂。”","notes":[]},{"n":8,"t":"约沙法从利未人和祭司，以及以色列族长中，也委派人在耶路撒冷为耶和华施行审判，为耶路撒冷的居民听讼断案。","notes":["“为耶路撒冷的居民听讼断案”是根据七十士译本；原文是“听讼断案。他们就回耶路撒冷去了”。"]},{"n":9,"t":"约沙法吩咐他们说：“你们当这样，以敬畏耶和华、诚实和纯正的心办事。","notes":[]},{"n":10,"t":"你们住在各城的弟兄，若有争讼的案件呈到你们这里，或为流血，或犯律法、诫命、律例、典章，你们要警戒他们，免得他们得罪耶和华，以致愤怒临到你们和你们的弟兄；你们当这样行，就没有罪了。","notes":[]},{"n":11,"t":"看哪，凡属耶和华的事，有亚玛利雅祭司长管理你们；凡属王的事，有犹大家的领袖以实玛利的儿子西巴第雅管理你们；在你们面前有利未人作官长。你们应当壮胆办事，愿耶和华与善人同在。”","notes":[]}]},"20":{"heading":"与以东交战","verses":[{"n":1,"t":"此后，摩押人和亚扪人，连同一些米乌尼人来攻击约沙法。","notes":["“一些米乌尼人”是根据七十士译本；原文是“亚扪人”。"]},{"n":2,"t":"有人来报告约沙法说：“从海的那边，以东有大军来攻击你，看哪，他们在哈洗逊．他玛，就是隐．基底。”","notes":["“以东”是根据一些古卷和其他古译本；原文是“亚兰”。"]},{"n":3,"t":"约沙法惧怕，就定意寻求耶和华，在全犹大宣告禁食。","notes":[]},{"n":4,"t":"于是犹大人聚集，求耶和华帮助，甚至他们从犹大各城前来寻求耶和华。","notes":[]},{"n":5,"t":"约沙法站在犹大和耶路撒冷的会众中，在耶和华殿新的院子前，","notes":[]},{"n":6,"t":"说：“耶和华－我们列祖的神啊，你不是天上的神吗？你不是万邦万国的主宰吗？在你手中有大能大力，无人能抵挡你。","notes":[]},{"n":7,"t":"我们的神啊，你不是曾在你百姓以色列面前驱逐这地的居民，将这地赐给你朋友亚伯拉罕的后裔永远为业吗？","notes":[]},{"n":8,"t":"他们住在这地，又为你的名建造圣所，说：","notes":[]},{"n":9,"t":"‘若有祸患临到我们，或刀兵的惩罚，或瘟疫饥荒，我们在急难的时候，站在这殿前向你呼求，你必垂听并且拯救，因为你的名在这殿里。’","notes":[]},{"n":10,"t":"现在，看哪，以色列人出埃及地的时候，你不容许以色列人侵犯亚扪人、摩押人和西珥山人，以色列人就离开他们，不灭绝他们。","notes":[]},{"n":11,"t":"看哪，他们这样回报我们，要来驱逐我们离开你赐给我们为业之地。","notes":[]},{"n":12,"t":"我们的神啊，你不惩罚他们吗？因为我们无力抵挡这来攻击我们的大军。我们不知道该怎么做，我们的眼目单仰望你。”","notes":[]},{"n":13,"t":"犹大众人和他们的孩童、妻子、儿女都站在耶和华面前。","notes":[]},{"n":14,"t":"那时，耶和华的灵在会众中临到利未人亚萨的后裔雅哈悉，他是玛探雅的玄孙，耶利的曾孙，比拿雅的孙子，撒迦利雅的儿子。","notes":[]},{"n":15,"t":"他说：“犹大众人、耶路撒冷的居民和约沙法王啊，你们要留心听，耶和华对你们如此说：‘不要因这大军恐惧惊惶，因为胜败不在乎你们，而是在乎神。","notes":[]},{"n":16,"t":"明日你们要下去迎敌；看哪，他们从洗斯坡上来，你们必在耶鲁伊勒旷野前的谷口遇见他们。","notes":[]},{"n":17,"t":"犹大和耶路撒冷人哪，这次你们不要争战，要摆阵站着，看耶和华为你们施行拯救。不要恐惧，也不要惊惶。明日当出去迎敌，因为耶和华与你们同在。’”","notes":[]},{"n":18,"t":"约沙法屈身，脸伏于地，犹大众人和耶路撒冷的居民也俯伏在耶和华面前，敬拜耶和华。","notes":[]},{"n":19,"t":"哥辖子孙和可拉子孙的利未人都起来，用极大的声音赞美耶和华－以色列的神。","notes":[]},{"n":20,"t":"清晨，众人早起往提哥亚的旷野去。出去的时候，约沙法站着说：“犹大人和耶路撒冷的居民哪，要听我说：信靠耶和华－你们的神就必站立得稳；信赖他的先知就必亨通。”","notes":[]},{"n":21,"t":"约沙法与百姓商议，就设立歌唱的人，颂赞耶和华，使他们穿上圣洁的礼服，走在军队前赞美耶和华：“当称谢耶和华，因他的慈爱永远长存！”","notes":[]},{"n":22,"t":"他们开始唱歌赞美的时候，耶和华派伏兵击杀那来攻击犹大的亚扪人、摩押人和西珥山人，他们就被打败了。","notes":[]},{"n":23,"t":"亚扪人和摩押人起来，击杀住西珥山的人，把他们灭尽；灭尽住西珥山的人之后，他们又彼此自相击杀。","notes":[]},{"n":24,"t":"犹大人来到旷野的瞭望楼，向那大军观看，看哪，遍地都是尸体，没有一个逃脱的。","notes":[]},{"n":25,"t":"约沙法和他的百姓就来收取掠物，找到许多牲畜、财物、衣服和珍宝。他们取掠物归为己有，直到无法携带；因为掠物太多，他们足足收取了三日。","notes":["“找到许多牲畜”是根据七十士译本；原文是“在他们当中找到”。","“衣服”是根据一些古卷和其他古译本；原文是“尸体”。"]},{"n":26,"t":"第四日，众人聚集在比拉迦谷，在那里称颂耶和华；因此那地方名叫比拉迦谷，直到今日。","notes":["“比拉迦”意思是“称颂”。"]},{"n":27,"t":"在约沙法率领下，犹大人和耶路撒冷人都欢欢喜喜地回耶路撒冷，耶和华使他们因战胜仇敌而喜乐。","notes":[]},{"n":28,"t":"他们弹琴、鼓瑟、吹号来到耶路撒冷，进了耶和华的殿。","notes":[]},{"n":29,"t":"地上所有的邦国听见耶和华打败以色列的仇敌，就都惧怕神。","notes":[]},{"n":30,"t":"这样，约沙法的国得享太平，因为神赐他四境平安。","notes":[]},{"n":31,"t":"约沙法作犹大王，登基的时候年三十五岁，在耶路撒冷作王二十五年。他母亲名叫阿苏巴，是示利希的女儿。","notes":[],"heads":["约沙法逝世"]},{"n":32,"t":"约沙法效法他父亲亚撒所行的道，不偏离左右，行耶和华眼中看为正的事。","notes":[]},{"n":33,"t":"只是丘坛还没有废去，百姓也没有立定心意归向他们列祖的神。","notes":[]},{"n":34,"t":"约沙法其余的事，看哪，自始至终都写在哈拿尼的儿子耶户的书上，这些事也记载在《以色列诸王记》上。","notes":[]},{"n":35,"t":"此后，犹大王约沙法与以色列王亚哈谢结盟；亚哈谢多行恶事。","notes":[]},{"n":36,"t":"他们合伙造船要往他施去，就在以旬．迦别造船。","notes":[]},{"n":37,"t":"玛利沙人多大瓦的儿子以利以谢向约沙法预言说：“因你与亚哈谢结盟，耶和华必破坏你所造的。”后来那些船果然毁坏，不能往他施去了。","notes":[]}]},"21":{"heading":"犹大王约兰","verses":[{"n":1,"t":"约沙法与他祖先同睡，与他祖先同葬在大卫城，他的儿子约兰接续他作王。","notes":[]},{"n":2,"t":"约兰有几个兄弟，就是约沙法的儿子亚撒利雅、耶歇、撒迦利雅、亚撒列夫、米迦勒、示法提雅；这些都是以色列王约沙法的儿子。","notes":["“以色列”：有许多古卷、七十士译本和其他古译本是“犹大”。"]},{"n":3,"t":"他们的父亲把许多礼物，金银财宝和犹大的坚固城赐给他们，却把国赐给约兰，因为他是长子。","notes":[]},{"n":4,"t":"约兰起来治理他父亲的国，奋勇自强，用刀杀了他所有的兄弟和以色列的几个领袖。","notes":[]},{"n":5,"t":"约兰登基的时候年三十二岁，在耶路撒冷作王八年。","notes":[]},{"n":6,"t":"他行以色列诸王的道，正如亚哈家所行的，因他娶了亚哈的女儿为妻，行耶和华眼中看为恶的事。","notes":[]},{"n":7,"t":"耶和华却因自己与大卫所立的约，不肯灭绝大卫的家，要照他所应许的，永远赐灯光给大卫和他的子孙。","notes":[]},{"n":8,"t":"约兰在位期间，以东背叛，自己立王治理他们，脱离犹大的权势。","notes":[]},{"n":9,"t":"约兰就率领他的军官和所有的战车过去。他夜间起来，攻打围困他的以东人和战车长。","notes":[]},{"n":10,"t":"这样，以东背叛，脱离犹大的权势，直到今日。那时，立拿也背叛了，脱离它的权势，因为约兰离弃耶和华－他列祖的神。","notes":[]},{"n":11,"t":"他又在犹大山岭建造丘坛，使耶路撒冷的居民行淫，诱惑犹大。","notes":["“山岭”：有许多古卷、七十士译本和其他古译本是“城镇”。"]},{"n":12,"t":"以利亚先知写信给约兰说：“耶和华－你祖先大卫的神如此说：‘因为你不行你父约沙法和犹大王亚撒的道，","notes":[]},{"n":13,"t":"反而行以色列诸王的道，使犹大和耶路撒冷居民行淫，像亚哈家行淫一样，又杀了你父家比你好的那些兄弟。","notes":[]},{"n":14,"t":"看哪，耶和华必降大灾于你的百姓和你的妻妾、儿女，以及你一切所有的。","notes":[]},{"n":15,"t":"至于你，你必患许多的病，你的肠子也必生病，日渐沉重，直到肠子坠落下来。’”","notes":["“许多的病”：有些古卷、七十士译本和其他古译本是“严重的病”。"]},{"n":16,"t":"耶和华激发非利士人和靠近古实人的阿拉伯人的心来攻击约兰。","notes":[]},{"n":17,"t":"他们上来攻击犹大，侵入境内，掳掠了王宫里所有的财物和他的妻妾、儿女，除了他的小儿子约哈斯之外，没有留下一个儿子。","notes":["“约哈斯”：七十士译本是“亚哈谢”；参代下22章。"]},{"n":18,"t":"这一切事以后，耶和华击打约兰，使他的肠子患不能医治的病。","notes":[]},{"n":19,"t":"这病缠绵日久，过了二年，肠子坠落下来，他就病重而死。他的百姓没有为他生火志哀，像从前为他祖先生火一样。","notes":[]},{"n":20,"t":"约兰登基的时候年三十二岁，在耶路撒冷作王八年。他逝世无人思慕，众人把他葬在大卫城，只是不在列王的坟墓里。","notes":[]}]},"22":{"heading":"犹大王亚哈谢","verses":[{"n":1,"t":"耶路撒冷的居民立约兰的小儿子亚哈谢接续他作王，因为跟随阿拉伯人来攻营的军兵把亚哈谢所有的兄长都杀了；犹大王约兰的儿子亚哈谢就作了王。","notes":[]},{"n":2,"t":"亚哈谢登基的时候年四十二岁，在耶路撒冷作王一年。他母亲名叫亚她利雅，是暗利的孙女。","notes":["“四十二岁”：王下8．26是“二十二岁”。"]},{"n":3,"t":"亚哈谢也行亚哈家的道，因为他母亲给他主谋，使他行恶。","notes":[]},{"n":4,"t":"他行耶和华眼中看为恶的事，像亚哈家一样；因他父亲死后，他们给他主谋，使他败坏。","notes":[]},{"n":5,"t":"他也听从他们的计谋，与以色列王亚哈的儿子约兰同往基列的拉末去，与亚兰王哈薛交战。亚兰人打伤了约兰，","notes":[]},{"n":6,"t":"他回到耶斯列，医治在拉末与亚兰王哈薛打仗时被击打所受的伤。约兰的儿子犹大王亚哈谢因为亚哈的儿子约兰病了，就下到耶斯列看望他。","notes":["“拉末”是根据七十士译本；原文是“拉玛”，可能是“基列的拉末”的简称。","“亚哈谢”是根据一些古卷、七十士译本和其他古译本；原文是“亚撒利雅”。"]},{"n":7,"t":"亚哈谢去见约兰而遇害，这是出乎神；因为他一到就同约兰出去攻击宁示的孙子耶户；这耶户是耶和华所膏，使他剪除亚哈家的。","notes":[]},{"n":8,"t":"耶户向亚哈家施行惩罚的时候，遇见犹大的众领袖和亚哈谢的侄子们正服事亚哈谢，就把他们都杀了。","notes":[]},{"n":9,"t":"亚哈谢躲在撒玛利亚，耶户寻找他，众人把他拿住，送到耶户那里，就杀了他。他们把他埋葬，因他们说，他是那尽心寻求耶和华之约沙法的儿子。这样，亚哈谢的家无力保住国权。","notes":[]},{"n":10,"t":"亚哈谢的母亲亚她利雅见她儿子死了，就起来剿灭犹大王室所有的后裔。","notes":[],"heads":["亚她利雅篡位"]},{"n":11,"t":"但王的女儿约示巴将亚哈谢的儿子约阿施从那被杀的王子中偷出来，把他和他的奶妈藏在卧房里。约示巴是约兰王的女儿，亚哈谢的妹妹，祭司耶何耶大的妻子。她藏了约阿施，躲避亚她利雅，免受杀害。","notes":[]},{"n":12,"t":"亚她利雅治理这地的时候，约阿施和他们一同在神殿里藏了六年。","notes":[]}]},"23":{"heading":"推翻亚她利雅","verses":[{"n":1,"t":"第七年，耶何耶大奋勇自强，叫了耶罗罕的儿子亚撒利雅、约哈难的儿子以实玛利、俄备得的儿子亚撒利雅、亚大雅的儿子玛西雅，和细基利的儿子以利沙法等众百夫长，与他们立约。","notes":[]},{"n":2,"t":"他们走遍犹大，从犹大各城召集利未人和以色列的众族长到耶路撒冷来。","notes":[]},{"n":3,"t":"全会众在神殿里与王立约。耶何耶大对他们说：“看哪，王的儿子必作王，正如耶和华指着大卫子孙所应许的。","notes":[]},{"n":4,"t":"你们要这样做：在安息日值班的祭司和利未人，三分之一要把守各门，","notes":[]},{"n":5,"t":"三分之一要在王宫，三分之一要在根基门；众百姓都要在耶和华殿的院内。","notes":[]},{"n":6,"t":"除了祭司和供职的利未人之外，不准别人进耶和华的殿；只有他们可以进去，因为他们是神圣的。众百姓都要遵守耶和华所吩咐的。","notes":[]},{"n":7,"t":"利未人要手中各拿兵器，四围保护王；凡擅自进殿的，要被处死。王出入的时候，你们当跟随他。”","notes":[]},{"n":8,"t":"利未人和犹大众人都照着耶何耶大祭司一切所吩咐的去做，各带自己的人，无论安息日值班或不值班的都来，因为耶何耶大祭司不许他们下班。","notes":[]},{"n":9,"t":"耶何耶大祭司就把神殿里所藏大卫王的枪和大小盾牌交给百夫长，","notes":[]},{"n":10,"t":"又分派众百姓手中各拿兵器，在祭坛和殿那里，从殿南到殿北，站在王的四围；","notes":[]},{"n":11,"t":"他们领约阿施 出来，给他戴上冠冕，把律法书交给他，立他作王。耶何耶大和他的儿子们膏他，他们说：“愿王万岁！”","notes":["“约阿施”：原文是“王的儿子”。"]},{"n":12,"t":"亚她利雅听见百姓奔走赞美王的声音，就进耶和华的殿，到百姓那里。","notes":[]},{"n":13,"t":"她观看，看哪，王站在殿门的柱旁，百夫长和号手在王旁边，国中的众百姓都欢乐吹号，又有歌唱的人用乐器领人歌唱赞美。亚她利雅就撕裂衣服，喊着说：“反了！反了！”","notes":[]},{"n":14,"t":"耶何耶大祭司带领管军兵的百夫长出来，对他们说：“把她从行列之间赶出去，凡跟随她的必用刀杀死！”因为祭司说：“不可在耶和华殿里杀她。”","notes":[]},{"n":15,"t":"他们就下手拿住她；她进入通往王宫的马门，他们就在那里把她杀了。","notes":[]},{"n":16,"t":"耶何耶大与众百姓，又与王立约，要作耶和华的子民。","notes":[],"heads":["耶何耶大的改革"]},{"n":17,"t":"于是众百姓到巴力庙去，拆毁了庙，打碎祭坛和偶像，又在坛前把巴力的祭司玛坦杀了。","notes":[]},{"n":18,"t":"耶何耶大派官员在利未家的祭司手下看守耶和华的殿，他们是大卫所分派的，在耶和华殿中照摩西律法上所写，献燔祭给耶和华，又按大卫所定的，欢乐歌唱。","notes":[]},{"n":19,"t":"耶何耶大又设立守卫把守耶和华殿的各门，无论因何事而不洁净的人，都不准进去。","notes":[]},{"n":20,"t":"他又率领百夫长和贵族，与民间的官长，以及国中的众百姓，请王从耶和华的殿下来，由上门正中进入王宫，使王坐在国度的王位上。","notes":[]},{"n":21,"t":"国中的众百姓都欢乐，合城也都平静。他们已将亚她利雅用刀杀了。","notes":[]}]},"24":{"heading":"犹大王约阿施","verses":[{"n":1,"t":"约阿施登基的时候年方七岁，在耶路撒冷作王四十年。他母亲名叫西比亚，是别是巴人。","notes":[]},{"n":2,"t":"耶何耶大祭司在世的日子，约阿施行耶和华眼中看为正的事。","notes":[]},{"n":3,"t":"耶何耶大为他娶了两个妻子，他生儿育女。","notes":[]},{"n":4,"t":"此后，约阿施有心重修耶和华的殿，","notes":[]},{"n":5,"t":"就召集祭司和利未人，吩咐他们说：“你们要往犹大各城去，向以色列众人征收银子，按每年的需要整修你们神的殿；你们要急速办理这事。”但利未人没有急速办理。","notes":[]},{"n":6,"t":"王召了耶何耶大祭司长来，对他说：“从前耶和华的仆人摩西，为法柜的帐幕与以色列会众所定的捐献，你为何不叫利未人照这例向犹大和耶路撒冷征收呢？”","notes":[]},{"n":7,"t":"因为那恶妇亚她利雅的儿子们曾拆毁神的殿，又用耶和华殿中分别为圣的物供奉诸巴力。","notes":[]},{"n":8,"t":"于是王下令造一个柜子，放在耶和华殿的门外，","notes":[]},{"n":9,"t":"又通告犹大和耶路撒冷，要将神仆人摩西在旷野所吩咐以色列的捐献送来给耶和华。","notes":[]},{"n":10,"t":"众领袖和百姓都欢欢喜喜带捐献来，投入柜中，直到投满。","notes":[]},{"n":11,"t":"利未人见银子多了，把柜子抬到王所派的官长面前；这时王的书记和祭司长的助手就会来把柜子倒空，然后放回原处。日日都是这样做，积蓄的银子很多。","notes":[]},{"n":12,"t":"王与耶何耶大把银子交给耶和华殿里办事的人，他们就雇了石匠、木匠重修耶和华的殿，又雇了铁匠、铜匠整修耶和华的殿。","notes":[]},{"n":13,"t":"工人做工，修理工程在他们手中渐渐完成，他们将神的殿修理得如同从前一样，非常坚固。","notes":[]},{"n":14,"t":"他们做完了，就把多余的银子拿到王与耶何耶大面前，用以制造耶和华殿供奉所用的器皿和调羹，以及金银的器皿。耶何耶大在世的日子，众人经常在耶和华殿里献燔祭。","notes":[]},{"n":15,"t":"耶何耶大年纪老迈，日子满足而死，死的时候年一百三十岁。","notes":[]},{"n":16,"t":"众人把他与列王同葬在大卫城，因为他在以色列中为神和他的殿做了美善的事。","notes":[]},{"n":17,"t":"耶何耶大死后，犹大的众领袖来叩拜王，那时王就听了他们。","notes":[]},{"n":18,"t":"他们离弃耶和华－他们列祖神的殿，去事奉亚舍拉和偶像；因他们这罪，就有愤怒临到犹大和耶路撒冷。","notes":[]},{"n":19,"t":"但神仍差遣先知到他们那里，引导他们归向耶和华。先知警戒他们，他们却不肯听。","notes":[]},{"n":20,"t":"那时，神的灵感动耶何耶大的儿子撒迦利亚祭司，他就站在上面，对百姓说：“神如此说：‘你们为何干犯耶和华的诫命，以致不得亨通呢？因为你们离弃耶和华，所以他也离弃你们。’”","notes":[]},{"n":21,"t":"众人谋害撒迦利亚，照着王的吩咐，在耶和华殿的院内用石头打死他。","notes":[]},{"n":22,"t":"这样，约阿施王不记念撒迦利亚的父亲耶何耶大向自己所施的恩，杀了他的儿子。撒迦利亚临死的时候说：“愿耶和华鉴察伸冤！”","notes":[]},{"n":23,"t":"年底的时候，亚兰的军兵上来攻击约阿施，来到犹大和耶路撒冷，杀了百姓中的众领袖，把所掠取的财物全送到大马士革王那里。","notes":[],"heads":["约阿施被杀"]},{"n":24,"t":"亚兰的军兵虽只来了一小队人，耶和华却将极大的军队交在他们手里；因为犹大人离弃耶和华－他们列祖的神，所以亚兰人惩罚约阿施。","notes":[]},{"n":25,"t":"亚兰人离开约阿施的时候，他患重病；他的臣仆背叛他，要报耶何耶大祭司儿子的流血之仇，在床上杀了他。他就死了，葬在大卫城，只是不葬在列王的坟墓里。","notes":["“他患重病”或译“他受了重伤”。","“儿子”是根据七十士译本和其他古译本；原文是“儿子们”。"]},{"n":26,"t":"背叛他的是亚扪妇人示米押的儿子撒拔和摩押妇人示米利的儿子约萨拔。","notes":[]},{"n":27,"t":"至于他的儿子们和他所受的众多警戒，以及他重修神殿的事，看哪，都写在《列王评传》上。他的儿子亚玛谢接续他作王。","notes":[]}]},"25":{"heading":"犹大王亚玛谢","verses":[{"n":1,"t":"亚玛谢登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫约耶但，是耶路撒冷人。","notes":[]},{"n":2,"t":"亚玛谢行耶和华眼中看为正的事，只是没有纯正的心。","notes":[]},{"n":3,"t":"他的王国一巩固，就把杀他父王的臣仆杀了，","notes":[]},{"n":4,"t":"却没有处死他们的儿子，这是照摩西律法书上耶和华所吩咐的说：“不可因子杀父，也不可因父杀子，各人要为自己的罪而死。”","notes":[]},{"n":5,"t":"亚玛谢召集犹大人，按着父家为全犹大和便雅悯设立千夫长、百夫长，又数点人数，从二十岁以上，能拿枪拿盾牌出去打仗的精兵共有三十万；","notes":[],"heads":["与以东交战"]},{"n":6,"t":"又用一百他连得银子，从以色列招募了十万大能的勇士。","notes":[]},{"n":7,"t":"有一个神人来见亚玛谢，对他说：“王啊，不要带领以色列的军兵与你同去，因为耶和华不和以色列，和任何以法莲的子孙同在。","notes":[]},{"n":8,"t":"你若一定要去，就奋勇作战吧！但神必使你败在敌人面前，因为神能助人得胜，也能使人落败。”","notes":[]},{"n":9,"t":"亚玛谢问神人：“我给了以色列军队的那一百他连得银子怎么样呢？”神人回答：“耶和华会把比这些更多的赐给你。”","notes":[]},{"n":10,"t":"于是亚玛谢把那从以法莲来的军兵分别出来，叫他们到自己的地方去。他们非常恼怒犹大，气愤地回自己的地方去了。","notes":[]},{"n":11,"t":"亚玛谢壮起胆来，率领他的军队到盐谷，杀了一万西珥人。","notes":[]},{"n":12,"t":"犹大人又生擒了一万人，把他们带到西拉山顶上，从西拉山顶扔下去，把他们全都摔碎了。","notes":[]},{"n":13,"t":"但亚玛谢所打发回去、不许一同出征的那些军兵劫掠犹大各城，从撒玛利亚直到伯．和仑，杀了三千人，抢了许多财物。","notes":[]},{"n":14,"t":"亚玛谢击杀以东人回来以后，他把西珥人的神像带回，立为自己的神明，在它们面前叩拜烧香。","notes":[]},{"n":15,"t":"耶和华的怒气向亚玛谢发作，差派一个先知去见他，对他说：“这些神明不能救自己的百姓脱离你的手，你为何寻求它们呢？”","notes":[]},{"n":16,"t":"先知与王说话的时候，王对他说：“难道我们立你作王的谋士吗？你住口吧！为何要挨打呢？”先知就止住了，却说：“我知道神已定意要消灭你，因为你行这事，不听从我的劝戒。”","notes":[]},{"n":17,"t":"犹大王亚玛谢经商议后，就派人去见耶户的孙子，约哈斯的儿子以色列王约阿施，说：“来，让我们面对面较量吧！”","notes":[],"heads":["与以色列争战"]},{"n":18,"t":"以色列王约阿施派人去见犹大王亚玛谢，说：“黎巴嫩的蒺藜派人去见黎巴嫩的香柏树，说：‘将你的女儿嫁给我的儿子。’但有一只野兽经过黎巴嫩，把蒺藜践踏了。","notes":[]},{"n":19,"t":"你说，看哪，你打败了以东，就心高气傲，以此为荣。现在，你待在家里算了吧，为何要惹祸使自己和犹大一同败亡呢？”","notes":[]},{"n":20,"t":"亚玛谢却不肯听从。这是出乎神，好将他们交在敌人手里，因为他们寻求以东的神明。","notes":[]},{"n":21,"t":"于是以色列王约阿施上来，在犹大的伯．示麦与犹大王亚玛谢面对面较量。","notes":[]},{"n":22,"t":"犹大败在以色列面前，他们逃跑，各人逃回自己的帐棚去了。","notes":[]},{"n":23,"t":"以色列王约阿施在伯．示麦擒住约哈斯的孙子，约阿施的儿子犹大王亚玛谢，把他带到耶路撒冷，又拆毁耶路撒冷的城墙，从以法莲门直到角门共四百肘。","notes":["“约哈斯”就是“亚哈谢”；参王下14．13。"]},{"n":24,"t":"他带着俄别．以东所看守神殿里的一切金银和器皿，与王宫里的财宝，又带着人质，回撒玛利亚去了。","notes":[]},{"n":25,"t":"约哈斯的儿子以色列王约阿施死后，犹大王约阿施的儿子亚玛谢又活了十五年。","notes":[]},{"n":26,"t":"亚玛谢其余的事，自始至终，看哪，不都写在《犹大和以色列诸王记》上吗？","notes":[]},{"n":27,"t":"自从亚玛谢离弃耶和华之后，在耶路撒冷有人背叛他，他就逃往拉吉；他们却派人追到拉吉，在那里杀了他。","notes":[]},{"n":28,"t":"有人用马将他驮回，把他与祖先一同葬在犹大的城。","notes":["“犹大的城”：有古卷和七十士译本是“大卫城”；参王下14．20。"]}]},"26":{"heading":"犹大王乌西雅","verses":[{"n":1,"t":"犹大众百姓立乌西雅接续他父亲亚玛谢作王，那时他年十六岁。","notes":["“乌西雅”又名“亚撒利雅”；参王下14．21。"]},{"n":2,"t":"亚玛谢王与他祖先同睡之后，乌西雅收复以禄回归犹大，又重新修建。","notes":[]},{"n":3,"t":"乌西雅登基的时候年十六岁，在耶路撒冷作王五十二年。他母亲名叫耶可利雅，是耶路撒冷人。","notes":[]},{"n":4,"t":"乌西雅行耶和华眼中看为正的事，效法他父亲亚玛谢一切所行的。","notes":[]},{"n":5,"t":"撒迦利亚是一个通晓神默示的人，他在世的日子，乌西雅定意寻求神；乌西雅寻求耶和华的日子，神使他亨通。","notes":["“通晓神默示的人”：有古卷和七十士译本是“教导人敬畏神的人”。"]},{"n":6,"t":"他出去攻击非利士人，拆毁了迦特、雅比尼和亚实突的城墙，又在非利士人中，在亚实突境内建筑城镇。","notes":[]},{"n":7,"t":"神帮助他攻击非利士人和住在姑珥．巴力的阿拉伯人，以及米乌尼人。","notes":[]},{"n":8,"t":"米乌尼人向乌西雅进贡。他的名声传到埃及，因他非常强盛。","notes":["“米乌尼人”是根据七十士译本；原文是“亚扪人”。"]},{"n":9,"t":"乌西雅在耶路撒冷的角门和谷门，以及城墙转角之处建筑城楼，非常坚固。","notes":[]},{"n":10,"t":"他在旷野建筑瞭望楼，又挖了许多井，因为他在谢非拉和平原有很多牲畜。他在山区和肥沃的土地雇用耕种田地和修整葡萄园的人，因为他喜爱土地。","notes":[]},{"n":11,"t":"乌西雅又有军兵，照书记耶利和官长玛西雅所数点的，在王的一个将军哈拿尼雅手下，分队出战。","notes":[]},{"n":12,"t":"族长和大能勇士的总数共二千六百人，","notes":[]},{"n":13,"t":"他们手下的军兵共三十万七千五百人，都大有能力，善于作战，帮助王攻击仇敌。","notes":[]},{"n":14,"t":"乌西雅为全军预备盾牌、头盔、铠甲、枪、弓和甩石的机弦，","notes":[]},{"n":15,"t":"又在耶路撒冷叫巧匠设计机器，安在城楼和角楼上，用以射箭，投掷大石。乌西雅的名声传到远方，因为他得了非凡的帮助，极其强盛。","notes":[]},{"n":16,"t":"乌西雅既强盛，就心高气傲，以致败坏。他干犯耶和华－他的神，进耶和华的殿，要在香坛上烧香。","notes":[],"heads":["乌西雅因骄傲受惩"]},{"n":17,"t":"亚撒利雅祭司率领八十名勇敢的耶和华的祭司，跟随他进去。","notes":[]},{"n":18,"t":"他们阻止乌西雅王，对他说：“乌西雅啊，给耶和华烧香不是你的事，而是亚伦子孙的事，他们是分别为圣来烧香的祭司。你出圣殿吧！因为你犯了罪，耶和华神必不使你得尊荣。”","notes":[]},{"n":19,"t":"乌西雅发怒，手拿香炉要烧香。他在耶和华殿中香坛旁向众祭司发怒的时候，他的额头在众祭司面前忽然长出麻风。","notes":["“麻风”泛指传染性皮肤病；下同。"]},{"n":20,"t":"亚撒利雅祭司长和众祭司转向他，看哪，他的额头长出麻风，就催他离开那里；他自己也急速出去，因为耶和华降灾于他。","notes":[]},{"n":21,"t":"乌西雅王患麻风直到死的那日；他因为染上麻风，就住在隔离的行宫里，与耶和华的殿隔绝。他儿子约坦管理王的家，治理这地的百姓。","notes":[]},{"n":22,"t":"乌西雅其余的事，自始至终，亚摩斯的儿子以赛亚先知都记录下来。","notes":[]},{"n":23,"t":"乌西雅与他祖先同睡，与他祖先同葬在田间的王陵；因为人说，他是长麻风的。他的儿子约坦接续他作王。","notes":[]}]},"27":{"heading":"犹大王约坦","verses":[{"n":1,"t":"约坦登基的时候年二十五岁，在耶路撒冷作王十六年。他母亲名叫耶路沙，是撒督的女儿。","notes":[]},{"n":2,"t":"约坦行耶和华眼中看为正的事，效法他父亲乌西雅一切所行的，只是他不入耶和华的殿。百姓仍旧行败坏的事。","notes":[]},{"n":3,"t":"约坦建造耶和华殿的上门，在俄斐勒城墙上有很多建设，","notes":[]},{"n":4,"t":"又在犹大山区建造城镇，在树林中建筑营寨和瞭望楼。","notes":[]},{"n":5,"t":"约坦与亚扪人的王打仗，胜了他们。那年亚扪人向他进贡一百他连得银子，一万歌珥小麦，一万歌珥大麦；第二年、第三年亚扪人也这样做。","notes":[]},{"n":6,"t":"约坦日渐强盛，因为他在耶和华－他神面前行正道。","notes":[]},{"n":7,"t":"约坦其余的事和一切战役，以及他的行为，看哪，都写在《以色列和犹大列王记》上。","notes":[]},{"n":8,"t":"他登基的时候年二十五岁，在耶路撒冷作王十六年。","notes":[]},{"n":9,"t":"约坦与他祖先同睡，葬在大卫城，他儿子亚哈斯接续他作王。","notes":[]}]},"28":{"heading":"犹大王亚哈斯","verses":[{"n":1,"t":"亚哈斯登基的时候年二十岁，在耶路撒冷作王十六年。他不像他祖先大卫行耶和华眼中看为正的事，","notes":[]},{"n":2,"t":"却行以色列诸王的道，又铸造诸巴力的像，","notes":[]},{"n":3,"t":"照着耶和华从以色列人面前赶出的外邦人所行可憎的事，在欣嫩子谷烧香，用火焚烧他的儿女，","notes":[]},{"n":4,"t":"又在丘坛上、山冈上、各青翠树下献祭烧香。","notes":[]},{"n":5,"t":"耶和华－他的神将他交在亚兰王手里。亚兰王打败他，从他掳走了许多人，带到大马士革去。神又将他交在以色列王手里，以色列王向他大行杀戮。","notes":[]},{"n":6,"t":"利玛利的儿子比加一日之内在犹大杀了十二万人，都是勇士，因为他们离弃了耶和华－他们列祖的神。","notes":[]},{"n":7,"t":"有一个叫细基利的以法莲勇士，杀了玛西雅王子、押斯利甘宫廷总管和以利加拿宰相。","notes":[]},{"n":8,"t":"以色列人掳了他们的弟兄，连妇人带儿女共二十万，又掠取了许多财物，把这些掠物带到撒玛利亚去。","notes":[],"heads":["先知俄德"]},{"n":9,"t":"但那里有耶和华的一个先知，名叫俄德，出来迎接往撒玛利亚去的军兵，对他们说：“看哪，耶和华－你们列祖的神恼怒犹大人，将他们交在你们手里，你们竟怒气冲天，向他们大行杀戮。","notes":[]},{"n":10,"t":"如今你们又有意强逼犹大人和耶路撒冷人作你们的奴婢，你们岂不是也得罪了耶和华－你们的神吗？","notes":[]},{"n":11,"t":"现在你们当听我说，要将从你们弟兄中掳来的释放回去，因耶和华的烈怒已临到你们了。”","notes":[]},{"n":12,"t":"于是，以法莲人的几个领袖，就是约哈难的儿子亚撒利雅、米实利末的儿子比利家、沙龙的儿子耶希西家、哈得莱的儿子亚玛撒，起来拦阻从战场上回来的人，","notes":[]},{"n":13,"t":"对他们说：“你们不可把这些被掳的人带到这里，因我们已经得罪耶和华了。你们还想加增我们的罪恶过犯吗？因为我们的罪过深重，已经有烈怒临到以色列了。”","notes":[]},{"n":14,"t":"于是带兵器的人将掳来的人口和掠取的财物都留在众领袖和全会众面前。","notes":[]},{"n":15,"t":"以上提名的那些人就起来，照顾被掳的人；其中凡赤身的，就从所掠取的财物中拿出衣服和鞋来，给他们穿，又给他们吃喝，用膏抹他们；其中凡软弱的，就使他们骑驴，送到棕树城耶利哥他们弟兄那里。然后，他们就回撒玛利亚去了。","notes":[]},{"n":16,"t":"那时，亚哈斯王派人去求亚述诸王来帮助他，","notes":["“诸王”：有古卷、七十士译本和其他古译本是“王”；参王下16．7。"],"heads":["亚哈斯向亚述王求援"]},{"n":17,"t":"因为以东人又来攻击犹大，掳掠俘虏。","notes":[]},{"n":18,"t":"非利士人也来侵占谢非拉和犹大的尼革夫的城镇，攻取了伯．示麦、亚雅仑、基低罗、梭哥和所属的乡镇、亭拿和所属的乡镇、瑾锁和所属的乡镇，就住在那里。","notes":["“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”。"]},{"n":19,"t":"因为以色列王亚哈斯在犹大放肆，大大干犯耶和华，所以耶和华使犹大卑微。","notes":["“以色列”：有古卷、七十士译本和其他古译本是“犹大”。"]},{"n":20,"t":"亚述王提革拉．毗列色来攻击他，不帮助他，反倒欺负他。","notes":[]},{"n":21,"t":"亚哈斯从耶和华殿里和王宫中，以及众领袖家中取财宝送给亚述王，也无济于事。","notes":[]},{"n":22,"t":"这亚哈斯王在急难的时候，越发得罪耶和华。","notes":[],"heads":["亚哈斯的罪行"]},{"n":23,"t":"他向那攻击他的大马士革的神明献祭，说：“因为亚兰王的神明帮助他们，我也要向这些神明献祭，好让它们帮助我。”但那些神明却使他和全以色列败亡。","notes":[]},{"n":24,"t":"亚哈斯聚集神殿里的器皿，把神殿里的器皿都打碎了，并且封锁耶和华殿的门，又在耶路撒冷各处的转角为自己建筑祭坛。","notes":[]},{"n":25,"t":"他在犹大各城建立丘坛，向别神烧香，惹耶和华－他列祖的神发怒。","notes":[]},{"n":26,"t":"亚哈斯其余的事和他一切的行为，自始至终，看哪，都写在《犹大和以色列诸王记》上。","notes":[]},{"n":27,"t":"亚哈斯与他祖先同睡，葬在耶路撒冷城里，却没有送入以色列诸王的坟墓。他的儿子希西家接续他作王。","notes":[]}]},"29":{"heading":"犹大王希西家","verses":[{"n":1,"t":"希西家登基的时候年二十五岁，在耶路撒冷作王二十九年。他母亲名叫亚比雅，是撒迦利雅的女儿。","notes":["“亚比雅”：王下18．2称“亚比”。"]},{"n":2,"t":"希西家行耶和华眼中看为正的事，效法他祖先大卫一切所行的。","notes":[]},{"n":3,"t":"元年正月，他开了耶和华殿的门，重新整修。","notes":[],"heads":["洁净圣殿"]},{"n":4,"t":"他召祭司和利未人来，聚集在东边的广场，","notes":[]},{"n":5,"t":"对他们说：“利未人哪，当听我说：现在你们要将自己分别为圣，又将耶和华－你们列祖神的殿分别为圣，从圣所中除去污秽之物。","notes":[]},{"n":6,"t":"因我们的祖先犯了罪，行耶和华－我们神眼中看为恶的事，离弃他，转脸背向耶和华的居所。","notes":[]},{"n":7,"t":"他们又封锁走廊的门，吹灭灯火，不在圣所中向以色列的神烧香，或献燔祭。","notes":[]},{"n":8,"t":"耶和华的愤怒临到犹大和耶路撒冷，使他们恐惧，令人惊骇，使人嗤笑，正如你们亲眼所见的。","notes":[]},{"n":9,"t":"看哪，我们的祖宗倒在刀下，我们的妻子儿女也为此被掳掠。","notes":[]},{"n":10,"t":"现在我心中有意与耶和华－以色列的神立约，好使他的烈怒转离我们。","notes":[]},{"n":11,"t":"我的众子啊，现在不要懈怠；因为耶和华拣选你们站在他面前事奉他，作他的仆人，向他烧香。”","notes":[]},{"n":12,"t":"于是，利未人起来，当中有哥辖的子孙，亚玛赛的儿子玛哈、亚撒利雅的儿子约珥；米拉利的子孙，亚伯底的儿子基士、耶哈利勒的儿子亚撒利雅；革顺人，薪玛的儿子约亚、约亚的儿子伊甸；","notes":[]},{"n":13,"t":"以利撒反的子孙申利和耶利；亚萨的子孙，撒迦利雅和玛探雅；","notes":[]},{"n":14,"t":"希幔的子孙耶歇和示每；耶杜顿的子孙示玛雅和乌薛。","notes":[]},{"n":15,"t":"他们聚集他们的弟兄，将自己分别为圣，照着耶和华的话和王的吩咐，进去洁净耶和华的殿。","notes":[]},{"n":16,"t":"祭司进入耶和华的内殿要洁净殿，把耶和华殿中所发现一切污秽之物都搬出去，搬到耶和华殿的院子，由利未人接走，搬出去到外头的汲沦溪。","notes":[]},{"n":17,"t":"从正月初一开始分别为圣，初八就来到耶和华殿的走廊。他们又用了八日使耶和华的殿分别为圣，到正月十六日才完成。","notes":[]},{"n":18,"t":"于是，他们到里面去见希西家王，说：“我们已将耶和华的全殿和燔祭坛，以及坛的一切器皿、供饼的供桌，与供桌的一切器皿都洁净了；","notes":[]},{"n":19,"t":"并且连亚哈斯王在位犯罪的时候所废弃的器皿，我们也都预备齐全，分别为圣，看哪，它们都在耶和华的祭坛前。”","notes":[]},{"n":20,"t":"希西家王清早起来，召集城里的领袖都上耶和华的殿。","notes":[],"heads":["重新奉献圣殿"]},{"n":21,"t":"他们牵了七头公牛、七只公羊、七只羔羊、七只公山羊，要为国、为殿、为犹大作赎罪祭。王吩咐亚伦的子孙众祭司在耶和华的坛上献祭。","notes":[]},{"n":22,"t":"他们宰了公牛，祭司将血接来，洒在坛上；他们宰了公羊，把血洒在坛上，又宰了羔羊，也把血洒在坛上。","notes":[]},{"n":23,"t":"他们把那些作赎罪祭的公山羊牵到王和会众面前，按手在公山羊上。","notes":[]},{"n":24,"t":"祭司宰了羊，将血献在坛上作赎罪祭，为全以色列赎罪，因为王吩咐要为全以色列献上燔祭和赎罪祭。","notes":[]},{"n":25,"t":"王又派利未人在耶和华殿中敲钹，鼓瑟，弹琴，正如大卫和王的先见迦得，以及拿单先知所吩咐的，就是耶和华藉先知所吩咐的。","notes":[]},{"n":26,"t":"利未人拿大卫的乐器，祭司拿号，一同站立。","notes":[]},{"n":27,"t":"希西家吩咐在坛上献燔祭，开始献燔祭的时候，他们就唱赞美耶和华的歌，吹号，并用以色列王大卫的乐器伴奏。","notes":[]},{"n":28,"t":"全会众都敬拜，歌唱的歌唱，吹号的吹号，如此直到燔祭献完了。","notes":[]},{"n":29,"t":"献完了祭，王和所有在场跟随他的人都俯伏敬拜。","notes":[]},{"n":30,"t":"希西家王与众领袖吩咐利未人用大卫和亚萨先见的诗词颂赞耶和华，他们欢欢喜喜地颂赞，低头敬拜。","notes":[]},{"n":31,"t":"希西家回应说：“如今你们既承接圣职归耶和华，就要前来把祭物和感谢祭奉到耶和华的殿里。”会众就奉上祭物和感谢祭，凡甘心乐意的也奉上燔祭。","notes":[]},{"n":32,"t":"会众所奉的燔祭数目如下：七十头公牛、一百只公羊、二百只羔羊，这些全都是要作燔祭献给耶和华的；","notes":[]},{"n":33,"t":"又有分别为圣之物，就是六百头公牛、三千只绵羊。","notes":[]},{"n":34,"t":"但祭司太少，不能剥尽所有燔祭牲的皮，所以他们的弟兄利未人帮助他们，直等献祭的事完毕，直到其他的祭司也分别为圣了；因利未人以正直的心分别为圣，胜过祭司。","notes":[]},{"n":35,"t":"燔祭和平安祭牲的脂肪，以及与燔祭同献的浇酒祭很多。这样，耶和华殿中的事务俱都齐备了。","notes":[]},{"n":36,"t":"希西家和众百姓都因神为百姓所预备的而喜乐，因为这事办得很迅速。","notes":[]}]},"30":{"heading":"预备守逾越节","verses":[{"n":1,"t":"希西家派人去见以色列和犹大众人，又写信给以法莲和玛拿西人，要他们到耶路撒冷耶和华的殿，向耶和华－以色列的神守逾越节，","notes":[]},{"n":2,"t":"因为王和众领袖，以及耶路撒冷全会众已经商议，要在二月份守逾越节。","notes":[]},{"n":3,"t":"那时他们不能守，因为分别为圣的祭司不够，百姓也还没有聚集在耶路撒冷。","notes":[]},{"n":4,"t":"这事在王与全会众眼中都看为合宜。","notes":[]},{"n":5,"t":"于是他们下令，通告全以色列，从别是巴直到但，吩咐百姓都来，在耶路撒冷向耶和华－以色列的神守逾越节，因为他们已经许久没有照所写的守这节了。","notes":["“他们已经...守这节了”或译“照所写的条例守这节的人已经不多了”。"]},{"n":6,"t":"信差遵着王命，拿着王和众领袖所发的信，送达全以色列和犹大，说：“以色列人哪，当转向耶和华－亚伯拉罕、以撒、以色列的神，好叫他转向你们这些脱离亚述诸王之手的余民。","notes":[]},{"n":7,"t":"不要效法你们的祖先和你们的弟兄；他们干犯耶和华－他们列祖的神，以致耶和华使他们令人惊骇，正如你们所见的。","notes":[]},{"n":8,"t":"现在，不要像你们祖先硬着颈项，只要归顺耶和华，进入他的圣所，就是永远成圣的居所，又要事奉耶和华－你们的神，好使他的烈怒转离你们。","notes":[]},{"n":9,"t":"你们若转向耶和华，你们的弟兄和儿女必在掳掠他们的人面前蒙怜悯，得以归回这地，因为耶和华－你们的神有恩惠，有怜悯。你们若转向他，他必不会转脸不顾你们。”","notes":[]},{"n":10,"t":"信差从这城跑到那城，传遍了以法莲和玛拿西之地，直到西布伦；那里的人却戏笑他们，讥诮他们。","notes":[]},{"n":11,"t":"然而亚设、玛拿西、西布伦中也有人谦卑自己，来到耶路撒冷。","notes":[]},{"n":12,"t":"神也按手在犹大人身上，使他们一心遵行王与众领袖照着耶和华的话所发的命令。","notes":[]},{"n":13,"t":"二月时，许多百姓聚集在耶路撒冷，成为一个盛大的会，要守除酵节。","notes":[],"heads":["守逾越节"]},{"n":14,"t":"他们起来，把耶路撒冷的祭坛和烧香的坛尽都除去，扔在汲沦溪中。","notes":[]},{"n":15,"t":"二月十四日，他们宰了逾越节的羔羊。祭司与利未人觉得惭愧，就使自己分别为圣，把燔祭奉到耶和华的殿中。","notes":[]},{"n":16,"t":"他们遵照神人摩西的律法，按定例站在自己的地方；祭司从利未人手里接过血来，洒出去。","notes":[]},{"n":17,"t":"会众中有许多人尚未分别为圣，所以利未人为所有不洁的人宰逾越节的羔羊，使他们归耶和华为圣。","notes":[]},{"n":18,"t":"从以法莲、玛拿西、以萨迦、西布伦来的许多百姓尚未自洁，他们却吃逾越节的羔羊，不合所写的条例。希西家为他们祷告说：“求至善的耶和华饶恕","notes":[]},{"n":19,"t":"那凡专心寻求神耶和华－他列祖的神，却未照圣所洁净礼自洁的人。”","notes":[]},{"n":20,"t":"耶和华应允希西家，医治了百姓。","notes":[]},{"n":21,"t":"在耶路撒冷的以色列人守除酵节七日，大大喜乐。利未人和祭司为耶和华演奏响亮的乐器，天天颂赞耶和华。","notes":[]},{"n":22,"t":"希西家慰劳所有精通礼仪，事奉耶和华的利未人。于是众人吃节期的筵席七日，又献平安祭，并且称谢耶和华－他们列祖的神。","notes":[]},{"n":23,"t":"全会众商议，要再守节七日；于是他们欢欢喜喜地又守节七日。","notes":[],"heads":["再度守节"]},{"n":24,"t":"犹大王希西家赐给会众一千头公牛、七千只羊；众领袖也赐给会众一千头公牛、一万只羊，并有许多祭司将自己分别为圣。","notes":[]},{"n":25,"t":"犹大全会众、祭司、利未人和从以色列来的全会众，以及那些从以色列地来的和住在犹大的寄居的人，尽都喜乐。","notes":[]},{"n":26,"t":"这样，在耶路撒冷大有喜乐，因自从以色列王大卫的儿子所罗门以来，在耶路撒冷从未有过这样的喜乐。","notes":[]},{"n":27,"t":"那时，祭司和利未人起来，为百姓祝福。他们的声音蒙神垂听，他们的祷告达到他天上的圣所。","notes":[]}]},"31":{"heading":"希西家的改革","verses":[{"n":1,"t":"这一切事都完毕以后，在那里的以色列众人就到犹大的城镇，打碎柱像，砍断亚舍拉，又在犹大、便雅悯、以法莲、玛拿西遍地把丘坛和祭坛完全拆毁。于是以色列众人各回各城，各归自己产业的地去了。","notes":[]},{"n":2,"t":"希西家分派祭司和利未人的班次，使祭司和利未人照各自的班次，按各自的职分献燔祭和平安祭，又在耶和华殿的门内事奉，称谢颂赞耶和华。","notes":["“殿”：原文是“营”。"]},{"n":3,"t":"王又从自己的产业中分出一份来作燔祭，就是早晚的燔祭，和安息日、初一，以及节期的燔祭，都是按耶和华律法上所记载的。","notes":[]},{"n":4,"t":"他又吩咐住耶路撒冷的百姓将祭司和利未人所应得的份给他们，使他们坚守耶和华的律法。","notes":[]},{"n":5,"t":"命令一出，以色列人就把初熟的五谷、新酒、新油、蜜和田地的出产多多送来；他们把各样出产的十分之一大量送来。","notes":[]},{"n":6,"t":"住犹大各城的以色列人和犹大人也将牛羊的十分之一，以及分别为圣归耶和华－他们神之物，就是十分取一之物，尽都送来，积成一堆一堆；","notes":[]},{"n":7,"t":"他们从三月开始堆积，到七月才完成。","notes":[]},{"n":8,"t":"希西家和众领袖来，看见这些堆积物，就称颂耶和华，又为耶和华的百姓以色列祝福。","notes":[]},{"n":9,"t":"希西家向祭司和利未人查问这些堆积物。","notes":[]},{"n":10,"t":"撒督家的亚撒利雅祭司长告诉他说：“自从礼物开始送到耶和华的殿以来，我们不但吃饱，而且剩下的很多；因为耶和华赐福给他的百姓，所剩下的才这样丰盛。”","notes":[]},{"n":11,"t":"希西家吩咐要在耶和华殿里预备仓房，他们就预备了。","notes":[]},{"n":12,"t":"他们诚心将礼物，十分取一之物，就是分别为圣之物，都搬入仓内。利未人歌楠雅主管这事，他的兄弟示每是副主管。","notes":[]},{"n":13,"t":"耶歇、亚撒细雅、拿哈、亚撒黑、耶利摩、约撒拔、以列、伊斯玛基雅、玛哈、比拿雅都是督办，在歌楠雅和他兄弟示每的手下，是希西家王和管理神殿的亚撒利雅所委派的。","notes":[]},{"n":14,"t":"守东门的利未人音拿的儿子可利，掌管献给神的甘心祭，发放献给耶和华的礼物和至圣的物。","notes":[]},{"n":15,"t":"在祭司的各城里，在他手下忠心协助他的有伊甸、珉雅珉、耶书亚、示玛雅、亚玛利雅、示迦尼雅，都按着班次分给他们的弟兄，无论大小，","notes":[]},{"n":16,"t":"不论是否登录在家谱，凡三岁以上的男丁，每日进耶和华殿、按班次供职事奉的，都分给他，","notes":[]},{"n":17,"t":"也发放给按父家登录在家谱的祭司；又按班次职任分给二十岁以上的利未人，","notes":[]},{"n":18,"t":"又按家谱的登记，分给他们的小孩、妻子、儿女，给全体会众；因为他们忠诚，将自己分别为圣。","notes":[]},{"n":19,"t":"住在各城郊野亚伦的子孙、按名受委任的人，要把应得的份给祭司中所有的男丁和载入家谱的利未人。","notes":[]},{"n":20,"t":"希西家在全犹大都这样办理，在耶和华－他神面前行良善、正直、忠诚的事。","notes":[]},{"n":21,"t":"凡他所行的，无论是开始办神殿的事，是遵律法守诫命，是寻求他的神，他都尽心去做，无不亨通。","notes":[]}]},"32":{"heading":"亚述人恐吓耶路撒冷","verses":[{"n":1,"t":"在这些虔诚的事以后，亚述王西拿基立来侵犯犹大，围困坚固城，想要攻破它们。","notes":[]},{"n":2,"t":"希西家见西拿基立来，定意要攻打耶路撒冷，","notes":[]},{"n":3,"t":"就与领袖和勇士商议，塞住城外的泉源；他们都帮助他。","notes":[]},{"n":4,"t":"于是许多百姓聚集，塞住一切泉源，以及国中流通的小河，说：“亚述诸王来，为何让他们得着许多水呢？”","notes":[]},{"n":5,"t":"希西家奋勇自强，修筑所有毁坏的城墙，升高城楼，又在城外筑另一片城墙，坚固大卫城的米罗，制造许多兵器和盾牌。","notes":["“米罗”是音译，指“土堆的防御工事”。"]},{"n":6,"t":"他设立军事将领管理百姓，召集他们在城门的广场，勉励他们，说：","notes":[]},{"n":7,"t":"“你们当刚强壮胆，不要因亚述王和跟随他的大军恐惧惊慌，因为与我们同在的，比与他们同在的更大。","notes":[]},{"n":8,"t":"与他们同在的是血肉之臂，但与我们同在的是耶和华－我们的神，他必帮助我们，为我们争战。”百姓因犹大王希西家的话就得到鼓励。","notes":[]},{"n":9,"t":"此后，亚述王西拿基立和跟随他的全军攻打拉吉，派臣仆到耶路撒冷见犹大王希西家和所有在耶路撒冷的犹大人，说：","notes":[]},{"n":10,"t":"“亚述王西拿基立如此说：‘你们倚靠什么，还留在耶路撒冷受困吗？","notes":[]},{"n":11,"t":"希西家说：耶和华－我们的神必救我们脱离亚述王的手，这不是诱惑你们，使你们受饥渴而死吗？","notes":[]},{"n":12,"t":"希西家岂不是将耶和华的丘坛和祭坛废去，并且吩咐犹大与耶路撒冷的人说：你们当在一个坛前敬拜，在其上烧香吗？","notes":[]},{"n":13,"t":"我与我祖先向列邦民族所行的，你们岂不知道吗？列邦的神明何尝能救自己的国脱离我的手呢？","notes":[]},{"n":14,"t":"我祖先所灭的那些国的神明，有谁能救自己的百姓脱离我的手呢？难道你们的神能救你们脱离我的手吗？","notes":[]},{"n":15,"t":"现在，不要让希西家这样欺骗你们，诱惑你们，也不要相信他，因为没有一国一邦的神明能救自己的百姓脱离我的手和我祖先的手，你们的神也绝不能救你们脱离我的手。’”","notes":[]},{"n":16,"t":"西拿基立的臣仆还说了一些话来毁谤耶和华神和他的仆人希西家。","notes":[]},{"n":17,"t":"西拿基立也写信毁谤耶和华－以色列的神，说：“列邦的神明既不能救自己的百姓脱离我的手，希西家的神也不能救他的百姓脱离我的手。”","notes":[]},{"n":18,"t":"亚述王的臣仆用犹大话向耶路撒冷城墙上的百姓大声呼喊，要恐吓他们，扰乱他们，以便取城。","notes":[]},{"n":19,"t":"他们谈论耶路撒冷的神，如同谈论世上人手所造的神明一样。","notes":[]},{"n":20,"t":"希西家王和亚摩斯的儿子以赛亚先知为此祷告，向天呼求。","notes":[]},{"n":21,"t":"耶和华就差遣一个使者进入亚述王的营中，把所有大能的勇士、官长和将领尽都灭了。亚述王满面羞愧地回到本国，进了他神明的庙中，他几个亲生的儿子在那里用刀杀了他。","notes":[]},{"n":22,"t":"这样，耶和华救希西家和耶路撒冷的居民脱离亚述王西拿基立的手，也脱离一切仇敌的手，又赐他们四境平安。","notes":["“赐他们四境平安”是根据七十士译本和其他古译本；原文是“在四境引导他们”。"]},{"n":23,"t":"有许多人到耶路撒冷将供物献与耶和华，又将宝物送给犹大王希西家。自此之后，希西家在列国人的眼中受人尊崇。","notes":[]},{"n":24,"t":"那些日子，希西家病得要死，就向耶和华祷告，耶和华应允他，赐他一个预兆。","notes":[],"heads":["希西家的疾病和骄傲"]},{"n":25,"t":"希西家却没有照他所蒙的恩回报，因他心里骄傲，所以愤怒要临到他，临到犹大和耶路撒冷。","notes":[]},{"n":26,"t":"但希西家和耶路撒冷的居民为了心里骄傲，就一同谦卑，以致耶和华的愤怒在希西家的日子没有临到他们。","notes":[]},{"n":27,"t":"希西家大有财富和尊荣，他为自己建造府库，收藏金银、宝石、香料、盾牌和各样的宝器，","notes":[],"heads":["希西家的财富和尊荣"]},{"n":28,"t":"又建造仓房，收藏五谷、新酒和新的油，又为各类牲畜盖棚立圈，","notes":[]},{"n":29,"t":"并且为自己建立城镇，也拥有许多的羊群牛群，因为神赐他极多的财产。","notes":[]},{"n":30,"t":"这希西家也塞住基训的上源，引水直下，流在大卫城的西边。希西家所行的事尽都亨通。","notes":[]},{"n":31,"t":"但当巴比伦诸侯差遣使者来见希西家，询问国中所发生的奇事时，神离开他，要考验他，好知道他心里的一切。","notes":[]},{"n":32,"t":"希西家其余的事和他的善行，看哪，都写在亚摩斯的儿子以赛亚先知的《默示书》上和《犹大和以色列诸王记》上。","notes":[],"heads":["希西家逝世"]},{"n":33,"t":"希西家与他祖先同睡，葬在大卫子孙陵墓的斜坡上。他死的时候，犹大众人和耶路撒冷的居民都向他致敬。他的儿子玛拿西接续他作王。","notes":[]}]},"33":{"heading":"犹大王玛拿西","verses":[{"n":1,"t":"玛拿西登基的时候年十二岁，在耶路撒冷作王五十五年。","notes":[]},{"n":2,"t":"他行耶和华眼中看为恶的事，效法耶和华在以色列人面前赶出的列国那些可憎的事。","notes":[]},{"n":3,"t":"他重新建筑他父亲希西家所拆毁的丘坛，为诸巴力筑坛，造亚舍拉，又敬拜天上的万象，事奉它们。","notes":[]},{"n":4,"t":"他在耶和华殿中筑坛，耶和华曾指着这殿说：“我的名必永远在耶路撒冷。”","notes":[]},{"n":5,"t":"他在耶和华殿的两个院子为天上的万象筑坛，","notes":[]},{"n":6,"t":"并在欣嫩子谷使他的儿子经火，又观星象，行法术，行邪术，求问招魂的和行巫术的，多行耶和华眼中看为恶的事，惹他发怒。","notes":[]},{"n":7,"t":"他在神殿内立雕刻的偶像；神曾对大卫和他儿子所罗门说：“我在以色列众支派中所选择的耶路撒冷和这殿，必立我的名，直到永远。","notes":[]},{"n":8,"t":"只要以色列人谨守遵行我藉摩西吩咐他们的一切律法、律例、典章，我就不再使他们的脚挪移，离开我所赐给他们列祖之土地。”","notes":[]},{"n":9,"t":"玛拿西引诱犹大和耶路撒冷的居民行恶，比耶和华在以色列人面前所灭的列国更严重。","notes":[]},{"n":10,"t":"耶和华警戒玛拿西和他的百姓，他们却不听。","notes":[],"heads":["玛拿西悔改"]},{"n":11,"t":"所以耶和华使亚述王的将领来攻击他们，用手铐铐住玛拿西，用铜链锁住他，把他带到巴比伦去。","notes":[]},{"n":12,"t":"他在急难的时候恳求耶和华－他的神，并在他列祖的神面前极其谦卑。","notes":[]},{"n":13,"t":"他祈祷耶和华，耶和华就应允他，垂听他的祷告，使他归回耶路撒冷，仍坐王位。玛拿西这才知道惟独耶和华是神。","notes":[]},{"n":14,"t":"此后，玛拿西在大卫城外，从谷内基训西边直到鱼门口，建筑城墙，环绕俄斐勒；这墙建得很高。他又在犹大各坚固城内设立将领。","notes":[]},{"n":15,"t":"他除掉外邦人的神像与耶和华殿中的偶像，又将他在耶和华殿的山上和耶路撒冷所筑的各坛都拆毁，抛在城外。","notes":[]},{"n":16,"t":"他重修耶和华的祭坛，在坛上献平安祭和感谢祭，并吩咐犹大人事奉耶和华－以色列的神。","notes":[]},{"n":17,"t":"百姓却仍在丘坛上献祭，不过，他们只献给耶和华－他们的神。","notes":[]},{"n":18,"t":"玛拿西其余的事和他向神的祷告，以及先见奉耶和华－以色列神的名警戒他的话，看哪，都在《以色列诸王记》上。","notes":[],"heads":["玛拿西逝世"]},{"n":19,"t":"他的祷告，神怎样应允他，他未谦卑以前的一切罪愆过犯，以及在何处建筑丘坛，设立亚舍拉和雕刻的偶像，看哪，都写在何赛的书上。","notes":["“何赛”意思是“我的先见”。"]},{"n":20,"t":"玛拿西与他祖先同睡，葬在自己的宫中，他儿子亚们接续他作王。","notes":[]},{"n":21,"t":"亚们登基的时候年二十二岁，在耶路撒冷作王二年。","notes":[],"heads":["犹大王亚们"]},{"n":22,"t":"他行耶和华眼中看为恶的事，效法他父亲玛拿西所行的，祭祀他父亲玛拿西所雕刻的一切偶像，事奉它们，","notes":[]},{"n":23,"t":"但他不像他父亲玛拿西在耶和华面前那样谦卑下来。这亚们的罪越犯越大。","notes":[]},{"n":24,"t":"他的臣仆背叛他，在宫里杀了他。","notes":[]},{"n":25,"t":"但这地的百姓杀了所有背叛亚们王的人；这地的百姓立他儿子约西亚接续他作王。","notes":[]}]},"34":{"heading":"犹大王约西亚","verses":[{"n":1,"t":"约西亚登基的时候年八岁，在耶路撒冷作王三十一年。","notes":[]},{"n":2,"t":"他行耶和华眼中看为正的事，行他祖先大卫所行的道，不偏左右。","notes":[]},{"n":3,"t":"他作王第八年，尚且年轻，就寻求他祖先大卫的神。到了十二年，他开始洁净犹大和耶路撒冷，除掉丘坛、亚舍拉、雕刻的像和铸造的像。","notes":[]},{"n":4,"t":"众人在他面前拆毁诸巴力的坛，砍断坛上高高的香坛，又把亚舍拉和雕刻的像，以及铸造的像打碎成灰，撒在向偶像献祭之人的坟上，","notes":[]},{"n":5,"t":"把祭司的骸骨烧在他们的坛上，洁净了犹大和耶路撒冷。","notes":[]},{"n":6,"t":"他又在玛拿西、以法莲、西缅、拿弗他利各城和四围的废墟，","notes":["“和四围的废墟”：原文另译“查访他们的屋子”。"]},{"n":7,"t":"拆毁祭坛，把亚舍拉和雕刻的像打碎成灰，砍断以色列全地所有的香坛。于是他回耶路撒冷去了。","notes":[]},{"n":8,"t":"约西亚王十八年，这地和殿洁净了之后，他派亚萨利雅的儿子沙番、玛西雅市长、约哈斯的儿子约亚史官去整修耶和华－他神的殿。","notes":[],"heads":["发现律法书"]},{"n":9,"t":"他们去见希勒家大祭司，把奉到神殿的银子交给他；这银子是看守殿门的利未人从玛拿西、以法莲，和以色列所有幸存的人，以及犹大、便雅悯众人和耶路撒冷的居民收来的。","notes":[]},{"n":10,"t":"他们把这银子交给耶和华殿里督工的，由他们转交整修耶和华殿的工匠，","notes":[]},{"n":11,"t":"就是交给木匠和石匠，好为犹大王所毁坏的殿，买凿成的石头和作钩子与栋梁的木料。","notes":[]},{"n":12,"t":"这些人办事诚实，管理他们的是利未人米拉利的子孙雅哈和俄巴底，又有哥辖人撒迦利亚和米书兰；还有所有善于奏乐的利未人。","notes":[]},{"n":13,"t":"他们监督扛抬的人，督导一切做各样工的人。利未人中也有作书记、官员、守卫的。","notes":[]},{"n":14,"t":"他们把奉到耶和华殿的银子运出来的时候，希勒家祭司发现了耶和华藉摩西所传的律法书。","notes":[]},{"n":15,"t":"希勒家对沙番书记说：“我在耶和华殿里发现了律法书。”希勒家把书递给沙番。","notes":[]},{"n":16,"t":"沙番把书拿到王那里，又把这事回覆王说：“凡交给仆人的手所办的事，他们都办好了。","notes":[]},{"n":17,"t":"耶和华殿里所发现的银子已经倒出来，交在督工和工匠的手里了。”","notes":[]},{"n":18,"t":"沙番书记又向王报告说：“希勒家祭司递给我一卷书。”沙番就在王面前朗读那书。","notes":[]},{"n":19,"t":"王听见律法的话，就撕裂衣服。","notes":[]},{"n":20,"t":"王吩咐希勒家与沙番的儿子亚希甘、米迦的儿子亚比顿、沙番书记和王的臣仆亚撒雅，说：","notes":["“米迦”是“米该亚”的小名；参王下22．12。","“亚比顿”：王下22．12称“亚革波”。"]},{"n":21,"t":"“你们去，以所发现这书上的话，为我、为以色列和犹大幸存的人求问耶和华；因为我们的祖先没有遵守耶和华的话，没有照这书上所记的一切去做，耶和华的烈怒就倒在我们身上。”","notes":[]},{"n":22,"t":"于是，希勒家和王的人都去见户勒大女先知，她是掌管礼服的沙龙的妻子，沙龙是哈斯拉的孙子，特瓦的儿子。户勒大住在耶路撒冷第二区。他们向她说明来意。","notes":["“王的人”：有古卷和古译本是“王所派的人”。"]},{"n":23,"t":"她对他们说：“耶和华－以色列的神如此说：‘你们可以回覆那派你们来见我的人说，","notes":[]},{"n":24,"t":"耶和华如此说：看哪，我必照着在犹大王面前所读那书上记载的一切诅咒，降祸于这地方和其上的居民。","notes":[]},{"n":25,"t":"因为他们离弃我，向别神烧香，用他们手所做的一切惹我发怒，所以我的愤怒必倒在这地方，总不止息。’","notes":[]},{"n":26,"t":"然而，派你们来求问耶和华的犹大王，你们要这样回覆他：‘耶和华－以色列的神如此说：至于你所听见的话，","notes":[]},{"n":27,"t":"就是听见我指着这地方和其上居民所说的话，你的心就软化，在我面前谦卑下来，撕裂衣服，向我哭泣，因此我应允你。这是耶和华说的。","notes":[]},{"n":28,"t":"看哪，我必使你归到你祖先那里，平安地进入坟墓，我要降于这地方和其上居民的一切灾祸，你不会亲眼看见。’”他们就去把这话回覆王。","notes":[]},{"n":29,"t":"王派人召集犹大和耶路撒冷的众长老来。","notes":[],"heads":["约西亚立约顺从主"]},{"n":30,"t":"王和犹大众人、耶路撒冷的居民、祭司、利未人，以及所有的百姓，无论大小，都一同上到耶和华的殿去；王把殿里所发现的约书上面一切的话读给他们听。","notes":[]},{"n":31,"t":"王站在自己的位上，在耶和华面前立约，要尽心尽性跟从耶和华，遵守他的诫命、法度、律例，实行这书上所记这约的话；","notes":[]},{"n":32,"t":"又使所有住耶路撒冷和便雅悯的人都服从这约。于是耶路撒冷的居民都遵行神，就是他们列祖之神的约。","notes":[]},{"n":33,"t":"约西亚从以色列各处把一切可憎之物尽都除掉，使以色列境内的人都事奉耶和华－他们的神。约西亚在世的日子，众人都跟从耶和华－他们列祖的神，总不离开。","notes":[]}]},"35":{"heading":"约西亚守逾越节","verses":[{"n":1,"t":"约西亚在耶路撒冷向耶和华守逾越节。正月十四日，他们宰了逾越节的羔羊。","notes":[]},{"n":2,"t":"王分派祭司各尽其职，又勉励他们办耶和华殿中的事。","notes":[]},{"n":3,"t":"他对那归耶和华为圣、教导以色列众人的利未人说：“你们将圣约柜安放在以色列王大卫儿子所罗门建造的殿里，不必再用肩扛抬。现在你们要服事耶和华－你们的神和他的百姓以色列。","notes":[]},{"n":4,"t":"你们应当按着父家，照着班次，遵照以色列王大卫和他儿子所罗门所写的，预备自己。","notes":[]},{"n":5,"t":"要按着你们百姓的弟兄、父家的班次，侍立在圣所；每父家的班次中要有几个利未人。","notes":[]},{"n":6,"t":"要宰逾越节的羔羊，将自己分别为圣，为你们的弟兄预备，好遵守耶和华藉摩西所吩咐的话。”","notes":[]},{"n":7,"t":"约西亚从群畜中赐给所有在场的百姓，三万只小绵羊和小山羊，三千头牛，作逾越节的祭物；这些都是出自王的产业。","notes":[]},{"n":8,"t":"约西亚的众领袖也乐意把祭牲给百姓、祭司和利未人；管理神殿的希勒家、撒迦利亚、耶歇，把二千六百只羔羊和三百头牛给祭司作逾越节的祭物。","notes":[]},{"n":9,"t":"利未人的族长歌楠雅和他两个兄弟示玛雅、拿坦业，与哈沙比雅、耶利、约撒拔，把五千只羔羊和五百头牛给利未人作逾越节的祭物。","notes":[]},{"n":10,"t":"这样，事奉的工作都安排好了，照王所吩咐的，祭司站在自己的位上，利未人按着班次侍立。","notes":[]},{"n":11,"t":"他们宰了逾越节的羔羊，祭司从他们手里接过血来洒出去；利未人剥皮，","notes":["原文没有“接过血来”。"]},{"n":12,"t":"把燔祭拿走，再按着父家的班次分给众百姓，照摩西书上所写的献给耶和华；献牛也是这样。","notes":[]},{"n":13,"t":"他们按着常例，用火烤逾越节的羔羊。至于其他的圣物，他们用盆，用锅，用釜煮了，速速地送给众百姓。","notes":[]},{"n":14,"t":"然后他们为自己和祭司预备祭物，因为作祭司的亚伦子孙献燔祭和脂肪，直到晚上。所以利未人为自己和作祭司的亚伦子孙预备。","notes":[]},{"n":15,"t":"歌唱的亚萨子孙，照着大卫、亚萨、希幔和王的先见耶杜顿所吩咐的，站在自己的位上。守门的看守各门，不用离开他们的职守，因为他们的弟兄利未人给他们预备。","notes":[]},{"n":16,"t":"当日，一切供奉耶和华、守逾越节，以及在耶和华坛上献燔祭的事，都照约西亚王的吩咐预备好了。","notes":[]},{"n":17,"t":"那时，在场的以色列人都守逾越节，又守除酵节七日。","notes":[]},{"n":18,"t":"自从撒母耳先知的日子以来，在以色列中没有守过这样的逾越节，以色列诸王也没有守过像约西亚、祭司、利未人、所有住犹大和以色列的人，以及耶路撒冷居民所守的逾越节。","notes":[]},{"n":19,"t":"这逾越节是约西亚作王十八年时守的。","notes":[]},{"n":20,"t":"约西亚为殿做完这一切事以后，埃及王尼哥上来，要攻打靠近幼发拉底河的迦基米施；约西亚出去迎击他。","notes":[],"heads":["约西亚逝世"]},{"n":21,"t":"他派使者来见约西亚，说：“犹大王啊，我跟你有什么相干呢？我今日来不是要攻打你，而是要攻打与我争战之家，并且神吩咐我从速行事。你不要干预与我同在的神，免得他毁灭你。”","notes":[]},{"n":22,"t":"约西亚却不转脸离开他，反而改装要与他打仗。他不听从神藉尼哥的口所说的话，就来到米吉多平原争战。","notes":[]},{"n":23,"t":"弓箭手射中约西亚王。王对他的臣仆说：“我受了重伤，你们载我离开战场吧！”","notes":[]},{"n":24,"t":"他的臣仆扶他下了战车，上了他的副座车，送他到耶路撒冷。他就死了，葬在他祖先的坟墓里。全犹大和耶路撒冷都哀悼约西亚。","notes":[]},{"n":25,"t":"耶利米为约西亚作哀歌，所有歌唱的男女也唱哀歌，追悼约西亚，直到今日。他们在以色列中以此为定例；看哪，这些哀歌写在《哀歌书》上。","notes":[]},{"n":26,"t":"约西亚其余的事和他遵照耶和华律法上所记而行的善事，","notes":[]},{"n":27,"t":"以及他自始至终所行的，看哪，都写在《以色列和犹大列王记》上。","notes":[]}]},"36":{"heading":"犹大王约哈斯","verses":[{"n":1,"t":"这地的百姓立约西亚的儿子约哈斯在耶路撒冷接续他父亲作王。","notes":[]},{"n":2,"t":"约哈斯登基的时候年二十三岁，在耶路撒冷作王三个月。","notes":[]},{"n":3,"t":"埃及王在耶路撒冷废了他，又罚这地一百他连得银子，一他连得金子。","notes":[]},{"n":4,"t":"埃及王尼哥立约哈斯的哥哥以利雅敬作犹大和耶路撒冷的王，给他改名叫约雅敬。尼哥却将他的弟弟约哈斯带到埃及去。","notes":[]},{"n":5,"t":"约雅敬登基的时候年二十五岁，在耶路撒冷作王十一年。他行耶和华－他神眼中看为恶的事。","notes":[],"heads":["犹大王约雅敬"]},{"n":6,"t":"巴比伦王尼布甲尼撒上来攻击他，用铜链锁着他，要把他带到巴比伦去。","notes":[]},{"n":7,"t":"尼布甲尼撒又将耶和华殿里的一些器皿带到巴比伦，放在巴比伦自己的宫里。","notes":["“自己的宫里”或译“他的庙里”。"]},{"n":8,"t":"约雅敬其余的事和他所行可憎的事，以及发生在他身上的事，看哪，都写在《以色列和犹大列王记》上，他儿子约雅斤接续他作王。","notes":[]},{"n":9,"t":"约雅斤登基的时候年八岁，在耶路撒冷作王三个月十天，他行耶和华眼中看为恶的事。","notes":["“八岁”：王下24．8是“十八岁”。"],"heads":["犹大王约雅斤"]},{"n":10,"t":"过了一年，尼布甲尼撒王差遣人将约雅斤和耶和华殿里宝贵的器皿带到巴比伦，然后立约雅斤的叔父西底家作犹大和耶路撒冷的王。","notes":["“叔父”：原文是“兄弟”。"]},{"n":11,"t":"西底家登基的时候年二十一岁，在耶路撒冷作王十一年。","notes":[],"heads":["犹大王西底家"]},{"n":12,"t":"他行耶和华－他神眼中看为恶的事，没有谦卑听从耶利米先知所传达耶和华的话。","notes":[]},{"n":13,"t":"尼布甲尼撒王曾叫他指着神起誓，他却背叛，硬着颈项，内心顽固，不归向耶和华－以色列的神。","notes":[]},{"n":14,"t":"众祭司长和百姓也多多犯罪，效法列国一切可憎的事，玷污耶和华在耶路撒冷分别为圣的殿。","notes":[]},{"n":15,"t":"耶和华－他们列祖的神因为爱惜自己的百姓和居所，一再差遣使者去警戒他们。","notes":[]},{"n":16,"t":"他们却嘲笑神的使者，藐视他的话，讥诮他的先知，以致耶和华向他的百姓大发烈怒，甚至无法可救。","notes":[]},{"n":17,"t":"所以，耶和华使迦勒底人的王来攻击他们，在他们圣殿里用刀杀了他们的壮丁，不怜悯他们的少男少女、老人长者。耶和华把所有的人都交在他手里。","notes":[]},{"n":18,"t":"他把神殿里一切的大小器皿与耶和华殿里的财宝，以及王和众领袖的财宝，全都带到巴比伦去。","notes":[]},{"n":19,"t":"迦勒底人焚烧了神的殿，拆毁耶路撒冷的城墙，用火烧了城里所有的宫殿，毁坏了城里一切宝贵的器皿。","notes":[]},{"n":20,"t":"凡脱离刀剑的幸存者，迦勒底王都掳到巴比伦去，作他和他子孙的仆婢，直到波斯国兴起。","notes":[]},{"n":21,"t":"这就应验耶和华藉耶利米的口所说的话：地得享安息；在荒凉的日子，地就守安息，直到满了七十年。","notes":[]},{"n":22,"t":"波斯王居鲁士元年，耶和华为要应验藉耶利米的口所说的话，就激发波斯王居鲁士的心，使他下诏书通告全国，说：","notes":[],"heads":["犹大人返国"]},{"n":23,"t":"“波斯王居鲁士如此说：耶和华－天上的神已将地上万国赐给我，又委派我在犹大的耶路撒冷为他建造殿宇。你们中间凡作他子民的可以上去，愿耶和华－他的神与他同在。”","notes":[]}]}},"EZR":{"1":{"heading":"居鲁士下令犹太人返国","verses":[{"n":1,"t":"波斯王居鲁士元年，耶和华为要应验藉耶利米的口所说的话，就激发波斯王居鲁士的心，使他下诏书通告全国，说：","notes":[]},{"n":2,"t":"“波斯王居鲁士如此说：耶和华天上的神已将地上万国赐给我，又委派我在犹大的耶路撒冷为他建造殿宇。","notes":[]},{"n":3,"t":"你们中间凡作他子民的，可以上犹大的耶路撒冷去，重建耶和华－以色列神的殿，他是在耶路撒冷的神；愿神与这人同在。","notes":[]},{"n":4,"t":"凡存留的人，无论寄居何处，那地的人要用金银、财物、牲畜帮助他，还要为耶路撒冷神的殿甘心献上礼物。”","notes":[]},{"n":5,"t":"于是，犹大和便雅悯的族长、祭司、利未人，凡是心被神感动的人都起来，要上耶路撒冷去建造耶和华的殿。","notes":[]},{"n":6,"t":"四围所有的人都拿银器、金子、财物、牲畜、珍宝支持他们，此外还有甘心献的一切礼物。","notes":["“银器”：原文另译“一切的东西，银子”。","“支持他们”：原文是“坚固他们的手”。","“此外还有甘心献的一切礼物”：原文另译“甘心献的礼物很多”。"]},{"n":7,"t":"居鲁士王也把耶和华殿的器皿拿出来，这些器皿是尼布甲尼撒从耶路撒冷掠取，放在自己神明庙中的。","notes":[]},{"n":8,"t":"波斯王居鲁士派米提利达司库把这些器皿拿出来，点交给犹大的领袖设巴萨。","notes":[]},{"n":9,"t":"它们的数目如下：金盘三十个，银盘一千个，刀二十九把，","notes":[]},{"n":10,"t":"金碗三十个，备用银碗四百一十个，其他器皿一千件。","notes":[]},{"n":11,"t":"金银器皿共有五千四百件。被掳的人从巴比伦上耶路撒冷的时候，设巴萨把这一切都带了上来。","notes":[]}]},"2":{"heading":"被掳归回者的名单","verses":[{"n":1,"t":"这些是从被掳之地上来的省民，巴比伦王尼布甲尼撒把他们掳到巴比伦，他们重返耶路撒冷和犹大，各归本城。","notes":[]},{"n":2,"t":"他们是同所罗巴伯、耶书亚、尼希米、西莱雅、利来雅、末底改、必珊、米斯拔、比革瓦伊、利宏、巴拿一起回来的。以色列百姓的人数如下：","notes":[]},{"n":3,"t":"巴录的子孙二千一百七十二名；","notes":[]},{"n":4,"t":"示法提雅的子孙三百七十二名；","notes":[]},{"n":5,"t":"亚拉的子孙七百七十五名；","notes":[]},{"n":6,"t":"巴哈．摩押的后裔，就是耶书亚和约押的子孙二千八百一十二名；","notes":[]},{"n":7,"t":"以拦的子孙一千二百五十四名；","notes":[]},{"n":8,"t":"萨土的子孙九百四十五名；","notes":[]},{"n":9,"t":"萨改的子孙七百六十名；","notes":[]},{"n":10,"t":"巴尼的子孙六百四十二名；","notes":[]},{"n":11,"t":"比拜的子孙六百二十三名；","notes":[]},{"n":12,"t":"押甲的子孙一千二百二十二名；","notes":[]},{"n":13,"t":"亚多尼干的子孙六百六十六名；","notes":[]},{"n":14,"t":"比革瓦伊的子孙二千零五十六名；","notes":[]},{"n":15,"t":"亚丁的子孙四百五十四名；","notes":[]},{"n":16,"t":"亚特的后裔，就是希西家的子孙九十八名；","notes":[]},{"n":17,"t":"比赛的子孙三百二十三名；","notes":[]},{"n":18,"t":"约拉的子孙一百一十二名；","notes":[]},{"n":19,"t":"哈顺的子孙二百二十三名；","notes":[]},{"n":20,"t":"吉罢珥人九十五名；","notes":[]},{"n":21,"t":"伯利恒人一百二十三名；","notes":[]},{"n":22,"t":"尼陀法人五十六名；","notes":[]},{"n":23,"t":"亚拿突人一百二十八名；","notes":[]},{"n":24,"t":"亚斯玛弗人四十二名；","notes":[]},{"n":25,"t":"基列．耶琳人、基非拉人、比录人共七百四十三名；","notes":[]},{"n":26,"t":"拉玛人和迦巴人共六百二十一名；","notes":[]},{"n":27,"t":"默玛人一百二十二名；","notes":[]},{"n":28,"t":"伯特利人和艾人共二百二十三名；","notes":[]},{"n":29,"t":"尼波人五十二名；","notes":[]},{"n":30,"t":"末必人一百五十六名；","notes":[]},{"n":31,"t":"另一个以拦的子孙一千二百五十四名；","notes":[]},{"n":32,"t":"哈琳的子孙三百二十名；","notes":[]},{"n":33,"t":"罗德人、哈第人、阿挪人共七百二十五名；","notes":[]},{"n":34,"t":"耶利哥人三百四十五名；","notes":[]},{"n":35,"t":"西拿人三千六百三十名。","notes":[]},{"n":36,"t":"祭司：耶书亚家耶大雅的子孙九百七十三名；","notes":[]},{"n":37,"t":"音麦的子孙一千零五十二名；","notes":[]},{"n":38,"t":"巴施户珥的子孙一千二百四十七名；","notes":[]},{"n":39,"t":"哈琳的子孙一千零一十七名。","notes":[]},{"n":40,"t":"利未人：何达威雅的后裔，就是耶书亚和甲篾的子孙七十四名。","notes":[]},{"n":41,"t":"歌唱的：亚萨的子孙一百二十八名。","notes":[]},{"n":42,"t":"门口的守卫：沙龙的子孙、亚特的子孙、达们的子孙、亚谷的子孙、哈底大的子孙、朔拜的子孙，共一百三十九名。","notes":[]},{"n":43,"t":"殿役：西哈的子孙、哈苏巴的子孙、答巴俄的子孙、","notes":[]},{"n":44,"t":"基绿的子孙、西亚的子孙、巴顿的子孙、","notes":[]},{"n":45,"t":"利巴拿的子孙、哈迦巴的子孙、亚谷的子孙、","notes":[]},{"n":46,"t":"哈甲的子孙、萨买的子孙、哈难的子孙、","notes":[]},{"n":47,"t":"吉德的子孙、迦哈的子孙、利亚雅的子孙、","notes":[]},{"n":48,"t":"利汛的子孙、尼哥大的子孙、迦散的子孙、","notes":[]},{"n":49,"t":"乌撒的子孙、巴西亚的子孙、比赛的子孙、","notes":[]},{"n":50,"t":"押拿的子孙、米乌宁的子孙、尼普心的子孙、","notes":[]},{"n":51,"t":"巴卜的子孙、哈古巴的子孙、哈忽的子孙、","notes":[]},{"n":52,"t":"巴洗律的子孙、米希大的子孙、哈沙的子孙、","notes":[]},{"n":53,"t":"巴柯的子孙、西西拉的子孙、答玛的子孙、","notes":[]},{"n":54,"t":"尼细亚的子孙、哈提法的子孙。","notes":[]},{"n":55,"t":"所罗门仆人的后裔：琐太的子孙、琐斐列的子孙、比路大的子孙、","notes":[]},{"n":56,"t":"雅拉的子孙、达昆的子孙、吉德的子孙、","notes":[]},{"n":57,"t":"示法提雅的子孙、哈替的子孙、玻黑列．哈斯巴音的子孙、亚米的子孙。","notes":[]},{"n":58,"t":"殿役和所罗门仆人的后裔共三百九十二名。","notes":[]},{"n":59,"t":"从特．米拉、特．哈萨、基绿、亚顿、音麦上来，不能证明他们的父系家族和后裔是否属以色列的如下：","notes":[]},{"n":60,"t":"第莱雅的子孙、多比雅的子孙、尼哥大的子孙，共六百五十二名。","notes":[]},{"n":61,"t":"祭司中，哈巴雅的子孙、哈哥斯的子孙、巴西莱的子孙，巴西莱因为娶了基列人巴西莱的女儿为妻，所以就以此为名。","notes":[]},{"n":62,"t":"这些人在族谱之中寻查自己的谱系，却寻不着，因此算为不洁，不得作祭司。","notes":[]},{"n":63,"t":"省长对他们说，不可吃至圣的物，直到有会用乌陵和土明的祭司兴起来。","notes":[]},{"n":64,"t":"全会众共有四万二千三百六十名。","notes":[]},{"n":65,"t":"此外，还有他们的仆婢七千三百三十七名，又有歌唱的男女二百名。","notes":[]},{"n":66,"t":"他们有七百三十六匹马，二百四十五匹骡子，","notes":[]},{"n":67,"t":"四百三十五匹骆驼，六千七百二十匹驴。","notes":[]},{"n":68,"t":"有些族长到了耶路撒冷耶和华的殿，为神的殿甘心献上礼物，要在原有的根基上重新建造。","notes":[]},{"n":69,"t":"他们量力捐入工程的库房，有六万一千达利克金子，五千弥那银子，以及一百件祭司的礼服。","notes":["“达利克”：古波斯金币；参“度量衡表”；8．27同。"]},{"n":70,"t":"于是祭司、利未人、百姓中的一些人、歌唱的、门口的守卫、殿役，各住在自己的城里；以色列众人都住在自己的城里。","notes":[]}]},"3":{"heading":"恢复敬拜神的生活","verses":[{"n":1,"t":"到了七月，以色列人住在自己的城里；那时他们如同一人，聚集在耶路撒冷。","notes":[]},{"n":2,"t":"约萨达的儿子耶书亚和他的弟兄众祭司，以及撒拉铁的儿子所罗巴伯和他的弟兄，都起来建筑以色列神的坛，要照神人摩西律法书上所写的，在坛上献燔祭。","notes":[]},{"n":3,"t":"他们在原有的根基上筑坛，因为他们惧怕邻邦民族，又在其上向耶和华早晚献燔祭，","notes":[]},{"n":4,"t":"并照律法书上所写的守住棚节，按数照例每日献所当献的燔祭。","notes":[]},{"n":5,"t":"此后，他们献常献的燔祭，并在初一和耶和华一切分别为圣的节期献祭，又向耶和华献各人的甘心祭。","notes":[]},{"n":6,"t":"从七月初一起，虽然耶和华殿的根基尚未立定，他们开始向耶和华献燔祭。","notes":[]},{"n":7,"t":"他们把银子给石匠、木匠，把粮食、酒、油给西顿人、推罗人，好将香柏树从黎巴嫩浮海运到约帕，是照波斯王居鲁士所允准他们的。","notes":[]},{"n":8,"t":"他们到了耶路撒冷神殿的第二年，二月的时候，撒拉铁的儿子所罗巴伯，约萨达的儿子耶书亚和其余的弟兄，就是祭司和利未人，以及所有被掳归回耶路撒冷的人，就开工建造；他们派二十岁以上的利未人，监督建造耶和华殿的工作。","notes":[],"heads":["重建圣殿"]},{"n":9,"t":"于是何达威雅的后裔，就是耶书亚和他的子孙与弟兄、甲篾和他的子孙，他们和利未人希拿达的子孙与弟兄，都起来如同一人，监督那些在神殿里做工的人。","notes":["“何达威雅”：原文是“犹大”；参2．40。"]},{"n":10,"t":"工匠立耶和华殿根基的时候，祭司穿礼服吹号，利未人亚萨的子孙敲钹，都照以色列王大卫亲手所定的，站着赞美耶和华。","notes":[]},{"n":11,"t":"他们彼此唱和，赞美称谢耶和华：“他本为善，他向以色列永施慈爱。”他们赞美耶和华的时候，众百姓大声呼喊，因为耶和华殿的根基已经立定。","notes":[]},{"n":12,"t":"然而有许多祭司、利未人和族长，就是见过先前那殿的老年人，现在亲眼看见这殿立了根基，就大声哭号，也有许多人大声欢呼，","notes":[]},{"n":13,"t":"百姓不能分辨欢呼的声音或哭号的声音，因为百姓大声呼喊，声音连远处都可听到。","notes":[]}]},"4":{"heading":"建殿之工受阻","verses":[{"n":1,"t":"犹大和便雅悯的敌人听说被掳归回的人为耶和华－以色列的神建造殿宇，","notes":[]},{"n":2,"t":"就去见所罗巴伯和族长，对他们说：“请让我们与你们一同建造，因为我们也与你们一样寻求你们的神。自从亚述王以撒．哈顿带我们上这地的日子以来，我们常向神献祭。”","notes":[]},{"n":3,"t":"但所罗巴伯、耶书亚和其余以色列的族长对他们说：“我们建造神的殿与你们无关，因为我们要照波斯王居鲁士所吩咐的，自己为耶和华－以色列的神协力建造。”","notes":[]},{"n":4,"t":"那地的人就在犹大百姓建造的时候，使他们的手发软，扰乱他们。","notes":[]},{"n":5,"t":"从波斯王居鲁士年间，直到波斯王大流士在位的时候，那些人贿赂谋士，要破坏他们的计划。","notes":[]},{"n":6,"t":"亚哈随鲁在位，他的国度刚开始的时候，他们上书控告犹大和耶路撒冷的居民。","notes":[],"heads":["阻挠重建耶路撒冷"]},{"n":7,"t":"亚达薛西年间，比施兰、米特利达、他别和他们的同僚上书奏告波斯王亚达薛西。奏文是用亚兰文写的，以亚兰文呈上。","notes":["“他们”：原文是“他”。"]},{"n":8,"t":"利宏省长、伸帅书记也上奏亚达薛西王，控告耶路撒冷如下","notes":["从 4．8－6．18，以及7．12－26，原文是亚兰文。"]},{"n":9,"t":"（那时，利宏省长、伸帅书记和他们其余的同僚，法官、官员、军官、波斯官员、亚基卫人、巴比伦人，和书珊迦人，就是以拦人，","notes":["“法官、官员、军官、波斯官员”：原文音译“底拿人、亚法萨提迦人、他毗拉人、亚法撒人”。","“就是以拦人”：原文另译“底亥人、以拦人”。"]},{"n":10,"t":"以及被亚斯那巴大人迁移、安置在撒玛利亚城和大河西边一带地方其余的人。现在 ，","notes":[]},{"n":11,"t":"这是他们上奏亚达薛西王奏文的抄本）：“河西的臣仆上奏亚达薛西王，现在","notes":[]},{"n":12,"t":"请王知道，从王那里上到我们这里的犹太人，已经抵达耶路撒冷。他们正在重建这反叛恶劣的城，已经完成了城墙，正要修复根基。","notes":[]},{"n":13,"t":"如今请王知道，这城若再建造，城墙完工，他们就不再进贡、纳粮、缴税，王的国库必受亏损。","notes":[]},{"n":14,"t":"如今，我们吃的盐既然全是宫廷的盐，就不忍见王吃亏，因此奏告于王，","notes":[]},{"n":15,"t":"请王考察先王史籍，必会在史籍上查知这城是反叛的城，对列王和各省有害；自古以来，城中常有悖逆的事，因此这城曾被拆毁。","notes":[]},{"n":16,"t":"我们谨奏王知，这城若再建造，城墙完工，河西之地王就无份了。”","notes":[]},{"n":17,"t":"那时王谕覆利宏省长、伸帅书记和他们其余的同僚，就是住撒玛利亚和河西一带地方的人，说：“愿你们平安。现在","notes":[]},{"n":18,"t":"你们所呈给我们的奏本，已经清楚地在我面前读了。","notes":[]},{"n":19,"t":"我已下令考查，得知这城自古以来果然背叛列王，其中常有反叛悖逆的事。","notes":[]},{"n":20,"t":"也曾有强大的君王治理耶路撒冷，统管河西全地，人就给他们进贡、纳粮、缴税。","notes":[]},{"n":21,"t":"现在你们要下令叫这些人停工，使这城不得建造，等到我再降旨。","notes":[]},{"n":22,"t":"你们当谨慎办这事，不可迟延，何必让损害加重，使王受亏损呢？”","notes":[]},{"n":23,"t":"亚达薛西王上谕的抄本在利宏和伸帅书记，以及他们的同僚面前宣读，他们就急忙往耶路撒冷去见犹太人，用势力和强权叫他们停工。","notes":[]},{"n":24,"t":"于是，在耶路撒冷神殿的工程就停止了，直停到波斯王大流士第二年。","notes":[],"heads":["恢复重建圣殿工作"]}]},"5":{"heading":"","verses":[{"n":1,"t":"那时，哈该先知和易多的孙子撒迦利亚，两个先知奉以色列神的名向犹大和耶路撒冷的犹太人说预言。","notes":[]},{"n":2,"t":"于是撒拉铁的儿子所罗巴伯和约萨达的儿子耶书亚起来，开始建造耶路撒冷神的殿，有神的先知在那里帮助他们。","notes":[]},{"n":3,"t":"当时河西的达乃总督和示他．波斯乃，以及他们的同僚来对犹太人这样说：“谁降旨让你们建造这殿，完成这建筑呢？”","notes":[]},{"n":4,"t":"于是我们告诉他们建造这建筑物的人叫什么名字。","notes":[]},{"n":5,"t":"但神的眼目看顾犹太人的长老，以致没有人叫他们停工，直到奏文上告大流士，得着他对这事的回谕。","notes":[]},{"n":6,"t":"这是河西的达乃总督和示他．波斯乃，以及他们的同僚，就是住河西的官员，上书奏告大流士王的抄本，","notes":["“官员”：原文音译“亚法萨迦人”；6．6同。"]},{"n":7,"t":"他们上书给王的奏文，其中写着：“愿大流士王诸事平安。","notes":[]},{"n":8,"t":"请王知道，我们往犹大省去，到了至大神的殿。这殿是用凿成的石头建造的，梁木插入墙内。这项工程进行迅速，在他们手中顺利。","notes":[]},{"n":9,"t":"于是我们问那些长老，对他们这样说：‘谁降旨让你们建造这殿，完成这建筑呢？’","notes":[]},{"n":10,"t":"我们又问他们的名字，要记下他们领袖的名字，奏告于王。","notes":[]},{"n":11,"t":"他们这样回答我们说：‘我们是天和地之神的仆人，重建多年前所建造的殿，就是以色列一位伟大的君王建造完成的。","notes":[]},{"n":12,"t":"但因我们祖先惹天上的神发怒，神把他们交在迦勒底人巴比伦王尼布甲尼撒的手中，他就拆毁这殿，又把百姓掳到巴比伦。","notes":[]},{"n":13,"t":"然而巴比伦王居鲁士元年，他降旨允准建造神的这殿。","notes":[]},{"n":14,"t":"神殿中的金银器皿，就是尼布甲尼撒从耶路撒冷殿中掠取带到巴比伦庙里的，居鲁士王从巴比伦庙里取出来，交给派为省长，名叫设巴萨的，","notes":[]},{"n":15,"t":"对他说：可以将这些器皿带去，放在耶路撒冷的殿中，在原处建造神的殿。","notes":[]},{"n":16,"t":"于是那位设巴萨来建立耶路撒冷神殿的根基。但从那时直到如今，这殿尚未修建完毕。’","notes":[]},{"n":17,"t":"现在，王若以为好，请查阅巴比伦王的档案库，看居鲁士王有没有降旨允准在耶路撒冷建造神的殿。请降旨指示我们王对这件事的心意。”","notes":[]}]},"6":{"heading":"发现居鲁士王的诏令","verses":[{"n":1,"t":"于是大流士王降旨，要寻察典籍库，就是在巴比伦藏档案之处；","notes":[]},{"n":2,"t":"在玛代省亚马他城的宫内寻得一卷，其中这样写着，“记录如下：","notes":[]},{"n":3,"t":"居鲁士王元年，王降旨论到在耶路撒冷神的殿，要建造这殿作为献祭之处，坚固它的根基。殿高六十肘，宽六十肘，","notes":[]},{"n":4,"t":"要用三层凿成的石头，一层木头，经费可出于王的库房。","notes":["“一层木头”：有古卷是“一层新木头”。"]},{"n":5,"t":"至于神殿的金银器皿，就是尼布甲尼撒从耶路撒冷的殿中掠取带到巴比伦的，必须归还，带回耶路撒冷的殿中，各按原处放在神的殿里。”","notes":[]},{"n":6,"t":"“现在，河西的达乃总督和示他．波斯乃，以及他们的同僚，就是住河西的官员，你们当远离那里。","notes":[],"heads":["大流士王下令继续建殿"]},{"n":7,"t":"不要拦阻这神殿的工作，任由犹太人的省长和长老在原处建造神的这殿。","notes":[]},{"n":8,"t":"我又降旨，吩咐你们为建造神的殿当向犹太人的长老这样行：从王的财产中，由河西所缴纳的贡银，迅速支付这些人，免得工程停顿。","notes":[]},{"n":9,"t":"他们向天上的神献燔祭所需用的公牛犊、公绵羊、小绵羊，以及麦子、盐、酒、油，都要照耶路撒冷祭司的话，每日供给他们，不得有误；","notes":[]},{"n":10,"t":"好叫他们献馨香的祭给天上的神，又为王和王众子的寿命祈祷。","notes":[]},{"n":11,"t":"我再降旨，无论谁更改这命令，必从他房屋中拆出一根梁木，把他举起，悬在其上，又使他的房屋为此成为粪堆。","notes":[]},{"n":12,"t":"任何王或百姓若伸手更改这命令，拆毁在耶路撒冷神的这殿，愿那立他名在那里的神将他们灭绝。我大流士降这谕旨，你们要速速遵行。”","notes":[]},{"n":13,"t":"于是，河西的达乃总督和示他．波斯乃，以及他们的同僚，急速遵行大流士王所颁的命令。","notes":[],"heads":["圣殿奉献礼"]},{"n":14,"t":"犹太人的长老因哈该先知和易多的孙子撒迦利亚的预言，就建造这殿，凡事顺利。他们遵照以色列神的命令和波斯王居鲁士、大流士、亚达薛西的谕旨，建造完毕。","notes":[]},{"n":15,"t":"大流士王第六年，亚达月初三，这殿完工了。","notes":[]},{"n":16,"t":"以色列人、祭司和利未人，以及其余被掳归回的人都欢欢喜喜地为神的这殿行奉献礼。","notes":[]},{"n":17,"t":"他们为这神殿的奉献礼献了一百头公牛、二百只公绵羊、四百只小绵羊，又照以色列支派的数目献十二只公山羊，作以色列众人的赎罪祭。","notes":[]},{"n":18,"t":"他们派祭司按着班次，利未人也按着班次在耶路撒冷事奉神，正如摩西律法书上所写的。","notes":[]},{"n":19,"t":"正月十四日，被掳归回的人守逾越节。","notes":[],"heads":["守逾越节"]},{"n":20,"t":"祭司和利未人一同自洁，他们全都洁净了。利未人为被掳归回的众人和他们的弟兄众祭司，并为自己宰逾越节的羔羊。","notes":[]},{"n":21,"t":"从被掳之地归回的以色列人，并所有归附他们、除掉这地外邦人的污秽、寻求耶和华－以色列神的人，都吃这羔羊。","notes":[]},{"n":22,"t":"他们欢欢喜喜地守除酵节七日，因为耶和华使他们欢喜。耶和华又使亚述王的心转向他们，坚固他们的手，去做神－以色列神殿的工。","notes":[]}]},"7":{"heading":"以斯拉到达耶路撒冷","verses":[{"n":1,"t":"这些事以后，波斯王亚达薛西在位的时候，有个人叫以斯拉，他是西莱雅的儿子，西莱雅是亚撒利雅的儿子，亚撒利雅是希勒家的儿子，","notes":[]},{"n":2,"t":"希勒家是沙龙的儿子，沙龙是撒督的儿子，撒督是亚希突的儿子，","notes":[]},{"n":3,"t":"亚希突是亚玛利雅的儿子，亚玛利雅是亚撒利雅的儿子，亚撒利雅是米拉约的儿子，","notes":[]},{"n":4,"t":"米拉约是西拉希雅的儿子，西拉希雅是乌西的儿子，乌西是布基的儿子，","notes":[]},{"n":5,"t":"布基是亚比书的儿子，亚比书是非尼哈的儿子，非尼哈是以利亚撒的儿子，以利亚撒是亚伦大祭司的儿子。","notes":[]},{"n":6,"t":"这以斯拉从巴比伦上来，他是一个文士，精通耶和华－以色列神所赐摩西的律法。王允准他一切所求的，因为耶和华－他神的手帮助他。","notes":[]},{"n":7,"t":"亚达薛西王第七年，有些以色列人、一些祭司、利未人、歌唱的、门口的守卫、殿役，上耶路撒冷去。","notes":[]},{"n":8,"t":"王第七年五月，以斯拉到了耶路撒冷。","notes":[]},{"n":9,"t":"正月初一，他从巴比伦起程，五月初一就到了耶路撒冷，因为他神施恩的手帮助他。","notes":[]},{"n":10,"t":"以斯拉立志考究遵行耶和华的律法，又将律例典章教导以色列人。","notes":[]},{"n":11,"t":"亚达薛西王赐给精通耶和华诫命和以色列律例的文士以斯拉祭司的谕旨，抄本如下：","notes":[],"heads":["亚达薛西王给以斯拉的文件"]},{"n":12,"t":"“诸王之王亚达薛西，达于精通天上之神律法的以斯拉祭司文士等等：现在","notes":[]},{"n":13,"t":"住在我国中的以色列百姓、祭司、利未人，凡愿意上耶路撒冷去的，我降旨准他们与你同去。","notes":[]},{"n":14,"t":"既然王与七个谋士派你去，照你手中神的律法视察犹大和耶路撒冷的景况；","notes":[]},{"n":15,"t":"你又带着王和谋士乐意献给住耶路撒冷、以色列神的金银，","notes":[]},{"n":16,"t":"和你在巴比伦全省所得的一切金银，以及百姓、祭司甘心献给耶路撒冷他们神殿的礼物，","notes":[]},{"n":17,"t":"那么，你就当用这银子急速买公牛、公绵羊、小绵羊，和同献的素祭、浇酒祭，献在耶路撒冷你们神殿的坛上。","notes":[]},{"n":18,"t":"剩下的金银，你和你的弟兄看怎样好，就怎样用，但总要遵照你们神的旨意。","notes":[]},{"n":19,"t":"你要带着交托给你、在神殿中事奉用的器皿，到耶路撒冷神面前。","notes":[]},{"n":20,"t":"你神殿里若再有需用的经费，是你负责供应的，可以从王的宝库里支取。","notes":[]},{"n":21,"t":"“我亚达薛西王又降旨达于河西所有的司库：‘精通天上之神律法的以斯拉祭司文士无论向你们要什么，你们要速速办理，","notes":[]},{"n":22,"t":"直至一百他连得银子，一百柯珥麦子，一百罢特酒，一百罢特油，盐不限其数。","notes":["“柯珥”：亚兰文音译，即希伯来固体容量单位“歌珥”；参“度量衡表”。"]},{"n":23,"t":"凡天上之神所吩咐的，当为天上之神的殿切实办理。何必使愤怒临到王和王众子的国呢？","notes":[]},{"n":24,"t":"我再吩咐你们：至于任何祭司、利未人、歌唱的、门口的守卫和殿役，以及在神的这殿事奉的人，不可要求他们进贡，纳粮，缴税。’","notes":[]},{"n":25,"t":"“你，以斯拉啊，要照着你神赐你的智慧，指派所有明白你神律法的人作官长、审判官，治理河西所有的百姓，教导不明白神律法的人。","notes":[]},{"n":26,"t":"凡不遵行你神律法和王命令的人，当速速定他的罪，或处死，或充军，或抄家，或囚禁。”","notes":[]},{"n":27,"t":"以斯拉说：“耶和华－我们列祖的神是应当称颂的！因他使王起这心愿，使耶路撒冷耶和华的殿得荣耀，","notes":[],"heads":["以斯拉称颂耶和华"]},{"n":28,"t":"他又在王和谋士，以及王所有大能的军官面前施恩于我。我因耶和华－我神的手的帮助，得以坚强，从以色列中召集领袖，与我一同上来。”","notes":[]}]},"8":{"heading":"从被掳之地回来的人","verses":[{"n":1,"t":"这些是亚达薛西王在位的时候，同我从巴比伦上来的族长和他们的家谱：","notes":[]},{"n":2,"t":"属非尼哈的子孙有革顺；属以他玛的子孙有但以理；属大卫的子孙有哈突；","notes":[]},{"n":3,"t":"属示迦尼的子孙；属巴录的子孙有撒迦利亚，同着他按家谱计算，男丁一百五十人；","notes":[]},{"n":4,"t":"属巴哈．摩押的子孙有西拉希雅的儿子以利约乃，同着他有男丁二百人；","notes":[]},{"n":5,"t":"属萨土的子孙有雅哈悉的儿子示迦尼，同着他有男丁三百人；","notes":["“属萨土<ins>.示迦尼”是根据七十士译本；原文是“属示迦尼的子孙有雅哈悉的儿子”。"]},{"n":6,"t":"属亚丁的子孙有约拿单的儿子以别，同着他有男丁五十人；","notes":[]},{"n":7,"t":"属以拦的子孙有亚他利雅的儿子耶筛亚，同着他有男丁七十人；","notes":[]},{"n":8,"t":"属示法提雅的子孙有米迦勒的儿子西巴第雅，同着他有男丁八十人；","notes":[]},{"n":9,"t":"属约押的子孙有耶歇的儿子俄巴底亚，同着他有男丁二百一十八人；","notes":[]},{"n":10,"t":"属巴尼的子孙有约细斐的儿子示罗密，同着他有男丁一百六十人；","notes":["“属巴尼</ins>.示罗密”是根据七十士译本；原文是“属示罗密的子孙有约细斐的儿子”。"]},{"n":11,"t":"属比拜的子孙有比拜的儿子撒迦利亚，同着他有男丁二十八人；","notes":[]},{"n":12,"t":"属押甲的子孙有哈加坦的儿子约哈难，同着他有男丁一百一十人；","notes":[]},{"n":13,"t":"属亚多尼干的子孙，就是晚到的，他们的名字是以利法列、耶利、示玛雅，同着他们有男丁六十人；","notes":[]},{"n":14,"t":"属比革瓦伊的子孙有乌太和撒刻，同着他们有男丁七十人。","notes":["“撒刻”：原文另译“撒布”。"]},{"n":15,"t":"我召集这些人在流入亚哈瓦的河旁边，我们在那里扎营三日。我查看百姓和祭司，发现并没有利未人在那里，","notes":[],"heads":["以斯拉召集利未人"]},{"n":16,"t":"就派人到以利以谢、亚列、示玛雅、以利拿单、雅立、以利拿单、拿单、撒迦利亚、米书兰等领袖，以及约雅立和以利拿单教师那里。","notes":["七十士译本的一些抄本没有“约雅立和以利拿单”。"]},{"n":17,"t":"我吩咐他们往迦西斐雅地方去见那里的领袖易多，又告诉他们当向易多和他的弟兄，就是迦西斐雅那地方的殿役说什么话，好为我们神的殿带事奉的人来。","notes":[]},{"n":18,"t":"蒙我们神施恩的手帮助我们，他们在以色列的曾孙，利未的孙子，抹利的后裔中带了一个精明的人来，就是示利比，还有他的众子与兄弟共十八人。","notes":[]},{"n":19,"t":"另外，还有哈沙比雅，同着他有米拉利的子孙耶筛亚，以及他的众子和兄弟共二十人。","notes":[]},{"n":20,"t":"从前大卫和众领袖派殿役服事利未人，现在从这殿役中也带了二百二十人来，全都是按名指定的。","notes":[]},{"n":21,"t":"那时，我在亚哈瓦河边宣告禁食，为要在我们神面前刻苦己心，求他使我们和我们的孩子，以及一切所有的，都得平坦的道路。","notes":[],"heads":["以斯拉禁食祷告"]},{"n":22,"t":"我以求王拨步兵骑兵帮助我们抵挡路上的仇敌为羞愧，因我们曾对王说：“我们神施恩的手必帮助凡寻求他的，但他的能力和愤怒必攻击凡离弃他的。”","notes":[]},{"n":23,"t":"我们为此禁食祈求我们的神，他就应允我们。","notes":[]},{"n":24,"t":"我分派十二位祭司长，就是示利比、哈沙比雅和与他们一起的兄弟十人，","notes":[],"heads":["献给圣殿的礼物"]},{"n":25,"t":"把王和谋士、军官，并在那里的以色列众人为我们神殿所献的金银和器皿，都秤了交给他们。","notes":[]},{"n":26,"t":"我秤了交在他们手中的有六百五十他连得银子，一百他连得银器，一百他连得金子，","notes":[]},{"n":27,"t":"二十个金碗，值一千达利克，上等光亮的铜器皿两个，珍贵如金。","notes":[]},{"n":28,"t":"我对他们说：“你们归耶和华为圣，器皿也归为圣；金银是甘心献给耶和华－你们列祖之神的。","notes":[]},{"n":29,"t":"你们要警醒看守，直到你们在祭司长和利未族长，以及以色列的各族长面前，在耶路撒冷耶和华殿的库房内，把这些过了秤。”","notes":[]},{"n":30,"t":"于是，祭司和利未人把秤过的金银和器皿接过来，要带到耶路撒冷我们神的殿里。","notes":[]},{"n":31,"t":"正月十二日，我们从亚哈瓦河边起行，要往耶路撒冷去。我们神的手保佑我们，救我们脱离仇敌和路上埋伏之人的手。","notes":[],"heads":["返回耶路撒冷"]},{"n":32,"t":"我们到了耶路撒冷，在那里住了三日。","notes":[]},{"n":33,"t":"第四日，金银和器皿都在我们神的殿里过了秤，交在乌利亚的儿子米利末祭司的手中。同着他的有非尼哈的儿子以利亚撒，还有利未人耶书亚的儿子约撒拔和宾内的儿子挪亚底。","notes":[]},{"n":34,"t":"那时，这一切都点过秤过了，重量全写在册上。","notes":[]},{"n":35,"t":"从被掳之地归回的人向以色列的神献燔祭，为以色列众人献十二头公牛、九十六只公绵羊、七十七只小绵羊，又献十二只公山羊作赎罪祭，这些全都是献给耶和华的燔祭。","notes":[]},{"n":36,"t":"被掳归回的人把王的谕旨交给王的总督与河西的省长，他们就支助百姓和神的殿。","notes":[]}]},"9":{"heading":"谴责跟异族通婚","verses":[{"n":1,"t":"这些事完成以后，众领袖来接近我，说：“以色列百姓、祭司和利未人没有弃绝迦南人、赫人、比利洗人、耶布斯人、亚扪人、摩押人、埃及人和亚摩利人等列邦民族所行可憎的事。","notes":[]},{"n":2,"t":"因他们为自己和儿子娶了这些外邦女子，以致圣洁的种子和列邦民族混杂，而且领袖和官长在这事上是罪魁。”","notes":[]},{"n":3,"t":"我一听见这事，就撕裂衣服和外袍，拔了头发和胡须，惊惶地坐着。","notes":[]},{"n":4,"t":"凡为以色列神言语战兢的人，都因被掳归回之人所犯的罪，聚集到我这里来。我惊惶地坐着，直到献晚祭的时候。","notes":[]},{"n":5,"t":"献晚祭的时候我从愁烦中起来，穿着撕裂的衣服和外袍，双膝跪下，向耶和华－我的神举手，","notes":[]},{"n":6,"t":"说：“我的神啊，我抱愧蒙羞，不敢向你－我的神仰面，因为我们的罪孽多到灭顶，我们的罪恶滔天。","notes":[]},{"n":7,"t":"从我们祖先的日子直到今日，我们的罪恶深重；因我们的罪孽，我们和君王、祭司都交在邻国诸王的手中，被杀害，掳掠，抢夺，脸上蒙羞，正如今日的景况。","notes":[]},{"n":8,"t":"现在耶和华－我们的神暂且向我们施恩，为我们留下一些残存之民，使我们如钉子钉在他的圣所，好让我们的神光照我们的眼目，使我们在受辖制之中稍微复兴。","notes":[]},{"n":9,"t":"我们是奴仆，然而在受辖制之中，我们的神没有丢弃我们，在波斯诸王面前向我们施恩，叫我们复兴，能重建我们神的殿，修补毁坏之处，使我们在犹大和耶路撒冷有城墙。","notes":[]},{"n":10,"t":"“我们的神啊，既然如此，现在我们还有什么话可说呢？因为我们离弃了你的诫命，","notes":[]},{"n":11,"t":"就是你藉你仆人众先知所吩咐的，说：‘你们要去得为业之地是污秽之地，因列邦民族的污秽和可憎的事，叫这地从这边到那边都充满了污秽。","notes":[]},{"n":12,"t":"现在，不可把你们的女儿嫁给他们的儿子，也不可为你们的儿子娶他们的女儿，永不可求他们的平安和他们的利益，这样你们就可以强盛，吃这地的美物，并把这地留给你们的子孙永远为业。’","notes":[]},{"n":13,"t":"我们因自己的恶行和大罪，遭遇这一切的事，但你－我们的神惩罚我们轻于我们罪所当得的，又为我们留下这些残存之民。","notes":[]},{"n":14,"t":"我们岂可再违背你的诫命，与行这些可憎之事的民族结亲呢？若我们这样行，你岂不向我们发怒，将我们灭绝，以致没有一个余民或残存之民吗？","notes":[]},{"n":15,"t":"耶和华－以色列的神啊，你是公义的，我们才能剩下这些残存之民，正如今日的景况。看哪，我们在你面前有罪恶，因此无人能在你面前站立得住。”","notes":[]}]},"10":{"heading":"终止与异族通婚的措施","verses":[{"n":1,"t":"以斯拉祷告，认罪，哭泣，俯伏在神殿前的时候，有以色列中的男女和孩童聚集到以斯拉那里，成了一个盛大的会，百姓无不痛哭。","notes":[]},{"n":2,"t":"以拦的子孙，耶歇的儿子示迦尼对以斯拉说：“我们娶了这地的外邦女子，干犯了我们的神，然而现在以色列人在这事上还有指望。","notes":[]},{"n":3,"t":"现在，我们要与我们的神立约，送走所有的妻子和她们所生的，照着主和那些因我们神诫命战兢之人所议定的，按律法去行。","notes":[]},{"n":4,"t":"起来，这是你当办的事，我们必支持你，你当奋勇而行。”","notes":[]},{"n":5,"t":"以斯拉就起来，叫祭司长和利未人，以及以色列众人起誓，要照这话去做；他们就起了誓。","notes":[]},{"n":6,"t":"以斯拉从神殿前起来，进入以利亚实的儿子约哈难的屋里，到了那里不吃饭，也不喝水，为被掳归回之人所犯的罪悲伤。","notes":[]},{"n":7,"t":"他们通告犹大和耶路撒冷，叫所有被掳归回的人聚集在耶路撒冷。","notes":[]},{"n":8,"t":"凡不遵照领袖和长老所议定，三日之内不来的，就必毁坏他所有的财产，把他从被掳归回之人的会中开除。","notes":[]},{"n":9,"t":"于是，犹大和便雅悯众人三日之内都聚集在耶路撒冷。那时是九月，那月的二十日，众百姓坐在神殿前的广场，因这事，又因下大雨，就都战抖。","notes":[]},{"n":10,"t":"以斯拉祭司站起来，对他们说：“你们有罪了，因为你们娶了外邦女子，增添以色列的罪恶。","notes":[]},{"n":11,"t":"现在当向耶和华－你们列祖的神认罪，遵行他的旨意，离开这地的百姓和外邦女子。”","notes":[]},{"n":12,"t":"全会众大声回答说：“好！我们必照着你的话去做。","notes":[]},{"n":13,"t":"只是百姓众多，又逢大雨的季节，我们没有气力站在外面；这也不是一两天可以办完的事，因我们在这事上犯了大罪。","notes":[]},{"n":14,"t":"让我们的领袖代表全会众留在那里。我们城镇中凡娶外邦女子的，当按所定的日期，会同本城的长老和审判官前来，直到办完这事，神的烈怒转离我们。”","notes":["“直到...转离我们”：有些古卷和七十士译本是“直到神因这事的烈怒转离我们”。"]},{"n":15,"t":"惟有亚撒黑的儿子约拿单，特瓦的儿子雅哈谢反对这事，并有米书兰和利未人沙比太支持他们。","notes":[]},{"n":16,"t":"被掳归回的人就如此做了。以斯拉祭司按着父家指名选派一些族长。十月初一，他们一同坐下来查办这事，","notes":["“以斯拉...族长”是根据七十士译本的一些抄本和其他古译本；原文是“选出来的有以斯拉祭司、一些人和按着父家所有指名的族长。”"]},{"n":17,"t":"到正月初一，才查清所有娶外邦女子的人数。","notes":[]},{"n":18,"t":"在祭司中查出娶外邦女子的：耶书亚的子孙中，有约萨达的儿子，和他兄弟玛西雅、以利以谢、雅立、基大利，","notes":[],"heads":["娶外邦女子的人"]},{"n":19,"t":"他们承诺要送走他们的妻子。他们因有罪，就献羊群中的一只公绵羊赎罪；","notes":[]},{"n":20,"t":"音麦的子孙中，有哈拿尼、西巴第雅；","notes":[]},{"n":21,"t":"哈琳的子孙中，有玛西雅、以利雅、示玛雅、耶歇、乌西雅；","notes":[]},{"n":22,"t":"巴施户珥的子孙中，有以利约乃、玛西雅、以实玛利、拿坦业、约撒拔、以利亚萨。","notes":[]},{"n":23,"t":"利未人中，有约撒拔、示每、基拉雅，基拉雅就是基利他，还有毗他希雅、犹大、以利以谢。","notes":[]},{"n":24,"t":"歌唱的人中有以利亚实。门口的守卫中，有沙龙、提联、乌利。","notes":[]},{"n":25,"t":"以色列人巴录的子孙中，有拉米、耶西雅、玛基雅、米雅民、以利亚撒、玛基雅、比拿雅。","notes":[]},{"n":26,"t":"以拦的子孙中，有玛他尼、撒迦利亚、耶歇、押底、耶列末、以利雅。","notes":[]},{"n":27,"t":"萨土的子孙中，有以利约乃、以利亚实、玛他尼、耶列末、撒拔、亚西撒。","notes":[]},{"n":28,"t":"比拜的子孙中，有约哈难、哈拿尼雅、萨拜、亚勒。","notes":[]},{"n":29,"t":"巴尼的子孙中，有米书兰、玛鹿、亚大雅、雅述、示押、拉末。","notes":["“拉末”：原文另译“耶列末”。"]},{"n":30,"t":"巴哈．摩押的子孙中，有阿底拿、基拉、比拿雅、玛西雅、玛他尼、比撒列、宾内、玛拿西。","notes":[]},{"n":31,"t":"哈琳的子孙中，有以利以谢、伊示雅、玛基雅、示玛雅、西缅、","notes":[]},{"n":32,"t":"便雅悯、玛鹿、示玛利雅。","notes":[]},{"n":33,"t":"哈顺的子孙中，有玛特乃、玛达他、撒拔、以利法列、耶利买、玛拿西、示每。","notes":[]},{"n":34,"t":"巴尼的子孙中，有玛玳、暗兰、乌益、","notes":[]},{"n":35,"t":"比拿雅、比底雅、基禄、","notes":[]},{"n":36,"t":"瓦尼雅、米利末、以利亚实、","notes":[]},{"n":37,"t":"玛他尼、玛特乃、雅扫、","notes":[]},{"n":38,"t":"巴尼、宾内、示每、","notes":[]},{"n":39,"t":"示利米雅、拿单、亚大雅、","notes":[]},{"n":40,"t":"玛拿底拜、沙赛、沙赖、","notes":[]},{"n":41,"t":"亚萨利、示利米雅、示玛利雅、","notes":[]},{"n":42,"t":"沙龙、亚玛利雅、约瑟。","notes":[]},{"n":43,"t":"尼波的子孙中，有耶利、玛他提雅、撒拔、西比拿、雅玳、约珥、比拿雅。","notes":[]},{"n":44,"t":"这些人全都娶了外邦女子，其中也有生了儿女的。","notes":["“其中也有生了儿女的”：原文另译“他们就将妻子和儿女送走”。"]}]}},"NEH":{"1":{"heading":"尼希米关心耶路撒冷","verses":[{"n":1,"t":"哈迦利亚的儿子尼希米的言语如下：亚达薛西王二十年基斯流月，我在书珊城堡中。","notes":[]},{"n":2,"t":"那时，我有一个兄弟哈拿尼，同几个人从犹大来。我问他们那些被掳归回、剩下残存的犹太人和耶路撒冷的情况。","notes":[]},{"n":3,"t":"他们对我说：“那些被掳归回剩下的余民在犹大省那里遭大难，受凌辱；耶路撒冷的城墙被拆毁，城门被火焚烧。”","notes":[]},{"n":4,"t":"我听见这话，就坐下哭泣，悲哀几日，在天上的神面前禁食祈祷，","notes":[]},{"n":5,"t":"说：“唉，耶和华－天上大而可畏的神，向爱你、守你诫命的人守约施慈爱的神啊，","notes":[]},{"n":6,"t":"愿你睁眼看，侧耳听你仆人今日昼夜在你面前，为你众仆人以色列人的祈祷，承认我们以色列人向你所犯的罪；我与我父家都犯了罪。","notes":[]},{"n":7,"t":"我们向你所行的非常败坏，没有遵守你吩咐你仆人摩西的诫命、律例、典章。","notes":[]},{"n":8,"t":"求你记念所吩咐你仆人摩西的话，说：‘你们若犯罪，我就把你们分散在万民中；","notes":[]},{"n":9,"t":"但你们若归向我，谨守遵行我的诫命，你们被赶散的人虽在天涯，我也必从那里将他们召集回来，带到我所选择立为我名居所的地方。’","notes":[]},{"n":10,"t":"他们是你的仆人和你的百姓，是你用大力和大能的手所救赎的。","notes":[]},{"n":11,"t":"唉，主啊，求你侧耳听你仆人的祈祷，听喜爱敬畏你名众仆人的祈祷，使你仆人今日亨通，在这人面前蒙恩。”我是王的酒政。","notes":[]}]},"2":{"heading":"尼希米返回耶路撒冷","verses":[{"n":1,"t":"亚达薛西王二十年尼散月，酒摆在王面前，我拿起酒来奉给王。我在王面前从来没有愁容。","notes":["“王面前”：七十士译本和古译本是“我面前”。"]},{"n":2,"t":"王对我说：“你既没有病，为什么面带愁容呢？这不是别的，必是你心中愁烦。”于是我非常惧怕。","notes":[]},{"n":3,"t":"我对王说：“愿王万岁！我祖先坟墓所在的那城荒凉，城门被火焚烧，我岂能面无愁容呢？”","notes":[]},{"n":4,"t":"王对我说：“你想求什么？”于是我向天上的神祈祷。","notes":[]},{"n":5,"t":"我对王说：“王若以为好，仆人若在王面前蒙宠爱，求王差遣我往犹大，到我祖先坟墓所在的那城去，我好重新建造。”","notes":[]},{"n":6,"t":"那时王后坐在王的旁边，王对我说：“你要去多久？几时回来？”王看这事为好，就派我去。我给王定了日期。","notes":[]},{"n":7,"t":"我又对王说：“王若以为好，求王赐我诏书，通知河西的省长准我经过，直到犹大；","notes":[]},{"n":8,"t":"又赐诏书，通知管理王园林的亚萨，叫他给我木材，作为殿的营楼之门、城墙，和我自己要住的房屋的横梁。”王就允准我，因为我神施恩的手帮助我。","notes":[]},{"n":9,"t":"王派了军官和骑兵护送我。我到了河西的省长那里，将王的诏书交给他们。","notes":[]},{"n":10,"t":"和伦人参巴拉和作臣仆的亚扪人多比雅，听见有人来为以色列人争取利益，就很恼怒。","notes":[]},{"n":11,"t":"我到了耶路撒冷，在那里停留了三天。","notes":[]},{"n":12,"t":"夜间我和跟随我的几个人起来；但神感动我心要为耶路撒冷做的事，我并没有告诉人。只有我自己骑的牲口，没有别的牲口在我那里。","notes":[]},{"n":13,"t":"当夜，我出了谷门，往野狗泉去，到了粪厂门，察看耶路撒冷的城墙，城墙被拆毁，城门被火焚烧。","notes":[]},{"n":14,"t":"我又往前，到了泉门，又到王池，但所骑的牲口没有地方可以过去。","notes":[]},{"n":15,"t":"于是我夜间沿溪而上，察看城墙，又转身进入谷门，就回来了。","notes":[]},{"n":16,"t":"我往哪里去，我做什么事，官长都不知道。我也没有告诉犹大人、祭司、贵族、官长和其余做工的人。","notes":[]},{"n":17,"t":"以后，我对他们说：“我们所遭的难，耶路撒冷怎样荒凉，城门被火焚烧，你们都看见了。来吧，让我们重建耶路撒冷的城墙，免得再受凌辱！”","notes":[]},{"n":18,"t":"我告诉他们我神施恩的手怎样帮助我，以及王向我所说的话。他们就说：“我们起来建造吧！”于是他们使自己的手坚强，做这美好的工作。","notes":[]},{"n":19,"t":"但和伦人参巴拉、作臣仆的亚扪人多比雅和阿拉伯人基善听见就嗤笑我们，藐视我们，说：“你们所做的这事是什么呢？要背叛王吗？”","notes":[]},{"n":20,"t":"我回答他们的话，对他们说：“天上的神必使我们亨通。我们作他仆人的，要起来建造；你们却在耶路撒冷无份、无权、无名号。”","notes":["“名号”：原文是“纪念”，意思是“使人记得他们”。"]}]},"3":{"heading":"重建耶路撒冷城墙","verses":[{"n":1,"t":"那时，以利亚实大祭司和他的弟兄众祭司起来建立羊门，将门分别为圣，安立门扇，直到哈米亚楼。他们又将它分别为圣，直到哈楠业楼。","notes":[]},{"n":2,"t":"在他旁边建造的是耶利哥人。在他旁边建造的是音利的儿子撒刻。","notes":[]},{"n":3,"t":"哈西拿的子孙建立鱼门，架横梁、安门扇，装闩和锁。","notes":[]},{"n":4,"t":"在他们旁边修造的是哈哥斯的孙子，乌利亚的儿子米利末。在他们旁边修造的是米示萨别的孙子，比利迦的儿子米书兰。在他们旁边修造的是巴拿的儿子撒督。","notes":[]},{"n":5,"t":"在他们旁边修造的是提哥亚人；但是他们的贵族不用肩扛他们主人的工作。","notes":["“肩”：原文是“颈项”。"]},{"n":6,"t":"巴西亚的儿子耶何耶大与比所玳的儿子米书兰修造古门，架横梁，安门扇，装闩和锁。","notes":[]},{"n":7,"t":"在他们旁边修造的是基遍人米拉提、米伦人雅顿、基遍人，和河西总督所管的米斯巴人。","notes":[]},{"n":8,"t":"在他旁边修造的是哈海雅的儿子乌薛银匠。在他旁边修造的是做香料的哈拿尼雅。他们修复耶路撒冷，直到宽墙。","notes":[]},{"n":9,"t":"在他们旁边修造的是管理耶路撒冷城区的一半、户珥的儿子利法雅。","notes":[]},{"n":10,"t":"在他们旁边的是哈路抹的儿子耶大雅在自己房屋的对面修造。在他旁边修造的是哈沙尼的儿子哈突。","notes":[]},{"n":11,"t":"哈琳的儿子玛基雅和巴哈．摩押的儿子哈述修造下一段和炉楼。","notes":[]},{"n":12,"t":"在他旁边修造的是管理耶路撒冷城区的另一半、哈罗黑的儿子沙龙和他的女儿们。","notes":[]},{"n":13,"t":"哈嫩和撒挪亚的居民修造谷门；他们立门，安门扇，装闩和锁，又修造城墙一千肘，直到粪厂门。","notes":[]},{"n":14,"t":"管理伯．哈基琳区、利甲的儿子玛基雅修造粪厂门；他立门，安门扇，装闩和锁。","notes":[]},{"n":15,"t":"管理米斯巴区、各．荷西的儿子沙仑修造泉门；他立门，盖门顶，安门扇，装闩和锁，又修造靠近王的花园西罗亚池的城墙，直到那从大卫城下来的台阶。","notes":[]},{"n":16,"t":"接续他修造的是管理伯．夙区的一半、押卜的儿子尼希米，直到大卫坟地的对面，又到人造池，到达勇士的房屋。","notes":[]},{"n":17,"t":"接续他修造的是利未人巴尼的儿子利宏。在他旁边的是管理基伊拉区一半的哈沙比雅为本区修造。","notes":[],"heads":["造城墙的利未人"]},{"n":18,"t":"接续他修造的是他们弟兄中管理基伊拉区的另一半、希拿达的儿子宾内。","notes":["“宾内”是根据一些古卷、七十士译本和其他古译本；原文是“巴瓦伊”。"]},{"n":19,"t":"在他旁边的是管理米斯巴、耶书亚的儿子以谢珥修造武库的上坡对面、城墙转弯处的那一段。","notes":[]},{"n":20,"t":"接续他的是萨拜的儿子巴录竭力修造下一段，从转弯处，直到以利亚实大祭司的府门。","notes":[]},{"n":21,"t":"接续他的是哈哥斯的孙子，乌利亚的儿子米利末修造下一段，从以利亚实的府门，直到以利亚实府的尽头。","notes":[]},{"n":22,"t":"接续他修造的是住平原的祭司。","notes":[],"heads":["造城墙的祭司"]},{"n":23,"t":"接续他的是便雅悯与哈述在自己房屋的对面修造。接续他的是亚难尼的孙子，玛西雅的儿子亚撒利雅在自己房屋的旁边修造。","notes":[]},{"n":24,"t":"接续他的是希拿达的儿子宾内修造下一段，从亚撒利雅的房屋直到转弯处，又到城角。","notes":[]},{"n":25,"t":"乌赛的儿子巴拉修造转弯处的对面和靠近护卫院、王宫上层凸出来的城楼。接续他的是巴录的儿子毗大雅，","notes":[]},{"n":26,"t":"（殿役住在俄斐勒，直到朝东水门的对面和凸出来的城楼。）","notes":[]},{"n":27,"t":"接续他的是提哥亚人又修造一段，对着那凸出来的大城楼，直到俄斐勒的城墙。","notes":[]},{"n":28,"t":"从马门往上，祭司各在自己房屋的对面修造。","notes":[]},{"n":29,"t":"接续他的是音麦的儿子撒督在自己房屋的对面修造。接续他修造的是东门的守卫、示迦尼的儿子示玛雅。","notes":[]},{"n":30,"t":"接续他的是示利米雅的儿子哈拿尼雅和萨拉的第六个儿子哈嫩修造下一段。接续他的是比利迦的儿子米书兰在自己房屋的对面修造。","notes":[]},{"n":31,"t":"接续他的是玛基雅银匠修造，直到殿役和商人的房屋，对着集合门，直到角楼。","notes":["“集合门”或音译“哈米弗甲门”。"]},{"n":32,"t":"银匠与商人在角楼和羊门之间修造。","notes":[]}]},"4":{"heading":"尼希米胜过阻挡他工作的人","verses":[{"n":1,"t":"参巴拉听见我们建造城墙就发怒，非常恼恨，并嗤笑犹太人。","notes":[]},{"n":2,"t":"他对他的弟兄和撒玛利亚的军兵说：“这些软弱的犹太人做什么呢？要为自己重建吗？要献祭吗？要一日完工吗？要使土堆里火烧过的石头再有用吗？”","notes":["“要为自己重建吗”或译“要把一切交托神吗”。"]},{"n":3,"t":"亚扪人多比雅在一旁说：“他们所修造的石墙，就是狐狸上去也必崩裂。”","notes":[]},{"n":4,"t":"我们的神啊，求你垂听，因为我们被藐视。求你使他们的毁谤归于他们自己头上，使他们在被掳之地成为掠物。","notes":[]},{"n":5,"t":"不要遮掩他们的罪孽，不要使他们的罪恶从你面前涂去，因为他们在修造的人前面惹你发怒。","notes":[]},{"n":6,"t":"这样，我们修造城墙，整个城墙就连接起来，到一半高，因为百姓一心做工。","notes":[]},{"n":7,"t":"参巴拉、多比雅、阿拉伯人、亚扪人和亚实突人听见耶路撒冷城墙正在修造，破裂的地方开始进行修补，就非常愤怒。","notes":[]},{"n":8,"t":"大家同谋要来攻打耶路撒冷，使城混乱。","notes":[]},{"n":9,"t":"然而，我们向我们的神祷告，又因他们的缘故，就派人站岗，昼夜防备他们。","notes":[]},{"n":10,"t":"但犹大有话说：“扛抬的人力气衰弱，瓦砾太多，我们自己不可能建造城墙。”","notes":[]},{"n":11,"t":"我们的敌人说：“趁他们不知道，看不见的时候，我们进入他们中间，杀了他们，使工作停止。”","notes":[]},{"n":12,"t":"那靠近敌人居住的犹太人十次从各处来见我们，说：“你们必须回到我们那里。”","notes":[]},{"n":13,"t":"我叫百姓站在城墙后边低洼的空处，使百姓各按宗族站着，拿刀、拿枪、拿弓。","notes":[]},{"n":14,"t":"我察看了，就起来对贵族、官长和其余的百姓说：“不要怕他们！当记得主是大而可畏的。你们要为你们的弟兄、儿女、妻子、家园争战。”","notes":[]},{"n":15,"t":"仇敌听见我们知道了他们的计谋，神也破坏他们的计谋，我们就都回到城墙那里，各做各的工。","notes":[]},{"n":16,"t":"从那日起，我的仆人一半做工，一半拿枪、拿盾牌、拿弓、穿铠甲，官长都站在犹大全家的后边。","notes":[]},{"n":17,"t":"他们建造城墙；扛抬材料的人扛抬的时候，一手做工，一手拿兵器。","notes":[]},{"n":18,"t":"建造的人都腰间佩刀建造，吹角的人在我旁边。","notes":[]},{"n":19,"t":"我对贵族、官长和其余的百姓说：“这工程浩大，范围辽阔，我们在城墙上彼此相离很远。","notes":[]},{"n":20,"t":"你们一听见角声在哪里，就聚集到我们那里去。我们的神必为我们争战。”","notes":[]},{"n":21,"t":"于是，我们做这工程，一半的人拿枪，从天亮直到星宿出现的时候。","notes":[]},{"n":22,"t":"那时，我又对百姓说：“各人和他的仆人当在耶路撒冷过夜，好为我们夜间守卫，白昼做工。”","notes":[]},{"n":23,"t":"这样，我和弟兄仆人，以及跟从我的卫兵都不脱衣服，各人打水时也拿着自己的兵器。","notes":["“打水时”：原文另译“手里”或“右手”。"]}]},"5":{"heading":"尼希米处理官长们的剥削","verses":[{"n":1,"t":"百姓和他们的妻子大大呼号，埋怨他们的弟兄犹太人。","notes":[]},{"n":2,"t":"有的说：“我们和儿女人口众多，必须得粮食吃，才能活下去。”","notes":[]},{"n":3,"t":"有的说：“我们典押了田地、葡萄园、房屋，才得粮食充饥。”","notes":[]},{"n":4,"t":"有的说：“我们借了钱付田地和葡萄园的税给王。","notes":[]},{"n":5,"t":"现在，我们的身体与我们弟兄的身体是一样的，我们的儿女与他们的儿女没有差别。看哪，我们却要迫使儿女作人的奴婢。我们有些女儿已被抢走了，我们却无能为力，因为我们的田地和葡萄园已经归了别人。”","notes":[]},{"n":6,"t":"我听见他们的呼号和这些话，就非常愤怒。","notes":[]},{"n":7,"t":"我心里作了决定，就斥责贵族和官长，对他们说：“你们各人借钱给弟兄，竟然索取利息！”于是我召开大会攻击他们。","notes":[]},{"n":8,"t":"我对他们说：“我们已尽力赎回我们的弟兄，就是卖到列国的犹太人；你们还要卖弟兄，让我们去买回来吗？”他们就静默不语，无话可答。","notes":[]},{"n":9,"t":"我又说：“你们做的这事不对！你们行事不是应该敬畏我们的神，免得列国我们的仇敌毁谤我们吗？","notes":[]},{"n":10,"t":"我和我的弟兄仆人也要把银钱粮食借给百姓，大家都当免除利息。","notes":[]},{"n":11,"t":"就在今日，你们要把他们的田地、葡萄园、橄榄园、房屋，以及向他们所取银钱的利息、粮食、新酒和新油都归还他们。”","notes":["“银钱的利息”或译“百分之一的银钱”。"]},{"n":12,"t":"贵族和官长说：“我们必归还，不再向他们索取，必照你所说的去做。”我就召了祭司来，叫贵族和官长起誓，必照这话去做。","notes":[]},{"n":13,"t":"我也抖着胸前的衣袋，说：“凡不实行这话的，愿神照样抖他离开他的家和他劳碌得来的，直到抖空了。”全会众都说：“阿们！”又赞美耶和华。百姓就照着这话去做。","notes":[]},{"n":14,"t":"自从我奉派作犹大地省长的那日，就是从亚达薛西王二十年直到三十二年，共十二年之久，我与我弟兄都没有吃省长的俸禄。","notes":[],"heads":["尼希米大公无私"]},{"n":15,"t":"在我以前的省长加重百姓的负担，向百姓索取粮食和酒，以及四十舍客勒银子，甚至他们的仆人也辖制百姓，但我因敬畏神不这样做。","notes":["“向百姓...银子”：有古译本是“每日向百姓索取粮食、酒、四十舍客勒银子”。"]},{"n":16,"t":"我也努力修造城墙。我们并没有购置田地，我所有的仆人也都聚集在那里做工。","notes":[]},{"n":17,"t":"除了从四围列国来的人以外，有犹太人和官长一百五十人与我同席。","notes":[]},{"n":18,"t":"每日预备一头公牛、六只肥羊，又为我预备飞禽；每十日一次多多预备各样的酒。虽然如此，我并不索取省长的俸禄，因为这百姓负的劳役很重。","notes":[]},{"n":19,"t":"我的神啊，求你记念我为这百姓所做的一切，施恩于我。","notes":[]}]},"6":{"heading":"敌对尼希米的阴谋","verses":[{"n":1,"t":"参巴拉、多比雅、阿拉伯人基善和我们其余的仇敌听见我已经建造了城墙，没有破裂之处在其中，那时我还没有在城门安门扇；","notes":[]},{"n":2,"t":"参巴拉和基善就派人来见我，说：“请你来，我们在阿挪平原的村庄见面。”其实，他们想要害我。","notes":[]},{"n":3,"t":"于是我派使者到他们那里，说：“我正在进行大的工程，不能下去。我怎么能离开，下去见你们，而让工程停顿呢？”","notes":[]},{"n":4,"t":"他们这样派人来见我四次，我都用这话回答他们。","notes":[]},{"n":5,"t":"参巴拉第五次同样派仆人来见我，手里拿着未封的信，","notes":[]},{"n":6,"t":"信上写着：“列国中有风声，基善也说，你和犹太人谋反，所以你建造城墙。据说，你要作他们的王，","notes":["“基善”：参尼2．19；原文译“迦施慕”。"]},{"n":7,"t":"并且你派先知在耶路撒冷指着你宣讲说，‘在犹大有王。’如今这些话必传给王知，现在请你来，我们一起商议。”","notes":[]},{"n":8,"t":"我就派人到他那里，说：“你所说的这些事，一概没有，是你心里捏造的。”","notes":[]},{"n":9,"t":"他们全都要使我们惧怕，说：“他们的手必软弱，不能工作，以致不能完工。”现在，求你坚固我的手。","notes":[]},{"n":10,"t":"我到了米希大别的孙子，第来雅的儿子示玛雅家里；那时，他闭门不出。他说：“我们可以在神的殿里，就在殿的中间会面，锁住殿门，因为他们要来杀你，要在夜里来杀你。”","notes":[]},{"n":11,"t":"我说：“像我这样的人岂会逃跑呢？像我这样的人岂能进入殿里保全生命呢？我不进去！”","notes":[]},{"n":12,"t":"我看清楚了，看哪，神并没有派他，是他自己说预言攻击我，是多比雅和参巴拉收买了他；","notes":[]},{"n":13,"t":"收买他的目的是要叫我惧怕，依从他犯罪，留下一个坏名声，好让他们毁谤我。","notes":[]},{"n":14,"t":"我的神啊，求你记得多比雅、参巴拉、挪亚底女先知和其余的先知，因他们行这些事，要叫我惧怕。","notes":[]},{"n":15,"t":"以禄月二十五日，城墙修完了，共修了五十二天。","notes":[],"heads":["工程结束"]},{"n":16,"t":"我们所有的仇敌听见了，四围的列国就惧怕，愁眉不展，因为他们知道这工作得以完成，是出于我们的神。","notes":[]},{"n":17,"t":"而且，在那些日子，犹大的贵族屡次寄信给多比雅，多比雅也回信给他们。","notes":[]},{"n":18,"t":"在犹大有许多人与多比雅结盟，因为他是亚拉的儿子示迦尼的女婿，并且他的儿子约哈难娶了比利迦的儿子米书兰的女儿。","notes":[]},{"n":19,"t":"他们也在我面前说多比雅的好话，又把我的话传给他。多比雅常寄信来，要叫我惧怕。","notes":[]}]},"7":{"heading":"被掳归回者的名单","verses":[{"n":1,"t":"城墙修完，我安了门扇，门口的守卫、歌唱的和利未人都已派定。","notes":[]},{"n":2,"t":"我吩咐我的兄弟哈拿尼和城堡的官长哈拿尼雅管理耶路撒冷，因为哈拿尼雅是一个忠信的人，敬畏神过于众人。","notes":[]},{"n":3,"t":"我对他们说：“等到太阳热的时候才可开耶路撒冷的城门；要派耶路撒冷的居民，各按班次在自己房屋的前面站岗。他们还在站岗的时候，就要关门上闩。”","notes":[]},{"n":4,"t":"城又宽又大，城中的百姓却稀少，房屋也还没有建造。","notes":[]},{"n":5,"t":"我的神感动我的心，我就召集贵族、官长和百姓，要登记家谱。我找到第一次上来之人的家谱，发现上面写着：","notes":[]},{"n":6,"t":"这些是从被掳之地上来的省民，巴比伦王尼布甲尼撒把他们掳去，他们重返耶路撒冷和犹大，各归本城。","notes":[]},{"n":7,"t":"他们是同所罗巴伯、耶书亚、尼希米、亚撒利雅、拉米、拿哈玛尼、末底改、必珊、米斯毗列、比革瓦伊、尼宏、巴拿一起回来的。以色列百姓的人数如下：","notes":[]},{"n":8,"t":"巴录的子孙二千一百七十二名；","notes":[]},{"n":9,"t":"示法提雅的子孙三百七十二名；","notes":[]},{"n":10,"t":"亚拉的子孙六百五十二名；","notes":[]},{"n":11,"t":"巴哈．摩押的后裔，就是耶书亚和约押的子孙二千八百一十八名；","notes":[]},{"n":12,"t":"以拦的子孙一千二百五十四名；","notes":[]},{"n":13,"t":"萨土的子孙八百四十五名；","notes":[]},{"n":14,"t":"萨改的子孙七百六十名；","notes":[]},{"n":15,"t":"宾内的子孙六百四十八名；","notes":[]},{"n":16,"t":"比拜的子孙六百二十八名；","notes":[]},{"n":17,"t":"押甲的子孙二千三百二十二名；","notes":[]},{"n":18,"t":"亚多尼干的子孙六百六十七名；","notes":[]},{"n":19,"t":"比革瓦伊的子孙二千零六十七名；","notes":[]},{"n":20,"t":"亚丁的子孙六百五十五名；","notes":[]},{"n":21,"t":"亚特的后裔，就是希西家的子孙九十八名；","notes":[]},{"n":22,"t":"哈顺的子孙三百二十八名；","notes":[]},{"n":23,"t":"比赛的子孙三百二十四名；","notes":[]},{"n":24,"t":"哈拉的子孙一百一十二名；","notes":[]},{"n":25,"t":"基遍人九十五名；","notes":[]},{"n":26,"t":"伯利恒人和尼陀法人共一百八十八名；","notes":[]},{"n":27,"t":"亚拿突人一百二十八名；","notes":[]},{"n":28,"t":"伯．亚斯玛弗人四十二名；","notes":[]},{"n":29,"t":"基列．耶琳人、基非拉人、比录人共七百四十三名；","notes":[]},{"n":30,"t":"拉玛人和迦巴人共六百二十一名；","notes":[]},{"n":31,"t":"默玛人一百二十二名；","notes":[]},{"n":32,"t":"伯特利人和艾人共一百二十三名；","notes":[]},{"n":33,"t":"别的尼波人五十二名；","notes":[]},{"n":34,"t":"另一个以拦子孙一千二百五十四名；","notes":[]},{"n":35,"t":"哈琳的子孙三百二十名；","notes":[]},{"n":36,"t":"耶利哥人三百四十五名；","notes":[]},{"n":37,"t":"罗德人、哈第人、阿挪人共七百二十一名；","notes":[]},{"n":38,"t":"西拿人三千九百三十名。","notes":[]},{"n":39,"t":"祭司：耶书亚家，耶大雅的子孙九百七十三名；","notes":[]},{"n":40,"t":"音麦的子孙一千零五十二名；","notes":[]},{"n":41,"t":"巴施户珥的子孙一千二百四十七名；","notes":[]},{"n":42,"t":"哈琳的子孙一千零一十七名。","notes":[]},{"n":43,"t":"利未人：何达威的后裔，就是耶书亚和甲篾的子孙七十四名。","notes":[]},{"n":44,"t":"歌唱的：亚萨的子孙一百四十八名。","notes":[]},{"n":45,"t":"门口的守卫：沙龙的子孙、亚特的子孙、达们的子孙、亚谷的子孙、哈底大的子孙、朔拜的子孙，共一百三十八名。","notes":[]},{"n":46,"t":"殿役：西哈的子孙、哈苏巴的子孙、答巴俄的子孙、","notes":[]},{"n":47,"t":"基绿的子孙、西亚的子孙、巴顿的子孙、","notes":[]},{"n":48,"t":"利巴拿的子孙、哈迦巴的子孙、萨买的子孙、","notes":[]},{"n":49,"t":"哈难的子孙、吉德的子孙、迦哈的子孙、","notes":[]},{"n":50,"t":"利亚雅的子孙、利汛的子孙、尼哥大的子孙、","notes":[]},{"n":51,"t":"迦散的子孙、乌撒的子孙、巴西亚的子孙、","notes":[]},{"n":52,"t":"比赛的子孙、米乌宁的子孙、尼普心的子孙、","notes":[]},{"n":53,"t":"巴卜的子孙、哈古巴的子孙、哈忽的子孙、","notes":[]},{"n":54,"t":"巴洗律的子孙、米希大的子孙、哈沙的子孙、","notes":[]},{"n":55,"t":"巴柯的子孙、西西拉的子孙、答玛的子孙、","notes":[]},{"n":56,"t":"尼细亚的子孙、哈提法的子孙。","notes":[]},{"n":57,"t":"所罗门仆人的后裔：琐太的子孙、琐斐列的子孙、比路大的子孙、","notes":[]},{"n":58,"t":"雅拉的子孙、达昆的子孙、吉德的子孙、","notes":[]},{"n":59,"t":"示法提雅的子孙、哈替的子孙、玻黑列．哈斯巴音的子孙、亚们的子孙。","notes":[]},{"n":60,"t":"殿役和所罗门仆人的后裔共三百九十二名。","notes":[]},{"n":61,"t":"从特．米拉、特．哈萨、基绿、亚顿、音麦上来，不能证明他们的父系家族和后裔是否属以色列的如下：","notes":[]},{"n":62,"t":"第莱雅的子孙、多比雅的子孙、尼哥大的子孙，共六百四十二名。","notes":[]},{"n":63,"t":"祭司中，哈巴雅的子孙、哈哥斯的子孙、巴西莱的子孙，巴西莱因为娶了基列人巴西莱的女儿为妻，所以就以此为名。","notes":[]},{"n":64,"t":"这些人在族谱之中寻查自己的谱系，却寻不着，因此算为不洁，不得作祭司。","notes":[]},{"n":65,"t":"省长对他们说，不可吃至圣的物，直到有会用乌陵和土明的祭司兴起来。","notes":[]},{"n":66,"t":"全会众共有四万二千三百六十名。","notes":[]},{"n":67,"t":"此外，还有他们的仆婢七千三百三十七名，又有歌唱的男女二百四十五名。","notes":[]},{"n":68,"t":"他们有七百三十六匹马，二百四十五匹骡子，","notes":[]},{"n":69,"t":"四百三十五匹骆驼，六千七百二十匹驴。","notes":[]},{"n":70,"t":"有些族长为工程捐助。省长捐入库房中的有一千达利克金子，五十个碗，五百三十件祭司的礼服。","notes":["“达利克”：古波斯金币，参“度量衡表”；下节同。"]},{"n":71,"t":"有些族长捐入工程的库房，有二万达利克金子，二千二百弥那银子。","notes":[]},{"n":72,"t":"其余百姓所捐的有二万达利克金子，二千弥那银子，六十七件祭司的礼服。","notes":[]},{"n":73,"t":"于是祭司、利未人、门口的守卫、歌唱的、百姓中的一些人、殿役，并以色列众人，都住在自己的城里。到了七月，以色列人住在自己的城里。","notes":[]}]},"8":{"heading":"住棚节","verses":[{"n":1,"t":"那时，众百姓如同一人聚集在水门前的广场，请以斯拉文士将耶和华吩咐以色列的摩西的律法书带来。","notes":[]},{"n":2,"t":"七月初一，以斯拉祭司将律法书带到听了能明白的男女会众面前。","notes":[]},{"n":3,"t":"他在水门前的广场，从清早到中午，在男女和能明白的人面前读这律法书，众百姓都侧耳而听。","notes":[]},{"n":4,"t":"以斯拉文士站在为这事特制的木台上。站在他旁边的有玛他提雅、示玛、亚奈雅、乌利亚和希勒家；站在他右边的有玛西雅；站在他左边的有毗大雅、米沙利、玛基雅、哈顺、哈拔大拿、撒迦利亚和米书兰。","notes":[]},{"n":5,"t":"以斯拉站在上面，在众百姓眼前展开这书。他一展开，众百姓都站起来。","notes":[]},{"n":6,"t":"以斯拉称颂耶和华至大的神，众百姓都举手应声说：“阿们！阿们！”他们低头，俯伏在地，敬拜耶和华。","notes":[]},{"n":7,"t":"耶书亚、巴尼、示利比、雅悯、亚谷、沙比太、荷第雅、玛西雅、基利他、亚撒利雅、约撒拔、哈难、毗莱雅和利未人使百姓明白律法；百姓都站在自己的地方。","notes":[]},{"n":8,"t":"他们清清楚楚地念神的律法书，讲明意思，使百姓明白所念的。","notes":[]},{"n":9,"t":"尼希米省长、以斯拉祭司文士，和教导百姓的利未人对众百姓说：“今日是耶和华－你们神的圣日，不要悲哀，也不要哭泣。”这是因为众百姓听见律法书上的话都哭了。","notes":[]},{"n":10,"t":"尼希米对他们说：“你们去吃肥美的，喝甘甜的，有不能预备的就分给他，因为今日是我们主的圣日。你们不要忧愁，因靠耶和华而得的喜乐是你们的力量。”","notes":[]},{"n":11,"t":"于是利未人叫众百姓安静，说：“安静，因今日是圣日，不要忧愁。”","notes":[]},{"n":12,"t":"众百姓去吃喝，也分给别人，都大大喜乐，因为他们明白所教导他们的话。","notes":[]},{"n":13,"t":"次日，众百姓的族长、祭司和利未人都聚集到以斯拉文士那里，要明白律法书上的话。","notes":[]},{"n":14,"t":"他们发现律法书上写着，耶和华藉摩西吩咐以色列人要在七月的节期中住在棚里，","notes":[]},{"n":15,"t":"并要在各城和耶路撒冷传扬宣告说：“你们当出去，上山，把橄榄树、野橄榄树、番石榴树、棕树和各样茂密树的枝子取来，照着所写的搭棚。”","notes":[]},{"n":16,"t":"于是百姓出去，取了树枝来，各人在自己的房顶上，院子里，神殿的院内，水门的广场，和以法莲门的广场搭棚。","notes":[]},{"n":17,"t":"从被掳之地归回的全会众就搭棚，住在棚里。从嫩的儿子约书亚的时候直到这日，以色列人没有这样行。他们都大大喜乐。","notes":[]},{"n":18,"t":"从第一天直到末一天，以斯拉天天朗读神的律法书。他们守节七日，第八日照例有严肃会。","notes":[]}]},"9":{"heading":"以色列人的认罪","verses":[{"n":1,"t":"这月二十四日，以色列人聚集禁食，他们披麻蒙灰。","notes":[]},{"n":2,"t":"以色列的后裔与所有的外邦人分别出来，站着承认自己的罪和祖先的罪孽。","notes":[]},{"n":3,"t":"那日的四分之一，他们站在自己的地方念耶和华－他们神的律法书，又在那日的四分之一认罪，敬拜耶和华－他们的神。","notes":[]},{"n":4,"t":"耶书亚、巴尼、甲篾、示巴尼、布尼、示利比、巴尼、基拿尼站在利未人的台阶上，大声哀求耶和华－他们的神。","notes":[]},{"n":5,"t":"利未人耶书亚、甲篾、巴尼、哈沙尼、示利比、荷第雅、示巴尼、毗他希雅说：“起来，称颂耶和华－你们的神，永世无尽：‘你荣耀之名是应当称颂的，超乎一切称颂和赞美。","notes":[]},{"n":6,"t":"“‘你，惟独你是耶和华！你造了天和天上的天，以及天上的万象，地和地上的万物，海和海中所有的；一切的生命全都是你赏赐的。天军都敬拜你。","notes":[]},{"n":7,"t":"你是耶和华神，曾拣选亚伯兰，领他出迦勒底的吾珥，给他改名叫亚伯拉罕。","notes":[]},{"n":8,"t":"你发现他在你面前心里忠诚，就与他立约，要把迦南人、赫人、亚摩利人、比利洗人、耶布斯人、革迦撒人之地赐给他的后裔，并且你也实现了你的话，因为你是公义的。","notes":[]},{"n":9,"t":"“‘你曾看见我们祖先在埃及所受的困苦，垂听他们在红海边的哀求，","notes":["“红海”是根据七十士译本；原文是“芦苇海”。"]},{"n":10,"t":"施行神迹奇事在法老和他所有臣仆，以及他国中众百姓身上，因为你知道他们向我们祖先行事狂傲。你也得了名声，正如今日一样。","notes":[]},{"n":11,"t":"你在我们祖先面前把海分开，使他们走过海中干地，将追赶他们的人抛在深海，如石头抛在大水中。","notes":[]},{"n":12,"t":"白昼你用云柱引导他们，黑夜你用火柱照亮他们当行的路。","notes":[]},{"n":13,"t":"你降临在西奈山，从天上与他们说话，赐给他们正直的典章、真实的律法、美好的律例与诫命，","notes":[]},{"n":14,"t":"又使他们知道你的圣安息日，并藉你仆人摩西传给他们诫命、律例、律法。","notes":[]},{"n":15,"t":"你从天上赐下粮食给他们充饥，使水从磐石流出给他们解渴。你吩咐他们进去，得你起誓应许要赐给他们的地。","notes":[]},{"n":16,"t":"“‘但我们的祖先行事狂傲，硬着颈项不听从你的诫命。","notes":[]},{"n":17,"t":"他们不肯顺从，也不记念你在他们中间所行的奇事，竟硬着颈项，居心悖逆，自立领袖，要回埃及他们为奴之地。但你是乐意饶恕人，有恩惠，有怜悯，不轻易发怒，有丰盛慈爱的神，并没有丢弃他们。","notes":["“要回埃及他们为奴之地”是根据一些古卷和七十士译本；原文是“要在背叛中回他们为奴之地”。"]},{"n":18,"t":"他们虽然为自己铸了一头牛犊，说，这就是领你出埃及的神明，因而犯了亵渎的大罪，","notes":[]},{"n":19,"t":"你还是有丰富的怜悯，不把他们丢弃在旷野。白昼，云柱不离开他们，仍引导他们行路；黑夜，火柱仍照亮他们当行的路。","notes":[]},{"n":20,"t":"你赐下你良善的灵教导他们，没有收回吗哪不给他们吃，仍赐水给他们解渴。","notes":[]},{"n":21,"t":"在旷野四十年，你养育他们，他们一无所缺，衣服没有穿破，脚也没有肿。","notes":[]},{"n":22,"t":"你将列国和诸民族交给他们，把那些角落分给他们，他们就得了西宏之地，就是希实本王之地，和巴珊王噩之地。","notes":[]},{"n":23,"t":"你使他们的子孙多如天上的星，带他们到你对他们祖先说要进去得为业之地。","notes":[]},{"n":24,"t":"这样，这些子孙进去得了那地。你在他们面前制伏那地的居民迦南人，把迦南人和他们的君王，以及那地的民族，都交在他们手里，让他们任意处置。","notes":[]},{"n":25,"t":"他们得了坚固的城镇、肥沃的土地，取了装满各样美物的房屋、挖成的水井、葡萄园、橄榄园，以及许多果树。他们就吃了，而且饱足，身体肥胖，因你的大恩活得快乐。","notes":[]},{"n":26,"t":"“‘然而，他们不顺从，竟背叛你，将你的律法丢在背后，又杀害那些劝他们回转归向你的众先知，犯了亵渎的大罪。","notes":[]},{"n":27,"t":"所以你将他们交在敌人的手中，敌人就折磨他们。他们遭难的时候哀求你，你就从天上垂听，照你丰富的怜悯赐给他们拯救者，救他们脱离敌人的手。","notes":[]},{"n":28,"t":"但他们得享太平之后，又在你面前行恶，所以你丢弃他们，交在仇敌的手中，仇敌就辖制他们；然而他们转回哀求你，你就从天上垂听，屡次照你的怜悯拯救他们，","notes":[]},{"n":29,"t":"你警戒他们，要使他们归顺你的律法。他们却行事狂傲，不听从你的诫命，干犯你的典章，人若遵行就必因此存活。他们顽梗地扭转肩头，硬着颈项，不肯听从。","notes":[]},{"n":30,"t":"但你多年宽容他们，又以你的灵藉众先知劝戒他们，他们仍不侧耳而听，所以你将他们交在列邦民族的手中。","notes":[]},{"n":31,"t":"然而因你丰富的怜悯，你不全然灭绝他们，也不丢弃他们，因为你是有恩惠、有怜悯的神。","notes":[]},{"n":32,"t":"“‘现在，我们的神啊，你是至大、至能、至可畏、守约施慈爱的神；我们的君王、官长、祭司、先知、祖先和你的众百姓，从亚述诸王的时候直到今日所遭遇的一切苦难，求你不要看为小事。","notes":[]},{"n":33,"t":"在一切临到我们的事上，你是公义的，因为你所行的是信实，我们所做的是邪恶。","notes":[]},{"n":34,"t":"我们的君王、官长、祭司、祖先都不遵守你的律法，不听从你的诫命和你警戒他们的话。","notes":[]},{"n":35,"t":"他们在本国领受你大恩的时候，在你所赐给他们这广大肥沃之地不事奉你，也不转离他们的恶行。","notes":[]},{"n":36,"t":"看哪，我们今日成了奴仆！你赐给我们祖先享受土产和美物的地，看哪，我们在这地上竟作了奴仆！","notes":[]},{"n":37,"t":"这地许多的出产都归了诸王，就是你因我们的罪派来辖制我们的。他们任意辖制我们的身体和牲畜，我们遭了大难。’”","notes":[]},{"n":38,"t":"因这一切，我们立确实的约，写在册上。我们的领袖、利未人和祭司都用了印。","notes":[]}]},"10":{"heading":"在公约上签名的人","verses":[{"n":1,"t":"用印的是哈迦利亚的儿子尼希米省长、西底家；","notes":[]},{"n":2,"t":"还有西莱雅、亚撒利雅、耶利米、","notes":[]},{"n":3,"t":"巴施户珥、亚玛利雅、玛基雅、","notes":[]},{"n":4,"t":"哈突、示巴尼、玛鹿、","notes":[]},{"n":5,"t":"哈琳、米利末、俄巴底亚、","notes":[]},{"n":6,"t":"但以理、近顿、巴录、","notes":[]},{"n":7,"t":"米书兰、亚比雅、米雅民、","notes":[]},{"n":8,"t":"玛西亚、璧该、示玛雅等祭司；","notes":[]},{"n":9,"t":"又有利未人亚散尼的儿子耶书亚、希拿达的子孙宾内、甲篾，","notes":[]},{"n":10,"t":"他们的弟兄示巴尼、荷第雅、基利他、毗莱雅、哈难、","notes":[]},{"n":11,"t":"米迦、利合、哈沙比雅、","notes":[]},{"n":12,"t":"撒刻、示利比、示巴尼、","notes":[]},{"n":13,"t":"荷第雅、巴尼、比尼努；","notes":[]},{"n":14,"t":"还有百姓中的领袖巴录、巴哈．摩押、以拦、萨土、巴尼、","notes":[]},{"n":15,"t":"布尼、押甲、比拜、","notes":[]},{"n":16,"t":"亚多尼雅、比革瓦伊、亚丁、","notes":[]},{"n":17,"t":"亚特、希西家、押朔、","notes":[]},{"n":18,"t":"荷第雅、哈顺、比赛、","notes":[]},{"n":19,"t":"哈拉、亚拿突、尼拜、","notes":[]},{"n":20,"t":"抹比押、米书兰、希悉、","notes":[]},{"n":21,"t":"米示萨别、撒督、押杜亚、","notes":[]},{"n":22,"t":"毗拉提、哈难、亚奈雅、","notes":[]},{"n":23,"t":"何细亚、哈拿尼雅、哈述、","notes":[]},{"n":24,"t":"哈罗黑、毗利哈、朔百、","notes":[]},{"n":25,"t":"利宏、哈沙拿、玛西雅、","notes":[]},{"n":26,"t":"亚希雅、哈难、亚难、","notes":[]},{"n":27,"t":"玛鹿、哈琳、巴拿。","notes":[]},{"n":28,"t":"其余的百姓、祭司、利未人、门口的守卫、歌唱的、殿役，所有与邻邦民族分别出来、归服神律法的，以及他们的妻子、儿女，凡有知识、能明白的，","notes":[],"heads":["公约的内容"]},{"n":29,"t":"都随从他们贵族的弟兄发咒起誓，要遵行神藉他仆人摩西所赐的律法，谨守遵行耶和华－我们主的一切诫命、典章、律例。","notes":[]},{"n":30,"t":"我们不把我们的女儿嫁给这地的居民，也不为我们的儿子娶他们的女儿。","notes":[]},{"n":31,"t":"这地的民族若在安息日，或什么圣日，带了货物或粮食来卖，我们必不买。每逢第七年必不耕种，凡欠我们债的必不追讨。","notes":[]},{"n":32,"t":"我们又为自己定例，每年各人捐献三分之一舍客勒，作为我们神殿之用：","notes":[]},{"n":33,"t":"为供饼、常献的素祭和燔祭，安息日、初一、节期所献的祭和圣物，以色列的赎罪祭，以及我们神殿里一切工作之用。","notes":[]},{"n":34,"t":"我们的祭司、利未人和百姓都抽签，每年按父家定期将奉献的木柴带到我们神的殿里，照着律法上所写的，烧在耶和华－我们神的坛上。","notes":[]},{"n":35,"t":"每年我们又将地上初熟的土产和各样树上初熟的果子，都奉到耶和华的殿里。","notes":[]},{"n":36,"t":"我们又照律法上所写的，将我们头胎的儿子和首生的牛羊都奉到我们神的殿，交给在神殿里供职的祭司；","notes":[]},{"n":37,"t":"并将初熟麦子所磨的面和举祭、各样树上的果子、新酒与新油奉给祭司，收在我们神殿的库房里，又把我们土地所产的十分之一奉给利未人，因利未人在我们一切城镇的土产中当取十分之一。","notes":[]},{"n":38,"t":"利未人取十分之一的时候，亚伦的子孙中当有一个祭司与利未人同在。利未人也当从十分之一中取十分之一，奉到我们神的殿，收在库房的仓里。","notes":[]},{"n":39,"t":"因以色列人和利未人要把礼物，就是五谷、新酒和新油，带到收存圣所器皿的仓里，供职的祭司、门口的守卫、歌唱的都在那里。我们绝不会不顾我们神的殿。","notes":[]}]},"11":{"heading":"住在耶路撒冷的人","verses":[{"n":1,"t":"百姓的领袖住在耶路撒冷。其余的百姓抽签，每十人中选一人来住在圣城耶路撒冷，另外九人住在别的城镇。","notes":[]},{"n":2,"t":"凡甘心乐意住在耶路撒冷的，百姓都为他们祝福。","notes":[]},{"n":3,"t":"以色列人、祭司、利未人、殿役和所罗门仆人的后裔都住在犹大的城镇，各在自己城内的地业中。本省的领袖住在耶路撒冷的如下：","notes":[]},{"n":4,"t":"住在耶路撒冷的有一些犹大人和便雅悯人。犹大人中有法勒斯的子孙亚他雅；亚他雅是乌西雅的儿子，乌西雅是撒迦利雅的儿子，撒迦利雅是亚玛利雅的儿子，亚玛利雅是示法提雅的儿子，示法提雅是玛勒列的儿子；","notes":[]},{"n":5,"t":"又有玛西雅；玛西雅是巴录的儿子，巴录是谷．何西的儿子，谷．何西是哈赛雅的儿子，哈赛雅是亚大雅的儿子，亚大雅是约雅立的儿子，约雅立是撒迦利雅的儿子，撒迦利雅是示罗尼的儿子；","notes":[]},{"n":6,"t":"住在耶路撒冷所有法勒斯的子孙共四百六十八名，都是勇士。","notes":[]},{"n":7,"t":"便雅悯人中有撒路；撒路是米书兰的儿子，米书兰是约叶的儿子，约叶是毗大雅的儿子，毗大雅是哥赖雅的儿子，哥赖雅是玛西雅的儿子，玛西雅是以铁的儿子，以铁是耶筛亚的儿子；","notes":[]},{"n":8,"t":"其次有迦拜、撒来，共九百二十八名。","notes":[]},{"n":9,"t":"细基利的儿子约珥是他们的长官；哈西努亚的儿子犹大是耶路撒冷的副长官。","notes":[]},{"n":10,"t":"祭司中有约雅立的儿子耶大雅，又有雅斤，","notes":[]},{"n":11,"t":"还有管理神殿的西莱雅；西莱雅是希勒家的儿子，希勒家是米书兰的儿子，米书兰是撒督的儿子，撒督是米拉约的儿子，米拉约是亚希突的儿子；","notes":[]},{"n":12,"t":"还有他们的弟兄在殿里供职的，共八百二十二名；又有亚大雅；亚大雅是耶罗罕的儿子，耶罗罕是毗拉利的儿子，毗拉利是暗洗的儿子，暗洗是撒迦利亚的儿子，撒迦利亚是巴施户珥的儿子，巴施户珥是玛基雅的儿子；","notes":[]},{"n":13,"t":"还有他的弟兄作族长的，共二百四十二名；又有亚玛帅；亚玛帅是亚萨列的儿子，亚萨列是亚哈赛的儿子，亚哈赛是米实利末的儿子，米实利末是音麦的儿子；","notes":[]},{"n":14,"t":"还有他们的弟兄，大能的勇士共一百二十八名；哈基多琳的儿子撒巴第业是他们的长官。","notes":[]},{"n":15,"t":"利未人中有示玛雅；示玛雅是哈述的儿子，哈述是押利甘的儿子，押利甘是哈沙比雅的儿子，哈沙比雅是布尼的儿子；","notes":[]},{"n":16,"t":"又有利未人的族长沙比太和约撒拔管理神殿外面的事务；","notes":[]},{"n":17,"t":"祈祷的时候，玛他尼是主礼，开始称谢；玛他尼是米迦的儿子，米迦是撒底的儿子，撒底是亚萨的儿子；又有玛他尼弟兄中的八布迦为副；还有押大；押大是沙母亚的儿子，沙母亚是加拉的儿子，加拉是耶杜顿的儿子；","notes":[]},{"n":18,"t":"在圣城所有的利未人共二百八十四名。","notes":[]},{"n":19,"t":"门口的守卫是亚谷和达们，以及他们的弟兄，看守各门，共一百七十二名。","notes":[]},{"n":20,"t":"其余的以色列人、祭司、利未人都住在犹大一切的城镇，各在自己的地业中。","notes":[]},{"n":21,"t":"殿役却住在俄斐勒；西哈和基斯帕管理他们。","notes":[]},{"n":22,"t":"在耶路撒冷，利未人的长官，管理神殿事务的是歌唱者亚萨的子孙乌西；乌西是巴尼的儿子，巴尼是哈沙比雅的儿子，哈沙比雅是玛他尼的儿子，玛他尼是米迦的儿子。","notes":[]},{"n":23,"t":"王为歌唱者下命令，确定他们每日当办的事。","notes":["“确定他们每日当办的事”或译“每日供给他们固定的口粮”。"]},{"n":24,"t":"犹大的儿子谢拉的子孙，米示萨别的儿子毗他希雅辅助王办理百姓一切的事。","notes":[]},{"n":25,"t":"至于村庄和所属的田地，有犹大人住在基列．亚巴和所属的乡镇、底本和所属的乡镇、叶甲薛和所属的村庄、","notes":["“乡镇”：原文直译“女子们”；下同。"],"heads":["住在其他城镇的人"]},{"n":26,"t":"耶书亚、摩拉大、伯．帕列、","notes":[]},{"n":27,"t":"哈萨．书亚、别是巴和所属的乡镇、","notes":[]},{"n":28,"t":"洗革拉、米哥拿和所属的乡镇、","notes":[]},{"n":29,"t":"隐．临门、琐拉、耶末、","notes":[]},{"n":30,"t":"撒挪亚、亚杜兰和属它们的村庄、拉吉和所属的田地、亚西加和所属的乡镇；他们所住的地方是从别是巴直到欣嫩谷。","notes":[]},{"n":31,"t":"便雅悯人从迦巴起，住在密抹、亚雅、伯特利和所属的乡镇、","notes":[]},{"n":32,"t":"亚拿突、挪伯、亚难雅、","notes":[]},{"n":33,"t":"夏琐、拉玛、基他音、","notes":[]},{"n":34,"t":"哈第、洗编、尼八拉、","notes":[]},{"n":35,"t":"罗德、阿挪、革．夏纳欣。","notes":[]},{"n":36,"t":"在犹大地区的利未人中，有些已归属便雅悯。","notes":[]}]},"12":{"heading":"祭司和利未人的名单","verses":[{"n":1,"t":"这些是同撒拉铁的儿子所罗巴伯以及耶书亚一起上来的祭司和利未人：西莱雅、耶利米、以斯拉、","notes":[]},{"n":2,"t":"亚玛利雅、玛鹿、哈突、","notes":[]},{"n":3,"t":"示迦尼、利宏、米利末、","notes":[]},{"n":4,"t":"易多、近顿、亚比雅、","notes":[]},{"n":5,"t":"米雅民、玛底雅、璧迦、","notes":[]},{"n":6,"t":"示玛雅、约雅立、耶大雅、","notes":[]},{"n":7,"t":"撒路、亚木、希勒家、耶大雅；这些人在耶书亚的时代作祭司和他们弟兄的领袖。","notes":[]},{"n":8,"t":"利未人有耶书亚、宾内、甲篾、示利比、犹大、玛他尼；玛他尼和他的弟兄负责赞美诗歌。","notes":[]},{"n":9,"t":"他们的弟兄八布迦和乌尼按照班次站在他们的对面。","notes":[]},{"n":10,"t":"耶书亚生约雅金，约雅金生以利亚实，以利亚实生耶何耶大，","notes":[],"heads":["耶书亚大祭司的后代"]},{"n":11,"t":"耶何耶大生约拿单，约拿单生押杜亚。","notes":[]},{"n":12,"t":"在约雅金的时代，祭司作族长的，西莱雅族有米拉雅，耶利米族有哈拿尼雅，","notes":[],"heads":["作族长的祭司"]},{"n":13,"t":"以斯拉族有米书兰，亚玛利雅族有约哈难，","notes":[]},{"n":14,"t":"米利古族有约拿单，示巴尼族有约瑟，","notes":[]},{"n":15,"t":"哈琳族有押拿，米拉约族有希勒恺，","notes":[]},{"n":16,"t":"易多族有撒迦利亚，近顿族有米书兰，","notes":[]},{"n":17,"t":"亚比雅族有细基利，米拿民族，摩亚底族有毗勒太，","notes":[]},{"n":18,"t":"璧迦族有沙母亚，示玛雅族有约拿单，","notes":[]},{"n":19,"t":"约雅立族有玛特乃，耶大雅族有乌西，","notes":[]},{"n":20,"t":"撒来族有加莱，亚木族有希伯，","notes":[]},{"n":21,"t":"希勒家族有哈沙比雅，耶大雅族有拿坦业。","notes":[]},{"n":22,"t":"在以利亚实、耶何耶大、约哈难、押杜亚的时代，利未人的族长都记在册上，祭司也一样，直到波斯王大流士在位的时候。","notes":[]},{"n":23,"t":"利未人作族长的记在史籍上，一直记到以利亚实的儿子约哈难的时代。","notes":[]},{"n":24,"t":"利未人的族长是哈沙比雅、示利比、甲篾的儿子耶书亚，他们的弟兄站在他们的对面，照神人大卫的命令按着班次赞美称谢。","notes":["“甲篾的儿子耶书亚”：原文另译“宾内、甲篾、耶书亚”；参尼10．9，12．8。"]},{"n":25,"t":"玛他尼、八布迦、俄巴底亚、米书兰、达们、亚谷是门口的守卫，在库房的门口站岗。","notes":[]},{"n":26,"t":"这些人都在约撒达的孙子，耶书亚的儿子约雅金和尼希米省长，以及以斯拉祭司文士的时代供职。","notes":[]},{"n":27,"t":"为耶路撒冷城墙行奉献礼的时候，众人把各处的利未人召到耶路撒冷，要以称谢、歌唱、敲钹、鼓瑟、弹琴，喜乐地行奉献礼。","notes":[],"heads":["城墙奉献礼"]},{"n":28,"t":"歌唱的人从耶路撒冷的周围聚集，从尼陀法人的村庄、","notes":[]},{"n":29,"t":"伯．吉甲，以及迦巴和亚斯玛弗的田地而来；因为歌唱的人在耶路撒冷四围为自己建立了村庄。","notes":[]},{"n":30,"t":"祭司和利未人就洁净自己，也洁净百姓，以及城门和城墙。","notes":[]},{"n":31,"t":"我带犹大的领袖上城墙，把称谢的人分为两大队，在城墙上往右边的粪厂门行进，","notes":[]},{"n":32,"t":"在他们后面行进的有何沙雅与犹大一半的领袖，","notes":[]},{"n":33,"t":"又有亚撒利雅、以斯拉、米书兰、","notes":[]},{"n":34,"t":"犹大、便雅悯、示玛雅、耶利米。","notes":[]},{"n":35,"t":"还有祭司的子孙，吹号的有撒迦利亚；撒迦利亚是约拿单的儿子，约拿单是示玛雅的儿子，示玛雅是玛他尼的儿子，玛他尼是米该亚的儿子，米该亚是撒刻的儿子，撒刻是亚萨的儿子；","notes":[]},{"n":36,"t":"又有撒迦利亚的弟兄示玛雅、亚撒利、米拉莱、基拉莱、玛艾、拿坦业、犹大、哈拿尼，各拿着神人大卫的乐器，由以斯拉文士在前面引领。","notes":[]},{"n":37,"t":"他们经过泉门往前，登大卫城的台阶，上城墙的斜坡，从大卫宫殿之上，直到朝东的水门。","notes":[]},{"n":38,"t":"第二队称谢的人要往反方向而行。我和一半的百姓在城墙上跟随他们，从炉楼之上，直到宽墙；","notes":[]},{"n":39,"t":"又过了以法莲门、古门、鱼门、哈楠业楼、哈米亚楼，直到羊门，就在护卫门站住。","notes":[]},{"n":40,"t":"于是，这两队称谢的人连同我和一半跟随我的官长，站在神的殿里。","notes":[]},{"n":41,"t":"还有以利亚金、玛西雅、米拿民、米该亚、以利约乃、撒迦利亚、哈楠尼亚等吹号的祭司；","notes":[]},{"n":42,"t":"又有玛西雅、示玛雅、以利亚撒、乌西、约哈难、玛基雅、以拦和以谢。歌唱的大声唱歌，有伊斯拉希雅作指挥。","notes":[]},{"n":43,"t":"那日，众人献上丰盛的祭物，并且欢乐，因为神使他们大大欢乐，连妇女带孩童也都欢乐，甚至从远处都可听到耶路撒冷的欢声。","notes":[]},{"n":44,"t":"当日，有些人受派管理库房，把举祭、初熟之物，和所取的十一奉献，按各城的田地，照律法所定，归给祭司和利未人的份，都收在库房里。犹大人因祭司和利未人供职就欢乐。","notes":[],"heads":["圣殿的各种职责"]},{"n":45,"t":"祭司和利未人遵守神所吩咐的，守洁净礼。歌唱的和门口的守卫照着大卫和他儿子所罗门的命令也如此行。","notes":[]},{"n":46,"t":"古时，在大卫和亚萨的日子，有歌唱者的指挥，也有赞美称谢神的诗歌。","notes":[]},{"n":47,"t":"在所罗巴伯和尼希米的时代，以色列众人把歌唱者和门口的守卫每日当得的份供给他们，又把给利未人的分别出来；利未人又把给亚伦子孙的分别出来。","notes":[]}]},"13":{"heading":"与外邦人隔离","verses":[{"n":1,"t":"在那日，百姓听到人朗读摩西的律法书，发现书上写着，亚扪人和摩押人永不可入神的会；","notes":[]},{"n":2,"t":"因为他们没有拿食物和水来迎接以色列人，却雇了巴兰诅咒他们，但我们的神使那诅咒变为祝福。","notes":[]},{"n":3,"t":"以色列人听见这律法，就与所有不同族群的人分别出来。","notes":[]},{"n":4,"t":"在这之前，与多比雅结亲的以利亚实祭司，受派管理我们神殿中的库房，","notes":[],"heads":["尼希米的改革"]},{"n":5,"t":"为多比雅预备了一间大屋子，就是从前收存素祭、乳香、器皿，和照例供给利未人、歌唱者、门口守卫的五谷、新酒和新油的十分之一，以及归祭司之举祭的屋子。","notes":[]},{"n":6,"t":"当这一切事发生的时候，我不在耶路撒冷，因为巴比伦王亚达薛西三十二年，我回到王那里。过了多日，我又向王告假。","notes":[]},{"n":7,"t":"我来到耶路撒冷，才知道以利亚实为多比雅所做、在神殿的院内为他预备屋子的那件恶事。","notes":[]},{"n":8,"t":"我非常愤怒，就把多比雅的一切家具都从屋子里抛出去。","notes":[]},{"n":9,"t":"我又吩咐人洁净这屋子，然后将神殿的器皿、素祭和乳香搬回那里。","notes":[]},{"n":10,"t":"我发现利未人当得的份无人供给他们，甚至供职的利未人与歌唱的都各奔回自己的田地去了。","notes":[]},{"n":11,"t":"我就斥责官长说：“你们为何不顾神的殿呢？”于是我召集利未人，使他们在自己的岗位上供职。","notes":[]},{"n":12,"t":"犹大众人就把五谷、新酒和新油的十分之一送入库房。","notes":[]},{"n":13,"t":"我派示利米雅祭司、撒督文士和利未人毗大雅作司库管理库房，副手是哈难；哈难是撒刻的儿子，撒刻是玛他尼的儿子；这些人都是忠实的，他们的职务是分派他们弟兄所当得的份。","notes":[]},{"n":14,"t":"我的神啊，求你因这事记念我，不要涂去我为神的殿与其中的礼仪所献的忠心。","notes":[]},{"n":15,"t":"那些日子，我在犹大见有人在安息日踹榨酒池，搬运禾捆驮在驴上，又把酒、葡萄、无花果和各样的担子在安息日扛入耶路撒冷，我就在他们卖食物的那日警戒他们。","notes":[]},{"n":16,"t":"有一些住在城里的推罗人也把鱼和各样货物运进来，甚至在耶路撒冷，在安息日卖给犹大人。","notes":[]},{"n":17,"t":"我就斥责犹大的贵族，对他们说：“你们怎么会做这恶事干犯安息日呢！","notes":[]},{"n":18,"t":"你们祖先岂不是这样做，以致我们的神使一切灾祸临到我们和这城吗？你们竟干犯安息日，使愤怒越发临到以色列！”","notes":[]},{"n":19,"t":"安息日前一日黄昏的时候，我吩咐人把耶路撒冷城门锁上；我又吩咐，不过安息日不准开门。我也派几个仆人在城门口站岗，免得有人在安息日挑担子进城。","notes":[]},{"n":20,"t":"于是商人和贩卖各样货物的人，有一两次在耶路撒冷城外过夜。","notes":[]},{"n":21,"t":"我警告他们说：“你们为何在城墙前过夜呢？若再这样，我必下手办你们。”从此以后，他们在安息日就不再来了。","notes":[]},{"n":22,"t":"我吩咐利未人洁净自己来守城门，使安息日分别为圣。我的神啊，求你因这事记念我，照你丰盛的慈爱怜悯我。","notes":[]},{"n":23,"t":"那些日子，我又看见犹太人娶了亚实突、亚扪和摩押的女子为妻。","notes":[]},{"n":24,"t":"他们的儿女，一半说亚实突话，或其他种族的方言，不会说犹大话。","notes":[]},{"n":25,"t":"我就斥责他们，诅咒他们，打了他们几个人，拔下他们的胡须，叫他们指着神起誓：“你们不可把自己的女儿嫁给外邦人的儿子，也不可为自己和儿子娶他们的女儿。","notes":[]},{"n":26,"t":"以色列王所罗门不也在这样的事上犯罪吗？在许多国家中并没有一位王像他，蒙他神喜爱，神立他作王治理全以色列。然而，连他也被外邦女子引诱犯罪。","notes":[]},{"n":27,"t":"我们岂能听凭你们行这一切大恶，娶外邦女子干犯我们的神呢？”","notes":[]},{"n":28,"t":"以利亚实大祭司的孙子，耶何耶大的一个儿子是和伦人参巴拉的女婿，我就把他从我这里赶出去。","notes":[]},{"n":29,"t":"我的神啊，求你记得他们的罪，因为他们玷污了祭司的职分，违背祭司和利未人的约。","notes":[]},{"n":30,"t":"这样，我洁净他们，使他们脱离属外邦人的一切；我又分派祭司和利未人的班次，使他们各尽其职，","notes":[]},{"n":31,"t":"按定期奉献木柴和初熟的土产。我的神啊，求你记念我，施恩于我。","notes":[]}]}},"EST":{"1":{"heading":"亚哈随鲁王废瓦实提王后","verses":[{"n":1,"t":"这事发生在亚哈随鲁的时代，亚哈随鲁从印度直到古实统治一百二十七个省，","notes":[]},{"n":2,"t":"就是亚哈随鲁王在书珊城堡中坐国度王位的那些日子。","notes":[]},{"n":3,"t":"他在位第三年，为所有官员和臣仆摆设宴席，有波斯和玛代的权贵，各省的贵族与领袖在他面前。","notes":[]},{"n":4,"t":"他把他荣耀国度的丰富和他伟大威严的尊贵给他们看了许多日子，共一百八十天。","notes":[]},{"n":5,"t":"这些日子满了，王又为所有住书珊城堡的百姓，无论大小，在御花园的院子里摆设宴席七日。","notes":[]},{"n":6,"t":"院子里有白色棉和蓝色线，用细麻绳、紫色绳系在白玉石柱的银环上，又有金银的床榻摆在红、白、黄、黑大理石镶嵌的地上。","notes":[]},{"n":7,"t":"用金器皿盛酒，有很多不同的器皿，照王的厚意提供丰富的御酒。","notes":[]},{"n":8,"t":"饮酒有规定，不准勉强人，因为王吩咐宫里所有的臣宰，让人各随己意。","notes":["“饮酒有规定，不准勉强人”或译“饮酒用大酒壶，没有限制”。"]},{"n":9,"t":"瓦实提王后在亚哈随鲁王的宫内也为妇女摆设宴席。","notes":[]},{"n":10,"t":"第七日，亚哈随鲁王饮酒，心中快乐，就吩咐在他面前侍立的七个太监米户幔、比斯他、哈波拿、比革他、亚拔他、西达、甲迦，","notes":[]},{"n":11,"t":"请瓦实提王后头戴王后的冠冕到王面前，让各民族和官员观看她的美貌，因为她容貌美丽。","notes":[]},{"n":12,"t":"瓦实提王后却不肯遵照太监所传的王命前来，所以王非常愤怒，怒火中烧。","notes":[]},{"n":13,"t":"按王的常规，办事必先询问知例明法的人。那时，王询问通达时务的智慧人，","notes":[]},{"n":14,"t":"就是在王左右常见王面、在国中坐高位的波斯和玛代的七个大臣，甲示拿、示达、押玛他、他施斯、米力、玛西拿、米慕干：","notes":[]},{"n":15,"t":"“瓦实提王后不遵照太监所传的王命，照例应当怎样办理呢？”","notes":[]},{"n":16,"t":"米慕干在王和众官长面前回答说：“瓦实提王后这事，不但得罪王，并且有害于亚哈随鲁王各省的臣民。","notes":[]},{"n":17,"t":"因为王后这事必传到众妇人那里，她们就会藐视自己的丈夫，说：‘亚哈随鲁王吩咐瓦实提王后到王面前，她却不来。’","notes":[]},{"n":18,"t":"今日波斯和玛代的众夫人听见王后这事，必向王所有的官长照样说，如此必造成无数的藐视和愤怒。","notes":[]},{"n":19,"t":"王若以为好，请降谕旨，写在波斯和玛代人的条例中，永不更改，不准瓦实提再到亚哈随鲁王面前，把她王后的位分赐给比她更好的妃子。","notes":[]},{"n":20,"t":"王的谕旨一传遍全国，国土纵然辽阔，凡作妻子的，无论丈夫是尊贵或卑贱，都必尊敬他。”","notes":[]},{"n":21,"t":"王和众官长都以这话为美，王就照米慕干的建议去做。","notes":[]},{"n":22,"t":"王下诏书，用各省的文字、各族的语言通知各省，使凡作丈夫的在家中作主，各说本地的语言。","notes":["七十士译本没有“各说本地的语言”。"]}]},"2":{"heading":"以斯帖被立为王后","verses":[{"n":1,"t":"这些事以后，亚哈随鲁王的愤怒平息，就想起瓦实提和她所做的，以及自己怎样降旨办她。","notes":[]},{"n":2,"t":"于是王的侍臣对王说：“请派人为王寻找美貌的少女；","notes":[]},{"n":3,"t":"请王派官员在国中各省招聚所有美貌的少女到书珊城堡的女院，交给王所派掌管女子的太监希该，给她们香膏涂抹。","notes":[]},{"n":4,"t":"王眼中看为好的女子可以立为王后，代替瓦实提。”王以这话为美，就照样做。","notes":[]},{"n":5,"t":"书珊城堡中有一个犹太人名叫末底改，是便雅悯人基士的曾孙，示每的孙子，睚珥的儿子。","notes":[]},{"n":6,"t":"从前巴比伦王尼布甲尼撒把犹大王耶哥尼雅和百姓从耶路撒冷掳来，末底改也在被掳的人当中。","notes":["“耶哥尼雅”又名“约雅斤”；参王下24．6。"]},{"n":7,"t":"末底改抚养他叔叔的女儿哈大沙，就是以斯帖，因为她没有父母。这女子容貌美丽；她父母死了，末底改收她为自己的女儿。","notes":[]},{"n":8,"t":"王的谕旨和敕令传出之后，许多女子被招聚到书珊城堡，交给掌管女子的希该；以斯帖也被送入王宫，交给希该。","notes":[]},{"n":9,"t":"希该眼中宠爱以斯帖，就恩待她，急忙给她涂抹的香膏和当得的份，又从王宫里挑选七个宫女来服事她，使她和她的宫女搬入女院上好的房屋。","notes":[]},{"n":10,"t":"以斯帖未曾将自己的籍贯宗族告诉人，因为末底改嘱咐她不可叫人知道。","notes":[]},{"n":11,"t":"末底改天天在女院前徘徊，要知道以斯帖是否平安，过得如何。","notes":[]},{"n":12,"t":"众女子照例先涂抹身体十二个月：六个月用没药油，六个月用香料和涂抹的香膏。满了日期，每个女子挨次进去朝见亚哈随鲁王。","notes":[]},{"n":13,"t":"女子进去朝见王是这样：从女院到王宫的时候，凡她所要的都必给她带进去。","notes":[]},{"n":14,"t":"晚上她进去，次日回到另一个女院，交给掌管妃嫔的太监沙甲。除非王喜爱她，再提名召她，她就不再进去见王。","notes":[]},{"n":15,"t":"末底改的叔叔亚比孩的女儿，就是末底改收为自己女儿的以斯帖，按次序要进去朝见王的时候，除了掌管女子的太监希该所分派给她的，她别无所求。凡看见以斯帖的都喜欢她。","notes":[]},{"n":16,"t":"亚哈随鲁王第七年十月，就是提别月，以斯帖被引入宫中朝见王。","notes":[]},{"n":17,"t":"王爱以斯帖过于众女子，她在王面前蒙宠爱胜过众少女。王把王后的冠冕戴在她头上，立她为王后，代替瓦实提。","notes":[]},{"n":18,"t":"王为所有的官长和臣仆摆设大宴席，称为以斯帖的宴席，又豁免各省的租税，并照王的厚意大颁赏赐。","notes":[]},{"n":19,"t":"第二次招聚少女的时候，末底改坐在朝门。","notes":[],"heads":["末底改救王的命"]},{"n":20,"t":"以斯帖遵照末底改所嘱咐的，没有将籍贯宗族告诉人；以斯帖照末底改的吩咐去做，正如受他抚养的时候一样。","notes":[]},{"n":21,"t":"那时候，末底改坐在朝门，王有两个守门的太监，辟探和提列，恼恨亚哈随鲁王，想要下手害他。","notes":[]},{"n":22,"t":"末底改知道了这件事，就告诉以斯帖王后。以斯帖以末底改的名向王报告。","notes":[]},{"n":23,"t":"这事经过查究后发现是真的，二人就被挂在木头上。这事在王面前记录在史籍上。","notes":[]}]},"3":{"heading":"哈曼阴谋除灭犹大人","verses":[{"n":1,"t":"这些事以后，亚哈随鲁王使亚甲人哈米大他的儿子哈曼尊大，提升了他，叫他的爵位超过所有与他同朝的官长。","notes":[]},{"n":2,"t":"在朝门，王所有的臣仆都跪拜哈曼，因为王如此吩咐，但末底改不跪不拜。","notes":[]},{"n":3,"t":"在朝门，王的臣仆对末底改说：“你为何违背王的命令呢？”","notes":[]},{"n":4,"t":"他们天天劝他，他还是不听，他们就告诉哈曼，要看末底改的事是否站得住，因他已经告诉他们自己是犹太人。","notes":[]},{"n":5,"t":"哈曼见末底改不跪不拜，就非常愤怒。","notes":[]},{"n":6,"t":"有人把末底改的宗族告诉哈曼。哈曼看下手只害末底改一人是小事，还图谋要灭绝亚哈随鲁王全国所有的犹太人，就是末底改的宗族。","notes":[]},{"n":7,"t":"亚哈随鲁王十二年正月，就是尼散月，人在哈曼面前抽普珥，普珥即签，要定何月何日；抽到了十二月，就是亚达月。","notes":[]},{"n":8,"t":"哈曼对亚哈随鲁王说：“有一民族散居在王国各省的民族中，与众不同；他们的律例与万民的律例不同，也不守王的律例，所以容留他们对王无益。","notes":[]},{"n":9,"t":"王若以为好，请下谕旨灭绝他们，我就捐一万他连得银子交给管财政的人，纳入王的府库。”","notes":[]},{"n":10,"t":"于是王从自己手上摘下戒指给犹太人的仇敌，亚甲人哈米大他的儿子哈曼。","notes":[]},{"n":11,"t":"王对哈曼说：“这银子赐给你，这民族也交给你，可以照你眼中看为好的待他们。”","notes":[]},{"n":12,"t":"正月十三日，王的一些书记受召而来，照着哈曼一切所吩咐的，用各省的文字、各族的语言，奉亚哈随鲁王的名写谕旨，又用王的戒指盖印，传给王的总督、各省的省长，以及各族的领袖。","notes":[]},{"n":13,"t":"诏书由信差传到王的各省，限令一日之内，就是在十二月，亚达月十三日，把所有的犹太人，无论老少妇女孩子，全然剪除，杀戮灭绝，并抢夺他们的财产。","notes":[]},{"n":14,"t":"这谕旨的抄本以敕令的方式在各省颁布，通知各族，预备等候那日。","notes":[]},{"n":15,"t":"信差奉王的命令急忙起行，敕令传遍了书珊城堡。王同哈曼坐下饮酒，书珊城堡却陷入慌乱中。","notes":[]}]},"4":{"heading":"末底改求以斯帖帮忙","verses":[{"n":1,"t":"末底改知道所发生的这一切事，就撕裂衣服，披麻蒙灰，在城中行走，痛哭哀号。","notes":[]},{"n":2,"t":"他到了朝门前就停住脚步，因为穿麻衣的不可进朝门。","notes":[]},{"n":3,"t":"王的谕旨和敕令所到的各省各处，犹太人都极其悲哀，禁食哭泣哀号，许多人躺在麻布和炉灰中。","notes":[]},{"n":4,"t":"以斯帖王后的宫女和太监来把这事告诉以斯帖，她非常忧愁，就送衣服给末底改穿，要他脱下身上的麻衣，他却不肯接受。","notes":[]},{"n":5,"t":"以斯帖把王所派伺候她的一个太监哈他革召来，吩咐他去见末底改，要知道到底发生了什么事，为何如此。","notes":[]},{"n":6,"t":"于是哈他革出来，到朝门前的广场见末底改。","notes":[]},{"n":7,"t":"末底改把自己遭遇的一切，以及哈曼为灭绝犹太人答应捐入王库的银数都告诉了他；","notes":[]},{"n":8,"t":"又把那传遍书珊、要灭绝犹太人的谕旨抄本交给哈他革，要他给以斯帖看，并向她说明，嘱咐她去晋见王，向王恳求，为本族的人在王面前请命。","notes":[]},{"n":9,"t":"哈他革回来，把末底改的话告诉以斯帖。","notes":[]},{"n":10,"t":"以斯帖吩咐哈他革去见末底改，说：","notes":[]},{"n":11,"t":"“王所有的臣仆和各省的百姓都知道有一个定例，若未奉召见，擅入内院见王的，无论男女必被处死；除非王向他伸出金杖，不得存活。但我没有被召进去见王已经有三十天了。”","notes":[]},{"n":12,"t":"他们把以斯帖的话告诉末底改。","notes":[]},{"n":13,"t":"末底改托人回覆以斯帖说：“你不要自己以为在王宫里强过任何犹太人，得以幸免。","notes":[]},{"n":14,"t":"此时你若闭口不言，犹太人必从别处得解脱，蒙拯救；你和你父家必致灭亡。焉知你得了王后的位分不是为现今的机会吗？”","notes":[]},{"n":15,"t":"以斯帖吩咐人回覆末底改说：","notes":[]},{"n":16,"t":"“你当去召集书珊所有的犹太人，为我禁食三昼三夜，不吃不喝；我和我的宫女也要这样禁食。然后我违例去晋见王，我若死就死吧！”","notes":[]},{"n":17,"t":"于是末底改照以斯帖一切所吩咐的去做。","notes":[]}]},"5":{"heading":"以斯帖为王和哈曼设宴","verses":[{"n":1,"t":"第三日，以斯帖穿上朝服，站立在王宫的内院，对着王宫。王在殿里坐在宝座上，对着殿的门。","notes":[]},{"n":2,"t":"王见以斯帖王后站在院内，她在王的眼中得恩宠，王向她伸出手中的金杖。以斯帖往前去摸杖头。","notes":[]},{"n":3,"t":"王对她说：“以斯帖王后啊，你要什么？无论你求什么，就是国的一半也必赐给你。”","notes":[]},{"n":4,"t":"以斯帖说：“王若以为好，请王带着哈曼今日赴我为王预备的宴席。”","notes":[]},{"n":5,"t":"王说：“叫哈曼速速照以斯帖的话去做。”于是王带着哈曼赴以斯帖所预备的宴席。","notes":[]},{"n":6,"t":"在宴席喝酒的时候，王又对以斯帖说：“你要什么，必赐给你；无论你求什么，就是国的一半也必给你。”","notes":[]},{"n":7,"t":"以斯帖回答说：“我所要的、我所求的，嗯..。","notes":[]},{"n":8,"t":"我若在王眼前蒙恩，王若愿意赐我所要的，准我所求的，就请王和哈曼再赴我为你们预备的宴席。明日我必照王的话去做。”","notes":[]},{"n":9,"t":"那日哈曼心中快乐，欢欢喜喜地出来。但是当他看见末底改在朝门不站起来，也不因他动一下，就满心恼怒末底改。","notes":[],"heads":["哈曼阴谋杀末底改"]},{"n":10,"t":"哈曼忍着气回家，叫人请他的一些朋友和他妻子细利斯来。","notes":[]},{"n":11,"t":"哈曼将他的荣华富贵、众多的儿女，和王使他尊大、提升他高过官长和臣仆的事，都述说给他们听。","notes":[]},{"n":12,"t":"哈曼又说：“以斯帖王后预备宴席，除了我之外不许别人随王赴席。明日王后又请我随王赴席。","notes":[]},{"n":13,"t":"只是每当我看见犹太人末底改坐在朝门，这一切对我就都毫无意义了。”","notes":[]},{"n":14,"t":"他的妻子细利斯和他所有的朋友对他说：“叫人做一个五十肘高的木架，早晨求王把末底改挂在其上，然后你可以欢欢喜喜随王赴席。”哈曼认为这话很好，就叫人做了木架。","notes":[]}]},"6":{"heading":"王赐末底改荣誉","verses":[{"n":1,"t":"那夜王睡不着觉，吩咐人取历史书，就是史籍，念给他听，","notes":[]},{"n":2,"t":"发现书上写着：王有两个守门的太监辟探和提列，想要下手害亚哈随鲁王，末底改告发了这件事。","notes":[]},{"n":3,"t":"王说：“末底改做了这事，有没有赐给他什么尊荣或高位呢？”伺候王的臣仆说：“没有赐给他什么。”","notes":[]},{"n":4,"t":"王说：“谁在院子里？”那时哈曼正进入王宫的外院，要请王把末底改挂在他所预备的木架上。","notes":[]},{"n":5,"t":"王的臣仆对他说：“看哪，哈曼站在院子里。”王说：“叫他进来。”","notes":[]},{"n":6,"t":"哈曼就进去。王对他说：“王所喜爱要赐尊荣的人，当如何待他呢？”哈曼心里说：“王所喜爱要赐尊荣的人，除了我，还有谁呢？”","notes":[]},{"n":7,"t":"哈曼就对王说：“王所喜爱要赐尊荣的人，","notes":[]},{"n":8,"t":"当把王所穿的王袍拿来，牵了戴冠的御马，","notes":[]},{"n":9,"t":"把王袍和御马都交给王一个极尊贵的大臣，吩咐人把王袍给王所喜爱要赐尊荣的人穿上，领他骑着御马走遍城里的广场，在他面前宣告：‘王所喜爱要赐尊荣的人，就是这样待他。’”","notes":[]},{"n":10,"t":"王对哈曼说：“你速速把这王袍和御马，照你所说的，向坐在朝门的犹太人末底改去做。凡你所说的，一样都不可缺。”","notes":[]},{"n":11,"t":"于是哈曼把王袍给末底改穿上，领他骑着御马走遍城里的广场，在他面前宣告：“王所喜爱要赐尊荣的人，就是这样待他。”","notes":[]},{"n":12,"t":"末底改仍回到朝门，哈曼却忧忧闷闷地蒙着头，急忙回家去了。","notes":[]},{"n":13,"t":"哈曼把所遭遇的一切都说给他妻子细利斯和他所有的朋友听。他的智囊团和他的妻子细利斯对他说：“你在末底改面前开始败落；他既是犹太人，你必不能胜过他，终必在他面前败落。”","notes":[]},{"n":14,"t":"他们正跟哈曼说话的时候，王的几位太监来了，催哈曼快去赴以斯帖所预备的宴席。","notes":[]}]},"7":{"heading":"哈曼被处死","verses":[{"n":1,"t":"王带着哈曼来赴以斯帖王后的宴席。","notes":[]},{"n":2,"t":"第二天在宴席喝酒的时候，王又对以斯帖说：“以斯帖王后啊，你要什么，必赐给你；无论你求什么，就是国的一半也必给你。”","notes":[]},{"n":3,"t":"以斯帖王后回答说：“王啊，我若在你眼前蒙恩，王若以为好，我所要的，是王把我的性命赐给我；我所求的，是求我的本族。","notes":[]},{"n":4,"t":"因为我和我的本族被出卖了，要被剪除，杀戮，灭绝。我们若被卖为奴为婢，我就闭口不言；但我们的痛苦比起王的损失，算不得什么。”","notes":["“但我们的痛苦...算不得什么”或译“但敌人所得的，抵不过王的损失”。"]},{"n":5,"t":"亚哈随鲁王问以斯帖王后说：“擅敢起意如此行的是谁？这人在哪里呢？”","notes":[]},{"n":6,"t":"以斯帖说：“仇人敌人就是这恶人哈曼！”哈曼在王和王后面前非常惊惶。","notes":[]},{"n":7,"t":"王大怒，起来离开酒席往御花园去了。哈曼见王定意要加罪于他，就留下来求以斯帖王后救他的命。","notes":[]},{"n":8,"t":"王从御花园回到酒席厅，见哈曼伏在以斯帖所靠的榻上；王说：“他竟敢在宫内、在我面前凌辱王后吗？”这话一出王口，哈曼的脸就被蒙住了。","notes":[]},{"n":9,"t":"有一个伺候王名叫哈波拿的太监说：“看哪，哈曼还为那报告给王、救王有功的末底改做了一个五十肘高的木架，现今立在哈曼的家里。”王说：“把哈曼挂在木架上。”","notes":[]},{"n":10,"t":"于是哈曼被挂在他为末底改所预备的木架上；王的愤怒才平息了。","notes":[]}]},"8":{"heading":"犹太人的反击","verses":[{"n":1,"t":"那日，亚哈随鲁王把犹太人的仇敌哈曼的家产赐给以斯帖王后。末底改也来到王面前，因为以斯帖已经告诉王，末底改跟她是什么关系。","notes":[]},{"n":2,"t":"王摘下自己的戒指，就是从哈曼取回的，给了末底改。以斯帖派末底改管理哈曼的家产。","notes":[]},{"n":3,"t":"以斯帖又在王面前求情，俯伏在他脚前，流泪哀求他阻止亚甲人哈曼害犹太人的恶谋。","notes":[]},{"n":4,"t":"王向以斯帖伸出金杖，以斯帖就起来，站在王面前，","notes":[]},{"n":5,"t":"说：“王若以为好，我若在王面前蒙恩，王若认为合宜，我若在王眼前得喜悦，请王下谕旨，废除亚甲人哈米大他的儿子哈曼设谋，要杀灭王各省的犹太人所颁的诏书。","notes":[]},{"n":6,"t":"我何忍见我本族的人受害？何忍见我同宗的人被灭呢？”","notes":[]},{"n":7,"t":"亚哈随鲁王对以斯帖王后和犹太人末底改说：“因为哈曼要下手害犹太人，看哪，我已把他的家产赐给以斯帖，也把哈曼挂在木架上了。","notes":[]},{"n":8,"t":"你们可以照你们看为好的，奉王的名写谕旨给犹太人，用王的戒指盖印；因为奉王的名所写、用王的戒指盖印的谕旨是不能废除的。”","notes":[]},{"n":9,"t":"三月，就是西弯月二十三日，当时王的一些书记受召而来，按着末底改所吩咐的，用各省的文字、各族的语言，以及犹太人的文字语言写谕旨，传给那从印度直到古实一百二十七省的犹太人，以及总督、省长和领袖。","notes":[]},{"n":10,"t":"末底改奉亚哈随鲁王的名写谕旨，用王的戒指盖印，交给信差们骑上御用的王室快马去颁布。","notes":[]},{"n":11,"t":"王准各城各镇的犹太人在一日之内，在十二月，就是亚达月的十三日聚集，在亚哈随鲁王的各省保护自己的性命，剪除，杀戮，灭绝那要攻击犹太人的各省各族所有的军队，以及他们的妻子儿女，夺取他们的财产为掠物。","notes":[],"end":12},{"n":13,"t":"这谕旨的抄本以敕令的方式在各省颁布，通知各族，使犹太人预备等候那日，好在仇敌身上报仇。","notes":[]},{"n":14,"t":"于是骑御用快马的信差奉王命催促，急忙起行；敕令传遍了书珊城堡。","notes":[]},{"n":15,"t":"末底改穿着蓝色白色的朝服，头戴大金冠冕，又穿紫色细麻布的外袍，从王面前出来；书珊城充满了欢乐的呼声。","notes":[]},{"n":16,"t":"犹太人有光荣，欢喜快乐，得享尊贵。","notes":[]},{"n":17,"t":"王的谕旨和敕令所到的各省各城，犹太人都欢喜快乐，摆设宴席，以那日为吉日。国中许多民族的人因惧怕犹太人，就自称为犹太人。","notes":[]}]},"9":{"heading":"犹太人除灭仇敌","verses":[{"n":1,"t":"十二月，就是亚达月十三日，王的谕旨和敕令要执行的那一日，犹太人的仇敌盼望制伏他们，但犹太人反倒制伏了恨他们的人。","notes":[]},{"n":2,"t":"犹太人在亚哈随鲁王各省的城里聚集，下手击杀那些要害他们的人。没有人能在他们面前站立得住，因为各民族都惧怕他们。","notes":[]},{"n":3,"t":"各省的领袖、总督、省长，和办理王事务的人，因惧怕末底改，就都帮助犹太人。","notes":[]},{"n":4,"t":"末底改在朝中为大，名声传遍各省；末底改这人的权势日渐扩大。","notes":[]},{"n":5,"t":"犹太人用刀击杀所有的仇敌，杀灭他们，随意待那些恨他们的人。","notes":[]},{"n":6,"t":"在书珊城堡中，犹太人杀灭了五百人。","notes":[]},{"n":7,"t":"他们杀了巴珊大他、达分、亚斯帕他、","notes":[]},{"n":8,"t":"破拉他、亚大利雅、亚利大他、","notes":[]},{"n":9,"t":"帕玛斯他、亚利赛、亚利代、瓦耶撒他；","notes":[]},{"n":10,"t":"这十人都是哈米大他的孙子，犹太人的仇敌哈曼的儿子。犹太人却没有下手夺取财物。","notes":[]},{"n":11,"t":"那日，书珊城堡中被杀的人数呈报到王面前。","notes":[]},{"n":12,"t":"王对以斯帖王后说：“犹太人在书珊城堡中杀灭了五百人，又杀了哈曼的十个儿子，在王其余的各省不知如何。你要什么，必赐给你；你还求什么，也必为你成就。”","notes":[]},{"n":13,"t":"以斯帖说：“王若以为好，求你允准书珊的犹太人，明日也照今日的谕旨去做，并把哈曼十个儿子的尸体挂在木架上。”","notes":[]},{"n":14,"t":"王允准这么做。敕令传遍书珊，哈曼十个儿子的尸体被挂了起来。","notes":[]},{"n":15,"t":"亚达月十四日，在书珊的犹太人又聚集，在书珊杀了三百人，却没有下手夺取财物。","notes":[]},{"n":16,"t":"亚达月十三日，在王各省其余的犹太人也都聚集，保护自己的性命，摆脱仇敌得享平安。他们杀了七万五千个恨他们的人，却没有下手夺取财物；十四日他们休息，以这日为设宴欢乐的日子。","notes":[],"end":17},{"n":18,"t":"但书珊的犹太人却在十三日、十四日聚集；十五日休息，以这日为设宴欢乐的日子。","notes":[]},{"n":19,"t":"所以住在无城墙的乡村的犹太人，都以亚达月十四日为设宴欢乐的吉日，彼此馈送礼物。","notes":[]},{"n":20,"t":"末底改记录这些事，写信给亚哈随鲁王各省远近所有的犹太人，","notes":[],"heads":["普珥日"]},{"n":21,"t":"吩咐他们每年守亚达月十四、十五两日，","notes":[]},{"n":22,"t":"以这两日为犹太人摆脱仇敌得享平安、转忧为喜、转悲为乐的吉日，并在这两日设宴欢乐，彼此馈送礼物，周济穷人。","notes":[]},{"n":23,"t":"于是，犹太人照末底改所写给他们的，把开始所做的作为遵守的定例。","notes":[]},{"n":24,"t":"因为犹太人的仇敌亚甲人哈米大他的儿子哈曼设谋要杀害犹太人，抽普珥，普珥即签，为要杀尽灭绝他们；","notes":[]},{"n":25,"t":"但这阴谋到了王面前，王却降旨使哈曼谋害犹太人的恶事归到他自己的头上，他和他的众子都被挂在木架上。","notes":["“这阴谋”或译“以斯帖”。"]},{"n":26,"t":"所以犹太人照着普珥这名字称这两日为普珥日。他们因这信上一切的话，又因所看见所遇见的事，","notes":[]},{"n":27,"t":"就规定自己与后裔，以及归化他们的人，每年按所写的、按时守这两日，永久不废。","notes":[]},{"n":28,"t":"各省各城、世世代代、家家户户都记念并守这两日，使这普珥日在犹太人中不可废掉，在他们后裔中也永不遗忘。","notes":[]},{"n":29,"t":"亚比孩的女儿以斯帖王后和犹太人末底改以全权写第二封信，坚立这普珥日，","notes":[]},{"n":30,"t":"送信给亚哈随鲁王国中一百二十七省所有的犹太人，祝他们平安和安稳，","notes":[]},{"n":31,"t":"劝他们遵照犹太人末底改和以斯帖王后所规定的，按时守这普珥日，并照着犹太人为自己与后裔所规定的，禁食与哀求。","notes":[]},{"n":32,"t":"以斯帖规定了守普珥日的条例，这事也记录在书上。","notes":[]}]},"10":{"heading":"亚哈随鲁和末底改的功绩","verses":[{"n":1,"t":"亚哈随鲁王向国中和海岛的人征税。","notes":[]},{"n":2,"t":"他以权柄能力所做的一切，以及他使末底改尊大、提升他的事，岂不都写在玛代和波斯王的史籍上吗？","notes":[]},{"n":3,"t":"犹太人末底改作亚哈随鲁王的宰相，在犹太人中为大，得许多弟兄的喜悦，为本族的人争取福利，为他所有的后代谋求幸福。","notes":[]}]}},"JOB":{"1":{"heading":"撒但试探约伯","verses":[{"n":1,"t":"乌斯地有一个人名叫约伯。这人完全、正直、敬畏神、远离恶事。","notes":[]},{"n":2,"t":"他生了七个儿子，三个女儿。","notes":[]},{"n":3,"t":"他的家产有七千只羊，三千匹骆驼，五百对牛，五百匹母驴，并有许多仆婢。这人在东方人中为至大。","notes":[]},{"n":4,"t":"他的儿子按着日子各在自己家里摆设宴席，派人去请他们的三个姊妹来，与他们一同吃喝。","notes":[]},{"n":5,"t":"宴席的日子过了，约伯派人去叫他们自洁。他清早起来，按着他们众人的数目献燔祭，因为他说：“恐怕我的儿子犯了罪，心中背弃神。”约伯常常这样行。","notes":["“背弃”：原文是“诅咒”；11节同。"]},{"n":6,"t":"有一天，神的众使者来侍立在耶和华面前，撒但也来在其中。","notes":["“神的众使者”：原文直译“神的众子”。"]},{"n":7,"t":"耶和华对撒但说：“你从哪里来？”撒但回答耶和华说：“我从地上走来走去，在那里往返。”","notes":[]},{"n":8,"t":"耶和华对撒但说：“你曾用心察看我的仆人约伯没有？地上再没有人像他那样完全、正直、敬畏神、远离恶事。”","notes":[]},{"n":9,"t":"撒但回答耶和华说：“约伯敬畏神，岂是无故呢？","notes":[]},{"n":10,"t":"你岂不是四面圈上篱笆围护他和他的家，以及他一切所有的吗？他手所做的都蒙你赐福，他的家产也在地上增多。","notes":[]},{"n":11,"t":"但你若伸手毁他一切所有的，他必当面背弃你。”","notes":[]},{"n":12,"t":"耶和华对撒但说：“看哪，凡他所有的都在你手中；只是不可伸手加害于他。”于是撒但从耶和华面前退出去。","notes":[]},{"n":13,"t":"有一天，约伯的儿女正在他们长兄的家里吃饭喝酒，","notes":[],"heads":["约伯丧失儿女和财产"]},{"n":14,"t":"有报信的来见约伯，说：“牛正耕地，母驴在旁边吃草，","notes":[]},{"n":15,"t":"示巴人忽然闯来，把牲畜掳去，并用刀杀了仆人；惟有我一人逃脱，来报信给你。”","notes":[]},{"n":16,"t":"他还说话的时候，又有人来说：“神从天上降下火来，把羊群和仆人都吞灭了；惟有我一人逃脱，来报信给你。”","notes":[]},{"n":17,"t":"他还说话的时候，又有人来说：“迦勒底人分成三队忽然闯来，把骆驼掳去，并用刀杀了仆人；惟有我一人逃脱，来报信给你。”","notes":[]},{"n":18,"t":"他还说话的时候，又有人来说：“你的儿女正在他们长兄的家里吃饭喝酒，","notes":[]},{"n":19,"t":"看哪，有狂风从旷野刮来，袭击房屋的四角，房屋倒塌在年轻人身上，他们就都死了；惟有我一人逃脱，来报信给你。”","notes":[]},{"n":20,"t":"约伯就起来，撕裂外袍，剃了头，俯伏在地敬拜，","notes":[]},{"n":21,"t":"说：“我赤身出于母胎，也必赤身归回；赏赐的是耶和华，收取的也是耶和华。耶和华的名是应当称颂的。”","notes":[]},{"n":22,"t":"在这一切的事上，约伯并没有犯罪，也不以神为狂妄。","notes":[]}]},"2":{"heading":"撒但再试探约伯","verses":[{"n":1,"t":"又有一天，神的众使者来侍立在耶和华面前，撒但也来在其中。","notes":["“神的众使者”：原文直译“神的众子”。"]},{"n":2,"t":"耶和华问撒但说：“你从哪里来？”撒但回答说：“我从地上走来走去，在那里往返。”","notes":[]},{"n":3,"t":"耶和华对撒但说：“你曾用心察看我的仆人约伯没有？地上再没有人像他那样完全、正直、敬畏神、远离恶事。你虽激起我攻击他，无故吞灭他，他仍然持守他的纯正。”","notes":[]},{"n":4,"t":"撒但回答耶和华说：“人以皮代皮，情愿舍去一切所有的，来保全性命。","notes":[]},{"n":5,"t":"但你若伸手伤他的骨头和他的肉，他必当面背弃你。”","notes":["“背弃”：原文是“诅咒”；9节同。"]},{"n":6,"t":"耶和华对撒但说：“看哪，他在你手中，只要留下他的性命。”","notes":[]},{"n":7,"t":"于是撒但从耶和华面前退出去，击打约伯，使他从脚掌到头顶长毒疮。","notes":[]},{"n":8,"t":"约伯就坐在灰烬中，拿瓦片刮身体。","notes":[]},{"n":9,"t":"他的妻子对他说：“你仍然持守你的纯正吗？你背弃神，死了吧！”","notes":[]},{"n":10,"t":"约伯却对她说：“你说话，正如愚顽的妇人。唉！难道我们从神手里得福，不也受祸吗？”在这一切的事上，约伯并没有以口犯罪。","notes":[]},{"n":11,"t":"约伯的三个朋友，提幔人以利法、书亚人比勒达、拿玛人琐法，听说这一切的灾祸临到他身上，各人就从自己的地方相约同来，为他悲伤，安慰他。","notes":[],"heads":["三个朋友来安慰约伯"]},{"n":12,"t":"他们远远地举目观看，认不出他来，就放声大哭。各人撕裂外袍，向空中撒尘土，落在自己的头上。","notes":[]},{"n":13,"t":"他们同他七天七夜坐在地上，一句话也不对他说，因为他们见到了极大的痛苦。","notes":[]}]},"3":{"heading":"约伯诅咒自己","verses":[{"n":1,"t":"此后，约伯开口诅咒自己的生日。","notes":["“自己的生日”：原文是“自己的日子”。"]},{"n":2,"t":"约伯说：","notes":[]},{"n":3,"t":"“愿我生的那日灭没，说‘怀了男胎’的那夜也灭没。","notes":[]},{"n":4,"t":"愿那日变为黑暗，愿神不从上面寻找它，愿亮光不照于其上。","notes":[]},{"n":5,"t":"愿黑暗和死荫索取那日，愿密云停在其上，愿白天的昏暗恐吓它。","notes":["“白天的昏暗”或译“日蚀”。"]},{"n":6,"t":"愿那夜被幽暗夺取，不在一年的日子中喜乐，也不列入月中的数目。","notes":[]},{"n":7,"t":"看哪，愿那夜没有生育，其间也没有欢乐的声音。","notes":[]},{"n":8,"t":"愿那些诅咒日子且能惹动力威亚探的，诅咒那夜。","notes":["“力威亚探”是音译，一种海兽；或译“鳄鱼”。"]},{"n":9,"t":"愿那夜黎明的星宿变为黑暗，盼亮却不亮，也不见晨曦破晓；","notes":["“晨曦破晓”：原文直译“清晨的眼皮”。"]},{"n":10,"t":"因它没有把怀我胎的门关闭，也没有从我的眼中隐藏患难。","notes":[]},{"n":11,"t":"“我为何不出母胎而死？为何不出母腹就气绝呢？","notes":[]},{"n":12,"t":"为何有膝盖接收我？为何有奶哺养我呢？","notes":[]},{"n":13,"t":"不然，我现在已躺卧安睡，而且，早已长眠安息；","notes":[]},{"n":14,"t":"与那些为自己重建荒凉之处，地上的君王和谋士在一起；","notes":[]},{"n":15,"t":"或与把银子装满房屋，拥有金子的王子在一起；","notes":[]},{"n":16,"t":"我为何不像流产的胎儿被埋藏，如同未见光的婴孩？","notes":[]},{"n":17,"t":"在那里恶人止息搅扰，在那里困乏人得享安息，","notes":[]},{"n":18,"t":"被囚的人同得安逸，不再听见监工的声音。","notes":[]},{"n":19,"t":"大的小的都在那里，奴仆脱离主人得自由。","notes":[]},{"n":20,"t":"“遭受患难的人为何有光赐给他呢？心中愁苦的人为何有生命赐给他呢？","notes":[]},{"n":21,"t":"他们等死，却不得死；求死，胜于求隐藏的珍宝。","notes":[]},{"n":22,"t":"他们寻见坟墓，就欢喜快乐，极其高兴。","notes":[]},{"n":23,"t":"这人的道路遮隐，神又四面围困他。","notes":[]},{"n":24,"t":"我吃饭前就发出叹息，我的唉哼涌出如水。","notes":[]},{"n":25,"t":"因我所恐惧的临到我，我所惧怕的迎向我；","notes":[]},{"n":26,"t":"我不得安逸，不得平静，也不得安息，却有患难来到。”","notes":[]}]},"4":{"heading":"第一次对话","verses":[{"n":1,"t":"提幔人以利法回答说：","notes":[]},{"n":2,"t":"“人想与你说话，你就厌烦吗？但谁能忍住不发言呢？","notes":[]},{"n":3,"t":"看哪，你素来教导许多人，又坚固软弱的手。","notes":[]},{"n":4,"t":"你的言语曾扶助跌倒的人；你使软弱的膝盖稳固。","notes":[]},{"n":5,"t":"但现在祸患临到你，你就烦躁了；它挨近你，你就惊惶。","notes":["“祸患临到”：原文是“它临到”。"]},{"n":6,"t":"你的倚靠不是在于你敬畏神吗？你的盼望不是在于你行事纯正吗？","notes":[]},{"n":7,"t":"“请你追想：无辜的人有谁灭亡？正直的人何处被剪除？","notes":[]},{"n":8,"t":"按我所见，耕罪孽的，种毒害的，照样收割。","notes":[]},{"n":9,"t":"神一嘘气，他们就灭亡；神一发怒，他们就消失。","notes":[]},{"n":10,"t":"狮子吼叫，猛狮咆哮，少壮狮子的牙齿被敲断。","notes":[]},{"n":11,"t":"公狮因缺猎物而死，母狮的幼狮都离散。","notes":[]},{"n":12,"t":"“有话暗中传递给我，耳朵听其微小的声音。","notes":[]},{"n":13,"t":"世人沉睡的时候，从夜间异象的杂念中，","notes":[]},{"n":14,"t":"恐惧战兢临到我身，使我百骨战抖。","notes":[]},{"n":15,"t":"有灵从我面前经过，我身上的毫毛竖立。","notes":[]},{"n":16,"t":"那灵停住，我却不能辨其形状；有形像在我眼前。我在静默中听见有声音：","notes":[]},{"n":17,"t":"‘必死的人能比神公义吗？壮士能比造他的主纯洁吗？","notes":[]},{"n":18,"t":"看哪，主不信靠他的仆人，尚且指他的使者为愚昧，","notes":[]},{"n":19,"t":"何况那些住在泥屋、根基在尘土里、被蛀虫所毁坏的人呢？","notes":[]},{"n":20,"t":"早晚之间，他们就被毁灭，永归无有，无人理会。","notes":[]},{"n":21,"t":"他们帐棚的绳索岂不从中拔出来呢？他们死，且是无智慧而死。’”","notes":[]}]},"5":{"heading":"","verses":[{"n":1,"t":"“你呼求吧，有谁回答你呢？圣者之中，你转向哪一位呢？","notes":[]},{"n":2,"t":"愤怒害死愚妄人，嫉妒杀死愚蠢的人。","notes":[]},{"n":3,"t":"我曾见愚妄人扎下根，但我忽然诅咒他的住处。","notes":[]},{"n":4,"t":"他的儿女远离稳妥之地，在城门口被欺压，无人搭救。","notes":[]},{"n":5,"t":"他的庄稼被饥饿的人吃尽了，就是在荆棘里的也抢去了；他的财宝被陷阱张口吞没了。","notes":["“陷阱”：有古译本是“口渴的人”。"]},{"n":6,"t":"因为祸患不是从尘土中出来，患难也不是从土地里长出。","notes":[]},{"n":7,"t":"人生出来必遭遇患难，如同火花飞腾。","notes":["“火花”或译“鸟儿”。"]},{"n":8,"t":"“至于我，我必寻求神，把我的事情交托给他。","notes":[]},{"n":9,"t":"他行大事不可测度，行奇事不可胜数。","notes":[]},{"n":10,"t":"他降雨在地面，赐水于田野。","notes":[]},{"n":11,"t":"他将卑微的人安置在高处，将哀痛的人举到稳妥之地。","notes":[]},{"n":12,"t":"他破坏通达人的计谋，使他们手所做的不得成就。","notes":[]},{"n":13,"t":"他使有智慧的人中了自己的诡计，叫狡诈人的计谋速速落空。","notes":[]},{"n":14,"t":"他们白昼遇见黑暗，午间摸索如在夜间。","notes":[]},{"n":15,"t":"神拯救贫穷人脱离残暴人的手，脱离他们口中的刀。","notes":[]},{"n":16,"t":"这样，贫寒人有指望，不义的人闭口无言。","notes":[]},{"n":17,"t":"“看哪，神所惩治的人是有福的！所以你不可轻看全能者的管教。","notes":[]},{"n":18,"t":"因为他打伤，又包扎；他击伤，又亲手医治。","notes":[]},{"n":19,"t":"你六次遭难，他必救你；就是七次，灾祸也无法害你。","notes":[]},{"n":20,"t":"在饥荒中，他必救你脱离死亡；在战争中，他必救你脱离刀剑的权势。","notes":[]},{"n":21,"t":"你必被隐藏，不受口舌之害；灾害临到，你也不惧怕。","notes":[]},{"n":22,"t":"对于灾害饥馑，你必讥笑；至于地上的野兽，你也不惧怕。","notes":[]},{"n":23,"t":"因为你必与田间的石头立约，田里的野兽也必与你和好。","notes":[]},{"n":24,"t":"你必知道你的帐棚平安，你查看你的羊圈，一无所失。","notes":[]},{"n":25,"t":"你也必知道你的后裔众多，你的子孙像地上的青草。","notes":[]},{"n":26,"t":"你必寿高年迈才归坟墓，好像禾捆按时收藏。","notes":[]},{"n":27,"t":"看哪，这道理我们已经考察，本是如此。你须要听，要亲自明白。”","notes":[]}]},"6":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"“惟愿我的烦恼被秤一秤，我一切的灾害放在天平里，","notes":[]},{"n":3,"t":"现今都比海沙更重，所以我说话急躁。","notes":[]},{"n":4,"t":"因全能者的箭射中了我，我的灵喝尽其毒；神的惊吓摆阵攻击我。","notes":[]},{"n":5,"t":"野驴有草岂会叫唤？牛有饲料岂会吼叫？","notes":[]},{"n":6,"t":"食物淡而无盐岂可吃呢？蛋白有什么滋味呢？","notes":[]},{"n":7,"t":"那些可厌的食物，我心不肯挨近。","notes":[]},{"n":8,"t":"“惟愿我得着所求的，神赏赐我所切望的，","notes":[]},{"n":9,"t":"愿神把我压碎，伸手将我剪除。","notes":[]},{"n":10,"t":"我因没有违弃那圣者的言语，就仍以此为安慰，在不止息的痛苦中还可欢跃。","notes":[]},{"n":11,"t":"我有什么气力使我等候？我有什么结局使我忍耐？","notes":[]},{"n":12,"t":"我的气力岂是石头的气力？我的肉身岂是铜呢？","notes":[]},{"n":13,"t":"在我里面岂不是无助吗？智慧岂不是从我心中被赶逐吗？","notes":[]},{"n":14,"t":"“灰心的人，他的朋友当以慈爱待他，因为他将离弃敬畏全能者的心。","notes":[]},{"n":15,"t":"我的弟兄诡诈，好像河道，像溪水流过的河床，","notes":[]},{"n":16,"t":"因结冰而混浊，有雪藏在其中，","notes":[]},{"n":17,"t":"暖和的时候就溶化，炎热时便从原处干涸。","notes":[]},{"n":18,"t":"商队偏离道路，上到荒凉之地而死亡。","notes":[]},{"n":19,"t":"提玛的商队瞻望，示巴的旅客等候。","notes":[]},{"n":20,"t":"他们因希望落空就抱愧，来到那里便蒙羞。","notes":[]},{"n":21,"t":"现在你们正是这样，看见惊吓的事就惧怕。","notes":["“你们正是这样”：原文另译“你们算不得什么”。"]},{"n":22,"t":"我岂说：‘请你们供给我，从你们的财物中送礼给我’？","notes":[]},{"n":23,"t":"或说：‘请你们拯救我脱离敌人的手，救赎我脱离残暴人的手’吗？","notes":[]},{"n":24,"t":"“请你们指教我，我就不作声；我在何事上有错，请使我明白。","notes":[]},{"n":25,"t":"正直言语的力量何其大！但你们责备是责备什么呢？","notes":[]},{"n":26,"t":"绝望人的讲论既然如风，你们还计划批驳言语吗？","notes":[]},{"n":27,"t":"你们甚至为孤儿抽签，把朋友当货物。","notes":[]},{"n":28,"t":"“现在，请你们看着我，我绝不当面说谎。","notes":[]},{"n":29,"t":"请你们转意，不要不公义；请再转意，正义在我这里。","notes":[]},{"n":30,"t":"我的舌头岂有不公义吗？我的上膛岂不辨奸恶吗？”","notes":[]}]},"7":{"heading":"","verses":[{"n":1,"t":"“人在世上岂无劳役呢？他的日子不像雇工的日子吗？","notes":[]},{"n":2,"t":"像奴仆切慕阴凉，像雇工等待工钱，","notes":[]},{"n":3,"t":"我也照样度过虚空的岁月，愁烦的夜晚指定给我。","notes":[]},{"n":4,"t":"我躺卧的时候就说：‘我何时可以起来呢？’漫漫长夜，我总是翻来覆去，直到天亮。","notes":[]},{"n":5,"t":"我的肉体以虫子和尘土为衣，我的皮肤才收了口又流脓。","notes":[]},{"n":6,"t":"我的日子比织布的梭更快，都消耗在没有指望之中。","notes":[]},{"n":7,"t":"“你要记得，我的生命不过是一口气，我的眼睛必不再看见福乐。","notes":[]},{"n":8,"t":"观看我的人，他的眼必不看见我；你的眼目投向我，我却不在了。","notes":[]},{"n":9,"t":"云彩消散而去；照样，人下阴间也不再上来。","notes":[]},{"n":10,"t":"他不再回自己的家，他自己的地方也不再认得他。","notes":[]},{"n":11,"t":"“我甚至不封我的口；我灵愁苦，要发出言语；我心苦恼，要吐露哀情。","notes":[]},{"n":12,"t":"我岂是海洋，岂是大鱼，你竟防守着我呢？","notes":[]},{"n":13,"t":"我若说：‘我的床必安慰我，我的榻必分担我的苦情’，","notes":[]},{"n":14,"t":"你就用梦惊扰我，用异象恐吓我。","notes":[]},{"n":15,"t":"甚至我宁可窒息死亡，胜似留我这副骨头。","notes":[]},{"n":16,"t":"我厌弃生命，不愿永远活着。你任凭我吧，因我的日子都是虚空。","notes":[]},{"n":17,"t":"人算什么，你竟看他为大，将他放在心上，","notes":[]},{"n":18,"t":"每早晨鉴察他，每时刻考验他？","notes":[]},{"n":19,"t":"你到何时才转眼不看我，任凭我咽下唾沫呢？","notes":[]},{"n":20,"t":"鉴察人的主啊，我若有罪，于你何妨？为何以我当你的箭靶，使我成为你的重担呢？","notes":[]},{"n":21,"t":"为何不赦免我的过犯，除掉我的罪孽呢？我现今要躺卧在尘土中；你要切切寻找我，我却不在了。”","notes":[]}]},"8":{"heading":"","verses":[{"n":1,"t":"书亚人比勒达回答说：","notes":[]},{"n":2,"t":"“这些话你要说到几时？你口中的言语如狂风要到几时呢？","notes":[]},{"n":3,"t":"神岂能偏离公平？全能者岂能偏离公义？","notes":[]},{"n":4,"t":"或者你的儿女得罪了他，他就把他们交在过犯的掌控中。","notes":[]},{"n":5,"t":"你若切切寻求神，向全能者恳求；","notes":[]},{"n":6,"t":"你若纯洁正直，他必定为你兴起，使你公义的居所兴旺。","notes":[]},{"n":7,"t":"你起初虽然微小，日后必非常强盛。","notes":[]},{"n":8,"t":"“请你询问上代，思念他们祖先所查究的。","notes":[]},{"n":9,"t":"我们不过从昨日才有，一无所知，因我们在世的日子好像影子。","notes":[]},{"n":10,"t":"他们岂不指教你，告诉你，说出发自内心的言语呢？","notes":[]},{"n":11,"t":"“蒲草没有泥岂能生长？芦荻没有水岂能长大？","notes":[]},{"n":12,"t":"它还青翠，没有割下的时候，比百样的草先枯槁。","notes":[]},{"n":13,"t":"凡忘记神的人，路途也是这样；不虔敬人的指望要灭没。","notes":[]},{"n":14,"t":"他所仰赖的必折断，他所倚靠的是蜘蛛网。","notes":[]},{"n":15,"t":"他要倚靠房屋，房屋却站立不住；他要抓住房屋，房屋却不能存留。","notes":[]},{"n":16,"t":"他在日光之下茂盛，嫩枝在园中蔓延；","notes":[]},{"n":17,"t":"他的根盘绕石堆，钻入石缝。","notes":["“钻入石缝”：原文是“看见石屋”。"]},{"n":18,"t":"他若从本地被拔出，那地就不认识他，说：‘我没有见过你。’","notes":[]},{"n":19,"t":"看哪，这就是他道路中的喜乐，以后必另有人从尘土而生。","notes":[]},{"n":20,"t":"看哪，神必不丢弃完全人，也不扶助邪恶人的手。","notes":[]},{"n":21,"t":"他还要以喜笑充满你的口，以欢呼充满你的嘴唇。","notes":[]},{"n":22,"t":"恨恶你的要披戴羞愧，恶人的帐棚必归于无有。”","notes":[]}]},"9":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"“我真的知道是这样，但人在神前怎能成为义呢？","notes":[]},{"n":3,"t":"人若想要与他争辩，千次中也不能回答一次。","notes":[]},{"n":4,"t":"他心里有智慧，且大有能力。谁向神刚硬而得平安呢？","notes":[]},{"n":5,"t":"他把山挪移，山却不知，他在怒气中，把山翻倒。","notes":[]},{"n":6,"t":"他使地震动，离其本位，地的柱子就摇撼。","notes":[]},{"n":7,"t":"他吩咐太阳，太阳就不出来，又封住众星。","notes":[]},{"n":8,"t":"他独自铺张诸天，步行在海浪之上。","notes":[]},{"n":9,"t":"他造北斗、参星、昴星，以及南方的星宿；","notes":["“南方的星宿”：原文是“南方的内宫”。"]},{"n":10,"t":"他行大事不可测度，行奇事不可胜数。","notes":[]},{"n":11,"t":"看哪，他从我旁边经过，我看不见；他走过，我没有察觉他。","notes":[]},{"n":12,"t":"看哪，他夺去，谁能阻挡他？谁敢对他说：‘你做什么呢？’","notes":[]},{"n":13,"t":"“神必不收回他的怒气，扶助拉哈伯的，屈身在神以下。","notes":["“拉哈伯”是神话故事中的大海怪。"]},{"n":14,"t":"既是这样，我怎敢回答他，怎敢在他之前选择辩词呢？","notes":[]},{"n":15,"t":"我虽有义，也不能回答，我要向那审判我的恳求。","notes":[]},{"n":16,"t":"我若呼求，纵然他应允我，我仍不信他会侧耳听我的声音。","notes":[]},{"n":17,"t":"他用暴风摧折我，无故加增我的损伤。","notes":["“用暴风”：原文另译“为一根头发”。"]},{"n":18,"t":"他不容我喘一口气，倒使我饱受苦恼。","notes":[]},{"n":19,"t":"若论力量，看哪，他真有能力！若论审判，‘谁能传我呢？’","notes":[]},{"n":20,"t":"我虽有义，我的口要定我有罪；我虽完全，他必证明我为弯曲。","notes":[]},{"n":21,"t":"我虽完全，不顾自己；我厌弃我的性命。","notes":[]},{"n":22,"t":"所以我说，都是一样；完全人和恶人，他都灭绝。","notes":[]},{"n":23,"t":"若灾祸忽然带来死亡，他必戏笑无辜人的苦难。","notes":[]},{"n":24,"t":"世界交在恶人手中；他蒙蔽世界审判官的脸，若不是他，那么是谁呢？","notes":[]},{"n":25,"t":"“我的日子比奔跑者更快，急速过去，不见福乐。","notes":[]},{"n":26,"t":"我的日子如蒲草船掠过，如鹰俯冲抓食。","notes":[]},{"n":27,"t":"我若说：‘我要忘记我的苦情，强颜欢笑’，","notes":[]},{"n":28,"t":"我就因一切的愁苦而惧怕；我知道你必不以我为无辜。","notes":[]},{"n":29,"t":"我必被定罪，我何必徒然劳苦呢？","notes":[]},{"n":30,"t":"我若用雪水洗身，用碱洁净我的手掌，","notes":[]},{"n":31,"t":"你还要把我扔在坑里，我的衣服都憎恶我。","notes":[]},{"n":32,"t":"他不像我是个人，使我可以回答他，使我们可以一同受审判。","notes":[]},{"n":33,"t":"我们中间没有仲裁者，可以按手在我们两造之间。","notes":[]},{"n":34,"t":"愿他使他的杖离开我，不使他的威严恐吓我，","notes":[]},{"n":35,"t":"我就说话，不惧怕他；但对我来说，我却不是这样。”","notes":[]}]},"10":{"heading":"","verses":[{"n":1,"t":"“我厌恶自己的性命，任由我述说自己的苦情；因心里苦恼，我要说话。","notes":[]},{"n":2,"t":"我对神说，不要定我有罪，要指示我，你为何与我争辩？","notes":[]},{"n":3,"t":"你手所造的，你又欺压，又藐视，却光照恶人的计谋。这事你以为美吗？","notes":[]},{"n":4,"t":"你的眼岂是肉眼？你察看岂像人察看吗？","notes":[]},{"n":5,"t":"你的日子岂像人的日子，你的年岁岂像壮士的年岁，","notes":[]},{"n":6,"t":"你就追问我的罪孽，寻察我的罪过吗？","notes":[]},{"n":7,"t":"其实，你知道我没有行恶，也无人能施行拯救，脱离你的手。","notes":[]},{"n":8,"t":"你的手塑造我，造了我，但我整个人却要一起被你吞灭。","notes":[]},{"n":9,"t":"求你记得，你制造我如泥土，你还要使我归回尘土吗？","notes":[]},{"n":10,"t":"你不是倒出我来好像奶，使我凝结如同奶酪吗？","notes":[]},{"n":11,"t":"你以皮和肉给我穿上，用骨与筋把我联结起来。","notes":[]},{"n":12,"t":"你将生命和慈爱赐给我，你也眷顾保全我的灵。","notes":[]},{"n":13,"t":"然而，你把这些事藏在你心里，我知道这是你的旨意。","notes":[]},{"n":14,"t":"我若犯罪，你就察看我，并不赦免我的罪。","notes":[]},{"n":15,"t":"我若行恶，我就有祸了；我若行义，也不敢抬头，而是饱受羞辱，看见我的痛苦。","notes":[]},{"n":16,"t":"你如狮子昂首追捕我，又在我身上显出奇事。","notes":["“你如...追捕我”：有古译本是“我若昂首自得，你就追捕我如狮子”。"]},{"n":17,"t":"你更新你的见证对付我，向我加增恼怒，调遣军队攻击我。","notes":[]},{"n":18,"t":"“你为何使我出母胎呢？甚愿我当时气绝，没有眼睛看见我。","notes":[]},{"n":19,"t":"这样，就如从未有过我，我一出母胎就被送入坟墓。","notes":[]},{"n":20,"t":"我的日子不是短少吗？求你停止，求你放过我，使我可以稍得喜乐，","notes":["“求你停止，求你放过我”：原文另译“愿他停止，愿他放过我”。"]},{"n":21,"t":"就是在我去而不返，往黑暗和死荫之地以先。","notes":[]},{"n":22,"t":"那是乌黑之地，犹如幽暗的死荫，毫无秩序；发出的光辉也像幽暗。”","notes":[]}]},"11":{"heading":"","verses":[{"n":1,"t":"拿玛人琐法回答说：","notes":[]},{"n":2,"t":"“这许多的话岂不该回答吗？多嘴多舌的人岂可成为义呢？","notes":[]},{"n":3,"t":"你夸大的话岂能使人不作声吗？你戏笑的时候岂没有人使你受辱吗？","notes":[]},{"n":4,"t":"你说：‘我的教导纯全，我在你眼前是清洁的。’","notes":[]},{"n":5,"t":"但是，惟愿神说话，愿他张开嘴唇攻击你。","notes":[]},{"n":6,"t":"愿他将智慧的奥秘指示你，因为健全的知识是两面的。你当知道，神使你忘记你的一些罪孽。","notes":[]},{"n":7,"t":"你能寻见神的奥秘吗？你能寻见全能者的极限吗？","notes":[]},{"n":8,"t":"高如诸天，你能做什么？比阴间深，你能知道什么？","notes":[]},{"n":9,"t":"其量度比地长，比海更宽。","notes":[]},{"n":10,"t":"他若经过，把人拘禁，召集会众，谁能阻挡他呢？","notes":[]},{"n":11,"t":"因为他知道虚妄的人；当他看见罪恶，岂不留意吗？","notes":[]},{"n":12,"t":"空虚的人若获得知识，野驴生下的驹子也成了人。","notes":[]},{"n":13,"t":"“至于你，若坚固己心，又向主举手；","notes":[]},{"n":14,"t":"你若远远脱离你手中的罪孽，不容许不义住在你帐棚之中；","notes":[]},{"n":15,"t":"这样，你必仰起脸来，毫无瑕疵；你也必安稳，无所惧怕。","notes":[]},{"n":16,"t":"你必忘记你的苦楚，就是想起来，也如流过的水。","notes":[]},{"n":17,"t":"你在世要升高，比正午更明，虽有黑暗，仍像早晨。","notes":[]},{"n":18,"t":"你因有指望就必稳固，也必四围察看，安然躺下。","notes":["“四围察看”：原文另译“得到庇护”。"]},{"n":19,"t":"你躺卧，无人惊吓，并有许多人向你求恩。","notes":[]},{"n":20,"t":"但恶人的眼睛要失明；他们无路可逃，他们的指望就是气绝身亡。”","notes":[]}]},"12":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"“你们果真是人物啊！智慧要与你们一同去死。","notes":[]},{"n":3,"t":"但我也有聪明，跟你们一样，并非不及你们。这些事，谁不知道呢？","notes":[]},{"n":4,"t":"我这求告神、蒙他应允的人竟成了朋友所讥笑的；又公义又完全的人竟遭受讥笑。","notes":[]},{"n":5,"t":"安逸的人心里藐视灾祸，这灾祸在等待失足滑跌的人。","notes":[]},{"n":6,"t":"强盗的帐棚安宁，惹神发怒的人稳固，他们把神握在自己手中。","notes":["“神”或译“神明”。","“他们把神握在自己手中”或译“神把他们领到自己的手中”。"]},{"n":7,"t":"“你问走兽，走兽必指教你；你问空中的飞鸟，飞鸟必告诉你；","notes":[]},{"n":8,"t":"或者你与地说话，地必指教你；海中的鱼也必向你说明。","notes":["“你与...指教你”或译“你问地上的草木，草木必指教你”。"]},{"n":9,"t":"在这一切当中，有谁不知道这是耶和华的手做成的呢？","notes":[]},{"n":10,"t":"凡动物的生命和人类的气息都在他手中。","notes":[]},{"n":11,"t":"耳朵岂不辨别言语，正如上膛品尝食物吗？","notes":[]},{"n":12,"t":"年老的有智慧，寿高的有知识。","notes":[]},{"n":13,"t":"“在神有智慧和能力，他有谋略和知识。","notes":[]},{"n":14,"t":"看哪，他拆毁，就不能重建；他拘禁人，人就不得释放。","notes":[]},{"n":15,"t":"看哪，他使水止住，水就干了；他把水放出，水就淹没大地。","notes":[]},{"n":16,"t":"在他有能力和智慧，走迷的和使人迷路的都属他。","notes":[]},{"n":17,"t":"他把谋士剥衣掳去，使审判官变为愚妄。","notes":[]},{"n":18,"t":"他解除君王的权势，用带子捆住他们的腰。","notes":["“他解除君王的权势”：原文另译“他放松君王的捆绑”；“权势”与“捆绑”的希伯来话发音相近。"]},{"n":19,"t":"他把祭司剥衣掳去，使有权能的人倾覆。","notes":[]},{"n":20,"t":"他废去忠信者的言论，夺去长者的见识。","notes":[]},{"n":21,"t":"他使贵族蒙羞受辱，放松勇士的腰带。","notes":[]},{"n":22,"t":"他从黑暗中彰显深奥的事，使死荫显出光明。","notes":[]},{"n":23,"t":"他使邦国兴旺而又毁灭，使邦国扩展又被掠夺。","notes":[]},{"n":24,"t":"他将地上百姓中领袖的聪明夺去，使他们迷失在荒凉无路之地。","notes":[]},{"n":25,"t":"他们在无光的黑暗中摸索；他使他们摇晃像醉酒的人一样。”","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"“看哪，这一切，我眼都见过；我耳都听过，而且明白。","notes":[]},{"n":2,"t":"你们所知道的，我也知道，并非不及你们。","notes":[]},{"n":3,"t":"然而我要对全能者说话，我愿与神理论。","notes":[]},{"n":4,"t":"但你们是编造谎言的，全都是无用的医生。","notes":[]},{"n":5,"t":"惟愿你们全然不作声，这就是你们的智慧！","notes":[]},{"n":6,"t":"请你们听我的答辩，留心听我嘴唇的诉求。","notes":[]},{"n":7,"t":"你们要为神说不义的话吗？要为他说诡诈的言语吗？","notes":[]},{"n":8,"t":"你们要看神的情面吗？要为他争辩吗？","notes":[]},{"n":9,"t":"他查究你们，这岂是好事吗？人欺骗人，你们也要照样欺骗他吗？","notes":[]},{"n":10,"t":"你们若暗中看人的情面，他必定要责备你们。","notes":[]},{"n":11,"t":"他的尊荣岂不叫你们惧怕吗？他岂不使惊吓临到你们吗？","notes":[]},{"n":12,"t":"你们可记念的谚语是灰烬的箴言；你们的后盾是泥土的后盾。","notes":[]},{"n":13,"t":"“你们不要向我作声，让我说话，无论如何我都承当。","notes":[]},{"n":14,"t":"我为何把我的肉挂在我的牙上，将我的命放在我的手掌中呢？","notes":[]},{"n":15,"t":"看哪，他要杀我，我毫无指望，然而我还要在他面前辩明我所行的。","notes":["“我毫无指望”：原文另译“我仍要仰望他”。"]},{"n":16,"t":"这要成为我的拯救，因为不虔诚的人不可到他面前。","notes":[]},{"n":17,"t":"你们要细听我的言语，让我的申辩入你们耳中。","notes":[]},{"n":18,"t":"看哪，我已陈明我的案，知道自己有义。","notes":[]},{"n":19,"t":"还有谁要和我争辩，我现在就缄默不言，气绝而死。","notes":[]},{"n":20,"t":"惟有两件事不要向我施行，我就不躲开你的面：","notes":[]},{"n":21,"t":"就是把你的手缩回，远离我身；又不使你的威严恐吓我。","notes":[]},{"n":22,"t":"这样，你呼叫，我就回答；或是让我说话，你回答我。","notes":[]},{"n":23,"t":"我的罪孽和我的罪有多少呢？求你叫我知道我的过犯与我的罪。","notes":[]},{"n":24,"t":"你为何转脸，拿我当仇敌呢？","notes":[]},{"n":25,"t":"你要惊动被风吹的叶子吗？要追赶枯干的碎秸吗？","notes":[]},{"n":26,"t":"你写下苦楚对付我，又使我担当幼年的罪孽。","notes":[]},{"n":27,"t":"你把我的脚锁上木枷，察看我一切的道路，为我的脚掌划定界限。","notes":[]},{"n":28,"t":"人像灭绝的烂物，像虫蛀的衣裳。”","notes":[]}]},"14":{"heading":"","verses":[{"n":1,"t":"“人为妇人所生，日子短少，多有患难。","notes":[]},{"n":2,"t":"他出来如花，凋谢而去；他飞逝如影，不能存留。","notes":[]},{"n":3,"t":"这样的人你岂会睁眼看他，又叫我来，在你那里受审吗？","notes":["“我”：七十士译本和其他古译本是“他”。"]},{"n":4,"t":"谁能使洁净出于污秽呢？谁也不能！","notes":[]},{"n":5,"t":"既然人的日子限定，他的月数在于你，你划定他的界限，他不能越过；","notes":[]},{"n":6,"t":"求你转眼不看他，使他得歇息，直到他像雇工享受他的一天。","notes":[]},{"n":7,"t":"“因树有指望，若被砍下，还可发芽，嫩枝生长不息。","notes":[]},{"n":8,"t":"树根若衰老在地里，树干也死在土中，","notes":[]},{"n":9,"t":"及至得了水气，还会发芽，长出枝条，像新栽的树一样。","notes":[]},{"n":10,"t":"但壮士一死就消逝了；人一气绝，他在何处呢？","notes":[]},{"n":11,"t":"海中的水枯竭，江河消散干涸。","notes":[]},{"n":12,"t":"人一躺下就不再起来，等到诸天没有了，仍不复醒，也不能从睡中唤醒。","notes":["“没有了”：有古译本是“废去了”。"]},{"n":13,"t":"惟愿你把我藏在阴间，把我隐藏，直到你的愤怒过去；愿你为我定下期限，并记得我。","notes":[]},{"n":14,"t":"壮士若死了能再活吗？我在一切服役的日子中等待，直到我退伍的时候来到。","notes":[]},{"n":15,"t":"你呼叫，我就回答你；你手所做的，你必期待。","notes":[]},{"n":16,"t":"但如今你数点我的脚步，不察看我的罪。","notes":[]},{"n":17,"t":"我的过犯被你密封在囊中，你遮掩了我的罪孽。","notes":[]},{"n":18,"t":"“然而，山崩变为无有，磐石从原处挪移。","notes":[]},{"n":19,"t":"流水冲蚀石头，急流洗去地上的尘土；你也照样灭绝人的指望。","notes":[]},{"n":20,"t":"你终必胜过人，使他消逝；你改变他的容貌，把他送走。","notes":[]},{"n":21,"t":"他的儿子得尊荣，他不知道；他们降为卑，他也不晓得。","notes":[]},{"n":22,"t":"他只觉得身上疼痛，心中为自己悲哀。”","notes":[]}]},"15":{"heading":"第二次对话","verses":[{"n":1,"t":"提幔人以利法回答说：","notes":[]},{"n":2,"t":"“智慧人岂可用虚空的知识回答，用东风充满自己的肚腹呢？","notes":[]},{"n":3,"t":"他岂可用无益的话，用无济于事的言语理论呢？","notes":[]},{"n":4,"t":"你诚然废弃敬畏，不在神面前默想。","notes":[]},{"n":5,"t":"你的罪孽指教你的口；你选用诡诈人的舌头。","notes":[]},{"n":6,"t":"你自己的口定你有罪，并非是我；你自己的嘴唇见证你的不是。","notes":[]},{"n":7,"t":"“你是头一个生下来的人吗？你受造在诸山之先吗？","notes":[]},{"n":8,"t":"你曾听见神的密旨吗？你要独自得尽智慧吗？","notes":[]},{"n":9,"t":"什么是你知道，我们不知道的呢？什么是你明白，我们不明白的呢？","notes":[]},{"n":10,"t":"我们这里有白发的和年老的，比你父亲还年长。","notes":[]},{"n":11,"t":"神的安慰和对你温和的话，你以为太小吗？","notes":[]},{"n":12,"t":"你的心为何失控，你的眼为何冒火，","notes":[]},{"n":13,"t":"以致你的灵反对神，你的口说出这样的言语呢？","notes":[]},{"n":14,"t":"人是什么，竟算为洁净呢？妇人所生的是什么，竟算为义呢？","notes":[]},{"n":15,"t":"看哪，神不信任他的众圣者；在他眼前，天也不洁净，","notes":[]},{"n":16,"t":"何况那污秽可憎，喝罪孽如水的世人呢！","notes":[]},{"n":17,"t":"“我指示你，你要听我；我要陈述我所看见的，","notes":[]},{"n":18,"t":"就是智慧人从列祖所受，传讲而不隐瞒的事。","notes":[]},{"n":19,"t":"这地惟独赐给他们，并没有外人从他们中间经过。","notes":[]},{"n":20,"t":"恶人一生的日子绞痛难熬，残暴人存留的年数也是如此。","notes":[]},{"n":21,"t":"惊吓的声音常在他耳中；在平安时，毁灭者必临到他。","notes":[]},{"n":22,"t":"他不信自己能从黑暗中转回；他被刀剑看守。","notes":[]},{"n":23,"t":"他飘流在外求食：‘哪里有食物呢？’他知道黑暗的日子在他手边预备好了。","notes":["“他飘流...有食物呢？”有古译本是“他被命定作秃鹰的食物。”","本节七十士译本是“他被派定作秃鹰的食物，知道自己会成为尸体，黑暗的日子要像风把他吹走。”"]},{"n":24,"t":"急难困苦叫他害怕，而且胜过他，好像君王预备上阵。","notes":[]},{"n":25,"t":"因他伸手攻击神，逞强对抗全能者，","notes":[]},{"n":26,"t":"挺着颈项，用盾牌坚厚的凸面向全能者直闯；","notes":[]},{"n":27,"t":"又因他的脸蒙上油脂，腰上积满肥肉。","notes":[]},{"n":28,"t":"他住在荒凉的城镇，房屋无人居住，成为废墟。","notes":[]},{"n":29,"t":"他不得富足，财物不得常存，产业在地上也不加增。","notes":[]},{"n":30,"t":"他不得脱离黑暗，火焰要把他的嫩枝烧干；因神口中的气，他要离去。","notes":[]},{"n":31,"t":"不要让他倚靠虚假，欺骗自己，因虚假必成为他的报应。","notes":[]},{"n":32,"t":"他的日期未到之先，这事必实现；他的枝子不得青绿。","notes":[]},{"n":33,"t":"他必像葡萄树，葡萄未熟就掉落；又像橄榄树，一开花就凋谢。","notes":[]},{"n":34,"t":"因不敬虔之辈必不能生育，受贿赂之人的帐棚必被火吞灭。","notes":[]},{"n":35,"t":"他们所怀的是毒害，所生的是罪孽，肚腹里所预备的是诡诈。”","notes":[]}]},"16":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"“这样的话我听了许多；你们全都是使人愁烦的安慰者。","notes":[]},{"n":3,"t":"如风的言语有穷尽吗？或者什么惹动你回答呢？","notes":[]},{"n":4,"t":"我也能说你们那样的话，你们若处在我的景况，我也可以堆砌言词攻击你们，又可以向你们摇头。","notes":[]},{"n":5,"t":"但我必用口坚固你们，颤动的嘴唇带来舒解。","notes":[]},{"n":6,"t":"“我若说话，痛苦仍不得缓解；我若停止，痛苦就离开我吗？","notes":[]},{"n":7,"t":"但现在神使我困倦，你使所有的亲友远离我，","notes":[]},{"n":8,"t":"你抓住我，成为见证起来攻击我；我的枯瘦也当着我的面作证。","notes":["“你抓住我”或译“你使我布满皱纹”。"]},{"n":9,"t":"神发怒撕裂我，逼迫我，向我咬牙切齿；我的敌人怒目瞪我。","notes":[]},{"n":10,"t":"他们向我大大张口，打我的耳光羞辱我，聚在一起攻击我。","notes":[]},{"n":11,"t":"神把我交给不敬虔的人，把我扔到恶人的手中。","notes":[]},{"n":12,"t":"我本是安逸，他折断我，掐住我的颈项，把我摔碎，又立我作他的箭靶。","notes":[]},{"n":13,"t":"他的弓箭手围绕我。他刺破我的肾脏，并不留情，把我的胆汁倾倒在地上。","notes":[]},{"n":14,"t":"他使我破裂，破裂又破裂，如同勇士向我直闯。","notes":[]},{"n":15,"t":"“我把麻布缝在我的皮肤上，把我的角放在尘土中。","notes":[]},{"n":16,"t":"我的脸因哭泣变红，我的眼皮上有死荫。","notes":[]},{"n":17,"t":"我的手中却没有暴力，我的祈祷也是纯洁的。","notes":[]},{"n":18,"t":"“地啊，不要遮盖我的血！不要让我的哀求有藏匿之处！","notes":[]},{"n":19,"t":"现今，看哪，在天有我的见证，在上有我的保人。","notes":[]},{"n":20,"t":"我的朋友讥诮我，我却向神眼泪汪汪。","notes":[]},{"n":21,"t":"愿人可与神理论，如同人与朋友一样；","notes":[]},{"n":22,"t":"因为再过几年，我必走那往而不返之路。”","notes":[]}]},"17":{"heading":"","verses":[{"n":1,"t":"“我的灵耗尽，我的日子消逝；坟墓为我预备好了。","notes":[]},{"n":2,"t":"戏笑的人果真陪伴着我，我的眼睛盯住他们的悖逆。","notes":[]},{"n":3,"t":"“愿你亲自为我付押担保。谁还会与我击掌呢？","notes":[]},{"n":4,"t":"因你蒙蔽他们的心，使不明理，所以你必不高举他们。","notes":[]},{"n":5,"t":"控告朋友为了分享产业的，他儿女的眼睛要失明。","notes":["“控告”或译“出卖”或“邀请”。"]},{"n":6,"t":"“神使我成为人群中的笑谈，他们吐唾沫在我脸上。","notes":[]},{"n":7,"t":"我的眼睛因忧愁昏花，我的肢体全像影儿。","notes":[]},{"n":8,"t":"正直人因此必惊奇；无辜的人要兴起攻击不敬虔之辈。","notes":[]},{"n":9,"t":"然而，义人要持守所行的道，手洁的人要力上加力。","notes":[]},{"n":10,"t":"至于你们众人，再回来吧！你们中间，我找不到一个智慧人。","notes":[]},{"n":11,"t":"我的日子已经过去了，我的谋算、我心的愿望已经断绝了。","notes":[]},{"n":12,"t":"他们以黑夜为白昼，即使面临黑暗，以为亮光已近。","notes":[]},{"n":13,"t":"我若盼望阴间为我的家，若下榻在黑暗中，","notes":[]},{"n":14,"t":"若对地府呼叫：‘你是我的父亲’，若对虫呼叫：‘你是我的母亲、姊妹’，","notes":[]},{"n":15,"t":"这样，我的盼望在哪里呢？我所盼望的，谁能看见呢？","notes":[]},{"n":16,"t":"这盼望要下到阴间的门闩吗？要一起在尘土中安息吗？”","notes":["“这盼望...门闩吗”：七十士译本是“这盼望要与我一起下到阴间吗”。","“要一起...安息吗”：七十士译本和其他古译本是“我们要一起下入尘土中吗”。"]}]},"18":{"heading":"","verses":[{"n":1,"t":"书亚人比勒达回答说：","notes":[]},{"n":2,"t":"“你们寻索言语要到几时呢？你们要明白，然后我们才说话。","notes":["“你们...几时呢”：原文直译“你们为言语设陷阱要到几时呢”；七十士译本和其他古译本是“你要说到几时才停止呢”。"]},{"n":3,"t":"我们为何被视为畜牲，在你们眼中看为愚笨呢？","notes":["“愚笨”或译“不洁净”。"]},{"n":4,"t":"在怒气中将自己撕裂的人哪，难道大地要因你见弃、磐石要挪开原处吗？","notes":[]},{"n":5,"t":"“恶人的亮光必要熄灭，他的火焰必不照耀。","notes":[]},{"n":6,"t":"他帐棚中的亮光要变黑暗，他上面的灯也必熄灭。","notes":[]},{"n":7,"t":"他强横的脚步必遭阻碍，他的计谋必将自己绊倒。","notes":[]},{"n":8,"t":"他因自己的脚陷入网中，走在缠人的网子上。","notes":[]},{"n":9,"t":"罗网必抓住他的脚跟，陷阱必擒获他。","notes":[]},{"n":10,"t":"绳索为他藏在土里，羁绊为他藏在路上。","notes":[]},{"n":11,"t":"四面的惊吓使他害怕，在他脚跟后面追赶他。","notes":[]},{"n":12,"t":"他的力量必因饥饿衰败，祸患要在他的旁边等候，","notes":[]},{"n":13,"t":"侵蚀他肢体的皮肤；死亡的长子吞吃他的肢体。","notes":[]},{"n":14,"t":"他要从所倚靠的帐棚被拔出来，带到使人惊恐的王那里。","notes":[]},{"n":15,"t":"不属他的必住在他的帐棚里，硫磺必撒在他所住之处。","notes":[]},{"n":16,"t":"下边，他的根要枯干；上边，他的枝子要剪除。","notes":[]},{"n":17,"t":"他的称号从地上消失，他的名字不在街上存留。","notes":["“称号”：原文是“纪念”。"]},{"n":18,"t":"他必从光明中被驱逐到黑暗里，他必被赶出世界。","notes":[]},{"n":19,"t":"他在自己百姓中必无子无孙，在寄居之地也没有幸存者。","notes":[]},{"n":20,"t":"以后的人要因他的日子惊讶，以前的人也被惊骇抓住。","notes":["“以后的人”或译“西方人”。","“以前的人”或译“东方人”。"]},{"n":21,"t":"不义之人的住处总是这样，这就是不认识神之人的下场。”","notes":[]}]},"19":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"“你们搅扰我的心，用言语压碎我要到几时呢？","notes":[]},{"n":3,"t":"你们这十次羞辱我，苦待我也不以为耻。","notes":[]},{"n":4,"t":"果真我有错，这错是在于我。","notes":[]},{"n":5,"t":"若你们真要向我夸大，以我的羞辱来责备我，","notes":[]},{"n":6,"t":"就该知道是神倾覆我，用罗网围绕我。","notes":[]},{"n":7,"t":"看哪，我喊冤叫屈，却不蒙应允；我呼求，却没有公正。","notes":[]},{"n":8,"t":"神拦住我的道路，使我不得经过；他使黑暗笼罩我的路径。","notes":[]},{"n":9,"t":"他剥去我的荣光，摘去我头上的冠冕。","notes":[]},{"n":10,"t":"他在四围攻击我，我就走了；他将我的指望如树拔出。","notes":[]},{"n":11,"t":"他向我发烈怒，以我为他的敌人。","notes":[]},{"n":12,"t":"他的军队一齐上来，修筑道路攻击我，在我帐棚的四围安营。","notes":[]},{"n":13,"t":"“他把我的兄弟隔在远处，使我认识的人全然与我生疏。","notes":[]},{"n":14,"t":"我的亲戚都离开了我；我的密友都忘记了我。","notes":[]},{"n":15,"t":"在我家寄居的和我的使女，都当我是陌生人；我在他们眼中被视为外邦人。","notes":[]},{"n":16,"t":"我呼唤仆人，他却不回答；我必须亲口求他。","notes":[]},{"n":17,"t":"我口的气味令我妻子厌恶，我的同胞都憎恶我。","notes":[]},{"n":18,"t":"连小男孩也藐视我；我起来，他们都嘲笑我。","notes":[]},{"n":19,"t":"我的知心朋友都憎恶我；我平日所爱的人向我翻脸。","notes":[]},{"n":20,"t":"我的皮和肉紧贴骨头，我得以逃脱，仅剩牙齿。","notes":["“牙齿”：原文是“牙的皮”。","本节七十士译本是“我的肉在皮下腐烂，我的骨头伸出好像牙齿”。"]},{"n":21,"t":"我的朋友啊，可怜我！可怜我！因为神的手攻击我。","notes":[]},{"n":22,"t":"你们为什么仿佛神逼迫我，吃我的肉还不满足呢？","notes":[]},{"n":23,"t":"“惟愿我的言语现在就写上，都记录在书上；","notes":[]},{"n":24,"t":"用铁笔和铅，刻在磐石上，存到永远。","notes":[]},{"n":25,"t":"我知道我的救赎主活着，末后他必站在尘土上。","notes":["“救赎主”或译“伸冤者”。"]},{"n":26,"t":"我这皮肉灭绝之后，我必在肉体之外得见神。","notes":["“我这皮肉灭绝之后”：原文另译“我醒来之后，他会使我跟他一起站起来”。","“在肉体之外”或译“在肉体之中”或“从肉体”。"]},{"n":27,"t":"我自己要见他，亲眼要看他，并不像陌生人。我的心肠在我里面耗尽了！","notes":[]},{"n":28,"t":"你们若说：‘我们怎么逼迫他呢？事情的根源是在于他’，","notes":["“他”是根据一些古卷、七十士译本和其他古译本；原文是“我”。"]},{"n":29,"t":"你们就当惧怕刀剑，因为愤怒带来刀剑的刑罚。这样，你们就知道有审判。”","notes":[]}]},"20":{"heading":"","verses":[{"n":1,"t":"拿玛人琐法回答说：","notes":[]},{"n":2,"t":"“这样，我的思念叫我回答，因为我心中急躁。","notes":[]},{"n":3,"t":"我听见那羞辱我的责备；我悟性的灵回答我。","notes":[]},{"n":4,"t":"你岂不知道吗？亘古以来，自从人被安置在地，","notes":[]},{"n":5,"t":"恶人欢乐的声音是暂时的，不敬虔人的喜乐不过是转眼之间。","notes":[]},{"n":6,"t":"他的尊荣虽达到天上，头虽顶到云中，","notes":[]},{"n":7,"t":"他必永远灭亡，像自己的粪一样。看见他的人要说：‘他在哪里呢？’","notes":[]},{"n":8,"t":"他必如梦飞去，不再寻见；他被赶走，如夜间的异象。","notes":[]},{"n":9,"t":"亲眼见过他的，必不再见他；他自己的地方也不再见到他。","notes":[]},{"n":10,"t":"他的儿女要向穷人求恩；他的手要赔还钱财。","notes":[]},{"n":11,"t":"他的骨头虽然满有年轻的活力，却要和他一同躺卧在尘土之中。","notes":[]},{"n":12,"t":"“他口中以恶为甘甜，把恶藏在舌头底下，","notes":[]},{"n":13,"t":"爱恋不舍，含在口中。","notes":[]},{"n":14,"t":"他的食物在肚里却要翻转，在他里面成为虺蛇的毒液。","notes":[]},{"n":15,"t":"他吞了财宝，还要吐出；神要从他腹中掏出来。","notes":[]},{"n":16,"t":"他必吸饮虺蛇的毒汁，毒蛇的舌头必杀他。","notes":[]},{"n":17,"t":"他不再看见溪流，流奶与蜜之河。","notes":[]},{"n":18,"t":"他劳碌得来的要赔还，不得吞下；赚取了财货，也不得欢乐。","notes":[]},{"n":19,"t":"他欺压穷人，弃之不顾，强取非自己所盖的房屋。","notes":["“强取...房屋”或译“强取房屋不得再建造”。"]},{"n":20,"t":"“他的肚腹不知安逸，所贪恋的连一样也不放过，","notes":[]},{"n":21,"t":"剩余的没有一样他不吞吃，所以他的福乐不能长久。","notes":[]},{"n":22,"t":"他在满足有余的时候，必有困苦临到；凡受苦楚之人的手必加在他身上。","notes":[]},{"n":23,"t":"他的肚腹正要满足的时候，神必将猛烈的愤怒降在他身上；他正在吃饭的时候，神要将这愤怒如雨降在他身上。","notes":[]},{"n":24,"t":"他要躲避铁的武器，铜弓要将他射透。","notes":[]},{"n":25,"t":"箭一抽，就从他背上出来，发亮的箭头从他胆中出来；有惊惶临到他身上。","notes":[]},{"n":26,"t":"他的财宝隐藏在深沉的黑暗里；有非人吹起的火要把他吞灭，把他帐棚中所剩下的烧毁。","notes":[]},{"n":27,"t":"天要显明他的罪孽，地要兴起去攻击他。","notes":[]},{"n":28,"t":"他家里出产的必消失，在神愤怒的日子被冲走。","notes":[]},{"n":29,"t":"这是恶人从神所得的份，是神为他所定的产业。”","notes":[]}]},"21":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"“你们要细心听我的言语，这就算是你们的安慰。","notes":[]},{"n":3,"t":"请宽容我，我又要说话；说了以后，任凭你嗤笑吧！","notes":[]},{"n":4,"t":"我岂是向人诉苦？我为何不是没有耐心呢？","notes":[]},{"n":5,"t":"你们要转向我而惊奇，要用手捂口。","notes":[]},{"n":6,"t":"我每逢思想，心就惊惶，战兢抓住我身。","notes":[]},{"n":7,"t":"恶人为何存活，得享高寿，势力强盛呢？","notes":[]},{"n":8,"t":"他们的后裔与他们一起，坚立在他们面前，他们得以眼见自己的子孙。","notes":["“与他们一起”：原文另译“他们的百姓”。"]},{"n":9,"t":"他们的家宅平安无惧，神的杖不加在他们身上。","notes":[]},{"n":10,"t":"他们的公牛传种而不断绝，母牛生牛犊而不掉胎。","notes":[]},{"n":11,"t":"他们打发小男孩出去，多如羊群，他们的孩子踊跃跳舞。","notes":[]},{"n":12,"t":"他们随着琴鼓歌唱，因箫声欢喜。","notes":[]},{"n":13,"t":"他们度日诸事亨通，在平安中下到阴间。","notes":[]},{"n":14,"t":"他们对神说：‘离开我们吧！我们不想知道你的道路。","notes":[]},{"n":15,"t":"全能者是谁，我们何必事奉他呢？求告他有什么益处呢？’","notes":[]},{"n":16,"t":"看哪，他们亨通不是靠自己的手；恶人的计谋离我好远。","notes":[]},{"n":17,"t":"“恶人的灯何尝熄灭？患难何尝临到他们呢？神何尝发怒，把灾祸分给他们呢？","notes":[]},{"n":18,"t":"他们何尝像风前的碎秸，如暴风刮去的糠秕呢？","notes":[]},{"n":19,"t":"神为恶人的儿女积蓄罪孽，不如本人遭报，好使他亲自知道。","notes":[]},{"n":20,"t":"愿他亲眼看见自己败亡，亲自饮全能者的愤怒。","notes":[]},{"n":21,"t":"他的岁月既尽，他身后还顾他的家吗？","notes":[]},{"n":22,"t":"谁能将知识教导神呢？是他审判那些居高位的。","notes":[]},{"n":23,"t":"有人至死身体强壮，尽得平顺安逸；","notes":[]},{"n":24,"t":"他的肚腹充满奶汁，他的骨髓滋润。","notes":["“他的肚腹充满奶汁”或译“他的桶子里满了奶”。"]},{"n":25,"t":"有人至死心中痛苦，从未尝过福乐的滋味；","notes":[]},{"n":26,"t":"他们同样躺卧于尘土，虫子覆盖他们。","notes":[]},{"n":27,"t":"“看哪，我知道你们的意念，并残害我的计谋。","notes":[]},{"n":28,"t":"你们说：‘权贵的房屋在哪里？恶人住过的帐棚在哪里？’","notes":[]},{"n":29,"t":"你们没有询问那些过路的人吗？你们不承认他们的证据吗？","notes":[]},{"n":30,"t":"就是恶人在患难的日子得存留，在愤怒的日子得逃脱。","notes":[]},{"n":31,"t":"他所行的，有谁当面给他说明？他所做的，有谁报应他呢？","notes":[]},{"n":32,"t":"然而他要被抬到坟地，并有人看守墓穴。","notes":[]},{"n":33,"t":"他要以谷中的土块为甘甜；人人要跟在他后面，在他前面去的无数。","notes":[]},{"n":34,"t":"你们怎能以空话安慰我呢？你们的对答全都错谬！”","notes":[]}]},"22":{"heading":"第三次对话","verses":[{"n":1,"t":"提幔人以利法回答说：","notes":[]},{"n":2,"t":"“人能使神有益吗？智慧人能使他有益吗？","notes":["“智慧人...有益吗？”或译“智慧人但能有益于己。”"]},{"n":3,"t":"你为人公义，岂能叫全能者喜悦呢？你行为完全，岂能使他得利呢？","notes":[]},{"n":4,"t":"他岂是因你敬畏的心就责备你，审判你吗？","notes":[]},{"n":5,"t":"你的罪恶岂不是大吗？你的罪孽不是没有穷尽吗？","notes":[]},{"n":6,"t":"因你无故强取弟兄的抵押，剥去赤身者的衣服。","notes":[]},{"n":7,"t":"疲乏的人，你没有给他水喝；饥饿的人，你没有给他食物。","notes":[]},{"n":8,"t":"有能力的人得土地；尊贵的人住在其中。","notes":[]},{"n":9,"t":"你打发寡妇空手回去，你折断孤儿的膀臂。","notes":[]},{"n":10,"t":"因此，有罗网环绕你，有恐惧忽然使你惊惶；","notes":[]},{"n":11,"t":"或有黑暗使你看不见，有洪水淹没你。","notes":["“或有...看不见”：七十士译本是“你的光变成黑暗”。"]},{"n":12,"t":"“神岂不是在高天吗？你看星宿的顶点何其高呢！","notes":[]},{"n":13,"t":"你说：‘神知道什么？他岂能透过幽暗施行审判呢？","notes":[]},{"n":14,"t":"密云将他遮盖，使他不能看见；他周游穹苍。’","notes":[]},{"n":15,"t":"你要依从上古的道吗？这道是恶人行过的。","notes":[]},{"n":16,"t":"他们未到时候就被抓去；他们的根基被江河冲去。","notes":["“就被抓去”或译“布满皱纹”。"]},{"n":17,"t":"他们向神说：‘离开我们吧！’全能者能把他们怎么样呢？","notes":[]},{"n":18,"t":"然而，是神以美物充满他们的房屋；恶人的计谋离我好远！","notes":[]},{"n":19,"t":"义人看见他们的结局就欢喜；无辜的人嗤笑他们：","notes":["原文没有“他们的结局”。"]},{"n":20,"t":"‘攻击我们的果然被剪除，剩余的都被火吞灭。’","notes":[]},{"n":21,"t":"“你要与神和好，要和平，这样，福气必临到你。","notes":[]},{"n":22,"t":"你当领受他口中的教导，将他的言语存在心里。","notes":[]},{"n":23,"t":"你若归向全能者，就必得建立。你要从你帐棚中远离不义，","notes":[]},{"n":24,"t":"你要将黄金丢到尘土里，将俄斐的金子丢在溪河石头之间；","notes":[]},{"n":25,"t":"全能者就必作你的黄金，作你成堆的银子。","notes":[]},{"n":26,"t":"那时，你要以全能者为喜乐，向神仰脸。","notes":[]},{"n":27,"t":"你要向他祷告，他就听你；你也要还你的愿。","notes":[]},{"n":28,"t":"你定意要做何事，必然为你成就；亮光也必照耀你的路。","notes":[]},{"n":29,"t":"当人降卑，你说：是因骄傲；眼目谦卑的人，神必然拯救。","notes":[]},{"n":30,"t":"不是无辜的人，神尚且要搭救他；他必因你手中的清洁得蒙拯救。”","notes":["“不是无辜的人...搭救他”：七十士译本是“神搭救无辜的人”。"]}]},"23":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"“如今我的哀告还算为悖逆；我虽唉哼，他的手仍然重重责罚我。","notes":["“他的手...责罚我”是根据七十士译本和其他古译本；原文是“我的手是重的”。"]},{"n":3,"t":"惟愿我知道哪里可以寻见神，能到他的台前，","notes":[]},{"n":4,"t":"我就在他面前陈明我的案件，满口辩诉。","notes":[]},{"n":5,"t":"我必知道他回答我的言语，明白他向我所要说的。","notes":[]},{"n":6,"t":"他岂用大能与我争辩呢？不！他必理会我。","notes":[]},{"n":7,"t":"在那里正直人可以与他辩论，我就必永远脱离那审判我的。","notes":[]},{"n":8,"t":"“看哪，我往前走，他不在那里；往后退，也没有察觉他。","notes":[]},{"n":9,"t":"他在左边行事，我却看不见他；他转向右边，我也见不到他。","notes":["“他转向右边”或译“他在右边隐藏”。"]},{"n":10,"t":"然而他知道我所走的路；他试炼我，我就如纯金。","notes":[]},{"n":11,"t":"我的脚紧跟他的步伐；我谨守他的道，并不偏离。","notes":[]},{"n":12,"t":"他嘴唇的命令，我未曾背弃；我看重他口中的言语，过于我需用的饮食。","notes":["“我需用的饮食”或译“我的原则”。","“我看重...饮食。”七十士译本是“我把他的言语珍藏在我胸怀。”"]},{"n":13,"t":"只是他心志已定，谁能使他转意呢？他心里所愿的，就行出来。","notes":[]},{"n":14,"t":"因此，为我所定的，他必做成，这类的事他还有许多。","notes":[]},{"n":15,"t":"所以我在他面前惊惶；我思想就惧怕他。","notes":[]},{"n":16,"t":"神使我丧胆，全能者使我惊惶。","notes":[]},{"n":17,"t":"但我并非被黑暗剪除，只是幽暗遮盖了我的脸。","notes":[]}]},"24":{"heading":"","verses":[{"n":1,"t":"“为何全能者不定下期限？为何认识他的人看不到那些日子呢？","notes":[]},{"n":2,"t":"有人挪移地界，抢夺群畜去放牧。","notes":[]},{"n":3,"t":"他们拉走孤儿的驴，强取寡妇的牛作抵押。","notes":[]},{"n":4,"t":"他们使贫穷人离开正道；世上的困苦人尽都隐藏。","notes":[]},{"n":5,"t":"看哪，他们如同野驴出到旷野，殷勤寻找食物，在野地给孩童糊口。","notes":[]},{"n":6,"t":"他们收割别人田间的庄稼，摘取恶人剩余的葡萄。","notes":[]},{"n":7,"t":"他们终夜赤身无衣，在寒冷中毫无遮盖。","notes":[]},{"n":8,"t":"他们在山上被大雨淋湿，因没有避身之处就拥抱磐石。","notes":[]},{"n":9,"t":"又有人从母怀中抢走孤儿，在困苦人身上强取抵押品。","notes":["“在困苦人身上强取抵押品”：原文另译“强取困苦人的婴孩作抵押”。"]},{"n":10,"t":"困苦人赤身无衣，到处流浪，饿着肚子扛抬禾捆，","notes":[]},{"n":11,"t":"他们在围墙内榨油，踹压酒池，自己却口渴。","notes":[]},{"n":12,"t":"在城内垂死的人呻吟，受伤的人哀号；神却不理会狂妄的事。","notes":[]},{"n":13,"t":"“又有人背弃光明，不认识光明的道，不留在光明的路上。","notes":[]},{"n":14,"t":"杀人者黎明起来，杀害困苦人和贫穷人，夜间又作盗贼。","notes":[]},{"n":15,"t":"奸夫的眼等候黄昏，说：‘没有眼睛能见我’，就把脸蒙住。","notes":[]},{"n":16,"t":"盗贼黑夜挖洞；他们白日躲藏，并不认识光明。","notes":[]},{"n":17,"t":"他们全都看早晨如死荫，因为他们熟悉死荫的惊骇。","notes":[]},{"n":18,"t":"“恶人在水面上快速飘荡，他们在地上所得的产业被诅咒；无人再回到他们的葡萄园。","notes":[]},{"n":19,"t":"干旱炎热融化雪水；阴间也如此吞没犯罪的人。","notes":[]},{"n":20,"t":"怀他的母胎忘记他；虫子要吃他，觉得甘甜；他不再被人记念；不义的人必如树折断。","notes":[]},{"n":21,"t":"“他与不怀孕不生育的妇人交往，却不善待寡妇。","notes":["“他与...交往”：七十士译本和其他古译本是“他恶待不怀孕的妇人”。"]},{"n":22,"t":"然而神用能力保全有势力的人；那性命难保的人仍然兴起。","notes":[]},{"n":23,"t":"神使他安稳，他就有所倚靠；神的眼目看顾他们的道路。","notes":[]},{"n":24,"t":"他们高升，不过片刻就没有了；他们降为卑，被除灭，与众人一样，又如谷的穗子被割下。","notes":["“他们降为卑...一样”或译“他们像花一样枯干凋谢”。"]},{"n":25,"t":"若不是这样，谁能指证我是说谎的，以我的言语为毫无根据呢？”","notes":[]}]},"25":{"heading":"","verses":[{"n":1,"t":"书亚人比勒达回答说：","notes":[]},{"n":2,"t":"“神有统治之权，威严可畏；他在高处施行和平。","notes":[]},{"n":3,"t":"他的军队岂能数算？他的光向谁不会升起呢？","notes":["“他的光...升起呢”：七十士译本是“他向谁不会埋伏呢”。"]},{"n":4,"t":"这样，在神面前人怎能称义？妇人所生的怎能洁净？","notes":[]},{"n":5,"t":"看哪，在神眼前，月亮无光，星宿也不皎洁，","notes":[]},{"n":6,"t":"更何况是如虫的人，如蛆的世人呢！","notes":[]}]},"26":{"heading":"","verses":[{"n":1,"t":"约伯回答说：","notes":[]},{"n":2,"t":"“无能的人蒙你何等的帮助！膀臂无力的人蒙你何等的拯救！","notes":[]},{"n":3,"t":"无智慧的人蒙你何等的指教！你向他显出丰富的知识。","notes":[]},{"n":4,"t":"你向谁发出言语？谁的灵从你而出？","notes":[]},{"n":5,"t":"在大水和水族以下，阴魂战兢。","notes":[]},{"n":6,"t":"在神面前，阴间显露；冥府也不得遮掩。","notes":["“冥府”：原文音译“亚巴顿”，意思是“灭亡之地”。"]},{"n":7,"t":"神将北极铺在空中，将大地悬在虚空。","notes":[]},{"n":8,"t":"他将水包在密云中，盛水的云却不破裂。","notes":[]},{"n":9,"t":"他遮蔽宝座的正面，把他的云彩铺在其上。","notes":[]},{"n":10,"t":"他在水面上划一圆圈，直到光明与黑暗的交界。","notes":[]},{"n":11,"t":"天的柱子震动，因他的斥责惊奇。","notes":[]},{"n":12,"t":"他以能力搅动大海，藉知识打伤拉哈伯。","notes":["“搅动”或译“平静”。"]},{"n":13,"t":"他藉自己的灵使天空晴朗；他的手刺杀爬得快的蛇。","notes":[]},{"n":14,"t":"看哪，这不过是神工作的些微；我们听见他的话，是何等细微的声音！他大能的雷声谁能明白呢？”","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"约伯继续发表他的言论说：","notes":[]},{"n":2,"t":"“我指着夺去我公道的永生神，并使我心中愁苦的全能者起誓：","notes":[]},{"n":3,"t":"只要我的生命尚在我里面，神所赐的气息仍在我鼻孔内，","notes":[]},{"n":4,"t":"我的唇绝不说不义，我的舌也不说诡诈。","notes":[]},{"n":5,"t":"我断不以你们为义；我至死不放弃自己的纯正！","notes":[]},{"n":6,"t":"我持定我的义，并不放松；在世的日子，我的心不责备我。","notes":[]},{"n":7,"t":"“愿我的仇敌如恶人一样；愿那起来攻击我的，如不义之人一般。","notes":[]},{"n":8,"t":"不敬虔的人有什么指望呢？神要剪除他，取他的性命。","notes":["本节或译“不敬虔的人虽然得利，神夺取其命的时候还有什么指望呢？”"]},{"n":9,"t":"患难临到他，神岂听他的呼求？","notes":[]},{"n":10,"t":"他岂以全能者为乐，随时求告神呢？","notes":[]},{"n":11,"t":"神手所做的，我要指教你们；全能者所行的，我也不会隐瞒。","notes":[]},{"n":12,"t":"看哪，你们自己也都见过，为何全变为这样虚妄呢？","notes":[]},{"n":13,"t":"“这是神为恶人所定的份，残暴人从全能者所得的产业：","notes":[]},{"n":14,"t":"倘若他的儿女增多，仍被刀所杀；他的子孙必不得饱食。","notes":[]},{"n":15,"t":"他遗留的人必死而埋葬，他的寡妇也不哀哭。","notes":[]},{"n":16,"t":"他虽积蓄银子如尘沙，堆积衣服如泥土，","notes":[]},{"n":17,"t":"他尽管堆积，义人却要穿上，无辜的人却要分取银子。","notes":[]},{"n":18,"t":"他建造房屋如虫做窝，又如守望者所搭的棚。","notes":[]},{"n":19,"t":"他虽富足躺卧，却不得收殓，他张开眼睛，就不在了。","notes":["“却不得收殓”：七十士译本和其他古译本是“却不会继续这样”。"]},{"n":20,"t":"惊恐如洪水将他追上，暴风在夜间将他刮去。","notes":[]},{"n":21,"t":"东风把他吹去，他就走了；风将他刮离原地。","notes":[]},{"n":22,"t":"风无情地击打他，他试图逃脱风的手。","notes":["“风”或译“神”；下同。"]},{"n":23,"t":"风要因他拍掌，并要发叱声，使他离开原地。”","notes":[]}]},"28":{"heading":"歌颂智慧","verses":[{"n":1,"t":"“银子有矿；炼金有场。","notes":[]},{"n":2,"t":"铁从土里开采，铜从矿石熔出。","notes":[]},{"n":3,"t":"人探索黑暗的尽头，查究矿石直到极处，那是幽暗和死荫；","notes":[]},{"n":4,"t":"他在无人居住之处开凿矿穴，在无足迹之地被遗忘，与人远离，悬空摇摆。","notes":["“在无足迹之地被遗忘”或译“过路的人也想不到他们”。"]},{"n":5,"t":"地出产粮食，地底翻腾如火。","notes":[]},{"n":6,"t":"地的石头是蓝宝石之处，那里还有金沙。","notes":[]},{"n":7,"t":"鸷鸟不知那条路，鹰眼也未曾见过。","notes":[]},{"n":8,"t":"狂傲的野兽未曾踩踏，猛烈的狮子也未曾经过。","notes":[]},{"n":9,"t":"“人动手凿开坚石，翻倒山的根基，","notes":[]},{"n":10,"t":"在磐石中凿出水道，亲眼看见各样宝物。","notes":[]},{"n":11,"t":"他封闭河川不得涓滴，使隐藏之物显露出来。","notes":["“他封闭河川不得涓滴”：原文另译“他封闭河川的水源”。"]},{"n":12,"t":"“然而，智慧何处可寻？聪明之地在哪里？","notes":[]},{"n":13,"t":"智慧的价值无人能知，活人之地也无处可寻。","notes":["“智慧的价值”：七十士译本是“智慧的道路”。"]},{"n":14,"t":"深渊说：‘不在我里面。’沧海说：‘不在我这里。’","notes":[]},{"n":15,"t":"智慧不可用黄金换取，也不能用白银秤她的价值。","notes":[]},{"n":16,"t":"俄斐的金子和贵重的红玛瑙，以及蓝宝石，不足与她比拟；","notes":[]},{"n":17,"t":"黄金和玻璃不足与她比较；纯金的器皿不足兑换她。","notes":[]},{"n":18,"t":"珊瑚、水晶都不值得提；智慧的价值胜过宝石。","notes":["“宝石”或译“珍珠”。"]},{"n":19,"t":"古实的红璧玺不足与她比较；纯金也不足与她比拟。","notes":[]},{"n":20,"t":"“智慧从何处来呢？聪明之地在哪里？","notes":[]},{"n":21,"t":"她隐藏，远离众生的眼目，她掩蔽，远离空中的飞鸟。","notes":[]},{"n":22,"t":"毁灭和死亡说：‘我们风闻其名。’","notes":[]},{"n":23,"t":"“神明白智慧的道路，知道智慧的所在。","notes":[]},{"n":24,"t":"因为他鉴察直到地极，遍观普天之下，","notes":[]},{"n":25,"t":"要为风定轻重，又度量诸水，","notes":[]},{"n":26,"t":"为雨定律例，为雷电定道路。","notes":[]},{"n":27,"t":"那时他看见智慧，就谈论她，坚定她，并且查究她。","notes":[]},{"n":28,"t":"他对人说：‘看哪，敬畏主就是智慧；远离恶事就是聪明。’”","notes":[]}]},"29":{"heading":"约伯最后的申诉","verses":[{"n":1,"t":"约伯继续发表他的言论说：","notes":[]},{"n":2,"t":"“惟愿我如从前的岁月，如神保护我的日子。","notes":[]},{"n":3,"t":"那时他的灯照在我头上，我藉他的光行过黑暗。","notes":[]},{"n":4,"t":"在我壮年的时候，神亲密的情谊临到我的帐棚中。","notes":[]},{"n":5,"t":"全能者仍与我同在，我的儿女都环绕我。","notes":[]},{"n":6,"t":"我的脚洗在乳酪当中；磐石为我流出油河。","notes":[]},{"n":7,"t":"我出到城门，在广场安排座位，","notes":[]},{"n":8,"t":"年轻人见我而回避，老年人起身站立。","notes":[]},{"n":9,"t":"王子都停止说话，用手捂口；","notes":[]},{"n":10,"t":"领袖静默无声，舌头贴住上膛。","notes":[]},{"n":11,"t":"耳朵听见了，称我有福；眼睛看见了，就称赞我。","notes":[]},{"n":12,"t":"因我拯救了哀求的困苦人和无人帮助的孤儿。","notes":[]},{"n":13,"t":"将要灭亡的为我祝福，我使寡妇心中欢呼。","notes":[]},{"n":14,"t":"我穿上公义，它遮蔽我；我的公平如外袍和冠冕。","notes":[]},{"n":15,"t":"我作瞎子的眼，瘸子的脚。","notes":[]},{"n":16,"t":"我作贫穷人的父；我不认识之人的案件，我也去查明。","notes":[]},{"n":17,"t":"我打破不义之人的大牙，从他牙齿中夺走他所抢的。","notes":[]},{"n":18,"t":"我说：‘我要增添我的日子如尘沙，我必死在自己家中。","notes":["“自己家中”：原文是“自己的窝里”。"]},{"n":19,"t":"我的根伸展到水边，露水夜宿我的枝上。","notes":[]},{"n":20,"t":"我的荣耀在我身上更新，我的弓在我手中日新。’","notes":[]},{"n":21,"t":"“人听我说话而等候，为我的教导而静默。","notes":[]},{"n":22,"t":"我说话之后，他们就不再说；我的言语滴在他们身上。","notes":[]},{"n":23,"t":"他们等候我如等雨水，又张口如切慕春雨。","notes":[]},{"n":24,"t":"我向他们微笑，他们不敢相信；他们不使我脸上的光失色。","notes":[]},{"n":25,"t":"我为他们选择道路，又坐首位；我如君王在军队中居住，又如人安慰哀伤的人。”","notes":[]}]},"30":{"heading":"","verses":[{"n":1,"t":"“但如今，比我年轻的人讥笑我；我曾藐视他们的父亲，不放在我的牧羊犬中。","notes":[]},{"n":2,"t":"他们的精力既已衰败，手中的气力于我何益？","notes":[]},{"n":3,"t":"他们因穷乏饥饿，没有生气，在荒废凄凉的幽暗中啃干燥之地。","notes":[]},{"n":4,"t":"他们在草丛之中采咸草，罗腾树的根成为他们的食物。","notes":["“罗腾”是音译，小树名，松类。"]},{"n":5,"t":"他们从人群中被赶出，人追喊他们如贼一般，","notes":[]},{"n":6,"t":"以致他们住在荒谷，住在地洞和岩穴中。","notes":[]},{"n":7,"t":"他们在草丛中叫唤，在荆棘下挤成一团。","notes":[]},{"n":8,"t":"这都是愚顽卑微人的儿女；他们被鞭打，赶出境外。","notes":[]},{"n":9,"t":"“现在这些人以我为歌曲，以我为笑谈。","notes":[]},{"n":10,"t":"他们厌恶我，躲避我，不住地吐唾沫在我脸上。","notes":[]},{"n":11,"t":"神松开我的弓弦使我受苦，他们就在我面前脱去辔头。","notes":["“我的弓弦”：原文另译“他的弓弦”。"]},{"n":12,"t":"这伙人在我右边起来，他们推开我的脚，筑灾难之路攻击我。","notes":[]},{"n":13,"t":"他们毁坏我的道，加增我的灾害；他们毋须人帮助。","notes":[]},{"n":14,"t":"他们来，如同闯进大缺口，在暴风间滚动。","notes":[]},{"n":15,"t":"惊恐倾倒在我身上，我的尊荣被逐如风；我的福禄如云飘去。","notes":[]},{"n":16,"t":"“现在我的心极其悲伤，困苦的日子将我抓住。","notes":[]},{"n":17,"t":"夜间，我里面的骨头刺痛，啃着我的没有止息。","notes":[]},{"n":18,"t":"我的外衣因大力扭皱 ，内衣的领子把我勒住。","notes":["“我的外衣...扭皱”：七十士译本是“他用大力抓住我的外衣”。"]},{"n":19,"t":"神把我扔在淤泥之中，我就像尘土和灰烬一样。","notes":[]},{"n":20,"t":"我呼求你，你不应允我；我站起来，你只是望着我。","notes":[]},{"n":21,"t":"你对我变得残忍，大能的手追逼我。","notes":[]},{"n":22,"t":"你把我提到风中，使我乘风而去，使我消失在烈风之中。","notes":[]},{"n":23,"t":"我知道你要使我归于死亡，到那为众生所定的阴宅。","notes":[]},{"n":24,"t":"“然而，人在废墟岂不伸手？遇灾难时一定呼救。","notes":["“遇灾难时一定呼救。”原文另译“遇灾难时岂不呼救呢？”或“遇灾难时必得帮助。”"]},{"n":25,"t":"人遭难的日子，我岂不为他哭泣呢？人贫穷的时候，我岂不为他忧愁呢？","notes":[]},{"n":26,"t":"我仰望福气，灾祸就来到；我等待光明，黑暗便来临。","notes":[]},{"n":27,"t":"我内心烦扰不安，困苦的日子临到我身。","notes":[]},{"n":28,"t":"我在阴暗中行走，没有日光，我在会众中站立求救。","notes":["“我在阴暗中...日光”或译“我变得黝黑并非因日晒”。"]},{"n":29,"t":"我与野狗为弟兄，我跟鸵鸟为同伴。","notes":[]},{"n":30,"t":"我的皮肤变黑脱落，我的骨头因热烧焦。","notes":[]},{"n":31,"t":"我的琴音变为哀泣；我的箫声变为哭声。”","notes":[]}]},"31":{"heading":"","verses":[{"n":1,"t":"“我与眼睛立约，怎能凝望少女呢？","notes":[]},{"n":2,"t":"从至上的神所得之分，从至高全能者所得之业是什么呢？","notes":[]},{"n":3,"t":"岂不是祸患临到不义的，灾害临到作恶的吗？","notes":[]},{"n":4,"t":"神岂不察看我的道路，数点我所有的脚步吗？","notes":[]},{"n":5,"t":"“我若与虚谎同行，我脚若紧跟诡诈，","notes":[]},{"n":6,"t":"愿神用公道的天平秤我，愿他知道我的纯正。","notes":[]},{"n":7,"t":"我的脚步若偏离正路，我的心若随从我眼目，我的手掌若粘有污秽；","notes":[]},{"n":8,"t":"愿我栽种，别人来吃，我的农作物连根拔出。","notes":[]},{"n":9,"t":"“我心若因妇人受迷惑，在邻舍的门外等候，","notes":[]},{"n":10,"t":"就愿我妻子给别人推磨，别人与她同寝。","notes":[]},{"n":11,"t":"因为这是邪恶的事，审判官裁定的罪孽。","notes":[]},{"n":12,"t":"这是一场火，直烧到毁灭，必拔除我一切的家产。","notes":["“毁灭”：原文音译“亚巴顿”，意思是“灭亡之地”。"]},{"n":13,"t":"“我的仆婢与我争辩，我若藐视不听他们的冤情，","notes":[]},{"n":14,"t":"神兴起的时候，我怎样行呢？他察问的时候，我怎样回答他呢？","notes":[]},{"n":15,"t":"造我在母腹中的，不也是造了他吗？在母胎中使我们成形的，岂不是同一位吗？","notes":[]},{"n":16,"t":"“我若不让贫寒人遂其所愿，或是叫寡妇眼中失望，","notes":[]},{"n":17,"t":"或独自吃自己的食物，孤儿没有吃其中些许；","notes":[]},{"n":18,"t":"从我年轻时，孤儿就与我一同长大，我好像他的父亲，我从出母腹就扶助寡妇；","notes":["“我从出母腹...寡妇”：原文另译“从他出母腹我就扶助他”。"]},{"n":19,"t":"我若见人因无衣死亡，或见贫穷人毫无遮盖；","notes":[]},{"n":20,"t":"我若不使他真心为我祝福，不使他因我羊的毛得暖；","notes":[]},{"n":21,"t":"我若举手攻击孤儿，因为在城门口见有帮助我的；","notes":[]},{"n":22,"t":"情愿我的肩膀从肩胛骨脱落，我的膀臂从肱骨折断。","notes":[]},{"n":23,"t":"因神降的灾祸使我恐惧，因他的威严，我什么都不能。","notes":["“因神...使我恐惧”：原文另译“因敬畏神的心临到我”。"]},{"n":24,"t":"“我若以黄金为我的指望，对纯金说：你是我的倚靠；","notes":[]},{"n":25,"t":"我若因财物丰裕，因手多得资财而欢喜；","notes":[]},{"n":26,"t":"我若见太阳发光，明月运行，","notes":[]},{"n":27,"t":"心就暗暗被引诱，口亲吻自己的手；","notes":[]},{"n":28,"t":"这也是审判官裁定的罪孽，因为我背弃了至上的神。","notes":[]},{"n":29,"t":"“我若见恨我的遇难就欢喜，见他遭灾就高兴；","notes":[]},{"n":30,"t":"其实我没有容许口犯罪，以诅咒要他的性命；","notes":[]},{"n":31,"t":"若我帐棚中的人未曾说：‘谁不以他的肉食吃饱呢？’","notes":[]},{"n":32,"t":"我未曾让旅客在街上过夜，却开门迎接行路的人；","notes":[]},{"n":33,"t":"我若像亚当遮掩自己的过犯，将罪孽藏在怀中；","notes":["“像亚当”或译“向人”。"]},{"n":34,"t":"我若因大大惧怕众人，又因宗族的藐视而恐惧，以致我缄默不言，闭门不出；","notes":[]},{"n":35,"t":"惟愿有一位肯听我！看哪，我的记号，愿全能者回答我！愿那与我争讼的写下状词！","notes":[]},{"n":36,"t":"我必把它带在肩上，绑在头上为冠冕。","notes":[]},{"n":37,"t":"我必向神述说我脚步的数目，如同王子进到他面前。","notes":[]},{"n":38,"t":"“若我的田地喊冤告我，犁沟也一同哭泣；","notes":[]},{"n":39,"t":"我若吃地的出产不给银钱，或叫地的原主丧命；","notes":[]},{"n":40,"t":"愿蒺藜生长代替麦子，恶臭的草代替大麦。”约伯的话说完了。","notes":[]}]},"32":{"heading":"以利户的话","verses":[{"n":1,"t":"于是这三个人因约伯看自己为义就停止，不再回答他。","notes":[]},{"n":2,"t":"那时布西人兰族巴拉迦的儿子以利户发怒了。他向约伯发怒，因约伯自以为义，不以神为义。","notes":[]},{"n":3,"t":"他又向约伯的三个朋友发怒，因为他们想不出回答的话来，仍以约伯为有罪。","notes":[]},{"n":4,"t":"以利户因为他们比自己年老，就等候要与约伯说话。","notes":[]},{"n":5,"t":"以利户见这三个人口中无话回答，就发怒。","notes":[]},{"n":6,"t":"布西人巴拉迦的儿子以利户回答说：“我年轻，你们年长，因此我退让，不敢向你们陈述我的意见。","notes":[]},{"n":7,"t":"我说：‘年长的当先说话；寿高的当以智慧教导人。’","notes":[]},{"n":8,"t":"其实，是人里面的灵，全能者的气使人有聪明。","notes":[]},{"n":9,"t":"寿高的不都有智慧，年老的不都明白公平。","notes":[]},{"n":10,"t":"因此我说：‘你们要听我，我也要陈述我的意见。’","notes":[]},{"n":11,"t":"“看哪，我等候你们的话，侧耳听你们的高见；直到你们找到要说的言语。","notes":[]},{"n":12,"t":"我留心听你们，看哪，你们中间无一人能折服约伯，回答他的话。","notes":[]},{"n":13,"t":"你们切不可说：‘我们寻得智慧；神能胜他，人却不能。’","notes":["“能胜他”：原文另译“教导我们”。"]},{"n":14,"t":"约伯没有用言语与我争辩；我也不用你们的话回答他。","notes":[]},{"n":15,"t":"“他们惊惶不再回答，一言不发。","notes":[]},{"n":16,"t":"我岂因他们不说话，因他们站住不再回答，仍旧等候呢？","notes":[]},{"n":17,"t":"我也要以我的一番话回答，我也要陈述我的意见。","notes":[]},{"n":18,"t":"因为我满怀言语，我里面的灵激动我。","notes":[]},{"n":19,"t":"看哪，我的肚腹如酒囊没有气孔，又如新皮袋快要破裂。","notes":["“新皮袋”：原文另译“铁匠的风箱”。"]},{"n":20,"t":"我要说话，使我舒畅；我要张开嘴唇回答。","notes":[]},{"n":21,"t":"我必不看人的情面，也不奉承人。","notes":[]},{"n":22,"t":"我不懂得奉承；不然，造我的主必快快除灭我。”","notes":[]}]},"33":{"heading":"","verses":[{"n":1,"t":"“但是，约伯啊，请听我的言语，侧耳听我一切的话。","notes":[]},{"n":2,"t":"看哪，我开口，我的舌在上膛发言。","notes":[]},{"n":3,"t":"我的言语要表明心中的正直，我嘴唇所知道的就诚实地说。","notes":[]},{"n":4,"t":"神的灵造了我，全能者的气使我得生。","notes":[]},{"n":5,"t":"你若能够，就请回答我；请你站起来，在我面前陈明。","notes":[]},{"n":6,"t":"看哪，我在神面前与你一样，也是用泥土造成的。","notes":[]},{"n":7,"t":"看哪，我不用威严恐吓你，也不用势力重压你。","notes":[]},{"n":8,"t":"“其实，你向我耳朵说话，我听见你言语的声音：","notes":[]},{"n":9,"t":"‘我是纯洁无过的，我是无辜的，在我里面没有罪孽。","notes":[]},{"n":10,"t":"看哪，神找机会攻击我，以我为他的仇敌，","notes":[]},{"n":11,"t":"把我的脚锁上木枷，察看我一切的道路。’","notes":[]},{"n":12,"t":"“看哪，你这话无理，我要回答你，因神比世人更大。","notes":[]},{"n":13,"t":"你为何与他争论：‘他任何事都不向人解答’？","notes":[]},{"n":14,"t":"神说一次、两次，人却不理会。","notes":[]},{"n":15,"t":"世人在床上沉睡安眠时，在梦中和夜间的异象里，","notes":[]},{"n":16,"t":"神就开通世人的耳朵，把警告印在他们心上，","notes":["“把警告印在他们心上”：原文另译“用警告惊吓他们”。"]},{"n":17,"t":"好叫人转离自己的行为，叫壮士远离骄傲，","notes":[]},{"n":18,"t":"拦阻人不陷入地府，不让他命丧刀下。","notes":["“命丧刀下”：原文另译“生命经过死河”。"]},{"n":19,"t":"“人在床上被疼痛惩治，骨头不住地挣扎，","notes":[]},{"n":20,"t":"以致生命厌弃食物，心中厌恶美味。","notes":[]},{"n":21,"t":"他的肉消瘦，难以看见；先前看不见的骨头都凸出来。","notes":[]},{"n":22,"t":"他的性命临近地府，他的生命挨近灭命者。","notes":[]},{"n":23,"t":"一千天使中，若有一个作传话的临到他，指示人所当行的事，","notes":[]},{"n":24,"t":"神就施恩给他，说：‘要救赎他免得下入地府，我已经得了赎价。","notes":["“救赎他”：有古抄本和古译本是“释放他”。"]},{"n":25,"t":"他的肉要比孩童的肉更嫩；他就返老还童。’","notes":[]},{"n":26,"t":"他向神祷告，神就悦纳他；他必欢呼朝见神的面，因神恢复他的义。","notes":[]},{"n":27,"t":"他在人前歌唱说：‘我犯了罪，颠倒是非，却没有受该得的报应。","notes":[]},{"n":28,"t":"神救赎我的性命免入地府，我的生命也必见光。’","notes":[]},{"n":29,"t":"“看哪，神两次、三次向人行这一切的事，","notes":[]},{"n":30,"t":"为要从地府救回人的性命，使他被生命之光照耀。","notes":[]},{"n":31,"t":"约伯啊，你当留心听我；不要作声，我要说话。","notes":[]},{"n":32,"t":"你若有话说，可以回答我；你只管说，因我愿以你为义。","notes":[]},{"n":33,"t":"若不然，你当听我；不要作声，我要把智慧教导你。”","notes":[]}]},"34":{"heading":"","verses":[{"n":1,"t":"以利户继续说：","notes":[]},{"n":2,"t":"“你们智慧人要听我的言语，有知识的人要侧耳听我。","notes":[]},{"n":3,"t":"因为耳朵辨别言语，好像上膛品尝食物。","notes":[]},{"n":4,"t":"我们当选择公理，彼此知道何为善。","notes":[]},{"n":5,"t":"约伯曾说：‘我是公义的，神夺去我的公理。","notes":[]},{"n":6,"t":"我有理，岂能说谎呢？我无过，受的箭伤却不能医治。’","notes":["“我有理，岂能说谎呢？”原文另译“我的审判官残酷待我。”七十士译本是“在我的案件上，他说谎。”"]},{"n":7,"t":"哪一个人像约伯，喝讥诮如同喝水呢？","notes":[]},{"n":8,"t":"他与作恶的结伴，和恶人同行。","notes":[]},{"n":9,"t":"他说：‘人以神为乐，总是无益。’","notes":[]},{"n":10,"t":"“所以，你们明理的人要听我，神断不致行恶，全能者断不致不义。","notes":[]},{"n":11,"t":"他必按人所做的报应人，使各人照所行的得报。","notes":[]},{"n":12,"t":"确实地，神必不作恶，全能者必不偏离公平。","notes":[]},{"n":13,"t":"谁派他治理大地？谁安定全世界呢？","notes":[]},{"n":14,"t":"他若专心为己，将灵和气收归自己，","notes":[]},{"n":15,"t":"凡血肉之躯必一同死亡；世人必归于尘土。","notes":[]},{"n":16,"t":"“你若明理，当听这话，侧耳听我言语的声音。","notes":[]},{"n":17,"t":"难道恨恶公平的可以掌权吗？那有公义、有大能的，你岂可定他有罪呢？","notes":[]},{"n":18,"t":"你会对君王说：‘你是卑鄙的’；对贵族说：‘你们是邪恶的’吗？","notes":["本节有古卷和古译本是“他对君王说：‘你是卑鄙的。’对贵族说：‘你们是邪恶的。’”"]},{"n":19,"t":"他待王子不徇情面，也不看重富足的过于贫寒的，因为他们都是他手所造的。","notes":[]},{"n":20,"t":"一瞬间他们就死亡。百姓在半夜中被震动而去世；有权力的被夺去，非藉人手。","notes":[]},{"n":21,"t":"“神的眼目观看人的道路，察看他每一脚步。","notes":[]},{"n":22,"t":"没有黑暗，没有死荫，能给作恶者在那里藏身。","notes":[]},{"n":23,"t":"神不必再三传人到他面前受审判。","notes":[]},{"n":24,"t":"他毋须调查就粉碎有大能的人，指定别人代替他们。","notes":[]},{"n":25,"t":"所以他知道他们的行为，使他们在夜间倾倒压碎。","notes":[]},{"n":26,"t":"他在众目睽睽下击打他们，如同击打恶人。","notes":[]},{"n":27,"t":"因为他们转离不跟从他，不留心他一切的道，","notes":[]},{"n":28,"t":"甚至使贫寒人的哀声达到他那里；他也听了困苦人的哀声。","notes":[]},{"n":29,"t":"他安静，谁能定罪呢？他转脸，谁能见他呢？无论一国或一人都是如此。","notes":[]},{"n":30,"t":"不虔敬的人不得作王，免得百姓陷入圈套。","notes":[]},{"n":31,"t":"“有谁对神说：‘我受了责罚，必不再犯罪；","notes":[]},{"n":32,"t":"我所看不明的，求你指教我；我若行了不义，必不再行’？","notes":[]},{"n":33,"t":"他因你拒绝不接受，就随你的心愿施行报应吗？选择的是你，不是我。你所知道的，只管说吧！","notes":[]},{"n":34,"t":"明理的人必对我说，听我的智慧人也说：","notes":[]},{"n":35,"t":"‘约伯说话没有知识，他的言语毫无智慧。’","notes":[]},{"n":36,"t":"愿约伯被考验到底，因他回答像恶人一样。","notes":[]},{"n":37,"t":"他在罪上又加悖逆；在我们中间引起疑惑 ，用许多言语轻慢神。”","notes":["“引起疑惑”：原文直译“敲击”。"]}]},"35":{"heading":"","verses":[{"n":1,"t":"以利户继续说：","notes":[]},{"n":2,"t":"“你以为这话有理，说：‘我在神面前是公义的。’","notes":[]},{"n":3,"t":"你说：‘这对你有什么益处？我不犯罪有什么好处呢？’","notes":[]},{"n":4,"t":"至于我，我要用言语回答你和跟你一起的朋友。","notes":[]},{"n":5,"t":"你要向天观看，瞻望那高于你的穹苍。","notes":[]},{"n":6,"t":"你若犯罪，能使神受何害呢？你的过犯加增，能使神受何损呢？","notes":[]},{"n":7,"t":"你若是公义，能加增他什么呢？他从你手里还接受什么呢？","notes":[]},{"n":8,"t":"你的罪恶只影响像你这类的人；你的公义也只影响世人。","notes":[]},{"n":9,"t":"“人因多受欺压就哀求，因强权者的膀臂而求救。","notes":[]},{"n":10,"t":"但无人说：‘造我的神在哪里？他使人夜间歌唱，","notes":[]},{"n":11,"t":"教导我们多过地上的走兽，使我们比空中的飞鸟更聪明。’","notes":[]},{"n":12,"t":"因为恶人骄傲，他们在那里呼求，他却不回答。","notes":[]},{"n":13,"t":"虚妄的呼求，神必不垂听；全能者必不留意。","notes":[]},{"n":14,"t":"何况你说，你不得见他。案件就在他面前，你等候他吧。","notes":[]},{"n":15,"t":"但如今因他未曾发怒降罚，也一点都不理会狂傲，","notes":[]},{"n":16,"t":"所以约伯开口说虚妄的话，多多发表无知识的言语。”","notes":[]}]},"36":{"heading":"","verses":[{"n":1,"t":"以利户继续说：","notes":[]},{"n":2,"t":"“你再给我片时，我就指示你，因我还有话要为神说。","notes":[]},{"n":3,"t":"我要把我的知识从远处引来，我要将公义归给造我的主。","notes":[]},{"n":4,"t":"我的言语绝不虚假，有全备知识的与你同在。","notes":[]},{"n":5,"t":"“看哪，神有大能，并不藐视人；他的心智能力广大。","notes":[]},{"n":6,"t":"他不让恶人活着，却为困苦人伸冤。","notes":[]},{"n":7,"t":"他的眼目不远离义人，却使他们和君王同坐宝座，永远被高举 。","notes":["“却使他们...被高举”或译“却使君王坐上宝座，使他们永远被高举”。"]},{"n":8,"t":"他们若被锁链捆住，被苦难的绳索缠住，","notes":[]},{"n":9,"t":"他就向他们指示他们的作为和过犯，以及他们的狂妄自大。","notes":[]},{"n":10,"t":"他也开通他们的耳朵来领受教导，吩咐他们回转离开罪孽。","notes":[]},{"n":11,"t":"他们若听从事奉他，就必度日亨通，历年享福。","notes":[]},{"n":12,"t":"他们若不听从，就要被刀杀灭，无知无识而死。","notes":[]},{"n":13,"t":"“那心中不敬虔的人积蓄怒气；神捆绑他们，他们竟不求救。","notes":[]},{"n":14,"t":"他们必在青年时死亡，与神庙娼妓一样丧命。","notes":[]},{"n":15,"t":"神藉着困苦救拔困苦人，藉所受的欺压开通他们的耳朵。","notes":[]},{"n":16,"t":"神也必引你脱离患难，进入宽阔不狭窄之地；摆在你席上的必满有肥甘。","notes":[]},{"n":17,"t":"“但你充满着恶人的辩辞，辩辞和审判抓住你。","notes":[]},{"n":18,"t":"不可让愤怒触动你，使你破口谩骂；也不可因赎价大而偏行。","notes":["“不可让...破口谩骂”：原文另译“不要因他的富足而让愤怒触动你”。"]},{"n":19,"t":"你的呼求和一切的势力，果真有用，使你不遭患难吗？","notes":["“你的呼求”或译“你的资财”。"]},{"n":20,"t":"不要切慕黑夜，就是众民在本处被除灭的时候。","notes":[]},{"n":21,"t":"你要谨慎，不可偏向罪孽，因你选择罪孽过于苦难。","notes":[]},{"n":22,"t":"看哪，神因他的能力而崇高；有谁像他那样作教师呢？","notes":[]},{"n":23,"t":"谁派定他的道路呢？谁能说：‘你行了不义’？","notes":[]},{"n":24,"t":"“你要记得颂赞他的作为，就是人所歌颂的。","notes":[]},{"n":25,"t":"他的作为，万人都看见；世人也从远处观看。","notes":[]},{"n":26,"t":"看哪，神崇高，我们不能知道；他的年数，不能测度。","notes":[]},{"n":27,"t":"因他吸取水点，水点就从云雾中变成雨；","notes":[]},{"n":28,"t":"云彩将雨落下，沛然降于世人。","notes":[]},{"n":29,"t":"又有谁能明白密云如何铺张，和神行宫的雷声呢？","notes":[]},{"n":30,"t":"看哪，他的亮光普照自己的四围；他覆盖海的深处。","notes":[]},{"n":31,"t":"因他用这些审判众民，又赐丰富的粮食。","notes":["“审判”或译“治理”。"]},{"n":32,"t":"他以闪电遮手掌，命令它击中靶子。","notes":[]},{"n":33,"t":"所发的雷声将他显明，牲畜也指明要起暴风。”","notes":["“牲畜也指明要起暴风”：原文另译“他因罪孽而发出妒火的怒气”。"]}]},"37":{"heading":"","verses":[{"n":1,"t":"“因此我心战兢，从原处移动。","notes":[]},{"n":2,"t":"听啊，听他轰轰的声音，是神口中所发的响声。","notes":[]},{"n":3,"t":"他发响声震遍天下，他的闪电直到地极。","notes":[]},{"n":4,"t":"随后，人听见他的声音，是那轰轰的声音；他发出威严的雷声，而不加以遏止。","notes":[]},{"n":5,"t":"神发出奇妙的雷声；他行大事，我们不能测透。","notes":[]},{"n":6,"t":"他对雪说：‘要降在地上’；对大雨和暴雨也是这样说。","notes":[]},{"n":7,"t":"他封住各人的手，叫所造的万人都知道他的作为。","notes":[]},{"n":8,"t":"野兽进入穴中，卧在自己洞内。","notes":[]},{"n":9,"t":"暴风来自内宫，寒冷出于狂风。","notes":[]},{"n":10,"t":"神嘘气成冰，凝结宽阔之水，","notes":[]},{"n":11,"t":"使密云盛满水气，乌云散布闪电。","notes":[]},{"n":12,"t":"云藉着他的指引游行旋转，在世界的地面上行他一切所吩咐的，","notes":[]},{"n":13,"t":"或为责罚，或为他的地，或为慈爱，都是他所行的。","notes":[]},{"n":14,"t":"“约伯啊，侧耳听这话，要站立，思想神奇妙的作为。","notes":[]},{"n":15,"t":"你知道神如何安排这些，如何使云中的闪电照耀吗？","notes":[]},{"n":16,"t":"你知道云彩如何浮于空中，知识全备者奇妙的作为吗？","notes":[]},{"n":17,"t":"你知道南风使地寂静，你的衣服就变为热吗？","notes":[]},{"n":18,"t":"你岂能与神同铺穹苍，坚固如同铸成的镜子吗？","notes":[]},{"n":19,"t":"我们因在黑暗中，不会陈说，请你指教我们该对他说什么。","notes":[]},{"n":20,"t":"有人告诉他我要说话吗？岂有人说他愿被吞灭吗？","notes":[]},{"n":21,"t":"“现在，人不得见穹苍的亮光；风一吹过，天色晴朗。","notes":[]},{"n":22,"t":"金色的光辉来自北方，在神那里有可畏的威严。","notes":[]},{"n":23,"t":"全能者，我们不能测度；他大有能力，又有公平，满有公义，必不苦待人。","notes":[]},{"n":24,"t":"所以，世人敬畏他；凡自以为有智慧的，他都不看顾。”","notes":["“自以为”：原文直译“心中”。"]}]},"38":{"heading":"耶和华回答约伯","verses":[{"n":1,"t":"那时，耶和华从旋风中回答约伯说：","notes":[]},{"n":2,"t":"“谁用无知的言语使我的旨意暗昧不明？","notes":[]},{"n":3,"t":"你要如勇士束腰；我问你，你可以让我知道。","notes":[]},{"n":4,"t":"“我立大地根基的时候，你在哪里？你若明白事理，只管说吧！","notes":[]},{"n":5,"t":"你知道是谁定地的尺度，是谁把准绳拉在其上吗？","notes":[]},{"n":6,"t":"地的根基安置在何处？地的角石是谁安放的？","notes":[]},{"n":7,"t":"那时，晨星一同歌唱；神的众使者也都欢呼。","notes":[]},{"n":8,"t":"“当海水冲出，如出母胎，谁用门将它关闭呢？","notes":[]},{"n":9,"t":"是我用云彩当海的衣服，用幽暗当包裹它的布，","notes":[]},{"n":10,"t":"为它定界限，又安门和闩，","notes":[]},{"n":11,"t":"说：‘你只可到这里，不可越过；你狂傲的浪要到此止住。’","notes":[]},{"n":12,"t":"“你有生以来，曾命定晨光，曾使黎明知道自己的地位，","notes":[]},{"n":13,"t":"抓住地的四极，把恶人从其中驱逐出来吗？","notes":[]},{"n":14,"t":"地改变如泥上盖印，万物出现如衣服一样。","notes":[]},{"n":15,"t":"亮光不照恶人，高举的膀臂也必折断。","notes":[]},{"n":16,"t":"“你曾进到海之源，或在深渊的隐密处行走吗？","notes":[]},{"n":17,"t":"死亡的门曾向你显露吗？死荫的门你曾见过吗？","notes":[]},{"n":18,"t":"地的广大，你能测透吗？你若全知道，只管说吧！","notes":[]},{"n":19,"t":"“往光明居所的路在哪里？黑暗的地方在何处？","notes":[]},{"n":20,"t":"你能将它带到其领域，能辨明其居所之路吗？","notes":[]},{"n":21,"t":"你知道的，因为那时你已出生，你活的日子数目也多。","notes":[]},{"n":22,"t":"“你曾进入雪之库，或见过雹的仓吗？","notes":[]},{"n":23,"t":"雪雹是我为灾难的时候，为打仗和战争的日子所预备。","notes":[]},{"n":24,"t":"光亮从何路分开？东风从何路分散遍地？","notes":[]},{"n":25,"t":"“谁为大雨分道，谁为雷电开路，","notes":[]},{"n":26,"t":"使雨降在无人之地，在无人居住的旷野，","notes":[]},{"n":27,"t":"使荒废凄凉之地得以丰足，青草得以生长？","notes":[]},{"n":28,"t":"“雨有父亲吗？露珠是谁生的呢？","notes":[]},{"n":29,"t":"冰出于谁的胎？天上的霜是谁生的呢？","notes":[]},{"n":30,"t":"诸水坚硬如石头，深渊之面凝结成冰。","notes":[]},{"n":31,"t":"“你能为昴星系结吗？你能为参星解带吗？","notes":[]},{"n":32,"t":"你能按时领出星宿吗？能引导北斗与其众星吗？","notes":[]},{"n":33,"t":"你知道天的定律吗？你能使地归其权下吗？","notes":[]},{"n":34,"t":"“你能向密云扬起声来，使倾盆的雨遮盖你吗？","notes":[]},{"n":35,"t":"你能发出闪电，使它们行走，并对你说‘我们在这里’吗？","notes":["“它们”指“闪电”。"]},{"n":36,"t":"谁将智慧放在朱鹭中？谁将聪明赐给雄鸡？","notes":["“朱鹭”或译“怀”。","“雄鸡”或译“心内”。"]},{"n":37,"t":"谁能用智慧数算云彩？谁能倾倒天上的瓶呢？","notes":[]},{"n":38,"t":"那时，尘土聚集成团，土块紧紧结连。","notes":[]},{"n":39,"t":"“你能为母狮抓取猎物，使少壮的狮子饱足吗？","notes":[]},{"n":40,"t":"那时，它们在洞中蹲伏，在隐密处埋伏。","notes":[]},{"n":41,"t":"谁能为乌鸦预备食物呢？那时，乌鸦之雏哀求神，因无食物飞来飞去。”","notes":[]}]},"39":{"heading":"","verses":[{"n":1,"t":"“你知道岩石间的野山羊几时生产吗？你能观察母鹿下小鹿吗？","notes":[]},{"n":2,"t":"你能数算它们怀胎的月数吗？你知道它们几时生产吗？","notes":[]},{"n":3,"t":"它们屈身，生下幼儿，就解除了阵痛。","notes":[]},{"n":4,"t":"其子渐渐肥壮，在荒野长大；它们出去，不再归回。","notes":[]},{"n":5,"t":"“谁放野驴自由？谁解开快驴的绳索？","notes":[]},{"n":6,"t":"我使旷野作它的住处，使盐地当它的居所。","notes":[]},{"n":7,"t":"它嘲笑城内的喧嚷，不听赶牲口的喝声。","notes":[]},{"n":8,"t":"诸山是它漫游的草场，它寻找各样青绿之物。","notes":[]},{"n":9,"t":"“野牛岂肯服事你？岂肯在你的槽旁过夜？","notes":[]},{"n":10,"t":"你岂能用套绳将野牛系于犁沟？它岂肯随你耙松山谷之地？","notes":[]},{"n":11,"t":"你岂可因它力大就倚靠它？岂可把你的工交给它做呢？","notes":[]},{"n":12,"t":"你岂能靠它把你的谷物运回，又收聚在你的禾场上吗？","notes":["本节原文另译“你岂能信赖它会回来，又收聚你禾场上的谷物呢？”"]},{"n":13,"t":"“鸵鸟的翅膀欢然拍动，但岂是鹳的翎毛和羽毛吗？","notes":["“但岂是...羽毛吗”或译“它的翎毛和羽毛岂是显示慈爱吗”；“慈爱”与“鹳”的希伯来话发音相近。"]},{"n":14,"t":"因它把蛋留在地上，使蛋在尘土中得温暖，","notes":[]},{"n":15,"t":"却忘记脚会把蛋踹碎，野兽会践踏它。","notes":[]},{"n":16,"t":"它粗暴待雏，似乎不是自己生的；虽徒然劳苦，也不惧怕。","notes":["“劳苦”指“孵蛋”。"]},{"n":17,"t":"因为神使它忘记智慧，也未将悟性分给它。","notes":[]},{"n":18,"t":"它几时挺身展开翅膀，就嘲笑马和骑马的人。","notes":[]},{"n":19,"t":"“马的力量是你所赐的吗？它颈项上的鬃是你披上的吗？","notes":[]},{"n":20,"t":"是你叫它跳跃像蝗虫吗？它喷气之威严使人惊惶。","notes":[]},{"n":21,"t":"它用蹄在谷中挖地，以能力欢跃；它出去迎击仇敌。","notes":["“它用蹄...挖地”：原文直译“它们在谷中挖地”。","“仇敌”：原文是“兵器”。"]},{"n":22,"t":"它嘲笑惧怕，并不惊惶，也不因刀剑退却。","notes":[]},{"n":23,"t":"箭袋在它身上铮铮有声，枪和短枪闪闪发亮。","notes":[]},{"n":24,"t":"它震颤激动，将地吞下 ；一听角声就站不住。","notes":["“将地吞下”意思是“全速奔跑”。"]},{"n":25,"t":"每逢角声一响，它说：‘啊哈！’它从远处闻到战争的气息，听见军官如雷的吼声和呐喊。","notes":[]},{"n":26,"t":"“鹰展开翅膀向南飞翔，岂是藉着你的智慧吗？","notes":[]},{"n":27,"t":"大鹰上腾在高处搭窝，岂是听你的指示吗？","notes":[]},{"n":28,"t":"它住在山岩，以山峰和坚固之所为家，","notes":[]},{"n":29,"t":"从那里窥察食物，眼睛自远方瞭望。","notes":[]},{"n":30,"t":"它的雏吸血；被杀的人在哪里，它也在哪里。”","notes":[]}]},"40":{"heading":"","verses":[{"n":1,"t":"耶和华继续对约伯说：","notes":[]},{"n":2,"t":"“强辩的岂可与全能者争论？与神辩驳的可以回答吧！”","notes":[]},{"n":3,"t":"于是，约伯回答耶和华说：","notes":[]},{"n":4,"t":"“看哪，我是卑贱的！我用什么回答你呢？我只好用手捂住我的口。","notes":[]},{"n":5,"t":"我说了一次，就不回答；说了两次，不再说了。”","notes":[]},{"n":6,"t":"于是，耶和华从旋风中回答约伯说：","notes":[]},{"n":7,"t":"“你要如勇士束腰；我问你，你可以让我知道。","notes":[]},{"n":8,"t":"你岂可废弃我的判断？岂可定我有罪，好显自己为义吗？","notes":[]},{"n":9,"t":"你有神那样的膀臂吗？你能像他那样发雷声吗？","notes":[]},{"n":10,"t":"“你要以荣耀庄严为妆饰，以尊荣威严为衣服。","notes":[]},{"n":11,"t":"你要发出你满溢的怒气，见一切骄傲的人，使他降卑；","notes":[]},{"n":12,"t":"你见一切骄傲的人，将他制伏，把恶人践踏在原来地方。","notes":[]},{"n":13,"t":"你将他们一同埋藏在尘土中，把他们的脸遮蔽在隐密处。","notes":["“把他们...隐密处”意思是“把他们捆绑在阴间”。"]},{"n":14,"t":"这样，我也向你承认，你的右手能救你自己。","notes":[]},{"n":15,"t":"“看哪，我造河马，也造了你；它吃草像牛一样。","notes":[]},{"n":16,"t":"看哪，它的力气在腰间，能力在肚腹的肌肉上。","notes":[]},{"n":17,"t":"它挺直尾巴如香柏树，它大腿的筋紧密结合。","notes":["“挺直”或译“垂下”。"]},{"n":18,"t":"它的骨头好像铜管；它的肢体仿佛铁棍。","notes":[]},{"n":19,"t":"“它在神所造之物中为首，只有创造它的能携刀临近它。","notes":[]},{"n":20,"t":"诸山为它产出食物，百兽也在那里游玩。","notes":[]},{"n":21,"t":"它伏在莲叶之下，在芦苇和沼泽的隐密处。","notes":[]},{"n":22,"t":"莲叶的阴影遮蔽它，溪旁的柳树环绕它。","notes":[]},{"n":23,"t":"看哪，河水泛滥，它不慌张；连约旦河涨到它口边，它也安然自若。","notes":[]},{"n":24,"t":"谁能在它眼前捉拿它呢？谁能以圈套穿它鼻子呢？”","notes":[]}]},"41":{"heading":"","verses":[{"n":1,"t":"“你能用鱼钩钓上力威亚探吗？能用绳子压下它的舌头吗？","notes":["“力威亚探”是音译，一种海兽；或译“鳄鱼”。"]},{"n":2,"t":"你能用绳索穿它的鼻子吗？能用钩子穿它的腮骨吗？","notes":[]},{"n":3,"t":"它岂向你连连恳求，向你说温柔的话吗？","notes":[]},{"n":4,"t":"它岂肯与你立约，让你拿它永远作奴仆吗？","notes":[]},{"n":5,"t":"你岂可拿它当雀鸟玩耍？岂可将它系来给你幼女？","notes":[]},{"n":6,"t":"合伙的鱼贩岂可拿它当货物？他们岂可把它分给商人呢？","notes":[]},{"n":7,"t":"你能用倒钩扎满它的皮，能用鱼叉叉满它的头吗？","notes":[]},{"n":8,"t":"把你的手掌按在它身上吧！想一想与它搏斗，你就不再这样做了！","notes":[]},{"n":9,"t":"看哪，对它有指望是徒然的；一见它，岂不也丧胆吗？","notes":["“一见它，岂不也丧胆吗？”原文另译“一见到它，人也丧胆。”有古译本是“一见它，神明也丧胆吗？”"]},{"n":10,"t":"没有那么凶猛的人敢惹它。这样，谁能在我面前站立得住呢？","notes":["“没有...敢惹它。”或译“它不是那么凶猛，以致没有人敢惹它吗？”"]},{"n":11,"t":"谁能与我对质，使我偿还呢？天下万物都是我的。","notes":[]},{"n":12,"t":"“我不能缄默不提它的肢体和力量，以及健美的骨骼。","notes":[]},{"n":13,"t":"谁能剥它的外皮？谁能进它的铠甲之间呢？","notes":["“它的铠甲之间”是根据七十士译本；原文是“它辔头的两边”。"]},{"n":14,"t":"谁能开它的腮颊？它牙齿的四围是可畏的。","notes":[]},{"n":15,"t":"它的背上有一排排的鳞甲，紧紧闭合，封得严密。","notes":["“它的背上...鳞甲”是根据七十士译本；原文是“它以一排排的鳞甲为可夸”。"]},{"n":16,"t":"这鳞甲一一相连，气不得透入其间，","notes":[]},{"n":17,"t":"互相连接，胶结一起，不能分开。","notes":[]},{"n":18,"t":"它打喷嚏就发出光来，它的眼睛好像晨曦。","notes":["“好像晨曦”：原文直译“好像清晨的眼皮”。"]},{"n":19,"t":"从它口中发出烧着的火把，有火星飞迸出来；","notes":[]},{"n":20,"t":"从它鼻孔冒出烟来，如烧开的锅在沸腾。","notes":["“在沸腾”：原文另译“和芦苇”。"]},{"n":21,"t":"它的气点着煤炭，有火焰从它口中发出。","notes":[]},{"n":22,"t":"它颈项中存着劲力，恐惧在它面前蹦跳。","notes":[]},{"n":23,"t":"它的肉块紧紧结连，紧贴其身，不能摇动。","notes":[]},{"n":24,"t":"它的心结实如石头，如下面的磨石那样结实。","notes":[]},{"n":25,"t":"它一起来，神明都恐惧，因崩溃而惊慌失措。","notes":[]},{"n":26,"t":"人用刀剑扎它，是无用的，枪、标枪、尖枪也一样。","notes":[]},{"n":27,"t":"它以铁为干草，以铜为烂木。","notes":[]},{"n":28,"t":"箭不能使它逃走，它看弹石如碎秸。","notes":[]},{"n":29,"t":"它当棍棒作碎秸，它嘲笑短枪的飕飕声。","notes":[]},{"n":30,"t":"它肚腹下面是尖瓦片；它如钉耙刮过淤泥。","notes":[]},{"n":31,"t":"它使深渊滚沸如锅，使海洋如锅中膏油。","notes":[]},{"n":32,"t":"它使走过以后的路发光，令人觉得深渊如同白发。","notes":[]},{"n":33,"t":"尘世上没有像它那样的受造物，一无所惧。","notes":[]},{"n":34,"t":"凡高大的，它盯着看；它在一切狂傲的野兽中作王。”","notes":[]}]},"42":{"heading":"结尾","verses":[{"n":1,"t":"约伯回答耶和华说：","notes":[]},{"n":2,"t":"“我知道，你万事都能做；你的计划不能拦阻。","notes":[]},{"n":3,"t":"谁无知使你的旨意隐藏呢？因此我说的，我不明白；这些事太奇妙，是我不知道的。","notes":[]},{"n":4,"t":"求你听我，我要说话；我问你，求你让我知道。","notes":[]},{"n":5,"t":"我从前风闻有你，现在亲眼看见你。","notes":[]},{"n":6,"t":"因此我撤回，在尘土和炉灰中懊悔。”","notes":["“我撤回”或译“我厌恶”；原文另译“我瓦解了”。"]},{"n":7,"t":"耶和华对约伯说话以后，耶和华就对提幔人以利法说：“我的怒气向你和你两个朋友发作，因为你们议论我，不如我的仆人约伯说的正确。","notes":[]},{"n":8,"t":"现在你们要为自己取七头公牛、七只公羊，到我的仆人约伯那里去，为自己献上燔祭，我的仆人约伯就为你们祈祷。我必悦纳他，不按你们的愚妄处置你们。你们议论我，不如我的仆人约伯说的正确。”","notes":[]},{"n":9,"t":"于是提幔人以利法、书亚人比勒达、拿玛人琐法遵照耶和华所吩咐的去做，耶和华就悦纳约伯。","notes":[]},{"n":10,"t":"约伯为他的朋友祈祷。耶和华就使约伯从苦境中转回，并且耶和华赐给他的比他从前所有的加倍。","notes":["“苦境”：原文直译“掳掠”。"]},{"n":11,"t":"约伯的兄弟、姊妹，和以前所认识的人都来到他那里，在他家里跟他一同吃饭。他们因耶和华所降于他的一切灾祸，都为他悲伤，安慰他。每人送他一块可锡塔和一个金环。","notes":["“可锡塔”：古希伯来钱币单位；参“度量衡表”。"]},{"n":12,"t":"这样，耶和华后来赐福给约伯比先前更多。他有一万四千只羊，六千匹骆驼，一千对牛，一千匹母驴。","notes":[]},{"n":13,"t":"他也有七个儿子，三个女儿。","notes":[]},{"n":14,"t":"他给长女起名叫耶米玛，次女叫基洗亚，三女叫基连哈朴。","notes":[]},{"n":15,"t":"在全地的妇女中找不着像约伯的女儿那样美貌的。她们的父亲使她们在兄弟中得产业。","notes":[]},{"n":16,"t":"此后，约伯又活了一百四十年，得见他的四代儿孙。","notes":[]},{"n":17,"t":"这样，约伯年纪老迈，日子满足而死。","notes":[]}]}},"PSA":{"1":{"heading":"真福","verses":[{"n":1,"t":"不从恶人的计谋，不站罪人的道路，不坐傲慢人的座位，惟喜爱耶和华的律法，昼夜思想他的律法；这人便为有福！","notes":["“思想”或译“默念”。"],"end":2},{"n":3,"t":"他要像一棵树栽在溪水旁，按时候结果子，叶子也不枯干。凡他所做的尽都顺利。","notes":[]},{"n":4,"t":"恶人并不是这样，却像糠秕被风吹散。","notes":[]},{"n":5,"t":"因此，当审判的时候恶人必站立不住，罪人在义人的会众中也是如此。","notes":[]},{"n":6,"t":"因为耶和华知道义人的道路，恶人的道路却必灭亡。","notes":[]}]},"2":{"heading":"神所拣选的君王","verses":[{"n":1,"t":"列国为什么争闹？万民为什么图谋虚妄？","notes":[]},{"n":2,"t":"世上的君王都站稳，臣宰一同算计，要对抗耶和华，对抗他的受膏者：","notes":[]},{"n":3,"t":"“我们要挣脱他们的捆绑，脱去他们的绳索。”","notes":[]},{"n":4,"t":"那坐在天上的必讥笑，主必嗤笑他们。","notes":[]},{"n":5,"t":"那时，他要在怒中责备他们，在烈怒中惊吓他们：","notes":[]},{"n":6,"t":"“我已经在锡安－我的圣山膏立了我的君王。”","notes":[]},{"n":7,"t":"我要传耶和华的圣旨，他对我说：“你是我的儿子，我今日生了你。","notes":[]},{"n":8,"t":"你求我，我就将列国赐你为基业，将地极赐你为田产。","notes":[]},{"n":9,"t":"你必用铁杖打破他们，把他们如同陶匠的瓦器摔碎。”","notes":[]},{"n":10,"t":"现在，君王啊，应当谨慎！世上的审判官哪，要听劝戒！","notes":[]},{"n":11,"t":"当存敬畏的心事奉耶和华，又当战兢而快乐。","notes":[]},{"n":12,"t":"当亲吻儿子，免得他发怒，你们就在半途中灭亡，因为他的怒气快要发作。凡投靠他的，都是有福的。","notes":[]}]},"3":{"heading":"求助的晨祷","verses":[{"n":1,"t":"耶和华啊，我的敌人何其增多！许多人起来攻击我。","notes":[]},{"n":2,"t":"许多人议论我：“他得不到神的帮助。”（细拉）","notes":[]},{"n":3,"t":"但你－耶和华是我四围的盾牌，是我的荣耀，又是令我抬起头来的。","notes":[]},{"n":4,"t":"我用我的声音求告耶和华，他就从他的圣山上应允我。（细拉）","notes":[]},{"n":5,"t":"我躺下，我睡觉，我醒来，耶和华都保佑我。","notes":[]},{"n":6,"t":"虽有成万的百姓周围攻击我，我也不惧怕。","notes":[]},{"n":7,"t":"耶和华啊，求你兴起！我的神啊，求你救我！因为你打断我所有仇敌的腮骨，敲碎了恶人的牙齿。","notes":[]},{"n":8,"t":"救恩属于耶和华；愿你赐福给你的百姓。（细拉）","notes":[]}]},"4":{"heading":"求助的晚祷","verses":[{"n":1,"t":"显我为义的神啊，我呼求的时候，求你应允我！我在困境中，你曾使我宽畅；求你怜悯我，听我的祷告！","notes":[]},{"n":2,"t":"你们这些人哪，你们把我的尊荣变为羞辱，要到几时呢？你们喜爱虚妄，寻找虚假，要到几时呢？（细拉）","notes":["本节七十士译本是“你们这些人哪，你们的心刚硬要到几时呢？你们为什么喜爱虚妄，寻找虚假呢？”"]},{"n":3,"t":"你们要知道，耶和华已将虔诚人分别出来归他自己；我求告耶和华，他必垂听。","notes":[]},{"n":4,"t":"应当畏惧，不可犯罪；在床上的时候，要心里思想，并要安静。（细拉）","notes":[]},{"n":5,"t":"当献上公义的祭，又当倚靠耶和华。","notes":[]},{"n":6,"t":"有许多人说：“谁能指示我们什么好处？耶和华啊，求你用你脸上的光照耀我们。”","notes":[]},{"n":7,"t":"你使我心里喜乐，胜过那丰收五谷新酒的人。","notes":[]},{"n":8,"t":"我必平安地躺下睡觉，因为独有你－耶和华使我安然居住。","notes":[]}]},"5":{"heading":"求主保护","verses":[{"n":1,"t":"耶和华啊，求你侧耳听我的言语，顾念我的心思！","notes":[]},{"n":2,"t":"我的王，我的神啊，求你留心听我呼求的声音！因为我向你祈祷。","notes":[]},{"n":3,"t":"耶和华啊，早晨你必听我的声音；早晨我要向你陈明我的心思，并要警醒。","notes":[]},{"n":4,"t":"因为你不是喜爱邪恶的神，恶人不能与你同住。","notes":[]},{"n":5,"t":"狂傲的人不能站在你眼前；凡作恶的，都是你所恨恶的。","notes":[]},{"n":6,"t":"说谎言的，你必灭绝；好流人血、玩弄诡诈的，都为耶和华所憎恶。","notes":[]},{"n":7,"t":"至于我，我必凭你丰盛的慈爱进入你的居所，我要存敬畏你的心向你的圣殿下拜。","notes":[]},{"n":8,"t":"耶和华啊，求你因我仇敌的缘故，凭你的公义引领我，使你的道路在我面前正直。","notes":[]},{"n":9,"t":"因为他们口中没有诚实，心里充满邪恶，他们的喉咙是敞开的坟墓；他们用舌头谄媚人。","notes":[]},{"n":10,"t":"神啊，求你定他们的罪！愿他们因自己的计谋跌倒；求你因他们过犯众多赶逐他们，因为他们背叛了你。","notes":[]},{"n":11,"t":"凡投靠你的，愿他们喜乐，时常欢呼，因为你庇护他们；又愿那爱你名的人都靠你欢欣。","notes":[]},{"n":12,"t":"耶和华啊，因为你必赐福给义人，你必用恩惠如同盾牌四面护卫他。","notes":[]}]},"6":{"heading":"患难中求助的祈祷","verses":[{"n":1,"t":"耶和华啊，求你不要在怒中责备我，不要在烈怒中惩罚我！","notes":[]},{"n":2,"t":"耶和华啊，求你怜悯我，因为我软弱。耶和华啊，求你医治我，因为我的骨头战抖。","notes":[]},{"n":3,"t":"我的心也大大惊惶。耶和华啊，你要等到几时呢？","notes":[]},{"n":4,"t":"耶和华啊，求你转回搭救我，因你的慈爱拯救我。","notes":[]},{"n":5,"t":"因为死了的人不会记念你，在阴间有谁称谢你？","notes":[]},{"n":6,"t":"我因呻吟而困乏；我每夜流泪，使床铺漂起，把褥子湿透。","notes":[]},{"n":7,"t":"我的眼睛因忧愁而昏花，因敌人的缘故，我的眼目模糊不清。","notes":[]},{"n":8,"t":"你们所有作恶的人，离开我吧！因为耶和华听了我哀哭的声音。","notes":[]},{"n":9,"t":"耶和华听了我的恳求，耶和华必接纳我的祷告。","notes":[]},{"n":10,"t":"我所有的仇敌都必羞愧，大大惊惶；转眼之间，他们要羞愧撤退。","notes":[]}]},"7":{"heading":"为公义而祈祷","verses":[{"n":1,"t":"耶和华－我的神啊，我投靠你！求你救我脱离所有追赶我的人，搭救我出来！","notes":[]},{"n":2,"t":"免得他们像狮子撕裂我，甚至撕碎，无人搭救。","notes":[]},{"n":3,"t":"耶和华－我的神啊，我若行了这事，若有罪孽在我手里，","notes":[]},{"n":4,"t":"我若以恶回报我的朋友，连那无故与我为敌的，我也救了他，","notes":["“连那...救了他”：原文另译“或无缘无故掠夺与我为敌的人”。"]},{"n":5,"t":"就任凭仇敌追赶我，直到追上，把我的性命踏在地上，使我的荣耀归于灰尘。（细拉）","notes":[]},{"n":6,"t":"耶和华啊，求你在怒中起来，挺身而立，抵挡我敌人的烈怒！求你为我兴起！你已经发令施行审判。","notes":[]},{"n":7,"t":"愿万民聚集环绕你！愿你居高位统治他们！","notes":[]},{"n":8,"t":"耶和华向万民施行审判；耶和华啊，求你按我的公义和我心中的纯正判断我。","notes":[]},{"n":9,"t":"愿恶人的恶断绝！愿你坚立义人！因为公义的神察验人的心肠肺腑。","notes":[]},{"n":10,"t":"神是我的盾牌，他拯救心里正直的人。","notes":[]},{"n":11,"t":"神是公义的审判者，又是天天向恶人发怒的神。","notes":[]},{"n":12,"t":"若有人不回头，他的刀必磨快，弓必上弦，预备妥当。","notes":[]},{"n":13,"t":"他也预备了致死的兵器，他所射的是火箭。","notes":[]},{"n":14,"t":"看哪，恶人怀邪恶，养毒害，生虚假。","notes":[]},{"n":15,"t":"他掘了坑，挖得太深，竟掉在自己所挖的陷阱里。","notes":[]},{"n":16,"t":"他的毒害必回到自己头上，他的残暴必落到自己的脑袋上。","notes":[]},{"n":17,"t":"我要照着耶和华的公义称谢他，要歌颂耶和华至高者的名。","notes":[]}]},"8":{"heading":"神的荣耀和人的尊贵","verses":[{"n":1,"t":"耶和华－我们的主啊，你的名在全地何其美！你将你的荣耀彰显于天。","notes":["“你将...天”：七十士译本是“你的荣耀高举于天”。"]},{"n":2,"t":"你因敌人的缘故，从孩童和吃奶的口中建立了能力，使仇敌和报仇的闭口无言。","notes":[]},{"n":3,"t":"我观看你手指所造的天，并你所陈设的月亮星宿。","notes":[]},{"n":4,"t":"人算什么，你竟顾念他！世人算什么，你竟眷顾他！","notes":[]},{"n":5,"t":"你使他比神微小一点，赐他荣耀尊贵为冠冕。","notes":["“神”或译“天使”；七十士译本是“天使”。"]},{"n":6,"t":"你派他管理你手所造的，使万物，就是一切的牛羊、田野的牲畜、空中的鸟、海里的鱼，凡游在水里的，都服在他的脚下。","notes":[],"end":8},{"n":9,"t":"耶和华－我们的主啊，你的名在全地何其美！","notes":[]}]},"9":{"heading":"称颂耶和华的公义","verses":[{"n":1,"t":"我要一心称谢耶和华，传扬你一切奇妙的作为。","notes":[]},{"n":2,"t":"我要因你欢喜快乐；至高者啊，我要歌颂你的名！","notes":[]},{"n":3,"t":"我的仇敌回转撤退的时候，他们在你面前跌倒灭亡。","notes":[]},{"n":4,"t":"因你已经为我伸冤，为我辩护；你坐在宝座上，按公义审判。","notes":[]},{"n":5,"t":"你曾斥责列国，灭绝恶人；你曾涂去他们的名，直到永永远远。","notes":[]},{"n":6,"t":"仇敌到了尽头；他们遭毁坏，直到永远。你拆毁他们的城镇，连他们的名字也都消灭！","notes":["“名字”：原文是“纪念”。"]},{"n":7,"t":"惟耶和华坐在王位上，直到永远；他已经为审判摆设宝座。","notes":[]},{"n":8,"t":"他要按公义审判世界，按正直判断万民。","notes":[]},{"n":9,"t":"耶和华要作受欺压者的庇护所，在患难时的庇护所。","notes":[]},{"n":10,"t":"耶和华啊，认识你名的人要倚靠你，因你没有离弃寻求你的人。","notes":[]},{"n":11,"t":"应当歌颂居于锡安的耶和华，将他所做的传扬在万民中。","notes":[]},{"n":12,"t":"那位追讨流人血的，他记念受屈的人，不忘记困苦人的哀求。","notes":[]},{"n":13,"t":"耶和华啊，求你怜悯我！你是从死门把我提升起来的，求你看那恨我的人所加给我的苦难，","notes":[]},{"n":14,"t":"好让我述说你一切的美德。我要在锡安的城门因你的救恩欢乐。","notes":["“锡安”：原文直译“锡安女子”。"]},{"n":15,"t":"外邦人陷在自己所掘的坑中，他们的脚被自己暗设的网罗缠住了。","notes":[]},{"n":16,"t":"耶和华已将自己显明，他已施行审判；恶人被自己手所做的缠住了。（细拉）","notes":["“恶人...缠住了”或译“他叫恶人被自己手所做的缠住了”。"]},{"n":17,"t":"恶人，就是忘记神的外邦人，都必归到阴间。","notes":[]},{"n":18,"t":"贫穷人必不永久被忘，困苦人的指望必不永远落空。","notes":[]},{"n":19,"t":"耶和华啊，求你兴起，不容世人得胜！愿外邦人在你面前受审判！","notes":[]},{"n":20,"t":"耶和华啊，求你使他们恐惧，愿外邦人知道自己不过是人。（细拉）","notes":[]}]},"10":{"heading":"为公义而祈祷","verses":[{"n":1,"t":"耶和华啊，你为什么站在远处？在患难的时候为什么隐藏？","notes":[]},{"n":2,"t":"恶人骄横地追逼困苦人；愿他们陷在自己所设的计谋里。","notes":[]},{"n":3,"t":"因为恶人以自己的心愿自夸，贪财的背弃耶和华，并且轻慢他。","notes":["“贪财的...轻慢他”或译“他称赞贪财的，却轻慢耶和华”。"]},{"n":4,"t":"恶人面带骄傲，不寻找耶和华；他的思想中全无神。","notes":[]},{"n":5,"t":"他的路时常亨通，你的审判不在他眼里。至于他所有的敌人，他都向他们发怒气。","notes":[]},{"n":6,"t":"他心里说：“我必不动摇，世世代代不遭灾难。”","notes":[]},{"n":7,"t":"他满口咒骂、诡诈、欺压，舌底尽是毒害、奸恶。","notes":[]},{"n":8,"t":"他在村庄埋伏等候，在隐密处杀害无辜的人，他的眼睛窥探无倚无靠的人。","notes":[]},{"n":9,"t":"他埋伏在暗地，如狮子蹲在洞中。他埋伏，要俘掳困苦人；他拉网，就把困苦人掳去。","notes":[]},{"n":10,"t":"他屈身蹲伏，无倚无靠的人就倒在他的暴力之下。","notes":[]},{"n":11,"t":"他心里说：“神竟忘记了，神转脸永不观看。”","notes":[]},{"n":12,"t":"耶和华啊，求你兴起！神啊，求你举手！不要忘记困苦人！","notes":[]},{"n":13,"t":"恶人为何轻慢神，心里说“你必不追究”？","notes":[]},{"n":14,"t":"你已经察看，顾念人的忧患和愁苦，放在你的手中。无倚无靠的人把自己交托给你，你向来是帮助孤儿的。","notes":[]},{"n":15,"t":"求你打断恶人的膀臂，至于坏人，求你追究他的恶，直到净尽。","notes":[]},{"n":16,"t":"耶和华永永远远为王，外邦人从他的地已经灭绝了。","notes":[]},{"n":17,"t":"耶和华啊，困苦人的心愿你早已听见；你必坚固他们的心，也必侧耳听他们的祈求，","notes":[]},{"n":18,"t":"为要给孤儿和受欺压的人伸冤，使世上的人不再威吓他们。","notes":[]}]},"11":{"heading":"在主里得安稳","verses":[{"n":1,"t":"我投靠耶和华；你们怎么对我说：“你当像鸟逃到你们的山去；","notes":[]},{"n":2,"t":"看哪，恶人弯弓，把箭搭在弦上，要在暗中射那心里正直的人。","notes":[]},{"n":3,"t":"根基若毁坏，义人还能做什么呢？”","notes":[]},{"n":4,"t":"耶和华在他的圣殿里，耶和华在天上的宝座上；他的眼睛察看，他的眼目察验世人。","notes":["“眼目”：原文是“眼皮”。"]},{"n":5,"t":"耶和华考验义人；惟有恶人和喜爱暴力的人，他心里恨恶。","notes":[]},{"n":6,"t":"他要向恶人密布罗网，烈火、硫磺、热风作他们杯中的份。","notes":[]},{"n":7,"t":"因为耶和华是公义的，他喜爱义行，正直人必得见他的面。","notes":[]}]},"12":{"heading":"求助的祈祷","verses":[{"n":1,"t":"耶和华啊，求你帮助，因虔诚人断绝了，世人中间忠信的人消失了。","notes":[]},{"n":2,"t":"人人向邻舍说谎；他们说话嘴唇油滑，心口不一。","notes":[]},{"n":3,"t":"愿耶和华剪除一切油滑的嘴唇，夸大的舌头。","notes":[]},{"n":4,"t":"他们说：“我们必能以舌头取胜，我们的嘴唇是自己的，谁能作我们的主呢？”","notes":[]},{"n":5,"t":"耶和华说：“因为困苦人的冤屈和贫穷人的叹息，我现在要起来，把他安置在他所切慕的稳妥之地。”","notes":[]},{"n":6,"t":"耶和华的言语是纯净的言语，如同银子在泥做的炉中炼过七次。","notes":[]},{"n":7,"t":"耶和华啊，你必保护他们，你必保佑他们永远脱离这世代的人。","notes":[]},{"n":8,"t":"卑鄙的人在世人中高升时，就有恶人四处横行。","notes":[]}]},"13":{"heading":"求耶和华看顾","verses":[{"n":1,"t":"耶和华啊，你忘记我要到几时呢？要到永远吗？你转脸不顾我要到几时呢？","notes":[]},{"n":2,"t":"我心里筹算，终日愁苦，要到几时呢？我的仇敌升高压制我，要到几时呢？","notes":[]},{"n":3,"t":"耶和华－我的神啊，求你看顾我，应允我！求你使我眼目明亮，免得我沉睡至死；","notes":[]},{"n":4,"t":"免得我的仇敌说“我胜了他”；免得我的敌人在我动摇的时候喜乐。","notes":[]},{"n":5,"t":"但我倚靠你的慈爱，我的心因你的救恩快乐。","notes":[]},{"n":6,"t":"我要向耶和华歌唱，因他厚厚地恩待我。","notes":[]}]},"14":{"heading":"人的邪恶","verses":[{"n":1,"t":"愚顽人心里说：“没有神。”他们都败坏，行了可憎恶的事，没有一个人行善。","notes":[]},{"n":2,"t":"耶和华从天上垂看世人，要看有明白的没有，有寻求神的没有。","notes":[]},{"n":3,"t":"他们都偏离正路，一同变为污秽，没有行善的，连一个也没有。","notes":[]},{"n":4,"t":"作恶的都没有知识吗？他们吞吃我的百姓如同吃饭一样，并不求告耶和华。","notes":[]},{"n":5,"t":"他们在那里大大害怕，因为神在义人的族类中。","notes":[]},{"n":6,"t":"你们叫困苦人的筹算变为羞辱，然而耶和华是他的避难所。","notes":[]},{"n":7,"t":"但愿以色列的救恩出自锡安。当耶和华救回他被掳子民的时候，雅各要快乐，以色列要欢喜。","notes":[]}]},"15":{"heading":"得居圣山者的品行","verses":[{"n":1,"t":"耶和华啊，谁能寄居你的帐幕？谁能居住你的圣山？","notes":[]},{"n":2,"t":"就是行为正直、做事公义、心里说实话的人。","notes":[]},{"n":3,"t":"他不以舌头谗害人，不恶待朋友，也不随伙毁谤邻舍。","notes":[]},{"n":4,"t":"他眼中藐视匪类，却尊重那敬畏耶和华的人。他发了誓，虽然自己吃亏也不更改。","notes":[]},{"n":5,"t":"他不放债取利，不受贿赂以害无辜。做这些事的人必永不动摇。","notes":[]}]},"16":{"heading":"为信心稳固而祈祷","verses":[{"n":1,"t":"神啊，求你保佑我，因为我投靠你。","notes":[]},{"n":2,"t":"我曾对耶和华说：“你是我的主，我的福气惟独从你而来。”","notes":["“我”：有古卷是“你”。"]},{"n":3,"t":"论到世上的圣民，他们是尊贵的人，是我最喜悦的。","notes":[]},{"n":4,"t":"追逐别神的，他们的愁苦必增加；他们所浇奠的血我不献上，我嘴唇也不提别神的名号。","notes":["“追逐”：原文另译“选择”。"]},{"n":5,"t":"耶和华是我的产业，是我杯中的福分；我所得的，你为我持守。","notes":[]},{"n":6,"t":"用绳量给我的地界，坐落在佳美之处；我的产业实在美好。","notes":[]},{"n":7,"t":"我要称颂那指引我的耶和华，在夜间我的心肠也指教我。","notes":[]},{"n":8,"t":"我让耶和华常在我面前，因他在我右边，我就不致动摇。","notes":[]},{"n":9,"t":"因此，我的心欢喜，我的灵快乐；我的肉身也要安然居住。","notes":["“灵”：原文是“荣耀”。"]},{"n":10,"t":"因为你必不将我的灵魂撇在阴间，也不让你的圣者见地府。","notes":["“我的灵魂”或译“我”。","“地府”：七十士译本是“朽坏”。"]},{"n":11,"t":"你必将生命的道路指示我。在你面前有满足的喜乐，在你右手中有永远的福乐。","notes":[]}]},"17":{"heading":"无辜的人的祷告","verses":[{"n":1,"t":"耶和华啊，求你垂听公义的呼声，留心听我的呼求！求你侧耳听我这没有诡诈的嘴唇的祈祷！","notes":[]},{"n":2,"t":"愿判我公正的话从你面前发出，愿你的眼睛察看正直。","notes":[]},{"n":3,"t":"你已经考验我的心，你在夜间鉴察我。你熬炼我，却找不到错失，我立志叫我口中没有过失。","notes":[]},{"n":4,"t":"论到人的行为，我谨守你嘴唇的言语，不走残暴人的道路。","notes":[]},{"n":5,"t":"我的脚紧紧跟随你的脚踪，我的两脚未曾滑跌。","notes":[]},{"n":6,"t":"神啊，我求告你，因为你必应允我；求你向我侧耳，听我的言语。","notes":[]},{"n":7,"t":"求你显出你奇妙的慈爱，你用右手拯救投靠你的人，脱离那起来攻击他们的人。","notes":[]},{"n":8,"t":"求你保护我，如同保护眼中的瞳人，把我隐藏在你翅膀的荫下，","notes":[]},{"n":9,"t":"使我脱离欺压我的恶人，脱离那围困我要害我命的仇敌。","notes":[]},{"n":10,"t":"他们的心被油脂包裹，用口说骄傲的话。","notes":[]},{"n":11,"t":"他们追逼我，现在他们围困了我们，瞪着眼，要把我们推倒在地。","notes":["“他们追逼我”：原文另译“我们的脚步”。"]},{"n":12,"t":"他像狮子要贪吃猎物，又像少壮狮子蹲伏在暗处。","notes":[]},{"n":13,"t":"耶和华啊，求你兴起，前去迎敌，把他打倒！求你用你的刀救我的命脱离恶人。","notes":[]},{"n":14,"t":"耶和华啊，求你用手救我脱离世人，脱离那只在今生有福分的世人！你以财宝充满他们的肚腹，他们因有儿女就满足，将其余的财物留给他们的孩子。","notes":[]},{"n":15,"t":"至于我，我必因公正得见你的面；我醒了的时候，你的形像使我满足。","notes":[]}]},"18":{"heading":"大卫的胜利之歌","verses":[{"n":1,"t":"耶和华我的力量啊，我爱你！","notes":[]},{"n":2,"t":"耶和华是我的岩石、我的山寨、我的救主、我的神、我的磐石、我所投靠的。他是我的盾牌，是拯救我的角，是我的碉堡。","notes":[]},{"n":3,"t":"我要求告当赞美的耶和华，我必从仇敌手中被救出来。","notes":[]},{"n":4,"t":"死亡的绳索勒住我，毁灭的急流惊吓我，","notes":[]},{"n":5,"t":"阴间的绳索缠绕我，死亡的圈套临到我。","notes":[]},{"n":6,"t":"我在急难中求告耶和华，向我的神呼求。他从殿中听了我的声音，我在他面前的呼求必进入他耳中。","notes":[]},{"n":7,"t":"那时，因他发怒地就震动战抖，山的根基也震动挪移。","notes":[]},{"n":8,"t":"他的鼻孔冒烟上腾，他的口发火焚烧，连煤炭也烧着了。","notes":[]},{"n":9,"t":"他使天垂下，亲自降临，黑云在他脚下。","notes":[]},{"n":10,"t":"他乘坐基路伯飞行，藉着风的翅膀快飞，","notes":[]},{"n":11,"t":"以黑暗为藏身之处，以水的黑暗、天空的密云作四围的行宫。","notes":[]},{"n":12,"t":"因他发出光辉，冰雹和火炭穿透密云。","notes":[]},{"n":13,"t":"耶和华在天上打雷，至高者发出声音，就有冰雹和火炭。","notes":["有古卷和七十士译本没有“就有冰雹和火炭”。"]},{"n":14,"t":"他射出箭来，使仇敌四散；发出连串的闪电，击溃他们。","notes":[]},{"n":15,"t":"耶和华啊，你的斥责一发，你鼻孔的气一出，海底就显现，大地的根基也暴露。","notes":[]},{"n":16,"t":"他从高天伸手抓住我，把我从大水中拉上来。","notes":[]},{"n":17,"t":"他救我脱离强敌和那些恨我的人，因为他们比我强盛。","notes":[]},{"n":18,"t":"我遭遇灾难的日子，他们来攻击我；但耶和华是我的倚靠。","notes":[]},{"n":19,"t":"他领我到宽阔之处，他救拔我，因他喜爱我。","notes":[]},{"n":20,"t":"耶和华必按我的公义报答我，按我手中的清洁赏赐我。","notes":[]},{"n":21,"t":"因为我遵守耶和华的道，未曾作恶离开我的神。","notes":[]},{"n":22,"t":"他的一切典章常在我面前，他的律例我也未曾丢弃。","notes":[]},{"n":23,"t":"我在他面前作了完全人，我也保护自己远离罪孽。","notes":[]},{"n":24,"t":"所以耶和华按我的公义，在他眼前按我手中的清洁赏赐我。","notes":[]},{"n":25,"t":"慈爱的人，你以慈爱待他；完全的人，你以完善待他。","notes":[]},{"n":26,"t":"清洁的人，你以清洁待他；歪曲的人，你以弯曲待他。","notes":[]},{"n":27,"t":"困苦的百姓，你必拯救；高傲的眼目，你使他降卑。","notes":[]},{"n":28,"t":"你必点亮我的灯；耶和华－我的神必照明我的黑暗。","notes":[]},{"n":29,"t":"我藉着你冲入敌军，藉着我的神跳过城墙。","notes":[]},{"n":30,"t":"至于神，他的道是完全的；耶和华的话是纯净的。凡投靠他的，他就作他们的盾牌。","notes":[]},{"n":31,"t":"除了耶和华，谁是神呢？除了我们的神，谁是磐石呢？","notes":[]},{"n":32,"t":"惟有那以力量束我的腰、使我行为完全的，他是神。","notes":[]},{"n":33,"t":"他使我的脚快如母鹿，使我站稳在高处。","notes":[]},{"n":34,"t":"他教导我的手能争战，我的膀臂能开铜造的弓。","notes":[]},{"n":35,"t":"你赐救恩给我作盾牌，你的右手扶持我，你的庇护使我为大。","notes":["“庇护”或译“温和”。"]},{"n":36,"t":"你使我脚步宽阔，我的脚踝未曾滑跌。","notes":[]},{"n":37,"t":"我要追赶我的仇敌，且要追上他们；若不将他们灭绝，我总不归回。","notes":[]},{"n":38,"t":"我要打伤他们，使他们站不起来；他们必倒在我的脚下。","notes":[]},{"n":39,"t":"你曾以力量束我的腰，使我能争战；也曾使那起来攻击我的，都服在我以下。","notes":[]},{"n":40,"t":"你又使我的仇敌在我面前转身逃跑，使我剪除那恨我的人。","notes":[]},{"n":41,"t":"他们呼求，却无人拯救；就是呼求耶和华，他也不应允。","notes":[]},{"n":42,"t":"我捣碎他们，如同风前的灰尘；倾倒他们，如同街上的泥土。","notes":["“倾倒”：有古卷是“践踏”。"]},{"n":43,"t":"你救我脱离百姓的纷争，立我作列国的元首；我素不认识的百姓必事奉我。","notes":[]},{"n":44,"t":"他们一听见我的名声就必顺从我，外邦人要投降我。","notes":[]},{"n":45,"t":"外邦人要丧胆，战战兢兢地出营寨。","notes":[]},{"n":46,"t":"耶和华永远活着。愿我的磐石被称颂，愿救我的神受尊崇。","notes":[]},{"n":47,"t":"这位神为我伸冤，使万民服在我以下。","notes":[]},{"n":48,"t":"他拯救我脱离仇敌，又把我举起，高过那些起来攻击我的人，救我脱离残暴的人。","notes":[]},{"n":49,"t":"耶和华啊，因此我要在外邦中称谢你，歌颂你的名。","notes":[]},{"n":50,"t":"耶和华赐极大的救恩给他所立的王，施慈爱给他的受膏者，就是给大卫和他的后裔，直到永远。","notes":[]}]},"19":{"heading":"造化的荣耀","verses":[{"n":1,"t":"诸天述说神的荣耀，穹苍传扬他手的作为。","notes":[]},{"n":2,"t":"这日到那日发出言语，这夜到那夜传出知识。","notes":[]},{"n":3,"t":"无言无语，也无声音可听。","notes":[]},{"n":4,"t":"它们的声浪传遍天下，它们的言语传到地极。神在其中为太阳安设帐幕，","notes":["“声浪”：原文是“绳索”。"]},{"n":5,"t":"太阳如同新郎步出洞房，又如勇士欢然奔路。","notes":[]},{"n":6,"t":"它从天这边出来，绕到天那边，没有一物可隐藏得不到它的热气。","notes":[]},{"n":7,"t":"耶和华的律法全备，使人苏醒；耶和华的法度确定，使愚蒙人有智慧。","notes":[],"heads":["耶和华的律法"]},{"n":8,"t":"耶和华的训词正直，使人心快活；耶和华的命令清洁，使人眼目明亮。","notes":[]},{"n":9,"t":"耶和华的典章真实，全然公义，敬畏耶和华是纯洁的，存到永远，","notes":[]},{"n":10,"t":"比金子可羡慕，比极多的纯金可羡慕；比蜜甘甜，比蜂房下滴的蜜甘甜。","notes":[]},{"n":11,"t":"因此你的仆人受警戒，遵守这些有极大的赏赐。","notes":[]},{"n":12,"t":"谁能察觉自己的错失呢？求你赦免我隐藏的过犯。","notes":[]},{"n":13,"t":"求你拦阻仆人不犯任意妄为的罪，不容这罪辖制我，我就完全，免犯大罪。","notes":[]},{"n":14,"t":"耶和华－我的磐石，我的救赎主啊，愿我口中的言语，心里的意念在你面前蒙悦纳。","notes":[]}]},"20":{"heading":"祈求胜利","verses":[{"n":1,"t":"愿耶和华在你患难的日子应允你，愿雅各的神的名保护你。","notes":[]},{"n":2,"t":"愿他从圣所救助你，从锡安坚固你，","notes":[]},{"n":3,"t":"记念你的一切祭物，悦纳你的燔祭，（细拉）","notes":[]},{"n":4,"t":"将你心所愿的赐给你，成就你的一切筹算。","notes":[]},{"n":5,"t":"我们要因你的救恩夸胜，要奉我们神的名竖立旌旗。愿耶和华成就你一切所求的！","notes":[]},{"n":6,"t":"现在我知道耶和华必救护他的受膏者，从他神圣的天上应允他，用右手的能力救护他。","notes":[]},{"n":7,"t":"有人靠车，有人靠马，但我们要提耶和华－我们神的名。","notes":[]},{"n":8,"t":"他们都屈身仆倒，我们却起来，坚立不移。","notes":[]},{"n":9,"t":"耶和华啊，求你拯救；我们呼求的时候，愿王应允我们！","notes":["本节七十士译本是“主啊，求你拯救王；我们呼求你的那一天，求你应允我们！”"]}]},"21":{"heading":"为胜利而歌颂","verses":[{"n":1,"t":"耶和华啊，王必因你的能力欢喜；因你的救恩，他的快乐何其大！","notes":[]},{"n":2,"t":"他心里所愿的，你已经赐给他；他嘴唇所求的，你未尝不应允。（细拉）","notes":[]},{"n":3,"t":"你以美善的福气迎接他，把纯金的冠冕戴在他头上。","notes":[]},{"n":4,"t":"他向你祈求长寿，你就赐给他，就是日子长久，直到永远。","notes":[]},{"n":5,"t":"他因你的救恩大有荣耀，你将尊荣威严加在他身上。","notes":[]},{"n":6,"t":"你使他有洪福，直到永远，又使他在你面前欢喜快乐。","notes":[]},{"n":7,"t":"王倚靠耶和华，因至高者的慈爱，王必不动摇。","notes":[]},{"n":8,"t":"你的手要搜出所有的仇敌，你的右手要搜出那些恨你的人。","notes":[]},{"n":9,"t":"你的脸出现的时候，要使他们如在炎热的火炉中。耶和华要在他的震怒中吞灭他们，那火要把他们烧尽。","notes":[]},{"n":10,"t":"你必从世上灭绝他们的幼苗，从人间灭绝他们的后裔。","notes":[]},{"n":11,"t":"因为他们有意加害于你；他们想出计谋，却不能做成。","notes":[]},{"n":12,"t":"你必使他们转身逃跑，向着他们的脸搭箭在弦。","notes":[]},{"n":13,"t":"耶和华啊，愿你因自己的能力显为至高！这样，我们就唱诗，歌颂你的大能。","notes":[]}]},"22":{"heading":"痛苦中的祷告和赞美","verses":[{"n":1,"t":"我的神，我的神，为什么离弃我？为什么远离不救我，不听我的呻吟？","notes":[]},{"n":2,"t":"我的神啊，我白日呼求，你不应允；夜间呼求，也不得安宁。","notes":[]},{"n":3,"t":"但你是神圣的，用以色列的赞美为宝座。","notes":[]},{"n":4,"t":"我们的祖宗倚靠你；他们倚靠你，你解救他们。","notes":[]},{"n":5,"t":"他们哀求你，就蒙解救；他们倚靠你，就不羞愧。","notes":[]},{"n":6,"t":"但我是虫，不是人，被众人羞辱，被百姓藐视。","notes":[]},{"n":7,"t":"凡看见我的都嗤笑我；他们撇嘴摇头：","notes":[]},{"n":8,"t":"“他把自己交托给耶和华，让耶和华救他吧！耶和华既喜爱他，可以搭救他吧！”","notes":[]},{"n":9,"t":"但你是叫我出母腹的，我在母怀里，你就使我有倚靠的心。","notes":[]},{"n":10,"t":"我自出母胎就交在你手里，自我出母腹，你就是我的神。","notes":[]},{"n":11,"t":"求你不要远离我！因为灾难临头，无人帮助。","notes":[]},{"n":12,"t":"许多公牛环绕我，巴珊大力的公牛四面围困我。","notes":[]},{"n":13,"t":"它们向我张口，好像猎食吼叫的狮子。","notes":[]},{"n":14,"t":"我如水被倒出，我的骨头都脱了节，我的心如蜡，在我里面熔化。","notes":[]},{"n":15,"t":"我的精力枯干，如同瓦片，我的舌头紧贴上颚。你将我安置在死灰中。","notes":[]},{"n":16,"t":"犬类围着我，恶党环绕我；他们扎了我的手、我的脚。","notes":[]},{"n":17,"t":"我数遍我的骨头；他们瞪着眼看我。","notes":[]},{"n":18,"t":"他们分我的外衣，为我的内衣抽签。","notes":[]},{"n":19,"t":"耶和华啊，求你不要远离我！我的救主啊，求你快来帮助我！","notes":[]},{"n":20,"t":"求你救我的性命脱离刀剑，使我仅有的脱离犬类，","notes":["“仅有的”就是“生命”。"]},{"n":21,"t":"求你救我脱离狮子的口；你已经应允我，使我脱离野牛的角。","notes":[]},{"n":22,"t":"我要将你的名传给我的弟兄，在会众中我要赞美你。","notes":[]},{"n":23,"t":"敬畏耶和华的人哪，要赞美他！雅各的后裔啊，要荣耀他！以色列的后裔啊，要惧怕他！","notes":[]},{"n":24,"t":"因为他没有藐视、憎恶受苦的人，也没有转脸不顾他们；那受苦之人呼求的时候，他就垂听。","notes":[]},{"n":25,"t":"我在大会中赞美你的话是从你而来，我要在敬畏耶和华的人面前还我的愿。","notes":[]},{"n":26,"t":"愿困苦的人吃得饱足，愿寻求耶和华的人赞美他。愿你们的心永远活着！","notes":[]},{"n":27,"t":"地的四极都要想念耶和华，并且归顺他，列国的万族都要在你面前敬拜。","notes":[]},{"n":28,"t":"因为国度属于耶和华，他是管理列国的。","notes":[]},{"n":29,"t":"地上富足的人都必吃喝而敬拜，凡下到尘土中不能存活自己性命的人，都要在他面前下拜；","notes":["“凡...下拜”：原文另译“凡下到尘土中的人都要在他面前下拜，我的性命为他而存活”。"]},{"n":30,"t":"必有后裔事奉他，主所做的事必传给后代。","notes":[]},{"n":31,"t":"他们必来传他的公义给尚未出生的子民，这是他的作为。","notes":[]}]},"23":{"heading":"耶和华是我牧者","verses":[{"n":1,"t":"耶和华是我的牧者，我必不致缺乏。","notes":[]},{"n":2,"t":"他使我躺卧在青草地上，领我在可安歇的水边。","notes":[]},{"n":3,"t":"他使我的灵魂苏醒，为自己的名引导我走义路。","notes":["“他使我的灵魂苏醒”或译“他使我的心灵苏醒”或“他使我回转”。"]},{"n":4,"t":"我虽然行过死荫的幽谷，也不怕遭害，因为你与我同在；你的杖、你的竿，都安慰我。","notes":[]},{"n":5,"t":"在我敌人面前，你为我摆设筵席；你用油膏了我的头，使我的福杯满溢。","notes":[]},{"n":6,"t":"我一生一世必有恩惠慈爱随着我；我且要住在耶和华的殿中，直到永远。","notes":["“住在”：原文是“回到”。"]}]},"24":{"heading":"伟大的君王","verses":[{"n":1,"t":"地和其中所充满的，世界和住在其中的，都属耶和华。","notes":[]},{"n":2,"t":"他把地建立在海上，安定在江河之上。","notes":[]},{"n":3,"t":"谁能登耶和华的山？谁能站在他的圣所？","notes":[]},{"n":4,"t":"就是手洁心清，意念不向虚妄，起誓不怀诡诈的人。","notes":[]},{"n":5,"t":"他必蒙耶和华赐福，又蒙救他的神使他成义。","notes":[]},{"n":6,"t":"这是寻求耶和华的族类，是寻求你面的雅各。（细拉）","notes":[]},{"n":7,"t":"众城门哪，要抬起头来！永久的门户啊，你们要被举起！荣耀的王将要进来！","notes":[]},{"n":8,"t":"这荣耀的王是谁呢？就是有力有能的耶和华，在战场上大有能力的耶和华！","notes":[]},{"n":9,"t":"众城门哪，要抬起头来！永久的门户啊，你们要高举！荣耀的王将要进来！","notes":[]},{"n":10,"t":"这荣耀的王是谁呢？万军之耶和华是荣耀的王！（细拉）","notes":[]}]},"25":{"heading":"求主指引保护","verses":[{"n":1,"t":"耶和华啊，我的心仰望你。","notes":[]},{"n":2,"t":"我的神啊，我素来倚靠你；求你不要叫我羞愧，不要叫我的仇敌向我夸胜。","notes":[]},{"n":3,"t":"凡等候你的必不羞愧，惟有那无故行奸诈的必要羞愧。","notes":[]},{"n":4,"t":"耶和华啊，求你将你的道指示我，将你的路指教我！","notes":[]},{"n":5,"t":"求你指教我，引导我进入你的真理，因为你是救我的神。我整日等候你。","notes":[]},{"n":6,"t":"耶和华啊，求你记念你的怜悯和慈爱，因为这是亘古以来所常有的。","notes":[]},{"n":7,"t":"求你不要记得我幼年的罪愆和我的过犯；耶和华啊，求你因你的良善，按你的慈爱记念我。","notes":[]},{"n":8,"t":"耶和华是良善正直的，因此，他必教导罪人走正路。","notes":[]},{"n":9,"t":"他要按公平引领谦卑人，将他的道指教他们。","notes":[]},{"n":10,"t":"凡遵守他的约和他法度的人，耶和华都以慈爱信实待他。","notes":[]},{"n":11,"t":"耶和华啊，求你因你名的缘故赦免我的罪，因我的罪重大。","notes":[]},{"n":12,"t":"谁敬畏耶和华，耶和华必教导他当选择的道路。","notes":[]},{"n":13,"t":"他要安然居住，他的后裔必承受土地。","notes":[]},{"n":14,"t":"耶和华与敬畏他的人亲密，他要将自己的约指示他们。","notes":[]},{"n":15,"t":"我的眼目时常仰望耶和华，因他必将我的脚从网里拉出来。","notes":[]},{"n":16,"t":"求你转向我，怜悯我，因我孤独困苦。","notes":[]},{"n":17,"t":"我心里愁苦甚多，求你救我脱离我的祸患。","notes":[]},{"n":18,"t":"求你看顾我的困苦、我的艰难，赦免我一切的罪。","notes":[]},{"n":19,"t":"求你察看我的仇敌，因为他们人数众多，并且痛恨我。","notes":[]},{"n":20,"t":"求你保护我的性命，搭救我，使我不致羞愧，因为我投靠你。","notes":[]},{"n":21,"t":"愿纯全、正直保护我，因为我等候你。","notes":[]},{"n":22,"t":"神啊，求你救赎以色列脱离他一切的愁苦。","notes":[]}]},"26":{"heading":"义人的祈祷","verses":[{"n":1,"t":"耶和华啊，求你为我伸冤，因我向来行事纯正；我倚靠耶和华，必不动摇。","notes":[]},{"n":2,"t":"耶和华啊，求你察看我，考验我，熬炼我的肺腑心肠。","notes":[]},{"n":3,"t":"因为你的慈爱常在我眼前，我也按你的真理而行。","notes":[]},{"n":4,"t":"我未曾与虚妄的人同坐，也不与伪善的人来往。","notes":[]},{"n":5,"t":"我痛恨恶人的集会，必不与恶人同坐。","notes":[]},{"n":6,"t":"耶和华啊，我要洗手表明无辜，才环绕你的祭坛；","notes":[]},{"n":7,"t":"我好发出称谢的声音，述说你一切奇妙的作为。","notes":[]},{"n":8,"t":"耶和华啊，我喜爱你所住的殿和你显荣耀的居所。","notes":[]},{"n":9,"t":"不要把我的性命和罪人一同除掉，不要把我的生命和好流人血的一同除掉。","notes":[]},{"n":10,"t":"他们的手中有奸恶，他们的右手满有贿赂。","notes":[]},{"n":11,"t":"至于我，却要行事纯正；求你救赎我，怜悯我！","notes":[]},{"n":12,"t":"我的脚站在平坦的地方，在聚会中我要称颂耶和华！","notes":[]}]},"27":{"heading":"赞美的祷告","verses":[{"n":1,"t":"耶和华是我的亮光，是我的拯救，我还怕谁呢？耶和华是我生命的保障，我还惧谁呢？","notes":[]},{"n":2,"t":"那作恶的就是我的仇敌，前来吃我肉的时候就绊跌仆倒。","notes":[]},{"n":3,"t":"虽有军队安营攻击我，我的心也不害怕；虽然兴起战争攻击我，我仍旧安稳。","notes":[]},{"n":4,"t":"有一件事，我曾求耶和华，我仍要寻求，就是一生一世住在耶和华的殿中，瞻仰他的荣美，在他的殿宇里求问。","notes":[]},{"n":5,"t":"因为我遭遇患难，他必将我隐藏在他的帐棚里，把我藏在他帐幕的隐密处，将我高举在磐石上。","notes":[]},{"n":6,"t":"现在我得以昂首，高过四面的仇敌。我要在他的帐幕里欢然献祭，我要唱诗歌颂耶和华。","notes":[]},{"n":7,"t":"耶和华啊，我呼求的时候，求你垂听我的声音；求你怜悯我，应允我。","notes":[]},{"n":8,"t":"你说：“你们当寻求我的面。”那时我的心向你说：“耶和华啊，你的面我正要寻求。”","notes":[]},{"n":9,"t":"求你不要转脸不顾我，不要发怒赶逐你的仆人，你向来是帮助我的。救我的神啊，不要离开我，也不要撇弃我。","notes":[]},{"n":10,"t":"即使我的父母撇弃我，耶和华终必收留我。","notes":[]},{"n":11,"t":"耶和华啊，求你将你的道指教我，因我仇敌的缘故引导我走平坦的路。","notes":[]},{"n":12,"t":"求你不要把我交给敌人，遂其所愿；因为妄作见证的和口吐凶言的都起来攻击我。","notes":[]},{"n":13,"t":"我深信在活人之地必得见耶和华的恩惠。","notes":[]},{"n":14,"t":"要等候耶和华，当壮胆，坚固你的心，要等候耶和华！","notes":[]}]},"28":{"heading":"求主帮助","verses":[{"n":1,"t":"耶和华啊，我要求告你！我的磐石啊，求你不要向我缄默！倘若你向我闭口，我就如下入地府的人一样。","notes":[]},{"n":2,"t":"我呼求你，向你至圣所举手的时候，求你垂听我恳求的声音！","notes":[]},{"n":3,"t":"不要把我和坏人并作恶的一同除掉；他们跟邻舍说平安，心里却是奸恶。","notes":[]},{"n":4,"t":"求你按着他们所做的，按他们的恶行对待他们；求你照着他们手所做的对待他们，将他们应得的报应加给他们。","notes":[]},{"n":5,"t":"他们既然不尊重耶和华的作为，也不尊重他手所做的，耶和华就必毁坏他们，不建立他们。","notes":[]},{"n":6,"t":"耶和华是应当称颂的，因为他听了我恳求的声音。","notes":[]},{"n":7,"t":"耶和华是我的力量，是我的盾牌，我心里倚靠他就得帮助。我心中欢乐，我要用诗歌称谢他。","notes":[]},{"n":8,"t":"耶和华是他百姓的力量，又是他受膏者得救的保障。","notes":[]},{"n":9,"t":"求你拯救你的百姓，赐福给你的产业；求你牧养他们，扶持他们，直到永远。","notes":[]}]},"29":{"heading":"耶和华威严的声音","verses":[{"n":1,"t":"神的子民哪，你们要将荣耀、能力归给耶和华，都归给耶和华！","notes":["“神的子民”或译“强有力的”或“诸神”。"]},{"n":2,"t":"要将耶和华的名的荣耀归给他，要敬拜神圣荣耀的耶和华。","notes":["“要敬拜...耶和华”或译“以圣洁的妆饰敬拜耶和华”。"]},{"n":3,"t":"耶和华的声音在众水上，荣耀的神打雷；耶和华打雷在大水之上。","notes":[]},{"n":4,"t":"耶和华的声音大有能力，耶和华的声音满有威严。","notes":[]},{"n":5,"t":"耶和华的声音震碎香柏树，耶和华震碎黎巴嫩的香柏树。","notes":[]},{"n":6,"t":"他使黎巴嫩跳跃如牛犊，使西连跳跃如野牛犊。","notes":[]},{"n":7,"t":"耶和华的声音使火焰分岔。","notes":[]},{"n":8,"t":"耶和华的声音震动旷野，耶和华震动加低斯的旷野。","notes":[]},{"n":9,"t":"耶和华的声音惊动母鹿落胎，树林也脱落净光。凡在他殿中的，都述说他的荣耀。","notes":[]},{"n":10,"t":"耶和华坐在洪水之上为王；耶和华坐着为王，直到永远。","notes":[]},{"n":11,"t":"耶和华必赐力量给他的百姓，耶和华必赐平安的福给他的百姓。","notes":[]}]},"30":{"heading":"感恩的祷告","verses":[{"n":1,"t":"耶和华啊，我要尊崇你，因为你救了我，不让仇敌向我夸耀。","notes":[]},{"n":2,"t":"耶和华－我的神啊，我呼求你，你医治了我。","notes":[]},{"n":3,"t":"耶和华啊，你救我的性命脱离阴间，使我存活，不至于下入地府。","notes":[]},{"n":4,"t":"耶和华的圣民哪，你们要歌颂他，要颂扬他神圣的名字。","notes":["“名字”：原文是“纪念”。"]},{"n":5,"t":"因为，他的怒气不过是转眼之间；他的恩典乃是一生之久。一宿虽然有哭泣，早晨便必欢呼。","notes":[]},{"n":6,"t":"至于我，我凡事顺利，就说：“我永不动摇。”","notes":[]},{"n":7,"t":"耶和华啊，你曾施恩，使我稳固如山；你转脸不顾，我就惊惶。","notes":[]},{"n":8,"t":"耶和华啊，我曾求告你；我向耶和华恳求：","notes":[]},{"n":9,"t":"“我被害流血，下到地府，有何益处呢？尘土岂能称谢你、传扬你的信实吗？","notes":[]},{"n":10,"t":"耶和华啊，求你应允我，怜悯我！耶和华啊，求你帮助我！”","notes":[]},{"n":11,"t":"你将我的哀哭变为跳舞，脱去我的麻衣，为我披上喜乐，","notes":[]},{"n":12,"t":"使我的灵歌颂你，不致缄默。耶和华－我的神啊，我要称谢你，直到永远！","notes":["“灵”：原文是“荣耀”。"]}]},"31":{"heading":"信靠神的祈祷","verses":[{"n":1,"t":"耶和华啊，我投靠你，求你使我永不羞愧，凭你的公义搭救我！","notes":[]},{"n":2,"t":"求你侧耳听我，快快救我！求你作我坚固的磐石，拯救我的保障！","notes":[]},{"n":3,"t":"你真是我的岩石、我的山寨，求你为你名的缘故引导我，指教我。","notes":[]},{"n":4,"t":"求你救我脱离人为我暗设的网罗，因为你是我的保障。","notes":[]},{"n":5,"t":"我将我的灵交在你手里；耶和华─信实的神啊，你救赎了我。","notes":[]},{"n":6,"t":"我恨恶那信奉虚无神明的人；我却倚靠耶和华。","notes":["“我”：有古卷、七十士译本和其他古译本是“你”。","“虚无神明”：原文是“虚无”。"]},{"n":7,"t":"我要因你的慈爱欢喜快乐，因为你见过我的困苦，知道我心中的艰难。","notes":[]},{"n":8,"t":"你未曾把我交在仇敌手里，你使我的脚站在宽阔的地方。","notes":[]},{"n":9,"t":"耶和华啊，求你怜悯我，因为我在急难之中；我的眼睛因忧愁而昏花，我的身心也已耗尽。","notes":[]},{"n":10,"t":"我的生命为愁苦所消耗，我的年岁为叹息所荒废；我的力量因我的罪孽衰败，我的骨头也枯干。","notes":["“罪孽”：原文另译“苦难”。"]},{"n":11,"t":"我因所有的敌人成了羞辱，在我邻舍跟前更加羞辱；那认识我的都惧怕我，在街上看见我的都躲避我。","notes":[]},{"n":12,"t":"我被遗忘，如同死人，无人记念；我好像破碎的器皿。","notes":[]},{"n":13,"t":"我听见许多人的毁谤，四围尽是惊吓；他们一同商议攻击我，图谋害我的性命。","notes":[]},{"n":14,"t":"耶和华啊，我仍要倚靠你；我说：“你是我的神。”","notes":[]},{"n":15,"t":"我终生的事在你手中，求你救我脱离仇敌的手和那些迫害我的人。","notes":[]},{"n":16,"t":"求你使你的脸向仆人发光，凭你的慈爱拯救我。","notes":[]},{"n":17,"t":"耶和华啊，求你叫我不致羞愧，因为我曾呼求你；求你使恶人羞愧，使他们在阴间缄默无声。","notes":[]},{"n":18,"t":"那撒谎的人逞骄傲轻慢，出狂妄的话攻击义人，愿他的嘴哑而无言。","notes":[]},{"n":19,"t":"在世人眼前，你为敬畏你的人所积存的，为投靠你的人所施行的，是何等大的恩惠啊！","notes":[]},{"n":20,"t":"你必将他们藏在你面前的隐密处，免得遭人暗算；你要隐藏他们在棚子里，免受口舌的争闹。","notes":[]},{"n":21,"t":"耶和华是应当称颂的，因为我在围城里，他向我施展奇妙的慈爱。","notes":[]},{"n":22,"t":"至于我，我曾惊惶地说：“我从你眼前被隔绝。”然而，我呼求你的时候，你仍听我恳求的声音。","notes":[]},{"n":23,"t":"耶和华的圣民哪，你们都要爱他！耶和华保护诚实可靠的人，却加倍报应行事骄傲的人。","notes":[]},{"n":24,"t":"凡仰望耶和华的人，你们都要壮胆，坚固你们的心！","notes":[]}]},"32":{"heading":"认罪与蒙赦","verses":[{"n":1,"t":"过犯得赦免，罪恶蒙遮盖的人有福了！","notes":[]},{"n":2,"t":"耶和华不算为有罪，内心没有诡诈的人有福了！","notes":[]},{"n":3,"t":"我闭口不认罪的时候，因终日呻吟而骨头枯干。","notes":[]},{"n":4,"t":"黑夜白日，你的手压在我身上沉重；我的精力耗尽，如同夏天的干旱。（细拉）","notes":["“我的精力耗尽”：有古卷是“田中的残梗枯干”。"]},{"n":5,"t":"我向你陈明我的罪，不隐瞒我的恶。我说：“我要向耶和华承认我的过犯”；你就赦免我的罪恶。（细拉）","notes":[]},{"n":6,"t":"为此，凡虔诚人都当趁你可寻找的时候向你祷告；大水泛滥的时候，必不临到他。","notes":["“趁你可寻找”：原文另译“在患难”。"]},{"n":7,"t":"你是我藏身之处，你必保佑我脱离苦难，以得救的欢呼四面环绕我。（细拉）","notes":["“得救的欢呼”：原文另译“得救”。"]},{"n":8,"t":"我要教导你，指示你当行的路，我要定睛在你身上劝戒你。","notes":[]},{"n":9,"t":"你不可像那无知的骡马，须用嚼环缰绳勒住，不然，它就不会靠近你。","notes":[]},{"n":10,"t":"恶人必多受苦楚；惟独倚靠耶和华的，必有慈爱四面环绕他。","notes":[]},{"n":11,"t":"义人哪，你们应当靠耶和华欢喜快乐，心里正直的人哪，你们都当欢呼。","notes":[]}]},"33":{"heading":"颂赞之歌","verses":[{"n":1,"t":"义人哪，你们当因耶和华欢呼，正直人理当赞美耶和华。","notes":[]},{"n":2,"t":"你们要弹琴称谢耶和华，用十弦瑟歌颂他。","notes":[]},{"n":3,"t":"应当向他唱新歌，弹得巧妙，声音洪亮。","notes":[]},{"n":4,"t":"因为耶和华的言语正直，他的作为尽都信实。","notes":[]},{"n":5,"t":"他喜爱公义和公平，遍地满了耶和华的慈爱。","notes":[]},{"n":6,"t":"诸天藉耶和华的话而造，万象藉他口中的气而成。","notes":[]},{"n":7,"t":"他聚集海水如垒，收藏深洋在仓库。","notes":[]},{"n":8,"t":"愿全地都敬畏耶和华！愿世上的居民都惧怕他！","notes":[]},{"n":9,"t":"因为他说有，就有，命立，就立。","notes":[]},{"n":10,"t":"耶和华使列国的筹算归于无有，使万民的计谋全无功效。","notes":[]},{"n":11,"t":"耶和华的筹算永远立定，他心中的计划万代长存。","notes":[]},{"n":12,"t":"以耶和华为神的，那国有福了！耶和华拣选为自己产业的，那民有福了！","notes":[]},{"n":13,"t":"耶和华从天上观看，看见所有的人，","notes":[]},{"n":14,"t":"从他的居所察看地上每一个居民，","notes":[]},{"n":15,"t":"他塑造他们的心，洞察他们一切的作为。","notes":[]},{"n":16,"t":"君王不能因兵多得胜，勇士不能因力大得救。","notes":[]},{"n":17,"t":"靠马得救是枉然的，马也不能因力大救人。","notes":[]},{"n":18,"t":"看哪，耶和华的眼目看顾敬畏他的人和仰望他慈爱的人，","notes":[]},{"n":19,"t":"要救他们的性命脱离死亡，使他们在饥荒中存活。","notes":[]},{"n":20,"t":"我们的心向来等候耶和华；他是我们的帮助，是我们的盾牌。","notes":[]},{"n":21,"t":"我们的心必靠他欢喜，因为我们向来倚靠他的圣名。","notes":[]},{"n":22,"t":"耶和华啊，求你照着我们所仰望你的，向我们施行慈爱！","notes":[]}]},"34":{"heading":"颂赞神的美善","verses":[{"n":1,"t":"我要时时称颂耶和华，赞美他的话常在我口中。","notes":[]},{"n":2,"t":"我的心必因耶和华夸耀，谦卑的人听见就喜乐。","notes":[]},{"n":3,"t":"你们要和我一同尊耶和华为大，让我们一同高举他的名。","notes":[]},{"n":4,"t":"我曾寻求耶和华，他就应允我，救我脱离一切的恐惧。","notes":[]},{"n":5,"t":"仰望他的人，就有光荣；他们的脸必不蒙羞。","notes":["“他们”：七十士译本和其他古译本是“你们”。"]},{"n":6,"t":"这困苦人呼求，耶和华就垂听，救他脱离一切的患难。","notes":[]},{"n":7,"t":"耶和华的使者在敬畏他的人四围安营，要搭救他们。","notes":[]},{"n":8,"t":"你们要尝尝主恩的滋味，便知道他是美善；投靠他的人有福了！","notes":[]},{"n":9,"t":"耶和华的圣民哪，你们当敬畏他，因敬畏他的一无所缺。","notes":[]},{"n":10,"t":"少壮狮子尚且缺食忍饿，但寻求耶和华的什么好处都不缺。","notes":[]},{"n":11,"t":"孩子们哪，来听我！我要将敬畏耶和华的道教导你们。","notes":[]},{"n":12,"t":"有谁喜爱生命，爱慕长寿，得享美福？","notes":[]},{"n":13,"t":"你要禁止舌头不出恶言，嘴唇不说诡诈的话。","notes":[]},{"n":14,"t":"要弃恶行善，寻求和睦，一心追求。","notes":[]},{"n":15,"t":"耶和华的眼目看顾义人，他的耳朵听他们的呼求。","notes":[]},{"n":16,"t":"耶和华向行恶的人变脸，要从地上除灭他们的名字。","notes":["“名字”：原文是“纪念”。"]},{"n":17,"t":"义人呼求，耶和华听见了，就拯救他们脱离一切患难。","notes":[]},{"n":18,"t":"耶和华靠近伤心的人，拯救心灵痛悔的人。","notes":[]},{"n":19,"t":"义人多有苦难，但耶和华救他脱离这一切，","notes":[]},{"n":20,"t":"又保护他全身的骨头，连一根也不折断。","notes":[]},{"n":21,"t":"恶必害死恶人，恨恶义人的，必被定罪。","notes":[]},{"n":22,"t":"耶和华救赎他仆人的性命，凡投靠他的，必不致定罪。","notes":[]}]},"35":{"heading":"求助的祷告","verses":[{"n":1,"t":"耶和华啊，与我相争的，求你与他们相争！与我争战的，求你与他们争战！","notes":[]},{"n":2,"t":"求你拿着大小盾牌，起来帮助我；","notes":[]},{"n":3,"t":"举起枪来，抵挡那追赶我的。求你对我说：“我是拯救你的。”","notes":[]},{"n":4,"t":"愿那寻索我命的，蒙羞受辱！愿那谋害我的，退后羞愧！","notes":[]},{"n":5,"t":"愿他们像风前的糠秕，有耶和华的使者赶逐他们。","notes":[]},{"n":6,"t":"愿他们的道路又暗又滑，有耶和华的使者追赶他们。","notes":[]},{"n":7,"t":"因他们无故为我暗设网罗，无故挖坑，要害我的命。","notes":[]},{"n":8,"t":"愿灾祸忽然临到他身上！愿他暗设的网罗缠住自己！愿他落在其中遭灾祸！","notes":[]},{"n":9,"t":"我的心必靠耶和华快乐，靠他的救恩欢喜。","notes":[]},{"n":10,"t":"我全身的骨头要说：“耶和华啊，谁能像你救护困苦人脱离那比他强壮的，救护困苦贫穷人脱离那抢夺他的？”","notes":[]},{"n":11,"t":"凶恶的见证人起来，盘问我所不知道的事。","notes":[]},{"n":12,"t":"他们向我以恶报善，使我丧失儿子。","notes":[]},{"n":13,"t":"至于我，他们有病的时候，我穿麻衣，禁食，刻苦己心；我所求的都归到自己身上。","notes":[]},{"n":14,"t":"我如此行，好像他是我的朋友，我的兄弟；我屈身悲哀，如同哀悼自己的母亲。","notes":[]},{"n":15,"t":"我在患难中，他们却欢喜，大家聚集，我所不认识的卑贱人聚集攻击我，他们不住地撕裂我。","notes":["“卑贱人”或译“被击打的人”；原文另译“外邦人”。"]},{"n":16,"t":"他们试探我，不断嘲笑我，向我咬牙切齿。","notes":["“他们...嘲笑我”是根据七十士译本；原文另译“他们如同席上好嬉笑的狂妄人”。"]},{"n":17,"t":"主啊，你看着不理要到几时呢？求你救我的性命脱离他们的残害，救我仅有的脱离少壮狮子！","notes":["“仅有的”就是“生命”。"]},{"n":18,"t":"我在大会中要称谢你，在许多百姓中要赞美你。","notes":[]},{"n":19,"t":"求你不容那无理与我为仇的向我夸耀！不容那无故恨我的向我瞪眼！","notes":[]},{"n":20,"t":"因为他们不说平安，倒想出诡诈的言语扰害地上安静的人。","notes":[]},{"n":21,"t":"他们大大张口攻击我，说：“啊哈，啊哈，我们已经亲眼看见了！”","notes":[]},{"n":22,"t":"耶和华啊，你已经看见了，求你不要沉默！主啊，求你不要远离我！","notes":[]},{"n":23,"t":"我的神─我的主啊，求你醒来，求你奋起，还我公正，伸明我冤！","notes":[]},{"n":24,"t":"耶和华－我的神啊，求你按你的公义判断我，不容他们向我夸耀！","notes":[]},{"n":25,"t":"不容他们心里说：“啊哈，遂我们的心愿了！”不容他们说：“我们已经把他吞了！”","notes":[]},{"n":26,"t":"愿那喜欢我遭难的一同抱愧蒙羞！愿那向我妄自尊大的披戴惭愧，蒙受羞辱！","notes":[]},{"n":27,"t":"愿那喜悦我被判为义的欢呼快乐；愿他们常说：“当尊耶和华为大！耶和华喜悦他的仆人平安。”","notes":["“被判为义”或译“冤屈得伸”。"]},{"n":28,"t":"我的舌头要论说你的公义，要常常赞美你。","notes":[]}]},"36":{"heading":"人的邪恶","verses":[{"n":1,"t":"过犯在恶人的心底向他说话，他的眼中不怕神。","notes":["“过犯...说话”是根据一些古卷和七十士译本；原文是“过犯在我的心底向恶人说话”。"]},{"n":2,"t":"他自夸自媚，以致罪孽无法察觉，不被恨恶。","notes":[]},{"n":3,"t":"他口中的言语尽是罪孽诡诈，他不再有智慧，也不再行善。","notes":[]},{"n":4,"t":"他在床上图谋罪孽，定意行不善的道，不憎恶恶事。","notes":[]},{"n":5,"t":"耶和华啊，你的慈爱上及诸天，你的信实达到穹苍，","notes":[],"heads":["神的良善"]},{"n":6,"t":"你的公义好像高山，你的判断如同深渊；耶和华啊，人民、牲畜，你都救护。","notes":[]},{"n":7,"t":"神啊，你的慈爱何其宝贵！世人投靠在你翅膀的荫下。","notes":[]},{"n":8,"t":"他们必因你殿里的丰盛得以饱足，你也必叫他们喝你那喜乐的泉水。","notes":[]},{"n":9,"t":"因为在你那里有生命的泉源，在你的光中，我们必得见光。","notes":[]},{"n":10,"t":"愿你常施慈爱给认识你的人，常以公义待心里正直的人。","notes":[]},{"n":11,"t":"不容骄傲人的脚践踏我，不容凶恶人的手赶逐我。","notes":[]},{"n":12,"t":"在那里，作恶的人已经仆倒；他们被推倒，不能再起来。","notes":[]}]},"37":{"heading":"义人和恶人的结局","verses":[{"n":1,"t":"不要为作恶的心怀不平，也不要嫉妒那行不义的人。","notes":[]},{"n":2,"t":"因为他们如草快被割下，又如绿色的嫩草快要枯干。","notes":[]},{"n":3,"t":"你当倚靠耶和华而行善，安居地上，以他的信实为粮；","notes":[]},{"n":4,"t":"又当以耶和华为乐，他就将你心里所求的赐给你。","notes":[]},{"n":5,"t":"当将你的道路交托耶和华，并倚靠他，他就必成全。","notes":[]},{"n":6,"t":"他要使你的公义如光发出，使你的公平明如正午。","notes":[]},{"n":7,"t":"你当安心倚靠耶和华，耐性等候他，不要因那道路通达的和那恶谋成就的心怀不平。","notes":[]},{"n":8,"t":"当止住怒气，离弃愤怒；不要心怀不平，以致作恶。","notes":[]},{"n":9,"t":"因为作恶的必被剪除；惟有等候耶和华的必承受土地。","notes":[]},{"n":10,"t":"还有片时，恶人要归于无有；你就是细察他的住处，也不存在。","notes":[]},{"n":11,"t":"但谦卑的人必承受土地，以丰盛的平安为乐。","notes":[]},{"n":12,"t":"恶人设谋要害义人，向他咬牙。","notes":[]},{"n":13,"t":"但主必笑他，因见他受罚的日子将要来到。","notes":[]},{"n":14,"t":"恶人刀已出鞘，弓已上弦，要砍倒困苦贫穷的人，要杀害行为正直的人。","notes":[]},{"n":15,"t":"他们的刀必刺入自己的心，他们的弓必折断。","notes":[]},{"n":16,"t":"一个义人所有的虽少，强过许多恶人的富余。","notes":[]},{"n":17,"t":"因为恶人的膀臂必折断；但耶和华扶持义人。","notes":[]},{"n":18,"t":"耶和华知道完全人的日子，他们的产业要存到永远。","notes":[]},{"n":19,"t":"他们在患难的时候必不致羞愧，在饥荒的日子必得饱足。","notes":[]},{"n":20,"t":"恶人却要灭亡。耶和华的仇敌要像草地的华美；他们要毁灭，在烟中消失。","notes":["“草地的华美”或译“羔羊的油脂”。","“在烟中消失”：七十士译本是“要如烟消灭”。"]},{"n":21,"t":"恶人借贷却不偿还；义人恩待人，并且施舍。","notes":[]},{"n":22,"t":"蒙耶和华赐福的必承受土地；他所诅咒的必被剪除。","notes":[]},{"n":23,"t":"义人的脚步为耶和华所稳定；他的道路，耶和华也喜爱。","notes":[]},{"n":24,"t":"他虽失脚也不致全身仆倒，因为耶和华搀扶他的手。","notes":[]},{"n":25,"t":"我从前年幼，现在年老，却未见过义人被弃，也未见过他的后裔求乞。","notes":[]},{"n":26,"t":"他常常恩待人，借贷给人，他的后裔也必蒙福。","notes":[]},{"n":27,"t":"你当离恶行善，就可永远安居。","notes":[]},{"n":28,"t":"因为耶和华喜爱公平，不撇弃他的圣民，他们永蒙保佑；但恶人的后裔必被剪除。","notes":[]},{"n":29,"t":"义人必承受土地，永居其上。","notes":[]},{"n":30,"t":"义人的口发出智慧，他的舌头讲说公平。","notes":[]},{"n":31,"t":"神的律法在他心里，他的步伐总不摇动。","notes":[]},{"n":32,"t":"恶人窥探义人，想要杀他。","notes":[]},{"n":33,"t":"耶和华必不把他交在恶人手中，当审判的时候，也不定他的罪。","notes":[]},{"n":34,"t":"你当等候耶和华，遵守他的道，他就抬举你，使你承受土地；你必看到恶人被剪除。","notes":[]},{"n":35,"t":"我见过恶人大有势力，高耸如本地青翠的树木。","notes":[]},{"n":36,"t":"有人从那里经过，看哪，他已不存在，我寻找他，却寻不着了。","notes":["“有人”：七十士译本和其他古译本是“我”。"]},{"n":37,"t":"你要细察那完全人，观看那正直人，因为和平的人有好结局。","notes":[]},{"n":38,"t":"至于罪人，必一同灭绝，恶人的结局必被剪除。","notes":[]},{"n":39,"t":"义人得救是出于耶和华，在患难时耶和华作他们的避难所。","notes":[]},{"n":40,"t":"耶和华帮助他们，解救他们；他解救他们脱离恶人，把他们救出来，因为他们投靠他。","notes":[]}]},"38":{"heading":"受苦者的祈祷","verses":[{"n":1,"t":"耶和华啊，求你不要在怒中责备我，不要在烈怒中惩罚我！","notes":[]},{"n":2,"t":"因为你的箭射入我身，你的手压住我。","notes":[]},{"n":3,"t":"因你的恼怒，我的肉无一完全；因我的罪过，我的骨头也不安宁。","notes":[]},{"n":4,"t":"我的罪孽高过我的头，如同重担叫我担当不起。","notes":[]},{"n":5,"t":"因我的愚昧，我的伤发臭流脓。","notes":[]},{"n":6,"t":"我疼痛，大大蜷曲，整日哀痛。","notes":[]},{"n":7,"t":"我满腰灼热，我的肉无一完全。","notes":[]},{"n":8,"t":"我被压碎，身心虚弱；因心里痛苦，我就呻吟。","notes":[]},{"n":9,"t":"主啊，我的心愿都在你面前，我的叹息不向你隐瞒。","notes":[]},{"n":10,"t":"我心颤栗，体力衰微，眼中无光。","notes":[]},{"n":11,"t":"我遭遇灾病，良朋密友都袖手旁观，我的亲戚本家也远远站立。","notes":[]},{"n":12,"t":"那寻索我命的设下罗网，那想要害我的口出恶言，整日思想诡计。","notes":[]},{"n":13,"t":"但我如聋子听不见，像哑巴不能开口。","notes":[]},{"n":14,"t":"我如听不见的人，无法用口答辩。","notes":[]},{"n":15,"t":"耶和华啊，我仰望你！主－我的神啊，你必应允我！","notes":[]},{"n":16,"t":"我曾说：“恐怕他们向我夸耀，我失脚的时候，他们向我夸口。”","notes":[]},{"n":17,"t":"我就要跌倒，我的痛苦常在我面前。","notes":[]},{"n":18,"t":"我要承认我的罪孽，要因我的罪忧愁。","notes":[]},{"n":19,"t":"但我的仇敌又活泼又强壮，无理恨我的增多了。","notes":[]},{"n":20,"t":"以恶报善的与我作对，但我追求良善。","notes":[]},{"n":21,"t":"耶和华啊，求你不要撇弃我！我的神啊，求你不要远离我！","notes":[]},{"n":22,"t":"拯救我的主啊，求你快快帮助我！","notes":[]}]},"39":{"heading":"受苦者的认罪","verses":[{"n":1,"t":"我曾说：“我要谨慎我的言行，免得我的舌头犯罪；恶人在我面前的时候，我要用嚼环勒住我的口。”","notes":[]},{"n":2,"t":"我默然无声，连好话也不出口，我的愁苦就更加深。","notes":[]},{"n":3,"t":"我的心在我里面发热；我默想的时候，火就烧起，我用舌头说话：","notes":[]},{"n":4,"t":"“耶和华啊，求你让我晓得我的结局，我的寿数几何，使我知道我的生命何等短暂！","notes":[]},{"n":5,"t":"看哪，你使我的年日窄如手掌，我一生的年数，在你面前如同无有；各人最稳妥的时候，真是全然虚幻。（细拉）","notes":[]},{"n":6,"t":"世人行动实系幻影，他们忙乱，真是枉然，积蓄财宝，不知将来有谁收取。","notes":[]},{"n":7,"t":"“主啊，如今我等什么呢？我的指望在乎你！","notes":[]},{"n":8,"t":"求你救我脱离一切的过犯，不要使我受愚顽人的羞辱。","notes":[]},{"n":9,"t":"我保持沉默，闭口不言，因为这一切都是你所做的。","notes":[]},{"n":10,"t":"求你从我身上免去你的责罚；因你手的责打，我就消灭。","notes":[]},{"n":11,"t":"因人的罪恶你惩罚管教他的时候，如蛀虫一般，吃掉他所喜爱的。世人真是虚幻！（细拉）","notes":[]},{"n":12,"t":"“耶和华啊，求你听我的祷告，侧耳听我的呼求！我流泪，求你不要静默无声！因为在你面前我是客旅，是寄居的，像我列祖一般。","notes":[]},{"n":13,"t":"求你宽容我，使我在去而不返之先可以喜乐。”","notes":[]}]},"40":{"heading":"颂赞之歌","verses":[{"n":1,"t":"我曾耐性等候耶和华，他垂听我的呼求。","notes":[]},{"n":2,"t":"他从泥坑里，从淤泥中，把我拉上来，使我的脚立在磐石上，使我脚步稳健。","notes":[]},{"n":3,"t":"他使我口唱新歌，就是赞美我们神的话。许多人必看见而惧怕，并要倚靠耶和华。","notes":[]},{"n":4,"t":"那倚靠耶和华、不理会狂傲和偏向虚假的，这人有福了！","notes":[]},{"n":5,"t":"耶和华－我的神啊，你所行的奇事和你为我们设想的计划，多到无法尽述；若要述说陈明，不可胜数。","notes":[]},{"n":6,"t":"祭物和礼物，你不喜爱，你已经开通我的耳朵；燔祭和赎罪祭非你所要。","notes":[]},{"n":7,"t":"那时我说：“看哪，我来了！我的事在经卷上已经记载了。","notes":[]},{"n":8,"t":"我的神啊，我乐意照你的旨意行，你的律法在我心里。”","notes":[]},{"n":9,"t":"我在大会中传讲公义的佳音，看哪，必不制止我的嘴唇；耶和华啊，这一切你都知道。","notes":[]},{"n":10,"t":"我未曾把你的公义藏在心里，我已陈明你的信实和你的救恩；在大会中我未曾隐瞒你的慈爱和信实。","notes":[]},{"n":11,"t":"耶和华啊，求你不要向我止住你的怜悯！愿你的慈爱和信实常常保佑我！","notes":[]},{"n":12,"t":"因有无数的祸患围困我，我的罪孽追上了我，使我不能看见，这罪孽比我的头发还多，我的胆量丧失了。","notes":[],"heads":["求助的祷告"]},{"n":13,"t":"耶和华啊，求你开恩搭救我！耶和华啊，求你速速帮助我！","notes":[]},{"n":14,"t":"愿那些寻找我、要灭我命的，一同抱愧蒙羞！愿那些喜悦我遭害的，退后受辱！","notes":[]},{"n":15,"t":"愿那些对我说“啊哈、啊哈”的，因羞愧而败亡！","notes":[]},{"n":16,"t":"愿一切寻求你的，因你欢喜快乐！愿那些喜爱你救恩的，常说：“当尊耶和华为大！”","notes":[]},{"n":17,"t":"我本是困苦贫穷的，主却顾念我。你是帮助我的，搭救我的；我的神啊，求你不要耽延！","notes":[]}]},"41":{"heading":"病中祈祷","verses":[{"n":1,"t":"眷顾贫寒人的有福了！在患难的日子，耶和华必搭救他。","notes":["“有福了”：原文另译“他要赐福给他”。"]},{"n":2,"t":"耶和华必保全他，使他存活，他要在地上享福。求你不要把他交给仇敌，遂其所愿。","notes":[]},{"n":3,"t":"他病重在榻，耶和华必扶持他；他在病中，你必使他离开病床。","notes":[]},{"n":4,"t":"我曾说：“耶和华啊，求你怜悯我，医治我，因为我得罪了你。”","notes":[]},{"n":5,"t":"我的仇敌用恶言议论我：“他几时才会死，他的名几时才会消灭呢？”","notes":[]},{"n":6,"t":"当他来看我的时候，说的是假话；他心存奸恶，走到外边才说出来。","notes":[]},{"n":7,"t":"所有恨我的，都一同交头接耳议论我，他们设计要害我。","notes":[]},{"n":8,"t":"他们说：“他有怪病缠身，他已躺下，必不能再起来。”","notes":[]},{"n":9,"t":"连我知己的朋友，我所信赖、吃我饭的人也用脚踢我。","notes":[]},{"n":10,"t":"耶和华啊，求你怜悯我，使我起来，好报复他们！","notes":[]},{"n":11,"t":"我因此就知道你喜爱我，我的仇敌不得向我夸胜。","notes":[]},{"n":12,"t":"你因我纯正就扶持我，使我永远站立在你面前。","notes":[]},{"n":13,"t":"耶和华－以色列的神是应当称颂的，从亘古直到永远。阿们！阿们！","notes":[]}]},"42":{"heading":"流亡异乡者的祷告（一）","verses":[{"n":1,"t":"神啊，我的心切慕你，如鹿切慕溪水。","notes":[]},{"n":2,"t":"我的心渴想神，就是永生神，我几时得朝见神呢？","notes":[]},{"n":3,"t":"我昼夜以眼泪当食物，人不住地对我说：“你的神在哪里呢？”","notes":[]},{"n":4,"t":"我从前与众人同往，领他们到神的殿里，大家用欢呼称颂的声音守节；我追想这些事，我的心极其悲伤。","notes":[]},{"n":5,"t":"我的心哪，你为何忧闷？为何在我里面烦躁？应当仰望神，我还要称谢他，我当面的拯救，","notes":[]},{"n":6,"t":"我的神。我的心在我里面忧闷，所以我从约旦地，从黑门岭，从米萨山记念你。","notes":["“我当面...忧闷”是根据七十士译本；原文是“他的脸的拯救。我的神啊，我的心在我里面忧闷”。"]},{"n":7,"t":"你的瀑布发声，深渊就与深渊响应，你的波浪洪涛漫过我身。","notes":[]},{"n":8,"t":"白昼，耶和华必施慈爱；黑夜，我要歌颂祈祷赐我生命的神。","notes":[]},{"n":9,"t":"我要对神－我的磐石说：“你为何忘记我呢？我为何因仇敌的欺压时常哀痛呢？”","notes":[]},{"n":10,"t":"我的敌人辱骂我，好像敲碎我的骨头，他们不住地对我说：“你的神在哪里呢？”","notes":[]},{"n":11,"t":"我的心哪，你为何忧闷？为何在我里面烦躁？应当仰望神，我还要称谢他，我当面的拯救，我的神。","notes":[]}]},"43":{"heading":"流亡异乡者的祷告（二）","verses":[{"n":1,"t":"神啊，求你为我伸冤，向不虔诚的国为我辩护；求你救我脱离诡诈不义的人。","notes":[]},{"n":2,"t":"你是作我保障的神，为何丢弃我呢？我为何因仇敌的欺压时常哀痛呢？","notes":["“作我保障”：七十士译本是“赐我力量”。"]},{"n":3,"t":"求你发出你的亮光和信实，好引导我，带我到你的圣山，到你的居所！","notes":[]},{"n":4,"t":"我就走到神的祭坛，到赐我喜乐的神那里。神，我的神啊，我要弹琴称谢你！","notes":[]},{"n":5,"t":"我的心哪，你为何忧闷？为何在我里面烦躁？应当仰望神，我还要称谢他，我当面的拯救，我的神。","notes":[]}]},"44":{"heading":"求主保护","verses":[{"n":1,"t":"神啊，你在古时，我们列祖的日子所做的事，我们亲耳听见了，我们的列祖曾为我们述说。","notes":[]},{"n":2,"t":"你曾用手赶出外邦人，却栽培了我们的列祖；你苦待万民，却叫我们的列祖发达。","notes":[]},{"n":3,"t":"因为他们不是靠自己的刀剑承受土地，也不是靠自己的膀臂得胜，而是靠你的右手、你的膀臂，和你脸上的亮光，因为你喜爱他们。","notes":[]},{"n":4,"t":"神啊，你是我的君王，求你发命令使雅各得胜。","notes":[]},{"n":5,"t":"靠你，我们要推倒我们的敌人；靠你的名，我们要践踏那兴起攻击我们的人。","notes":[]},{"n":6,"t":"因为我必不倚靠我的弓，我的刀也不能使我得胜。","notes":[]},{"n":7,"t":"惟有你拯救我们脱离敌人，使恨我们的人羞愧。","notes":[]},{"n":8,"t":"我们要常常因神夸耀，要永远颂扬你的名。（细拉）","notes":[]},{"n":9,"t":"但如今你丢弃了我们，使我们受辱，不和我们的军队同去。","notes":[]},{"n":10,"t":"你使我们在敌人前转身撤退，使那恨我们的人任意抢夺。","notes":[]},{"n":11,"t":"你使我们如羊当作食物，把我们分散在列国中。","notes":[]},{"n":12,"t":"你卖了你的子民也不获利，所得的并未加添你的资财。","notes":[]},{"n":13,"t":"你使我们受邻国的羞辱，被四围的人嗤笑讥讽。","notes":[]},{"n":14,"t":"你使我们在列国中成了笑柄，在万民中使人摇头。","notes":[]},{"n":15,"t":"因辱骂者和毁谤者的声音，因仇敌和报仇者的缘故，我的凌辱常常在我面前，我脸上的羞愧将我遮蔽，","notes":[],"end":16},{"n":17,"t":"这些事都临到我们身上，我们却没有忘记你，也没有违背你的约；","notes":[]},{"n":18,"t":"我们的心并未退缩，我们的脚也没有偏离你的路。","notes":[]},{"n":19,"t":"你在野狗出没之处压伤我们，以死荫笼罩我们。","notes":[]},{"n":20,"t":"倘若我们忘记神的名，或向外邦神明举手，","notes":[]},{"n":21,"t":"神岂不鉴察这事吗？因为他晓得人心里的隐秘。","notes":[]},{"n":22,"t":"我们为你的缘故终日被杀，人看我们如将宰的羊。","notes":[]},{"n":23,"t":"主啊，求你睡醒，为何尽睡呢？求你醒来，不要永远丢弃我们！","notes":[]},{"n":24,"t":"你为何转脸，不顾我们所遭的苦难和所受的欺压呢？","notes":[]},{"n":25,"t":"我们俯伏在尘土上，我们的肚腹紧贴地面。","notes":[]},{"n":26,"t":"求你兴起帮助我们！因你的慈爱救赎我们！","notes":[]}]},"45":{"heading":"皇家婚礼诗歌","verses":[{"n":1,"t":"我心里涌出美辞，我为王朗诵我的诗章，我的舌头是敏捷文士的手笔。","notes":[]},{"n":2,"t":"你比世人更美，你嘴里满有恩惠；所以神赐福给你，直到永远。","notes":[]},{"n":3,"t":"勇士啊，愿你腰间佩刀，大展荣耀和威严，","notes":[]},{"n":4,"t":"为真理、谦卑、公义威严地驾车前进，无不得胜；愿你的右手显明可畏的事。","notes":[]},{"n":5,"t":"你的箭锋快，射中王的仇敌的心，万民仆倒在你之下。","notes":[]},{"n":6,"t":"神啊，你的宝座是永永远远的，你国度的权杖是正直的权杖。","notes":[]},{"n":7,"t":"你喜爱公义，恨恶罪恶，所以神，就是你的神，用喜乐油膏你，胜过膏你的同伴。","notes":[]},{"n":8,"t":"你的衣服散发没药、沉香、肉桂的香气，象牙宫中丝弦乐器的声音使你欢喜。","notes":[]},{"n":9,"t":"你的妃嫔之中有列王的女儿，王后佩戴俄斐金饰站立在你右边。","notes":[]},{"n":10,"t":"女子啊，要倾听，要思想，要侧耳而听！不要记念你本族和你父家，","notes":[]},{"n":11,"t":"王就羡慕你的美貌；因为他是你的主，你当向他下拜。","notes":[]},{"n":12,"t":"推罗必来送礼，百姓中富足的人也必向你求恩。","notes":["“推罗”：原文直译“推罗女子”。"]},{"n":13,"t":"君王的女儿在宫里极其荣华，她的衣服是金线绣的；","notes":[]},{"n":14,"t":"她穿锦绣的衣服，引到王面前，陪伴她的童女随从她，也被带到你面前。","notes":[]},{"n":15,"t":"她们要欢喜快乐，被引导进入王宫。","notes":[]},{"n":16,"t":"你的子孙要接续你列祖，你要立他们在各地作王。","notes":[]},{"n":17,"t":"我必使万代记念你的名，万民要永永远远称谢你。","notes":[]}]},"46":{"heading":"神与我们同在","verses":[{"n":1,"t":"神是我们的避难所，是我们的力量，是我们在患难中随时的帮助。","notes":[]},{"n":2,"t":"所以，地虽改变，山虽摇动到海心，","notes":[]},{"n":3,"t":"其中的水虽澎湃翻腾，山虽因海涨而战抖，我们也不害怕。（细拉）","notes":[]},{"n":4,"t":"有一道河，这河的分汊使神的城欢喜，这城就是至高者居住的圣所。","notes":[]},{"n":5,"t":"神在其中，城必不动摇；到天一亮，神必帮助这城。","notes":[]},{"n":6,"t":"万邦喧嚷，国度动摇；神出声，地就熔化。","notes":[]},{"n":7,"t":"万军之耶和华与我们同在，雅各的神是我们的避难所！（细拉）","notes":[]},{"n":8,"t":"你们来看耶和华的作为，看他使地怎样荒凉。","notes":[]},{"n":9,"t":"他止息战争，直到地极；他折弓、断枪，把战车焚烧在火中。","notes":[]},{"n":10,"t":"你们要休息，要知道我是神！我必在列国中受尊崇，在全地也受尊崇。","notes":[]},{"n":11,"t":"万军之耶和华与我们同在，雅各的神是我们的避难所！","notes":[]}]},"47":{"heading":"至高的主宰","verses":[{"n":1,"t":"万民哪，你们都要鼓掌！用欢呼的声音向神呼喊！","notes":[]},{"n":2,"t":"因为耶和华至高者是可畏的，他是治理全地的大君王。","notes":[]},{"n":3,"t":"他使万民服在我们以下，又使万族服在我们脚下。","notes":[]},{"n":4,"t":"他为我们选择产业，就是他所爱之雅各的荣耀。（细拉）","notes":[]},{"n":5,"t":"神上升，有喊声相送；耶和华上升，有角声相送。","notes":[]},{"n":6,"t":"你们要向神歌颂，歌颂！向我们的王歌颂，歌颂！","notes":[]},{"n":7,"t":"因为神是全地的王，你们要用圣诗歌颂！","notes":[]},{"n":8,"t":"神作王治理列国，神坐在他的圣宝座上。","notes":[]},{"n":9,"t":"万民的君王聚集，要作亚伯拉罕的神的子民，因为地上的盾牌是属神的，他为至高！","notes":[]}]},"48":{"heading":"锡安－神的城","verses":[{"n":1,"t":"耶和华本为大！在我们神的城中，在他的圣山上，当受大赞美。","notes":[]},{"n":2,"t":"锡安山－大君王的城，在北面居高华美，为全地所喜悦。","notes":[]},{"n":3,"t":"神在城的宫殿中，自显为避难所。","notes":[]},{"n":4,"t":"看哪，诸王会合，一同经过。","notes":[]},{"n":5,"t":"他们见了这城就惊奇丧胆，急忙逃跑。","notes":[]},{"n":6,"t":"战兢在那里抓住他们，他们好像临产的妇人一样阵痛。","notes":[]},{"n":7,"t":"神啊，你用东风击破他施的船只。","notes":[]},{"n":8,"t":"我们在万军之耶和华的城里，就是我们神的城里，所看见的正如我们所听见的。神必坚立这城，直到永远。（细拉）","notes":[]},{"n":9,"t":"神啊，我们在你的殿中想念你的慈爱。","notes":[]},{"n":10,"t":"神啊，你受的赞美正与你的名相称，直到地极！你的右手满了公义。","notes":[]},{"n":11,"t":"因你的判断，锡安山应当欢喜，犹大的城镇应当快乐。","notes":["“犹大的城镇”：原文直译“犹大众女子”。"]},{"n":12,"t":"你们当周游锡安，四围环绕，数点城楼，","notes":[]},{"n":13,"t":"细看它的城郭，察看它的宫殿，为要传扬给后代。","notes":[]},{"n":14,"t":"因为这神永永远远为我们的神，他必作我们引路的，直到死时。","notes":["“直到死时”：七十士译本是“直到永远”。"]}]},"49":{"heading":"恃财之愚","verses":[{"n":1,"t":"万民哪，你们都当听这话！世上所有的居民，无论贵贱贫富，都当侧耳而听！","notes":[],"end":2},{"n":3,"t":"我口要说智慧的言语，我心思想通达的道理。","notes":[]},{"n":4,"t":"我要侧耳听比喻，用琴解谜语。","notes":[]},{"n":5,"t":"在患难的日子，追逼我的人的奸恶环绕我，我何必惧怕？","notes":["“追逼我的人的奸恶”：七十士译本是“奸恶随我脚跟”。"]},{"n":6,"t":"他们那些倚靠财货，自夸钱财多的人，","notes":[]},{"n":7,"t":"没有一个能赎自己的弟兄，能将赎价给神，","notes":["“没有...弟兄”或译“哀哉，没有一个能赎回自己”。"]},{"n":8,"t":"让他长远活着，不见地府；因为赎生命的价值极贵，只可永远罢休。","notes":["“地府”：七十士译本是“朽坏”。"],"end":9},{"n":10,"t":"他要见智慧人死，愚昧人和畜牲一般的人一同灭亡，把他们的财货留给别人。","notes":[]},{"n":11,"t":"他们虽以自己的名叫自己的地，坟墓却作他们永远的家，作他们世世代代的居所。","notes":["本节根据七十士译本；原文是“他们心里思想：他们的家室必永存，住宅必留到万代；他们就以自己的名称自己的地。”"]},{"n":12,"t":"人居尊贵中不能长久，如同死亡的畜类一样。","notes":[]},{"n":13,"t":"他们所行之道本为自己的愚昧，后来的人却还佩服他们的话语。（细拉）","notes":[]},{"n":14,"t":"他们如同羊群注定要下阴间，死亡必作他们的牧者；到了早晨，正直人必管辖他们。他们的形像必被阴间所灭，无处可容身。","notes":[]},{"n":15,"t":"然而神必救赎我的命脱离阴间的掌控，因他必收纳我。（细拉）","notes":[]},{"n":16,"t":"见人发财、家室日益显赫的时候，你不要惧怕；","notes":[]},{"n":17,"t":"因为他死的时候什么也不能带去，他的荣耀不能随他下去。","notes":[]},{"n":18,"t":"他活着的时候，虽然自夸为有福─你若自己行得好，人必夸奖你─","notes":[]},{"n":19,"t":"他仍必与历代的祖宗一样同归死亡，永不见光。","notes":[]},{"n":20,"t":"人在尊贵中而不醒悟，就如死亡的畜类一样。","notes":[]}]},"50":{"heading":"真实的敬拜","verses":[{"n":1,"t":"大能者神－耶和华已经发言呼召天下，从日出之地到日落之处。","notes":[]},{"n":2,"t":"从全然美丽的锡安中，神已经发光了。","notes":[]},{"n":3,"t":"我们的神要来，绝不闭口；有烈火在他面前吞灭，有暴风在他四围刮起。","notes":[]},{"n":4,"t":"他呼召上天下地，为要审判他的子民：","notes":[]},{"n":5,"t":"“召集我的圣民，就是那些用祭物与我立约的人，到我这里来。”","notes":[]},{"n":6,"t":"诸天必表明他的公义，因为神是施行审判的。（细拉）","notes":[]},{"n":7,"t":"“听啊，我的子民，我要说话！以色列啊，我要审问你；我是神，是你的神！","notes":[]},{"n":8,"t":"我并不因你的祭物责备你；你的燔祭常在我面前。","notes":[]},{"n":9,"t":"我不从你家中取公牛，也不从你圈内取公山羊；","notes":[]},{"n":10,"t":"因为，林中的百兽是我的，千山的牲畜也是我的。","notes":[]},{"n":11,"t":"山中的飞鸟，我都知道，田野的走兽也都属我。","notes":["“山中”：七十士译本和其他古译本是“天空”。"]},{"n":12,"t":"“我若是饥饿，不用告诉你，因为世界和其中所充满的都是我的。","notes":[]},{"n":13,"t":"我岂吃公牛的肉呢？我岂喝公山羊的血呢？","notes":[]},{"n":14,"t":"你们要以感谢为祭献给神，又要向至高者还你的愿，","notes":[]},{"n":15,"t":"并要在患难之日求告我，我必搭救你，你也要荣耀我。”","notes":[]},{"n":16,"t":"但神对恶人说：“你怎敢传讲我的律例，口中提到我的约呢？","notes":[]},{"n":17,"t":"其实你恨恶管教，将我的言语抛在脑后。","notes":[]},{"n":18,"t":"你见了盗贼就乐意与他同伙，又和行奸淫的人同流合污。","notes":[]},{"n":19,"t":"“你的口出恶言，你的舌编造诡诈。","notes":[]},{"n":20,"t":"你坐着，毁谤你的兄弟，谗害你亲母的儿子。","notes":[]},{"n":21,"t":"你做了这些事，我闭口不言，你想我正如你一样；其实我要责备你，将这些事摆在你眼前。","notes":[]},{"n":22,"t":"“你们忘记神的，要思想这事，免得我把你们撕碎，无人搭救。","notes":[]},{"n":23,"t":"凡以感谢献祭的就是荣耀我；那按正路而行的，我必使他得着神的救恩。”","notes":[]}]},"51":{"heading":"求主赦免","verses":[{"n":1,"t":"神啊，求你按你的慈爱恩待我！按你丰盛的怜悯涂去我的过犯！","notes":[]},{"n":2,"t":"求你将我的罪孽洗涤净尽，洁除我的罪！","notes":[]},{"n":3,"t":"因为我知道我的过犯；我的罪常在我面前。","notes":[]},{"n":4,"t":"我向你犯罪，惟独得罪了你，在你眼前行了这恶，以致你责备的时候显为公义，判断的时候显为清白。","notes":[]},{"n":5,"t":"看哪，我是在罪孽里生的，在我母亲怀胎的时候就有了罪。","notes":[]},{"n":6,"t":"你所喜爱的是内心的诚实；求你在我隐密处使我得智慧。","notes":[]},{"n":7,"t":"求你用牛膝草洁净我，我就干净；求你洗涤我，我就比雪更白。","notes":[]},{"n":8,"t":"求你使我得听欢喜快乐的声音，使你所压伤的骨头可以踊跃。","notes":[]},{"n":9,"t":"求你转脸不看我的罪，涂去我一切的罪孽。","notes":[]},{"n":10,"t":"神啊，求你为我造清洁的心，使我里面重新有正直的灵。","notes":["“正直”或译“坚定”。"]},{"n":11,"t":"不要丢弃我，使我离开你的面；不要从我收回你的圣灵。","notes":[]},{"n":12,"t":"求你使我重得救恩之乐，以乐意的灵来扶持我，","notes":[]},{"n":13,"t":"我就把你的道指教有过犯的人，罪人必归顺你。","notes":[]},{"n":14,"t":"神啊，你是拯救我的神；求你救我脱离流人血的罪！我的舌头就高唱你的公义。","notes":[]},{"n":15,"t":"主啊，求你使我嘴唇张开，我的口就传扬赞美你的话！","notes":[]},{"n":16,"t":"你本不喜爱祭物，若喜爱，我就献上；燔祭你也不喜悦。","notes":[]},{"n":17,"t":"神所要的祭就是忧伤的灵；神啊，忧伤痛悔的心，你必不轻看。","notes":[]},{"n":18,"t":"求你随你的美意善待锡安，建造耶路撒冷的城墙。","notes":[]},{"n":19,"t":"那时，你必喜爱公义的祭和燔祭，全牲的燔祭；那时，人必将公牛献在你坛上。","notes":[]}]},"52":{"heading":"神的审判和恩惠","verses":[{"n":1,"t":"勇士啊，你为何作恶自夸？神的慈爱是常存的。","notes":[]},{"n":2,"t":"你这行诡诈的人哪，你的舌头像快利的剃刀，图谋毁灭。","notes":[]},{"n":3,"t":"你爱恶胜似爱善，又爱说谎，胜于爱说公义。（细拉）","notes":[]},{"n":4,"t":"诡诈的舌头啊，你爱说一切毁灭的话！","notes":[]},{"n":5,"t":"神也要毁灭你，直到永远。他要抓住你，从帐棚中拉你出来，从活人之地将你拔除。（细拉）","notes":[]},{"n":6,"t":"义人要看见而惧怕，并要笑他。","notes":[]},{"n":7,"t":"看哪，这就是那不以神为保障的人，他只倚靠丰富的财物，在邪恶上坚立自己。","notes":[]},{"n":8,"t":"至于我，就像神殿中的青橄榄树，我永永远远倚靠神的慈爱。","notes":[]},{"n":9,"t":"我要称谢你，直到永远，因为你做了这事。我也要在你圣民面前仰望你的名，这名本为美好。","notes":[]}]},"53":{"heading":"人的邪恶","verses":[{"n":1,"t":"愚顽人心里说：“没有神。”他们都败坏，行了可憎恶的罪孽，没有一个人行善。","notes":[]},{"n":2,"t":"神从天上垂看世人，要看有明白的没有，有寻求神的没有。","notes":[]},{"n":3,"t":"他们全都退后，一同变为污秽，没有行善的，连一个也没有。","notes":[]},{"n":4,"t":"作恶的都没有知识吗？他们吞吃我的百姓如同吃饭一样，并不求告神。","notes":[]},{"n":5,"t":"他们在无可惧怕之处就大大害怕，因为神使那安营攻击你之人的骨头散开了。你使他们蒙羞，因为神弃绝了他们。","notes":[]},{"n":6,"t":"但愿以色列的救恩出自锡安。当神救回他被掳子民的时候，雅各要快乐，以色列要欢喜。","notes":[]}]},"54":{"heading":"遭敌迫害求主保护","verses":[{"n":1,"t":"神啊，求你因你的名拯救我，凭你的大能为我伸冤。","notes":[]},{"n":2,"t":"神啊，求你听我的祷告，侧耳听我口中的言语。","notes":[]},{"n":3,"t":"因为陌生人兴起攻击我，强横的人寻索我的性命；他们眼中没有神。（细拉）","notes":[]},{"n":4,"t":"看哪，神是帮助我的，主是扶持我性命的，","notes":[]},{"n":5,"t":"他要报应我仇敌所作的恶；求你凭你的信实灭绝他们。","notes":[]},{"n":6,"t":"我要把甘心祭献给你；耶和华啊，我要颂扬你的名，这名本为美好。","notes":[]},{"n":7,"t":"他从一切的急难中把我救出来，我的眼睛也看见了我的仇敌遭报。","notes":[]}]},"55":{"heading":"被出卖者的祷告","verses":[{"n":1,"t":"神啊，求你侧耳听我的祷告，不要隐藏不听我的恳求！","notes":[]},{"n":2,"t":"求你留心听我，应允我。我哀叹不安，发出呻吟，","notes":[]},{"n":3,"t":"都因仇敌的声音，恶人的欺压；他们将罪孽加在我身上，发怒气加害我。","notes":[]},{"n":4,"t":"我的心在我里面阵痛，死亡的恐怖落在我身。","notes":[]},{"n":5,"t":"恐惧战兢临到了我，惊恐笼罩我。","notes":[]},{"n":6,"t":"我说：“但愿我有翅膀像鸽子，我就飞去，得享安息。","notes":[]},{"n":7,"t":"看哪，我要远走高飞，宿在旷野。（细拉）","notes":[]},{"n":8,"t":"我要速速逃到避难之所，脱离狂风暴雨。”","notes":[]},{"n":9,"t":"主啊，求你吞灭他们，变乱他们的言语！因为我在城中见了凶暴争吵的事。","notes":[]},{"n":10,"t":"他们昼夜在城墙上绕行，城内也有罪孽和奸恶。","notes":[]},{"n":11,"t":"邪恶在其中，欺压和诡诈不离街市。","notes":[]},{"n":12,"t":"原来，不是仇敌辱骂我，若是仇敌，还可忍受；也不是恨我的人向我狂妄自大，若是恨我的人，我必躲避他。","notes":[]},{"n":13,"t":"不料是你；你原与我同等，是我的朋友，是我的知己！","notes":[]},{"n":14,"t":"我们素常彼此交谈，以为甘甜；我们结伴在神的殿中同行。","notes":[]},{"n":15,"t":"愿死亡忽然临到他们！愿他们活生生地下入阴间！因为他们的住处都是邪恶，他们的内心充满奸恶。","notes":[]},{"n":16,"t":"至于我，我要求告神，耶和华必拯救我。","notes":[]},{"n":17,"t":"晚上、早晨、中午我要哀声悲叹，他就垂听我的声音。","notes":[]},{"n":18,"t":"他救赎我的命脱离攻击我的人，使我得享平安，因为与我相争的人很多。","notes":[]},{"n":19,"t":"那不愿改变、不敬畏神的人，从太古常存的神必听见而使他受苦。（细拉）","notes":[]},{"n":20,"t":"他背了约，伸手攻击与他和好的人。","notes":[]},{"n":21,"t":"他的口如奶油光滑，他的心却怀着敌意；他的话比油柔和，其实是拔出的刀。","notes":[]},{"n":22,"t":"你要把你的重担卸给耶和华，他必扶持你，他永不叫义人动摇。","notes":[]},{"n":23,"t":"神啊，你必使恶人坠入灭亡的坑；那好流人血、行诡诈的人必活不过半生，但我要倚靠你。","notes":[]}]},"56":{"heading":"信靠神的祈祷","verses":[{"n":1,"t":"神啊，求你怜悯我，因为有人践踏我，终日攻击欺压我。","notes":[]},{"n":2,"t":"我的仇敌终日践踏我，逞骄傲攻击我的人很多。","notes":[]},{"n":3,"t":"我惧怕的时候要倚靠你。","notes":[]},{"n":4,"t":"我倚靠神，我要赞美他的话语；我倚靠神，必不惧怕。血肉之躯能把我怎么样呢？","notes":[]},{"n":5,"t":"他们终日扭曲我的话，千方百计加害于我。","notes":[]},{"n":6,"t":"他们聚集，埋伏，窥探我的脚踪，等候要害我的命。","notes":[]},{"n":7,"t":"他们岂能脱罪呢？神啊，求你在怒中使万民败落！","notes":["“他们岂能脱罪呢”：七十士译本是“他们不能逃脱”。"]},{"n":8,"t":"我几次流离，你都数算；求你把我的眼泪装在你的皮袋里。这一切不都记在你的册子上吗？","notes":[]},{"n":9,"t":"我呼求的日子，仇敌都要转身撤退。神帮助我，这是我所知道的。","notes":[]},{"n":10,"t":"我倚靠神，我要赞美他的话语；我倚靠耶和华，我要赞美他的话语。","notes":[]},{"n":11,"t":"我倚靠神，必不惧怕。人能把我怎么样呢？","notes":[]},{"n":12,"t":"神啊，我要向你还所许的愿，我要以感谢祭回报你；","notes":[]},{"n":13,"t":"因为你救我的命脱离死亡。你保护我的脚不跌倒，使我在生命的光中行在神面前。","notes":[]}]},"57":{"heading":"求主拯救","verses":[{"n":1,"t":"神啊，求你怜悯我，怜悯我，因为我的心投靠你。我要投靠在你翅膀荫下，直等到灾害过去。","notes":[]},{"n":2,"t":"我要求告至高的神，就是为我成全万事的神。","notes":[]},{"n":3,"t":"那践踏我的人辱骂我的时候，神必从天上施恩救我，(细拉)他必向我施行慈爱和信实。","notes":[]},{"n":4,"t":"至于我的性命，我好像躺卧在吞噬人的狮子当中；他们的牙齿是枪、箭，他们的舌头是快刀。","notes":[]},{"n":5,"t":"神啊，愿你崇高过于诸天！愿你的荣耀高过全地！","notes":[]},{"n":6,"t":"他们为我的脚设下网罗，压迫我；他们在我面前掘了坑，自己反掉在其中。（细拉）","notes":[]},{"n":7,"t":"神啊，我心坚定，我心坚定；我要唱诗，我要歌颂！","notes":[]},{"n":8,"t":"我的灵啊，你当醒起！琴瑟啊，当醒起！我自己要极早醒起！","notes":["“灵”：原文是“荣耀”。"]},{"n":9,"t":"主啊，我要在万民中称谢你，在万族中歌颂你！","notes":[]},{"n":10,"t":"因为你的慈爱高及诸天，你的信实达到穹苍。","notes":[]},{"n":11,"t":"神啊，愿你崇高过于诸天！愿你的荣耀高过全地！","notes":[]}]},"58":{"heading":"求神罚恶","verses":[{"n":1,"t":"你们缄默不语，真合公义吗？你们审判世人，岂按正直吗？","notes":[]},{"n":2,"t":"不然！你们心中作恶，量出你们在地上手中的残暴。","notes":[]},{"n":3,"t":"恶人一出母胎就与神疏远，一离母腹就走错路，说谎话。","notes":[]},{"n":4,"t":"他们的毒气好像蛇的毒气，他们好像聋的毒蛇塞住耳朵，","notes":[]},{"n":5,"t":"听不见弄蛇者的声音，也听不见魔术师的咒语。","notes":[]},{"n":6,"t":"神啊，求你敲碎他们口中的牙！耶和华啊，求你敲掉少壮狮子的大牙！","notes":[]},{"n":7,"t":"愿他们消灭，如急流的水一般；他们瞄准射箭的时候，箭头仿佛折断。","notes":[]},{"n":8,"t":"愿他们像蜗牛腐烂消失，又像妇人流掉的胎儿，未见天日。","notes":[]},{"n":9,"t":"你们用荆棘烧火，锅还未热，神就用旋风把未烧着的和已烧着的一齐刮去。","notes":[]},{"n":10,"t":"义人见仇敌遭报就欢喜，他要在恶人的血中洗脚。","notes":[]},{"n":11,"t":"因此，人必说：“义人诚然有善报，在地上果然有施行审判的神！”","notes":[]}]},"59":{"heading":"求主保护","verses":[{"n":1,"t":"我的神啊，求你救我脱离仇敌，把我安置在高处，脱离那些起来攻击我的人。","notes":[]},{"n":2,"t":"求你救我脱离作恶的人，救我脱离好流人血的人！","notes":[]},{"n":3,"t":"因为他们埋伏要害我命，强悍的人聚集攻击我，耶和华啊，不是为我的过犯，也不是为我的罪愆。","notes":[]},{"n":4,"t":"我虽然无过，他们急忙摆阵攻击我。求你兴起，来帮助我，来鉴察！","notes":[]},{"n":5,"t":"万军之耶和华神－以色列的神啊，求你醒起，惩治万国！不要怜悯行诡诈的恶人！（细拉）","notes":[]},{"n":6,"t":"他们晚上转回，叫号如狗，围城绕行。","notes":[]},{"n":7,"t":"看哪，他们口中喷吐恶言，嘴里有刀：“有谁听见呢？”","notes":[]},{"n":8,"t":"但你－耶和华必讥笑他们，你要嗤笑万国。","notes":[]},{"n":9,"t":"我的力量啊，我要等候你，因为神是我的庇护所。","notes":["“我”：有古卷是“你”。"]},{"n":10,"t":"我的神要以慈爱迎接我，神要叫我看见我的仇敌遭报。","notes":["“我的神要以慈爱”：有古卷是“慈爱的神”。"]},{"n":11,"t":"主，我们的盾牌啊，不要杀他们，免得我的子民遗忘；求你用你的能力使他们四散，使他们降为卑。","notes":[]},{"n":12,"t":"愿他们因口中的罪和嘴唇的言语，被自己的骄傲抓住，他们所说的尽是咒骂和谎话。","notes":[]},{"n":13,"t":"求你发怒，使他们消灭，求你使他们消灭，归于无有，使他们知道神在雅各中间掌权，直到地极。（细拉）","notes":[]},{"n":14,"t":"他们晚上转回，叫号如狗，围城绕行。","notes":[]},{"n":15,"t":"他们到处走动觅食，若不饱足就咆哮不已。","notes":[]},{"n":16,"t":"但我要歌颂你的能力，早晨要高唱你的慈爱；因为你是我的庇护所，在急难的日子作过我的避难所。","notes":[]},{"n":17,"t":"我的力量啊，我要歌颂你；因为神是我的庇护所，是赐恩给我的神。","notes":[]}]},"60":{"heading":"求主解救","verses":[{"n":1,"t":"神啊，你丢弃了我们，破坏了我们；你曾发怒，求你使我们复兴！","notes":[]},{"n":2,"t":"你使地震动，崩裂；求你将裂口补好，因为地在摇动。","notes":[]},{"n":3,"t":"你让你的子民遇见艰难，使我们喝那令人东倒西歪的酒。","notes":[]},{"n":4,"t":"你把旌旗赐给敬畏你的人，可以躲避弓箭。（细拉）","notes":["“躲避弓箭”是根据七十士译本；原文是“为真理扬起来”。"]},{"n":5,"t":"求你应允我们，用右手施行拯救，好让你所亲爱的人得救。","notes":["“我们”：原文另译“我”。"]},{"n":6,"t":"神在他的圣所说：“我要欢乐；要划分示剑，丈量疏割谷。","notes":["“在他的圣所”或译“指着他的圣洁”。"]},{"n":7,"t":"基列是我的，玛拿西是我的。以法莲是护卫我头的，犹大是我的权杖。","notes":[]},{"n":8,"t":"摩押是我的沐浴盆，我要向以东扔鞋。非利士啊，你还能因我欢呼吗？”","notes":[]},{"n":9,"t":"谁能领我进坚固城？谁能引我到以东地？","notes":[]},{"n":10,"t":"神啊，你真的丢弃了我们吗？神啊，你不和我们的军队同去吗？","notes":[]},{"n":11,"t":"求你帮助我们攻击敌人，因为人的帮助是枉然的。","notes":[]},{"n":12,"t":"我们倚靠神才得施展大能，因为践踏我们敌人的就是他。","notes":[]}]},"61":{"heading":"求主保佑","verses":[{"n":1,"t":"神啊，求你听我的呼求，留心听我的祷告！","notes":[]},{"n":2,"t":"我心里发昏的时候，要从地极求告你。求你领我到那比我更高的磐石，","notes":[]},{"n":3,"t":"因为你是我的避难所，是我的坚固台，使我脱离仇敌。","notes":[]},{"n":4,"t":"我要永远住在你的帐幕里！我要投靠在你翅膀下的隐密处！（细拉）","notes":[]},{"n":5,"t":"神啊，你听了我所许的愿；你将产业赐给敬畏你名的人。","notes":[]},{"n":6,"t":"求你加添王的寿数，使他的年岁存到世世代代。","notes":[]},{"n":7,"t":"愿他在神面前永远坐在王位上，求你预备慈爱和信实保佑他！","notes":[]},{"n":8,"t":"这样，我要歌颂你的名，直到永远，天天还我所许的愿。","notes":[]}]},"62":{"heading":"在神保佑中安稳自在","verses":[{"n":1,"t":"我的心默默无声，专等候神，我的救恩从他而来。","notes":[]},{"n":2,"t":"惟独他是我的磐石，我的拯救；他是我的庇护所，我必不大大动摇。","notes":[]},{"n":3,"t":"你们大家攻击一人，使他被杀，如歪斜的墙、将倒的壁，要到几时呢？","notes":[]},{"n":4,"t":"他们彼此商议，要把他从高位上拉下来；他们喜爱谎话，口虽祝福，心却诅咒。（细拉）","notes":[]},{"n":5,"t":"我的心哪，你当默默无声，专等候神，因为我的盼望是从他而来。","notes":[]},{"n":6,"t":"惟独他是我的磐石，我的拯救；他是我的庇护所，我必不动摇。","notes":[]},{"n":7,"t":"我的拯救、我的荣耀都在于神；我力量的磐石、我的避难所都在于神。","notes":[]},{"n":8,"t":"百姓啊，要时时倚靠他，在他面前倾心吐意；神是我们的避难所。（细拉）","notes":[]},{"n":9,"t":"人真是虚空，人真是虚假；放在天平里就必浮起，他们一共比空气还轻。","notes":[]},{"n":10,"t":"不要仗势欺人，也不要因抢夺而骄傲；若财宝加增，不要放在心上。","notes":[]},{"n":11,"t":"神说了一次、两次，我都听见了，就是能力属乎神。","notes":[]},{"n":12,"t":"主啊，慈爱也是属乎你，因为你照着各人所做的报应他。","notes":[]}]},"63":{"heading":"渴慕神","verses":[{"n":1,"t":"神啊，你是我的神，我要切切寻求你；在干旱疲乏无水之地，我的心灵渴想你，我的肉身切慕你。","notes":[]},{"n":2,"t":"我在圣所中曾如此瞻仰你，为要见你的能力和你的荣耀。","notes":[]},{"n":3,"t":"因你的慈爱比生命更好，我的嘴唇要颂赞你。","notes":[]},{"n":4,"t":"我还活着的时候要这样称颂你，我要奉你的名举手。","notes":[]},{"n":5,"t":"我在床上记念你，在夜更的时候思念你；我的心像吃饱了骨髓肥油，我也要以欢乐的嘴唇赞美你。","notes":[],"end":6},{"n":7,"t":"因为你曾帮助了我，我要在你翅膀的荫下欢呼。","notes":[]},{"n":8,"t":"我的心紧紧跟随你；你的右手扶持了我。","notes":[]},{"n":9,"t":"但那些寻索要灭我命的人必往地底下去；","notes":[]},{"n":10,"t":"他们必被刀剑所杀，成为野狗的食物。","notes":[]},{"n":11,"t":"但是王必因神欢喜，凡指着他发誓的都要夸耀，因为说谎之人的口必被塞住。","notes":[]}]},"64":{"heading":"求主保护","verses":[{"n":1,"t":"神啊，我哀叹的时候，求你听我的声音！求你保护我的性命，不受仇敌的惊吓！","notes":[]},{"n":2,"t":"求你把我隐藏，使我脱离作恶之人的暗谋，脱离作孽之人的扰乱。","notes":[]},{"n":3,"t":"他们磨舌如刀，发出苦毒的言语，好像瞄准了的箭，","notes":[]},{"n":4,"t":"要在暗地里射完全人；他们忽然射他，并不惧怕。","notes":[]},{"n":5,"t":"他们彼此勉励，设下恶计；他们商量，暗设圈套，说：“谁能看见呢？”","notes":[]},{"n":6,"t":"他们图谋奸恶：“我们完成了精密的策划。”各人的意念心思是深沉的。","notes":[]},{"n":7,"t":"但神要用箭射他们，他们忽然受了伤。","notes":[]},{"n":8,"t":"他们必然绊跌，被自己的舌头所害；凡看见他们的都必摇头。","notes":[]},{"n":9,"t":"众人都要害怕，要传扬神的工作，并且明白他的作为。","notes":[]},{"n":10,"t":"义人必因耶和华欢喜，并要投靠他；凡心里正直的人都必夸耀。","notes":[]}]},"65":{"heading":"颂赞主恩","verses":[{"n":1,"t":"神啊，在锡安，人都等候赞美你，也要向你还所许的愿。","notes":[]},{"n":2,"t":"听祷告的主啊，凡有血肉之躯的都要来就你。","notes":[]},{"n":3,"t":"罪孽胜了我；至于我们的过犯，你都要赦免。","notes":[]},{"n":4,"t":"你所拣选、使他亲近你、住在你院中的，这人有福了！我们要因你居所、你圣殿的美福知足。","notes":[]},{"n":5,"t":"拯救我们的神啊，你必以威严秉公义应允我们；地极和海角远方的人都倚靠你。","notes":[]},{"n":6,"t":"你既以大能束腰，就用力量安定诸山，","notes":[]},{"n":7,"t":"使诸海的响声和其中波浪的响声，并万民的喧哗，都平静了。","notes":[]},{"n":8,"t":"住在地极的人因你的神迹惧怕，你使日出日落之地都欢呼。","notes":[]},{"n":9,"t":"你眷顾地，降雨使地大大肥沃。神的河满了水；你这样浇灌了地，好为人预备五谷。","notes":[]},{"n":10,"t":"你浇透地的犁沟，润泽犁脊，降甘霖，使地松软；其中生长的，蒙你赐福。","notes":[]},{"n":11,"t":"你以恩惠为年岁的冠冕，你的路径都滴下油脂，","notes":[]},{"n":12,"t":"滴在旷野的草场上。小山以欢乐束腰，","notes":[]},{"n":13,"t":"草场以羊群为衣，谷中也长满了五谷；这一切都欢呼歌唱。","notes":[]}]},"66":{"heading":"颂赞感恩的诗","verses":[{"n":1,"t":"全地都当向神欢呼！","notes":[]},{"n":2,"t":"当歌颂他名的荣耀，使赞美他的话大有荣耀！","notes":[]},{"n":3,"t":"当对神说：“你的作为何等可畏！因你的大能，仇敌要向你投降。","notes":[]},{"n":4,"t":"全地要敬拜你，歌颂你，要歌颂你的名。”（细拉）","notes":[]},{"n":5,"t":"你们来看神所做的，他向世人所做之事是可畏的。","notes":[]},{"n":6,"t":"他将海变成干地，使百姓步行过河；我们在那里要因他欢喜。","notes":[]},{"n":7,"t":"他用权能治理，直到永远。他的眼睛鉴察万民；悖逆的人不可自高。（细拉）","notes":[]},{"n":8,"t":"万民哪，你们当称颂我们的神，使人得听赞美他的声音。","notes":[]},{"n":9,"t":"他使我们的性命存活，不叫我们的脚摇动。","notes":[]},{"n":10,"t":"神啊，你曾考验我们，你熬炼我们，如炼银子一样。","notes":[]},{"n":11,"t":"你使我们进入罗网，把重担放在我们身上。","notes":[]},{"n":12,"t":"你使人坐车轧我们的头；我们经过水火，你却使我们到丰富之地。","notes":[]},{"n":13,"t":"我要带着燔祭进你的殿，向你还我的愿，","notes":[]},{"n":14,"t":"就是在急难时我嘴唇所发的、口中所许的。","notes":[]},{"n":15,"t":"我要将肥牛的燔祭和公羊的香祭献给你，又要把公牛和公山羊献上。（细拉）","notes":[]},{"n":16,"t":"敬畏神的人哪，你们都来听！我要述说他为我所做的事。","notes":[]},{"n":17,"t":"我曾用口求告他，我的舌头也称他为高。","notes":[]},{"n":18,"t":"我若心里注重罪孽，主必不听。","notes":[]},{"n":19,"t":"但神实在听见了，他留心听了我祷告的声音。","notes":[]},{"n":20,"t":"神是应当称颂的！他没有推却我的祷告，也没有使他的慈爱离开我。","notes":[]}]},"67":{"heading":"感恩的诗","verses":[{"n":1,"t":"愿神怜悯我们，赐福给我们，使他的脸向我们发光，（细拉）","notes":[]},{"n":2,"t":"好让全地得知你的道路，万国得知你的救恩。","notes":[]},{"n":3,"t":"神啊，愿万民称谢你！愿万民都称谢你！","notes":[]},{"n":4,"t":"愿万族都快乐欢呼；因为你必按公正审判万民，引导地上的万族。（细拉）","notes":[]},{"n":5,"t":"神啊，愿万民称谢你！愿万民都称谢你！","notes":[]},{"n":6,"t":"地已经出了土产，神，我们的神，要赐福给我们。","notes":[]},{"n":7,"t":"神要赐福给我们，地的四极都要敬畏他！","notes":[]}]},"68":{"heading":"胜利之歌","verses":[{"n":1,"t":"愿神兴起，使他的仇敌四散，使那恨他的人从他面前逃跑。","notes":[]},{"n":2,"t":"你驱逐他们，如烟被吹散；恶人见神的面就消灭，如蜡被火熔化。","notes":["“你驱逐他们”：有古译本是“他们被驱逐”。"]},{"n":3,"t":"惟有义人必然欢喜，在神面前快乐，他们要在喜乐中欢欣。","notes":[]},{"n":4,"t":"你们当向神唱诗，歌颂他的名；为那驾车经过旷野的修平道路。他的名是耶和华，你们要在他面前欢乐！","notes":["“为那...道路”或译“为那驾云的高唱”。"]},{"n":5,"t":"神在他的圣所作孤儿的父，作寡妇的伸冤者。","notes":[]},{"n":6,"t":"神使孤独的有家，使被囚的出来享福；惟有悖逆的要住在干旱之地。","notes":[]},{"n":7,"t":"神啊，当你走在百姓前头，在旷野行进，（细拉）","notes":[]},{"n":8,"t":"地见神的面就震动，天也降雨；西奈山见以色列神的面也震动。","notes":[]},{"n":9,"t":"神啊，你降下大雨；你的产业以色列疲乏的时候，你使他坚固。","notes":[]},{"n":10,"t":"你的会众住在境内；神啊，你在恩惠中为困苦人预备所需的。","notes":[]},{"n":11,"t":"主发命令，传好信息的妇女成了大群：","notes":[]},{"n":12,"t":"“统领大军的君王逃跑了，逃跑了！”在家等候的妇女也分得了掠物。","notes":[]},{"n":13,"t":"你们躺卧在羊圈，好像鸽子的翅膀镀银，翎毛镀金一般。","notes":[]},{"n":14,"t":"全能者在境内赶散列王的时候，势如飘雪在撒们。","notes":[]},{"n":15,"t":"巴珊山是极其宏伟的山，巴珊山是多峰多岭的山。","notes":["“极其宏伟”或译“神”。"]},{"n":16,"t":"你们多峰多岭的山哪，为何以妒忌的眼光看神所愿居住的山？耶和华必住这山，直到永远！","notes":[]},{"n":17,"t":"神的车辇累万盈千；主在其中，好像在西奈圣山一样。","notes":[]},{"n":18,"t":"你已经升上高天，掳掠了俘虏；你在人间，就是在悖逆的人中，受了供献，使耶和华神可以与他们同住。","notes":[]},{"n":19,"t":"天天背负我们重担的主，就是拯救我们的神，是应当称颂的！（细拉）","notes":[]},{"n":20,"t":"神是为我们施行拯救的神；人能脱离死亡是在乎主─耶和华。","notes":[]},{"n":21,"t":"但神要打破他仇敌的头，就是那常犯罪之人的头颅。","notes":[]},{"n":22,"t":"主说：“我要使百姓从巴珊归来，使他们从深海转回，","notes":[]},{"n":23,"t":"好叫你打碎仇敌，使你的脚踹在血中，使你狗的舌头也有份。”","notes":[]},{"n":24,"t":"神啊，你是我的神，我的王；人已经看见你行走，进入圣所。","notes":[]},{"n":25,"t":"歌唱的行在前，作乐的随在后，都在击鼓的童女中间：","notes":[]},{"n":26,"t":"“从以色列源头而来的啊，你们当在各会中称颂神─耶和华！”","notes":[]},{"n":27,"t":"在那里，有统管他们的小便雅悯，有犹大的领袖和他们的一群人，有西布伦的领袖，有拿弗他利的领袖。","notes":[]},{"n":28,"t":"你的神已赐给你力量；神啊，求你坚固你为我们所成全的事！","notes":["“你的神已赐给你力量”：有古卷是“神啊，求你赏赐你的力量”。"]},{"n":29,"t":"因你耶路撒冷的殿，列王必带贡物献给你。","notes":[]},{"n":30,"t":"求你斥责芦苇中的野兽和公牛群，并万民中的牛犊。直到他们带着银块来朝贡；神已经赶散好战的万民。","notes":["“直到...朝贡”：原文另译“把银块踹在脚下”。","“神...万民”：原文另译“赶散好战的万民”。"]},{"n":31,"t":"埃及的使臣要出来，古实人要急忙向神伸出手来。","notes":["“古实”：包括苏丹的大部分和埃塞俄比亚的一部分。"]},{"n":32,"t":"地上的国度啊， 你们要向神歌唱，要歌颂主，（细拉）","notes":[]},{"n":33,"t":"就是那驾行在亘古的诸天之上的主！听啊，他发出声音，是极大的声音。","notes":[]},{"n":34,"t":"你们要将能力归给神；他的威荣在以色列之上，他的能力显在天上。","notes":[]},{"n":35,"t":"神啊，你从圣所显为可畏，以色列的神是那将力量权能赐给他百姓的。神是应当称颂的！","notes":[]}]},"69":{"heading":"求助的祷告","verses":[{"n":1,"t":"神啊，求你救我！因为众水就要淹没我。","notes":[]},{"n":2,"t":"我深陷在淤泥中，没有立脚之地；我到了深水之中，波涛漫过我身。","notes":[]},{"n":3,"t":"我因呼求困乏，喉咙发干；我因等候神，眼睛失明。","notes":[]},{"n":4,"t":"无故恨我的，比我的头发还多；无理与我为仇、要把我剪除的，甚为强盛。我没有抢夺，他们竟然要我偿还！","notes":[]},{"n":5,"t":"神啊，我的愚昧，你原知道，我的罪愆不能向你隐瞒。","notes":[]},{"n":6,"t":"万军之主耶和华啊，求你不要让那等候你的因我蒙羞！以色列的神啊，求你不要让那寻求你的因我受辱！","notes":[]},{"n":7,"t":"因我为你的缘故受了辱骂，满面羞愧。","notes":[]},{"n":8,"t":"我的兄弟把我当陌生人，我母亲的儿子把我当外邦人。","notes":[]},{"n":9,"t":"因我为你的殿心里焦急，如同火烧，并且辱骂你的人的辱骂都落在我身上。","notes":[]},{"n":10,"t":"我哭泣，以禁食刻苦我心；这倒成了我的羞辱。","notes":[]},{"n":11,"t":"我拿麻布当衣裳，却成了他们的笑柄。","notes":[]},{"n":12,"t":"坐在城门口的谈论我，酒徒也以我为歌曲。","notes":[]},{"n":13,"t":"至于我，耶和华啊，在悦纳的时候我向你祈祷。神啊，求你按你丰盛的慈爱，凭你拯救的信实应允我！","notes":[]},{"n":14,"t":"求你搭救我脱离淤泥，不叫我陷在其中；求你使我脱离那些恨我的人，使我脱离深水。","notes":[]},{"n":15,"t":"求你不容波涛漫过我，不容深渊吞灭我，不容深坑在我以上合口。","notes":[]},{"n":16,"t":"耶和华啊，求你应允我！因为你的慈爱本为美好；求你按你丰盛的怜悯转回眷顾我！","notes":[]},{"n":17,"t":"不要转脸不顾你的仆人；我在急难之中，求你速速应允我！","notes":[]},{"n":18,"t":"求你亲近我，救赎我！求你因我仇敌的缘故将我赎回！","notes":[]},{"n":19,"t":"你知道我所受的辱骂、欺凌、羞辱；我的敌人都在你面前。","notes":[]},{"n":20,"t":"辱骂刺伤我的心，使我忧愁。我指望有人体恤，却没有一个；指望有人安慰，却找不着一个。","notes":[]},{"n":21,"t":"他们拿苦胆给我当食物；我渴了，他们拿醋给我喝。","notes":[]},{"n":22,"t":"愿他们的筵席在他们面前变为罗网，在他们平安的时候变为圈套。","notes":["“在他们平安的时候”或译“对他们的朋友”。"]},{"n":23,"t":"愿他们的眼睛昏花，看不见；求你使他们的腰常常战抖。","notes":[]},{"n":24,"t":"求你将你的恼恨倒在他们身上，使你的烈怒追上他们。","notes":[]},{"n":25,"t":"愿他们的住处变为废墟，他们的帐棚无人居住。","notes":[]},{"n":26,"t":"因为你所击打的，他们就迫害；你所击伤的，他们述说他的愁苦。","notes":["“述说”：原文另译“增加”。"]},{"n":27,"t":"求你使他们罪上加罪，不容他们在你面前称义。","notes":[]},{"n":28,"t":"愿他们从生命册上被涂去，不得名列在义人之中。","notes":[]},{"n":29,"t":"但我困苦忧伤；神啊，愿你的救恩将我安置在高处。","notes":[]},{"n":30,"t":"我要以诗歌赞美神的名，以感谢尊他为大！","notes":[]},{"n":31,"t":"这就让耶和华喜悦，胜似献牛，献有角有蹄的公牛。","notes":[]},{"n":32,"t":"谦卑的人看见了就喜乐；寻求神的人，愿你们的心苏醒。","notes":[]},{"n":33,"t":"因为耶和华听了穷乏的人，不藐视被囚的人。","notes":[]},{"n":34,"t":"愿天和地、海洋和其中一切的动物都赞美他！","notes":[]},{"n":35,"t":"因为神要拯救锡安，建造犹大的城镇；他的子民要在那里居住，得地为业。","notes":[]},{"n":36,"t":"他仆人的后裔要承受这地，爱他名的人要住在其中。","notes":[]}]},"70":{"heading":"求助的祈祷","verses":[{"n":1,"t":"神啊，求你快快搭救我！耶和华啊，求你速速帮助我！","notes":[]},{"n":2,"t":"愿那些寻索我命的，抱愧蒙羞；愿那些喜悦我遭害的，退后受辱。","notes":[]},{"n":3,"t":"愿那些对我说“啊哈、啊哈”的，因羞愧退后。","notes":[]},{"n":4,"t":"愿所有寻求你的，因你欢喜快乐；愿那些喜爱你救恩的，常说：“当尊神为大！”","notes":[]},{"n":5,"t":"但我是困苦贫穷的；神啊，求你速速到我这里来！你是帮助我的，搭救我的；耶和华啊，求你不要耽延！","notes":[]}]},"71":{"heading":"老年人的祈祷","verses":[{"n":1,"t":"耶和华啊，我投靠你，求你叫我永不羞愧！","notes":[]},{"n":2,"t":"求你凭你的公义搭救我，救拔我；侧耳听我，拯救我！","notes":[]},{"n":3,"t":"求你作我常来栖身的磐石，你已经吩咐要救我，因为你是我的岩石、我的山寨。","notes":["“栖身”：有古卷是“避难”。"]},{"n":4,"t":"我的神啊，求你救我脱离恶人的手，脱离不义和残暴之人的手。","notes":[]},{"n":5,"t":"主耶和华啊，你是我所盼望的；自我年幼，你是我所倚靠的。","notes":[]},{"n":6,"t":"我自出母胎被你扶持，使我出母腹的是你。我要常常赞美你！","notes":[]},{"n":7,"t":"许多人看我为异类，但你是我坚固的避难所。","notes":[]},{"n":8,"t":"我要满口述说赞美你的话终日荣耀你。","notes":[]},{"n":9,"t":"我年老的时候，求你不要丢弃我！我体力衰弱时，求你不要离弃我！","notes":[]},{"n":10,"t":"我的仇敌议论我，那些窥探要害我命的一同商议，","notes":[]},{"n":11,"t":"说：“神已经离弃他；你们去追赶他，捉拿他吧！因为没有人搭救。”","notes":[]},{"n":12,"t":"神啊，求你不要远离我！我的神啊，求你速速帮助我！","notes":[]},{"n":13,"t":"愿那与我为敌的，羞愧灭亡；愿那谋害我的，受辱蒙羞。","notes":[]},{"n":14,"t":"我却要常常仰望，并要越发赞美你。","notes":[]},{"n":15,"t":"我的口要终日述说你的公义和你的救恩，因我无从计算其数。","notes":[]},{"n":16,"t":"我要述说主耶和华的大能，我单要提说你的公义。","notes":[]},{"n":17,"t":"神啊，自我年幼，你就教导我；直到如今，我传扬你奇妙的作为。","notes":[]},{"n":18,"t":"神啊，我年老发白的时候，求你不要离弃我！等我宣扬你的能力给下一代，宣扬你的大能给后世的人。","notes":[]},{"n":19,"t":"神啊，你的公义极高；行过大事的神啊，谁能像你？","notes":[]},{"n":20,"t":"你是叫我多经历重大急难的，必使我再活过来，从地的深处救我上来。","notes":[]},{"n":21,"t":"你必使我越发昌大，又转来安慰我。","notes":[]},{"n":22,"t":"我的神啊，我要鼓瑟称谢你，称谢你的信实！以色列的圣者啊，我要弹琴歌颂你！","notes":[]},{"n":23,"t":"我歌颂你的时候，我的嘴唇要欢呼；我的性命，就是你所救赎的，也要欢呼。","notes":[]},{"n":24,"t":"我的舌头也必终日讲论你的公义，因为那些谋害我的人已经蒙羞受辱了。","notes":[]}]},"72":{"heading":"为王祈祷","verses":[{"n":1,"t":"神啊，求你将你的公平赐给王，将你的公义赐给王的儿子。","notes":[]},{"n":2,"t":"使他按公义审判你的子民，按公平审判你的困苦人。","notes":[]},{"n":3,"t":"大山小山都要因公义使百姓得享平安。","notes":[]},{"n":4,"t":"他必为百姓中困苦的人伸冤，拯救贫穷之辈，压碎那欺压人的人。","notes":[]},{"n":5,"t":"太阳还存，月亮犹在，人要敬畏你，直到万代！","notes":["“人要敬畏你”：七十士译本是“愿他永活”。"]},{"n":6,"t":"他必降临，像雨降在已割的草地上，如甘霖滋润田地。","notes":[]},{"n":7,"t":"在他的日子，公义要兴旺，大有平安，除非月亮不在。","notes":["“公义”：有古卷是“义人”。"]},{"n":8,"t":"他要执掌权柄，从这海直到那海，从大河直到地极。","notes":[]},{"n":9,"t":"住在旷野的必在他面前下拜，他的仇敌必要舔土。","notes":[]},{"n":10,"t":"他施和海岛的王要进贡，示巴和西巴的王要献礼物。","notes":[]},{"n":11,"t":"众王都要叩拜他，万国都要事奉他。","notes":[]},{"n":12,"t":"贫穷人呼求，他要搭救，无人帮助的困苦人，他也搭救。","notes":[]},{"n":13,"t":"他要怜悯贫寒和贫穷的人，拯救贫穷人的性命。","notes":[]},{"n":14,"t":"他要救赎他们脱离欺压和残暴，他们的血在他眼中看为宝贵。","notes":[]},{"n":15,"t":"愿他永远活着，示巴的金子要献给他；愿人常常为他祷告，终日祝福他。","notes":[]},{"n":16,"t":"在地的山顶上，愿五谷茂盛，所结的谷实响动，如黎巴嫩的树林；愿城里的人兴旺，如地上的草。","notes":[]},{"n":17,"t":"愿他的名存到永远，他的名如太阳之长久；愿人因他蒙福，万国称他为有福。","notes":["“长久”：原文另译“坚定”或“延续”。"]},{"n":18,"t":"惟独耶和华－以色列的神能行奇事，他是应当称颂的！","notes":[]},{"n":19,"t":"他荣耀的名也当称颂，直到永远。愿他的荣耀充满全地！阿们！阿们！","notes":[]},{"n":20,"t":"耶西的儿子－大卫的祈祷完毕。","notes":[]}]},"73":{"heading":"神的公正","verses":[{"n":1,"t":"神实在恩待以色列那些清心的人！","notes":[]},{"n":2,"t":"至于我，我的脚几乎失闪，我的步伐险些走偏；","notes":[]},{"n":3,"t":"因为我嫉妒狂傲的人，我看见恶人享平安。","notes":[]},{"n":4,"t":"他们的力气强壮，他们死的时候也没有疼痛。","notes":[]},{"n":5,"t":"他们不像别人受苦，也不像别人遭灾。","notes":[]},{"n":6,"t":"所以，骄傲如链子戴在他们项上，残暴像衣裳覆盖在他们身上。","notes":[]},{"n":7,"t":"他们的眼睛因体胖而凸出，他们的内心放任不羁。","notes":["“眼睛”：原文另译“罪孽”。","“他们的内心放任不羁”：七十士译本是“他们得到心里所想的”。"]},{"n":8,"t":"他们讥笑人，凭恶意说欺压人的话。他们说话自高；","notes":[]},{"n":9,"t":"他们的口亵渎上天，他们的舌毁谤全地。","notes":[]},{"n":10,"t":"所以他的百姓归到这里，享受满杯的水。","notes":["“享受...水”或译“喝尽了满杯的苦水”。"]},{"n":11,"t":"他们说：“神怎能晓得？至高者哪会知道呢？”","notes":[]},{"n":12,"t":"看哪，这就是恶人，他们常享安逸，财宝增多。","notes":[]},{"n":13,"t":"我实在徒然洁净了我的心，徒然洗手表明我的无辜，","notes":[]},{"n":14,"t":"因为我终日遭灾难，每日早晨受惩治。","notes":[]},{"n":15,"t":"我若说“我要这样讲”，就是愧对这世代的众儿女了。","notes":[]},{"n":16,"t":"我思索要明白这事，眼看实系为难，","notes":[]},{"n":17,"t":"直到我进了神的圣所，思想他们的结局。","notes":[]},{"n":18,"t":"你实在把他们安放在滑地，使他们跌倒灭亡；","notes":[]},{"n":19,"t":"他们转眼之间成了何等荒凉！他们被惊恐灭尽了。","notes":[]},{"n":20,"t":"人睡醒了，怎样看梦，主啊，你醒了也必照样轻看他们的影像。","notes":[]},{"n":21,"t":"因此，我心里苦恼，肺腑被刺。","notes":[]},{"n":22,"t":"我这样愚昧无知，在你面前如同畜牲。","notes":[]},{"n":23,"t":"然而，我常与你同在；你搀扶我的右手。","notes":[]},{"n":24,"t":"你要以你的训言引导我，以后你必接我到荣耀里。","notes":[]},{"n":25,"t":"除你以外，在天上我有谁呢？除你以外，在地上我也没有所爱慕的。","notes":[]},{"n":26,"t":"我的肉体和我的心肠衰残；但神是我心里的力量，又是我的福分，直到永远。","notes":[]},{"n":27,"t":"看哪，远离你的，必要死亡；凡离弃你行淫的，你都灭绝了。","notes":[]},{"n":28,"t":"但我亲近神是于我有益；我以主耶和华为我的避难所，好叫我述说你一切的作为。","notes":[]}]},"74":{"heading":"求主解救国家","verses":[{"n":1,"t":"神啊，你为何永远丢弃我们呢？为何向你草场的羊发怒，如烟冒出呢？","notes":[]},{"n":2,"t":"求你记念你古时得来的会众，就是你所赎、作你产业支派的，并记念你向来居住的锡安山。","notes":[]},{"n":3,"t":"求你举步去看那日久荒凉之地，看仇敌在圣所中所做的一切恶事。","notes":[]},{"n":4,"t":"你的敌人在你会中吼叫，他们竖起自己的标帜为记号，","notes":[]},{"n":5,"t":"好像人扬起斧子对着林中的树，","notes":["“好像人扬起斧子”：七十士译本和其他古译本是“好像斧子在入口处”。"]},{"n":6,"t":"现在将圣所中的雕刻，全都用斧子锤子打坏。","notes":["“雕刻”：七十士译本是“门扉”。"]},{"n":7,"t":"他们用火焚烧你的圣所，亵渎你名的居所于地。","notes":[]},{"n":8,"t":"他们心里说“我们要尽行毁灭”；就在遍地烧毁敬拜神聚会的所在。","notes":[]},{"n":9,"t":"我们看不见自己的标帜，不再有先知，我们当中也无人知道这灾祸要到几时。","notes":[]},{"n":10,"t":"神啊，敌人辱骂要到几时呢？仇敌藐视你的名要到永远吗？","notes":[]},{"n":11,"t":"你为什么缩回你的右手？求你从怀中伸出手来，毁灭他们。","notes":[]},{"n":12,"t":"神自古以来是我的王，在这地上施行拯救。","notes":[]},{"n":13,"t":"你曾用能力将海分开，你打破水里大鱼的头。","notes":[]},{"n":14,"t":"你曾压碎力威亚探的头，把它给旷野的禽兽作食物。","notes":["“力威亚探”是音译，一种海兽。"]},{"n":15,"t":"你曾分裂泉源和溪流；使长流的江河枯干。","notes":[]},{"n":16,"t":"白昼属你，黑夜也属你；亮光和太阳是你预备的。","notes":[]},{"n":17,"t":"地的一切疆界是你立的，夏天和冬天是你定的。","notes":[]},{"n":18,"t":"耶和华啊，仇敌辱骂，愚顽之辈藐视你的名；求你记念这事。","notes":[]},{"n":19,"t":"不要将属你的斑鸠交给野兽，不要永远忘记你困苦人的性命。","notes":["“斑鸠”：七十士译本和其他古译本是“赞美”。"]},{"n":20,"t":"求你顾念所立的约，因为地上黑暗之处遍满了凶暴。","notes":[]},{"n":21,"t":"不要让受欺压的人蒙羞回去；要使困苦贫穷的人赞美你的名。","notes":[]},{"n":22,"t":"神啊，求你起来为自己辩护！求你记念愚顽人怎样终日辱骂你。","notes":[]},{"n":23,"t":"不要忘记你敌人的喧闹，就是那时常上升、起来对抗你之人的喧哗。","notes":[]}]},"75":{"heading":"神是审判者","verses":[{"n":1,"t":"神啊，我们称谢你，我们称谢你！你的名临近，人都述说你奇妙的作为。","notes":["“人”：七十士译本是“我”。"]},{"n":2,"t":"我选定了日期，必按正直施行审判。","notes":[]},{"n":3,"t":"地和其上的居民都熔化了；我亲自坚立地的柱子。（细拉）","notes":[]},{"n":4,"t":"我对狂傲的人说：“不要狂傲！”对凶恶的人说：“不要举角！”","notes":[]},{"n":5,"t":"不要把你们的角高举，不要挺着颈项说话。","notes":["“挺着颈项”：七十士译本是“顶撞神”。"]},{"n":6,"t":"因为高举非从东，非从西，也非从南而来。","notes":[]},{"n":7,"t":"惟有神断定，他使这人降卑，使那人升高。","notes":[]},{"n":8,"t":"耶和华的手里有杯，杯内满了调和起沫的酒；他倒出来，地上的恶人都必喝，直到喝尽它的渣滓。","notes":[]},{"n":9,"t":"但我要宣扬，直到永远！我要歌颂雅各的神！","notes":[]},{"n":10,"t":"恶人一切的角，我要砍断；惟有义人的角必被高举。","notes":[]}]},"76":{"heading":"神是胜利者","verses":[{"n":1,"t":"在犹大，神为人所认识；在以色列，他的名为大。","notes":[]},{"n":2,"t":"在撒冷有他的住处，在锡安有他的居所。","notes":[]},{"n":3,"t":"他在那里折断弓上的火箭、盾牌、刀剑和战争的兵器。（细拉）","notes":[]},{"n":4,"t":"你是光荣的，比猎物之山更威严。","notes":["“猎物”：七十士译本是“永恒”。"]},{"n":5,"t":"心中勇敢的人都被掠夺；他们睡了长觉，没有一个英雄能措手。","notes":[]},{"n":6,"t":"雅各的神啊，你的斥责一发，战车和战马都沉睡了。","notes":[]},{"n":7,"t":"你，惟独你是可畏的！你的怒气一发，谁能在你面前站得住呢？","notes":[]},{"n":8,"t":"你从天上使人听判断。神起来施行审判，要救地上所有困苦的人；那时地就惧怕而静默。（细拉）","notes":[],"end":9},{"n":10,"t":"人的愤怒终必称谢你，你要以人的余怒束腰。","notes":[]},{"n":11,"t":"你们当向耶和华－你们的神许愿，还愿；在他四围的人都当拿贡物献给那可畏的主。","notes":[]},{"n":12,"t":"他要挫折王子的骄气，向地上的君王显为可畏。","notes":[]}]},"77":{"heading":"遇难时得安慰","verses":[{"n":1,"t":"我要向神发声呼求；我向神发声，他必侧耳听我。","notes":[]},{"n":2,"t":"我在患难之日寻求主，在夜间不住地举手祷告，我的心不肯受安慰。","notes":["“在夜间...祷告”：原文另译“我的手夜间不住地在他面前”。"]},{"n":3,"t":"我想念神，就烦躁不安；我沉思默想，心灵发昏。（细拉）","notes":[]},{"n":4,"t":"你使我不能闭眼；我心烦乱，甚至不能说话。","notes":[]},{"n":5,"t":"我追想古时之日，上古之年。","notes":[]},{"n":6,"t":"夜间我想起我的歌曲，我的心默想，我的灵仔细省察：","notes":["“想起我的歌曲”：七十士译本和其他古译本是“沉思”。"]},{"n":7,"t":"“难道主要永远丢弃我，不再施恩吗？","notes":[]},{"n":8,"t":"难道他的慈爱永远穷尽，他的应许世世废弃吗？","notes":[]},{"n":9,"t":"难道神忘记施恩，因发怒就止住他的怜悯吗？”（细拉）","notes":[]},{"n":10,"t":"我说，至高者右手的能力已改变，这是我的悲哀。","notes":[]},{"n":11,"t":"我要记念耶和华所做的，要记念你古时的奇事；","notes":[]},{"n":12,"t":"我要思想你所做的，默念你的作为。","notes":[]},{"n":13,"t":"神啊，你的道是神圣的；有何神明大如神呢？","notes":[]},{"n":14,"t":"你是行奇事的神，你曾在万民中彰显能力。","notes":[]},{"n":15,"t":"你曾用膀臂赎了你的子民，就是雅各和约瑟的子孙。（细拉）","notes":[]},{"n":16,"t":"神啊，众水见你，众水一见你就都惊惶，深渊也都战抖。","notes":[]},{"n":17,"t":"密云倒出水来，天空发出响声，你的箭也飞行四方。","notes":[]},{"n":18,"t":"你的雷声在旋风之中，闪电照亮世界，大地战抖震动。","notes":[]},{"n":19,"t":"你的道在海中，你的路在大水之中，你的脚踪无人知道。","notes":[]},{"n":20,"t":"你曾藉摩西和亚伦的手引导你的百姓，好像领羊群一般。","notes":[]}]},"78":{"heading":"神与他的子民","verses":[{"n":1,"t":"我的子民哪，要侧耳听我的训诲，竖起耳朵听我口中的言语。","notes":[]},{"n":2,"t":"我要开口说比喻，我要解开古时的谜语，","notes":[]},{"n":3,"t":"是我们所听见、所知道，我们的祖宗告诉我们的。","notes":[]},{"n":4,"t":"我们不要向子孙隐瞒这些事，而要将耶和华的美德和他的能力，并他所行的奇事，述说给后代听。","notes":[]},{"n":5,"t":"他在雅各中立法度，在以色列中设律法；他吩咐我们的祖宗要传给子孙，","notes":[]},{"n":6,"t":"使将要生的后代子孙可以晓得。他们也要起来告诉他们的子孙，","notes":[]},{"n":7,"t":"好让他们仰望神，不忘记神的作为，惟遵守他的命令；","notes":[]},{"n":8,"t":"不要像他们的祖宗，是顽梗悖逆、心不坚定，向神心不忠实之辈。","notes":[]},{"n":9,"t":"以法莲人带着兵器，拿着弓，临阵之日转身退后。","notes":[]},{"n":10,"t":"他们不遵守神的约，不肯照他的律法行；","notes":[]},{"n":11,"t":"又忘记他的作为和他所彰显的奇事。","notes":[]},{"n":12,"t":"他在埃及地，在琐安田，在他们祖宗眼前施行奇事。","notes":[]},{"n":13,"t":"他把海分开，使他们过去，又叫水立起如垒。","notes":[]},{"n":14,"t":"他白日用云彩，终夜用火光引导他们。","notes":[]},{"n":15,"t":"他在旷野使磐石裂开，多多地给他们水喝，如从深渊而出。","notes":[]},{"n":16,"t":"他使水从磐石涌出，叫水如江河下流。","notes":[]},{"n":17,"t":"他们却仍旧得罪他，在干旱之地悖逆至高者。","notes":[]},{"n":18,"t":"他们心中试探神，随自己所欲的求食物，","notes":[]},{"n":19,"t":"并且妄论神说：“神岂能在旷野摆设筵席吗？","notes":[]},{"n":20,"t":"他虽曾击打磐石，使水涌出，如江河泛滥；他还能赐粮食吗？还能为他的百姓预备吃的肉吗？”","notes":[]},{"n":21,"t":"所以，耶和华听见就发怒，有烈火向雅各点燃，有怒气向以色列上腾；","notes":[]},{"n":22,"t":"因为他们不信服神，不倚赖他的拯救。","notes":[]},{"n":23,"t":"然而他却吩咐天空，又敞开天上的门，","notes":[]},{"n":24,"t":"降吗哪像雨，给他们吃，将天上的粮食赐给他们。","notes":[]},{"n":25,"t":"各人就吃大能者的食物；他赐下粮食，使他们饱足。","notes":[]},{"n":26,"t":"他令东风吹在天空，用能力引来南风。","notes":[]},{"n":27,"t":"他降肉像雨，多如尘土，降飞鸟，多如海沙，","notes":[]},{"n":28,"t":"落在他自己的营中，在他帐幕的四周围。","notes":[]},{"n":29,"t":"他们吃了，而且饱足；这样就随了他们所欲的。","notes":[]},{"n":30,"t":"但在他们满足食欲以前，食物还在他们口中的时候，","notes":[]},{"n":31,"t":"神的怒气就向他们上腾，杀了他们当中肥壮的人，打倒以色列的青年。","notes":[]},{"n":32,"t":"虽是这样，他们仍旧犯罪，不信他奇妙的作为。","notes":[]},{"n":33,"t":"因此，他使他们的日子全归虚空，叫他们的年岁尽属惊恐。","notes":[]},{"n":34,"t":"他杀他们的时候，他们才求问他，回心转意，切切寻求神。","notes":[]},{"n":35,"t":"他们追念神是他们的磐石，至高的神是他们的救赎主。","notes":[]},{"n":36,"t":"他们却用口谄媚他，用舌向他说谎。","notes":[]},{"n":37,"t":"他们的心向他不坚定，不忠于他的约。","notes":[]},{"n":38,"t":"但他有怜悯，赦免他们的罪孽，没有灭绝他们，而且屡次撤销他的怒气，不发尽他的愤怒。","notes":[]},{"n":39,"t":"他想念他们不过是血肉之躯，是一阵去而不返的风。","notes":[]},{"n":40,"t":"他们在旷野悖逆他，在荒地令他担忧，何其多呢！","notes":[]},{"n":41,"t":"他们再三试探神，惹动以色列的圣者。","notes":[]},{"n":42,"t":"他们不追念他手的能力，和他救赎他们脱离敌人的日子；","notes":[]},{"n":43,"t":"他怎样在埃及显神迹，在琐安田显奇事，","notes":[]},{"n":44,"t":"把江河并河汊的水都变为血，使他们不能喝。","notes":[]},{"n":45,"t":"他使苍蝇成群落在他们当中，吃尽他们，又叫青蛙灭了他们，","notes":[]},{"n":46,"t":"将他们的果实交给蚂蚱，把他们劳碌得来的交给蝗虫。","notes":[]},{"n":47,"t":"他降冰雹打坏他们的葡萄树，下寒霜打坏他们的桑树，","notes":[]},{"n":48,"t":"将他们的牲畜交给冰雹，把他们的群畜交给闪电。","notes":[]},{"n":49,"t":"他使猛烈的怒气和愤怒、恼恨、苦难，成了一群降灾的使者，临到他们。","notes":[]},{"n":50,"t":"他为自己的怒气修平了路，将他们的性命交给瘟疫，使他们死亡，","notes":[]},{"n":51,"t":"在埃及击杀所有的长子，在含的帐棚中击杀他们壮年时头生的。","notes":[]},{"n":52,"t":"他却领出自己的子民如羊，在旷野引导他们如羊群。","notes":[]},{"n":53,"t":"他领他们稳稳妥妥地，使他们不致害怕；海却淹没他们的仇敌。","notes":[]},{"n":54,"t":"他带他们到自己圣地的边界，到他右手所得的这山地。","notes":[]},{"n":55,"t":"他在他们面前赶出外邦人，用绳子抽签量地给他们为业，让以色列支派的人住在自己的帐棚里。","notes":[]},{"n":56,"t":"他们仍旧试探，悖逆至高的神，不遵守他的法度，","notes":[]},{"n":57,"t":"反倒退后，行诡诈，像他们的祖宗一样，他们翻转，如同松弛的弓，","notes":[]},{"n":58,"t":"以丘坛惹他发怒，以雕刻的偶像使他忌恨。","notes":[]},{"n":59,"t":"神听见就发怒，全然弃绝了以色列，","notes":[]},{"n":60,"t":"甚至离弃示罗的帐幕，就是他在人间所搭的帐棚；","notes":[]},{"n":61,"t":"又将他有能力的约柜交给人掳去，将他的荣耀交在敌人手中；","notes":["“有能力的约柜”：原文是“能力”。"]},{"n":62,"t":"并将他的百姓交给刀剑，向他的产业发怒。","notes":[]},{"n":63,"t":"壮丁被火烧灭，童女也无婚礼颂歌。","notes":[]},{"n":64,"t":"祭司倒在刀下，寡妇却不哀哭。","notes":[]},{"n":65,"t":"那时，主像睡觉的人醒来，如勇士饮酒呼喊。","notes":[]},{"n":66,"t":"他击退敌人，叫他们永蒙羞辱。","notes":[]},{"n":67,"t":"他撇弃约瑟的帐棚，不拣选以法莲支派，","notes":[]},{"n":68,"t":"却拣选犹大支派，拣选他所喜爱的锡安山；","notes":[]},{"n":69,"t":"建造他的圣所如同高峰，又像他所建立的永存之地。","notes":[]},{"n":70,"t":"他拣选他的仆人大卫，从羊圈中将他召来，","notes":[]},{"n":71,"t":"叫他不再牧放那些母羊，为要牧养自己的百姓雅各和自己的产业以色列。","notes":[]},{"n":72,"t":"于是，他以纯正的心牧养他们，用巧妙的手引导他们。","notes":[]}]},"79":{"heading":"求主解救国家","verses":[{"n":1,"t":"神啊，外邦人侵犯你的产业，玷污你的圣殿，使耶路撒冷变成废墟，","notes":[]},{"n":2,"t":"将你仆人的尸首交给天空的飞鸟为食，把你圣民的肉交给地上的走兽，","notes":[]},{"n":3,"t":"耶路撒冷的周围流出他们的血如水，无人埋葬。","notes":[]},{"n":4,"t":"我们成为邻国羞辱的对象，被四围的人嗤笑讥刺。","notes":[]},{"n":5,"t":"耶和华啊，你发怒要到几时呢？要到永远吗？你的忌恨要如火焚烧吗？","notes":[]},{"n":6,"t":"求你将你的愤怒倾倒在那不认识你的万邦和那不求告你名的国度。","notes":[]},{"n":7,"t":"因为他们吞了雅各，将他的住处变为废墟。","notes":[]},{"n":8,"t":"求你不要记得我们先前世代的罪孽；愿你的怜悯速速临到我们，因为我们落到极卑微的地步。","notes":[]},{"n":9,"t":"拯救我们的神啊，求你因你名的荣耀帮助我们！为你名的缘故搭救我们，赦免我们的罪。","notes":[]},{"n":10,"t":"为何让列国说“他们的神在哪里”呢？求你让列国知道，你在我们眼前伸你仆人流血的冤。","notes":[]},{"n":11,"t":"愿被囚之人的叹息达到你面前，求你以强大的膀臂存留那些将死的人。","notes":[]},{"n":12,"t":"主啊，求你将我们邻邦所加给你的羞辱七倍归到他们身上。","notes":[]},{"n":13,"t":"这样，你的子民，你草场的羊，要称谢你，直到永远；要述说赞美你的话，直到万代。","notes":[]}]},"80":{"heading":"求主复兴国家","verses":[{"n":1,"t":"领约瑟如领羊群的以色列牧者啊，求你侧耳而听！在基路伯之上坐宝座的啊，求你发出光来！","notes":[]},{"n":2,"t":"在以法莲、便雅悯、玛拿西面前求你施展你的大能，拯救我们。","notes":[]},{"n":3,"t":"神啊，求你使我们回转，使你的脸发光，我们就会得救！","notes":["“回转”或译“复兴”；下同。"]},{"n":4,"t":"耶和华─万军之神啊，你因你百姓的祷告发怒，要到几时呢？","notes":[]},{"n":5,"t":"你以眼泪当食物给他们吃，量出满碗的眼泪给他们喝。","notes":[]},{"n":6,"t":"你使邻邦因我们纷争，我们的仇敌彼此戏笑。","notes":[]},{"n":7,"t":"万军之神啊，求你使我们回转，使你的脸发光，我们就会得救！","notes":[]},{"n":8,"t":"你从埃及拔出一棵葡萄树，赶出外邦人，把这树栽上。","notes":[]},{"n":9,"t":"你在它面前清除杂物，它就深深扎根，蔓延满地。","notes":[]},{"n":10,"t":"它的影子遮蔽群山，枝子好像高大的香柏树。","notes":[]},{"n":11,"t":"它长出枝子，直到大海，伸展嫩枝，延到大河。","notes":[]},{"n":12,"t":"你为何拆毁这树的篱笆，任凭路人摘取？","notes":[]},{"n":13,"t":"林中的野猪践踏它，田里的走兽吞吃它。","notes":[]},{"n":14,"t":"万军之神啊，求你转回，从天上垂看观察，眷顾这葡萄树；","notes":[]},{"n":15,"t":"保护你右手所栽的根，你为自己所坚固的幼苗。","notes":[]},{"n":16,"t":"这树已经被火焚烧，被刀砍伐，因你脸上的怒容就灭亡了。","notes":[]},{"n":17,"t":"愿你的手扶持你右边的人，你为自己所坚固的人子。","notes":[]},{"n":18,"t":"这样，我们就不背离你；求你救活我们，让我们得以求告你的名。","notes":[]},{"n":19,"t":"耶和华─万军之神啊，求你使我们回转，使你的脸发光，我们就会得救！","notes":[]}]},"81":{"heading":"劝戒以色列的刚愎","verses":[{"n":1,"t":"你们当向神－我们的力量大声歌唱，向雅各的神欢呼！","notes":[]},{"n":2,"t":"高唱诗歌，击打手鼓，弹奏悦耳的琴瑟。","notes":[]},{"n":3,"t":"当在新月和满月－我们过节的日期吹角，","notes":[]},{"n":4,"t":"因这是为以色列所定的律例，是雅各神的典章。","notes":[]},{"n":5,"t":"他攻击埃及地的时候，曾立此为约瑟的法度。我听见我所不明白的语言：","notes":[]},{"n":6,"t":"“我使你的肩头得脱重担，使你的手放下筐子。","notes":["本节的“你”原文是“他”。"]},{"n":7,"t":"你在急难中呼求，我就搭救你，在雷的隐密处应允你，在米利巴水那里考验你。（细拉）","notes":[]},{"n":8,"t":"听啊，我的子民，我要劝戒你；以色列啊，我真愿你肯听从我。","notes":[]},{"n":9,"t":"在你当中，不可有外族的神明；外邦的神明，你也不可下拜。","notes":[]},{"n":10,"t":"我是耶和华－你的神，曾将你从埃及地领上来；你要大大张口，我就使你满足。","notes":[]},{"n":11,"t":"“无奈，我的子民不听我的声音，以色列不肯听从我。","notes":[]},{"n":12,"t":"我就任凭他们心里顽梗，随自己的计谋而行。","notes":[]},{"n":13,"t":"我的子民若肯听从我，以色列肯行我的道，","notes":[]},{"n":14,"t":"我就速速制伏他们的仇敌，反手攻击他们的敌人。","notes":[]},{"n":15,"t":"恨耶和华的人必来投降，愿他们的厄运直到永远。","notes":[]},{"n":16,"t":"他必拿上好的麦子给以色列吃，又拿磐石出的蜂蜜使你饱足。 ”","notes":["“以色列”：原文是“他”。"]}]},"82":{"heading":"神是最高的主宰","verses":[{"n":1,"t":"神站立在神圣的会中，在诸神中施行审判。","notes":[]},{"n":2,"t":"你们审判不秉公义，抬举恶人的脸面，要到几时呢？（细拉）","notes":[]},{"n":3,"t":"当为贫寒的人和孤儿伸冤，为困苦和穷乏的人施行公义。","notes":[]},{"n":4,"t":"当保护贫寒和贫穷的人，救他们脱离恶人的手。","notes":[]},{"n":5,"t":"他们愚昧，他们无知，在黑暗中走来走去；地的根基都摇动了。","notes":[]},{"n":6,"t":"我曾说：“你们是诸神，都是至高者的儿子。","notes":[]},{"n":7,"t":"然而，你们要死去，与世人一样，要仆倒，像任何一位王子一般。”","notes":[]},{"n":8,"t":"神啊，求你起来审判全地，因为你必得万国为业。","notes":[]}]},"83":{"heading":"求主败敌","verses":[{"n":1,"t":"神啊，求你不要静默！神啊，求你不要闭口，不要不作声！","notes":[]},{"n":2,"t":"因为你的仇敌喧嚷，恨你的抬起头来。","notes":[]},{"n":3,"t":"他们同谋奸诈要害你的百姓，彼此商议要害你所保护的人。","notes":[]},{"n":4,"t":"他们说：“来吧，我们将他们除灭，使他们不再成国！使以色列的名不再被人记念！”","notes":[]},{"n":5,"t":"他们同心商议，彼此结盟，要抵挡你；","notes":[]},{"n":6,"t":"他们就是住帐棚的以东和以实玛利人，摩押和夏甲人，","notes":[]},{"n":7,"t":"迦巴勒、亚扪、亚玛力、非利士和推罗的居民。","notes":[]},{"n":8,"t":"亚述也与他们联合，作罗得子孙的帮手。（细拉）","notes":[]},{"n":9,"t":"求你待他们，如待米甸，如在基顺河待西西拉和耶宾一样。","notes":[]},{"n":10,"t":"他们在隐．多珥灭亡，成了地上的粪土。","notes":[]},{"n":11,"t":"求你使他们的贵族像俄立和西伊伯，使他们的王子都像西巴和撒慕拿。","notes":[]},{"n":12,"t":"因为他们说：“我们要得神的住处，作自己的产业。”","notes":[]},{"n":13,"t":"我的神啊，求你使他们像旋风中的尘土，如风前的碎秸。","notes":[]},{"n":14,"t":"火怎样焚烧树林，火焰怎样烧着山岭，","notes":[]},{"n":15,"t":"求你也照样用狂风追赶他们，用暴雨恐吓他们。","notes":[]},{"n":16,"t":"耶和华啊，求你使他们满面羞耻，好叫他们寻求你的名！","notes":[]},{"n":17,"t":"愿他们永远羞愧惊惶！愿他们惭愧灭亡！","notes":[]},{"n":18,"t":"愿他们认识你的名是耶和华，惟独你是掌管全地的至高者！","notes":[]}]},"84":{"heading":"渴慕耶和华的殿宇","verses":[{"n":1,"t":"万军之耶和华啊，你的居所何等可爱！","notes":[]},{"n":2,"t":"我羡慕渴想耶和华的院宇，我的内心，我的肉体向永生神欢呼。","notes":[]},{"n":3,"t":"万军之耶和华－我的王，我的神啊，在你祭坛那里，麻雀为自己找到了家，燕子为自己找着抱雏之窝。","notes":[]},{"n":4,"t":"如此住在你殿中的有福了！他们不断地赞美你。（细拉）","notes":[]},{"n":5,"t":"靠你有力量、心中向往锡安大道的，这人有福了！","notes":[]},{"n":6,"t":"他们经过“流泪谷”，叫这谷变为泉源之地；且有秋雨之福盖满了全谷。","notes":["“流泪谷”或译“干旱谷”。"]},{"n":7,"t":"他们行走，力上加力，各人到锡安朝见神。","notes":[]},{"n":8,"t":"万军之耶和华神啊，求你听我的祷告！雅各的神啊，求你侧耳而听！（细拉）","notes":[]},{"n":9,"t":"神啊，我们的盾牌，求你观看，求你垂顾你受膏者的面！","notes":[]},{"n":10,"t":"在你的院宇一日，胜似千日；宁可在我神的殿中看门，不愿住在恶人的帐棚里。","notes":[]},{"n":11,"t":"因为耶和华神是太阳，是盾牌，耶和华要赐下恩惠和荣耀。他未尝留下福气不给那些行动正直的人。","notes":[]},{"n":12,"t":"万军之耶和华啊，倚靠你的人有福了！","notes":[]}]},"85":{"heading":"为国求福","verses":[{"n":1,"t":"耶和华啊，你已经向你的地施恩，救回被掳的雅各。","notes":[]},{"n":2,"t":"你赦免了你百姓的罪孽，遮盖了他们一切的过犯。（细拉）","notes":[]},{"n":3,"t":"你收回所发的愤怒，撤销你猛烈的怒气。","notes":[]},{"n":4,"t":"拯救我们的神啊，求你使我们回转，使你向我们所发的愤怒止息。","notes":[]},{"n":5,"t":"你要向我们发怒到永远吗？要将你的怒气延留到万代吗？","notes":[]},{"n":6,"t":"你不再将我们救活，使你的百姓因你欢喜吗？","notes":[]},{"n":7,"t":"耶和华啊，求你使我们得见你的慈爱，又将你的救恩赐给我们。","notes":[]},{"n":8,"t":"我要听神－耶和华所说的话，因为他必应许赐平安给他的百姓，就是他的圣民；他们却不可再转向愚昧。","notes":["“他们...愚昧”：七十士译本是“和给那些心里归向他的人”。"]},{"n":9,"t":"他的救恩诚然与敬畏他的人相近，使荣耀住在我们的地上。","notes":[]},{"n":10,"t":"慈爱和诚实彼此相遇，公义与和平彼此相亲。","notes":[]},{"n":11,"t":"诚实从地而生，公义从天而现。","notes":[]},{"n":12,"t":"耶和华必赐福气给我们；我们的地也要出土产。","notes":[]},{"n":13,"t":"公义要行在他面前，使他的脚踪有可走之路。","notes":[]}]},"86":{"heading":"求主恩助","verses":[{"n":1,"t":"耶和华啊，求你侧耳应允我，因我是困苦贫穷的。","notes":[]},{"n":2,"t":"求你保住我的性命，因我是虔诚的人。我的神啊，求你拯救我这倚靠你的仆人！","notes":[]},{"n":3,"t":"主啊，求你怜悯我，因我终日求告你。","notes":[]},{"n":4,"t":"主啊，求你使你的仆人心里欢喜，因为我的心仰望你。","notes":[]},{"n":5,"t":"主啊，你本为良善，乐于饶恕人，以丰盛的慈爱对待凡求告你的人。","notes":[]},{"n":6,"t":"耶和华啊，求你侧耳听我的祷告，留心听我恳求的声音。","notes":[]},{"n":7,"t":"我在患难之日要求告你，因为你必应允我。","notes":[]},{"n":8,"t":"主啊，诸神之中没有可与你相比的，你的作为也无以为比。","notes":[]},{"n":9,"t":"主啊，你所造的万民都要来敬拜你，他们要荣耀你的名。","notes":[]},{"n":10,"t":"因你本为大，且行奇妙的事，惟独你是神。","notes":[]},{"n":11,"t":"耶和华啊，求你将你的道指教我，我要照你的真理而行；求你使我专心敬畏你的名！","notes":[]},{"n":12,"t":"主－我的神啊，我要一心称谢你；我要荣耀你的名，直到永远。","notes":[]},{"n":13,"t":"因为你的慈爱在我身上浩大，你救了我的性命免入阴间的深处。","notes":[]},{"n":14,"t":"神啊，骄傲的人起来攻击我，又有一群强横的人寻索我的命；他们没有将你放在眼里。","notes":[]},{"n":15,"t":"主啊，你是有怜悯，有恩惠的神，不轻易发怒，并有丰盛的慈爱和信实。","notes":[]},{"n":16,"t":"求你转向我，怜悯我，将你的力量赐给仆人，拯救你使女的儿子。","notes":[]},{"n":17,"t":"求你向我显出恩待我的凭据，使恨我的人看见就羞愧，因为你－耶和华帮助我，安慰了我。","notes":[]}]},"87":{"heading":"锡安颂","verses":[{"n":1,"t":"耶和华所立的根基在圣山上。","notes":[]},{"n":2,"t":"耶和华爱锡安的门，胜于爱雅各一切的住处。","notes":[]},{"n":3,"t":"神的城啊，有荣耀的事是指着你说的。（细拉）","notes":[]},{"n":4,"t":"我要提起拉哈伯和巴比伦人，是在认识我之中的；看哪，非利士、推罗和古实人，个个生在那里。","notes":["“拉哈伯”是神话故事中的大海怪。"]},{"n":5,"t":"论到锡安，必有话说：“这一个、那一个都生在其中”；而且至高者必亲自坚立这城。","notes":[]},{"n":6,"t":"当耶和华记录万民的时候，他要写出人的出生地。（细拉）","notes":[]},{"n":7,"t":"歌唱的、跳舞的，都要说：“我的泉源都在你里面。”","notes":["本节七十士译本是“他们都以住在你里面为乐。”"]}]},"88":{"heading":"求主眷顾","verses":[{"n":1,"t":"耶和华－拯救我的神啊，我昼夜在你面前呼求；","notes":[]},{"n":2,"t":"愿我的祷告达到你面前，求你侧耳听我的恳求！","notes":[]},{"n":3,"t":"因为我心里满了患难，我的性命临近阴间；","notes":[]},{"n":4,"t":"我与下到地府的人同列，如同无人帮助的人一样。","notes":[]},{"n":5,"t":"我被丢在死人中，好像被杀的人躺在坟墓里，不再被你记得，与你的手隔绝了。","notes":[]},{"n":6,"t":"你把我放在极深的地府里，在黑暗地，在深处。","notes":[]},{"n":7,"t":"你的愤怒重压我身，你用一切的波浪困住我。（细拉）","notes":[]},{"n":8,"t":"你把我所认识的人隔在远处，使我为他们所憎恶；我被拘禁，不能出来。","notes":[]},{"n":9,"t":"我的眼睛因困苦而昏花；耶和华啊，我天天求告你，向你举手。","notes":[]},{"n":10,"t":"你岂要行奇事给死人看吗？阴魂还能起来称谢你吗？（细拉）","notes":[]},{"n":11,"t":"你的慈爱岂能在坟墓里被人述说吗？你的信实岂能在冥府被人传扬吗？","notes":["“冥府”：原文音译“亚巴顿”，意思是“灭亡之地”。"]},{"n":12,"t":"你的奇事岂能在幽暗里为人所知吗？你的公义岂能在遗忘之地为人所识吗？","notes":[]},{"n":13,"t":"耶和华啊，至于我，我要呼求你；每早晨，我的祷告要达到你面前。","notes":[]},{"n":14,"t":"耶和华啊，你为何丢弃我？为何转脸不顾我？","notes":[]},{"n":15,"t":"我自幼受苦，几乎死亡；你使我惊恐，烦乱不安。","notes":[]},{"n":16,"t":"你的烈怒漫过我身，你用惊吓把我除灭。","notes":[]},{"n":17,"t":"这些如水终日环绕我，一起围困我。","notes":[]},{"n":18,"t":"你把我的良朋密友隔在远处，使我所认识的人都在黑暗里。","notes":["“使我...黑暗里”或译“我所知的尽是黑暗”。"]}]},"89":{"heading":"困难中的圣诗","verses":[{"n":1,"t":"我要歌唱耶和华的慈爱，直到永远，我要用口将你的信实传到万代。","notes":[]},{"n":2,"t":"因我曾说：“你的慈爱必建立到永远，你的信实必坚立在天上。”","notes":["本节七十士译本是“你说，慈爱必建立到永远，你的信实必坚立在天上。”"]},{"n":3,"t":"“我与我所拣选的人立了约，向我的仆人大卫起了誓：","notes":[]},{"n":4,"t":"‘我要坚立你的后裔，直到永远，要建立你的宝座，直到万代。’”（细拉）","notes":[]},{"n":5,"t":"耶和华啊，诸天要称谢你的奇事；在圣者的会中，要称谢你的信实。","notes":[]},{"n":6,"t":"因在天空谁能比耶和华呢？诸神之中，谁能像耶和华呢？","notes":[]},{"n":7,"t":"在圣者的会中，他是大有威严的神，比在他四围所有的更可畏惧。","notes":[]},{"n":8,"t":"耶和华－万军之神啊，哪一个大能者像耶和华？你的信实在你四围。","notes":[]},{"n":9,"t":"你管辖海的狂傲；波浪翻腾，你使它平静了。","notes":[]},{"n":10,"t":"你打碎了拉哈伯，使它如遭刺杀的人；你用大能的膀臂打散了你的仇敌。","notes":["“拉哈伯”是神话故事中的大海怪。"]},{"n":11,"t":"天属你，地也属你；世界和其中所充满的都为你所建立。","notes":[]},{"n":12,"t":"南北为你所创造；他泊和黑门都因你的名欢呼。","notes":[]},{"n":13,"t":"你有大能的膀臂，你的手有力，你的右手也高举。","notes":[]},{"n":14,"t":"公义和公平是你宝座的根基，慈爱和信实行在你前面。","notes":[]},{"n":15,"t":"知道向你欢呼的，那民有福了！耶和华啊，他们要行走在你脸的光中。","notes":[]},{"n":16,"t":"他们因你的名终日欢乐，因你的公义得以高举。","notes":[]},{"n":17,"t":"你是他们力量的荣耀。我们的角必被高举，因为你喜爱我们。","notes":[]},{"n":18,"t":"我们的盾牌是耶和华，我们的王是以色列的圣者。","notes":[]},{"n":19,"t":"当时，你在异象中吩咐你的圣民，说：“我已把救助之力加在壮士身上，高举了那从百姓中所拣选的人。","notes":[],"heads":["神对大卫的应许"]},{"n":20,"t":"我寻得我的仆人大卫，用我的圣膏膏他。","notes":[]},{"n":21,"t":"我的手必使他坚立，我的膀臂也必坚固他。","notes":[]},{"n":22,"t":"仇敌必不勒索他，凶恶之子也不苦害他。","notes":[]},{"n":23,"t":"我要在他面前打碎他的敌人，击杀那些恨他的人。","notes":[]},{"n":24,"t":"我的信实和我的慈爱要与他同在；因我的名，他的角必被高举。","notes":[]},{"n":25,"t":"我要使他的手伸到海上，右手伸到河上。","notes":[]},{"n":26,"t":"他要称呼我说：‘你是我的父，是我的神，是拯救我的磐石。’","notes":[]},{"n":27,"t":"我也要立他为长子，为世上最高的君王。","notes":[]},{"n":28,"t":"我要为他存留我的慈爱，直到永远，我与他所立的约必坚定不移。","notes":[]},{"n":29,"t":"我也要使他的后裔存到永远，使他的宝座如天之久。","notes":[]},{"n":30,"t":"“倘若他的子孙离弃我的律法，不照我的典章行，","notes":[]},{"n":31,"t":"背弃我的律例，不遵守我的诫命，","notes":[]},{"n":32,"t":"我就要用杖责罚他们的过犯，用鞭责罚他们的罪孽。","notes":[]},{"n":33,"t":"只是我不将我的慈爱全然收回，也不叫我的信实废除。","notes":[]},{"n":34,"t":"我必不毁损我的约，也不改变我口中所出的话。","notes":[]},{"n":35,"t":"我仅此一次指着自己的神圣起誓，我绝不向大卫说谎！","notes":[]},{"n":36,"t":"他的后裔要存到永远，他的宝座在我面前如太阳，","notes":[]},{"n":37,"t":"又如月亮永远坚立；天上的见证是确实的。”（细拉）","notes":[]},{"n":38,"t":"但你恼怒你的受膏者，拒绝他，离弃了他。","notes":[],"heads":["君主惨败的哀歌"]},{"n":39,"t":"你厌恶与你仆人所立的约，将他的冠冕践踏于地。","notes":[]},{"n":40,"t":"你拆毁了他一切的围墙，使他的堡垒变为废墟。","notes":[]},{"n":41,"t":"过路的人都抢夺他，他成了邻邦羞辱的对象。","notes":[]},{"n":42,"t":"你高举了他敌人的右手，使他所有的仇敌欢喜。","notes":[]},{"n":43,"t":"你叫他的刀剑卷刃，使他在战争中站立不住。","notes":[]},{"n":44,"t":"你使他的光辉止息，将他的宝座推倒于地。","notes":[]},{"n":45,"t":"你减少他年轻的日子，又使他蒙羞。（细拉）","notes":[]},{"n":46,"t":"耶和华啊，这要到几时呢？你要隐藏自己到永远吗？你的愤怒如火焚烧要到几时呢？","notes":[],"heads":["求救的祷告"]},{"n":47,"t":"求你想念我的生命是何等短暂。你创造世人，要使他们归于何等的虚空呢？","notes":[]},{"n":48,"t":"谁能常活不见死亡、救自己脱离阴间的掌控呢？（细拉）","notes":[]},{"n":49,"t":"主啊，你从前凭你的信实向大卫起誓要施行的慈爱在哪里呢？","notes":[]},{"n":50,"t":"主啊，求你记念仆人们所受的羞辱，记念我怎样将万族所加的羞辱都放在我的胸怀。","notes":[]},{"n":51,"t":"耶和华啊，这是你仇敌所加的羞辱，羞辱了你受膏者的脚踪。","notes":[]},{"n":52,"t":"耶和华是应当称颂的，直到永远。阿们！阿们！","notes":[]}]},"90":{"heading":"神与人","verses":[{"n":1,"t":"主啊，你世世代代作我们的居所。","notes":[]},{"n":2,"t":"诸山未曾生出，地与世界你未曾造成，从亘古到永远，你是神。","notes":[]},{"n":3,"t":"你使人归于尘土，说：“世人哪，你们要归回。”","notes":[]},{"n":4,"t":"在你看来，千年如已过的昨日，又如夜间的一更。","notes":[]},{"n":5,"t":"你叫他们如水冲去，他们如睡一觉。早晨，他们如生长的草；","notes":[]},{"n":6,"t":"早晨发芽生长，晚上割下枯干。","notes":[]},{"n":7,"t":"我们因你的怒气而消灭，因你的愤怒而惊惶。","notes":[]},{"n":8,"t":"你将我们的罪孽摆在你面前，将我们的隐恶摆在你面光之中。","notes":[]},{"n":9,"t":"我们经过的日子，都在你震怒之下，我们度尽的年岁，好像一声叹息。","notes":[]},{"n":10,"t":"我们一生的年日是七十岁，若是强壮可到八十岁；但其中所矜夸的不过是劳苦愁烦，转眼即逝，我们便如飞而去。","notes":[]},{"n":11,"t":"谁晓得你怒气的权势？谁因着敬畏你而晓得你的愤怒呢？","notes":[]},{"n":12,"t":"求你指教我们怎样数算自己的日子，好叫我们得着智慧的心。","notes":[]},{"n":13,"t":"耶和华啊，我们要等到几时呢？求你转回，怜悯你的仆人们。","notes":[]},{"n":14,"t":"求你使我们早早饱得你的慈爱，好叫我们一生一世欢呼喜乐。","notes":[]},{"n":15,"t":"求你照着你使我们受苦的日子，和我们遭难的年岁，使我们喜乐。","notes":[]},{"n":16,"t":"愿你的作为向你仆人们显现，愿你的荣耀向他们子孙显明。","notes":[]},{"n":17,"t":"愿主－我们神的恩宠归于我们身上。愿你坚立我们手所做的工，我们手所做的工，愿你坚立。","notes":[]}]},"91":{"heading":"神是我们的保护者","verses":[{"n":1,"t":"住在至高者隐密处的，必住在全能者的荫下。","notes":[]},{"n":2,"t":"我要向耶和华说：“我的避难所、我的山寨、我的神，你是我所倚靠的。”","notes":[]},{"n":3,"t":"他必救你脱离捕鸟者的罗网和毁灭人的瘟疫。","notes":[]},{"n":4,"t":"他必用自己的翎毛遮蔽你；你要投靠在他翅膀底下，他的信实是大小的盾牌。","notes":[]},{"n":5,"t":"你必不怕黑夜的惊骇，或是白日飞的箭，","notes":[]},{"n":6,"t":"也不怕黑夜流行的瘟疫，或是午间灭人的灾害。","notes":[]},{"n":7,"t":"虽有千人仆倒在你旁边，万人仆倒在你右边，这灾却不得临近你。","notes":[]},{"n":8,"t":"你惟亲眼观看，见恶人遭报。","notes":[]},{"n":9,"t":"因为耶和华是我的避难所，你以至高者为居所，","notes":[]},{"n":10,"t":"祸患必不临到你，灾害也不挨近你的帐棚。","notes":[]},{"n":11,"t":"因他要为你命令他的使者，在你所行的一切道路上保护你。","notes":[]},{"n":12,"t":"他们要用手托住你，免得你的脚碰在石头上。","notes":[]},{"n":13,"t":"你要踹踏狮子和毒蛇，践踏少壮狮子和大蛇。","notes":[]},{"n":14,"t":"“因为他专心爱我，我要搭救他；因为他认识我的名，我要把他安置在高处。","notes":[]},{"n":15,"t":"他若求告我，我就应允他；他在急难中，我与他同在；我要搭救他，使他尊贵。","notes":[]},{"n":16,"t":"我要使他享足长寿，将我的救恩显明给他。”","notes":[]}]},"92":{"heading":"颂赞之诗","verses":[{"n":1,"t":"这是多么好啊！称谢耶和华，歌颂你至高者的名，","notes":[]},{"n":2,"t":"早晨传扬你的慈爱，每夜传扬你的信实。","notes":[]},{"n":3,"t":"用十弦的乐器和瑟，用琴优雅的声音；","notes":[]},{"n":4,"t":"因你－耶和华藉着你的作为使我高兴，我要因你手的工作欢呼。","notes":[]},{"n":5,"t":"耶和华啊，你的工作何其大！你的心思极其深！","notes":[]},{"n":6,"t":"畜牲一般的人不晓得，愚昧人也不明白。","notes":[]},{"n":7,"t":"恶人虽茂盛如草，作恶的人虽全都兴旺，他们却要灭亡，直到永远。","notes":[]},{"n":8,"t":"耶和华啊，惟有你是至高，直到永远。","notes":[]},{"n":9,"t":"耶和华啊，看哪，你的仇敌，看哪，你的仇敌都要灭亡；作恶的全都要离散。","notes":[]},{"n":10,"t":"你却高举了我的角，如野牛的角；我是被新油膏抹的。","notes":[]},{"n":11,"t":"我的眼睛看见我的仇敌遭报，我的耳朵听见那些起来攻击我的恶人受罚。","notes":[]},{"n":12,"t":"义人要兴旺如棕树，生长如黎巴嫩的香柏树。","notes":[]},{"n":13,"t":"他们栽于耶和华的殿中，发旺在我们神的院里。","notes":[]},{"n":14,"t":"他们发白的时候仍结果子，而且鲜美多汁，","notes":[]},{"n":15,"t":"好显明耶和华是正直的；他是我的磐石，在他毫无不义。","notes":[]}]},"93":{"heading":"神是王","verses":[{"n":1,"t":"耶和华作王！他以威严为衣穿上；耶和华以能力为衣，以能力束腰，世界就坚定，不得动摇。","notes":[]},{"n":2,"t":"你的宝座从太初立定，你从亘古就有。","notes":[]},{"n":3,"t":"耶和华啊，大水扬起，大水发声，大水澎湃。","notes":[]},{"n":4,"t":"耶和华在高处大有威力，胜过诸水的响声，洋海的大浪。","notes":[]},{"n":5,"t":"耶和华啊，你的法度最为确定；你的殿宜称为圣，直到永远。","notes":[]}]},"94":{"heading":"神审判万人","verses":[{"n":1,"t":"耶和华啊，你是伸冤的神；伸冤的神啊，求你发出光来！","notes":[]},{"n":2,"t":"审判世界的主啊，求你挺身而立，使骄傲的人受应得的报应！","notes":[]},{"n":3,"t":"耶和华啊，恶人夸胜要到几时呢？要到几时呢？","notes":[]},{"n":4,"t":"他们咆哮，说狂妄的话，作恶的人全都夸耀自己。","notes":[]},{"n":5,"t":"耶和华啊，他们强压你的百姓，苦害你的产业。","notes":[]},{"n":6,"t":"他们杀死寡妇和寄居的人，又杀害孤儿。","notes":[]},{"n":7,"t":"他们说：“耶和华必不看见，雅各的神必不留意。”","notes":[]},{"n":8,"t":"百姓中像畜牲一般的人当思想，你们愚昧人要到几时才有智慧呢？","notes":[]},{"n":9,"t":"造耳朵的，难道自己听不见吗？造眼睛的，难道自己看不见吗？","notes":[]},{"n":10,"t":"管教列国的，就是叫人得知识的，难道自己不惩治人吗？","notes":[]},{"n":11,"t":"耶和华知道人的意念是虚妄的。","notes":[]},{"n":12,"t":"耶和华啊，你所管教、用律法教导的人有福了！","notes":[]},{"n":13,"t":"你使他在遭难的日子仍得平安，直到为恶人挖好了坑。","notes":[]},{"n":14,"t":"因为耶和华必不丢弃他的百姓，也不离弃他的产业。","notes":[]},{"n":15,"t":"审判要回复公义，心里正直的，都必跟随它。","notes":[]},{"n":16,"t":"谁肯为我起来攻击邪恶的？谁肯为我站起抵挡作恶的？","notes":[]},{"n":17,"t":"若不是耶和华帮助我，我早就住在寂静之中了。","notes":["“寂静”就是“死亡”。"]},{"n":18,"t":"我若说：“我失了脚！”耶和华啊，你的慈爱必扶持我。","notes":[]},{"n":19,"t":"我心里多忧多疑，你的安慰使我欢乐。","notes":[]},{"n":20,"t":"那藉着律例玩弄奸恶、以权位肆行残害的，岂能与你交往呢？","notes":[]},{"n":21,"t":"他们大家聚集攻击义人，将无辜的人定了死罪。","notes":[]},{"n":22,"t":"但耶和华向来作我的碉堡，我的神作了我投靠的磐石。","notes":[]},{"n":23,"t":"他叫他们的罪孽归到自己身上，要因他们的邪恶剪除他们；耶和华－我们的神要把他们剪除。","notes":[]}]},"95":{"heading":"颂赞之诗","verses":[{"n":1,"t":"来啊，我们要向耶和华歌唱，向拯救我们的磐石欢呼！","notes":[]},{"n":2,"t":"我们要以感谢来到他面前，用诗歌向他欢呼！","notes":[]},{"n":3,"t":"因耶和华是伟大的神，是超越万神的大君王。","notes":[]},{"n":4,"t":"地的深处在他手中；山的高峰也属他。","notes":[]},{"n":5,"t":"海洋属他，是他造的；旱地也是他手造成的。","notes":[]},{"n":6,"t":"来啊，我们要俯伏敬拜，在造我们的耶和华面前跪拜。","notes":[]},{"n":7,"t":"因为他是我们的神；我们是他草场的百姓，是他手中的羊。惟愿你们今天听他的话！","notes":[]},{"n":8,"t":"你们不可硬着心，像在米利巴，就是在旷野玛撒的日子。","notes":[]},{"n":9,"t":"那时，你们的祖宗试我，探我，并且观看我的作为。","notes":[]},{"n":10,"t":"四十年之久，我厌烦那世代，说：“这是心里迷糊的百姓，竟不知道我的道路！”","notes":[]},{"n":11,"t":"所以，我在怒中起誓：“他们断不可进入我的安息！”","notes":[]}]},"96":{"heading":"神是最高的君王","verses":[{"n":1,"t":"你们要向耶和华唱新歌！全地都要向耶和华歌唱！","notes":[]},{"n":2,"t":"要向耶和华歌唱，称颂他的名！天天传扬他的救恩！","notes":[]},{"n":3,"t":"在列国中述说他的荣耀！在万民中述说他的奇事！","notes":[]},{"n":4,"t":"因耶和华本为大，当受极大的赞美；他在万神之上，当受敬畏。","notes":[]},{"n":5,"t":"因万民的神明都属虚无；惟独耶和华创造诸天。","notes":[]},{"n":6,"t":"有尊荣和威严在他面前，有能力与华美在他圣所。","notes":[]},{"n":7,"t":"民中的万族啊，要将荣耀、能力归给耶和华，都归给耶和华！","notes":[]},{"n":8,"t":"要将耶和华的名所当得的荣耀归给他，拿供物来进入他的院宇。","notes":[]},{"n":9,"t":"当敬拜神圣荣耀的耶和华，全地都要在他面前战抖！","notes":["“当敬拜...耶和华”或译“当以圣洁的妆饰敬拜耶和华”。"]},{"n":10,"t":"要在列国中说：“耶和华作王了！世界坚定，不得动摇；他要按公正审判万民。”","notes":[]},{"n":11,"t":"愿天欢喜，愿地快乐！愿海和其中所充满的澎湃！","notes":[]},{"n":12,"t":"愿田和其中所有的都欢乐！那时，林中的树木都要在耶和华面前欢呼。","notes":[]},{"n":13,"t":"因为他来了，他来要审判全地。他要按公义审判世界，按信实审判万民。","notes":[]}]},"97":{"heading":"神是最高的统治者","verses":[{"n":1,"t":"耶和华作王！愿地快乐！愿众海岛欢喜！","notes":[]},{"n":2,"t":"密云和幽暗在他四围，公义和公平是他宝座的根基。","notes":[]},{"n":3,"t":"烈火在他前头行，烧灭他四围的敌人。","notes":[]},{"n":4,"t":"他的闪电光照世界，大地看见就震动。","notes":[]},{"n":5,"t":"诸山见耶和华的面，就是全地之主的面，就如蜡熔化。","notes":[]},{"n":6,"t":"诸天表明他的公义，万民看见他的荣耀。","notes":[]},{"n":7,"t":"愿所有事奉雕刻偶像、靠虚无神明自夸的，都蒙羞愧。万神哪，你们都当拜他。","notes":[]},{"n":8,"t":"耶和华啊，因你的判断，锡安听见就欢喜；犹大的城镇也都快乐。","notes":["“犹大的城镇”：原文直译“犹大众女子”。"]},{"n":9,"t":"因为你－耶和华至高，超乎全地；受尊崇，远超万神之上。","notes":[]},{"n":10,"t":"你们爱耶和华的，都当恨恶罪恶；他保护圣民的性命，搭救他们脱离恶人的手。","notes":[]},{"n":11,"t":"散播亮光是为义人，喜乐归于心里正直的人。","notes":["“散播亮光是为义人”：有古卷、七十士译本和其他古译本是“有亮光照耀着义人”。"]},{"n":12,"t":"义人哪，你们当靠耶和华欢喜，当颂扬他神圣的名字。","notes":["“名字”：原文是“纪念”。"]}]},"98":{"heading":"神掌管世界","verses":[{"n":1,"t":"你们要向耶和华唱新歌！因为他行过奇妙的事，他的右手和圣臂施行救恩。","notes":[]},{"n":2,"t":"耶和华显明了他的救恩，在列国眼前显出公义；","notes":[]},{"n":3,"t":"记念他对以色列家的慈爱和信实。地的四极都看见我们神的救恩。","notes":[]},{"n":4,"t":"全地都要向耶和华欢呼，要扬声，欢唱，歌颂！","notes":[]},{"n":5,"t":"用琴歌颂耶和华，用琴和诗歌的声音歌颂他！","notes":[]},{"n":6,"t":"用号筒和角声，在大君王耶和华面前欢呼！","notes":[]},{"n":7,"t":"愿海和其中所充满的澎湃，愿世界和住在其间的发声。","notes":[]},{"n":8,"t":"愿大水拍掌，愿诸山在耶和华面前一同欢呼；","notes":[]},{"n":9,"t":"因为他来要审判全地。他要按公义审判世界，按公正审判万民。","notes":[]}]},"99":{"heading":"神是至高之王","verses":[{"n":1,"t":"耶和华作王，万民当战抖！他坐在基路伯的宝座上，地当动摇。","notes":[]},{"n":2,"t":"耶和华在锡安为大，他超越万民之上。","notes":[]},{"n":3,"t":"愿他们颂扬他大而可畏的名，他本为圣！","notes":[]},{"n":4,"t":"喜爱公平、大能的王啊，你坚立公正，在雅各中施行公平和公义。","notes":[]},{"n":5,"t":"当尊崇耶和华－我们的神，在他脚凳前下拜。他本为圣！","notes":[]},{"n":6,"t":"在他的祭司中有摩西和亚伦，在求告他名的人中有撒母耳。他们求告耶和华，他就应允他们。","notes":[]},{"n":7,"t":"他在云柱中向他们说话，他们遵守他的法度和他所赐给他们的律例。","notes":[]},{"n":8,"t":"耶和华－我们的神啊，你应允了他们；你是赦免他们的神，却按他们所做的报应他们。","notes":[]},{"n":9,"t":"当尊崇耶和华－我们的神，在他的圣山下拜，因为耶和华－我们的神本为圣！","notes":[]}]},"100":{"heading":"颂赞之诗","verses":[{"n":1,"t":"普天下当向耶和华欢呼！","notes":[]},{"n":2,"t":"当乐意事奉耶和华，当欢唱来到他面前！","notes":[]},{"n":3,"t":"当认识耶和华是神！我们是他造的，也是属他的；我们是他的民，是他草场的羊。","notes":[]},{"n":4,"t":"当称谢进入他的门，当赞美进入他的院。当感谢他，称颂他的名！","notes":[]},{"n":5,"t":"因为耶和华本为善；他的慈爱存到永远，他的信实直到万代。","notes":[]}]},"101":{"heading":"王的诺言","verses":[{"n":1,"t":"我要歌唱慈爱和公平，耶和华啊，我要向你歌颂！","notes":[]},{"n":2,"t":"我要用智慧行完全的道。你几时到我这里来呢？我要以纯正的心行在我家中。","notes":[]},{"n":3,"t":"邪僻的事，我都不摆在我眼前；悖逆的人所做的事，我甚恨恶，不容沾在我身上。","notes":[]},{"n":4,"t":"歪曲的心思，我必远离；邪恶的事情，我不知道。","notes":[]},{"n":5,"t":"暗中谗害他邻居的，我必将他灭绝；眼目高傲、心里骄纵的，我必不容忍。","notes":[]},{"n":6,"t":"我眼要看顾地上诚实可靠的人，使他们与我同住；行正直路的，他要侍候我。","notes":[]},{"n":7,"t":"行诡诈的，必不得住在我家里；说谎言的，必不得立在我眼前。","notes":[]},{"n":8,"t":"我每日早晨要灭绝地上所有的恶人，把作恶的从耶和华的城里全都剪除。","notes":[]}]},"102":{"heading":"遭难中的祈祷","verses":[{"n":1,"t":"耶和华啊，求你听我的祷告，愿我的呼求达到你面前！","notes":[]},{"n":2,"t":"我急难的日子，求你不要转脸不顾我！我呼求的日子，求你向我侧耳，快快应允我！","notes":[]},{"n":3,"t":"因为我的年日在烟中消失，我的骨头如火把烧着。","notes":["“在烟中消失”：有古卷、七十士译本和其他古译本是“如烟消灭”。"]},{"n":4,"t":"我的心如草被踩碎而枯干，甚至我忘记吃饭。","notes":[]},{"n":5,"t":"因我叹息的声音，我的肉紧贴骨头。","notes":[]},{"n":6,"t":"我如同旷野的鹈鹕，好像荒地的猫头鹰。","notes":[]},{"n":7,"t":"我清醒难以入眠，如同房顶上孤单的麻雀。","notes":[]},{"n":8,"t":"我的仇敌整日辱骂我，向我叫号的人指着我赌咒。","notes":[]},{"n":9,"t":"我吃灰烬如同吃饭，我喝的有眼泪搀杂。","notes":[]},{"n":10,"t":"这都因你的恼恨和愤怒，你把我举起，又把我摔下。","notes":[]},{"n":11,"t":"我的年日如夕阳，我也如草枯干。","notes":[]},{"n":12,"t":"惟你－耶和华必永远坐在宝座上，你的名存到万代。","notes":["“名”：原文是“纪念”。"]},{"n":13,"t":"你必起来怜悯锡安；因现在是可怜它的时候，因所定的日期已经到了。","notes":[]},{"n":14,"t":"你的仆人们喜爱锡安的石头，怜悯它的尘土。","notes":[]},{"n":15,"t":"列国要敬畏耶和华的名，地上众王都要敬畏你的荣耀。","notes":[]},{"n":16,"t":"因为耶和华建造了锡安，在他的荣耀里显现。","notes":[]},{"n":17,"t":"他垂听穷乏人的祷告，不藐视他们的祈求。","notes":[]},{"n":18,"t":"这必为后代的人记下，将来受造的百姓要赞美耶和华。","notes":[]},{"n":19,"t":"因为他从至高的圣所垂看；耶和华从天向地观看，","notes":[]},{"n":20,"t":"要垂听被囚之人的叹息，要释放将死的人，","notes":[]},{"n":21,"t":"使人在锡安传扬耶和华的名，在耶路撒冷传扬赞美他的话，","notes":[]},{"n":22,"t":"就是在万民和列国聚集事奉耶和华的时候。","notes":[]},{"n":23,"t":"他使我的力量半途衰弱，使我的年日短少。","notes":[]},{"n":24,"t":"我说：“我的神啊，不要使我中年去世。你的年数世世无穷！”","notes":[]},{"n":25,"t":"你起初立了地的根基，天也是你手所造的。","notes":[]},{"n":26,"t":"天地都会消灭，你却长存；天地都会像外衣渐渐旧了。你要将天地如内衣更换，天地就都改变了。","notes":[]},{"n":27,"t":"惟有你永不改变，你的年数没有穷尽。","notes":[]},{"n":28,"t":"你仆人的子孙要安然居住，他们的后裔要坚立在你面前。","notes":[]}]},"103":{"heading":"耶和华的慈爱","verses":[{"n":1,"t":"我的心哪，你要称颂耶和华！凡在我里面的，都要称颂他的圣名！","notes":[]},{"n":2,"t":"我的心哪，你要称颂耶和华！不可忘记他一切的恩惠！","notes":[]},{"n":3,"t":"他赦免你一切的罪孽，医治你一切的疾病。","notes":[]},{"n":4,"t":"他救赎你的命脱离地府，以仁爱和怜悯为你的冠冕。","notes":[]},{"n":5,"t":"他用美物使你的生命得以满足，以致你如鹰返老还童。","notes":["“你的生命”：七十士译本是“你所愿的”。"]},{"n":6,"t":"耶和华施行公义，为所有受欺压的人伸冤。","notes":[]},{"n":7,"t":"他使摩西知道他的法则，使以色列人晓得他的作为。","notes":[]},{"n":8,"t":"耶和华有怜悯，有恩惠，不轻易发怒，且有丰盛的慈爱。","notes":[]},{"n":9,"t":"他不长久责备，也不永远怀怒。","notes":[]},{"n":10,"t":"他没有按我们的罪待我们，也没有照我们的罪孽报应我们。","notes":[]},{"n":11,"t":"天离地何等的高，他的慈爱向敬畏他的人也是何等的大！","notes":[]},{"n":12,"t":"东离西有多远，他叫我们的过犯离我们也有多远！","notes":[]},{"n":13,"t":"父亲怎样怜悯他的儿女，耶和华也怎样怜悯敬畏他的人！","notes":[]},{"n":14,"t":"因为他知道我们的本体，思念我们不过是尘土。","notes":[]},{"n":15,"t":"至于世人，他的年日如草一样。他兴旺如野地的花，","notes":[]},{"n":16,"t":"经风一吹，就归无有，它的原处也不再认识它。","notes":[]},{"n":17,"t":"但耶和华的慈爱归于敬畏他的人，从亘古到永远；他的公义也归于子子孙孙，","notes":[]},{"n":18,"t":"就是那些遵守他的约、记念他的训词而遵行的人。","notes":[]},{"n":19,"t":"耶和华在天上立定宝座，他的国统管万有。","notes":[]},{"n":20,"t":"听从他命令、成全他旨意、有大能的天使啊，你们都要称颂耶和华！","notes":[]},{"n":21,"t":"你们行他所喜悦的，作他诸军，作他仆役的啊，都要称颂耶和华！","notes":[]},{"n":22,"t":"你们一切被他造的，在他所治理的各处，都要称颂耶和华！我的心哪，你要称颂耶和华！","notes":[]}]},"104":{"heading":"造化主颂","verses":[{"n":1,"t":"我的心哪，你要称颂耶和华！耶和华－我的神啊，你为至大！你以尊荣威严为衣，","notes":[]},{"n":2,"t":"披上亮光，如披外袍，铺张穹苍，如铺幔子，","notes":[]},{"n":3,"t":"在水中立楼阁的栋梁，用云彩为车辇，藉着风的翅膀而行，","notes":[]},{"n":4,"t":"以风为使者，以火焰为仆役，","notes":[]},{"n":5,"t":"将地立在根基上，使地永不动摇。","notes":[]},{"n":6,"t":"你用深水遮盖地面，犹如衣裳；诸水高过山岭。","notes":[]},{"n":7,"t":"你的斥责一发，水就奔逃；你的雷声一发，水就奔流。","notes":[]},{"n":8,"t":"诸山上升，诸谷下沉，归你为它所立定之地。","notes":[]},{"n":9,"t":"你定了界限，使水不能超越，不再转回淹没大地。","notes":[]},{"n":10,"t":"耶和华使泉源涌在山谷，流在山间，","notes":[]},{"n":11,"t":"使野地的走兽有水喝，野驴得解其渴。","notes":[]},{"n":12,"t":"天上的飞鸟在水旁住宿，在枝干间啼叫。","notes":[]},{"n":13,"t":"他从楼阁中浇灌山岭；因他作为的功效，地就丰足。","notes":[]},{"n":14,"t":"他使草生长，给牲畜吃，使菜蔬生长，供给人用，使人从地里得食物，","notes":["“使菜蔬...用”或译“使人耕种而长菜蔬”。"]},{"n":15,"t":"得酒能悦人心，得油能润人面，得粮能养人心。","notes":[]},{"n":16,"t":"佳美的树木，就是耶和华所栽种的黎巴嫩的香柏树，都满了汁浆。","notes":[]},{"n":17,"t":"雀鸟在其上搭窝，鹳以松树为家。","notes":["“松树”：原文另译“树顶”。"]},{"n":18,"t":"高山为野山羊的居所，岩石为石獾的藏身处。","notes":[]},{"n":19,"t":"你安置月亮以定季节，太阳自知沉落。","notes":[]},{"n":20,"t":"你造黑暗为夜，林中的百兽就都爬出来。","notes":[]},{"n":21,"t":"少壮狮子吼叫觅食，向神寻求食物。","notes":[]},{"n":22,"t":"太阳一出，兽就躲避，躺卧在洞里。","notes":[]},{"n":23,"t":"人出去做工，劳碌直到晚上。","notes":[]},{"n":24,"t":"耶和华啊，你所造的何其多！都是你用智慧造成的，全地遍满了你所造之物。","notes":[]},{"n":25,"t":"那里有海，又大又广，其中有无数的动物，大小活物都有。","notes":[]},{"n":26,"t":"那里有船行走，有你所造的力威亚探悠游在其中。","notes":["“力威亚探”是音译，一种海兽。"]},{"n":27,"t":"这些都仰望你按时给它们食物。","notes":[]},{"n":28,"t":"你给它们，它们就拾起来；你张手，它们就饱得美食。","notes":[]},{"n":29,"t":"你转脸，它们就惊惶；你收回它们的气，它们就死亡，归于尘土。","notes":[]},{"n":30,"t":"你差遣你的灵，它们就受造；你使地面更换为新。","notes":[]},{"n":31,"t":"愿耶和华的荣耀存到永远！愿耶和华喜爱自己所造的！","notes":[]},{"n":32,"t":"他看地，地便震动；他摸山，山就冒烟。","notes":[]},{"n":33,"t":"我一生要向耶和华唱诗！我还活的时候，要向我的神歌颂！","notes":[]},{"n":34,"t":"愿他悦纳我的默念！我要因耶和华欢喜！","notes":[]},{"n":35,"t":"愿罪人从世上消灭！愿恶人归于无有！我的心哪，你要称颂耶和华！哈利路亚！","notes":["“哈利路亚”意思是“你们要赞美耶和华”；下同。"]}]},"105":{"heading":"神和他的子民","verses":[{"n":1,"t":"你们要称谢耶和华，求告他的名，在万民中传扬他的作为！","notes":[]},{"n":2,"t":"要向他唱诗，向他歌颂，述说他一切奇妙的作为！","notes":[]},{"n":3,"t":"要夸耀他的圣名！愿寻求耶和华的人心中欢喜！","notes":[]},{"n":4,"t":"要寻求耶和华与他的能力，时常寻求他的面。","notes":[]},{"n":5,"t":"他仆人亚伯拉罕的后裔，他所拣选雅各的子孙哪，要记念他奇妙的作为和他的奇事，并他口中的判语。","notes":[],"end":6},{"n":7,"t":"他是耶和华－我们的神，全地都有他的判断。","notes":[]},{"n":8,"t":"他记念他的约，直到永远；记念他吩咐的话，直到千代，","notes":[]},{"n":9,"t":"就是与亚伯拉罕所立的约，向以撒所起的誓。","notes":[]},{"n":10,"t":"他将这约向雅各定为律例，向以色列定为永远的约，","notes":[]},{"n":11,"t":"说：“我必将迦南地赐给你，作你们应得的产业。”","notes":[]},{"n":12,"t":"当时，他们人丁有限，数目稀少，在那地寄居。","notes":[]},{"n":13,"t":"他们从这邦游到那邦，从这国去到另一民族。","notes":[]},{"n":14,"t":"他不容人欺负他们，为他们的缘故责备君王：","notes":[]},{"n":15,"t":"“不可伤害我的受膏者，也不可恶待我的先知。”","notes":[]},{"n":16,"t":"他命饥荒降在那地，断绝日用的粮食，","notes":["“粮食”：原文直译“粮食的杖”。"]},{"n":17,"t":"在他们以先差遣一个人前往，约瑟被卖为奴。","notes":[]},{"n":18,"t":"人用脚镣伤他的脚，他被铁的项链捆锁。","notes":[]},{"n":19,"t":"耶和华的话试炼他，直等所说的应验了。","notes":[]},{"n":20,"t":"王差人将他解开，治理万民的把他释放，","notes":[]},{"n":21,"t":"立他为王家之主，掌管他一切所有的，","notes":[]},{"n":22,"t":"使他随意捆绑他的臣宰，将智慧教导他的长老。","notes":[]},{"n":23,"t":"以色列也到了埃及，雅各在含地寄居。","notes":[]},{"n":24,"t":"耶和华使他的百姓生养众多，使他们比敌人强盛，","notes":[]},{"n":25,"t":"他使敌人的心转去恨他的百姓，用诡计待他的仆人。","notes":[]},{"n":26,"t":"他差遣他的仆人摩西和他所拣选的亚伦，","notes":[]},{"n":27,"t":"在敌人中间显他的神迹，在含地显他的奇事。","notes":[]},{"n":28,"t":"他差遣黑暗，就有黑暗；他们没有违背他的话。","notes":[]},{"n":29,"t":"他使埃及的水变为血，令他们的鱼死了。","notes":[]},{"n":30,"t":"在他们的地上，青蛙多多滋生，王宫的内室也是如此。","notes":[]},{"n":31,"t":"他一吩咐，苍蝇就成群飞来，并有蚊子进入他们四境。","notes":[]},{"n":32,"t":"他给他们降下冰雹为雨，在他们的地上降下火焰。","notes":[]},{"n":33,"t":"他击打他们的葡萄树和无花果树，毁坏他们境内的树木。","notes":[]},{"n":34,"t":"他一吩咐，就有蝗虫蝻子上来，不计其数，","notes":[]},{"n":35,"t":"吃光他们地上各样的菜蔬，吞尽他们田地的出产。","notes":[]},{"n":36,"t":"他又击杀他们国内所有的长子，就是他们强壮时头生的。","notes":["“他们国内”：有古卷是“埃及”。"]},{"n":37,"t":"他却带领自己的百姓带着金子银子出来，他支派中没有一个走不动的。","notes":[]},{"n":38,"t":"他们出来的时候，埃及人就欢喜；因为埃及人惧怕他们。","notes":[]},{"n":39,"t":"他铺张云彩当遮蔽，夜间使火光照。","notes":[]},{"n":40,"t":"他们祈求，他就使鹌鹑飞来，并用天上的粮食使他们饱足。","notes":[]},{"n":41,"t":"他敲开磐石，水就涌出；在干旱之处，水流成河。","notes":[]},{"n":42,"t":"这都因他记念他的圣言和他的仆人亚伯拉罕。","notes":[]},{"n":43,"t":"他带领自己的百姓欢乐而出，带领自己的选民欢呼前往。","notes":[]},{"n":44,"t":"他把列国的地赐给他们，他们就承受万民劳碌得来的，","notes":[]},{"n":45,"t":"好让他们遵他的律例，守他的律法。哈利路亚！","notes":[]}]},"106":{"heading":"神对他子民的良善","verses":[{"n":1,"t":"哈利路亚！你们要称谢耶和华，因他本为善，他的慈爱永远长存！","notes":[]},{"n":2,"t":"谁能传扬耶和华的大能？谁能表明他一切的美德？","notes":[]},{"n":3,"t":"凡遵守公平、常行公义的，这人有福了！","notes":[]},{"n":4,"t":"耶和华啊，你恩待你百姓的时候，求你记念我；你拯救他们的时候，求你眷顾我，","notes":[]},{"n":5,"t":"好使我经历你选民的福分，享受你国民的喜乐，与你的产业一同夸耀。","notes":[]},{"n":6,"t":"我们与我们的祖宗一同犯罪，偏邪行恶。","notes":[]},{"n":7,"t":"我们的祖宗在埃及不明白你的奇事，不记念你丰盛的慈爱，反倒在红海行了悖逆。","notes":["“红海”是根据七十士译本，原文是“芦苇海”；本卷书下同。"]},{"n":8,"t":"然而，他因自己的名拯救他们，为要彰显他的大能。","notes":[]},{"n":9,"t":"他斥责红海，海就干了，带领他们走过深海，如走旷野。","notes":[]},{"n":10,"t":"他拯救他们脱离恨他们之人的手，从仇敌手中救赎他们。","notes":[]},{"n":11,"t":"水淹没他们的敌人，没有一个存留。","notes":[]},{"n":12,"t":"那时，他们才信他的话，歌唱赞美他。","notes":[]},{"n":13,"t":"很快地，他们就忘了他的作为，不仰望他的指引，","notes":[]},{"n":14,"t":"反倒在旷野起了贪婪之心，在荒地试探神。","notes":[]},{"n":15,"t":"他将他们所求的赐给他们，却使他们心灵软弱。","notes":[]},{"n":16,"t":"他们在营中嫉妒摩西和耶和华的圣者亚伦。","notes":[]},{"n":17,"t":"地就裂开，吞下大坍，掩盖亚比兰一伙的人。","notes":[]},{"n":18,"t":"有火在他们党中点燃，有火焰烧毁了恶人。","notes":[]},{"n":19,"t":"他们在何烈山造了牛犊，叩拜铸成的像，","notes":[]},{"n":20,"t":"将他们荣耀的主换为吃草之牛的像，","notes":[]},{"n":21,"t":"忘了神－他们的救主，就是曾在埃及行大事，","notes":[]},{"n":22,"t":"在含地行奇事，在红海行可畏之事的那位。","notes":[]},{"n":23,"t":"因此，他说要灭绝他们；若非他所拣选的摩西在他面前站在破裂之处，使他的愤怒转消，恐怕他就灭绝他们了。","notes":[]},{"n":24,"t":"他们又藐视那美地，不信他的话，","notes":[]},{"n":25,"t":"在自己帐棚内发怨言，不听耶和华的声音。","notes":[]},{"n":26,"t":"所以他向他们起誓，必叫他们倒在旷野，","notes":[]},{"n":27,"t":"叫他们的后裔倒在列国之中，分散在各地。","notes":[]},{"n":28,"t":"他们又与巴力．毗珥连合，吃了祭死人的物。","notes":[]},{"n":29,"t":"他们这样行，惹耶和华发怒，就有瘟疫流行在他们中间。","notes":[]},{"n":30,"t":"那时，非尼哈起而干预，瘟疫这才止息。","notes":[]},{"n":31,"t":"那就算他为义，世世代代，直到永远。","notes":[]},{"n":32,"t":"他们在米利巴水又惹耶和华发怒，甚至摩西也因他们的缘故受亏损，","notes":[]},{"n":33,"t":"是因他们触怒了他的灵，摩西就用嘴说了急躁的话。","notes":[]},{"n":34,"t":"他们不照耶和华所吩咐的灭绝外邦人，","notes":[]},{"n":35,"t":"反倒与列国相交，学习他们的行为，","notes":[]},{"n":36,"t":"事奉他们的偶像，这就成了自己的圈套。","notes":[]},{"n":37,"t":"他们把自己的儿女祭祀鬼魔，","notes":[]},{"n":38,"t":"流无辜人的血，就是自己儿女的血，用他们祭祀迦南的偶像，那地就被血玷污了。","notes":[]},{"n":39,"t":"这样，他们被自己所做的玷污了，在行为上犯了淫乱。","notes":[]},{"n":40,"t":"耶和华的怒气向他的百姓发作，他憎恶自己的产业，","notes":[]},{"n":41,"t":"将他们交在外邦人手里，恨他们的人就辖制他们。","notes":[]},{"n":42,"t":"他们的仇敌欺压他们，他们伏在敌人手下。","notes":[]},{"n":43,"t":"他屡次搭救他们，他们却图谋悖逆，就因自己的罪孽降为卑下。","notes":[]},{"n":44,"t":"然而，他听见他们哀告的时候，就眷顾他们的急难，","notes":[]},{"n":45,"t":"为了他们，他记念自己的约，照他丰盛的慈爱改变心意，","notes":[]},{"n":46,"t":"使他们在凡掳掠他们的人面前蒙怜悯。","notes":[]},{"n":47,"t":"耶和华－我们的神啊，求你拯救我们，从列国中召集我们，我们好颂扬你的圣名，以赞美你为夸胜。","notes":[]},{"n":48,"t":"耶和华－以色列的神是应当称颂的，从亘古直到永远。愿全体百姓都说：“阿们！”哈利路亚！","notes":[]}]},"107":{"heading":"颂赞神的良善","verses":[{"n":1,"t":"你们要称谢耶和华，因他本为善，他的慈爱永远长存！","notes":[]},{"n":2,"t":"愿耶和华救赎的百姓说这话，就是他从敌人手中所救赎，","notes":[]},{"n":3,"t":"从各地，从东从西，从北从海那边召集来的。","notes":[]},{"n":4,"t":"他们在旷野、在荒地飘流，找不到可居住的城，","notes":[]},{"n":5,"t":"又饥又渴，心里发昏。","notes":[]},{"n":6,"t":"于是他们在急难中哀求耶和华，他就搭救他们脱离祸患，","notes":[]},{"n":7,"t":"又领他们行走直路，前往可居住的城。","notes":[]},{"n":8,"t":"但愿人因耶和华的慈爱和他向人所做的奇事都称谢他；","notes":[]},{"n":9,"t":"因他使心里渴慕的人得以满足，使饥饿的人得饱美食。","notes":[]},{"n":10,"t":"那些坐在黑暗中、死荫里的人，被困苦和铁链捆锁，","notes":[]},{"n":11,"t":"是因他们违背神的言语，藐视至高者的旨意。","notes":[]},{"n":12,"t":"所以，他用劳苦制伏他们的心；他们仆倒，无人扶助。","notes":[]},{"n":13,"t":"于是他们在急难中哀求耶和华，他就拯救他们脱离祸患。","notes":[]},{"n":14,"t":"他从黑暗中、从死荫里领他们出来，扯断他们的捆绑。","notes":[]},{"n":15,"t":"但愿人因耶和华的慈爱和他向人所做的奇事都称谢他；","notes":[]},{"n":16,"t":"因为他打破了铜门，砍断了铁闩。","notes":[]},{"n":17,"t":"愚妄人因自己叛逆的行径和自己的罪孽受苦楚。","notes":[]},{"n":18,"t":"他们心里厌恶各样的食物，就临近死亡之门。","notes":[]},{"n":19,"t":"于是他们在急难中哀求耶和华，他就拯救他们脱离祸患。","notes":[]},{"n":20,"t":"他发出自己的话语医治他们，救他们脱离阴府。","notes":[]},{"n":21,"t":"但愿人因耶和华的慈爱和他向人所做的奇事都称谢他。","notes":[]},{"n":22,"t":"愿他们以感谢为祭献给他，欢呼述说他的作为！","notes":[]},{"n":23,"t":"那些搭船出海，在大水中做生意的，","notes":[]},{"n":24,"t":"他们看见耶和华的作为，并他在深海中的奇事。","notes":[]},{"n":25,"t":"他一出令，狂风卷起，波浪翻腾。","notes":[]},{"n":26,"t":"他们上到天空，下到海底，他们的心因患难而消沉。","notes":[]},{"n":27,"t":"他们摇摇晃晃，东倒西歪，好像醉酒的人，他们的智慧无法可施。","notes":[]},{"n":28,"t":"于是他们在急难中哀求耶和华，他就领他们脱离祸患。","notes":[]},{"n":29,"t":"他使狂风止息，波浪平静，","notes":[]},{"n":30,"t":"既平静了，他们就欢喜，他就领他们到想要去的海港。","notes":[]},{"n":31,"t":"但愿人因耶和华的慈爱和他向人所做的奇事都称谢他。","notes":[]},{"n":32,"t":"愿他们在百姓的会中尊崇他，在长老的座位上赞美他！","notes":[]},{"n":33,"t":"他使江河变为旷野，叫水泉变为干涸之地，","notes":[]},{"n":34,"t":"使肥沃之地变为荒芜的盐地，都因当地居民的邪恶。","notes":[]},{"n":35,"t":"他使旷野变为水潭，叫旱地变为水泉，","notes":[]},{"n":36,"t":"使饥饿的人住在那里，建造可居住的城，","notes":[]},{"n":37,"t":"又种田地，栽葡萄园，得享所出产的果实。","notes":[]},{"n":38,"t":"他赐福给他们，使他们生养众多，也不叫他们的牲畜减少。","notes":[]},{"n":39,"t":"但他们因欺压、患难、愁苦，人口减少而且卑微。","notes":[]},{"n":40,"t":"他使贵族蒙羞受辱，使他们迷失在荒凉无路之地；","notes":[]},{"n":41,"t":"却将穷乏人安置在高处，脱离苦难，使他的家属多如羊群。","notes":[]},{"n":42,"t":"正直的人看见就欢喜，罪孽之辈却要哑口无言。","notes":[]},{"n":43,"t":"凡有智慧的必在这些事上留心，他必思想耶和华的慈爱。","notes":[]}]},"108":{"heading":"抗敌求助","verses":[{"n":1,"t":"神啊，我心坚定；我口要唱诗歌颂！","notes":["“口”：原文是“荣耀”。"]},{"n":2,"t":"琴瑟啊，当醒起！我要唤起曙光！","notes":[]},{"n":3,"t":"耶和华啊，我要在万民中称谢你，在万族中歌颂你！","notes":[]},{"n":4,"t":"因为你的慈爱大过诸天，你的信实达到穹苍。","notes":[]},{"n":5,"t":"神啊，愿你崇高过于诸天！愿你的荣耀高过全地！","notes":[]},{"n":6,"t":"求你应允我，用右手施行拯救，好让你所亲爱的人得救。","notes":[]},{"n":7,"t":"神在他的圣所说：“我要欢乐；要划分示剑，丈量疏割谷。","notes":["“在他的圣所”或译“指着他的圣洁”。"]},{"n":8,"t":"基列是我的，玛拿西是我的，以法莲是护卫我头的，犹大是我的权杖。","notes":[]},{"n":9,"t":"摩押是我的沐浴盆，我要向以东扔鞋，我必因胜非利士而欢呼。”","notes":[]},{"n":10,"t":"谁能领我进坚固城？谁能引我到以东地？","notes":[]},{"n":11,"t":"神啊，你真的丢弃了我们吗？神啊，你不和我们的军队同去吗？","notes":[]},{"n":12,"t":"求你帮助我们攻击敌人，因为人的帮助是枉然的。","notes":[]},{"n":13,"t":"我们倚靠神才得施展大能，因为践踏我们敌人的就是他。","notes":[]}]},"109":{"heading":"遭难者的诉苦","verses":[{"n":1,"t":"我所赞美的神啊，求你不要闭口不言。","notes":[]},{"n":2,"t":"因为恶人的嘴和诡诈人的口张开攻击我，他们用撒谎的舌头对我说话。","notes":[]},{"n":3,"t":"他们围绕我，说怨恨的话，又无故地攻打我。","notes":[]},{"n":4,"t":"他们与我作对回报我的爱，但我专心祈祷。","notes":[]},{"n":5,"t":"他们向我以恶报善，以恨报爱。","notes":[]},{"n":6,"t":"求你派恶人辖制他，派对头站在他右边！","notes":[]},{"n":7,"t":"他受审判的时候，愿他背负罪名而出！愿他的祈祷反成为罪！","notes":[]},{"n":8,"t":"愿他的年岁短少！愿别人得他的职分！","notes":[]},{"n":9,"t":"愿他的儿女成为孤儿，他的妻子成为寡妇！","notes":[]},{"n":10,"t":"愿他的儿女飘流讨饭，从荒凉之处出来求乞！","notes":["“从荒凉之处出来求乞”：七十士译本是“愿他们从荒凉之处被赶出来”。"]},{"n":11,"t":"愿债主牢笼他一切所有的！愿陌生人抢走他劳碌得来的！","notes":[]},{"n":12,"t":"愿无人向他布施恩惠，无人恩待他的孤儿！","notes":[]},{"n":13,"t":"愿他的后人断绝，名字被涂去，不传于下代！","notes":[]},{"n":14,"t":"愿耶和华记得他祖宗的罪孽，不涂去他母亲的罪过！","notes":[]},{"n":15,"t":"愿这些罪常在耶和华面前！愿他们的名字从地上除灭！","notes":["“名字”：原文是“纪念”。"]},{"n":16,"t":"因为他从未想过要施恩，却迫害困苦贫穷的和伤心的人，把他们处死。","notes":[]},{"n":17,"t":"他爱咒骂，咒骂就临到他；他不喜爱祝福，祝福就远离他！","notes":[]},{"n":18,"t":"他拿咒骂当衣服穿上；这咒骂就如水进到他里面，如油进入他骨头。","notes":[]},{"n":19,"t":"愿这咒骂当他遮身的衣服，作他经常束腰的带子！","notes":[]},{"n":20,"t":"这就是那些与我作对、用恶言议论我的人从耶和华所受的报应。","notes":[]},{"n":21,"t":"但是你，主－耶和华啊，求你因你的名采取行动；因你的慈爱美好，求你搭救我！","notes":[]},{"n":22,"t":"因为我困苦贫穷，内心受伤。","notes":[]},{"n":23,"t":"我如日影偏斜而去，如蝗虫被抖出来。","notes":[]},{"n":24,"t":"我因禁食，膝盖软弱；我身体消瘦，不再丰润。","notes":[]},{"n":25,"t":"我受他们的羞辱，他们看见我就摇头。","notes":[]},{"n":26,"t":"耶和华－我的神啊，求你帮助我，照你的慈爱拯救我，","notes":[]},{"n":27,"t":"好让他们知道这是你的手，是你－耶和华所做的事。","notes":[]},{"n":28,"t":"任凭他们咒骂，你却要赐福；他们几时起来就必蒙羞，你的仆人却要欢喜。","notes":[]},{"n":29,"t":"愿与我作对的人披戴羞辱！愿他们以自己的羞愧作外袍遮身！","notes":[]},{"n":30,"t":"我要用口极力称谢耶和华，我要在众人中间赞美他；","notes":[]},{"n":31,"t":"因为他必站在贫穷人的右边，救他脱离定他死罪的人。","notes":[]}]},"110":{"heading":"耶和华所拣选之王","verses":[{"n":1,"t":"耶和华对我主说：“你坐在我的右边，等我使你仇敌作你的脚凳。”","notes":[]},{"n":2,"t":"耶和华必使你从锡安伸出你能力的权杖；你务要在仇敌中掌权。","notes":[]},{"n":3,"t":"你在圣山上掌权的日子，你的子民必甘心跟随；从晨曦初现，你就有清晨的甘露。","notes":["“圣山上”或译“圣洁妆饰中”。","“你的子民必甘心跟随”：七十士译本是“你必有王子的尊严”。","“清晨”：原文是“青春”。"]},{"n":4,"t":"耶和华起了誓，绝不改变：“你是照着麦基洗德的体系永远为祭司。”","notes":[]},{"n":5,"t":"在你右边的主，当他发怒的日子，必打伤列王。","notes":[]},{"n":6,"t":"他要审判列国，尸首就布满各处；他要痛击遍地的领袖。","notes":[]},{"n":7,"t":"他要喝路旁的河水，因此必抬起头来。","notes":[]}]},"111":{"heading":"赞美耶和华","verses":[{"n":1,"t":"哈利路亚！我要在正直人的大会和会众中一心称谢耶和华。","notes":[]},{"n":2,"t":"耶和华的作为本为大，被所有喜爱的人所探寻。","notes":[]},{"n":3,"t":"他所做的是尊荣和威严，他的公义存到永远。","notes":[]},{"n":4,"t":"他行了奇事，使人记念；耶和华有恩惠，有怜悯。","notes":[]},{"n":5,"t":"他赐粮食给敬畏他的人，他必永远记念他的约。","notes":[]},{"n":6,"t":"他向百姓显出大能的作为，将列国赐给他们为业。","notes":[]},{"n":7,"t":"他手所做的信实公平，他的训词全然可靠，","notes":[]},{"n":8,"t":"是永永远远坚定的，是按信实正直设立的。","notes":[]},{"n":9,"t":"他向百姓施行救赎，颁布他的约，直到永远；他的名圣而可畏。","notes":[]},{"n":10,"t":"敬畏耶和华是智慧的开端，凡遵行他命令的有美好的见识。耶和华是永远当赞美的！","notes":[]}]},"112":{"heading":"义人之福","verses":[{"n":1,"t":"哈利路亚！敬畏耶和华，甚喜爱他命令的，这人有福了！","notes":[]},{"n":2,"t":"他的后裔在世必强盛，正直人的后代必蒙福。","notes":[]},{"n":3,"t":"他的家中有金银财宝，他的义行存到永远。","notes":[]},{"n":4,"t":"正直人在黑暗中有光向他照耀，他有恩惠，有怜悯，有公义。","notes":[]},{"n":5,"t":"施恩与人、借贷与人、秉公处事的人必享美福，","notes":[]},{"n":6,"t":"他永不动摇。义人被记念，直到永远。","notes":[]},{"n":7,"t":"他不惧怕凶恶的信息，他的心坚定，倚靠耶和华。","notes":[]},{"n":8,"t":"他的心确定，总不惧怕，直到他看见敌人遭报。","notes":[]},{"n":9,"t":"他施舍，周济贫穷，他的义行存到永远，他的角必被高举，大有荣耀。","notes":[]},{"n":10,"t":"恶人看见就愤怒，必咬牙而消亡，恶人的心愿要归于幻灭。","notes":[]}]},"113":{"heading":"赞美耶和华的良善","verses":[{"n":1,"t":"哈利路亚！耶和华的仆人哪，你们要赞美，赞美耶和华的名！","notes":[]},{"n":2,"t":"耶和华的名是应当称颂的，从今时直到永远！","notes":[]},{"n":3,"t":"从日出之地到日落之处，耶和华的名是应当赞美的！","notes":[]},{"n":4,"t":"耶和华超乎万国之上，他的荣耀高过诸天。","notes":[]},{"n":5,"t":"谁像耶和华－我们的神呢？他坐在至高之处，","notes":[]},{"n":6,"t":"自己谦卑，观看天上地下的事。","notes":[]},{"n":7,"t":"他从灰尘里抬举贫寒的人，从粪堆中提拔贫穷的人，","notes":[]},{"n":8,"t":"使他们与贵族同坐，与本国的贵族同坐。","notes":[]},{"n":9,"t":"他使不孕的妇女安居家中，成为快乐的母亲，儿女成群。哈利路亚！","notes":[]}]},"114":{"heading":"逾越节之歌","verses":[{"n":1,"t":"以色列出埃及，雅各家离开说陌生语言之民时，","notes":[]},{"n":2,"t":"犹大作主的圣所，以色列为他所治理的国。","notes":[]},{"n":3,"t":"沧海看见就奔逃，约旦河也倒流。","notes":[]},{"n":4,"t":"大山踊跃如公羊，小山跳舞如羔羊。","notes":[]},{"n":5,"t":"沧海啊，你为何奔逃？约旦哪，你为何倒流？","notes":[]},{"n":6,"t":"大山哪，你为何踊跃如公羊？小山哪，你为何跳舞如羔羊？","notes":[]},{"n":7,"t":"大地啊，在主的面前，在雅各的神的面前，震动吧！","notes":[]},{"n":8,"t":"他叫磐石变为水池，使坚石变为泉源。","notes":[]}]},"115":{"heading":"独一真神","verses":[{"n":1,"t":"耶和华啊，荣耀不要归与我们，不要归与我们；要因你的慈爱和信实归在你的名下！","notes":[]},{"n":2,"t":"为何让列国说“他们的神在哪里”呢？","notes":[]},{"n":3,"t":"但是，我们的神在天上，万事都随自己的旨意而行。","notes":[]},{"n":4,"t":"他们的偶像是金的，是银的，是人手所造的，","notes":[]},{"n":5,"t":"有口却不能言，有眼却不能看，","notes":[]},{"n":6,"t":"有耳却不能听，有鼻却不能闻，","notes":[]},{"n":7,"t":"有手却不能摸，有脚却不能走，有喉却不能说话。","notes":[]},{"n":8,"t":"造它们的要像它们一样，凡靠它们的也必如此。","notes":[]},{"n":9,"t":"以色列啊，要倚靠耶和华！他是人的帮助和盾牌。","notes":[]},{"n":10,"t":"亚伦家啊，要倚靠耶和华！他是人的帮助和盾牌。","notes":[]},{"n":11,"t":"敬畏耶和华的人哪，要倚靠耶和华！他是人的帮助和盾牌。","notes":[]},{"n":12,"t":"耶和华向来眷念我们，他还要赐福，赐福给以色列家，赐福给亚伦家。","notes":[]},{"n":13,"t":"凡敬畏耶和华的，无论大小，主必赐福给他。","notes":[]},{"n":14,"t":"愿耶和华使你们和你们的子孙日见增加。","notes":[]},{"n":15,"t":"你们蒙了耶和华的福，他是创造天地的主宰。","notes":[]},{"n":16,"t":"天，是耶和华的天；地，他却给了世人。","notes":[]},{"n":17,"t":"死人不能赞美耶和华，下到寂静中的也都不能。","notes":["“寂静”就是“死亡”。"]},{"n":18,"t":"但我们要称颂耶和华，从今时直到永远。哈利路亚！","notes":[]}]},"116":{"heading":"为出死入生赞美神","verses":[{"n":1,"t":"我爱耶和华，因为他听了我的声音和我的恳求。","notes":[]},{"n":2,"t":"他既向我侧耳，我一生要求告他。","notes":[]},{"n":3,"t":"死亡的绳索勒住我，阴间的痛苦抓住我，我遭遇患难愁苦。","notes":[]},{"n":4,"t":"那时，我求告耶和华的名：“耶和华啊，求你救我！”","notes":[]},{"n":5,"t":"耶和华有恩惠，有公义，我们的神有怜悯。","notes":[]},{"n":6,"t":"耶和华保护愚蒙的人；我落到卑微的地步，他救了我。","notes":[]},{"n":7,"t":"我的心哪！你要复归安宁，因为耶和华用厚恩待你。","notes":[]},{"n":8,"t":"主啊，你救我的命脱离死亡，使我的眼不再流泪，使我的脚不致跌倒。","notes":[]},{"n":9,"t":"我行在耶和华面前，走在活人之地。","notes":[]},{"n":10,"t":"我信，尽管我说：“我受了极大的困苦。”","notes":[]},{"n":11,"t":"我曾惊惶地说：“人都是说谎的！”","notes":[]},{"n":12,"t":"耶和华向我赏赐一切厚恩，我拿什么来报答他呢？","notes":[]},{"n":13,"t":"我要举起救恩的杯，称扬耶和华的名。","notes":[]},{"n":14,"t":"我要在他的全体百姓面前向耶和华还我所许的愿。","notes":[]},{"n":15,"t":"在耶和华眼中，圣民之死极为宝贵。","notes":[]},{"n":16,"t":"耶和华啊，哦，我是你的仆人；我是你的仆人，是你使女的儿子。你已经解开我的捆索。","notes":[]},{"n":17,"t":"我要以感谢为祭献给你，又要求告耶和华的名。","notes":[]},{"n":18,"t":"我要在耶路撒冷当中，在耶和华殿的院内，在他的全体百姓面前，向耶和华还我所许的愿。哈利路亚！","notes":[],"end":19}]},"117":{"heading":"赞美耶和华","verses":[{"n":1,"t":"万国啊，你们要赞美耶和华！万族啊，你们都要颂赞他！","notes":[]},{"n":2,"t":"因为他向我们大施慈爱，耶和华的信实存到永远。哈利路亚！","notes":[]}]},"118":{"heading":"因胜利而称谢耶和华","verses":[{"n":1,"t":"你们要称谢耶和华，因他本为善；他的慈爱永远长存！","notes":[]},{"n":2,"t":"愿以色列说：“他的慈爱永远长存！”","notes":[]},{"n":3,"t":"愿亚伦家说：“他的慈爱永远长存！”","notes":[]},{"n":4,"t":"愿敬畏耶和华的人说：“他的慈爱永远长存！”","notes":[]},{"n":5,"t":"我在急难中求告耶和华，耶和华就应允我，把我安置在宽阔之地。","notes":[]},{"n":6,"t":"耶和华在我这边，我必不惧怕，人能把我怎么样呢？","notes":["“耶和华在我这边”：七十士译本是“主是我的帮助”。"]},{"n":7,"t":"在那帮助我的人中，有耶和华帮助我，所以我要看见那些恨我的人遭报。","notes":[]},{"n":8,"t":"投靠耶和华，强似倚赖人；","notes":[]},{"n":9,"t":"投靠耶和华，强似倚赖权贵。","notes":[]},{"n":10,"t":"列邦围绕我，我靠耶和华的名必剿灭他们。","notes":[]},{"n":11,"t":"他们围绕我，围困我，我靠耶和华的名必剿灭他们。","notes":[]},{"n":12,"t":"他们如同蜜蜂一般地围绕我，他们熄灭，好像烧荆棘的火；我靠耶和华的名，必剿灭他们。","notes":[]},{"n":13,"t":"你用力推我，要叫我跌倒，但耶和华帮助了我。","notes":[]},{"n":14,"t":"耶和华是我的力量，是我的诗歌，他也成了我的拯救。","notes":[]},{"n":15,"t":"在义人的帐棚里，有欢呼拯救的声音，耶和华的右手施展大能。","notes":[]},{"n":16,"t":"耶和华的右手高举，耶和华的右手施展大能。","notes":[]},{"n":17,"t":"我不至于死，仍要存活，并要传扬耶和华的作为。","notes":[]},{"n":18,"t":"耶和华虽严严地惩治我，却未曾将我交于死亡。","notes":[]},{"n":19,"t":"给我敞开义门，我要进去称谢耶和华！","notes":[]},{"n":20,"t":"这是耶和华的门，义人要进去！","notes":[]},{"n":21,"t":"我要称谢你，因为你已经应允我，又成了我的拯救！","notes":[]},{"n":22,"t":"匠人所丢弃的石头已成了房角的头块石头。","notes":[]},{"n":23,"t":"这是耶和华所做的，在我们眼中看为奇妙。","notes":[]},{"n":24,"t":"这是耶和华所定的日子，我们在其中要高兴欢喜！","notes":[]},{"n":25,"t":"耶和华啊，求你拯救！耶和华啊，求你使我们顺利！","notes":["“求你拯救”：原文音译“和散那”。"]},{"n":26,"t":"奉耶和华的名来的是应当称颂的！我们从耶和华的殿中为你们祝福！","notes":[]},{"n":27,"t":"耶和华是神，他光照了我们。你们要用绳索把祭牲拴住，直牵到坛角。","notes":[]},{"n":28,"t":"你是我的神，我要称谢你！我的神啊，我要尊崇你！","notes":["“我要尊崇你”：七十士译本是“我要尊崇你！我要称谢你，因为你已经应允我，又成了我的拯救”。"]},{"n":29,"t":"你们要称谢耶和华，因他本为善；他的慈爱永远长存！","notes":[]}]},"119":{"heading":"耶和华的律法","verses":[{"n":1,"t":"行为正直、遵行耶和华律法的，这人有福了！","notes":[]},{"n":2,"t":"遵守他的法度、一心寻求他的，这人有福了！","notes":[]},{"n":3,"t":"他们不做不义的事，但遵行他的道。","notes":[]},{"n":4,"t":"耶和华啊，你曾将你的训词吩咐我们，为要我们切实遵守。","notes":[]},{"n":5,"t":"但愿我行事坚定，得以遵守你的律例。","notes":[]},{"n":6,"t":"我看重你的一切命令，就不致羞愧。","notes":[]},{"n":7,"t":"我学习你公义的典章，要以正直的心称谢你。","notes":[]},{"n":8,"t":"我必遵守你的律例，求你不要把我全然弃绝！","notes":[]},{"n":9,"t":"青年要如何保持纯洁呢？是要遵行你的话！","notes":[],"heads":["顺从耶和华的律法"]},{"n":10,"t":"我曾一心寻求你，求你不要使我偏离你的命令。","notes":[]},{"n":11,"t":"我将你的话藏在心里，免得我得罪你。","notes":[]},{"n":12,"t":"耶和华啊，你是应当称颂的！求你将你的律例教导我！","notes":[]},{"n":13,"t":"我用嘴唇传扬你口中一切的典章。","notes":[]},{"n":14,"t":"我喜爱你的法度，如同喜爱一切的财物。","notes":[]},{"n":15,"t":"我要默想你的训词，看重你的道路。","notes":[]},{"n":16,"t":"我要以你的律例为乐，我不忘记你的话。","notes":[]},{"n":17,"t":"求你用厚恩待你的仆人，使我存活，我就遵守你的话。","notes":[],"heads":["因耶和华律法而蒙福"]},{"n":18,"t":"求你开我的眼睛，使我看出你律法中的奇妙。","notes":[]},{"n":19,"t":"我在地上是寄居的人，求你不要向我隐藏你的命令！","notes":[]},{"n":20,"t":"我时常切慕你的典章，耗尽心力。","notes":[]},{"n":21,"t":"受诅咒、偏离你命令的骄傲人，你已经责备他们。","notes":[]},{"n":22,"t":"求你除掉我所受的羞辱和藐视，因我遵守你的法度。","notes":[]},{"n":23,"t":"虽有掌权者坐着妄论我，你仆人却思想你的律例。","notes":[]},{"n":24,"t":"你的法度也是我的喜乐，我的导师。","notes":["“我的导师”：七十士译本是“你的律例是我的导师”。"]},{"n":25,"t":"我的性命几乎归于尘土，求你照你的话将我救活！","notes":[],"heads":["决意遵行耶和华的律法"]},{"n":26,"t":"我述说我所做的，你应允了我；求你将你的律例教导我！","notes":[]},{"n":27,"t":"求你使我明白你的训词，我要默想你的奇事。","notes":[]},{"n":28,"t":"我因愁苦身心耗尽，求你照你的话使我坚立！","notes":[]},{"n":29,"t":"求你使我离开奸诈的道路，开恩将你的律法赐给我！","notes":[]},{"n":30,"t":"我选择了忠信的道路，将你的典章摆在我面前。","notes":[]},{"n":31,"t":"我持守你的法度；耶和华啊，求你不要叫我羞愧！","notes":[]},{"n":32,"t":"你使我心胸开阔的时候，我就往你命令的道路直奔。","notes":[]},{"n":33,"t":"耶和华啊，求你将你的律例指教我，我必遵守到底！","notes":[],"heads":["求主赐悟性"]},{"n":34,"t":"求你赐我悟性，我就遵守你的律法，且要一心遵守。","notes":[]},{"n":35,"t":"求你叫我遵行你的命令，因为这是我所喜爱的。","notes":[]},{"n":36,"t":"求你使我的心趋向你的法度，不趋向不义之财。","notes":[]},{"n":37,"t":"求你叫我转眼不看虚假，使我活在你的道路中。","notes":["“道路”：有古卷是“话”。"]},{"n":38,"t":"求你向敬畏你的仆人坚守你的话！","notes":[]},{"n":39,"t":"求你使我所惧怕的羞辱远离我，因你的典章本为美。","notes":[]},{"n":40,"t":"看哪，我切慕你的训词，求你因你的公义赐我生命！","notes":["“因你...生命”或译“求你使我活在你的公义中”。"]},{"n":41,"t":"耶和华啊，求你使你的慈爱临到我，照你的话使你的救恩临到我，","notes":[],"heads":["倚靠耶和华的律法"]},{"n":42,"t":"我就有话回答那羞辱我的，因我倚靠你的话。","notes":[]},{"n":43,"t":"求你叫真理的话总不离开我的口，因我仰望你的典章。","notes":[]},{"n":44,"t":"我要常守你的律法，直到永永远远。","notes":[]},{"n":45,"t":"我要自由而行，因我寻求了你的训词。","notes":["“自由而行”或译“行在宽阔之地”。"]},{"n":46,"t":"我要在列王面前宣讲你的法度，也不致羞愧。","notes":[]},{"n":47,"t":"我以你的命令为乐，这命令是我所喜爱的。","notes":[]},{"n":48,"t":"我向我所爱的，就是你的命令高举双手，我也要默想你的律例。","notes":["“我向...双手”或译“我要遵行我所爱的，就是你的命令”。"]},{"n":49,"t":"求你记念你向仆人所说的话，这话使我有盼望。","notes":[],"heads":["因耶和华的律法而安稳"]},{"n":50,"t":"你的话将我救活了；这是我在患难中的安慰。","notes":[]},{"n":51,"t":"骄傲的人极度地侮慢我，我却未曾偏离你的律法。","notes":[]},{"n":52,"t":"耶和华啊，我记念你从古以来的典章，就得了安慰。","notes":[]},{"n":53,"t":"我因恶人离弃你的律法，怒火中烧。","notes":[]},{"n":54,"t":"我在世寄居，以你的律例为诗歌。","notes":[]},{"n":55,"t":"耶和华啊，我夜间记念你的名，我也要遵守你的律法。","notes":[]},{"n":56,"t":"这临到我，是因我谨守你的训词。","notes":[]},{"n":57,"t":"耶和华是我的福分；我曾说，我要遵守你的话。","notes":[],"heads":["深爱耶和华的律法"]},{"n":58,"t":"我一心恳求你的面，求你照你的话怜悯我！","notes":[]},{"n":59,"t":"我思想自己所行的道路，我的脚步就转向你的法度。","notes":[]},{"n":60,"t":"我速速遵守你的命令，并不迟延。","notes":[]},{"n":61,"t":"恶人的绳索缠绕我，我却没有忘记你的律法。","notes":[]},{"n":62,"t":"我因你公义的典章，夜半起来称谢你。","notes":[]},{"n":63,"t":"凡敬畏你、守你训词的人，我都与他作伴。","notes":[]},{"n":64,"t":"耶和华啊，遍地满了你的慈爱；求你将你的律例教导我！","notes":[]},{"n":65,"t":"耶和华啊，你照你的话，善待你的仆人。","notes":[],"heads":["耶和华律法的宝贵"]},{"n":66,"t":"求你教我明辨和知识，因我信靠你的命令。","notes":[]},{"n":67,"t":"我未受苦以先曾经迷失，现在却遵守你的话。","notes":[]},{"n":68,"t":"你本为善，所行的也善；求你将你的律例教导我！","notes":[]},{"n":69,"t":"骄傲的人编造谎言攻击我，我却要一心遵守你的训词。","notes":[]},{"n":70,"t":"他们的心蒙昧如蒙油脂，我却喜爱你的律法。","notes":[]},{"n":71,"t":"我受苦是与我有益，为要使我学习你的律例。","notes":[]},{"n":72,"t":"你口中的律法与我有益，胜于千万金银。","notes":[]},{"n":73,"t":"你的手造了我，塑造我；求你赐我悟性学习你的命令！","notes":[],"heads":["耶和华律法的公正"]},{"n":74,"t":"敬畏你的人看见我就欢喜，因我仰望你的话。","notes":[]},{"n":75,"t":"耶和华啊，我知道你的典章是公义的；你使我受苦是以信实待我。","notes":[]},{"n":76,"t":"求你照着你向仆人所说的话，以慈爱安慰我。","notes":[]},{"n":77,"t":"求你的怜悯临到我，使我存活，因你的律法是我的喜乐。","notes":[]},{"n":78,"t":"愿骄傲的人蒙羞，因为他们无理倾覆我；但我要默想你的训词。","notes":[]},{"n":79,"t":"愿敬畏你的人和知道你法度的人都归向我。","notes":["本节或译“愿敬畏你的人都归向我，他们就知道你的法度。”"]},{"n":80,"t":"愿我的心在你的律例上完全，使我不致蒙羞。","notes":[]},{"n":81,"t":"我渴想你的救恩身心耗尽，我仰望你的话。","notes":[],"heads":["求主解救"]},{"n":82,"t":"我因渴望你的话眼睛失明，说：“你何时安慰我呢？”","notes":[]},{"n":83,"t":"我虽像烟薰的皮囊，却不忘记你的律例。","notes":[]},{"n":84,"t":"你仆人的年日有多少呢？你几时向迫害我的人施行审判呢？","notes":[]},{"n":85,"t":"不顺从你律法的骄傲人为我掘了坑。","notes":[]},{"n":86,"t":"你的命令尽都信实；他们无理迫害我，求你帮助我！","notes":[]},{"n":87,"t":"他们几乎把我从世上除灭；但我没有离弃你的训词。","notes":[]},{"n":88,"t":"求你照你的慈爱将我救活，我就遵守你口中的法度。","notes":[]},{"n":89,"t":"耶和华啊，你的话安定在天，直到永远。","notes":[],"heads":["信赖耶和华的律法"]},{"n":90,"t":"你的信实存到万代；你坚立了地，地就长存。","notes":[]},{"n":91,"t":"天地照你的典章存到今日；万物都是你的仆役。","notes":[]},{"n":92,"t":"我若不以你的律法为乐，早就在苦难中灭绝了！","notes":[]},{"n":93,"t":"我永不忘记你的训词，因你用这训词将我救活。","notes":[]},{"n":94,"t":"我是属你的，求你救我，因我寻求了你的训词。","notes":[]},{"n":95,"t":"恶人等着要灭绝我，我却要揣摩你的法度。","notes":[]},{"n":96,"t":"我看万事尽都有限，惟有你的命令极其宽广。","notes":[]},{"n":97,"t":"我何等爱慕你的律法，终日不住地思想。","notes":[],"heads":["喜爱耶和华的律法"]},{"n":98,"t":"你的命令常存在我心里，使我比仇敌有智慧。","notes":[]},{"n":99,"t":"我比我的教师更通达，因我思想你的法度。","notes":[]},{"n":100,"t":"我比年老的更明白，因我谨守你的训词。","notes":[]},{"n":101,"t":"我阻止我的脚走一切邪路，为要遵守你的话。","notes":[]},{"n":102,"t":"我没有偏离你的典章，因为你教导了我。","notes":[]},{"n":103,"t":"你的言语在我上膛何等甘美，在我口中比蜜更甜！","notes":[]},{"n":104,"t":"我藉着你的训词得以明白，因此，我恨恶一切虚假的行径。","notes":[]},{"n":105,"t":"你的话是我脚前的灯，是我路上的光。","notes":[],"heads":["耶和华律法的亮光"]},{"n":106,"t":"你公义的典章，我曾起誓遵守，我必按着誓言而行。","notes":[]},{"n":107,"t":"我极其痛苦；耶和华啊，求你照你的话将我救活！","notes":[]},{"n":108,"t":"耶和华啊，求你悦纳我口中的赞美为甘心祭，又将你的典章教导我！","notes":[]},{"n":109,"t":"我的性命常在我手掌中，我却不忘记你的律法。","notes":["“性命常在我手掌中”意思是“危险”。"]},{"n":110,"t":"恶人为我设下罗网，我却没有偏离你的训词。","notes":[]},{"n":111,"t":"我以你的法度为永远的产业，因这是我心中所喜爱的。","notes":[]},{"n":112,"t":"我的心倾向你的律例，谨守到底，直到永远。","notes":[]},{"n":113,"t":"心怀二意的人为我所恨；但你的律法为我所爱。","notes":[],"heads":["因耶和华律法得安全"]},{"n":114,"t":"你是我藏身之处，是我的盾牌；我仰望你的话。","notes":[]},{"n":115,"t":"作恶的人哪，你们离开我吧！我要遵守我神的命令。","notes":[]},{"n":116,"t":"求你照你的话扶持我，使我存活，不要叫我因失望而蒙羞。","notes":[]},{"n":117,"t":"求你扶持我，使我得救，时常看重你的律例。","notes":[]},{"n":118,"t":"凡偏离你律例的人，你都轻看他们，因为他们的诡诈必归虚空。","notes":[]},{"n":119,"t":"你除掉地上所有的恶人，好像除掉渣滓；因此我喜爱你的法度。","notes":["“你除掉...渣滓”：有古卷和古译本是“在你看来恶人好像渣滓”。"]},{"n":120,"t":"我因惧怕你，肉体战栗；我害怕你的典章。","notes":[]},{"n":121,"t":"我行公平和公义，求你不要撇下我，交给欺压我的人！","notes":[],"heads":["遵从耶和华的律法"]},{"n":122,"t":"求你保证你的仆人得福，不容骄傲的人欺压我！","notes":[]},{"n":123,"t":"我因盼望你的救恩和你公义的言语眼睛失明。","notes":[]},{"n":124,"t":"求你照你的慈爱待仆人，将你的律例教导我。","notes":[]},{"n":125,"t":"我是你的仆人，求你赐我悟性，得以认识你的法度。","notes":[]},{"n":126,"t":"这是耶和华采取行动的时候，因人废弃了你的律法。","notes":[]},{"n":127,"t":"所以，我喜爱你的命令胜于金子，更胜于纯金。","notes":[]},{"n":128,"t":"你的一切训词，在万事上我都以为正直；我恨恶一切虚假的行径。","notes":[]},{"n":129,"t":"你的法度奇妙，所以我一心谨守。","notes":[],"heads":["渴慕遵行耶和华的律法"]},{"n":130,"t":"你的话一开启就发出亮光，使愚蒙人通达。","notes":[]},{"n":131,"t":"我大大张口，呼吸急促，因我切慕你的命令。","notes":[]},{"n":132,"t":"求你转向我，怜悯我，就像你待那些喜爱你名的人。","notes":[]},{"n":133,"t":"求你用你的言语使我脚步稳健，不容罪孽辖制我。","notes":[]},{"n":134,"t":"求你救我脱离人的欺压，我要遵守你的训词。","notes":[]},{"n":135,"t":"求你使你的脸向仆人发光，又将你的律例教导我。","notes":[]},{"n":136,"t":"我的眼睛流泪成河，因为他们不守你的律法。","notes":[]},{"n":137,"t":"耶和华啊，你是公义的；你的典章正直！","notes":[],"heads":["耶和华律法的公正"]},{"n":138,"t":"你所颁布的法度是公义的，极其可靠。","notes":[]},{"n":139,"t":"我的狂热把我烧灭，因我敌人忘记你的话。","notes":[]},{"n":140,"t":"你的言语极其精炼，令你仆人喜爱。","notes":[]},{"n":141,"t":"我渺小，被人藐视，却不忘记你的训词。","notes":[]},{"n":142,"t":"你的公义永远公义，你的律法是确实的。","notes":[]},{"n":143,"t":"我遭遇患难愁苦，你的命令是我的喜乐。","notes":[]},{"n":144,"t":"你的法度永远公义；求你赐我悟性，使我存活。","notes":[]},{"n":145,"t":"耶和华啊，我一心呼求你，求你应允我！我必谨守你的律例。","notes":[],"heads":["求主解救"]},{"n":146,"t":"我向你呼求，求你救我！我要遵守你的法度。","notes":[]},{"n":147,"t":"天尚未亮我呼喊求救，我仰望你的话。","notes":[]},{"n":148,"t":"我终夜双眼睁开，为要思想你的言语。","notes":[]},{"n":149,"t":"求你按你的慈爱听我的声音，耶和华啊，求你照你的典章将我救活！","notes":[]},{"n":150,"t":"追逐奸恶的人迫近了，他们远离你的律法。","notes":["“追逐奸恶的人”：有古卷和古译本是“以奸恶追逐我的人”。"]},{"n":151,"t":"耶和华啊，你就在我身边，你一切的命令是确实的！","notes":[]},{"n":152,"t":"我从你的法度早已知道，这法度是你永远立定的。","notes":[]},{"n":153,"t":"求你看顾我的苦难，搭救我，因我不忘记你的律法。","notes":[],"heads":["请求恩助"]},{"n":154,"t":"求你为我的冤屈辩护，救赎我，照你的言语将我救活。","notes":[]},{"n":155,"t":"救恩远离恶人，因为他们不寻求你的律例。","notes":[]},{"n":156,"t":"耶和华啊，你的怜悯本为大；求你照你的典章将我救活。","notes":[]},{"n":157,"t":"迫害我的、抵挡我的甚多，我却没有偏离你的法度。","notes":[]},{"n":158,"t":"我看见奸恶的人就憎恶，因为他们不遵守你的言语。","notes":[]},{"n":159,"t":"你看我何等喜爱你的训词！耶和华啊，求你按你的慈爱将我救活！","notes":[]},{"n":160,"t":"你话语的精髓是真实的，你一切公义的典章永远长存。","notes":[]},{"n":161,"t":"掌权者无故迫害我，然而我的心畏惧你的话。","notes":[],"heads":["热爱耶和华的律法"]},{"n":162,"t":"我喜爱你的言语，好像人得到许多战利品。","notes":[]},{"n":163,"t":"我恨恶，憎恶虚假；惟喜爱你的律法。","notes":[]},{"n":164,"t":"我因你公义的典章一天七次赞美你。","notes":[]},{"n":165,"t":"喜爱你律法的人大有平安，任何事都不能使他们跌倒。","notes":[]},{"n":166,"t":"耶和华啊，我仰望你的救恩，遵行你的命令。","notes":[]},{"n":167,"t":"我心谨守你的法度，这法度我极其喜爱。","notes":[]},{"n":168,"t":"我遵守你的训词和法度，因我所行的道路都在你的面前。","notes":[]},{"n":169,"t":"耶和华啊，愿我的呼求达到你面前，求你照你的话赐我悟性。","notes":[],"heads":["求主帮助"]},{"n":170,"t":"愿我的恳求达到你面前，求你照你的言语搭救我。","notes":[]},{"n":171,"t":"愿我的嘴唇发出赞美，因为你将律例教导我。","notes":[]},{"n":172,"t":"愿我的舌头歌唱你的言语，因你一切的命令尽都公义。","notes":[]},{"n":173,"t":"求你用你的手帮助我，因我选择你的训词。","notes":[]},{"n":174,"t":"耶和华啊，我切慕你的救恩！你的律法是我的喜乐。","notes":[]},{"n":175,"t":"愿我的性命存活，得以赞美你！愿你的典章帮助我！","notes":[]},{"n":176,"t":"我走迷了路如同失丧的羊，求你寻找你的仆人，因我不忘记你的命令。","notes":[]}]},"120":{"heading":"求主恩助","verses":[{"n":1,"t":"我在急难中求告耶和华，他就应允我。","notes":[]},{"n":2,"t":"耶和华啊，求你救我脱离说谎的嘴唇和诡诈的舌头！","notes":[]},{"n":3,"t":"诡诈的舌头啊，他会给你什么呢？会加给你什么呢？","notes":[]},{"n":4,"t":"就是勇士的利箭、罗腾木的炭火。","notes":["“罗腾木”为小树名，松类。"]},{"n":5,"t":"祸哉！我寄居在米设，住在基达帐棚之中。","notes":[]},{"n":6,"t":"我与那恨恶和平的人许久同住。","notes":[]},{"n":7,"t":"我愿和平，当我发言，他们却要战争。","notes":[]}]},"121":{"heading":"耶和华是我们的保护者","verses":[{"n":1,"t":"我要向山举目，我的帮助从何而来？","notes":[]},{"n":2,"t":"我的帮助从造天地的耶和华而来。","notes":[]},{"n":3,"t":"他不叫你的脚摇动，保护你的必不打盹！","notes":[]},{"n":4,"t":"保护以色列的必不打盹，也不睡觉。","notes":[]},{"n":5,"t":"保护你的是耶和华，耶和华在你右边荫庇你。","notes":[]},{"n":6,"t":"白日，太阳必不伤你；夜间，月亮也不害你。","notes":[]},{"n":7,"t":"耶和华要保护你，免受一切的灾害，他要保护你的性命。","notes":[]},{"n":8,"t":"你出你入，耶和华要保护你，从今时直到永远。","notes":[]}]},"122":{"heading":"耶路撒冷颂","verses":[{"n":1,"t":"我喜乐，因人对我说：“我们到耶和华的殿去。”","notes":[]},{"n":2,"t":"耶路撒冷啊，我们的脚站在你门内。","notes":[]},{"n":3,"t":"耶路撒冷被建造，如同连结整齐的一座城。","notes":[]},{"n":4,"t":"众支派就是耶和华的支派，上那里去，按以色列的法度颂扬耶和华的名。","notes":[]},{"n":5,"t":"他们在那里设立审判的宝座，就是大卫家的宝座。","notes":[]},{"n":6,"t":"你们要为耶路撒冷求平安：“愿爱你的人兴旺！","notes":[]},{"n":7,"t":"愿你城中有平安！愿你宫内得平静！”","notes":[]},{"n":8,"t":"为我弟兄和同伴的缘故，我要说：“愿你平安！”","notes":[]},{"n":9,"t":"为耶和华－我们神殿的缘故，我要为你求福！","notes":[]}]},"123":{"heading":"求主怜悯","verses":[{"n":1,"t":"坐在天上的主啊，我向你举目。","notes":[]},{"n":2,"t":"看哪，仆人的眼睛怎样仰望主人的手，婢女的眼睛怎样仰望女主人的手，我们的眼睛也照样仰望耶和华－我们的神，直到他怜悯我们。","notes":[]},{"n":3,"t":"耶和华啊，求你怜悯我们，怜悯我们！因为我们受尽了藐视。","notes":[]},{"n":4,"t":"我们受尽了安逸人的讥诮和骄傲人的藐视。","notes":[]}]},"124":{"heading":"神保护他的子民","verses":[{"n":1,"t":"说吧，以色列：“若不是耶和华帮助我们，","notes":[]},{"n":2,"t":"若不是耶和华帮助我们，当人起来攻击我们，","notes":[]},{"n":3,"t":"那时，人向我们发怒，就把我们活活吞了；","notes":[]},{"n":4,"t":"那时，波涛必漫过我们，河水必淹没我们；","notes":[]},{"n":5,"t":"那时，狂傲的水必淹没我们。”","notes":[]},{"n":6,"t":"耶和华是应当称颂的！他没有把我们交给他们，作牙齿的猎物。","notes":[]},{"n":7,"t":"我们好像雀鸟，从捕鸟人的罗网里逃脱，罗网破裂，我们就逃脱了。","notes":[]},{"n":8,"t":"我们得帮助，是因造天地之耶和华的名。","notes":[]}]},"125":{"heading":"耶和华子民的安全","verses":[{"n":1,"t":"倚靠耶和华的人好像锡安山，安稳坐镇，永不动摇。","notes":[]},{"n":2,"t":"众山怎样围绕耶路撒冷，耶和华也照样围绕他的百姓，从今时直到永远。","notes":[]},{"n":3,"t":"恶人的杖必不在义人的土地上停留，免得义人伸手作恶。","notes":[]},{"n":4,"t":"耶和华啊，求你善待行善和心里正直的人。","notes":[]},{"n":5,"t":"至于那偏行弯曲道路的人，耶和华必将他们和作恶的人一同驱逐出去。愿平安归于以色列！","notes":[]}]},"126":{"heading":"被掳归回者的欢乐","verses":[{"n":1,"t":"当耶和华使锡安被掳的人归回的时候，我们好像做梦的人。","notes":[]},{"n":2,"t":"那时，我们满口喜笑、满舌欢呼；那时，列国中就有人说：“耶和华为他们行了大事！”","notes":[]},{"n":3,"t":"耶和华果然为我们行了大事，我们就欢喜。","notes":[]},{"n":4,"t":"耶和华啊，求你使我们这些被掳的人归回，好像尼革夫的河水复流。","notes":["“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”。"]},{"n":5,"t":"流泪撒种的，必欢呼收割！","notes":[]},{"n":6,"t":"那带种流泪出去的，必欢呼地带禾捆回来！","notes":[]}]},"127":{"heading":"称颂神的良善","verses":[{"n":1,"t":"若不是耶和华建造房屋，建造的人就枉然劳力；若不是耶和华看守城池，看守的人就枉然警醒。","notes":[]},{"n":2,"t":"你们清晨早起，夜晚安歇，吃劳碌得来的饭，本是枉然；惟有耶和华所亲爱的，必叫他安然睡觉。","notes":[]},{"n":3,"t":"看哪，儿女是耶和华所赐的产业，所怀的胎是他所给的赏赐。","notes":[]},{"n":4,"t":"人在年轻时生的儿女好像勇士手中的箭。","notes":[]},{"n":5,"t":"箭袋充满的人有福了！他们在城门口和仇敌争论时必不蒙羞。","notes":[]}]},"128":{"heading":"顺从耶和华的报偿","verses":[{"n":1,"t":"凡敬畏耶和华、遵行他道的人有福了！","notes":[]},{"n":2,"t":"你要吃劳碌得来的；你要享福，凡事顺利。","notes":[]},{"n":3,"t":"你妻子在你内室，好像多结果子的葡萄树；你儿女围绕你的桌子，如同橄榄树苗。","notes":[]},{"n":4,"t":"看哪，敬畏耶和华的人必要这样蒙福！","notes":[]},{"n":5,"t":"愿耶和华从锡安赐福给你！愿你一生一世看见耶路撒冷兴旺！","notes":[]},{"n":6,"t":"愿你看见你的子子孙孙！愿平安归于以色列！","notes":[]}]},"129":{"heading":"求耶和华退敌","verses":[{"n":1,"t":"说吧，以色列：“从我幼年以来，人屡次苦害我；","notes":[]},{"n":2,"t":"从我幼年以来，人屡次苦害我，却没有胜过我。","notes":[]},{"n":3,"t":"扶犁的人在我背上扶犁而耕，耕的犁沟很长。”","notes":[]},{"n":4,"t":"耶和华是公义的，他砍断了恶人的绳索。","notes":[]},{"n":5,"t":"愿恨恶锡安的都蒙羞退后！","notes":[]},{"n":6,"t":"愿他们像房顶上的草，一发芽就枯干，","notes":[]},{"n":7,"t":"收割的不够用手抓一把，捆禾的也不够抱满怀。","notes":[]},{"n":8,"t":"过路的也不说：“愿耶和华所赐的福归与你们！我们奉耶和华的名给你们祝福！”","notes":[]}]},"130":{"heading":"求助的祈祷","verses":[{"n":1,"t":"耶和华啊，我从深处求告你！","notes":[]},{"n":2,"t":"主啊，求你听我的声音！求你侧耳听我恳求的声音！","notes":[]},{"n":3,"t":"耶和华啊，你若究察罪孽，主啊，谁能站得住呢？","notes":[]},{"n":4,"t":"但在你有赦免之恩，要叫人敬畏你。","notes":[]},{"n":5,"t":"我等候耶和华，我的心等候；我也仰望他的话。","notes":[]},{"n":6,"t":"我的心等候主，胜于守夜的等候天亮，胜于守夜的等候天亮。","notes":[]},{"n":7,"t":"以色列啊，你当仰望耶和华，因耶和华有慈爱，有丰盛的救恩。","notes":[]},{"n":8,"t":"他必救赎以色列脱离一切的罪孽。","notes":[]}]},"131":{"heading":"谦卑靠主","verses":[{"n":1,"t":"耶和华啊，我的心不狂妄，我的眼不高傲；重大和测不透的事，我也不敢行。","notes":[]},{"n":2,"t":"我使我心安稳平静，好像母亲怀中断奶的孩子；我的心在我里面如同断过奶的孩子。","notes":[]},{"n":3,"t":"以色列啊，你当仰望耶和华，从今时直到永远！","notes":[]}]},"132":{"heading":"圣殿颂","verses":[{"n":1,"t":"耶和华啊，求你记念大卫，记念他所受的一切苦难！","notes":[]},{"n":2,"t":"他怎样向耶和华起誓，向雅各的大能者许愿：","notes":[]},{"n":3,"t":"“我必不进我的帐幕，也不上我的床铺；","notes":[]},{"n":4,"t":"我不容我的眼睛睡觉，也不容我的眼皮打盹；","notes":[]},{"n":5,"t":"直等到我为耶和华寻得所在，为雅各的大能者寻得居所。”","notes":[]},{"n":6,"t":"我们听说约柜在以法他，我们在雅珥的田野寻见它。","notes":["“雅珥”曾译“基列．耶琳”；“雅珥”意思是“森林”。"]},{"n":7,"t":"“我们要进他的居所，在他脚凳前下拜。”","notes":[]},{"n":8,"t":"耶和华啊，求你兴起，与你有能力的约柜同入安歇之所！","notes":[]},{"n":9,"t":"愿你的祭司披上公义！愿你的圣民欢呼！","notes":[]},{"n":10,"t":"求你因你仆人大卫的缘故，不要厌弃你的受膏者！","notes":[]},{"n":11,"t":"耶和华凭信实向大卫起了誓，绝不改变：“我要立你身所生的坐在你的宝座上。","notes":[]},{"n":12,"t":"你的众子若谨守我的约和我所教导他们的法度，他们的子孙必永远坐在你的宝座上。”","notes":[]},{"n":13,"t":"因为耶和华拣选了锡安，愿意当作自己的居所：","notes":[]},{"n":14,"t":"“这是我永远安歇之所；我要住在这地方，因为我愿意在这里。","notes":[]},{"n":15,"t":"我要赐福使粮食丰足，使其中的贫穷人饱享食物。","notes":[]},{"n":16,"t":"我要使祭司披上救恩，圣民就要大声欢呼！","notes":[]},{"n":17,"t":"在那里我要使大卫的角茁壮，为我的受膏者预备明灯。","notes":[]},{"n":18,"t":"我要使他的仇敌披上羞耻；但他的冠冕要在他头上发光。”","notes":[]}]},"133":{"heading":"弟兄相爱颂","verses":[{"n":1,"t":"看哪，弟兄和睦同住是何等的善，何等的美！","notes":[]},{"n":2,"t":"这好比那贵重的油浇在亚伦的头上，流到胡须，又流到他的衣襟；","notes":[]},{"n":3,"t":"又好比黑门的甘露降在锡安山；因为在那里有耶和华所命定的福，就是永远的生命。","notes":[]}]},"134":{"heading":"宣召称颂","verses":[{"n":1,"t":"来，称颂耶和华！夜间侍立在耶和华殿中，耶和华的仆人，","notes":[]},{"n":2,"t":"当向圣所举手，称颂耶和华！","notes":[]},{"n":3,"t":"愿造天地的耶和华从锡安赐福给你们！","notes":[]}]},"135":{"heading":"称颂的圣诗","verses":[{"n":1,"t":"哈利路亚！你们要赞美耶和华的名！侍立在耶和华殿中，耶和华的仆人，侍立在我们神殿院中的，要赞美他！","notes":[],"end":2},{"n":3,"t":"你们要赞美耶和华，因耶和华本为善；要歌颂他的名，因为这是美好的。","notes":[]},{"n":4,"t":"耶和华拣选雅各归自己，拣选以色列作他宝贵的产业。","notes":[]},{"n":5,"t":"我知道耶和华本为大，也知道我们的主超乎万神之上。","notes":[]},{"n":6,"t":"在天，在地，在海洋，在各深渊，耶和华都随自己的旨意而行。","notes":[]},{"n":7,"t":"他使云雾从地极上腾，造电随雨而闪，从仓库中吹出风来。","notes":[]},{"n":8,"t":"他将埃及头生的，连人带牲畜都击杀了。","notes":[]},{"n":9,"t":"埃及啊，他施行神迹奇事，在你们中间，在法老和他所有臣仆身上。","notes":[]},{"n":10,"t":"他击打许多国家，杀戮大能的君王，","notes":[]},{"n":11,"t":"就是亚摩利王西宏、巴珊王噩，和迦南一切的国度，","notes":[]},{"n":12,"t":"他赏赐他们的地为业，作为自己百姓以色列的产业。","notes":[]},{"n":13,"t":"耶和华啊，你的名字存到永远！耶和华啊，你的称号存到万代！","notes":["“称号”：原文是“纪念”。"]},{"n":14,"t":"耶和华要为自己的百姓伸冤，为自己的仆人发怜悯。","notes":[]},{"n":15,"t":"外邦的偶像是金的，是银的，是人手所造的，","notes":[]},{"n":16,"t":"有口却不能言，有眼却不能看，","notes":[]},{"n":17,"t":"有耳却不能听，口中也没有气息。","notes":[]},{"n":18,"t":"造它们的要像它们一样，凡靠它们的也必如此。","notes":[]},{"n":19,"t":"以色列家啊，要称颂耶和华！亚伦家啊，要称颂耶和华！","notes":[]},{"n":20,"t":"利未家啊，要称颂耶和华！你们敬畏耶和华的，要称颂耶和华！","notes":[]},{"n":21,"t":"住在耶路撒冷的、锡安的耶和华，是应当称颂的。哈利路亚！","notes":[]}]},"136":{"heading":"感恩的圣诗","verses":[{"n":1,"t":"你们要称谢耶和华，因他本为善；他的慈爱永远长存。","notes":[]},{"n":2,"t":"你们要称谢万神之神，因他的慈爱永远长存。","notes":[]},{"n":3,"t":"你们要称谢万主之主，因他的慈爱永远长存。","notes":[]},{"n":4,"t":"称谢那惟一能行大奇事的，因他的慈爱永远长存。","notes":["死海古卷和七十士译本没有“大”。"]},{"n":5,"t":"称谢那用智慧造天的，因他的慈爱永远长存。","notes":[]},{"n":6,"t":"称谢那铺地在水以上的，因他的慈爱永远长存。","notes":[]},{"n":7,"t":"称谢那造成大光的，因他的慈爱永远长存。","notes":[]},{"n":8,"t":"他造太阳管白昼，因他的慈爱永远长存。","notes":[]},{"n":9,"t":"他造月亮星宿管黑夜，因他的慈爱永远长存。","notes":[]},{"n":10,"t":"称谢那击杀埃及凡是头生的，因他的慈爱永远长存。","notes":[]},{"n":11,"t":"他以大能的手和伸出来的膀臂，因他的慈爱永远长存。领以色列人从埃及人中出来，因他的慈爱永远长存。","notes":[],"end":12},{"n":13,"t":"称谢那分裂红海的，因他的慈爱永远长存。","notes":[]},{"n":14,"t":"他领以色列从其中经过，因他的慈爱永远长存；","notes":[]},{"n":15,"t":"却把法老和他的军队推落红海里，因他的慈爱永远长存。","notes":[]},{"n":16,"t":"称谢那引导自己子民行走旷野的，因他的慈爱永远长存。","notes":[]},{"n":17,"t":"称谢那击杀大君王的，因他的慈爱永远长存。","notes":[]},{"n":18,"t":"他杀戮威武的君王，因他的慈爱永远长存；","notes":[]},{"n":19,"t":"杀戮亚摩利王西宏，因他的慈爱永远长存；","notes":[]},{"n":20,"t":"杀戮巴珊王噩，因他的慈爱永远长存。","notes":[]},{"n":21,"t":"他赏赐他们的地为业，因他的慈爱永远长存；","notes":[]},{"n":22,"t":"作为他仆人以色列的产业，因他的慈爱永远长存。","notes":[]},{"n":23,"t":"我们身处卑微，他顾念我们，因他的慈爱永远长存。","notes":[]},{"n":24,"t":"他搭救我们脱离敌人，因他的慈爱永远长存。","notes":[]},{"n":25,"t":"凡有血有肉的，他赐粮食，因他的慈爱永远长存。","notes":[]},{"n":26,"t":"你们要称谢天上的神，因他的慈爱永远长存。","notes":[]}]},"137":{"heading":"被掳的哀歌","verses":[{"n":1,"t":"我们在巴比伦河边，坐在那里，追想锡安，就哭了。","notes":[]},{"n":2,"t":"在一排柳树中，我们挂上我们的竖琴。","notes":[]},{"n":3,"t":"掳掠我们的在那里要我们唱歌；抢夺我们的要我们为他们作乐：“给我们唱一首锡安的歌吧！”","notes":[]},{"n":4,"t":"我们怎能在外邦之土唱耶和华的歌呢？","notes":[]},{"n":5,"t":"耶路撒冷啊，我若忘记你，宁愿我的右手枯萎；","notes":[]},{"n":6,"t":"我若不记得你，不看你过于我最喜乐的，宁愿我的舌头贴于上膛！","notes":[]},{"n":7,"t":"耶路撒冷攻破的日子，以东人说：“拆毁！拆毁！直拆到根基！”耶和华啊，求你记得！","notes":[]},{"n":8,"t":"将要被灭的巴比伦哪，用你待我们的恶行报复你的，那人有福了。","notes":["“巴比伦”：原文直译“巴比伦女子”。"]},{"n":9,"t":"抓起你的婴孩摔在磐石上的，那人有福了。","notes":[]}]},"138":{"heading":"感恩之祷","verses":[{"n":1,"t":"我要一心称谢你，在诸神面前歌颂你。","notes":["“我要一心称谢你”：有古卷和古译本是“耶和华啊！我要一心称谢你”。"]},{"n":2,"t":"我要向你的圣殿下拜，我要因你的慈爱和信实颂扬你的名；因你使你的名和你的言语显为大，超乎一切。","notes":["“因你...一切”：原文是“因你使你的言语大过你一切的名声”。"]},{"n":3,"t":"我呼求的日子，你应允我，使我壮胆，心里有能力。","notes":[]},{"n":4,"t":"耶和华啊，地上的君王都要称谢你，因他们听见了你口中的言语。","notes":[]},{"n":5,"t":"他们要歌颂耶和华的作为，因耶和华大有荣耀。","notes":[]},{"n":6,"t":"耶和华虽崇高，却看顾卑微的人；骄傲的人，他从远处即能认出。","notes":[]},{"n":7,"t":"我虽困在患难中，你必将我救活；我的仇敌发怒，你必伸手抵挡他们，你的右手也必拯救我。","notes":[]},{"n":8,"t":"耶和华必成全他在我身上的旨意；耶和华啊，你的慈爱永远长存！求你不要离弃你手所造的。","notes":[]}]},"139":{"heading":"耶和华的全知和眷顾","verses":[{"n":1,"t":"耶和华啊，你已经鉴察我，认识我。","notes":[]},{"n":2,"t":"我坐下，我起来，你都晓得；你从远处知道我的意念。","notes":[]},{"n":3,"t":"我行路，我躺卧，你都细察；你也深知我一切所行的。","notes":[]},{"n":4,"t":"耶和华啊，我舌头上的话，你没有一句不知道的。","notes":[]},{"n":5,"t":"你前后环绕我，按手在我身上。","notes":[]},{"n":6,"t":"这样的知识奇妙，是我不能测的；至高，是我不能及的。","notes":[]},{"n":7,"t":"我往哪里去，躲避你的灵？我往哪里逃，躲避你的面？","notes":[]},{"n":8,"t":"我若升到天上，你在那里；我若躺在阴间，你也在那里。","notes":[]},{"n":9,"t":"我若展开清晨的翅膀，飞到海极居住，","notes":[]},{"n":10,"t":"就是在那里，你的手必引导我，你的右手也必扶持我。","notes":[]},{"n":11,"t":"我若说“黑暗必定压碎我，我周围的亮光必成为黑夜”，","notes":[]},{"n":12,"t":"黑暗对你不再是黑暗，黑夜却如白昼发亮。黑暗和光明，在你看来都是一样。","notes":[]},{"n":13,"t":"我的肺腑是你所造的，我在母腹中，你已编织我。","notes":["“编织”或译“覆庇”。"]},{"n":14,"t":"我要称谢你，因我受造奇妙可畏，你的作为奇妙，这是我心深知道的。","notes":[]},{"n":15,"t":"我在暗中受造，在地的深处被塑造；那时，我的形体并不向你隐藏。","notes":[]},{"n":16,"t":"我未成形的体质，你的眼早已看见了；你所定的日子，我尚未度一日，都在你的册子写上了。","notes":[]},{"n":17,"t":"神啊，你的意念向我何等宝贵！其数何等众多！","notes":[]},{"n":18,"t":"我若数点，比海沙更多；我睡醒的时候，仍和你同在。","notes":[]},{"n":19,"t":"神啊，惟愿你杀戮恶人；你们好流人血的，离开我去吧！","notes":[]},{"n":20,"t":"他们说恶言顶撞你，你的仇敌妄称你的名。","notes":["原文没有“你的名”。"]},{"n":21,"t":"耶和华啊，恨恶你的，我岂不恨恶他们吗？攻击你的，我岂不憎恶他们吗？","notes":[]},{"n":22,"t":"我恨恶他们到极点，以他们为我的仇敌。","notes":[]},{"n":23,"t":"神啊，求你鉴察我，知道我的心思，试炼我，知道我的意念；","notes":[]},{"n":24,"t":"看在我里面有什么恶行没有，引导我走永生的道路。","notes":[]}]},"140":{"heading":"求耶和华护佑","verses":[{"n":1,"t":"耶和华啊，求你救我脱离邪恶的人，保护我脱离残暴的人！","notes":[]},{"n":2,"t":"他们心中图谋奸恶，日日不停挑起战争。","notes":[]},{"n":3,"t":"他们的舌头锐利如蛇，嘴唇里有毒蛇的毒液。（细拉）","notes":[]},{"n":4,"t":"耶和华啊，求你庇护我脱离恶人的手，保护我脱离残暴的人，他们想要推倒我。","notes":[]},{"n":5,"t":"骄傲的人为我暗设罗网和绳索；他们在路旁张开网，为我设下圈套。（细拉）","notes":[]},{"n":6,"t":"我曾对耶和华说：“你是我的神。”耶和华啊，求你侧耳听我恳求的声音！","notes":[]},{"n":7,"t":"主－耶和华、我救恩的力量啊，在战争的日子，你遮蔽了我的头。","notes":[]},{"n":8,"t":"耶和华啊，求你不要遂恶人的心愿；不要成就他们的计谋，免得他们自高。（细拉）","notes":[]},{"n":9,"t":"至于那些昂首围困我的人，愿他们嘴唇的奸恶陷害自己！","notes":["“陷害”：原文是“遮蔽”。"]},{"n":10,"t":"愿他们被丢在火中，火炭落在他们身上；愿他们被抛在深坑里，不能再起来！","notes":[]},{"n":11,"t":"愿说恶言的人在地上站立不住；愿祸患猎取残暴的人，把他打倒。","notes":[]},{"n":12,"t":"我知道耶和华必为困苦人伸冤，为贫穷人辩护。","notes":[]},{"n":13,"t":"义人必颂扬你的名，正直人要在你面前居住。","notes":[]}]},"141":{"heading":"晚 祷","verses":[{"n":1,"t":"耶和华啊，我曾求告你，求你快快临到我这里！我求告你的时候，求你侧耳听我的声音！","notes":[]},{"n":2,"t":"愿我的祷告如香呈到你面前！愿我的手举起，如献晚祭！","notes":["“手举起”：在此有“献供物”的意思。"]},{"n":3,"t":"耶和华啊，求你看守我的口，把守我的嘴唇！","notes":[]},{"n":4,"t":"不要使我的心偏向邪恶的事，以致我和作恶的人一同行恶；也不叫我吃他们的美食。","notes":[]},{"n":5,"t":"任凭义人击打我，这算为仁慈；任凭他责备我，这算为头上的膏油；我的头不躲闪。人正行恶的时候，我仍要祈祷。","notes":[]},{"n":6,"t":"他们的审判官被扔在岩下，他们就要听我的话，因为这话甘甜。","notes":[]},{"n":7,"t":"我们的骨头散落在阴间的口，就像人耕田刨地一样。","notes":["“我们的”：有古译本是“他们的”。","“人耕田刨地”：原文另译“磨石破裂”。"]},{"n":8,"t":"主－耶和华啊，我的眼目仰望你；我投靠你，求你不要使我的性命陷入危险！","notes":[]},{"n":9,"t":"求你保护我脱离恶人为我设的罗网和作恶之人的圈套！","notes":[]},{"n":10,"t":"愿恶人落在自己的网中，我却得以逃脱。","notes":[]}]},"142":{"heading":"求主眷顾","verses":[{"n":1,"t":"我出声哀告耶和华，出声恳求耶和华。","notes":[]},{"n":2,"t":"我在他面前倾诉我的苦情，在他面前陈说我的患难。","notes":[]},{"n":3,"t":"我的灵在我里面发昏的时候，你知道我的道路。在我所行的路上，人为我暗设罗网。","notes":[]},{"n":4,"t":"求你留意向我右边观看，无人认识我；我无避难之处，也无人眷顾我。","notes":[]},{"n":5,"t":"耶和华啊，我曾向你哀求。我说：“你是我的避难所，在活人之地，你是我的福分。”","notes":[]},{"n":6,"t":"求你留心听我的呼求，因我落到极卑微之地；求你救我脱离迫害我的人，因为他们比我强盛。","notes":[]},{"n":7,"t":"求你从被囚之地领我出来，我好颂扬你的名。义人必环绕我，因为你用厚恩待我。","notes":[]}]},"143":{"heading":"求主拯救","verses":[{"n":1,"t":"耶和华啊，求你听我的祷告，侧耳听我的恳求，凭你的信实和公义应允我。","notes":[]},{"n":2,"t":"求你不要审问仆人，因为在你面前，凡活着的人没有一个是义的。","notes":[]},{"n":3,"t":"因为仇敌迫害我，将我打倒在地，使我住在幽暗之处，像死了许久的人一样。","notes":[]},{"n":4,"t":"我的灵在我里面发昏，我的心在我里面颤栗。","notes":[]},{"n":5,"t":"我追想古时之日，思想你的一切作为，默念你手的工作。","notes":[]},{"n":6,"t":"我向你举手，我的心渴想你，如干旱之地盼雨一样。（细拉）","notes":[]},{"n":7,"t":"耶和华啊，求你速速应允我！我的心神耗尽！求你不要转脸不顾我，免得我像那些下入地府的人一样。","notes":[]},{"n":8,"t":"求你使我清晨得听你慈爱的声音，因我倚靠你；求你使我知道当走的路，因我的心仰望你。","notes":[]},{"n":9,"t":"耶和华啊，求你救我脱离我的仇敌！我往你那里藏身。","notes":[]},{"n":10,"t":"求你指教我遵行你的旨意，因你是我的神；愿你至善的灵引我到平坦之地。","notes":[]},{"n":11,"t":"耶和华啊，求你为你名的缘故将我救活，凭你的公义，将我从患难中领出来，","notes":[]},{"n":12,"t":"凭你的慈爱剪除我的仇敌，灭绝所有苦待我的人，因我是你的仆人。","notes":[]}]},"144":{"heading":"君王为胜利感恩","verses":[{"n":1,"t":"耶和华─我的磐石是应当称颂的！他教导我的手争战，教导我的指头打仗。","notes":[]},{"n":2,"t":"他是我慈爱的主、我的山寨、我的碉堡、我的救主、我的盾牌，是我所投靠的。他使我的百姓服在我以下。","notes":["“我的百姓”：有古卷是“列邦”。"]},{"n":3,"t":"耶和华啊，人算什么，你竟认识他！世人算什么，你竟顾念他！","notes":[]},{"n":4,"t":"人不过像一口气，他的年日如影消逝。","notes":[]},{"n":5,"t":"耶和华啊，求你使天下垂，亲自降临；求你摸山，使山冒烟。","notes":[]},{"n":6,"t":"求你发出闪电，使仇敌四散，射出你的箭，使他们混乱。","notes":[]},{"n":7,"t":"求你从高处伸手救拔我，救我脱离大水，脱离外邦人的手。","notes":[]},{"n":8,"t":"他们的口说谎话，他们的右手起假誓。","notes":[]},{"n":9,"t":"神啊，我要向你唱新歌，用十弦瑟向你歌颂。","notes":[]},{"n":10,"t":"你是那拯救君王的，你是那救仆人大卫脱离害命之刀的。","notes":[]},{"n":11,"t":"求你救拔我，救我脱离外邦人的手。他们的口说谎话，他们的右手起假誓。","notes":[]},{"n":12,"t":"我们的儿子从幼年好像树苗长大，我们的女儿如同房角石，按照建宫殿的样式凿成。","notes":[]},{"n":13,"t":"我们的仓盈满，能供应各种粮食；我们的羊在田野孳生千万。","notes":[]},{"n":14,"t":"我们的牲口驮满货物，没有人闯进来抢夺，也没有人出去争战；我们的街市上也没有哭号的声音。","notes":[]},{"n":15,"t":"这样情况的百姓有福了！以耶和华为他们神的百姓有福了！","notes":[]}]},"145":{"heading":"称颂之歌","verses":[{"n":1,"t":"我的神、我的王啊、我要尊崇你！我要永永远远称颂你的名！","notes":[]},{"n":2,"t":"我要天天称颂你，也要永永远远赞美你的名！","notes":[]},{"n":3,"t":"耶和华本为大，该受大赞美，其大无法测度。","notes":[]},{"n":4,"t":"这一代要对那一代颂赞你的作为，他们要传扬你的大能。","notes":[]},{"n":5,"t":"他们要述说你威严荣耀的尊荣，我要默念你奇妙的作为。","notes":["本节根据死海古卷；原文是“我要默念你威严荣耀的尊荣和你奇妙的作为”。"]},{"n":6,"t":"人要传讲你可畏的能力，我也要传扬你的伟大。","notes":[]},{"n":7,"t":"他们要将你可记念的大恩传开，并要高唱你的公义。","notes":[]},{"n":8,"t":"耶和华有恩惠，有怜悯，不轻易发怒，大有慈爱。","notes":[]},{"n":9,"t":"耶和华善待万有，他的怜悯覆庇他一切所造的。","notes":[]},{"n":10,"t":"耶和华啊，你一切所造的都要称谢你，你的圣民也要称颂你。","notes":[]},{"n":11,"t":"他们要传讲你国度的荣耀，谈论你的大能，","notes":[]},{"n":12,"t":"好让世人知道你大能的作为和你国度威严的荣耀。","notes":[]},{"n":13,"t":"你的国是永远的国！你执掌的权柄存到万代！耶和华一切的话信实可靠，他一切的作为都有慈爱。","notes":["“耶和华...慈爱”是根据死海古卷、七十士译本和其他古译本；原文无此句。"]},{"n":14,"t":"耶和华扶起所有跌倒的，扶起所有被压下的。","notes":[]},{"n":15,"t":"万有的眼目都仰望你，你按时给他们食物。","notes":[]},{"n":16,"t":"你张手，使一切有生命的都随愿饱足。","notes":[]},{"n":17,"t":"耶和华一切所行的，无不公义，一切所做的，都有慈爱。","notes":[]},{"n":18,"t":"耶和华临近凡求告他的，临近所有诚心求告他的人。","notes":[]},{"n":19,"t":"敬畏他的，他必成就他们的心愿，也必听他们的呼求，拯救他们。","notes":[]},{"n":20,"t":"耶和华保护凡爱他的人，却要灭绝所有的恶人。","notes":[]},{"n":21,"t":"我的口要述说赞美耶和华的话；惟愿有血肉之躯的都永永远远称颂他的圣名。","notes":[]}]},"146":{"heading":"赞美耶和华的救助","verses":[{"n":1,"t":"哈利路亚！我的心哪，你要赞美耶和华！","notes":[]},{"n":2,"t":"我一生要赞美耶和华！我还活着的时候要歌颂我的神！","notes":[]},{"n":3,"t":"你们不要倚靠君王，不要倚靠世人，他一点也不能帮助。","notes":[]},{"n":4,"t":"他的气一断，就归回尘土，他所打算的，当日就消灭了。","notes":[]},{"n":5,"t":"以雅各的神为帮助、仰望耶和华－他神的，这人有福了！","notes":[]},{"n":6,"t":"耶和华造天、地、海和其中的万物，他守信实，直到永远。","notes":[]},{"n":7,"t":"他为受欺压的伸冤，赐食物给饥饿的人。耶和华释放被囚的，","notes":[]},{"n":8,"t":"耶和华开了盲人的眼睛，耶和华扶起被压下的人，耶和华喜爱义人。","notes":[]},{"n":9,"t":"耶和华保护寄居的，扶持孤儿和寡妇，却使恶人的道路弯曲。","notes":[]},{"n":10,"t":"耶和华要作王，直到永远！锡安哪，你的神要作王，直到万代！哈利路亚！","notes":[]}]},"147":{"heading":"赞美神的全能","verses":[{"n":1,"t":"哈利路亚！歌颂我们的神是美善的，因为他是美好的，赞美他是合宜的。","notes":[]},{"n":2,"t":"耶和华建造耶路撒冷，聚集以色列中被赶散的人。","notes":[]},{"n":3,"t":"他医好伤心的人，包扎他们的伤处。","notes":[]},{"n":4,"t":"他数点星宿的数目，一一称它们的名。","notes":[]},{"n":5,"t":"我们的主本为大，大有能力，他的智慧无法测度。","notes":[]},{"n":6,"t":"耶和华扶持谦卑的人，将恶人倾覆于地。","notes":[]},{"n":7,"t":"你们要以感谢向耶和华歌唱，用琴向我们的神歌颂。","notes":[]},{"n":8,"t":"他用密云遮天，为地预备雨水，使草生长在山上。","notes":[]},{"n":9,"t":"他赐食物给走兽和啼叫的小乌鸦。","notes":[]},{"n":10,"t":"他不喜悦马的力大，不喜爱人的腿快。","notes":[]},{"n":11,"t":"耶和华喜爱敬畏他和盼望他慈爱的人。","notes":[]},{"n":12,"t":"耶路撒冷啊，要颂赞耶和华！锡安哪，要赞美你的神！","notes":[]},{"n":13,"t":"因为他坚固了你的门闩，赐福给你中间的儿女。","notes":[]},{"n":14,"t":"他使你境内平安，用上好的麦子使你满足。","notes":[]},{"n":15,"t":"他向大地发出命令，他的话速速颁行。","notes":[]},{"n":16,"t":"他降雪如羊毛，撒霜如灰烬。","notes":[]},{"n":17,"t":"他掷下冰雹如碎渣，他发出寒冷，谁能当得起呢？","notes":[]},{"n":18,"t":"他一出令，这些就都融化，他使风刮起，水便流动。","notes":[]},{"n":19,"t":"他将他的道指示雅各，将他的律例典章指示以色列。","notes":[]},{"n":20,"t":"他未曾这样对待别国，至于他的典章，他们向来都不知道。哈利路亚！","notes":["“他们向来都不知道”：有古译本是“他没有让他们知道”。"]}]},"148":{"heading":"宣召万有赞美耶和华","verses":[{"n":1,"t":"哈利路亚！你们要从天上赞美耶和华，在高处赞美他！","notes":[]},{"n":2,"t":"他的众使者啊，要赞美他！他的诸军啊，都要赞美他！","notes":[]},{"n":3,"t":"太阳月亮啊，要赞美他！放光的星宿啊，都要赞美他！","notes":[]},{"n":4,"t":"天上的天和天上的水啊，你们都要赞美他！","notes":[]},{"n":5,"t":"愿这些都赞美耶和华的名！因他一吩咐就都造成。","notes":[]},{"n":6,"t":"他将这些设定，直到永永远远；他订了律例，不能废去。","notes":[]},{"n":7,"t":"你们哪，都当赞美耶和华：地上一切所有的，大鱼和深洋，","notes":[]},{"n":8,"t":"火和冰雹，雪和雾气，成就他命令的狂风，","notes":[]},{"n":9,"t":"大山和小山，结果子的树木和一切香柏树，","notes":[]},{"n":10,"t":"野兽和一切牲畜，昆虫和飞鸟，","notes":[]},{"n":11,"t":"世上的君王和万民，领袖和世上所有的审判官，","notes":[]},{"n":12,"t":"少年和少女，老人和孩童，","notes":[]},{"n":13,"t":"愿这些都赞美耶和华的名！因为独有他的名被尊崇，他的荣耀在天地之上。","notes":[]},{"n":14,"t":"他高举自己百姓的角，使他的圣民以色列人，就是与他相近的百姓得荣耀。哈利路亚！","notes":["“使...得荣耀”或译“他一切圣民以色列人， 就是与他相近的百姓，都赞美他”。"]}]},"149":{"heading":"赞美的圣诗","verses":[{"n":1,"t":"哈利路亚！你们要向耶和华唱新歌，在圣民的会中赞美他！","notes":[]},{"n":2,"t":"愿以色列因造他的主欢喜！愿锡安的民因他们的王快乐！","notes":[]},{"n":3,"t":"愿他们跳舞赞美他的名，击鼓弹琴歌颂他！","notes":[]},{"n":4,"t":"因为耶和华喜爱自己的百姓，他要用救恩当作谦卑人的妆饰。","notes":[]},{"n":5,"t":"愿圣民因所得的荣耀欢乐！愿他们在床上也欢呼！","notes":[]},{"n":6,"t":"愿他们口中称颂神为至高，手里有两刃的剑，","notes":[]},{"n":7,"t":"为要报复列国，惩罚万民。","notes":[]},{"n":8,"t":"要用链子捆他们的君王，用铁镣锁他们的贵族，","notes":[]},{"n":9,"t":"要在他们身上施行所记录的审判。他的圣民都享荣耀。哈利路亚！","notes":[]}]},"150":{"heading":"赞美耶和华","verses":[{"n":1,"t":"哈利路亚！你们要在神的圣所赞美他！在他显能力的穹苍赞美他！","notes":[]},{"n":2,"t":"要因他大能的作为赞美他，因他极其伟大赞美他！","notes":[]},{"n":3,"t":"要用角声赞美他，鼓瑟弹琴赞美他！","notes":[]},{"n":4,"t":"击鼓跳舞赞美他！用丝弦的乐器和箫的声音赞美他！","notes":[]},{"n":5,"t":"用大响的钹赞美他！用高声的钹赞美他！","notes":[]},{"n":6,"t":"凡有生命的都要赞美耶和华！哈利路亚！","notes":[]}]}},"PRO":{"1":{"heading":"箴言的价值","verses":[{"n":1,"t":"大卫的儿子，以色列王所罗门的箴言：","notes":[]},{"n":2,"t":"要使人懂得智慧和训诲，明白通达的言语，","notes":[]},{"n":3,"t":"使人领受明智的训诲，就是公义、公平和正直，","notes":[]},{"n":4,"t":"使愚蒙人灵巧，使年轻人有知识，有智谋。","notes":[]},{"n":5,"t":"智慧人听见，增长学问，聪明人得着智谋，","notes":[]},{"n":6,"t":"明白箴言和譬喻，懂得智慧人的言词和谜语。","notes":[]},{"n":7,"t":"敬畏耶和华是知识的开端；愚妄人藐视智慧和训诲。","notes":[]},{"n":8,"t":"我儿啊，要听你父亲的训诲，不可离弃你母亲的教诲；","notes":[],"heads":["给年轻人的忠告"]},{"n":9,"t":"因为这要作你头上恩惠的华冠，作你颈上的项链。","notes":[]},{"n":10,"t":"我儿啊，罪人若引诱你，你不可随从。","notes":[]},{"n":11,"t":"他们若说：“你与我们同去，我们要埋伏杀人流血，无故地潜藏，杀害无辜；","notes":[]},{"n":12,"t":"我们好像阴间，把他们活活吞下，囫囵吞下，如吞下那下到地府的人；","notes":[]},{"n":13,"t":"我们必得各样宝物，将所夺来的装满房屋；","notes":[]},{"n":14,"t":"你来与我们同伙，共用一个钱囊。”","notes":[]},{"n":15,"t":"我儿啊，不要与他们走同一道路，禁止你的脚走他们的路径。","notes":[]},{"n":16,"t":"因为他们的脚奔跑行恶，他们急速杀人流血。","notes":[]},{"n":17,"t":"在飞鸟眼前张设网罗，一定会徒劳无功；","notes":[]},{"n":18,"t":"同样，他们埋伏，是自流己血，他们潜藏，是自害己命。","notes":[]},{"n":19,"t":"凡靠暴力敛财的，所行之路都是如此，这种念头必夺去自己的生命。","notes":[]},{"n":20,"t":"智慧在街市上呼喊，在广场上高声呐喊，","notes":["“智慧”是拟人化的名词，原文是阴性；下同。"],"heads":["智慧呼唤人"]},{"n":21,"t":"在热闹街头呼叫，在城门口，在城中，发出言语，说：","notes":[]},{"n":22,"t":"“你们无知的人喜爱无知，傲慢人喜欢傲慢，愚昧人恨恶知识，要到几时呢？","notes":[]},{"n":23,"t":"你们当因我的责备回转，我要将我的灵浇灌你们，将我的话指示你们。","notes":[]},{"n":24,"t":"因为我呼唤，你们不听，我招手，无人理会。","notes":[]},{"n":25,"t":"你们忽视我一切的劝戒，拒听我的责备。","notes":[]},{"n":26,"t":"你们遭难，我就发笑；惊恐临到你们，惊恐如狂风来临，灾难好像暴风来到，急难痛苦临到你们身上，我必嗤笑。","notes":[],"end":27},{"n":28,"t":"那时，他们就会呼求我，我却不回答，恳切寻求我，却寻不见。","notes":[]},{"n":29,"t":"因为他们恨恶知识，选择不敬畏耶和华，","notes":[]},{"n":30,"t":"不听我的劝戒，藐视我一切的责备，","notes":[]},{"n":31,"t":"所以他们要自食其果，饱胀在自己的计谋中。","notes":[]},{"n":32,"t":"愚蒙人背道，害死自己，愚昧人安逸，自取灭亡。","notes":[]},{"n":33,"t":"惟听从我的，必安然居住，得享宁静，不怕灾祸。”","notes":[]}]},"2":{"heading":"智慧的赏赐","verses":[{"n":1,"t":"我儿啊，你若领受我的言语，珍藏我的命令，","notes":[]},{"n":2,"t":"留心听智慧，专心求聪明；","notes":[]},{"n":3,"t":"你若呼求明理，扬声求聪明，","notes":[]},{"n":4,"t":"寻找她，如寻找银子，搜寻她，如搜寻宝藏，","notes":[]},{"n":5,"t":"你就懂得敬畏耶和华，得以认识神。","notes":[]},{"n":6,"t":"因为耶和华赏赐智慧，知识和聪明都由他口而出。","notes":[]},{"n":7,"t":"他为正直人珍藏健全的知识，给行为纯正的人作盾牌，","notes":[]},{"n":8,"t":"为要保护公正的路，庇护虔诚人的道。","notes":[]},{"n":9,"t":"那时，你就明白公义、公平、正直，和一切完善的道路。","notes":[]},{"n":10,"t":"因为智慧要进入你的心，知识要使你内心欢愉。","notes":[]},{"n":11,"t":"智谋要庇护你，聪明必保护你，","notes":[]},{"n":12,"t":"救你脱离恶人的道，脱离言谈乖谬的人。","notes":[]},{"n":13,"t":"他们离弃正直的路，行走黑暗的道，","notes":[]},{"n":14,"t":"喜欢作恶，喜爱恶人的错谬。","notes":[]},{"n":15,"t":"他们的路歪曲，他们偏离中道。","notes":[]},{"n":16,"t":"智慧要救你远离陌生女子，远离那油嘴滑舌的外邦女子。","notes":[]},{"n":17,"t":"她离弃年轻时的配偶，忘了自己神圣的盟约。","notes":[]},{"n":18,"t":"她的家陷入死亡，她的路偏向阴魂。","notes":[]},{"n":19,"t":"凡到她那里去的，不得回转，也得不到生命的路。","notes":[]},{"n":20,"t":"智慧使你行善人的道，守义人的路。","notes":[]},{"n":21,"t":"正直人必在地上居住，完全人必在其上存留；","notes":[]},{"n":22,"t":"惟恶人要从地上剪除，奸诈人要被拔出。","notes":[]}]},"3":{"heading":"给年轻人的忠告","verses":[{"n":1,"t":"我儿啊，不要忘记我的教诲，你的心要谨守我的命令，","notes":[]},{"n":2,"t":"因为它们必加给你长久的日子，生命的年数与平安。","notes":["“它们”指“教诲”和“命令”。"]},{"n":3,"t":"不可使慈爱和诚信离开你，要系在你颈项上，刻在你心版上。","notes":[]},{"n":4,"t":"这样，你必在神和世人眼前蒙恩惠，有美好的见识。","notes":[]},{"n":5,"t":"你要专心仰赖耶和华，不可倚靠自己的聪明，","notes":[]},{"n":6,"t":"在你一切所行的路上都要认定他，他必使你的道路平直。","notes":[]},{"n":7,"t":"不要自以为有智慧；要敬畏耶和华，远离恶事。","notes":[]},{"n":8,"t":"这便医治你的肉体，滋润你的百骨。","notes":["“肉体”：原文是“肚脐”。"]},{"n":9,"t":"你要以财物和一切初熟的土产尊崇耶和华，","notes":[]},{"n":10,"t":"这样，你的仓库必充满有余，你的酒池有新酒盈溢。","notes":[]},{"n":11,"t":"我儿啊，不可轻看耶和华的管教，也不可厌烦他的责备，","notes":[]},{"n":12,"t":"因为耶和华所爱的，他必责备，正如父亲责备所喜爱的儿子。","notes":[]},{"n":13,"t":"得智慧，得聪明的，这人有福了。","notes":[]},{"n":14,"t":"因为智慧的获利胜过银子，所得的盈余强如金子，","notes":[]},{"n":15,"t":"比宝石更宝贵，你一切所喜爱的，都不足与其比较。","notes":["“宝石”或译“珍珠”；本卷书下同。"]},{"n":16,"t":"她的右手有长寿，左手有富贵。","notes":[]},{"n":17,"t":"她的道是安乐，她的路全是平安。","notes":[]},{"n":18,"t":"她给持守她的人作生命树，谨守她的必定蒙福。","notes":[]},{"n":19,"t":"耶和华以智慧奠立地基，以聪明铺设诸天，","notes":[]},{"n":20,"t":"以知识使深渊裂开，使天空滴下甘露。","notes":[]},{"n":21,"t":"我儿啊，要谨守健全的知识和智谋，不可使它们偏离你的眼目。","notes":[]},{"n":22,"t":"这样，它们必使你的生命有活力，又作你颈项的美饰。","notes":[]},{"n":23,"t":"那时，你就坦然行路，不致跌倒。","notes":[]},{"n":24,"t":"你躺下，必不惧怕；你躺卧，睡得香甜。","notes":[]},{"n":25,"t":"忽然来的惊恐，你不要害怕；恶人遭毁灭，也不要恐惧，","notes":[]},{"n":26,"t":"因为耶和华是你的倚靠，他必保护你的脚不陷入罗网。","notes":[]},{"n":27,"t":"你的手若有行善的力量，不可推辞，要施与那应得的人。","notes":[]},{"n":28,"t":"你若手头方便，不可对邻舍说：“去吧，明天再来，我必给你。”","notes":[]},{"n":29,"t":"你的邻舍既在你附近安居，不可设计害他。","notes":[]},{"n":30,"t":"人若未曾加害你，不可无故与他相争。","notes":[]},{"n":31,"t":"不可嫉妒残暴的人，不可选择他的任何道路。","notes":[]},{"n":32,"t":"因为走偏方向的人是耶和华所憎恶的；正直人为他所亲密。","notes":[]},{"n":33,"t":"耶和华诅咒恶人的家；义人的居所他却赐福。","notes":[]},{"n":34,"t":"他讥诮那爱讥诮的人；但赐恩给谦卑的人。","notes":[]},{"n":35,"t":"智慧人必承受尊荣；愚昧人高升却是羞辱。","notes":[]}]},"4":{"heading":"智慧的益处","verses":[{"n":1,"t":"孩子们，要听父亲的训诲，留心明白道理。","notes":[]},{"n":2,"t":"因我给你们好的教导，不可离弃我的教诲。","notes":[]},{"n":3,"t":"当我在父亲面前还是小孩，是母亲独一娇儿的时候，","notes":[]},{"n":4,"t":"他教导我说：“你的心要持守我的话，遵守我的命令，你就会存活。","notes":[]},{"n":5,"t":"要获得智慧，要获得聪明，不可忘记， 也不可偏离我口中的言语。","notes":[]},{"n":6,"t":"不可离弃智慧，智慧就庇护你，要爱她，她就保护你。","notes":[]},{"n":7,"t":"智慧为首，所以要获得智慧，要用你一切所有的换取聪明。","notes":[]},{"n":8,"t":"高举智慧，她就使你升高，拥抱智慧，她就使你尊荣。","notes":[]},{"n":9,"t":"她必将恩惠的华冠加在你头上，把荣冕赐给你。”","notes":[]},{"n":10,"t":"我儿啊，要听，要领受我的言语，你就必延年益寿。","notes":[]},{"n":11,"t":"我已指教你走智慧的道，引导你行正直的路。","notes":[]},{"n":12,"t":"你行走，脚步没有阻碍；你奔跑，也不致跌倒。","notes":[]},{"n":13,"t":"要持定训诲，不可放松；要谨守它，因为它是你的生命。","notes":[]},{"n":14,"t":"不可行恶人的路，不要走坏人的道；","notes":[]},{"n":15,"t":"要躲避，不可经过，要转离而去。","notes":[]},{"n":16,"t":"他们若不行恶，难以成眠，不使人跌倒，就睡卧不安；","notes":[]},{"n":17,"t":"因为他们以邪恶当饼吃，以暴力当酒喝。","notes":[]},{"n":18,"t":"但义人的路好像黎明的光，越照越明，直到正午。","notes":[]},{"n":19,"t":"恶人的道幽暗，自己不知因何跌倒。","notes":[]},{"n":20,"t":"我儿啊，要留心听我的话，侧耳听我的言语，","notes":[]},{"n":21,"t":"不可使它们偏离你的眼目，要存记在你心中。","notes":[]},{"n":22,"t":"因为找到它们的，就找到生命，得到全身的医治。","notes":[]},{"n":23,"t":"你要保守你心，胜过保守一切，因为生命的泉源由心发出。","notes":[]},{"n":24,"t":"要离开歪曲的口，转离偏邪的嘴唇。","notes":[]},{"n":25,"t":"你的两眼要向前看，你的双目直视前方。","notes":["“双目”：原文是“眼皮”。"]},{"n":26,"t":"要修平你脚下的路，你一切的道就必稳固。","notes":["“修平”或译“察验”。"]},{"n":27,"t":"不可偏左偏右，你的脚要离开邪恶。","notes":[]}]},"5":{"heading":"警告勿犯淫乱","verses":[{"n":1,"t":"我儿啊，要留心听我的智慧，侧耳听我的聪明，","notes":[]},{"n":2,"t":"为要使你谨守智谋，嘴唇保护知识。","notes":[]},{"n":3,"t":"因为陌生女子的嘴唇滴下蜂蜜，她的口比油更滑，","notes":[]},{"n":4,"t":"后来却苦似茵陈，锐利如两刃的剑。","notes":[]},{"n":5,"t":"她的脚坠落死亡，她的脚步踏入阴间，","notes":[]},{"n":6,"t":"她无法找到生命的道路，她的路变迁不定，自己却不知道。","notes":[]},{"n":7,"t":"孩子们，现在要听从我，不可离弃我口中的言语。","notes":[]},{"n":8,"t":"你所行的道要远离她，不可靠近她家的门口，","notes":[]},{"n":9,"t":"免得将你的尊荣给别人，将你的岁月给残忍的人；","notes":[]},{"n":10,"t":"免得陌生人满得你的财富，你劳苦所得的归入外邦人的家。","notes":[]},{"n":11,"t":"在你人生终结，你皮肉和身体衰残时，你必唉声叹气，","notes":[]},{"n":12,"t":"说：“我为何恨恶管教，心里轻看责备呢？","notes":[]},{"n":13,"t":"我不听从教师的话，也没有侧耳听那教导我的。","notes":[]},{"n":14,"t":"在聚集的会众中，我几乎坠入深渊。”","notes":[]},{"n":15,"t":"你要喝自己池中的水，饮自己井里的活水。","notes":[]},{"n":16,"t":"你的泉源岂可溢流在外？你的河水岂可流到街上？","notes":[]},{"n":17,"t":"让它们惟独归你，不可与陌生人同享。","notes":[]},{"n":18,"t":"要使你的泉源蒙福，要喜爱你年轻时的妻子。","notes":[]},{"n":19,"t":"她如可爱的母鹿，如优美的母羊，愿她的胸怀使你时时满足，愿你常常迷恋她的爱情。","notes":[]},{"n":20,"t":"我儿啊，你为何迷恋陌生女子？为何拥抱外邦女子的胸怀？","notes":[]},{"n":21,"t":"因为人所行的道都在耶和华眼前，他察验人一切的路。","notes":["“察验”或译“修平”。"]},{"n":22,"t":"恶人被自己的罪孽抓住，被自己罪恶的绳索缠绕。","notes":[]},{"n":23,"t":"他因不受管教而死亡，因极度愚昧而走迷。","notes":[]}]},"6":{"heading":"更多的警告","verses":[{"n":1,"t":"我儿啊，你若为朋友担保，替陌生人击掌，","notes":[]},{"n":2,"t":"你就被口中的言语套住，被嘴里的言语抓住。","notes":[]},{"n":3,"t":"我儿啊，你既落在朋友手中，当这样行才可救自己：你要谦卑自己，去恳求你的朋友。","notes":[]},{"n":4,"t":"不要让你的眼睛睡觉，不可容你的眼皮打盹。","notes":[]},{"n":5,"t":"要救自己，如羚羊脱离猎人的手，如鸟脱离捕鸟人的手。","notes":[]},{"n":6,"t":"懒惰人哪，你去察看蚂蚁的动作，就可得智慧。","notes":[]},{"n":7,"t":"蚂蚁没有领袖，没有官长，没有君王，","notes":[]},{"n":8,"t":"尚且在夏天预备食物，在收割时储存粮食。","notes":[]},{"n":9,"t":"懒惰人哪，你要睡到几时呢？你什么时候才睡醒呢？","notes":[]},{"n":10,"t":"再睡片时，打盹片时，抱着双臂躺卧片时，","notes":[]},{"n":11,"t":"你的贫穷就如盗贼来到，你的贫乏仿佛拿盾牌的人来临。","notes":[]},{"n":12,"t":"无赖的恶徒行事全凭歪曲的口，","notes":[]},{"n":13,"t":"他眨眼传神，以脚示意，用指点划，","notes":[]},{"n":14,"t":"存心乖谬，常设恶谋，散播纷争。","notes":[]},{"n":15,"t":"所以，灾难必突然临到他，他必顷刻被毁，无从医治。","notes":[]},{"n":16,"t":"耶和华所恨恶的有六样，他心所憎恶的共有七样：","notes":[]},{"n":17,"t":"就是高傲的眼，撒谎的舌，杀害无辜的手，","notes":[]},{"n":18,"t":"图谋恶计的心，飞奔行恶的脚，","notes":[]},{"n":19,"t":"口吐谎言的假证人，并在弟兄间散播纷争的人。","notes":[]},{"n":20,"t":"我儿啊，要遵守你父亲的命令，不可离弃你母亲的教诲。","notes":[],"heads":["警告勿犯淫乱"]},{"n":21,"t":"要常挂在你心上，系在你颈项上。","notes":[]},{"n":22,"t":"你行走，她必引导你，你躺卧，她必保护你，你睡醒，她必与你谈论。","notes":[]},{"n":23,"t":"因为诫命是灯，教诲是光，管教的责备是生命的道，","notes":[]},{"n":24,"t":"要保护你远离邪恶的妇女，远离外邦女子谄媚的舌头。","notes":[]},{"n":25,"t":"你不要因她的美色而动心，也不要被她的眼皮勾引。","notes":[]},{"n":26,"t":"因为连最后一块饼都会被妓女拿走；有夫之妇会猎取宝贵的生命。","notes":["“连最后一块饼都会被妓女拿走”或译“妓女的雇价只是一块饼”。"]},{"n":27,"t":"人若兜火在怀中，他的衣服岂能不烧着呢？","notes":[]},{"n":28,"t":"人若走在火炭上，他的脚岂能不烫伤呢？","notes":[]},{"n":29,"t":"与邻舍之妻同寝的，也是如此，凡亲近她的，难免受罚。","notes":[]},{"n":30,"t":"贼因饥饿偷窃充饥，人不藐视他，","notes":[]},{"n":31,"t":"但若被抓到，要赔偿七倍，他必赔上家中一切财物。","notes":[]},{"n":32,"t":"与妇人行奸淫的，便是无知，做这事的，必毁了自己。","notes":[]},{"n":33,"t":"他必受损伤和羞辱，他的羞耻不得消除。","notes":[]},{"n":34,"t":"丈夫因嫉恨发怒，报仇的时候绝不留情。","notes":[]},{"n":35,"t":"他不接受任何赔偿，你送许多礼物，他也不肯和解。","notes":[]}]},"7":{"heading":"淫乱的妇人","verses":[{"n":1,"t":"我儿啊，要遵守我的言语，存记我的命令。","notes":[]},{"n":2,"t":"遵守我的命令就得存活，谨守我的教诲，好像保护眼中的瞳人。","notes":[]},{"n":3,"t":"要系在你指头上，刻在你心版上。","notes":[]},{"n":4,"t":"对智慧说“你是我的姊妹”，称呼聪明为亲人，","notes":[]},{"n":5,"t":"她就保护你远离陌生女子，远离油嘴滑舌的外邦女子。","notes":[]},{"n":6,"t":"我曾在我房屋的窗户内，透过窗格子往外观看，","notes":[]},{"n":7,"t":"看见在愚蒙人中，注意到孩儿中有一个无知的青年，","notes":[]},{"n":8,"t":"从街上经过，靠近她的巷口，直往她家的路去，","notes":[]},{"n":9,"t":"在黄昏，在傍晚，在半夜，黑暗之中。","notes":[]},{"n":10,"t":"看哪，有一个女子来迎接他，是妓女的打扮，有诡诈的心思。","notes":[]},{"n":11,"t":"她喧嚷，不守约束，她的脚在家里留不住，","notes":[]},{"n":12,"t":"有时在街市，有时在广场，或在各巷口等候。","notes":[]},{"n":13,"t":"她拉住那青年吻他，厚着脸皮对他说：","notes":[]},{"n":14,"t":"“我已献了平安祭，今日我还了所许的愿。","notes":[]},{"n":15,"t":"因此，我出来迎接你，渴望见你的面，我总算找到你了！","notes":[]},{"n":16,"t":"我已在床上铺好被单，是埃及麻织的花纹布，","notes":[]},{"n":17,"t":"又用没药、沉香、桂皮薰了我的床。","notes":[]},{"n":18,"t":"你来，让我们饱享爱情，直到早晨，让我们彼此亲爱欢乐。","notes":[]},{"n":19,"t":"因为我丈夫不在家，出门远行，","notes":[]},{"n":20,"t":"他手带钱囊，要到月圆才回家。”","notes":[]},{"n":21,"t":"这女子用许多巧言引诱他，用谄媚的嘴唇催逼他。","notes":[]},{"n":22,"t":"青年立刻跟随她，好像牛去被宰杀，又像愚妄人带着脚镣去受刑，","notes":[]},{"n":23,"t":"直到箭穿进他的肝，如同雀鸟急投罗网，却不知会赔上自己的生命。","notes":[]},{"n":24,"t":"孩子们，现在要听从我，要留心听我口中的言语。","notes":[]},{"n":25,"t":"你的心不可偏向她的道，不要误入她的迷途。","notes":[]},{"n":26,"t":"因为她击倒许多人，无数的人被她杀戮。","notes":["“无数的人被她杀戮”或译“被她杀戮的都是强壮者”。"]},{"n":27,"t":"她的家是在阴间之路，下到死亡之宫。","notes":[]}]},"8":{"heading":"智慧颂","verses":[{"n":1,"t":"智慧岂不呼唤？聪明岂不扬声？","notes":[]},{"n":2,"t":"她站立在十字路口，在道路旁高处的顶上，","notes":[]},{"n":3,"t":"在城门旁，城门口，入口处，她呼喊：","notes":[]},{"n":4,"t":"“人哪，我呼唤你们，我向世人扬声。","notes":[]},{"n":5,"t":"愚蒙人哪，你们要学习灵巧，愚昧人哪，你们的心要明辨。","notes":[]},{"n":6,"t":"你们当听，因我要说尊贵的事，我要张开嘴唇讲正直的事。","notes":[]},{"n":7,"t":"我的口要发出真理，我的嘴唇憎恶邪恶。","notes":[]},{"n":8,"t":"我口中的言语都是公义，并无奸诈和歪曲。","notes":[]},{"n":9,"t":"聪明人看为正确，有知识的，都以为正直。","notes":[]},{"n":10,"t":"你们当领受我的训诲，胜过领受银子，宁得知识，强如得上选的金子。","notes":[]},{"n":11,"t":"“因为智慧比宝石更美，一切可喜爱的都不足与其比较。","notes":[]},{"n":12,"t":"我－智慧以灵巧为居所，又寻得知识和智谋。","notes":[]},{"n":13,"t":"敬畏耶和华就是恨恶邪恶；我恨恶骄傲、狂妄、恶道，和乖谬的口。","notes":[]},{"n":14,"t":"我有策略和健全的知识，我聪明，又有能力。","notes":[]},{"n":15,"t":"君王藉我治国，王子藉我定公平，","notes":[]},{"n":16,"t":"王公贵族，所有公义的审判官，都藉我掌权。","notes":["本节七十士译本是“贵族因我而尊大，君王藉着我统治土地”。"]},{"n":17,"t":"爱我的，我也爱他，恳切寻求我的，必寻见。","notes":[]},{"n":18,"t":"财富和尊荣在我，恒久的财宝和繁荣也在我。","notes":["“繁荣”或译“公义”。"]},{"n":19,"t":"我的果实胜过金子，强如纯金，我的出产超乎上选的银子。","notes":[]},{"n":20,"t":"我在公义的道上走，在公平的路中行，","notes":[]},{"n":21,"t":"使爱我的承受财产，充满他们的库房。","notes":[]},{"n":22,"t":"“耶和华在造化的起头，在太初创造万物之先，就有了我。","notes":["“有”或译“造”。"]},{"n":23,"t":"从亘古，从太初，未有大地以前，我已被立。","notes":[]},{"n":24,"t":"没有深渊，没有大水的泉源，我已出生。","notes":[]},{"n":25,"t":"大山未曾奠定，小山未有之先，我已出生。","notes":[]},{"n":26,"t":"那时，他还没有创造大地和田野，并世上头一撮尘土。","notes":[]},{"n":27,"t":"他立高天，我在那里，他在渊面的周围划出圆圈，","notes":[]},{"n":28,"t":"上使穹苍坚硬，下使渊源稳固，","notes":[]},{"n":29,"t":"为沧海定出范围，使水不越过界限，奠定大地的根基。","notes":[]},{"n":30,"t":"那时，我在他旁边为工程师，天天充满喜乐，时时在他面前欢笑，","notes":[]},{"n":31,"t":"在他的全地欢笑，喜爱住在人世间。","notes":[]},{"n":32,"t":"“孩子们，现在要听从我，谨守我道的有福了。","notes":[]},{"n":33,"t":"要听训诲，得智慧，不可弃绝。","notes":[]},{"n":34,"t":"听从我，天天在我门口守望，在我门框旁等候的，那人有福了。","notes":[]},{"n":35,"t":"因为寻得我的，就寻得生命，他必蒙耶和华的恩惠。","notes":[]},{"n":36,"t":"得罪我的，害了自己的生命，凡恨恶我的，喜爱死亡。”","notes":[]}]},"9":{"heading":"智慧和愚蠢","verses":[{"n":1,"t":"智慧建造房屋，凿成七根柱子，","notes":[]},{"n":2,"t":"宰杀牲畜，调好美酒，又摆设筵席，","notes":[]},{"n":3,"t":"派遣女仆出去，自己在城中至高处呼唤：","notes":[]},{"n":4,"t":"“谁是愚蒙的人，让他转到这里来！”又对那无知的人说：","notes":[]},{"n":5,"t":"“你们来，吃我的饼，喝我调的酒。","notes":[]},{"n":6,"t":"你们要离弃愚蒙，就得存活，并要走明智的道路。”","notes":[]},{"n":7,"t":"纠正傲慢人的，必招羞辱，责备恶人的，必被侮辱。","notes":[]},{"n":8,"t":"不要责备傲慢人，免得他恨你；要责备智慧人，他必爱你。","notes":[]},{"n":9,"t":"教导智慧人，他就越有智慧，指示义人，他就增长学问。","notes":[]},{"n":10,"t":"敬畏耶和华是智慧的开端，认识至圣者便是聪明。","notes":[]},{"n":11,"t":"藉着我，你的日子必增多，你生命的年数也必加添。","notes":[]},{"n":12,"t":"你若有智慧，是自己有智慧；你若傲慢，就自己承担。","notes":[]},{"n":13,"t":"愚昧的女子喧嚷，她是愚蒙，一无所知。","notes":[]},{"n":14,"t":"她坐在自己家门口，在城中高处的座位上，","notes":[]},{"n":15,"t":"呼唤过路的，向那些在路上直走的人说：","notes":[]},{"n":16,"t":"“谁是愚蒙的人，让他转到这里来！”又对那无知的人说：","notes":[]},{"n":17,"t":"“偷来的水是甜的，暗藏的饼是美的。”","notes":[]},{"n":18,"t":"人却不知有阴魂在她那里，她召唤的人是在阴间的深处。","notes":[]}]},"10":{"heading":"所罗门的箴言","verses":[{"n":1,"t":"所罗门的箴言：智慧之子使父亲喜乐；愚昧之子使母亲担忧。","notes":[]},{"n":2,"t":"不义之财毫无益处；惟有公义能救人脱离死亡。","notes":[]},{"n":3,"t":"耶和华不使义人捱饿；恶人所欲的，耶和华必拒绝。","notes":[]},{"n":4,"t":"手懒的，必致穷乏；手勤的，却要富足。","notes":[]},{"n":5,"t":"夏天储存的，是智慧之子；收割时沉睡的，是蒙羞之子。","notes":[]},{"n":6,"t":"福祉临到义人头上；恶人的口藏匿残暴。","notes":[]},{"n":7,"t":"义人的称号带来祝福；恶人的名字必然败坏。","notes":[]},{"n":8,"t":"智慧的心，领受诫命；愚妄的嘴唇，必致倾倒。","notes":[]},{"n":9,"t":"行正直路的，步步安稳；走弯曲道的，必致败露。","notes":[]},{"n":10,"t":"挤眉弄眼的，使人忧患；愚妄的嘴唇，必致倾倒。","notes":[]},{"n":11,"t":"义人的口是生命的泉源；恶人的口藏匿残暴。","notes":[]},{"n":12,"t":"恨能挑启争端；爱能遮掩一切过错。","notes":[]},{"n":13,"t":"聪明人嘴里有智慧；无知的人背上受刑杖。","notes":[]},{"n":14,"t":"智慧人积存知识；愚妄人的口速致败坏。","notes":[]},{"n":15,"t":"有钱人的财物是他坚固的城；贫寒人的贫乏使他败坏。","notes":[]},{"n":16,"t":"义人的报酬带来生命；恶人的所得用来犯罪。","notes":[]},{"n":17,"t":"遵守训诲的，行在生命道上；离弃责备的，走迷了路。","notes":[]},{"n":18,"t":"隐藏怨恨的，有说谎的嘴唇；口出毁谤的，是愚昧人。","notes":[]},{"n":19,"t":"多言多语难免有过；节制嘴唇是有智慧。","notes":[]},{"n":20,"t":"义人的舌如上选的银子；恶人的心所值无几。","notes":[]},{"n":21,"t":"义人的嘴唇牧养多人；愚妄人因无知而死亡。","notes":[]},{"n":22,"t":"耶和华所赐的福使人富足，并不加上忧虑。","notes":[]},{"n":23,"t":"愚昧人以行恶为乐；聪明人以智慧为乐。","notes":[]},{"n":24,"t":"恶人所怕的，必临到他；义人的心愿，必蒙应允。","notes":[]},{"n":25,"t":"暴风一过，恶人归于无有；义人却有永久的根基。","notes":[]},{"n":26,"t":"懒惰人使那差他的人，如醋倒牙，如烟薰目。","notes":[]},{"n":27,"t":"敬畏耶和华使人长寿；恶人的年岁必减少。","notes":[]},{"n":28,"t":"义人的盼望带来喜乐；恶人的指望必致灭没。","notes":[]},{"n":29,"t":"耶和华的道是正直人的保障；却成了作恶人的败坏。","notes":[]},{"n":30,"t":"义人永不动摇；恶人不得住在地上。","notes":[]},{"n":31,"t":"义人的口结出智慧；乖谬的舌必被割断。","notes":[]},{"n":32,"t":"义人的嘴唇懂得令人喜悦；恶人的口只知乖谬。","notes":[]}]},"11":{"heading":"","verses":[{"n":1,"t":"诡诈的天平为耶和华所憎恶；公平的法码为他所喜悦。","notes":[]},{"n":2,"t":"骄傲来，羞耻也来；谦逊人却有智慧。","notes":[]},{"n":3,"t":"正直人的纯正必引导自己；奸诈人的邪恶必毁灭自己。","notes":[]},{"n":4,"t":"遭怒的日子钱财无益；惟有公义能救人脱离死亡。","notes":[]},{"n":5,"t":"完全人的义修平自己的路；但恶人必因自己的恶跌倒。","notes":[]},{"n":6,"t":"正直人的义必拯救自己；奸诈人必被自己的欲望缠住。","notes":[]},{"n":7,"t":"恶人一死，他的指望就灭绝；罪人的盼望也必灭绝。","notes":[]},{"n":8,"t":"义人得脱离患难，有恶人来代替他。","notes":[]},{"n":9,"t":"不虔敬的人用口败坏邻舍；义人却因知识得救。","notes":[]},{"n":10,"t":"义人享福，全城喜乐；恶人灭亡，人人欢呼。","notes":[]},{"n":11,"t":"因正直人的祝福，城必升高；因邪恶人的口，它必倾覆。","notes":[]},{"n":12,"t":"藐视邻舍的，便是无知；聪明人却静默不言。","notes":[]},{"n":13,"t":"到处传话的，泄漏机密；内心老实的，保守秘密。","notes":[]},{"n":14,"t":"无智谋，民就败落；谋士多，就必得胜。","notes":[]},{"n":15,"t":"为陌生人担保的，必受亏损；恨恶击掌的，却得安稳。","notes":[]},{"n":16,"t":"恩慈的妇女得尊荣；强壮的男子得财富。","notes":[]},{"n":17,"t":"仁慈的人善待自己；残忍的人扰害己身。","notes":[]},{"n":18,"t":"恶人做事，得虚幻的报酬；撒公义种子的，得实在的报偿。","notes":[]},{"n":19,"t":"真正行义的，必得生命；追求邪恶的，必致死亡。","notes":[]},{"n":20,"t":"心中歪曲的，为耶和华所憎恶；行为正直的，为他所喜悦。","notes":[]},{"n":21,"t":"击掌保证，恶人难免受罚；义人的后裔必得拯救。","notes":[]},{"n":22,"t":"妇女美貌而无见识，如同金环戴在猪鼻上。","notes":[]},{"n":23,"t":"义人的心愿尽是好的；恶人的指望却带来愤怒。","notes":[]},{"n":24,"t":"有施舍的，钱财增添；吝惜过度，反致穷乏。","notes":[]},{"n":25,"t":"慷慨待人，必然丰裕；滋润人的，连自己也得滋润。","notes":[]},{"n":26,"t":"屯粮不卖的，百姓必诅咒他；愿意出售的，祝福临到头上。","notes":[]},{"n":27,"t":"恳切求善的，就求得恩宠；但那求恶的，恶必临到他。","notes":[]},{"n":28,"t":"倚靠财富的，自己必跌倒；义人必兴旺如绿叶。","notes":[]},{"n":29,"t":"扰害己家的，必承受虚空；愚妄人作心中有智慧者的仆人。","notes":["“虚空”：原文是“风”。"]},{"n":30,"t":"义人的果实是生命树；智慧人必能得人。","notes":[]},{"n":31,"t":"看哪，义人在地上尚且受报，何况恶人和罪人呢？","notes":[]}]},"12":{"heading":"","verses":[{"n":1,"t":"喜爱管教的，就是喜爱知识；恨恶责备的，却像畜牲。","notes":[]},{"n":2,"t":"善人蒙耶和华的恩宠；设诡计的，耶和华必定罪。","notes":[]},{"n":3,"t":"人靠恶行不能坚立；义人的根必不动摇。","notes":[]},{"n":4,"t":"才德的妻子是丈夫的冠冕；蒙羞的妇人使丈夫骨头朽烂。","notes":[]},{"n":5,"t":"义人的思念是公平；恶人的计谋是诡诈。","notes":[]},{"n":6,"t":"恶人的言论埋伏流人的血；正直人的口却拯救人。","notes":[]},{"n":7,"t":"恶人倾覆，归于无有；义人的家却屹立不倒。","notes":[]},{"n":8,"t":"人按自己的智慧得称赞；心中偏邪的，必被藐视。","notes":[]},{"n":9,"t":"被人藐视，但有自己仆人的，胜过妄自尊大，却缺乏食物。","notes":["“有自己仆人”或译“自己工作”。"]},{"n":10,"t":"义人顾惜他牲畜的命；恶人的怜悯也是残忍。","notes":[]},{"n":11,"t":"耕种自己田地的，必得饱食；追求虚浮的，却是无知。","notes":[]},{"n":12,"t":"恶人想得坏人的猎物；义人的根结出果实。","notes":[]},{"n":13,"t":"嘴唇的过错是恶人的圈套；但义人必脱离患难。","notes":[]},{"n":14,"t":"人因口所结的果实，必饱得美福；人手所做的，必归到自己身上。","notes":[]},{"n":15,"t":"愚妄人所行的，在自己眼中看为正直；惟智慧人从善如流。","notes":[]},{"n":16,"t":"愚妄人的恼怒立时显露；通达人却能忍辱。","notes":[]},{"n":17,"t":"说出真话的，显明公义；作假见证的，显出诡诈。","notes":[]},{"n":18,"t":"说话浮躁，犹如刺刀；智慧人的舌头却能医治。","notes":[]},{"n":19,"t":"诚实的嘴唇永远坚立；说谎的舌头只存片时。","notes":[]},{"n":20,"t":"图谋恶事的，心存诡诈；劝人和睦的，便得喜乐。","notes":[]},{"n":21,"t":"义人不遭灾害；恶人满受祸患。","notes":[]},{"n":22,"t":"说谎的嘴唇，为耶和华所憎恶；行事诚实，为他所喜悦。","notes":[]},{"n":23,"t":"通达人隐藏知识；愚昧人的心彰显愚昧。","notes":[]},{"n":24,"t":"殷勤人的手必掌权；懒惰的人必服苦役。","notes":[]},{"n":25,"t":"人心忧虑，就必沉重；一句良言，使心欢乐。","notes":[]},{"n":26,"t":"义人引导他的邻舍；恶人的道叫人迷失。","notes":["“义人引导他的邻舍”或译“义人慎选他的朋友”，又或译“义人比他的邻舍更好”。"]},{"n":27,"t":"懒惰的人不烤猎物；殷勤的人却得宝贵的财物。","notes":[]},{"n":28,"t":"在公义的路上有生命；在其道上并无死亡。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"智慧之子听父亲的训诲；傲慢人不听责备。","notes":[]},{"n":2,"t":"人因口所结的果实，必享美福；奸诈人却意图残暴。","notes":[]},{"n":3,"t":"谨慎守口的，得保生命；大张嘴唇的，必致败亡。","notes":[]},{"n":4,"t":"懒惰的人奢求，却无所得；殷勤的人必然丰裕。","notes":[]},{"n":5,"t":"义人恨恶谎言；恶人可憎可耻。","notes":[]},{"n":6,"t":"行为纯正的，有公义保护；犯罪的，被罪恶倾覆。","notes":[]},{"n":7,"t":"假冒富足的，一无所有；装作穷乏的，多有财物。","notes":[]},{"n":8,"t":"财富可作人的生命赎价；穷乏人却听不见威吓的话。","notes":[]},{"n":9,"t":"义人的光使人欢喜；恶人的灯要熄灭。","notes":["“使人欢喜”：原文另译“明亮”。"]},{"n":10,"t":"骄傲挑启纷争；听劝言却有智慧。","notes":[]},{"n":11,"t":"不劳而获之财必减少；逐渐积蓄的必增多。","notes":["“不劳而获之财”：七十士译本是“暴发的不义之财”。"]},{"n":12,"t":"盼望迟延，令人心忧；愿望实现，就是得到生命树。","notes":[]},{"n":13,"t":"藐视训言的，自取灭亡；敬畏诫命的，必得善报。","notes":[]},{"n":14,"t":"智慧人的教诲是生命的泉源，使人避开死亡的圈套。","notes":[]},{"n":15,"t":"美好的见识使人得宠；奸诈人的道路恒久奸诈。","notes":["“恒久奸诈”：原文是“恒久”。"]},{"n":16,"t":"通达人都凭知识行事；愚昧人张扬自己的愚昧。","notes":[]},{"n":17,"t":"邪恶的使者必陷入祸患；忠信的使臣带来医治。","notes":[]},{"n":18,"t":"弃绝管教的，必贫穷受辱；领受责备的，必享尊荣。","notes":[]},{"n":19,"t":"愿望实现，心觉甘甜；远离恶事，为愚昧人所憎恶。","notes":[]},{"n":20,"t":"与智慧人同行的，必得智慧；和愚昧人作伴的，必受亏损。","notes":[]},{"n":21,"t":"祸患追赶罪人；义人却得善报。","notes":[]},{"n":22,"t":"善人给子孙遗留产业；罪人积财却归义人。","notes":[]},{"n":23,"t":"穷乏人开垦的地虽多产粮食，却因不公而被夺走。","notes":[]},{"n":24,"t":"不忍用杖打儿子的，是恨恶他；疼爱儿子的，勤加管教。","notes":[]},{"n":25,"t":"义人吃喝食欲满足；恶人肚腹却是缺乏。","notes":[]}]},"14":{"heading":"","verses":[{"n":1,"t":"妇人的智慧建立家室；愚昧却亲手拆毁它。","notes":["本节七十士译本是“智慧妇人建立家室；愚妄妇人亲手拆毁”。"]},{"n":2,"t":"行事正直的，敬畏耶和华；偏离正路的，却藐视他。","notes":[]},{"n":3,"t":"在愚妄人的口中有骄傲的杖；智慧人的嘴唇必保护自己。","notes":[]},{"n":4,"t":"没有牛，槽就空空；土产丰盛却凭牛的力气。","notes":[]},{"n":5,"t":"诚实的证人不说谎；虚假的证人口吐谎言。","notes":[]},{"n":6,"t":"傲慢人枉寻智慧；聪明人易得知识。","notes":[]},{"n":7,"t":"不要到愚昧人面前，你无法从他嘴唇里知道知识。","notes":[]},{"n":8,"t":"通达人的智慧使他认清自己的道路；愚昧人的愚昧却是自欺。","notes":[]},{"n":9,"t":"愚妄人嘲笑赎愆祭；但正直人蒙悦纳。","notes":["“赎愆祭”或译“复和”。"]},{"n":10,"t":"心中的苦楚，只有自己知道；心里的喜乐，陌生人无法分享。","notes":[]},{"n":11,"t":"恶人的房屋必倒塌；正直人的帐棚必兴旺。","notes":[]},{"n":12,"t":"有一条路，人以为正，至终成为死亡之路。","notes":[]},{"n":13,"t":"人在喜笑中，心也会忧愁；快乐的终点就是愁苦。","notes":[]},{"n":14,"t":"心中背道的，必满尝其果；善人必从自己的行为得到回报。","notes":[]},{"n":15,"t":"无知的人什么话都信；通达人谨慎自己的脚步。","notes":[]},{"n":16,"t":"智慧人有所惧怕，就远离恶事；愚昧人却狂傲自恃。","notes":[]},{"n":17,"t":"轻易发怒的，行事愚昧；擅长诡计的，被人恨恶。","notes":[]},{"n":18,"t":"愚蒙人承受愚昧为产业；通达人得知识为冠冕。","notes":[]},{"n":19,"t":"坏人在善人面前俯伏；恶人在义人门口也是如此。","notes":[]},{"n":20,"t":"穷乏人，连邻舍也恨他；有钱人，爱他的人众多。","notes":[]},{"n":21,"t":"藐视邻舍的，这人有罪；施恩给困苦人的，这人有福。","notes":[]},{"n":22,"t":"谋恶的，岂非走入迷途？谋善的，有慈爱和诚实。","notes":[]},{"n":23,"t":"任何勤劳总有收获；仅耍嘴皮必致穷乏。","notes":[]},{"n":24,"t":"智慧人的冠冕是富有智慧；愚昧人的愚昧终究是愚昧。","notes":[]},{"n":25,"t":"诚实作证，救人性命；口吐谎言是诡诈。","notes":[]},{"n":26,"t":"敬畏耶和华的，大有倚靠；他的儿女也有避难所。","notes":[]},{"n":27,"t":"敬畏耶和华是生命的泉源，使人离开死亡的圈套。","notes":[]},{"n":28,"t":"君王的荣耀在乎民多；没有百姓，王就衰败。","notes":[]},{"n":29,"t":"不轻易发怒的，大有聪明；性情暴躁的，大显愚昧。","notes":[]},{"n":30,"t":"平静的心使肉体有生气；嫉妒使骨头朽烂。","notes":[]},{"n":31,"t":"欺压贫寒人的，是蔑视造他的主；怜悯贫穷人的，是尊敬主。","notes":[]},{"n":32,"t":"恶人因所行的恶必被推倒；义人临死，有所投靠。","notes":["“义人临死”：七十士译本是“义人因其完全”。"]},{"n":33,"t":"智慧安居在聪明人的心中，在愚昧人的心中却不认识。","notes":["“在愚昧人...不认识”是根据七十士译本；原文是“也为愚昧人的心所知”。"]},{"n":34,"t":"公义使邦国高举；罪恶是百姓的羞辱。","notes":[]},{"n":35,"t":"君王的恩宠临到智慧的臣仆；但其愤怒临到蒙羞的臣仆。","notes":[]}]},"15":{"heading":"","verses":[{"n":1,"t":"回答柔和，使怒消退；言语粗暴，触动怒气。","notes":[]},{"n":2,"t":"智慧人的舌善发知识；愚昧人的口吐出愚昧。","notes":[]},{"n":3,"t":"耶和华的眼目无处不在，恶人善人，他都鉴察。","notes":[]},{"n":4,"t":"温良的舌是生命树；邪恶的舌使人心碎。","notes":[]},{"n":5,"t":"愚妄人藐视父亲的管教；领受责备，使人精明。","notes":[]},{"n":6,"t":"义人家中多有财富；恶人获利反受扰害。","notes":[]},{"n":7,"t":"智慧人的嘴传扬知识；愚昧人的心并非如此。","notes":[]},{"n":8,"t":"恶人献祭，为耶和华所憎恶；正直人祈祷，为他所喜悦。","notes":[]},{"n":9,"t":"恶人的道路，为耶和华所憎恶；追求公义的，为他所喜爱。","notes":[]},{"n":10,"t":"背弃正路的，必受严刑；恨恶责备的，必致死亡。","notes":[]},{"n":11,"t":"阴间和冥府尚且在耶和华面前，何况世人的心呢？","notes":["“冥府”：原文音译“亚巴顿”，意思是“灭亡之地”。"]},{"n":12,"t":"傲慢人不爱受责备，也不去接近智慧人。","notes":[]},{"n":13,"t":"心中喜乐，面有喜色；心里忧愁，灵就忧伤。","notes":[]},{"n":14,"t":"聪明人的心追求知识；愚昧人的口吞吃愚昧。","notes":[]},{"n":15,"t":"困苦人的日子都是愁苦；心中欢畅的，常享宴席。","notes":[]},{"n":16,"t":"财宝稀少，敬畏耶和华，强如财宝众多，烦乱不安。","notes":[]},{"n":17,"t":"有爱，吃素菜，强如相恨，吃肥牛。","notes":[]},{"n":18,"t":"暴怒的人挑启争端；忍怒的人止息纷争。","notes":[]},{"n":19,"t":"懒惰人的道像荆棘的篱笆；正直人的路是平坦大道。","notes":[]},{"n":20,"t":"智慧之子使父亲喜乐；愚昧的人藐视母亲。","notes":[]},{"n":21,"t":"无知的人以愚昧为乐；聪明的人按正直而行。","notes":[]},{"n":22,"t":"不先商议，所谋无效；谋士众多，所谋得成。","notes":[]},{"n":23,"t":"口善应对，自觉喜乐；话合其时，何等美好。","notes":[]},{"n":24,"t":"生命之道使智慧人上升，使他远离底下的阴间。","notes":[]},{"n":25,"t":"耶和华必拆毁骄傲人的家，却要立定寡妇的地界。","notes":[]},{"n":26,"t":"恶谋为耶和华所憎恶；良言却是纯净的。","notes":[]},{"n":27,"t":"暴力敛财的，扰害己家；恨恶贿赂的，必得存活。","notes":[]},{"n":28,"t":"义人的心思量应答；恶人的口吐出恶言。","notes":[]},{"n":29,"t":"耶和华远离恶人，却听义人的祈祷。","notes":[]},{"n":30,"t":"眼睛发光，使心喜乐；好的信息，滋润骨头。","notes":[]},{"n":31,"t":"耳听使人得生命的责备，必居住在智慧人之中。","notes":[]},{"n":32,"t":"弃绝管教的，轻看自己的生命；领受责备的，却得智慧的心。","notes":[]},{"n":33,"t":"敬畏耶和华是智慧的训诲；要得尊荣，先有谦卑。","notes":[]}]},"16":{"heading":"","verses":[{"n":1,"t":"心中的筹谋在乎人，舌头的应对出于耶和华。","notes":[]},{"n":2,"t":"人一切所行的，在自己眼中看为纯洁，惟有耶和华衡量人的内心。","notes":[]},{"n":3,"t":"你所做的，要交托耶和华，你所谋的，就必坚立。","notes":[]},{"n":4,"t":"耶和华造万物各适其用，就是恶人也为祸患的日子所造。","notes":[]},{"n":5,"t":"凡心里骄傲的，为耶和华所憎恶；击掌保证，他难免受罚。","notes":[]},{"n":6,"t":"因慈爱和信实，罪孽得赎；敬畏耶和华的，远离恶事。","notes":[]},{"n":7,"t":"人所行的若蒙耶和华喜悦，耶和华也使仇敌与他和好。","notes":[]},{"n":8,"t":"少获利，行事公义，强如多获利，行事不义。","notes":[]},{"n":9,"t":"人心筹算自己的道路；惟耶和华指引他的脚步。","notes":[]},{"n":10,"t":"王的嘴唇有圣言，审判之时，他的口必不差错。","notes":[]},{"n":11,"t":"公道的秤和天平属耶和华，囊中一切的法码是他所定。","notes":[]},{"n":12,"t":"作恶，为王所憎恶，因国位是靠公义坚立。","notes":[]},{"n":13,"t":"公义的嘴唇，王喜悦，说正直话的，他喜爱。","notes":[]},{"n":14,"t":"王的震怒是死亡的使者，但智慧人能平息王怒。","notes":[]},{"n":15,"t":"王脸上的光使人有生命，他的恩惠好像云带来的春雨。","notes":[]},{"n":16,"t":"得智慧胜过得金子，选聪明强如选银子。","notes":[]},{"n":17,"t":"正直人的道远离恶事，谨守己路的，保全性命。","notes":[]},{"n":18,"t":"骄傲在败坏以先，内心高傲在跌倒之前。","notes":[]},{"n":19,"t":"心里谦卑与困苦人来往，强如与骄傲人同分战利品。","notes":[]},{"n":20,"t":"留心训言的，必得福乐；倚靠耶和华的，这人有福。","notes":["“留心训言的”或译“专注事务的”。"]},{"n":21,"t":"心中有智慧的，必称为聪明人；嘴唇的甜言，增长人的学问。","notes":[]},{"n":22,"t":"人有智慧就有生命的泉源；愚妄人必受愚妄的惩戒。","notes":[]},{"n":23,"t":"智慧人的心使他的口谨慎，又使他的嘴唇增长学问。","notes":[]},{"n":24,"t":"良言如同蜂巢，使心甘甜，使骨得医治。","notes":[]},{"n":25,"t":"有一条路，人以为正，至终却成为死亡之路。","notes":[]},{"n":26,"t":"劳力的人为自己劳力，因为他的口腹催逼他。","notes":[]},{"n":27,"t":"匪徒图谋奸恶，嘴唇上的言语仿佛烧焦的火。","notes":[]},{"n":28,"t":"乖谬的人散播纷争，造谣的离间密友。","notes":[]},{"n":29,"t":"残暴的人引诱邻舍，领他走不好的道路。","notes":[]},{"n":30,"t":"紧闭双目的，图谋乖谬；紧咬嘴唇的，成就恶事。","notes":[]},{"n":31,"t":"白发是荣耀的冠冕，行在公义道上的，必能得着。","notes":[]},{"n":32,"t":"不轻易发怒的，胜过勇士；控制自己脾气的，强如取城。","notes":[]},{"n":33,"t":"人虽可掷签在膝上，定事却由耶和华。","notes":[]}]},"17":{"heading":"","verses":[{"n":1,"t":"一块干饼，大家相安；胜过宴席满屋，大家相争。","notes":[]},{"n":2,"t":"明智的仆人必管辖蒙羞的儿子，并在兄弟中同分产业。","notes":[]},{"n":3,"t":"鼎为炼银，炉为炼金，惟有耶和华熬炼人心。","notes":[]},{"n":4,"t":"行恶的，留心听恶毒的嘴唇；说谎的，侧耳听邪恶的舌头。","notes":[]},{"n":5,"t":"讥笑穷乏人的，是蔑视造他的主；幸灾乐祸的，难免受罚。","notes":[]},{"n":6,"t":"子孙为老人的冠冕；父母是儿女的荣耀。","notes":[]},{"n":7,"t":"愚顽人说美言并不相宜，君子说谎言也不合宜。","notes":[]},{"n":8,"t":"贿赂在馈赠者的眼中看为玉石，随处运转都得顺利。","notes":[]},{"n":9,"t":"包容过错的，寻求友爱；喋喋不休的，离间密友。","notes":[]},{"n":10,"t":"一句责备的话深入聪明人的心，强如打愚昧人一百下。","notes":[]},{"n":11,"t":"恶人只寻求背叛，残忍的使者必奉差攻击他。","notes":[]},{"n":12,"t":"宁可遇见失丧小熊的母熊，也不愿遇见正行愚昧的愚昧人。","notes":[]},{"n":13,"t":"以恶报善的，祸患必不离他的家。","notes":[]},{"n":14,"t":"纷争掀起，如同缺口的水；因此，争端尚未爆发就当制止。","notes":[]},{"n":15,"t":"定恶人为义的，定义人为有罪的，都为耶和华所憎恶。","notes":[]},{"n":16,"t":"愚昧人既无知，为何手拿银钱去买智慧呢？","notes":[]},{"n":17,"t":"朋友时常亲爱，弟兄为患难而生。","notes":[]},{"n":18,"t":"在邻舍面前击掌担保的，是无知的人。","notes":[]},{"n":19,"t":"喜爱争吵的，是喜爱过犯；门盖得高的，自取败坏。","notes":[]},{"n":20,"t":"心中歪曲的，得不着福乐；舌头颠倒是非的，陷在祸患中。","notes":[]},{"n":21,"t":"生愚昧之子的，自己必愁苦；愚顽人的父亲毫无喜乐。","notes":[]},{"n":22,"t":"喜乐的心能治好疾病；忧伤的灵使骨头枯干。","notes":[]},{"n":23,"t":"恶人暗中受贿赂，以致弯曲公正的路。","notes":[]},{"n":24,"t":"聪明人面前有智慧；愚昧人眼望地的尽头。","notes":[]},{"n":25,"t":"愚昧的儿子使父亲愁烦，使那生他的母亲忧苦。","notes":[]},{"n":26,"t":"刑罚义人实为不善，责打正直的君子也不宜。","notes":[]},{"n":27,"t":"节制言语的，有见识；性情温良的人，有聪明。","notes":[]},{"n":28,"t":"愚妄人若静默不言，可算为智慧，闭上嘴唇也可算为聪明。","notes":[]}]},"18":{"heading":"","verses":[{"n":1,"t":"孤僻的人只顾自己的心愿，他鄙视一切健全的知识。","notes":["“只顾自己的心愿”：七十士译本和其他古译本是“只顾为自己找藉口”。"]},{"n":2,"t":"愚昧人不喜爱聪明，只喜爱表达自己的心意。","notes":[]},{"n":3,"t":"邪恶来，藐视跟着来；羞耻到，辱骂同时到。","notes":[]},{"n":4,"t":"人的口所讲的话如同深水，智慧之泉如涌流的河水。","notes":[]},{"n":5,"t":"偏袒恶人的情面，是不好的。审判时使义人受屈，也是不善。","notes":[]},{"n":6,"t":"愚昧人的嘴唇挑起争端，一开口就招鞭打。","notes":[]},{"n":7,"t":"愚昧人的口自取败坏，他的嘴唇是自己生命的圈套。","notes":[]},{"n":8,"t":"造谣者的话如同美食，深入人的肚腹。","notes":[]},{"n":9,"t":"做工懈怠的，是破坏者的兄弟。","notes":[]},{"n":10,"t":"耶和华的名是坚固台，义人奔入就得安稳。","notes":[]},{"n":11,"t":"有钱人的财物是他坚固的城，在他幻想中，犹如高墙。","notes":[]},{"n":12,"t":"败坏之先，人心骄傲；要得尊荣，先有谦卑。","notes":[]},{"n":13,"t":"未听完就回话的，就是他的愚昧和羞辱。","notes":[]},{"n":14,"t":"人的心灵忍耐疾病；心灵忧伤，谁能承当呢？","notes":[]},{"n":15,"t":"聪明人的心得知识；智慧人的耳求知识。","notes":[]},{"n":16,"t":"人的礼物为他开路，引他到高位的人面前。","notes":[]},{"n":17,"t":"先诉情由的，似乎有理；另一人来到，就察出实情。","notes":[]},{"n":18,"t":"掣签能止息纷争，也能化解双方激烈的争辩。","notes":[]},{"n":19,"t":"被冒犯的弟兄强如难以攻下的坚城；纷争如同城堡的门闩。","notes":["“被冒犯的弟兄”：七十士译本是“弟兄互助”。"]},{"n":20,"t":"人的肚腹必因口所结的果实饱足；他必因嘴唇所出的感到满足。","notes":[]},{"n":21,"t":"生死在舌头的掌握之下，喜爱弄舌的，必吃它所结的果实。","notes":[]},{"n":22,"t":"得着妻子的，得着好处，他是蒙了耶和华的恩惠。","notes":[]},{"n":23,"t":"穷乏人说哀求的话；有钱人却用威吓的话回答。","notes":[]},{"n":24,"t":"朋友太多的人，必受损害；但有一知己比兄弟更亲密。","notes":["“朋友...损害”或译“有些朋友是玩弄友谊的”。"]}]},"19":{"heading":"","verses":[{"n":1,"t":"行为纯正的穷乏人胜过嘴唇歪曲的愚昧人。","notes":[]},{"n":2,"t":"热心而无见识，实为不善；脚步急快的，易入歧途。","notes":[]},{"n":3,"t":"人因愚昧自毁前途，他的心却埋怨耶和华。","notes":[]},{"n":4,"t":"财富使朋友增多；贫寒人连仅有的朋友也离弃他。","notes":[]},{"n":5,"t":"作假见证的，难免受罚；口吐谎言的，不能逃脱。","notes":[]},{"n":6,"t":"有权贵的，许多人求他赏脸；爱送礼的，人都作他的朋友。","notes":[]},{"n":7,"t":"穷乏人连兄弟都恨他，何况朋友，更是远离他！他用言语追随，他们却不在。","notes":[]},{"n":8,"t":"得着智慧的，爱惜生命；持守聪明的，寻得好处。","notes":[]},{"n":9,"t":"作假见证的，难免受罚；口吐谎言的，必定灭亡。","notes":[]},{"n":10,"t":"愚昧人奢华度日并不相宜，仆人管辖王子，也不应该。","notes":[]},{"n":11,"t":"人有见识就不轻易发怒，宽恕人的过失便是自己的荣耀。","notes":[]},{"n":12,"t":"王的愤怒好像狮子吼叫；他的恩惠却如草上的甘露。","notes":[]},{"n":13,"t":"愚昧的儿子是父亲的祸患，妻子的争吵如雨连连滴漏。","notes":[]},{"n":14,"t":"房屋钱财是祖宗所遗留的；惟有贤慧的妻是耶和华所赐的。","notes":[]},{"n":15,"t":"懒惰使人沉睡，懈怠的人必捱饿。","notes":[]},{"n":16,"t":"遵守诫命的，保全生命；轻忽己路的，必致死亡。","notes":[]},{"n":17,"t":"怜悯贫寒人的，就是借给耶和华，他的报偿，耶和华必归还他。","notes":[]},{"n":18,"t":"趁还有指望，管教你的儿子，不可执意摧毁他。","notes":[]},{"n":19,"t":"暴怒的人必受惩罚，你若救他，必须再救。","notes":[]},{"n":20,"t":"要听劝言，接受训诲，使你终久有智慧。","notes":[]},{"n":21,"t":"人心多有计谋；惟有耶和华的筹算才能成就。","notes":[]},{"n":22,"t":"仁慈的人令人喜爱，穷乏人强如说谎言的。","notes":["“仁慈...喜爱”或译“贪心是人的羞耻”。"]},{"n":23,"t":"敬畏耶和华的，得着生命，他必饱足安居，不遭祸患。","notes":[]},{"n":24,"t":"懒惰人把手埋入盘里，连缩回送进口中也不肯。","notes":[]},{"n":25,"t":"责打傲慢人，能使无知的人变精明；责备聪明人，他就明白知识。","notes":[]},{"n":26,"t":"虐待父亲、驱逐母亲的，是蒙羞致辱之子。","notes":[]},{"n":27,"t":"我儿啊，停止听那叫你偏离知识言语的教导。","notes":["“停止...教导”或译“不可听了教导而又偏离知识的言语”；又或译“不可偏离知识的言语，要听教导”。"]},{"n":28,"t":"卑劣的见证嘲笑公平，恶人的口吞下罪孽。","notes":[]},{"n":29,"t":"刑罚是为傲慢人预备的，鞭打则是为愚昧人的背预备的。","notes":[]}]},"20":{"heading":"","verses":[{"n":1,"t":"酒能使人傲慢，烈酒使人喧嚷，凡沉溺其中的，都无智慧。","notes":[]},{"n":2,"t":"王的威吓如狮子吼叫，激怒他的是自害己命。","notes":[]},{"n":3,"t":"止息纷争是人的尊荣，愚妄人争闹不休。","notes":[]},{"n":4,"t":"懒惰人因冬寒不去耕种，到收割时，他去寻找，一无所得。","notes":[]},{"n":5,"t":"人心中的筹算如同深水，惟聪明人才能汲引出来。","notes":[]},{"n":6,"t":"很多人声称自己忠信，但诚信的人谁能遇着呢？","notes":[]},{"n":7,"t":"义人行为纯正，他后代的子孙有福了！","notes":[]},{"n":8,"t":"王坐在审判的位上，以眼目驱散一切邪恶。","notes":[]},{"n":9,"t":"谁能说：“我已经洁净了我的心，脱净了我的罪？”","notes":[]},{"n":10,"t":"两样的法码和两样的伊法，都为耶和华所憎恶。","notes":["“伊法”是量固体的量器或单位；参“度量衡表”。"]},{"n":11,"t":"孩童的行动或纯洁，或正直，都以行为显明自己。","notes":[]},{"n":12,"t":"能听的耳，能看的眼，二者都为耶和华所造。","notes":[]},{"n":13,"t":"不要贪睡，免致贫穷；眼要睁开，就可吃饱。","notes":[]},{"n":14,"t":"买东西的说：“不好，不好！”及至离去，他却自夸。","notes":[]},{"n":15,"t":"有金子和许多宝石，惟知识的嘴唇是贵重的珍宝。","notes":[]},{"n":16,"t":"谁为陌生人担保，就拿谁的衣服；谁为外邦人作保，谁就要承当。","notes":[]},{"n":17,"t":"靠谎言而得的食物，令人愉悦；到后来，他的口必充满碎石。","notes":[]},{"n":18,"t":"计谋凭筹算立定，打仗要凭智谋。","notes":[]},{"n":19,"t":"到处传话的，泄漏机密；口无遮拦的，不可与他结交。","notes":[]},{"n":20,"t":"咒骂父母的，他的灯必熄灭，在漆黑中。","notes":[]},{"n":21,"t":"起初很快得来的产业，终久却不是福。","notes":[]},{"n":22,"t":"你不要说：“我要以恶报恶”；要等候耶和华，他必拯救你。","notes":[]},{"n":23,"t":"两样的法码为耶和华所憎恶，诡诈的天平也为不善。","notes":[]},{"n":24,"t":"人的脚步为耶和华所定，人岂能明白自己的道路呢？","notes":[]},{"n":25,"t":"人冒失地声称：“这是神圣的！”许愿之后才细想，就是自陷圈套。","notes":[]},{"n":26,"t":"智慧的王驱散恶人，用轮子滚过他们。","notes":[]},{"n":27,"t":"人的灵是耶和华的灯，鉴察人的内心深处。","notes":[]},{"n":28,"t":"慈爱和诚实庇护君王，他的王位因慈爱而立稳。","notes":[]},{"n":29,"t":"强壮是青年的荣耀；白发为老人的尊荣。","notes":[]},{"n":30,"t":"鞭伤除净邪恶，责打可洁净人心深处。","notes":[]}]},"21":{"heading":"","verses":[{"n":1,"t":"王的心在耶和华手中像河水，他能使它随意流转。","notes":[]},{"n":2,"t":"人一切所行的，在自己眼中看为正直，惟有耶和华衡量人心。","notes":[]},{"n":3,"t":"行公义和公平比献祭更蒙耶和华悦纳。","notes":[]},{"n":4,"t":"眼高心傲，就是恶人的灯，都是罪。","notes":[]},{"n":5,"t":"殷勤筹划的，足致丰裕；行事急躁的，必致缺乏。","notes":[]},{"n":6,"t":"用诡诈之舌所得的财富如被吹散的雾气，趋向灭亡。","notes":["“趋向灭亡”：有古卷、七十士译本和其他古译本是“和死亡的圈套”。"]},{"n":7,"t":"恶人的残暴必扫去自己，因他们不肯按公平行事。","notes":[]},{"n":8,"t":"有罪的人其路弯曲；纯洁的人行为正直。","notes":[]},{"n":9,"t":"宁可住在房顶的一角，也不与好争吵的妇人同住。","notes":[]},{"n":10,"t":"恶人的心渴想邪恶，他的眼并不怜悯邻舍。","notes":[]},{"n":11,"t":"傲慢人受惩罚，愚蒙人可得智慧；智慧人受训诲，便得知识。","notes":[]},{"n":12,"t":"公义的神鉴察恶人的家，他倾覆恶人，以致灭亡。","notes":["“公义的神”或译“义人”。"]},{"n":13,"t":"塞耳不听贫寒人哀求的，他自己呼求，也不蒙应允。","notes":[]},{"n":14,"t":"暗中送的礼物挽回怒气，怀里的贿赂能止息暴怒。","notes":[]},{"n":15,"t":"秉公行义使义人喜乐，却使作恶的人败坏。","notes":[]},{"n":16,"t":"人偏离智慧的路，必与阴魂为伍。","notes":["“必与阴魂为伍”：原文是“必住在阴魂的会中”。"]},{"n":17,"t":"爱宴乐的，必致穷乏；贪爱酒和油的，必不富足。","notes":[]},{"n":18,"t":"恶人作义人的赎价，奸诈人代替正直人。","notes":[]},{"n":19,"t":"宁可住在旷野之地，也不与争吵易怒的妇人同住。","notes":[]},{"n":20,"t":"智慧人的居所积蓄宝物与膏油；愚昧人却挥霍一空。","notes":["“智慧人...膏油”：七十士译本是“渴慕的宝物留在智慧人的嘴上”。"]},{"n":21,"t":"追求公义慈爱的，就寻得生命、公义和尊荣。","notes":["七十士译本没有“公义”。"]},{"n":22,"t":"智慧人爬上勇士的城墙，摧毁他所倚靠的堡垒。","notes":[]},{"n":23,"t":"谨守口和舌的，就保护自己免受灾难。","notes":[]},{"n":24,"t":"心骄气傲的人名叫傲慢，他行事出于狂妄骄傲。","notes":[]},{"n":25,"t":"懒惰人的欲望害死自己，因为他的手不肯做工；","notes":[]},{"n":26,"t":"有人终日贪得无餍，义人却施舍而不吝惜。","notes":[]},{"n":27,"t":"恶人献的祭是可憎的，何况他存恶意来献呢？","notes":[]},{"n":28,"t":"不实的见证必消灭；惟聆听真情的，他的证词有力。","notes":[]},{"n":29,"t":"恶人脸无羞耻；正直人行事坚定。","notes":["“正直人行事坚定”：原文另译“正直人明白己道”。"]},{"n":30,"t":"没有人能以智慧、聪明、谋略抵挡耶和华。","notes":[]},{"n":31,"t":"马是为打仗之日预备的；得胜却在于耶和华。","notes":[]}]},"22":{"heading":"智言三十则","verses":[{"n":1,"t":"美名胜过大财，宏恩强如金银。","notes":[]},{"n":2,"t":"有钱人与穷乏人相遇，他们都为耶和华所造。","notes":["“相遇”或译“是一样的”。"]},{"n":3,"t":"通达人见祸就藏躲；愚蒙人却前往受害。","notes":[]},{"n":4,"t":"敬畏耶和华心存谦卑，就得财富、尊荣、生命为赏赐。","notes":[]},{"n":5,"t":"歪曲的人路上有荆棘和罗网，保护自己生命的，必要远离。","notes":[]},{"n":6,"t":"教养孩童走当行的道，就是到老他也不偏离。","notes":["七十士译本没有本节。"]},{"n":7,"t":"有钱人管辖穷乏人，欠债的是债主的仆人。","notes":[]},{"n":8,"t":"撒不义种子的必收割灾祸，他逞怒的杖也必废掉。","notes":[]},{"n":9,"t":"眼目仁慈的必蒙福，因他将食物分给贫寒人。","notes":[]},{"n":10,"t":"赶出傲慢人，争端就消除，纷争和羞辱也必止息。","notes":[]},{"n":11,"t":"喜爱清心，嘴唇有恩言的，王必与他为友。","notes":[]},{"n":12,"t":"耶和华的眼目保护知识，却毁坏奸诈人的言语。","notes":[]},{"n":13,"t":"懒惰人说：“外面有狮子，我在街上必被杀害。”","notes":[]},{"n":14,"t":"陌生女子的口是深坑，耶和华所憎恶的，必陷在其中。","notes":[]},{"n":15,"t":"愚昧迷住孩童的心，用管教的杖可以远远赶除。","notes":[]},{"n":16,"t":"欺压贫寒人为要利己的，并送礼给有钱人的，都必缺乏。","notes":[]},{"n":17,"t":"你要侧耳听智慧人的言语，留心领会我的知识。","notes":["“你要...言语”：七十士译本是“智慧人的言语：你要侧耳听我的言语”。"]},{"n":18,"t":"你若心中存记，嘴唇也准备就绪，这是美的。","notes":[]},{"n":19,"t":"我今日特地指教你，为要使你倚靠耶和华。","notes":[]},{"n":20,"t":"谋略和知识的美事，我岂没有写给你吗？","notes":["“美事”：原文另译“三十句”。"]},{"n":21,"t":"要使你明白真情实理，好将实情回覆那差你来的人。","notes":[]},{"n":22,"t":"不可因人贫寒就抢夺他，也不可在城门口欺压困苦人，","notes":[]},{"n":23,"t":"因耶和华必为他们辩护，也必夺取那抢夺者的命。","notes":[]},{"n":24,"t":"不可结交好生气的人，也不可与暴怒的人来往，","notes":[]},{"n":25,"t":"恐怕你效法他的行为，自己就陷在圈套里。","notes":[]},{"n":26,"t":"不要为人击掌担保，也不要为债务作保。","notes":[]},{"n":27,"t":"你若没有什么可偿还，何必使人夺去你睡卧的床呢？","notes":[]},{"n":28,"t":"祖先所立的地界，你不可挪移。","notes":[]},{"n":29,"t":"你看见办事殷勤的人吗？他必侍立在君王面前，不在平庸的人面前。","notes":[]}]},"23":{"heading":"","verses":[{"n":1,"t":"你若与长官坐席，要留意在你面前的是谁。","notes":[]},{"n":2,"t":"你若是胃口大的人，就当拿刀放在喉咙上。","notes":[]},{"n":3,"t":"不可贪恋长官的美食，因为那是欺哄人的食物。","notes":[]},{"n":4,"t":"不要劳碌求富，要有聪明来节制。","notes":[]},{"n":5,"t":"你定睛在财富，它就消失，因为它必长翅膀，如鹰向天飞去。","notes":[]},{"n":6,"t":"守财奴的饭，你不要吃，也不要贪恋他的美味；","notes":["“守财奴”：原文直译“眼目邪恶的人”。"]},{"n":7,"t":"因为他的心怎样算计，他为人就是这样。他虽对你说：请吃，请喝，他的心却与你相背。","notes":["“心怎样算计”：原文另译“喉咙有头发”。"]},{"n":8,"t":"你所吃的那点食物必吐出来，你恭维的话语也必落空。","notes":[]},{"n":9,"t":"不要说话给愚昧人听，因他必藐视你智慧的言语。","notes":[]},{"n":10,"t":"不可挪移古时的地界，也不可侵占孤儿的田地，","notes":[]},{"n":11,"t":"因他们的救赎者大有能力，他必向你为他们辩护。","notes":["“救赎者”或译“赎业至亲”。"]},{"n":12,"t":"你要留心领受训诲，侧耳听从知识的言语。","notes":[]},{"n":13,"t":"不可不管教孩童，因为你用杖打他，他不会死。","notes":[]},{"n":14,"t":"你用杖打他，就可以救他的性命免下阴间。","notes":[]},{"n":15,"t":"我儿啊，你若心存智慧，我的心就甚欢喜。","notes":[]},{"n":16,"t":"你的嘴唇若说正直话，我的心肠也必快乐。","notes":[]},{"n":17,"t":"你的心不要羡慕罪人，却要羡慕常常敬畏耶和华的人，","notes":[]},{"n":18,"t":"因为你必有前途，你的指望也不致断绝。","notes":[]},{"n":19,"t":"我儿啊，你当听，当存智慧，好在正道上引导你的心。","notes":[]},{"n":20,"t":"不可与好饮酒的人在一起，也不要跟贪吃肉的人来往，","notes":[]},{"n":21,"t":"因为贪食好酒的，必致贫穷，爱睡觉的，必穿破烂衣服。","notes":[]},{"n":22,"t":"你要听从生你的父亲；不可因母亲年老而轻看她。","notes":[]},{"n":23,"t":"你当获得真理，不可出卖，智慧、训诲和聪明也是一样。","notes":[]},{"n":24,"t":"义人的父亲必大大快乐，生智慧儿子的，必因他欢喜。","notes":[]},{"n":25,"t":"愿你的父母欢喜，愿那生你的母亲快乐。","notes":[]},{"n":26,"t":"我儿啊，要将你的心归我，你的眼目也要喜爱我的道路。","notes":["“喜爱”：原文另译“谨守”。"]},{"n":27,"t":"妓女是深坑，外邦女子是窄井。","notes":[]},{"n":28,"t":"她像强盗埋伏，她使奸诈的人增多。","notes":[]},{"n":29,"t":"谁有祸患？谁有灾难？谁有纷争？谁有焦虑？谁无故受伤？谁的眼目红赤？","notes":[]},{"n":30,"t":"就是那流连饮酒的人，常去寻找调和的酒。","notes":[]},{"n":31,"t":"酒发红，在杯中闪烁时，你不可观看；虽下咽舒畅，终究它必咬你如蛇，刺你如毒蛇。","notes":[],"end":32},{"n":33,"t":"你的眼睛必看见怪异的事，你的心必发出乖谬的话。","notes":[]},{"n":34,"t":"你必像躺在深海中，或卧在桅杆顶上，","notes":[]},{"n":35,"t":"说：“人击打我，但我未受伤，重击我，我不觉得。我几时清醒，还要再去寻酒。”","notes":[]}]},"24":{"heading":"其他智言","verses":[{"n":1,"t":"你不要嫉妒恶人，也不要渴望与他们相处，","notes":[]},{"n":2,"t":"因为他们的心图谋暴行，他们的嘴唇谈论奸恶。","notes":[]},{"n":3,"t":"房屋因智慧建造，因聪明立稳；","notes":[]},{"n":4,"t":"又因知识，屋内充满各样美好宝贵的财物。","notes":[]},{"n":5,"t":"有智慧的勇士大有能力，有知识的人力上加力。","notes":[]},{"n":6,"t":"你去打仗，要凭智谋；谋士众多，就必得胜。","notes":[]},{"n":7,"t":"对愚妄人，智慧高不可及，所以他在城门不敢开口。","notes":[]},{"n":8,"t":"图谋行恶的，必称为奸诈人。","notes":[]},{"n":9,"t":"愚妄人的筹划尽是罪恶，傲慢者为人所憎恶。","notes":[]},{"n":10,"t":"在患难时你若灰心，你的力量就微小。","notes":[]},{"n":11,"t":"人被拉到死亡，你要解救；人将被杀，你须拦阻。","notes":[]},{"n":12,"t":"你若说：“看哪，这事我们不知道”，那衡量人心的岂不明白吗？保护你性命的岂不知道吗？他岂不按各人所做的报应各人吗？","notes":[]},{"n":13,"t":"我儿啊，你要吃蜜，因为它是美好的，要让甘甜的蜜滴入你的口。","notes":[]},{"n":14,"t":"你要知道，智慧对你的生命正像如此。你若找着，必有前途，你的指望也不致断绝。","notes":[]},{"n":15,"t":"你这恶人，不可埋伏攻击义人的家，也不可毁坏他安居之所。","notes":[]},{"n":16,"t":"因为义人虽七次跌倒，仍必兴起；恶人却被祸患倾倒。","notes":[]},{"n":17,"t":"你的仇敌跌倒，你不要欢喜，他倾倒，你的心不要快乐；","notes":[]},{"n":18,"t":"恐怕耶和华看见就不喜悦，将怒气从仇敌身上转过来。","notes":[]},{"n":19,"t":"不要为作恶的心怀不平，也不要嫉妒恶人，","notes":[]},{"n":20,"t":"因为坏人没有前途，恶人的灯也必熄灭。","notes":[]},{"n":21,"t":"我儿啊，你要敬畏耶和华与君王，不可结交反覆无常的人，","notes":[]},{"n":22,"t":"因为他们的灾难必忽然兴起。谁能知道耶和华与君王所施行的毁灭呢？","notes":[]},{"n":23,"t":"以下也是智慧人的箴言：审判时看人情面是不好的。","notes":[]},{"n":24,"t":"对恶人说“你是义人”的，万民必诅咒，万族必恼恨。","notes":[]},{"n":25,"t":"责备恶人的，必得喜悦，美好的福分也必临到他。","notes":[]},{"n":26,"t":"应对合宜的，犹如与人亲吻。","notes":[]},{"n":27,"t":"你要在外面预备材料，在田间为自己准备齐全，然后才建造你的房屋。","notes":[]},{"n":28,"t":"不可无故作证反对邻舍，也不可用嘴唇欺骗人。","notes":[]},{"n":29,"t":"不可说：“人怎样待我，我也怎样待他，我必照他所做的报复他。”","notes":[]},{"n":30,"t":"我经过懒惰人的田地，走过无知人的葡萄园，","notes":[]},{"n":31,"t":"看哪，它长满了荆棘，荨麻盖地面，石墙也坍塌了。","notes":[]},{"n":32,"t":"我看见就留心思想，我看着就领受训诲。","notes":[]},{"n":33,"t":"再睡片时，打盹片时，抱着双臂躺卧片时，","notes":[]},{"n":34,"t":"你的贫穷就如盗贼来到，你的贫乏仿佛拿盾牌的人来临。","notes":[]}]},"25":{"heading":"所罗门的另一些箴言","verses":[{"n":1,"t":"以下也是所罗门的箴言，是犹大王希西家的人所誊录的。","notes":[]},{"n":2,"t":"隐藏事情是神的荣耀；查明事情乃君王的荣耀。","notes":[]},{"n":3,"t":"天之高，地之深，君王之心测不透。","notes":[]},{"n":4,"t":"除去银子的渣滓，银匠就做出器皿来。","notes":[]},{"n":5,"t":"除去王面前的恶人，国位就靠公义坚立。","notes":[]},{"n":6,"t":"不可在君王面前妄自尊大，也不要站在大人的位上。","notes":[]},{"n":7,"t":"宁可让人家说“请你上到这里来”，强如在你觐见的贵人面前令你退下。","notes":[]},{"n":8,"t":"不要冒失出去与人争讼 ，免得你的邻舍羞辱你，最后你就不知怎么做。","notes":["“强如...争讼”或译“强如在贵人面前令你退下。你所看见的，不要冒失出去与人争讼”。"]},{"n":9,"t":"要与邻舍争辩你的案情，不可泄漏他人的隐密，","notes":[]},{"n":10,"t":"恐怕听见的人责骂你，你就难以摆脱臭名。","notes":[]},{"n":11,"t":"一句话说得合宜，就如金苹果在银网子里。","notes":["“在银网子里”或译“在银的底座上”。"]},{"n":12,"t":"智慧人的劝戒在顺从的人耳中，好像金环和金首饰。","notes":[]},{"n":13,"t":"忠信的使者对那差他的人，就如收割时有冰雪的凉气，使主人的心舒畅。","notes":[]},{"n":14,"t":"人空夸礼物而不肯赠送，就好像有风有云却无雨。","notes":[]},{"n":15,"t":"恒常的忍耐可以劝服君王，柔和的舌头能折断骨头。","notes":[]},{"n":16,"t":"你得了蜜，吃够就好，免得过饱就吐出来。","notes":[]},{"n":17,"t":"你的脚要少进邻舍的家，免得他厌烦你，恨恶你。","notes":[]},{"n":18,"t":"作假见证陷害邻舍的，就是大锤，是利刀，是快箭。","notes":[]},{"n":19,"t":"患难时倚靠奸诈的人，好像牙齿断裂，又如脚脱臼。","notes":[]},{"n":20,"t":"对伤心的人唱歌，就如冷天脱他的衣服，又如在碱上倒醋。","notes":["“在碱上倒醋”：七十士译本是“在伤口上洒醋”。"]},{"n":21,"t":"你的仇敌若饿了，就给他饭吃，若渴了，就给他水喝；","notes":[]},{"n":22,"t":"因为你这样做，就是把炭火堆在他的头上，耶和华必回报你。","notes":[]},{"n":23,"t":"正如北风生雨，毁谤的舌头也生怒容。","notes":[]},{"n":24,"t":"宁可住在房顶的一角，也不与好争吵的妇人同住。","notes":[]},{"n":25,"t":"有好消息从遥远的地方来，就如凉水滋润口渴的人。","notes":[]},{"n":26,"t":"义人在恶人面前退缩，好像搅浑之泉，污染之井。","notes":[]},{"n":27,"t":"吃蜜过多是不好的，自求荣耀也是一样。","notes":[]},{"n":28,"t":"人不克制自己的心，就像毁坏的城没有墙。","notes":[]}]},"26":{"heading":"","verses":[{"n":1,"t":"愚昧人得尊荣不相宜，正如夏天落雪，收割时下雨。","notes":[]},{"n":2,"t":"诅咒不会无故临到，正如麻雀掠过，燕子翻飞。","notes":["“诅咒...临到”：原文另译“无故的诅咒必返回自己身上”。"]},{"n":3,"t":"鞭子是为打马，辔头是为勒驴，刑杖正是为打愚昧人的背。","notes":[]},{"n":4,"t":"不要照愚昧人的愚昧话回答他，免得你与他一样。","notes":[]},{"n":5,"t":"要照愚昧人的愚昧话回答他，免得他自以为有智慧。","notes":[]},{"n":6,"t":"藉愚昧人的手寄信的，就像砍断双脚，喝下残暴。","notes":[]},{"n":7,"t":"箴言在愚昧人的口中，正如瘸子的脚悬空无用。","notes":[]},{"n":8,"t":"将尊荣给愚昧人的，就像石头绑在弹弓上。","notes":[]},{"n":9,"t":"箴言在愚昧人的口中，好像荆棘刺入醉汉的手。","notes":[]},{"n":10,"t":"雇愚昧人的，与雇过路人的，就像弓箭手射伤任何人。","notes":[]},{"n":11,"t":"愚昧人重复做愚昧之事，就如狗转过来吃自己所吐的。","notes":[]},{"n":12,"t":"你看见自以为有智慧的人吗？愚昧人比他更有指望。","notes":[]},{"n":13,"t":"懒惰人说：“道路有猛狮，街上有壮狮。”","notes":[]},{"n":14,"t":"懒惰人在床上，就像门在轴心上转动一样。","notes":[]},{"n":15,"t":"懒惰人把手埋入盘里，就是送进口中也觉得累。","notes":[]},{"n":16,"t":"懒惰人眼看自己比七个善于应对的人更有智慧。","notes":[]},{"n":17,"t":"过路时卷入与己无关的纷争，好像人揪住狗耳一般。","notes":[]},{"n":18,"t":"人欺骗邻舍，却说“我只是开玩笑而已”，他就像疯狂的人抛掷致死的火把和利箭。","notes":[],"end":19},{"n":20,"t":"火缺了柴就必熄灭；无人造谣，纷争就止息。","notes":[]},{"n":21,"t":"好争吵的人煽动争端，就如余火加炭，火上加柴一样。","notes":[]},{"n":22,"t":"造谣者的话如同美食，深入人的肚腹。","notes":[]},{"n":23,"t":"火热的嘴唇，邪恶的心，好像银渣包在瓦器上。","notes":["“火热的”：七十士译本是“油滑的”。"]},{"n":24,"t":"仇敌用嘴唇掩饰，心里却藏着诡诈；","notes":[]},{"n":25,"t":"他用甜言蜜语，你不能相信他，因为他心中有七样可憎恶的事。","notes":[]},{"n":26,"t":"他虽用诡诈掩饰怨恨，他的邪恶必在集会中显露。","notes":[]},{"n":27,"t":"挖陷坑的，自己必陷在其中；滚石头的，石头反滚在他身上。","notes":[]},{"n":28,"t":"虚谎的舌憎恨他所压伤的人；谄媚的口败坏人的事。","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"不要为明天自夸，因为你不知道每天会发生何事。","notes":[]},{"n":2,"t":"要让陌生人夸奖你，不可用口自夸；让外邦人称赞你，不可用嘴唇称赞自己。","notes":[]},{"n":3,"t":"石头沉，沙土重，愚妄人的恼怒比这两样更沉重。","notes":[]},{"n":4,"t":"愤怒为残忍，怒气像狂澜，惟有嫉妒，谁能挡得住呢？","notes":[]},{"n":5,"t":"当面的责备胜过隐藏的爱情。","notes":[]},{"n":6,"t":"朋友加的伤痕出于忠诚；敌人的亲吻却是多余。","notes":[]},{"n":7,"t":"人吃饱了，厌恶蜂房的蜜；人饥饿了，一切苦物都觉甘甜。","notes":[]},{"n":8,"t":"人离故乡漂泊，就像雀鸟离窝四处飞翔。","notes":[]},{"n":9,"t":"膏油与香料使人心喜悦，朋友诚心的劝勉也是如此甘美。","notes":[]},{"n":10,"t":"你的朋友和父亲的朋友，你都不可离弃。你遭难时，不要上兄弟的家去；相近的邻舍强如远方的兄弟。","notes":[]},{"n":11,"t":"我儿啊，你要做智慧人，好叫我的心欢喜，使我可以回答那辱骂我的人。","notes":[]},{"n":12,"t":"通达人见祸就藏躲；愚蒙人却前往受害。","notes":[]},{"n":13,"t":"谁为陌生人担保，就拿谁的衣服；谁为外邦女子作保，谁就要承当。","notes":[]},{"n":14,"t":"清晨起来大声给朋友祝福的，就算是诅咒他。","notes":[]},{"n":15,"t":"下雨天连连滴漏，好争吵的妇人就像这样；","notes":[]},{"n":16,"t":"拦阻她的，就是拦阻风，又像用右手抓油。","notes":[]},{"n":17,"t":"以铁磨铁，越磨越利，朋友当面琢磨，也是如此。","notes":[]},{"n":18,"t":"看守无花果树的，必吃树上的果子；敬奉主人的，必得尊荣。","notes":[]},{"n":19,"t":"水中照脸，彼此相符；人心相映，也是如此。","notes":[]},{"n":20,"t":"阴间和冥府永不满足，人的眼目也是如此。","notes":["“冥府”：原文音译“亚巴顿”，意思是“灭亡之地”。"]},{"n":21,"t":"鼎为炼银，炉为炼金，口中的称赞也试炼人。","notes":[]},{"n":22,"t":"用杵把愚妄人与谷粒一同捣在臼中，他的愚昧还是离不了他。","notes":[]},{"n":23,"t":"你要详细知道你羊群的景况，留心照顾你的牛群，","notes":[]},{"n":24,"t":"因为财富不能永留，冠冕岂能存到万代？","notes":[]},{"n":25,"t":"青草除去，嫩草长出，山上的菜蔬也被采收。","notes":[]},{"n":26,"t":"绵羊可以做衣服，公山羊可作田地的价值，","notes":[]},{"n":27,"t":"并有母山羊奶够你吃，够你养家和女仆的生活。","notes":[]}]},"28":{"heading":"","verses":[{"n":1,"t":"恶人虽无人追赶也逃跑；义人却胆壮像狮子。","notes":[]},{"n":2,"t":"地上因有罪过，君王就多更换；因聪明和有见识的人，国必长存。","notes":[]},{"n":3,"t":"穷乏人欺压贫寒人，好像暴雨扫过，不留粮食。","notes":[]},{"n":4,"t":"离弃律法的，夸奖恶人；遵守律法的，却与恶人相争。","notes":[]},{"n":5,"t":"恶人不明白公义；惟有寻求耶和华的，无不明白。","notes":[]},{"n":6,"t":"行为纯正的穷乏人胜过行事歪曲的有钱人。","notes":[]},{"n":7,"t":"谨守教诲的，是聪明之子；与贪食者为伍的，却羞辱其父。","notes":[]},{"n":8,"t":"人以厚利增加财富，是给那怜悯贫寒人的积财。","notes":[]},{"n":9,"t":"转耳不听教诲的，他的祈祷也可憎。","notes":[]},{"n":10,"t":"诱惑正直人行恶道的，必掉在自己的坑里；惟有完全人必承受福分。","notes":[]},{"n":11,"t":"有钱人自以为有智慧，但聪明的贫寒人能看穿他。","notes":[]},{"n":12,"t":"义人高升，有大荣耀；恶人兴起，人就躲藏。","notes":[]},{"n":13,"t":"遮掩自己过犯的，必不顺利；承认且离弃过犯的，必蒙怜悯。","notes":[]},{"n":14,"t":"常存敬畏的，这人有福了；心里刚硬的，必陷在祸患里。","notes":[]},{"n":15,"t":"邪恶的君王压制贫民，好像吼叫的狮子，又如觅食的熊。","notes":[]},{"n":16,"t":"无知的君王多行暴虐；恨恶非分之财的，必年长日久。","notes":[]},{"n":17,"t":"背负流人血之罪的，必逃跑直到地府；愿无人帮助他！","notes":[]},{"n":18,"t":"行为正直的，必蒙拯救；行事弯曲的，立时跌倒。","notes":[]},{"n":19,"t":"耕种自己田地的，粮食充足；追求虚浮的，穷困潦倒。","notes":[]},{"n":20,"t":"诚实人必多得福；想要急速发财的，难免受罚。","notes":[]},{"n":21,"t":"看人情面是不好的；却有人因一块饼而犯法。","notes":[]},{"n":22,"t":"守财奴想要急速发财，却不知穷乏必临到他身上。","notes":["“守财奴”：原文直译“眼目邪恶的人”。"]},{"n":23,"t":"责备人的，后来蒙人喜悦，多于那用舌头谄媚人的。","notes":[]},{"n":24,"t":"抢夺父母竟说“这不是罪过”，此人与毁灭者同类。","notes":[]},{"n":25,"t":"心中贪婪的，挑起争端；倚靠耶和华的，必得丰裕。","notes":[]},{"n":26,"t":"心中自以为是的，就是愚昧人；凭智慧行事的，必蒙拯救。","notes":[]},{"n":27,"t":"周济穷乏人的，不致缺乏；遮眼不看的，多受诅咒。","notes":[]},{"n":28,"t":"恶人兴起，人就躲藏；恶人败亡，义人必增多。","notes":[]}]},"29":{"heading":"","verses":[{"n":1,"t":"人屡次受责罚，仍然硬着颈项，他必顷刻被毁，无从医治。","notes":[]},{"n":2,"t":"义人增多，民就喜乐；恶人掌权，民就叹息。","notes":[]},{"n":3,"t":"爱慕智慧的，使父亲喜乐；结交妓女的，却浪费钱财。","notes":[]},{"n":4,"t":"王藉公平，使国坚定；强索贡物的，使它毁坏。","notes":[]},{"n":5,"t":"谄媚邻舍的，就是设网罗绊他的脚。","notes":[]},{"n":6,"t":"恶人犯罪，自陷圈套；惟独义人欢呼喜乐。","notes":[]},{"n":7,"t":"义人关注贫寒人的案情；恶人不明了这种知识。","notes":[]},{"n":8,"t":"傲慢人煽动全城；智慧人止息众怒。","notes":[]},{"n":9,"t":"智慧人与愚妄人有争讼，或怒或笑，总不得安宁。","notes":[]},{"n":10,"t":"好流人血的，恨恶完全人，正直人却顾惜他的性命。","notes":["“顾惜”：原文是“寻索”。"]},{"n":11,"t":"愚昧人怒气全发；智慧人自我平息。","notes":[]},{"n":12,"t":"君王若听谎言，他一切臣仆都是奸恶。","notes":[]},{"n":13,"t":"穷乏人和欺压者相遇，耶和华使他们的眼目明亮。","notes":["“相遇”或译“是一样的”。"]},{"n":14,"t":"君王凭诚信判断贫寒人，他的国位必永远坚立。","notes":[]},{"n":15,"t":"杖打和责备能增加智慧；任性的少年使母亲羞愧。","notes":[]},{"n":16,"t":"恶人多，过犯也加多，义人必看见他们败亡。","notes":[]},{"n":17,"t":"管教你的儿子，他就使你得安宁，也使你心里喜乐。","notes":[]},{"n":18,"t":"没有异象，民就放肆；惟遵守律法的，便为有福。","notes":["“异象”或译“默示”。"]},{"n":19,"t":"仆人不能靠言语受教；他即使明白，也不回应。","notes":[]},{"n":20,"t":"你见过言语急躁的人吗？愚昧人比他更有指望。","notes":[]},{"n":21,"t":"人将仆人从小娇养，至终必带来忧伤。","notes":["“至终必带来忧伤”或译“这仆人至终必成了他的继承人”。"]},{"n":22,"t":"好生气的人挑起争端，暴怒的人多多犯错。","notes":[]},{"n":23,"t":"人的高傲使自己蒙羞；心里谦逊的，必得尊荣。","notes":[]},{"n":24,"t":"与盗贼分赃的，是恨恶自己的性命；他虽听见发誓的声音，也不告诉人。","notes":[]},{"n":25,"t":"惧怕人的，陷入圈套；惟有倚靠耶和华的，必得安稳。","notes":[]},{"n":26,"t":"求王恩的人多；人获公正来自耶和华。","notes":[]},{"n":27,"t":"不义之人，义人憎恶；行事正直的，恶人憎恶。","notes":[]}]},"30":{"heading":"亚古珥语录","verses":[{"n":1,"t":"雅基的儿子、玛撒人亚古珥的言语，是这人对以铁和乌甲说的。","notes":["“雅基...言语”或译“雅基的儿子亚古珥的言语，就是神谕”。"]},{"n":2,"t":"我比众人更像畜牲，也没有人的聪明。","notes":[]},{"n":3,"t":"我没有学好智慧，也不认识至圣者。","notes":[]},{"n":4,"t":"谁升天又降下来？谁聚风在手掌中？谁包水在衣服里？谁立定地的四极？他名叫什么？他儿子名叫什么？你知道吗？","notes":[]},{"n":5,"t":"神的言语句句都是炼净的，投靠他的，他便作他们的盾牌。","notes":[]},{"n":6,"t":"你不可加添他的言语，恐怕他责备你，你就显为说谎的。","notes":[]},{"n":7,"t":"我求你两件事，在我未死之先，不要拒绝我：","notes":[],"heads":["其他箴言"]},{"n":8,"t":"求你使虚假和谎言远离我，使我不贫穷也不富足，赐给我需用的饮食。","notes":[]},{"n":9,"t":"免得我饱足了，就不认你，说：“耶和华是谁呢？”又恐怕我贫穷就偷窃，以致亵渎我神的名。","notes":[]},{"n":10,"t":"不要向主人谗害他的仆人，恐怕他诅咒你，你便算为有罪。","notes":[]},{"n":11,"t":"有一类人，诅咒父亲，不给母亲祝福。","notes":[]},{"n":12,"t":"有一类人，自以为纯洁，却没有洗净自己的污秽。","notes":[]},{"n":13,"t":"有一类人，眼目何其高傲，眼皮也是高举。","notes":[]},{"n":14,"t":"有一类人，牙如剑，齿如刀，要吞灭地上的困苦人和世间的贫穷人。","notes":[]},{"n":15,"t":"水蛭有两个女儿：“给呀，给呀。”有三样不知足的，不说“够了”的有四样：","notes":[]},{"n":16,"t":"阴间和不生育的子宫，吸水不足的地，还有不说“够了”的火。","notes":[]},{"n":17,"t":"嘲笑父亲、藐视而不听从母亲的，谷中的乌鸦必啄他的眼睛，小鹰也必吃它。","notes":[]},{"n":18,"t":"我所测不透的奇妙有三样，我所不知道的有四样：","notes":[]},{"n":19,"t":"就是鹰在空中飞的道，蛇在磐石上爬的道，船在海中行的道，男与女交合的道。","notes":[]},{"n":20,"t":"淫妇的道是这样，她吃了，把嘴一擦就说：“我没有行恶。”","notes":[]},{"n":21,"t":"使地震动的有三样，地承担不起的有四样：","notes":[]},{"n":22,"t":"就是仆人作王，愚顽人吃得饱足，","notes":[]},{"n":23,"t":"令人憎恶的女子出嫁，婢女取代她的女主人。","notes":[]},{"n":24,"t":"地上有四样东西虽小，却甚聪明：","notes":[]},{"n":25,"t":"蚂蚁是无力之类，却在夏天预备粮食。","notes":[]},{"n":26,"t":"石獾并非强壮之类，却在岩石中造房子。","notes":[]},{"n":27,"t":"蝗虫没有君王，却分队而出。","notes":[]},{"n":28,"t":"壁虎你用手就可抓住，它却住在王宫。","notes":[]},{"n":29,"t":"脚步威武的有三样，行走威武的有四样：","notes":[]},{"n":30,"t":"狮子－百兽中最勇猛的、无论遇见什么绝不退缩，","notes":[]},{"n":31,"t":"猎狗，公山羊，和有整排士兵的君王。","notes":[]},{"n":32,"t":"你若行事愚顽，自高自傲，或是设计恶谋，就当用手捂口。","notes":[]},{"n":33,"t":"搅动牛奶必成乳酪，扭鼻子必出血，照样，激发烈怒必挑起争端。","notes":[]}]},"31":{"heading":"给君王的忠告","verses":[{"n":1,"t":"玛撒王利慕伊勒的言语，就是他母亲教导他的。","notes":["“玛撒王...他的”或译“利慕伊勒王的言语，是他母亲教导他的神谕”。"]},{"n":2,"t":"我儿，怎么了？我腹中生的儿，怎么了？我许愿而得的儿，怎么了？","notes":[]},{"n":3,"t":"不要将你的精力给妇女，也不要有败坏君王的行为。","notes":[]},{"n":4,"t":"利慕伊勒啊，君王不宜，君王不宜喝酒，王子寻找烈酒也不相宜；","notes":[]},{"n":5,"t":"恐怕喝了就忘记所颁的法令，颠倒所有困苦人的是非。","notes":[]},{"n":6,"t":"可以把烈酒给将亡的人喝，把酒给心里愁苦的人喝，","notes":[]},{"n":7,"t":"让他喝了，就忘记他的贫穷，不再记得他的苦楚。","notes":[]},{"n":8,"t":"你当为不能自辩的人开口，为所有孤独无助者伸冤。","notes":["“不能自辩的人”或译“哑巴”。"]},{"n":9,"t":"你当开口按公义判断，当为困苦和贫穷的人辩护。","notes":[]},{"n":10,"t":"才德的妇人谁能得着呢？她的价值远胜过宝石。","notes":["由本节开始，原文是字母诗。"],"heads":["论贤妻"]},{"n":11,"t":"她丈夫心里信赖她，必不缺少利益；","notes":[]},{"n":12,"t":"她终其一生，使丈夫有益无损。","notes":[]},{"n":13,"t":"她寻找羊毛和麻，欢喜用手做工。","notes":[]},{"n":14,"t":"她好像商船，从远方运来粮食，","notes":[]},{"n":15,"t":"未到黎明她就起来，把食物分给家中的人，将当做的工分派女仆。","notes":[]},{"n":16,"t":"她想得田地，就去买来，用手中的成果栽葡萄园。","notes":[]},{"n":17,"t":"她以能力束腰，使膀臂有力。","notes":[]},{"n":18,"t":"她觉得自己获利不错，她的灯终夜不灭。","notes":[]},{"n":19,"t":"她伸手拿卷线杆，她的手掌把住纺车。","notes":[]},{"n":20,"t":"她张手周济困苦人，伸手帮助贫穷人。","notes":[]},{"n":21,"t":"她不因下雪为家里的人担心，因为全家都穿上朱红衣服。","notes":[]},{"n":22,"t":"她为自己制作被单，她的衣服是细麻和紫色布做的。","notes":[]},{"n":23,"t":"她丈夫在城门口与本地的长老同坐，为人所认识。","notes":[]},{"n":24,"t":"她做细麻布衣裳来卖，又将腰带卖给商家。","notes":[]},{"n":25,"t":"能力和威仪是她的衣服，她想到日后的景况就喜笑。","notes":[]},{"n":26,"t":"她开口就发智慧，她舌上有仁慈的教诲。","notes":[]},{"n":27,"t":"她管理家务，并不吃闲饭。","notes":[]},{"n":28,"t":"她的儿女起来称她有福，她的丈夫也称赞她：","notes":[]},{"n":29,"t":"“才德的女子很多，惟独你超过一切。”","notes":[]},{"n":30,"t":"魅力是虚假的，美貌是虚浮的；惟敬畏耶和华的妇女必得称赞。","notes":[]},{"n":31,"t":"她手中的成果你们要赏给她，愿她的工作在城门口荣耀她。","notes":[]}]}},"ECC":{"1":{"heading":"人生的虚空","verses":[{"n":1,"t":"在耶路撒冷作王、大卫的儿子、传道者的言语。","notes":[]},{"n":2,"t":"传道者说：虚空的虚空，虚空的虚空，全是虚空。","notes":[]},{"n":3,"t":"人一切的劳碌，就是他在日光之下的劳碌，有什么益处呢？","notes":[]},{"n":4,"t":"一代过去，一代又来，地却永远长存。","notes":[]},{"n":5,"t":"太阳上升，太阳落下，急归所出之地。","notes":[]},{"n":6,"t":"风往南刮，又向北转，不停旋转，绕回原路。","notes":[]},{"n":7,"t":"江河都往海里流，海却不满；江河从何处流，仍归回原处。","notes":[]},{"n":8,"t":"万事令人厌倦，人不能说尽。眼看，看不饱；耳听，听不足。","notes":[]},{"n":9,"t":"已有的事，后必再有；已行的事，后必再行。日光之下并无新事。","notes":[]},{"n":10,"t":"有一件事人指着说：“看，这是新的！”它在我们以前的世代早已有了。","notes":[]},{"n":11,"t":"已过的事，无人记念；将来的事，后来的人也不记念。","notes":[]},{"n":12,"t":"我传道者在耶路撒冷作过以色列的王。","notes":[],"heads":["传道者的经验"]},{"n":13,"t":"我用智慧专心探寻、考察天下所发生的一切事：神给世人何等沉重的担子，使他们在其中劳苦！","notes":[]},{"n":14,"t":"我见日光之下所发生的一切事，看哪，全是虚空，全是捕风。","notes":[]},{"n":15,"t":"弯曲的，不能变直；缺乏的，不计其数。","notes":[]},{"n":16,"t":"我心里说：“看哪，我大有智慧，胜过在我以前所有统治耶路撒冷的人；我的心也多经历智慧和知识的事。”","notes":[]},{"n":17,"t":"我专心想要明白智慧，想要明白狂妄与愚昧，方知这也是捕风。","notes":[]},{"n":18,"t":"因为多有智慧，就多有愁烦；增加知识，就增加忧伤。","notes":[]}]},"2":{"heading":"","verses":[{"n":1,"t":"我心里说：“来吧，让我用喜乐试试你，使你享福！”看哪，这也是虚空。","notes":[]},{"n":2,"t":"论嬉笑，我说：“这是狂妄。”论享乐，“这有什么用呢？”","notes":[]},{"n":3,"t":"我心以智慧引导我，我心里探究，如何用酒使身体舒畅，如何抓住愚昧，直等我看明世人在天下短暂一生中，当行何事为美。","notes":[]},{"n":4,"t":"我大兴土木，为自己建造房屋，栽葡萄园，","notes":[]},{"n":5,"t":"修造庭园和公园，在其中栽种各样果树，","notes":[]},{"n":6,"t":"挖造水池，用以灌溉林中的幼树。","notes":[]},{"n":7,"t":"我买了仆婢，也有生在家中的仆婢；又有许多牛群羊群，胜过我以前所有在耶路撒冷的人。","notes":[]},{"n":8,"t":"我为自己积蓄金银，搜集各君王、各省份的财宝；又为自己得男女歌手和世人所喜爱的物，以及一个又一个的妃嫔。","notes":[]},{"n":9,"t":"这样，我就日渐昌盛，胜过我以前所有在耶路撒冷的人。我的智慧仍然存留。","notes":[]},{"n":10,"t":"凡我眼所求的，我没有克制它；我心所乐的，我没有不享受。因我的心要为一切的劳碌快乐，这是我从一切劳碌中所得的报偿。","notes":["“报偿”或译“福分”；3．22，5．18，9．9同。"]},{"n":11,"t":"后来，我回顾我手所经营的一切和我劳碌所做的工。看哪，全是虚空，全是捕风；在日光之下毫无益处。","notes":[]},{"n":12,"t":"我转而回顾智慧、狂妄和愚昧。在王以后来的人又如何呢？不过做先前所做的就是了。","notes":[]},{"n":13,"t":"于是我看出智慧胜过愚昧，如同光明胜过黑暗。","notes":[]},{"n":14,"t":"智慧人的眼目光明，愚昧人却在黑暗里行。但我知道他们都有相同的遭遇。","notes":["“光明”：原文是“在他头上”。"]},{"n":15,"t":"我心里就说：“愚昧人所遇见的，我也一样遇见，那么我何必更有智慧呢？”我心里说：“这也是虚空。”","notes":[]},{"n":16,"t":"智慧人和愚昧人一样，不会长久被人记念，因为日后都被遗忘。可叹！智慧人和愚昧人都一样会死亡。","notes":[]},{"n":17,"t":"于是我恨恶生命，因为在日光之下所发生的事我都以为烦恼，全是虚空，全是捕风。","notes":[]},{"n":18,"t":"我恨恶一切的劳碌，就是我在日光之下所劳碌的，因为我所得的必须留给我以后的人。","notes":[]},{"n":19,"t":"那人是智慧是愚昧，谁能知道呢？他竟要掌管我在日光之下用智慧劳碌所得的。这也是虚空。","notes":[]},{"n":20,"t":"我转想我在日光之下所劳碌的一切工作，心就绝望。","notes":[]},{"n":21,"t":"因为有人用智慧、知识、灵巧劳碌工作，所得来的却要遗留给未曾劳碌的人作产业。这也是虚空，大大不幸。","notes":[]},{"n":22,"t":"人一切的劳碌操心，就是他在日光之下所劳碌的，又得着了什么呢？","notes":[]},{"n":23,"t":"他日日忧虑，他的劳苦成为愁烦，连夜间心也不得休息。这也是虚空。","notes":[]},{"n":24,"t":"难道一个人有吃有喝，且在劳碌中享福，不是福气吗？我看这也是出于神的手。","notes":[]},{"n":25,"t":"论到吃用、享福，谁能胜过我呢？","notes":[]},{"n":26,"t":"神喜爱谁，就给谁智慧、知识和喜乐；惟有罪人，神使他劳苦，将他所储藏、所堆积的归给神所喜爱的人。这也是虚空，也是捕风。","notes":[]}]},"3":{"heading":"万事都有定时","verses":[{"n":1,"t":"凡事都有定期，天下每一事务都有定时。","notes":[]},{"n":2,"t":"生有时，死有时；栽种有时，拔出有时；","notes":["“拔出”：原文是“拔出所栽种的”。"]},{"n":3,"t":"杀戮有时，医治有时；拆毁有时，建造有时；","notes":[]},{"n":4,"t":"哭有时，笑有时；哀恸有时，跳舞有时；","notes":[]},{"n":5,"t":"丢石头有时，捡石头有时；怀抱有时，不抱有时；","notes":[]},{"n":6,"t":"寻找有时，失落有时；保存有时，抛弃有时；","notes":[]},{"n":7,"t":"撕裂有时，缝补有时；沉默有时，说话有时；","notes":[]},{"n":8,"t":"喜爱有时，恨恶有时；战争有时，和平有时。","notes":[]},{"n":9,"t":"这样，做事的人在他所劳碌的事上得到什么益处呢？","notes":[]},{"n":10,"t":"我观看神给世人的担子，使他们在其中劳苦：","notes":[]},{"n":11,"t":"神造万物，各按其时成为美好，又将永恒安放在世人心里；然而神从始至终的作为，人不能测透。","notes":[]},{"n":12,"t":"我知道，人除了终身喜乐纳福，没有一件幸福的事。","notes":[]},{"n":13,"t":"并且人人吃喝，在他的一切劳碌中享福，这也是神的赏赐。","notes":[]},{"n":14,"t":"我知道神所做的都必存到永远；无所增添，无所减少。神这样做，是要人在他面前存敬畏的心。","notes":[]},{"n":15,"t":"现今的事以前就有了，将来的事也早已有了，并且神使已过的事重新再来。","notes":["“使已过的事重新再来”：原文是“再寻回已过的事”。"]},{"n":16,"t":"我又见日光之下，应有公平之处有奸恶，应有公义之处也有奸恶。","notes":[],"heads":["世上的不公平"]},{"n":17,"t":"我心里说：“神必审判义人和恶人，因为在那里，各样事务，一切工作，都有定时。”","notes":[]},{"n":18,"t":"我心里说：“为世人的缘故，神考验他们，让他们看见自己不过像走兽一样。”","notes":[]},{"n":19,"t":"因为世人遭遇的，走兽也遭遇，所遭遇的都一样：这个怎样死，那个也怎样死，他们都有一样的气息。人不能强于走兽，全是虚空；","notes":[]},{"n":20,"t":"都归一处，都是出于尘土，也都归于尘土。","notes":[]},{"n":21,"t":"谁知道人的气息是往上升，走兽的气息是下入地呢？","notes":["本节或译“谁知道人的灵是往上升，兽的魂是下入地呢？”"]},{"n":22,"t":"总而言之，人能够在他经营的事上喜乐，是最好不过了，因为这是他应得的报偿。他身后的事谁能领他回来看呢？","notes":[]}]},"4":{"heading":"","verses":[{"n":1,"t":"我转而观看日光之下所发生的一切欺压之事。看哪，受欺压的流泪，无人安慰；欺压他们的有权势，也无人安慰。","notes":[]},{"n":2,"t":"因此，我赞叹那已死的死人，胜过那还活着的活人。","notes":[]},{"n":3,"t":"但那尚未出生，就是未曾见过日光之下所发生之恶事的，比这两种人更幸福。","notes":[]},{"n":4,"t":"我见人因彼此嫉妒而有一切的劳碌和各样工作的成就，这也是虚空，也是捕风。","notes":[]},{"n":5,"t":"愚昧人抱着双臂，自食其肉。","notes":[]},{"n":6,"t":"一掌满满而得享安静，胜过两掌满满而劳碌捕风。","notes":[]},{"n":7,"t":"我转而观看日光之下有一件虚空的事：","notes":[]},{"n":8,"t":"有人孤单无双，无子无兄弟，竟劳碌不息，眼目也不以财富为满足。他说：“我劳碌，自己却不享福，到底是为了谁呢？”这也是虚空，是极沉重的担子。","notes":[]},{"n":9,"t":"两个人总比一个人好，他们劳碌同得美好的报偿。","notes":[]},{"n":10,"t":"若是跌倒，这人可以扶起他的同伴；倘若孤身跌倒，没有别人扶起他来，这人就有祸了。","notes":[]},{"n":11,"t":"再者，二人同睡就都暖和，一人独睡怎能暖和呢？","notes":[]},{"n":12,"t":"若遇敌攻击，孤身难挡，二人就能抵挡他；三股合成的绳子不易折断。","notes":[]},{"n":13,"t":"贫穷而有智慧的年轻人，胜过年老不再纳谏的愚昧王，","notes":[]},{"n":14,"t":"那人从监牢里出来作王，在国中原是出身贫寒。","notes":[]},{"n":15,"t":"我见日光之下所有行走的活人，都跟随那年轻人，就是接续作王的那位。","notes":[]},{"n":16,"t":"他的百姓，就是他所治理的众人，多得无数；但后来的人还是不喜欢他。这也是虚空，也是捕风。","notes":[]}]},"5":{"heading":"不可随便许愿","verses":[{"n":1,"t":"你到神的殿要谨慎你的脚步；近前听，胜过愚昧人献祭，他们不知道自己在作恶。","notes":[]},{"n":2,"t":"在神面前你不可冒失开口，也不可心急发言；因为神在天上，你在地上，所以你的话语要少。","notes":[]},{"n":3,"t":"事务多，令人做梦；话语多，显出愚昧。","notes":[]},{"n":4,"t":"你向神许愿，还愿不可迟延，因他不喜欢愚昧人，你许的愿应当偿还。","notes":[]},{"n":5,"t":"你许愿不还，不如不许。","notes":[]},{"n":6,"t":"不可放任你的口使肉体犯罪，也不可在使者面前说是错许了。为何使神因你的声音发怒，败坏你手所做的呢？","notes":["“使者”：七十士译本是“神”。"]},{"n":7,"t":"多梦多言，其中多有虚空，你只要敬畏神。","notes":[]},{"n":8,"t":"你若在一个地区看见穷人受欺压，公义公平被掠夺，不要因此惊奇；有一位高过居高位的在鉴察，在他们之上还有更高的。","notes":[],"heads":["人生是虚空的"]},{"n":9,"t":"况且地的益处归众人，就是君王也受田地的供应。","notes":["本节或译“君王有耕种的田地，对全地是有益的。”"]},{"n":10,"t":"喜爱银子的，不因得银子满足；喜爱财富的，也不因得利益知足。这也是虚空。","notes":[]},{"n":11,"t":"货物增添，吃的人也增添，物主得什么益处呢？不过眼看而已！","notes":[]},{"n":12,"t":"劳碌的人不拘吃多吃少，睡得香甜；富人的丰足却不容他睡觉。","notes":[]},{"n":13,"t":"我见日光之下有一件令人忧伤的祸患，就是财主积存财富，反害自己。","notes":[]},{"n":14,"t":"他因遭遇不幸，财产尽失；他生了儿子，手里却一无所有。","notes":["“遭遇不幸”或译“经营不善”。"]},{"n":15,"t":"他怎样从母胎赤身而来，也必照样赤身而去；他所劳碌得来的，手中分毫不能带去。","notes":[]},{"n":16,"t":"这是一件令人忧伤的祸患。他来的时候怎样，去的时候也必怎样。他为风劳碌有什么益处呢？","notes":[]},{"n":17,"t":"并且他终身在黑暗中吃喝，多有烦恼、病痛和怒气。","notes":["“在黑暗中吃喝”：七十士译本是“黑暗和悲伤”。"]},{"n":18,"t":"看哪，我所见为善为美的，就是人在神赐他一生的日子吃喝，享受日光之下劳碌得来的好处，因为这是他应得的报偿。","notes":[]},{"n":19,"t":"而且，一个人蒙神赏赐财富与资产，又使他能享用，能获取自己当有的报偿，在他的劳碌中喜乐，这是神的赏赐。","notes":["“自己当有的报偿”或译“自己的福分”。"]},{"n":20,"t":"他不多思念自己一生的日子，因为神使他的心充满喜乐。","notes":[]}]},"6":{"heading":"","verses":[{"n":1,"t":"我见日光之下有一件祸患重压在人身上，","notes":[]},{"n":2,"t":"就是人蒙神赐他财富、资产和尊荣，以致他心里所愿的一样都不缺，只是神使他不能享用，反被外人享用。这是虚空，也是祸患。","notes":[]},{"n":3,"t":"人若生一百个儿子，活许多岁数；他即使寿命很长，心里却不因福乐而满足，又不得埋葬；我说，那流掉的胎比他倒好。","notes":[]},{"n":4,"t":"因为这胎虚虚而来，暗暗而去，名字被黑暗遮蔽，","notes":[]},{"n":5,"t":"而且没有见过天日，什么都不知道，这胎比那人倒享安息。","notes":[]},{"n":6,"t":"那人虽然活千年，再活千年，却不能享福；众人岂不都归同一个地方去吗？","notes":[]},{"n":7,"t":"人的劳碌都为口腹，心里却不知足。","notes":[]},{"n":8,"t":"智慧人比愚昧人有什么益处呢？困苦人在众人面前知道如何行，有什么益处呢？","notes":[]},{"n":9,"t":"眼睛所看的比心里妄想的倒好。这也是虚空，也是捕风。","notes":[]},{"n":10,"t":"先前所有的，早已起了名，人早知道人是如何的，不能与比自己强壮的相争。","notes":[]},{"n":11,"t":"话语多，虚空也增多，这对人有什么益处呢？","notes":[]},{"n":12,"t":"人一生虚度的日子，如影儿经过，谁知道什么才是对他有益呢？谁能告诉他身后在日光之下会发生什么事呢？","notes":[]}]},"7":{"heading":"智愚之别","verses":[{"n":1,"t":"名誉强如美好的膏油，人死去的日子胜过他出生的日子。","notes":[]},{"n":2,"t":"往丧家去，强如往宴乐的家，因为死是众人的结局，活人必将这事放在心上。","notes":[]},{"n":3,"t":"忧愁强如喜笑，因为面带愁容，终必使心喜乐。","notes":[]},{"n":4,"t":"智慧人的心在遭丧之家；愚昧人的心在快乐之家。","notes":[]},{"n":5,"t":"听智慧人的责备，强如听愚昧人歌唱；","notes":[]},{"n":6,"t":"因为愚昧人的笑声，好像锅子下面烧荆棘的爆声，这也是虚空。","notes":[]},{"n":7,"t":"勒索使智慧人变为愚妄，贿赂能败坏人的心。","notes":[]},{"n":8,"t":"事情的终局强如它的起头；存心忍耐的，胜过居心骄傲的。","notes":[]},{"n":9,"t":"你的心不要急躁恼怒，因为恼怒存在愚昧人的怀中。","notes":[]},{"n":10,"t":"不要说：为什么先前的日子强过现今的日子呢？你这样问不是出于智慧。","notes":[]},{"n":11,"t":"智慧加上产业是美好的，对见天日的人都有益处。","notes":[]},{"n":12,"t":"因为智慧庇护人，好像金钱庇护人一样；智慧能保全智慧者的生命，这就是知识的益处。","notes":[]},{"n":13,"t":"你要观看神的作为，谁能使他所弯曲的变直呢？","notes":[]},{"n":14,"t":"顺利时要喜乐；患难时当思考。神使这两样都发生，因此，人不知将会发生什么事。","notes":[]},{"n":15,"t":"在虚度的日子里，我见过各样的事情，义人在他的义中灭亡，恶人在他的恶中倒享长寿。","notes":[]},{"n":16,"t":"不要行义过分，也不要过于自逞智慧，何必自取败亡呢？","notes":[]},{"n":17,"t":"不要行恶过分，也不要为人愚昧，何必未到期而死呢？","notes":[]},{"n":18,"t":"你持守这个，那个也不要松手才好。敬畏神的人，这一切都能兼得。","notes":[]},{"n":19,"t":"智慧使拥有智慧的人比城中十个官长更有能力。","notes":[]},{"n":20,"t":"其实世上没有行善而不犯罪的义人。","notes":[]},{"n":21,"t":"人所说的话，你不要都放在心上，免得听见你的仆人诅咒你。","notes":[]},{"n":22,"t":"因为你心里知道，自己也曾屡次诅咒别人。","notes":[]},{"n":23,"t":"我曾用智慧试验这一切事，我说：“要得智慧。”智慧却离我远。","notes":[]},{"n":24,"t":"万事之理遥不可及，太深奥，谁能测透呢？","notes":[]},{"n":25,"t":"我转念，一心要知道，要考察，要寻求智慧和万事的来由，要知道邪恶为愚昧，愚昧为狂妄。","notes":[]},{"n":26,"t":"我发现有一种妇人比死还苦毒：她本身是陷阱，她的心是罗网，手是锁链。凡蒙神喜爱的人必能躲开她；有罪的人却被她缠住了。","notes":[]},{"n":27,"t":"传道者说：“你看，我考察一件又一件，为要寻求万事的来由，这是我所寻得的：","notes":[]},{"n":28,"t":"我继续寻找，却未找到；一千当中，我找到一个男的，但在这一切当中，却找不到一个女的。","notes":[]},{"n":29,"t":"你看，我所找到的只有一件，就是神造的人是正直的，但他们却寻出许多诡计。”","notes":[]}]},"8":{"heading":"服从君王","verses":[{"n":1,"t":"谁如智慧人呢？谁知道事情的解释呢？人的智慧使他的脸发光，改变他脸上的暴戾之气。","notes":["“如”：七十士译本是“知道”。","“改变...暴戾之气”：七十士译本是“不知廉耻人的容貌为人所恨恶”。"]},{"n":2,"t":"我劝你因神誓言的缘故，当遵守王的命令。","notes":["七十士译本没有“我劝你”。"]},{"n":3,"t":"不要急躁离开王的面前，不要固执行恶，因为他凡事都随自己心意而行。","notes":[]},{"n":4,"t":"王的话本有权力，谁能对他说：“你在做什么？”","notes":[]},{"n":5,"t":"凡遵守命令的，必不经历祸患；智慧人的心知道适当的时机和必经的过程。","notes":[]},{"n":6,"t":"各样事务都有时机和过程，但人有苦难重压在身。","notes":[]},{"n":7,"t":"他不知道将来的事，其实将来如何，谁能告诉他呢？","notes":[]},{"n":8,"t":"没有人能掌握生命，将生命留住；也没有人有权力掌管死期。这场争战无人能免；邪恶也不能救那行邪恶的人。","notes":[]},{"n":9,"t":"这一切我都见过，我专心考察日光之下所发生的一切事，有时这人管辖那人，令他受害。","notes":[]},{"n":10,"t":"我见恶人被埋葬；从前他们进出圣地，他们在城中的作为被人忘记。这也是虚空。","notes":[],"heads":["恶人和义人"]},{"n":11,"t":"判罪之后不立刻执行，所以世人满怀作恶的心思。","notes":[]},{"n":12,"t":"罪人虽然作恶百次，倒享长寿；然而我也知道，福乐必临到敬畏神的人，就是在他面前心存敬畏的人。","notes":[]},{"n":13,"t":"恶人却不得福乐，他的日子好像影儿不得长久，因为他不敬畏神。","notes":[]},{"n":14,"t":"世上有一件虚空的事，就是义人所遭遇的，反而照恶人所做的；恶人所遭遇的，反而照义人所做的。我说，这也是虚空。","notes":[]},{"n":15,"t":"我就称赞快乐，原来人在日光之下，最大的福气莫过于吃喝快乐；他在日光之下，神赐他一生的日子，要从劳碌中享受所得。","notes":[]},{"n":16,"t":"我专心想要明白智慧，要观看世上所发生的事。有人昼夜不得阖眼睡觉。","notes":[]},{"n":17,"t":"我观看神一切的作为，知道人不能探求日光之下所发生的事；任凭他费多少力探索，都找不出来，智慧人虽说他明白，仍不能找出来。","notes":[]}]},"9":{"heading":"智慧胜过武力","verses":[{"n":1,"t":"我将这一切事放在心上，详细研究这些，就知道义人和智慧人，并他们的作为都在神手中；或是爱，或是恨，都在他们面前，但人不能知道。","notes":[]},{"n":2,"t":"凡临到众人的际遇都一样：义人和恶人，好人，洁净的人和不洁净的人，献祭的和不献祭的，都一样。好人如何，罪人也如何；起誓的如何，怕起誓的也如何。","notes":["“好人”：七十士译本是“好人和坏人”。"]},{"n":3,"t":"在日光之下发生的一切事中有一件祸患，就是众人的际遇都一样，并且世人的心充满了恶；活着的时候心里狂妄，后来就归死人那里去了。","notes":[]},{"n":4,"t":"与一切活人相连的，那人还有指望，因为活着的狗胜过死了的狮子。","notes":[]},{"n":5,"t":"活着的人知道必死；死了的人毫无所知，也不再得赏赐，因为他们的名已被遗忘。","notes":["“名”：原文是“纪念”。"]},{"n":6,"t":"他们的爱，他们的恨，他们的嫉妒，早就消灭了。在日光之下所发生的一切事，他们永不再有份了。","notes":[]},{"n":7,"t":"你只管欢欢喜喜吃你的饭，心中快乐喝你的酒，因为神已经悦纳你的作为。","notes":[]},{"n":8,"t":"你的衣服要时时洁白，你头上也不要缺少膏油。","notes":[]},{"n":9,"t":"在你一生虚空的日子，就是神赐你在日光之下虚空的日子，当与你所爱的妻快活度日，因为那是你一生中在日光之下劳碌所得的报偿。","notes":["七十士译本没有“虚空”。"]},{"n":10,"t":"凡你手所当做的事，要尽力去做；因为在你所必须去的阴间没有工作，没有谋算，没有知识，也没有智慧。","notes":[]},{"n":11,"t":"我转而回顾日光之下，快跑的未必能赢，强壮的未必战胜，智慧的未必得粮食，聪明的未必得财富，有学问的未必得人喜悦，全在乎各人遇上的时候和机会。","notes":[]},{"n":12,"t":"人不知道自己的定期。鱼被险恶的网圈住，鸟被罗网捉住，祸患的时刻忽然临到，世人陷在其中也是如此。","notes":[]},{"n":13,"t":"我见日光之下有一样智慧，在我看来是伟大的，","notes":[]},{"n":14,"t":"就是有一人口稀少的小城，遇大君王前来攻击，修筑营垒，将城围困。","notes":[]},{"n":15,"t":"城中有一个贫穷的智慧人，他用智慧救了那城，却没有人记念那穷人。","notes":[]},{"n":16,"t":"我就说，智慧胜过勇力；然而那贫穷人的智慧被人藐视，他的话也无人听从。","notes":[]},{"n":17,"t":"宁可听智慧人安静的话语，不听掌权者在愚昧人中的喊声。","notes":[]},{"n":18,"t":"智慧胜过打仗的兵器；但一个罪人能败坏许多善事。","notes":[]}]},"10":{"heading":"","verses":[{"n":1,"t":"死苍蝇使做香的膏油散发臭气；同样，一点愚昧也能压倒智慧和尊荣。","notes":[]},{"n":2,"t":"智慧人的心居右；愚昧人的心居左。","notes":[]},{"n":3,"t":"愚昧人的行径显出无知，对众人说，他是愚昧人。","notes":[]},{"n":4,"t":"掌权者的怒气若向你发作，不要离开你的本位，因为镇定能平息大过。","notes":[]},{"n":5,"t":"我见日光之下有一件祸患，似乎出于统治者的错误，","notes":[]},{"n":6,"t":"就是愚昧人立在高位；有钱人却坐在低位。","notes":[]},{"n":7,"t":"我见仆人骑马，王子像仆人在地上步行。","notes":[]},{"n":8,"t":"挖陷坑的，自己必陷在其中；拆城墙的，自己必被蛇咬。","notes":[]},{"n":9,"t":"开凿石头的，会受损伤；劈开木头的，必遭危险。","notes":[]},{"n":10,"t":"铁器钝了，若不将刃磨快，就必多费力气；但智慧的益处在于使人成功。","notes":[]},{"n":11,"t":"尚未行法术，蛇若咬人，行法术的人就得不到什么好处了。","notes":[]},{"n":12,"t":"智慧人的口说出恩言；愚昧人的嘴吞灭自己，","notes":[]},{"n":13,"t":"他口中的话语起头是愚昧，终局是邪恶的狂妄。","notes":[]},{"n":14,"t":"愚昧人多有话语。人不知将来会发生什么事，他身后的事谁能告诉他呢？","notes":[]},{"n":15,"t":"愚昧人的劳碌使自己困乏，连进城的路他也不知道。","notes":[]},{"n":16,"t":"邦国啊，你的君王若年少，你的群臣早晨宴乐，你就有祸了！","notes":[]},{"n":17,"t":"邦国啊，你的君王若是贵族之子，你的群臣按时吃喝，是为强身，不为酒醉，你就有福了！","notes":[]},{"n":18,"t":"因人懒惰，房顶塌下；因人手懒，房屋滴漏。","notes":[]},{"n":19,"t":"摆设宴席是为欢乐。酒能使人快活，钱能叫万事应心。","notes":[]},{"n":20,"t":"不可诅咒君王，连起意也不可，在卧室里也不可诅咒富人；因为空中的飞鸟必传扬这声音，有翅膀的必述说这事。","notes":[]}]},"11":{"heading":"智慧人的作为","verses":[{"n":1,"t":"当将你的粮食撒在水面上，因为日子久了，你必能得着它。","notes":[]},{"n":2,"t":"将你所拥有的分给七人，或八人，因为你不知道会有什么灾祸临到地上。","notes":[]},{"n":3,"t":"云若满了雨，就必倾倒在地上。树向南倒，或向北倒，树倒在何处，就留在何处。","notes":[]},{"n":4,"t":"看风的，必不撒种；望云的，必不收割。","notes":[]},{"n":5,"t":"你不知道气息如何进入孕妇的骨头里；照样，造万物之神的作为，你也无从得知。","notes":["“你不知道...骨头里”或译“风从何道来，骨头在孕妇的胎中如何长成，你尚且不得知道”。"]},{"n":6,"t":"早晨要撒种，晚上也不要歇手，因为你不知道哪一样发旺；前者或后者，或两者都一样好。","notes":[]},{"n":7,"t":"光是甜美的，眼见日光是多么好啊！","notes":[]},{"n":8,"t":"人活多少年，就当快乐多少年，然而也当想到黑暗的日子；因为这样的日子必多，所要来临的全是虚空。","notes":[]},{"n":9,"t":"年轻人哪，你在年少时当快乐；在年轻时使你的心欢畅，做你心所愿做的，看你眼所爱看的；却要知道，为这一切，神必审问你。","notes":[],"heads":["对年轻人的忠告"]},{"n":10,"t":"所以，当从心中除掉愁烦，从肉体除去痛苦；因为年少和年轻之时，全是虚空。","notes":[]}]},"12":{"heading":"结论","verses":[{"n":1,"t":"你趁着年轻、衰老的日子尚未来到，就是你所说，我毫无喜悦的那些岁月来临之前，当记念造你的主。","notes":[]},{"n":2,"t":"不要等到太阳、光明、月亮、星宿变为黑暗，雨后云又返回；","notes":[]},{"n":3,"t":"看守房屋的发颤，强壮的屈身，推磨的妇女因人少而停工，从窗户往外看的眼光变为昏暗；","notes":[]},{"n":4,"t":"街门关闭，推磨的声音微小，鸟一叫，就惊醒，唱歌女子的声音也都微弱；","notes":[]},{"n":5,"t":"人怕高处，路上有惊慌；杏树开花，蚱蜢成为重担，欲望不再挑起；因为人归他永远的家，吊丧的在街上往来。","notes":[]},{"n":6,"t":"不要等到银链折断，金罐破裂，瓶子在泉旁损坏，水轮在井口断裂，","notes":["“折断”：原文另译“取下”。"]},{"n":7,"t":"尘土仍归于地，像原来一样，气息仍归于赐气息的神。","notes":[]},{"n":8,"t":"传道者说：“虚空的虚空，全是虚空。”","notes":[]},{"n":9,"t":"再者，传道者因有智慧，将知识教导众人；他思量，考察，并列举出许多箴言。","notes":[]},{"n":10,"t":"传道者专心寻求可喜悦的言语，是凭正直写的诚实话。","notes":[]},{"n":11,"t":"智慧人的话语如同刺棒；这些嘉言好像钉稳的钉子，都是一个牧者所赐的。","notes":[]},{"n":12,"t":"我儿，还有一点，你当受劝戒：著书多，没有穷尽；读书多，身体疲倦。","notes":[]},{"n":13,"t":"这些事都已听见了，结论就是：敬畏神，谨守他的诫命，这是人当尽的本分。","notes":[]},{"n":14,"t":"因为人所做的事，连一切隐藏的事，无论是善是恶，神都必审问。","notes":[]}]}},"SNG":{"1":{"heading":"第一首","verses":[{"n":1,"t":"所罗门的雅歌。","notes":["“雅歌”：原文直译“歌中之歌”。"]},{"n":2,"t":"愿他用口与我亲吻。你的爱情比酒更美，","notes":[]},{"n":3,"t":"你的膏油馨香，你的名如倾泻而出的香膏，所以童女都爱你。","notes":[]},{"n":4,"t":"愿你吸引我跟随你；让我们快跑吧！王领我进入他的内室。我们必因你欢喜快乐，我们要思念你的爱情，胜似思念美酒。她们爱你是理所当然的。","notes":[]},{"n":5,"t":"耶路撒冷的女子啊，我虽然黑，却是秀美，如同基达的帐棚，好像所罗门的幔子，","notes":[]},{"n":6,"t":"不要因太阳把我晒黑了就瞪着我。我母亲的儿子向我发怒，他们使我看守葡萄园；我自己的葡萄园我却没有看守。","notes":[]},{"n":7,"t":"我心所爱的啊，请告诉我，你在何处牧羊？正午在何处使羊歇卧？我何必像蒙着脸的女子在你同伴的羊群旁边呢？","notes":[]},{"n":8,"t":"你这女子中最美丽的，你若不知道，只管跟随羊群的脚踪行，在牧人的帐棚边，牧放你的小山羊。","notes":[]},{"n":9,"t":"我的佳偶，你好比法老战车上的骏马。","notes":[]},{"n":10,"t":"你的两颊因发辫而秀美，你的颈项因珠串而华丽。","notes":[]},{"n":11,"t":"我们要为你编上金链，镶上银饰。","notes":[]},{"n":12,"t":"王正坐席的时候，我的哪哒香膏散发香气。","notes":[]},{"n":13,"t":"我的良人好像一袋没药，在我胸怀中。","notes":[]},{"n":14,"t":"我的良人好像一束凤仙花，在隐．基底的葡萄园中。","notes":[]},{"n":15,"t":"看哪，我的佳偶，你真美丽！看哪，你真美丽！你的眼睛是鸽子。","notes":[]},{"n":16,"t":"看哪，我的良人，你多英俊可爱！让我们以青草为床榻，","notes":[]},{"n":17,"t":"以香柏树为房子的栋梁，以松树作屋顶的椽木。","notes":[]}]},"2":{"heading":"第二首","verses":[{"n":1,"t":"我是沙仑的玫瑰花，是谷中的百合花。","notes":[]},{"n":2,"t":"我的佳偶在女子中，好像荆棘里的百合花。","notes":[]},{"n":3,"t":"我的良人在男子中，如同苹果树在树林里。我欢欢喜喜坐在他的荫下，尝他果子的滋味，觉得甘甜。","notes":[]},{"n":4,"t":"他领我进入宴会厅，为我插上爱的旗帜。","notes":[]},{"n":5,"t":"请你们用葡萄饼增补我力，以苹果畅快我的心，因我为爱而生病。","notes":[]},{"n":6,"t":"他的左手在我头下，他的右手将我环抱。","notes":[]},{"n":7,"t":"耶路撒冷的女子啊，我指着羚羊或田野的母鹿嘱咐你们，不要唤醒，不要挑动爱情，等它自发。","notes":[]},{"n":8,"t":"听啊！我良人的声音，看哪！他穿山越岭而来。","notes":[]},{"n":9,"t":"我的良人像羚羊，像小鹿。看哪，他站在我们的墙壁边，从窗户往里观看，从窗格子往里窥探。","notes":[]},{"n":10,"t":"我的良人对我说：“我的佳偶，起来！我的美人，与我同去！","notes":[]},{"n":11,"t":"看哪，因为冬天已逝，雨水止住，已经过去了。","notes":[]},{"n":12,"t":"地上百花开放，歌唱的时候到了，斑鸠的声音在我们境内也听见了。","notes":[]},{"n":13,"t":"无花果树的果子渐渐成熟，葡萄树开花，散发香气。我的佳偶，起来！我的美人，与我同去！","notes":[]},{"n":14,"t":"我的鸽子啊，你在磐石穴中，在陡岩的隐密处。求你容我得见你的面貌，求你容我得听你的声音；因你的声音悦耳，你的容貌秀美。","notes":[]},{"n":15,"t":"请为我们擒拿狐狸，就是毁坏葡萄园的小狐狸，我们的葡萄正在开花。”","notes":[]},{"n":16,"t":"我的良人属我，我也属他，他在百合花中放牧。","notes":[]},{"n":17,"t":"我的良人哪，等到天起凉风、日影飞去的时候，愿你归回，像羚羊，像小鹿，在崎岖的山上。","notes":["“崎岖的山”或音译“比特山”。"]}]},"3":{"heading":"第三首","verses":[{"n":1,"t":"我夜间躺卧在床上，寻找我心所爱的；我寻找他，却寻不着。","notes":[]},{"n":2,"t":"“我要起来，绕行城中，在街市上，在广场上，寻找我心所爱的。”我寻找他，却寻不着。","notes":[]},{"n":3,"t":"城中巡逻的守卫遇见我，“你们看见我心所爱的没有？”","notes":[]},{"n":4,"t":"我刚离开他们，就遇见我心所爱的。我拉住他，不放他走，领他进入我母亲的家，到怀我者的内室。","notes":[]},{"n":5,"t":"耶路撒冷的女子啊，我指着羚羊或田野的母鹿嘱咐你们，不要唤醒，不要挑动爱情，等它自发。","notes":[]},{"n":6,"t":"那如烟柱从旷野上来，薰了没药、乳香，扑上商人各样香粉的是谁呢？","notes":[]},{"n":7,"t":"看哪，是所罗门的轿，周围有六十个勇士，都是以色列中的勇士。","notes":[]},{"n":8,"t":"他们的手都持刀，善于争战，各人腰间佩刀，防备夜间恐怖的攻击。","notes":[]},{"n":9,"t":"所罗门王用黎巴嫩木为自己制作轿子。","notes":[]},{"n":10,"t":"轿柱是用银做的，轿底是用金做的，坐垫是紫色的，其中所铺的是耶路撒冷女子的爱情。","notes":[]},{"n":11,"t":"锡安的女子啊，你们要出去观看所罗门王！他头戴冠冕，就是在他结婚当天心中喜乐的时候，他母亲给他戴上的。","notes":[]}]},"4":{"heading":"","verses":[{"n":1,"t":"看哪，我的佳偶，你真美丽！看哪，你真美丽！你的眼睛在面纱后好像鸽子。你的头发如同一群山羊，从基列山下来。","notes":[]},{"n":2,"t":"你的牙齿如新剪毛的一群母羊，洗净之后走上来，它们成对，没有一颗是单独的。","notes":[]},{"n":3,"t":"你的唇好像一条朱红线，你的嘴秀美。你的鬓角在面纱后，如同迸开的石榴。","notes":[]},{"n":4,"t":"你的颈项犹如大卫为收藏军器而造的高塔，其上悬挂一千个盾牌，都是勇士的盾牌。","notes":[]},{"n":5,"t":"你的两乳好像百合花中吃草的一对小鹿，是母鹿双生的。","notes":[]},{"n":6,"t":"我要往没药山和乳香冈去，直到天起凉风、日影飞去的时候。","notes":[]},{"n":7,"t":"我的佳偶，你全然美丽，毫无瑕疵！","notes":[]},{"n":8,"t":"我的新娘，请你与我一同离开黎巴嫩，与我一同离开黎巴嫩。从亚玛拿山巅，从示尼珥，就是黑门山顶，从狮子的洞，从豹子的山往下观看。","notes":["“请你与我…与我一同离开黎巴嫩”：七十士译本是“从黎巴嫩下来，从黎巴嫩下来”。"]},{"n":9,"t":"我的妹子，我的新娘，你夺了我的心。你明眸一瞥，你颈项的链子，夺了我的心！","notes":[]},{"n":10,"t":"我的妹子，我的新娘，你的爱情何其美！你的爱情比酒甜美！你膏油的馨香胜过一切香料！","notes":["“爱情”：七十士译本是“胸怀”；下同。"]},{"n":11,"t":"我的新娘，你的唇滴下蜂蜜，你的舌下有蜜，有奶。你衣服的香气宛如黎巴嫩的芬芳。","notes":[]},{"n":12,"t":"我的妹子，我的新娘是上锁的园子，是禁闭的园子，是封闭的泉源。","notes":["“园子”是根据一些古卷和七十士译本；原文是“井”。"]},{"n":13,"t":"你园内所种的结了石榴，有佳美的果子，并凤仙花与哪哒树。","notes":[]},{"n":14,"t":"有哪哒和番红花，香菖蒲和桂树，并各样乳香木、没药、沉香，与一切上等的香料。","notes":[]},{"n":15,"t":"你是园中的泉，活水的井，是从黎巴嫩涌流而下的溪水。","notes":[]},{"n":16,"t":"北风啊，兴起！南风啊，吹来！吹在我的园内，使其中的香气散发出来。愿我的良人进入自己园里，吃他佳美的果子。","notes":[]}]},"5":{"heading":"第四首","verses":[{"n":1,"t":"我的妹子，我的新娘，我进入我的园中，采了我的没药和香料，吃了我的蜂房和蜂蜜，喝了我的酒和奶。我的朋友，请吃！我亲爱的，请喝，多多地喝！","notes":[]},{"n":2,"t":"我身躺卧，我心却醒。这是我良人的声音；他敲门：“我的妹子，我的佳偶，我的鸽子，我完美的人儿，请你为我开门；因我的头沾满露水，我的发被夜露滴湿。”","notes":[]},{"n":3,"t":"我脱了衣裳，怎能再穿上呢？我洗了脚，怎可再弄脏呢？","notes":[]},{"n":4,"t":"我的良人从门缝里伸进他的手，我便因他动了心。","notes":[]},{"n":5,"t":"我起来，要为我的良人开门。我的两手滴下没药，我的指头有没药汁滴在门闩上。","notes":[]},{"n":6,"t":"我为我的良人开了门，我的良人却已转身走了。他说话的时候，我魂不守舍。我寻找他，竟寻不着，我呼叫他，他却不回答。","notes":[]},{"n":7,"t":"城中巡逻的守卫遇见我，打了我，伤了我，看守城墙的人夺去我的披肩。","notes":[]},{"n":8,"t":"耶路撒冷的女子啊，我嘱咐你们：若遇见我的良人，要告诉他，我为爱而生病。","notes":[]},{"n":9,"t":"你这女子中最美丽的，你的良人有什么胜过别的良人呢？你的良人有什么胜过别的良人，使你这样嘱咐我们？","notes":[]},{"n":10,"t":"我的良人红润发亮，超乎万人之上。","notes":[]},{"n":11,"t":"他的头像千足的纯金，他的发绺卷曲，黑如乌鸦。","notes":[]},{"n":12,"t":"他的眼如溪水旁的鸽子，沐浴在奶中，安得合式。","notes":["“安得合式”或译“坐在溪水边”。"]},{"n":13,"t":"他的两颊如香花园，如香草台；他的嘴唇像百合花，滴下没药汁。","notes":["“如香草台”：七十士译本是“散发香味”。"]},{"n":14,"t":"他的双手宛如金条，镶嵌水苍玉；他的身体如同雕刻的象牙，周围镶嵌蓝宝石。","notes":[]},{"n":15,"t":"他的腿好比白玉石柱，安在精金座上；他的容貌如黎巴嫩，佳美如香柏树。","notes":[]},{"n":16,"t":"他的口甘甜，他全然可爱。耶路撒冷的女子啊，这是我的良人，这是我的朋友。","notes":[]}]},"6":{"heading":"第五首","verses":[{"n":1,"t":"你这女子中最美丽的，你的良人往何处去？你的良人转向何处去了？我们好与你同去寻找他。","notes":[]},{"n":2,"t":"我的良人进入自己园中，到香花园，在园内放牧，采百合花。","notes":[]},{"n":3,"t":"我属我的良人，我的良人属我；他在百合花中放牧。","notes":[]},{"n":4,"t":"我的佳偶啊，你美丽如得撒，秀美如耶路撒冷，威武如展开旌旗的军队。","notes":[]},{"n":5,"t":"求你转眼不要看我，因你的眼睛使我慌乱。你的头发如同一群山羊，从基列山下来。","notes":[]},{"n":6,"t":"你的牙齿如一群母羊，洗净之后走上来，它们成对，没有一颗是单独的。","notes":[]},{"n":7,"t":"你的鬓角在面纱后，如同迸开的石榴。","notes":[]},{"n":8,"t":"虽有六十王后、八十妃嫔，并有无数的童女。","notes":[]},{"n":9,"t":"她是我独一的鸽子、我完美的人儿，是她母亲独生的，是生养她的所宠爱的。女子见了都称她有福，王后妃嫔见了也赞美她。","notes":[]},{"n":10,"t":"那俯视如晨曦、美丽如月亮、皎洁如太阳、威武如展开旌旗军队的是谁呢？","notes":[]},{"n":11,"t":"我下到坚果园，要看谷中青翠的植物，要看葡萄可曾发芽，石榴可曾放蕊；","notes":[]},{"n":12,"t":"不知不觉，我仿佛坐在我百姓高官的战车中。","notes":["“我百姓高官”或音译“亚米．拿达”。"]},{"n":13,"t":"回来，回来，书拉密的女子；回来，回来，我们要看你。你们为何要观看书拉密的女子，像观看两队人马在跳舞呢？","notes":["“两队人马在跳舞”或译“玛哈念跳舞的”。"]}]},"7":{"heading":"","verses":[{"n":1,"t":"尊贵的女子啊，你的脚在鞋中何等秀美！你的大腿圆润，好像美玉，是巧匠的手做成的。","notes":[]},{"n":2,"t":"你的肚脐如圆杯，不缺调和的酒。你的肚子如一堆麦子，周围有百合花。","notes":[]},{"n":3,"t":"你的两乳好像一对小鹿，是母鹿双生的。","notes":[]},{"n":4,"t":"你的颈项如象牙塔，你的眼睛像希实本、巴特．拉并门旁的水池，你的鼻子仿佛朝向大马士革的黎巴嫩塔。","notes":[]},{"n":5,"t":"你的头在你身上好像迦密山 ，你头上的发呈紫色，王被这发绺系住了。","notes":[]},{"n":6,"t":"我亲爱的，喜乐的女子啊，你何等美丽！何等令人喜悦！","notes":["“喜乐的女子啊”是根据一些古译本；原文是“在喜乐中”。"]},{"n":7,"t":"你的身材好像棕树，你的两乳如同累累的果实。","notes":[]},{"n":8,"t":"我说：我要爬上棕树，抓住枝子。愿你的两乳好像葡萄累累，愿你鼻子的香气如苹果；","notes":[]},{"n":9,"t":"你的上颚如美酒，直流入我良人的口里，流入沉睡者的口中。","notes":["“流入沉睡者的口中”：七十士译本是“流在我的唇齿之间”。"]},{"n":10,"t":"我属我的良人，他也恋慕我。","notes":[]},{"n":11,"t":"来吧！我的良人，让我们往田间去，在村庄住宿。","notes":[]},{"n":12,"t":"早晨让我们起来往葡萄园去，看葡萄树发芽没有，花开了没有，石榴放蕊没有，在那里我要将我的爱情给你。","notes":[]},{"n":13,"t":"曼陀罗草散发香味，在我们的门内有各样新陈佳美的果子；我的良人，这都是我为你保存的。","notes":["“曼陀罗草”或译“爱情花”。"]}]},"8":{"heading":"第六首","verses":[{"n":1,"t":"惟愿你像我的兄弟，像吃我母亲奶的兄弟。我在外头遇见你就与你亲吻，谁也不轻看我。","notes":[]},{"n":2,"t":"我必引导你，领你进入我母亲的家，她必教导我，我必使你喝石榴汁酿的香酒。","notes":[]},{"n":3,"t":"他的左手在我头下，他的右手将我环抱。","notes":[]},{"n":4,"t":"耶路撒冷的女子啊，我嘱咐你们，不要唤醒、不要挑动爱情，等它自发。","notes":[]},{"n":5,"t":"那靠着良人从旷野上来的是谁呢？在苹果树下，我叫醒了你；在那里，你母亲曾为了生你而阵痛，在那里，生你的为你阵痛。","notes":[]},{"n":6,"t":"求你将我放在你心上如印记，带在你臂上如戳记。因为爱情如死之坚强，热恋如阴间之牢固，所发的光是火焰的光，是极其猛烈的火焰。","notes":["“极其猛烈的火焰”或译“耶和华的烈焰”。"]},{"n":7,"t":"爱情，众水不能熄灭，江河也不能淹没。若有人拿家中所有的财宝要换爱情，就全被藐视。","notes":[]},{"n":8,"t":"我们有一小妹，她还没有乳房，人来提亲的日子，我们当为她怎么办呢？","notes":[]},{"n":9,"t":"她若是墙，我们要在其上建造银塔；她若是门，我们要用香柏木板围护她。","notes":[]},{"n":10,"t":"我是墙，我的两乳像塔。那时，我在他眼中是找到平安的人。","notes":[]},{"n":11,"t":"所罗门在巴力．哈们有一葡萄园，他将这葡萄园租给看守的人，每人为其中的果子要交一千银子。","notes":[]},{"n":12,"t":"我有属自己的葡萄园。所罗门哪，一千归你，两百归看守果子的人。","notes":[]},{"n":13,"t":"你这住在园中的，同伴都要听你的声音，求你使我也得以听见。","notes":[]},{"n":14,"t":"我的良人哪，求你快来！像羚羊，像小鹿，在香草山上。","notes":[]}]}},"ISA":{"1":{"heading":"神责备以色列","verses":[{"n":1,"t":"当乌西雅、约坦、亚哈斯、希西家作犹大王的时候，亚摩斯的儿子以赛亚见异象，论到犹大和耶路撒冷。","notes":[]},{"n":2,"t":"天哪，要听！地啊，侧耳而听！因为耶和华说：“我养育儿女，将他们养大，他们竟悖逆我。","notes":[]},{"n":3,"t":"牛认识主人，驴认识主人的槽；以色列却不认识，我的民却不明白。”","notes":[]},{"n":4,"t":"祸哉！犯罪的国民，担着罪孽的百姓，行恶的族类，败坏的儿女！他们离弃耶和华，藐视以色列的圣者，背向他，与他疏远。","notes":[]},{"n":5,"t":"你们为什么屡次悖逆，继续受责打呢？你们已经满头疼痛，全心发昏；","notes":[]},{"n":6,"t":"从脚掌到头顶，没有一处是完好的，尽是创伤、瘀青，与流血的伤口，未曾挤净，未曾包扎，也没有用膏滋润。","notes":[]},{"n":7,"t":"你们的土地荒芜，城镇被火烧毁；你们的田地在你们眼前被陌生人侵吞，既被陌生人倾覆，就成为荒芜。","notes":["“既被...荒芜”或译“成为荒芜，如同陌生人曾被倾覆一样”。"]},{"n":8,"t":"仅存的锡安，好似葡萄园的草棚，如瓜田中的茅屋，又如被围困的城。","notes":["“锡安”：原文直译“锡安女子”。"]},{"n":9,"t":"若不是万军之耶和华为我们留下一些幸存者，我们早已变成所多玛，像蛾摩拉一样了。","notes":[]},{"n":10,"t":"所多玛的官长啊，你们要听耶和华的言语！蛾摩拉的百姓啊，要侧耳听我们神的教诲！","notes":[]},{"n":11,"t":"耶和华说：“你们许多的祭物于我何益呢？公绵羊的燔祭和肥畜的油脂，我已经腻烦了；公牛、羔羊、公山羊的血，我都不喜悦。","notes":[]},{"n":12,"t":"“你们来朝见我，谁向你们的手要求这些，使你们践踏我的院宇呢？","notes":[]},{"n":13,"t":"不要再献无谓的供物了，香是我所憎恶的。我不能容忍行恶又守严肃会：初一、安息日和召集的大会。","notes":[]},{"n":14,"t":"你们的初一和节期，我心里恨恶，它们成了我的重担，担当这些，令我厌烦。","notes":[]},{"n":15,"t":"你们举手祷告，我必遮眼不看，就算你们多多祈祷，我也不听；你们的手沾满了血。","notes":[]},{"n":16,"t":"你们要洗涤、自洁，从我眼前除掉恶行；要停止作恶，","notes":[]},{"n":17,"t":"学习行善，寻求公平，帮助受欺压的，替孤儿伸冤，为寡妇辩护。”","notes":["“帮助受欺压的”或译“导正欺压者”。"]},{"n":18,"t":"耶和华说：“来吧，我们彼此辩论。你们的罪虽像朱红，必变成雪白；虽红如丹颜，必白如羊毛。","notes":[]},{"n":19,"t":"你们若甘心听从，必吃地上的美物；","notes":[]},{"n":20,"t":"若不听从，反倒悖逆，必被刀剑吞灭；这是耶和华亲口说的。”","notes":[]},{"n":21,"t":"忠信的城竟然变为妓女！从前充满了公平，公义居在其中，现今却有凶手居住。","notes":[],"heads":["罪大恶极的城"]},{"n":22,"t":"你的银子变为渣滓，你的酒用水冲淡。","notes":[]},{"n":23,"t":"你的官长悖逆，与盗贼为伍，全都喜爱贿赂，追求赃物；他们不为孤儿伸冤，寡妇的案件也呈不到他们面前。","notes":[]},{"n":24,"t":"因此，主－万军之耶和华、以色列的大能者说：“唉！我要向我的对头雪恨，向我的敌人报仇。","notes":[]},{"n":25,"t":"我必反手对付你，如碱炼净你的渣滓，除尽你的杂质。","notes":[]},{"n":26,"t":"我必回复你的审判官，像起初一样，回复你的谋士，如起先一般。然后，你必称为公义之城，忠信之邑。”","notes":[]},{"n":27,"t":"锡安必因公平得蒙救赎，其中归正的人必因公义得蒙救赎。","notes":[]},{"n":28,"t":"但悖逆的和犯罪的必一同败亡，离弃耶和华的必致消灭。","notes":[]},{"n":29,"t":"那等人必因所喜爱的圣树抱愧；你们必因所选择的园子蒙羞，","notes":["“园子”是拜圣树的地方。"]},{"n":30,"t":"因为你们必如叶子枯干的橡树，如无水的园子。","notes":[]},{"n":31,"t":"有权势的必如麻线，他的作为好像火花，都要一同焚烧，无人扑灭。","notes":[]}]},"2":{"heading":"永恒的和平","verses":[{"n":1,"t":"亚摩斯的儿子以赛亚所见，有关犹大和耶路撒冷的事。","notes":[]},{"n":2,"t":"末后的日子，耶和华殿的山必坚立，超乎诸山，高举过于万岭；万国都要流归这山。","notes":[]},{"n":3,"t":"必有许多民族前往，说：“来吧，我们登耶和华的山，到雅各神的殿。他必将他的道教导我们，我们也要行他的路。”因为教诲必出于锡安，耶和华的言语必出于耶路撒冷。","notes":[]},{"n":4,"t":"他必在万国中施行审判，为许多民族断定是非。他们要将刀打成犁头，把枪打成镰刀；这国不举刀攻击那国，他们也不再学习战事。","notes":[]},{"n":5,"t":"雅各家啊，来吧！让我们在耶和华的光明中行走。","notes":[]},{"n":6,"t":"你离弃了你的百姓雅各家，因为他们充满了东方的习俗，又像非利士人一样观星象，并与外邦人击掌。","notes":["原文没有“习俗”。"],"heads":["骄者必败"]},{"n":7,"t":"他们的国满了金银，财宝也无穷；他们的地满了马匹，战车也无数。","notes":[]},{"n":8,"t":"他们的地满了偶像；他们跪拜自己手所造的，就是自己手指所做的。","notes":[]},{"n":9,"t":"有人屈膝，有人下跪；所以，不要饶恕他们。","notes":[]},{"n":10,"t":"当进入磐石，藏在土中，躲避耶和华的惊吓和他威严的荣光。","notes":[]},{"n":11,"t":"到那日，眼目高傲的必降卑，狂妄的人必屈膝；惟独耶和华被尊崇。","notes":[]},{"n":12,"t":"因万军之耶和华的一个日子要临到所有骄傲狂妄的，临到一切自高的，使他们降为卑；","notes":[]},{"n":13,"t":"临到黎巴嫩高大的香柏树、巴珊的橡树，","notes":[]},{"n":14,"t":"临到一切高山、一切峻岭，","notes":[]},{"n":15,"t":"临到一切碉堡、一切坚固的城墙，","notes":[]},{"n":16,"t":"临到他施一切的船只、一切华丽的船艇。","notes":[]},{"n":17,"t":"人的骄傲必屈膝，人的狂妄必降卑；在那日，惟独耶和华被尊崇，","notes":[]},{"n":18,"t":"偶像必全然废弃。","notes":[]},{"n":19,"t":"耶和华兴起使地大震动的时候，人就进入石洞和土穴里，躲避耶和华的惊吓和他威严的荣光。","notes":[]},{"n":20,"t":"到那日，人必将造来敬拜的金偶像、银偶像抛给田鼠和蝙蝠。","notes":[]},{"n":21,"t":"耶和华兴起使地大震动的时候，人就进入磐缝和岩隙里，躲避耶和华的惊吓和他威严的荣光。","notes":[]},{"n":22,"t":"你们不要倚靠世人，他只不过鼻孔里有气息，算得了什么呢？","notes":[]}]},"3":{"heading":"耶路撒冷的混乱","verses":[{"n":1,"t":"看哪，主－万军之耶和华要从耶路撒冷和犹大除掉众人所倚靠的，所仰赖的，就是所倚靠的粮，所仰赖的水；","notes":[]},{"n":2,"t":"除掉勇士和战士，审判官和先知，占卜的和长老，","notes":[]},{"n":3,"t":"除掉五十夫长和显要、谋士和巧匠，以及擅长法术的人。","notes":[]},{"n":4,"t":"我必使孩童作他们的领袖，幼儿管辖他们。","notes":[]},{"n":5,"t":"百姓要彼此欺压，各人欺压邻舍；青年要侮慢老人，卑贱的要侮慢尊贵的。","notes":[]},{"n":6,"t":"人在父家拉住自己的兄弟：“你有外衣，来作我们的官长，让这些败坏的事归于你的手下吧！”","notes":[]},{"n":7,"t":"那时，他必扬声说：“我不作医治你们的人；我家里没有粮食，也没有衣服，你们不可立我作百姓的官长。”","notes":[]},{"n":8,"t":"耶路撒冷败落，犹大倾倒；因为他们的舌头和行为与耶和华相悖，无视于他荣光的眼目。","notes":[]},{"n":9,"t":"他们的脸色证明自己不正，他们述说自己像所多玛一样的罪恶，毫不隐瞒。他们有祸了！因为作恶自害。","notes":[]},{"n":10,"t":"你们要对义人说，他是有福的，因为他必吃自己行为所结的果实。","notes":[]},{"n":11,"t":"恶人有祸了！他必遭灾难！因为他要按自己手所做的受报应。","notes":[]},{"n":12,"t":"至于我的百姓，统治者剥削你们，放高利贷的人管辖你们。我的百姓啊，引导你的使你走错，并毁坏你所行的道路。","notes":["“统治者...管辖你们”是根据七十士译本；原文是“孩童欺压他们，妇女管辖他们”。"]},{"n":13,"t":"耶和华兴起诉讼，站着审判万民。","notes":[],"heads":["耶和华审判他的子民"]},{"n":14,"t":"耶和华必审问他国中的长老和领袖：“你们，你们摧毁葡萄园，抢夺困苦人，囤积在你们家中。","notes":[]},{"n":15,"t":"你们为何压碎我的百姓，碾磨困苦人的脸呢？”这是万军之主耶和华说的。","notes":[]},{"n":16,"t":"耶和华说：因为锡安狂傲，行走挺项，卖弄眼目，俏步徐行，脚下玎珰，","notes":["“锡安”：原文直译“锡安女子”；17节同。"],"heads":["对耶路撒冷的警告"]},{"n":17,"t":"主必使锡安头顶长疮，耶和华又暴露其下体。","notes":[]},{"n":18,"t":"到那日，主必除掉华美的足饰、额带、月牙圈、","notes":[]},{"n":19,"t":"耳环、手镯、面纱、","notes":[]},{"n":20,"t":"头巾、足链、华带、香盒、符囊、","notes":[]},{"n":21,"t":"戒指、鼻环、","notes":[]},{"n":22,"t":"礼服、外套、披肩、皮包、","notes":[]},{"n":23,"t":"手镜、细麻衣、头饰、纱巾。","notes":[]},{"n":24,"t":"必有腐烂代替馨香，绳子代替腰带，光秃代替美发，麻衣系腰代替华服，烙痕代替美貌。","notes":[]},{"n":25,"t":"你的男丁必倒在刀下，你的勇士必死在阵上。","notes":[]},{"n":26,"t":"锡安的城门必悲伤、哀号；它必荒凉，坐在地上。","notes":[]}]},"4":{"heading":"耶路撒冷的重建","verses":[{"n":1,"t":"在那日，七个女人必拉住一个男人，说：“我们吃自己的食物，穿自己的衣服，但求你允许我们归你名下，除掉我们的羞耻。”","notes":[]},{"n":2,"t":"在那日，耶和华的苗必华美尊荣，地的出产必成为幸存的以色列民的骄傲和光荣。","notes":[]},{"n":3,"t":"主以公平的灵和焚烧的灵洗净锡安居民的污秽，又除净在耶路撒冷流人血的罪。那时，剩在锡安、留在耶路撒冷的，就是一切住耶路撒冷、在生命册上记名的，必称为圣。","notes":["“锡安居民”：原文是“锡安众女子”。"],"end":4},{"n":5,"t":"耶和华必在整座锡安山，在会众之上，白天造云，黑夜发出烟和火焰的光，因为在一切荣耀之上必有华盖；","notes":[]},{"n":6,"t":"这要作为棚子，白天可以遮荫避暑，暴风雨侵袭时，可作藏身处和避难所。","notes":[]}]},"5":{"heading":"葡萄园之歌","verses":[{"n":1,"t":"我要为我亲爱的唱歌，我所爱的、他的葡萄园之歌。我亲爱的有葡萄园在肥沃的山冈上。","notes":[]},{"n":2,"t":"他刨挖园子，清除石头，栽种上等的葡萄树，在园中盖了一座楼，又凿出酒池；指望它结葡萄，反倒结了野葡萄。","notes":[]},{"n":3,"t":"耶路撒冷的居民和犹大人哪，现在，请你们在我与我的葡萄园之间断定是非。","notes":[]},{"n":4,"t":"我为我葡萄园所做的之外，还有什么可做的呢？我指望它结葡萄，怎么倒结了野葡萄呢？","notes":[]},{"n":5,"t":"现在我告诉你们，我要向我的葡萄园怎么做。我必撤去篱笆，使它被烧毁；拆毁围墙，使它被践踏。","notes":[]},{"n":6,"t":"我必使它荒废，不再修剪，不再锄草，任荆棘蒺藜生长；我也必吩咐密云，不再降雨在其上。","notes":[]},{"n":7,"t":"万军之耶和华的葡萄园就是以色列家；他所喜爱的树就是犹大人。他指望公平，看哪，却有流血；指望公义，看哪，却有冤声。","notes":[]},{"n":8,"t":"祸哉！你们以房接房，以地连地，以致不留余地，只顾自己独居境内。","notes":[],"heads":["人的恶行"]},{"n":9,"t":"我耳闻万军之耶和华说：“许多房屋必然荒废；宏伟华丽，无人居住。","notes":[]},{"n":10,"t":"十亩的葡萄园只酿出一罢特的酒，一贺梅珥的谷种只结一伊法粮食。”","notes":["“亩”：古希伯来面积单位；参“度量衡表”。"]},{"n":11,"t":"祸哉！那些清晨早起，追寻烈酒，因酒狂热，流连到深夜的人，","notes":[]},{"n":12,"t":"他们在宴席上弹琴，鼓瑟，击鼓，吹笛，饮酒，却不留意耶和华的作为，也不留心他手所做的。","notes":[]},{"n":13,"t":"所以，我的百姓因无知就被掳去；尊贵的人甚是饥饿，平民也极其干渴。","notes":[]},{"n":14,"t":"因此，阴间胃口大开，张开无限量的口；令耶路撒冷的贵族与平民、狂欢的与作乐的人都掉落其中。","notes":["“胃口”或译“喉咙”。"]},{"n":15,"t":"人为之屈膝，人就降为卑；高傲的眼目也降为卑。","notes":[]},{"n":16,"t":"惟有万军之耶和华因公平显为崇高，神圣的神因公义显为圣。","notes":[]},{"n":17,"t":"羔羊必来吃草，如同在自己的草场；在富有人的废墟，流浪的牲畜也来吃。","notes":["“在富有人...来吃”或译“丰肥人的荒场被流浪的人吃尽”。"]},{"n":18,"t":"祸哉！那些以虚假的绳子牵引罪孽，以套车的绳索紧拉罪恶的人。","notes":[]},{"n":19,"t":"他们说：“任以色列的圣者急速前行，快快成就他的作为，好让我们看看；任他的筹算临近成就，好使我们知道。”","notes":[]},{"n":20,"t":"祸哉！那些称恶为善，称善为恶，以暗为光，以光为暗，以苦为甜，以甜为苦的人。","notes":[]},{"n":21,"t":"祸哉！那些在自己眼中有智慧，在自己面前有通达的人。","notes":[]},{"n":22,"t":"祸哉！那些以饮酒称雄，以调烈酒称霸的人。","notes":[]},{"n":23,"t":"他们因受贿赂，就称恶人为义，将义人的义夺去。","notes":[]},{"n":24,"t":"火苗怎样吞灭碎秸，干草怎样落在火焰之中，照样，他们的根必然腐朽，他们的花像灰尘扬起；因为他们厌弃万军之耶和华的教诲，藐视以色列圣者的言语。","notes":[]},{"n":25,"t":"因此，耶和华的怒气向他的百姓发作。他伸手攻击他们，山岭就震动；他们的尸首在街市上好像粪土。虽然如此，他的怒气并未转消，他的手依然伸出。","notes":[]},{"n":26,"t":"他必竖立大旗，召集远方的国民，把他们从地极叫来。看哪，他们必急速奔来，","notes":[]},{"n":27,"t":"其中没有疲倦的，绊跌的；没有打盹的，睡觉的；腰带并不放松，鞋带也不拉断。","notes":[]},{"n":28,"t":"他们的箭锐利，弓也上了弦；马蹄如坚石，车轮像旋风。","notes":[]},{"n":29,"t":"他们要吼叫，像母狮，咆哮，像少壮狮子；他们要咆哮，抓取猎物，稳稳叼走，无人能救回。","notes":[]},{"n":30,"t":"那日，他们要向以色列人咆哮，像海浪澎湃；人若望地，看哪，只有黑暗与祸患，光明因密云而变黑暗。","notes":[]}]},"6":{"heading":"主呼召以赛亚作先知","verses":[{"n":1,"t":"当乌西雅王崩的那年，我看见主坐在高高的宝座上。他的衣裳下摆遮满圣殿。","notes":[]},{"n":2,"t":"上有撒拉弗侍立，各有六个翅膀：两个翅膀遮脸，两个翅膀遮脚，两个翅膀飞翔，","notes":[]},{"n":3,"t":"彼此呼喊说：“圣哉！圣哉！圣哉！万军之耶和华；他的荣光遍满全地！”","notes":[]},{"n":4,"t":"因呼喊者的声音，门槛的根基震动，殿里充满了烟云。","notes":[]},{"n":5,"t":"那时我说：“祸哉！我灭亡了！因为我是嘴唇不洁的人，住在嘴唇不洁的民中，又因我亲眼看见大君王－万军之耶和华。”","notes":[]},{"n":6,"t":"有一撒拉弗向我飞来，手里拿着烧红的炭，是用火钳从坛上取下来的，","notes":[]},{"n":7,"t":"用炭沾我的口，说：“看哪，这炭沾了你的嘴唇，你的罪孽便除掉，你的罪恶就赦免了。”","notes":[]},{"n":8,"t":"我听见主的声音说：“我可以差遣谁呢？谁肯为我们去呢？”我说：“我在这里，请差遣我！”","notes":[]},{"n":9,"t":"他说：“你去告诉这百姓说：‘你们听了又听，却不明白；看了又看，却不晓得。’","notes":[]},{"n":10,"t":"要使这百姓心蒙油脂，耳朵发沉，眼睛昏花；恐怕他们眼睛看见，耳朵听见，心里明白，回转过来，就得医治。”","notes":[]},{"n":11,"t":"我就说：“主啊，这到几时为止呢？”他说：“直到城镇荒凉，无人居住，房屋空无一人，土地极其荒芜；","notes":[]},{"n":12,"t":"耶和华将人迁到远方，国内被撇弃的土地很多。","notes":[]},{"n":13,"t":"国内剩下的人若还有十分之一，也必被吞灭。然而如同大树与橡树，虽被砍伐，残干却仍存留，圣洁的苗裔是它的残干。”","notes":[]}]},"7":{"heading":"传给亚哈斯王的信息","verses":[{"n":1,"t":"乌西雅的孙子，约坦的儿子，犹大王亚哈斯在位的时候，亚兰王利汛和利玛利的儿子以色列王比加上来攻打耶路撒冷，却不能攻取。","notes":[]},{"n":2,"t":"有人告诉大卫家说：“亚兰与以法莲已经结盟。”王的心和百姓的心就都颤动，好像林中的树被风吹动一样。","notes":[]},{"n":3,"t":"耶和华对以赛亚说：“你和你的儿子施亚．雅述要出去，到上池的水沟尽头，往漂布地的大路上，迎见亚哈斯，","notes":["“施亚．雅述”意思是“余民要归回”。"]},{"n":4,"t":"对他说：‘你要谨慎，要镇定，不要害怕，不要因利汛和亚兰，以及利玛利的儿子这两个冒烟火把的头所发的烈怒而心里胆怯。","notes":[]},{"n":5,"t":"因为亚兰、以法莲，和利玛利的儿子设恶谋要害你，说：","notes":[]},{"n":6,"t":"我们要上去攻击犹大，扰乱它，攻破它来归我们，在其中立他比勒的儿子为王。","notes":[]},{"n":7,"t":"主耶和华如此说：这事必站立不住，也不得成就。","notes":[]},{"n":8,"t":"因为亚兰的首都是大马士革，大马士革的领袖是利汛；六十五年之内，以法莲必然国破族亡，","notes":[]},{"n":9,"t":"以法莲的首都是撒玛利亚；撒玛利亚的领袖是利玛利的儿子。你们若是不信，必站立不稳。’”","notes":[]},{"n":10,"t":"耶和华又吩咐亚哈斯：","notes":[],"heads":["以马内利的记号"]},{"n":11,"t":"“你向耶和华－你的神求一个预兆：在阴间的深渊，或往上的高处。”","notes":[]},{"n":12,"t":"但亚哈斯说：“我不求；我不试探耶和华。”","notes":[]},{"n":13,"t":"以赛亚说：“听啊，大卫家！你们使人厌烦岂算小事，还要使我的神厌烦吗？","notes":[]},{"n":14,"t":"因此，主自己要给你们一个预兆，看哪，必有童女怀孕生子，给他起名叫以马内利。","notes":["“以马内利”意思是“神与我们同在”。"]},{"n":15,"t":"到他晓得弃恶择善的时候，他必吃乳酪与蜂蜜。","notes":[]},{"n":16,"t":"因为在这孩子还不晓得弃恶择善之先，你所憎恶的那两个王的土地必被撇弃。","notes":[]},{"n":17,"t":"耶和华必使亚述王临到你和你的百姓，并你的父家，自从以法莲脱离犹大的时候，未曾有过这样的日子。","notes":[]},{"n":18,"t":"“那时，耶和华要呼叫，召来埃及江河源头的苍蝇和亚述地的蜂；","notes":[]},{"n":19,"t":"它们都必飞来，停在陡峭的谷中、岩石缝里、一切荆棘丛中和片片草场上。","notes":[]},{"n":20,"t":"“那时，主必用大河外雇来的剃头刀，就是亚述王，剃去你的头发和脚毛，并要剃净你的胡须。","notes":[]},{"n":21,"t":"“那时，每一个人要养活一头母牛犊和两只母羊；","notes":[]},{"n":22,"t":"因为奶量充足，他就有乳酪可吃，国内剩余的人也都能吃乳酪与蜂蜜。","notes":[]},{"n":23,"t":"“那时，凡种一千棵葡萄树、价值一千银子的地方，必长出荆棘和蒺藜。","notes":[]},{"n":24,"t":"人到那里去，必带弓箭，因为遍地长满了荆棘和蒺藜。","notes":[]},{"n":25,"t":"所有锄头刨过的山地，你因惧怕荆棘和蒺藜，不敢到那里去；只能作放牛之处，羊群践踏之地。”","notes":[]}]},"8":{"heading":"用以赛亚的儿子作记号","verses":[{"n":1,"t":"耶和华对我说：“你取一块大板子，拿人的笔，写上‘玛黑珥．沙拉勒．哈施．罢斯’。","notes":["“拿人的笔”或译“用普通的字”。","“玛黑珥．沙拉勒．哈施．罢斯”意思是“掳掠速临、抢夺即将发生”。"]},{"n":2,"t":"我要用可靠的证人，乌利亚祭司和耶比利家的儿子撒迦利亚为我作证。”","notes":["“我”：有古卷和七十士译本是“你”。"]},{"n":3,"t":"我亲近女先知；她就怀孕生子，耶和华对我说：“给他起名叫玛黑珥．沙拉勒．哈施．罢斯；","notes":["“女先知”是以赛亚的妻子。"]},{"n":4,"t":"因为在这孩子还不晓得叫爸爸妈妈以前，大马士革的财宝和撒玛利亚的掳物必被亚述王掠夺一空。”","notes":[]},{"n":5,"t":"耶和华又吩咐我：","notes":[],"heads":["亚述王速临"]},{"n":6,"t":"“这百姓既厌弃西罗亚缓流的水，喜欢利汛以及利玛利的儿子，","notes":[]},{"n":7,"t":"因此，看哪，主必使亚述王和他的威势如大河翻腾汹涌的水上涨，盖过他们，必上涨超过一切水道，涨过两岸，","notes":[]},{"n":8,"t":"必冲入犹大，涨溢泛滥，直到颈项。他展开翅膀，遮蔽你的全地。以马内利啊！”","notes":[]},{"n":9,"t":"万民哪，任凭你们行恶，终必毁灭；远方的众人哪，当侧耳而听！任凭你们束腰，终必毁灭；你们束起腰来，终必毁灭。","notes":["“行恶”或译“崩溃”或“喧嚷”。"]},{"n":10,"t":"任凭你们筹算什么，终必无效；不管你们讲定什么，总不成立；因为神与我们同在。","notes":[]},{"n":11,"t":"耶和华以大能的手训诫我不可行这百姓所行的道，对我这样说：","notes":["“训诫我不可行”：死海古卷是“使我远离”。"],"heads":["耶和华警告先知"]},{"n":12,"t":"“这百姓说同谋背叛的，你们不要说同谋背叛。他们所怕的，你们不要怕，也不要畏惧；","notes":[]},{"n":13,"t":"但要尊万军之耶和华为圣，他才是你们所当怕的，所当畏惧的。","notes":[]},{"n":14,"t":"他必作为圣所，却向以色列的两家成为绊脚的石头，使人跌倒的磐石；作耶路撒冷居民的罗网和圈套。","notes":[]},{"n":15,"t":"许多人在其上绊倒，他们跌倒，甚至跌伤，并且落入陷阱，被抓住了。”","notes":[]},{"n":16,"t":"你要卷起律法书，在我门徒中间封住教诲。","notes":[],"heads":["不要求问死人"]},{"n":17,"t":"我要等候那转脸不顾雅各家的耶和华，也要仰望他。","notes":[]},{"n":18,"t":"看哪，我与耶和华所赐给我的儿女成了以色列的预兆和奇迹，这是从住在锡安山万军之耶和华来的。","notes":[]},{"n":19,"t":"有人对你们说：“当求问招魂的与行巫术的，他们唧唧喳喳，念念有词。”然而，百姓不当求问自己的神吗？岂可为活人求问死人呢？","notes":[]},{"n":20,"t":"当以教诲和律法书为准；人所说的若不与此相符，必没有黎明。","notes":[]},{"n":21,"t":"他必经过这地，遇艰难，受饥饿；饥饿的时候，心中焦躁，咒骂自己的君王和神。他仰观上天，","notes":[],"heads":["遭难的时候"]},{"n":22,"t":"俯察下地，看哪，尽是艰难、黑暗和骇人的昏暗。他必被赶入幽暗中去。","notes":[]}]},"9":{"heading":"未来的君王","verses":[{"n":1,"t":"但那受过痛苦的必不再见幽暗。从前神使西布伦地和拿弗他利地被藐视，末后却使这沿海的路，约旦河东，外邦人居住的加利利地得荣耀。","notes":[]},{"n":2,"t":"在黑暗中行走的百姓看见了大光；住在死荫之地的人有光照耀他们。","notes":[]},{"n":3,"t":"你使这国民众多，使他们喜乐大增；他们在你面前欢喜，好像收割时的欢喜，又像人分战利品那样的快乐。","notes":["“你使这国民众多”：原文另译“你增加他们的快乐”。"]},{"n":4,"t":"因为他们所负的重轭和肩头上的杖，并欺压者的棍，你都已经折断，如同在米甸的日子一般。","notes":[]},{"n":5,"t":"战士在战乱中所穿的靴子，以及那滚在血中的衣服，都必当作柴火燃烧。","notes":[]},{"n":6,"t":"因有一婴孩为我们而生；有一子赐给我们。政权必担在他的肩头上；他名称为“奇妙策士、全能的神、永在的父、和平的君”。","notes":[]},{"n":7,"t":"他的政权与平安必加增无穷。他必在大卫的宝座上治理他的国，以公平公义使国坚定稳固，从今直到永远。万军之耶和华的热心必成就这事。","notes":[]},{"n":8,"t":"主向雅各家发出言语，主的话临到以色列家。","notes":[],"heads":["耶和华要惩罚以色列"]},{"n":9,"t":"众百姓，就是以法莲和撒玛利亚的居民，都将知道；他们凭骄傲自大的心说：","notes":[]},{"n":10,"t":"“砖块掉落了，我们要凿石头重建；桑树砍了，我们要改种香柏树。”","notes":[]},{"n":11,"t":"因此，耶和华兴起利汛的敌人前来攻击以色列，要激起它的仇敌，","notes":["“利汛的敌人”：有些现代的译本译为“敌人”、“敌人利汛”或“他们的敌人利汛”。"]},{"n":12,"t":"东有亚兰人，西有非利士人；他们张口吞吃以色列。虽然如此，耶和华的怒气并未转消；他的手依然伸出。","notes":[]},{"n":13,"t":"这百姓还没有归向击打他们的主，也没有寻求万军之耶和华。","notes":[]},{"n":14,"t":"耶和华在一日之间从以色列中剪除了头与尾－棕树枝与芦苇－","notes":[]},{"n":15,"t":"长老和显要就是头，以谎言教人的先知就是尾。","notes":[]},{"n":16,"t":"因为引导这百姓的使他们走入迷途，被引导的都必被吞灭。","notes":[]},{"n":17,"t":"所以，主不喜爱他们的青年，也不怜悯他们的孤儿和寡妇；因为他们都是亵渎的，行恶的，并且各人的口都说愚妄的话。虽然如此，耶和华的怒气并未转消；他的手依然伸出。","notes":["“喜爱”有古卷是“喜悦”；死海古卷是“顾惜”。"]},{"n":18,"t":"邪恶如火焚烧，吞灭荆棘和蒺藜，在稠密的树林中点燃，成为烟柱，旋转上腾。","notes":[]},{"n":19,"t":"因万军之耶和华的烈怒，地都烧遍了；百姓成为柴火，无人怜惜弟兄。","notes":[]},{"n":20,"t":"有人右边抢夺，犹受饥饿；左边吞吃，仍不饱足，各人吃自己膀臂上的肉。","notes":[]},{"n":21,"t":"玛拿西吞吃以法莲，以法莲吞吃玛拿西，他们又一同攻击犹大。虽然如此，耶和华的怒气并未转消；他的手依然伸出。","notes":[]}]},"10":{"heading":"神用亚述王为工具","verses":[{"n":1,"t":"祸哉！那些设立不义之律例的，和记录奸诈之判词的，","notes":[]},{"n":2,"t":"为要扭曲贫寒人的案件，夺去我民中困苦人的理，以寡妇当作掳物，以孤儿当作掠物。","notes":[]},{"n":3,"t":"到降罚的日子，灾祸从远方临到，那时，你们要怎么办呢？你们要向谁逃奔求救呢？你们的财宝要存放何处呢？","notes":[]},{"n":4,"t":"他们只得屈身在被掳的人之下，仆倒在被杀的人中间。虽然如此，耶和华的怒气并未转消；他的手依然伸出。","notes":["“他们...中间”或译“那些不愿屈身被掳的人，将仆倒在被杀的人中间”。"]},{"n":5,"t":"祸哉！亚述，我怒气的棍！他们手中的杖是我的恼恨。","notes":[]},{"n":6,"t":"我要差遣他攻击亵渎的国，吩咐他对付我所恼怒的民，抢走掳物，夺取掠物，将他们践踏，如同街上的泥土一般。","notes":[]},{"n":7,"t":"然而，这并非他的意念，他的心不是这样打算；他的心要摧毁，要剪除不少的国家。","notes":[]},{"n":8,"t":"他说：“我的官长岂不都是君王吗？","notes":[]},{"n":9,"t":"迦勒挪岂不像迦基米施吗？哈马岂不像亚珥拔吗？撒玛利亚岂不像大马士革吗？","notes":[]},{"n":10,"t":"既然我的手已伸到了这些有偶像的国，他们所雕刻的偶像过于耶路撒冷和撒玛利亚的偶像，","notes":[]},{"n":11,"t":"我岂不照样待耶路撒冷和其中的偶像，如同我待撒玛利亚和其中的偶像吗？”","notes":[]},{"n":12,"t":"主在锡安山和耶路撒冷成就他一切工作的时候，说：“我必惩罚亚述王自大的心和他高傲尊贵的眼目。”","notes":[]},{"n":13,"t":"因为他说：“我所成就的事是靠我手的能力和我的智慧，因为我本有聪明。我挪移列国的地界，抢夺他们所积蓄的财宝，并且像勇士，使坐宝座的降为卑。","notes":[]},{"n":14,"t":"我的手夺取列国的财宝，好像人夺取鸟窝；我得了全地，好像人拾起被弃的鸟蛋；没有振动翅膀的，没有张嘴的，也没有鸣叫的。”","notes":[]},{"n":15,"t":"斧岂可向用斧砍伐的自夸呢？锯岂可向拉锯的自大呢？这好比棍挥动那举棍的，好比杖举起那不是木头的人。","notes":[]},{"n":16,"t":"因此，主－万军之耶和华必使亚述王的壮士变为瘦弱，在他的荣华之下必有火点燃，如同火在燃烧一般。","notes":[]},{"n":17,"t":"以色列的光必变成火，它的圣者必成为火焰；一日之间，将亚述王的荆棘和蒺藜焚烧净尽，","notes":[]},{"n":18,"t":"又毁灭树林和田园的荣华，连魂带体，好像病重的人消逝一样。","notes":["“病重的人消逝”或译“拿军旗的昏过去”。"]},{"n":19,"t":"他林中只剩下稀少的树木，连孩童也能写其数目。","notes":[]},{"n":20,"t":"到那日，以色列所剩下的和雅各家所逃脱的，必不再倚靠那击打他们的，却要诚心仰赖耶和华－以色列的圣者。","notes":[],"heads":["残存之民归回"]},{"n":21,"t":"所剩下的，就是雅各家的余民，必归回全能的神。","notes":[]},{"n":22,"t":"以色列啊，你的百姓虽多如海沙，惟有剩下的归回。灭绝之事已成定局，公义必如水涨溢。","notes":[]},{"n":23,"t":"因为万军之主耶和华在全地必成就所定的灭绝之事。","notes":[]},{"n":24,"t":"所以，万军之主耶和华如此说：“住锡安我的百姓啊，亚述王虽然用棍击打你，又如埃及举杖攻击你，你不要怕他。","notes":[],"heads":["耶和华要惩罚亚述"]},{"n":25,"t":"因为还有一点点时候，我向你们发的愤怒就要结束，我的怒气要使他们灭亡。","notes":[]},{"n":26,"t":"万军之耶和华要举起鞭子来攻击他，好像在俄立磐石那里击打米甸人一样。他的杖向海伸出，他必把杖举起，如在埃及一般。","notes":[]},{"n":27,"t":"到那日，亚述王的重担必离开你的肩头，他的轭必离开你的颈项；那轭必因肥壮而撑断。”","notes":["“他的轭...撑断”：七十士译本是“他的轭必折断离开你的颈项”。"]},{"n":28,"t":"亚述王来到亚叶，经过米矶仑，在密抹安放辎重。","notes":[],"heads":["侵略者进攻"]},{"n":29,"t":"他们过了隘口，要在迦巴住宿。拉玛战兢，扫罗的基比亚逃命。","notes":[]},{"n":30,"t":"迦琳哪，要高声呼喊！注意听，莱煞啊！困苦的亚拿突啊！","notes":["“迦琳”：原文直译“迦琳女子”。","“困苦的亚拿突啊”：原文另译“回应他，亚拿突啊”。"]},{"n":31,"t":"玛得米那躲避，基柄的居民逃遁。","notes":[]},{"n":32,"t":"当那日，亚述王要在挪伯停留，挥手攻击锡安的山，就是耶路撒冷的山。","notes":["“锡安”：原文直译“锡安女子”。"]},{"n":33,"t":"看哪，主－万军之耶和华以猛撞削断树枝；巨木必被砍下，高大的树必降为低。","notes":[]},{"n":34,"t":"稠密的树林，他要用铁器砍下，黎巴嫩必被大能者伐倒。","notes":["“黎巴嫩必被大能者伐倒”或译“黎巴嫩的荣华必倾倒”。"]}]},"11":{"heading":"和平的国度","verses":[{"n":1,"t":"从耶西的残干必长出嫩枝，他的根所抽的枝子必结果实。","notes":[]},{"n":2,"t":"耶和华的灵必住在他身上，就是智慧和聪明的灵，谋略和能力的灵，知识和敬畏耶和华的灵。","notes":[]},{"n":3,"t":"他必以敬畏耶和华为乐；行审判不凭眼见，断是非也不凭耳闻；","notes":[]},{"n":4,"t":"却要以公义审判贫寒人，以正直判断地上的困苦人，以口中的棍击打全地，以嘴里的气杀戮恶人。","notes":[]},{"n":5,"t":"公义必当他的腰带，信实必作他胁下的带子。","notes":[]},{"n":6,"t":"野狼必与小绵羊同住，豹子与小山羊同卧；少壮狮子、牛犊和肥畜同群；孩童要牵引它们。","notes":["“和肥畜同群”：死海古卷是“一起长大”。"]},{"n":7,"t":"牛必与熊同食，牛犊与小熊同卧；狮子与牛一样吃草。","notes":[]},{"n":8,"t":"吃奶的婴孩在虺蛇的洞口玩耍，断奶的幼儿必按手在毒蛇的穴上。","notes":[]},{"n":9,"t":"在我圣山各处，它们都不伤人，不害物；因为认识耶和华的知识要遍满全地，好像水充满海洋一般。","notes":[]},{"n":10,"t":"到那日，耶西的根立作万民的大旗；列国的人必寻求他，他安歇之所大有荣耀。","notes":[],"heads":["被掳的人归回"]},{"n":11,"t":"当那日，主必再度伸手救回自己百姓中所剩余的，就是在亚述、埃及、巴特罗、古实、以拦、示拿、哈马，并众海岛所剩下的。","notes":["“古实”包括苏丹的大部分和埃塞俄比亚的一部分。"]},{"n":12,"t":"他要向列国竖立大旗，召集以色列被赶散的人，又从地极四方聚集分散的犹大人。","notes":[]},{"n":13,"t":"以法莲的嫉妒必消散，苦待犹大的也被剪除；以法莲必不嫉妒犹大，犹大也不苦待以法莲。","notes":[]},{"n":14,"t":"他们要飞向西方，扑在非利士人的肩头上，他们要一同掳掠东方人，他们的手伸到以东和摩押；亚扪人也必顺服他们。","notes":[]},{"n":15,"t":"耶和华必使埃及的海湾全然毁坏，他举手在大河之上刮起了暴热的风，击打它，使它分成七条溪流，人穿鞋便可渡过。","notes":["“全然毁坏”：原文另译“枯干”；七十士译本是“荒芜”。"]},{"n":16,"t":"必有一条大道，为百姓中从亚述逃脱生还的余民而开，如当日为以色列从埃及上来一样。","notes":[]}]},"12":{"heading":"感恩的诗歌","verses":[{"n":1,"t":"在那日，你要说：“耶和华啊，我要称谢你！因为你虽然向我发怒，你的怒气却已转消；你又安慰了我。","notes":[]},{"n":2,"t":"“看哪！神是我的拯救；我要倚靠他，并不惧怕。因为主耶和华是我的力量，是我的诗歌，他也成了我的拯救。”","notes":[]},{"n":3,"t":"你们必从救恩的泉源欢然取水。","notes":[]},{"n":4,"t":"在那日，你们要说：“当称谢耶和华，求告他的名；在万民中传扬他的作为，宣告他的名已被尊崇。","notes":[]},{"n":5,"t":"“你们要向耶和华唱歌，因他所做的十分宏伟；但愿这事遍传全地。","notes":[]},{"n":6,"t":"锡安的居民哪，当扬声欢呼，因为在你们当中的以色列圣者最为伟大。”","notes":[]}]},"13":{"heading":"神要惩罚巴比伦","verses":[{"n":1,"t":"亚摩斯的儿子以赛亚所见，有关巴比伦的默示。","notes":[]},{"n":2,"t":"你们要在荒凉的山上竖立大旗，向他们扬声，挥手招呼他们进入贵族之门。","notes":[]},{"n":3,"t":"我吩咐我所分别为圣的人，召唤我的勇士，就是我那狂喜高傲的人，为要执行我的怒气。","notes":[]},{"n":4,"t":"听啊，山间有喧闹的声音，好像有许多百姓聚集，听啊，多国之民聚集闹哄的声音；这是万军之耶和华召集作战的军队。","notes":[]},{"n":5,"t":"他们从远方来，从天边来，耶和华和他恼恨的兵器要毁灭全地。","notes":[]},{"n":6,"t":"你们要哀号，因为耶和华的日子临近了！这日来到，好像毁灭从全能者来到。","notes":[]},{"n":7,"t":"因此，人的手都变软弱，人的心都必惶惶。","notes":[]},{"n":8,"t":"他们必惊恐，悲痛和愁苦将他们抓住。他们阵痛，好像临产的妇人一样，彼此惊奇对看，脸如火焰。","notes":[]},{"n":9,"t":"看哪！耶和华的日子临到，必有残忍、愤恨、烈怒，使这地荒芜，除灭其中的罪人。","notes":[]},{"n":10,"t":"天上的星宿都不发光，太阳一升起就变黑暗，月亮也不放光。","notes":[]},{"n":11,"t":"我必因邪恶惩罚世界，因罪孽惩罚恶人，我要止息骄傲人的狂妄，制伏残暴者的傲慢。","notes":[]},{"n":12,"t":"我要使人比纯金更少，比俄斐的赤金还少。","notes":[]},{"n":13,"t":"我，万军之耶和华狂怒，就是发烈怒的日子，要令天震动，地必摇撼，离其本位。","notes":[]},{"n":14,"t":"人如被追赶的羚羊，像无人聚集的羊群，各自归回本族，逃到本地。","notes":[]},{"n":15,"t":"凡被追上的必被刺死，凡被捉拿的必倒在刀下。","notes":[]},{"n":16,"t":"他们的婴孩必在他们眼前被摔死，他们的房屋被抢劫，他们的妻子被污辱。","notes":[]},{"n":17,"t":"看哪，我必激起玛代人攻击他们，玛代人并不看重银子，也不喜爱金子。","notes":[]},{"n":18,"t":"他们必用弓击溃青年，不怜悯妇人所生的；眼也不顾惜孩子。","notes":[]},{"n":19,"t":"巴比伦为列国的荣耀，为迦勒底人所夸耀的华美，必像神所倾覆的所多玛、蛾摩拉一样；","notes":[]},{"n":20,"t":"国中必永无人烟，世世代代无人居住；阿拉伯人不在那里支搭帐棚，牧羊的人也不使羊群躺卧在那里。","notes":[]},{"n":21,"t":"旷野的走兽躺卧在那里，咆哮的动物挤满栖身之所；鸵鸟住在那里，山羊鬼魔也在那里跳舞。","notes":[]},{"n":22,"t":"土狼必在它的宫殿 呼号，野狗在华美的殿里吼叫。巴比伦的时辰临近了，它的日子必不长久。","notes":["“宫殿”是根据一些古译本；原文是“寡妇”。"]}]},"14":{"heading":"从被掳中归回","verses":[{"n":1,"t":"耶和华要怜悯雅各，再度拣选以色列，将他们安顿在本地。寄居的必与他们联合，加入雅各家。","notes":[]},{"n":2,"t":"外邦人要将他们带回本地。以色列家必在耶和华的地上得外邦人为仆婢，也要掳掠先前掳掠他们的，辖制先前欺压他们的。","notes":[]},{"n":3,"t":"当耶和华使你得享安息，脱离愁苦、烦恼，和被迫做苦工的日子，","notes":[],"heads":["巴比伦王下到阴间"]},{"n":4,"t":"你必唱这诗歌嘲讽巴比伦王说：“欺压人的竟然灭亡！他的凶暴竟然止息！","notes":["“他的凶暴”是根据死海古卷和古译本；原文是“一堆金子”。"]},{"n":5,"t":"耶和华折断恶人的杖，打断统治者的权杖；","notes":[]},{"n":6,"t":"他们在愤怒中连连攻击万民，在怒气中辖制列国，逼迫他们，毫不留情。","notes":[]},{"n":7,"t":"现在全地得安息，享平静，人都出声欢呼。","notes":[]},{"n":8,"t":"松树和黎巴嫩的香柏树都因你欢乐：自从你仆倒，再也无人上来砍伐我们。","notes":[]},{"n":9,"t":"下面的阴间因你震动，迎接你的到来；在世曾为领袖的阴魂为你惊动，那曾为列国君王的，都从宝座起立。","notes":[]},{"n":10,"t":"他们都要发言，对你说：‘你也变为软弱，像我们一样吗？你也成了我们的样子吗？’","notes":[]},{"n":11,"t":"你的威严和琴瑟的声音都下到阴间。你下面铺的是虫，上面盖的是蛆。","notes":[]},{"n":12,"t":"“明亮之星，早晨之子啊，你竟然从天坠落！你这攻败列国的，竟然被砍倒在地上！","notes":[]},{"n":13,"t":"你心里曾说：‘我要升到天上，我要高举我的宝座在神的众星之上，我要坐在会众聚集的山上，在极北的地方。","notes":[]},{"n":14,"t":"我要升到高云之上，我要与至高者同等。’","notes":[]},{"n":15,"t":"然而，你必坠落阴间，到地府极深之处。","notes":[]},{"n":16,"t":"凡看见你的都要定睛望你，留意看你，说：‘就是这个人吗？他使大地颤抖，使列国震动，","notes":[]},{"n":17,"t":"使世界如同荒野，使城镇倾覆；是他，不释放被掳的人归家。’","notes":[]},{"n":18,"t":"列国的君王各自在自己的坟墓中，在尊荣里长眠。","notes":[]},{"n":19,"t":"惟独你被抛弃在你的坟墓之外，有如被厌恶的枝子，被许多用刀刺透杀死的人覆盖着，一同坠落地府的石头那里，像被践踏的尸首。","notes":["“枝子”与“尼布甲尼撒”的希伯来话发音相近；原文另译“尸身”。"]},{"n":20,"t":"你不得与君王同葬，因为你毁坏你的国，杀戮你的民。“恶人的后裔永不留名。","notes":[]},{"n":21,"t":"为了祖先的罪孽，要预备他子孙的屠宰场，免得他们兴起，夺得全地，使城市遍满地面。”","notes":[]},{"n":22,"t":"万军之耶和华说：“我必起来攻击他们，将巴比伦的名号和剩余的人，连子带孙一并剪除；这是耶和华说的。","notes":[],"heads":["神要毁灭巴比伦"]},{"n":23,"t":"“我必使巴比伦为豪猪占据，成为泥沼之地；我要用灭命的扫帚扫净它；这是万军之耶和华说的。”","notes":[]},{"n":24,"t":"万军之耶和华起誓说：“我怎样思想，必照样成就；我怎样定意，必照样坚立，","notes":[],"heads":["神要毁灭亚述"]},{"n":25,"t":"要在我的地上击破亚述，在我的山上将它践踏。它的轭必离开受压制的人，它的重担必离开他们的肩头。”","notes":[]},{"n":26,"t":"这是向全地所定的旨意，向万国所伸出的手。","notes":[]},{"n":27,"t":"万军之耶和华既然定意，谁能阻挠呢？他的手已经伸出，谁能使它缩回呢？","notes":[]},{"n":28,"t":"亚哈斯王崩的那年，有默示如下：","notes":[],"heads":["神要毁灭非利士"]},{"n":29,"t":"“全非利士啊，不要因击打你的杖折断就喜乐。因为蛇必生出毒蛇，它所生的是会飞的火蛇。","notes":[]},{"n":30,"t":"贫寒人的长子必有得吃；贫穷人必安然躺卧。我必以饥荒灭绝你的根，它必杀尽你所剩余的人。","notes":["“它”：死海古卷是“我”。"]},{"n":31,"t":"门哪，哀号吧！城啊，呼喊吧！全非利士都熔化了！因为有烟从北方而来，在它的行伍中没有掉队的。”","notes":[]},{"n":32,"t":"当如何回答外邦的使者呢？“耶和华建立了锡安，在其中他困苦的百姓必有倚靠。”","notes":[]}]},"15":{"heading":"神要毁灭摩押","verses":[{"n":1,"t":"论摩押的默示。一夜之间，摩押的亚珥变为荒废，归于无有；一夜之间，摩押的基珥变为荒废，归于无有。","notes":[]},{"n":2,"t":"摩押上到神庙和底本的丘坛去哭泣；它因尼波和米底巴哀号，各人头上光秃，胡须剃净。","notes":[]},{"n":3,"t":"他们在街市上腰束麻布，都在房顶和广场上哀号，泪流不停。","notes":[]},{"n":4,"t":"希实本和以利亚利呼喊，他们的声音达到雅杂，所以摩押的士兵高声喊叫，他们的心战兢。","notes":[]},{"n":5,"t":"我的心为摩押哀号；它的难民逃到琐珥，逃到伊基拉．施利施亚。他们上鲁希坡，随走随哭，在何罗念的路上，因毁灭发出哀声。","notes":["“我的心”：有古卷是“它的心”。"]},{"n":6,"t":"宁林的水干涸，青草枯干，嫩草死光，青绿之物，一无所有。","notes":[]},{"n":7,"t":"因此，摩押人所得的财物和积蓄都要运过柳树河。","notes":[]},{"n":8,"t":"哀声遍传摩押四境，哀号的声音达到以基莲，哀号的声音远及比珥．以琳。","notes":[]},{"n":9,"t":"底们的水充满了血，然而我还要加添底们的灾难，让狮子追上摩押的难民和那地剩余的人。","notes":["“底们”：有古卷是“底本”；下同。","“让狮子追上”：死海古卷是“我要淹没”。","“那地”：七十士译本是“押玛”。"]}]},"16":{"heading":"摩押的难民逃到犹大","verses":[{"n":1,"t":"你们当将羔羊奉送给那地的掌权者，从西拉往旷野，送到锡安的山。","notes":["“你们当将”：有古卷是“他们将”。","“锡安”：原文直译“锡安女子”。"]},{"n":2,"t":"摩押的居民来到亚嫩渡口，如逃遁的飞鸟，被赶离鸟巢。","notes":["“摩押的居民”：原文直译“摩押众女子”。","“被赶离鸟巢”或译“如拆窝的雏”。"]},{"n":3,"t":"求你赐谋略，行公平，使你的影子在正午如黑夜，掩护逃亡的人，不泄露逃难者的行踪。","notes":[]},{"n":4,"t":"愿我摩押逃亡的人寄居在你那里，你作他们的避难所，躲避灭命者的面。勒索的人消失，毁灭的事止息，欺压者从国中除灭，","notes":["“愿我摩押逃亡的人”：原文另译“摩押逃亡的人”。"]},{"n":5,"t":"在大卫帐幕中必有宝座因慈爱坚立，必有一位君王凭信实坐在其上，施行审判，寻求公平，迅速行公义。","notes":[]},{"n":6,"t":"我们听闻摩押的骄傲，极其骄傲；它狂妄、骄傲、自大，它夸大的言词都是空的。","notes":[]},{"n":7,"t":"因此，摩押人必为摩押哀号，人人都要哀号。你们要为吉珥．哈列设的葡萄饼哀叹，极其忧伤。","notes":[]},{"n":8,"t":"因为希实本的田地和西比玛的葡萄树都衰残了，列国的君主折断它的枝干，这枝子曾长到雅谢，延伸到旷野，嫩枝向外伸出，直伸过海；","notes":[]},{"n":9,"t":"所以，我要为西比玛的葡萄树哀哭，像雅谢人一样哀哭。希实本、以利亚利啊，我要以眼泪浇灌你，你因夏天果子和收割的庄稼，欢呼声已经止息了。","notes":[]},{"n":10,"t":"田园中不再有欢喜快乐，葡萄园里必无人歌唱，无人欢呼，在压酒池中踹酒的不再踹酒了，我使欢呼的声音止息了。","notes":["“我使...止息了”：七十士译本是“欢呼的声音已止息了”。"]},{"n":11,"t":"因此，我的心肠为摩押哀鸣如琴，我的内心为吉珥．哈列设哀哭。","notes":[]},{"n":12,"t":"当摩押人出现在丘坛，筋疲力尽时，虽然到自己的圣所祈祷，却仍无济于事。","notes":[]},{"n":13,"t":"这是耶和华曾论到摩押的话。","notes":[]},{"n":14,"t":"但现在，耶和华说：“三年之内，按照雇工年数的算法，摩押的荣华必变为羞辱，人口虽曾众多，剩余的又少又弱。”","notes":[]}]},"17":{"heading":"神要惩罚亚兰和以色列","verses":[{"n":1,"t":"论大马士革的默示。看哪，大马士革不再为城市，变为废墟。","notes":[]},{"n":2,"t":"亚罗珥的城镇被撇弃，将成为牧羊之处，羊群在那里躺卧，无人使它们惊吓。","notes":["“亚罗珥...被撇弃”：七十士译本是“永远被撇弃”。"]},{"n":3,"t":"以法莲不再有堡垒，大马士革失去其王国，亚兰的百姓所剩无几，如以色列人的荣美消失一般；这是万军之耶和华说的。","notes":[]},{"n":4,"t":"到那日，雅各的荣美必失色，它肥胖的身躯渐渐消瘦；","notes":[]},{"n":5,"t":"像人收割成熟的禾稼，用手臂割取麦穗，又像人在利乏音谷拾取穗子；","notes":[]},{"n":6,"t":"其间所剩不多，好像人打橄榄树，在最高的树梢上只剩两、三颗橄榄，在多结果子的旁枝上只剩四、五颗；这是耶和华－以色列的神说的。","notes":[]},{"n":7,"t":"当那日，人必仰望造他们的主，眼目看着以色列的圣者。","notes":[]},{"n":8,"t":"他们必不仰望自己手所筑的祭坛，也不理会自己指头所造的亚舍拉和香坛。","notes":[]},{"n":9,"t":"当那日，他们坚固的城必因以色列人的缘故，如同树林中和山顶上所撇弃的地方。这样，地就荒芜了。","notes":["“如同...地方”：七十士译本是“如同亚摩利人和希未人所抛弃的城市”。"]},{"n":10,"t":"因你忘记拯救你的神，忘记那保护你的磐石；所以，你虽栽上佳美的树苗，插上别样的枝子，","notes":[]},{"n":11,"t":"栽种的日子，你使它生长，栽种的早晨，你使它开花，但在愁苦、极其伤痛的日子，所收割的都归无有。","notes":[]},{"n":12,"t":"唉！万民闹哄，好像海浪澎湃，列邦喧闹，如同洪水滔滔，","notes":[],"heads":["敌国都被击败"]},{"n":13,"t":"列邦喧闹，如同大水滔滔；但神一斥责，他们就远远躲避，他们被追赶，如同山上风前的糠秕，又如暴风前的碎秸；","notes":[]},{"n":14,"t":"看哪，晚上有惊吓，未到早晨它就消失无踪。这是掳掠我们之人的厄运，是抢夺我们之人的报应。","notes":[]}]},"18":{"heading":"神要责罚古实","verses":[{"n":1,"t":"祸哉！古实河的那一边、翅膀刷刷作响之地，","notes":[]},{"n":2,"t":"差遣使者在水面上，坐蒲草船过海。你们这些疾行的使者，要到高大光滑的民那里去；那民远近都畏惧，是强大好征服的国，土地有河流穿过。","notes":[]},{"n":3,"t":"世上所有的居民，住在地上的人哪，山上大旗竖起时，你们要看，号角吹响时，你们要听。","notes":[]},{"n":4,"t":"耶和华对我如此说：“我要安静，从我的居所观看，如同日光下闪烁的热气，又如收割时露水蒸发的云雾。”","notes":["“收割时”是根据一些古卷、七十士译本和其他古译本；原文是“收割的热气”。"]},{"n":5,"t":"收割之前，花蕾先谢，花成了将熟的葡萄；他必用刀削去嫩枝，砍掉蔓延的枝条，","notes":[]},{"n":6,"t":"一起丢给山间的鸷鸟和地上的野兽；鸷鸟要在其上避暑，地上一切的野兽都在那里过冬。","notes":[]},{"n":7,"t":"到那时，这高大光滑的民，远近都畏惧的民、强大好征服之国、土地有河流穿过；他们必被当作礼物献给万军之耶和华，献到锡安山－万军之耶和华立他名的地方。","notes":["“被当作”：七十士译本是“将”。"]}]},"19":{"heading":"神要惩罚埃及","verses":[{"n":1,"t":"论埃及的默示。看哪，耶和华乘驾快云，临到埃及；埃及的偶像在他面前战兢，埃及人的心在里面消溶。","notes":[]},{"n":2,"t":"我要激起埃及人攻击埃及人，弟兄攻击弟兄，邻舍攻击邻舍，这城攻击那城，这国攻击那国。","notes":[]},{"n":3,"t":"埃及人的心神在里面耗尽，我要破坏他们的计谋。他们必求问偶像和念咒的，求问招魂的与行巫术的人。","notes":[]},{"n":4,"t":"我要将埃及人交在严厉的主人手中，残暴的君王必管辖他们；这是主－万军之耶和华说的。","notes":[]},{"n":5,"t":"海水枯竭，河流干涸，","notes":[]},{"n":6,"t":"江河发臭，埃及的河水必然减少而枯干。芦苇和芦荻枯萎，","notes":[]},{"n":7,"t":"尼罗河旁的植物，在尼罗河的沿岸，并尼罗河旁所种的一切全都枯焦，被风吹去，归于无有。","notes":["“植物”：原文是“荒地”。"]},{"n":8,"t":"打鱼的哀哭，所有在尼罗河钓鱼的都必悲伤，在水上撒网的也都衰残。","notes":[]},{"n":9,"t":"以细致的麻编织的必羞愧，织布的必变苍白；","notes":["本节是根据死海古卷；原文是“以细致的麻编织的和织白布的，都必羞愧”。"]},{"n":10,"t":"织布的心情沮丧，所有的佣工心都愁烦。","notes":["“织布的心情沮丧”是根据死海古卷；原文是“他的支柱必打碎”。"]},{"n":11,"t":"琐安的官长极其愚昧，法老智慧的谋士筹划愚谋；你们怎敢对法老说：“我是智慧人的子孙，是古代国王的后裔？”","notes":[]},{"n":12,"t":"你的智慧人在哪里？万军之耶和华向埃及所定的旨意，他们既然知道，就让他们告诉你吧！","notes":[]},{"n":13,"t":"琐安的官长愚昧，挪弗的官长受蒙蔽；作埃及支派栋梁的，带领埃及走错了路。","notes":["“挪弗”就是埃及的孟斐斯。"]},{"n":14,"t":"耶和华使歪曲的灵渗入埃及中间，让他们使埃及一切所做的都出差错，好像醉酒之人呕吐时东倒西歪一样。","notes":[]},{"n":15,"t":"在埃及，无论是头是尾，棕树枝与芦苇，所做的事都不得成就。","notes":[]},{"n":16,"t":"到那日，埃及必像妇人一样，因万军之耶和华挥手攻击而战兢惧怕。","notes":[]},{"n":17,"t":"犹大地必使埃及惊恐，不论向谁提起，他都惧怕。这是因万军之耶和华向埃及所定的旨意。","notes":[]},{"n":18,"t":"当那日，埃及地必有五个城市的人说迦南的语言，又指着万军之耶和华起誓。有一城必称为“太阳城”。","notes":["“太阳城”是根据死海古卷和许多古卷；原文是“灭亡城”。"]},{"n":19,"t":"在那日，在埃及地将有献给耶和华的一座坛，边界上必有为耶和华立的一根柱子。","notes":[]},{"n":20,"t":"这都要在埃及地为万军之耶和华作记号和证据。埃及人因受欺压哀求耶和华，他就差遣一位救主作护卫者，拯救他们，","notes":[]},{"n":21,"t":"耶和华就被埃及所认识。在那日，埃及人要认识耶和华，献牲祭和素祭敬拜他，并向耶和华许愿还愿。","notes":[]},{"n":22,"t":"耶和华必击打埃及，又击打又医治，埃及人就归向耶和华。他必应允他们的祷告，医治他们。","notes":[]},{"n":23,"t":"在那日，必有从埃及通往亚述的大道。亚述人要进入埃及，埃及人也要进入亚述；埃及人要与亚述人一同敬拜。","notes":[]},{"n":24,"t":"在那日，以色列将与埃及、亚述三国一起，使地上的人得福。","notes":[]},{"n":25,"t":"万军之耶和华必赐福给他们，说：“埃及－我的百姓，亚述－我手的工作，以色列－我的产业，都有福了！”","notes":[]}]},"20":{"heading":"赤身赤脚的先知","verses":[{"n":1,"t":"亚述元帅受亚述王撒珥根派遣往亚实突的那年，他攻打亚实突，将城攻取。","notes":["“亚述元帅”：原文是亚述的官职“他珥探”。"]},{"n":2,"t":"那时，耶和华吩咐亚摩斯的儿子以赛亚说：“你去解掉你腰间的麻布，脱下你脚上的鞋。”以赛亚就这样做，赤身赤脚行走。","notes":[]},{"n":3,"t":"耶和华说：“我仆人以赛亚怎样赤身赤脚行走三年，作为关于埃及和古实的预兆奇迹，","notes":[]},{"n":4,"t":"照样，亚述王必掳去埃及人，掠去古实人，无论老少，都赤身赤脚，露出下体，使埃及蒙羞。","notes":[]},{"n":5,"t":"以色列人必惊惶羞愧，因为他们仰望古实，以埃及为荣。","notes":[]},{"n":6,"t":"“那时，沿海一带的居民必说：‘看哪，我们素来所仰望的，就是为躲避亚述王所逃往求救的，不过如此！我们怎能逃脱呢？’”","notes":["“逃往”：死海古卷是“倚靠”。"]}]},"21":{"heading":"巴比伦的灭亡","verses":[{"n":1,"t":"论海边旷野的默示。它像尼革夫的旋风扫过，从旷野，从可怕之地而来。","notes":["“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”；本卷书下同。"]},{"n":2,"t":"有凄惨的异象向我揭示：“诡诈的在行诡诈，毁灭的在行毁灭。以拦哪，前进吧！玛代啊，围攻吧！我使它一切的叹息停止了。”","notes":[]},{"n":3,"t":"为此，我腰部满是疼痛，痛苦将我抓住，好像临产的妇人一样的痛。我疼痛甚至不能听，我惊惶甚至不能看。","notes":["“我疼痛...不能看”或译“我所听到的使我疼痛，我所见的使我惊惶”。"]},{"n":4,"t":"我心慌乱，惊恐威吓我。我所渴望的黄昏，反成为我的恐惧。","notes":[]},{"n":5,"t":"有人摆设筵席，铺上地毯，又吃又喝。“官长啊，起来，抹亮盾牌。”","notes":[]},{"n":6,"t":"主对我如此说：“你去设立守望者，让他报告他所看见的。","notes":[]},{"n":7,"t":"他会看见一对一对骑着马的军队，又看见驴队，骆驼队，他要留心听，仔细地听。”","notes":[]},{"n":8,"t":"他如狮子般吼叫：“主啊，我白天常站在瞭望楼，彻夜立在我的瞭望台。”","notes":["“他如狮子般吼叫”：死海古卷是“守望者喊叫”。"]},{"n":9,"t":"看哪，有一对一对骑着马的军队前来。他就回应说：“巴比伦倾倒了！倾倒了！他把巴比伦神明的一切雕刻偶像都打碎在地上了。”","notes":[]},{"n":10,"t":"我被打的禾稼，我禾场上的谷物啊，我从万军之耶和华－以色列的神那里所听见的，都告诉你们了。","notes":[]},{"n":11,"t":"论度玛的默示。有人声从西珥呼喊：“守望的啊，夜里如何？守望的啊，夜里如何？”","notes":[],"heads":["论以东的信息"]},{"n":12,"t":"守望者说：“早晨来到，黑夜将临。你们若要问，问吧，也可以回头再来。”","notes":[]},{"n":13,"t":"论阿拉伯的默示。底但的旅行商队啊，你们在阿拉伯的树林中住宿。","notes":[],"heads":["论阿拉伯的信息"]},{"n":14,"t":"提玛地的居民哪，提水来迎接口渴的人，带饼来迎接难民。","notes":[]},{"n":15,"t":"他们躲避刀剑和出了鞘的刀，躲避上了弦的弓与战争的重灾。","notes":[]},{"n":16,"t":"主对我这样说：“一年之内，按照雇工年数的算法，基达一切的繁华必归无有。","notes":[]},{"n":17,"t":"基达人中强壮弓箭手剩下的数目甚为稀少，这是耶和华－以色列的神说的。”","notes":[]}]},"22":{"heading":"论耶路撒冷的信息","verses":[{"n":1,"t":"论异象谷的默示。什么事使你们上去，全都上到屋顶呢？","notes":[]},{"n":2,"t":"你这四处呐喊、大声喧哗的城、欢乐的邑啊，你被杀的并非被刀所杀，也不是因打仗阵亡。","notes":[]},{"n":3,"t":"你所有的官长一同奔逃，不用弓箭就被捆绑；你们即使逃往远方，也要被找到，一同被捆绑。","notes":["“不用...捆绑”或译“都为弓箭手所捆绑”。"]},{"n":4,"t":"因此我说：“不要看我，让我痛哭吧！不要因我百姓的毁灭竭力安慰我。”","notes":["“我百姓”：原文直译“我百姓的女儿”。"]},{"n":5,"t":"因为这是万军之主耶和华使异象谷混乱、践踏、烦扰的日子；城墙被攻破，哀声达到山上。","notes":[]},{"n":6,"t":"以拦提着箭袋，有战车、士兵、骑兵；吉珥亮出盾牌，","notes":[]},{"n":7,"t":"你佳美的山谷遍布战车，骑兵排列在城门前。","notes":[]},{"n":8,"t":"他除掉犹大的防御。那时，你指望森林库里的兵器。","notes":[]},{"n":9,"t":"你们看见大卫城缺口很多，就汇集下池的水；","notes":[]},{"n":10,"t":"你们数点耶路撒冷的房屋，拆毁房屋，用以修补城墙，","notes":[]},{"n":11,"t":"又在两道城墙中间挖水池，用以盛旧池的水，却不仰望成就这事的主，也不顾念从古时定这事的主。","notes":[]},{"n":12,"t":"当那日，万军之主耶和华使人哭泣哀号，头上光秃，身披麻布。","notes":[]},{"n":13,"t":"看哪，人却欢喜快乐，宰牛杀羊，吃肉喝酒：“让我们吃吃喝喝吧！因为明天要死了。”","notes":[]},{"n":14,"t":"万军之耶和华开启我的耳朵：“这罪孽直到你们死，断不得赦免！”这是万军之主耶和华说的。","notes":[]},{"n":15,"t":"万军之主耶和华如此说：“你到舍伯那宫廷总管那里去，说：","notes":[],"heads":["对舍伯那的警告"]},{"n":16,"t":"‘你在这里凭什么？你在这里靠谁？竟敢在这里为自己凿坟墓，在高处为自己凿坟墓，在岩石中为自己挖安身之所！","notes":[]},{"n":17,"t":"你这伟大的人，看哪，耶和华必将你用力抛出，将你紧紧缠裹。","notes":[]},{"n":18,"t":"他必将你卷成一团，好像抛球一样抛向宽阔之地。你这主人家的羞辱啊，你必死在那里，你引以为荣的战车也毁在那里。","notes":[]},{"n":19,"t":"我要革除你的官职，你必从原位被逐。’","notes":["“你..被逐”：原文是“他必将你逐出原位”。"]},{"n":20,"t":"“到那日，我要召希勒家的儿子─我的仆人以利亚敬来，","notes":[]},{"n":21,"t":"将你的外袍给他穿上，将你的腰带给他系紧，将你的政权交在他手中。他必作耶路撒冷居民和犹大家的父。","notes":[]},{"n":22,"t":"我要将大卫家的钥匙放在他肩头上。他开了，无人能关；他关了，无人能开。","notes":[]},{"n":23,"t":"我要使他立稳，像钉子钉在坚固的地方；他必成为他父家荣耀的宝座。","notes":[]},{"n":24,"t":"他父家所有的荣耀，连儿女带子孙，有如杯碗、瓶罐的小器皿，都挂上他身上。","notes":[]},{"n":25,"t":"当那日，万军之耶和华说，钉在坚固处的钉子必挪移，被砍断落地，挂在上面的各样重担都被切断。这是耶和华说的。”","notes":[]}]},"23":{"heading":"论推罗的信息","verses":[{"n":1,"t":"论推罗的默示。哀号吧，他施的船只！因为推罗已成废墟，没有房屋存留，他们从基提地来的时候，得到这个消息。","notes":["“他们...消息”或译“没有可进之路。这消息是从基提地得来的”。"]},{"n":2,"t":"沿海的居民，西顿的商家啊，当静默无声。你差人航海，","notes":["本节是根据死海古卷；原文是“沿海的居民，就是素来靠航海西顿的商家得丰盛的，你们当静默无言。”"]},{"n":3,"t":"在大水之上，西曷河的粮食、尼罗河的庄稼是推罗的进项，它就成为列国的商埠。","notes":[]},{"n":4,"t":"西顿，你这海洋中的堡垒啊，应当羞愧，因为大海说：“我未经历产痛，也没有生产，未曾养育男孩，也没有抚养女孩。”","notes":["“西顿...说”或译“西顿哪，你当惭愧；因为大海说，就是海中的保障说”。"]},{"n":5,"t":"推罗的风声传到埃及时，他们为这风声极其疼痛。","notes":[]},{"n":6,"t":"你们当渡到他施去，哀号吧，沿海的居民！","notes":[]},{"n":7,"t":"这就是你们那古老欢乐的城市吗？它的脚曾带人到远方居住。","notes":[]},{"n":8,"t":"谁定意推罗有这样的遭遇呢？它本是赐冠冕的，它的商家是王子，生意人是世上尊贵的人。","notes":[]},{"n":9,"t":"这是万军之耶和华所定的，为要贬抑一切荣耀的狂傲，使地上一切尊贵的人被藐视。","notes":[]},{"n":10,"t":"他施啊，你要像尼罗河一样在你的地泛滥，不再有腰带的束缚了。","notes":["“他施”：原文直译“他施女子”。","本节七十士译本是“去耕你田地吧！因船只不再出离迦太基。”"]},{"n":11,"t":"耶和华已经向海伸手，震动列国；他出令对付迦南，要拆毁其中的堡垒。","notes":[]},{"n":12,"t":"他说：“受欺压的少女西顿哪，你必不再欢乐。起来！渡到基提去，就是在那里也不得安歇。","notes":["“少女西顿”：原文直译“少女西顿女子”。"]},{"n":13,"t":"看哪，迦勒底人之地，这国民如今已不复存在。亚述人使它成为住旷野者的居所。他们建筑自己的瞭望楼，拆毁它的宫殿，使它成为荒凉。","notes":["“它”指“推罗”；下同。"]},{"n":14,"t":"哀号吧，他施的船只！因你们的堡垒已成废墟。","notes":[]},{"n":15,"t":"到那时，推罗必被忘记七十年，就是一位君王的年数。七十年后，推罗的景况必如妓女之歌：","notes":[]},{"n":16,"t":"“你这被遗忘的妓女啊，带着琴周游城内，弹得美妙，唱许多歌，好让人记得你。”","notes":[]},{"n":17,"t":"七十年后，耶和华必巡视推罗，使它再度获利，与地面上的世界各国贸易。","notes":["“获利”：原文是“得卖淫的赏金”；下同。","“贸易”：原文是“行淫”。"]},{"n":18,"t":"它的收益和获利都要归耶和华为圣，不再私自屯积存留；因为它的收益必归给住在耶和华面前的人，使他们吃饱，穿华丽的衣服。","notes":[]}]},"24":{"heading":"耶和华要责罚世界","verses":[{"n":1,"t":"看哪，耶和华使地空虚，变为荒芜，地面扭曲，居民四散。","notes":[]},{"n":2,"t":"那时，百姓如何，祭司也如何；仆人如何，主人也如何；婢女如何，主母也如何；买主如何，卖主也如何；放债的如何，借贷的也如何；债主如何，欠债的也如何。","notes":[]},{"n":3,"t":"地必全然空虚，尽都荒芜，因为这话是耶和华说的。","notes":[]},{"n":4,"t":"大地悲哀凋零，世界败落衰残，地上居高位的人也没落了。","notes":[]},{"n":5,"t":"地被其上的居民所污秽，因为他们犯了律法，废了律例，背了永约。","notes":[]},{"n":6,"t":"所以，诅咒吞灭大地，住在其上的都有罪；地上的居民被火焚烧，剩下的人稀少。","notes":[]},{"n":7,"t":"新酒悲哀，葡萄树凋残，心中欢乐的都叹息。","notes":[]},{"n":8,"t":"击鼓之乐停止，狂欢者的喧哗止住，弹琴之乐也停止了。","notes":[]},{"n":9,"t":"人不再饮酒唱歌，喝烈酒的，必以为苦。","notes":[]},{"n":10,"t":"荒凉的城拆毁了，各家关闭，无法进入。","notes":[]},{"n":11,"t":"有人在街上嚷着要酒喝，一切的喜乐变为昏暗，地上的欢乐全都消失。","notes":[]},{"n":12,"t":"城里尽是荒凉，城门全都摧毁。","notes":[]},{"n":13,"t":"地上的万民正像打过的橄榄树，又如葡萄酿酒以后再去摘取，所剩无几。","notes":[]},{"n":14,"t":"他们要高声欢呼，从海那边扬声赞美耶和华的威严。","notes":[]},{"n":15,"t":"因此，你们要在日出之地荣耀耶和华，在众海岛荣耀耶和华－以色列神的名。","notes":[]},{"n":16,"t":"我们听见从地极有人歌唱：“荣耀归于公义的那一位！”我却说：“我灭亡了！我灭亡了，我有祸了！诡诈的还在行诡诈，诡诈的还在大行诡诈。”","notes":[]},{"n":17,"t":"地上的居民哪，惊吓、陷阱、罗网都临到你；","notes":[]},{"n":18,"t":"躲过惊吓之声的坠入陷阱，逃离陷阱的又被罗网缠住，因为天上的窗户都打开，地的根基也震动。","notes":[]},{"n":19,"t":"地必全然破坏，尽都崩裂，剧烈震动。","notes":[]},{"n":20,"t":"地要摇摇晃晃，好像醉酒的人，又如小屋子摇来摇去；罪过重压其上，它就塌陷，不能复起。","notes":[]},{"n":21,"t":"到那日，耶和华在天上必惩罚天上的军队，在地上必惩罚地上的列王。","notes":[]},{"n":22,"t":"他们必被聚集，像囚犯困在牢里，他们被关在监狱，多日之后便受惩罚。","notes":[]},{"n":23,"t":"那时，月亮要蒙羞，太阳要惭愧，因为万军之耶和华必在锡安山，在耶路撒冷作王，在他众长老面前彰显荣耀。","notes":[]}]},"25":{"heading":"一首赞美诗","verses":[{"n":1,"t":"耶和华啊，你是我的神，我要尊崇你，称颂你的名。因为你以信实忠信行远古所定奇妙的事。","notes":[]},{"n":2,"t":"你使城市变为废墟，使坚固的城荒凉，使外邦人的城堡不再为城，永远不再重建。","notes":[]},{"n":3,"t":"所以，强大的民必尊敬你，残暴之国的城必敬畏你。","notes":[]},{"n":4,"t":"因为你是贫寒人的保障，贫穷人急难中的保障，暴风雨之避难所，炎热地之阴凉处。当残暴者盛气凌人的时候，如暴风直吹墙壁，","notes":[]},{"n":5,"t":"如干旱地的热气，你要制止外邦人的喧嚷，残暴者的歌要停止，好像热气因云的阴影而消失。","notes":[]},{"n":6,"t":"在这山上，万军之耶和华必为万民摆设宴席，有肥甘与美酒，就是满有骨髓的肥甘与精酿的美酒。","notes":[],"heads":["神为万民摆设宴席"]},{"n":7,"t":"在这山上，他必吞灭那缠裹万民的面纱和那遮盖列国的遮蔽物。","notes":[]},{"n":8,"t":"他已吞灭死亡直到永远。主耶和华必擦干各人脸上的眼泪，在全地除去他百姓的羞辱；这是耶和华说的。","notes":[]},{"n":9,"t":"到那日，人必说：“看哪，这是我们的神，我们向来等候他，他必拯救我们。这是耶和华，我们向来等候他，我们必因他的救恩欢喜快乐。”","notes":[]},{"n":10,"t":"耶和华的手必按住这山，摩押人要被践踏在他底下，好像干草被践踏在粪池里。","notes":["“粪池”：原文另译“粪池的水”。"],"heads":["神要惩罚摩押"]},{"n":11,"t":"他们要在其中伸展双手，好像游泳的人伸手游泳。他们的手虽灵巧，耶和华却使他们的骄傲降为卑下。","notes":[]},{"n":12,"t":"他使你城墙上坚固的碉堡倾倒，夷为平地，化为尘土。","notes":[]}]},"26":{"heading":"神使他的百姓得胜","verses":[{"n":1,"t":"当那日，在犹大地，人必唱这歌：“我们有坚固的城，耶和华赐救恩为城墙，为城郭。","notes":[]},{"n":2,"t":"你们要敞开城门，使守信的公义之民得以进入。","notes":[]},{"n":3,"t":"坚心倚赖你的，你必保守他十分平安，因为他倚靠你。","notes":[]},{"n":4,"t":"你们当倚靠耶和华，直到永远，因为耶和华，耶和华是永远的磐石。","notes":[]},{"n":5,"t":"他使居住高处的与高处的城市一同降为卑下，将城拆毁，夷为平地，化为尘土，","notes":[]},{"n":6,"t":"使它被脚践踏，就是被困苦人和贫寒人的脚践踏。”","notes":[]},{"n":7,"t":"义人的道是正直的，正直的主啊，你修平义人的路。","notes":[]},{"n":8,"t":"耶和华啊，我们在你行审判的路上等候你，我们心里所渴慕的，就是你的名和你的称号。","notes":["“等候你”：死海古卷和一些古译本是“仰望”。","“称号”：原文是“纪念”。"]},{"n":9,"t":"夜间，我的心渴想你，我里面的灵切切寻求你。因为你在地上行审判的时候，世上的居民就学习公义。","notes":[]},{"n":10,"t":"恶人虽然领受恩惠，仍未学到公义。在正直之地，他行不义，也不看耶和华的威严。","notes":[]},{"n":11,"t":"耶和华啊，你的手高举，他们不观看；愿他们观看你为百姓发的热心而羞愧，愿火吞灭你的敌人。","notes":[]},{"n":12,"t":"耶和华啊，你必赏赐我们平安，因为我们所做的一切，都是你为我们成就的。","notes":[]},{"n":13,"t":"耶和华－我们的神啊，在你以外曾有别的主管辖我们，但我们惟独称扬你的名。","notes":[]},{"n":14,"t":"死去的不能再复活，阴魂不能再兴起；你惩罚他们，使他们毁灭，他们的名号就全然消灭。","notes":["“名号”：原文是“纪念”。"]},{"n":15,"t":"耶和华啊，你增添国民，你增添国民，得了荣耀，又拓展国土的疆界。","notes":[]},{"n":16,"t":"耶和华啊，他们在急难中寻求你。你的管教临到他们身上时，他们倾吐低声的祷告。","notes":["本节有古卷是“耶和华啊，我们在急难中寻求你。你低声的管教倾倒在我们身上。”"]},{"n":17,"t":"妇人怀孕，临产疼痛，在痛苦之中喊叫；耶和华啊，我们在你面前也是如此。","notes":[]},{"n":18,"t":"我们曾怀孕，曾疼痛，所生产的竟像风一样，并未带给地上任何拯救；世上也未曾有居民生下来。","notes":["“并未...生下来”或译“并未带给地上任何胜利，也未曾打败世上的居民”。"]},{"n":19,"t":"你的死人要复活，我的尸首要起来。睡在尘土里的啊，要醒起歌唱！你的甘露好像晨曦的甘露，地要交出阴魂。","notes":["“睡...歌唱！”死海古卷和七十士译本是“睡在尘土里的必醒起歌唱。”","“晨曦”或译“菜蔬”。"]},{"n":20,"t":"我的百姓啊，要进入内室，关上你的门，躲避片刻，等到愤怒过去。","notes":[],"heads":["审判和复兴"]},{"n":21,"t":"因为，看哪，耶和华从他的居所出来，要惩罚地上居民的罪孽。地必露出其中的血，不再掩盖被杀的人。","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"到那日，耶和华必用他坚硬锐利的大刀惩罚力威亚探，就是那爬得快的蛇，惩罚力威亚探，就是那弯弯曲曲的蛇，并杀死海里的大鱼。","notes":["“力威亚探”是音译，一种海兽；下同。"]},{"n":2,"t":"当那日，你们要唱这美好葡萄园的歌：","notes":["“美好”是根据七十士译本；原文是“出酒”。"]},{"n":3,"t":"“我－耶和华看守葡萄园，按时灌溉，昼夜看守，免得有人损害。","notes":[]},{"n":4,"t":"我心中不存愤怒。惟愿在战争中我有荆棘和蒺藜，我就起步攻击他，把他一同焚烧；","notes":[]},{"n":5,"t":"或者让他紧靠我，以我为避难所，与我和好，与我和好。”","notes":[]},{"n":6,"t":"将来雅各要扎根，以色列要发芽开花，果实遍满地面。","notes":[]},{"n":7,"t":"耶和华击打以色列，岂像击打那些击打他们的人吗？以色列被杀戮，岂像其他人所遭遇的杀戮吗？","notes":[]},{"n":8,"t":"你驱赶他们，放逐他们，与他们相争。在刮东风的日子，他以暴风赶逐他们。","notes":[]},{"n":9,"t":"所以，雅各的罪孽藉此得赦免，除罪的效果尽在乎此；他使祭坛的石头变为粉碎的石灰，使亚舍拉和香坛不再立起。","notes":[]},{"n":10,"t":"因为坚固的城变为荒凉，成了被撇弃的居所，像旷野一样；牛犊在那里吃草，在那里躺卧，吃尽其中的树枝。","notes":[]},{"n":11,"t":"它的枝条一枯干，就被折断，妇女用以点火燃烧。因为这百姓蒙昧无知，所以，造他们的必不怜悯他们，造成他们的也不施恩给他们。","notes":[]},{"n":12,"t":"到那日， 以色列人哪，耶和华必像人打树拾果一般，从大河的支流，直到埃及的溪谷，将你们一一收集。","notes":[]},{"n":13,"t":"当那日，号角大响；在亚述地将亡的，与被赶散至埃及地的，都要前来，在耶路撒冷圣山上敬拜耶和华。","notes":[]}]},"28":{"heading":"对北国的警告","verses":[{"n":1,"t":"祸哉！以法莲酒徒高傲的冠冕，其荣美竟如花凋残；他们在肥沃的山谷顶上，被酒击败。","notes":[]},{"n":2,"t":"看哪，主有一位大能大力者，如强烈的冰雹，如毁灭的暴风雨，如涨溢的洪水，他必亲手将他们摔落在地。","notes":[]},{"n":3,"t":"以法莲酒徒高傲的冠冕，必被脚践踏；","notes":[]},{"n":4,"t":"那如凋残之花的荣美，在肥沃的山谷顶上，必如夏令前初熟的无花果，让看见的人注意，摘到手里，随即吞吃。","notes":[]},{"n":5,"t":"到那日，万军之耶和华必成为他余民的荣冠华冕，","notes":[]},{"n":6,"t":"成为在位审判者的公平之灵，和城门口制敌的力量。","notes":[]},{"n":7,"t":"这些人也因酒摇晃，因烈酒东倒西歪。祭司和先知因烈酒摇晃，被酒所困，因烈酒东倒西歪。他们错解默示，审判时不分是非。","notes":[],"heads":["以赛亚和犹大酒醉的先知"]},{"n":8,"t":"筵席上都满了呕吐的污秽，没有一处干净。","notes":[]},{"n":9,"t":"“他要将知识指教谁呢？要向谁阐明信息呢？是向那些刚断奶的，离开母亲胸怀的吗？","notes":[]},{"n":10,"t":"因为他咕哝咕哝，咕哝咕哝，唠唠叨叨，唠唠叨叨，这里一点，那里一点。”","notes":[]},{"n":11,"t":"耶和华要藉嘲弄的嘴唇和外邦人的舌头，向这百姓说话。","notes":[]},{"n":12,"t":"他曾对他们说：“这是安歇之所，你们要使疲乏的人得安歇，这是歇息之处。”他们却不肯听。","notes":[]},{"n":13,"t":"耶和华的话对他们而言是“咕哝咕哝，咕哝咕哝，唠唠叨叨， 唠唠叨叨，这里一点，那里一点”；以致他们往前行，却后仰跌倒，甚至跌伤，落入陷阱，被抓住了。","notes":[]},{"n":14,"t":"因此，你们这些傲慢的人，就是管辖住耶路撒冷这百姓的，要听耶和华的话。","notes":[],"heads":["锡安的房角石"]},{"n":15,"t":"你们曾说：“我们已与死亡立约，与阴间结盟，不可挡的鞭子挥过时，必不临到我们；因我们以谎言为避难所，靠虚假来藏身”；","notes":[]},{"n":16,"t":"所以，主耶和华如此说：“看哪，我在锡安放一块石头作为根基，是衡量的石头，是宝贵的房角石，稳固的根基；信靠他的人必不致惊恐。","notes":[]},{"n":17,"t":"我以公平为准绳，以公义为铅垂线；冰雹必冲去谎言的避难所，大水必漫过藏身之处。","notes":[]},{"n":18,"t":"你们与死亡所立的约必废除，与阴间所结的盟不得坚立；不可挡的鞭子挥过时，你们必被践踏。","notes":[]},{"n":19,"t":"每逢它挥来，必将你们掳去；每早晨它必挥过，白昼黑夜都是如此。明白这信息的都必惊恐。”","notes":[]},{"n":20,"t":"床榻短，人不能伸展；被子窄，人无从裹身。","notes":[]},{"n":21,"t":"耶和华必兴起，像在毗拉心山，他必发怒，如在基遍谷；为要做成他的工，就是非常的工，成就他的事，就是奇异的事。","notes":[]},{"n":22,"t":"现在你们不可傲慢，免得捆绑你们的绳索更结实，因为我从万军之主耶和华那里听见，在全地施行灭绝的事已定。","notes":[]},{"n":23,"t":"你们当侧耳听我的声音，留心听我的言语。","notes":[],"heads":["神的智慧"]},{"n":24,"t":"那为撒种而耕地的会不停地耕地，松土，耙地吗？","notes":[]},{"n":25,"t":"他铲平了地面，岂不就种小茴香，播种大茴香，按行列种小麦，在定处种大麦，在田边种粗麦吗？","notes":[]},{"n":26,"t":"他的神教导他，指导他合宜的方法。","notes":[]},{"n":27,"t":"原来打小茴香，不用尖利的器具，轧大茴香，也不是用车轮；却要用杖打小茴香，用棍打大茴香。","notes":[]},{"n":28,"t":"谷要打，但不能持续地捣，用车轮和马轧，却不轧碎它。","notes":[]},{"n":29,"t":"这也是出于万军之耶和华，他的谋略奇妙，他的智慧广大。","notes":[]}]},"29":{"heading":"耶路撒冷受围困","verses":[{"n":1,"t":"祸哉！亚利伊勒，亚利伊勒，大卫安营的城，任凭你年复一年，节期照常循环，","notes":["“亚利伊勒”：代表耶路撒冷，意思是“祭坛”；下同。"]},{"n":2,"t":"我却要使亚利伊勒遭难；它必悲伤哀号，它对我是亚利伊勒。","notes":[]},{"n":3,"t":"我必四围安营攻击你，筑台围困你，堆垒攻击你。","notes":[]},{"n":4,"t":"你必败落，从地里说话，你的言语细微出于尘埃。你的声音必像那招魂者的声音出于地，你的言语呢喃出于尘埃。","notes":[]},{"n":5,"t":"你那成群的陌生人要像细尘，暴民要像吹起的糠秕；这事必顷刻之间忽然临到。","notes":["“你那成群的陌生人”：死海古卷是“你那成群骄傲的人”；七十士译本是“不敬虔的人的财富”。"]},{"n":6,"t":"万军之耶和华必使雷轰、地震、巨响、旋风、暴风，并吞灭的火焰临到它。","notes":[]},{"n":7,"t":"那时，攻击亚利伊勒列国的军队，与一切攻击亚利伊勒和它城堡，并带给它患难的，必如梦，如夜间的异象；","notes":[]},{"n":8,"t":"又像饥饿的人在梦中吃饭，醒了仍觉饥肠辘辘；或像口渴的人在梦中喝水，醒了仍觉发昏，心里想喝。攻击锡安山列国的军队也必如此。","notes":[]},{"n":9,"t":"你们等候惊奇吧！你们沉迷宴乐吧！他们醉了，却非因酒；东倒西歪，却非因烈酒。","notes":[],"heads":["无人听警告"]},{"n":10,"t":"因为耶和华将沉睡的灵浇灌你们，遮住你们的眼，眼就是先知，覆盖你们的头，头就是先见。","notes":[]},{"n":11,"t":"所有的默示，在你们看来都如封住的书卷，人将这书卷交给识字的人，说：“请念吧！”他说：“我不能念，因为它封住了。”","notes":[]},{"n":12,"t":"又将这书卷交给不识字的人，说：“请念吧！”他说：“我不识字。”","notes":[]},{"n":13,"t":"主说：“因这百姓以口亲近我，用嘴唇尊敬我，心却远离我；他们敬畏我，不过是领受前人的命令。","notes":[]},{"n":14,"t":"所以，看哪，我要在这百姓中行奇妙的事，就是奇妙又奇妙的事。他们智慧人的智慧必然消灭，聪明人的聪明必然消失。”","notes":[]},{"n":15,"t":"祸哉！那些向耶和华深藏谋略的，他们在暗中行事，说：“有谁看见我们呢？谁会注意我们呢？”","notes":[]},{"n":16,"t":"你们把事情颠倒了，岂可看陶匠如陶土呢？受造物岂可论创造者说，“他并没有造我”？制成物岂可论制作者说，“他根本不懂”？","notes":[]},{"n":17,"t":"黎巴嫩变为田园，田园看似森林，不是只需要一些时间吗？","notes":[],"heads":["将来的希望"]},{"n":18,"t":"那时，聋子必听见这书上的话；盲人的眼必从迷蒙黑暗中看见。","notes":[]},{"n":19,"t":"困苦的人必因耶和华增添欢喜，人间贫穷的必因以色列的圣者快乐。","notes":[]},{"n":20,"t":"因为残暴的人归于无有，傲慢的人已经灭绝，一切存心作恶的都被剪除。","notes":[]},{"n":21,"t":"他们凭一句话定一个人有罪，为在城门口断是非的设下罗网，又用虚无的事屈枉义人。","notes":[]},{"n":22,"t":"所以，救赎亚伯拉罕的耶和华论到雅各家时如此说：“雅各必不再羞愧，面容也不再变色。","notes":[]},{"n":23,"t":"当他的儿女看见我的手在他们当中所成就的事情，他们就必尊我的名为圣，尊雅各的圣者为圣，他们必敬畏以色列的神。","notes":["“当...事情”或译“但他看见他的众子，就是我手的工作在他那里”。"]},{"n":24,"t":"心中迷糊的必明白，发怨言的必领受训诲。”","notes":[]}]},"30":{"heading":"跟埃及订立无用的条约","verses":[{"n":1,"t":"耶和华说：“祸哉！这悖逆的儿女。他们同谋，却不出于我，结盟，却不出于我的灵，以致罪上加罪。","notes":[]},{"n":2,"t":"他们没有寻求我的指示，就起身下埃及去，要倚靠法老的庇护坚固自己，并投在埃及的荫下。","notes":[]},{"n":3,"t":"但法老的庇护反成为你们的羞辱；你们投在埃及荫下，反使你们惭愧。","notes":[]},{"n":4,"t":"他们的领袖已在琐安，他们的使臣到了哈内斯。","notes":[]},{"n":5,"t":"他们必因那无益于他们的民蒙羞；那民并非帮助，也非有益，只带来羞耻和凌辱。”","notes":[]},{"n":6,"t":"论尼革夫牲畜的默示。他们将财物驮在驴背上，将宝物驮在骆驼的背脊，经过艰难困苦之地，就是母狮、公狮、毒蛇、飞蛇之地，往那无益于他们的民那里去。","notes":[]},{"n":7,"t":"埃及的帮助是徒然的，因此，我称它为“毫不中用的拉哈伯”。","notes":["“拉哈伯”是神话故事中的大海怪。"]},{"n":8,"t":"现在你要去，在他们面前将这话刻在版上，写在书上，以便流传后世，直到永永远远。","notes":["“直到永永远远”：有古卷是“作永远的见证”。"],"heads":["不顺服的百姓"]},{"n":9,"t":"因为他们是悖逆的百姓、说谎的儿女，是不肯听从耶和华训诲的儿女。","notes":[]},{"n":10,"t":"他们对先见说：“不要再看了”；对先知说：“不要向我们预言正直的事；要对我们说好听的话，预言虚幻的事。","notes":[]},{"n":11,"t":"要离开这道，偏离这路，不要在我们面前再提说以色列的圣者。”","notes":[]},{"n":12,"t":"所以，以色列的圣者如此说：“因你们藐视这话，倚赖欺压和诡诈，以此为可靠，","notes":[]},{"n":13,"t":"因此，这罪孽在你们身上，好像高墙里有凸起的裂缝，顷刻之间忽然坍下来了；","notes":[]},{"n":14,"t":"它被砸碎，好像把陶匠的瓦器摔碎，毫不顾惜，甚至在碎块中找不到一片可用以从炉内取火，或从池中舀水。”","notes":[]},{"n":15,"t":"主耶和华－以色列的圣者如此说：“你们得救在乎归回安息，得力在乎平静安稳。”你们却是不肯，","notes":[]},{"n":16,"t":"你们说：“不然，我们要骑马奔走”，所以你们必然奔走。你们又说：“我们要骑快马”，所以追赶你们的，也必飞快。","notes":[]},{"n":17,"t":"一人叱喝，令千人逃跑，五人叱喝，你们都逃跑；以致剩下的如山顶的旗杆，如山冈上的大旗。","notes":[]},{"n":18,"t":"耶和华必然等候，要施恩给你们；必然兴起，好怜悯你们。因为耶和华是公平的神；凡等候他的都是有福的！","notes":[],"heads":["神要赐福给他的子民"]},{"n":19,"t":"住在锡安、居于耶路撒冷的百姓啊，你必不再哭泣。主必因你哀求的声音施恩给你，他听见的时候就必应允你。","notes":[]},{"n":20,"t":"主虽然以艰难给你当饼，以困苦给你当水，你的教师却不再隐藏，你的眼睛必看见你的教师。","notes":[]},{"n":21,"t":"你或向左或向右，必听见后边有声音说：“这是正路，要行在其间。”","notes":[]},{"n":22,"t":"你要玷污那雕刻偶像所包的银子和铸造偶像所镀的金子。你要抛弃它们，如抛弃污秽之物；对偶像说：“去吧！”","notes":[]},{"n":23,"t":"你撒种在地里，主必降雨在其上，使地所出的粮食肥美丰盛。那时，你的牲畜必在辽阔的草场吃草。","notes":[]},{"n":24,"t":"耕地的牛和驴必吃加盐的饲料，是用铲子和杈子扬净的。","notes":[]},{"n":25,"t":"在大行杀戮的日子，城楼倒塌的时候，高山峻岭必有川河涌流。","notes":[]},{"n":26,"t":"当耶和华包扎他百姓的伤口，医治他所击打伤痕的日子，月光必像日光，日光必加七倍，像七日的光一样。","notes":[]},{"n":27,"t":"看哪，耶和华的名从远方来，他的怒气烧起，浓烟上腾。他的嘴唇满有愤恨，他的舌头像吞灭的火。","notes":[],"heads":["神要惩罚亚述"]},{"n":28,"t":"他的气息如涨溢的河水，直涨到颈项，要用毁灭的筛网筛净列国，并在众民口中安放导错方向的嚼环。","notes":[]},{"n":29,"t":"你们必唱歌，像守圣节的夜间一样；并且心中喜乐，像人吹笛，来到耶和华的山，到以色列的磐石那里。","notes":[]},{"n":30,"t":"耶和华必使人听见他威严的声音，又以极大的愤怒、吞灭的火焰、雷雨、暴风和像石块的冰雹，使人看见他降罚的膀臂。","notes":[]},{"n":31,"t":"亚述必因耶和华的声音惊惶，耶和华必用杖击打它。","notes":[]},{"n":32,"t":"耶和华必将定规要打的杖加在它身上；每打一下，都必配合击鼓弹琴的节奏。打仗时，耶和华必振臂与它交战。","notes":["“定规要打”：有古卷是“惩罚”。"]},{"n":33,"t":"原来陀斐特早已预备好了，是为君王预备的；又深又宽，堆满了火和木柴；耶和华的气息犹如一股硫磺使它燃起。","notes":["“陀斐特”是焚烧的地方，在耶路撒冷南方欣嫩子谷的东南端。"]}]},"31":{"heading":"神要保护耶路撒冷","verses":[{"n":1,"t":"祸哉！那些下埃及求帮助的，他们仰赖马匹，倚靠甚多的战车，并倚靠强壮的骑兵，却不仰望以色列的圣者，也不求问耶和华。","notes":[]},{"n":2,"t":"其实，耶和华有智慧，他降灾祸，并不撤回自己的话，却要兴起攻击作恶之家，攻击那帮助人作恶的。","notes":[]},{"n":3,"t":"埃及人不过是人，并非神，他们的马不过是血肉，并不是灵。耶和华一伸手，那帮助人的必绊跌，受帮助的也必跌倒，都一同灭亡。","notes":[]},{"n":4,"t":"耶和华对我如此说，狮子和少壮狮子为猎物而咆哮，许多牧人被召来攻击它，它总不因他们的声音惊惶，也不因他们的喧嚷退缩；万军之耶和华也必如此降临在锡安的大小山冈上争战。","notes":[]},{"n":5,"t":"雀鸟盘旋护卫，万军之耶和华也必照样保护耶路撒冷；他必保护拯救，必逾越而搭救。","notes":[]},{"n":6,"t":"以色列人哪，要归向你们严重悖逆的那一位！","notes":[]},{"n":7,"t":"到那日，你们各人要抛弃亲手所造、陷自己于罪中的金偶像和银偶像。","notes":[]},{"n":8,"t":"亚述必倒在刀下，并非人的刀；有刀要将它吞灭，并非人的刀。它要逃避这刀，它的年轻人必做苦工。","notes":[]},{"n":9,"t":"它的磐石必因惊吓而消失，它的领袖必因大旗惊惶；这是那有火在锡安、有炉在耶路撒冷的耶和华说的。","notes":[]}]},"32":{"heading":"公正的君王","verses":[{"n":1,"t":"看哪，必有一位君王凭公义执政，必有王子藉公平掌权。","notes":[]},{"n":2,"t":"必有一人如避风港，如暴风雨的藏身处；如干旱地的溪流，又如干燥地巨石的阴影。","notes":[]},{"n":3,"t":"看的人眼睛不再昏花，听的人耳朵必留心听。","notes":[]},{"n":4,"t":"性急的人懂得分辨，口吃的人说话流畅。","notes":[]},{"n":5,"t":"愚顽人不再称为君子，流氓不再称为绅士。","notes":[]},{"n":6,"t":"因为愚顽人必说愚妄的话，他的心作恶，行亵渎的事，传播恶言攻击耶和华，使饥饿的人仍然饥饿，口渴的人无水可喝。","notes":["“作恶”：死海古卷是“谋恶”。"]},{"n":7,"t":"流氓的手段邪恶，他图谋恶计，用谎言毁灭困苦人；贫穷人讲求公理时，他也是如此行。","notes":[]},{"n":8,"t":"君子却图谋高尚的事，他必因高尚的事站立得稳。","notes":[]},{"n":9,"t":"安逸的妇女啊，起来听我的声音！无虑的女子啊，侧耳听我的言语！","notes":[],"heads":["审判和复兴"]},{"n":10,"t":"无虑的女子啊，再过一年，你们必颤栗，因为无葡萄可摘，也无果实可收。","notes":[]},{"n":11,"t":"安逸的妇女啊，要战兢；无虑的女子啊，要颤栗，要脱去衣服，赤着身体，腰束麻布。","notes":[]},{"n":12,"t":"你们要为美好的田地和多结果子的葡萄树捶胸哀哭。","notes":[]},{"n":13,"t":"刺草和荆棘要长在我百姓的田地上，长在欢乐城中一切快乐家园上。","notes":[]},{"n":14,"t":"宫殿必被撇下，繁华的城必被抛弃，堡垒和瞭望楼永为洞穴，成为野驴的乐土，羊群的草场。","notes":[]},{"n":15,"t":"等到圣灵从高处浇灌我们，旷野将变为田园，田园看似森林。","notes":[]},{"n":16,"t":"公平要居住在旷野，公义要安歇在田园。","notes":[]},{"n":17,"t":"公义的果实是平安，公义的效果是平静和安稳，直到永远。","notes":[]},{"n":18,"t":"我的百姓要住在平安的居所，安稳的住处，宁静的安歇之地。","notes":[]},{"n":19,"t":"虽有冰雹击倒树林，城也夷为平地；","notes":[]},{"n":20,"t":"然而你们在水边撒种，牧放牛驴的有福了！","notes":[]}]},"33":{"heading":"求救的祈祷","verses":[{"n":1,"t":"祸哉！你这未遭毁灭而毁灭人的人，人未以诡诈待你而你以诡诈待人的人！等你行完了毁灭，自己必被毁灭；你行完了诡诈，人必以诡诈待你。","notes":[]},{"n":2,"t":"耶和华啊，求你施恩给我们，我们等候你。求你每早晨作我们的膀臂，遭难时作我们的拯救。","notes":[]},{"n":3,"t":"轰然之声一发出，万民就奔逃；你一兴起，列国就四散。","notes":["“兴起”：死海古卷是“安静”或“吼叫”。"]},{"n":4,"t":"你们的掳物必被敛尽，有如蚂蚱敛尽禾稼；人为掳物奔走，宛如蝗虫蹦跳。","notes":[]},{"n":5,"t":"耶和华受尊崇，居高处，使公平和公义充满锡安。","notes":[]},{"n":6,"t":"他是你这世代安定的力量，丰盛的救恩、智慧和知识；敬畏耶和华是锡安的至宝。","notes":[]},{"n":7,"t":"看哪，他们的英雄在外面哀号，求和的使臣在痛哭。","notes":["“看哪...哀号”：有古卷是“我看见他们，他们在外面哀号”；原文另译“亚利伊勒（参赛29．1）在外面哀号”。"]},{"n":8,"t":"大路荒凉，行人止息；盟约撕毁，见证被弃，人也不受尊重。","notes":["“见证”是根据死海古卷；原文是“城镇”。"]},{"n":9,"t":"大地悲哀衰残，黎巴嫩羞愧且枯干，沙仑好像旷野，巴珊和迦密必凋残。","notes":[]},{"n":10,"t":"耶和华说：“现在我要兴起，要高升，要受尊崇。","notes":[],"heads":["耶和华对敌人的警告"]},{"n":11,"t":"你们怀的是糠秕，生的是碎秸；你们的气息如火吞灭自己。","notes":[]},{"n":12,"t":"万民必像烧着的石灰，又如斩断的荆棘，在火里燃烧。”","notes":[]},{"n":13,"t":"你们远方的人，当听我所做的事；你们近处的人，当承认我的大能。","notes":[]},{"n":14,"t":"锡安的罪人都惧怕，战兢抓住不敬虔的人。我们中间有谁能与吞噬的火同住？我们中间有谁能与不灭的火共存呢？","notes":[]},{"n":15,"t":"那行事公义、说话正直、憎恶欺压所得之财、摇手不受贿赂、掩耳不听流血的计谋、闭眼不看邪恶之事的，","notes":[]},{"n":16,"t":"这人必居高处，他的保障是磐石的堡垒，必有粮食赐给他，饮水也不致断绝。","notes":[]},{"n":17,"t":"你必亲眼看见君王的荣美，看见辽阔之地。","notes":[],"heads":["光荣的将来"]},{"n":18,"t":"你的心必回想那些恐怖的事：“那数算的人在哪里？秤重的人在哪里？数点城楼的又在哪里呢？”","notes":[]},{"n":19,"t":"你必不再看见那凶暴的民，他们嘴唇说艰涩的言语，难以理解；舌头结巴，说无意义的话。","notes":[]},{"n":20,"t":"你要注视锡安，我们守圣节的城！你必亲眼看见耶路撒冷成为安静的居所，成为不挪移的帐幕，橛子永不拔出，绳索一根也不折断。","notes":[]},{"n":21,"t":"在那里，威严的耶和华对我们是宽阔的江河，其中必没有摇桨的小船来往，也没有巨大的船舶经过。","notes":[]},{"n":22,"t":"耶和华是审判我们的，耶和华为我们设立律法；耶和华是我们的君王，他必拯救我们。","notes":[]},{"n":23,"t":"船上的绳索松开，不能稳住桅杆，也无法扬起船帆。那时许多掳物被瓜分，连瘸腿的也能夺走掠物。","notes":[]},{"n":24,"t":"城内的居民无人说：“我病了”；城里居住的百姓，罪孽都蒙赦免。","notes":[]}]},"34":{"heading":"神要惩罚仇敌","verses":[{"n":1,"t":"列国啊，要近前来听！万民哪，要侧耳而听！全地和其上所充满的，世界和其中所出的，都应当听！","notes":[]},{"n":2,"t":"因为耶和华向列国发怒，向他们的全军发烈怒，要将他们灭尽，任人杀戮。","notes":[]},{"n":3,"t":"被杀的人必被抛弃，尸首臭气上腾，诸山为他们的血所融化。","notes":[]},{"n":4,"t":"天上万象都要朽坏，天被卷起，有如书卷，其上的万象尽都衰残；如葡萄树的叶子凋落，又如无花果树枯萎一样。","notes":[]},{"n":5,"t":"因为我的刀在天上将要显现；看哪，这刀临到以东和我所诅咒的民，要施行审判。","notes":["“将要显现”是根据死海古卷；原文是“已经喝足”。"]},{"n":6,"t":"耶和华的刀沾满了血，是用油脂和羔羊、公山羊的血，并公绵羊肾上的油脂滋润的；因为在波斯拉有祭物献给耶和华，在以东地有大屠杀。","notes":[]},{"n":7,"t":"野牛与他们一起倒下，牛犊和壮牛也一同倒下。他们的地被血染遍，他们的尘土因油脂肥润。","notes":[]},{"n":8,"t":"这是耶和华报仇之日，为锡安伸冤的报应之年。","notes":[]},{"n":9,"t":"它的河水要变为柏油，尘埃变为硫磺，大地成为燃烧的柏油，","notes":[]},{"n":10,"t":"昼夜总不熄灭，它的烟永远上腾，必世世代代成为荒废，永永远远无人经过。","notes":[]},{"n":11,"t":"鹈鹕、豪猪要得它为业，猫头鹰、乌鸦要住在其间。耶和华必将空虚的准绳、混沌的石垂线，拉在以东之上。","notes":[]},{"n":12,"t":"人必宣称那里没有王国，它的贵族和所有领袖都归于无有。","notes":[]},{"n":13,"t":"以东的宫殿要长出荆棘，城堡要生长蒺藜和刺草；成为野狗的住处，鸵鸟的居所。","notes":[]},{"n":14,"t":"野兽要和土狼相遇，山羊鬼魔要与同伴对唱，莉莉丝必在那里栖身，为自己寻找安歇之处。","notes":["“莉莉丝”是音译，中东的雌性鬼怪；或译“夜间的怪物”。"]},{"n":15,"t":"箭头蛇要在那里做窝，下蛋，孵蛋，并招聚幼蛇在其保护之下；鹞鹰也与伴侣聚集在那里。","notes":[]},{"n":16,"t":"你们要查考并诵读耶和华的书；这些现象必然存在，没有一样动物缺少伴侣。因为是他，藉着我的口吩咐，他的灵将它们聚集。","notes":["“我的口”：死海古卷是“他的口”。"]},{"n":17,"t":"他为它们抽签，亲手用准绳为它们分地；直到它们永远得地为业，世世代代住在其间。","notes":[]}]},"35":{"heading":"神圣之路","verses":[{"n":1,"t":"旷野和干旱之地必然欢喜，沙漠也必快乐；又如玫瑰绽放，","notes":[]},{"n":2,"t":"朵朵繁茂，其乐融融，而且欢呼。黎巴嫩的荣耀，并迦密与沙仑的华美，必赐给它。人要看见耶和华的荣耀，看见我们神的荣美。","notes":[]},{"n":3,"t":"你们要使软弱的手强壮，使无力的膝盖稳固；","notes":[]},{"n":4,"t":"对心里焦急的人说：“要刚强，不要惧怕。看哪，你们的神要来施报，要施行极大的报应，他必来拯救你们。”","notes":[]},{"n":5,"t":"那时，盲人的眼必睁开，聋子的耳必开通。","notes":[]},{"n":6,"t":"那时，瘸子必跳跃如鹿，哑巴的舌头必欢呼。在旷野有水喷出，在沙漠有江河涌流。","notes":[]},{"n":7,"t":"火热之地要变为水池，干渴之地要变为泉源。野狗躺卧休息之处必长出青草、芦苇和蒲草。","notes":[]},{"n":8,"t":"在那里必有一条大道，就是一条路，称为圣路。污秽的人不得经过，是专为走路的人预备的，愚昧的人也不会迷路。","notes":["死海古卷没有“就是一条路”。","“走路的人”或译“赎民”。"]},{"n":9,"t":"在那里没有狮子，猛兽也不经过；在那里它们未现踪迹，只有救赎的民在那里行走。","notes":[]},{"n":10,"t":"耶和华救赎的民必归回，歌唱来到锡安；永远的快乐必归到他们头上，他们必得着欢喜快乐，忧伤叹息尽都逃避。","notes":[]}]},"36":{"heading":"亚述人威胁耶路撒冷","verses":[{"n":1,"t":"希西家王十四年，亚述王西拿基立上来攻击犹大的一切坚固的城，将城攻取。","notes":[]},{"n":2,"t":"亚述王从拉吉差遣将军率领大军前往耶路撒冷，到希西家王那里去。将军站在上池的水沟旁，在往漂布地的大路上。","notes":["“将军”：原文是亚述的官职“拉伯．沙基”，司令官；下同。"]},{"n":3,"t":"希勒家的儿子以利亚敬宫廷总管、舍伯那书记和亚萨的儿子约亚史官，出来见他。","notes":[]},{"n":4,"t":"将军对他们说：“你们去告诉希西家，大王亚述王如此说：‘你倚赖什么，让你如此自信满满？","notes":[]},{"n":5,"t":"我说，你有打仗的计谋和能力，我看不过是空话。你到底倚靠谁，竟敢背叛我呢？","notes":["“我说”：有古卷是“你说”。"]},{"n":6,"t":"看哪，你所倚靠的埃及是那断裂的苇杖，人若倚靠这杖，它就刺进他的手，穿透它。埃及王法老向所有倚靠他的人都是这样。","notes":[]},{"n":7,"t":"你若对我说：我们倚靠耶和华－我们的神，希西家岂不是将神的丘坛和祭坛废去，并且吩咐犹大和耶路撒冷的人说：你们只当在这一个坛前敬拜吗？","notes":[]},{"n":8,"t":"现在你与我主亚述王打赌，我给你两千匹马，看你能否派得出骑士来骑它们。","notes":[]},{"n":9,"t":"若不然，怎能使我主臣仆中最小的一个军官转脸而逃呢？你难道要倚靠埃及的战车和骑兵吗？","notes":[]},{"n":10,"t":"现在我上来攻击毁灭这地，岂不是出于耶和华吗？耶和华吩咐我说，你上去攻击这地，毁灭它吧！’”","notes":[]},{"n":11,"t":"以利亚敬、舍伯那、约亚对将军说：“求你用亚兰话对仆人说，因为我们听得懂；不要用犹大话对我们说，免得传到城墙上百姓的耳中。”","notes":[]},{"n":12,"t":"将军说：“我主差遣我来，岂是单对你和你的主人说这些话吗？不也是对这些坐在城墙上，要与你们一同吃自己粪、喝自己尿的人说的吗？”","notes":[]},{"n":13,"t":"于是亚述将军站着，用犹大话大声喊着说：“你们当听大王亚述王的话，","notes":[]},{"n":14,"t":"王如此说：‘你们不要被希西家欺哄了，因他不能拯救你们。","notes":[]},{"n":15,"t":"不要听凭希西家说服你们倚靠耶和华，他说，耶和华必要拯救我们，这城必不交在亚述王的手中。’","notes":[]},{"n":16,"t":"你们不要听希西家的话！因亚述王如此说：‘你们要与我讲和，出来投降，各人就可以吃自己葡萄树和无花果树的果子，喝自己井里的水，","notes":[]},{"n":17,"t":"等我来领你们到一个地方，与你们本地一样，就是有五谷和新酒之地，有粮食和葡萄园之地。","notes":[]},{"n":18,"t":"恐怕希西家误导你们说，耶和华必拯救我们。列国的神明有哪一个曾救它本国脱离亚述王的手呢？","notes":[]},{"n":19,"t":"哈马和亚珥拔的神明在哪里呢？西法瓦音的神明在哪里呢？它们曾救撒玛利亚脱离我的手吗？","notes":[]},{"n":20,"t":"这些国的神明有谁曾救自己的国家脱离我的手呢？难道耶和华能救耶路撒冷脱离我的手吗？’”","notes":[]},{"n":21,"t":"百姓静默不言，一句不答，因为希西家王曾吩咐说：“不要回答他。”","notes":[]},{"n":22,"t":"当下希勒家的儿子以利亚敬宫廷总管、舍伯那书记，和亚萨的儿子约亚史官都撕裂衣服，来到希西家那里，将亚述将军的话告诉他。","notes":[]}]},"37":{"heading":"国王差人征求以赛亚的意见","verses":[{"n":1,"t":"希西家王听见了，就撕裂衣服，披上麻衣，进了耶和华的殿。","notes":[]},{"n":2,"t":"他差遣以利亚敬宫廷总管和舍伯那书记，并祭司中年长的，都披上麻衣，到亚摩斯的儿子以赛亚先知那里去。","notes":[]},{"n":3,"t":"他们对他说：“希西家如此说：‘今日是急难、惩罚、凌辱的日子，就如婴孩快要出生，却没有力气生产。","notes":[]},{"n":4,"t":"或许耶和华－你的神听见亚述将军的话，就是他主人亚述王差他来辱骂永生神的话，耶和华－你的神就斥责所听见的这些话。求你为幸存的余民扬声祷告。’”","notes":[]},{"n":5,"t":"希西家王的臣仆就来到以赛亚那里。","notes":[]},{"n":6,"t":"以赛亚对他们说：“要对你们的主人这样说，耶和华如此说：‘你听见亚述王的仆人亵渎我的话，不要惧怕。","notes":[]},{"n":7,"t":"看哪，因为我必惊动他的心，他要听见风声就归回本地，在那里我必使他倒在刀下。’”","notes":["“惊动他的心”：原文是“使灵进入他里面”。"]},{"n":8,"t":"亚述将军听见亚述王已拔营离开拉吉，就启程返回，正遇见亚述王去攻打立拿。","notes":[],"heads":["亚述王再来威胁"]},{"n":9,"t":"亚述王听见有人谈论古实王特哈加说：“他出来要与你争战。”亚述王一听见，就差使者去见希西家，说：","notes":[]},{"n":10,"t":"“你们要对犹大王希西家如此说：‘不要听你所倚靠的神欺哄你说：耶路撒冷必不交在亚述王的手中。","notes":[]},{"n":11,"t":"看哪，你总听说亚述诸王向列国所行的是尽行灭绝，难道你能幸免吗？","notes":[]},{"n":12,"t":"我祖先所毁灭的，就是歌散、哈兰、利色和提．拉撒的伊甸人；这些国的神明何曾拯救他们呢？","notes":[]},{"n":13,"t":"哈马的王，亚珥拔的王，西法瓦音城的王，希拿和以瓦的王，都在哪里呢？’”","notes":[]},{"n":14,"t":"希西家从使者手里接过书信，看完了，就上耶和华的殿，在耶和华面前展开书信。","notes":[]},{"n":15,"t":"希西家向耶和华祷告说：","notes":[]},{"n":16,"t":"“坐在基路伯之上万军之耶和华－以色列的神啊，你，惟有你是地上万国的神，你创造了天和地。","notes":[]},{"n":17,"t":"耶和华啊，求你侧耳而听；耶和华啊，求你睁眼而看，听西拿基立差遣使者辱骂永生神的一切话。","notes":[]},{"n":18,"t":"耶和华啊，亚述诸王果然使列国和列国之地变为荒芜，","notes":[]},{"n":19,"t":"将列国的神明扔在火里，因为它们本不是神明，是人手所造的，是木头、石头，所以被灭绝了。","notes":[]},{"n":20,"t":"耶和华－我们的神啊，现在求你救我们脱离亚述王的手，使地上万国都知道惟有你是耶和华。”","notes":[]},{"n":21,"t":"亚摩斯的儿子以赛亚就差人去见希西家，说：“耶和华－以色列的神如此说，你因亚述王西拿基立的事向我祈求，","notes":[],"heads":["以赛亚给王的信息"]},{"n":22,"t":"所以耶和华论他这样说：‘少女锡安藐视你，嘲笑你；耶路撒冷向你摇头。","notes":["“少女锡安”：原文直译“少女锡安女子”。","“耶路撒冷”：原文直译“ 耶路撒冷女子”。"]},{"n":23,"t":"“‘你辱骂谁，亵渎谁，扬起声来，高举眼目攻击谁呢？你攻击的是以色列的圣者。","notes":[]},{"n":24,"t":"你藉臣仆辱骂主说：我率领许多战车登上高山，到黎巴嫩的顶端；我要砍伐其中高大的香柏树和上好的松树。我必上到极高之处，进入茂盛的森林里。","notes":[]},{"n":25,"t":"我已经挖井喝水；我必用脚掌踏干埃及一切的河流。","notes":["“挖井喝水”：死海古卷是“在外邦挖井喝水”；参王下19．24。"]},{"n":26,"t":"“‘你岂没有听见我早先所定、古时所立、现今实现的事吗？就是让你去毁坏坚固的城，使它们变为废墟；","notes":[]},{"n":27,"t":"城里居民的力量甚小，他们惊惶羞愧；像野草，像青菜，如房顶上的草，被东风刮散。","notes":["“被东风刮散”是根据死海古卷； 原文是“又如田间未长成的禾稼”，并且没有下节的“你站起”。"]},{"n":28,"t":"“‘你站起，你坐下，你出去，你进来，你向我发烈怒，我都知道。","notes":[]},{"n":29,"t":"因你向我发烈怒，你的狂傲上达我耳中，我要用钩子钩住你的鼻子，将嚼环放在你口里，使你从原路转回去。’","notes":[]},{"n":30,"t":"“我赐给你的预兆：你们今年要吃野生的，明年也要吃自长的；后年，你们就要耕种收割，栽葡萄园，吃其中的果子。","notes":[]},{"n":31,"t":"犹大家所逃脱剩余的，仍要往下扎根，向上结果。","notes":[]},{"n":32,"t":"必有剩余的民从耶路撒冷而出；有逃脱的人从锡安山而来。万军之耶和华的热心必成就这事。","notes":[]},{"n":33,"t":"“所以耶和华论亚述王如此说：他必不得来到这城，也不在这里射箭，不得拿盾牌到城前，也不能建土堆攻城。","notes":[]},{"n":34,"t":"他从哪条路来，必从那条路回去，必不得来到这城。这是耶和华说的。","notes":[]},{"n":35,"t":"因我为自己的缘故，又为我仆人大卫的缘故，必保护拯救这城。”","notes":[]},{"n":36,"t":"耶和华的使者出去，在亚述营中杀了十八万五千人。清早有人起来，看哪，都是死尸。","notes":[]},{"n":37,"t":"亚述王西拿基立就拔营回去，住在尼尼微。","notes":[]},{"n":38,"t":"一日，他在他的神明尼斯洛庙里叩拜，他儿子亚得米勒和沙利色用刀杀了他，然后逃到亚拉腊地；他儿子以撒．哈顿接续他作王。","notes":[]}]},"38":{"heading":"希西家王罹病和痊愈","verses":[{"n":1,"t":"那些日子，希西家病得要死，亚摩斯的儿子以赛亚先知来见他，对他说：“耶和华如此说：‘你当留遗嘱给你的家，因为你必死，不能活了。’”","notes":[]},{"n":2,"t":"希西家就转脸朝墙，向耶和华祷告，","notes":[]},{"n":3,"t":"说：“耶和华啊，求你记念我在你面前怎样存完全的心，按诚实行事，又做你眼中看为善的事。”希西家就痛哭。","notes":[]},{"n":4,"t":"耶和华的话临到以赛亚说：","notes":[]},{"n":5,"t":"“你去告诉希西家说，耶和华－你祖先大卫的神如此说：‘我听见了你的祷告，看见了你的眼泪。看哪，我必加添你十五年的寿数；","notes":[]},{"n":6,"t":"我要救你和这城脱离亚述王的手，也要保护这城。’","notes":[]},{"n":7,"t":"“耶和华必成就他所说的这话。这是耶和华给你的预兆：","notes":[]},{"n":8,"t":"看哪，我要使亚哈斯日晷上随太阳前进的影子，往后退十度。”于是，在日晷上照下来的日影果然往后退了十度。","notes":[]},{"n":9,"t":"犹大王希西家患病痊愈后的诗：","notes":[]},{"n":10,"t":"我说，在如日中天的时候我就走了，将剩余的年岁交给阴间的门。","notes":["本节或译“我说，在如日中天的时候，我必进入阴间的门，不得享受剩余的年岁。”"]},{"n":11,"t":"我说，我必不得见耶和华，不得在活人之地见耶和华，也不再看见世人，就是短暂世界中的居民。","notes":["“短暂世界”：有古卷是“世界”。"]},{"n":12,"t":"我的住处好像牧人的帐棚，遭人掀起，离我而去；我将性命卷起，像织布的卷布一样。他从织布机头那里将我剪断，你使我命丧于旦夕。","notes":[]},{"n":13,"t":"我令自己安静直到天亮；他像狮子折断我所有的骨头，你使我命丧于旦夕。","notes":["“我令自己安静”：死海古卷是“我被压碎”；七十士译本是“我被放弃”。"]},{"n":14,"t":"我像燕子呢喃，像白鹤鸣叫，又如鸽子哀鸣；我因仰望，眼睛困倦。主啊，我受欺压，求你为我作保。","notes":[]},{"n":15,"t":"我还有什么可说的呢？他应许我的，他已成就了。我因心里的苦楚，在一生的年日必谦卑而行。","notes":["“他应许我的”：死海古卷是“我对他说的”。","“在一生的年日必谦卑而行”：死海古卷是“我的睡眠溜走了”。"]},{"n":16,"t":"主啊，人得存活是在乎此，我的灵存活也全在乎此；求你使我痊愈，仍然存活。","notes":["“我的灵...在乎此”：死海古卷是“万物的存活都因他的灵”。"]},{"n":17,"t":"看哪，我受大苦是为使我得平安；你爱我，救我的性命脱离败坏的地府，将我一切的罪扔在你背后。","notes":[]},{"n":18,"t":"原来，阴间不能称谢你，死亡不能颂扬你，下到地府的人也不能盼望你的信实。","notes":[]},{"n":19,"t":"只有活人，活人必称谢你，像我今日称谢你一样。为父的，必使儿女知道你的信实。","notes":[]},{"n":20,"t":"耶和华肯救我，所以，我们要一生一世在耶和华殿中弹奏我弦乐的歌。","notes":[]},{"n":21,"t":"以赛亚说：“拿一块无花果饼来，贴在疮上，王必痊愈。”","notes":[]},{"n":22,"t":"希西家说：“我能上耶和华的殿，有什么预兆呢？”","notes":["死海古卷没有 21、22 节。"]}]},"39":{"heading":"巴比伦王的使节","verses":[{"n":1,"t":"那时，巴拉但的儿子，巴比伦王米罗达．巴拉但听见希西家病得痊愈，就送书信和礼物给他。","notes":[]},{"n":2,"t":"希西家欢喜见使者，就将自己宝库里的金子、银子、香料、贵重的膏油和他军械库里一切的兵器，以及他所有的财宝，都给他们看；在他家中和全国之内，希西家没有一样不给他们看的。","notes":[]},{"n":3,"t":"于是以赛亚先知到希西家王那里去，对他说：“这些人说了些什么？他们从哪里来见你？”希西家说：“他们从远方的巴比伦来见我。”","notes":[]},{"n":4,"t":"以赛亚说：“他们在你家里看见了什么？”希西家说：“凡我家中所有的，他们都看见了；我财宝中没有一样东西不给他们看的。”","notes":[]},{"n":5,"t":"以赛亚对希西家说：“你要听万军之耶和华的话，","notes":[]},{"n":6,"t":"耶和华说：‘看哪，日子将到，凡你家里所有的，并你祖先积蓄到如今的一切，都要被掳到巴比伦去，不留下一样；","notes":[]},{"n":7,"t":"从你本身所生的孩子，其中必有被掳到巴比伦王宫当太监的。’”","notes":[]},{"n":8,"t":"希西家对以赛亚说：“你所说耶和华的话甚好。”因为他想：“在我有生之年必有太平和安稳。”","notes":[]}]},"40":{"heading":"安慰的话","verses":[{"n":1,"t":"你们的神说：“要安慰，安慰我的百姓。","notes":[]},{"n":2,"t":"要对耶路撒冷说安慰的话，向它宣告，它的战争已结束，它的罪孽已赦免；它为自己一切的罪，已从耶和华手中加倍受罚。”","notes":[]},{"n":3,"t":"有声音呼喊着：“要在旷野为耶和华预备道路，在沙漠为我们的神修直大道。","notes":[]},{"n":4,"t":"一切山洼都要填满，大小山冈都要削平；陡峭的要变为平坦，崎岖的必成为平原。","notes":[]},{"n":5,"t":"耶和华的荣耀必然显现，凡有血肉之躯的都一同看见，因为这是耶和华亲口说的。”","notes":[]},{"n":6,"t":"有声音说：“你喊叫吧！”我说：“我喊叫什么呢？”凡有血肉之躯的尽都如草，他的一切荣美像野地的花。","notes":["“我”是根据死海古卷和七十士译本；原文是“他”。"]},{"n":7,"t":"耶和华吹一口气，草就枯干，花也凋谢。百姓诚然是草；","notes":[]},{"n":8,"t":"草必枯干，花必凋谢，惟有我们神的话永远立定。","notes":[]},{"n":9,"t":"报好信息的锡安哪，要登高山；报好信息的耶路撒冷啊，要极力扬声。扬声不要惧怕，对犹大的城镇说：“看哪，你们的神！”","notes":[]},{"n":10,"t":"看哪，主耶和华必以大能临到，他的膀臂必为他掌权；看哪，他的赏赐在他那里，他的报应在他面前。","notes":[]},{"n":11,"t":"他要像牧人牧养自己的羊群，用膀臂聚集羔羊，抱在胸怀，慢慢引导那乳养小羊的。","notes":[]},{"n":12,"t":"谁曾用手心量诸水，用手虎口量苍天，用升斗盛大地的尘土，用秤称山岭，用天平称冈陵呢？","notes":[],"heads":["以色列的神无可比拟"]},{"n":13,"t":"谁曾测度耶和华的灵，或作他的谋士指教他呢？","notes":[]},{"n":14,"t":"他与谁商议，谁教导他，以公平的路指示他，将知识传授与他，又将通达的道指教他呢？","notes":[]},{"n":15,"t":"看哪，列国都像水桶里的一滴，又如天平上的微尘；看哪，他举起众海岛，好像举起极微小之物。","notes":[]},{"n":16,"t":"黎巴嫩不够当柴烧，其中的走兽也不够作燔祭。","notes":[]},{"n":17,"t":"列国在他面前如同不存在，在他看来微不足道，只是虚空。","notes":[]},{"n":18,"t":"你们究竟将谁比神，用什么形像与他相较呢？","notes":[]},{"n":19,"t":"至于偶像，匠人铸造它，银匠用金子包裹它，又为它铸造银链。","notes":[]},{"n":20,"t":"没有能力捐献的人，就挑选不易朽坏的木头，为自己寻找巧匠，竖立不会倒的偶像。","notes":[]},{"n":21,"t":"你们岂不知道吗？岂未曾听见吗？难道没有人从起头就告诉你们吗？自从地的根基立定，你们岂不明白吗？","notes":[]},{"n":22,"t":"神坐在地的穹窿之上，地上的居民有如蚱蜢。他铺张穹苍如幔子，展开诸天如可住的帐棚。","notes":[]},{"n":23,"t":"他使君王归于虚无，使地上的审判官成为虚空。","notes":[]},{"n":24,"t":"他们刚栽上，刚种好，根也刚扎在地里，经他一吹，就都枯干；旋风将他们吹去，像碎秸一样。","notes":[]},{"n":25,"t":"那圣者说：“你们将谁与我相比，与我相等呢？”","notes":[]},{"n":26,"t":"你们要向上举目，看是谁创造这万象，按数目领出它们，一一称其名，以他的权能和他的大能大力，使它们一个都不缺。","notes":[]},{"n":27,"t":"雅各啊，你为何说，以色列啊，你为何言，“我的道路向耶和华隐藏，我的冤屈神并不查问”？","notes":[]},{"n":28,"t":"你岂不曾知道吗？你岂未曾听见吗？永在的神耶和华，创造地极的主，他不疲乏，也不困倦；他的智慧无法测度。","notes":[]},{"n":29,"t":"疲乏的，他赐能力；软弱的，他加力量。","notes":[]},{"n":30,"t":"就是年轻人也要疲乏困倦，强壮的也必全然跌倒。","notes":[]},{"n":31,"t":"但那等候耶和华的必重新得力。他们必如鹰展翅上腾；他们奔跑却不困倦，行走却不疲乏。","notes":[]}]},"41":{"heading":"神对以色列的保证","verses":[{"n":1,"t":"众海岛啊，在我面前静默；万民要重新得力，让他们近前来陈述，我们可以彼此辩论。","notes":[]},{"n":2,"t":"谁从东方兴起一人，凭公义召他来到脚前？谁将列国交给他，使他管辖列王，把他们如灰尘交与他的刀，如风吹的碎秸交与他的弓？","notes":[]},{"n":3,"t":"他追赶君王，安然走过，快速地脚不落地。","notes":["“快速地脚不落地”：死海古卷是“他们不认识脚所走的路”；七十士译本是“他们脚所走的路”。"]},{"n":4,"t":"谁做成这事，从起初宣召历代呢？就是我－耶和华！我是首先的，也与末后的同在。","notes":[]},{"n":5,"t":"众海岛看见就都害怕，地极也都战兢，他们近前来；","notes":[]},{"n":6,"t":"各人互相帮助，对弟兄说：“壮胆吧！”","notes":[]},{"n":7,"t":"木匠鼓励银匠，用锤子打光的鼓励打砧的，对焊工说：“焊得好！”又用钉子钉稳，免得它倒下。","notes":[]},{"n":8,"t":"惟你以色列，我的仆人，雅各，我所拣选的，我朋友亚伯拉罕的后裔，","notes":[]},{"n":9,"t":"你是我从地极领来，从地角召来的，我对你说：“你是我的仆人；我拣选你，并不弃绝你。”","notes":[]},{"n":10,"t":"你不要害怕，因为我与你同在；不要惊惶，因为我是你的神。我必坚固你，帮助你，用我公义的右手扶持你。","notes":[]},{"n":11,"t":"看哪，凡向你发怒的都抱愧蒙羞，与你相争的必如无有，并要灭亡。","notes":[]},{"n":12,"t":"与你争斗的，你要寻找他们，却遍寻不着；与你争战的必如无有，成为虚无。","notes":[]},{"n":13,"t":"因为我耶和华－你的神必搀扶你的右手，对你说：“不要害怕！我必帮助你。”","notes":[]},{"n":14,"t":"虫子雅各，以色列人哪，不要害怕！我必帮助你；救赎你的是以色列的圣者。这是耶和华说的。","notes":[]},{"n":15,"t":"看哪，我使你成为全新的打谷机，齿轮锐利；你要把山岭打得粉碎，使冈陵如同糠秕。","notes":[]},{"n":16,"t":"你要簸扬它们，风要将它们吹去；旋风要刮散它们。你却要以耶和华为喜乐，因以色列的圣者夸耀。","notes":[]},{"n":17,"t":"困苦贫穷人寻找水，却寻不着；他们因口渴，舌头干燥。我－耶和华必应允他们，我─以色列的神必不离弃他们。","notes":[]},{"n":18,"t":"我要在光秃的高地开江河，在谷中开泉源；我要使沙漠变为水池，使干地变为涌泉。","notes":[]},{"n":19,"t":"我要在旷野栽植香柏树、皂荚树、番石榴树，和野橄榄树。在沙漠一同栽上松树、杉树，和黄杨树，","notes":[]},{"n":20,"t":"好叫人看见，知道，思想，明白；这是耶和华亲手做的，是以色列的圣者所造的。","notes":[]},{"n":21,"t":"耶和华说：“你们要呈上你们的案件。”雅各的君王说：“你们要提出你们的理由。”","notes":[],"heads":["耶和华向偶像挑战"]},{"n":22,"t":"让它们近前来，告诉我们将来要发生什么事！你们要说明先前发生的事，好让我们思索；或者告诉我们将来的事，使我们得知事情的结局。","notes":[]},{"n":23,"t":"你们要指明未来的事，使我们知道你们是神明！你们或降福，或降祸，好使我们惊奇，一同观看。","notes":[]},{"n":24,"t":"看哪，你们属乎虚无，你们的作为也属虚空；那选择你们的是可憎恶的。","notes":[]},{"n":25,"t":"我从北方兴起一人，他从日出之地而来，是求告我名的；他必踩踏掌权者，如踩踏泥土，又如陶匠踹泥一般。","notes":["“踩踏”：原文是“临到”；下同。"]},{"n":26,"t":"有谁从起初宣布这事，使我们知道呢？有谁从先前指明，使我们说“他是对的”呢？没有人宣布，没有人指明，也没有人听见你们的话。","notes":[]},{"n":27,"t":"我首先对锡安说，看哪，他们在此！我要将一位报好信息的赐给耶路撒冷。","notes":[]},{"n":28,"t":"然而我观看，并无一人；我询问的时候，他们中间也没有谋士可回答。","notes":[]},{"n":29,"t":"看哪，他们尽是麻烦，所做的工都属虚无；所铸的偶像是风，是虚空。","notes":["“麻烦”：死海古卷和一些译本是“虚空”。"]}]},"42":{"heading":"耶和华的仆人","verses":[{"n":1,"t":"看哪，我的仆人，我所扶持、所拣选、心里所喜悦的！我已将我的灵赐给他，他必将公理传给万邦。","notes":[]},{"n":2,"t":"他不喧嚷，不扬声，也不使街上听见他的声音。","notes":[]},{"n":3,"t":"压伤的芦苇，他不折断；将残的灯火，他不吹灭。他凭信实将公理传开。","notes":[]},{"n":4,"t":"他不灰心，也不丧胆，直到他在地上设立公理；众海岛都等候他的训诲。","notes":[]},{"n":5,"t":"那创造诸天，铺张穹苍，铺开地与地的出产，赐气息给地上众人，赐生命给行走其上之人的神耶和华如此说：","notes":[]},{"n":6,"t":"“我－耶和华凭公义召你，要搀扶你的手，保护你，要藉着你与百姓立约，使你成为万邦之光，","notes":[]},{"n":7,"t":"开盲人的眼，领囚犯出监狱，领坐在黑暗中的出地牢。","notes":[]},{"n":8,"t":"我是耶和华，这是我的名；我必不将我的荣耀归给别神，也不将我所得的颂赞归给雕刻的偶像。","notes":["“别神”：原文是“别的”。"]},{"n":9,"t":"看哪，先前的事已经成就，现在我要指明新事，告诉你们尚未发生的事。","notes":[]},{"n":10,"t":"航海的人和海中一切所有的，众海岛和其中的居民，都当向耶和华唱新歌，从地极赞美他。","notes":[],"heads":["颂赞之歌"]},{"n":11,"t":"旷野和其中的城镇，并基达人居住的村庄都当扬声；西拉的居民当欢呼，在山顶上大声呼喊。","notes":["“扬声”：七十士译本是“欢乐”。"]},{"n":12,"t":"愿他们将荣耀归给耶和华，在海岛中传扬颂赞他的话。","notes":[]},{"n":13,"t":"耶和华必如勇士出征，如战士激起愤恨，他要喊叫，大声呐喊，击败他的敌人。","notes":[]},{"n":14,"t":"我许久闭口不言，沉默不语；现在我要像临产的妇人，大声喊叫，呼吸急促而喘气。","notes":[],"heads":["神应许帮助他的子民"]},{"n":15,"t":"我要使大小山冈变为荒芜，使其上的花草都枯干；我要使江河变为沙洲，使水池尽都干涸。","notes":[]},{"n":16,"t":"我要引导盲人行他们所不认识的道，引领他们走他们未曾走过的路；我在他们面前使黑暗变为光明，使弯曲变为平直。这些事我都要做，并不离弃他们。","notes":[]},{"n":17,"t":"但那倚靠雕刻的偶像，对铸造的偶像说：“你是我们的神明”；这种人要退后，大大蒙羞。","notes":[]},{"n":18,"t":"你们这耳聋的，听吧！你们这眼瞎的，看吧，使你们得以看见！","notes":[],"heads":["以色列人不受教诲"]},{"n":19,"t":"谁比我的仆人眼瞎呢？谁比我所差遣的使者耳聋呢？谁瞎眼像那献身给我的人？谁瞎眼像耶和华的仆人呢？","notes":["“瞎眼”：有古卷是“耳聋”。"]},{"n":20,"t":"看见许多事却不领会，耳朵开通却听不见。","notes":[]},{"n":21,"t":"耶和华因自己的公义，乐意使律法为大为尊。","notes":[]},{"n":22,"t":"但这百姓是被抢被夺的，全都陷在洞穴中，关在监牢里；他们成了掠物，无人拯救，成了掳物，无人索还。","notes":[]},{"n":23,"t":"你们中间谁肯侧耳听这话，谁肯留心听，以防将来呢？","notes":[]},{"n":24,"t":"谁将雅各交出作为掳物，将以色列交给抢夺者呢？岂不是耶和华─我们所得罪的那位吗？他们不肯遵行他的道，也不听从他的训诲。","notes":[]},{"n":25,"t":"所以，他将猛烈的怒气和战争的威力倾倒在以色列身上；在他周围如火燃起，他竟然不知，烧着了，他也不在意。","notes":[]}]},"43":{"heading":"神应许拯救他的子民","verses":[{"n":1,"t":"雅各啊，创造你的耶和华，以色列啊，造成你的那位，现在如此说：“你不要害怕，因为我救赎了你；我曾提你的名召你，你是属我的。","notes":[]},{"n":2,"t":"你从水中经过，我必与你同在，你渡过江河，水必不漫过你；你在火中行走，也不被烧伤，火焰必不烧着你身。","notes":[]},{"n":3,"t":"因为我是耶和华－你的神，是以色列的圣者－你的救主；我使埃及作你的赎价，使古实和西巴代替你。","notes":[]},{"n":4,"t":"因我看你为宝贝为尊贵；又因我爱你，所以使人代替你，使万民替换你的生命。","notes":[]},{"n":5,"t":"你不要害怕，因我与你同在；我必领你的后裔从东方来，又从西方召集你。","notes":[]},{"n":6,"t":"我要对北方说，交出来！对南方说，不可扣留！要将我的儿子从远方带来，将我的女儿从地极领回，","notes":[]},{"n":7,"t":"就是凡称为我名下的人，是我为自己的荣耀创造的，是我所塑造，所做成的。”","notes":[]},{"n":8,"t":"你要将有眼却瞎、有耳却聋的民都带出来！","notes":[],"heads":["以色列是耶和华的见证人"]},{"n":9,"t":"任凭万国聚集，任凭万民会合。他们当中谁能说明，并将先前的事指示我们呢？让他们带来见证，显明他们有理，看是否听见的人会说：“果然是真的。”","notes":[]},{"n":10,"t":"你们是我的见证，是我所拣选的仆人，为了要使你们知道，且信服我，又明白我就是耶和华。在我以前没有任何被造的真神，在我以后也必没有。这是耶和华说的。","notes":[]},{"n":11,"t":"我，惟有我是耶和华；除我以外没有救主。","notes":[]},{"n":12,"t":"我曾指示，我曾拯救，我曾说明，并没有外族的神明在你们中间。你们是我的见证，我是神。这是耶和华说的。","notes":["“外族的神明”：原文是“外族”。"]},{"n":13,"t":"自有日子以来，我就是神，谁也不能救人脱离我的手。我要行事，谁能逆转呢？","notes":[]},{"n":14,"t":"耶和华─你们的救赎主、以色列的圣者如此说：“因你们的缘故，我已派遣人到巴比伦去；要使迦勒底人都如难民，坐自己素来宴乐的船下来。","notes":[],"heads":["逃离巴比伦"]},{"n":15,"t":"我是耶和华－你们的圣者，是创造以色列的，是你们的君王。”","notes":[]},{"n":16,"t":"那在沧海中开道，在大水中开路，使战车、马匹、军兵、勇士一同出来，使他们仆倒，不再起来，使他们灭没，好像熄灭之灯火的耶和华如此说：","notes":[],"end":17},{"n":18,"t":"“你们不要追念从前的事，也不要思想古时的事。","notes":[]},{"n":19,"t":"看哪，我要行一件新事，如今就要显明，你们岂不知道吗？我必在旷野开道路，在沙漠开江河。","notes":["“江河”：死海古卷是“路径”。"]},{"n":20,"t":"野地的走兽要尊敬我，野狗和鸵鸟也必尊敬我。因我使旷野有水，使沙漠有河，好赐给我的百姓、我的选民喝。","notes":[]},{"n":21,"t":"这百姓是我为自己造的，为要述说我的美德。”","notes":[]},{"n":22,"t":"“雅各啊，你并没有求告我；以色列啊，你倒厌烦我。","notes":[],"heads":["以色列人的罪恶"]},{"n":23,"t":"你并没有将你的羊带来献给我做燔祭，也没有用牲祭尊敬我；我未曾因素祭使你操劳，也没有因乳香使你厌烦。","notes":[]},{"n":24,"t":"你没有用银子为我买香菖蒲，也没有用祭物的油脂使我饱足；倒使我因你的罪恶操劳，使我因你的罪孽厌烦。","notes":[]},{"n":25,"t":"我，惟有我为自己的缘故涂去你的过犯，我也不再记得你的罪恶。","notes":[]},{"n":26,"t":"你尽管提醒我，让我们来辩论；尽管陈述，自显为义。","notes":[]},{"n":27,"t":"你的始祖犯罪，你的师傅违背我；","notes":[]},{"n":28,"t":"因此，我要凌辱圣所的领袖，使雅各遭毁灭，使以色列受辱骂。”","notes":["“我要...领袖”：七十士译本是“领袖们亵渎了我的圣所，于是我要”。"]}]},"44":{"heading":"耶和华是独一的神","verses":[{"n":1,"t":"“我的仆人雅各，我所拣选的以色列啊，现在你当听。","notes":[]},{"n":2,"t":"那位造你，使你在母腹中成形，并要帮助你的耶和华如此说：我的仆人雅各，我所拣选的耶书仑哪，不要害怕！","notes":[]},{"n":3,"t":"因为我要把水浇灌干渴的地方，使水涌流在干旱之地。我要将我的灵浇灌你的后裔，使我的福临到你的子孙。","notes":[]},{"n":4,"t":"他们要在草丛中生长，如溪水旁的柳树。","notes":["“他们...生长”：死海古卷是“他们像在草丛中生长”；七十士译本是“他们要像草在水中生长”。"]},{"n":5,"t":"这个要说：‘我是属耶和华的’，那个要以雅各的名自称，又有一个在手上写着：‘归耶和华’，并自称为以色列。”","notes":[]},{"n":6,"t":"耶和华－以色列的君王，以色列的救赎主－万军之耶和华如此说：“我是首先的，也是末后的；除我以外再没有神。","notes":[]},{"n":7,"t":"自从古时我设立了人，谁能像我宣告，指明，又为自己陈说呢？让他指明未来的事和必成的事吧！","notes":[]},{"n":8,"t":"你们不要恐惧，也不要害怕。我岂不是从上古就告诉并指示你们了吗？你们是我的见证人！除我以外，岂有神呢？诚然没有磐石，就我所知，一个也没有！”","notes":[]},{"n":9,"t":"制造偶像的人尽都虚空，他们所喜悦的全无益处；偶像的见证人毫无所见，毫无所知，以致他们羞愧。","notes":[],"heads":["虚无的偶像"]},{"n":10,"t":"谁制造神像，铸造偶像？这些都是无益的。","notes":[]},{"n":11,"t":"看哪，他的同伙都必羞愧。工匠不过是人，任他们聚集，任他们站立吧！他们都必惧怕，一同羞愧。","notes":[]},{"n":12,"t":"铁匠用工具在火炭上工作，用锤打出形状，用他有力的膀臂来锤。他因饥饿而无力气；因未喝水而疲倦。","notes":["“铁匠...工作”：七十士译本是“工匠磨利铁器”。"]},{"n":13,"t":"木匠拉线，用笔划出样子，用刨子刨成形状，又用圆规划了模样。他仿照人的体态，做出美妙的人形，放在庙里。","notes":[]},{"n":14,"t":"他砍伐香柏树，又取杉树和橡树，在树林中让它茁壮；或栽种松树，得雨水滋润长大。","notes":[]},{"n":15,"t":"这树，人可用以生火；他拿一些来取暖，又搧火烤饼，而且做神像供跪拜，做雕刻的偶像向它叩拜。","notes":[]},{"n":16,"t":"他将一半的木头烧在火中，用它烤肉来吃；吃饱了，就自己取暖说：“啊哈，我暖和了，我看到火了！”","notes":[]},{"n":17,"t":"然后又用剩下的一半做了一个神明，就是雕刻的偶像，向这偶像俯伏叩拜，向它祷告说：“求你拯救我，因你是我的神明。”","notes":[]},{"n":18,"t":"他们既无知，又不思想；因为耶和华蒙蔽他们的眼，使他们看不见，塞住他们的心，使他们不明白。","notes":[]},{"n":19,"t":"没有一个心里醒悟，有知识，有聪明，能说：“我曾拿一部分用火燃烧，在炭火上烤饼，也烤肉来吃。这剩下的，我岂要做可憎之像吗？我岂可向木头叩拜呢？”","notes":[]},{"n":20,"t":"他以灰尘为食，心里迷糊，以致偏邪，不能自救，也不能说：“我右手中岂不是有虚谎吗？”","notes":[]},{"n":21,"t":"雅各啊，要思念这些事；以色列啊，你是我的仆人。我造了你，你是我的仆人，以色列啊，我必不忘记你。","notes":["“我必不忘记你”或译“你不会忘记我”。"],"heads":["耶和华是创造主也是救赎主"]},{"n":22,"t":"我涂去你的过犯，像厚云消散；涂去你的罪恶，如薄雾消失。你当归向我，因我救赎了你。","notes":[]},{"n":23,"t":"诸天哪，应当歌唱，因为耶和华成就这事。地的深处啊，应当欢呼；众山哪，要出声歌唱；树林和其中所有的树木啊，你们都当歌唱！因为耶和华救赎了雅各，并要因以色列荣耀自己。","notes":[]},{"n":24,"t":"从你在母腹中就造了你，你的救赎主－耶和华如此说：“我－耶和华创造万物，独自铺张诸天，亲自展开大地；","notes":["“亲自展开大地”：原文另译“展开大地，谁与我同在呢？”"]},{"n":25,"t":"我使虚谎的预兆失效，愚弄占卜的人，使智慧人退后，使他的知识变为愚拙；","notes":[]},{"n":26,"t":"却使我仆人的话站得住，成就我使者的筹算。我论耶路撒冷说：‘必有人居住’；论犹大的城镇说：‘必被建造，我必重建其中的废墟。’","notes":[]},{"n":27,"t":"我对深渊说：‘干了吧！我要使你的江河干涸’；","notes":[]},{"n":28,"t":"论居鲁士说：‘他是我的牧人，他要成就我所喜悦的，下令建造耶路撒冷，发命令立稳圣殿的根基。’”","notes":[]}]},"45":{"heading":"耶和华立居鲁士为王","verses":[{"n":1,"t":"耶和华对所膏的居鲁士如此说，他的右手我曾搀扶，使列国降服在他面前，列王的腰带我曾松开，使城门在他面前敞开，不得关闭：","notes":[]},{"n":2,"t":"“我要在你前面行，修平崎岖之地。我必打破铜门，砍断铁闩。","notes":[]},{"n":3,"t":"我要将暗中的宝物和隐藏的财富赐给你，使你知道提名召你的就是我－耶和华，以色列的神。","notes":[]},{"n":4,"t":"因我的仆人雅各，我所拣选的以色列，我提名召你；你虽不认识我，我也加给你名号。","notes":[]},{"n":5,"t":"我是耶和华，再没有别的了；除了我以外再没有神。你虽不认识我，我必给你束腰。","notes":[]},{"n":6,"t":"从日出之地到日落之处使人都知道除我以外，没有别的。我是耶和华，再没有别的了。","notes":[]},{"n":7,"t":"我造光，又造暗；施平安，又降灾祸；做成这一切的是我－耶和华。","notes":[]},{"n":8,"t":"“诸天哪，要如雨倾盆而降，云要降下公义，地要裂开，救恩涌出，使公义也一同滋长；这都是我－耶和华造的。”","notes":["“救恩涌出”：原文另译“产出救恩”。"]},{"n":9,"t":"“那与造他的主争论的人有祸了！他不过是地上瓦块中的一片。泥土岂可对塑造它的说：‘你做的是什么？你所做的物怎么没有把手呢？’","notes":["“那与...一片”：死海古卷是“那与造他的主争论的人，就是瓦器与陶匠争论的，有祸了！”","“你所做...把手呢？”或译“所做的物岂可说：你没有手呢 ？”"],"heads":["创造和历史的主宰"]},{"n":10,"t":"有人对父亲说，‘你生的是什么’，对母亲说，‘你生产的是什么’；这人有祸了！”","notes":["“母亲”：原文是“妇人”。"]},{"n":11,"t":"耶和华－以色列的圣者，就是造以色列的如此说：“难道我孩子的未来，你们能质问我，我手的工作，你们可以吩咐我吗？","notes":[]},{"n":12,"t":"我造大地，又创造人在地上。我亲手铺张诸天，天上万象也是我所任命的。","notes":[]},{"n":13,"t":"我凭公义兴起居鲁士，又要修直他一切的道路。他必建造我的城，释放我被掳的民，不为工价，也不为奖赏。”这是万军之耶和华说的。","notes":["“居鲁士”：原文是“他”。"]},{"n":14,"t":"耶和华如此说：“埃及的出产和古实的货物必归你；身量高大的西巴人，他们必过来归你，为你所有。他们必带着锁链过来跟随你，向你下拜，祈求你说：‘神真是在你中间，再没有别的，没有别的神。’”","notes":[]},{"n":15,"t":"救主－以色列的神啊，你诚然是隐藏自己的神。","notes":[]},{"n":16,"t":"制造偶像的都要抱愧蒙羞，他们要一同归于惭愧。","notes":[]},{"n":17,"t":"惟有以色列必蒙耶和华拯救，得永远的救恩。你们必不蒙羞，也不抱愧，直到永世无尽。","notes":[]},{"n":18,"t":"耶和华如此说，他创造诸天，他是神；他造了地，形成它，坚固它，并非创造它为荒凉，而是要给人居住：“我是耶和华，再没有别的。","notes":[]},{"n":19,"t":"我不在隐密黑暗之地说话，也没有对雅各的后裔说，‘你们寻求我是徒然的’，我－耶和华所讲的是公义，所说的是正直。”","notes":[]},{"n":20,"t":"“你们从列国逃脱的人，要一同聚集前来。那些抬着雕刻的木偶、祈求不能救人之神明的，毫无知识。","notes":[],"heads":["天地之主"]},{"n":21,"t":"你们要近前来说明，让他们彼此商议。谁从古时指明这事？谁从上古述说它？不是我－耶和华吗？除了我以外，再没有神；我是公义的神，又是救主；除了我以外，再没有别的了。","notes":[]},{"n":22,"t":"“地的四极都当转向我，就必得救；因为我是神，再没有别的。","notes":[]},{"n":23,"t":"我指着自己起誓，公义从我的口发出，这话并不返回：‘万膝必向我跪拜，万口必凭我起誓。’","notes":[]},{"n":24,"t":"“人论我说，‘公义、能力，惟独在乎耶和华。人必归向他，凡向他发怒的都必蒙羞。","notes":["“人论我说”：七十士译本是“人说”。"]},{"n":25,"t":"以色列的后裔必因耶和华得称为义，并要彼此夸耀。’”","notes":[]}]},"46":{"heading":"巴比伦的偶像","verses":[{"n":1,"t":"彼勒叩拜，尼波屈身；巴比伦的偶像驮在走兽和牲畜背上。你们所抬的成了重驮，使牲畜疲乏。","notes":[]},{"n":2,"t":"这些神明一同屈身叩拜，不能救自己，反倒遭人掳去。","notes":["“自己”或译“重驮”。"]},{"n":3,"t":"雅各家，以色列家所有的余民哪，你们自从生下就蒙我抱，自出母胎便由我来背，你们都要听从我。","notes":[]},{"n":4,"t":"直到你们年老，我不改变；直到你们发白，我仍扶持。我已造你，就必背你；我必抱你，也必拯救。","notes":[]},{"n":5,"t":"你们将谁与我相比，与我相等，将谁与我相较，使我们相似呢？","notes":[]},{"n":6,"t":"他们从钱囊中倒出金子，用天平秤出银子，雇银匠造成神像，他们又俯伏，又叩拜。","notes":[]},{"n":7,"t":"他们抬起神像，扛在肩上，安置在定处，使它站立，不离本位；人呼求它，它却不回答，也无法救人脱离灾难。","notes":[]},{"n":8,"t":"你们当记得这事，立定心意。叛逆的人哪，要留心思想。","notes":["“立定心意”或译“自己做大丈夫”。"]},{"n":9,"t":"要追念上古的事，因为我是神，并无别的；我是神，没有能与我相比的。","notes":[]},{"n":10,"t":"我从起初就指明末后的事，从古时便言明未成的事，说：“我的筹算必立定；凡我所喜悦的，我必成就。”","notes":[]},{"n":11,"t":"我召鸷鸟从东方来，召那成就我筹算的人从远方来。我已说出，就必成就；我已谋定，也必做成。","notes":[]},{"n":12,"t":"你们这些心中顽固、远离公义的人，要听从我。","notes":[]},{"n":13,"t":"我使我的公义临近，它已不远。我的救恩必不迟延。我要为以色列－我的荣耀在锡安施行救恩。","notes":[]}]},"47":{"heading":"审判巴比伦","verses":[{"n":1,"t":"少女巴比伦 哪，下来坐在尘埃；迦勒底啊，没有宝座，要坐在地上；你不再称为柔弱娇嫩。","notes":["“少女巴比伦”：原文直译“少女巴比伦女子”。","“迦勒底”：原文直译“迦勒底女子”；下同。"]},{"n":2,"t":"要用磨磨面，揭去面纱，脱去长裙，露腿渡河。","notes":[]},{"n":3,"t":"你的下体必被露出；你的羞辱必被看见。我要报复，谁也不宽容。","notes":["“谁也不宽容”或译“谁也不能阻止我”。"]},{"n":4,"t":"我们的救赎主是以色列的圣者，他的名为万军之耶和华。","notes":[]},{"n":5,"t":"迦勒底啊，你要静坐，进入黑暗中，因你不再称为万国之后。","notes":[]},{"n":6,"t":"我向我的百姓发怒，使我的产业受凌辱，将他们交在你手中；然而你毫不怜悯他们，连老年人你也加极重的轭。","notes":[]},{"n":7,"t":"你说：“我必永远为后。”你不将这事放在心上，也不思想事情的结局。","notes":[]},{"n":8,"t":"你这专好宴乐、以为地位稳固的，现在当听这话。你心中说：“惟有我，除我以外再没有别的。我必不致寡居，也不经历丧子之痛。”","notes":[]},{"n":9,"t":"哪知，丧子、寡居这两件事一日之间忽然临到你；你虽多行邪术、广施魔咒，这两件事必全然临到你身上。","notes":[]},{"n":10,"t":"你倚靠自己的恶行，说：“无人看见我。”你的智慧聪明使你走偏，你心里说：“惟有我，除我以外再没有别的了。”","notes":[]},{"n":11,"t":"但灾祸临到你，你不知如何驱除；灾害落在你身上，你也无法除掉，你所不知道的毁灭必忽然临到你身上。","notes":[]},{"n":12,"t":"尽管使用从幼年就施行的魔符和众多的邪术吧！或许有些帮助，或许可以致胜。","notes":[]},{"n":13,"t":"你筹划太多，以致疲倦。让那些观天象，看星宿，在初一说预言的都起来，救你脱离所要临到你的事！","notes":[]},{"n":14,"t":"看哪，他们要像碎秸被火焚烧，无法救自己脱离火焰的魔掌；没有炭火可以取暖，你也不能坐在火旁。","notes":["“取暖”或译“烤饼”。"]},{"n":15,"t":"你所操劳的事都像这样；从你幼年以来与你交易的都各奔己路，没有一人来救你。","notes":[]}]},"48":{"heading":"神掌管未来","verses":[{"n":1,"t":"雅各家，称为以色列名下，从犹大的源头而出的啊，你们指着耶和华的名起誓，提说以色列的神，却不凭诚信，也不凭公义；你们自称为圣城之民，倚靠名为万军之耶和华－以色列的神；现在，当听我言：","notes":[],"end":2},{"n":3,"t":"“先前的事，我自古已说明，已从我口而出，是我所指示的；我瞬间行事，事便成就。","notes":[]},{"n":4,"t":"因为我知道你是顽梗的；你的颈项是铁的，你的额头是铜的。","notes":[]},{"n":5,"t":"所以，我自古就给你说明，在事未成以先指示你，免得你说：‘这些事是我的偶像所行的，是我雕刻的偶像和铸造的神像所命定的。’","notes":[]},{"n":6,"t":"“你既已听见，现在要察看这一切；你们不是要说明吗？从今以后，我要指示你新事，就是你所不知道的隐密事。","notes":[]},{"n":7,"t":"这事是现今造的，并非自古就有，在今日以先，你未曾听见；免得你说：‘看哪，这事我早已知道了。’","notes":[]},{"n":8,"t":"诚然你未曾听见，也未曾知道；你的耳朵从来未曾开通。我原知道你行事极其诡诈，你自从出母胎以来，就称为悖逆的。","notes":[]},{"n":9,"t":"“我为我的名暂且忍怒，为了我的荣耀向你容忍，不将你剪除。","notes":[]},{"n":10,"t":"看哪，我熬炼你，却不像熬炼银子；你在苦难的火炉中，我试炼你。","notes":["“试炼”是根据死海古卷；原文是“拣选”。"]},{"n":11,"t":"我为自己的缘故必做这事，我岂能被亵渎？我必不将我的荣耀归给别神。","notes":["“我岂能被亵渎？”七十士译本和其他古译本是“因为我的名被亵渎。”","“别神”：原文是“别的”。"]},{"n":12,"t":"雅各－我所选召的以色列啊，当听从我：我是耶和华，我是首先的，也是末后的。","notes":[]},{"n":13,"t":"我亲手立了地的根基，以右手铺张诸天；我一召唤，天地就都立定。”","notes":[]},{"n":14,"t":"“你们都当聚集而听，偶像之中谁曾说明这些事？耶和华爱他，他必向巴比伦成就耶和华的旨意，耶和华的膀臂也要加在迦勒底人身上。","notes":["“偶像”：原文是“它们”。","“耶和华爱他...身上”：七十士译本是“我因爱你，向巴比伦成就了你的旨意，除掉了迦勒底的后裔”。"],"heads":["耶和华拣选居鲁士"]},{"n":15,"t":"我，惟有我曾说过，我选召他，领他来，他的道路必亨通。","notes":[]},{"n":16,"t":"你们要接近我来听这话，我从起初就未曾在隐密之处说话，万事之始，我就在那里。”现在，主耶和华差遣了我，带着他的灵而来。","notes":["“差遣了我，带着他的灵而来”：原文是“差遣了我和他的灵来”。"]},{"n":17,"t":"耶和华－你的救赎主，以色列的圣者如此说：“我是耶和华－你的神，我教导你，使你得益处，指引你当走的路。","notes":[],"heads":["耶和华对他子民的计划"]},{"n":18,"t":"甚愿你听从我的命令，你的平安就会如河水，你的公义如海浪，","notes":[]},{"n":19,"t":"你的后裔必多如海沙，你腹中所生的必多如沙粒。他的名绝不从我面前剪除，也不灭绝。”","notes":[]},{"n":20,"t":"你们要从巴比伦出来，从迦勒底人中逃脱，以欢呼的声音宣告，将这事传扬到地极，说：耶和华救赎了他的仆人雅各！","notes":[]},{"n":21,"t":"他引导他们经过沙漠，他们却未尝干渴；他为他们使水从磐石流出，磐石裂开，水就涌出。","notes":[]},{"n":22,"t":"耶和华说：“恶人必不得平安！”","notes":[]}]},"49":{"heading":"以色列成为万邦之光","verses":[{"n":1,"t":"众海岛啊，当听从我！远方的众民哪，要留心听！自出母胎，耶和华就选召我；自出母腹，他就称呼我的名。","notes":[]},{"n":2,"t":"他使我的口如快刀，把我藏在他手荫之下；又使我成为磨利的箭，把我藏在他箭袋之中；","notes":[]},{"n":3,"t":"对我说：“你是我的仆人以色列；我必因你得荣耀。”","notes":[]},{"n":4,"t":"我却说：“我劳碌是徒然，我尽力是虚无虚空。耶和华诚然以公平待我，我的赏赐在我的神那里。”","notes":[]},{"n":5,"t":"现在耶和华说话，他从我出母胎，就造我作他的仆人，要使雅各归向他，使以色列聚集在他那里。耶和华看我为尊贵，我的神是我的力量。","notes":[]},{"n":6,"t":"他说：“你作我的仆人，使雅各众支派复兴，使以色列中蒙保存的人归回；然而此事尚小，我还要使你作万邦之光，使你施行我的救恩，直到地极。”","notes":[]},{"n":7,"t":"救赎主－以色列的圣者耶和华对那被人藐视、本国憎恶、统治者奴役的如此说：“君王看见就站起来，领袖也要下拜；这都是因信实的耶和华，因拣选你的以色列的圣者。”","notes":[]},{"n":8,"t":"耶和华如此说：“在悦纳的时候，我应允了你；在拯救的日子，我帮助了你。我要保护你，要藉着你与百姓立约，为了复兴遍地，使人承受荒芜之地为业；","notes":[],"heads":["耶路撒冷的复兴"]},{"n":9,"t":"对那被捆绑的人说：‘出来吧！’对在黑暗里的人说：‘显现吧！’他们在路上必得饮食，在光秃的高地必有食物。","notes":[]},{"n":10,"t":"他们不饥不渴，炎热和烈日必不伤害他们；因为怜悯他们的必引导他们，领他们到水泉旁边。","notes":[]},{"n":11,"t":"我必在众山开辟路径，大道也要填高。","notes":[]},{"n":12,"t":"看哪，他们从远方来；有些从北方来，有些从西方来，有些从色弗尼地来。”","notes":["“色弗尼”是根据死海古卷，原文是“希尼”；或译“秦国”。"]},{"n":13,"t":"诸天哪，应当欢呼！大地啊，应当快乐！众山哪，应当扬声歌唱！因为耶和华已经安慰他的百姓，他要怜悯他的困苦之民。","notes":[]},{"n":14,"t":"锡安说：“耶和华离弃了我，主忘记了我。”","notes":[]},{"n":15,"t":"妇人焉能忘记她吃奶的婴孩，不怜悯她所生的儿子？即或有忘记的，我却不忘记你。","notes":[]},{"n":16,"t":"看哪，我将你铭刻在我掌上，你的城墙常在我眼前。","notes":[]},{"n":17,"t":"建立你的胜过毁坏你的，使你荒废的必都离你而去。","notes":["本节是根据死海古卷；原文是“你的儿女必急速归回；毁坏你的，使你荒废的，必都离你而去。”"]},{"n":18,"t":"你举目向四围观看，他们都聚集来到你这里。我指着我的永生起誓，你定要以他们为妆饰佩戴，带着他们，像新娘一样。这是耶和华说的。","notes":[]},{"n":19,"t":"至于你荒废凄凉之处，并你被毁坏之地，如今居民必嫌太窄，吞灭你的必离你遥远。","notes":[]},{"n":20,"t":"你要再听见丧失子女后所生的儿女说：“这地方我居住太窄，请你给我地方居住。”","notes":[]},{"n":21,"t":"那时你心里必说：“我既丧子不育，被掳，飘流在外，谁给我生了这些？谁将他们养大呢？看哪，我被撇下独自一人时，他们都在哪里呢？”","notes":["七十士译本没有“被掳，飘流在外”。"]},{"n":22,"t":"主耶和华如此说：“看哪，我必向列国举手，向万民竖立大旗；他们必将你的儿子抱在怀中带来，将你的女儿背在肩上扛来。","notes":[]},{"n":23,"t":"列王必作你的养父，王后必作你的乳母。他们必以脸伏地，向你下拜，并舔你脚上的尘土。你就知道我是耶和华，等候我的必不致羞愧。”","notes":[]},{"n":24,"t":"勇士抢去的岂能夺回？被残暴者掳掠的岂能得解救呢？","notes":[]},{"n":25,"t":"但耶和华如此说：“就是勇士所掳掠的，也可以夺回；残暴者所抢的，也可以得解救。与你相争的，我必与他相争，我也要拯救你的儿女。","notes":[]},{"n":26,"t":"我必使那欺压你的吃自己的肉，饮自己的血，如喝甜酒喝醉一样。凡有血肉之躯的都必知道我－耶和华是你的救主，是你的救赎主，是雅各的大能者。”","notes":[]}]},"50":{"heading":"耶和华仆人的顺服","verses":[{"n":1,"t":"耶和华如此说：“我休了你们的母亲，她的休书在哪里呢？我将你们卖给了我哪一个债主呢？看哪，你们被卖是因你们的罪孽；你们的母亲被休，是因你们的过犯。","notes":[]},{"n":2,"t":"我来的时候，为何没有人呢？我呼唤的时候，为何无人回应呢？我的膀臂岂是过短、不能救赎吗？我岂无拯救之力吗？看哪，我一斥责，海就干了；我使江河变为旷野，其中的鱼因无水腥臭，干渴而死。","notes":[]},{"n":3,"t":"我使诸天以黑暗为衣，以麻布为遮盖。”","notes":[]},{"n":4,"t":"主耶和华赐我受教者的舌头，使我知道怎样用言语扶助疲乏的人。主每天早晨唤醒，唤醒我的耳朵，使我能听，像受教者一样。","notes":[]},{"n":5,"t":"主耶和华开启我的耳朵，我并未违背，也未退后。","notes":[]},{"n":6,"t":"人打我的背，我任他打；人拔我两颊的胡须，我由他拔；人侮辱我，向我吐唾沫，我并不掩面。","notes":[]},{"n":7,"t":"主耶和华必帮助我，所以我不抱愧。我硬着脸面好像坚石，也知道我必不致蒙羞。","notes":[]},{"n":8,"t":"称我为义的与我相近；谁与我争论，让我们来对质；谁与我作对，让他近前来吧！","notes":[]},{"n":9,"t":"看哪，主耶和华必帮助我，谁能定我有罪呢？看哪，他们都要像衣服渐渐破旧，被蛀虫蛀光。","notes":[]},{"n":10,"t":"你们当中有谁是敬畏耶和华，听从他仆人的话语，却行在黑暗中，没有亮光的，当倚靠耶和华的名，仰赖自己的神。","notes":[]},{"n":11,"t":"看哪，你们当中所有点火、以火把围绕自己的人，当行走在你们的火焰里，并你们所点的火把中。这是我亲手为你们定的：你们必躺卧在悲惨之中。","notes":["“火焰”：七十士译本和其他古译本是“火光”。"]}]},"51":{"heading":"安慰锡安的话","verses":[{"n":1,"t":"追求公义、 寻求耶和华的人哪，当听从我！你们要追想自己是从哪块磐石凿出，从哪个岩穴挖掘而来；","notes":[]},{"n":2,"t":"要追想你们的祖宗亚伯拉罕和生你们的撒拉；因为我选召亚伯拉罕时，他只有一个人，但我赐福给他，使他增多。","notes":[]},{"n":3,"t":"耶和华已经安慰锡安，安慰了锡安一切的废墟，使旷野如伊甸，使沙漠像耶和华的园子；其中必有欢喜、快乐、感谢，和歌唱的声音。","notes":[]},{"n":4,"t":"我的民哪，要留心听我，我的国啊，要向我侧耳；因为训诲必从我而出，我必使我的公理成为万民之光。","notes":[]},{"n":5,"t":"我的公义临近，我的救恩发出。我的膀臂要审判万民，众海岛都要等候我，倚赖我的膀臂。","notes":[]},{"n":6,"t":"你们要向天举目，观看下面的地；天必像烟云消散，地必如衣服渐渐破旧；其上的居民也要如此死亡。惟有我的救恩永远长存，我的公义也不废掉。","notes":["“如此”：原文另译“像蠓虫”。"]},{"n":7,"t":"知道公义、将我的训诲存在心中的人哪，当听从我！不要怕人的辱骂，也不要因人的毁谤惊惶。","notes":[]},{"n":8,"t":"因为他们必像衣服被蛀虫蛀；像羊毛被虫子咬。惟有我的公义永远长存，我的救恩直到万代。","notes":[]},{"n":9,"t":"耶和华的膀臂啊，兴起，兴起！以能力为衣穿上，像古时的年日，像上古的世代一样兴起！从前砍碎拉哈伯、刺透大鱼的，不是你吗？","notes":["“拉哈伯”是神话故事中的大海怪。"]},{"n":10,"t":"使海与深渊的水干涸，在海的深处开路，使救赎的民走过的，不是你吗？","notes":[]},{"n":11,"t":"耶和华救赎的民必归回，歌唱来到锡安；永恒的喜乐必归到他们头上。他们必得着欢喜快乐，忧伤叹息尽都逃避。","notes":[]},{"n":12,"t":"我，惟有我是安慰你们的。你是谁，竟怕那必死的人，怕那生命如草的世人，","notes":[]},{"n":13,"t":"却忘记铺张诸天、立定地基、造你的耶和华？你因欺压者图谋毁灭所发的暴怒，终日害怕，其实那欺压者的暴怒在哪里呢？","notes":[]},{"n":14,"t":"被掳的即将得释放，不至于死而下入地府，也不致缺乏食物。","notes":[]},{"n":15,"t":"我是耶和华－你的神，我搅动大海，使海中的波浪澎湃，万军之耶和华是我的名。","notes":[]},{"n":16,"t":"我已将我的话放在你口中，用我的手影遮蔽你，为要安定诸天，立定地基，并对锡安说：“你是我的百姓。”","notes":[]},{"n":17,"t":"耶路撒冷啊，兴起，兴起！站起来！你从耶和华手中喝了他愤怒的杯，那使人东倒西歪的杯，直到喝尽。","notes":[],"heads":["耶路撒冷苦难的终结"]},{"n":18,"t":"她所生育的孩子中，没有一个搀她的；她所抚养的孩子中，没有一个扶她的。","notes":[]},{"n":19,"t":"这双重的灾难临到你，有谁怜悯你呢？破坏和毁灭，饥荒和战争临到，我如何能安慰你呢？","notes":["“我如何能安慰你呢？”死海古卷和七十士译本是“谁能安慰你呢？”"]},{"n":20,"t":"你的孩子发昏，在各街头躺卧，如同网罗里的羚羊，满了耶和华的愤怒，满了你神的斥责。","notes":[]},{"n":21,"t":"因此，你这困苦却非因酒而醉的，当听这话，","notes":[]},{"n":22,"t":"你的主，耶和华，就是为他百姓辩护的神如此说：“看哪，我已从你手中接过那使人东倒西歪的杯，就是我愤怒的杯，你必不再喝。","notes":[]},{"n":23,"t":"我必将这杯递在苦待你的人手中。他们曾对你说：‘你屈身，任我们践踏过去吧！’你就以背为地，又如街道，任人走过。","notes":["“苦待你的人”：死海古卷和七十士译本是“苦待你的人和压迫你的人”。"]}]},"52":{"heading":"神要拯救耶路撒冷","verses":[{"n":1,"t":"锡安哪，兴起！兴起！穿上你的能力！圣城耶路撒冷啊，穿上你华美的衣服！因为从今以后，未受割礼、不洁净的必不再进入你中间。","notes":[]},{"n":2,"t":"耶路撒冷啊，抖去尘埃，起来坐在王位上！被掳的锡安哪，解开你颈上的锁链！","notes":["“锡安”：原文直译“锡安女子”。"]},{"n":3,"t":"耶和华如此说：“你们白白地被卖，也必不用银子赎回。”","notes":[]},{"n":4,"t":"主耶和华如此说：“先前我的百姓下到埃及，在那里寄居，末后又有亚述人欺压他们。","notes":[]},{"n":5,"t":"我的百姓既是白白地被掳，如今我在这里做什么呢？这是耶和华说的。辖制他们的人欢呼，我的名终日不断受亵渎，这是耶和华说的。","notes":["“辖制他们的人欢呼”或译“百姓的领袖哀号”。"]},{"n":6,"t":"因此，我的百姓必认识我的名；在那日，他们必知道说这话的就是我。看哪，是我！”","notes":[]},{"n":7,"t":"在山上报佳音，传平安，报好信息，传扬救恩，那人的脚踪何等佳美啊！他对锡安说：“你的神作王了！”","notes":[]},{"n":8,"t":"听啊，你守望之人的声音，他们扬声一同欢唱；因为他们必亲眼看见耶和华返回锡安。","notes":[]},{"n":9,"t":"耶路撒冷的废墟啊，要出声一同欢唱；因为耶和华安慰了他的百姓，救赎了耶路撒冷。","notes":[]},{"n":10,"t":"耶和华在万国眼前露出圣臂，地的四极都要看见我们神的救恩。","notes":[]},{"n":11,"t":"离开吧！离开吧！你们要从巴比伦出来。你们扛抬耶和华器皿的人哪，不要沾染不洁净之物，离去时务要保持洁净。","notes":[]},{"n":12,"t":"你们出来必不致匆忙，也不致奔逃；因为耶和华要在你们前头行，以色列的神必作你们的后盾。","notes":[]},{"n":13,"t":"看哪，我的仆人行事必有智慧，他必被高升，高举，升到至高之处。","notes":[],"heads":["受苦的仆人"]},{"n":14,"t":"许多人因他惊奇─他的面貌比别人憔悴，他的外表比世人枯槁─","notes":["“他”：原文是“你”。"]},{"n":15,"t":"同样，他也必使许多国家惊奇，君王要向他闭口。未曾传给他们的，他们必看见；未曾听见过的事，他们要明白。","notes":["“他也必使许多国家惊奇”是根据七十士译本 ；原文是 “他必洗净许多国家”。"]}]},"53":{"heading":"","verses":[{"n":1,"t":"我们所传的有谁信呢？耶和华的膀臂向谁显露呢？","notes":[]},{"n":2,"t":"他在耶和华面前生长如嫩芽，像根出于干地。他无佳形美容使我们注视他，也无美貌使我们仰慕他。","notes":[]},{"n":3,"t":"他被藐视，被人厌弃；多受痛苦，常经忧患。他被藐视，好像被人掩面不看的一样，我们也不尊重他。","notes":[]},{"n":4,"t":"他诚然担当我们的忧患，背负我们的痛苦；我们却以为他受责罚，是被神击打苦待。","notes":[]},{"n":5,"t":"他为我们的过犯受害，为我们的罪孽被压伤。因他受的惩罚，我们得平安；因他受的鞭伤，我们得医治。","notes":[]},{"n":6,"t":"我们都如羊走迷，各人偏行己路；耶和华使我们众人的罪孽都归在他身上。","notes":[]},{"n":7,"t":"他被欺压受苦，却不开口；他像羔羊被牵去宰杀，又像羊在剪毛的人手下无声，他也是这样不开口。","notes":[]},{"n":8,"t":"因受欺压和审判，他被夺去，谁能想到他的世代呢？因为他从活人之地被剪除，为我百姓的罪过他被带到死里。","notes":["“我百姓”：死海古卷是“他的百姓”。","“他被带到死里”是根据七十士译本；原文是“为他们受击打”。","本节或译“因受欺压和审判，他被夺去，至于他同世的人，谁想他受鞭打、从活人之地被剪除，是因我百姓的罪过呢？”"]},{"n":9,"t":"他虽然未行残暴，口中也没有诡诈，人还使他与恶人同穴，与财主同墓。","notes":["“与财主同墓”是根据死海古卷；原文是“他死的时候与财主一起”。"]},{"n":10,"t":"耶和华的旨意要压伤他，使他受苦。当他的生命作为赎罪祭时，他必看见后裔，他的年日必然长久。耶和华所喜悦的事，必在他手中亨通。","notes":["“当...赎罪祭时”或译“当耶和华以他为赎罪祭时”。"]},{"n":11,"t":"因自己的劳苦，他必看见光就心满意足。因自己的认识，我的义仆使许多人得称为义，他要担当他们的罪孽。","notes":["“光”是根据死海古卷和七十士译本；原文没有“光”。"]},{"n":12,"t":"因此，我要使他与位大的同份，与强盛的均分掳物。因为他倾倒自己的生命，以致于死，也列在罪犯之中。他却担当多人的罪，为他们的过犯代求。","notes":["“为他们的过犯代求”是根据死海古卷和七十士译本；原文是“又为罪犯代求”。"]}]},"54":{"heading":"耶和华对以色列的爱","verses":[{"n":1,"t":"你这不怀孕、不生育的，要欢呼；你这未曾经过产难的，要欢呼，扬声呼喊；因为被遗弃的妇人，比有丈夫的人儿女更多；这是耶和华说的。","notes":[]},{"n":2,"t":"要扩张你帐幕之地，伸展你居所的幔子，不要缩回；要放长你的绳子，坚固你的橛子。","notes":[]},{"n":3,"t":"因为你要向左向右开展，你的后裔必得列国为业，又使荒废的城镇有人居住。","notes":[]},{"n":4,"t":"不要惧怕，因你必不致蒙羞；不要抱愧，因你必不致受辱。你必忘记年轻时的羞愧，不再记得守寡的耻辱。","notes":[]},{"n":5,"t":"因为造你的是你的丈夫，万军之耶和华是他的名；救赎你的是以色列的圣者，他必称为全地之神。","notes":[]},{"n":6,"t":"耶和华召你，如同召回心中忧伤遭遗弃的妇人，就是年轻时所娶被遗弃的妻子；这是你的神说的。","notes":[]},{"n":7,"t":"我离弃你不过片时，却要大施怜悯将你寻回。","notes":[]},{"n":8,"t":"我因涨溢的怒气，一时向你转脸，但我要以永远的慈爱怜悯你；这是耶和华－你的救赎主说的。","notes":[]},{"n":9,"t":"这事于我有如挪亚的洪水；我怎样起誓不再使挪亚的洪水淹没全地，也照样起誓不再向你发怒，且不斥责你。","notes":[]},{"n":10,"t":"大山可以挪开，小山可以迁移，但我的慈爱必不离开你，我平安的约也不迁移；这是怜悯你的耶和华说的。","notes":[]},{"n":11,"t":"你这受困苦、被暴风卷走、不得怜悯的城，看哪，我必以灰泥来做你的石头，以蓝宝石立你的根基，","notes":[],"heads":["耶路撒冷的将来"]},{"n":12,"t":"又以红宝石造你的女墙，以晶莹的珠玉造你的城门，以珍贵的宝石造你四围的边界。","notes":[]},{"n":13,"t":"你的儿女都要领受耶和华的教导，你的儿女必大享平安。","notes":[]},{"n":14,"t":"你必因公义得坚立，必远离欺压，毫不惧怕；你必远离惊吓，惊吓必不临近你。","notes":[]},{"n":15,"t":"若有人攻击你，这非出于我；凡攻击你的，必因你仆倒。","notes":[]},{"n":16,"t":"看哪，我造了那吹炭火、打造合用兵器的铁匠；我也造了那残害人、行毁灭的人。","notes":[]},{"n":17,"t":"凡为攻击你而造的兵器必无效用；在审判时兴起用口舌攻击你的，你必驳倒他。这是耶和华仆人的产业，是他们从我所得的义；这是耶和华说的。","notes":[]}]},"55":{"heading":"神要施怜悯","verses":[{"n":1,"t":"来！你们所有干渴的，都当来到水边；没有银钱的也可以来。你们都来，买了吃；不用银钱，不付代价，就可买酒和奶。","notes":[]},{"n":2,"t":"你们为何花钱买那不是食物的东西，用劳碌得来的买那无法使人饱足的呢？你们要留意听从我的话，就能吃那美物，得享肥甘，心中喜乐。","notes":[]},{"n":3,"t":"当侧耳而听，来到我这里；要听，就必存活。我要与你们立永约，就是应许给大卫那可靠的慈爱。","notes":[]},{"n":4,"t":"看哪，我已立他作万民的见证，立他作万民的君王和发令者。","notes":[]},{"n":5,"t":"看哪，你要召集素不认识的国民，素不认识的国民要奔向你；这都因耶和华─你的神，因以色列的圣者已经荣耀了你。","notes":[]},{"n":6,"t":"当趁耶和华可寻找的时候寻找他，在他接近的时候求告他。","notes":[]},{"n":7,"t":"恶人当离弃自己的道路，不义的人应除掉自己的意念。归向耶和华，耶和华就必怜悯他；当归向我们的神，因为他必广行赦免。","notes":[]},{"n":8,"t":"我的意念非同你们的意念，我的道路非同你们的道路。这是耶和华说的。","notes":[]},{"n":9,"t":"天怎样高过地，照样，我的道路高过你们的道路，我的意念高过你们的意念。","notes":[]},{"n":10,"t":"雨雪从天而降，并不返回，却要滋润土地，使地面发芽结实，使撒种的有种，使要吃的有粮。","notes":[]},{"n":11,"t":"我口所出的话也必如此，绝不徒然返回，却要成就我的旨意，达成我差它的目的。","notes":[]},{"n":12,"t":"你们必欢欢喜喜出来，平平安安蒙引导。大山小山必在你们面前欢呼，田野的树木也都拍掌。","notes":[]},{"n":13,"t":"松树长出，代替荆棘；番石榴长出，代替蒺藜。这要为耶和华留名，作为永不磨灭的证据。","notes":[]}]},"56":{"heading":"神的子民将遍及各国","verses":[{"n":1,"t":"耶和华如此说：“你们当守公平，行公义；因我的救恩临近，我的公义将要显现。","notes":[]},{"n":2,"t":"谨守安息日不予干犯，禁止己手不作恶，如此行、如此持守的人有福了！”","notes":[]},{"n":3,"t":"与耶和华联合的外邦人不要说：“耶和华将我和他的子民分别出来。”太监也不要说：“看哪，我是枯树。”","notes":[]},{"n":4,"t":"因为耶和华如此说：“那些谨守我的安息日，选择我旨意，持守我约的太监，","notes":[]},{"n":5,"t":"我必使他们在我殿中，在我墙内，有纪念碑，有名号，胜过有儿有女；我必赐他们永远的名，不能剪除。","notes":[]},{"n":6,"t":"“那些与耶和华联合，事奉他，爱他名，作他仆人的外邦人，凡谨守安息日不予干犯，又持守我约的人，","notes":[]},{"n":7,"t":"我必领他们到我的圣山，使他们在我的祷告的殿中喜乐。他们的燔祭和祭物，在我坛上必蒙悦纳，因我的殿必称为万民祷告的殿。","notes":[]},{"n":8,"t":"我还要召集更多的人归并到这些被召集的人中。这是召集被赶散的以色列人的主耶和华说的。”","notes":[]},{"n":9,"t":"野地的走兽，你们都来吞吃吧！林中的野兽，你们也来吞吃！","notes":[],"heads":["以色列的领袖被定罪"]},{"n":10,"t":"以色列的守望者都瞎了眼，没有知识；都是哑狗，不会吠叫，只知做梦，躺卧，贪睡，","notes":[]},{"n":11,"t":"这些狗贪食，不知饱足。这些牧人不知明辨，他们都偏行己路，人人追求自己的利益。","notes":[]},{"n":12,"t":"他们说：“来吧！我去拿酒，让我们畅饮烈酒吧！明天必和今天一样，甚至更好！”","notes":[]}]},"57":{"heading":"以色列拜偶像被定罪","verses":[{"n":1,"t":"义人死亡，无人放在心上；虔诚的人被接去，无人理解；义人被接去，以免祸患。","notes":[]},{"n":2,"t":"行为正直的人进入平安，得以在床上安歇。","notes":["“在床上安歇”或译“在坟里安息”。"]},{"n":3,"t":"到这里来吧！你们这些巫婆的儿子，奸夫和妓女的后代；","notes":[]},{"n":4,"t":"你们向谁戏笑？向谁张口吐舌呢？你们岂不是叛逆所生的儿女，虚谎所生的后代吗？","notes":[]},{"n":5,"t":"你们在橡树中间，在各青翠的树下欲火攻心；在山谷间，在岩隙下杀了儿女；","notes":["“橡树”或译“神像”。"]},{"n":6,"t":"去拜谷中光滑的石头有你们的份，这些就是你们的命运。你向它们献浇酒祭，献供物，这事我岂能容忍吗？","notes":[]},{"n":7,"t":"你在高而又高的山上安设床铺，上那里去献祭。","notes":[]},{"n":8,"t":"你在门后，在门框后，立起你的牌来；你离弃了我，赤露己身，又爬上自己所铺宽阔的床铺，与它们立约；你喜爱它们的床，看着它们的赤体。","notes":["“赤体”：原文是“手”。"]},{"n":9,"t":"你带了油到摩洛那里，加上许多香水。你派遣使者往远方去，甚至降到阴间，","notes":["“摩洛”或译“王”。"]},{"n":10,"t":"因路途遥远，你就疲倦，却不说，这是枉然，以为能找到复兴之力，所以不觉疲惫。","notes":[]},{"n":11,"t":"你怕谁，因谁恐惧，竟说谎，不记得我，不将这事放在心上。是否因我许久闭口不言，你就不怕我了呢？","notes":[]},{"n":12,"t":"我可以宣告你的公义和你的作为，但它们与你无益。","notes":[]},{"n":13,"t":"你哀求的时候，让你所搜集的神像拯救你吧！风要把它们全都刮散，吹一口气就都吹走。但那投靠我的必得地产，承受我的圣山为业。","notes":["原文没有“神像”。"]},{"n":14,"t":"耶和华说：“你们要修筑，修筑，要预备道路，除掉我百姓路中的绊脚石。”","notes":[],"heads":["神应许帮助和医治"]},{"n":15,"t":"那至高无上、永远长存、名为圣者的如此说：“我住在至高至圣的所在，却与心灵痛悔的谦卑人同住；要使谦卑的人心灵苏醒，使痛悔的人内心复苏。","notes":[]},{"n":16,"t":"我必不长久控诉，也不永远怀怒，因为我虽使灵性发昏，我也造了人的气息。","notes":[]},{"n":17,"t":"我因人贪婪的罪孽，发怒击打他；我转脸向他发怒，他却仍随意背道而行。","notes":[]},{"n":18,"t":"我看见他的行为，要医治他，引导他，使他和与他一同哀伤的人都得安慰。","notes":["“引导他”：七十士译本是“安慰他”。"]},{"n":19,"t":"我要医治他，他要结出嘴唇的果实。平安，平安，归给远处和近处的人！这是耶和华说的。”","notes":[]},{"n":20,"t":"但是恶人好像翻腾的海，不得平静；其中的水常涌出污秽和淤泥。","notes":[]},{"n":21,"t":"我的神说：“恶人必不得平安！”","notes":[]}]},"58":{"heading":"真正的禁食","verses":[{"n":1,"t":"你要大声喊叫，不要停止；要扬声，好像吹角；向我的百姓宣告他们的过犯，向雅各家陈述他们的罪恶。","notes":[]},{"n":2,"t":"他们天天寻求我，乐意明白我的道，好像行义的国家，未离弃它的神的典章；他们向我求问公义的判词，喜悦亲近神。","notes":[]},{"n":3,"t":"“我们禁食，你为何不看呢？我们刻苦己心，你为何不理会呢？”看哪，你们禁食的时候仍追求私利，剥削为你们做苦工的人。","notes":[]},{"n":4,"t":"看哪，你们禁食，却起纷争兴讼，以凶恶的拳头打人。你们今日这种禁食无法使你们的声音听闻于高处。","notes":[]},{"n":5,"t":"这岂是我所要的禁食，为人所用以刻苦己心的日子吗？我难道只是叫人如芦苇般低头，铺上麻布和灰烬吗？你能称此为禁食，为耶和华所悦纳的日子吗？","notes":[]},{"n":6,"t":"我所要的禁食，岂不是要你松开凶恶的绳，解开轭上的索，使被欺压的得自由，折断一切的轭吗？","notes":[]},{"n":7,"t":"岂不是要你把食物分给饥饿的人，将流浪的穷人接到家中，见赤身的给他衣服遮体，而不隐藏自己避开你的骨肉吗？","notes":[]},{"n":8,"t":"这样，必有光如晨光破晓照耀你，你也要快快得到医治；你的公义在你前面行，耶和华的荣光必作你的后盾。","notes":[]},{"n":9,"t":"那时你求告，耶和华必应允；你呼求，他必说：“我在这里。”你若从你中间除掉重轭和指摘人的指头，并发恶言的事，","notes":[]},{"n":10,"t":"向饥饿的人施怜悯，使困苦的人得满足；你在黑暗中就必得着光明，你的幽暗必变如正午。","notes":[]},{"n":11,"t":"耶和华必时常引导你，在干旱之地使你心满意足，又使你骨头强壮。你必如有水浇灌的园子，又像水流不绝的泉源。","notes":[]},{"n":12,"t":"你们中间必有人起来修造久已荒废之处，立起代代相承的根基。你必称为修补裂痕的，和重修路径给人居住的。","notes":[]},{"n":13,"t":"你若禁止自己的脚践踏安息日，不在我的圣日做自己高兴的事，称安息日为“可喜乐的”，称耶和华的圣日为“可尊重的”，尊敬这日，不走自己的道路，不求自己的喜悦，也不随意说话；","notes":[],"heads":["守安息日者的报偿"]},{"n":14,"t":"那么，你就会以耶和华为乐。耶和华要使你乘驾于地的高处，又要以你祖先雅各的产业养育你；这是耶和华亲口说的。","notes":[]}]},"59":{"heading":"先知指责百姓的罪恶","verses":[{"n":1,"t":"看哪，耶和华的膀臂并非过短，不能拯救，耳朵并非发沉，不能听见，","notes":[]},{"n":2,"t":"但你们的罪孽使你们与神隔绝，你们的罪恶使他转脸不听你们。","notes":[]},{"n":3,"t":"因你们的手掌被血沾染，你们的指头被罪玷污，你们的嘴唇说谎言，你们的舌头出恶语。","notes":[]},{"n":4,"t":"无人按公义控诉，也无人凭诚实辩白；却倚靠虚妄，口说谎言，怀毒害，生罪孽。","notes":[]},{"n":5,"t":"他们孵毒蛇蛋，结蜘蛛网。凡吃这蛋的必死，蛋一打破，就孵出蛇来。","notes":[]},{"n":6,"t":"所结的网不能当衣服，无法掩盖自己所作所为。他们的行为全是邪恶，手所做的尽都残暴。","notes":[]},{"n":7,"t":"他们的脚奔跑行恶，急速流无辜者的血；他们的思想全是恶念，走过的路尽是破坏与毁灭。","notes":[]},{"n":8,"t":"平安的路，他们不知道，所行的事无一公平。他们为自己修筑弯曲的路，凡走这路的都不得平安。","notes":[]},{"n":9,"t":"因此，公平离我们甚远，公义追不上我们。我们指望光亮，看哪，却只有黑暗，指望光明，却行在幽暗中。","notes":[],"heads":["百姓悔罪"]},{"n":10,"t":"我们用手摸墙，好像盲人，四处摸索，如同失明的人；中午时我们绊倒，如在黄昏一样，在强壮的人中，我们好像死人一般。","notes":[]},{"n":11,"t":"我们全都咆哮如熊，哀鸣如鸽子；指望公平，却得不着；指望救恩，它却远离。","notes":[]},{"n":12,"t":"我们的过犯在你面前增加，罪恶作证控告我们；过犯与我们同在。至于我们的罪孽，我们都知道：","notes":[]},{"n":13,"t":"就是悖逆，否认耶和华，转去不跟从我们的神，口说欺压和叛逆的话，心怀谎言，随即说出；","notes":[]},{"n":14,"t":"公平转而退后，公义站在远处，诚实仆倒在广场上，正直不得进入；","notes":[]},{"n":15,"t":"诚实少见，离弃邪恶的人反成掠物。那时，耶和华见没有公平，就不喜悦。","notes":[]},{"n":16,"t":"他见无人，竟无一人代求，甚为诧异，就用自己的膀臂拯救他，以公义扶持他。","notes":[]},{"n":17,"t":"他穿上公义为铠甲，戴上救恩为头盔，穿上报复为衣服，披戴热心为外袍。","notes":[]},{"n":18,"t":"他必按人的行为报应，恼怒他的敌人，报复他的仇敌，向众海岛施行报应。","notes":[]},{"n":19,"t":"在日落之处，人必敬畏耶和华的名；在日出之地，人必敬畏他的荣耀。他必如湍急的河流冲来，耶和华的灵催逼他自己。","notes":[]},{"n":20,"t":"必有一位救赎主来到锡安，来到雅各族中离弃过犯的人那里；这是耶和华说的。","notes":[]},{"n":21,"t":"耶和华说：“这就是我与他们所立的约：我加给你的灵，传给你的话，必不离你的口，也不离你后裔与你后裔之后裔的口，从今直到永远；这是耶和华说的。”","notes":[]}]},"60":{"heading":"耶路撒冷未来的荣耀","verses":[{"n":1,"t":"兴起，发光！因为你的光已来到！耶和华的荣光发出照耀着你。","notes":[]},{"n":2,"t":"看哪，黑暗笼罩大地，幽暗遮盖万民，耶和华却要升起照耀你，他的荣光要显在你身上。","notes":[]},{"n":3,"t":"列国要来就你的光，列王要来就你发出的光辉。","notes":[]},{"n":4,"t":"你举目向四围观看，众人都聚集到你这里。你的儿子从远方来，你的女儿也被抱着带来。","notes":[]},{"n":5,"t":"那时，你看见就有光荣，你的心兴奋欢畅；因为大海那边的财富必归你，列国的财宝也来归你。","notes":["“欢畅”：原文是“宽阔”。"]},{"n":6,"t":"成群的骆驼，并米甸和以法的独峰驼遮满你；示巴的众人都必来到，要奉上黄金和乳香，又要传扬赞美耶和华的话。","notes":[]},{"n":7,"t":"基达的羊群都聚集到你这里，尼拜约的公羊供你使用，献在我坛上蒙悦纳；我必荣耀我那荣耀的殿。","notes":[]},{"n":8,"t":"那些飞来如云、又像鸽子飞向窗户的是谁呢？","notes":[]},{"n":9,"t":"众海岛必等候我，他施的船只领先，将你的儿女，连同他们的金银从远方带来，这都因以色列的圣者、耶和华－你神的名，因为他已经荣耀了你。","notes":["“众海岛必等候我”：原文另译“众海岛的船只聚集”。"]},{"n":10,"t":"外邦人要建造你的城墙，他们的君王必服事你。我曾发怒击打你，如今却施恩怜悯你。","notes":[]},{"n":11,"t":"你的城门必时常开放，昼夜不关，使人将列国的财物带来归你，他们的君王也被牵引而来。","notes":[]},{"n":12,"t":"不事奉你的那邦、那国要灭亡，那些国家必全然荒废。","notes":[]},{"n":13,"t":"黎巴嫩的荣耀，就是松树、杉树、黄杨树，都必一同归你，用以装饰我圣所坐落之处；我也要使我脚所踏之地得荣耀。","notes":[]},{"n":14,"t":"压制你的，他的子孙必来向你屈身；藐视你的，都要在你脚前下拜。人要称你为“耶和华的城”，为“以色列圣者的锡安”。","notes":[]},{"n":15,"t":"你虽曾被抛弃，被恨恶，甚至无人经过，我却使你有永远的荣华，成为世世代代的喜乐。","notes":[]},{"n":16,"t":"你要吃列国的奶，吃列王的乳。你就知道我－耶和华是你的救主，是你的救赎主，是雅各的大能者。","notes":[]},{"n":17,"t":"我要赏赐金子代替铜，赏赐银子代替铁，铜代替木头，铁代替石头。我要以和平为你的官长，以公义为你的监督。","notes":[]},{"n":18,"t":"你的地不再听闻残暴的事，境内不再听见破坏与毁灭。你必称你的墙为“拯救”，称你的门为“赞美”。","notes":[]},{"n":19,"t":"白昼太阳不再作你的光，月亮也不再发光照耀你；耶和华却要作你永远的光，你的神要成为你的荣耀。","notes":["“月亮”：有古卷和七十士译本是“夜晚月亮”。"]},{"n":20,"t":"你的太阳不再落下，月亮也不消失；因为耶和华必作你永远的光。你悲哀的日子定要结束。","notes":[]},{"n":21,"t":"你的居民全是义人，永远得地为业；他们是我栽的苗，是我手的工作，为了彰显我的荣耀。","notes":[]},{"n":22,"t":"稀少的要成为大族，弱小的要变为强国。我－耶和华到了时候必速速成就这事。","notes":[]}]},"61":{"heading":"拯救的好消息","verses":[{"n":1,"t":"主耶和华的灵在我身上，因为耶和华用膏膏我，叫我报好信息给贫穷的人，差遣我医好伤心的人，报告被掳的得释放，被捆绑的得自由；","notes":[]},{"n":2,"t":"宣告耶和华的恩年和我们的神报仇的日子；安慰所有悲哀的人，","notes":[]},{"n":3,"t":"为锡安悲哀的人，赐华冠代替灰烬，喜乐的油代替悲哀，赞美为衣代替忧伤的灵；称他们为“公义树”，是耶和华所栽植的，为要彰显他的荣耀。","notes":[]},{"n":4,"t":"他们必修造久已荒凉的废墟，建立先前凄凉之处，重修历代荒凉之城。","notes":[]},{"n":5,"t":"那时，陌生人要伺候、牧放你们的羊群；外邦人必为你们耕种田地，修整你们的葡萄园。","notes":[]},{"n":6,"t":"但你们要称为“耶和华的祭司”，称作“我们神的仆人”。你们必享用列国的财物，必承受他们的财富。","notes":["“必...财富”：死海古卷和七十士译本是“因得他们的荣耀自夸”。"]},{"n":7,"t":"因为他们所受双倍的羞辱，凌辱被称为他们的命运，因此，他们在境内必得双倍的产业，永远之乐必归给他们。","notes":[]},{"n":8,"t":"因为我－耶和华喜爱公平，恨恶抢夺与恶行；我要凭诚实施行报偿，与我的百姓立永约。","notes":["“恨恶抢夺与恶行”：有古卷是“恨恶抢夺又献燔祭”。"]},{"n":9,"t":"他们的后裔必在列国中为人所知，他们的子孙在万民中为人所识；凡看见他们的必承认他们是耶和华所赐福的后裔。","notes":[]},{"n":10,"t":"我因耶和华大大欢喜，我的心因神喜乐；因他以拯救为衣给我穿上，以公义为外袍给我披上，好像新郎戴上华冠，又如新娘佩戴首饰。","notes":[]},{"n":11,"t":"地怎样使芽长出，园子怎样使所栽种的生长，主耶和华也必照样使公义和赞美在万国中发出。","notes":[]}]},"62":{"heading":"","verses":[{"n":1,"t":"我因锡安必不静默，为耶路撒冷必不安宁，直到它的公义如光辉发出，它的救恩如火把燃烧。","notes":[]},{"n":2,"t":"列国要看见你的公义，列王要看见你的荣耀。你必得新的名字，是耶和华亲口起的。","notes":[]},{"n":3,"t":"你在耶和华的手中成为华冠，在你神的掌上成为冠冕。","notes":[]},{"n":4,"t":"你不再称为“被撇弃的”，你的地也不再称为“荒芜的”；你要称为“我所喜悦的”，你的地要称为“有归属的”。因为耶和华喜悦你，你的地必归属于他。","notes":[]},{"n":5,"t":"年轻人怎样娶童女，你的百姓也要照样娶你；新郎怎样因新娘而喜乐，你的神也要如此以你为乐。","notes":[]},{"n":6,"t":"耶路撒冷啊，我在你城墙上设立守望者，他们昼夜不停地呼喊。呼求耶和华的啊，你们不要歇息，","notes":[]},{"n":7,"t":"也不要使他歇息，直等他建立耶路撒冷，使耶路撒冷在地上为人所赞美。","notes":[]},{"n":8,"t":"耶和华指着自己的右手和大能的膀臂起誓说：“我必不再将你的五谷给仇敌作食物，外邦人也必不再喝你劳碌得来的新酒。","notes":[]},{"n":9,"t":"惟有那收割的要吃，并赞美耶和华；那储藏葡萄的要在我圣所院内喝。”","notes":[]},{"n":10,"t":"你们当从门经过，经过，预备百姓的路。你们要修筑，修筑大道，清除石头，为万民竖立大旗。","notes":[]},{"n":11,"t":"看哪，耶和华曾宣告到地极，你们要对锡安说：“看哪，你的拯救者已来到。看哪，他的赏赐在他那里，他的报偿在他面前。”","notes":["“锡安”：原文直译“锡安女子”。"]},{"n":12,"t":"人称他们为“圣民”，为“耶和华救赎的民”，你也必称为“受眷顾的”，为“不被撇弃的城”。","notes":[]}]},"63":{"heading":"耶和华恩待以色列","verses":[{"n":1,"t":"这从以东的波斯拉来，穿红衣服，装扮华美，能力广大，大步向前迈进的是谁呢？就是我，凭公义说话，以大能施行拯救的。","notes":[]},{"n":2,"t":"你为何以红色装扮？你的衣服为何像踹榨酒池的人呢？","notes":[]},{"n":3,"t":"我独自踹榨酒池，万民中并无一人与我同在。我发怒，将他们踹下，发烈怒将他们践踏。他们的血溅在我的衣服上，玷污了我一切的衣裳。","notes":[]},{"n":4,"t":"因为报仇之日在我心中，救赎我民之年已经来到。","notes":[]},{"n":5,"t":"我仰望，见无人帮助；我诧异，竟无人扶持。因此，我的膀臂为我施行拯救；我的烈怒将我扶持。","notes":[]},{"n":6,"t":"我发怒，踹下众民；发烈怒，使他们喝醉，又将他们的血倒在地上。","notes":[]},{"n":7,"t":"我要照耶和华一切所赐给我们的，并他凭怜悯与丰盛的慈爱所赐给以色列家的大恩，述说他的慈爱和美德。","notes":[],"heads":["耶和华怜悯以色列"]},{"n":8,"t":"他说：“他们诚然是我的百姓，未行虚假的子民。”这样，他就作了他们的救主。","notes":[]},{"n":9,"t":"他们在一切苦难当中，他也同受苦难，并且他面前的使者拯救他们。他以慈爱和怜悯救赎他们，在古时的日子时常抱他们，背他们。","notes":["“他也...拯救他们”：七十士译本是“没有使者或天使，只有主亲自拯救他们”。"]},{"n":10,"t":"他们竟然悖逆，使他的圣灵忧伤。他就转变，成为他们的仇敌，亲自攻击他们。","notes":[]},{"n":11,"t":"那时，他的百姓想起古时摩西的日子：“那将百姓和牧养群羊的人从海里领上来的在哪里呢？那将圣灵降在他们中间，","notes":[]},{"n":12,"t":"以荣耀的膀臂在摩西右边行动，在百姓面前将水分开，为要建立自己永远的名，","notes":[]},{"n":13,"t":"又带领他们经过深处的在哪里呢？”他们如马行走旷野，不致绊跌；","notes":[]},{"n":14,"t":"又如牲畜下到山谷，耶和华的灵使他们得安息；照样，你也引导你的百姓，为要建立自己荣耀的名。","notes":[]},{"n":15,"t":"求你从天上，从你神圣荣耀的居所垂顾观看。你的热心和你大能的作为在哪里呢？你内心的关怀和你的怜悯向我们停止了。","notes":[],"heads":["求主怜悯帮助"]},{"n":16,"t":"亚伯拉罕虽然不承认我们，以色列也不承认我们，你却是我们的父。耶和华啊，你是我们的父；自古以来，你的名是“我们的救赎主”。","notes":[]},{"n":17,"t":"耶和华啊，你为何使我们偏离你的道，使我们心里刚硬、不敬畏你呢？求你为你的仆人，为你产业的支派而回转。","notes":[]},{"n":18,"t":"你的圣民暂时得你的圣所，但我们的敌人践踏了它。","notes":["本节或译“我们的敌人暂时赶出你的圣民，他们践踏了你的圣所。”"]},{"n":19,"t":"我们就成了你未曾治理的人，成了未曾称为你名下的人。","notes":[]}]},"64":{"heading":"","verses":[{"n":1,"t":"愿你破天而降，愿山在你面前震动，","notes":[]},{"n":2,"t":"好像火烧干柴，又如火将水烧开，使你敌人知道你的名，列国必在你面前发颤！","notes":[]},{"n":3,"t":"你曾做我们不能逆料可畏的事；那时你降临，山岭在你面前震动。","notes":[]},{"n":4,"t":"自古以来，人未曾听见，未曾耳闻，未曾眼见，除你以外，还有神能为等候他的人行事。","notes":[]},{"n":5,"t":"你迎见那欢喜行义、记念你道的人；看哪，你曾发怒，因我们犯了罪；这景况已久，我们还能得救吗？","notes":[]},{"n":6,"t":"我们都如不洁净的人，所行的义都像污秽的衣服。我们如叶子渐渐枯干，罪孽像风把我们吹走。","notes":[]},{"n":7,"t":"无人求告你的名，无人奋力抓住你。你转脸不顾我们，你使我们因罪孽而融化。","notes":["“你使...融化”：七十士译本和其他古译本是“你把我们交给罪孽”。"]},{"n":8,"t":"但耶和华啊，现在你仍是我们的父！我们是泥，你是陶匠；我们都是你亲手所造的。","notes":[]},{"n":9,"t":"耶和华啊，求你不要大发震怒，也不要永远记得罪孽；看哪，求你垂顾我们，因我们都是你的百姓。","notes":[]},{"n":10,"t":"你的圣城已变为旷野；锡安变为旷野，耶路撒冷成为废墟。","notes":[]},{"n":11,"t":"我们那神圣华美的殿，就是我们祖先赞美你的地方，已被火焚烧；我们所羡慕的美地尽都荒芜。","notes":[]},{"n":12,"t":"耶和华啊，有这些事，你还能忍受吗？你还静默，使我们大受苦难吗？","notes":[]}]},"65":{"heading":"神惩罚悖逆者","verses":[{"n":1,"t":"“没有求问我的，我要让他们找到；没有寻找我的，我要让他们寻见；我对没有呼求我名的国说：‘我在这里！我在这里！’","notes":["“我对...的国”是根据死海古卷；原文是“我对没有称为我名下的国”。"]},{"n":2,"t":"我整天向那悖逆的百姓招手，他们随自己的意念行不善之道。","notes":[]},{"n":3,"t":"这百姓时常当面惹我发怒，在园中献祭，在砖上烧香，","notes":[]},{"n":4,"t":"在坟墓间停留，在隐密处过夜，吃猪肉，器皿中有不洁净之肉熬的汤；","notes":[]},{"n":5,"t":"且对人说：‘你站开吧！不要挨近我，因为我对你来说太神圣了。’这些人惹我鼻中冒烟，如终日燃烧的火。","notes":["“我对你...神圣了”：原文另译“我会使你成为圣”。"]},{"n":6,"t":"看哪，这些都写在我面前。我必不静默，却要施行报应，将你们和你们祖先的罪孽全都报应在后人身上；因为他们在山上烧香，在冈上亵渎我，我要按他们先前所行的，报应在他们身上；这是耶和华说的。”","notes":["“身上”：原文是“怀中”。"],"end":7},{"n":8,"t":"耶和华如此说：“人在葡萄中寻得新酒时会说：‘不要毁坏它，因为它还有用处’；同样，我必因我仆人的缘故，不将他们全然毁灭。","notes":[]},{"n":9,"t":"我必从雅各中领出后裔，从犹大中领出那要继承我众山的；我的选民要继承它，我的仆人要在那里居住。","notes":[]},{"n":10,"t":"沙仑必成为羊群的圈，亚割谷成为牛群躺卧之处，都为寻求我的民所得。","notes":[]},{"n":11,"t":"但你们这些离弃耶和华，就是忘记我的圣山、为‘幸运之神’摆设筵席、为‘命运之神’装满调和酒的，","notes":[]},{"n":12,"t":"我命定你们归于刀下，你们都要屈身被杀；因为我呼唤，你们不回应；我说话，你们不听从；反倒做我眼中看为恶的事，选择我所不喜悦的事。”","notes":[]},{"n":13,"t":"所以，主耶和华如此说：“看哪，我的仆人必得吃，你们却饥饿；看哪，我的仆人必得喝，你们却干渴；看哪，我的仆人必欢喜，你们却蒙羞。","notes":[]},{"n":14,"t":"看哪，我的仆人因心中喜乐而欢呼，你们却因心里悲痛而哀哭，因灵里忧伤而哀号。","notes":[]},{"n":15,"t":"你们必留下自己的名给我选民指着赌咒：主耶和华必杀你们，另起别名称呼他的仆人。","notes":[]},{"n":16,"t":"在地上为自己求福的，必凭真实的神求福；在地上起誓的，必指着真实的神起誓。因为从前的患难已被遗忘，从我眼前消逝。”","notes":[]},{"n":17,"t":"“看哪，我造新天新地！从前的事不再被记念，也不被人放在心上；","notes":[],"heads":["新天新地"]},{"n":18,"t":"当因我所造的欢喜快乐，直到永远；看哪，因为我造耶路撒冷为人所喜，造其中的居民为人所乐。","notes":[]},{"n":19,"t":"我必因耶路撒冷欢喜，因我的百姓快乐，那里不再听见哭泣和哀号的声音。","notes":[]},{"n":20,"t":"那里没有数日夭折的婴孩，也没有寿数不满的老人；因为百岁死的仍算孩童，未达百岁而亡的算是被诅咒的。","notes":["“未达百岁而亡的”或译“百岁死的罪人”。"]},{"n":21,"t":"他们建造房屋，居住其中，栽葡萄园，吃园中的果子；","notes":[]},{"n":22,"t":"并非造了给别人居住，也非栽种给别人享用；因为我百姓的日子必长久如树木，我的选民必享受亲手劳碌得来的。","notes":[]},{"n":23,"t":"他们必不徒然劳碌，所生产的，也不遭灾害，因为他们和他们的子孙都是蒙耶和华赐福的后裔。","notes":[]},{"n":24,"t":"他们尚未求告，我就应允；正说话的时候，我就垂听。","notes":[]},{"n":25,"t":"野狼必与羔羊同食，狮子必吃草，与牛一样，蛇必以尘土为食物；在我圣山的遍处，它们都不伤人，也不害物；这是耶和华说的。”","notes":[]}]},"66":{"heading":"耶和华审判万民","verses":[{"n":1,"t":"耶和华如此说：“天是我的座位；地是我的脚凳。你们能为我造怎样的殿宇呢？哪里是我安歇的地方呢？","notes":[]},{"n":2,"t":"这一切是我手所造的，这一切就都存在了。我所看顾的是困苦、灵里痛悔、因我言语而战兢的人。这是耶和华说的。","notes":[]},{"n":3,"t":"“至于那些宰牛，杀人，献羔羊，打断狗颈项，献猪血为供物，烧乳香，称颂偶像的，他们选择自己的道路，心里喜爱可憎恶的事；","notes":[]},{"n":4,"t":"我也必选择苦待他们，使他们所惧怕的临到他们；因为我呼唤，无人回应；我说话，他们不听从；反倒做我眼中看为恶的事，选择我所不喜悦的事。”","notes":[]},{"n":5,"t":"你们因耶和华言语而战兢的人哪，当听他的话：“你们的弟兄，就是恨恶你们，因我名赶出你们的，曾说：‘愿耶和华彰显荣耀，好让我们看见你们的喜乐。’但蒙羞的终究是他们！","notes":["“愿耶和华彰显荣耀”：七十士译本是“愿主的名得荣耀”。"]},{"n":6,"t":"“有喧哗的声音出自城中！有声音来自殿里！是耶和华向仇敌施行报应的声音！","notes":[]},{"n":7,"t":"“锡安未曾阵痛就生产，疼痛尚未来到，就生出男孩。","notes":[]},{"n":8,"t":"国岂能一日而生？民岂能一时而产？但锡安一阵痛就生下儿女，这样的事有谁听见，有谁看见呢？","notes":[]},{"n":9,"t":"耶和华说：我使人临产，岂不让她生产呢？你的神说：我使人生产，难道还让她关闭不生吗？","notes":["“她”：本修订版的“国”和“城”的代名词都用“它”；本章用“她”。","“关闭”意思是“关闭子宫”。"]},{"n":10,"t":"“你们所有爱慕耶路撒冷的啊，要与她一同欢喜，为她高兴；你们所有为她悲哀的啊，都要与她一同乐上加乐；","notes":[]},{"n":11,"t":"使你们在她安慰的怀中吃奶得饱，尽情吸取她丰盛的荣耀，满心喜乐。”","notes":[]},{"n":12,"t":"耶和华如此说：“看哪，我要使平安临到她，好像江河；使列国的荣耀及于她，如同涨溢的溪流。你们要尽情吸吮；你们必被抱在身旁，摇弄在膝上。","notes":["“你们要...身旁”：七十士译本是“她的孩子必举在肩膀上”。"]},{"n":13,"t":"我要安慰你们，如同母亲安慰儿女；你们也必在耶路撒冷得安慰。","notes":[]},{"n":14,"t":"你们看见，心里就喜乐，你们的骨头必如草生长；耶和华的手在他仆人身上彰显，他却要向他的仇敌发怒。”","notes":[]},{"n":15,"t":"看哪，耶和华必在火中降临，他的战车宛如暴风，以烈怒施行报应，以火焰施行责罚；","notes":[]},{"n":16,"t":"耶和华必以火与刀审判凡有血肉之躯的，被耶和华所杀的很多。","notes":[]},{"n":17,"t":"“那些洁净自己献给偶像，进入园内，跟随在其中一个人去吃猪肉和鼠肉，并可憎之物的，他们必一同灭绝。这是耶和华说的。","notes":[]},{"n":18,"t":"“我知道他们的行为和他们的意念。聚集万国万族的时候到了，他们要来瞻仰我的荣耀；","notes":["“族”：原文是“舌头”，即“语言”。","“聚集...到了”：七十士译本是“我要来聚集万国万族”。"]},{"n":19,"t":"我要在他们中间显神迹，差遣他们当中的幸存者到列国去，就是到他施、普勒、以善射闻名的路德、土巴、雅完，和未曾听见我名声，未曾看见我荣耀的遥远海岛那里去；他们必在列国中传扬我的荣耀。","notes":["“普勒”：七十士译本是“普特”，现在的利比亚。","“以善射闻名的路德”：七十士译本是“路德、默舍克”。"]},{"n":20,"t":"他们要将你们的弟兄从列国中带回，或骑马，或坐车，或乘蓬车，或骑骡子，或骑独峰驼，到我的圣山耶路撒冷，作为供物献给耶和华。这是耶和华说的。正如以色列人用洁净的器皿盛供物奉到耶和华的殿中，","notes":[]},{"n":21,"t":"我也必从他们中间立人作祭司，作利未人。这是耶和华说的。","notes":[]},{"n":22,"t":"“我所造的新天新地在我面前长存，你们的后裔和你们的名号也必照样长存。这是耶和华说的。","notes":[]},{"n":23,"t":"每逢初一、安息日，凡有血肉之躯的必前来，在我面前下拜；这是耶和华说的。","notes":[]},{"n":24,"t":"“他们要出去观看那些违背我的人的尸首，他们的虫是不死的，他们的火是不灭的，凡有血肉之躯的都必憎恶他们。”","notes":[]}]}},"JER":{"1":{"heading":"耶利米蒙选召","verses":[{"n":1,"t":"这些是便雅悯地亚拿突城的祭司，希勒家的儿子耶利米的话。","notes":[]},{"n":2,"t":"亚们的儿子犹大王约西亚在位第十三年，耶和华的话临到耶利米。","notes":[]},{"n":3,"t":"从约西亚的儿子犹大王约雅敬在位的时候，直到约西亚的儿子犹大王西底家在位的末年，就是第十一年五月间耶路撒冷被掳时，耶和华的话也常临到耶利米。","notes":[]},{"n":4,"t":"耶利米说，耶和华的话临到我，说：","notes":[]},{"n":5,"t":"“我尚未将你造在母腹中，就已认识你；你未出母胎，我已将你分别为圣，派你作列国的先知。”","notes":[]},{"n":6,"t":"我就说：“唉，主耶和华！看哪，我不知道怎么说，因为我年轻。”","notes":[]},{"n":7,"t":"耶和华对我说：“不要说‘我年轻’，因为我差遣你到谁那里去，你都要去；我吩咐你说什么话，你都要说。","notes":[]},{"n":8,"t":"你不要怕他们，因为我与你同在，要拯救你。这是耶和华说的。”","notes":[]},{"n":9,"t":"于是耶和华伸手按住我的口，对我说：“看哪，我已将我的话放在你口中。","notes":[]},{"n":10,"t":"我今日立你在列邦列国之上，为要拔出，拆毁，毁坏，倾覆，又要建立，栽植。”","notes":[]},{"n":11,"t":"耶和华的话临到我，说：“耶利米，你看见什么？”我说：“我看见一根杏树枝。”","notes":[],"heads":["两个异象"]},{"n":12,"t":"耶和华对我说：“你看得不错；因为我要看守我的话，使它实现。”","notes":["“看守”与“杏树枝”的希伯来话发音相近。"]},{"n":13,"t":"耶和华的话第二次临到我，说：“你看见什么？”我说：“我看见一个水烧开的锅，从北而倾。”","notes":[]},{"n":14,"t":"耶和华对我说：“必有灾祸从北方发出，临到这地所有的居民。","notes":[]},{"n":15,"t":"看哪，我要召北方列国的万族。这是耶和华说的。他们要来，各安宝座在耶路撒冷的城门口，周围攻击城墙，又要攻击犹大的一切城镇。","notes":[]},{"n":16,"t":"这民离弃我，向别神烧香，跪拜自己手所造的，我要针对这一切恶行，向他们宣读我的判决。","notes":[]},{"n":17,"t":"所以你当束腰，起来，将我所吩咐你的一切话都告诉他们；不要因他们惊惶，免得我使你在他们面前惊惶。","notes":[]},{"n":18,"t":"看哪，我今日使你成为坚城、铁柱、铜墙，对抗全地和犹大的君王、官长、祭司，并这地的百姓。","notes":[]},{"n":19,"t":"他们要攻击你，却不能胜过你，因为我与你同在，要拯救你。这是耶和华说的。”","notes":[]}]},"2":{"heading":"神眷顾以色列","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“你去向耶路撒冷居民的耳朵呼喊，耶和华如此说：‘你年轻时的恩爱，新婚时的爱情，你怎样在旷野，在未耕种之地跟随我，我都记得。","notes":[]},{"n":3,"t":"那时以色列归耶和华为圣，作为他初熟的土产；凡吞吃它的必算为有罪，灾祸必临到他们。这是耶和华说的。’”","notes":[]},{"n":4,"t":"雅各家，以色列家的各族啊，当听耶和华的话，","notes":[],"heads":["以色列祖先的罪恶"]},{"n":5,"t":"耶和华如此说：“你们的祖先看我有什么错处，竟远离我，随从那虚无的神明，自己成为虚无呢？","notes":["“虚无的神明”：原文是“虚无”。"]},{"n":6,"t":"他们并不问：‘那领我们从埃及地上来，引导我们走过旷野、沙漠有坑洞之地，走过干旱死荫、无人经过、无人居住之地的耶和华在哪里呢？’","notes":[]},{"n":7,"t":"我领你们进入肥沃之地，使你们得吃其中的果子和美物；你们进入时，却使我的地玷污，使我的产业成为可憎的。","notes":[]},{"n":8,"t":"祭司从来不问：‘耶和华在哪里呢？’传讲律法的不认识我，官长违背我，先知藉巴力说预言，随从无益的东西。”","notes":[]},{"n":9,"t":"“我因此必与你们争辩，也与你们的子孙争辩。这是耶和华说的。","notes":[],"heads":["神谴责他的子民"]},{"n":10,"t":"你们且渡到基提海岛察看，派人往基达去留心查考，看可曾有过这样的事。","notes":[]},{"n":11,"t":"岂有一国换了它的神明吗？其实那不是神明！但我的百姓将他们的荣耀换了那无益的东西。","notes":[]},{"n":12,"t":"诸天哪，要因此震惊，颤栗，极其凄凉！这是耶和华说的。","notes":[]},{"n":13,"t":"因为我的百姓做了两件恶事：离弃我这活水的泉源；又为自己凿出水池，却是破裂不能储水的池子。”","notes":[]},{"n":14,"t":"“以色列是仆人吗？是家中生的奴仆吗？为何成为掠物呢？","notes":[],"heads":["以色列不忠的结局"]},{"n":15,"t":"少壮狮子向它咆哮，大声吼叫，使它的地荒芜；城镇烧毁，无人居住。","notes":[]},{"n":16,"t":"挪弗人和答比匿人打破你的头颅。","notes":["“挪弗”即埃及的孟斐斯；本卷书44．1，46．14、19同。"]},{"n":17,"t":"这不是你自己招惹的吗？不是因耶和华－你神引导你行路时，你离弃了他吗？","notes":[]},{"n":18,"t":"现今你为何在埃及路上喝西曷河的水呢？为何在亚述路上喝大河的水呢？","notes":["“西曷河”是尼罗河的支流。"]},{"n":19,"t":"你自己的恶必惩治你，你背道的事必责罚你。由此可知可见，你离弃耶和华－你的神，不存敬畏我的心，实为恶事，为苦事；这是万军之主耶和华说的。”","notes":[]},{"n":20,"t":"“你在古时折断你的轭，解开你的绳索，说：‘我必不事奉耶和华。’你在各高冈上、各青翠的树下屈身行淫。","notes":["“你”是根据七十士译本；原文是“我”。","“不事奉耶和华”：原文另译“不作恶”。"],"heads":["以色列拒绝敬拜耶和华"]},{"n":21,"t":"然而，我栽种你为上等的葡萄树，全用纯正的种子；你怎么向我变为外邦葡萄树的坏枝子呢？","notes":[]},{"n":22,"t":"你虽用碱、多用皂荚清洗，你罪孽的痕迹仍显在我面前。这是主耶和华说的。","notes":[]},{"n":23,"t":"你怎能说：‘我没有玷污，没有随从巴力’？看看你在谷中所做的，思想你自己的所作所为；你是快行的独峰驼，狂奔乱闯。","notes":[]},{"n":24,"t":"你是野驴，习惯旷野，欲心发动时就呼吸急促，发情时谁能使它转回呢？凡寻找它的必不费力，在它的季节必能寻见它。","notes":[]},{"n":25,"t":"你不要弄到赤足而行，喉咙干渴。你却说：‘没有用的，我喜爱陌生人，我必随从他们。’”","notes":[]},{"n":26,"t":"“贼被捉拿，怎样羞愧，以色列家和他们的君王、官长、祭司、先知也都照样羞愧。","notes":[],"heads":["以色列该受惩罚"]},{"n":27,"t":"他们向木头说：‘你是我的父’；向石头说：‘你是生我的。’他们以背向我，不肯以面向我；及至遭遇患难时却说：‘起来拯救我们吧！’","notes":[]},{"n":28,"t":"你为自己做的神明在哪里呢？你遭遇患难的时候，让它们起来拯救你吧！犹大啊，你神明的数目与你城的数目相等。","notes":[]},{"n":29,"t":"“你们为何与我争辩呢？你们都违背了我。这是耶和华说的。","notes":[]},{"n":30,"t":"我责打你们的儿女是徒然的，他们不受管教。你们自己的刀吞灭你们的先知，好像残害人的狮子。","notes":[]},{"n":31,"t":"这世代的人哪，你们要留意耶和华的话。我向以色列岂是旷野，或幽暗之地呢？我的百姓为何说：‘我们脱离约束，不再归向你了’？","notes":[]},{"n":32,"t":"少女岂能忘记她的妆饰呢？新娘岂能忘记她的美衣呢？我的百姓却在无数的日子里忘记了我！","notes":[]},{"n":33,"t":"“你竟然如此精于求爱之道，可把你的门径教邪恶的女人！","notes":[]},{"n":34,"t":"你衣服的边上有无辜贫穷人的血，其实你并未发现他们挖洞进屋偷窃。虽有这一切的事，","notes":["参出22．2。","“其实...一切的事，”七十士译本是“我并没有在洞里找到他们，而是在每棵橡树底下。”"]},{"n":35,"t":"你还说：‘我无辜；耶和华的怒气必定转离我了。’看哪，我必审问你；因你自己说：‘我没有犯罪。’","notes":[]},{"n":36,"t":"你为何东奔西跑改变你的道路呢？你必因埃及蒙羞，像从前因亚述蒙羞一样。","notes":[]},{"n":37,"t":"你也必两手抱头离开这里；因为耶和华已经弃绝你所倚靠的，你不能因他们而得顺利。”","notes":[]}]},"3":{"heading":"不忠的以色列","verses":[{"n":1,"t":"耶和华说：“人若休妻，妻离他而去，做了别人的妻子，前夫岂能再回到她那里呢？那地岂不是大大污秽了吗？但你和许多情郎行淫，还是可以回到我这里。这是耶和华说的。","notes":["“耶和华说”或译“有话说”；七十士译本和其他古译本没有“耶和华说”。"]},{"n":2,"t":"你举目向光秃的高地观看，何处没有你的淫行呢？你坐在道路旁等候，好像阿拉伯人在旷野埋伏，你的淫行和邪恶使全地污秽了。","notes":[]},{"n":3,"t":"因此甘霖停止，春雨不降。你还是一副娼妓之脸，不顾羞耻。","notes":[]},{"n":4,"t":"你不是才向我呼叫说：‘我父啊，你是我年轻时的密友，","notes":[]},{"n":5,"t":"人岂永远怀恨，长久存怒吗？’看哪，你虽这样说，还是竭尽所能去行恶。”","notes":[]},{"n":6,"t":"约西亚王在位的时候，耶和华对我说：“你看见背道的以色列所做的吗？她上到各高山，在各青翠的树下行淫。","notes":[],"heads":["以色列和犹大应当悔改"]},{"n":7,"t":"我说：‘她行这些事以后会回转归向我’，她却不回转。她奸诈的妹妹犹大也看见了。","notes":[]},{"n":8,"t":"我看见背道的以色列行淫，我为这缘故给她休书休了她，她奸诈的妹妹犹大还不惧怕，也去行淫。","notes":[]},{"n":9,"t":"因以色列轻忽了她的淫乱，与石头和木头行奸淫，她和这地就都污秽了。","notes":["“与石头和木头行奸淫”意思是“拜石头和木头”。","“她和...污秽了”：原文另译“她就使这地污秽了”。"]},{"n":10,"t":"虽有这一切的事，她奸诈的妹妹犹大还不一心归向我，不过是假意归我。这是耶和华说的。”","notes":[]},{"n":11,"t":"耶和华对我说：“背道的以色列比奸诈的犹大还显为义。","notes":[]},{"n":12,"t":"你去向北方宣告这些话，说：‘背道的以色列啊，回来吧！这是耶和华说的。我必不怒目看你们，因为我是慈爱的，这是耶和华说的。我必不永远怀怒；","notes":[]},{"n":13,"t":"只要承认你的罪孽，就是违背耶和华－你的神，在各青翠的树下追逐外族的神明，没有听从我的话。这是耶和华说的。","notes":["“外族的神明”：原文是“外族”。"]},{"n":14,"t":"背道的儿女啊，回来吧！这是耶和华说的。因为我作你们的丈夫，要将你们从一城取一人，从一族取两人，带到锡安。","notes":[]},{"n":15,"t":"“‘我必将合我心意的牧者赏赐给你们，他们要以知识和智慧牧养你们。","notes":[]},{"n":16,"t":"你们在国中生养众多的时候，那些日子，人必不再提说耶和华的约柜，不追想，不记念，不觉缺少，也不再制造。这是耶和华说的。","notes":[]},{"n":17,"t":"那时，人必称耶路撒冷为耶和华的宝座；万国聚集在那里，为耶和华的名来到耶路撒冷，他们必不再随从自己顽梗的恶心行事。","notes":[]},{"n":18,"t":"当那些日子，犹大家要和以色列家同行，从北方之地一同来到我所赐给你们祖先为业之地。’”","notes":[]},{"n":19,"t":"“我说，我多么乐意把你列在儿女之中，赐给你美地，就是万国中最美的产业。我说，你会以‘我父啊’称呼我，不再转离而跟从我。","notes":[],"heads":["神的子民拜偶像"]},{"n":20,"t":"以色列家啊，你们向我行诡诈，真像妻子行诡诈离开丈夫。这是耶和华说的。”","notes":[]},{"n":21,"t":"有声音从光秃的高地传来，就是以色列人哭泣恳求的声音，因为他们走弯曲之道，忘记耶和华－他们的神。","notes":[]},{"n":22,"t":"“你们这背道的儿女啊，回来吧！我要医治你们背道的病。”“看哪，我们来到你这里，因你是耶和华－我们的神。","notes":[]},{"n":23,"t":"从小山来的真是枉然，大山的喧嚷也是枉然。以色列得救，诚然在乎耶和华－我们的神。","notes":["小山和大山是拜偶像的地方。"]},{"n":24,"t":"“从我们幼年以来，那可耻之物吞吃了我们祖先劳碌得来的，就是他们的羊群、牛群和他们的儿女。","notes":["“那可耻之物”就是“偶像”。"]},{"n":25,"t":"我们在羞耻中躺卧吧！愿惭愧将我们遮盖！因为从我们幼年以来，我们和我们的祖先都得罪了耶和华－我们的神，没有听从耶和华－我们神的话。”","notes":[]}]},"4":{"heading":"呼召以色列悔改","verses":[{"n":1,"t":"耶和华说：“以色列啊，你若回转，回转归向我，若从我眼前除掉你可憎的偶像，不再犹疑不定，","notes":[]},{"n":2,"t":"凭诚实、公平、公义指着永生的耶和华起誓；列国就必因他蒙福，也必因他夸耀。”","notes":[]},{"n":3,"t":"耶和华对犹大人和耶路撒冷人如此说：“你们要为自己开垦荒地，不要撒种在荆棘里。","notes":[]},{"n":4,"t":"犹大人和耶路撒冷的居民哪，你们当自行割礼，归耶和华，将你们心里的污秽除掉；免得我的愤怒因你们的恶行发作，如火燃起，甚至无人能熄灭！”","notes":["“污秽”：原文是“包皮”。"]},{"n":5,"t":"你们要在犹大传扬，在耶路撒冷宣告，说：“当在国中吹角，高声呼叫说：‘你们当聚集！我们好进入坚固城！’","notes":[],"heads":["外患威胁犹大"]},{"n":6,"t":"应当向锡安竖立大旗。逃吧，不要迟延，因我必使灾祸与大毁灭从北方来到。","notes":[]},{"n":7,"t":"有狮子从密林中上来，是毁坏列国的。它已动身出离本处，要使你的地荒凉，使你的城镇变为废墟，无人居住。","notes":[]},{"n":8,"t":"因此，你们当腰束麻布，哭泣哀号，因为耶和华的烈怒并未转离我们。”","notes":[]},{"n":9,"t":"耶和华说：“到那时，君王和领袖的心要失丧，祭司都要惊奇，先知都要诧异。”","notes":[]},{"n":10,"t":"我说：“哀哉！主耶和华啊，你真是大大欺哄这百姓和耶路撒冷，说：‘你们必得平安。’其实刀剑已经抵住喉咙了！”","notes":[]},{"n":11,"t":"那时，必有话对这百姓和耶路撒冷说：“来自旷野光秃高地的热风吹向我的百姓，不是为簸扬，也不是为扬净。","notes":["“我的百姓”：原文直译“我百姓的女儿”。"]},{"n":12,"t":"又有一阵比这更大的风向我刮来；现在，我要向他们宣读我的判决。”","notes":[]},{"n":13,"t":"看哪，他必如云涌上；他的战车如旋风，他的马比鹰更快。我们有祸了！我们败落了！","notes":[],"heads":["犹大被围困"]},{"n":14,"t":"耶路撒冷啊，你当洗去心中的恶，使你可以得救。恶念在你里面要存到几时呢？","notes":[]},{"n":15,"t":"有声音从但传出，有灾祸从以法莲山传来。","notes":[]},{"n":16,"t":"你们当传给列国，看哪，要向耶路撒冷报告：“有围攻的人从远方来到，向犹大的城镇大声喊叫。","notes":[]},{"n":17,"t":"他们包围耶路撒冷，好像看守田园的，因为它背叛了我。这是耶和华说的。","notes":[]},{"n":18,"t":"你的作风和行为招惹这事；这是你罪恶的结果，实在是苦，刺透了你的心！”","notes":[]},{"n":19,"t":"我的肺腑啊，我的肺腑啊，我心疼痛！我的心在我里面烦躁不安。我不能静默不言，因我已听见角声和打仗的喊声。","notes":[],"heads":["耶利米为同胞担忧"]},{"n":20,"t":"毁坏的信息不断传来，因为全地荒废。我的帐棚忽然毁坏，我的幔子顷刻破裂。","notes":[]},{"n":21,"t":"我看见大旗，听见角声，要到几时呢？","notes":[]},{"n":22,"t":"“我的百姓愚顽，不认识我；他们是愚昧无知的儿女，有智慧行恶，没有知识行善。”","notes":[]},{"n":23,"t":"我观看地，看哪，地是空虚混沌；我观看天，天也无光。","notes":[],"heads":["将要来临的毁灭"]},{"n":24,"t":"我观看大山，看哪，尽都震动，小山也都摇来摇去。","notes":[]},{"n":25,"t":"我观看，看哪，无人；空中的飞鸟也都躲避。","notes":[]},{"n":26,"t":"我观看，看哪，肥田变为荒地；所有城镇在耶和华面前，因他的烈怒都被拆毁。","notes":[]},{"n":27,"t":"耶和华如此说：“全地必然荒凉，我却不毁灭净尽。","notes":[]},{"n":28,"t":"因此，地要悲哀，天上也必黑暗；因为我言已出，我意已定，必不改变，也不由此转回。”","notes":[]},{"n":29,"t":"各城的人因骑兵和弓箭手的响声就都逃跑，进入密林，爬上磐石；城镇都被抛弃，无人住在其中。","notes":[]},{"n":30,"t":"你这被毁灭的啊，你要做什么呢？你穿上朱红衣服，佩戴黄金饰物，用眼影修饰眼睛，徒然美化你自己。恋慕你的却藐视你，寻索你的性命。","notes":[]},{"n":31,"t":"我听见有仿佛妇人临产的声音，好像是生头胎疼痛的声音，原来是锡安的声音；她喘着气，伸开手：“我有祸了！在杀人者跟前，我的心灵发昏。”","notes":["“锡安”：原文直译“锡安女子”。"]}]},"5":{"heading":"耶路撒冷的罪","verses":[{"n":1,"t":"你们要走遍耶路撒冷的街市，在广场寻找，看是否有人行公平、求诚实；若有，我就赦免这城。","notes":[]},{"n":2,"t":"虽然他们说“我对永生的耶和华发誓”，所起的誓实在是假的。","notes":[]},{"n":3,"t":"耶和华啊，你的眼目不是在寻找诚实吗？你击打他们，他们却不伤恸；你摧毁他们，他们仍不领受管教。他们使脸刚硬过于磐石，不肯回头。","notes":[]},{"n":4,"t":"我说：“这些人实在是贫寒的，他们是愚昧的，因为不知道耶和华的作为，也不知道他们神的法则。","notes":[]},{"n":5,"t":"我要去见尊贵的人，向他们说话，他们应该知道耶和华的作为，知道他们神的法则。”然而，这些人却齐心将轭折断，挣开绳索。","notes":[]},{"n":6,"t":"因此，林中的狮子必害死他们，野地的狼必灭绝他们，豹子在城外窥伺。凡出城的必被撕碎，因为他们的罪过极多，背道的事也增加。","notes":[]},{"n":7,"t":"我怎能赦免你呢？你的儿女离弃我，又指着那不是神的起誓。我使他们饱足，他们就行奸淫，居住在娼妓家里。","notes":["“居住”是根据七十士译本；原文是“割划自己”；另有古译本是“成群聚集”。"]},{"n":8,"t":"他们如喂饱的马，精力旺盛，各向邻舍的妻子吹哨。","notes":[]},{"n":9,"t":"我岂不因这些事施行惩罚吗？像这样的国家，我岂能不报复呢？这是耶和华说的。","notes":[]},{"n":10,"t":"你们要上去毁坏它的葡萄园，但不可毁坏净尽，只可除掉其枝子，因为不属耶和华。","notes":[]},{"n":11,"t":"以色列家和犹大家向我大行诡诈。这是耶和华说的。","notes":[]},{"n":12,"t":"关乎耶和华他们说了虚谎的话：“他不会的，灾祸必不临到我们，我们也不会遇见刀剑和饥荒。","notes":[],"heads":["耶和华丢弃以色列"]},{"n":13,"t":"先知不过是一阵风，道也不在他们里面；这灾祸必临到他们身上。”","notes":[]},{"n":14,"t":"所以耶和华－万军之神如此说：“因为他们说这话，看哪，我必使我的话在你口中为火，使这百姓为柴，火便将他们烧灭。","notes":[]},{"n":15,"t":"以色列家啊，看哪，我必使一国从远方来攻击你，是强盛的国，是古老的国；他们的言语你不知道，所说的话你不明白。这是耶和华说的。","notes":[]},{"n":16,"t":"他们的箭袋有如敞开的坟墓，他们全都是勇士。","notes":[]},{"n":17,"t":"他们必吃尽你的庄稼和粮食，是你儿女该吃的；必吃尽你的牛羊，吃尽你的葡萄和无花果；又必用刀剑毁坏你所倚靠的坚固城。","notes":["“是你儿女该吃的”：七十士译本是“吃尽你的儿女”。"]},{"n":18,"t":"“就是在那些日子，我也不会将你们毁灭净尽。这是耶和华说的。","notes":[]},{"n":19,"t":"百姓若说：‘耶和华－我们的神为什么向我们行这一切事呢？’你就对他们说：‘你们怎样离弃我，在你们的地上事奉外邦神明，也必照样在不属你们的地上事奉外族人。’”","notes":[]},{"n":20,"t":"当在雅各家传扬，在犹大宣告，说：","notes":[],"heads":["神警告他的子民"]},{"n":21,"t":"“愚昧无知的百姓啊，你们有眼不看，有耳不听，现在当听这话。","notes":[]},{"n":22,"t":"你们难道不惧怕我吗？在我面前还不战兢吗？这是耶和华说的。我以沙为海的界限，作永远的条例，使它不得越过。波浪汹涌，却不能胜过；怒涛澎湃，仍无法越过。","notes":[]},{"n":23,"t":"但这百姓有背叛忤逆的心，他们转离而去。","notes":[]},{"n":24,"t":"他们心里并不说：‘我们应当敬畏耶和华－我们的神；他按时赐雨，就是秋雨和春雨，又为我们定收割的季节。’","notes":[]},{"n":25,"t":"你们的罪孽使这些转离你们，你们的罪恶使你们不能得福。","notes":[]},{"n":26,"t":"在我百姓当中有恶人，他们埋伏，好像捕鸟的人在窥探；他们设罗网陷害人。","notes":["“他们...在窥探”：原文另译“他们设罗网，像捕鸟人的网”。"]},{"n":27,"t":"笼子怎样装满雀鸟，他们的屋里也照样充满诡诈；他们因此得以强大富足。","notes":[]},{"n":28,"t":"他们肥胖光润，作恶过甚，不为人伸冤，不为孤儿伸冤，使他们胜诉，也不为贫穷人辩护。","notes":[]},{"n":29,"t":"我岂不因这些事施行惩罚吗？像这样的国家，我岂能不报复呢？这是耶和华说的。","notes":[]},{"n":30,"t":"“国中有令人惊骇、恐怖的事发生，","notes":[]},{"n":31,"t":"就是先知说假预言，祭司把权柄抓在自己手上，我的百姓也喜爱这样，到了结局你们要怎么办呢？”","notes":[]}]},"6":{"heading":"耶路撒冷遭围攻","verses":[{"n":1,"t":"便雅悯人哪，当逃离耶路撒冷，在提哥亚吹号角，在伯．哈基琳升信号，因为有灾祸与大毁灭从北方逼近。","notes":[]},{"n":2,"t":"那秀美娇嫩的锡安，我必剪除。","notes":["“锡安”：原文直译“锡安女子”。","本节另译“我把锡安比作最可爱的草场”。"]},{"n":3,"t":"牧人必引领羊群到它那里，在它周围支搭帐棚，各在自己的地方放牧。","notes":[]},{"n":4,"t":"“你们要准备攻击它。起来吧，我们要趁正午上去。”“哀哉！日已渐斜，黄昏的影子拖长了。”","notes":[]},{"n":5,"t":"“起来吧，我们要在夜间上去，毁坏它的宫殿。”","notes":[]},{"n":6,"t":"万军之耶和华如此说：“你们要砍伐树木，建土堆攻打耶路撒冷，就是那该受罚的城，其中尽是欺压。","notes":["“该受罚的城”：原文另译“放纵的城”或“被弃的城”。"]},{"n":7,"t":"井怎样涌出水来，这城也照样涌出恶来；其中常听闻残暴毁灭的事，病痛损伤也常在我面前。","notes":[]},{"n":8,"t":"耶路撒冷啊，当受管教，免得我心与你生疏，免得我使你荒凉，成为无人居住之地。”","notes":[]},{"n":9,"t":"万军之耶和华如此说：“他们洗劫以色列剩下的民，如摘净葡萄一样；现你的手如采收葡萄的人，在树枝上采了又采。”","notes":["“你的手...采了又采”：七十士译本是“你要像摘葡萄的人，回手放在筐子里”。"],"heads":["叛逆的以色列"]},{"n":10,"t":"现在我可以向谁说话，警告谁，使他们听呢？看哪，他们的耳朵未受割礼，不能听见。看哪，他们以耶和华的话为羞辱，不以为喜悦。","notes":[]},{"n":11,"t":"因此我被耶和华的愤怒充满，难以忍受。“你要把它倒在街上孩童和成群的年轻人身上，他们连夫带妻，年长者与高龄的人都必被擒拿。","notes":[]},{"n":12,"t":"他们的房屋、田地，和妻子都要一起转归别人，我要伸手攻击这地的居民。”这是耶和华说的。","notes":[]},{"n":13,"t":"“因为他们从最小的到最大的都贪图不义之财，从先知到祭司全都行事虚假。","notes":[]},{"n":14,"t":"他们轻忽地医治我百姓的损伤，说：‘平安了！平安了！’其实没有平安。","notes":[]},{"n":15,"t":"他们行可憎之事，应当羞愧；然而他们却一点也不觉得羞愧，也不知羞耻。因此，他们必与仆倒的人一同仆倒，我惩罚他们的时候，他们必跌倒。”这是耶和华说的。","notes":[]},{"n":16,"t":"耶和华如此说：“你们当站在路边察看，寻访古老的路，哪里是完善的道路，就行走在其上；这样，你们自己必找到安息。他们却说：‘我们不走。’","notes":[],"heads":["以色列拒绝神的道路"]},{"n":17,"t":"我为你们设立守望的人，要留心听角声。他们却说：‘我们不听。’","notes":[]},{"n":18,"t":"因此，列国啊，当听！会众啊，要知道他们必遭遇的事。","notes":[]},{"n":19,"t":"地啊，当听！看哪，我必使灾祸临到这百姓，是他们计谋所结的果子；因为他们不肯留心听我的话，至于我的律法，他们也厌弃。","notes":[]},{"n":20,"t":"从示巴来的乳香，从远方出的香菖蒲，奉来给我有何用呢？你们的燔祭不蒙悦纳；你们的祭物，我也不喜悦。”","notes":[]},{"n":21,"t":"所以耶和华如此说：“看哪，我要将绊脚石放在这百姓面前；父亲和儿子要一同跌在其上，邻舍与朋友也都灭亡。”","notes":[]},{"n":22,"t":"耶和华如此说：“看哪，有一民族从北方而来；有一大国被激起，从地极来到。","notes":[],"heads":["北方来的侵略者"]},{"n":23,"t":"他们拿弓和枪，性情残忍，不施怜悯；他们的声音如海浪澎湃。锡安哪，他们都骑马，如上战场的人摆阵攻击你。”","notes":["“锡安”：原文直译“锡安女子”。"]},{"n":24,"t":"我们听见这样的风声，手就发软；痛苦将我们抓住，疼痛仿佛临产的妇人。","notes":[]},{"n":25,"t":"你们不要出到田野去，也不要行走在路上，因四围有仇敌的刀剑和惊吓。","notes":[]},{"n":26,"t":"我的百姓啊，应当腰束麻布，滚在灰中。要悲伤，如丧独子般痛痛哭号，因为灭命的忽然临到我们。","notes":["“我的百姓”：原文直译“我百姓的女儿”。"]},{"n":27,"t":"我使你作我百姓的测试者和考验者，使你知道并考验他们的行为。","notes":["“测试者”或译“庇护所”。","“考验者”：原文另译“堡垒”。"]},{"n":28,"t":"他们极其悖逆，到处毁谤人，他们是铜是铁，全都败坏了。","notes":[]},{"n":29,"t":"风箱吹火，铅被烧毁，炼而又炼，终是徒然，因为恶劣的还未除掉。","notes":[]},{"n":30,"t":"人必称他们为被抛弃的银子，因为耶和华已经抛弃了他们。","notes":[]}]},"7":{"heading":"耶利米在圣殿讲道","verses":[{"n":1,"t":"耶和华的话临到耶利米，说：","notes":[]},{"n":2,"t":"“你当站在耶和华殿的门口，在那里宣讲这话说：所有从这些门进来敬拜耶和华的犹大人哪，当听耶和华的话。","notes":[]},{"n":3,"t":"万军之耶和华－以色列的神如此说：你们要改正你们的所作所为，我就使你们仍然居住这地。","notes":["“我就...这地”：有古译本是“让我与你们住在这地”。"]},{"n":4,"t":"不要倚靠虚谎的话，说：‘这是耶和华的殿，是耶和华的殿，是耶和华的殿！’","notes":[]},{"n":5,"t":"“你们若实在改正你们的所作所为，彼此诚然施行公平，","notes":[]},{"n":6,"t":"不欺压寄居的和孤儿寡妇，不在这地方流无辜人的血，也不随从别神陷害自己，","notes":[]},{"n":7,"t":"我就使你们仍然居住这地，就是我从古时所赐给你们祖先的地，从永远到永远。","notes":["“我就...这地”：有古译本是“我就与你们住在这地”。"]},{"n":8,"t":"“看哪，你们倚靠虚谎无益的话语。","notes":[]},{"n":9,"t":"你们岂可偷盗，杀害，奸淫，起假誓，向巴力烧香，随从素不认识的别神，","notes":[]},{"n":10,"t":"又来到这称为我名下的殿，在我面前敬拜，说‘我们平安无事’，为了要行这一切可憎的事呢？","notes":[]},{"n":11,"t":"这称为我名下的殿在你们眼中岂可看为贼窝呢？看哪，我真的都看见了。这是耶和华说的。","notes":[]},{"n":12,"t":"你们到我的地方示罗去，就是我先前在那里立为我名的居所，察看我因这百姓以色列的罪恶向那地方所行的事。","notes":[]},{"n":13,"t":"现在，因你们行了这一切的事，我一再警戒你们，你们却不听从；我呼唤你们，你们也不回应。这是耶和华说的。","notes":[]},{"n":14,"t":"所以我要向这称为我名下、你们所倚靠的殿，与我所赐给你们和你们祖先的地这样行，正如我从前向示罗所行的。","notes":[]},{"n":15,"t":"我必将你们从我眼前赶出，正如赶出你们的众弟兄，就是所有以法莲的后裔。”","notes":[]},{"n":16,"t":"“所以，你不要为这百姓祈祷；不要为他们呼求祷告，也不要为他们向我祈求，因我不听你。","notes":[],"heads":["百姓违背命令"]},{"n":17,"t":"他们在犹大城镇和耶路撒冷街上所做的，你难道没有看见吗？","notes":[]},{"n":18,"t":"孩子捡柴，父亲烧火，妇女揉面做饼，献给天后，又向别神献浇酒祭，惹我发怒。","notes":[]},{"n":19,"t":"他们岂是惹我发怒呢？不是自己惹祸，以致脸上惭愧吗？这是耶和华说的。”","notes":[]},{"n":20,"t":"所以主耶和华如此说：“看哪，我必将我的怒气和愤怒倾倒在这地方的人和牲畜身上、田野的树木和地里的出产上，它必燃烧，不会熄灭。”","notes":[]},{"n":21,"t":"万军之耶和华－以色列的神如此说：“你们要将燔祭加在你们的祭物上，又要吃肉；","notes":[]},{"n":22,"t":"因为我将你们祖先从埃及地领出来的那日，燔祭和祭物的事我并没有提说，也没有吩咐他们。","notes":[]},{"n":23,"t":"我只吩咐他们这一件事说：‘你们当听从我的话，我就作你们的神，你们也作我的子民。你们行走我所吩咐的一切道路，就可以得福。’","notes":[]},{"n":24,"t":"他们却不听从，也不侧耳而听，竟随从自己的计谋和顽梗的恶心去行，不进反退。","notes":[]},{"n":25,"t":"自从你们祖先出埃及地的那日，直到今日，我每日一再差遣我的仆人众先知到你们那里去。","notes":[]},{"n":26,"t":"你们却不听我，不侧耳而听，竟硬着颈项行恶，比你们的祖先更甚。","notes":[]},{"n":27,"t":"“你要将这一切的话告诉他们，他们却不听你；呼唤他们，他们却不回应。","notes":[]},{"n":28,"t":"你要对他们说：‘这就是不听从耶和华－他们神的话、不领受训诲的国民；诚信已从他们口中消失殆尽了。","notes":[]},{"n":29,"t":"耶路撒冷啊，要剪头发，扔掉它，在光秃的高地唱哀歌，因为耶和华弃绝、离弃了惹他发怒的世代。’”","notes":[]},{"n":30,"t":"“犹大人行我眼中看为恶的事，将可憎之偶像立在称为我名下的殿里，玷污这殿。这是耶和华说的。","notes":[],"heads":["在欣嫩子谷的罪行"]},{"n":31,"t":"他们在欣嫩子谷建造陀斐特的丘坛，要在火中焚烧自己的儿女。这并不是我所吩咐的，我心里也从来没有想过。","notes":[]},{"n":32,"t":"因此，看哪，日子将到，这地方不再称为陀斐特和欣嫩子谷，反倒称为杀戮谷。他们要在陀斐特埋葬尸首，甚至无处可葬。这是耶和华说的。","notes":[]},{"n":33,"t":"并且这百姓的尸首要给空中的飞鸟和地上的走兽作食物，无人吓走它们。","notes":[]},{"n":34,"t":"那时，我必止息犹大城镇和耶路撒冷街上欢喜和快乐的声音、新郎和新娘的声音，因为这地必然荒芜。”","notes":[]}]},"8":{"heading":"罪与罚","verses":[{"n":1,"t":"耶和华说：“那时，人必将犹大诸王和领袖的骸骨、祭司和先知的骸骨，以及耶路撒冷居民的骸骨，都从坟墓中取出来，","notes":[]},{"n":2,"t":"散布在太阳、月亮和天上众星之下，就是他们从前所喜爱、所事奉、所随从、所求问、所敬拜的。这些骸骨不被收殓，不被埋葬，必在地面上成为粪土。","notes":[]},{"n":3,"t":"这邪恶家族所幸存的余民，就是在我赶他们到的各处所剩下的，全都宁可选死不选活。这是万军之耶和华说的。”","notes":["有古卷和七十士译本没有“所剩下的”。"]},{"n":4,"t":"“你要对他们说，耶和华如此说：人跌倒，不再起来吗？人转去，不再转回来吗？","notes":[]},{"n":5,"t":"这耶路撒冷的百姓为何永久背道呢？他们抓住诡诈，不肯回头。","notes":[]},{"n":6,"t":"我留心听，听见他们说不诚实的话。无人懊悔自己的恶行，说：‘我做的是什么呢？’他们全都转奔己路，如马直闯战场。","notes":[]},{"n":7,"t":"空中的鹳鸟知道自己的季节，斑鸠、燕子与白鹤也守候当来的时令；我的百姓却不知道耶和华的法则。","notes":[]},{"n":8,"t":"“你们怎么说：‘我们有智慧，耶和华的律法在我们这里’？看哪，其实文士的假笔舞弄虚假。","notes":[]},{"n":9,"t":"智慧人惭愧，惊惶，被擒拿；看哪，他们背弃耶和华的话，还会有什么智慧呢？","notes":[]},{"n":10,"t":"因此，我必将他们的妻子给别人，将他们的田地给别人为业；因为他们从最小的到最大的都贪图不义之财，从先知到祭司全都行事虚假。","notes":[]},{"n":11,"t":"他们轻忽地医治我百姓的损伤，说：‘平安了！平安了！’其实没有平安。","notes":[]},{"n":12,"t":"他们行可憎之事，应当羞愧；然而他们却一点也不觉得羞愧，又不知羞耻。因此，他们必与仆倒的人一样仆倒；我惩罚他们的时候，他们必跌倒。这是耶和华说的。","notes":[]},{"n":13,"t":"我必使他们全然灭绝；葡萄树上必没有葡萄，无花果树上没有果子，叶子也必枯干。我所赐给他们的，必离他们而去。这是耶和华说的。”","notes":["“我必...葡萄”：有古译本是“我要采收果子，但葡萄树上必没有葡萄”。"]},{"n":14,"t":"我们为何静坐不动呢？我们当聚集，进入坚固城，在那里静默不言；因为耶和华－我们的神使我们静默不言，又将苦水给我们喝，都因我们得罪了耶和华。","notes":[]},{"n":15,"t":"我们指望平安，却得不着福气；指望痊愈时刻，看哪，受了惊惶。","notes":[]},{"n":16,"t":"“从但那里传来敌人的马喷气的声音，壮马发出嘶声，全地就都震动；因为他们来吞灭这地和其上所有的，吞灭这城与其中的居民。","notes":[]},{"n":17,"t":"看哪，我必派蛇进到你们中间，就是法术无法驱除的毒蛇，它们必咬你们。这是耶和华说的。”","notes":[]},{"n":18,"t":"忧愁时我寻找安慰，我心在我里面发昏。","notes":["“忧愁...安慰”：七十士译本是“无法医治的忧伤压倒你们的心”。"],"heads":["耶利米为同胞悲伤"]},{"n":19,"t":"听啊，是我百姓呼救的声音从远地传来：“耶和华不是在锡安吗？锡安的王不是在其中吗？”“他们为什么以自己雕刻的偶像和外邦虚无的神明惹我发怒呢？”","notes":["“虚无的神明”：原文是“虚无”。"]},{"n":20,"t":"“秋收已过，夏季已完，我们还未得救！”","notes":[]},{"n":21,"t":"因我百姓的损伤，我也受了损伤。我哀恸，惊惶将我抓住。","notes":[]},{"n":22,"t":"在基列岂没有乳香呢？在那里岂没有医生呢？我百姓为何得不着医治呢？","notes":["“我百姓”：原文直译“我百姓的女儿”。"]}]},"9":{"heading":"耶路撒冷哀求援助","verses":[{"n":1,"t":"但愿我的头为水，我的眼为泪水的泉源，我好为我百姓中被杀的人昼夜哭泣。","notes":["“我百姓”：原文直译“我百姓的女儿”。"]},{"n":2,"t":"惟愿在旷野有旅客的客栈，我好离开我的百姓而去；因他们全都行奸淫，是行诡诈的一党。","notes":[]},{"n":3,"t":"他们弯起舌头像弓，为要说谎话；他们在国中增长势力，不是为诚信。他们恶上加恶，并不认识我。这是耶和华说的。","notes":[]},{"n":4,"t":"你们各人当谨防邻舍，不可信赖弟兄；因为弟兄尽行欺骗，邻舍也都往来毁谤人。","notes":[]},{"n":5,"t":"他们互相欺骗，不说真话，训练自己的舌头说谎，竭尽所能地作恶。","notes":[]},{"n":6,"t":"你居住在诡诈的人中；他们因行诡诈，不愿意认识我。这是耶和华说的。","notes":["“竭尽...因行诡诈”：七十士译本是“他们不停地作恶，不知悔改；压迫又压迫，欺骗又欺骗 ”。"]},{"n":7,"t":"所以万军之耶和华如此说：“看哪，我要熬炼他们，考验他们；不然，为了我的百姓，我该如何行呢？","notes":["“我的百姓”：原文直译“我百姓的女儿”。"]},{"n":8,"t":"他们的舌头是毒箭，说话诡诈，跟邻舍口说平安，心却谋害他。","notes":[]},{"n":9,"t":"我岂不因这些事向他们施行惩罚吗？像这样的国家，我岂能不报复呢？这是耶和华说的。”","notes":[]},{"n":10,"t":"我要为山岭哭泣悲哀，为旷野的草场扬声哀号；因为都已枯焦，甚至无人经过。牲畜的鸣叫听不见，空中的飞鸟和地上的走兽也都逃离。","notes":[]},{"n":11,"t":"我必使耶路撒冷成为废墟，为野狗的住处，也必使犹大的城镇荒废，无人居住。","notes":[]},{"n":12,"t":"谁是智慧人，可以明白这事？耶和华的口可向谁述说，使他传讲呢？这地为何毁灭，枯焦如旷野，无人经过呢？","notes":[]},{"n":13,"t":"耶和华说：“因为这百姓离弃我在他们面前所设立的律法，不听从我的话，不肯遵行，","notes":[]},{"n":14,"t":"反随从自己顽梗的心行事，照他们祖先所教训的随从诸巴力。”","notes":[]},{"n":15,"t":"所以万军之耶和华－以色列的神如此说：“看哪，我必将茵陈给这百姓吃，又用苦水给他们喝。","notes":[]},{"n":16,"t":"我要把他们分散在他们和他们祖宗所不认识的列国；我也要使刀剑追杀他们，直到将他们灭尽。”","notes":[]},{"n":17,"t":"万军之耶和华如此说：“你们要考虑，将唱哀歌的妇女召来，差人召善哭的妇女前来，","notes":[]},{"n":18,"t":"叫她们速速为我们举哀，使我们泪眼汪汪，使我们的眼皮涌出泪水。","notes":[]},{"n":19,"t":"因为有哀声从锡安传来：‘我们竟然败落！我们何等惭愧！我们撇下土地，人拆毁了我们的房屋。’”","notes":[]},{"n":20,"t":"妇女们哪，当听耶和华的话，领受他口中的言语；当教导你们的女儿举哀，各人教导女伴唱哀歌。","notes":[]},{"n":21,"t":"因为死亡从窗户进来，进入我们的宫殿，从外边剪除孩童，从街上剪除少年。","notes":[]},{"n":22,"t":"你当说，耶和华如此说：人的尸首必倒在田野像粪土，又像收割的人身后遗落的禾稼，无人拾取。","notes":[]},{"n":23,"t":"耶和华如此说：“智慧人不要因他的智慧夸口，勇士不要因他的力气夸口，财主也不要因他的财富夸口；","notes":[]},{"n":24,"t":"夸口的却要夸自己有聪明，认识我是耶和华，知道我喜悦在世上施行慈爱、公平和公义。这是耶和华说的。","notes":[]},{"n":25,"t":"“看哪，日子将到，这是耶和华说的，我要惩罚只在肉身受割礼的人，","notes":[]},{"n":26,"t":"就是埃及、犹大、以东、亚扪人、摩押人，和住旷野所有剃鬓发的人；因为列国都未受割礼，以色列全家心中也未受割礼。”","notes":[]}]},"10":{"heading":"拜偶像和真敬拜","verses":[{"n":1,"t":"以色列家啊，要听耶和华对你们所说的话，","notes":[]},{"n":2,"t":"耶和华如此说：“不要效法列国的行为，任凭列国因天象惊惶，你们不要惊惶。","notes":[]},{"n":3,"t":"万民的习俗是虚空的；偶像不过是从树林中砍来的木头，是匠人用斧头做成的手工。","notes":["“偶像”：原文是“它”。"]},{"n":4,"t":"人用金银妆饰它，用钉子和锤子钉稳，使它不动摇。","notes":[]},{"n":5,"t":"偶像好像瓜田里的稻草人，不能说话，不能行走，必须有人抬着。不要怕它们，因它们不能降祸，也无力降福。”","notes":[]},{"n":6,"t":"耶和华啊，没有谁能与你相比！你本为大，你的名也大有能力。","notes":[]},{"n":7,"t":"万国的王啊，谁不敬畏你？敬畏你本是合宜的；列国所有的智慧人中，在他们一切的国度里，都没有能与你相比的。","notes":[]},{"n":8,"t":"他们如同畜牲，尽都愚昧。偶像的训诲算什么呢？偶像不过是木头，","notes":[]},{"n":9,"t":"锤炼的银片是从他施来的，金子则从乌法而来，都是匠人和银匠的手工；又有蓝色和紫色的衣服，全都是巧匠的作品。","notes":["“乌法”：有古译本是“俄斐”。"]},{"n":10,"t":"惟耶和华是真神，是活的神，是永远的王。他一发怒，大地震动；他一恼恨，列国担当不起。","notes":[]},{"n":11,"t":"你们要对他们这样说：“那些不是创造天地的神明，必从地上、从天下被除灭！”","notes":["本节原文是亚兰文。"]},{"n":12,"t":"耶和华以能力创造大地，以智慧建立世界，以聪明铺张穹苍。","notes":[],"heads":["颂赞神的诗"]},{"n":13,"t":"他一出声，天上就有众水澎湃；他使云雾从地极上腾，造电随雨而闪，从仓库中吹出风来。","notes":[]},{"n":14,"t":"人人都如同畜牲，毫无知识；银匠都因偶像羞愧，他所铸的偶像本是虚假，它们里面并无气息。","notes":[]},{"n":15,"t":"偶像都是虚无的，是迷惑人的作品，到受罚的时刻必被除灭。","notes":[]},{"n":16,"t":"雅各所得的福分不是这样，因主是那创造万有的，以色列是他产业的支派，万军之耶和华是他的名。","notes":["“主”：原文是“他”。"]},{"n":17,"t":"受围困的居民哪，当收拾你的行囊，离开这地。","notes":[],"heads":["预告被掳"]},{"n":18,"t":"因为耶和华如此说：“看哪，这一次，我必将此地的居民抛出去，又必加害他们，使他们觉悟。”","notes":["“使他们觉悟”：七十士译本是“你的灾难就被发现”。"]},{"n":19,"t":"祸哉！我受损伤，我的伤痕极其重大。我却说：“这真的是我必须忍受的痛苦。”","notes":[]},{"n":20,"t":"我的帐棚毁坏，我的绳索折断，我的儿女都离我而去，不在了。再无人来支搭我的帐棚，挂起我的幔子。","notes":[]},{"n":21,"t":"因为牧人如同畜牲，没有寻求耶和华，所以不得顺利；他们的羊群也都分散了。","notes":[]},{"n":22,"t":"有风声！看哪，来了！有大扰乱从北方而来，要使犹大的城镇变为废墟，成为野狗的住处。","notes":[]},{"n":23,"t":"耶和华啊，我知道人的道路不由自己，行路的人也不能定自己的脚步。","notes":[]},{"n":24,"t":"耶和华啊，求你按公平管教我，不要在你的怒中惩治我，免得你使我归于无有。","notes":[]},{"n":25,"t":"求你将愤怒倾倒在不认识你的列国中，倾倒在不求告你名的各族上；因为他们吞了雅各，不但吞了，而且灭绝，使他的住处变为荒凉。","notes":[]}]},"11":{"heading":"耶利米宣告神的约","verses":[{"n":1,"t":"耶和华的话临到耶利米，说：","notes":[]},{"n":2,"t":"“当听这约的话，告诉犹大人和耶路撒冷的居民，","notes":[]},{"n":3,"t":"对他们说，耶和华－以色列的神如此说：‘不听从这约之话的人必受诅咒。","notes":[]},{"n":4,"t":"这约是我将你们祖先从埃及地领出来，脱离铁炉的那日所吩咐他们的，说：你们要听从我的话，照我所吩咐的一切去做。这样，你们作我的子民，我也作你们的神，","notes":[]},{"n":5,"t":"我好坚定我向你们列祖所起的誓，赏赐他们流奶与蜜之地，正如今日一样。’”我就回应说：“耶和华啊，阿们！”","notes":[]},{"n":6,"t":"耶和华对我说：“你要在犹大城镇和耶路撒冷街市宣告这一切话，说：‘当听从遵行这约的话，","notes":[]},{"n":7,"t":"因为我将你们祖先从埃及地领出来的那日，直到今日，都一再切切告诫他们说：当听从我的话。","notes":[]},{"n":8,"t":"他们却不听从，也不侧耳而听，竟随从自己顽梗的恶心去行。我就使这约中一切诅咒的话临到他们身上；这约是我吩咐他们遵行的，他们却不遵行。’”","notes":[]},{"n":9,"t":"耶和华对我说：“在犹大人和耶路撒冷居民中有同谋背叛的事。","notes":[]},{"n":10,"t":"他们转去效法他们祖先的恶行，不肯听我的话，竟随从别神，事奉它们。以色列家和犹大家违背了我与他们列祖所立的约。","notes":[]},{"n":11,"t":"所以耶和华如此说：看哪，我必使灾祸临到他们，是他们不能逃脱的。他们向我哀求，我却不听。","notes":[]},{"n":12,"t":"那时，犹大城镇的人和耶路撒冷的居民要哀求他们烧香所供奉的神明；只是遭难的时候，这些神明一点也不能拯救他们。","notes":[]},{"n":13,"t":"犹大啊，你神明的数目与你城镇的数目相等；你所筑可耻的坛，就是向巴力烧香的坛，也与耶路撒冷街道的数目相等。","notes":["“你所筑...烧香的坛”：七十士译本是“你为巴力烧香所筑的坛”。"]},{"n":14,"t":"“所以你不要为这百姓祈祷，也不要为他们呼求祷告，因为他们遭难向我哀求的时候，我必不应允。","notes":[]},{"n":15,"t":"我所亲爱的既多设恶谋，还能在我殿中做什么呢？你因作恶就喜乐，圣肉要离开你。","notes":[]},{"n":16,"t":"从前耶和华给你起名叫青橄榄树，又华美又结好果子；如今他用一声巨响点火在其上，枝子就折断了。","notes":[]},{"n":17,"t":"“原来栽培你的万军之耶和华已经说要降祸给你，是因以色列家和犹大家行恶。他们向巴力烧香，惹我发怒，是自作自受。”","notes":[]},{"n":18,"t":"耶和华指示我，我才知道；你将他们所做的给我指明。","notes":[],"heads":["杀害耶利米的阴谋"]},{"n":19,"t":"我像柔顺的羔羊被牵去宰杀，并不知道他们设计谋害我：“我们把树连果子都灭了吧！把他从活人之地剪除，使他的名不再被记得。”","notes":[]},{"n":20,"t":"按公义判断、察验人肺腑心肠的万军之耶和华啊，求你使我得见你在他们身上报仇，因我已将我的案件向你禀明了。","notes":[]},{"n":21,"t":"所以，耶和华论到寻索你命的亚拿突人如此说：“他们说：你不要奉耶和华的名说预言，免得你死在我们手中。","notes":[]},{"n":22,"t":"所以万军之耶和华如此说：看哪，我必惩罚他们；他们的壮丁必被刀剑杀死，他们的儿女必因饥荒而死，","notes":[]},{"n":23,"t":"他们当中必无任何幸存者；因为在他们受罚之年，我必使灾祸临到亚拿突人。”","notes":[]}]},"12":{"heading":"耶利米询问耶和华","verses":[{"n":1,"t":"耶和华啊，我与你争辩的时候，你总是显为义；但有一件，我还要与你理论：恶人的道路为何亨通呢？大行诡诈的为何得安逸呢？","notes":[]},{"n":2,"t":"你栽培了他们，他们也扎了根，长大，而且结果。他们的口与你相近，心却与你远离。","notes":[]},{"n":3,"t":"耶和华啊，你认识我，看见我，你察验我向你的心如何。求你将他们拉出来，如将宰的羊，为杀戮的日子分别出来。","notes":[]},{"n":4,"t":"这地悲哀，一切田野的青草枯干要到几时呢？因其上居民的恶行，牲畜和飞鸟都灭绝了。因为他们说：“他看不见我们的结局。”","notes":["“他看不见”：死海古卷是“耶和华不让你看见”。","“他看不见...结局”：七十士译本是“神看不见我们的道路”。"]},{"n":5,"t":"“你与步行的人同跑，尚且觉得累，怎能与马赛跑呢？你在安全之地尚且会跌倒，在约旦河边的丛林要怎么办呢？","notes":["“尚且会跌倒”或译“感觉安稳”。"]},{"n":6,"t":"因为连你兄弟和你父家都以诡诈待你，甚至在你后边大声喊叫。虽然他们向你说好话，你也不要相信他们。”","notes":[]},{"n":7,"t":"我离弃了我的殿宇，撇弃了我的产业，将我心里所亲爱的交在她仇敌手中。","notes":["“她”指的是“所亲爱的”、“产业”。"],"heads":["耶和华为他的子民忧伤"]},{"n":8,"t":"我的产业向我如林中的狮子，出声攻击我，因此我恨恶她。","notes":[]},{"n":9,"t":"我的产业向我如斑点的鸷鸟，有鸷鸟在四围攻击她。你们去聚集田野的百兽，叫它们来吞吃吧！","notes":[]},{"n":10,"t":"许多牧人毁坏我的葡萄园，践踏我的地产，使我美好的地产变为荒凉的旷野。","notes":[]},{"n":11,"t":"他们使地荒凉；地既荒凉，就向我哀哭。全地荒凉，却无人在意。","notes":[]},{"n":12,"t":"灭命的来到旷野中一切光秃的高地；耶和华的刀从地这边直到地那边，尽行杀灭，凡血肉之躯都不得平安。","notes":[]},{"n":13,"t":"他们种的是麦子，收的却是荆棘；辛辛苦苦却无收获。因耶和华的烈怒，你们必为自己的收成感到羞愧。","notes":[]},{"n":14,"t":"耶和华如此说：“看哪，我要将所有的恶邻拔出本地，他们曾占据了我赐给以色列百姓所承受的产业；我也要将犹大家从他们中间拔出来。","notes":[],"heads":["耶和华对以色列的许诺"]},{"n":15,"t":"我拔出他们以后，必回转过来怜悯他们，使他们归回，各归本业，各归故土。","notes":[]},{"n":16,"t":"他们若殷勤学习我百姓的道，指着我的名起誓：‘我指着永生的耶和华起誓’，正如他们从前教我百姓指着巴力起誓，他们必在我百姓中得以建立。","notes":[]},{"n":17,"t":"他们若是不听，我必拔出那国，不但拔出，还要毁灭。这是耶和华说的。”","notes":[]}]},"13":{"heading":"腰带的比喻","verses":[{"n":1,"t":"耶和华对我如此说：“你去买一条麻布带子，束在你腰上，不可把它泡在水里。”","notes":[]},{"n":2,"t":"我就照耶和华的话，买了一条带子，束在我的腰上。","notes":[]},{"n":3,"t":"耶和华的话第二次临到我，说：","notes":[]},{"n":4,"t":"“要拿你所买、在你腰上的带子，起来往幼发拉底河去，把腰带藏在那里的磐石穴中。”","notes":[]},{"n":5,"t":"我就去，照着耶和华命令我的，把腰带藏在幼发拉底河边。","notes":[]},{"n":6,"t":"过了多日，耶和华对我说：“你起来往幼发拉底河去，把我命令你藏在那里的腰带取出来。”","notes":[]},{"n":7,"t":"我就往幼发拉底河去，把那腰带从我所藏的地方挖出来。看哪，腰带已经破烂，毫无用处了。","notes":[]},{"n":8,"t":"耶和华的话临到我，说：","notes":[]},{"n":9,"t":"“耶和华如此说：我要照样败坏犹大的骄傲和耶路撒冷的狂傲。","notes":[]},{"n":10,"t":"这恶民不肯听我的话，按自己顽梗的心而行，随从别神，事奉敬拜它们；这恶民必像这腰带，毫无用处。","notes":[]},{"n":11,"t":"腰带怎样紧贴人的腰，照样，我也曾使以色列全家和犹大全家紧贴着我，归我为子民，使我得名声，得颂赞，得荣耀；他们却不肯听从。这是耶和华说的。”","notes":[]},{"n":12,"t":"“所以你要对他们说：‘耶和华－以色列的神如此说：各坛都要装满酒。’他们必对你说：‘我们岂不知道各坛都要装满酒吗？’","notes":[],"heads":["酒坛的比喻"]},{"n":13,"t":"你就对他们说：‘耶和华如此说：看哪，我必使这地所有的居民，就是坐大卫宝座的君王、祭司和先知，并耶路撒冷所有的居民，都酩酊大醉。","notes":[]},{"n":14,"t":"我要使他们彼此冲突，连父与子也互相冲突；我必不可怜，不顾惜，不怜悯，以致将他们灭绝。这是耶和华说的。’”","notes":[]},{"n":15,"t":"你们当听，当侧耳而听；不可骄傲，因为耶和华已经吩咐了。","notes":[],"heads":["耶利米警告狂傲的行为"]},{"n":16,"t":"当耶和华－你们的神尚未使黑暗来临，在昏暗的山上你们的脚未绊跌以前，要将荣耀归给他。你们盼望光明，他却使光明变为死荫，成为幽暗。","notes":[]},{"n":17,"t":"你们若不听这话，我的心必因你们的骄傲暗自哭泣；我的眼必痛哭流泪，因为耶和华的羊群被掳去了。","notes":[]},{"n":18,"t":"你要对君王和太后说：“你们当自卑，坐下；因你们的王冠，就是你们华美的冠冕已经掉落了。”","notes":["“因你们...掉落了”：七十士译本和其他古译本是“因你们华美的冠冕已经从头上掉落了”。"]},{"n":19,"t":"尼革夫的城镇都被关闭，无人打开；犹大全被掳掠，掳掠净尽。","notes":["“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”；本卷书下同。"]},{"n":20,"t":"你们要举目观看从北方来的人。先前赐给你的羊群，就是你所引以为荣的羊，现今在哪里呢？","notes":[]},{"n":21,"t":"耶和华立你自己所教导的盟友，立他们为头来辖制你，你还有什么话可说呢？痛苦岂不将你抓住像临产的妇人吗？","notes":["“耶和华...可说呢？”或译“当他来惩罚你的时候，你还有什么话可说呢？你自己所教导的盟友作头来辖制你。”"]},{"n":22,"t":"你若心里说：“这一切的事为何临到我呢？”是因你罪孽甚多。你的下摆揭起，你的脚跟受伤。","notes":[]},{"n":23,"t":"古实人岂能改变皮肤呢？豹岂能改变斑点呢？若能，你们这善于行恶的便能行善了。","notes":["“古实”包括苏丹的大部分和埃塞俄比亚的一部分。"]},{"n":24,"t":"我必吹散他们，如碎秸随旷野的风飘动。","notes":[]},{"n":25,"t":"这是你所当得的，是我量给你的报应；因为你忘记了我，倚靠虚假。这是耶和华说的。","notes":["“我量给你的报应”：七十士译本是“你们背叛我的报应”。","“虚假”或译“偶像”。"]},{"n":26,"t":"我要揭起你的下摆，蒙在你脸上，显露你的羞耻。","notes":[]},{"n":27,"t":"你在田野的山上行奸淫，发嘶声，谋淫乱，这些可憎之事我都看见了。耶路撒冷啊，你有祸了！你不肯洁净还要等到几时呢？","notes":["“你不肯洁净”：七十士译本是“你不肯洁净来跟从我”。"]}]},"14":{"heading":"可怕的旱灾","verses":[{"n":1,"t":"耶和华的话临到耶利米，论到旱灾的事：","notes":[]},{"n":2,"t":"“犹大悲哀，城门衰败；众人坐在地上哀恸，耶路撒冷的哀声上达。","notes":[]},{"n":3,"t":"他们的贵族打发僮仆去打水；他们来到水池，找不到水，就拿着空器皿，蒙羞惭愧，抱头而回。","notes":[]},{"n":4,"t":"因为无雨降在地上，土地就干裂，农夫为此蒙羞抱头。","notes":[]},{"n":5,"t":"田野的母鹿因为无草也撇弃才生的小鹿。","notes":[]},{"n":6,"t":"野驴站在光秃的高地喘气，好像野狗；它们的眼目因无草而失明。”","notes":[]},{"n":7,"t":"耶和华啊，虽然我们的罪孽控告我们，求你为你名的缘故行动吧！我们本是多次背道，得罪了你。","notes":[]},{"n":8,"t":"以色列所盼望，在患难时作他救主的啊，你在这地为何像寄居的，又如旅行的只住一夜呢？","notes":[]},{"n":9,"t":"你为何像受惊吓的人，像不能救人的勇士呢？耶和华啊，你在我们中间，我们是称为你名下的人，求你不要离开我们。","notes":[]},{"n":10,"t":"耶和华论到这百姓如此说：“这百姓喜爱游荡，不约束自己的脚步，所以耶和华不悦纳他们。现今他要记起他们的罪孽，惩罚他们的罪恶。”","notes":[]},{"n":11,"t":"耶和华又对我说：“不要为这百姓求福。","notes":[]},{"n":12,"t":"他们禁食的时候，我不听他们的呼求；他们献燔祭和素祭，我也不悦纳。我却要用刀剑、饥荒、瘟疫灭绝他们。”","notes":[]},{"n":13,"t":"我就说：“唉！主耶和华，看哪，那些先知常对他们说：‘你们必不见刀剑，也不遭饥荒；耶和华要在这地方赏赐你们真正的平安。’”","notes":[]},{"n":14,"t":"耶和华对我说：“那些先知托我的名说假预言，我并未差遣他们，没有吩咐他们，也没有对他们说话；他们向你们预言的是虚假的异象、占卜、虚无，以及心中的诡诈。","notes":[]},{"n":15,"t":"所以耶和华如此说：‘论到托我名说预言的那些先知，我并未差遣他们；他们说这地不会有刀剑、饥荒，其实那些先知自己必被刀剑、饥荒灭绝。","notes":[]},{"n":16,"t":"听他们说预言的百姓必因饥荒、刀剑被扔在耶路撒冷的街道上，无人埋葬。他们连妻子带儿女，都是如此。我必将他们的恶倒在他们身上。’”","notes":[]},{"n":17,"t":"你要向他们说这些话：愿我眼泪汪汪，昼夜不息，因为少女─我百姓受了重大的打击，伤口极其严重。","notes":["“我百姓”：原文直译“我百姓的女儿”。"]},{"n":18,"t":"我若出到田间，看哪，有被刀杀的；我若进入城内，看哪，有因饥荒患病的；先知和祭司也在各地往来经商，不知如何是好。","notes":[]},{"n":19,"t":"你全然弃绝犹大吗？你的心厌恶锡安吗？你为何击打我们，使我们无法得医治呢？我们指望平安，却得不着福气；指望痊愈，看哪，受了惊惶。","notes":[],"heads":["百姓恳求耶和华怜悯"]},{"n":20,"t":"耶和华啊，我们承认自己的罪恶和我们祖先的罪孽，因我们得罪了你。","notes":[]},{"n":21,"t":"求你为你名的缘故，不厌恶，不轻视你荣耀的宝座。求你记念，不要违背你与我们所立的约。","notes":[]},{"n":22,"t":"外邦虚无的神明中有能降雨的吗？天能自降甘霖吗？耶和华－我们的神啊，不是你吗？我们要等候你，因为这一切都是你所造的。","notes":["“虚无的神明”：原文是“虚无”。"]}]},"15":{"heading":"犹大百姓的厄运","verses":[{"n":1,"t":"耶和华对我说：“虽有摩西和撒母耳站在我面前，我的心也不顾惜这百姓。你把他们从我眼前赶出，叫他们出去吧！","notes":[]},{"n":2,"t":"他们若问你说：‘我们往哪里去呢？’你就告诉他们，耶和华如此说：‘定为死亡的，必致死亡；定为刀杀的，必被刀杀；定为饥荒的，必遭饥荒；定为掳掠的，必被掳掠。’”","notes":[]},{"n":3,"t":"“我命定四样灾害临到他们，就是刀剑杀戮、群狗拖拉、空中的飞鸟和地上的走兽吞吃毁灭。这是耶和华说的。","notes":[]},{"n":4,"t":"我必使地上万国因他们而惊骇，都因希西家的儿子犹大王玛拿西在耶路撒冷所做的事。”","notes":[]},{"n":5,"t":"耶路撒冷啊，有谁同情你呢？有谁为你悲伤呢？有谁转身问你安呢？","notes":[]},{"n":6,"t":"你弃绝了我，转身退后；因此我伸手攻击你，毁灭你，我已怜悯到厌烦了。这是耶和华说的。","notes":[]},{"n":7,"t":"我在境内各关口用簸箕筛我的百姓，使他们丧掉儿女，又毁灭他们，他们仍不转离所行的道。","notes":[]},{"n":8,"t":"他们的寡妇在我面前比海沙更多；我使灭命者在正午来到，攻击年轻人的母亲，使痛苦惊吓忽然临到她身上。","notes":[]},{"n":9,"t":"生过七个孩子的妇人衰弱；尚在白昼，太阳忽然落下，她就抱愧蒙羞。我必当着敌人的面，将他们当中的幸存者交给刀剑。这是耶和华说的。","notes":[]},{"n":10,"t":"我的母亲哪，我有祸了！因你生我作全地争相指控的人。我素来没有借贷给人，人也没有借贷给我，人人却都咒骂我。","notes":[],"heads":["耶利米向耶和华诉苦"]},{"n":11,"t":"耶和华说：“我必定释放你，使你得福气。灾祸苦难来临时，我必使仇敌央求你。","notes":["“释放”：原文另译“坚固”。"]},{"n":12,"t":"人岂能将铜与铁，就是北方的铁折断呢？","notes":[]},{"n":13,"t":"“我必因你在四境之内所犯的一切罪，将你的货物财宝当掠物，白白地交出来。","notes":["“白白地交出来”：原文直译“不以任何代价交出来”；七十士译本是“作为该付的代价”。"]},{"n":14,"t":"我要使你的仇敌过去，到你所不认识的地方，因为你们要被我怒中所起的火焚烧。”","notes":["“我要...地方”：有古卷和七十士译本是“我要使你在你所不认识之地服侍你四围的仇敌”。"]},{"n":15,"t":"耶和华啊，你是知道的；求你记念我，眷顾我，向迫害我的人为我报仇；不要把我取去，因你不轻易发怒，要知道我为你的缘故受了凌辱。","notes":[]},{"n":16,"t":"耶和华－万军之神啊，我得着你的话就把它们吃了，你的话是我心中的欢喜快乐；因我是称为你名下的人。","notes":[]},{"n":17,"t":"我并未坐在享乐人的会中欢乐；因你的手，我就独自静坐，你使我满心愤慨。","notes":[]},{"n":18,"t":"我的痛苦为何长久不止呢？我的伤痕为何无法可医，不能痊愈呢？难道你以诡诈待我，像流干的河道吗？","notes":[]},{"n":19,"t":"所以耶和华如此说：“你若回转，我就使你归回，站在我面前。你若能将宝物和无用之物分别出来，你就可以当作我的口。他们必归向你，你却不可归向他们。","notes":[]},{"n":20,"t":"我必使你向这百姓成为坚固的铜墙。他们必攻击你，却不能胜过你；因我与你同在，要拯救你，搭救你。这是耶和华说的。","notes":[]},{"n":21,"t":"我必搭救你脱离恶人的手，救赎你脱离残暴之人的手。”","notes":[]}]},"16":{"heading":"耶和华要耶利米独身","verses":[{"n":1,"t":"耶和华的话又临到我，说：","notes":[]},{"n":2,"t":"“你不可在这地方娶妻，为自己生儿育女。","notes":[]},{"n":3,"t":"因为论到在这地方所生的儿女，又论到在这国中生他们的父母，耶和华如此说：","notes":[]},{"n":4,"t":"他们必死于致命的疾病，无人哀哭，不得埋葬，在地上如粪土，因刀剑和饥荒而灭绝；他们的尸首必给空中的飞鸟和地上的走兽作食物。","notes":[]},{"n":5,"t":"“耶和华如此说：不要进入丧家，不要去哀哭，也不要为他们悲伤，因我已使我的平安、慈爱、怜悯离开这百姓。这是耶和华说的。","notes":[]},{"n":6,"t":"他们连大带小，都必在这地死亡，不得埋葬。人必不为他们哀哭，不为他们割划自己，也不剃光头。","notes":[]},{"n":7,"t":"有丧事，人不为他们擘饼 ，也不因死人安慰他们；他们丧父丧母，人也不给他们一杯酒安慰他们。","notes":["“有丧事...擘饼”：有古卷是“人不为丧家擘饼”。"]},{"n":8,"t":"你不可进入宴乐的家，与人同坐又吃又喝，","notes":[]},{"n":9,"t":"因为万军之耶和华－以色列的神如此说：看哪，你们还活着的日子，我必在你们眼前止息这地方欢喜和快乐的声音、新郎和新娘的声音。","notes":[]},{"n":10,"t":"“你将这一切的话指示这百姓，他们若问你说：‘耶和华为什么说，要降这大灾祸攻击我们呢？我们有什么罪孽呢？我们向耶和华－我们的神犯了什么罪呢？’","notes":[]},{"n":11,"t":"你就对他们说：‘因为你们祖先离弃了我，随从别神，事奉敬拜它们，却离弃我，不遵守我的律法。这是耶和华说的。","notes":[]},{"n":12,"t":"你们行恶比你们祖先更甚，看哪，各人随从自己顽梗的恶心行事，不听从我。","notes":[]},{"n":13,"t":"所以我必将你们从这地赶出，直赶到你们和你们祖先素不认识之地。你们在那里昼夜必事奉别神，因为我必不再向你们施恩。’”","notes":[]},{"n":14,"t":"“看哪，日子将到，人必不再指着那领以色列人从埃及地上来的永生耶和华起誓。这是耶和华说的。","notes":[],"heads":["预告被掳归回"]},{"n":15,"t":"人却要指着那领以色列人离开北方之地，离开他们被赶到的各国之永生的耶和华起誓；并且我要领他们归回我从前赐给他们祖先之地。”","notes":[]},{"n":16,"t":"“看哪，我要差派许多打鱼的捕获他们；以后，我也要派许多打猎的，从各山上、各冈上、各石穴中猎取他们。这是耶和华说的。","notes":[],"heads":["将要临到的惩罚"]},{"n":17,"t":"因我的眼目察看他们一切的行为；他们不能在我面前遮掩，他们的罪孽也不能在我眼前隐藏。","notes":[]},{"n":18,"t":"我要先加倍报应他们的罪孽和罪恶，因为他们以可憎之偶像的尸首使我的地玷污，使我的产业充斥可厌之物。”","notes":[]},{"n":19,"t":"耶和华啊，你是我的力量，是我的保障，在患难之日是我的避难所。列国的人必从地极来到你这里，说：“我们祖先所承受的，不过是虚假，是虚空无益之物。","notes":[],"heads":["耶利米的信心祈祷"]},{"n":20,"t":"人岂可为自己制造神明呢？其实它们不是神明。”","notes":[]},{"n":21,"t":"“所以，看哪，我要使他们知道，就是这一次使他们知道我的手和我的能力。他们就知道我的名是耶和华了。”","notes":[]}]},"17":{"heading":"犹大的罪和惩罚","verses":[{"n":1,"t":"犹大的罪是用铁笔、用金刚石记录的，铭刻在他们的心版和祭坛角上。","notes":[]},{"n":2,"t":"他们的儿女思念他们在高冈上、青翠树旁的祭坛和亚舍拉。","notes":[]},{"n":3,"t":"我田野的山哪，因你在全境内的丘坛所犯的罪，我必使你的财富和一切的财宝成为掠物。","notes":[]},{"n":4,"t":"因自己所做的，你必失去我所赐给你的产业。我也必使你在你所不认识的地服侍你的仇敌；因你们激起了我的怒火，直烧到永远。","notes":["“因自己所做的”：原文另译“因自己的手所做的”或没有“因自己所做的”。"]},{"n":5,"t":"耶和华如此说：“倚靠人，以血肉为膀臂，心中离弃耶和华的，那人该受诅咒！","notes":[],"heads":["训诲集"]},{"n":6,"t":"他必像沙漠里的矮树，不见福乐来到；他要住在旷野干旱之处，无人居住的盐地。","notes":[]},{"n":7,"t":"倚靠耶和华、以耶和华为他所仰赖的，那人有福了！","notes":[]},{"n":8,"t":"他必像树栽于水旁，在河边扎根，炎热来到，毫不察觉，叶子仍必青翠；在干旱之年，一无挂虑，并且结果不止。","notes":["“察觉”：原文另译“惧怕”。"]},{"n":9,"t":"“人心比万物都诡诈，坏到极处，谁能识透呢？","notes":[]},{"n":10,"t":"我－耶和华是鉴察人心，考验人肺腑的，要按各人所行的和他做事的结果报应他。”","notes":[]},{"n":11,"t":"那不按正道得财富的，好像鹧鸪孵不是自己生的；到了中年，财富必离开他，终久他必成为愚顽人。","notes":[]},{"n":12,"t":"我们的圣所是荣耀的宝座，从太初就在高处。","notes":[]},{"n":13,"t":"耶和华－以色列的盼望啊，凡离弃你的必蒙羞。离我而去的，他们必被写在地里，因为他们离弃耶和华，这活水的泉源。","notes":[]},{"n":14,"t":"耶和华啊，求你医治我，我就痊愈，拯救我，我便得救；因你是我所赞美的。","notes":[],"heads":["耶利米求耶和华帮助"]},{"n":15,"t":"看哪，他们对我说：“耶和华的话在哪里呢？让它应验吧！”","notes":[]},{"n":16,"t":"至于我，我并没有逃避作牧人跟随你，也没有想望那灾殃的日子；这是你所知道的。我嘴唇所出的都在你面前。","notes":["“我并没有...跟随你”：原文另译“我不求你派来灾难”。"]},{"n":17,"t":"不要使我因你惊恐；灾祸来临时，你是我的避难所。","notes":[]},{"n":18,"t":"愿那些迫害我的蒙羞，却不要使我蒙羞；使他们惊惶，却不要使我惊惶；愿灾祸的日子临到他们，以加倍的毁坏毁坏他们。","notes":[]},{"n":19,"t":"耶和华对我如此说：“你去站在犹大君王出入的平民门，和耶路撒冷的各城门口，","notes":[],"heads":["关于遵守安息日"]},{"n":20,"t":"对他们说：‘你们这犹大君王、犹大众人和耶路撒冷所有的居民，凡从这些城门进入的，都当听耶和华的话。","notes":[]},{"n":21,"t":"耶和华如此说：你们要谨慎，不可在安息日挑什么担子进入耶路撒冷的城门，","notes":[]},{"n":22,"t":"也不可在安息日从家中挑担子出去。无论何工都不可做，只要以安息日为圣日，正如我所吩咐你们祖先的。’","notes":[]},{"n":23,"t":"他们却不听从，也不侧耳而听，竟硬着颈项不听，不肯领受训诲。","notes":[]},{"n":24,"t":"“你们若留意听从我，在安息日不挑什么担子进入这城的各门，只以安息日为圣日，在那日不做任何工作，这是耶和华说的，","notes":[]},{"n":25,"t":"就必有坐大卫宝座的君王和领袖，与犹大人，并耶路撒冷的居民，或坐车，或骑马，进入这城的各门，而且这城必存到永远。","notes":[]},{"n":26,"t":"也必有人从犹大城镇和耶路撒冷四围的各处，从便雅悯地、谢非拉、山区，并尼革夫而来，都带燔祭和祭物，素祭和乳香，并感谢祭，到耶和华的殿去。","notes":["“谢非拉”是音译，意思是“低地”；本卷书下同。"]},{"n":27,"t":"你们若不听从我，不以安息日为圣日，仍在安息日挑担子进入耶路撒冷的各城门，我必在城门中点火；这火必烧毁耶路撒冷的宫殿，不会熄灭。”","notes":[]}]},"18":{"heading":"耶利米在陶匠的家","verses":[{"n":1,"t":"耶和华的话临到耶利米，说：","notes":[]},{"n":2,"t":"“你起来，下到陶匠的家里去，在那里我要使你听见我的话。”","notes":[]},{"n":3,"t":"我就下到陶匠的家里去，看哪，他在转盘上做器皿。","notes":[]},{"n":4,"t":"陶匠用泥做的器皿在他手中做坏了，他就用它另做别的器皿，照他看为好的去做。","notes":[]},{"n":5,"t":"耶和华的话临到我，说：","notes":[]},{"n":6,"t":"“以色列家啊，我待你们岂不能像这陶匠弄泥吗？以色列家，看哪，泥在陶匠的手中怎样，你们在我的手中也怎样。这是耶和华说的。","notes":[]},{"n":7,"t":"我何时论到一邦或一国说，要拔出、拆毁、毁坏；","notes":[]},{"n":8,"t":"我所说的那一邦若回转离开他们的恶，我就改变心意，不将我想要施行的灾祸降与他们。","notes":[]},{"n":9,"t":"我何时论到一邦或一国说，要建立、栽植；","notes":[]},{"n":10,"t":"他们若行我眼中看为恶的事，不听从我的话，我就改变心意，不将我所说的福气赐给他们。","notes":[]},{"n":11,"t":"现在你要对犹大人和耶路撒冷的居民说：‘耶和华如此说：看哪，我捏塑灾祸降给你们，定意惩罚你们。你们各人当回转离开所行的恶道，改正你们的所作所为。’","notes":[]},{"n":12,"t":"“他们却说：‘没有用的，我们要照自己的计谋去行，各人要随自己顽梗的恶心行事。’”","notes":[]},{"n":13,"t":"“所以，耶和华如此说：你们且往各国访问，有谁听见这样的事？少女以色列行了一件极恐怖的事。","notes":[],"heads":["百姓忘记耶和华"]},{"n":14,"t":"黎巴嫩的雪岂能从田野的磐石上融化呢？从远处流下的凉水岂能干涸呢？","notes":["“田野”：原文另译“西连”（黎巴嫩山顶）或“全能者”（参创17．1）。","“远处”：原文是“外国”；原文另译“山上”。"]},{"n":15,"t":"我的百姓竟忘记我，向那虚无的神明烧香，它们使百姓在所行的路上、在古道上绊跌，去行未修筑的斜路，","notes":["“虚无的神明”：原文是“虚无”。"]},{"n":16,"t":"他们的地就变为荒凉，长久被人嘲笑；凡经过这地的必惊骇摇头。","notes":[]},{"n":17,"t":"在仇敌面前，我必如东风刮散他们，遭难的日子，我要以背向他们，不以脸看他们。”","notes":[]},{"n":18,"t":"他们说：“来吧！让我们设计谋害耶利米；因为我们有祭司讲律法，有智慧人设谋略，有先知说预言，都未曾断绝。来吧！让我们用舌头攻击他，不要理他一切的话。”","notes":[],"heads":["谋害耶利米"]},{"n":19,"t":"耶和华啊，求你留心听我，且听那些指控我的人的话。","notes":[]},{"n":20,"t":"人岂可以恶报善呢？他们竟挖坑要害我的性命！求你记念我站在你面前为他们说好话，要使你的愤怒转离他们。","notes":[]},{"n":21,"t":"因此，愿他们的儿女忍受饥荒，愿他们死于刀剑之手；愿他们的妻无子，且作寡妇，愿他们的男人被死亡所灭，他们的壮丁在阵上被刀击杀。","notes":[]},{"n":22,"t":"你使敌军忽然临到他们的时候，愿人听见哀声从他们的屋内发出；因他们挖坑要捉拿我，暗设罗网要绊我的脚。","notes":[]},{"n":23,"t":"耶和华啊，他们要杀我的那一切计谋，你都知道。求你不要赦免他们的罪孽，也不要从你面前涂去他们的罪恶。愿他们在你面前跌倒，愿你在发怒的时候对付他们。","notes":[]}]},"19":{"heading":"破碎的瓶","verses":[{"n":1,"t":"耶和华如此说：“你去买陶匠的瓷瓶 ，你和百姓中的长老、位尊的祭司","notes":["“你和”：七十士译本和其他古译本是“带着”。"]},{"n":2,"t":"出去到欣嫩子谷、哈珥西的门口，在那里宣告我所吩咐你的话，","notes":["“哈珥西”意思是“瓦片”。"]},{"n":3,"t":"说：‘犹大君王和耶路撒冷的居民哪，当听耶和华的话。万军之耶和华－以色列的神如此说：看哪，我必使灾祸临到这地方，凡听见的人都必耳鸣；","notes":[]},{"n":4,"t":"因为他们和他们祖先，并犹大君王都离弃我，使这地方与我疏远，在这里向素不认识的别神烧香，又使这地方遍满无辜人的血。","notes":["“使这地方与我疏远”：七十士译本是“将这地方看为平常”。"]},{"n":5,"t":"他们建造巴力的丘坛，要在火中焚烧自己的儿女，作为燔祭献给巴力。这不是我命令的，不是我吩咐的，我心里也从来没有想过。","notes":[]},{"n":6,"t":"因此，看哪，日子将到，这地方不再称为陀斐特和欣嫩子谷，反倒称为杀戮谷。这是耶和华说的。","notes":[]},{"n":7,"t":"我要在这地方使犹大和耶路撒冷的计谋落空，也必使他们在仇敌面前倒在刀下，倒在寻索其命的人手下。我要把他们的尸首给空中的飞鸟和地上的走兽作食物。","notes":[]},{"n":8,"t":"我必使这城令人惊骇嘲笑；凡路过的，必因这城所遭的灾难惊骇嘲笑。","notes":[]},{"n":9,"t":"仇敌和寻索其命的人追逼他们，使他们落在围困窘迫之中，我必使他们各人吃自己儿女的肉和朋友的肉。’","notes":[]},{"n":10,"t":"“你要在跟你同去的人眼前打碎那瓶，","notes":[]},{"n":11,"t":"对他们说：‘万军之耶和华如此说：我要打碎这民和这城，正如人打碎陶匠的器皿，不能再使其完整。他们要在陀斐特埋葬，甚至无处可葬。","notes":[]},{"n":12,"t":"我必向这地方和其中的居民如此行，使这城与陀斐特一样。这是耶和华说的。","notes":[]},{"n":13,"t":"耶路撒冷的房屋和犹大君王的宫殿，就是他们在其上向天上的万象烧香、向别神献浇酒祭的宫殿房屋，都必被玷污，和陀斐特一样。’”","notes":[]},{"n":14,"t":"耶利米从耶和华差他去说预言的陀斐特回来，站在耶和华殿的院中对众百姓说：","notes":[]},{"n":15,"t":"“万军之耶和华－以色列的神如此说：‘看哪，我必使我所说的一切灾祸临到这城和属它的城镇，因为他们硬着颈项不听我的话。’”","notes":[]}]},"20":{"heading":"耶利米跟巴施户珥的冲突","verses":[{"n":1,"t":"音麦的儿子巴施户珥祭司作耶和华殿的总管，听见耶利米预言这些事，","notes":[]},{"n":2,"t":"就打耶利米先知，用耶和华殿里上便雅悯门内的枷锁，把他锁在那里。","notes":[]},{"n":3,"t":"次日，巴施户珥开枷释放耶利米。于是耶利米对他说：“耶和华不叫你的名为巴施户珥，而叫你玛歌珥．米撒毕，","notes":["“玛歌珥．米撒毕”意思是“四面惊吓”。"]},{"n":4,"t":"因耶和华如此说：‘看哪，我要使你和你的众朋友惊吓；你们要亲眼看见他们倒在仇敌的刀下。我必将犹大人全都交在巴比伦王的手中，他要把他们掳到巴比伦去，用刀杀他们。","notes":[]},{"n":5,"t":"我要将这城中一切的货财和劳碌得来的，并一切的珍宝，以及犹大君王所有的宝物，都交在仇敌手中。仇敌要抢夺他们，抓住他们，把他们带到巴比伦去。","notes":[]},{"n":6,"t":"你，巴施户珥，和所有住在你家中的人都必被掳；你和你的朋友，就是你向他们说假预言的，都要到巴比伦去，死在那里，葬在那里。’”","notes":[]},{"n":7,"t":"耶和华啊，你欺哄了我，我也被你欺哄了。你比我强，并且得胜。我终日成为笑柄，人人都戏弄我。","notes":[],"heads":["耶利米埋怨耶和华"]},{"n":8,"t":"我每逢讲话的时候，就哀叹，我喊叫：“有暴力和毁灭！”因为耶和华的话终日成了我的凌辱和讥刺。","notes":[]},{"n":9,"t":"我若说：“我不再提耶和华，也不再奉他的名讲论”，我心里便觉得似乎有烧着的火闷在我骨中，我忍受不住，不能自禁。","notes":[]},{"n":10,"t":"我听见许多的毁谤，四围都是惊吓；连我知己朋友都看着我跌倒：“告他吧，我们要告他！或者他被引诱，我们就能胜他，在他身上报仇。”","notes":[]},{"n":11,"t":"然而，耶和华与我同在，好像可怕的勇士。因此，迫害我的都绊跌，不能得胜；他们大大蒙羞，由于行事没有智慧，必永远受那不能忘怀的羞辱。","notes":[]},{"n":12,"t":"考验义人、察看人肺腑心肠的万军之耶和华啊，求你使我得见你在他们身上报仇，因我已将我的案件向你禀明了。","notes":[]},{"n":13,"t":"你们要向耶和华唱歌！要赞美耶和华！因他救了穷人的性命脱离恶人的手。","notes":[]},{"n":14,"t":"愿我出生的那日受诅咒！愿我母亲生我的那天不蒙福！","notes":[]},{"n":15,"t":"报信给我父亲说“你得了儿子”，使我父亲甚欢喜的，愿那人受诅咒。","notes":[]},{"n":16,"t":"愿那人像耶和华所倾覆而不怜惜的城镇；愿他早晨听见哀声，中午听见呐喊；","notes":[]},{"n":17,"t":"因他没有在我未出胎就把我杀了，以致我母亲成为我的坟墓，她却一直怀着胎。","notes":["“她却一直怀着胎”：七十士译本是“胎儿就不断长大”。"]},{"n":18,"t":"我为何出胎见劳碌愁苦，在羞愧中度尽我的年日呢？","notes":[]}]},"21":{"heading":"预言耶路撒冷灭亡","verses":[{"n":1,"t":"耶和华的话临到耶利米。那时，西底家王差派玛基雅的儿子巴施户珥和玛西雅的儿子西番雅祭司到他那里去，说：","notes":[]},{"n":2,"t":"“请你为我们求问耶和华，因为巴比伦王尼布甲尼撒前来攻击我们；或者耶和华照他一切奇妙的作为待我们，使巴比伦王离开我们而去。”","notes":[]},{"n":3,"t":"耶利米对他们说：“你们当对西底家这样说：","notes":[]},{"n":4,"t":"‘耶和华－以色列的神如此说：看哪，我要使你们手中的兵器，就是你们与城外围困你们的巴比伦王和迦勒底人打仗所用的兵器转回来，把它们聚集在这城中。","notes":[]},{"n":5,"t":"我要在怒气、愤怒和大恼怒中，用伸出来的手和大能的膀臂，亲自攻击你们；","notes":[]},{"n":6,"t":"又要击打这城的居民，他们连人带牲畜都必遭遇大瘟疫而死亡。","notes":[]},{"n":7,"t":"以后，我要将犹大王西底家和他的臣仆百姓，就是在城内，从瘟疫、刀剑、饥荒中幸存的人，都交在巴比伦王尼布甲尼撒手中，交在仇敌和寻索其命的人手中。巴比伦王必用刀击杀他们，不顾惜，不同情，不怜悯。这是耶和华说的。’","notes":[]},{"n":8,"t":"“你要对这百姓说：‘耶和华如此说：看哪，我将生命的路和死亡的路摆在你们面前。","notes":[]},{"n":9,"t":"住在这城里的必遭刀剑、饥荒、瘟疫而死；但出去投降围困你们之迦勒底人的必得存活，保全自己的性命。","notes":[]},{"n":10,"t":"我向这城板脸，降祸不降福；这城必交在巴比伦王的手中，他必用火焚烧。这是耶和华说的。’”","notes":[]},{"n":11,"t":"“至于犹大王的家，你们当听耶和华的话。","notes":[],"heads":["审判犹大王室"]},{"n":12,"t":"大卫家啊，耶和华如此说：‘每早晨你们要施行公平，拯救被抢夺的脱离欺压者的手，免得我的愤怒因你们的恶行发作，如火燃起，无人能熄灭。’","notes":[]},{"n":13,"t":"住在山谷和平原磐石上的居民啊，看哪，我与你们为敌，因为你们说：‘谁能下来攻击我们？谁能进入我们的住处呢？’这是耶和华说的。","notes":[]},{"n":14,"t":"我必按你们行事的结果惩罚你们，也必使火在耶路撒冷的林中燃起，将四围所有的尽行烧灭。这是耶和华说的。”","notes":[]}]},"22":{"heading":"耶利米警告犹大王","verses":[{"n":1,"t":"耶和华如此说：“你要下到犹大王的宫中，在那里说这话，","notes":[]},{"n":2,"t":"你要说：‘坐大卫宝座的犹大王啊，你和你的臣仆，并进入这些城门的百姓，都当听耶和华的话。","notes":[]},{"n":3,"t":"耶和华如此说：你们要施行公平和公义，拯救被抢夺的脱离欺压者的手，不可亏负寄居的和孤儿寡妇，不可用残暴对待他们，也不可在这地方流无辜人的血。","notes":[]},{"n":4,"t":"你们若切实遵行这话，就必有坐大卫宝座的君王和他的臣仆百姓，或坐车或骑马，从这王宫的各门进入。","notes":[]},{"n":5,"t":"你们若不听这些话，我指着自己起誓，这王宫必变为废墟。这是耶和华说的。’","notes":[]},{"n":6,"t":"耶和华论到犹大王的家如此说：“我看你如基列，如黎巴嫩的山顶；然而，我必使你变为旷野，成为无人居住的城镇。","notes":[]},{"n":7,"t":"我要预备施行毁灭的人，各人佩带兵器攻击你；他们要砍伐你佳美的香柏树，扔在火中。","notes":[]},{"n":8,"t":"“许多国的百姓经过这城，就彼此谈论说：‘耶和华为何向这大城这样做呢？’","notes":[]},{"n":9,"t":"必有人回答说：‘是因他们离弃了耶和华－他们神的约，事奉敬拜别神。’”","notes":[]},{"n":10,"t":"不要为已死的人哀哭，也不要为他悲伤，却要为离家外出的人大大哀哭；因为他不再回来见自己的出生地。","notes":[],"heads":["关于约哈斯"]},{"n":11,"t":"因为论到离开这地方的约西亚之子犹大王沙龙，就是接续他父亲约西亚作王的，耶和华这样说：“他必不再回到这里来，","notes":["“沙龙”：王下23．30称“约哈斯”。"]},{"n":12,"t":"却要死在被掳去的地方，必不得再见这地。”","notes":[]},{"n":13,"t":"祸哉！那以不公义盖房，以不公平造楼，白白使邻舍做工，却不给工钱的人，","notes":[],"heads":["关于约雅敬"]},{"n":14,"t":"他说：“我要为自己盖宽敞的房，盖高大的楼。”他为它开窗户，以香柏木为墙板，漆上丹红色。","notes":[]},{"n":15,"t":"难道你作王就是要盖香柏木楼房争胜的吗？你的父亲岂不是也吃也喝，也施行公平和公义吗？那时他得了福乐。","notes":[]},{"n":16,"t":"他为困苦和贫穷的人伸冤，那时就得了福乐。认识我不就在此吗？这是耶和华说的。","notes":[]},{"n":17,"t":"你的眼和你的心却专顾不义之财，流无辜人的血，行欺压和残暴。","notes":[]},{"n":18,"t":"所以，耶和华论到约西亚的儿子犹大王约雅敬如此说：人必不为他举哀：“哀哉，我的哥哥！哀哉，我的姊姊！”也不为他举哀：“哀哉，我的主！哀哉，我主的荣华！”","notes":[]},{"n":19,"t":"他被埋葬好像埋驴子一样，被拖出去，扔在耶路撒冷城门外。","notes":[]},{"n":20,"t":"你要上黎巴嫩哀号，在巴珊扬声，从亚巴琳哀号，因为你所亲爱的都毁灭了。","notes":[],"heads":["关于耶路撒冷百姓的命运"]},{"n":21,"t":"你兴盛的时候，我对你说话；你却说：“我不听。”你从年轻时就是这样，不肯听我的话。","notes":[]},{"n":22,"t":"你的牧人要被风吞吃，你所亲爱的必被掳去；那时你必因你一切的恶行抱愧蒙羞。","notes":[]},{"n":23,"t":"你这住黎巴嫩、在香柏树上搭窝的，有痛苦临到你，如疼痛临到临产的妇人，那时你何等可怜！","notes":["“何等可怜”：七十士译本和其他古译本是“就会呻吟”。"]},{"n":24,"t":"耶和华说：“约雅敬的儿子犹大王哥尼雅，虽是我右手上带印的戒指，我凭我的永生起誓，我必将你从其上摘下来。","notes":["“哥尼雅”即“耶哥尼雅”，又名“约雅斤”；参王下24．6，耶24．1。"],"heads":["神审判哥尼雅"]},{"n":25,"t":"我要将你交在寻索你命的人和你所惧怕的人手中，就是巴比伦王尼布甲尼撒和迦勒底人手中。","notes":[]},{"n":26,"t":"我也要将你和生你的母亲赶到别国，不是你们出生的地方；你们必死在那里，","notes":[]},{"n":27,"t":"心中虽然很想归回那地，却不得归回。”","notes":[]},{"n":28,"t":"哥尼雅这人是被轻看、遭毁坏的罐子，是无人喜爱的器皿吗？他和他的后裔为何被赶到素不认识之地呢？","notes":[]},{"n":29,"t":"地啊，地啊，地啊，当听耶和华的话！","notes":[]},{"n":30,"t":"耶和华如此说：“要把这人登记为无子，是平生不得亨通的人；因为他后裔中再无一人得亨通，能坐在大卫的宝座上治理犹大。”","notes":[]}]},"23":{"heading":"对将来的希望","verses":[{"n":1,"t":"耶和华说：“祸哉！那些残害、赶散我草场之羊的牧人！”","notes":[]},{"n":2,"t":"耶和华－以色列的神论到那些牧养他百姓的牧人如此说：“你们赶散我的羊群，并未看顾他们；看哪，我必惩罚你们的恶行。这是耶和华说的。","notes":[]},{"n":3,"t":"我要从我赶他们到的各国召集我羊群中剩余的，领他们归回本处；他们必生养众多。","notes":[]},{"n":4,"t":"我必设立牧人照管他们，牧养他们。他们不再惧怕，不再惊惶，没有一个失丧的。这是耶和华说的。","notes":[]},{"n":5,"t":"“看哪，日子将到，我要为大卫兴起公义的苗裔； 他必掌王权，行事有智慧，在地上施行公平和公义。这是耶和华说的。","notes":[]},{"n":6,"t":"在他的日子，犹大必得救，以色列也安然居住。他的名必称为‘耶和华－我们的义’。","notes":[]},{"n":7,"t":"“看哪，日子将到，人必不再指着那领以色列人从埃及地上来的永生耶和华起誓。这是耶和华说的。","notes":[]},{"n":8,"t":"人却要指着那领以色列家的后裔离开北方之地，离开我赶他们到的各国的永生耶和华起誓。他们必住在本地。”","notes":[]},{"n":9,"t":"论到那些先知，我心在我里面忧伤，我的骨头全都发颤；因耶和华和他的圣言，我像醉酒的人，像被酒所胜的人。","notes":[],"heads":["对先知的警告"]},{"n":10,"t":"全地满了犯奸淫的人！因妄自赌咒，地就悲哀，旷野的草场都枯干了。他们所行的道是恶的；他们的权力用得不对。","notes":[]},{"n":11,"t":"连先知带祭司都是亵渎的，就是在我殿中，我也看见他们的恶行。这是耶和华说的。","notes":[]},{"n":12,"t":"因此，他们的道路必像黑暗中的滑地，他们必被追赶，仆倒在其上；因为在他们受罚之年，我必使灾祸临到他们。这是耶和华说的。","notes":[]},{"n":13,"t":"我在撒玛利亚的先知中曾见狂妄的事；他们藉巴力说预言，使我的百姓以色列走迷了路。","notes":[]},{"n":14,"t":"我在耶路撒冷的先知中曾见恐怖的事；他们犯奸淫，行虚谎，又坚固恶人的手，无人回转离开自己的恶行。他们在我面前都像所多玛，耶路撒冷的居民都像蛾摩拉。","notes":[]},{"n":15,"t":"因此，万军之耶和华论到先知如此说：“看哪，我必使他们吃茵陈，喝苦水；因为亵渎的事出于耶路撒冷的先知，遍及各地。”","notes":[]},{"n":16,"t":"万军之耶和华如此说：“你们不要听这些先知向你们所说的预言。他们使你们成为虚无，所说的异象是出于自己的心，不是出于耶和华的口。","notes":[]},{"n":17,"t":"他们常对藐视我的人说：‘耶和华说：你们必享平安’又对一切按自己顽梗之心而行的人说：‘灾祸必不临到你们。’”","notes":["“他们常对...平安’”七十士译本是“他们常对藐视主的话的人说：‘你们必享平安’”。"]},{"n":18,"t":"有谁站在耶和华的会中察看并听见他的话呢？有谁留心听他的话呢？","notes":[]},{"n":19,"t":"看哪！耶和华的暴风在震怒中发出，是旋转的暴风，必转到恶人头上。","notes":[]},{"n":20,"t":"耶和华的怒气必不转消，直到他心中所定的成就了，实现了。末后的日子，你们要全然明白。","notes":[]},{"n":21,"t":"我并未差遣那些先知，他们竟自奔跑；我没有对他们说话，他们竟自预言。","notes":[]},{"n":22,"t":"他们若站在我的会中，必使我的百姓听我的话，又使他们回转离开恶道，离开他们所行的恶。","notes":[]},{"n":23,"t":"我是靠近你们的神，不是遥远的神，不是吗？这是耶和华说的。","notes":["“我是...不是吗？”或译“我岂为近处的神呢？不也为远处的神吗？”"]},{"n":24,"t":"人岂能在隐密处藏身，使我看不见他呢？这是耶和华说的。我岂不遍满天和地吗？这是耶和华说的。","notes":[]},{"n":25,"t":"我已听见那些先知所说的，他们托我的名说假预言：“我做了梦！我做了梦！”","notes":[]},{"n":26,"t":"所言虚假、心存诡诈的先知，他们这样存心要到几时呢？","notes":[]},{"n":27,"t":"他们彼此述说所做的梦，想要使我的百姓忘记我的名，正如他们祖先因巴力忘记我的名一样。","notes":[]},{"n":28,"t":"得梦的先知可以述说那梦；领受我话的人可以诚实讲我的话。糠秕怎能与麦子比较呢？这是耶和华说的。","notes":[]},{"n":29,"t":"我的话岂不像火，又像能打碎磐石的大锤吗？这是耶和华说的。","notes":[]},{"n":30,"t":"看哪，那些先知各从邻舍偷窃我的话，因此我必与他们为敌。这是耶和华说的。","notes":[]},{"n":31,"t":"那些先知用自己的舌头说是耶和华说的；看哪，我必与他们为敌。这是耶和华说的。","notes":[]},{"n":32,"t":"那些以假梦为预言，又述说这梦，以谎言和鲁莽使我百姓走迷了路的，看哪，我必与他们为敌。这是耶和华说的。我并未差遣他们，也没有吩咐他们。他们对这百姓毫无益处。这是耶和华说的。","notes":[]},{"n":33,"t":"无论是这百姓、是先知、是祭司，问你说：“耶和华有什么默示呢？”你就对他们说：“什么默示啊？我已撇弃你们了。这是耶和华说的。”","notes":["“什么默示啊？”：原文另译“你们就是重担。”"],"heads":["耶和华的默示"]},{"n":34,"t":"凡说“耶和华的默示”的，无论是先知、是祭司、是百姓，我必惩罚那人和他的家。","notes":[]},{"n":35,"t":"你们各人要对邻舍、对弟兄如此说：“耶和华回答了什么？耶和华说了什么呢？”","notes":[]},{"n":36,"t":"你们不可再提“耶和华的默示”，因为各人所说的话必成为自己的重担；你们错用了永生神、万军之耶和华－我们神的话。","notes":["“重担”和“默示”原文相同。"]},{"n":37,"t":"你们要对先知如此说：“耶和华回答了你什么？耶和华说了什么呢？”","notes":[]},{"n":38,"t":"你们若说“耶和华的默示”，耶和华就必如此说：“我曾差人到你们那里去，告诉你们不可说‘耶和华的默示’这几个字，你们却说‘耶和华的默示’；","notes":[]},{"n":39,"t":"所以，看哪，我必忘记你们，将你们和我所赐给你们并你们祖先的城都撇弃了；","notes":["“忘记你们”：原文另译“将你们举起来”。"]},{"n":40,"t":"又必使永远的凌辱和长久的羞耻临到你们，是不能忘记的。”","notes":[]}]},"24":{"heading":"两筐无花果","verses":[{"n":1,"t":"巴比伦王尼布甲尼撒将约雅敬的儿子犹大王耶哥尼雅 和犹大的领袖，并工匠、铁匠从耶路撒冷掳去，带到巴比伦。这事以后，耶和华指给我看，看哪，有两筐无花果放在耶和华殿前。","notes":["“耶哥尼雅”即“哥尼雅”；参耶22．24。"]},{"n":2,"t":"一筐是极好的无花果，像是初熟的；一筐是极坏的无花果，坏得不能吃。","notes":[]},{"n":3,"t":"耶和华对我说：“耶利米，你看见什么？”我说：“我看见无花果，好的极好，坏的极坏，坏得不能吃。”","notes":[]},{"n":4,"t":"于是耶和华的话临到我，说：","notes":[]},{"n":5,"t":"“耶和华－以色列的神如此说：‘被掳去的犹大人，就是我所打发离开这地到迦勒底人之地去的，我必看顾他们如这好的无花果，使他们得福乐。","notes":[]},{"n":6,"t":"我要眷顾他们，使他们得福乐，领他们归回这地。我也要建立他们，必不拆毁；栽植他们，必不拔出。","notes":[]},{"n":7,"t":"我要赐给他们认识我的心，认识我是耶和华。他们要作我的子民，我要作他们的神，他们要一心归向我。’”","notes":[]},{"n":8,"t":"耶和华如此说：“我必将犹大王西底家和他的众领袖，以及留在这地耶路撒冷剩余的人，并住在埃及地的犹大人都交出来，好像那极坏、坏得不能吃的无花果。","notes":[]},{"n":9,"t":"我必使他们在地上万国中成为恐惧，成为灾祸，在我赶逐他们到的各处成为凌辱、笑柄、讥笑、诅咒的对象。","notes":[]},{"n":10,"t":"我必使刀剑、饥荒、瘟疫临到他们，直到他们从我所赐给他们和他们祖先之地灭绝。”","notes":[]}]},"25":{"heading":"从北方来的敌人","verses":[{"n":1,"t":"约西亚的儿子犹大王约雅敬第四年，就是巴比伦王尼布甲尼撒的元年，耶和华论犹大众百姓的话临到耶利米。","notes":[]},{"n":2,"t":"耶利米先知就将这些话对犹大众百姓和耶路撒冷所有的居民说：","notes":[]},{"n":3,"t":"“从亚们的儿子犹大王约西亚十三年直到今日，在这二十三年中，常有耶和华的话临到我；我也一再对你们传讲，只是你们不听从。","notes":[]},{"n":4,"t":"耶和华也曾一再差遣他的仆人众先知到你们这里来，只是你们不听从，也不侧耳而听，","notes":[]},{"n":5,"t":"说：‘你们各人当回转离开恶道和恶行，就可居住耶和华从古时所赐给你们和你们祖先之地，直到永远。","notes":[]},{"n":6,"t":"不可随从别神，事奉敬拜它们，以你们手所做的惹我发怒；这样，我就不会降灾祸给你们。","notes":[]},{"n":7,"t":"然而你们不听从我，竟以手所做的惹我发怒，害了自己。这是耶和华说的。’”","notes":[]},{"n":8,"t":"所以万军之耶和华如此说：“因为你们不听我的话，","notes":[]},{"n":9,"t":"看哪，我必召北方的众族和我仆人巴比伦王尼布甲尼撒前来攻击这地和这地的居民，并四围所有的国民。我要将他们尽行灭绝，以致他们令人惊骇、嗤笑，并且永久荒凉。这是耶和华说的。","notes":["“永久荒凉”：七十士译本是“成了永久的羞辱”。"]},{"n":10,"t":"我又要止息他们欢喜和快乐的声音、新郎和新娘的声音、推磨的声音和灯的亮光。","notes":[]},{"n":11,"t":"这全地必然荒凉，令人惊骇。这些国家要服事巴比伦王七十年。","notes":[]},{"n":12,"t":"七十年满了以后，我必惩罚巴比伦王和那国，并迦勒底人之地，因他们的罪孽使那地永远荒凉。这是耶和华说的。","notes":[]},{"n":13,"t":"我也必使我向那地所说的话，就是所有记在这书上，耶利米向这些国家说的预言，都临到那地。","notes":[]},{"n":14,"t":"因为必有许多国家和大君王使迦勒底人作奴仆；我也必照他们的行为，按他们手所做的报应他们。”","notes":[]},{"n":15,"t":"耶和华－以色列的神对我如此说：“你从我手中拿这杯愤怒的酒，给我所差遣你去的各国的百姓喝。","notes":[],"heads":["神审判列国"]},{"n":16,"t":"他们喝了就要东倒西歪，并要发狂，因我使刀剑临到他们中间。”","notes":[]},{"n":17,"t":"我就从耶和华的手中拿了这杯，给耶和华所差遣我去的各国的百姓喝，","notes":[]},{"n":18,"t":"其中有耶路撒冷和犹大的城镇，并耶路撒冷的君王与领袖；因此这城镇荒凉，令人惊骇、嗤笑、诅咒，正如今日一样。","notes":[]},{"n":19,"t":"又有埃及王法老和他的臣仆、官长，以及他的众百姓，","notes":[]},{"n":20,"t":"并混居的各族和乌斯地的诸王，与非利士人之地的诸王，包括亚实基伦、迦萨、以革伦，以及亚实突剩下的人，","notes":[]},{"n":21,"t":"还有以东、摩押、亚扪人，","notes":[]},{"n":22,"t":"推罗的诸王、西顿的诸王、海的那边沿海地区的诸王，","notes":[]},{"n":23,"t":"底但、提玛、布斯，和所有剃鬓发的人，","notes":[]},{"n":24,"t":"阿拉伯的诸王、住旷野混居各族的诸王、","notes":[]},{"n":25,"t":"心利的诸王、以拦的诸王、玛代的诸王、","notes":[]},{"n":26,"t":"北方远近的诸王，以及天下、地面上的万国也一个一个都喝了，以后示沙克王也要喝。","notes":["“示沙克”就是“巴比伦”。"]},{"n":27,"t":"“你要对他们说：‘万军之耶和华－以色列的神如此说：你们要喝，且要喝醉，要呕吐，且要跌倒，不再起来，都因我使刀剑临到你们中间。’","notes":[]},{"n":28,"t":"“他们若不肯从你手中拿这杯来喝，你就要对他们说：‘万军之耶和华如此说：你们一定要喝！","notes":[]},{"n":29,"t":"看哪，我既从称为我名下的城起首施行灾祸，你们能免去惩罚吗？你们必不能免，因为我要命刀剑临到地上所有的居民。这是万军之耶和华说的。’","notes":[]},{"n":30,"t":"“所以你要向他们预言这一切的话，对他们说：‘耶和华从高天吼叫，从圣所发出声音，向自己的羊群大声吼叫；他要向地上所有的居民呐喊，像踹葡萄的人一样。","notes":[]},{"n":31,"t":"必有响声达到地极，因为耶和华与列国争辩。凡有血肉之躯的，他必审问；至于恶人，他必交给刀剑。这是耶和华说的。’","notes":[]},{"n":32,"t":"“万军之耶和华如此说：看哪，必有灾祸发出，从这国到那国，并有大暴风从地极刮起。","notes":[]},{"n":33,"t":"“到那日，从地这边到地那边，都有耶和华所杀戮的人。必无人哀哭，不得收殓，不得埋葬，必在地面上成为粪土。","notes":[]},{"n":34,"t":"“牧人哪，你们当哀号，呼喊；羊群的领导者啊，你们要在灰中翻滚；因为你们被宰杀、被分散的日子已经来到。你们要仆倒，好像珍贵的器皿打碎一样。","notes":["“被分散”是根据一些古卷；原文是“我打碎你们”。"]},{"n":35,"t":"牧人无路可逃，羊群的领导者也无法逃脱。","notes":[]},{"n":36,"t":"听啊，有牧人呼喊，有羊群领导者哀号的声音，因为耶和华摧毁他们的草场。","notes":[]},{"n":37,"t":"因耶和华猛烈的怒气，平安的羊圈都被肃清。","notes":[]},{"n":38,"t":"他像狮子离开洞穴，他们的地因凶猛的怒气和他强烈的怒气，都变为荒凉。”","notes":["“凶猛的怒气”：有古卷和七十士译本是“残暴的刀剑”。"]}]},"26":{"heading":"耶利米受审","verses":[{"n":1,"t":"约西亚的儿子犹大王约雅敬登基时，有这话从耶和华临到耶利米，说：","notes":[]},{"n":2,"t":"“耶和华如此说：你要站在耶和华殿的院内，对犹大所有城镇的人，就是到耶和华的殿来礼拜的，传讲我所吩咐你的一切话，一字也不可删减。","notes":[]},{"n":3,"t":"或者他们肯听从，各人回转离开恶道，我就改变心意，不将我因他们所行的恶、想要施行的灾祸降与他们。","notes":[]},{"n":4,"t":"你要对他们说，耶和华如此说：‘你们若不听从我，不遵行我在你们面前所设立的律法，","notes":[]},{"n":5,"t":"不听从我一再差遣我仆人众先知到你们那里去所说的话，你们果然没有听从，","notes":[]},{"n":6,"t":"我就必使这殿如示罗，使这城成为地上万国所诅咒的。’”","notes":[]},{"n":7,"t":"耶利米在耶和华殿中所说的这些话，祭司、先知与众百姓都听见了。","notes":[]},{"n":8,"t":"耶利米说完了耶和华吩咐他对众百姓说的一切话，祭司、先知与众百姓都来抓住他，说：“你该死！","notes":[]},{"n":9,"t":"你为何假借耶和华的名预言，说这殿必如示罗，这城必荒废无人居住呢？”于是众百姓都聚集在耶和华的殿中围住耶利米。","notes":[]},{"n":10,"t":"犹大的官长们听见这些事，就从王宫上到耶和华的殿，坐在耶和华殿新门的入口。","notes":[]},{"n":11,"t":"祭司、先知对官长和众百姓说：“这人该死，因为他说预言攻击这城，正如你们亲耳听见的。”","notes":[]},{"n":12,"t":"耶利米就对官长和众百姓说：“耶和华差遣我预言攻击这殿和这城，传讲你们所听见的这一切话。","notes":[]},{"n":13,"t":"现在，要改正你们的所作所为，听从耶和华－你们神的话，他就必改变心意，不把所说的灾祸降与你们。","notes":[]},{"n":14,"t":"至于我，看哪，我在你们手中，你们眼里看什么是好的，是正确的，就那样待我吧！","notes":[]},{"n":15,"t":"但你们要确实知道，你们若把我处死，就使流无辜人血的罪归给你们和这城，以及城里的居民了；因为耶和华确实差遣我到你们这里来，将这一切话传到你们耳中。”","notes":[]},{"n":16,"t":"官长和众百姓对祭司和先知说：“这人是不该死的，因为他奉耶和华－我们神的名向我们说话。”","notes":[]},{"n":17,"t":"国中的长老就有几个人起来，对聚集的众百姓说：","notes":[]},{"n":18,"t":"“当犹大王希西家的日子，有摩利沙人弥迦对犹大众百姓预言说：‘万军之耶和华如此说：锡安要被耕种像一块田地，耶路撒冷要变为废墟，这殿的山必像丛林的高处。’","notes":[]},{"n":19,"t":"犹大王希西家和犹大人岂是把他处死呢？希西家岂不是敬畏耶和华，恳求耶和华施恩吗？耶和华就改变心意，不把所说的灾祸降与他们。若处死这人，我们就做了大恶，害死自己了。”","notes":[]},{"n":20,"t":"有一个人，就是示玛雅的儿子基列．耶琳人乌利亚，也奉耶和华的名说预言；他说预言攻击这城和这地，和耶利米所说的完全一样。","notes":[]},{"n":21,"t":"约雅敬王和他所有的勇士、官长听见了乌利亚的话，王想要把他处死。乌利亚听见就惧怕，逃往埃及去了。","notes":[]},{"n":22,"t":"约雅敬王差亚革波的儿子以利拿单，带领几个人前往埃及。","notes":[]},{"n":23,"t":"他们将乌利亚从埃及带出来，解送到约雅敬王那里；王用刀杀了他，把他的尸首抛在平民的坟地中。","notes":[]},{"n":24,"t":"然而，沙番的儿子亚希甘保护耶利米，不将他交在百姓手中，以免他们把他处死。","notes":[]}]},"27":{"heading":"耶利米负轭","verses":[{"n":1,"t":"约西亚的儿子犹大王约雅敬登基时，有这话从耶和华临到耶利米，说：","notes":["“约雅敬”：有古卷是“西底家”；参3、12节。"]},{"n":2,"t":"“耶和华对我如此说：你要为自己做皮带和木轭，套在你的颈项上，","notes":[]},{"n":3,"t":"然后托那些来到耶路撒冷，到犹大王西底家那里的使节，把皮带和木轭送到以东王、摩押王、亚扪王、推罗王、西顿王那里，","notes":[]},{"n":4,"t":"且嘱咐他们转达他们的主人。万军之耶和华－以色列的神如此说，你们要对你们的主人这样说：","notes":[]},{"n":5,"t":"我用大能和伸出来的膀臂创造大地和地上的人民、牲畜。我看给谁合适，就把地给谁。","notes":[]},{"n":6,"t":"现在我将全地都交在我仆人巴比伦王尼布甲尼撒手中，也把野地的走兽给他使用。","notes":[]},{"n":7,"t":"列国都要服事他和他的子孙，直到他本国遭报的日期来到；那时，许多国家和大君王要使他作奴隶。","notes":[]},{"n":8,"t":"“无论哪一邦、哪一国，不肯服事巴比伦王尼布甲尼撒，不把颈项放在他的轭下，我必用刀剑、饥荒、瘟疫惩罚那邦，直到我藉巴比伦王的手毁灭他们。这是耶和华说的。","notes":[]},{"n":9,"t":"至于你们，不可听从你们的先知和占卜的、做梦的、观星象的，以及行邪术的；他们对你们说：‘你们必不致服事巴比伦王。’","notes":["“做梦的”是根据七十士译本和其他古译本；原文是“梦”。"]},{"n":10,"t":"他们向你们传的是假预言，要叫你们远离本地，以致我将你们赶出去，使你们灭亡。","notes":[]},{"n":11,"t":"但哪一邦肯把颈项放在巴比伦王的轭下服事他，我必使那邦仍在本地存留，在那里耕种居住。这是耶和华说的。”","notes":[]},{"n":12,"t":"我就照这一切话对犹大王西底家说：“你们要把颈项放在巴比伦王的轭下，服事他和他的百姓，就得存活。","notes":[]},{"n":13,"t":"你和你的百姓何必因刀剑、饥荒、瘟疫而死亡，像耶和华所论不肯服事巴比伦王的国家呢？","notes":[]},{"n":14,"t":"不可听那些先知对你们所说的话，他们说：‘你们必不致服事巴比伦王’，其实他们向你们传的是假预言。","notes":[]},{"n":15,"t":"耶和华说：‘我并未差遣他们，他们却托我的名传假预言，使我将你们和向你们说预言的那些先知赶出去，一同灭亡。’”","notes":[]},{"n":16,"t":"我又对祭司和这众百姓说：“耶和华如此说：你们不可听那先知对你们所说的预言，他们说：‘看哪，耶和华殿中的器皿快要从巴比伦带回来’；其实他们向你们传的是假预言。","notes":[]},{"n":17,"t":"不可听从他们，只管服事巴比伦王，就得存活。何必使这城变为废墟呢？","notes":[]},{"n":18,"t":"他们若真是先知，有耶和华的话临到他们，让他们祈求万军之耶和华，使耶和华殿中和犹大王宫内，并耶路撒冷剩下的器皿，不致被带到巴比伦去。","notes":[]},{"n":19,"t":"万军之耶和华这样论柱子、铜海、盆座，并留在这城里剩下的器皿，","notes":[]},{"n":20,"t":"就是巴比伦王尼布甲尼撒掳掠约雅敬的儿子犹大王耶哥尼雅，并犹大、耶路撒冷所有贵族时，没有从耶路撒冷掠去巴比伦的器皿。","notes":[]},{"n":21,"t":"论到那在耶和华殿中和犹大王宫内，并耶路撒冷剩下的器皿，万军之耶和华－以色列的神如此说：","notes":[]},{"n":22,"t":"它们必被带到巴比伦，存放在那里，直到我眷顾以色列人，将这些器皿带回归还此地的日子。这是耶和华说的。”","notes":[]}]},"28":{"heading":"耶利米和哈拿尼雅","verses":[{"n":1,"t":"当年，就是犹大王西底家登基第四年五月，押朔的儿子基遍人哈拿尼雅先知，在耶和华的殿中当着祭司和众百姓的面对我说：","notes":[]},{"n":2,"t":"“万军之耶和华－以色列的神如此说：我已经折断巴比伦王的轭。","notes":[]},{"n":3,"t":"二年之内，我要将巴比伦王尼布甲尼撒从这地掳掠到巴比伦的器皿，就是耶和华殿中的一切器皿，都带回此地。","notes":[]},{"n":4,"t":"我又要将约雅敬的儿子犹大王耶哥尼雅和被掳到巴比伦所有的犹大人带回此地，因为我要折断巴比伦王的轭。这是耶和华说的。”","notes":[]},{"n":5,"t":"耶利米先知当着祭司和站在耶和华殿里众百姓的面，对哈拿尼雅先知说：","notes":[]},{"n":6,"t":"“阿们！愿耶和华如此行，愿耶和华实现你所预言的话，将耶和华殿中的器皿和所有被掳去的人从巴比伦带回此地。","notes":[]},{"n":7,"t":"然而我在你和众百姓耳中所要说的话，你应当听。","notes":[]},{"n":8,"t":"从古以来，在你我以前的众先知，向多国和大邦说预言，论到战争、灾祸、瘟疫的事。","notes":["“灾祸”：有古卷是“饥荒”。"]},{"n":9,"t":"至于那预言平安的先知，到先知的话应验的时候，人就知道他真是耶和华所差来的。”","notes":[]},{"n":10,"t":"哈拿尼雅先知就取下耶利米先知颈项上的轭，把它折断。","notes":[]},{"n":11,"t":"哈拿尼雅又当着众百姓的面说：“耶和华如此说：二年之内我必照样从列国的颈项上折断巴比伦王尼布甲尼撒的轭。”耶利米先知就离开了。","notes":[]},{"n":12,"t":"哈拿尼雅先知折断耶利米先知颈项上的轭以后，耶和华的话临到耶利米，说：","notes":[]},{"n":13,"t":"“你去告诉哈拿尼雅说，耶和华如此说：你折断木轭，却换来铁轭！","notes":[]},{"n":14,"t":"万军之耶和华－以色列的神如此说：我已将铁轭加在这些国的颈项上，使他们服事巴比伦王尼布甲尼撒。他们总要服事他，我也把野地的走兽给了他。”","notes":[]},{"n":15,"t":"于是耶利米先知对哈拿尼雅先知说：“哈拿尼雅啊，你应当听！耶和华并没有差遣你，你竟使这百姓倚靠谎言。","notes":[]},{"n":16,"t":"所以耶和华如此说：看哪，我要把你从地面上除掉，你今年必死，因为你向耶和华说了叛逆的话。”","notes":[]},{"n":17,"t":"这样，哈拿尼雅先知当年七月间就死了。","notes":[]}]},"29":{"heading":"耶利米送信给巴比伦的犹大人","verses":[{"n":1,"t":"耶利米先知从耶路撒冷送信给被掳幸存的长老，以及祭司、先知，和尼布甲尼撒从耶路撒冷掳到巴比伦去的众百姓。","notes":[]},{"n":2,"t":"这是在耶哥尼雅王和太后、太监，并犹大和耶路撒冷的领袖，以及工匠、铁匠都离开耶路撒冷之后。","notes":[]},{"n":3,"t":"他藉沙番的儿子以利亚萨和希勒家的儿子基玛利的手送去；他们二人是犹大王西底家差往巴比伦去见巴比伦王尼布甲尼撒的。","notes":[]},{"n":4,"t":"信上说：“万军之耶和华－以色列的神对所有被掳的，就是我使他们从耶路撒冷被掳到巴比伦去的人如此说：","notes":[]},{"n":5,"t":"你们要建造房屋，住在其中；要开垦田园，吃园中所出产的；","notes":[]},{"n":6,"t":"要娶妻生儿养女，为你们的儿子娶妻，使你们的女儿嫁人，生儿养女。你们要在那里生养众多，不可减少。","notes":[]},{"n":7,"t":"我使你们被掳到的那城，你们要为那城求平安，为那城向耶和华祈求，因为那城得平安，你们也随着得平安。","notes":[]},{"n":8,"t":"万军之耶和华－以色列的神如此说：不要被你们中间的先知和占卜的所诱惑，也不要听信你们所做的梦，","notes":["“你们”：原文另译“他们”。"]},{"n":9,"t":"因为他们托我的名对你们说假预言，我并未差遣他们。这是耶和华说的。","notes":[]},{"n":10,"t":"“耶和华如此说：为巴比伦所定的七十年满了以后，我要眷顾你们，向你们实现我的恩言，使你们归回此地。","notes":[]},{"n":11,"t":"我知道我向你们所怀的意念是赐平安的意念，不是降灾祸的意念，要叫你们末后有指望。这是耶和华说的。","notes":[]},{"n":12,"t":"你们呼求我，向我祷告，我就应允你们。","notes":[]},{"n":13,"t":"你们寻求我，若专心寻求我，就必寻见。","notes":[]},{"n":14,"t":"我必被你们寻见，也必使你们被掳的人归回。这是耶和华说的。我必将你们从各国和我赶你们到的各处召集过来，又将你们带回我使你们被掳离开的地方。这是耶和华说的。","notes":[]},{"n":15,"t":"“你们说：‘耶和华已在巴比伦为我们兴起先知。’","notes":[]},{"n":16,"t":"所以耶和华如此论坐大卫宝座的君王和住在这城里所有的百姓，就是未曾与你们一同被掳的弟兄，","notes":[]},{"n":17,"t":"万军之耶和华如此说：‘看哪，我必使刀剑、饥荒、瘟疫临到他们，使他们像极坏的无花果，坏得不能吃。","notes":[]},{"n":18,"t":"我必用刀剑、饥荒、瘟疫追赶他们，使地上万国因他们而惊骇；在我赶他们到的各国，令人诅咒、惊骇、嗤笑、羞辱。","notes":[]},{"n":19,"t":"这是因为他们不听从我先前一再差遣我仆人众先知说的话。这是耶和华说的。你们也一样不听。这是耶和华说的。’","notes":["“你们”：有古译本是“他们”。"]},{"n":20,"t":"所以你们所有被掳去的，就是我从耶路撒冷放逐到巴比伦去的，当听耶和华的话。","notes":[]},{"n":21,"t":"万军之耶和华－以色列的神论哥赖雅的儿子亚哈和玛西雅的儿子西底家如此说：‘他们托我的名向你们说假预言，看哪，我必把他们交在巴比伦王尼布甲尼撒的手中，他要在你们眼前杀害他们。","notes":[]},{"n":22,"t":"在巴比伦所有被掳的犹大人必藉这二人赌咒说：愿耶和华使你像巴比伦王在火中焚烧的西底家和亚哈一样。","notes":[]},{"n":23,"t":"这二人在以色列中做了丑事，与邻舍的妻行淫，又假托我的名说我未曾吩咐他们的话。我知道这一切，也作见证。这是耶和华说的。’”","notes":[]},{"n":24,"t":"“你要对尼希兰人示玛雅说：","notes":[],"heads":["示玛雅的信件"]},{"n":25,"t":"万军之耶和华－以色列的神如此说：你曾用自己的名送信给耶路撒冷的众百姓和玛西雅的儿子西番雅祭司，并众祭司，说：","notes":[]},{"n":26,"t":"‘耶和华已经立你西番雅为祭司，代替耶何耶大祭司，使耶和华的殿中有总管，好把所有狂妄自称先知的人用枷枷住，用锁锁住。","notes":[]},{"n":27,"t":"现在亚拿突人耶利米向你们自称先知，你为什么不责备他呢？","notes":[]},{"n":28,"t":"他送信给我们在巴比伦的人说：被掳的事必长久，你们要建造房屋，住在其中；要开垦田园，吃园中所出产的。’”","notes":[]},{"n":29,"t":"西番雅祭司就把这信念给耶利米先知听。","notes":[]},{"n":30,"t":"于是耶和华的话临到耶利米，说：","notes":[]},{"n":31,"t":"“你当送信给所有被掳的人，说：‘耶和华论到尼希兰人示玛雅说：因为示玛雅向你们说预言，使你们倚靠谎言，而我并没有差遣他，","notes":[]},{"n":32,"t":"所以耶和华如此说：看哪，我必惩罚尼希兰人示玛雅和他的后裔，他必无一人存留住在这民中，也看不见我所要赏赐给我百姓的福乐，因为他向耶和华说了叛逆的话。这是耶和华说的。’”","notes":[]}]},"30":{"heading":"耶和华给他子民的应许","verses":[{"n":1,"t":"耶和华的话临到耶利米，说：","notes":[]},{"n":2,"t":"“耶和华－以色列的神如此说：你要将我对你说过的一切话都写在书上。","notes":[]},{"n":3,"t":"看哪，日子将到，我要使我的百姓以色列和犹大被掳的人归回。这是耶和华说的。耶和华说：我要使他们回到我所赐给他们祖先之地，他们就得这地为业。”","notes":[]},{"n":4,"t":"以下是耶和华论到以色列和犹大所说的话：","notes":[]},{"n":5,"t":"耶和华如此说：“我们听见颤抖的声音，令人惧怕，没有平安。","notes":[]},{"n":6,"t":"你们且访查看看，男人会生孩子吗？我怎么看见人人都用手撑腰，像临产的妇人，脸都发白了呢？","notes":[]},{"n":7,"t":"哀哉！那日为大，无日可比；这是雅各遭难的时刻，但他必从患难中得拯救。”","notes":["“脸都...哀哉！”：七十士译本是“脸都变白了。”"]},{"n":8,"t":"万军之耶和华说：“到那日，我必折断你颈项上仇敌的轭，拉断你的皮带。陌生人必不再使他作奴隶。","notes":[]},{"n":9,"t":"他们却要事奉耶和华－他们的神，事奉我为他们所兴起的大卫王。”","notes":[]},{"n":10,"t":"我的仆人雅各啊，不要惧怕；以色列啊，不要惊惶；因我从远方拯救你，从被掳之地拯救你的后裔；雅各必回来得享平静安逸，无人能使他害怕。这是耶和华说的。","notes":[]},{"n":11,"t":"因我与你同在，要拯救你，也要将那些国灭绝净尽，就是我赶你去的那些国；却不将你灭绝净尽，倒要从宽惩治你，但绝不能不罚你。这是耶和华说的。","notes":[]},{"n":12,"t":"耶和华如此说：“你的损伤无法医治，你的伤痕极其重大。","notes":[]},{"n":13,"t":"无人为你的伤痛辩护，也没有可医治你的良药。","notes":[]},{"n":14,"t":"你所亲爱的都忘记你，不来探望你。我因你罪孽甚大，罪恶众多，曾藉仇敌加的伤害伤害你，藉残忍者惩治你。","notes":[]},{"n":15,"t":"你为何因所受的损伤哀号呢？你的痛苦无法医治。我因你罪孽甚大，罪恶众多，曾将这些加在你身上。","notes":[]},{"n":16,"t":"因此，凡吞吃你的必被吞吃，你的敌人个个都被掳去；掳掠你的必成为掳物，我使抢夺你的成为掠物。","notes":[]},{"n":17,"t":"我必使你痊愈，医好你的伤痕，都因人称你为被赶散的，这是锡安，是无人来探望的！这是耶和华说的。”","notes":[]},{"n":18,"t":"耶和华如此说：“看哪，我必使雅各被掳去的帐棚归回，也必顾惜他的住处。城必建造在原有的废墟上，宫殿也必照样有人居住。","notes":[]},{"n":19,"t":"必有感谢和欢乐的声音从其中发出，我使他们增多，不致减少；使他们尊荣，不致卑微。","notes":[]},{"n":20,"t":"他们的儿女必如往昔；他们的会众坚立在我面前；凡欺压他们的，我必惩罚。","notes":[]},{"n":21,"t":"他们的君王是他们自己的人，掌权的必出自他们。我要使他接近我，他也要亲近我；不然，谁敢放胆亲近我呢？这是耶和华说的。","notes":[]},{"n":22,"t":"你们要作我的子民，我要作你们的神。”","notes":[]},{"n":23,"t":"看哪，耶和华的愤怒如暴风已经发出；是扫灭的暴风，必转到恶人的头上。","notes":[]},{"n":24,"t":"耶和华的烈怒必不转消，直到他心中所定的成就了，实现了；末后的日子你们就会明白。","notes":[]}]},"31":{"heading":"以色列人回乡","verses":[{"n":1,"t":"耶和华说：“那时，我必作以色列各家的神，他们必作我的子民。”","notes":[]},{"n":2,"t":"耶和华如此说：“从刀剑生还的百姓在旷野蒙恩；以色列寻找安歇之处。”","notes":[]},{"n":3,"t":"耶和华从远方向我显现：“我以永远的爱爱你，因此，我以慈爱吸引你。”","notes":[]},{"n":4,"t":"少女以色列啊，我要再建立你，你就得以建立；你必再拿起手鼓，随着欢乐的舞者而出。","notes":[]},{"n":5,"t":"你必在撒玛利亚的山上栽葡萄园，栽种的人栽种，而且享用。","notes":[]},{"n":6,"t":"日子将到，守望的人必在以法莲山上呼叫：“起来吧！我们要上锡安，到耶和华－我们的神那里去。”","notes":[]},{"n":7,"t":"耶和华如此说：“你们当为雅各欢乐歌唱，为万国中为首的欢呼。当传扬，颂赞说：‘耶和华啊，求你拯救你的百姓，拯救以色列的余民。’","notes":["“耶和华啊...你的百姓”：七十士译本是“主已拯救他的百姓”。"]},{"n":8,"t":"看哪，我必将他们从北方之地领来，从地极召集而来；同他们来的有盲人、瘸子、孕妇、产妇；他们必成群结队回到这里。","notes":[]},{"n":9,"t":"他们要哭泣而来。我要照他们恳求的引导他们，使他们在河水旁行走正直的路，他们在其上必不致绊跌；因为我是以色列的父，以法莲是我的长子。","notes":[]},{"n":10,"t":"列国啊，要听耶和华的话，要在远方的海岛传扬，说：“赶散以色列的必召集他，看守他，如牧人看守羊群。”","notes":[]},{"n":11,"t":"因为耶和华救赎了雅各，救赎他脱离比他更强之人的手。","notes":[]},{"n":12,"t":"他们来到锡安的高处歌唱，因耶和华的宏恩而喜乐洋溢，就是五谷、新酒和新的油，并羔羊和牛犊。他们必像有水浇灌的园子，一点也不再有愁烦。","notes":[]},{"n":13,"t":"那时，少女必欢乐跳舞；年轻的、年老的，都一同欢乐；因为我要使他们的悲哀变为欢喜，并要安慰他们，使他们的愁烦转为喜乐。","notes":[]},{"n":14,"t":"我必以肥油使祭司的心满足，我的百姓也要因我的恩惠知足。这是耶和华说的。","notes":[]},{"n":15,"t":"耶和华如此说：“在拉玛听见号啕痛哭的声音，是拉结哭她儿女，不肯因她儿女受安慰，因为他们都不在了。”","notes":[],"heads":["耶和华怜悯以色列"]},{"n":16,"t":"耶和华如此说：“不要出声哀哭，你的眼目也不要流泪；因你的辛劳必有报偿，他们必从仇敌之地归回。这是耶和华说的。","notes":[]},{"n":17,"t":"你末后必有指望，你的儿女必回到自己的疆土。这是耶和华说的。","notes":[]},{"n":18,"t":"我听见以法莲为自己悲叹说：‘你管教我，我便受管教，我如未驯服的牛犊。求你使我回转，我便回转，因为你是耶和华－我的神。","notes":[]},{"n":19,"t":"我背离以后就懊悔，受教以后就捶胸；我因担当年轻时的凌辱就抱愧蒙羞。’","notes":["“捶胸”：原文直译“拍腿”，表示苦恼和悲伤。"]},{"n":20,"t":"以法莲是我的爱子吗？是我喜欢的孩子吗？我每逢责备他，仍深顾念他。因此，我的心肠牵挂着他，我必要怜悯他。这是耶和华说的。","notes":[]},{"n":21,"t":"少女以色列啊，当为自己设立路标，为自己竖起指路牌。要留心向着大道，就是你曾走过的路；你当回转，回到你自己的城镇。","notes":[]},{"n":22,"t":"背道的女子啊，你翻来覆去要到几时呢？耶和华在地上造了一件新事，就是女子护卫男子。”","notes":[]},{"n":23,"t":"万军之耶和华－以色列的神如此说：“我使被掳之人归回的时候，他们在犹大地和其中的城镇必再这样说：公义的居所啊，圣山哪，愿耶和华赐福给你。","notes":[],"heads":["神子民光明的前途"]},{"n":24,"t":"犹大和犹大城镇的人，耕地的和带着群畜游牧的人，都要一同住在其中。","notes":[]},{"n":25,"t":"疲乏的人，我使他振作；愁烦的人，我使他满足。”","notes":[]},{"n":26,"t":"于是我醒了，我看到我睡得香甜。","notes":[]},{"n":27,"t":"“看哪，日子将到，我要使人的后代和牲畜的种，在以色列家和犹大家繁衍。这是耶和华说的。","notes":[]},{"n":28,"t":"我先前怎样看守他们，为要拔出、拆毁、毁坏、倾覆、苦害，也必照样看守他们，为要建立、栽植。这是耶和华说的。","notes":[]},{"n":29,"t":"当那些日子，人不再说：‘父亲吃了酸葡萄，儿子牙齿就酸倒。’","notes":[]},{"n":30,"t":"但各人要因自己的罪死亡；凡吃酸葡萄的，自己的牙必酸倒。","notes":[]},{"n":31,"t":"“看哪，日子将到，我要与以色列家和犹大家另立新的约。这是耶和华说的。","notes":[]},{"n":32,"t":"这约不像我拉着他们祖宗的手，领他们出埃及地的时候与他们所立的约。我虽作他们的丈夫，他们却背了我的约。这是耶和华说的。","notes":[]},{"n":33,"t":"那些日子以后，我与以色列家所立的约是这样：我要将我的律法放在他们里面，写在他们心上。我要作他们的神，他们要作我的子民。这是耶和华说的。","notes":[]},{"n":34,"t":"他们各人不再教导自己的邻舍和弟兄说：‘你该认识耶和华’，因为他们从最小的到最大的都必认识我。我要赦免他们的罪孽，不再记得他们的罪恶。这是耶和华说的。”","notes":[]},{"n":35,"t":"耶和华使太阳白昼发光，按定例使月亮和星辰照耀黑夜，又搅动大海，使海中波浪澎湃，万军之耶和华是他的名，他如此说：","notes":[]},{"n":36,"t":"“这些定例若能在我面前废掉，以色列的后裔才会在我面前断绝，永远不再成国。这是耶和华说的。”","notes":[]},{"n":37,"t":"耶和华如此说：“若有人能测量上面的天，探索下面地的根基，我才会因以色列后裔所做的一切弃绝他们。这是耶和华说的。”","notes":[]},{"n":38,"t":"看哪，日子将到，这城必为耶和华而造，从哈楠业楼直到角门。这是耶和华说的。","notes":[]},{"n":39,"t":"丈量的绳子要往外拉出，直到迦立山，又转到歌亚；","notes":[]},{"n":40,"t":"抛尸的全谷和倒灰之处，并一切田地，直到汲沦溪，又到东边马门的角落，都要归耶和华为圣；不再拔出，不再倾覆，直到永远。","notes":[]}]},"32":{"heading":"耶利米购置田地","verses":[{"n":1,"t":"犹大王西底家第十年，就是尼布甲尼撒十八年，耶和华的话临到耶利米。","notes":[]},{"n":2,"t":"那时巴比伦王的军队围困耶路撒冷，耶利米先知被囚在犹大王宫中护卫兵的院内；","notes":[]},{"n":3,"t":"因为犹大王西底家囚禁他，说：“你为什么预言耶和华如此说：‘看哪，我要把这城交在巴比伦王的手中，他必攻下这城。","notes":[]},{"n":4,"t":"犹大王西底家必不能逃脱迦勒底人的手，定要交在巴比伦王手中，他要亲眼看到巴比伦王，亲口跟他说话。","notes":[]},{"n":5,"t":"巴比伦王要将西底家带到巴比伦；西底家必住在那里，直到我惩罚他的时候。你们虽与迦勒底人争战，却不顺利。这是耶和华说的。’”","notes":["“惩罚”或译“眷顾”。"]},{"n":6,"t":"耶利米说：“耶和华的话临到我，说：","notes":[]},{"n":7,"t":"‘看哪，你叔父沙龙的儿子哈拿篾必到你这里来，说：请你买我在亚拿突的那块地，因为你有代赎的责任。’","notes":[]},{"n":8,"t":"我叔父的儿子哈拿篾果然照耶和华的话来到护卫兵的院内，对我说：‘请你买我在便雅悯境内、亚拿突的那块地；因为它应该由你来承受，而且你也有代赎的责任。请你买下它吧！’我就知道这确是耶和华的话。","notes":[]},{"n":9,"t":"“我便向我叔父的儿子哈拿篾买了亚拿突的那块地，秤了十七舍客勒银子给他。","notes":[]},{"n":10,"t":"我在契上签字，将契封缄，又请证人来，用天平把银子秤给他。","notes":[]},{"n":11,"t":"我又将按照法定条例所立的买契，就是封缄的那一张和敞开的那一张，","notes":[]},{"n":12,"t":"在我叔父的儿子哈拿篾和签字作证的人，并坐在护卫兵院内所有犹大人眼前，交给玛西雅的孙子尼利亚的儿子巴录。","notes":["“我叔父的儿子”是根据一些古卷、七十士译本和其他古译本；原文是“我叔父”。"]},{"n":13,"t":"我在众人眼前嘱咐巴录说：","notes":[]},{"n":14,"t":"‘万军之耶和华－以色列的神如此说：你拿着这文件，就是封缄的和敞开的买契，把它们放在瓦器里，以便长久保存。","notes":[]},{"n":15,"t":"因为万军之耶和华－以色列的神如此说：将来在这地必有人再购置房屋、田地和葡萄园。’”","notes":[]},{"n":16,"t":"“我将买契交给尼利亚的儿子巴录以后，就向耶和华祷告说：","notes":[],"heads":["耶利米的祈祷"]},{"n":17,"t":"‘唉！主耶和华，看哪，你曾用大能和伸出来的膀臂创造天和地，在你没有难成的事。","notes":[]},{"n":18,"t":"你施慈爱给千万人，又将祖先的罪孽报应在他后世子孙身上。至大全能的神啊，万军之耶和华是你的名，","notes":[]},{"n":19,"t":"你谋事有大略，行事有大能，注目观看世人一切的举动，为要照各人所做的和他做事的结果报应他。","notes":[]},{"n":20,"t":"你在埃及地显神迹奇事，直到今日在以色列和世人中间也是如此，建立了自己的名声，正如今日一样。","notes":[]},{"n":21,"t":"你用神迹奇事、大能的手、伸出来的膀臂和大可畏的事，领你的百姓以色列出了埃及，","notes":[]},{"n":22,"t":"把这地赏赐给他们，就是你向他们列祖起誓应许要赐给他们的流奶与蜜之地。","notes":[]},{"n":23,"t":"他们进入并取得这地，却不听从你的话，也不遵行你的律法。你吩咐他们所当行的，他们都不去行，因此你使这一切的灾祸临到他们。","notes":[]},{"n":24,"t":"看哪，敌人已经来到，用土堆攻取这城；这城也因刀剑、饥荒、瘟疫被交在攻城的迦勒底人手中。你所说的话都应验了，看哪，你也看见了。","notes":[]},{"n":25,"t":"主耶和华啊，你却对我说，要用银子为自己买那块地，又请人作证；其实这城已交在迦勒底人的手中了。’”","notes":[]},{"n":26,"t":"耶和华的话临到耶利米，说：","notes":[]},{"n":27,"t":"“看哪，我是耶和华，是凡有血肉之躯者的神，在我岂有难成的事吗？","notes":[]},{"n":28,"t":"耶和华如此说：看哪，我必将这城交给迦勒底人的手和巴比伦王尼布甲尼撒的手，他必攻取这城。","notes":[]},{"n":29,"t":"攻城的迦勒底人必来放火焚烧这城和城里的房屋；人曾在这房顶上向巴力烧香，向别神献浇酒祭，惹我发怒。","notes":[]},{"n":30,"t":"以色列人和犹大人从年轻时，就专做我眼中看为恶的事。以色列人尽以手所做的惹我发怒。这是耶和华说的。","notes":[]},{"n":31,"t":"这城自从建造的那日直到今日，常惹我的怒气和愤怒，以致我将这城从我面前除掉；","notes":[]},{"n":32,"t":"这是因以色列人和犹大人一切的邪恶，就是他们和他们的君王、官长、祭司、先知，并犹大人，以及耶路撒冷居民所做的，惹我发怒。","notes":[]},{"n":33,"t":"他们以背向我，不以面向我；我虽然一再教导他们，他们却不听从，不领受训诲，","notes":[]},{"n":34,"t":"竟把可憎之偶像设立在称为我名下的殿中，玷污了这殿。","notes":[]},{"n":35,"t":"他们在欣嫩子谷建造巴力的丘坛，把自己的儿女经火献给摩洛；他们行这可憎的事，使犹大陷在罪里，这并不是我吩咐的，我心里也从来没有想过。”","notes":[]},{"n":36,"t":"现在论到这城，就是你们所说，已经因刀剑、饥荒、瘟疫被交在巴比伦王手中的，耶和华－以色列的神如此说：","notes":[],"heads":["复国的应许"]},{"n":37,"t":"“看哪，我曾在怒气、愤怒和大恼怒中，将以色列人赶到各国；我必从那里将他们召集出来，领他们回到此地，使他们安然居住。","notes":[]},{"n":38,"t":"他们要作我的子民，我要作他们的神。","notes":[]},{"n":39,"t":"我要使他们彼此同心同道，好叫他们永远敬畏我，使他们和他们后世的子孙得享福乐。","notes":[]},{"n":40,"t":"我要跟他们立永远的约，要施恩给他们，绝不转离；又要把敬畏我的心放在他们心里，不离弃我。","notes":[]},{"n":41,"t":"我必欢喜施恩给他们，尽心尽意、真诚地将他们栽于此地。","notes":[]},{"n":42,"t":"“因为耶和华如此说：我怎样使这一切大灾祸临到这百姓，也要照样使我所应许他们的一切福乐都临到他们。","notes":[]},{"n":43,"t":"你们所说荒凉、无人、无牲畜，已交给迦勒底人手的这地，必有人购置田地。","notes":[]},{"n":44,"t":"在便雅悯地、耶路撒冷四围的各处、犹大的城镇、山地的城镇、谢非拉的城镇，并尼革夫的城镇，人必用银子买田地，在契上签字，将契封缄，找人作证，因为我必使被掳的人归回。这是耶和华说的。”","notes":[]}]},"33":{"heading":"重申复国的应许","verses":[{"n":1,"t":"耶利米还囚在护卫兵的院内，耶和华的话第二次临到他，说：","notes":[]},{"n":2,"t":"“成事的耶和华，塑造它为要建立它的耶和华，名为耶和华的那位如此说：","notes":[]},{"n":3,"t":"‘你求告我，我就应允你，并将你所不知道、又大又隐密的事指示你。","notes":[]},{"n":4,"t":"论到这城中的房屋和犹大君王的宫殿，就是拆毁来挡围城工事和刀剑的，耶和华－以色列的神如此说：","notes":[]},{"n":5,"t":"他们与迦勒底人争战，用我在怒气和愤怒中所杀之人的尸首塞满这房屋；我因他们一切的恶，转脸不顾这城。","notes":[]},{"n":6,"t":"看哪，我要使这城得以痊愈安舒，我要医治他们，将丰盛的平安与信实显明给他们。","notes":[]},{"n":7,"t":"我也要使犹大被掳的和以色列被掳的人归回，并要建立他们，如起初一样。","notes":[]},{"n":8,"t":"我要洗净他们干犯我的一切罪，赦免他们干犯我、违背我的一切罪。","notes":[]},{"n":9,"t":"这城在地上万国面前要因我的缘故，以喜乐得名，得颂赞，得荣耀，因为他们听见我所赏赐的一切福乐。他们因我向这城所施的一切福乐平安，就惧怕战兢。”","notes":[]},{"n":10,"t":"耶和华如此说：“你们论这地方，说是荒废、无人、无牲畜之地，但在这荒凉、无人、无居民、无牲畜的犹大城镇和耶路撒冷街上，必再听见","notes":[]},{"n":11,"t":"欢喜和快乐的声音、新郎和新娘的声音，并听见有人说：你们要称谢万军之耶和华，因耶和华本为善，他的慈爱永远长存！他们奉感谢祭到耶和华的殿中；因为我必使这地被掳的人归回，如起初一样。这是耶和华说的。”","notes":[]},{"n":12,"t":"万军之耶和华如此说：“在这荒废、无人、无牲畜之地，并其中所有的城镇，必再有牧人的草场，可让羊群躺卧在那里。","notes":[]},{"n":13,"t":"在山区的城镇、谢非拉的城镇、尼革夫的城镇、便雅悯地、耶路撒冷四围的各处和犹大的城镇，必再有羊群从数点的人手下经过。这是耶和华说的。","notes":[]},{"n":14,"t":"“看哪，日子将到，我应许以色列家和犹大家的恩言必然实现。这是耶和华说的。","notes":[]},{"n":15,"t":"在那些日子、那时候，我必使大卫公义的苗裔长起来；他必在地上施行公平和公义。","notes":[]},{"n":16,"t":"在那些日子，犹大必得救，耶路撒冷必安然居住，他的名必称为‘耶和华－我们的义’。","notes":[]},{"n":17,"t":"“因为耶和华如此说：大卫家必永远不断有人坐在以色列家的宝座上；","notes":[]},{"n":18,"t":"利未家的祭司也不断有人在我面前献燔祭、烧素祭，时常办理献祭的事。”","notes":[]},{"n":19,"t":"耶和华的话临到耶利米，说：","notes":[]},{"n":20,"t":"“耶和华如此说：你们若能废弃我所立白日黑夜的约，使白日黑夜不按时轮转，","notes":[]},{"n":21,"t":"就能废弃我与我仆人大卫所立的约，使他没有后裔在他的宝座上作王，并能废弃我与事奉我的利未家的祭司所立的约。","notes":[]},{"n":22,"t":"正如天上的万象不能数算，海边的尘沙不能斗量，我必照样使我仆人大卫的后裔和事奉我的利未人多起来。”","notes":[]},{"n":23,"t":"耶和华的话临到耶利米，说：","notes":[]},{"n":24,"t":"“你没有留意这百姓所说的话吗？他们说：‘耶和华所拣选的二族，他已经弃绝了。’他们这样藐视我的百姓，不把他们当作国来看待。","notes":[]},{"n":25,"t":"耶和华如此说：除非我没有立白日黑夜之约，也未曾安排天和地的定例，","notes":[]},{"n":26,"t":"否则我不会弃绝雅各的后裔和我仆人大卫的后裔，使大卫的后裔不再治理亚伯拉罕、以撒、雅各的后裔。我必使他们被掳的人归回，也必怜悯他们。”","notes":[]}]},"34":{"heading":"给西底家的信息","verses":[{"n":1,"t":"巴比伦王尼布甲尼撒率领他的全军和地上他管辖的各国各邦，攻打耶路撒冷和耶路撒冷所有的城镇。那时，耶和华的话临到耶利米，说：","notes":[]},{"n":2,"t":"“耶和华－以色列的神说，你去告诉犹大王西底家，耶和华如此说：看哪，我要把这城交在巴比伦王的手中，他必用火焚烧。","notes":[]},{"n":3,"t":"你必不能逃脱他的手，定被拿住，交在他手中。你要亲眼看到巴比伦王，他要亲口跟你说话，你也必到巴比伦去。","notes":[]},{"n":4,"t":"犹大王西底家啊，你一定要听耶和华的话。耶和华论到你如此说：你必不死于刀下；","notes":[]},{"n":5,"t":"必平安而终，人要为你焚烧，好像为你祖先，就是在你以前早先的王焚烧一样。人要为你举哀说：‘哀哉！我主啊。’这话是我说的。这是耶和华说的。”","notes":[]},{"n":6,"t":"于是，耶利米先知在耶路撒冷把这一切话告诉犹大王西底家。","notes":[]},{"n":7,"t":"那时，巴比伦王的军队正攻打耶路撒冷，又攻打犹大仅存的城镇，就是拉吉和亚西加；原来犹大的坚固城只剩下这两座。","notes":[]},{"n":8,"t":"西底家王与耶路撒冷的众百姓立约，要他们宣告自由，叫各人释放自己的仆人和婢女，使希伯来的男人和女人得自由，谁也不可使他的犹大弟兄作奴仆。这事以后，耶和华的话临到耶利米。","notes":[],"end":9,"heads":["违背释放奴隶的约"]},{"n":10,"t":"所有前来立约的领袖和众百姓都顺从，各人释放自己的仆人和婢女，使他们得自由，不再叫他们作奴仆。大家都顺从，将仆婢释放了。","notes":[]},{"n":11,"t":"但后来他们又反悔，叫被释放得自由的仆人婢女回来，强迫他们仍为仆婢。","notes":[]},{"n":12,"t":"因此耶和华的话临到耶利米，说：","notes":[]},{"n":13,"t":"“耶和华－以色列的神如此说：我将你们祖先从埃及地为奴之家领出时，与他们立约说：","notes":[]},{"n":14,"t":"‘你的一个希伯来弟兄若卖给你，服事你六年，到第七年你们各人就要释放他自由出去。’只是你们祖先不听我，不侧耳而听。","notes":[]},{"n":15,"t":"如今你们回转，行我眼中看为正的事，各人向邻舍宣告自由，并且在我面前、在称为我名下的殿中立约。","notes":[]},{"n":16,"t":"你们却反悔，亵渎我的名，各人叫所释放得自由的仆人婢女回来，强迫他们仍为仆婢。","notes":[]},{"n":17,"t":"所以耶和华如此说：你们不听从我，各人不向弟兄邻舍宣告自由。看哪！我要向你们宣告自由，把你们自由地交给刀剑、饥荒、瘟疫，并且使地上万国因你们而惊骇。这是耶和华说的。","notes":[]},{"n":18,"t":"那些违背我约的人，就是不遵守在我面前立约之话的，我要使他们成了那劈成两半的牛犊，使人从切块中经过：","notes":[]},{"n":19,"t":"犹大的领袖、耶路撒冷的领袖、官员、祭司，和从牛犊切块中经过的这地的众百姓，","notes":[]},{"n":20,"t":"我必将他们交在仇敌和寻索其命的人手中；他们的尸首必给空中的飞鸟和地上的走兽作食物。","notes":[]},{"n":21,"t":"我必将犹大王西底家和他的众领袖交在仇敌和寻索其命的人手中，与那暂时离你们而去的巴比伦王军队的手中。","notes":[]},{"n":22,"t":"看哪，我要吩咐他们回到这城，攻打这城，将城攻取，用火焚烧；我也要使犹大的城镇变为废墟，无人居住。这是耶和华说的。”","notes":[]}]},"35":{"heading":"耶利米和利甲族","verses":[{"n":1,"t":"当约西亚的儿子约雅敬作犹大王的时候，耶和华的话临到耶利米，说：","notes":[]},{"n":2,"t":"“你去见利甲族的人，吩咐他们，领他们进入耶和华殿的一个房间，给他们酒喝。”","notes":[]},{"n":3,"t":"我就带哈巴洗尼雅的孙子雅利米雅的儿子雅撒尼亚，和他的兄弟，并他所有的儿子，以及利甲全族的人，","notes":[]},{"n":4,"t":"领他们到耶和华的殿，进入伊基大利的儿子神人哈难儿子们的房间；那房间靠近官长的房间，在沙龙之子门口的守卫玛西雅的房间上面。","notes":[]},{"n":5,"t":"于是我在利甲族的人面前摆设盛满了酒的碗和杯，对他们说：“请喝酒。”","notes":[]},{"n":6,"t":"他们却说：“我们不喝酒，因为我们祖先利甲的儿子约拿达曾吩咐我们说：‘你们与你们的子孙永不可喝酒，","notes":[]},{"n":7,"t":"不可盖房子，不可撒种，也不可栽葡萄园，连拥有都不可；但一生的年日要住帐棚，使你们的日子在寄居的地面上得以长久。’","notes":[]},{"n":8,"t":"凡我们祖先利甲的儿子约拿达所吩咐我们的话，我们都听从了。我们和我们的妻子儿女一生的年日都不喝酒，","notes":[]},{"n":9,"t":"不盖房子居住，我们也没有葡萄园、田地和种子；","notes":[]},{"n":10,"t":"但住在帐棚里，听从并遵行我们祖先约拿达所吩咐我们的一切话。","notes":[]},{"n":11,"t":"巴比伦王尼布甲尼撒上来攻打这地的时候，我们说：‘来吧，我们到耶路撒冷去，躲避迦勒底的军队和亚兰的军队。’这样，我们才住在耶路撒冷。”","notes":[]},{"n":12,"t":"耶和华的话临到耶利米，说：","notes":[]},{"n":13,"t":"“万军之耶和华－以色列的神如此说：你去对犹大人和耶路撒冷的居民说，你们不肯领受训诲，听从我的话吗？这是耶和华说的。","notes":[]},{"n":14,"t":"利甲的儿子约拿达所吩咐他子孙不可喝酒的话，他们已经遵守了；他们因为听从祖先的吩咐，直到今日都不喝酒。至于我，我一再警戒你们，你们却不肯听从我。","notes":[]},{"n":15,"t":"我一再差遣我的仆人众先知到你们那里去，说：‘你们各人当回头离开恶道，改正行为，不再随从事奉别神，如此，就必住在我所赐给你们和你们祖先的地上。’只是你们不侧耳而听，也不听我。","notes":[]},{"n":16,"t":"利甲的儿子约拿达的子孙能遵守祖先所吩咐他们的命令，这百姓却不肯听从我！","notes":[]},{"n":17,"t":"因此，耶和华－万军之神、以色列的神如此说：看哪，我要使我所说的一切灾祸临到犹大人和耶路撒冷所有的居民。因为我向他们说话，他们不听从；我呼唤他们，他们也没有回应。”","notes":[]},{"n":18,"t":"耶利米对利甲族的人说：“万军之耶和华－以色列的神如此说：因你们听从你们祖先约拿达的吩咐，谨守他的一切命令，照他所吩咐的去做，","notes":[]},{"n":19,"t":"所以万军之耶和华－以色列的神如此说：利甲的儿子约拿达必永远不断有人侍立在我面前。”","notes":[]}]},"36":{"heading":"巴录在圣殿里宣读书卷","verses":[{"n":1,"t":"约西亚的儿子犹大王约雅敬第四年，有这话从耶和华临到耶利米，说：","notes":[]},{"n":2,"t":"“你要取一书卷，把我对你所说攻击以色列和犹大，并各国的一切话，从我对你说话的那日，就是从约西亚的日子起直到今日，都写在其上；","notes":[]},{"n":3,"t":"或者犹大家听见我想要降给他们的一切灾祸，各人就回转离开恶道，我就赦免他们的罪孽和罪恶。”","notes":[]},{"n":4,"t":"耶利米召了尼利亚的儿子巴录来；巴录就从耶利米口中，把耶和华对耶利米所说的一切话写在书卷上。","notes":[]},{"n":5,"t":"耶利米吩咐巴录说：“我被禁止，不能进耶和华的殿。","notes":[]},{"n":6,"t":"所以你要趁禁食的日子进入耶和华的殿中，把耶和华的话，就是你从我口中写在书卷上的话，念给百姓和所有从各城镇前来的犹大人亲耳听；","notes":[]},{"n":7,"t":"或者他们的恳求达到耶和华面前，各人回转离开恶道，因为耶和华向这百姓所说要发的怒气和愤怒实在很大。”","notes":[]},{"n":8,"t":"尼利亚的儿子巴录就照耶利米先知所吩咐的一切去做，在耶和华殿中宣读书卷上耶和华的话。","notes":[]},{"n":9,"t":"约西亚的儿子犹大王约雅敬第五年九月，耶路撒冷的众百姓和那从犹大城镇前来耶路撒冷的众百姓，在耶和华面前宣告禁食，","notes":[]},{"n":10,"t":"巴录就在耶和华殿的上院，靠近耶和华殿的新门口，沙番的儿子基玛利雅文士的房间里，宣读书卷上耶利米的话给众百姓亲耳听。","notes":[]},{"n":11,"t":"沙番的孙子基玛利雅的儿子米该亚听见书卷上耶和华的一切话，","notes":[],"heads":["向官长宣读书卷"]},{"n":12,"t":"就下到王宫，进入书记的房间。看哪，所有的官长都坐在那里，包括以利沙玛文士、示玛雅的儿子第莱雅、亚革波的儿子以利拿单、沙番的儿子基玛利雅、哈拿尼雅的儿子西底家和其余的官长。","notes":[]},{"n":13,"t":"米该亚向他们述说他所听见的一切话，就是当巴录向众百姓宣读那书卷时亲耳听见的。","notes":[]},{"n":14,"t":"官长们就派犹底，就是古示的曾孙、示利米雅的孙子、尼探雅的儿子到巴录那里，对他说：“你把你所念给百姓听的书卷拿在手里，到我们这里来。”尼利亚的儿子巴录就手拿书卷到他们那里去。","notes":[]},{"n":15,"t":"他们对他说：“请坐下，念给我们亲耳听。”巴录就念给他们亲耳听。","notes":[]},{"n":16,"t":"他们听见这一切话就害怕，面面相觑，对巴录说：“我们必须将这一切话禀告王。”","notes":[]},{"n":17,"t":"他们问巴录说：“请你告诉我们，你怎样从他口中写下这一切话呢？”","notes":[]},{"n":18,"t":"巴录回答说：“他向我口述这一切话，我就用笔墨把它写在书卷上。”","notes":[]},{"n":19,"t":"众官长对巴录说：“你和耶利米要去躲起来，不可叫人知道你们躲在哪里。”","notes":[]},{"n":20,"t":"众官长把书卷留在以利沙玛文士的房间里，然后进院见王，把这一切话说给王听。","notes":[],"heads":["约雅敬焚烧书卷"]},{"n":21,"t":"王就派犹底去拿这书卷来；他就从以利沙玛文士的房间内取来，念给王和侍立在王左右的众官长亲耳听。","notes":[]},{"n":22,"t":"那时正是九月，王坐在过冬的房屋里，王前面有燃烧的火盆。","notes":["“王前面有燃烧的火盆”：七十士译本是“王前面的火盆中有燃烧的火”。"]},{"n":23,"t":"犹底念了三、四段，王就用文士的刀把书卷割破，丢在火盆里，直到全卷在火中烧尽了。","notes":["“段”或译“栏”。"]},{"n":24,"t":"王和听见这一切话的臣仆都不惧怕，也不撕裂衣服。","notes":[]},{"n":25,"t":"以利拿单和第莱雅，并基玛利雅恳求王不要烧这书卷，王却不听。","notes":[]},{"n":26,"t":"王吩咐王的儿子耶拉篾、亚斯列的儿子西莱雅和亚伯叠的儿子示利米雅，去捉拿巴录文士和耶利米先知；耶和华却将他们隐藏起来。","notes":["“王”或译“哈米勒”。"]},{"n":27,"t":"王烧了有巴录从耶利米口中所写之话的书卷以后，耶和华的话临到耶利米，说：","notes":[],"heads":["耶利米另写一书卷"]},{"n":28,"t":"“你再取一书卷，将犹大王约雅敬所烧前一卷书上原有的一切话写在上面。","notes":[]},{"n":29,"t":"论到犹大王约雅敬你要说，耶和华如此说：你烧了这书卷，说：‘你为什么在上面写着，巴比伦王必要来毁灭这地，使这地绝了人民和牲畜呢？’","notes":[]},{"n":30,"t":"所以耶和华论到犹大王约雅敬说：他后裔中必没有人坐在大卫的宝座上；他的尸首必被抛弃，白天受炎热，黑夜受寒霜。","notes":[]},{"n":31,"t":"我必因他和他后裔，并他臣仆的罪孽惩罚他们。我要使我所说的一切灾祸临到他们和耶路撒冷的居民，并犹大人；只是他们不肯听从。”","notes":[]},{"n":32,"t":"于是，耶利米又取一书卷交给尼利亚的儿子巴录文士，他就从耶利米的口中写了犹大王约雅敬在火中所烧书卷上的一切话，另外又添了许多相仿的话。","notes":[]}]},"37":{"heading":"西底家求耶利米代祷","verses":[{"n":1,"t":"约西亚的儿子西底家接续约雅敬的儿子哥尼雅作王，因为巴比伦王尼布甲尼撒立他在犹大地作王。","notes":[]},{"n":2,"t":"但西底家、他的臣仆和这地的百姓都不听从耶和华藉耶利米先知所说的话。","notes":[]},{"n":3,"t":"西底家王派示利米雅的儿子犹甲和玛西雅的儿子西番雅祭司，去见耶利米先知，说：“求你为我们祈求耶和华－我们的神。”","notes":[]},{"n":4,"t":"那时耶利米仍在百姓中进出，因为他们还没有把他囚在监里。","notes":[]},{"n":5,"t":"法老的军队已经从埃及出来，那围困耶路撒冷的迦勒底人听见这风声，就拔营离开耶路撒冷去了。","notes":[]},{"n":6,"t":"耶和华的话临到耶利米先知，说：","notes":[]},{"n":7,"t":"“耶和华－以色列的神如此说：你们要对派你们来求问我的犹大王如此说：‘看哪，那出来帮助你们的法老军队必回埃及本国去。","notes":[]},{"n":8,"t":"迦勒底人必再来攻打这城，并要攻下，用火焚烧。","notes":[]},{"n":9,"t":"耶和华如此说：你们不要自欺说“迦勒底人必定离开我们”，因为他们必不离开。","notes":[]},{"n":10,"t":"你们即使击败与你们争战的迦勒底全军，他们当中剩下受伤的人也必各自从帐棚里起来，用火焚烧这城。’”","notes":[]},{"n":11,"t":"迦勒底的军队因躲避法老的军队，拔营离开耶路撒冷的时候，","notes":[],"heads":["耶利米被捕入狱"]},{"n":12,"t":"耶利米离开耶路撒冷，往便雅悯地去，要在那里从百姓当中取得自己的地产。","notes":[]},{"n":13,"t":"他到了便雅悯门，那里的守门官名叫伊利雅，是哈拿尼亚的孙子，示利米雅的儿子，他逮捕耶利米先知，说：“你是去投降迦勒底人的！”","notes":[]},{"n":14,"t":"耶利米说：“你这是谎话，我并不是去投降迦勒底人。”伊利雅不听耶利米的话，就逮捕他，把他带到官长那里。","notes":[]},{"n":15,"t":"官长们恼怒耶利米，打了他，把他囚在约拿单文士的房屋中，因为他们把这屋子当作监牢。","notes":[]},{"n":16,"t":"耶利米来到地牢，进入牢房，在那里拘留多日。","notes":[]},{"n":17,"t":"西底家王差人提他出来，在自己的宫内私下问他说：“有什么话从耶和华临到没有？”耶利米说：“有！”又说：“你必被交在巴比伦王手中。”","notes":[]},{"n":18,"t":"耶利米又对西底家王说：“我在什么事上得罪你，或你的臣仆，或这百姓，你们竟将我囚在监里呢？","notes":[]},{"n":19,"t":"对你们预言‘巴比伦王必不来攻击你们和这地’的先知在哪里呢？","notes":[]},{"n":20,"t":"主－我的王啊，现在求你垂听，允准我在你面前的恳求：不要把我送回约拿单文士的房屋中，免得我死在那里。”","notes":[]},{"n":21,"t":"于是西底家王下令，他们就把耶利米交在护卫兵的院中，每天从饼店街取一个饼给他，直到城中所有的饼都用尽了。这样，耶利米仍逗留在护卫兵的院中。","notes":[]}]},"38":{"heading":"耶利米在井里","verses":[{"n":1,"t":"玛坦的儿子示法提雅、巴施户珥的儿子基大利、示利米雅的儿子犹甲、玛基雅的儿子巴示户珥听见耶利米对众百姓所说的话，说：","notes":[]},{"n":2,"t":"“耶和华如此说：留在这城里的必遭刀剑、饥荒、瘟疫而死，但归向迦勒底人的必得存活；至少能保全自己的性命，得以存活。","notes":[]},{"n":3,"t":"耶和华如此说：这城必要交在巴比伦王军队的手中，他必攻下这城。”","notes":[]},{"n":4,"t":"于是官长们对王说：“求你把这人处死，因他向城里剩下的士兵和众人说这样的话，使他们的手发软。这人不是为这百姓求平安，而是叫他们受灾祸。”","notes":[]},{"n":5,"t":"西底家王说：“看哪，他在你们手中，王不能反对你们所做的事。”","notes":[]},{"n":6,"t":"他们就拿住耶利米，把他丢在王的儿子玛基雅的井里；那口井在护卫兵的院中。他们用绳子把耶利米缒下去，井里没有水，只有淤泥，耶利米就陷在淤泥中。","notes":["“王”或译“哈米勒”。"]},{"n":7,"t":"在王宫里的太监古实人以伯．米勒，听见他们把耶利米丢进井里，那时王坐在便雅悯门前。","notes":[]},{"n":8,"t":"以伯．米勒从王宫里出来，对王说：","notes":[]},{"n":9,"t":"“主－我的王啊，这些人向耶利米先知一味地行恶，把他丢在井里；他在那里必因饥饿而死，因为城里不再有粮食了。”","notes":[]},{"n":10,"t":"王就吩咐古实人以伯．米勒说：“你从这里带领三十人，趁耶利米先知还没死，把他从井里拉上来。”","notes":[]},{"n":11,"t":"于是以伯．米勒带领这些人同去，进入王宫，到库房以下，从那里取了些碎布和破衣服，用绳子缒下去，到井里耶利米那里。","notes":["“库房以下”：原文另译“库房的衣柜”。"]},{"n":12,"t":"古实人以伯．米勒对耶利米说：“你用这些碎布和破衣服放在绳子上，垫你的腋下。”耶利米就照样做。","notes":[]},{"n":13,"t":"这样，他们用绳子将耶利米从井里拉上来。耶利米仍在护卫兵的院中。","notes":[]},{"n":14,"t":"西底家王差人将耶利米先知带进耶和华殿的第三个门，到王那里去。王对耶利米说：“我要问你一件事，你一点都不可向我隐瞒。”","notes":[],"heads":["西底家问计于耶利米"]},{"n":15,"t":"耶利米对西底家说：“我若告诉你，你岂不是一定要把我处死吗？我若劝你，你必不听我。”","notes":[]},{"n":16,"t":"西底家王就私下对耶利米说：“我指着那造我们生命之永生的耶和华起誓：我必不把你处死，也不将你交在寻索你命的人手中。”","notes":[]},{"n":17,"t":"耶利米对西底家说：“耶和华－万军之神、以色列的神如此说：你若归顺巴比伦王的官长，你的命就必存活，这城也不致被火焚烧，你和你的全家都必存活。","notes":[]},{"n":18,"t":"你若不归顺巴比伦王的官长，这城必交在迦勒底人手中。他们必用火焚烧，你也不得脱离他们的手。”","notes":[]},{"n":19,"t":"西底家王对耶利米说：“我怕那些投降迦勒底人的犹大人，恐怕迦勒底人把我交在他们手中，他们就戏弄我。”","notes":[]},{"n":20,"t":"耶利米说：“迦勒底人必不把你交出。求你听从我对你所说耶和华的话，这样对你有好处，你的命也必存活。","notes":[]},{"n":21,"t":"你若不肯归顺，耶和华指示我的话是这样：","notes":[]},{"n":22,"t":"看哪，犹大王宫里所留下来的妇女必被带到巴比伦王的官长那里。这些妇女要说：你知己的朋友引诱你，他们胜过你；你的脚陷入淤泥，他们却离弃你。","notes":[]},{"n":23,"t":"“人必将你的后妃和你的儿女带到迦勒底人那里；你也不得脱离他们的手，必被巴比伦王的手捉住，这城也必被火焚烧。”","notes":["“这城...焚烧”是根据一些古卷和七十士译本；原文是“你将使这城焚烧”。"]},{"n":24,"t":"西底家对耶利米说：“不要让人知道这些对话，你就不至于死。","notes":[]},{"n":25,"t":"官长们若听见我跟你说话，到你那里对你说：‘告诉我们，你对王说了什么话，王又向你说了什么；不可向我们隐瞒，否则我们就要杀你。’","notes":[]},{"n":26,"t":"你就对他们说：‘我在王面前恳求不要把我送回约拿单的房屋，免得我死在那里。’”","notes":[]},{"n":27,"t":"随后官长们到耶利米那里，问他，他就照王所吩咐的一切话回答他们。他们就不再问他，因为事情没有泄漏。","notes":[]},{"n":28,"t":"于是耶利米仍在护卫兵的院中，直到耶路撒冷被攻下的日子。当耶路撒冷被攻下时，他仍在那里。","notes":["“当...那里。”七十士译本没有此句。"]}]},"39":{"heading":"耶路撒冷陷落","verses":[{"n":1,"t":"犹大王西底家第九年十月，巴比伦王尼布甲尼撒率领全军前来围困耶路撒冷。","notes":[]},{"n":2,"t":"西底家十一年四月初九日，城被攻破。","notes":[]},{"n":3,"t":"耶路撒冷被攻下的时候，巴比伦王的众官长，尼甲．沙利薛、三甲．尼波、撒西金将军、尼甲．沙利薛将军，并巴比伦王其余的官长都来坐在中门。","notes":["“将军”：原文是巴比伦的武将官职“拉伯．撒利”。","“将军”：原文是巴比伦的武将官职“拉墨”。"]},{"n":4,"t":"犹大王西底家和所有士兵看见他们，就在夜间从靠近王的花园、两城墙中间的门逃跑出城，往亚拉巴逃去。","notes":[]},{"n":5,"t":"迦勒底的军队追赶他们，在耶利哥的平原追上西底家，将他逮住，带到哈马地的利比拉、巴比伦王尼布甲尼撒那里；尼布甲尼撒就判他的罪。","notes":[]},{"n":6,"t":"在利比拉，巴比伦王在西底家眼前杀了他的儿女；巴比伦王又杀了犹大所有的贵族，","notes":[]},{"n":7,"t":"并且挖了西底家的眼睛，用铜链锁住他，要带到巴比伦去。","notes":[]},{"n":8,"t":"迦勒底人用火焚烧王宫和百姓的房屋，又拆毁耶路撒冷的城墙。","notes":[]},{"n":9,"t":"那时，尼布撒拉旦护卫长把城里所剩下的百姓和投降他的降民，以及其余的百姓都掳到巴比伦去了。","notes":[]},{"n":10,"t":"尼布撒拉旦护卫长却把百姓中一无所有的穷人留在犹大地，当时就赏给他们葡萄园和田地。","notes":["“赏给...田地”：原文另译“让他们当葡萄园的园丁和田地的工人”。"]},{"n":11,"t":"巴比伦王尼布甲尼撒为了耶利米，嘱咐尼布撒拉旦护卫长：","notes":[],"heads":["耶利米被释放"]},{"n":12,"t":"“你领他去，好好地看待他，切不可害他；他对你怎么说，你就向他怎样做。”","notes":[]},{"n":13,"t":"尼布撒拉旦护卫长和尼布沙斯班将军、尼甲．沙利薛将军，并巴比伦王众官长，","notes":["“将军”：原文是巴比伦的武将官职“拉伯．撒利”。","“将军”：原文是巴比伦的武将官职“拉墨”。"]},{"n":14,"t":"派人把耶利米从护卫兵的院中提出来，交给沙番的孙子，亚希甘的儿子基大利，让他自由进出屋子；于是耶利米住在百姓中间。","notes":[]},{"n":15,"t":"耶利米还囚在护卫兵院中的时候，耶和华的话临到他，说：","notes":[],"heads":["以伯．米勒的希望"]},{"n":16,"t":"“你去告诉古实人以伯．米勒说，万军之耶和华－以色列的神如此说：看哪，我说降祸不降福的话必临到这城，到那时必在你面前实现。","notes":[]},{"n":17,"t":"到那日我必拯救你，你必不致交在你所怕的人手中。这是耶和华说的。","notes":[]},{"n":18,"t":"我定要搭救你，你必不致倒在刀下，却要保全自己的性命，因你倚靠我。这是耶和华说的。”","notes":[]}]},"40":{"heading":"耶利米跟基大利同住","verses":[{"n":1,"t":"耶利米被链子锁在耶路撒冷和犹大被掳到巴比伦的人中，尼布撒拉旦护卫长把他从拉玛提出来，释放他以后，耶和华的话临到耶利米。","notes":[]},{"n":2,"t":"护卫长提耶利米来，对他说：“耶和华－你的神曾说要降这灾祸给此地。","notes":[]},{"n":3,"t":"耶和华照他所说的做了，已使这灾祸临到；因你们得罪耶和华，不听从他的话，所以这事临到你们。","notes":[]},{"n":4,"t":"看哪，现在我解开你手上的链子，你若看与我同往巴比伦去好，就可以去，我必厚待你；你若看与我同往巴比伦去不好，就不必去。看哪，全地在你面前，你以为哪里美好，哪里合宜，只管去吧","notes":[]},{"n":5,"t":"─耶利米尚未回去─你可以回到巴比伦王所立管理犹大城镇的沙番的孙子，亚希甘的儿子基大利那里去，在他那里住在百姓当中。不然，你看哪里合宜就可以去。”于是护卫长送他粮食和礼物，释放了他。","notes":["“耶利米...回去”：原文另译“耶利米尚未回答”；有古译本是“如果你留下来的话”。"]},{"n":6,"t":"耶利米就来到米斯巴，亚希甘的儿子基大利那里去，与他同住，住在留于境内的百姓当中。","notes":[]},{"n":7,"t":"在乡间所有的军官和属他们的人，听见巴比伦王立了亚希甘的儿子基大利作当地的省长，并将没有掳到巴比伦的男人、妇女、孩童和当地极穷的人全交给他，","notes":[],"heads":["基大利出任省长"]},{"n":8,"t":"于是尼探雅的儿子以实玛利，加利亚的两个儿子约哈难和约拿单，单户篾的儿子西莱雅，并尼陀法人以斐的众子，玛迦人的儿子耶撒尼亚，和属他们的人，都来到米斯巴的基大利那里。","notes":["“耶撒尼亚”：王下25．23称“雅撒尼亚”。"]},{"n":9,"t":"沙番的孙子，亚希甘的儿子基大利向他们和属他们的人起誓说：“不要怕服事迦勒底人，只管住在这地，服事巴比伦王，就可以得福。","notes":[]},{"n":10,"t":"至于我，我要住在米斯巴，侍候那些到我们这里来的迦勒底人；只是你们当积蓄酒、油和夏天的果子，收藏在器皿里，并住在你们所占的城镇中。”","notes":[]},{"n":11,"t":"在摩押地和亚扪人当中，在以东地和各国，所有的犹大人听见巴比伦王留下一些犹大人，并立沙番的孙子、亚希甘的儿子基大利管理他们，","notes":[]},{"n":12,"t":"所有的犹大人就从被赶到的各处回来，到犹大地米斯巴的基大利那里。他们积蓄了许多的酒，并夏天的果子。","notes":[]},{"n":13,"t":"加利亚的儿子约哈难和在乡间的军官来到米斯巴的基大利那里，","notes":[],"heads":["基大利被暗杀"]},{"n":14,"t":"对他说：“亚扪人的王巴利斯派尼探雅的儿子以实玛利来谋害你的命，你知道吗？”亚希甘的儿子基大利却不相信他们的话。","notes":[]},{"n":15,"t":"加利亚的儿子约哈难在米斯巴私下对基大利说：“求你容我去杀尼探雅的儿子以实玛利，必无人知道。何必让他害你的命，使聚集到你这里来的犹大人都分散，以致犹大剩余的人都灭亡呢？”","notes":[]},{"n":16,"t":"亚希甘的儿子基大利对加利亚的儿子约哈难说：“你不可做这事，你所论以实玛利的话是假的。”","notes":[]}]},"41":{"heading":"","verses":[{"n":1,"t":"七月中，王的大臣，就是王室后裔以利沙玛的孙子、尼探雅的儿子以实玛利带着十个人，来到米斯巴，亚希甘的儿子基大利那里；他们在米斯巴一同吃饭。","notes":[]},{"n":2,"t":"尼探雅的儿子以实玛利和同他来的那十个人起来，用刀击杀沙番的孙子，亚希甘的儿子基大利，就是巴比伦王所立为当地省长的，把他杀死。","notes":[]},{"n":3,"t":"以实玛利把所有在米斯巴与基大利一起的犹大人，以及他们在那里所遇见的迦勒底人和士兵都杀了。","notes":[]},{"n":4,"t":"他杀了基大利的第二天，还没有人知道的时候，","notes":[]},{"n":5,"t":"有八十人从示剑、示罗和撒玛利亚前来，胡须剃去，衣服撕裂，身体划破，手拿素祭和乳香，要奉到耶和华的殿。","notes":[]},{"n":6,"t":"尼探雅的儿子以实玛利从米斯巴出来迎接他们，随走随哭，遇见了他们，就对他们说：“你们可以到亚希甘的儿子基大利那里。”","notes":[]},{"n":7,"t":"他们到了城中，尼探雅的儿子以实玛利和与他一起的人就把他们杀了，丢在坑里。","notes":[]},{"n":8,"t":"只是他们中间有十个人对以实玛利说：“不要杀我们，因为我们有许多大麦、小麦、油和蜜藏在田间。”于是他住手，没有在弟兄中间杀他们。","notes":[]},{"n":9,"t":"以实玛利把那些因基大利事件所杀之人的尸首都丢在坑里；这坑是从前亚撒王因怕以色列王巴沙所挖的。尼探雅的儿子以实玛利把那些被杀的人填满了坑。","notes":[]},{"n":10,"t":"以实玛利把米斯巴剩下的人，就是众公主和仍住在米斯巴所有的百姓都掳去，他们原是尼布撒拉旦护卫长交给亚希甘的儿子基大利的。尼探雅的儿子以实玛利掳了他们，要到亚扪人那里去。","notes":[]},{"n":11,"t":"加利亚的儿子约哈难和与他一起的军官，听见尼探雅的儿子以实玛利所做的一切恶事，","notes":[]},{"n":12,"t":"就带领众人前往，要和尼探雅的儿子以实玛利争战，他们在基遍的大水池旁遇见他。","notes":["“大水池”：原文是“大水”。"]},{"n":13,"t":"在以实玛利那里的众人看见加利亚的儿子约哈难和与他一起的军官，就都欢喜。","notes":[]},{"n":14,"t":"这样，以实玛利从米斯巴所掳去的众人都转身归向加利亚的儿子约哈难。","notes":[]},{"n":15,"t":"尼探雅的儿子以实玛利和八个人脱离约哈难的手，逃到亚扪人那里去。","notes":[]},{"n":16,"t":"尼探雅的儿子以实玛利杀了亚希甘的儿子基大利，从米斯巴把所有幸存的百姓、士兵、妇女、孩童、太监掳到基遍之后，加利亚的儿子约哈难和与他一起的军官把他们都抢回来，","notes":[]},{"n":17,"t":"带到靠近伯利恒的基罗特金罕住下，要到埃及去，","notes":["“基罗特金罕”或译“金罕的寓所”。"]},{"n":18,"t":"躲避迦勒底人。他们惧怕迦勒底人，因为尼探雅的儿子以实玛利杀了巴比伦王所立管理那地的亚希甘的儿子基大利。","notes":[]}]},"42":{"heading":"百姓求耶利米代祷","verses":[{"n":1,"t":"众军官和加利亚的儿子约哈难，并何沙雅的儿子耶撒尼亚以及众百姓，从最小的到最大的都进前来，","notes":["“耶撒尼亚”：七十士译本是“亚撒利雅”；参43．2。"]},{"n":2,"t":"对耶利米先知说：“请你准我们在你面前祈求，为我们这幸存的人向耶和华－你的神祷告。我们本来众多，现在剩下的极少，这是你亲眼看见的。","notes":[]},{"n":3,"t":"愿耶和华－你的神指示我们当走的路，当做的事。”","notes":[]},{"n":4,"t":"耶利米先知对他们说：“我已经听见了，看哪，我必照你们的话向耶和华－你们的神祷告。耶和华无论回答什么，我都必告诉你们，绝不隐瞒。”","notes":[]},{"n":5,"t":"于是他们对耶利米说：“我们若不照耶和华－你神差遣你说的一切话去做，愿耶和华在我们中间作真实可靠的见证。","notes":[]},{"n":6,"t":"我们请你到耶和华－我们的神面前，他说的无论是好是歹，我们都必听从；因为我们听从耶和华－我们神的话，就可以得福。”","notes":[]},{"n":7,"t":"过了十天，耶和华的话临到耶利米。","notes":[],"heads":["耶和华回答耶利米"]},{"n":8,"t":"他就将加利亚的儿子约哈难和与他一起所有的军官和百姓，从最小的到最大的都召来，","notes":[]},{"n":9,"t":"对他们说：“你们请我到耶和华－以色列的神面前为你们祈求，他如此说：","notes":[]},{"n":10,"t":"‘你们若仍留在这地，我就建立你们，必不拆毁；栽植你们，必不拔出；因我为所降与你们的灾祸感到遗憾。","notes":[]},{"n":11,"t":"不要怕你们所惧怕的巴比伦王。不要怕他！因为我与你们同在，要拯救你们脱离他的手。这是耶和华说的。","notes":[]},{"n":12,"t":"我要向你们施怜悯，他就怜悯你们，使你们归回本地。’","notes":["“他”：七十士译本是“我”。"]},{"n":13,"t":"倘若你们说：‘我们不留在这地’，不听从耶和华－你们神的话，","notes":[]},{"n":14,"t":"说：‘我们不留在这地，却要进入埃及地，在那里我们看不见战争，听不见角声，也不致缺食挨饿；我们要住在那里。’","notes":[]},{"n":15,"t":"幸存的犹大人哪，你们现在要听耶和华的话；万军之耶和华－以色列的神如此说：‘你们若定意进入埃及，在那里寄居，","notes":[]},{"n":16,"t":"你们所惧怕的刀剑在埃及地必追上你们，你们所惧怕的饥荒在埃及要紧紧跟随你们，你们必死在那里。","notes":[]},{"n":17,"t":"凡定意进入埃及在那里寄居的，必遭刀剑、饥荒、瘟疫而死，无一人存留，得以逃脱我所降与他们的灾祸。’","notes":[]},{"n":18,"t":"“万军之耶和华－以色列的神如此说：‘我怎样将我的怒气和愤怒倾倒在耶路撒冷的居民身上，你们进入埃及的时候，我也必照样将我的愤怒倾倒在你们身上，以致你们受辱骂、惊骇、诅咒、羞辱，并且不得再看见这地方。’","notes":[]},{"n":19,"t":"幸存的犹大人哪，耶和华论到你们说：‘不要进入埃及。’你们要确实知道，我今日已警戒你们了。","notes":[]},{"n":20,"t":"你们行诡诈害自己；因为你们请我到耶和华－你们神那里，说：‘请你为我们向耶和华－我们的神祷告，你把耶和华－我们神所说的一切告诉我们，我们就必遵行。’","notes":[]},{"n":21,"t":"我今日把这话告诉你们，你们却不听耶和华－你们神为这一切事差我到你们那里所说的话。","notes":[]},{"n":22,"t":"现在你们要确实知道，你们在所要去的寄居之地必遭刀剑、饥荒、瘟疫而死。”","notes":[]}]},"43":{"heading":"耶利米被带到埃及","verses":[{"n":1,"t":"耶利米向众百姓说完了耶和华－他们神一切的话，就是耶和华－他们神差他去说的这一切话，","notes":[]},{"n":2,"t":"何沙雅的儿子亚撒利雅和加利亚的儿子约哈难，以及所有狂傲的人，就对耶利米说：“你说谎！耶和华－我们的神并没有差遣你说：‘你们不可进入埃及，在那里寄居。’","notes":[]},{"n":3,"t":"这是尼利亚的儿子巴录挑唆你害我们，要把我们交在迦勒底人手中，使我们被杀或被掳到巴比伦去。”","notes":[]},{"n":4,"t":"加利亚的儿子约哈难和所有的军官、百姓，都不肯听从耶和华的话留在犹大地。","notes":[]},{"n":5,"t":"加利亚的儿子约哈难和所有的军官却将幸存的犹大人，就是从被赶到的各国回来，在犹大地寄居的男人、妇女、孩童和众公主，并尼布撒拉旦护卫长留在沙番的孙子，亚希甘的儿子基大利那里的众人，与耶利米先知，以及尼利亚的儿子巴录，","notes":[],"end":6},{"n":7,"t":"都带入埃及地，到了答比匿；这是因他们不肯听从耶和华的话。","notes":[]},{"n":8,"t":"在答比匿，耶和华的话临到耶利米，说：","notes":[]},{"n":9,"t":"“你要在犹大人眼前用手拿几块大石头，藏在答比匿法老的宫门砌砖的石墩上，","notes":[]},{"n":10,"t":"对他们说：‘万军之耶和华－以色列的神如此说：看哪，我必召我的仆人巴比伦王尼布甲尼撒前来，安置他的宝座在所藏的这些石头上；他要在其上支搭华丽的帐幕。","notes":[]},{"n":11,"t":"他要来攻击埃及地：定为死亡的，必致死亡；定为掳掠的，必遭掳掠；定为刀杀的，必被刀杀。","notes":[]},{"n":12,"t":"我要用火点燃埃及众神明的庙宇，巴比伦王要焚烧庙宇，掳去神像；他要围住埃及地，好像牧人披上外衣，从那里安然而去。","notes":[]},{"n":13,"t":"他必打碎埃及地伯．示麦的柱像，用火焚烧埃及众神明的庙宇。’”","notes":[]}]},"44":{"heading":"给流亡埃及以色列人的信息","verses":[{"n":1,"t":"有话临到耶利米，论到住埃及地所有的犹大人，就是住在密夺、答比匿、挪弗、巴特罗境内的犹大人，说：","notes":[]},{"n":2,"t":"“万军之耶和华－以色列的神如此说：我所降与耶路撒冷和犹大各城的一切灾祸，你们都看见了。看哪，那些城镇今日荒凉，无人居住；","notes":[]},{"n":3,"t":"这是因居民所行的恶，去烧香事奉别神，就是他们和你们，以及你们列祖所不认识的神明，惹我发怒。","notes":[]},{"n":4,"t":"我一再差遣我的仆人众先知去，说：你们切不可行我所厌恶这可憎之事。","notes":[]},{"n":5,"t":"他们却不听从，不侧耳而听，也不转离恶事，仍向别神烧香。","notes":[]},{"n":6,"t":"因此，我的怒气和愤怒都倾倒出来，在犹大城镇和耶路撒冷街市上燃起，以致它们都荒废凄凉，正如今日一样。","notes":[]},{"n":7,"t":"现在耶和华－万军之神、以色列的神如此说：你们为何做这大恶自害己命，使你们的男人、妇女、孩童和吃奶的都从犹大剪除，不留一人呢？","notes":[]},{"n":8,"t":"你们以手所做的，在寄居的埃及地向别神烧香，惹我发怒，使你们被剪除，在天下万国中受诅咒羞辱。","notes":[]},{"n":9,"t":"你们祖先的恶行，犹大诸王和后妃的恶行，你们自己和你们妻子的恶行，就是在犹大地和耶路撒冷街市上所做的，你们都忘了吗？","notes":[]},{"n":10,"t":"到如今你们还不懊悔，不惧怕，不肯遵行我在你们和你们祖先面前所设立的法度律例。","notes":[]},{"n":11,"t":"“所以万军之耶和华－以色列的神如此说：看哪，我必向你们变脸降灾，剪除犹大众人。","notes":[]},{"n":12,"t":"我必使那定意进入埃及地、在那里寄居的，就是幸存的犹大人，尽都灭绝。他们必在埃及地仆倒，因刀剑饥荒灭绝，从最小的到最大的都必遭刀剑饥荒而死，甚至受辱骂、惊骇、诅咒、羞辱。","notes":[]},{"n":13,"t":"我怎样用刀剑、饥荒、瘟疫惩罚耶路撒冷，也必照样惩罚那些住在埃及地的犹大人。","notes":[]},{"n":14,"t":"那进入埃及地、在那里寄居的，就是幸存的犹大人，都不得逃脱，也不得归回犹大地。他们心中很想归回，居住在那里；但除了少数逃脱的以外，都不得归回。”","notes":[]},{"n":15,"t":"那些知道自己妻子向别神烧香的男人，与站在那里的一大群妇女，就是住埃及地巴特罗所有的百姓，回答耶利米说：","notes":[]},{"n":16,"t":"“论到你奉耶和华的名向我们所说的话，我们必不听从。","notes":[]},{"n":17,"t":"我们定要照我们口中所说的一切话去做，向天后烧香，献浇酒祭，按着我们与我们祖先、君王、官长在犹大城镇和耶路撒冷街市上素常所做的一样；因为那时我们得以吃饱、享福乐，并未遇见灾祸。","notes":[]},{"n":18,"t":"自从我们停止向天后烧香，献浇酒祭，我们倒缺乏这一切，又因刀剑饥荒灭绝。”","notes":[]},{"n":19,"t":"妇女们说：“我们向天后烧香，献浇酒祭，做天后像的饼供奉它，向它献浇酒祭，难道我们的丈夫没有参与吗？”","notes":["“妇女们说”是根据古译本；原文没有。"]},{"n":20,"t":"耶利米对这样回答他的男人和妇女说：","notes":[]},{"n":21,"t":"“你们与你们祖先、君王、官长，以及这地的百姓，在犹大城镇和耶路撒冷街市上所烧的香，耶和华岂不记得，放在他心上吗？","notes":[]},{"n":22,"t":"耶和华因你们所行的恶、所做可憎的事，不能再容忍，所以使你们的地荒凉，受惊骇诅咒，无人居住，正如今日一样。","notes":[]},{"n":23,"t":"你们烧香，得罪耶和华，不听耶和华的话，不遵行他的律法、条例、法度，所以你们遭遇这灾祸，正如今日一样。”","notes":[]},{"n":24,"t":"耶利米又对众百姓和妇女说：“所有在埃及地的犹大人哪，当听耶和华的话。","notes":[]},{"n":25,"t":"万军之耶和华－以色列的神如此说：你们和你们的妻子口中说过、手里做到，说：‘我们定要向天后还愿，向它烧香，献浇酒祭。’现在你们尽管坚定所许的愿，去还愿吧！","notes":[]},{"n":26,"t":"所有住埃及地的犹大人哪，当听耶和华的话。耶和华说：看哪，我指着我至大的名起誓，在埃及全地，我的名必不再被犹大任何人的口呼喊：‘我指着主－永生的耶和华起誓。’","notes":[]},{"n":27,"t":"看哪，我看守他们，为要降祸不降福；在埃及地的犹大人必因刀剑、饥荒而灭亡，直到灭绝。","notes":[]},{"n":28,"t":"从埃及地能脱离刀剑、归回犹大地的人数很少。那进入埃及地、在那里寄居的，就是幸存的犹大人，必知道是谁的话站得住，是我的话呢，还是他们的话。","notes":[]},{"n":29,"t":"我在这地方惩罚你们，必有预兆，使你们知道我降祸给你们的话必站得住。这是耶和华说的。","notes":[]},{"n":30,"t":"耶和华如此说：看哪，我必将埃及王合弗拉法老交在他仇敌和寻索其命的人手中，像我将犹大王西底家交在他仇敌和寻索其命的巴比伦王尼布甲尼撒手中一样。”","notes":[]}]},"45":{"heading":"耶和华给巴录的许诺","verses":[{"n":1,"t":"约西亚的儿子犹大王约雅敬第四年，尼利亚的儿子巴录把耶利米先知口中所说的话写在书上；耶利米对巴录说：","notes":[]},{"n":2,"t":"“巴录啊，耶和华－以色列的神说：","notes":[]},{"n":3,"t":"你曾说：‘哀哉！耶和华使我愁上加愁，我因呻吟而困乏，不得安歇。’","notes":[]},{"n":4,"t":"你要这样告诉他，耶和华如此说：看哪，我所建立的，我必拆毁；我所栽植的，我必拔出；在全地我都如此行。","notes":[]},{"n":5,"t":"你为自己图谋大事吗？不要图谋！看哪，我必使灾祸临到凡有血肉之躯的。但你无论往哪里去，我要保全你的性命。这是耶和华说的。”","notes":[]}]},"46":{"heading":"埃及在迦基米施受挫","verses":[{"n":1,"t":"耶和华论列国的话临到耶利米先知。","notes":[]},{"n":2,"t":"论到埃及，关于埃及王尼哥法老的军队，这军队安营在幼发拉底河边的迦基米施，是巴比伦王尼布甲尼撒在约西亚的儿子犹大王约雅敬第四年所打败的。","notes":[]},{"n":3,"t":"你们要预备大小盾牌，往前上阵，","notes":[]},{"n":4,"t":"套上车，骑上马！顶盔站立，磨枪披甲！","notes":[]},{"n":5,"t":"我为何看见他们惊惶，转身退后呢？他们的勇士打败仗，急忙逃跑，并不回头；四围都有惊吓！这是耶和华说的。","notes":[]},{"n":6,"t":"不要容快跑的逃避，也不要容勇士逃脱；在北方幼发拉底河边，他们绊跌仆倒。","notes":["“不要...逃脱”或译“快跑的不能逃避，勇士也不能逃脱”。"]},{"n":7,"t":"这是谁，像尼罗河涨溢，如江河的水翻腾呢？","notes":[]},{"n":8,"t":"埃及像尼罗河涨溢，如江河的水翻腾。它说：“我要涨溢遮盖全地；我要毁灭城镇和其中的居民。","notes":[]},{"n":9,"t":"马匹啊，上去吧！战车啊，要疾行！手拿盾牌的古实和弗的勇士，擅长拉弓的路德人，前进吧！”","notes":["“弗”是利比亚的一部分。"]},{"n":10,"t":"那日是万军之主耶和华报仇的日子，要向敌人报仇。刀剑必吞吃饱足，饮血满足；因为在北方幼发拉底河边，有祭物献给万军之主耶和华。","notes":[]},{"n":11,"t":"少女埃及啊，要上基列去取乳香；你虽服用许多药，还是徒然，不得治好。","notes":["“少女埃及”：原文直译“少女埃及女子”。"]},{"n":12,"t":"列国听见你的羞辱，遍地满了你的哀声；勇士与勇士彼此相撞，二人一起跌倒。","notes":[]},{"n":13,"t":"以下是耶和华对耶利米先知说的话，论到巴比伦王尼布甲尼撒要来攻击埃及地。","notes":[],"heads":["尼布甲尼撒来犯"]},{"n":14,"t":"你们要在埃及传扬，在密夺报告，在挪弗、答比匿宣告说：“要摆好阵势，预备作战，因为刀剑在你四围施行吞灭。”","notes":[]},{"n":15,"t":"你的壮士为何被扫除呢？他们站立不住，因为耶和华驱逐他们；","notes":["“你的...站立不住，”七十士译本是“阿庇斯（挪弗的牛神）为何逃走呢？你精选的牛为何站立不住呢？”"]},{"n":16,"t":"他使多人绊跌，彼此撞倒。他们说：“起来，让我们回到自己的同胞、回到自己的出生地去，好躲避欺压的刀剑。”","notes":[]},{"n":17,"t":"他们在那里称埃及王法老为“错失良机的夸大者”。","notes":["“他们...法老”：七十士译本是“你们要称埃及王法老尼哥的名字”。"]},{"n":18,"t":"名为万军之耶和华的君王说：我指着我的永生起誓：“尼布甲尼撒来的时候，必像众山之中的他泊，像海边的迦密。”","notes":["“尼布甲尼撒”：原文是“他”。"]},{"n":19,"t":"住在埃及的啊，要预备被掳时需用的物品；因为挪弗必成为废墟，被烧毁，无人居住。","notes":["“埃及”：原文直译“埃及女子”；本章24节同。"]},{"n":20,"t":"埃及是肥美的母牛犊；但来自北方的牛虻来到了！来到了！","notes":["“来到了！来到了！”有古卷和七十士译本是“临到它。”"]},{"n":21,"t":"它的佣兵好像圈里的肥牛犊，他们转身退后，一齐逃跑，站立不住；因为他们遭难的日子、受罚的时刻已经来临。","notes":[]},{"n":22,"t":"它的声音好像蛇在滑行。敌人要成队而来，如砍伐树木的人，手拿斧头攻击它。","notes":[]},{"n":23,"t":"虽然它的树林不易穿过，敌人却要砍伐，因敌人比蝗虫还多，不可胜数。这是耶和华说的。","notes":[]},{"n":24,"t":"埃及必然蒙羞，被交在北方人的手中。","notes":[]},{"n":25,"t":"万军之耶和华－以色列的神说：“看哪，我要惩罚挪的亚扪和法老、埃及和它的神明，以及君王，也要惩罚法老和倚靠他的人。","notes":["“挪”就是埃及的底比斯。","“亚扪”是埃及的主要神明。"]},{"n":26,"t":"我要将他们交给寻索其命之人的手和巴比伦王尼布甲尼撒与他臣仆的手。但埃及日后必再有人居住，与从前一样。这是耶和华说的。”","notes":[]},{"n":27,"t":"我的仆人雅各啊，不要惧怕！以色列啊，不要惊惶！因我要从远方拯救你，从被掳之地拯救你的后裔。雅各必回来，得享平静安逸，无人令他害怕。","notes":[],"heads":["耶和华要救他的子民"]},{"n":28,"t":"我的仆人雅各啊，不要惧怕！因我与你同在。我要将那些国灭绝净尽，就是我赶你去的那些国；却不将你灭绝净尽，倒要从宽惩治你，但绝不能不罚你。这是耶和华说的。","notes":[]}]},"47":{"heading":"有关非利士的话","verses":[{"n":1,"t":"在法老攻击迦萨之前，耶和华论非利士人的话临到耶利米先知。","notes":[]},{"n":2,"t":"耶和华如此说：看哪，有水从北方涨起，成为涨溢的河，要淹没全地和其中所充满的，淹没城和城里的居民。人必呼喊，境内的居民都必哀号。","notes":[]},{"n":3,"t":"一听见敌人壮马蹄踏的响声、战车隆隆、车轮轰轰，为父的手就发软，不能回头看顾儿女。","notes":[]},{"n":4,"t":"因为日子将到，耶和华必毁灭所有非利士人，剪除推罗、西顿仅存的帮助者；他要毁灭非利士人、迦斐托海岛剩余的人。","notes":[]},{"n":5,"t":"迦萨成了光秃，亚实基伦归于无有。平原中所剩的啊，你割划自己，要到几时呢？","notes":["“平原”：七十士译本是“亚衲族”。"]},{"n":6,"t":"耶和华的刀剑哪，你要到几时才止息呢？要入鞘，安静不动。","notes":[]},{"n":7,"t":"耶和华吩咐它攻击亚实基伦和海边之地，既已派定它，你怎能静止不动呢？","notes":["“你”：七十士译本是“它”。"]}]},"48":{"heading":"有关摩押的话","verses":[{"n":1,"t":"论摩押。万军之耶和华－以色列的神如此说：祸哉，尼波！它要变为废墟。基列亭蒙羞被攻取，米斯迦蒙羞被毁坏，","notes":["“米斯迦”或译“碉堡”。"]},{"n":2,"t":"摩押不再被称赞。有人在希实本设计谋害它：“来吧！我们将它剪除，使它不再成国。”玛得缅哪，你也必静默无声；刀剑必追赶你。","notes":[]},{"n":3,"t":"从何罗念有哀号声：“荒凉！大毁灭！”","notes":[]},{"n":4,"t":"“摩押毁灭了！”它的孩童哀号，使人听见。","notes":[]},{"n":5,"t":"人上鲁希坡随走随哭，因为在何罗念的下坡听见毁灭的哀声。","notes":[]},{"n":6,"t":"你们要奔逃，自救己命，使你们的性命如旷野里的矮树。","notes":["“矮树”：七十士译本是“野驴”。"]},{"n":7,"t":"你因倚靠自己所做的和自己的财宝，必被攻取。基抹和属它的祭司、官长也要一同被掳去。","notes":["“自己所做的”：七十士译本是“自己的堡垒”。","“基抹”为摩押的神明；下同。"]},{"n":8,"t":"那行毁灭的要来到各城，并无一城幸免。山谷必败落，平原必毁坏，正如耶和华所说的。","notes":[]},{"n":9,"t":"你们要将翅膀给摩押，使它可以飞去。它的城镇必荒凉，无人居住。","notes":["“你们要...飞去”：原文另译“你们要为摩押洒盐，因为它一定会灭亡”（参士9．45）七十士译本是“要给摩押竖立墓碑，它不久将被毁灭”。"]},{"n":10,"t":"懒惰不肯为耶和华做事的，必受诅咒；禁止刀剑不见血的，必受诅咒。","notes":[]},{"n":11,"t":"摩押自幼年以来常享安逸，如沉淀未被搅动的酒，没有从这器皿倒在那器皿，也未曾被掳掠过。因此，它的原味尚存，香气未变。","notes":["原文没有“酒”。"],"heads":["摩押的城镇被毁灭"]},{"n":12,"t":"看哪，日子将到，我必差倒酒的到它那里去，将它倒出来；他们要倒空器皿，打碎坛子。这是耶和华说的。","notes":[]},{"n":13,"t":"摩押必因基抹羞愧，像以色列家因倚靠伯特利羞愧一样。","notes":[]},{"n":14,"t":"你们怎么说：“我们是勇士，是会打仗的壮士”呢？","notes":[]},{"n":15,"t":"摩押变为废墟，敌人上去占它的城镇。它精良的壮丁都下去遭杀戮；这是名为万军之耶和华的君王说的。","notes":[]},{"n":16,"t":"摩押的灾殃临近，灾难速速来到。","notes":[]},{"n":17,"t":"凡在它四围的和认识它名的，都要为它悲伤，说：那结实的杖和美好的棍，竟然折断了！","notes":[]},{"n":18,"t":"底本的居民哪，要从你荣耀的座位上下来，坐着忍受干渴；因毁灭摩押的人上来攻击你，毁坏了你的堡垒。","notes":["“底本”：原文直译“底本女子”。"]},{"n":19,"t":"住亚罗珥的啊，要站在道路的边上观望，问逃跑的男人和逃脱的女人说：“发生了什么事呢”？","notes":[]},{"n":20,"t":"摩押因毁坏蒙羞；你们要哀号呼喊，要在亚嫩报告：“摩押已成废墟！”","notes":[]},{"n":21,"t":"审判临到平原之地的何伦、雅杂、米法押、","notes":[]},{"n":22,"t":"底本、尼波、伯．低比拉太音、","notes":[]},{"n":23,"t":"基列亭、伯．迦末、伯．米恩、","notes":[]},{"n":24,"t":"加略、波斯拉和摩押地远近所有的城镇。","notes":[]},{"n":25,"t":"摩押的角砍断了，膀臂折断了。这是耶和华说的。","notes":[]},{"n":26,"t":"你们要使摩押沉醉，因它向耶和华夸大。它要在自己所吐之物中打滚，又要被人嗤笑。","notes":[],"heads":["摩押受凌辱"]},{"n":27,"t":"以色列不是你的笑柄吗？它难道是在贼中被逮到，使你每逢提到它就摇头的吗？","notes":[]},{"n":28,"t":"摩押的居民哪，要离开城镇，住在山崖里，像鸽子在峡谷口上搭窝。","notes":[]},{"n":29,"t":"我们听闻摩押人的骄傲，极其骄傲；他们自高、自傲、自我狂妄、居心自大。","notes":[]},{"n":30,"t":"我知道他们的愤怒是虚空的，他们夸大的话一无所成。这是耶和华说的。","notes":[]},{"n":31,"t":"因此，我要为摩押哀号，为摩押全地呼喊；人必为吉珥．哈列设人叹息。","notes":[]},{"n":32,"t":"西比玛的葡萄树啊，我为你哀哭，甚于雅谢人的哀哭。你的枝子蔓延过海，直伸到雅谢海。那行毁灭的已经临到你夏天的果子和葡萄。","notes":[]},{"n":33,"t":"肥田和摩押地的欢喜快乐都被夺去，我使酒池不再流出酒来，无人踹酒欢呼；呼喊的声音不再是欢呼。","notes":[]},{"n":34,"t":"有哀声从希实本达到以利亚利，他们发的哀声达到雅杂；从琐珥达到何罗念，达到伊基拉．施利施亚，因为宁林的水必然干涸。","notes":[]},{"n":35,"t":"我必在摩押地使那在丘坛献祭的，和那向他的神明烧香的都灭绝了。这是耶和华说的。","notes":[]},{"n":36,"t":"因此，我的心为摩押哀鸣如箫，我的心为吉珥．哈列设人哀哭；摩押人所得的财物都毁灭了。","notes":[]},{"n":37,"t":"各人头上光秃，胡须剪短，手有划伤，腰束麻布。","notes":[]},{"n":38,"t":"在摩押的各房顶上和街市上到处有人哀哭，因我打碎摩押，好像打碎无人喜爱的器皿。这是耶和华说的。","notes":[]},{"n":39,"t":"打得粉碎了！他们要哀号了！摩押要羞愧转背了！这样，摩押必受四围的人嗤笑惊骇。","notes":[]},{"n":40,"t":"耶和华如此说：看哪，仇敌必如鹰展翅快飞，攻击摩押。","notes":[],"heads":["摩押无路可逃"]},{"n":41,"t":"加略被攻取，堡垒也被占据。到那日，摩押的勇士心中疼痛如临产的妇人。","notes":[]},{"n":42,"t":"摩押必被毁灭，不再成国，因它向耶和华夸大。","notes":[]},{"n":43,"t":"摩押的居民哪，惊吓、陷阱、罗网都临近你。这是耶和华说的。","notes":[]},{"n":44,"t":"躲过惊吓的必坠入陷阱，逃离陷阱的又被罗网缠住，因我必使惩罚之年临到摩押。这是耶和华说的。","notes":[]},{"n":45,"t":"逃难的人站在希实本的荫下，筋疲力尽，因为有火从希实本发出，有火焰出自西宏，烧尽摩押的鬓角和闹哄人的头顶。","notes":["“西宏”：有古卷是“西宏的家”。"]},{"n":46,"t":"摩押啊，你有祸了！属基抹的百姓灭亡了！因你的儿子都被掳去，你的女儿也被掳去。","notes":[]},{"n":47,"t":"到末后，我却要使摩押被掳的人归回。摩押受审判的话到此为止。这是耶和华说的。","notes":[]}]},"49":{"heading":"有关亚扪的话","verses":[{"n":1,"t":"论亚扪人。耶和华如此说：以色列没有儿子吗？没有后嗣吗？米勒公为何承受迦得为业呢？属它的百姓为何住其中的城镇呢？","notes":["“米勒公”是根据七十士译本和其他古译本，亚扪人神明的名字，又名“摩洛”；原文是“他们的王”，音译“玛勒堪”；下同。"]},{"n":2,"t":"看哪，日子将到，我必使人听见打仗的喊声，攻击亚扪人所住的拉巴的喊声。拉巴要成为废墟，属它的乡镇要被火焚烧。这是耶和华说的。先前承受以色列为业的，此时以色列倒要承受他们为业。这是耶和华说的。","notes":["“乡镇”：原文直译“女子们”；下同。"]},{"n":3,"t":"希实本哪，要哀号，因为爱地已成荒地。拉巴的乡镇哪，要呼喊，以麻布束腰；要哭号，在篱笆中往来奔跑；因米勒公和它的祭司、官长要一同被掳去。","notes":[]},{"n":4,"t":"背道的民哪，你为何因有山谷，因有水流的山谷夸耀呢？为何倚靠自己的财宝，说：“谁能来到我们这里呢？”","notes":["“民”：原文直译“女子”。"]},{"n":5,"t":"万军之主耶和华说：看哪，我要使惊吓从四围的邻邦临到你们；你们必被赶出，各人一直往前，无人收容难民。","notes":[]},{"n":6,"t":"但后来，我却要使被掳的亚扪人归回。这是耶和华说的。","notes":[]},{"n":7,"t":"论以东。万军之耶和华如此说：提幔不再有智慧了吗？聪明人的谋略都用尽了吗？他们的智慧尽归无有了吗？","notes":[],"heads":["有关以东的话"]},{"n":8,"t":"底但的居民哪，要转身逃跑，住在深密处；因为我惩罚以扫的时候，必使灾殃临到他。","notes":[]},{"n":9,"t":"摘葡萄的若来到你那里，岂不留下几串吗？贼若夜间来到，岂不是只毁坏他们要毁坏的吗？","notes":[]},{"n":10,"t":"我却使以扫赤裸，暴露他的藏身处；他不能隐藏自己。他的后裔、弟兄、邻舍全都灭绝，他也归于无有。","notes":[]},{"n":11,"t":"你撇下孤儿，我必保全他们的性命；你的寡妇可以倚靠我。","notes":[]},{"n":12,"t":"耶和华如此说：“看哪，既然原不该喝那杯的一定要喝，你能免去惩罚吗？必不能免，一定要喝！","notes":[]},{"n":13,"t":"我指着自己起誓，波斯拉必令人惊骇、受羞辱、被诅咒，并且全然荒废。它所有的城镇都要永远成为废墟。这是耶和华说的。”","notes":[]},{"n":14,"t":"我从耶和华那里听见消息，有使者被差往列国去，说：“你们要聚集前来攻击以东，要起来争战。”","notes":[]},{"n":15,"t":"看哪，我使你在列国中为最小，在世人中被藐视。","notes":[]},{"n":16,"t":"住在山穴中盘据山顶的啊，你被自己的声势与心中的狂傲所蒙蔽；你虽如大鹰高高搭窝，我却要从那里拉你下来。这是耶和华说的。","notes":[]},{"n":17,"t":"以东必令人惊骇；凡经过的人都惊骇，又因它一切的灾祸嗤笑。","notes":[]},{"n":18,"t":"耶和华说：它要像所多玛、蛾摩拉和邻近的城镇一样倾覆，必无人住在那里，也无人在其中寄居。","notes":[]},{"n":19,"t":"看哪，就像狮子从约旦河边的丛林上来，攻击坚固的居所，我要在转眼之间使以东人逃跑，离开这地。我拣选谁，就派谁治理这地。谁能像我呢？谁能召我出庭呢？有哪一个牧人能在我面前站得住呢？","notes":["“谁能召我出庭呢？”原文另译“谁能与我相比呢？”"]},{"n":20,"t":"你们要听耶和华攻击以东所定的计划和他攻击提幔居民所定的旨意。他们羊群当中微弱的定要被拖走，他们的草场定要变为荒凉。","notes":[]},{"n":21,"t":"因他们仆倒的声音，地就震动，哀号的声音传到红海那里。","notes":["“红海”是根据七十士译本；原文是“芦苇海”。"]},{"n":22,"t":"看哪，仇敌必如大鹰飞起，展开翅膀攻击波斯拉。到那日，以东的勇士心中疼痛如临产的妇人。","notes":[]},{"n":23,"t":"论大马士革。哈马和亚珥拔蒙羞，因为他们听见凶恶的消息就融化；焦虑像海浪汹涌，不得平静。","notes":[],"heads":["有关大马士革的话"]},{"n":24,"t":"大马士革发软，转身逃跑；战兢将它捉住，痛苦忧愁将它抓住，如临产的妇人一样。","notes":[]},{"n":25,"t":"我所喜乐受称赞的城，怎能被撇弃呢？","notes":["“怎能被撇弃”是根据一些古译本；原文是“怎能不被撇弃”。"]},{"n":26,"t":"它的壮丁必仆倒在街上，当那日，战士全都静默无声。这是万军之耶和华说的。","notes":[]},{"n":27,"t":"我必用火点燃大马士革的城墙，烧灭便．哈达的宫殿。","notes":[]},{"n":28,"t":"论巴比伦王尼布甲尼撒所攻打的基达和夏琐诸国。耶和华如此说：迦勒底人哪，起来上基达去，毁灭东方人。","notes":[],"heads":["有关基达和夏琐的话"]},{"n":29,"t":"人要夺去他们的帐棚和羊群，人要带走他们的幔子、一切器皿，和骆驼，占为己有。人向他们喊着说：四围都有惊吓。","notes":[]},{"n":30,"t":"夏琐的居民哪，要逃奔远方，住在深密处；因为巴比伦王尼布甲尼撒设计谋害你们，起意攻击你们。这是耶和华说的。","notes":[]},{"n":31,"t":"迦勒底人哪，起来！上到安逸无虑的国民那里去，他们是无门无闩、单独居住的。这是耶和华说的。","notes":[]},{"n":32,"t":"他们的骆驼必成为掠物，他们众多的牲畜必成为掳物。我要将剃鬓发的人分散四方，使灾殃从四围临到他们。这是耶和华说的。","notes":["“方”：原文是“风”；下同。"]},{"n":33,"t":"夏琐必成为野狗的住处，永远荒废；无人住在那里，也无人在其中寄居。","notes":[]},{"n":34,"t":"犹大王西底家登基的时候，耶和华论以拦的话临到耶利米先知，说：","notes":[],"heads":["有关以拦的话"]},{"n":35,"t":"“万军之耶和华如此说：看哪，我必折断以拦人的弓，那是他们战斗的主力。","notes":[]},{"n":36,"t":"我要使风从天的四方刮来，临到以拦，将他们分散四方。以拦被赶散的人没有一国不到的。","notes":[]},{"n":37,"t":"我必使以拦人在仇敌和寻索其命的人面前惊惶；我也必使灾祸，就是我的烈怒临到他们，又必使刀剑追杀他们，直到将他们灭尽。这是耶和华说的。","notes":[]},{"n":38,"t":"我要在以拦设立我的宝座，在那里除灭君王和官长。这是耶和华说的。","notes":[]},{"n":39,"t":"“到末后，我却要使被掳的以拦人归回。这是耶和华说的。”","notes":[]}]},"50":{"heading":"巴比伦被占领","verses":[{"n":1,"t":"以下是耶和华藉耶利米先知论巴比伦和迦勒底人之地所说的话。","notes":[]},{"n":2,"t":"你们要在万国中传扬，宣告，竖立大旗；要宣告，不可隐瞒，说：“巴比伦被攻取，彼勒蒙羞，米罗达惊惶。巴比伦的神像都蒙羞，它的偶像都惊惶。”","notes":["“彼勒”是巴比伦的主要神明。","“米罗达”是巴比伦的主要神明。"]},{"n":3,"t":"因有一国从北方上来攻击它，使它的地荒凉，无人居住，连人带牲畜都逃走了。","notes":[]},{"n":4,"t":"在那日、在那时，以色列人要和犹大人同来，随走随哭，寻求耶和华－他们的神。这是耶和华说的。","notes":[],"heads":["以色列人回乡"]},{"n":5,"t":"他们要问到锡安之路，又面向那里，说：“来吧，他们要在永不被遗忘的约中与耶和华联合。”","notes":["“他们要”：有古译本是“让我们”。"]},{"n":6,"t":"我的百姓成了失丧的羊，牧人使他们走迷了路，转入丛山之间。他们从大山走到小山，竟忘了自己安歇之处。","notes":[]},{"n":7,"t":"凡遇见他们的，就把他们吞灭。敌人说：“我们不算有罪；因他们得罪了那可作真正居所的耶和华，就是他们祖先所仰望的耶和华。”","notes":["“真正”或译“公义”。"]},{"n":8,"t":"“你们要逃离巴比伦，要离开迦勒底人之地，像走在羊群前面的公山羊。","notes":[]},{"n":9,"t":"看哪，因我必激起大国联盟，带领他们从北方来攻击巴比伦，他们要摆阵攻击它，它必在那里被攻取。他们的箭好像善射勇士的箭，绝不徒然返回。","notes":["“善射”是根据一些古卷；原文是“使人丧子”。"]},{"n":10,"t":"迦勒底要成为掠物，凡掳掠它的都必心满意足。这是耶和华说的。”","notes":[]},{"n":11,"t":"抢夺我产业的啊，你们因欢喜快乐，像踹谷嬉戏的母牛犊，又像发嘶声的壮马。","notes":["“踹谷”：七十士译本是“在草地上”。"],"heads":["巴比伦陷落"]},{"n":12,"t":"你们的母亲极其抱愧，生你们的必然蒙羞。看哪，她要列在诸国之末，成为旷野、旱地、沙漠；","notes":[]},{"n":13,"t":"因耶和华的愤怒，巴比伦必无人居住，全然荒凉，凡经过的都要受惊骇，又因它所遭的灾殃嗤笑。","notes":[]},{"n":14,"t":"所有拉弓的啊，要在巴比伦的四围摆阵，射箭攻击它，不用爱惜箭枝，因为它得罪了耶和华。","notes":[]},{"n":15,"t":"要在它四围呐喊：“它已经投降，堡垒坍塌了，城墙拆毁了！”这是耶和华所报的仇。你们要向它报仇；它怎样待人，你们也要怎样待它。","notes":[]},{"n":16,"t":"你们要将巴比伦撒种的和收割时拿镰刀的全都剪除。他们各人因躲避欺压的刀剑，必归回本族，逃到本土。","notes":[]},{"n":17,"t":"以色列是打散的羊，被狮子赶散。首先是亚述王将他吞灭，末后是巴比伦王尼布甲尼撒折断他的骨头。","notes":[],"heads":["以色列人回乡"]},{"n":18,"t":"所以万军之耶和华－以色列的神如此说：“看哪，我必惩罚巴比伦王和他的地，像我从前惩罚亚述王一样。","notes":[]},{"n":19,"t":"我必领以色列回他自己的草场，他要在迦密和巴珊吃草，又在以法莲山上和基列境内得以饱足。","notes":[]},{"n":20,"t":"在那日、在那时，你寻找以色列的罪孽，一无所有；寻找犹大的罪恶，也无所得；因为我所留下的人，我必赦免。这是耶和华说的。”","notes":[]},{"n":21,"t":"你要上去攻击米拉大翁之地，又攻击比割的居民。将他们追杀灭尽，照我所吩咐你的一切去做。这是耶和华说的。","notes":[],"heads":["神审判巴比伦"]},{"n":22,"t":"境内有打仗和大毁灭的响声。","notes":[]},{"n":23,"t":"全地的大锤竟然砍断破坏！巴比伦在列国中竟然荒凉！","notes":[]},{"n":24,"t":"巴比伦哪，我为你设下罗网，你被缠住，竟不自觉。你被寻着，也被捉住，因为你对抗耶和华。","notes":[]},{"n":25,"t":"耶和华已经打开军械库，拿出他恼恨的兵器；这是万军之主耶和华在迦勒底人之地要做的事。","notes":[]},{"n":26,"t":"你们要从极远的边界前来攻击它，要开它的仓廪，将它堆起如高堆，毁灭净尽，丝毫不留。","notes":["“你们要...它”：原文另译“它收割的时候到了”。"]},{"n":27,"t":"要杀它一切的牛犊，使它们下去遭杀戮。他们有祸了，因为他们的日子，就是他们受罚的时刻已经来到。","notes":[]},{"n":28,"t":"从巴比伦之地逃出来的难民，在锡安扬声宣告耶和华－我们的神要报仇，为他的圣殿报仇。","notes":[]},{"n":29,"t":"你们要招集一切弓箭手来攻击巴比伦，在巴比伦四围安营，不容一人逃脱。要照着它所做的报应它；它怎样待人，你们也要怎样待它，因为它向耶和华－以色列的圣者狂傲。","notes":[]},{"n":30,"t":"所以它的壮丁必仆倒在街上。当那日，它的士兵全都静默无声。这是耶和华说的。","notes":[]},{"n":31,"t":"“看哪，你这狂傲的啊，我与你为敌，因为你的日子，我惩罚你的时刻已经来到。这是万军之主耶和华说的。","notes":[]},{"n":32,"t":"狂傲的必绊跌仆倒，无人扶起。我必用火点燃他的城镇，将他四围所有的尽行烧灭。”","notes":[]},{"n":33,"t":"万军之耶和华如此说：“以色列人和犹大人一同受欺压；凡掳掠他们的都紧紧抓住他们，不肯释放。","notes":[]},{"n":34,"t":"他们的救赎主大有能力，万军之耶和华是他的名。他必定为他们伸冤，使全地得享平静；他却要搅扰巴比伦的居民。”","notes":[]},{"n":35,"t":"有刀剑临到迦勒底人和巴比伦的居民，临到它的领袖与智慧人。这是耶和华说的。","notes":[]},{"n":36,"t":"有刀剑临到矜夸的人，他们就变为愚昧；有刀剑临到它的勇士，他们就惊惶。","notes":[]},{"n":37,"t":"有刀剑临到它的马匹、战车，和其中混居的各族，他们变成与妇女一样；有刀剑临到它的宝物，宝物就被抢夺。","notes":[]},{"n":38,"t":"有干旱临到它的众水，它们就必干涸；因为这是雕刻偶像之地，人因偶像颠狂。","notes":["“干旱”：原文另译“刀剑”。","“人因偶像颠狂”：有古卷是“人以偶像为荣”。"]},{"n":39,"t":"所以野兽和土狼必住在那里，鸵鸟也住在其中，永远无人居住，世世代代无人定居。","notes":[]},{"n":40,"t":"巴比伦要像神所倾覆的所多玛、蛾摩拉和邻近的城镇一样，必无人住在那里，也无人在其中寄居。这是耶和华说的。","notes":[]},{"n":41,"t":"看哪，有一民族从北方而来，有一大国和许多君王被激起，从地极来到。","notes":[]},{"n":42,"t":"他们拿弓和枪，性情残忍，毫不留情；他们的声音像海浪澎湃。巴比伦啊，他们骑着马，如上战场的人摆列队伍，要攻击你。","notes":["“ 巴比伦”：原文直译“巴比伦女子”。"]},{"n":43,"t":"巴比伦王听见他们的风声，手就发软，痛苦将他抓住，仿佛临产的妇人疼痛一般。","notes":[]},{"n":44,"t":"“看哪，就像狮子从约旦河边的丛林上来，攻击坚固的居所，我要在转眼之间使迦勒底人逃跑，离开这地。我拣选谁，就派谁治理这地。谁能像我呢？谁能召我出庭呢？有哪一个牧人能在我面前站得住呢？","notes":[]},{"n":45,"t":"你们要听耶和华攻击巴比伦所定的计划和他攻击迦勒底人之地所定的旨意。他们羊群当中微弱的定要被拖走，他们的草场定要变为荒凉。","notes":[]},{"n":46,"t":"因巴比伦被攻下的声音，地就震动，人在列国都听见呼喊的声音。”","notes":[]}]},"51":{"heading":"再审判巴比伦","verses":[{"n":1,"t":"耶和华如此说：看哪，我必刮起毁灭的风，攻击巴比伦和住在立加米的人。","notes":[]},{"n":2,"t":"我要差陌生人来到巴比伦，他们要簸扬它，使它的地空无一物。在它遭祸的日子，他们要四围攻击它。","notes":["“陌生人”：有古卷和古译本是“簸扬的人”。"]},{"n":3,"t":"不要叫拉弓的拉弓，不要叫他佩戴盔甲；不要怜惜巴比伦的壮丁，要灭尽它的全军。","notes":["“不要叫拉弓...盔甲”是根据原文的另一读法；原文和七十士译本是“要叫拉弓的拉弓，要叫他佩戴盔甲”。"]},{"n":4,"t":"他们必在迦勒底人之地被杀仆倒，在巴比伦的街市上被刺透。","notes":[]},{"n":5,"t":"以色列和犹大境内虽然充满违背以色列圣者的罪，却没有被他的神－万军之耶和华所遗弃。","notes":[]},{"n":6,"t":"你们要奔逃，离开巴比伦，各救自己的性命！不要陷在它的罪孽中一同灭亡，因为这是耶和华报仇的时刻，他必向巴比伦施行报应。","notes":[]},{"n":7,"t":"巴比伦素来是耶和华手中的金杯，使全地沉醉，列国喝了它的酒就颠狂。","notes":[]},{"n":8,"t":"巴比伦忽然倾覆毁坏；要为它哀号，拿乳香来止它的疼痛，或者可以治好。","notes":[]},{"n":9,"t":"我们想医治巴比伦，它却未获痊愈。离开它吧！让我们各人归回本国，因为它受的审判通于上天，达到穹苍。","notes":[]},{"n":10,"t":"耶和华已经彰显出我们的义。来吧！我们要在锡安传扬耶和华－我们神的作为。","notes":[]},{"n":11,"t":"你们要磨尖箭头，抓住盾牌。论到巴比伦，耶和华定意要毁灭它，所以激起玛代君王的心；这是耶和华报仇，为他的圣殿报仇。","notes":[]},{"n":12,"t":"你们要竖立大旗，攻击巴比伦的城墙；要坚固瞭望台，派定守望的设下埋伏；因为耶和华指着巴比伦居民所说的，他不但这样定意，也已成就。","notes":[]},{"n":13,"t":"住在众水之上多有财宝的啊，你的结局已到！你贪婪之量已满盈！","notes":["“你贪婪之量已满盈”或译“你生命的线被剪断”。"]},{"n":14,"t":"万军之耶和华指着自己起誓说：我必使人遍满各处像蝗虫一样，他们必呐喊攻击你。","notes":[]},{"n":15,"t":"耶和华以能力创造大地，以智慧建立世界，以聪明铺张穹苍。","notes":[],"heads":["颂赞神的诗歌"]},{"n":16,"t":"他一出声，天上就有众水澎湃；他使云雾从地极上腾，造电随雨而闪，从仓库中吹出风来。","notes":[]},{"n":17,"t":"人人都如同畜牲，毫无知识；银匠都因偶像羞愧，他所铸的偶像本为虚假，它们里面并无气息。","notes":[]},{"n":18,"t":"它们都是虚无的，是迷惑人的东西，到它们受罚的时刻必被除灭。","notes":[]},{"n":19,"t":"雅各所得的福分不是这样，因主是那创造万有的，以色列是他产业的支派，万军之耶和华是他的名。","notes":["“主”：原文是“他”。","“以色列”是根据一些古卷；原文是“他”。"]},{"n":20,"t":"你是我争战的斧子和打仗的兵器。我要用你打碎列邦，毁灭列国；","notes":[],"heads":["耶和华的大锤"]},{"n":21,"t":"用你打碎马和骑马的，打碎战车和坐在其上的；","notes":[]},{"n":22,"t":"用你打碎男人和女人，打碎老人和少年，打碎壮丁和少女；","notes":[]},{"n":23,"t":"用你打碎牧人和他的羊群，打碎农夫和他的一对耕牛，打碎省长和官员。","notes":[]},{"n":24,"t":"我必在你们眼前报复巴比伦人和迦勒底居民在锡安所做的一切恶事。这是耶和华说的。","notes":[],"heads":["惩罚巴比伦"]},{"n":25,"t":"行毁灭的山，看哪，我与你为敌，你毁灭全地，我必伸手攻击你，将你从山岩滚下去，使你成为烧毁了的山。这是耶和华说的。","notes":[]},{"n":26,"t":"人必不从你那里取石头为房角石，也不取石头来作根基，因为你必永远荒废。这是耶和华说的。","notes":[]},{"n":27,"t":"你们要在境内竖立大旗，在列邦中吹角，使列邦预备攻击巴比伦。要招集亚拉腊、米尼、亚实基拿各国前来攻击它，派将军攻击它，使马匹上来如粗暴的蝗虫；","notes":[]},{"n":28,"t":"使列邦和玛代君王，省长和官员，他们所管的全地，都预备攻击它。","notes":[]},{"n":29,"t":"地必震动而移转；因耶和华向巴比伦旨意已确定，要使巴比伦土地荒凉，无人居住。","notes":[]},{"n":30,"t":"巴比伦的勇士停止争战，躲在堡垒之中。他们的力气耗尽，他们变成与妇女一样。巴比伦的住处焚烧，门闩都折断了。","notes":[]},{"n":31,"t":"通报的彼此相遇，送信的彼此相遇，报告巴比伦王，城的四方都被攻下了，","notes":[]},{"n":32,"t":"渡口被占据了，芦苇被火焚烧，战士都惊慌。","notes":[]},{"n":33,"t":"万军之耶和华－以色列的神如此说：巴比伦好像踹谷的禾场；再过片时，它收割的时候就到了。","notes":["“巴比伦”：原文直译“巴比伦女子”。"]},{"n":34,"t":"巴比伦王尼布甲尼撒吞灭我，压碎我，使我成为空器皿。他如大鱼将我吞下，以我的美物充满他的肚腹，又把我赶出去。","notes":[]},{"n":35,"t":"锡安的居民要说：愿我和我骨肉之亲所受的残暴归给巴比伦。耶路撒冷人要说：愿我们所流的血归给迦勒底的居民。","notes":[]},{"n":36,"t":"所以，耶和华如此说：看哪，我必为你伸冤，为你报仇；我必使巴比伦的海枯竭，使它的泉源干涸。","notes":[],"heads":["耶和华要帮助以色列"]},{"n":37,"t":"巴比伦必成为废墟，为野狗的住处，令人惊骇、嗤笑，并且无人居住。","notes":[]},{"n":38,"t":"他们要像少壮狮子一同咆哮，像小狮子吼叫。","notes":[]},{"n":39,"t":"他们食欲一来的时候，我必为他们摆设酒席，使他们沉醉，好叫他们快乐；他们睡了长觉，永不醒起。这是耶和华说的。","notes":[]},{"n":40,"t":"我必使他们像羔羊、像公绵羊和公山羊被牵去宰杀。","notes":[]},{"n":41,"t":"示沙克竟然被攻取！全地所称赞的被占据！巴比伦在列国中竟然变为荒凉！","notes":["“示沙克”就是巴比伦。"],"heads":["巴比伦的命运"]},{"n":42,"t":"海水涨起，漫过巴比伦；澎湃的海浪遮盖了它。","notes":[]},{"n":43,"t":"它的城镇变废墟，地变干旱，成为沙漠，成为无人居住、无人经过之地。","notes":[]},{"n":44,"t":"我要惩罚巴比伦的彼勒，使它吐出所吞之物。列国必不再流归到它那里，巴比伦的城墙也必坍塌。","notes":["“彼勒”是巴比伦的主要神明。"]},{"n":45,"t":"我的子民哪，你们要离开巴比伦！各人逃命，躲避耶和华的烈怒。","notes":[]},{"n":46,"t":"不要因境内所听见的风声心惊胆怯或惧怕；因为这年有风声传来，那年也有风声传来；境内有残暴的事，官长攻击官长。","notes":[]},{"n":47,"t":"所以，看哪，日子将到，我必惩罚巴比伦雕刻的偶像。它的全地必然抱愧，它被杀的人必仆倒在其上。","notes":[]},{"n":48,"t":"那时，天地和其中所有的，必因巴比伦欢呼，因为行毁灭的要从北方来到它那里。这是耶和华说的。","notes":[]},{"n":49,"t":"巴比伦要因以色列被杀的人而仆倒，正如全地被刺杀的人是因巴比伦仆倒一般。","notes":[]},{"n":50,"t":"你们躲避刀剑的要快走，不要站住！要在远方怀念耶和华，心中追想耶路撒冷。","notes":[],"heads":["给在巴比伦以色列人的信息"]},{"n":51,"t":"我们听见辱骂就蒙羞，满面惭愧，因为外邦人进入耶和华殿的圣所。","notes":[]},{"n":52,"t":"所以，看哪，日子将到，我必惩罚巴比伦雕刻的偶像，在全境内到处都有刺伤的人在呻吟。这是耶和华说的。","notes":[]},{"n":53,"t":"巴比伦虽升到天上，虽使它坚固的高处更坚固，我也要差毁灭者到它那里。这是耶和华说的。","notes":[]},{"n":54,"t":"有哀号的声音从巴比伦出来，有大毁灭从迦勒底人之地而来。","notes":[],"heads":["巴比伦灭亡"]},{"n":55,"t":"耶和华使巴比伦变为废墟，使其中喧哗的大声灭绝。仇敌仿佛众水，波浪澎湃，发出响声；","notes":[]},{"n":56,"t":"这是行毁灭的临到巴比伦。巴比伦的勇士被捉住，他们的弓折断了；因为耶和华是施行报应的神，他必施行报应。","notes":[]},{"n":57,"t":"我必使巴比伦的领袖、智慧人、省长、官员和勇士都喝醉，使他们永远沉睡，不再醒起。这是名为万军之耶和华的君王说的。","notes":[]},{"n":58,"t":"万军之耶和华如此说：巴比伦宽阔的城墙要夷为平地，它高大的城门必被火焚烧。万民所劳碌的必致虚空，万族所劳碌的被火焚烧，他们都必困乏。","notes":[]},{"n":59,"t":"犹大王西底家在位第四年，玛西雅的孙子，尼利亚的儿子西莱雅与王同去巴比伦，西莱雅是王宫的大臣，耶利米先知有话吩咐他。","notes":[],"heads":["耶利米的信息传到巴比伦"]},{"n":60,"t":"耶利米把一切要临到巴比伦的灾祸，就是论到巴比伦的这一切话，写在一书卷上。","notes":[]},{"n":61,"t":"耶利米对西莱雅说：“你到了巴比伦，务要宣读这一切话，","notes":[]},{"n":62,"t":"说：‘耶和华啊，你曾论到这地方说：要剪除它，不再有人与牲畜居住此地，必永远荒凉。’","notes":[]},{"n":63,"t":"你读完这书卷，就要把一块石头拴在其上，投入幼发拉底河中，","notes":[]},{"n":64,"t":"说：‘巴比伦因耶和华所要降与它的灾祸，必如此沉下去，不再浮起来，百姓也必困乏。’”耶利米的话到此为止。","notes":[]}]},"52":{"heading":"耶路撒冷的陷落","verses":[{"n":1,"t":"西底家登基的时候年二十一岁，在耶路撒冷作王十一年。他母亲名叫哈慕她，是立拿人耶利米的女儿。","notes":[]},{"n":2,"t":"西底家行耶和华眼中看为恶的事，像约雅敬所做的一切。","notes":[]},{"n":3,"t":"因此，耶和华向耶路撒冷和犹大发怒，以致把他们从自己面前赶出去。西底家背叛巴比伦王，","notes":[]},{"n":4,"t":"他作王第九年十月初十，巴比伦王尼布甲尼撒率领全军前来攻击耶路撒冷，对着城安营，四围筑堡垒攻城，","notes":[]},{"n":5,"t":"城被围困，直到西底家王十一年。","notes":[]},{"n":6,"t":"四月初九，城里的饥荒非常严重，当地的百姓都没有粮食。","notes":[]},{"n":7,"t":"城被攻破，士兵全都在夜间从靠近王园两城墙中间的门逃跑出城；迦勒底人正在四围攻城，他们就往亚拉巴逃去。","notes":[]},{"n":8,"t":"迦勒底的军队追赶西底家王，在耶利哥的平原追上他。他的全军都离开他溃散了。","notes":[]},{"n":9,"t":"迦勒底人就拿住王，带他到哈马地利比拉的巴比伦王那里；巴比伦王就判他的罪。","notes":[]},{"n":10,"t":"巴比伦王在西底家眼前杀了他的儿女，又在利比拉杀了犹大全体的官长，","notes":[]},{"n":11,"t":"并且挖了西底家的眼睛，用铜链锁着他，带到巴比伦去，将他囚在监里，直到他死的日子。","notes":[]},{"n":12,"t":"巴比伦王尼布甲尼撒十九年五月初十，在巴比伦王面前侍立的尼布撒拉旦护卫长进入耶路撒冷，","notes":[],"heads":["圣殿毁灭"]},{"n":13,"t":"他焚烧了耶和华的殿、王宫和耶路撒冷的房屋；用火焚烧所有大户人家的房屋。","notes":[]},{"n":14,"t":"跟随护卫长的迦勒底全军拆毁了耶路撒冷四围的城墙。","notes":[]},{"n":15,"t":"那时尼布撒拉旦护卫长将百姓中最穷的和城里所剩下的百姓，并那些投降巴比伦王的人，以及剩下的工匠，都掳去了。","notes":[]},{"n":16,"t":"但尼布撒拉旦护卫长留下一些当地最穷的人，叫他们修整葡萄园，耕种田地。","notes":[]},{"n":17,"t":"耶和华殿的铜柱并殿内的盆座和铜海，迦勒底人都打碎了，把那些铜运到巴比伦去；","notes":[]},{"n":18,"t":"他们又带走锅、铲子、钳子、盘子、勺子，和供奉用的一切铜器；","notes":[]},{"n":19,"t":"杯、火盆、碗、锅、灯台、勺子、酒杯，无论金的银的，护卫长都带走了；","notes":[]},{"n":20,"t":"还有所罗门为耶和华殿所造的两根铜柱、一面铜海，并座下的十二只铜牛，这些器皿的铜多得无法可秤。","notes":[]},{"n":21,"t":"至于柱子，这一根柱子高十八肘，厚四指，周围十二肘，中间是空的；","notes":[]},{"n":22,"t":"柱上有铜顶，每个铜顶高五肘；铜顶的周围有网子和石榴，也都是铜的。另一根柱子与此相同，也有石榴。","notes":[]},{"n":23,"t":"柱子四面有九十六个石榴，在网子周围，总共有一百个石榴。","notes":[]},{"n":24,"t":"护卫长拿住西莱雅大祭司、西番亚副祭司和门口的三个守卫，","notes":[],"heads":["犹大人被掳到巴比伦"]},{"n":25,"t":"又从城中拿住一个管理士兵的官，并在城里找到王面前的七个亲信，和召募当地百姓之将军的书记官，以及在城中找到的六十个当地百姓。","notes":["“官”或译“太监”。"]},{"n":26,"t":"尼布撒拉旦护卫长把这些人带到利比拉的巴比伦王那里。","notes":[]},{"n":27,"t":"巴比伦王击杀他们，在哈马地的利比拉把他们处死。这样，犹大人就被掳去离开本地。","notes":[]},{"n":28,"t":"这是尼布甲尼撒所掳百姓的数目：他在位第七年掳去犹大人三千零二十三人；","notes":[]},{"n":29,"t":"尼布甲尼撒十八年从耶路撒冷掳去八百三十二人；","notes":[]},{"n":30,"t":"尼布甲尼撒二十三年，尼布撒拉旦护卫长掳去犹大人七百四十五人；共有四千六百人。","notes":[]},{"n":31,"t":"巴比伦王以未．米罗达作王的元年，就是犹大王约雅斤被掳后三十七年十二月二十五日，他使犹大王约雅斤抬起头来，提他出监，","notes":[],"heads":["约雅斤被释放"]},{"n":32,"t":"对他说好话，使他的位高过与他一同被掳、在巴比伦众王的位；","notes":[]},{"n":33,"t":"又给他脱了囚服，使他终身常在巴比伦王面前吃饭。","notes":[]},{"n":34,"t":"巴比伦王赐给他日常需用的食物，日日一份，终身都是这样，直到他死的日子。","notes":[]}]}},"LAM":{"1":{"heading":"耶路撒冷的忧患","verses":[{"n":1,"t":"唉！先前人口稠密的城市，现在为何独坐！先前在列国中为大的，现在竟如寡妇！先前在各省中为王后的，现在竟成为服苦役的人！","notes":[]},{"n":2,"t":"她夜间痛哭，泪流满颊，在所有亲爱的人中，找不到一个安慰她的。她的朋友都以诡诈待她，成为她的仇敌。","notes":["“她”：本修订版的“国”和“城”的代名词都用“它”；本卷用“她”。"]},{"n":3,"t":"犹大被掳，遭遇苦难，多服劳役。她住在列国中，得不着安息；追逼她的在狭窄之地追上她。","notes":[]},{"n":4,"t":"锡安的道路因无人前来过节就哀伤，她的城门荒凉，祭司叹息，少女悲伤；她自己充满痛苦。","notes":[]},{"n":5,"t":"她的敌人作主，她的仇敌亨通；耶和华因她过犯多而使她受苦，她的孩童在敌人面前去作俘虏。","notes":[]},{"n":6,"t":"锡安的威荣全都失去。她的领袖如找不着草场的鹿，在追赶的人面前无力行走。","notes":["“锡安”：原文直译“锡安女子”。"]},{"n":7,"t":"耶路撒冷在困苦窘迫之时，就追想古时一切的荣华。她的百姓落在敌人手中，无人帮助；敌人看见，就因她的毁灭嗤笑。","notes":[]},{"n":8,"t":"耶路撒冷犯了大罪，因此成为不洁净；素来尊敬她的，见她裸露就都藐视她，她自己也叹息退后。","notes":[]},{"n":9,"t":"她的污秽是在下摆上；她未曾思想自己的结局，她的败落令人惊诧，无人安慰她。“耶和华啊，求你看顾我的苦难，因为仇敌强大。”","notes":[]},{"n":10,"t":"敌人伸手夺取她的一切贵重物品；她眼见列国侵入她的圣所，你曾吩咐他们不可进入你的集会。","notes":[]},{"n":11,"t":"她的百姓都叹息，寻求食物；他们用贵重物品换取粮食，要救性命。“耶和华啊，求你观看，留意我多么卑微。”","notes":[]},{"n":12,"t":"所有过路的人哪，愿这事不要发生在你们身上。你们要留意观看，有像这样临到我的痛苦没有？耶和华在他发烈怒的日子使我受苦。","notes":["“愿这事...身上”或译“这事你们不介意吗”；七十士译本和其他古译本没有本句。"],"heads":["耶路撒冷的哀号"]},{"n":13,"t":"他从高处降火进入我的骨头，克制了我；他张开网，绊我的脚，使我退后，又令我终日凄凉发昏。","notes":[]},{"n":14,"t":"他用手绑我罪过的轭，卷绕着加在我颈项上；他使我力量衰败。主将我交在我不能抵挡的人手中。","notes":[]},{"n":15,"t":"主弃绝我们当中所有的勇士，聚集会众攻击我，要压碎我的年轻人。主踹下少女犹大，在榨酒池中。","notes":["“少女犹大”：原文直译“少女犹大女子”。"]},{"n":16,"t":"我因这些事哭泣，眼泪汪汪；因为那安慰我、使我重新得力的，离我甚远。我的儿女孤苦，因为仇敌得胜了。","notes":[]},{"n":17,"t":"锡安伸出双手，却无人安慰。论到雅各，耶和华已经出令，使四围的人作他的仇敌；耶路撒冷在他们中间成为不洁净。","notes":[]},{"n":18,"t":"耶和华是公义的！我违背了他的命令。万民哪，请听，来看我的痛苦；我的少女和壮丁都被掳去。","notes":[]},{"n":19,"t":"我招呼我所亲爱的，他们却欺骗了我。我的祭司和长老寻找食物，要救性命的时候，就在城中断了气。","notes":[]},{"n":20,"t":"耶和华啊，求你观看，因为我在急难中；我的心肠烦乱，我心在我里面翻转，因我大大背逆。在外，刀剑使人丧亡；在家，犹如死亡。","notes":[]},{"n":21,"t":"有人听见我叹息，却无人安慰我！我所有的仇敌听见我的患难就喜乐，因这是你所做的。你使你所宣告的日子来临，愿他们像我一样。","notes":["“有人...叹息”：七十士译本是“听啊，我在叹息”。"]},{"n":22,"t":"愿他们的恶行都呈现在你面前；你怎样因我一切的罪过待我，求你也照样待他们；因我叹息甚多，心中发昏。","notes":[]}]},"2":{"heading":"耶路撒冷的痛苦","verses":[{"n":1,"t":"唉！主竟发怒，使黑云遮蔽锡安！他将以色列的华美从天扔在地上，在他发怒的日子并不顾念自己的脚凳。","notes":["“锡安”：原文直译“锡安女子”；4、8、10、18节同。"]},{"n":2,"t":"主吞灭雅各一切的住处，并不顾惜。他发怒倾覆犹大的堡垒，将它们夷为平地，凌辱这国与她的领袖。","notes":["“犹大”：原文直译“犹大女子”；下同。"]},{"n":3,"t":"他发烈怒，砍断以色列一切的角，在仇敌面前收回右手。他将雅各烧毁，如火焰四围吞灭。","notes":[]},{"n":4,"t":"他张弓好像仇敌，他站立举起右手，如同敌人杀戮我们眼目所喜爱的。他在锡安的帐棚倾倒愤怒，如火一般。","notes":[]},{"n":5,"t":"主如仇敌吞灭以色列，吞灭它一切的宫殿，毁坏境内的堡垒；在犹大加添悲伤和哭号。","notes":[]},{"n":6,"t":"他摧毁自己的帐幕如摧毁园子，毁坏自己的会幕。耶和华使节庆和安息日在锡安尽被遗忘，又在极其愤怒中厌弃君王与祭司。","notes":[]},{"n":7,"t":"耶和华撇弃自己的祭坛，憎恶自己的圣所，把宫殿的墙交给仇敌。他们在耶和华的殿中喧嚷，如在节庆之日一样。","notes":[]},{"n":8,"t":"耶和华定意拆毁锡安的城墙；他拉了准绳，不将手收回，定要毁灭。他使城郭和城墙都悲哀，一同衰败。","notes":[]},{"n":9,"t":"锡安的门陷入地里，主毁坏，折断她的门闩。她的君王和官长都置身列国中，没有律法；她的先知也不再从耶和华领受异象。","notes":[]},{"n":10,"t":"锡安的长老坐在地上，默默无声；他们扬起尘土落在头上，腰束麻布；耶路撒冷的少女垂头至地。","notes":[]},{"n":11,"t":"我的眼睛流泪，以致失明；我的心肠烦乱，肝胆落地，都因我的百姓遭毁灭，又因孩童和吃奶的在城内的广场上昏厥。","notes":["“我的百姓”：原文直译“我百姓的女儿”。"]},{"n":12,"t":"他们如受伤的人在城内广场上昏厥，在母亲的怀里将要丧命时，就对母亲说：“饼和酒在哪里呢？”","notes":[]},{"n":13,"t":"耶路撒冷啊，我可用什么向你证明呢？我可用什么与你相比呢？少女锡安哪，我拿什么和你比较，好安慰你呢？因你的裂伤大如海；谁能医治你呢？","notes":["“耶路撒冷”：原文直译“耶路撒冷女子”；下同。","“证明”：原文另译“比较”。","“少女锡安”：原文直译“少女锡安女子”。"]},{"n":14,"t":"你的先知为你看见虚假和粉饰的异象，并未揭露你的罪孽，使你被掳的归回；却传给你虚假与误导人的默示。","notes":[]},{"n":15,"t":"凡过路的都向你拍掌。他们向耶路撒冷嗤笑，摇头：“这就是人称为全美的、称为全地所喜悦的城吗？”","notes":[]},{"n":16,"t":"你所有的仇敌张口来攻击你；他们嗤笑，切齿，说：“我们把她吞灭了，这是我们所盼望的日子！我们终于等到了，亲眼看见了！”","notes":[]},{"n":17,"t":"耶和华成就了他所定的，应验了他古时所命定的。他倾覆，并不顾惜，他使仇敌向你夸耀，使你敌人的角高举。","notes":[]},{"n":18,"t":"他们的心哀求主。锡安的城墙啊，愿你日夜泪流如河，不让自己休息，你眼中的瞳人也不歇息。","notes":[]},{"n":19,"t":"夜间每逢时辰开始，要起来呼喊，在主面前倾心吐意如水。你的孩童在街头上挨饿昏厥，你要为他们的性命向主举手。","notes":[]},{"n":20,"t":"耶和华啊，求你观看，留意你向谁这样行。妇人岂可吃自己所生、所抚育的婴孩吗？祭司和先知岂可在主的圣所中被杀吗？","notes":[]},{"n":21,"t":"年轻人和老年人躺卧在街上，我的少女和壮丁都倒在刀下。你在发怒的日子杀了他们，你杀戮，并不顾惜。","notes":[]},{"n":22,"t":"你从四围招聚使我惊吓的人，像在节庆的日子一样。耶和华发怒的日子，无人逃脱，无人生还。我所抚育养大的，仇敌都杀尽了。","notes":[]}]},"3":{"heading":"惩罚、悔改、盼望","verses":[{"n":1,"t":"因耶和华愤怒的杖，我是遭遇困苦的人。","notes":[]},{"n":2,"t":"他驱赶我走入黑暗，没有光明。","notes":[]},{"n":3,"t":"他反手攻击我，终日不停。","notes":[]},{"n":4,"t":"他使我皮肉枯干，折断我的骨头。","notes":[]},{"n":5,"t":"他筑垒攻击我，以苦楚和艰难围困我；","notes":[]},{"n":6,"t":"使我住在幽暗之处，像死了许久的人一样。","notes":[]},{"n":7,"t":"他围住我，使我无法脱身；他使我的铜链沉重。","notes":[]},{"n":8,"t":"尽管我哀号求救，他仍拦阻我的祷告。","notes":[]},{"n":9,"t":"他用凿过的石头挡住我的道路，使我的路径弯曲。","notes":[]},{"n":10,"t":"他向我如埋伏的熊，如在隐密处的狮子。","notes":[]},{"n":11,"t":"他使我转离正路，把我撕碎，使我凄凉。","notes":["“把我撕碎”：有一古译本是“使我跛脚”。"]},{"n":12,"t":"他拉弓，命我站立，当作箭靶；","notes":[]},{"n":13,"t":"把箭袋中的箭射入我的肺腑。","notes":[]},{"n":14,"t":"我成了全体百姓的笑柄，成了他们终日的歌曲。","notes":[]},{"n":15,"t":"他使我受尽苦楚，饱食茵陈；","notes":[]},{"n":16,"t":"用沙石磨断我的牙，以灰尘覆盖我。","notes":[]},{"n":17,"t":"你使我远离平安，我忘了何为福乐。","notes":[]},{"n":18,"t":"于是我说：“我的力量衰败，在耶和华那里我毫无指望！”","notes":[]},{"n":19,"t":"求你记得我的困苦和流离，它如茵陈和苦胆一般；","notes":[]},{"n":20,"t":"我心想念这些，就在我里面忧闷。","notes":["“忧闷”：原文另译“沉思”。"]},{"n":21,"t":"但我的心回转过来，因此就有指望；","notes":[]},{"n":22,"t":"因耶和华的慈爱，我们不致灭绝，因他的怜悯永不断绝，","notes":["“我们不致灭绝”：有古卷是“从不止息”。"]},{"n":23,"t":"每早晨，这都是新的；你的信实极其广大！","notes":[]},{"n":24,"t":"我心里说：“耶和华是我的福分，因此，我要仰望他。”","notes":[]},{"n":25,"t":"凡等候耶和华，心里寻求他的，耶和华必施恩给他。","notes":[]},{"n":26,"t":"人仰望耶和华，安静等候他的救恩，这是好的。","notes":[]},{"n":27,"t":"人在年轻时负轭，这是好的。","notes":[]},{"n":28,"t":"他当安静独坐，因为这是耶和华加在他身上的。","notes":[]},{"n":29,"t":"让他脸伏于地吧！或者还会有指望。","notes":["“脸伏于地”：原文是“口贴尘土”。"]},{"n":30,"t":"让人打他耳光，使他饱受凌辱吧！","notes":[]},{"n":31,"t":"主必不永远撇弃，","notes":[]},{"n":32,"t":"他虽使人忧愁，还要照他丰盛的慈爱施怜悯；","notes":[]},{"n":33,"t":"他并不存心要人受苦，令世人忧愁。","notes":[]},{"n":34,"t":"把世上所有的囚犯踹在脚下，","notes":[]},{"n":35,"t":"在至高者面前扭曲人的公正，","notes":[]},{"n":36,"t":"在人的诉讼上颠倒是非，这都是主看不中的。","notes":[]},{"n":37,"t":"若非主发命令，谁能说了就成呢？","notes":[]},{"n":38,"t":"是祸，是福，不都出于至高者的口吗？","notes":[]},{"n":39,"t":"人都有自己的罪，活人有什么好发怨言的呢？","notes":[]},{"n":40,"t":"让我们省察，检讨自己的行为，归向耶和华吧！","notes":[]},{"n":41,"t":"让我们献上我们的心，向天上的神举手！","notes":[]},{"n":42,"t":"我们犯罪悖逆，你并未赦免。","notes":[]},{"n":43,"t":"你浑身是怒气，追赶我们；你施行杀戮，并不顾惜。","notes":[]},{"n":44,"t":"你以密云围着自己，祷告不能穿透。","notes":[]},{"n":45,"t":"你使我们在万民中成为污物和垃圾。","notes":[]},{"n":46,"t":"我们所有的仇敌张口来攻击我们；","notes":[]},{"n":47,"t":"惊吓和陷阱临到我们，残害和毁灭也临到我们。","notes":[]},{"n":48,"t":"因我百姓遭毁灭，我的眼睛泪流成河。","notes":["“我百姓”：原文直译“我百姓的女儿”。"]},{"n":49,"t":"我的眼睛流泪不停，流泪不止，","notes":[]},{"n":50,"t":"直等到耶和华垂顾，从天上观看。","notes":[]},{"n":51,"t":"为我城中的百姓，我眼所见的使我心痛。","notes":["“百姓”：原文直译“女子们”。"]},{"n":52,"t":"无故与我为敌的追逼我，像追捕雀鸟一样。","notes":[]},{"n":53,"t":"他们要在坑中了结我的性命，丢石头在我身上。","notes":[]},{"n":54,"t":"众水淹没我的头，我说：“我没命了！”","notes":[]},{"n":55,"t":"耶和华啊，在极深的地府里，我求告你的名。","notes":[]},{"n":56,"t":"我的声音你听见了，求你不要掩耳不听我的呼声，我的求救。","notes":[]},{"n":57,"t":"我求告你的时候，你临近我，说：“不要惧怕！”","notes":[]},{"n":58,"t":"主啊，你为我伸冤，你救赎了我的命。","notes":[]},{"n":59,"t":"耶和华啊，你已看见我的委屈，求你为我主持正义。","notes":[]},{"n":60,"t":"他们要报复，谋害我，你都看见了。","notes":[]},{"n":61,"t":"耶和华啊，你听见他们的辱骂，他们害我的一切计谋，","notes":[]},{"n":62,"t":"那些起来攻击我的人嘴唇所说的话和他们终日攻击我的计谋。","notes":[]},{"n":63,"t":"求你留意！他们无论坐下或起来，我都是他们的笑柄。","notes":[]},{"n":64,"t":"耶和华啊，求你照他们手所做的向他们施行报应。","notes":[]},{"n":65,"t":"求你使他们心里刚硬，使你的诅咒临到他们。","notes":[]},{"n":66,"t":"求你发怒追赶他们，从耶和华的地上除灭他们。","notes":["“地上”：原文是“诸天底下”。"]}]},"4":{"heading":"耶路撒冷陷落","verses":[{"n":1,"t":"唉！黄金竟然无光！纯金竟然变色！圣所的石头散落在街上。","notes":[]},{"n":2,"t":"锡安宝贝的孩子虽然好比精金，现在竟当作陶匠手所做的瓦瓶！","notes":[]},{"n":3,"t":"野狗尚且哺乳其子，我百姓的妇人反倒残忍，如旷野的鸵鸟一般；","notes":["“我百姓”：原文直译“我百姓的女儿”；下同。"]},{"n":4,"t":"吃奶孩子的舌头因干渴贴住上膛，孩童求饼，却无人擘给他们。","notes":[]},{"n":5,"t":"素来吃美好食物的，如今遭遗弃在街上；素来穿着朱红衣裳长大的，如今却拥抱粪堆。","notes":[]},{"n":6,"t":"我百姓的罪孽比所多玛的罪还大；所多玛虽无人伸手攻击，转眼之间就被倾覆。","notes":[]},{"n":7,"t":"锡安的拿细耳人比雪纯净，比奶更白；他们的身体比宝石更红，身躯之美如蓝宝石一般。","notes":["“拿细耳人”：参民6．2。"]},{"n":8,"t":"但如今他们的面貌比煤炭更黑，在街上无人认识；他们的皮肤紧贴骨头，枯干形同槁木。","notes":[]},{"n":9,"t":"被刀剑刺杀的胜过因饥饿而死的；饥饿者由于缺乏田里的出产就消瘦而亡。","notes":["“死”：原文是“被刺杀”。","“亡”：原文是“刺穿”。"]},{"n":10,"t":"当我百姓遭毁灭的时候，慈心的妇人亲手烹煮自己的儿女为食物。","notes":[]},{"n":11,"t":"耶和华发尽他的愤怒，倾倒他的烈怒，用火焚烧锡安，烧毁锡安的根基。","notes":[]},{"n":12,"t":"地上的君王和世上的居民都不信敌人和仇敌竟能进入耶路撒冷的城门。","notes":[]},{"n":13,"t":"这都因她先知的罪恶和祭司的罪孽，他们在城中流了义人的血。","notes":[]},{"n":14,"t":"他们如盲人在街上徘徊，又被血玷污，以致人不敢摸他们的衣服。","notes":[]},{"n":15,"t":"人向他们喊着：“你这不洁净的，走开！走开！走开！不要摸我！”他们逃走流浪的时候，列国中有人说：“他们不可再寄居此地。”","notes":[]},{"n":16,"t":"耶和华亲自赶散他们，不再眷顾他们；不看重祭司，也不厚待长老。","notes":[]},{"n":17,"t":"我们的眼目徒然仰望帮助，以致失明，我们从瞭望台所守望的，竟是一个不能救人的国！","notes":[]},{"n":18,"t":"仇敌追逐我们的脚踪，使我们不敢在自己的街上行走。我们的结局临近，日子已满，我们的结局已经来到。","notes":[]},{"n":19,"t":"追赶我们的比空中的鹰更快；他们在山上追逼我们，在旷野埋伏，等候我们。","notes":[]},{"n":20,"t":"耶和华的受膏者是我们鼻中的气，被抓到他们的坑里，论到他，我们曾说：“我们必在他荫下，在列国中存活。”","notes":[]},{"n":21,"t":"住乌斯地的以东啊，尽管欢喜快乐，苦杯必传到你那里；你要喝醉，裸露自己。","notes":["“以东”：原文直译“以东女子”；下同。"]},{"n":22,"t":"锡安哪，你罪孽的惩罚已经结束，耶和华必不再使你被掳去。以东啊，耶和华必惩罚你的罪孽，揭露你的罪恶。","notes":["“锡安”：原文直译“锡安女子”。"]}]},"5":{"heading":"求耶和华垂怜","verses":[{"n":1,"t":"耶和华啊，求你顾念我们所遭遇的，留意看我们所受的凌辱。","notes":[]},{"n":2,"t":"我们的产业归陌生人，我们的房屋归外邦人。","notes":[]},{"n":3,"t":"我们是无父的孤儿，我们的母亲如同寡妇。","notes":[]},{"n":4,"t":"我们出银钱才得水喝，我们的柴也是用钱买来的。","notes":[]},{"n":5,"t":"我们被追赶，迫及颈项，疲乏却不得歇息。","notes":[]},{"n":6,"t":"我们束手投降埃及和亚述，为要得粮吃饱。","notes":[]},{"n":7,"t":"我们的祖先犯罪，而今他们不在了，我们却担当他们的罪孽。","notes":[]},{"n":8,"t":"奴仆辖制我们，无人救我们脱离他们的手。","notes":[]},{"n":9,"t":"因旷野有刀剑，我们冒生命的危险才能得粮食。","notes":[]},{"n":10,"t":"因饥荒的干热，我们的皮肤热如火炉。","notes":[]},{"n":11,"t":"他们在锡安玷污妇人，在犹大城镇污辱少女。","notes":[]},{"n":12,"t":"他们吊起领袖的手，使长老脸上无光。","notes":[]},{"n":13,"t":"年轻人扛磨石，孩童背木柴而跌倒。","notes":[]},{"n":14,"t":"城门口不再有老年人，年轻人也不再奏乐。","notes":[]},{"n":15,"t":"我们心中的快乐止息，跳舞转为悲哀。","notes":[]},{"n":16,"t":"冠冕从我们的头上掉落；我们有祸了，因为犯了罪。","notes":[]},{"n":17,"t":"因这些事我们心里发昏，眼睛昏花。","notes":[]},{"n":18,"t":"锡安山荒凉，狐狸行在其上。","notes":[]},{"n":19,"t":"耶和华啊，你治理直到永远，你的宝座万代长存。","notes":[]},{"n":20,"t":"你为何全然忘记我们？为何长久离弃我们？","notes":[]},{"n":21,"t":"耶和华啊，求你使我们回转归向你，我们就得以回转。求你更新我们的年日，像古时一样，","notes":[]},{"n":22,"t":"难道你全然弃绝了我们，向我们大发烈怒？","notes":[]}]}},"EZK":{"1":{"heading":"以西结的第一个异象","verses":[{"n":1,"t":"在三十年四月初五，我在迦巴鲁河边被掳的人当中，那时天开了，我看见神的异象。","notes":[],"heads":["神的宝座"]},{"n":2,"t":"正是约雅斤王被掳的第五年四月初五，","notes":[]},{"n":3,"t":"在迦勒底人之地的迦巴鲁河边，耶和华的话特地临到布西的儿子以西结祭司，耶和华的手按在他身上。","notes":[]},{"n":4,"t":"我观看，看哪，狂风从北方刮来，有一朵大云闪烁着火，周围有光辉，其中的火好像闪耀的金属；","notes":[]},{"n":5,"t":"又从其中显出四个活物的形像。他们的形状是这样：有人的形像，","notes":[]},{"n":6,"t":"各有四张脸，四个翅膀。","notes":[]},{"n":7,"t":"他们的腿是直的，脚掌好像牛犊的蹄，灿烂如磨亮的铜。","notes":[]},{"n":8,"t":"在四面的翅膀以下有人的手。这四个活物的脸和翅膀是这样：","notes":[]},{"n":9,"t":"翅膀彼此相接，行走时并不转弯，各自往前直行。","notes":[]},{"n":10,"t":"至于脸的形像：四个活物各有人的脸，右面有狮子的脸，左面有牛的脸，也有鹰的脸；","notes":[]},{"n":11,"t":"这就是他们的脸。他们的翅膀向上张开，各有两个翅膀彼此相接，用另外两个翅膀遮体。","notes":["七十士译本没有“这就是他们的脸”。"]},{"n":12,"t":"他们各自往前直行。灵往哪里去，他们就往哪里去，行走时并不转弯。","notes":[]},{"n":13,"t":"至于四活物的形像，就如烧着火炭的形状，又如火把的形状。有火在四活物中间来回移动，这火有光辉，从火中发出闪电。","notes":[]},{"n":14,"t":"这些活物往来奔走，好像电光一闪。","notes":[]},{"n":15,"t":"我观看活物，看哪，有四张脸的活物旁边各有一个轮子在地上。","notes":[]},{"n":16,"t":"轮子的形状结构好像耀眼的水苍玉。四轮都是一个样式，形状结构好像轮中套轮。","notes":["七十士译本没有“结构”。","七十士译本没有“形状”。"]},{"n":17,"t":"轮子行走的时候，向四方直行，行走时并不转弯。","notes":[]},{"n":18,"t":"至于轮圈，高而可畏；四个轮圈周围布满眼睛。","notes":[]},{"n":19,"t":"活物行走，轮子也在旁边行走；活物离地上升，轮子也上升。","notes":[]},{"n":20,"t":"灵往哪里去，活物就往哪里去；轮子在活物旁边上升，因为活物的灵在轮中。","notes":[]},{"n":21,"t":"活物行走，轮子也行走；活物站住，轮子也站住；活物离地上升，轮子也在旁边上升，因为活物的灵在轮中。","notes":[]},{"n":22,"t":"活物的头上面有穹苍的形像，像耀眼惊人的水晶，铺张在活物的头顶上。","notes":[]},{"n":23,"t":"穹苍之下，活物的翅膀伸直，彼此相对，每个活物用两个翅膀遮住自己；每个活物用两个翅膀遮住自己 ，就是自己的身体。","notes":["有古卷和七十士译本没有第二次的“每个活物用两个翅膀遮住自己”。"]},{"n":24,"t":"活物行走的时候，我听见翅膀的响声，像大水的声音，像全能者的声音，又像军队闹哄的声音。活物站住的时候，翅膀垂下。","notes":[]},{"n":25,"t":"在他们头上的穹苍之上有声音。他们站住的时候，翅膀垂下。","notes":[]},{"n":26,"t":"在他们头上的穹苍之上有宝座的形像，仿佛蓝宝石的样子；宝座的形像上方有仿佛人的样子的形像。","notes":[]},{"n":27,"t":"我见他的腰以上有仿佛闪耀的金属，周围有仿佛火的形状，又见他的腰以下有仿佛火的形状，周围也有光辉。","notes":[]},{"n":28,"t":"下雨的日子，云中彩虹的形状怎样，周围光辉的形状也是怎样。这就是耶和华荣耀形像的样式，我一看见就脸伏于地。我又听见一位说话者的声音。","notes":[]}]},"2":{"heading":"神选召以西结作先知","verses":[{"n":1,"t":"他对我说：“人子啊，你站起来，我要和你说话。”","notes":[]},{"n":2,"t":"他对我说话的时候，灵进入我里面，使我站起来，我就听见他对我说话。","notes":[]},{"n":3,"t":"他对我说：“人子啊，我差你往悖逆我的国家，以色列人那里去，他们是悖逆我的。他们和他们的祖先违背我，直到今日。","notes":[]},{"n":4,"t":"这些人厚着脸皮，心里刚硬。我差你到他们那里去，你要对他们说：‘主耶和华如此说。’","notes":[]},{"n":5,"t":"他们是悖逆之家，他们或听，或不听，必知道在他们中间有了先知。","notes":[]},{"n":6,"t":"你，人子啊，虽有荆棘和蒺藜在你那里，你又住在蝎子中间，总不要怕他们，也不要怕他们的话；他们虽是悖逆之家，但你不要怕他们的话，也不要因他们的脸色惊惶。","notes":[]},{"n":7,"t":"他们或听，或不听，你只管将我的话告诉他们；他们是极其悖逆的。","notes":[]},{"n":8,"t":"“但是你，人子啊，要听我对你说的话，不要像那悖逆之家一样悖逆，要开口吃我所赐给你的。”","notes":[]},{"n":9,"t":"我观看，看哪，有一只手向我伸来；看哪，手中有一书卷。","notes":[]},{"n":10,"t":"他在我面前展开书卷，它内外都写着字，上面所写的有哀号、叹息、悲痛的话。","notes":[]}]},"3":{"heading":"耶和华派以西结作守望者","verses":[{"n":1,"t":"他对我说：“人子啊，要吃你所得到的，吃下这书卷；然后要去，对以色列家宣讲。”","notes":[]},{"n":2,"t":"于是我张开了口，他就使我吃这书卷。","notes":[]},{"n":3,"t":"他对我说：“人子啊，要吃我所赐给你的这书卷，塞满你的肚腹。”我就吃了，口中觉得其甜如蜜。","notes":[]},{"n":4,"t":"他对我说：“人子啊，你要到以色列家那里去，对他们传讲我的话。","notes":[]},{"n":5,"t":"你奉差遣不是往那说话艰涩、言语难懂的民那里，而是往以色列家去；","notes":[]},{"n":6,"t":"你不是往那说话艰涩、言语难懂的许多民族那里去，他们的话你不懂。然而，我若差你往他们那里去，他们会听从你。","notes":[]},{"n":7,"t":"以色列家却不肯听从你，因为他们不肯听从我；原来以色列全家是额头坚硬、心里刚愎的人。","notes":[]},{"n":8,"t":"看哪，我使你的脸坚硬，对抗他们的脸；使你的额头坚硬，对抗他们的额头。","notes":[]},{"n":9,"t":"我使你的额头像金刚石，比火石更坚硬。他们虽是悖逆之家，但你不要怕他们，也不要因他们的脸色而惊惶。”","notes":[]},{"n":10,"t":"他又对我说：“人子啊，我对你说的一切话，你心里要领会，耳朵要听。","notes":[]},{"n":11,"t":"要到被掳的人，到你本国百姓那里去，他们或听，或不听，你要对他们宣讲，告诉他们这是主耶和华说的。”","notes":[]},{"n":12,"t":"那时，灵将我举起，我就听见在我身后有极大震动的声音：“耶和华的荣耀，从他所在之处，是应当称颂的！”","notes":[]},{"n":13,"t":"有活物的翅膀相碰的声音，也有活物旁边轮子的声音，是极大震动的声音。","notes":[]},{"n":14,"t":"于是灵将我举起，带着我走。我就去了，十分苦恼，我的灵火热；耶和华的手重重地按在我身上。","notes":[]},{"n":15,"t":"我就来到提勒．亚毕那些住在迦巴鲁河边被掳的人那里，到他们住的地方，在他们中间惊愕地坐了七日。","notes":["“到他们住的地方”：原文另译“我就住在他们住的地方”。"]},{"n":16,"t":"过了七日，耶和华的话临到我，说：","notes":[]},{"n":17,"t":"“人子啊，我立你作以色列家的守望者，所以你要听我口中的话，替我警戒他们。","notes":[]},{"n":18,"t":"我何时指着恶人说：‘他必要死’；你若不警戒他，也不劝告他，使他离开恶行，拯救他的性命，这恶人必死在罪孽之中；我却要从你手里讨他的血债。","notes":[]},{"n":19,"t":"倘若你警戒恶人，他仍不转离罪恶，也不离开恶行，他必死在罪孽之中，你却救了自己的命。","notes":[]},{"n":20,"t":"但是义人若转离他的义而作恶，我要把绊脚石放在他面前，他必死亡；因你没有警戒他，他必死在罪中，他素来所行的义不被记念；我却要从你手里讨他的血债。","notes":[]},{"n":21,"t":"倘若你警戒义人，使他不犯罪，他就不犯罪；他因领受警戒就必存活，你也救了自己的命。”","notes":[]},{"n":22,"t":"在那里耶和华的手按在我身上。他对我说：“起来，到平原去，我要在那里和你说话。”","notes":[],"heads":["以西结暂成哑巴"]},{"n":23,"t":"于是我起来，到平原去，看哪，耶和华的荣耀停在那里，正如我在迦巴鲁河边所见到的一样，我就脸伏于地。","notes":[]},{"n":24,"t":"灵进入我里面，使我站起来。耶和华对我说：“你进屋里去，把门关上。","notes":[]},{"n":25,"t":"你，人子，看哪，人要用绳索捆绑你，使你不能出去到他们中间。","notes":[]},{"n":26,"t":"我必使你的舌头贴住上膛，以致你哑口，不能作责备他们的人；他们原是悖逆之家。","notes":[]},{"n":27,"t":"但我对你说话的时候，必使你开口，你就要对他们说：‘主耶和华如此说。’听的，让他听；不听的，任他不听，因为他们是悖逆之家。”","notes":[]}]},"4":{"heading":"预演耶路撒冷被困","verses":[{"n":1,"t":"“你，人子啊，拿一块砖，摆在你面前，将一座城耶路撒冷画在上面。","notes":[]},{"n":2,"t":"你要围攻这城，筑堡垒，建土堆，安营攻击，周围设撞城槌攻城，","notes":[]},{"n":3,"t":"又要拿一个铁盘放在你和城的中间，作为铁墙。你要把你的脸对着这城，使城被困。你要围攻这城，这要成为以色列家的预兆。","notes":[]},{"n":4,"t":"“你要向左侧卧，承担以色列家的罪孽；按你向左侧卧的日数，担当他们的罪孽。","notes":[]},{"n":5,"t":"我已将他们作恶的年数定了日期，就是三百九十天，你要如此担当以色列家的罪孽。","notes":[]},{"n":6,"t":"这些日子结束之后，你还要向右侧卧，担当犹大家的罪孽。我为你定了四十天，一天顶一年。","notes":[]},{"n":7,"t":"你要把你的脸对着被困的耶路撒冷，露出膀臂，说预言攻击这城。","notes":[]},{"n":8,"t":"看哪，我用绳索捆绑你，使你不能从这边翻到那边，直等到你围困的日子结束。","notes":[]},{"n":9,"t":"“你要取小麦、大麦、豆子、红豆、小米、粗麦，装在一个器皿里，为自己做饼；在你侧卧的三百九十天吃这饼。","notes":[]},{"n":10,"t":"你所吃食物的量是每天二十舍客勒，要按时吃。","notes":[]},{"n":11,"t":"你喝水的量是每天六分之一欣，要按时喝。","notes":[]},{"n":12,"t":"你要吃这饼像大麦饼一样，在众人眼前用人的粪烤它。”","notes":[]},{"n":13,"t":"耶和华说：“以色列人在我赶他们到的列国中，也必这样吃不洁净的食物。”","notes":[]},{"n":14,"t":"我说：“唉！主耶和华，看哪，我从来未曾被玷污，从幼年到如今没有吃过自然死的，或被野兽撕裂的，那不洁净的肉也未曾入我的口。”","notes":[]},{"n":15,"t":"于是他对我说：“看，我给你牛粪代替人粪，你要在上面烤你的饼。”","notes":[]},{"n":16,"t":"他又对我说：“人子，看哪，我必断绝耶路撒冷粮食的供应。他们要带着忧虑限量吃饼；带着惊惶限量喝水。","notes":["“粮食的供应”：原文直译“粮食的杖”；本卷书下同。"]},{"n":17,"t":"他们因缺粮缺水，彼此惊惶，在自己的罪孽中消灭。”","notes":[]}]},"5":{"heading":"以西结剃发","verses":[{"n":1,"t":"“你，人子啊，拿一把快刀当作剃刀，用这刀剃你的头发和胡须，然后用天平将须发分成几份。","notes":[]},{"n":2,"t":"围困的日子满了，你要把三分之一放在城中用火焚烧；三分之一放在城的四围用刀砍碎；三分之一任风吹散，我要拔刀追赶它们。","notes":[]},{"n":3,"t":"你要从其中取几根须发，用衣服的边包起来，","notes":[]},{"n":4,"t":"再从其中取一些扔在火里，在火中焚烧；必有火从其中出来烧尽以色列全家。","notes":[]},{"n":5,"t":"主耶和华如此说：这就是耶路撒冷。我曾将它安置在列国中，列邦都在它的四围。","notes":[]},{"n":6,"t":"耶路撒冷行恶，违背我的典章，过于列国；干犯我的律例，过于四围的列邦。它弃绝我的典章，也没有遵行我的律例。","notes":[]},{"n":7,"t":"所以主耶和华如此说：因为你们混乱，过于四围的列国，不遵行我的律例，不顺从我的典章，甚至也不顺从四围列国的规条，","notes":["“甚至...规条”：有古卷和古译本是“并以遵从四围列国的恶规尚不满意”。"]},{"n":8,"t":"所以主耶和华如此说：看哪，我，我必与你为敌，必在列国眼前，在你中间施行审判；","notes":[]},{"n":9,"t":"并且因你一切可憎的事，我要在你中间行未曾行过，将来也不会行的事。","notes":[]},{"n":10,"t":"在你中间，父亲要吃儿子，儿子要吃父亲。我必向你施行审判，将你剩下的人分散四方。","notes":["“方”：原文是“风”；下同。"]},{"n":11,"t":"主耶和华说：我指着我的永生起誓，因你用一切可憎之物、可厌的事玷污我的圣所，所以，我要把你剃光 ，我的眼必不顾惜你，也不可怜你。","notes":["“把你剃光”：有古卷是“使你减少”；七十士译本是“弃绝你”。"]},{"n":12,"t":"你的百姓三分之一必遭瘟疫而死，因饥荒在你们中间而消灭；三分之一必在你四围倒在刀下；我必将三分之一分散四方，要拔刀追赶他们。","notes":[]},{"n":13,"t":"“我要这样发尽我的怒气；我向他们发的愤怒停止以后，自己就得到平息。当我向他们发尽我的愤怒时，他们就知道我─耶和华所说的是出于妒忌。","notes":[]},{"n":14,"t":"在四围的列国中，我要使你成为荒凉，在所有过路人的眼前看为羞辱。","notes":[]},{"n":15,"t":"这样，我必以怒气、愤怒和烈怒的责备，向你施行审判。那时，它就在四围的列国中成为羞辱、讥刺、警戒、惊骇；这是我─耶和华说的。","notes":["“它”：七十士译本和其他古译本是“你”。"]},{"n":16,"t":"我向灭亡的人射出饥荒的恶箭，将它们射出，毁灭你们；那时，我要加重你们的饥荒，断绝你们粮食的供应。","notes":[]},{"n":17,"t":"我要令饥荒和恶兽临到你，使你丧失儿女。瘟疫和流血的事必在你那里盛行，我也要使刀剑临到你。这是我─耶和华说的。”","notes":[]}]},"6":{"heading":"谴责拜偶像的罪","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要面向以色列的众山说预言。","notes":[]},{"n":3,"t":"你要说：以色列的众山哪，要听主耶和华的话。主耶和华对大山、小冈、水沟、山谷如此说：看哪，我要使刀剑临到你们，也必毁坏你们的丘坛。","notes":[]},{"n":4,"t":"你们的祭坛要荒废，香坛必打碎。我要使你们当中被杀的人仆倒在你们的偶像面前，","notes":[]},{"n":5,"t":"将以色列人的尸首放在他们的偶像面前，把你们的骸骨抛散在祭坛的四周围。","notes":[]},{"n":6,"t":"无论你们住在何处，城镇要变为废墟，丘坛也必毁坏，以至于你们的祭坛荒废，被定罪，偶像打碎消除，香坛砍倒；你们所做的被涂去。","notes":["“被定罪”：有古译本是“毁坏”。"]},{"n":7,"t":"被杀的人必仆倒在你们中间，你们就知道我是耶和华。","notes":[]},{"n":8,"t":"“我必留下一些人，你们中有人得以在列国中脱离刀剑，分散在列邦。","notes":[]},{"n":9,"t":"那些逃脱的人，必在被掳所到的各国中记得我，我心里何等伤痛，因他们起淫心，离弃我，淫荡的眼追随偶像。他们因所做一切可憎的恶事，必厌恶自己。","notes":[]},{"n":10,"t":"他们必知道我是耶和华；我说过要使这灾祸临到他们身上，并非空话。","notes":[]},{"n":11,"t":"“主耶和华如此说：你当击掌顿足，说：哀哉！以色列家做了这一切可憎的恶事，必仆倒在刀剑、饥荒、瘟疫之下。","notes":[]},{"n":12,"t":"在远方的，必遭瘟疫而死；在近处的，必倒在刀剑之下；那存留被围困的，必因饥荒而死；我要在他们身上发尽我的愤怒。","notes":[]},{"n":13,"t":"被杀的要仆倒在祭坛四围的偶像中，在各高冈、各山顶、各青翠的树下，和各茂密的橡树下，就是他们献馨香的祭给一切偶像的地方。那时，他们就知道我是耶和华。","notes":[]},{"n":14,"t":"我必伸手攻击他们，使他们的地荒废，从第伯拉他的旷野起，一切的住处都荒凉。他们就知道我是耶和华。”","notes":["“从第伯拉他的旷野起”：有古卷是“从旷野到利比拉”。"]}]},"7":{"heading":"以色列的结局近了","verses":[{"n":1,"t":"耶和华的话又临到我，说：","notes":[]},{"n":2,"t":"“你，人子啊，主耶和华对以色列地如此说：结局，结局临到了地的四境！","notes":[]},{"n":3,"t":"现在你的结局已经来临；我要使我的怒气临到你，也要按你的行为审判你，照你所做一切可憎的事惩罚你。","notes":[]},{"n":4,"t":"我的眼必不顾惜你，也不可怜你，却要按你所做的报应你，照你们中间可憎的事惩罚你；你就知道我是耶和华。","notes":[]},{"n":5,"t":"“主耶和华如此说：灾难，惟一的灾难，看哪，临近了！","notes":["“灾难…灾难”：有古卷是“灾难接着灾难”。"]},{"n":6,"t":"结局到了，结局到了，它要醒起来攻击你。看哪，它已来到！","notes":[]},{"n":7,"t":"境内的居民哪，厄运临到你；时候到了，日子近了，有闹哄，但不是山上欢呼的声音。","notes":[]},{"n":8,"t":"我快要将我的愤怒倾倒在你身上，向你发尽我的怒气，按你的行为审判你，照你所做一切可憎的事惩罚你。","notes":[]},{"n":9,"t":"我的眼必不顾惜你，也不可怜你，必按你所做的报应你，照你中间可憎的事惩罚你；你就知道击打你的是我─耶和华。","notes":[]},{"n":10,"t":"“看哪，那日子！看哪，已来到！厄运已经发生！杖已开花，骄傲已发芽。","notes":[]},{"n":11,"t":"残暴兴起，成了罚恶的杖。他们将一无所有，他们的富足、他们的财宝都不复存在；他们中间也不再有尊荣。","notes":["“富足”或译“群众”。","“财宝”或译“喧嚣”。"]},{"n":12,"t":"时候到了，日子近了，买主不可欢喜，卖主也不用愁烦，因为烈怒已经临到他们众人身上。","notes":[]},{"n":13,"t":"卖主即使存活，也不能讨回所卖的，因为这异象关乎他们众人；谁都不能讨回，也没有人能在罪孽中使自己的生命刚强。”","notes":[]},{"n":14,"t":"“他们吹了角，预备齐全，却无一人出战，因为我的烈怒临到他们众人身上。","notes":[],"heads":["惩罚以色列的罪恶"]},{"n":15,"t":"外有刀剑，内有瘟疫、饥荒。在田野的，必因刀剑而死；在城中的，必遭饥荒、瘟疫吞灭。","notes":[]},{"n":16,"t":"其中幸存的要逃脱，各人因自己的罪孽在山上发出悲声，如谷中的鸽子哀鸣；","notes":[]},{"n":17,"t":"双手发软，膝盖软弱如水，","notes":[]},{"n":18,"t":"腰束麻布，战栗笼罩他们；各人脸上羞愧，头上光秃。","notes":[]},{"n":19,"t":"他们要把银子抛弃在街上，看金子如污秽之物。正当耶和华发怒的日子，金银不能拯救他们，不能满足食欲，也不能使肚腹饱满，反倒成了自己罪孽的绊脚石。","notes":[]},{"n":20,"t":"他们用所夸耀华美的妆饰制造可憎可厌的偶像，所以我使他们看它如污秽之物。","notes":[]},{"n":21,"t":"我必将它交给外邦人为掠物，交给地上的恶人为掳物；他们要亵渎它。","notes":[]},{"n":22,"t":"他们亵渎我宝贵之所，强盗也进去亵渎它。我必转脸不顾以色列人。","notes":["“宝贵之所”或译“隐密之所”。","“以色列人”：原文是“他们”。"]},{"n":23,"t":"“要制造锁链；因为遍地都有流血的罪，满城都是残暴的事。","notes":[]},{"n":24,"t":"所以，我要使列国中最凶恶的人前来占据他们的房屋；我要止息残暴人的骄傲，他们的圣所也要被亵渎。","notes":[]},{"n":25,"t":"毁灭来到；他们求平安，却没有平安。","notes":[]},{"n":26,"t":"灾害加上灾害，风声接连风声；他们要向先知寻求异象，但祭司的教诲、长老的谋略都必断绝。","notes":[]},{"n":27,"t":"君王要悲哀，官长要披绝望为衣，这地百姓的手都发颤。我必照他们所做的待他们，按他们所应得的审判他们，他们就知道我是耶和华。”","notes":[]}]},"8":{"heading":"以西结所见的第二个异象","verses":[{"n":1,"t":"第六年六月初五，我坐在家中；犹大的众长老坐在我面前。在那里主耶和华的手降在我身上。","notes":[],"heads":["耶路撒冷城里的偶像崇拜"]},{"n":2,"t":"我观看，看哪，有形像仿佛火的形状，从他腰部以下形状是火，从他腰部以上有光辉的形状，好像闪耀的金属。","notes":["“火”：七十士译本是“人”。"]},{"n":3,"t":"他伸出一只手的样式，抓住我的一绺头发，灵就将我举到天地中间；在神的异象中，他带我到耶路撒冷朝北的内院门口，在那里有惹动妒忌的偶像的座位，它惹动了妒忌。","notes":[]},{"n":4,"t":"看哪，在那里有以色列神的荣耀，形状与我在平原所见的一样。","notes":[]},{"n":5,"t":"神对我说：“人子啊，你举目向北观看。”我就举目向北观看，看哪，祭坛门北边的门口有那惹动妒忌的偶像。","notes":[]},{"n":6,"t":"他又对我说：“人子啊，你看见以色列家所做的吗？他们在这里做了极其可憎的事，使我远离我的圣所。你还要看见另有极其可憎的事。”","notes":[]},{"n":7,"t":"他领我到院子门口。我观看，看哪，墙上有一个洞。","notes":[]},{"n":8,"t":"他对我说：“人子啊，你要挖墙。”我就挖墙。看哪，有一扇门。","notes":[]},{"n":9,"t":"他说：“你进去，看他们在这里所做可憎的恶事。”","notes":[]},{"n":10,"t":"于是我进去看。看哪，四面墙上刻着各样爬行的动物、可憎的走兽和以色列家各样的偶像。","notes":[]},{"n":11,"t":"以色列家的七十个长老站在这些像前，沙番的儿子雅撒尼亚也站在其中，各人手拿他的香炉，烟云的香气上腾。","notes":[]},{"n":12,"t":"他对我说：“人子啊，你看见以色列家的长老，暗中在自己偶像的房间里所做的吗？因为他们说：‘耶和华看不见我们；耶和华已经离弃这地。’”","notes":[]},{"n":13,"t":"他又说：“你还要看见他们所做另外极其可憎的事。”","notes":[]},{"n":14,"t":"他领我到耶和华殿朝北的门口。看哪，在那里有妇女们坐着，为搭模斯哭泣。","notes":["“搭模斯”为神明的名字。"]},{"n":15,"t":"他对我说：“人子啊，你看见了吗？你还要看见比这更可憎的事。”","notes":[]},{"n":16,"t":"然后他领我到耶和华殿的内院。看哪，在耶和华殿门口、走廊和祭坛中间，约有二十五个人背向耶和华的殿，面向东方，向东拜太阳。","notes":[]},{"n":17,"t":"他对我说：“人子啊，你看见了吗？犹大家在这里行可憎的事还算为小吗？他们遍地行残暴，再三惹我发怒。看哪，他们手拿枝条举向鼻前！","notes":["“手拿枝条举向鼻前”：这是侮辱神的动作。"]},{"n":18,"t":"因此，我也要以愤怒行事。我的眼必不顾惜，也不可怜他们；他们虽在我耳边大声呼求，我还是不听。”","notes":[]}]},"9":{"heading":"耶路撒冷受惩罚","verses":[{"n":1,"t":"他在我耳边大声喊叫，说：“上前来啊，惩罚这城的人，手中要各拿毁灭的兵器。”","notes":[]},{"n":2,"t":"看哪，有六个人从朝北的上门而来，各人手里拿着致命的兵器；他们当中有一人身穿细麻衣，腰间系着文士用的墨盒。他们进来，站在铜的祭坛旁。","notes":[]},{"n":3,"t":"在基路伯之上，以色列神的荣耀从那里上升，到殿的入口处。神召那身穿细麻衣、腰间系着墨盒的人前来。","notes":[]},{"n":4,"t":"耶和华对他说：“你去走遍耶路撒冷全城，那些为城中所做可憎之事叹息哀哭的人，你要在他们额上做记号。”","notes":[]},{"n":5,"t":"我耳中听见耶和华对其余的人说：“要跟随他走遍全城去击杀。你们的眼不要顾惜，也不要可怜他们。","notes":[]},{"n":6,"t":"要将年老的、年轻的、少女、孩童和妇女，从我的圣所开始全都杀尽，只是不可挨近凡有记号的人。”于是他们从殿前的长老杀起。","notes":[]},{"n":7,"t":"他对他们说：“要使这殿污秽，使院中遍满被杀的人。你们出去吧！”他们就出去，在城中击杀。","notes":[]},{"n":8,"t":"他们击杀的时候，只剩我一人，我就脸伏在地上，呼喊说：“唉！主耶和华啊，你将愤怒倾倒在耶路撒冷，岂要把以色列所剩余的人都灭绝吗？”","notes":[]},{"n":9,"t":"他对我说：“以色列家和犹大家的罪孽极其重大。遍地都有流血的事，满城有冤屈，因为他们说：‘耶和华已经离弃这地，他看不见我们。’","notes":[]},{"n":10,"t":"因此，我的眼必不顾惜，也不可怜他们，要照他们所做的报应在他们头上。”","notes":[]},{"n":11,"t":"看哪，那身穿细麻衣、腰间系着墨盒的人回覆这事说：“我已经照你所吩咐的做了。”","notes":[]}]},"10":{"heading":"耶和华的荣耀离开圣城","verses":[{"n":1,"t":"我观看，看哪，在穹苍之中，也就是基路伯的头上，有蓝宝石的形状，仿佛宝座的形像显在他们上面。","notes":[]},{"n":2,"t":"耶和华对那身穿细麻衣的人说：“你进到基路伯下面旋转的轮子中，从基路伯之间取出火炭装满两手掌，撒在城上。”我亲眼看见他进去。","notes":[]},{"n":3,"t":"那人进去的时候，基路伯站在殿的南边，云彩充满了内院。","notes":[]},{"n":4,"t":"耶和华的荣耀从基路伯那里上升，到殿的入口处；殿内满布云彩，院子也充满了耶和华荣耀的光辉。","notes":[]},{"n":5,"t":"基路伯翅膀的响声传到外院，好像全能神说话的声音。","notes":[]},{"n":6,"t":"耶和华吩咐那身穿细麻衣的人说：“要从基路伯之间旋转的轮子中取火。”那人就进去站在一个轮子旁边。","notes":[]},{"n":7,"t":"基路伯中的一个基路伯伸手到基路伯中间的火那里，取一些放在那身穿细麻衣人的手掌中，那人拿了就出去。","notes":[]},{"n":8,"t":"在基路伯翅膀以下，显出有人手的样式。","notes":[]},{"n":9,"t":"我又观看，看哪，这些基路伯的旁边有四个轮子。一个基路伯旁有一个轮子，另一个基路伯旁也有一个轮子；轮子的形状好像水苍玉石。","notes":[]},{"n":10,"t":"至于四轮的形状，都是一个样式，好像轮中套轮。","notes":[]},{"n":11,"t":"轮子行走的时候，向四方都能直行，行走时并不转弯。头转向何方，它们也随着向何方行走，行走时并不转弯。","notes":[]},{"n":12,"t":"基路伯的全身，连背带手和翅膀，并轮子周围都布满眼睛。他们四个的轮子都是如此。","notes":[]},{"n":13,"t":"我耳中听见这些轮子称为“旋转的轮”。","notes":[]},{"n":14,"t":"基路伯各有四张脸：第一是基路伯的脸，第二是人的脸，第三是狮子的脸，第四是鹰的脸。","notes":[]},{"n":15,"t":"基路伯升上去了；这就是我在迦巴鲁河边所看见的活物。","notes":[]},{"n":16,"t":"基路伯行走，轮子也在旁边行走。基路伯展开翅膀，离地上升，轮子也不转离他们的旁边。","notes":[]},{"n":17,"t":"基路伯站住，轮子也站住；基路伯上升，轮子也跟着上升，因为活物的灵在轮中。","notes":[]},{"n":18,"t":"耶和华的荣耀离开殿的入口处，停在基路伯之上。","notes":[]},{"n":19,"t":"基路伯展开翅膀，在我眼前离地上升；他们离去的时候，轮子在旁边，都停在耶和华殿的东门口。在他们上面有以色列神的荣耀。","notes":[]},{"n":20,"t":"这是我在迦巴鲁河边所见的活物，他们在以色列神之下；因此我知道他们是基路伯。","notes":[]},{"n":21,"t":"他们各有四张脸、四个翅膀，翅膀以下有人手的样式。","notes":[]},{"n":22,"t":"至于他们脸的模样，以及身体的形像，正是我从前在迦巴鲁河边所看见的。他们各自往前直行。","notes":["七十士译本没有“以及身体的形像”。"]}]},"11":{"heading":"耶路撒冷被判罪","verses":[{"n":1,"t":"灵将我举起，带我到耶和华圣殿面向东方的东门。看哪，门口有二十五个人。我见其中有百姓的领袖押朔的儿子雅撒尼亚和比拿雅的儿子毗拉提。","notes":[]},{"n":2,"t":"耶和华对我说：“人子啊，他们就是图谋罪孽，在这城中设计恶谋的人。","notes":[]},{"n":3,"t":"他们说：‘盖房屋的时候尚未临近；这城是锅，我们是肉。’","notes":[]},{"n":4,"t":"人子啊，因此你当说预言，说预言攻击他们。”","notes":[]},{"n":5,"t":"耶和华的灵降在我身上，对我说：“你当说，耶和华如此说：以色列家啊，你们所说的，你们心里所想的，我都知道。","notes":[]},{"n":6,"t":"你们在这城里大行屠杀，被杀的人遍满街道。","notes":[]},{"n":7,"t":"所以主耶和华如此说：你们在城中杀的人是肉，这城是锅；你们却要从其中被带出去。","notes":[]},{"n":8,"t":"你们怕刀剑，我却要使刀剑临到你们。这是主耶和华说的。","notes":[]},{"n":9,"t":"我要把你们从这城中带出去，交在外邦人的手里，且要在你们中间施行审判。","notes":[]},{"n":10,"t":"你们要仆倒在刀下；我必在以色列的边界审判你们，你们就知道我是耶和华。","notes":[]},{"n":11,"t":"这城必不作你们的锅，你们也不作锅中的肉。我要在以色列的边界审判你们，","notes":[]},{"n":12,"t":"你们就知道我是耶和华；因为你们不遵行我的律例，也不顺从我的典章，却随从你们四围列国的规条。”","notes":[]},{"n":13,"t":"我正说预言的时候，比拿雅的儿子毗拉提死了。于是我脸伏在地，大声呼叫说：“唉！主耶和华啊，你要把以色列剩余的人都灭绝净尽吗？”","notes":[]},{"n":14,"t":"耶和华的话临到我，说：","notes":[],"heads":["神对被掳者的应许"]},{"n":15,"t":"“人子啊，耶路撒冷的居民对你的兄弟、你的本家、你的亲属、以色列全家所有的人说：‘你们远离耶和华吧！这地是赐给我们为业的。’","notes":[]},{"n":16,"t":"所以你当说：‘主耶和华如此说：我虽将以色列全家远远流放到列国，使他们分散在列邦，我却要在他们所到的列邦，暂时作他们的圣所。’","notes":[]},{"n":17,"t":"你当说：‘主耶和华如此说：我必从万民中召集你们，从分散的列邦中聚集你们，又将以色列地赐给你们。’","notes":[]},{"n":18,"t":"他们到了那里，必从其中除掉一切可憎之物、可厌的事。","notes":[]},{"n":19,"t":"我要使他们有合一的心，也要将新灵放在你们里面，又从他们的肉体中除掉石心，赐给他们肉心，","notes":["“你们”：有古卷、七十士译本和其他古译本是“他们”。"]},{"n":20,"t":"使他们顺从我的律例，谨守遵行我的典章。他们要作我的子民，我要作他们的神。","notes":[]},{"n":21,"t":"至于那些心中随从可憎之物、可厌的事的人，我必照他们所做的报应在他们头上。这是主耶和华说的。”","notes":[]},{"n":22,"t":"于是，基路伯展开翅膀，轮子都在他们旁边；在他们上面有以色列神的荣耀。","notes":[],"heads":["神的荣耀离开耶路撒冷"]},{"n":23,"t":"耶和华的荣耀从城中上升，停在城东的那座山上。","notes":[]},{"n":24,"t":"灵将我举起，在异象中神的灵将我带回迦勒底地，到被掳的人那里；之后我所见的异象就离我上升去了。","notes":[]},{"n":25,"t":"我就把耶和华指示我的一切事都说给被掳的人听。","notes":[]}]},"12":{"heading":"先知扮演难民","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你住在悖逆之家中；他们有眼可看却看不见，有耳可听却听不到，因为他们是悖逆之家。","notes":[]},{"n":3,"t":"所以人子啊，你要收拾被掳时需用的物件，白天在他们眼前离去，在他们眼前离开你所住的地方，移到别处去；他们虽是悖逆之家，或者可以领悟。","notes":[]},{"n":4,"t":"你要白天在他们眼前拿出你被掳时需用的物件。到了晚上，要在他们眼前离去，像被掳的人离去一样。","notes":[]},{"n":5,"t":"你要在他们眼前挖通墙壁，从其中将物件带出去。","notes":["“从其中...出去”：七十士译本是“穿过它出去”。"]},{"n":6,"t":"到天黑时，在他们眼前背在肩上带走，并要蒙住脸看不见地，因为我要使你成为以色列家的预兆。”","notes":["“带走”：七十士译本是“出去”；下同。"]},{"n":7,"t":"我就照着所吩咐的去做，白天拿出被掳时需用的物件。到了晚上，用手挖通墙壁；天黑的时候，在他们眼前背在肩上带走。","notes":[]},{"n":8,"t":"次日早晨，耶和华的话临到我，说：","notes":[]},{"n":9,"t":"“人子啊，以色列家，就是那悖逆之家，岂不是问你说：‘你在做什么呢？’","notes":[]},{"n":10,"t":"你要对他们说：‘主耶和华如此说：这是关乎耶路撒冷君王和其中以色列全家的默示。’","notes":[]},{"n":11,"t":"你要说：‘我是你们的预兆：我怎样做，他们所遭遇的也必这样，他们必被掳去，作俘虏。’","notes":[]},{"n":12,"t":"他们中间的君王也必在天黑时把物件背在肩上带走。他们要挖通墙壁，从其中带出去。他必蒙住脸，眼看不见地。","notes":["“从其中带出去”：七十士译本是“穿过它出去”。"]},{"n":13,"t":"我要把我的网撒在他身上，他就被我的罗网缠住。我要带他到迦勒底人之地的巴比伦；他没有看见那地，就死在那里。","notes":[]},{"n":14,"t":"我要把四围帮助他的和他所有的军队分散到四方，也要拔刀追赶他们。","notes":["“方”：原文是“风”。"]},{"n":15,"t":"我把他们驱逐到列国，分散在列邦的时候，他们就知道我是耶和华。","notes":[]},{"n":16,"t":"我却要留下他们当中几个人得免刀剑、饥荒、瘟疫，使他们在所到的列国述说自己所做一切可憎的事；他们就知道我是耶和华。”","notes":[]},{"n":17,"t":"耶和华的话临到我，说：","notes":[],"heads":["忧虑惊惶的预兆"]},{"n":18,"t":"“人子啊，你吃饭时必战抖，喝水时必惊惶忧虑。","notes":[]},{"n":19,"t":"你要对这地的百姓说：主耶和华论以色列地的耶路撒冷居民如此说，他们吃饭时必忧虑，喝水时必惊惶，因其中居民所行残暴的事，这地必然荒废，一无所存。","notes":[]},{"n":20,"t":"有人居住的城镇必变为废墟，地必荒凉；你们就知道我是耶和华。”","notes":[]},{"n":21,"t":"耶和华的话临到我，说：","notes":[],"heads":["平凡的俗语和非凡的信息"]},{"n":22,"t":"“人子啊，在以色列地你们怎么有这俗语说：‘日子延长，一切异象却落了空’呢？","notes":[]},{"n":23,"t":"你要告诉他们说：‘主耶和华如此说：我必令这俗语止息，以色列中不再有人引用这俗语。’你却要对他们说：‘日子临近，一切的异象都必应验。’","notes":[]},{"n":24,"t":"从此以后，以色列家不再有虚假的异象和奉承的占卜。","notes":[]},{"n":25,"t":"我─耶和华说话，所说的必定实现，不再耽延。你们这悖逆之家啊，你们在世的日子，我所说的话必定实现。这是主耶和华说的。”","notes":[]},{"n":26,"t":"耶和华的话临到我，说：","notes":[]},{"n":27,"t":"“人子，看哪，以色列家的人说：‘他所见的异象是许多日子以后的事，所说的预言是指着遥远的时候。’","notes":[]},{"n":28,"t":"所以你要对他们说：‘主耶和华如此说：我的话不再有一句耽延，我所说的话必定实现。’这是主耶和华说的。”","notes":[]}]},"13":{"heading":"斥责假先知","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要说预言，攻击以色列中说预言的先知，对那些随心说预言的人说：‘你们当听耶和华的话。’”","notes":[]},{"n":3,"t":"主耶和华如此说：“祸哉！那些愚顽的先知，随从自己的心意，却一无所见。","notes":[]},{"n":4,"t":"以色列啊，你的先知好像废墟中的狐狸，","notes":[]},{"n":5,"t":"没有上去堵住缺口，也没有为以色列家重修城墙，使它在耶和华的日子来临时，可以在战争中站得住。","notes":[]},{"n":6,"t":"他们看见的是虚假，是谎诈的占卜，说是耶和华说的；其实耶和华并没有差遣他们，他们却指望那话必站立得住。","notes":[]},{"n":7,"t":"你们岂不是见了虚假的异象吗？岂不是说了谎诈的占卜吗？你们说，这是耶和华说的，其实我没有说过。”","notes":[]},{"n":8,"t":"所以主耶和华如此说：“因你们说的是虚假，见的是谎诈，所以，看哪，我要敌对你们。这是主耶和华说的。","notes":[]},{"n":9,"t":"我的手必攻击那见虚假异象、用谎诈占卜的先知，他们必不列在我百姓的会中，不录在以色列家的名册上，也不能进入以色列地；你们就知道我是主耶和华。","notes":[]},{"n":10,"t":"他们诱惑我的百姓，说：‘平安！’其实没有平安，就像有人筑墙壁，看哪，他们倒去粉刷它。","notes":[]},{"n":11,"t":"所以你要对那些粉刷的人说：‘墙要倒塌，暴雨漫过。你们大冰雹啊，要降下 ，狂风要吹裂这墙。’","notes":["“你们...降下”：七十士译本是“我要降下大冰雹”。"]},{"n":12,"t":"看哪，这墙倒塌，人岂不是要问你们说：‘你们所粉刷的在哪里呢？’”","notes":[]},{"n":13,"t":"所以主耶和华如此说：“我要发怒，使狂风吹裂它，在怒中令暴雨漫过，又发怒降下大冰雹，毁坏它。","notes":[]},{"n":14,"t":"我要这样拆毁你们那粉饰的墙，把它夷为平地，以致根基露出；墙一倒塌，你们也要在其中灭亡。你们就知道我是耶和华。","notes":[]},{"n":15,"t":"我要对墙和粉刷它的人发尽我的愤怒，我要对你们说：‘墙没有了！粉刷它的人也没有了！’","notes":["“我”：原文另译“他们”。"]},{"n":16,"t":"这就是以色列的先知，他们指着耶路撒冷说预言，见到这城平安的异象，其实没有平安。这是主耶和华说的。”","notes":[]},{"n":17,"t":"“你，人子啊，要面向你百姓中随心说预言的妇女们，说预言攻击她们，","notes":[],"heads":["斥责假的女先知"]},{"n":18,"t":"说，主耶和华如此说：‘这些妇女有祸了！她们为众人的手腕缝驱邪带，替身材高矮不同的人做头巾，为要猎取人的性命。难道你们要猎取我百姓的性命，使自己存活吗？","notes":[]},{"n":19,"t":"你们为几把大麦、几块饼，在我的百姓中亵渎我，对那肯听谎言的百姓说谎言，让不该死的人死，让不该活的人活。’”","notes":[]},{"n":20,"t":"所以主耶和华如此说：“看哪，我要对付你们那用以猎取人，如猎飞鸟般的驱邪带。我要把驱邪带从你们的手腕扯去，释放那些如飞鸟被你们猎取的人。","notes":[]},{"n":21,"t":"我也必撕裂你们的头巾，救我百姓脱离你们的手，使他们不再被猎取，落在你们手中；你们就知道我是耶和华。","notes":[]},{"n":22,"t":"我未曾使义人伤心，你们却以谎话使他伤心，且又坚固恶人的手，不使他回转离开恶道得以存活。","notes":[]},{"n":23,"t":"所以，你们必不再看见虚假的异象，也不再行占卜的事；我要救我的百姓脱离你们的手；你们就知道我是耶和华。”","notes":[]}]},"14":{"heading":"神斥责拜偶像的罪","verses":[{"n":1,"t":"有几个以色列的长老到我这里来，坐在我面前。","notes":[]},{"n":2,"t":"耶和华的话临到我，说：","notes":[]},{"n":3,"t":"“人子啊，这些人在心中设立偶像，把陷自己于罪的绊脚石放在面前，我真的能让他们求问吗？","notes":[]},{"n":4,"t":"所以你要告诉他们，对他们说：‘主耶和华如此说：以色列家的人，凡在心中设立偶像，把陷自己于罪的绊脚石放在面前，却来到先知那里的，我─耶和华在他所求的事上，必因他拜许多偶像向他施行报应，","notes":["“在他...报应”：原文另译“必报应那些带着许多偶像来的人”。"]},{"n":5,"t":"为要夺回以色列家的心，他们全都拜偶像，与我疏远了。’","notes":[]},{"n":6,"t":"“所以你要对以色列家说：‘主耶和华如此说：回转吧！回转离开你们的偶像，转脸离开一切可憎的事。’","notes":[]},{"n":7,"t":"因为以色列家的人，或在以色列中寄居的外人，凡与我隔绝，在心中设立偶像，把陷自己于罪的绊脚石放在面前，却来到先知那里，要为自己的事求问我的，我─耶和华必亲自报应他。","notes":[]},{"n":8,"t":"我要向那人变脸，使他成为警戒和笑柄，并且我要把他从我民中剪除；你们就知道我是耶和华。","notes":[]},{"n":9,"t":"先知若被骗说了一句预言，是我─耶和华骗了那先知，我要伸手攻击他，把他从我百姓以色列中除灭。","notes":[]},{"n":10,"t":"他们必担当自己的罪孽。先知的罪孽和求问之人的罪孽都一样，","notes":[]},{"n":11,"t":"使以色列家不再走迷离开我，也不再因各样的罪过玷污自己，却要作我的子民，我也作他们的神。这是主耶和华说的。”","notes":[]},{"n":12,"t":"耶和华的话临到我，说：","notes":[],"heads":["挪亚、但以理、约伯"]},{"n":13,"t":"“人子啊，若有一国犯罪干犯我，我也伸手攻击它，断绝他们粮食的供应，使饥荒临到那地，将人与牲畜从其中剪除；","notes":[]},{"n":14,"t":"虽有挪亚、但以理、约伯这三人在那里，他们只能因自己的义救自己的命。这是主耶和华说的。","notes":[]},{"n":15,"t":"我若使恶兽经过那地，大肆蹂躏，使地荒凉，以致因这些兽，人都不得经过；","notes":[]},{"n":16,"t":"虽有这三人在其中，主耶和华说：我指着我的永生起誓，他们不能救儿子女儿，只有他们自己可以得救，那地仍然荒凉。","notes":[]},{"n":17,"t":"或者我使刀剑临到那地，说：‘让刀剑穿越那地’，以致我把人与牲畜从其中剪除；","notes":[]},{"n":18,"t":"虽有这三人在其中，主耶和华说：我指着我的永生起誓，他们不能救儿子女儿，只有他们自己可以得救。","notes":[]},{"n":19,"t":"或者我叫瘟疫流行那地，把我的愤怒带着血倾在其中，好使人与牲畜从其中剪除；","notes":[]},{"n":20,"t":"虽有挪亚、但以理、约伯在那里，主耶和华说：我指着我的永生起誓，他们不能救儿子女儿，只能因自己的义救自己的命。","notes":[]},{"n":21,"t":"“主耶和华如此说：我若将这四样大灾，就是刀剑、饥荒、恶兽、瘟疫降在耶路撒冷，将人与牲畜从其中剪除，岂不是更严重吗？","notes":[]},{"n":22,"t":"看哪，在那里必有幸免于难的人带着儿子女儿；看哪，他们来到你们这里；你们看见他们的所作所为，就会因我降给耶路撒冷的灾祸，因我降给它的一切，得到安慰。","notes":[]},{"n":23,"t":"你们因看见他们的所作所为，得到安慰，就会知道我在耶路撒冷所做的并非毫无缘故。这是主耶和华说的。”","notes":[]}]},"15":{"heading":"葡萄树的比喻","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，葡萄树比一切其他的树，就是树林里众树木的树枝，有什么长处呢？","notes":[]},{"n":3,"t":"可以从其中取木料来做工吗？人可以拿来做钉子，挂东西在上面吗？","notes":[]},{"n":4,"t":"看哪，它已经抛在火中当柴烧，火既烧了两头，中间也烧焦了，它还有什么用处呢？","notes":[]},{"n":5,"t":"看哪，它完整的时候尚且不能拿来做工，何况被火烧焦了，还能拿来做工吗？","notes":[]},{"n":6,"t":"所以，主耶和华如此说：我怎样使林中树里的葡萄树在火中当柴烧，我也必照样对待耶路撒冷的居民。","notes":[]},{"n":7,"t":"我必向他们变脸；他们虽从火中逃出来，火仍要烧灭他们。我向他们变脸的时候，你们就知道我是耶和华。","notes":[]},{"n":8,"t":"我必使这地荒凉，因为他们做了背叛的事。这是主耶和华说的。”","notes":[]}]},"16":{"heading":"不忠实的耶路撒冷","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要使耶路撒冷知道它那些可憎的事。","notes":[]},{"n":3,"t":"你要说，主耶和华对耶路撒冷如此说：你的根源，你的出身，是在迦南地；你的父亲是亚摩利人，母亲是赫人。","notes":[]},{"n":4,"t":"论到你出世的景况，在你出生的日子没有人为你断脐带，也没有用水清洗，使你洁净；没有人撒盐在你身上，也没有人用布包你。","notes":[]},{"n":5,"t":"没有人顾惜你，为你做一件这样的事来可怜你。你却被扔在田野上面，因你出生的日子就被厌恶。","notes":[]},{"n":6,"t":"“我从你旁边经过，见你在血中打滚，就对你说：‘你虽在血中，却要活下去！’我又说：‘你虽在血中，却要活下去！’","notes":["“我又说...去”：有些古卷、七十士译本和其他古译本没有本句。"]},{"n":7,"t":"我使你成长如田间所生长的；你就渐长，美而又美，两乳成形，头发秀长，但你仍然赤身露体。","notes":["“美而又美”：原文另译“成为少女”。"]},{"n":8,"t":"“我从你旁边经过看见你，看哪，正是你渴慕爱情的时候，我就用我衣服的边搭在你身上，遮盖你的赤体；又向你起誓，与你立约，你就归我。这是主耶和华说的。","notes":[]},{"n":9,"t":"那时我用水洗你，洗净你身上的血，又用油抹你。","notes":[]},{"n":10,"t":"我使你身穿锦绣衣裳，脚穿海狗皮鞋，用细麻布裹着你，精致衣料披在你身上。","notes":[]},{"n":11,"t":"我用首饰打扮你：我把手镯戴在你手上，项链在你颈上，","notes":[]},{"n":12,"t":"我也把环子戴在你鼻上，耳环在你耳上，华冠在你头上。","notes":[]},{"n":13,"t":"这样，你就有金银的首饰，穿的是细麻衣和精致衣料，以及锦绣衣裳；吃的是细面、蜂蜜和油。你也极其美貌，配登王后之位。","notes":[]},{"n":14,"t":"你美貌的名声传到列国，因我加给你荣华，使你完美。这是主耶和华说的。","notes":[]},{"n":15,"t":"“只是你仗着自己美貌，又凭着你的名声行淫。你向路人纵情淫乱，你的美貌就属于他的了。","notes":["“你的美貌…他的了”：原文另译“你就属于他了”；七十士译本的一些抄本和其他古译本没有本句。"]},{"n":16,"t":"你拿你的衣服为自己做成彩色丘坛，在其上行淫。这样的事本不该有，以后也不该发生。","notes":[]},{"n":17,"t":"你拿我所赐给你的那些美丽的金银宝物，为自己制造男性的偶像，与它们行淫；","notes":[]},{"n":18,"t":"你拿你的锦绣衣裳为它们披上，把我的膏油和香料摆在它们面前；","notes":[]},{"n":19,"t":"你把我赐给你的食物，就是我赐给你享用的细面、油和蜂蜜，都摆在它们面前作为馨香的供物。事情就是这样。这是主耶和华说的。","notes":[]},{"n":20,"t":"你拿你为我所生的儿女献给它们吞噬。你的淫乱岂是小事？","notes":[]},{"n":21,"t":"你竟把我的儿女杀了，使他们经火献给它们！","notes":[]},{"n":22,"t":"你做这一切可憎和淫乱的事，并未追念你幼年的日子，那时你赤身露体，在血中打滚。”","notes":[]},{"n":23,"t":"“你有祸了！你有祸了！这是主耶和华说的。你做这一切恶事之后，","notes":[],"heads":["耶路撒冷像淫妇"]},{"n":24,"t":"又为自己建造土墩，在各广场上筑起高台。","notes":[]},{"n":25,"t":"你在各个街头建造高台，使你的美貌变为可憎；又向所有过路的人招手，多行淫乱。","notes":["“招手”：原文直译“伸开双脚”。"]},{"n":26,"t":"你也和你那放纵情欲的邻邦埃及人行淫，增添你的淫乱，惹我发怒。","notes":[]},{"n":27,"t":"看哪，我伸手攻击你，减少你的福分，却将你交给恨恶你的非利士人，让他们任意待你。他们为你的淫行也感到羞耻。","notes":["“非利士人”：原文直译“非利士众女子”；下同。"]},{"n":28,"t":"你尚且不满意，又与亚述人行淫，但与他们行淫之后，仍不满足；","notes":[]},{"n":29,"t":"于是你与那称为贸易之地的迦勒底多行淫乱，即使这样，你仍不满足。","notes":[]},{"n":30,"t":"“你的心何等脆弱！这是主耶和华说的。你做这一切事，都是不知羞耻的妓女所做的，","notes":[]},{"n":31,"t":"在各个街头建造土墩，在各广场上筑高台；但你藐视行淫的赏金，又不像妓女。","notes":[]},{"n":32,"t":"你这行淫的妻子啊，竟然接外人，替代丈夫。","notes":[]},{"n":33,"t":"凡妓女都是得人赠礼，你反倒馈赠你所爱的人，倒贴他们，使他们从四围来与你行淫。","notes":[]},{"n":34,"t":"你的淫行与其他妇女相反，不是人要求与你行淫；是你给人赏金，不是人给你赏金；你是相反的。”","notes":[]},{"n":35,"t":"“你这妓女啊，要听耶和华的话。","notes":[],"heads":["神审判耶路撒冷"]},{"n":36,"t":"主耶和华如此说：因你放纵情欲，露出下体，与你所爱的行淫，因你敬拜一切可憎的偶像，就像自己儿女的血献给它们，","notes":["“就像”：原文另译“用”。"]},{"n":37,"t":"所以，看哪，我要聚集所有与你交欢的情人，不论是你所爱的或你所恨的，聚集他们从四围到你那里来；我要在他们面前暴露你的下体，使他们看尽你的下体。","notes":[]},{"n":38,"t":"我也要审判你，如审判淫妇和流人血的妇女一样。我要在愤怒和妒忌中使流血的罪归到你身上。","notes":[]},{"n":39,"t":"我要把你交在他们手中；他们必拆毁你的土墩，毁坏你的高台，剥去你的衣服，夺取你美丽的宝物，留下你赤身露体。","notes":[]},{"n":40,"t":"他们必聚集众人攻击你，用石头打死你，用刀剑刺透你，","notes":[]},{"n":41,"t":"用火焚烧你的房屋，在许多妇女眼前审判你。我必使你不再行淫，你也不再给赏金。","notes":[]},{"n":42,"t":"我止息了向你所发的愤怒，我的妒忌也离开了你；这样，我就平静，不再恼怒。","notes":[]},{"n":43,"t":"因你不追念幼年的日子，反而在这一切的事上惹我发烈怒，所以，看哪，我必照你所做的报应在你头上。在你一切可憎的事上，你不是还行了淫乱吗？这是主耶和华说的。”","notes":[]},{"n":44,"t":"“看哪，凡说俗语的必用这俗语攻击你，说：‘有其母必有其女。’","notes":[],"heads":["有其母必有其女"]},{"n":45,"t":"你实在是你母亲的女儿，厌弃丈夫和儿女；你也是你姊妹的姊妹，厌弃丈夫和儿女。你的母亲是赫人，父亲是亚摩利人。","notes":[]},{"n":46,"t":"你的姊姊是撒玛利亚，她和她的女儿们住在你北边；你的妹妹是所多玛，她和她的女儿们住在你南边。","notes":[]},{"n":47,"t":"你不只效法她们的行为，照她们可憎的事去做，不消多时，你所做的一切就比她们更恶。","notes":["“不消多时”或译“还以此为小事”。"]},{"n":48,"t":"主耶和华说：我指着我的永生起誓，你的妹妹所多玛与她的女儿们并未做你和你女儿们所做的事。","notes":[]},{"n":49,"t":"看哪，你的妹妹所多玛的罪孽是这样：她和她的女儿们都骄傲，粮源充足，大享安逸，却不扶持困苦和贫穷人的手。","notes":[]},{"n":50,"t":"她们狂傲，在我面前做可憎的事，我看见了就把她们除掉。","notes":[]},{"n":51,"t":"撒玛利亚所犯的罪不及你的一半，你所做可憎的事比她更多；比起你所做这一切可憎的事，你的姊妹倒显为义。","notes":[]},{"n":52,"t":"你既为你的姊妹辩护，就要担当自己的羞辱。因你所犯的罪比她们更可憎，她们比你倒显为义；你既使你的姊妹显为义，就要抱愧，担当自己的羞辱。”","notes":[]},{"n":53,"t":"“我必使她们被掳的归回，使所多玛和她的女儿们、撒玛利亚和她的女儿们，并与你一起被掳的都归回；","notes":[],"heads":["所多玛、撒玛利亚的复兴"]},{"n":54,"t":"好使你担当自己的羞辱，为所做的一切抱愧，让她们得到安慰。","notes":[]},{"n":55,"t":"你的妹妹所多玛和她的女儿们必回复原状；撒玛利亚和她的女儿们必回复原状；你和你的女儿们也必回复原状。","notes":[]},{"n":56,"t":"在你骄傲的日子，你的妹妹所多玛岂不是你口中的笑柄吗？","notes":[]},{"n":57,"t":"在你的恶行显露以前，那受了凌辱的亚兰女儿们和亚兰四围非利士的女儿们，都在四围藐视你。","notes":[]},{"n":58,"t":"耶和华说：你的淫荡和可憎之事，你自己要担当。”","notes":[]},{"n":59,"t":"“主耶和华如此说：你这轻看誓言而背约的，我必照你所做的报应你。","notes":[],"heads":["永远的约"]},{"n":60,"t":"然而我要追念在你幼年时我与你所立的约，也要与你立定永约。","notes":[]},{"n":61,"t":"当你接纳你的姊姊和妹妹时，你要追念你所行的，自觉惭愧；并且我要将她们赏给你做女儿，却不是按着我与你所立的约。","notes":[]},{"n":62,"t":"我要坚定与你所立的约，你就知道我是耶和华，","notes":[]},{"n":63,"t":"使你在我赦免你一切恶行时，心中追念，自觉惭愧，又因羞辱就不再开口。这是主耶和华说的。”","notes":[]}]},"17":{"heading":"大鹰和葡萄树的比喻","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要向以色列家出谜语，设比喻，","notes":[]},{"n":3,"t":"说，主耶和华如此说：有一只大鹰，翅膀大，翎毛长，羽毛丰满，色彩缤纷；它飞到黎巴嫩，啄去香柏树梢，","notes":[]},{"n":4,"t":"啄断它顶端的嫩枝，叼到贸易之地，放在商业城中。","notes":[]},{"n":5,"t":"它又从这地取了一些种子，种在肥沃的田里，栽于丰沛的水源旁，如种植柳树。","notes":[]},{"n":6,"t":"它渐渐生长，成为低矮蔓生的葡萄树；树枝伸向那鹰，根部在它下面。这样，它就长成了一棵葡萄树，生出枝子，长出枝干。","notes":[]},{"n":7,"t":"“有一只大鹰，翅膀大，羽毛多。看哪，葡萄树从栽种它的苗圃向这鹰伸出根来，长出枝子，期盼从它得到浇灌。","notes":["“一只”：七十士译本是“另一只”。"]},{"n":8,"t":"这棵树栽于肥田丰沛的水源旁，原是为了生枝、结果，成为佳美的葡萄树。","notes":[]},{"n":9,"t":"你要说，主耶和华如此说：这棵葡萄树岂能发旺呢？鹰岂不拔出它的根来，摘光它的果子，使它枯干，连长出的嫩叶都枯萎了吗？要把它连根拔除，并不需要费大力或动用许多人。","notes":[]},{"n":10,"t":"看哪，葡萄树虽然栽种了，岂能发旺呢？一经东风击打，岂不全然枯干了吗？它必在生长的苗圃中枯干了。”","notes":[]},{"n":11,"t":"耶和华的话临到我，说：","notes":[],"heads":["解释比喻"]},{"n":12,"t":"“你要对那悖逆之家说：你们不知道这些事是什么意思吗？你要这样说，看哪，巴比伦王曾到耶路撒冷，把其中的君王和官长带到巴比伦去，","notes":[]},{"n":13,"t":"又从以色列王室后裔中选取一人，与他立约，令他发誓，又掳走国中有势力的人，","notes":[]},{"n":14,"t":"使王国衰弱，不再强盛，只能靠守盟约方得生存。","notes":[]},{"n":15,"t":"他却背叛巴比伦王，差派使者前往埃及，要求埃及人给他马匹和许多人。他岂能亨通呢？这样做的人岂能逃脱呢？他背了约岂能逃脱呢？","notes":[]},{"n":16,"t":"主耶和华说：我指着我的永生起誓，他定要死在巴比伦，就是巴比伦王所在之处；因为巴比伦王立他为王，他竟轻看向王所起的誓，背弃王与他所立的约。","notes":[]},{"n":17,"t":"当敌人建土堆，筑堡垒，要歼灭许多人时，法老虽有强大军队和大批人马，在战场上还是不能帮助他。","notes":[]},{"n":18,"t":"他轻看誓言，背弃盟约，看哪，虽已投降，却又做这一切的事，他必不能逃脱。","notes":["“投降”：原文直译“伸出他的手”。"]},{"n":19,"t":"所以主耶和华如此说：我指着我的永生起誓，他既轻看我的誓言，背弃我的约，我必使这罪归到他头上。","notes":[]},{"n":20,"t":"我要把我的网撒在他身上，他就被我的罗网缠住。我要带他到巴比伦，在那里因他背叛我的罪惩罚他。","notes":[]},{"n":21,"t":"所有逃跑的军队必倒在刀下；剩余的也必分散四方。你们就知道说这话的是我─耶和华。”","notes":["“逃跑的”：有些古卷是“精锐的”。","“方”：原文是“风”。"]},{"n":22,"t":"主耶和华如此说：“我要从香柏树高高的树梢摘取并栽上，从顶端的嫩枝中折下一嫩枝，栽于极高的山上，","notes":[],"heads":["神对将来的应许"]},{"n":23,"t":"栽在以色列高处的山上。它就生枝、结果，成为高大的香柏树，各类飞禽中的鸟都来宿在其下，宿在枝子的荫下。","notes":["“各类飞禽...荫下”：七十士译本是“各类动物都来宿在其下，各类飞鸟宿在枝子的荫下”。"]},{"n":24,"t":"田野的树木因此就知道是我─耶和华使高树矮小，使矮树高大，使绿树枯干，使枯树发旺。我─耶和华说了这话，就必成就。”","notes":[]}]},"18":{"heading":"","verses":[{"n":1,"t":"耶和华的话又临到我，说：","notes":[]},{"n":2,"t":"“你们在以色列地何以有这俗语，‘父亲吃了酸葡萄，儿子牙齿就酸倒’呢？","notes":[]},{"n":3,"t":"主耶和华说：我指着我的永生起誓，你们在以色列必不再引用这俗语。","notes":[]},{"n":4,"t":"看哪，所有的生命都是属我的；父亲的生命怎样属我，儿子的生命也照样属我；然而犯罪的，他必定死。","notes":[]},{"n":5,"t":"“人若是公义，行公平公义的事：","notes":[]},{"n":6,"t":"未曾在山上吃祭物，未曾向以色列家的偶像举目；未曾污辱邻舍的妻，也未曾在妇人的经期间亲近她；","notes":[]},{"n":7,"t":"未曾亏负人，而是将欠债之人的抵押品还给他；未曾抢夺人的物件，却把食物给饥饿的人吃，把衣服给赤身的人穿；","notes":[]},{"n":8,"t":"未曾向人取利息，也未曾索取高利，反倒缩手不作恶，在人与人之间施行诚实的判断；","notes":[]},{"n":9,"t":"遵行我的律例，谨守我的典章，按诚实行事；这人是公义的，必要存活。这是主耶和华说的。","notes":["“按诚实行事”或译“遵行它”。"]},{"n":10,"t":"“他若生了儿子，儿子作强盗，流人的血，作父亲的虽然未犯此过，儿子却对弟兄行了以上所说的恶，在山上吃祭物，污辱邻舍的妻；","notes":["“作父亲的”：原文是“他”。","有些古译本没有“对弟兄”。"],"end":11},{"n":12,"t":"亏负困苦和贫穷的人，抢夺别人的物件，不归还抵押品，却向偶像举目，做可憎的事；","notes":[]},{"n":13,"t":"向人取利息，索取高利，这人岂能存活呢？他不能存活。他因做这一切可憎的事，必要死亡，他的血要归到自己身上。","notes":[]},{"n":14,"t":"“看哪，他若生了儿子，儿子见父亲所犯的一切罪，他见了，却不照样去做；","notes":[]},{"n":15,"t":"他未曾在山上吃祭物，未曾向以色列家的偶像举目，未曾污辱邻舍的妻；","notes":[]},{"n":16,"t":"也未曾亏负人，未曾取人的抵押品，未曾抢夺人的物件，却把食物给饥饿的人吃，把衣服给赤身的人穿，","notes":[]},{"n":17,"t":"缩手不害困苦人，未曾向人索取利息或高利；反倒顺从我的典章，遵行我的律例；如此，他必不因父亲的罪孽死亡，定要存活。","notes":[]},{"n":18,"t":"至于他父亲，因为施行欺压，抢夺弟兄，在百姓中行不善，看哪，他必因自己的罪孽死亡。","notes":[]},{"n":19,"t":"“你们还说：‘儿子为什么不担当父亲的罪孽呢？’儿子若行公平公义的事，谨守遵行我一切的律例，他必要存活。","notes":[]},{"n":20,"t":"惟有犯罪的，却必死亡。儿子不担当父亲的罪孽，父亲也不担当儿子的罪孽。义人的善果要归自己，恶人的恶报也要归自己。","notes":[]},{"n":21,"t":"“恶人若回转离开所做的一切罪恶，谨守我的一切律例，行公平公义的事，他必要存活，不致死亡。","notes":[]},{"n":22,"t":"他所犯的一切罪过都不被记念；他因所行的义，必要存活。","notes":[]},{"n":23,"t":"恶人死亡，岂是我所喜悦的呢？我岂不是喜悦他回转离开所行的道而存活吗？这是主耶和华说的。","notes":[]},{"n":24,"t":"至于义人，他若转离义行而作恶，照着恶人所做一切可憎的事去做，岂能存活呢？他所行的一切义都不被记念；反而因所行的恶、所犯的罪死亡。","notes":[]},{"n":25,"t":"“你们却说：‘主的道不公平！’以色列家啊，你们要听，我的道不公平吗？你们的道不是不公平吗？","notes":[]},{"n":26,"t":"义人若转离义行而作恶，他就因这些恶而死亡。他要死在他所作的恶中。","notes":[]},{"n":27,"t":"恶人若回转离开所行的恶，行公平公义的事，他必救自己的命；","notes":[]},{"n":28,"t":"因为他省察，回转离开所犯的一切罪过，他必要存活，不致死亡。","notes":[]},{"n":29,"t":"以色列家还说：‘主的道不公平！’以色列家啊，我的道不公平吗？你们的道不是不公平吗？","notes":[]},{"n":30,"t":"所以，以色列家啊，我必按你们各人所做的审判你们。当回转，回转离开你们一切的罪过，免得罪孽成为你们的绊脚石。这是主耶和华说的。","notes":[]},{"n":31,"t":"你们要把所犯的一切罪过尽行抛弃，为自己造一个新的心和新的灵。以色列家啊，你们为什么要死呢？","notes":[]},{"n":32,"t":"我不喜欢有任何人死亡，所以你们当回转，要存活！这是主耶和华说的。”","notes":[]}]},"19":{"heading":"哀歌","verses":[{"n":1,"t":"你当为以色列的领袖们唱哀歌，","notes":[]},{"n":2,"t":"说：你的母亲在狮子中是怎样的母狮呢？它蹲伏在少壮狮子中，养育小狮子。","notes":[]},{"n":3,"t":"它养大了其中一只小狮子，成了少壮狮子，学会抓食，它就吃人。","notes":[]},{"n":4,"t":"列国听见了就把它逮住在他们的坑里，用钩子拉它到埃及地去。","notes":[]},{"n":5,"t":"母狮见自己等候，期望落空，就从小狮子中取一只，养为少壮狮子；","notes":["“一只”：七十士译本是“另一只”。"]},{"n":6,"t":"它在众狮子中徜徉，长大成为少壮狮子，学会抓食，它就吃人。","notes":[]},{"n":7,"t":"它拆毁他们的宫殿，使他们的城镇变为废墟；因它咆哮的声音，遍地和其中所充满的都荒废了。","notes":["“它拆毁...宫殿”是根据一些古译本；原文直译“它知道他们的寡妇”，意思是“它与他们的寡妇同寝”。"]},{"n":8,"t":"于是四围列国从各省前来攻击它，把网撒在它身上，把它逮住在他们的坑里。","notes":[]},{"n":9,"t":"他们又用钩子钩住它，把它放入笼中，带到巴比伦王那里，把它押进城堡，以色列山上就不再听见它的声音。","notes":[]},{"n":10,"t":"你的母亲如葡萄树，在葡萄园中，栽于水边，因为水多，就多结果子，多生枝子；","notes":["“在葡萄园中”：原文是“在你血中”。"]},{"n":11,"t":"它长出坚固的枝干，可作统治者的权杖。这枝干高举在茂密的树枝中，可见树身高大，枝子繁多。","notes":[]},{"n":12,"t":"但在烈怒中它被拔出，摔在地上；东风吹干其果子，那坚固的枝干因折断而枯干，被火烧毁；","notes":[]},{"n":13,"t":"如今这葡萄树移植于旷野，在干旱无水之地，","notes":[]},{"n":14,"t":"火从枝干中发出，烧灭它的枝条和它的果子，以致不再有坚固的枝干，可作统治者的权杖。这是哀伤之歌，成为一首哀歌。","notes":["“它的枝条和它的果子”：原文另译“它的枝条”。"]}]},"20":{"heading":"以色列人的抗命","verses":[{"n":1,"t":"第七年五月初十，有以色列的几个长老前来求问耶和华，坐在我面前。","notes":[]},{"n":2,"t":"耶和华的话临到我，说：","notes":[]},{"n":3,"t":"“人子啊，你要告诉以色列的长老，对他们说，主耶和华如此说：你们来是为求问我吗？主耶和华说：我指着我的永生起誓，我必不让你们求问。","notes":[]},{"n":4,"t":"人子啊，你要审问他们吗？你要审问吗？你当使他们知道他们祖先那些可憎的事；","notes":[]},{"n":5,"t":"你要对他们说，主耶和华如此说：当日我拣选以色列，对雅各家的后裔起誓，在埃及地向他们显现，起誓说：我是耶和华─你们的神；","notes":[]},{"n":6,"t":"那日我向他们起誓，要领他们出埃及地，到我为他们所找到的流奶与蜜之地，就是全地中最美好之地。","notes":[]},{"n":7,"t":"我对他们说，你们各人要抛弃眼中所喜爱的可憎之物，不可用埃及的偶像玷污自己。我是耶和华─你们的神。","notes":[]},{"n":8,"t":"他们却悖逆我，不肯听从我，不抛弃他们眼中所喜爱的可憎之物，离弃埃及的偶像。“我就说，在埃及地，我要把我的愤怒倾倒在他们身上，向他们发尽我的怒气。","notes":[]},{"n":9,"t":"我这么做是为了我名的缘故，免得我的名在他们所居住之列国眼中被亵渎；我曾在这些列国眼前向他们显现，领他们出了埃及地。","notes":[]},{"n":10,"t":"我领他们出埃及地，带他们到旷野。","notes":[]},{"n":11,"t":"我将我的律例赐给他们，将我的典章指示他们；人若遵行就必因此存活。","notes":[]},{"n":12,"t":"我将我的安息日赐给他们，在我与他们中间作记号，让他们知道我─耶和华是使他们分别为圣的。","notes":[]},{"n":13,"t":"以色列家却在旷野中悖逆我，不顺从我的律例，厌弃我的典章；人若遵行就必因此存活。他们却大大干犯我的安息日。“因此我说，我要在旷野把我的愤怒倾倒在他们身上，灭绝他们。","notes":[]},{"n":14,"t":"我这么做是为了我名的缘故，免得我的名在列国眼中被亵渎，因为在这些列国眼前我领了他们出来。","notes":[]},{"n":15,"t":"并且我在旷野向他们起誓，必不领他们进入我所赐的流奶与蜜之地，就是全地中最美好之地；","notes":[]},{"n":16,"t":"因为他们厌弃我的典章，不顺从我的律例，干犯我的安息日，他们的心随从自己的偶像。","notes":[]},{"n":17,"t":"虽然如此，我的眼仍顾惜他们，不毁灭他们，不在旷野把他们灭绝净尽。","notes":[]},{"n":18,"t":"“我在旷野对他们的儿女说：‘不要遵行你们祖先的律例，不要谨守他们的规条，也不要用他们的偶像玷污自己。","notes":[]},{"n":19,"t":"我是耶和华─你们的神，你们要顺从我的律例，谨守遵行我的典章，","notes":[]},{"n":20,"t":"且以我的安息日为圣。这日必在我与你们中间作记号，使你们知道我是耶和华─你们的神。’","notes":[]},{"n":21,"t":"只是他们的儿女悖逆我，不顺从我的律例，也不谨守遵行我的典章；人若遵行就必因此存活。他们却干犯我的安息日。“因此我说，我要在旷野把我的愤怒倾倒在他们身上，向他们发尽我的怒气。","notes":[]},{"n":22,"t":"但我却缩手而未如此行；我这么做是为了我名的缘故，免得我的名在列国眼中被亵渎，因为在这些列国眼前我领了他们出来。","notes":[]},{"n":23,"t":"并且我在旷野向他们起誓，要把他们驱散到列国，分散在列邦；","notes":[]},{"n":24,"t":"因为他们不遵行我的典章，厌弃我的律例，干犯我的安息日，眼目向着他们祖先的偶像。","notes":[]},{"n":25,"t":"我也任他们遵行那无益的律例，随从那不能使人存活的规条。","notes":[]},{"n":26,"t":"他们使所有头生的经火，我就任凭他们在这供物上玷污自己；我令他们惊恐，他们就知道我是耶和华。","notes":[]},{"n":27,"t":"“人子啊，你要告诉以色列家，对他们说，主耶和华如此说：你们的祖先在背叛我的事上再次亵渎了我；","notes":[]},{"n":28,"t":"我领他们到我起誓应许赐给他们的地，他们看见各高冈、各茂密的树，就在那里献祭，献上惹我发怒的供物，也在那里焚烧馨香的祭，献浇酒祭。","notes":[]},{"n":29,"t":"我就对他们说：你们去的那丘坛叫什么呢？它名叫巴麻，直到今日。","notes":[]},{"n":30,"t":"所以你要对以色列家说，主耶和华如此说：你们仍要照你们祖先所做的玷污自己吗？还要照他们可憎的事行淫吗？","notes":[]},{"n":31,"t":"当你们献上供物，使你们儿子经火的时候，你们仍用各样的偶像玷污自己，直到今日。以色列家啊，我岂能让你们求问呢？主耶和华说：我指着我的永生起誓，我必不让你们求问。","notes":[]},{"n":32,"t":"“你们说：‘我们要像列国和列邦的宗族一样，去事奉木头与石头。’你们所起的心意万不能成就。”","notes":[]},{"n":33,"t":"“主耶和华说：我指着我的永生起誓，我要作王，用大能的手和伸出的膀臂，并倾倒出来的愤怒治理你们。","notes":[],"heads":["神的惩罚和赦免"]},{"n":34,"t":"我必用大能的手和伸出的膀臂，并倾倒出来的愤怒，把你们从万民中领出来，从被赶散到的列邦聚集你们。","notes":[]},{"n":35,"t":"我必带你们到万民的旷野，在那里当面审判你们。","notes":[]},{"n":36,"t":"我怎样在埃及地的旷野审判你们的祖先，也必照样审判你们。这是主耶和华说的。","notes":[]},{"n":37,"t":"我要使你们从杖下经过，按着约的拘束带领你们。","notes":["“约的拘束”：七十士译本是“数目”。"]},{"n":38,"t":"我必从你们中间除尽叛逆和得罪我的人；我将他们从所寄居的地方领出来，他们却不得进入以色列地，你们就知道我是耶和华。","notes":[]},{"n":39,"t":"“你们，以色列家啊，主耶和华如此说：你们若不听从我，从今以后就让各人去事奉他的偶像吧，只是不可再以你们的供物和偶像亵渎我的圣名。","notes":[]},{"n":40,"t":"“在我的圣山，就是以色列高处的山，以色列全家，那地所有的人，都要在那里事奉我。在那里我悦纳他们，并要你们献供物和初熟的土产，以及一切的圣物。这是主耶和华说的。","notes":[]},{"n":41,"t":"我把你们从万民中领出来，从被赶散到的列邦聚集你们，那时我必悦纳你们如同悦纳馨香之祭，我要在列国眼前，在你们中间显为圣。","notes":[]},{"n":42,"t":"我领你们进入以色列地，就是我起誓应许赐给你们列祖之地，那时你们就知道我是耶和华。","notes":[]},{"n":43,"t":"你们在那里要追念那玷污自己的所作所为，又要因所行的一切恶事厌恶自己。","notes":[]},{"n":44,"t":"以色列家啊，我为我名的缘故，没有照着你们的恶行和你们的败坏对待你们；你们就知道我是耶和华。这是主耶和华说的。”","notes":[]},{"n":45,"t":"耶和华的话临到我，说：","notes":[],"heads":["尼革夫大火"]},{"n":46,"t":"“人子啊，你要面向南方，向南方传讲，向尼革夫田野的树林说预言。","notes":["“传讲”：原文是“滴下”；21．2同。","“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”；下同。"]},{"n":47,"t":"你要对尼革夫的树林说，要听耶和华的话。主耶和华如此说：看哪，我要在你那里点火，烧灭你们中间所有的绿树和枯树，猛烈的火焰必不熄灭；从南到北，人的脸都被烧焦。","notes":[]},{"n":48,"t":"凡血肉之躯都知道是我─耶和华点了火，这火必不熄灭。”","notes":[]},{"n":49,"t":"于是我说：“唉！主耶和华啊，人都指着我说：他不是说比喻的人吗？”","notes":[]}]},"21":{"heading":"耶和华的刀","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，把你的脸正对着耶路撒冷，对着圣所传讲 ，向以色列地说预言。","notes":["“圣所”：有古卷和七十士译本是“他们的圣所”；原文另译“她的圣所”。"]},{"n":3,"t":"你要向以色列地说，耶和华如此说：看哪，我与你为敌，拔刀出鞘，把义人和恶人从你中间剪除。","notes":[]},{"n":4,"t":"因为我要剪除你当中的义人和恶人，所以我的刀要出鞘，从南到北攻击所有的血肉之躯；","notes":[]},{"n":5,"t":"凡血肉之躯都知道我─耶和华已拔刀出鞘，刀必不再入鞘。","notes":[]},{"n":6,"t":"你，人子啊，要叹息，在他们眼前断了腰，愁苦地叹息。","notes":[]},{"n":7,"t":"若有人对你说：‘你为什么叹息呢？’你就说：‘因为有风声传来，人心惶惶，双手发软，精神衰败，膝弱如水。看哪，它临近了，一定会发生。’这是主耶和华说的。”","notes":[]},{"n":8,"t":"耶和华的话临到我，说：","notes":[]},{"n":9,"t":"“人子啊，你要预言说，耶和华如此吩咐，你要说：有刀，刀已磨快，又擦亮了；","notes":[]},{"n":10,"t":"磨快为要大大杀戮，擦亮为要像闪电。我们岂能快乐呢？它藐视我儿的权杖和一切的木头。","notes":["“我们岂能快乐呢？”原文另译“啊！它在炫耀。”","“它藐视...木头”或译“我儿的权杖藐视一切的木头”。"]},{"n":11,"t":"它已经交给人擦亮，可以掌握使用；这刀已经磨快擦亮，好交在行杀戮的人手中。","notes":[]},{"n":12,"t":"人子啊，你要呼喊哀号，因为这刀将临到我的百姓，临到以色列所有的领袖身上。他们和我的百姓都要交在刀下，所以你要捶胸。","notes":["“捶胸”：原文直译“拍腿”，表示苦恼和悲伤。"]},{"n":13,"t":"因为这是一个考验，若它藐视权杖，也不算一回事，又怎么样呢？这是主耶和华说的。”","notes":[]},{"n":14,"t":"“人子啊，你要拍掌预言，使这刀三番两次临到；这是致人死伤的刀，就是包围人，使人大受死伤的刀。","notes":[]},{"n":15,"t":"我设立这恐吓的刀，攻击他们一切的城门，为要使他们的心惊慌害怕，许多人因而跌倒。唉！它造得像闪电，磨得尖利，要行杀戮。","notes":["“恐吓”：七十士译本是“屠宰”。","“它”：原文另译“这恐吓的刀”。","“磨得尖利”：原文是“收入鞘内”。"]},{"n":16,"t":"刀啊，要行动一致，向右边，或指向左边；面向哪方，就向哪方。","notes":["“要行动一致”：七十士译本是“要把自己磨得尖利”。"]},{"n":17,"t":"我也要拍掌，使我的愤怒平息。这是我─耶和华说的。”","notes":[]},{"n":18,"t":"耶和华的话临到我，说：","notes":[],"heads":["巴比伦王的刀"]},{"n":19,"t":"“人子啊，你要画定两条路线，使巴比伦王的刀过来，这两条路必从同一地分出来；要在通往城里的路口画手作指标。","notes":[]},{"n":20,"t":"你要划定一条路，使刀来到亚扪人的拉巴，来到犹大，在坚固城耶路撒冷。","notes":[]},{"n":21,"t":"因为巴比伦王站在岔路上，在两条路口占卜。他摇签求问神像，察看肝脏；","notes":["“签”：原文是“箭”。"]},{"n":22,"t":"右手是耶路撒冷的占卜，以便安设撞城槌，张口喊杀，扬声呼叫，建土堆，筑堡垒，以撞城槌攻打城门。","notes":["“喊杀”：七十士译本是“大喊”。"]},{"n":23,"t":"在那些曾郑重起誓的犹大人眼中，这是虚假的占卜；但巴比伦王要使他们想起自己的罪孽，以便俘掳他们。”","notes":[]},{"n":24,"t":"于是，主耶和华如此说：“因你们的过犯显露，你们的罪孽被记得，以致你们的罪恶在你们一切的行为上都彰显出来；你们既被记得，就被掳在掌中。","notes":[]},{"n":25,"t":"你这亵渎行恶的以色列王啊，你的日子，最后惩罚的时刻已来临。","notes":[]},{"n":26,"t":"主耶和华如此说：当除掉荣冕，摘下华冠，景况已不复从前；要使卑者升为高，使高者降为卑。","notes":[]},{"n":27,"t":"我要将这国倾覆，倾覆，再倾覆；这国必不存在，直等到那应得的人来到，我就将国赐给他。”","notes":[]},{"n":28,"t":"“人子啊，你要说预言；你要说，论到亚扪人和他们的凌辱，主耶和华吩咐我如此说：有刀，拔出来的刀，已经擦亮，为了行杀戮；它亮如闪电以行吞灭。","notes":[],"heads":["刀和亚扪人"]},{"n":29,"t":"他们为你见虚假的异象，行谎诈的占卜，使你倒在亵渎之恶人的颈项上；他们的日子，最后惩罚的时刻已来临。","notes":[]},{"n":30,"t":"你收刀入鞘吧！我要在你受造之处、生长之地惩罚你。","notes":[]},{"n":31,"t":"我要把我的愤怒倾倒在你身上，把我烈怒的火喷在你身上；又将你交在善于杀灭、畜牲一般的人手中。","notes":[]},{"n":32,"t":"你要成为火中之柴，你的血必在地里；你必不再被记得，因为这是我─耶和华说的。”","notes":[]}]},"22":{"heading":"耶路撒冷的过犯","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“你，人子啊，你要审问，审问这流人血的城吗？要使它知道它一切可憎的事。","notes":[]},{"n":3,"t":"你要说，主耶和华如此说：那在其中流人血的城啊，它的时刻已到，它制造偶像玷污了自己。","notes":[]},{"n":4,"t":"你因流了人的血，算为有罪；因所制造的偶像，玷污自己；你使你的日子临近，你的年数已来到。所以我使你承受列国的凌辱和列邦的讥诮。","notes":["“你的年数已来到”：七十士译本是“使你的年数来到”。"]},{"n":5,"t":"你这恶名昭彰、混乱的城啊，离你或远或近的国家都必讥诮你。","notes":[]},{"n":6,"t":"“看哪，以色列的领袖在你那里，为了流人的血各逞其能。","notes":[]},{"n":7,"t":"你那里有轻慢父母的，在你当中有欺压寄居者的，你那里也有亏负孤儿寡妇的。","notes":[]},{"n":8,"t":"你藐视我的圣物，干犯我的安息日。","notes":[]},{"n":9,"t":"你那里有为流人血而毁谤人的，你那里有在山上吃祭物的，在你当中也有行淫乱的，","notes":[]},{"n":10,"t":"有露父亲下体的，有玷辱经期中不洁净之妇人的。","notes":["“有露父亲下体的”：参利18．8。"]},{"n":11,"t":"这人与邻舍的妻子行可憎的事，那人行淫污辱媳妇，在你那里还有人污辱他的姊妹，父亲的女儿。","notes":[]},{"n":12,"t":"你那里有收取报酬而流人血的。你取利息，又索取高利；欺压邻舍，夺取财物；你竟然忘了我。这是主耶和华说的。","notes":[]},{"n":13,"t":"“看哪，我因你所得不义之财和你们中间所流的血，就击打手掌。","notes":[]},{"n":14,"t":"到了我对付你的日子，你的心岂能忍受呢？你的手还能有力吗？我─耶和华说了这话，就必成就。","notes":[]},{"n":15,"t":"我要把你驱散到列国，分散在列邦。我也必除掉你们中间的污秽。","notes":[]},{"n":16,"t":"你在列国眼前因自己所做的被侮辱，你就知道我是耶和华。”","notes":["“你...被侮辱”：七十士译本和其他古译本是“我在列国眼前因你而受亵渎”。"]},{"n":17,"t":"耶和华的话临到我，说：","notes":[],"heads":["神的大炼炉"]},{"n":18,"t":"“人子啊，我看以色列家为渣滓。他们是炉中的铜、锡、铁、铅，是炼银的渣滓。","notes":["“他们是...渣滓”：原文另译“他们是银、铜、锡、铁、铅，是炉中的渣滓”。"]},{"n":19,"t":"所以主耶和华如此说：因你们全都成为渣滓，所以，看哪，我必将你们聚集在耶路撒冷中。","notes":[]},{"n":20,"t":"人怎样把银、铜、铁、铅、锡聚在炉中，吹火使它熔化；照样，我也要在我的怒气和愤怒中聚集你们，把你们安置在城中，使你们熔化。","notes":[]},{"n":21,"t":"我必聚集你们，把我烈怒的火吹在你们身上，你们就在其中熔化。","notes":[]},{"n":22,"t":"银子怎样在炉中熔化，你们也必照样在城中熔化，因此就知道是我─耶和华把愤怒倾倒在你们身上。”","notes":[]},{"n":23,"t":"耶和华的话临到我，说：","notes":[],"heads":["以色列领袖们的罪恶"]},{"n":24,"t":"“人子啊，你要向这地说：你是未被洁净之地，在我盛怒的日子，没有雨水在其上。","notes":["“被洁净”：七十士译本是“被雨浸透”。"]},{"n":25,"t":"其中的先知同谋背叛，如咆哮的狮子抓撕掠物。他们吞灭人命，抢夺财宝，使这地寡妇增多。","notes":["“其中的先知同谋背叛”：七十士译本是“它其中的领袖”。"]},{"n":26,"t":"其中的祭司曲解我的律法，亵渎我的圣物，不分别圣与俗，也不使人分辨洁净和不洁净，又遮眼不顾我的安息日；在他们中间连我也被亵慢了。","notes":[]},{"n":27,"t":"其中的领袖仿佛野狼抓撕掠物，流人的血，伤害人命，为得不义之财。","notes":[]},{"n":28,"t":"其中的先知为他们粉刷，见虚假的异象，行谎诈的占卜，说：‘主耶和华如此说’，其实耶和华并没有说。","notes":[]},{"n":29,"t":"这地的百姓惯行欺压抢夺之事，亏负困苦和贫穷的人，欺压寄居者，没有公平。","notes":[]},{"n":30,"t":"我在他们中间寻找一人重修城墙，在我面前为这地站在缺口上，使我不致灭绝它，却连一个也找不着。","notes":[]},{"n":31,"t":"所以我把愤怒倾倒在他们身上，用烈怒之火消灭他们，照他们所做的报应在他们头上。这是主耶和华说的。”","notes":[]}]},"23":{"heading":"两个犯罪的姊妹","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，有两个女子，是一母所生，","notes":[]},{"n":3,"t":"她们在埃及行淫，年少时就开始行淫；在那里任人拥抱胸怀，抚弄她们少女的乳房。","notes":[]},{"n":4,"t":"她们的名字，大的叫阿荷拉，妹妹叫阿荷利巴。她们都归于我，生了儿女。论到她们的名字，阿荷拉是撒玛利亚，阿荷利巴是耶路撒冷。","notes":[]},{"n":5,"t":"“阿荷拉归我之后却仍行淫，恋慕所爱的人，就是亚述人，都是战士，","notes":["“战士”或译“邻邦”；下同。"]},{"n":6,"t":"穿着蓝衣，作省长、副省长，全都是俊美的年轻人，骑着马的骑士。","notes":[]},{"n":7,"t":"阿荷拉与亚述人中所有的美男子放纵淫行，她因拜所恋慕之人的一切偶像，玷污了自己。","notes":[]},{"n":8,"t":"她从埃及的时候，就没有离开过淫乱；因为她年轻时，有人与她同寝，抚弄她少女的乳房，和她纵欲行淫。","notes":[]},{"n":9,"t":"因此，我把她交在她所爱的人手中，就是她所恋慕的亚述人手中。","notes":[]},{"n":10,"t":"他们暴露她的下体，掳掠她的儿女，用刀杀了她；他们向她施行审判，使她在妇女中留下臭名。","notes":[]},{"n":11,"t":"“她妹妹阿荷利巴虽然看见了，却还是纵欲，比姊姊更加腐败，行淫乱比姊姊更甚。","notes":[]},{"n":12,"t":"她恋慕亚述人，就是省长和副省长，披挂整齐的战士，骑着马的骑士，全都是俊美的年轻人。","notes":[]},{"n":13,"t":"我看见她被污辱，姊妹二人同行一路。","notes":[]},{"n":14,"t":"阿荷利巴又加增淫行，她看见墙上刻有人像，就是鲜红色的迦勒底人雕刻的像。","notes":[]},{"n":15,"t":"它们腰间系着带子，头上有飘扬的裹头巾，都是将军的样子，巴比伦人的形像；迦勒底是他们的出生地。","notes":[]},{"n":16,"t":"阿荷利巴一看见就恋慕他们，派遣使者往迦勒底他们那里去。","notes":[]},{"n":17,"t":"巴比伦人来到她那里，上了她爱情的床，与她行淫污辱她。她被污辱，随后她的心却与他们生疏。","notes":[]},{"n":18,"t":"这样，她既暴露淫行，暴露下体；我的心就与她生疏，像先前与她的姊姊生疏一样。","notes":[]},{"n":19,"t":"她仍继续增添淫行，追念她年轻时在埃及地行淫的日子，","notes":[]},{"n":20,"t":"恋慕情人的身壮精足，如驴似马。","notes":[]},{"n":21,"t":"这样，你就渴望年轻时的淫荡；那时，埃及人因你年轻时的胸怀，抚弄你的乳房。”","notes":["“因你...乳房”：原文另译“抚弄你的乳房，抚摸你的胸怀”。"]},{"n":22,"t":"阿荷利巴啊，主耶和华如此说：“看哪，我要激起先前你喜爱，而后生疏的人前来攻击你。我必使他们前来，在你四围攻击你；","notes":[],"heads":["神审判妹妹"]},{"n":23,"t":"有巴比伦人、迦勒底众人、比割人、书亚人、哥亚人，还有亚述众人与他们一起，都是俊美的年轻人。他们是省长、副省长、将军、有名声的，全都骑着马。","notes":[]},{"n":24,"t":"他们用兵器、战车、辎重车，率领大军前来攻击你。他们要拿大小盾牌，戴着头盔，在你四围摆阵攻击你。我要把审判交给他们，他们必按着自己的规条审判你。","notes":["“用兵器、”：原文另译“配备”；七十士译本是“从北方用”。"]},{"n":25,"t":"我要向你倾泄我的妒忌，使他们以愤怒对待你。他们必割去你的鼻子和耳朵，你剩余的人必倒在刀下。他们必掳去你的儿女，你所剩余的必被火焚烧。","notes":[]},{"n":26,"t":"他们必剥去你的衣服，夺取你美丽的宝物。","notes":[]},{"n":27,"t":"这样，我必止息你的淫行和你从埃及地就开始犯的淫乱，使你不再仰望亚述，也不再追念埃及。","notes":[]},{"n":28,"t":"主耶和华如此说：看哪，我必把你交在你所恨恶的人手中，就是你心与他生疏的人手中。","notes":[]},{"n":29,"t":"他们要以恨恶对待你，夺取你劳碌得来的一切，留下你赤身露体。你淫乱的下体，连你的淫行和淫荡，都必显露。","notes":[]},{"n":30,"t":"人必向你行这些事；因为你随从外邦人行淫，用他们的偶像玷污自己。","notes":[]},{"n":31,"t":"你走了你姊姊的路，所以我必把她的杯交在你的手中。”","notes":[]},{"n":32,"t":"主耶和华如此说：“你必喝你姊姊的杯，那杯又深又广，盛得很多，使你遭受嗤笑讥刺。","notes":[]},{"n":33,"t":"你必酩酊大醉，满有愁苦。你姊姊撒玛利亚的杯，惊骇和凄凉的杯，","notes":[]},{"n":34,"t":"你必喝它，并且喝干。甚至咀嚼杯片，撕裂自己的胸脯；因为我曾说过。这是主耶和华说的。”","notes":[]},{"n":35,"t":"主耶和华如此说：“因你忘记我，将我丢在背后，所以你要担当你的淫行和淫荡。”","notes":[]},{"n":36,"t":"耶和华对我说：“人子啊，你要审问阿荷拉与阿荷利巴吗？要指出她们所做可憎的事。","notes":[],"heads":["神审判两姊妹"]},{"n":37,"t":"她们行奸淫，手中有血。她们与偶像行奸淫，使她们为我所生的儿女经火，给它们当食物。","notes":[]},{"n":38,"t":"此外，她们还向我这样做：同一天又玷污我的圣所，干犯我的安息日。","notes":[]},{"n":39,"t":"她们杀了儿女献给偶像，当天又进入我的圣所，亵渎了它。看哪，这就是她们在我殿中所做的。","notes":[]},{"n":40,"t":"“况且你们两姊妹派人从远方召人来。使者到了他们那里，看哪，他们就来了。为了他们，你们沐浴，画眼影，佩戴首饰，","notes":[]},{"n":41,"t":"坐在华美的床上，前面摆设桌子，把我的香料和膏油放在其上。","notes":[]},{"n":42,"t":"在那里有一群人欢乐的声音；有许多的平民，从旷野来的醉汉，把镯子戴在她们手上，把华冠戴在她们头上。","notes":["“醉汉”：原文另译“西巴人”；七十士译本的一些抄本是“男子”。"]},{"n":43,"t":"“我论到这久行奸淫而色衰的妇人说：现在人们还要与她行淫，她也要与人行淫。","notes":[]},{"n":44,"t":"人去到阿荷拉和阿荷利巴二淫妇那里，好像与妓女行淫。","notes":["“人...那里”：七十士译本是“人与阿荷拉及阿荷利巴行淫”。"]},{"n":45,"t":"义人必按照审判淫妇和流人血之妇人的规条，审判她们；因为她们是淫妇，她们的手中有血。”","notes":[]},{"n":46,"t":"主耶和华如此说：“我要让军队上来攻击她们，使她们惊骇，成为掳物。","notes":[]},{"n":47,"t":"这军队必用石头打死她们，用刀剑杀害她们，又杀戮她们的儿女，用火焚烧她们的房屋。","notes":[]},{"n":48,"t":"我必使这地不再有淫行，所有的妇女都受警戒，不再效法你们的淫行。","notes":["“你们的淫行”：七十士译本是“她们的淫行”。"]},{"n":49,"t":"人必因你们的淫行报应你们；你们要担当拜偶像的罪，因此你们就知道我是主耶和华。”","notes":[]}]},"24":{"heading":"生锈的锅","verses":[{"n":1,"t":"第九年十月初十，耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要记录这一天的名称，这特别的一天，巴比伦王围困耶路撒冷，就在这特别的一天。","notes":[]},{"n":3,"t":"你要向这悖逆之家设比喻，对他们说，主耶和华如此说：把锅放在火上，放好了，倒水在其中；","notes":[]},{"n":4,"t":"要将肉块，一切肥美的肉块，腿和肩都放在锅里，要装满上等的骨头；","notes":[]},{"n":5,"t":"要取羊群中最好的，把柴堆在下面，把它煮开，骨头煮在其中。","notes":["“柴”：原文是“骨头”。"]},{"n":6,"t":"“主耶和华如此说：祸哉！这流人血的城，就是长锈的锅。它的锈未曾除掉，要将肉块从其中一一取出，不必抽签。","notes":[]},{"n":7,"t":"这城所流的血还在城中，血倒在光滑的磐石上，没有倒在地上，用土掩盖；","notes":[]},{"n":8,"t":"是我使这城所流的血倒在光滑的磐石上，不得掩盖，为要惹动愤怒，施行报应。","notes":[]},{"n":9,"t":"所以主耶和华如此说：祸哉！这流人血的城，我必亲自加大柴堆。","notes":[]},{"n":10,"t":"你要添上木柴，使火着旺，将肉煮烂，加上香料，烤焦骨头；","notes":["“加上香料”：原文另译“把汤倒出”；七十士译本是“把汤熬浓”。"]},{"n":11,"t":"你要把空锅放在炭火上，将锅烧热，把铜烧红，熔化其中的污秽，除净其上的锈。","notes":[]},{"n":12,"t":"然而这一切劳碌无效，它厚厚的锈，即使用火也除不掉。","notes":["“然而...无效”：原文另译“我的劳碌无效”；七十士译本没有本句。"]},{"n":13,"t":"虽然我想洁净你污秽的淫行，你却不洁净，你的污秽再也不能洁净，直等我止息了向你发的愤怒。","notes":[]},{"n":14,"t":"我─耶和华说了这话，时候到了，就必成就；必不退缩，不顾惜，也不怜悯。人必照你的所作所为审判你。这是主耶和华说的。”","notes":[]},{"n":15,"t":"耶和华的话临到我，说：","notes":[],"heads":["先知妻子的死"]},{"n":16,"t":"“人子，看哪，我要以灾病夺取你眼中所喜爱的，你却不可悲哀哭泣，也不可流泪，","notes":[]},{"n":17,"t":"只可叹息，不可出声，不可办理丧事；裹上头巾，脚上穿鞋，不可捂着胡须，也不可吃一般人的食物。”","notes":["“一般人的食物”：原文另译“吊丧的食物”；下同。"]},{"n":18,"t":"到了早晨我把这事告诉百姓，晚上我的妻子就死了。次日早晨我就遵命而行。","notes":[]},{"n":19,"t":"百姓对我说：“你这样做跟我们有什么关系，你不告诉我们吗？”","notes":[]},{"n":20,"t":"我对他们说：“耶和华的话临到我，说：","notes":[]},{"n":21,"t":"‘你告诉以色列家，主耶和华如此说：我要使我的圣所被亵渎，就是你们凭势力所夸耀、眼里所喜爱、心中所爱惜的；并且你们所遗留的儿女必倒在刀下。","notes":[]},{"n":22,"t":"那时，你们要照我所做的去做。你们不可捂着胡须，也不可吃一般人的食物。","notes":[]},{"n":23,"t":"你们头要裹上头巾，脚要穿上鞋；不可悲哀哭泣。你们必因自己的罪孽衰残，相对叹息。","notes":[]},{"n":24,"t":"以西结必这样成为你们的预兆；凡他所做的，你们也必照样做。那事来到，你们就知道我是主耶和华。’”","notes":[]},{"n":25,"t":"“你，人子啊，那日当我除掉他们所倚靠的保障、所欢喜的荣耀，并眼中所喜爱的，心里所重看的儿女时，","notes":[]},{"n":26,"t":"逃脱的人岂不来到你这里，使你耳闻这事吗？","notes":[]},{"n":27,"t":"那日你要向逃脱的人开口说话，不再哑口无言。你必这样成为他们的预兆，他们就知道我是耶和华。”","notes":[]}]},"25":{"heading":"预言亚扪受惩罚","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要面向亚扪人说预言，攻击他们。","notes":[]},{"n":3,"t":"你要对亚扪人说，当听主耶和华的话。主耶和华如此说：我的圣所遭亵渎，以色列地变荒凉，犹大家被掳掠；那时，你因这些事说‘啊哈’，","notes":[]},{"n":4,"t":"所以，看哪，我要把你交给东方人为业；他们必在你中间安营居住，设立居所，吃你的果子，喝你的奶。","notes":[]},{"n":5,"t":"我必使拉巴成为牧放骆驼之地，使亚扪成为羊群躺卧之处，你们就知道我是耶和华。","notes":[]},{"n":6,"t":"主耶和华如此说：因你们拍手顿足，幸灾乐祸，藐视以色列地，","notes":[]},{"n":7,"t":"所以，看哪，我要伸手攻击你，把你交给列国作为掳物。我必从万民中剪除你，从列邦中消灭你。我必除灭你，你就知道我是耶和华。”","notes":[]},{"n":8,"t":"“主耶和华如此说：因摩押和西珥人说‘看哪，犹大家与列国无异’，","notes":[],"heads":["斥责摩押"]},{"n":9,"t":"所以，看哪，我要破开摩押边界的城镇，就是摩押人所夸耀的城镇，伯．耶施末、巴力．免、基列亭，","notes":[]},{"n":10,"t":"令东方人前来攻击亚扪人。我必将亚扪交给他们为业，使亚扪人在列国中不再被记念。","notes":[]},{"n":11,"t":"我也必向摩押施行审判，他们就知道我是耶和华。”","notes":[]},{"n":12,"t":"“主耶和华如此说：因为以东向犹大家报仇，因向他们报仇而大大显为有罪，","notes":[],"heads":["斥责以东"]},{"n":13,"t":"所以主耶和华如此说：我要伸手攻击以东，将人与牲畜剪除，使以东从提幔起，直到底但，地变荒凉，人也都倒在刀下。","notes":[]},{"n":14,"t":"我要藉我子民以色列的手报复以东；他们必照我的怒气，按我的愤怒对待以东，以东人就知道施报的是我。这是主耶和华说的。”","notes":[]},{"n":15,"t":"“主耶和华如此说：因非利士人报仇，就是心存轻蔑报仇；他们永怀仇恨，意图毁灭，","notes":[],"heads":["斥责非利士"]},{"n":16,"t":"所以主耶和华如此说：看哪，我要伸手攻击非利士人，剪除基利提人，灭绝沿海剩余的居民。","notes":[]},{"n":17,"t":"我要大大报复他们，发怒斥责他们。我报复他们的时候，他们就知道我是耶和华。”","notes":[]}]},"26":{"heading":"斥责推罗","verses":[{"n":1,"t":"第十一年某月初一，耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，因推罗向耶路撒冷说：‘啊哈！那众民之门已经破坏，向我敞开；它既变为废墟，我必丰盛。’","notes":[]},{"n":3,"t":"所以，主耶和华如此说：推罗，看哪，我与你为敌，使许多国家涌上攻击你，如同海洋使波浪涌上一样。","notes":[]},{"n":4,"t":"他们要破坏推罗的城墙，拆毁它的城楼。我也要刮净它的尘土，使它成为光滑的磐石。","notes":[]},{"n":5,"t":"推罗必成为海中的晒网场，因为我曾说过， 这是主耶和华说的。它必成为列国的掳物，","notes":[]},{"n":6,"t":"推罗乡间邻近的城镇必遭刀剑灭绝，他们就知道我是耶和华。”","notes":["“邻近的城镇”：原文直译“众女子”；下同。"]},{"n":7,"t":"主耶和华如此说：“看哪，我必使诸王之王，就是巴比伦王尼布甲尼撒，率领马匹、战车、骑兵、军队和许多人从北方来攻击推罗。","notes":[]},{"n":8,"t":"他必用刀剑杀灭你乡间邻近的城镇，也必筑堡垒，建土堆，举盾牌攻击你。","notes":[]},{"n":9,"t":"他要安设撞城槌攻破你的城墙，以刀剑拆毁你的城楼。","notes":[]},{"n":10,"t":"因他马匹众多，尘土必扬起遮蔽你。他进入你的城门，如同进入已有缺口之城。那时，你的城墙必因骑兵、车轮和战车的响声震动。","notes":[]},{"n":11,"t":"他的马蹄必践踏你所有的街道；他必用刀剑杀戮你的居民。你坚固的柱子必倒在地上。","notes":["“柱子”或译“柱像”。"]},{"n":12,"t":"人必掳获你的财宝，掠夺你的货财；他们要破坏你的城墙，拆毁你华美的房屋，将你的石头、木头、尘土都抛在水中。","notes":[]},{"n":13,"t":"我要使你唱歌的声音止息；人不再听见你弹琴的声音。","notes":[]},{"n":14,"t":"我必使你成为光滑的磐石，作晒网的场所。你不得再被建造，因为我─耶和华已这样说了。这是主耶和华说的。”","notes":[]},{"n":15,"t":"主耶和华对推罗如此说：“在你中间行杀戮，受伤的人唉哼时，海岛岂不都因你倾倒的响声震动吗？","notes":[]},{"n":16,"t":"那时沿海的君王都要从宝座下来，除去朝服，脱下锦衣，披上战兢，坐在地上，不停发抖，为你而惊骇。","notes":[]},{"n":17,"t":"他们必为你作哀歌，向你说：‘你这闻名之城，航海之人居住，海上最为坚固的，你和居民使所有住在沿海的人无不惊恐，现在竟然毁灭了！","notes":[]},{"n":18,"t":"如今在你倾覆的日子，海岛都要战兢；海中的群岛见你归于无有就都惊惶。’”","notes":[]},{"n":19,"t":"主耶和华如此说：“推罗啊，我要使你变为荒凉，如无人居住的城镇；又使深水漫过你，大水淹没你。","notes":["原文没有“推罗啊”。"]},{"n":20,"t":"那时，我要使你和下到地府的人同去，到古时候的人那里；我要使你和下到地府的人一同住在地的深处，在久已荒废的地方，使你那里不再有人居住；我要在活人之地显荣耀。","notes":["“我要...显荣耀”：七十士译本是“你不能在活人之地立足”。"]},{"n":21,"t":"我必叫你令人惊恐，使你不再存留于世；人虽寻找你，却永不寻见。这是主耶和华说的。”","notes":[]}]},"27":{"heading":"哀悼推罗的挽歌","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，要为推罗作哀歌。","notes":[]},{"n":3,"t":"你要对位于海口，跟许多海岛的百姓做生意的推罗说，主耶和华如此说：推罗啊，你曾说：‘我全然美丽。’","notes":[]},{"n":4,"t":"你的疆界在海的中心，造你的使你全然美丽。","notes":[]},{"n":5,"t":"他们用示尼珥的松树作你的甲板，用黎巴嫩的香柏树作桅杆，","notes":[]},{"n":6,"t":"用巴珊的橡树作你的桨，用镶嵌象牙的基提海岛黄杨木为舱板。","notes":["“黄杨木”：原文另译“柏树”。"]},{"n":7,"t":"你的帆是用埃及绣花细麻布做的，可作你的大旗；你的篷是用以利沙岛的蓝色和紫色布做的。","notes":[]},{"n":8,"t":"西顿和亚发的居民为你划桨；推罗啊，你们中间的智慧人为你掌舵。","notes":[]},{"n":9,"t":"迦巴勒的长者和智者在你中间修补裂缝；海上一切的船只和水手都在你那里进行货物交易。","notes":[]},{"n":10,"t":"“波斯人、路德人、弗人在你的军营中作战士；他们在你们中间悬挂盾牌和头盔，彰显你的尊荣。","notes":["“弗”是利比亚的一部分。"]},{"n":11,"t":"亚发人和你的军队都驻守在四围的城墙上，你的城楼上也有勇士；他们悬挂盾牌，成全你的美丽。","notes":[]},{"n":12,"t":"“他施因你多有财物，就作你的客商，他们带着银、铁、锡、铅前来换你的商品。","notes":[]},{"n":13,"t":"雅完、土巴、米设都与你交易，以人口和铜器换你的货物。","notes":[]},{"n":14,"t":"陀迦玛族用马匹、战马和骡子换你的商品。","notes":[]},{"n":15,"t":"底但人与你交易，许多海岛成为你的码头；他们拿象牙、黑檀木与你交换。","notes":[]},{"n":16,"t":"亚兰 因你货品充裕，就作你的客商；他们用绿宝石、紫色布、刺绣、细麻布、珊瑚、红宝石换你的商品。","notes":["“亚兰”：有古卷是“以东”。"]},{"n":17,"t":"犹大和以色列地都与你交易；他们用米匿的小麦、饼、蜜、油、乳香换你的货物。","notes":[]},{"n":18,"t":"大马士革也因你货品充裕，多有各类财物，就带来黑本酒和白羊毛与你交易。","notes":[]},{"n":19,"t":"威但和从乌萨来的雅完人为了你的货物，以加工的铁、桂皮、香菖蒲换你的商品。","notes":["“威但...雅完人”：原文另译“他们用从乌萨来的酒”。"]},{"n":20,"t":"底但以骑马用的座垫毯子与你交换。","notes":[]},{"n":21,"t":"阿拉伯和基达所有的领袖都作你的客商，用羔羊、公绵羊、公山羊与你交换。","notes":[]},{"n":22,"t":"示巴和拉玛的商人也来与你交易，他们用各类上好的香料、各类的宝石和黄金换你的商品。","notes":[]},{"n":23,"t":"哈兰、干尼、伊甸、示巴商人、亚述和基抹都与你交易。","notes":["“示巴商人、亚述”：原文另译“亚述商人”；或另译“亚述”。"]},{"n":24,"t":"这些商人将美好的货物包在蓝色的绣花包袱内，又将华丽的衣服装在香柏木的箱子里，用绳索捆着，以此与你交易。","notes":["“以此与你交易”：原文直译“在你的市场”。"]},{"n":25,"t":"他施的船只为你运货，你在海中满载货物，极其沉重。","notes":[]},{"n":26,"t":"划桨的把你划到水深之处，东风在海中将你击破。","notes":[]},{"n":27,"t":"你的财宝、商品、货物、水手、掌舵的、修补船缝的、进行货物交易的，并你那里所有的战士和你中间所有的军队，在你倾覆的日子都必沉在海底。","notes":[]},{"n":28,"t":"因掌舵者的呼声，郊野就必震动。","notes":[]},{"n":29,"t":"所有划桨的都从他们的船下来；水手和所有在海上掌舵的，都要登岸。","notes":[]},{"n":30,"t":"他们必为你放声痛哭，撒尘土于头上，在灰中打滚；","notes":[]},{"n":31,"t":"又为你使头光秃，用麻布束腰，号啕痛哭，痛苦至极。","notes":[]},{"n":32,"t":"他们哀号的时候，为你作哀歌，为你痛哭：有何城如推罗，在海中沉寂呢？","notes":[]},{"n":33,"t":"你由海上运出商品，使许多民族充裕；你以许多财宝货物令地上的君王丰富。","notes":[]},{"n":34,"t":"在深水中被海浪打破的时候，你的货物和你中间所有的军队都下沉。","notes":[]},{"n":35,"t":"海岛所有的居民为你惊奇，他们的君王都甚恐慌，面带愁容。","notes":[]},{"n":36,"t":"万民中的商人向你发嘘声；你令人惊恐，不再存留于世，直到永远。”","notes":[]}]},"28":{"heading":"斥责推罗王","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要对推罗的君王说，主耶和华如此说：你心里高傲，说：‘我是神明；我在海中坐诸神之位。’虽然你把你的心比作神明的心，你却不过是人，并不是神明！","notes":[]},{"n":3,"t":"看哪，你比但以理更有智慧，任何秘密都不能向你隐藏。","notes":[]},{"n":4,"t":"你靠自己的智慧聪明得了财宝，把金银收入库房；","notes":[]},{"n":5,"t":"你靠自己的大智慧以贸易增添财宝，又因你的财宝心里高傲；","notes":[]},{"n":6,"t":"所以主耶和华如此说：因你把你的心比作神明的心，","notes":[]},{"n":7,"t":"所以，看哪，我必使外国人，就是列国中凶暴的人临到你这里；他们要拔刀摧毁你用智慧得来的美物，污损你的荣光。","notes":[]},{"n":8,"t":"他们必使你坠入地府；你要像被刺杀之人的死，死在海中。","notes":[]},{"n":9,"t":"在杀你的人面前，你还能说‘我是神明’吗？在杀害你的人手中，你不过是人，并不是神明。","notes":[]},{"n":10,"t":"你要死在陌生人手中，像未受割礼之人的死，因为我曾说过，这是主耶和华说的。”","notes":[]},{"n":11,"t":"耶和华的话临到我，说：","notes":[],"heads":["推罗王的结局"]},{"n":12,"t":"“人子啊，要为推罗王作哀歌，对他说，主耶和华如此说：你曾是完美的典范，智慧充足，全然美丽。","notes":[]},{"n":13,"t":"你在伊甸─神的园中，佩戴各样宝石，就是红宝石、红璧玺、金刚石、水苍玉、红玛瑙、碧玉、蓝宝石、绿宝石、红玉；你的宝石有黄金的底座，手工精巧，都是在你受造之日预备的。","notes":["“你的宝石...精巧”：原文另译“和黄金；又有精美的鼓笛在你那里”。"]},{"n":14,"t":"我指定你为受膏的基路伯，看守保护；你在神的圣山上；往来在如火的宝石中。","notes":[]},{"n":15,"t":"你从受造之日起行为正直，直到后来查出你的不义。","notes":[]},{"n":16,"t":"你因贸易发达，暴力充斥其中，以致犯罪，所以我污辱你，使你离开神的山。守护者基路伯啊，我已将你从如火的宝石中歼灭。","notes":[]},{"n":17,"t":"你因美丽心中高傲，因荣光而败坏智慧，我已将你抛弃在地，把你摆在君王面前，好叫他们目睹眼见。","notes":[]},{"n":18,"t":"你因罪孽众多，贸易不公，亵渎了你的圣所；因此我使火从你中间发出，烧灭了你，使你在所有观看的人眼前变为地上的灰烬。","notes":[]},{"n":19,"t":"万民中凡认识你的都必为你惊奇。你令人惊恐，不再存留于世，直到永远。”","notes":[]},{"n":20,"t":"耶和华的话临到我，说：","notes":[],"heads":["斥责西顿"]},{"n":21,"t":"“人子啊，你要面向西顿，向它说预言。","notes":[]},{"n":22,"t":"你要说，主耶和华如此说：‘西顿，看哪，我与你为敌，我要在你中间得荣耀。’我在它中间施行审判、显为圣的时候，人就知道我是耶和华。","notes":[]},{"n":23,"t":"我必令瘟疫进入西顿，使血流在街上。刀剑从四围临到它，被杀的要仆倒在其中；人就知道我是耶和华。”","notes":[]},{"n":24,"t":"“四围恨恶以色列家的人，对他们必不再如刺人的荆棘、伤人的蒺藜；他们就知道我是主耶和华。”","notes":[],"heads":["以色列要蒙福"]},{"n":25,"t":"主耶和华如此说：“我将分散在万民中的以色列家召集回来，在列国眼前向他们显为圣的时候，他们仍可在我所赐给我仆人雅各之地居住。","notes":[]},{"n":26,"t":"他们要在这地上安然居住。我向四围恨恶他们的众人施行审判之后，他们要建造房屋，栽葡萄园，安然居住，他们就知道我是耶和华─他们的神。”","notes":[]}]},"29":{"heading":"斥责埃及","verses":[{"n":1,"t":"第十年十月十二日，耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要面向埃及王法老，向他和埃及全地说预言。","notes":[]},{"n":3,"t":"你要说，主耶和华如此说：埃及王法老，你这卧在自己江河中的海怪，看哪，我与你为敌。你曾说：‘我的尼罗河是我的，是我为自己造的。’","notes":[]},{"n":4,"t":"我必用钩子钩住你的腮颊，令江河中的鱼贴住你的鳞甲；我要把你和所有贴着鳞甲的鱼从你的江河中拉上来。","notes":[]},{"n":5,"t":"我要把你和江河中的鱼全都抛弃在旷野；你必仆倒在田间，无人收殓，无人掩埋。我已将你给了地上的走兽、空中的飞鸟作食物。","notes":[]},{"n":6,"t":"“埃及所有的居民必定知道我是耶和华。因为你已成为以色列家芦苇的杖；","notes":[]},{"n":7,"t":"他们用手掌一握，你就断裂，伤了他们的肩；他们靠着你，你却折断，闪了他们的腰。","notes":["“闪了他们的腰”是根据七十士译本和其他古译本；原文是“稳住他们的腰”。"]},{"n":8,"t":"所以主耶和华如此说：我必使刀剑临到你，把人与牲畜从你中间剪除。","notes":[]},{"n":9,"t":"埃及地必荒芜废弃，他们就知道我是耶和华。“因为法老说‘尼罗河是我的，是我所造的’，","notes":[]},{"n":10,"t":"所以，看哪，我必与你和你的江河为敌，使埃及地，从密夺到色弗尼，直到古实边界，全然废弃荒芜。","notes":["“古实”包括苏丹的大部分和埃塞俄比亚的一部分。"]},{"n":11,"t":"人的脚不经过，兽的蹄也不经过，四十年之久无人居住。","notes":[]},{"n":12,"t":"我要使埃及地成为荒芜中最荒芜的地，使它的城镇变为荒废中最荒废的城镇，共四十年之久。我必将埃及人分散到列国，四散在列邦。","notes":[]},{"n":13,"t":"“主耶和华如此说：满了四十年后，我必招聚分散在万民中的埃及人。","notes":[]},{"n":14,"t":"我要令埃及被掳的人归回，使他们回到本地巴特罗。在那里，他们必成为弱小的国家，","notes":[]},{"n":15,"t":"成为列国中最低微的，不再自高于列邦之上。我必使他们变为小国，不再辖制列邦。","notes":[]},{"n":16,"t":"埃及必不再作以色列家的倚靠，却使以色列家想起他们仰赖埃及的罪。他们就知道我是主耶和华。”","notes":[]},{"n":17,"t":"第二十七年正月初一，耶和华的话临到我，说：","notes":[],"heads":["尼布甲尼撒将征服埃及"]},{"n":18,"t":"“人子啊，巴比伦王尼布甲尼撒令他的军兵大力攻打推罗，以致头都光秃，肩都磨破；然而他和军兵虽然为攻打推罗花这么多力气，却没有从那里得到什么犒赏。","notes":[]},{"n":19,"t":"所以主耶和华如此说：我要将埃及地赐给巴比伦王尼布甲尼撒；他必掳掠埃及的财富，抢夺它的掳物，掳掠它的掠物，用以犒赏他的军兵。","notes":[]},{"n":20,"t":"我将埃及地赐给他，犒赏他，因他们为我效劳。这是主耶和华说的。","notes":[]},{"n":21,"t":"“当那日，我必使以色列家壮大，又必使你─以西结在他们中间开口；他们就知道我是耶和华。”","notes":["“壮大”：原文是“角长出来”。"]}]},"30":{"heading":"耶和华惩罚埃及","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要说预言；你要说，主耶和华如此说：哀哉这日！你们应当哭号，","notes":[]},{"n":3,"t":"因为日子近了，耶和华的日子临近了；那是密云之日，是列国受罚之期。","notes":["原文没有“受罚”。"]},{"n":4,"t":"必有刀剑临到埃及；被杀的人仆倒在埃及时，古实人颤惊不已。埃及的财富遭掳掠，根基被拆毁。","notes":[]},{"n":5,"t":"古实人、弗人、路德人、混居的各族和古伯人，以及盟国的人都要与埃及人一同倒在刀下。","notes":[]},{"n":6,"t":"“耶和华如此说：扶助埃及的必倾倒，埃及骄傲的权势必降为卑，从密夺到色弗尼，人必倒在刀下。这是主耶和华说的。","notes":[]},{"n":7,"t":"埃及成为荒凉中最荒凉的国，它的城镇变为荒废中最荒废的城镇。","notes":[]},{"n":8,"t":"我在埃及放火，帮助埃及的，都遭灭绝；那时，他们就知道我是耶和华。","notes":[]},{"n":9,"t":"“到那日，必有使者从我面前乘船出去，使安逸无虑的古实人惊惧；当埃及遭难的日子，痛苦也必临到他们。看哪，这事临近了！","notes":[]},{"n":10,"t":"“主耶和华如此说：我要藉巴比伦王尼布甲尼撒的手除灭埃及的军队。","notes":[]},{"n":11,"t":"他和随从他的人，就是列国中凶暴的人，要前来毁灭这地，拔刀攻击埃及，使遍地布满被杀的人。","notes":[]},{"n":12,"t":"我要使江河干涸，将这地卖在恶人手中；我要藉外国人的手，使这地和其中所充满的变为荒芜；这是我─耶和华说的。","notes":[]},{"n":13,"t":"“主耶和华如此说：我要毁灭偶像，从挪弗除掉神像；不再有君王出自埃及地，我要使埃及地的人惧怕。","notes":["“挪弗”就是埃及的孟斐斯；下同。"]},{"n":14,"t":"我必令巴特罗荒凉，在琐安放火，向挪施行审判。","notes":["“挪”就是埃及的底比斯；下同。"]},{"n":15,"t":"我要将我的愤怒倾倒在训，埃及的堡垒上，要剪除挪的众民。","notes":[]},{"n":16,"t":"我必在埃及放火，训必大大痛苦，挪被攻破，挪弗终日遭敌侵袭。","notes":[]},{"n":17,"t":"亚文和比．伯实的年轻人必倒在刀下，这些城镇将被掳掠。","notes":[]},{"n":18,"t":"我在答比匿折断埃及的轭，使它骄傲的权势止息。那时，日光必退去；至于这城，必有密云遮蔽，邻近的城镇也遭掳掠。","notes":["“轭”：有古卷和七十士译本是“权杖”。","“邻近的城镇”：原文直译“其中的众女子”。"]},{"n":19,"t":"我要如此向埃及施行审判，他们就知道我是耶和华。”","notes":[]},{"n":20,"t":"第十一年正月初七，耶和华的话临到我，说：","notes":[],"heads":["埃及王的崩溃"]},{"n":21,"t":"“人子啊，我已折断埃及王法老的一只膀臂；看哪，无人为他敷药，也无人为他包扎绷带，使他有力持刀。","notes":[]},{"n":22,"t":"因此，主耶和华如此说：看哪，我与埃及王法老为敌，要折断他的膀臂，折断强壮的和已受伤的，使刀从他手中掉落。","notes":[]},{"n":23,"t":"我必将埃及人分散到列国，四散在列邦。","notes":[]},{"n":24,"t":"我要使巴比伦王的膀臂有力，把我的刀交在他手中；却要折断法老的膀臂，使他在巴比伦王面前呻吟，如同被杀的人一样。","notes":[]},{"n":25,"t":"我要使巴比伦王的膀臂强壮，法老的膀臂却要下垂；当我把我的刀交在巴比伦王手中时，他要举刀攻击埃及地，他们就知道我是耶和华。","notes":[]},{"n":26,"t":"我必将埃及人分散到列国，四散在列邦；他们就知道我是耶和华。”","notes":[]}]},"31":{"heading":"高耸的香柏树","verses":[{"n":1,"t":"第十一年三月初一，耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要对埃及王法老和他的军队说：论到你的强盛，谁能与你相比呢？","notes":[]},{"n":3,"t":"看哪，亚述是黎巴嫩的香柏树，枝条荣美，荫密如林，极其高大，树顶高耸入云。","notes":[]},{"n":4,"t":"众水使它生长，深水使它长高；所栽之地有江河环绕，汊出的水道流至田野的树木。","notes":[]},{"n":5,"t":"所以它高大超过田野的树木；生长时因水源丰沛，枝子繁多，枝条增长。","notes":[]},{"n":6,"t":"空中所有的飞鸟在枝子上搭窝，野地所有的走兽在枝条下生子，所有的大国也在它的荫下居住。","notes":[]},{"n":7,"t":"它树大枝长，极为荣美，因它的根在众水之旁。","notes":[]},{"n":8,"t":"神园中的香柏树不能遮蔽它；松树不及它的枝子，枫树不及它的枝条，神园中的树都没有它荣美。","notes":[]},{"n":9,"t":"我使它枝条繁多，极为荣美；在神的园中，伊甸所有的树都嫉妒它。”","notes":[]},{"n":10,"t":"所以主耶和华如此说：“因它高大，树顶高耸入云，心高气傲，","notes":["“它”是根据古译本；原文是“你”。"]},{"n":11,"t":"我要把它交给列国中强人的手里，他们必定按它的罪恶惩治它。我已经驱逐它。","notes":["“我要把它交给”：有古卷和七十士译本是“我已把它交给”。"]},{"n":12,"t":"外国人，就是列国中凶暴的人，已把它砍断抛弃。它的枝条掉落山间和一切谷中，枝子折断，落在地上一切河道。地上的万民都离开它的遮荫，抛弃了它。","notes":[]},{"n":13,"t":"空中的飞鸟都栖身在掉落的树干上，野地的走兽也都躺卧在它的枝条中。","notes":[]},{"n":14,"t":"为了要使水边的树木枝干不再长高，树顶也不再高耸入云；那些得水滋润的，不再屹立于其中。因为它们和下到地府的人一起，都被交与死亡，到了地底下。”","notes":[]},{"n":15,"t":"主耶和华如此说：“它坠落阴间的那日，我为它遮盖深渊，拦住江河，使众水停流，以表哀悼。我使黎巴嫩为它悲哀，田野的树木都因它枯萎。","notes":[]},{"n":16,"t":"我把它扔到阴间，与下到地府的人一同坠落。那时，列国听见坠落的响声就震惊；伊甸一切的树木，就是黎巴嫩中得水滋润、最佳最美的树，在地底下都得了安慰。","notes":[]},{"n":17,"t":"这些树也要与它同下阴间，到被刀所杀的人那里；它们曾作它的膀臂，在列国中曾居住在它的荫下。","notes":["“它的膀臂”：原文另译和七十士译本是“它的后裔”。"]},{"n":18,"t":"在这样的荣耀与威势中，伊甸树木有谁能与你相比呢？然而你要与伊甸的树木一同到地底下；在未受割礼的人中，与被刀所杀的人一同躺下。“法老和他的军队正是如此。这是主耶和华说的。”","notes":[]}]},"32":{"heading":"以海怪比埃及王","verses":[{"n":1,"t":"第十二年十二月初一，耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要为埃及王法老作哀歌，说：你在列国中，如同少壮狮子，却像海里的海怪，冲出江河，以爪搅动诸水，使江河浑浊。","notes":[]},{"n":3,"t":"主耶和华如此说：许多民族聚集时，我要将我的网撒在你身上，他们要把你拉上来。","notes":[]},{"n":4,"t":"我要把你丢在地上，抛在田野，使空中的飞鸟落在你身上，遍地的野兽因你得以饱足。","notes":[]},{"n":5,"t":"我要将你的肉丢在山间，用你巨大的尸首填满山谷。","notes":["“巨大的尸首”：原文另译“腐烂的尸首”。"]},{"n":6,"t":"我要以你所流的血浸透大地，漫过山顶，溢满河道。","notes":[]},{"n":7,"t":"我毁灭你时，要遮蔽诸天，使众星昏暗；我必以密云遮掩太阳，月亮也不放光。","notes":[]},{"n":8,"t":"我要使天上发亮的光体在你上面变为昏暗，使你的地也变为黑暗。这是主耶和华说的。","notes":[]},{"n":9,"t":"“我使你在列国，在你所不认识的列邦中灭亡。那时，我必使许多民族的心因你愁烦。","notes":["“灭亡”：七十士译本是“被掳”。"]},{"n":10,"t":"当我在他们面前举起我的刀，我要使许多民族因你惊恐，他们的君王也必因你极其恐慌。在你仆倒的日子，他们各人为自己的性命时时战兢。","notes":[]},{"n":11,"t":"主耶和华如此说：巴比伦王的刀必临到你。","notes":[]},{"n":12,"t":"我必藉勇士的刀使你的军队仆倒；这些勇士都是列国中凶暴的人。他们必使埃及的骄傲归于无有，埃及的军队必被灭绝。","notes":[]},{"n":13,"t":"我要除灭众水旁一切的走兽，人的脚必不再搅浑这水，兽的蹄也不搅浑这水。","notes":[]},{"n":14,"t":"那时，我必使他们的水澄清，使他们的江河像油缓流。这是主耶和华说的。","notes":[]},{"n":15,"t":"我使埃及地荒废，使这地空无一物，又击杀其中所有的居民；那时，他们就知道我是耶和华。","notes":[]},{"n":16,"t":"“这是一首为人所吟唱的哀歌；列国的女子要唱这哀歌，她们要为埃及和它的军队唱这哀歌。这是主耶和华说的。”","notes":[]},{"n":17,"t":"第十二年某月十五日，耶和华的话临到我，说：","notes":["“某月”：七十士译本是“正月”。"],"heads":["为埃及哀号"]},{"n":18,"t":"“人子啊，你要为埃及的军队哀号，把他们和强盛之国一同扔到地底下，与那些下到地府的人在一起。","notes":["“强盛之国”：原文直译“强盛之国的女子”。"]},{"n":19,"t":"‘你的美丽胜过谁呢？坠落吧，与未受割礼的人躺在一起！’","notes":[]},{"n":20,"t":"他们要仆倒在被刀所杀的人当中。埃及被交给刀剑，人要把它和它的军队拉走。","notes":[]},{"n":21,"t":"强壮的勇士要在阴间对埃及王和他的盟友说话；他们未受割礼，被刀剑所杀，已经坠落躺下。","notes":[]},{"n":22,"t":"“亚述和它的全军在那里，四围都是坟墓；他们全都是被杀倒在刀下的人。","notes":[]},{"n":23,"t":"他们的坟墓在地府极深之处，它的众军环绕它的坟墓，他们全都是被杀倒在刀下的人，曾在活人之地使人惊恐。","notes":[]},{"n":24,"t":"“以拦在那里，它的全军环绕它的坟墓；他们全都是被杀倒在刀下、未受割礼而到地底下的，曾在活人之地使人惊恐；他们与下到地府的人一同担当羞辱。","notes":[]},{"n":25,"t":"人为它和它的军队在被杀的人中设立床榻，四围都是坟墓；他们都是未受割礼被刀所杀的，曾在活人之地使人惊恐；他们与下到地府的人一同担当羞辱。以拦已列在被杀的人中。","notes":[]},{"n":26,"t":"“米设、土巴和他们的全军都在那里，四围都是坟墓；他们都是未受割礼被刀所杀的，曾在活人之地使人惊恐。","notes":[]},{"n":27,"t":"他们不得与那未受割礼仆倒的勇士躺在一起；这些勇士带着兵器下到阴间，头枕着刀剑，骨头带着本身的罪孽，曾在活人之地使人惊恐。","notes":["“那未受割礼”：七十士译本和其他古译本是“古代”。"]},{"n":28,"t":"法老啊，你必与未受割礼的人一起毁灭，与被刀所杀的人躺在一起。","notes":[]},{"n":29,"t":"“以东在那里，它的君王和所有官长虽然英勇，还是与被刀所杀的人同列；他们必与未受割礼的和下到地府的人躺在一起。","notes":[]},{"n":30,"t":"“在那里有北方的众王子和所有的西顿人，全都与被杀的人一同下去。他们虽然英勇，使人惊恐，还是蒙羞。他们未受割礼，和被刀所杀的人躺在一起，与下到地府的人一同担当羞辱。","notes":[]},{"n":31,"t":"“法老看见他们，就为他的军兵，就是被刀所杀属法老的人和他的全军感到安慰。这是主耶和华说的。","notes":[]},{"n":32,"t":"我任凭法老在活人之地使人惊恐，法老和他的军兵必躺在未受割礼和被刀所杀的人中。这是主耶和华说的。”","notes":[]}]},"33":{"heading":"神派以西结作守望者","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要吩咐本国的百姓，对他们说：我使刀剑临到哪一国，哪一国的百姓从他们中间选立一人，作为守望者。","notes":[]},{"n":3,"t":"守望者见刀剑临到那地，若吹角警戒百姓，","notes":[]},{"n":4,"t":"有人听见角声却不受警戒，刀剑来除灭了他，这人的血必归到自己头上。","notes":[]},{"n":5,"t":"他听见角声，不受警戒，他的血必归到自己身上；他若受警戒，就救了自己的命。","notes":[]},{"n":6,"t":"倘若守望者见刀剑临到，却不吹角，以致百姓未受警戒，刀剑来杀了他们中间的一个人，这人虽然因自己的罪孽而死，我却要从守望者的手里讨他的血债。","notes":[]},{"n":7,"t":"“人子啊，我照样立你作以色列家的守望者；你要听我口中的话，替我警戒他们。","notes":[]},{"n":8,"t":"我对恶人说：‘恶人哪，你必要死！’你若不开口警戒恶人，使他离开所行的道，这恶人必因自己的罪孽而死，我却要从你手里讨他的血债。","notes":[]},{"n":9,"t":"但是你，你若警戒恶人，叫他离弃所行的道，他仍不转离，他必因自己的罪孽而死，你却救了自己的命。”","notes":[]},{"n":10,"t":"“人子啊，你要对以色列家说：你们曾这样说：‘我们的过犯罪恶在自己身上，我们必因此消灭，怎能存活呢？’","notes":[],"heads":["个人的责任"]},{"n":11,"t":"你要对他们说，主耶和华说：我指着我的永生起誓，我断不喜悦恶人死亡，惟喜悦恶人转离他所行的道而存活。以色列家啊，你们回转，回转离开恶道吧！何必死亡呢？","notes":[]},{"n":12,"t":"人子啊，你要对本国的百姓说：义人的义，在他犯罪之日不能救他；至于恶人的恶，在他转离恶行之日不会使他倾倒；义人在他犯罪之日不能因自己的义存活。","notes":[]},{"n":13,"t":"我对义人说：‘你必存活！’他若倚靠自己的义作恶，所行的义就不被记念；他必因所作的恶死亡。","notes":[]},{"n":14,"t":"我对恶人说：‘你必死亡！’他若转离他的罪恶，行公平公义的事；","notes":[]},{"n":15,"t":"恶人若归还抵押品，归回所抢夺的东西，遵行生命的律例，不再作恶；他必存活，不致死亡。","notes":[]},{"n":16,"t":"他所犯的一切罪必不被记念；他行了公平公义的事，必要存活。","notes":[]},{"n":17,"t":"“你本国的百姓说：‘主的道不公平。’其实他们，他们的道才是不公平。","notes":[]},{"n":18,"t":"义人转离自己的义作恶，他必因此而死亡。","notes":[]},{"n":19,"t":"恶人转离他的恶，行公平公义的事，他必因此而存活。","notes":[]},{"n":20,"t":"你们还说：‘主的道不公平。’以色列家啊，我必按你们各人所行的审判你们。”","notes":[]},{"n":21,"t":"我们被掳后第十二年的十月初五，有人从耶路撒冷逃到我这里，说：“城已被攻破。”","notes":[],"heads":["耶路撒冷陷落的消息"]},{"n":22,"t":"逃来的人到的前一天晚上，耶和华的手按在我身上，开我的口。第二天早晨，等那人来到我这里，我的口就开了，不再说不出话来。","notes":[]},{"n":23,"t":"耶和华的话临到我，说：","notes":[],"heads":["百姓的罪"]},{"n":24,"t":"“人子啊，住在以色列荒废之地的人说：‘亚伯拉罕一人能得这地为业，我们人数众多，这地更是给我们为业的。’","notes":[]},{"n":25,"t":"所以你要对他们说，主耶和华如此说：你们吃带血的食物，向偶像举目，并且流人的血，你们还能得这地为业吗？","notes":[]},{"n":26,"t":"你们倚靠自己的刀剑行可憎的事，人人污辱邻舍的妻，你们还能得这地为业吗？","notes":[]},{"n":27,"t":"你要对他们这样说，主耶和华如此说：我指着我的永生起誓，在废墟的，必倒在刀下；在田野的，必交给野兽吞吃；在堡垒和洞中的，必遭瘟疫而死。","notes":[]},{"n":28,"t":"我必使这地荒废荒凉，它骄傲的权势也必止息；以色列的山都必荒废，无人经过。","notes":[]},{"n":29,"t":"我因他们所做一切可憎的事，使地荒废荒凉；那时，他们就知道我是耶和华。”","notes":[]},{"n":30,"t":"“你，人子啊，你本国的百姓在城墙旁边、在房屋门口谈论你。弟兄对弟兄彼此说：‘来吧！听听有什么话从耶和华而出。’","notes":[],"heads":["先知传讲的信息"]},{"n":31,"t":"他们如同百姓前来，来到你这里，坐在你面前仿佛是我的子民。他们听了你的话，却不实行；因为他们口里说爱，心却追随财利。","notes":[]},{"n":32,"t":"看哪，他们看你如同一个唱情歌的人，声音优雅、善于奏乐；他们听了你的话，却不实行。","notes":["“一个唱情歌的人”：原文是“一首情歌”。"]},{"n":33,"t":"看哪，这话就要应验；应验时，他们就知道在他们中间有了先知。”","notes":[]}]},"34":{"heading":"以色列的牧人","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要向以色列的牧人说预言，对他们说，主耶和华如此说：祸哉！以色列的牧人只知牧养自己。牧人岂不当牧养群羊吗？","notes":[]},{"n":3,"t":"你们吃肥油、穿羊毛、宰杀肥羊，却不牧养群羊。","notes":["“肥油”：七十士译本和其他古译本是“奶”。"]},{"n":4,"t":"瘦弱的，你们不调养；有病的，你们不医治；受伤的，你们未包扎；被逐的，你们不去领回；失丧的，你们不寻找；却用暴力严严地辖制它们。","notes":["“用暴力...它们”：七十士译本是“你们严严地辖制强壮者”。"]},{"n":5,"t":"它们因无牧人就分散；既分散，就成为一切野兽的食物。","notes":[]},{"n":6,"t":"我的羊流落众山之间和各高冈上，分散在全地，无人去寻，无人去找。","notes":[]},{"n":7,"t":"“所以，你们这些牧人要听耶和华的话。","notes":[]},{"n":8,"t":"主耶和华说：我指着我的永生起誓，我的羊因无牧人就成为掠物，也作了一切野兽的食物。我的牧人不寻找我的羊；这些牧人只知喂养自己，并不喂养我的羊。","notes":[]},{"n":9,"t":"所以你们这些牧人要听耶和华的话。","notes":[]},{"n":10,"t":"主耶和华如此说：看哪，我必与牧人为敌，从他们手里讨回我的羊，使他们不再牧放群羊；牧人也不再喂养自己。我必救我的羊脱离他们的口，不再作他们的食物。”","notes":[]},{"n":11,"t":"“主耶和华如此说：‘看哪，我必亲自寻找我的羊，将它们寻见。","notes":[],"heads":["好牧人"]},{"n":12,"t":"牧人在羊群四散的日子怎样寻找他的羊，我必照样寻找我的羊。这些羊在密云黑暗的日子散在各处，我要从那里救回它们。","notes":[]},{"n":13,"t":"我要从万民中领出它们，从各国聚集它们，引领它们归回故土。我要在以色列山上，在一切溪水旁边，在境内所有可居住的地牧养它们。","notes":[]},{"n":14,"t":"我要在肥美的草场牧养它们。它们的圈必在以色列高处的山上，它们必躺卧在佳美的圈内，在以色列山肥美的草场上吃草。","notes":[]},{"n":15,"t":"我要亲自牧养我的群羊，使它们得以躺卧。这是主耶和华说的。","notes":[]},{"n":16,"t":"失丧的，我必寻找；被逐的，我必领回；受伤的，我必包扎；有病的，我必医治；只是肥的壮的，我要除灭；我必秉公牧养它们。’","notes":["“我要除灭”：七十士译本和其他古译本是“我要看管”。"]},{"n":17,"t":"“我的羊群哪，论到你们，主耶和华如此说：看哪，我要在羊与羊中间、公绵羊与公山羊中间施行审判。","notes":[]},{"n":18,"t":"你们在肥美的草场上吃草还以为是小事吗？竟用你们的脚践踏剩下的草；你们喝了清水，竟用你们的脚搅浑剩下的水。","notes":[]},{"n":19,"t":"至于我的羊，只能吃你们所践踏的，喝你们所搅浑的。","notes":[]},{"n":20,"t":"“所以，主耶和华对它们如此说：看哪，我要亲自在肥羊和瘦羊中间施行审判。","notes":[]},{"n":21,"t":"因为你们用侧边用肩推挤一切瘦弱的羊，又用角抵撞，使它们四散在外；","notes":[]},{"n":22,"t":"所以，我要拯救我的群羊，它们必不再作掠物；我也要在羊和羊中间施行审判。","notes":[]},{"n":23,"t":"我必在他们之上立一牧人，就是我的仆人大卫，牧养它们；他必牧养他们，作他们的牧人。","notes":["“一牧人”：七十士译本的一份抄本是“另一牧人”。"]},{"n":24,"t":"我─耶和华必作他们的神，我的仆人大卫要在他们中间作王。这是我─耶和华说的。","notes":[]},{"n":25,"t":"“我要与他们立平安的约，使恶兽从境内断绝；他们在旷野也能安然居住，在树林也能躺卧。","notes":[]},{"n":26,"t":"我要使他们和我山冈的四围蒙福；我也必叫时雨落下，使福如甘霖降下。","notes":[]},{"n":27,"t":"田野的树木必结果子，地也必有出产；他们要在自己的土地安然居住。我折断他们所负的轭，救他们脱离奴役他们之人的手；那时，他们就知道我是耶和华。","notes":[]},{"n":28,"t":"他们必不再作外邦人的掠物，地上的野兽也不再吞吃他们；他们却要安然居住，无人使他们惊吓。","notes":[]},{"n":29,"t":"我必为他们建立闻名的栽种之地；他们在境内就不再为饥荒所灭，也不再受列国的羞辱。","notes":["“闻名的”：七十士译本是“平安的”。"]},{"n":30,"t":"他们必知道我─耶和华他们的神与他们同在，并知道他们，以色列家，是我的子民。这是主耶和华说的。","notes":[]},{"n":31,"t":"你们这些人，你们是我的羊，我草场上的羊；我是你们的神。这是主耶和华说的。”","notes":[]}]},"35":{"heading":"神惩罚以东","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要面向西珥山，向它说预言，","notes":[]},{"n":3,"t":"对它说，主耶和华如此说：西珥山，看哪，我与你为敌，必伸手攻击你，使你荒凉荒废。","notes":[]},{"n":4,"t":"我必使你的城镇变为废墟，使你成为荒凉；你就知道我是耶和华。","notes":[]},{"n":5,"t":"因为你永怀仇恨，在以色列人遭遇灾难、罪孽到了尽头时，把他们交给刀剑，","notes":[]},{"n":6,"t":"所以主耶和华说：我指着我的永生起誓，我必使你遭遇血的报应，血必追赶你；你既不恨恶血，血必追赶你。","notes":[]},{"n":7,"t":"我要使西珥山荒凉荒废，把来往经过的人从它那里剪除。","notes":[]},{"n":8,"t":"我要使西珥山布满被杀的人。被刀杀的要倒在小山和山谷，并一切的溪水中。","notes":[]},{"n":9,"t":"我必使你永远荒凉，使你的城镇无人居住，你们就知道我是耶和华。","notes":[]},{"n":10,"t":"“因为你曾说‘这二国、这二邦必归我，我们必得为业’，其实耶和华仍在那里；","notes":[]},{"n":11,"t":"所以主耶和华说：我指着我的永生起誓，我必照你因仇恨向他们发的怒气和嫉妒对待你；我审判你的时候，要在他们中间显明自己。","notes":[]},{"n":12,"t":"你必知道我─耶和华已听见你一切凌辱的话，是针对以色列群山说的：‘这些山荒凉了，它们是给我们作食物的。’","notes":[]},{"n":13,"t":"你们用口向我说夸大的话，增多与我敌对的话，我都听见了。","notes":[]},{"n":14,"t":"主耶和华如此说：全地欢乐的时候，我必使你荒凉。","notes":[]},{"n":15,"t":"你怎样因以色列家的地业荒凉而喜乐，我也要照你所做的对待你。西珥山哪，你和以东全地都必荒凉；人就知道我是耶和华。”","notes":["“人就知道”：七十士译本是“你就知道”。"]}]},"36":{"heading":"神赐福给以色列","verses":[{"n":1,"t":"“人子啊，你要对以色列群山说预言：以色列群山哪，要听耶和华的话。","notes":[]},{"n":2,"t":"主耶和华如此说，因仇敌说：‘啊哈！这古老的丘坛都归我们为业了！’","notes":[]},{"n":3,"t":"所以你要预言，说：主耶和华如此说：因为敌人使你荒凉，四围践踏你，要叫你归其余的列国为业，使你们成为各族的话柄与百姓的笑谈；","notes":[]},{"n":4,"t":"因此，以色列群山哪，要听主耶和华的话。对那遭四围其余列国占据、讥刺的大山小冈、水沟山谷、荒废之地、被弃之城，主耶和华如此说；","notes":[]},{"n":5,"t":"所以，主耶和华如此说：我因妒火中烧，就责备其余的列国和以东的众人。他们快乐满怀，心存恨恶，将我的地占为己有，视为被抛弃的掠物。","notes":[]},{"n":6,"t":"所以，你要指着以色列地说预言，对大山小冈、水沟山谷说，主耶和华如此说：看哪，我在妒忌和愤怒中宣布：因你们曾受列国的羞辱，","notes":[]},{"n":7,"t":"所以我起誓说，你们四围的列国要担当自己的羞辱。这是主耶和华说的。","notes":[]},{"n":8,"t":"“以色列群山哪，要长出枝条，为我子民以色列结出果子，因为他们即将来到。","notes":[]},{"n":9,"t":"看哪，我是帮助你们的，我要转向你们，使你们得以耕作栽种。","notes":[]},{"n":10,"t":"我要使以色列全家在你们那里人数增多，城镇有人居住，废墟重新建造。","notes":[]},{"n":11,"t":"我要使人丁和牲畜在你们那里加增，他们必生养众多。我要使你们那里像以前一样有人居住，并要赐福，比先前更多；你们就知道我是耶和华。","notes":[]},{"n":12,"t":"我要使我的子民以色列在你们那里行走，他们必得你为业；你就成为他们的产业，不再使他们丧失儿女。","notes":[]},{"n":13,"t":"主耶和华如此说，因为人对你们说‘你是吞吃人的，又使国民丧失儿女’，","notes":[]},{"n":14,"t":"所以你必不再吞吃人，也不再使国民丧失儿女。这是主耶和华说的。","notes":[]},{"n":15,"t":"我使你不再听见列国的羞辱；你必不再受万民的辱骂，也不再使国民绊跌。这是主耶和华说的。”","notes":[]},{"n":16,"t":"耶和华的话临到我，说：","notes":[],"heads":["以色列的新生活"]},{"n":17,"t":"“人子啊，以色列家住本地的时候，所作所为使那地玷污。他们的行为在我面前，好像妇人在经期中那样污秽。","notes":[]},{"n":18,"t":"所以我因他们在那地流人的血，且以偶像使那地玷污，就把我的愤怒倾倒在他们身上。","notes":[]},{"n":19,"t":"我将他们分散到列国，四散在列邦，按他们的所作所为惩罚他们。","notes":[]},{"n":20,"t":"他们到了所去的列国，使我的圣名被亵渎；因为人谈论他们说，这是耶和华的子民，却从耶和华的地出来。","notes":["“他们到了”是根据一些古卷和七十士译本；原文是“他到了”。"]},{"n":21,"t":"但我顾惜我的圣名，就是以色列家在所到的列国中亵渎的。","notes":[]},{"n":22,"t":"“所以，你要对以色列家说，主耶和华如此说：以色列家啊，我做这事不是为你们，而是为了我的圣名，就是你们在所到的列国中亵渎的。","notes":[]},{"n":23,"t":"我要使我至大的名显为圣；这名在列国中已遭亵渎，是你们在他们中间亵渎的。我在他们眼前，在你们身上显为圣的时候，他们就知道我是耶和华。这是主耶和华说的。","notes":[]},{"n":24,"t":"我必从列国带领你们，从列邦聚集你们，领你们回到本地。","notes":[]},{"n":25,"t":"我必洒清水在你们身上，你们就洁净了。我要洁净你们，使你们脱离一切的污秽，弃绝一切的偶像。","notes":[]},{"n":26,"t":"我也要赐给你们一颗新心，将新灵放在你们里面，又从你们的肉体中除掉石心，赐给你们肉心。","notes":[]},{"n":27,"t":"我必将我的灵放在你们里面，使你们顺从我的律例，谨守遵行我的典章。","notes":[]},{"n":28,"t":"你们必住在我所赐给你们祖先之地；你们要作我的子民，我要作你们的神。","notes":[]},{"n":29,"t":"我要救你们脱离一切的污秽，也要令五谷丰登，使你们不再遭遇饥荒。","notes":[]},{"n":30,"t":"我要使树木多结果子，田地多出土产，好叫你们不再因饥荒被列国凌辱。","notes":[]},{"n":31,"t":"那时，你们必追念自己的恶行和不好的作为，就因你们的罪孽和可憎的事厌恶自己。","notes":[]},{"n":32,"t":"你们要知道，我这样做不是为你们。以色列家啊，你们当为自己的行为抱愧蒙羞。这是主耶和华说的。","notes":[]},{"n":33,"t":"“主耶和华如此说：我洁净你们，使你们脱离一切罪孽的日子，必使城镇有人居住，废墟重新建造。","notes":[]},{"n":34,"t":"这荒芜的土地，曾被过路的人看为荒芜，现今却得以耕种。","notes":[]},{"n":35,"t":"他们必说：‘这荒芜之地，现在成了像伊甸园一样；这荒凉、荒废、毁坏的城镇，现今坚固，有人居住。’","notes":[]},{"n":36,"t":"那时，在你们四围其余的列国必知道，我─耶和华修造那毁坏之处，开垦那荒芜之地。我─耶和华说了这话，就必成就。","notes":[]},{"n":37,"t":"“主耶和华如此说：我要回应以色列家的求问，成全他们，增添他们的人数，使他们多如羊群。","notes":[]},{"n":38,"t":"在耶路撒冷守节时，作为祭物所献的羊群有多少，照样，荒凉的城镇必为人群所充满；他们就知道我是耶和华。”","notes":[]}]},"37":{"heading":"枯骨复苏","verses":[{"n":1,"t":"耶和华的手按在我身上。耶和华藉着他的灵带我出去，把我放在平原中，平原遍满骸骨。","notes":[]},{"n":2,"t":"他使我从骸骨的四围经过，看哪，平原上面的骸骨甚多，看哪，极其枯干。","notes":[]},{"n":3,"t":"他对我说：“人子啊，这些骸骨能活过来吗？”我说：“主耶和华啊，你是知道的。”","notes":[]},{"n":4,"t":"他又对我说：“你要向这些骸骨说预言，对它们说：枯干的骸骨啊，要听耶和华的话。","notes":[]},{"n":5,"t":"主耶和华对这些骸骨如此说：‘看哪，我必使气息进入你们里面，你们就要活过来。","notes":["“气息”或译“灵”；下同。"]},{"n":6,"t":"我要给你们加上筋，长出肉，又给你们包上皮，使气息进入你们里面，你们就要活过来；你们就知道我是耶和华。’”","notes":[]},{"n":7,"t":"于是，我遵命说预言。正说预言的时候，有响声，看哪，有地震；骨与骨彼此接连。","notes":[]},{"n":8,"t":"我观看，看哪，骸骨上面有筋，长了肉，又包上皮，只是里面还没有气息。","notes":[]},{"n":9,"t":"耶和华对我说：“人子啊，你要说预言，向风说预言。你要说，耶和华如此说：气息啊，要从四方而来，吹在这些被杀的人身上，使他们活过来。”","notes":["“风”或译“灵”。","“方”：原文是“风”。"]},{"n":10,"t":"于是我遵命说预言，气息就进入骸骨，骸骨就活过来，并且用脚站起来，成为极大的军队。","notes":[]},{"n":11,"t":"他对我说：“人子啊，这些骸骨就是以色列全家。他们说：‘看哪，我们的骨头枯干了，我们的指望失去了，我们灭绝净尽了！’","notes":[]},{"n":12,"t":"所以你要说预言，对他们说，主耶和华如此说：我的子民，看哪，我要打开你们的坟墓，把你们带出坟墓，领你们进入以色列地。","notes":[]},{"n":13,"t":"我的子民哪，我打开你们的坟墓，把你们带出坟墓时，你们就知道我是耶和华。","notes":[]},{"n":14,"t":"我必将我的灵放在你们里面，你们就要活过来。我把你们安置在本地，你们就知道我─耶和华说了这话，就必成就。这是耶和华说的。”","notes":[]},{"n":15,"t":"耶和华的话临到我，说：","notes":[],"heads":["犹大和以色列合一"]},{"n":16,"t":"“人子啊，你要取一根木杖，在其上写‘为犹大和他的盟友以色列人’；又取一根木杖，在其上写‘为约瑟，就是以法莲的杖，和他的盟友以色列全家’。","notes":["“一根”：七十士译本是“第二根”；有古译本是“另一根”。"]},{"n":17,"t":"你要将这两根木杖彼此相接，连成一根，使它们在你手中合而为一。","notes":[]},{"n":18,"t":"当你本国的子民对你说：‘你这是什么意思，你不指示我们吗？’","notes":[]},{"n":19,"t":"你就对他们说，主耶和华如此说：看哪，我要将约瑟和他的盟友以色列支派的杖，就是在以法莲手中的那根，与犹大的杖接连成为一根，在我手中合而为一。","notes":[]},{"n":20,"t":"你要在他们眼前，把写了字的那两根杖拿在手中，","notes":[]},{"n":21,"t":"对他们说，主耶和华如此说：看哪，我要从以色列人所到的列国带领他们，从四围聚集他们，领他们回到本地。","notes":[]},{"n":22,"t":"我要使他们在这地，在以色列群山上成为一国，必有一王作他们全体的王。他们不再成为二国，绝不再分为二国。","notes":[]},{"n":23,"t":"他们不再因偶像和可憎的物，并一切的罪过玷污自己。我却要救他们离开一切犯罪所住的地方；我要洁净他们，如此，他们要作我的子民，我要作他们的神。","notes":["“犯罪所住的地方”：七十士译本是“所犯堕落的罪”。"]},{"n":24,"t":"“我的仆人大卫要作他们的王；他们全体必归一个牧人。他们必顺从我的典章，谨守遵行我的律例。","notes":[]},{"n":25,"t":"他们要住在我赐给我仆人雅各的地上，就是你们列祖所住之地。他们和他们的子孙，并子孙的子孙，都永远住在那里。我的仆人大卫要作他们的王，直到永远；","notes":[]},{"n":26,"t":"并且我要与他们立平安的约，作为永约。我要安顿他们，使他们人数增多，又在他们中间设立我的圣所，直到永远。","notes":[]},{"n":27,"t":"我的居所必在他们中间；我要作他们的神，他们要作我的子民。","notes":[]},{"n":28,"t":"我的圣所在以色列人中间直到永远，列国就知道是我─耶和华使以色列分别为圣。”","notes":[]}]},"38":{"heading":"耶和华使用歌革","verses":[{"n":1,"t":"耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“人子啊，你要面向玛各地的歌革，就是米设和土巴的大王，向他说预言。","notes":[]},{"n":3,"t":"你要说，主耶和华如此说：米设和土巴的大王歌革，看哪，我与你为敌。","notes":[]},{"n":4,"t":"我要把你掉转过来，用钩子钩住你的腮颊，把你和你的军兵、马匹、骑兵都带走。他们全都披挂整齐，成为大军，佩带大小盾牌，各人拿着刀剑；","notes":[]},{"n":5,"t":"他们当中有波斯人、古实人和弗人，都带着盾牌和头盔；","notes":[]},{"n":6,"t":"还有歌篾人和他的军队，北方极远的陀迦玛族和他的军队，这许多民族都跟着你。","notes":[]},{"n":7,"t":"“你和聚集到你那里的军队都要预备，预备妥当，你要作他们的守卫。","notes":[]},{"n":8,"t":"过了多日，你必被差派；到末后之年，你要来到那脱离刀剑、从列国召集回来的人所住之地，来到以色列常久荒凉的山上；他们都从列国中被领出，在那里安然居住。","notes":[]},{"n":9,"t":"你和你的全军，并跟随你的许多民族都要上来，如暴风刮来，如密云遮盖地面。","notes":[]},{"n":10,"t":"“主耶和华如此说：那时，你的心必起意念，图谋恶计，","notes":[]},{"n":11,"t":"说：‘我要上那无墙的乡村之地，到那安静的居民那里，他们无墙，无门、无闩，安然居住。","notes":[]},{"n":12,"t":"我去那里要抢财为掳物，夺货为掠物，反手攻击那从前荒凉、现在有人居住之地，又攻击那从列国招聚出来、得了牲畜财货、住在地的高处的百姓。’","notes":[]},{"n":13,"t":"示巴人、底但人、他施的商人和他们的少壮狮子都对你说：‘你来是要抢财为掳物吗？你聚集军队是要夺货为掠物，夺取金银，掳去牲畜、财货，抢夺许多财宝为掳物吗？’","notes":[]},{"n":14,"t":"“人子啊，你要因此说预言，对歌革说，主耶和华如此说：我的子民以色列安然居住时，你是知道的。","notes":["“你是知道的。”七十士译本是“你岂不是要兴起吗？”"]},{"n":15,"t":"你从你的地方，从北方极远处率领许多民族前来，他们都骑着马，是一队强而多的军兵。","notes":[]},{"n":16,"t":"歌革啊，你必上来攻击我的子民以色列，如密云遮盖地面。末后的日子，我必领你来攻击我的地，我藉你在列国眼前显为圣的时候，他们就要认识我。","notes":[]},{"n":17,"t":"主耶和华如此说：我在古时藉我仆人以色列众先知所说的，不就是你吗？他们在那些日子，多年说预言，我必领你来攻击以色列人。”","notes":["“不就是你吗？”七十士译本和其他古译本是“就是你。”"]},{"n":18,"t":"“主耶和华说：歌革上来攻击以色列地的时候，我的怒气要从鼻孔里发出。","notes":[],"heads":["耶和华惩罚歌革"]},{"n":19,"t":"我在妒忌和如火的烈怒中说：那日在以色列地必有大震动，","notes":[]},{"n":20,"t":"甚至海中的鱼、天空的鸟、野地的兽，和地上爬的各种爬行动物，并地面上的众人，因见我的面就都震动；山岭崩裂，陡岩塌陷，一切的墙都必坍塌。","notes":[]},{"n":21,"t":"我必令刀剑在我的众山攻击歌革；人要用刀剑杀害弟兄。这是主耶和华说的。","notes":[]},{"n":22,"t":"我要用瘟疫和血惩罚他。我也必降暴雨、大冰雹、火及硫磺在他和他的军队，并跟随他的许多民族身上。","notes":[]},{"n":23,"t":"我必显为大，显为圣，在许多国家眼前显明自己；他们就知道我是耶和华。”","notes":[]}]},"39":{"heading":"歌革的溃败","verses":[{"n":1,"t":"“你，人子啊，要向歌革说预言。你要说，主耶和华如此说：米设和土巴的大王歌革，看哪，我与你为敌。","notes":[]},{"n":2,"t":"我要把你调转过来，带领你，从北方极远的地方上来，带你到以色列的群山上。","notes":[]},{"n":3,"t":"我要打落你左手的弓，打掉你右手的箭。","notes":[]},{"n":4,"t":"你和你的全军，并跟随你的列国的人，都必倒在以色列的群山上。我要将你给各类攫食的飞鸟和野地的走兽作食物。","notes":[]},{"n":5,"t":"你必倒在田野，因为我曾说过，这是主耶和华说的。","notes":[]},{"n":6,"t":"我要降火在玛各和海岛安然居住的人身上，他们就知道我是耶和华。","notes":[]},{"n":7,"t":"“我要在我的子民以色列中彰显我的圣名，不容我的圣名再被亵渎，列国就知道我─耶和华是以色列中的圣者。","notes":[]},{"n":8,"t":"看哪，时候到了，必然成就，这就是我曾说过的日子。这是主耶和华说的。","notes":[]},{"n":9,"t":"“住以色列城镇的人要出去生火，用军器燃烧，就是大小盾牌、弓箭、棍棒、枪矛；用它们来烧火，直烧了七年。","notes":[]},{"n":10,"t":"他们不必从田野捡柴，也不必从森林伐木，因为他们要用这些军器烧火。他们要抢夺那抢夺他们的人，掳掠那掳掠他们的人。这是主耶和华说的。”","notes":[]},{"n":11,"t":"“当那日，我要把以色列境内、海东边的旅人谷给歌革在那里作坟地，阻挡了旅行的人。在那里，人要埋葬歌革和他的军兵，称那地为哈们．歌革谷。","notes":["“旅人谷”：原文另译“亚巴琳谷”，参民27．12。","“在那里作坟地”：七十士译本和其他古译本是“作有名的坟地”。","“旅行的人”：原文另译“亚巴琳人”。","“哈们．歌革谷”意思是“歌革军兵谷”；下同。"],"heads":["歌革的埋葬"]},{"n":12,"t":"以色列家的人要用七个月埋葬他们，好使那地洁净。","notes":[]},{"n":13,"t":"那地所有的百姓都来埋葬他们。当我得荣耀的日子，这事必叫百姓得名声。这是主耶和华说的。","notes":[]},{"n":14,"t":"他们要分派人专职巡查遍地，埋葬那遗留在地面上入侵者的尸首，好洁净全地。过了七个月，他们还要再巡查。","notes":[]},{"n":15,"t":"巡查的人要遍行全地，见有人的骸骨，就在旁边立一标记，等埋葬的人来将骸骨葬在哈们．歌革谷，","notes":[]},{"n":16,"t":"且有一城要取名为哈摩那。他们必这样洁净那地。","notes":["“哈摩那”意思是“军兵城”。"]},{"n":17,"t":"“你，人子啊，主耶和华如此说：你要向各类的飞鸟和野地的走兽说：你们要聚集，来吧，从四方聚集来吃我为你们准备的祭物，就是在以色列的群山上丰盛的祭物，叫你们吃肉、喝血。","notes":[]},{"n":18,"t":"你们要吃勇士的肉，喝地上领袖的血，如吃公绵羊、羔羊、公山羊、公牛；他们全都是巴珊的肥畜。","notes":[]},{"n":19,"t":"你们吃我为你们准备的祭物，必吃油脂直到饱了，喝血直到醉了。","notes":[]},{"n":20,"t":"你们要因我席上的马匹、骑兵、勇士和所有的战士而饱足。这是主耶和华说的。”","notes":[]},{"n":21,"t":"“我要在列国中彰显我的荣耀，万国就必看见我怎样把手加在他们身上，施行审判。","notes":[],"heads":["以色列的复兴"]},{"n":22,"t":"从那日以后，以色列家就知道我是耶和华─他们的神，","notes":[]},{"n":23,"t":"列国也必知道，以色列家被掳掠是因他们的罪孽。他们得罪我，我就转脸不顾他们，将他们交在敌人手中，使他们全都倒在刀下。","notes":[]},{"n":24,"t":"我照他们的污秽和罪过待他们，转脸不顾他们。","notes":[]},{"n":25,"t":"“所以主耶和华如此说：现在，我要使雅各被掳的人归回，要怜悯以色列全家，又为我的圣名发热心。","notes":[]},{"n":26,"t":"我将他们从万民中领回，从仇敌之地召来，在许多国家的眼前，在他们身上显为圣，他们在本地安然居住，无人使他们惊吓，那时，他们要担当自己的羞辱和干犯我的一切罪。","notes":["“担当”或译“忘记”。"],"end":27},{"n":28,"t":"我使他们被掳到列国，后又聚集他们回到本地，不再留一人在那里，那时他们就知道我是耶和华─他们的神。","notes":[]},{"n":29,"t":"我不再转脸不顾他们，因我已将我的灵浇灌以色列家。这是主耶和华说的。”","notes":[]}]},"40":{"heading":"新圣殿的异象","verses":[{"n":1,"t":"我们被掳的第二十五年，耶路撒冷城攻破后十四年，正在年初，某月初十，就在那一天，耶和华的手按在我身上，把我带到那里。","notes":[],"heads":["以西结被带到耶路撒冷"]},{"n":2,"t":"在神的异象中，他带我到以色列地，把我安置在一座极高的山上；在山的南边有仿佛一座城的建筑物。","notes":[]},{"n":3,"t":"他带我到那里，看哪，有一人面貌如铜，手拿麻绳和丈量的芦苇竿，站在门口。","notes":["“面貌”：原文是“形状”。"]},{"n":4,"t":"那人对我说：“人子啊，凡我所指示你的，你都要用眼看，用耳听，并要放在心上。我带你到这里来，为要指示你；凡你所见的，都要告诉以色列家。”","notes":[]},{"n":5,"t":"看哪，殿外四围有墙。那人手拿丈量的芦苇竿，长六肘，每肘再加一掌。他量围墙，宽一竿，高一竿。","notes":[],"heads":["东门"]},{"n":6,"t":"他到了朝东的门，就上台阶，量这门的门槛，宽一竿；这门槛宽一竿。","notes":[]},{"n":7,"t":"又有守卫房，每间长一竿，宽一竿，守卫房之间相隔五肘。挨着通往殿之门走廊的门槛，一竿。","notes":[]},{"n":8,"t":"他量通往殿之门的走廊，一竿。","notes":[]},{"n":9,"t":"他量门的走廊，八肘；墙柱，二肘；门的走廊通往殿那里。","notes":[]},{"n":10,"t":"往东的门有守卫房：这旁三间，那旁三间，大小都一样；这边和那边的墙柱，大小也一样。","notes":[]},{"n":11,"t":"他量门的入口，宽十肘，门长十三肘。","notes":[]},{"n":12,"t":"守卫房前有矮墙，一肘，那边的矮墙也是一肘；守卫房这边六肘，那边也是六肘。","notes":[]},{"n":13,"t":"他量门，从守卫房这边的房顶到那边的房顶，宽二十五肘；入口与入口相对。","notes":[]},{"n":14,"t":"他量墙柱，六十肘，院子的四周围有挨着墙柱的门。","notes":[]},{"n":15,"t":"从大门入口到里面门的走廊，五十肘。","notes":[]},{"n":16,"t":"守卫房和四围挨着墙柱的门，都有嵌壁式的窗户，廊子也有；里面到处都有窗户，墙柱上雕刻着棕树。","notes":[]},{"n":17,"t":"他带我到外院，看哪，院子的四围有房间，有石板地；石板地上有三十个房间。","notes":[],"heads":["外院"]},{"n":18,"t":"沿着门侧边的石板地，就是下面的石板地，与门的长度相同。","notes":[]},{"n":19,"t":"他量宽度，从下门的前面到内院外的前面，东向北向一百肘。","notes":[]},{"n":20,"t":"他量外院朝北的门的长和宽。","notes":[],"heads":["北门"]},{"n":21,"t":"门的守卫房，这旁三间，那旁三间；墙柱和廊子，与第一个门的大小一样。长五十肘，宽二十五肘。","notes":[]},{"n":22,"t":"其窗户和廊子，并雕刻的棕树，与朝东的门大小一样。要登七个台阶才能上到这门，前面有廊子。","notes":["“前面”：七十士译本是“里面”。"]},{"n":23,"t":"内院有门与这门相对，北面东面都是如此。他从这门量到那门，共一百肘。","notes":[]},{"n":24,"t":"他带我往南去，看哪，朝南有门，他量门的墙柱和廊子，大小与先前一样。","notes":["“墙柱”：七十士译本是“守卫房、墙柱”。"],"heads":["南门"]},{"n":25,"t":"门两旁与廊子的周围都有窗户，和先前量的窗户一样。门长五十肘，宽二十五肘。","notes":[]},{"n":26,"t":"要登七个台阶才能上到这门，前面有廊子；墙柱上雕刻着棕树，这边一棵，那边一棵。","notes":["“前面”：七十士译本是“里面”。"]},{"n":27,"t":"内院朝南也有门，从这门量到朝南的那门，共一百肘。","notes":[]},{"n":28,"t":"他带我从南门到内院，他量南门，大小与先前一样。","notes":[],"heads":["内院的南门"]},{"n":29,"t":"守卫房和墙柱、廊子，大小与先前一样。门两旁与廊子的周围都有窗户。门长五十肘，宽二十五肘。","notes":[]},{"n":30,"t":"周围有廊子，长二十五肘，宽五肘。","notes":[]},{"n":31,"t":"廊子朝着外院，墙柱上雕刻着棕树。要登八个台阶才能上到这门。","notes":[]},{"n":32,"t":"他带我到内院的东边，他量那门，大小与先前一样。","notes":[],"heads":["内院的东门"]},{"n":33,"t":"守卫房和墙柱、廊子，大小与先前一样。门两旁与廊子的周围都有窗户。长五十肘，宽二十五肘。","notes":[]},{"n":34,"t":"廊子朝着外院。墙柱两边都雕刻着棕树。要登八个台阶才能上到这门。","notes":[]},{"n":35,"t":"他带我到北门，他量了，大小与先前一样，","notes":[],"heads":["内院的北门"]},{"n":36,"t":"就是量守卫房和墙柱、廊子。门的周围都有窗户；门长五十肘，宽二十五肘。","notes":[]},{"n":37,"t":"墙柱朝着外院。墙柱两边都雕刻着棕树。要登八个台阶才能上到这门。","notes":["“墙柱”：七十士译本和其他古译本是“廊子”。"]},{"n":38,"t":"有房间和它的入口在门的墙柱旁，那里是洗燔祭牲的地方。","notes":["“墙柱”：原文另译“走廊”。"],"heads":["厢房"]},{"n":39,"t":"在门的走廊内，这边有两张桌子，那边也有两张桌子，其上可宰杀燔祭牲、赎罪祭牲和赎愆祭牲。","notes":[]},{"n":40,"t":"上到北门的入口，朝向外面的这边有两张桌子，门的走廊那边也有两张桌子。","notes":[]},{"n":41,"t":"门这边有四张桌子，那边也有四张桌子，共八张，在其上宰杀祭牲。","notes":[]},{"n":42,"t":"为燔祭牲的四张桌子是用石头凿成的，长一肘半，宽一肘半，高一肘。宰杀燔祭牲和其他祭牲所用的器皿可放在其上。","notes":[]},{"n":43,"t":"有钩子，宽一掌，挂在廊内的四周围。桌子上可放祭牲的肉。","notes":[]},{"n":44,"t":"从外面进到内门，内院里有房间，为歌唱的人而设；一间在北门旁，朝南，又有一间在南门旁，朝北。","notes":["“从外面...而设”：七十士译本是“他带我进到内院，看哪，内院有两个房间”。","“南”是根据七十士译本；原文是“东”。"]},{"n":45,"t":"他对我说：“这朝南的房间是为了圣殿供职的祭司，","notes":[]},{"n":46,"t":"那朝北的房间是为了祭坛前供职的祭司；这些祭司是利未人中撒督的子孙，近前来事奉耶和华的。”","notes":[]},{"n":47,"t":"他又量内院，长一百肘，宽一百肘，是正方的。祭坛就在殿前。","notes":[],"heads":["内院和圣殿"]},{"n":48,"t":"于是他带我到殿前的走廊，量走廊的墙柱。这面宽五肘，那面宽五肘。门的两旁，这边三肘，那边三肘。","notes":["七十士译本在此有“门宽十四肘”。"]},{"n":49,"t":"走廊长二十肘，宽十一肘 。要登台阶才能上到走廊。靠近墙柱又有柱子，这边一根，那边一根。","notes":["“十一肘”：七十士译本是“十二肘”。","“要登台阶”：七十士译本是“要登十个台阶”。"]}]},"41":{"heading":"靠圣殿墙边的厢房","verses":[{"n":1,"t":"他带我到殿那里，他量墙柱：这面宽六肘，那面宽六肘，宽窄与会幕相同。","notes":["有古卷和七十士译本没有“宽窄与会幕相同”。"]},{"n":2,"t":"门口宽十肘。门的两旁，这边五肘，那边五肘。他又量了殿，长四十肘，宽二十肘。","notes":[]},{"n":3,"t":"他到内殿量门的墙柱，二肘，门口六肘，门的两旁各宽七肘。","notes":[]},{"n":4,"t":"他量内殿，长二十肘，宽二十肘。他对我说：“这是至圣所。”","notes":[]},{"n":5,"t":"他又量殿的墙，六肘；围着殿有厢房，各宽四肘。","notes":[]},{"n":6,"t":"厢房有三层，层叠而上，每层排列三十间。殿的墙四周有凸出的墙支撑厢房，厢房就不必以殿的墙为支柱。","notes":[]},{"n":7,"t":"这围绕着殿的厢房越高越宽；厢房围着殿悬叠而上，所以越上面越宽，从下一层，到中一层，到上一层。","notes":[]},{"n":8,"t":"我又见有高台围绕着殿，作为厢房的根基，高足足有一竿，就是六大肘。","notes":[]},{"n":9,"t":"厢房的外墙宽五肘。殿的厢房和那边的房间中间还有空地，宽二十肘，围绕着殿。","notes":[],"end":10},{"n":11,"t":"厢房的门口向着空地：一门向北，一门向南。周围的空地宽五肘。","notes":[]},{"n":12,"t":"在西边空地之后有房子，宽七十肘，长九十肘，墙四围厚五肘。","notes":[],"heads":["西边的房子"]},{"n":13,"t":"这样，他量了殿，长一百肘，又量空地和那房子并墙，共长一百肘。","notes":[],"heads":["圣殿的面积"]},{"n":14,"t":"殿的前面和东边的空地，宽一百肘。","notes":[]},{"n":15,"t":"他量了空地后面的那房子，并两旁的楼廊，共长一百肘。内殿、院的走廊、","notes":[]},{"n":16,"t":"门槛、嵌壁式的窗户，并对着门槛的三层楼廊，周围都镶上木板；地板到窗户，窗户都关着，","notes":["“内殿、院的走廊、门槛”：七十士译本是“镶了板的内殿和院廊”。"]},{"n":17,"t":"直到门以上，就是到内殿和外殿内外四围墙壁，都这样测量。","notes":[]},{"n":18,"t":"墙上雕刻基路伯和棕树，基路伯和基路伯之间有一棵棕树，每基路伯有两张脸；","notes":[]},{"n":19,"t":"人的脸向着这边的棕树，狮子的脸向着那边的棕树，殿内四周围都是如此。","notes":[]},{"n":20,"t":"从地板到门的上面，都有基路伯和棕树。殿的墙就是这样。","notes":[]},{"n":21,"t":"殿的门柱是方的。至圣所的前面有个东西形状像","notes":[]},{"n":22,"t":"木头做的坛，高三肘，长二肘。坛角和底座，并四面，都是木头做的。他对我说：“这是耶和华面前的供桌。”","notes":["“长二肘”：七十士译本是“长二肘，宽二肘”。","“底座”是依据七十士译本；原文是“长度”。"]},{"n":23,"t":"殿和圣所各有一个双层门。","notes":[],"heads":["门"]},{"n":24,"t":"每个门有两扇，每扇又有两个摺叠页；这一扇有两页，另一扇也有两页。","notes":[]},{"n":25,"t":"殿的门扇上雕刻着基路伯和棕树，与刻在墙上的一样。在外面门的走廊前有木头做的飞檐。","notes":[]},{"n":26,"t":"门的走廊这边和那边都有嵌壁式的窗户和棕树；殿的厢房和飞檐也是这样。","notes":[]}]},"42":{"heading":"圣殿附近的房间","verses":[{"n":1,"t":"他带我出来往北，到外院，又带我进入一个房间，一面对着空地，一面对着北边的房子。","notes":[]},{"n":2,"t":"前面长一百肘，宽五十肘，有门向北；","notes":[]},{"n":3,"t":"对着内院那二十肘，又对着外院的石板地，在第三层楼有楼廊对着楼廊。","notes":["“那二十肘”：七十士译本是“那些门”。"]},{"n":4,"t":"那些房间前有一条走道，宽十肘，往里面有宽一肘的通道。房门都向北。","notes":["“往里面...通道”：七十士译本是“长一百肘”。"]},{"n":5,"t":"房间因为楼廊占掉一些地方，所以房子的上层比中下两层窄。","notes":[]},{"n":6,"t":"房间分三层，却不像外院的屋子用柱子支撑，而是从地面往上，所以一层比一层更窄。","notes":[]},{"n":7,"t":"外面有一道墙，长五十肘，在房间前面，与朝外院的房间平行。","notes":[]},{"n":8,"t":"靠着外院的房间长五十肘，看哪，朝圣殿的长一百肘。","notes":[]},{"n":9,"t":"这些房间下面的东边有一个入口，从外院可由此进入；","notes":[]},{"n":10,"t":"其宽如院墙。朝东也有房间，一面对着空地，一面对着房子。","notes":["“东”：七十士译本是“南”。"]},{"n":11,"t":"这些房间前的通道与北边房间的通道一样；长、宽、出口、样式和入口都相同。","notes":[]},{"n":12,"t":"在东边通道的开端，正对着那道墙有门可以进入，与向南边房间的门一样。","notes":[]},{"n":13,"t":"他对我说：“面对空地南边的房间和北边的房间，都是圣的房间；亲近耶和华的祭司当在那里吃至圣的东西，也当在那里存放至圣的东西，就是素祭、赎罪祭和赎愆祭，因此处为圣。","notes":[]},{"n":14,"t":"祭司进圣所，出来的时候，不可直接到外院，要在那里放下他们供职的衣服，因为这是圣衣；要穿上别的衣服才可以到百姓所在之处。”","notes":[]},{"n":15,"t":"他量完了内殿的大小，就带我出朝东的门，去量院的四周围。","notes":[],"heads":["圣殿周围的面积"]},{"n":16,"t":"他用丈量的芦苇竿量东面，五百竿；又转去","notes":["“竿”：七十士译本是“肘”；下同。"]},{"n":17,"t":"用丈量的芦苇竿量北面，五百竿；又转去","notes":[]},{"n":18,"t":"用丈量的芦苇竿量南面，五百竿。","notes":[]},{"n":19,"t":"他又转到西面，用丈量的芦苇竿去量，五百竿。","notes":[]},{"n":20,"t":"他量四面，长五百，宽五百，四周围有墙，为要分别圣与俗。","notes":[]}]},"43":{"heading":"耶和华的荣耀回到圣殿","verses":[{"n":1,"t":"以后，他带我到一座门，就是朝东的门。","notes":[]},{"n":2,"t":"看哪，以色列神的荣光从东而来，他的声音如同众水的响声，地因他的荣耀发光。","notes":[]},{"n":3,"t":"我所见的异象如同从前我来灭城的时候所见的异象，又如我在迦巴鲁河边所见的异象，我就脸伏于地。","notes":["“我”：有古卷和古译本是“他”。"]},{"n":4,"t":"耶和华的荣光从朝东的门照入殿中。","notes":[]},{"n":5,"t":"灵将我举起，带入内院，看哪，耶和华的荣光充满了殿。","notes":[]},{"n":6,"t":"我听见有一位从殿中向我说话，有一人站在我旁边。","notes":[]},{"n":7,"t":"他对我说：“人子啊，这是我宝座之地，是我脚掌所踏之地。我要住在这里，住在以色列人中间直到永远。以色列家和他们的君王不可再以淫行，或在高处以君王的尸首玷污我的圣名。","notes":["“在高处以君王的尸首”：有古卷和古译本是“以君王死时的尸首”。"]},{"n":8,"t":"因他们使自己的门槛挨近我的门槛，使自己的门框挨近我的门框，又使他们与我之间仅隔一墙，并且行可憎的事，玷污我的圣名，所以我发怒灭绝他们。","notes":[]},{"n":9,"t":"现在，他们当从我面前远离淫行和君王的尸首，我就要住在他们中间，直到永远。","notes":[]},{"n":10,"t":"“你，人子啊，要将这殿指示以色列家，让他们量殿的大小，使他们因自己的罪孽羞愧。","notes":["“要将这殿<ins>.大小”：七十士译本和其他古译本是“要将这殿，其外观和样式指示以色列家”。"]},{"n":11,"t":"他们若因自己所做的一切感到羞愧，你就要将殿的规模、样式、出口、入口，以及有关整体规模的条例、礼仪、律法指示他们，在他们眼前写下，使他们遵照殿整体的规模和条例去做。","notes":["“你就要</ins>.指示他们”：七十士译本是“你就要描述殿和其出口、样式，并它一切的条例，又要将它一切的律法指示他们”。"]},{"n":12,"t":"这是殿的律法：山顶上四周围的全地界都称为至圣；看哪，这就是殿的律法。”","notes":["七十士译本没有“看哪...律法”。"]},{"n":13,"t":"这些是祭坛的大小，以肘来量，这肘是一肘一掌。底座高一肘，边宽一肘，四周围有边，高一虎口；这是祭坛的座。","notes":["“座”：七十士译本是“高度”。"],"heads":["祭坛"]},{"n":14,"t":"从底座到下层的台座，二肘，边宽一肘。从小台座到大台座，四肘，边宽一肘。","notes":[]},{"n":15,"t":"坛上的炉台，高四肘，从炉台向上突起四个角。","notes":[]},{"n":16,"t":"这炉台长十二肘，宽十二肘，四面见方。","notes":[]},{"n":17,"t":"台座长十四肘，宽十四肘，四面见方。四周围有边，高半肘，底座四围的边宽一肘。有台阶朝东。","notes":[]},{"n":18,"t":"他对我说：“人子啊，主耶和华如此说：这些是建造祭坛，为要在其上献燔祭，把血洒在上面的条例：","notes":[],"heads":["奉献祭坛"]},{"n":19,"t":"你要将一头公牛犊作为赎罪祭，交给那近前来事奉我的利未家的祭司撒督的后裔；这是主耶和华说的。","notes":[]},{"n":20,"t":"你要取那公牛犊的一些血，抹在坛的四角和台座的四角，并周围的边上。你要这样洁净坛，为坛赎罪。","notes":[]},{"n":21,"t":"你又要将那作赎罪祭的公牛烧在圣所外面，殿的预定之处。","notes":[]},{"n":22,"t":"次日，要将无残疾的公山羊献为赎罪祭；要洁净坛，像用公牛洁净一样。","notes":[]},{"n":23,"t":"你洁净了坛，就要将一头无残疾的公牛犊和羊群中一只无残疾的公绵羊","notes":[]},{"n":24,"t":"奉到耶和华面前。祭司要撒盐在其上，献给耶和华为燔祭。","notes":[]},{"n":25,"t":"七日内，你要每日献一只公山羊为赎罪祭，也要献一头公牛犊和羊群中的一只公绵羊，都要没有残疾的。","notes":[]},{"n":26,"t":"七日内祭司要为坛赎罪，使它洁净，把它分别为圣。","notes":[]},{"n":27,"t":"满了七日，自八日以后，祭司要在坛上献你们的燔祭和平安祭；我必悦纳你们。这是主耶和华说的。”","notes":[]}]},"44":{"heading":"东门的使用","verses":[{"n":1,"t":"他又带我回到圣所朝东的外门，那门关闭了。","notes":[]},{"n":2,"t":"耶和华对我说：“这门必须关闭，不可敞开，谁也不可由其中进入；因为耶和华─以色列的神已经由其中进入，所以必须关闭。","notes":[]},{"n":3,"t":"至于君王，他必按君王的位分坐在其内，在耶和华面前吃饼。他必由这门的走廊而入，也必由此而出。”","notes":[]},{"n":4,"t":"他又带我由北门来到殿前。我观看，看哪，耶和华的荣光充满耶和华的殿，我就脸伏于地。","notes":[],"heads":["进入圣殿之规定"]},{"n":5,"t":"耶和华对我说：“人子啊，我对你所说耶和华殿中一切的条例和律法，你要留心，用眼看，用耳听，要留心殿的入口和圣所一切的出口。","notes":[]},{"n":6,"t":"你要对那悖逆的以色列家说，主耶和华如此说：以色列家啊，你们行这一切可憎的事，够了吧！","notes":[]},{"n":7,"t":"你们把我的食物，就是脂肪和血献上的时候，竟把心和肉体未受割礼的外邦人领进我的圣所，玷污我的殿；你们行这一切可憎的事，违背了我的约。","notes":[]},{"n":8,"t":"你们未尽看守我圣物的职责，竟派别人在我的圣所替你们尽看守之责。","notes":[]},{"n":9,"t":"“主耶和华如此说：所有心和肉体未受割礼的外邦人，就是住在以色列中间的任何外邦人，都不可进入我的圣所。”","notes":[]},{"n":10,"t":"“以色列人走迷的时候，利未人远离我，随从他们的偶像走迷离开我，他们必担当自己的罪孽。","notes":[],"heads":["不准当祭司的利未人"]},{"n":11,"t":"他们必在我的圣所当仆役，照管殿门，在殿里伺候；他们要为百姓宰杀燔祭牲和其他祭牲，站在百姓面前伺候他们。","notes":[]},{"n":12,"t":"因为这些利未人曾在偶像前伺候他们，成了以色列家罪孽的绊脚石，所以我向他们起誓：他们必担当自己的罪孽。这是主耶和华说的。","notes":[]},{"n":13,"t":"他们不可亲近我，作事奉我的祭司，也不可挨近我任何一件圣物，就是至圣的物；他们却要担当自己的羞辱和所行可憎之事的报应。","notes":[]},{"n":14,"t":"我要指派他们在殿里看守，办理殿中一切事务，做一切当做的工。”","notes":[]},{"n":15,"t":"“以色列人走迷离开我的时候，利未家的祭司撒督的子孙仍然尽看守我圣所的职责；因此他们必亲近我，事奉我，并且侍立在我面前，把脂肪与血献给我。这是主耶和华说的。","notes":[],"heads":["利未家的祭司"]},{"n":16,"t":"只有他们可以进我的圣所，来到我的桌前事奉我，守我吩咐的职责。","notes":[]},{"n":17,"t":"他们进内院的门要穿细麻衣，在内院门和殿内供职时不可穿羊毛衣服。","notes":[]},{"n":18,"t":"他们要头戴细麻布的头巾，腰穿细麻布的裤子；不可穿容易出汗的衣服。","notes":[]},{"n":19,"t":"他们出到外院，到外院百姓那里，要脱下供职所穿的衣服，放在圣的房间内，换上别的衣服，免得因他们的衣服使百姓成为圣。","notes":["有些古卷、七十士译本和其他古译本没有“到外院”。"]},{"n":20,"t":"他们不可剃头，也不可留长发，头发一定要修剪。","notes":[]},{"n":21,"t":"祭司进内院时不可喝酒。","notes":[]},{"n":22,"t":"他们不可娶寡妇或被休的妇人为妻，只可娶以色列后裔中的处女，或祭司的寡妇。","notes":[]},{"n":23,"t":"他们要教导我的子民分辨圣与俗，使他们知道洁净和不洁净的分别。","notes":[]},{"n":24,"t":"有争讼的事，他们应当审判，按我的典章审判。他们要在我的节期守我的律法和条例，也当以我的安息日为圣日。","notes":[]},{"n":25,"t":"祭司不可挨近死尸使自己不洁净，只可为父亲、母亲、儿子、女儿、兄弟和未出嫁的姊妹使自己不洁净。","notes":[]},{"n":26,"t":"他洁净之后，他们必须再为他计算七天。","notes":[]},{"n":27,"t":"当他进内院，入圣所，在圣所中事奉的日子，要为自己献上赎罪祭。这是主耶和华说的。","notes":[]},{"n":28,"t":"“祭司必有产业，我就是他们的产业。不可在以色列中给他们基业，我就是他们的基业。","notes":[]},{"n":29,"t":"素祭、赎罪祭和赎愆祭他们都可以吃，以色列中一切永献的祭物都归他们。","notes":[]},{"n":30,"t":"各样上好的初熟之物和所献的供物，都要归祭司。你们也要将最先的面团给祭司；这样，福气就必临到你们的家。","notes":[]},{"n":31,"t":"无论是鸟是兽，凡自然死去的，或是被撕裂的，祭司都不可吃。”","notes":[]}]},"45":{"heading":"归给耶和华的土地","verses":[{"n":1,"t":"你们抽签分地为业，要献上一份作为献给耶和华的圣地，长二万五千肘，宽二万肘。整个地区都作为圣地。","notes":["原文没有“肘”；下同。","“二万”是根据七十士译本；原文是“一万”。"]},{"n":2,"t":"再从其中划出一块作为圣所，长五百肘，宽五百肘，四面见方；四围再加五十肘的空地。","notes":[]},{"n":3,"t":"从这整个范围要划出长二万五千肘，宽一万肘的地，其中要有圣所，是至圣的。","notes":[]},{"n":4,"t":"这是地上的一块圣地，要归给在圣所供职、亲近事奉耶和华的祭司，作为他们房屋用地与圣所的圣地。","notes":[]},{"n":5,"t":"其余长二万五千肘，宽一万肘，要归给在殿中供职的利未人，作为他们二十间房屋的地业。","notes":["“二十间房屋”：七十士译本是“居住的城镇”。"]},{"n":6,"t":"在那块献上的圣地旁边，你们要划分造城的地业，宽五千肘，长二万五千肘，归以色列全家。","notes":[]},{"n":7,"t":"划归君王的地要在献上的圣地和城用地的两旁，面对着圣地，又面对城的用地，西至西边的疆界，东至东边的疆界，从西到东，长度与每支派所分得的一样。","notes":[],"heads":["君王的土地"]},{"n":8,"t":"这地要在以色列中归君王为业。我所立的君王必不再欺压我的子民，却要按支派把地分给以色列家。","notes":[]},{"n":9,"t":"主耶和华如此说：“以色列的王啊，你们够了吧！要除掉残暴和抢夺的事，行公平和公义，不可再勒索我的百姓。这是主耶和华说的。","notes":[],"heads":["君王应守的规例"]},{"n":10,"t":"“你们要用公道的天平、公道的伊法、公道的罢特。","notes":[]},{"n":11,"t":"伊法要与罢特等量；一罢特为贺梅珥的十分之一，一伊法也是贺梅珥的十分之一，都以贺梅珥为计算单位。","notes":[]},{"n":12,"t":"一舍客勒是二十季拉；二十舍客勒，二十五舍客勒，十五舍客勒，合起来为你们的一弥那。","notes":[]},{"n":13,"t":"“你们当献的供物是这样：一贺梅珥麦子要献六分之一伊法，一贺梅珥大麦也要献六分之一伊法。","notes":[]},{"n":14,"t":"献油的条例是这样，按油的罢特：每一歌珥油，即十罢特或一贺梅珥，要献十分之一罢特，原来十罢特等于一贺梅珥。","notes":[]},{"n":15,"t":"从以色列水源丰沛的草场上，每二百只羊中要献一只羔羊。这都可作素祭、燔祭、平安祭，来为民赎罪。这是主耶和华说的。","notes":[]},{"n":16,"t":"这地所有的百姓都要带这些供物到以色列王那里。","notes":[]},{"n":17,"t":"王的本分是在节期、初一、安息日，就是以色列家一切的盛会，奉上燔祭、素祭、浇酒祭。他要献上赎罪祭、素祭、燔祭和平安祭，为以色列家赎罪。”","notes":[]},{"n":18,"t":"主耶和华如此说：“正月初一，你要取无残疾的公牛犊，洁净圣所。","notes":[],"heads":["节期"]},{"n":19,"t":"祭司要取一些赎罪祭牲的血，抹在殿的门柱上和祭坛台座的四角上，并内院的门框上。","notes":[]},{"n":20,"t":"本月初七，你也要为误犯罪的和因无知而犯罪的这样做；你们要为圣殿赎罪。","notes":[]},{"n":21,"t":"“正月十四日，你们要守逾越节，七天的节期都要吃无酵饼。","notes":[]},{"n":22,"t":"当日，王要为自己和全国百姓预备一头公牛作赎罪祭。","notes":[]},{"n":23,"t":"节期的七天内，每天他要预备无残疾的七头公牛、七只公绵羊，给耶和华为燔祭；每天又要预备一只公山羊为赎罪祭。","notes":[]},{"n":24,"t":"他也要预备素祭，为一头公牛同献一伊法细面，为一只公绵羊同献一伊法细面，每一伊法加一欣油。","notes":[]},{"n":25,"t":"七月十五日守节的时候，七天他都要像这样预备赎罪祭、燔祭、素祭和油。”","notes":[]}]},"46":{"heading":"王和节期","verses":[{"n":1,"t":"主耶和华如此说：“内院朝东的门，在六个工作的日子必须关闭；惟有安息日和初一要敞开。","notes":[]},{"n":2,"t":"王从外面要由门的走廊进入，站在门框旁边；祭司要为他预备燔祭和平安祭，王要在门的门槛那里敬拜，然后退出。这门直到晚上不可关闭。","notes":[]},{"n":3,"t":"安息日和初一，这地的百姓要在这门口，在耶和华面前敬拜。","notes":[]},{"n":4,"t":"安息日，王要用六只无残疾的羔羊、一只无残疾的公绵羊，献给耶和华为燔祭；","notes":[]},{"n":5,"t":"同献的素祭，要为公绵羊献一伊法细面，为羔羊则按照他的力量献，一伊法要加一欣油。","notes":[]},{"n":6,"t":"初一，他要献一头无残疾的公牛犊、六只羔羊、一只公绵羊，全都要用无残疾的。","notes":[]},{"n":7,"t":"他也要预备素祭，为公牛献一伊法细面，为公绵羊献一伊法细面，为羔羊则按照他的力量献，一伊法要加一欣油。","notes":[]},{"n":8,"t":"王进入的时候要由这门的走廊而入，也要从原路出去。","notes":[]},{"n":9,"t":"“在各节期，这地的百姓朝见耶和华的时候，从北门进入敬拜的，要由南门而出；从南门进入的，要由北门而出。不可从进入的门出去，要往前直行，从对面的门出去。","notes":[]},{"n":10,"t":"他们进入时，王也跟他们一同进入；他们出去，他也要出去。","notes":[]},{"n":11,"t":"“在节期和盛会的日子同献的素祭，要为一头公牛献一伊法细面，为一只公绵羊献一伊法细面，为羔羊则按照各人的力量献，一伊法要加一欣油。","notes":[]},{"n":12,"t":"王奉献甘心祭，就是向耶和华甘心献的燔祭或平安祭时，当有人为他开朝东的门。他就献上燔祭和平安祭，与安息日所献的一样，然后退出。他出去之后，当有人将门关闭。”","notes":[]},{"n":13,"t":"“每日，你要取一只无残疾一岁的羔羊献给耶和华为燔祭；要每天早晨献上。","notes":[],"heads":["每日献的祭"]},{"n":14,"t":"每天早晨你也要预备同献的素祭，六分之一伊法细面，并三分之一欣油，调和细面。这素祭要经常献给耶和华，作为永远的定例。","notes":[]},{"n":15,"t":"每天早晨要这样献上羔羊、素祭和油，为经常献的燔祭。”","notes":[]},{"n":16,"t":"主耶和华如此说：“王若将礼物赐给他的任何一个儿子，这就成为儿子的产业，可留给子孙，是他们所承受的地业。","notes":[],"heads":["王和土地"]},{"n":17,"t":"倘若王将他产业的一份赐给他的一个臣仆，这就成为他臣仆的产业，直到自由之年，然后地要归还王；王的产业终究要归自己的儿子。","notes":[]},{"n":18,"t":"王不可夺取百姓的产业，以致赶逐他们离开自己的地业；他应该从自己的地业中将产业赐给子孙，免得我的子民离开自己的地业，四散各处。”","notes":[]},{"n":19,"t":"他带领我从大门旁边的入口，进到朝北为祭司所预备圣的房间，看哪，西边尽头有一块土地。","notes":[],"heads":["圣殿的厨房"]},{"n":20,"t":"他对我说：“这是祭司煮赎愆祭牲、赎罪祭牲，烤素祭的地方，免得带出外院，使百姓成为圣。”","notes":[]},{"n":21,"t":"他又带我出到外院，使我经过院子的四个角落，看哪，院子的每个角落都有一个小院子。","notes":[]},{"n":22,"t":"院子四个角落有小院子，周围有墙，每个小院子长四十肘，宽三十肘；四个角落的小院子大小都一样，","notes":["原文没有“肘”；下同。"]},{"n":23,"t":"小院子周围各有一排石墙，每排石墙下面有炉灶。","notes":[]},{"n":24,"t":"他对我说：“这些是煮肉用的屋子，殿内的仆役要在这里煮百姓的祭物。”","notes":[]}]},"47":{"heading":"从圣殿流出的水","verses":[{"n":1,"t":"他带我回到殿门，看哪，有水从殿的门槛下面往东流出，因为这殿是朝东的。水从殿的侧面，就是右边，从祭坛的南边往下流。","notes":[]},{"n":2,"t":"他带我出北门，又领我从外边转到朝东的外门，看哪，水从右边流出。","notes":[]},{"n":3,"t":"他手拿绳子往东出去，量了一千肘，使我涉水而过，水到脚踝。","notes":[]},{"n":4,"t":"他又量了一千，使我涉水而过，水就到膝；再量了一千，使我过去，水就到腰；","notes":[]},{"n":5,"t":"又量了一千，水已成河，无法过去；因为水势高涨成河，只能游泳，无法走过。","notes":[]},{"n":6,"t":"他对我说：“人子啊，你看见了吗？”他带我回到河边。","notes":[]},{"n":7,"t":"我回到河边时，看哪，河这边与那边的岸上有极多的树木。","notes":[]},{"n":8,"t":"他对我说：“这水往东方流，下到亚拉巴，直到海。所流出来的水，一入海就使水变淡。","notes":["“直到海...一入海”：有古译本是“一入臭水的海”。","“使水变淡”：原文是“使水得医治”；下同。"]},{"n":9,"t":"这两条河所到之处，凡滋生的动物都必存活；这水流到那里，使那里的水变淡，因此里面有极多的鱼。这河水所到之处，百物都必存活。","notes":["“这两条河”：七十士译本和其他古译本是“这条河”。"]},{"n":10,"t":"必有渔夫站在河边，从隐．基底直到隐．以革莲，全都成了晒网的场所。那里的鱼各从其类，好像大海的鱼甚多。","notes":["“晒”或译“张”。"]},{"n":11,"t":"但是沼泽与池塘的水无法变淡，只能作产盐之用。","notes":[]},{"n":12,"t":"河这边与那边的岸上必生长各类树木，可作食物；叶子不枯干，果子不断绝。每月必结新果子，因为这水是从圣所流出来的。树上的果子必作食物，叶子可以治病。”","notes":[]},{"n":13,"t":"主耶和华如此说：“这是你们按以色列十二支派分地为业的地界，约瑟要得两份。","notes":[],"heads":["地界"]},{"n":14,"t":"你们承受这地为业，要彼此均分；我曾起誓应许将这地赐给你们的列祖，这地必归你们为业。","notes":[]},{"n":15,"t":"“这地的疆界如下：北界从大海往希特伦，直到西达达口；","notes":[]},{"n":16,"t":"又往哈马、比罗他、西伯莲(西伯莲在大马士革的边界与哈马的边界中间)，到浩兰边界的哈撒．哈提干。","notes":["“直到西达达口；又往哈马”：七十士译本是“直到哈马口；又往西达达”。"]},{"n":17,"t":"这样，疆界是从大海往大马士革地界上的哈萨．以难，北边以哈马为界。这是北界。","notes":[]},{"n":18,"t":"“东界在浩兰和大马士革中间，基列和以色列地的中间，以约旦河为界。你们要量疆界直到东海。这是东界。","notes":["“你们要...到东海”：有古译本是“疆界要从东海直到他玛”。"]},{"n":19,"t":"“南界是从他玛到加低斯的米利巴水，经埃及溪谷，直到大海。这是南界。","notes":["“埃及溪谷”：原文是“溪谷”。"]},{"n":20,"t":"“西界就是大海，从南界直到哈马口对面。这是西界。","notes":[]},{"n":21,"t":"“你们要为自己按以色列的支派分这地。","notes":[]},{"n":22,"t":"要抽签分这地为业，归自己和那在你们中间寄居，生儿育女的外人。你们要看他们如本地出生的以色列人，他们要在以色列支派中与你们同得地业。","notes":[]},{"n":23,"t":"外人寄居在哪个支派，你们就在哪里将地业分给他们。这是主耶和华说的。”","notes":[]}]},"48":{"heading":"各支派分配土地","verses":[{"n":1,"t":"众支派的名字如下：从北边尽头，由希特伦往哈马口，到大马士革地界上的哈萨．以难。北边靠着哈马地，从东到西是但的一份。","notes":[]},{"n":2,"t":"靠着但的地界，从东到西，是亚设的一份。","notes":[]},{"n":3,"t":"靠着亚设的地界，从东到西，是拿弗他利的一份。","notes":[]},{"n":4,"t":"靠着拿弗他利的地界，从东到西，是玛拿西的一份。","notes":[]},{"n":5,"t":"靠着玛拿西的地界，从东到西，是以法莲的一份。","notes":[]},{"n":6,"t":"靠着以法莲的地界，从东到西，是吕便的一份。","notes":[]},{"n":7,"t":"靠着吕便的地界，从东到西，是犹大的一份。","notes":[]},{"n":8,"t":"靠着犹大的地界，从东到西，必有你们所当献的圣地，宽二万五千肘；长短与各族从东到西所分的地相同，圣所当在其中。","notes":["原文没有“肘”；下同。"],"heads":["中部的圣地"]},{"n":9,"t":"你们献给耶和华的圣地要长二万五千肘，宽一万肘。","notes":[]},{"n":10,"t":"这圣地要归祭司，北长二万五千肘，西宽一万肘，东宽一万肘，南长二万五千肘。耶和华的圣所当在其中。","notes":[]},{"n":11,"t":"这地要归撒督的子孙中成为圣的祭司，他们谨守我所吩咐的；当以色列人走迷的时候，他们不像那些利未人走迷了。","notes":[]},{"n":12,"t":"在圣地中要特别保留一份归他们，为至圣，紧邻着利未人的地界。","notes":[]},{"n":13,"t":"利未人所得的地长二万五千肘，宽一万肘，与祭司的地界相等，都长二万五千肘，宽一万肘。","notes":[]},{"n":14,"t":"这地不可卖，不可换；这上好的部分不可转让给别人，因为它归耶和华为圣。","notes":[]},{"n":15,"t":"剩下的地长二万五千肘、宽五千肘，要作公用，为造城、盖房、空地之用；城要在中间。","notes":[]},{"n":16,"t":"以下是城的大小：北面四千五百肘，南面四千五百肘，东面四千五百肘，西面四千五百肘。","notes":[]},{"n":17,"t":"城要有空地，向北二百五十肘，向南二百五十肘，向东二百五十肘，向西二百五十肘。","notes":[]},{"n":18,"t":"靠着圣地并排剩余的，东长一万肘，西长一万肘；它与圣地并排，其中所出产的要作城内工人的食物。","notes":[]},{"n":19,"t":"以色列支派中所有在城内做工的，都要耕种这地。","notes":[]},{"n":20,"t":"你们要将整块四方的圣地，长二万五千肘，宽二万五千肘，连同城的用地都献作圣地。","notes":[]},{"n":21,"t":"圣地和城的用地两边剩余的要归给王。地的东边，南北二万五千肘，东至东界；西边，南北二万五千肘，西至西界；靠着各支派所分的地，都要归给王。圣地和殿的圣所要在其中。","notes":[]},{"n":22,"t":"利未人的地与城的用地都在王的地中间，犹大边界和便雅悯边界之间，要归给王。","notes":[]},{"n":23,"t":"论到其余的支派，从东到西，是便雅悯的一份。","notes":[],"heads":["其他支派的土地"]},{"n":24,"t":"靠着便雅悯的地界，从东到西，是西缅的一份。","notes":[]},{"n":25,"t":"靠着西缅的地界，从东到西，是以萨迦的一份。","notes":[]},{"n":26,"t":"靠着以萨迦的地界，从东到西，是西布伦的一份。","notes":[]},{"n":27,"t":"靠着西布伦的地界，从东到西，是迦得的一份。","notes":[]},{"n":28,"t":"靠着迦得南边的地界，界限从他玛到加低斯的米利巴水，经埃及溪谷，直到大海。","notes":["“埃及溪谷”：原文是“溪谷”。"]},{"n":29,"t":"这就是你们要抽签分给以色列支派为业之地，是他们各支派所得的份。这是主耶和华说的。","notes":[]},{"n":30,"t":"以下是城的出口：北面四千五百肘，","notes":[],"heads":["耶路撒冷的城门"]},{"n":31,"t":"城的各门要按以色列的支派命名。北面有三个门，一为吕便门，一为犹大门，一为利未门。","notes":[]},{"n":32,"t":"东面四千五百肘，有三个门，一为约瑟门，一为便雅悯门，一为但门。","notes":[]},{"n":33,"t":"南面四千五百肘，有三个门，一为西缅门，一为以萨迦门，一为西布伦门。","notes":[]},{"n":34,"t":"西面四千五百肘，有三个门，一为迦得门，一为亚设门，一为拿弗他利门。","notes":[]},{"n":35,"t":"城的周围共一万八千肘。从此以后，这城的名字必称为“耶和华的所在”。","notes":[]}]}},"DAN":{"1":{"heading":"但以理和他的朋友","verses":[{"n":1,"t":"犹大王约雅敬在位第三年，巴比伦王尼布甲尼撒来到耶路撒冷，将城围困。","notes":[],"heads":["但以理在尼布甲尼撒的宫廷里"]},{"n":2,"t":"主将犹大王约雅敬和神殿中的一些器皿交在他的手中。他就把他们带到示拿地他神明的庙里，将器皿收入他神明的库房中。","notes":[]},{"n":3,"t":"王吩咐太监长亚施毗拿，从以色列人的王室后裔和贵族中带进几个人来，","notes":[]},{"n":4,"t":"就是没有残疾、相貌俊美、通达各样学问、知识聪明俱备、足能在王宫侍立的少年，要教他们迦勒底的文字和语言。","notes":["“学问”：原文是“智慧”；下同。"]},{"n":5,"t":"王从自己所用的膳和所饮的酒中，派给他们每日的分量，养育他们三年，好叫他们期满以后侍立在王面前。","notes":[]},{"n":6,"t":"他们中间有犹大人但以理、哈拿尼雅、米沙利和亚撒利雅。","notes":[]},{"n":7,"t":"太监长给他们另外起名，称但以理为伯提沙撒，称哈拿尼雅为沙得拉，称米沙利为米煞，称亚撒利雅为亚伯尼歌。","notes":[]},{"n":8,"t":"但以理却立志，不以王的膳和王所饮的酒玷污自己，于是恳求太监长容他不使自己玷污。","notes":[]},{"n":9,"t":"神使但以理在太监长眼前蒙恩，得怜悯。","notes":[]},{"n":10,"t":"太监长对但以理说：“我惧怕我主我王，他已经派给你们的饮食，何必让他见你们的面貌比你们同年龄的少年憔悴呢？这样，你们就使我的头在王那里不保了。”","notes":[]},{"n":11,"t":"但以理对太监长所派监管但以理、哈拿尼雅、米沙利、亚撒利雅的管理者说：","notes":[]},{"n":12,"t":"“请你考验仆人们十天，给我们素菜吃，清水喝，","notes":[]},{"n":13,"t":"然后你亲自观察我们的面貌和那用王膳的少年的面貌；就照你所观察的待你的仆人吧！”","notes":[]},{"n":14,"t":"管理者准许他们这件事，考验他们十天。","notes":[]},{"n":15,"t":"过了十天，他们的身材看来比所有享用王膳的少年更加俊美健壮，","notes":[]},{"n":16,"t":"于是管理者撤去王派给他们用的膳和所饮的酒，只给他们素菜。","notes":[]},{"n":17,"t":"这四个少年，神在各样文字学问上赐给他们知识和聪明；但以理又明白各样异象和梦兆。","notes":[]},{"n":18,"t":"王吩咐带他们进宫的日子到了，太监长就把他们带到尼布甲尼撒面前。","notes":[]},{"n":19,"t":"王与他们谈论，在所有少年中找不到人能与但以理、哈拿尼雅、米沙利、亚撒利雅相比，于是他们就在王面前侍立。","notes":[]},{"n":20,"t":"王考问他们一切智慧和聪明的事，发现他们比全国所有的术士和巫师胜过十倍。","notes":[]},{"n":21,"t":"到居鲁士王元年，但以理还健在。","notes":[]}]},"2":{"heading":"神指示但以理","verses":[{"n":1,"t":"尼布甲尼撒在位第二年，他做了很多梦，心里烦乱，不能睡觉。","notes":[]},{"n":2,"t":"王吩咐人将术士、巫师、行邪术的和迦勒底人召来，要他们把王的梦告诉王；他们就来，站在王面前。","notes":[]},{"n":3,"t":"王对他们说：“我做了一个梦，心里烦乱，想要知道这是什么梦。”","notes":[]},{"n":4,"t":"迦勒底人用亚兰话对王说：“愿王万岁！请将梦告诉仆人，我们就可以讲解。”","notes":["从“愿王万岁”开始到第七章结尾，原文是亚兰文。"]},{"n":5,"t":"王回答迦勒底人说：“这事我已决定，你们若不把梦和梦的解释告诉我，就必被凌迟，你们的房屋必成粪堆；","notes":[]},{"n":6,"t":"但你们若能说出这个梦和梦的解释，就必从我得到礼物、赏赐和殊荣。现在，你们要把梦和梦的解释告诉我。”","notes":[]},{"n":7,"t":"他们再一次回答说：“请王将梦告诉仆人，我们就可以讲解。”","notes":[]},{"n":8,"t":"王回答说：“我确实知道你们是故意拖延，因为你们知道这事我已决定。","notes":[]},{"n":9,"t":"你们若不将梦告诉我，只有一个办法对待你们；因为你们彼此串通，向我胡言乱语，要等候情势改变。现在，你们要将梦告诉我，让我知道你们真能为我解梦。”","notes":[]},{"n":10,"t":"迦勒底人回答王说：“世上没有人能解释王的事情；从来没有君王、大臣、掌权者向术士、巫师，或迦勒底人问过这样的事。","notes":[]},{"n":11,"t":"王所问的事很难，除了不与血肉之躯同住的神，没有人能在王面前解释。”","notes":[]},{"n":12,"t":"王因这事生气，大大震怒，吩咐灭绝巴比伦所有的智慧人。","notes":[]},{"n":13,"t":"命令发出，智慧人将要被杀，人就寻找但以理和他的同伴，要杀他们。","notes":[]},{"n":14,"t":"王的护卫长亚略奉命去杀巴比伦的智慧人，但以理用婉言和智慧回应，","notes":[]},{"n":15,"t":"向王的大臣亚略说：“王的命令为何这样紧急呢？”亚略就把事情告诉但以理。","notes":[]},{"n":16,"t":"于是但以理进去求王宽限，好为王解梦。","notes":[]},{"n":17,"t":"但以理回到他的居所，把这事告诉他的同伴哈拿尼雅、米沙利、亚撒利雅，","notes":[]},{"n":18,"t":"要他们祈求天上的神施怜悯，将这奥秘指明，免得但以理和他的同伴与巴比伦其余的智慧人一同灭亡。","notes":[]},{"n":19,"t":"这奥秘就在夜间异象中显明给但以理，但以理就称颂天上的神。","notes":[]},{"n":20,"t":"但以理说：“神的名是应当称颂的，从亘古直到永远！因为智慧和能力都属乎他。","notes":[]},{"n":21,"t":"他改变时间、季节，他废王，立王；将智慧赐给智慧人，将知识赐给聪明人。","notes":[]},{"n":22,"t":"他显明深奥隐秘的事，洞悉幽暗中的一切，光明也与他同住。","notes":[]},{"n":23,"t":"我列祖的神啊，我感谢你，赞美你，因你将智慧才能赐给我，我们所求问的现在你已指明给我，把王的事给我们指明。”","notes":[]},{"n":24,"t":"于是，但以理进到王所派灭绝巴比伦智慧人的亚略那里去，对他这样说：“不要灭绝巴比伦的智慧人，求你领我到王面前，我可以为王解梦。”","notes":[],"heads":["但以理解梦"]},{"n":25,"t":"亚略就急忙领但以理到王面前，对王这样说：“我在被掳的犹大人中找到一人，能将梦的解释告诉王。”","notes":[]},{"n":26,"t":"王对那称为伯提沙撒的但以理说：“你能将我所做的梦和梦的解释告诉我吗？”","notes":[]},{"n":27,"t":"但以理回答王说：“王所问的那奥秘，智慧人、巫师、术士、观兆的都不能告诉王，","notes":[]},{"n":28,"t":"只有那在天上的神能显明奥秘。他已把日后将要发生的事指示尼布甲尼撒王。你在床上做的梦和你脑中的异象是这样：","notes":[]},{"n":29,"t":"你，王啊，你在床上所思想的是关乎日后的事，那显明奥秘的主已把将来要发生的事指示你。","notes":[]},{"n":30,"t":"至于我，那奥秘显明给我，并非因我智慧胜过一切活着的人，而是为了让王知道梦的解释，知道你心里的意念。","notes":[]},{"n":31,"t":"“你，王啊，你正观看，看哪，有一个很大的像，这像甚高，极其光耀，立在你面前，形状非常可怕。","notes":[]},{"n":32,"t":"这像的头是纯金的，胸膛和膀臂是银的，腹部和腰是铜的，","notes":[]},{"n":33,"t":"腿是铁的，脚是半铁半泥的。","notes":[]},{"n":34,"t":"你正观看，见有一块非人手凿出来的石头打在它半铁半泥的脚上，把脚砸碎；","notes":[]},{"n":35,"t":"于是铁、泥、铜、银、金都一同砸得粉碎，如夏天禾场上的糠秕，被风吹散，无处可寻。打碎这像的石头成了一座大山，覆盖全地。","notes":[]},{"n":36,"t":"“这就是那梦；我们要在王面前讲解那梦。","notes":[]},{"n":37,"t":"你，王啊，你是诸王之王。天上的神已将国度、权势、能力、尊荣都赐给你。","notes":[]},{"n":38,"t":"世人和走兽，并天空的飞鸟，不论居住何处，他都交在你的手中，令你掌管这一切。你就是那金的头。","notes":[]},{"n":39,"t":"在你以后必兴起另一国，不及于你；又有第三国如铜，必掌管全地。","notes":[]},{"n":40,"t":"第四国必坚壮如铁，就像铁能打碎砸碎一切；铁怎样压碎一切，那国也必照样打碎压碎。","notes":[]},{"n":41,"t":"你既看见像的脚和脚趾头，一半是陶匠的泥，一半是铁，那国将来也必分裂。你既看见铁和泥搀杂，那国也必有铁的力量。","notes":[]},{"n":42,"t":"那脚趾头既是半铁半泥，那国也必半强半弱。","notes":[]},{"n":43,"t":"你既看见铁和泥搀杂，他们必有混杂的后裔，却不能彼此相合，正如铁和泥不能相合。","notes":[]},{"n":44,"t":"当诸王在位的时候，天上的神必另立一个永不败坏的国度，这国度必不归给其他百姓，却要打碎灭绝所有的国度，存立到永远。","notes":[]},{"n":45,"t":"你既看见非人手凿出来的一块石头从山而出，打碎铁、铜、泥、银、金，那就是至大的神把将来要发生的事给王指明。这梦是确实的，这解释也是准确的。”","notes":[]},{"n":46,"t":"当时，尼布甲尼撒王脸伏于地，向但以理下拜，并且吩咐人给他奉上供物和香。","notes":[],"heads":["王奖赏但以理"]},{"n":47,"t":"王对但以理说：“你既能讲明这奥秘，你们的神诚然是万神之神、万王之主，是奥秘的启示者。”","notes":[]},{"n":48,"t":"于是王使但以理高升，赏赐他极多的礼物，派他管理巴比伦全省，又立他为总理，掌管巴比伦所有的智慧人。","notes":[]},{"n":49,"t":"但以理求王，王就派沙得拉、米煞、亚伯尼歌管理巴比伦省的事务，只是但以理仍在朝中侍立。","notes":[]}]},"3":{"heading":"尼布甲尼撒下令拜金像","verses":[{"n":1,"t":"尼布甲尼撒王造了一个金像，高六十肘，宽六肘，立在巴比伦省的杜拉平原。","notes":[]},{"n":2,"t":"尼布甲尼撒王差人将总督、钦差、省长、参谋、财务、法官、地方官和各省的官员都召了来，为尼布甲尼撒王所立的像行开光礼。","notes":[]},{"n":3,"t":"于是总督、钦差、省长、参谋、财务、法官、地方官和各省的官员都聚集，站在尼布甲尼撒所立的像前，要为尼布甲尼撒王所立的像行开光礼。","notes":[]},{"n":4,"t":"那时传令的大声呼叫说：“各方、各国、各族的人哪，有命令传给你们：","notes":["“族”：原文是“舌”；下同。"]},{"n":5,"t":"你们一听见角、号、琴、瑟、三角琴、鼓和各样乐器的声音，就当俯伏，拜尼布甲尼撒王所立的金像。","notes":[]},{"n":6,"t":"凡不俯伏下拜的，必立刻扔在烈火的窑中。”","notes":[]},{"n":7,"t":"因此百姓一听见角、号、琴、瑟、三角琴和各样乐器的声音，各方、各国、各族的人就都俯伏，拜尼布甲尼撒王所立的金像。","notes":["有古卷在此有“鼓”。"]},{"n":8,"t":"在那时，有几个迦勒底人进前来控告犹大人。","notes":[],"heads":["但以理的三个朋友被控违令"]},{"n":9,"t":"他们对尼布甲尼撒王说：“愿王万岁！","notes":[]},{"n":10,"t":"你，王啊，你曾降旨，凡听见角、号、琴、瑟、三角琴、鼓和各样乐器声音的，都当俯伏拜这金像。","notes":[]},{"n":11,"t":"凡不俯伏下拜的，必扔在烈火的窑中。","notes":[]},{"n":12,"t":"现在有几个犹大人，就是王所派管理巴比伦省事务的沙得拉、米煞、亚伯尼歌；王啊，这些人不理你的谕旨，不事奉你的神明，也不拜你所立的金像。”","notes":[]},{"n":13,"t":"当时，尼布甲尼撒大发烈怒，命令把沙得拉、米煞、亚伯尼歌带过来；他们就把这几个人带到王面前。","notes":[]},{"n":14,"t":"尼布甲尼撒问他们说：“沙得拉、米煞、亚伯尼歌，你们不事奉我的神明，不拜我所立的金像，是真的吗？","notes":[]},{"n":15,"t":"现在，你们若准备好，一听见角、号、琴、瑟、三角琴、鼓和各样乐器的声音，就俯伏拜我所造的像；若不下拜，必立刻扔在烈火的窑中，有哪一个神明能救你们脱离我的手呢？”","notes":[]},{"n":16,"t":"沙得拉、米煞、亚伯尼歌对王说：“尼布甲尼撒啊，这件事我们不必回答你，","notes":[]},{"n":17,"t":"即便如此，我们所事奉的神能将我们从烈火的窑中救出来。王啊，他必救我们脱离你的手；","notes":[]},{"n":18,"t":"即或不然，王啊，你当知道，我们绝不事奉你的神明，也不拜你所立的金像。”","notes":[]},{"n":19,"t":"当时，尼布甲尼撒怒气填胸，向沙得拉、米煞、亚伯尼歌变了脸色，命令把窑烧热，比平常热七倍；","notes":[],"heads":["但以理的三个朋友被扔进火窑"]},{"n":20,"t":"又命令他军中的几个壮士，把沙得拉、米煞、亚伯尼歌捆起来，扔在烈火的窑中。","notes":[]},{"n":21,"t":"这三人穿着内袍、外衣、头巾和其他的衣服，被捆起来扔在烈火的窑中。","notes":[]},{"n":22,"t":"因为王的命令紧急，窑又非常热，那抬沙得拉、米煞、亚伯尼歌的人都被火焰烧死。","notes":[]},{"n":23,"t":"但是这三个人，沙得拉、米煞、亚伯尼歌被捆绑着，掉进烈火的窑中。","notes":[]},{"n":24,"t":"那时，尼布甲尼撒王惊奇，急忙站起来，对谋士说：“我们捆起来扔在火里的不是三个人吗？”他们回答王说：“王啊，是的。”","notes":[]},{"n":25,"t":"王说：“看哪，我看见有四个人，并没有捆绑，在火中行走，也没有受伤；那第四个的相貌好像神明的儿子。”","notes":[]},{"n":26,"t":"于是尼布甲尼撒靠近烈火窑门，说：“至高神的仆人沙得拉、米煞、亚伯尼歌，出来，来吧！”沙得拉、米煞、亚伯尼歌就从火中出来。","notes":[],"heads":["三人获释且得高升"]},{"n":27,"t":"那些总督、钦差、省长和王的谋士一同聚集来看这三个人，见火不能伤他们的身体，头发没有烧焦，衣裳也没有变色，都没有火烧过的气味。","notes":[]},{"n":28,"t":"尼布甲尼撒说：“沙得拉、米煞、亚伯尼歌的神是应当称颂的！他差遣使者救护倚靠他的仆人，他们不遵王的命令，甚至舍身，在他们神以外不肯事奉敬拜别神。","notes":[]},{"n":29,"t":"现在我降旨，无论何方、何国、何族，凡有人毁谤沙得拉、米煞、亚伯尼歌的神，他必被凌迟，他的房屋必成粪堆，因为没有别神能像这样施行拯救。”","notes":[]},{"n":30,"t":"那时王在巴比伦省使沙得拉、米煞、亚伯尼歌高升。","notes":[]}]},"4":{"heading":"尼布甲尼撒的第二个梦","verses":[{"n":1,"t":"尼布甲尼撒王对住在全地各方、各国、各族的人说：“愿你们大享平安！","notes":[]},{"n":2,"t":"我乐意宣扬至高神向我所行的神迹奇事。","notes":[]},{"n":3,"t":"他的神迹何其大！他的奇事何其盛！他的国度存到永远；他的权柄存到万代！","notes":[]},{"n":4,"t":"“我－尼布甲尼撒安居在家中，在宫里享受荣华。","notes":[]},{"n":5,"t":"我做了一个梦，使我惧怕。我在床上的意念和脑中的异象，使我惊惶。","notes":[]},{"n":6,"t":"因此我降旨召巴比伦的智慧人全都到我面前，要他们将梦的解释告诉我。","notes":[]},{"n":7,"t":"于是那些术士、巫师、迦勒底人、观兆的都进来，我将那梦告诉他们，他们却不能把梦的解释告诉我。","notes":[]},{"n":8,"t":"最后，但以理，就是按照我神明的名字称为伯提沙撒的，来到我面前，他里头有神圣神明的灵，我将梦告诉他：","notes":[]},{"n":9,"t":"‘术士的领袖伯提沙撒啊，我知道你里头有神圣神明的灵，什么奥秘都不能为难你。现在你要把我梦中所见的异象和梦的解释告诉我。’","notes":["“现在...告诉我”：七十士译本是“现在你要听我在梦中所见的异象，把梦的解释告诉我”。"]},{"n":10,"t":"“我在床上脑中的异象是这样：我观看，看哪，大地中间有一棵树，极其高大。","notes":[]},{"n":11,"t":"那树渐长，而且茁壮，高得顶天，从地极都能看见，","notes":[]},{"n":12,"t":"叶子华美，果子甚多，可作所有动物的食物；野地的走兽卧在荫下，天空的飞鸟宿在枝上，凡有血肉的都从这树得食物。","notes":[]},{"n":13,"t":"“我观看，我在床上脑中的异象是这样，看哪，有守望者，就是神圣的一位，从天而降，","notes":[]},{"n":14,"t":"大声呼叫说：‘砍倒这树！砍下枝子！拔掉叶子！抛散果子！使走兽逃离树下，飞鸟躲开树枝。","notes":[]},{"n":15,"t":"树的残干却要留在地里，在田野的青草中用铁圈和铜圈套住。任他让天上的露水滴湿，和地上的走兽一同吃草，","notes":[]},{"n":16,"t":"使他的心改变，不再是人的心，而给他一个兽心，使他经过七个时期。","notes":["“七个时期”或译“七年”；下同。"]},{"n":17,"t":"这是众守望者所发的命令，是众圣者所作的决定，好叫世人知道至高者在人的国中掌权，要将国赐给谁就赐给谁，并且立极卑微的人执掌国权。’","notes":[]},{"n":18,"t":"“这是我－尼布甲尼撒王所做的梦。伯提沙撒啊，你要说明这梦的解释；我国中所有的智慧人都不能把梦的解释告诉我，惟独你能，因你里头有神圣神明的灵。”","notes":[]},{"n":19,"t":"于是称为伯提沙撒的但以理惊骇片时，心意惊惶。王说：“伯提沙撒啊，不要因梦和梦的解释惊惶。”伯提沙撒回答说：“我主啊，愿这梦归给恨恶你的人，这梦的解释归给你的敌人。","notes":[],"heads":["但以理解梦"]},{"n":20,"t":"你所见的树渐长，而且茁壮，高得顶天，全地都能看见，","notes":[]},{"n":21,"t":"叶子华美，果子甚多，可作所有动物的食物；野地的走兽住在其下，天空的飞鸟宿在枝上。","notes":[]},{"n":22,"t":"“王啊，这成长又茁壮的树就是你。你的威势成长及于天，你的权柄达到地极。","notes":[]},{"n":23,"t":"王既看见一位神圣的守望者从天而降，说：‘将这树砍倒毁坏，树的残干却要留在地里，在田野的青草中用铁圈和铜圈套住。任他让天上的露水滴湿，与野地的走兽一同吃草，直到经过七个时期。’","notes":[]},{"n":24,"t":"“王啊，梦的解释就是这样：临到我主我王的事是出于至高者的命令。","notes":[]},{"n":25,"t":"你必被赶出离开世人，与野地的走兽同住，吃草如牛，让天上的露水滴湿，且要经过七个时期，直等到你知道至高者在人的国中掌权，要将国赐给谁就赐给谁。","notes":[]},{"n":26,"t":"这使树的残干存留的命令，是要等你知道天在掌权，你的国必定归你。","notes":[]},{"n":27,"t":"王啊，求你悦纳我的谏言，以施行公义除去罪过，以怜悯穷人除掉罪恶，或者你的平安可以延长。”","notes":[]},{"n":28,"t":"这些事都临到尼布甲尼撒王。","notes":[]},{"n":29,"t":"过了十二个月，他在巴比伦王宫顶上散步。","notes":[]},{"n":30,"t":"王说：“这大巴比伦岂不是我用大能大力建为首都，要显示我威严的荣耀吗？”","notes":[]},{"n":31,"t":"这话还在王口中的时候，有声音从天降下，说：“尼布甲尼撒王啊，有话对你说，你的国离开你了。","notes":[]},{"n":32,"t":"你必被赶出离开世人，与野地的走兽同住，吃草如牛，且要经过七个时期；等你知道至高者在人的国中掌权，要将国赐给谁就赐给谁。”","notes":[]},{"n":33,"t":"当时这话就应验在尼布甲尼撒身上，他被赶出离开世人，吃草如牛，身体被天上的露水滴湿，头发长得像鹰的羽毛，指甲长得像鸟爪。","notes":[]},{"n":34,"t":"“时候到了，我－尼布甲尼撒举目望天，我的知识复归于我，我就称颂至高者，赞美尊敬活到永远的神。他的权柄存到永远，他的国度存到万代。","notes":[],"heads":["尼布甲尼撒颂赞神"]},{"n":35,"t":"地上所有的居民都算为虚无；在天上万军和地上居民中，他都凭自己的旨意行事。无人能拦住他的手，或问他说，你在做什么呢？","notes":[]},{"n":36,"t":"“那时，我的知识复归于我，威严和光荣也复归于我，使我的国度得荣耀，我的谋士和大臣也来朝见我。我又重建我的国度，更大的权势加添在我身上。","notes":[]},{"n":37,"t":"现在我－尼布甲尼撒赞美、尊崇、恭敬天上的王，因为他所行的全都信实，他所做的尽都公平。那行事骄傲的，他能降为卑。”","notes":[]}]},"5":{"heading":"伯沙撒王的宴会","verses":[{"n":1,"t":"伯沙撒王为他的一千大臣摆设盛筵，与这一千人饮酒。","notes":[]},{"n":2,"t":"伯沙撒在欢饮之间，吩咐人将他父尼布甲尼撒从耶路撒冷圣殿所掳掠的金银器皿拿来，好使王与大臣、王后、妃嫔用这器皿饮酒。","notes":["“父”或译“祖”；下同。"]},{"n":3,"t":"于是他们把圣殿，就是耶路撒冷神殿中所掳掠的金器皿拿来，王和大臣、王后、妃嫔就用这器皿饮酒。","notes":[]},{"n":4,"t":"他们饮酒，赞美金、银、铜、铁、木、石造的神明。","notes":[]},{"n":5,"t":"当时，忽然有人的指头出现，在灯台对面王宫粉刷的墙上写字。王看见写字的指头，","notes":[]},{"n":6,"t":"就变了脸色，心意惊惶，腰骨好像脱节，双膝彼此相碰，","notes":[]},{"n":7,"t":"大声吩咐将巫师、迦勒底人和观兆的领进来。王对巴比伦的智慧人说：“谁能读这文字，并且向我讲解它的意思，他必身穿紫袍，项带金链，在我国中位列第三。”","notes":[]},{"n":8,"t":"于是王所有的智慧人都进前来，他们却不能读那文字，也不能为王讲解它的意思。","notes":[]},{"n":9,"t":"伯沙撒王就甚惊惶，脸色改变，他的大臣也都困惑。","notes":[]},{"n":10,"t":"太后因王和他大臣所说的话，就进入宴会厅，说：“愿王万岁！你的心不要惊惶，脸不要变色。","notes":["“太后”或译“王后”；下同。"]},{"n":11,"t":"在你国中有一人，他里头有神圣神明的灵，你父在世的日子，这人心中光明，又有聪明智慧，好像神明的智慧。你父尼布甲尼撒王，就是王的父，曾立他为术士、巫师、迦勒底人和观兆者的领袖，","notes":[]},{"n":12,"t":"都因为他有美好的灵性，又有知识聪明，能解梦，释谜语，解疑惑。这人名叫但以理，尼布甲尼撒王又称他为伯提沙撒，现在可以召他来，他必解明这意思。”","notes":[]},{"n":13,"t":"于是但以理被领到王面前。王问但以理说：“你就是我父王从犹大带来、被掳的犹大人但以理吗？","notes":[],"heads":["但以理解释墙上的字"]},{"n":14,"t":"我听说你里头有神明的灵，心中有光，又有聪明和高超的智慧。","notes":[]},{"n":15,"t":"现在智慧人和巫师都被带到我面前，要叫他们读这文字，为我讲解它的意思；无奈他们都不能讲解它的意思。","notes":[]},{"n":16,"t":"我听说你能讲解，能解疑惑；现在你若能读这文字，为我讲解它的意思，就必身穿紫袍，项戴金链，在我国中位列第三。”","notes":[]},{"n":17,"t":"但以理回答王说：“你的礼物可以归你自己，你的赏赐可以归给别人；我却要为王读这文字，讲解它的意思。","notes":[]},{"n":18,"t":"你，王啊，至高的神曾将国度、大权、荣耀、威严赐给你父尼布甲尼撒；","notes":[]},{"n":19,"t":"因神所赐给他的大权，各方、各国、各族的人都在他面前恐惧战兢，因他要杀就杀，要人活就活，要升就升，要降就降。","notes":[]},{"n":20,"t":"但他的心高傲，灵也刚愎，以致行事狂傲，就被革去国度的王位，夺走荣耀。","notes":[]},{"n":21,"t":"他被赶出离开世人，他的心变为兽心，与野驴同住，吃草如牛，身体被天上的露水滴湿，直到他知道，至高的神在人的国中掌权，凭自己的旨意立人治国。","notes":[]},{"n":22,"t":"伯沙撒啊，你是他的儿子，你虽知道这一切，却不谦卑自己，","notes":["“儿子”或译“孙子”。"]},{"n":23,"t":"竟向天上的主自高，差人将他殿中的器皿拿到你面前，你和大臣、王后、妃嫔用这器皿饮酒。你又赞美那不能看、不能听、无知无识，用金、银、铜、铁、木、石造的神明，没有将荣耀归与那手中掌管你气息，管理你一切行动的神。","notes":[]},{"n":24,"t":"于是从他那里显出指头写这文字。","notes":[]},{"n":25,"t":"“所写的文字是：‘弥尼，弥尼，提客勒，乌法珥新。’","notes":["“乌法珥新”：亚兰文音译；原文另译“以及毗勒斯”；参28节。"]},{"n":26,"t":"解释是这样：弥尼就是神数算你国的年日到此完毕。","notes":[]},{"n":27,"t":"提客勒就是你被秤在天平上，秤出你的亏欠来。","notes":[]},{"n":28,"t":"毗勒斯就是你的国要分裂，归给玛代人和波斯人。”","notes":["“毗勒斯”与“乌法珥新”同义。"]},{"n":29,"t":"于是伯沙撒下令，人就把紫袍给但以理穿上，把金链给他戴在颈项上，又传令使他在国中位列第三。","notes":[]},{"n":30,"t":"当夜，迦勒底王伯沙撒被杀。","notes":[]},{"n":31,"t":"玛代人大流士年六十二岁，取了迦勒底国。","notes":[]}]},"6":{"heading":"但以理在狮子坑中","verses":[{"n":1,"t":"大流士随心所愿，立了一百二十个总督，治理全国，","notes":[]},{"n":2,"t":"又在他们以上立总长三人，但以理也在其中；使总督在他们三人面前呈报，免得王受亏损。","notes":[]},{"n":3,"t":"这但以理因有卓越的灵性，超乎其余的总长和总督，王想立他治理全国。","notes":[]},{"n":4,"t":"那时，总长和总督在治国的事务上寻找但以理的把柄，为要控告他；只是找不到任何的把柄和过失，因他忠心办事，毫无错误过失。","notes":[]},{"n":5,"t":"那些人就说：“我们要找但以理的把柄，若不从他神的律法中下手，就寻不着。”","notes":[]},{"n":6,"t":"于是，总长和总督纷纷聚集来见王，说：“大流士王万岁！","notes":[]},{"n":7,"t":"国中的总长、钦差、总督、谋士和省长彼此商议，求王下旨，立一条禁令，三十天之内，不拘何人，若在王以外，或向神明或向人求什么，就必扔在狮子坑中。","notes":[]},{"n":8,"t":"王啊，现在求你立这禁令，在这文件上签署，使它不能更改；照玛代人和波斯人的例，绝不更动。”","notes":[]},{"n":9,"t":"于是大流士王在这禁令的文件上签署。","notes":[]},{"n":10,"t":"但以理知道这文件已经签署，就进自己的家，他家楼上的窗户开向耶路撒冷。他一天三次，双膝跪着，在他的神面前祷告感谢，像平常一样。","notes":[]},{"n":11,"t":"于是，那些人纷纷聚集，发现但以理在他神面前祈祷恳求。","notes":[]},{"n":12,"t":"他们就进到王面前，向王提及禁令，说：“三十天之内不拘何人，若在王以外，或向神明或向人求什么，必被扔在狮子坑中，王不是在这禁令上签署了吗？”王回答说：“确有这事，照玛代人和波斯人的例是不可更改的。”","notes":[]},{"n":13,"t":"他们对王说：“王啊，那被掳的犹大人但以理不理会你，也不遵守你签署的禁令，竟一天三次祈祷。”","notes":[]},{"n":14,"t":"王听见这话，就甚愁烦，一心要救但以理，直到日落的时候，他还在筹划解救他。","notes":[]},{"n":15,"t":"那些人就纷纷聚集到王那里，对王说：“王啊，当知道玛代人和波斯人有例，凡王所立的禁令和律例都不可更改。”","notes":[]},{"n":16,"t":"于是王下令，人就把但以理带来，扔在狮子坑中。王对但以理说：“你经常事奉的神，他必拯救你。”","notes":[]},{"n":17,"t":"有人搬来一块石头放在坑口，王用自己的玺和大臣的印，封闭那坑，使惩办但以理的事绝不更改。","notes":[]},{"n":18,"t":"王回到宫里，终夜禁食，不让人带乐器到他面前，他也失眠了。","notes":["“乐器”或译“跳舞的女子”或“食物”。"]},{"n":19,"t":"次日黎明，王起来，急忙往狮子坑那里去，","notes":[]},{"n":20,"t":"临近坑边，哀声呼叫但以理。王对但以理说：“永生神的仆人但以理啊，你经常事奉的神能救你脱离狮子吗？”","notes":[]},{"n":21,"t":"但以理对王说：“愿王万岁！","notes":[]},{"n":22,"t":"我的神差遣使者封住狮子的口，叫狮子不伤我，因我在神面前无辜。王啊，在你面前我也没有做过任何亏损的事。”","notes":[]},{"n":23,"t":"王因此就甚喜乐，吩咐把但以理从坑里拉上来。于是但以理从坑里被拉上来，身上毫无损伤，因为他信靠他的神。","notes":[]},{"n":24,"t":"王下令，把那些控告但以理的人和他们的妻子儿女都带来，扔在狮子坑中。他们还没有到坑底，狮子就制伏他们，咬碎他们的骨头。","notes":[]},{"n":25,"t":"于是，大流士王传旨给住在全地各方、各国、各族的人说：“愿你们大享平安！","notes":[]},{"n":26,"t":"现在我降旨，我所统辖全国的人民，都要在但以理的神面前战兢畏惧。因为他是活的神，永远长存，他的国度永不败坏，他的权柄永存无极！","notes":[]},{"n":27,"t":"他庇护，搭救，在天上地下施行神迹奇事，救了但以理脱离狮子的口。”","notes":[]},{"n":28,"t":"如此，这但以理，当大流士在位的时候和波斯的居鲁士在位的时候，大享亨通。","notes":[]}]},"7":{"heading":"但以理叙述异象","verses":[{"n":1,"t":"巴比伦王伯沙撒元年，但以理在床上做梦，脑中看见异象，就记录这梦，述说其中的大意。","notes":[],"heads":["四兽的异象"]},{"n":2,"t":"但以理说：我在夜间的异象中观看，看哪，天上四风，突然刮在大海之上。","notes":[]},{"n":3,"t":"有四只巨兽从海里上来，它们各不相同：","notes":[]},{"n":4,"t":"头一个像狮子，有鹰的翅膀；我正观看的时候，它的翅膀被拔去，它从地上被扶起来，用两脚站立，像人一样，还给了它人的心。","notes":[]},{"n":5,"t":"看哪，另有一兽如熊，就是第二兽，半身侧立，口里的牙齿中有三根獠牙。有人吩咐这兽说：“起来，吞吃许多的肉。”","notes":["“獠牙”或译“肋骨”。"]},{"n":6,"t":"其后，我观看，看哪，另有一兽如豹，背上有四个鸟的翅膀；这兽有四个头，还给了它权柄。","notes":[]},{"n":7,"t":"其后，我在夜间的异象中观看，看哪，第四兽可怕可惧，极其强壮，有大铁牙，吞吃嚼碎，剩下的用脚践踏。这兽与前面所有的兽不同，它有十只角。","notes":[]},{"n":8,"t":"我正思考这些角的时候，看哪，其中又长出另一只小角；先前的角中有三只角在它面前连根被拔出。看哪，这角有眼，像人的眼，有口说夸大的话。","notes":[]},{"n":9,"t":"我正观看的时候，有宝座设立，上面坐着亘古常在者。他的衣服洁白如雪，头发如纯净的羊毛。宝座是火焰，其轮为烈火。","notes":[],"heads":["永存者的异象"]},{"n":10,"t":"有火如河涌出，从他面前流出来；事奉他的有千千，在他面前侍立的有万万；他坐着要行审判，案卷都展开了。","notes":["“他坐着要行审判”或译“审判即将开始”；26节同。"]},{"n":11,"t":"于是我观看，因这角说夸大的话，我正观看的时候，那兽被杀，身体被毁，扔在火中焚烧。","notes":[]},{"n":12,"t":"其余的兽，权柄都被夺去，生命却得以延续，直到所定的时候和日期。","notes":[]},{"n":13,"t":"我在夜间的异象中观看，看哪，有一位像人子的，驾着天上的云而来，被领到亘古常在者面前。","notes":[]},{"n":14,"t":"他得了权柄、荣耀、国度，使各方、各国、各族的人都事奉他。他的权柄是永远的，不能废去，他的国度必不败坏。","notes":[]},{"n":15,"t":"至于我－但以理，我的灵在我里面忧伤，我脑中的异象使我惊惶。","notes":[],"heads":["解释异象"]},{"n":16,"t":"我走近其中一位侍立者，问他这一切的实情。他就告诉我，使我知道这事的解释：","notes":[]},{"n":17,"t":"这四只巨兽就是将要在世上兴起的四个王。","notes":["“王”：有古卷、七十士译本和其他古译本是“国度”。"]},{"n":18,"t":"然而，至高者的众圣者必要得到这国度，并且拥有它，直到永远，永永远远。","notes":[]},{"n":19,"t":"于是我想要更清楚知道第四兽的实情，它与一切的兽不同，甚是可怕，有铁牙铜爪，吞吃嚼碎，剩下的用脚践踏；","notes":[]},{"n":20,"t":"头上有十只角和那另长出的一角，三只角在这角面前掉落；这角有眼，有口说夸大的话，形状比它的同类更强。","notes":[]},{"n":21,"t":"我观看，这角与众圣者争战，胜了他们，","notes":[]},{"n":22,"t":"直到亘古常在者来到，为至高者的众圣者伸冤，众圣者得到国度的时候就到了。","notes":[]},{"n":23,"t":"那侍立者这样说：第四兽就是世上要兴起的第四国，与其他各国不同，它要并吞全地，并且践踏嚼碎。","notes":[]},{"n":24,"t":"至于那十只角，就是从这国中兴起的十个王；后来又兴起另一王，与先前的不相同，他要制伏三个王。","notes":[]},{"n":25,"t":"他说话抵挡至高者，折磨至高者的众圣者，又改变节期和律法。众圣者要交在他手中一年、两年、又半年。","notes":["“年”或译“时期”；下同。"]},{"n":26,"t":"然而，他坐着要行审判；他的权柄要被夺去，毁坏，灭绝，一直到底。","notes":[]},{"n":27,"t":"国度、权柄和天下诸国的大权必赐给至高者的众圣民。他的国是永远的国，所有掌权的都必事奉他，顺从他。","notes":[]},{"n":28,"t":"这事到此结束。我－但以理因这些念头甚是惊惶，脸色也变了，却将这事记在心里。","notes":[]}]},"8":{"heading":"公绵羊、公山羊的异象","verses":[{"n":1,"t":"伯沙撒王在位第三年，有异象向我－但以理显现，是在先前所见的异象之后。","notes":[]},{"n":2,"t":"我在异象中观看，见自己在以拦省书珊的城堡中；我在异象中又见自己在乌莱河边。","notes":[]},{"n":3,"t":"我举目观看，看哪，有一只公绵羊站在河边，它有两只角，这两角都高，一角高过另一角，后长出来的比较高。","notes":[]},{"n":4,"t":"我见那公绵羊向西、向北、向南抵撞，没有任何兽在它面前站立得住，没有能逃脱它手的；它任意而行，自高自大。","notes":[]},{"n":5,"t":"我正思想的时候，看哪，有一只公山羊从西而来，遍行全地，脚不着地。这山羊两眼当中有一只显眼的角。","notes":[]},{"n":6,"t":"它往我先前所见、站在河边、有双角的公绵羊那里，以猛烈的怒气向它直闯。","notes":[]},{"n":7,"t":"我见公山羊靠近公绵羊，向它发怒，攻击它，折断它的两角。公绵羊在公山羊面前站立不住；它把公绵羊撞倒在地，用脚践踏，没有能救公绵羊脱离它手的。","notes":[]},{"n":8,"t":"这公山羊长得极其高大，正强壮的时候，那大角折断了，从角的下面向天的四方长出四只显眼的角来。","notes":["“方”：原文是“风”。"]},{"n":9,"t":"从四角中的一角又长出另一只小角，向南、向东、向佳美之地，日渐壮大。","notes":[]},{"n":10,"t":"它渐壮大，高及诸天万象，把一些天象和星辰摔落在地，用脚践踏。","notes":[]},{"n":11,"t":"它自高自大，自以为高及万象之君，它除掉经常献给君的祭，毁坏君的圣所。","notes":["“它自高自大”：原文另译“它被高举”。"]},{"n":12,"t":"因罪过的缘故，有军队和经常献的祭交给它。它把真理抛在地上，任意而行，无往不利。","notes":["“它把真理...任意而行”：有古卷是“真理被抛在地上，它任意而行”。"]},{"n":13,"t":"我听见有一位圣者说话，又有一位圣者向那说话的圣者说：“这经常献的祭、带来荒凉的罪过、圣所与军队被践踏的异象，要持续到几时呢？”","notes":[]},{"n":14,"t":"他对我说：“要到二千三百日，圣所就必洁净。”","notes":["“我”：七十士译本和其他古译本是“他”。","“洁净”或译“重行奉献礼”。"]},{"n":15,"t":"我－但以理见了这异象，想要明白其中的意思。看哪，有一位形状像人的站在我面前。","notes":[],"heads":["天使加百列解释异象"]},{"n":16,"t":"我听见乌莱河中有人声呼叫说：“加百列啊，要使这人明白这异象。”","notes":[]},{"n":17,"t":"他就来到我所站的地方。他一来，我就惊慌，脸伏于地。他对我说：“人子啊，你要明白，因为这是关乎末后时期的异象。”","notes":[]},{"n":18,"t":"他对我说话的时候，我在沉睡，脸伏于地。他就摸我，扶我站起来。","notes":[]},{"n":19,"t":"他说：“看哪，我要指示你恼怒结束的时候必成的事，因为这是关乎末后指定的时期。","notes":[]},{"n":20,"t":"你所看见那有双角的公绵羊就是玛代王和波斯王。","notes":[]},{"n":21,"t":"那公山羊就是希腊王；两眼当中的大角就是第一个王。","notes":["“希腊”：原文是“雅完”；本卷书下同。"]},{"n":22,"t":"至于角折断了，又从角的下面长出四只角，意思就是有四个国要从这国兴起，只是权势都不及它。","notes":[]},{"n":23,"t":"这四国末期，恶贯满盈的时候，必有一王兴起，面貌凶恶，诡计多端。","notes":[]},{"n":24,"t":"他的权柄极大，却不是因自己的能力；他要施行惊人的毁灭，无往不利，任意而行，又要毁灭强有力的人和众圣民。","notes":[]},{"n":25,"t":"他用权术使手中的诡计成功；他的心自高自大，趁人无备的时候毁灭多人。他又起来攻击万君之君，至终却非因人的手而遭毁灭。","notes":[]},{"n":26,"t":"所说二千三百日的异象是真的，但你要将这异象封住，因为它关乎未来许多的日子。”","notes":["“二千三百日”：参8．14；原文是“晚上和早上”，指的是晚祭和早祭。"]},{"n":27,"t":"于是我－但以理昏倒，病了数日，然后起来办理王的事务。我因这异象惊骇不已，但还是不能了解。","notes":[]}]},"9":{"heading":"但以理为同胞祷告","verses":[{"n":1,"t":"玛代族亚哈随鲁的儿子大流士被立为王，统治迦勒底国元年，","notes":[]},{"n":2,"t":"就是他在位第一年，我－但以理从书上得知，耶和华的话临到耶利米先知，论耶路撒冷荒凉期满的年数为七十年。","notes":[]},{"n":3,"t":"我面向主神，禁食，披麻蒙灰，恳切祷告祈求。","notes":[]},{"n":4,"t":"我向耶和华－我的神祈祷、认罪，说：“主啊，你是大而可畏的神，向爱主、守主诫命的人守约施慈爱。","notes":[]},{"n":5,"t":"我们犯罪作恶，行恶叛逆，偏离你的诫命典章，","notes":[]},{"n":6,"t":"没有听从你仆人众先知奉你的名向我们君王、官长、祖先和这地所有百姓所说的话。","notes":[]},{"n":7,"t":"主啊，你是公义的，但我们犹大人和耶路撒冷的居民，并你所赶到各国的以色列众人，不论远近，因为背叛了你，脸上蒙羞，正如今日一样。","notes":[]},{"n":8,"t":"耶和华啊，我们和我们的君王、官长、祖先因得罪了你，脸上就都蒙羞。","notes":[]},{"n":9,"t":"主－我们的神是怜悯饶恕人的，我们却违背了他，","notes":[]},{"n":10,"t":"没有听从耶和华－我们神的话，没有遵行他藉仆人众先知向我们颁布的律法。","notes":[]},{"n":11,"t":"以色列众人都犯了你的律法，偏离、不听从你的话；因此，你仆人摩西律法上所写的诅咒和誓言倾倒在我们身上，因我们得罪了神。","notes":[]},{"n":12,"t":"神使大灾祸临到我们，实现了警戒我们和审判我们官长的话；原来耶路撒冷所遭遇的灾祸是普天之下未曾有过的。","notes":[]},{"n":13,"t":"这一切灾祸临到我们，是照摩西律法上所写的，我们却没有求耶和华－我们神的恩惠，使我们回转离开罪孽，明白你的真理。","notes":[]},{"n":14,"t":"所以耶和华特意使这灾祸临到我们，耶和华－我们的神在他所行的事上都是公义的；我们并没有听从他的话。","notes":[]},{"n":15,"t":"主－我们的神啊，你曾用大能的手领你的子民出埃及地，使自己得了名声，正如今日一样，现在，我们犯了罪，作了恶。","notes":[]},{"n":16,"t":"主啊，求你按你丰盛的公义，使你的怒气和愤怒转离你的城耶路撒冷，就是你的圣山。因我们的罪恶和我们祖先的罪孽，耶路撒冷和你的子民被四围的人羞辱。","notes":[]},{"n":17,"t":"我们的神啊，现在求你垂听你仆人的祈祷恳求，为你自己的缘故使你的脸向荒凉的圣所发光。","notes":[]},{"n":18,"t":"我的神啊，求你侧耳而听，睁眼而看，眷顾我们那荒凉之地和称为你名下的城。我们在你面前恳求，不是因自己的义，而是因你丰富的怜悯。","notes":[]},{"n":19,"t":"主啊，求你垂听！主啊，求你赦免！主啊，求你侧耳，求你实行！为你自己的缘故不要迟延。我的神啊，因这城和这民都是称为你名下的。”","notes":[]},{"n":20,"t":"我正说话、祷告，承认我的罪和我百姓以色列的罪，为我神的圣山，在耶和华－我的神面前恳求；","notes":[],"heads":["加百列解释预言"]},{"n":21,"t":"我正在祷告中说话，先前在异象中所见的那位加百列，约在献晚祭的时候迅速飞到我这里来。","notes":[]},{"n":22,"t":"他指教我说：“但以理啊，现在我来要使你有智慧，有聪明。","notes":["“他指教我说”：七十士译本和其他古译本是“他来对我说”。"]},{"n":23,"t":"你刚开始恳求的时候，就有命令发出。现在我来告诉你，因你是蒙爱的；所以你要思想这事，明白这异象。","notes":[]},{"n":24,"t":"“为你百姓和你圣城，已经定了七十个七，要止住罪过，除净罪恶，赎尽罪孽，引进永恒的公义，封住异象和预言，并膏至圣所。","notes":["“至圣所”或译“至圣者”。"]},{"n":25,"t":"你当知道，当明白，从发出命令恢复并重建耶路撒冷，直到受膏的君出现，必有七个七和六十二个七。耶路撒冷城连街带濠都必在艰难中恢复并重建。","notes":[]},{"n":26,"t":"过了六十二个七，那受膏者被剪除，一无所有；必有一王的百姓来毁灭这城和圣所，它的结局必如洪水冲没。必有战争，一直到末了，荒凉的事已经定了。","notes":["“那受膏者”或译“有受膏者”。","“它的结局”或译“他的结局”。"]},{"n":27,"t":"在一七之期，他必与许多人坚立盟约；一七之半，他必使献祭与供献止息。那施行毁灭的可憎之物必立在圣殿里，直到所定的结局倾倒在那行毁灭者的身上。”","notes":["“圣殿里”是根据七十士译本；原文是“翅膀上”。"]}]},"10":{"heading":"底格里斯河边的异象","verses":[{"n":1,"t":"波斯王居鲁士第三年，有话指示那称为伯提沙撒的但以理。这话是确实的，指着大战争；但以理明白这话，明白这异象。","notes":[]},{"n":2,"t":"那时，我－但以理悲伤了三个七日；","notes":[]},{"n":3,"t":"美味我没有吃，酒和肉没有入我的口，也没有用油抹我的身，直到满了三个七日。","notes":[]},{"n":4,"t":"正月二十四日，我在大河，就是底格里斯河边，","notes":[]},{"n":5,"t":"举目观看，看哪，有一人身穿细麻衣，腰束乌法的纯金腰带。","notes":[]},{"n":6,"t":"他的身体如水苍玉，面貌如闪电，眼目如火把，手臂和脚如明亮的铜，说话的声音像众人的声音。","notes":[]},{"n":7,"t":"我－但以理一人看见这异象，跟我一起的人没有看见，却有极大的战兢落在他们身上，他们就逃跑躲避，","notes":[]},{"n":8,"t":"只剩下我一人。我看见这大异象就浑身无力，面容变色，毫无气力。","notes":[]},{"n":9,"t":"我听见他说话的声音；一听见他说话的声音，我就沉睡，脸伏于地。","notes":[]},{"n":10,"t":"看哪，有一只手摸我，使我膝盖和手掌战抖。","notes":[]},{"n":11,"t":"他对我说：“蒙爱的但以理啊，要思想我对你所说的话，只管站起来，因为我现在奉差遣来到你这里。”他对我说这话，我就战战兢兢地站起来。","notes":[]},{"n":12,"t":"他说：“但以理啊，不要惧怕！因为自从第一日你立志要明白，又在你神面前刻苦自己，你的话已蒙应允；我就是因你的话而来。","notes":[]},{"n":13,"t":"但波斯国的领袖拦阻了我二十一天。看哪，天使长中的一位米迦勒来帮助我，因为我被留在波斯诸王那里。","notes":["“天使长”：原文是“领袖之首”。"]},{"n":14,"t":"现在我来，要使你明白你百姓日后必遭遇的事，因为这异象关乎未来的日子。”","notes":[]},{"n":15,"t":"他向我这样说，我就脸面朝地，哑口无声。","notes":[]},{"n":16,"t":"看哪，有一位形状像人的，摸我的嘴唇，我就开口说话，向那站在我面前的说：“我主啊，因这异象使我感到剧痛，毫无气力。","notes":[]},{"n":17,"t":"我主的仆人怎能跟我主说话呢？我现在浑身无力，毫无气息。”","notes":[]},{"n":18,"t":"有一位形状像人的再一次摸我，使我有力量。","notes":[]},{"n":19,"t":"他说：“蒙爱的人哪，不要惧怕，愿你平安！你要刚强！要刚强！”他一对我说话，我就觉得有力量，说：“我主请说，因你使我有力量。”","notes":["“你要刚强！要刚强！”：有古卷是“你要刚强壮胆！”"]},{"n":20,"t":"他说：“你知道我为什么到你这里来吗？现在我要回去与波斯的领袖争战，我去了之后，看哪，希腊的领袖必来。","notes":[]},{"n":21,"t":"但我要将那记录在真理之书上的话告诉你。除了你们的天使米迦勒之外，没有人帮助我抵挡他们。”","notes":[]}]},"11":{"heading":"南方王和北方王","verses":[{"n":1,"t":"“至于我，当玛代的大流士元年，我曾起来扶助米迦勒，使他坚强。","notes":[]},{"n":2,"t":"现在我要指示你确实的事。”“看哪，波斯还有三个王要兴起，第四王必富足远胜诸王。他因富足成为强盛，就必煽动各国攻击希腊国。","notes":[]},{"n":3,"t":"必有一个勇敢的王兴起，执掌大权，随意而行。","notes":[]},{"n":4,"t":"他正兴起的时候，他的国必瓦解，向天的四方裂开，却不归他的后裔，也不如他当年统治的权威；他的国必被拔出，归给他后裔之外的人。","notes":["“方”：原文是“风”。"]},{"n":5,"t":"“南方的王必强盛，他的将帅中必有一个比他更强，执掌权柄，权柄甚大。","notes":[]},{"n":6,"t":"过了几年，他们必结盟，南方王的女儿必来到北方王那里，使约生效；但这女子不能保留实力，王的力量也未能存留。这女子、带她来的、生她的和当时扶助她的必被杀害。","notes":["“力量”：七十士译本和其他古译本是“后裔”。","“生她的”：有古译本是“她的孩子”。","“被杀害”：原文是“被交出来”。"]},{"n":7,"t":"但从这女子的本家必另有一子接续王位，他要率领军队进入北方王的堡垒，攻击他们，而且得胜，","notes":["“本家必另有一子”：原文是“根必另生一枝”。"]},{"n":8,"t":"把他们的神像和铸成的偶像，与金银宝器都掳掠到埃及去。数年之内，他不去攻击北方的王。","notes":[]},{"n":9,"t":"北方的王必侵入南方王的国土，但却要撤回本地。","notes":[]},{"n":10,"t":"“北方王的儿子们必动干戈，招聚许多军兵。他要前进，如洪水泛滥；要再度争战，直捣南方王的堡垒。","notes":[]},{"n":11,"t":"南方王必发烈怒，出来与北方王争战，摆列大军；北方王的军兵必败在南方王的手下。","notes":[]},{"n":12,"t":"这大军既被扫荡，南方王的心就自高；他虽使万人仆倒，却不能保持胜利。","notes":[]},{"n":13,"t":"“北方王要再度摆列大军，比先前更多。过了几年，他必率领大军，带极多的装备而来。","notes":[]},{"n":14,"t":"那时，必有许多人起来攻击南方王，并且你百姓中的残暴人要兴起，应验异象，他们却要败亡。","notes":[]},{"n":15,"t":"北方王必来建土堆攻取坚固城，南方的军兵抵挡不住，就是精选的部队也无力抵挡；","notes":[]},{"n":16,"t":"前来攻击南方王的必任意而行，无人在北方王面前站立得住。他要站在那佳美之地，用手施行毁灭。","notes":[]},{"n":17,"t":"“他必定意倾全国之力而来，与南方王订约，把自己的女儿给南方王为妻，企图败坏他的国度。这计谋却未得逞，自己也得不到好处。","notes":["“自己的女儿”：原文是“妇人的女儿 ”。"]},{"n":18,"t":"其后北方王必转头，夺取许多海岛。但有一将帅除掉北方王对人的羞辱，并且使羞辱归到他自己身上。","notes":[]},{"n":19,"t":"他必转头回到本地的堡垒，却要绊跌仆倒，归于无有。","notes":[]},{"n":20,"t":"“那时，有一人兴起接续他的王位，他为了王国的荣华，差官员横征暴敛。这王过不多时就死了，不是因怒气，也不是因战役。”","notes":["“怒气”或译“面对面的搏斗”。"]},{"n":21,"t":"“后来，有一个卑鄙的人兴起接续他的王位，人未曾将国的尊荣给他，他却趁人无备的时候前来，用诡诈夺取政权。","notes":[],"heads":["北方的恶王"]},{"n":22,"t":"势如洪水般的军兵在他面前被冲没，遭击溃；立约的领袖也是如此。","notes":[]},{"n":23,"t":"他与人结盟之后，却行诡诈。跟随他的人虽不多，他却日渐强盛。","notes":[]},{"n":24,"t":"他趁人无备的时候，来到国中极肥沃之地，做他祖宗和祖宗的祖宗未曾做过的事，瓜分掳物、掠物和财宝，又策划进攻堡垒；然而这都是暂时的。","notes":[]},{"n":25,"t":"“他必奋勇向前，率领大军攻击南方王；南方王以极强的大军迎战，却抵挡不住，因为有人设计谋害南方王。","notes":[]},{"n":26,"t":"吃王饷的使王败坏，王的军队必被冲没，仆倒被杀的甚多。","notes":[]},{"n":27,"t":"至于这二王，他们心怀恶计，同席吃饭却彼此说谎，但计谋不成，因为结局要在指定的时期来到。","notes":[]},{"n":28,"t":"北方王必带许多财宝回本地，但他的心反对圣约；他恣意横行，回到本地。","notes":[]},{"n":29,"t":"“到了指定的时期，他必返回，侵入南方。这一次却不像前一次，","notes":[]},{"n":30,"t":"因为基提的战船要来攻击他，他就丧胆而退。他恼恨圣约，恣意横行，要回来善待那些背弃圣约的人。","notes":[]},{"n":31,"t":"他要兴兵，这兵必亵渎圣所，就是堡垒，除掉经常献的祭，设立那施行毁灭的可憎之物。","notes":[]},{"n":32,"t":"他必用巧言奉承违背圣约的恶人；惟独认识神的子民必刚强行事。","notes":[]},{"n":33,"t":"民间的智慧人必训诲许多人，然而在一段日子里，他们必因刀剑、火烧、掳掠、抢夺而仆倒。","notes":[]},{"n":34,"t":"他们仆倒的时候，会得到少许援助，却有许多人用诡诈加入他们。","notes":[]},{"n":35,"t":"智慧人中有些人仆倒，为要使他们受熬炼，成为洁净、洁白，直到末了；因为还有一段日子才到所定的时期。","notes":[]},{"n":36,"t":"“王必任意而行，自高自大，超过所有的神明，又用荒谬的话攻击万神之神。他必行事亨通，直到主的愤怒结束，因为所定的事必然实现。","notes":[]},{"n":37,"t":"他不顾他祖宗的神明，也不顾妇女所仰慕的神明，任何神明他都不顾；因为他自大，高过一切，","notes":[]},{"n":38,"t":"以敬奉堡垒的神明取而代之，用金、银、宝石和珍宝敬奉他祖宗所不认识的神明。","notes":[]},{"n":39,"t":"他靠外邦神明的帮助，攻破最坚固的堡垒。凡承认他的，他要给他们许多尊荣，使他们管辖许多人，又分封土地作为报偿。","notes":[]},{"n":40,"t":"“到末了，南方王要与北方王交战。北方王要用战车、骑兵和许多战船，势如暴风来攻击他，又要侵入列国，如洪水泛滥。","notes":[]},{"n":41,"t":"他要侵入那佳美之地，许多国就被倾覆，但以东人、摩押人和大半的亚扪人必逃离他的手。","notes":["“许多国就被倾覆”：原文另译“千万人要伤亡”。","“大半的”：有古译本是“残余的”。"]},{"n":42,"t":"他要伸手攻击列国，连埃及地也不得逃脱。","notes":[]},{"n":43,"t":"他要掌管埃及的金银财宝和各样珍宝，路比人和古实人都跟从他的脚步。","notes":["“路比”就是利比亚。","“古实”包括苏丹的大部分和埃塞俄比亚的一部分。"]},{"n":44,"t":"但从东方和北方必有消息传来扰乱他，他就大发烈怒出去，要将许多人杀灭净尽。","notes":[]},{"n":45,"t":"他要在海和荣美的圣山之间搭起王宫的帐幕；然而他的结局到了，无人能帮助他。”","notes":[]}]},"12":{"heading":"末日","verses":[{"n":1,"t":"“那时，保佑你百姓的天使长米迦勒必站起来，并且有大艰难，自从有国以来直到此时，未曾有过这样的事。那时，你的百姓凡记录在册上的，必得拯救。","notes":["“天使长”：原文是“大领袖”。"]},{"n":2,"t":"睡在地里尘埃中的必有多人醒过来；其中有得永生的，有受羞辱永远被憎恶的。","notes":[]},{"n":3,"t":"智慧人要发光，如同天上的光；那领许多人归于义的必发光如星，直到永永远远。","notes":[]},{"n":4,"t":"但以理啊，你要隐藏这话，封闭这书，直到末时。必有许多人往来奔跑，知识就必增长。”","notes":["“往来奔跑”或译“悉心研究”。","“知识”：原文另译“邪恶”；七十士译本是“不义”。"]},{"n":5,"t":"我－但以理观看，看哪，另有两个人站立：一个在河这边，一个在河那边。","notes":[]},{"n":6,"t":"其中一个对那在河水之上、穿细麻衣的说：“这奇异的事要到几时才应验呢？”","notes":[]},{"n":7,"t":"我听见那在河水之上、穿细麻衣的，向天举起左右手，指着那活到永远的起誓说：“要到一年、两年，又半年，粉碎圣民力量结束的时候，这一切的事就要应验。”","notes":["“年”或译“时期”；下同。"]},{"n":8,"t":"我听了却不明白，就说：“我主啊，这些事的结局是怎样呢？”","notes":[]},{"n":9,"t":"他说：“但以理，去吧！因为这话已经隐藏封闭，直到末时。","notes":[]},{"n":10,"t":"必有许多人使自己洁净、洁白，且受熬炼；但恶人仍必行恶，没有一个恶人明白，惟独智慧人能明白。","notes":[]},{"n":11,"t":"从除掉经常献的祭，设立那施行毁灭的可憎之物的时候起，必有一千二百九十日。","notes":[]},{"n":12,"t":"那等候，直到一千三百三十五日的有福了。","notes":[]},{"n":13,"t":"“至于你，你要去等候结局。你必安息，到了末期，你必起来，享受你的福分。”","notes":[]}]}},"HOS":{"1":{"heading":"何西阿的妻子和儿女","verses":[{"n":1,"t":"当乌西雅、约坦、亚哈斯、希西家作犹大王，约阿施的儿子耶罗波安作以色列王的时候，耶和华的话临到备利的儿子何西阿。","notes":[]},{"n":2,"t":"耶和华初次向何西阿说话。耶和华对他说：“你去娶一个淫荡的女子为妻，收那从淫乱所生的儿女；因为这地行大淫乱，离弃耶和华。”","notes":[]},{"n":3,"t":"于是，何西阿去娶了滴拉音的女儿歌篾。她就怀孕，为何西阿生了一个儿子。","notes":[]},{"n":4,"t":"耶和华对何西阿说：“给他起名叫耶斯列；因为再过片时，我要惩罚耶户家在耶斯列流人血的罪，也必终结以色列家的王朝。","notes":["“耶斯列”意思是“神栽种”；2．22同。"]},{"n":5,"t":"到那日，我必在耶斯列平原折断以色列的弓。”","notes":[]},{"n":6,"t":"歌篾又怀孕，生了一个女儿，耶和华对何西阿说：“给她起名叫罗．路哈玛；因为我必不再怜悯以色列家，绝不赦免他们。","notes":["“罗．路哈玛”意思是“不蒙怜悯”；2．23同。"]},{"n":7,"t":"我却要怜悯犹大家，使他们靠耶和华－他们的神得救；我必不让他们靠弓、刀、战争、马匹与骑兵得救。”","notes":[]},{"n":8,"t":"歌篾在罗．路哈玛断奶以后，又怀孕生了一个儿子。","notes":[]},{"n":9,"t":"耶和华说：“给他起名叫罗．阿米；因为你们不是我的子民，我也不是你们的神。”","notes":["“罗．阿米”意思是“非我民”；2．23同。","原文没有“神”。"]},{"n":10,"t":"然而，以色列的人数必多如海沙，不可量，不可数。从前在什么地方对他们说“你们不是我的子民”，将来就在那里称他们为“永生神的儿子”。","notes":[],"heads":["以色列将要复兴"]},{"n":11,"t":"犹大人和以色列人要一同聚集，为自己设立一个“头”，从这地上来，因为耶斯列的日子必为大日。","notes":[]}]},"2":{"heading":"不贞的歌篾－不忠的以色列","verses":[{"n":1,"t":"你们要称你们的众弟兄为阿米，称你们的众姊妹为路哈玛。","notes":["“众弟兄”：七十士译本是“弟兄”。","“阿米”意思是“我民”。","“众姊妹”：七十士译本和其他古译本是“姊妹”。","“路哈玛”意思是“蒙怜悯”。"]},{"n":2,"t":"要跟你们的母亲理论，理论，─因为她不是我的妻子，我也不是她的丈夫─叫她除掉脸上的淫相和胸间的淫态，","notes":[]},{"n":3,"t":"免得我剥光她，使她赤身，如刚出生的时候一样，使她如旷野，如干旱之地，干渴而死。","notes":[]},{"n":4,"t":"我必不怜悯她的儿女，因为他们是从淫乱生的儿女。","notes":[]},{"n":5,"t":"他们的母亲行了淫乱，怀他们的做了可羞耻的事；因为她说：“我要跟随我所爱的，我的饼、水、羊毛、麻、油、酒，都是他们给的。”","notes":[]},{"n":6,"t":"因此，看哪，我要用荆棘堵塞她的道，筑墙挡住她，使她找不着路；","notes":["“她”是根据七十士译本和其他古译本；原文是“你”。"]},{"n":7,"t":"以致她追随所爱的人，却追不上，寻找他们，却寻不着，就说：“我要回到前夫那里去，因我那时比现在还好。”","notes":[]},{"n":8,"t":"她不知道是我给她五谷、新酒和新的油，又加添她的金银；他们却用来供奉巴力。","notes":[]},{"n":9,"t":"因此，我要在收割的日子收回我的五谷，在当令的季节收回我的新酒，我要夺回她用以遮体的羊毛和麻。","notes":[]},{"n":10,"t":"如今我必在她所爱的人眼前显露她的羞耻，无人能救她脱离我的手。","notes":["“显露她的羞耻”或译“暴露她的下体”。"]},{"n":11,"t":"我必使她的宴乐、节期、初一、安息日，她一切的盛会都止息。","notes":[]},{"n":12,"t":"我要毁坏她的葡萄树和无花果树，就是她所说“我所爱的给我为赏赐”的；我要使它们变为荒林，为野地的走兽所吞吃。","notes":[]},{"n":13,"t":"我要惩罚她素日给诸巴力烧香的罪；那时她佩戴耳环和珠宝，跟随她所爱的，却忘记我。这是耶和华说的。","notes":[]},{"n":14,"t":"因此，看哪，我要诱导她，领她到旷野，我要说动她的心。","notes":[],"heads":["神对他子民的爱"]},{"n":15,"t":"在那里，我必赐她葡萄园，又赐她亚割谷作为指望的门。她必在那里回应，像在年轻时从埃及地上来的时候一样。","notes":[]},{"n":16,"t":"那日你必称呼我伊施，不再称呼我巴力。这是耶和华说的。","notes":["“伊施”意思是“我的丈夫”。","“巴力”意思是“我的主”。"]},{"n":17,"t":"因为我必从她口中除掉诸巴力的名号，不再有人提这名号。","notes":[]},{"n":18,"t":"当那日，我必为我的百姓，与野地的走兽、天空的飞鸟和地上爬行的动物立约；又要在国中折断弓和刀，止息战争，使他们安然躺卧。","notes":[]},{"n":19,"t":"我必聘你永远归我为妻，以公义、公平、慈爱、怜悯聘你归我；","notes":[]},{"n":20,"t":"也以信实聘你归我，你就必认识耶和华。","notes":[]},{"n":21,"t":"耶和华说：那日我必应允，我必应允天，天必应允地，","notes":[]},{"n":22,"t":"地必应允五谷、新酒和新的油；这些都必应允在耶斯列身上。","notes":[]},{"n":23,"t":"我为自己必将她种在这地。我必怜悯罗．路哈玛；对罗．阿米说：“你是我的子民”；他必说：“我的神。”","notes":[]}]},"3":{"heading":"何西阿和不贞的妇人","verses":[{"n":1,"t":"耶和华又对我说：“你去爱那情人所爱却犯奸淫的妇人，正如耶和华爱那偏向别神、喜爱葡萄饼的以色列人。”","notes":["“葡萄饼”是祭祀神明用的。"]},{"n":2,"t":"于是我用十五舍客勒银子和一贺梅珥半大麦买她归我。","notes":[]},{"n":3,"t":"我对她说：“你当多日与我同住，不可行淫，不可归与别人，我对你也一样。”","notes":[]},{"n":4,"t":"因为以色列人必多日过着无君王，无领袖，无祭祀，无柱像，无以弗得，无家中神像的生活。","notes":[]},{"n":5,"t":"后来以色列人必归回，寻求耶和华─他们的神和他们的王大卫。在末后的日子，他们必敬畏耶和华，领受他的恩惠。","notes":["“归回”或译“回转”。"]}]},"4":{"heading":"耶和华谴责以色列","verses":[{"n":1,"t":"以色列人哪，当听耶和华的话。耶和华指控这地的居民，因为在这地上无诚信，无慈爱，无人认识神；","notes":[]},{"n":2,"t":"惟起誓、欺骗、杀害、偷盗、奸淫、残暴、流血又流血。","notes":[]},{"n":3,"t":"因此，这地悲哀，其上的居民、野地的走兽、天空的飞鸟都日趋衰微，海中的鱼也必消灭。","notes":[]},{"n":4,"t":"然而，人都不必争辩，也不必指责。你的百姓与抗拒祭司的人一样。","notes":[],"heads":["谴责祭司"]},{"n":5,"t":"日间你必跌倒，夜间先知也要与你一同跌倒；我要灭绝你的母亲。","notes":[]},{"n":6,"t":"我的百姓因无知识而灭亡。你抛弃知识，我也必抛弃你，使你不再作我的祭司。你既忘了你神的律法，我也必忘记你的儿女。","notes":[]},{"n":7,"t":"祭司越发增多，就越发得罪我；我必使他们的荣耀变为羞辱。","notes":[]},{"n":8,"t":"他们吞吃我百姓的赎罪祭，满心愿意我的子民犯罪。","notes":["“赎罪祭”或译“罪”。"]},{"n":9,"t":"将来百姓所受的，祭司也必承受；我必因他们所行的惩罚他们，照他们所做的报应他们。","notes":[]},{"n":10,"t":"他们吃，却不得饱足；行淫，却不繁衍；因为他们离弃耶和华，常行","notes":[]},{"n":11,"t":"淫乱。酒和新酒夺去人的心。","notes":[]},{"n":12,"t":"我的百姓求问木偶，以为木杖能指示他们；淫乱的心使他们失迷，以致行淫离弃他们的神，","notes":[],"heads":["谴责拜偶像的罪"]},{"n":13,"t":"在各山顶献祭，在各高冈上烧香，在橡树、杨树、大树之下，因为那里树影美好。所以，你们的女儿行淫，你们的媳妇犯奸淫。","notes":["“媳妇”或译“新娘”；下同。"]},{"n":14,"t":"我不因你们的女儿行淫或你们的媳妇犯奸淫惩罚她们；因为人自己转去与娼妓同居，与神庙娼妓一同献祭。这无知的百姓必致倾倒。","notes":[]},{"n":15,"t":"以色列啊，你虽然行淫，犹大却不可犯罪；不要往吉甲去，不要上到伯．亚文，也不要指着永生的耶和华起誓。","notes":[]},{"n":16,"t":"以色列倔强，犹如倔强的母牛；现在耶和华能牧放他们，如在宽阔之地牧放羔羊吗？","notes":[]},{"n":17,"t":"以法莲亲近偶像，任凭他吧！","notes":[]},{"n":18,"t":"他们喝完了酒，荒淫无度，他们的官长甚爱羞耻的事。","notes":[]},{"n":19,"t":"风把他们卷在翅膀里，他们必因所献的祭蒙羞。","notes":["“所献的祭”：七十士译本是“祭坛”。"]}]},"5":{"heading":"何西阿警告拜偶像的人","verses":[{"n":1,"t":"众祭司啊，要听这话！以色列家啊，要留心听！王室啊，要侧耳而听！审判将临到你们，因你们在米斯巴如罗网，在他泊山如张开的网。","notes":[]},{"n":2,"t":"这些悖逆的人大行杀戮，我要斥责他们众人。","notes":[]},{"n":3,"t":"至于我，我认识以法莲，以色列不能向我隐藏。以法莲哪，现在你竟然行淫，以色列竟然被污辱。","notes":["“以法莲哪...行淫”：七十士译本是“现在以法莲竟然行淫”。"]},{"n":4,"t":"他们所做的使他们不能归向神，因有淫乱的心在他们里面；他们不认识耶和华。","notes":[]},{"n":5,"t":"以色列的骄傲使自己脸面无光；以色列和以法莲必因自己的罪孽跌倒，犹大也必与他们一同跌倒。","notes":["“使自己脸面无光”或译“当面见证自己的不是”或“使自己卑微”；7．10同。"]},{"n":6,"t":"他们牵着牛羊去寻求耶和华，却寻不着；因他已转去离开他们。","notes":[]},{"n":7,"t":"他们不忠于耶和华，生了私生子。现在新月必吞灭他们和他们的地业。","notes":[]},{"n":8,"t":"你们当在基比亚吹角，在拉玛吹号，在伯．亚文发出警报；便雅悯哪，留意你的背后！","notes":[],"heads":["犹大和以色列的战争"]},{"n":9,"t":"到了惩罚的日子，以法莲必变为废墟；我在以色列众支派中，已指示将来必成的事。","notes":[]},{"n":10,"t":"犹大的领袖如同挪移地界的人，我必把我的愤怒如水倾倒在他们身上。","notes":[]},{"n":11,"t":"以法莲因喜爱遵从荒谬的命令，就受欺压，在审判中被压碎。","notes":["“遵从荒谬的命令”：原文另译“追求粪土”；七十士译本和其他古译本是“追求虚无”。"]},{"n":12,"t":"我对以法莲竟如蛀虫，向犹大家竟如朽烂。","notes":[]},{"n":13,"t":"以法莲见自己有病，犹大见自己有伤，以法莲就前往亚述，差遣人去见大王；他却不能医治你们，不能治好你们的伤。","notes":["“大王”或译“耶雷布王”；10．6同。"]},{"n":14,"t":"我必向以法莲如狮子，向犹大家如少壮狮子。我要撕裂，并且离去，我必夺去，无人搭救。","notes":[]},{"n":15,"t":"我要去，我要回到原处，等他们自觉有罪，寻求我的面；急难时他们必切切寻求我。","notes":[]}]},"6":{"heading":"以色列无悔改诚意","verses":[{"n":1,"t":"来，我们归向耶和华吧！他撕裂我们，也必医治；打伤我们，也必包扎。","notes":[]},{"n":2,"t":"过两天他必使我们苏醒，第三天他必使我们兴起，我们就在他面前得以存活。","notes":[]},{"n":3,"t":"我们要认识，要追求认识耶和华。他如黎明必然出现，他必临到我们像甘霖，像滋润土地的春雨。","notes":[]},{"n":4,"t":"以法莲哪，我可以向你怎样行呢？犹大啊，我可以向你怎样做呢？因为你们的慈爱如同早晨的云雾，又如速散的露水。","notes":[]},{"n":5,"t":"因此，我藉先知砍伐他们，以我口中的话杀戮他们；对你的审判如光发出。","notes":["“对你的审判”：七十士译本和其他古译本是“我的审判”。"]},{"n":6,"t":"我喜爱慈爱，不喜爱祭物；喜爱人认识神，胜于燔祭。","notes":["“慈爱”：七十士译本是“怜悯”。"]},{"n":7,"t":"他们却如亚当背约，在那里向我行诡诈。","notes":["“如亚当”或译“如人”。"]},{"n":8,"t":"基列是作恶之人的城，被血沾染。","notes":[]},{"n":9,"t":"成群的祭司如强盗埋伏等候，在示剑的路上杀戮，行了邪恶。","notes":[]},{"n":10,"t":"在以色列家我看见可憎的事，在以法莲那里有淫行，以色列被污辱了。","notes":[]},{"n":11,"t":"犹大啊，我使被掳之民归回的时候，必有为你所预备的丰收。","notes":[]}]},"7":{"heading":"宫廷内乱","verses":[{"n":1,"t":"我正要医治以色列的时候，以法莲的罪孽和撒玛利亚的邪恶就显露出来。他们行事虚谎，内有贼人入侵，外有群盗劫掠。","notes":[]},{"n":2,"t":"他们以为我不在意他们一切的恶行；现在，他们所做的在我面前缠绕他们。","notes":[]},{"n":3,"t":"他们行恶使君王欢喜，说谎使官长快乐。","notes":[]},{"n":4,"t":"他们全都犯奸淫，如同烤热的火炉，师傅在揉面到发面时暂时停止煽火。","notes":[]},{"n":5,"t":"在我们君王宴乐的日子，官长因酒的烈性而生病，王与亵慢的人握手。","notes":["“因酒...生病”：七十士译本是“开始因酒而狂热”。"]},{"n":6,"t":"他们临近，心里如火炉一般，他们等待，如烤饼的整夜睡觉，到了早晨如火焰熊熊。","notes":[]},{"n":7,"t":"他们全都热如火炉，吞灭他们的审判官。他们的君王都仆倒，他们中间无一人求告我。","notes":[]},{"n":8,"t":"以法莲混居在万民中，以法莲是没有翻过的饼。","notes":["“混居在万民中”或译“在万民中逐渐枯朽”。"],"heads":["以色列和列邦"]},{"n":9,"t":"外邦人消耗他的力量，他却不知道；头发斑白，他也不觉得。","notes":[]},{"n":10,"t":"以色列的骄傲使自己脸面无光。他们虽遭遇这一切，仍不归向耶和华－他们的神，也不寻求他。","notes":[]},{"n":11,"t":"以法莲好像鸽子愚蠢无知，他们求告埃及，投奔亚述。","notes":[]},{"n":12,"t":"他们去的时候，我要把我的网撒在他们身上；我要捕获他们如同空中的鸟。我必按他们会众所听到的惩罚他们。","notes":["“他们会众所听到的”：原文另译“他们的邪恶”；七十士译本是“听到他们的灾难而”。"]},{"n":13,"t":"他们因离弃我，必定有祸；因违背我，必遭毁灭。我虽想要救赎他们，他们却向我说谎。","notes":[]},{"n":14,"t":"他们在床上呼号，却不诚心哀求我；他们为求五谷新酒而聚集，却背叛我。","notes":["“聚集”：有古卷和七十士译本是“割伤自己”。"]},{"n":15,"t":"我虽管教他们，坚固他们的膀臂，他们却图谋邪恶抗拒我。","notes":[]},{"n":16,"t":"他们归向，但不是归向至上者；终究必如松弛的弓。他们的领袖必因舌头的狂傲倒在刀下，这在埃及地必成为人的笑柄。","notes":["“他们...至上者”：原文另译“他们归向巴力”；七十士译本是“他们归向那不存在的”。"]}]},"8":{"heading":"以色列人因拜偶像被定罪","verses":[{"n":1,"t":"你用口吹角吧！敌人如鹰攻打耶和华的家；因为他们违背了我的约，干犯了我的律法。","notes":[]},{"n":2,"t":"他们必呼求我：“我的神啊，我们以色列认识你了。”","notes":["“我的神啊...认识你了”：原文另译“以色列的神啊，我们认识你了”。"]},{"n":3,"t":"以色列丢弃良善；仇敌必追逼他。","notes":["“良善”或译“福分”。"]},{"n":4,"t":"他们立君王，并非出于我；立官长，我却不知道。他们用金银为自己制造偶像，以致被剪除。","notes":[]},{"n":5,"t":"撒玛利亚啊，耶和华已抛弃你的牛犊；我的怒气向拜牛犊的人发作。他们要到几时方能无罪呢？","notes":[]},{"n":6,"t":"因这牛犊是出于以色列，是匠人所造的，并不是神。撒玛利亚的牛犊必被打碎。","notes":[]},{"n":7,"t":"他们所栽种的是风，所收割的是暴风；禾稼不长穗，无以制成面粉；即便制成，外邦人也必吞吃它。","notes":[]},{"n":8,"t":"以色列被吞吃，如今在列国中像人所不喜爱的器皿。","notes":[]},{"n":9,"t":"他们投奔亚述如独行的野驴。以法莲雇用情人，","notes":[]},{"n":10,"t":"他们雇用列国；如今我要聚集他们，他们必因君王和官长所加的重担开始衰微。","notes":["“他们必因...衰微”：七十士译本是“他们要停止片时，不再膏君王和官长”。"]},{"n":11,"t":"以法莲为赎罪增添许多祭坛，这些祭坛却使他犯罪。","notes":[]},{"n":12,"t":"我为他写了许多条律法，他却以为与他毫无关系。","notes":["“许多条”：原文另译“万条”。"]},{"n":13,"t":"他们献祭物作为给我的供物，却自食其肉，耶和华并不悦纳他们。现在他必记起他们的罪孽，惩罚他们的罪恶；他们必返回埃及。","notes":[]},{"n":14,"t":"以色列忘记造他的主，建造宫殿，犹大增添许多坚固的城；我却要降火在他的城镇，吞灭其堡垒。","notes":[]}]},"9":{"heading":"宣布以色列受惩罚","verses":[{"n":1,"t":"以色列啊，不要欢喜，像万民一样快乐；因为你行淫离弃你的神，喜爱各禾场上卖淫所得的赏金。","notes":["“像”：七十士译本是“不要像”。"]},{"n":2,"t":"禾场和压酒池都不足以喂养他们，它的新酒也必缺乏。","notes":[]},{"n":3,"t":"他们必不得住耶和华的地；以法莲却要返回埃及，在亚述吃不洁净的食物。","notes":[]},{"n":4,"t":"他们必不得向耶和华献浇酒祭，所献的祭也不蒙悦纳。他们的祭物如居丧者的食物，凡吃的必使自己玷污；因为他们的食物只为自己的口腹，必不得入耶和华的殿。","notes":[]},{"n":5,"t":"到盛会的日子，在耶和华的节期，你们要怎样行呢？","notes":[]},{"n":6,"t":"看哪，他们要逃避灾难；埃及人要收殓他们，摩弗人要埋葬他们。蒺藜盘踞他们贵重的银器，荆棘必占据他们的帐棚。","notes":["“摩弗”就是埃及的孟斐斯，也称“挪弗”。"]},{"n":7,"t":"降罚的日子近了，报应的时候已经来到。以色列必知道，先知愚昧，受灵感动的人狂妄，皆因你多多作恶，大怀怨恨。","notes":[]},{"n":8,"t":"以法莲替我的神守望；至于先知，他所到之处都有捕鸟人的罗网，在他神的家中也遭人怀恨。","notes":[]},{"n":9,"t":"他们深深败坏，如在基比亚的日子一样。耶和华必记起他们的罪孽，惩罚他们的罪恶。","notes":[]},{"n":10,"t":"我发现以色列，如在旷野的葡萄；我看见你们的祖先，如春季无花果树上初熟的果子。他们却来到巴力．毗珥，献上自己做羞耻的事，成为可憎恶的，与他们所爱的一样。","notes":[],"heads":["以色列的罪及其后果"]},{"n":11,"t":"以法莲，他们的荣耀如鸟飞去，必不生产，不怀胎，不成孕；","notes":[]},{"n":12,"t":"他们纵然将儿女养大，我却要使他们丧子，一个也不留。我离弃他们，他们就有祸了。","notes":[]},{"n":13,"t":"我看以法莲如推罗栽于美地。以法莲却要将自己的儿女带出来，交给行杀戮的人。","notes":[]},{"n":14,"t":"耶和华啊，求你加给他们，加给他们什么呢？要使他们怀孕流产，乳房枯干。","notes":[]},{"n":15,"t":"因他们在吉甲的一切恶事，我在那里憎恶他们。因他们所行的恶，我必把他们赶出我的殿，不再爱他们；他们的领袖都是悖逆的。","notes":[],"heads":["耶和华审判以色列"]},{"n":16,"t":"以法莲受击打，其根枯干，不能结果，即或生产，我也要杀他们所生的爱子。","notes":[]},{"n":17,"t":"我的神必弃绝他们，因为他们不听从他；他们必飘流在列国中。","notes":[],"heads":["先知论以色列"]}]},"10":{"heading":"神审判以色列","verses":[{"n":1,"t":"以色列是茂盛的葡萄树，结果繁多。果子越多，就越增添祭坛；土地越肥美，就越建造美丽的柱像。","notes":[]},{"n":2,"t":"他们心怀二意，现今要定为有罪。耶和华必拆毁他们的祭坛，粉碎他们的柱像。","notes":[]},{"n":3,"t":"现在他们要说：“我们没有王；因为我们不敬畏耶和华，王又能为我们做什么呢？”","notes":[]},{"n":4,"t":"他们讲空话，以假誓立约；因此，惩罚如苦菜滋生在田间的犁沟中。","notes":[]},{"n":5,"t":"撒玛利亚的居民必因伯．亚文的牛犊惊恐；它的百姓为它悲哀，它的祭司为它战兢，因为荣耀已经离开它。","notes":[]},{"n":6,"t":"人必将牛犊带到亚述，当作礼物献给大王。以法莲必蒙羞，以色列必因自己的计谋惭愧。","notes":[]},{"n":7,"t":"撒玛利亚的王要灭亡，如水面上的泡沫一般。","notes":[]},{"n":8,"t":"亚文的丘坛，以色列犯罪的地方必毁坏，荆棘和蒺藜必长在他们的祭坛上。他们要向大山说：遮盖我们！向小山说：倒在我们身上！","notes":[]},{"n":9,"t":"以色列啊，你从基比亚的日子以来就时常犯罪，他们仍停留在那里。攻击罪孽之辈的战事岂不会临到基比亚吗？","notes":[]},{"n":10,"t":"我必随己意惩罚他们，他们为双重的罪所缠；万民必聚集攻击他们。","notes":[]},{"n":11,"t":"以法莲是驯良的母牛犊，喜爱踹谷，我要将轭套在它肥美的颈项上，我要使以法莲被套住；犹大必耕田，雅各必耙地。","notes":[]},{"n":12,"t":"你们要为自己栽种公义，收割慈爱。你们要开垦荒地，现今正是寻求耶和华的时候；等他临到，公义必如雨降给你们。","notes":[]},{"n":13,"t":"你们耕种奸恶，收割罪孽，吃的是谎言的果实。因你倚靠自己的行为，仰赖你众多的勇士，","notes":[]},{"n":14,"t":"所以在你百姓中必掀起闹哄，你一切的堡垒必被拆毁，就如沙勒幔在争战的日子拆毁伯．亚比勒，将城中的母子一同摔碎。","notes":[]},{"n":15,"t":"伯特利啊，因你们的大恶，你们必遭遇如此。黎明来临，以色列的王必全然灭绝。","notes":["“伯特利”：七十士译本是“以色列家”。"]}]},"11":{"heading":"怜爱叛民","verses":[{"n":1,"t":"以色列年幼的时候，我爱他，就从埃及召我的儿子出来。","notes":[]},{"n":2,"t":"先知越是呼唤他们，他们越是远离，向诸巴力献祭，为雕刻的偶像烧香。","notes":["“先知”：原文是“他们”。","“先知...远离”：七十士译本是“我越是呼唤他们，他们越是远离我”。"]},{"n":3,"t":"我曾教导以法莲行走，我用膀臂抱起他们，他们却不知道是我医治他们。","notes":["“我用膀臂”是根据七十士译本；原文是“他用他的膀臂”。"]},{"n":4,"t":"我用慈绳爱索牵引他们；我待他们如人松开牛两腮旁边的轭，弯下身来喂养他们。","notes":[]},{"n":5,"t":"他们不必返回埃及地；然而亚述人要作他们的王，因他们不肯归向我。","notes":[]},{"n":6,"t":"刀剑必临到他们的城镇，毁坏门闩，吞灭众人，都因他们自己的计谋。","notes":[]},{"n":7,"t":"我的百姓偏要背离我，他们虽向至高者呼求，他却不抬举他们。","notes":["“他们虽...不抬举他们”或译“虽然人呼召他们归向至高者，却无人尊崇他”。"]},{"n":8,"t":"以法莲哪，我怎能舍弃你？以色列啊，我怎能弃绝你？我怎能使你如押玛？怎能使你如洗扁？我回心转意，我的怜悯燃了起来。","notes":[]},{"n":9,"t":"我必不发猛烈的怒气，也不再毁灭以法莲。因我是神，并非世人，是你们中间的圣者；我必不在怒中临到你们。","notes":[]},{"n":10,"t":"耶和华如狮子吼叫，他的儿女必跟随他。他一吼叫，他们就从西方战兢而来。","notes":[]},{"n":11,"t":"他们必如雀鸟从埃及战兢而来，又如鸽子从亚述地来到。我必使他们住自己的房屋；这是耶和华说的。","notes":[]},{"n":12,"t":"以法莲用谎言围绕我，以色列家用诡计环绕我；犹大却仍与神同行，向圣者忠心。","notes":["“与神同行”：七十士译本是“为神所认识”。"],"heads":["谴责以色列"]}]},"12":{"heading":"续论以色列","verses":[{"n":1,"t":"以法莲以风为食物，终日追逐东风，增添虚谎和残暴，与亚述立约，也把油送到埃及。","notes":[]},{"n":2,"t":"耶和华指控犹大，要照雅各所行的惩罚他，按他所做的报应他。","notes":[]},{"n":3,"t":"他在腹中抓住哥哥的脚跟，壮年的时候与神角力，","notes":[]},{"n":4,"t":"他与天使角力，并且得胜。他曾哀哭，恳求施恩。在伯特利遇见耶和华，耶和华在那里吩咐我们，","notes":["“我们”：七十士译本和其他古译本是“他”。"]},{"n":5,"t":"耶和华是万军之神，耶和华是他可记念的名。","notes":[]},{"n":6,"t":"所以你当归向你的神，谨守慈爱和公平，常常等候你的神。","notes":[]},{"n":7,"t":"商人手持诡诈的天平，喜爱欺压。","notes":["“商人”或译“迦南”。"]},{"n":8,"t":"以法莲说：我果然富有，得了财宝；我所劳碌得来的一切，人必找不到我有什么可算为有罪的恶。","notes":[]},{"n":9,"t":"自从你出埃及地以来，我就是耶和华－你的神；我必使你再住帐棚，如同节期的日子一样。","notes":[]},{"n":10,"t":"我已吩咐众先知，又增加异象，藉先知设比喻。","notes":[]},{"n":11,"t":"基列没有罪孽吗？他们诚然是虚假的，在吉甲献牛犊为祭；他们的祭坛如同田间犁沟中的乱堆。","notes":[]},{"n":12,"t":"从前雅各逃到亚兰地，以色列为娶妻子工作，为娶妻子而牧放。","notes":[]},{"n":13,"t":"后来耶和华藉先知领以色列从埃及上来，也藉先知看顾他们。","notes":[]},{"n":14,"t":"然而以法莲大大惹动主怒，他所流的血必归到他身上。主必使他的羞辱归还给他。","notes":[]}]},"13":{"heading":"以色列最后的审判","verses":[{"n":1,"t":"从前以法莲说话，人都战兢，他在以色列中居处高位；但他因巴力犯罪就死了。","notes":[]},{"n":2,"t":"如今他们罪上加罪，为自己铸造偶像，凭自己的聪明用银子造偶像，全都是匠人所制的。论到它，有话说：献祭的人都要亲吻牛犊。","notes":[]},{"n":3,"t":"因此，他们必如早晨的云雾，又如速散的露水，如被狂风吹离禾场的糠秕，又如烟囱冒出的烟。","notes":[]},{"n":4,"t":"自从你出埃及地以来，我就是耶和华－你的神；除了我神以外，你不认识别的，在我以外，并没有救主。","notes":[]},{"n":5,"t":"我曾在旷野，就是那干旱之地认识你。","notes":[]},{"n":6,"t":"他们得到喂养，就饱足；既得饱足，就心高气傲，因而忘记了我。","notes":[]},{"n":7,"t":"因此我向他们如同狮子，又如豹伏在道旁。","notes":[]},{"n":8,"t":"我如失去小熊的母熊，攻击他们，撕裂他们的胸膛。在那里我必如母狮吞吃他们，如野兽撕开他们。","notes":[]},{"n":9,"t":"以色列啊，你自取灭亡了 ，因为我才是你的帮助。","notes":["“你自取灭亡了”：原文另译“我要毁灭你”。","本节七十士译本是“以色列啊，在你的毁灭中，谁能帮助呢？”"]},{"n":10,"t":"现在，你的王在哪里呢？让他在你的各城中拯救你吧！你曾说“给我立君王和官长”，那些治理你的又在哪里呢？","notes":[]},{"n":11,"t":"我在怒气中将王赐给你，又在烈怒中将王废去。","notes":[]},{"n":12,"t":"以法莲的罪孽被卷起来，他的罪恶被收藏起来。","notes":[]},{"n":13,"t":"产妇的疼痛必临到他身上；他是无智慧之子，如同临盆时未出现的胎儿。","notes":[]},{"n":14,"t":"我必救赎他们脱离阴间，救赎他们脱离死亡。死亡啊，你的灾害在哪里？阴间哪，你的毁灭在哪里？怜悯必从我眼前消逝。","notes":[]},{"n":15,"t":"他在弟兄中虽然旺盛，却有东风刮来，就是耶和华的风从旷野上来。他的泉源必干涸，他的源头必枯竭，这风必夺走他所积蓄的一切宝物。","notes":[]},{"n":16,"t":"撒玛利亚要担当罪孽，因为背叛自己的神。他们必倒在刀下，婴孩必被摔碎，孕妇必被剖开。","notes":[]}]},"14":{"heading":"劝告以色列人","verses":[{"n":1,"t":"以色列啊，你要归向耶和华－你的神，你因自己的罪孽跌倒了。","notes":[]},{"n":2,"t":"当归向耶和华，用言语向他说：“求你除尽罪孽，悦纳善行，我们就用嘴唇的祭代替牛犊献上。","notes":[]},{"n":3,"t":"亚述不能救我们，我们不再骑马，也不再对我们手所造的偶像说：‘你是我们的神’；孤儿在你那里得蒙怜悯。”","notes":[]},{"n":4,"t":"我必医治他们背道的病，甘心爱他们，因为我向他们所发的怒气已转消。","notes":[],"heads":["应许以色列新生命"]},{"n":5,"t":"我必向以色列如甘露；他必如百合花开放，如黎巴嫩的树扎根。","notes":[]},{"n":6,"t":"他的嫩枝必延伸，他的荣华如橄榄树，香气如黎巴嫩的香柏树。","notes":[]},{"n":7,"t":"曾住在他荫下的必归回，使五谷生长，他们要发旺如葡萄树，他的名气如黎巴嫩的酒。","notes":["“使五谷生长”：原文另译“他们生长如园子”；七十士译本是“以五谷维生和得灌溉”。","“名气”或译“香气”。"]},{"n":8,"t":"以法莲说：“我与偶像有何相干？”我应允他，顾念他：我如青翠的松树，你的果实从我而来。","notes":[]},{"n":9,"t":"智慧人必明白这些事，聪明人必知道这一切。耶和华的道是正直的，义人行在其中，罪人却在其上跌倒。","notes":[],"heads":["结语"]}]}},"JOL":{"1":{"heading":"百姓的悲伤","verses":[{"n":1,"t":"耶和华的话临到毗土珥的儿子约珥。","notes":[]},{"n":2,"t":"老年人哪，当听这话；这地所有的居民哪，要侧耳而听。在你们的日子，或你们祖先的日子，曾发生过这样的事吗？","notes":[]},{"n":3,"t":"你们要将这事传与子，子传与孙，孙传与后代。","notes":[]},{"n":4,"t":"剪虫吃剩的，蝗虫来吃；蝗虫吃剩的，蝻子来吃；蝻子吃剩的，蚂蚱来吃。","notes":["剪虫、蝻子、蚂蚱都是蝗虫的一种。"]},{"n":5,"t":"醉酒的人哪，要清醒，要哭泣；好酒的人哪，都要为甜酒哀号，因为酒从你们的口中断绝了。","notes":[]},{"n":6,"t":"有一队蝗虫，强盛且不可数，上来侵犯我的地；它的牙齿如狮子的牙齿，如母狮的大牙。","notes":["“一队蝗虫”：原文是“一国”；2．2同。"]},{"n":7,"t":"它毁坏我的葡萄树，撕裂我的无花果树，剥光又丢弃，使枝条露白。","notes":[]},{"n":8,"t":"你要像童女腰束麻布，为她年少时的丈夫哀号。","notes":[]},{"n":9,"t":"耶和华的殿中断绝素祭和浇酒祭，事奉耶和华的祭司都悲哀。","notes":[]},{"n":10,"t":"田荒凉，地悲哀；因为五谷毁坏，新酒枯竭，新的油也缺乏。","notes":[]},{"n":11,"t":"农夫啊，你们要惭愧；修整葡萄园的啊，你们要哀号；因为大麦、小麦与田间的庄稼全都毁了。","notes":[]},{"n":12,"t":"葡萄树枯干，无花果树衰残，石榴树、棕树、苹果树，田野一切的树木都枯干；众人的喜乐尽都消逝。","notes":[]},{"n":13,"t":"祭司啊，当束上麻布痛哭；事奉祭坛的啊，要哀号；事奉我神的啊，你们要来，披上麻布过夜，因为在你们神的殿中不再有素祭和浇酒祭了。","notes":[]},{"n":14,"t":"你们要使禁食的日子分别为圣，宣告严肃会，召集长老和这地所有的居民来到耶和华－你们神的殿，向耶和华哀求。","notes":[]},{"n":15,"t":"哀哉，这日子！因为耶和华的日子临近，好像毁灭从全能者来到。","notes":[]},{"n":16,"t":"粮食不是在我们眼前断绝了吗？欢喜快乐不是从我们神的殿中止息了吗？","notes":[]},{"n":17,"t":"种子在土块下朽烂，仓荒凉，廪破坏，因为五谷枯干了。","notes":[]},{"n":18,"t":"牲畜哀鸣，牛群混乱，因无草场，羊群也受苦。","notes":[]},{"n":19,"t":"耶和华啊，我向你求告，因为有火吞噬野地的草场，火焰烧尽田野的树木。","notes":[]},{"n":20,"t":"田野的走兽切慕你，因为溪水干涸，火吞噬了野地的草场。","notes":[]}]},"2":{"heading":"蝗灾临近","verses":[{"n":1,"t":"你们要在锡安吹角，在我的圣山发出警报。这地所有的居民要发颤，因为耶和华的日子快到，已经临近了。","notes":[]},{"n":2,"t":"那是黑暗、阴森的日子，是密云、乌黑的日子，如同黎明笼罩山岭。有一队蝗虫，又大又强，自古以来没有像这样的，以后直到万代也必没有。","notes":[]},{"n":3,"t":"它们前面有火吞噬，后面有火焰烧尽。它们未到以前，地如伊甸园，过去以后，却成了荒凉的旷野，没有一样能躲避它们。","notes":[]},{"n":4,"t":"它们形状如马，奔跑如战马。","notes":[]},{"n":5,"t":"响声如战车在山顶上跳动，如火焰吞噬碎秸，好像强大的军队摆阵备战。","notes":[]},{"n":6,"t":"在它们面前，万民伤恸，脸都变色。","notes":[]},{"n":7,"t":"它们如勇士奔跑，如战士攀登城墙，各行于自己的道路，不乱队伍；","notes":[]},{"n":8,"t":"它们并不彼此推挤，各行于自己的大道，冲过防御，并不停止。","notes":["“防御”：原文是“兵器”。"]},{"n":9,"t":"它们蹦上城，跳上墙，爬上房屋，从窗户进来，如同盗贼。","notes":[]},{"n":10,"t":"在它们面前，地动天摇，日月昏暗，星宿无光。","notes":[]},{"n":11,"t":"耶和华在他的军旅前出声，他的队伍庞大，遵行他命令的强盛。耶和华的日子大而可畏，谁能当得起呢？","notes":[]},{"n":12,"t":"然而你们现在要禁食，哭泣，哀号，一心归向我。这是耶和华说的。","notes":[],"heads":["呼吁百姓悔改"]},{"n":13,"t":"你们要撕裂心肠，不要撕裂衣服。归向耶和华－你们的神，因为他有恩惠，有怜悯，不轻易发怒，有丰盛的慈爱，并且会改变心意，不降那灾难。","notes":[]},{"n":14,"t":"谁知道他也许会回心转意，留下余福，就是献给耶和华－你们神的素祭和浇酒祭。","notes":[]},{"n":15,"t":"你们要在锡安吹角，使禁食的日子分别为圣，宣告严肃会。","notes":[]},{"n":16,"t":"聚集百姓，使会众自洁；召集老年人，聚集孩童和在母怀吃奶的；使新郎出内室，新娘离开洞房。","notes":[]},{"n":17,"t":"事奉耶和华的祭司要在走廊和祭坛间哭泣，说：“耶和华啊，求你顾惜你的百姓，不要使你的产业受羞辱，在列国中成为笑柄。为何让人在万民中说‘他们的神在哪里’呢？”","notes":[]},{"n":18,"t":"耶和华为自己的地发热心，怜悯他的百姓。","notes":[],"heads":["神再赐福泽"]},{"n":19,"t":"耶和华应允他的百姓说：“看哪，我要赏赐你们五谷、新酒和新的油，使你们饱足，我必不再使你们受列国的羞辱。","notes":[]},{"n":20,"t":"我要使北方来的队伍远离你们，将他们赶到干旱荒芜之地：前队赶入东海，后队赶入西海；臭气上升，恶臭腾空。耶和华果然行了大事！","notes":[]},{"n":21,"t":"“土地啊，不要惧怕，要欢喜快乐，因为耶和华行了大事。","notes":[]},{"n":22,"t":"田野的走兽啊，不要惧怕，因为旷野的草已生长，树木结果，无花果树、葡萄树也都效力。","notes":["“效力”意思是“出产丰盛”。"]},{"n":23,"t":"“锡安的民哪，你们要欢喜，要因耶和华－你们的神快乐；因他赏赐你们合宜的秋雨，为你们降下甘霖，秋雨和春雨，和先前一样。","notes":["“因他赏赐...秋雨”或译“因他按公义赐秋雨给你们”或“因他赏赐你们公义的教师”。"]},{"n":24,"t":"“禾场充满五谷，池中漫溢新酒和新的油。","notes":[]},{"n":25,"t":"我差遣到你们中间的大军队，就是蝗虫、蝻子、蚂蚱、剪虫，那些年间所吃的，我要补还给你们。","notes":[]},{"n":26,"t":"“你们必吃得饱足，赞美耶和华－你们神的名，他为你们行了奇妙的事。我的百姓不致羞愧，直到永远。","notes":[]},{"n":27,"t":"你们必知道我是在以色列中，又知道我是耶和华－你们的神，没有别的。我的百姓不致羞愧，直到永远。”","notes":[]},{"n":28,"t":"“以后，我要将我的灵浇灌凡有血肉之躯的。你们的儿女要说预言，你们的老人要做异梦，你们的少年要见异象。","notes":[],"heads":["耶和华的日子"]},{"n":29,"t":"在那些日子，我要将我的灵浇灌我的仆人和婢女。","notes":[]},{"n":30,"t":"“我要在天上地下显出奇事，有血，有火，有烟柱。","notes":[]},{"n":31,"t":"太阳要变为黑暗，月亮要变为血，这都在耶和华大而可畏的日子未到以前。","notes":[]},{"n":32,"t":"那时，凡求告耶和华名的就必得救；因为照耶和华所说的，在锡安山，在耶路撒冷将有逃脱的人。凡耶和华所召的，都在余民之列。”","notes":["“凡耶和华所召的”或译“凡呼求耶和华的”。"]}]},"3":{"heading":"神要审判列国","verses":[{"n":1,"t":"“看哪，在那些日子，到那个时候，我使犹大和耶路撒冷被掳之人归回的时候，","notes":[]},{"n":2,"t":"我要聚集万民，带他们下到约沙法谷去，在那里我要为我百姓，我产业以色列的缘故，向万民施行审判；因为他们把我的百姓分散到列国，瓜分了我的土地，","notes":[]},{"n":3,"t":"为我的百姓抽签，以男孩换取妓女，为喝酒卖掉女孩。","notes":[]},{"n":4,"t":"“推罗、西顿和非利士四境的人哪，你们与我何干？你们要报复我吗？若要报复我，我必使报应速速归到你们头上。","notes":[]},{"n":5,"t":"你们夺取我的金银，把我珍贵的宝物带入你们的庙宇，","notes":["“庙宇”或译“宫殿”。"]},{"n":6,"t":"并将犹大人和耶路撒冷人卖给希腊人，使他们远离自己的疆界。","notes":["“希腊人”：原文是“雅完人”。"]},{"n":7,"t":"看哪，我必激发他们离开你们把他们卖去的地方，又必使报应归到你们头上。","notes":[]},{"n":8,"t":"我要将你们的儿女卖到犹大人手中，他们必转卖给远方的国家示巴人。这是耶和华说的。”","notes":[]},{"n":9,"t":"当在列国中宣告：预备打仗，激发勇士，使所有战士上前来。","notes":[]},{"n":10,"t":"要将犁头打成刀剑，镰刀打成戈矛；弱者要说：“我是勇士。”","notes":[]},{"n":11,"t":"四围的列国啊，你们要速速前来，一同聚集。耶和华啊，求你使你的勇士降临。","notes":[]},{"n":12,"t":"列国都当兴起，上到约沙法谷；因为我必坐在那里，审判四围的列国。","notes":[]},{"n":13,"t":"挥镰刀吧！因为庄稼熟了；来踩踏吧！因为榨酒池满了。酒池已经满溢，因为他们的罪恶甚大。","notes":[]},{"n":14,"t":"在断定谷有许多许多的人，因为耶和华的日子临近断定谷了。","notes":[]},{"n":15,"t":"日月昏暗，星宿无光。","notes":[]},{"n":16,"t":"耶和华必从锡安吼叫，从耶路撒冷出声，天地就震动。耶和华却要作他百姓的避难所，作以色列人的保障。","notes":[],"heads":["神将赐福给他的子民"]},{"n":17,"t":"你们就知道我是耶和华－你们的神，我住在锡安－我的圣山。耶路撒冷必成为圣；陌生人不再从其中经过。","notes":[]},{"n":18,"t":"在那日，大山要滴甜酒，小山要流奶，犹大的溪河都有水流出；必有泉源从耶和华的殿中流出，滋润什亭谷。","notes":[]},{"n":19,"t":"埃及必定荒凉，以东成为荒凉的旷野，因为他们向犹大人行残暴，又因他们在本地流无辜人的血。","notes":[]},{"n":20,"t":"但犹大必存到永远，耶路撒冷必存到万代。","notes":[]},{"n":21,"t":"我要免除流人血的罪，是先前未曾免除的，耶和华居住在锡安。","notes":["“免除”：七十士译本是“报复”；下同。"]}]}},"AMO":{"1":{"heading":"神审判以色列的邻国","verses":[{"n":1,"t":"这是犹大王乌西雅在位与约阿施的儿子以色列王耶罗波安在位的时候，大地震前二年，从提哥亚来的牧人阿摩司所见的─他的话论到以色列。","notes":[]},{"n":2,"t":"他说：“耶和华必从锡安吼叫，从耶路撒冷出声；牧人的草场哀伤，迦密的山顶枯干。”","notes":[]},{"n":3,"t":"耶和华如此说：“大马士革三番四次犯罪，以铁的打谷机击打基列，我必不撤销对它的惩罚。","notes":[]},{"n":4,"t":"我要降火在哈薛的王宫，吞灭便．哈达的宫殿；","notes":[]},{"n":5,"t":"我要折断大马士革的门闩，剪除亚文平原的居民和伯．伊甸的掌权者，亚兰人必被掳到吉珥。”这是耶和华说的。","notes":[]},{"n":6,"t":"耶和华如此说：“迦萨三番四次犯罪，掳掠全体百姓交给以东，我必不撤销对它的惩罚。","notes":[]},{"n":7,"t":"我要降火在迦萨城内，吞灭它的宫殿；","notes":[]},{"n":8,"t":"我要剪除亚实突的居民和亚实基伦的掌权者，反手攻击以革伦，剩余的非利士人都必灭亡。”这是主耶和华说的。","notes":[]},{"n":9,"t":"耶和华如此说：“推罗三番四次犯罪，将全体百姓交给以东，不顾念弟兄的盟约，我必不撤销对它的惩罚，","notes":[]},{"n":10,"t":"我要降火在推罗城内，吞灭它的宫殿。”","notes":[]},{"n":11,"t":"耶和华如此说：“以东三番四次犯罪，怒气不停发作，永远怀着愤怒，拿刀追赶兄弟，丝毫不存怜悯，我必不撤销对它的惩罚。","notes":[]},{"n":12,"t":"我要降火在提幔，吞灭波斯拉的宫殿。”","notes":[]},{"n":13,"t":"耶和华如此说：“亚扪人三番四次犯罪，剖开基列的孕妇，扩张自己的疆界，我必不撤销对它的惩罚。","notes":[]},{"n":14,"t":"我要在战争呐喊的日子，在旋风狂吹时，在拉巴城内放火，吞灭它的宫殿；","notes":[]},{"n":15,"t":"他们的君王和官长必一同被掳。”这是耶和华说的。","notes":[]}]},"2":{"heading":"神审判以色列","verses":[{"n":1,"t":"耶和华如此说：“摩押三番四次犯罪，把以东王的骸骨焚烧成灰，我必不撤销对它的惩罚。","notes":[]},{"n":2,"t":"我要降火在摩押，吞灭加略的宫殿，摩押必在闹哄、呐喊、吹角声中灭亡；","notes":[]},{"n":3,"t":"我要剪除摩押的领袖，把所有的官长和他一同杀戮。”这是耶和华说的。","notes":[]},{"n":4,"t":"耶和华如此说：“犹大三番四次犯罪，厌弃耶和华的训诲，不遵守他的律例；他们祖先所随从虚假的偶像使他们走迷了，我必不撤销对它的惩罚。","notes":["“虚假的偶像”：原文是“虚假”。"]},{"n":5,"t":"我要降火在犹大，吞灭耶路撒冷的宫殿。”","notes":[]},{"n":6,"t":"耶和华如此说：“以色列三番四次犯罪，为银子卖了义人，为一双鞋卖了穷人，我必不撤销对它的惩罚。","notes":[]},{"n":7,"t":"他们把贫寒人的头践踏在地的尘土上，又阻碍困苦人的道路。父子与同一个女子行淫，以致亵渎我的圣名。","notes":["“他们...尘土上”或译“他们切慕贫寒人头上所蒙土地的灰尘”。"]},{"n":8,"t":"他们在各祭坛旁边，躺卧在人所典当的衣服上，又在他们神的殿里喝受罚之人的酒。","notes":["“他们神的殿里”或译“他们神明的庙中”。"]},{"n":9,"t":"“我从他们面前除灭亚摩利人；他虽高大如香柏树，强壮如橡树，我却上灭其果，下绝其根。","notes":[]},{"n":10,"t":"我曾将你们从埃及地领上来，在旷野里引导你们四十年，使你们得亚摩利人之地为业；","notes":[]},{"n":11,"t":"我从你们子孙中兴起先知，又从你们少年中兴起拿细耳人。以色列人哪，不是这样吗？”这是耶和华说的。","notes":[]},{"n":12,"t":"“你们却把酒给拿细耳人喝，嘱咐先知说：‘不要说预言。’","notes":[]},{"n":13,"t":"“看哪，我要把你们压下去，如同装满禾捆的车压过一样。","notes":[]},{"n":14,"t":"快跑的无从避难，壮士无法使力，勇士也不能自救；","notes":[]},{"n":15,"t":"拿弓的站立不住，腿快的不能逃脱，骑马的也不能自救。","notes":[]},{"n":16,"t":"到那日，勇士中最有胆量的，必赤身逃跑。”这是耶和华说的。","notes":[]}]},"3":{"heading":"先知的任务","verses":[{"n":1,"t":"以色列人哪，当听耶和华责备你们的话，责备我从埃及地领上来的全家，说：","notes":[]},{"n":2,"t":"“在地上万族中，我只认识你们；因此，我必惩罚你们一切的罪孽。”","notes":[]},{"n":3,"t":"二人若不同心，岂能同行呢？","notes":[]},{"n":4,"t":"狮子若无猎物，岂会在林中咆哮呢？少壮狮子若无所得，岂会从洞里吼叫呢？","notes":[]},{"n":5,"t":"若未设圈套，雀鸟岂能陷入地上的罗网呢？罗网若无所得，岂会从地上翻起呢？","notes":[]},{"n":6,"t":"城中若吹角，百姓岂不战兢吗？灾祸若临到一城，岂非耶和华所降的吗？","notes":[]},{"n":7,"t":"主耶和华不会做任何事情，除非先将奥秘指示他的仆人众先知。","notes":[]},{"n":8,"t":"狮子吼叫，谁不惧怕呢？主耶和华既已说了，谁能不说预言呢？","notes":[]},{"n":9,"t":"你们要在亚实突的宫殿和埃及地的宫殿传扬，说：“要聚集在撒玛利亚的山上，看城里有何等大的扰乱与欺压。”","notes":[],"heads":["撒玛利亚的结局"]},{"n":10,"t":"“他们以暴力抢夺，堆积在自己的宫殿里，却不懂得行正直的事。”这是耶和华说的。","notes":[]},{"n":11,"t":"所以主耶和华如此说：“敌人必来围攻这地，削弱你的势力，抢掠你的宫殿。”","notes":[]},{"n":12,"t":"耶和华如此说：“牧人怎样从狮子口中抢回两条腿或耳朵的一小片，住撒玛利亚的以色列人得救也是如此，不过抢回床的一角和床榻的靠枕而已。”","notes":["“床榻的靠枕”：原文另译“大马士革的床榻”或“床脚的一部分”。"]},{"n":13,"t":"主耶和华－万军之神说：“当听这话，警戒雅各家。","notes":[]},{"n":14,"t":"我惩罚以色列罪孽的日子，也要惩罚伯特利的祭坛；祭坛的角必被砍下，坠落于地。","notes":[]},{"n":15,"t":"我要拆毁过冬和避暑的房屋，象牙的房屋必毁灭，广厦豪宅都归无有。”这是耶和华说的。","notes":[]}]},"4":{"heading":"以色列的失败","verses":[{"n":1,"t":"“你们这些撒玛利亚山上的巴珊母牛啊，当听这话！你们欺负贫寒人，压碎贫穷人，对主人说：‘拿酒来，我们喝吧！’","notes":[]},{"n":2,"t":"主耶和华指着自己的神圣起誓说：‘看哪，日子将到，人必用钩子将你们钩去，用鱼钩把你们中最后一个钩去。","notes":[]},{"n":3,"t":"你们必从城墙的缺口出去，各人直往前行，投向哈门。’”这是耶和华说的。","notes":["“城墙的缺口”：原文是“缺口”。","“哈门”：原文另译“黑门山”或“粪堆”。"]},{"n":4,"t":"“以色列人哪，任你们往伯特利去犯罪，到吉甲增加罪过，每早晨献上你们的祭物，每三日纳你们的十一奉献；","notes":[]},{"n":5,"t":"任你们献上有酵的感谢祭，宣扬你们的甘心祭，使人听见，因为这是你们所喜爱的。”这是主耶和华说的。","notes":[]},{"n":6,"t":"“我使你们在每一座城里牙齿干净，使你们各处的粮食缺乏，你们仍不归向我。”这是耶和华说的。","notes":[]},{"n":7,"t":"“在收割的前三个月，我不降雨在你们那里，我降雨在这城，不降雨在那城；这块地有雨，那块无雨的地就必枯干。","notes":[]},{"n":8,"t":"两三城的人挤到一个城去找水喝，却喝不足，你们仍不归向我。”这是耶和华说的。","notes":[]},{"n":9,"t":"“我以焚风和霉烂攻击你们，你们许多的菜园、葡萄园、无花果树、橄榄树屡屡被剪虫所吃，你们仍不归向我。”这是耶和华说的。","notes":["“焚风”或译“虫害”。","“剪虫”就是蝗虫的一种。"]},{"n":10,"t":"“我降瘟疫在你们中间，如在埃及的样子；用刀杀戮你们的年轻人和你们遭掳掠的马匹，营中臭气扑鼻，你们仍不归向我。”这是耶和华说的。","notes":[]},{"n":11,"t":"“我倾覆你们，如同神从前倾覆所多玛、蛾摩拉一样；你们好像从火中抢救出来的一根柴，你们仍不归向我。”这是耶和华说的。","notes":[]},{"n":12,"t":"“因此，以色列啊，我要如此对待你；因为我要这样对待你，以色列啊，你当预备迎见你的神。”","notes":[]},{"n":13,"t":"看哪，那创山，造风，将其心意指示人，使晨光变幽暗，踩行在地之高处的，他的名是耶和华－万军之神。","notes":[]}]},"5":{"heading":"呼吁以色列人悔改","verses":[{"n":1,"t":"以色列家啊，听我为你们所作的哀歌：","notes":[]},{"n":2,"t":"“以色列民跌倒，不得再起；躺在地上，无人扶起。”","notes":["“民”：原文是“少女”。"]},{"n":3,"t":"主耶和华如此说：“以色列家的城派出一千，只剩一百；派出一百，只剩十个。”","notes":[]},{"n":4,"t":"耶和华向以色列家如此说：“你们要寻求我，就必存活。","notes":[]},{"n":5,"t":"不要往伯特利寻求，不要进入吉甲，也不要过到别是巴；因为吉甲必被掳走，伯特利必归无有。”","notes":[]},{"n":6,"t":"要寻求耶和华，就必存活，免得他在约瑟家如火发出，焚烧伯特利，无人扑灭。","notes":["“伯特利”：七十士译本是“以色列家”。"]},{"n":7,"t":"你们这使公平变为茵陈，将公义丢弃于地的人哪！","notes":[]},{"n":8,"t":"那造昴星和参星，使死荫变为晨光，使白昼变为黑夜，召唤海水、使其倾倒在地面上的，耶和华是他的名。","notes":[]},{"n":9,"t":"他快速摧毁强壮的人，毁灭就临到堡垒。","notes":[]},{"n":10,"t":"你们怨恨那在城门口断是非的，憎恶那说正直话的。","notes":[]},{"n":11,"t":"所以，因你们践踏贫寒人，向他们勒索粮税；你们虽建造石凿的房屋，却不得住在其内；虽栽植美好的葡萄园，却不得喝其中所出的酒。","notes":[]},{"n":12,"t":"我知道你们的罪过何其多，你们的罪恶何其大；你们迫害义人，收受贿赂，在城门口屈枉贫穷人。","notes":[]},{"n":13,"t":"所以智慧人在这样的时候必静默不言，因为这是险恶的时候。","notes":[]},{"n":14,"t":"你们要寻求良善，不要寻求邪恶，就必存活。这样，耶和华－万军之神必照你们所说的与你们同在。","notes":[]},{"n":15,"t":"要恨恶邪恶，喜爱良善，在城门口秉公行义；或者耶和华－万军之神会施恩给约瑟的余民。","notes":[]},{"n":16,"t":"因此，主耶和华－万军之神如此说：“在一切的广场上必有哀号的声音；在各街市上必有人说：‘哀哉！哀哉！’他们叫农夫来哭号，叫善唱哀歌的来举哀；","notes":[]},{"n":17,"t":"各葡萄园都有哀号的声音，因为我必从你中间经过。”这是耶和华说的。","notes":[]},{"n":18,"t":"想望耶和华日子的人有祸了！为什么你们要耶和华的日子呢？那是黑暗没有光明的日子，","notes":[]},{"n":19,"t":"好像人躲避狮子却遇见熊；进房屋以手靠墙，却被蛇咬。","notes":[]},{"n":20,"t":"耶和华的日子岂不是黑暗没有光明，幽暗毫无光辉吗？","notes":[]},{"n":21,"t":"“我厌恶你们的节期，也不喜悦你们的严肃会。","notes":[]},{"n":22,"t":"你们虽然向我献燔祭和素祭，我却不悦纳，也不看你们用肥畜献的平安祭。","notes":[]},{"n":23,"t":"要使你们歌唱的声音远离我，因为我不听你们琴瑟的乐曲。","notes":[]},{"n":24,"t":"惟愿公平如大水滚滚，公义如江河滔滔。","notes":[]},{"n":25,"t":"“以色列家啊，你们在旷野四十年，何尝将祭物和供物献给我呢？","notes":[]},{"n":26,"t":"你们抬着你们的撒古特君王，和你们为自己所造之偶像迦温─你们的神明之星。","notes":["“你们的撒古特君王”：七十士译本是“摩洛的帐幕”。"]},{"n":27,"t":"所以我要把你们掳到大马士革以外。”这是耶和华说的，他的名为万军之神。","notes":[]}]},"6":{"heading":"以色列的毁灭","verses":[{"n":1,"t":"“那在锡安安逸，在撒玛利亚山安稳，为列国之首，具有名望，且为以色列家所归向的，有祸了！","notes":[]},{"n":2,"t":"你们要过到甲尼察看，从那里往哈马大城去，又下到非利士人的迦特，你们比这些国更好吗？或是他们的疆界比你们的疆界广大呢？","notes":[]},{"n":3,"t":"你们以为降祸的日子尚远，却使残暴的统治临近。","notes":["“统治”：原文是“座位”。"]},{"n":4,"t":"“那些躺卧在象牙床上，舒身在榻上的，吃群中的羔羊和棚里的牛犊。","notes":[]},{"n":5,"t":"他们以琴瑟逍遥歌唱，为自己作曲，像大卫一样；","notes":["“作曲”：原文是“制造乐器”。"]},{"n":6,"t":"以大碗喝酒，用上等油抹身，却不为约瑟所受的苦难忧伤；","notes":[]},{"n":7,"t":"所以，现在这些人必首先被掳，逍遥的欢宴必消失。”","notes":[]},{"n":8,"t":"主耶和华指着自己起誓说：“我憎恶雅各的骄傲，厌弃他的宫殿；我必将城和其中一切所有的都交给敌人。”这是耶和华－万军之神说的。","notes":["七十士译本没有“这是...神说的”。"]},{"n":9,"t":"那时，若一房之内剩下十个人，也都必死。","notes":[]},{"n":10,"t":"死人的叔伯要把尸首抬到屋外焚烧，就问房屋内间的人说：“你那里还有别人吗？”他说：“没有。”又说：“不要作声，不可提耶和华的名。”","notes":[]},{"n":11,"t":"看哪，耶和华发命令，把大房子拆成碎片，小屋子裂为小块。","notes":[]},{"n":12,"t":"马岂能在岩石上奔跑？人岂能在那里用牛耕种呢？你们却使公平变为苦胆，使公义的果子变为茵陈。","notes":["“在那里”：原文另译“在海上”。"]},{"n":13,"t":"你们这些喜爱罗．底巴的，自夸说：“我们不是凭自己的力量攻占了加宁吗？”","notes":["“罗．底巴”意思是“虚浮的事”。","“加宁”意思是“两角”。"]},{"n":14,"t":"耶和华─万军之神说：“以色列家，看哪，我必兴起一国攻击你们；他们必欺压你们，从哈马口直到亚拉巴的河。”","notes":[]}]},"7":{"heading":"蝗虫的异象","verses":[{"n":1,"t":"主耶和华指示我一件事，在春天作物刚长出时，看哪，主造了蝗虫；看哪，这是王收割后长出的春天作物。","notes":["“主”：原文是“他”。"]},{"n":2,"t":"蝗虫吃尽那地青草的时候，我说：“主耶和华啊，求你赦免；因为雅各弱小，他怎能站立得住呢？”","notes":[]},{"n":3,"t":"耶和华对这事改变心意，耶和华说：“这灾可以免了。”","notes":[]},{"n":4,"t":"主耶和华又指示我一件事，看哪，主耶和华命火施行审判，火就吞灭深渊，烧尽产业。","notes":[],"heads":["火的异象"]},{"n":5,"t":"我就说：“主耶和华啊，求你止息；因为雅各弱小，他怎能站立得住呢？”","notes":[]},{"n":6,"t":"耶和华对这事改变心意，主耶和华说：“这灾也可免了。”","notes":[]},{"n":7,"t":"他又指示我一件事，看哪，主手拿铅垂线，站立在依铅垂线建好的墙边。","notes":[],"heads":["铅垂线的异象"]},{"n":8,"t":"耶和华对我说：“阿摩司，你看见什么？”我说：“铅垂线。”主说：“看哪，我要在我子民以色列中吊起铅垂线，不再宽恕他们。","notes":[]},{"n":9,"t":"以撒的丘坛必荒凉，以色列的圣所必荒废；我要起来用刀攻击耶罗波安的家。”","notes":[]},{"n":10,"t":"伯特利的祭司亚玛谢派人到以色列王耶罗波安那里，说：“阿摩司在以色列家中图谋背叛你，他所说的一切话，这地不能承担；","notes":[],"heads":["阿摩司和亚玛谢"]},{"n":11,"t":"因为阿摩司这样说：‘耶罗波安必被刀杀，以色列百姓必被掳，离开本地。’”","notes":[]},{"n":12,"t":"于是亚玛谢对阿摩司说：“你这先见哪，要逃到犹大地，在那里过活，在那里说预言；","notes":["“过活”：原文是“吃”。"]},{"n":13,"t":"却不要在伯特利再说预言，因为这里有王的圣所，有王的宫殿。”","notes":[]},{"n":14,"t":"阿摩司对亚玛谢说：“我原不是先知，也不是先知的门徒；我是牧人，是修剪桑树的。","notes":[]},{"n":15,"t":"耶和华带领我，叫我不再牧放羊群，对我说：‘你去向我子民以色列说预言。’","notes":[]},{"n":16,"t":"“现在你要听耶和华的话。你说：‘不要向以色列说预言，也不要向以撒家传讲。’","notes":["“传讲”：原文是“滴下”。"]},{"n":17,"t":"所以耶和华如此说：‘你的妻子要在城中作妓女，你的儿女要倒在刀下；你的地必有人用绳子量了瓜分，你自己必死在不洁净之地；以色列百姓必被掳，离开本地。’”","notes":[]}]},"8":{"heading":"一筐果子的异象","verses":[{"n":1,"t":"主耶和华又指示我一件事，看哪，有一筐夏天的果子。","notes":[]},{"n":2,"t":"他说：“阿摩司，你看见什么？”我说：“一筐夏天的果子。”耶和华对我说：“我子民以色列的结局到了，我必不再宽恕他们。","notes":["“结局”与“夏天的果子”希伯来话发音相近。"]},{"n":3,"t":"那日，宫殿里的诗歌要变为哀号；必有许多尸首抛在各处，安静无声。”这是主耶和华说的。","notes":["“宫殿里...哀号”：原文另译“宫殿里唱歌的女子要哀号”。"]},{"n":4,"t":"你们这些践踏贫穷人、使这地困苦人衰败的，当听这话！","notes":[],"heads":["以色列的结局"]},{"n":5,"t":"你们说：“初一几时过去，我们好卖粮；安息日几时过去，我们好摆开谷物；我们要把伊法变小，把舍客勒变大，以诡诈的天平欺哄人，","notes":[]},{"n":6,"t":"用银子买贫寒人，以一双鞋换贫穷人，把坏的谷物卖给人。”","notes":[]},{"n":7,"t":"耶和华指着雅各的骄傲起誓说：“他们这一切的行为，我必永远不忘。","notes":[]},{"n":8,"t":"地岂不因这事震动？其中的居民岂不悲哀吗？全地必如尼罗河涨起，如埃及的尼罗河涌起退落。","notes":[]},{"n":9,"t":"“到那日，我要使太阳在正午落下，使这地在白昼黑暗。”这是主耶和华说的。","notes":[]},{"n":10,"t":"“我要使你们的节期变为悲哀，你们一切的歌曲变为哀歌；我要使众人腰束麻布，头上光秃；我要使这悲哀如丧独子，其结局如悲痛的日子。","notes":[]},{"n":11,"t":"“看哪，日子将到，我必命饥荒降在地上；人饥饿非因无饼，干渴非因无水，而是因不听耶和华的话。”这是主耶和华说的。","notes":[]},{"n":12,"t":"他们必飘流，从这海到那海，从北边到东边，往来奔跑，寻求耶和华的话，却寻不着。","notes":[]},{"n":13,"t":"“当那日，少年和美貌的少女必因干渴而发昏。","notes":[]},{"n":14,"t":"那些指着撒玛利亚的罪孽起誓的，说：‘但哪，我们指着你那里的神明起誓’，又说：‘我们指着通往别是巴的路起誓’，这些人都必仆倒，永不再起。”","notes":["“罪孽”：原文另译“亚示玛像”；参王下17．30。"]}]},"9":{"heading":"耶和华的审判","verses":[{"n":1,"t":"我看见主站在祭坛旁，说：“你要击打柱顶，使门槛震动，要剪除众人当中为首的，他们中最后的，我必用刀杀戮；无一人能逃避，无一人能逃脱。","notes":["“要剪除...最后的”或译“要砍掉它们，落在众人头上，所剩下的人”。"]},{"n":2,"t":"“虽然他们挖透阴间，我的手必从那里拉出他们；虽然他们爬到天上，我必从那里拿下他们；","notes":[]},{"n":3,"t":"虽然藏在迦密山顶，我必在那里搜寻，擒拿他们；虽然离开我眼前藏在海底，我必在那里命令蛇咬他们；","notes":[]},{"n":4,"t":"虽然被仇敌掳去，我也必在那里命令刀剑杀戮他们；我必定睛在他们身上，降祸不降福。”","notes":[]},{"n":5,"t":"万军的主耶和华触摸地，地就融化，凡住在地上的都必悲哀；全地必如尼罗河涨起，如同埃及的尼罗河落下。","notes":[]},{"n":6,"t":"那在天上建造楼阁、在地上奠定穹苍、召唤海水、使其倾倒在地面上的，耶和华是他的名。","notes":[]},{"n":7,"t":"耶和华说：“以色列人哪，我岂不是看你们如古实人吗？我岂不是领以色列人出埃及地，也领非利士人出迦斐托，领亚兰人出吉珥吗？","notes":["“古实”包括苏丹的大部分和埃塞俄比亚的一部分。"]},{"n":8,"t":"看哪，主耶和华的眼目察看这有罪的国度，要把它从地面上灭绝，却不将雅各家灭绝净尽。”这是耶和华说的。","notes":[]},{"n":9,"t":"“看哪，我发命令，使以色列家在万国中飘流，好像人用筛子筛谷，连一粒也不落在地上。","notes":[]},{"n":10,"t":"我子民中所有的罪人，就是那些说‘灾祸必不靠近，必不追上我们’的，都必死在刀下。”","notes":[]},{"n":11,"t":"“在那日，我必重建大卫倒塌的帐幕，修补其中的缺口；我必建立那遭破坏的，重新修造，如古时一般，","notes":[],"heads":["以色列的复兴"]},{"n":12,"t":"使以色列人接管以东所剩余的和所有称为我名下的国。这是耶和华说的，他要行这事。","notes":[]},{"n":13,"t":"“看哪，日子将到，耕种的必接续收割的，踹葡萄的必接续撒种的；大山要滴下甜酒，小山也被漫过。”这是耶和华说的。","notes":[]},{"n":14,"t":"“我要使以色列被掳的子民归回；他们要重修荒废的城镇，居住在其中；栽植葡萄园，喝其中所出的酒，修造果园，吃其中的果子。","notes":[]},{"n":15,"t":"我要将他们栽植于本地，他们必不再从我所赐给他们的地上被拔出。”这是耶和华－你的神说的。","notes":[]}]}},"OBA":{"1":{"heading":"耶和华惩罚以东","verses":[{"n":1,"t":"俄巴底亚所见的异象。我们从耶和华那里得到消息，有使者被差往列国去：“起来吧，我们要起来与以东争战！”主耶和华论以东如此说：","notes":[]},{"n":2,"t":"看哪，我要使你在列国中为最小，被人大大藐视。","notes":[]},{"n":3,"t":"你狂傲的心欺骗了你，你住在岩穴，居所在高处，心里说：“谁能把我拉下来到地上呢？”","notes":[]},{"n":4,"t":"你虽如鹰高飞，在星宿之间搭窝，我必从那里拉你下来。这是耶和华说的。","notes":[]},{"n":5,"t":"盗贼若来到你那里，小偷夜间来到，岂不是只偷他们所需要的吗？摘葡萄的若来到你那里，岂不留下几串吗？你竟全然灭绝！","notes":[]},{"n":6,"t":"以扫遭到搜查，他隐藏的宝物竟被寻出！","notes":[]},{"n":7,"t":"与你结盟的都驱赶你，直到边界，与你和好的欺骗你，胜过你，吃你饭的人设下圈套陷害你─他却毫无聪明。","notes":["“他却毫无聪明”或译“你却毫无知觉”。"]},{"n":8,"t":"到那日，我岂不从以东除灭智慧人？从以扫山除灭聪明人？这是耶和华说的。","notes":[]},{"n":9,"t":"提幔哪，你的勇士必惊惶，以致以扫山的人都被杀戮剪除。","notes":[]},{"n":10,"t":"因你向兄弟雅各施暴，你必蒙羞，永被剪除。","notes":[],"heads":["以东受罚的原因"]},{"n":11,"t":"当陌生人掳掠雅各的财物，当外邦人进入他的城门，为耶路撒冷抽签分取财物的日子，你竟站在一旁，像与他们同伙。","notes":[]},{"n":12,"t":"你兄弟遭难的日子，你不该瞪着眼看；犹大人被灭的日子，你不该幸灾乐祸；他们遭难的日子，你不该说狂傲的话。","notes":[]},{"n":13,"t":"我子民遭灾的日子，你不该进他们的城门；他们遭灾的日子，你不该瞪着眼看他们受苦；他们遭灾的日子，你不该伸手抢他们的财物。","notes":[]},{"n":14,"t":"他们遭难的日子，你不该站在岔路口剪除他们逃脱的人，你不该交出他们的幸存者。","notes":[]},{"n":15,"t":"耶和华的日子临近万国；你所做的，人也必向你照样做，你的报应必归到自己头上。","notes":[],"heads":["耶和华审判万国"]},{"n":16,"t":"你们在我圣山怎样喝了苦杯，万国必照样不停地喝，且喝且吞，他们就必归于无有。","notes":[]},{"n":17,"t":"但在锡安山必有逃脱的人，那山必成为圣；雅各家必得原有的产业。","notes":["“原有的产业”：七十士译本是“那抢夺他们之人的产业”。"],"heads":["以色列的胜利"]},{"n":18,"t":"雅各家必成为大火，约瑟家成为火焰；以扫家必如碎秸，遭燃烧，被吞灭，以扫家必无幸存者。这是耶和华说的。","notes":[]},{"n":19,"t":"他们必得尼革夫和以扫山，得谢非拉，非利士人之地，他们必得以法莲地和撒玛利亚地，得便雅悯和基列；","notes":["“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”；下同。","“谢非拉”是音译，意思是“低地”。"]},{"n":20,"t":"被掳的以色列大军必得迦南人的地，直到撒勒法，在西法拉被掳的耶路撒冷人必得尼革夫的城镇。","notes":["“迦南”指“腓尼基”。"]},{"n":21,"t":"必有一些解救者上到锡安山，审判以扫山，国度就归耶和华了。","notes":["“一些解救者”：七十士译本是“一些被救出的人”。"]}]}},"JON":{"1":{"heading":"约拿违背耶和华","verses":[{"n":1,"t":"耶和华的话临到亚米太的儿子约拿，说：","notes":[]},{"n":2,"t":"“起来，到尼尼微大城去，向其中的居民宣告，因为他们的恶已达到我面前。”","notes":[]},{"n":3,"t":"约拿却起身，逃往他施去躲避耶和华。他下到约帕，遇见一条船要往他施去。约拿付了船费，就上船，与船上的人同往他施，为要躲避耶和华。","notes":[]},{"n":4,"t":"耶和华在海上刮起大风，海就狂风大作，船几乎破裂。","notes":[]},{"n":5,"t":"水手都惧怕，各人哀求自己的神明。他们把船上的货物抛进海里，为要减轻载重。约拿却下到舱底，躺卧沉睡。","notes":[]},{"n":6,"t":"船长到他那里，对他说：“你怎么还在沉睡呢？起来，求告你的神明，或者神明顾念我们，使我们不致灭亡。”","notes":[]},{"n":7,"t":"船上的人彼此说：“来吧，我们来抽签，看看这灾难临到我们是因谁的缘故。”于是他们就抽签，抽出约拿来。","notes":[]},{"n":8,"t":"他们对约拿说：“请你告诉我们，这灾难临到我们是因谁的缘故呢？你做什么行业？你从哪里来？你是哪一国的人？属哪一族？”","notes":[]},{"n":9,"t":"他说：“我是希伯来人，我敬畏耶和华，天上的神，他创造了沧海和陆地。”","notes":[]},{"n":10,"t":"那些人就大大惧怕，对他说：“你做的是什么事呢？”原来他们已经知道他在躲避耶和华，因为他告诉了他们。","notes":[]},{"n":11,"t":"海浪越來越汹涌，他们就问他说：“我们当向你做什么，才能使海浪平静呢？”","notes":[]},{"n":12,"t":"他对他们说：“你们把我抬起来，抛进海里，海就会平静了；我知道你们遭遇这大风浪是因我的缘故。”","notes":[]},{"n":13,"t":"然而那些人竭力划桨，想要把船靠回陆地，却是不能；因风浪越來越大，扑向他们。","notes":[]},{"n":14,"t":"于是他们求告耶和华说：“耶和华啊，求求你不要因这人的性命使我们灭亡，不要使流无辜人血的罪归给我们；因为你－耶和华随自己的旨意行事。”","notes":[]},{"n":15,"t":"他们把约拿抬起来，抛进海里，海的狂浪就平息了。","notes":[]},{"n":16,"t":"那些人就大大惧怕耶和华，向耶和华献祭许愿。","notes":[]},{"n":17,"t":"耶和华安排一条大鱼吞下约拿，约拿在鱼腹中三日三夜。","notes":[]}]},"2":{"heading":"约拿的祷告","verses":[{"n":1,"t":"约拿在鱼腹中向耶和华－他的神祷告，","notes":[]},{"n":2,"t":"说：“我在患难中求告耶和华，他就应允我；我从阴间的深处呼求，你就俯听我的声音。","notes":[]},{"n":3,"t":"你将我投下深渊，直到海心；大水环绕我，你的波浪洪涛漫过我身。","notes":[]},{"n":4,"t":"我说：‘我从你眼前被驱逐，然而我仍要仰望你的圣殿。’","notes":[]},{"n":5,"t":"众水环绕我，几乎淹没我；深渊围住我；海草缠绕我的头。","notes":[]},{"n":6,"t":"我下沉到山的根基，地的门闩将我永远关住。耶和华－我的神啊，你却将我的性命从地府里救出来。","notes":[]},{"n":7,"t":"我心灵发昏时，就想起耶和华。我的祷告进入你的圣殿，达到你面前。","notes":[]},{"n":8,"t":"那信奉虚无神明的人，丢弃自己的慈爱；","notes":["“虚无神明”：原文是“虚无”。"]},{"n":9,"t":"但我要以感谢的声音向你献祭。我所许的愿，我必偿还。救恩出于耶和华。”","notes":[]},{"n":10,"t":"耶和华吩咐那鱼，鱼就把约拿吐在陆地上。","notes":[]}]},"3":{"heading":"约拿顺服耶和华","verses":[{"n":1,"t":"耶和华的话第二次临到约拿，说：","notes":[]},{"n":2,"t":"“起来，到尼尼微大城去，把我告诉你的信息向其中的居民宣告。”","notes":[]},{"n":3,"t":"约拿就照耶和华的话起来，到尼尼微去。尼尼微是一座极大的城，约有三天的路程。","notes":[]},{"n":4,"t":"约拿进城，走了一天，宣告说：“再过四十天，尼尼微要倾覆了！”","notes":[]},{"n":5,"t":"尼尼微人就信服神，宣告禁食，从最大的到最小的都穿上麻衣。","notes":[]},{"n":6,"t":"这消息传到尼尼微王那里，他就从宝座起来，脱下朝服，披上麻布，坐在灰中。","notes":[]},{"n":7,"t":"他叫人通告尼尼微全城，说：“王和大臣有令，人、畜、牛、羊都不可尝任何东西，不可吃，也不可喝水。","notes":[]},{"n":8,"t":"人与牲畜都要披上麻布，切切求告神。各人要回转离开恶道，离弃自己掌中的残暴。","notes":[]},{"n":9,"t":"谁知道神也许会回心转意，不发烈怒，使我们不致灭亡。”","notes":[]},{"n":10,"t":"神察看他们的行为，见他们离开恶道，神就改变心意，原先所说要降与他们的灾难，他不降了。","notes":[]}]},"4":{"heading":"约拿的愤怒和神的怜悯","verses":[{"n":1,"t":"这事令约拿大大不悦，甚至发怒。","notes":[]},{"n":2,"t":"他就向耶和华祷告，说：“耶和华啊，这不就是我仍在本国的时候所说的吗？我知道你是有恩惠，有怜悯的神，不轻易发怒，有丰盛的慈爱，并且会改变心意，不降那灾难。我就是因为这样，才急速逃往他施去的呀！","notes":[]},{"n":3,"t":"耶和华啊，现在求你取走我的性命吧！因为我死了比活着更好。”","notes":[]},{"n":4,"t":"耶和华说：“你这样发怒，对吗？”","notes":[]},{"n":5,"t":"约拿出城，坐在城的东边，在那里为自己搭了一座棚。他坐在棚子的荫下，要看看城里会发生什么事。","notes":[]},{"n":6,"t":"耶和华神安排了一棵蓖麻，使它生长高过约拿，影子遮盖他的头，使他免受苦难；约拿因这棵蓖麻大大欢喜。","notes":[]},{"n":7,"t":"次日黎明，神却安排一条虫来咬这蓖麻，以致枯干。","notes":[]},{"n":8,"t":"太阳出来的时候，神安排炎热的东风，太阳曝晒约拿的头，使他发昏，他就为自己求死，说：“我死了比活着更好！”","notes":[]},{"n":9,"t":"神对约拿说：“你因这棵蓖麻这样发怒，对吗？”他说：“我发怒以至于死，都是对的！”","notes":[]},{"n":10,"t":"耶和华说：“这棵蓖麻你没有为它操劳，也不是你使它长大的；它一夜生长，一夜枯死，你尚且爱惜；","notes":[]},{"n":11,"t":"何况这尼尼微大城，其中不能分辨左右手的就有十二万多人，还有许多牲畜，我岂能不爱惜呢？”","notes":[]}]}},"MIC":{"1":{"heading":"先知唱哀歌","verses":[{"n":1,"t":"当犹大王约坦、亚哈斯、希西家在位的时候，耶和华的话临到摩利沙人弥迦，他见到有关撒玛利亚和耶路撒冷的异象。","notes":[]},{"n":2,"t":"万民哪，你们都要听！地和其上所有的，要留心听！主耶和华要从他的圣殿指证你们的不是。","notes":[]},{"n":3,"t":"看哪，耶和华从他的居所出来，降临步行地之高处。","notes":[]},{"n":4,"t":"众山在他底下熔化，诸谷崩裂，如蜡熔在火中，如水冲下山坡。","notes":[]},{"n":5,"t":"这都是因雅各的罪过，因以色列家的罪恶。雅各的罪过在哪里呢？岂不是在撒玛利亚吗？犹大的丘坛在哪里呢？岂不是在耶路撒冷吗？","notes":[]},{"n":6,"t":"因此，我必使撒玛利亚变为田野的废墟，用以栽植葡萄；我必把它的石头倒在山谷，掀开它的地基。","notes":[]},{"n":7,"t":"城里一切雕刻的偶像必被打碎，行淫的赏金全被火烧，我要毁灭它的一切偶像；因为从妓女的赏金积聚而来的，它们仍归为妓女的赏金。","notes":[]},{"n":8,"t":"为此我要大声哀号，赤身赤脚行走；我要呼号如野狗，哀鸣如鸵鸟。","notes":[]},{"n":9,"t":"因为撒玛利亚的创伤无法医治，蔓延到犹大，到了我百姓的城门，直达耶路撒冷。","notes":[]},{"n":10,"t":"不要在迦特宣扬这事，千万不要哭泣；却要在伯．亚弗拉翻滚于灰尘中。","notes":["“宣扬”与“迦特”的希伯来话发音相近。","“灰尘”与“亚弗拉”的希伯来话发音相近。"],"heads":["敌人迫近耶路撒冷"]},{"n":11,"t":"沙斐的居民哪，要赤身羞愧地经过，撒南的居民不敢出门，伯．以薛哀哭，不再支持你们。","notes":[]},{"n":12,"t":"玛律的居民心甚忧急，切望得着福气，因为灾祸已从耶和华那里临到耶路撒冷的城门。","notes":[]},{"n":13,"t":"拉吉的居民哪，要用快马套车；锡安的罪由你而起，以色列的罪过在你那里显出。","notes":["“用快马”与“拉吉”的希伯来话发音相近。","“锡安”：原文直译“锡安女子”。"]},{"n":14,"t":"因此，你要将送别礼送到摩利设．迦特；亚革悉的众家族必用诡诈待以色列诸王。","notes":["“诡诈”与“亚革悉”的希伯来话发音相近。"]},{"n":15,"t":"玛利沙的居民哪，我必使抢夺者来到你这里；以色列的贵族必来到亚杜兰。","notes":["“贵族”：原文是“荣耀”。"]},{"n":16,"t":"犹大啊，为了你所喜爱的儿女，你要剪发，剃光头，要使你的头光秃，如同秃鹰，因为他们被掳去离开你了。","notes":[]}]},"2":{"heading":"欺压者的命运","verses":[{"n":1,"t":"祸哉，那些在床上图谋罪孽、筹划恶事的人！天一亮，他们因手中有能力就去行恶。","notes":[]},{"n":2,"t":"他们看上田地就占据，贪图房屋便夺取；他们欺压户主和他的家庭，霸占人和他的产业。","notes":[]},{"n":3,"t":"所以耶和华如此说：看哪，我筹划灾祸降与这家族；这灾祸在你们颈项上无法解脱，你们也不能昂首而行，因为这是灾祸的时刻。","notes":[]},{"n":4,"t":"到那日，必有人为你们唱诗歌，用悲哀的哀歌哀号，说：“我们全然败落，我百姓的产业易主了！耶和华竟然使它离开我，我们的田地为悖逆的人所瓜分了！”","notes":[]},{"n":5,"t":"因此，你必无人能在耶和华的会中抽签拉绳。","notes":["“抽签拉绳”意思是“划地为界”。"]},{"n":6,"t":"他们传讲说：“不可传讲；人都不可传讲这些事，羞辱不会临到我们。”","notes":[]},{"n":7,"t":"雅各家啊，可这么说吗？耶和华没有耐心吗？这些事是他所行的吗？我的言语岂不是与行动正直的人有益吗？","notes":["“雅各家…说吗”：原文另译“雅各家能被诅咒吗”。"]},{"n":8,"t":"然而，近来我的百姓兴起如仇敌。你们剥去那些安然行路、不愿打仗之人身上的外衣，","notes":[]},{"n":9,"t":"把我百姓中的妇人从安乐家中赶出，又将我的荣耀从她们孩子身上永远夺去。","notes":[]},{"n":10,"t":"起来，走吧！这里并非安歇之处；因为不洁净带来毁坏，且是大大的毁坏。","notes":[]},{"n":11,"t":"若有人心存虚假，用谎言说：“我向你们传讲可得清酒和烈酒”，那人就必作这百姓的传讲者。","notes":["“用谎言说”：原文另译“我会用谎言说”。","“烈酒”与“谎言”的希伯来话发音相近。"]},{"n":12,"t":"雅各家啊，我定要聚集你们，定要召集以色列的余民，将他们安置在一处，如波斯拉的羊，又如草场上的羊群，人数众多，大大喧哗。","notes":["“波斯拉”或译“羊圈”。"]},{"n":13,"t":"开路的在他们前面上去，直闯过城门，从城门出去；他们的王在前面行，耶和华在他们的前头。","notes":[]}]},"3":{"heading":"斥责以色列的领袖","verses":[{"n":1,"t":"于是我说： 雅各的领袖，以色列家的官长啊，你们要听！你们岂不知道公平吗？","notes":[]},{"n":2,"t":"你们恶善好恶，剥我百姓身上的皮，从他们的骨头上剔肉，","notes":["“我百姓”：原文是“他们”。"]},{"n":3,"t":"你们吃我百姓的肉，剥他们的皮，打断他们的骨头，如切块下锅，如釜中的肉。","notes":["“如切块”：七十士译本是“如切肉块”。"]},{"n":4,"t":"到了遭灾的时候，这些人要哀求耶和华，他却不应允他们。那时，因他们所行的恶，他必转脸离开他们。","notes":[]},{"n":5,"t":"论到使我百姓走入歧途的先知，他们牙齿有所嚼，就呼喊说：“平安！”谁不给他们吃，就扬言攻击他，耶和华如此说：","notes":[]},{"n":6,"t":"你们因此必遭遇黑夜，看不到异象；遭遇幽暗，无法占卜。太阳必向先知沉落，白昼转为黑暗。","notes":[]},{"n":7,"t":"先见必抱愧，占卜的必蒙羞，他们全都捂着胡须，因为神不应允他们。","notes":[]},{"n":8,"t":"至于我，我藉耶和华的灵，满有能力、公平和勇气，可以向雅各述说他的过犯，向以色列指出他的罪恶。","notes":[]},{"n":9,"t":"当听这话，雅各家的领袖，以色列家的官长啊！你们厌弃公平，在一切事上屈枉正直；","notes":[]},{"n":10,"t":"以血建立锡安，以罪孽建造耶路撒冷。","notes":[]},{"n":11,"t":"城里的领袖为贿赂行审判，祭司为酬劳施训诲，先知为银钱行占卜；他们却倚赖耶和华，说：“耶和华不是在我们中间吗？灾祸必不临到我们。”","notes":[]},{"n":12,"t":"因此，为你们的缘故，锡安要被耕种像一块田地，耶路撒冷要变为废墟，这殿的山必如丛林的高处。","notes":[]}]},"4":{"heading":"永恒的和平","verses":[{"n":1,"t":"末后的日子，耶和华殿的山必坚立，超乎诸山，高举过于万岭；万民都要流归这山。","notes":[]},{"n":2,"t":"必有许多民族前往，说：“来吧，我们登耶和华的山，到雅各神的殿。他必将他的道指教我们，我们也要行他的路。”因为教诲必出于锡安，耶和华的言语必出于耶路撒冷。","notes":[]},{"n":3,"t":"他必在许多民族中施行审判，为远方强盛的国断定是非。他们要将刀打成犁头，把枪打成镰刀。这国不举刀攻击那国，他们也不再学习战事。","notes":[]},{"n":4,"t":"人人都要坐在自己的葡萄树和无花果树下，无人使他们惊吓；这是万军之耶和华亲口说的。","notes":[]},{"n":5,"t":"万民都奉自己神明的名行事，我们却要奉耶和华－我们神的名而行，直到永永远远。","notes":[]},{"n":6,"t":"耶和华说：在那日，我必聚集瘸腿的，召集被赶逐的，以及我所惩治的人。","notes":[],"heads":["以色列人归回本国"]},{"n":7,"t":"我要使瘸腿的成为余民，使被赶到远方的成为强盛之国。耶和华要在锡安山作王治理他们，从今直到永远。","notes":[]},{"n":8,"t":"你，以得台，锡安的山冈啊，先前的权柄必归给你，耶路撒冷的国权必将归还。","notes":["“以得台”就是“牧羊人的瞭望台”；参创35．21。","“锡安”：原文直译“锡安女子”；下同。","“耶路撒冷”：原文是“耶路撒冷女子”。"]},{"n":9,"t":"现在，你为何大声呼喊呢？你中间没有君王，你的谋士灭绝，以致疼痛抓住你，如临产的妇人吗？","notes":[]},{"n":10,"t":"锡安哪，你要疼痛生产，仿佛临产的妇人；因为你必从城里出来，住在田野；你要到巴比伦去，在那里，你要蒙解救，在那里，耶和华必救赎你脱离仇敌的手掌。","notes":[]},{"n":11,"t":"现在，许多国家聚集攻击你，说：“让锡安被玷污！让我们亲眼看到！”","notes":[]},{"n":12,"t":"他们却不知道耶和华的意念，也不明白他的筹算，他聚集他们，像把禾捆聚到禾场。","notes":[]},{"n":13,"t":"锡安哪，起来踹谷吧！我必使你的角成为铁，使你的蹄成为铜。你必打碎许多民族，将他们的财宝献给耶和华，将他们的财富献给全地的主。","notes":[]}]},"5":{"heading":"神应许一位掌权者出于伯利恒","verses":[{"n":1,"t":"成群的民哪，现在要聚集成队；仇敌前来围攻我们，要用杖击打以色列领袖的脸颊。","notes":["“民”：原文是“女儿”。"]},{"n":2,"t":"伯利恒的以法他啊，你在犹大诸城中虽小，将来必有一位从你那里出来，在以色列中为我作掌权者；他的根源自亘古，从太初就有。","notes":[]},{"n":3,"t":"因此，耶和华要将以色列人交给敌人，直到临产的妇人生下孩子；那时，他其余的弟兄必回到以色列人那里。","notes":[]},{"n":4,"t":"他必倚靠耶和华的大能，倚靠耶和华－他神之名的威严，站立并牧养，使他们安然居住；因为现在他必尊大，直到地极。","notes":[]},{"n":5,"t":"这位就是和平。当亚述侵入我们领土，践踏我们宫殿时，我们就立七个牧者，八个领袖攻击它。","notes":["“和平”或译“平安”。"]},{"n":6,"t":"他们要用刀剑毁坏亚述地和宁录地的关口。当亚述侵入我们领土，践踏我们边境时，他必拯救我们。","notes":["“宁录地的关口”：有古译本是“向宁录地拔出刀来”。"]},{"n":7,"t":"雅各的余民必在许多民族中，如从耶和华降下的露水，又如甘霖降在草上；他们不倚靠人，也不仰赖世人。","notes":[]},{"n":8,"t":"雅各的余民必在列国中，在许多民族中，如林间百兽中的狮子，又如少壮狮子在羊群中；他若经过就必践踏撕裂，无人搭救。","notes":[]},{"n":9,"t":"愿你的手举起，高过敌人！愿你的仇敌都被剪除！","notes":[]},{"n":10,"t":"耶和华说：到那日，我必从你中间剪除马匹，毁坏战车；","notes":[]},{"n":11,"t":"除灭你国中的城镇，拆毁你一切的堡垒；","notes":[]},{"n":12,"t":"除掉你手中的邪术，你那里也不再有占卜的人。","notes":[]},{"n":13,"t":"我必从你中间除灭雕刻的偶像和柱像，你就不再跪拜自己手所造的；","notes":[]},{"n":14,"t":"我必从你中间拔除亚舍拉，毁灭你的城镇；","notes":[]},{"n":15,"t":"我必在怒气和愤怒中报应那不听从我的列国。","notes":[]}]},"6":{"heading":"耶和华谴责以色列","verses":[{"n":1,"t":"当听耶和华说的话：起来，向山岭争辩，使冈陵听见你的声音。","notes":[]},{"n":2,"t":"山岭啊，要听耶和华的指控！大地永久的根基啊，要听！因耶和华控告他的百姓，与以色列争辩。","notes":[]},{"n":3,"t":"“我的百姓啊，我向你做了什么呢？我在什么事上使你厌烦？你回答我吧！","notes":[]},{"n":4,"t":"我曾将你从埃及地领出来，从为奴之家救赎你，我差遣摩西、亚伦和米利暗在你前面带领。","notes":[]},{"n":5,"t":"我的百姓啊，当记念从前摩押王巴勒如何筹算，比珥的儿子巴兰如何回应他，当记念从什亭到吉甲所发生的事，好使你们明白耶和华公义的作为。”","notes":[]},{"n":6,"t":"“我朝见耶和华，在至高神面前跪拜，当献上什么呢？难道献一岁的牛犊为燔祭来朝见他吗？","notes":[],"heads":["耶和华的要求"]},{"n":7,"t":"耶和华岂喜悦千千的公羊，或是万万的油河吗？我岂可为自己的过犯献我的长子，为自己的罪恶献我所亲生的吗？”","notes":[]},{"n":8,"t":"世人哪，耶和华已指示你何为善。他向你所要的是什么呢？只要你行公义，好怜悯，存谦卑的心与你的神同行。","notes":[]},{"n":9,"t":"耶和华向这城呼叫─看重你的名是真智慧─你们当听惩罚和派定惩罚的人。","notes":["“看重...真智慧”：七十士译本是“他会拯救敬畏他名的人”。","“惩罚”：原文是“刑杖”；下同。","“你们当听...的人”：有古译本是“听啊，支派和城的众民！”七十士译本是“听啊，支派，谁管治这城？”"]},{"n":10,"t":"恶人家中不是仍有不义之财和惹人生气的变小了的伊法吗？","notes":[]},{"n":11,"t":"我若用不公道的天平和袋中诡诈的法码，岂可算为清白呢？","notes":[]},{"n":12,"t":"城里的有钱人遍行残暴，其中的居民说谎话，口中的舌头尽是诡诈。","notes":[]},{"n":13,"t":"因此，我也击打你，使你受伤，因你的罪恶使你受惊骇。","notes":["“我也击打你，使你受伤”：七十士译本和其他古译本是“我也开始击打你”。"]},{"n":14,"t":"你要吃，却吃不饱，你的肚子仍是空空。你必被挪去，不得逃脱；如有逃脱的，我必交给刀剑。","notes":[]},{"n":15,"t":"你撒种，却不得收割；踹橄榄，却不得油抹身；有新酒，却不得酒喝。","notes":[]},{"n":16,"t":"因为你遵守暗利的规条，行亚哈家一切所行的，顺从他们的计谋；因此，我必使你荒凉，使你的居民遭人嗤笑，你们也必担当我百姓的羞辱。","notes":[]}]},"7":{"heading":"以色列人的腐败","verses":[{"n":1,"t":"我有祸了！我好像夏日收割后的果子，又如收成之后剩余的葡萄，没有一挂可吃的，也没有我心所渴想初熟的无花果。","notes":[]},{"n":2,"t":"地上的虔诚人灭尽了，人世间已无正直的人；他们都埋伏，为要流人的血，用罗网猎取自己的弟兄。","notes":[]},{"n":3,"t":"他们双手善于作恶，君王和审判官都索取贿赂；位高的人吐出心中的欲望，彼此勾结。","notes":["“彼此勾结”：原文另译“祸哉，公义被扭曲了”。"]},{"n":4,"t":"他们当中最好的，不过像蒺藜；最正直的，不过如荆棘篱笆。你守候的日子，惩罚已经来到，他们必扰乱不安。","notes":[]},{"n":5,"t":"不可倚赖邻舍，不可信靠密友；甚至对躺在你怀中的妻子也要守住你的口。","notes":[]},{"n":6,"t":"因为儿子藐视父亲，女儿抵挡母亲，媳妇抗拒婆婆，人的仇敌就是自己家里的人。","notes":[]},{"n":7,"t":"至于我，我要仰望耶和华，等候那救我的神；我的神必应允我。","notes":[]},{"n":8,"t":"我的仇敌啊，不要向我夸耀。我虽跌倒，仍要起来；虽坐在黑暗里，耶和华却作我的光。","notes":[],"heads":["耶和华拯救他的子民"]},{"n":9,"t":"我要承受耶和华的恼怒，直到他为我辩护，为我伸冤，因我得罪了他；他要领我进入光明，我必得见他的公义。","notes":[]},{"n":10,"t":"那时我的仇敌看见这事就羞愧，他曾对我说：“耶和华－你的神在哪里？”我必亲眼见他遭报，现在，他必被践踏，如同街上的泥土。","notes":[]},{"n":11,"t":"你的城墙重修的日子到了！到那日，边界必扩展。","notes":[]},{"n":12,"t":"到那日，人必从亚述，从埃及的城镇，从埃及到大河，从这海到那海，从这山到那山，都归到你这里。","notes":[]},{"n":13,"t":"然而，因居民的缘故，为了他们行事的结果。这地必然荒凉。","notes":[]},{"n":14,"t":"求你在迦密的树林中，以你的杖牧放你独居的民，你产业中的羊群；愿他们像古时一样，牧放在巴珊和基列。","notes":["“迦密”或译“佳美园地”。"],"heads":["耶和华怜悯以色列"]},{"n":15,"t":"我要显奇事给他们看，好像出埃及地的时候一样。","notes":[]},{"n":16,"t":"列国看见，虽大有势力仍觉惭愧；他们必用手捂口，掩耳不听。","notes":[]},{"n":17,"t":"他们要舔土如蛇，又如地上爬行的动物，战战兢兢离开他们的营寨；他们必畏惧耶和华─我们的神，也必因你而害怕。","notes":[]},{"n":18,"t":"有哪一个神明像你，赦免罪孽，饶恕他产业中余民的罪过？他不永远怀怒，喜爱施恩。","notes":[]},{"n":19,"t":"他必转回怜悯我们，把我们的罪孽踏在脚下。你必将他们一切的罪投于深海。","notes":["“他”：原文另译“你”。","“他们”：七十士译本和其他古译本是“我们”。"]},{"n":20,"t":"你必按古时向我们列祖起誓的话，以信实待雅各，向亚伯拉罕施慈爱。","notes":[]}]}},"NAM":{"1":{"heading":"耶和华向尼尼微发怒","verses":[{"n":1,"t":"论尼尼微的默示，伊勒歌斯人那鸿所见异象的书。","notes":[]},{"n":2,"t":"耶和华是忌邪、报应的神。耶和华施报应，大有愤怒；耶和华向他的敌人报应，向他的仇敌怀怒。","notes":["“忌邪”：原文是“妒忌”，意思是“不容许有对立的神明”。"]},{"n":3,"t":"耶和华不轻易发怒，大有能力，但耶和华万不以有罪的为无罪。他的道路在旋风和暴风之中，云彩为他脚下的尘土。","notes":[]},{"n":4,"t":"他斥责海，使海枯干，使一切江河干涸。巴珊和迦密衰残，黎巴嫩的花草也衰残了。","notes":[]},{"n":5,"t":"大山因他震动，小山也都融化；大地在他面前突起，世界和住在其间的也都如此。","notes":[]},{"n":6,"t":"他发愤恨，谁能立得住呢？他发烈怒，谁能当得起呢？他的愤怒如火倾泄而出，磐石因他崩裂。","notes":[]},{"n":7,"t":"耶和华本为善，在患难的日子为人的保障，并且认识那些投靠他的人；","notes":[]},{"n":8,"t":"但他必以涨溢的洪水淹没其地方，又驱逐仇敌进入黑暗。","notes":["“其地方”：七十士译本是“起来攻击的人”。"]},{"n":9,"t":"你们筹划何种计谋攻击耶和华呢？他必终结一切，仇敌不会再度兴起。","notes":["“仇敌”或译“灾难”。"]},{"n":10,"t":"你们像杂乱的荆棘，像喝醉了的人，又如枯干的碎秸，全然烧灭。","notes":[]},{"n":11,"t":"有一人从你那里出来，图谋邪恶，设恶计攻击耶和华。","notes":[]},{"n":12,"t":"耶和华如此说：“他们虽然势力强大，人数众多，也要被剪除，归于无有。我虽曾使你受苦，却不再使你受苦。","notes":[]},{"n":13,"t":"现在，我要从你身上折断他的轭，解开捆绑你的绳索。”","notes":[]},{"n":14,"t":"耶和华已经发命令，指着你说：“你的名下必不再留后；我要从你神明的庙中除灭雕刻的偶像和铸造的偶像，我必因你的卑贱，为你预备坟墓。”","notes":[]},{"n":15,"t":"看哪，在山上有报佳音、传平安之人的脚踪。犹大啊，守你的节期，还你的愿吧！因为恶人不再侵犯你，他已灭绝净尽了。","notes":[]}]},"2":{"heading":"尼尼微的倾覆","verses":[{"n":1,"t":"那打碎你的人上到你面前。要看守堡垒，把守道路，要挺起腰来，大大使力。","notes":["“打碎你的人”或译“驱散你的人”。"]},{"n":2,"t":"耶和华复兴雅各的荣华，像复兴以色列的荣华；因为蹂躏者曾经蹂躏他们，毁坏了他们的葡萄枝。","notes":[]},{"n":3,"t":"他勇士的盾牌是红的，精兵都穿朱红衣服。在预备打仗的日子，战车上的铁闪烁如火，柏木的枪杆也已举起；","notes":["“战车...如火”：原文另译“战车如火把的火”。","“柏木...举起”：七十士译本是“骑兵在跃马前进”。"]},{"n":4,"t":"战车在街上疾行，在广场上来往奔驰，形状如火把，飞驰如闪电。","notes":[]},{"n":5,"t":"他招聚他的贵族；他们前行时绊跌，速上城墙，预备屏障。","notes":["“他”指“尼尼微王”。"]},{"n":6,"t":"河闸开放，宫殿冲没。","notes":[]},{"n":7,"t":"这是命定之事：王后赤身被掳，宫女捶胸，哀鸣如鸽子。","notes":["“这是命定之事...被掳”或译“女神像赤身被掳”；原文另可音译作“胡钗芙王后赤身被掳”。"]},{"n":8,"t":"尼尼微自古以来如同聚水的池子；现在居民都在逃跑。“站住！站住！”却无人回转。","notes":["“尼尼微...逃跑”：七十士译本是“至于尼尼微，它的水如同一个漏水的池子”。"]},{"n":9,"t":"你们抢夺金子吧！你们抢夺银子吧！因为所积蓄的无穷，华美的宝器无数。","notes":[]},{"n":10,"t":"荒芜，荒凉，全然荒废，人心害怕，双膝颤抖，腰部疼痛，脸都变色。","notes":[]},{"n":11,"t":"狮子的洞，幼狮喂养之处在哪里呢？公狮、母狮、小狮出入，无人使它们惊吓之地在哪里呢？","notes":[]},{"n":12,"t":"公狮撕碎的足够给幼狮吃，又为母狮掐死猎物，把猎物塞满它的洞穴，把撕碎的装满它的窝。","notes":[]},{"n":13,"t":"看哪，我与你为敌，将它的战车焚烧成烟，刀剑必吞灭你的少壮狮子；我必从地上除灭你的猎物，你使者的声音必不再听见。这是万军之耶和华说的。","notes":["“它的战车”：原文另译“你的战车”；七十士译本是“你的群众”。"]}]},"3":{"heading":"","verses":[{"n":1,"t":"祸哉！这流人血的城，欺诈连连，抢夺充斥，掳掠的事总不止息。","notes":[]},{"n":2,"t":"鞭声响亮，车轮轰轰，马匹跳跃，战车奔腾；","notes":[]},{"n":3,"t":"骑兵争先，刀剑发光，枪矛闪烁，被杀的甚多，尸首成堆，尸骸无数，人因尸骸而绊跌，","notes":[]},{"n":4,"t":"都因那美貌的妓女多有淫行，惯行邪术，藉淫行诱惑列国，用邪术诱惑万族。","notes":["“诱惑”：原文是“卖”；下同。"]},{"n":5,"t":"看哪，我与你为敌，掀开你的下摆，蒙在你脸上，使列邦看见你的赤体，使列国观看你的羞辱。这是万军之耶和华说的。","notes":[]},{"n":6,"t":"我必将可憎污秽之物抛在你身上，使你被藐视，为众人所观看。","notes":[]},{"n":7,"t":"凡看见你的，都必逃离你，说：“尼尼微荒凉了！有谁为你悲伤呢？我何处找到安慰你的人呢？”","notes":[]},{"n":8,"t":"你能胜过挪亚们吗？它坐落在众河之间，周围有水，海作它的城郭，海作它的城墙。","notes":["“挪亚们”就是埃及的底比斯，也称“挪”。","“海”指尼罗河；下同。","“海”：七十士译本是“众水”。"]},{"n":9,"t":"古实和埃及是它的力量，没有穷尽，弗人和路比人是它的帮手。","notes":["“古实”包括苏丹的大部分和埃塞俄比亚的一部分。","“弗”是利比亚的一部分。","“路比”就是利比亚。"]},{"n":10,"t":"但它被流放，被人掳去，它的婴孩也被摔碎在各街头；人为它的贵族抽签，它的权贵都被锁链锁住。","notes":[]},{"n":11,"t":"你也必喝醉，昏迷错乱，并因仇敌的缘故寻求庇护。","notes":[]},{"n":12,"t":"你一切的堡垒必如无花果树上初熟的果子，一经摇动，就落在想吃的人口中。","notes":[]},{"n":13,"t":"看哪，你中间的士兵是妇女，你国中的关口向仇敌敞开，你的门闩被火焚烧。","notes":[]},{"n":14,"t":"你要打水预备受困；要加强防御，取土踹泥，做成砖模。","notes":[]},{"n":15,"t":"在那里，火要吞灭你，刀必杀戮你，如蝻子般吞灭你。你人数增多如蝻子，增多如蝗虫吧！","notes":[]},{"n":16,"t":"你增添商贾，多过天上的星宿；如蝻子蜕皮飞去。","notes":[]},{"n":17,"t":"你的领袖多如蝗虫，你的将军仿佛成群的蝗虫；天凉时齐落在篱笆上，太阳一出就飞去，人不知道落在何处。","notes":[]},{"n":18,"t":"亚述王啊，你的牧人睡觉，你的贵族躺卧，你的百姓散在山间，无人招聚。","notes":["“躺卧”：原文另译“安歇”。"]},{"n":19,"t":"你的损伤并未减轻，你的伤痕极其重大。凡听见这消息的人都因你拍掌。有谁没有时常遭受你的暴行呢？","notes":[]}]}},"HAB":{"1":{"heading":"哈巴谷的诉苦","verses":[{"n":1,"t":"哈巴谷先知所看见的默示。","notes":[]},{"n":2,"t":"耶和华啊，我呼求，你不应允，要到几时呢？我向你呼喊“暴力！”你还不拯救？","notes":[]},{"n":3,"t":"你为何使我看见罪孽？你为何坐视奸恶呢？毁灭和凶暴在我面前，争执与纷争不断发生。","notes":[]},{"n":4,"t":"因此律法无效，公理从未彰显。恶人围困义人，所以公理遭受扭曲。","notes":[]},{"n":5,"t":"你们要向列国观看，注意看，要惊奇，再惊奇！因为在你们的日子，有一件事发生，尽管有人说了，你们还是不信。","notes":["“你们要向列国观看”：七十士译本是“你们这些藐视的人要观看”。","“有一件事发生”：七十士译本是“我行一件事”。"],"heads":["耶和华的回答"]},{"n":6,"t":"看哪，我必兴起迦勒底人，就是那残忍暴躁之民，通行遍地，霸占不属自己的住处。","notes":[]},{"n":7,"t":"他威武可畏，审判与威权都由他而出。","notes":[]},{"n":8,"t":"他的马比豹更快，比晚上的野狼更猛。他的战马跳跃，他的战马从远方而来；他们飞跑，如鹰急速抓食，","notes":["“晚上”：七十士译本是“阿拉伯”。","“他的战马跳跃...而来”：七十士译本是“他的骑兵奔驰，从远方而来”。"]},{"n":9,"t":"都为施行残暴而来，他们的脸面向东，聚集俘虏，多如尘沙。","notes":["“向东”：原文另译“向前”。"]},{"n":10,"t":"他讥诮列王，嘲讽领袖，嗤笑一切堡垒，堆土攻取它。","notes":[]},{"n":11,"t":"那时，他如风猛然扫过，他背叛，显为有罪；他以自己的力量为神明。","notes":[]},{"n":12,"t":"耶和华－我的神，我的圣者啊，你不是从亘古就有吗？我们必不致死。耶和华啊，你派他为要行审判；磐石啊，你立他为要惩治人。","notes":[],"heads":["哈巴谷又诉苦"]},{"n":13,"t":"你的眼目清洁，不看邪恶，也不看奸恶，为何你却看着人行诡诈呢？恶人吞灭比自己公义的人，为何你保持沉默呢？","notes":[]},{"n":14,"t":"你为何使人如海中的鱼，又如无人管辖的爬行动物呢？","notes":[]},{"n":15,"t":"他用钩子把他们全拉上来，用罗网捕获他们，拉渔网聚集他们。因此，他欢喜快乐，","notes":[]},{"n":16,"t":"向罗网献祭，向渔网烧香；因为他藉此得丰盛的收获与肥美的食物。","notes":[]},{"n":17,"t":"但他岂可因此屡屡倒空罗网，时常杀戮列国的人，毫不顾惜呢？","notes":["“倒空罗网”：死海古卷是“拔刀出鞘”。"]}]},"2":{"heading":"耶和华回答哈巴谷","verses":[{"n":1,"t":"我要站在我的瞭望台，立在城楼上观看，看耶和华要对我说什么，我可用什么话向他诉冤。","notes":["“城楼”：死海古卷是“我的城楼”。"]},{"n":2,"t":"耶和华回答我，说：将这默示清楚地写在看板上，使人容易朗读。","notes":["“使人容易朗读”：原文是“使跑的人也可以朗读”。"]},{"n":3,"t":"因为这默示有一定的日期，论及终局，绝不落空。它虽然耽延，你要等候；因为它必临到，不再迟延。","notes":[]},{"n":4,"t":"看哪，恶人自高自大，心不正直；惟义人必因他的信得生。","notes":["“因他的信得生”或译“因他的信实得生”；七十士译本是“因我的信实得生”。"]},{"n":5,"t":"他因酒诡诈、狂傲、不安于位；他张开喉咙，好像阴间，如死亡不能知足，他聚集万国，招聚万民全归自己。","notes":["“张开喉咙”或译“扩充心欲”。"],"heads":["不义的结局"]},{"n":6,"t":"这些人岂不都要提起诗歌和俗语，嘲讽他说：祸哉！你增添不属自己的财物，靠押金发财，要到几时呢？","notes":[]},{"n":7,"t":"咬伤你的岂不忽然兴起，扰害你的岂不突然崛起，你就成为他们的掳物吗？","notes":["“咬伤你的”或译“借你钱的”。"]},{"n":8,"t":"因你抢夺许多国家，流人的血，向土地、城镇和全城的居民施行残暴，各国残存之民都必抢夺你。","notes":[]},{"n":9,"t":"祸哉！那为本家积蓄不义之财、在高处搭窝、指望得免灾祸的人！","notes":[]},{"n":10,"t":"你图谋剪除许多民族，犯了罪，使自己的家蒙羞，自害己命。","notes":[]},{"n":11,"t":"墙里的石头要呼叫，屋内的栋梁必应声。","notes":[]},{"n":12,"t":"祸哉！那以鲜血建城、以罪孽造镇的人！","notes":[]},{"n":13,"t":"看哪，这不都是出于万军之耶和华吗？万民劳碌得来的被火焚烧，万族辛苦建造的，归于虚空。","notes":["“看哪，这不都是”：原文另译“它们不都是”。"]},{"n":14,"t":"全地都必认识耶和华的荣耀，好像水充满海洋一般。","notes":[]},{"n":15,"t":"祸哉！那给邻舍酒喝，加上毒物，使人喝醉，为要看见他们下体的人！","notes":["“加上毒物”或译“倾倒怒气”。"]},{"n":16,"t":"你满受羞辱，不得荣耀；你也喝吧，显明你是未受割礼的！耶和华右手的杯必传到你那里，你的荣耀就变为羞辱。","notes":["“显明你是未受割礼的”：死海古卷、一些古卷和七十士译本是“摇摇晃晃吧”。"]},{"n":17,"t":"黎巴嫩所受的残暴必淹没你，野兽所遭遇的毁灭使你惊吓；因你流人的血，向土地、城镇和全城的居民施行残暴。","notes":["“使你惊吓”是根据七十士译本和其他古译本；原文是“使它们惊吓”。"]},{"n":18,"t":"偶像有什么益处呢？制造者雕刻它，铸成偶像，作虚假的教师；制造者倚靠的是自己所做的哑巴偶像。","notes":[]},{"n":19,"t":"祸哉！那对木头说“醒起”，对哑巴石头说“起来”的人！偶像岂能教导人呢？看哪，它以金银包裹，其中并无气息。","notes":[]},{"n":20,"t":"惟耶和华在他的圣殿中，全地都当在他面前肃静。","notes":[]}]},"3":{"heading":"哈巴谷的祈祷","verses":[{"n":1,"t":"哈巴谷先知的祷告，调用流离歌。","notes":[]},{"n":2,"t":"耶和华啊，我听见你的名声；耶和华啊，我惧怕你的作为。求你在这些年间复兴你的作为，在这些年间将它显明出来；在发怒的时候以怜悯为念。","notes":["“在这些年间”：七十士译本是“这些年临近的时候”。","“将它显明出来”：七十士译本是“你会显明出来”。"]},{"n":3,"t":"神从提幔而来，圣者从巴兰山临到；（细拉）他的荣光遮蔽诸天，颂赞遍满全地。","notes":[]},{"n":4,"t":"他的辉煌如同日光，从他手里发出光芒，那里隐藏他的能力。","notes":["“那里”：原文另译“天上”。"]},{"n":5,"t":"在他前面有瘟疫流行，在他脚下有热症发出。","notes":[]},{"n":6,"t":"他站立，震动大地，他观看，震动列国。永久的山崩裂，长存的岭塌陷，他的作为与古时一样。","notes":["“震动”或译“量”。"]},{"n":7,"t":"我见古珊的帐棚遭难，米甸地的幔子动摇。","notes":[]},{"n":8,"t":"耶和华啊，你岂是向江河发怒，向江河生气，向海洋发烈怒吗？你骑在马上，坐在得胜的战车上，","notes":[]},{"n":9,"t":"你的弓全然显露，箭是发誓的言语；（细拉）你以江河分开大地。","notes":["“你的弓全然显露”：原文另译“你打开弓套”。","“箭是发誓的言语”：原文另译“箭在弦上待命”；七十士译本的一个抄本是“你把你的箭袋装满了箭”。"]},{"n":10,"t":"山岭见你，无不战抖；大水泛滥而过，深渊发声，汹涌翻腾。","notes":["“汹涌翻腾”：原文是“向上举手”。"]},{"n":11,"t":"因你的箭射出光芒，你的枪闪出光耀，日月都停在原处。","notes":[]},{"n":12,"t":"你发怒遍行大地，以怒气责打列国，如打谷一般。","notes":[]},{"n":13,"t":"你出来拯救你的百姓，拯救你的受膏者；你打破恶人之家的头，暴露其根基，直到颈项。 （细拉）","notes":["“颈项”意思是“上端”。"]},{"n":14,"t":"你以其戈矛刺透他战士的头；他们如旋风将我刮散，他们喜爱暗中吞吃困苦的人。","notes":["“我”：原文另译“我们”。"]},{"n":15,"t":"你骑马践踏海，践踏汹涌的大水。","notes":[]},{"n":16,"t":"我听见这声音，身体战兢，嘴唇发颤，骨中朽烂，在所立之处战兢；但我安静等候灾难之日临到那上来侵犯我们的民。","notes":["“在所立之处战兢”：原文另译“我的脚步在所立之处战兢”。","“但我...民”或译“我只可安静等候灾难之日临到，侵犯我们的民上来”。"]},{"n":17,"t":"虽然无花果树不发旺，葡萄树不结果，橄榄树也不收成，田地不出粮食，圈中绝了羊，棚内也没有牛；","notes":[]},{"n":18,"t":"然而，我要因耶和华欢欣，因救我的神喜乐。","notes":[]},{"n":19,"t":"主耶和华是我的力量，他使我的脚快如母鹿，又使我稳行在高处。这歌交给圣咏团长，用丝弦的乐器。","notes":[]}]}},"ZEP":{"1":{"heading":"耶和华审判的日子","verses":[{"n":1,"t":"当亚们的儿子犹大王约西亚在位的时候，耶和华的话临到希西家的玄孙，亚玛利雅的曾孙，基大利的孙子，古示的儿子西番雅。","notes":[]},{"n":2,"t":"耶和华说：“我必从地面上彻底除灭万物。","notes":[]},{"n":3,"t":"我必除灭人与牲畜，除灭空中的鸟、海里的鱼、绊脚石和恶人；我必把人从地面上剪除，这是耶和华说的。","notes":[]},{"n":4,"t":"我必伸手攻击犹大和耶路撒冷所有的居民；从这地方剪除剩下的巴力、事奉偶像之祭司的名字与祭司；","notes":[]},{"n":5,"t":"还有那些在屋顶拜天上万象的，那些敬拜耶和华指着他起誓，却又指着米勒公起誓的；","notes":["“米勒公”是根据七十士译本和其他古译本，亚扪人神明的名字，又名“摩洛”；原文是“他们的王”，音译“玛勒堪”。"]},{"n":6,"t":"并那些转去不跟从耶和华，不寻求耶和华，也不求问他的。”","notes":[]},{"n":7,"t":"在主耶和华面前要静默无声，因为耶和华的日子快到了。耶和华已经预备祭物，将召来的人分别为圣。","notes":[]},{"n":8,"t":"“到了献祭给耶和华的日子，我要惩罚领袖和王子，及所有穿外邦衣服的人。","notes":[]},{"n":9,"t":"到那日，我必惩罚所有跳过门槛，以残暴和诡诈塞满主人房屋的人。","notes":[]},{"n":10,"t":"“当那日，从鱼门必发出悲哀的声音，从第二城区发出哀号的声音，从山间发出破裂的大响声。这是耶和华说的。","notes":[]},{"n":11,"t":"玛革提施的居民哪，你们要哀号，因为所有的商人都灭亡了，满载银子的人都被剪除。","notes":["“商人”或译“迦南人”。"]},{"n":12,"t":"那时，我必用灯巡查耶路撒冷，惩罚那些沉湎在酒渣上的人；他们心里说：‘耶和华必不降福，也不降祸。’","notes":[]},{"n":13,"t":"他们的财宝成为掠物，房屋变为废墟。他们建造房屋，却不得住在其内；栽葡萄园，却不得喝其中所出的酒。”","notes":[]},{"n":14,"t":"耶和华的大日临近，临近而且甚快；那是耶和华日子的风声，勇士必在那里痛痛地哭号。","notes":[]},{"n":15,"t":"那日是愤怒的日子，急难困苦的日子，荒废凄凉的日子，黑暗幽冥的日子，乌云密布的日子，","notes":[]},{"n":16,"t":"是吹角呐喊的日子，要攻击坚固的城，攻击高大的城楼。","notes":[]},{"n":17,"t":"我必使灾祸临到人身上，使他们行走如同盲人，因为他们得罪了耶和华；他们的血必倒出如灰尘，肉身抛弃如粪土。","notes":[]},{"n":18,"t":"当耶和华发怒的日子，他们的金银不能救自己；耶和华妒忌的火必烧灭全地，要向地上所有的居民施行可怕的毁灭。","notes":[]}]},"2":{"heading":"呼吁百姓悔改","verses":[{"n":1,"t":"不知羞耻的国民哪，趁命令尚未发出，日子流逝如糠秕，耶和华的烈怒尚未临到你们，他发怒的日子未到以先，你们应当聚集，聚集起来。","notes":[],"end":2},{"n":3,"t":"世上遵守耶和华典章的谦卑人哪，你们都当寻求耶和华，寻求公义，寻求谦卑；或许在耶和华发怒的日子得以隐藏。","notes":[]},{"n":4,"t":"迦萨必遭遗弃，亚实基伦必然荒凉；亚实突人必在正午被赶出，以革伦也要连根拔除。","notes":["“遗弃”与“迦萨”的希伯来话发音相近。","“连根拔除”与“以革伦”的希伯来话发音相近。"],"heads":["以色列邻国的结局"]},{"n":5,"t":"祸哉，住沿海之地的基利提人！迦南、非利士人之地啊，耶和华的话攻击你们：我必毁灭你，以致无人居住。","notes":[]},{"n":6,"t":"沿海之地要变为草场，牧人的住处和羊群的圈。","notes":["“住处”或译“井”或“牧场”。"]},{"n":7,"t":"这地必为犹大家的余民所得；他们要在那里放牧，晚上躺卧在亚实基伦的房屋中；因为耶和华－他们的神必眷顾他们，使被掳的人归回。","notes":[]},{"n":8,"t":"我听见摩押毁谤，亚扪人辱骂；他们辱骂我的百姓，自夸自大，侵犯他们的疆土。”","notes":[]},{"n":9,"t":"万军之耶和华－以色列的神说：因此，我指着我的永生起誓：摩押必如所多玛，亚扪人必像蛾摩拉，都变为刺草、盐坑、永远荒废之地。我百姓中剩余的必掳掠他们，我国中的幸存者必得他们的地。","notes":[]},{"n":10,"t":"这事临到他们是因他们的骄傲，他们自夸自大，辱骂万军之耶和华的百姓。","notes":[]},{"n":11,"t":"耶和华必向他们显为可畏，因他使地上的众神衰微；列国的海岛各在自己的地方敬拜他。","notes":[]},{"n":12,"t":"你们古实人，也是被我的刀所杀的。","notes":["“古实”包括苏丹的大部分和埃塞俄比亚的一部分。"]},{"n":13,"t":"耶和华要伸手攻击北方，毁灭亚述，使尼尼微荒凉，干旱如同旷野。","notes":[]},{"n":14,"t":"群畜，就是各类的走兽必卧在其中，鹈鹕和豪猪要宿在柱顶；窗户有鸣叫的声音，门槛毁坏，他要毁坏香柏木板。","notes":["“类”：原文是“国”。","“门槛毁坏”：七十士译本是“乌鸦在门槛”。","“他要毁坏香柏木板”：原文另译“香柏木板显露”。"]},{"n":15,"t":"这素来欢乐、安然居住的城，心里说：“惟有我，除我以外再没有别的”，现在竟然荒凉，成为野兽躺卧之处！凡经过的人都必摇着手嗤笑它。","notes":[]}]},"3":{"heading":"耶路撒冷的罪恶和救赎","verses":[{"n":1,"t":"祸哉，这欺压的城！悖逆，污秽，","notes":[]},{"n":2,"t":"不听从命令，不领受训诲，不倚靠耶和华，不亲近它的神。","notes":[]},{"n":3,"t":"其中的领袖是咆哮的狮子，审判官是晚上的野狼，不留一点到早晨。","notes":["“晚上”：七十士译本是“阿拉伯”。"]},{"n":4,"t":"它的先知是虚浮诡诈的人，祭司亵渎圣所，强解律法。","notes":[]},{"n":5,"t":"耶和华在它中间是公义的，断不做非义的事，每早晨显明他的公义，无日不然；只是不义的人不知羞耻。","notes":[]},{"n":6,"t":"“我已经除灭列国，使他们的城楼荒废。我使他们街道荒凉，无人经过；他们的城镇毁坏，没有人，没有居民。","notes":[]},{"n":7,"t":"我说：‘只要你敬畏我，领受训诲；其住处就不会照我原先所定的被剪除。’然而，他们从早起来就在各样事上败坏自己。","notes":["“其住处...被剪除”：七十士译本是“你们就不会从它眼中被剪除，我要彻底地报复它”。"]},{"n":8,"t":"“你们要等候我，直到我兴起掳掠的日子；因为我已定意招聚列邦，聚集列国，将我的恼怒，我一切的烈怒，都倾倒在它们身上。我妒忌的火必烧灭全地。这是耶和华说的。","notes":["“掳掠”：七十士译本和其他古译本是“作证”。"]},{"n":9,"t":"“那时，我要改变万民，使他们有清洁的嘴唇，好求告耶和华的名，同心合意事奉我。","notes":[]},{"n":10,"t":"那些向我祈求的，我所分散的子民，必从古实河的那一边，献供物给我。","notes":["“子民”：原文是“女儿”。"]},{"n":11,"t":"“当那日，你必不再因一切得罪我的事蒙羞，因为那时我必从你中间除掉狂喜高傲的人，在我的圣山上你也不再狂傲。","notes":[]},{"n":12,"t":"我却要在你中间留下困苦贫寒的百姓，他们必投靠耶和华的名。","notes":[]},{"n":13,"t":"以色列的余民必不行恶，不说谎，口中没有诡诈的舌头；他们吃喝躺卧，无人使他们惊吓。”","notes":[]},{"n":14,"t":"锡安哪，应当歌唱！以色列啊，应当欢呼！耶路撒冷啊，应当满心欢喜快乐！","notes":["“锡安”：原文直译“锡安女子”。","“耶路撒冷”：原文是“耶路撒冷女子”。"],"heads":["欢乐之歌"]},{"n":15,"t":"耶和华已经免去对你的审判，赶出你的仇敌。以色列的王－耶和华在你中间；你必不再惧怕灾祸。","notes":[]},{"n":16,"t":"当那日，必有话对耶路撒冷说：“不要惧怕！锡安哪，不要手软！","notes":[]},{"n":17,"t":"耶和华－你的神在你中间大有能力，施行拯救。他必因你欢欣喜乐，他在爱中静默，且因你而喜乐欢呼。","notes":[]},{"n":18,"t":"我要聚集那些因无节期而愁烦的人，他们曾远离你，是你的重担和羞辱。","notes":["“是你的…羞辱”：原文是“是它的重担和羞辱”；七十士译本是“哀哉，谁使它受到羞辱”。"]},{"n":19,"t":"那时，看哪，我必对付所有苦待你的人，拯救瘸腿的，召集被赶出的；那些在全地受羞辱的，我必使他们得称赞，享名声。","notes":[]},{"n":20,"t":"那时，我必领你们回来，召集你们；我使你们被掳之人归回的时候，必使你们在地上的万民中享名声，得称赞；这是耶和华说的。”","notes":[]}]}},"HAG":{"1":{"heading":"耶和华命令重建圣殿","verses":[{"n":1,"t":"大流士王第二年六月初一，耶和华的话藉哈该先知向撒拉铁的儿子犹大省长所罗巴伯和约撒答的儿子约书亚大祭司传讲，说：","notes":[]},{"n":2,"t":"“万军之耶和华如此说，这百姓说，建造耶和华殿的时候还没有到。”","notes":["“建造...还没有到”：原文另译“现在还没有到建造耶和华殿的时候”。"]},{"n":3,"t":"耶和华的话藉哈该先知传讲，说：","notes":[]},{"n":4,"t":"“这殿荒凉，你们自己还住天花板的房屋吗？","notes":[]},{"n":5,"t":"现在，万军之耶和华如此说，你们要省察自己的行为。","notes":[]},{"n":6,"t":"你们撒的种多，收的却少；你们吃，却不得饱；喝，却不得足；穿衣服，却不得暖；领工钱的，领了工钱却装入有破洞的袋中。","notes":[]},{"n":7,"t":"“万军之耶和华如此说，你们要省察自己的行为。","notes":[]},{"n":8,"t":"你们要上山取木料，建造这殿，我就因此喜乐，且得荣耀。这是耶和华说的。","notes":[]},{"n":9,"t":"你们盼望多得，看哪，所得的却少；你们收到家中，我就吹去。这是为什么呢？因为我的殿荒凉，你们各人却只为自己的房屋奔走。这是万军之耶和华说的。","notes":[]},{"n":10,"t":"所以，因你们的缘故，天不降甘露，地也不出土产。","notes":["七十士译本没有“因你们的缘故”。"]},{"n":11,"t":"我命令干旱临到土地、山冈、五谷、新酒、新油和地上的出产，也临到人和牲畜，以及一切人手劳碌得来的。”","notes":[]},{"n":12,"t":"那时，撒拉铁的儿子所罗巴伯、约撒答的儿子约书亚大祭司，和所有幸存的百姓都听从耶和华－他们神的话，就是哈该先知奉耶和华他们神差遣所说的话；百姓在耶和华面前存敬畏的心。","notes":[],"heads":["百姓顺从耶和华的命令"]},{"n":13,"t":"耶和华的使者哈该奉耶和华差遣对百姓说：“我与你们同在。这是耶和华说的。”","notes":[]},{"n":14,"t":"耶和华激发撒拉铁的儿子犹大省长所罗巴伯、约撒答的儿子约书亚大祭司，和所有幸存百姓的心，他们就来为万军之耶和华－他们神的殿做工。","notes":[]},{"n":15,"t":"这是在大流士王第二年六月二十四日。","notes":[]}]},"2":{"heading":"新殿的荣耀","verses":[{"n":1,"t":"七月二十一日，耶和华的话藉哈该先知传讲，说：","notes":[]},{"n":2,"t":"“你要晓谕撒拉铁的儿子犹大省长所罗巴伯、约撒答的儿子约书亚大祭司，和所有幸存的百姓，说：","notes":[]},{"n":3,"t":"‘你们中间存留的，有谁见过这殿从前的荣耀呢？现在你们看如何？在你们眼中岂不是如同无有吗？","notes":[]},{"n":4,"t":"所罗巴伯啊，现在，你当刚强！这是耶和华说的。约撒答的儿子约书亚大祭司啊，你当刚强！这是耶和华说的。这地的百姓啊，你们都当刚强做工，因为我与你们同在。这是万军之耶和华说的。","notes":[]},{"n":5,"t":"这是照着你们出埃及时我与你们立约的话。我的灵仍要住在你们中间，你们不必惧怕。","notes":[]},{"n":6,"t":"万军之耶和华如此说：过些时候，我必再一次震动天地、沧海与干地。","notes":[]},{"n":7,"t":"我必震动万国，万国的珍宝都必运来，我就使这殿充满荣耀。这是万军之耶和华说的。","notes":["“万国...必运来”或译“万国所羡慕的必来到”。"]},{"n":8,"t":"银子是我的，金子也是我的。这是万军之耶和华说的。","notes":[]},{"n":9,"t":"这后来的殿的荣耀必大过先前的荣耀。这是万军之耶和华说的。在这地方我必赐平安。这是万军之耶和华说的。’”","notes":[]},{"n":10,"t":"大流士王第二年九月二十四日，耶和华的话临到哈该先知，说：","notes":[],"heads":["先知向祭司请教"]},{"n":11,"t":"“万军之耶和华如此说，你要向祭司请教律法，说：","notes":[]},{"n":12,"t":"‘看哪，若有人用衣服的边兜圣肉，这衣服的边接触了饼，或汤，或酒，或油，或别的食物，这些是否成为圣呢？’”祭司回答说：“不。”","notes":[]},{"n":13,"t":"哈该又说：“若有人因摸尸体染了不洁净，然后接触任何东西，这东西就变为不洁净吗？”祭司回答说：“必不洁净。”","notes":[]},{"n":14,"t":"于是哈该说：“耶和华说，在我面前这民如此，这国也是如此；他们手里的各样工作都是如此；他们在那里所献的都不洁净。”","notes":[]},{"n":15,"t":"“现在，你们心里要想一想，从今日起，耶和华的殿还没有一块石头放在石头上的情况。","notes":[],"heads":["耶和华应许赐福"]},{"n":16,"t":"那时你们怎么了？有人来到二十斗的谷堆那里，却只得了十斗；有人来到酒池那里要取五十桶，却只得了二十桶。","notes":["“你们怎么了？”是根据七十士译本，原文是“自从你们这么样”。"]},{"n":17,"t":"我以焚风、霉烂、冰雹攻击你们，和你们手上的各样工作，你们仍不归向我。这是耶和华说的。","notes":["“焚风”或译“虫害”。"]},{"n":18,"t":"你们心里要想一想，从今日起，就是从这九月二十四日起，从立耶和华殿根基的日子起，你们心里想一想：","notes":[]},{"n":19,"t":"仓里还有谷种吗？葡萄树、无花果树、石榴树、橄榄树虽没有结果子，从今日起，我必赐福。”","notes":["“葡萄树...果子，”七十士译本是“葡萄树、无花果树、石榴树、橄榄树都还没有结果子吗？”"]},{"n":20,"t":"这月二十四日，耶和华的话再次临到哈该，说：","notes":[],"heads":["耶和华给所罗巴伯的应许"]},{"n":21,"t":"“你要告诉犹大省长所罗巴伯说，我必震动天地，","notes":[]},{"n":22,"t":"倾覆列国的宝座，除灭列邦列国的势力，并倾覆战车和坐在其上的。马和骑兵都必跌倒，各人被弟兄的刀所杀。","notes":[]},{"n":23,"t":"万军之耶和华说：撒拉铁的儿子我仆人所罗巴伯啊，这是耶和华说的，到那日，我必以你为印，因我拣选了你。这是万军之耶和华说的。”","notes":[]}]}},"ZEC":{"1":{"heading":"耶和华呼唤子民归向他","verses":[{"n":1,"t":"大流士王第二年八月，耶和华的话临到易多的孙子，比利家的儿子撒迦利亚先知，说：","notes":[]},{"n":2,"t":"“耶和华曾向你们祖先大发烈怒。","notes":[]},{"n":3,"t":"你要对以色列人说，万军之耶和华如此说：你们要转向我，这是万军之耶和华说的，我就转向你们，这是万军之耶和华说的。","notes":[]},{"n":4,"t":"不要效法你们的祖先。从前的先知呼叫他们说：‘万军之耶和华如此说，当回转离开你们的恶道恶行。’他们却不听，也不顺从我。这是耶和华说的。","notes":[]},{"n":5,"t":"你们的祖先在哪里呢？那些先知能永远存活吗？","notes":[]},{"n":6,"t":"然而我的言语和律例，就是我所吩咐我仆人众先知的，岂不临到你们的祖先吗？他们就回转，说：万军之耶和华定意按我们的所作所为对待我们，他也已经照样行了。”","notes":[]},{"n":7,"t":"大流士第二年十一月，就是细罢特月二十四日，耶和华的话临到易多的孙子，比利家的儿子撒迦利亚先知，说：","notes":[],"heads":["马的异象"]},{"n":8,"t":"“我夜间观看，看哪，有一人骑着红马，站在洼地的番石榴树中间。在他身后有红色、褐色和白色的马。”","notes":[]},{"n":9,"t":"我说：“主啊，这是什么意思？”与我说话的天使说：“我要指示你这是什么意思。”","notes":[]},{"n":10,"t":"那站在番石榴树中间的人回答说：“这是奉耶和华差遣，在遍地巡逻的。”","notes":[]},{"n":11,"t":"他们对站在番石榴树中间耶和华的使者说：“我们在遍地巡逻，看哪，全地都安息平静。”","notes":[]},{"n":12,"t":"于是，耶和华的使者说：“万军之耶和华啊，你恼恨耶路撒冷和犹大的城镇已经七十年了，你不施怜悯要到几时呢？”","notes":[]},{"n":13,"t":"耶和华就用美善的话和安慰的话回答那与我说话的天使。","notes":[]},{"n":14,"t":"与我说话的天使对我说：“你要宣告，万军之耶和华如此说：我为耶路撒冷而妒忌，为锡安大大妒忌。","notes":[]},{"n":15,"t":"我非常恼怒那享安逸的列国，因我从前稍微恼怒，他们就越发加害。","notes":[]},{"n":16,"t":"所以耶和华如此说：现在我回到耶路撒冷，仍要施怜悯，我的殿要重建在其中，准绳必拉在耶路撒冷之上。这是万军之耶和华说的。","notes":[]},{"n":17,"t":"你要再宣告，万军之耶和华如此说：我的城镇要再度繁荣发达。耶和华必再安慰锡安，拣选耶路撒冷。”","notes":[]},{"n":18,"t":"我举目观看，看哪，有四只角。","notes":[],"heads":["角的异象"]},{"n":19,"t":"我问那与我说话的天使：“这是什么意思？”他对我说：“这是击散犹大、以色列和耶路撒冷的角。”","notes":[]},{"n":20,"t":"耶和华又把四个匠人指给我看。","notes":[]},{"n":21,"t":"我问：“这些人来做什么呢？”他说：“那是击散犹大的角，使人不敢抬头；但这些匠人前来威吓列国，打掉列国的角，因为他们举起角来击散犹大地。”","notes":[]}]},"2":{"heading":"丈量绳的异象","verses":[{"n":1,"t":"我举目观看，看哪，有一人手拿丈量的绳。","notes":[]},{"n":2,"t":"我问：“你到哪里去？”他对我说：“要去丈量耶路撒冷，看有多宽多长。”","notes":[]},{"n":3,"t":"看哪，与我说话的天使出去，另有一位天使迎着他来，","notes":["“出去”：七十士译本是“站着”。"]},{"n":4,"t":"对他说：“你跑去告诉这个年轻人说，耶路撒冷必有人居住，如同无城墙的乡村，因为其中的人和牲畜很多。","notes":[]},{"n":5,"t":"耶和华说：‘我要作耶路撒冷四围火的城墙，并要作城中的荣耀。’”","notes":[]},{"n":6,"t":"耶和华说：“来，来！你们要从北方之地逃回；因我曾把你们分散到天的四方。这是耶和华说的。”","notes":["“到天的四方”：原文是“犹如天的四风”。"],"heads":["呼唤被掳者归回"]},{"n":7,"t":"来！住巴比伦的锡安百姓啊，逃吧！","notes":["“巴比伦”：原文直译“巴比伦女子”。"]},{"n":8,"t":"万军之耶和华在显出荣耀之后，差遣我到掳掠你们的列国那里，他如此说：“碰你们的就是碰他自己眼中的瞳人。","notes":["“他自己”：原文另译“我”。"]},{"n":9,"t":"看哪，我要挥手攻击他们，他们就必作自己奴仆的掳物。”你们就知道万军之耶和华差遣了我。","notes":[]},{"n":10,"t":"耶和华说：“锡安哪，应当欢乐歌唱，因为，看哪，我要来，要住在你中间。","notes":["“锡安”：原文直译“锡安女子”。"]},{"n":11,"t":"在那日，必有许多国家归附耶和华，作我的子民。我要住在你中间。”你就知道万军之耶和华差遣我到你那里去。","notes":["“我要住”：原文另译“他要住”；七十士译本是“他们要住”。"]},{"n":12,"t":"耶和华必收回犹大，作为他圣地的产业，他必再度拣选耶路撒冷。","notes":[]},{"n":13,"t":"凡血肉之躯都当在耶和华面前静默无声，因为他从他的圣所奋起了。","notes":[]}]},"3":{"heading":"大祭司的异象","verses":[{"n":1,"t":"天使指给我看：约书亚大祭司站在耶和华的使者面前，撒但站在约书亚的右边控告他。","notes":["“天使”：原文是“他”。"]},{"n":2,"t":"耶和华向撒但说：“撒但哪，耶和华责备你！拣选耶路撒冷的耶和华责备你！这不是从火中抽出来的一根柴吗？”","notes":[]},{"n":3,"t":"约书亚穿着污秽的衣服，站在那使者面前。","notes":[]},{"n":4,"t":"使者吩咐那些侍立在他面前的说：“脱去他污秽的衣服。”又对约书亚说：“你看，我使你的罪孽离开你，要给你穿上华美的衣服。”","notes":[]},{"n":5,"t":"我说：“要将洁净的冠冕戴在他头上。”他们就把洁净的冠冕戴在他头上，给他穿上华美的衣服，耶和华的使者在旁边站立。","notes":["“我说”：原文另译“他说”；七十士译本没有“我说”。"]},{"n":6,"t":"耶和华的使者告诫约书亚说，","notes":[]},{"n":7,"t":"万军之耶和华如此说：“你若遵行我的道，谨守我的命令，就可以管理我的家，看守我的院宇；我也要使你在这些侍立的人中间来往。","notes":[]},{"n":8,"t":"约书亚大祭司啊，你和坐在你面前的同伴都当听，因为他们是作预兆的：看哪，我必使我仆人大卫的苗裔长出。","notes":["“大卫的苗裔”：原文是“苗裔”。"]},{"n":9,"t":"看哪，这是我在约书亚面前所立的石头，这一块石头上有七眼。看哪，我要亲自雕刻这石头，并在一日之间除掉这地的罪孽。这是万军之耶和华说的。","notes":[]},{"n":10,"t":"在那日，你们各人要请邻舍坐在葡萄树和无花果树下。这是万军之耶和华说的。”","notes":[]}]},"4":{"heading":"金灯台的异象","verses":[{"n":1,"t":"那与我说话的天使又来叫醒我，好像人睡觉时被唤醒一样。","notes":[]},{"n":2,"t":"他问我：“你看见什么？”我说：“我看见了，看哪，有一个纯金的灯台，顶上有灯座，其上有七盏灯，每盏灯的上头有七根管子；","notes":[]},{"n":3,"t":"旁边有两棵橄榄树，一棵在灯座的右边，一棵在灯座的左边。”","notes":[]},{"n":4,"t":"我问与我说话的天使说：“主啊，这是什么意思？”","notes":[]},{"n":5,"t":"与我说话的天使回答，对我说：“你不知道这是什么意思吗？”我说：“主啊，我不知道。”","notes":[]},{"n":6,"t":"他回答我说：“这是耶和华指示所罗巴伯的话。万军之耶和华说：不是倚靠势力，不是倚靠才能，乃是倚靠我的灵方能成事。","notes":["原文没有“方能成事”。"],"heads":["神给所罗巴伯的应许"]},{"n":7,"t":"大山哪，你算什么呢？在所罗巴伯面前，你必夷为平地。他安放顶上的那块石头，人就欢呼：‘愿恩惠、恩惠归与这殿！’”","notes":[]},{"n":8,"t":"耶和华的话临到我，说：","notes":[]},{"n":9,"t":"“所罗巴伯的手立了这殿的根基，他的手也必完成这工，你就知道万军之耶和华差遣我到你们这里。","notes":[]},{"n":10,"t":"谁藐视这日的事为小呢？他们见所罗巴伯手拿石垂线就欢喜。这七盏灯是耶和华的眼睛，遍察全地。”","notes":["“七盏灯”：原文是“七”。"]},{"n":11,"t":"我问天使说：“那么在灯台左右的这两棵橄榄树是什么意思呢？”","notes":[]},{"n":12,"t":"我再次问他：“这两根橄榄树枝在两根流出金色油的金嘴旁边，是什么意思呢？”","notes":[]},{"n":13,"t":"他对我说：“你不知道这是什么意思吗？”我说：“主啊，我不知道。”","notes":[]},{"n":14,"t":"他说：“这是两位受膏者，侍立在全地之主的旁边。”","notes":[]}]},"5":{"heading":"飞卷的异象","verses":[{"n":1,"t":"我又举目观看，看哪，有一飞行的书卷。","notes":[]},{"n":2,"t":"他问我：“你看见什么？”我回答：“我看见一飞行的书卷，长二十肘，宽十肘。”","notes":[]},{"n":3,"t":"他对我说：“这就是向全地面发出的诅咒。凡偷窃的必按书卷这面的话除灭，凡起假誓的必按书卷那面的话除灭。","notes":[]},{"n":4,"t":"万军之耶和华说：我要把这书卷送出去，进入偷窃者的家和指着我名起假誓者的家，停留在他家里，连房屋带木头和石头都毁灭了。”","notes":[]},{"n":5,"t":"与我说话的天使前来，对我说：“你要举目观看，看那出现的是什么。”","notes":[],"heads":["量器中妇人的异象"]},{"n":6,"t":"我问：“这是什么呢？”他说：“这出现的是量器。”又说：“是他们的眼目，遍行全地。”","notes":["“量器”：原文是“伊法”；下同。","“他们的眼目，遍行全地”：七十士译本和其他古译本是“他们在遍地的恶行”。"]},{"n":7,"t":"看哪，圆形的铅盖被抬起来，有一个妇人坐在量器中。","notes":[]},{"n":8,"t":"天使说：“这是罪恶。”他就把妇人推进量器里，把铅盖压在量器的口上。","notes":[]},{"n":9,"t":"于是我举目观看，看哪，有两个妇人前来，她们的翅膀中有风，翅膀如同鹳鸟的翅膀。她们把量器抬起来，悬在天地之间。","notes":[]},{"n":10,"t":"我问那与我说话的天使：“她们要把量器抬到哪里去呢？”","notes":[]},{"n":11,"t":"他对我说：“要抬到示拿地去，为它建造房屋；等预备妥当，就把它安放在自己的台座上。”","notes":[]}]},"6":{"heading":"马车的异象","verses":[{"n":1,"t":"我又举目观看，看哪，有四辆马车从两座山的中间出来；那两座山是铜山。","notes":[]},{"n":2,"t":"第一辆车套着红马，第二辆车套着黑马，","notes":[]},{"n":3,"t":"第三辆车套着白马，第四辆车套着带斑点的马，都是强壮的。","notes":["“带斑点...强壮的”或译“带斑点的灰马”。"]},{"n":4,"t":"我就回应与我说话的天使说：“主啊，这是什么意思？”","notes":[]},{"n":5,"t":"天使回答，对我说：“这是天的四风，是从全地之主面前出来的。”","notes":[]},{"n":6,"t":"套着黑马的车往北方之地去，白马跟随在后；有斑点的马往南方之地去；","notes":[]},{"n":7,"t":"那些壮马出来，急着要在地上巡逻。天使说：“你们只管在地上巡逻。”它们就在地上巡逻。","notes":[]},{"n":8,"t":"他又呼叫我，告诉我说：“你看，往北方地去的已在北方之地使我放心。”","notes":[]},{"n":9,"t":"耶和华的话临到我，说：","notes":[],"heads":["为约书亚加冕"]},{"n":10,"t":"“你要拿从巴比伦归来的被掳之人黑玳、多比雅、耶大雅所献的，当日就要进到西番雅的儿子约西亚的家里，","notes":[]},{"n":11,"t":"拿这金银做冠冕，戴在约撒答的儿子约书亚大祭司的头上；","notes":[]},{"n":12,"t":"对他说，万军之耶和华如此说：‘看哪，那名称为大卫苗裔的，要在本处生长，并要建造耶和华的殿。","notes":[]},{"n":13,"t":"就是他，要建造耶和华的殿，他要承受尊荣，坐在位上掌王权；又有一位祭司坐在自己的位上，两职之间筹划和平。","notes":[]},{"n":14,"t":"这冠冕要归希连、多比雅、耶大雅，和西番雅的儿子贤，放在耶和华的殿里作为纪念。’”","notes":["“希连”就是“黑玳”。","“贤”就是“约西亚”。"]},{"n":15,"t":"远方的人要来建造耶和华的殿，你们因此就知道，万军之耶和华差遣我到你们这里来。你们若留意听从耶和华－你们神的话，这事必然成就。","notes":[]}]},"7":{"heading":"谴责不诚恳的禁食","verses":[{"n":1,"t":"大流士王第四年九月，就是基斯流月初四，耶和华的话临到撒迦利亚。","notes":[]},{"n":2,"t":"那时伯特利人已经差遣沙利色和利坚．米勒，并他们的人，去恳求耶和华的恩，","notes":["“利坚．米勒”：原文另译“国王的重臣”。"]},{"n":3,"t":"问万军之耶和华殿中的祭司，又问先知：“我当如历年以来所行，在五月哭泣斋戒吗？”","notes":[]},{"n":4,"t":"万军之耶和华的话临到我，说：","notes":[]},{"n":5,"t":"“你要向这地全体百姓和祭司说：‘你们这七十年来，在五月、七月禁食悲哀，岂是真的向我禁食吗？","notes":[]},{"n":6,"t":"你们吃喝，不是为自己吃，为自己喝吗？","notes":[]},{"n":7,"t":"当耶路撒冷和四围的城镇有人居住，享繁荣，尼革夫和谢非拉也有人居住的时候，耶和华藉从前的先知所宣告的，你们不当听吗？’”","notes":["“尼革夫”是音译，意思是“旷野干旱的地方”，指“南方之地”。","“谢非拉”是音译，意思是“低地”。"]},{"n":8,"t":"耶和华的话临到撒迦利亚，说：","notes":[],"heads":["被掳的原因"]},{"n":9,"t":"“万军之耶和华如此说：你们要按真正的公平来审判，彼此以慈爱怜悯相待。","notes":[]},{"n":10,"t":"不可欺压寡妇、孤儿、寄居的和困苦的人。谁都不可心里谋害弟兄。","notes":[]},{"n":11,"t":"他们却不留意；耸肩悖逆，耳朵发沉，不肯听从。","notes":[]},{"n":12,"t":"他们的心坚硬如金刚石，不听律法和万军之耶和华藉着他的灵差遣从前先知所说的话。因此，万军之耶和华大发烈怒。","notes":[]},{"n":13,"t":"万军之耶和华说：我曾呼唤他们，他们不听；将来他们呼求我，我也不听！","notes":[]},{"n":14,"t":"我必以旋风将他们吹散到素不认识的万国中。他们离开以后，地就荒凉，无人来往经过；他们使美好之地荒凉了。”","notes":[]}]},"8":{"heading":"耶和华应许复兴耶路撒冷","verses":[{"n":1,"t":"万军之耶和华的话临到我，说：","notes":[]},{"n":2,"t":"“万军之耶和华如此说：我为锡安而妒忌，大大妒忌；我为了它妒忌而大发烈怒。","notes":[]},{"n":3,"t":"耶和华如此说：我要回到锡安，住在耶路撒冷中间。耶路撒冷必称为忠实的城，万军之耶和华的山必称为圣山。","notes":[]},{"n":4,"t":"万军之耶和华如此说：将来必有年老的男女坐在耶路撒冷的广场上，各人因年纪老迈而手拿枴杖。","notes":[]},{"n":5,"t":"城里的广场满有男孩女孩在玩耍。","notes":[]},{"n":6,"t":"万军之耶和华如此说：在那些日子，即使这事在这余民眼中看为奇妙，难道在我眼中也看为奇妙吗？这是万军之耶和华说的。","notes":[]},{"n":7,"t":"万军之耶和华如此说：看哪，我要从日出之地、从日落之地拯救我的子民。","notes":[]},{"n":8,"t":"我要领他们来，使他们住在耶路撒冷中间。他们要作我的子民，我要作他们的神，都凭信实和公义。","notes":[]},{"n":9,"t":"“万军之耶和华如此说：你们的手要坚强；这些日子，你们已听见先知的口，在万军之耶和华殿的根基立定、圣殿建造的日子所说的这些话。","notes":[]},{"n":10,"t":"那些日子以前，人得不着工价，牲畜也无人雇用；且因敌人的缘故，出入不得平安；因我使人与人互相攻击。","notes":[]},{"n":11,"t":"但如今，我对这余民必不像先前的日子。这是万军之耶和华说的。","notes":[]},{"n":12,"t":"因为他们要平安撒种，葡萄树要结果子，土地必有出产，天也必降甘露。我要使这余民享受这一切。","notes":[]},{"n":13,"t":"犹大家和以色列家啊，你们从前在列国中怎样成为可诅咒的；照样，我要拯救你们，使你们得福。不要惧怕，你们的手要坚强。","notes":["“使你们得福”或译“使你们叫人得福”。"]},{"n":14,"t":"“万军之耶和华如此说：你们祖先惹我发怒的时候，我怎样定意降祸，并不改变；万军之耶和华说，","notes":[]},{"n":15,"t":"这些日子我也定意施恩给耶路撒冷和犹大家；你们不要惧怕。","notes":[]},{"n":16,"t":"你们所当行的是这样：每个人要与邻舍说诚实话，在城门口要按真正的公平来审判，使人和睦。","notes":[]},{"n":17,"t":"谁都不可心里谋害邻舍，也不可喜爱起假誓，因为这些事都为我所恨恶。这是耶和华说的。”","notes":[]},{"n":18,"t":"万军之耶和华的话临到我，说：","notes":[]},{"n":19,"t":"“万军之耶和华如此说：四月的禁食、五月的禁食、七月的禁食和十月的禁食，必成为犹大家的欢喜和快乐，以及美好的节期；所以你们要喜爱诚实与和平。","notes":[]},{"n":20,"t":"“万军之耶和华如此说：将来还有众百姓和许多城镇的居民要来。","notes":[]},{"n":21,"t":"这城的居民必到那城，说：‘我们快去恳求耶和华的恩，寻求万军之耶和华；我自己也要去。’","notes":[]},{"n":22,"t":"必有许多民族和强盛的国家来到耶路撒冷寻求万军之耶和华，恳求耶和华的恩。","notes":[]},{"n":23,"t":"万军之耶和华如此说：在那些日子，列国中说各种语言的人，必有十个人强拉住一个犹大人衣服的边，说：‘我们要与你们同去，因为我们听见神与你们同在了。’”","notes":[]}]},"9":{"heading":"审判邻国","verses":[{"n":1,"t":"耶和华的默示，他的话临到哈得拉地、大马士革－因世人和以色列各支派的眼目都向着耶和华－","notes":[]},{"n":2,"t":"和邻近的哈马，以及推罗和西顿。因为它极有智慧，","notes":[]},{"n":3,"t":"推罗为自己建造坚固城，堆起银子如尘沙，纯金如街上的泥土。","notes":["“坚固城”与“推罗”的希伯来话发音相近。"]},{"n":4,"t":"看哪，主必赶出它，重创它海上的势力，它必被火吞灭。","notes":[]},{"n":5,"t":"亚实基伦看见必惧怕，迦萨看见甚痛苦，以革伦因失了盼望而蒙羞；迦萨必不再有君王，亚实基伦也不再有人居住，","notes":[]},{"n":6,"t":"混血的人要住在亚实突；我必除灭非利士人的骄傲。","notes":[]},{"n":7,"t":"我要除去他口中带血之肉和牙齿内可憎之物。他必作余民归于我们的神，在犹大像族长一样；以革伦必如耶布斯人。","notes":[]},{"n":8,"t":"我要扎营在我的家，敌军不得任意往来，暴虐的人也不再经过，因为我亲眼看顾。","notes":[]},{"n":9,"t":"锡安哪，应当大大喜乐；耶路撒冷啊，应当欢呼。看哪，你的王来到你这里！他是公义的，并且施行拯救，谦和地骑着驴，骑着小驴，驴的驹子。","notes":["“锡安”：原文直译“锡安女子”。","“耶路撒冷”：原文直译“耶路撒冷女子”。"],"heads":["未来的君王"]},{"n":10,"t":"我必除灭以法莲的战车和耶路撒冷的战马；战争的弓也必剪除。他要向列国讲和平；他的权柄必从这海管到那海，从大河管到地极。","notes":[]},{"n":11,"t":"锡安哪，我因与你立约的血，要从无水坑里释放你中间被囚的人。","notes":[],"heads":["神子民的复兴"]},{"n":12,"t":"被囚而有指望的人哪，要转回堡垒；我今日宣告，我必加倍补偿你。","notes":[]},{"n":13,"t":"我为自己把犹大弯紧，我使以法莲如满弓。锡安哪，我要唤起你的儿女，希腊啊，我要攻击你的儿女，使你如勇士的刀。","notes":["“希腊”：原文是“雅完”。"]},{"n":14,"t":"耶和华要显现在他们身上，他的箭要射出如闪电。主耶和华必吹角，乘南方的旋风而行。","notes":[]},{"n":15,"t":"万军之耶和华必保护他们；他们要吞灭，要践踏弹弓的石头；他们呐喊，狂饮如喝酒，如盛满的碗，又如坛的四角。","notes":["“他们要吞灭...石头”或译“弹弓的石头要吞灭和践踏”。","“他们呐喊，狂饮”：七十士译本的一些抄本是“他们饮血”。"]},{"n":16,"t":"当那日，耶和华－他们的神必看他的百姓如羊群，拯救他们；因为他们如冠冕上的宝石，在他的地上如旗帜高举。","notes":["“如旗帜高举”或译“发出光辉”。"]},{"n":17,"t":"他是何等善！他是何其美！五谷使少男强壮，新酒使少女健美。","notes":[]}]},"10":{"heading":"耶和华应许解救","verses":[{"n":1,"t":"春雨的季节，你们要向耶和华求雨。耶和华发出雷电，为众人降下大雨，把田园的菜蔬赐给人。","notes":[]},{"n":2,"t":"因为家中神像所言的是虚空，占卜者所见的是虚假，他们讲说假梦，徒然安慰人。所以众人如羊流离，因无牧人就受欺压。","notes":[]},{"n":3,"t":"我的怒气向牧人发作，我必惩罚那为首的；万军之耶和华眷顾他的羊群，就是犹大家，必使他们如战场上的骏马。","notes":["“为首的”或译“公山羊”。"]},{"n":4,"t":"房角石从他而出，橛子从他而出，战争的弓也从他而出，每一个掌权的都从他而出。","notes":[]},{"n":5,"t":"他们必如战场上的勇士，践踏仇敌如街上的泥土。他们必争战，因为耶和华与他们同在，他们必使骑马的羞愧。","notes":[]},{"n":6,"t":"我要坚固犹大家，拯救约瑟家，我要领他们归回，因我怜悯他们，他们必像我未曾弃绝他们一样；都因我是耶和华－他们的神，我必应允他们。","notes":[]},{"n":7,"t":"以法莲人必如勇士，他们心中畅快如同喝酒；他们的儿女看见就欢喜，他们的心必因耶和华喜乐。","notes":[]},{"n":8,"t":"我要呼叫，聚集他们，因我已经救赎他们。他们的人数必增添，如从前增添一样。","notes":[]},{"n":9,"t":"我要将他们分散在列国中，他们必在远方记得我；他们与儿女都必存活，他们要归回。","notes":[]},{"n":10,"t":"我必使他们从埃及地归回，从亚述召集他们，领他们到基列地和黎巴嫩；这些还不够他们居住。","notes":[]},{"n":11,"t":"耶和华必经过苦海，击打海浪。尼罗河的深处全都枯干，亚述的骄傲必降卑，埃及的权杖必除去。","notes":["“耶和华”：原文是“他”；七十士译本是“他们”。"]},{"n":12,"t":"我要使他们倚靠耶和华，得以坚固，他们必奉他的名而行；这是耶和华说的。","notes":["“他们必奉他的名而行”：七十士译本是“他们必荣耀他的名”。"]}]},"11":{"heading":"暴君的没落","verses":[{"n":1,"t":"黎巴嫩哪，敞开你的门，任火吞灭你的香柏树。","notes":[]},{"n":2,"t":"哀号吧，松树！因为香柏树倾倒了，高大的树毁坏了。哀号吧，巴珊的橡树！因为茂盛的树林倒下来了。","notes":[]},{"n":3,"t":"听啊，有牧人在哀号，因他们的荣华败落了；听啊，有少壮狮子咆哮，因约旦河旁的丛林荒废了。","notes":[]},{"n":4,"t":"耶和华－我的神如此说：“你要牧养这群将宰的羊。","notes":[],"heads":["两个牧人"]},{"n":5,"t":"买羊的宰了他们，却不认为自己有罪；卖他们的也说：‘耶和华是应当称颂的，因我富足了。’牧养他们的并不怜悯他们。","notes":[]},{"n":6,"t":"我不再怜悯这地的居民。看哪，我要将这些人交在各人的邻舍和君王手中；他们必毁灭这地，我却不救任何一个脱离他们的手。这是耶和华说的。”","notes":[]},{"n":7,"t":"于是，我牧养这群将宰的羊，就是羊群中最困苦的；我拿着两根杖，一根我称为“恩惠”，一根称为“联合”。这样，我就牧养这群羊。","notes":["“我牧养...最困苦的”：原文另译“我为了那些买卖羊群的人牧养这群将宰的羊”。","“恩惠”或译“荣美”；下同。"]},{"n":8,"t":"一个月之内，我废除了三个牧人，因为我的心厌烦他们，他们的心也憎恶我。","notes":[]},{"n":9,"t":"我就说：“我不牧养你们。要死的，由他死；灭亡的，由他灭亡；剩余的，由他们彼此吞食。”","notes":[]},{"n":10,"t":"我拿起那根称为“恩惠”的杖，折断它，表明我废弃与万民所立的约。","notes":[]},{"n":11,"t":"当日约就废了。因此，那些羊群中最困苦的，看着我，就知道这真是耶和华的话。","notes":["“那些羊群中最困苦的”：原文另译“那些买卖羊群的人”。"]},{"n":12,"t":"我对他们说：“你们若看为美，就给我工价。不然，就罢了！”于是他们秤了三十块银钱作为我的工价。","notes":[]},{"n":13,"t":"耶和华对我说：“把它丢给窑户。那是他们对我所估定的好价钱！”我就取这三十块银钱，在耶和华的殿中将它丢给窑户。","notes":[]},{"n":14,"t":"我又折断第二根杖，就是称为“联合”的那根杖，表明我废弃犹大与以色列弟兄间的情谊。","notes":[]},{"n":15,"t":"耶和华对我说：“你再把愚昧牧人所用的器具拿来，","notes":[]},{"n":16,"t":"因为，看哪，我要在这地立一个牧人；他不看顾将亡的，不寻找分散的，不医治受伤的，也不牧养强壮的；却要吞吃肥羊的肉，撕裂它们的蹄。","notes":[]},{"n":17,"t":"祸哉！无用的牧人丢弃羊群，刀必临到他的膀臂和右眼上；他的膀臂必全然枯干，他的右眼也必昏暗失明。”","notes":[]}]},"12":{"heading":"耶路撒冷将蒙拯救","verses":[{"n":1,"t":"耶和华的默示，他的话论到以色列。铺张诸天、建立地基、造人里面之灵的耶和华说：","notes":[]},{"n":2,"t":"“看哪，我要使耶路撒冷成为令四围列国百姓昏醉的杯；耶路撒冷被围困，犹大也一样受困。","notes":["“耶路撒冷被围困...受困”：有古译本是“犹大也去围困耶路撒冷”。"]},{"n":3,"t":"在那日，我要使耶路撒冷成为万民的一块沉重石头，凡举起它的必受重伤；地上的万国都聚集攻击它。","notes":[]},{"n":4,"t":"到那日，我必令一切的马匹惊惶，使骑马的癫狂。我必张开眼睛看顾犹大家，却使列国一切的马匹瞎眼。这是耶和华说的。","notes":[]},{"n":5,"t":"犹大的族长心里要说：‘耶路撒冷的居民因倚靠万军之耶和华－他们的神，就成为我的力量。’","notes":["“就成为我的力量”：原文另译“就有力量”。"]},{"n":6,"t":"“那日，我必使犹大的族长如柴堆中的火盆，又如禾捆里的火把；他们必左右吞灭四围列国的百姓。耶路撒冷却仍屹立在本处，仍在耶路撒冷！","notes":[]},{"n":7,"t":"“耶和华要先拯救犹大的帐棚，免得大卫家的荣耀和耶路撒冷居民的荣耀胜过犹大。","notes":[]},{"n":8,"t":"那日，耶和华必保护耶路撒冷的居民。他们中间软弱的在那日必如大卫；大卫家必如神，如行在他们前面的耶和华的使者。","notes":[]},{"n":9,"t":"那日，我必定意灭绝前来攻击耶路撒冷的万国。”","notes":[]},{"n":10,"t":"“我要将那施恩与恳求的灵，浇灌大卫家和耶路撒冷的居民。他们必仰望我，就是他们所扎的那位。他们必为他悲伤，如丧独子，又为他哀哭，如丧长子。","notes":[],"heads":["为所刺的哀伤"]},{"n":11,"t":"那日，在耶路撒冷必有大大的哀号，如米吉多平原上哈达．临门的哀号。","notes":[]},{"n":12,"t":"这地必哀哭：一家一家地哭，大卫家的家族聚在一处，他们的妇女聚在一处；拿单家的家族聚在一处，他们的妇女聚在一处。","notes":[]},{"n":13,"t":"利未家的家族聚在一处，他们的妇女聚在一处；示每家的家族聚在一处，他们的妇女聚在一处。","notes":[]},{"n":14,"t":"其余的各家，每一家的家族聚在一处，他们的妇女聚在一处。”","notes":[]}]},"13":{"heading":"牧人被杀","verses":[{"n":1,"t":"“在那日，因罪恶与污秽的缘故，必有一泉源为大卫家和耶路撒冷的居民而开。”","notes":[]},{"n":2,"t":"万军之耶和华说：“在那日，我要从地上除灭偶像的名，使它不再被记得；我也必使这地不再有先知，不再有污秽的灵。","notes":[]},{"n":3,"t":"若还有人说预言，生他的父母必对他说：‘你不得存活，因为你假借耶和华的名说谎话。’生他的父母在他说预言时，要将他刺死。","notes":[]},{"n":4,"t":"那日，凡作先知说预言的必因所论的异象羞愧，不再穿毛皮外袍哄骗人。","notes":[]},{"n":5,"t":"他要说：‘我不是先知，我是耕地的；我从幼年就作人的奴仆。’","notes":[]},{"n":6,"t":"有人对他说：‘你两手臂间是什么伤呢？’他说：‘这是我在亲友家中所受的伤。’”","notes":[]},{"n":7,"t":"万军之耶和华说：刀剑哪，兴起攻击我的牧人，攻击我的同伴吧！要击打牧人，羊就分散了；我必反手攻击那微小的。","notes":[]},{"n":8,"t":"这全地的人，三分之二将被剪除而死，三分之一仍必存留。这是耶和华说的。","notes":[]},{"n":9,"t":"我要使这三分之一经过火，熬炼他们，如熬炼银子；试炼他们，如试炼金子。他们要求告我的名，我必应允他们。我说：“这是我的子民。”他们要说：“耶和华是我的神。”","notes":[]}]},"14":{"heading":"耶路撒冷和列国","verses":[{"n":1,"t":"看哪，耶和华的日子临近了，你的财物必被抢掠，在你中间被瓜分。","notes":[]},{"n":2,"t":"我要招聚万国与耶路撒冷争战；城必被攻取，房屋被抢夺，妇女被玷污，城中的一半被掳去；但其余的百姓不会从城中被剪除。","notes":[]},{"n":3,"t":"那时，耶和华要出去与那些国家打仗，如同从前战争的日子打仗一样。","notes":[]},{"n":4,"t":"那日，他的脚必站在橄榄山上，这山面向耶路撒冷的东边。橄榄山必从中间裂开，自东至西成为极大的谷；山的一半向北挪移，一半向南挪移。","notes":[]},{"n":5,"t":"你们要从我的山谷中逃跑，因为山谷必延到亚萨。你们要逃跑，如在犹大王乌西雅年间逃避大地震一样。耶和华－我的神必降临，所有的圣者与你同来。","notes":["“你们要从...一样”：七十士译本是“我的山谷要被堵塞，因为山谷必延到亚萨，被堵塞，如在犹大王乌西雅年间大地震时堵塞一样”。","“与你”：七十士译本和其他古译本是“与他”。"]},{"n":6,"t":"在那日，必没有光，不会放晴，只有乌云。","notes":["“不会放晴，只有乌云”：原文另译“荣光被冻结了”；七十士译本是“只有寒冷与冰霜”。"]},{"n":7,"t":"耶和华所知的那一日，没有白天，没有黑夜，到了晚上仍有亮光。","notes":[]},{"n":8,"t":"在那日，必有活水从耶路撒冷出来，一半往东海流，一半往西海流；冬夏都是如此。","notes":[]},{"n":9,"t":"耶和华要作全地的王。那日，耶和华必为独一无二，他的名也是独一无二。","notes":[]},{"n":10,"t":"从迦巴直到耶路撒冷南方的临门，全地要变为旷野。耶路撒冷要矗立于本处，从便雅悯门到旧门，又到角门，并从哈楠业楼，直到王的酒池。","notes":[]},{"n":11,"t":"人要住在其中，不再有诅咒；耶路撒冷必安然屹立。","notes":[]},{"n":12,"t":"这是耶和华所降的灾殃，要攻击那些与耶路撒冷作战的万民；他们两脚站立时，肉要溃烂，眼在眶中溃烂，舌在口中也溃烂。","notes":[]},{"n":13,"t":"那日，耶和华必使他们大大混乱。他们彼此用手揪住，用手互相攻击。","notes":[]},{"n":14,"t":"犹大也要在耶路撒冷打仗。那时四围各国的财物，就是许许多多的金银和衣服，必被收聚。","notes":["“犹大...打仗”或译“甚至犹大也要攻打耶路撒冷”。"]},{"n":15,"t":"马匹、骡子、骆驼、驴和营中一切的牲畜所遭的灾殃与那灾殃一样。","notes":[]},{"n":16,"t":"上来攻击耶路撒冷的列国中所有剩下的人，要年年上来敬拜大君王－万军之耶和华，并守住棚节。","notes":[]},{"n":17,"t":"地上万族中，凡不上耶路撒冷敬拜大君王－万军之耶和华的，雨必不降在他们的地上。","notes":[]},{"n":18,"t":"埃及族若不上来，雨必不降在他们的地上；凡不上来守住棚节的列国，耶和华必用这灾攻击他们。","notes":[]},{"n":19,"t":"这就是埃及的惩罚和那些不上来守住棚节之列国的惩罚。","notes":[]},{"n":20,"t":"在那日，马的铃铛上要刻上“归耶和华为圣”。耶和华殿内的锅必如祭坛前的碗一样。","notes":[]},{"n":21,"t":"耶路撒冷和犹大一切的锅都必归万军之耶和华为圣。凡献祭的都必来取这锅，在其中煮肉。当那日，在万军之耶和华的殿中必不再有做买卖的人。","notes":["“做买卖的人”或译“迦南人”。"]}]}},"MAL":{"1":{"heading":"耶和华爱以色列","verses":[{"n":1,"t":"耶和华的话，藉玛拉基传给以色列的默示。","notes":[]},{"n":2,"t":"耶和华说：“我曾爱你们。”你们却说：“你在何事上爱我们呢？”耶和华说：“以扫不是雅各的哥哥吗？我却爱雅各，","notes":[]},{"n":3,"t":"恶以扫，使他的山岭荒凉，把他的地业交给旷野的野狗。”","notes":[]},{"n":4,"t":"以东若说：“我们虽被毁坏，却要重建荒废之处。”万军之耶和华如此说：“任他们建造，我必拆毁；人必称他们为‘邪恶之境’，为‘耶和华永远恼怒之民’。”","notes":[]},{"n":5,"t":"你们必亲眼看见，你们要说：“耶和华在以色列疆界之外必尊为大！”","notes":[]},{"n":6,"t":"万军之耶和华对你们说：“儿子孝敬父亲，仆人敬畏主人；我既为父亲，孝敬我的在哪里呢？我既为主人，敬畏我的在哪里呢？你们这些藐视我名的祭司啊！”你们却说：“我们在何事上藐视你的名呢？”","notes":[],"heads":["斥责祭司"]},{"n":7,"t":"“你们将不洁净的食物献在我的祭坛上，却说：‘我们在何事上使你不洁净呢？’你们说，耶和华的供桌是可藐视的。","notes":[]},{"n":8,"t":"你们将瞎眼的献为祭物，这不算为恶吗？将瘸腿的、有病的献上，这不算为恶吗？那么，请把这些献给你的省长，他岂会悦纳你，岂会抬举你呢？这是万军之耶和华说的。”","notes":["“你”：七十士译本是“它”。"]},{"n":9,"t":"现在我劝你们要恳求神，好让他施恩给我们。这事既出于你们的手，他岂会抬举你们任何人呢？这是万军之耶和华说的。","notes":[]},{"n":10,"t":"万军之耶和华说：“甚愿你们中间有人把殿的门关上，免得你们徒然在我坛上烧火。我不喜欢你们，也不从你们手中悦纳供物。”","notes":["“殿的门”：原文是“门”。"]},{"n":11,"t":"万军之耶和华说：“从日出之地到日落之处，我的名在列国中必尊为大。在各处，人必奉我的名烧香，献洁净的供物，因为我的名在列国中必尊为大。","notes":[]},{"n":12,"t":"你们却亵渎我的名，说：‘主的供桌是不洁净的，供桌上的果子和食物是可藐视的。’","notes":[]},{"n":13,"t":"你们又说：‘看哪，这些事何等烦琐！’并嗤之以鼻。这是万军之耶和华说的。你们把抢来的、瘸腿的、有病的拿来献上为祭，我岂能从你们手中悦纳它呢？这是耶和华说的。","notes":["“嗤之以鼻”：原文另译“瞧不起我”。"]},{"n":14,"t":"行诡诈的人是可诅咒的！他的群畜中虽有公羊，他许了愿，却将有残疾的献给主。因我是大君王，我的名在列国中是可畏的。这是万军之耶和华说的。”","notes":[]}]},"2":{"heading":"百姓对神不忠","verses":[{"n":1,"t":"现在，众祭司啊，这诫命是给你们的。","notes":[]},{"n":2,"t":"万军之耶和华说：“你们若不听，若不放在心上，将荣耀归给我的名，我就使诅咒临到你们，使你们的福分变为诅咒；其实我已经诅咒了你们的福分，因你们不把诫命放在心上。","notes":[]},{"n":3,"t":"看哪，我要斥责你们的后裔，把粪抹在你们脸上，就是你们祭牲的粪。人要把你们和粪一起抬出去，","notes":["“祭牲”：原文是“节期”。"]},{"n":4,"t":"你们就知道我颁这诫命给你们，使我与利未所立的约可以常存。这是万军之耶和华说的。","notes":[]},{"n":5,"t":"我曾与他立生命和平安的约。我将这两样赐给他，使他存敬畏的心；他就敬畏我，惧怕我的名。","notes":[]},{"n":6,"t":"真实的训诲在他口中，他的嘴唇中没有不义。他以平安和正直与我同行，使许多人回转离开罪孽。","notes":[]},{"n":7,"t":"祭司的嘴唇当守护知识，人也当从他口中寻求训诲，因为他是万军之耶和华的使者。","notes":[]},{"n":8,"t":"你们却偏离正道，使许多人在这训诲上绊跌。你们破坏了我与利未人所立的约。这是万军之耶和华说的。","notes":[]},{"n":9,"t":"所以我使你们被众百姓藐视，看为卑贱；因你们不遵守我的道，在律法上看人的情面。”","notes":["“在律法上看人的情面”或译“你们的训诲没有使人得福”。"]},{"n":10,"t":"我们岂不都有一位父吗？岂不是一位神创造了我们吗？为何互相行诡诈，亵渎了神与我们列祖所立的约呢？","notes":[]},{"n":11,"t":"犹大行事诡诈，在以色列和耶路撒冷中行了可憎的事；因为犹大亵渎耶和华所喜爱的圣殿，娶外邦神明的女子为妻。","notes":[]},{"n":12,"t":"凡做这事的，无论是清醒的或回应的，即使献供物给万军之耶和华，耶和华也要将他从雅各的帐棚中剪除。","notes":["“清醒的”或译“看守的”。"]},{"n":13,"t":"你们又再做这样的事，使哭泣和叹息的眼泪遮盖耶和华的祭坛，以致耶和华不再理会那供物，也不喜欢从你们的手中收纳。","notes":[]},{"n":14,"t":"你们还说：“这是为什么呢？”因为耶和华在你和你年轻时所娶的妻之间作证。她虽是你的配偶，你誓约的妻，你却背弃她。","notes":["“誓约”与“配偶”的希伯来话发音相近。"]},{"n":15,"t":"一个人如果还剩下一点灵性，他不会这么做。这人在寻找什么呢？神的后裔！当谨守你们的灵性，谁也不可背弃年轻时所娶的妻。","notes":["“一个人...后裔！”或译“神有灵的余力，不是只能单造一人。为何只造一人呢？乃是愿人得神的子孙。”"]},{"n":16,"t":"耶和华－以色列的神说：“我恨恶休妻的事和衣服外面披上暴力的人。所以当谨守你们的心，不可行诡诈。这是万军之耶和华说的。”","notes":[]},{"n":17,"t":"你们用言语使耶和华厌烦，却说：“我们在何事上使他厌烦呢？”因为你们说：“凡行恶的，耶和华看为善，并且喜爱他们；”又说：“公平的神在哪里呢？”","notes":[],"heads":["审判之日已近"]}]},"3":{"heading":"十一奉献","verses":[{"n":1,"t":"万军之耶和华说：“看哪，我要差遣我的使者在我前面预备道路。你们所寻求的主必忽然来到他的殿；立约的使者，就是你们所仰慕的，看哪，快要来到。”","notes":[]},{"n":2,"t":"他来的日子，谁能当得起呢？他显现的时候，谁能立得住呢？因为他如炼金匠的火，如漂洗者的碱。","notes":[]},{"n":3,"t":"他必坐下如炼净银子的人，必洁净利未人，熬炼他们像金银一样；他们就凭公义献供物给耶和华。","notes":[]},{"n":4,"t":"那时，犹大和耶路撒冷所献的供物必蒙耶和华悦纳，仿佛古时之日、上古之年。","notes":[]},{"n":5,"t":"万军之耶和华说：“我必临近你们，施行审判。我必速速作见证，警戒那些行邪术的、犯奸淫的、起假誓的、剥削雇工工钱的、欺压孤儿寡妇的、屈枉寄居者的和不敬畏我的人。”","notes":[]},{"n":6,"t":"“我－耶和华是不改变的；所以，雅各的子孙啊，你们不致灭亡。","notes":[]},{"n":7,"t":"从你们祖先的日子以来，你们就偏离我的律例而不遵守。现在你们要转向我，我就转向你们。这是万军之耶和华说的。你们却说：‘我们如何转向呢？’","notes":[]},{"n":8,"t":"人岂可抢夺神呢？你们竟抢夺我！你们却说：‘我们在何事上抢夺你呢？’其实就是在你们当纳的十分之一奉献和当献的供物上。","notes":[]},{"n":9,"t":"因你们全国上下都抢夺我的供物，诅咒就临到你们身上。","notes":[]},{"n":10,"t":"你们要将当纳的十分之一全然送入仓库，使我家有粮，以此试试我，是否为你们敞开天上的窗户，倾福与你们，甚至无处可容。这是万军之耶和华说的。","notes":[]},{"n":11,"t":"我必为你们斥责蝗虫，不容它毁坏你们的土产。你们田间的葡萄树，果实未熟以先也不会掉落。这是万军之耶和华说的。","notes":["“蝗虫”：原文是“吞噬者”。"]},{"n":12,"t":"万国必称你们为有福的，因你们必成为喜乐之地。这是万军之耶和华说的。”","notes":[]},{"n":13,"t":"耶和华说：“你们用话顶撞我。”你们却说：“我们说了什么话顶撞你呢？”","notes":[],"heads":["神应许施怜悯"]},{"n":14,"t":"你们说：“事奉神是枉然，我们遵守神所吩咐的，在万军之耶和华面前哀痛而行，有什么益处呢？","notes":[]},{"n":15,"t":"现在，我们称狂傲的人为有福，并且行恶的人得以建立；他们虽然试探神，却得以逃脱。”","notes":[]},{"n":16,"t":"那时，敬畏耶和华的人彼此谈论，耶和华侧耳而听，且有纪念册在他面前，记录那敬畏耶和华、思念他名的人。","notes":[]},{"n":17,"t":"万军之耶和华说：“在我所定的日子，他们必属我，是我宝贵的产业。我必怜悯他们，如同人怜悯那服侍他的儿子。","notes":[]},{"n":18,"t":"那时你们必再一次看出义人和恶人，事奉神和不事奉神的人有何差别。”","notes":["“再一次”：七十士译本是“归回”。"]}]},"4":{"heading":"耶和华的日子临近","verses":[{"n":1,"t":"万军之耶和华说：“看哪，那日临近，势如烧着的火炉，凡狂傲的和行恶的都如碎秸，在那日被烧尽，根与枝条无一存留。","notes":[]},{"n":2,"t":"但是，对你们敬畏我名的人，必有公义的太阳出现，其光线有医治的能力。你们必出来跳跃如圈里的牛犊。","notes":["“光线”：原文是“翅膀”。"]},{"n":3,"t":"你们必践踏恶人；在我所定的日子，他们必成为你们脚掌下的灰尘。这是万军之耶和华说的。","notes":[]},{"n":4,"t":"“你们当记念我仆人摩西的律法，就是我在何烈山为以色列众人所吩咐他的律例典章。","notes":[]},{"n":5,"t":"“看哪，耶和华大而可畏之日未到以前，我要差遣以利亚先知到你们那里去。","notes":[]},{"n":6,"t":"他必使父亲的心转向儿女，儿女的心转向父亲，免得我来诅咒这地。”","notes":[]}]}},"MAT":{"1":{"heading":"耶稣基督的家谱","verses":[{"n":1,"t":"亚伯拉罕的后裔、大卫的子孙耶稣基督的家谱：","notes":["“后裔，子孙”：原文直译“儿子”。"]},{"n":2,"t":"亚伯拉罕生以撒，以撒生雅各，雅各生犹大和他的兄弟，","notes":[]},{"n":3,"t":"犹大从她玛氏生法勒斯和谢拉，法勒斯生希斯仑，希斯仑生亚兰，","notes":[]},{"n":4,"t":"亚兰生亚米拿达，亚米拿达生拿顺，拿顺生撒门，","notes":[]},{"n":5,"t":"撒门从喇合氏生波阿斯，波阿斯从路得氏生俄备得，俄备得生耶西，","notes":[]},{"n":6,"t":"耶西生大卫王。大卫从乌利亚的妻子生所罗门，","notes":[]},{"n":7,"t":"所罗门生罗波安，罗波安生亚比雅，亚比雅生亚撒，","notes":[]},{"n":8,"t":"亚撒生约沙法，约沙法生约兰，约兰生乌西雅，","notes":[]},{"n":9,"t":"乌西雅生约坦，约坦生亚哈斯，亚哈斯生希西家，","notes":[]},{"n":10,"t":"希西家生玛拿西，玛拿西生亚们，亚们生约西亚，","notes":[]},{"n":11,"t":"百姓被迁到巴比伦的时候，约西亚生耶哥尼雅和他的兄弟。","notes":[]},{"n":12,"t":"迁到巴比伦之后，耶哥尼雅生撒拉铁，撒拉铁生所罗巴伯，","notes":[]},{"n":13,"t":"所罗巴伯生亚比玉，亚比玉生以利亚敬，以利亚敬生亚所，","notes":[]},{"n":14,"t":"亚所生撒督，撒督生亚金，亚金生以律，","notes":[]},{"n":15,"t":"以律生以利亚撒，以利亚撒生马但，马但生雅各，","notes":[]},{"n":16,"t":"雅各生约瑟，就是马利亚的丈夫；那称为基督的耶稣是从马利亚生的。","notes":[]},{"n":17,"t":"这样，从亚伯拉罕到大卫共有十四代，从大卫到迁至巴比伦的时候也有十四代，从迁至巴比伦的时候到基督又有十四代。","notes":[]},{"n":18,"t":"耶稣基督降生的事记在下面：他母亲马利亚已经许配给约瑟，还没有迎娶，马利亚就从圣灵怀了孕。","notes":[],"heads":["耶稣基督降生"]},{"n":19,"t":"她丈夫约瑟是个义人，不愿意当众羞辱她，想要暗地里把她休了。","notes":[]},{"n":20,"t":"正考虑这些事的时候，忽然主的使者在约瑟梦中向他显现，说：“大卫的子孙约瑟，不要怕，把你的妻子马利亚娶过来，因她所怀的孕是从圣灵来的。","notes":[]},{"n":21,"t":"她将要生一个儿子，你要给他起名叫耶稣，因他要将自己的百姓从罪恶里救出来。”","notes":[]},{"n":22,"t":"这整件事的发生，是要应验主藉先知所说的话：","notes":[]},{"n":23,"t":"“必有童女怀孕生子；人要称他的名为以马内利。”（以马内利翻出来就是“神与我们同在”。）","notes":[]},{"n":24,"t":"约瑟醒来，就遵照主的使者的吩咐把妻子娶过来；","notes":[]},{"n":25,"t":"但是没有和她同房，直到她生了儿子，就给他起名叫耶稣。","notes":["“儿子”：有古卷是“头胎的儿子”。"]}]},"2":{"heading":"博学之士朝拜","verses":[{"n":1,"t":"在希律作王的时候，耶稣生在犹太的伯利恒。有几个博学之士从东方来到耶路撒冷，说：","notes":["“博学之士”或译“星象家”；7、16节同。"]},{"n":2,"t":"“那生下来作犹太人之王的在哪里？我们在东方看见他的星，特来拜他。”","notes":[]},{"n":3,"t":"希律王听见了，就心里不安；耶路撒冷全城的人也都不安。","notes":[]},{"n":4,"t":"他就召集了祭司长和民间的文士，问他们：“基督该生在哪里？”","notes":[]},{"n":5,"t":"他们说：“在犹太的伯利恒。因为有先知记着：","notes":[]},{"n":6,"t":"‘犹大地的伯利恒啊，你在犹大诸城中并不是最小的；因为将来有一位统治者要从你那里出来，牧养我以色列民。’”","notes":[]},{"n":7,"t":"于是，希律暗地里召了博学之士来，查问那星是什么时候出现的，","notes":[]},{"n":8,"t":"就派他们往伯利恒去，说：“你们去仔细寻访那小孩子，找到了就来报信，我也好去拜他。”","notes":[]},{"n":9,"t":"他们听了王的话就去了。忽然，在东方所看到的那颗星在前面引领他们，一直行到小孩子所在地方的上方就停住了。","notes":[]},{"n":10,"t":"他们看见那星，就非常欢喜；","notes":[]},{"n":11,"t":"进了房子，看见小孩子和他母亲马利亚，就俯伏拜那小孩子，揭开宝盒，拿出黄金、乳香、没药，作为礼物献给他。","notes":[]},{"n":12,"t":"因为在梦中得到主的指示，不要回去见希律，他们就从别的路回自己的家乡去了。","notes":[]},{"n":13,"t":"他们走后，忽然主的使者在约瑟梦中向他显现，说：“起来！带着小孩子和他母亲逃往埃及，住在那里，等我的指示；因为希律要搜寻那小孩子来杀害他。”","notes":[],"heads":["逃往埃及"]},{"n":14,"t":"约瑟就起来，连夜带着小孩子和他母亲往埃及去，","notes":[]},{"n":15,"t":"住在那里，直到希律死了。这是要应验主藉先知所说的话：“我从埃及召我的儿子出来。”","notes":[]},{"n":16,"t":"希律见自己被博学之士愚弄，极其愤怒，差人将伯利恒城里和四境所有的男孩，根据他向博学之士仔细查问到的时间，凡两岁以内的，都杀尽了。","notes":[],"heads":["屠杀男孩"]},{"n":17,"t":"这就应验了耶利米先知所说的话：","notes":[]},{"n":18,"t":"“在拉玛听见号啕大哭的声音，是拉结哭她儿女；她不肯受安慰，因为他们都不在了。”","notes":[]},{"n":19,"t":"希律死了以后，在埃及，忽然主的使者在约瑟梦中向他显现，","notes":[],"heads":["从埃及回来"]},{"n":20,"t":"说：“起来，带着小孩子和他母亲回以色列地去！因为要杀害这小孩子的人已经死了。”","notes":[]},{"n":21,"t":"约瑟就起来，带着小孩子和他母亲进入以色列地去。","notes":[]},{"n":22,"t":"但是他因听见亚基老继承他父亲希律作了犹太王，怕到那里去；又在梦中得到主的指示，就往加利利境内去了。","notes":[]},{"n":23,"t":"他们到了一座城，名叫拿撒勒，就住在那里。这是要应验先知所说的话：“他将称为拿撒勒人。”","notes":[]}]},"3":{"heading":"施洗约翰传道","verses":[{"n":1,"t":"在那些日子，施洗的约翰出来，在犹太的旷野宣讲：","notes":[]},{"n":2,"t":"“你们要悔改！因为天国近了。”","notes":[]},{"n":3,"t":"这人就是以赛亚先知所说的：“在旷野有声音呼喊着：预备主的道，修直他的路。”","notes":[]},{"n":4,"t":"这约翰身穿骆驼毛的衣服，腰束皮带，吃的是蝗虫和野蜜。","notes":[]},{"n":5,"t":"那时，耶路撒冷、全犹太和全约旦河地区的人，都到约翰那里去，","notes":[]},{"n":6,"t":"承认他们的罪，在约旦河里受他的洗。","notes":[]},{"n":7,"t":"约翰看见许多法利赛人和撒都该人也来受洗，就对他们说：“毒蛇的孽种啊，谁指示你们逃避那将要来的愤怒呢？","notes":[]},{"n":8,"t":"你们要结出果子来，和悔改的心相称。","notes":[]},{"n":9,"t":"不要自己心里说：‘我们有亚伯拉罕为祖宗。’我告诉你们，神能从这些石头中给亚伯拉罕兴起子孙来。","notes":[]},{"n":10,"t":"现在斧子已经放在树根上，凡不结好果子的树就砍下来，丢在火里。","notes":[]},{"n":11,"t":"我是用水给你们施洗，叫你们悔改；但那在我以后来的，能力比我更大，我就是给他提鞋子也不配，他要用圣灵与火给你们施洗。","notes":[]},{"n":12,"t":"他手里拿着簸箕，要扬净他的谷物，把麦子收在仓里，把糠用不灭的火烧尽。”","notes":[]},{"n":13,"t":"当时，耶稣从加利利来到约旦河，到了约翰那里，请约翰为他施洗。","notes":[],"heads":["耶稣受洗"]},{"n":14,"t":"约翰想要阻止他，说：“我应该受你的洗，你怎么到我这里来呢？”","notes":[]},{"n":15,"t":"耶稣回答他：“暂且这样做吧，因为我们理当这样履行全部的义。”于是约翰就依了他。","notes":["“义”或译“礼”。"]},{"n":16,"t":"耶稣受了洗，随即从水里上来。天忽然为他开了，他看见神的灵降下，仿佛鸽子落在他身上。","notes":["有古卷没有“为他”。"]},{"n":17,"t":"这时，天上有声音说：“这是我的爱子，我所喜爱的。”","notes":[]}]},"4":{"heading":"耶稣受试探","verses":[{"n":1,"t":"当时，耶稣被圣灵引到旷野，受魔鬼的试探。","notes":[]},{"n":2,"t":"他禁食四十昼夜，后来就饿了。","notes":[]},{"n":3,"t":"那试探者进前来对他说：“你若是神的儿子，叫这些石头变成食物吧。”","notes":[]},{"n":4,"t":"耶稣却回答说：“经上记着：‘人活着，不是单靠食物，乃是靠神口里所出的一切话。’”","notes":[]},{"n":5,"t":"魔鬼就带他进了圣城，叫他站在圣殿顶上，","notes":[]},{"n":6,"t":"对他说：“你若是神的儿子，就跳下去！因为经上记着：‘主要为你命令他的使者，用手托住你，免得你的脚碰在石头上。’”","notes":[]},{"n":7,"t":"耶稣对他说：“经上又记着：‘不可试探主—你的神。’”","notes":[]},{"n":8,"t":"魔鬼又带他上了一座很高的山，将世上的万国和万国的荣华都指给他看，","notes":[]},{"n":9,"t":"对他说：“你若俯伏拜我，我就把这一切赐给你。”","notes":[]},{"n":10,"t":"耶稣说：“撒但，退去！因为经上记着：‘要拜主—你的神，惟独事奉他。’”","notes":["“撒但”就是敌对者的意思，是魔鬼的别名。"]},{"n":11,"t":"于是，魔鬼离开了耶稣，立刻有天使来伺候他。","notes":[]},{"n":12,"t":"耶稣听见约翰下了监，就退到加利利去；","notes":[],"heads":["开始在加利利传道"]},{"n":13,"t":"后来离开拿撒勒，往迦百农去，住在那里。那地方靠海，在西布伦和拿弗他利地区。","notes":[]},{"n":14,"t":"这是要应验以赛亚先知所说的话：","notes":[]},{"n":15,"t":"“西布伦，拿弗他利，沿海的路，约旦河的东边，外邦人的加利利—","notes":[]},{"n":16,"t":"那坐在黑暗里的百姓看见了大光；坐在死荫之地的人有光照耀他们。”","notes":[]},{"n":17,"t":"从那时候，耶稣开始宣讲，说：“你们要悔改！因为天国近了。”","notes":[]},{"n":18,"t":"耶稣沿着加利利海边行走，看见两兄弟，就是那叫彼得的西门和他弟弟安得烈，正往海里撒网；他们本是打鱼的。","notes":[],"heads":["呼召四个渔夫"]},{"n":19,"t":"耶稣对他们说：“来跟从我，我要叫你们得人如得鱼一样。”","notes":[]},{"n":20,"t":"他们立刻舍了网，跟从他。","notes":[]},{"n":21,"t":"耶稣从那里往前走，看见另外两兄弟，就是西庇太的儿子雅各和他弟弟约翰，同他们的父亲西庇太在船上补网，耶稣就呼召他们。","notes":[]},{"n":22,"t":"他们立刻舍了船，辞别父亲，跟从了耶稣。","notes":[]},{"n":23,"t":"耶稣走遍加利利，在各会堂里教导人，宣讲天国的福音，医治百姓各样的疾病。","notes":[],"heads":["向大众传道"]},{"n":24,"t":"他的名声传遍了叙利亚。那里的人把一切病人，就是有各样疾病和疼痛的、被鬼附的、癫痫的、瘫痪的，都带了来，耶稣就治好了他们。","notes":[]},{"n":25,"t":"当时，有一大群人从加利利、低加坡里、耶路撒冷、犹太、约旦河的东边，来跟从他。","notes":[]}]},"5":{"heading":"山上宝训","verses":[{"n":1,"t":"耶稣看见这一群人，就上了山，坐下后，门徒到他跟前来，","notes":[]},{"n":2,"t":"他开口教导他们说：","notes":[]},{"n":3,"t":"“心灵贫穷的人有福了！因为天国是他们的。","notes":[],"heads":["论福"]},{"n":4,"t":"哀恸的人有福了！因为他们必得安慰。","notes":[]},{"n":5,"t":"谦和的人有福了！因为他们必承受土地。","notes":[]},{"n":6,"t":"饥渴慕义的人有福了！因为他们必得饱足。","notes":[]},{"n":7,"t":"怜悯人的人有福了！因为他们必蒙怜悯。","notes":[]},{"n":8,"t":"清心的人有福了！因为他们必得见神。","notes":[]},{"n":9,"t":"缔造和平的人有福了！因为他们必称为神的儿子。","notes":[]},{"n":10,"t":"为义受迫害的人有福了！因为天国是他们的。","notes":[]},{"n":11,"t":"“人若因我辱骂你们，迫害你们，捏造各样坏话毁谤你们，你们就有福了！","notes":["“捏造…你们”：有古卷是“说各样坏话毁谤你们”。"]},{"n":12,"t":"要欢喜快乐，因为你们在天上的赏赐是很多的。在你们以前的先知，人也是这样迫害他们。”","notes":[]},{"n":13,"t":"“你们是地上的盐。盐若失了味，怎能叫它再咸呢？它不再有用，只好被丢在外面，任人践踏。","notes":[],"heads":["盐和光"]},{"n":14,"t":"你们是世上的光。城造在山上是不能隐藏的。","notes":[]},{"n":15,"t":"人点灯，不放在斗底下，而是放在灯台上，就照亮一家的人。","notes":[]},{"n":16,"t":"你们的光也要这样照在人前，叫他们看见你们的好行为，把荣耀归给你们在天上的父。”","notes":[]},{"n":17,"t":"“不要以为我来是要废掉律法和先知。我来不是要废掉，而是要成全。","notes":[],"heads":["论律法"]},{"n":18,"t":"我实在告诉你们，就是到天地都废去，律法的一点一画也不能废去，直到一切都实现。","notes":[]},{"n":19,"t":"所以，无论谁废掉这诫命中最小的一条，又教导人也这样做，他在天国里要称为最小的。但无论谁遵行并如此教导人的，他在天国里要称为大。","notes":[]},{"n":20,"t":"我告诉你们，你们的义若不胜过文士和法利赛人的义，绝不能进天国。”","notes":[]},{"n":21,"t":"“你们听过有对古人说：‘不可杀人’；‘凡杀人的，必须受审判。’","notes":[],"heads":["论发怒"]},{"n":22,"t":"但是我告诉你们：凡向弟兄动怒的，必须受审判；凡骂弟兄是废物的，必须受议会的审判；凡骂弟兄是白痴的，必须遭受地狱的火。","notes":[]},{"n":23,"t":"所以，你在祭坛上献祭物的时候，若想起有弟兄对你怀恨，","notes":[]},{"n":24,"t":"就要把祭物留在坛前，先去跟弟兄和好，然后来献祭物。","notes":[]},{"n":25,"t":"你同告你的冤家还在路上，就要赶快与他讲和，免得他把你送交给法官，法官交给警卫，你就下在监里了。","notes":[]},{"n":26,"t":"我实在告诉你，就是有一个大文钱还没有还清，你也绝不能从那里出来。”","notes":["“大文钱”：参“度量衡表”。"]},{"n":27,"t":"“你们听过有话说：‘不可奸淫。’","notes":[],"heads":["论奸淫"]},{"n":28,"t":"但是我告诉你们：凡看见妇女就动淫念的，这人心里已经与她犯奸淫了。","notes":[]},{"n":29,"t":"若是你的右眼使你跌倒，就把它挖出来，丢掉。宁可失去身体中的一部分，也不让整个身体被扔进地狱。","notes":[]},{"n":30,"t":"若是你的右手使你跌倒，就把它砍下来，丢掉。宁可失去身体中的一部分，也不让整个身体下地狱。”","notes":[]},{"n":31,"t":"“又有话说：‘无论谁休妻，都要给她休书。’","notes":[],"heads":["论休妻"]},{"n":32,"t":"但是我告诉你们：凡休妻的，除非是因不贞的缘故，否则就是使她犯奸淫了；人若娶被休的妇人，也是犯奸淫了。”","notes":[]},{"n":33,"t":"“你们又听过有对古人说：‘不可背誓，所起的誓总要向主谨守。’","notes":[],"heads":["论起誓"]},{"n":34,"t":"但是我告诉你们：什么誓都不可起。不可指着天起誓，因为天是神的宝座。","notes":[]},{"n":35,"t":"不可指着地起誓，因为地是他的脚凳；也不可指着耶路撒冷起誓，因为耶路撒冷是大君王的京城。","notes":[]},{"n":36,"t":"又不可指着你的头起誓，因为你不能使一根头发变黑变白。","notes":[]},{"n":37,"t":"你们的话，是，就说是；不是，就说不是。若再多说，就是出于那恶者。”","notes":[]},{"n":38,"t":"“你们听过有话说：‘以眼还眼，以牙还牙。’","notes":[],"heads":["论报复"]},{"n":39,"t":"但是我告诉你们：不要与恶人作对。有人打你的右脸，连另一边也转过去由他打。","notes":[]},{"n":40,"t":"有人想要告你，要拿你的里衣，连外衣也由他拿去。","notes":[]},{"n":41,"t":"有人强迫你走一里路，你就跟他走二里。","notes":["“里”原文音译“米利翁”，古罗马长度单位；参“度量衡表”；下同。"]},{"n":42,"t":"有求你的，就给他；有向你借贷的，不可推辞。”","notes":[]},{"n":43,"t":"“你们听过有话说：‘要爱你的邻舍，恨你的仇敌。’","notes":[],"heads":["论爱仇敌"]},{"n":44,"t":"但是我告诉你们：要爱你们的仇敌，为那迫害你们的祷告。","notes":[]},{"n":45,"t":"这样，你们就可以作天父的儿女了。因为他叫太阳照好人，也照坏人；降雨给义人，也给不义的人。","notes":[]},{"n":46,"t":"你们若只爱那爱你们的人，有什么赏赐呢？就是税吏不也是这样做吗？","notes":[]},{"n":47,"t":"你们若只请你弟兄的安，有什么比别人强呢？就是外邦人不也是这样做吗？","notes":[]},{"n":48,"t":"所以，你们要完全，如同你们的天父是完全的。”","notes":[]}]},"6":{"heading":"论施舍","verses":[{"n":1,"t":"“你们要谨慎，不可故意在人面前表现虔诚，叫他们看见，若是这样，就不能得你们天父的赏赐了。","notes":[]},{"n":2,"t":"“所以，你施舍的时候，不可叫人在你前面吹号，像那假冒为善的人在会堂里和街道上所做的，故意要得人的称赞。我实在告诉你们，他们已经得了他们的赏赐。","notes":[]},{"n":3,"t":"你施舍的时候，不要让左手知道右手所做的，","notes":[]},{"n":4,"t":"好使你隐秘地施舍；你父在隐秘中察看，必然赏赐你。”","notes":[]},{"n":5,"t":"“你们祷告的时候，不可像那假冒为善的人，爱站在会堂里和十字路口祷告，故意让人看见。我实在告诉你们，他们已经得了他们的赏赐。","notes":[],"heads":["论祷告"]},{"n":6,"t":"你祷告的时候，要进入内室，关上门，向那在隐秘中的父祷告；你父在隐秘中察看，必将赏赐你。","notes":[]},{"n":7,"t":"你们祷告，不可像外邦人那样重复一些空话，他们以为话多了必蒙垂听。","notes":[]},{"n":8,"t":"你们不可效法他们。因为在你们祈求以前，你们所需要的，你们的父早已知道了。”","notes":[]},{"n":9,"t":"“所以，你们要这样祷告：‘我们在天上的父：愿人都尊你的名为圣。","notes":[],"heads":["主祷文"]},{"n":10,"t":"愿你的国降临；愿你的旨意行在地上，如同行在天上。","notes":[]},{"n":11,"t":"我们日用的饮食，今日赐给我们。","notes":[]},{"n":12,"t":"免我们的债，如同我们免了人的债。","notes":[]},{"n":13,"t":"不叫我们陷入试探；救我们脱离那恶者。因为国度、权柄、荣耀，全是你的，直到永远。阿们！’","notes":["有古卷没有“因为...阿们”等字。"]},{"n":14,"t":"你们若饶恕人的过犯，你们的天父也必饶恕你们；","notes":[]},{"n":15,"t":"你们若不饶恕人，你们的天父也必不饶恕你们的过犯。”","notes":["有古卷加“的过犯”。"]},{"n":16,"t":"“你们禁食的时候，不可像那假冒为善的人，脸上带着愁容；因为他们蓬头垢面，故意让人看出他们在禁食。我实在告诉你们，他们已经得了他们的赏赐。","notes":[],"heads":["论禁食"]},{"n":17,"t":"你禁食的时候，要梳头洗脸，","notes":[]},{"n":18,"t":"不要让人看出你在禁食，只让你隐秘中的父看见；你父在隐秘中察看，必然赏赐你。”","notes":[]},{"n":19,"t":"“不要为自己在地上积蓄财宝；地上有虫子咬，能锈坏，也有贼挖洞来偷。","notes":[],"heads":["论天上的财宝"]},{"n":20,"t":"要在天上积蓄财宝；天上没有虫子咬，不会锈坏，也没有贼挖洞来偷。","notes":[]},{"n":21,"t":"因为你的财宝在哪里，你的心也在哪里。”","notes":[]},{"n":22,"t":"“眼睛是身体的灯。你的眼睛若明亮，全身就光明；","notes":[],"heads":["眼睛是身体的灯"]},{"n":23,"t":"你的眼睛若昏花，全身就黑暗。你里面的光若黑暗了，那黑暗是何等大呢！”","notes":[]},{"n":24,"t":"“一个人不能服侍两个主；他不是恨这个爱那个，就是重这个轻那个。你们不能又服侍神，又服侍玛门。”","notes":["“玛门”意思是“钱财”。"],"heads":["论神和钱财"]},{"n":25,"t":"“所以，我告诉你们，不要为你们的生命忧虑吃什么喝什么，或为你们的身体忧虑穿什么。生命不胜于饮食吗？身体不胜于衣裳吗？","notes":["有古卷没有“喝什么”。"],"heads":["不要忧虑"]},{"n":26,"t":"你们看一看那天上的飞鸟，也不种也不收，也不在仓里存粮，你们的天父尚且养活它们。你们不比飞鸟贵重得多吗？","notes":[]},{"n":27,"t":"你们哪一个能藉着忧虑使寿数多加一刻呢？","notes":["“使寿数多加一刻呢”或译“使身量多加一肘呢”。"]},{"n":28,"t":"何必为衣裳忧虑呢？你们想一想野地里的百合花是怎么长起来的：它也不劳动也不纺线。","notes":[]},{"n":29,"t":"然而我告诉你们，就是所罗门极荣华的时候，他所穿戴的还不如这些花的一朵呢！","notes":[]},{"n":30,"t":"你们这小信的人哪！野地里的草今天还在，明天就丢在炉里，神还给它这样的妆饰，何况你们呢？","notes":[]},{"n":31,"t":"所以，不要忧虑，说：‘我们吃什么？喝什么？穿什么？’","notes":[]},{"n":32,"t":"这都是外邦人所求的。你们需要这一切东西，你们的天父都知道。","notes":[]},{"n":33,"t":"你们要先求神的国和他的义，这些东西都要加给你们了。","notes":[]},{"n":34,"t":"所以，不要为明天忧虑，因为明天自有明天的忧虑；一天的难处一天当就够了。”","notes":[]}]},"7":{"heading":"不要评断人","verses":[{"n":1,"t":"“你们不要评断别人，免得你们被审判。","notes":[]},{"n":2,"t":"因为你们怎样评断别人，也必怎样被审判；你们用什么量器量给人，也必用什么量器量给你们。","notes":[]},{"n":3,"t":"为什么看见你弟兄眼中有刺，却不想自己眼中有梁木呢？","notes":[]},{"n":4,"t":"你自己眼中有梁木，怎能对你弟兄说‘让我去掉你眼中的刺’呢？","notes":[]},{"n":5,"t":"你这假冒为善的人！先去掉自己眼中的梁木，然后才能看得清楚，好去掉你弟兄眼中的刺。","notes":[]},{"n":6,"t":"不要把圣物给狗，也不要把你们的珍珠丢在猪面前，恐怕它们践踏了珍珠，转过来咬你们。”","notes":[]},{"n":7,"t":"“你们祈求，就给你们；寻找，就找到；叩门，就给你们开门。","notes":[],"heads":["祈求、寻找、叩门"]},{"n":8,"t":"因为凡祈求的，就得着；寻找的，就找到；叩门的，就给他开门。","notes":[]},{"n":9,"t":"你们中间谁有儿子求饼，反给他石头呢？","notes":[]},{"n":10,"t":"求鱼，反给他蛇呢？","notes":[]},{"n":11,"t":"你们虽然不好，尚且知道拿好东西给儿女，何况你们在天上的父，他岂不更要把好东西赐给求他的人吗？","notes":[]},{"n":12,"t":"所以，无论何事，你们想要人怎样待你们，你们也要怎样待人，因为这就是律法和先知的道理。”","notes":[]},{"n":13,"t":"“你们要进窄门。因为通往灭亡的门是宽的，路是大的，进去的人也多；","notes":[],"heads":["要进窄门"]},{"n":14,"t":"通往生命的门是窄的，路是小的，找到的人也少。”","notes":[]},{"n":15,"t":"“你们要防备假先知。他们到你们这里来，外面披着羊皮，里面却是残暴的狼。","notes":[],"heads":["两种果树"]},{"n":16,"t":"岂能在荆棘上摘葡萄呢？岂能在蒺藜里摘无花果呢？凭着他们的果子，就可以认出他们来。","notes":[]},{"n":17,"t":"这样，凡好树都结好果子，而坏树结坏果子。","notes":[]},{"n":18,"t":"好树不能结坏果子，坏树也不能结好果子。","notes":[]},{"n":19,"t":"凡不结好果子的树就砍下来，丢在火里。","notes":[]},{"n":20,"t":"所以，凭着他们的果子就可以认出他们来。”","notes":[]},{"n":21,"t":"“不是每一个称呼我‘主啊，主啊’的人都能进天国；惟有遵行我天父旨意的人才能进去。","notes":[],"heads":["遵主旨得进天国"]},{"n":22,"t":"在那日必有许多人对我说：‘主啊，主啊，我们不是奉你的名传道，奉你的名赶鬼，奉你的名行许多异能吗？’","notes":[]},{"n":23,"t":"我要向他们宣告：‘我从来不认识你们，你们这些作恶的人，给我走开！’”","notes":[]},{"n":24,"t":"“所以，凡听了我这些话又去做的，好比一个聪明人把房子盖在磐石上。","notes":[],"heads":["两种根基"]},{"n":25,"t":"风吹，雨打，水冲，撞击那房子，房子总不倒塌，因为根基立在磐石上。","notes":[]},{"n":26,"t":"凡听了我这些话而不去做的，好比一个无知的人把房子盖在沙土上。","notes":[]},{"n":27,"t":"风吹，雨打，水冲，撞击那房子，房子就倒塌了，并且倒塌得很厉害。”","notes":[]},{"n":28,"t":"耶稣讲完了这些话，众人对他的教导都感到惊奇，","notes":[]},{"n":29,"t":"因为他教导他们正像有权柄的人，不像他们的文士。","notes":[]}]},"8":{"heading":"洁净麻风病人","verses":[{"n":1,"t":"耶稣下了山，有一大群人跟着他。","notes":[]},{"n":2,"t":"这时，一个麻风病人前来拜他，说：“主啊，你若肯，你能使我洁净。”","notes":[]},{"n":3,"t":"耶稣伸手摸他，说：“我肯，你洁净了吧！”他的麻风病立刻就洁净了。","notes":[]},{"n":4,"t":"耶稣对他说：“你要注意，不可告诉任何人，只要去，让祭司为你检查，并献上摩西所吩咐的祭物，作为证据给众人看。”","notes":[]},{"n":5,"t":"耶稣进了迦百农，有一个百夫长进前来，求他，","notes":[],"heads":["治好百夫长的僮仆"]},{"n":6,"t":"说：“主啊，我的僮仆瘫痪了，躺在家里，非常痛苦。”","notes":[]},{"n":7,"t":"耶稣说：“我去医治他。”","notes":[]},{"n":8,"t":"百夫长回答：“主啊，你到舍下来，我不敢当；只要你说一句话，我的僮仆就会痊愈。","notes":[]},{"n":9,"t":"因为我在人的权下，也有兵在我以下。我对这个说：‘去！’他就去；对那个说：‘来！’他就来；对我的仆人说：‘做这事！’他就去做。”","notes":[]},{"n":10,"t":"耶稣听了就很惊讶，对跟从的人说：“我实在告诉你们，这么大的信心，就是在以色列，我也没有见过。","notes":[]},{"n":11,"t":"我又告诉你们，从东从西，将有许多人来，在天国里与亚伯拉罕、以撒、雅各一同坐席；","notes":[]},{"n":12,"t":"本国的子民反而被赶到外边黑暗里去，在那里要哀哭切齿了。”","notes":[]},{"n":13,"t":"耶稣对百夫长说：“你回去吧！照你的信心成全你了。”就在那时，他的僮仆好了。","notes":[]},{"n":14,"t":"耶稣到了彼得家里，见彼得的岳母正发烧躺着。","notes":[],"heads":["治好许多病人"]},{"n":15,"t":"耶稣一摸她的手，烧就退了，于是她起来服事耶稣。","notes":[]},{"n":16,"t":"傍晚的时候，有人带着许多被鬼附的来到耶稣跟前，他只用一句话就把邪灵都赶出去，并且治好了一切有病的人。","notes":[]},{"n":17,"t":"这是要应验以赛亚先知所说的话：“他代替了我们的软弱，担当了我们的疾病。”","notes":[]},{"n":18,"t":"耶稣见许多人围着他，就吩咐渡到对岸去。","notes":[],"heads":["跟从耶稣应有的准备"]},{"n":19,"t":"有一个文士进前来对他说：“老师，你无论往哪里去，我都要跟从你。”","notes":[]},{"n":20,"t":"耶稣说：“狐狸有洞，天空的飞鸟有窝，人子却没有枕头的地方。”","notes":[]},{"n":21,"t":"又有一个门徒对耶稣说：“主啊，容许我先回去埋葬我的父亲。”","notes":[]},{"n":22,"t":"耶稣说：“让死人埋葬他们的死人。你跟从我吧！”","notes":[]},{"n":23,"t":"耶稣上了船，门徒跟着他。","notes":[],"heads":["平静风和海"]},{"n":24,"t":"海里忽然起了猛烈的风暴，以致船几乎被波浪淹没，耶稣却睡着了。","notes":[]},{"n":25,"t":"门徒去叫醒他，说：“主啊，救命啊，我们快没命啦！”","notes":[]},{"n":26,"t":"耶稣说：“你们这些小信的人哪，为什么胆怯呢？”于是他起来，斥责风和海，风和海就大大平静了。","notes":[]},{"n":27,"t":"众人惊讶地说：“这是怎样的一个人？连风和海都听从他。”","notes":[]},{"n":28,"t":"耶稣渡到对岸去，到加大拉人的地区，有两个被鬼附的人从坟墓迎着他走来。他们极其凶猛，甚至没有人敢从那条路经过。","notes":["有古卷是“格各森人”；另有古卷是“格拉森人”。"],"heads":["治好加大拉被鬼附的人"]},{"n":29,"t":"他们喊着说：“神的儿子，你为什么干扰我们？时候还没有到，你就上这里来叫我们受苦吗？”","notes":[]},{"n":30,"t":"离他们很远，有一大群猪正在吃食。","notes":[]},{"n":31,"t":"鬼就央求耶稣，说：“若要把我们赶出去，就打发我们进入猪群吧！”","notes":[]},{"n":32,"t":"耶稣对他们说：“去吧！”鬼就出来，进入猪群。一转眼，整群猪都闯下山崖，投进海里，淹死了。","notes":[]},{"n":33,"t":"放猪的就逃进城去，把这一切事和被鬼附的人所遭遇的都告诉众人。","notes":[]},{"n":34,"t":"全城的人都出来迎见耶稣，见了他以后，就央求他离开他们的地区。","notes":[]}]},"9":{"heading":"治好瘫子","verses":[{"n":1,"t":"耶稣上了船，渡过海，来到自己的城里。","notes":[]},{"n":2,"t":"有人用褥子抬着一个瘫子到耶稣跟前来。耶稣见他们的信心，就对瘫子说：“孩子，放心吧，你的罪赦了。”","notes":[]},{"n":3,"t":"这时，有几个文士心里说：“这个人说亵渎的话了。”","notes":[]},{"n":4,"t":"耶稣知道他们的心思，就说：“你们心里为什么怀着恶念呢？","notes":[]},{"n":5,"t":"说‘你的罪赦了’，或说‘你起来行走’，哪一样容易呢？","notes":[]},{"n":6,"t":"但要让你们知道，人子在地上有赦罪的权柄”，于是对瘫子说：“起来！拿你的褥子回家去吧。”","notes":[]},{"n":7,"t":"那人就起来，回家去了。","notes":[]},{"n":8,"t":"众人看见都畏惧，归荣耀给神，因为他把这样的权柄赐给人。","notes":[]},{"n":9,"t":"耶稣从那里往前走，看见一个人名叫马太，在税关坐着，就对他说：“来跟从我！”他就起来跟从耶稣。","notes":[],"heads":["呼召马太"]},{"n":10,"t":"耶稣在屋里坐席的时候，有好些税吏和罪人来，与耶稣和他的门徒一同坐席。","notes":[]},{"n":11,"t":"法利赛人看见，就对耶稣的门徒说：“你们的老师为什么与税吏和罪人一同吃饭呢？”","notes":[]},{"n":12,"t":"耶稣听见，就说：“健康的人用不着医生；有病的人才用得着。","notes":[]},{"n":13,"t":"经上说：‘我喜爱怜悯，不喜爱祭祀。’这句话的意思，你们去揣摩。我不是来召义人，而是召罪人。”","notes":[]},{"n":14,"t":"那时，约翰的门徒来见耶稣，说：“我们和法利赛人常常禁食，你的门徒却不禁食，这是为什么呢？”","notes":["有古卷没有“常常”。"],"heads":["禁食的问题"]},{"n":15,"t":"耶稣对他们说：“新郎和宾客在一起的时候，宾客怎么能哀恸呢？但日子将到，新郎要被带走，那时候他们就要禁食了。","notes":[]},{"n":16,"t":"没有人把新布补在旧衣服上；因为所补上的会撕破那衣服，裂口就更大了。","notes":[]},{"n":17,"t":"也没有人把新酒装在旧皮袋里，若是这样，皮袋会胀破，酒就漏出来，皮袋也糟蹋了。相反地，把新酒装在新皮袋里，两样就都保全了。”","notes":[]},{"n":18,"t":"耶稣说这些话的时候，有一个会堂主管来，向他下跪，说：“我女儿刚死了，求你去按手在她身上，她就会活过来。”","notes":[],"heads":["会堂主管的女儿和经血不止的女人"]},{"n":19,"t":"耶稣就起来跟他去；门徒也跟了去。","notes":[]},{"n":20,"t":"这时，有一个女人，患了经血不止的病有十二年，来到耶稣背后，摸他的衣裳繸子；","notes":[]},{"n":21,"t":"因为她心里说：“我只要摸他的衣裳，就会痊愈。”","notes":[]},{"n":22,"t":"耶稣转过来，看见她，就说：“女儿，放心！你的信救了你。”从那时起，这女人就痊愈了。","notes":[]},{"n":23,"t":"耶稣到了会堂主管的家里，看见吹鼓手和乱哄哄的一群人，","notes":[]},{"n":24,"t":"就说：“退去吧！这女孩不是死了，而是睡着了。”他们就嘲笑他。","notes":[]},{"n":25,"t":"众人被赶出后，耶稣就进去，拉着她的手，女孩就起来了。","notes":[]},{"n":26,"t":"于是这消息传遍了那地方。","notes":[]},{"n":27,"t":"耶稣从那里往前走，有两个盲人跟着他，喊叫说：“大卫之子，可怜我们吧！”","notes":[],"heads":["治好两个盲人"]},{"n":28,"t":"耶稣进了屋子，盲人就来到他跟前。耶稣说：“你们信我能做这事吗？”他们说：“主啊，我们信。”","notes":[]},{"n":29,"t":"耶稣就摸他们的眼睛，说：“照着你们的信心成全你们吧。”","notes":[]},{"n":30,"t":"他们的眼睛就开了。耶稣严严地叮嘱他们说：“要小心，不可让人知道。”","notes":[]},{"n":31,"t":"他们出去，竟把他的名声传遍了那地方。","notes":[]},{"n":32,"t":"他们出去的时候，有人把一个被鬼附的哑巴带到耶稣跟前来。","notes":[],"heads":["治好哑巴"]},{"n":33,"t":"鬼被赶出去，哑巴就说出话来。众人都很惊讶，说：“在以色列，从来没有见过这样的事。”","notes":[]},{"n":34,"t":"法利赛人却说：“他是靠着鬼王赶鬼的。”","notes":[]},{"n":35,"t":"耶稣走遍各城各乡，在他们的会堂里教导人，宣讲天国的福音，又医治各样的病症。","notes":[],"heads":["耶稣的怜悯"]},{"n":36,"t":"他看见一大群人，就怜悯他们；因为他们困苦无助，如同羊没有牧人一样。","notes":[]},{"n":37,"t":"于是他对门徒说：“要收的庄稼多，做工的人少。","notes":[]},{"n":38,"t":"所以，你们要求庄稼的主差遣做工的人出去收他的庄稼。”","notes":[]}]},"10":{"heading":"耶稣拣选十二使徒","verses":[{"n":1,"t":"耶稣叫了十二个门徒来，给他们权柄，能驱赶污灵和医治各样的疾病。","notes":[]},{"n":2,"t":"这十二使徒的名字如下：头一个叫西门（又称彼得），还有他弟弟安得烈，西庇太的儿子雅各和雅各的弟弟约翰，","notes":[]},{"n":3,"t":"腓力和巴多罗买，多马和税吏马太，亚勒腓的儿子雅各，和达太，","notes":[]},{"n":4,"t":"激进党的西门，还有出卖耶稣的加略人犹大。","notes":[]},{"n":5,"t":"耶稣差遣这十二个人出去，吩咐他们说：“外邦人的路，你们不要走；撒玛利亚人的城，你们不要进；","notes":[],"heads":["耶稣差遣十二使徒"]},{"n":6,"t":"宁可往以色列家迷失的羊那里去。","notes":[]},{"n":7,"t":"要边走边传，说‘天国近了’。","notes":[]},{"n":8,"t":"要医治病人，使死人复活，使麻风病人洁净，把鬼赶出去。你们白白地得来，也要白白地给人。","notes":[]},{"n":9,"t":"腰袋里不要带金银铜钱；","notes":[]},{"n":10,"t":"途中不要带行囊，不要带两件内衣，也不要带鞋子和手杖，因为工人得饮食是应当的。","notes":[]},{"n":11,"t":"你们无论进哪一城、哪一村，要打听那里谁是合适的人，就住在他家，直住到离开的时候。","notes":[]},{"n":12,"t":"进他家时，要向那家请安。","notes":[]},{"n":13,"t":"那家若配得平安，你们所求的平安就临到那家；若不配得，你们所求的平安仍归你们。","notes":[]},{"n":14,"t":"凡不接待你们，不听你们话的人，你们离开那家，或是那城的时候，要跺掉你们脚上的尘土。","notes":[]},{"n":15,"t":"我实在告诉你们，在审判的日子，所多玛和蛾摩拉地方所受的，比那城还容易受呢！”","notes":[]},{"n":16,"t":"“看哪！我差你们出去，如同羊进入狼群，所以你们要机警如蛇，纯真如鸽。","notes":[],"heads":["将来的迫害"]},{"n":17,"t":"你们要防备那些人，因为他们要把你们交给议会，也要在会堂里鞭打你们。","notes":[]},{"n":18,"t":"你们要为我的缘故被送到统治者和君王面前，对他们和外邦人作见证。","notes":[]},{"n":19,"t":"当人把你们交出时，不要担心怎样说话，或说什么话。到那时候，必赐给你们该说的话，","notes":[]},{"n":20,"t":"因为不是你们自己说的，而是你们父的灵在你们里面说的。","notes":[]},{"n":21,"t":"兄弟要把兄弟、父亲要把儿女置于死地；儿女要起来与父母为敌，害死他们。","notes":[]},{"n":22,"t":"而且你们要为我的名被众人憎恨。但坚忍到底的终必得救。","notes":[]},{"n":23,"t":"有人在这城迫害你们，就逃到另一城去。我实在告诉你们，以色列的城镇，你们还没有走遍，人子就要来临。","notes":["有古卷加“若那城的人迫害你们，就逃到别的城去。”"]},{"n":24,"t":"“学生不高过老师，仆人不高过主人。","notes":[]},{"n":25,"t":"学生所遭遇的与老师一样，仆人所遭遇的与主人一样，也就够了。既然有人骂一家的主人是‘别西卜’，更何况他的家人呢？”","notes":["“别西卜”：鬼王的名。"]},{"n":26,"t":"“所以，不要怕他们，因为掩盖的事没有不显露出来的，隐藏的事也没有不被知道的。","notes":[],"heads":["不要惧怕"]},{"n":27,"t":"我在暗中告诉你们的，你们要在明处说出来；你们耳中所听的，要在屋顶上宣扬出来。","notes":[]},{"n":28,"t":"那杀人身体但不能灭人灵魂的，不要怕他们；惟有那能在地狱里毁灭身体和灵魂的，才要怕他。","notes":[]},{"n":29,"t":"两只麻雀不是卖一铜钱吗？你们的父若不许，一只也不会掉在地上。","notes":["“铜钱”：参“度量衡表”。"]},{"n":30,"t":"就是你们的头发也都数过了。","notes":[]},{"n":31,"t":"所以，不要惧怕，你们比许多的麻雀还贵重！”","notes":[]},{"n":32,"t":"“所以，凡在人面前认我的，我在我天上的父面前也必认他；","notes":[],"heads":["在人的面前认基督"]},{"n":33,"t":"凡在人面前不认我的，我在我天上的父面前也必不认他。”","notes":[]},{"n":34,"t":"“你们不要以为我来是带给地上和平，我来并不是带来和平，而是刀剑。","notes":[],"heads":["作门徒的代价"]},{"n":35,"t":"因为我来是要叫‘人与父亲对立，女儿与母亲对立，媳妇与婆婆对立。","notes":[]},{"n":36,"t":"人的仇敌就是自己家里的人。’","notes":[]},{"n":37,"t":"爱父母胜过爱我的，不配作我的门徒；爱儿女胜过爱我的，不配作我的门徒。","notes":[]},{"n":38,"t":"不背自己的十字架跟从我的，不配作我的门徒。","notes":[]},{"n":39,"t":"得着性命的，要丧失性命；为我丧失性命的，要得着性命。”","notes":[]},{"n":40,"t":"“接纳你们的就是接纳我；接纳我的就是接纳差遣我来的那位。","notes":[],"heads":["论赏赐"]},{"n":41,"t":"把先知当作先知接纳的，必得先知的赏赐；把义人当作义人接纳的，必得义人的赏赐。","notes":[]},{"n":42,"t":"无论谁，只因门徒的名，就算把一杯凉水给这些小子中的一个喝，我实在告诉你们，他一定会得到赏赐。”","notes":[]}]},"11":{"heading":"施洗约翰的门徒来见耶稣","verses":[{"n":1,"t":"耶稣吩咐完了十二个门徒，就离开那里，往各城去传道，教导人。","notes":[]},{"n":2,"t":"约翰在监狱里听见基督所做的事，就派他的门徒去，","notes":[]},{"n":3,"t":"问耶稣：“将要来的那位就是你吗？还是我们要等候另一位呢？”","notes":[]},{"n":4,"t":"耶稣回答他们：“你们去，把所听见、所看见的告诉约翰：","notes":[]},{"n":5,"t":"就是盲人看见，瘸子行走，麻风病人得洁净，聋子听见，死人复活，穷人听到福音。","notes":[]},{"n":6,"t":"凡不因我跌倒的有福了！”","notes":[]},{"n":7,"t":"他们一走，耶稣就对众人谈到约翰，说：“你们从前到旷野去，是要看什么呢？看风吹动的芦苇吗？","notes":[]},{"n":8,"t":"你们出去到底是要看什么？看穿细软衣服的人吗？那穿细软衣服的人是在王宫里。","notes":[]},{"n":9,"t":"你们出去究竟是要看什么？是先知吗？是的，我告诉你们，他比先知大多了。","notes":[]},{"n":10,"t":"这个人就是经上所说的：‘看哪，我要差遣我的使者在你面前，他要在你前面为你预备道路。’","notes":[]},{"n":11,"t":"我实在告诉你们，凡女子所生的，没有一个比施洗约翰大；但在天国里，最小的比他还大。","notes":[]},{"n":12,"t":"从施洗约翰的日子到今天，天国受到强烈的攻击，强者夺取它。","notes":["“天国…夺取它”或译“天国是要努力进入的，努力的人就得着了”。"]},{"n":13,"t":"众先知和律法，直到约翰为止，都说了预言。","notes":[]},{"n":14,"t":"如果你们愿意接受，这人就是那要来的以利亚。","notes":[]},{"n":15,"t":"有耳的，就应当听！","notes":[]},{"n":16,"t":"“我该用什么来比这世代呢？这正像孩童坐在街市上向同伴呼喊：","notes":[]},{"n":17,"t":"‘我们为你们吹笛，你们不跳舞；我们唱哀歌，你们不捶胸。’","notes":[]},{"n":18,"t":"约翰来了，既不吃也不喝，人们就说他是被鬼附的；","notes":[]},{"n":19,"t":"人子来了，也吃也喝，他们又说这人贪食好酒，是税吏和罪人的朋友。而智慧是由它的果子来证实的。”","notes":["有古卷是“而智慧是以行为来证实的”。"]},{"n":20,"t":"那时，耶稣在一些城行了许多异能。因为城里的人不肯悔改，他就责备那些城说：","notes":[],"heads":["耶稣责备不悔改的城"]},{"n":21,"t":"“哥拉汛哪，你有祸了！伯赛大啊，你有祸了！因为在你们中间所行的异能若行在推罗、西顿，他们早已披麻蒙灰悔改了。","notes":[]},{"n":22,"t":"但我告诉你们，在审判的日子，推罗和西顿所受的，比你们还容易受呢！","notes":[]},{"n":23,"t":"迦百农啊，你以为要被举到天上吗？你要被推下阴间！因为在你那里所行的异能，若行在所多玛，它还可以存留到今日。","notes":[]},{"n":24,"t":"但我告诉你们，在审判的日子，所多玛地方所受的，比你们还容易受呢！”","notes":[]},{"n":25,"t":"那时，耶稣说：“父啊，天地的主，我感谢你！因为你把这些事向聪明智慧的人隐藏起来，而向婴孩启示出来。","notes":[],"heads":["到我这里来"]},{"n":26,"t":"父啊，是的，因为你的美意本是如此。","notes":[]},{"n":27,"t":"一切都是我父交给我的；除了父，没有人知道子；除了子和子所愿意启示的人，没有人知道父。","notes":[]},{"n":28,"t":"凡劳苦担重担的人都到我这里来，我要使你们得安息。","notes":[]},{"n":29,"t":"我心里柔和谦卑，你们当负我的轭，向我学习；这样，你们的心灵就必得安息。","notes":[]},{"n":30,"t":"因为我的轭是容易的，我的担子是轻省的。”","notes":[]}]},"12":{"heading":"在安息日摘麦穗","verses":[{"n":1,"t":"那时，耶稣在安息日从麦田经过。他的门徒饿了，就摘麦穗来吃。","notes":[]},{"n":2,"t":"法利赛人看见，对耶稣说：“看哪，你的门徒在安息日做不合法的事了。”","notes":[]},{"n":3,"t":"耶稣对他们说：“大卫和跟从他的人饥饿时所做的事，你们没有念过吗？","notes":[]},{"n":4,"t":"他怎么进了神的居所，吃了供饼呢？这饼是他和跟从他的人不可以吃的，惟独祭司才可以吃。","notes":[]},{"n":5,"t":"再者，律法上所记的，在安息日，祭司在圣殿里犯了安息日也不算有罪，你们没有念过吗？","notes":[]},{"n":6,"t":"但我告诉你们，比圣殿更大的在这里。","notes":[]},{"n":7,"t":"‘我喜爱怜悯，不喜爱祭祀。’你们若明白这话的意思，就不将无罪的当作有罪了。","notes":[]},{"n":8,"t":"因为人子是安息日的主。”","notes":[]},{"n":9,"t":"耶稣离开那地方，进了犹太人的会堂；","notes":[],"heads":["治好萎缩了的手"]},{"n":10,"t":"那里有个一只手萎缩了的人。有人为了要控告耶稣，就问他：“安息日治病合不合法？”","notes":[]},{"n":11,"t":"耶稣对他们说：“你们中间谁有一只羊在安息日掉在坑里，不抓住它，把它拉上来呢？","notes":[]},{"n":12,"t":"人比羊贵重得多了！所以，在安息日做善事是合法的。”","notes":[]},{"n":13,"t":"于是对那人说：“伸出手来！”他把手一伸，手就复原了，和另一只一样。","notes":[]},{"n":14,"t":"法利赛人出去，商议怎样除掉耶稣。","notes":[]},{"n":15,"t":"耶稣知道了，就离开那里，有一大群人跟着他。他把所有的病人都治好了，","notes":[],"heads":["神所拣选的仆人"]},{"n":16,"t":"又嘱咐他们不要把他宣扬出去。","notes":[]},{"n":17,"t":"这是要应验以赛亚先知所说的话：","notes":[]},{"n":18,"t":"“看哪，我所拣选的仆人，我所亲爱，心所喜悦的；我要将我的灵赐给他，他必将公理传给外邦。","notes":[]},{"n":19,"t":"他不争吵，不喧嚷，街上也没有人听见他的声音。","notes":[]},{"n":20,"t":"压伤的芦苇，他不折断，将残的灯火，他不吹灭，直到他使公理得胜。","notes":[]},{"n":21,"t":"外邦人都要仰望他的名。”","notes":[]},{"n":22,"t":"当时，有人把一个被鬼附，又盲又哑的人带到耶稣那里，耶稣医治他，那哑巴就能说话，又能看见。","notes":[],"heads":["诬蔑耶稣为别西卜"]},{"n":23,"t":"众人都惊奇，说：“这不是大卫之子吗？”","notes":[]},{"n":24,"t":"但法利赛人听见，就说：“这个人赶鬼，无非是靠着鬼王别西卜罢了。”","notes":[]},{"n":25,"t":"耶稣知道他们的心思，就对他们说：“一国自相纷争，必定荒芜；一城一家自相纷争，必立不住。","notes":[]},{"n":26,"t":"若撒但赶出撒但，就是自相纷争，他的国怎能立得住呢？","notes":[]},{"n":27,"t":"我若靠着别西卜赶鬼，你们的子弟赶鬼又靠着谁呢？这样，他们要作你们的判官。","notes":[]},{"n":28,"t":"我若靠着神的灵赶鬼，那么，神的国就已临到你们了。","notes":[]},{"n":29,"t":"人怎能进壮士家里抢夺他的东西呢？除非先绑住那壮士，否则无法抢夺他的家。","notes":[]},{"n":30,"t":"不跟我一起的，就是反对我；不与我一起收聚的，就是在拆散。","notes":[]},{"n":31,"t":"所以我告诉你们，人一切的罪和亵渎的话都可得赦免，但是亵渎圣灵，总不得赦免。","notes":[]},{"n":32,"t":"凡说话干犯人子的，还可得赦免；但是说话干犯圣灵的，今世来世总不得赦免。”","notes":[]},{"n":33,"t":"“你们知道树好，果子也好；又知道树坏，果子也坏；因为看果子就可以知道树。","notes":[],"heads":["树和果子"]},{"n":34,"t":"毒蛇的孽种啊，你们既是恶人，怎能说出好话来呢？因为心里所充满的，口里就说出来。","notes":[]},{"n":35,"t":"善人从他所存的善发出善来；恶人从他所存的恶发出恶来。","notes":[]},{"n":36,"t":"我告诉你们，凡是人所说的闲话，在审判的日子，要句句供出来；","notes":[]},{"n":37,"t":"因为要凭你的话定你为义，也要凭你的话定你有罪。”","notes":[]},{"n":38,"t":"当时，有几个文士和法利赛人对耶稣说：“老师，我们想请你显个神迹给我们看看。”","notes":[],"heads":["求神迹"]},{"n":39,"t":"耶稣回答他们：“邪恶淫乱的世代求看神迹，除了先知约拿的神迹以外，再没有神迹给他们看了。","notes":[]},{"n":40,"t":"约拿三日三夜在大鱼肚腹中，同样，人子也要三日三夜在地里面。","notes":[]},{"n":41,"t":"在审判的时候，尼尼微人要起来定这世代的罪，因为尼尼微人听了约拿所传的就悔改了。看哪，比约拿更大的在这里！","notes":[]},{"n":42,"t":"在审判的时候，南方的女王要起来定这世代的罪，因为她从地极而来，要听所罗门智慧的话。看哪，比所罗门更大的在这里！”","notes":[]},{"n":43,"t":"“污灵离了人身，走遍无水之地寻找安歇之处，却找不到。","notes":[],"heads":["污灵回来"]},{"n":44,"t":"于是他说：‘我要回到我原来的屋里去。’他到了，看见里面空着，打扫干净，修饰好了，","notes":[]},{"n":45,"t":"就去另带了七个比自己更恶的灵来，都进去住在那里。那人后来的景况比先前更坏了。这邪恶的世代也要如此。”","notes":[]},{"n":46,"t":"耶稣还在对众人说话的时候，不料，他母亲和他兄弟站在外边想要跟他说话。","notes":[],"heads":["遵父旨意的人都是亲属"]},{"n":47,"t":"有人告诉他：“看哪！你母亲和你兄弟站在外边，想要跟你说话。”","notes":["有古卷没有47节。"]},{"n":48,"t":"他却回答那对他说话的人，说：“谁是我的母亲？谁是我的兄弟？”","notes":[]},{"n":49,"t":"于是他伸手指着门徒，说：“看哪，我的母亲，我的兄弟！","notes":[]},{"n":50,"t":"凡遵行我天父旨意的人就是我的兄弟、姊妹和母亲。”","notes":[]}]},"13":{"heading":"撒种的比喻","verses":[{"n":1,"t":"就在那天，耶稣从房子里出来，坐在海边。","notes":[]},{"n":2,"t":"有一大群人到他那里聚集，他只好上船坐下，众人都站在岸上。","notes":[]},{"n":3,"t":"他用比喻对他们讲了许多话。他说：“有一个撒种的出去撒种。","notes":[]},{"n":4,"t":"他撒的时候，有的落在路旁，飞鸟来把它们吃掉了。","notes":[]},{"n":5,"t":"有的落在土浅的石头地上，因为土不深，很快就长出苗来，","notes":[]},{"n":6,"t":"太阳出来一晒，因为没有根就枯干了。","notes":[]},{"n":7,"t":"有的落在荆棘里，荆棘长起来，把它挤住了。","notes":[]},{"n":8,"t":"又有的落在好土里，就结出果实，有一百倍的，有六十倍的，有三十倍的。","notes":[]},{"n":9,"t":"有耳的，就应当听！”","notes":[]},{"n":10,"t":"门徒进前来问耶稣：“对众人讲话，为什么用比喻呢？”","notes":[],"heads":["用比喻的目的"]},{"n":11,"t":"耶稣回答他们说：“因为天国的奥秘只让你们知道，不让他们知道。","notes":[]},{"n":12,"t":"凡有的，还要给他，让他有余；凡没有的，连他所有的也要夺去。","notes":[]},{"n":13,"t":"我之所以用比喻对他们讲，是因为他们看却看不清，听却听不见，也不明白。","notes":[]},{"n":14,"t":"在他们身上，正应验了以赛亚的预言：‘你们听了又听，却不明白，看了又看，却看不清。","notes":[]},{"n":15,"t":"因为这百姓的心麻木，耳朵发沉，眼睛闭着，免得眼睛看见，耳朵听见，心里明白，回转过来，我会医治他们。’","notes":[]},{"n":16,"t":"但你们的眼睛是有福的，因为看得见；你们的耳朵也是有福的，因为听得见。","notes":[]},{"n":17,"t":"我实在告诉你们，从前有许多先知和义人要看你们所看的，却没有看见；要听你们所听的，却没有听见。”","notes":[]},{"n":18,"t":"“所以，你们要听这撒种的比喻。","notes":[],"heads":["解释撒种的比喻"]},{"n":19,"t":"凡听见天国的道而不明白的，那恶者就来，把撒在他心里的夺了去；这就是撒在路旁的了。","notes":[]},{"n":20,"t":"撒在石头地上的，就是人听了道，立刻欢喜领受，","notes":[]},{"n":21,"t":"只因心里没有根，不过是暂时的，一旦为道遭受患难或迫害，立刻就跌倒。","notes":[]},{"n":22,"t":"撒在荆棘里的，就是人听了道，后来有世上的忧虑、钱财的迷惑把道挤住了，结不出果实。","notes":[]},{"n":23,"t":"撒在好土里的，就是人听了道，明白了，后来结了果实，有一百倍的，有六十倍的，有三十倍的。”","notes":[]},{"n":24,"t":"耶稣又设个比喻对他们说：“天国好比人撒好种在田里，","notes":[],"heads":["杂草的比喻"]},{"n":25,"t":"在人睡觉的时候，他的仇敌来，把杂草撒在麦子里就走了。","notes":[]},{"n":26,"t":"到长苗吐穗的时候，杂草也显出来。","notes":[]},{"n":27,"t":"地主的仆人进前来对他说：‘主人，你不是撒好种在田里吗？哪里来的杂草呢？’","notes":[]},{"n":28,"t":"主人回答他们：‘这是仇敌做的。’仆人对他说：‘你要我们去拔掉吗？’","notes":[]},{"n":29,"t":"主人说：‘不必，恐怕拔杂草，也把麦子连根拔出来。","notes":[]},{"n":30,"t":"让这两样一起长，等到收割。当收割的时候，我会对收割的人说，先把杂草拔出来，捆成捆，留着烧，把麦子收在我的仓里。’”","notes":[]},{"n":31,"t":"他又设个比喻对他们说：“天国好比一粒芥菜种，有人拿去种在田里。","notes":[],"heads":["芥菜种和面酵的比喻"]},{"n":32,"t":"它原比所有的种子都小，等到长起来，却比各样的菜都大，且成了树，以致天上的飞鸟来在它的枝上筑巢。”","notes":[]},{"n":33,"t":"他又对他们讲另一个比喻：“天国好比面酵，有妇人拿来放进三斗面里，直到全团都发起来。”","notes":[]},{"n":34,"t":"这都是耶稣用比喻对众人说的话，不用比喻，他就不对他们说什么。","notes":[],"heads":["用比喻的原因"]},{"n":35,"t":"这是要应验先知所说的话：“我要开口说比喻，说出从创世以来所隐藏的事。”","notes":["有古卷加“以赛亚”。"]},{"n":36,"t":"当时，耶稣离开众人，进了屋子。他的门徒进前来，说：“请把田间杂草的比喻讲给我们听。”","notes":[],"heads":["解释杂草的比喻"]},{"n":37,"t":"他回答：“那撒好种的就是人子，","notes":[]},{"n":38,"t":"田地就是世界，好种就是天国之子，杂草就是那恶者之子，","notes":[]},{"n":39,"t":"撒杂草的仇敌就是魔鬼，收割的时候就是世代的终结，收割的人就是天使。","notes":[]},{"n":40,"t":"正如把杂草拔出来用火焚烧，世代的终结也要如此。","notes":[]},{"n":41,"t":"人子要差遣他的使者，把一切使人跌倒的和作恶的从他国里挑出来，","notes":[]},{"n":42,"t":"丢在火炉里，在那里要哀哭切齿了。","notes":[]},{"n":43,"t":"那时，义人要在他们父的国里发出光来，像太阳一样。有耳的，就应当听！”","notes":[]},{"n":44,"t":"“天国好比宝贝藏在地里，人发现了就把它藏起来，欢欢喜喜地去变卖一切所有的，买这块地。","notes":[],"heads":["藏宝和寻珠的比喻"]},{"n":45,"t":"“天国又好比商人寻找好的珍珠，","notes":[]},{"n":46,"t":"发现一颗贵重的珍珠，就去变卖他一切所有的，买下这颗珍珠。”","notes":[]},{"n":47,"t":"“天国又好比网撒在海里，聚拢各种鱼类，","notes":[],"heads":["撒网的比喻"]},{"n":48,"t":"网一满，人们就把它拉上岸，坐下来，拣好的收在桶里，不好的丢掉。","notes":[]},{"n":49,"t":"世代的终结也要这样：天使要出来，把恶人从义人中分别出来，","notes":[]},{"n":50,"t":"丢在火炉里，在那里要哀哭切齿了。”","notes":[]},{"n":51,"t":"耶稣说：“这一切的话你们都明白了吗？”他们对他说：“明白了。”","notes":[],"heads":["新旧库藏"]},{"n":52,"t":"他对他们说：“凡文士学习作天国的门徒，就像一个家的主人从他库里拿出新的和旧的东西来。”","notes":[]},{"n":53,"t":"耶稣说完了这些比喻，就离开那里，","notes":[],"heads":["拿撒勒人厌弃耶稣"]},{"n":54,"t":"来到自己的家乡，在会堂里教导人，以致他们都很惊奇，说：“这人哪来这样的智慧和异能呢？","notes":[]},{"n":55,"t":"这不是那木匠的儿子吗？他母亲不是叫马利亚吗？他兄弟们不是叫雅各、约瑟、西门、犹大吗？","notes":["“约瑟”：有古卷是“约西”。"]},{"n":56,"t":"他姊妹们不是都在我们这里吗？他这一切是从哪里来的呢？”","notes":[]},{"n":57,"t":"他们就厌弃他。耶稣对他们说：“先知除了在本乡和自己的家之外，没有不被尊敬的。”","notes":[]},{"n":58,"t":"耶稣因为他们不信，没有在那里行很多异能。","notes":[]}]},"14":{"heading":"施洗约翰之死","verses":[{"n":1,"t":"那时，希律分封王听见耶稣的名声，","notes":[]},{"n":2,"t":"就对臣仆说：“这是施洗的约翰从死人中复活，因此才有这些异能在他里面运行。”","notes":[]},{"n":3,"t":"原来，希律为他兄弟腓力的妻子希罗底的缘故，把约翰抓住绑了，关进监狱，","notes":[]},{"n":4,"t":"因为约翰曾对他说：“你占有这妇人是不合法的。”","notes":[]},{"n":5,"t":"希律就想要杀他，可是怕民众，因为他们认为约翰是先知。","notes":[]},{"n":6,"t":"到了希律的生日，希罗底的女儿在众人面前跳舞，使希律欢喜，","notes":[]},{"n":7,"t":"于是希律发誓许诺随她所求的给她。","notes":[]},{"n":8,"t":"女儿被母亲指使，就说：“请把施洗约翰的头放在盘子里，拿来给我。”","notes":[]},{"n":9,"t":"王就忧愁，然而因他所发的誓，又因同席的人，就下令给她；","notes":[]},{"n":10,"t":"于是打发人去，在监狱里斩了约翰，","notes":[]},{"n":11,"t":"把头放在盘子里，拿来给那女孩，她拿去给她母亲。","notes":[]},{"n":12,"t":"约翰的门徒来，把尸体领去埋葬了，又去告诉耶稣。","notes":[]},{"n":13,"t":"耶稣听到了，就从那里上船，私下退到荒野的地方去。众人听到后，从各城来，步行跟随他。","notes":[],"heads":["耶稣使五千人吃饱"]},{"n":14,"t":"耶稣出来，见有一大群人，就怜悯他们，治好了他们的病人。","notes":[]},{"n":15,"t":"傍晚的时候，门徒进前来，说：“这地方偏僻，而且时候已经晚了，请叫众人散去，他们好进村子，自己买些食物。”","notes":[]},{"n":16,"t":"耶稣对他们说：“不用他们去，你们给他们吃吧！”","notes":[]},{"n":17,"t":"门徒说：“我们这里只有五个饼、两条鱼。”","notes":[]},{"n":18,"t":"耶稣说：“拿过来给我。”","notes":[]},{"n":19,"t":"于是他吩咐众人坐在草地上，就拿着这五个饼和两条鱼，望着天祝福，擘开饼，递给门徒，门徒又递给众人。","notes":[]},{"n":20,"t":"他们都吃，并且吃饱了。门徒把剩下的碎屑收拾起来，装满了十二个篮子。","notes":[]},{"n":21,"t":"吃的人中，男的约有五千，还不算妇女和孩子。","notes":[]},{"n":22,"t":"耶稣随即催门徒上船，先渡到对岸，等他叫众人散去。","notes":[],"heads":["耶稣在海上行走"]},{"n":23,"t":"疏散了众人以后，他独自上山去祷告。到了晚上，只有他一人在那里。","notes":[]},{"n":24,"t":"那时船已离岸好几里 ，因风不顺，被浪颠簸。","notes":["“里”：原文是“斯他迪”，古希腊长度单位；参“度量衡表”。","“已离岸好几里”：有古卷是“正在海中”。"]},{"n":25,"t":"天快亮的时候，耶稣在海面上走，往门徒那里去。","notes":[]},{"n":26,"t":"但门徒看见他在海面上走，就惊慌了，说：“是个鬼怪！”他们害怕得喊叫起来。","notes":[]},{"n":27,"t":"耶稣连忙对他们说：“放心！是我，不要怕！”","notes":[]},{"n":28,"t":"彼得回答他说：“主啊，如果是你，请叫我从水面上走到你那里去。”","notes":[]},{"n":29,"t":"耶稣说：“你来吧！”彼得就从船上下去，在水面上走，往耶稣那里去；","notes":[]},{"n":30,"t":"只因见风很强，害怕起来，将要沉下去，就喊着说：“主啊，救我！”","notes":["“风很强”：有古卷没有“很强”；另有古卷是“风势非常猛烈”。"]},{"n":31,"t":"耶稣立刻伸手拉住他，说：“你这小信的人哪，为什么疑惑呢？”","notes":[]},{"n":32,"t":"他们一上船，风就停了。","notes":[]},{"n":33,"t":"在船上的人都拜他，说：“你真是神的儿子。”","notes":[]},{"n":34,"t":"他们渡过了海，在革尼撒勒上岸。","notes":[],"heads":["治好革尼撒勒的病人"]},{"n":35,"t":"那里的人认出耶稣，就打发人到整个周围地区去，把所有的病人带到他那里，","notes":[]},{"n":36,"t":"求耶稣让他们只摸一摸他的衣裳繸子，摸着的人就都好了。","notes":[]}]},"15":{"heading":"论古人的传统","verses":[{"n":1,"t":"那时，有法利赛人和文士从耶路撒冷来见耶稣，说：","notes":[]},{"n":2,"t":"“你的门徒为什么违反古人的传统？因为他们吃饭的时候不洗手。”","notes":[]},{"n":3,"t":"耶稣回答他们：“你们为什么因你们的传统而违反神的诫命呢？","notes":[]},{"n":4,"t":"神说：‘当孝敬父母’；又说：‘咒骂父母的，必须处死。’","notes":[]},{"n":5,"t":"你们倒说：‘无论谁对父母说：我所当供奉你的已经作了奉献，","notes":[]},{"n":6,"t":"就可以不孝敬他的父亲。’这就是你们藉着传统，废了神的话。","notes":["有古卷是“他的父母”。"]},{"n":7,"t":"假冒为善的人哪！以赛亚指着你们所预言的说得好：","notes":[]},{"n":8,"t":"‘这百姓用嘴唇尊敬我，他们的心却远离我。","notes":[]},{"n":9,"t":"他们把人的规条当作教义教导人；他们拜我也是枉然。’”","notes":[]},{"n":10,"t":"耶稣叫了众人来，对他们说：“你们要听，也要明白。","notes":[]},{"n":11,"t":"从口里进去的不玷污人，从口里出来的才玷污人。”","notes":[]},{"n":12,"t":"当时，门徒进前来对他说：“法利赛人听见这话很反感，你知道吗？”","notes":[]},{"n":13,"t":"耶稣回答：“一切植物，若不是我天父栽植的，都要连根拔出来。","notes":[]},{"n":14,"t":"由他们吧！他们是瞎子作瞎子的向导；若是瞎子领瞎子，两个人都要掉在坑里。”","notes":["有古卷是“他们是瞎子作向导”。"]},{"n":15,"t":"彼得回应他说：“请将这比喻讲解给我们听。”","notes":[]},{"n":16,"t":"耶稣说：“连你们也还不明白吗？","notes":[]},{"n":17,"t":"难道你们不了解，凡进到口里的，是经过肚子，又排入厕所吗？","notes":[]},{"n":18,"t":"然而口里出来的是出于心里，这才玷污人。","notes":[]},{"n":19,"t":"因为出于心里的有种种恶念，如凶杀、奸淫、淫乱、偷盗、伪证、毁谤。","notes":[]},{"n":20,"t":"这些才玷污人。至于不洗手吃饭，那并不玷污人。”","notes":[]},{"n":21,"t":"耶稣离开那里，退到推罗、西顿境内。","notes":[],"heads":["迦南妇人的信心"]},{"n":22,"t":"有一个迦南妇人从那地方出来，喊着说：“主啊，大卫之子，可怜我！我女儿被鬼缠得很苦。”","notes":[]},{"n":23,"t":"耶稣却一言不答。门徒进前来，求他说：“这妇人在我们后头喊叫，请打发她走吧。”","notes":[]},{"n":24,"t":"耶稣回答：“我奉差遣只到以色列家迷失的羊那里去。”","notes":[]},{"n":25,"t":"那妇人来拜他，说：“主啊，帮帮我！”","notes":[]},{"n":26,"t":"他回答：“拿孩子的饼丢给小狗吃是不妥的。”","notes":[]},{"n":27,"t":"妇人说：“主啊，不错，可是小狗也吃它主人桌上掉下来的碎屑。”","notes":[]},{"n":28,"t":"于是耶稣回答她说：“妇人，你的信心很大！照你所要的成全你吧。”从那时起，她的女儿就好了。","notes":[]},{"n":29,"t":"耶稣离开那地方，来到靠近加利利的海边，就上山坐下。","notes":[],"heads":["治好许多病人"]},{"n":30,"t":"有一大群人到他那里，带着瘸子、盲人、肢残的、聋哑的，和好些别的病人，都放在他脚前，他就治好了他们。","notes":[]},{"n":31,"t":"于是众人都惊讶，因为看见聋哑的说话，肢残的痊愈，瘸子行走，盲人看见，他们就归荣耀给以色列的神。","notes":[]},{"n":32,"t":"耶稣叫门徒来，说：“我怜悯这群人，因为他们同我在这里已经三天，没有吃的东西了。我不愿意叫他们饿着回去，恐怕他们在路上饿昏了。”","notes":[],"heads":["耶稣使四千人吃饱"]},{"n":33,"t":"门徒说：“我们在这野地，哪里有这么多的饼让这许多人吃饱呢？”","notes":[]},{"n":34,"t":"耶稣对他们说：“你们有多少饼？”他们说：“有七个，还有几条小鱼。”","notes":[]},{"n":35,"t":"他就吩咐众人坐在地上，","notes":[]},{"n":36,"t":"拿着这七个饼和几条鱼，祝谢了，擘开，递给门徒；门徒又递给众人。","notes":[]},{"n":37,"t":"他们都吃，并且吃饱了，收拾剩下的碎屑，装满了七个筐子。","notes":[]},{"n":38,"t":"吃的人中，男的有四千，还不算妇女和孩子。","notes":[]},{"n":39,"t":"耶稣叫众人散去，就上船，来到马加丹境内。","notes":["“马加丹”：有古卷是“抹大拉”。"]}]},"16":{"heading":"求神迹","verses":[{"n":1,"t":"法利赛人和撒都该人来试探耶稣，请他显个来自天上的神迹给他们看。","notes":[]},{"n":2,"t":"耶稣回答他们：“傍晚天发红，你们就说：‘明日天晴。’","notes":[]},{"n":3,"t":"早晨天色又红又暗，你们就说：‘今日有风雨。’你们知道分辨天上的气象，倒不能分辨这个时代的神迹。","notes":["有古卷没有“傍晚…神迹”。"]},{"n":4,"t":"邪恶淫乱的世代求看神迹，除了约拿的神迹以外，再没有神迹给他们看了。”于是耶稣离开他们走了。","notes":[]},{"n":5,"t":"门徒渡到对岸，忘了带饼。","notes":[],"heads":["防备法利赛人和撒都该人的酵"]},{"n":6,"t":"耶稣对他们说：“你们要谨慎，要防备法利赛人和撒都该人的酵。”","notes":[]},{"n":7,"t":"门徒彼此议论说：“这是因为我们没有带饼吧。”","notes":[]},{"n":8,"t":"耶稣知道了，就说：“你们这小信的人，为什么因为没有饼就彼此议论呢？","notes":[]},{"n":9,"t":"你们还不明白吗？不记得那五个饼分给五千人，你们收拾了多少篮子的碎屑吗？","notes":[]},{"n":10,"t":"也不记得那七个饼分给四千人，你们又收拾了多少筐子的碎屑吗？","notes":[]},{"n":11,"t":"我对你们说‘要防备法利赛人和撒都该人的酵’，这话不是指着饼说的，你们怎么不明白呢？”","notes":[]},{"n":12,"t":"门徒这才明白他所说的不是要他们防备饼的酵，而是要防备法利赛人和撒都该人的教训。","notes":["“防备饼的酵”：有古卷是“防备法利赛人和撒都该人的酵”。"]},{"n":13,"t":"耶稣到了凯撒利亚．腓立比的境内，就问门徒：“人们说人子是谁？”","notes":[],"heads":["彼得认耶稣为基督"]},{"n":14,"t":"他们说：“有人说是施洗的约翰；有人说是以利亚；又有人说是耶利米或是先知中的一位。”","notes":[]},{"n":15,"t":"耶稣问他们：“你们说我是谁？”","notes":[]},{"n":16,"t":"西门．彼得回答说：“你是基督，是永生神的儿子。”","notes":[]},{"n":17,"t":"耶稣回答他说：“约拿的儿子西门，你是有福的！因为这不是属血肉的启示你的，而是我在天上的父启示的。","notes":[]},{"n":18,"t":"我还告诉你，你是彼得，我要把我的教会建造在这磐石上，阴间的权柄不能胜过它。","notes":["“彼得”：原文的意思是“磐石”。"]},{"n":19,"t":"我要把天国的钥匙给你，凡你在地上所捆绑的，在天上也要捆绑；凡你在地上所释放的，在天上也要释放。”","notes":[]},{"n":20,"t":"当时，耶稣嘱咐门徒不可对任何人说他是基督。","notes":[]},{"n":21,"t":"从那时起，耶稣才向门徒明说，他必须上耶路撒冷去，受长老、祭司长和文士许多的苦，并且被杀，第三天复活。","notes":[],"heads":["耶稣预言受难和复活"]},{"n":22,"t":"彼得就拉着他，责备他说：“主啊，千万不可如此！这事绝不可临到你身上。”","notes":[]},{"n":23,"t":"耶稣转过来，对彼得说：“撒但，退到我后边去！你是我的绊脚石，因为你不体会神的心意，而是体会人的意思。”","notes":[]},{"n":24,"t":"于是耶稣对门徒说：“若有人要跟从我，就当舍己，背起自己的十字架来跟从我。","notes":[]},{"n":25,"t":"因为凡要救自己生命的，要丧失生命；凡为我丧失生命的，要得着生命。","notes":[]},{"n":26,"t":"人若赚得全世界，赔上自己的生命，有什么益处呢？人还能拿什么换生命呢？","notes":[]},{"n":27,"t":"人子要在他父的荣耀里与他的众使者一起来临，那时候，他要照各人的行为报应各人。","notes":[]},{"n":28,"t":"我实在告诉你们，站在这里的，有人在没经历死亡以前，必定看见人子来到他的国里。”","notes":[]}]},"17":{"heading":"耶稣登山显荣","verses":[{"n":1,"t":"过了六天，耶稣带着彼得、雅各和雅各的弟弟约翰，领他们悄悄地上了高山。","notes":[]},{"n":2,"t":"他在他们面前变了形像，他的脸明亮如太阳，衣裳洁白如光。","notes":[]},{"n":3,"t":"忽然，有摩西和以利亚向他们显现，与耶稣说话。","notes":[]},{"n":4,"t":"彼得回应，对耶稣说：“主啊，我们在这里真好！你若愿意，我就在这里搭三座棚，一座为你，一座为摩西 ，一座为以利亚。”","notes":[]},{"n":5,"t":"说话之间，忽然有一朵明亮的云彩遮盖他们，又有声音从云彩里出来，说：“这是我的爱子，我所喜爱的。你们要听从他！”","notes":[]},{"n":6,"t":"门徒听见，就俯伏在地，极其害怕。","notes":[]},{"n":7,"t":"耶稣进前来，拍拍他们，说：“起来，不要害怕！”","notes":[]},{"n":8,"t":"他们举目，不见一人，只见耶稣独自一人。","notes":[]},{"n":9,"t":"下山的时候，耶稣嘱咐他们说：“人子还没有从死人中复活，你们不要把所看到的告诉人。”","notes":[]},{"n":10,"t":"门徒问耶稣：“那么，文士为什么说以利亚必须先来？”","notes":[]},{"n":11,"t":"耶稣回答：“以利亚的确要来，并要复兴万事；","notes":[]},{"n":12,"t":"可是我告诉你们，以利亚已经来了，人不认识他，反倒任意待他。人子也将这样受他们的苦。”","notes":[]},{"n":13,"t":"门徒这才明白耶稣所说的是指施洗的约翰。","notes":[]},{"n":14,"t":"耶稣和门徒到了众人那里，有一个人来见耶稣，跪下，","notes":[],"heads":["治好被鬼附的孩子"]},{"n":15,"t":"说：“主啊，可怜我的儿子。他害癫痫病很苦，屡次跌进火里，屡次跌进水里。","notes":[]},{"n":16,"t":"我带他到你门徒那里，他们却不能医治他。”","notes":[]},{"n":17,"t":"耶稣回答：“唉！这又不信又悖谬的世代啊，我和你们在一起要到几时呢？我忍耐你们要到几时呢？把他带到我这里来！”","notes":[]},{"n":18,"t":"耶稣斥责那鬼，鬼就出来；从那时起，孩子就痊愈了。","notes":[]},{"n":19,"t":"门徒私下进前来问耶稣：“我们为什么不能赶出那鬼呢？”","notes":[]},{"n":20,"t":"耶稣对他们说：“是因你们的信心小。我实在告诉你们，你们若有信心像一粒芥菜种，就是对这座山说：‘你从这边移到那边’，它也会移过去，并且你们没有一件不能做的事了。”","notes":["有古卷加“21 至于这一类的鬼，若不祷告禁食，他就不出来。”"]},{"n":22,"t":"他们聚集在加利利的时候，耶稣对门徒说：“人子将要被交在人手里。","notes":[],"heads":["耶稣第二次预言受难和复活"]},{"n":23,"t":"他们要杀害他，第三天他要复活。”门徒就非常忧愁。","notes":[]},{"n":24,"t":"他们到了迦百农，收圣殿税的人来见彼得，说：“你们的老师不纳圣殿税吗？”","notes":["“圣殿税”：原文是“二德拉克马”，或译“丁税”，即半块钱；参“度量衡表”。"],"heads":["缴纳圣殿税"]},{"n":25,"t":"彼得说：“纳。”他进了屋子，耶稣先对他说：“西门，你的意见如何？世上的君王向谁征收关税或丁税？是向自己的儿子呢？还是向外人呢？”","notes":[]},{"n":26,"t":"彼得说：“是向外人。”耶稣对他说：“既然如此，儿子就可以免了。","notes":[]},{"n":27,"t":"但恐怕触犯他们，你往海边去钓鱼，把先钓上来的鱼拿起来，开了它的口，会发现一个司塔特，可以拿去给他们，作你我的税钱。”","notes":["“司塔特”：古罗马银币；参“度量衡表”。"]}]},"18":{"heading":"天国里谁最大","verses":[{"n":1,"t":"当时，门徒前来问耶稣：“天国里谁是最大的？”","notes":[]},{"n":2,"t":"耶稣叫一个小孩子来，让他站在他们当中，","notes":[]},{"n":3,"t":"说：“我实在告诉你们，你们若不回转，变成像小孩子一样，绝不能进天国。","notes":[]},{"n":4,"t":"所以，凡自己谦卑像这小孩子的，他在天国里就是最大的。","notes":[]},{"n":5,"t":"凡为我的名接纳一个像这小孩子的，就是接纳我。”","notes":[]},{"n":6,"t":"“凡使这些信我的小子中的一个跌倒的，倒不如把大磨石拴在这人的颈项上，沉在深海里。","notes":[],"heads":["拒绝罪的诱惑"]},{"n":7,"t":"这世界有祸了，因为它使人跌倒；绊倒人的事是免不了的，但那绊倒人的有祸了！","notes":[]},{"n":8,"t":"如果你一只手或是一只脚使你跌倒，就把它砍下来扔掉。你缺一只手或是一只脚进入永生，比有两手两脚被扔进永火里还好。","notes":[]},{"n":9,"t":"如果你一只眼使你跌倒，就把它挖出来扔掉。你只有一只眼进入永生，比有两只眼被扔进地狱的火里还好。”","notes":[]},{"n":10,"t":"“你们要小心，不可轻看这些小子中的一个；我告诉你们，他们的天使在天上，常见我天父的面。","notes":["有古卷加“11 人子来，为要拯救失丧的人。”"],"heads":["迷羊的比喻"]},{"n":12,"t":"“一个人若有一百只羊，其中一只走迷了路，你们的意见如何？他岂不留下这九十九只在山上，去找那只迷路的羊吗？","notes":[]},{"n":13,"t":"若是找到了，我实在告诉你们，他为这一只羊欢喜，比为那没有迷路的九十九只欢喜还大呢！","notes":[]},{"n":14,"t":"你们在天上的父也是这样，不愿意失去这些小子中的一个。”","notes":["有古卷是“我”。"]},{"n":15,"t":"“若是你的弟兄得罪你，你要去，趁着只有他和你在一起的时候，指出他的错来。他若听你，你就赢得了你的弟兄；","notes":["“得罪你”：有古卷是“犯罪”。"],"heads":["如何对待有过错的弟兄"]},{"n":16,"t":"他若不听，你就另外带一个或两个人同去，因为‘任何指控都要凭两个或三个证人的口述才能成立’。","notes":[]},{"n":17,"t":"他若是不听他们，就去告诉教会；若是不听教会，就把他看作外邦人和税吏。","notes":[]},{"n":18,"t":"“我实在告诉你们，凡你们在地上所捆绑的，在天上也要捆绑；凡你们在地上所释放的，在天上也要释放。","notes":[]},{"n":19,"t":"我又实在告诉你们，若是你们中间有两个人在地上同心合意地求什么事，我在天上的父必为他们成全。","notes":["有古卷没有“实在”。"]},{"n":20,"t":"因为，哪里有两三个人奉我的名聚会，哪里就有我在他们中间。”","notes":[]},{"n":21,"t":"那时，彼得进前来，对耶稣说：“主啊，我弟兄得罪我，我当饶恕他几次呢？到七次够吗？”","notes":[],"heads":["不饶恕人的恶仆"]},{"n":22,"t":"耶稣说：“我告诉你，不是到七次，而是到七十个七次。","notes":[]},{"n":23,"t":"因为天国好像一个王要和他仆人算账。","notes":[]},{"n":24,"t":"他开始算的时候，有人带了一个欠一万他连得的仆人来。","notes":[]},{"n":25,"t":"因为他没有什么偿还之物，主人下令把他和他妻子儿女，以及一切所有的都卖了来偿还。","notes":[]},{"n":26,"t":"那仆人就俯伏向他叩头，说：‘宽容我吧，我都会还你的。’","notes":[]},{"n":27,"t":"那仆人的主人就动了慈心，把他释放了，并且免了他的债。","notes":[]},{"n":28,"t":"那仆人出来，遇见一个欠他一百个银币的同伴，就揪着他，扼住他的喉咙，说：‘把你所欠的还我！’","notes":[]},{"n":29,"t":"他的同伴就俯伏央求他，说：‘宽容我吧，我会还你的。’","notes":[]},{"n":30,"t":"他不肯，却把他下在监里，直到他还了所欠的债。","notes":[]},{"n":31,"t":"同伴们看见他所做的事就很悲愤，把这一切的事都告诉了主人。","notes":[]},{"n":32,"t":"于是主人叫了他来，对他说：‘你这恶奴才！你央求我，我就把你所欠的都免了；","notes":[]},{"n":33,"t":"你不应该怜悯你的同伴，像我怜悯你吗？’","notes":[]},{"n":34,"t":"主人就大怒，把他交给司刑的，直到他还清了所欠的债。","notes":[]},{"n":35,"t":"你们各人若不从心里饶恕你的弟兄，我天父也要这样待你们。”","notes":[]}]},"19":{"heading":"休妻的问题","verses":[{"n":1,"t":"耶稣说完了这些话，就离开加利利，来到犹太的境内、约旦河的东边。","notes":[]},{"n":2,"t":"有一大群人跟着他，他就在那里治好了他们。","notes":[]},{"n":3,"t":"有些法利赛人来试探耶稣说：“无论什么缘故，人休妻都合法吗？”","notes":[]},{"n":4,"t":"耶稣回答：“那起初造人的，是造男造女，并且说：‘因此，人要离开父母，与妻子结合，二人成为一体。’这经文你们没有念过吗？","notes":[],"end":5},{"n":6,"t":"既然如此，夫妻不再是两个人，而是一体的了。所以，神配合的，人不可分开。”","notes":[]},{"n":7,"t":"法利赛人说：“这样，摩西为什么吩咐给妻子休书就可以休她呢？”","notes":[]},{"n":8,"t":"耶稣说：“摩西因为你们的心硬，所以准许你们休妻，但起初并不是这样。","notes":[]},{"n":9,"t":"我告诉你们，凡休妻另娶的，若不是为不贞的缘故，就是犯奸淫了。”","notes":["有古卷加“有人娶那被休的妇人，也是犯奸淫了。”"]},{"n":10,"t":"门徒对耶稣说：“丈夫和妻子的关系既是这样，倒不如不娶。”","notes":[]},{"n":11,"t":"耶稣对他们说：“这话不是人人都能领受的，惟独赐给谁，谁才能领受。","notes":[]},{"n":12,"t":"因为有人从母腹里就是不宜结婚的，也有因人为的缘故不宜结婚的，并有为天国的缘故自己不结婚的。这话谁能领受，就领受吧。”","notes":["“不宜结婚的”与“不结婚的”：原文直译“阉人”。"]},{"n":13,"t":"那时，有人带着小孩子来见耶稣，要他给他们按手祷告，门徒就责备那些人。","notes":[],"heads":["耶稣为小孩祝福"]},{"n":14,"t":"耶稣说：“让小孩子到我这里来，不要阻止他们，因为在天国的正是这样的人。”","notes":[]},{"n":15,"t":"耶稣给他们按手，然后离开那地方。","notes":[]},{"n":16,"t":"有一个人进前来问耶稣：“老师，我该做什么善事才能得永生？”","notes":[],"heads":["青年财主寻求永生"]},{"n":17,"t":"耶稣对他说：“你为什么问我关于善的事呢？只有一位是善良的。你若要进入永生，就该遵守诫命。”","notes":[]},{"n":18,"t":"他说：“哪些诫命？”耶稣说：“就是不可杀人；不可奸淫；不可偷盗；不可作假见证；","notes":[]},{"n":19,"t":"当孝敬父母；又当爱邻如己。”","notes":["“邻”也可译作“人”。"]},{"n":20,"t":"那青年说：“这一切我都遵守了，还缺少什么呢？”","notes":[]},{"n":21,"t":"耶稣说：“你若愿意作完全人，去变卖你所拥有的，分给穷人，就必有财宝在天上；然后来跟从我。”","notes":[]},{"n":22,"t":"那青年听见这话，就忧忧愁愁地走了，因为他的产业很多。","notes":[]},{"n":23,"t":"耶稣对门徒说：“我实在告诉你们，财主进天国是难的。","notes":[]},{"n":24,"t":"我再告诉你们，骆驼穿过针眼比财主进神的国还容易呢！”","notes":[]},{"n":25,"t":"门徒听见这话，就非常惊奇，说：“这样，谁能得救呢？”","notes":[]},{"n":26,"t":"耶稣看着他们，说：“在人这是不能，在神凡事都能。”","notes":[]},{"n":27,"t":"于是彼得回应，对他说：“看哪，我们已经撇下一切跟从你了，我们会得到什么呢？”","notes":[]},{"n":28,"t":"耶稣对他们说：“我实在告诉你们，你们这些跟从我的人，到了万物更新、人子坐在他荣耀宝座上的时候，你们也要坐在十二个宝座上，审判以色列十二个支派。","notes":[]},{"n":29,"t":"凡为我的名撇下房屋，或是兄弟、姊妹、父亲、母亲、儿女、田地的，将得着百倍，并且承受永生。","notes":["有古卷加“妻子”。"]},{"n":30,"t":"然而，有许多在前的，将要在后；在后的，将要在前。”","notes":[]}]},"20":{"heading":"在葡萄园做工的比喻","verses":[{"n":1,"t":"“因为天国好比一家的主人清早去雇人进他的葡萄园做工。","notes":[]},{"n":2,"t":"他和工人讲定一天一个银币，就打发他们进葡萄园去。","notes":["这是当时一日的工资。"]},{"n":3,"t":"约在上午九点钟出去，看见市场上还有闲站的人，","notes":[]},{"n":4,"t":"就对那些人说：‘你们也进葡萄园去，我会给你们合理的工钱。’","notes":[]},{"n":5,"t":"他们也进去了。约在正午和下午三点钟又出去，他也是这么做。","notes":[]},{"n":6,"t":"约在下午五点钟出去，他看见还有人站在那里，就问他们：‘你们为什么整天在这里闲站呢？’","notes":[]},{"n":7,"t":"他们说：‘因为没有人雇我们。’他说：‘你们也进葡萄园去。’","notes":[]},{"n":8,"t":"到了晚上，园主对工头说：‘叫工人都来，给他们工钱，从后来的起，到先来的为止。’","notes":[]},{"n":9,"t":"约在下午五点钟雇的人来了，各人领了一个银币。","notes":[]},{"n":10,"t":"那些最先雇的来了，以为可以多领，谁知也是各领一个银币。","notes":[]},{"n":11,"t":"他们领了工钱，就埋怨那家的主人说：","notes":[]},{"n":12,"t":"‘我们整天劳苦受热，那些后来的只做了一小时，你竟待他们和我们一样吗？’","notes":[]},{"n":13,"t":"主人回答其中的一人说：‘朋友，我没亏待你，你与我讲定的不是一个银币吗？","notes":[]},{"n":14,"t":"拿你的钱走吧！我乐意给那后来的和给你的一样，","notes":[]},{"n":15,"t":"难道我的东西不可随我的意思用吗？因为我作好人，你就眼红了吗？’","notes":[]},{"n":16,"t":"这样，那在后的，将要在前；在前的，将要在后了。”","notes":[]},{"n":17,"t":"耶稣上耶路撒冷去的时候，在路上把十二个门徒带到一边，对他们说：","notes":[],"heads":["耶稣第三次预言受难和复活"]},{"n":18,"t":"“看哪，我们上耶路撒冷去，人子将被交给祭司长和文士；他们要定他死罪，","notes":[]},{"n":19,"t":"把他交给外邦人戏弄，鞭打，钉在十字架上；第三天他要复活。”","notes":[]},{"n":20,"t":"那时，西庇太儿子的母亲和她两个儿子上前来，向耶稣叩头，求他一件事。","notes":[],"heads":["为首与为仆"]},{"n":21,"t":"耶稣问她：“你要什么呢？”她对耶稣说：“在你的国里，请让我这两个儿子一个坐在你右边，一个坐在你左边。”","notes":[]},{"n":22,"t":"耶稣回答：“你们不知道所求的是什么。我将要喝的杯，你们能喝吗？”他们对他说：“我们能。”","notes":[]},{"n":23,"t":"耶稣说：“我所喝的杯，你们要喝。可是坐在我的左右，不是我可以赐的，而是我父为谁预备就赐给谁。”","notes":[]},{"n":24,"t":"其余十个门徒听见，就对他们兄弟二人很生气。","notes":[]},{"n":25,"t":"耶稣叫了他们来，说：“你们知道，外邦人有君王作主治理他们，有大臣操权管辖他们。","notes":[]},{"n":26,"t":"但是在你们中间，不可这样。你们中间谁愿为大，就要作你们的用人；","notes":[]},{"n":27,"t":"谁愿为首，就要作你们的仆人。","notes":[]},{"n":28,"t":"正如人子来，不是要受人的服事，乃是要服事人，并且要舍命，作多人的赎价。”","notes":[]},{"n":29,"t":"他们出耶利哥的时候，有一大群人跟随耶稣。","notes":[],"heads":["治好两个盲人"]},{"n":30,"t":"有两个盲人坐在路旁，听说是耶稣经过，就喊着说：“主啊，大卫之子，可怜我们吧！”","notes":["有古卷没有“主啊”；另有古卷是“耶稣啊”。"]},{"n":31,"t":"众人责备他们，不许他们作声，他们却越发喊着说：“主啊，大卫之子，可怜我们吧！”","notes":["有古卷没有“主啊”。"]},{"n":32,"t":"耶稣就站住，叫他们来，说：“你们要我为你们做什么？”","notes":[]},{"n":33,"t":"他们说：“主啊，让我们的眼睛能看见。”","notes":[]},{"n":34,"t":"耶稣动了慈心，摸了他们的眼睛，他们立刻看得见，就跟从耶稣。","notes":[]}]},"21":{"heading":"荣入圣城","verses":[{"n":1,"t":"耶稣和门徒快到耶路撒冷，进了橄榄山的伯法其时，打发两个门徒，","notes":[]},{"n":2,"t":"对他们说：“你们往对面村子里去，会立刻看见一匹驴拴在那里，还有驴驹同在一处，解开它们，牵到我这里来。","notes":[]},{"n":3,"t":"若有人对你们说什么，你们就说：‘主要用它们。’那人会立刻让你们牵来。”","notes":[]},{"n":4,"t":"这事发生是要应验先知所说的话：","notes":[]},{"n":5,"t":"“要对锡安的儿女说：看哪，你的王来到你这里，谦和地骑着驴，骑着小驴—驴的驹子。”","notes":["“儿女”：原文直译“女儿”。"]},{"n":6,"t":"门徒就照耶稣所吩咐的去做，","notes":[]},{"n":7,"t":"牵了驴和驴驹来，把他们的衣服搭在上面，耶稣就骑上。","notes":[]},{"n":8,"t":"许许多多的人把自己的衣服铺在路上，还有人砍下树枝来铺在路上。","notes":[]},{"n":9,"t":"前呼后拥的人群喊着说：“和散那归于大卫之子！奉主名来的是应当称颂的！至高无上的，和散那！”","notes":["“和散那”：原是求救的意思，在此是称颂的话。"]},{"n":10,"t":"耶稣进了耶路撒冷，全城都惊动了，说：“这是谁？”","notes":[]},{"n":11,"t":"众人说：“这是从加利利的拿撒勒来的先知耶稣。”","notes":[]},{"n":12,"t":"耶稣进了圣殿，赶出圣殿里所有在做买卖的人，推倒兑换银钱之人的桌子和卖鸽子之人的凳子，","notes":["“圣殿”：有古卷是“神的殿”。"],"heads":["洁净圣殿"]},{"n":13,"t":"对他们说：“经上记着：‘我的殿要称为祷告的殿，你们倒使它成为贼窝了。’”","notes":[]},{"n":14,"t":"在圣殿里有盲人和瘸子到耶稣跟前，他就治好了他们。","notes":[]},{"n":15,"t":"祭司长和文士看见耶稣所行的奇事，又见小孩子在圣殿里喊着说：“和散那归于大卫之子！”就很生气，","notes":[]},{"n":16,"t":"对他说：“这些人所喊的，你听到了吗？”耶稣对他们说：“听到了。经上说：‘你藉孩童和吃奶的口发出完全的赞美’，你们没有念过吗？”","notes":[]},{"n":17,"t":"于是他离开他们，出城到伯大尼去，在那里过夜。","notes":[]},{"n":18,"t":"早晨回城的时候，他饿了，","notes":[],"heads":["诅咒无花果树"]},{"n":19,"t":"看见路旁有一棵无花果树，就走到跟前，在树上找不到什么，只有叶子，就对树说：“从今以后，你永不结果子！”那无花果树立刻枯干了。","notes":[]},{"n":20,"t":"门徒看见了，惊讶地说：“无花果树怎么立刻枯干了呢？”","notes":[]},{"n":21,"t":"耶稣回答他们：“我实在告诉你们，你们若有信心，不疑惑，不但能行我对无花果树所行的事，就是对这座山说：‘离开此地，投在海里！’也会实现。","notes":[]},{"n":22,"t":"你们祷告，无论求什么，只要信，就必得着。”","notes":[]},{"n":23,"t":"耶稣进了圣殿，正教导人的时候，祭司长和百姓的长老来问他：“你仗着什么权柄做这些事？给你这权柄的是谁呢？”","notes":[],"heads":["耶稣的权柄受到质问"]},{"n":24,"t":"耶稣回答他们说：“我也要问你们一句话，你们若告诉我，我就告诉你们我仗着什么权柄做这些事。","notes":[]},{"n":25,"t":"约翰的洗礼是从哪里来的？是从天上来的，还是从人间来的呢？”他们彼此商议说：“我们若说‘从天上来的’，他会对我们说：‘这样，你们为什么不信他呢？’","notes":[]},{"n":26,"t":"若说‘从人间来的’，我们又怕众人，因为大家都认为约翰是先知。”","notes":[]},{"n":27,"t":"于是他们回答耶稣：“我们不知道。”耶稣也对他们说：“我也不告诉你们，我仗着什么权柄做这些事。”","notes":[]},{"n":28,"t":"“有一件事，你们的意见如何？一个人有两个儿子。他来对大儿子说：‘孩子，今天到葡萄园里做工去。’","notes":[],"heads":["两个儿子的比喻"]},{"n":29,"t":"他回答：‘我不去’，以后自己懊悔，就去了。","notes":[]},{"n":30,"t":"他来对小儿子也是这样说。他回答：‘父亲大人，我去’，却不去。","notes":[]},{"n":31,"t":"这两个儿子是哪一个照着父亲的意愿做了呢？”他们说：“大儿子。”耶稣说：“我实在告诉你们，税吏和娼妓倒比你们先进神的国。","notes":[]},{"n":32,"t":"因为约翰到你们这里来指引你们走义路，你们却不信他，税吏和娼妓倒信了他。你们看见了以后，还是不悔悟去信他。”","notes":[]},{"n":33,"t":"“你们再听一个比喻：有一个家的主人开垦了一个葡萄园，四周围上篱笆，里面挖了一个榨酒池，盖了一座守望楼，租给园户，就出外远行去了。","notes":[],"heads":["恶园户的比喻"]},{"n":34,"t":"收果子的时候快到了，他打发仆人到园户那里去收果子。","notes":[]},{"n":35,"t":"园户拿住仆人，打了一个，杀了一个，用石头打死了一个。","notes":[]},{"n":36,"t":"主人又打发别的仆人去，比先前更多；园户还是照样对待他们。","notes":[]},{"n":37,"t":"最后他打发自己的儿子到他们那里去，说：‘他们会尊敬我的儿子。’","notes":[]},{"n":38,"t":"可是，园户看见他儿子，彼此说：‘这是承受产业的。来，我们杀了他，占他的产业！’","notes":[]},{"n":39,"t":"于是他们拿住他，把他扔出葡萄园外，杀了。","notes":[]},{"n":40,"t":"葡萄园的主人来的时候，要怎样处置那些园户呢？”","notes":[]},{"n":41,"t":"他们说：“要狠狠地除灭那些恶人，将葡萄园转租给那些按时候交果子的园户。”","notes":[]},{"n":42,"t":"耶稣对他们说：“‘匠人所丢弃的石头已作了房角的头块石头。这是主所做的，在我们眼中看为奇妙。’这段经文你们从来没有念过吗？","notes":[]},{"n":43,"t":"所以我告诉你们，神的国必从你们夺去，赐给那能结果子的民。","notes":[]},{"n":44,"t":"谁跌在这石头上，一定会跌得粉碎；这石头掉在谁的身上，就要把谁压得稀烂。”","notes":["有古卷没有44节。"]},{"n":45,"t":"祭司长和法利赛人听见他的比喻，就看出他是指着他们说的。","notes":[]},{"n":46,"t":"他们想要捉拿他，但是惧怕众人，因为众人认为他是先知。","notes":[]}]},"22":{"heading":"喜宴的比喻","verses":[{"n":1,"t":"耶稣又用比喻对他们说：","notes":[]},{"n":2,"t":"“天国好比一个王为他儿子摆设娶亲的宴席。","notes":[]},{"n":3,"t":"他打发仆人去，请那些被邀的人来赴宴，他们却不肯来。","notes":[]},{"n":4,"t":"王又打发别的仆人，说：‘你们去告诉那被邀的人，我的宴席已经预备好了，牛和肥畜已经宰了，各样都齐备，请你们来赴宴。’","notes":[]},{"n":5,"t":"那些人不理就走了，一个到自己田里去，一个做买卖去。","notes":[]},{"n":6,"t":"其余的抓住仆人，凌辱他们，把他们杀了。","notes":[]},{"n":7,"t":"王就大怒，发兵除灭那些凶手，烧毁他们的城。","notes":[]},{"n":8,"t":"于是王对仆人说：‘喜宴已经齐备，只是所邀的人不配。","notes":[]},{"n":9,"t":"所以你们要往岔路口上去，凡遇见的，都邀来赴宴。’","notes":[]},{"n":10,"t":"那些仆人就出去，到大路上，凡遇见的，不论善恶都招聚了来，宴席上就坐满了客人。","notes":[]},{"n":11,"t":"王进来见宾客，看到那里有一个没有穿礼服的，","notes":[]},{"n":12,"t":"就对他说：‘朋友，你到这里来怎么不穿礼服呢？’那人无言可答。","notes":[]},{"n":13,"t":"于是王对侍从说：‘捆起他的手脚，把他扔在外边的黑暗里；在那里他要哀哭切齿了。’","notes":[]},{"n":14,"t":"因为被召的人多，选上的人少。”","notes":[]},{"n":15,"t":"于是，法利赛人出去商议，怎样找话柄来陷害耶稣，","notes":[],"heads":["纳税给凯撒的问题"]},{"n":16,"t":"就打发他们的门徒同希律党人去见耶稣，说：“老师，我们知道你是诚实的，并且诚诚实实传神的道，无论谁你都一视同仁，因为你不看人的面子。","notes":[]},{"n":17,"t":"请告诉我们，你的意见如何？纳税给凯撒合不合法？”","notes":[]},{"n":18,"t":"耶稣看出他们的恶意，就说：“假冒为善的人哪，为什么试探我？","notes":[]},{"n":19,"t":"拿一个纳税的钱给我看！”他们就拿一个银币来给他。","notes":[]},{"n":20,"t":"耶稣问他们：“这像和这名号是谁的？”","notes":[]},{"n":21,"t":"他们说：“是凯撒的。”于是耶稣说：“这样，凯撒的归凯撒；神的归神。”","notes":[]},{"n":22,"t":"他们听了十分惊讶，就离开他走了。","notes":[]},{"n":23,"t":"那天，撒都该人来见耶稣。他们说没有复活这回事，于是问耶稣：","notes":[],"heads":["复活的问题"]},{"n":24,"t":"“老师，摩西说：‘某人若死了，没有孩子，他弟弟该娶他的妻子，为哥哥生子立后。’","notes":[]},{"n":25,"t":"从前，在我们这里有兄弟七人，第一个娶了妻，死了，没有孩子，撇下妻子给弟弟。","notes":[]},{"n":26,"t":"第二、第三，直到第七个，都是如此。","notes":[]},{"n":27,"t":"后来，那妇人也死了。","notes":[]},{"n":28,"t":"那么，在复活的时候，她是七个人中哪一个的妻子呢？因为他们都娶过她。”","notes":[]},{"n":29,"t":"耶稣回答他们说：“你们错了，因为不明白圣经，也不知道神的大能。","notes":[]},{"n":30,"t":"在复活的时候，人也不娶也不嫁，而是像天上的天使一样。","notes":[]},{"n":31,"t":"论到死人复活，神向你们所说的话，你们没有念过吗？","notes":[]},{"n":32,"t":"他说：‘我是亚伯拉罕的神，以撒的神，雅各的神。’神不是死人的神，而是活人的神。”","notes":[]},{"n":33,"t":"众人听见这话，对他的教导非常惊讶。","notes":[]},{"n":34,"t":"法利赛人听见耶稣堵住了撒都该人的口，他们就聚集在一起。","notes":[],"heads":["最大的诫命"]},{"n":35,"t":"其中有一个人是律法师，要试探耶稣，就问他：","notes":["有古卷没有“是律法师”。"]},{"n":36,"t":"“老师，律法上的诫命哪一条是最大的呢？”","notes":[]},{"n":37,"t":"耶稣对他说：“你要尽心、尽性、尽意爱主—你的神。","notes":[]},{"n":38,"t":"这是最大的，且是第一条诫命。","notes":[]},{"n":39,"t":"第二条也如此，就是要爱邻如己。","notes":["“邻”也可译作“人”。"]},{"n":40,"t":"这两条诫命是一切律法和先知书的总纲。”","notes":[]},{"n":41,"t":"法利赛人聚集的时候，耶稣问他们：","notes":[],"heads":["基督与大卫的关系"]},{"n":42,"t":"“论到基督，你们的意见如何？他是谁的后裔呢？”他们说：“是大卫的。”","notes":[]},{"n":43,"t":"耶稣说：“这样，大卫被圣灵感动，怎么还称他为主，说：","notes":[]},{"n":44,"t":"‘主对我主说：你坐在我的右边，等我把你的仇敌放在你脚下？’","notes":[]},{"n":45,"t":"大卫既称他为主，他怎么又是大卫的后裔呢？”","notes":[]},{"n":46,"t":"没有一个人能回答一句话，从那日以后没有人敢再问他什么。","notes":[]}]},"23":{"heading":"谴责文士和法利赛人","verses":[{"n":1,"t":"那时，耶稣对众人和门徒讲论，","notes":[]},{"n":2,"t":"说：“文士和法利赛人坐在摩西的位上，","notes":[]},{"n":3,"t":"所以凡他们所吩咐你们的，你们都要谨守遵行。但不要效法他们的行为，因为他们能说不能行。","notes":[]},{"n":4,"t":"他们把难挑的重担捆起来，搁在人的肩上，但自己一个指头也不肯动。","notes":["有古卷没有“难挑的”。"]},{"n":5,"t":"他们所做的一切事都是要让人看见，所以把佩戴的经匣加宽了，衣裳的繸子加长了，","notes":["“经匣”是一种经文袋。犹太人在晨祷时，常把装有经文的皮袋绑在左臂或前额。"]},{"n":6,"t":"喜爱宴席上的首座、会堂里的高位，","notes":[]},{"n":7,"t":"又喜欢人们在街市上向他们问安，称呼他们拉比。","notes":["“拉比”意思是“老师”。"]},{"n":8,"t":"但你们不要接受拉比的称呼，因为只有一位是你们的老师；你们都是弟兄。","notes":[]},{"n":9,"t":"也不要称呼地上的人为父，因为只有一位是你们的父，就是在天上的父。","notes":[]},{"n":10,"t":"不要接受师傅的称呼，因为只有一位是你们的师傅，就是基督。","notes":[]},{"n":11,"t":"你们中间谁为大，谁就要作你们的用人。","notes":[]},{"n":12,"t":"凡自高的，必降为卑；自甘卑微的，必升为高。","notes":[]},{"n":13,"t":"“你们这假冒为善的文士和法利赛人有祸了！因为你们当着人的面把天国的门关了，自己不进去，要进去的人，你们也不容他们进去。","notes":["有古卷加“14 你们这假冒为善的文士和法利赛人有祸了！因为你们侵吞寡妇的家产，假意作很长的祷告，所以要受更重的惩罚。”"]},{"n":15,"t":"“你们这假冒为善的文士和法利赛人有祸了！因为你们走遍海洋陆地，说服一个人入教，既入了教，却使他成为比你们加倍坏的地狱之子。","notes":[]},{"n":16,"t":"“你们这瞎眼的向导有祸了！你们说：‘凡指着圣所起誓的算不得什么；但是凡指着圣所中的金子起誓的，他就该谨守。’","notes":[]},{"n":17,"t":"你们这无知的瞎子啊，哪个更大呢？是金子，还是使金子成圣的圣所呢？","notes":[]},{"n":18,"t":"你们又说：‘凡指着祭坛起誓的算不得什么；但是凡指着坛上祭物起誓的，他就该谨守。’","notes":[]},{"n":19,"t":"你们这些瞎子啊，哪个更大呢？是祭物，还是使祭物成圣的坛呢？","notes":[]},{"n":20,"t":"所以，人指着祭坛起誓，就是指着坛和坛上一切所有的起誓；","notes":[]},{"n":21,"t":"人指着圣所起誓，就是指着圣所和那住在圣所里的起誓；","notes":[]},{"n":22,"t":"人指着天起誓，就是指着神的宝座和那坐在上面的起誓。","notes":[]},{"n":23,"t":"“你们这假冒为善的文士和法利赛人有祸了！因为你们将薄荷、大茴香、小茴香献上十分之一，那律法上更重要的事，就是公义、怜悯、信实，你们反倒不做；这原是你们该做的－至于那些奉献也不可废弃。","notes":[]},{"n":24,"t":"你们这瞎眼的向导，蠓虫你们就滤出来，骆驼你们倒吞下去。","notes":[]},{"n":25,"t":"“你们这假冒为善的文士和法利赛人有祸了！因为你们洗净杯盘的外面，里面却满了贪婪和放荡。","notes":[]},{"n":26,"t":"你这瞎眼的法利赛人，先洗净杯子的里面，好使外面也干净了。","notes":["“杯子”：有古卷是“杯盘”。"]},{"n":27,"t":"“你们这假冒为善的文士和法利赛人有祸了！因为你们好像粉饰了的坟墓，外面好看，里面却满了死人的骨头和一切的污秽。","notes":[]},{"n":28,"t":"你们也是如此，外面对人显出公义，里面却满了虚伪和不法的事。","notes":[]},{"n":29,"t":"“你们这假冒为善的文士和法利赛人有祸了！因为你们建造先知的坟，装修义人的墓，","notes":[]},{"n":30,"t":"说：‘若是我们在先祖的时代，必不和他们一同流先知的血。’","notes":[]},{"n":31,"t":"这样，你们就证明自己是杀害先知的人的子孙了。","notes":[]},{"n":32,"t":"你们去充满你们祖宗的恶贯吧！","notes":[]},{"n":33,"t":"你们这些蛇啊，毒蛇的孽种啊，怎能逃脱地狱的惩罚呢？","notes":[]},{"n":34,"t":"所以，我差遣先知、智慧人和文士到你们这里来，有的你们要杀害，要钉十字架；有的你们要在会堂里鞭打，从这城追逼到那城，","notes":[]},{"n":35,"t":"如此，地上所有义人流的血都归到你们身上，从义人亚伯的血起，直到你们在圣所和祭坛中间所杀的巴拉加的儿子撒迦利亚的血为止。","notes":[]},{"n":36,"t":"我实在告诉你们，这一切的罪都要归到这世代了。”","notes":[]},{"n":37,"t":"“耶路撒冷啊，耶路撒冷啊，你常杀害先知，又用石头打死那奉差遣到你这里来的人。我多少次想聚集你的儿女，好像母鸡把小鸡聚集在翅膀底下，但是你们不愿意。","notes":[],"heads":["为耶路撒冷哀哭"]},{"n":38,"t":"看吧，你们的家要被废弃成为荒芜。","notes":[]},{"n":39,"t":"我告诉你们，从今以后，你们绝不会再见到我，直到你们说：‘奉主名来的是应当称颂的！’”","notes":[]}]},"24":{"heading":"预言圣殿被毁","verses":[{"n":1,"t":"耶稣出了圣殿，正离开的时候，门徒前来，把圣殿的建筑指给他看。","notes":[]},{"n":2,"t":"耶稣回应他们说：“你们不是看见这一切吗？我实在告诉你们，这里将没有一块石头会留在另一块石头上，而不被拆毁的。”","notes":[]},{"n":3,"t":"耶稣在橄榄山上坐着，门徒私下进前来问他：“请告诉我们，什么时候有这些事呢？你来临和世代的终结有什么预兆呢？”","notes":[],"heads":["终局的预兆"]},{"n":4,"t":"耶稣回答他们：“你们要谨慎，免得有人迷惑你们。","notes":[]},{"n":5,"t":"因为将有好些人冒我的名来，说‘我是基督’，并且要迷惑许多人。","notes":[]},{"n":6,"t":"你们也将听见打仗和打仗的风声。注意，不要惊慌！因为这些事必须发生，但这还不是终结。","notes":[]},{"n":7,"t":"民要攻打民，国要攻打国，多处必有饥荒、地震。","notes":[]},{"n":8,"t":"这都是灾难的起头。","notes":["“灾难”：原文直译“生产的阵痛”。"]},{"n":9,"t":"那时，人要使你们陷在患难里，也要杀害你们；你们又要为我的名被万民憎恨。","notes":[]},{"n":10,"t":"那时，会有许多人跌倒，也会彼此陷害，彼此憎恨；","notes":[]},{"n":11,"t":"且有好些假先知起来，迷惑许多人。","notes":[]},{"n":12,"t":"因为不法的事增多，许多人的爱心渐渐冷淡了。","notes":[]},{"n":13,"t":"但坚忍到底的终必得救。","notes":[]},{"n":14,"t":"这天国的福音要传遍天下，对万民作见证，然后终结才来到。”","notes":[]},{"n":15,"t":"“当你们看见先知但以理所说的那‘施行毁灭的亵渎者’站在圣地（读这经的人要会意），","notes":[],"heads":["大灾难"]},{"n":16,"t":"那时，在犹太的，应当逃到山上；","notes":[]},{"n":17,"t":"在屋顶上的，不要下来拿家里的东西；","notes":[]},{"n":18,"t":"在田里的，不要回去取衣裳。","notes":[]},{"n":19,"t":"在那些日子，怀孕的和奶孩子的就苦了。","notes":[]},{"n":20,"t":"你们要祈求，好让你们逃走的时候，不遇见冬天或安息日。","notes":[]},{"n":21,"t":"因为那时必有大灾难，自从世界的起头直到如今，从没有这样的灾难，将来也不会有。","notes":[]},{"n":22,"t":"若不减少那些日子，凡血肉之躯的，就没有一个能得救；可是为了选民，那些日子将减少。","notes":[]},{"n":23,"t":"那时，若有人对你们说：‘看哪，基督在这里！’或‘在那里！’你们不要信。","notes":[]},{"n":24,"t":"因为假基督和假先知将要起来，显大神迹、大奇事，如果可能，要把选民也迷惑了。","notes":[]},{"n":25,"t":"看哪，我已经预先告诉你们了。","notes":[]},{"n":26,"t":"若有人对你们说：‘看哪，基督在旷野里！’你们不要出去；或说：‘看哪，基督在内室中！’你们不要信。","notes":[]},{"n":27,"t":"好像闪电从东边发出，直照到西边，人子来临也要这样。","notes":[]},{"n":28,"t":"尸首在哪里，鹰也会聚在哪里。”","notes":[]},{"n":29,"t":"“那些日子的灾难一过去，太阳要变黑，月亮也不放光，众星要从天上坠落，天上的万象都要震动。","notes":[],"heads":["人子的来临"]},{"n":30,"t":"那时，人子的预兆要显在天上，地上的万族都要哀哭。他们要看见人子带着能力和大荣耀，驾着天上的云来临。","notes":[]},{"n":31,"t":"他要差遣天使，用大声的号筒，从四方，从天这边直到天那边，召集他的选民。”","notes":[]},{"n":32,"t":"“你们要从无花果树学习功课：当树枝发芽长叶的时候，你们就知道夏天近了。","notes":[],"heads":["从无花果树学功课"]},{"n":33,"t":"同样，当你们看见这一切，就知道那时候近了，就在门口了。","notes":[]},{"n":34,"t":"我实在告诉你们，这世代还没有过去，这一切都要发生。","notes":[]},{"n":35,"t":"天地要废去，我的话却绝不废去。”","notes":[]},{"n":36,"t":"“但那日子，那时辰，没有人知道，连天上的天使也不知道，子也不知道，惟有父知道。","notes":[],"heads":["那日那时没有人知道"]},{"n":37,"t":"挪亚的日子怎样，人子来临也要怎样。","notes":[]},{"n":38,"t":"在洪水以前的那些日子，人照常吃喝嫁娶，直到挪亚进方舟的那日，","notes":[]},{"n":39,"t":"不知不觉洪水来了，把他们全都冲去。人子来临也要这样。","notes":[]},{"n":40,"t":"那时，两个人在田里，一个被接去，一个被撇下。","notes":[]},{"n":41,"t":"两个女人推磨，一个被接去，一个被撇下。","notes":[]},{"n":42,"t":"所以，你们要警醒，因为不知道你们的主哪一天来到。","notes":[]},{"n":43,"t":"你们要知道，一家的主人若知道晚上什么时候有贼来，就必警醒，不让贼挖穿房屋。","notes":[]},{"n":44,"t":"所以，你们也要预备，因为在你们想不到的时候，人子就来了。”","notes":[]},{"n":45,"t":"“那么，谁是那忠心又精明的仆人，主人派他管理自己的家仆、按时分粮给他们的呢？","notes":[],"heads":["忠心和不忠心的仆人"]},{"n":46,"t":"主人来到，看见仆人这样做，那仆人就有福了。","notes":[]},{"n":47,"t":"我实在告诉你们，主人要派他管理所有的财产。","notes":[]},{"n":48,"t":"如果那恶仆心里说：‘我的主人会来得迟’，","notes":[]},{"n":49,"t":"就动手打他的同伴，又和醉酒的人一同吃喝，","notes":[]},{"n":50,"t":"在想不到的日子，不知道的时候，那仆人的主人要来，","notes":[]},{"n":51,"t":"重重地惩罚他，定他和假冒为善的人同罪，在那里他要哀哭切齿了。”","notes":["“重重地惩罚他”或译“把他腰斩了”。"]}]},"25":{"heading":"十童女的比喻","verses":[{"n":1,"t":"“那时，天国好比十个童女拿着灯出去迎接新郎。","notes":[]},{"n":2,"t":"其中有五个是愚拙的，五个是聪明的。","notes":[]},{"n":3,"t":"愚拙的拿着灯，却没有带油；","notes":[]},{"n":4,"t":"聪明的拿着灯，又盛了油在器皿里。","notes":[]},{"n":5,"t":"新郎迟延的时候，她们都打盹，睡着了。","notes":[]},{"n":6,"t":"半夜有人喊：‘看，新郎来了，你们出来迎接他。’","notes":[]},{"n":7,"t":"那些童女就都起来挑亮她们的灯。","notes":[]},{"n":8,"t":"愚拙的对聪明的说：‘请分点油给我们，因为我们的灯要灭了。’","notes":[]},{"n":9,"t":"聪明的回答：‘恐怕不够你我用的；你们还是自己到卖油的那里去买吧。’","notes":[]},{"n":10,"t":"她们去买的时候，新郎到了。那预备好了的，与他进去共赴婚宴，门就关了。","notes":[]},{"n":11,"t":"其余的童女随后也来了，说：‘主啊，主啊，给我们开门！’","notes":[]},{"n":12,"t":"他却回答：‘我实在告诉你们，我不认识你们。’","notes":[]},{"n":13,"t":"所以，你们要警醒，因为那日子，那时辰，你们不知道。”","notes":[]},{"n":14,"t":"“天国又好比一个人要出外远行，就叫了仆人来，把他的家业交给他们。","notes":[],"heads":["按才受托的比喻"]},{"n":15,"t":"他按着各人的才干，给他们银子：一个给了五千，一个给了二千，一个给了一千，就出外远行去了。","notes":["“五千”：原文直译“五个他连得”；16、20节同。","“二千”：原文直译“二个他连得”；17、22节同。","“一千”：原文直译“一个他连得”；18、24、25、28节同。"]},{"n":16,"t":"那领五千的立刻拿去做买卖，另外赚了五千。","notes":[]},{"n":17,"t":"那领二千的也照样另赚了二千。","notes":[]},{"n":18,"t":"但那领一千的去掘开地，把主人的银子埋藏了。","notes":[]},{"n":19,"t":"过了许久，那些仆人的主人来了，和他们算账。","notes":[]},{"n":20,"t":"那领五千的又带着另外的五千来，说：‘主啊，你交给我五千。请看，我又赚了五千。’","notes":[]},{"n":21,"t":"主人说：‘好，你这又善良又忠心的仆人，你在少许的事上忠心，我要派你管理许多的事，进来享受你主人的快乐吧！’","notes":[]},{"n":22,"t":"那领二千的也进前来，说：‘主啊，你交给我二千。请看，我又赚了二千。’","notes":[]},{"n":23,"t":"主人说：‘好，你这又善良又忠心的仆人，你在少许的事上忠心，我要派你管理许多的事，进来享受你主人的快乐吧！’","notes":[]},{"n":24,"t":"那领一千的也进前来，说：‘主啊，我知道你，你是个严厉的人：没有种的地方也要收割，没有播的地方也要收获，","notes":[]},{"n":25,"t":"我就害怕，去把你的一千银子埋藏在地里。请看，你的银子在这里。’","notes":[]},{"n":26,"t":"他的主人回答他说：‘你这又恶又懒的仆人，你既知道我没有种的地方也要收割，没有播的地方也要收获，","notes":[]},{"n":27,"t":"就该把我的银子放给兑换银钱的人，到我来的时候可以连本带利收回。","notes":[]},{"n":28,"t":"把他这一千夺过来，给那有一万的。","notes":["“一万”：原文直译“十个他连得”。"]},{"n":29,"t":"因为凡有的，还要加给他，叫他有余；没有的，连他所有的也要夺过来。","notes":[]},{"n":30,"t":"把这无用的仆人丢在外面黑暗里，在那里他要哀哭切齿了。’”","notes":[]},{"n":31,"t":"“当人子在他荣耀里，同着众天使来临的时候，要坐在他荣耀的宝座上。","notes":[],"heads":["万民受审判"]},{"n":32,"t":"万民都要聚集在他面前。他要把他们分别出来，好像牧人分别绵羊、山羊一般，","notes":[]},{"n":33,"t":"把绵羊安置在右边，山羊在左边。","notes":[]},{"n":34,"t":"于是王要向他右边的说：‘你们这蒙我父赐福的，可来承受那创世以来为你们所预备的国。","notes":[]},{"n":35,"t":"因为我饿了，你们给我吃；渴了，你们给我喝；我流浪在外，你们留我住；","notes":[]},{"n":36,"t":"我赤身露体，你们给我穿；我病了，你们看顾我；我在监狱里，你们来看我。’","notes":[]},{"n":37,"t":"义人就回答：‘主啊，我们什么时候见你饿了，给你吃；渴了，给你喝？","notes":[]},{"n":38,"t":"什么时候见你流浪在外，留你住；或是赤身露体，给你穿？","notes":[]},{"n":39,"t":"又什么时候见你病了，或是在监狱里，来看你呢？’","notes":[]},{"n":40,"t":"王回答他们说：‘我实在告诉你们，这些事你们做在我弟兄中一个最小的身上，就是做在我身上了。’","notes":[]},{"n":41,"t":"“王又要向那左边的说：‘你们这被诅咒的人，离开我！进入那为魔鬼和他的使者所预备的永火里去！","notes":[]},{"n":42,"t":"因为我饿了，你们没有给我吃；渴了，你们没有给我喝；","notes":[]},{"n":43,"t":"我流浪在外，你们没有留我住；我赤身露体，你们没有给我穿；我病了，我在监狱里，你们没有来看顾我。’","notes":[]},{"n":44,"t":"他们也要回答：‘主啊，我们什么时候见你饿了，或渴了，或流浪在外，或赤身露体，或病了，或在监狱里，没有伺候你呢？’","notes":[]},{"n":45,"t":"王要回答：‘我实在告诉你们，这些事你们没有做在任何一个最小的弟兄身上，就是没有做在我身上了。’","notes":[]},{"n":46,"t":"这些人要往永刑里去；那些义人要往永生里去。”","notes":[]}]},"26":{"heading":"杀害耶稣的阴谋","verses":[{"n":1,"t":"耶稣说完了这一切的话，就对门徒说：","notes":[]},{"n":2,"t":"“你们知道，过两天是逾越节，人子将要被出卖，钉在十字架上。”","notes":[]},{"n":3,"t":"那时，祭司长和百姓的长老聚集在那称为该亚法的大祭司的院里。","notes":[]},{"n":4,"t":"大家商议要设计捉拿耶稣，把他杀掉。","notes":[]},{"n":5,"t":"可是他们说：“不可在过节的日子，恐怕百姓生乱。”","notes":[]},{"n":6,"t":"耶稣在伯大尼的麻风病人西门家里，","notes":[],"heads":["在伯大尼受膏"]},{"n":7,"t":"有一个女人拿着一玉瓶极贵的香膏来，趁耶稣坐席的时候，浇在他的头上。","notes":[]},{"n":8,"t":"门徒看见就很不高兴，说：“何必这样浪费呢！","notes":[]},{"n":9,"t":"这香膏可以卖许多钱，周济穷人。”","notes":[]},{"n":10,"t":"耶稣看出他们的意思，就说：“为什么难为这女人呢？她在我身上做的是一件美事。","notes":[]},{"n":11,"t":"因为常有穷人和你们在一起，但是你们不常有我。","notes":[]},{"n":12,"t":"她把这香膏浇在我身上是为我安葬作准备的。","notes":[]},{"n":13,"t":"我实在告诉你们，普天之下，无论在什么地方传这福音，都要述说这女人所做的，来记念她。”","notes":[]},{"n":14,"t":"当时，十二使徒中有一个叫加略人犹大的，去见祭司长，","notes":[],"heads":["犹大出卖耶稣"]},{"n":15,"t":"说：“我把他交给你们，你们愿意给我多少钱？”他们给了他三十块银钱。","notes":[]},{"n":16,"t":"从那时候起，他就找机会要把耶稣交给他们。","notes":[]},{"n":17,"t":"除酵节的第一天，门徒来问耶稣：“你要我们在哪里给你预备吃逾越节的宴席呢？”","notes":[],"heads":["与门徒同守逾越节"]},{"n":18,"t":"耶稣说：“你们进城去，到某人那里，对他说：‘老师说：我的时候快到了，我要和我的门徒在你家里守逾越节。’”","notes":[]},{"n":19,"t":"门徒遵照耶稣所吩咐的去预备了逾越节的宴席。","notes":[]},{"n":20,"t":"到了晚上，耶稣和十二使徒坐席。","notes":[]},{"n":21,"t":"他们吃的时候，耶稣说：“我实在告诉你们，你们中间有一个人要出卖我。”","notes":[]},{"n":22,"t":"他们就非常忧愁，一个一个地问他：“主，该不是我吧？”","notes":[]},{"n":23,"t":"耶稣回答说：“同我蘸手在盘子里的，就是要出卖我的。","notes":[]},{"n":24,"t":"人子要去了，正如经上所写有关他的；但出卖人子的人有祸了！那人没有出生倒好。”","notes":[]},{"n":25,"t":"出卖耶稣的犹大回答他说：“拉比，该不是我吧？”耶稣说：“你自己说了。”","notes":[]},{"n":26,"t":"他们吃的时候，耶稣拿起饼来，祝福了，就擘开，递给门徒，说：“你们拿去，吃吧。这是我的身体。”","notes":[],"heads":["设立主的晚餐"]},{"n":27,"t":"他又拿起杯来，祝谢了，递给他们，说：“你们都喝这个，","notes":[]},{"n":28,"t":"因为这是我立约的血，为许多人流出来，使罪得赦。","notes":[]},{"n":29,"t":"但我告诉你们，从今以后，我不再喝这葡萄汁，直到我在我父的国里与你们同喝新的那日子。”","notes":[]},{"n":30,"t":"他们唱了诗，就出来往橄榄山去。","notes":[]},{"n":31,"t":"那时，耶稣对他们说：“今夜，你们为我的缘故都要跌倒。因为经上记着：‘我要击打牧人，羊就分散了。’","notes":[],"heads":["预言彼得不认主"]},{"n":32,"t":"但我复活以后，要在你们之前往加利利去。”","notes":[]},{"n":33,"t":"彼得回答他说：“即使众人为你的缘故跌倒，我也绝不跌倒。”","notes":[]},{"n":34,"t":"耶稣说：“我实在告诉你，今夜鸡叫以前，你要三次不认我。”","notes":[]},{"n":35,"t":"彼得说：“我就是必须和你同死，也绝不会不认你。”所有的门徒都是这样说。","notes":[]},{"n":36,"t":"耶稣和门徒来到一个地方，名叫客西马尼。他对他们说：“你们坐在这里，我到那边去祷告。”","notes":[],"heads":["在客西马尼祷告"]},{"n":37,"t":"于是他带着彼得和西庇太的两个儿子同去。他忧愁起来，极其难过，","notes":[]},{"n":38,"t":"就对他们说：“我心里非常忧伤，几乎要死；你们留在这里，和我一同警醒。”","notes":[]},{"n":39,"t":"他就稍往前走，俯伏在地，祷告说：“我父啊，如果可能，求你使这杯离开我。然而，不是照我所愿的，而是照你所愿的。”","notes":[]},{"n":40,"t":"他回到门徒那里，见他们睡着了，就对彼得说：“怎么样？你们不能同我警醒一小时吗？","notes":[]},{"n":41,"t":"总要警醒祷告，免得陷入试探。你们心灵固然愿意，肉体却软弱了。”","notes":[]},{"n":42,"t":"他第二次又去祷告说：“我父啊，这杯若不能离开我，必须我喝，就愿你的旨意成全。”","notes":[]},{"n":43,"t":"他又来，见他们睡着了，因为他们的眼睛困倦。","notes":[]},{"n":44,"t":"耶稣又离开他们，第三次去祷告，说的话跟先前一样。","notes":[]},{"n":45,"t":"然后他来到门徒那里，对他们说：“现在你们仍在睡觉安歇吗？看哪，时候到了，人子被出卖在罪人手里了。","notes":[]},{"n":46,"t":"起来，我们走吧！看哪，那出卖我的人快来了。”","notes":[]},{"n":47,"t":"耶稣还在说话的时候，十二使徒之一的犹大来了，还有一大群人带着刀棒，从祭司长和百姓的长老那里跟他同来。","notes":[],"heads":["耶稣被捕"]},{"n":48,"t":"那出卖耶稣的给了他们一个暗号，说：“我亲谁，谁就是。你们把他抓住。”","notes":[]},{"n":49,"t":"犹大立刻进前来对耶稣说：“拉比，你好！”就跟他亲吻。","notes":[]},{"n":50,"t":"耶稣对他说：“朋友，你来要做的事，就做吧。”于是那些人上前，下手抓住耶稣。","notes":["“你来要做的事，就做吧。”或译“你来做什么？”"]},{"n":51,"t":"忽然，有一个和耶稣一起的人伸手拔出刀来，把大祭司的仆人砍了一刀，削掉了他一只耳朵。","notes":[]},{"n":52,"t":"耶稣对他说：“收刀入鞘吧！凡动刀的，必死在刀下。","notes":[]},{"n":53,"t":"你想我不能求我父，现在为我差遣比十二营还多的天使来吗？","notes":[]},{"n":54,"t":"若是这样，经上所说事情必须如此发生的话怎么应验呢？”","notes":[]},{"n":55,"t":"就在那时，耶稣对众人说：“你们带着刀棒出来抓我，如同拿强盗吗？我天天坐在圣殿里教导人，你们并没有抓我。","notes":[]},{"n":56,"t":"但这整件事的发生，是要应验先知书上的话。”那时，门徒都离开他，逃走了。","notes":[]},{"n":57,"t":"抓耶稣的人把他带到大祭司该亚法那里去，文士和长老已经在那里聚集。","notes":[],"heads":["耶稣在议会受审"]},{"n":58,"t":"彼得远远地跟着耶稣，直到大祭司的院子，进到里面，就和警卫同坐，要看结局怎样。","notes":[]},{"n":59,"t":"祭司长和全议会寻找假见证控告耶稣，要处死他。","notes":[]},{"n":60,"t":"虽然有好些人来作假见证，总找不到实据。最后有两个人前来，","notes":[]},{"n":61,"t":"说：“这个人曾说：‘我能拆毁神的殿，三日内又建造起来。’”","notes":[]},{"n":62,"t":"大祭司就站起来，对耶稣说：“这些人作证告你的事，你什么都不回答吗？”","notes":[]},{"n":63,"t":"耶稣却不言语。大祭司对他说：“我指着永生神命令你起誓告诉我们，你是不是基督—神的儿子？”","notes":[]},{"n":64,"t":"耶稣对他说：“你自己说了。然而，我告诉你们，此后你们要看见人子坐在权能者的右边，驾着天上的云来临。”","notes":[]},{"n":65,"t":"大祭司就撕裂衣服，说：“他说了亵渎的话，我们何必再要证人呢？现在你们已经听见他这亵渎的话了。","notes":[]},{"n":66,"t":"你们的意见如何？”他们回答：“他该处死。”","notes":[]},{"n":67,"t":"他们就吐唾沫在他脸上，用拳头打他，也有打他耳光的，","notes":[]},{"n":68,"t":"说：“基督啊，向我们说预言吧！打你的是谁？”","notes":[]},{"n":69,"t":"彼得在外面院子里坐着，有一个使女前来，说：“你素来也是同那加利利人耶稣一起的。”","notes":[],"heads":["彼得三次不认主"]},{"n":70,"t":"彼得在众人面前却不承认，说：“我不知道你说的是什么！”","notes":[]},{"n":71,"t":"他出去，到了门口，又有一个使女看见他，就对那里的人说：“这个人是同拿撒勒人耶稣一起的。”","notes":[]},{"n":72,"t":"彼得又不承认，起誓说：“我不认得那个人。”","notes":[]},{"n":73,"t":"过了不久，旁边站着的人进前来，对彼得说：“你的确是他们一伙的，你的口音把你显露出来了。”","notes":[]},{"n":74,"t":"彼得就赌咒发誓说：“我不认得那个人。”立刻鸡就叫了。","notes":[]},{"n":75,"t":"彼得想起耶稣所说的话：“鸡叫以前，你要三次不认我。”他就出去痛哭。","notes":[]}]},"27":{"heading":"耶稣被解送给彼拉多","verses":[{"n":1,"t":"到了早晨，众祭司长和百姓的长老商议要处死耶稣，","notes":[]},{"n":2,"t":"就把他绑着，解去，交给彼拉多总督。","notes":[]},{"n":3,"t":"这时，出卖耶稣的犹大看见耶稣已经定了罪，就后悔，把那三十块银钱拿回来给祭司长和长老，","notes":[],"heads":["犹大之死"]},{"n":4,"t":"说：“我出卖了无辜人的血有罪了。”他们说：“那跟我们有什么相干？你自己承当吧！”","notes":[]},{"n":5,"t":"犹大就把那银钱丢在殿里，出去吊死了。","notes":[]},{"n":6,"t":"祭司长拾起银钱来，说：“这是血价，不可放在圣殿的银库里。”","notes":[]},{"n":7,"t":"他们商议，就用那银钱买了窑户的一块田，用来埋葬外乡人。","notes":[]},{"n":8,"t":"所以，那块田直到今日还叫做“血田”。","notes":[]},{"n":9,"t":"这就应验了先知耶利米所说的话：“他们用那三十块银钱，就是以色列人给那被估定的人所估定的价钱，","notes":[]},{"n":10,"t":"买了窑户的一块田；这是照着主所吩咐我的。”","notes":[]},{"n":11,"t":"耶稣站在总督面前，总督问他：“你是犹太人的王吗？”耶稣说：“是你说的。”","notes":[],"heads":["耶稣在彼拉多面前受审"]},{"n":12,"t":"他被祭司长和长老控告的时候，什么都不回答。","notes":[]},{"n":13,"t":"彼拉多就对他说：“他们作证告你这么多的事，你没有听见吗？”","notes":[]},{"n":14,"t":"耶稣仍不回答，连一句话也不说，以致总督觉得非常惊讶。","notes":[]},{"n":15,"t":"总督有一个常例，每逢这节期，随众人的意愿释放一个囚犯给他们。","notes":[],"heads":["耶稣被判死刑"]},{"n":16,"t":"当时有一个出名的囚犯叫巴拉巴。","notes":["有古卷是“耶稣．巴拉巴”；17节同。"]},{"n":17,"t":"众人聚集的时候，彼拉多就对他们说：“你们要我释放哪一个给你们？是巴拉巴呢？是称为基督的耶稣呢？”","notes":[]},{"n":18,"t":"总督原知道他们是因为嫉妒才把他解了来。","notes":[]},{"n":19,"t":"正坐堂的时候，他的夫人打发人来说：“这义人的事，你一点不可管，因为我今天在梦中因他受了许多的苦。”","notes":[]},{"n":20,"t":"祭司长和长老挑唆众人，要求释放巴拉巴，除掉耶稣。","notes":[]},{"n":21,"t":"总督回答他们说：“这两个人，你们要我释放哪一个给你们呢？”他们说：“巴拉巴。”","notes":[]},{"n":22,"t":"彼拉多说：“这样，那称为基督的耶稣我怎么办他呢？”他们都说：“把他钉十字架！”","notes":[]},{"n":23,"t":"总督说：“为什么？他做了什么恶事呢？”他们更加喊着说：“把他钉十字架！”","notes":[]},{"n":24,"t":"彼拉多见说也无济于事，反要生乱，就拿水在众人面前洗手，说：“流这人的血，罪不在我，你们承当吧。”","notes":["“人”：有古卷是“义人”。"]},{"n":25,"t":"众人都回答：“他的血归到我们和我们的子孙身上！”","notes":[]},{"n":26,"t":"于是彼拉多释放巴拉巴给他们，把耶稣鞭打后交给人钉十字架。","notes":[]},{"n":27,"t":"总督的兵把耶稣带进总督府，把全营的兵都聚集在耶稣那里。","notes":[],"heads":["士兵戏弄耶稣"]},{"n":28,"t":"他们脱了他的衣服，穿上一件朱红色的袍子，","notes":[]},{"n":29,"t":"用荆棘编了冠冕，戴在他头上，拿一根芦苇秆放在他右手里，跪在他面前，戏弄他，说：“万岁，犹太人的王！”","notes":[]},{"n":30,"t":"他们又向他吐唾沫，拿芦苇秆打他的头。","notes":[]},{"n":31,"t":"他们戏弄完了，就给他脱了袍子，又穿上他自己的衣服，带他出去，要钉十字架。","notes":[]},{"n":32,"t":"他们出去的时候，遇见一个古利奈人，名叫西门，就强迫他同去，好背耶稣的十字架。","notes":[],"heads":["耶稣被钉十字架"]},{"n":33,"t":"他们到了一个地方，名叫各各他，就是“髑髅地”。","notes":[]},{"n":34,"t":"士兵拿苦胆调和的酒给耶稣喝。他尝了，不肯喝。","notes":[]},{"n":35,"t":"他们把他钉在十字架上，然后抽签分了他的衣服，","notes":[]},{"n":36,"t":"又坐在那里看守他。","notes":[]},{"n":37,"t":"他们在他头上方安了一个罪状牌，写着：“这是犹太人的王耶稣。”","notes":[]},{"n":38,"t":"当时，有两个强盗和他同钉十字架，一个在右边，一个在左边。","notes":[]},{"n":39,"t":"从那里经过的人讥笑他，摇着头，","notes":[]},{"n":40,"t":"说：“你这拆毁殿、三日又建造起来的，救救你自己吧！如果你是神的儿子，就从十字架上下来呀！”","notes":[]},{"n":41,"t":"众祭司长、文士和长老也同样嘲笑他，说：","notes":[]},{"n":42,"t":"“他救了别人，不能救自己。他是以色列的王，现在从十字架上下来，我们就信他。","notes":[]},{"n":43,"t":"他倚靠神，神若愿意，现在就来救他，因为他曾说‘我是神的儿子’。”","notes":[]},{"n":44,"t":"和他同钉的强盗也这样讥讽他。","notes":[]},{"n":45,"t":"从正午到下午三点钟，遍地都黑暗了。","notes":[],"heads":["耶稣之死"]},{"n":46,"t":"约在下午三点钟，耶稣大声高呼，说：“以利！以利！拉马撒巴各大尼？”就是说：“我的神！我的神！为什么离弃我？”","notes":[]},{"n":47,"t":"站在那里的人，有的听见就说：“这个人呼叫以利亚呢！”","notes":[]},{"n":48,"t":"其中有一个人立刻跑去，拿海绵蘸满了醋，绑在芦苇秆上，送给他喝。","notes":[]},{"n":49,"t":"其余的人说：“且等着，看以利亚来不来救他。”","notes":[]},{"n":50,"t":"耶稣又大喊一声，气就断了。","notes":[]},{"n":51,"t":"忽然，殿的幔子从上到下裂为两半，地震动，磐石崩裂，","notes":[]},{"n":52,"t":"坟墓也开了，有许多已睡了的圣徒的身体也复活了。","notes":[]},{"n":53,"t":"耶稣复活以后，他们从坟墓里出来，进了圣城，向许多人显现。","notes":[]},{"n":54,"t":"百夫长和跟他一同看守耶稣的人看见地震和所经历的事，非常害怕，说：“他真是神的儿子！”","notes":[]},{"n":55,"t":"有好些妇女在那里，远远地观看，她们是从加利利跟随耶稣，来服事他的；","notes":[]},{"n":56,"t":"其中有抹大拉的马利亚，又有雅各和约瑟的母亲马利亚，并有西庇太两个儿子的母亲。","notes":[]},{"n":57,"t":"到了晚上，有一个财主，名叫约瑟，是亚利马太来的，他也是耶稣的门徒。","notes":[],"heads":["耶稣的安葬"]},{"n":58,"t":"这人去见彼拉多，请求要耶稣的身体，彼拉多就吩咐给他。","notes":[]},{"n":59,"t":"约瑟取了身体，用干净的细麻布裹好，","notes":[]},{"n":60,"t":"然后把他安放在自己的新墓穴里，就是他凿在岩石里的。他又把大石头滚到墓门口，然后离开。","notes":[]},{"n":61,"t":"有抹大拉的马利亚和另一个马利亚在那里，对着坟墓坐着。","notes":[]},{"n":62,"t":"次日，就是预备日的第二天，祭司长和法利赛人聚集来见彼拉多，","notes":[],"heads":["封石妥守"]},{"n":63,"t":"说：“大人，我们记得那迷惑人的还活着的时候曾说：‘三天后我要复活。’","notes":[]},{"n":64,"t":"因此，请吩咐人将坟墓把守妥当，直到第三天，恐怕他的门徒来把他偷了去，就告诉百姓说：‘他从死人中复活了。’这样的话，那后来的迷惑就比先前的更厉害了。”","notes":[]},{"n":65,"t":"彼拉多说：“你们有看守的兵，去吧！尽你们所能的把守妥当。”","notes":[]},{"n":66,"t":"他们就带着看守的兵同去，封了石头，将坟墓把守妥当。","notes":[]}]},"28":{"heading":"耶稣复活","verses":[{"n":1,"t":"安息日过后，七日的第一日，天快亮的时候，抹大拉的马利亚和另一个马利亚来看坟墓。","notes":[]},{"n":2,"t":"忽然，地大震动；因为有主的一个使者从天上下来，把石头滚开，坐在上面。","notes":[]},{"n":3,"t":"他的相貌如同闪电，衣服洁白如雪。","notes":[]},{"n":4,"t":"看守的人吓得浑身颤抖，甚至和死人一样。","notes":[]},{"n":5,"t":"天使回应妇女说：“不要害怕！我知道你们是寻找那钉十字架的耶稣。","notes":[]},{"n":6,"t":"他不在这里，照他所说的，他已经复活了。你们来！看看安放他的地方。","notes":[]},{"n":7,"t":"快去告诉他的门徒，说他已从死人中复活了，并且要比你们先到加利利去，在那里你们会看见他。看哪！我已经告诉你们了。”","notes":[]},{"n":8,"t":"妇女们急忙离开坟墓，又害怕，又大为欢喜，跑去告诉他的门徒。","notes":[]},{"n":9,"t":"忽然，耶稣迎上她们，说：“平安！”她们就上前抱住他的脚拜他。","notes":[]},{"n":10,"t":"耶稣对她们说：“不要害怕！你们去告诉我的弟兄，叫他们往加利利去，在那里会见到我。”","notes":[]},{"n":11,"t":"她们去的时候，看守的兵有几个进城去，把所发生的事都报告祭司长。","notes":[],"heads":["祭司长捏造谎言"]},{"n":12,"t":"祭司长和长老聚集商议，就拿许多银钱给士兵，","notes":[]},{"n":13,"t":"说：“你们要这样说：‘夜间我们睡觉的时候，他的门徒来把他偷去了。’","notes":[]},{"n":14,"t":"若是这话被总督听见，有我们劝他，保你们无事。”","notes":[]},{"n":15,"t":"士兵收了银钱，就照所嘱咐他们的去做。这话就在犹太人中间流传，直到今日。","notes":[]},{"n":16,"t":"十一个门徒往加利利去，到了耶稣指定他们去的山上。","notes":[],"heads":["门徒奉差遣"]},{"n":17,"t":"他们见了耶稣就拜他，然而还有人疑惑。","notes":[]},{"n":18,"t":"耶稣进前来，对他们说：“天上地下所有的权柄都赐给我了。","notes":[]},{"n":19,"t":"所以，你们要去，使万民作我的门徒，奉父、子、圣灵的名给他们施洗，","notes":["“奉父、子、圣灵的名给他们施洗”或译“给他们施洗，归于父、子、圣灵的名”。"]},{"n":20,"t":"凡我所吩咐你们的，都教导他们遵守。看哪，我天天与你们同在，直到世代的终结。”","notes":[]}]}},"MRK":{"1":{"heading":"施洗约翰传道","verses":[{"n":1,"t":"神的儿子，耶稣基督福音的起头。","notes":["有古卷没有“神的儿子”。"]},{"n":2,"t":"正如以赛亚先知书上记着：“看哪，我要差遣我的使者在你面前，他要为你预备道路。","notes":[]},{"n":3,"t":"在旷野有声音呼喊着：预备主的道，修直他的路。”","notes":[]},{"n":4,"t":"照这话，施洗约翰来到旷野，宣讲悔改的洗礼，使罪得赦。","notes":["有古卷是“约翰来了，在旷野施洗”。"]},{"n":5,"t":"犹太全地和全耶路撒冷的人都出去，到约翰那里，承认他们的罪，在约旦河里受他的洗。","notes":[]},{"n":6,"t":"约翰穿骆驼毛的衣服，腰束皮带，吃的是蝗虫和野蜜。","notes":[]},{"n":7,"t":"他宣讲，说：“有一位在我以后来的，能力比我更大，我就是弯腰给他解鞋带也不配。","notes":[]},{"n":8,"t":"我用水给你们施洗，他却要用圣灵给你们施洗。”","notes":[]},{"n":9,"t":"那时，耶稣从加利利的拿撒勒来，在约旦河里受了约翰的洗。","notes":[],"heads":["耶稣受洗"]},{"n":10,"t":"他从水里一上来，就看见天裂开了，圣灵仿佛鸽子降在他身上。","notes":[]},{"n":11,"t":"又有声音从天上来，说：“你是我的爱子，我喜爱你。”","notes":[]},{"n":12,"t":"圣灵立刻把耶稣催促到旷野里去。","notes":[],"heads":["耶稣受试探"]},{"n":13,"t":"他在旷野四十天，受撒但的试探，并与野兽同在一起，且有天使来伺候他。","notes":[]},{"n":14,"t":"约翰下监以后，耶稣来到加利利，宣讲神的福音，","notes":[],"heads":["开始在加利利传道"]},{"n":15,"t":"说：“日期满了，神的国近了。你们要悔改，信福音！”","notes":[]},{"n":16,"t":"耶稣沿着加利利的海边走，看见西门和西门的弟弟安得烈在海上撒网；他们本是打鱼的。","notes":[],"heads":["呼召四个渔夫"]},{"n":17,"t":"耶稣对他们说：“来跟从我，我要叫你们得人如得鱼一样。”","notes":[]},{"n":18,"t":"他们立刻舍了网，跟从他。","notes":[]},{"n":19,"t":"耶稣稍往前走，又见西庇太的儿子雅各和他弟弟约翰在船上补网。","notes":[]},{"n":20,"t":"耶稣随即呼召他们，他们就把父亲西庇太和雇工留在船上，跟从了耶稣。","notes":[]},{"n":21,"t":"他们到了迦百农，耶稣就在安息日进了会堂教导人。","notes":[],"heads":["耶稣赶逐污灵"]},{"n":22,"t":"他们对他的教导感到很惊奇，因为他教导他们正像有权柄的人，不像文士。","notes":[]},{"n":23,"t":"当时，会堂里有一个污灵附身的人，他在喊叫，","notes":[]},{"n":24,"t":"说：“拿撒勒人耶稣，你为什么干扰我们？你来消灭我们吗？我知道你是谁，你是神的圣者。”","notes":[]},{"n":25,"t":"耶稣斥责他说：“不要作声，从这人身上出来吧！”","notes":[]},{"n":26,"t":"污灵使那人抽了一阵风，大声喊叫，就出来了。","notes":[]},{"n":27,"t":"众人都惊讶，以致彼此对问：“这是什么事？是个新的教导啊！他用权柄命令污灵，连污灵也听从了他。”","notes":[]},{"n":28,"t":"于是耶稣的名声立刻传遍了全加利利周围地区。","notes":[]},{"n":29,"t":"他们一出会堂，就同雅各和约翰进了西门和安得烈的家。","notes":[],"heads":["治好许多病人"]},{"n":30,"t":"西门的岳母正发烧躺着，就有人告诉耶稣。","notes":[]},{"n":31,"t":"耶稣进前拉着她的手，扶她起来，烧就退了，于是她服事他们。","notes":[]},{"n":32,"t":"傍晚日落的时候，有人带着一切害病的和被鬼附的，来到耶稣跟前。","notes":[]},{"n":33,"t":"全城的人都聚集在门前。","notes":[]},{"n":34,"t":"耶稣治好了许多害各样病的人，又赶出许多鬼，不许鬼说话，因为鬼认识他。","notes":[]},{"n":35,"t":"次日早晨，天未亮的时候，耶稣起来，到旷野地方去，在那里祷告。","notes":[],"heads":["在加利利传道"]},{"n":36,"t":"西门和同伴出去找他，","notes":[]},{"n":37,"t":"找到了就对他说：“众人都在找你！”","notes":[]},{"n":38,"t":"耶稣对他们说：“让我们往别处去，到邻近的乡村，我也好在那里传道，因为我是为这事出来的。”","notes":[]},{"n":39,"t":"于是他走遍全加利利，在他们的会堂传道，并且赶鬼。","notes":[]},{"n":40,"t":"有一个麻风病人来求耶稣，向他跪下，说：“你若肯，你能使我洁净。”","notes":["有古卷没有“向他跪下”。"],"heads":["洁净麻风病人"]},{"n":41,"t":"耶稣动了慈心，就伸手摸他，说：“我肯，你洁净了吧！”","notes":[]},{"n":42,"t":"麻风病立刻离开他，他就洁净了。","notes":[]},{"n":43,"t":"耶稣严严地叮嘱他，立刻打发他走，","notes":[]},{"n":44,"t":"对他说：“你要注意，千万不可告诉任何人，只要去，让祭司为你检查，又因为你已经洁净，献上摩西所吩咐的祭物，作为证据给众人看。”","notes":[]},{"n":45,"t":"那人出去，倒说许多的话，把这件事传扬开了，使耶稣不能再公开进城，只好留在外边旷野地方，人从各处都到他跟前来。","notes":[]}]},"2":{"heading":"治好瘫子","verses":[{"n":1,"t":"过了些日子，耶稣又进了迦百农。人听说他在屋里，","notes":[]},{"n":2,"t":"于是许多人聚集，甚至连门前都没有空地；耶稣就对他们讲道。","notes":[]},{"n":3,"t":"有人带着一个瘫子来见耶稣，是由四个人抬来的；","notes":[]},{"n":4,"t":"因为人多，无法抬到耶稣跟前，就把他所在那房子的屋顶拆了，既拆通了，就把瘫子连所躺卧的褥子都缒下去。","notes":[]},{"n":5,"t":"耶稣见他们的信心，就对瘫子说：“孩子，你的罪赦了。”","notes":[]},{"n":6,"t":"有几个文士坐在那里，心里议论，说：","notes":[]},{"n":7,"t":"“这个人为什么这样说呢？他说亵渎的话了。除了神一位之外，谁能赦罪呢？”","notes":[]},{"n":8,"t":"耶稣心中立刻知道他们心里这样议论，就说：“你们心里为什么这样议论呢？","notes":[]},{"n":9,"t":"对瘫子说‘你的罪赦了’，或说‘起来！拿你的褥子行走’，哪一样容易呢？","notes":[]},{"n":10,"t":"但要让你们知道，人子在地上有赦罪的权柄。”就对瘫子说：","notes":[]},{"n":11,"t":"“我吩咐你，起来！拿你的褥子回家去吧。”","notes":[]},{"n":12,"t":"那人就起来，立刻拿着褥子，当着众人面前出去了，以致众人都惊奇，归荣耀给神，说：“我们从来没有见过这样的事！”","notes":[]},{"n":13,"t":"耶稣又到海边去，众人都到他跟前来，他就教导他们。","notes":[],"heads":["呼召利未"]},{"n":14,"t":"耶稣往前走，看见亚勒腓的儿子利未在税关坐着，就对他说：“来跟从我！”他就起来跟从耶稣。","notes":[]},{"n":15,"t":"耶稣在利未家里坐席的时候，有好些税吏和罪人与耶稣和他的门徒一同坐席，因为有很多人也跟随耶稣。","notes":[]},{"n":16,"t":"法利赛人中的文士看见耶稣与罪人和税吏一同吃饭，就对他的门徒说：“他与税吏和罪人一同吃饭吗？”","notes":["有古卷是“文士和法利赛人”。"]},{"n":17,"t":"耶稣听见，就对他们说：“健康的人用不着医生，有病的人才用得着。我不是来召义人，而是召罪人。”","notes":[]},{"n":18,"t":"那时，约翰的门徒和法利赛人都禁食。他们来问耶稣说：“约翰的门徒和法利赛人的门徒禁食，你的门徒却不禁食，这是为什么呢？”","notes":[],"heads":["禁食的问题"]},{"n":19,"t":"耶稣对他们说：“新郎和宾客在一起的时候，宾客怎么能禁食呢？只要新郎和他们在一起，他们不能禁食。","notes":[]},{"n":20,"t":"但日子将到，新郎要被带走，那日他们就要禁食了。","notes":[]},{"n":21,"t":"“没有人把新布缝在旧衣服上，若是这样，所补上的新布会撕破旧衣服，裂口就更大了。","notes":[]},{"n":22,"t":"也没有人把新酒装在旧皮袋里，若是这样，酒会胀破皮袋，酒和皮袋都糟蹋了。相反地，新酒要装在新皮袋里。”","notes":["有古卷是“酒就漏出来，皮袋也糟蹋了”。","有古卷没有“相反地…皮袋里”。"]},{"n":23,"t":"有一个安息日，耶稣从麦田经过。他的门徒走路的时候，摘起麦穗来。","notes":[],"heads":["在安息日摘麦穗"]},{"n":24,"t":"法利赛人对耶稣说：“看哪！他们为什么做安息日不合法的事呢？”","notes":[]},{"n":25,"t":"耶稣对他们说：“大卫和跟从他的人饥饿需要食物时所做的事，你们没有念过吗？","notes":[]},{"n":26,"t":"他在亚比亚他作大祭司的时候，怎么进了神的居所，吃了供饼，又给跟从他的人吃呢？这饼除了祭司以外，人都不可以吃。”","notes":[]},{"n":27,"t":"他又对他们说：“安息日是为人设立的，人不是为安息日设立的。","notes":[]},{"n":28,"t":"所以，人子也是安息日的主。”","notes":[]}]},"3":{"heading":"治好萎缩了的手","verses":[{"n":1,"t":"耶稣又进了会堂，在那里有一个人，他的一只手萎缩了。","notes":[]},{"n":2,"t":"众人为了要控告耶稣，就窥探他会不会在安息日医治那人。","notes":[]},{"n":3,"t":"耶稣对那手萎缩了的人说：“起来站在当中！”","notes":[]},{"n":4,"t":"他又问众人：“在安息日行善行恶，救命害命，哪样是合法的呢？”他们都不作声。","notes":[]},{"n":5,"t":"耶稣怒目环视他们，因他们的心刚硬而忧伤，就对那人说：“伸出手来！”他把手一伸，手就复原了。","notes":[]},{"n":6,"t":"法利赛人出去，立刻同希律一党的人商议怎样除掉耶稣。","notes":[]},{"n":7,"t":"耶稣和门徒退到海边去，有许多人从加利利跟随他。还有许多人听见他所做的事，就从犹太、耶路撒冷、以土买、约旦河的东边，以及推罗和西顿的附近地方来到他那里。","notes":[],"end":8,"heads":["海边的群众"]},{"n":9,"t":"因为人多，他吩咐门徒为他预备一只小船，免得众人拥挤他。","notes":[]},{"n":10,"t":"他治好了许多人，所以凡有疾病的，都挤着要摸他。","notes":[]},{"n":11,"t":"每当污灵看见他，就俯伏在他面前，喊着说：“你是神的儿子。”","notes":[]},{"n":12,"t":"耶稣再三嘱咐他们不要把他宣扬出去。","notes":[]},{"n":13,"t":"耶稣上了山，把自己所要的人召来，他们就来到他那里。","notes":[],"heads":["拣选十二使徒"]},{"n":14,"t":"于是他设立十二个人，又称他们为使徒，要他们常和自己同在，也要差他们去传道，","notes":["有古卷没有“又称他们为使徒”。"]},{"n":15,"t":"并给他们权柄赶鬼。","notes":[]},{"n":16,"t":"他设立的十二个人有西门－耶稣又给他起名叫彼得，","notes":["有古卷没有“他设立的十二个人”。"]},{"n":17,"t":"还有西庇太的儿子雅各和雅各的弟弟约翰—耶稣又给他们起名叫半尼其，就是雷的儿子—","notes":[]},{"n":18,"t":"又有安得烈、腓力、巴多罗买、马太、多马、亚勒腓的儿子雅各、达太和激进党的西门，","notes":[]},{"n":19,"t":"还有出卖耶稣的加略人犹大。","notes":[]},{"n":20,"t":"耶稣进了屋子，众人又聚集，甚至他连饭也顾不得吃。","notes":[],"heads":["诬蔑耶稣为别西卜"]},{"n":21,"t":"耶稣的家人听见，就出来要拉住他，因为他们说他癫狂了。","notes":[]},{"n":22,"t":"从耶路撒冷下来的文士说：“他是被别西卜附身的”，又说：“他是靠着鬼王赶鬼的。”","notes":[]},{"n":23,"t":"耶稣叫他们来，用比喻对他们说：“撒但怎能赶出撒但呢？","notes":[]},{"n":24,"t":"一国若自相纷争，那国就立不住；","notes":[]},{"n":25,"t":"一家若自相纷争，那家就立不住。","notes":[]},{"n":26,"t":"撒但若自相攻打纷争，他就立不住，必定灭亡。","notes":[]},{"n":27,"t":"没有人能进壮士家里，抢夺他的东西；除非先绑住那壮士，否则无法抢夺他的家。","notes":[]},{"n":28,"t":"我实在告诉你们，世人一切的罪和一切亵渎的话都可以得到赦免；","notes":[]},{"n":29,"t":"凡亵渎圣灵的，却永不得赦免，而要担当永远的罪。”","notes":[]},{"n":30,"t":"因为他们说：“他是被污灵附身的。”","notes":[]},{"n":31,"t":"那时，耶稣的母亲和他兄弟来，站在外边，打发人去叫他。","notes":[],"heads":["遵父旨意的人都是亲属"]},{"n":32,"t":"有许多人在耶稣周围坐着，他们就告诉他说：“看哪！你母亲、你兄弟和你姊妹在外边找你。”","notes":["有古卷没有“和你姊妹”。"]},{"n":33,"t":"耶稣回答他们：“谁是我的母亲？谁是我的兄弟？”","notes":[]},{"n":34,"t":"就环视那周围坐着的人，说：“看哪，我的母亲，我的兄弟！","notes":[]},{"n":35,"t":"凡遵行神旨意的人就是我的兄弟姊妹和母亲。”","notes":[]}]},"4":{"heading":"撒种的比喻","verses":[{"n":1,"t":"耶稣又在海边教导人。有一大群人到他那里聚集，他只好上船坐下。船在海里，众人都靠近海，站在岸上。","notes":[]},{"n":2,"t":"耶稣就用许多比喻教导他们。在教导的时候，他对他们说：","notes":[]},{"n":3,"t":"“你们听啊，有一个撒种的出去撒种。","notes":[]},{"n":4,"t":"他撒的时候，有的落在路旁，飞鸟来把它吃掉了。","notes":[]},{"n":5,"t":"有的落在土浅的石头地上，因为土不深，很快就长出苗来，","notes":[]},{"n":6,"t":"太阳出来一晒，因为没有根就枯干了。","notes":[]},{"n":7,"t":"有的落在荆棘里，荆棘长起来，把它挤住了，就结不出果实。","notes":[]},{"n":8,"t":"又有的落在好土里，就发芽长大，结出果实，有三十倍的，有六十倍的，有一百倍的。”","notes":[]},{"n":9,"t":"耶稣又说：“有耳可听的，就应当听！”","notes":[]},{"n":10,"t":"耶稣独自一人的时候，跟随他的人和十二使徒问他这些比喻的意思。","notes":[],"heads":["用比喻的目的"]},{"n":11,"t":"耶稣对他们说：“神国的奥秘只让你们知道，若是对外人讲，凡事就用比喻，","notes":[]},{"n":12,"t":"要他们看了又看，却看不清，听了又听，却不明白，免得他们回转过来，获得赦免。”","notes":[]},{"n":13,"t":"耶稣又对他们说：“你们不明白这比喻吗？这样怎能明白一切的比喻呢？","notes":[],"heads":["解释撒种的比喻"]},{"n":14,"t":"撒种的人所撒的就是道。","notes":[]},{"n":15,"t":"那撒在路旁的种子，就是人听了道，撒但立刻来，把撒在他们心里的道夺了去。","notes":[]},{"n":16,"t":"那撒在石头地上的，就是人听了道，立刻欢喜领受，","notes":[]},{"n":17,"t":"因心里没有根，不过是暂时的，一旦为道遭受患难或迫害，立刻就跌倒。","notes":[]},{"n":18,"t":"还有那撒在荆棘里的，就是人听了道，","notes":[]},{"n":19,"t":"后来有世上的忧虑、钱财的迷惑，和别样的私欲进来，把道挤住了，结不出果实。","notes":[]},{"n":20,"t":"那撒在好土里的，就是人听了道，领受了，并且结了果实，有三十倍的，有六十倍的，有一百倍的。”","notes":[]},{"n":21,"t":"耶稣又对他们说：“人拿灯来，难道是要放在斗底下，床底下，而不放在灯台上吗？","notes":[],"heads":["斗下的灯"]},{"n":22,"t":"因为掩藏的事没有不显出来的，隐瞒的事也没有不露出来的。","notes":[]},{"n":23,"t":"有耳可听的，就应当听！”","notes":[]},{"n":24,"t":"他又说：“你们要留心所听的。你们用什么量器来量，也将要用什么来量给你们，并且要多给你们。","notes":[]},{"n":25,"t":"因为有的，还要给他；没有的，连他所有的也要夺去。”","notes":[]},{"n":26,"t":"耶稣又说：“神的国如同人把种子撒在地上，","notes":[],"heads":["种子长大的比喻"]},{"n":27,"t":"黑夜睡觉，白日起来，这种子就发芽生长，那人却不知道如何会这样。","notes":[]},{"n":28,"t":"土地自然而然地出产五谷，先发苗，后长穗，然后穗上结成饱满的谷子。","notes":[]},{"n":29,"t":"五谷熟了，就用镰刀去割，因为收成的时候到了。”","notes":[]},{"n":30,"t":"耶稣又说：“我们可用什么来比拟神的国呢？可用什么比喻来说明呢？","notes":[],"heads":["芥菜种的比喻"]},{"n":31,"t":"它像一粒芥菜种，种在地里的时候，虽比地上所有的种子都小，","notes":[]},{"n":32,"t":"但种下去以后，它长起来，比各样的菜都大，又长出大枝，以致天上的飞鸟可以在它的荫下筑巢。”","notes":[]},{"n":33,"t":"耶稣用许多这样的比喻，照他们所能听的，对他们讲道；","notes":[],"heads":["用比喻讲道"]},{"n":34,"t":"若不用比喻，他就不对他们讲，但私下没有人的时候，就把一切的道讲给门徒听。","notes":[]},{"n":35,"t":"那天晚上，耶稣对门徒说：“我们渡到对岸去吧。”","notes":[],"heads":["平静风和海"]},{"n":36,"t":"门徒离开众人，耶稣已在船上，他们就请他一同去；也有别的船和他同行。","notes":[]},{"n":37,"t":"忽然狂风大作，波浪打入船内，以致船灌满了水。","notes":[]},{"n":38,"t":"耶稣在船尾上，枕着枕头睡觉。门徒叫醒他，说：“老师！我们快没命了，你不管吗？”","notes":[]},{"n":39,"t":"耶稣醒了，斥责那风，向海说：“住了吧！静了吧！”风就止住，大大平静了。","notes":[]},{"n":40,"t":"耶稣对他们说：“为什么胆怯？你们还没有信心吗？”","notes":[]},{"n":41,"t":"他们就非常惧怕，彼此说：“这到底是谁？连风和海都听从他。”","notes":[]}]},"5":{"heading":"治好格拉森污灵附身的人","verses":[{"n":1,"t":"他们渡到海的对岸，到格拉森人的地区。","notes":["有古卷是“加大拉人”；另有古卷是“格各森人”。"]},{"n":2,"t":"耶稣一下船，就有一个污灵附身的人从坟墓迎着他走来。","notes":[]},{"n":3,"t":"那人常住在坟墓里，没有人能捆住他，就是用铁链也不能；","notes":[]},{"n":4,"t":"因为人屡次用脚镣和铁链捆锁他，铁链被他挣断，脚镣也被他弄碎了，总没有人能制伏他。","notes":[]},{"n":5,"t":"他昼夜常在坟墓里和山中喊叫，又用石头打自己。","notes":[]},{"n":6,"t":"他远远看见耶稣，就跑过来拜他，","notes":[]},{"n":7,"t":"大声呼叫说：“至高神的儿子耶稣，你为什么干扰我？我指着神恳求你，不要叫我受苦！”","notes":[]},{"n":8,"t":"这是因耶稣曾吩咐他说：“污灵啊，从这人身上出来！”","notes":[]},{"n":9,"t":"耶稣问他：“你叫什么名字？”他说：“我名叫群，因为我们数目众多。”","notes":[]},{"n":10,"t":"他就再三求耶稣不要叫他们离开那地方。","notes":[]},{"n":11,"t":"在山坡那里，有一大群猪正在吃食；","notes":[]},{"n":12,"t":"污灵就央求耶稣，说：“求你打发我们进入猪群，好附着它们。”","notes":[]},{"n":13,"t":"耶稣准了他们，污灵就出来，进入猪里，那群猪就闯下山崖，投进海里，淹死了。猪的数目约有二千。","notes":[]},{"n":14,"t":"放猪的逃跑了，去告诉城里和乡下的人。众人就来，要看发生了什么事。","notes":[]},{"n":15,"t":"他们来到耶稣那里，看见那被鬼附的人，就是曾被群鬼所附的，坐着，穿着衣服，神智清醒，他们就害怕。","notes":[]},{"n":16,"t":"看见这事的人把被鬼附的人所遇见的，和那群猪的事，都告诉了众人，","notes":[]},{"n":17,"t":"众人就央求耶稣离开他们的地区。","notes":[]},{"n":18,"t":"耶稣上船的时候，那曾被鬼附的人恳求要和耶稣在一起。","notes":[]},{"n":19,"t":"耶稣不许，却对他说：“你回家去，到你的亲友那里，将主为你所做多么大的事和他怎样怜悯你，都告诉他们。”","notes":[]},{"n":20,"t":"那人就走了，开始在低加坡里传扬耶稣为他做了多么大的事，众人就都惊讶。","notes":[]},{"n":21,"t":"耶稣又坐船渡到对岸，有一大群人聚集到他身边；他正在海边。","notes":["有古卷没有“坐船”。"],"heads":["叶鲁的女儿和经血不止的女人"]},{"n":22,"t":"有一个会堂主管，名叫叶鲁，也来了，一见到耶稣，就俯伏在他脚前，","notes":[]},{"n":23,"t":"再三求他，说：“我的小女儿快要死了，求你去为她按手，使她痊愈，可以活下去。”","notes":[]},{"n":24,"t":"耶稣就和他同去。有一大群人跟随他，拥挤着他。","notes":[]},{"n":25,"t":"有一个女人，患了经血不止的病有十二年，","notes":[]},{"n":26,"t":"在好多医生手里受了许多苦，又花尽了她所有的，一点也不见好，反而更重了。","notes":[]},{"n":27,"t":"她听见耶稣的事，就夹在众人中间，从后面来摸耶稣的衣裳，","notes":[]},{"n":28,"t":"因她想：“我只摸到他的衣裳，就会痊愈。”","notes":[]},{"n":29,"t":"于是她的流血立刻止住，她觉得身上的疾病好了。","notes":[]},{"n":30,"t":"耶稣顿时心里觉得有能力从自己身上出去，就在众人中间转过来，说：“谁摸我的衣裳？”","notes":[]},{"n":31,"t":"门徒对他说：“你看众人拥挤着你，还说‘谁摸我’呢？”","notes":[]},{"n":32,"t":"耶稣周围观看，要见做这事的女人。","notes":[]},{"n":33,"t":"那女人知道在自己身上所成的事，就恐惧战兢，来俯伏在耶稣跟前，将实情全告诉他。","notes":[]},{"n":34,"t":"耶稣对她说：“女儿，你的信救了你，平安地回去吧！你的疾病痊愈了。”","notes":[]},{"n":35,"t":"耶稣还在说话的时候，有人从会堂主管的家里来，说：“你的女儿死了，何必还劳驾老师呢？”","notes":[]},{"n":36,"t":"耶稣不理会他们所说的话，就对会堂主管说：“不要怕，只要信！”","notes":[]},{"n":37,"t":"于是他带着彼得、雅各和雅各的弟弟约翰同去，不许别人跟着他。","notes":[]},{"n":38,"t":"他们来到会堂主管的家里，耶稣看到一片吵闹，并有人大声哭泣哀号，","notes":[]},{"n":39,"t":"就进到里面，对他们说：“为什么大吵大哭呢？孩子不是死了，是睡着了。”","notes":[]},{"n":40,"t":"他们就嘲笑耶稣。耶稣把他们都赶出去，带着孩子的父母和跟随的人进了孩子所在的地方，","notes":[]},{"n":41,"t":"就拉着孩子的手，对她说：“大利大，古米！”翻出来就是说：“女孩，我吩咐你，起来！”","notes":[]},{"n":42,"t":"那女孩子立刻起来走动—她已经十二岁了；他们就非常惊奇。","notes":[]},{"n":43,"t":"耶稣切切地嘱咐他们，不要让人知道这事，又吩咐给她东西吃。","notes":[]}]},"6":{"heading":"拿撒勒人厌弃耶稣","verses":[{"n":1,"t":"耶稣离开那里，来到自己的家乡；门徒也跟从他。","notes":[]},{"n":2,"t":"到了安息日，他在会堂里教导人。众人听见，就很惊奇，说：“这人哪来这本事呢？所赐给他的是什么智慧？他手所做的是何等的异能呢？","notes":[]},{"n":3,"t":"这不是那木匠吗？不是马利亚的儿子雅各、约西、犹大、西门的长兄吗？他姊妹们不也是在我们这里吗？”他们就厌弃他。","notes":[]},{"n":4,"t":"耶稣对他们说：“先知除了在本乡、本族和自己的家之外，没有不被尊敬的。”","notes":[]},{"n":5,"t":"耶稣在那里不能行什么异能，不过为几个病人按手，治好他们。","notes":[]},{"n":6,"t":"他也诧异他们不信。耶稣走遍周围乡村教导人。","notes":[]},{"n":7,"t":"他叫了十二个使徒来，差遣他们两个两个地出去，也赐给他们权柄制伏污灵，","notes":[]},{"n":8,"t":"并且吩咐他们：途中不要带食物和行囊，腰袋里也不要带钱，除了手杖以外，什么都不要带；","notes":[]},{"n":9,"t":"只要穿鞋子，也不要穿两件内衣。","notes":[]},{"n":10,"t":"他又对他们说：“你们无论到何处，进哪家，就住在哪里，直到离开那地方。","notes":[]},{"n":11,"t":"若有什么地方的人不接待你们，不听你们，你们离开那里的时候，要跺掉你们脚上的尘土，证明他们的不是。”","notes":[]},{"n":12,"t":"使徒就出去传道，叫人悔改，","notes":[]},{"n":13,"t":"又赶出许多鬼，用油抹了许多病人，治好他们。","notes":[]},{"n":14,"t":"耶稣的名声传开了，希律王也听见。有人说：“施洗的约翰从死人中复活了，因此才有这些异能在他里面运行。”","notes":[],"heads":["施洗约翰之死"]},{"n":15,"t":"但别人说：“他是以利亚。”又有人说：“是先知，正如先知中的一位。”","notes":[]},{"n":16,"t":"希律听见却说：“是我所斩的约翰，他复活了。”","notes":[]},{"n":17,"t":"原来，希律为他兄弟腓力的妻子希罗底的缘故，派人去抓了约翰，把他绑了在监狱里，因为希律已经娶了那妇人。","notes":[]},{"n":18,"t":"约翰曾对希律说：“你占有你兄弟的妻子是不合法的。”","notes":[]},{"n":19,"t":"于是希罗底怀恨他，想要杀他，只是不能。","notes":[]},{"n":20,"t":"因为希律怕约翰，知道他是义人，是圣人，所以就保护他，虽然听了他的讲论十分困惑，仍然乐意听他。","notes":["“十分困惑”：有古卷是“也做了许多事”。"]},{"n":21,"t":"有一天，恰巧是希律的生日，希律摆设宴席，请了大臣、千夫长和加利利的领袖。","notes":[]},{"n":22,"t":"他的女儿希罗底进来跳舞，使希律和同席的人都很高兴。王就对女孩说：“无论你要什么，向我求，我都会给你”；","notes":["有古卷是“希罗底自己的女儿”；另有古卷是“希罗底的女儿”。"]},{"n":23,"t":"又对她多次起誓说：“无论你向我求什么，就是我国家的一半，我也会给你。”","notes":["有古卷没有“多次”。"]},{"n":24,"t":"她就出去对她母亲说：“我该求什么呢？”她母亲说：“施洗约翰的头。”","notes":[]},{"n":25,"t":"她就急忙进去见王，求他说：“我愿王立刻把施洗约翰的头放在盘子里给我。”","notes":[]},{"n":26,"t":"王就很忧愁，然而因他所发的誓，又因同席的人，不愿食言，","notes":[]},{"n":27,"t":"就立刻派一个卫兵，吩咐拿约翰的头来。卫兵就去，在监狱里斩了约翰，","notes":[]},{"n":28,"t":"把头放在盘子里，拿来给那女孩，她就给她母亲。","notes":[]},{"n":29,"t":"约翰的门徒听到了，就来把他的尸体领去，放在坟墓里。","notes":[]},{"n":30,"t":"使徒们聚集到耶稣那里，把一切所做的事、所传的道全告诉他。","notes":[],"heads":["耶稣使五千人吃饱"]},{"n":31,"t":"他就说：“你们来，同我私下到荒野的地方去歇一歇。”这是因为来往的人多，他们连吃饭的时间也没有。","notes":[]},{"n":32,"t":"他们就坐船，私下往荒野的地方去。","notes":[]},{"n":33,"t":"众人看见他们走了，有许多认识他们的，就从各城步行，一同跑到那里，比他们先赶到了。","notes":[]},{"n":34,"t":"耶稣出来，见有一大群的人，就怜悯他们，因为他们如同羊没有牧人一般，于是开始教导他们许多事。","notes":[]},{"n":35,"t":"天已经很晚，门徒进前来，说：“这地方偏僻，而且天已经很晚了，","notes":[]},{"n":36,"t":"请叫众人散去，他们好往四面的乡镇村庄去，自己买些东西吃。”","notes":[]},{"n":37,"t":"耶稣回答他们说：“你们给他们吃吧！”门徒对他说：“我们要拿两百个银币去买饼给他们吃吗？”","notes":[]},{"n":38,"t":"耶稣说：“你们有多少饼？去看看。”他们知道后就说：“有五个，还有两条鱼。”","notes":[]},{"n":39,"t":"耶稣吩咐他们，叫众人一组一组地坐在青草地上。","notes":[]},{"n":40,"t":"众人就一群一群地坐下，有一百的，有五十的。","notes":[]},{"n":41,"t":"耶稣拿着这五个饼和两条鱼，望着天祝福，擘开饼，递给门徒，摆在众人面前，也把那两条鱼分给众人。","notes":[]},{"n":42,"t":"他们都吃，并且吃饱了。","notes":[]},{"n":43,"t":"门徒把饼和鱼的碎屑收拾起来，装满了十二个篮子。","notes":[]},{"n":44,"t":"吃饼的男人共有五千。","notes":[]},{"n":45,"t":"耶稣随即催门徒上船，先渡到对岸，到伯赛大去，等他叫众人散去。","notes":[],"heads":["耶稣在海上行走"]},{"n":46,"t":"他辞别了他们，就往山上去祷告。","notes":[]},{"n":47,"t":"到了晚上，船在海中，耶稣独自在岸上。","notes":[]},{"n":48,"t":"他看见门徒因风不顺，摇橹很苦。天快亮的时候，他在海面上走，往他们那里去，想要超过他们。","notes":[]},{"n":49,"t":"但门徒看见他在海面上走，以为是鬼怪，就喊叫起来；","notes":[]},{"n":50,"t":"因为他们都看见了他，甚为惊慌。耶稣连忙对他们说：“放心！是我，不要怕！”","notes":[]},{"n":51,"t":"于是他到他们那里，一上船，风就停了；他们心里十分惊奇。","notes":[]},{"n":52,"t":"这是因为他们不明白那分饼的事，心里还是愚顽。","notes":[]},{"n":53,"t":"他们渡过了海，在革尼撒勒靠岸，泊了船，","notes":[],"heads":["治好革尼撒勒的病人"]},{"n":54,"t":"他们一下来，众人立刻认出是耶稣，","notes":[]},{"n":55,"t":"就跑遍那整个地区，听到他在哪里，就把有病的人用褥子抬到哪里。","notes":[]},{"n":56,"t":"耶稣所到的地方，或村中、或城里、或乡间，他们都把病人放在街市上，求耶稣让他们摸一摸他的衣裳繸子，摸着的人就都好了。","notes":[]}]},"7":{"heading":"论古人的传统","verses":[{"n":1,"t":"有法利赛人和几个从耶路撒冷来的文士聚集到耶稣那里。","notes":[]},{"n":2,"t":"他们曾看见他的门徒中有人用不洁净的手，就是没有洗的手吃饭。","notes":[]},{"n":3,"t":"法利赛人和所有的犹太人都拘守古人的传统，若不按规矩洗手就不吃饭；","notes":[]},{"n":4,"t":"从市场来，若不洗净也不吃饭；他们还拘守好些别的规矩，如洗杯、罐、铜器、床铺等。","notes":["有古卷没有“床铺”。"]},{"n":5,"t":"法利赛人和文士问他说：“你的门徒为什么不照古人的传统，竟然用不洁净的手吃饭呢？”","notes":[]},{"n":6,"t":"耶稣对他们说：“以赛亚指着你们假冒为善的人所预言的说得好。如经上所记：‘这百姓用嘴唇尊敬我，他们的心却远离我。","notes":[]},{"n":7,"t":"他们把人的规条当作教义教导人；他们拜我也是枉然。’","notes":[]},{"n":8,"t":"你们是离弃神的诫命，拘守人的传统。”","notes":[]},{"n":9,"t":"耶稣又说：“你们诚然是废弃神的诫命，为要守自己的传统。","notes":[]},{"n":10,"t":"摩西说：‘当孝敬父母’；又说：‘咒骂父母的，必须处死。’","notes":[]},{"n":11,"t":"你们倒说：‘人若对父母说：我所当供奉你的已经作了各耳板’（各耳板就是奉献的意思），","notes":[]},{"n":12,"t":"你们就容许他不必再奉养父母。","notes":[]},{"n":13,"t":"这就是你们藉着继承传统，废了神的话。你们还做许多这样的事。”","notes":[]},{"n":14,"t":"耶稣又叫众人来，对他们说：“你们都要听我的话，也要明白。","notes":[]},{"n":15,"t":"从外面进去的不能玷污人，惟有从里面出来的才玷污人。”","notes":["有古卷加“16 有耳可听的，就应当听！”"]},{"n":17,"t":"耶稣离开众人，进了屋子，门徒就问他这比喻的意思。","notes":[]},{"n":18,"t":"耶稣对他们说：“你们也是这样不明白吗？难道你们不了解，凡从外面进去的不能玷污人吗？","notes":[]},{"n":19,"t":"因为不是进入他的心，而是进入他的肚子，又排入厕所。”（这是说，各样的食物都是洁净的。）","notes":[]},{"n":20,"t":"耶稣又说：“从人里面出来的，那才玷污人；","notes":[]},{"n":21,"t":"因为从人心里发出种种恶念，如淫乱、偷盗、凶杀、","notes":[]},{"n":22,"t":"奸淫、贪婪、邪恶、诡诈、淫荡、嫉妒、毁谤、骄傲、狂妄。","notes":[]},{"n":23,"t":"这一切的恶都是从里面出来，且能玷污人。”","notes":[]},{"n":24,"t":"耶稣从那里起身，往推罗境内去，进了一家，他不愿意人知道，却隐藏不住。","notes":["有古卷加“西顿”。"],"heads":["腓尼基妇人的信心"]},{"n":25,"t":"立刻有一个妇人，她的小女儿被污灵附着，一听见耶稣的事，就来俯伏在他脚前。","notes":[]},{"n":26,"t":"这妇人是希腊人，属叙利亚的腓尼基族。她求耶稣从她女儿身上赶出那鬼。","notes":[]},{"n":27,"t":"耶稣对她说：“让孩子们先吃饱，拿孩子的饼丢给小狗吃是不妥的。”","notes":[]},{"n":28,"t":"妇人回答：“主啊，桌子底下的小狗也吃小孩子的碎屑呀！”","notes":[]},{"n":29,"t":"耶稣对她说：“凭着这句话，你回去吧，鬼已经离开你的女儿了。”","notes":[]},{"n":30,"t":"她就回家去，见小孩子躺在床上，鬼已经出去了。","notes":[]},{"n":31,"t":"耶稣又离开了推罗地区，经过西顿，就从低加坡里境内来到加利利海。","notes":[],"heads":["耶稣治好耳聋舌结的人"]},{"n":32,"t":"有人带着一个耳聋舌结的人来见耶稣，求他为他按手。","notes":[]},{"n":33,"t":"耶稣领他离开众人，到一边去，就用指头探他的耳朵，吐唾沫抹他的舌头，","notes":[]},{"n":34,"t":"望天叹息，对他说：“以法大！”就是说“开了吧！”","notes":[]},{"n":35,"t":"他的耳朵立刻开了，舌结也解了，他说话也清楚了。","notes":["有古卷没有“立刻”。"]},{"n":36,"t":"耶稣嘱咐他们不要告诉人；但他越嘱咐，他们越发传扬。","notes":[]},{"n":37,"t":"众人分外惊奇，说：“他所做的事样样都好，他甚至使聋子听见，哑巴说话。”","notes":[]}]},"8":{"heading":"耶稣使四千人吃饱","verses":[{"n":1,"t":"那时，又有一大群人聚集，没有什么吃的。耶稣叫门徒来，说：","notes":[]},{"n":2,"t":"“我怜悯这群人，因为他们同我在这里已经三天，没有吃的东西了。","notes":[]},{"n":3,"t":"我若叫他们饿着回家，他们会在路上饿昏，因为其中有从远处来的。”","notes":[]},{"n":4,"t":"门徒回答：“在这野地，从哪里能得饼使这些人吃饱呢？”","notes":[]},{"n":5,"t":"耶稣问他们：“你们有多少饼？”他们说：“七个。”","notes":[]},{"n":6,"t":"他吩咐众人坐在地上，就拿着这七个饼祝谢了，擘开，递给门徒，叫他们摆开，门徒就摆在众人面前。","notes":[]},{"n":7,"t":"他们还有几条小鱼；耶稣祝谢了，就吩咐也摆在众人面前。","notes":[]},{"n":8,"t":"他们都吃，并且吃饱了，收拾剩下的碎屑，有七筐子。","notes":[]},{"n":9,"t":"人数约有四千。耶稣打发他们走了，","notes":[]},{"n":10,"t":"随即同门徒上船，来到大玛努他境内。","notes":[]},{"n":11,"t":"法利赛人出来盘问耶稣，要求他从天上显个神迹给他们看，想要试探他。","notes":[],"heads":["法利赛人求神迹"]},{"n":12,"t":"耶稣心里深深叹息，说：“这世代为什么求神迹呢？我实在告诉你们，没有神迹给这世代看。”","notes":[]},{"n":13,"t":"他就离开他们，又上船往海的对岸去了。","notes":[]},{"n":14,"t":"门徒忘了带饼，在船上除了一个饼，没有别的食物。","notes":[],"heads":["防备法利赛人和希律的酵"]},{"n":15,"t":"耶稣嘱咐他们说：“你们要谨慎，要防备法利赛人的酵和希律的酵。”","notes":[]},{"n":16,"t":"他们彼此议论说：“这是因为我们没有饼吧。”","notes":[]},{"n":17,"t":"耶稣知道了，就说：“你们为什么因为没有饼就议论呢？你们还不领悟，还不明白吗？你们的心还是愚顽吗？","notes":[]},{"n":18,"t":"你们有眼睛，看不见吗？有耳朵，听不到吗？也不记得吗？","notes":[]},{"n":19,"t":"我擘开那五个饼分给五千人，你们收拾的碎屑装满了多少个篮子呢？”他们说：“十二个。”","notes":[]},{"n":20,"t":"“又擘开那七个饼分给四千人，你们收拾的碎屑装满了多少个筐子呢？”他们说：“七个。”","notes":[]},{"n":21,"t":"耶稣说：“你们还不明白吗？”","notes":[]},{"n":22,"t":"他们来到伯赛大，有人带一个盲人来，求耶稣摸他。","notes":[],"heads":["治好伯赛大的盲人"]},{"n":23,"t":"耶稣拉着盲人的手，领他到村外，就吐唾沫在他眼睛上，为他按手，问他：“你看见什么？”","notes":[]},{"n":24,"t":"他抬头一看，说：“我看见人，他们好像树木，并且行走。”","notes":[]},{"n":25,"t":"随后耶稣又按手在他眼睛上，他定睛一看，就复原了，样样都看得清楚了。","notes":[]},{"n":26,"t":"耶稣打发他回家，说：“连这村子你也不要进去。”","notes":[]},{"n":27,"t":"耶稣和门徒出去，往凯撒利亚．腓立比附近的村庄去。在路上，他问门徒：“人们说我是谁？”","notes":[],"heads":["彼得认耶稣为基督"]},{"n":28,"t":"他们对他说：“是施洗的约翰；有人说是以利亚；又有人说是先知中的一位。”","notes":[]},{"n":29,"t":"他又问他们：“你们说我是谁？”彼得回答他：“你是基督。”","notes":[]},{"n":30,"t":"于是耶稣切切地嘱咐他们不可对任何人说起他。","notes":[]},{"n":31,"t":"从此，他教导他们说：“人子必须受许多的苦，被长老、祭司长和文士弃绝，并且被杀，三天后复活。”","notes":[],"heads":["耶稣预言受难和复活"]},{"n":32,"t":"耶稣明白地说了这话，彼得就拉着他，责备他。","notes":[]},{"n":33,"t":"耶稣转过来看着门徒，斥责彼得说：“撒但，退到我后边去！因为你不体会神的心意，而是体会人的意思。”","notes":[]},{"n":34,"t":"于是他叫众人和门徒来，对他们说：“若有人要跟从我，就当舍己，背起自己的十字架来跟从我。","notes":[]},{"n":35,"t":"因为凡要救自己生命的，必丧失生命；凡为我和福音丧失生命的，必救自己的生命。","notes":[]},{"n":36,"t":"人就是赚得全世界，赔上自己的生命，有什么益处呢？","notes":[]},{"n":37,"t":"人还能拿什么换生命呢？","notes":[]},{"n":38,"t":"凡在这淫乱罪恶的世代，把我和我的道当作可耻的，人子在他父的荣耀里与圣天使一同来临的时候，也要把那人当作可耻的。”","notes":[]}]},"9":{"heading":"耶稣登山显荣","verses":[{"n":1,"t":"耶稣又对他们说：“我实在告诉你们，站在这里的，有人在没经历死亡以前，必定看见神的国带着能力临到。”","notes":[]},{"n":2,"t":"过了六天，耶稣带着彼得、雅各、约翰，领他们悄悄地上了高山。他在他们面前变了形像，","notes":[]},{"n":3,"t":"衣服放光，极其洁白，地上漂布的人没有一个能漂得那样白。","notes":[]},{"n":4,"t":"有以利亚和摩西向他们显现，并且与耶稣说话。","notes":[]},{"n":5,"t":"彼得对耶稣说：“拉比，我们在这里真好！我们来搭三座棚，一座为你，一座为摩西，一座为以利亚。”","notes":["“拉比”意思是“老师”。"]},{"n":6,"t":"彼得不知道说什么才好，因为他们很害怕。","notes":[]},{"n":7,"t":"有一朵云彩来遮盖他们，又有声音从云彩里出来，说：“这是我的爱子，你们要听从他！”","notes":[]},{"n":8,"t":"门徒连忙向周围观看，不再看见任何人，只见耶稣同他们在一起。","notes":[]},{"n":9,"t":"下山的时候，耶稣嘱咐他们说：“人子还没有从死人中复活，你们不要把所看到的告诉人。”","notes":[]},{"n":10,"t":"门徒将这话存记在心，彼此议论“从死人中复活”是什么意思。","notes":[]},{"n":11,"t":"他们就问耶稣：“文士为什么说以利亚必须先来？”","notes":[]},{"n":12,"t":"耶稣说：“以利亚的确先来复兴万事。经上不是指着人子说，他要受许多的苦和被人轻慢吗？","notes":[]},{"n":13,"t":"我告诉你们，以利亚已经来了，他们任意待他，正如经上指着他说的。”","notes":[]},{"n":14,"t":"他们到了门徒那里，看见有一大群人围着他们，又有文士和他们辩论。","notes":[],"heads":["治好污灵附身的孩子"]},{"n":15,"t":"众人一见耶稣，都很惊奇，就跑上去向他问安。","notes":[]},{"n":16,"t":"耶稣问他们：“你们和他们辩论什么？”","notes":[]},{"n":17,"t":"众人中的一个回答：“老师，我带了我的儿子到你这里来，他被哑巴的灵附着。","notes":[]},{"n":18,"t":"无论在哪里，那灵拿住他，把他摔倒，他就口吐白沫，牙关紧锁，身体僵硬。我请过你的门徒把那灵赶出去，他们却不能。”","notes":[]},{"n":19,"t":"耶稣回答：“唉！这不信的世代啊，我和你们在一起要到几时呢？我忍耐你们要到几时呢？把他带到我这里！”","notes":[]},{"n":20,"t":"他们就带了他来。那灵一见耶稣，就使他重重地抽风，倒在地上，翻来覆去，口吐白沫。","notes":[]},{"n":21,"t":"耶稣问他父亲：“他得这病有多久了呢？”父亲说：“从小的时候。","notes":[]},{"n":22,"t":"那灵屡次把他扔在火里、水里，要治死他。你若能做什么，求你怜悯我们，帮助我们。”","notes":[]},{"n":23,"t":"耶稣对他说：“‘你若能’，在信的人，凡事都能。”","notes":[]},{"n":24,"t":"孩子的父亲立刻喊着说：“我信；求你帮助我的不信！”","notes":[]},{"n":25,"t":"耶稣看见众人都跑上来，就斥责那污灵说：“你这聋哑的灵，我命令你从他里头出来，再不要进去！”","notes":[]},{"n":26,"t":"那灵大喊一声，使孩子猛烈地抽了一阵风，就出来了。孩子好像死了一般，以致众人多半说：“他死了。”","notes":[]},{"n":27,"t":"但耶稣拉着他的手，扶他起来，他就站起来了。","notes":[]},{"n":28,"t":"耶稣进了屋子，门徒就私下问他：“我们为什么不能赶出那灵呢？”","notes":[]},{"n":29,"t":"耶稣对他们说：“非用祷告，这一类的邪灵总赶不出来。”","notes":["有古卷加“禁食”。"]},{"n":30,"t":"他们离开那地方，经过加利利；耶稣不愿意人知道，","notes":[],"heads":["耶稣第二次预言受难和复活"]},{"n":31,"t":"因为他正教导门徒说：“人子将要被交在人手里，他们要杀害他；被杀以后，三天后他要复活。”","notes":[]},{"n":32,"t":"门徒却不明白这话，又不敢问他。","notes":[]},{"n":33,"t":"他们来到迦百农。耶稣在屋里问门徒说：“你们在路上议论的是什么？”","notes":[],"heads":["谁最大"]},{"n":34,"t":"门徒不作声，因为他们在路上彼此争论谁最大。","notes":[]},{"n":35,"t":"耶稣坐下，叫十二个使徒来，说：“若有人愿意为首，他要作众人之后，作众人的用人。”","notes":[]},{"n":36,"t":"于是耶稣领一个小孩过来，让他站在门徒当中，又抱起他来，对他们说：","notes":[]},{"n":37,"t":"“凡为我的名接纳一个像这小孩子的，就是接纳我；凡接纳我的，不是接纳我，而是接纳那差我来的。”","notes":[]},{"n":38,"t":"约翰对耶稣说：“老师，我们看见一个人奉你的名赶鬼，我们就阻止他，因为他不跟从我们。”","notes":[],"heads":["不抵挡我们就是帮助我们"]},{"n":39,"t":"耶稣说：“不要阻止他，因为没有人奉我的名行异能，反倒轻易毁谤我。","notes":[]},{"n":40,"t":"不抵挡我们的，就是帮助我们的。","notes":[]},{"n":41,"t":"凡因你们是属基督，给你们一杯水喝的，我实在告诉你们，他一定会得到赏赐。”","notes":[]},{"n":42,"t":"“凡使这些信我的小子中的一个跌倒的，倒不如把大磨石拴在这人的颈项上，扔在海里。","notes":["“这些…小子”：有古卷是“这些有信心的小子”。"],"heads":["拒绝罪的诱惑"]},{"n":43,"t":"如果你一只手使你跌倒，就把它砍下来；你缺一只手进入永生，比有两只手落到地狱，入那不灭的火里去还好。","notes":["有古卷加44节，经文与48节同。"]},{"n":45,"t":"如果你一只脚使你跌倒，就把它砍下来；你瘸腿进入永生，比有两只脚被扔进地狱里还好。","notes":["有古卷加46节，经文与48节同。"]},{"n":47,"t":"如果你一只眼使你跌倒，就去掉它；你只有一只眼进入神的国，比有两只眼被扔进地狱里还好。","notes":[]},{"n":48,"t":"在那里，虫是不死的，火是不灭的。","notes":[]},{"n":49,"t":"因为每个人必被火像盐一般腌起来。","notes":["有古卷加“凡祭物必用盐腌。”"]},{"n":50,"t":"盐本是好的，若失了咸味，你们怎能用它调味呢？你们中间要有盐，彼此和睦。”","notes":[]}]},"10":{"heading":"休妻的问题","verses":[{"n":1,"t":"耶稣从那里起身，来到犹太的境内，约旦河的东边。众人又聚集到他那里，他又照常教导他们。","notes":[]},{"n":2,"t":"有法利赛人来问他说：“男人休妻合不合法？”意思是要试探他。","notes":[]},{"n":3,"t":"耶稣回答他们说：“摩西吩咐你们的是什么？”","notes":[]},{"n":4,"t":"他们说：“摩西准许写了休书就可以休妻。”","notes":[]},{"n":5,"t":"耶稣对他们说：“摩西因为你们的心硬，所以写这诫命给你们。","notes":[]},{"n":6,"t":"但从起初创造的时候，神造人是造男造女。","notes":[]},{"n":7,"t":"因此，人要离开他的父母，与妻子结合，","notes":["有古卷没有“与妻子结合”。"]},{"n":8,"t":"二人成为一体。既然如此，夫妻不再是两个人，而是一体的了。","notes":[]},{"n":9,"t":"所以，神配合的，人不可分开。”","notes":[]},{"n":10,"t":"他们到了屋里，门徒又问他这事。","notes":[]},{"n":11,"t":"耶稣对他们说：“凡休妻另娶的，就是犯奸淫，辜负他的妻子；","notes":[]},{"n":12,"t":"妻子若离弃丈夫另嫁，也是犯奸淫了。”","notes":[]},{"n":13,"t":"有人带着小孩子来见耶稣，要他摸他们，门徒就责备那些人。","notes":[],"heads":["耶稣为小孩祝福"]},{"n":14,"t":"耶稣看见就很生气，对门徒说：“让小孩到我这里来，不要阻止他们，因为在神国的正是这样的人。","notes":[]},{"n":15,"t":"我实在告诉你们，凡要接受神国的，若不像小孩子，绝不能进去。”","notes":[]},{"n":16,"t":"于是他抱着小孩子，给他们按手，为他们祝福。","notes":[]},{"n":17,"t":"耶稣刚上路的时候，有一个人跑来，跪在他面前，问他：“善良的老师，我该做什么事才能承受永生？”","notes":[],"heads":["财主寻求永生"]},{"n":18,"t":"耶稣对他说：“你为什么称我是善良的？除了神一位之外，再没有善良的。","notes":[]},{"n":19,"t":"诫命你是知道的：‘不可杀人；不可奸淫；不可偷盗；不可作假见证；不可亏负人；当孝敬父母。’”","notes":[]},{"n":20,"t":"他对耶稣说：“老师，这一切我从小都遵守了。”","notes":[]},{"n":21,"t":"耶稣看着他，就爱他，对他说：“你还缺少一件：去变卖你所有的，分给穷人，就必有财宝在天上；然后来跟从我。”","notes":[]},{"n":22,"t":"他听见这话，脸就变了色，忧忧愁愁地走了，因为他的产业很多。","notes":[]},{"n":23,"t":"耶稣看了看周围，对门徒说：“有钱财的人进神的国是何等的难哪！”","notes":[]},{"n":24,"t":"门徒对他的话非常惊奇。耶稣又对他们说：“孩子们，要进神的国是何等的难哪！","notes":["有古卷加“倚靠钱财的人”。"]},{"n":25,"t":"骆驼穿过针眼比财主进神的国还容易呢！”","notes":[]},{"n":26,"t":"门徒就更为惊讶，彼此对问：“这样，谁能得救呢？”","notes":[]},{"n":27,"t":"耶稣看着他们，说：“在人不能，在神却不然，因为在神凡事都能。”","notes":[]},{"n":28,"t":"彼得就对他说：“看哪，我们已经撇下一切跟从你了。”","notes":[]},{"n":29,"t":"耶稣说：“我实在告诉你们，凡为我和福音撇下房屋，或是兄弟、姊妹、父亲、母亲、儿女、田地，","notes":[]},{"n":30,"t":"没有不在今世得百倍的，就是房屋、兄弟、姊妹、母亲、儿女、田地，并且要受迫害，在来世得永生。","notes":[]},{"n":31,"t":"然而，有许多在前的，将要在后；在后的，将要在前。”","notes":[]},{"n":32,"t":"他们行路上耶路撒冷去。耶稣在前头走，他们很惊讶，跟从的人也害怕。耶稣又叫十二使徒来，把自己将要遭遇的事告诉他们，","notes":[],"heads":["耶稣第三次预言受难和复活"]},{"n":33,"t":"说：“看哪，我们上耶路撒冷去，人子将被交给祭司长和文士；他们要定他死罪，又交给外邦人。","notes":[]},{"n":34,"t":"他们要戏弄他，向他吐唾沫，鞭打他，杀害他；三天后，他要复活。”","notes":[]},{"n":35,"t":"西庇太的儿子雅各和约翰进前来，对耶稣说：“老师，我们无论求你什么，愿你为我们做。”","notes":[],"heads":["为首与为仆"]},{"n":36,"t":"耶稣对他们说：“要我为你们做什么？”","notes":[]},{"n":37,"t":"他们对他说：“在你的荣耀里，请赐我们一个坐在你右边，一个坐在你左边。”","notes":[]},{"n":38,"t":"耶稣对他们说：“你们不知道所求的是什么。我所喝的杯，你们能喝吗？我所受的洗，你们能受吗？”","notes":[]},{"n":39,"t":"他们对他说：“我们能。”耶稣对他们说：“我所喝的杯，你们要喝；我所受的洗，你们也要受。","notes":[]},{"n":40,"t":"可是坐在我的左右，不是我可以赐的，而是为谁预备就赐给谁。”","notes":[]},{"n":41,"t":"其余十个门徒听见，就对雅各和约翰很生气。","notes":[]},{"n":42,"t":"耶稣叫了他们来，对他们说：“你们知道，外邦人有君王作主治理他们，有大臣操权管辖他们。","notes":[]},{"n":43,"t":"但是在你们中间，不可这样。你们中间谁愿为大，就要作你们的用人；","notes":[]},{"n":44,"t":"在你们中间谁愿为首，就要作众人的仆人。","notes":[]},{"n":45,"t":"因为人子来，并不是要受人的服事，乃是要服事人，并且要舍命作多人的赎价。”","notes":[]},{"n":46,"t":"他们到了耶利哥。耶稣同门徒并许多人离开耶利哥的时候，有一个讨饭的盲人，是底买的儿子巴底买，坐在路旁。","notes":[],"heads":["治好盲人巴底买"]},{"n":47,"t":"他听见是拿撒勒的耶稣，就喊了起来，说：“大卫之子耶稣啊，可怜我吧！”","notes":[]},{"n":48,"t":"有许多人责备他，不许他作声，他却越发喊着：“大卫之子啊，可怜我吧！”","notes":[]},{"n":49,"t":"耶稣就站住，说：“叫他过来。”他们就叫那盲人，对他说：“放心，起来！他在叫你啦。”","notes":[]},{"n":50,"t":"盲人就丢下衣服，跳起来，走到耶稣那里。","notes":[]},{"n":51,"t":"耶稣回答他说：“你要我为你做什么？”盲人对他说：“拉波尼，我要能看见。”","notes":["“拉波尼”意思是“我的老师”。"]},{"n":52,"t":"耶稣对他说：“你去吧！你的信救了你。”盲人立刻看得见，就在路上跟随耶稣。","notes":[]}]},"11":{"heading":"荣入圣城","verses":[{"n":1,"t":"耶稣和门徒快到耶路撒冷，来到伯法其和伯大尼，在橄榄山那里。耶稣打发两个门徒，","notes":[]},{"n":2,"t":"对他们说：“你们往对面村子里去，一进去的时候会看见一匹驴驹拴在那里，是从来没有人骑过的，把它解开，牵来。","notes":[]},{"n":3,"t":"若有人对你们说：‘为什么做这事？’你们就说：‘主要用它，但会立刻把它牵回到这里来。’”","notes":[]},{"n":4,"t":"他们去了，看见一匹驴驹拴在门外街道上，就把它解开。","notes":[]},{"n":5,"t":"在那里站着的人，有几个说：“你们解开驴驹做什么？”","notes":[]},{"n":6,"t":"门徒照着耶稣的话说，那些人就任凭他们牵去了。","notes":[]},{"n":7,"t":"他们把驴驹牵到耶稣那里，把自己的衣服搭在上面，耶稣就骑上。","notes":[]},{"n":8,"t":"有许多人把衣服铺在路上，还有人把田间的树枝砍下来铺上。","notes":[]},{"n":9,"t":"前呼后拥的人都喊着说：“和散那！奉主名来的是应当称颂的！","notes":["“和散那”：原是求救的意思，在此是称颂的话。"]},{"n":10,"t":"那将要来的我祖大卫之国是应当称颂的！至高无上的，和散那！”","notes":[]},{"n":11,"t":"耶稣到了耶路撒冷，进入圣殿，看了周围的一切。天色已晚，他就和十二使徒出城，往伯大尼去。","notes":[]},{"n":12,"t":"第二天，他们从伯大尼出来，耶稣饿了。","notes":[],"heads":["诅咒无花果树"]},{"n":13,"t":"他远远地看见一棵无花果树，树上有叶子，就过去，看是不是在树上可以找到什么。他到了树下，竟找不到什么，只有叶子，因为不是无花果的季节。","notes":[]},{"n":14,"t":"耶稣就对树说：“从今以后，永没有人吃你的果子。”他的门徒都听到了。","notes":[]},{"n":15,"t":"他们来到耶路撒冷。耶稣一进圣殿，就赶出在圣殿里做买卖的人，推倒兑换银钱之人的桌子和卖鸽子之人的凳子；","notes":[],"heads":["洁净圣殿"]},{"n":16,"t":"也不许人拿着器具从圣殿里经过。","notes":[]},{"n":17,"t":"他教导他们说：“经上不是记着：‘我的殿要称为万国祷告的殿吗？你们倒使它成为贼窝了。’”","notes":[]},{"n":18,"t":"祭司长和文士听见这话，就想法子要除掉耶稣，却又怕他，因为众人都对他的教导感到惊奇。","notes":[]},{"n":19,"t":"每天晚上，他们都到城外去。","notes":["有古卷是“耶稣”。"]},{"n":20,"t":"早晨，他们从那里经过，看见无花果树连根都枯干了。","notes":[],"heads":["从无花果树得教导"]},{"n":21,"t":"彼得想起耶稣的话来，就对他说：“拉比，你看！你所诅咒的无花果树已经枯干了。”","notes":[]},{"n":22,"t":"耶稣回答：“你们对神要有信心。","notes":[]},{"n":23,"t":"我实在告诉你们，无论何人对这座山说：‘离开此地，投在海里！’他心里若不疑惑，只信所说的必成，就为他实现。","notes":[]},{"n":24,"t":"所以我告诉你们，凡你们祷告祈求的，无论是什么，只要信你们已经得着了，就为你们实现。","notes":[]},{"n":25,"t":"你们站着祷告的时候，若想起有人得罪你们，就该饶恕他，好让你们在天上的父也饶恕你们的过犯。”","notes":["有古卷加“26 你们若不饶恕人，你们在天上的父也不饶恕你们的过犯。”"]},{"n":27,"t":"他们又来到耶路撒冷。耶稣在圣殿里行走的时候，祭司长、文士和长老进前来，","notes":[],"heads":["耶稣的权柄受到质问"]},{"n":28,"t":"问他说：“你仗着什么权柄做这些事？给你权柄做这些事的是谁呢？”","notes":[]},{"n":29,"t":"耶稣对他们说：“我要问你们一句话，你们回答我，我就告诉你们我仗着什么权柄做这些事。","notes":[]},{"n":30,"t":"约翰的洗礼是从天上来的，还是从人间来的呢？你们回答我吧。”","notes":[]},{"n":31,"t":"他们彼此商议说：“我们若说‘从天上来的’，他会说：‘这样，你们为什么不信他呢？’","notes":[]},{"n":32,"t":"但若说‘从人间来的’，却又怕众人，因为大家认为约翰确是先知。”","notes":[]},{"n":33,"t":"于是他们回答耶稣：“我们不知道。”耶稣说：“我也不告诉你们，我仗着什么权柄做这些事。”","notes":[]}]},"12":{"heading":"恶园户的比喻","verses":[{"n":1,"t":"耶稣就用比喻对他们说：“有人开垦了一个葡萄园，四周围上篱笆，挖了一个榨酒池，盖了一座守望楼，租给园户，就出外远行去了。","notes":[]},{"n":2,"t":"到了时候，他打发一个仆人到园户那里，要向他们收葡萄园的果子。","notes":[]},{"n":3,"t":"他们拿住他，打了他，叫他空手回去。","notes":[]},{"n":4,"t":"园主再打发一个仆人到他们那里。他们打伤他的头，并且侮辱他。","notes":[]},{"n":5,"t":"园主又打发一个仆人去，他们就杀了他。以后又打发好些仆人去，有的被他们打了，有的被他们杀了。","notes":[]},{"n":6,"t":"园主还有一位，是他的爱子，最后又打发他去，说：‘他们会尊敬我的儿子。’","notes":[]},{"n":7,"t":"那些园户却彼此说：‘这是承受产业的。来，我们杀了他，产业就归我们了！’","notes":[]},{"n":8,"t":"于是他们拿住他，杀了他，把他扔出葡萄园。","notes":[]},{"n":9,"t":"这样，葡萄园主要怎么做呢？他要来除灭那些园户，将葡萄园转给别人。","notes":[]},{"n":10,"t":"‘匠人所丢弃的石头已作了房角的头块石头。这是主所做的，在我们眼中看为奇妙。’这经文你们没有念过吗？”","notes":[],"end":11},{"n":12,"t":"他们看出这比喻是指着他们说的，就想要捉拿他，但是惧怕众人，于是离开他走了。","notes":[]},{"n":13,"t":"后来，他们打发几个法利赛人和希律党人到耶稣那里，要用他自己的话陷害他。","notes":[],"heads":["纳税给凯撒的问题"]},{"n":14,"t":"他们来了，就对他说：“老师，我们知道你是诚实的，无论谁你都一视同仁；因为你不看人的面子，而是诚诚实实传神的道。纳税给凯撒合不合法？","notes":[]},{"n":15,"t":"我们该不该纳？”耶稣知道他们的虚伪，就对他们说：“你们为什么试探我？拿一个银币来给我看。”","notes":[]},{"n":16,"t":"他们就拿了来。耶稣问他们：“这像和这名号是谁的？”他们对他说：“是凯撒的。”","notes":[]},{"n":17,"t":"耶稣对他们说：“凯撒的归凯撒；神的归神。”他们对他非常惊讶。","notes":[]},{"n":18,"t":"撒都该人来见耶稣。他们说没有复活这回事，于是问耶稣：","notes":[],"heads":["复活的问题"]},{"n":19,"t":"“老师，摩西为我们写下这话：‘某人的哥哥若死了，撇下妻子，没有孩子，他该娶哥哥的妻子，为哥哥生子立后。’","notes":[]},{"n":20,"t":"那么，有兄弟七人，第一个娶了妻，死了，没有留下孩子。","notes":[]},{"n":21,"t":"第二个娶了她，也死了，没有留下孩子。第三个也是这样。","notes":[]},{"n":22,"t":"那七个人都没有留下孩子。最后，那妇人也死了。","notes":[]},{"n":23,"t":"在复活的时候，她是哪一个的妻子呢？因为他们七个人都娶过她。”","notes":["有古卷加“当他们复活”。"]},{"n":24,"t":"耶稣说：“你们错了，不正是因为不明白圣经，也不知道神的大能吗？","notes":[]},{"n":25,"t":"当人从死人中复活后，也不娶也不嫁，而是像天上的天使一样。","notes":[]},{"n":26,"t":"论到死人复活，你们没有念过摩西书中《荆棘篇》上所记载的吗？神对摩西说：‘我是亚伯拉罕的神，以撒的神，雅各的神。’","notes":[]},{"n":27,"t":"神不是死人的神，而是活人的神。你们是大错了。”","notes":[]},{"n":28,"t":"有一个文士来，听见他们的辩论，知道耶稣回答得好，就问他说：“诫命中哪一条是第一呢？”","notes":[],"heads":["最大的诫命"]},{"n":29,"t":"耶稣回答：“第一是：‘以色列啊，你要听，主—我们的神是独一的主。","notes":[]},{"n":30,"t":"你要尽心、尽性、尽意、尽力爱主—你的神。’","notes":[]},{"n":31,"t":"第二是：‘要爱邻如己。’再没有比这两条诫命更大的了。”","notes":["“邻”也可译作“人”；33节同。"]},{"n":32,"t":"那文士对耶稣说：“好，老师，你说得对，神是一位，除了他以外，再没有别的了；","notes":[]},{"n":33,"t":"并且尽心、尽智、尽力爱他，又爱邻如己，要比一切燔祭和祭祀好得多。”","notes":[]},{"n":34,"t":"耶稣见他回答得有智慧，就对他说：“你离神的国不远了。”从此以后，没有人敢再问他什么。","notes":[]},{"n":35,"t":"耶稣在圣殿里教导人，问他们说：“文士怎么说基督是大卫的后裔呢？","notes":[],"heads":["基督与大卫的关系"]},{"n":36,"t":"大卫被圣灵感动，说：‘主对我主说：你坐在我的右边，等我把你的仇敌放在你脚下。’","notes":["“放在你脚下”：有古卷是“作你的脚凳”。"]},{"n":37,"t":"大卫亲自称他为主，他怎么又是大卫的后裔呢？”一大群的人都喜欢听他。","notes":[]},{"n":38,"t":"他在教导的时候，说：“你们要防备文士。他们好穿长袍走来走去，喜欢人们在街市上向他们问安，","notes":[],"heads":["谴责文士"]},{"n":39,"t":"又喜爱会堂里的高位，宴席上的首座。","notes":[]},{"n":40,"t":"他们侵吞寡妇的家产，假意作很长的祷告。这些人要受更重的惩罚！”","notes":[]},{"n":41,"t":"耶稣面向圣殿银库坐着，看众人怎样把钱投入银库。有好些财主投了许多钱。","notes":[],"heads":["寡妇的奉献"]},{"n":42,"t":"有一个穷寡妇来，投了两个小文钱，就是一个大文钱。","notes":["“小文钱”：参“度量衡表”。","“大文钱”：参“度量衡表”。"]},{"n":43,"t":"耶稣叫门徒来，对他们说：“我实在告诉你们，这穷寡妇投入银库里的比众人所投的更多。","notes":[]},{"n":44,"t":"因为，众人都是拿有余的捐献，但这寡妇，虽然自己不足，却把她一生所有的全都投进去了。”","notes":[]}]},"13":{"heading":"预言圣殿被毁","verses":[{"n":1,"t":"耶稣从圣殿里出来的时候，有一个门徒对他说：“老师，请看，这是多么了不起的石头！多么了不起的建筑！”","notes":[]},{"n":2,"t":"耶稣对他说：“你看见这些宏伟的建筑吗？这里将没有一块石头会留在另一块石头上而不被拆毁的。”","notes":[]},{"n":3,"t":"耶稣在橄榄山上，面向圣殿坐着；彼得、雅各、约翰和安得烈私下问他说：","notes":[],"heads":["终局的预兆"]},{"n":4,"t":"“请告诉我们，什么时候有这些事呢？这一切事将成的时候有什么预兆呢？”","notes":[]},{"n":5,"t":"耶稣说：“你们要谨慎，免得有人迷惑你们。","notes":[]},{"n":6,"t":"将有好些人冒我的名来，说‘我是基督’，并且要迷惑许多人。","notes":[]},{"n":7,"t":"当你们听见打仗和打仗的风声，不要惊慌；这些事必须发生，但这还不是终结。","notes":[]},{"n":8,"t":"民要攻打民，国要攻打国，多处必有地震、饥荒。这都是灾难的起头。","notes":["“灾难”：原文直译“生产的阵痛”。"]},{"n":9,"t":"但你们自己要谨慎；因为有人要把你们交给议会，并且你们在会堂里要受鞭打，又为我的缘故站在统治者和君王面前，对他们作见证。","notes":[]},{"n":10,"t":"然而，福音必须先传给万民。","notes":[]},{"n":11,"t":"有人把你们解送去受审的时候，不要事先担心说什么；到那时候，赐给你们什么话，你们就说什么；因为说话的不是你们，而是圣灵。","notes":[]},{"n":12,"t":"兄弟要把兄弟、父亲要把儿女置于死地；儿女要起来与父母为敌，害死他们；","notes":[]},{"n":13,"t":"而且你们要为我的名被众人憎恨。但坚忍到底的终必得救。”","notes":[]},{"n":14,"t":"“当你们看见那‘施行毁灭的亵渎者’站在不当站的地方（读这经的人要会意），那时，在犹太的，应当逃到山上；","notes":[],"heads":["大灾难"]},{"n":15,"t":"在屋顶上的，不要下来，也不要进家里去拿东西；","notes":[]},{"n":16,"t":"在田里的，不要回去取衣裳。","notes":[]},{"n":17,"t":"在那些日子，怀孕的和奶孩子的就苦了。","notes":[]},{"n":18,"t":"你们要祈求，叫这事不在冬天发生。","notes":[]},{"n":19,"t":"因为，在那些日子必有灾难，自从神创造万物直到如今，从没有这样的灾难，将来也不会有。","notes":[]},{"n":20,"t":"若不是主减少那些日子，凡血肉之躯的，就没有一个能得救；但是为了他所拣选的选民，他将那些日子减少了。","notes":[]},{"n":21,"t":"那时，若有人对你们说：‘看哪，基督在这里！看哪，在那里！’你们不要信。","notes":[]},{"n":22,"t":"因为假基督和假先知将要起来，显神迹奇事，如果可能，连选民也迷惑了。","notes":[]},{"n":23,"t":"你们要谨慎！凡事我都预先告诉你们了。”","notes":[]},{"n":24,"t":"“在那些日子、那灾难以后，太阳要变黑，月亮也不放光，","notes":[],"heads":["人子的来临"]},{"n":25,"t":"众星要从天上坠落，天上的万象都要震动。","notes":[]},{"n":26,"t":"那时，他们要看见人子带着大能力和荣耀驾云来临。","notes":[]},{"n":27,"t":"他要差遣天使，从四方，从地极直到天边，召集他的选民。”","notes":[]},{"n":28,"t":"“你们要从无花果树学习功课：当树枝发芽长叶的时候，你们就知道夏天近了。","notes":[],"heads":["从无花果树学功课"]},{"n":29,"t":"同样，当你们看见这些事发生，就知道那时候近了，就在门口了。","notes":[]},{"n":30,"t":"我实在告诉你们，这世代还没有过去，这一切都要发生。","notes":[]},{"n":31,"t":"天地要废去，我的话却绝不废去。”","notes":[]},{"n":32,"t":"“但那日子，那时辰，没有人知道，连天上的天使也不知道，子也不知道，惟有父知道。","notes":[],"heads":["那日那时没有人知道"]},{"n":33,"t":"你们要谨慎，要警醒，因为你们不知道那时刻几时来到。","notes":["有古卷加“祈祷”。"]},{"n":34,"t":"这事正如一个人离家远行，授权给仆人们，分派各人的工作，又吩咐看门的警醒。","notes":[]},{"n":35,"t":"所以，你们要警醒，因为你们不知道这家的主人什么时候来，是晚上，或半夜，或鸡叫时，或早晨，","notes":[]},{"n":36,"t":"免得他忽然来到，看见你们睡着了。","notes":[]},{"n":37,"t":"我对你们所说的话，也是对众人说的：要警醒！”","notes":[]}]},"14":{"heading":"杀害耶稣的阴谋","verses":[{"n":1,"t":"过两天是逾越节，又是除酵节，祭司长和文士在想法子怎样设计捉拿耶稣，把他杀掉。","notes":[]},{"n":2,"t":"他们说：“不可在过节的日子，恐怕百姓生乱。”","notes":[]},{"n":3,"t":"耶稣在伯大尼麻风病人西门家里坐席的时候，有一个女人拿着一玉瓶极贵的纯哪哒香膏来，打破玉瓶，把膏浇在耶稣的头上。","notes":["“哪哒”即“甘松”。"],"heads":["在伯大尼受膏"]},{"n":4,"t":"有几个人心中很不高兴，说：“何必这样浪费香膏呢？","notes":[]},{"n":5,"t":"这香膏可以卖三百多个银币周济穷人。”他们就对那女人生气。","notes":[]},{"n":6,"t":"耶稣说：“由她吧！为什么难为她呢？她在我身上做的是一件美事。","notes":[]},{"n":7,"t":"因为常有穷人和你们在一起，要向他们行善，随时都可以，但是你们不常有我。","notes":[]},{"n":8,"t":"她所做的是尽她所能的；她是为了我的安葬，把香膏预先浇在我身上。","notes":[]},{"n":9,"t":"我实在告诉你们，普天之下，无论在什么地方传这福音，都要述说这女人所做的，来记念她。”","notes":[]},{"n":10,"t":"十二使徒中有一个加略人犹大，去见祭司长，要把耶稣交给他们。","notes":[],"heads":["犹大出卖耶稣"]},{"n":11,"t":"他们听见就很高兴，又应许给他银子；他就想怎样找机会把耶稣交给他们。","notes":[]},{"n":12,"t":"除酵节的第一天，就是宰逾越节羔羊的那一天，门徒对耶稣说：“你要我们到哪里去预备你吃逾越节的宴席呢？”","notes":[],"heads":["与门徒同守逾越节"]},{"n":13,"t":"耶稣就打发两个门徒，对他们说：“你们进城去，会有人拿着一罐水迎面而来，你们就跟着他。","notes":[]},{"n":14,"t":"无论他进哪一家，你们就对那家的主人说：‘老师问：我的客房在哪里？我和我的门徒要在那里吃逾越节的宴席。’","notes":[]},{"n":15,"t":"他会带你们看一间摆设齐全、准备妥当的楼上大厅，你们就在那里为我们预备。”","notes":[]},{"n":16,"t":"门徒出去，进了城，所看到的正如耶稣所说的。他们就预备了逾越节的宴席。","notes":[]},{"n":17,"t":"到了晚上，耶稣和十二使徒都来了。","notes":[]},{"n":18,"t":"他们坐席，正吃的时候，耶稣说：“我实在告诉你们，你们中间有一个与我同吃的人要出卖我了。”","notes":[]},{"n":19,"t":"他们就忧愁起来，一个个地问他：“不是我吧？”","notes":[]},{"n":20,"t":"耶稣对他们说：“是十二人中的一个，就是同我蘸饼在盘子里的那个人。","notes":[]},{"n":21,"t":"人子要去了，正如经上所写有关他的；但出卖人子的人有祸了！那人没有出生倒好。”","notes":[]},{"n":22,"t":"他们吃的时候，耶稣拿起饼来，祝福了，就擘开，递给他们，说：“你们拿去，这是我的身体。”","notes":[],"heads":["设立主的晚餐"]},{"n":23,"t":"他又拿起杯来，祝谢了，递给他们；他们都喝了。","notes":[]},{"n":24,"t":"耶稣对他们说：“这是我立约的血，为许多人流出来的。","notes":[]},{"n":25,"t":"我实在告诉你们，我不再喝这葡萄汁，直到我在神的国里喝新的那日子。”","notes":[]},{"n":26,"t":"他们唱了诗，就出来往橄榄山去。","notes":[]},{"n":27,"t":"耶稣对他们说：“你们都要跌倒，因为经上记着：‘我要击打牧人，羊就分散了。’","notes":[],"heads":["预言彼得不认主"]},{"n":28,"t":"但我复活以后，要在你们之前往加利利去。”","notes":[]},{"n":29,"t":"彼得说：“虽然众人跌倒，但我不会。”","notes":[]},{"n":30,"t":"耶稣对他说：“我实在告诉你，今天夜里，鸡叫两遍以前，你要三次不认我。”","notes":["有古卷没有“两遍”。"]},{"n":31,"t":"彼得却极力地说：“我就是必须和你同死，也绝不会不认你。”所有的门徒都是这样说。","notes":["“所有的门徒”：原文直译“所有的人”。"]},{"n":32,"t":"他们来到一个地方，名叫客西马尼。耶稣对门徒说：“你们坐在这里，我去祷告。”","notes":[],"heads":["在客西马尼祷告"]},{"n":33,"t":"于是他带着彼得、雅各和约翰同去。他惊恐起来，极其难过，","notes":[]},{"n":34,"t":"对他们说：“我心里非常忧伤，几乎要死；你们留在这里，要警醒。”","notes":[]},{"n":35,"t":"他就稍往前走，俯伏在地，祷告说，如果可能，就叫那时候离开他。","notes":[]},{"n":36,"t":"他说：“阿爸，父啊！在你凡事都能；求你将这杯撤去。然而，不是照我所愿的，而是照你所愿的。”","notes":[]},{"n":37,"t":"耶稣回来，见他们睡着了，就对彼得说：“西门，你睡着了吗？不能警醒一小时吗？","notes":[]},{"n":38,"t":"总要警醒祷告，免得陷入试探。你们心灵固然愿意，肉体却软弱了。”","notes":[]},{"n":39,"t":"耶稣又去祷告，说的话跟先前一样。","notes":[]},{"n":40,"t":"他又来，见他们睡着了，因为他们的眼睛很困倦；他们也不知道怎么回答他。","notes":[]},{"n":41,"t":"他第三次来对他们说：“现在你们仍在睡觉安歇吗？够了，时候到了。看哪，人子被出卖在罪人手里了。","notes":[]},{"n":42,"t":"起来，我们走吧！看哪，那出卖我的人快来了。”","notes":[]},{"n":43,"t":"耶稣还在说话的时候，忽然十二使徒之一的犹大来了，还有一群人带着刀棒，从祭司长、文士和长老那里跟他同来。","notes":[],"heads":["耶稣被捕"]},{"n":44,"t":"那出卖耶稣的人曾给他们一个暗号，说：“我亲谁，谁就是。你们把他抓住，稳妥地带走。”","notes":[]},{"n":45,"t":"犹大来了，随即到耶稣跟前，说：“拉比”，就跟他亲吻。","notes":[]},{"n":46,"t":"他们就下手抓住他。","notes":[]},{"n":47,"t":"旁边站着的人，有一个拔出刀来，把大祭司的仆人砍了一刀，削掉了他一只耳朵。","notes":[]},{"n":48,"t":"耶稣回应他们说：“你们带着刀棒出来拿我，如同拿强盗吗？","notes":[]},{"n":49,"t":"我天天教导人，同你们在殿里，你们并没有抓我。但这是要应验经上的话。”","notes":[]},{"n":50,"t":"门徒都离开他，逃走了。","notes":[]},{"n":51,"t":"有一个青年光着身子，只披一块麻布，跟随耶稣，众人就抓住他。","notes":[],"heads":["逃走的青年"]},{"n":52,"t":"他却丢下麻布，赤身逃走了。","notes":[]},{"n":53,"t":"他们把耶稣带到大祭司那里，又有众祭司长、长老和文士都来一同聚集。","notes":[],"heads":["耶稣在议会受审"]},{"n":54,"t":"彼得远远地跟着耶稣，直到进了大祭司的院子，和警卫一同坐在火边取暖。","notes":[]},{"n":55,"t":"祭司长和全议会寻找见证控告耶稣，要处死他，却找不到实据。","notes":[]},{"n":56,"t":"因为有好些人作假见证告他，他们的见证又各不相符。","notes":[]},{"n":57,"t":"又有几个人站起来，作假见证告他说：","notes":[]},{"n":58,"t":"“我们听见他说：‘我要拆毁这人手所造的殿，三日内另造一座不是人手所造的。’”","notes":[]},{"n":59,"t":"就是这样，他们的见证还是不相符。","notes":[]},{"n":60,"t":"大祭司起来站在中间，问耶稣说：“这些人作证告你的事，你什么都不回答吗？”","notes":[]},{"n":61,"t":"耶稣却不言语，一句也不回答。大祭司又问他：“你是不是基督，那当称颂者的儿子？”","notes":[]},{"n":62,"t":"耶稣说：“我是。你们要看见人子坐在那权能者的右边，驾着天上的云来临。”","notes":[]},{"n":63,"t":"大祭司就撕裂衣服，说：“我们何必再要证人呢？","notes":[]},{"n":64,"t":"你们已经听见他这亵渎的话了。你们的决定如何？”他们都判定他该处死。","notes":[]},{"n":65,"t":"于是有人开始向他吐唾沫，又蒙着他的脸，用拳头打他，对他说：“你说预言吧！”警卫把他拉过来，打他耳光。","notes":[]},{"n":66,"t":"彼得在下边院子里，大祭司的一个使女来了，","notes":[],"heads":["彼得三次不认主"]},{"n":67,"t":"见彼得取暖，就看着他，说：“你素来也是同拿撒勒人耶稣一起的。”","notes":[]},{"n":68,"t":"彼得却不承认，说：“我不知道，也不明白你说的是什么！”于是他出来，到了前院，鸡就叫了。","notes":["有古卷没有“鸡就叫了”。"]},{"n":69,"t":"那使女看见他，又对旁边站着的人说：“这个人也是他们一伙的。”","notes":[]},{"n":70,"t":"彼得又不承认。过了不久，旁边站着的人又对彼得说：“你真是他们一伙的，因为你也是加利利人。”","notes":[]},{"n":71,"t":"彼得就赌咒发誓说：“我不认得你们说的这个人。”","notes":[]},{"n":72,"t":"立刻，鸡叫了第二遍。彼得想起耶稣对他所说的话：“鸡叫两遍以前，你要三次不认我。”他就忍不住哭了。","notes":[]}]},"15":{"heading":"耶稣在彼拉多面前受审","verses":[{"n":1,"t":"一到早晨，众祭司长、长老、文士，和全议会的人大家商议，就把耶稣绑着，解去，交给彼拉多。","notes":[]},{"n":2,"t":"彼拉多问他：“你是犹太人的王吗？”耶稣回答：“是你说的。”","notes":[]},{"n":3,"t":"祭司长们告他许多的事。","notes":[]},{"n":4,"t":"彼拉多又问他：“你看，他们告你这么多的事，你什么都不回答吗？”","notes":[]},{"n":5,"t":"耶稣仍不回答，以致彼拉多觉得惊讶。","notes":[]},{"n":6,"t":"每逢这节期，彼拉多照众人所求的，释放一个囚犯给他们。","notes":[],"heads":["耶稣被判死刑"]},{"n":7,"t":"有一个人名叫巴拉巴，和作乱的人监禁在一起。他们作乱的时候曾杀过人。","notes":[]},{"n":8,"t":"众人上去求彼拉多照常例给他们办理。","notes":[]},{"n":9,"t":"彼拉多说：“你们要我释放犹太人的王给你们吗？”","notes":[]},{"n":10,"t":"他原知道祭司长们是因嫉妒才把耶稣解了来。","notes":[]},{"n":11,"t":"但是祭司长们煽动众人，宁可要他释放巴拉巴给他们。","notes":[]},{"n":12,"t":"彼拉多又说：“那么，你们称为犹太人的王的，要我怎么办他呢？”","notes":["“你们…的王的”：有古卷是“犹太人的王”。","有古卷没有“要”。"]},{"n":13,"t":"他们又再喊着：“把他钉十字架！”","notes":[]},{"n":14,"t":"彼拉多说：“为什么？他做了什么恶事呢？”他们更加喊着：“把他钉十字架！”","notes":[]},{"n":15,"t":"彼拉多要讨好众人，就释放巴拉巴给他们，把耶稣鞭打后交给人钉十字架。","notes":[]},{"n":16,"t":"士兵把耶稣带进总督府的庭院里，叫齐了全营的兵。","notes":[],"heads":["士兵戏弄耶稣"]},{"n":17,"t":"他们给他穿上紫袍，又用荆棘编了冠冕给他戴上，","notes":[]},{"n":18,"t":"然后向他致敬，说：“万岁，犹太人的王！”","notes":[]},{"n":19,"t":"他们又拿一根芦苇秆打他的头，向他吐唾沫，屈膝拜他。","notes":[]},{"n":20,"t":"他们戏弄完了，就给他脱了紫袍，又穿上他自己的衣服，带他出去，要把他钉十字架。","notes":[]},{"n":21,"t":"有一个古利奈人西门，就是亚历山大和鲁孚的父亲，从乡下来，经过那地方，他们就强迫他同去，好背耶稣的十字架。","notes":[],"heads":["耶稣被钉十字架"]},{"n":22,"t":"他们带耶稣到了一个地方叫各各他（翻出来就是“髑髅地”），","notes":[]},{"n":23,"t":"拿没药调和的酒给耶稣，他却不受。","notes":[]},{"n":24,"t":"于是他们把他钉在十字架上，抽签分他的衣服，看谁得什么。","notes":[]},{"n":25,"t":"他们把他钉十字架的时候是上午九点钟。","notes":[]},{"n":26,"t":"罪状牌上写的是：“犹太人的王。”","notes":[]},{"n":27,"t":"他们又把两个强盗和他同钉十字架，一个在右边，一个在左边。","notes":["有古卷加“28 这就应验了经上的话说：他被列在罪犯之中。”"]},{"n":29,"t":"从那里经过的人讥笑他，摇着头，说：“哼！你这拆毁殿、三日又建造起来的，","notes":[]},{"n":30,"t":"救救你自己，从十字架上下来呀！”","notes":[]},{"n":31,"t":"众祭司长和文士也这样嘲笑他，彼此说：“他救了别人，不能救自己。","notes":[]},{"n":32,"t":"以色列的王基督，现在从十字架上下来，好让我们看见就信了呀！”那和他同钉的人也讥讽他。","notes":[]},{"n":33,"t":"到了正午，全地都黑暗了，直到下午三点钟。","notes":[],"heads":["耶稣之死"]},{"n":34,"t":"下午三点钟的时候，耶稣大声呼喊：“以罗伊！以罗伊！拉马撒巴各大尼？”（翻出来就是：我的神！我的神！为什么离弃我？）","notes":[]},{"n":35,"t":"旁边站着的人，有的听见就说：“看哪，他叫以利亚呢！”","notes":[]},{"n":36,"t":"有一个人跑去，把海绵蘸满了醋，绑在芦苇秆上，送给他喝，说：“且等着，看以利亚会不会来把他放下来。”","notes":[]},{"n":37,"t":"耶稣大喊一声，气就断了。","notes":[]},{"n":38,"t":"殿的幔子从上到下裂为两半。","notes":[]},{"n":39,"t":"对面站着的百夫长看见耶稣这样断气，就说：“这人真是神的儿子！”","notes":["“这样断气”：有古卷是“这样喊叫断气”。"]},{"n":40,"t":"还有些妇女远远地观看，其中有抹大拉的马利亚，又有小雅各和约西的母亲马利亚，并有撒罗米，","notes":[]},{"n":41,"t":"就是耶稣在加利利的时候，跟随他、服事他的那些人，还有同耶稣上耶路撒冷的好些妇女。","notes":[]},{"n":42,"t":"到了晚上，因为这是预备日，就是安息日的前一日，","notes":[],"heads":["耶稣的安葬"]},{"n":43,"t":"有亚利马太的约瑟前来，他是尊贵的议员，也是盼望着神国的，他放胆进去见彼拉多，请求要耶稣的身体。","notes":[]},{"n":44,"t":"彼拉多诧异耶稣已经死了，就叫百夫长来，问他耶稣是不是死了很久；","notes":[]},{"n":45,"t":"既从百夫长得知实情，就把耶稣的身体赐给约瑟。","notes":[]},{"n":46,"t":"约瑟买了细麻布，把耶稣取下来，用细麻布裹好，安放在岩石中凿出来的墓穴里，又滚来一块石头挡住墓门。","notes":[]},{"n":47,"t":"抹大拉的马利亚和约西的母亲马利亚都看见安放他的地方。","notes":[]}]},"16":{"heading":"耶稣复活","verses":[{"n":1,"t":"过了安息日，抹大拉的马利亚、雅各的母亲马利亚，和撒罗米，买了香料，要去膏耶稣的身体。","notes":[]},{"n":2,"t":"七日的第一日清早，太阳出来后，她们来到坟墓那里，","notes":[]},{"n":3,"t":"彼此说：“谁要替我们把石头从墓门滚开呢？”","notes":[]},{"n":4,"t":"她们抬头一看，看见石头已经滚开了，原来那石头很大。","notes":[]},{"n":5,"t":"她们进了坟墓，看见一个年轻人坐在右边，穿着白袍，就很惊奇。","notes":[]},{"n":6,"t":"那年轻人对她们说：“不要惊慌！你们寻找那钉十字架的拿撒勒人耶稣，他已经复活了，不在这里。来看安放他的地方。","notes":[]},{"n":7,"t":"你们去，对他的门徒和彼得说：‘他要比你们先到加利利去，在那里你们会看见他，正如他从前所告诉你们的。’”","notes":[]},{"n":8,"t":"于是她们出来，从坟墓那里逃走，又发抖又惊讶，什么也没有告诉人，因为她们害怕。","notes":[]},{"n":9,"t":"〔 凡耶稣所吩咐的，她们简洁地告诉彼得和他周围的人。这些事以后，耶稣亲自藉着他的门徒，从东到西，把那神圣、不朽、永远拯救的福音传出去。阿们！〕","notes":[],"seq":1,"heads":["．有些古卷有下列结语．","短结语："]},{"n":9,"t":"〔 在七日的第一日清早，耶稣复活了，先向抹大拉的马利亚显现；耶稣曾从她身上赶出七个鬼。","notes":[],"seq":2,"heads":["长结语：","向抹大拉的马利亚显现"]},{"n":10,"t":"她去告诉那向来跟随耶稣的人；那时他们正哀恸哭泣。","notes":[]},{"n":11,"t":"他们听见耶稣活了，被马利亚看见，可是不信。〕","notes":[]},{"n":12,"t":"〔 这些事以后，门徒中有两个人往乡下去；正走着的时候，耶稣以另一种形像向他们显现。","notes":[],"heads":["向两个门徒显现"]},{"n":13,"t":"他们去告诉其余的门徒，那些门徒还是不信。〕","notes":[]},{"n":14,"t":"〔 后来十一使徒坐席的时候，耶稣向他们显现，责备他们不信，心里刚硬，因为他们不信那些在他复活以后看见他的人。","notes":[],"heads":["门徒奉差遣"]},{"n":15,"t":"他又对他们说：“你们往普天下去，传福音给万民听。","notes":["“万民”：原文直译“凡受造的”。"]},{"n":16,"t":"信而受洗的必然得救，不信的必被定罪。","notes":[]},{"n":17,"t":"信的人将有神迹随着他们：就是奉我的名赶鬼；说新方言；","notes":[]},{"n":18,"t":"手能拿蛇；若喝了什么毒物，也不会受害；手按病人，病人就好了。”〕","notes":["有古卷没有“手”。"]},{"n":19,"t":"〔 主耶稣和他们说完了话以后，被接到天上，坐在神的右边。","notes":["有古卷是“主耶稣基督”；有古卷是“主”；另有古卷是“耶稣”。"],"heads":["耶稣升天"]},{"n":20,"t":"门徒出去，到处传福音。主和他们同工，藉着伴随的神迹证实所传的道。〕","notes":["有古卷加“阿们！”"]}]}},"LUK":{"1":{"heading":"预言施洗约翰的出生","verses":[{"n":1,"t":"提阿非罗大人哪，有好些人提笔作书，述说在我们中间所实现的事，是照传道的人从起初亲眼看见又传给我们的。这些事我从起头都详细考察了，我也想按着次序写给你，","notes":[],"end":3},{"n":4,"t":"要让你知道所学的道都是确实的。","notes":[]},{"n":5,"t":"在希律作犹太王的时候，亚比雅班里有一个祭司，名叫撒迦利亚；他妻子是亚伦的后代，名叫伊利莎白。","notes":[]},{"n":6,"t":"他们两人在神面前都是义人，遵行主的一切诫命和条例，没有可指责的。","notes":[]},{"n":7,"t":"只是他们没有孩子，因为伊利莎白不生育，两个人又年纪老迈了。","notes":[]},{"n":8,"t":"撒迦利亚按班次在神面前执行祭司的职务，","notes":[]},{"n":9,"t":"照祭司的规矩抽签，进到主的殿里烧香。","notes":[]},{"n":10,"t":"烧香的时候，众百姓在外面祷告。","notes":[]},{"n":11,"t":"有主的一个使者站在香坛的右边，向他显现。","notes":[]},{"n":12,"t":"撒迦利亚看见，就惊慌害怕。","notes":[]},{"n":13,"t":"天使对他说：“撒迦利亚，不要害怕，因为你的祈祷已经被听见了。你的妻子伊利莎白要给你生一个儿子，你要给他起名叫约翰。","notes":[]},{"n":14,"t":"你必欢喜快乐；有许多人因他出世也必喜乐。","notes":[]},{"n":15,"t":"他在主面前将要为大，淡酒烈酒都不喝，从母腹里就被圣灵充满。","notes":[]},{"n":16,"t":"他要使许多以色列人回转，归于主—他们的神。","notes":[]},{"n":17,"t":"他将有以利亚的精神和能力，走在主的前面，叫父亲的心转向儿女，叫悖逆的人转向义人的智慧，又为主预备迎接他的百姓。”","notes":[]},{"n":18,"t":"撒迦利亚对天使说：“我怎么能知道这事呢？我已经老了，我的妻子也年纪老迈了。”","notes":[]},{"n":19,"t":"天使回答他说：“我是站在神面前的加百列，奉差遣来对你说话，把这好信息报给你。","notes":[]},{"n":20,"t":"到了时候，这些话必然应验；只因你不信我的话，你会成为哑巴，不能说话，直到这些事实现的日子。”","notes":[]},{"n":21,"t":"百姓等候撒迦利亚，诧异他在圣所里迟延那么久。","notes":[]},{"n":22,"t":"到他出来，却不能和他们说话，他们就知道他在圣所里见了异象；他直向他们打手势，因为他成了哑巴。","notes":[]},{"n":23,"t":"他供职的日子一满，就回家去了。","notes":[]},{"n":24,"t":"这些日子以后，他的妻子伊利莎白就怀孕，隐藏了五个月；","notes":[]},{"n":25,"t":"她说：“主在眷顾我的日子，这样看顾我，要除掉我在人前的羞耻。”","notes":[]},{"n":26,"t":"到了第六个月，天使加百列奉神的差遣往加利利的一座城去，这城名叫拿撒勒，","notes":[],"heads":["预言耶稣的降生"]},{"n":27,"t":"到一个童女那里，她已经许配大卫家的一个人，名叫约瑟；童女的名字叫马利亚。","notes":[]},{"n":28,"t":"天使进去，对她说：“蒙大恩的女子，你好，主和你同在！”","notes":[]},{"n":29,"t":"马利亚因这话就很惊慌，又反覆思考这样问候是什么意思。","notes":[]},{"n":30,"t":"天使对她说：“马利亚，不要怕，你在神面前已经蒙恩了。","notes":[]},{"n":31,"t":"你要怀孕生子，要给他起名叫耶稣。","notes":[]},{"n":32,"t":"他将要为大，称为至高者的儿子；主神要把他祖先大卫的王位给他。","notes":[]},{"n":33,"t":"他要作雅各家的王，直到永远；他的国没有穷尽。”","notes":[]},{"n":34,"t":"马利亚对天使说：“我没有出嫁，怎么会有这事呢？”","notes":[]},{"n":35,"t":"天使回答她说：“圣灵要临到你身上；至高者的能力要庇荫你，因此，那要出生的圣者要称为神的儿子。","notes":["“那要出生的圣者要称为神的儿子”或译“那要出生的要称为圣，为神的儿子”。"]},{"n":36,"t":"况且，你的亲戚伊利莎白，就是那素来称为不生育的，在年老的时候也怀了男胎，现在怀孕六个月了。","notes":[]},{"n":37,"t":"因为，出于神的话，没有一句不带能力的。”","notes":[]},{"n":38,"t":"马利亚说：“我是主的使女，愿意照你的话实现在我身上。”于是天使离开她去了。","notes":[]},{"n":39,"t":"在那些日子，马利亚起身，急忙前往山区，来到犹大的一座城，","notes":[],"heads":["马利亚看望伊利莎白"]},{"n":40,"t":"进了撒迦利亚的家，向伊利莎白问安。","notes":[]},{"n":41,"t":"伊利莎白一听到马利亚问安，所怀的胎就在腹里跳动。伊利莎白被圣灵充满，","notes":[]},{"n":42,"t":"高声喊着说：“你在妇女中是有福的！你所怀的胎也是有福的！","notes":[]},{"n":43,"t":"我主的母亲到我这里来，为何这事临到我呢？","notes":[]},{"n":44,"t":"因为你问安的声音一入我耳，我腹里的胎就欢喜跳动。","notes":[]},{"n":45,"t":"这相信的女子是有福的！因为主对她所说的话都要应验。”","notes":[]},{"n":46,"t":"马利亚说：“我心尊主为大；","notes":[],"heads":["马利亚的尊主颂"]},{"n":47,"t":"我灵以神我的救主为乐；","notes":[]},{"n":48,"t":"因为他顾念他使女的卑微；从今以后，万代要称我有福。","notes":[]},{"n":49,"t":"因为那有权能的为我做了大事；他的名是圣的。","notes":[]},{"n":50,"t":"他怜悯敬畏他的人，直到世世代代。","notes":[]},{"n":51,"t":"他用膀臂施展大能；他赶散心里妄想的狂傲人。","notes":[]},{"n":52,"t":"他叫有权柄的失位，叫卑贱的升高。","notes":[]},{"n":53,"t":"他叫饥饿的饱餐美食，叫富足的空手回去。","notes":[]},{"n":54,"t":"他扶助了他的仆人以色列，不忘记施怜悯，","notes":[]},{"n":55,"t":"正如他对我们的列祖说过，‘怜悯亚伯拉罕和他的后裔，直到永远。’”","notes":[]},{"n":56,"t":"马利亚和伊利莎白同住，约有三个月，然后回家去了。","notes":[]},{"n":57,"t":"伊利莎白的产期到了，生了一个儿子。","notes":[],"heads":["施洗约翰的出生"]},{"n":58,"t":"邻里亲属听见主向她大施怜悯，就和她一同欢乐。","notes":[]},{"n":59,"t":"到了第八日，他们来给孩子行割礼，并要照他父亲的名字叫他撒迦利亚。","notes":[]},{"n":60,"t":"他母亲回应说：“不！要叫他约翰。”","notes":[]},{"n":61,"t":"他们对她说：“你亲族中没有叫这名字的。”","notes":[]},{"n":62,"t":"他们就向他父亲打手势，问他这孩子要叫什么名字。","notes":[]},{"n":63,"t":"他要了一块写字的板，写上：“他的名字是约翰。”他们就都惊讶。","notes":[]},{"n":64,"t":"撒迦利亚的口立刻开了，舌头也松了，就开始说话称颂神。","notes":[]},{"n":65,"t":"周围居住的人都惧怕；这一切的事就传遍了犹太山区。","notes":[]},{"n":66,"t":"凡听见的人都把这事放在心里，他们说：“这个孩子将来会怎么样呢？”因为有主的手与他同在。","notes":[]},{"n":67,"t":"他父亲撒迦利亚被圣灵充满，就预言说：","notes":[],"heads":["撒迦利亚颂"]},{"n":68,"t":"“主—以色列的神是应当称颂的！因他眷顾他的百姓，为他们施行救赎，","notes":[]},{"n":69,"t":"在他仆人大卫家中，为我们兴起了拯救的角，","notes":[]},{"n":70,"t":"正如主藉着古时候圣先知的口所说的，","notes":[]},{"n":71,"t":"‘他拯救我们脱离仇敌，脱离一切恨我们之人的手。","notes":[]},{"n":72,"t":"他向我们列祖施怜悯，记得他的圣约，","notes":[]},{"n":73,"t":"就是他对我们祖宗亚伯拉罕所起的誓，","notes":[]},{"n":74,"t":"叫我们既从仇敌手中被救出来，就可以终身在他面前，无所惧怕地用圣洁和公义事奉他。","notes":[],"end":75},{"n":76,"t":"孩子啊，你要称为至高者的先知；因为你要走在主的前面，为他预备道路，","notes":[]},{"n":77,"t":"叫他的百姓因罪得赦，认识救恩；","notes":[]},{"n":78,"t":"因我们神怜悯的心肠，叫清晨的日光从高天临到我们，","notes":[]},{"n":79,"t":"要照亮坐在黑暗中死荫里的人，把我们的脚引到和平的路上。’”","notes":[]},{"n":80,"t":"这孩子渐渐长大，心灵坚强，住在旷野，直到他在以色列人面前公开出现的日子。","notes":[]}]},"2":{"heading":"耶稣降生","verses":[{"n":1,"t":"在那些日子，凯撒奥古斯都降旨，叫全国人民都登记户籍。","notes":[]},{"n":2,"t":"这第一次登记户籍是在居里扭作叙利亚总督的时候行的。","notes":[]},{"n":3,"t":"众人各归各城，办理登记。","notes":[]},{"n":4,"t":"约瑟也从加利利的拿撒勒城上犹太去，到了大卫的城名叫伯利恒，因为他是大卫家族的人，","notes":[]},{"n":5,"t":"要和他所聘之妻马利亚一同登记户籍。那时马利亚已经怀孕。","notes":[]},{"n":6,"t":"他们在那里的时候，马利亚的产期到了，","notes":[]},{"n":7,"t":"就生了头胎的儿子，用布包起来，放在马槽里，因为客店里没有地方。","notes":[]},{"n":8,"t":"在伯利恒的野外有牧羊人，夜间值班看守羊群。","notes":["“在伯利恒”：原文直译“在同一个区域”。"],"heads":["天使报喜讯给牧羊人"]},{"n":9,"t":"有主的一个使者站在他们旁边，主的荣光四面照着他们，牧羊人就很惧怕。","notes":[]},{"n":10,"t":"那天使对他们说：“不要惧怕！看哪！因为我报给你们大喜的信息，是关乎万民的：","notes":[]},{"n":11,"t":"因今天在大卫的城里，为你们生了救主，就是主基督。","notes":[]},{"n":12,"t":"你们要看见一个婴孩，包着布，卧在马槽里，那就是给你们的记号。”","notes":[]},{"n":13,"t":"忽然，有一大队天兵同那天使赞美神说：","notes":[]},{"n":14,"t":"“在至高之处荣耀归与神！在地上平安归与他所喜悦的人！”","notes":[]},{"n":15,"t":"众天使离开他们，升天去了。牧羊人彼此说：“我们往伯利恒去，看看所成的事，就是主所告诉我们的。”","notes":[]},{"n":16,"t":"他们急忙去了，找到马利亚和约瑟，还有那婴孩卧在马槽里。","notes":[]},{"n":17,"t":"他们看见，就把天使论这孩子的话传开了。","notes":[]},{"n":18,"t":"听见的人都诧异牧羊人对他们所说的话。","notes":[]},{"n":19,"t":"马利亚却把这一切的事存在心里，反覆思考。","notes":[]},{"n":20,"t":"牧羊人回去了，因所听见所看见的一切事，正如天使向他们所说的，就归荣耀于神，赞美他。","notes":[]},{"n":21,"t":"满了八天，他们就给孩子行割礼，又给他起名叫耶稣；这是他还没有在母腹里成胎以前天使所起的名。","notes":[]},{"n":22,"t":"按摩西律法满了洁净的日子，他们就带着孩子上耶路撒冷去，要把他献给主。","notes":[],"heads":["把耶稣献给主"]},{"n":23,"t":"正如主的律法上所记：“凡头生的男子必归主为圣”；","notes":[]},{"n":24,"t":"又要照主的律法上所说，用一对斑鸠，或用两只雏鸽献祭。","notes":[]},{"n":25,"t":"那时，在耶路撒冷有一个人，名叫西面；这人又公义又虔诚，素常盼望以色列的安慰者来到，又有圣灵在他身上。","notes":[]},{"n":26,"t":"他得了圣灵的启示，知道自己未死以前必看见主所立的基督。","notes":[]},{"n":27,"t":"他受了圣灵的感动，进入圣殿，正遇见耶稣的父母抱着孩子进来，要照律法的规矩而行。","notes":[]},{"n":28,"t":"西面就把他抱过来，称颂神说：","notes":[]},{"n":29,"t":"“主啊，如今可以照你的话，容你的仆人安然去世；","notes":[]},{"n":30,"t":"因为我的眼睛已经看见你的救恩，","notes":[]},{"n":31,"t":"就是你在万民面前所预备的：","notes":[]},{"n":32,"t":"是启示外邦人的光，是你民以色列的荣耀。”","notes":[]},{"n":33,"t":"孩子的父母因论耶稣的这些话就惊讶。","notes":[]},{"n":34,"t":"西面给他们祝福，又对孩子的母亲马利亚说：“这孩子被立，是要叫以色列中许多人跌倒，许多人兴起；又要成为毁谤的对象，","notes":[]},{"n":35,"t":"叫许多人心里的意念显露出来；你自己的心也要被剑刺透。”","notes":[]},{"n":36,"t":"又有位女先知，名叫亚拿，是亚设支派法内力的女儿，年纪已经老迈，从童女出嫁，同丈夫住了七年，","notes":[]},{"n":37,"t":"就寡居了，现在已经八十四岁。她不离开圣殿，禁食祈求，昼夜事奉神。","notes":["“就寡居了，现在已经八十四岁”或译“就寡居了八十四年”。"]},{"n":38,"t":"正当那时，她进前来感谢神，对一切盼望耶路撒冷得救赎的人讲论这孩子的事。","notes":[]},{"n":39,"t":"约瑟和马利亚照主的律法办完了一切的事，就回加利利，到自己的城拿撒勒去了。","notes":[],"heads":["回拿撒勒"]},{"n":40,"t":"孩子渐渐长大，强健起来，充满智慧，又有神的恩典在他身上。","notes":[]},{"n":41,"t":"每年逾越节，他父母都上耶路撒冷去。","notes":[],"heads":["少年耶稣在圣殿里"]},{"n":42,"t":"当他十二岁的时候，他们按着过节的规矩上去。","notes":[]},{"n":43,"t":"守满了节期，他们回去，孩童耶稣仍旧在耶路撒冷。他的父母并不知道，","notes":[]},{"n":44,"t":"以为他在同行的人中间，走了一天的路程才在亲属和熟悉的人中找他，","notes":[]},{"n":45,"t":"既找不着，就回耶路撒冷去找他。","notes":[]},{"n":46,"t":"过了三天，他们发现他在圣殿里，坐在教师中间，一面听，一面问。","notes":[]},{"n":47,"t":"凡听见他的人都对他的聪明和应对感到惊奇。","notes":[]},{"n":48,"t":"他父母看见就很惊奇。他母亲对他说：“我儿啊，为什么对我们这样做呢？看哪，你父亲和我很焦急，到处找你！”","notes":[]},{"n":49,"t":"耶稣对他们说：“为什么找我呢？难道你们不知道我应当在我父的家里吗？”","notes":["“难道你们不知道我应当在我父的家里吗？”或译“难道你们不知道我应当以我父的事为念吗？”"]},{"n":50,"t":"他所说的这话，他们不明白。","notes":[]},{"n":51,"t":"他就同他们下去，回到拿撒勒，并且顺从他们。他母亲把这一切的事都存在心里。","notes":[]},{"n":52,"t":"耶稣的智慧和身量，并神和人喜爱他的心，都一齐增长。","notes":["“身量”或译“年纪”。"]}]},"3":{"heading":"施洗约翰传道","verses":[{"n":1,"t":"凯撒提庇留在位第十五年，本丢．彼拉多作犹太总督，希律作加利利分封的王，他兄弟腓力作以土利亚和特拉可尼地区分封的王，吕撒聂作亚比利尼分封的王，","notes":[]},{"n":2,"t":"亚那和该亚法作大祭司。那时，撒迦利亚的儿子约翰在旷野里，神的话临到他。","notes":[]},{"n":3,"t":"他就走遍约旦河一带地方，宣讲悔改的洗礼，使罪得赦。","notes":[]},{"n":4,"t":"正如以赛亚先知书上所记的话：“在旷野有声音呼喊着：预备主的道，修直他的路！","notes":[]},{"n":5,"t":"一切山洼都要填满；大小山冈都要削平！弯弯曲曲的地方要改为笔直；高高低低的道路要改为平坦！","notes":[]},{"n":6,"t":"凡有血肉之躯的，都要看见神的救恩！”","notes":[]},{"n":7,"t":"约翰对那出来要受他洗的众人说：“毒蛇的孽种啊，谁指示你们逃避那将要来的愤怒呢？","notes":[]},{"n":8,"t":"你们要结出果子来，和悔改的心相称。不要自己心里说：‘我们有亚伯拉罕为祖宗。’我告诉你们，神能从这些石头中给亚伯拉罕兴起子孙来。","notes":[]},{"n":9,"t":"现在斧子已经放在树根上，凡不结好果子的树就砍下来，丢在火里。”","notes":[]},{"n":10,"t":"众人问他：“这样，我们该做什么呢？”","notes":[]},{"n":11,"t":"约翰回答：“有两件衣裳的，就分给那没有的；有食物的，也该这样做。”","notes":[]},{"n":12,"t":"也有税吏来要受洗，对他说：“老师，我们该做什么呢？”","notes":[]},{"n":13,"t":"约翰对他们说：“除了规定的数目，不要多收。”","notes":[]},{"n":14,"t":"也有士兵问他说：“我们该做什么呢？”约翰说：“不要勒索任何人，也不要敲诈人；自己有粮饷就该知足。”","notes":[]},{"n":15,"t":"百姓期待基督的来临；他们心里猜测，或许约翰是基督。","notes":[]},{"n":16,"t":"约翰对众人说：“我是用水给你们施洗，但有一位能力比我更大的要来，我就是给他解鞋带也不配。他要用圣灵与火给你们施洗。","notes":[]},{"n":17,"t":"他手里拿着簸箕，要扬净他的谷物，把麦子收在仓里，把糠用不灭的火烧尽。”","notes":[]},{"n":18,"t":"约翰又用许多别的话劝百姓，向他们传福音。","notes":[]},{"n":19,"t":"希律分封王，因他兄弟之妻希罗底的缘故，并因他所做的一切恶事，受了约翰的责备。","notes":[]},{"n":20,"t":"希律在一切事上又添了这一件，就是把约翰收在监里。","notes":[]},{"n":21,"t":"众百姓都受了洗，耶稣也受了洗。他正祷告的时候，天开了，","notes":[],"heads":["耶稣受洗"]},{"n":22,"t":"圣灵降在他身上，形状仿佛鸽子；又有声音从天上来，说：“你是我的爱子，我喜爱你。”","notes":[]},{"n":23,"t":"耶稣开始传道，年纪约有三十岁。依人看来，他是约瑟的儿子，约瑟是希里的儿子，","notes":[],"heads":["耶稣的家谱"]},{"n":24,"t":"希里是玛塔的儿子，玛塔是利未的儿子，利未是麦基的儿子，麦基是雅拿的儿子，雅拿是约瑟的儿子，","notes":[]},{"n":25,"t":"约瑟是玛他提亚的儿子，玛他提亚是亚摩斯的儿子，亚摩斯是拿鸿的儿子，拿鸿是以斯利的儿子，以斯利是拿该的儿子，","notes":[]},{"n":26,"t":"拿该是玛押的儿子，玛押是玛他提亚的儿子，玛他提亚是西美的儿子，西美是约瑟的儿子，约瑟是犹大的儿子，犹大是约亚拿的儿子，","notes":[]},{"n":27,"t":"约亚拿是利撒的儿子，利撒是所罗巴伯的儿子，所罗巴伯是撒拉铁的儿子，撒拉铁是尼利的儿子，尼利是麦基的儿子，","notes":[]},{"n":28,"t":"麦基是亚底的儿子，亚底是哥桑的儿子，哥桑是以摩当的儿子，以摩当是珥的儿子，珥是约细的儿子，","notes":[]},{"n":29,"t":"约细是以利以谢的儿子，以利以谢是约令的儿子，约令是玛塔的儿子，玛塔是利未的儿子，","notes":[]},{"n":30,"t":"利未是西缅的儿子，西缅是犹大的儿子，犹大是约瑟的儿子，约瑟是约南的儿子，约南是以利亚敬的儿子，","notes":[]},{"n":31,"t":"以利亚敬是米利亚的儿子，米利亚是买南的儿子，买南是玛达他的儿子，玛达他是拿单的儿子，拿单是大卫的儿子，","notes":[]},{"n":32,"t":"大卫是耶西的儿子，耶西是俄备得的儿子，俄备得是波阿斯的儿子，波阿斯是沙拉的儿子，沙拉是拿顺的儿子，","notes":["有古卷是“波阿斯是撒门的儿子，撒门是拿顺的儿子”。"]},{"n":33,"t":"拿顺是亚米拿达的儿子，亚米拿达是亚民的儿子，亚民是亚尼的儿子，亚尼是希斯仑的儿子，希斯仑是法勒斯的儿子，法勒斯是犹大的儿子，","notes":["有古卷是“亚米拿达是亚兰的儿子，亚兰是希斯仑的儿子”；其他古卷的内文有许多不同。"]},{"n":34,"t":"犹大是雅各的儿子，雅各是以撒的儿子，以撒是亚伯拉罕的儿子，亚伯拉罕是他拉的儿子，他拉是拿鹤的儿子，","notes":[]},{"n":35,"t":"拿鹤是西鹿的儿子，西鹿是拉吴的儿子，拉吴是法勒的儿子，法勒是希伯的儿子，希伯是沙拉的儿子，","notes":[]},{"n":36,"t":"沙拉是该南的儿子，该南是亚法撒的儿子，亚法撒是闪的儿子，闪是挪亚的儿子，挪亚是拉麦的儿子，","notes":[]},{"n":37,"t":"拉麦是玛土撒拉的儿子，玛土撒拉是以诺的儿子，以诺是雅列的儿子，雅列是玛勒列的儿子，玛勒列是该南的儿子，该南是以挪士的儿子，","notes":[]},{"n":38,"t":"以挪士是塞特的儿子，塞特是亚当的儿子，亚当是神的儿子。","notes":[]}]},"4":{"heading":"耶稣受试探","verses":[{"n":1,"t":"耶稣满有圣灵，从约旦河回来，圣灵把他引到旷野，","notes":[]},{"n":2,"t":"四十天受魔鬼的试探。在那些日子，他没有吃什么，日子满了，他饿了。","notes":[]},{"n":3,"t":"魔鬼对他说：“你若是神的儿子，叫这块石头变成食物吧。”","notes":[]},{"n":4,"t":"耶稣回答说：“经上记着：‘人活着，不是单靠食物。’”","notes":["有古卷加“乃是靠神口里所出的一切话。”"]},{"n":5,"t":"魔鬼又领他上了高山，霎时间把天下万国都指给他看，","notes":[]},{"n":6,"t":"对他说：“这一切权柄和荣华我都要给你，因为这原是交给我的，我愿意给谁就给谁。","notes":[]},{"n":7,"t":"你若在我面前下拜，这一切都归你。”","notes":[]},{"n":8,"t":"耶稣回答他说：“经上记着：‘要拜主—你的神，惟独事奉他。’”","notes":[]},{"n":9,"t":"魔鬼又领他到耶路撒冷去，叫他站在圣殿顶上，对他说：“你若是神的儿子，从这里跳下去！","notes":[]},{"n":10,"t":"因为经上记着：‘主要为你命令他的使者保护你；","notes":[]},{"n":11,"t":"他们要用手托住你，免得你的脚碰在石头上。’”","notes":[]},{"n":12,"t":"耶稣回答他说：“经上说：‘不可试探主—你的神。’”","notes":[]},{"n":13,"t":"魔鬼用完了各样的试探，就离开耶稣，再等时机。","notes":[]},{"n":14,"t":"耶稣带着圣灵的能力回到加利利，他的名声传遍了四方。","notes":[],"heads":["开始在加利利传道"]},{"n":15,"t":"他在各会堂里教导人，众人都称赞他。","notes":[]},{"n":16,"t":"耶稣来到拿撒勒，就是他长大的地方。在安息日，照他素常的规矩进了会堂，站起来要念圣经。","notes":[],"heads":["拿撒勒人厌弃耶稣"]},{"n":17,"t":"有人把以赛亚先知的书交给他，他就打开，找到一处写着：","notes":[]},{"n":18,"t":"“主的灵在我身上，因为他用膏膏我，叫我传福音给贫穷的人；差遣我宣告：被掳的得释放，失明的得看见，受压迫的得自由，","notes":[]},{"n":19,"t":"宣告神悦纳人的禧年。”","notes":[]},{"n":20,"t":"于是他把书卷起来，交还给管理人，就坐下。会堂里的人都定睛看他。","notes":[]},{"n":21,"t":"耶稣对他们说：“你们听见的这段经文，今天已经应验了。”","notes":[]},{"n":22,"t":"众人都称赞他，并对他口中所出的恩言感到惊讶；他们说：“这不是约瑟的儿子吗？”","notes":[]},{"n":23,"t":"耶稣对他们说：“你们一定会用这俗语向我说：‘医生，你医治自己吧！我们听见你在迦百农所做的事，也该在你自己的家乡做吧。’”","notes":[]},{"n":24,"t":"他又说：“我实在告诉你们，没有先知在自己家乡被人接纳的。","notes":[]},{"n":25,"t":"我对你们说实话，在以利亚的时候，天闭塞了三年六个月，遍地有大饥荒，那时，以色列中有许多寡妇，","notes":[]},{"n":26,"t":"以利亚并没有奉差往她们中任何一个人那里去，只奉差往西顿的撒勒法一个寡妇那里去。","notes":[]},{"n":27,"t":"在以利沙先知的时候，以色列中有许多麻风病人，但除了叙利亚的乃缦，没有一个得洁净的。”","notes":[]},{"n":28,"t":"会堂里的人听见这些话，都怒气填胸，","notes":[]},{"n":29,"t":"就起来赶他出城。他们的城造在山上；他们带他到山崖，要把他推下去。","notes":[]},{"n":30,"t":"他却从他们中间穿过去，走了。","notes":[]},{"n":31,"t":"耶稣下到迦百农，就是加利利的一座城，在安息日教导众人。","notes":[],"heads":["耶稣赶逐污灵"]},{"n":32,"t":"他们对他的教导感到很惊奇，因为他的话里有权柄。","notes":[]},{"n":33,"t":"在会堂里有一个人，被污鬼的灵附着，大声喊叫说：","notes":[]},{"n":34,"t":"“唉！拿撒勒人耶稣，你为什么干扰我们？你来消灭我们吗？我知道你是谁，你是神的圣者。”","notes":[]},{"n":35,"t":"耶稣斥责他说：“不要作声，从这人身上出来吧！”鬼把那人摔倒在众人中间，就出来了，却没有伤害他。","notes":[]},{"n":36,"t":"众人都惊讶，彼此对问：“这是什么道理呢？因为他用权柄能力命令污灵，污灵就出来。”","notes":[]},{"n":37,"t":"于是耶稣的名声传遍了周围各地。","notes":[]},{"n":38,"t":"耶稣出了会堂，进了西门的家。西门的岳母在发高烧，有些人为她求耶稣。","notes":[],"heads":["治好许多病人"]},{"n":39,"t":"耶稣站在她旁边，斥责那高烧，烧就退了。她立刻起来服事他们。","notes":[]},{"n":40,"t":"日落的时候，凡有病人的，不论害什么病，都带到耶稣那里。耶稣给他们每一个人按手，治好他们。","notes":[]},{"n":41,"t":"又有鬼从好些人身上出来，喊着说：“你是神的儿子！”耶稣斥责他们，不许他们说话，因为他们知道他是基督。","notes":[]},{"n":42,"t":"天亮的时候，耶稣出来，走到荒野的地方。众人去找他，到了他那里，要留住他，不让他离开他们。","notes":[],"heads":["在犹太传道"]},{"n":43,"t":"但耶稣对他们说：“我也必须在别的城传神国的福音，因我奉差原是为此。”","notes":[]},{"n":44,"t":"于是耶稣在犹太的各会堂传道。","notes":[]}]},"5":{"heading":"耶稣呼召早先的门徒","verses":[{"n":1,"t":"耶稣站在革尼撒勒湖边，众人拥挤他，要听神的道。","notes":[]},{"n":2,"t":"他见有两只船靠在湖边，打鱼的人却离开船，洗网去了。","notes":[]},{"n":3,"t":"有一只船是西门的，耶稣就上去，请他把船撑开，稍微离岸，就坐下，在船上教导众人。","notes":[]},{"n":4,"t":"他讲完了，对西门说：“把船开到水深的地方下网打鱼。”","notes":[]},{"n":5,"t":"西门说：“老师，我们整夜劳累，并没有打着什么。但依从你的话，我就下网。”","notes":[]},{"n":6,"t":"他们下了网，圈住许多鱼，网险些裂开，","notes":[]},{"n":7,"t":"就招手叫另一只船上的同伴来帮助。他们就来，把鱼装满了两只船，船甚至要沉下去。","notes":[]},{"n":8,"t":"西门．彼得看见，就俯伏在耶稣膝前，说：“主啊，离开我，我是个罪人。”","notes":[]},{"n":9,"t":"他和一切跟他一起的人对打到了这一网的鱼都很惊讶。","notes":[]},{"n":10,"t":"他的伙伴西庇太的儿子雅各、约翰，也是这样。耶稣对西门说：“不要怕！从今以后，你要得人了。”","notes":[]},{"n":11,"t":"他们把两只船靠了岸，就撇下所有的，跟从了耶稣。","notes":[]},{"n":12,"t":"有一回，耶稣在一个城里，有人满身长了麻风，看见他，就俯伏在地，求他说：“主啊，你若肯，你能使我洁净。”","notes":[],"heads":["洁净麻风病人"]},{"n":13,"t":"耶稣伸手摸他，说：“我肯，你洁净了吧！”麻风病立刻离开了他。","notes":[]},{"n":14,"t":"耶稣吩咐他：“你不可告诉任何人，只要去，把自己给祭司察看，又因为你已经洁净，要照摩西所吩咐的献上祭物，作为证据给众人看。”","notes":[]},{"n":15,"t":"但耶稣的名声越发传扬出去。有一大群人聚集来听道，也希望耶稣医治他们的病。","notes":[]},{"n":16,"t":"耶稣却退到旷野去祷告。","notes":[]},{"n":17,"t":"有一天，耶稣教导人，有法利赛人和律法教师在旁边坐着；他们是从加利利各乡村、犹太和耶路撒冷来的。主的能力与耶稣同在，使他能治好病人。","notes":[],"heads":["治好瘫子"]},{"n":18,"t":"这时，有些人用褥子抬着一个瘫子，要把他抬进去放在耶稣面前，","notes":[]},{"n":19,"t":"却因人多，找不出法子抬进去，就上了房顶，从瓦间把他连褥子缒到当中，在耶稣面前。","notes":[]},{"n":20,"t":"耶稣见他们的信心，就说：“朋友，你的罪赦了。”","notes":[]},{"n":21,"t":"文士和法利赛人就开始议论说：“这个人是谁，竟说亵渎的话？除了神一位之外，谁能赦罪呢？”","notes":[]},{"n":22,"t":"耶稣知道他们所议论的，就回答他们说：“你们心里为什么议论呢？","notes":[]},{"n":23,"t":"说‘你的罪赦了’，或说‘你起来行走’，哪一样容易呢？","notes":[]},{"n":24,"t":"但要让你们知道，人子在地上有赦罪的权柄。”他就对瘫子说：“我吩咐你，起来！拿你的褥子回家去吧。”","notes":[]},{"n":25,"t":"那人当着众人面前立刻起来，拿了他所躺卧的褥子回家去，归荣耀给神。","notes":[]},{"n":26,"t":"众人都惊奇，也归荣耀给神，并且满心惧怕，说：“我们今日看见不寻常的事了！”","notes":[]},{"n":27,"t":"这些事以后，耶稣出去，看见一个税吏，名叫利未，在税关坐着，就对他说：“来跟从我！”","notes":[],"heads":["呼召利未"]},{"n":28,"t":"他就撇下所有的，起来跟从耶稣。","notes":[]},{"n":29,"t":"利未在自己家里为耶稣大摆宴席，有一大群税吏和别的人与他们一同坐席。","notes":[]},{"n":30,"t":"法利赛人和文士就向耶稣的门徒发怨言说：“你们为什么跟税吏和罪人一同吃喝呢？”","notes":[]},{"n":31,"t":"耶稣回答他们：“健康的人用不着医生；有病的人才用得着。","notes":[]},{"n":32,"t":"我不是来召义人悔改，而是召罪人悔改。”","notes":[]},{"n":33,"t":"他们对耶稣说：“约翰的门徒常常禁食祈祷，法利赛人的门徒也是这样，惟独跟你在一起的又吃又喝。”","notes":[],"heads":["禁食的问题"]},{"n":34,"t":"耶稣对他们说：“新郎和宾客在一起的时候，你们怎么能叫宾客禁食呢？","notes":[]},{"n":35,"t":"但日子将到，新郎要被带走，那些日子他们就要禁食了。”","notes":[]},{"n":36,"t":"耶稣又讲一个比喻，对他们说：“没有人把新衣服撕下一块来补在旧衣服上，若是这样，会把新的撕裂了，并且所撕下来的那块新的和旧的也不相称。","notes":[]},{"n":37,"t":"也没有人把新酒装在旧皮袋里；若是这样，新酒会胀破皮袋，酒就漏出来，皮袋也糟蹋了。","notes":[]},{"n":38,"t":"相反地，新酒必须装在新皮袋里。","notes":[]},{"n":39,"t":"没有人喝了陈酒又想喝新的；他总说陈的好。”","notes":[]}]},"6":{"heading":"在安息日摘麦穗","verses":[{"n":1,"t":"有一个安息日，耶稣从麦田经过。他的门徒摘了麦穗，用手搓着吃。","notes":["有古卷是“在第二个首安息日”。"]},{"n":2,"t":"有几个法利赛人说：“你们为什么做安息日不合法的事呢？”","notes":[]},{"n":3,"t":"耶稣回答他们：“大卫和跟从他的人饥饿时所做的事，你们没有念过吗？","notes":[]},{"n":4,"t":"他怎么进了神的居所，拿供饼吃，又给跟从的人吃呢？这饼惟独祭司可以吃，别人都不可以吃。”","notes":[]},{"n":5,"t":"他又对他们说：“人子是安息日的主。”","notes":[]},{"n":6,"t":"又有一个安息日，耶稣进了会堂教导人，在那里有一个人，他的右手萎缩了。","notes":[],"heads":["治好萎缩的手"]},{"n":7,"t":"文士和法利赛人窥探耶稣会不会在安息日治病，为要找把柄告他。","notes":[]},{"n":8,"t":"耶稣却知道他们的意念，就对那萎缩了手的人说：“起来，站在当中！”那人就起来，站着。","notes":[]},{"n":9,"t":"耶稣对他们说：“我问你们，在安息日行善行恶，救命害命，哪样是合法的呢？”","notes":[]},{"n":10,"t":"他就环视众人，对那人说：“伸出手来！”他照着做，他的手就复原了。","notes":[]},{"n":11,"t":"他们怒气填胸，彼此商议怎样对付耶稣。","notes":[]},{"n":12,"t":"在那些日子，耶稣出去，上山祈祷，整夜向神祷告。","notes":[],"heads":["拣选十二使徒"]},{"n":13,"t":"到了天亮，他叫门徒来，就从他们中间挑选十二个人，称他们为使徒。","notes":[]},{"n":14,"t":"这十二个人有西门（耶稣又给他起名叫彼得），还有他弟弟安得烈，又有雅各和约翰，腓力和巴多罗买，","notes":[]},{"n":15,"t":"马太和多马，亚勒腓的儿子雅各和激进党的西门，","notes":[]},{"n":16,"t":"雅各的儿子犹大和后来成为出卖者的加略人犹大。","notes":[]},{"n":17,"t":"耶稣和他们下了山，站在一块平地上；在一起的有许多门徒，又有许多百姓从全犹太和耶路撒冷，并推罗、西顿的海边来，","notes":[],"heads":["向大众传道"]},{"n":18,"t":"都要听他讲道，又希望耶稣医治他们的病；还有被污灵缠磨的，也得了医治。","notes":[]},{"n":19,"t":"众人都想要摸他，因为有能力从他身上发出来，治好了他们。","notes":[]},{"n":20,"t":"耶稣举目看着门徒，说：“贫穷的人有福了！因为神的国是你们的。","notes":[],"heads":["论福与祸"]},{"n":21,"t":"现在饥饿的人有福了！因为你们将得饱足。现在哭泣的人有福了！因为你们将要欢笑。","notes":[]},{"n":22,"t":"人为人子的缘故憎恨你们，拒绝你们，辱骂你们，把你们当恶人除掉你们的名，你们就有福了！","notes":[]},{"n":23,"t":"在那日，你们要欢欣雀跃，因为你们在天上的赏赐是很多的；他们的祖宗也是这样待先知的。","notes":[]},{"n":24,"t":"但你们富足的人有祸了！因为你们已经受过安慰。","notes":[]},{"n":25,"t":"你们现在饱足的人有祸了！因为你们将要饥饿。你们现在欢笑的人有祸了！因为你们将要哀恸哭泣。","notes":[]},{"n":26,"t":"人都说你们好的时候，你们有祸了！因为他们的祖宗也是这样待假先知的。”","notes":[]},{"n":27,"t":"“可是我告诉你们这些听的人，要爱你们的仇敌！要善待恨你们的人！","notes":[],"heads":["论爱仇敌"]},{"n":28,"t":"要祝福诅咒你们的人！要为凌辱你们的人祷告！","notes":[]},{"n":29,"t":"有人打你的脸，连另一边也由他打。有人拿你的外衣，连内衣也由他拿去。","notes":[]},{"n":30,"t":"凡求你的，就给他；有人拿走你的东西，不要讨回来。","notes":[]},{"n":31,"t":"“你们想要人怎样待你们，你们也要怎样待人。","notes":[]},{"n":32,"t":"你们若只爱那爱你们的人，有什么可感谢的呢？就是罪人也爱那爱他们的人。","notes":[]},{"n":33,"t":"你们若善待那善待你们的人，有什么可感谢的呢？就是罪人也是这样做。","notes":[]},{"n":34,"t":"你们若借给人，希望从他收回，有什么可感谢的呢？就是罪人也借给罪人，再如数收回。","notes":[]},{"n":35,"t":"你们倒要爱仇敌，要善待他们，并要借给人不指望偿还，你们的赏赐就很多了，你们必作至高者的儿子，因为他恩待那忘恩的和作恶的。","notes":[]},{"n":36,"t":"你们要仁慈，像你们的父是仁慈的。”","notes":[]},{"n":37,"t":"“你们不要评断别人，就不被审判；你们不要定人的罪，就不被定罪；你们要饶恕人，就必蒙饶恕。","notes":[],"heads":["不要评断人"]},{"n":38,"t":"你们要给人，就必有给你们的，并且用十足的升斗，连摇带按，上尖下流地倒在你们怀里；因为你们用什么量器量给人，也必用什么量器量给你们。”","notes":[]},{"n":39,"t":"耶稣又用比喻对他们说：“瞎子岂能领瞎子，两个人不是都要掉在坑里吗？","notes":[]},{"n":40,"t":"学生不高过老师，凡学成了的会和老师一样。","notes":[]},{"n":41,"t":"为什么看见你弟兄眼中有刺，却不想自己眼中有梁木呢？","notes":[]},{"n":42,"t":"你不见自己眼中有梁木，怎能对你弟兄说：‘让我去掉你眼中的刺’呢？你这假冒为善的人！先去掉自己眼中的梁木，然后才能看得清楚，好去掉你弟兄眼中的刺。”","notes":[]},{"n":43,"t":"“没有好树结坏果子，也没有坏树结好果子。","notes":[],"heads":["树和果子"]},{"n":44,"t":"每一种树木可以从其果子看出来。人不是从荆棘上摘无花果的，也不是从蒺藜里摘葡萄的。","notes":[]},{"n":45,"t":"善人从他心里所存的善发出善来，恶人从他所存的恶发出恶来；因为心里所充满的，口里就说出来。”","notes":[]},{"n":46,"t":"“你们为什么称呼我‘主啊，主啊’，却不照我的话做呢？","notes":[],"heads":["两种根基"]},{"n":47,"t":"凡到我这里来，听了我的话又去做的，我要告诉你们他像什么人：","notes":[]},{"n":48,"t":"他像一个人盖房子，把地挖深，将根基立在磐石上，到发大水的时候，水冲那房子，房子总不动摇，因为盖造得好。","notes":[]},{"n":49,"t":"但听了不去做的，就像一个人在土地上盖房子，没有根基，水一冲，立刻倒塌了，并且那房子损坏得很厉害。”","notes":[]}]},"7":{"heading":"治好百夫长的僮仆","verses":[{"n":1,"t":"耶稣对百姓讲完了这一切的话，就进了迦百农。","notes":[]},{"n":2,"t":"有一个百夫长所器重的仆人害病，快要死了。","notes":[]},{"n":3,"t":"百夫长风闻耶稣的事，就托犹太人的几个长老去求耶稣来救他的仆人。","notes":[]},{"n":4,"t":"他们到了耶稣那里，切切地求他说：“你为他做这事是他配得的；","notes":[]},{"n":5,"t":"因为他爱我们的民族，为我们建造会堂。”","notes":[]},{"n":6,"t":"耶稣就和他们同去。离那家不远，百夫长托几个朋友去见耶稣，对他说：“主啊，不必劳驾，因你到舍下来，我不敢当。","notes":[]},{"n":7,"t":"我也自以为不配去见你，只要你说一句话，就会让我的僮仆得痊愈。","notes":[]},{"n":8,"t":"因为我被派在人的权下，也有兵在我之下。我对这个说：‘去！’他就去；对那个说：‘来！’他就来；对我的仆人说：‘做这事！’他就去做。”","notes":[]},{"n":9,"t":"耶稣听到这些话，就很惊讶，转身对跟随的众人说：“我告诉你们，这么大的信心，就是在以色列，我也没有见过。”","notes":[]},{"n":10,"t":"那差来的人回到百夫长家里，发现仆人已经好了。","notes":[]},{"n":11,"t":"过了不久，耶稣往一座城去，这城名叫拿因，他的门徒和一大群人与他同行。","notes":["有古卷是“次日”。"],"heads":["使寡妇的独子起死回生"]},{"n":12,"t":"当他走近城门时，有一个死人被抬出来。这人是他母亲独生的儿子，而他母亲又是寡妇。城里的许多人与她一同送殡。","notes":[]},{"n":13,"t":"主看见那寡妇就怜悯她，对她说：“不要哭。”","notes":[]},{"n":14,"t":"于是耶稣进前来，按着杠，抬的人就站住了。耶稣说：“年轻人，我吩咐你，起来！”","notes":[]},{"n":15,"t":"那死人就坐了起来，开始说话，耶稣就把他交给他的母亲。","notes":[]},{"n":16,"t":"众人都惊奇，归荣耀给神，说：“有大先知在我们当中兴起了！”又说：“神眷顾了他的百姓！”","notes":[]},{"n":17,"t":"关于耶稣的这事就传遍了犹太和周围地区。","notes":[]},{"n":18,"t":"约翰的门徒把这些事都告诉约翰。于是约翰叫了两个门徒来，","notes":[],"heads":["施洗约翰差人问主"]},{"n":19,"t":"差他们到主那里去，说：“将要来的那位就是你吗？还是我们要等候别人呢？”","notes":["“主”：有古卷是“耶稣”；另有古卷是“主耶稣”。"]},{"n":20,"t":"那两个人来到耶稣那里，说：“施洗的约翰差我们来问你：‘将要来的那位就是你吗？还是我们要等候别人呢？’”","notes":[]},{"n":21,"t":"就在那时，耶稣治好了许多患疾病的，得瘟疫的，被邪灵附身的，又开恩使好些盲人能看见。","notes":[]},{"n":22,"t":"耶稣回答他们：“你们去，把所看见、所听见的告诉约翰：就是盲人看见，瘸子行走，麻风病人得洁净，聋子听见，死人复活，穷人听到福音。","notes":[]},{"n":23,"t":"凡不因我跌倒的有福了！”","notes":[]},{"n":24,"t":"约翰所差来的人一走，耶稣就对众人谈到约翰，说：“你们从前到旷野去，是要看什么呢？被吹动的芦苇吗？","notes":[]},{"n":25,"t":"你们出去到底是要看什么？穿细软衣服的人吗？看哪，那穿华丽衣服、宴乐度日的人是在王宫里。","notes":[]},{"n":26,"t":"你们出去究竟是要看什么？是先知吗？是的，我告诉你们，他比先知大多了。","notes":[]},{"n":27,"t":"这个人就是经上所说的：‘看哪，我要差遣我的使者在你面前，他要在你前面为你预备道路。’","notes":[]},{"n":28,"t":"我告诉你们，凡女子所生的，没有比约翰大的；但在神国里，最小的比他还大。”","notes":[]},{"n":29,"t":"众百姓和税吏已受过约翰的洗，听见这话，就以神为义；","notes":[]},{"n":30,"t":"但法利赛人和律法师没有受过约翰的洗，竟废弃了神为他们所定的旨意。","notes":["29-30两节或译“众百姓和税吏听见了约翰的话，就受了他的洗，就以神为义；但法利赛人和律法师不受约翰的洗，竟为自己废弃了神为他们所定的旨意。”"]},{"n":31,"t":"主又说：“这样，我该用什么来比这世代的人呢？他们好像什么呢？","notes":[]},{"n":32,"t":"这正像孩童坐在街市上，彼此喊叫：‘我们为你们吹笛，你们不跳舞；我们唱哀歌，你们不啼哭。’","notes":[]},{"n":33,"t":"施洗的约翰来，不吃饼，不喝酒，你们说他是被鬼附的。","notes":[]},{"n":34,"t":"人子来，也吃也喝，你们又说这人贪食好酒，是税吏和罪人的朋友。","notes":[]},{"n":35,"t":"而智慧是由所有智慧的人来证实的。”","notes":[]},{"n":36,"t":"有一个法利赛人请耶稣和他吃饭，耶稣就到那法利赛人家里去坐席。","notes":[],"heads":["有罪的女人得蒙赦免"]},{"n":37,"t":"那城里有一个女人，是个罪人，知道耶稣在法利赛人家里坐席，就拿着盛满香膏的玉瓶，","notes":[]},{"n":38,"t":"站在耶稣背后，挨着他的脚哭，眼泪滴湿了耶稣的脚，就用自己的头发擦干，又用嘴连连亲他的脚，把香膏抹上。","notes":[]},{"n":39,"t":"请耶稣的法利赛人看见这事，心里说：“这人若是先知，一定知道摸他的是谁，是个怎样的女人；她是个罪人哪！”","notes":[]},{"n":40,"t":"耶稣回应他说：“西门，我有话要对你说。”西门说：“老师，请说。”","notes":[]},{"n":41,"t":"耶稣说：“有两个人欠了某一个债主的钱，一个欠五百个银币，一个欠五十个银币。","notes":[]},{"n":42,"t":"因为他们无力偿还，债主就开恩赦免了他们两个人的债。那么，这两个人哪一个更爱他呢？”","notes":[]},{"n":43,"t":"西门回答：“我想是那多得赦免的人。”耶稣对他说：“你的判断不错。”","notes":[]},{"n":44,"t":"于是他转过来向着那女人，对西门说：“你看见这女人吗？我进了你的家，你没有给我水洗脚，但这女人用眼泪滴湿了我的脚，又用头发擦干。","notes":[]},{"n":45,"t":"你没有亲我，但这女人从我进来就不住地亲我的脚。","notes":[]},{"n":46,"t":"你没有用油抹我的头，但这女人用香膏抹我的脚。","notes":[]},{"n":47,"t":"所以我告诉你，她许多的罪都赦免了，因为她爱的多；而那少得赦免的，爱的就少。”","notes":[]},{"n":48,"t":"于是耶稣对那女人说：“你的罪都赦免了。”","notes":[]},{"n":49,"t":"同席的人心里说：“这是什么人，竟赦免人的罪呢？”","notes":[]},{"n":50,"t":"耶稣对那女人说：“你的信救了你，平安地回去吧！”","notes":[]}]},"8":{"heading":"跟从耶稣的妇女们","verses":[{"n":1,"t":"过了不久，耶稣周游各城各乡传道，宣讲神国的福音。和他同去的有十二个使徒，","notes":[]},{"n":2,"t":"还有曾被邪灵所附，被疾病所缠，而已经治好的几个妇女，其中有称为抹大拉的马利亚，曾有七个鬼从她身上赶出来，","notes":[]},{"n":3,"t":"又有希律的管家苦撒的妻子约亚拿，和苏撒拿以及好些别的妇女，她们都是用自己的财物供给耶稣和使徒。","notes":[]},{"n":4,"t":"当一大群人聚集，又有人从各城里出来见耶稣的时候，耶稣用比喻说：","notes":[],"heads":["撒种的比喻"]},{"n":5,"t":"“有一个撒种的出去撒种。他撒的时候，有的落在路旁，被人践踏，天上的飞鸟又来把它吃掉了。","notes":[]},{"n":6,"t":"有的落在磐石上，一出来就枯干了，因为得不着滋润。","notes":[]},{"n":7,"t":"有的落在荆棘里，荆棘跟它一同生长，把它挤住了。","notes":[]},{"n":8,"t":"又有的落在好土里，生长起来，结实百倍。”耶稣说完这些话，大声说：“有耳可听的，就应当听！”","notes":[]},{"n":9,"t":"门徒问耶稣这比喻是什么意思。","notes":[],"heads":["用比喻的目的"]},{"n":10,"t":"他说：“神国的奥秘只让你们知道，至于别人，就用比喻，要他们看也看不见，听也不明白。”","notes":[]},{"n":11,"t":"“这比喻是这样的：种子就是神的道。","notes":[],"heads":["解释撒种的比喻"]},{"n":12,"t":"那些在路旁的，就是人听了道，随后魔鬼来，从他们心里把道夺去，以免他们信了得救。","notes":[]},{"n":13,"t":"那些在磐石上的，就是人听道，欢喜领受，但没有根，不过暂时相信，等到碰上试炼就退后了。","notes":[]},{"n":14,"t":"那落在荆棘里的，就是人听了道，走开以后，被今生的忧虑、钱财、宴乐挤住了，结不出成熟的子粒来。","notes":[]},{"n":15,"t":"那落在好土里的，就是人听了道，并用纯真善良的心持守它，耐心等候结果实。”","notes":[]},{"n":16,"t":"“没有人点灯用器皿盖上，或放在床底下，而是放在灯台上，让进来的人看见亮光。","notes":[],"heads":["器皿下的灯"]},{"n":17,"t":"因为掩藏的事没有不显出来的，隐瞒的事也没有不露出来被人知道的。","notes":[]},{"n":18,"t":"所以，你们应当小心怎样听。因为凡有的，还要给他；凡没有的，连他自以为有的也要夺去。”","notes":[]},{"n":19,"t":"耶稣的母亲和他兄弟来看他，因为人多，不能到他跟前。","notes":[],"heads":["遵父旨意的人都是亲属"]},{"n":20,"t":"有人告诉他说：“你母亲和你兄弟站在外边，要见你。”","notes":[]},{"n":21,"t":"耶稣回答他们：“听了神的道而遵行的人，就是我的母亲，我的兄弟了。”","notes":[]},{"n":22,"t":"有一天，耶稣和门徒上了船，他对门徒说：“我们渡到湖的对岸去吧。”他们就开了船。","notes":[],"heads":["平静风和海"]},{"n":23,"t":"船行的时候，耶稣睡着了。湖上忽然起了狂风，船将灌满了水，很危险。","notes":[]},{"n":24,"t":"门徒去叫醒他，说：“老师！老师！我们快没命啦！”耶稣醒了，斥责那狂风大浪，风浪就止住，平静了。","notes":[]},{"n":25,"t":"耶稣对他们说：“你们的信心在哪里呢？”他们又惧怕又惊讶，彼此说：“这到底是谁？他吩咐风和水，连风和水都听从他。”","notes":[]},{"n":26,"t":"他们到了格拉森人的地区，就在加利利的对面。","notes":["有古卷是“格各森”，另有古卷是“加大拉”；37节同。"],"heads":["治好格拉森被鬼附的人"]},{"n":27,"t":"耶稣上了岸，就有城里一个被鬼附的人迎着他走来。这个人好久不穿衣服，不住在屋子里，而住在坟墓里。","notes":[]},{"n":28,"t":"他看见耶稣，就喊叫着俯伏在他面前，大声说：“至高神的儿子耶稣，你为什么干扰我？我求你，不要叫我受苦！”","notes":[]},{"n":29,"t":"这是因耶稣曾吩咐污灵从这人身上出来。原来这污灵屡次抓住他；他常被人看守，又被铁链和脚镣捆锁，他竟把锁链挣断，被鬼赶到旷野去。","notes":[]},{"n":30,"t":"耶稣问他：“你的名字叫什么？”他说：“群”；这是因为附着他的鬼多。","notes":[]},{"n":31,"t":"鬼就央求耶稣不要命令他们到无底坑里去。","notes":[]},{"n":32,"t":"那里有一大群猪正在山坡上吃食，鬼央求耶稣准他们进入猪里；耶稣准了他们。","notes":[]},{"n":33,"t":"于是鬼从那人出来，进入猪里，那群猪就闯下山崖，投进湖里，淹死了。","notes":[]},{"n":34,"t":"放猪的看见这事就逃跑了，去告诉城里和乡下的人。","notes":[]},{"n":35,"t":"众人出来，要看发生了什么事；到了耶稣那里，发现那人坐在耶稣脚前，鬼已离开了他，穿着衣服，神智清醒，他们就害怕。","notes":[]},{"n":36,"t":"看见这事的人把被鬼附的人怎么得医治的事告诉他们。","notes":[]},{"n":37,"t":"格拉森周围地区的人，因为害怕得很，都求耶稣离开他们；耶稣就上船回去了。","notes":[]},{"n":38,"t":"鬼已从身上出去的那人恳求要和耶稣在一起，耶稣却打发他回去，说：","notes":[]},{"n":39,"t":"“你回家去，传讲神为你做了多么大的事。”他就走遍全城，传扬耶稣为他做了多么大的事。","notes":[]},{"n":40,"t":"耶稣回来的时候，众人迎接他，因为他们都等候着他。","notes":[],"heads":["叶鲁的女儿和经血不止的女人"]},{"n":41,"t":"有一个会堂主管，名叫叶鲁，来俯伏在耶稣脚前，求耶稣到他家里去，","notes":[]},{"n":42,"t":"因为他有一个独生女，约十二岁，快要死了。耶稣去的时候，众人簇拥着他。","notes":[]},{"n":43,"t":"有一个女人，患了经血不止的病有十二年，在医生手里花尽了一生所有的，但没有人能治好她。","notes":["有古卷没有“在医生手里…一生所有的”。"]},{"n":44,"t":"她来到耶稣背后，摸他的衣裳繸子，经血立刻止住了。","notes":[]},{"n":45,"t":"耶稣说：“摸我的是谁？”众人都不承认。彼得说：“老师，众人拥拥挤挤紧靠着你。”","notes":[]},{"n":46,"t":"耶稣说：“有人摸了我，因为我觉得有能力从我身上出去。”","notes":[]},{"n":47,"t":"那女人知道瞒不住了，就战战兢兢地俯伏在耶稣跟前，把摸他的缘故和怎样立刻痊愈的事，当着众人都说出来。","notes":[]},{"n":48,"t":"耶稣对她说：“女儿，你的信救了你。平安地回去吧！”","notes":[]},{"n":49,"t":"耶稣还在说话的时候，有人从会堂主管的家里来，说：“你的女儿死了，不要劳驾老师了。”","notes":[]},{"n":50,"t":"耶稣听见就对他说：“不要怕，只要信！她必得痊愈。”","notes":[]},{"n":51,"t":"耶稣到了他的家，除了彼得、约翰、雅各，和女儿的父母，不许别人同他进去。","notes":[]},{"n":52,"t":"众人都在为这女孩哀哭捶胸。耶稣说：“不要哭，她不是死了，是睡着了。”","notes":[]},{"n":53,"t":"他们知道她已经死了，就嘲笑耶稣。","notes":[]},{"n":54,"t":"耶稣拉着她的手，呼叫着：“孩子，起来吧！”","notes":[]},{"n":55,"t":"她的灵魂就回来了，她立刻起来。耶稣吩咐给她东西吃。","notes":[]},{"n":56,"t":"她的父母非常惊奇；耶稣吩咐他们不要把所发生的事告诉任何人。","notes":[]}]},"9":{"heading":"耶稣差遣十二使徒","verses":[{"n":1,"t":"耶稣叫齐了十二使徒，给他们能力和权柄制伏一切的鬼，医治疾病，","notes":[]},{"n":2,"t":"又差遣他们宣讲神的国，医治病人，","notes":[]},{"n":3,"t":"对他们说：“途中什么都不要带；不要带手杖和行囊，不要带食物和银钱，也不要带两件内衣。","notes":["有古卷是“每人也不要带两件内衣”。"]},{"n":4,"t":"你们无论进哪一家，就住在哪里，也从那里离开。","notes":[]},{"n":5,"t":"凡不接待你们的，你们离开那城的时候，要跺掉你们脚上的尘土，证明他们的不是。”","notes":[]},{"n":6,"t":"于是使徒出去，走遍各乡传福音，到处治病。","notes":[]},{"n":7,"t":"希律分封王听见耶稣所做的一切事，就困惑起来，因为有人说：“约翰从死人中复活了。”","notes":[],"heads":["希律的困惑"]},{"n":8,"t":"又有人说：“以利亚显现了。”还有人说：“古时的一个先知又活了。”","notes":[]},{"n":9,"t":"希律说：“约翰我已经斩了，但这是什么人？关于他，我竟听到这样的事！”于是希律想要见他。","notes":[]},{"n":10,"t":"使徒们回来，把所做的事告诉耶稣，耶稣就私下带他们离开那里，往一座叫伯赛大的城去。","notes":[],"heads":["耶稣使五千人吃饱"]},{"n":11,"t":"众人知道了，就跟着他去；耶稣接待他们，对他们讲论神国的事，治好那些需要医治的人。","notes":[]},{"n":12,"t":"太阳快要下山，十二使徒进前来对他说：“请叫众人散去，他们好往四面村庄乡镇里去借宿和找吃的，因为我们这里地方偏僻。”","notes":[]},{"n":13,"t":"耶稣对他们说：“你们给他们吃吧！”他们说：“我们不过有五个饼、两条鱼，若不去为这许多人买食物就不够。”","notes":[]},{"n":14,"t":"那时，男人约有五千。耶稣对门徒说：“叫他们分组坐下，每组大约五十个人。”","notes":[]},{"n":15,"t":"门徒就这样做了，叫众人都坐下。","notes":[]},{"n":16,"t":"耶稣拿着这五个饼和两条鱼，望着天祝福，擘开，递给门徒，摆在众人面前。","notes":[]},{"n":17,"t":"所有的人都吃，并且吃饱了。他们把剩下的碎屑收拾起来，装满了十二个篮子。","notes":[]},{"n":18,"t":"耶稣独自祷告的时候，门徒也同他在那里。耶稣问他们：“众人说我是谁？”","notes":[],"heads":["彼得认耶稣为基督"]},{"n":19,"t":"他们回答：“是施洗的约翰；有人说是以利亚；还有人说是古时的一个先知又活了。”","notes":[]},{"n":20,"t":"耶稣问他们：“你们说我是谁？”彼得回答：“是神所立的基督。”","notes":[]},{"n":21,"t":"耶稣切切吩咐他们，命令他们不可把这事告诉任何人；","notes":[],"heads":["耶稣预言受难和复活"]},{"n":22,"t":"又说：“人子必须受许多的苦，被长老、祭司长和文士弃绝，并且被杀，第三天复活。”","notes":[]},{"n":23,"t":"耶稣又对众人说：“若有人要跟从我，就当舍己，天天背起自己的十字架来跟从我。","notes":[]},{"n":24,"t":"因为凡要救自己生命的，必丧失生命；凡为我丧失生命的，他必救自己的生命。","notes":[]},{"n":25,"t":"人就是赚得全世界，却丧失了自己，或赔上自己，有什么益处呢？","notes":[]},{"n":26,"t":"凡把我和我的道当作可耻的，人子在自己的荣耀里，和天父与圣天使的荣耀里来临的时候，也要把那人当作可耻的。","notes":[]},{"n":27,"t":"我实在告诉你们，站在这里的，有人在没经历死亡以前，必定看见神的国。”","notes":[]},{"n":28,"t":"说了这些话以后约有八天，耶稣带着彼得、约翰、雅各上山去祷告。","notes":[],"heads":["耶稣登山显荣"]},{"n":29,"t":"正祷告的时候，他的面貌改变了，衣服洁白放光。","notes":[]},{"n":30,"t":"忽然有摩西和以利亚两个人同耶稣说话；","notes":[]},{"n":31,"t":"他们在荣光里显现，谈论耶稣去世的事，就是他在耶路撒冷将要完成的事。","notes":[]},{"n":32,"t":"彼得和他的同伴都打盹，但一清醒，就看见耶稣的荣光和与他一起站着的那两个人。","notes":[]},{"n":33,"t":"二人正要和耶稣分离的时候，彼得对耶稣说：“老师，我们在这里真好！我们来搭三座棚，一座为你，一座为摩西，一座为以利亚。”他却不知道自己在说些什么。","notes":[]},{"n":34,"t":"说这些话的时候，有一朵云彩来遮盖他们；他们一进入云彩就很惧怕。","notes":[]},{"n":35,"t":"有声音从云彩里出来，说：“这是我的儿子，我所拣选的。你们要听从他！”","notes":["有古卷是“我所爱的”。"]},{"n":36,"t":"声音停止后，只见耶稣独自一人。当那些日子，门徒保持沉默，不把所看见的事告诉任何人。","notes":[]},{"n":37,"t":"第二天，他们下了山，有一大群人来迎见耶稣。","notes":[],"heads":["治好被灵附身的孩子"]},{"n":38,"t":"其中有一人喊着说：“老师！求你看看我的儿子，因为他是我的独子。","notes":[]},{"n":39,"t":"他被灵拿住就突然喊叫，那灵又使他抽风，口吐白沫，并且重重地伤害他，不轻易放过他。","notes":[]},{"n":40,"t":"我求过你的门徒把那灵赶出去，他们却不能。”","notes":[]},{"n":41,"t":"耶稣回答：“唉！这又不信又悖谬的世代啊，我和你们在一起，忍耐你们，要到几时呢？把你的儿子带到这里来！”","notes":[]},{"n":42,"t":"他正来的时候，那鬼把他摔倒，使他重重地抽风。耶稣斥责那污灵，把孩子治好了，交给他父亲。","notes":[]},{"n":43,"t":"众人都诧异神的大能。众人正惊讶于耶稣所做的一切事的时候，耶稣对门徒说：","notes":["“大能”或译“威荣”。"]},{"n":44,"t":"“你们要把这些话听进去，因为人子将要被交在人手里。”","notes":[]},{"n":45,"t":"门徒却不明白这话，其中的意思对他们隐藏着，使他们不能明白，他们也不敢问这话的意思。","notes":[]},{"n":46,"t":"门徒互相议论，他们中间谁最大。","notes":[],"heads":["谁最大"]},{"n":47,"t":"耶稣看出他们心中的议论，就领一个小孩子来，叫他站在自己旁边，","notes":[]},{"n":48,"t":"对他们说：“凡为我的名接纳这小孩子的，就是接纳我；凡接纳我的，就是接纳那差我来的。你们中间最小的，他就是最大的。”","notes":[]},{"n":49,"t":"约翰回应说：“老师，我们看见一个人奉你的名赶鬼，我们就阻止他，因为他不与我们一同跟从你。”","notes":[],"heads":["不抵挡你们就是帮助你们"]},{"n":50,"t":"耶稣对他说：“不要阻止他，因为不抵挡你们的，就是帮助你们的。”","notes":[]},{"n":51,"t":"耶稣被接上升的日子将到，他决定面向耶路撒冷走去。","notes":[],"heads":["撒玛利亚人不接待主"]},{"n":52,"t":"他打发使者在他前头走；他们进了撒玛利亚的一个村庄，要为他作准备。","notes":[]},{"n":53,"t":"那里的人不接待他，因为他面向着耶路撒冷去。","notes":[]},{"n":54,"t":"他的门徒雅各和约翰看见了，就说：“主啊！你要我们吩咐火从天上降下来，烧灭他们吗？”","notes":["有古卷加“像以利亚所做的”。"]},{"n":55,"t":"耶稣转身责备两个门徒。","notes":["有古卷加“他说：‘你们的心如何，你们并不知道。56 人子来不是要灭人的性命，而是要救人的性命。’”"]},{"n":56,"t":"于是他们就往别的村庄去了。","notes":[]},{"n":57,"t":"他们在路上走的时候，有一个人对耶稣说：“你无论往哪里去，我都要跟从你。”","notes":[],"heads":["跟从耶稣应有的准备"]},{"n":58,"t":"耶稣对他说：“狐狸有洞，天空的飞鸟有窝，人子却没有枕头的地方。”","notes":[]},{"n":59,"t":"他又对另一个人说：“来跟从我！”那人说：“主啊，容许我先回去埋葬我的父亲。”","notes":["有古卷没有“主啊”。"]},{"n":60,"t":"耶稣对他说：“让死人埋葬他们的死人，你只管去传讲神的国。”","notes":[]},{"n":61,"t":"又有一人说：“主啊，我要跟从你，但容许我先去辞别我家里的人。”","notes":[]},{"n":62,"t":"耶稣对他说：“手扶着犁向后看的人，不配进神的国。”","notes":[]}]},"10":{"heading":"主差遣七十二人","verses":[{"n":1,"t":"这些事以后，主另外指定七十二个人，差遣他们两个两个地在他前面，往自己所要到的各城各地去。","notes":["有古卷是“七十个人”；17节同。"]},{"n":2,"t":"他对他们说：“要收的庄稼多，做工的人少。所以，你们要求庄稼的主差遣做工的人出去收他的庄稼。","notes":[]},{"n":3,"t":"你们去吧！看！我差你们出去，如同羔羊进入狼群。","notes":[]},{"n":4,"t":"不要带钱囊，不要带行囊，不要带鞋子；在路上也不要向人问安。","notes":[]},{"n":5,"t":"无论进哪一家，先要说：‘愿这一家平安。’","notes":[]},{"n":6,"t":"那里若有当得平安的人，你们所求的平安就必临到那家，不然，将归还你们。","notes":[]},{"n":7,"t":"你们要住在那家，吃喝他们所供给的，因为工人得工钱是应当的；不要从这家搬到那家。","notes":[]},{"n":8,"t":"无论进哪一城，人若接待你们，给你们摆上什么食物，你们就吃什么。","notes":[]},{"n":9,"t":"要医治那城里的病人，对他们说：‘神的国临近你们了。’","notes":[]},{"n":10,"t":"无论进哪一城，人若不接待你们，你们就到大街上去，说：","notes":[]},{"n":11,"t":"‘就是你们城里的尘土粘在我们的脚上，我们也当着你们擦去。但是，你们该知道神的国临近了。’","notes":[]},{"n":12,"t":"我告诉你们，在那日子，所多玛所受的，比那城还容易受呢！”","notes":[]},{"n":13,"t":"“哥拉汛哪，你有祸了！伯赛大啊，你有祸了！因为在你们中间所行的异能，若行在推罗、西顿，他们早已披麻蒙灰，坐在地上悔改了。","notes":[],"heads":["耶稣责备不悔改的城"]},{"n":14,"t":"在审判的时候，推罗和西顿所受的，比你们还容易受呢！","notes":[]},{"n":15,"t":"迦百农啊，你以为要被举到天上吗？你要被推下阴间！”","notes":[]},{"n":16,"t":"耶稣又对门徒说：“听从你们的就是听从我；弃绝你们的就是弃绝我；弃绝我的就是弃绝差遣我来的那位。”","notes":[]},{"n":17,"t":"那七十二个人欢欢喜喜地回来，说：“主啊，因你的名，就是鬼也服了我们。”","notes":[],"heads":["七十二人回来"]},{"n":18,"t":"耶稣对他们说：“我看见撒但从天上坠落，像闪电一样。","notes":[]},{"n":19,"t":"我已经给你们权柄可以践踏蛇和蝎子，又胜过仇敌一切的能力，绝没有什么能害你们。","notes":[]},{"n":20,"t":"然而，不要因灵服了你们就欢喜，而要因你们的名记录在天上欢喜。”","notes":[]},{"n":21,"t":"正当那时，耶稣被圣灵感动而欢喜快乐，说：“父啊，天地的主，我感谢你！因为你把这些事向聪明智慧的人隐藏起来，而向婴孩启示出来。父啊，是的，因为你的美意本是如此。","notes":[],"heads":["耶稣的欢乐"]},{"n":22,"t":"一切都是我父交给我的。除了父，没有人知道子是谁；除了子和子所愿意启示的人，没有人知道父是谁。”","notes":[]},{"n":23,"t":"耶稣转身私下对门徒说：“看见你们所看见的，那眼睛有福了。","notes":[]},{"n":24,"t":"我告诉你们，从前有许多先知和君王要看你们所看的，却没有看见，要听你们所听的，却没有听见。”","notes":[]},{"n":25,"t":"有一个律法师起来试探耶稣，说：“老师！我该做什么才可以承受永生？”","notes":[],"heads":["好撒玛利亚人"]},{"n":26,"t":"耶稣对他说：“律法上写的是什么？你是怎样念的呢？”","notes":[]},{"n":27,"t":"他回答说：“你要尽心、尽性、尽力、尽意爱主—你的神，又要爱邻如己。”","notes":["“邻”也可译作“人”。"]},{"n":28,"t":"耶稣对他说：“你回答得正确，你这样做就会得永生。”","notes":[]},{"n":29,"t":"那人要证明自己有理，就对耶稣说：“谁是我的邻舍呢？”","notes":[]},{"n":30,"t":"耶稣回答：“有一个人从耶路撒冷下耶利哥去，落在强盗手中。他们剥去他的衣裳，把他打个半死，丢下他走了。","notes":[]},{"n":31,"t":"偶然有一个祭司从那条路下来，看见他就从另一边过去了。","notes":[]},{"n":32,"t":"又有一个利未人来到那里，看见他，也照样从另一边过去了。","notes":[]},{"n":33,"t":"可是，有一个撒玛利亚人路过那里，看见他就动了慈心，","notes":[]},{"n":34,"t":"上前用油和酒倒在他的伤处，包裹好了，扶他骑上自己的牲口，带他到旅店里去，照应他。","notes":[]},{"n":35,"t":"第二天，他拿出两个银币来，交给店主，说：‘请你照应他，额外的费用，我回来时会还你。’","notes":[]},{"n":36,"t":"你想，这三个人哪一个是落在强盗手中那人的邻舍呢？”","notes":[]},{"n":37,"t":"他说：“是怜悯他的。”耶稣对他说：“你去，照样做吧！”","notes":[]},{"n":38,"t":"他们继续前行，耶稣进了一个村庄。有一个女人，名叫马大，接他到自己家里。","notes":[],"heads":["耶稣探望马大和马利亚"]},{"n":39,"t":"她有一个妹妹，名叫马利亚，在主的脚前坐着听他的道。","notes":[]},{"n":40,"t":"马大伺候的事多，心里忙乱，进前来，说：“主啊，我的妹妹留下我一个人伺候，你不在意吗？请吩咐她来帮助我。”","notes":[]},{"n":41,"t":"主回答说：“马大，马大，你为许多的事操心烦恼，","notes":[]},{"n":42,"t":"但是不可少的只有一件。马利亚已经选择了那上好的福分，是没有人能从她夺去的。”","notes":["“只有一件”：有古卷是“只有几件，或是一件”。"]}]},"11":{"heading":"论祷告","verses":[{"n":1,"t":"耶稣在一个地方祷告。祷告完了，有个门徒对他说：“主啊，求你教导我们祷告，像约翰教导他的门徒一样。”","notes":[]},{"n":2,"t":"耶稣对他们说：“你们祷告的时候，要说：‘父啊，愿人都尊你的名为圣；愿你的国降临；","notes":["有古卷是“我们在天上的父”。","有古卷加“愿你的旨意行在地上，如同行在天上。”"]},{"n":3,"t":"我们日用的饮食，天天赐给我们。","notes":[]},{"n":4,"t":"赦免我们的罪，因为我们也赦免凡亏欠我们的人。不叫我们陷入试探。’”","notes":["有古卷加“救我们脱离那恶者。”"]},{"n":5,"t":"耶稣又对他们说：“你们中间谁有一个朋友半夜到他那里去，对他说：‘朋友！请借给我三个饼；","notes":[]},{"n":6,"t":"因为我有一个朋友旅途中来到我这里，我没有东西招待他。’","notes":[]},{"n":7,"t":"那人在里面回答：‘不要打扰我，门已经关了，孩子们也同我在床上了，我不能起来给你。’","notes":[]},{"n":8,"t":"我告诉你们，虽不因他是朋友起来给他，也会因他不顾面子地直求，起来照他所需要的给他。","notes":[]},{"n":9,"t":"我又告诉你们，祈求，就给你们；寻找，就找到；叩门，就给你们开门。","notes":[]},{"n":10,"t":"因为凡祈求的，就得着；寻找的，就找到；叩门的，就给他开门。","notes":[]},{"n":11,"t":"你们中间作父亲的，谁有儿子求鱼，反拿蛇当鱼给他呢？","notes":["有古卷加“求饼，反给他石头呢？”"]},{"n":12,"t":"求鸡蛋，反给他蝎子呢？","notes":[]},{"n":13,"t":"你们虽然不好，尚且知道拿好东西给儿女，何况天父，他岂不更要把圣灵赐给求他的人吗？”","notes":["有古卷加“你们的”。"]},{"n":14,"t":"耶稣赶出一个使人成为哑巴的鬼，鬼出去了，哑巴就说出话来；众人都很惊讶。","notes":["有古卷是“一个哑巴鬼”。"],"heads":["诬蔑耶稣为别西卜"]},{"n":15,"t":"其中却有人说：“他是靠着鬼王别西卜赶鬼。”","notes":[]},{"n":16,"t":"又有人试探耶稣，要他显个来自天上的神迹。","notes":[]},{"n":17,"t":"他知道他们的意念，就对他们说：“一国自相纷争，必定荒芜；一家自相纷争，就必败落。","notes":[]},{"n":18,"t":"撒但若自相纷争，他的国怎能立得住呢？因为你们说我是靠着别西卜赶鬼。","notes":[]},{"n":19,"t":"我若靠着别西卜赶鬼，你们的子弟赶鬼又靠着谁呢？这样，他们要作你们的判官。","notes":[]},{"n":20,"t":"我若靠着神的能力赶鬼，那么，神的国就已临到你们了。","notes":[]},{"n":21,"t":"壮士全副武装，看守自己的住宅，他所有的都很安全；","notes":[]},{"n":22,"t":"但有一个比他更强的来攻击他，并且战胜了他，就夺去他所倚靠的盔甲兵器，又分了他的掠物。","notes":[]},{"n":23,"t":"不跟我一起的，就是反对我；不与我一起收聚的，就是在拆散。”","notes":[]},{"n":24,"t":"“污灵离了人身，走遍无水之地寻找安歇之处，却找不到。就说：‘我要回到我原来的屋里去。’","notes":[],"heads":["污灵回来"]},{"n":25,"t":"他到了，看见里面打扫干净，修饰好了，","notes":[]},{"n":26,"t":"就去另带了七个比自己更恶的灵来，都进去住在那里。那人后来的景况比先前更坏了。”","notes":[]},{"n":27,"t":"耶稣正说这些话的时候，众人中间有一个女人高声对他说：“怀你胎乳养你的有福了！”","notes":[],"heads":["真正的福"]},{"n":28,"t":"耶稣却说：“更有福的是听神的道而遵守的人！”","notes":[]},{"n":29,"t":"当众人越来越拥挤的时候，耶稣说：“这世代是一个邪恶的世代。他们求看神迹，除了约拿的神迹以外，再没有神迹给他们看了。","notes":[],"heads":["求神迹"]},{"n":30,"t":"约拿怎样为尼尼微人成了神迹，人子也要照样为这世代的人成为神迹。","notes":[]},{"n":31,"t":"在审判的时候，南方的女王要起来定这世代的人的罪，因为她从地极而来，要听所罗门智慧的话。看哪，比所罗门更大的在这里！","notes":[]},{"n":32,"t":"在审判的时候，尼尼微人要起来定这世代的罪，因为尼尼微人听了约拿所传的就悔改了。看哪，比约拿更大的在这里！”","notes":[]},{"n":33,"t":"“没有人点灯放在地窖里，或是斗底下，总是放在灯台上，让进来的人看见亮光。","notes":["有古卷没有“或是斗底下”。"],"heads":["眼睛是身体的灯"]},{"n":34,"t":"你的眼睛就是身体的灯。当你的眼睛明亮，全身就光明，当眼睛昏花，全身就黑暗。","notes":[]},{"n":35,"t":"所以，你要注意，免得你里面的光暗了。","notes":[]},{"n":36,"t":"若是你全身光明，毫无黑暗，就必全然光明，如同灯的明光照亮你。”","notes":[]},{"n":37,"t":"耶稣正说话的时候，有一个法利赛人请他吃饭，耶稣就进去坐席。","notes":[],"heads":["谴责法利赛人和文士"]},{"n":38,"t":"这法利赛人看见耶稣饭前不先洗手就很诧异。","notes":[]},{"n":39,"t":"主对他说：“如今你们法利赛人洗净杯盘的外面，你们里面却满了贪婪和邪恶。","notes":[]},{"n":40,"t":"无知的人哪！造外面的，不也造了里面吗？","notes":[]},{"n":41,"t":"只要把杯盘里面的施舍给人，对你们来说一切就都洁净了。","notes":[]},{"n":42,"t":"“但是你们法利赛人有祸了！因为你们将薄荷、芸香，和各样蔬菜献上十分之一，疏忽了公义和爱神的事；这原是你们该做的—至于其他也不可忽略。","notes":[]},{"n":43,"t":"你们法利赛人有祸了！因为你们喜爱会堂里的高位，又喜欢人们在街市上向你们问安。","notes":[]},{"n":44,"t":"你们有祸了！因为你们如同不显露的坟墓，走在上面的人并不知道。”","notes":[]},{"n":45,"t":"律法师中有一个回答耶稣，说：“老师，你这样说也把我们侮辱了。”","notes":[]},{"n":46,"t":"耶稣说：“你们律法师也有祸了！因为你们把难挑的担子放在别人身上，自己却不肯动一个指头去减轻这些担子。","notes":[]},{"n":47,"t":"你们有祸了！因为你们建造先知的坟墓，那些先知正是你们的祖宗所杀的。","notes":[]},{"n":48,"t":"可见你们祖宗所做的事，你们是证人，你们也赞同，因为他们杀了先知，你们建造先知的坟墓。","notes":[]},{"n":49,"t":"所以，神的智慧也曾说：‘我要差遣先知和使徒到他们那里去，有的他们要残杀，有的他们要迫害’，","notes":[]},{"n":50,"t":"为使创世以来所流众先知的血的罪都归在这世代的人身上，","notes":[]},{"n":51,"t":"就是从亚伯的血起，直到被杀在祭坛和圣所中间的撒迦利亚的血为止。是的，我告诉你们，这都要向这世代的人追讨。","notes":[]},{"n":52,"t":"你们律法师有祸了！因为你们把知识的钥匙夺了去，自己不进去，要进去的人，你们也阻挡他们。”","notes":[]},{"n":53,"t":"耶稣从那里出来，文士和法利赛人就开始极力地催逼他，盘问他许多事，","notes":[]},{"n":54,"t":"伺机要抓他的话柄。","notes":[]}]},"12":{"heading":"警戒假冒为善","verses":[{"n":1,"t":"这时，有几万人聚集，甚至彼此践踏。耶稣就先对门徒说：“你们要防备法利赛人的酵，就是假冒为善。","notes":[]},{"n":2,"t":"掩盖的事没有不显露出来的，隐藏的事也没有不被人知道的。","notes":[]},{"n":3,"t":"因此，你们在暗中所说的，将要在明处被人听见；在密室附耳所说的，将要在屋顶上被人宣扬。”","notes":[]},{"n":4,"t":"“我的朋友，我对你们说，那最多只能杀人身体而不能再做什么的，不要怕他们。","notes":[],"heads":["不要惧怕"]},{"n":5,"t":"我提醒你们该怕的是谁：该怕那杀了以后又有权柄把人扔在地狱里的。是的，我告诉你们，正要怕他。","notes":[]},{"n":6,"t":"五只麻雀不是卖二铜钱吗？但在神面前，一只也不被忘记；","notes":["“铜钱”：参“度量衡表”。"]},{"n":7,"t":"就是你们的头发也都数过了。不要惧怕，你们比许多的麻雀还贵重！”","notes":[]},{"n":8,"t":"“我又告诉你们，凡在人面前认我的，人子在神的使者面前也必认他；","notes":[],"heads":["在人的面前认基督"]},{"n":9,"t":"在人面前不认我的，人子在神的使者面前也必不认他。","notes":[]},{"n":10,"t":"凡说话干犯人子的，还可得赦免；但是亵渎圣灵的，总不得赦免。","notes":[]},{"n":11,"t":"有人带你们到会堂、官长和掌权的人面前，不要担心怎么答辩，说什么话；","notes":[]},{"n":12,"t":"因为就在那时候，圣灵要指教你们该说的话。”","notes":[]},{"n":13,"t":"人群中有一个人对耶稣说：“老师！请你吩咐我的兄弟和我分家产。”","notes":[],"heads":["无知的财主"]},{"n":14,"t":"耶稣对他说：“你这个人！谁立我作你们的判官，或给你们分家产的呢？”","notes":[]},{"n":15,"t":"于是他对他们说：“你们要谨慎自守，躲避一切的贪心，因为人的生命不在于家道丰富。”","notes":[]},{"n":16,"t":"然后他用比喻对他们说：“有一个财主，田地出产丰富。","notes":[]},{"n":17,"t":"他自己心里想：‘我的出产没有地方储藏，怎么办呢？’","notes":[]},{"n":18,"t":"就说：‘我要这么办：要把我的仓库拆了，另盖更大的，在那里好储藏我一切的粮食和财物，","notes":[]},{"n":19,"t":"然后要对我自己说：你这个人哪，你有许多财物积存，可供多年享用，只管安安逸逸吃喝快乐吧！’","notes":[]},{"n":20,"t":"神却对他说：‘无知的人哪！今夜就要你的性命，你所预备的要归谁呢？’","notes":[]},{"n":21,"t":"凡为自己积财，在神面前却不富足的，也是这样。”","notes":[]},{"n":22,"t":"耶稣又对门徒说：“所以，我告诉你们，不要为生命忧虑吃什么，为身体忧虑穿什么。","notes":[],"heads":["不要忧虑"]},{"n":23,"t":"因为生命胜于饮食，身体胜于衣裳。","notes":[]},{"n":24,"t":"你们想一想乌鸦：它们既不种也不收，既没有仓又没有库，神尚且养活它们。你们比飞鸟要贵重得多呢！","notes":[]},{"n":25,"t":"你们哪一个能藉着忧虑使寿数多加一刻呢？","notes":["“使寿数多加一刻呢？”或译“使身量多加一肘呢？”"]},{"n":26,"t":"这最小的事你们尚且不能做，何必忧虑其余的事呢？","notes":[]},{"n":27,"t":"你们想一想百合花是怎么长起来的：它也不劳动，也不纺线。然而我告诉你们，就是所罗门极荣华的时候，他所穿戴的还不如这些花的一朵呢！","notes":[]},{"n":28,"t":"你们这小信的人哪！野地里的草今天还在，明天就丢在炉里，神还给它这样的妆饰，何况你们呢？","notes":[]},{"n":29,"t":"你们不要求吃什么，喝什么，也不要挂虑。","notes":[]},{"n":30,"t":"这都是世上的外邦人所求的；你们需要这些东西，你们的父都知道。","notes":[]},{"n":31,"t":"你们只要求他的国，这些东西就必加给你们了。","notes":[]},{"n":32,"t":"你们这小群，不要惧怕，因为你们的父乐意把国赐给你们。","notes":[]},{"n":33,"t":"你们要变卖财产周济人，为自己预备永不坏的钱囊和用不尽的财宝在天上，就是贼不能近，虫不能蛀的地方。","notes":[]},{"n":34,"t":"因为你们的财宝在哪里，你们的心也在哪里。”","notes":[]},{"n":35,"t":"“你们要束紧腰带，灯也要点着，","notes":[],"heads":["警醒的仆人"]},{"n":36,"t":"好像仆人等候自己的主人从婚宴上回来。他来叩门，就立刻给他开门。","notes":[]},{"n":37,"t":"主人来了，看见仆人警醒，那些仆人就有福了。我实在告诉你们，主人会叫他们坐席，自己束上腰带，前来伺候他们。","notes":[]},{"n":38,"t":"他或是半夜来，或是天亮之前来，看见仆人这样，那些仆人就有福了。","notes":[]},{"n":39,"t":"你们要知道，一家的主人若知道贼什么时候来，就不容贼挖穿房屋。","notes":["有古卷加“必警醒”。"]},{"n":40,"t":"你们也要预备，因为在你们想不到的时候，人子就来了。”","notes":[]},{"n":41,"t":"彼得说：“主啊，这比喻是对我们说的呢？还是也对众人呢？”","notes":[]},{"n":42,"t":"主说：“那么，谁是那忠心又精明的管家，主人要派他管理自己的家仆，按时定量分粮给他们的呢？","notes":[]},{"n":43,"t":"主人来到，看见仆人这样做，那仆人就有福了。","notes":[]},{"n":44,"t":"我实在告诉你们，主人要派他管理所有的财产。","notes":[]},{"n":45,"t":"如果那仆人心里说‘我的主人会来得迟’，就动手打僮仆和使女，并且吃喝醉酒，","notes":[]},{"n":46,"t":"在想不到的日子，不知道的时候，那仆人的主人要来，重重地惩罚他，定他和不忠心的人同罪。","notes":["“重重地惩罚他”或译“把他腰斩了”。"]},{"n":47,"t":"仆人知道主人的意思，却没预备，又未顺他的意思做，那仆人要多受责打；","notes":[]},{"n":48,"t":"至于那不知道而做了当受责打的事的，要少受责打。多给谁，就向谁多取；多托谁，就向谁多要。”","notes":[]},{"n":49,"t":"“我来是要把火丢在地上，假如已经烧起来，不也是我所希望的吗？","notes":[],"heads":["分裂的原因"]},{"n":50,"t":"我有当受的洗还没有受，在这事完成之前，我是多么地焦急！","notes":[]},{"n":51,"t":"你们以为我来是要使地上太平吗？不！我告诉你们，是使人纷争。","notes":[]},{"n":52,"t":"从今以后，一家五个人将要纷争，三个和两个相争，两个和三个相争：","notes":[]},{"n":53,"t":"父亲和儿子相争，儿子和父亲相争；母亲和女儿相争，女儿和母亲相争；婆婆和媳妇相争，媳妇和婆婆相争。”","notes":[]},{"n":54,"t":"耶稣又对众人说：“你们看见西边起了云彩，就说：‘要下大雨了’，果然就有；","notes":[],"heads":["分辨时候"]},{"n":55,"t":"起了南风，你们就说：‘要燥热了’，也就有了。","notes":[]},{"n":56,"t":"假冒为善的人哪，你们知道分辨天地的气象，怎么不知道分辨这是什么时代呢？”","notes":[]},{"n":57,"t":"“你们又为何不自己判断什么是合理的呢？","notes":[],"heads":["与冤家和解"]},{"n":58,"t":"你同告你的冤家去见官，还在路上，要尽力跟他和解，免得他拉你到法官面前，法官把你交给法警，法警把你下在监里。","notes":[]},{"n":59,"t":"我告诉你，就是最后一小文钱还没有还清，你也绝不能从那里出来。”","notes":["“小文钱”：参“度量衡表”。"]}]},"13":{"heading":"不悔改必灭亡","verses":[{"n":1,"t":"正当那时，有些在场的人把彼拉多使加利利人的血搀杂在他们祭物中的事，告诉耶稣。","notes":[]},{"n":2,"t":"耶稣对他们说：“你们以为这些加利利人比其他的加利利人更有罪，所以受这害吗？","notes":[]},{"n":3,"t":"我告诉你们，不是的！你们若不悔改，都同样要灭亡！","notes":[]},{"n":4,"t":"从前西罗亚楼倒塌，压死了十八个人，你们以为那些人比一切住在耶路撒冷的人更有罪吗？","notes":[]},{"n":5,"t":"我告诉你们，不是的！你们若不悔改，都照样要灭亡！”","notes":[]},{"n":6,"t":"于是，耶稣用比喻说：“有一个人在葡萄园里栽了一棵无花果树。他前来在树上找果子，却找不到，","notes":[],"heads":["不结果子的无花果树"]},{"n":7,"t":"就对园丁说：‘看哪，我这三年来到这棵无花果树前找果子，竟找不到。把它砍了吧，何必白占土地呢？’","notes":[]},{"n":8,"t":"园丁回答：‘主啊，今年且留着，等我在树周围掘开土，加上肥料，","notes":[]},{"n":9,"t":"以后若结果子便罢，不然再把它砍了。’”","notes":[]},{"n":10,"t":"安息日，耶稣在一个会堂里教导人。","notes":[],"heads":["在安息日治好驼背的女人"]},{"n":11,"t":"有一个女人被灵附身，病了十八年，腰弯得一点都直不起来。","notes":[]},{"n":12,"t":"耶稣看见，就叫她过来，对她说：“妇人，你的病好了！”","notes":[]},{"n":13,"t":"于是用双手按着她，她立刻直起腰来，就归荣耀给神。","notes":[]},{"n":14,"t":"会堂的主管因为耶稣在安息日治病，就很生气，对众人说：“有六天应当做工，那六天之内可以来求医，在安息日却不可。”","notes":[]},{"n":15,"t":"主回答他：“假冒为善的人哪，难道你们各人在安息日不解开槽上的牛和驴，牵去喝水吗？","notes":[]},{"n":16,"t":"何况她本是亚伯拉罕的后裔，被撒但捆绑了十八年，不该在安息日这天解开她的绑吗？”","notes":[]},{"n":17,"t":"耶稣说这些话，他的敌人都惭愧了；所有的人因他所做一切荣耀的事都很欢喜。","notes":[]},{"n":18,"t":"耶稣说：“神的国像什么？我拿什么来比拟呢？","notes":[],"heads":["芥菜种和面酵的比喻"]},{"n":19,"t":"它好比一粒芥菜种，有人拿去种在园子里，长大成树，天上的飞鸟在它的枝上筑巢。”","notes":[]},{"n":20,"t":"他又说：“我拿什么来比拟神的国呢？","notes":[]},{"n":21,"t":"它好比面酵，有妇人拿来放进三斗面里，直到全团都发起来。”","notes":[]},{"n":22,"t":"耶稣往耶路撒冷去，在所经过的各城各乡教导人。","notes":[],"heads":["要进窄门"]},{"n":23,"t":"有一个人问他：“主啊，得救的人很少吧？” 耶稣对众人说：","notes":[]},{"n":24,"t":"“你们要努力进窄门。我告诉你们，将来有许多人想要进去，却不能。","notes":[]},{"n":25,"t":"等到一家之主起来关了门，你们才站在外面敲门，说：‘主啊，给我们开门！’他要回答你们说：‘我不认识你们，不知道你们是哪里来的。’","notes":[]},{"n":26,"t":"那时，你们要说：‘我们在你面前吃过喝过，你也在我们的街上教导过人。’","notes":[]},{"n":27,"t":"他要对你们说：‘我告诉你们，我不知道你们是哪里来的。你们这一切不义的人，给我走开！’","notes":["有古卷加“实在”。"]},{"n":28,"t":"你们要看见亚伯拉罕、以撒、雅各和众先知都在神的国里，你们却被赶到外面，在那里要哀哭切齿了。","notes":[]},{"n":29,"t":"从东从西，从南从北，将有人来，在神的国里坐席。","notes":[]},{"n":30,"t":"看吧，在后的，将要在前；在前的，将要在后。”","notes":[]},{"n":31,"t":"就在那时，有几个法利赛人来对耶稣说：“离开这里到别处去吧，因为希律想要杀你。”","notes":[],"heads":["为耶路撒冷哀哭"]},{"n":32,"t":"耶稣对他们说：“你们去告诉那个狐狸：‘你看吧，今天明天我赶鬼治病，第三天我的事就成了。’","notes":[]},{"n":33,"t":"虽然这样，今天明天后天我必须向前走，因为先知是不可能在耶路撒冷之外被害的。","notes":[]},{"n":34,"t":"耶路撒冷啊，耶路撒冷啊，你常杀害先知，又用石头打死那奉差遣到你这里来的人。我多少次想聚集你的儿女，好像母鸡把小鸡聚集在翅膀底下，可是你们不愿意。","notes":[]},{"n":35,"t":"看吧，你们的家要被废弃。我告诉你们，你们绝不会再见到我，直到你们说：‘奉主名来的是应当称颂的！’”","notes":[]}]},"14":{"heading":"在安息日治好水肿病人","verses":[{"n":1,"t":"安息日，耶稣到一个法利赛人的领袖家里去吃饭，他们就窥探他。","notes":[]},{"n":2,"t":"这时在他面前有一个患水肿病的人。","notes":[]},{"n":3,"t":"耶稣回答律法师和法利赛人，说：“安息日治病合不合法？”","notes":[]},{"n":4,"t":"他们却不说话。耶稣扶着那人，治好了他，叫他走了。","notes":[]},{"n":5,"t":"耶稣对他们说：“你们中间谁有儿子或有牛在安息日掉在井里，不立刻拉他上来呢？”","notes":["“儿子”：有古卷是“驴”。"]},{"n":6,"t":"他们对这些事不能反驳。","notes":[]},{"n":7,"t":"耶稣见所请的客人选择首位，就用比喻对他们说：","notes":[],"heads":["对客人和主人的教导"]},{"n":8,"t":"“你被人请去赴婚宴，不要坐在首位上，恐怕主人请了比你尊贵的客人，","notes":[]},{"n":9,"t":"请了你和他的那人前来，对你说：‘请让座给这一位吧。’你就羞羞惭惭地退到末位去了。","notes":[]},{"n":10,"t":"你被请的时候，去坐在末位上，好让主人来对你说：‘朋友，请上座。’那时，你在同席的人面前就有光彩了。","notes":[]},{"n":11,"t":"因为凡自高的，必降为卑；自甘卑微的，必升为高。”","notes":[]},{"n":12,"t":"耶稣又对请他的人说：“你准备午饭或晚餐，不要请你的朋友、弟兄、亲属和富足的邻舍，免得他们回请你，你就得了报答。","notes":[]},{"n":13,"t":"你摆设宴席，倒要请那贫穷的、残疾的、瘸腿的、失明的，","notes":[]},{"n":14,"t":"你就有福了！因为他们没有什么可报答你。到义人复活的时候，你要得到报答。”","notes":[]},{"n":15,"t":"同席的有一人听见这些话，就对耶稣说：“在神国里吃饭的有福了！”","notes":[],"heads":["大宴席的比喻"]},{"n":16,"t":"耶稣对他说：“有人摆设大宴席，请了许多客人。","notes":[]},{"n":17,"t":"到了坐席的时候，他打发仆人去对所请的人说：‘请来吧！样样都已齐备了。’","notes":[]},{"n":18,"t":"众人异口同声地推辞。头一个对他说：‘我买了一块地，必须去看看。请你准我辞了。’","notes":[]},{"n":19,"t":"另一个说：‘我买了五对牛，要去试一试。请你准我辞了。’","notes":[]},{"n":20,"t":"又有一个说：‘我才娶了妻子，所以不能去。’","notes":[]},{"n":21,"t":"那仆人回来，把这些事都告诉了主人。这家的主人就发怒，对仆人说：‘快出去，到城里大街小巷，领那贫穷的、残疾的、失明的、瘸腿的来。’","notes":[]},{"n":22,"t":"仆人说：‘主啊，你所吩咐的已经办了，还有空位。’","notes":[]},{"n":23,"t":"主人对仆人说：‘你出去，到大街小巷强拉人进来，坐满我的屋子。","notes":[]},{"n":24,"t":"我告诉你们，先前所请的人没有一个可以尝到我的宴席。’”","notes":[]},{"n":25,"t":"有一大群人和耶稣同行。他转过来对他们说：","notes":[],"heads":["作门徒的代价"]},{"n":26,"t":"“无论什么人到我这里来，若不爱我胜过爱自己的父母、妻子、儿女、兄弟、姊妹，甚至自己的性命，就不能作我的门徒。","notes":["“爱我胜过爱”：原文直译“恨”。"]},{"n":27,"t":"凡不背着自己的十字架来跟从我的，也不能作我的门徒。","notes":[]},{"n":28,"t":"你们哪一个要盖一座楼，不先坐下来计算费用，看能不能盖成？","notes":[]},{"n":29,"t":"免得安了地基，不能盖成，看见的人都笑话他，说：","notes":[]},{"n":30,"t":"‘这个人开了工，却不能完工。’","notes":[]},{"n":31,"t":"或是一个王出去和别的王打仗，岂不先坐下来酌量，他能不能用一万兵去抵抗那领二万兵来攻打他的吗？","notes":[]},{"n":32,"t":"若是不能，他就趁敌人还远的时候，派使者去谈和平的条件。","notes":[]},{"n":33,"t":"这样，你们无论什么人，若不撇下一切所有的，就不能作我的门徒。”","notes":[]},{"n":34,"t":"“盐本是好的；盐若失了味，怎能叫它再咸呢？","notes":[],"heads":["失味的盐"]},{"n":35,"t":"或用在田里，或堆在粪里，都不合适，只好丢在外面。有耳可听的，就应当听！”","notes":[]}]},"15":{"heading":"迷羊的比喻","verses":[{"n":1,"t":"许多税吏和罪人都挨近耶稣，要听他讲道。","notes":[]},{"n":2,"t":"法利赛人和文士私下议论说：“这个人接纳罪人，又同他们吃饭。”","notes":[]},{"n":3,"t":"耶稣就用比喻对他们说：","notes":[]},{"n":4,"t":"“你们中间谁有一百只羊，失去其中的一只，不把这九十九只留在旷野，去找那失去的羊，直到找着呢？","notes":[]},{"n":5,"t":"找到了，他就欢欢喜喜地把羊扛在肩上。","notes":[]},{"n":6,"t":"他回到家里，请朋友和邻舍来，对他们说：‘你们和我一同欢喜吧，我失去的羊已经找到了！’","notes":[]},{"n":7,"t":"我告诉你们，一个罪人悔改，在天上也要这样为他欢喜，比为九十九个不用悔改的义人欢喜还大呢！”","notes":[]},{"n":8,"t":"“同样，哪一个妇人有十块钱，若失落一块，不点上灯，打扫屋子，细细地找，直到找着呢？","notes":["“钱”：参“度量衡表”；下同。"],"heads":["失钱的比喻"]},{"n":9,"t":"找到了，她就请朋友和邻舍来，对她们说：‘你们和我一同欢喜吧，我失落的那块钱已经找到了！’","notes":[]},{"n":10,"t":"我告诉你们，一个罪人悔改，神的使者也是这样为他欢喜。”","notes":[]},{"n":11,"t":"耶稣又说：“一个人有两个儿子。","notes":[],"heads":["浪子的比喻"]},{"n":12,"t":"小儿子对父亲说：‘父亲，请你把我应得的家业分给我。’他父亲就把财产分给他们。","notes":[]},{"n":13,"t":"过了不多几天，小儿子把他一切所有的都收拾起来，往远方去了。在那里，他任意放荡，浪费钱财。","notes":[]},{"n":14,"t":"他耗尽了一切所有的，又恰逢那地方有大饥荒，就穷困起来。","notes":[]},{"n":15,"t":"于是他去投靠当地的一个居民，那人打发他到田里去放猪。","notes":[]},{"n":16,"t":"他恨不得拿猪所吃的豆荚充饥，也没有人给他什么吃的。","notes":[]},{"n":17,"t":"他醒悟过来，就说：‘我父亲有多少雇工，粮食有余，我倒在这里饿死吗？","notes":[]},{"n":18,"t":"我要起来，到我父亲那里去，对他说：父亲！我得罪了天，又得罪了你，","notes":[]},{"n":19,"t":"从今以后，我不配称为你的儿子，把我当作一个雇工吧。’","notes":[]},{"n":20,"t":"于是他起来，往他父亲那里去。相离还远，他父亲看见，就动了慈心，跑去拥抱着他，连连亲他。","notes":[]},{"n":21,"t":"儿子对他说：‘父亲！我得罪了天，又得罪了你，从今以后，我不配称为你的儿子。’","notes":[]},{"n":22,"t":"父亲却吩咐仆人：‘快把那上好的袍子拿出来给他穿，把戒指戴在他指头上，把鞋穿在他脚上，","notes":[]},{"n":23,"t":"把那肥牛犊牵来宰了，我们来吃喝庆祝；","notes":[]},{"n":24,"t":"因为我这个儿子是死而复活，失而复得的。’他们就开始庆祝。","notes":[]},{"n":25,"t":"“那时，大儿子正在田里。他回来，离家不远时，听见奏乐跳舞的声音，","notes":[]},{"n":26,"t":"就叫一个僮仆来，问是什么事。","notes":[]},{"n":27,"t":"僮仆对他说：‘你弟弟回来了，你父亲因为他无灾无病地回来，把肥牛犊宰了。’","notes":[]},{"n":28,"t":"大儿子就生气，不肯进去，他父亲出来劝他。","notes":[]},{"n":29,"t":"他对父亲说：‘你看，我服侍你这么多年，从来没有违背过你的命令，而你从来没有给我一只小山羊，叫我和朋友们一同快乐。","notes":[]},{"n":30,"t":"但你这个儿子和娼妓吃光了你的财产，他一回来，你倒为他宰了肥牛犊。’","notes":[]},{"n":31,"t":"父亲对他说：‘儿啊！你常和我同在，我所有的一切都是你的；","notes":[]},{"n":32,"t":"可是你这个弟弟是死而复活，失而复得的，所以我们理当欢喜庆祝。’”","notes":[]}]},"16":{"heading":"不义的管家","verses":[{"n":1,"t":"耶稣又对门徒说：“某财主有一个管家，有人向主人告管家浪费他的财物。","notes":[]},{"n":2,"t":"主人叫他来，对他说：‘我听到了，你做的是什么事？把你所经管的交代清楚，你不能再作我的管家了。’","notes":[]},{"n":3,"t":"那管家心里说：‘主人辞我，不用我再作管家，我将来做什么呢？锄地嘛，没有力气；讨饭嘛，怕羞。","notes":[]},{"n":4,"t":"我知道怎么做，好叫人们在我不作管家之后，接我到他们家里去。’","notes":[]},{"n":5,"t":"于是他把欠他主人债的，一个一个地叫了来，问头一个说：‘你欠我主人多少？’","notes":[]},{"n":6,"t":"他说：‘一百篓油。’管家对他说：‘拿你的账，快坐下，写五十。’","notes":["“篓”：参“度量衡表”。"]},{"n":7,"t":"他问另一个说：‘你欠多少？’他说：‘一百石麦子。’管家对他说：‘拿你的账，写八十。’","notes":[]},{"n":8,"t":"主人就夸奖这不义的管家做事精明，因为今世之子应付自己的世代比光明之子更加精明。","notes":[]},{"n":9,"t":"我又告诉你们，要藉着那不义的钱财结交朋友，到了钱财无用的时候，他们可以接你们到永远的住处去。","notes":["“住处”：原文直译“帐幕”。"]},{"n":10,"t":"人在最小的事上忠心，在大事上也忠心；在最小的事上不义，在大事上也不义。","notes":[]},{"n":11,"t":"若是你们在不义的钱财上不忠心，谁还把那真实的钱财托付你们呢？","notes":[]},{"n":12,"t":"如果你们在别人的东西上不忠心，谁还把你们自己的东西给你们呢？","notes":[]},{"n":13,"t":"一个仆人不能服侍两个主；他不是恨这个爱那个，就是重这个轻那个。你们不能又服侍神，又服侍玛门。”","notes":["“玛门”意思是“钱财”。"]},{"n":14,"t":"法利赛人是贪爱钱财的；他们听见这一切话，就嘲笑耶稣。","notes":[],"heads":["律法和神的国"]},{"n":15,"t":"耶稣对他们说：“你们是在人面前自称为义的，你们的心，神却知道；因为人以为尊贵的，是神看为可憎恶的。","notes":[]},{"n":16,"t":"律法和先知到约翰为止，从此神国的福音传开了，人人努力要进去。","notes":[]},{"n":17,"t":"天地废去比律法的一点一画落空还要容易。","notes":[]},{"n":18,"t":"凡休妻另娶的，就是犯奸淫；娶被丈夫休了的妇人的，也是犯奸淫。”","notes":[]},{"n":19,"t":"“有一个财主穿着紫色袍和细麻布衣服，天天奢华宴乐。","notes":[],"heads":["财主和拉撒路"]},{"n":20,"t":"又有一个讨饭的，名叫拉撒路，浑身长疮，被人放在财主门口，","notes":[]},{"n":21,"t":"想得财主桌子上掉下来的碎食充饥，甚至还有狗来舔他的疮。","notes":[]},{"n":22,"t":"后来那讨饭的死了，被天使带去放在亚伯拉罕的怀里。财主也死了，并且埋葬了。","notes":[]},{"n":23,"t":"他在阴间受苦，举目远远地望见亚伯拉罕，又望见拉撒路在他怀里，","notes":[]},{"n":24,"t":"他就喊着说：‘我祖亚伯拉罕哪，可怜我吧！请打发拉撒路来，用指头尖蘸点水，凉凉我的舌头，因为我在这火焰里，极其痛苦。’","notes":[]},{"n":25,"t":"亚伯拉罕说：‘孩子啊，你该回想你生前享过福，拉撒路也同样受过苦，如今他在这里得安慰，你却受痛苦。","notes":[]},{"n":26,"t":"除此之外，在你们和我们之间，有深渊隔开，以致人要从这边过到你们那边是不可能的；要从那边过到这边也是不可能的。’","notes":[]},{"n":27,"t":"财主说：‘我祖啊，既然这样，求你打发拉撒路到我父家去，","notes":[]},{"n":28,"t":"因为我还有五个兄弟，他可以警告他们，免得他们也来到这痛苦的地方。’","notes":[]},{"n":29,"t":"亚伯拉罕说：‘他们有摩西和先知的话可以听从。’","notes":[]},{"n":30,"t":"他说：‘不！我祖亚伯拉罕哪，假如有一个人从死人中到他们那里去，他们一定会悔改。’","notes":[]},{"n":31,"t":"亚伯拉罕对他说：‘如果他们不听从摩西和先知的话，就是有人从死人中复活，他们也不会信服的。’”","notes":[]}]},"17":{"heading":"饶恕得罪你的人","verses":[{"n":1,"t":"耶稣又对门徒说：“绊倒人的事是免不了的，但那绊倒人的有祸了！","notes":[]},{"n":2,"t":"人若把这些小子中的一个绊倒的，还不如把磨石拴在他的颈项上，丢在海里。","notes":[]},{"n":3,"t":"你们要谨慎！若是你的弟兄犯罪，就劝戒他；他若懊悔，就饶恕他。","notes":[]},{"n":4,"t":"如果他一天七次得罪你，又七次回头，说：‘我懊悔了’，你总要饶恕他。”","notes":[]},{"n":5,"t":"使徒对主说：“请加增我们的信心。”","notes":[],"heads":["信心的能力"]},{"n":6,"t":"主说：“你们若有信心像一粒芥菜种，就是对这棵桑树说：‘你要连根拔起，栽在海里’，它也会听从你们。”","notes":[]},{"n":7,"t":"“你们当中谁有仆人耕地或是放羊，从田里回来，就对他说‘你快来坐下吃饭’呢？","notes":[],"heads":["仆人的本分"]},{"n":8,"t":"他岂不对仆人说‘你给我预备晚饭，束上带子伺候我，等我吃喝完了，你才可以吃喝’吗？","notes":[]},{"n":9,"t":"仆人照所吩咐的去做，主人还谢谢他吗？","notes":[]},{"n":10,"t":"这样，你们做完了一切所吩咐的，要说：‘我们是无用的仆人，所做的本是我们该做的。’”","notes":[]},{"n":11,"t":"耶稣往耶路撒冷去，经过撒玛利亚和加利利中间的地区。","notes":[],"heads":["治好十个麻风病人"]},{"n":12,"t":"他进入一个村子，有十个麻风病人迎面而来，远远地站着，","notes":[]},{"n":13,"t":"高声说：“耶稣，老师啊，可怜我们吧！”","notes":[]},{"n":14,"t":"耶稣看见，就对他们说：“你们去，把身体给祭司检查。”他们正去的时候就洁净了。","notes":[]},{"n":15,"t":"其中有一个见自己已经好了，就回来大声归荣耀给神，","notes":[]},{"n":16,"t":"又俯伏在耶稣脚前感谢他。这人是撒玛利亚人。","notes":[]},{"n":17,"t":"耶稣回答说：“洁净了的不是十个人吗？那九个在哪里呢？","notes":[]},{"n":18,"t":"除了这外族人，再没有别人回来归荣耀给神吗？”","notes":[]},{"n":19,"t":"于是他对那人说：“起来，走吧，你的信救了你！”","notes":[]},{"n":20,"t":"法利赛人问：“神的国几时来到？”耶稣回答：“神的国来到，不是眼睛看得见的。","notes":[],"heads":["神国的来到"]},{"n":21,"t":"人也不能说：‘看哪，在这里！’或说：‘在那里！’因为神的国就在你们心里。”","notes":["“心里”或译“中间”。"]},{"n":22,"t":"他又对门徒说：“那些日子将到，你们渴望能看见人子的一个日子，却看不见。","notes":[]},{"n":23,"t":"有人要对你们说：‘看哪，在那里！’或说：‘看哪，在这里！’你们不要出去，也不要追随他们。","notes":[]},{"n":24,"t":"好像闪电从天这边一闪直照到天那边，人子在他的日子也要这样。","notes":["有古卷没有“在他的日子”。"]},{"n":25,"t":"可是他必须先受许多苦，又被这世代所弃绝。","notes":[]},{"n":26,"t":"挪亚的日子怎样，人子的日子也要怎样。","notes":[]},{"n":27,"t":"那时，人又吃又喝，又娶又嫁，直到挪亚进方舟的那日，洪水就来，把他们全都灭了。","notes":[]},{"n":28,"t":"同样，就像在罗得的日子，人又吃又喝，又买又卖，又耕种又建造，","notes":[]},{"n":29,"t":"到罗得离开所多玛的那日，有火与硫磺从天上降下来，把他们全都灭了。","notes":[]},{"n":30,"t":"人子显现的日子也要这样。","notes":[]},{"n":31,"t":"在那日，人在屋顶上，东西在屋里，不要下来拿；人在田里，也不要回家。","notes":[]},{"n":32,"t":"你们想想罗得的妻子吧！","notes":[]},{"n":33,"t":"凡想保全性命的，要丧失性命；凡丧失性命的，要保存性命。","notes":[]},{"n":34,"t":"我告诉你们，在那一夜，两个人在一张床上，一个被接去，一个被撇下。","notes":[]},{"n":35,"t":"两个女人一同推磨，一个被接去，一个被撇下。”","notes":["有古卷加“36 两个人在田里，一个被接去，一个被撇下。”"]},{"n":37,"t":"门徒回答他说：“主啊，在哪里呢？”耶稣对他们说：“尸首在哪里，鹰也会聚在哪里。”","notes":[]}]},"18":{"heading":"寡妇和法官的比喻","verses":[{"n":1,"t":"耶稣对门徒讲了一个比喻，为了要他们常常祷告，不可灰心。","notes":[]},{"n":2,"t":"他说：“某城有一个官，不惧怕神，也不尊重人。","notes":[]},{"n":3,"t":"那城里有个寡妇，常到他那里，说：‘我有一个冤家，求你给我伸冤。’","notes":[]},{"n":4,"t":"他很久不受理，后来心里说：‘我虽不惧怕神，也不尊重人，","notes":[]},{"n":5,"t":"只因这寡妇烦扰我，我就给她伸冤吧，免得她常来纠缠我。’”","notes":[]},{"n":6,"t":"主说：“你们听这不义的官所说的话。","notes":[]},{"n":7,"t":"神的选民昼夜呼吁他，他岂会延迟不给他们伸冤吗？","notes":[]},{"n":8,"t":"我告诉你们，他很快就要给他们伸冤。然而，人子来的时候，能在世上找到这样的信德吗？”","notes":[]},{"n":9,"t":"耶稣向那些自以为义而藐视别人的人讲了这比喻：","notes":[],"heads":["法利赛人和税吏的祷告"]},{"n":10,"t":"“有两个人上圣殿去祷告，一个是法利赛人，一个是税吏。","notes":[]},{"n":11,"t":"法利赛人独自站着，自言自语地祷告说：‘神啊，我感谢你，我不像别人勒索、不义、奸淫，也不像这个税吏。","notes":[]},{"n":12,"t":"我每周禁食两次，凡我所得的都献上十分之一。’","notes":[]},{"n":13,"t":"那税吏远远地站着，连举目望天也不敢，只捶着胸，说：‘神啊，开恩可怜我这个罪人！’","notes":[]},{"n":14,"t":"我告诉你们，这人回家去比那人倒算为义了。因为凡自高的，必降为卑；自甘卑微的，必升为高。”","notes":[]},{"n":15,"t":"有人甚至连婴孩也带来见耶稣，要他摸他们，门徒看见就责备那些人。","notes":[],"heads":["耶稣为小孩祝福"]},{"n":16,"t":"耶稣却叫他们来，说：“让小孩子到我这里来，不要阻止他们，因为在神国的正是这样的人。","notes":[]},{"n":17,"t":"我实在告诉你们，凡要接受神国的，若不像小孩子，绝不能进去。”","notes":[]},{"n":18,"t":"有一个官问耶稣说：“善良的老师，我该做什么事才能承受永生？”","notes":[],"heads":["富足的官寻求永生"]},{"n":19,"t":"耶稣对他说：“你为什么称我是善良的？除了神一位之外，再没有善良的。","notes":[]},{"n":20,"t":"诫命你是知道的：‘不可奸淫；不可杀人；不可偷盗；不可作假见证；当孝敬父母。’”","notes":[]},{"n":21,"t":"那人说：“这一切我从小都遵守了。”","notes":[]},{"n":22,"t":"耶稣听见了，就对他说：“你还缺少一件：要变卖你一切所有的，分给穷人，就必有财宝在天上；你还要来跟从我。”","notes":[]},{"n":23,"t":"他听见这些话，就很忧愁，因为他很富有。","notes":[]},{"n":24,"t":"耶稣见他变得很忧愁，就说：“有钱财的人进神的国是何等的难哪！","notes":["有古卷没有“变得很忧愁”。"]},{"n":25,"t":"骆驼穿过针眼比财主进神的国还容易呢！”","notes":[]},{"n":26,"t":"听见的人说：“这样，谁能得救呢？”","notes":[]},{"n":27,"t":"耶稣说：“在人所不能的事，在神都能。”","notes":[]},{"n":28,"t":"彼得说：“看哪，我们已经撇下自己所有的跟从你了。”","notes":[]},{"n":29,"t":"耶稣对他们说：“我实在告诉你们，凡是为神的国撇下房屋，或是妻子、兄弟、父母、儿女的，","notes":[]},{"n":30,"t":"没有不在今世得更多倍，而在来世得永生的。”","notes":[]},{"n":31,"t":"耶稣把十二使徒带到一边，对他们说：“看哪，我们上耶路撒冷去，先知所写的一切事都要成就在人子身上。","notes":[],"heads":["耶稣第三次预言受难和复活"]},{"n":32,"t":"他将被交给外邦人；他们要戏弄他，凌辱他，向他吐唾沫，","notes":[]},{"n":33,"t":"并要鞭打他，杀害他；第三天他要复活。”","notes":[]},{"n":34,"t":"这些事门徒一点也不明白，这话的意思对他们是隐藏的；他们不知道所说的是什么。","notes":[]},{"n":35,"t":"耶稣将近耶利哥的时候，有一个盲人坐在路旁讨饭。","notes":[],"heads":["治好耶利哥的盲人"]},{"n":36,"t":"他听见许多人经过，就问是什么事。","notes":[]},{"n":37,"t":"他们告诉他，是拿撒勒人耶稣经过。","notes":[]},{"n":38,"t":"他就呼叫说：“大卫之子耶稣啊，可怜我吧！”","notes":[]},{"n":39,"t":"在前头走的人就责备他，不许他作声，他却越发喊叫：“大卫之子啊，可怜我吧！”","notes":[]},{"n":40,"t":"耶稣就站住，吩咐把他领过来，他到了跟前，就问他：","notes":[]},{"n":41,"t":"“你要我为你做什么？”他说：“主啊，我要能看见。”","notes":[]},{"n":42,"t":"耶稣对他说：“你看见吧！你的信救了你。”","notes":[]},{"n":43,"t":"那盲人立刻看得见了，就跟随耶稣，一路归荣耀给神。众人看见这事，也都赞美神。","notes":[]}]},"19":{"heading":"撒该悔改","verses":[{"n":1,"t":"耶稣进了耶利哥，要从那里经过。","notes":[]},{"n":2,"t":"有一个人名叫撒该，作税吏长，是个财主。","notes":[]},{"n":3,"t":"他要看看耶稣是怎样的人，只因人多，他的身材又矮，所以看不见。","notes":[]},{"n":4,"t":"于是他跑到前头，爬上桑树，要看耶稣，因为耶稣要从那里经过。","notes":[]},{"n":5,"t":"耶稣到了那里，抬头一看，对他说：“撒该，快下来！今天我必须住在你家里。”","notes":[]},{"n":6,"t":"他就急忙下来，欢欢喜喜地接待耶稣。","notes":[]},{"n":7,"t":"众人看见，都私下议论说：“他竟然到罪人家里去住宿。”","notes":[]},{"n":8,"t":"撒该站着对主说：“主啊，我把所有的一半给穷人；我若勒索了谁，就还他四倍。”","notes":[]},{"n":9,"t":"耶稣对他说：“今天救恩到了这家，因为他也是亚伯拉罕的子孙。","notes":[]},{"n":10,"t":"人子来是要寻找和拯救失丧的人。”","notes":[]},{"n":11,"t":"众人正听见这些话的时候，耶稣因为将近耶路撒冷，又因他们以为神的国快要显现，就接着讲了一个比喻，","notes":[],"heads":["十锭银子的比喻"]},{"n":12,"t":"说：“有一个贵族往远方去，为要取得王位，然后回来。","notes":[]},{"n":13,"t":"他叫了自己的十个仆人来，交给他们十锭银子，说：‘你们去做生意，直到我回来。’","notes":[]},{"n":14,"t":"他本国的百姓却恨他，打发使者随后去，说：‘我们不愿意这个人作我们的王。’","notes":[]},{"n":15,"t":"他得了王位回来，就吩咐叫那领了银子的仆人来，要知道他们做生意赚了多少。","notes":[]},{"n":16,"t":"头一个上来，说：‘主啊，你的一锭银子已经赚了十锭。’","notes":[]},{"n":17,"t":"主人对他说：‘好，我善良的仆人，你既在最小的事上忠心，你有权柄管十座城。’","notes":[]},{"n":18,"t":"第二个来，说：‘主啊，你的一锭银子已经赚了五锭。’","notes":[]},{"n":19,"t":"主人也对这个说：‘你管五座城。’","notes":[]},{"n":20,"t":"又有一个来说：‘主啊！看哪，你的一锭银子在这里，我把它包在手巾里存着。","notes":[]},{"n":21,"t":"我向来怕你，因为你是严厉的人：没有放的，也要去拿；没有种的，也要去收。’","notes":[]},{"n":22,"t":"主人对他说：‘你这恶仆，我要凭你的话定你的罪。你既知道我是严厉的人，没有放的也去拿，没有种的也去收，","notes":[]},{"n":23,"t":"为什么不把我的银子存在银行，等我来的时候，连本带利都取回来呢？’","notes":[]},{"n":24,"t":"于是他对那些站在旁边的人说：‘把他这一锭夺过来，给那有十锭的。’","notes":[]},{"n":25,"t":"他们对他说：‘主啊，他已经有十锭了。’","notes":[]},{"n":26,"t":"主人说：‘我告诉你们，凡有的，还要给他；没有的，连他所有的也要夺过来。","notes":[]},{"n":27,"t":"至于我那些仇敌，不要我作他们王的，把他们拉来，在我面前杀了！’”","notes":[]},{"n":28,"t":"耶稣说完了这些话，就走在前面，上耶路撒冷去。","notes":[],"heads":["荣入圣城"]},{"n":29,"t":"快到伯法其和伯大尼，在名叫橄榄山的地方，他打发两个门徒，","notes":[]},{"n":30,"t":"说：“你们往对面村子里去，进去的时候会看见一匹驴驹拴在那里，是从来没有人骑过的，把它解开，牵来。","notes":[]},{"n":31,"t":"若有人问为什么解开它，你们就这样说：‘主要用它。’”","notes":[]},{"n":32,"t":"被打发的人去了，所遇见的正如耶稣对他们所说的。","notes":[]},{"n":33,"t":"他们解开驴驹的时候，主人问他们：“为什么解开驴驹？”","notes":[]},{"n":34,"t":"他们说：“主要用它。”","notes":[]},{"n":35,"t":"他们把驴驹牵到耶稣那里，把自己的衣服搭在上面，扶耶稣骑上。","notes":[]},{"n":36,"t":"他前进的时候，众人把衣服铺在路上。","notes":[]},{"n":37,"t":"他将近耶路撒冷，正下橄榄山的时候，一大群门徒因所见过的一切异能，都欢呼起来，大声赞美神，","notes":[]},{"n":38,"t":"说：“奉主名来的王是应当称颂的！在天上有和平；在至高之处有荣光。”","notes":["有古卷没有“王”。"]},{"n":39,"t":"人群中有几个法利赛人对耶稣说：“老师，责备你的门徒吧！”","notes":[]},{"n":40,"t":"耶稣回答：“我告诉你们，若是这些人闭口不说，石头也要呼叫起来。”","notes":[]},{"n":41,"t":"耶稣快到耶路撒冷，看见那城，就为它哀哭，","notes":[]},{"n":42,"t":"说：“但愿你在这日子知道有关你平安的事，不过这事现在是隐藏的，你的眼睛看不出来。","notes":[]},{"n":43,"t":"因为日子将到，你的仇敌要筑起土垒包围你，四面困住你，","notes":[]},{"n":44,"t":"并要消灭你和你里头的儿女，连一块石头也不留在另一块石头上，因为你不知道你蒙眷顾的时候。”","notes":[]},{"n":45,"t":"耶稣一进圣殿就赶出在里面做买卖的人，","notes":[],"heads":["洁净圣殿"]},{"n":46,"t":"对他们说：“经上说：‘我的殿是祷告的殿，你们倒使它成为贼窝了。’”","notes":[]},{"n":47,"t":"耶稣天天在圣殿里教导人。祭司长、文士和百姓的领袖都想杀他，","notes":[]},{"n":48,"t":"但找不出方法来，因为百姓都侧耳听他。","notes":[]}]},"20":{"heading":"耶稣的权柄受到质问","verses":[{"n":1,"t":"有一天，耶稣在圣殿里教导百姓，宣讲福音的时候，祭司长、文士和长老上前来，","notes":[]},{"n":2,"t":"问他说：“你告诉我们，你仗着什么权柄做这些事？给你这权柄的是谁呢？”","notes":[]},{"n":3,"t":"耶稣回答他们：“我也要问你们一句话，你们告诉我。","notes":[]},{"n":4,"t":"约翰的洗礼是从天上来的，还是从人间来的呢？”","notes":[]},{"n":5,"t":"他们彼此商量说：“我们若说‘从天上来的’，他会说‘这样，你们为什么不信他呢？’","notes":[]},{"n":6,"t":"我们若说‘从人间来的’，所有的百姓都会用石头打死我们，因为他们信约翰是先知。”","notes":[]},{"n":7,"t":"于是他们回答：“我们不知道是从哪里来的。”","notes":[]},{"n":8,"t":"耶稣对他们说：“我也不告诉你们，我仗着什么权柄做这些事。”","notes":[]},{"n":9,"t":"耶稣用这个比喻对百姓说：“有人开垦了一个葡萄园，租给园户，就出外远行，去了许久。","notes":[],"heads":["恶园户的比喻"]},{"n":10,"t":"到了时候，他打发一个仆人到园户那里去，叫他们把园中当纳的果子交给他；园户竟打了他，叫他空手回去。","notes":[]},{"n":11,"t":"园主又打发另一个仆人去，他们也打了他，并且侮辱他，叫他空手回去。","notes":[]},{"n":12,"t":"园主又打发第三个仆人去，他们也打伤了他，把他推出去了。","notes":[]},{"n":13,"t":"葡萄园主说：‘我要怎么做呢？我要打发我的爱子去，或许他们会尊敬他。’","notes":[]},{"n":14,"t":"可是，园户看见他，彼此说：‘这是承受产业的。我们杀了他，产业就归我们了！’","notes":[]},{"n":15,"t":"于是他们把他扔出葡萄园外，杀了。这样，葡萄园主要怎么处置他们呢？","notes":[]},{"n":16,"t":"他要来除灭那些园户，将葡萄园转给别人。”听见的人说：“绝对不可！”","notes":[]},{"n":17,"t":"耶稣看着他们，说：“那么，经上记着：‘匠人所丢弃的石头已作了房角的头块石头。’这是什么意思呢？","notes":[]},{"n":18,"t":"凡跌在那石头上的，一定会跌得粉碎；那石头掉在谁的身上，就要把谁压得稀烂。”","notes":[]},{"n":19,"t":"文士和祭司长看出这比喻是指着他们说的，当时就想要下手拿他，只是惧怕百姓。","notes":[]},{"n":20,"t":"于是他们窥探耶稣，打发奸细装作好人，要在他的话上抓把柄，好把他交给总督处置。","notes":[],"heads":["纳税给凯撒的问题"]},{"n":21,"t":"奸细就问耶稣：“老师，我们知道你所讲所教的都很正确，也不看人的面子，而是诚诚实实传神的道。","notes":[]},{"n":22,"t":"我们纳税给凯撒合不合法？”","notes":[]},{"n":23,"t":"耶稣看出他们的诡诈，就对他们说：","notes":[]},{"n":24,"t":"“拿一个银币来给我看。这像和这名号是谁的？”他们说：“是凯撒的。”","notes":[]},{"n":25,"t":"耶稣对他们说：“这样，凯撒的归凯撒，神的归神。”","notes":[]},{"n":26,"t":"他们无法当着百姓在他的话上抓到把柄，又因他的对答而惊讶，就闭口不言了。","notes":[]},{"n":27,"t":"有些撒都该人来见耶稣。他们说没有复活这回事，于是问耶稣：","notes":[],"heads":["复活的问题"]},{"n":28,"t":"“老师，摩西为我们写下这话：‘某人的哥哥若死了，有妻无子，他该娶哥哥的妻子，为哥哥生子立后。’","notes":[]},{"n":29,"t":"那么，有兄弟七人，第一个娶了妻，没有孩子死了。","notes":[]},{"n":30,"t":"第二个、","notes":[]},{"n":31,"t":"第三个也娶过她；同样地，七个人都娶过她，没有留下孩子就死了。","notes":[]},{"n":32,"t":"后来，那妇人也死了。","notes":[]},{"n":33,"t":"那么，在复活的时候，那妇人是哪一个的妻子呢？因为他们七个人都娶过她。”","notes":[]},{"n":34,"t":"耶稣对他们说：“这世代的人有娶有嫁，","notes":[]},{"n":35,"t":"惟有配得那要来的世代和从死人中复活的人不娶也不嫁。","notes":[]},{"n":36,"t":"因为他们不能再死，和天使一样；既然是复活的人，他们就是神的儿子。","notes":[]},{"n":37,"t":"至于死人复活，摩西在《荆棘篇》上就指明了，他称主是亚伯拉罕的神，以撒的神，雅各的神。","notes":[]},{"n":38,"t":"神不是死人的神，而是活人的神，因为对他来说，人都是活的。”","notes":[]},{"n":39,"t":"有几个文士说：“老师，你说得好。”","notes":[]},{"n":40,"t":"以后，他们不敢再问他什么了。","notes":[]},{"n":41,"t":"耶稣对他们说：“人们怎么说基督是大卫的后裔呢？","notes":[],"heads":["基督与大卫的关系"]},{"n":42,"t":"《诗篇》上大卫自己说：“主对我主说：‘你坐在我的右边，","notes":[]},{"n":43,"t":"等我使你的仇敌作你的脚凳。’","notes":[]},{"n":44,"t":"大卫既称他为主，他怎么又是大卫的后裔呢？”","notes":[]},{"n":45,"t":"众百姓听的时候，耶稣对他的门徒说：","notes":[],"heads":["谴责文士"]},{"n":46,"t":"“你们要防备文士。他们好穿长袍走来走去，喜欢人们在街市上向他们问安，又喜爱会堂里的高位，宴席上的首座。","notes":[]},{"n":47,"t":"他们侵吞寡妇的家产，假意作很长的祷告。这些人要受更重的惩罚！”","notes":[]}]},"21":{"heading":"寡妇的奉献","verses":[{"n":1,"t":"耶稣抬头观看，见财主把捐项投入圣殿银库，","notes":[]},{"n":2,"t":"又见一个穷寡妇投了两个小文钱，","notes":["“小文钱”：参“度量衡表”。"]},{"n":3,"t":"就说：“我实在告诉你们，这穷寡妇所投的比众人更多。","notes":[]},{"n":4,"t":"因为众人都是拿有余的捐献，但这寡妇，虽然自己不足，却把一生所有的都投进去了。”","notes":[]},{"n":5,"t":"有人谈论圣殿是用美石和供物装饰的，耶稣就说：","notes":[],"heads":["预言圣殿被毁"]},{"n":6,"t":"“你们所看见的这一切，日子将到，没有一块石头会留在另一块石头上而不被拆毁的。”","notes":[]},{"n":7,"t":"他们问他：“老师，什么时候有这些事呢？这些事将临到的时候有什么预兆呢？”","notes":[],"heads":["终局的预兆"]},{"n":8,"t":"耶稣说：“你们要谨慎，不要受迷惑，因为将有好些人冒我的名来，说‘我是基督’，又说‘时候近了’，你们不要跟从他们！","notes":[]},{"n":9,"t":"当你们听见打仗和动乱的事，不要惊惶；因为这些事必须先发生，但终结不会立刻就到。”","notes":[]},{"n":10,"t":"于是耶稣对他们说：“民要攻打民，国要攻打国，","notes":[]},{"n":11,"t":"将有大地震，多处必有饥荒、瘟疫，又有可怕的异象和大神迹从天上显现。","notes":[]},{"n":12,"t":"但这一切的事以前，有人要下手拿你们，迫害你们，把你们交给会堂，并且关在监里，又为我名的缘故拉你们到君王和统治者面前。","notes":[]},{"n":13,"t":"但这些事终必成为你们作见证的机会。","notes":[]},{"n":14,"t":"所以，你们要立定心意，不要预先考虑怎样申辩；","notes":[]},{"n":15,"t":"因为我必赐你们口才和智慧，是你们一切敌人所敌不住、驳不倒的。","notes":[]},{"n":16,"t":"连你们的父母、兄弟、亲族、朋友也要把你们交给官府；你们中间也将有被他们害死的。","notes":[]},{"n":17,"t":"你们要为我的名被众人憎恨。","notes":[]},{"n":18,"t":"然而，你们连一根头发也不会损失。","notes":[]},{"n":19,"t":"你们凭着坚忍，就必保全性命。”","notes":[]},{"n":20,"t":"“当你们看见耶路撒冷被兵围困，就可知道它成为荒芜的日子近了。","notes":[],"heads":["预言耶路撒冷被毁"]},{"n":21,"t":"那时，在犹太的，应当逃到山上；在城里的，应当出来；在乡下的，不要进城。","notes":[]},{"n":22,"t":"因为这是报应的日子，要使经上所写的都得应验。","notes":[]},{"n":23,"t":"在那些日子，怀孕的和奶孩子的就苦了。因为将有大灾难降在这地方，也有愤怒临到这百姓。","notes":[]},{"n":24,"t":"他们要倒在刀下，又被掳到各国去。耶路撒冷要被外邦人践踏，直到外邦人的日子满了。”","notes":[]},{"n":25,"t":"“日月星辰要显出预兆，地上的邦国也有困苦，因海中波浪的响声而惶惶不安。","notes":[],"heads":["人子的来临"]},{"n":26,"t":"人想到那要临到世界的事，就都吓得魂不附体，因为天上的万象都要震动。","notes":[]},{"n":27,"t":"那时，他们要看见人子带着能力和大荣耀驾云来临。","notes":[]},{"n":28,"t":"一有这些事，你们就当挺身昂首，因为你们得救赎的日子近了。”","notes":[]},{"n":29,"t":"耶稣对他们讲了一个比喻说：“你们看无花果树和各样的树，","notes":[],"heads":["从无花果树学功课"]},{"n":30,"t":"树叶一长出来，你们看了自然就知道夏天近了。","notes":[]},{"n":31,"t":"同样，当你们看见这些事发生，就知道神的国近了。","notes":[]},{"n":32,"t":"我实在告诉你们，这世代还没有过去，一切都要发生。","notes":[]},{"n":33,"t":"天地要废去，我的话却绝不废去。”","notes":[]},{"n":34,"t":"“你们要谨慎，免得被贪食、醉酒和今生的忧虑压住你们的心，那日子就忽然临到你们，","notes":[],"heads":["劝告门徒警醒"]},{"n":35,"t":"如同罗网一样，因为那日子要临到所有居住在地面上的人。","notes":[]},{"n":36,"t":"你们要时时警醒，常常祈求，使你们能逃避这一切要来的事，得以站立在人子面前。”","notes":[]},{"n":37,"t":"耶稣每日在圣殿里教导人，每夜出城到橄榄山住宿。","notes":[]},{"n":38,"t":"众百姓清早上圣殿，到耶稣那里听他讲道。","notes":[]}]},"22":{"heading":"杀害耶稣的阴谋","verses":[{"n":1,"t":"除酵节，又叫逾越节，近了。","notes":[]},{"n":2,"t":"祭司长和文士在想法子怎样杀害耶稣，因他们惧怕百姓。","notes":[]},{"n":3,"t":"这时，撒但入了那称为加略人犹大的心。他本是十二使徒里的一个。","notes":[]},{"n":4,"t":"他去跟祭司长和守殿官商量怎样把耶稣交给他们。","notes":[]},{"n":5,"t":"他们很高兴，就约定给他银子。","notes":[]},{"n":6,"t":"他应允了，就找机会，要趁众人不在跟前的时候把耶稣交给他们。","notes":[]},{"n":7,"t":"除酵节到了，这一天必须宰逾越节的羔羊。","notes":[],"heads":["预备逾越节的宴席"]},{"n":8,"t":"耶稣打发彼得和约翰，说：“你们去为我们预备逾越节的宴席，好让我们吃。”","notes":[]},{"n":9,"t":"他们问他：“你要我们在哪里预备？”","notes":[]},{"n":10,"t":"耶稣对他们说：“你们进了城，会有人拿着一罐水迎面而来，你们就跟着他，到他所进的房子里去，","notes":[]},{"n":11,"t":"对那家的主人说：‘老师问：客房在哪里？我和我的门徒要在那里吃逾越节的宴席。’","notes":[]},{"n":12,"t":"他会带你们看一间摆设齐全的楼上大厅，你们就在那里预备。”","notes":[]},{"n":13,"t":"他们去了，所看到的正如耶稣所说的。他们就预备了逾越节的宴席。","notes":[]},{"n":14,"t":"时候到了，耶稣坐席，使徒们也和他同坐。","notes":[],"heads":["设立主的晚餐"]},{"n":15,"t":"耶稣对他们说：“我非常渴望在受害以前和你们吃这逾越节的宴席。","notes":[]},{"n":16,"t":"我告诉你们，我不再吃这宴席，直到它实现在神的国里。”","notes":[]},{"n":17,"t":"耶稣接过杯来，祝谢了，说：“你们拿这杯，大家分着喝。","notes":[]},{"n":18,"t":"我告诉你们，从今以后，我不再喝这葡萄汁，直等神的国来到。”","notes":[]},{"n":19,"t":"他又拿起饼来，祝谢了，就擘开，递给他们，说：“这是我的身体，为你们舍的，你们要如此行，为的是记念我。”","notes":[]},{"n":20,"t":"饭后他照样拿起杯来，说：“这杯是用我的血所立的新约，为你们流出来的。","notes":[]},{"n":21,"t":"但是，看哪，那出卖我的人的手跟我一同在桌子上。","notes":[]},{"n":22,"t":"人子固然要照所预定的离去，但那出卖人子的人有祸了！”","notes":[]},{"n":23,"t":"于是他们开始互相追问他们中间哪一个会做这事。","notes":[]},{"n":24,"t":"门徒中间也起了争论：他们中哪一个可算为大。","notes":[],"heads":["争论谁为大"]},{"n":25,"t":"耶稣对他们说：“外邦人有君王为主治理他们，那掌权管他们的称为恩主。","notes":[]},{"n":26,"t":"但你们不可这样。你们中间最大的，倒要成为最小的；为领袖的，倒要像服事人的。","notes":[]},{"n":27,"t":"是谁为大？是坐席的还是服事人的呢？不是坐席的大吗？然而，我在你们中间是如同服事人的。","notes":[]},{"n":28,"t":"“我在试炼之中，常和我同在的就是你们。","notes":[]},{"n":29,"t":"我把国赐给你们，正如我父赐给我一样，","notes":[]},{"n":30,"t":"使你们在我的国里坐在我的席上吃喝，并且坐在宝座上审判以色列十二个支派。”","notes":[]},{"n":31,"t":"主又说：“西门，西门！撒但要得着你们，好筛你们像筛麦子一样；","notes":[],"heads":["预言彼得不认主"]},{"n":32,"t":"但我已经为你祈求，使你不至于失了信心。你回头以后，要坚固你的弟兄。”","notes":[]},{"n":33,"t":"彼得对他说：“主啊，我已准备好要同你坐牢，与你同死。”","notes":[]},{"n":34,"t":"耶稣说：“彼得，我告诉你，今日鸡还没有叫，你要三次说不认得我。”","notes":[]},{"n":35,"t":"耶稣又对他们说：“我差你们出去的时候，没有钱囊，没有行囊，没有鞋子，你们缺少什么没有？”他们说：“没有。”","notes":[],"heads":["钱囊、行囊、刀"]},{"n":36,"t":"耶稣对他们说：“但如今，有钱囊的要带着，有行囊的也一样；没有刀的要卖衣服买刀。","notes":[]},{"n":37,"t":"我告诉你们，经上写着说：‘他被列在罪犯之中。’这话必须应验在我身上，因为那关于我的事必然成就。”","notes":[]},{"n":38,"t":"他们说：“主啊，请看！这里有两把刀。”耶稣对他们说：“够了。”","notes":[]},{"n":39,"t":"耶稣出来，照常往橄榄山去，门徒也跟随他。","notes":[],"heads":["在橄榄山上祷告"]},{"n":40,"t":"到了那地方，他就对他们说：“你们要祷告，免得陷入试探。”","notes":[]},{"n":41,"t":"于是他离开他们约有一块石头扔出去那么远，跪下祷告，","notes":[]},{"n":42,"t":"说：“父啊！你若愿意，求你将这杯撤去；然而，不是照我的意愿，而是要成全你的旨意。”","notes":[]},{"n":43,"t":"〔 有一位天使从天上显现，加添他的力量。","notes":[]},{"n":44,"t":"耶稣非常痛苦焦虑，祷告更加恳切，汗如大血点滴在地上。〕","notes":["有古卷没有43、44两节。"]},{"n":45,"t":"祷告完了，他起来，到门徒那里，见他们因为忧愁都睡着了，","notes":[]},{"n":46,"t":"就对他们说：“你们为什么睡觉呢？起来祷告，免得陷入试探！”","notes":[]},{"n":47,"t":"耶稣还在说话的时候，来了一群人。十二使徒之一名叫犹大的，走在前头，接近耶稣，要亲他。","notes":[],"heads":["耶稣被捕"]},{"n":48,"t":"耶稣对他说：“犹大，你用亲吻来出卖人子吗？”","notes":[]},{"n":49,"t":"左右的人见了要发生的事，就说：“主啊，我们拿刀砍好不好？”","notes":[]},{"n":50,"t":"其中有一个人把大祭司的仆人砍了一刀，削掉了他的右耳。","notes":[]},{"n":51,"t":"耶稣回答说：“算了，住手吧！”就摸那人的耳朵，把他治好了。","notes":[]},{"n":52,"t":"耶稣对那些来抓他的祭司长、守殿官和长老说：“你们带着刀棒出来，如同对付强盗吗？","notes":[]},{"n":53,"t":"我天天同你们在圣殿里，你们不下手抓我。现在却是你们的时候，黑暗掌权了。”","notes":[]},{"n":54,"t":"他们拿住耶稣，把他带走，进入大祭司的住宅。彼得远远地跟着。","notes":[],"heads":["彼得三次不认主"]},{"n":55,"t":"他们在院子中间生了火，一同坐着，彼得也坐在他们当中。","notes":[]},{"n":56,"t":"有一个使女看见彼得面向火光坐着，就定睛看他，说：“这个人素来也是同那人一起的。”","notes":[]},{"n":57,"t":"彼得却不承认，说：“你这个女人，我不认得他！”","notes":[]},{"n":58,"t":"过了一会儿，又有一个人看见他，说：“你也是他们一伙的。”彼得说：“你这个人，我不是！”","notes":[]},{"n":59,"t":"约过了一小时，又有一个人坚持说：“他实在是同那人一起的，因为他也是加利利人。”","notes":[]},{"n":60,"t":"彼得说：“你这个人，我不知道你在说什么！”正说话之间，鸡就叫了。","notes":[]},{"n":61,"t":"主转过身来看彼得，彼得就想起主对他所说的话：“今日鸡叫以前，你要三次不认我。”","notes":[]},{"n":62,"t":"他就出去痛哭。","notes":[]},{"n":63,"t":"看守耶稣的人戏弄他，打他，","notes":[],"heads":["戏弄鞭打耶稣"]},{"n":64,"t":"又蒙着他的眼，问他：“你说预言吧！打你的是谁？”","notes":[]},{"n":65,"t":"他们还用许多别的话辱骂他。","notes":[]},{"n":66,"t":"天一亮，民间的众长老、祭司长和文士都聚集，把耶稣带到他们的议会里，","notes":[],"heads":["耶稣在议会受审"]},{"n":67,"t":"说：“如果你是基督，就告诉我们。”耶稣对他们说：“我若告诉你们，你们也不信；","notes":[]},{"n":68,"t":"我若问你们，你们也不回答。","notes":[]},{"n":69,"t":"从今以后，人子要坐在权能者神的右边。”","notes":[]},{"n":70,"t":"他们都说：“那么，你是神的儿子了？”耶稣对他们说：“你们说我是。”","notes":[]},{"n":71,"t":"他们说：“我们何必再要见证呢？他亲口所说的，我们都亲耳听见了。”","notes":[]}]},"23":{"heading":"耶稣在彼拉多面前受审","verses":[{"n":1,"t":"众人都起来，把耶稣解到彼拉多面前。","notes":[]},{"n":2,"t":"他们开始控告他说：“我们见这人煽惑我们的国民，禁止我们纳税给凯撒，并说自己是基督，是王。”","notes":[]},{"n":3,"t":"彼拉多问耶稣：“你是犹太人的王吗？”耶稣回答：“是你说的。”","notes":[]},{"n":4,"t":"彼拉多对祭司长们和众人说：“我查不出这人有什么罪来。”","notes":[]},{"n":5,"t":"但他们越发竭力地说：“他煽动百姓，在犹太全地传道，从加利利起，直到这里了。”","notes":[]},{"n":6,"t":"彼拉多一听见，就问：“这人是加利利人吗？”","notes":[],"heads":["耶稣在希律面前受审"]},{"n":7,"t":"既知道耶稣属希律所管，彼拉多就把他送到希律那里去。那时希律正在耶路撒冷。","notes":[]},{"n":8,"t":"希律看见耶稣就非常高兴；因为听见过他的事，早就想要见他，并且指望看他行些神迹，","notes":[]},{"n":9,"t":"于是问他许多的话，耶稣却一言不答。","notes":[]},{"n":10,"t":"那些祭司长和文士都站着，竭力控告他。","notes":[]},{"n":11,"t":"希律和他的士兵就藐视耶稣，戏弄他，给他穿上华丽的衣服，把他送回彼拉多那里去。","notes":[]},{"n":12,"t":"从前希律和彼拉多彼此有仇，在那一天竟成了朋友。","notes":[]},{"n":13,"t":"彼拉多传齐了众祭司长、官长和百姓，","notes":[],"heads":["耶稣被判死刑"]},{"n":14,"t":"对他们说：“你们解这人到我这里，说他是煽惑百姓的。看哪，我也曾在你们面前审问他，并没有查出这人犯过你们控告他的任何罪；","notes":[]},{"n":15,"t":"就是希律也是如此，所以把他送回来。可见他没有做什么该死的事。","notes":[]},{"n":16,"t":"所以，我要责打他，把他释放。”","notes":["有古卷加“17 每逢这节期，总督必须释放一个囚犯给他们。”"]},{"n":18,"t":"众人却一齐喊着说：“除掉这个人！释放巴拉巴给我们！”","notes":[]},{"n":19,"t":"这巴拉巴是因在城里作乱和杀人而下在监里的。","notes":[]},{"n":20,"t":"彼拉多愿意释放耶稣，就再次向他们讲话。","notes":[]},{"n":21,"t":"无奈他们喊着说：“把他钉十字架！把他钉十字架！”","notes":[]},{"n":22,"t":"彼拉多第三次对他们说：“为什么呢？这人做了什么恶事呢？我并没有查出他有什么该死的罪来。所以，我要责打他，把他释放。”","notes":[]},{"n":23,"t":"他们大声催逼彼拉多，要求他把耶稣钉十字架；他们的声音终于得胜。","notes":[]},{"n":24,"t":"彼拉多这才照他们的要求定案；","notes":[]},{"n":25,"t":"又把他们所要求的那因作乱和杀人而下在监里的人释放了，而把耶稣交给他们，随他们的意思处置。","notes":[]},{"n":26,"t":"他们把耶稣带去的时候，有一个古利奈人西门从乡下来，他们就拿住他，把十字架搁在他身上，叫他背着跟在耶稣后面。","notes":[],"heads":["耶稣被钉十字架"]},{"n":27,"t":"有许多百姓跟随耶稣，其中有好些妇女为他号啕痛哭。","notes":[]},{"n":28,"t":"耶稣转身对她们说：“耶路撒冷的女子，不要为我哭，要为你们自己和你们的儿女哭。","notes":[]},{"n":29,"t":"因为日子将到，人要说：‘不生育的、未曾怀孕的，和未曾哺乳孩子的有福了！’","notes":[]},{"n":30,"t":"那时，人要向大山说：‘倒在我们身上！’向小山说：‘遮盖我们！’","notes":[]},{"n":31,"t":"他们若在树木青绿的时候做这些事，那么在枯干的时候将会怎么样呢？”","notes":[]},{"n":32,"t":"另外有两个犯人也被带来和耶稣一同处死。","notes":[]},{"n":33,"t":"到了一个地方，名叫髑髅地，他们就在那里把耶稣钉在十字架上，又钉了两个犯人：一个在右边，一个在左边。","notes":[]},{"n":34,"t":"〔 这时，耶稣说：“父啊！赦免他们，因为他们所做的，他们不知道。”〕士兵就抽签分他的衣服。","notes":["有古卷没有括号里的文字。"]},{"n":35,"t":"百姓站在那里观看。官长也嘲笑他，说：“他救了别人，他若是基督，是神所拣选的，救救他自己吧！”","notes":[]},{"n":36,"t":"士兵也戏弄他，上前拿醋送给他喝，","notes":[]},{"n":37,"t":"说：“你若是犹太人的王，救救你自己吧！”","notes":[]},{"n":38,"t":"在耶稣上方有一个牌子写着：“这是犹太人的王。”","notes":[]},{"n":39,"t":"同钉的犯人中有一个讥笑他，说：“你不是基督吗？救救你自己和我们吧！”","notes":[]},{"n":40,"t":"另一个就应声责备他，说：“你是一样受刑的，还不怕神吗？","notes":[]},{"n":41,"t":"我们是应得的，因为我们是自作自受，但这个人没有做过一件不对的事。”","notes":[]},{"n":42,"t":"他对耶稣说：“耶稣啊，你进入你国的时候，求你记念我。”","notes":[]},{"n":43,"t":"耶稣对他说：“我实在告诉你，今日你要同我在乐园里了。”","notes":["“我实在…乐园里了。”或译“我今日实在告诉你，你将要同我在乐园里。”"]},{"n":44,"t":"那时大约是正午，全地都黑暗了，直到下午三点钟，","notes":[],"heads":["耶稣之死"]},{"n":45,"t":"太阳变黑了，殿的幔子从当中裂为两半。","notes":[]},{"n":46,"t":"耶稣大声喊着说：“父啊，我将我的灵交在你手里！”他说了这话，气就断了。","notes":[]},{"n":47,"t":"百夫长看见所发生的事，就归荣耀给神，说：“这人真是个义人！”","notes":[]},{"n":48,"t":"聚集观看这事的众人，见了所发生的事，都捶着胸回去了。","notes":[]},{"n":49,"t":"所有与耶稣熟悉的人，和从加利利跟着他来的妇女们，都远远地站着，看这些事。","notes":[]},{"n":50,"t":"有一个人名叫约瑟，是个议员，为人善良正直，","notes":[],"heads":["耶稣的安葬"]},{"n":51,"t":"却没有附从别人的所谋所为。他是犹太的亚利马太城人，素常盼望着神的国。","notes":[]},{"n":52,"t":"这人去见彼拉多，请求要耶稣的身体。","notes":[]},{"n":53,"t":"他把耶稣的身体取下来，用细麻布裹好，安放在凿岩而成的坟墓里；那坟墓从来没有葬过人。","notes":[]},{"n":54,"t":"那日是预备日，安息日快到了。","notes":[]},{"n":55,"t":"那些从加利利和耶稣同来的妇女跟在后面，看见了坟墓和他的身体怎样安放。","notes":[]},{"n":56,"t":"她们就回去，预备了香料香膏。在安息日，她们遵照诫命安息了。","notes":[]}]},"24":{"heading":"耶稣复活","verses":[{"n":1,"t":"七日的第一日，黎明的时候，那些妇女带着所预备的香料来到坟墓那里，","notes":[]},{"n":2,"t":"发现石头已经从坟墓滚开了，","notes":[]},{"n":3,"t":"她们就进去，只是不见主耶稣的身体。","notes":[]},{"n":4,"t":"正在为这事困惑的时候，忽然有两个人站在旁边，衣服放光。","notes":[]},{"n":5,"t":"妇女们非常害怕，就俯伏在地上。那两个人对她们说：“为什么在死人中找活人呢？","notes":[]},{"n":6,"t":"他不在这里，已经复活了。要记得他还在加利利的时候怎样告诉你们的，","notes":[]},{"n":7,"t":"他说：‘人子必须被交在罪人手里，钉在十字架上，第三天复活。’”","notes":[]},{"n":8,"t":"她们就想起耶稣的话来。","notes":[]},{"n":9,"t":"于是她们从坟墓那里回去，把这一切事告诉十一个使徒和其余的人。","notes":[]},{"n":10,"t":"把这些事告诉使徒的有抹大拉的马利亚、约亚拿，和雅各的母亲马利亚，还有跟她们在一起的妇女。","notes":[]},{"n":11,"t":"她们这些话，使徒以为是胡言，就不相信。","notes":[]},{"n":12,"t":"彼得起来，跑到坟墓前，俯身往里看，只见细麻布，就回去了，因所发生的事而心里惊讶。","notes":[]},{"n":13,"t":"同一天，门徒中有两个人往一个村子去；这村子名叫以马忤斯，离耶路撒冷约有二十五里。","notes":["“二十五里”：即十一公里，原文是“六十斯他迪”，古希腊长度单位；参“度量衡表”。"],"heads":["在去以马忤斯的路上"]},{"n":14,"t":"他们彼此谈论所发生的这一切事。","notes":[]},{"n":15,"t":"正交谈议论的时候，耶稣亲自走近他们，和他们同行，","notes":[]},{"n":16,"t":"可是他们的眼睛模糊了，没认出他。","notes":[]},{"n":17,"t":"耶稣对他们说：“你们一边走一边谈，彼此谈论的是什么事呢？”他们就站住，脸上带着愁容。","notes":[]},{"n":18,"t":"两人中有一个名叫革流巴的回答：“你是在耶路撒冷的旅客中，惟一还不知道这几天在那里发生了什么事的人吗？”","notes":[]},{"n":19,"t":"耶稣对他们说：“什么事呢？”他们对他说：“就是拿撒勒人耶稣的事。他是个先知，在神和众百姓面前，说话行事都大有能力。","notes":[]},{"n":20,"t":"祭司长们和我们的官长竟把他解去，定了死罪，钉在十字架上。","notes":[]},{"n":21,"t":"但我们素来所盼望要救赎以色列民的就是他。不但如此，这些事发生到现在已经三天了。","notes":[]},{"n":22,"t":"还有，我们中间的几个妇女使我们惊奇：她们清早去了坟墓，","notes":[]},{"n":23,"t":"不见他的身体，就回来告诉我们，说她们看见了天使显现，说他活了。","notes":[]},{"n":24,"t":"又有我们的几个人往坟墓那里去，所发现的正如妇女们所说的，只是没有看见他。”","notes":[]},{"n":25,"t":"耶稣对他们说：“无知的人哪，先知所说的一切话，你们的心信得太迟钝了。","notes":[]},{"n":26,"t":"基督不是必须受这些苦难，然后进入他的荣耀吗？”","notes":[]},{"n":27,"t":"于是，他从摩西和众先知起，凡经上所指着自己的话都给他们作了解释。","notes":[]},{"n":28,"t":"他们走近所要去的村子，耶稣好像还要往前走，","notes":[]},{"n":29,"t":"他们却强留他说：“时候晚了，天快黑了，请你同我们住下吧。”耶稣就进去，要同他们住下。","notes":[]},{"n":30,"t":"坐下来和他们用餐的时候，耶稣拿起饼来，祝福了，擘开，递给他们。","notes":[]},{"n":31,"t":"他们的眼睛开了，这才认出他来。耶稣却从他们眼前消失了。","notes":[]},{"n":32,"t":"他们彼此说：“在路上他和我们说话，给我们讲解圣经的时候，我们的心在我们里面岂不是火热的吗？”","notes":["有古卷没有“在我们里面”。"]},{"n":33,"t":"于是他们立刻起身，回耶路撒冷去，看见十一个使徒和与他们正在一起的人聚集在一处，","notes":[]},{"n":34,"t":"说：“主果然复活了，已经显现给西门看了。”","notes":[]},{"n":35,"t":"于是，两个人把路上所遇到，和耶稣擘饼的时候怎么被他们认出来的事，都述说了一遍。","notes":[]},{"n":36,"t":"正说这些话的时候，耶稣亲自站在他们当中，说：“愿你们平安！”","notes":[],"heads":["向门徒显现"]},{"n":37,"t":"他们却惊慌害怕，以为所看见的是魂。","notes":[]},{"n":38,"t":"耶稣对他们说：“你们为什么惊恐不安？为什么心里起疑惑呢？","notes":[]},{"n":39,"t":"你们看我的手和我的脚，就知道实在是我了。摸摸我，看，因为魂无骨无肉，你们看，我是有的。”","notes":[]},{"n":40,"t":"说了这话，他就把手和脚给他们看。","notes":[]},{"n":41,"t":"他们还在又惊又喜、不敢相信的时候，耶稣对他们说：“你们这里有什么吃的没有？”","notes":[]},{"n":42,"t":"他们给了他一片烤鱼，","notes":[]},{"n":43,"t":"他接过来，在他们面前吃了。","notes":[]},{"n":44,"t":"耶稣对他们说：“这就是我从前和你们同在时所告诉你们的话：摩西的律法、先知的书，和《诗篇》上所记一切指着我的话都必须应验。”","notes":[]},{"n":45,"t":"于是耶稣开他们的心窍，使他们能明白圣经，","notes":[]},{"n":46,"t":"又对他们说：“照经上所写的，基督必受害，第三天从死人中复活，","notes":[]},{"n":47,"t":"并且人们要奉他的名传悔改、使罪得赦的道，从耶路撒冷起直传到万邦。","notes":[]},{"n":48,"t":"你们就是这些事的见证。","notes":[]},{"n":49,"t":"我要将我父所应许的降在你们身上，你们要在城里等候，直到你们领受从上面来的能力。”","notes":[]},{"n":50,"t":"耶稣领他们出来，直到伯大尼附近，就举手给他们祝福。","notes":[],"heads":["耶稣升天"]},{"n":51,"t":"正祝福的时候，他离开他们，被带到天上去了。","notes":[]},{"n":52,"t":"他们就拜他，带着极大的喜乐回耶路撒冷去，","notes":[]},{"n":53,"t":"常在圣殿里称颂神。","notes":[]}]}},"JHN":{"1":{"heading":"道成了肉身","verses":[{"n":1,"t":"太初有道，道与神同在，道就是神。","notes":[]},{"n":2,"t":"这道太初与神同在。","notes":[]},{"n":3,"t":"万物都是藉着他造的，没有一样不是藉着他造的。凡被造的，","notes":[]},{"n":4,"t":"在他里面有生命，这生命就是人的光。","notes":["“没有一样…有生命”：有古卷是“凡被造的，没有一样不是藉着他造的。在他里面有生命”。"]},{"n":5,"t":"光照在黑暗里，黑暗却没有胜过光。","notes":["“黑暗却没有胜过光”或译“黑暗却不接受光”。"]},{"n":6,"t":"有一个人，是从神那里差来的，名叫约翰。","notes":[]},{"n":7,"t":"这人来是为了作见证，是为那光作见证，要使众人藉着他而信。","notes":[]},{"n":8,"t":"他不是那光，而是要为那光作见证。","notes":[]},{"n":9,"t":"那光是真光，来到世上，照亮所有的人。","notes":["本节或译“他是那来到世界照亮所有的人的真光”。"]},{"n":10,"t":"他在世界，世界是藉着他造的，世界却不认识他。","notes":[]},{"n":11,"t":"他来到自己的地方，自己的人并不接纳他。","notes":[]},{"n":12,"t":"凡接纳他的，就是信他名的人，他就赐他们权柄作神的儿女。","notes":[]},{"n":13,"t":"这些人不是从血生的，不是从情欲生的，也不是从人的意愿生的，而是从神生的。","notes":[]},{"n":14,"t":"道成了肉身，住在我们中间，充充满满地有恩典有真理，我们也见过他的荣光，正是父独一儿子的荣光。","notes":["“独一儿子”或译“独生子”； 18节同。"]},{"n":15,"t":"约翰为他作见证，喊着说：“这就是我曾说：‘那在我以后来的先于我，因为在我以前，他已经存在。’”","notes":[]},{"n":16,"t":"从他的丰富里，我们都领受了恩典，而且恩上加恩。","notes":[]},{"n":17,"t":"律法是藉着摩西颁布的；恩典和真理却是由耶稣基督来的。","notes":[]},{"n":18,"t":"从来没有人见过神，只有在父怀里独一的儿子将他表明出来。","notes":[]},{"n":19,"t":"这是约翰的见证：犹太人从耶路撒冷差祭司和利未人到约翰那里去问他：“你是谁？”","notes":[],"heads":["施洗约翰的见证"]},{"n":20,"t":"他就承认，并不隐瞒，承认说：“我不是基督。”","notes":[]},{"n":21,"t":"他们又问他：“那么，你是谁？是以利亚吗？”他说：“我不是。”“是那位先知吗？”他回答：“不是。”","notes":[]},{"n":22,"t":"于是他们对他说：“你到底是谁，好让我们回覆差我们来的人。你说，你自己是谁？”","notes":[]},{"n":23,"t":"他说：“我就是那在旷野呼喊的声音：修直主的道。”正如以赛亚先知所说的。","notes":[]},{"n":24,"t":"那些人是法利赛人差来的。","notes":[]},{"n":25,"t":"他们就问他：“你既不是基督，不是以利亚，也不是那位先知，那么，你为什么施洗呢？”","notes":[]},{"n":26,"t":"约翰回答：“我是用水施洗，但有一位站在你们中间，是你们不认识的，","notes":[]},{"n":27,"t":"就是那在我以后来的，我给他解鞋带也不配。”","notes":[]},{"n":28,"t":"这些事发生在约旦河东边的伯大尼，约翰施洗的地方。","notes":["有古卷是“伯大巴喇”。"]},{"n":29,"t":"第二天，约翰看见耶稣来到他那里，就说：“看哪，神的羔羊，除去世人的罪的！","notes":[],"heads":["神的羔羊"]},{"n":30,"t":"这就是我曾说‘那在我以后来的先于我，因为在我以前，他已经存在’的那一位。","notes":[]},{"n":31,"t":"我先前不认识他，如今我来用水施洗，为要使他显明给以色列人。”","notes":[]},{"n":32,"t":"约翰又作见证说：“我曾看见圣灵仿佛鸽子从天降下，停留在他的身上。","notes":[]},{"n":33,"t":"我先前不认识他，可是那差我来用水施洗的对我说：‘你看见圣灵降下来，停留在谁的身上，谁就是用圣灵施洗的。’","notes":[]},{"n":34,"t":"我看见了，所以作证：这一位是神的儿子。”","notes":[]},{"n":35,"t":"又过了一天，约翰同两个门徒站在那里。","notes":[],"heads":["初次选召门徒"]},{"n":36,"t":"他见耶稣走过，就说：“看哪，神的羔羊！”","notes":[]},{"n":37,"t":"两个门徒听见他的话，就跟从了耶稣。","notes":[]},{"n":38,"t":"耶稣转过身来，看见他们跟着，就问他们说：“你们要什么？”他们对他说：“拉比，你在哪里住？”（“拉比”翻出来就是老师。）","notes":[]},{"n":39,"t":"耶稣说：“你们来看。”他们就去看他在哪里住。这一天他们就跟他同住；那时大约是下午四点钟。","notes":[]},{"n":40,"t":"听了约翰的话而跟从耶稣的那两个人，其中一个是西门．彼得的弟弟安得烈。","notes":[]},{"n":41,"t":"他先找到自己的哥哥西门，对他说：“我们遇见弥赛亚了。”（“弥赛亚”翻出来就是基督。）","notes":[]},{"n":42,"t":"于是安得烈领西门去见耶稣。耶稣看着他，说：“你是约翰的儿子西门，你要称为矶法。”（“矶法”翻出来就是彼得。）","notes":["有古卷是“约拿”。","“矶法”是亚兰语，与希腊语的“彼得”同义，意思是“磐石”。"]},{"n":43,"t":"又过了一天，耶稣想要往加利利去。他找到腓力，就对他说：“来跟从我！”","notes":[],"heads":["呼召腓力和拿但业"]},{"n":44,"t":"这腓力是伯赛大人，是安得烈和彼得的同乡。","notes":[]},{"n":45,"t":"腓力找到拿但业，对他说：“摩西在律法书上所写的，和众先知所记的那一位，我们遇见了，就是约瑟的儿子拿撒勒人耶稣。”","notes":[]},{"n":46,"t":"拿但业对他说：“拿撒勒还能出什么好的吗？”腓力说：“你来看。”","notes":[]},{"n":47,"t":"耶稣看见拿但业向他走来，就论到他说：“看哪，这真是个以色列人！他心里是没有诡诈的。”","notes":[]},{"n":48,"t":"拿但业对耶稣说：“你从哪里认识我的？”耶稣回答他说：“腓力还没有呼唤你，你在无花果树底下，我就看见你了。”","notes":[]},{"n":49,"t":"拿但业回答他：“拉比！你是神的儿子，你是以色列的王。”","notes":[]},{"n":50,"t":"耶稣回答他说：“因为我说在无花果树底下看见你，你就信吗？你将看见比这些更大的事呢！”","notes":[]},{"n":51,"t":"他又说：“我实实在在地告诉你们，你们将要看见天开了，神的使者在人子身上，上去下来。”","notes":[]}]},"2":{"heading":"迦拿的婚礼","verses":[{"n":1,"t":"第三日，在加利利的迦拿有一个婚宴，耶稣的母亲在那里。","notes":[]},{"n":2,"t":"耶稣和他的门徒也被请去赴宴。","notes":[]},{"n":3,"t":"酒用完了，耶稣的母亲对他说：“他们没有酒了。”","notes":[]},{"n":4,"t":"耶稣说：“母亲，我与你何干呢？我的时候还没有到。”","notes":["原文直译“妇人”，在犹太文化中不是一种不尊敬的称呼。"]},{"n":5,"t":"他母亲对用人说：“他告诉你们什么，你们就做吧。”","notes":[]},{"n":6,"t":"照犹太人洁净礼的规矩，有六口石缸摆在那里，每口可以盛两三桶水。","notes":["“桶”：参“度量衡表”。"]},{"n":7,"t":"耶稣对用人说：“把缸倒满水。”他们就倒满了，直到缸口。","notes":[]},{"n":8,"t":"耶稣又说：“现在舀出来，送给宴会总管。”他们就送了去。","notes":[]},{"n":9,"t":"宴会总管尝了那水变的酒，并不知道是哪里来的，只有舀水的用人知道。于是宴会总管叫新郎来，","notes":[]},{"n":10,"t":"对他说：“人家都是先摆上好酒，等客人喝够了才摆上次的，你倒把好酒留到现在！”","notes":[]},{"n":11,"t":"这是耶稣所行的第一个神迹，是在加利利的迦拿行的，显出了他的荣耀来，他的门徒就信他了。","notes":[]},{"n":12,"t":"这事以后，耶稣与他的母亲、兄弟和门徒都下迦百农去，在那里住了不多几天。","notes":["有古卷没有“兄弟”。","有古卷没有“门徒”。"]},{"n":13,"t":"犹太人的逾越节近了，耶稣上耶路撒冷去。","notes":[],"heads":["洁净圣殿"]},{"n":14,"t":"他看见圣殿里有卖牛羊和鸽子的，还有兑换银钱的人坐着，","notes":[]},{"n":15,"t":"耶稣就拿绳子做成鞭子，把所有的，包括牛羊都赶出圣殿，倒出兑换银钱之人的银钱，推翻他们的桌子，","notes":[]},{"n":16,"t":"又对卖鸽子的说：“把这些东西拿走！不要把我父的殿当作买卖的地方。”","notes":[]},{"n":17,"t":"他的门徒就想起经上记着：“我为你的殿心里焦急，如同火烧。”","notes":[]},{"n":18,"t":"因此犹太人问他：“你能显什么神迹给我们看，表明你可以做这些事呢？”","notes":[]},{"n":19,"t":"耶稣回答他们说：“你们拆毁这殿，我三日内要把它重建。”","notes":[]},{"n":20,"t":"犹太人说：“这殿造了四十六年，你三日内就能重建吗？”","notes":[]},{"n":21,"t":"但耶稣所说的殿是指他的身体。","notes":[]},{"n":22,"t":"所以他从死人中复活以后，门徒想起他曾说过这事，就信了圣经和耶稣所说的话。","notes":[]},{"n":23,"t":"耶稣在耶路撒冷过逾越节的时候，有许多人看见他所行的神迹，就信了他的名。","notes":[],"heads":["耶稣洞察人心"]},{"n":24,"t":"耶稣自己却不信任他们，因为他认识所有的人，","notes":[]},{"n":25,"t":"也用不着谁来证明人是怎样的，因为他自己认识人的内心。","notes":[]}]},"3":{"heading":"耶稣和尼哥德慕谈重生","verses":[{"n":1,"t":"有一个法利赛人，名叫尼哥德慕，是犹太人的官。","notes":[]},{"n":2,"t":"这人夜里来见耶稣，对他说：“拉比，我们知道你是由神那里来作老师的；因为你所行的神迹，若没有神同在，无人能行。”","notes":[]},{"n":3,"t":"耶稣回答他说：“我实实在在地告诉你，人若不重生，就不能见神的国。”","notes":["“重生”或译“从上面而生”。"]},{"n":4,"t":"尼哥德慕对他说：“人已经老了，如何能重生呢？岂能再进母腹生出来吗？”","notes":[]},{"n":5,"t":"耶稣回答：“我实实在在地告诉你，人若不是从水和圣灵生的，就不能进神的国。","notes":[]},{"n":6,"t":"从肉身生的就是肉身；从灵生的就是灵。","notes":[]},{"n":7,"t":"我说‘你们必须重生’，你不要惊讶。","notes":[]},{"n":8,"t":"风随着意思吹，你听见风的声音，却不知道是从哪里来，往哪里去；凡从圣灵生的也是如此。”","notes":["原文的“风”与“灵”同字。"]},{"n":9,"t":"尼哥德慕问他：“怎么能有这些事呢？”","notes":[]},{"n":10,"t":"耶稣回答，对他说：“你是以色列人的老师，还不明白这些事吗？","notes":[]},{"n":11,"t":"我实实在在地告诉你，我们所说的是我们知道的，我们所见证的是我们见过的，你们却不领受我们的见证。","notes":[]},{"n":12,"t":"我对你们说地上的事，你们尚且不信，若对你们说天上的事，如何能信呢？","notes":[]},{"n":13,"t":"除了从天降下的人子，没有人升过天。","notes":["有古卷加“仍旧在天”。"]},{"n":14,"t":"摩西在旷野怎样举蛇，人子也必须照样被举起来，","notes":[]},{"n":15,"t":"要使一切信他的人都得永生。","notes":[]},{"n":16,"t":"“神爱世人，甚至将他独一的儿子赐给他们，叫一切信他的人不致灭亡，反得永生。","notes":["“他独一的儿子”或译“他的独生子”；18节同。"]},{"n":17,"t":"因为神差他的儿子到世上来，不是要定世人的罪，而是要使世人因他得救。","notes":["“定世人的罪”或译“审判世人”；18、19节同。"]},{"n":18,"t":"信他的人不被定罪；不信的人已经被定罪了，因为他不信神独一儿子的名。","notes":[]},{"n":19,"t":"光来到世上，世人因自己的行为是恶的，不爱光，倒爱黑暗，这就定了他们的罪。","notes":[]},{"n":20,"t":"凡作恶的人都恨恶光，不来接近光，恐怕他的行为被暴露。","notes":[]},{"n":21,"t":"但实行真理的人就来接近光，为要显明他的行为是靠神而行的。”","notes":[]},{"n":22,"t":"这些事以后，耶稣和门徒到了犹太地区，在那里他和他们同住，并且施洗。","notes":[],"heads":["耶稣和施洗约翰"]},{"n":23,"t":"约翰也在靠近撒冷的哀嫩施洗，因为那里水多，众人都去受洗。","notes":[]},{"n":24,"t":"那时约翰还没有下在监里。","notes":[]},{"n":25,"t":"约翰的门徒和一个犹太人辩论洁净的礼仪，","notes":[]},{"n":26,"t":"就来见约翰，对他说：“拉比，从前同你在约旦河的东边，你所见证的那位，你看，他在施洗，众人都到他那里去了。”","notes":[]},{"n":27,"t":"约翰回答说：“若不是从天上赐的，人就不能得到什么。","notes":[]},{"n":28,"t":"你们自己可以为我作见证，我曾说，我不是基督，只是奉差遣在他前面开路的。","notes":[]},{"n":29,"t":"娶新娘的是新郎；新郎的朋友站在一旁听，一听见新郎的声音就欢喜快乐。因此，我这喜乐得以满足了。","notes":[]},{"n":30,"t":"他必兴旺；我必衰微。”","notes":[]},{"n":31,"t":"“从上头来的是在万有之上；出于地的是属于地，他所说的也是属于地。从天上来的是在万有之上。","notes":[],"heads":["从天上来的那一位"]},{"n":32,"t":"他把所见所闻的见证出来，只是没有人领受他的见证。","notes":[]},{"n":33,"t":"那领受他见证的，就印证神是真实的。","notes":[]},{"n":34,"t":"神所差来的说神的话，因为神所赐给他的圣灵是没有限量的。","notes":[]},{"n":35,"t":"父爱子，已把万有交在他手里。","notes":[]},{"n":36,"t":"信子的人有永生；不信子的人得不到永生，而且神的愤怒常在他身上。”","notes":[]}]},"4":{"heading":"耶稣和撒玛利亚妇人谈道","verses":[{"n":1,"t":"耶稣知道法利赛人听见他收门徒和施洗比约翰还多， （","notes":["有古卷是“主”。"]},{"n":2,"t":"其实不是耶稣亲自施洗，而是他的门徒施洗，）","notes":[]},{"n":3,"t":"他就离开犹太，又回加利利去。","notes":[]},{"n":4,"t":"他必须经过撒玛利亚，","notes":[]},{"n":5,"t":"于是到了撒玛利亚的一座城，名叫叙加，靠近雅各给他儿子约瑟的那块地。","notes":[]},{"n":6,"t":"雅各井就在那里；耶稣因旅途疲乏，坐在井旁。那时约是正午。","notes":[]},{"n":7,"t":"有一个撒玛利亚妇人来打水。耶稣对她说：“请给我水喝。”","notes":[]},{"n":8,"t":"因为那时门徒进城买食物去了。","notes":[]},{"n":9,"t":"撒玛利亚妇人对他说：“你是犹太人，怎么向我一个撒玛利亚女人要水喝呢？”因为犹太人和撒玛利亚人没有来往。","notes":[]},{"n":10,"t":"耶稣回答她说：“你若知道神的恩赐，和对你说‘请给我水喝’的是谁，你早就会求他，他也早就会给了你活水。”","notes":[]},{"n":11,"t":"妇人对耶稣说：“先生，你没有打水的器具，井又深，哪里去取活水呢？","notes":[]},{"n":12,"t":"我们的祖宗雅各把这井留给我们，他自己和儿女以及牲畜都喝这井里的水，难道你比他还大吗？”","notes":[]},{"n":13,"t":"耶稣回答，对她说：“凡喝这水的，还要再渴；","notes":[]},{"n":14,"t":"谁喝我所赐的水，就永远不渴。我所赐的水要在他里面成为泉源，直涌到永生。”","notes":[]},{"n":15,"t":"妇人对他说：“先生，请把这水赐给我，使我不渴，也不用到这里来打水。”","notes":[]},{"n":16,"t":"耶稣对她说：“你去，叫你的丈夫，再到这里来。”","notes":[]},{"n":17,"t":"妇人回答，对耶稣说：“我没有丈夫。”耶稣说：“你说没有丈夫是对的。","notes":[]},{"n":18,"t":"你已经有过五个丈夫，你现在有的并不是你的丈夫。你这话是真的。”","notes":[]},{"n":19,"t":"妇人对他说：“先生，我看你是一位先知。","notes":[]},{"n":20,"t":"我们的祖宗在这山上敬拜神，你们倒说，应当敬拜的地方是在耶路撒冷。”","notes":[]},{"n":21,"t":"耶稣对她说：“妇人，你要信我。时候将到，你们敬拜父，既不在这山上，也不在耶路撒冷。","notes":[]},{"n":22,"t":"你们所敬拜的，你们不知道；我们所敬拜的，我们知道，因为救恩是从犹太人出来的。","notes":[]},{"n":23,"t":"时候将到，现在就是了，那真正敬拜父的，要用心灵和诚实敬拜他，因为父要这样的人敬拜他。","notes":[]},{"n":24,"t":"神是灵，所以敬拜他的必须用心灵和诚实敬拜他。”","notes":[]},{"n":25,"t":"妇人对他说：“我知道弥赛亚—就是那称为基督的—要来；他来了，会把一切的事都告诉我们。”","notes":[]},{"n":26,"t":"耶稣对她说：“我就是，正在跟你说话呢！”","notes":[]},{"n":27,"t":"正在这时，门徒回来了。他们对耶稣正在和一个妇人说话感到惊讶，可是没有人说：“你要什么？”或说：“你为什么和她说话？”","notes":[]},{"n":28,"t":"那妇人留下水罐，往城里去，对众人说：","notes":[]},{"n":29,"t":"“你们来看！有一个人把我素来所做的一切事都说了出来，难道这个人就是基督吗？”","notes":[]},{"n":30,"t":"他们就出城，来到耶稣那里。","notes":[]},{"n":31,"t":"就在这个时候，门徒求耶稣说：“拉比，请吃吧。”","notes":[]},{"n":32,"t":"耶稣对他们说：“我有食物吃，是你们不知道的。”","notes":[]},{"n":33,"t":"门徒就彼此说：“难道有人拿什么给他吃了吗？”","notes":[]},{"n":34,"t":"耶稣对他们说：“我的食物就是要遵行差我来那位的旨意，完成他的工作。","notes":[]},{"n":35,"t":"你们不是说‘到收割的时候还有四个月’吗？我告诉你们，举目向田观看，庄稼熟了，可以收割了。","notes":[]},{"n":36,"t":"收割的人已经得工钱，为永生储存五谷，使撒种的和收割的一同快乐。","notes":["“庄稼熟了…已经得工钱”：有古卷是“庄稼已经熟了…得工钱”。"]},{"n":37,"t":"‘那人撒种，这人收割’，这话可见是真的。","notes":[]},{"n":38,"t":"我差你们去收你们所没有辛劳的；别人辛劳，你们享受他们辛劳的成果。”","notes":[]},{"n":39,"t":"那城里有好些撒玛利亚人信了耶稣，因为那妇人作见证，说：“他把我素来所做的一切事都说了出来。”","notes":[]},{"n":40,"t":"于是撒玛利亚人来见耶稣，求他在他们那里住下，他就在那里住了两天。","notes":[]},{"n":41,"t":"因为耶稣的话，信的人就更多了。","notes":[]},{"n":42,"t":"他们对那妇人说：“现在我们信，不再是因为你的话，而是我们亲自听见了，知道这人真是世界的救主。”","notes":[]},{"n":43,"t":"过了那两天，耶稣离开那地方，往加利利去。","notes":[],"heads":["耶稣治好大臣的儿子"]},{"n":44,"t":"因为耶稣自己作过见证说：“先知在自己的家乡是没有人尊敬的。”","notes":[]},{"n":45,"t":"到了加利利，加利利人都欢迎他，因为他们也上耶路撒冷去过节，曾经看过他在节期间所做的一切事。","notes":[]},{"n":46,"t":"耶稣又到了加利利的迦拿，就是他从前变水为酒的地方。有一个大臣，他的儿子在迦百农病了。","notes":[]},{"n":47,"t":"他听见耶稣从犹太到了加利利，就来见他，求他下去医治他的儿子，因为他儿子快要死了。","notes":[]},{"n":48,"t":"耶稣对他说：“若不看见神迹奇事，你们总是不信。”","notes":[]},{"n":49,"t":"那大臣对他说：“先生，求你趁着我的孩子还没有死就下去吧。”","notes":[]},{"n":50,"t":"耶稣对他说：“回去吧，你的儿子会活！”那人信耶稣所说的话，就回去了。","notes":[]},{"n":51,"t":"正下去的时候，他的仆人迎面而来，说他的儿子活了。","notes":[]},{"n":52,"t":"他就问什么时候见好的。他们对他说：“昨天下午一点钟热就退了。”","notes":[]},{"n":53,"t":"他就知道这正是耶稣对他说“你的儿子会活”的时候；他自己和全家就都信了。","notes":[]},{"n":54,"t":"这是耶稣从犹太回到加利利后所行的第二个神迹。","notes":[]}]},"5":{"heading":"在毕士大池边治病","verses":[{"n":1,"t":"这些事以后，到了犹太人的一个节期，耶稣上耶路撒冷去。","notes":[]},{"n":2,"t":"在耶路撒冷，靠近羊门有一个池子，希伯来话叫毕士大，旁边有五个柱廊；","notes":["有古卷是“伯赛大”。"]},{"n":3,"t":"里面躺着许多病人，有失明的、瘸腿的、瘫痪的。","notes":["有古卷加“等候水动，4 因为有天使按时下池子搅动那水，水动之后，先下水的人无论患什么病都能得痊愈。”"]},{"n":5,"t":"在那里有一个人，病了三十八年。","notes":[]},{"n":6,"t":"耶稣看见他躺着，知道他病了很久，就问他：“你要痊愈吗？”","notes":[]},{"n":7,"t":"病人回答他：“先生，水动的时候，没有人把我放在池子里；我正要去的时候，别人比我先下去了。”","notes":[]},{"n":8,"t":"耶稣对他说：“起来，拿起你的褥子走吧！”","notes":[]},{"n":9,"t":"那人立刻痊愈，就拿起自己的褥子走了。那天是安息日，","notes":[]},{"n":10,"t":"所以犹太人对那被治好了的人说：“今天是安息日，你拿褥子是不合法的。”","notes":[]},{"n":11,"t":"他却回答他们：“那使我痊愈的人对我说：‘拿起你的褥子走吧！’”","notes":[]},{"n":12,"t":"他们问他：“对你说‘拿起褥子走’的是什么人？”","notes":[]},{"n":13,"t":"那治好了的人不知道那人是谁，因为那里人很多，耶稣已经躲开了。","notes":[]},{"n":14,"t":"后来耶稣在圣殿里找到他，对他说：“你已经痊愈了，不要再犯罪，免得你的遭遇更坏。”","notes":[]},{"n":15,"t":"那人就去告诉犹太人，使他痊愈的是耶稣。","notes":[]},{"n":16,"t":"所以犹太人迫害耶稣，因为他在安息日做了这些事。","notes":[]},{"n":17,"t":"耶稣就回答他们：“我父做事直到如今，我也做事。”","notes":[]},{"n":18,"t":"为了这缘故，犹太人越发想要杀他，因为他不但犯了安息日，而且称神为他的父，把自己和神看为同等。","notes":[]},{"n":19,"t":"于是耶稣回答，对他们说：“我实实在在地告诉你们，子凭着自己不能做什么，惟有看见父所做的，他才做；父所做的事，子也照样做。","notes":[],"heads":["圣子的权柄"]},{"n":20,"t":"父爱子，将自己所做的一切事指示给他看，还要将比这更大的事给他看，使你们惊讶。","notes":[]},{"n":21,"t":"父怎样叫死人复活，赐他们生命，子也照样随自己的意愿赐人生命。","notes":[]},{"n":22,"t":"父不审判任何人，而是把审判的事全交给子，","notes":[]},{"n":23,"t":"为要使人都尊敬子，如同尊敬父一样。不尊敬子的，就是不尊敬差子来的父。","notes":[]},{"n":24,"t":"“我实实在在地告诉你们，那听我话又信差我来那位的，就有永生，不至于被定罪，而是已经出死入生了。","notes":[]},{"n":25,"t":"我实实在在地告诉你们，时候将到，现在就是了，死人要听见神儿子的声音，听见的人就要活了。","notes":[]},{"n":26,"t":"因为父怎样自己里面有生命，也照样赐给他儿子自己里面有生命，","notes":[]},{"n":27,"t":"并且赐给他施行审判的权柄，因为他是人子。","notes":[]},{"n":28,"t":"你们不要对这事感到惊讶，因为时候将到，凡在坟墓里的，都要听见他的声音，","notes":[]},{"n":29,"t":"并且要出来：行善的，复活得生命；作恶的，复活被定罪。","notes":[]},{"n":30,"t":"“我凭着自己不能做什么。我怎么听见就怎么审判，而我的审判是公平的，因为我不寻求自己的意愿，只寻求差我来那位的旨意。”","notes":[]},{"n":31,"t":"“我若为自己作见证，我的见证就不真。","notes":[],"heads":["为耶稣作见证"]},{"n":32,"t":"另有一位为我作见证，我也知道他为我作的见证是真的。","notes":[]},{"n":33,"t":"你们曾差人到约翰那里，他为真理作过见证。","notes":[]},{"n":34,"t":"其实，我所受的见证不是从人来的；然而，我说这些话是为了使你们得救。","notes":[]},{"n":35,"t":"约翰是点亮的明灯，你们情愿因他的光欢欣一时。","notes":[]},{"n":36,"t":"但我有比约翰更大的见证：父交给我去完成的工作，就是我正在做的，为我作证是父差遣了我。","notes":[]},{"n":37,"t":"那差我来的父也为我作了见证。你们从来没有听见他的声音，也没有看见他的形像。","notes":[]},{"n":38,"t":"你们并没有他的道存在心里，因为你们不信他所差来的那一位。","notes":[]},{"n":39,"t":"你们查考圣经，因你们以为其中有永生；而这经正是为我作见证的。","notes":[]},{"n":40,"t":"然而，你们不肯到我这里来得生命。","notes":[]},{"n":41,"t":"“我不接受从人来的荣耀，","notes":[]},{"n":42,"t":"但我知道，你们没有爱神的心。","notes":[]},{"n":43,"t":"我奉我父的名来了，你们并不接纳我；若有别人奉自己的名来，你们倒会接纳他。","notes":[]},{"n":44,"t":"你们互相受荣耀，却不寻求从独一神来的荣耀，怎能信我呢？","notes":[]},{"n":45,"t":"不要以为我会在父面前告你们；有一位告你们的，就是你们所仰望的摩西。","notes":[]},{"n":46,"t":"如果你们信摩西，也会信我，因为他写过关于我的事。","notes":[]},{"n":47,"t":"你们若不信他的书，怎能信我的话呢？”","notes":[]}]},"6":{"heading":"耶稣使五千人吃饱","verses":[{"n":1,"t":"这些事以后，耶稣渡过加利利海，就是提比哩亚海。","notes":[]},{"n":2,"t":"有一大群人因为看见他在病人身上所行的神迹，就跟随他。","notes":[]},{"n":3,"t":"耶稣上了山，和门徒一同坐在那里。","notes":[]},{"n":4,"t":"那时犹太人的逾越节近了。","notes":[]},{"n":5,"t":"耶稣举目看见一大群人来，就对腓力说：“我们到哪里去买饼给这些人吃呢？”","notes":[]},{"n":6,"t":"他说这话是要考验腓力，他自己原知道要怎样做。","notes":[]},{"n":7,"t":"腓力回答他：“就是两百个银币的饼也不够给他们每人吃一点点。”","notes":[]},{"n":8,"t":"有一个门徒，就是西门．彼得的弟弟安得烈，对耶稣说：","notes":[]},{"n":9,"t":"“这里有一个孩子，带着五个大麦饼和两条鱼，但是分给这么多人还算什么呢？”","notes":[]},{"n":10,"t":"耶稣说：“你们叫大家坐下。”那地方的草多，人们就坐下，男人的数目约有五千。","notes":[]},{"n":11,"t":"耶稣拿起饼来，祝谢了，就分给坐着的人，也同样分了鱼，都照他们所要的来分。","notes":[]},{"n":12,"t":"他们吃饱后，耶稣对门徒说：“把剩下的碎屑收拾起来，免得糟蹋了。”","notes":[]},{"n":13,"t":"他们就把那五个大麦饼的碎屑，就是大家吃剩的，收拾起来，装满了十二个篮子。","notes":[]},{"n":14,"t":"人们看见耶稣所行的神迹，就说：“这真是那要到世上来的先知！”","notes":[]},{"n":15,"t":"耶稣知道他们要来强迫他作王，就独自又退到山上去了。","notes":[]},{"n":16,"t":"到了晚上，他的门徒下到海边，","notes":[],"heads":["耶稣在海上行走"]},{"n":17,"t":"上了船，要过海往迦百农去。天已经黑了，耶稣还没有来到他们那里。","notes":[]},{"n":18,"t":"忽然狂风大作，海浪翻腾。","notes":[]},{"n":19,"t":"门徒摇橹，约行了十里多，看见耶稣在海面上走，渐渐靠近了船，他们就害怕。","notes":["“十里多”：即五、六公里；原文即“二十五或三十斯他迪”，古希腊长度单位，参“度量衡表”。"]},{"n":20,"t":"耶稣对他们说：“是我，不要怕！”","notes":[]},{"n":21,"t":"门徒就欣然接他上船，船立刻到了他们所要去的地方。","notes":[]},{"n":22,"t":"第二天，留在海的对岸的众人发觉那里原来只有一条小船，而且耶稣没有同他的门徒上船，是门徒自己去的。","notes":[],"heads":["耶稣是生命的粮"]},{"n":23,"t":"另外有几条从提比哩亚来的小船，却停靠在主祝谢后给他们吃饼的地方附近。","notes":[]},{"n":24,"t":"这时众人见耶稣和门徒都不在那里，就上了船，往迦百农去找耶稣。","notes":[]},{"n":25,"t":"他们在海的对岸找到他后，对他说：“拉比，你几时到这里来的？”","notes":[]},{"n":26,"t":"耶稣回答他们说：“我实实在在地告诉你们，你们找我，并不是因见了神迹，而是因吃饼吃饱了。","notes":[]},{"n":27,"t":"不要为那会坏的食物操劳，而要为那存到永生的食物操劳。这食物是人子要赐给你们的，因为父神已印证了。”","notes":[]},{"n":28,"t":"于是他们问他：“我们该做什么才算是做神的工作呢？”","notes":[]},{"n":29,"t":"耶稣回答，对他们说：“信神所差来的，这就是神的工作。”","notes":[]},{"n":30,"t":"于是他们对他说：“你行什么神迹，好让我们看见而信你呢？你到底要做什么呢？","notes":[]},{"n":31,"t":"我们的祖宗在旷野吃过吗哪，如经上写着：‘他从天上赐下粮食来给他们吃。’”","notes":[]},{"n":32,"t":"于是耶稣对他们说：“我实实在在地告诉你们，那从天上来的粮不是摩西赐给你们的，那从天上来的真粮是我父赐给你们的。","notes":[]},{"n":33,"t":"因为神的粮就是那位从天上降下来，并且赐生命给世界的。”","notes":[]},{"n":34,"t":"于是他们对他说：“主啊，请常常把这粮赐给我们！”","notes":[]},{"n":35,"t":"耶稣对他们说：“我就是生命的粮。到我这里来的，绝不饥饿；信我的，永不干渴。","notes":[]},{"n":36,"t":"可是，我告诉过你们，你们已经看见我，还是不信。","notes":["有古卷没有“我”。"]},{"n":37,"t":"凡父所赐给我的人，必到我这里来；到我这里来的，我总不丢弃他。","notes":[]},{"n":38,"t":"因为我从天上降下来，不是要按自己的意愿行，而是要遵行差我来那位的旨意。","notes":[]},{"n":39,"t":"差我来那位的旨意就是：他所赐给我的，要我一个也不失落，并且在末日使他复活。","notes":[]},{"n":40,"t":"因为我父的旨意是要使每一个见了子而信的人得永生，并且在末日我要使他复活。”","notes":[]},{"n":41,"t":"犹太人因为耶稣说“我是从天上降下来的粮”，就私下议论他，","notes":[]},{"n":42,"t":"说：“这不是约瑟的儿子耶稣吗？我们岂不认得他的父母吗？现在他怎么说‘我是从天上降下来的’呢？”","notes":[]},{"n":43,"t":"耶稣回答，对他们说：“你们不要彼此私下议论。","notes":[]},{"n":44,"t":"若不是差我来的父吸引人，就没有人能到我这里来；到我这里来的，在末日我要使他复活。","notes":[]},{"n":45,"t":"在先知书上写着：‘他们都要蒙神教导。’凡听了父的教导而学习的，都到我这里来。","notes":[]},{"n":46,"t":"这不是说有人看见过父，惟独从神来的，他才看见过父。","notes":[]},{"n":47,"t":"我实实在在地告诉你们，信的人有永生。","notes":[]},{"n":48,"t":"我就是生命的粮。","notes":[]},{"n":49,"t":"你们的祖宗在旷野吃过吗哪，还是死了。","notes":[]},{"n":50,"t":"这是从天上降下来的粮，使人吃了就不死。","notes":[]},{"n":51,"t":"我就是从天上降下来生命的粮；人若吃这粮，必永远活着。我为世人的生命所赐下的粮就是我的肉。”","notes":[]},{"n":52,"t":"因此，犹太人彼此争论说：“这个人怎能把他的肉给我们吃呢？”","notes":[]},{"n":53,"t":"耶稣对他们说：“我实实在在地告诉你们，你们若不吃人子的肉，不喝人子的血，在你们里面就没有生命。","notes":[]},{"n":54,"t":"吃我肉、喝我血的人就有永生，并且在末日我要使他复活。","notes":[]},{"n":55,"t":"我的肉是真正可吃的；我的血是真正可喝的。","notes":[]},{"n":56,"t":"吃我肉、喝我血的人常在我里面，我也常在他里面。","notes":[]},{"n":57,"t":"永生的父怎样差我来，我又怎样因父活着，照样，吃我肉的人也要因我活着。","notes":[]},{"n":58,"t":"这是从天上降下来的粮，不像你们的祖宗吃过吗哪还是死了；吃这粮的人将永远活着。”","notes":[]},{"n":59,"t":"这些话是耶稣在迦百农会堂里教导人的时候说的。","notes":[]},{"n":60,"t":"他的门徒中有好些人听见了，就说：“这话很难，谁听得进呢？”","notes":[],"heads":["永生的话"]},{"n":61,"t":"耶稣心里知道门徒为这话私下议论，就对他们说：“这话成了你们的绊脚石吗？","notes":[]},{"n":62,"t":"如果你们看见人子升到他原来所在之处，会怎么样呢？","notes":[]},{"n":63,"t":"圣灵赐人生命，肉体毫无用处。我对你们所说的话就是灵，就是生命。","notes":[]},{"n":64,"t":"可是你们中间有些人不信。”耶稣起初就知道哪些人不信他，哪一个要出卖他。","notes":[]},{"n":65,"t":"于是耶稣说：“所以，我对你们说过，若不是蒙我父的恩赐，没有人能到我这里来。”","notes":[]},{"n":66,"t":"从此，他门徒中有很多退却了，不再和他同行。","notes":[]},{"n":67,"t":"耶稣就对那十二使徒说：“你们也要离开吗？”","notes":[]},{"n":68,"t":"西门．彼得回答他：“主啊，你有永生之道，我们还跟从谁呢？","notes":[]},{"n":69,"t":"我们已经信了，又知道你是神的圣者。”","notes":[]},{"n":70,"t":"耶稣回答他们：“我不是拣选了你们十二个吗？但你们中间有一个是魔鬼。”","notes":[]},{"n":71,"t":"耶稣这话是指着要出卖他的加略人西门的儿子犹大说的；他本是十二使徒里的一个。","notes":[]}]},"7":{"heading":"耶稣的兄弟们不信","verses":[{"n":1,"t":"这些事以后，耶稣周游加利利，不愿在犹太往来，因为犹太人想要杀他。","notes":[]},{"n":2,"t":"这时犹太人的住棚节近了。","notes":[]},{"n":3,"t":"耶稣的兄弟们对他说：“你离开这里上犹太去吧，好让你的门徒也看见你所做的事。","notes":[]},{"n":4,"t":"因为人要扬名，没有在隐秘的地方行事的，如果你要做这些事，该把自己显明给世人看。”","notes":[]},{"n":5,"t":"原来连他的兄弟们也不信他。","notes":[]},{"n":6,"t":"于是耶稣对他们说：“我的时机还没有到，你们的时机却随时都有。","notes":[]},{"n":7,"t":"世人不会恨你们，却是恨我，因为我指证他们的行为是恶的。","notes":[]},{"n":8,"t":"你们上去过节吧！我现在不上去过这节，因为我的时机还没有成熟。”","notes":["有古卷是“我现在还没有上去过这节”。"]},{"n":9,"t":"耶稣说了这些话，仍然留在加利利。","notes":[]},{"n":10,"t":"但他的兄弟们上去过节以后，他也上去，不是公开去，却似乎是秘密地去的。","notes":["有古卷没有“似乎”。"],"heads":["耶稣过住棚节"]},{"n":11,"t":"节期间，犹太人寻找耶稣，说：“他在哪里？”","notes":[]},{"n":12,"t":"人群中有许多人对他议论纷纷，另有的说：“他是好人。”有的说：“不，他是迷惑群众的。”","notes":[]},{"n":13,"t":"可是没有人公开谈论他，因为他们怕犹太人。","notes":[]},{"n":14,"t":"节期已过了一半，耶稣上圣殿去教导人。","notes":[]},{"n":15,"t":"犹太人惊讶地说：“这个人没有学过，怎么那样熟悉经典呢？”","notes":[]},{"n":16,"t":"于是耶稣回答他们，说：“我的教导不是我自己的，而是差我来那位的。","notes":[]},{"n":17,"t":"人若立志要遵行神的旨意，就会知道这教导究竟是出于神，还是我凭着自己说的。","notes":[]},{"n":18,"t":"凭着自己说的人是寻求自己的荣耀；但那寻求差他来那位的荣耀的人，他是真诚的，在他心里没有不义。","notes":[]},{"n":19,"t":"摩西不是传了律法给你们吗？你们却没有一个人守律法。为什么想要杀我呢？”","notes":[]},{"n":20,"t":"众人回答：“你是被鬼附了！谁想要杀你呢？”","notes":[]},{"n":21,"t":"耶稣回答，对他们说：“我做了一件事，你们都惊讶。","notes":[]},{"n":22,"t":"摩西传割礼给你们（其实割礼不是从摩西开始，而是从列祖开始的），你们就在安息日给人行割礼。","notes":[]},{"n":23,"t":"人若在安息日受割礼，是为了不违背摩西的律法，我在安息日使一个人痊愈了，你们就向我发怒吗？","notes":[]},{"n":24,"t":"不要凭外表断定是非，总要按公平断定是非。”","notes":[]},{"n":25,"t":"于是耶路撒冷人中有的说：“这个人不是他们想要杀的吗？","notes":[],"heads":["这是基督吗？"]},{"n":26,"t":"你看，他还公开讲道，他们也不对他说什么。难道官长真的认为这是基督吗？","notes":[]},{"n":27,"t":"然而，我们知道这个人从哪里来；可是基督来的时候，没有人知道他从哪里来。”","notes":[]},{"n":28,"t":"那时，耶稣在圣殿里教导人，喊着说：“你们认识我，也知道我从哪里来；我并不是凭着自己来的。但差我来的那位是真实的，你们不认识他。","notes":[]},{"n":29,"t":"我却认识他，因为我从他那里来，是他差遣了我。”","notes":[]},{"n":30,"t":"于是他们想要捉拿耶稣，只是没有人下手，因为他的时候还没有到。","notes":[]},{"n":31,"t":"但人群中有好些人信他，他们说：“基督来的时候，他所行的神迹难道会比这人行的更多吗？”","notes":[]},{"n":32,"t":"法利赛人听见群众对耶稣这样议论纷纷，祭司长和法利赛人就打发圣殿警卫去捉拿他。","notes":[],"heads":["祭司长差人捉拿耶稣"]},{"n":33,"t":"于是耶稣说：“我跟你们在一起的时候不会太久了，我要回到那差我来的那里去。","notes":[]},{"n":34,"t":"你们要找我，却找不到；我所在的地方，你们不能去。”","notes":[]},{"n":35,"t":"于是犹太人彼此问：“这人要往哪里去，使我们找不到他呢？难道他要往散居在希腊的犹太人那里去教导希腊人吗？","notes":[]},{"n":36,"t":"他说‘你们要找我，却找不到；我所在的地方，你们不能去’，这话是什么意思呢？”","notes":[]},{"n":37,"t":"节期的最后一天，就是最隆重的一天，耶稣站着，喊着说：“人若渴了，到我这里来喝！","notes":[],"heads":["活水的江河"]},{"n":38,"t":"信我的人，就如经上所说：‘从他腹中将流出活水的江河来。’”","notes":[]},{"n":39,"t":"耶稣这话是指信他的人要受圣灵说的；那时还没有赐下圣灵，因为耶稣还没有得到荣耀。","notes":[]},{"n":40,"t":"众人听见这些话，有的说：“这真是那先知。”","notes":[],"heads":["众人因耶稣而分裂"]},{"n":41,"t":"另有的说：“这是基督。”但也有的说：“难道基督是出自加利利吗？","notes":[]},{"n":42,"t":"经上不是说‘基督是大卫的后裔，出自大卫的本乡伯利恒’吗？”","notes":[]},{"n":43,"t":"于是众人因耶稣而分裂了。","notes":[]},{"n":44,"t":"其中有人要捉拿他，只是没有人下手。","notes":[]},{"n":45,"t":"警卫们回到祭司长和法利赛人那里。他们对警卫说：“你们为什么没有带他来呢？”","notes":[],"heads":["犹太领袖的不信"]},{"n":46,"t":"警卫回答：“从来没有像他这样说话的！”","notes":[]},{"n":47,"t":"于是法利赛人说：“你们也受了迷惑吗？","notes":[]},{"n":48,"t":"难道官长或法利赛人中有信他的吗？","notes":[]},{"n":49,"t":"但这些不明白律法的众人是被诅咒的！”","notes":[]},{"n":50,"t":"其中有尼哥德慕，就是从前去见过耶稣的，对他们说：","notes":[]},{"n":51,"t":"“不先听本人的口供，查明他所做的事，难道我们的律法还定他的罪吗？”","notes":[]},{"n":52,"t":"他们回答他说：“你也是出自加利利吗？你去查考就知道，加利利是不出先知的。”","notes":[]},{"n":53,"t":"〔 于是各人都回家去了，","notes":[],"heads":["犯奸淫时被捉的女人"]}]},"8":{"heading":"耶稣是世界的光","verses":[{"n":1,"t":"耶稣却到橄榄山去。","notes":[]},{"n":2,"t":"清早，他又回到圣殿里。众百姓都到他那里去，他就坐下，教导他们。","notes":[]},{"n":3,"t":"文士和法利赛人带着一个犯奸淫时被捉的女人来，叫她站在当中，","notes":[]},{"n":4,"t":"然后对耶稣说：“老师，这女人是正在犯奸淫的时候被捉到的。","notes":[]},{"n":5,"t":"摩西在律法书上命令我们把这样的女人用石头打死。那么，你怎么说呢？”","notes":[]},{"n":6,"t":"他们说这话是要试探耶稣，要抓到控告他的把柄。耶稣却弯下腰，用指头在地上写字。","notes":[]},{"n":7,"t":"他们还是不住地问他，耶稣就直起腰来，对他们说：“你们中间谁没有罪，谁就先拿石头打她！”","notes":[]},{"n":8,"t":"于是他又弯着腰，用指头在地上写字。","notes":[]},{"n":9,"t":"他们听见这话，从老的开始，一个一个都走开了，只剩下耶稣一人和那仍然站在中间的女人。","notes":[]},{"n":10,"t":"耶稣就直起腰来，对她说：“妇人，那些人在哪里呢？没有任何人定你的罪吗？”","notes":[]},{"n":11,"t":"她说：“主啊，没有。”耶稣说：“我也不定你的罪。去吧！从今以后不要再犯罪了。”〕","notes":["最早的古卷没有括弧内7．53和8．1-11这段经文；有古卷把它放在约翰福音21．24之后；另有古卷把它放在路加福音21．38之后。"]},{"n":12,"t":"耶稣又对众人说：“我就是世界的光。跟从我的，必不在黑暗里走，却要得着生命的光。”","notes":[]},{"n":13,"t":"法利赛人对他说：“你是为自己作见证，你的见证不真。”","notes":[]},{"n":14,"t":"耶稣回答他们，对他们说：“即使我为自己作见证，我的见证还是真的，因为我知道我从哪里来，到哪里去。你们却不知道我从哪里来，到哪里去。","notes":[]},{"n":15,"t":"你们是以人的标准来判断人，我不判断任何人。","notes":[]},{"n":16,"t":"即使我判断人，我的判断也是真确的，因为不是我独自在判断，而是差我来的父与我一同判断。","notes":[]},{"n":17,"t":"你们的律法也记着说：‘两个人的见证才算为真’。","notes":[]},{"n":18,"t":"我是为自己作见证，还有差我来的父也为我作见证。”","notes":[]},{"n":19,"t":"于是他们问他：“你的父在哪里？”耶稣回答：“你们不认识我，也不认识我的父；若是认识我，也会认识我的父。”","notes":[]},{"n":20,"t":"这些话是耶稣在圣殿的银库房里教导人的时候说的。当时没有人捉拿他，因为他的时候还没有到。","notes":[]},{"n":21,"t":"于是耶稣又对他们说：“我去了，你们会找我，而你们会死在自己的罪中；我所去的地方，你们不能去。”","notes":[],"heads":["我所去的地方你们不能去"]},{"n":22,"t":"犹太人说：“他说‘我所去的地方，你们不能去’，难道他要自杀吗？”","notes":[]},{"n":23,"t":"耶稣对他们说：“你们是从下面来的，我是从上面来的；你们是属这世界的，我不是属这世界的。","notes":[]},{"n":24,"t":"所以我对你们说，你们会死在自己的罪中，你们若不信我就是那位，就会死在自己的罪中。”","notes":[]},{"n":25,"t":"他们就问他：“你到底是谁？”耶稣对他们说：“我从起初就告诉你们了。","notes":[]},{"n":26,"t":"我有许多事要讲论你们，判断你们；但差我来的那位是真实的，我从他那里所听见的，就告诉世人。”","notes":[]},{"n":27,"t":"他们不明白耶稣是对他们讲父的事。","notes":[]},{"n":28,"t":"所以耶稣说：“你们举起人子以后就会知道我就是那位了，并且知道我没有一件事是凭着自己做的。我说这些话是照着父所教导我的。","notes":[]},{"n":29,"t":"差我来的那位与我同在；他没有撇下我独自一人，因为我一直行他所喜悦的事。”","notes":[]},{"n":30,"t":"耶稣说这些话的时候，有许多人信了他。","notes":[]},{"n":31,"t":"耶稣对信他的犹太人说：“你们若继续遵守我的道，就真是我的门徒了。","notes":[],"heads":["真理使你们自由"]},{"n":32,"t":"你们将认识真理，真理会使你们自由。”","notes":[]},{"n":33,"t":"他们回答他：“我们是亚伯拉罕的后裔，从来没有作过谁的奴隶，你怎么说‘会使你们自由’呢？”","notes":[]},{"n":34,"t":"耶稣回答他们：“我实实在在地告诉你们，所有犯罪的人就是罪的奴隶。","notes":[]},{"n":35,"t":"奴隶不能永远住在家里；儿子才永远住在家里。","notes":[]},{"n":36,"t":"所以，神的儿子若使你们自由，你们就真正自由了。”","notes":[]},{"n":37,"t":"“我知道，你们是亚伯拉罕的后裔，你们却想要杀我，因为你们心里容不下我的道。","notes":[],"heads":["出于神的必听神的话"]},{"n":38,"t":"我所说的是在我父那里看见的；你们所做的是在你们的父那里听到的。”","notes":[]},{"n":39,"t":"他们回答耶稣：“我们的父是亚伯拉罕。”耶稣对他们说：“你们若是亚伯拉罕的儿女，就会做亚伯拉罕所做的事。","notes":[]},{"n":40,"t":"我把在神那里所听见的真理告诉了你们，现在你们却想要杀我；亚伯拉罕没有做过这样的事。","notes":[]},{"n":41,"t":"你们是做你们父的工作。”他们就对他说：“我们不是从淫乱生的，我们只有一位父，就是神。”","notes":[]},{"n":42,"t":"耶稣对他们说：“假如神是你们的父，你们会爱我，因为我本是出于神，也是从神而来，我不是凭着自己来，而是他差我来的。","notes":[]},{"n":43,"t":"你们为什么不明白我的话呢？无非是你们听不进我的道。","notes":[]},{"n":44,"t":"你们是出于你们的父魔鬼，你们宁愿随着你们父的欲念而行。他从起初就是杀人的，不守真理，因他心里没有真理。他说谎是出于自己的本性，因他本来是说谎的，也是说谎者之父。","notes":[]},{"n":45,"t":"但是，因为我讲真理，你们就不信我。","notes":[]},{"n":46,"t":"你们中间谁能指证我有罪呢？既然我讲真理，你们为什么不信我呢？","notes":[]},{"n":47,"t":"出于神的，必听神的话；你们不听，因为你们不是出于神。”","notes":[]},{"n":48,"t":"犹太人回答他：“我们说你是撒玛利亚人，并且是被鬼附的，这话不是很对吗？”","notes":[],"heads":["耶稣在亚伯拉罕之先"]},{"n":49,"t":"耶稣回答：“我没有被鬼附；我尊敬我的父，你们却不尊敬我。","notes":[]},{"n":50,"t":"我不寻求自己的荣耀，但有一位为我寻求荣耀，判断是非。","notes":[]},{"n":51,"t":"我实实在在地告诉你们，人若遵守我的道，就永远不经历死亡。”","notes":[]},{"n":52,"t":"于是犹太人对他说：“现在我们知道你是被鬼附了。亚伯拉罕死了，众先知也死了，你还说：‘人若遵守我的道，就永远不经历死亡。’","notes":[]},{"n":53,"t":"难道你比我们的祖宗亚伯拉罕还大吗？他死了，众先知也死了，你把自己当作什么人呢？”","notes":[]},{"n":54,"t":"耶稣回答：“我若荣耀自己，我的荣耀就算不了什么；荣耀我的是我的父，就是你们所说的你们的神。","notes":[]},{"n":55,"t":"你们不认识他，我却认识他。我若说不认识他，我就是说谎的，像你们一样；但我认识他，也遵守他的道。","notes":[]},{"n":56,"t":"你们的祖宗亚伯拉罕欢欢喜喜地仰望我的日子，他看见了，就快乐。”","notes":[]},{"n":57,"t":"犹太人就对他说：“你还没有五十岁，难道见过亚伯拉罕吗？”","notes":[]},{"n":58,"t":"耶稣对他们说：“我实实在在地告诉你们，还没有亚伯拉罕我就存在了。”","notes":[]},{"n":59,"t":"于是他们拿石头要打他，耶稣却躲开，走出了圣殿。","notes":[]}]},"9":{"heading":"治好生来失明的人","verses":[{"n":1,"t":"耶稣往前走的时候，看见一个生来就失明的人。","notes":[]},{"n":2,"t":"门徒问耶稣：“拉比，这人生来失明，是谁犯了罪？是这人还是他的父母呢？”","notes":[]},{"n":3,"t":"耶稣回答：“既不是这人犯了罪，也不是他的父母，而是要在他身上显出神的作为来。","notes":[]},{"n":4,"t":"趁着白日，我们必须做差我来的那位的工；黑夜来到，就没有人能做工了。","notes":["有古卷是“我”。","有古卷是“我们”。"]},{"n":5,"t":"我在世上的时候，是世上的光。”","notes":[]},{"n":6,"t":"耶稣说了这些话，就吐唾沫在地上，用唾沫和了泥抹在盲人的眼睛上，","notes":[]},{"n":7,"t":"对他说：“你到西罗亚池子里去洗。”（西罗亚翻出来就是“奉差遣”。）于是他去，洗了，回来就看见了。","notes":[]},{"n":8,"t":"他的邻舍和素常见他讨饭的人，就说：“这不是那从前坐着讨饭的人吗？”","notes":[]},{"n":9,"t":"有的说：“是他”；又有的说：“不是，却是像他。”他自己说：“是我。”","notes":[]},{"n":10,"t":"于是他们对他说：“你的眼睛是怎么开的呢？”","notes":[]},{"n":11,"t":"那人回答：“有一个名叫耶稣的，他和了泥抹我的眼睛，对我说：‘你到西罗亚池子去洗。’我去一洗，就看见了。”","notes":[]},{"n":12,"t":"他们对他说：“那个人在哪里？”他说：“我不知道。”","notes":[]},{"n":13,"t":"他们把以前失明的那个人带到法利赛人那里。","notes":[],"heads":["法利赛人盘问医治的事"]},{"n":14,"t":"耶稣和泥开他眼睛的那一天是安息日。","notes":[]},{"n":15,"t":"法利赛人又问他是怎么得看见的。他对他们说：“他把泥抹在我的眼睛上，我一洗，就看见了。”","notes":[]},{"n":16,"t":"于是法利赛人中有的说：“这个人不是从神来的，因为他不守安息日。”另有的说：“一个罪人怎能行这样的神迹呢？”他们之间就产生了分裂。","notes":[]},{"n":17,"t":"于是他们又对那盲人说：“他开了你的眼睛，你说他是怎样的人呢？”他说：“他是个先知。”","notes":[]},{"n":18,"t":"犹太人不信他以前是失明，后来能看见的，等到叫了他的父母来，","notes":[]},{"n":19,"t":"问他们说：“这是你们的儿子吗？你们说他生来是失明的，现在怎么看见了呢？”","notes":[]},{"n":20,"t":"他的父母就回答说：“他是我们的儿子，生来就失明，这是我们知道的。","notes":[]},{"n":21,"t":"至于他现在怎么能看见，我们却不知道；是谁开了他的眼睛，我们也不知道。他已经是成人，你们问他吧，他自己会说。”","notes":[]},{"n":22,"t":"他父母说这些话，是怕犹太人，因为犹太人已经商定，若有宣认耶稣是基督的，要把他赶出会堂。","notes":[]},{"n":23,"t":"因此他父母说“他已经是成人，你们问他吧”。","notes":[]},{"n":24,"t":"于是法利赛人第二次叫了那以前失明的人来，对他说：“你要将荣耀归给神，我们知道这人是个罪人。”","notes":[]},{"n":25,"t":"那人就回答：“他是不是个罪人，我不知道；有一件事我知道，我本来是失明的，现在我看见了。”","notes":[]},{"n":26,"t":"他们就问他：“他给你做了什么？是怎么开了你的眼睛？”","notes":[]},{"n":27,"t":"他回答他们：“我已经告诉你们了，你们不听，为什么又要听呢？难道你们也要作他的门徒吗？”","notes":[]},{"n":28,"t":"他们就骂他：“你是他的门徒，而我们是摩西的门徒。","notes":[]},{"n":29,"t":"神对摩西说话是我们知道的，可是这个人，我们不知道他从哪里来。”","notes":[]},{"n":30,"t":"那人回答，对他们说：“他开了我的眼睛，你们竟不知道他从哪里来，这真是奇怪！","notes":[]},{"n":31,"t":"我们知道神不听罪人，惟有敬奉神、遵行他旨意的，神才听他。","notes":[]},{"n":32,"t":"从创世以来，未曾听见有人开了生来就失明的人的眼睛。","notes":[]},{"n":33,"t":"这人若不是从神来的，什么也不能做。”","notes":[]},{"n":34,"t":"他们回答他说：“你完全是生在罪中的，还要来教训我们吗？”于是他们把他赶出去了。","notes":[]},{"n":35,"t":"耶稣听说他们把他赶出去，就找到他，说：“你信人子吗？”","notes":["有古卷是“神的儿子”。"],"heads":["灵性的盲目"]},{"n":36,"t":"那人回答说：“主啊，人子是谁？告诉我，好让我信他。”","notes":[]},{"n":37,"t":"耶稣对他说：“你已经看见他，现在和你说话的就是他。”","notes":[]},{"n":38,"t":"他说：“主啊，我信！”他就拜耶稣。","notes":[]},{"n":39,"t":"耶稣说：“我为审判到这世上来，使不能看见的看见，能看见的反而失明。”","notes":[]},{"n":40,"t":"同他在那里的法利赛人听见这些话，就对他说：“难道我们也失明了吗？”","notes":[]},{"n":41,"t":"耶稣对他们说：“你们若是失明的，就没有罪了；但现在你们说‘我们能看见’，你们的罪还在。”","notes":[]}]},"10":{"heading":"羊圈的比喻","verses":[{"n":1,"t":"“我实实在在地告诉你们，那不从门进羊圈，倒从别处爬进去的，就是贼，就是强盗。","notes":[]},{"n":2,"t":"那从门进去的才是羊的牧人。","notes":[]},{"n":3,"t":"看门的给他开门，羊也听他的声音。他按着名叫自己的羊，把羊领出来。","notes":[]},{"n":4,"t":"当他把自己的羊都放出来，就走在前面，羊也跟着他，因为它们认得他的声音。","notes":[]},{"n":5,"t":"羊绝不跟陌生人，反而会逃走，因为不认得陌生人的声音。”","notes":[]},{"n":6,"t":"耶稣把这比方告诉他们，但他们不明白他所说的是什么。","notes":[]},{"n":7,"t":"所以，耶稣又对他们说：“我实实在在地告诉你们，我就是羊的门。","notes":[],"heads":["耶稣是好牧人"]},{"n":8,"t":"凡在我以前来的都是贼，是强盗；羊没有听从他们。","notes":["有古卷没有“在我以前”。"]},{"n":9,"t":"我就是门，凡从我进来的，必得安全，并且可进出，找到草吃。","notes":["“必得安全”或译“必然得救”。"]},{"n":10,"t":"盗贼来，无非要偷窃、杀害、毁坏；我来了，是要羊得生命，并且得的更丰盛。","notes":[]},{"n":11,"t":"“我是好牧人，好牧人为羊舍命。","notes":[]},{"n":12,"t":"雇工不是牧人，羊不是他自己的，他一看见狼来，就撇下羊群逃跑；狼抓住羊，把它们赶散。","notes":[]},{"n":13,"t":"雇工逃走，因为他是雇工，对羊毫不关心。","notes":[]},{"n":14,"t":"我是好牧人；我认识我的羊，我的羊也认识我，","notes":[]},{"n":15,"t":"正如父认识我，我也认识父一样；并且我为羊舍命。","notes":[]},{"n":16,"t":"我另外有羊，不属这圈里的，我必须领它们来，它们也要听我的声音，并且要合成一群，归一个牧人。","notes":[]},{"n":17,"t":"为此，我父爱我，因为我把命舍去，好再取回来。","notes":[]},{"n":18,"t":"没有人夺去我的命，是我自己舍的；我有权舍弃，也有权再取回。这是我从我父所受的命令。”","notes":[]},{"n":19,"t":"犹太人为这些话又起了分裂。","notes":[]},{"n":20,"t":"其中有好些人说：“他是被鬼附了，而且疯了，为什么听他的呢？”","notes":[]},{"n":21,"t":"另有的说：“这不是被鬼附的人所说的话。鬼岂能开盲人的眼睛呢？”","notes":[]},{"n":22,"t":"那时正是冬天，在耶路撒冷有献殿节。","notes":[],"heads":["犹太人弃绝耶稣"]},{"n":23,"t":"耶稣在圣殿里的所罗门廊下行走。","notes":[]},{"n":24,"t":"犹太人围着他，对他说：“你让我们犹豫不定到几时呢？你若是基督，就明白地告诉我们。”","notes":[]},{"n":25,"t":"耶稣回答他们：“我已经告诉你们，你们却不信。我奉我父的名所行的事可以为我作见证。","notes":[]},{"n":26,"t":"但是你们不信，因为你们不是我的羊。","notes":[]},{"n":27,"t":"我的羊听我的声音，我认识它们，它们也跟从我。","notes":[]},{"n":28,"t":"并且，我赐给他们永生；他们永不灭亡，谁也不能从我手里把他们夺去。","notes":[]},{"n":29,"t":"我父所赐给我的比万有都大，谁也不能从我父手里把他们夺去。","notes":["有古卷是“我父把他们赐给我，他比万有都大”。"]},{"n":30,"t":"我与父原为一。”","notes":[]},{"n":31,"t":"犹太人又拿起石头来要打他。","notes":[]},{"n":32,"t":"耶稣回应他们：“我做了许多从父那里来的善事给你们看，你们是为哪一件拿石头打我呢？”","notes":[]},{"n":33,"t":"犹太人回答他：“我们不是为了善事拿石头打你，而是为了你说亵渎的话；因为你是个人，却把自己当作神。”","notes":[]},{"n":34,"t":"耶稣回答他们：“你们的律法书上不是写着‘我曾说你们是诸神’吗？","notes":[]},{"n":35,"t":"经上的话是不能废的；如果那些领受神的道的人，神尚且称他们为诸神，","notes":[]},{"n":36,"t":"那么父所分别为圣又差到世上来的那位说‘我是神的儿子’，你们还对他说‘你说亵渎的话’吗？","notes":[]},{"n":37,"t":"我若不做我父的工作，你们就不必信我；","notes":[]},{"n":38,"t":"我若做了，你们即使不信我，也当信这些工作，好让你们知道并且明白父在我里面，我也在父里面。”","notes":[]},{"n":39,"t":"于是，他们又要捉拿他，他却从他们手中逃脱了。","notes":[]},{"n":40,"t":"耶稣又往约旦河的东边去，到了约翰起初施洗的地方，就住在那里。","notes":[]},{"n":41,"t":"有许多人来到他那里，说：“约翰没有行过一件神迹，但约翰所说有关这人的一切话都是真的。”","notes":[]},{"n":42,"t":"在那里，许多人信了耶稣。","notes":[]}]},"11":{"heading":"拉撒路的死","verses":[{"n":1,"t":"有一个患病的人，名叫拉撒路，住在伯大尼，就是马利亚和她姐姐马大的村庄。","notes":[]},{"n":2,"t":"这马利亚就是那用香膏抹主，又用头发擦他脚的；患病的拉撒路是她的弟弟。","notes":[]},{"n":3,"t":"姊妹两个就打发人去见耶稣，说：“主啊，你所爱的人病了。”","notes":[]},{"n":4,"t":"耶稣听见后却说：“这病不至于死，而是为了神的荣耀，为要使神的儿子藉此得荣耀。”","notes":[]},{"n":5,"t":"耶稣素来爱马大和她妹妹，以及拉撒路。","notes":[]},{"n":6,"t":"他听见拉撒路病了，仍在原地住了两天，","notes":[]},{"n":7,"t":"然后对门徒说：“我们再到犹太去吧！”","notes":[]},{"n":8,"t":"门徒对他说：“拉比，犹太人近来要拿石头打你，你还再到那里去吗？”","notes":[]},{"n":9,"t":"耶稣回答：“白天不是有十二小时吗？人若在白天行走，就不致跌倒，因为他看见这世上的光。","notes":[]},{"n":10,"t":"人若在黑夜行走，就会跌倒，因为他没有光。”","notes":[]},{"n":11,"t":"耶稣说了这些话，随后对他们说：“我们的朋友拉撒路睡了，我去叫醒他。”","notes":[]},{"n":12,"t":"门徒就说：“主啊，他若睡了，就会好的。”","notes":[]},{"n":13,"t":"耶稣说这话是指拉撒路死了，他们却以为他是指通常的睡眠。","notes":[]},{"n":14,"t":"于是耶稣就明白地告诉他们：“拉撒路死了。","notes":[]},{"n":15,"t":"为了你们的缘故，我不在那里反而欢喜，为要使你们信。现在我们到他那里去吧。”","notes":[]},{"n":16,"t":"于是那称为低土马的多马对其他的门徒说：“我们也去和他同死吧！”","notes":[]},{"n":17,"t":"耶稣到了，知道拉撒路在坟墓里已经四天了。","notes":[],"heads":["耶稣是复活，是生命"]},{"n":18,"t":"伯大尼离耶路撒冷不远，约有六里路。","notes":["“六里”：即三公里；原来即“十五斯他迪”，古希腊长度单位，参“度量衡表”。"]},{"n":19,"t":"有好些犹太人来看马大和马利亚，要为她们弟弟的缘故安慰她们。","notes":[]},{"n":20,"t":"马大听见耶稣来了，就出去迎接他；马利亚却仍然坐在家里。","notes":[]},{"n":21,"t":"马大对耶稣说：“主啊，你若早在这里，我弟弟就不会死了。","notes":[]},{"n":22,"t":"我也知道，即使现在，你无论向神求什么，神也必赐给你。”","notes":[]},{"n":23,"t":"耶稣对她说：“你弟弟会复活的。”","notes":[]},{"n":24,"t":"马大对他说：“我知道在末日复活的时候，他会复活。”","notes":[]},{"n":25,"t":"耶稣对她说：“复活...也在我。信我的人虽然死了，也必复活。","notes":["“复活在我，生命也在我”：原文直译“我就是复活和生命”。"]},{"n":26,"t":"凡活着信我的人必永远不死。你信这话吗？”","notes":[]},{"n":27,"t":"马大对他说：“主啊，是的。我信你是基督，是神的儿子，就是那要临到世界的。”","notes":[]},{"n":28,"t":"马大说了这话就回去，叫她妹妹马利亚，私下说：“老师来了，他在叫你。”","notes":[],"heads":["耶稣哭了"]},{"n":29,"t":"马利亚听见了，急忙起来，到耶稣那里去。","notes":[]},{"n":30,"t":"那时，耶稣还没有进村子，仍在马大迎接他的地方。","notes":[]},{"n":31,"t":"那些同马利亚在家里安慰她的犹太人，见她急忙起来，出去，就跟着她，以为她要往坟墓那里去哭。","notes":[]},{"n":32,"t":"马利亚到了耶稣那里，看见他，就俯伏在他脚前，对他说：“主啊，你若早在这里，我弟弟就不会死了。”","notes":[]},{"n":33,"t":"耶稣看见她哭，并看见与她同来的犹太人也哭，就心里悲叹，又甚忧愁，","notes":[]},{"n":34,"t":"就说：“你们把他安放在哪里？”他们对他说：“主啊，请你来看。”","notes":[]},{"n":35,"t":"耶稣哭了。","notes":[]},{"n":36,"t":"犹太人就说：“你看，他多么爱他！”","notes":[]},{"n":37,"t":"其中有人说：“他既然开了盲人的眼睛，难道不能叫这人不死吗？”","notes":[]},{"n":38,"t":"耶稣又心里悲叹，来到坟墓前。那坟墓是个穴，有一块石头挡着。","notes":[],"heads":["拉撒路复活"]},{"n":39,"t":"耶稣说：“把石头挪开！”那死者的姐姐马大对他说：“主啊，他现在必定臭了，因为他已经死了四天了。”","notes":[]},{"n":40,"t":"耶稣对她说：“我不是对你说过，你若信就必看见神的荣耀吗？”","notes":[]},{"n":41,"t":"于是他们把石头挪开。耶稣举目望天，说：“父啊，我感谢你，因为你已经听了我。","notes":[]},{"n":42,"t":"我知道你常常听我，但我说这话是为了周围站着的众人，要使他们信是你差了我来的。”","notes":[]},{"n":43,"t":"说了这些话，他大声呼叫说：“拉撒路，出来！”","notes":[]},{"n":44,"t":"那死了的人就出来了，手脚都裹着布，脸上包着头巾。耶稣对他们说：“解开他，让他走！”","notes":[]},{"n":45,"t":"于是来看马利亚的犹太人中，有很多人见了耶稣所做的事，就信了他。","notes":[],"heads":["杀害耶稣的阴谋"]},{"n":46,"t":"但其中也有人去见法利赛人，把耶稣所做的事告诉他们。","notes":[]},{"n":47,"t":"祭司长和法利赛人召开议会，说：“这人行好些神迹，我们怎么办呢？","notes":[]},{"n":48,"t":"若让他这样做，人人都要信他；罗马人也要来毁灭我们的圣殿和我们的民族。”","notes":["“圣殿”或译“土地”。"]},{"n":49,"t":"其中有一个人，名叫该亚法，那年当大祭司，对他们说：“你们什么都不知道，","notes":[]},{"n":50,"t":"也不想想，一个人替百姓死，免得整个民族灭亡，这对你们是有利的。”","notes":[]},{"n":51,"t":"他这话不是出于自己的意思，而是因他那年当大祭司，所以预言耶稣将为这民族而死。","notes":[]},{"n":52,"t":"他不但替这民族死，还要把神四散的儿女都聚集起来，合成一群。","notes":[]},{"n":53,"t":"从那日起，他们就商议要杀耶稣。","notes":[]},{"n":54,"t":"所以，耶稣不再公开在犹太人中走动，却离开那里，往靠近旷野的乡间去，到了一座城，名叫以法莲，就在那里和门徒住下来。","notes":[]},{"n":55,"t":"犹太人的逾越节近了，有许多人从乡下上耶路撒冷去，要在过节前洁净自己。","notes":[]},{"n":56,"t":"于是他们寻找耶稣，站在圣殿里彼此说：“你们认为怎样，他不会来过节吧？”","notes":[]},{"n":57,"t":"那时，祭司长和法利赛人早已下令，若有人知道耶稣的下落，就要报告，他们好去捉拿他。","notes":[]}]},"12":{"heading":"在伯大尼受膏","verses":[{"n":1,"t":"逾越节前六天，耶稣来到伯大尼，就是他使拉撒路从死人中复活的地方。","notes":[]},{"n":2,"t":"有人在那里为耶稣预备宴席；马大伺候，拉撒路也在同耶稣坐席的人中间。","notes":[]},{"n":3,"t":"马利亚拿着一斤极贵的纯哪哒香膏，抹耶稣的脚，又用自己头发去擦，屋里充满了膏的香气。","notes":["“哪哒”即“甘松”。"]},{"n":4,"t":"有一个门徒，就是那将要出卖耶稣的加略人犹大，说：","notes":[]},{"n":5,"t":"“为什么不把这香膏卖三百个银币去周济穷人呢？”","notes":[]},{"n":6,"t":"他说这话，并不是关心穷人，而是因为他是个贼，又管钱囊，常偷取钱囊中所存的。","notes":[]},{"n":7,"t":"耶稣说：“由她吧！她这香膏本是为我的安葬之日留着的。","notes":[]},{"n":8,"t":"因为常有穷人和你们在一起，但是你们不常有我。”","notes":[]},{"n":9,"t":"有一大群犹太人知道耶稣在那里，就来了，不但是为耶稣的缘故，也是要看耶稣使他从死人中复活的拉撒路。","notes":[],"heads":["杀害拉撒路的阴谋"]},{"n":10,"t":"于是众祭司长商议连拉撒路也要杀了，","notes":[]},{"n":11,"t":"因为有许多犹太人为了拉撒路的缘故，开始背离他们，信了耶稣。","notes":[]},{"n":12,"t":"第二天，有一大群上来过节的人听见耶稣要来耶路撒冷，","notes":[],"heads":["荣入圣城"]},{"n":13,"t":"就拿着棕树枝出去迎接他，喊着：“和散那，以色列的王！奉主名来的是应当称颂的！”","notes":["“和散那”：原是求救的意思，在此是称颂的话。"]},{"n":14,"t":"耶稣找到了一匹驴驹，就骑上，如经上所记：","notes":[]},{"n":15,"t":"“锡安的儿女啊，不要惧怕！看哪，你的王来了；他骑在驴驹上。”","notes":["“儿女”：原文直译“女儿”。"]},{"n":16,"t":"门徒当初不明白这些事，等到耶稣得了荣耀后才想起这些话是指他写的，并且人们果然对他做了这些事。","notes":[]},{"n":17,"t":"当耶稣呼唤拉撒路，使他从死人中复活出坟墓的时候，同耶稣在那里的众人就作见证。","notes":[]},{"n":18,"t":"众人因听见耶稣行了这神迹，就去迎接他。","notes":[]},{"n":19,"t":"法利赛人彼此说：“你们看，你们一事无成，世人都随着他去了。”","notes":[]},{"n":20,"t":"那时，上来过节礼拜的人中，有几个希腊人。","notes":[],"heads":["希腊人求见耶稣"]},{"n":21,"t":"他们来见加利利的伯赛大人腓力，请求他说：“先生，我们想见耶稣。”","notes":[]},{"n":22,"t":"腓力去告诉安得烈，然后安得烈同腓力去告诉耶稣。","notes":[]},{"n":23,"t":"耶稣回答他们说：“人子得荣耀的时候到了。","notes":[]},{"n":24,"t":"我实实在在地告诉你们，一粒麦子不落在地里死了，仍旧是一粒；若是死了，就结出许多子粒来。","notes":[]},{"n":25,"t":"爱惜自己性命的，就丧失性命；那恨恶自己在这世上的性命的，要保全性命到永生。","notes":[]},{"n":26,"t":"若有人服事我，就当跟从我；我在哪里，服事我的人也要在哪里；若有人服事我，我父必尊重他。”","notes":[]},{"n":27,"t":"“我现在心里忧愁，我说什么才好呢？说‘父啊，救我脱离这时候’吗？但我正是为这时候来的。","notes":[],"heads":["人子必须被举起来"]},{"n":28,"t":"父啊，愿你荣耀你的名！”于是有声音从天上来，说：“我已经荣耀了我的名，还要再荣耀。”","notes":[]},{"n":29,"t":"站在旁边的众人听见，就说：“打雷了。”另有的说：“有天使对他说话。”","notes":[]},{"n":30,"t":"耶稣回答说：“这声音不是为我，而是为你们来的。","notes":[]},{"n":31,"t":"现在正是这世界受审判的时候；现在这世界的统治者要被赶出去。","notes":[]},{"n":32,"t":"我从地上被举起来的时候，我要吸引万人来归我。”","notes":[]},{"n":33,"t":"耶稣这话是指自己将要怎样死说的。","notes":[]},{"n":34,"t":"众人就回答他：“我们听见律法书上说，基督是永存的；你怎么说，人子必须被举起来呢？这人子是谁呢？”","notes":[]},{"n":35,"t":"耶稣对他们说：“光在你们中间为时不多了，应该趁着有光的时候行走，免得黑暗临到你们；那在黑暗里行走的，不知道往何处去。","notes":[]},{"n":36,"t":"你们趁着有光，要信从这光，使你们成为光明之子。”耶稣说了这些话，就离开他们隐藏了。","notes":[]},{"n":37,"t":"他虽然在他们面前行了许多神迹，他们还是不信他。","notes":[]},{"n":38,"t":"这是要应验以赛亚先知所说的话：“主啊，我们所传的有谁信呢？主的膀臂向谁显露呢？”","notes":[]},{"n":39,"t":"他们所以不能信，因为以赛亚又说：","notes":[]},{"n":40,"t":"“主使他们瞎了眼，使他们硬了心，免得他们眼睛看见，他们心里明白，回转过来，我会医治他们。”","notes":[]},{"n":41,"t":"以赛亚因看见了他的荣耀，就说了关于他的这话。","notes":[]},{"n":42,"t":"虽然如此，官长中却有好些信他的，只因法利赛人的缘故不敢承认，恐怕被赶出会堂。","notes":[]},{"n":43,"t":"这是因他们爱人给的尊荣过于爱神给的尊荣。","notes":[]},{"n":44,"t":"耶稣喊着说：“信我的人不是信我，而是信差我来的那位。","notes":[],"heads":["耶稣的道要审判人"]},{"n":45,"t":"看见我的，就是看见差我来的那位。","notes":[]},{"n":46,"t":"我就是来到世上的光，使凡信我的不住在黑暗里。","notes":[]},{"n":47,"t":"若有人听见我的话而不遵守，我不审判他，因为我来不是要审判世人，而是要拯救世人。","notes":[]},{"n":48,"t":"弃绝我、不领受我话的人自有审判他的；我所讲的道在末日要审判他。","notes":[]},{"n":49,"t":"因为我没有凭着自己讲，而是差我来的父已经给我命令，叫我说什么，讲什么。","notes":[]},{"n":50,"t":"我也知道他的命令就是永生。所以，我讲的正是照着父所告诉我的，我就这么讲了。”","notes":[]}]},"13":{"heading":"耶稣为门徒洗脚","verses":[{"n":1,"t":"逾越节以前，耶稣知道自己离世归父的时候到了。他一向爱世间属自己的人，就爱他们到底。","notes":[]},{"n":2,"t":"晚餐的时候，魔鬼已把出卖耶稣的意思放在加略人西门的儿子犹大心里。","notes":[]},{"n":3,"t":"耶稣知道父已把万有交在他手里，且知道自己是从神出来的，又要回到神那里去，","notes":[]},{"n":4,"t":"就离席站起来，脱了衣服，拿一条手巾束腰，","notes":[]},{"n":5,"t":"随后把水倒在盆里，开始洗门徒的脚，并用束腰的手巾擦干。","notes":[]},{"n":6,"t":"到了西门．彼得跟前，彼得对他说：“主啊，你洗我的脚吗？”","notes":[]},{"n":7,"t":"耶稣回答他说：“我所做的，你现在不知道，但以后会明白。”","notes":[]},{"n":8,"t":"彼得对他说：“你绝对不可以洗我的脚！”耶稣回答他：“我若不洗你，你就与我无份了。”","notes":[]},{"n":9,"t":"西门．彼得对他说：“主啊，不仅是我的脚，连手和头也要洗！”","notes":[]},{"n":10,"t":"耶稣对他说：“凡洗过澡的人不需要再洗，只要把脚一洗，全身就干净了。你们是干净的，然而不都是干净的。”","notes":[]},{"n":11,"t":"耶稣已知道要出卖他的是谁，因此说“你们不都是干净的”。","notes":[]},{"n":12,"t":"耶稣洗完了他们的脚，就穿上衣服，又坐下，对他们说：“我为你们所做的，你们明白吗？","notes":[]},{"n":13,"t":"你们称呼我老师，称呼我主，你们说的不错，我本来就是。","notes":[]},{"n":14,"t":"我是你们的主，你们的老师，尚且洗你们的脚，你们也应当彼此洗脚。","notes":[]},{"n":15,"t":"我给你们作了榜样，为要你们照着我为你们所做的去做。","notes":[]},{"n":16,"t":"我实实在在地告诉你们，仆人不大于主人；奉差的人也不大于差他的人。","notes":[]},{"n":17,"t":"你们既知道这些事，若是去实行就有福了。","notes":[]},{"n":18,"t":"我不是指着你们众人说的，我知道我所拣选的是谁；但是要应验经上的话：‘吃我饭的人用脚踢我。’","notes":["有古卷是“同我吃饭的人”。"]},{"n":19,"t":"事情还没有发生，我现在先告诉你们，让你们到事情发生的时候好信我就是那位。","notes":[]},{"n":20,"t":"我实实在在地告诉你们，接纳我所差遣的就是接纳我；接纳我的就是接纳差遣我的那位。”","notes":[]},{"n":21,"t":"耶稣说了这些话，心里忧愁，于是明确地说：“我实实在在地告诉你们，你们中间有一个人要出卖我。”","notes":[],"heads":["耶稣预言将被出卖"]},{"n":22,"t":"门徒彼此相看，猜不出他说的是谁。","notes":[]},{"n":23,"t":"门徒中有一个人，是耶稣所爱的，侧身挨近耶稣的胸怀。","notes":[]},{"n":24,"t":"西门．彼得就对这个人示意，要问耶稣是指着谁说的。","notes":[]},{"n":25,"t":"于是那人紧靠着耶稣的胸膛，问他：“主啊，是谁呢？”","notes":[]},{"n":26,"t":"耶稣回答：“我蘸一点饼给谁，就是谁。”耶稣就蘸了一点饼，递给加略人西门的儿子犹大。","notes":[]},{"n":27,"t":"他接了那饼以后，撒但就进入他的心。于是耶稣对他说：“你要做的，快做吧！”","notes":["“接”或译“吃”。"]},{"n":28,"t":"同席的人没有一个知道耶稣为什么对他说这话。","notes":[]},{"n":29,"t":"有人因犹大管钱囊，以为耶稣是对他说“你去买我们过节所需要的东西”，或是叫他拿些什么给穷人。","notes":[]},{"n":30,"t":"犹大受了那点饼以后立刻出去。那时候是夜间了。","notes":["“受”或译“吃”。"]},{"n":31,"t":"犹大出去后，耶稣说：“如今人子得了荣耀，神在人子身上也得了荣耀。","notes":[],"heads":["新的命令"]},{"n":32,"t":"如果神因人子得了荣耀，神也要因自己荣耀人子，并且要立刻荣耀他。","notes":["有古卷没有“如果…得了荣耀”。"]},{"n":33,"t":"孩子们！我与你们同在的时候不多了；你们会找我，但我所去的地方，你们不能去。这话我曾对犹太人说过，现在也照样对你们说。","notes":[]},{"n":34,"t":"我赐给你们一条新命令，乃是叫你们彼此相爱；我怎样爱你们，你们也要怎样彼此相爱。","notes":[]},{"n":35,"t":"你们若彼此相爱，众人因此就认出你们是我的门徒了。”","notes":[]},{"n":36,"t":"西门．彼得问耶稣：“主啊，你去哪里？”耶稣回答：“我所去的地方，你现在不能跟我去，以后却要跟我去。”","notes":[],"heads":["预言彼得不认主"]},{"n":37,"t":"彼得对他说：“主啊，为什么我现在不能跟你去？我愿意为你舍命。”","notes":[]},{"n":38,"t":"耶稣回答：“你愿意为我舍命吗？我实实在在地告诉你，鸡叫以前，你要三次不认我。”","notes":[]}]},"14":{"heading":"耶稣是道路、真理、生命","verses":[{"n":1,"t":"“你们心里不要忧愁；你们信神，也当信我。","notes":[]},{"n":2,"t":"在我父的家里有许多住处；若是没有，我就早已告诉你们了。我去原是为你们预备地方去。","notes":["“若是没有…预备地方去。”或译“若是没有，我会告诉你们，我去是为你们预备地方吗？”"]},{"n":3,"t":"我若去为你们预备了地方，就必再来接你们到我那里去，我在哪里，叫你们也在哪里。","notes":[]},{"n":4,"t":"我往哪里去，你们知道那条路。”","notes":[]},{"n":5,"t":"多马对他说：“主啊，我们不知道你去哪里，怎么能知道那条路呢？”","notes":[]},{"n":6,"t":"耶稣对他说：“我就是道路、真理、生命；若不藉着我，没有人能到父那里去。","notes":[]},{"n":7,"t":"既然你们认识了我，也会认识我的父。从今以后，你们就认识他，并且已经看见他了。”","notes":[]},{"n":8,"t":"腓力对他说：“主啊，将父显给我们看，我们就知足了。”","notes":[]},{"n":9,"t":"耶稣对他说：“腓力，我与你们在一起这么久了，你还不认识我吗？看见我的就是看见了父，你怎么还说‘将父显给我们看’呢？","notes":[]},{"n":10,"t":"我在父里面，父在我里面，你不信吗？我对你们所说的话不是凭着自己说的，而是住在我里面的父在做他的工作。","notes":[]},{"n":11,"t":"你们要信我，我在父里面，父在我里面；即使不信，也要因我所做的工作信我。","notes":[]},{"n":12,"t":"我实实在在地告诉你们，我所做的工作，信我的人也要做，并且要做得比这些更大，因为我到父那里去。","notes":[]},{"n":13,"t":"你们奉我的名无论求什么，我必成全，为了使父因儿子得荣耀。","notes":[]},{"n":14,"t":"你们若奉我的名向我求什么，我必成全。”","notes":[]},{"n":15,"t":"“你们若爱我，就会遵守我的命令。","notes":[],"heads":["应许赐圣灵"]},{"n":16,"t":"我要求父，父就赐给你们另外一位保惠师，使他永远与你们同在。","notes":["“保惠师”或译“劝慰者”；26节，15.26，16.7同。"]},{"n":17,"t":"他就是真理的灵，是世人不能接受的。因为他们既看不见他，也不认识他；你们却认识他，因他常与你们同在，也要在你们里面。","notes":[]},{"n":18,"t":"我不会撇下你们为孤儿，我必到你们这里来。","notes":[]},{"n":19,"t":"再过不久，世人不再看见我，你们却会看见我，因为我活着，你们也要活着。","notes":[]},{"n":20,"t":"到那日，你们就会知道我在父里面，你们在我里面，我也在你们里面。","notes":[]},{"n":21,"t":"有了我的命令而又遵守的人，就是爱我的；爱我的人，我父要爱他，我也要爱他，并且要亲自向他显现。”","notes":[]},{"n":22,"t":"犹大（不是加略人犹大）问耶稣：“主啊，为什么亲自向我们显现，而不向世人显现呢？”","notes":[]},{"n":23,"t":"耶稣回答他说：“凡爱我的人就会遵守我的道，我父也会爱他，并且我们要到他那里去，与他同住。","notes":[]},{"n":24,"t":"不爱我的人就不遵守我的道。你们所听见的道不是我的，而是差我来之父的。","notes":[]},{"n":25,"t":"“我还与你们在一起的时候，已对你们说了这些事。","notes":[]},{"n":26,"t":"但保惠师，就是父因我的名所要差来的圣灵，他要把一切的事教导你们，并且要使你们想起我对你们所说的一切话。","notes":[]},{"n":27,"t":"我留下平安给你们，我把我的平安赐给你们。我所赐给你们的，不像世人所赐的。你们心里不要忧愁，也不要胆怯。","notes":[]},{"n":28,"t":"你们听见我对你们说过，我去了还要回到你们这里来。你们若爱我，就会因我到父那里去而喜乐，因为父比我大。","notes":[]},{"n":29,"t":"现在事情还没有发生，我预先告诉你们，使你们在事情发生的时候会信。","notes":[]},{"n":30,"t":"我不再和你们多说了，因为这世界的统治者将到，他在我身上一无所能。","notes":[]},{"n":31,"t":"我这么做是照着父命令我的，为了让世人知道我爱父。起来，我们走吧！”","notes":[]}]},"15":{"heading":"耶稣是真葡萄树","verses":[{"n":1,"t":"“我就是真葡萄树，我父是栽培的人。","notes":[]},{"n":2,"t":"凡属我不结果子的枝子，他就剪掉；凡结果子的，他就修剪干净，使枝子结果子更多。","notes":[]},{"n":3,"t":"现在你们因我讲给你们的道已经洁净了。","notes":[]},{"n":4,"t":"你们要常在我里面，我也常在你们里面。枝子若不常在葡萄树上，自己就不能结果子；你们若不常在我里面，也是这样。","notes":[]},{"n":5,"t":"我就是葡萄树，你们是枝子。常在我里面的，我也常在他里面，这人就多结果子，因为离了我，你们就不能做什么。","notes":[]},{"n":6,"t":"人若不常在我里面，就像枝子被丢在外面，枯干了，人捡起来，扔进火里烧了。","notes":[]},{"n":7,"t":"你们若常在我里面，我的话也常在你们里面，凡你们想要的，祈求，就给你们成全。","notes":[]},{"n":8,"t":"你们多结果子，我父就因此得荣耀，你们也就是我的门徒了。","notes":["“是”：有古卷是“成为”。"]},{"n":9,"t":"我爱你们，正如父爱我一样；你们要常在我的爱里。","notes":[]},{"n":10,"t":"你们若遵守我的命令，就会常在我的爱里，正如我遵守了我父的命令，常在他的爱里。","notes":[]},{"n":11,"t":"“我已对你们说了这些事，是要让我的喜乐存在你们心里，并让你们的喜乐得以满足。","notes":[]},{"n":12,"t":"你们要彼此相爱，像我爱你们一样，这是我的命令。","notes":[]},{"n":13,"t":"人为朋友舍命，人的爱心没有比这个更大的了。","notes":[]},{"n":14,"t":"你们若遵行我所命令的，就是我的朋友。","notes":[]},{"n":15,"t":"以后我不再称你们为仆人，因为仆人不知道主人所做的事；但我称你们为朋友，因为我从我父所听见的一切都已经让你们知道了。","notes":[]},{"n":16,"t":"不是你们拣选了我，而是我拣选了你们，并且派你们去结果子，让你们的果子得以长存，好使你们奉我的名，无论向父求什么，他会赐给你们。","notes":[]},{"n":17,"t":"我这样命令你们，是要你们彼此相爱。”","notes":[]},{"n":18,"t":"“世人若恨你们，你们要知道，他们在恨你们以前已经恨我了。","notes":[],"heads":["世人的憎恨"]},{"n":19,"t":"你们若属世界，世界会爱属自己的；只因你们不属世界，而是我从世界中拣选了你们，所以世界就恨你们。","notes":[]},{"n":20,"t":"你们要记得我对你们说过的话：‘仆人不大于主人。’他们若迫害了我，也会迫害你们，他们若遵守了我的话，也会遵守你们的话。","notes":[]},{"n":21,"t":"但他们要因我的名向你们做这一切的事，因为他们不认识差我来的那位。","notes":[]},{"n":22,"t":"我若没有来教导他们，他们就没有罪；但如今他们的罪无可推诿了。","notes":[]},{"n":23,"t":"恨我的也恨我的父。","notes":[]},{"n":24,"t":"我若没有在他们中间做过别人未曾做的事，他们就没有罪；但如今连我与我的父，他们也看见了，也恨恶了。","notes":[]},{"n":25,"t":"这是要应验他们律法上所写的话：‘他们无故地恨我。’","notes":[]},{"n":26,"t":"“但我要从父那里差保惠师来，就是从父出来的那真理的灵，他来的时候要为我作见证。","notes":[]},{"n":27,"t":"你们也要作见证，因为你们从起初就与我同在。”","notes":[]}]},"16":{"heading":"圣灵的工作","verses":[{"n":1,"t":"“我对你们说了这些事，是要使你们不至于跌倒。","notes":[]},{"n":2,"t":"人要把你们赶出会堂，而且时候将到，凡杀你们的还以为是在事奉神。","notes":[]},{"n":3,"t":"他们这样做，是因为没有认识父，也没有认识我。","notes":[]},{"n":4,"t":"我对你们说了这些事，是要在他们做这些事的时候，你们会想起我对你们说过的话。”“我起先没有对你们说这些事，因为我一直与你们同在。","notes":[]},{"n":5,"t":"现在我要到差我来的父那里去，你们中间却没有人问我‘你去哪里？’","notes":[]},{"n":6,"t":"只因我对你们说了这些事，你们就满心忧愁。","notes":[]},{"n":7,"t":"然而，我把真情告诉你们，我去对你们是有益的。我若不去，保惠师就不会到你们这里来；我若去，就差他到你们这里来。","notes":[]},{"n":8,"t":"他来的时候，要为罪、为义，为审判，指证世人；","notes":[]},{"n":9,"t":"为罪，是因他们不信我；","notes":[]},{"n":10,"t":"为义，是因我到父那里去，你们将不再见到我；","notes":[]},{"n":11,"t":"为审判，是因这世界的统治者已受了审判。","notes":[]},{"n":12,"t":"“我还有好些事要告诉你们，但你们现在担当不了。","notes":["“担当不了”或译“不能领会”。"]},{"n":13,"t":"但真理的灵来的时候，他要引导你们进入一切真理。因为他不是凭着自己说的，而是把他所听见的都说出来，并且要把将要来的事向你们传达。","notes":[]},{"n":14,"t":"他要荣耀我，因为他要把从我领受的向你们传达。","notes":[]},{"n":15,"t":"凡父所有的都是我的，所以我说，他要把从我领受的向你们传达。”","notes":[]},{"n":16,"t":"“不久，你们将不再见到我；再过不久，你们还要见到我。”","notes":[],"heads":["忧愁变为喜乐"]},{"n":17,"t":"有几个门徒彼此说：“他对我们说‘不久，你们将不再见到我；再过不久，你们还要见到我’；又说‘因我到父那里去’。这是什么意思呢？”","notes":[]},{"n":18,"t":"于是门徒说：“他说‘不久’到底是什么意思呢？我们不明白他说什么。”","notes":["有古卷没有“他说”。"]},{"n":19,"t":"耶稣看出他们要问他，就对他们说：“我说‘不久，你们将不再见到我；再过不久，你们还要见到我’，你们为这话彼此询问吗？","notes":[]},{"n":20,"t":"我实实在在地告诉你们，你们将要痛哭，哀号，世人反要欢喜。你们将要忧愁，然而你们的忧愁要变成喜乐。","notes":[]},{"n":21,"t":"妇人生产的时候会忧愁，因为她的时候到了；但孩子一生出来，就不再记得那痛苦了，因为欢喜有一个人生在世上了。","notes":[]},{"n":22,"t":"你们现在也是忧愁，但我要再见到你们，你们的心就会有喜乐了；这喜乐没有人能夺去。","notes":[]},{"n":23,"t":"到那日，你们什么也不会问我了。我实实在在地告诉你们，你们奉我的名无论向父求什么，他会赐给你们。","notes":["“你们奉我的名…赐给你们”：有古卷是“你们若向父求什么，他会因我的名赐给你们”。"]},{"n":24,"t":"直到现在，你们没有奉我的名求什么，如今你们求就必得着，使你们的喜乐得以满足。”","notes":[]},{"n":25,"t":"“这些事，我是用比方对你们说的；时候将到，我不再用比方对你们说，而是要把父的事明白地告诉你们。","notes":[],"heads":["我已经胜过世界"]},{"n":26,"t":"到那日，你们要奉我的名祈求；我并不对你们说，我要为你们向父祈求。","notes":[]},{"n":27,"t":"父自己爱你们，因为你们已经爱我，又信我是从神而来的。","notes":["“神”：有古卷是“父”。"]},{"n":28,"t":"我从父而来，到了世界，又离开世界，到父那里去。”","notes":["“我从…世界”：有古卷是“我到了世界”。"]},{"n":29,"t":"门徒说：“你看，如今你是明说，不用比方了。","notes":[]},{"n":30,"t":"现在我们晓得你凡事都知道，也不需要有人问你；从此我们信你是从神而来的。”","notes":[]},{"n":31,"t":"耶稣回答他们：“现在你们信了吗？","notes":[]},{"n":32,"t":"看哪，时候将到，其实已经到了，你们要分散，各归自己的地方，留下我独自一人；然而我不是独自一人，因为有父与我同在。","notes":[]},{"n":33,"t":"我对你们说了这些事，是要使你们在我里面有平安。在世上你们有苦难，但你们要有勇气，我已经胜过世界。”","notes":["“但你们要有勇气”或译“但你们放心”。"]}]},"17":{"heading":"耶稣的祷告","verses":[{"n":1,"t":"耶稣说了这些话，就举目望天，说：“父啊，时候到了，愿你荣耀你的儿子，使儿子也荣耀你；","notes":[]},{"n":2,"t":"因为你曾赐给他权柄掌管凡血肉之躯的，使他把永生赐给你所赐给他的人。","notes":[]},{"n":3,"t":"认识你—独一的真神，并且认识你所差来的耶稣基督，这就是永生。","notes":[]},{"n":4,"t":"我在地上已经荣耀你，你交给我做的工作，我已完成了。","notes":[]},{"n":5,"t":"父啊，现在求你使我在你面前得荣耀，就是在未有世界以前，我同你享有的荣耀。","notes":[]},{"n":6,"t":"“你从世上赐给我的人，我已把你的名显明给他们。他们本是你的，你把他们赐给我，他们也遵守了你的道。","notes":[]},{"n":7,"t":"现在他们知道，你所赐给我的一切都是从你那里来的；","notes":[]},{"n":8,"t":"因为你所赐给我的话，我已经赐给他们，他们也领受了，又确实知道，我是从你出来的，并且信你差了我来。","notes":[]},{"n":9,"t":"我为他们祈求，不为世人祈求，却为你所赐给我的人祈求，因他们本是你的。","notes":[]},{"n":10,"t":"凡是我的都是你的，你的也是我的，并且我因他们得了荣耀。","notes":[]},{"n":11,"t":"我到你那里去；我不再留在世上，他们却在世上。圣父啊，求你因你的名，就是你所赐给我的名，保守他们，使他们像我们一样合而为一。","notes":[]},{"n":12,"t":"我与他们同在的时候，我奉你的名，就是你所赐给我的名，保守了他们，我也护卫了他们；其中除了那灭亡之子，没有一个灭亡的，好使经上的话得以应验。","notes":[]},{"n":13,"t":"现在我到你那里去，我在世上说这些话，是要他们心里充满了我的喜乐。","notes":[]},{"n":14,"t":"我已把你的道赐给他们；世界恨他们，因为他们不属世界，正如我不属世界一样。","notes":[]},{"n":15,"t":"我不求你把他们从世上接走，只求你保全他们，使他们脱离那恶者。","notes":[]},{"n":16,"t":"他们不属世界，正如我不属世界一样。","notes":[]},{"n":17,"t":"求你用真理使他们成圣；你的道就是真理。","notes":[]},{"n":18,"t":"你怎样差我到世上，我也照样差他们到世上。","notes":[]},{"n":19,"t":"我为他们的缘故使自己分别为圣，为要使他们也因真理成圣。","notes":[]},{"n":20,"t":"“我不但为这些人祈求，也为那些藉着他们的话信我的人祈求，","notes":[]},{"n":21,"t":"使他们都合而为一。正如父你在我里面，我在你里面，使他们也在我们里面，好让世人信是你差我来的。","notes":[]},{"n":22,"t":"你所赐给我的荣耀，我已赐给他们，使他们合而为一，像我们合而为一。","notes":[]},{"n":23,"t":"我在他们里面，你在我里面，使他们完完全全合而为一，让世人知道是你差我来的，也知道你爱他们，如同爱我一样。","notes":[]},{"n":24,"t":"父啊，我在哪里，愿你所赐给我的人也同我在哪里，使他们看见你所赐给我的荣耀，因为创世以前，你已经爱我了。","notes":[]},{"n":25,"t":"公义的父啊，世人未曾认识你，我却认识你，这些人也知道是你差我来的。","notes":[]},{"n":26,"t":"我已让他们认识你的名，还要让他们认识，好让你爱我的爱在他们里面，我也在他们里面。”","notes":[]}]},"18":{"heading":"耶稣被捕","verses":[{"n":1,"t":"耶稣说了这些话，就同门徒出去，过了汲沦溪。在那里有一个园子，他和门徒进去了。","notes":[]},{"n":2,"t":"出卖耶稣的犹大也知道那地方，因为耶稣和门徒屡次在那里聚集。","notes":[]},{"n":3,"t":"犹大领了一队兵，以及祭司长和法利赛人的圣殿警卫，拿着灯笼、火把和兵器来到园里。","notes":[]},{"n":4,"t":"耶稣知道将要临到自己的一切事，就出来对他们说：“你们找谁？”","notes":[]},{"n":5,"t":"他们回答他：“拿撒勒人耶稣。”耶稣对他们说：“我就是。”出卖他的犹大也同他们站在一起。","notes":[]},{"n":6,"t":"耶稣一对他们说“我就是”，他们就退后，倒在地上。","notes":[]},{"n":7,"t":"他又问他们：“你们找谁？”他们说：“拿撒勒人耶稣。”","notes":[]},{"n":8,"t":"耶稣回答：“我已经告诉你们，我就是。你们若找的是我，就让这些人走吧。”","notes":[]},{"n":9,"t":"这要应验耶稣说过的话：“你所赐给我的人，我一个也不失落。”","notes":[]},{"n":10,"t":"西门．彼得带着一把刀，就拔出来，把大祭司的仆人砍了一刀，削掉了他的右耳，那仆人名叫马勒古。","notes":[]},{"n":11,"t":"于是耶稣对彼得说：“收刀入鞘吧！我父给我的杯，我岂可不喝呢？”","notes":[]},{"n":12,"t":"那队兵、千夫长和犹太人的警卫拿住耶稣，把他捆绑了，","notes":[],"heads":["耶稣被带到亚那面前"]},{"n":13,"t":"先带到亚那面前，因为他是那年的大祭司该亚法的岳父。","notes":[]},{"n":14,"t":"这该亚法就是从前向犹太人忠告说“一个人替百姓死是有利的”那个人。","notes":[]},{"n":15,"t":"西门．彼得跟着耶稣，另一个门徒也跟着；那门徒是大祭司所认识的，他就同耶稣进了大祭司的院子。","notes":[],"heads":["彼得不认耶稣"]},{"n":16,"t":"彼得却站在门外。大祭司所认识的那个门徒出来，对看门的使女说了一声，就领彼得进去。","notes":[]},{"n":17,"t":"那看门的使女对彼得说：“你不也是这人的门徒吗？”他说：“我不是。”","notes":[]},{"n":18,"t":"仆人和警卫因为天冷生了炭火，站在那里取暖；彼得也同他们站着取暖。","notes":[]},{"n":19,"t":"于是，大祭司盘问耶稣有关他的门徒和他教导的事。","notes":[],"heads":["大祭司盘问耶稣"]},{"n":20,"t":"耶稣回答他：“我一向都是公开地对世人讲话，我常在会堂和圣殿里，就是犹太人聚集的地方教导人，我私下并没有讲什么。","notes":[]},{"n":21,"t":"你为什么问我呢？去问那些听过我讲话的人，我所说的，他们都知道。”","notes":[]},{"n":22,"t":"耶稣说了这些话，旁边站着的一个警卫打了他一耳光，说：“你这样回答大祭司吗？”","notes":[]},{"n":23,"t":"耶稣回答他：“假如我说的不对，你指证不对的地方；假如我说的对，你为什么打我呢？”","notes":[]},{"n":24,"t":"于是亚那把耶稣绑着押解到大祭司该亚法那里。","notes":[]},{"n":25,"t":"西门．彼得正站着取暖，有人对他说：“你不也是他的门徒吗？”彼得不承认，说：“我不是。”","notes":[],"heads":["彼得再次不认耶稣"]},{"n":26,"t":"大祭司的一个仆人，是被彼得削掉耳朵那人的亲属，说：“我不是看见你同他在园子里吗？”","notes":[]},{"n":27,"t":"彼得又不承认，立刻鸡就叫了。","notes":[]},{"n":28,"t":"他们把耶稣从该亚法那里押解到总督府。那时是清早。他们自己却不进总督府，恐怕染了污秽，不能吃逾越节的宴席。","notes":[],"heads":["耶稣在彼拉多面前受审"]},{"n":29,"t":"于是彼拉多出来，到他们那里，说：“你们告这人是为什么事呢？”","notes":[]},{"n":30,"t":"他们回答他说：“这人若不作恶，我们就不会把他交给你了。”","notes":[]},{"n":31,"t":"彼拉多对他们说：“你们自己带他去，按着你们的律法问他吧！”犹太人说：“我们没有杀人的权柄。”","notes":[]},{"n":32,"t":"这是要应验耶稣所说，指自己将要怎样死的话。","notes":[]},{"n":33,"t":"于是彼拉多又进了总督府，叫耶稣来，对他说：“你是犹太人的王吗？”","notes":[]},{"n":34,"t":"耶稣回答：“这话是你说的，还是别人论到我时对你说的呢？”","notes":[]},{"n":35,"t":"彼拉多回答：“难道我是犹太人吗？你的同胞和祭司长把你交给我。你做了什么事呢？”","notes":[]},{"n":36,"t":"耶稣回答：“我的国不属于这世界；我的国若属于这世界，我的部下就会为我战斗，使我不至于被交给犹太人。只是我的国不属于这世界。”","notes":[]},{"n":37,"t":"于是彼拉多对他说：“那么，你是王了？”耶稣回答：“是你说我是王。我为此而生，也为此来到世界，为了给真理作见证。凡属真理的人都听我的话。”","notes":[]},{"n":38,"t":"彼拉多对他说：“真理是什么呢？”说了这话，彼拉多又出来到犹太人那里，对他们说：“我查不出他有什么罪状。","notes":[]},{"n":39,"t":"但你们有个规矩，在逾越节要我给你们释放一个人，你们要我给你们释放这犹太人的王吗？”","notes":[]},{"n":40,"t":"他们又再喊着说：“不要这人！要巴拉巴！”这巴拉巴是个强盗。","notes":[]}]},"19":{"heading":"耶稣被钉十字架","verses":[{"n":1,"t":"于是，彼拉多命令把耶稣带去鞭打了。","notes":[]},{"n":2,"t":"士兵用荆棘编了冠冕，戴在他头上，给他穿上紫袍，","notes":[]},{"n":3,"t":"又走到他面前，说：“万岁，犹太人的王！”他们就打他耳光。","notes":[]},{"n":4,"t":"彼拉多又出来对众人说：“看，我带他出来见你们，让你们知道我查不出他有什么罪状。”","notes":[]},{"n":5,"t":"耶稣出来，戴着荆棘冠冕，穿着紫袍。彼拉多对他们说：“看哪，这个人！”","notes":[]},{"n":6,"t":"祭司长和圣殿警卫看见他，就喊着说：“钉十字架！钉十字架！”彼拉多对他们说：“你们自己把他带去钉十字架吧！我查不出他有什么罪状。”","notes":[]},{"n":7,"t":"犹太人回答他：“我们有律法，按照律法，他是该死的，因为他自以为是神的儿子。”","notes":[]},{"n":8,"t":"彼拉多听见这话，越发害怕，","notes":[]},{"n":9,"t":"又进了总督府，对耶稣说：“你是哪里来的？”耶稣却不回答。","notes":[]},{"n":10,"t":"于是彼拉多对他说：“你不对我说话吗？难道你不知道我有权柄释放你，也有权柄把你钉十字架吗？”","notes":[]},{"n":11,"t":"耶稣回答他：“若不是从上头赐给你的，你就毫无权柄办我，所以，把我交给你的那人罪更重了。”","notes":[]},{"n":12,"t":"从此，彼拉多想要释放耶稣，无奈犹太人喊着说：“你若释放这个人，你就不是凯撒的忠臣。凡自立为王的就是背叛凯撒。”","notes":["“忠臣”：原文直译“朋友”。"]},{"n":13,"t":"彼拉多听见这些话，就带耶稣出来，到了一个地方，叫“铺华石处”，希伯来话叫厄巴大，就在那里坐堂。","notes":[]},{"n":14,"t":"那日是逾越节的预备日，约在正午。彼拉多对犹太人说：“看哪，你们的王！”","notes":[]},{"n":15,"t":"他们就喊着：“除掉他！除掉他！把他钉十字架！”彼拉多对他们说：“要我把你们的王钉十字架吗？”祭司长回答：“除了凯撒，我们没有王。”","notes":[]},{"n":16,"t":"于是彼拉多把耶稣交给他们去钉十字架。他们就把耶稣带了去。","notes":[]},{"n":17,"t":"耶稣背着自己的十字架出来，到了一个地方，名叫“髑髅地”，希伯来话叫各各他。","notes":[]},{"n":18,"t":"他们就在那里把他钉在十字架上，还有两个人和他一同被钉，一边一个，耶稣在中间。","notes":[]},{"n":19,"t":"彼拉多又写了一个牌子，钉在十字架上，写的是：“犹太人的王，拿撒勒人耶稣。”","notes":[]},{"n":20,"t":"有许多犹太人念这牌子，因为耶稣被钉十字架的地方靠近城，而且牌子是用希伯来、罗马、希腊三种文字写的。","notes":[]},{"n":21,"t":"犹太人的祭司长就对彼拉多说：“不要写‘犹太人的王’，要写‘那人说：我是犹太人的王’。”","notes":[]},{"n":22,"t":"彼拉多回答：“我写了就写了。”","notes":[]},{"n":23,"t":"士兵把耶稣钉在十字架上以后，把他的衣服拿来分为四份，每人一份。他们又拿他的内衣，这件内衣没有缝，是上下一片织成的。","notes":[]},{"n":24,"t":"他们就彼此说：“我们不要撕开，我们抽签，看是谁的。”这要应验经上的话说：“他们分了我的外衣，为我的内衣抽签。”士兵果然做了这些事。","notes":[]},{"n":25,"t":"站在耶稣十字架旁边的，有他的母亲、姨母、革罗罢的妻子马利亚，和抹大拉的马利亚。","notes":[]},{"n":26,"t":"耶稣见母亲和他所爱的那门徒站在旁边，就对母亲说：“母亲，看，你的儿子！”","notes":["“母亲”：原文直译“妇人”。"]},{"n":27,"t":"又对那门徒说：“看，你的母亲！”从那刻起，那门徒就接她到自己家里去了。","notes":[]},{"n":28,"t":"这事以后，耶稣知道各样的事已经成了，为使经上的话应验，就说：“我渴了。”","notes":[],"heads":["耶稣之死"]},{"n":29,"t":"有一个盛满了醋的罐子放在那里，他们就拿海绵蘸满了醋，绑在牛膝草上，送到他嘴边。","notes":[]},{"n":30,"t":"耶稣尝了那醋，说：“成了！”就低下头，断了气。","notes":["“断了气”或译“交上了灵”。"]},{"n":31,"t":"因为这日是预备日，又因为那安息日是个大日子，犹太人就来求彼拉多叫人打断他们的腿，把他们搬走，免得尸首在安息日留在十字架上。","notes":[],"heads":["耶稣的肋旁被刺"]},{"n":32,"t":"于是士兵来，把第一个人的腿，和与耶稣同钉的另一个人的腿，都打断了。","notes":[]},{"n":33,"t":"当他们来到耶稣那里，见他已经死了，就没有打断他的腿。","notes":[]},{"n":34,"t":"然而有一个士兵拿枪扎他的肋旁，立刻有血和水流出来。","notes":[]},{"n":35,"t":"看见这事的人作了见证—他的见证是真的，他知道自己所说的是真的—好让你们也信。","notes":[]},{"n":36,"t":"这些事发生，为要应验经上的话：“他的骨头一根也不可折断。”","notes":[]},{"n":37,"t":"另有经文也说：“他们要仰望自己所扎的人。”","notes":[]},{"n":38,"t":"这些事以后，亚利马太的约瑟来求彼拉多，要把耶稣的身体领去。他是耶稣的门徒，只因怕犹太人，就暗地里作门徒。彼拉多准许了，他就把耶稣的身体领走。","notes":[],"heads":["耶稣的安葬"]},{"n":39,"t":"尼哥德慕也来了，就是先前夜里去见耶稣的那位，他带着约一百斤的没药和沉香。","notes":[]},{"n":40,"t":"他们照犹太人丧葬的规矩，用细麻布加上香料，把耶稣的身体裹好了。","notes":[]},{"n":41,"t":"在耶稣钉十字架的地方有一个园子，园子里有一座新墓穴，是从来没有葬过人的。","notes":[]},{"n":42,"t":"因为那天是犹太人的预备日，而那坟墓又在附近，他们就把耶稣安放在那里。","notes":[]}]},"20":{"heading":"耶稣复活","verses":[{"n":1,"t":"七日的第一日清早，天还黑的时候，抹大拉的马利亚来到坟墓，看见石头已从坟墓挪开了，","notes":[]},{"n":2,"t":"就跑来见西门．彼得和耶稣所爱的那个门徒，对他们说：“有人从坟墓里把主移走了，我们不知道他们把他放在哪里。”","notes":[]},{"n":3,"t":"彼得和那门徒就出来，往坟墓去。","notes":[]},{"n":4,"t":"两个人同跑，那门徒比彼得跑得快，先到了坟墓，","notes":[]},{"n":5,"t":"低头往里看，看见细麻布还放在那里，只是没有进去。","notes":[]},{"n":6,"t":"西门．彼得随后也到了，进了坟墓，看见细麻布放在那里，","notes":[]},{"n":7,"t":"又看见耶稣的裹头巾没有和细麻布放在一起，是另在一处卷着。","notes":[]},{"n":8,"t":"然后先到坟墓的那门徒也进去，他看见就信了。","notes":[]},{"n":9,"t":"他们还不明白圣经所说耶稣必须从死人中复活的意思。","notes":[]},{"n":10,"t":"于是两个门徒回自己的住处去了。","notes":[]},{"n":11,"t":"马利亚却站在坟墓外面哭。她哭的时候，低头往坟墓里看，","notes":[],"heads":["向抹大拉的马利亚显现"]},{"n":12,"t":"看见两个天使穿着白衣，在安放耶稣身体的地方坐着，一个在头，一个在脚。","notes":[]},{"n":13,"t":"天使对她说：“妇人，你为什么哭？”她对他们说：“因为有人把我主移走了，我不知道他们把他放在哪里。”","notes":[]},{"n":14,"t":"说了这些话，她转过身来，看见耶稣站在那里，却不知道他是耶稣。","notes":[]},{"n":15,"t":"耶稣问她：“妇人，你为什么哭？你找谁？”马利亚以为他是看园子的，就对他说：“先生，若是你把他移了去，请告诉我，你把他放在哪里，我去把他移回来。”","notes":[]},{"n":16,"t":"耶稣对她说：“马利亚。”马利亚转过身来，用希伯来话对他说：“拉波尼！”（“拉波尼”就是老师的意思。）","notes":[]},{"n":17,"t":"耶稣对她说：“不要拉住我，因为我还没有升上去见我的父。你到我弟兄那里去告诉他们，我要升上去见我的父，也是你们的父，见我的神，也是你们的神。”","notes":[]},{"n":18,"t":"抹大拉的马利亚就向门徒报信：“我已经看见了主。”她又把主对她说的话告诉他们。","notes":[]},{"n":19,"t":"那日（就是七日的第一日）晚上，门徒因怕犹太人，所在的地方门都关了。耶稣来，站在当中，对他们说：“愿你们平安！”","notes":[],"heads":["向门徒显现"]},{"n":20,"t":"说了这话，他把手和肋旁给他们看。门徒一看见主就喜乐了。","notes":[]},{"n":21,"t":"于是耶稣又对他们说：“愿你们平安！父怎样差遣了我，我也照样差遣你们。”","notes":[]},{"n":22,"t":"说了这话，他向他们吹一口气，说：“领受圣灵吧！","notes":[]},{"n":23,"t":"你们赦免谁的罪，谁的罪就得赦免；你们不赦免谁的罪，谁的罪就不得赦免。”","notes":[]},{"n":24,"t":"那十二使徒中，有个叫低土马的多马，耶稣来的时候，他没有和他们在一起。","notes":[],"heads":["耶稣和多马"]},{"n":25,"t":"其他的门徒就对他说：“我们已经看见主了。”多马却对他们说：“除非我看见他手上的钉痕，用我的指头探入那钉痕，用我的手探入他的肋旁，我绝不信。”","notes":[]},{"n":26,"t":"过了八日，门徒又在屋里，多马也和他们在一起。门都关了，耶稣来，站在当中，说：“愿你们平安！”","notes":[]},{"n":27,"t":"然后他对多马说：“把你的指头伸到这里来，看看我的手；把你的手伸过来，探入我的肋旁。不要疑惑，总要信！”","notes":[]},{"n":28,"t":"多马回答，对他说：“我的主！我的神！”","notes":[]},{"n":29,"t":"耶稣对他说：“你因为看见了我才信吗？那没有看见却信的有福了。”","notes":[]},{"n":30,"t":"耶稣在他门徒面前另外行了许多神迹，没有记录在这书上。","notes":[],"heads":["本书的目的"]},{"n":31,"t":"但记载这些事是要使你们信耶稣是基督，是神的儿子，并且使你们信他，好因着他的名得生命。","notes":["“使你们信”：有古卷是“使你们继续信”。"]}]},"21":{"heading":"耶稣向七个门徒显现","verses":[{"n":1,"t":"这些事以后，耶稣在提比哩亚海边又向门徒显现。他怎样显现记在下面。","notes":[]},{"n":2,"t":"西门．彼得、叫低土马的多马、加利利的迦拿人拿但业、西庇太的两个儿子，和另外两个门徒，都在一起。","notes":[]},{"n":3,"t":"西门．彼得对他们说：“我打鱼去。”他们对他说：“我们也和你一起去。”他们就出去，上了船；那一夜并没有打着什么。","notes":[]},{"n":4,"t":"天刚亮的时候，耶稣站在岸上，门徒却不知道他是耶稣。","notes":[]},{"n":5,"t":"耶稣就对他们说：“孩子们！你们有吃的没有？”他们回答他：“没有。”","notes":[]},{"n":6,"t":"耶稣对他们说：“你们把网撒在船的右边，就会得到。”于是他们撒下网去，竟拉不上来了，因为鱼很多。","notes":[]},{"n":7,"t":"耶稣所爱的那门徒对彼得说：“是主！”那时西门．彼得赤着身子，一听见是主，就束上外衣，跳进海里。","notes":[]},{"n":8,"t":"其余的门徒因离岸不远，约有二百肘，就坐着小船把那网鱼拉过来。","notes":[]},{"n":9,"t":"他们上了岸，看见那里有炭火，上面有鱼和饼。","notes":[]},{"n":10,"t":"耶稣对他们说：“把刚才打的鱼拿几条来。”","notes":[]},{"n":11,"t":"西门．彼得就上船，把网拉到岸上，网里满了大鱼，共一百五十三条；虽然鱼这样多，网却没有破。","notes":[]},{"n":12,"t":"耶稣对他们说：“你们来吃早饭。”门徒中没有一个敢问他：“你是谁？”因为他们知道他是主。","notes":[]},{"n":13,"t":"耶稣走过来，拿饼给他们，也照样拿鱼给他们。","notes":[]},{"n":14,"t":"耶稣从死人中复活后向门徒显现，这是第三次。","notes":[]},{"n":15,"t":"他们吃完了早饭，耶稣对西门．彼得说：“约翰的儿子西门，你爱我比这些更深吗？”彼得对他说：“主啊，是的，你知道我爱你。”耶稣说：“你喂养我的小羊。”","notes":["“约翰”在马太福音16．17称为“约拿”。"],"heads":["三问彼得"]},{"n":16,"t":"耶稣第二次又对他说：“约翰的儿子西门，你爱我吗？”彼得对他说：“主啊，是的，你知道我爱你。”耶稣说：“你牧养我的羊。”","notes":[]},{"n":17,"t":"耶稣第三次对他说：“约翰的儿子西门，你爱我吗？”彼得因为耶稣第三次对他说“你爱我吗”，就忧愁，对耶稣说：“主啊，你无所不知，你知道我爱你。”耶稣说：“你喂养我的羊。","notes":[]},{"n":18,"t":"我实实在在地告诉你，你年轻的时候，自己束上带子，随意往来；但年老的时候，你要伸出手来，别人要把你束上，带你到不愿意去的地方。”","notes":[]},{"n":19,"t":"耶稣说这话，是指彼得会怎样死来荣耀神。说了这话，耶稣对他说：“你跟从我吧！”","notes":[]},{"n":20,"t":"彼得转过身来，看见耶稣所爱的那门徒跟着，就是在晚餐时靠着耶稣胸膛说“主啊，出卖你的是谁”的那门徒。","notes":[],"heads":["耶稣和他所爱的那门徒"]},{"n":21,"t":"彼得看见他，就问耶稣：“主啊，这个人怎样呢？”","notes":[]},{"n":22,"t":"耶稣对他说：“假如我要他等到我来的时候还在，跟你有什么关系呢？你跟从我吧！”","notes":[]},{"n":23,"t":"于是这话在弟兄中间流传，说那门徒不死。其实，耶稣不是说他不死，而是对彼得说：“假如我要他等到我来的时候还在，跟你有什么关系呢？”","notes":["有古卷没有“跟你有什么关系呢？”"]},{"n":24,"t":"这门徒就是为这些事作见证、并且记载这些事的，我们知道他的见证是真的。","notes":[]},{"n":25,"t":"耶稣所行的事还有许多，若是一一都写出来，我想，就是全世界也容不下所要写的书。","notes":[]}]}},"ACT":{"1":{"heading":"赐圣灵的应许","verses":[{"n":1,"t":"提阿非罗啊，我在第一本书中已论到耶稣从开头所做和所教导的一切事，","notes":[]},{"n":2,"t":"直到他藉着圣灵吩咐所拣选的使徒后，被接上升的日子为止。","notes":[]},{"n":3,"t":"他受害以后，用许多确据向使徒显明自己是活着的，在四十天之中向他们显现，并讲说神国的事。","notes":[]},{"n":4,"t":"耶稣和他们聚集的时候，嘱咐他们说：“不要离开耶路撒冷，但要等候父的应许，就是你们听见我说过的。","notes":[]},{"n":5,"t":"约翰是用水施洗，但过了不多几天，你们要在圣灵里受洗。”","notes":[]},{"n":6,"t":"他们聚集的时候，问耶稣：“主啊，你就要在这时候复兴以色列国吗？”","notes":[],"heads":["耶稣升天"]},{"n":7,"t":"耶稣对他们说：“父凭着自己的权柄所定的时候和日期，不是你们可以知道的。","notes":[]},{"n":8,"t":"但圣灵降临在你们身上，你们就必得着能力，并要在耶路撒冷、犹太全地和撒玛利亚，直到地极，作我的见证。”","notes":[]},{"n":9,"t":"说了这些话，他们正看的时候，他被接上升，有一朵云彩从他们眼前把他接去。","notes":[]},{"n":10,"t":"他升上去的时候，他们定睛望天，看哪，有两个人身穿白衣站在他们旁边，","notes":[]},{"n":11,"t":"说：“加利利人哪，你们为什么站着望天呢？这离开你们被接升天的耶稣，你们见他怎样升上天去，他也要怎样来临。”","notes":[]},{"n":12,"t":"有一座山，名叫橄榄山，离耶路撒冷不远，有安息日可行走的路程。那时，门徒从那里回耶路撒冷去，","notes":["“安息日…路程”：约二千肘或一公里。"],"heads":["接替犹大职分的人"]},{"n":13,"t":"他们一进城，就上了所住的楼房；在那里有彼得、约翰、雅各、安得烈、腓力、多马、巴多罗买、马太、亚勒腓的儿子雅各、激进党的西门，和雅各的儿子犹大。","notes":["“儿子”或译“兄弟”。"]},{"n":14,"t":"这些人和几个妇人，包括耶稣的母亲马利亚，和耶稣的兄弟，都同心合意地恒切祷告。","notes":[]},{"n":15,"t":"那时，有许多人聚会，约有一百二十名，彼得在弟兄中间站起来，说：","notes":[]},{"n":16,"t":"“诸位弟兄，圣经的话必须应验。圣经中，圣灵曾藉大卫的口预先说到那领人来拿耶稣的犹大；","notes":[]},{"n":17,"t":"他本来算是我们中的一个，并且得了这一份使徒的职任。","notes":[]},{"n":18,"t":"这人用他不义的代价买了一块田，以后身子仆倒，肚腹崩裂，肠子都流出来。","notes":[]},{"n":19,"t":"住在耶路撒冷的人都知道这事，所以按着他们当地的话把那块田叫亚革大马，就是“血田”的意思。","notes":[]},{"n":20,"t":"因为《诗篇》上写着：“愿他的住处变为废墟，无人在内居住。”又说：“愿别人得他的职分。”","notes":[]},{"n":21,"t":"所以，主耶稣在我们中间出入的整段时间，就是从约翰施洗起，直到主离开我们被接上升的日子为止，必须从那常与我们一起的人中，立一位与我们同作耶稣复活的见证。”","notes":[],"end":22},{"n":23,"t":"于是他们推举两个人，就是那叫巴撒巴，又称为犹士都的约瑟，和马提亚。","notes":[]},{"n":24,"t":"众人祷告说：“主啊，你知道万人的心，求你从这两个人中指明你所拣选的是哪一位，","notes":[]},{"n":25,"t":"去得这使徒的职任；这职位犹大已经丢弃，往自己的地方去了。”","notes":[]},{"n":26,"t":"于是众人为他们摇签，摇出马提亚来；他就和十一个使徒同列。","notes":[]}]},"2":{"heading":"圣灵降临","verses":[{"n":1,"t":"五旬节那日到了，他们全都聚集在一起。","notes":[]},{"n":2,"t":"忽然，有响声从天上下来，好像一阵大风吹过，充满了他们所坐的整座屋子；","notes":[]},{"n":3,"t":"又有舌头如火焰向他们显现，分开落在他们每个人身上。","notes":[]},{"n":4,"t":"他们都被圣灵充满，就按着圣灵所赐的口才说起别国的话来。","notes":[]},{"n":5,"t":"那时，有从天下各国来的虔诚的犹太人，住在耶路撒冷。","notes":[]},{"n":6,"t":"这声音一响，许多人都来聚集，各人因为听见门徒用他们各自的乡谈说话，就甚纳闷，","notes":[]},{"n":7,"t":"都诧异惊奇说：“看哪，这些说话的不都是加利利人吗？","notes":[]},{"n":8,"t":"我们每个人怎么听见他们说我们生来所用的乡谈呢？","notes":[]},{"n":9,"t":"我们帕提亚人、玛代人、以拦人，和住在美索不达米亚、犹太、加帕多家、本都、亚细亚、","notes":[]},{"n":10,"t":"弗吕家、旁非利亚、埃及的人，并靠近古利奈的利比亚一带地方的人，侨居的罗马人，","notes":[]},{"n":11,"t":"包括犹太人和皈依犹太教的人， 克里特人和阿拉伯人，都听见他们用我们的乡谈讲论神的大作为。”","notes":[]},{"n":12,"t":"众人就都惊奇困惑，彼此说：“这是什么意思呢？”","notes":[]},{"n":13,"t":"还有人讥诮，说：“他们是灌满了新酒吧！”","notes":[]},{"n":14,"t":"彼得和十一个使徒站起来，他就高声向众人说：“犹太人和所有住在耶路撒冷的人哪，这件事你们要知道，要侧耳听我的话。","notes":[],"heads":["彼得在五旬节的演讲"]},{"n":15,"t":"这些人并不像你们所想的喝醉了，因为现在才早晨九点钟。","notes":[]},{"n":16,"t":"这正是藉着先知约珥所说的：","notes":[]},{"n":17,"t":"‘神说：在末后的日子，我要将我的灵浇灌凡血肉之躯的。你们的儿女要说预言；你们的少年要见异象；你们的老人要做异梦。","notes":[]},{"n":18,"t":"在那些日子，我要把我的灵浇灌，甚至给我的仆人和婢女，他们要说预言。","notes":[]},{"n":19,"t":"在天上，我要显出奇事，在地下，我要显出神迹，有血，有火，有烟雾。","notes":[]},{"n":20,"t":"太阳要变为黑暗，月亮要变为血，这都在主大而光荣的日子未到以前。","notes":[]},{"n":21,"t":"那时，凡求告主名的都必得救。’","notes":[]},{"n":22,"t":"“以色列人哪，你们要听我这些话：拿撒勒人耶稣就是神以异能、奇事、神迹向你们证明出来的人，这些事是神藉着他在你们中间施行，正如你们自己知道的。","notes":[]},{"n":23,"t":"他既按着神确定的旨意和预知被交与人，你们就藉着不法之人的手把他钉在十字架上，杀了。","notes":[]},{"n":24,"t":"神却将死的痛苦解除，使他复活了，因为他原不能被死拘禁。","notes":[]},{"n":25,"t":"大卫指着他说：‘我看见主常在我眼前，他在我右边，使我不至于动摇。","notes":["“看见”：原文直译“预见”。"]},{"n":26,"t":"所以我心里欢喜，我的舌头快乐，而且我的肉身要安居在指望中。","notes":[]},{"n":27,"t":"因你必不将我的灵魂撇在阴间，也不让你的圣者见朽坏。","notes":[]},{"n":28,"t":"你已将生命的道路指示我，必使我在你面前充满快乐。’","notes":[]},{"n":29,"t":"“诸位弟兄，先祖大卫的事，我可以坦然地对你们说：他死了，也埋葬了，而且他的坟墓直到今日还在我们这里。","notes":[]},{"n":30,"t":"既然大卫是先知，他知道神曾向他起誓，要从他的后裔中立一位坐在他的宝座上。","notes":[]},{"n":31,"t":"他预先看见了，就讲论基督的复活，说：‘他不被撇在阴间；他的肉身也不见朽坏。’","notes":[]},{"n":32,"t":"这耶稣，神已经使他复活了，我们都是这事的见证人。","notes":[]},{"n":33,"t":"他既被高举在神的右边，又从父受了所应许的圣灵，就把你们所看见所听见的，浇灌下来。","notes":[]},{"n":34,"t":"大卫并没有升到天上，但他自己说：‘主对我主说：你坐在我的右边，","notes":[]},{"n":35,"t":"等我使你的仇敌作你的脚凳。’","notes":[]},{"n":36,"t":"故此，以色列全家当确实知道，你们钉在十字架上的这位耶稣，神已经立他为主，为基督了。”","notes":[]},{"n":37,"t":"众人听见这话，觉得扎心，就对彼得和其余的使徒说：“诸位弟兄，我们该怎样做呢？”","notes":[]},{"n":38,"t":"彼得对他们说：“你们各人要悔改，奉耶稣基督的名受洗，使你们的罪得赦免，就会领受所赐的圣灵。","notes":[]},{"n":39,"t":"因为这应许是给你们和你们的儿女，并一切在远方的人，就是给所有主—我们的神所召来的人。”","notes":[]},{"n":40,"t":"彼得还用更多别的话作见证，劝勉他们说：“你们当救自己脱离这弯曲的世代。”","notes":[]},{"n":41,"t":"于是领受他话的人，都受了洗；那一天，门徒约添了三千人。","notes":[]},{"n":42,"t":"他们都专注于使徒的教导和彼此的团契，擘饼和祈祷。","notes":[]},{"n":43,"t":"众人都心存敬畏；使徒们又行了许多奇事神迹。","notes":["有古卷加“在耶路撒冷”。"],"heads":["信徒的团契生活"]},{"n":44,"t":"信的人都聚在一处，凡物公用，","notes":[]},{"n":45,"t":"又卖了田产和家业，照每一个人所需要的分给他们。","notes":[]},{"n":46,"t":"他们天天同心合意恒切地在圣殿里敬拜，且在家中擘饼，存着欢喜坦诚的心用饭，","notes":["“在家中”：原文或译“挨家挨户”。"]},{"n":47,"t":"赞美神，得全体百姓的喜爱。主将得救的人天天加给他们。","notes":[]}]},"3":{"heading":"圣殿门口的瘸腿者得医治","verses":[{"n":1,"t":"下午三点钟祷告的时候，彼得和约翰上圣殿去。","notes":[]},{"n":2,"t":"一个从母腹里就是瘸腿的人正被人抬来，他们天天把他放在圣殿的一个叫美门的门口，求进圣殿的人施舍。","notes":[]},{"n":3,"t":"他看见彼得、约翰将要进圣殿，就求他们施舍。","notes":[]},{"n":4,"t":"彼得和约翰定睛看他，彼得说：“看着我们！”","notes":[]},{"n":5,"t":"那人就注目看他们，指望从他们得着什么。","notes":[]},{"n":6,"t":"彼得却说：“金银我都没有，但我把我有的给你：奉拿撒勒人耶稣基督的名起来行走！”","notes":["有古卷没有“起来”。"]},{"n":7,"t":"于是彼得拉着他的右手，扶他起来；他的脚和踝骨立刻健壮了，","notes":[]},{"n":8,"t":"就跳起来，站着，又开始行走。他跟他们进了圣殿，边走边跳，赞美神。","notes":[]},{"n":9,"t":"百姓都看见他又行走，又赞美神，","notes":[]},{"n":10,"t":"认得他是那素常坐在圣殿的美门口求人施舍的，就因他所遇到的事满心惊讶诧异。","notes":[]},{"n":11,"t":"那人正在称为所罗门的廊下，拉住彼得和约翰，大家都觉得很惊讶，一齐跑到他们那里。","notes":[],"heads":["彼得在所罗门廊下的演讲"]},{"n":12,"t":"彼得看见，就对百姓说：“以色列人哪，为什么因这事而惊讶呢？为什么定睛看我们，以为我们凭自己的能力和虔诚使这人行走呢？","notes":[]},{"n":13,"t":"亚伯拉罕的神、以撒的神、雅各的神，就是我们列祖的神，已经荣耀了他的仆人耶稣，这耶稣就是你们交付官府的那位，彼拉多决定要释放他时，你们却在彼拉多面前弃绝了他。","notes":[]},{"n":14,"t":"你们弃绝了那圣洁公义者，反而要求释放一个凶手给你们。","notes":[]},{"n":15,"t":"你们杀了那生命的创始者，神却叫他从死人中复活；我们都是这事的见证人。","notes":[]},{"n":16,"t":"因信他的名，他的名使你们所看见所认识的这人健壮了；正是他所赐的信心使这人在你们众人面前完全好了。","notes":[]},{"n":17,"t":"“如今，弟兄们，我知道你们做这事是出于无知，你们的官长也是如此。","notes":[]},{"n":18,"t":"但神藉着众先知的口预先宣告过基督将要受害的事，就这样应验了。","notes":[]},{"n":19,"t":"所以，你们当悔改归正，使你们的罪得以涂去，","notes":[]},{"n":20,"t":"这样，那安舒的日子就必从主面前来到；主也必差遣所预定给你们的基督耶稣来临。","notes":[]},{"n":21,"t":"他必须留在天上，直到万物复兴的时候，就是神自古藉着圣先知的口所说的。","notes":[]},{"n":22,"t":"摩西曾说：‘主—你们的神要从你们弟兄中给你们兴起一位先知像我，凡他向你们所说的一切，你们都要听从。","notes":["有古卷是“我们”。"]},{"n":23,"t":"凡不听从那先知的，必将从民中灭绝。’","notes":[]},{"n":24,"t":"从撒母耳以来和后继的众先知，凡说预言的，也都曾宣告这些日子。","notes":[]},{"n":25,"t":"你们是先知的子孙，也是神与你们祖宗所立之约的子孙，就是对亚伯拉罕说：‘地上万族都将因你的后裔得福。’","notes":["有古卷是“我们”。"]},{"n":26,"t":"神既兴起他的仆人，就先差他到你们这里来，赐福给你们，使各人回转，离开你们的邪恶。”","notes":[]}]},"4":{"heading":"彼得和约翰在议会前被查问","verses":[{"n":1,"t":"彼得和约翰正向百姓说话的时候，祭司们、守殿官和撒都该人来了，","notes":[]},{"n":2,"t":"就很烦恼，因为使徒们教导百姓，传扬在耶稣的事上证明有死人复活，","notes":[]},{"n":3,"t":"于是下手拿住他们；因为天已经晚了，就把他们押在拘留所到第二天。","notes":[]},{"n":4,"t":"但听道的人有许多信了，男人的数目约有五千。","notes":[]},{"n":5,"t":"第二天，官长、长老和文士在耶路撒冷聚集，","notes":[]},{"n":6,"t":"又有亚那大祭司、该亚法、约翰、亚历山大，和大祭司的亲族都在那里。","notes":[]},{"n":7,"t":"他们叫使徒站在中间，问他们：“你们凭什么能力，奉谁的名做这事呢？”","notes":[]},{"n":8,"t":"那时，彼得被圣灵充满，对他们说：“民间的官长和长老啊，","notes":[]},{"n":9,"t":"倘若今日我们被查问是因为在残障的人身上所行的善事，就是这人怎么得了痊愈，","notes":[]},{"n":10,"t":"那么，你们大家和以色列全民都当知道，站在你们面前的这人得痊愈，是因你们所钉在十字架、神使他从死人中复活的拿撒勒人耶稣基督的名。","notes":[]},{"n":11,"t":"这位耶稣是：‘你们匠人所丢弃的石头，已成了房角的头块石头。’","notes":[]},{"n":12,"t":"除他以外，别无拯救，因为在天下人间，没有赐下别的名，我们可以靠着得救。”","notes":[]},{"n":13,"t":"他们见彼得、约翰的胆量，又看出他们原是没有学问的平民，就很惊讶，认出他们曾是跟耶稣一起的；","notes":[]},{"n":14,"t":"又看见那治好了的人和他们一同站着，就无话可驳。","notes":[]},{"n":15,"t":"于是他们吩咐他们两人从议会退出，就彼此商议，","notes":[]},{"n":16,"t":"说：“我们当怎样办这两个人呢？因为他们诚然行了一件明显的神迹，凡住在耶路撒冷的人都知道，我们也不能否认。","notes":[]},{"n":17,"t":"但为避免这事越发在民间传扬，我们必须威吓他们，叫他们不可再奉这名对任何人讲论。”","notes":[]},{"n":18,"t":"于是他们叫了两人来，禁止他们，再不可奉耶稣的名讲论或教导人。","notes":[]},{"n":19,"t":"彼得和约翰回答他们说：“听从你们，不听从神，在神面前合理不合理，你们自己判断吧！","notes":[]},{"n":20,"t":"我们所看见所听见的，我们不能不说。”","notes":[]},{"n":21,"t":"官长为百姓的缘故，想不出任何法子惩罚他们，只好威吓一番就把他们释放了；这是因众人为了所行的奇事都归荣耀与神。","notes":[]},{"n":22,"t":"原来经历这神迹医好的人有四十多岁了。","notes":[]},{"n":23,"t":"二人既被释放，就到自己的人那里去，把祭司长和长老所说的话都告诉他们。","notes":[],"heads":["门徒求主赐胆量"]},{"n":24,"t":"他们听见了，就同心合意地高声向神说：“主宰啊！你是那创造天、地、海和其中万物的；","notes":[]},{"n":25,"t":"你曾藉着圣灵托你仆人—我们祖宗大卫的口说：‘外邦为什么扰动？万民为什么谋算虚妄的事？","notes":[]},{"n":26,"t":"地上的君王都站稳，臣宰也聚集一处，要对抗主，对抗主的受膏者。’","notes":["“受膏者”或译“基督”。"]},{"n":27,"t":"希律和本丢．彼拉多，同外邦人和以色列民，果然在这城里聚集，要攻打你所膏的圣仆耶稣，","notes":[]},{"n":28,"t":"做了你手和你旨意所预定必成就的事。","notes":[]},{"n":29,"t":"主啊，现在求你鉴察，他们的威吓，使你仆人放胆讲你的道，","notes":[]},{"n":30,"t":"伸出你的手来，让医治、神迹、奇事藉着你圣仆耶稣的名行出来。”","notes":[]},{"n":31,"t":"他们祷告完了，聚会的地方震动；他们都被圣灵充满，放胆传讲神的道。","notes":[]},{"n":32,"t":"许多信徒都一心一意，没有一人说他的任何东西是自己的，都是大家公用。","notes":[],"heads":["凡物公用"]},{"n":33,"t":"使徒以大能见证主耶稣复活；众人也都蒙了大恩。","notes":["“主耶稣”：有古卷是“主耶稣基督”。"]},{"n":34,"t":"他们当中没有一个缺乏的，因为凡有田产房屋的都卖了，把所卖的钱拿来，","notes":[]},{"n":35,"t":"放在使徒脚前，照每人所需要的，分给每人。","notes":[]},{"n":36,"t":"有一个利未人，名叫约瑟，使徒称他为巴拿巴（巴拿巴翻出来就是安慰之子），生在塞浦路斯。","notes":[]},{"n":37,"t":"他有田地，也卖了，把钱拿来，放在使徒脚前。","notes":[]}]},"5":{"heading":"亚拿尼亚和撒非喇","verses":[{"n":1,"t":"有一个人，名叫亚拿尼亚，同他的妻子撒非喇，卖了田产，","notes":[]},{"n":2,"t":"把钱私自留下一部分，他的妻子也知道，其余的部分拿来放在使徒脚前。","notes":[]},{"n":3,"t":"彼得说：“亚拿尼亚！为什么撒但充满了你的心，使你欺骗圣灵，把卖田地的钱私自留下一部分呢？","notes":[]},{"n":4,"t":"田地还没有卖，不是你自己的吗？既卖了，钱不是你作主吗？你怎么心里会想这样做呢？你不是欺骗人，是欺骗神！”","notes":[]},{"n":5,"t":"亚拿尼亚一听见这些话，就仆倒，断了气；所有听见的人都非常惧怕。","notes":[]},{"n":6,"t":"有些年轻人起来，把他裹好，抬出去埋葬了。","notes":[]},{"n":7,"t":"约过了三小时，他的妻子进来，还不知道所发生的事。","notes":[]},{"n":8,"t":"彼得对她说：“你告诉我，你们卖田地的钱就是这些吗？”她说：“就是这些。”","notes":[]},{"n":9,"t":"彼得对她说：“你们为什么同谋来试探主的灵呢？你看，埋葬你丈夫之人的脚已到门口，他们也要把你抬出去。”","notes":[]},{"n":10,"t":"她立刻仆倒在彼得脚前，断了气。那些年轻人进来，见她已经死了，就把她抬出去，埋在她丈夫旁边。","notes":[]},{"n":11,"t":"全教会和所有听见这些事的人都非常惧怕。","notes":[]},{"n":12,"t":"主藉使徒的手在民间行了许多神迹奇事；他们都同心合意地聚集在所罗门的廊下。","notes":[],"heads":["主藉使徒行许多神迹奇事"]},{"n":13,"t":"其余的人没有一个敢接近他们，百姓却尊重他们。","notes":[]},{"n":14,"t":"信主的人越发增添，连男带女都很多，","notes":[]},{"n":15,"t":"甚至有人将病人抬到街上，放在床上或褥子上，好让彼得走过来的时候，或者影子投在一些人身上。","notes":[]},{"n":16,"t":"还有许多人带着病人和被污灵缠磨的，从耶路撒冷四围的城镇来，他们全都得了医治。","notes":[]},{"n":17,"t":"于是，大祭司采取行动，他和他所有一起的人，就是撒都该派的人，满心忌恨，","notes":[],"heads":["使徒受迫害"]},{"n":18,"t":"就下手拿住使徒，把他们押在公共拘留所内。","notes":[]},{"n":19,"t":"但在夜间主的使者开了监门，领他们出来，说：","notes":[]},{"n":20,"t":"“你们去，站在圣殿里，把这生命的一切话讲给百姓听。”","notes":[]},{"n":21,"t":"使徒听了这话，天将亮的时候就进圣殿里去教导人。大祭司和他一起的人来了，叫齐议会的人和以色列人的众长老，然后派人到监牢里去把使徒提出来。","notes":[]},{"n":22,"t":"但差役到了，不见他们在监里，就回来禀报，","notes":[]},{"n":23,"t":"说：“我们看见监牢关得很紧，警卫也站在门外，但打开门来，里面一个人都不见。”","notes":[]},{"n":24,"t":"守殿官和祭司长听了这些话，心里困惑，不知这事将来如何。","notes":[]},{"n":25,"t":"有一个人来禀报说：“你们押在监里的人，现在站在圣殿里教导百姓。”","notes":[]},{"n":26,"t":"于是守殿官和差役去带使徒来，并没有用暴力，因为怕百姓用石头打他们。","notes":[]},{"n":27,"t":"他们把使徒带来了，就叫他们站在议会前。大祭司问他们，","notes":[]},{"n":28,"t":"说：“我们不是严严地禁止你们，不可奉这名教导人吗？看，你们倒把你们的道理充满了耶路撒冷，想要叫这人的血归到我们身上！”","notes":["“我们…教导人吗？”：有古卷是“我们严严地禁止你们不可奉这名教导人。”"]},{"n":29,"t":"彼得和众使徒回答：“我们必须顺从神，胜于顺从人。","notes":[]},{"n":30,"t":"你们挂在木头上杀害的耶稣，我们祖宗的神已经使他复活了。","notes":[]},{"n":31,"t":"神把他高举在自己的右边，使他作元帅，作救主，使以色列人得以悔改，并且罪得赦免。","notes":[]},{"n":32,"t":"我们是这些事的见证人；神赐给顺从的人的圣灵也为这些事作见证。”","notes":[]},{"n":33,"t":"议会的人听了极其恼怒，想要杀他们。","notes":[]},{"n":34,"t":"但有一个法利赛人，名叫迦玛列，是众百姓所敬重的律法教师，他在议会中站起来，吩咐人把使徒暂且带到外面去，","notes":[]},{"n":35,"t":"然后对众人说：“以色列人哪，对于这些人，你们应当小心怎样处理。","notes":[]},{"n":36,"t":"从前杜达出现，自命不凡，附从他的人数约有四百；他被杀后，附从他的人全都散了，归于无有。","notes":[]},{"n":37,"t":"此后，登记户籍的时候，又有加利利的犹大出现，引诱百姓跟从他，他也灭亡，附从他的人也都四散了。","notes":[]},{"n":38,"t":"现在，我劝你们不要管这些人，任凭他们吧！他们所谋所为若是出于人，必要败坏；","notes":[]},{"n":39,"t":"若是出于神，你们就不能败坏他们，恐怕你们倒是攻击神了。”议会的人被他说服了，","notes":[]},{"n":40,"t":"就叫使徒来，把他们打了，又吩咐他们不可奉耶稣的名讲道，然后把他们释放了。","notes":[]},{"n":41,"t":"他们欢欢喜喜地离开议会，因他们算配为这名受辱。","notes":[]},{"n":42,"t":"他们就每日在圣殿里，在家里，不住地教导人，传耶稣是基督的福音。","notes":["“在家里”：原文或译“挨家挨户”。"]}]},"6":{"heading":"拣选七人办理供给之事","verses":[{"n":1,"t":"那些日子，门徒增多，有说希腊话的犹太人向希伯来人发怨言，因为在日常的供给上忽略了他们的寡妇。","notes":[]},{"n":2,"t":"十二使徒叫众门徒来，说：“我们撇下神的道去管理饭食，是不合宜的。","notes":[]},{"n":3,"t":"所以弟兄们，当从你们中间选出七个有好名声、满有圣灵和智慧，我们派他们管理这事。","notes":[]},{"n":4,"t":"至于我们，我们要专注于祈祷和传道的事奉。”","notes":[]},{"n":5,"t":"这话使全会众都喜悦，就拣选了司提反—他是一个满有信心和圣灵的人；他们又拣选了腓利、伯罗哥罗、尼迦挪、提门、巴米拿，并皈依犹太教的安提阿人尼哥拉，","notes":[]},{"n":6,"t":"叫他们站在使徒面前，使徒祷告后，就为他们按手。","notes":[]},{"n":7,"t":"神的道兴旺起来；在耶路撒冷门徒数目增加得很多，也有许多祭司听从了这信仰。","notes":[]},{"n":8,"t":"司提反满有恩惠和能力，在民间行了大奇事和神迹。","notes":[],"heads":["司提反被捕"]},{"n":9,"t":"当时有从称为“自由人”会堂，并古利奈、亚历山大会堂来的人，还有些从基利家、亚细亚来的人，起来和司提反辩论。","notes":[]},{"n":10,"t":"司提反是以智慧和圣灵说话，众人抵挡不住，","notes":[]},{"n":11,"t":"就收买人来说：“我们听见他说亵渎摩西和神的话。”","notes":[]},{"n":12,"t":"他们又煽动百姓、长老和文士，就突然来捉拿他，把他带到议会去，","notes":[]},{"n":13,"t":"设下假见证，说：“这个人不断地说话，侮辱神圣的地方和律法。","notes":[]},{"n":14,"t":"我们曾听见他说，这拿撒勒人耶稣要毁坏这地方，也要改变摩西所交给我们的规矩。”","notes":[]},{"n":15,"t":"在议会里坐着的人都定睛看他，见他的面貌好像天使的面貌。","notes":[]}]},"7":{"heading":"司提反当众申诉","verses":[{"n":1,"t":"大祭司说：“果真有这些事吗？”","notes":[]},{"n":2,"t":"司提反说：“诸位父老弟兄请听！从前我们的祖宗亚伯拉罕在美索不达米亚，还没有住在哈兰的时候，荣耀的神向他显现，","notes":[]},{"n":3,"t":"对他说：‘你要离开本地和亲族，往我所要指示你的地去。’","notes":[]},{"n":4,"t":"他就离开迦勒底人的地方，住在哈兰。他父亲死了以后，神使他从那里搬到你们现在所住的地方。","notes":[]},{"n":5,"t":"在这里神并没有给他产业，连立足的地方都没有，但应许要将这地赐给他和他的后裔为业，虽然那时他还没有儿子。","notes":[]},{"n":6,"t":"神这样说：‘他的后裔必寄居外邦，那里的人要使他们作奴隶，苦待他们四百年。’","notes":[]},{"n":7,"t":"神又说：‘但我要惩罚使他们作奴隶的那国。以后他们要出来，在这地方事奉我。’","notes":[]},{"n":8,"t":"神又赐他割礼的约。于是亚伯拉罕生了以撒，在第八日给他行了割礼；后来以撒生雅各，雅各生十二位先祖。","notes":[]},{"n":9,"t":"“先祖嫉妒约瑟，把他卖到埃及去，神却与他同在，","notes":[]},{"n":10,"t":"救他脱离一切苦难，又使他在埃及王法老面前蒙恩，又有智慧。法老派他作埃及国的宰相兼管法老的全家。","notes":[]},{"n":11,"t":"后来全埃及和迦南遭遇饥荒和大灾难，我们的祖宗绝了粮。","notes":[]},{"n":12,"t":"雅各听见在埃及有粮，就打发我们的祖宗初次往那里去。","notes":[]},{"n":13,"t":"第二次约瑟与兄弟们相认，法老才认识他的家族。","notes":[]},{"n":14,"t":"约瑟就打发人，请父亲雅各和全族七十五个人都来。","notes":[]},{"n":15,"t":"于是雅各下了埃及，后来他和我们的祖宗都死在那里；","notes":[]},{"n":16,"t":"他们又被迁到示剑，葬于亚伯拉罕在示剑用银子从哈抹子孙买来的坟墓里。","notes":["“在示剑…子孙”：有古卷是“用银子从示剑的哈抹子孙”。"]},{"n":17,"t":"“当神应许亚伯拉罕的日期将到的时候，以色列人在埃及人丁兴旺，","notes":[]},{"n":18,"t":"直到另一位不认识约瑟的王兴起统治埃及。","notes":["有古卷没有“统治埃及”。"]},{"n":19,"t":"他用诡计待我们的宗族，苦待我们的祖宗，强迫他们丢弃婴孩，使婴孩不能存活。","notes":[]},{"n":20,"t":"就在那时，摩西生了下来，神看为俊美，在父亲家里被抚养了三个月。","notes":[]},{"n":21,"t":"他被丢弃的时候，法老的女儿拾了去，当自己的儿子抚养。","notes":[]},{"n":22,"t":"摩西学了埃及人一切的学问，说话办事都有才能。","notes":[]},{"n":23,"t":"“他到了四十岁，心中起意去看望他的弟兄以色列人。","notes":[]},{"n":24,"t":"他见他们中的一个人受冤屈，就庇护他，为那被压迫的人报仇，打死了那埃及人。","notes":[]},{"n":25,"t":"他以为他的弟兄们必明白神是藉他的手搭救他们，他们却不明白。","notes":[]},{"n":26,"t":"第二天，他遇见有人在打架，就想劝他们和好，说：‘二位，你们是弟兄，为什么彼此欺负呢？’","notes":[]},{"n":27,"t":"那欺负邻舍的人把他推开，说：‘谁立你作我们的领袖和审判官呢？","notes":[]},{"n":28,"t":"难道你要杀我像昨天杀那埃及人一样吗？’","notes":[]},{"n":29,"t":"摩西听见这话就逃走了，寄居于米甸地，在那里生了两个儿子。","notes":[]},{"n":30,"t":"“过了四十年，在西奈山的旷野，有一位天使在荆棘的火焰中向摩西显现。","notes":[]},{"n":31,"t":"摩西见了那异象，觉得很惊讶，正往前观看的时候，有主的声音说：","notes":[]},{"n":32,"t":"‘我是你列祖的神，就是亚伯拉罕、以撒、雅各的神。’摩西战战兢兢，不敢观看。","notes":[]},{"n":33,"t":"主对他说：‘把你脚上的鞋脱下来，因为你所站的地方是圣地。","notes":[]},{"n":34,"t":"我的百姓在埃及所受的困苦，我确实看见了；他们悲叹的声音，我也听见了。我下来要救他们。现在，你来，我要差你往埃及去。’","notes":[]},{"n":35,"t":"“这摩西就是有人曾弃绝他说‘谁立你作我们的领袖和审判官’的，神却藉那在荆棘中显现的天使的手差派他作领袖，作解救者。","notes":[]},{"n":36,"t":"这人领以色列人出来，在埃及地，在红海，在旷野的四十年间行了奇事神迹。","notes":[]},{"n":37,"t":"这人是摩西，就是那曾对以色列人说‘神要从你们弟兄中给你们兴起一位先知像我’的。","notes":[]},{"n":38,"t":"这人是那曾在旷野的会众中和西奈山上，与那对他说话的天使同在，又与我们祖宗同在的，他领受了活泼的圣言传给我们。","notes":[]},{"n":39,"t":"我们的祖宗不肯听从，反弃绝他，他们的心转向埃及，","notes":[]},{"n":40,"t":"对亚伦说：‘你为我们造神明，在我们前面引路，因为领我们出埃及地的这个摩西，我们不知道他遭遇了什么事。’","notes":[]},{"n":41,"t":"那时，他们造了一个牛犊，又拿祭物献给那像，为自己手所做的工作欢跃。","notes":[]},{"n":42,"t":"但是神转脸不顾，任凭他们祭拜天上的日月星辰，正如先知书上所写的：‘以色列家啊，你们四十年间在旷野，何曾将牺牲和祭物献给我？","notes":[]},{"n":43,"t":"你们抬着摩洛的帐幕和理番─你们神明的星，就是你们所造为要敬拜的像。因此，我要把你们迁到巴比伦外去。’","notes":[]},{"n":44,"t":"“我们的祖宗在旷野，有作证的会幕，是神吩咐摩西照着他所看见的样式做的。","notes":[]},{"n":45,"t":"这帐幕，我们的祖宗同约书亚相继承受了，当神在他们面前赶走外邦人的时候，他们把这帐幕搬进承受为业之地，直存到大卫的日子。","notes":[]},{"n":46,"t":"大卫在神面前蒙恩，祈求为雅各的家预备居所。","notes":["“家”：有古卷是“神”。"]},{"n":47,"t":"但却是所罗门为神造成殿宇。","notes":[]},{"n":48,"t":"其实，至高者并不住人手所造的，就如先知所言：","notes":[]},{"n":49,"t":"‘主说：天是我的宝座，地是我的脚凳。你们要为我造怎样的殿宇？哪里是我安歇的地方呢？","notes":[]},{"n":50,"t":"这一切不都是我手所造的吗？’","notes":[]},{"n":51,"t":"“你们这硬着颈项，心与耳未受割礼的人哪，时常抗拒圣灵！你们的祖宗怎样，你们也怎样。","notes":[]},{"n":52,"t":"先知中有哪一个不是受你们祖宗的迫害呢？他们把预先宣告那义者要来的人杀了。如今你们成了那义者的出卖者和凶手了。","notes":[]},{"n":53,"t":"你们领受了天使所传布的律法，竟不遵守。”","notes":[]},{"n":54,"t":"众人听见这些话，心中极其恼怒，向司提反咬牙切齿。","notes":[],"heads":["众人用石头打死司提反"]},{"n":55,"t":"但司提反满有圣灵，定睛望天，看见神的荣耀，又看见耶稣站在神的右边，","notes":[]},{"n":56,"t":"就说：“我看见天开了，人子站在神的右边。”","notes":[]},{"n":57,"t":"众人大声喊叫，捂着耳朵，齐心冲向他，","notes":[]},{"n":58,"t":"把他推到城外，用石头打他。作见证的人把他们的衣裳放在一个名叫扫罗的青年脚前。","notes":[]},{"n":59,"t":"他们正用石头打司提反的时候，他呼求说：“主耶稣啊，求你接纳我的灵魂！”","notes":[]},{"n":60,"t":"然后他跪下来，大声喊着：“主啊，不要将这罪归于他们！”说了这话，就长眠了。","notes":[]}]},"8":{"heading":"扫罗迫害教会","verses":[{"n":1,"t":"扫罗也赞同处死他。从那一天开始，耶路撒冷的教会遭受到大迫害，除了使徒以外，众门徒都分散在犹太和撒玛利亚各处。","notes":[]},{"n":2,"t":"有些虔诚的人把司提反埋葬了，为他大大哀哭。","notes":[]},{"n":3,"t":"扫罗却残害教会，挨家挨户地进去，拉着男女关在监里。","notes":[]},{"n":4,"t":"那些分散的人往各地去传福音的道。","notes":[],"heads":["福音传到撒玛利亚"]},{"n":5,"t":"腓利下撒玛利亚城去，向当地人宣讲基督。","notes":["“下…城去”：有古卷是“下撒玛利亚的一座城去”。"]},{"n":6,"t":"众人都聚精会神，同心合意地听腓利所说的话，一边听他的话，一边看他所行的神迹。","notes":[]},{"n":7,"t":"因为有许多人被污灵附着，那些污灵大声呼叫，从他们身上出来；还有许多瘫痪的、瘸腿的都得了医治。","notes":[]},{"n":8,"t":"那城里，有极大的喜乐。","notes":[]},{"n":9,"t":"有一个人名叫西门，向来在那城里行邪术，自命为大人物，使撒玛利亚的居民惊奇。","notes":[]},{"n":10,"t":"所有的人，从小到大都听从他，说：“这个人就是神的能力，那称为大能者的。”","notes":[]},{"n":11,"t":"他们听从他，因他很久以来用邪术使他们惊奇。","notes":[]},{"n":12,"t":"当他们信了腓利所传神国的福音和耶稣基督的名，连男带女都受了洗。","notes":[]},{"n":13,"t":"西门自己也信了；既受了洗，就常与腓利在一处，看见他所行的神迹和大异能，就觉得很惊奇。","notes":[]},{"n":14,"t":"在耶路撒冷的使徒听见撒玛利亚人领受了神的道，就打发彼得和约翰到他们那里去。","notes":[]},{"n":15,"t":"两个人下去，就为他们祷告，要让他们领受圣灵，","notes":[]},{"n":16,"t":"因为圣灵还没有降在他们任何一个人身上，他们只奉主耶稣的名受了洗。","notes":[]},{"n":17,"t":"于是使徒按手在他们头上，他们就领受了圣灵。","notes":[]},{"n":18,"t":"西门看见使徒一按手，就有圣灵赐下，就拿钱给使徒，","notes":[]},{"n":19,"t":"说：“请把这权柄也给我，使我手按着谁，谁就可以领受圣灵。”","notes":[]},{"n":20,"t":"彼得对他说：“你的银子和你一同灭亡吧！因为你想神的恩赐是可以用钱买的。","notes":[]},{"n":21,"t":"你在这道上无份无关；因为你在神面前心怀不正。","notes":[]},{"n":22,"t":"你要为你这样的恶而悔改，祈求主，或者你心里的意念可得赦免。","notes":[]},{"n":23,"t":"我看出你正在苦胆之中，被不义捆绑着。”","notes":[]},{"n":24,"t":"西门回答说：“请你们为我求主，使你们所说的，没有一样临到我身上。”","notes":[]},{"n":25,"t":"使徒既作了见证，并且宣讲了主的道，就回耶路撒冷去，一路在撒玛利亚好些村庄传扬福音。","notes":[]},{"n":26,"t":"有主的一个使者对腓利说：“起来！向南走，往那从耶路撒冷下迦萨的路上去。”那路是旷野。","notes":[],"heads":["腓利与埃塞俄比亚的太监"]},{"n":27,"t":"腓利就起身去了。不料，有一个埃塞俄比亚人，是个有大权的太监，在埃塞俄比亚女王甘大基的手下总管银库，他上耶路撒冷去礼拜。","notes":[]},{"n":28,"t":"回程中，他坐在车上，正念着以赛亚先知的书，","notes":[]},{"n":29,"t":"圣灵对腓利说：“你去！靠近那车走。”","notes":[]},{"n":30,"t":"腓利就跑到太监那里，听见他正在念以赛亚先知的书，就说：“你明白你所念的吗？”","notes":[]},{"n":31,"t":"他说：“没有人指教我，怎能明白呢？”于是他请腓利上车，与他同坐。","notes":[]},{"n":32,"t":"他所念的那段经文是这样：“他像羊被牵去宰杀，又像羔羊在剪毛的人手下无声，他也是这样不开口。","notes":[]},{"n":33,"t":"他卑微的时候，得不到公义的审判，谁能述说他的身世？因为他的生命从地上被夺去。”","notes":[]},{"n":34,"t":"太监回答腓利说：“请问，先知说这话是指谁，是指自己，还是指别人呢？”","notes":[]},{"n":35,"t":"腓利就开口，从这段经文开始，对他传讲耶稣的福音。","notes":[]},{"n":36,"t":"二人正沿路往前走，到了有水的地方，太监说：“看哪！这里有水，有什么能阻止我受洗呢？”","notes":["有古卷加“37 腓利说：‘你若是一心相信，就可以。’他回答：‘我信耶稣基督是神的儿子。’”"]},{"n":38,"t":"于是他吩咐把车停下来，腓利和太监二人一同下到水里，腓利就给他施洗。","notes":[]},{"n":39,"t":"他们从水里上来，主的灵把腓利提了去，太监再也看不见他了，就欢欢喜喜地上路。","notes":[]},{"n":40,"t":"后来有人在亚锁都遇见腓利；他走遍那地方，在各城宣扬福音，一直到凯撒利亚。","notes":[]}]},"9":{"heading":"扫罗的悔改","verses":[{"n":1,"t":"扫罗不断用威吓凶悍的口气向主的门徒说话。他去见大祭司，","notes":[]},{"n":2,"t":"要求发信给大马士革的各会堂，若是找着信奉这道的人，无论男女，都准他捆绑带到耶路撒冷。","notes":[]},{"n":3,"t":"扫罗在途中，将到大马士革的时候，忽然有一道光从天上下来，四面照射着他，","notes":[]},{"n":4,"t":"他就仆倒在地，听见有声音对他说：“扫罗！扫罗！你为什么迫害我？”","notes":[]},{"n":5,"t":"他说：“主啊！你是谁？”主说：“我就是你所迫害的耶稣。","notes":[]},{"n":6,"t":"起来！进城去，你应该做的事，必有人告诉你。”","notes":[]},{"n":7,"t":"同行的人站在那里，说不出话来，因为他们听见声音，却看不见人。","notes":[]},{"n":8,"t":"扫罗从地上起来，睁开眼睛，竟不能看见什么。有人拉他的手，领他进了大马士革。","notes":[]},{"n":9,"t":"他三天什么都看不见，也不吃也不喝。","notes":[]},{"n":10,"t":"那时，在大马士革有一个门徒，名叫亚拿尼亚。主在异象中对他说：“亚拿尼亚！”他说：“主啊，我在这里。”","notes":[]},{"n":11,"t":"主对他说：“起来！往那叫直街的路去，在犹大的家里，去找一个大数人，名叫扫罗；他正在祷告，","notes":[]},{"n":12,"t":"在异象中看见了一个人，名叫亚拿尼亚，进来为他按手，让他能再看得见。”","notes":["有古卷没有“在异象中”。"]},{"n":13,"t":"亚拿尼亚回答：“主啊，我听见许多人讲到这个人，说他怎样在耶路撒冷多多苦待你的圣徒，","notes":[]},{"n":14,"t":"并且他在这里有从祭司长得来的权柄，要捆绑一切求告你名的人。”","notes":[]},{"n":15,"t":"主对他说：“你只管去。他是我所拣选的器皿，要在外邦人、君王和以色列人面前宣扬我的名。","notes":[]},{"n":16,"t":"我也要指示他，为我的名必须受许多的苦难。”","notes":[]},{"n":17,"t":"亚拿尼亚就去了，进入那家，把手按在扫罗身上，说：“扫罗弟兄，在你来的路上向你显现的主，就是耶稣，打发我来，叫你能再看得见，又被圣灵充满。”","notes":[]},{"n":18,"t":"扫罗的眼睛上立刻好像有鳞一般的东西掉下来，他就能再看得见，于是他起来，受了洗，","notes":[]},{"n":19,"t":"吃过饭体力就恢复了。扫罗和大马士革的门徒一起住了些日子，","notes":[]},{"n":20,"t":"立刻在各会堂里传扬耶稣，说他是神的儿子。","notes":[]},{"n":21,"t":"凡听见的人都很惊奇，说：“在耶路撒冷残害求告这名的不就是这个人吗？他不是到这里来要捆绑他们，带到祭司长那里去吗？”","notes":[]},{"n":22,"t":"但扫罗越发有能力，驳倒住在大马士革的犹太人，证明耶稣是基督。","notes":[]},{"n":23,"t":"过了好些日子，犹太人商议要杀扫罗，","notes":[],"heads":["逃脱犹太人的谋害"]},{"n":24,"t":"但他们的计谋被扫罗知道了。他们昼夜在城门守候着要杀他。","notes":[]},{"n":25,"t":"他的门徒就在夜间用筐子把他从城墙上缒了下去。","notes":[]},{"n":26,"t":"扫罗到了耶路撒冷，想与门徒结交，大家却都怕他，不信他是门徒。","notes":[],"heads":["扫罗在耶路撒冷"]},{"n":27,"t":"只有巴拿巴接待他，领他去见使徒，把他在路上怎么看见主，主怎么向他说话，他在大马士革怎么奉耶稣的名放胆传道，都述说出来。","notes":[]},{"n":28,"t":"于是扫罗在耶路撒冷同门徒出入来往，奉主的名放胆传道，","notes":[]},{"n":29,"t":"并和说希腊话的犹太人讲论辩驳，他们却想法子要杀他。","notes":[]},{"n":30,"t":"弟兄们知道了，就带他下凯撒利亚，送他往大数去。","notes":[]},{"n":31,"t":"那时，犹太、加利利、撒玛利亚各处的教会都得平安，建立起来，凡事敬畏主，蒙圣灵的安慰，人数逐渐增多。","notes":[]},{"n":32,"t":"彼得在众信徒中到处奔波的时候，也到了住在吕大的圣徒那里。","notes":[],"heads":["以尼雅得医治"]},{"n":33,"t":"他在那里遇见一个人，名叫以尼雅，得了瘫痪，在褥子上躺了八年。","notes":[]},{"n":34,"t":"彼得对他说：“以尼雅，耶稣基督医好你了，起来！整理你的褥子吧。”他立刻就起来了。","notes":[]},{"n":35,"t":"凡住吕大和沙仑的人都看见了他，就归向主。","notes":[]},{"n":36,"t":"在约帕有一个女门徒，名叫大比大，翻出来的意思是多加；她广行善事，多施周济。","notes":["“多加”意思是“羚羊”。"],"heads":["多加复活"]},{"n":37,"t":"当时，她患病死了，有人把她清洗后，停在楼上。","notes":[]},{"n":38,"t":"吕大原与约帕相近；门徒听见彼得在那里，就派两个人去见他，央求他说：“请快到我们那里去，不要耽延。”","notes":[]},{"n":39,"t":"彼得就起身和他们同去。他到了，就有人领他上楼。众寡妇都站在彼得旁边哭，拿多加与她们同在时所做的内衣外衣给他看。","notes":[]},{"n":40,"t":"彼得叫她们都出去，然后跪下祷告，转身对着尸体说：“大比大，起来！”她就睁开眼睛，看见彼得，就坐了起来。","notes":[]},{"n":41,"t":"彼得伸手扶她起来，叫那些圣徒和寡妇都进来，把多加活活地交给他们。","notes":[]},{"n":42,"t":"这事传遍了约帕，就有许多人信了主。","notes":[]},{"n":43,"t":"此后，彼得在约帕一个皮革匠西门的家里住了好些日子。","notes":[]}]},"10":{"heading":"彼得和哥尼流","verses":[{"n":1,"t":"在凯撒利亚有一个人名叫哥尼流，是意大利营的百夫长。","notes":[]},{"n":2,"t":"他是个虔诚人，他和全家都敬畏神。他多多周济百姓，常常向神祷告。","notes":[]},{"n":3,"t":"有一天，约在下午三点钟，他在异象中清楚看见神的一个使者进来，到他那里，对他说：“哥尼流。”","notes":[]},{"n":4,"t":"哥尼流定睛看他，惊惶地说：“主啊，什么事？”天使对他说：“你的祷告和你的周济已达到神面前，蒙记念了。","notes":[]},{"n":5,"t":"现在你要派人往约帕去，请一位称为彼得的西门来。","notes":[]},{"n":6,"t":"他住在一个皮革匠西门的家里，房子就在海边。”","notes":[]},{"n":7,"t":"向他说话的天使离开后，哥尼流叫了两个仆人和常伺候他的一个虔诚的兵来，","notes":[]},{"n":8,"t":"把一切的事都讲给他们听，然后就派他们往约帕去。","notes":[]},{"n":9,"t":"第二天，他们走路将近那城，约在正午，彼得上房顶去祷告。","notes":[]},{"n":10,"t":"他觉得饿了，想要吃。那家的人正预备饭的时候，彼得魂游象外，","notes":[]},{"n":11,"t":"看见天开了，有一块好像大布的东西降下，四角吊着缒在地上，","notes":["有古卷加“绑住”。"]},{"n":12,"t":"里面有地上各样四脚的走兽、爬虫和天上的飞鸟。","notes":[]},{"n":13,"t":"又有声音对他说：“彼得，起来！宰了吃。”","notes":[]},{"n":14,"t":"彼得却说：“主啊，绝对不可！凡污俗和不洁净的东西，我从来没有吃过。”","notes":[]},{"n":15,"t":"第二次有声音再对他说：“神所洁净的，你不可当作污俗的。”","notes":[]},{"n":16,"t":"这样一连三次，那东西随即收回天上去了。","notes":[]},{"n":17,"t":"正当彼得心里困惑，不知所看见的异象是什么意思时，哥尼流所差来的人已经找到了西门的家，站在门外，","notes":[]},{"n":18,"t":"喊着问有没有一位称为彼得的西门住在这里。","notes":[]},{"n":19,"t":"彼得还在思考那异象的时候，圣灵对他说：“有三个人来找你。","notes":[]},{"n":20,"t":"起来，下去，跟他们同去，不要疑惑，因为是我差他们来的。”","notes":[]},{"n":21,"t":"于是彼得下去见那些人，说：“我就是你们要找的人，你们是为了什么缘故在这里？”","notes":[]},{"n":22,"t":"他们说：“百夫长哥尼流是个义人，敬畏神，为犹太全民族所称赞。他蒙一位圣天使指示，叫他请你到他家里去，要听你讲话。”","notes":[]},{"n":23,"t":"彼得就请他们进去住宿。次日，他起身和他们同去，还有约帕的几个弟兄跟他一起去。","notes":[]},{"n":24,"t":"又次日，他进入凯撒利亚，哥尼流已经请了他的亲朋好友在等候他们。","notes":["有古卷是“他们”。"]},{"n":25,"t":"彼得一进去，哥尼流就迎接他，俯伏在他脚前拜他。","notes":[]},{"n":26,"t":"但是彼得拉他起来，说：“你起来，我自己也不过是人。”","notes":[]},{"n":27,"t":"彼得和他一边说话一边进去，见有好些人聚集，","notes":[]},{"n":28,"t":"就对他们说：“你们知道，犹太人和别国的人结交来往本是不合规矩的，但神已经指示我，无论什么人都不可看作污俗或不洁净的。","notes":[]},{"n":29,"t":"所以，我一被邀请，没有推辞就来了。现在请问，你们为什么叫我来呢？”","notes":[]},{"n":30,"t":"哥尼流说：“四天前，这个时候，我在家中守着下午三点钟的祷告，忽然有一个人穿着明亮的衣裳站在我面前，","notes":[]},{"n":31,"t":"说：‘哥尼流，你的祷告已蒙垂听，你的周济在神面前已蒙记念了。","notes":[]},{"n":32,"t":"你要派人往约帕去，请那称为彼得的西门来，他住在海边一个皮革匠西门的家里。’","notes":[]},{"n":33,"t":"所以我立刻派人去请你。你来了真好。现在我们都在神面前，要听主吩咐你的一切话。”","notes":["“主”：有古卷是“神”。"]},{"n":34,"t":"彼得开口说：“我真的看出神是不偏待人的。","notes":[],"heads":["在哥尼流家中讲道"]},{"n":35,"t":"不但如此，在各国中那敬畏他而行义的人都为他所悦纳。","notes":[]},{"n":36,"t":"神藉着耶稣基督—他是万有的主—传和平的福音，把这道传给以色列人。","notes":[]},{"n":37,"t":"这话在约翰传扬洗礼以后，从加利利起，传遍了犹太。神怎样以圣灵和能力膏了拿撒勒人耶稣，这都是你们知道的。他到处奔波，行善事，医好凡被魔鬼压制的人，因为神与他同在。","notes":[],"end":38},{"n":39,"t":"他在犹太人之地和耶路撒冷所行的一切事，有我们作见证人。他们竟把他挂在木头上杀了。","notes":[]},{"n":40,"t":"第三天，神使他复活，使他显现出来；","notes":[]},{"n":41,"t":"不是显现给所有的人看，而是显现给神预先所拣选为他作见证的人看，就是我们这些在他从死人中复活以后和他同吃同喝的人。","notes":[]},{"n":42,"t":"他吩咐我们传道给众人，证明他是神所立定，要作审判活人、死人的审判者。","notes":[]},{"n":43,"t":"众先知也为这人作见证：凡信他的人，必藉着他的名得蒙赦罪。”","notes":[]},{"n":44,"t":"彼得还在说这些话的时候，圣灵降在一切听道的人身上。","notes":[],"heads":["外邦人领受圣灵"]},{"n":45,"t":"那些奉割礼的信徒和彼得同来，见圣灵的恩赐也浇在外邦人身上，就都惊奇；","notes":[]},{"n":46,"t":"因听见他们说方言，称赞神为大。于是彼得回答：","notes":["“方言”或译“灵语”。"]},{"n":47,"t":"“这些人既受了圣灵，跟我们一样，谁能阻止用水给他们施洗呢？”","notes":[]},{"n":48,"t":"他就吩咐奉耶稣基督的名给他们施洗。于是他们请彼得住了几天。","notes":[]}]},"11":{"heading":"向耶路撒冷教会报告","verses":[{"n":1,"t":"使徒和在犹太的众弟兄听到外邦人也领受了神的道。","notes":[]},{"n":2,"t":"等到彼得上了耶路撒冷，那些奉割礼的信徒和他争辩，","notes":[]},{"n":3,"t":"说：“你竟进入未受割礼之人当中，和他们一同吃饭！”","notes":[]},{"n":4,"t":"彼得就开始把这事逐一向他们解释，说：","notes":[]},{"n":5,"t":"“我在约帕城里祷告的时候，魂游象外，看见异象，有一块好像大布的东西降下，四角吊着从天缒下，直来到我跟前。","notes":[]},{"n":6,"t":"我定睛观看，见内中有地上四脚的牲畜、野兽、爬虫和天上的飞鸟。","notes":[]},{"n":7,"t":"我还听见有声音对我说：‘彼得，起来！宰了吃。’","notes":[]},{"n":8,"t":"我说：‘主啊，绝对不可！凡污俗或不洁净的东西从来没有进过我的口。’","notes":[]},{"n":9,"t":"第二次，有声音从天上回答：‘神所洁净的，你不可当作污俗的。’","notes":[]},{"n":10,"t":"这样一连三次，然后一切就都收回天上去了。","notes":[]},{"n":11,"t":"正当那时，有三个从凯撒利亚差来见我的人，站在我们所住的屋子门前。","notes":["有古卷是“我”。"]},{"n":12,"t":"圣灵吩咐我和他们同去，不要疑惑，还有这六位弟兄也跟我一起去，我们进了那人的家。","notes":[]},{"n":13,"t":"那人就告诉我们，他如何看见一位天使站在他家里，说：‘你派人往约帕去，请那称为彼得的西门来，","notes":[]},{"n":14,"t":"他有话要告诉你，因这些话你和你的全家都可以得救。’","notes":[]},{"n":15,"t":"我一开始讲话，圣灵就降在他们身上，正像当初降在我们身上一样。","notes":[]},{"n":16,"t":"我就想起主的话如何说：‘约翰用水施洗，但你们要在圣灵里受洗。’","notes":[]},{"n":17,"t":"既然神给他们恩赐，像在我们信主耶稣基督的时候给了我们一样，我是谁，能拦阻神吗？”","notes":[]},{"n":18,"t":"众人听见这些话，就不说话了，只归荣耀给神，说：“这样看来，神也赐恩给外邦人，使他们悔改得生命了。”","notes":[]},{"n":19,"t":"那些因司提反的事遭患难而四处分散的门徒，直走到腓尼基、塞浦路斯和安提阿。他们不向别人讲道，只向犹太人讲。","notes":[],"heads":["安提阿的教会"]},{"n":20,"t":"但内中有塞浦路斯和古利奈人，他们到了安提阿也向希腊人传讲主耶稣的福音。","notes":["有古卷是“也向说希腊话的犹太人传讲主耶稣的福音”。"]},{"n":21,"t":"主的手与他们同在，信而归主的人数很多。","notes":[]},{"n":22,"t":"这风声传到耶路撒冷教会的人耳中，他们就打发巴拿巴到安提阿去。","notes":[]},{"n":23,"t":"他到了那里，看见神所赐的恩就欢喜，劝勉众人要立定心志，恒久靠主。","notes":[]},{"n":24,"t":"这巴拿巴原是个好人，满有圣灵和信心，于是有许多人归服了主。","notes":[]},{"n":25,"t":"他又往大数去找扫罗，","notes":[]},{"n":26,"t":"找着了，就带他到安提阿去。他们足有一年和教会一同聚集，教导了许多人。门徒称为“基督徒”是从安提阿开始的。","notes":[]},{"n":27,"t":"当那些日子，有几位先知从耶路撒冷下到安提阿。","notes":[]},{"n":28,"t":"内中有一位，名叫亚迦布，站起来，藉着圣灵指示普天下将有大饥荒；这事在克劳第年间果然实现了。","notes":[]},{"n":29,"t":"于是门徒决定，照各人的力量捐钱，送去供给住在犹太的弟兄。","notes":[]},{"n":30,"t":"他们就这样做了，托巴拿巴和扫罗的手送到众长老那里。","notes":[]}]},"12":{"heading":"雅各被杀，彼得被囚","verses":[{"n":1,"t":"约在那时候，希律王下手苦待教会中的一些人，","notes":[]},{"n":2,"t":"用刀杀了约翰的哥哥雅各。","notes":[]},{"n":3,"t":"他见犹太人喜欢这事，也去拿住彼得。那时候正是除酵节期间。","notes":[]},{"n":4,"t":"希律捉了彼得，押在监里，交给四班士兵看守，每班四个人，企图要在逾越节后把他提出来，当着百姓办他。","notes":[]},{"n":5,"t":"于是彼得被囚在监里，教会却为他切切祷告神。","notes":[]},{"n":6,"t":"希律将要提他出来的前一夜，彼得被两条铁链锁着，睡在两个士兵当中；门前还有警卫看守。","notes":[],"heads":["彼得获救出监"]},{"n":7,"t":"忽然，有主的一个使者显现，牢房里有光照耀；天使拍彼得的肋旁，叫醒了他，说：“快起来！”铁链就从他手上脱落下来。","notes":[]},{"n":8,"t":"天使对他说：“束上腰带，穿上鞋子。”他就照着做了。天使又对他说：“披上外衣，跟我来。”","notes":[]},{"n":9,"t":"彼得就出来跟着他走，不知道天使所做是真的，以为见了异象。","notes":[]},{"n":10,"t":"他们经过了第一层和第二层监牢，就来到往城内的铁门，那门就自动给他们开了。他们出来，走过一条街，忽然天使离开他去了。","notes":[]},{"n":11,"t":"彼得清醒过来，说：“现在我真知道主差遣他的使者，救我脱离希律的手，和犹太人所期待的一切。”","notes":[]},{"n":12,"t":"他明白了，就到那称为马可的约翰的母亲马利亚家去，在那里已有好些人聚集祷告。","notes":[]},{"n":13,"t":"彼得敲外门时，有一个使女，名叫罗大，出来应门，","notes":[]},{"n":14,"t":"认出是彼得的声音，欢喜得顾不了开门，就跑进去报信，说彼得站在门外。","notes":[]},{"n":15,"t":"他们对她说：“你疯了！”使女坚持真有其事。他们说：“那是他的天使。”","notes":[]},{"n":16,"t":"彼得不停地敲门；他们开了门，一见是他，就很惊奇。","notes":[]},{"n":17,"t":"彼得做个手势，要他们不作声，就告诉他们主怎样领他出监；又说：“你们要把这些事告诉雅各和众弟兄。”然后，他离开往别处去了。","notes":[]},{"n":18,"t":"到了天亮，士兵中起了不少骚动，不知道彼得到哪里去了。","notes":[]},{"n":19,"t":"希律找他，找不着，就审问警卫，下令带走他们处死。后来希律离开犹太，下凯撒利亚去，住在那里。","notes":[]},{"n":20,"t":"希律向推罗和西顿的人发怒。他们那一带地方是从王的土地供应粮食的，因此就托了王的内侍大臣伯拉斯都的情，一心来求和。","notes":[],"heads":["希律之死"]},{"n":21,"t":"希律在所定的日子，穿上朝服，坐在位上，对他们演讲。","notes":[]},{"n":22,"t":"民众一直喊着：“这是神明的声音，不是人的声音。”","notes":[]},{"n":23,"t":"希律不归荣耀给神，所以主的使者立刻击打他，他被虫咬，就断了气。","notes":[]},{"n":24,"t":"神的道日见兴旺，越发广传。","notes":[]},{"n":25,"t":"巴拿巴和扫罗完成了供给的事，就回到耶路撒冷，带着称为马可的约翰同去。","notes":["有古卷是“就从耶路撒冷回去”。"]}]},"13":{"heading":"巴拿巴和扫罗奉差遣","verses":[{"n":1,"t":"在安提阿的教会中，有几位先知和教师，就是巴拿巴和称为尼结的西面、古利奈人路求，与希律分封王一起长大的马念，和扫罗。","notes":[]},{"n":2,"t":"他们在事奉主和禁食的时候，圣灵说：“要为我分派巴拿巴和扫罗去做我召他们做的工作。”","notes":[]},{"n":3,"t":"于是他们禁食祷告后，给巴拿巴和扫罗按手，然后派遣他们走了。","notes":[]},{"n":4,"t":"他们既蒙圣灵差遣，就下到西流基，从那里坐船往塞浦路斯去，","notes":[],"heads":["在塞浦路斯传道"]},{"n":5,"t":"到了撒拉米，就在犹太人各会堂里宣讲神的道，也有约翰作他们的帮手。","notes":[]},{"n":6,"t":"他们走遍全岛，直到帕弗，在那里遇见一个术士—犹太人的假先知，名叫巴耶稣。","notes":[]},{"n":7,"t":"这人常和士求．保罗省长在一起。士求．保罗是个通达人，他请巴拿巴和扫罗来，要听神的道。","notes":[]},{"n":8,"t":"只是术士以吕马(他的名字翻出来就是行法术的意思)敌对使徒，设法使省长远离这信仰。","notes":[]},{"n":9,"t":"扫罗，又名保罗，被圣灵充满，定睛看他，","notes":[]},{"n":10,"t":"说：“你这充满各样诡诈奸恶，魔鬼的儿子，一切正义的仇敌，你还不停止扭曲主的正道吗？","notes":[]},{"n":11,"t":"现在你看，主的手临到你身上，你会瞎眼，暂时看不见日光。”立刻迷濛和黑暗笼罩着他，他到处摸索，求人拉着手领他。","notes":[]},{"n":12,"t":"省长看见所发生的事就信了，因对主的教导感到惊奇。","notes":[]},{"n":13,"t":"保罗和他的同伴从帕弗开船，来到旁非利亚的别加，约翰却离开他们，回耶路撒冷去了。","notes":[],"heads":["在彼西底的安提阿传道"]},{"n":14,"t":"他们从别加往前行，来到彼西底的安提阿。在安息日，他们进了会堂就坐下。","notes":[]},{"n":15,"t":"在读完了律法和先知的书，会堂主管们叫人过去，对他们说：“二位弟兄，你们若有什么劝勉众人的话，请说。”","notes":[]},{"n":16,"t":"保罗就站起来，做个手势，说：“诸位以色列人和一切敬畏神的人，请听。","notes":[]},{"n":17,"t":"这以色列民的神拣选了我们的祖宗，当百姓寄居埃及的时候抬举他们，用大能的手领他们从那地出来。","notes":[]},{"n":18,"t":"他在旷野容忍他们，约有四十年。","notes":["“容忍”：有古卷是“抚养”。"]},{"n":19,"t":"他消灭了迦南地七族的人后，把那地分给他们为业，","notes":[]},{"n":20,"t":"约有四百五十年。此后，他给他们设立士师，直到撒母耳先知的时候。","notes":["“约有…此后”：有古卷是“此后，约有四百五十年”。"]},{"n":21,"t":"从那时起，他们要求立一个王，神就将便雅悯支派中基士的儿子扫罗给他们作王，共四十年。","notes":[]},{"n":22,"t":"他废了扫罗之后，就兴起大卫作他们的王，又为他作见证说：‘我寻得耶西的儿子大卫，他是合我心意的人，他要遵行我一切的旨意。’","notes":[]},{"n":23,"t":"从这人的后裔中，神已经照着所应许的为以色列人兴起一位救主，就是耶稣。","notes":[]},{"n":24,"t":"在他没有出来以前，约翰已向以色列全民宣讲悔改的洗礼。","notes":[]},{"n":25,"t":"约翰快走完他的人生路程时，说：‘你们以为我是谁？我不是；但是有一位在我以后来的，我就是解他脚上的鞋带也不配。’","notes":["或译“我不是基督”。"]},{"n":26,"t":"“诸位弟兄—亚伯拉罕的子孙和你们中间敬畏神的人哪，这救世的道是传给我们的。","notes":[]},{"n":27,"t":"耶路撒冷的居民和他们的官长，因为不认识这基督，也不明白每安息日所读的先知的书，把他定了死罪，正应验了先知的预言。","notes":[]},{"n":28,"t":"虽然他们查不出他有该死的罪状，还是要求彼拉多把他杀了。","notes":[]},{"n":29,"t":"他们既实现了经上指着他所记的一切话，就从木头上把他取下来，放在坟墓里。","notes":[]},{"n":30,"t":"神却使他从死人中复活。","notes":[]},{"n":31,"t":"有许多日子，他向那些从加利利同他上耶路撒冷的人显现，这些人如今在民间成为他的见证人。","notes":[]},{"n":32,"t":"我们报好信息给你们，就是那应许祖宗的话，","notes":[]},{"n":33,"t":"神已经向我们这些作他们儿女的应验，使耶稣复活了。正如《诗篇》第二篇上记着：‘你是我的儿子，我今日生了你。’","notes":["“向我们…儿女的”：有古卷是“向我们的儿女”。"]},{"n":34,"t":"论到神使他从死人中复活，不再归于朽坏，他曾这样说：‘我必将所应许大卫那圣洁、可靠的恩典赐给你们。’","notes":[]},{"n":35,"t":"所以他也在另一篇说：‘你必不让你的圣者见朽坏。’","notes":[]},{"n":36,"t":"大卫在世的时候，遵行了神的旨意就长眠了，归到他祖宗那里，已见朽坏；","notes":["或译“大卫按神的旨意服侍了那一世的人，就长眠了”。"]},{"n":37,"t":"惟独神使他复活的那一位，他并未见朽坏。","notes":[]},{"n":38,"t":"所以弟兄们，你们当知道：赦罪的道是由这人传给你们的，","notes":[]},{"n":39,"t":"你们靠摩西的律法在不得称义的一切事上，每一个信靠这位耶稣的都得称义了。","notes":[]},{"n":40,"t":"所以，你们要小心，免得先知书上所说的临到你们：","notes":[]},{"n":41,"t":"‘要观看，你们这些藐视的人，要惊讶，要灭亡，因为在你们的日子，我行一件事，虽有人告诉你们，你们总是不信。’”","notes":[]},{"n":42,"t":"他们走出会堂的时候，众人请他们在下一个安息日再讲这些话给他们听。","notes":[]},{"n":43,"t":"散会以后，有许多犹太人和敬虔的皈依犹太教的人跟从了保罗和巴拿巴。二人对他们讲话，劝他们务要恒久倚靠神的恩典。","notes":[]},{"n":44,"t":"到下一个安息日，全城的人几乎都聚集起来，要听主的道。","notes":["有古卷是“神的道”；48节同。"]},{"n":45,"t":"但犹太人看见这么多的人，就满心嫉妒，辩驳保罗所说的话，并且毁谤他。","notes":[]},{"n":46,"t":"于是保罗和巴拿巴放胆说：“神的道本应先传给你们；只因你们弃绝这道，断定自己不配得永生，我们就转向外邦人。","notes":[]},{"n":47,"t":"因为主曾这样吩咐我们：‘我已经立你作万邦之光，使你施行我的救恩，直到地极。’”","notes":[]},{"n":48,"t":"外邦人听见这话很欢喜，赞美主的道，凡被指定得永生的人都信了。","notes":[]},{"n":49,"t":"于是主的道传遍了那一带地方。","notes":[]},{"n":50,"t":"但犹太人挑唆虔敬尊贵的妇女和城内有名望的人，迫害保罗和巴拿巴，把他们赶出境外。","notes":[]},{"n":51,"t":"二人对着众人跺掉脚上的尘土，然后往以哥念去了。","notes":[]},{"n":52,"t":"门徒满心喜乐，又被圣灵充满。","notes":[]}]},"14":{"heading":"在以哥念传道","verses":[{"n":1,"t":"同样的事也发生在以哥念。保罗和巴拿巴进了犹太人的会堂，在那里讲道，所以有很多犹太人和希腊人都信了。","notes":[]},{"n":2,"t":"但那不顺从的犹太人煽动外邦人，使他们心里仇恨弟兄。","notes":[]},{"n":3,"t":"二人在那里住了好些日子，倚靠主放胆讲道，主藉他们的手施行神迹奇事，证明他恩惠的道。","notes":[]},{"n":4,"t":"城里的众人却分裂了：有依附犹太人的，有依附使徒的。","notes":[]},{"n":5,"t":"那时，外邦人、犹太人和他们的官长，一齐拥上来，要凌辱使徒，用石头打他们。","notes":[]},{"n":6,"t":"使徒知道了，就逃到吕高尼的路司得和特庇两个城，以及周围地方去，","notes":[]},{"n":7,"t":"在那里继续传福音。","notes":[]},{"n":8,"t":"路司得城里有一个两脚无力的人，他从母腹里就是瘸腿的，老是坐着，从来没有走过。","notes":[],"heads":["在路司得传道"]},{"n":9,"t":"他听保罗讲道；保罗定睛看他，见他有信心，可得痊愈，","notes":[]},{"n":10,"t":"就大声说：“起来！两脚站直。”那人就跳起来，开始行走。","notes":[]},{"n":11,"t":"众人看见保罗所做的事，就用吕高尼话大声说：“有神明藉着人形降临在我们中间了。”","notes":[]},{"n":12,"t":"于是他们称巴拿巴为宙斯，称保罗为希耳米，因为他总是带头说话。","notes":[]},{"n":13,"t":"城外有宙斯庙的祭司牵着牛，拿着花环，来到门前，要同众人一起献祭。","notes":[]},{"n":14,"t":"巴拿巴和保罗二位使徒听见，就撕开衣裳，跳进众人中间，喊着：","notes":[]},{"n":15,"t":"“诸位，为什么做这些事呢？我们也是人，性情和你们一样。我们传福音给你们，是要你们离弃这些虚妄的事，归向那创造天、地、海和其中万物的永生的神。","notes":[]},{"n":16,"t":"他在从前的世代，任凭万国各行其道；","notes":[]},{"n":17,"t":"然而他未尝不为自己留下证据来，就如常行善事，从天降雨，赏赐丰年，使你们饮食饱足，满心喜乐。”","notes":[]},{"n":18,"t":"二人说了这些话，总算拦住众人不献祭给他们。","notes":[]},{"n":19,"t":"但有些犹太人，从安提阿和以哥念来，挑唆众人，并且用石头打保罗，以为他死了，就把他拖到城外。","notes":[]},{"n":20,"t":"当门徒围着他的时候，他站了起来，走进城去。第二天，保罗同巴拿巴往特庇去。","notes":[]},{"n":21,"t":"保罗和巴拿巴对那城里的人传了福音，使好些人成为门徒后，又回路司得、以哥念、安提阿去，","notes":[],"heads":["回到叙利亚的安提阿"]},{"n":22,"t":"坚固门徒的心，劝他们持守他们的信仰，说：“我们进入神的国，必须经历许多艰难。”","notes":[]},{"n":23,"t":"二人在各教会中选立了长老，禁食祷告后，把他们交托给他们所信的主。","notes":[]},{"n":24,"t":"二人经过彼西底来到旁非利亚，","notes":[]},{"n":25,"t":"在别加讲了道，就下亚大利去，","notes":[]},{"n":26,"t":"从那里坐船回安提阿去。当初，众人就在这地方，把他们交托在神的恩典中，要完成现在所做的工。","notes":[]},{"n":27,"t":"他们一到那里，就聚集了会众，述说神藉他们所行的一切事，并且神怎样为外邦人开了信道的门。","notes":[]},{"n":28,"t":"二人在那里同门徒住了一段日子。","notes":[]}]},"15":{"heading":"耶路撒冷会议","verses":[{"n":1,"t":"有几个人从犹太下来，教导弟兄们说：“你们若不按照摩西的规矩受割礼，不能得救。”","notes":[]},{"n":2,"t":"保罗和巴拿巴跟他们发生了激烈的争执和辩论；大家就决定指派保罗、巴拿巴和本会的几个人，为所辩论的事上耶路撒冷去见使徒和长老。","notes":[]},{"n":3,"t":"于是教会为他们送行。他们经过腓尼基、撒玛利亚，沿途叙说外邦人归主的事，使众弟兄都非常欢喜。","notes":[]},{"n":4,"t":"他们到了耶路撒冷，教会、使徒和长老都接待他们，他们就述说神同他们所做的一切事。","notes":[]},{"n":5,"t":"惟有几个法利赛派的信徒起来，说：“必须给外邦人行割礼，吩咐他们遵守摩西的律法。”","notes":[]},{"n":6,"t":"使徒和长老聚集商议这事。","notes":[]},{"n":7,"t":"辩论了许久后，彼得站起来，对他们说：“诸位弟兄，你们知道神早已在你们中间拣选了我，让外邦人从我口中得听福音之道，而且相信。","notes":[]},{"n":8,"t":"知道人心的神也为他们作了见证，赐圣灵给他们，正如给我们一样；","notes":[]},{"n":9,"t":"又藉着信洁净了他们的心，他们和我们之间并没有什么分别。","notes":[]},{"n":10,"t":"现在你们为什么试探神，要把我们祖宗和我们所不能负的轭放在门徒的颈项上呢？","notes":[]},{"n":11,"t":"相反地，我们相信，我们得救是因主耶稣的恩典，和他们一样。”","notes":[]},{"n":12,"t":"众人都默默无声，听巴拿巴和保罗述说神藉着他们在外邦人中所行的神迹和奇事。","notes":[]},{"n":13,"t":"他们讲完了，雅各回答说：“诸位弟兄，请听我说。","notes":[]},{"n":14,"t":"刚才西门述说神当初怎样眷顾外邦人，从他们中间选取人民归于自己的名下；","notes":[]},{"n":15,"t":"众先知的话也与这意思相符合。","notes":[]},{"n":16,"t":"正如经上所写的：‘此后，我要回来，重新修造大卫倒塌了的帐幕，从废墟中重新修造，把它建立起来，","notes":[]},{"n":17,"t":"使剩余的人，就是凡称我名的外邦人，都寻求主。这话是自古以来显明这些事的主说的。’","notes":[],"end":18},{"n":19,"t":"所以，我的意见是不可难为那归向神的外邦人；","notes":[]},{"n":20,"t":"但是要写信吩咐他们禁戒偶像所玷污的东西、血和勒死的牲畜，禁戒淫乱。","notes":["有古卷没有“勒死的牲畜”；29节，21．25同。"]},{"n":21,"t":"因为历代以来，摩西的书在各城都有人宣讲，每逢安息日，也在会堂里诵读。”","notes":[]},{"n":22,"t":"那时，使徒、长老和全教会认为应从他们中间拣选人，差他们和保罗、巴拿巴一同到安提阿去，所拣选的就是称为巴撒巴的犹大和西拉。这二人在弟兄中是领袖。","notes":[],"heads":["会议的覆函"]},{"n":23,"t":"他们带去的信说：“使徒和作长老的弟兄们向安提阿、叙利亚、基利家外邦众弟兄问安。","notes":[]},{"n":24,"t":"我们听说，有几个人从我们这里出去，用一些话骚扰你们，使你们的心困惑，其实我们并没有吩咐他们。","notes":["有古卷没有“出去”。","有古卷加“说你们必须受割礼，守摩西的律法。”"]},{"n":25,"t":"我们认为，既然我们同心定意，就拣选几个人，派他们同我们所亲爱的巴拿巴和保罗到你们那里去。","notes":[]},{"n":26,"t":"这二人曾为我主耶稣基督的名不顾自己的性命。","notes":[]},{"n":27,"t":"所以我们派犹大和西拉去，他们也会亲口述说这些事。","notes":[]},{"n":28,"t":"因为圣灵和我们决定除了这几件重要的事，不将别的重担放在你们身上，","notes":[]},{"n":29,"t":"就是禁戒偶像所玷污的东西、血和勒死的牲畜，禁戒淫乱。这几件你们若能自己禁戒就好了。祝你们安康！”","notes":[]},{"n":30,"t":"他们既奉了差遣就下安提阿去，聚集会众，把书信交给他们。","notes":[]},{"n":31,"t":"众人念了，因为信上鼓励的话而感到欣慰。","notes":[]},{"n":32,"t":"犹大和西拉自己也是先知，就用许多话劝勉弟兄，坚固他们。","notes":[]},{"n":33,"t":"二人住了些日子，弟兄们打发他们平平安安地回到差遣他们的人那里去。","notes":["有古卷加“34 惟有西拉决定仍住在那里。”"]},{"n":35,"t":"但保罗和巴拿巴仍留在安提阿，和许多别的人一同教导，并传扬主的道。","notes":[]},{"n":36,"t":"过了些日子，保罗对巴拿巴说：“让我们回到从前宣扬主道的各城，看看弟兄们的情况如何。”","notes":[],"heads":["保罗和巴拿巴分手"]},{"n":37,"t":"巴拿巴有意要带称为马可的约翰同去；","notes":[]},{"n":38,"t":"但保罗认为不宜带他去，因为马可从前在旁非利亚离开他们，不和他们一起工作。","notes":[]},{"n":39,"t":"于是二人起了争执，甚至彼此分手。巴拿巴带着马可，坐船往塞浦路斯去；","notes":[]},{"n":40,"t":"保罗则拣选了西拉，也出发了，蒙弟兄们把他交于主的恩典中。","notes":[]},{"n":41,"t":"他就走遍了叙利亚、基利家，坚固众教会。","notes":[]}]},"16":{"heading":"提摩太跟保罗和西拉同工","verses":[{"n":1,"t":"后来，保罗来到特庇，又到路司得。在那里有一个门徒，名叫提摩太，是信主的犹太妇人的儿子，他父亲却是希腊人。","notes":[]},{"n":2,"t":"路司得和以哥念的弟兄都称赞他。","notes":[]},{"n":3,"t":"保罗要带他同去，只因那些地方的犹太人都知道他父亲是希腊人，就给他行了割礼。","notes":[]},{"n":4,"t":"他们经过各城，把耶路撒冷使徒和长老所决定的规条交给门徒遵守。","notes":[]},{"n":5,"t":"于是众教会信心越发坚固，人数天天增加。","notes":[]},{"n":6,"t":"因为圣灵禁止他们在亚细亚讲道，他们就经过弗吕家、加拉太一带地方。","notes":[],"heads":["保罗看见马其顿人的异象"]},{"n":7,"t":"到了每西亚的边界，他们想要往庇推尼去，耶稣的灵却不许。","notes":[]},{"n":8,"t":"他们就越过每西亚，下特罗亚去。","notes":[]},{"n":9,"t":"夜间，有异象向保罗显现。有一个马其顿人站着求他说：“请你过来，到马其顿来帮助我们！”","notes":[]},{"n":10,"t":"保罗既看见这异象，我们就立即设法往马其顿去，认为神呼召我们传福音给那里的人。","notes":[]},{"n":11,"t":"我们从特罗亚开船，直行驶到撒摩特喇，第二天到了尼亚坡里；","notes":[],"heads":["吕底亚归主"]},{"n":12,"t":"从那里来到腓立比，就是马其顿这一带的一个重要城市，也是罗马的驻防城。我们在这城里住了几天。","notes":["“这一带…城市”：有古卷是“第一区的一个城市”。"]},{"n":13,"t":"在安息日，我们出城门，到了河边，知道那里有一个祷告的地方，我们就坐下来对那些聚会的妇女讲道。","notes":["“知道…地方”：有古卷是“那里是人们惯常祷告的地方”；另有古卷是“那里被认为是个祷告的地方”。"]},{"n":14,"t":"有一个卖紫色布的妇人，名叫吕底亚，是推雅推喇城的人，素来敬拜神。她在听着，主就开导她的心，使她留心听保罗所讲的话。","notes":[]},{"n":15,"t":"她和她一家都领了洗，就求我们说：“你们若以为我是真心信主的，请到我家里来住。”于是她坚决请我们留下。","notes":["或译“你们若以为我是忠心于主的”。"]},{"n":16,"t":"后来，我们往那祷告的地方去时，有一个被占卜的灵附身的使女迎面走来，她使用法术使她的主人们发了大财。","notes":[],"heads":["在腓立比被囚"]},{"n":17,"t":"她跟随保罗和我们，喊着说：“这些人是至高神的仆人，对你们传讲救人的道路。”","notes":[]},{"n":18,"t":"她一连好几天这样喊叫，保罗就心中厌烦，转身对那灵说：“我奉耶稣基督的名吩咐你从她身上出来！”那灵立刻出来了。","notes":[]},{"n":19,"t":"使女的主人们见发财的指望没有了，就揪住保罗和西拉，拉他们到市上去见官；","notes":[]},{"n":20,"t":"又带他们到行政官长们面前，说：“这些骚扰我们城的，他们是犹太人，","notes":[]},{"n":21,"t":"竟传布我们罗马人所不可接受、不可遵守的规矩。”","notes":[]},{"n":22,"t":"群众就一齐起来攻击他们。官长们吩咐撕开他们的衣裳，用棍子打；","notes":[]},{"n":23,"t":"打了许多棍，就把他们下在监里，嘱咐狱警严紧看守。","notes":[]},{"n":24,"t":"狱警领了这样的命令，就把他们下在内监，两脚拴在木架上。","notes":[]},{"n":25,"t":"约在半夜，保罗和西拉正在祷告，唱诗赞美神，众囚犯也侧耳听着的时候，","notes":[]},{"n":26,"t":"忽然，地大震动，甚至监牢的地基都摇动了，监门立刻全开，众囚犯的锁链也都解开了。","notes":[]},{"n":27,"t":"狱警一醒，看见监门全开，以为囚犯已经逃走，就拔刀要自杀。","notes":[]},{"n":28,"t":"保罗大声呼叫：“不要伤害自己！我们都在这里。”","notes":[]},{"n":29,"t":"狱警叫人拿灯来，就冲进去，战战兢兢地俯伏在保罗和西拉面前。","notes":[]},{"n":30,"t":"然后狱警领他们出来，说：“二位先生，我必须做什么才可以得救？”","notes":[]},{"n":31,"t":"他们说：“当信主耶稣，你和你一家都必得救。”","notes":["“你和你…得救”：原文直译“你必得救，你的一家也是这样”。"]},{"n":32,"t":"他们就把主的道讲给他和他全家的人听。","notes":[]},{"n":33,"t":"当夜，就在那时候，狱警把他们带去，洗他们的伤；他和他所有的家人立刻都受了洗。","notes":[]},{"n":34,"t":"于是狱警领他们上自己的家里去，给他们摆上饭。他和全家的人，因为信了神，都满心喜乐。","notes":[]},{"n":35,"t":"到了天亮，官长们打发差役来，说：“释放那两个人吧。”","notes":[]},{"n":36,"t":"狱警就把这些话告诉保罗：“官长们打发人来，要释放你们，现在可以出监，平平安安去吧。”","notes":[]},{"n":37,"t":"保罗却说：“我们是罗马人，并没有定罪，他们竟在公众面前打了我们，又把我们下在监里；现在要私下赶我们出去吗？这不行！叫他们自己来领我们出去吧！”","notes":[]},{"n":38,"t":"差役把这些话回禀官长们；官长们听见他们是罗马人，就害怕了，","notes":[]},{"n":39,"t":"于是来劝他们，领他们出来，请他们离开那城。","notes":[]},{"n":40,"t":"二人出了监牢，往吕底亚家里去，见了弟兄们，劝慰他们一番，就离开了。","notes":[]}]},"17":{"heading":"帖撒罗尼迦的骚动","verses":[{"n":1,"t":"保罗和西拉经过暗妃坡里、亚波罗尼亚，来到帖撒罗尼迦，在那里有犹太人的会堂。","notes":[]},{"n":2,"t":"保罗照他素常的规矩进去，一连三个安息日，根据圣经与他们辩论，","notes":[]},{"n":3,"t":"讲解和说明基督必须受害，从死人中复活；又说：“我所传给你们的这位耶稣就是基督。”","notes":[]},{"n":4,"t":"他们中间有些人听了劝，就跟从保罗和西拉，还有许多虔敬的希腊人，尊贵的妇女也不少。","notes":[]},{"n":5,"t":"但不信的犹太人心里嫉妒，聚集了些市井流氓，搭伙成群，煽动全城的人闯进耶孙的家，要把保罗和西拉带到民众那里。","notes":[]},{"n":6,"t":"那些人找不着他们，就把耶孙和几个弟兄拉到地方官那里，喊叫着：“这些搅乱天下的人也到这里来了，","notes":[]},{"n":7,"t":"耶孙竟收留他们。这些人都违背凯撒的命令，说另有一个王耶稣。”","notes":[]},{"n":8,"t":"众人和地方官听见这些话，就惶恐了，","notes":[]},{"n":9,"t":"于是收了耶孙和其余的人的保证金后，释放了他们。","notes":[]},{"n":10,"t":"当夜，弟兄们立刻送保罗和西拉往庇哩亚去；二人到了，就进入犹太人的会堂。","notes":[],"heads":["使徒们在庇哩亚传道"]},{"n":11,"t":"这地方的犹太人比帖撒罗尼迦的人开明，热心领受这道，天天查考圣经，要知道这道是否真实。","notes":[]},{"n":12,"t":"所以，他们中间有许多信了，又有希腊的尊贵妇人，男人也不少。","notes":[]},{"n":13,"t":"但帖撒罗尼迦的犹太人知道保罗又在庇哩亚传神的道，就往那里去，煽动挑拨群众。","notes":[]},{"n":14,"t":"于是，弟兄们立刻送保罗到海边去，西拉和提摩太却仍留在庇哩亚。","notes":[]},{"n":15,"t":"护送保罗的人带他到了雅典，他们领了保罗的命令，叫西拉和提摩太赶快到他那里来，然后回去了。","notes":[]},{"n":16,"t":"保罗在雅典等候他们的时候，看见满城都是偶像，就心里非常难过。","notes":[],"heads":["保罗在雅典"]},{"n":17,"t":"于是他在会堂里与犹太人和虔敬的人，以及每日在市场上所遇见的人辩论。","notes":[]},{"n":18,"t":"还有伊壁鸠鲁和斯多亚两派的哲学家也与他争辩。有的说：“这胡言乱语的要说什么？”有的说：“他似乎是宣传外邦鬼神的。”这是因保罗传讲耶稣与复活的福音。","notes":[]},{"n":19,"t":"他们就把他带到亚略巴古，说：“你所讲的这新学说，我们也可以知道吗？","notes":[]},{"n":20,"t":"因为你有些奇怪的事传到我们耳中，我们想知道这些事是什么意思。”","notes":[]},{"n":21,"t":"原来所有的雅典人和居住在那里的外国人都无暇管别的事，只是谈谈或听听新闻。","notes":[]},{"n":22,"t":"保罗站在亚略巴古当中，说：“诸位雅典人！我看你们凡事很敬畏鬼神。","notes":[]},{"n":23,"t":"我到处走走的时候，仔细观察你们所敬拜的，发现一座坛，上面写着‘献给未识之神明’。你们所不认识而敬拜的，我现在向你们宣告：","notes":[]},{"n":24,"t":"他是创造宇宙和其中万物的神；他既是天地的主，就不住在人手所造的殿宇里，","notes":[]},{"n":25,"t":"也不用人手去服侍，好像缺少什么似的；自己倒将生命、气息、万物赐给万人。","notes":[]},{"n":26,"t":"他从一人造出万族，居住在全地面上，并且预先定准他们的年限和所住的疆界，","notes":["“人”：有古卷是“血脉”。"]},{"n":27,"t":"为要使他们寻求神，或者可以揣摩而找到他，其实他离我们各人不远。","notes":[]},{"n":28,"t":"我们生活、行动、存在都在于他。就如你们的诗人也有人说：‘我们也是他所生的。’","notes":[]},{"n":29,"t":"既然我们是神所生的，就不应该以为神的神性像人用手艺和心思所雕刻的金、银、石像一般。","notes":[]},{"n":30,"t":"世人蒙昧无知的时候，神并不追究，如今却吩咐各处的人都要悔改。","notes":[]},{"n":31,"t":"因为他已经定了日子，要藉着他所设立的人按公义审判天下，并且使他从死人中复活，给万人作可信的凭据。”","notes":[]},{"n":32,"t":"众人听见死人复活的话，就有人讥诮他；又有人说：“我们会再听你讲这事。”","notes":[]},{"n":33,"t":"于是保罗从他们当中出去了。","notes":[]},{"n":34,"t":"但有几个人依附他，信了主，其中有亚略巴古的议员丢尼修，和一个名叫大马哩的妇人，还有几个与他们一起的人。","notes":[]}]},"18":{"heading":"保罗在哥林多","verses":[{"n":1,"t":"这些事以后，保罗离开雅典，来到哥林多。","notes":[]},{"n":2,"t":"他遇见一个生在本都的犹太人，名叫亚居拉。不久前，他带着妻子百基拉从意大利来，因为克劳第命令所有的犹太人都离开罗马。保罗去投靠他们。","notes":[]},{"n":3,"t":"他们本是制造帐棚为业。保罗因与他们同业，就和他们同住，一同做工。","notes":[]},{"n":4,"t":"每逢安息日，保罗在会堂里辩论，劝导犹太人和希腊人。","notes":[]},{"n":5,"t":"西拉和提摩太从马其顿来的时候，保罗正专心传道，向犹太人证明耶稣是基督。","notes":[]},{"n":6,"t":"当他们抗拒他、毁谤他的时候，他就抖掉衣裳的灰尘，对他们说：“你们的罪归到你们自己的头上，与我无干。从今以后，我要往外邦人那里去。”","notes":[]},{"n":7,"t":"于是他离开那里，到了一个人的家里，他名叫提多．犹士都，是敬拜神的人，他的家靠近会堂。","notes":["“提多．犹士都”：有古卷是“犹士都”。"]},{"n":8,"t":"会堂的主管基利司布和全家都信了主，还有许多哥林多人听了就信，而且受了洗。","notes":[]},{"n":9,"t":"夜间，主在异象中对保罗说：“不要怕，只管讲，不要沉默，","notes":[]},{"n":10,"t":"有我与你同在，没有人会下手害你，因为在这城里有许多属我的人。”","notes":[]},{"n":11,"t":"保罗在那里住了一年六个月，将神的道教导他们。","notes":[]},{"n":12,"t":"到迦流作亚该亚省长的时候，犹太人齐心起来攻击保罗，拉他到法庭，","notes":[]},{"n":13,"t":"说：“这个人教唆人不按着律法敬拜神。”","notes":[]},{"n":14,"t":"保罗刚要开口，迦流对犹太人说：“你们这些犹太人哪！如果是为冤枉或奸恶的事，我理当耐性听你们。","notes":[]},{"n":15,"t":"既然你们所争论的是关乎用字、名目和你们的律法，你们自己去办吧！这样的事我不愿意审问。”","notes":[]},{"n":16,"t":"于是，他把他们逐出法庭。","notes":[]},{"n":17,"t":"众人就揪住会堂的主管所提尼，在法庭前打他。这些事迦流都不管。","notes":[]},{"n":18,"t":"保罗又住了好些日子，就辞别了弟兄，坐船到叙利亚去。百基拉、亚居拉和他同去。他因为许过愿，就在坚革哩剃了头发。","notes":[],"heads":["保罗回到安提阿"]},{"n":19,"t":"到了以弗所，保罗就把他们留在那里，自己进了会堂，和犹太人辩论。","notes":[]},{"n":20,"t":"众人请他多住些日子，他没有答应，","notes":[]},{"n":21,"t":"就辞别他们，说：“神若许可，我还要回到你们这里来。”于是他上船离开以弗所。","notes":[]},{"n":22,"t":"他在凯撒利亚下了船，上耶路撒冷去问候教会，随后下安提阿去。","notes":[]},{"n":23,"t":"他在那里住了些日子，又离开了那里，逐一经过加拉太和弗吕家各地方，坚固众门徒。","notes":[]},{"n":24,"t":"有一个生在亚历山大的犹太人，名叫亚波罗，来到以弗所，他很有口才，很会讲解圣经。","notes":[],"heads":["亚波罗在以弗所讲道"]},{"n":25,"t":"这人已经在主的道路上受了训练，心里火热，精确地讲论和教导耶稣的事；可是他只知道约翰的洗礼。","notes":[]},{"n":26,"t":"他开始在会堂里放胆讲道；百基拉、亚居拉听见，就接他来，将神的道路给他更精确地讲解。","notes":["有古卷是“主的道路”。"]},{"n":27,"t":"他想要往亚该亚去，弟兄们就勉励他，并写信请门徒们接待他，他到了那里，多多帮助那些蒙恩信主的人，","notes":[]},{"n":28,"t":"因为他在公众面前极力驳倒犹太人，引圣经证明耶稣是基督。","notes":[]}]},"19":{"heading":"保罗在以弗所","verses":[{"n":1,"t":"亚波罗在哥林多的时候，保罗经过了内陆地区，来到以弗所，在那里他遇见几个门徒，","notes":[]},{"n":2,"t":"问他们：“你们信的时候领受了圣灵没有？”他们说：“没有，我们连什么是圣灵都没有听过。”","notes":[]},{"n":3,"t":"保罗说：“这样，你们受的是什么洗呢？”他们说：“是受了约翰的洗。”","notes":[]},{"n":4,"t":"保罗说：“约翰所施的是悔改的洗礼，他告诉百姓当信那在他以后要来的那位，就是耶稣。”","notes":[]},{"n":5,"t":"他们听见这话以后，就奉主耶稣的名受洗。","notes":[]},{"n":6,"t":"保罗给他们按手，圣灵就降在他们身上，他们开始说方言 和说预言。","notes":["“方言”或译“灵语”。"]},{"n":7,"t":"他们约有十二个人。","notes":[]},{"n":8,"t":"保罗进会堂，一连三个月放胆讲道，辩论神国的事，劝导众人。","notes":[]},{"n":9,"t":"后来，有些人心里刚硬不信，在众人面前毁谤这道；保罗就离开他们，也叫门徒与他们分开，就在推喇奴的讲堂天天辩论。","notes":[]},{"n":10,"t":"这样有两年之久，使一切住在亚细亚的，无论是犹太人是希腊人，都听见主的道。","notes":[]},{"n":11,"t":"神藉保罗的手行了些奇异的神迹，","notes":[],"heads":["士基瓦的儿子们"]},{"n":12,"t":"甚至有人从保罗身上拿走手巾或围裙放在病人身上，病就消除了，邪灵也出去了。","notes":[]},{"n":13,"t":"那时，有几个巡回各处念咒赶鬼的犹太人，擅自利用主耶稣的名，向那些被邪灵所附的人说：“我奉保罗所传的耶稣命令你们出来！”","notes":[]},{"n":14,"t":"做这事的是犹太祭司长士基瓦的七个儿子。","notes":[]},{"n":15,"t":"但邪灵回答他们：“耶稣我知道，保罗我也认识，你们却是谁呢？”","notes":[]},{"n":16,"t":"被邪灵所附的人就扑到他们身上，制伏他们，胜过他们，使他们赤着身子，受了伤，从那房子里逃出去了。","notes":[]},{"n":17,"t":"凡住在以弗所的，无论是犹太人是希腊人，都知道这件事，也都惧怕；主耶稣的名从此就更被尊为大了。","notes":[]},{"n":18,"t":"许多已经信的人来承认并公开自己所行的事。","notes":[]},{"n":19,"t":"又有许多平素行邪术的人把他们的书都拿来，堆积在众人面前焚烧。他们计算书价，得知共值五万块银钱。","notes":[]},{"n":20,"t":"这样，主的道大大兴旺，而且普遍传开了。","notes":[]},{"n":21,"t":"这些事过后，保罗心里决定要经过马其顿、亚该亚，就往耶路撒冷去。他说：“我到了那里以后，也必须到罗马去看看。”","notes":[],"heads":["以弗所的暴动"]},{"n":22,"t":"于是他差遣两个助手提摩太和以拉都往马其顿去，自己暂时留在亚细亚。","notes":[]},{"n":23,"t":"那时，因这道路而起的骚动不小。","notes":[]},{"n":24,"t":"有一个银匠，名叫底米丢，是制造亚底米神银龛的，他使从事这手艺的人生意发达。","notes":[]},{"n":25,"t":"他聚集他们和同行的工人，说：“诸位，你们知道我们是倚靠这生意发财的。","notes":[]},{"n":26,"t":"你们看到，也听见这保罗不但在以弗所，也几乎在亚细亚全地，引诱迷惑了许多人，说：‘人手所做的不是神明。’","notes":[]},{"n":27,"t":"这样，不仅我们这行业陷入被藐视的危险，就是大女神亚底米的庙也要被人轻看，连亚细亚全地和普天下所敬拜的女神的威望也受损害了。”","notes":[]},{"n":28,"t":"众人听见，就怒气冲冲，喊着说：“大哉，以弗所人的亚底米！”","notes":[]},{"n":29,"t":"于是满城都骚动起来。众人抓住与保罗同行的马其顿人该犹和亚里达古，齐心冲进剧场。","notes":[]},{"n":30,"t":"保罗想要进到民众那里，门徒却不许他去。","notes":[]},{"n":31,"t":"连亚细亚的几位官员，是保罗的朋友，也打发人来劝他不要冒险到剧场里去。","notes":[]},{"n":32,"t":"聚集的人乱成一团，有的喊这个，有的喊那个，大半不知道为了什么聚集。","notes":[]},{"n":33,"t":"犹太人把亚历山大推出去，人群中有人怂恿他，他就做手势，要向民众申诉。","notes":[]},{"n":34,"t":"但他们一认出他是犹太人，大家就异口同声喊着：“大哉，以弗所人的亚底米！”约喊了两小时。","notes":[]},{"n":35,"t":"城里的书记官安抚了群众后，说：“以弗所人哪，谁不知道以弗所人的城是看守大亚底米的庙和从宙斯那里落下来的像的守护者呢？","notes":[]},{"n":36,"t":"既然这些事是驳不倒的，你们就要安静下来，不可妄动。","notes":[]},{"n":37,"t":"你们把这些人带来，他们并没有偷窃庙中之物，也没有亵渎我们的女神。","notes":[]},{"n":38,"t":"如果底米丢和他同行的手艺人有控告的事，自有公堂，也有省长，他们可以彼此控告。","notes":[]},{"n":39,"t":"你们若有别的事请求，可以在合法的集会里解决。","notes":[]},{"n":40,"t":"今日的扰乱本是无缘无故的，有被控告的危险。这次的骚动，我们也说不出理由来。”","notes":[]},{"n":41,"t":"他说完这些话，就叫众人散会。","notes":[]}]},"20":{"heading":"保罗再次访问马其顿和希腊","verses":[{"n":1,"t":"骚乱平定以后，保罗请门徒来，劝勉了他们，就辞别他们，往马其顿去。","notes":[]},{"n":2,"t":"他走遍那一带地方，用许多话劝勉门徒，然后来到希腊，","notes":[]},{"n":3,"t":"在那里住了三个月。他快要坐船往叙利亚去的时候，犹太人设计害他，他就决定从马其顿回去。","notes":[]},{"n":4,"t":"同他到亚细亚去的，有庇哩亚人毕罗斯的儿子所巴特，帖撒罗尼迦人亚里达古和西公都，还有特庇人该犹和提摩太，又有亚细亚人推基古和特罗非摩。","notes":[]},{"n":5,"t":"这些人先走，在特罗亚等候我们。","notes":[]},{"n":6,"t":"过了除酵节的日子，我们从腓立比开船，五天以后到了特罗亚，和他们相会，在那里住了七天。","notes":[]},{"n":7,"t":"七日的第一日，我们聚会擘饼的时候，保罗因次日要起行，就为他们讲道，直讲到半夜。","notes":[],"heads":["保罗最后一次访问特罗亚"]},{"n":8,"t":"我们聚会的那座楼上有好些灯火。","notes":[]},{"n":9,"t":"有一个少年，名叫犹推古，坐在窗口上，沉沉入睡。保罗讲了多时，少年睡熟了，从三层楼上掉下去，扶起来时已经死了。","notes":[]},{"n":10,"t":"保罗下去，伏在他身上，抱着他，说：“你们不要慌乱，他还有气呢！”","notes":[]},{"n":11,"t":"保罗又上楼去，擘饼，吃了，再讲了许久，直到天亮才离开。","notes":[]},{"n":12,"t":"他们把那活过来的孩子带走，大家得到很大的安慰。","notes":[]},{"n":13,"t":"我们先上船，起航往亚朔去，想要在那里接保罗；因为他是这样安排的，他自己本来打算要走陆路。","notes":[],"heads":["从特罗亚到米利都"]},{"n":14,"t":"他既在亚朔与我们相会，我们就接他上船，来到米推利尼。","notes":[]},{"n":15,"t":"我们从那里开船，第二天到了基阿的对岸；再下一天，在撒摩靠岸，又过了一天，到了米利都。","notes":[]},{"n":16,"t":"因为保罗早已决定要越过以弗所，免得在亚细亚耽延，他急忙前行，假如可能的话，在五旬节前能赶到耶路撒冷。","notes":[]},{"n":17,"t":"保罗从米利都打发人往以弗所去，请教会的长老来。","notes":[],"heads":["保罗向以弗所长老讲话"]},{"n":18,"t":"他们来了，保罗对他们说：“你们自己知道，自从我到亚细亚的第一天，我怎样跟你们相处，","notes":[]},{"n":19,"t":"怎样凡事谦卑，以眼泪服侍主，又因犹太人的谋害经历试炼。","notes":[]},{"n":20,"t":"你们也知道，凡对你们有益的，我没有一样隐瞒不说的，或在公众面前，或在每一个人的家里，我都教导你们，","notes":[]},{"n":21,"t":"不论犹太人和希腊人，我都已证明他们当在神面前悔改，信靠我们的主耶稣。","notes":[]},{"n":22,"t":"现在我被圣灵催迫要往耶路撒冷去，虽然不知道在那里会遭遇什么事，","notes":["“催迫”：原文直译“捆绑”。"]},{"n":23,"t":"但知道圣灵在各城里向我指证，说有捆锁与患难等着我。","notes":[]},{"n":24,"t":"我却不以性命为念，只要走完我的路程，完成我从主耶稣所领受的职分，为神恩典的福音作见证。","notes":[]},{"n":25,"t":"“我素常在你们中间到处传讲神的国；现在我知道，你们众人以后不会再见到我的面了。","notes":[]},{"n":26,"t":"所以我今日向你们作证，你们中间无论何人死亡，罪不在我。","notes":[]},{"n":27,"t":"因为神一切的旨意，我并没有退缩不传给你们的。","notes":[]},{"n":28,"t":"圣灵立你们作全群的监督，你们就当为自己谨慎，也为全群谨慎，牧养神的教会，就是他用自己血所买来的。","notes":["“神”：有古卷是“主”；另有古卷是“主和神”。","“买来的”或译“救赎的”。"]},{"n":29,"t":"我知道，在我离开以后必有凶暴的豺狼进入你们中间，不顾惜羊群。","notes":[]},{"n":30,"t":"就是你们中间也必有人起来，说悖谬的话，要引诱门徒跟从他们。","notes":[]},{"n":31,"t":"所以你们要警醒，记念我三年之久，昼夜不断地流泪劝戒你们各人。","notes":[]},{"n":32,"t":"现在我把你们交托给神和他恩惠的道；这道能建立你们，使你们和一切成圣的人同得基业。","notes":[]},{"n":33,"t":"我未曾贪图一个人的金、银或衣服。","notes":[]},{"n":34,"t":"你们自己知道，我靠两只手工作来供给我和同工的需用。","notes":[]},{"n":35,"t":"我凡事给你们作榜样，叫你们知道应当这样劳苦，扶助软弱的人，又当记念主耶稣的话，说：‘施比受更为有福。’”","notes":[]},{"n":36,"t":"保罗说完了这些话，就和大家跪下来祷告。","notes":[]},{"n":37,"t":"众人痛哭，抱着保罗的颈项跟他亲吻。","notes":[]},{"n":38,"t":"叫他们最伤心的，就是他说“以后不会再见到我的面”那句话。于是他们送他上船去了。","notes":[]}]},"21":{"heading":"保罗上耶路撒冷","verses":[{"n":1,"t":"我们离别了众人，就开船直航到哥士，第二天到了罗底，又从那里到帕大喇。","notes":[]},{"n":2,"t":"我们遇见一只船要往腓尼基去，就上船起航。","notes":[]},{"n":3,"t":"我们望见塞浦路斯，就从南边行过，往叙利亚去，在推罗上岸，因为船要在那里卸货。","notes":[]},{"n":4,"t":"我们在那里找到了一些门徒，就住了七天。他们藉着圣灵的感动，告诉保罗不要上耶路撒冷去。","notes":[]},{"n":5,"t":"几天之后，我们又出发前行。他们众人同妻子儿女都送我们到城外，我们都跪在滩上祷告，彼此辞别。","notes":[]},{"n":6,"t":"我们上了船，他们就回家去了。","notes":[]},{"n":7,"t":"我们从推罗行完航程，来到了多利买，问候那里的弟兄，和他们同住了一天。","notes":[]},{"n":8,"t":"第二天，我们离开那里，来到凯撒利亚，就进了传福音的腓利家里，和他同住；他是那七个执事里的一个。","notes":[]},{"n":9,"t":"他有四个女儿，都是未出嫁的，都会说预言。","notes":[]},{"n":10,"t":"我们在那里多住了好几天，有一个先知，名叫亚迦布，从犹太下来。","notes":[]},{"n":11,"t":"他到了我们这里，就拿保罗的腰带，捆上自己的手脚，说：“圣灵这样说：‘犹太人在耶路撒冷要如此捆绑这腰带的主人，把他交在外邦人手里。’”","notes":[]},{"n":12,"t":"我们听见这些话，就跟当地的人苦劝保罗不要上耶路撒冷去。","notes":[]},{"n":13,"t":"于是保罗回答：“你们为什么这样痛哭，使我心碎呢？我为主耶稣的名，不但被人捆绑，就是死在耶路撒冷也是愿意的。”","notes":[]},{"n":14,"t":"既然保罗不听劝，我们就住了口，只说：“愿主的旨意成就。”","notes":[]},{"n":15,"t":"过了这几天，我们收拾行李上耶路撒冷去。","notes":[]},{"n":16,"t":"有凯撒利亚的几个门徒和我们同去，带我们到一个早期的门徒塞浦路斯人拿孙的家里，请我们与他同住。","notes":[]},{"n":17,"t":"我们到了耶路撒冷，弟兄们欢欢喜喜地接待我们。","notes":[],"heads":["保罗访问雅各"]},{"n":18,"t":"第二天，保罗同我们去见雅各；所有的长老也都在场。","notes":[]},{"n":19,"t":"保罗向他们问安，然后将神用他在外邦人中所做的事奉，一一述说了。","notes":[]},{"n":20,"t":"他们听见了，就归荣耀给神，对保罗说：“弟兄，你看犹太人中有数以万计的信徒，而他们都是热心于律法的人。","notes":[]},{"n":21,"t":"他们曾听见人说，你教导所有在外邦的犹太人离弃摩西，对他们说，不要给孩子行割礼，也不要遵守规矩。","notes":[]},{"n":22,"t":"众人必听见你来了，这可怎么办呢？","notes":[]},{"n":23,"t":"你就照着我们的话做吧！我们这里有四个人，都有愿在身。","notes":[]},{"n":24,"t":"你带他们去，与他们一同行洁净的礼，替他们缴纳规费，让他们得以剃头。这样，众人就会知道，先前所听见关于你的事都是假的；而且也知道，你自己为人循规蹈矩，遵行律法。","notes":[]},{"n":25,"t":"至于信主的外邦人，我们已经根据我们的决议写信，叫他们要禁戒偶像所玷污的东西、血和勒死的牲畜，禁戒淫乱。”","notes":["有古卷加“他们没有什么可控告你。”"]},{"n":26,"t":"于是保罗带着那四个人，第二天与他们一同行了洁净礼，进了圣殿，报告洁净期满的日子，等候祭司为他们各人献上祭物。","notes":[]},{"n":27,"t":"那七日将完，从亚细亚来的犹太人看见保罗在圣殿里，就煽动所有的群众，下手拿住他，","notes":[],"heads":["保罗在圣殿里被捕"]},{"n":28,"t":"喊着：“以色列人哪，来帮忙！这就是在各处教导众人糟蹋我们百姓、律法和这地方的人。不但如此，他还带了希腊人进圣殿，污秽了这圣地。”","notes":[]},{"n":29,"t":"这话是因他们曾看见以弗所人特罗非摩跟保罗一起在城里，以为保罗带他进了圣殿。","notes":[]},{"n":30,"t":"于是全城都骚动，百姓一齐跑来，拿住保罗，拉他出圣殿，殿门立刻都关了。","notes":[]},{"n":31,"t":"他们正想要杀他，有人报信给营里的千夫长，说耶路撒冷全城都乱了。","notes":[]},{"n":32,"t":"千夫长立刻带着士兵和几个百夫长，跑下去到他们那里。他们见了千夫长和士兵，就停下来不打保罗。","notes":[]},{"n":33,"t":"于是千夫长上前拿住他，吩咐用两条铁链捆锁，又问他是什么人，做了什么事。","notes":[]},{"n":34,"t":"群众中有的喊这个，有的喊那个；因为这样乱嚷，千夫长无法知道实情，就下令将保罗带进营楼去。","notes":[]},{"n":35,"t":"保罗一走上台阶，群众挤得凶猛，士兵只得将保罗抬起来。","notes":[]},{"n":36,"t":"一群人跟在后面，喊着：“除掉他！”","notes":[]},{"n":37,"t":"保罗快要被带进营楼时，对千夫长说：“我可以对你说句话吗？”千夫长说：“你懂得希腊话吗？","notes":[],"heads":["保罗为自己辩护"]},{"n":38,"t":"那你就不是从前作乱、带领四千凶徒往旷野去的那埃及人了。”","notes":[]},{"n":39,"t":"保罗说：“我本是犹太人，生在基利家的大数，并不是无名小城的公民。求你准我对百姓说话。”","notes":[]},{"n":40,"t":"千夫长准了。保罗就站在台阶上，向百姓做了个手势，要他们静下来，保罗就用希伯来话对他们说：","notes":[]}]},"22":{"heading":"保罗叙述归主的经过","verses":[{"n":1,"t":"“诸位父老弟兄，请听我现在对你们的申辩。”","notes":[]},{"n":2,"t":"他们听保罗说的是希伯来话，就更加安静了。","notes":[]},{"n":3,"t":"保罗说：“我原是犹太人，生在基利家的大数，但在这城里长大，在迦玛列门下按着我们祖宗严紧的律法受教，热心事奉神，就如你们大家今日一样。","notes":[]},{"n":4,"t":"我也曾迫害信奉这道路的人，置他们于死地，无论男女都捆绑，关在监里。","notes":[]},{"n":5,"t":"这是大祭司和议会的众长老都可以给我作证的。我又从他们那里领了致弟兄们的书信，往大马士革去，要把在那里的信徒绑起来，带到耶路撒冷受刑。”","notes":[]},{"n":6,"t":"“当我走近大马士革的时候，约在中午，忽然有一道大光从天上下来，照射在我周围。","notes":[]},{"n":7,"t":"我就仆倒在地，听见有声音对我说：‘扫罗！扫罗！你为什么迫害我？’","notes":[]},{"n":8,"t":"我回答：‘主啊！你是谁？’他对我说：‘我就是你所迫害的拿撒勒人耶稣。’","notes":[]},{"n":9,"t":"跟我一起的人看见了那光，却没有听见那位对我说话的声音。","notes":[]},{"n":10,"t":"我说：‘主啊，我该做什么？’主说：‘起来，进大马士革去，在那里有人会把指派你做的一切事告诉你。’","notes":[]},{"n":11,"t":"我因那光的闪耀不能看见，跟我一起的人就拉着我的手进了大马士革。","notes":[]},{"n":12,"t":"“那里有一个人，名叫亚拿尼亚，按着律法是虔诚人，为所有住在那里的犹太人所称赞。","notes":[]},{"n":13,"t":"他来见我，站在旁边，对我说：‘扫罗弟兄，你看见吧！’就在那时，我恢复视觉，看见了他。","notes":[]},{"n":14,"t":"他又说：‘我们祖宗的神拣选了你，让你明白他的旨意，又看见那义者，听见他口中所出的声音。","notes":[]},{"n":15,"t":"因为你要将所看见的、所听见的，对着万人作他的见证人。","notes":[]},{"n":16,"t":"现在你为什么耽延呢？起来，受洗，求告他的名，洗去你的罪。’”","notes":[]},{"n":17,"t":"“后来，我回到耶路撒冷，在圣殿里祷告的时候，魂游象外，","notes":[],"heads":["保罗奉召向外邦人传道"]},{"n":18,"t":"看见主对我说：‘你赶紧离开耶路撒冷，越快越好，因为这里的人不接受你为我作的见证。’","notes":[]},{"n":19,"t":"我就说：‘主啊，他们都知道，我从前在各会堂里把信你的人监禁，又鞭打他们。","notes":[]},{"n":20,"t":"当你的见证人司提反被害流血的时候，我也站在一旁赞同；又为打死他的人看守衣裳。’","notes":[]},{"n":21,"t":"主对我说：‘你去吧！我要差你到远方外邦人那里去。’”","notes":[]},{"n":22,"t":"众人听他说到这句话，就高声说：“这样的人，从地上除掉他吧！他是该死的。”","notes":[],"heads":["保罗与长官交涉"]},{"n":23,"t":"大家一边喧嚷一边摔衣裳，向空中撒灰尘。","notes":[]},{"n":24,"t":"千夫长下令把保罗带进营楼，叫人用鞭子拷问他，要知道他们向他这样喧嚷是什么缘故。","notes":[]},{"n":25,"t":"他们刚用皮条把他捆上的时候，保罗对站在旁边的百夫长说：“一个罗马人，又未被定罪，你们就鞭打他是合法的吗？”","notes":[]},{"n":26,"t":"百夫长听见这话，就去见千夫长，报告说：“你要怎么办呢？这个人是罗马人。”","notes":[]},{"n":27,"t":"千夫长就来问保罗：“你告诉我，你是罗马人吗？”保罗说：“是。”","notes":[]},{"n":28,"t":"千夫长回答：“我用了许多银子才得到罗马公民的身份。”保罗说：“我生来就是。”","notes":[]},{"n":29,"t":"于是那些要拷问保罗的人立刻离开他走了。千夫长一知道他是罗马人，又因为曾捆绑了他，也害怕起来。","notes":[]},{"n":30,"t":"第二天，千夫长为要知道犹太人控告保罗的实情，就解开他，下令祭司长们和全议会的人都聚集，然后将保罗带下来，叫他站在他们面前。","notes":[],"heads":["保罗在议会前申诉"]}]},"23":{"heading":"杀害保罗的阴谋","verses":[{"n":1,"t":"保罗定睛看着议会的人，说：“诸位弟兄，我在神面前，行事为人都是凭着清白的良心，直到今日。”","notes":[]},{"n":2,"t":"亚拿尼亚大祭司就吩咐旁边站着的人打他的嘴。","notes":[]},{"n":3,"t":"这时，保罗对他说：“你这粉饰的墙，神要打你！你坐堂是要按律法审问我，你竟违背律法，命令人打我吗？”","notes":[]},{"n":4,"t":"站在旁边的人说：“你竟敢辱骂神的大祭司吗？”","notes":[]},{"n":5,"t":"保罗说：“弟兄们，我不知道他是大祭司；因为经上记着：‘不可毁谤你百姓的官长。’”","notes":[]},{"n":6,"t":"保罗看出他们一部分是撒都该人，一部分是法利赛人，就在议会中喊着：“诸位弟兄，我是法利赛人，也是法利赛人的子孙。我现在受审问是为有关死人复活的盼望。”","notes":[]},{"n":7,"t":"说了这话，法利赛人和撒都该人争论起来，会众分为两派。","notes":[]},{"n":8,"t":"因为撒都该人一方面说没有复活，另一方面没有天使和鬼魂；法利赛人却承认两方面都有。","notes":[]},{"n":9,"t":"于是大大地争吵起来；有几个法利赛派的文士站起来争辩说：“我们看不出这人有什么错处；说不定有鬼魂或者天使对他说过话呢！”","notes":[]},{"n":10,"t":"那时争辩越来越大，千夫长恐怕保罗被他们扯碎了，就命令士兵下去，把他从众人当中抢出来，带进营楼去。","notes":[]},{"n":11,"t":"当夜，主站在保罗旁边，说：“放心吧！你怎样在耶路撒冷为我作见证，也必怎样在罗马为我作见证。”","notes":[]},{"n":12,"t":"到了天亮，犹太人同谋起誓，说“若不先杀保罗就不吃不喝”。","notes":[]},{"n":13,"t":"参与这阴谋的有四十多人。","notes":[]},{"n":14,"t":"他们来见祭司长和长老，说：“我们已经发了重誓，若不先杀保罗就什么也不吃。","notes":[]},{"n":15,"t":"现在你们和议会要通知千夫长，叫他把保罗带到你们这里来，假装要详细调查他的事；我们已经预备好，在他来到这里以前就杀掉他。”","notes":[]},{"n":16,"t":"保罗的外甥听见他们设下埋伏，就来到营楼里告诉保罗。","notes":[]},{"n":17,"t":"保罗请一个百夫长来，说：“你领这青年去见千夫长，他有事告诉他。”","notes":[]},{"n":18,"t":"于是百夫长把他领去见千夫长，说：“被囚的保罗请我到他那里，求我领这青年来见你；他有事告诉你。”","notes":[]},{"n":19,"t":"千夫长就拉着他的手，走到一旁，私下问他：“你有什么事告诉我呢？”","notes":[]},{"n":20,"t":"他说：“犹太人已经约定，要求你明天把保罗带到议会去，假装要详细查问他的事。","notes":[]},{"n":21,"t":"你切不要随从他们，因为他们有四十多人埋伏，已经起誓，若不先杀掉保罗就不吃不喝。现在都预备好了，只等你的允准。”","notes":[]},{"n":22,"t":"于是千夫长打发那青年走，嘱咐他：“不要告诉人，你已将这些事报告我了。”","notes":[]},{"n":23,"t":"于是，千夫长叫了两个百夫长来，说：“预备步兵二百、骑兵七十、长枪手二百，今夜九点往凯撒利亚去；","notes":[],"heads":["保罗被解交腓力斯总督"]},{"n":24,"t":"也要预备牲口让保罗骑上，护送到腓力斯总督那里去。”","notes":[]},{"n":25,"t":"千夫长又写了公文，大略说：","notes":[]},{"n":26,"t":"“克劳第．吕西亚向腓力斯总督大人请安。","notes":[]},{"n":27,"t":"这个人被犹太人拿住，快被杀害时，我得知他是罗马人，就带士兵下去，把他救了出来。","notes":[]},{"n":28,"t":"因为我要知道他们告他的罪状，就带他下到他们的议会去。","notes":[]},{"n":29,"t":"我查知他被告发是因他们律法上的争论，并没有什么该死或该监禁的罪名。","notes":[]},{"n":30,"t":"后来有人把要害他的计谋告诉我，我立刻把他解到你那里去，又命令告他的人在你面前告他。”","notes":["有古卷加“愿你平安。”"]},{"n":31,"t":"于是士兵照所命令他们的，连夜把保罗带到安提帕底。","notes":[]},{"n":32,"t":"第二天，由骑兵护送保罗，他们就回营楼去。","notes":[]},{"n":33,"t":"骑兵来到凯撒利亚，把公文呈给总督，就叫保罗站在他面前。","notes":[]},{"n":34,"t":"总督读了公文，问保罗是哪一省的人；一知道他是基利家人，","notes":[]},{"n":35,"t":"就说：“等告你的人来到，我才详细听你。”于是他命令把保罗拘留在希律的衙门里。","notes":[]}]},"24":{"heading":"犹太人控告保罗","verses":[{"n":1,"t":"过了五天，亚拿尼亚大祭司、几个长老和一个叫帖土罗的律师下来，向总督控告保罗。","notes":[]},{"n":2,"t":"保罗一被传来，帖土罗就开始控告他，说：“腓力斯大人，我们因你得以享受国泰民安，并且这一国的弊病，因着你的远见得以改革。","notes":[]},{"n":3,"t":"我们随时随地都满心感激不尽。","notes":[]},{"n":4,"t":"为了不敢耽搁你太久，我只求你宽容一下，听我们说几句话。","notes":[]},{"n":5,"t":"我们看这个人如同瘟疫一般，是鼓动普天下所有的犹太人作乱的人，又是拿撒勒教派里的一个头目。","notes":[]},{"n":6,"t":"他甚至连圣殿也要污秽，我们就把他捉拿了。","notes":["有古卷加“要按我们的律法审问，7 可是，吕西亚千夫长前来，甚是强横，从我们手中把他夺去，下令告他的人到你这里来。”"]},{"n":8,"t":"你自己审问他，就可以知道我们所控告他的一切事了。”","notes":[]},{"n":9,"t":"众犹太人也随着控告他，说：“这些事情确是这样。”","notes":[]},{"n":10,"t":"总督示意叫保罗说话，保罗就回答：“我知道你在本国作法官多年，所以我乐意为自己申辩。","notes":[],"heads":["保罗为自己辩护"]},{"n":11,"t":"你查问就可以知道，从我上耶路撒冷去礼拜到今日不过十二天。","notes":[]},{"n":12,"t":"他们并没有看见我在圣殿里跟人辩论，或在会堂里、在城里煽动群众。","notes":[]},{"n":13,"t":"也不能对你证实他们现在所控告我的事。","notes":[]},{"n":14,"t":"但有一件事我向你承认，就是我正按着他们所称为异端的道事奉我祖宗的神，又信合乎律法和先知书上所记载的一切。","notes":[]},{"n":15,"t":"我对神存着这些人自己也接受的盼望，就是义人和不义的人都要复活。","notes":[]},{"n":16,"t":"因此，我勉励自己，对神对人，时常存着无亏的良心。","notes":[]},{"n":17,"t":"过了几年，我带着周济本国的捐项和供物上去。","notes":[]},{"n":18,"t":"正献的时候，他们看见我在圣殿里已经洁净了，并没有聚众，也没有吵嚷，","notes":[]},{"n":19,"t":"惟有几个从亚细亚来的犹太人—他们若有控告我的事，应当到你面前来告我。","notes":[]},{"n":20,"t":"不然，让这些人自己说，他们看出我站在议会前的时候，有什么不对的地方。","notes":[]},{"n":21,"t":"纵然有，也不过是为了一句话，就是我站在他们中间喊说：‘我今日在你们面前受审，是为了死人复活。’”","notes":[]},{"n":22,"t":"腓力斯本是详细认识这道，就拖延他们，说：“且等吕西亚千夫长下来，我再审判你们的案。”","notes":[]},{"n":23,"t":"于是他下令百夫长看守保罗，要从宽待他，不可拦阻他的亲友来供给他。","notes":[]},{"n":24,"t":"过了几天，腓力斯和他夫人犹太女子土西拉一同来到，就叫保罗来，听他讲论信基督耶稣的事。","notes":[],"heads":["腓力斯留保罗在监里"]},{"n":25,"t":"保罗讲论公义、节制和将来的审判，腓力斯害怕起来，就回答：“你暂且去吧！等我有机会时再来叫你。”","notes":[]},{"n":26,"t":"腓力斯又指望保罗送他银钱，所以屡次叫他来，和他谈论。","notes":[]},{"n":27,"t":"过了两年，波求．非斯都接了腓力斯的任；腓力斯要讨犹太人的喜欢，就把保罗留在监里。","notes":[]}]},"25":{"heading":"保罗要向凯撒上诉","verses":[{"n":1,"t":"非斯都到省里上任，过了三天，就从凯撒利亚上耶路撒冷去。","notes":[]},{"n":2,"t":"祭司长和犹太人的领袖向他控告保罗；又央求他，","notes":[]},{"n":3,"t":"向他求情要对付保罗，把他提到耶路撒冷来，他们要在路上埋伏杀害他。","notes":[]},{"n":4,"t":"非斯都就回答：“保罗押在凯撒利亚，我自己快要往那里去。”","notes":[]},{"n":5,"t":"他又说：“所以，你们中间有权的人与我一同下去，那人若有什么不是，就让他们控告他。”","notes":[]},{"n":6,"t":"非斯都在他们那里住了不超过八天或十天，就下凯撒利亚去；第二天开庭，下令把保罗提上来。","notes":[]},{"n":7,"t":"保罗来了，那些从耶路撒冷下来的犹太人周围站着，提出许多严重而不能证实的事控告他。","notes":[]},{"n":8,"t":"保罗申辩说：“无论犹太人的律法，或是圣殿，或是凯撒，我都没有干犯。”","notes":[]},{"n":9,"t":"但非斯都要讨犹太人的喜欢，就回答保罗说：“你愿意上耶路撒冷去，在那里为这些事受我的审判吗？”","notes":[]},{"n":10,"t":"保罗说：“我现在站在凯撒的审判台前，这就是我应当受审的地方。我并没有对犹太人做过什么不对的事，这也是你明明知道的。","notes":[]},{"n":11,"t":"我若做了不对的事，犯了什么该死的罪，就是死我也不辞。他们所控告我的事若都不实，就没有人能把我交给他们。我要向凯撒上诉。”","notes":[]},{"n":12,"t":"非斯都和议会商量了，就回答：“既然你要向凯撒上诉，你就到凯撒那里去吧。”","notes":[]},{"n":13,"t":"过了些日子，亚基帕王和百妮基来到凯撒利亚，拜访非斯都。","notes":[],"heads":["被带到亚基帕百妮基前"]},{"n":14,"t":"他们在那里住了好些日子，非斯都将保罗的案件向王陈述，说：“这里有一个人，是腓力斯留在监里的。","notes":[]},{"n":15,"t":"我在耶路撒冷的时候，祭司长和犹太的长老把他的事禀报了，要求定他的罪。","notes":[]},{"n":16,"t":"我回覆他们，无论什么人，被告还没有和原告当面对质，没有机会为所控告的事申辩，就先定他罪的，这不是罗马人的规矩。","notes":[]},{"n":17,"t":"及至他们都来到这里，我没有耽误，第二天就开庭，下令把那人提上来。","notes":[]},{"n":18,"t":"控告他的人站起来告他，所控告的并没有任何我所预料的那等恶事。","notes":["有古卷没有“那等恶”。"]},{"n":19,"t":"不过，有几样辩论是有关他们自己敬鬼神的事，以及一个名叫耶稣的人，他已经死了，保罗却说他是活着的。","notes":[]},{"n":20,"t":"我对这些事不知该怎样处理，所以问他是否愿意上耶路撒冷去，在那里为这些事接受审判。","notes":[]},{"n":21,"t":"但保罗要求我留下他，要听皇上判断，我就下令把他留下，等我解他到凯撒那里去。”","notes":[]},{"n":22,"t":"亚基帕对非斯都说：“我也愿意亲自听听这个人。”非斯都说：“明天你就可以听他。”","notes":[]},{"n":23,"t":"第二天，亚基帕和百妮基大张旗鼓而来，与众千夫长和城里的显要进了大厅。非斯都一声令下，就有人将保罗带进来。","notes":[]},{"n":24,"t":"非斯都说：“亚基帕王和在这里的诸位，你们看这个人，他就是所有在耶路撒冷和这里的犹太人曾向我恳求呼叫，说不可容他再活着的。","notes":[]},{"n":25,"t":"但我查明他并没有犯什么该死的罪，并且他自己也已向皇帝上诉了，所以我决定把他解去。","notes":[]},{"n":26,"t":"论到这个人，我没有确实的事可以奏明主上。因此，我带他到你们面前，尤其到你亚基帕王面前，为要在查问之后有所呈奏。","notes":[]},{"n":27,"t":"因为据我看，解送囚犯而不指明他的罪状是不合理的。”","notes":[]}]},"26":{"heading":"保罗在亚基帕前申辩","verses":[{"n":1,"t":"亚基帕对保罗说：“准你为自己申诉。”于是保罗伸手辩护说：","notes":[]},{"n":2,"t":"“亚基帕王啊，犹太人所控告我的一切事，今日得以在你面前辩护，实为万幸。","notes":[]},{"n":3,"t":"更庆幸的是你熟悉犹太人的规矩和他们的争论；所以，求你耐心听我。","notes":[]},{"n":4,"t":"“我自幼为人如何，从起初在本国的同胞中，以及在耶路撒冷，所有的犹太人都知道。","notes":[]},{"n":5,"t":"他们若肯作见证，就知道我从起初是按着我们教中最严紧的教门作了法利赛人。","notes":[]},{"n":6,"t":"现在我站在这里受审，是为了对神向我们祖宗的应许存着盼望。","notes":[]},{"n":7,"t":"这应许，我们十二个支派，昼夜切切地事奉神，都指望得着。王啊，我正是因这指望被犹太人控告。","notes":[]},{"n":8,"t":"神使死人复活，你们为什么判断为不可信呢？","notes":[]},{"n":9,"t":"“从前我自己认为必须竭力反对拿撒勒人耶稣的名，","notes":[]},{"n":10,"t":"我在耶路撒冷也曾这样做过；我不但从祭司长得了权柄，把许多圣徒收在监里，而且他们被杀，我也表示赞成。","notes":["“表示”可能是以投不同颜色的卵石来表示赞成或反对。"]},{"n":11,"t":"在各会堂，我屡次用刑强迫他们说亵渎的话，我非常厌恶他们，甚至追逼他们，直到外邦的城镇。”","notes":[]},{"n":12,"t":"“那时，我带着祭司长的权柄和命令往大马士革去。","notes":[],"heads":["保罗叙述归主经过"]},{"n":13,"t":"王啊！我在路上，中午的时候，看见从天上有一道光，比太阳还亮，四面照射着我和跟我同行的人。","notes":[]},{"n":14,"t":"我们都仆倒在地，我就听见有声音用希伯来话对我说：‘扫罗！扫罗！你为什么迫害我？你用脚踢刺棒是自找苦吃的！’","notes":[]},{"n":15,"t":"我说：‘主啊，你是谁？’主说：‘我就是你所迫害的耶稣。","notes":[]},{"n":16,"t":"起来，站着，我向你显现的目的是要派你作仆役，为你所看见我的事，和我将要指示你的事作见证人。","notes":["有古卷没有“我”。"]},{"n":17,"t":"我也要救你脱离百姓和外邦人的手。我差你到他们那里去，","notes":[]},{"n":18,"t":"要开他们的眼睛，使他们从黑暗中转向光明，从撒但权下归向神；使他们因信我而得蒙赦罪，和一切成圣的人同得基业。’”","notes":[]},{"n":19,"t":"“因此，亚基帕王啊！我没有违背那从天上来的异象；","notes":[],"heads":["保罗向犹太和外邦人作见证"]},{"n":20,"t":"我先在大马士革，后在耶路撒冷和犹太全地，以及外邦，劝勉他们应当悔改归向神，行事与悔改的心相称。","notes":[]},{"n":21,"t":"为这缘故，犹太人在圣殿里拿住我，想要杀我。","notes":[]},{"n":22,"t":"然而，我蒙神的帮助，直到今日还站立得稳，向尊贵的和卑微的作见证。我所讲的，并不外乎众先知和摩西所说将来必成的事，","notes":[]},{"n":23,"t":"就是基督必须受害，并且首先从死人中复活，把亮光传给犹太人和外邦人。”","notes":[]},{"n":24,"t":"保罗这样申诉时，非斯都大声说：“保罗，你疯了！你的学问太大，反使你疯了！”","notes":[],"heads":["保罗恳请亚基帕信主"]},{"n":25,"t":"保罗说：“非斯都大人，我不是疯了，我说的乃是真实和清醒的话。","notes":[]},{"n":26,"t":"王也知道这些事，所以对王大胆直言，我深信这些事没有一件能向王隐瞒的，因为都不是在背地里做的。","notes":[]},{"n":27,"t":"亚基帕王啊，你信先知吗？我知道你是信的。”","notes":[]},{"n":28,"t":"亚基帕对保罗说：“你想稍微劝一劝就能说服我作基督徒了吗？”","notes":[]},{"n":29,"t":"保罗说：“无论少劝还是多劝，我向神所求的，不但你一个人，就是今天所有听我说话的人都要像我一样，只是不要有这些锁链。”","notes":[]},{"n":30,"t":"于是，王和总督以及百妮基跟同坐的人都站起来，","notes":[]},{"n":31,"t":"退到里面，彼此谈论说：“这个人并没有犯什么该死该监禁的罪。”","notes":[]},{"n":32,"t":"亚基帕对非斯都说：“这人若没有向凯撒上诉，早就被释放了。”","notes":[]}]},"27":{"heading":"保罗坐船往罗马","verses":[{"n":1,"t":"既然非斯都决定要我们坐船往意大利去，就将保罗和别的囚犯交给御营里的一个名叫犹流的百夫长。","notes":[]},{"n":2,"t":"有一只亚大米田的船要开往亚细亚沿海一带地方去，我们上了那船，就起航了；有马其顿的帖撒罗尼迦人亚里达古和我们同去。","notes":[]},{"n":3,"t":"第二天，我们到了西顿。犹流宽待保罗，准他往朋友那里去，受他们的照应。","notes":[]},{"n":4,"t":"我们又从那里开船，因为遇到逆风，就贴着塞浦路斯的背风岸航行，","notes":[]},{"n":5,"t":"渡过了基利家、旁非利亚一带的海面，就到了吕家的每拉。","notes":[]},{"n":6,"t":"在那里，百夫长找到一只亚历山大的船要往意大利去，就叫我们上了那船。","notes":[]},{"n":7,"t":"一连多日，船行得很慢，我们好不容易才来到革尼土的对面；又因被风拦阻，我们就贴着克里特岛背风岸，从撒摩尼对面航行。","notes":[]},{"n":8,"t":"我们沿岸前进，十分艰难，来到一个名叫佳澳的地方，离那里不远有拉西亚城。","notes":[]},{"n":9,"t":"航行的日子久了，已经过了禁食的节期，行船又危险，保罗就建议，","notes":[]},{"n":10,"t":"对众人说：“诸位，我看这次航行，不但货物和船要受损伤，大遭破坏，连我们的性命也难保。”","notes":[]},{"n":11,"t":"但百夫长信从船长和船主，不信保罗所说的。","notes":[]},{"n":12,"t":"且因在这港口不适宜过冬，船上大多数的人都主张开船离开这地方，或者能到非尼基去过冬。非尼基是克里特的一个港口，一面朝西南，一面朝西北。","notes":[]},{"n":13,"t":"当南风微微吹起时，他们以为对目的地已有了把握，就起锚，贴近克里特开去。","notes":[],"heads":["海上的风暴"]},{"n":14,"t":"过了不久，有一股叫“友拉革罗”的东北巨风从岛上扑来，","notes":[]},{"n":15,"t":"船被风抓住，无法顶风航行，我们只好任它漂流。","notes":[]},{"n":16,"t":"我们贴着一个叫高大的小岛的背风岸急航，好不容易才保住了救生艇。","notes":[]},{"n":17,"t":"既然把救生艇拉上来，他们就用缆索捆绑船底，又恐怕在赛耳底浅滩上搁浅，就落了篷，任船漂流。","notes":[]},{"n":18,"t":"我们被风浪逼得很急，第二天众人就把货物抛在海里。","notes":[]},{"n":19,"t":"第三天，他们又亲手把船上的器具抛弃了。","notes":[]},{"n":20,"t":"许多天都没有看到太阳和星辰，又有狂风大浪催逼，我们获救的指望都放弃了。","notes":[]},{"n":21,"t":"众人已有好几天没有吃东西，保罗就出来站在他们中间，说：“诸位，你们本该听我的话不离开克里特岛，就不致遭到这样的损失和破坏。","notes":[]},{"n":22,"t":"现在我劝你们放心，除了损失这条船，你们中间没有一人会丧失性命。","notes":[]},{"n":23,"t":"因为昨夜，我所属所事奉的神的使者站在我旁边，","notes":[]},{"n":24,"t":"说：‘保罗，不要害怕，你必定站在凯撒面前；并且神已把安全赐给与你同船的人了。’","notes":[]},{"n":25,"t":"所以，诸位可以放心，我信神怎样对我说，事情也要怎样成就；","notes":[]},{"n":26,"t":"只是我们必须在一个岛上搁浅。”","notes":[]},{"n":27,"t":"到了第十四天夜间，船在亚得里亚海漂来漂去。约在半夜，水手以为渐近旱地，","notes":[]},{"n":28,"t":"就去探测深浅，探得有十二丈；稍往前行，又探深浅，探得有九丈。","notes":["“丈”：参“度量衡表”；下同。"]},{"n":29,"t":"恐怕我们撞到礁石，他们就从船尾抛下四个锚，盼望天亮。","notes":[]},{"n":30,"t":"水手想弃船逃走，把救生艇缒下海里，假装要从船头抛锚的样子。","notes":[]},{"n":31,"t":"保罗对百夫长和士兵说：“这些人若不留在船上，你们就不能获救。”","notes":[]},{"n":32,"t":"于是士兵砍断救生艇的绳子，由它漂去。","notes":[]},{"n":33,"t":"天快亮的时候，保罗劝众人都用餐，说：“你们一直捱饿等候，不吃什么，已经十四天了。","notes":[]},{"n":34,"t":"所以我劝你们吃点东西，这是关乎你们获救的，因为你们各人连一根头发也不至于掉落。”","notes":[]},{"n":35,"t":"保罗说了这话，就拿起饼来，在众人面前祝谢了神，然后擘开来吃。","notes":[]},{"n":36,"t":"于是他们都放心，就吃了。","notes":[]},{"n":37,"t":"我们在船上的共有二百七十六个人。","notes":[]},{"n":38,"t":"他们吃饱了，为要使船轻一点，就把船上的麦子抛到海里。","notes":[]},{"n":39,"t":"天亮的时候，他们不认得那地方，只见一个有岸可登的海湾，就想法子看能不能把船靠岸。","notes":[],"heads":["船搁了浅"]},{"n":40,"t":"于是他们砍断缆索，把锚丢到海里，同时也松开舵绳，拉起头篷，顺风向着岸行去。","notes":[]},{"n":41,"t":"但碰到两水夹流的地方，就搁了浅，船头胶住不动，船尾被浪的猛力冲坏了。","notes":["“船尾…冲坏了”：有古卷是“船尾被猛力冲坏了”；另有古卷是“船尾被浪冲坏了”。"]},{"n":42,"t":"士兵的意思要把囚犯都杀了，免得有游水脱逃的。","notes":[]},{"n":43,"t":"但百夫长要救保罗，不准他们任意而行，就吩咐会游水的，跳下水去，先上岸；","notes":[]},{"n":44,"t":"其余的人则用板子或船的碎片上岸。这样，众人都获救，上了岸。","notes":[]}]},"28":{"heading":"保罗在马耳他岛上","verses":[{"n":1,"t":"我们既已获救，才知道那岛名叫马耳他。","notes":[]},{"n":2,"t":"当地人非常友善地接待我们；因为正在下雨，天气又冷，他们就生了火欢迎我们众人。","notes":[]},{"n":3,"t":"那时，保罗拾起一捆柴，放在火中，有一条毒蛇，因为热的缘故钻了出来，缠住他的手。","notes":[]},{"n":4,"t":"当地的人看见那毒蛇悬在他手上，就彼此说：“这人必是个凶手，虽然他从海里获救，天理仍不容他活着。”","notes":[]},{"n":5,"t":"保罗竟把那毒蛇甩在火里，并没有受伤。","notes":[]},{"n":6,"t":"当地的人想他快要肿起来，或是忽然倒下死了，但等了好久，见他没有什么异样，就转念说他是个神明。","notes":[]},{"n":7,"t":"离那地方不远有一些田产，是岛长部百流的。他接纳我们，尽情款待了我们三日。","notes":[]},{"n":8,"t":"当时，部百流的父亲卧病不起，患了热病和痢疾。保罗进去见他，为他祷告按手，治好了他。","notes":[]},{"n":9,"t":"从此，岛上其余的病人也都来，得了医治。","notes":[]},{"n":10,"t":"他们又多方面尊敬我们，到了开船的时候，又把我们所需用的东西送到船上。","notes":[]},{"n":11,"t":"过了三个月，我们上了亚历山大的船起航。这船以“宙斯双子”为记，是在那海岛过冬的。","notes":[],"heads":["保罗抵达罗马"]},{"n":12,"t":"我们到了叙拉古，停泊了三日；","notes":[]},{"n":13,"t":"又从那里起锚开船，来到利基翁。过了一天，起了南风，第二天就来到部丢利。","notes":["有古卷是“从那里绕道航行”。"]},{"n":14,"t":"我们在那里遇见一些弟兄，他们请我们同住了七天。就这样，我们来到罗马。","notes":[]},{"n":15,"t":"那里的弟兄们一听见我们的消息，就到亚比乌市和三馆来迎接我们。保罗见了他们，就感谢神，越发壮胆。","notes":[]},{"n":16,"t":"我们进了罗马城，保罗蒙准和那个看守他的兵另住在一处。","notes":["有古卷加“百夫长把众囚犯交给御营的统领，惟有”。"]},{"n":17,"t":"过了三天，保罗请当地犹太人的领袖来。他们来了，保罗对他们说：“诸位弟兄，虽然我没有做什么事干犯本国的百姓和我们祖宗的规矩，却在耶路撒冷被囚禁，交在罗马人的手里。","notes":[],"heads":["保罗在罗马传道"]},{"n":18,"t":"他们审问了我，有意要释放我，因为在我身上并没有该死的罪状。","notes":[]},{"n":19,"t":"但犹太人反对，我不得已只好上诉于凯撒，并不是有什么事要控告我本国的百姓。","notes":[]},{"n":20,"t":"为这缘故，我请你们来见我当面谈话，我原是为以色列人所指望的那位才被这铁链捆绑的。”","notes":[]},{"n":21,"t":"他们对他说：“我们并没有接到从犹太寄来有关于你的信，也没有弟兄到这里来向我们报告，或说你有什么不好的地方。","notes":[]},{"n":22,"t":"但我们愿意听听你的意见，因为我们知道这教门是到处遭人反对的。”","notes":[]},{"n":23,"t":"他们和保罗约定了日子，就有许多人到他的住处来。保罗从早到晚向他们讲解这事，为神的国作证，并引摩西的律法和先知的书劝导他们信从耶稣。","notes":[]},{"n":24,"t":"他所说的话，有的信，有的不信。","notes":[]},{"n":25,"t":"他们间彼此不合，就分散了；未散以先，保罗说了一句话：“圣灵藉以赛亚先知向你们祖宗所说的话是对的。","notes":[]},{"n":26,"t":"他说：‘你去对这百姓说：你们听了又听，却不明白；看了又看，却看不清。","notes":[]},{"n":27,"t":"因为这百姓的心麻木，耳朵塞着，眼睛闭着，免得眼睛看见，耳朵听见，心里明白，回转过来，我会医治他们。’","notes":[]},{"n":28,"t":"所以，你们当知道，神这救恩已经传给外邦人；他们会听的。”","notes":["有古卷在此加“29 保罗说了这些话，犹太人议论纷纷地走了。”"]},{"n":30,"t":"保罗在自己所租的房子里住了足足两年。凡来见他的人，他都接待，","notes":[]},{"n":31,"t":"放胆传讲神的国，并教导主耶稣基督的事，没有人禁止。","notes":[]}]}},"ROM":{"1":{"heading":"问候与祝愿","verses":[{"n":1,"t":"基督耶稣的仆人保罗，蒙召为使徒，奉派传神的福音。","notes":[]},{"n":2,"t":"这福音是神从前藉众先知，在圣经上所应许的。","notes":[]},{"n":3,"t":"论到他儿子－我主耶稣基督，按肉体说，是从大卫后裔生的；按神圣的灵说，因从死人中复活，用大能显明他是神的儿子。","notes":[],"end":4},{"n":5,"t":"我们从他蒙恩受了使徒的职分，为他的名在万国中使人因信而顺服，","notes":[]},{"n":6,"t":"其中也有你们这蒙召属耶稣基督的人。","notes":[]},{"n":7,"t":"我写信给你们在罗马、为神所爱、蒙召作圣徒的众人。愿恩惠、平安从我们的父神和主耶稣基督归给你们！","notes":["“平安”或译“和平”。"]},{"n":8,"t":"首先，我靠着耶稣基督，为你们众人感谢我的神，因你们的信德传遍了天下。","notes":[],"heads":["保罗有意访问罗马"]},{"n":9,"t":"我在他儿子的福音上，用心灵所事奉的神可以见证，我怎样不住地提到你们，","notes":[]},{"n":10,"t":"在我的祷告中常常恳求，或许照神的旨意，最终我能毫无阻碍地往你们那里去。","notes":[]},{"n":11,"t":"因为我迫切地想见你们，要把一些属灵的恩赐分给你们，使你们得以坚固，","notes":[]},{"n":12,"t":"也可以说，我在你们中间，因你我彼此的信心而同得安慰。","notes":[]},{"n":13,"t":"弟兄们，我不愿意你们不知道，我屡次计划往你们那里去，要在你们中间得些果子，如同在其余的外邦人中一样，只是到如今仍有拦阻。","notes":[]},{"n":14,"t":"无论是希腊人、未开化的人、聪明人、愚拙人，我都欠他们的债，","notes":[]},{"n":15,"t":"所以愿意尽我的力量把福音也传给你们在罗马的人。","notes":[]},{"n":16,"t":"我不以福音为耻；这福音本是神的大能，要救一切相信的，先是犹太人，后是希腊人。","notes":[],"heads":["福音是神的大能"]},{"n":17,"t":"因为神的义正在这福音上显明出来；这义是本于信，以至于信。如经上所记：“义人必因信得生。”","notes":[]},{"n":18,"t":"原来，神的愤怒从天上显明在一切不虔不义的人身上，就是那些行不义压制真理的人。","notes":[],"heads":["人类的罪恶"]},{"n":19,"t":"神的事情，人所能知道的，原显明在人心里，因为神已经向他们显明。","notes":[]},{"n":20,"t":"自从造天地以来，神的永能和神性是明明可知的，虽然眼不能见，但藉着所造之物就可以了解看见，叫人无可推诿。","notes":[]},{"n":21,"t":"因为，他们虽然知道神，却不把他当作神荣耀他，也不感谢他。他们的思想变为虚妄，无知的心昏暗了。","notes":[]},{"n":22,"t":"他们自以为聪明，反成了愚昧，","notes":[]},{"n":23,"t":"将不能朽坏之神的荣耀变为偶像，仿照必朽坏的人、飞禽、走兽、爬虫的形像。","notes":[]},{"n":24,"t":"所以，神任凭他们随着心里的情欲行污秽的事，以致彼此羞辱自己的身体。","notes":[]},{"n":25,"t":"他们将神的真实变为虚谎，去敬拜事奉受造之物，不敬奉那造物的主—主是可称颂的，直到永远。阿们！","notes":[]},{"n":26,"t":"因此，神任凭他们放纵可羞耻的情欲。他们的女人把自然的关系变成违反自然的；","notes":[]},{"n":27,"t":"男人也是如此，放弃了和女人自然的关系，欲火攻心，男的和男的彼此贪恋，行可耻的事，就在自己身上受这逆性行为当得的报应。","notes":[]},{"n":28,"t":"他们既然故意不认识神，神就任凭他们存扭曲的心，做那些不该做的事，","notes":[]},{"n":29,"t":"装满了各样不义、邪恶、贪婪、恶毒，满心是嫉妒、凶杀、纷争、诡诈、毒恨，又是毁谤的、","notes":["有古卷加“淫乱”。"]},{"n":30,"t":"说人坏话的、怨恨神的、侮辱人的、狂傲的、自夸的、制造是非的、忤逆父母的、","notes":["“怨恨神的”或译“被神所憎恶的”。"]},{"n":31,"t":"顽梗不化的、言而无信的、无情无义的、不怜悯人的。","notes":[]},{"n":32,"t":"他们虽知道神判定做这样事的人是该死的，然而他们不但自己去做，还赞同别人去做。","notes":[]}]},"2":{"heading":"神的公义审判","verses":[{"n":1,"t":"所以，你这评断人的人哪，无论你是谁，都无可推诿。你在什么事上评断人，就在什么事上定自己的罪。因你这评断人的，自己所做的却和别人一样。","notes":[]},{"n":2,"t":"我们知道这样做的人，神必公平地审判他。","notes":[]},{"n":3,"t":"你这个人哪，你评断做这样事的人，自己所做的却和别人一样，你以为能逃脱神的审判吗？","notes":[]},{"n":4,"t":"还是你藐视他丰富的恩慈、宽容、忍耐，不知道他的恩慈是领你悔改吗？","notes":[]},{"n":5,"t":"你竟放任你刚硬不悔改的心，为自己累积愤怒！在愤怒的日子，神公义的审判要显示出来。","notes":[]},{"n":6,"t":"他要照各人的行为报应各人。","notes":[]},{"n":7,"t":"凡恒心行善，寻求荣耀、尊贵和不能朽坏的，就有永生报偿他们；","notes":[]},{"n":8,"t":"但是那些自私自利、不顺从真理、反顺从不义的人，就有恼恨、愤怒报应他们。","notes":[]},{"n":9,"t":"他要把患难、困苦加给一切作恶的人，先是犹太人，后是希腊人；","notes":[]},{"n":10,"t":"却把荣耀、尊贵、平安加给一切行善的人，先是犹太人，后是希腊人。","notes":[]},{"n":11,"t":"因为神不偏待人。","notes":[]},{"n":12,"t":"凡在律法之外犯了罪的，将在律法之外灭亡；凡在律法之内犯了罪的，将按律法受审判。","notes":[]},{"n":13,"t":"原来在神面前，不是听律法的为义，而是行律法的称义。","notes":[]},{"n":14,"t":"没有律法的外邦人若顺着本性行律法上的事，他们虽然没有律法，自己就是自己的律法。","notes":[]},{"n":15,"t":"他们显明律法的功用刻在他们心里，他们的良心一同作证—他们的内心挣扎，有时自责，有时为自己辩护。","notes":[]},{"n":16,"t":"在那日，神要藉着基督耶稣，按照我所传的福音，审判人隐藏的事。","notes":["“基督耶稣”：有古卷是“耶稣基督”。"]},{"n":17,"t":"但是你，你既自称为犹太人，倚靠律法，以神夸口，","notes":[],"heads":["犹太人与律法"]},{"n":18,"t":"知道神的旨意，从律法受了教导而能分辨是非；","notes":[]},{"n":19,"t":"你既深信自己是给盲人领路的，是在黑暗中人的光，","notes":[]},{"n":20,"t":"是无知的人的师傅，是小孩子的老师，体现了律法中的知识和真理；","notes":[]},{"n":21,"t":"那么，你这教导别人的，还不教导自己吗？你这宣讲不可偷窃的，自己还偷窃吗？","notes":[]},{"n":22,"t":"你这说不可奸淫的，自己还奸淫吗？你这厌恶偶像的，自己还抢劫庙中之物吗？","notes":[]},{"n":23,"t":"你这以律法夸口的，自己倒违犯律法，羞辱神！","notes":[]},{"n":24,"t":"神的名在外邦人中因你们受了亵渎，正如经上所记的。","notes":[]},{"n":25,"t":"你若遵行律法，割礼固然于你有益；若违犯律法，你的割礼就算不得割礼。","notes":[]},{"n":26,"t":"所以，那未受割礼的，若遵守律法的要求，他虽然未受割礼，岂不算是受了割礼吗？","notes":[]},{"n":27,"t":"而且那本来未受割礼的，若能全守律法，岂不是要审判你这有仪文和割礼，竟违犯律法的人吗？","notes":[]},{"n":28,"t":"因为外表是犹太人的不是真犹太人；外表肉身的割礼也不是真割礼。","notes":[]},{"n":29,"t":"惟有内心作犹太人的才是真犹太人，真割礼也是心里的，在乎圣灵，不在乎仪文。这样的人所受的称赞不是从人来的，而是从神来的。","notes":["“圣灵”或译“灵”。"]}]},"3":{"heading":"没有义人","verses":[{"n":1,"t":"这样说来，犹太人有什么比别人强呢？割礼有什么益处呢？","notes":[]},{"n":2,"t":"很多，各方面都有。首先，神的圣言交托他们。","notes":[]},{"n":3,"t":"即使有不信的，这又何妨呢？难道他们的不信就废掉神的信实吗？","notes":[]},{"n":4,"t":"绝对不会！不如说，神是真实的，而人都是虚谎的。如经上所记：“以致你责备的时候显为公义；你被指控的时候一定胜诉。”","notes":[]},{"n":5,"t":"我姑且照着人的看法来说，我们的不义若显出神的义来，我们要怎么说呢？神降怒是他不义吗？","notes":[]},{"n":6,"t":"绝对不是！若是这样，神怎能审判世界呢？","notes":[]},{"n":7,"t":"若神的真实因我的虚谎越发显出他的荣耀，为什么我还像罪人一样受审判呢？","notes":[]},{"n":8,"t":"为什么不说，我们可以作恶以成善呢？有人毁谤我们，说我们讲过这话；这等人被定罪是应该的。","notes":[]},{"n":9,"t":"那又怎么样呢？我们比他们强吗？绝不是！因我们已经指证：犹太人和希腊人都在罪恶之下。","notes":[]},{"n":10,"t":"就如经上所记：“没有义人，连一个也没有。","notes":[]},{"n":11,"t":"没有明白的，没有寻求神的。","notes":[]},{"n":12,"t":"人人偏离正路，一同走向败坏。没有行善的，连一个也没有。","notes":["“没有行善…没有”：有古卷是“连一个行善的也没有”。"]},{"n":13,"t":"他们的喉咙是敞开的坟墓；他们的舌头玩弄诡诈。他们的嘴唇里有毒蛇的毒液，","notes":[]},{"n":14,"t":"满口是咒骂苦毒。","notes":[]},{"n":15,"t":"他们的脚为杀人流血飞跑；","notes":[]},{"n":16,"t":"他们的路留下毁坏和灾难。","notes":[]},{"n":17,"t":"和平的路，他们不认识；","notes":[]},{"n":18,"t":"他们眼中不怕神。”","notes":[]},{"n":19,"t":"我们知道律法所说的话都是对律法之下的人说的，好塞住各人的口，使普世的人都伏在神的审判之下。","notes":[]},{"n":20,"t":"所以，凡血肉之躯没有一个能因律法的行为而在神面前称义，因为律法本是要人认识罪。","notes":[]},{"n":21,"t":"但如今，神的义在律法之外已经显明出来，有律法和先知为证：","notes":[],"heads":["因信称义"]},{"n":22,"t":"就是神的义，因信耶稣基督加给一切信的人。这并没有分别，","notes":["“因信耶稣基督”或译“藉耶稣基督的信”。"]},{"n":23,"t":"因为世人都犯了罪，亏缺了神的荣耀，","notes":[]},{"n":24,"t":"如今却蒙神的恩典，藉着在基督耶稣里的救赎，就白白地得称为义。","notes":[]},{"n":25,"t":"神设立耶稣作赎罪祭，是凭耶稣的血，藉着信，要显明神的义；因为他用忍耐的心宽容人先前所犯的罪，好使今时显明他的义，让人知道他自己为义，也称信耶稣的人为义。","notes":["“也称…为义”或译“也称本着耶稣之信的人为义”。"],"end":26},{"n":27,"t":"既是这样，哪里可夸口呢？没有可夸的。是藉什么法呢？功德吗？不是！是藉信主之法。","notes":[]},{"n":28,"t":"所以我们认定，人称义是因着信，不在于律法的行为。","notes":[]},{"n":29,"t":"难道神只是犹太人的吗？不也是外邦人的吗？是的，他也是外邦人的神。","notes":[]},{"n":30,"t":"既然神是一位，他就要本于信称那受割礼的为义，也要藉着信称那未受割礼的为义。","notes":[]},{"n":31,"t":"这样，我们藉着信废了律法吗？绝对不是！更是巩固律法。","notes":[]}]},"4":{"heading":"亚伯拉罕的榜样","verses":[{"n":1,"t":"这样，那按肉体作我们祖宗的亚伯拉罕，我们要怎么说呢？","notes":[]},{"n":2,"t":"倘若亚伯拉罕是因行为称义，他就有可夸的，但是在神面前他一无可夸。","notes":[]},{"n":3,"t":"经上说什么呢？“亚伯拉罕信了神，这就算他为义。”","notes":[]},{"n":4,"t":"做工的得工资不算是恩典，而是应得的；","notes":[]},{"n":5,"t":"但那不做工的，只信那位称不敬虔之人为义的，他的信就算为义。","notes":[]},{"n":6,"t":"正如大卫称那在行为之外蒙神算为义的人是有福的：","notes":[]},{"n":7,"t":"“过犯得赦免，罪恶蒙遮盖的人有福了！","notes":[]},{"n":8,"t":"主不算为有罪的，这样的人有福了！”","notes":[]},{"n":9,"t":"如此看来，这福只加给那受割礼的人吗？不也加给那未受割礼的人吗？我们说，因着信，就算亚伯拉罕为义。","notes":[]},{"n":10,"t":"那么，这是怎么算的呢？是在他受割礼的时候呢？还是在他未受割礼的时候呢？不是在受割礼的时候，而是在未受割礼的时候。","notes":[]},{"n":11,"t":"并且，他受了割礼的记号，作他未受割礼的时候因信称义的印证，为使他作一切未受割礼而信之人的父，使他们也算为义，","notes":[]},{"n":12,"t":"也使他作受割礼之人的父，就是那些不但受割礼，而且跟随我们的祖宗亚伯拉罕未受割礼而信的足迹的人。","notes":[]},{"n":13,"t":"因为神给亚伯拉罕和他后裔承受世界的应许不是藉着律法，而是藉着信而得的义。","notes":[],"heads":["应许因信而实现"]},{"n":14,"t":"若是属于律法的人才是后嗣，信就落空了，应许也就失效了。","notes":[]},{"n":15,"t":"因为律法是惹动愤怒的，哪里没有律法，哪里就没有过犯。","notes":[]},{"n":16,"t":"所以，人作后嗣是出于信，因此就属乎恩，以致应许保证归给所有的后裔，不但归给那属于律法的，也归给那效法亚伯拉罕之信的人。亚伯拉罕所信的是那叫死人复活、使无变为有的神，在这位神面前亚伯拉罕成为我们众人的父，如经上所记：“我已经立你作多国之父。”","notes":[],"end":17},{"n":18,"t":"他在没有盼望的时候，仍存着盼望来相信，就得以作多国之父，正如先前所说：“你的后裔将要如此。”","notes":[]},{"n":19,"t":"他将近百岁的时候，虽然想到自己的身体如同已死，撒拉也不可能生育，他的信心还是不软弱，","notes":["“虽然想到”：有古卷是“不顾念”。"]},{"n":20,"t":"仍仰望神的应许，总没有因不信而起疑惑，反倒因信而刚强，将荣耀归给神，","notes":[]},{"n":21,"t":"且满心相信神所应许的必能成就。","notes":[]},{"n":22,"t":"所以这也就算他为义。","notes":["有古卷没有“也”。"]},{"n":23,"t":"“算他为义”这句话不是单为他写的，","notes":[]},{"n":24,"t":"也是为我们将来得算为义的人写的，就是为我们这些信神使我们的主耶稣从死人中复活的人写的。","notes":[]},{"n":25,"t":"耶稣被出卖，是为我们的过犯；他复活，是为使我们称义。","notes":[]}]},"5":{"heading":"因信称义的福","verses":[{"n":1,"t":"所以，我们既因信称义，就藉着我们的主耶稣基督得以与神和好。","notes":[]},{"n":2,"t":"我们又藉着他，因信得以进入现在所站立的这恩典中，并且欢欢喜喜盼望神的荣耀。","notes":["有古卷没有“因信”。"]},{"n":3,"t":"不但如此，就是在患难中也是欢欢喜喜的，因为知道患难生忍耐，","notes":[]},{"n":4,"t":"忍耐生老练，老练生盼望，","notes":[]},{"n":5,"t":"盼望不至于落空，因为神的爱，已藉着所赐给我们的圣灵，浇灌在我们心里。","notes":[]},{"n":6,"t":"我们还软弱的时候，基督就在特定的时刻为不敬虔之人死。","notes":[]},{"n":7,"t":"为义人死，是少有的；为仁人死，或者有敢做的。","notes":[]},{"n":8,"t":"惟有基督在我们还作罪人的时候为我们死，神的爱就在此向我们显明了。","notes":[]},{"n":9,"t":"现在我们既靠着他的血称义，就更要藉着他得救，免受神的愤怒。","notes":[]},{"n":10,"t":"因为我们作仇敌的时候，尚且藉着神儿子的死得以与神和好，既已和好，就更要因他的生得救了。","notes":[]},{"n":11,"t":"不但如此，我们既藉着我们的主耶稣基督得以与神和好，也就藉着他以神为乐。","notes":[]},{"n":12,"t":"为此，正如罪是从一人进入世界，死又从罪而来，于是死就临到所有的人，因为人人都犯了罪。","notes":[],"heads":["亚当和基督"]},{"n":13,"t":"没有律法之前，罪已经在世上，但没有律法，罪也不算罪。","notes":[]},{"n":14,"t":"然而，从亚当到摩西，死就掌了权，连那些不与亚当犯一样罪过的，也在死的权下。亚当是那以后要来之人的预像。","notes":[]},{"n":15,"t":"但是过犯不如恩赐，若因一人的过犯，众人都死了，那么，神的恩典，与那因耶稣基督一人而来的恩典中的赏赐，岂不加倍地临到众人吗？","notes":[]},{"n":16,"t":"因一人犯罪而来的后果，也不如赏赐，原来审判是由一人而定罪，恩赐乃是由许多过犯而称义。","notes":[]},{"n":17,"t":"若因一人的过犯，死就因这一人掌权，那些受洪恩又蒙所赐之义的，岂不更要因耶稣基督一人在他们生命中掌权吗？","notes":[]},{"n":18,"t":"这样看来，因一次的过犯，所有的人都被定罪；照样，因一次的义行，所有的人也就被称义而得生命了。","notes":[]},{"n":19,"t":"因一人的悖逆，众人成为罪人；照样，因一人的顺从，众人也成为义了。","notes":[]},{"n":20,"t":"而且加添了律法，使得过犯增加，只是罪在哪里增加，恩典就在哪里越发丰盛了。","notes":[]},{"n":21,"t":"所以，正如罪藉着死掌权；照样，恩典也藉着义掌权，使人因我们的主耶稣基督得永生。","notes":[]}]},"6":{"heading":"对罪死，在基督里活","verses":[{"n":1,"t":"这样，我们要怎么说呢？我们可以仍在罪中使恩典增多吗？","notes":[]},{"n":2,"t":"绝对不可！我们向罪死了的人，岂可仍在罪中活着呢？","notes":[]},{"n":3,"t":"难道你们不知道，我们这受洗归入基督耶稣的人，就是受洗归入他的死吗？","notes":[]},{"n":4,"t":"所以，我们藉着洗礼归入死，和他一同埋葬，是要我们行事为人都有新生的样子，像基督藉着父的荣耀从死人中复活一样。","notes":[]},{"n":5,"t":"我们若与他合一，经历与他一样的死，也将经历与他一样的复活。","notes":[]},{"n":6,"t":"我们知道，我们的旧人和他同钉十字架，使罪身灭绝，叫我们不再作罪的奴隶，","notes":[]},{"n":7,"t":"因为已死的人是脱离了罪。","notes":[]},{"n":8,"t":"我们若与基督同死，我们信也必与他同活，","notes":[]},{"n":9,"t":"因为知道基督既从死人中复活，就不再死，死也不再作他的主了。","notes":[]},{"n":10,"t":"他死了，是对罪死，只这一次；他活，是对神活着。","notes":[]},{"n":11,"t":"这样，你们也要看自己对罪是死的，在基督耶稣里对神却是活的。","notes":[]},{"n":12,"t":"所以，不要让罪在你们必死的身上掌权，使你们顺从身体的私欲。","notes":[]},{"n":13,"t":"也不要把你们的肢体献给罪作不义的工具，倒要像从死人中活着的人，把自己献给神，并把你们的肢体献给神作义的工具。","notes":[]},{"n":14,"t":"罪必不能作你们的主，因你们不在律法之下，而是在恩典之下。","notes":[]},{"n":15,"t":"那又怎么样呢？我们在恩典之下，不在律法之下，就可以犯罪吗？绝对不可！","notes":[],"heads":["义的奴仆"]},{"n":16,"t":"难道你们不知道，你们献自己作奴仆，顺从谁就作谁的奴仆吗？或作罪的奴隶，以至于死；或作顺服的奴仆，以至于成义。","notes":[]},{"n":17,"t":"感谢神！因为你们从前虽然作罪的奴隶，现在却从心里顺服了所传给你们教导的典范。","notes":[]},{"n":18,"t":"你们既从罪里得了释放，就作了义的奴仆。","notes":[]},{"n":19,"t":"我因你们肉体的软弱，就以人的观点来说。你们从前怎样把肢体献给不洁不法作奴隶，以至于不法；现在也要照样将肢体献给义作奴仆，以至于成圣。","notes":[]},{"n":20,"t":"因为你们作罪的奴隶时，不被义所约束。","notes":[]},{"n":21,"t":"那么，你们现在所看为羞耻的事，当时有什么果子呢？那些事的结局就是死。","notes":[]},{"n":22,"t":"但如今，你们既从罪里得了释放，作了神的奴仆，就结出果子，以至于成圣，那结局就是永生。","notes":[]},{"n":23,"t":"因为罪的工价乃是死；惟有神的恩赐，在我们的主基督耶稣里，乃是永生。","notes":[]}]},"7":{"heading":"律法的约束力","verses":[{"n":1,"t":"弟兄们，我对你们这些明白律法的人说，你们岂不知道律法约束人是在他活着的时候吗？","notes":[]},{"n":2,"t":"就如女人有了丈夫，丈夫还活着，她就被律法约束；丈夫若死了，她就从丈夫的律法中解脱了。","notes":[]},{"n":3,"t":"所以丈夫还活着，她若跟了别的男人，就叫淫妇；丈夫若死了，她就脱离了律法，虽然跟了别的男人，也不是淫妇。","notes":[]},{"n":4,"t":"我的弟兄们，这样说来，你们藉着基督的身体对律法也是死了，使你们归于另一位，就是归于那从死人中复活的，为要使我们结果子给神。","notes":[]},{"n":5,"t":"因为我们属肉体的时候，那因律法而生犯罪的欲望在我们肢体中发动，以致结出死亡的果子。","notes":[]},{"n":6,"t":"但如今，我们既然在捆绑我们的律法上死了，就从律法中解脱，使我们服侍主，要按着圣灵的新样，不按着仪文的旧样。","notes":["“圣灵”或译“灵”。"]},{"n":7,"t":"这样，我们要怎么说呢？律法是罪吗？绝对不是！但是，若不是藉着律法，我就不知何为罪；若不是律法说“不可贪心”，我就不知何为贪心。","notes":[],"heads":["律法与罪的关系"]},{"n":8,"t":"然而，罪趁着机会，藉着诫命，使各样的贪心在我里头发动，因为没有律法，罪是死的。","notes":[]},{"n":9,"t":"以前没有律法的时候，我是活的；但是诫命来到，罪活起来，","notes":[]},{"n":10,"t":"我就死了。那本该叫人活的诫命反而叫我死。","notes":[]},{"n":11,"t":"因为罪趁着机会，藉着诫命诱惑我，并且藉着诫命杀了我。","notes":[]},{"n":12,"t":"这样看来，律法是圣的，诫命也是圣的、义的、善的。","notes":[]},{"n":13,"t":"那么，那善的是叫我死吗？绝对不是！叫我死的是罪。罪藉着那善的叫我死，为要显出这真是罪，以致罪藉着诫命更显出是恶极了。","notes":[]},{"n":14,"t":"我们原知道律法是属灵的，我却是属肉体的，是已经卖给罪了。","notes":[],"heads":["灵与肉的交战"]},{"n":15,"t":"因为我所做的，我自己不明白。我所愿意的，我并不做；我所恨恶的，我反而去做。","notes":[]},{"n":16,"t":"如果我所做的是我所不愿意的，我得承认律法是善的。","notes":[]},{"n":17,"t":"事实上，这不是我做的，而是住在我里面的罪做的。","notes":[]},{"n":18,"t":"我也知道，住在我里面的，就是我肉体之中，没有善。因为立志为善由得我，只是行出来由不得我。","notes":[]},{"n":19,"t":"我所愿意的善，我不去做；我所不愿意的恶，我反而去做。","notes":[]},{"n":20,"t":"如果我去做我不愿意做的，就不是我做的，而是住在我里面的罪做的。","notes":[]},{"n":21,"t":"我觉得有个律，就是我愿意行善的时候，就有恶缠着我。","notes":[]},{"n":22,"t":"因为，按着我里面的人，我喜欢神的律，","notes":[]},{"n":23,"t":"但我看出肢体中另有个律和我内心的律交战，把我掳去，使我附从那肢体中罪的律。","notes":[]},{"n":24,"t":"我真苦啊！谁能救我脱离这必死的身体呢？","notes":[]},{"n":25,"t":"感谢神，靠着我们的主耶稣基督就能！这样看来，一方面，我内心顺服神的律，另一方面，肉体却顺服罪的律了。","notes":[]}]},"8":{"heading":"在圣灵里的生活","verses":[{"n":1,"t":"如今，那些在基督耶稣里的人就不被定罪了。","notes":[]},{"n":2,"t":"因为赐生命的圣灵的律，在基督耶稣里从罪和死的律中把你释放出来。","notes":[]},{"n":3,"t":"律法既因肉体软弱而无能为力，神就差遣自己的儿子成为罪身的样子，为了对付罪，在肉体中定了罪，","notes":["“为了对付罪”或译“作了赎罪祭”。"]},{"n":4,"t":"为要使律法要求的义，实现在我们这不随从肉体、只随从圣灵去行的人身上。","notes":[]},{"n":5,"t":"因为，随从肉体的人体贴肉体的事；随从圣灵的人体贴圣灵的事。","notes":[]},{"n":6,"t":"体贴肉体就是死；体贴圣灵就是生命和平安。","notes":["“平安”或译“和平”。"]},{"n":7,"t":"因为体贴肉体就是与神为敌，对神的律法不顺服，事实上也无法顺服。","notes":[]},{"n":8,"t":"属肉体的人无法使神喜悦。","notes":[]},{"n":9,"t":"如果神的灵住在你们里面，你们就不属肉体，而是属圣灵了。人若没有基督的灵，就不是属基督的。","notes":[]},{"n":10,"t":"基督若在你们里面，身体就因罪而死，灵却因义而活。","notes":[]},{"n":11,"t":"然而，使耶稣从死人中复活的神的灵若住在你们里面，那使基督从死人中复活的，也必藉着住在你们里面的圣灵使你们必死的身体又活过来。","notes":[]},{"n":12,"t":"弟兄们，这样看来，我们不是欠肉体的债去顺从肉体而活。","notes":[]},{"n":13,"t":"你们若顺从肉体活着，必定会死；若靠着圣灵把身体的恶行处死，就必存活。","notes":[]},{"n":14,"t":"因为凡被神的灵引导的都是神的儿子。","notes":[]},{"n":15,"t":"你们所领受的不是奴仆的灵，仍旧害怕；所领受的是儿子名分的灵，因此我们呼叫：“阿爸，父！”","notes":[]},{"n":16,"t":"圣灵自己与我们的灵一同见证我们是神的儿女。","notes":[]},{"n":17,"t":"若是儿女，就是后嗣，是神的后嗣，和基督同作后嗣。如果我们和他一同受苦，是要我们和他一同得荣耀。","notes":[]},{"n":18,"t":"我认为，现在的苦楚，若比起将来要显示给我们的荣耀，是不足介意的。","notes":[],"heads":["将来的荣耀"]},{"n":19,"t":"受造之物切望等候神的众子显出来。","notes":[]},{"n":20,"t":"因为受造之物屈服在虚空之下，不是自己愿意，而是因那使它屈服的叫他如此。但受造之物仍然指望从败坏的辖制下得释放，得享神儿女荣耀的自由。","notes":[],"end":21},{"n":22,"t":"我们知道，一切受造之物一同呻吟，一同忍受阵痛，直到如今。","notes":[]},{"n":23,"t":"不但如此，就是我们这有圣灵作初熟果子的，也是自己内心呻吟，等候得着儿子的名分，就是我们的身体得救赎。","notes":[]},{"n":24,"t":"我们得救是在于盼望；可是看得见的盼望就不是盼望。谁还去盼望他所看得见的呢？","notes":[]},{"n":25,"t":"但我们若盼望那看不见的，我们就耐心等候。","notes":[]},{"n":26,"t":"同样，我们的软弱有圣灵帮助。我们本不知道当怎样祷告，但是圣灵亲自用无可言喻的叹息替我们祈求。","notes":[]},{"n":27,"t":"那鉴察人心的知道圣灵所体贴的，因为圣灵照着神的旨意替圣徒祈求。","notes":[]},{"n":28,"t":"我们知道，万事都互相效力，叫爱神的人得益处，就是按他旨意被召的人。","notes":["“万事”：有古卷是“神使万事”。"]},{"n":29,"t":"因为他所预知的人，他也预定他们效法他儿子的榜样，使他儿子在许多弟兄中作长子。","notes":["“作长子”或译“为首生者”。"]},{"n":30,"t":"他所预定的人，他又召他们来；所召来的人，他又称他们为义；所称为义的人，他又叫他们得荣耀。","notes":[]},{"n":31,"t":"既是这样，我们对这些事还要怎么说呢？神若帮助我们，谁能抵挡我们呢？","notes":[],"heads":["不能隔绝的爱"]},{"n":32,"t":"神既不顾惜自己的儿子，为我们众人舍了他，岂不也把万物和他一同白白地赐给我们吗？","notes":[]},{"n":33,"t":"谁能控告神所拣选的人呢？有神称他们为义了。","notes":[]},{"n":34,"t":"谁能定他们的罪呢？有基督耶稣 已经死了，而且复活了，现今在神的右边，也替我们祈求。","notes":["有古卷没有“耶稣”。"]},{"n":35,"t":"谁能使我们与基督的爱隔绝呢？难道是患难吗？是困苦吗？是迫害吗？是饥饿吗？是赤身露体吗？是危险吗？是刀剑吗？","notes":[]},{"n":36,"t":"如经上所记：“我们为你的缘故终日被杀；人看我们如将宰的羊。”","notes":[]},{"n":37,"t":"然而，靠着爱我们的主，在这一切的事上，我们已经得胜有余了。","notes":[]},{"n":38,"t":"因为我深信，无论是死，是活，是天使，是掌权的，是有权能的 ，是现在的事，是将来的事，","notes":["“是掌权的，是有权能的”：指灵界的势力。"]},{"n":39,"t":"是高处的，是深处的，是别的受造之物，都不能使我们与神的爱隔绝，这爱是在我们的主基督耶稣里的。","notes":[]}]},"9":{"heading":"神拣选以色列人","verses":[{"n":1,"t":"我在基督里说真话，不说谎话；我的良心被圣灵感动为我作证。","notes":[]},{"n":2,"t":"我非常忧愁，心里时常伤痛。","notes":[]},{"n":3,"t":"为我弟兄，我骨肉之亲，就是自己被诅咒，与基督分离，我也愿意。","notes":[]},{"n":4,"t":"他们是以色列人，那儿子的名分、荣耀、诸约、律法的颁布、敬拜的礼仪、应许都是给他们的。","notes":[]},{"n":5,"t":"列祖是他们的，基督按肉体说也是从他们出来的。愿在万有之上的神被称颂，直到永远。阿们！","notes":["“基督按肉体…直到永远”：原文或译“基督按肉体说也是从他们出来的，他是在万有之上，永远可称颂的神”。"]},{"n":6,"t":"这不是说神的话落了空。因为从以色列生的不都是以色列人，","notes":[]},{"n":7,"t":"也不因为是亚伯拉罕的后裔就都是他的儿女；惟独“从以撒生的才要称为你的后裔。”","notes":[]},{"n":8,"t":"这就是说，肉身所生的儿女不是神的儿女，惟独那应许的儿女才算是后裔。","notes":[]},{"n":9,"t":"因为所应许的话是这样：“到明年这时候我要来，撒拉必会生一个儿子。”","notes":[]},{"n":10,"t":"不但如此，利百加也是这样。她从一个人，就是从我们的祖宗以撒怀了孕。","notes":[]},{"n":11,"t":"双胞胎还没有生下来，善恶还没有行出来，为要贯彻神拣选人的旨意，","notes":[]},{"n":12,"t":"不是凭着人的行为，而是凭着那呼召人的，神就对利百加说：“将来，大的要服侍小的。”","notes":[]},{"n":13,"t":"正如经上所记：“雅各是我所爱的；以扫是我所恶的。”","notes":[]},{"n":14,"t":"这样，我们要怎么说呢？难道神有什么不义吗？绝对没有！","notes":[]},{"n":15,"t":"因他对摩西说：“我要怜悯谁就怜悯谁，要恩待谁就恩待谁。”","notes":[]},{"n":16,"t":"由此看来，这不靠人的意愿，也不靠人的努力，只靠神的怜悯。","notes":[]},{"n":17,"t":"因为经上有话对法老说：“我将你兴起来，特要在你身上彰显我的权能，为要使我的名传遍全地。”","notes":[]},{"n":18,"t":"由此看来，神要怜悯谁就怜悯谁，要使谁刚硬就使谁刚硬。","notes":[]},{"n":19,"t":"这样，你会对我说：“那么，他为什么还指责人呢？有谁能抗拒他的旨意呢？”","notes":[],"heads":["神的愤怒和怜悯"]},{"n":20,"t":"你这个人哪，你是谁，竟敢向神顶嘴呢？受造之物岂会对造他的说：“你为什么把我造成这样呢？”","notes":[]},{"n":21,"t":"难道陶匠没有权从一团泥里拿一块做成贵重的器皿，又拿一块做成卑贱的器皿吗？","notes":[]},{"n":22,"t":"倘若神要显明他的愤怒，彰显他的权能，难道不可多多忍耐宽容那应受愤怒、预备遭毁灭的器皿吗？","notes":[]},{"n":23,"t":"这是为了要把他丰盛的荣耀彰显在那蒙怜悯、早预备得荣耀的器皿上。","notes":[]},{"n":24,"t":"这器皿也就是我们这些蒙神所召的，不但是从犹太人中，也是从外邦人中召来的。","notes":[]},{"n":25,"t":"正如神在《何西阿书》上说：“那本来不是我子民的，我要称为‘我的子民’；本来不是蒙爱的，我要称为‘蒙爱的’。","notes":[]},{"n":26,"t":"从前在什么地方对他们说：你们不是我的子民，将来就在那里称他们为‘永生神的儿子’。”","notes":[]},{"n":27,"t":"关于以色列人，以赛亚喊着：“虽然以色列人多如海沙，得救的将是剩下的余数，","notes":[]},{"n":28,"t":"因为主要在地上施行他的话，彻底而又迅速。”","notes":[]},{"n":29,"t":"又如以赛亚先前说过：“若不是万军之主给我们存留余种，我们早已变成所多玛，像蛾摩拉一样了。”","notes":[]},{"n":30,"t":"这样，我们要怎么说呢？那不追求义的外邦人却获得了义，就是因信而获得的义。","notes":[],"heads":["以色列人和福音"]},{"n":31,"t":"但以色列人追求律法的义，反而达不到律法的义。","notes":[]},{"n":32,"t":"这是什么缘故呢？是因为他们不凭着信心，而是凭着行为，他们正跌在那绊脚石上。","notes":[]},{"n":33,"t":"就如经上所记：“我在锡安放一块绊脚的石头，使人跌倒的磐石；信靠他的人必不蒙羞。”","notes":[]}]},"10":{"heading":"求告主名的必定得救","verses":[{"n":1,"t":"弟兄们，我心里所渴望的和向神所求的，是要以色列人得救。","notes":[]},{"n":2,"t":"我为他们作证，他们对神有热心，但不是按着真知识。","notes":[]},{"n":3,"t":"因为不明白神的义，想要立自己的义，他们就不服神的义了。","notes":[]},{"n":4,"t":"律法的总结就是基督，使所有信他的人都得着义。","notes":[]},{"n":5,"t":"论到出于律法的义，摩西写着：“行这些事的人，就必因此得生。”","notes":[]},{"n":6,"t":"但出于信的义却如此说：“你不要心里说：谁要升到天上去呢？（就是说，把基督领下来。）","notes":[]},{"n":7,"t":"或说：谁要下到阴间去呢？（就是说，把基督从死人中领上来。）”","notes":[]},{"n":8,"t":"他到底怎么说呢？“这话语就离你近，就在你口中，在你心里，”（就是说，我们传扬所信的话语。）","notes":[]},{"n":9,"t":"你若口里宣认耶稣为主，心里信神叫他从死人中复活，就必得救。","notes":[]},{"n":10,"t":"因为，人心里信就可以称义，口里宣认就可以得救。","notes":[]},{"n":11,"t":"经上说：“凡信靠他的人必不蒙羞。”","notes":[]},{"n":12,"t":"犹太人和希腊人并没有分别，因为人人都有同一位主，他也厚待求告他的每一个人。","notes":[]},{"n":13,"t":"因为“凡求告主名的就必得救”。","notes":[]},{"n":14,"t":"然而，人未曾信他，怎能求告他呢？未曾听见他，怎能信他呢？没有传道的，怎能听见呢？","notes":[]},{"n":15,"t":"若没有奉差遣，怎能传道呢？如经上所记：“报福音、传喜信的人，他们的脚踪何等佳美！”","notes":[]},{"n":16,"t":"但不是每一个人都听从福音，因为以赛亚说：“主啊，我们所传的有谁信呢？”","notes":[]},{"n":17,"t":"可见，信道是从听道来的，听道是从基督的话来的。","notes":[]},{"n":18,"t":"但我要问，人没有听见吗？当然听见了。“他们的声音传遍全地；他们的言语传到地极。”","notes":[]},{"n":19,"t":"我再问，以色列人不知道吗？先有摩西说：“我要以不成国的激起你们嫉妒；我要以愚顽的国惹起你们发怒。”","notes":[]},{"n":20,"t":"又有以赛亚放胆说：“没有寻找我的，我要让他们寻见；没有求问我的，我要向他们显现。”","notes":[]},{"n":21,"t":"关于以色列人，他说：“我整天向那悖逆顶嘴的百姓招手。”","notes":[]}]},"11":{"heading":"以色列的余民","verses":[{"n":1,"t":"那么，我要问，神弃绝了他的百姓吗？绝对没有！因为我也是以色列人，亚伯拉罕的后裔，属便雅悯支派的。","notes":[]},{"n":2,"t":"神并没有弃绝他预先所知道的百姓。你们岂不知道经上论到以利亚是怎么说的呢？他在神面前怎样控告以色列人说：","notes":[]},{"n":3,"t":"“主啊，他们杀了你的先知，拆了你的祭坛，只剩下我一个人，他们还要我的命。”","notes":[]},{"n":4,"t":"但神的指示是怎么对他说的呢？他说：“我为自己留下七千人，是未曾向巴力屈膝的。”","notes":[]},{"n":5,"t":"现在这时刻也是这样，照着出于恩典的拣选，还有所留的余数。","notes":[]},{"n":6,"t":"既是靠恩典，就不凭行为，不然，恩典就不再是恩典了。","notes":[]},{"n":7,"t":"那又怎么说呢？以色列人所寻求的，他们没有得着。但是蒙拣选的人得着了，其余的人却成了顽梗不化的。","notes":[]},{"n":8,"t":"如经上所记：“神给他们昏沉的灵，眼睛看不见，耳朵听不到，直到今日。”","notes":[]},{"n":9,"t":"大卫也说：“愿他们的宴席变为罗网，变为陷阱，变为绊脚石，作他们的报应。","notes":[]},{"n":10,"t":"愿他们的眼睛昏花，看不见；愿你时常弯下他们的腰。”","notes":[]},{"n":11,"t":"那么，我再问，他们失足是要他们跌倒吗？绝对不是！因他们的过犯，救恩反而临到外邦人，要激起他们嫉妒的心。","notes":[],"heads":["外邦人得救"]},{"n":12,"t":"如果他们的过犯成为世界的富足，他们的缺乏成为外邦人的富足，更何况他们全数得救呢？","notes":[]},{"n":13,"t":"我对你们外邦人说，正因为我是外邦人的使徒，我敬重我的职分，","notes":[]},{"n":14,"t":"希望可以激起我骨肉之亲的嫉妒，好救他们一些人。","notes":[]},{"n":15,"t":"如果他们被丢弃，世界因而得以与神和好；他们被收纳，岂不就是从死人中复生吗？","notes":[]},{"n":16,"t":"所献的新面若圣洁，整个面团都圣洁了；树根若圣洁，树枝也圣洁了。","notes":[]},{"n":17,"t":"若有几根枝子被折下来，你这野橄榄枝接上去，同享橄榄根的肥汁，","notes":[]},{"n":18,"t":"你就不可向旧枝子夸口；若是夸口，该知道不是你托着根，而是根托着你。","notes":[]},{"n":19,"t":"你会说，那些枝子被折下来是为了使我接上去。","notes":[]},{"n":20,"t":"不错。他们因为不信，所以被折下来；你因为信，所以立得住。你不可自高，反要战战兢兢。","notes":[]},{"n":21,"t":"神既然不顾惜原来的枝子，岂会顾惜你？","notes":["“岂会顾惜你？”有古卷是“也不会顾惜你。”"]},{"n":22,"t":"可见，神又恩慈又严厉：对那跌倒的人是严厉的；对你是恩慈的，只要你长久在他的恩慈里，不然，你也要被砍下来。","notes":[]},{"n":23,"t":"而且，他们若不是长久不信，仍要被接上，因为神能够重新把他们接上去。","notes":[]},{"n":24,"t":"你是从那天生的野橄榄上砍下来的，尚且违反自然地接在好橄榄上，何况这些原来的枝子岂不更要接在原树上吗？","notes":[]},{"n":25,"t":"弟兄们，我不愿意你们不知道这奥秘，恐怕你们自以为聪明。这奥秘就是有一部分以色列人是硬心的，等到外邦人的数目添满了，","notes":[],"heads":["全以色列都将得救"]},{"n":26,"t":"以色列全家都要得救。如经上所记：“必有一位救主从锡安出来，要消除雅各家一切不虔不敬。”","notes":[]},{"n":27,"t":"“这就是我与他们所立的约，那时我要除去他们的罪。”","notes":[]},{"n":28,"t":"就福音来说，他们为你们的缘故是仇敌；就拣选来说，他们因列祖的缘故是蒙爱的。","notes":[]},{"n":29,"t":"因为神的恩赐和选召是不会撤回的。","notes":[]},{"n":30,"t":"你们从前不顺服神，如今因他们的不顺服，你们倒蒙了怜悯。","notes":[]},{"n":31,"t":"同样，他们现在也是不顺服，叫他们因着施给你们的怜悯，现在也就蒙怜悯。","notes":["有古卷没有“现在”。"]},{"n":32,"t":"因为神把众人都圈在不顺服中，为的是要怜悯众人。","notes":[]},{"n":33,"t":"深哉，神的丰富、智慧和知识！他的判断何其难测！他的踪迹何其难寻！","notes":[]},{"n":34,"t":"谁知道主的心？谁作过他的谋士？","notes":[]},{"n":35,"t":"谁先给了他，使他后来偿还呢？","notes":[]},{"n":36,"t":"因为万有都是本于他，倚靠他，归于他。愿荣耀归给他，直到永远。阿们！","notes":[]}]},"12":{"heading":"基督里的新生活","verses":[{"n":1,"t":"所以，弟兄们，我以神的慈悲劝你们，将身体献上当作活祭，是圣洁的，是神所喜悦的，你们如此事奉乃是理所当然的。","notes":["“你们如此…当然的”或译“你们如此敬拜乃是属灵的”。"]},{"n":2,"t":"不要效法这个世界，只要心意更新而变化，叫你们察验何为神的善良、纯全、可喜悦的旨意。","notes":[]},{"n":3,"t":"我凭着所赐我的恩对你们每一位说：不要把自己看得太高，要照着神所分给各人的信心来衡量，看得合乎中道。","notes":[]},{"n":4,"t":"正如我们一个身子上有好些肢体，肢体也不都有一样的用处。","notes":[]},{"n":5,"t":"这样，我们许多人在基督里是一个身体，互相联络作肢体。","notes":[]},{"n":6,"t":"按着所得的恩典，我们各有不同的恩赐：或说预言，要按着信心的程度说预言；","notes":[]},{"n":7,"t":"或服事的，要专一服事；或教导的，要专一教导；","notes":[]},{"n":8,"t":"或劝勉的，要专一劝勉；施舍的，要诚实；治理的，要殷勤；怜悯人的，要乐意。","notes":[]},{"n":9,"t":"爱，不可虚假；恶，要厌恶；善，要亲近。","notes":[],"heads":["基督徒的生活守则"]},{"n":10,"t":"爱弟兄，要相亲相爱；恭敬人，要彼此推让；","notes":[]},{"n":11,"t":"殷勤，不可懒惰。要灵里火热；常常服侍主。","notes":[]},{"n":12,"t":"在盼望中要喜乐；在患难中要忍耐；祷告要恒切。","notes":[]},{"n":13,"t":"圣徒有缺乏，要供给；异乡客，要殷勤款待。","notes":[]},{"n":14,"t":"要祝福迫害你们的，要祝福，不可诅咒。","notes":["有古卷没有“你们”。"]},{"n":15,"t":"要与喜乐的人同乐；要与哀哭的人同哭。","notes":[]},{"n":16,"t":"要彼此同心，不要心高气傲，倒要俯就卑微的人。不要自以为聪明。","notes":[]},{"n":17,"t":"不要以恶报恶，众人以为美的事要留心去做。","notes":[]},{"n":18,"t":"若是可行，总要尽力与众人和睦。","notes":[]},{"n":19,"t":"各位亲爱的，不要自己伸冤，宁可给主的愤怒留地步，因为经上记着：“主说：‘伸冤在我，我必报应。’”","notes":[]},{"n":20,"t":"不但如此，“你的仇敌若饿了，就给他吃；若渴了，就给他喝。因为你这样做，就是把炭火堆在他的头上。”","notes":[]},{"n":21,"t":"不要被恶所胜，反要以善胜恶。","notes":[]}]},"13":{"heading":"顺服掌权者","verses":[{"n":1,"t":"在上有权柄的，人人要顺服，因为没有权柄不是来自神的。掌权的都是神所立的。","notes":[]},{"n":2,"t":"所以，抗拒掌权的就是抗拒神所立的；抗拒的人必自招审判。","notes":[]},{"n":3,"t":"作官的原不是要使行善的惧怕，而是要使作恶的惧怕。你愿意不惧怕掌权的吗？只要行善，你就可得他的称赞；","notes":[]},{"n":4,"t":"因为他是神的用人，是与你有益的。你若作恶，就该惧怕，因为他不是徒然佩剑；他是神的用人，为神的愤怒，报应作恶的。","notes":[]},{"n":5,"t":"所以，你们必须顺服，不但是因神的愤怒，也是因着良心。","notes":[]},{"n":6,"t":"你们纳粮也为这个缘故，因他们是神的仆役，专管这事。","notes":[]},{"n":7,"t":"凡人所当得的，就给他。当得粮的，给他纳粮；当得税的，给他上税；当惧怕的，惧怕他；当恭敬的，恭敬他。","notes":[]},{"n":8,"t":"你们除了彼此相爱，对任何人都不可亏欠什么，因为那爱人的就成全了律法。","notes":[],"heads":["爱成全律法"]},{"n":9,"t":"那不可奸淫，不可杀人，不可偷盗，不可贪婪，或别的诫命，都包括在“爱邻如己”这一句话之内了。","notes":["“邻”也可译作“人”。"]},{"n":10,"t":"爱是不对邻人作恶，所以爱就成全了律法。","notes":[]},{"n":11,"t":"还有，你们要知道，现在正是该从睡梦中醒来的时候了；因为我们得救，现在比初信的时候更近了。","notes":[],"heads":["白昼将近"]},{"n":12,"t":"黑夜已深，白昼将近。所以我们该除去暗昧的行为，带上光明的兵器。","notes":[]},{"n":13,"t":"行事为人要端正，好像在白昼行走。不可荒宴醉酒；不可好色淫荡；不可纷争嫉妒。","notes":[]},{"n":14,"t":"总要披戴主耶稣基督，不要只顾满足肉体，去放纵私欲。","notes":[]}]},"14":{"heading":"不可评断弟兄","verses":[{"n":1,"t":"信心软弱的，你们要接纳，不同的意见，不要争论。","notes":[]},{"n":2,"t":"有人信什么都可吃；但那软弱的，只吃蔬菜。","notes":[]},{"n":3,"t":"吃的人不可轻看不吃的人；不吃的人也不可评断吃的人，因为神已经接纳他了。","notes":[]},{"n":4,"t":"你是谁，竟评断别人的仆人呢？他或站立或跌倒，自有他的主人在，而且他也必会站立，因为主能使他站稳。","notes":[]},{"n":5,"t":"有人看这日比那日强；有人看日日都是一样。只是各人要在自己的心意上坚定。","notes":[]},{"n":6,"t":"守日子的人是为主守的。吃的人是为主吃的，因他感谢神；不吃的人是为主不吃的，他也感谢神。","notes":[]},{"n":7,"t":"我们没有一个人为自己而活，也没有一个人为自己而死。","notes":[]},{"n":8,"t":"我们若活，是为主而活；我们若死，是为主而死。所以，我们或死或活总是主的人。","notes":[]},{"n":9,"t":"为此，基督死了，又活了，为要作死人和活人的主。","notes":[]},{"n":10,"t":"可是你，你为什么评断弟兄呢？你又为什么轻看弟兄呢？因我们都要站在神的审判台前。","notes":[]},{"n":11,"t":"经上写着：“主说，我指着我的永生起誓：万膝必向我跪拜；万口必称颂神。”","notes":[]},{"n":12,"t":"这样看来，我们各人一定要把自己的事在神面前交代。","notes":["有古卷没有“在神面前”。"]},{"n":13,"t":"所以，我们不可再彼此评断，宁可决意不给弟兄放置障碍或绊脚石。","notes":[],"heads":["不可使弟兄跌倒"]},{"n":14,"t":"我凭着主耶稣确知深信，凡物本来没有不洁净的，除非人以为不洁净的，在他就不洁净了。","notes":[]},{"n":15,"t":"你若因食物使弟兄忧愁，就不是按着爱心行事。基督已经为他死，你不可因你的食物使他败坏。","notes":[]},{"n":16,"t":"所以，不可让你们的善被人毁谤。","notes":[]},{"n":17,"t":"因为神的国不在乎饮食，而在乎公义、和平及圣灵中的喜乐。","notes":["“公义…喜乐”或译“圣灵中的公义、和平及喜乐”。"]},{"n":18,"t":"凡这样服侍基督的，就为神所喜悦，又为人所赞许。","notes":[]},{"n":19,"t":"所以，我们务要追求和平与彼此造就的事。","notes":["“务要追求”：有古卷是“追求”。"]},{"n":20,"t":"不可因食物毁坏神的工作。一切都是洁净的，但有人因食物使人跌倒，这在他就是恶了。","notes":[]},{"n":21,"t":"无论是吃肉是喝酒，是什么别的事，使弟兄跌倒，一概不做，才是善的。","notes":[]},{"n":22,"t":"你有信心，就要在神面前持守。人能在自己以为可行的事上不自责就有福了。","notes":[]},{"n":23,"t":"若有人疑惑而吃的，就被定罪，因为他吃不是出于信心。凡不出于信心的都是罪。","notes":[]}]},"15":{"heading":"要让邻人喜悦","verses":[{"n":1,"t":"我们坚强的人应该分担不坚强的人的软弱，不求自己的喜悦。","notes":[]},{"n":2,"t":"我们各人务必要让邻人喜悦，使他得益处，得造就。","notes":[]},{"n":3,"t":"因为基督也不求自己的喜悦，如经上所记：“辱骂你的人的辱骂都落在我身上。”","notes":[]},{"n":4,"t":"从前所写的圣经都是为教导我们写的，要使我们藉着忍耐和因圣经所生的安慰，得着盼望。","notes":[]},{"n":5,"t":"但愿赐忍耐和安慰的神使你们彼此同心，效法基督耶稣，","notes":[]},{"n":6,"t":"为使你们同心同声荣耀我们主耶稣基督的父神！","notes":[]},{"n":7,"t":"所以，你们要彼此接纳，如同基督接纳你们一样，归荣耀给神。","notes":[],"heads":["神的福音一视同仁"]},{"n":8,"t":"我说，基督是为神真理作了受割礼的人的执事，要证实所应许列祖的话，","notes":[]},{"n":9,"t":"并使外邦人，因他的怜悯，荣耀神。如经上所记：“因此，我要在外邦中称颂你，歌颂你的名。”","notes":[]},{"n":10,"t":"又说：“外邦人哪，你们要与主的子民一同欢乐。”","notes":[]},{"n":11,"t":"又说：“列邦啊，你们要赞美主！万民哪，你们都要颂赞他！”","notes":[]},{"n":12,"t":"又有以赛亚说：“将来有耶西的根，就是那兴起来要治理列邦的；外邦人要仰望他。”","notes":[]},{"n":13,"t":"愿赐盼望的神，因你们的信把各样的喜乐、平安充满你们的心，使你们藉着圣灵的能力大有盼望！","notes":["“平安”或译“和平”；33节同。"]},{"n":14,"t":"我的弟兄们，我本人也深信你们自己充满良善，有各种丰富的知识，也能彼此劝戒。","notes":[],"heads":["保罗的宣教使命"]},{"n":15,"t":"但我更大胆写信给你们，是要在一些事上提醒你们，我因神所赐我的恩，","notes":[]},{"n":16,"t":"使我为外邦人作基督耶稣的仆役，作神福音的祭司，使所献上的外邦人因着圣灵成为圣洁，可蒙悦纳。","notes":[]},{"n":17,"t":"所以，有关神面前的事奉，我在基督耶稣里是有可夸的。","notes":[]},{"n":18,"t":"除了基督藉我做的那些事，我什么都不敢提，只提他藉我的言语作为，用神迹奇事的能力，并神的灵的能力，使外邦人顺服；甚至我从耶路撒冷，直转到以利哩古，到处传了基督的福音。","notes":["“神的灵”：有古卷是“圣灵”。"],"end":19},{"n":20,"t":"这样，我立了志向，不在基督的名已经传扬过的地方传福音，免得建造在别人的根基上；","notes":[]},{"n":21,"t":"却如经上所记：“未曾传给他们的，他们必看见；未曾听见过的事，他们要明白。”","notes":[]},{"n":22,"t":"因此我多次被拦阻，不能到你们那里去。","notes":[],"heads":["保罗计划访问罗马"]},{"n":23,"t":"但如今，在这一带再没有可传的地方，而且这许多年来，我迫切想去你们那里，","notes":[]},{"n":24,"t":"盼望到西班牙去的时候经过，得见你们，先与你们彼此交往，心里稍得满足，然后蒙你们为我送行。","notes":[]},{"n":25,"t":"但如今我要到耶路撒冷去，供应圣徒的需要。","notes":[]},{"n":26,"t":"因为马其顿和亚该亚人乐意凑出一些捐款给耶路撒冷圣徒中的穷人。","notes":[]},{"n":27,"t":"这固然是他们乐意的，其实也算是所欠的债；因为外邦人既然分享了他们灵性上的好处，就当把肉体上的需用供给他们。","notes":[]},{"n":28,"t":"等我办完了这事，把这笔捐款交付给他们，我就要路过你们那里，到西班牙去。","notes":["“捐款”：原文直译“果实”。"]},{"n":29,"t":"我也知道去你们那里的时候，我将带着基督丰盛的恩典去。","notes":[]},{"n":30,"t":"弟兄们，我藉着我们的主耶稣基督，又藉着圣灵的爱，劝你们与我一同竭力为我祈求神，","notes":[]},{"n":31,"t":"使我脱离在犹太不顺从的人，也让我在耶路撒冷的事奉可蒙圣徒悦纳，","notes":[]},{"n":32,"t":"并使我照着神的旨意欢欢喜喜地到你们那里，与你们同得安息。","notes":[]},{"n":33,"t":"愿赐平安的神与你们众人同在。阿们！","notes":[]}]},"16":{"heading":"问安","verses":[{"n":1,"t":"我对你们推荐我们的姊妹非比，她是坚革哩教会中的执事。","notes":[]},{"n":2,"t":"请你们在主里用合乎圣徒的方式来接待她。她在任何事上需要你们帮助，你们就帮助她；因她素来帮助许多人，也帮助了我。","notes":[]},{"n":3,"t":"请向百基拉和亚居拉问安。他们在基督耶稣里作我的同工，","notes":[]},{"n":4,"t":"也为我的性命把自己的生死置之度外；不但我感谢他们，就是外邦的众教会也感谢他们。","notes":[]},{"n":5,"t":"又向在他们家中的教会问安。向我所亲爱的以拜尼土问安，他是亚细亚归于基督的初结果子。","notes":[]},{"n":6,"t":"又向马利亚问安，她为你们非常辛劳。","notes":[]},{"n":7,"t":"又向与我一同坐监的亲戚安多尼古和犹尼亚问安，他们在使徒中是有名望的，也是比我先在基督里的。","notes":[]},{"n":8,"t":"又向我在主里面所亲爱的暗伯利问安。","notes":[]},{"n":9,"t":"又向我们在基督里的同工耳巴奴和我所亲爱的士大古问安。","notes":[]},{"n":10,"t":"又向在基督里经过考验的亚比利问安。向亚利多布家里的人问安。","notes":[]},{"n":11,"t":"又向我亲戚希罗天问安。向拿其数家在主里的人问安。","notes":[]},{"n":12,"t":"又向为主辛劳的土非拿和土富撒问安。向所亲爱、为主非常辛劳的彼息问安。","notes":[]},{"n":13,"t":"又向在主里蒙拣选的鲁孚和他母亲问安，他的母亲就是我的母亲。","notes":[]},{"n":14,"t":"又向亚逊其土、弗勒干、黑米、八罗巴、黑马，和跟他们在一起的弟兄们问安。","notes":[]},{"n":15,"t":"又向非罗罗古和犹利亚，尼利亚和他姊妹，阿林巴和跟他们在一起的众圣徒问安。","notes":[]},{"n":16,"t":"你们要以圣洁的吻彼此问安。基督的众教会都向你们问安！","notes":[]},{"n":17,"t":"弟兄们，那些离间你们、使你们跌倒、违背所学之道的人，我劝你们要留意躲避他们。","notes":[]},{"n":18,"t":"因为这样的人不服侍我们的主基督，只服侍自己的肚腹，用花言巧语诱惑老实人的心。","notes":[]},{"n":19,"t":"你们的顺服已经传于众人，所以我为你们欢喜；但我愿你们在善上聪明，在恶上愚拙。","notes":[]},{"n":20,"t":"那赐平安的神快要把撒但践踏在你们脚下。愿我们主耶稣基督的恩与你们同在！","notes":["“平安”或译“和平”。"]},{"n":21,"t":"我的同工提摩太，和我的亲戚路求、耶孙、所西巴德，向你们问安。","notes":[]},{"n":22,"t":"我这代笔写信的德提，在主里向你们问安。","notes":[]},{"n":23,"t":"那接待我，也接待全教会的该犹，向你们问安。城里的财务官以拉都和弟兄括土向你们问安。","notes":["有古卷加“24 愿我们的主耶稣基督赐恩典给你们各位！阿们！”"]},{"n":25,"t":"惟有神能照我所传的福音和所讲的耶稣基督，并照历代以来隐藏的奥秘的启示，坚固你们。","notes":[],"heads":["颂赞"]},{"n":26,"t":"这奥秘如今显示出来，而且按着永生神的命令，藉众先知的书指示万民，使他们因信而顺服。","notes":[]},{"n":27,"t":"愿荣耀，藉着耶稣基督，归给独一全智的神，直到永远。阿们！","notes":[]}]}},"1CO":{"1":{"heading":"祝福和感谢","verses":[{"n":1,"t":"奉神旨意，蒙召作基督耶稣使徒的保罗，同弟兄所提尼，","notes":[]},{"n":2,"t":"写信给在哥林多神的教会—就是在基督耶稣里成圣、蒙召作圣徒的—以及所有在各处求告我主耶稣基督之名的人。基督是他们的主，也是我们的主。","notes":[]},{"n":3,"t":"愿恩惠、平安从我们的父神并主耶稣基督归给你们！","notes":["“平安”或译“和平”。"]},{"n":4,"t":"我常为你们感谢我的神，因神在基督耶稣里所赐给你们的恩惠。","notes":[]},{"n":5,"t":"因为你们在他里面凡事富足，具有各种口才、各样知识，","notes":[]},{"n":6,"t":"正如我为基督作的见证在你们心里得以坚固，","notes":[]},{"n":7,"t":"以致你们在恩赐上一无欠缺，切切等候我们主耶稣基督的显现。","notes":[]},{"n":8,"t":"他也必坚固你们到底，使你们在我们主耶稣基督的日子无可指责。","notes":["有古卷没有“基督”。"]},{"n":9,"t":"神是信实的，他呼召你们好与他儿子—我们的主耶稣基督—共享团契。","notes":[]},{"n":10,"t":"弟兄们，我藉我们主耶稣基督的名劝你们说话要一致。你们中间不可分裂，只要一心一意彼此团结。","notes":[],"heads":["教会中的纷争"]},{"n":11,"t":"我的弟兄们，革来氏家里的人曾对我提起你们，说你们中间有纷争。","notes":[]},{"n":12,"t":"我的意思是，你们各人说：“我是属保罗的”；“我是属亚波罗的”；“我是属矶法的”；“我是属基督的。”","notes":[]},{"n":13,"t":"基督是分裂的吗？保罗为你们钉了十字架吗？你们是奉保罗的名受了洗吗？","notes":[]},{"n":14,"t":"我感谢神，除了基利司布和该犹以外，我没有给你们中的任何一个人施洗，","notes":["有古卷没有“神”。"]},{"n":15,"t":"免得有人说你们是奉我的名受洗的。","notes":[]},{"n":16,"t":"我曾为司提法那家施过洗；此外我已记不清有没有给别人施过洗。","notes":[]},{"n":17,"t":"因为基督差遣我不是为施洗，而是为传福音；并不是用智慧的言论，免得基督的十字架落了空。","notes":[]},{"n":18,"t":"因为十字架的道理，在那灭亡的人是愚拙，在我们得救的人却是神的大能。","notes":[],"heads":["基督是神的大能和智慧"]},{"n":19,"t":"就如经上所记：“我要摧毁智慧人的智慧，废弃聪明人的聪明。”","notes":[]},{"n":20,"t":"智慧人在哪里？文士在哪里？这世上的辩士在哪里？神岂不是已使这世上的智慧变成愚拙了吗？","notes":[]},{"n":21,"t":"既然世人凭自己的智慧不认识神，神就本着自己的智慧乐意藉着人所传愚拙的话拯救那些信的人。","notes":[]},{"n":22,"t":"犹太人要的是神迹，希腊人求的是智慧，","notes":[]},{"n":23,"t":"我们却是传被钉十字架的基督，这对犹太人是绊脚石，对外邦人是愚拙；","notes":[]},{"n":24,"t":"但对那蒙召的，无论是犹太人、希腊人，基督总是神的大能，神的智慧。","notes":[]},{"n":25,"t":"因为，神的愚拙总比人智慧；神的软弱总比人强壮。","notes":[]},{"n":26,"t":"弟兄们哪，想一想你们的蒙召，按着人的观点，有智慧的不多，有能力的不多，有尊贵地位的也不多。","notes":[]},{"n":27,"t":"但是，神拣选了世上愚拙的，为了使有智慧的羞愧；又拣选了世上软弱的，为了使强壮的羞愧。","notes":[]},{"n":28,"t":"神也拣选了世上卑贱的，被人厌恶的，以及那一无所有的，为要废掉那样样都有的，","notes":[]},{"n":29,"t":"使凡血肉之躯的，在神面前，一个也不能自夸。","notes":[]},{"n":30,"t":"但你们得以在基督耶稣里是本乎神，他使基督成为我们的智慧，成为公义、圣洁、救赎。","notes":[]},{"n":31,"t":"如经上所记：“要夸耀的，该夸耀主。”","notes":[]}]},"2":{"heading":"传扬钉十字架的基督","verses":[{"n":1,"t":"弟兄们，从前我到你们那里去，并没有用高言大智对你们宣讲神的奥秘。","notes":[]},{"n":2,"t":"因为我曾定了主意，在你们中间不知道别的，只知道耶稣基督并他钉十字架。","notes":[]},{"n":3,"t":"我在你们那里时，又软弱，又惧怕，又战战兢兢。","notes":[]},{"n":4,"t":"我说的话、讲的道不是用委婉智慧的言语，而是以圣灵的大能来证明，","notes":["“委婉智慧的言语”：有古卷是“委婉的智慧”；另有古卷是“人委婉智慧的言语”。"]},{"n":5,"t":"为要使你们的信不靠着人的智慧，而是靠着神的大能。","notes":[]},{"n":6,"t":"然而，在成熟的人中，我们也讲智慧，但不是今世的智慧，也不是今世有权有位、将要灭亡的人的智慧。","notes":[],"heads":["神之灵的启示"]},{"n":7,"t":"我们讲的是从前隐藏的、神奥秘的智慧，就是神在万世以前预定使我们得荣耀的智慧；","notes":[]},{"n":8,"t":"这智慧，今世有权有位的人没有一个知道，若知道，他们就不会把荣耀的主钉在十字架上了。","notes":[]},{"n":9,"t":"如经上所记：“神为爱他的人所预备的是眼睛未曾看见，耳朵未曾听见，人心也未曾想到的。”","notes":[]},{"n":10,"t":"只有神藉着圣灵把这事向我们显明了；因为圣灵参透万事，就是神深奥的事也参透了。","notes":[]},{"n":11,"t":"除了在人里头的灵，谁知道人的事？照样，除了神的灵，也没有人知道神的事。","notes":[]},{"n":12,"t":"我们所领受的并不是世上的灵，而是从神来的灵，为使我们知道神把恩赐赏给我们的事。","notes":[]},{"n":13,"t":"我们也讲说这些事，不是用人的智慧所教的言语，而是用圣灵所教的言语，用属灵的话解释属灵的事。","notes":["“用属灵的话解释属灵的事”或译“把属灵的事讲给属灵的人”。"]},{"n":14,"t":"然而，属血气的人不接受神的灵的事，他反倒以这为愚拙，并且他不能了解，因为这些事惟有属灵的人才能领悟。","notes":[]},{"n":15,"t":"属灵的人能看透万事，却没有一人能看透他。","notes":[]},{"n":16,"t":"“谁曾知道主的心？谁会教导他？”至于我们，我们有基督的心。","notes":[]}]},"3":{"heading":"神的同工","verses":[{"n":1,"t":"弟兄们，我从前对你们说话，还不能把你们当作属灵的，只能把你们当作属肉体的，你们在基督里仅是婴孩。","notes":[]},{"n":2,"t":"我用奶喂你们，没有用饭喂你们，因为那时你们不能吃。就是如今还是不能，","notes":[]},{"n":3,"t":"因为你们仍是属肉体的。你们中间有嫉妒、纷争，这岂不是属乎肉体，照着世人的样子生活吗？","notes":[]},{"n":4,"t":"有人说：“我是属保罗的”；有人说：“我是属亚波罗的”；这样你们岂不是和世人一样吗？","notes":[]},{"n":5,"t":"亚波罗算什么？保罗算什么？我们都是神的执事，藉着我们，你们信了；这不过是照着主给各人的恩赐去做罢了。","notes":[]},{"n":6,"t":"我栽种了，亚波罗浇灌了，惟有神使它生长。","notes":[]},{"n":7,"t":"可见，栽种的算不了什么，浇灌的也算不了什么；惟有神能使它生长。","notes":[]},{"n":8,"t":"栽种的和浇灌的都是一样，但将来各人要照自己的劳苦得到自己的报酬。","notes":[]},{"n":9,"t":"因为我们是神的同工，而你们是神的田地，神的房屋。","notes":[]},{"n":10,"t":"我照神所给我的恩典，好像一个聪明的工头，立好了根基，别人在上面建造；只是各人要谨慎怎样在上面建造。","notes":[]},{"n":11,"t":"因为，那已经立好的根基就是耶稣基督，此外没有人能立别的根基。","notes":[]},{"n":12,"t":"若有人用金银、宝石，草木、禾秸，在这根基上建造，","notes":[]},{"n":13,"t":"各人的工程必将显露，因为那日子要将它显明，有火把它暴露出来，这火要试炼各人的工程怎样。","notes":[]},{"n":14,"t":"人在那根基上所建造的工程若能保得住，他将要得赏赐。","notes":[]},{"n":15,"t":"人的工程若被烧了，他将损失，虽然他自己将得救，却要像从火里经过一样。","notes":[]},{"n":16,"t":"难道不知你们是神的殿，神的灵住在你们里面吗？","notes":[]},{"n":17,"t":"若有人毁坏神的殿，神一定要毁灭那人；因为神的殿是神圣的，这殿就是你们。","notes":[]},{"n":18,"t":"谁都不可自欺。你们中间若有人自以为在今世有智慧，倒不如变为愚拙，好成为有智慧的。","notes":[]},{"n":19,"t":"因为这世界的智慧在神看来是愚拙的。如经上记着：“主使有智慧的人中了自己的诡计；”","notes":[]},{"n":20,"t":"又说：“主知道智慧人的意念，因为它们是虚妄的。”","notes":[]},{"n":21,"t":"所以，无论谁都不可夸耀人；因为万有都是你们的，","notes":[]},{"n":22,"t":"或保罗，或亚波罗，或矶法，或世界，或生，或死，或现今的事，或将来的事，全是你们的，","notes":[]},{"n":23,"t":"而你们是属基督的，基督是属神的。","notes":[]}]},"4":{"heading":"使徒的工作","verses":[{"n":1,"t":"人应该把我们看为基督的执事，为神的奥秘的管家。","notes":[]},{"n":2,"t":"所求于管家的，是要他忠心。","notes":[]},{"n":3,"t":"我被你们评断，或被别人评断，我都以为是极小的事；连我自己也不评断自己。","notes":[]},{"n":4,"t":"虽然我不觉得自己有错，却也不能因此判为无罪；审断我的是主。","notes":[]},{"n":5,"t":"所以，时候未到，在主来以前什么都不要评断，他要照出暗中的隐情，揭发人的动机。那时，各人要从神那里得着称赞。","notes":[]},{"n":6,"t":"弟兄们，为你们的缘故，我拿这些事应用到我自己和亚波罗身上，让你们从我们学到“不可过于圣经所记”这话的意思，免得你们自高自大，看重这个，看轻那个。","notes":[]},{"n":7,"t":"使你与人不同的是谁呢？你所有的有哪一个不是领受的呢？若是领受的，为何自夸，仿佛不是领受的呢？","notes":[]},{"n":8,"t":"你们已经饱足了，已经富足了，用不着我们，自己就作王了。我愿意你们果真作王，让我们也可以与你们一同作王！","notes":[]},{"n":9,"t":"我想，神把我们作使徒的明显地列在末后，好像定死罪的囚犯，因为我们成了一台戏，给世界、天使和众人观看。","notes":[]},{"n":10,"t":"我们为基督的缘故成为愚拙的；你们在基督里倒是聪明的。我们软弱，你们倒强壮；你们有荣耀，我们倒被藐视。","notes":[]},{"n":11,"t":"直到如今，我们还是又饥又渴，又赤身露体，又挨打，又到处漂泊，","notes":[]},{"n":12,"t":"并且劳碌，亲手做工；被人咒骂，我们就祝福；被人迫害，我们就忍受；","notes":[]},{"n":13,"t":"被人毁谤，我们就劝导。直到如今，人还把我们看作世上的污秽，万物中的渣滓。","notes":[]},{"n":14,"t":"我写这些话，不是要使你们羞愧，而是要警戒你们，好像我所爱的儿女一样。","notes":[]},{"n":15,"t":"虽然你们在基督里有无数的导师，却没有许多父亲，因我是在基督耶稣里用福音生了你们。","notes":[]},{"n":16,"t":"所以，我求你们要效法我。","notes":[]},{"n":17,"t":"因此，我已差提摩太到你们那里去。他在主里面是我亲爱和忠心的儿子；他要提醒你们，我在基督耶稣里怎样行事为人，在各处各教会中怎样教导人。","notes":["“基督耶稣”：有古卷是“基督”。"]},{"n":18,"t":"有些人以为我不到你们那里去而自高自大。","notes":[]},{"n":19,"t":"但是，主若准许，我会很快到你们那里去；我所要知道的，不是那些自高自大者的言语，而是他们的权能。","notes":[]},{"n":20,"t":"因为神的国不在乎言语，而在乎权能。","notes":[]},{"n":21,"t":"你们愿意怎么样呢？要我带着棍子到你们那里去呢，还是带着慈爱温柔的心呢？","notes":[]}]},"5":{"heading":"不容忍淫乱的事","verses":[{"n":1,"t":"我确实听说在你们中间有淫乱的事；这种淫乱连外邦人中也没有，就是有人和他的继母同居。","notes":[]},{"n":2,"t":"你们还自高自大！你们不是该觉得痛心，把做这事的人从你们中间赶出去吗？","notes":[]},{"n":3,"t":"我人虽然不在你们那里，心却在你们那里，好像亲自与你们同在。我奉我们主耶稣的名，已经判断了做这事的人。你们聚会的时候，我的心和你们同在。你们藉着我们主耶稣的权能，","notes":["“我们主耶稣”：有古卷是“主耶稣基督”；另有古卷是“我们主耶稣基督”。"],"end":4},{"n":5,"t":"要把这样的人交给撒但，使他的肉体败坏，好让他的灵魂在主的日子可以得救。","notes":[]},{"n":6,"t":"你们这样自夸是不好的。你们不知道一点面酵能使全团发起来吗？","notes":[]},{"n":7,"t":"既然你们是无酵的面，要把旧酵除净，好使你们成为新团；因为我们逾越节的羔羊—基督已经被杀献为祭牲了。","notes":[]},{"n":8,"t":"所以，我们来守这节，不可用旧酵，就是不可用恶毒、邪恶的酵，只用纯洁真实的无酵饼。","notes":[]},{"n":9,"t":"我先前写信告诉过你们，不可与淫乱的人交往。","notes":[]},{"n":10,"t":"此话不是泛指这世上所有行淫乱的，或贪婪的，勒索的，或拜偶像的；若是这样，你们非离开这世界不可。","notes":[]},{"n":11,"t":"但现在，我写信告诉你们，若有称为弟兄的人却仍犯淫乱，或贪婪，或拜偶像，或辱骂，或醉酒，或勒索，这样的人不可跟他交往，就是跟他吃饭都不可以。","notes":[]},{"n":12,"t":"因为审判教外的人与我何干？教内的人岂不是你们要审判吗？","notes":[]},{"n":13,"t":"至于外人有神审判他们。如经上说：“要从你们中间把那邪恶的人赶出去。”","notes":[]}]},"6":{"heading":"不可彼此告状","verses":[{"n":1,"t":"你们中间有彼此争吵的事，怎敢告到不义的人面前，而不告到圣徒面前呢？","notes":[]},{"n":2,"t":"你们岂不知圣徒要审判世界吗？若世界要受你们的审判，难道你们不配审判这最小的事吗？","notes":[]},{"n":3,"t":"你们岂不知我们要审判天使吗？何况今生的事呢！","notes":[]},{"n":4,"t":"既是这样，你们若有今生当审判的事，会让教会所轻看的人来审判吗？","notes":[]},{"n":5,"t":"我说这话是要使你们惭愧。难道你们中间没有一个有智慧的人能审断弟兄中的事吗？","notes":[]},{"n":6,"t":"你们竟然有弟兄去告弟兄，而且告到不信主的人面前。","notes":[]},{"n":7,"t":"你们彼此告状，这已经是你们的大错了。为什么不情愿受冤屈呢？为什么不情愿吃亏呢？","notes":[]},{"n":8,"t":"你们反倒去冤枉人，亏负人，况且所冤枉所亏负的就是弟兄。","notes":[]},{"n":9,"t":"你们岂不知不义的人不能承受神的国吗？不要自欺！无论是淫乱的、拜偶像的、奸淫的、作娼妓的，亲男色的、","notes":["“作娼妓”：原文意思是“娇媚”，可能指神庙里的男妓。"]},{"n":10,"t":"偷窃的、贪婪的、醉酒的、辱骂的、勒索的，都不能承受神的国。","notes":[]},{"n":11,"t":"从前你们中间也有人是这样；但现在你们奉主耶稣基督的名，并藉着我们神的灵，已经洗净，已经成圣，已经称义了。","notes":["“主耶稣基督”：有古卷是“主耶稣”；另有古卷是“我们主耶稣基督”。"]},{"n":12,"t":"“凡事我都可行”，但不是凡事都有益处。“凡事我都可行”，但无论哪一件，我都不受它的辖制。","notes":[],"heads":["在身体上荣耀神"]},{"n":13,"t":"“食物是为肚腹，肚腹是为食物”；但神要使这两样都毁坏。身体不是为淫乱，而是为主；主也是为身体。","notes":[]},{"n":14,"t":"神已经使主复活，也要用他自己的能力使我们复活。","notes":[]},{"n":15,"t":"你们岂不知道你们的身体是基督的肢体吗？我可以把基督的肢体作为娼妓的肢体吗？绝对不可！","notes":[]},{"n":16,"t":"你们岂不知道与娼妓苟合的，就是与她成为一体吗？因为主说：“二人要成为一体。”","notes":[]},{"n":17,"t":"但与主联合的，就是与主成为一灵。","notes":[]},{"n":18,"t":"你们要远避淫行。人所犯的，无论什么罪，都在身体以外；惟有行淫的，是得罪自己的身体。","notes":[]},{"n":19,"t":"你们岂不知道你们的身体是圣灵的殿吗？这圣灵是从神而来，住在你们里面的。而且你们不是属自己的人，","notes":[]},{"n":20,"t":"因为你们是重价买来的。所以，要在你们的身体上荣耀神。","notes":[]}]},"7":{"heading":"婚姻的问题","verses":[{"n":1,"t":"关于你们信上所提的事，男人不亲近女人倒好。","notes":[]},{"n":2,"t":"但为了避免淫乱的事，男人当各有自己的妻子，女人也当各有自己的丈夫。","notes":[]},{"n":3,"t":"丈夫对妻子要尽本分；妻子对丈夫也要如此。","notes":[]},{"n":4,"t":"妻子对自己的身体没有主张的权柄，权柄在丈夫；丈夫对自己的身体也没有主张的权柄，权柄在妻子。","notes":[]},{"n":5,"t":"夫妻不可忽略对方的需求，除非为了要专心祷告，在两相情愿下暂时分房；以后仍要同房，免得撒但趁着你们情不自禁而引诱你们。","notes":[]},{"n":6,"t":"我说这话是出于容忍，不是命令。","notes":[]},{"n":7,"t":"我愿众人像我一样；但是各人都有来自神的恩赐，一个是这样，一个是那样。","notes":[]},{"n":8,"t":"我对没有嫁娶的和寡妇说，他们若能维持独身像我一样就好。","notes":[]},{"n":9,"t":"但他们若不能自制，就应该嫁娶，与其欲火攻心，倒不如结婚为妙。","notes":[]},{"n":10,"t":"至于那已经嫁娶的，我吩咐他们—其实不是我，而是主吩咐的：妻子不可离开丈夫，","notes":[]},{"n":11,"t":"若是离开了，不可再嫁，不然要跟丈夫复和；丈夫也不可离弃妻子。","notes":[]},{"n":12,"t":"我对其余的人说—是我，不是主说—倘若某弟兄有不信的妻子，妻子也情愿和他一起生活，他就不可离弃妻子。","notes":[]},{"n":13,"t":"妻子有不信的丈夫，丈夫也情愿和她一起生活，她就不可离弃丈夫。","notes":[]},{"n":14,"t":"因为不信的丈夫会因着妻子成了圣洁；不信的妻子也会因着丈夫成了圣洁。不然，你们的儿女就不洁净了，但现在他们是圣洁的。","notes":["“丈夫”：原文直译“弟兄”。"]},{"n":15,"t":"倘若那不信的人要离开，就由他离开吧！无论是弟兄是姊妹，遇着这样的事都不必拘束。神召你们原是要你们和睦。","notes":[]},{"n":16,"t":"你这作妻子的怎么知道不能救你的丈夫呢？你这作丈夫的怎么知道不能救你的妻子呢？","notes":[]},{"n":17,"t":"无论如何，要照主所分给各人的恩赐和神所召各人的情况生活。我在各教会里都是这样规定的。","notes":[],"heads":["照蒙召时的身份生活"]},{"n":18,"t":"有人受割礼后才蒙召，他就不必除去割礼的记号。有人未受割礼前蒙召，他就不必受割礼。","notes":[]},{"n":19,"t":"受割礼算不了什么，不受割礼也算不了什么，只要谨守神的诫命就是了。","notes":[]},{"n":20,"t":"各人蒙召的时候是什么身份，要守住这身份。","notes":[]},{"n":21,"t":"你是作奴隶时蒙召的吗？不要介意；若能获得自由，就争取自由更好。","notes":[]},{"n":22,"t":"因为，蒙主呼召的奴仆是主所释放的人；蒙主呼召的自由之人是基督的奴仆。","notes":[]},{"n":23,"t":"你们是重价买来的；不要作人的奴仆。","notes":[]},{"n":24,"t":"弟兄们，你们各人蒙召的时候是什么身份，要在神面前守住这身份。","notes":[]},{"n":25,"t":"关于未婚女子，我没有主的命令，但我既蒙主怜悯、作为一个可信靠的人，把自己的意见告诉你们。","notes":[],"heads":["未婚和寡居"]},{"n":26,"t":"因现今的艰难，据我看来，人不如安于现状。","notes":[]},{"n":27,"t":"你已经有了妻子，就不要求摆脱；你还没有妻子，就不要想娶妻。","notes":[]},{"n":28,"t":"你若娶妻，并不是犯罪；未婚女子若出嫁，也不是犯罪。然而，这等人会遭受肉身上的苦难，我宁愿你们免受这苦难。","notes":[]},{"n":29,"t":"弟兄们，我是说：时候不多了。从此以后，那有妻子的，要像没有一样；","notes":[]},{"n":30,"t":"哀哭的，不像在哀哭；快乐的，不像在快乐；购买的，像一无所得；","notes":[]},{"n":31,"t":"享受这世界的，不像在享受这世界；因为这世界的局面将要过去了。","notes":[]},{"n":32,"t":"我愿你们一无挂虑。没有结婚的是为主的事挂虑，想怎样令主喜悦；","notes":[]},{"n":33,"t":"结了婚的是为世上的事挂虑，想怎样让妻子喜悦，","notes":[]},{"n":34,"t":"于是，他就分心了。没有结婚的和未婚的女子是为主的事挂虑，为要身体和心灵都圣洁；已经出嫁的是为世上的事挂虑，想怎样让丈夫喜悦。","notes":[]},{"n":35,"t":"我说这话是为你们的益处，不是要限制你们，而是要你们做合宜的事，得以不分心地对主忠诚。","notes":[]},{"n":36,"t":"若有人认为自己待他的女儿不合宜，女儿也过了适婚年龄，他可以随意处理，不算有罪，让两人结婚就是了。","notes":["“女儿”或译“未婚妻”。","“女儿…适婚年龄”或译“女儿也过了年龄，应该结婚”；又或译“对未婚妻有强烈的欲望”。"]},{"n":37,"t":"倘若有人心里坚定，没有不得已的事，并且由得自己作主，心里又决定了不让女儿结婚，这样做也好。","notes":["“不让女儿结婚”或译“不跟未婚妻结婚”。"]},{"n":38,"t":"这样看来，让自己的女儿结婚固然是好，不让她结婚更好。","notes":["“让…结婚”或译“跟自己的未婚妻结婚”。"]},{"n":39,"t":"丈夫活着的时候，妻子是受约束的；丈夫若长眠了，妻子就自由了，可以随意再嫁，只是要嫁给主里面的人。","notes":[]},{"n":40,"t":"然而，按我的意见，她若能守节就更有福气。我想我自己也有神的灵的感动。","notes":[]}]},"8":{"heading":"祭过偶像的食物","verses":[{"n":1,"t":"关于祭过偶像的食物，我们晓得“我们都有知识”，但知识使人自高自大，惟有爱心能造就人。","notes":[]},{"n":2,"t":"若有人自以为知道什么，他其实仍不知道他所应当知道的。","notes":[]},{"n":3,"t":"若有人爱神，他就是神所认识的人了。","notes":[]},{"n":4,"t":"关于吃祭过偶像的食物，我们知道“偶像在世上算不得什么”；也知道“神只有一位，没有别的”。","notes":[]},{"n":5,"t":"虽然在天上或地上有许多所谓的神明，就如他们中间有许多的神明，许多的主，","notes":[]},{"n":6,"t":"但是我们只有一位神，就是父，万物都出于他，我们也归于他；并只有一位主，就是耶稣基督，万物都是藉着他而有，我们也是藉着他而有。","notes":[]},{"n":7,"t":"可是，不是人人都有这知识。有人到现在因拜惯了偶像，仍以为所吃的是祭过偶像的食物；既然他们的良心软弱，也就污秽了。","notes":[]},{"n":8,"t":"其实，食物不能使我们更接近神，因为我们不吃也无损，吃也无益。","notes":[]},{"n":9,"t":"可是，你们要谨慎，免得你们这自由竟成了软弱人的绊脚石。","notes":[]},{"n":10,"t":"若有人见你这有知识的在偶像的庙里坐席，而这人的良心是软弱的，他岂不放胆去吃那祭过偶像的食物吗？","notes":[]},{"n":11,"t":"因此，基督为他死的那软弱弟兄，也就因你的知识沉沦了。","notes":[]},{"n":12,"t":"你们这样得罪弟兄，伤了他们软弱的良心，就是得罪基督。","notes":[]},{"n":13,"t":"所以，食物若使我的弟兄跌倒，我就永远不吃肉，免得使我的弟兄跌倒了。","notes":[]}]},"9":{"heading":"使徒的权利","verses":[{"n":1,"t":"我不是自由的吗？我不是使徒吗？我不是见过我们的主耶稣吗？你们不是我在主里面工作的成果吗？","notes":[]},{"n":2,"t":"假若对别人来说，我不是使徒，对你们来说，我总是使徒；因为你们在主里正是我作使徒的印证。","notes":[]},{"n":3,"t":"对那些质问我的人，这就是我的答辩。","notes":[]},{"n":4,"t":"难道我们没有权利靠着传福音吃喝吗？","notes":[]},{"n":5,"t":"难道我们没有权利带着信主的妻子一起出入，如同其余的使徒，和主的兄弟们，和矶法一样吗？","notes":[]},{"n":6,"t":"只有我和巴拿巴没有权利不做工吗？","notes":[]},{"n":7,"t":"有谁当兵而自备粮饷呢？有谁栽葡萄园而不吃园里的果子呢？有谁牧养牛羊而不喝牛羊的奶呢？","notes":[]},{"n":8,"t":"我说这些话岂是照一般人的看法？律法不也是这样说吗？","notes":[]},{"n":9,"t":"就如摩西的律法记着：“牛在踹谷的时候，不可笼住它的嘴。”难道神所挂念的是牛吗？","notes":[]},{"n":10,"t":"他不全是为我们说的吗？的确是为我们说的！因为耕种的要存着指望去耕种；收割的也要存着分享谷物的指望去收割。","notes":[]},{"n":11,"t":"我们既然把属灵的种子撒在你们中间，若从你们收取养生之物，这还算大事吗？","notes":[]},{"n":12,"t":"假如别人在你们身上享有这权利，何况我们呢？然而，我们并没有用过这权利，倒是凡事忍受，免得基督的福音受到阻碍。","notes":[]},{"n":13,"t":"你们岂不知在圣殿供职的人吃圣殿中的食物吗？在祭坛伺候的人分享坛上的供物吗？","notes":[]},{"n":14,"t":"主也是这样命令，要传福音的人靠着福音养生。","notes":[]},{"n":15,"t":"但这权利我全然没有用过。我写这些话，并非要你们这样待我，因为我宁可死也不让人使我所夸的落了空。","notes":[]},{"n":16,"t":"我传福音原没有可夸耀的，因为我是不得已的，若不传福音，我就有祸了。","notes":[]},{"n":17,"t":"我若甘心做这事，就有赏赐；若不甘心，责任却已经托付给我了。","notes":[]},{"n":18,"t":"这样，我的赏赐是什么呢？就是我传福音的时候，使人不花钱得福音，免得我用尽了传福音的权利。","notes":[]},{"n":19,"t":"我虽然是自由的，不受人管辖，但我甘心作了众人的仆人，为赢得更多的人。","notes":[]},{"n":20,"t":"对犹太人，我就作犹太人，为要赢得犹太人；对律法以下的人，我虽不在律法以下，还是作律法以下的人，为要赢得律法以下的人。","notes":[]},{"n":21,"t":"对没有律法的人，我就作没有律法的人，为要赢得没有律法的人；其实我在神面前，不是没有律法，而是在基督的律法之下。","notes":[]},{"n":22,"t":"对软弱的人，我就作软弱的人，为要赢得软弱的人。对什么样的人，我就作什么样的人。无论如何我总要救一些人。","notes":[]},{"n":23,"t":"凡我所做的，都是为福音的缘故，为要与人共享这福音的好处。","notes":[]},{"n":24,"t":"你们不知道在运动场上赛跑的，大家都跑，但得奖赏的只有一人？你们也要这样跑，好使你们得着奖赏。","notes":[]},{"n":25,"t":"凡参加竞赛的，在各方面都要有节制，他们不过是要得会朽坏的冠冕；我们却是要得不会朽坏的冠冕。","notes":[]},{"n":26,"t":"所以，我奔跑，不像无目标的；我斗拳，不像打空气的。","notes":[]},{"n":27,"t":"我克制己身，使它完全顺服，免得我传福音给别人，自己反而被淘汰了。","notes":[]}]},"10":{"heading":"警戒拜偶像","verses":[{"n":1,"t":"弟兄们，我不愿意你们不知道，我们的祖宗从前都在云下，都从海中经过，","notes":[]},{"n":2,"t":"都在云里、海里受洗归了摩西，","notes":["“受洗”：有古卷是“为自己施洗”。"]},{"n":3,"t":"并且都吃了一样的灵粮，","notes":[]},{"n":4,"t":"也都喝了一样的灵水，所喝的是出于跟随着他们的灵磐石；那磐石就是基督。","notes":[]},{"n":5,"t":"但他们中间多半是神不喜欢的人，所以倒毙在旷野里了。","notes":[]},{"n":6,"t":"这些事都是我们的鉴戒，使我们不要贪恋恶事，像他们贪恋过的一样。","notes":[]},{"n":7,"t":"也不要拜偶像，像他们中有些人曾经拜过。如经上所记：“百姓坐下吃喝，起来玩乐。”","notes":[]},{"n":8,"t":"我们也不可犯奸淫，像他们中有些人曾经犯过，一天就倒毙了二万三千人。","notes":[]},{"n":9,"t":"也不可试探主，像他们中有些人曾试探主就被蛇咬死。","notes":["“主”：有古卷是“基督”。"]},{"n":10,"t":"你们也不可发怨言，像他们中有些人曾经发过，就被毁灭者所灭。","notes":[]},{"n":11,"t":"这些事发生在他们身上，要作为鉴戒，而且写下来正是要警戒我们这末世的人。","notes":[]},{"n":12,"t":"所以，自以为站得稳的人必须谨慎，免得跌倒。","notes":[]},{"n":13,"t":"你们所受的考验无非是人所承受得了的。神是信实的，他不会让你们遭受无法承受的考验，在受考验的时候，总会给你们开一条出路，让你们能忍受得了。","notes":[]},{"n":14,"t":"所以，我亲爱的，你们要远避拜偶像的事。","notes":[]},{"n":15,"t":"我好像对精明人说的；你们要辨别我的话。","notes":[]},{"n":16,"t":"我们所祝谢的杯，岂不是同领基督的血吗？我们所擘开的饼，岂不是同领基督的身体吗？","notes":[]},{"n":17,"t":"因为饼只是一个，我们虽然人多，仍是一体，我们同享一个饼。","notes":[]},{"n":18,"t":"你们看那按肉体是以色列人的，那些吃祭物的人岂不是与祭坛有份吗？","notes":[]},{"n":19,"t":"那么，我怎么说呢？是说祭偶像之物算得了什么吗？或说偶像算得了什么吗？","notes":[]},{"n":20,"t":"不，我是说，他们所献的祭是祭鬼，不是祭神；我不愿意你们与鬼来往。","notes":["有古卷是“外邦人”。"]},{"n":21,"t":"你们不能喝主的杯，又喝鬼的杯；不能吃主的筵席，又吃鬼的筵席。","notes":[]},{"n":22,"t":"我们要惹主的嫉恨吗？我们比他更强吗？","notes":[]},{"n":23,"t":"“凡事都可行”，但不都有益处；“凡事都可行”，但不都造就人。","notes":[],"heads":["凡事为荣耀神而做"]},{"n":24,"t":"无论什么人，不要求自己的益处，而要求别人的益处。","notes":[]},{"n":25,"t":"凡市场上所卖的，你们只管吃，不要为良心的缘故问什么，","notes":[]},{"n":26,"t":"“因为地和其中所充满的都属于主”。","notes":[]},{"n":27,"t":"倘若有一个不信的人请你们吃饭，而你们也愿意去，凡摆在你们面前的，只管吃，不要为良心的缘故问什么。","notes":[]},{"n":28,"t":"若有人对你们说：“这是献过祭的物”，那么为了那告诉你们的人，并为了良心的缘故就不吃。","notes":[]},{"n":29,"t":"我说的良心不是你自己的，而是他的。我的自由为什么被别人的良心评断呢？","notes":[]},{"n":30,"t":"我若谢恩而吃，为什么因我谢恩的物被人毁谤呢？","notes":[]},{"n":31,"t":"所以，你们或吃或喝，无论做什么，都要为荣耀神而做。","notes":[]},{"n":32,"t":"你们不要使犹太人、希腊人，或神教会中的人跌倒；","notes":[]},{"n":33,"t":"但要像我一样，凡事都使众人喜欢，不求自己的益处，只求众人的益处，使他们得救。","notes":[]}]},"11":{"heading":"礼拜时蒙头的问题","verses":[{"n":1,"t":"你们该效法我，像我效法基督一样。","notes":[]},{"n":2,"t":"我称赞你们，因为你们凡事记得我，又坚守我所传授给你们的。","notes":[]},{"n":3,"t":"但是我要你们知道：基督是男人的头；男人是女人的头；神是基督的头。","notes":["“男人是女人的头”或译“丈夫是妻子的头”。"]},{"n":4,"t":"凡男人祷告或讲道，若蒙着头，就是羞辱自己的头。","notes":["“讲道”或译“说预言”；5节同。"]},{"n":5,"t":"凡女人祷告或讲道，若不蒙着头，就是羞辱自己的头，因为这就如同剃了头发一样。","notes":[]},{"n":6,"t":"女人若不蒙着头，就该剪了头发；女人若以剪发剃发为羞愧，就该蒙着头。","notes":[]},{"n":7,"t":"男人本不该蒙着头，因为他是神的形像和荣耀；但女人是男人的荣耀。","notes":[]},{"n":8,"t":"起初，男人不是由女人而出，女人却是由男人而出。","notes":[]},{"n":9,"t":"而且男人不是为女人造的，女人却是为男人造的。","notes":[]},{"n":10,"t":"因此，女人为天使的缘故应当在头上有服权柄的记号。","notes":[]},{"n":11,"t":"然而，照主的安排，女人不可没有男人，男人也不可没有女人。","notes":[]},{"n":12,"t":"因为女人原是由男人而出，男人是藉着女人而生；但万有都是出于神。","notes":[]},{"n":13,"t":"你们自己要判断，女人祷告神，不蒙着头合宜吗？","notes":[]},{"n":14,"t":"你们的本性不也教导你们，男人若留长头发是他的羞辱吗？","notes":[]},{"n":15,"t":"但女人留长头发是她的荣耀，因为这头发是给她盖头的。","notes":["“给她盖头的”：有古卷是“为盖头的”。"]},{"n":16,"t":"若有人想要辩驳，我们却没有这样的规矩，神的众教会也没有。","notes":[]},{"n":17,"t":"我现在吩咐你们这话不是在称赞你们，因为你们聚会是有损无益的。","notes":[],"heads":["妄用主的圣餐"]},{"n":18,"t":"首先，我听说你们教会聚会的时候有分裂的事，我也有些相信这话。","notes":[]},{"n":19,"t":"在你们中间必然有分门结党的事，好使那些经得起考验的人显明出来。","notes":[]},{"n":20,"t":"你们聚会的时候，不是在吃主的晚餐，","notes":[]},{"n":21,"t":"因为吃的时候，各人先吃自己的饭，甚至有人饥饿，有人酒醉。","notes":[]},{"n":22,"t":"难道你们没有家可以吃喝吗？还是你们藐视神的教会，使那没有的羞愧呢？我该对你们说什么呢？我要称赞你们吗？在这事上我绝不称赞你们！","notes":[]},{"n":23,"t":"我当日传给你们的是从主所领受的。主耶稣被出卖的那一夜，拿起饼来，","notes":[],"heads":["圣餐的设立"]},{"n":24,"t":"祝谢了，就擘开，说：“这是我的身体，为你们舍的；你们要如此行，为的是记念我。”","notes":["“舍”：有古卷是“擘开”。"]},{"n":25,"t":"饭后，他也照样拿起杯来，说：“这杯是用我的血所立的新约；你们每逢喝的时候，要如此行，来记念我。”","notes":[]},{"n":26,"t":"你们每逢吃这饼，喝这杯，是宣告主的死，直到他来。","notes":[]},{"n":27,"t":"所以，任何不按规矩吃了主的饼，喝了主的杯，就是干犯主的身体和主的血了。","notes":[],"heads":["圣餐前应省察自己"]},{"n":28,"t":"人应该省察自己，然后吃这饼，喝这杯。","notes":[]},{"n":29,"t":"因为人吃喝，若不分辨是主的身体，他的吃喝就是定自己的罪了。","notes":[]},{"n":30,"t":"因此，在你们中间有好些软弱的与患病的，长眠了的也不少。","notes":[]},{"n":31,"t":"我们若是先省察自己，就不至于受审判。","notes":[]},{"n":32,"t":"我们受审判的时候，就是被主管教，这样就免得和世人一同被定罪。","notes":[]},{"n":33,"t":"所以，我的弟兄们，你们聚会吃晚餐的时候，要彼此等待。","notes":[]},{"n":34,"t":"若有人饿了，要在家里先吃，免得你们聚会，反被定罪。其余的事等我来的时候再安排。","notes":[]}]},"12":{"heading":"属灵的恩赐","verses":[{"n":1,"t":"弟兄们，关于属灵的恩赐，我不愿意你们不明白。","notes":["“属灵的恩赐”或译“属灵的人”。"]},{"n":2,"t":"你们知道，你们作外邦人的时候，随事被引诱，受了迷惑去拜不会出声的偶像。","notes":[]},{"n":3,"t":"所以，我要你们知道，被神的灵感动的，没有人会说“耶稣该受诅咒”；若不是被圣灵感动的，也没有人能说“耶稣是主”。","notes":[]},{"n":4,"t":"恩赐有许多种，却是同一位圣灵所赐。","notes":[]},{"n":5,"t":"事奉有许多种，却是事奉同一位主。","notes":[]},{"n":6,"t":"工作有许多种，却是同一位神在万人中运行万事。","notes":[]},{"n":7,"t":"圣灵彰显在各人身上，是要使人得益处。","notes":[]},{"n":8,"t":"有人藉着圣灵领受智慧的言语；有人也靠着同一位圣灵领受知识的言语；","notes":[]},{"n":9,"t":"又有人由同一位圣灵领受信心；还有人由同一位圣灵领受医病的恩赐；","notes":[]},{"n":10,"t":"又有人能行异能，又有人能作先知，又有人能辨别诸灵，又有人能说方言，又有人能翻方言。","notes":["“方言”或译“灵语”；本节下同，28、30节同。"]},{"n":11,"t":"这一切都是由惟一的、同一位圣灵所运行，随着自己的旨意分给各人的。","notes":[]},{"n":12,"t":"就如身体是一个，却有许多肢体，身体的肢体虽多，仍是一个身体；基督也是这样。","notes":[],"heads":["一个身体有许多肢体"]},{"n":13,"t":"我们无论是犹太人是希腊人，是为奴的是自主的，都从一位圣灵受洗成了一个身体，并且共享这位圣灵。","notes":[]},{"n":14,"t":"身体原不只是一个肢体，而是许多肢体。","notes":[]},{"n":15,"t":"假如脚说：“我不是手，所以不属于身体”，它不能因此就不属于身体。","notes":[]},{"n":16,"t":"假如耳朵说：“我不是眼睛，所以不属于身体”，它也不能因此就不属于身体。","notes":[]},{"n":17,"t":"假如全身是眼睛，听觉在哪里呢？假如全身是耳朵，嗅觉在哪里呢？","notes":[]},{"n":18,"t":"但现在神随自己的意思把肢体一一安置在身体上了。","notes":[]},{"n":19,"t":"假如全都是一个肢体，身体在哪里呢？","notes":[]},{"n":20,"t":"但现在肢体虽多，身体还是一个。","notes":[]},{"n":21,"t":"眼睛不能对手说：“我用不着你。”头也不能对脚说：“我用不着你。”","notes":[]},{"n":22,"t":"不但如此，身上的肢体，人以为软弱的，更是不可缺少的；","notes":[]},{"n":23,"t":"身上的肢体，我们认为不体面的，越发给它加上体面；我们不雅观的，越发装饰得雅观。","notes":[]},{"n":24,"t":"我们雅观的肢体自然用不着装饰；但神配搭这身子，把加倍的体面给那有缺欠的肢体，","notes":[]},{"n":25,"t":"免得身体不协调，总要肢体彼此照顾。","notes":[]},{"n":26,"t":"假如一个肢体受苦，所有的肢体就一同受苦；假如一个肢体得光荣，所有的肢体就一同快乐。","notes":[]},{"n":27,"t":"你们是基督的身体，并且各自都是肢体。","notes":[]},{"n":28,"t":"神在教会所设立的：第一是使徒；第二是先知；第三是教师；其次是行异能的；再次是医病的恩赐，帮助人的，治理事的，说方言的。","notes":[]},{"n":29,"t":"难道个个都是使徒吗？难道个个都是先知吗？难道个个都是教师吗？难道个个都是行异能的吗？","notes":[]},{"n":30,"t":"难道个个都是有医病的恩赐吗？难道个个都是说方言的吗？难道个个都是翻方言的吗？","notes":[]},{"n":31,"t":"你们要追求那更大的恩赐。我现今把最妙的道指示你们。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"我若能说人间的方言，甚至天使的语言，却没有爱，我就成为鸣的锣、响的钹一般。","notes":[]},{"n":2,"t":"我若有先知讲道的能力，也明白各样的奥秘，各样的知识，而且有齐备的信心，使我能够移山，却没有爱，我就算不了什么。","notes":[]},{"n":3,"t":"我若将所有的财产救济穷人，又牺牲自己的身体让人夸赞，却没有爱，仍然对我无益。","notes":["“让人夸赞”：有古卷是“给人当作祭品焚烧”。"]},{"n":4,"t":"爱是恒久忍耐；又有恩慈；爱是不嫉妒；爱是不自夸，不张狂，","notes":[]},{"n":5,"t":"不做害羞的事，不求自己的益处，不轻易发怒，不计算人的恶，","notes":[]},{"n":6,"t":"不喜欢不义，只喜欢真理；","notes":[]},{"n":7,"t":"凡事包容，凡事相信，凡事盼望，凡事忍耐。","notes":[]},{"n":8,"t":"爱是永不止息。先知讲道之能终必归于无有；说方言之能终必停止；知识也终必归于无有。","notes":["“方言”或译“灵语”。"]},{"n":9,"t":"我们现在所知道的有限，先知所讲的也有限，","notes":[]},{"n":10,"t":"等那完全的来到，这有限的必消逝。","notes":[]},{"n":11,"t":"我作孩子的时候，说话像孩子，心思像孩子，意念像孩子；既长大成人，就把孩子的事丢弃了。","notes":[]},{"n":12,"t":"我们现在是对着镜子观看，模糊不清；到那时，就要面对面了。我如今所认识的有限，到那时就全认识，如同主认识我一样。","notes":["“模糊不清”：原文直译“如同猜谜”。"]},{"n":13,"t":"如今常存的有信，有望，有爱这三样，其中最大的是爱。","notes":[]}]},"14":{"heading":"说方言和作先知讲道","verses":[{"n":1,"t":"你们要追求爱，也要切慕属灵的恩赐，尤其是作先知讲道。","notes":["“先知讲道”：原文直译“说预言”；3节同。"]},{"n":2,"t":"那说方言的，不是对人说，而是对神说，因为没有人听得懂；他是藉着圣灵说各样的奥秘。","notes":["“方言”或译“灵语”；4、5、6、13、14、16、18、19、22、23、24、26、27、39节同。"]},{"n":3,"t":"但作先知讲道的，是对人说，要造就、安慰、劝勉人。","notes":[]},{"n":4,"t":"说方言的，是造就自己；作先知讲道的，是造就教会。","notes":[]},{"n":5,"t":"我希望你们都说方言，更希望你们作先知讲道；因为说方言的，若不解释出来，使教会得造就，那作先知讲道的就比他强了。","notes":[]},{"n":6,"t":"弟兄们，我到你们那里去，若只说方言，不用启示，或知识，或预言，或教导，给你们讲解，我对你们有什么益处呢？","notes":[]},{"n":7,"t":"就连那有声而没有生命的东西，如箫，如琴，发出来的音若没有分别，怎能知道所吹所弹的是什么呢？","notes":[]},{"n":8,"t":"号角吹出来的音若不清楚，谁会预备打仗呢？","notes":[]},{"n":9,"t":"你们也是如此；若用舌头说听不懂的信息，怎能知道所说的是什么呢？你们就是向空气说话了。","notes":[]},{"n":10,"t":"世上有许多种语言，却没有一样是无意思的。","notes":[]},{"n":11,"t":"我若不明白那语言的意思，说话的人必以我为未开化的人，我也以他为未开化的人。","notes":[]},{"n":12,"t":"你们也是如此，既然你们切慕属灵的恩赐，就当追求多得造就教会的恩赐。","notes":[]},{"n":13,"t":"所以，那说方言的，就当祈求有翻方言的恩赐。","notes":[]},{"n":14,"t":"我若用方言祷告，是我的灵在祷告；但我的理智没有效果。","notes":[]},{"n":15,"t":"我应该怎么做呢？我要用灵祷告，也要用理智祷告；我要用灵歌唱，也要用理智歌唱。","notes":[]},{"n":16,"t":"不然，你用灵祝谢，那在座不通方言的人，既然不明白你的话，怎能在你感谢的时候说“阿们”呢？","notes":[]},{"n":17,"t":"你的感谢固然是好，不过不能造就别人。","notes":[]},{"n":18,"t":"我感谢神，我说方言比你们众人还多；","notes":[]},{"n":19,"t":"但在教会中，我宁可用理智说五句教导人的话，强过说万句方言。","notes":[]},{"n":20,"t":"弟兄们，在心志上不要作小孩子。但是，在恶事上要作婴孩，而在心志上总要作大人。","notes":[]},{"n":21,"t":"律法上记着：“主说：我要用外邦人的舌头和外邦人的嘴唇向这百姓说话；虽然如此，他们还是不听从我。”","notes":[]},{"n":22,"t":"这样看来，说方言不是为信的人作标记，而是为不信的人；作先知讲道不是为不信的人作标记，而是为信的人。","notes":[]},{"n":23,"t":"所以，全教会聚在一处的时候，若都说方言，偶然有不通方言的或是不信的人进来，岂不会说你们疯了吗？","notes":[]},{"n":24,"t":"若个个都作先知讲道，偶然有不信的或是不懂方言的人进来，就被众人劝戒，被众人审问，","notes":[]},{"n":25,"t":"他心里的隐情被显露出来，就必将脸伏地，敬拜神，宣告说：“神真的是在你们中间了。”","notes":[]},{"n":26,"t":"弟兄们，那么，你们该怎么做呢？你们聚会的时候，各人或有诗歌，或有教导，或有启示，或有方言，或有翻出来，凡事都应当造就人。","notes":[],"heads":["凡事都要按次序行"]},{"n":27,"t":"若有说方言的，只可有两个人，至多三个人，且要轮流着说，也要有一个人翻出来。","notes":[]},{"n":28,"t":"若没有人翻，就当在会中闭口，只对自己和神说就是了。","notes":[]},{"n":29,"t":"至于作先知讲道的，只可有两个人或是三个人，其余的人当慎思明辨。","notes":[]},{"n":30,"t":"假如旁边坐着的得了启示，那先说话的就当闭口不言。","notes":[]},{"n":31,"t":"因为你们都可以一个一个地作先知讲道，使众人都可以学习，使众人都得劝勉。","notes":[]},{"n":32,"t":"先知的灵是顺服先知的，","notes":[]},{"n":33,"t":"因为神不是叫人混乱，而是叫人和谐的神。在圣徒的众教会中，","notes":[]},{"n":34,"t":"妇女应该闭口不言；因为，不准她们说话，总要顺服，正如律法所说的。","notes":[]},{"n":35,"t":"她们若要学什么，应该在家里问自己的丈夫，因为妇女在会中说话是可耻的。","notes":[]},{"n":36,"t":"难道神的话是从你们出来的吗？难道是单临到你们的吗？","notes":[]},{"n":37,"t":"若有人自以为是先知，或是属灵的，就应该知道，我所写给你们的是主的命令。","notes":[]},{"n":38,"t":"若有不理会的，你们也不必理会他。","notes":[]},{"n":39,"t":"所以，我的弟兄们，你们要切慕作先知讲道的恩赐，不要禁止说方言。","notes":[]},{"n":40,"t":"凡事都要规规矩矩地按着次序行。","notes":[]}]},"15":{"heading":"基督的复活","verses":[{"n":1,"t":"弟兄们，我要你们认清我先前传给你们的福音；这福音你们领受了，又靠着它站立得住，","notes":[]},{"n":2,"t":"你们若能够持守我传给你们的信息，就必因这福音得救，否则你们是徒然相信。","notes":[]},{"n":3,"t":"我当日所领受又传给你们的，最重要的就是：照圣经所说，基督为我们的罪死了，","notes":[]},{"n":4,"t":"而且埋葬了；又照圣经所说，第三天复活了，","notes":[]},{"n":5,"t":"还显给矶法看，又显给十二使徒看，","notes":[]},{"n":6,"t":"后来一次显给五百多弟兄看，其中一大半到现在还在，却也有已经睡了的。","notes":[]},{"n":7,"t":"以后他显给雅各看，再显给众使徒看，","notes":[]},{"n":8,"t":"最后也显给我看；我如同未到产期而生的人一般。","notes":[]},{"n":9,"t":"我原是使徒中最小的，不配称为使徒，因为我曾迫害过神的教会。","notes":[]},{"n":10,"t":"然而，由于神的恩典，我才成了今日的我，并且他所赐给我的恩典不是徒然的。我比众使徒格外劳苦；其实不是我，而是神的恩典与我同在。","notes":[]},{"n":11,"t":"无论是我或是其他使徒，我们都如此传，你们也都如此信了。","notes":[]},{"n":12,"t":"既然我们传基督是从死人中复活了，怎么在你们中间有人说没有死人复活的事呢？","notes":[],"heads":["死人的复活"]},{"n":13,"t":"若没有死人复活的事，基督就没有复活了。","notes":[]},{"n":14,"t":"基督若没有复活，我们所传的就是枉然，你们所信的也是枉然。","notes":[]},{"n":15,"t":"这样，我们甚至被当作是为神妄作见证的，因为我们见证神是使基督复活了。如果死人真的没有复活，神就没有使基督复活了。","notes":[]},{"n":16,"t":"因为死人若不复活，基督也就没有复活了。","notes":[]},{"n":17,"t":"基督若没有复活，你们的信就是徒然，你们仍活在罪里。","notes":[]},{"n":18,"t":"就是在基督里睡了的人也灭亡了。","notes":[]},{"n":19,"t":"我们若靠基督只在今生有指望，就比所有的人更可怜了。","notes":[]},{"n":20,"t":"其实，基督已经从死人中复活，成为睡了之人初熟的果子。","notes":[]},{"n":21,"t":"既然死是因一人而来，死人复活也因一人而来。","notes":[]},{"n":22,"t":"在亚当里众人都死了；同样，在基督里众人也都要复活。","notes":[]},{"n":23,"t":"但各人是按着自己的次序复活：初熟的果子是基督；然后在他来的时候，是那些属于基督的。","notes":[]},{"n":24,"t":"再后，终结到了，那时基督既将一切执政的、掌权的、有权能的都毁灭了，就把国交给父神。","notes":[]},{"n":25,"t":"因为基督必须掌权，等神把一切仇敌都放在他的脚下。","notes":[]},{"n":26,"t":"他要毁灭的最后仇敌就是死亡。","notes":[]},{"n":27,"t":"因为经上说：“神使万物都服在他的脚下。”既然说万物都服了他，那使万物屈服的，很明显地是不在其内了。","notes":[]},{"n":28,"t":"既然万物服了他，那时，子也要自己顺服那叫万物服他的，好使神在万物之中，在万物之上。","notes":[]},{"n":29,"t":"不然，那些为死人受洗的，能做什么呢？如果死人不会复活，为什么替他们受洗呢？","notes":[]},{"n":30,"t":"我们为什么要时刻冒险呢？","notes":[]},{"n":31,"t":"弟兄们，我在我们的主基督耶稣里，指着你们—我所夸的极力地说，我天天冒死。","notes":["有古卷没有“弟兄们”。"]},{"n":32,"t":"从人的观点看来，我当日在以弗所同野兽搏斗，对我有什么益处呢？如果死人没有复活，“让我们吃吃喝喝吧！因为明天要死了。”","notes":[]},{"n":33,"t":"不要被欺骗了；“滥交朋友败坏品德。”","notes":[]},{"n":34,"t":"你们要醒悟为善，不再犯罪；因为有人不认识神。我说这话是要使你们羞愧。","notes":[]},{"n":35,"t":"但是有人会问：“死人怎样复活呢？他们带着什么身体来呢？”","notes":[],"heads":["复活的身体"]},{"n":36,"t":"无知的人哪，你所种的若不死就不能生。","notes":[]},{"n":37,"t":"并且你所种的不是那将来要有的形体，无论是麦子或别样谷物，都不过是子粒。","notes":[]},{"n":38,"t":"但神随自己的意思给它一个形体，并叫各样子粒各有自己的形体。","notes":[]},{"n":39,"t":"不是所有的肉体都是同样的：人是一个样子，兽又是一个样子，鸟又是一个样子，鱼又是一个样子。","notes":[]},{"n":40,"t":"有天上的形体，也有地上的形体；但天上形体的荣光是一个样子，地上形体的荣光又是一个样子。","notes":[]},{"n":41,"t":"日有日的光辉，月有月的光辉，星有星的光辉；这星和那星的光辉也有区别。","notes":[]},{"n":42,"t":"死人复活也是这样。所种的是会朽坏的，复活的是不朽坏的；","notes":[]},{"n":43,"t":"所种的是羞辱的，复活的是荣耀的；所种的是软弱的，复活的是强壮的；","notes":[]},{"n":44,"t":"所种的是血肉的身体，复活的是灵性的身体。既有血肉的身体，也就有灵性的身体。","notes":[]},{"n":45,"t":"经上也是这样记着说：“首先的人亚当成了有生命的人”；末后的亚当成了赐生命的灵。","notes":[]},{"n":46,"t":"但是，不是属灵的在先，而是属血肉的在先，然后才是属灵的。","notes":[]},{"n":47,"t":"第一个人是出于地，是属于尘土；第二个人是出于天。","notes":[]},{"n":48,"t":"那属尘土的怎样，凡属尘土的也都怎样；属天的怎样，凡属天的也都怎样。","notes":[]},{"n":49,"t":"就如我们既有属尘土的形像，将来也必有属天的形像。","notes":[]},{"n":50,"t":"弟兄们，我要告诉你们的是：血肉之躯不能承受神的国，必朽坏的也不能承受不朽坏的。","notes":[]},{"n":51,"t":"我如今把一件奥秘的事告诉你们：我们不是都要睡觉，而是都要改变，","notes":[]},{"n":52,"t":"就在一刹那，眨眼之间，号筒末次吹响的时候。因号筒要吹响，死人要复活成为不朽坏的，我们也要改变。","notes":[]},{"n":53,"t":"这会朽坏的必须变成不朽坏的；这会死的总要变成不会死的。","notes":["“变成”：原文直译“穿”；下同。"]},{"n":54,"t":"当这会朽坏的变成不朽坏的，这会死的变成不会死的，那时经上所记“死亡已被胜利吞灭了”的话就应验了。","notes":[]},{"n":55,"t":"“死亡啊！你得胜的权势在哪里？死亡啊！你的毒刺在哪里？”","notes":[]},{"n":56,"t":"死亡的毒刺就是罪，罪的权势就是律法。","notes":[]},{"n":57,"t":"感谢神，他使我们藉着我们的主耶稣基督得胜。","notes":[]},{"n":58,"t":"所以，我亲爱的弟兄们，你们务要坚固，不可动摇，常常竭力多做主工，因为你们知道，你们在主里的劳苦不是徒然的。","notes":[]}]},"16":{"heading":"捐助圣徒","verses":[{"n":1,"t":"关于为圣徒捐款的事，我从前怎样吩咐加拉太的众教会，你们也该怎样做。","notes":[]},{"n":2,"t":"每逢七日的第一日，每人要照自己的收入抽出若干，保留起来，免得我来的时候现凑。","notes":[]},{"n":3,"t":"等到我来了，你们写信举荐谁，我就差遣他们，把你们的款项送到耶路撒冷去。","notes":[]},{"n":4,"t":"如果我也该去，他们可以和我同去。","notes":[]},{"n":5,"t":"我想穿越马其顿；我经过了马其顿后，就到你们那里去，","notes":[],"heads":["行程的计划"]},{"n":6,"t":"可能会和你们同住一些时候，甚至和你们一起过冬。这样无论我往哪里去，你们可以给我送行。","notes":[]},{"n":7,"t":"我现在不愿意在路过的时候见你们；主若允许，我就指望和你们同住一些时候。","notes":[]},{"n":8,"t":"不过我要仍旧住在以弗所，直到五旬节，","notes":[]},{"n":9,"t":"因为有又宽大又有效的门为我开了，虽然反对的人也多。","notes":[]},{"n":10,"t":"若是提摩太来到，你们要留心照顾他，使他在你们那里无所惧怕，因为他做主的工作像我一样。","notes":[]},{"n":11,"t":"所以，无论谁都不可藐视他。只要送他平安前行，让他到我这里来，因为我等着他和弟兄们同来。","notes":[]},{"n":12,"t":"至于亚波罗弟兄，我再三劝他同弟兄们到你们那里去；但现在他绝不愿意去，等有机会他就会去。","notes":[]},{"n":13,"t":"你们要警醒，在信仰上要站稳，要勇敢，要刚强。","notes":[],"heads":["最后的请求和问安"]},{"n":14,"t":"你们所做的一切都要凭爱心而做。","notes":[]},{"n":15,"t":"弟兄们，你们知道司提法那一家，是亚该亚初结的果子；他们专以服事圣徒为念。","notes":[]},{"n":16,"t":"我劝你们顺服这样的人，和一切与他同工同劳的人。","notes":[]},{"n":17,"t":"司提法那、福徒拿都和亚该古到这里来，我很高兴，因为他们补上了你们不在我身边的遗憾。","notes":[]},{"n":18,"t":"他们使我和你们心里都快慰；这样的人，你们务要敬重。","notes":[]},{"n":19,"t":"亚细亚的众教会向你们问安。亚居拉、百基拉，和在他们家里的教会，在主里热切地向你们问安。","notes":[]},{"n":20,"t":"众弟兄都向你们问安。要用圣洁的吻彼此问安。","notes":[]},{"n":21,"t":"我—保罗亲笔问安。","notes":[]},{"n":22,"t":"若有人不爱主，这人该受诅咒。主啊，愿你来！","notes":[]},{"n":23,"t":"愿主耶稣基督的恩常与你们众人同在。","notes":[]},{"n":24,"t":"我在基督耶稣里的爱与你们同在！","notes":["有古卷加“阿们！”"]}]}},"2CO":{"1":{"heading":"问候","verses":[{"n":1,"t":"奉神旨意作基督耶稣使徒的保罗和弟兄提摩太，写信给在哥林多神的教会和全亚该亚的众圣徒。","notes":[]},{"n":2,"t":"愿恩惠、平安从我们的父神和主耶稣基督归给你们！","notes":["“平安”或译“和平”。"]},{"n":3,"t":"愿颂赞归于神—我们主耶稣基督的父；他是发慈悲的父，赐各样安慰的神。","notes":[]},{"n":4,"t":"我们在一切患难中，他安慰我们，使我们能用神所赐的安慰去安慰那些遭各样患难的人。","notes":[]},{"n":5,"t":"正如我们跟基督同受许多苦楚，我们也靠基督得许多安慰。","notes":[]},{"n":6,"t":"如果我们受患难，那是为使你们得安慰，得拯救；如果我们得安慰，那也是为使你们得安慰，这安慰能使你们忍受我们所受同样的苦楚。","notes":[]},{"n":7,"t":"我们为你们所存的盼望是确定的，因为知道你们分担了我们的痛苦，也要分享我们的安慰。","notes":[]},{"n":8,"t":"弟兄们，我们不要你们不知道，我们从前在亚细亚遭遇苦难，因受到无法忍受的压力，甚至连活命的指望都没有了。","notes":[]},{"n":9,"t":"自己心里也断定是必死无疑，这是要使我们不依靠自己，只依靠使死人复活的神。","notes":[]},{"n":10,"t":"他曾救我们脱离那极大的死亡，他要继续救我们，而且我们指望他将来还要救我们。","notes":[]},{"n":11,"t":"你们也要一同用祈祷来帮助我们，好使许多人为我们感恩，因着他们许多的祷告，我们获得了恩赐。","notes":[]},{"n":12,"t":"我们所夸的是：我们在世为人，特别是跟你们的关系，是凭着神所赐的坦率和真诚，不是靠人的聪明，而是靠神的恩惠；这是我们的良心可以作证的。","notes":[],"heads":["保罗延期访问哥林多"]},{"n":13,"t":"我们现在写给你们的话，无非是你们所能诵读、所能明白的，我也盼望你们真能彻底明白。","notes":[]},{"n":14,"t":"你们已经有几分认识我们，在我们主耶稣的日子，你们会以我们为荣，正像我们也以你们为荣。","notes":["“主耶稣”：有古卷是“主”。"]},{"n":15,"t":"既然我这样深信，早就有意先到你们那里去，让你们得加倍的益处。","notes":[]},{"n":16,"t":"我要路过你们那里往马其顿去，再从马其顿回到你们那里，让你们给我送行往犹太去。","notes":[]},{"n":17,"t":"我有此意，难道是反覆不定吗？难道我的意愿是从私欲起的，以致我忽是忽非吗？","notes":[]},{"n":18,"t":"我指着信实的神说，我们向你们所传的道并非又是又非的。","notes":[]},{"n":19,"t":"因为，我、西拉和提摩太在你们中间传神的儿子耶稣基督，从没有“又是又非”的；在他只有一个“是”。","notes":[]},{"n":20,"t":"神的应许，不论有多少，在基督都是“是”的。所以，我们藉着他说“阿们”，使神因我们得荣耀。","notes":[]},{"n":21,"t":"那在基督里坚固我们和你们，并且膏抹我们的，就是神。","notes":[]},{"n":22,"t":"他在我们身上盖了印，并赐圣灵在我们心里作凭据。","notes":[]},{"n":23,"t":"我指着我的性命求告神作证，我没有再往哥林多去是为了要宽容你们。","notes":[]},{"n":24,"t":"我们并不是要控制你们的信心，而是要作你们的同工，让你们得快乐，因为你们在信仰上已经站得稳了。","notes":[]}]},"2":{"heading":"赦免犯过失的人","verses":[{"n":1,"t":"我自己定了主意，下次不再带着悲伤到你们那里去。","notes":[]},{"n":2,"t":"我若使你们悲伤，除了因我而使他悲伤的那人以外，谁能使我喜乐呢？","notes":[]},{"n":3,"t":"我曾把这事写给你们，免得我到的时候，那该令我喜乐的人反倒令我悲伤。我也深信，你们众人都以我的喜乐为自己的喜乐。","notes":[]},{"n":4,"t":"我先前忧心忡忡、眼泪汪汪地给你们写了信，并非要使你们悲伤，而是要你们知道我格外疼爱你们。","notes":[]},{"n":5,"t":"如果有人使人悲伤，他不但使我悲伤，也是使你们众人有些悲伤。我说有些，恐怕说得太重了。","notes":[]},{"n":6,"t":"这样的人受了大多数人的责备也就够了，","notes":[]},{"n":7,"t":"倒不如赦免他，安慰他，免得他过分悲伤，甚至受不了啦！","notes":[]},{"n":8,"t":"所以，我劝你们，要向他肯定你们的爱心。","notes":[]},{"n":9,"t":"为此，我先前也写信给你们，正是要考验你们，看你们是否在一切事上都顺从我。","notes":[]},{"n":10,"t":"你们赦免谁，我也赦免谁。我若有所赦免，是在基督面前为你们的缘故赦免的，","notes":[]},{"n":11,"t":"免得撒但趁着机会胜过我们，因我们并非不知道他的诡计。","notes":[]},{"n":12,"t":"我从前为基督的福音到了特罗亚，主给我开了门。","notes":[],"heads":["保罗的不安和安慰"]},{"n":13,"t":"那时，因为没有遇见我的弟兄提多，我心里不安，就辞别那里的人，往马其顿去了。","notes":[]},{"n":14,"t":"感谢神！他常率领我们在基督里得胜，并藉着我们在各处显扬那因认识基督而有的香气。","notes":[]},{"n":15,"t":"因为无论在得救的人或在灭亡的人当中，我们都是基督馨香之气，是献给神的。","notes":[]},{"n":16,"t":"对灭亡的人，这是死而又死的气味；对得救的人，这是生而又生的气味。这些事谁能当得起呢？","notes":[]},{"n":17,"t":"我们不像许多人，把神的道当商品贩卖，而是由于真诚，而是受命于神，在神面前凭着基督讲道。","notes":[]}]},"3":{"heading":"新约的执事","verses":[{"n":1,"t":"难道我们又开始推荐自己吗？难道我们像某些人那样要用人的推荐信介绍给你们，或用你们的推荐信给人吗？","notes":[]},{"n":2,"t":"你们就是我们的推荐信，写在我们心里，被众人所知道、所诵读的，","notes":[]},{"n":3,"t":"而你们显明自己是基督的书信，藉着我们写成的。不是用墨写的，而是用永生神的灵写的；不是写在石版上，而是写在心版上的。","notes":[]},{"n":4,"t":"我们藉着基督才对神有这样的信心。","notes":[]},{"n":5,"t":"并不是我们凭自己配做什么事，我们之所以配做是出于神；","notes":[]},{"n":6,"t":"他使我们能配作新约的执事，不是文字上的约，而是圣灵的约；因为文字使人死，圣灵能使人活。","notes":[]},{"n":7,"t":"那用字刻在石头上属死的事奉尚且有荣光，以致以色列人因摩西脸上那逐渐褪色的荣光不能定睛看他的脸，","notes":[]},{"n":8,"t":"那属圣灵的事奉不是更有荣光吗？","notes":[]},{"n":9,"t":"若是那使人定罪的事奉有荣光，那使人称义的事奉的荣光就越发大了。","notes":[]},{"n":10,"t":"那从前有荣光的，因这更大的荣光，就算不得有荣光了；","notes":[]},{"n":11,"t":"若是那逐渐褪色的有荣光，这长存的就更有荣光了。","notes":[]},{"n":12,"t":"既然我们有这样的盼望，就大有胆量，","notes":[]},{"n":13,"t":"不像摩西将面纱蒙在脸上，使以色列人不能定睛看到那逐渐褪色的荣光的结局。","notes":[]},{"n":14,"t":"但他们的心地刚硬，直到今日诵读旧约的时候，这同样的面纱还没有揭去；因为这面纱在基督里才被废去。","notes":[]},{"n":15,"t":"然而直到今日，每逢诵读摩西书的时候，面纱还在他们心上。","notes":[]},{"n":16,"t":"但他们的心何时归向主，面纱就何时除去。","notes":[]},{"n":17,"t":"主就是那灵；主的灵在哪里，哪里就有自由。","notes":[]},{"n":18,"t":"既然我们众人以揭去面纱的脸得以看见主的荣光，好像从镜子里返照，就变成了与主有同样的形像，荣上加荣，如同从主的灵变成的。","notes":["“看见”或译“反映”。","“从主的灵”或译“从主，就是灵”。"]}]},"4":{"heading":"瓦器里的宝贝","verses":[{"n":1,"t":"所以，既然我们蒙怜悯受了这事奉的责任，就不丧胆，","notes":[]},{"n":2,"t":"反而把那些暗昧可耻的事弃绝了，不行诡诈，不曲解神的道，只将真理显扬出来，好在神面前把自己推荐给各人的良心。","notes":[]},{"n":3,"t":"即使我们的福音被遮蔽，那只是对灭亡的人遮蔽。","notes":[]},{"n":4,"t":"这些不信的人被这世界的神明弄瞎了心眼，使他们看不见基督荣耀的福音。基督本是神的像。","notes":[]},{"n":5,"t":"我们不是传自己，而是传耶稣基督为主，并且自己因耶稣作你们的仆人。","notes":[]},{"n":6,"t":"那吩咐光从黑暗里照出来的神已经照在我们心里，使我们知道神荣耀的光显在耶稣基督的脸上。","notes":[]},{"n":7,"t":"我们有这宝贝放在瓦器里，为要显明这莫大的能力是出于神，不是出于我们。","notes":[]},{"n":8,"t":"我们处处受困，却不被捆住；内心困扰，却没有绝望；","notes":[]},{"n":9,"t":"遭受迫害，却不被撇弃；击倒在地，却不致灭亡。","notes":[]},{"n":10,"t":"我们身上常带着耶稣的死，使耶稣的生也在我们身上显明。","notes":[]},{"n":11,"t":"因为我们这活着的人常为耶稣被置于死地，使耶稣的生命在我们这必死的人身上显明出来。","notes":[]},{"n":12,"t":"这样看来，死是在我们身上运作，生却在你们身上运作。","notes":[]},{"n":13,"t":"但我们既然有从同一位灵而来的信心，正如经上记着：“我信，故我说话”，我们也信，所以也说话；","notes":[]},{"n":14,"t":"因为知道，那使主耶稣复活的也必使我们与耶稣一同复活，并且使我们与你们一起站在他面前。","notes":[]},{"n":15,"t":"凡事都是为了你们，好使恩惠既藉着更多的人而加增，感恩也格外显多，好归荣耀给神。","notes":[]},{"n":16,"t":"所以，我们不丧胆。虽然我们外在的人日渐朽坏，内在的人却日日更新。","notes":[],"heads":["靠信心生活"]},{"n":17,"t":"我们这短暂而轻微的苦楚要为我们成就极重、无比、永远的荣耀。","notes":[]},{"n":18,"t":"因为我们不是顾念看得见的，而是顾念看不见的；原来看得见的是暂时的，看不见的才是永远的。","notes":[]}]},"5":{"heading":"劝人与神和好的职分","verses":[{"n":1,"t":"因为我们知道，我们这地上的帐篷若拆毁了，我们将有神所造的居所，不是人手所造的，而是在天上永存的。","notes":[]},{"n":2,"t":"我们在这帐篷里叹息，渴望得到那从天上来的居所，好像穿上衣服；","notes":[]},{"n":3,"t":"倘若脱下也不至于赤身了。","notes":["有古卷是“倘若穿上就”。"]},{"n":4,"t":"其实，我们在这帐篷里的人劳苦叹息，并不是愿意脱下地上的帐篷，而是愿意穿上天上的居所，好使这必死的被生命吞灭了。","notes":[]},{"n":5,"t":"那为我们安排这事的是神，他赐给我们圣灵作凭据。","notes":["“凭据”：原文直译“质”。"]},{"n":6,"t":"所以，我们总是勇敢的，并且知道，只要我们住在这身体内就是离开了主。","notes":[]},{"n":7,"t":"因为我们行事为人是凭着信心，不是凭着眼见。","notes":[]},{"n":8,"t":"我们勇敢，更情愿离开身体，与主同住。","notes":[]},{"n":9,"t":"所以，无论是住在身内或住在身外，我们都立了志向要得主的喜悦。","notes":[]},{"n":10,"t":"因为我们众人必须站在基督审判台前受审，为使各人按着本身所行的，或善或恶受报。","notes":[]},{"n":11,"t":"既然我们知道主是可畏的，就劝导人；但是神是认识我们的，我盼望你们的良心也认识我们。","notes":[]},{"n":12,"t":"我们不是向你们再推荐自己，而是要让你们有夸耀我们的机会，使你们好面对那凭外貌、不凭内心夸耀的人。","notes":[]},{"n":13,"t":"如果我们癫狂，是为神；如果我们清醒，是为你们。","notes":[]},{"n":14,"t":"原来基督的爱激励我们；因我们这样断定，一人既替众人死，众人就都死了；","notes":[]},{"n":15,"t":"并且他替众人死，是叫那些活着的人不再为自己活，乃为替他们死而复活的主活。","notes":[]},{"n":16,"t":"所以，从今以后，我们不再按照人的看法来认识人，纵使我们曾经按照人的看法认识基督，如今却不再这样认识他了。","notes":[]},{"n":17,"t":"所以，若有人在基督里，他就是新造的人，旧事已过，都变成新的了。","notes":[]},{"n":18,"t":"一切都是出于神；他藉着基督使我们与他和好，又将劝人与他和好的使命赐给我们。","notes":[]},{"n":19,"t":"这就是：神在基督里使世人与自己和好，不将他们的过犯归到他们身上，并且将这和好的信息托付了我们。","notes":[]},{"n":20,"t":"所以，我们作基督的特使，就好像神藉我们劝你们一般。我们替基督求你们，与神和好吧！","notes":[]},{"n":21,"t":"神使那无罪的，替我们成为罪，好使我们在他里面成为神的义。","notes":["“无罪”：原文直译“不知罪”。"]}]},"6":{"heading":"永生神的殿","verses":[{"n":1,"t":"我们与神同工的也劝你们，不可白受他的恩典；","notes":[]},{"n":2,"t":"因为他说：“在悦纳的时候，我应允了你；在拯救的日子，我帮助了你。”看哪，现在正是悦纳的时候！看哪，现在正是拯救的日子！","notes":[]},{"n":3,"t":"我们不在任何事上妨碍任何人，免得这使命被人毁谤；","notes":[]},{"n":4,"t":"反倒在各样的事上表明自己是神的用人：就如在持久的忍耐、患难、困苦、灾难、","notes":[]},{"n":5,"t":"鞭打、监禁、动乱、劳碌、失眠、饥饿、","notes":[]},{"n":6,"t":"廉洁、知识、坚忍、恩慈、圣灵的感化、无伪的爱心、","notes":[]},{"n":7,"t":"真实的言语、神的大能、藉着仁义的兵器在左在右、","notes":[]},{"n":8,"t":"荣誉或羞辱、恶名或美名。我们似乎是诱惑人的，却是诚实的；","notes":[]},{"n":9,"t":"似乎不为人所知，却是人所共知；似乎是死了，却是活着；似乎受惩罚，却没有被处死；","notes":[]},{"n":10,"t":"似乎忧愁，却常有喜乐；似乎贫穷，却使许多人富足；似乎一无所有，却样样都有。","notes":[]},{"n":11,"t":"哥林多人哪，我们对你们，口是诚实的，心是宽宏的。","notes":[]},{"n":12,"t":"你们的狭窄不是由于我们，而是由于你们自己的心肠狭窄。","notes":[]},{"n":13,"t":"你们也要照样用宽宏的心报答我；我这话正像对自己的孩子说的。","notes":[]},{"n":14,"t":"你们不要和不信的人同负一轭。义和不义有什么相关？光明和黑暗有什么相连？","notes":[]},{"n":15,"t":"基督和彼列有什么相和？信主的和不信主的有什么相干？","notes":["“彼列”是撒但的别名。"]},{"n":16,"t":"神的殿和偶像有什么相同？因为我们是永生神的殿，就如神曾说：“我要在他们中间居住来往；我要作他们的神，他们要作我的子民。”","notes":[]},{"n":17,"t":"所以主说：“你们务要从他们中间出来，跟他们分别；不要沾不洁净的东西，我就收纳你们。","notes":[]},{"n":18,"t":"我要作你们的父，你们要作我的儿女。这是全能的主说的。”","notes":[]}]},"7":{"heading":"保罗为教会悔改而欢喜","verses":[{"n":1,"t":"所以，亲爱的，既然我们有这样的应许，就当洁净自己，除去身体和灵魂一切的污秽，藉着敬畏神，得以成圣。","notes":[]},{"n":2,"t":"宽宏大量地接纳我们吧！我们未曾亏负谁，未曾败坏谁，未曾占谁的便宜。","notes":[]},{"n":3,"t":"我说这话，不是要定你们的罪，我已经说过，你们常在我们心里，我们情愿与你们同生共死。","notes":[]},{"n":4,"t":"我对你们很是放心，多多夸耀你们；我满有安慰，在我们一切患难中格外喜乐。","notes":[]},{"n":5,"t":"我们从前到了马其顿的时候，身体没有丝毫安宁，反而到处遭患难，外有纷争，内有惧怕。","notes":[]},{"n":6,"t":"但那安慰灰心之人的神藉着提多来安慰了我们；","notes":[]},{"n":7,"t":"不但藉着他来，也藉着他从你们所得的安慰，安慰了我们，因为他把你们的思念，你们的哀恸，你们对我的热忱，都告诉了我，使我更加欢喜。","notes":[]},{"n":8,"t":"即使我先前那封信使你们忧愁，后来我曾懊悔，如今却不懊悔；因为我知道，那封信使你们忧愁，不过是暂时的。","notes":[]},{"n":9,"t":"如今我欢喜，不是因你们曾忧愁，而是因忧愁导致你们的悔改。你们依着神的意思忧愁，凡事就不至于因我们受亏损了。","notes":[]},{"n":10,"t":"因为依着神的意思而忧愁，就生出没有懊悔的悔改来，以致得救；但世俗的忧愁叫人死。","notes":[]},{"n":11,"t":"你看，你们依着神的意思而忧愁，这在你们当中产生了何等的殷勤、甚至辩白、甚至愤慨、甚至恐惧、甚至渴望、甚至热忱、甚至责罚。在这一切事上，你们都表明自己是无可指责的。","notes":[]},{"n":12,"t":"所以，虽然我从前写信给你们，却不是为那亏负人的，也不是为那受人亏负的，而是要在神面前把你们顾念我们的热忱表现出来。","notes":[]},{"n":13,"t":"因此，我们得了安慰。在我们所得的安慰之外，又因你们众人使提多心里畅快喜乐，我们就更加欢喜了。","notes":[]},{"n":14,"t":"我若对提多夸奖过你们什么，也不觉得惭愧，因为我对提多夸奖你们的话是真的，正如我对你们所说的话也向来都是真的。","notes":[]},{"n":15,"t":"提多一想起你们众人的顺服，怎样恐惧战兢地接待他，他爱你们的心就越发热切了。","notes":[]},{"n":16,"t":"我如今欢喜，因为我在一切事上对你们有信心。","notes":[]}]},"8":{"heading":"慷慨的捐助","verses":[{"n":1,"t":"弟兄们，我们要把神赐给马其顿众教会的恩惠告诉你们：","notes":[]},{"n":2,"t":"他们在患难中受大考验的时候，仍然满有喜乐，在极度贫穷中还格外显出他们乐捐的慷慨。","notes":[]},{"n":3,"t":"我可以证明，他们是按着能力，而且超过了能力来捐助，主动","notes":[]},{"n":4,"t":"再三恳求我们，准他们在这供给圣徒的善事上有份；","notes":[]},{"n":5,"t":"并且他们所做的，不但照我们所期望的，更照神的旨意先把自己献给主，又给了我们。","notes":[]},{"n":6,"t":"因此，我们劝提多，既然在你们中间开始这慈善的事，就当把它办成。","notes":[]},{"n":7,"t":"既然你们在信心、口才、知识、万分的热忱，以及我们对你们的爱心上，都胜人一等，那么，当在这慈善的事上也要胜人一等。","notes":["有古卷是“你们对我们”。"]},{"n":8,"t":"我说这话，并不是命令你们，而是藉着别人的热忱来考验你们爱心的真诚。","notes":[]},{"n":9,"t":"你们知道我们主耶稣基督的恩典：他本是富足，却为你们成了贫穷，好使你们因他的贫穷而成为富足。","notes":[]},{"n":10,"t":"我在这事上把我的意见告诉你们，是对你们有益，因为你们开始办这事，而且起此心意已经有一年了。","notes":[]},{"n":11,"t":"如今就当办成这事，既然有愿做的心，也当照你们所有的去办成。","notes":[]},{"n":12,"t":"因为人只要有愿做的心，必照他所有的蒙悦纳，并不是照他所没有的。","notes":[]},{"n":13,"t":"我不是要别人轻松，你们受累，而是要均匀：","notes":[]},{"n":14,"t":"就是要你们现在的富余补他们的不足，使他们的富余将来也可以补你们的不足，这就均匀了。","notes":[]},{"n":15,"t":"如经上所记：多收的没有余，少收的也没有缺。","notes":[]},{"n":16,"t":"感谢神，把我对你们的热忱同样放在提多心里。","notes":[],"heads":["提多和他的同工"]},{"n":17,"t":"他固然听了我的劝告，但自己更加热心，自愿往你们那里去。","notes":[]},{"n":18,"t":"我们还差遣一位弟兄和他同去，这人在传福音的事上得了众教会的称赞；","notes":[]},{"n":19,"t":"不但这样，他也被众教会选派跟我们同行，把所交托我们的这捐款送到了，为的是荣耀主，也表明我们的好意。","notes":[]},{"n":20,"t":"我们这样做，免得有人因我们收的捐款多而挑剔我们。","notes":[]},{"n":21,"t":"我们留心做好事，不但在主面前，就是在人面前也是这样。","notes":[]},{"n":22,"t":"我们又差遣一位弟兄同去。这人的热忱，我们在许多事上屡次考验过，现在他因为深深信任你们，就更加热心了。","notes":[]},{"n":23,"t":"至于提多，他是我的伙伴，为服事你们作我的同工。至于那两位弟兄，他们是众教会的使者，是基督的荣耀。","notes":[]},{"n":24,"t":"所以，你们务要在众教会面前向他们显明你们的爱心和我所夸奖你们的凭据。","notes":[]}]},"9":{"heading":"帮助圣徒的捐款","verses":[{"n":1,"t":"关于供给圣徒的事，我本来不必写信给你们；","notes":[]},{"n":2,"t":"因为我知道你们的好意，常对马其顿人夸奖你们，说亚该亚人预备好已经有一年了。你们的热心感动了许多人。","notes":[]},{"n":3,"t":"但我差遣那几位弟兄去，要使你们照我的话预备妥当，免得我们在这事上夸奖你们的话落了空。","notes":[]},{"n":4,"t":"万一有马其顿人与我同去，见你们没有预备好，就使我们所确信的反成了羞愧；你们的羞愧更不用说了。","notes":[]},{"n":5,"t":"因此，我想必须鼓励那几位弟兄先到你们那里去，把从前所应许的捐款预备妥当，好显出你们所捐的是出于乐意，不是出于勉强。","notes":[]},{"n":6,"t":"还有一点：“少种的少收；多种的多收。”","notes":[]},{"n":7,"t":"各人要随心所愿，不要为难，不要勉强，因为神爱乐捐的人。","notes":[]},{"n":8,"t":"神能将各样的恩惠多多加给你们，使你们凡事常常充足，能多做各样善事。","notes":[]},{"n":9,"t":"如经上所记：“他施舍，周济贫穷；他的义行存到永远。”","notes":[]},{"n":10,"t":"那赐种子给撒种的，赐粮食给人吃的，必多多加给你们种地的种子，又增添你们仁义的果子。","notes":[]},{"n":11,"t":"你们必凡事富足，能多多施舍，使人藉着我们而生感谢神的心。","notes":[]},{"n":12,"t":"因为办这供给的事，不但补圣徒的缺乏，而且使许多人对神充满更多的感谢。","notes":[]},{"n":13,"t":"他们从这供给的事上得了凭据，知道你们宣认基督，顺服他的福音，慷慨捐助给他们和众人，把荣耀归给神。","notes":[]},{"n":14,"t":"他们也因神极大的恩赐显在你们身上而切切想念你们，为你们祈祷。","notes":[]},{"n":15,"t":"感谢神，因他有说不尽的恩赐！","notes":[]}]},"10":{"heading":"保罗为自己的工作辩护","verses":[{"n":1,"t":"我－保罗与你们见面的时候是温和的，不在你们那里的时候向你们是勇敢的，如今亲自藉着基督的温柔和慈祥劝你们。","notes":[]},{"n":2,"t":"有人认为我们是凭着血气行事，我认为必须敢于对付这等人；我但求在那里的时候，不必这样勇敢。","notes":[]},{"n":3,"t":"我们虽然在血气中行事，却不凭着血气争战。","notes":[]},{"n":4,"t":"因为我们争战的兵器本不是属血气的，而是凭着神的能力，能够攻破坚固的营垒。我们攻破各样的计谋，","notes":[]},{"n":5,"t":"和各样拦阻人认识神的高垒，又夺回人心来顺服基督。","notes":[]},{"n":6,"t":"我已经预备好了，等你们完全顺服的时候来惩罚所有不顺服的人。","notes":[]},{"n":7,"t":"你们只看事情的外表。倘若有人自信是属基督的，他要再想想，他属基督，我们也属基督。","notes":[]},{"n":8,"t":"主赐给我们权柄，是要造就你们，并不是要拆毁你们；我就是为这权柄稍微夸口也不觉得惭愧。","notes":[]},{"n":9,"t":"我说这话，免得你们以为我写信是要恐吓你们。","notes":[]},{"n":10,"t":"因为有人说：“他信上的语气既严厉又强硬，他本人却软弱无能，言语粗俗。”","notes":[]},{"n":11,"t":"这等人当明白，我们不在那里时信上怎么说，见面时也必怎么做。","notes":[]},{"n":12,"t":"因为我们不敢将自己和某些自我推荐的人并列相比；他们用自己度量自己，用自己比较自己，是不明智的。","notes":[]},{"n":13,"t":"我们不愿意过分夸口，但是我们只在神划定的界限内夸口。这界限甚至扩展到你们那里。","notes":[]},{"n":14,"t":"我们扩展到你们那里时并没有越过了自己的界限，其实我们是首先到你们那里传基督福音的。","notes":[]},{"n":15,"t":"我们不靠别人所劳碌的过分夸口；我们只希望你们信心增长的时候，所划定给我们的范围也能够因着你们更加扩展，","notes":[]},{"n":16,"t":"使福音得以传到你们以外的地方，而不在别人的范围之内，以别人所成就的事夸口。","notes":[]},{"n":17,"t":"但“要夸耀的，该夸耀主”。","notes":[]},{"n":18,"t":"因为蒙悦纳的，不是自我称许的，而是主所称许的。","notes":[]}]},"11":{"heading":"保罗和假使徒","verses":[{"n":1,"t":"但愿你们容忍我小小的愚蠢；请你们务必容忍我。","notes":[]},{"n":2,"t":"我以神嫉妒的爱来爱你们，因为我曾把你们许配给一个丈夫，要把你们如同贞洁的童女献给基督。","notes":[]},{"n":3,"t":"我只怕你们的心偏邪了，失去那向基督所献诚恳贞洁的心，就像蛇用诡诈诱惑了夏娃一样。","notes":["有古卷没有“贞洁”。"]},{"n":4,"t":"假如有人来，传另一个耶稣，不是我们所传过的；或者你们另受一个灵，不是你们所受过的圣灵；或者接纳另一个福音，不是你们所接纳过的；你们居然容忍了！","notes":[]},{"n":5,"t":"但我想，我一点也不在那些超级使徒以下。","notes":[]},{"n":6,"t":"虽然我不擅长说话，我的知识却不如此。这点我们已经在每一方面各样事上向你们表明了。","notes":[]},{"n":7,"t":"我贬低自己，为了使你们高升，因为我白白地传神的福音给你们，难道这算是我犯了错吗？","notes":[]},{"n":8,"t":"我剥夺了别的教会，向他们取了报酬来效劳你们。","notes":[]},{"n":9,"t":"我在你们那里有缺乏的时候，并没有连累你们一个人，因为我所缺乏的，那些从马其顿来的弟兄都补足了。我向来凡事谨慎，将来也必谨慎，总不要连累你们。","notes":[]},{"n":10,"t":"既有基督的真诚在我里面，在亚该亚一带地方就没有人能阻止我这样自夸。","notes":[]},{"n":11,"t":"为什么呢？是因我不爱你们吗？神知道，我爱你们！","notes":[]},{"n":12,"t":"我现在所做的，将来还要做，为要断绝那些寻机会之人的机会，不让他们在所夸耀的事上被人认为与我们一样。","notes":[]},{"n":13,"t":"那样的人是假使徒，行事诡诈，装作基督的使徒。","notes":[]},{"n":14,"t":"这也不足为奇，因为连撒但也装作光明的天使。","notes":[]},{"n":15,"t":"所以，他的差役若装作公义的差役也没有什么大不了。他们的结局必然跟他们的行为相符。","notes":[]},{"n":16,"t":"我再说，谁都不可把我看作愚蠢的；即使你们把我当作愚蠢人，那么，也让我稍微夸夸口吧。","notes":[],"heads":["保罗所受的患难"]},{"n":17,"t":"我说的话不是奉主的权柄说的，而是像愚蠢人具有自信地放胆夸口。","notes":[]},{"n":18,"t":"既然有好些人凭着血气在夸口，我也要夸口了。","notes":[]},{"n":19,"t":"你们是聪明人，竟能甘心容忍愚蠢人！","notes":[]},{"n":20,"t":"假若有人奴役你们，或侵吞你们，或压榨你们，或侮辱你们，或打你们的脸，你们居然都能容忍。","notes":[]},{"n":21,"t":"说来惭愧，在这方面好像我们是太软弱了。然而，我说句蠢话，人在什么事上敢夸口，我也敢夸口。","notes":[]},{"n":22,"t":"他们是希伯来人吗？我也是。他们是以色列人吗？我也是。他们是亚伯拉罕的后裔吗？我也是。","notes":[]},{"n":23,"t":"他们是基督的用人吗？我说句狂话，我更是。我比他们忍受更多劳苦，坐过更多次监牢，受过无数次的鞭打，常常冒死。","notes":[]},{"n":24,"t":"我被犹太人鞭打五次，每次四十减去一下；","notes":[]},{"n":25,"t":"被棍打了三次，被石头打了一次，遭海难三次，一昼一夜在深海里挣扎。","notes":[]},{"n":26,"t":"我又屡次行远路，遭江河的危险，盗贼的危险，同族人的危险，外族人的危险，城里的危险，旷野的危险，海中的危险，假弟兄的危险。","notes":[]},{"n":27,"t":"我劳碌困苦，常常失眠，又饥又渴，忍饥耐寒，赤身露体。","notes":[]},{"n":28,"t":"除了这些外表的事以外，我还有为众教会操心的事天天压在我身上。","notes":[]},{"n":29,"t":"有谁软弱，我不软弱呢？有谁跌倒，我不焦急呢？","notes":[]},{"n":30,"t":"我若必须夸口，就夸我软弱的事好了。","notes":[]},{"n":31,"t":"那永远可称颂之主耶稣的父神知道我不说谎。","notes":[]},{"n":32,"t":"在大马士革的亚哩达王手下的提督把守大马士革城，要捉拿我，","notes":[]},{"n":33,"t":"我被人用筐子从城墙上的窗口缒下，逃脱了他的手。","notes":[]}]},"12":{"heading":"异象和启示","verses":[{"n":1,"t":"虽然自夸无益，我还是不得不夸。我现在要提到主的异象和启示。","notes":[]},{"n":2,"t":"我认识一个在基督里的人，他在十四年前被提到第三层天上去；或在身内，我不知道，或在身外，我也不知道，只有神知道。","notes":[]},{"n":3,"t":"我认识的这样的一个人—或在身内，或在身外，我都不知道，只有神知道—","notes":[]},{"n":4,"t":"他被提到乐园里，听见隐秘的言语，是人不可说的。","notes":[]},{"n":5,"t":"为这人，我要夸口；但是为我自己，除了我的软弱以外，我并不夸口。","notes":[]},{"n":6,"t":"就是我愿意夸口也不算狂，因为我会说实话；只是我绝口不谈，恐怕有人把我看得太高了，过于他在我身上所看见所听见的；","notes":[]},{"n":7,"t":"又恐怕我因所得的启示太高深，就过于高抬自己，所以有一根刺加在我身上，就是撒但的差役来折磨我，免得我过于高抬自己。","notes":["有古卷没有“所以”。"]},{"n":8,"t":"为了这事，我曾三次求主使这根刺离开我。","notes":[]},{"n":9,"t":"他对我说：“我的恩典是够你用的，因为我的能力是在人的软弱上显得完全。”所以，我更喜欢夸耀自己的软弱，好使基督的能力覆庇我。","notes":[]},{"n":10,"t":"为基督的缘故，我以软弱、凌辱、艰难、迫害、困苦为可喜乐的事；因为我什么时候软弱，什么时候就刚强了。","notes":[]},{"n":11,"t":"我成了愚蠢人，是被你们逼出来的，因为我本该被你们赞许才是。虽然我算不了什么，却没有一件事在那些超级使徒以下。","notes":[],"heads":["保罗关心哥林多教会"]},{"n":12,"t":"我在你们中间，用百般的忍耐，藉着神迹、奇事、异能显出使徒的凭据来。","notes":[]},{"n":13,"t":"除了我不曾连累你们这一件事，你们还有什么事不及别的教会呢？这不公平之处，请你们饶恕我吧。","notes":[]},{"n":14,"t":"如今，我准备第三次到你们那里去。我仍不会连累你们，因为我所求的是你们，不是你们的财物。儿女不该为父母积财，父母该为儿女积财。","notes":[]},{"n":15,"t":"我也甘心乐意为你们的灵魂费财费力。难道我越爱你们，就越少得你们的爱吗？","notes":[]},{"n":16,"t":"罢了，我自己并没有连累你们，你们却有人说，我施诡诈，用心计牢笼你们。","notes":[]},{"n":17,"t":"我所差遣到你们那里去的人，我何曾藉着他们中的任何人占过你们的便宜呢？","notes":[]},{"n":18,"t":"我劝提多到你们那里去，又差遣那位弟兄与他同去，提多占过你们的便宜吗？我们的行事为人不是同一心灵吗？不是同一步伐吗？","notes":["“心灵”或译“圣灵”。"]},{"n":19,"t":"你们一直认为我们是在你们面前为自己辩护吗？其实，我们本是在基督里当着神面前说话。亲爱的，一切的事都是为了造就你们。","notes":[]},{"n":20,"t":"我怕我再来的时候，见你们不合我所期望的，而你们见我也不合你们所期望的。我怕有纷争、嫉妒、愤怒、自私、毁谤、谗言、狂傲、动乱的事。","notes":[]},{"n":21,"t":"我怕我再来的时候，我的神使我在你们面前蒙羞，并且又因许多人从前犯罪，行污秽、淫乱、放荡的事，不肯悔改而悲伤。","notes":[]}]},"13":{"heading":"警告和问候","verses":[{"n":1,"t":"这是我第三次要到你们那里去。“任何指控都要凭两个或三个证人的口述才能成立。”","notes":[]},{"n":2,"t":"对那些犯了罪的人和其余所有的人，正如我第二次见你们的时候曾说过，现在不在你们那里再次说：“我若再来，必不宽容。”","notes":[]},{"n":3,"t":"因为你们想求证基督是否藉着我说话。基督对你们并不是软弱的，而是在你们里面大有能力的。","notes":[]},{"n":4,"t":"他因软弱被钉在十字架上，却因神的大能仍然活着。我们在他里面也成为软弱的，但对你们，我们将因神的大能而与他一同活着。","notes":[]},{"n":5,"t":"你们总要省察自己是否在信仰中生活；你们要考验自己。除非你们经不起考验，你们自己岂不应该知道有耶稣基督在你们里面吗？","notes":[]},{"n":6,"t":"我希望你们知道，我们并不是经不起考验的人。","notes":[]},{"n":7,"t":"我们祈求神使你们不做任何恶事；这不是要显明我们是经得起考验的，而是要你们行事端正，即使我们似乎经不起考验也没有关系。","notes":[]},{"n":8,"t":"我们不能做任何对抗真理的事，只能维护真理。","notes":[]},{"n":9,"t":"当我们软弱而你们刚强时，我们也欢喜。我们所祈求的是：你们能成为完全人。","notes":[]},{"n":10,"t":"所以，我不在你们那里的时候，把这些话写给你们，好使我见你们的时候不用照主所给我的权柄严厉地待你们；这权柄原是为造就人，而不是为摧毁人。","notes":[]},{"n":11,"t":"末了，弟兄们，愿你们喜乐。要追求完全；要接受鼓励；要同心合意；要彼此和睦。如此，慈爱和平的神必与你们同在。","notes":[]},{"n":12,"t":"你们要用圣洁的吻彼此问安。众圣徒都向你们问安。","notes":[]},{"n":13,"t":"愿主耶稣基督的恩惠、神的慈爱、圣灵的感动常与你们众人同在！","notes":[]}]}},"GAL":{"1":{"heading":"问候","verses":[{"n":1,"t":"我使徒保罗和所有跟我一起的弟兄，写信给加拉太的众教会。我作使徒不是由于人，也不是藉着人，而是藉着耶稣基督与使他从死人中复活的父神。","notes":[],"end":2},{"n":3,"t":"愿恩惠、平安从我们的父神和主耶稣基督归给你们！","notes":["“平安”或译“和平”。"]},{"n":4,"t":"基督照我们父神的旨意，为我们的罪舍己，要救我们脱离现今这罪恶的世代。","notes":[]},{"n":5,"t":"愿荣耀归给神，直到永永远远。阿们！","notes":[]},{"n":6,"t":"我很惊讶你们这么快就离开那位藉着基督之恩呼召你们的神，而去随从别的福音；","notes":["有古卷没有“基督之”；另有古卷是“耶稣基督之”。"],"heads":["没有别的福音"]},{"n":7,"t":"其实并没有另一个福音，不过有些人骚扰你们，要把基督的福音更改了。","notes":[]},{"n":8,"t":"但无论是我们或是天上来的使者，若传福音给你们，与我们所传给你们的不同，他该受诅咒！","notes":["有古卷没有“给你们”。"]},{"n":9,"t":"我们已经说了，现在我再说，若有人传福音给你们，与你们以往所领受的不同，他该受诅咒！","notes":[]},{"n":10,"t":"我现在是要得人的心，还是要得神的心呢？难道我在讨人的喜欢吗？我若仍旧想讨人的喜欢，我就不是基督的仆人了。","notes":[]},{"n":11,"t":"弟兄们，我要你们知道，我所传的福音不是按照人的意思；","notes":[],"heads":["保罗怎样成为使徒"]},{"n":12,"t":"因为我不是从人领受的，也不是人教导我的，而是藉着耶稣基督的启示而来。","notes":[]},{"n":13,"t":"你们听说过从前我在犹太教中的行径，我怎样竭力压迫残害神的教会。","notes":[]},{"n":14,"t":"在犹太教中，我比本国许多同辈的人更激进，为我祖宗的传统更热心。","notes":[]},{"n":15,"t":"然而，那位把我从母腹里分别出来、又施恩呼召我的神，既然乐意","notes":["有古卷没有“神”。"]},{"n":16,"t":"把他儿子启示在我心里，让我在外邦人中传扬他，我就没有跟有血有肉的人商量，","notes":[]},{"n":17,"t":"也没有上耶路撒冷去见那些比我先作使徒的，惟独到阿拉伯去，后来又回到大马士革。","notes":[]},{"n":18,"t":"过了三年，我才上耶路撒冷去见矶法，和他同住了十五天。","notes":[]},{"n":19,"t":"至于别的使徒，除了主的兄弟雅各，我都没有见过。","notes":[]},{"n":20,"t":"我现在写给你们的是在神面前说的，不说谎话。","notes":[]},{"n":21,"t":"以后我到了叙利亚和基利家一带；","notes":[]},{"n":22,"t":"那时，在基督里的犹太各教会都没有见过我的面。","notes":[]},{"n":23,"t":"不过他们听说“那从前压迫我们的，现在竟传扬他原先所残害的信仰”。","notes":[]},{"n":24,"t":"他们就为我的缘故归荣耀给神。","notes":[]}]},"2":{"heading":"保罗被其他使徒接纳","verses":[{"n":1,"t":"过了十四年，我再上耶路撒冷去，巴拿巴同行，也带了提多一起去。","notes":[]},{"n":2,"t":"我是奉了启示上去的；我把在外邦人中所传的福音对弟兄们说明，我是私下对那些有名望的人说的，免得我现在或是从前都徒然奔跑了。","notes":[]},{"n":3,"t":"但跟我同去的提多，虽是希腊人，也没有勉强他受割礼；","notes":[]},{"n":4,"t":"因为有偷着混进来的假弟兄，暗中窥探我们在基督耶稣里拥有的自由，要使我们作奴隶，","notes":[]},{"n":5,"t":"可是，为要使福音的真理仍存在你们中间，我们一点也没有让步顺服他们。","notes":[]},{"n":6,"t":"至于那些有名望的，不论他们是何等人，都与我无关；神不以外貌取人。那些有名望的，并没有加增我什么。","notes":[]},{"n":7,"t":"相反地，他们看见了主托付我传福音给未受割礼的人，正如主托付彼得传福音给受割礼的人；","notes":[]},{"n":8,"t":"那感动彼得、叫他为受割礼的人作使徒的，也感动我，叫我为外邦人作使徒。","notes":[]},{"n":9,"t":"那些被认为是教会柱石的雅各、矶法、约翰知道神所赐给我的恩典，就跟我和巴拿巴握右手以示合作，同意我们往外邦人那里去，他们往受割礼的人那里去。","notes":[]},{"n":10,"t":"他们只要求我们记念穷人，这也是我一向热心在做的。","notes":[]},{"n":11,"t":"后来，矶法到了安提阿，因为他有可责之处，我就当面反对他。","notes":[],"heads":["保罗责备彼得"]},{"n":12,"t":"从雅各那里来的人未到以前，他和外邦人一同吃饭，及至他们来到，他因怕奉割礼的人就退出，跟外邦人疏远了。","notes":[]},{"n":13,"t":"其余的犹太人也都随着他装假，甚至连巴拿巴也随伙装假。","notes":[]},{"n":14,"t":"但我一看见他们做得不对，与福音的真理不合，就在众人面前对矶法说：“你既是犹太人，却按照外邦人的样子，不按照犹太人的样子生活，怎么能勉强外邦人按照犹太人的样子生活呢？”","notes":[]},{"n":15,"t":"我们生来就是犹太人，不是外邦罪人；","notes":[],"heads":["犹太人也像外邦人因信得救"]},{"n":16,"t":"可是我们知道，人称义不是因律法的行为，而是因信耶稣基督，我们也信了基督耶稣，为要使我们因信基督称义，不因律法的行为称义，因为，凡血肉之躯没有一个能因律法的行为称义。","notes":["“因信耶稣基督”或译“藉耶稣基督的信”。"]},{"n":17,"t":"我们若求在基督里称义，自己却还被视为罪人，那么，基督是罪的用人吗？绝对不是！","notes":[]},{"n":18,"t":"如果我重新建造我所拆毁的，这就证明自己是违犯律法的人。","notes":[]},{"n":19,"t":"我因律法而向律法死了，使我可以向神活着。我已经与基督同钉十字架，","notes":[]},{"n":20,"t":"现在活着的不再是我，乃是基督在我里面活着；并且我如今在肉身活着，是因信神的儿子而活；他是爱我，为我舍己。","notes":[]},{"n":21,"t":"我不废掉神的恩；如果义是藉着律法而获得，那么基督就白白死了。","notes":[]}]},"3":{"heading":"律法或信心","verses":[{"n":1,"t":"无知的加拉太人哪，耶稣基督钉十字架，已经活现在你们眼前，谁又迷惑了你们呢？","notes":[]},{"n":2,"t":"这是我惟一要问你们的：你们领受了圣灵，是因律法的行为或是因听信福音呢？","notes":[]},{"n":3,"t":"你们既然以圣灵开始，如今竟要以肉身终结吗？你们是这样的无知吗？","notes":[]},{"n":4,"t":"你们受这么多的苦都是徒然的吗？如果真是徒然的，","notes":[]},{"n":5,"t":"那么，神赐给你们圣灵，又在你们中间行异能，是因律法的行为或是因听信福音呢？","notes":[]},{"n":6,"t":"正如亚伯拉罕“信了神，这就算他为义”。","notes":[]},{"n":7,"t":"所以，你们知道：有信心的人才是亚伯拉罕的子孙。","notes":[]},{"n":8,"t":"圣经既然预先看见神要使外邦人因信称义，预先传福音给亚伯拉罕，说：“万国都必因你得福。”","notes":[]},{"n":9,"t":"可见，那有信心的人和有信心的亚伯拉罕一同得福。","notes":[]},{"n":10,"t":"凡出于律法的行为都是受诅咒的，因为经上记着：“凡不持守律法书上所记的一切而去行的，都是受诅咒的。”","notes":[]},{"n":11,"t":"没有一个人靠着律法在神面前称义，这是明显的，因为经上说：“义人必因信得生。”","notes":[]},{"n":12,"t":"律法并不出于信，而是说：“行这些事的就必因此得生。”","notes":[]},{"n":13,"t":"既然基督为我们成了诅咒，就把我们从律法的诅咒中赎出来。因为经上记着：“凡挂在木头上的都是受诅咒的。”","notes":[]},{"n":14,"t":"这是要使亚伯拉罕的福，因着基督耶稣临到外邦人，使我们能因信得着所应许的圣灵。","notes":[]},{"n":15,"t":"弟兄们，我照着人的观点说，人的遗嘱一经确定，没有人能废弃或加增。","notes":[],"heads":["律法和应许"]},{"n":16,"t":"那些应许原是向亚伯拉罕和他后裔说的，并不是说“和众后裔”，指许多人，而是说“和你那个后裔”，指一个人，就是基督。","notes":[]},{"n":17,"t":"我是这么说，神预先所立的约不能被四百三十年以后的律法废掉，使应许失效。","notes":[]},{"n":18,"t":"因为承受产业若是出于律法，就不再是出于应许；但神是凭着应许把产业赐给亚伯拉罕。","notes":[]},{"n":19,"t":"这样说来，为什么要有律法呢？律法是为过犯的缘故而加上去的，等候那蒙应许的子孙来到才结束，是藉着天使经中保之手而设立的。","notes":[]},{"n":20,"t":"但中保本不是为单方设立的；神却是一位。","notes":[]},{"n":21,"t":"这样，律法是与神的应许对立吗？绝对不是！如果律法的颁布能使人得生命，义就诚然出于律法了。","notes":["有古卷没有“神的”；另有古卷是“基督的”。"],"heads":["奴隶和儿子"]},{"n":22,"t":"但圣经把万物都圈在罪里，为要使因信耶稣基督而来的应许归给信的人。","notes":["“因信耶稣基督”或译“藉耶稣基督的信”。"]},{"n":23,"t":"但这“信”还未来以前，我们被看守在律法之下，像被圈住，直到那将来的“信”显明出来。","notes":[]},{"n":24,"t":"这样，律法是我们的启蒙教师，直到基督来了，好使我们因信称义。","notes":["“直到基督来了”或译“引我们到基督那里”。"]},{"n":25,"t":"但这“信”既然来到，我们从此就不在启蒙教师的手下了。","notes":[]},{"n":26,"t":"其实，你们藉着信，在基督耶稣里都成为神的儿女。","notes":[]},{"n":27,"t":"你们凡受洗归入基督的都披戴基督了：","notes":[]},{"n":28,"t":"不再分犹太人或希腊人，不再分为奴的自主的，不再分男的女的，因为你们在基督耶稣里都成为一了。","notes":[]},{"n":29,"t":"既然你们属于基督，你们就是亚伯拉罕的子孙，是照着应许承受产业的了。","notes":[]}]},"4":{"heading":"保罗关怀加拉太人","verses":[{"n":1,"t":"我说，虽然那承受产业的是整个产业的主人，但在未成年的时候却与奴隶毫无分别，","notes":[]},{"n":2,"t":"仍是在监护人和管家的手下，直等他父亲预定的时候来到。","notes":[]},{"n":3,"t":"我们也是一样，在未成年的时候，被世上粗浅的学说所奴役，也是如此。","notes":["“世上粗浅的学说”或译“宇宙的星宿”。"]},{"n":4,"t":"等到时候成熟，神就差遣他的儿子，为女子所生，且生在律法之下，","notes":[]},{"n":5,"t":"为要把律法之下的人赎出来，使我们获得儿子的名分。","notes":[]},{"n":6,"t":"因为你们是儿子，神就差他儿子的灵进入我们的心，呼叫：“阿爸，父！”","notes":["“我们”：有古卷是“你们”。"]},{"n":7,"t":"可见，你不再是奴隶，而是儿子了，既然是儿子，就靠着神也成为后嗣了。","notes":[]},{"n":8,"t":"但从前不认识神的时候，你们是给那些本来不是神的神明作奴隶；","notes":[]},{"n":9,"t":"现在你们既然认识神，更可说是被神所认识的，怎么还要转回那懦弱无用的粗浅学说，情愿再给它们作奴隶呢？","notes":["“粗浅学说”或译“星宿之学”。"]},{"n":10,"t":"你们竟又谨守日子、月份、节期、年份，","notes":[]},{"n":11,"t":"我为你们担心，惟恐我在你们身上是枉费工夫了。","notes":[]},{"n":12,"t":"弟兄们，我劝你们，要像我一样，因为我也像你们一样。你们一点没有亏负我。","notes":[]},{"n":13,"t":"你们知道，我因为身体有疾病才有第一次传福音给你们的机会。","notes":[]},{"n":14,"t":"虽然你们为我身体的缘故受试炼，却没有轻看我，也没有厌弃我，反倒接待我如同神的使者，如同基督耶稣。","notes":[]},{"n":15,"t":"你们当日的好意哪里去了呢？那时若办得到，你们就是把自己的眼睛挖出来给我，也都情愿。这是我可以给你们作证的。","notes":[]},{"n":16,"t":"如今我把真理告诉你们，倒成了你们的仇敌吗？","notes":[]},{"n":17,"t":"那些热心待你们的人，不怀好意，是要隔绝你们，好使你们热心待他们。","notes":[]},{"n":18,"t":"在善事上，时刻热心待别人原是好的，却不只是我与你们同在的时候才这样。","notes":[]},{"n":19,"t":"我的孩子们哪，我为你们再受生产之苦，直等到基督成形在你们心里。","notes":["“成形在你们心里”或译“在你们当中成形”。"]},{"n":20,"t":"我期望现今就在你们那里，可以改变我的口气，因为我为你们心里难过。","notes":[]},{"n":21,"t":"你们这愿意在律法之下的人，请告诉我，你们没有听见律法吗？","notes":[],"heads":["夏甲和撒拉的例子"]},{"n":22,"t":"因为律法上记着，亚伯拉罕有两个儿子，一个是使女生的，一个是自由的妇人生的。","notes":[]},{"n":23,"t":"那使女所生的是按着肉体生的；那自由的妇人所生的是凭着应许生的。","notes":[]},{"n":24,"t":"这是比方：那两个妇人就是两个约；一个妇人是出于西奈山，生子为奴，就是夏甲。","notes":[]},{"n":25,"t":"这夏甲是指着阿拉伯的西奈山，与现在的耶路撒冷同类，因为耶路撒冷和她的儿女都是为奴的。","notes":["有古卷是“因为西奈山是指着阿拉伯的一座山”。"]},{"n":26,"t":"但另一妇人就是在上的耶路撒冷，是自由的，她是我们的母亲。","notes":[]},{"n":27,"t":"因为经上记着：“不怀孕、不生养的，你要欢乐；未曾经过产难的，你要高声欢呼；因为没有丈夫的，比有丈夫的有更多的儿女。”","notes":[]},{"n":28,"t":"弟兄们，你们是凭着应许作儿女的，如同以撒一样。","notes":[]},{"n":29,"t":"当时，那按着肉体生的迫害了那按着圣灵生的，现在也是这样。","notes":[]},{"n":30,"t":"然而经上是怎么说的呢？是说：“把使女和她儿子赶出去！因为使女的儿子绝不能与自由妇人的儿子一同承受产业。”","notes":[]},{"n":31,"t":"弟兄们，这样看来，我们不是使女的儿女，而是自由妇人的儿女了。","notes":[]}]},"5":{"heading":"基督徒的自由","verses":[{"n":1,"t":"基督释放了我们，为使我们得自由。所以要站稳了，不要再被奴隶的轭挟制。","notes":[]},{"n":2,"t":"我—保罗告诉你们，你们若受割礼，基督就对你们无益了。","notes":[]},{"n":3,"t":"我再指着凡受割礼的人确实地说，他有义务遵行全部的律法。","notes":[]},{"n":4,"t":"你们这要靠律法称义的是与基督隔绝，从恩典中坠落了。","notes":[]},{"n":5,"t":"至于我们，我们是靠着圣灵，凭着信心，等候所盼望的义。","notes":[]},{"n":6,"t":"因为在基督耶稣里，受割礼不受割礼都没有功效，惟独使人发出仁爱的信心才有功效。","notes":[]},{"n":7,"t":"你们向来跑得好，谁拦阻了你们，使你们不顺从真理呢？","notes":[]},{"n":8,"t":"这样的劝导不是出于那召你们的。","notes":[]},{"n":9,"t":"一点面酵能使全团都发起来。","notes":[]},{"n":10,"t":"我在主里深信你们必不怀别样的心；但骚扰你们的，无论是谁，必须承受惩罚。","notes":[]},{"n":11,"t":"弟兄们，我若仍旧传割礼，为什么还受迫害呢？若是这样，十字架绊倒人的地方就没有了。","notes":[]},{"n":12,"t":"恨不得那骚扰你们的人把自己阉割了。","notes":[]},{"n":13,"t":"弟兄们，你们蒙召是要得自由；只是不可把这自由当作放纵情欲的机会，总要用爱心互相服侍。","notes":[]},{"n":14,"t":"因为全部律法都包括在“爱邻如己”这一句话之内了。","notes":["“邻”也可译作“人”。"]},{"n":15,"t":"你们要谨慎，你们若相咬相吞，恐怕要彼此消灭了。","notes":[]},{"n":16,"t":"我说，你们要顺着圣灵而行，绝不可满足肉体的情欲。","notes":[],"heads":["圣灵的果子和肉体的恶行"]},{"n":17,"t":"因为肉体的情欲和圣灵相争，圣灵和肉体相争，这两个彼此敌对，使你们不能做所愿意做的。","notes":[]},{"n":18,"t":"但你们若被圣灵引导，就不在律法之下。","notes":[]},{"n":19,"t":"情欲的事都是显而易见的；就如淫乱、污秽、放荡、","notes":[]},{"n":20,"t":"拜偶像、行邪术、仇恨、纷争、忌恨、愤怒、自私、分派、结党、","notes":[]},{"n":21,"t":"嫉妒、醉酒、荒宴等类。我从前告诉过你们，现在又告诉你们，做这样事的人必不能承受神的国。","notes":["有古卷在此加“凶杀”。"]},{"n":22,"t":"圣灵的果子就是仁爱、喜乐、和平、忍耐、恩慈、良善、信实、","notes":[]},{"n":23,"t":"温柔、节制。这样的事没有律法禁止。","notes":[]},{"n":24,"t":"凡属基督耶稣的人，是已经把肉体与肉体的邪情私欲同钉在十字架上了。","notes":["“基督耶稣”：有古卷是“基督”。"]},{"n":25,"t":"我们若靠着圣灵而活，也要靠着圣灵行事。","notes":[]},{"n":26,"t":"不要贪图虚名，彼此惹气，互相嫉妒。","notes":[]}]},"6":{"heading":"各人的重担要互相担当","verses":[{"n":1,"t":"弟兄们，若有人偶然被过犯所胜，你们属灵的人就要用温柔的心把他挽回过来；自己也要留意，免得也被引诱。","notes":[]},{"n":2,"t":"你们各人的重担要互相担当，这样就会成全基督的律法。","notes":["有古卷是“要这样成全”。"]},{"n":3,"t":"人若没有什么了不起，还自以为了不起的，就是自欺。","notes":[]},{"n":4,"t":"各人要省察自己的行为；这样，他所夸口的只在自己，而不在别人。","notes":[]},{"n":5,"t":"因为人人必须担当自己的担子。","notes":[]},{"n":6,"t":"在真道上受教的，要把一切美好的东西与施教的人分享。","notes":[]},{"n":7,"t":"不要自欺；神是轻慢不得的，因为人种的是什么，收的也是什么。","notes":[]},{"n":8,"t":"顺着肉体撒种的，必从肉体收败坏；顺着圣灵撒种的，必从圣灵收永生。","notes":[]},{"n":9,"t":"我们行善不可丧志，因为若不灰心，到了适当的时候就有收成。","notes":[]},{"n":10,"t":"所以，一有机会就要向众人行善，向信徒一家的人更要这样。","notes":[]},{"n":11,"t":"你们看我亲手写给你们的字是何等的大！","notes":[],"heads":["警告和祝福"]},{"n":12,"t":"那些想要炫耀外表的人才勉强你们受割礼，无非是怕自己为基督的十字架受迫害。","notes":[]},{"n":13,"t":"他们那些受割礼的，连自己也不守律法；他们要你们受割礼，不过是要拿你们的肉体夸口。","notes":[]},{"n":14,"t":"但我绝不以别的夸口，只夸我们主耶稣基督的十字架；因这十字架，就我而论，世界已经钉在十字架上；就世界而论，我已经钉在十字架上。","notes":["“因这十字架”或译“藉着他（基督）”。"]},{"n":15,"t":"受割礼或不受割礼都无关紧要，要紧的就是作新造的人。","notes":[]},{"n":16,"t":"凡照这准则行的人，愿平安怜悯加给他们，和神的以色列民。","notes":["“平安”或译“和平”。"]},{"n":17,"t":"从今以后，不要有人再搅扰我，因为我身上带着耶稣的印记。","notes":[]},{"n":18,"t":"弟兄们，愿我们主耶稣基督的恩与你们的灵同在。阿们！","notes":[]}]}},"EPH":{"1":{"heading":"问候","verses":[{"n":1,"t":"奉神旨意作基督耶稣使徒的保罗，写信给在以弗所的众圣徒，就是在基督耶稣里忠心的人。","notes":["有古卷没有“在以弗所的”。"]},{"n":2,"t":"愿恩惠、平安从我们的父神和主耶稣基督归给你们！","notes":["“平安”或译“和平”。"]},{"n":3,"t":"愿颂赞归给我们主耶稣基督的父神。他在基督里曾把天上各样属灵的福气赐给我们。","notes":[],"heads":["基督里的属灵福气"]},{"n":4,"t":"因为他从创世以前，在基督里拣选了我们，使我们在他面前成为圣洁，没有瑕疵，满有爱心。","notes":[]},{"n":5,"t":"他按着自己旨意所喜悦的，预定我们藉着耶稣基督得儿子的名分，","notes":["“没有瑕疵...喜悦的”：原文或译“没有瑕疵。在爱中，他按着自己旨意所喜悦的”。"]},{"n":6,"t":"使他荣耀的恩典得到称赞；这恩典是他在爱子里白白赐给我们的。","notes":[]},{"n":7,"t":"我们藉着这爱子的血得蒙救赎，过犯得以赦免，这是照他丰富的恩典，","notes":[]},{"n":8,"t":"充充足足地赏给我们的。他以诸般的智慧聪明，","notes":[]},{"n":9,"t":"照自己在基督里所立定的美意，使我们知道他旨意的奥秘，","notes":[]},{"n":10,"t":"要照着所安排的，在时机成熟的时候，使天上、地上、一切所有的，都在基督里面同归于一。","notes":[]},{"n":11,"t":"我们也在他里面得了基业；这原是那位随己意行万事的神照着自己的旨意所预定的，","notes":[]},{"n":12,"t":"为要使我们，这些首先把希望寄托在基督里的人，颂赞他的荣耀。","notes":[]},{"n":13,"t":"在基督里你们听见真理的道，就是那使你们得救的福音，你们也信了他，就受了所应许的圣灵为印记。","notes":[]},{"n":14,"t":"这圣灵是我们得基业的凭据，直等到神的子民得救赎，使他的荣耀得到称赞。","notes":[]},{"n":15,"t":"因此，我既然听见你们对主耶稣有信心，对众圣徒有爱心，","notes":[],"heads":["保罗的祷告"]},{"n":16,"t":"就不住地为你们感谢神，祷告的时候常常提到你们，","notes":[]},{"n":17,"t":"求我们主耶稣基督的神，荣耀的父，把那赐人智慧和启示的灵赐给你们，使你们真正认识他，","notes":[]},{"n":18,"t":"照亮你们心中的眼睛，使你们知道他呼召你们来得的指望是什么，他在圣徒中所得荣耀的基业是何等丰盛，","notes":[]},{"n":19,"t":"并知道他向我们这些信的人所显的能力是何等浩大，这是照他的大能大力运行的。","notes":[]},{"n":20,"t":"这大能曾运行在基督身上，使他从死人中复活，又使他在天上坐在自己的右边，","notes":[]},{"n":21,"t":"远超越一切执政的、掌权的、有权能的、统治的和一切有名号的；不但是今世的，连来世的也都超越了。","notes":[]},{"n":22,"t":"神使万有服在他的脚下，又使他为了教会作万有之首；","notes":[]},{"n":23,"t":"教会是他的身体，是那充满万有者所充满的。","notes":[]}]},"2":{"heading":"出死入生","verses":[{"n":1,"t":"从前，你们因着自己的过犯罪恶而死了。","notes":[]},{"n":2,"t":"那时，你们在过犯罪恶中生活，随从今世的风俗，顺服空中掌权者的领袖，就是现今在悖逆的人心中运行的邪灵。","notes":[]},{"n":3,"t":"我们从前也都生活在他们当中，放纵肉体的私欲，随着肉体和心中的意念去做，和别人一样，生来就是该受惩罚的人。","notes":[]},{"n":4,"t":"然而，神有丰富的怜悯，因着他爱我们的大爱，","notes":[]},{"n":5,"t":"竟在我们因过犯而死了的时候，使我们与基督一同活过来—可见你们得救是本乎恩—","notes":[]},{"n":6,"t":"他又使我们在基督耶稣里与他一同复活，一同坐在天上，","notes":[]},{"n":7,"t":"为要把他极丰富的恩典，就是他在基督耶稣里向我们所施的恩慈，显明给后来的世代。","notes":[]},{"n":8,"t":"你们得救是本乎恩，也因着信；这并不是出于自己，而是神所赐的；","notes":[]},{"n":9,"t":"也不是出于行为，免得有人自夸。","notes":[]},{"n":10,"t":"我们是他所造之物，在基督耶稣里创造的，为要使我们行善，就是神早已预备好要我们做的。","notes":[]},{"n":11,"t":"所以，你们要记得：从前你们按肉体是外邦人，是“没受割礼的”；这名字是那些凭人手在肉身上“受割礼的人”所取的。","notes":[],"heads":["在基督里合而为一"]},{"n":12,"t":"要记得那时候，你们与基督无关，与以色列选民团体隔绝，在所应许的约上是局外人，而且在世上没有指望，没有神。","notes":[]},{"n":13,"t":"从前你们是远离神的人，如今却在基督耶稣里，靠着他的血，已经得以亲近了。","notes":[]},{"n":14,"t":"因为他自己是我们的和平，使双方合而为一，拆毁了中间隔绝的墙，而且以自己的身体终止了冤仇，","notes":["“因为…和平”或译“因为他使我们和睦”。"]},{"n":15,"t":"废掉那记在律法上的规条，为要使两方藉着自己造成一个新人，促成了和平；","notes":[]},{"n":16,"t":"既在十字架上消灭了冤仇，就藉这十字架使双方归为一体，与神和好，","notes":[]},{"n":17,"t":"并且来传和平的福音给你们远处的人，也传和平给那些近处的人，","notes":[]},{"n":18,"t":"因为我们双方藉着他，在同一位圣灵里得以进到父面前。","notes":[]},{"n":19,"t":"这样，你们不再是外人或客旅，是与圣徒同国，是神家里的人了，","notes":[]},{"n":20,"t":"被建造在使徒和先知的根基上，而基督耶稣自己为房角石，","notes":[]},{"n":21,"t":"靠着他整座房子连接得紧凑，渐渐成为在主里的圣殿。","notes":[]},{"n":22,"t":"你们也靠他同被建造，成为神藉着圣灵居住的所在。","notes":[]}]},"3":{"heading":"保罗向外邦人传福音","verses":[{"n":1,"t":"因此，我—保罗为你们外邦人作了基督耶稣囚徒的，替你们祈祷。","notes":["“基督耶稣”：有古卷是“基督”。","此句是对照14节所加的。"]},{"n":2,"t":"想必你们曾听见神赐恩给我，把关切你们的职分托付我，","notes":[]},{"n":3,"t":"用启示让我知道福音的奥秘，正如我以前略略写过的。","notes":[]},{"n":4,"t":"你们读了，就会知道我深深了解基督的奥秘；","notes":[]},{"n":5,"t":"这奥秘在以前的世代没有让人知道，像如今藉着圣灵向他的圣使徒和先知启示一样，","notes":[]},{"n":6,"t":"就是外邦人在基督耶稣里，藉着福音，得以同为后嗣，同为一体，同为蒙应许的人。","notes":[]},{"n":7,"t":"我作了这福音的仆役，是照着神的恩赐，是照他运行的大能赐给我的。","notes":[]},{"n":8,"t":"虽然我比众圣徒中最小的还小，他还赐我这恩典，让我把基督那测不透的丰富传给外邦人，","notes":[]},{"n":9,"t":"又使众人都明白什么是历代以来隐藏在创造万物之神里的奥秘，","notes":["“使众人都明白”：有古卷是“显明”。"]},{"n":10,"t":"为要在现今藉着教会使天上执政的、掌权的知道神百般的智慧。","notes":[]},{"n":11,"t":"这是照着神在我们主基督耶稣里所完成的永恒的计划。","notes":[]},{"n":12,"t":"我们因信耶稣，就在他里面放胆无惧，满有自信地进到神面前。","notes":["“因信耶稣”或译“藉耶稣的信”。"]},{"n":13,"t":"所以我求你们，不要因我为你们所受的患难丧胆；这原是你们的光荣。","notes":[]},{"n":14,"t":"因此，我在父面前屈膝—","notes":[],"heads":["明白基督的爱"]},{"n":15,"t":"天上地上的各家都是从他得名的－","notes":[]},{"n":16,"t":"为要他按着他丰盛的荣耀，藉着他的灵，使你们内心的力量刚强起来；","notes":[]},{"n":17,"t":"又要他使基督因着你们的信住在你们心里，使你们既在爱中生根立基，","notes":[]},{"n":18,"t":"能够和众圣徒一同明白基督的爱是何等的长、阔、高、深，并知道这爱是超过人的知识所能测度的，为要使你们充满神一切的丰盛。","notes":[],"end":19},{"n":20,"t":"神能照着运行在我们心里的大能充充足足地成就一切，超过我们所求所想的。","notes":[]},{"n":21,"t":"愿他在教会中，并在基督耶稣里，得着荣耀，直到世世代代，永永远远。阿们！","notes":[]}]},"4":{"heading":"身体的合一","verses":[{"n":1,"t":"我为主作囚徒的劝你们，既然蒙召，行事为人就要与你们所蒙的呼召相称。","notes":[]},{"n":2,"t":"凡事要谦虚、温柔、忍耐，用爱心互相宽容，","notes":[]},{"n":3,"t":"以和平彼此联系，竭力保持圣灵所赐的合一。","notes":[]},{"n":4,"t":"身体只有一个，圣灵只有一位，正如你们蒙召，是为同有一个指望而蒙召，","notes":[]},{"n":5,"t":"一主，一信，一洗，","notes":[]},{"n":6,"t":"一神－就是万人之父，超越万有之上，贯通万有，在万有之中。","notes":[]},{"n":7,"t":"我们每个人蒙恩都是照基督所量给每个人的恩赐。","notes":[]},{"n":8,"t":"所以有话说：“他升上高天的时候，掳掠了俘虏，将各样的恩赐赏给人。”","notes":[]},{"n":9,"t":"既说“他升上”，岂不是指他曾降到地底下吗？","notes":[]},{"n":10,"t":"那降下的，就是高升远超越诸天之上的，为要充满万有。","notes":[]},{"n":11,"t":"他所赐的有使徒，有先知，有传福音的，有牧者和教师，","notes":[]},{"n":12,"t":"为要装备圣徒，做事奉的工作，建立基督的身体，","notes":[]},{"n":13,"t":"直等到我们众人在信仰上同归于一，认识神的儿子，得以长大成人，达到基督完全长成的身量。","notes":[]},{"n":14,"t":"这样，我们不再作小孩子，中了人的诡计和欺骗的法术，被一切邪说之风摇动，飘来飘去。","notes":[]},{"n":15,"t":"我们反而要用爱心说诚实话，各方面向着基督长进，连于元首基督，","notes":[]},{"n":16,"t":"靠着他全身都连接得紧凑，百节各按各职，照着各体的功用彼此相助，使身体渐渐增长，在爱中建立自己。","notes":[]},{"n":17,"t":"所以我这样说，且在主里郑重地说，你们行事为人，不要再像外邦人存虚妄的心而活。","notes":[],"heads":["旧我和新我"]},{"n":18,"t":"他们心地昏昧，因自己无知，心里刚硬而与神所赐的生命隔绝了。","notes":[]},{"n":19,"t":"既然他们已经麻木，就放纵情欲，贪婪地行种种污秽的事。","notes":[]},{"n":20,"t":"但你们从基督学的不是这样。","notes":[]},{"n":21,"t":"如果你们听过他的道，领了他的教，因为真理就在耶稣里，","notes":[]},{"n":22,"t":"你们要脱去从前的行为，脱去旧我；这旧我是因私欲的迷惑而渐渐败坏的。","notes":[]},{"n":23,"t":"你们要把自己的心志更新，","notes":[]},{"n":24,"t":"并且穿上新我；这新我是照着神的形像造的，有从真理来的公义和圣洁。","notes":[]},{"n":25,"t":"所以，你们要弃绝谎言，每个人要与邻舍说诚实话，因为我们是互为肢体。","notes":[],"heads":["新生活的守则"]},{"n":26,"t":"即使生气也不要犯罪；不可含怒到日落，","notes":[]},{"n":27,"t":"不可给魔鬼留地步。","notes":[]},{"n":28,"t":"偷窃的，不要再偷；总要勤劳，亲手做正当的事，这样才可以把自己有的，分给有缺乏的人。","notes":["有古卷没有“亲手”。"]},{"n":29,"t":"一句坏话也不可出口，只要随着需要说造就人的好话，让听见的人得益处。","notes":[]},{"n":30,"t":"不要使神的圣灵担忧，你们原是受了他的印记，等候得救赎的日子来到。","notes":[]},{"n":31,"t":"一切苦毒、愤怒、恼恨、嚷闹、毁谤，和一切的恶毒都要从你们中间除掉。","notes":[]},{"n":32,"t":"要仁慈相待，存怜悯的心，彼此饶恕，正如神在基督里饶恕了你们一样。","notes":[]}]},"5":{"heading":"行事为人要像光明的子女","verses":[{"n":1,"t":"所以，作为蒙慈爱的儿女，你们该效法神。","notes":[]},{"n":2,"t":"要凭爱心行事，正如基督爱我们，为我们舍了自己，当作馨香的供物和祭物献给神。","notes":[]},{"n":3,"t":"至于淫乱和一切污秽，或是贪婪，在你们中间连提都不可，这才合乎圣徒的体统。","notes":[]},{"n":4,"t":"淫词、妄语和粗俗的俏皮话都不合宜；总要说感谢的话。","notes":[]},{"n":5,"t":"要确实知道，无论是淫乱的，是污秽的，是贪心的（贪心的就是拜偶像的），在基督和神的国里都得不到基业。","notes":[]},{"n":6,"t":"不要被人虚浮的话欺骗了，因这些事，神的愤怒必临到那些悖逆的人。","notes":[]},{"n":7,"t":"所以，不要与他们同伙。","notes":[]},{"n":8,"t":"从前你们是暗昧的，但如今在主里面是光明的，行事为人要像光明的子女—","notes":[]},{"n":9,"t":"光明所结的果子就是一切的良善、公义、诚实。","notes":[]},{"n":10,"t":"总要察验什么是主所喜悦的事。","notes":[]},{"n":11,"t":"那暗昧无益的事，不可参与，倒要把这种事揭发出来。","notes":[]},{"n":12,"t":"因为，他们暗中所做的，就是连提起来都是可耻的。","notes":[]},{"n":13,"t":"凡被光所照明的都显露出来，","notes":[]},{"n":14,"t":"因为使一切显露出来的就是光。所以有话说：“你这睡着的人醒过来吧！要从死人中复活，基督要光照你了。”","notes":[]},{"n":15,"t":"你们要谨慎行事，不要像无知的人，要像智慧的人。","notes":[]},{"n":16,"t":"要把握时机，因为现今的世代邪恶。","notes":["或译“要爱惜光阴”。"]},{"n":17,"t":"不要作糊涂人，要明白主的旨意如何。","notes":[]},{"n":18,"t":"不要醉酒，酒能使人放荡；要被圣灵充满。","notes":[]},{"n":19,"t":"要用诗篇、赞美诗、灵歌彼此对说，口唱心和地赞美主。","notes":[]},{"n":20,"t":"凡事要奉我们主耶稣基督的名常常感谢父神。","notes":[]},{"n":21,"t":"要存敬畏基督的心彼此顺服。","notes":[],"heads":["丈夫和妻子"]},{"n":22,"t":"作妻子的，你们要顺服自己的丈夫，如同顺服主。","notes":[]},{"n":23,"t":"因为丈夫是妻子的头，如同基督是教会的头；他又是这身体的救主。","notes":[]},{"n":24,"t":"教会怎样顺服基督，妻子也要怎样凡事顺服丈夫。","notes":[]},{"n":25,"t":"作丈夫的，你们要爱自己的妻子，正如基督爱教会，为教会舍己，","notes":[]},{"n":26,"t":"以水藉着道把教会洗净，使她成为圣洁，","notes":[]},{"n":27,"t":"好献给自己，作荣耀的教会，毫无玷污、皱纹等类的缺陷，而是圣洁没有瑕疵的。","notes":[]},{"n":28,"t":"丈夫也应当照样爱妻子，如同爱自己的身体；爱妻子就是爱自己了。","notes":[]},{"n":29,"t":"从来没有人恨恶自己的身体，总是保养爱惜，正像基督待教会一样，","notes":[]},{"n":30,"t":"因我们是他身体的肢体。","notes":[]},{"n":31,"t":"“为这个缘故，人要离开父母，与妻子结合，二人成为一体。”","notes":[]},{"n":32,"t":"这是极大的奥秘，而我是指基督和教会说的。","notes":[]},{"n":33,"t":"然而，你们每个人都要爱妻子，如同爱自己一样；妻子也要敬重她的丈夫。","notes":[]}]},"6":{"heading":"儿女和父母","verses":[{"n":1,"t":"作儿女的，你们要在主里听从父母，这是理所当然的。","notes":["有古卷没有“在主里”。"]},{"n":2,"t":"当孝敬父母，使你得福，在世长寿。这是第一条带应许的诫命。","notes":[],"end":3},{"n":4,"t":"作父亲的，你们不要激怒儿女，但要照着主的教导和劝戒养育他们。","notes":[]},{"n":5,"t":"作仆人的，你们要惧怕战兢，用诚实的心听从你们肉身的主人，好像听从基督一般；","notes":[],"heads":["仆人和主人"]},{"n":6,"t":"不要只在人的眼前这样做，像仅是讨人的喜欢，而是作基督的仆人，从心里遵行神的旨意，","notes":[]},{"n":7,"t":"甘心服侍，好像服侍主，不像服侍人，","notes":[]},{"n":8,"t":"因为知道每个人所做的善事，不论是为奴的或是自主的，都必按所做的从主得到赏赐。","notes":[]},{"n":9,"t":"作主人的，你们待仆人也是一样，不要威吓他们，因为知道他们和你们在天上同有一位主，他并不偏待人。","notes":[]},{"n":10,"t":"最后，你们要靠着主，依赖他的大能大力作刚强的人。","notes":[],"heads":["与邪恶争战"]},{"n":11,"t":"要穿戴神所赐的全副军装，好抵挡魔鬼的诡计。","notes":[]},{"n":12,"t":"因为我们的争战并不是对抗有血有肉的人，而是对抗那些执政的、掌权的、管辖这幽暗世界的，以及天空灵界的恶魔。","notes":[]},{"n":13,"t":"所以，要拿起神所赐的全副军装，好在邪恶的日子能抵挡仇敌，并且完成了一切后还能站立得住。","notes":[]},{"n":14,"t":"所以，要站稳了，用真理当作带子束腰，用公义当作护心镜遮胸，","notes":[]},{"n":15,"t":"又用和平的福音当作预备走路的鞋穿在脚上。","notes":[]},{"n":16,"t":"此外，要拿信德当作盾牌，用来扑灭那恶者一切烧着的箭。","notes":[]},{"n":17,"t":"要戴上救恩的头盔，拿着圣灵的宝剑—就是神的道。","notes":[]},{"n":18,"t":"要靠着圣灵，随时多方祷告祈求，并要为此警醒不倦，为众圣徒祈求。","notes":[]},{"n":19,"t":"也要为我祈求，让我有口才，能放胆开口讲明福音的奥秘，","notes":[]},{"n":20,"t":"我为这福音的奥秘作了带铁链的使者，让我能照着当尽的本分放胆宣讲。","notes":[]},{"n":21,"t":"今有亲爱、忠心服事主的弟兄推基古，为了你们也明白我的事情和我的景况，他会让你们知道一切的事。","notes":[],"heads":["祝福"]},{"n":22,"t":"我特意打发他到你们那里去，好让你们知道我们的情况，又让他安慰你们的心。","notes":[]},{"n":23,"t":"愿平安、慈爱、信心从父神和主耶稣基督归给弟兄们。","notes":["“平安”或译“和平”。"]},{"n":24,"t":"愿所有恒心爱我们主耶稣基督的人都蒙恩惠。","notes":[]}]}},"PHP":{"1":{"heading":"问候","verses":[{"n":1,"t":"基督耶稣的仆人保罗和提摩太写信给住腓立比、在基督耶稣里的众圣徒，以及诸位监督和执事。","notes":[]},{"n":2,"t":"愿恩惠、平安从我们的父神和主耶稣基督归给你们！","notes":["“平安”或译“和平”。"]},{"n":3,"t":"我每逢想念你们，就感谢我的神，","notes":[],"heads":["保罗为腓立比信徒祷告"]},{"n":4,"t":"每逢为你们众人祈求的时候，总是欢欢喜喜地祈求，","notes":[]},{"n":5,"t":"因为从第一天直到如今，你们都同心合意兴旺福音。","notes":[]},{"n":6,"t":"我深信，那在你们心里动了美好工作的，到了耶稣基督的日子必完成这工作。","notes":[]},{"n":7,"t":"我为你们众人有这样的想法原是应当的，因为你们常在我心里；无论我是在捆锁中，在辩明并证实福音的时候，你们都与我一同蒙恩。","notes":[]},{"n":8,"t":"我以基督耶稣的心肠切切想念你们众人，这是神可以为我作证的。","notes":[]},{"n":9,"t":"我所祷告的就是：要你们的爱心，在知识和各样见识上，不断增长，","notes":[]},{"n":10,"t":"使你们能分辨是非，在基督的日子作真诚无可指责的人，","notes":[]},{"n":11,"t":"更靠着耶稣基督结满仁义的果子，归荣耀称赞给神。","notes":[]},{"n":12,"t":"弟兄们，我要你们知道，我所遭遇的事反而使福音更兴旺，","notes":[],"heads":["我活着就是基督"]},{"n":13,"t":"以致御营全军和其余的人都知道我是为基督的缘故受捆锁的；","notes":[]},{"n":14,"t":"而且那在主里的弟兄，多半都因我受的捆锁而笃信不疑，越发放胆无所惧怕地传道。","notes":[]},{"n":15,"t":"有些人传基督是出于嫉妒纷争；有些人是出于好意。","notes":[]},{"n":16,"t":"后者是出于爱心，知道我奉差遣是为福音辩护的。","notes":[]},{"n":17,"t":"前者传基督是出于自私，动机不纯，企图要加增我捆锁的苦楚。","notes":[]},{"n":18,"t":"这又何妨呢？或是假意或是真心，无论如何，只要基督被传开了，为此我就欢喜。我还要欢喜，","notes":[]},{"n":19,"t":"因为我知道，这事藉着你们的祈祷和耶稣基督的灵的帮助，终必使我得到释放。","notes":[]},{"n":20,"t":"这就是我所切慕、所盼望的：没有一事能使我羞愧；反倒凡事坦然无惧，无论是生是死，总要让基督在我身上照常显大。","notes":[]},{"n":21,"t":"因为我活着就是基督，死了就有益处。","notes":[]},{"n":22,"t":"但是，我在肉身活着，若能有工作的成果，我就不知道该挑选什么。","notes":[]},{"n":23,"t":"我处在两难之间：我情愿离世与基督同在，因为这是好得无比的；","notes":[]},{"n":24,"t":"然而，我为你们肉身活着更加要紧。","notes":[]},{"n":25,"t":"既然我这样深信，就知道仍要留在世间，且与你们众人一起存留，使你们在所信的道上又长进又喜乐，","notes":[]},{"n":26,"t":"为了我再到你们那里时，你们在基督耶稣里的夸耀越发加增。","notes":[]},{"n":27,"t":"最重要的是：你们行事为人要与基督的福音相称，这样，无论我来见你们，或不在你们那里，都可以听到你们的景况，知道你们同有一个心志，站立得稳，为福音的信仰齐心努力，","notes":[]},{"n":28,"t":"丝毫不怕敌人的威胁；以此证明他们会沉沦，你们会得救，这是出于神。","notes":[]},{"n":29,"t":"因为你们蒙恩，不但得以信服基督，而且要为他受苦。","notes":[]},{"n":30,"t":"你们的争战，就与你们曾在我身上见过、现在所听到的是一样的。","notes":[]}]},"2":{"heading":"以基督的心为心","verses":[{"n":1,"t":"所以，在基督里若有任何劝勉，若有任何爱心的安慰，若有任何圣灵的团契，若有任何慈悲怜悯，","notes":[]},{"n":2,"t":"你们就要意志相同，爱心相同，有一致的心思，一致的想法，使我的喜乐得以满足。","notes":[]},{"n":3,"t":"凡事不可自私自利，不可贪图虚荣；只要心存谦卑，各人看别人比自己强。","notes":[]},{"n":4,"t":"各人不要单顾自己的事，也要顾别人的事。","notes":[]},{"n":5,"t":"你们当以基督耶稣的心为心：","notes":[]},{"n":6,"t":"他本有神的形像，却不坚持自己与神同等；","notes":["“却不坚持…同等”或译“却不企图攫取与神同等的地位”。"]},{"n":7,"t":"反倒虚己，取了奴仆的形像，成为人的样式；既有人的样子，","notes":[]},{"n":8,"t":"就谦卑自己，存心顺服，以至于死，且死在十字架上。","notes":[]},{"n":9,"t":"所以神把他升为至高，又赐给他超乎万名之上的名，","notes":[]},{"n":10,"t":"使一切在天上的、地上的和地底下的，因耶稣的名，众膝都要跪下，","notes":[]},{"n":11,"t":"众口都要宣认：耶稣基督是主，归荣耀给父神。","notes":[]},{"n":12,"t":"我亲爱的，这样看来，你们向来是顺服的，不但我在你们那里，就是我现在不在你们那里的时候更是顺服的，就当恐惧战兢完成你们自己得救的事；","notes":[],"heads":["在这世上像明光照耀"]},{"n":13,"t":"因为是神在你们心里运行，使你们又立志又实行，为要成就他的美意。","notes":[]},{"n":14,"t":"你们无论做什么事，都不要发怨言起争论，","notes":[]},{"n":15,"t":"好使你们无可指责，诚实无伪，在这弯曲悖谬的世代作神无瑕疵的儿女。你们在这世代中要像明光照耀，","notes":[]},{"n":16,"t":"将生命的道显明出来，使我在基督的日子得以夸耀我没有白跑，也没有徒劳。","notes":[]},{"n":17,"t":"我以你们的信心为供献的祭物，我若被浇献在其上也是喜乐，并且与你们众人一同喜乐。","notes":[]},{"n":18,"t":"你们也要照样喜乐，并且与我一同喜乐。","notes":[]},{"n":19,"t":"我靠主耶稣希望很快能差提摩太去见你们，好让我知道你们的事而心里得着安慰。","notes":[],"heads":["提摩太和以巴弗提"]},{"n":20,"t":"因为我没有别人与我同心，真正关怀你们的事。","notes":[]},{"n":21,"t":"其他的人都求自己的事，并不求耶稣基督的事。","notes":[]},{"n":22,"t":"但你们知道提摩太是经得起考验的，他与我为了福音一同服侍，待我像儿子待父亲一样。","notes":[]},{"n":23,"t":"所以，我一看出我的事怎样了结，我希望立刻差他去，","notes":[]},{"n":24,"t":"但我靠着主自信我不久也会去。","notes":[]},{"n":25,"t":"然而，我想必须差以巴弗提到你们那里去。他是我的弟兄、同工和战友，是你们差遣来供应我需要的。","notes":[]},{"n":26,"t":"他很想念你们众人，并且极其难过，因为你们听见他病了。","notes":["有古卷加“要见”。"]},{"n":27,"t":"他真的生病了，几乎要死。然而神怜悯他，不但怜悯他，也怜悯我，免得我忧上加忧。","notes":[]},{"n":28,"t":"所以，我更要尽快送他回去，好让你们再见到他而喜乐，我也可以减少忧愁。","notes":[]},{"n":29,"t":"故此，你们要在主里欢欢喜喜地接待他，而且要尊重这样的人，","notes":[]},{"n":30,"t":"因他为做基督的工作不顾性命，几乎至死，为要补足你们供应我不够的地方。","notes":[]}]},"3":{"heading":"真正的义","verses":[{"n":1,"t":"末了，我的弟兄们，你们要靠主喜乐。我把这些话再写给你们，对我并不困难，对你们却是妥当的。","notes":[]},{"n":2,"t":"应当防备犬类，防备作恶的，防备妄自行割的。","notes":[]},{"n":3,"t":"因为真受割礼的，就是我们这藉着神的灵敬拜、以基督耶稣为夸耀、不依靠肉体的。","notes":[]},{"n":4,"t":"其实，我也可以靠肉体；若是别人以为他可以依靠肉体，我更可以。","notes":[]},{"n":5,"t":"我出生后第八天受割礼；我是以色列族、便雅悯支派的人，是希伯来人所生的希伯来人。就律法说，我是法利赛人；","notes":[]},{"n":6,"t":"就热心说，我是迫害教会的；就律法上的义说，我是无可指责的。","notes":[]},{"n":7,"t":"只是我先前以为对我是有益的，我现在因基督的缘故而当作是有损的。","notes":[]},{"n":8,"t":"不但如此，我已把万事当作是有损的，因我以认识我主基督耶稣为至宝。我为他已经丢弃万事，看作粪土，为要赢得基督，","notes":[]},{"n":9,"t":"并且得以在他里面，不是有自己因律法而得的义，而是有信基督的义，就是基于信，从神而来的义，","notes":["“有信基督的义”或译“有藉基督的信而来的义”。"]},{"n":10,"t":"使我认识基督，知道他复活的大能，并且知道和他一同受苦，效法他的死，","notes":[]},{"n":11,"t":"或许我也得以从死人中复活。","notes":[]},{"n":12,"t":"这不是说我已经得着了，已经完全了；而是竭力追求，或许可以得着基督耶稣所要我得着的。","notes":["“基督耶稣”：有古卷是“基督”。","“所要我得着的”或译“所以得着我的”。"],"heads":["向着标竿直跑"]},{"n":13,"t":"弟兄们，我不是以为自己已经得着了；我只有一件事，就是忘记背后，努力面前的，","notes":[]},{"n":14,"t":"向着标竿直跑，要得神在基督耶稣里从上面召我来得的奖赏。","notes":[]},{"n":15,"t":"所以，我们中间凡是成熟的人，总要存这样的心；若在什么事上存别样的心，神也会把这些事指示你们。","notes":[]},{"n":16,"t":"然而，我们达到什么地步，就当照这个地步行。","notes":[]},{"n":17,"t":"弟兄们，你们要一同效法我，也当留意看那些效法我们榜样的人。","notes":[]},{"n":18,"t":"因为，我屡次告诉你们，现在又流泪告诉你们：许多人行事是基督十字架的仇敌。","notes":[]},{"n":19,"t":"他们的结局就是灭亡。他们的神明是自己的肚腹；他们以自己的羞辱为光荣，专以地上的事为念。","notes":[]},{"n":20,"t":"我们却是天上的国民，并且等候救主，就是主耶稣基督从天上降临。","notes":[]},{"n":21,"t":"他要按着那能使万有归服自己的大能，把我们这卑贱的身体改变形状，和他自己荣耀的身体相似。","notes":[]}]},"4":{"heading":"保罗的劝导","verses":[{"n":1,"t":"我所亲爱、所想念的弟兄们，你们就是我的喜乐，我的冠冕。我亲爱的，你们应当靠主站立得稳。","notes":[]},{"n":2,"t":"我劝友阿蝶和循都基要在主里同心。","notes":[]},{"n":3,"t":"我也求你这真实同负一轭的，要帮助这两个女人，因为她们在福音上曾与我、革利免和我其余的同工一同劳苦，他们的名字都在生命册上。","notes":[]},{"n":4,"t":"你们要靠主常常喜乐。我再说，你们要喜乐。","notes":[]},{"n":5,"t":"要让众人知道你们谦让的心。主已经近了。","notes":[]},{"n":6,"t":"应当一无挂虑，只要凡事藉着祷告、祈求和感谢，将你们所要的告诉神。","notes":[]},{"n":7,"t":"神所赐那超越人所能了解的平安，必在基督耶稣里，保守你们的心怀意念。","notes":["“平安”或译“和平”；9节同。"]},{"n":8,"t":"末了，弟兄们，凡是真实的、凡是可敬的、凡是公义的、凡是清洁的、凡是可爱的、凡是有美名的，若有什么德行，若有什么称赞，你们都要留意。","notes":[]},{"n":9,"t":"你们从我所学习的，所领受的，所听见的，所看见的事，你们都要继续去做，赐平安的神就必与你们同在。","notes":[]},{"n":10,"t":"我靠主大大喜乐，因为你们关怀我的心如今又表现了出来；其实你们一直都关怀我，只是没有机会罢了。","notes":[],"heads":["为馈赠致谢"]},{"n":11,"t":"我并不是因缺乏而说这话，因为我已经学会无论在什么景况都可以知足。","notes":[]},{"n":12,"t":"我知道怎样处卑贱，也知道怎样处丰富；或饱足或饥饿，或有余或缺乏，任何事情，任何景况，我都得了秘诀。","notes":[]},{"n":13,"t":"我靠着那加给我力量的，凡事都能做。","notes":[]},{"n":14,"t":"然而，你们能和我分担忧患是一件好事。","notes":[]},{"n":15,"t":"腓立比人哪，你们也知道我开始传福音、离开马其顿的时候，在收支的事上，除了你们以外，并没有别的教会和我分担。","notes":[]},{"n":16,"t":"就是我在帖撒罗尼迦，你们也一再差人来供给我的需用。","notes":[]},{"n":17,"t":"我并不求什么馈赠，只求你们的果子不断增多，归在你们的账上。","notes":[]},{"n":18,"t":"但我已经如数收到，并且有余；我已经充足，因我从以巴弗提受了你们的馈赠，当作极美的香气，为神所接纳、所喜悦的祭物。","notes":[]},{"n":19,"t":"我的神必照他荣耀的丰富，在基督耶稣里，使你们一切所需用的都充足。","notes":[]},{"n":20,"t":"愿荣耀归给我们的父神，直到永永远远。阿们！","notes":[]},{"n":21,"t":"请问候在基督耶稣里的各位圣徒。跟我一起的众弟兄都问候你们。","notes":[],"heads":["祝福"]},{"n":22,"t":"众圣徒都问候你们，特别在凯撒家里的人问候你们。","notes":[]},{"n":23,"t":"愿主耶稣基督的恩与你们的灵同在！","notes":[]}]}},"COL":{"1":{"heading":"问候","verses":[{"n":1,"t":"奉神旨意，作基督耶稣使徒的保罗，和我们的弟兄提摩太，","notes":[]},{"n":2,"t":"写信给歌罗西的圣徒，在基督里忠心的弟兄。愿恩惠、平安从我们的父神归给你们！","notes":["“平安”或译“和平”。"]},{"n":3,"t":"我们为你们祷告的时候，常常感谢我们主耶稣基督的父神，","notes":["“父神”：有古卷是“父和神”。"],"heads":["为信徒感谢神"]},{"n":4,"t":"因为听见你们对基督耶稣的信心，并对众圣徒有的爱心。","notes":[]},{"n":5,"t":"这都是因着那给你们存在天上的盼望，它就是你们从前所听见真理的道，就是福音；","notes":[]},{"n":6,"t":"这福音传到你们那里，也传到普天下，并且继续增长，不断结果，正如自从你们听见福音，真正知道神恩惠的日子起，在你们中间也是这样。","notes":[]},{"n":7,"t":"这福音是你们从我们所亲爱、一同作仆人的以巴弗学到的。他为我们作了基督的忠心仆役，","notes":["“我们”：有古卷是“你们”。"]},{"n":8,"t":"也把圣灵赐给你们的爱告诉我们。","notes":[]},{"n":9,"t":"因此，我们自从听见的日子就不住地为你们祷告和祈求，愿你们满有一切属灵的智慧和悟性，真正知道神的旨意，","notes":[],"heads":["基督和他的工作"]},{"n":10,"t":"好使你们行事为人对得起主，凡事蒙他喜悦，在一切善事上结果子，对神的认识更有长进。","notes":[]},{"n":11,"t":"愿你们从他荣耀的权能中，得以在一切事上力上加力，好使你们凡事欢欢喜喜地忍耐宽容，","notes":[]},{"n":12,"t":"又感谢父，使你们配与众圣徒在光明中分享基业。","notes":[]},{"n":13,"t":"他救了我们脱离黑暗的权势，迁移到他爱子的国度里。","notes":[]},{"n":14,"t":"藉着他的爱子，我们得蒙救赎，罪得赦免。","notes":[]},{"n":15,"t":"爱子是那看不见的神之像，是首生的，在一切被造的以先。","notes":["“首生的”或译“长子”；18节同。"]},{"n":16,"t":"因为万有都是在他里面造的，无论是天上的、地上的，能看见的、不能看见的，或是有权位的、统治的，或是执政的、掌权的，一概都是藉着他为着他造的。","notes":["“在他里面”或译“藉着他”。"]},{"n":17,"t":"他在万有之先；万有也靠他而存在。","notes":[]},{"n":18,"t":"他是身体（教会）的头；他是元始，是从死人中复活的首生者，好让他在万有中居首位。","notes":[]},{"n":19,"t":"因为神喜欢使一切的丰盛在他里面居住，","notes":[]},{"n":20,"t":"藉着他，神使万有与自己和好，无论是地上的、天上的，都藉着他在十字架上所流的血促成了和平。","notes":["有古卷没有“藉着他”。"]},{"n":21,"t":"从前你们与神隔绝，心思上与他为敌，行为邪恶；","notes":[]},{"n":22,"t":"但如今，他藉着他儿子肉身的死，已经使你们与他自己和好了，把你们献在他的面前，成为圣洁，没有瑕疵，无可指责。","notes":["“他藉着…和好了”：有古卷是“藉着他儿子肉身的死，你们已经得以跟他和好了”。"]},{"n":23,"t":"只要你们持守信仰，根基稳固，坚定不移，不致动摇，离开了你们从前所听见的福音的盼望；这福音也是传给天下一切被造之物的，我—保罗作了这福音的仆役。","notes":[]},{"n":24,"t":"现在我为你们受苦，倒很快乐；并且为基督的身体，就是为教会，我要在自己的肉身上补满基督未尽的苦难。","notes":[],"heads":["保罗为教会的工作"]},{"n":25,"t":"我照神为你们所赐我的职分作了教会的仆役，要把神的道传得完满；","notes":[]},{"n":26,"t":"这道就是历世历代所隐藏的奥秘，但如今向他的圣徒显明了。","notes":[]},{"n":27,"t":"神要让他们知道，这奥秘在外邦人中有何等丰盛的荣耀；就是基督在你们心里成了得荣耀的盼望。","notes":["“心里”或译“中间”。"]},{"n":28,"t":"我们传扬他，是用诸般的智慧，劝戒各人，教导各人，要把各人在基督里完完全全地献上。","notes":["“要把各人…献上”或译“要使各人在基督里成熟地献上”。"]},{"n":29,"t":"我也为此劳苦，照着他在我里面运用的大能尽心竭力。","notes":[]}]},"2":{"heading":"基督里的丰盛","verses":[{"n":1,"t":"我要你们知道，我为你们和老底嘉人，和所有没有与我见过面的人，是何等地勤奋；","notes":[]},{"n":2,"t":"为要使他们的心得安慰，因爱心互相联络，以致有从确实了解所产生的丰盛，好深知神的奥秘，就是基督；","notes":[]},{"n":3,"t":"在他里面蕴藏着一切智慧和知识。","notes":[]},{"n":4,"t":"我说这话，免得有人用花言巧语迷惑你们。","notes":[]},{"n":5,"t":"虽然我身体不在你们那里，心却与你们同在，很高兴见你们循规蹈矩，对基督的信心也坚固。","notes":[]},{"n":6,"t":"既然你们接受了主基督耶稣，就要靠着他而生活，","notes":[]},{"n":7,"t":"照着你们所领受的教导，在他里面生根建造，信心坚固，充满着感谢的心。","notes":[]},{"n":8,"t":"你们要谨慎，免得有人用他的哲学和虚空的废话，不照着基督，而是照人间的传统和世上粗浅的学说，把你们掳去。","notes":["“世上粗浅的学说”或译“宇宙的星宿”；20-21节同。"]},{"n":9,"t":"因为神本性一切的丰盛都有形有体地居住在基督里面；","notes":[]},{"n":10,"t":"你们在他里面也已经成为丰盛。他是所有执政掌权者的元首。","notes":[]},{"n":11,"t":"你们也在他里面受了不是人手所行的割礼，而是使你们脱去肉体情欲的基督的割礼。","notes":[]},{"n":12,"t":"你们既受洗与他一同埋葬，也就在此礼上，因信那使他从死人中复活的神的作为跟他一同复活。","notes":[]},{"n":13,"t":"你们从前在过犯和未受割礼的肉体中死了，神却赦免了你们一切的过犯，使你们与基督一同活过来，","notes":[]},{"n":14,"t":"涂去了在律例上所写、敌对我们、束缚我们的字据，把它撤去，钉在十字架上。","notes":[]},{"n":15,"t":"基督既将一切执政者、掌权者的权势解除了，就在凯旋的行列中，将他们公开示众，仗着十字架夸胜。","notes":[]},{"n":16,"t":"所以，不要让任何人在饮食上，或节期、初一、安息日等事上评断你们。","notes":[]},{"n":17,"t":"这些原是未来的事的影子，真体却是属基督的。","notes":[]},{"n":18,"t":"不要让人藉着故作谦虚和敬拜天使夺去你们的奖赏。这等人拘泥在所见过的幻象，随着自己的欲望无故地自高自大，","notes":["有古卷是“这等人窥察所没有见过的”。"]},{"n":19,"t":"不紧随元首；其实，由于他全身藉着关节筋络才得到滋养，互相联络，靠神所赐的成长而成长。","notes":[]},{"n":20,"t":"既然你们与基督同死而脱离了世上粗淺的学说，为什么仍像生活在世俗中一样，去服从那“不可拿、不可尝、不可摸”等类的规条呢？","notes":[],"end":21,"heads":["基督里的新生活"]},{"n":22,"t":"这些都是根据人的命令和教导，论到这一切都是一经使用就都败坏了。","notes":[]},{"n":23,"t":"这些规条使人徒有智慧之名，用私意崇拜，自表谦卑，苦待己身，其实在克制肉体的情欲上毫无功效。","notes":[]}]},"3":{"heading":"新生活的本分","verses":[{"n":1,"t":"所以，既然你们已经与基督一同复活，就当求上面的事；那里有基督，坐在神的右边。","notes":[]},{"n":2,"t":"你们要思考上面的事，不要思考地上的事。","notes":[]},{"n":3,"t":"因为你们已经死了，你们的生命与基督一同藏在神里面。","notes":[]},{"n":4,"t":"基督是你们的生命，他显现的时候，你们也要与他一同在荣耀里显现。","notes":[]},{"n":5,"t":"所以，要治死你们在地上的肢体；就如淫乱、污秽、邪情、恶欲和贪婪—贪婪就是拜偶像。","notes":[]},{"n":6,"t":"因这些事，神的愤怒必临到那些悖逆的人。","notes":["“必临到…的人”：有古卷是“必来临”。"]},{"n":7,"t":"当你们在这些事中活着的时候，你们的行为也曾是这样的。","notes":[]},{"n":8,"t":"但现在你们要弃绝这一切的事，就是恼恨、愤怒、恶毒、毁谤和口中污秽的言语。","notes":[]},{"n":9,"t":"不要彼此说谎，因为你们已经脱去旧人和旧人的行为，","notes":[]},{"n":10,"t":"穿上了新人，这新人照着造他的主的形像在知识上不断地更新。","notes":[]},{"n":11,"t":"在这事上并不分希腊人和犹太人，受割礼的和未受割礼的，未开化的人、西古提人、为奴的、自主的；惟独基督是一切，又在一切之内。","notes":[]},{"n":12,"t":"所以，你们既是神的选民，圣洁、蒙爱的人，要穿上怜悯、恩慈、谦虚、温柔和忍耐。","notes":[]},{"n":13,"t":"倘若这人与那人有嫌隙，总要彼此容忍，彼此饶恕；主怎样饶恕了你们，你们也要怎样饶恕人。","notes":["有古卷是“基督”。"]},{"n":14,"t":"除此以外，还要穿上爱心，因为爱是贯通全德的。","notes":[]},{"n":15,"t":"你们要让基督所赐的和平在你们心里作主，也为此蒙召，归为一体。你们还要存感谢的心。","notes":[]},{"n":16,"t":"当用各样的智慧，把基督的道丰丰富富的存在心里，用诗篇、赞美诗、灵歌，彼此教导，互相劝戒，以感恩的心歌颂神。","notes":[]},{"n":17,"t":"你们无论做什么，或说话或行事，都要奉主耶稣的名，藉着他感谢父神。","notes":[]},{"n":18,"t":"你们作妻子的，要顺服自己的丈夫，这在主里面是合宜的。","notes":[]},{"n":19,"t":"你们作丈夫的，要爱你们的妻子，不可虐待她们。","notes":[]},{"n":20,"t":"你们作儿女的，要凡事听从父母，因为这是主所喜悦的。","notes":[]},{"n":21,"t":"你们作父亲的，不要惹儿女生气，恐怕他们会灰心。","notes":[]},{"n":22,"t":"你们作仆人的，要凡事听从你们肉身的主人，不要只在眼前服事，像是讨人喜欢的，总要心存诚实，因为你们敬畏主。","notes":[]},{"n":23,"t":"你们无论做什么，都要从心里做，像是为主做的，不是为人做的；","notes":[]},{"n":24,"t":"因为你们知道，从主那里必得着基业作为赏赐。你们要服侍的是主基督。","notes":[]},{"n":25,"t":"行不义的人必受不义的报应；主并不偏待人。","notes":[]}]},"4":{"heading":"劝导","verses":[{"n":1,"t":"你们作主人的，待仆人要公正，因为知道，你们也有一位主在天上。","notes":[]},{"n":2,"t":"你们要恒切祷告，在祷告中警醒感恩。","notes":[]},{"n":3,"t":"同时，也要为我们祷告，求神给我们开传道的门，能宣讲基督的奥秘，","notes":[]},{"n":4,"t":"使我能按着所该说的话将这奥秘显明出来，我为此而被捆锁。","notes":[]},{"n":5,"t":"你们要把握时机，用智慧与外人来往。","notes":[]},{"n":6,"t":"你们的言谈要时常带着温和，好像用盐调味，让你们知道该怎样应对每一个人。","notes":[]},{"n":7,"t":"推基古是我亲爱的弟兄，忠心的仆役，和我一同作主的仆人；他要把我一切的事都告诉你们。","notes":[],"heads":["最后的问候"]},{"n":8,"t":"我特意打发他到你们那里去，好让你们知道我们的情况，又让他安慰你们的心。","notes":[]},{"n":9,"t":"我又打发一位亲爱忠心的弟兄阿尼西谋同去；他也是你们那里的人。他们会把这里一切的事都告诉你们。","notes":[]},{"n":10,"t":"与我一同坐牢的亚里达古问候你们。巴拿巴的表弟马可也问候你们。关于他，你们已经得到指示；他若到你们那里，你们要接待他。","notes":[]},{"n":11,"t":"称为犹士都的耶数也问候你们。奉割礼的人中，只有这三个人是为神的国与我作同工的，也是使我心里得安慰的。","notes":[]},{"n":12,"t":"有一位你们那里的人，作基督耶稣仆人的以巴弗问候你们。他祷告的时候常为你们竭力祈求，愿你们能站稳而成熟，充分确信神一切的旨意。","notes":["“基督耶稣”：有古卷是“基督”。"]},{"n":13,"t":"他为你们、老底嘉和希拉坡里的弟兄多多劳苦，这是我可以为他作见证的。","notes":[]},{"n":14,"t":"亲爱的医生路加和底马问候你们。","notes":[]},{"n":15,"t":"请问候老底嘉的弟兄以及宁法，和她家里的教会。","notes":["有古卷是“和他们家里”。"]},{"n":16,"t":"你们宣读了这书信，也要交给老底嘉的教会宣读；你们也要宣读从老底嘉转来的书信。","notes":[]},{"n":17,"t":"你们要对亚基布说：“务要完成你从主所领受的职分。”","notes":[]},{"n":18,"t":"我—保罗亲笔问候你们。要记念我在捆锁中。愿恩惠与你们同在！","notes":[]}]}},"1TH":{"1":{"heading":"问候","verses":[{"n":1,"t":"保罗、西拉、提摩太写信给帖撒罗尼迦在父神和主耶稣基督里的教会。愿恩惠、平安归给你们！","notes":["“平安”或译“和平”。"]},{"n":2,"t":"我们为你们众人常常感谢神，祷告的时候提到你们，","notes":[],"heads":["帖撒罗尼迦信徒的信心和榜样"]},{"n":3,"t":"在我们的父神面前，不住地记念你们因信心所做的工作，因爱心所受的劳苦，因盼望我们主耶稣基督所存的坚忍。","notes":[]},{"n":4,"t":"神所爱的弟兄啊，我知道你们是蒙拣选的；","notes":[]},{"n":5,"t":"因为我们的福音传到你们那里，不仅在言语，也在能力，也在圣灵和充足的确信。你们知道，我们在你们那里，为你们的缘故是怎样为人。","notes":[]},{"n":6,"t":"你们成为效法我们，更效法主的人，因圣灵所激发的喜乐，在大患难中领受了真道，","notes":[]},{"n":7,"t":"从此你们作了马其顿和亚该亚所有信主的人的榜样。","notes":[]},{"n":8,"t":"因为主的道已经从你们那里传播出去，你们向神的信心不只在马其顿和亚该亚，就是在各处也都传开了，所以不用我们说什么话。","notes":[]},{"n":9,"t":"因为他们自己已经传讲我们是怎样进到你们那里，你们是怎样离弃偶像，归向神来服侍那又真又活的神，","notes":[]},{"n":10,"t":"等候他儿子从天降临，就是神使他从死人中复活的那位救我们脱离将来愤怒的耶稣。","notes":[]}]},"2":{"heading":"保罗在帖撒罗尼迦的工作","verses":[{"n":1,"t":"弟兄们，你们自己知道我们来到你们那里并不是徒然的。","notes":[]},{"n":2,"t":"我们从前在腓立比蒙难受辱，这是你们知道的，可是我们还是靠着神给我们的勇气，在强烈反对中把神的福音传给你们。","notes":[]},{"n":3,"t":"我们的劝勉不是出于错误，也不是出于污秽，也不是用诡诈。","notes":[]},{"n":4,"t":"但神既然认定我们经得起考验，把福音托付我们，我们就照着传讲，不是要讨人喜欢，而是要讨那考验我们的心的神喜欢。","notes":[]},{"n":5,"t":"因为我们从来没有用过谄媚的话，这是你们知道的，也没有藏着贪心，这是神可以作证的。","notes":[]},{"n":6,"t":"我们作为基督的使徒，虽然可以受人尊重，却没有向你们或向别人求荣耀，反而在你们当中心存温柔，如同母亲哺乳自己的孩子。","notes":[],"end":7},{"n":8,"t":"既然我们这样爱你们，不但乐意将神的福音给你们，连自己的性命也乐意给你们，因为你们是我们所疼爱的。","notes":[]},{"n":9,"t":"弟兄们，你们记念我们的辛苦劳碌，昼夜做工，传神的福音给你们，免得你们任何人受累。","notes":[]},{"n":10,"t":"我们对你们信主的人是何等圣洁、正直、无可指责，这有你们作证，也有神作证。","notes":[]},{"n":11,"t":"正如你们知道，我们待你们好像父亲待自己的儿女一样。","notes":[]},{"n":12,"t":"我们劝勉你们，安慰你们，嘱咐你们，使你们行事对得起那召你们进他自己的国、得他荣耀的神。","notes":[]},{"n":13,"t":"为此，我们也不断地感谢神，因为你们听见我们所传神的道的时候，你们领受了，不以为这是人的道，而以为这确实是神的道，而且在你们信主的人当中运行着。","notes":[]},{"n":14,"t":"弟兄们，你们与犹太地区神的各教会，就是在基督耶稣里的各教会，有同样的遭遇，因为你们也受了同胞的迫害，像他们受了犹太人的迫害一样。","notes":[]},{"n":15,"t":"这些犹太人不但杀了主耶稣和先知们，又把我们赶出去。他们令神不悦，且与众人为敌，","notes":[]},{"n":16,"t":"阻挠我们传道给外邦人，使他们得救，以致常常恶贯满盈，但神的愤怒终于临到他们身上。","notes":[]},{"n":17,"t":"弟兄们，我们被迫暂时与你们分离，身体离开，心却没有；我们极力想法子，渴望见你们的面。","notes":[],"heads":["保罗希望再访问帖撒罗尼迦教会"]},{"n":18,"t":"所以我们很想到你们那里去。我－保罗有一两次要去，只是撒但阻挡了我们。","notes":[]},{"n":19,"t":"当我们的主耶稣再来，我们站在他面前的时候，我们的盼望、喜乐和所夸的冠冕是什么呢？不正是你们吗？","notes":[]},{"n":20,"t":"你们就是我们的荣耀和喜乐！","notes":[]}]},"3":{"heading":"","verses":[{"n":1,"t":"既然我们不能再忍，就决定独自留在雅典，","notes":[]},{"n":2,"t":"于是差派我们在基督福音上作神同工的弟兄提摩太前去，在你们所信的道上坚固你们，劝勉你们，","notes":[]},{"n":3,"t":"免得有人被这些患难动摇。因为你们自己知道，我们受患难原是命定的。","notes":[]},{"n":4,"t":"我们在你们那里的时候，曾预先告诉你们，我们必受患难；你们知道，这果然发生了。","notes":[]},{"n":5,"t":"为此，既然我不能再忍，就差派人去，要知道你们的信心如何，恐怕那诱惑人的果真诱惑了你们，以致我们的劳苦归于徒然。","notes":[]},{"n":6,"t":"但是，提摩太刚从你们那里回来，将你们信心和爱心的好消息报给我们，又说你们常常记念我们，切切想见我们，如同我们想见你们一样。","notes":[]},{"n":7,"t":"所以，弟兄们，我们在一切困苦患难中，因着你们的信心得到鼓励。","notes":[]},{"n":8,"t":"如今你们若靠主站立得稳，我们就得生了。","notes":[]},{"n":9,"t":"我们在神面前，因着你们满有喜乐。为这一切喜乐，我们能用怎样的感谢为你们报答神呢？","notes":[]},{"n":10,"t":"我们昼夜切切祈求要见你们的面，来补足你们信心的不足。","notes":[]},{"n":11,"t":"愿我们的父神自己和我们的主耶稣，为我们开路到你们那里去。","notes":[]},{"n":12,"t":"又愿主使你们彼此相爱的心，和爱众人的心，都能增长，充足，如同我们爱你们一样，","notes":[]},{"n":13,"t":"好坚固你们的心，使你们在我们的主耶稣同他众圣徒来临的时候，在我们父神面前，成为圣洁，无可指责。阿们！","notes":["有古卷没有“阿们！”"]}]},"4":{"heading":"神所悦纳的生活","verses":[{"n":1,"t":"末了，弟兄们，我们靠着主耶稣求你们，劝你们，既然你们领受了我们的教导，知道该怎样行事为人，讨神的喜悦，其实你们也正这样行，我劝你们要更加努力。","notes":[]},{"n":2,"t":"你们原知道，我们凭主耶稣传给你们什么命令。","notes":[]},{"n":3,"t":"神的旨意就是要你们成为圣洁，远避淫行；","notes":[]},{"n":4,"t":"要你们各人知道怎样用圣洁、尊贵控制自己的身体 ，","notes":["“控制自己的身体”或译“与自己的妻子相处”。"]},{"n":5,"t":"不放纵私欲的邪情，像不认识神的外邦人。","notes":[]},{"n":6,"t":"不准有人在这事上越轨，占他弟兄的便宜；因为这一类的事，主必报应，正如我预先对你们说过，又切切警告过你们的。","notes":[]},{"n":7,"t":"神召我们本不是要我们沾染污秽，而是要我们圣洁。","notes":[]},{"n":8,"t":"所以，那弃绝这教导的不是弃绝人，而是弃绝那把自己的圣灵赐给你们的神。","notes":[]},{"n":9,"t":"有关弟兄间的手足之情，不用人写信给你们，因为你们自己蒙了神的教导要彼此相爱。","notes":[]},{"n":10,"t":"你们向全马其顿的众弟兄固然是这样行，但我劝弟兄们要更加努力。","notes":[]},{"n":11,"t":"要立志过安静的生活，管自己的事，亲手做工，正如我们从前吩咐你们的，","notes":["有古卷没有“亲手”。"]},{"n":12,"t":"好使你们的行为能得外人的尊敬，同时也不依赖任何人。","notes":[]},{"n":13,"t":"弟兄们，至于已睡了的人，我们不愿意你们不知道，恐怕你们忧伤，像那些没有指望的人一样。","notes":[],"heads":["主的再临"]},{"n":14,"t":"既然我们信耶稣死了，复活了，那些已经在耶稣里睡了的人，神也必将他们与耶稣一同带来。","notes":[]},{"n":15,"t":"我们照主的话告诉你们一件事：我们这活着还存留到主来临的人，绝不会在那已经睡了的人之先。","notes":[]},{"n":16,"t":"因为，召集令一发，天使长的呼声一叫，神的号角一吹，主必亲自从天降临；那在基督里死了的人必先复活，","notes":[]},{"n":17,"t":"然后我们这些活着还存留的人必和他们一同被提到云里，在空中与主相会。这样，我们就要和主永远同在。","notes":[]},{"n":18,"t":"所以，你们当用这些话彼此劝勉。","notes":[]}]},"5":{"heading":"最后的劝勉与祝福","verses":[{"n":1,"t":"弟兄们，关于那时候和日期，不用人写信给你们，","notes":[]},{"n":2,"t":"因为你们自己明明知道，主的日子来到会像贼在夜间突然来到一样。","notes":[]},{"n":3,"t":"人正说平安稳定的时候，灾祸忽然临到他们，如同阵痛临到怀胎的妇人一样，他们绝逃脱不了。","notes":[]},{"n":4,"t":"弟兄们，你们并不在黑暗里，那日子不会像贼一样临到你们。","notes":[]},{"n":5,"t":"你们都是光明之子，都是白昼之子；我们不属黑夜，也不属幽暗。","notes":[]},{"n":6,"t":"所以，我们不要沉睡，像别人一样，总要警醒谨慎。","notes":[]},{"n":7,"t":"因为睡了的人是在夜间睡，醉了的人是在夜间醉。","notes":[]},{"n":8,"t":"但既然我们属于白昼，就应当谨慎，把信和爱当作护心镜遮胸，把得救的盼望当作头盔戴上。","notes":[]},{"n":9,"t":"因为神不是预定我们受惩罚，而是预定我们藉着我们的主耶稣基督得救。","notes":[]},{"n":10,"t":"他替我们死，让我们无论醒着、睡着，都与他同活。","notes":[]},{"n":11,"t":"所以，你们该彼此劝勉，互相造就，正如你们素常做的。","notes":[]},{"n":12,"t":"弟兄们，我们劝你们要敬重那些在你们中间劳苦的，就是在主里面督导你们、劝戒你们的人。","notes":[]},{"n":13,"t":"又因他们所做的工作，要以爱心格外尊重他们。你们也要彼此和睦。","notes":[]},{"n":14,"t":"弟兄们，我们劝你们，要警戒不守规矩的人，勉励灰心的人，扶助软弱的人，对众人要有耐心。","notes":[]},{"n":15,"t":"你们要谨慎，无论是谁都不要以恶报恶，彼此间和对众人都要追求做好事。","notes":[]},{"n":16,"t":"要常常喜乐，","notes":[]},{"n":17,"t":"不住地祷告，","notes":[]},{"n":18,"t":"凡事谢恩，因为这是神在基督耶稣里向你们所定的旨意。","notes":[]},{"n":19,"t":"不要熄灭圣灵；","notes":[]},{"n":20,"t":"不要藐视先知的讲论。","notes":[]},{"n":21,"t":"但凡事要察验：美善的事要持守，","notes":[]},{"n":22,"t":"各样恶事要禁戒。","notes":[]},{"n":23,"t":"愿赐平安的神亲自使你们完全成圣！愿你们的灵、魂、体得蒙保守，在我们的主耶稣基督来临的时候，完全无可指责。","notes":["“平安”或译“和平”。"]},{"n":24,"t":"那召你们的本是信实的，他必成就这事。","notes":[]},{"n":25,"t":"弟兄们，请也为我们祷告。","notes":["有古卷是“请为”。"]},{"n":26,"t":"用圣洁的吻向众弟兄问安。","notes":[]},{"n":27,"t":"我指着主嘱咐你们，要把这信宣读给众弟兄听。","notes":[]},{"n":28,"t":"愿我们的主耶稣基督的恩惠与你们同在！","notes":[]}]}},"2TH":{"1":{"heading":"问候","verses":[{"n":1,"t":"保罗、西拉和提摩太写信给帖撒罗尼迦、在我们的父神与主耶稣基督里的教会。","notes":[]},{"n":2,"t":"愿恩惠、平安从我们的父神和主耶稣基督归给你们！","notes":["“平安”或译“和平”。","有古卷没有“我们的”。"]},{"n":3,"t":"弟兄们，我们该常常为你们感谢神，这本是合宜的；因为你们的信心格外增长，你们众人彼此相爱的心也都增加。","notes":[],"heads":["基督再来时的审判"]},{"n":4,"t":"所以，我们在神的各教会里为你们夸耀，因为你们在所受的一切压迫患难中仍牢守着耐心和信心。","notes":[]},{"n":5,"t":"这正是神公义判断的明证，使你们配得上他的国，你们就是为这国受苦。","notes":[]},{"n":6,"t":"既然神是公义的，他必以患难报复那加患难给你们的人，","notes":[]},{"n":7,"t":"也必使你们这受患难的人与我们同得平安。那时，主耶稣同他有权能的天使从天上在火焰中显现，要报应那些不认识神和不听从我们的主耶稣福音的人。","notes":[],"end":8},{"n":9,"t":"他们要受惩罚，永远沉沦，与主的面和他权能的荣光隔绝。","notes":[]},{"n":10,"t":"这正是主再来，要在他圣徒的身上得荣耀，就是要使一切信的人感到惊讶的那日子，因为你们信了我们对你们作的见证。","notes":[]},{"n":11,"t":"为此，我们常为你们祷告，愿我们的神看你们与他的呼召相配，又用大能成就你们一切良善的美意和因信心所做的工作，","notes":[]},{"n":12,"t":"使我们主耶稣的名，照着我们的神和主耶稣基督的恩，在你们身上得荣耀，你们也在他身上得荣耀。","notes":[]}]},"2":{"heading":"不法的人","verses":[{"n":1,"t":"弟兄们，关于我们主耶稣基督的来临和我们到他那里聚集，我劝你们：","notes":[]},{"n":2,"t":"无论藉着灵，藉着言语，藉着冒我的名写的书信，说主的日子已经到了，不要轻易动心，也不要惊慌。","notes":[]},{"n":3,"t":"不要让任何人用什么法子欺骗你们，因为那日子以前必有叛教的事，并有那不法的人，那沉沦之子出现。","notes":[]},{"n":4,"t":"那抵挡者高抬自己超过一切称为神明的，和一切受人敬拜的，甚至坐在神的殿里，自称为神。","notes":[]},{"n":5,"t":"我还在你们那里的时候曾把这些事告诉你们，你们不记得吗？","notes":[]},{"n":6,"t":"现在你们也知道那拦阻他的是什么，为要使他到了时机才出现。","notes":[]},{"n":7,"t":"因为那不法的隐秘已经运作，只是现在有一个阻挡的，要等到那阻挡的被除去才会发作，","notes":[]},{"n":8,"t":"那时这不法的人必出现，主耶稣要用口中的气灭绝他，以自己来临的光辉摧毁他。","notes":["“主耶稣”：有古卷是“主”。"]},{"n":9,"t":"这不法的人来，是靠撒但的运作，行各样的异能、神迹和一切虚假的奇事，","notes":[]},{"n":10,"t":"并且在那沉沦的人身上行各样不义的诡诈，因为他们不领受爱真理的心，好让他们得救。","notes":[]},{"n":11,"t":"故此，神就给他们一个引发错误的心，叫他们信从虚谎，","notes":[]},{"n":12,"t":"使一切不信真理、倒喜爱不义的人都被定罪。","notes":[]},{"n":13,"t":"主所爱的弟兄们哪，我们本该常为你们感谢神，因为他拣选你们为初熟的果子，使你们因信真道，又蒙圣灵感化成圣，得到拯救。","notes":["“他拣选你们为初熟的果子”：有古卷是“他从起初拣选了你们”。"],"heads":["被拣选接受救恩"]},{"n":14,"t":"为此，神藉着我们所传的福音呼召你们，好得着我们主耶稣基督的荣光。","notes":[]},{"n":15,"t":"所以，弟兄们，你们要站立得稳，凡所领受的教导，无论是我们口传的，是信上写的，都要坚守。","notes":[]},{"n":16,"t":"愿我们主耶稣基督自己，和那爱我们、开恩将永远的安慰及美好的盼望赐给我们的父神，","notes":[]},{"n":17,"t":"安慰你们的心，并且在一切善行善言上坚固你们！","notes":[]}]},"3":{"heading":"为我们祷告","verses":[{"n":1,"t":"末了，弟兄们，请你们为我们祷告，好让主的道快快传开，得着荣耀，正如在你们中间一样，","notes":[]},{"n":2,"t":"也让我们能脱离无理和邪恶人的手，因为不是人人都有信仰。","notes":[]},{"n":3,"t":"但主是信实的，他要坚固你们，保护你们脱离那邪恶者。","notes":[]},{"n":4,"t":"我们靠主对你们有信心，你们现在遵行，以后也必遵行我们所吩咐的。","notes":[]},{"n":5,"t":"愿主引导你们的心去爱神，并学基督的忍耐！","notes":[]},{"n":6,"t":"弟兄们，我们奉主耶稣基督的名吩咐你们，凡有弟兄懒散，不遵守我们所传授的教导，要远离他。","notes":[],"heads":["警戒懒散的人"]},{"n":7,"t":"你们自己知道该怎样效法我们。因为我们在你们当中从未懒散过，","notes":[]},{"n":8,"t":"也从未白吃人的饭，倒是辛苦劳碌，昼夜做工，免得使你们中间有人受累。","notes":[]},{"n":9,"t":"这并不是因我们没有权柄，而是要给你们作榜样，好让你们效法我们。","notes":[]},{"n":10,"t":"我们在你们那里的时候曾吩咐你们，说若有人不肯做工，就不可吃饭。","notes":[]},{"n":11,"t":"因为我们听说，在你们中间有人懒散，什么工都不做，反倒专管闲事。","notes":[]},{"n":12,"t":"我们靠主耶稣基督吩咐并劝戒这样的人，要安分做工，自食其力。","notes":[]},{"n":13,"t":"弟兄们，你们行善不可丧志。","notes":[]},{"n":14,"t":"若有人不听从我们这信上的话，要把他记下，不和他交往，使他自觉羞愧；","notes":[]},{"n":15,"t":"但不要把他当仇人，要劝他如劝弟兄。","notes":[]},{"n":16,"t":"愿赐平安的主随时随事亲自赐给你们平安！愿主与你们众人同在！","notes":["“平安”或译“和平”；下同。"],"heads":["祝福"]},{"n":17,"t":"我—保罗亲笔向你们问安。凡我的信都以此为记，我的笔迹就是这样。","notes":[]},{"n":18,"t":"愿我们主耶稣基督的恩惠与你们众人同在！","notes":[]}]}},"1TI":{"1":{"heading":"问候","verses":[{"n":1,"t":"奉我们的救主神，和我们的盼望基督耶稣的命令，作基督耶稣使徒的保罗，","notes":[]},{"n":2,"t":"写信给那因信主作我真儿子的提摩太。愿恩惠、怜悯、平安从父神和我们主基督耶稣归给你！","notes":["“平安”或译“和平”。"]},{"n":3,"t":"我往马其顿去的时候，曾劝你留在以弗所，好嘱咐某些人不可传别的教义，","notes":[],"heads":["警告虚伪的教义"]},{"n":4,"t":"也不要听从无稽的传说和冗长的家谱；这样的事只会引起争论，无助于神的计划，这计划是凭着信才能了解的。","notes":[]},{"n":5,"t":"但命令的目的就是爱；这爱是出于清洁的心、无愧的良心和无伪的信心。","notes":[]},{"n":6,"t":"有人偏离了这些而转向空谈，","notes":[]},{"n":7,"t":"想要作律法教师，却不明白自己所讲的是什么，也不知道所主张的是什么。","notes":[]},{"n":8,"t":"我们知道，只要人善用律法，律法是好的；","notes":[]},{"n":9,"t":"因为知道律法不是为义人订立的，而是为不法和叛逆的，不虔诚和犯罪的，不圣洁和恋世俗的，弑父母和杀人的，","notes":[]},{"n":10,"t":"犯淫乱和亲男色的，拐卖人口和说谎话的，并起假誓的，或是为任何违背健全教义的事订立的。","notes":[]},{"n":11,"t":"这是按照可称颂、荣耀之神交托我的福音说的。","notes":[]},{"n":12,"t":"我感谢那赐给我力量的我们的主基督耶稣，因为他认为我可信任，派我服事他。","notes":[],"heads":["感谢神的怜悯"]},{"n":13,"t":"我从前是亵渎、迫害、侮慢神的人；然而我还蒙了怜悯，因为我是在不信、不明白的时候做的。","notes":[]},{"n":14,"t":"而且我们的主的恩典格外丰盛，使我在基督耶稣里有信心和爱心。","notes":[]},{"n":15,"t":"这话可信，值得完全接受：“基督耶稣到世上来是要拯救罪人”，而在罪人中我是个罪魁。","notes":[]},{"n":16,"t":"然而，我蒙了怜悯，好让基督耶稣在我这罪魁身上显明他完全的忍耐，给后来信他得永生的人做榜样。","notes":[]},{"n":17,"t":"愿尊贵、荣耀归给永世的君王，那不朽坏、看不见、独一的神，直到永永远远。阿们！","notes":[]},{"n":18,"t":"我儿提摩太啊，我照从前指着你的预言把这命令交托你，使你能藉着这些预言打那美好的仗，","notes":[]},{"n":19,"t":"常存信心和无愧的良心。有些人丢弃良心，在信仰上触了礁；","notes":[]},{"n":20,"t":"其中有许米乃和亚历山大，我已经把他们交给撒但，让他们学会不再亵渎。","notes":[]}]},"2":{"heading":"有关祷告的指示","verses":[{"n":1,"t":"所以，我劝你，首先要为人人祈求、祷告、代求、感谢；","notes":[]},{"n":2,"t":"为君王和一切在位的，也要如此，使我们能够敬虔端正地过平稳宁静的生活。","notes":[]},{"n":3,"t":"这是好的，在我们的救主神面前可蒙悦纳。","notes":[]},{"n":4,"t":"他愿意人人得救，并得以认识真理。","notes":[]},{"n":5,"t":"因为只有一位神，在神和人之间也只有一位中保，是成为人的基督耶稣。","notes":[]},{"n":6,"t":"他献上自己作人人的赎价；在适当的时候这事已经证实了。","notes":[]},{"n":7,"t":"我为此奉派作传道，作使徒，在信仰和真理上作外邦人的教师。我说的是真话，不是说谎。","notes":[]},{"n":8,"t":"我希望男人举起圣洁的手随处祷告，不发怒，不争论。","notes":[]},{"n":9,"t":"我也希望女人以端正、克制和合乎体统的服装打扮自己，不以编发、金饰、珍珠和名贵衣裳来打扮。","notes":[]},{"n":10,"t":"要有善行，这才与自称为敬畏神的女人相称。","notes":[]},{"n":11,"t":"女人要事事顺服地安静学习。","notes":[]},{"n":12,"t":"我不许女人教导，也不许她管辖男人，只要安静。","notes":[]},{"n":13,"t":"因为亚当先被造，然后才是夏娃；","notes":[]},{"n":14,"t":"亚当并没有受骗，而是女人受骗，陷在过犯里。","notes":[]},{"n":15,"t":"然而，女人若持守信心、爱心，又圣洁克制，就必藉着生产而得救。","notes":[]}]},"3":{"heading":"监督的资格","verses":[{"n":1,"t":"“若有人想望监督的职分，他是在羡慕一件好事”，这话是可信的。","notes":[]},{"n":2,"t":"监督必须无可指责，只作一个妇人的丈夫，有节制、克己、端正，乐意接待外人，善于教导，","notes":[]},{"n":3,"t":"不酗酒，不打人；要温和，不好斗，不贪财。","notes":[]},{"n":4,"t":"要好好管理自己的家，使儿女顺服，凡事庄重。","notes":[]},{"n":5,"t":"人若不知道管理自己的家，怎能照管神的教会呢？","notes":[]},{"n":6,"t":"刚信主的，不可作监督，恐怕他自高自大，落在魔鬼所受的惩罚里。","notes":[]},{"n":7,"t":"监督也必须在教外有好名声，免得被人毁谤，落在魔鬼的罗网里。","notes":[]},{"n":8,"t":"同样，执事也必须庄重，不一口两舌，不好酒，不贪不义之财；","notes":[],"heads":["执事的资格"]},{"n":9,"t":"要存清白的良心固守信仰的奥秘。","notes":[]},{"n":10,"t":"这些人也要先受考验，若没有可责之处，才让他们作执事。","notes":[]},{"n":11,"t":"同样，女执事 也必须庄重，不说闲话，有节制，凡事忠心。","notes":["“女执事”或译“他们的妻子”。"]},{"n":12,"t":"执事只作一个妇人的丈夫，要好好管儿女和自己的家。","notes":[]},{"n":13,"t":"因为善于作执事的，为自己得到美好的地位，并且无惧地坚信在基督耶稣里的信仰。","notes":[]},{"n":14,"t":"我希望尽快到你那里去，所以先把这些事写给你；","notes":[],"heads":["敬虔的奥秘"]},{"n":15,"t":"倘若我延误了，你也可以知道在神的家中该怎样做。这家就是永生神的教会，真理的柱石和根基。","notes":[]},{"n":16,"t":"敬虔的奥秘是公认为伟大的：神在肉身显现，被圣灵称义，被天使看见，被传于外邦，被世人信服，被接在荣耀里。","notes":[]}]},"4":{"heading":"预言有人离弃信仰","verses":[{"n":1,"t":"圣灵明说，在末后的时期必有人离弃信仰，去听信那诱惑人的邪灵和鬼魔的教训。","notes":[]},{"n":2,"t":"这是出于撒谎者的假冒；这些人的良心如同被热铁烙了一般。","notes":[]},{"n":3,"t":"他们禁止嫁娶，又禁戒食物—就是神所造、让那信而明白真理的人存感谢的心领受的。","notes":[]},{"n":4,"t":"神所造之物样样都是好的，若存感谢的心领受，没有一样是不可吃的，","notes":[]},{"n":5,"t":"都因神的话和人的祈祷而成为圣洁了。","notes":[]},{"n":6,"t":"你若把这些事提醒弟兄们，就是基督耶稣的好执事，在信仰的话语和你向来所服从的正确教义上得到了栽培。","notes":[],"heads":["基督耶稣的好执事"]},{"n":7,"t":"要弃绝那世俗的言语和老妇的无稽传说。要在敬虔上操练自己：","notes":[]},{"n":8,"t":"因操练身体有些益处；但敬虔在各方面都有益，它有现今和未来的生命的应许。","notes":[]},{"n":9,"t":"这话可信，值得完全接受。","notes":[]},{"n":10,"t":"我们劳苦，努力正是为此，因为我们的指望在乎永生的神。他是人人的救主，更是信徒的救主。","notes":["有古卷是“遭受谴责”。"]},{"n":11,"t":"你要嘱咐和教导这些事。","notes":[]},{"n":12,"t":"不可叫人小看你年轻，总要在言语、行为、爱心、信心、清洁上，都作信徒的榜样。","notes":[]},{"n":13,"t":"要以宣读圣经，劝勉，教导为念，直等到我来。","notes":[]},{"n":14,"t":"不要忽略你所得的恩赐，就是从前藉着预言、在众长老按手的时候赐给你的。","notes":[]},{"n":15,"t":"这些事你要殷勤去做，并要在这些事上专心，让众人看出你的长进来。","notes":[]},{"n":16,"t":"要谨慎自己和自己的教导，要在这些事上恒心，因为这样做，既能救自己，又能救听你的人。","notes":[]}]},"5":{"heading":"对别人的本分","verses":[{"n":1,"t":"不可严责老年人，要劝他如同父亲。要待年轻人如同弟兄，","notes":[]},{"n":2,"t":"年老妇女如同母亲。要清清洁洁地待年轻妇女如同姊妹。","notes":[]},{"n":3,"t":"要尊敬真正守寡的妇人。","notes":[]},{"n":4,"t":"寡妇若有儿女，或有孙儿女，要让儿孙先在自己家中学习行孝，报答亲恩，因为这在神面前是可蒙悦纳的。","notes":[]},{"n":5,"t":"独居无靠的真寡妇只仰赖神，昼夜不住地祈求祷告。","notes":[]},{"n":6,"t":"但好宴乐的寡妇活着也算是死了。","notes":[]},{"n":7,"t":"这些事，你要嘱咐她们，让她们无可指责。","notes":[]},{"n":8,"t":"若有人不照顾亲属，尤其是自己家里的人，就是背弃信仰，还不如不信的人。","notes":[]},{"n":9,"t":"寡妇登记，年龄必须在六十岁以上，只作一个丈夫的妻子，","notes":[]},{"n":10,"t":"又有行善的名声，就如养育儿女，收留外人，洗圣徒的脚，救济遭难的人，竭力行各样善事。","notes":[]},{"n":11,"t":"至于年轻的寡妇，你要拒绝登记，因为她们情欲冲动、背弃基督的时候，就想嫁人，","notes":[]},{"n":12,"t":"她们因废弃了当初所许的愿而被定罪。","notes":[]},{"n":13,"t":"同时，她们又学了懒惰，习惯于挨家闲逛；不但懒惰，而且说长道短，好管闲事，说些不该说的话。","notes":[]},{"n":14,"t":"所以，我希望年轻的寡妇嫁人，生养儿女，治理家务，不让敌人有辱骂的把柄，","notes":[]},{"n":15,"t":"因为已经有一些人转去随从撒但了。","notes":[]},{"n":16,"t":"信主的妇女若有亲戚是寡妇，要救济她们，不可拖累教会，好使教会能救济真正无助的寡妇。","notes":[]},{"n":17,"t":"善于督导教会的长老，尤其是勤劳讲道教导人的，应该得到加倍的敬奉。","notes":[]},{"n":18,"t":"因为经上说：“牛在踹谷的时候，不可笼住它的嘴”；又说：“工人得工资是应当的。”","notes":[]},{"n":19,"t":"有控告长老的案件，非有两三个证人就不要受理。","notes":[]},{"n":20,"t":"继续犯罪的人，要在众人面前责备他，使其余的人也有所惧怕。","notes":[]},{"n":21,"t":"我在神、基督耶稣和蒙拣选的天使面前嘱咐你要遵守这些话，不可存成见，做事也不可偏心。","notes":[]},{"n":22,"t":"不可急于给人行按手礼；也不可在别人的罪上有份，要保守自己纯洁。","notes":[]},{"n":23,"t":"为了你的胃，又常患病，不要只喝水，要稍微喝点酒。","notes":[]},{"n":24,"t":"有些人的罪是明显的，已先受审判了；有些人的罪是随后跟着来。","notes":[]},{"n":25,"t":"同样，善行也有明显的，就是那不明显的也不能隐藏。","notes":[]}]},"6":{"heading":"假教导和真财富","verses":[{"n":1,"t":"凡负轭作奴隶的，要认为自己的主人配受各样的尊敬，免得神的名和教导被人亵渎。","notes":[]},{"n":2,"t":"奴隶若有信主的主人，不可因他是主内弟兄就轻看他们，更要越发服侍他们，因为得到服侍的益处的正是信徒，是蒙爱的人。你要教导和劝勉这些事。","notes":[]},{"n":3,"t":"若有人传别的教义，不符合我们主耶稣基督纯正的话语与合乎敬虔的教导，","notes":[]},{"n":4,"t":"他是自高自大，一无所知，专好争辩，擅于舌战，因而生出嫉妒、纷争、毁谤、恶意猜疑，","notes":[]},{"n":5,"t":"和心术不正与丧失真理的人不停地争吵，以敬虔为得利的门路。","notes":[]},{"n":6,"t":"其实，敬虔加上知足就是大利。","notes":[]},{"n":7,"t":"因为我们没有带什么到世上来，也不能带什么去；","notes":[]},{"n":8,"t":"只要有衣有食，我们就该知足。","notes":[]},{"n":9,"t":"但那些想要发财的人就陷在诱惑、罗网和许多无知有害的欲望中，使人沉沦，以致败坏和灭亡。","notes":[]},{"n":10,"t":"贪财是万恶之根。有人因贪恋钱财而背离信仰，用许多愁苦把自己刺透了。","notes":[]},{"n":11,"t":"但你这属神的人哪，要逃避这些事；要追求公义、敬虔、信心、爱心、忍耐、温柔。","notes":[],"heads":["美好的仗"]},{"n":12,"t":"你要为信仰打那美好的仗；要持定永生，你为此被召，也已经在许多见证人面前作了那美好的见证。","notes":[]},{"n":13,"t":"我在那赐生命给万物的神面前，并在向本丢．彼拉多作过那美好见证的基督耶稣面前嘱咐你：","notes":["有古卷没有“你”。"]},{"n":14,"t":"要守这命令，毫不玷污，无可指责，直到我们的主耶稣基督显现。","notes":[]},{"n":15,"t":"到了适当的时候都要显明出来：他是那可称颂、独一的权能者，万王之王，万主之主，","notes":[]},{"n":16,"t":"就是那独一不死、住在人不能靠近的光里，是人未曾看见，也是不能看见的。愿尊贵和永远的权能都归给他。阿们！","notes":[]},{"n":17,"t":"至于那些今世富足的人，你要嘱咐他们不要自高，也不要倚赖靠不住的钱财；要倚靠那厚赐万物给我们享受的神。","notes":[]},{"n":18,"t":"又要嘱咐他们行善，在好事上富足，甘心施舍，乐意分享，","notes":[]},{"n":19,"t":"为自己积存财富，而为将来打美好的根基，好使他们能把握那真正的生命。","notes":[]},{"n":20,"t":"提摩太啊，要持守所给你的托付。要躲避世俗的空谈和那假冒知识的矛盾言论。","notes":[]},{"n":21,"t":"有人自称有这知识而偏离了信仰。愿恩惠与你们同在！","notes":[]}]}},"2TI":{"1":{"heading":"问候","verses":[{"n":1,"t":"奉神旨意，按照基督耶稣里所应许的生命，作基督耶稣使徒的保罗，","notes":[]},{"n":2,"t":"写信给我亲爱的儿子提摩太。愿恩惠、怜悯、平安从父神和我们的主基督耶稣归给你！","notes":["“平安”或译“和平”。"]},{"n":3,"t":"我感谢神，就是我接续祖先用纯洁的良心所事奉的神，在祈祷中昼夜不停地想念你。","notes":[],"heads":["忠于福音"]},{"n":4,"t":"我一想起你的眼泪，就急切想见你，好让我满心快乐。","notes":[]},{"n":5,"t":"我记得你无伪的信心，这信心先存在你外祖母罗以和你母亲友妮基的心里，我深信也存在你的心里。","notes":[]},{"n":6,"t":"为这缘故，我提醒你要把神藉着我按手所给你的恩赐再如火挑旺起来。","notes":[]},{"n":7,"t":"因为神赐给我们的不是胆怯的心，而是刚强、仁爱、自制的心。","notes":[]},{"n":8,"t":"所以，不要以给我们的主作见证为耻，也不要以我这为主被囚的为耻；总要靠着神的大能，与我为福音同受苦难。","notes":[]},{"n":9,"t":"神救了我们，以圣召召我们，不是按我们的行为，而是按他的旨意和恩典；这恩典是万古之先在基督耶稣里赐给我们的，","notes":[]},{"n":10,"t":"但如今藉着我们的救主基督耶稣的显现已经表明出来；他把死废去，藉着福音，将不朽的生命彰显出来。","notes":[]},{"n":11,"t":"我为这福音奉派作传道，作使徒，作教师。","notes":[]},{"n":12,"t":"为这缘故，我也受这些苦难。然而，我不以为耻，因为我知道我所信的是谁，也深信他能保全他所交托我的，直到那日。","notes":["“他所交托我的”或译“我所信托他的”。"]},{"n":13,"t":"你从我听到那健全的言论，要用在基督耶稣里的信心和爱心常常守着，作为规范。","notes":[]},{"n":14,"t":"你要靠着那住在我们里面的圣灵，牢牢守住所交托给你那美好的事。","notes":[]},{"n":15,"t":"你知道，所有在亚细亚的人都离弃了我，其中有腓吉路和黑摩其尼。","notes":[]},{"n":16,"t":"愿主怜悯阿尼色弗一家的人，因为他屡次令我欣慰。他不以我的铁链为耻，","notes":[]},{"n":17,"t":"反而一到罗马就急切寻找我，并且找到了。","notes":[]},{"n":18,"t":"愿主使他在那日能蒙主的怜悯。他在以弗所怎样多服事我，你是清楚知道的。","notes":[]}]},"2":{"heading":"基督耶稣的精兵","verses":[{"n":1,"t":"我儿啊，你要在基督耶稣的恩典上刚强起来。","notes":[]},{"n":2,"t":"你在许多见证人面前听见我所教导的，也要交托给那忠心而又能教导别人的人。","notes":[]},{"n":3,"t":"你要和我同受苦难，作基督耶稣的精兵。","notes":[]},{"n":4,"t":"凡当兵的，不让世务缠身，好使那招他当兵的人喜悦。","notes":[]},{"n":5,"t":"运动员在比赛的时候，不按规则就不能得冠冕。","notes":[]},{"n":6,"t":"勤劳的农夫理当先得粮食。","notes":[]},{"n":7,"t":"我所说的话，你要考虑，因为主必在凡事上给你聪明。","notes":[]},{"n":8,"t":"要记得耶稣基督，他是大卫的后裔，从死人中复活；这就是我所传的福音。","notes":[]},{"n":9,"t":"我为这福音受苦难，甚至像犯人一样被捆绑，然而神的话没有被捆绑。","notes":[]},{"n":10,"t":"所以，我为了选民事事忍耐，为使他们也能得到那在基督耶稣里的救恩和永远的荣耀。","notes":[]},{"n":11,"t":"这话是可信的：我们若与基督同死，也必与他同活；","notes":[]},{"n":12,"t":"我们若忍耐到底，也必和他一同作王。我们若不认他，他也必不认我们；","notes":[]},{"n":13,"t":"我们纵然失信，他仍是可信的，因为他不能否认自己。","notes":[]},{"n":14,"t":"你要向众人提醒这些事，在神面前嘱咐他们不可在言词上争辩；这是没有益处的，只能伤害听的人。","notes":["“神”：有古卷是“主”。"],"heads":["无愧的工人"]},{"n":15,"t":"你当竭力在神面前作一个经得起考验、无愧的工人，按着正意讲解真理的话。","notes":[]},{"n":16,"t":"要远避世俗的空谈，因为这等空谈会使人进到更不敬虔的地步。","notes":[]},{"n":17,"t":"他们的话如同毒疮越烂越大；其中有许米乃和腓理徒，","notes":[]},{"n":18,"t":"他们偏离了真理，说复活的事已过去，败坏了好些人的信心。","notes":[]},{"n":19,"t":"然而，神坚固的根基屹立不移；上面有这印记说：“主认得他自己的人”，又说：“凡称呼主名的人总要离开不义。”","notes":[]},{"n":20,"t":"大户人家不但有金器银器，也有木器瓦器；有作为贵重之用的，有作为卑贱之用的。","notes":[]},{"n":21,"t":"人若自洁，脱离卑贱的事，必成为贵重的器皿，成为圣洁，合乎主用，预备行各样的善事。","notes":[]},{"n":22,"t":"你要逃避年轻人的私欲，同那以纯洁的心求告主的人追求公义、信实、仁爱、和平。","notes":[]},{"n":23,"t":"但要弃绝那愚拙无知的辩论，因为你知道这等事只会引起争辩。","notes":[]},{"n":24,"t":"主的仆人不可争辩，只要温和待人，善于教导，恒心忍耐，","notes":[]},{"n":25,"t":"用温柔劝导反对的人。也许神会给他们悔改的心能明白真理，","notes":[]},{"n":26,"t":"让他们这些已被魔鬼掳去顺从他诡计的人能醒悟过来，脱离他的罗网。","notes":[]}]},"3":{"heading":"末世的人性","verses":[{"n":1,"t":"你该知道，末世必有艰难的日子来到。","notes":[]},{"n":2,"t":"那时人会专爱自己，贪爱钱财，自夸，狂傲，毁谤，违背父母，忘恩负义，心不圣洁，","notes":[]},{"n":3,"t":"没有亲情，抗拒和解，好说谗言，不能节制，性情凶暴，不爱良善，","notes":[]},{"n":4,"t":"卖主卖友，任意妄为，自高自大，爱好宴乐，不爱神，","notes":[]},{"n":5,"t":"有敬虔的外貌，却背弃了敬虔的实质，这等人你要避开。","notes":[]},{"n":6,"t":"他们当中有人潜入别人家里，操纵无知的妇女；这些妇女被罪恶压制，被各样的私欲引诱，","notes":[]},{"n":7,"t":"虽然常常学习，终久无法达到明白真理的地步。","notes":[]},{"n":8,"t":"从前雅尼和佯庇怎样反对摩西，这等人也怎样抵挡真理；他们的心地败坏，信仰经不起考验。","notes":[]},{"n":9,"t":"然而，他们没有进步，因为他们的愚昧必在众人面前显露出来，像那两人一样。","notes":[]},{"n":10,"t":"但你已经追随了我的教导、行为、志向、信心、宽容、爱心、忍耐，","notes":[],"heads":["对提摩太的最后指示"]},{"n":11,"t":"以及我在安提阿、以哥念、路司得所遭遇的迫害和苦难。我忍受了何等的迫害！但从这一切苦难中，主都把我救了出来。","notes":[]},{"n":12,"t":"其实，凡立志在基督耶稣里敬虔度日的，也都将受迫害。","notes":[]},{"n":13,"t":"只是作恶的和骗人的将变本加厉，迷惑人也被人迷惑。","notes":[]},{"n":14,"t":"至于你，你要持守所学习的和所确信的，因为你知道是跟谁学的，","notes":[]},{"n":15,"t":"并且知道你从小明白圣经，这圣经能使你因在基督耶稣里的信有得救的智慧。","notes":["“因在基督耶稣里的信”或译“因信基督耶稣”。"]},{"n":16,"t":"圣经都是神所默示的，于教训、督责、使人归正、教导人学义都是有益的，","notes":["“圣经都是神所默示的”或译“凡神所默示的圣经”。"]},{"n":17,"t":"叫属神的人得以完全，预备行各样的善事。","notes":[]}]},"4":{"heading":"最后的吩咐","verses":[{"n":1,"t":"我在神面前，并在将来审判活人死人的基督耶稣面前，凭着他的显现和他的国度郑重地劝戒你：","notes":[]},{"n":2,"t":"务要传道；无论得时不得时总要专心，并以百般的忍耐和各样的教导责备人，警戒人，劝勉人。","notes":[]},{"n":3,"t":"因为时候将到，那时人会厌烦健全的教导，耳朵发痒，就随心所欲地增添好些教师，","notes":[]},{"n":4,"t":"并且掩耳不听真理，偏向无稽的传说。","notes":[]},{"n":5,"t":"至于你，凡事要谨慎，忍受苦难，做传福音的工作，尽你的职分。","notes":[]},{"n":6,"t":"至于我，我已经被浇献，离世的时候到了。","notes":[]},{"n":7,"t":"那美好的仗我已经打过了，当跑的路我已经跑尽了，该信的道我已经守住了。","notes":[]},{"n":8,"t":"从此以后，有公义的冠冕为我存留，就是按着公义审判的主到了那日要赐给我的；不但赐给我，也赐给凡爱慕他显现的人。","notes":[]},{"n":9,"t":"你要赶紧到我这里来。","notes":[]},{"n":10,"t":"因为底马贪爱现今的世界，已经离弃我，往帖撒罗尼迦去了；革勒士往加拉太去；提多往挞马太去；","notes":[]},{"n":11,"t":"只有路加在我这里。你来的时候把马可带来，因为他在服事上于我有益。","notes":["“服事”或译“传道”。"]},{"n":12,"t":"我已经打发推基古往以弗所去。","notes":[]},{"n":13,"t":"我在特罗亚留给加布的那件外衣，你来的时候要带来，那些书也带来，特别是那几卷羊皮的书。","notes":[]},{"n":14,"t":"铜匠亚历山大多方害我；主必照他所行的报应他。","notes":[]},{"n":15,"t":"你也要防备他，因为他极力抗拒我们的话。","notes":[]},{"n":16,"t":"我初次上诉时，没有人前来帮助，竟都离弃了我，但愿这罪不归在他们身上。","notes":[]},{"n":17,"t":"惟有主站在我身边，加给我力量，使我能把福音完整地传开，让所有的外邦人都听见；我也从狮子口里被救出来。","notes":[]},{"n":18,"t":"主必救我脱离一切的凶恶，也必救我进他的天国。愿荣耀归给他，直到永永远远。阿们！","notes":[]},{"n":19,"t":"请向百基拉、亚居拉和阿尼色弗一家的人问安。","notes":[],"heads":["问安与祝福"]},{"n":20,"t":"以拉都在哥林多住下了。特罗非摩病了，我把他留在米利都。","notes":[]},{"n":21,"t":"你要赶紧在冬天以前到我这里来。友布罗、布田、利奴、革老底亚和众弟兄都向你问安。","notes":[]},{"n":22,"t":"愿主与你的灵同在！愿恩惠与你们同在！","notes":[]}]}},"TIT":{"1":{"heading":"问候","verses":[{"n":1,"t":"神的仆人、耶稣基督的使徒保罗，为了使神的选民信从与认识合乎敬虔的真理—","notes":[]},{"n":2,"t":"这真理是在盼望那无谎言的神在万古之先所应许的永生，","notes":[]},{"n":3,"t":"到了适当的时机，藉着传扬福音，把他的道显明了；这传扬的责任是按着我们的救主神的命令交托给我的—","notes":[]},{"n":4,"t":"我写信给在共同的信仰上作我真儿子的提多。愿恩惠、平安从父神和我们的救主基督耶稣归给你！","notes":["“平安”或译“和平”。"]},{"n":5,"t":"我从前把你留在克里特，是要你将那没有办完的事都办妥，又照我所吩咐你的，在各城设立长老。","notes":[],"heads":["提多在克里特的工作"]},{"n":6,"t":"若有无可指责的人，只作一个妇人的丈夫，儿女也是信主的，没有人告他们放荡，不受约束，就可以设立。","notes":[]},{"n":7,"t":"监督既然是神的管家，必须无可指责、不自负、不暴躁、不酗酒、不好斗、不贪财；","notes":[]},{"n":8,"t":"却要乐意接待外人、好善、克己、正直、圣洁、节制，","notes":[]},{"n":9,"t":"坚守合乎教义的可靠之道，就能将健全的教导劝勉人，又能驳倒争辩的人。","notes":[]},{"n":10,"t":"因为也有许多人不受约束，说空话欺哄人，尤其是那些奉割礼的人。","notes":[]},{"n":11,"t":"这些人的口必须堵住，因为他们贪不义之财，将不该教导的事教导人，败坏人的全家。","notes":[]},{"n":12,"t":"克里特人中有一个本地的先知说：“克里特人常说谎话，是恶兽，贪吃懒做。”","notes":[]},{"n":13,"t":"这个见证是真的。为这缘故，你要严厉地责备他们，使他们在信仰上健全。","notes":[]},{"n":14,"t":"不要听犹太人无稽的传说和背弃真理之人的命令。","notes":[]},{"n":15,"t":"在洁净的人，凡物都洁净；在污秽不信的人，什么都不洁净，连心地和天良也都污秽了。","notes":[]},{"n":16,"t":"他们宣称认识神，却在行为上否认他；他们是可憎恶的，是悖逆的，不配做任何好事。","notes":[]}]},"2":{"heading":"健全的教导","verses":[{"n":1,"t":"至于你，你所讲的总要合乎那健全的教导。","notes":[]},{"n":2,"t":"劝老年人要有节制、端正、克己，在信心、爱心、耐心上都要健全。","notes":[]},{"n":3,"t":"又要劝年长的妇女在操守上恭正，不说谗言，不作酒的奴隶，用善道教导人，","notes":[]},{"n":4,"t":"好指教年轻的妇女爱丈夫，爱儿女，","notes":[]},{"n":5,"t":"克己，贞洁，理家，善良，顺服自己的丈夫，免得神的道被毁谤。","notes":[]},{"n":6,"t":"同样，要劝年轻人凡事克己。","notes":[]},{"n":7,"t":"你要显出自己是好行为的榜样，在教导上要正直、庄重，","notes":[]},{"n":8,"t":"言语健全，无可指责，使那反对的人，因说不出我们有什么不好而自觉羞愧。","notes":[]},{"n":9,"t":"要劝仆人顺服自己的主人，凡事讨他的喜悦，不可顶撞他，","notes":[]},{"n":10,"t":"不可私窃财物；要凡事显出完美的忠诚，好事事都能荣耀我们救主神的教导。","notes":[]},{"n":11,"t":"因为，神救众人的恩典已经显明出来，","notes":[]},{"n":12,"t":"训练我们除去不敬虔的心和世俗的情欲，在今世过克己、正直、敬虔的生活，","notes":[]},{"n":13,"t":"等候福乐的盼望，并等候至大的神和我们的救主耶稣基督的荣耀显现。","notes":["“神和我们的救主”或译“神—我们的救主”。"]},{"n":14,"t":"他为我们的缘故舍己，为了要赎我们脱离一切罪恶，又洁净我们作他自己的子民，热心为善。","notes":[]},{"n":15,"t":"这些事你要讲明，要充分运用你的职权劝勉人，责备人。不要让任何人轻看你。","notes":[]}]},"3":{"heading":"热心行善","verses":[{"n":1,"t":"你要提醒众人，叫他们顺服执政的、掌权的，要服从，预备行各样善事。","notes":[]},{"n":2,"t":"不要毁谤，不要争吵，要和气，对众人总要显出温柔。","notes":[]},{"n":3,"t":"我们从前也是无知、悖逆、受迷惑，作各样私欲和宴乐的奴隶，在恶毒、嫉妒中度日，是可恨的，而且彼此相恨。","notes":[]},{"n":4,"t":"但到了我们救主神的恩慈和慈爱显明的时候，","notes":[]},{"n":5,"t":"他救了我们，并不是因我们自己所行的义，而是照他的怜悯，藉着重生的洗和圣灵的更新。","notes":[]},{"n":6,"t":"圣灵就是神藉着我们的救主耶稣基督厚厚地浇灌在我们身上的，","notes":[]},{"n":7,"t":"好让我们因他的恩得称为义，可以凭着永生的盼望成为后嗣。","notes":["“可以凭着…成为后嗣”或译“可以凭着…承受永生”。"]},{"n":8,"t":"这话是可信的。我愿你坚持这些事，使那些已信神的人留心行善。这都是美好且对人有益的。","notes":["“行善”或译“做正经的事业”；14节同。"]},{"n":9,"t":"要远避愚拙的辩论、家谱、纷争和因律法而起的争辩，因为这都是虚妄无益的。","notes":[]},{"n":10,"t":"分门结党的人，警戒过一两次后就要拒绝跟他来往；","notes":[]},{"n":11,"t":"因为你知道这样的人已经背道，常常犯罪，自己定自己的罪了。","notes":[]},{"n":12,"t":"我打发亚提马或推基古到你那里去的时候，你要赶紧往尼哥坡里来见我，因为我已经决定在那里过冬。","notes":[],"heads":["指示和问安"]},{"n":13,"t":"你要赶紧给西纳律师和亚波罗送行，让他们没有缺乏。","notes":[]},{"n":14,"t":"我们的人也该学习行善，帮助有迫切需要的人，这样才不会不结果子。","notes":[]},{"n":15,"t":"跟我同在一起的人都向你问安。请代向在信仰上爱我们的人问安。愿恩惠与你们众人同在！","notes":[]}]}},"PHM":{"1":{"heading":"问候","verses":[{"n":1,"t":"为基督耶稣被囚的保罗，同弟兄提摩太，写信给我们所亲爱的同工腓利门、","notes":[]},{"n":2,"t":"亚腓亚姊妹，和我们的战友亚基布，以及在你家里的教会。","notes":[]},{"n":3,"t":"愿恩惠、平安从我们的父神和主耶稣基督归给你们！","notes":["“平安”或译“和平”。"]},{"n":4,"t":"我在祷告中记念你的时候，常为你感谢我的神，","notes":[],"heads":["腓利门的爱心和信心"]},{"n":5,"t":"因听说你对众圣徒的爱心，和你对主耶稣的信心。","notes":[]},{"n":6,"t":"愿你与人分享信心的时候，能产生功效，让人知道我们所行的各样善事都是为基督做的。","notes":["有古卷是“你们”。"]},{"n":7,"t":"弟兄啊，由于你的爱心，我得到极大的快乐和安慰，因为众圣徒的心从你得到舒畅。","notes":[]},{"n":8,"t":"虽然我靠着基督能放胆吩咐你做该做的事，","notes":[],"heads":["保罗为阿尼西谋请求"]},{"n":9,"t":"可是像我这上了年纪的保罗，现在又是为基督耶稣被囚的，宁可凭着爱心求你，","notes":[]},{"n":10,"t":"就是为我在捆锁中所生的儿子阿尼西谋求你。","notes":["“阿尼西谋”：此名就是“有益处”的意思。"]},{"n":11,"t":"从前他与你没有益处，但如今与你我都有益处。","notes":[]},{"n":12,"t":"我现在打发他回到你那里去，他是我心肝。","notes":[]},{"n":13,"t":"我本来有意将他留下，在我为福音所受的捆锁中替你伺候我。","notes":[]},{"n":14,"t":"但不知道你的意见，我不愿意这样做，好使你的善行不是出于勉强，而是出于自愿。","notes":[]},{"n":15,"t":"他暂时离开你，也许是要让你永远得着他，","notes":[]},{"n":16,"t":"不再是奴隶，而是高过奴隶，是亲爱的弟兄；对我确实如此，何况对你呢！无论在肉身或在主里更是如此。","notes":[]},{"n":17,"t":"所以，你若以我为同伴，就接纳他，如同接纳我一样。","notes":[]},{"n":18,"t":"他若亏负你，或欠你什么，都算在我的账上吧，","notes":[]},{"n":19,"t":"我必偿还。这是我—保罗亲笔写的。我并不用对你说，甚至你自己也亏欠我呢！","notes":[]},{"n":20,"t":"弟兄啊，希望你使我在主里因你得益处，让我的心在基督里得到舒畅。","notes":[]},{"n":21,"t":"我写信给你，深信你必顺服，知道你所要做的，必过于我所说的。","notes":[]},{"n":22,"t":"此外，还请给我预备住处，因为我盼望藉着你们的祷告，必蒙恩回到你们那里去。","notes":[]},{"n":23,"t":"为基督耶稣与我一同坐监的以巴弗问候你。","notes":[],"heads":["最后的问安"]},{"n":24,"t":"我的同工马可、亚里达古、底马、路加也都问候你。","notes":[]},{"n":25,"t":"愿主耶稣基督的恩与你们的灵同在。","notes":["有古卷加“我们”。","有古卷加“阿们！”"]}]}},"HEB":{"1":{"heading":"神藉着他儿子说话","verses":[{"n":1,"t":"古时候，神藉着众先知多次多方向列祖说话，","notes":[]},{"n":2,"t":"末世，藉着他儿子向我们说话，又立他为承受万有的，也藉着他创造宇宙。","notes":[]},{"n":3,"t":"他是神荣耀的光辉，是神本体的真像，常用他大能的命令托住万有。他洗净了人的罪，就坐在高天至大者的右边。","notes":[]},{"n":4,"t":"他所承受的名比天使的名更尊贵，所以他远比天使崇高。","notes":[],"heads":["神的儿子远超过天使"]},{"n":5,"t":"神曾对哪一个天使说过：“你是我的儿子；我今日生了你”？又说过：“我要作他的父；他要作我的子”呢？","notes":[]},{"n":6,"t":"再者，神引领他长子进入世界的时候，说：“神的使者都要拜他。”","notes":["“长子”或译“首生者”。"]},{"n":7,"t":"关于使者，他说：“神以风为使者，以火焰为仆役。”","notes":[]},{"n":8,"t":"关于子，他却说：“神啊，你的宝座是永永远远的；你国度的权杖是正直的权杖。","notes":[]},{"n":9,"t":"你喜爱公义，恨恶罪恶；所以神，就是你的神，用喜乐油膏你，胜过膏你的同伴。”","notes":[]},{"n":10,"t":"他又说：“主啊，你起初立了地的根基，天也是你手所造的。","notes":[]},{"n":11,"t":"天地都会消灭，你却长存；天地都会像衣服渐渐旧了；","notes":[]},{"n":12,"t":"你要将天地卷起来，像卷一件外衣，天地像衣服都会改变。你却永不改变；你的年数没有穷尽。”","notes":[]},{"n":13,"t":"神曾对哪一个天使说：“你坐在我的右边，等我使你的仇敌作你的脚凳”？","notes":[]},{"n":14,"t":"众天使不都是事奉的灵，奉差遣为那将要承受救恩的人服务的吗？","notes":[]}]},"2":{"heading":"伟大的救恩","verses":[{"n":1,"t":"所以，我们必须越发注意所听见的道，免得我们随流失去。","notes":[]},{"n":2,"t":"既然那藉着天使所传的话是确定的，凡违背不听从的，都受了该受的报应；","notes":[]},{"n":3,"t":"我们若忽略这么大的救恩，怎能逃避呢？这拯救起先是主亲自讲的，后来是听见的人给我们证实了。","notes":[]},{"n":4,"t":"神又按自己的旨意，更用神迹奇事、百般的异能，和圣灵所给的恩赐，与他们一同作见证。","notes":[]},{"n":5,"t":"我们所说将来的世界，神没有交给天使管辖。","notes":[],"heads":["救恩的元帅"]},{"n":6,"t":"但有人在某处证明说：“人算什么，你竟顾念他；世人算什么，你竟眷顾他。","notes":[]},{"n":7,"t":"你使他暂时比天使微小，赐他荣耀尊贵为冠冕，你派他管理你手所造的，","notes":["或译“你使他比天使微小一点”。"]},{"n":8,"t":"使万物都服在他的脚下。”既然使万物都服他，就没有剩下一样不服他的了。只是如今我们还不见万物都服他；","notes":["有古卷是“既然使万物都降服”。"]},{"n":9,"t":"惟独见那成为暂时比天使微小的耶稣，因为受了死的痛苦，得了尊贵荣耀为冠冕，好使他因着神的恩，为人人经历了死亡。","notes":[]},{"n":10,"t":"原来那为万物所属、为万物所本的，为要领许多儿子进入荣耀，使救他们的元帅因受苦难而得以完全，本是合宜的。","notes":[]},{"n":11,"t":"因那使人成圣的，和那些得以成圣的，都是出于一。为这缘故，他称他们为弟兄也不以为耻，","notes":[]},{"n":12,"t":"说：“我要将你的名传给我的弟兄，在会众中我要颂扬你。”","notes":[]},{"n":13,"t":"他又说：“我要依赖他。”他又说：“看哪！我与神所给我的儿女都在这里。”","notes":[]},{"n":14,"t":"既然儿女同有血肉之躯，他也照样亲自成了血肉之躯，为能藉着死败坏那掌管死权的，就是魔鬼，","notes":[]},{"n":15,"t":"并要释放那些一生因怕死而作奴隶的人。","notes":[]},{"n":16,"t":"诚然，他并没有帮助天使，而是帮助了亚伯拉罕的后裔。","notes":[]},{"n":17,"t":"所以，他凡事应当与他的弟兄相同，为要在神的事上成为慈悲忠信的大祭司，为百姓的罪献上赎罪祭。","notes":[]},{"n":18,"t":"既然他自己被试探而受苦，他能帮助被试探的人。","notes":[]}]},"3":{"heading":"耶稣超越摩西","verses":[{"n":1,"t":"同蒙天召的圣洁弟兄啊，要思想我们所宣认为使者、为大祭司的耶稣；","notes":[]},{"n":2,"t":"他向指派他的尽忠，如同摩西向神的全家尽忠一样。","notes":["有古卷没有“全”。"]},{"n":3,"t":"他比摩西配得更多的荣耀，好像建造房屋的人比房屋更尊荣；","notes":[]},{"n":4,"t":"因为房屋都必有人建造，但建造万物的是神。","notes":[]},{"n":5,"t":"摩西作为仆人，向神的全家尽忠，为将来要谈论的事作证；","notes":[]},{"n":6,"t":"但是基督作为儿子，治理神的家。我们若坚持因盼望而有的胆量和夸耀，我们就是他的家了。","notes":[]},{"n":7,"t":"所以，正如圣灵所说：“今日，你们若听他的话，","notes":[],"heads":["神子民的安息"]},{"n":8,"t":"就不可硬着心，像在背叛之时，就如在旷野受试探之日。","notes":[]},{"n":9,"t":"在那里，你们的祖宗试探我，并且观看我的作为，","notes":[]},{"n":10,"t":"有四十年之久。所以，我厌烦那世代，说：他们的心常常迷糊，竟不知道我的道路！","notes":[]},{"n":11,"t":"我在怒中起誓：他们断不可进入我的安息！”","notes":[]},{"n":12,"t":"弟兄们，你们要谨慎，免得你们中间有人存着邪恶不信的心，离弃了永生的神。","notes":[]},{"n":13,"t":"总要趁着还有今日，天天彼此相劝，免得你们中间有人被罪迷惑，心肠刚硬了。","notes":[]},{"n":14,"t":"只要我们将起初确实的信心坚持到底，就在基督里有份了。","notes":[]},{"n":15,"t":"经上说：“今日，你们若听他的话，就不可硬着心，像在背叛之时。”","notes":[]},{"n":16,"t":"听见他而又背叛他的是谁呢？岂不是跟着摩西从埃及出来的众人吗？","notes":[]},{"n":17,"t":"神向谁发怒四十年之久呢？岂不是那些犯罪而陈尸在旷野的人吗？","notes":[]},{"n":18,"t":"他向谁起誓，不容他们进入他的安息呢？岂不是向那些不信从的人吗？","notes":[]},{"n":19,"t":"这样看来，他们不能进入安息是因为不信的缘故了。","notes":[]}]},"4":{"heading":"大祭司耶稣","verses":[{"n":1,"t":"所以，既然进入他安息的应许依旧存在，我们就该存畏惧的心，免得我们 中间有人似乎没有得到安息。","notes":["“我们”：原文直译“你们”。"]},{"n":2,"t":"因为的确有福音传给我们像传给他们一样；只是所听见的道对他们无益，因为他们没有以信心与所听见的道配合。","notes":[]},{"n":3,"t":"但我们已经信的人进入安息，正如神所说：“我在怒中起誓：他们断不可进入我的安息！”其实造物之工，从创世以来已经完成了。","notes":[]},{"n":4,"t":"论到第七日，有一处说：“到第七日，神就歇了他一切工作。”","notes":[]},{"n":5,"t":"又有一处说：“他们断不可进入我的安息！”","notes":[]},{"n":6,"t":"既有这安息保留着让一些人进入，那些先前听见福音的人，因不信从而不得进去，","notes":[]},{"n":7,"t":"所以神多年后藉着大卫的书，又定了一天—“今日”，如以上所引的说：“今日，你们若听他的话，就不可硬着心。”","notes":[]},{"n":8,"t":"若是约书亚已使他们享了安息，后来神就不会再提别的日子了。","notes":[]},{"n":9,"t":"这样看来，另有一安息日的安息为神的子民保留着。","notes":[]},{"n":10,"t":"因为那些进入安息的，也是歇了自己的工作，正如神歇了他的工作一样。","notes":[]},{"n":11,"t":"所以，我们务必竭力进入那安息，免得有人学了不顺从而跌倒了。","notes":[]},{"n":12,"t":"神的道是活泼的，是有功效的，比一切两刃的剑更锋利，甚至魂与灵、骨节与骨髓，都能刺入、剖开，连心中的思念和主意都能辨明。","notes":[]},{"n":13,"t":"被造的，没有一样在他面前不是显露的；万物在他眼前都是赤露敞开的，我们必须向他交账。","notes":[]},{"n":14,"t":"既然我们有一位伟大、进入高天的大祭司，就是耶稣—神的儿子，我们应当持定所宣认的道。","notes":[]},{"n":15,"t":"因为我们的大祭司并非不能体恤我们的软弱；他也在各方面受过试探，与我们一样，只是他没有犯罪。","notes":[]},{"n":16,"t":"所以，我们只管坦然无惧地来到施恩的宝座前，为要得怜悯，蒙恩惠，作及时的帮助。","notes":[]}]},"5":{"heading":"警戒叛道的人","verses":[{"n":1,"t":"凡从人间挑选的大祭司都是奉派替人办理属神的事，要为罪献上礼物和祭物。","notes":["“要为罪献上礼物和祭物”或译“为要献上礼物和赎罪祭”。"]},{"n":2,"t":"他能体谅无知和迷失的人，因为他自己也是被软弱所困，","notes":[]},{"n":3,"t":"因此他理当为百姓和自己的罪献祭。","notes":[]},{"n":4,"t":"没有人可擅自取得大祭司的尊荣，惟有蒙神所选召的才可以，像亚伦一样。","notes":[]},{"n":5,"t":"同样，基督也没有自取作大祭司的荣耀，而是在乎向他说话的那一位，他说：“你是我的儿子，我今日生了你。”","notes":[]},{"n":6,"t":"就如又有一处说：“你是照着麦基洗德的体系永远为祭司。”","notes":[]},{"n":7,"t":"基督在他肉身的日子，曾大声哀哭，流泪祷告，恳求那能救他免死的神，就因他的虔诚蒙了应允。","notes":[]},{"n":8,"t":"他虽然为儿子，还是因所受的苦难学了顺从。","notes":[]},{"n":9,"t":"既然他得以完全，就为凡顺从他的人成了永远得救的根源，","notes":[]},{"n":10,"t":"并蒙神照着麦基洗德的体系宣称他为大祭司。","notes":[]},{"n":11,"t":"论到这事，我们有好些话要说，可是很难解释，因为你们听不进去。","notes":[]},{"n":12,"t":"按时间说，你们早该作教师了，谁知还需要有人再将神圣言基础的要道教导你们；你们成了那需要吃奶、不能吃干粮的人。","notes":[]},{"n":13,"t":"凡只能吃奶的，就不熟练仁义的道理，因为他是婴孩。","notes":[]},{"n":14,"t":"惟独长大成人的才能吃干粮，他们的心窍因练习而灵活，能分辨善恶了。","notes":[]}]},"6":{"heading":"神确切的应许","verses":[{"n":1,"t":"所以，我们应当离开基督道理的基础，竭力进到成熟的地步；不必再立根基，就如懊悔致死的行为、信靠神、","notes":[]},{"n":2,"t":"各样洗礼、按手礼、死人复活，以及永远的审判等的教导。","notes":[]},{"n":3,"t":"神若准许，我们就这样做。","notes":[]},{"n":4,"t":"论到那些已经蒙了光照、尝过天恩的滋味、又于圣灵有份、并尝过神的话的美味，和来世权能的人，若再离弃真道，就不可能使他们重新懊悔了；因为他们亲自把神的儿子重钉十字架，公然羞辱他。","notes":[],"end":6},{"n":7,"t":"就如一块田地吸收过屡次下的雨水，生长蔬菜，合乎耕种的人用，就从神得福。","notes":[]},{"n":8,"t":"这块田地若长荆棘和蒺藜，必被废弃，近于诅咒，结局就是焚烧。","notes":[]},{"n":9,"t":"亲爱的，虽然这样说，我们仍深信你们有更好的情况，更接近救恩。","notes":[]},{"n":10,"t":"因为神并非不公义，竟忘记你们的工作和你们为他的名所显的爱心，就是你们过去和现在伺候圣徒的爱心。","notes":[]},{"n":11,"t":"我们盼望你们各人都显出同样的热忱，一直到底，好达成所确信的指望。","notes":[]},{"n":12,"t":"这样你们才不会懒惰，却成为效法那些藉着信和忍耐承受应许的人。","notes":[]},{"n":13,"t":"当初神应许亚伯拉罕的时候，因为没有比自己更大的可以指着起誓，就指着自己起誓，","notes":[]},{"n":14,"t":"说：“我必多多赐福给你；我必使你大大增多。”","notes":[]},{"n":15,"t":"这样，亚伯拉罕因恒心等待而得了所应许的。","notes":[]},{"n":16,"t":"人都是指着比自己大的起誓，并且以起誓作保证，了结各样的争论。","notes":[]},{"n":17,"t":"照样，神愿意为那承受应许的人更有力地显明他的旨意不可更改，他以起誓作保证。","notes":[]},{"n":18,"t":"藉这两件不可更改的事—在这些事上，神绝不会说谎—我们这些逃往避难所的人能得到强有力的鼓励，去抓住那摆在我们前头的指望。","notes":[]},{"n":19,"t":"我们有这指望，如同灵魂的锚，又坚固又牢靠，进入幔子后面的至圣所。","notes":[]},{"n":20,"t":"为我们作先锋的耶稣，既照着麦基洗德的体系成了永远的大祭司，已经进入了。","notes":[]}]},"7":{"heading":"麦基洗德的祭司体系","verses":[{"n":1,"t":"这麦基洗德就是撒冷王，是至高神的祭司。他在亚伯拉罕打败诸王回来的时候迎接他，并给他祝福。","notes":[]},{"n":2,"t":"亚伯拉罕也将自己所得来的一切，取十分之一给他。他头一个名字翻译出来是“公义的王”，他又名“撒冷王”，是和平王的意思。","notes":[]},{"n":3,"t":"他无父、无母、无族谱、无生之始、无命之终，是与神的儿子相似，他永远作祭司。","notes":[]},{"n":4,"t":"你们想一想，这个人多么伟大啊！连先祖亚伯拉罕都拿战利品的十分之一给他。","notes":[]},{"n":5,"t":"那得祭司职分的利未子孙，奉命照例向百姓取十分之一，这百姓是自己的弟兄，虽是从亚伯拉罕亲身生的，还是照例取十分之一。","notes":[]},{"n":6,"t":"惟独麦基洗德那不与他们同族谱的，从亚伯拉罕收取了十分之一，并且给蒙应许的亚伯拉罕祝福。","notes":[]},{"n":7,"t":"向来位分大的给位分小的祝福，这是无可争议的。","notes":[]},{"n":8,"t":"在这事上，一方面，收取十分之一的都是必死的人；另一方面，收取十分之一的却是那位被证实是活着的。","notes":[]},{"n":9,"t":"我们可以说，那接受十分之一的利未也是藉着亚伯拉罕纳了十分之一，","notes":[]},{"n":10,"t":"因为麦基洗德迎接亚伯拉罕的时候，利未还在他先祖的身体里面。","notes":[]},{"n":11,"t":"那么，如果百姓藉着利未人的祭司职任能达到完全—因为百姓是在这职分下领受律法的—为什么还需要按照麦基洗德的体系另外兴起一位祭司，而不按照亚伦的体系呢？","notes":[]},{"n":12,"t":"既然祭司的职分已更改，律法也需要更改。","notes":[]},{"n":13,"t":"因为这些话所指的人本属别的支派，那支派里从来没有一人在祭坛前事奉的。","notes":[]},{"n":14,"t":"很明显地，我们的主是从犹大出来的；但关于这支派，摩西并没有提到祭司。","notes":[]},{"n":15,"t":"倘若有另一位像麦基洗德的祭司兴起来，我的话就更显而易见了。","notes":[]},{"n":16,"t":"他成为祭司，并不是照属肉身的条例，而是照无穷生命的大能。","notes":["“无穷”：原文直译“不能毁坏”。"]},{"n":17,"t":"因为有给他作见证的说：“你是照着麦基洗德的体系永远为祭司。”","notes":[]},{"n":18,"t":"一方面，先前的诫命因软弱无能而废掉了，","notes":[]},{"n":19,"t":"（律法本来就不能成就什么）；另一方面，一个更好的指望被引进来，靠这指望，我们就可以亲近神。","notes":[]},{"n":20,"t":"再者，耶稣成为祭司，并不是没有神的誓言；其他的祭司被指派时并没有这种誓言，","notes":[]},{"n":21,"t":"只有耶稣是起誓立的，因为那位立他的对他说：“主起了誓，绝不改变。你是永远为祭司。”","notes":[]},{"n":22,"t":"既是起誓立的，耶稣也作了更美之约的中保。","notes":[]},{"n":23,"t":"一方面，那些成为祭司的数目本来多，是因为受死亡限制不能长久留住。","notes":[]},{"n":24,"t":"另一方面，这位既是永远留住的，他具有不可更换的祭司职任。","notes":[]},{"n":25,"t":"所以，凡靠着他进到神面前的人，他都能拯救到底，因为他长远活着为他们祈求。","notes":[]},{"n":26,"t":"这样一位圣洁、无邪恶、无玷污、远离罪人、高过诸天的大祭司，对我们是最合适的；","notes":[]},{"n":27,"t":"他不像那些大祭司，每日必须先为自己的罪，后为百姓的罪献祭，因为他只一次将自己献上就把这事成全了。","notes":[]},{"n":28,"t":"律法所立的大祭司本是有弱点的人，但在律法以后，神以起誓的话立了儿子为大祭司，成为完全，直到永远。","notes":[]}]},"8":{"heading":"更新更美之约的大祭司","verses":[{"n":1,"t":"我们所讲的事，其中第一要紧的就是：我们有这样一位大祭司，他已经坐在天上至大者宝座的右边，","notes":[]},{"n":2,"t":"在圣所，就是在真帐幕里作仆役；这帐幕是主所支搭的，不是人所支搭的。","notes":[]},{"n":3,"t":"凡大祭司都是为献礼物和祭物设立的，所以这位大祭司也必须有所献上。","notes":[]},{"n":4,"t":"他若在地上，就不用作祭司，因为已经有照律法献礼物的祭司了。","notes":[]},{"n":5,"t":"他们所供奉的本是天上之事的样式和影像，正如摩西将要造帐幕的时候，神警戒他，说：“要谨慎，一切都要照着在山上指示你的样式去做。”","notes":[]},{"n":6,"t":"如今耶稣已经得了更优越的事奉，正如他作更美之约的中保；这约原是凭更美之应许立的。","notes":[]},{"n":7,"t":"第一个约若没有瑕疵，就无须寻求第二个约了。","notes":[]},{"n":8,"t":"所以神指责他们说：“主说，看哪，日子将到，我要与以色列家和犹大家另立新的约；","notes":[]},{"n":9,"t":"不像我拉着他们祖宗的手领他们出埃及地的时候，与他们所立的约；因为他们不恒心守我的约，所以我也不理他们；这是主说的。","notes":[]},{"n":10,"t":"主又说：那些日子以后，我与以色列家所立的约是这样：我要将我的律法放在他们的心思里，写在他们的心上；我要作他们的神，他们要作我的子民。","notes":[]},{"n":11,"t":"他们各人不用教导自己的乡亲和自己的弟兄，说：你要认识主；因为从最小的到最大的，他们都要认识我。","notes":[]},{"n":12,"t":"我要宽恕他们的不义，绝不再记得他们的罪恶。”","notes":[]},{"n":13,"t":"既然神提到“新的约”，那么第一个约就成为旧的了；而那渐旧渐衰的必然很快消逝了。","notes":[]}]},"9":{"heading":"地上和天上的圣所","verses":[{"n":1,"t":"原来连第一个约都有敬拜的礼仪和属世界的圣幕。","notes":[]},{"n":2,"t":"因为那预备好了的帐幕，第一层叫圣所，里面有灯台、供桌和供饼。","notes":[]},{"n":3,"t":"第二层幔子后又有一层帐幕，叫至圣所，","notes":[]},{"n":4,"t":"有金香坛和四周包金的约柜，柜里有盛吗哪的金罐、亚伦那根发过芽的杖和两块约版；","notes":[]},{"n":5,"t":"柜上面有荣耀的基路伯罩着施恩座。有关这一切我现在不能一一细说。","notes":[]},{"n":6,"t":"这些物件既如此预备齐了，众祭司就不断地进第一层帐幕行拜神的礼。","notes":[]},{"n":7,"t":"至于第二层帐幕，惟有大祭司一年一次独自进去，没有一次不带着血，为自己献上，也为百姓无意所犯的过错献上。","notes":[]},{"n":8,"t":"圣灵藉此指明，第一层帐幕仍存在的时候，进入至圣所的路还没有显示。","notes":[]},{"n":9,"t":"那第一层帐幕是现今时代的一个预表，表示所献的礼物和祭物都不能使敬拜的人在良心上得以完全。","notes":[]},{"n":10,"t":"这些事只不过是有关饮食和各种洁净的规矩，是属肉体的条例，它的功效是直到新次序的时期来到为止。","notes":[]},{"n":11,"t":"但现在基督已经来到，作了已实现的美事的大祭司，经过那更大更全备的帐幕，不是人手所造，也不是属于这世界的；","notes":[]},{"n":12,"t":"他不用山羊和牛犊的血，而是用自己的血，只一次进入至圣所就获得了永远的赎罪。","notes":[]},{"n":13,"t":"若山羊和公牛的血，以及母牛犊的灰，洒在不洁的人身上，尚且使人成圣，身体洁净，","notes":[]},{"n":14,"t":"何况基督的血，他藉着永远的灵把自己无瑕疵地献给神，更能洗净我们的良心，除去致死的行为，好事奉那位永生的神。","notes":["“我们”：有古卷是“你们”。"]},{"n":15,"t":"为此，基督作了新约的中保；因为他的死，赎了人在第一个约之时所犯的罪过，使蒙召的人能得着所应许永远的产业。","notes":[]},{"n":16,"t":"凡有遗嘱，必须证实立遗嘱的人已经死了。","notes":[]},{"n":17,"t":"因为人死了，遗嘱才有效力；立遗嘱的人尚在，遗嘱就不能生效。","notes":[]},{"n":18,"t":"所以，第一个约也是用血立的。","notes":[]},{"n":19,"t":"因为摩西当日照着律法将各样诫命传给众百姓，就拿朱红色绒和牛膝草，把牛犊、山羊的血和水洒在书上，又洒在众百姓身上，","notes":["有古卷没有“山羊”。"]},{"n":20,"t":"说：“这血就是神与你们立约的凭据。”","notes":[]},{"n":21,"t":"他又照样把血洒在帐幕和敬拜用的各样器皿上。","notes":[]},{"n":22,"t":"按着律法，几乎每样东西都是用血洁净的；没有流血，就没有赦罪。","notes":[]},{"n":23,"t":"这样，照着天上样式做的物件必须用这些礼仪去洁净，但那天上的一切，自然当用更美的祭物去洁净。","notes":[],"heads":["基督献己为祭除掉了罪"]},{"n":24,"t":"因为基督并没有进了人手所造的圣所—这不过是真圣所的影像—而是进到天上，如今为我们出现在神面前。","notes":[]},{"n":25,"t":"他也无须多次将自己献上，像大祭司每年带着牛羊的血进入至圣所。","notes":[]},{"n":26,"t":"如果这样，他从创世以来就必须多次受苦了。但如今，他在今世的末期显现，仅一次把自己献为祭，好除掉罪。","notes":[]},{"n":27,"t":"按着命定，人人都有一死，死后且有审判。","notes":[]},{"n":28,"t":"同样，基督既然一次献上，担当了许多人的罪，将来要第二次显现，与罪无关，而是为了拯救热切等候他的人。","notes":[]}]},"10":{"heading":"劝勉和警告","verses":[{"n":1,"t":"既然律法只不过是未来美好事物的影子，不是本体的真像，就不能藉着每年常献一样的祭物，使那些进前来的人完全。","notes":[]},{"n":2,"t":"若不然，献祭的事岂不早已停止了吗？因为敬拜的人仅只一次洁净，良心就不再觉得有罪了。","notes":[]},{"n":3,"t":"但是这些祭物使人每年都想起罪来，","notes":[]},{"n":4,"t":"因为公牛和山羊的血不能除罪。","notes":[]},{"n":5,"t":"所以，基督到世上来的时候，就说：“祭物和礼物不是你所要的，但你曾给我预备了身体。","notes":[]},{"n":6,"t":"燔祭和赎罪祭是你不喜欢的。","notes":[]},{"n":7,"t":"那时我说：看哪！我来了，我的事在经卷上已经记载了；神啊！我来为要照你的旨意行。”","notes":[]},{"n":8,"t":"以上说：“祭物和礼物，以及燔祭和赎罪祭，不是你所要的，也不是你喜欢的。”这都是按着律法献的。","notes":[]},{"n":9,"t":"他接着说：“看哪！我来了，为要照你的旨意行。”可见他除去在先的，为要立定在后的。","notes":[]},{"n":10,"t":"我们凭着这旨意，藉着耶稣基督，仅只一次献上他的身体就得以成圣。","notes":[]},{"n":11,"t":"所有的祭司天天站着事奉神，屡次献上一样的祭物，这祭物永不能除罪。","notes":[]},{"n":12,"t":"但基督献了一次永远有效的赎罪祭，就坐在神的右边，","notes":[]},{"n":13,"t":"从此等候他的仇敌成为他的脚凳。","notes":[]},{"n":14,"t":"因为他仅只一次献祭，就使那些得以成圣的人永远完全。","notes":[]},{"n":15,"t":"圣灵也对我们作证，因为他说过：","notes":[]},{"n":16,"t":"“主说：那些日子以后，我与他们所立的约是这样的：我要将我的律法放在他们的心上，又要写在他们的心思里。”","notes":[]},{"n":17,"t":"并说：“他们的罪恶和他们的过犯，我绝不再记得。”","notes":[]},{"n":18,"t":"这些罪过既已蒙赦免，就不用再为罪献祭了。","notes":[]},{"n":19,"t":"所以，弟兄们，既然我们靠着耶稣的血得以坦然进入至圣所，","notes":[]},{"n":20,"t":"是藉着他给我们开了一条又新又活的路，从幔子经过，这幔子就是他的身体。","notes":[]},{"n":21,"t":"既然我们有一位伟大祭司治理神的家，","notes":[]},{"n":22,"t":"那么，我们该用诚心和充足的信心，同已蒙洁净、无亏的良心，和清水洗净了的身体来亲近神。","notes":[]},{"n":23,"t":"我们要坚守所宣认的指望，毫不动摇，因为应许我们的那位是信实的。","notes":[]},{"n":24,"t":"我们要彼此相顾，激发爱心，勉励行善；","notes":[]},{"n":25,"t":"不可停止聚会，好像那些停止惯了的人，倒要彼此劝勉，既然知道那日子临近，就更当如此。","notes":[]},{"n":26,"t":"如果我们领受真理的知识以后仍故意犯罪，就不再有赎罪的祭物，","notes":[]},{"n":27,"t":"惟有战战兢兢等候审判和那将吞灭众敌人的烈火了。","notes":[]},{"n":28,"t":"任何人干犯摩西的律法，凭两个或三个证人，尚且必须处死，不得宽赦，","notes":[]},{"n":29,"t":"更何况践踏神儿子的人，他们将那使他成圣之约的血当作不洁净，又亵慢施恩的圣灵的人，你们想，他不该受更严厉的惩罚吗？","notes":[]},{"n":30,"t":"因为我们知道谁说：“伸冤在我，我必报应。”又说：“主要审判他的百姓。”","notes":[]},{"n":31,"t":"落在永生神的手里真是可怕呀！","notes":[]},{"n":32,"t":"你们要追念往日；你们蒙了光照以后，忍受了许多痛苦的挣扎：","notes":[]},{"n":33,"t":"一面在众人面前公然被毁谤，遭患难；一面陪伴那些受这样苦难的人。","notes":[]},{"n":34,"t":"你们同情那些遭监禁的人，也欣然忍受你们的家业被人抢去，因为你们知道自己有更美好更长存的家业。","notes":[]},{"n":35,"t":"所以，不可丢弃你们无惧的心，存这样的心必得大赏赐。","notes":[]},{"n":36,"t":"你们必须忍耐，使你们行完了神的旨意，可以获得所应许的。","notes":[]},{"n":37,"t":"因为“还有一点点时候，那要来的就来，必不迟延。","notes":[]},{"n":38,"t":"只是我的义人必因信得生；他若退缩，我心就不喜欢他。”","notes":[]},{"n":39,"t":"我们却不是退缩以致沉沦的那等人，而是有信心以致得生命的人。","notes":[]}]},"11":{"heading":"论信","verses":[{"n":1,"t":"信就是对所盼望之事有把握，对未见之事有确据。","notes":[]},{"n":2,"t":"古人因着这信获得了赞许。","notes":[]},{"n":3,"t":"因着信，我们知道这宇宙是藉神的话造成的。这样，看得见的是从看不见的造出来的。","notes":[]},{"n":4,"t":"因着信，亚伯献祭给神比该隐所献的更美，因此获得了赞许为义人，神亲自悦纳了他的礼物。他虽然死了，却因这信仍旧在说话。","notes":[]},{"n":5,"t":"因着信，以诺被接去，得以不见死，人也找不着他，因为神已经把他接去了；只是他被接去以前，已讨得神的喜悦而蒙赞许。","notes":[]},{"n":6,"t":"没有信，就不能讨神的喜悦，因为到神面前来的人必须信有神，并且信他会赏赐寻求他的人。","notes":[]},{"n":7,"t":"因着信，挪亚既蒙神指示他未见的事，动了敬畏的心，造了方舟，使他全家得救。藉此他定了那世代的罪，自己也承受了那从信而来的义。","notes":[]},{"n":8,"t":"因着信，亚伯拉罕蒙召的时候就遵命出去，往将来要承受为基业的地方去；他出去的时候还不知往哪里去。","notes":[]},{"n":9,"t":"因着信，他就在所应许之地作客，好像在异乡，居住在帐棚里，与蒙同一个应许的以撒和雅各一样。","notes":[]},{"n":10,"t":"因为他等候着那座有根基的城，就是神所设计和建造的。","notes":[]},{"n":11,"t":"因着信，撒拉自己已过了生育的年龄还能怀孕，因为她认为应许她的那位是可信的；","notes":["本节或译“因着信，撒拉自己虽然已过了生育的年龄，亚伯拉罕也老了，但还能作父亲，因为他认为应许他的那位是可信的”。"]},{"n":12,"t":"所以，从一个仿佛已死的人竟生出子孙，如同天上的星那样众多，海边的沙那样无数。","notes":[]},{"n":13,"t":"这些人都是存着信心死的，并没有得着所应许的，却从远处观望，且欢喜迎接。他们承认自己在地上是客旅，是寄居的。","notes":[]},{"n":14,"t":"说这样话的人是表明自己要寻找一个家乡。","notes":[]},{"n":15,"t":"他们若想念所离开的家乡，还有回去的机会。","notes":[]},{"n":16,"t":"其实他们所羡慕的是一个更美的，就是在天上的家乡。所以，神并不因他们称他为神而觉得羞耻，因为他已经为他们预备了一座城。","notes":["“称他为神”或译“求告他”。"]},{"n":17,"t":"因着信，亚伯拉罕被考验的时候把以撒献上，这就是那领受了应许的人甘心把自己独生的儿子献上。","notes":[]},{"n":18,"t":"论到这儿子，神曾说：“从以撒生的才要称为你的后裔。”","notes":[]},{"n":19,"t":"他认为神甚至能使人从死人中复活，意味着他得回了他的儿子。","notes":[]},{"n":20,"t":"因着信，以撒指着将来的事给雅各、以扫祝福。","notes":[]},{"n":21,"t":"因着信，雅各临死的时候给约瑟的两个儿子个别祝福，扶着拐杖敬拜神。","notes":[]},{"n":22,"t":"因着信，约瑟临终的时候提到以色列人将来要出埃及，并为自己的骸骨留下遗言。","notes":[]},{"n":23,"t":"因着信，摩西生下来，他的父母见他是个俊美的孩子，把他藏了三个月，并不怕王的命令。","notes":[]},{"n":24,"t":"因着信，摩西长大了不肯称为法老女儿之子。","notes":[]},{"n":25,"t":"他宁可和神的百姓一同受苦，也不愿在罪中享受片刻的欢乐。","notes":[]},{"n":26,"t":"他把为弥赛亚受凌辱看得比埃及的财物更宝贵，因为他想望所要得的赏赐。","notes":[]},{"n":27,"t":"因着信，他离开埃及，不怕王的愤怒，因为他恒心忍耐，如同看见那不能看见的神。","notes":[]},{"n":28,"t":"因着信，他设立逾越节，在门上洒血，免得那毁灭者加害以色列人的长子。","notes":[]},{"n":29,"t":"因着信，他们过红海如行干地；埃及人试着要过去就被淹没了。","notes":[]},{"n":30,"t":"因着信，以色列人围绕耶利哥城七日，城墙就倒塌了。","notes":[]},{"n":31,"t":"因着信，妓女喇合曾友善地接待探子，就没有跟那些不顺从的人一同灭亡。","notes":[]},{"n":32,"t":"我还要说什么呢？若要一一细说基甸、巴拉、参孙、耶弗他、大卫、撒母耳和众先知的事，时间就不够了。","notes":[]},{"n":33,"t":"他们藉着信，制伏了敌国，行了公义，得了应许，堵住了狮子的口，","notes":[]},{"n":34,"t":"灭了烈火的威力，在锋利的刀剑下逃生，从软弱变为刚强，争战中显出勇猛，打退外邦的全军。","notes":[]},{"n":35,"t":"有些妇人得回从死人中复活的亲人。又有人忍受严刑，拒绝被释放，为要得着更美好的复活。","notes":[]},{"n":36,"t":"又有人忍受戏弄、鞭打、捆锁、监禁、各等的磨炼；","notes":[]},{"n":37,"t":"他们被石头打死，被锯锯死，被刀杀，披着绵羊山羊的皮各处奔跑，受贫穷、患难、虐待。","notes":["有古卷加“受试探”。"]},{"n":38,"t":"这世界配不上他们，他们在旷野、山岭、山洞、地穴，飘流无定。","notes":[]},{"n":39,"t":"这些人都是因信获得了赞许，却仍未得着所应许的，","notes":[]},{"n":40,"t":"因为神给我们预备了更美好的事，若没有我们，他们就不能达到完全。","notes":[]}]},"12":{"heading":"主的管教","verses":[{"n":1,"t":"所以，既然我们有这许多见证人如同云彩围绕着我们，就该卸下各样重担和紧紧缠累的罪，以坚忍的心奔那摆在我们前头的路程，","notes":[]},{"n":2,"t":"仰望我们信心的创始成终者耶稣，他因那摆在前面的喜乐，轻看羞辱，忍受了十字架的苦难，如今已坐在神宝座的右边。","notes":[]},{"n":3,"t":"你们要仔细想想这位忍受了罪人如此顶撞的耶稣，你们就不致心灰意懒了。","notes":[]},{"n":4,"t":"你们与罪恶争斗，还没有抵抗到流血的地步。","notes":[]},{"n":5,"t":"你们又忘了神劝你们如同劝儿女的那些话，说：“我儿啊，不可轻看主的管教，被他责备的时候不可灰心；","notes":[]},{"n":6,"t":"因为主所爱的，他必管教，又鞭打他所接纳的每一个孩子。”","notes":[]},{"n":7,"t":"为了受管教，你们要忍受。神待你们如同待儿女。哪有儿女不被父亲管教的呢？","notes":[]},{"n":8,"t":"管教原是众儿女共同所领受的；你们若不受管教，就是私生子，不是儿女了。","notes":[]},{"n":9,"t":"再者，我们曾有肉身之父管教我们，我们尚且敬重他，何况灵性之父，我们岂不更当顺服他而得生命吗？","notes":[]},{"n":10,"t":"肉身之父都是短时间随己意管教我们，惟有灵性之父管教我们是要我们得益处，使我们在他的圣洁上有份。","notes":[]},{"n":11,"t":"凡管教的事，当时不觉得快乐，反觉得痛苦；后来却为那经过锻鍊的人结出平安的果子，就是义的果子。","notes":[]},{"n":12,"t":"所以，你们要把下垂的手举起来，发酸的腿挺直；","notes":[]},{"n":13,"t":"要为自己的脚把道路修直了，使瘸了的腿不再脱臼，反而得到痊愈。","notes":[]},{"n":14,"t":"你们要追求与众人和睦，并要追求圣洁；人非圣洁不能见主。","notes":[],"heads":["警告弃绝神恩典的人"]},{"n":15,"t":"要谨慎，免得有人失去了神的恩典；免得有毒根生出来扰乱你们，因而使许多人沾染污秽，","notes":[]},{"n":16,"t":"免得有人淫乱，或不敬虔如以扫，他因一点点食物把自己长子的名分卖了。","notes":[]},{"n":17,"t":"后来你们知道，他想要承受父亲的祝福，竟被拒绝，虽然流着泪苦求，却得不着门路使他父亲回心转意。","notes":[]},{"n":18,"t":"你们不是来到那可触摸的山，那里有火焰、密云、黑暗、暴风、","notes":[]},{"n":19,"t":"角声，和说话的声音；当时那些听见这声音的，都求不要再向他们说话，","notes":[]},{"n":20,"t":"因为他们担当不起所命令他们的话，说：“靠近这山的，即使是走兽，也要用石头打死。”","notes":[]},{"n":21,"t":"所见的景象极其可怕，以致摩西说：“我恐惧战兢。”","notes":[]},{"n":22,"t":"但是你们是来到锡安山，永生神的城，就是天上的耶路撒冷，那里有千千万万的天使，","notes":[]},{"n":23,"t":"有名字记录在天上众长子的盛会，有审判众人的神和成为完全的义人的灵魂，","notes":[]},{"n":24,"t":"并新约的中保耶稣，以及所洒的血；这血所说的信息比亚伯的血所说的更美。","notes":[]},{"n":25,"t":"你们总要谨慎，不可拒绝那向你们说话的，因为那些拒绝了在地上警戒他们的，尚且不能逃罪，何况我们违背那从天上警戒我们的呢？","notes":[]},{"n":26,"t":"当时他的声音震动了地，但如今他应许说：“再一次我不单要震动地，还要震动天。”","notes":[]},{"n":27,"t":"这“再一次”的话是指明被震动的要像受造之物一样被挪去，使那不被震动的能常存。","notes":[]},{"n":28,"t":"所以，既然我们得了不能被震动的国度，就要感恩，照着神所喜悦的，用虔诚、敬畏的心事奉神，","notes":[]},{"n":29,"t":"因为我们的神是吞灭的火。","notes":[]}]},"13":{"heading":"蒙神悦纳的事奉","verses":[{"n":1,"t":"你们务要常存弟兄相爱的心。","notes":[]},{"n":2,"t":"不可忘记用爱心接待旅客，因为曾经有人这样做，在无意中接待了天使。","notes":[]},{"n":3,"t":"要记念受监禁的人，好像与他们同受监禁；要记念受虐待的人，好像你们也亲身受虐待一样。","notes":[]},{"n":4,"t":"婚姻，人人都当尊重，共眠的床也不可污秽，因为淫乱和通奸的人，神必审判。","notes":[]},{"n":5,"t":"不可贪爱钱财，要以自己所有的为满足，因为神曾说：“我绝不撇下你，也绝不丢弃你。”","notes":[]},{"n":6,"t":"所以，我们可以勇敢地说：“主是我的帮助，我必不惧怕。人能把我怎么样呢？”","notes":[]},{"n":7,"t":"从前引导你们、传神的道给你们的人，你们要记念他们，效法他们的信心，回顾他们为人的结局。","notes":[]},{"n":8,"t":"耶稣基督昨日、今日，一直到永远，是一样的。","notes":[]},{"n":9,"t":"你们不要被种种怪异的教训勾引了去，因为人的心靠恩典得坚固才是好的，并不是靠饮食。那在饮食上用心的，从来没有得到益处。","notes":[]},{"n":10,"t":"我们有一祭坛，上面的祭物是那些在会幕中供职的人无权可吃的。","notes":[]},{"n":11,"t":"因为牲畜的血被大祭司带入至圣所作赎罪祭，牲畜的体却在营外烧掉。","notes":[]},{"n":12,"t":"所以，耶稣也在城门外受苦，为要用自己的血使百姓成圣。","notes":[]},{"n":13,"t":"这样，我们也当走出营外，到他那里去，忍受他所受的凌辱。","notes":[]},{"n":14,"t":"在这里，我们本没有永存的城，而是在寻求那将要来的城。","notes":[]},{"n":15,"t":"我们应当藉着耶稣，常常以颂赞为祭献给神，这是那宣认他名的人嘴唇所结的果子。","notes":[]},{"n":16,"t":"只是不可忘记行善和分享，因为这样的祭物是神所喜悦的。","notes":[]},{"n":17,"t":"你们要服从那些引导你们的，并且要顺服，因为他们为你们的灵魂时刻警醒，像在神面前交账的人，让他们在交账的时候有喜乐，而不是叹息，叹息就对你们无益了。","notes":[]},{"n":18,"t":"请你们为我们祷告；因为我们自觉良心无亏，愿意凡事按正道而行。","notes":[]},{"n":19,"t":"我更求你们为我祷告，使我快些回到你们那里去。","notes":[]},{"n":20,"t":"但愿赐平安的神，就是那凭永约之血，把群羊的大牧人—我们主耶稣从死人中领出来的神，","notes":["“平安”或译“和平”。"],"heads":["祝福和问安"]},{"n":21,"t":"在各样善事上装备你们，使你们遵行他的旨意；又藉着耶稣基督在我们里面行他所喜悦的事。愿荣耀归给他，直到永永远远。阿们！","notes":["“我们”：有古卷是“你们”。","有古卷是“直到永远”。"]},{"n":22,"t":"弟兄们，我简略地写信给你们，希望你们听我劝勉的话。","notes":[]},{"n":23,"t":"你们该知道，我们的弟兄提摩太已经重获自由了；他若很快就来，我必同他去见你们。","notes":[]},{"n":24,"t":"请你们向带领你们的诸位和众圣徒问安。从意大利来的人也向你们问安。","notes":[]},{"n":25,"t":"愿恩惠与你们众人同在。","notes":["有古卷加“阿们！”"]}]}},"JAS":{"1":{"heading":"问候","verses":[{"n":1,"t":"神和主耶稣基督的仆人雅各问候散居在各处的十二个支派的人。","notes":[]},{"n":2,"t":"我的弟兄们，你们遭受各种试炼时，都要认为是大喜乐，","notes":[],"heads":["信心和智慧"]},{"n":3,"t":"因为知道你们的信心经过考验，就生忍耐。","notes":[]},{"n":4,"t":"但要让忍耐发挥完全的功用，使你们能又完全又完整，一无所缺。","notes":[]},{"n":5,"t":"你们中间若有缺少智慧的，该求那厚赐与众人又不斥责人的神，神必赐给他。","notes":[]},{"n":6,"t":"只要凭着信心求，一点也不疑惑；因为那疑惑的人，就像海中的波浪被风吹动翻腾。","notes":[]},{"n":7,"t":"这样的人不要想从主那里得到什么。","notes":[]},{"n":8,"t":"三心二意的人，在他一切所行的路上都摇摆不定。","notes":[]},{"n":9,"t":"卑微的弟兄要因高升而夸耀，","notes":[],"heads":["贫穷和富有"]},{"n":10,"t":"富足的却要因被降卑而夸耀，因为富足的人要消逝，如同草上的花一样。","notes":[]},{"n":11,"t":"太阳出来，热风刮起，草就枯干，花也凋谢，它美丽的样子就消失了；那富足的人在他一生的奔波中也要这样衰残。","notes":[]},{"n":12,"t":"忍受试炼的人有福了，因为他经过考验以后必得生命的冠冕，这是主应许给爱他之人的。","notes":[],"heads":["考验和试探"]},{"n":13,"t":"人被诱惑，不可说：“我是被神诱惑”；因为神是不被恶诱惑的，他也不诱惑人。","notes":[]},{"n":14,"t":"但每一个人被诱惑是因自己的私欲牵引而被诱惑的。","notes":[]},{"n":15,"t":"私欲既怀了胎，就生出罪来；罪既长成，就生出死来。","notes":[]},{"n":16,"t":"我亲爱的弟兄们，不要被欺骗了。","notes":[]},{"n":17,"t":"各样美善的恩泽和各样完美的赏赐都是从上头来的，从众光之父那里降下来的；在他并没有改变，也没有转动的影儿。","notes":[]},{"n":18,"t":"他按自己的旨意，用真理的道生了我们，使我们在他所造的万物中成为初熟的果子。","notes":[]},{"n":19,"t":"我亲爱的弟兄们，你们要明白：你们每一个人要快快地听，慢慢地说，慢慢地动怒，","notes":[],"heads":["听道和行道"]},{"n":20,"t":"因为人的怒气并不能实现神的义。","notes":[]},{"n":21,"t":"所以，你们要除去一切的污秽和累积的恶毒，要存温柔的心领受所栽种的道，就是能救你们灵魂的道。","notes":[]},{"n":22,"t":"但是，你们要作行道的人，不要只作听道的人，自己欺骗自己。","notes":[]},{"n":23,"t":"因为只听道而不行道的，就像人对着镜子观看自己本来的面目，","notes":[]},{"n":24,"t":"注视后，就离开，立刻忘了自己的相貌如何。","notes":[]},{"n":25,"t":"惟有查看那完美、使人自由的律法，并且时常遵守的，他不是听了就忘，而是切实行出来，这样的人在所行的事上必然蒙福。","notes":[]},{"n":26,"t":"若有人自以为虔诚，却不勒住自己的舌头，反欺骗自己的心，这人的虔诚是徒然的。","notes":[]},{"n":27,"t":"在神—我们的父面前，清洁没有玷污的虔诚就是看顾在患难中的孤儿寡妇，并且保守自己不沾染世俗。","notes":[]}]},"2":{"heading":"警告偏私","verses":[{"n":1,"t":"我的弟兄们，你们信奉我们荣耀的主耶稣基督，就不可按着外貌待人。","notes":[]},{"n":2,"t":"若有一个人戴着金戒指，穿着华丽的衣服，进入你们的会堂，又有一个穷人穿着肮脏的衣服也进去，","notes":[]},{"n":3,"t":"而你们只看重那穿华丽衣服的人，说：“请坐在这里”，又对那穷人说：“你站在那里”，或“坐在我脚凳旁”；","notes":[]},{"n":4,"t":"这岂不是你们偏心待人，用恶意评断人吗？","notes":[]},{"n":5,"t":"我亲爱的弟兄们，请听，神岂不是拣选了世上的贫穷人，使他们在信心上富足，并承受他所应许给那些爱他之人的国吗？","notes":[]},{"n":6,"t":"你们却羞辱贫穷的人。欺压你们，拉你们到公堂去的，不就是这些富有的人吗？","notes":[]},{"n":7,"t":"毁谤为你们求告时所奉的尊名的，不就是他们吗？","notes":[]},{"n":8,"t":"经上记着：“要爱邻 如己”，你们若切实守这至尊的律法，你们就做得很好。","notes":["“邻”也可译作“人”。"]},{"n":9,"t":"但你们若按外貌待人就是犯罪，是被律法定为犯法的。","notes":[]},{"n":10,"t":"因为凡遵守全部律法的，只违背了一条就是违犯了所有的律法。","notes":[]},{"n":11,"t":"原来那说“不可奸淫”的，也说“不可杀人”。你就是不奸淫，却杀人，也是成为违犯律法的。","notes":[]},{"n":12,"t":"既然你们要按使人自由的律法受审判，就要照这律法说话行事。","notes":[]},{"n":13,"t":"因为对那不怜悯人的，他们要受没有怜悯的审判；怜悯胜过审判。","notes":[]},{"n":14,"t":"我的弟兄们，若有人说自己有信心，却没有行为，有什么益处呢？这信心能救他吗？","notes":[],"heads":["信心和行为"]},{"n":15,"t":"若是弟兄或是姊妹没有衣服穿，又缺少日用的饮食；","notes":[]},{"n":16,"t":"你们中间有人对他们说：“平平安安地去吧！愿你们穿得暖，吃得饱”，却不给他们身体所需要的，这有什么益处呢？","notes":[]},{"n":17,"t":"信心也是这样，若没有行为是死的。","notes":[]},{"n":18,"t":"但是有人会说：“你有信心，我有行为。”把你没有行为的信心给我看，我就藉着我的行为把我的信心给你看。","notes":[]},{"n":19,"t":"你信神只有一位，你信得很好；连鬼魔也信，且怕得发抖。","notes":[]},{"n":20,"t":"你这虚浮的人哪，你愿意知道没有行为的信心是没有用的吗？","notes":[]},{"n":21,"t":"我们的祖宗亚伯拉罕把他儿子以撒献在坛上，岂不是因行为得称义吗？","notes":[]},{"n":22,"t":"可见信心是与他的行为相辅并行，而且信心是因着行为才得以成全的。","notes":[]},{"n":23,"t":"这正应验了经上所说：“亚伯拉罕信了神，这就算他为义”；他又得称为神的朋友。","notes":[]},{"n":24,"t":"这样看来，人称义是因着行为，不是单因着信。","notes":[]},{"n":25,"t":"同样，妓女喇合接待使者，又放他们从另一条路出去，不也是因行为称义吗？","notes":[]},{"n":26,"t":"所以，就如身体没有灵魂是死的，信心没有行为也是死的。","notes":[]}]},"3":{"heading":"制伏舌头","verses":[{"n":1,"t":"我的弟兄们，不要许多人做教师，因为你们知道，我们做教师的要接受更严厉的审判。","notes":[]},{"n":2,"t":"原来我们在许多事上都有过失；若有人在言语上没有过失，他就是完全的人，也能勒住自己的全身。","notes":[]},{"n":3,"t":"我们若把嚼环放在马嘴里使它们驯服，就能控制它们的全身。","notes":[]},{"n":4,"t":"再看船只，虽然甚大，又被强风猛吹，只用小小的舵就随着掌舵的意思转动。","notes":[]},{"n":5,"t":"同样，舌头是小肢体，却能说大话。看哪，最小的火能点燃最大的树林。","notes":[]},{"n":6,"t":"舌头就是火。在我们百体中，舌头是个不义的世界，能玷污全身，也能烧毁生命的轮子，而且是被地狱的火点燃的。","notes":[]},{"n":7,"t":"各类的走兽、飞禽、爬虫、水族，本来都可以制伏，也已经被人制伏了；","notes":[]},{"n":8,"t":"惟独舌头没有人能制伏，是永不静止的邪恶，充满了害死人的毒气。","notes":[]},{"n":9,"t":"我们用舌头颂赞我们的主—我们的天父，又用舌头诅咒照着神形像被造的人。","notes":[]},{"n":10,"t":"颂赞和诅咒从同一个口出来。我的弟兄们，这是不应该的。","notes":[]},{"n":11,"t":"泉源能从一个出口发出甜苦两样的水吗？","notes":[]},{"n":12,"t":"我的弟兄们，无花果树能生橄榄吗？葡萄树能结无花果吗？咸水也不能流出甜水来。","notes":[]},{"n":13,"t":"你们中间谁是有智慧有见识的呢？他就当在智慧的温柔上显出他的善行来。","notes":[],"heads":["从上头来的智慧"]},{"n":14,"t":"你们心里若怀着恶毒的嫉妒和自私，就不可自夸，不可说谎话抵挡真理。","notes":[]},{"n":15,"t":"这样的智慧不是从上头下来的，而是属地上的，属情欲的，属鬼魔的。","notes":[]},{"n":16,"t":"在何处有嫉妒、自私，在何处就有动乱和各样的坏事。","notes":[]},{"n":17,"t":"惟独从上头来的智慧，先是清洁，后是和平、温良、柔顺，满有怜悯和美善的果子，没有偏私，没有虚伪。","notes":[]},{"n":18,"t":"正义的果实是为促进和平的人用和平栽种出来的。","notes":[]}]},"4":{"heading":"不可与世俗为友","verses":[{"n":1,"t":"你们中间的冲突是哪里来的？争执是哪里来的？不是从你们肢体中交战着的私欲来的吗？","notes":[]},{"n":2,"t":"你们贪恋，得不着就杀人；你们嫉妒，不能得手就起争执和冲突；你们得不着，是因为你们不求。","notes":[]},{"n":3,"t":"你们求也得不着，是因为你们妄求，为了要浪费在你们的宴乐中。","notes":[]},{"n":4,"t":"你们这些淫乱的人哪，岂不知道与世俗为友就是与神为敌吗？所以，凡想要与世俗为友的，就是与神为敌了。","notes":[]},{"n":5,"t":"经上说：“神爱安置在我们里面的灵，爱到嫉妒的地步。”你们以为这话是徒然的吗？","notes":["“神爱…的地步。”或译“神会嫉妒地爱恋他安置在我们里面的灵。”"]},{"n":6,"t":"但是他赐更多的恩典，正如经上说：“神抵挡骄傲的人，但赐恩给谦卑的人。”","notes":[]},{"n":7,"t":"所以，要顺服神。要抵挡魔鬼，魔鬼就必逃避你们；","notes":[]},{"n":8,"t":"要亲近神，神就必亲近你们。有罪的人哪，要洁净你们的手！心怀二意的人哪，要清洁你们的心！","notes":[]},{"n":9,"t":"你们要愁苦，悲哀，哭泣；要将欢笑变为悲哀，欢乐变为愁闷。","notes":[]},{"n":10,"t":"要在主面前谦卑，他就使你们高升。","notes":[]},{"n":11,"t":"弟兄们，不可彼此诋毁。诋毁弟兄或评断弟兄的人，就是诋毁律法，评断律法；你若评断律法，就不是遵行律法，而是评断者了。","notes":[],"heads":["不可评断弟兄"]},{"n":12,"t":"立法者和审判者只有一位；他就是那能拯救人也能毁灭人的。你是谁，竟敢评断你的邻舍！","notes":[]},{"n":13,"t":"注意！有人说：“今天或明天我们要往某城去，在那里住一年，做买卖赚钱。”","notes":[],"heads":["警戒自夸"]},{"n":14,"t":"其实明天如何，你们还不知道。你们的生命是什么呢？你们原来是一片云雾，出现片刻就不见了。","notes":["有古卷是“它”。"]},{"n":15,"t":"你们倒应当说：“主若愿意，我们就能活着，也可以做这事或那事。”","notes":[]},{"n":16,"t":"现今你们竟然狂傲自夸；凡这样的自夸都是邪恶的。","notes":[]},{"n":17,"t":"所以，人若知道该行善而不去行，这就是他的罪了。","notes":[]}]},"5":{"heading":"警告富足的人","verses":[{"n":1,"t":"注意！你们这些富足人哪，要为将要临到你们身上的灾难哭泣、号啕。","notes":[]},{"n":2,"t":"你们的财物腐烂了，你们的衣服被虫子蛀了。","notes":[]},{"n":3,"t":"你们的金银都生锈了；这锈要证明你们的不是，又要像火一样吞吃你们的肉。你们在这末世只知道积蓄钱财。","notes":[]},{"n":4,"t":"工人给你们收割庄稼，你们克扣他们的工钱；这工钱在喊冤，而且收割工人的冤声已经进入万军之主的耳朵了。","notes":[]},{"n":5,"t":"你们在地上享奢华宴乐，把自己养肥了，等候宰杀的日子。","notes":[]},{"n":6,"t":"你们定了义人的罪，把他杀害，他没有抵抗你们。","notes":[]},{"n":7,"t":"所以弟兄们，你们要忍耐，直到主来。看哪，农夫等候着地里宝贵的出产，耐心地等到它得了秋霖春雨。","notes":[],"heads":["忍耐和祷告"]},{"n":8,"t":"你们也要忍耐，坚固你们的心，因为主来的日子近了。","notes":[]},{"n":9,"t":"弟兄们，你们不要彼此埋怨，免得受审判。看哪，审判的主站在门口了。","notes":[]},{"n":10,"t":"弟兄们，你们要把那先前奉主名说话的众先知作能受苦、能忍耐的榜样。","notes":[]},{"n":11,"t":"看哪，那些忍耐的人，我们称他们是有福的。你们听见过约伯的忍耐，也看见主给他的结局，知道主是充满怜悯和慈悲的。","notes":[]},{"n":12,"t":"我的弟兄们，最要紧的是不可起誓；不可指着天起誓，也不可指着地起誓，任何誓都不可起。你们说话，是，就说是；不是，就说不是，免得你们落在审判之下。","notes":[]},{"n":13,"t":"你们中间若有人受苦，他该祷告；有人喜乐，他该歌颂。","notes":[]},{"n":14,"t":"你们中间若有人病了，他该请教会的长老们来为他祷告，奉主的名为他抹油。","notes":[]},{"n":15,"t":"出于信心的祈祷必能救那病人，主必叫他起来；他若犯了罪，也必蒙赦免。","notes":[]},{"n":16,"t":"所以，你们要彼此认罪，互相代求，使你们得医治。义人祈祷所发的力量是大有功效的。","notes":[]},{"n":17,"t":"以利亚与我们是同样性情的人，他恳切地祈求不要下雨，地上就三年六个月没有下雨。","notes":[]},{"n":18,"t":"他又祷告，天就降下雨来，地就有了出产。","notes":[]},{"n":19,"t":"我的弟兄们，你们中间若有人迷失了真理而有人使他回转，","notes":[]},{"n":20,"t":"这人该知道，使一个罪人从迷途中回转，会从死亡中把他的灵魂救回来，而且遮盖许多的罪。","notes":[]}]}},"1PE":{"1":{"heading":"问候","verses":[{"n":1,"t":"耶稣基督的使徒彼得写信给那些被拣选，分散在本都、加拉太、加帕多家、亚细亚、庇推尼寄居的人，","notes":[]},{"n":2,"t":"就是照父神的预知，藉着圣灵得以成圣，以致顺服耶稣基督，又蒙他血所洒的人。愿恩惠、平安多多地赐给你们！","notes":["“平安”或译“和平”。"]},{"n":3,"t":"愿颂赞归于我们主耶稣基督的父神！他曾照自己的大怜悯，藉着耶稣基督从死人中复活，重生了我们，使我们有活的盼望，","notes":[],"heads":["活的盼望"]},{"n":4,"t":"好得到不朽坏、不玷污、不衰残、为你们存留在天上的基业，","notes":[]},{"n":5,"t":"就是为你们这些藉着信、蒙神大能保守的人，能获得他所预备、到末世要显现的救恩。","notes":[]},{"n":6,"t":"虽然你们必须在百般试炼中暂时忧愁，你们要为此喜乐 ，","notes":["“你们要为此喜乐”或译“为此你们有喜乐”。"]},{"n":7,"t":"使你们的信心既被考验，就比那被火试炼仍然能坏的金子更显宝贵，可以在耶稣基督显现的时候得着称赞、荣耀、尊贵。","notes":[]},{"n":8,"t":"虽然你们没有见过他，却是爱他；如今虽看不见，你们却因信他而有说不出来、满有荣光的喜乐，","notes":[]},{"n":9,"t":"因为你们得到信心的效果，就是灵魂的得救。","notes":["有古卷是“我们”。"]},{"n":10,"t":"论到这救恩，那预先说你们要得恩典的众先知已经详细地搜索查考过，","notes":[]},{"n":11,"t":"查考在他们心里的基督的灵预先证明基督受苦难，后来得荣耀，是指什么时候，什么样的情况。","notes":[]},{"n":12,"t":"他们得了启示，知道他们所服事的不是自己，而是你们。那藉着从天上差来的圣灵传福音给你们的人，现在将这些事传给你们；这些事连天使也都切望察看呢！","notes":[]},{"n":13,"t":"所以，要准备好你们的心，谨慎自守，专心盼望耶稣基督显现的时候带给你们的恩惠。","notes":[],"heads":["应当过圣洁的生活"]},{"n":14,"t":"作为顺服的儿女，就不要效法从前蒙昧无知的时候那放纵私欲的样子。","notes":[]},{"n":15,"t":"但那召你们的既是圣洁，你们在一切所行的事上也要圣洁；","notes":[]},{"n":16,"t":"因为经上记着：“你们要成为圣，因为我是神圣的。”","notes":[]},{"n":17,"t":"既然你们称那不偏待人、按各人行为审判人的主为父，就当存敬畏的心，度你们在世寄居的日子。","notes":["“称那…为父”或译“求告那不偏待人、按各人行为审判人的父”。"]},{"n":18,"t":"你们知道，你们得以从你们祖先传下来虚妄的行为中救赎出来，不是靠着会朽坏的金银等物，","notes":[]},{"n":19,"t":"而是凭着基督的宝血，如同无瑕疵、无玷污的羔羊的血。","notes":[]},{"n":20,"t":"基督是神在创世以前所预知，而在这末世才为你们显现的。","notes":[]},{"n":21,"t":"你们也因着他而信那使他从死人中复活、又给他荣耀的神，好让你们的信心和盼望都在于神。","notes":[]},{"n":22,"t":"既然你们因顺从真理而洁净了自己的心灵，能真诚爱弟兄，就该以清洁的心彼此切实相爱。","notes":["“以清洁的心”：有古卷是“从心里”；另有古卷是“以真诚的心”。"]},{"n":23,"t":"你们蒙了重生，不是由于会朽坏的种子，而是由于不会朽坏的种子，是藉着神永活常存的道。","notes":[]},{"n":24,"t":"因为“凡血肉之躯的尽都如草，他的一切荣美像草上的花；草必枯干，花必凋谢，","notes":[]},{"n":25,"t":"惟有主的道永远常存。”这话就是传给你们的福音。","notes":[]}]},"2":{"heading":"活石和圣洁的国度","verses":[{"n":1,"t":"所以，你们要除去一切的恶毒，一切诡诈、假善、嫉妒，和一切毁谤的话。","notes":[]},{"n":2,"t":"要爱慕那纯净的灵奶，像初生的婴孩爱慕奶一样，好使你们藉着它成长，以致得救，","notes":[]},{"n":3,"t":"因为你们已经尝过主恩的滋味。","notes":[]},{"n":4,"t":"要亲近主，他是活石，虽然被人所丢弃，却是神所拣选、所珍贵的。","notes":[]},{"n":5,"t":"你们作为活石，要被建造成属灵的殿，成为圣洁的祭司，藉着耶稣基督献上蒙神悦纳的属灵祭物。","notes":[]},{"n":6,"t":"因为经上说：“看哪，我把一块石头放在锡安—一块蒙拣选、珍贵的房角石；信靠他的人必不蒙羞。”","notes":[]},{"n":7,"t":"所以，这石头在你们信的人是珍贵的；在那不信的人却有话说：“匠人所丢弃的石头已作了房角的头块石头。”","notes":[]},{"n":8,"t":"又说：“作了绊脚的石头，使人跌倒的磐石。”他们绊跌，因为不顺从这道，这也是预定的。","notes":[]},{"n":9,"t":"不过，你们是被拣选的一族，是君尊的祭司，是神圣的国度，是属神的子民，要使你们宣扬那召你们出黑暗入奇妙光明者的美德。","notes":[]},{"n":10,"t":"“你们从前不是子民，现在却成了神的子民；从前未曾蒙怜悯，现在却蒙了怜悯。”","notes":[]},{"n":11,"t":"亲爱的，你们是客旅，是寄居的，我劝你们要禁戒肉体的情欲；这情欲是与灵魂争战的。","notes":[],"heads":["作神的仆人"]},{"n":12,"t":"你们在外邦人中要品行端正，好让那些人，虽然毁谤你们是作恶的，会因看见你们的好行为而在鉴察的日子归荣耀给神。","notes":["“鉴察”或译“眷顾”或“来临”。"]},{"n":13,"t":"你们为主的缘故要顺服人的一切制度，或是在上的君王，","notes":[]},{"n":14,"t":"或是君王所派惩恶赏善的官员。","notes":[]},{"n":15,"t":"因为神的旨意原是要你们以行善来堵住糊涂无知人的口。","notes":[]},{"n":16,"t":"虽然你们是自由的，却不可藉着自由遮盖恶毒，总要作神的仆人。","notes":[]},{"n":17,"t":"务要尊重众人；要敬爱教中的弟兄姊妹；要敬畏神；要尊敬君王。","notes":[]},{"n":18,"t":"你们作奴仆的，凡事要存敬畏的心顺服主人；不但顺服善良温和的，就是乖僻的也要顺服。","notes":[],"heads":["基督受苦的榜样"]},{"n":19,"t":"倘若你们为使良心对得起神，忍受冤屈的痛苦，这是可赞许的。","notes":[]},{"n":20,"t":"你们若因犯罪受责打而忍耐，有什么可称赞的呢？但你们若因行善受苦而忍耐，这在神看来是可赞许的。","notes":[]},{"n":21,"t":"你们蒙召就是为此，因为基督也为你们受过苦，给你们留下榜样，为要使你们跟随他的脚踪。","notes":[]},{"n":22,"t":"“他并没有犯罪，口里也没有诡诈。”","notes":[]},{"n":23,"t":"他被辱骂不还口，受害也不说威吓的话，只将自己交托给公义的审判者。","notes":[]},{"n":24,"t":"他被挂在木头上，亲身担当了我们的罪，使我们既然在罪上死，就得以在义上活。因他受的鞭伤，你们得了医治。","notes":[]},{"n":25,"t":"你们从前好像迷路的羊，如今却归回你们灵魂的牧人和监督了。","notes":[]}]},"3":{"heading":"妻子和丈夫","verses":[{"n":1,"t":"同样，你们作妻子的，要顺服自己的丈夫，这样，即使有不信从道理的丈夫，也会因妻子的品行，并非言语，而感化过来，","notes":[]},{"n":2,"t":"因为看见了你们敬虔纯洁的品行。","notes":[]},{"n":3,"t":"你们不要藉外表来妆饰自己，如编头发，戴金饰，穿美丽的衣裳等，","notes":[]},{"n":4,"t":"而要有蕴藏在人内心不衰退的美，以温柔娴静的心妆饰自己；这在神面前是极宝贵的。","notes":[]},{"n":5,"t":"因为古时仰赖神的圣洁妇人正是以此为妆饰，顺服自己的丈夫。","notes":[]},{"n":6,"t":"就如撒拉听从亚伯拉罕，称他为主。你们只要行善，不怕任何恐吓，就成为撒拉的女儿了。","notes":[]},{"n":7,"t":"同样，你们作丈夫的，要按情理跟妻子共同生活，体贴女性是比较软弱的器皿；要尊重她，因为她也与你一同承受生命之恩。这样，你们的祷告就不会受阻碍。","notes":["“情理”：原文直译“知识”。"]},{"n":8,"t":"总而言之，你们都要同心，彼此体恤，相爱如弟兄，存怜悯和谦卑的心。","notes":[],"heads":["为义受苦"]},{"n":9,"t":"不要以恶报恶，以辱骂还辱骂，倒要祝福，因为你们正是为此蒙召的，好使你们承受福气。","notes":[]},{"n":10,"t":"因为经上说：“凡要爱惜生命、享受好日子的人，要禁止舌头不出恶言，嘴唇不说诡诈的话。","notes":[]},{"n":11,"t":"也要弃恶行善，寻求和睦，一心追求。","notes":[]},{"n":12,"t":"因为主的眼看顾义人，他的耳听他们的祈祷；但主向行恶的人变脸。”","notes":[]},{"n":13,"t":"你们若热心行善，有谁会害你们呢？","notes":[]},{"n":14,"t":"即使你们为义受苦，也是有福的。不要怕人的威吓，也不要惊慌；","notes":[]},{"n":15,"t":"只要心里奉主基督为圣，尊他为主。有人问你们心中盼望的理由，要随时准备答覆；","notes":[]},{"n":16,"t":"不过，要以温柔、敬畏的心回答。要存无亏的良心，使你们在何事上被毁谤，就在何事上使那些凌辱你们在基督里有好品行的人自觉羞愧。","notes":[]},{"n":17,"t":"神的旨意若是要你们因行善受苦，这总比因行恶受苦好。","notes":[]},{"n":18,"t":"因为基督也曾一次为罪受苦 ，就是义的代替不义的，为要引领你们到神面前。在肉体里，他被治死；但在灵里，他复活了。","notes":["“受苦”：有古卷是“受死”。","“你们”：有古卷是“我们”。"]},{"n":19,"t":"他藉这灵也曾去向那些在监狱里的灵传道，","notes":[]},{"n":20,"t":"就是那些从前在挪亚预备方舟、神容忍等待的时候不信从的人。当时进入方舟，藉着水得救的不多，只有八个人。","notes":[]},{"n":21,"t":"这水所预表的洗礼，现在藉着耶稣基督的复活拯救你们，不是除掉肉体的污秽，而是向神恳求有无亏的良心。","notes":[]},{"n":22,"t":"耶稣已经到天上去，在神的右边，众天使、有权柄的、有权能的都服从了他。","notes":[]}]},"4":{"heading":"神恩赐的好管家","verses":[{"n":1,"t":"既然基督在肉身受苦，你们也该将这样的心志作为兵器，因为在肉身受过苦的已经与罪断绝了，","notes":[]},{"n":2,"t":"使你们从今以后不再随从人的情欲，只顺从神的旨意，在世度余下的光阴。","notes":[]},{"n":3,"t":"因为你们从前随从外邦人的心意，生活在淫荡、情欲、醉酒、荒宴、狂饮和可憎的偶像崇拜中，时候已经够了。","notes":[]},{"n":4,"t":"在这些事上，他们见你们不与他们同奔放荡无度的路就以为怪，毁谤你们。","notes":[]},{"n":5,"t":"他们必须在那位将要审判活人死人的主面前交账。","notes":[]},{"n":6,"t":"为此，死人也曾有福音传给他们，要使他们的肉体按着人受审判，他们的灵却靠神活着。","notes":[]},{"n":7,"t":"万物的结局近了。所以你们要谨慎自守，要警醒祷告。","notes":[]},{"n":8,"t":"最要紧的是彼此切实相爱，因为爱能遮掩许多的罪。","notes":[]},{"n":9,"t":"你们要互相款待，不发怨言。","notes":[]},{"n":10,"t":"人人要照自己所得的恩赐彼此服事，作神各种恩赐的好管家。","notes":[]},{"n":11,"t":"若有人讲道，他要按着神的圣言讲；若有人服事，他要按着神所赐的力量服事，好让神在凡事上因耶稣基督得荣耀。愿荣耀和权能都归给他，直到永永远远。阿们！","notes":[]},{"n":12,"t":"亲爱的，有火一般的考验临到你们，不要奇怪，似乎是遭遇非常的事；","notes":[],"heads":["基督徒的受苦"]},{"n":13,"t":"倒要欢喜，因为你们是与基督一同受苦，使你们在他荣耀显现的时候也可以欢喜快乐。","notes":[]},{"n":14,"t":"你们若为基督的名受辱骂是有福的，因为荣耀的灵，就是神的灵，在你们身上。","notes":[]},{"n":15,"t":"你们中间，不可有人因为杀人、偷窃、作恶、好管闲事而受苦。","notes":[]},{"n":16,"t":"若有人因是基督徒而受苦，不要引以为耻，倒要因这名而归荣耀给神。","notes":[]},{"n":17,"t":"因为时候到了，审判要从神的家开始；若是先从我们开始，那么，不信从神福音的人将有何等的结局呢？","notes":[]},{"n":18,"t":"“若是义人还仅仅得救，不虔敬和犯罪的人将有何地可站呢？”","notes":[]},{"n":19,"t":"所以，照神旨意受苦的人要一心为善，将自己的灵魂交给那信实的造物主。","notes":[]}]},"5":{"heading":"牧养神的羊群","verses":[{"n":1,"t":"所以，我这同作长老，作基督受苦的证人和分享将来所要显现的荣耀的人，勉励在你们中间的长老们：","notes":[]},{"n":2,"t":"务要牧养在你们当中神的群羊，按着神的旨意照顾他们，不是出于勉强，而是出于甘心；也不是因为贪财，而是出于乐意。","notes":["“按着…他们”：有古卷没有“按着神的旨意”；另有古卷没有“照顾他们”。"]},{"n":3,"t":"不要辖制所托付你们的群羊，而是要作他们的榜样。","notes":[]},{"n":4,"t":"到了大牧人显现的时候，你们必得到那永不衰残、荣耀的冠冕。","notes":[]},{"n":5,"t":"同样，你们年轻的，要顺服年长的。你们大家都要以谦卑当衣服穿上，彼此顺服，因为“神抵挡骄傲的人，但赐恩给谦卑的人。”","notes":[]},{"n":6,"t":"所以，你们要谦卑服在神大能的手下，这样，到了适当的时候，他必使你们升高。","notes":[]},{"n":7,"t":"你们要将一切的忧虑卸给神，因为他顾念你们。","notes":[]},{"n":8,"t":"务要谨慎，要警醒。因为你们的仇敌魔鬼，如同咆哮的狮子，走来走去，寻找可吞吃的人。","notes":[]},{"n":9,"t":"你们要用坚固的信心抵挡他，因为知道你们在世上的众弟兄也正在经历这样的苦难。","notes":[]},{"n":10,"t":"那赐一切恩典的神曾在基督里召了你们，得享他永远的荣耀，在你们暂受苦难之后，必要亲自成全你们，坚固你们，赐力量给你们，建立你们。","notes":["有古卷加“耶稣”。","有古卷没有“建立你们”。"]},{"n":11,"t":"愿权能归给他，直到永永远远。阿们！","notes":[]},{"n":12,"t":"我简单地写了这信，托我所看为忠心的弟兄西拉交给你们，劝勉你们，又证明这恩是神真实的恩典；你们务要在这恩上站立得住。","notes":[],"heads":["问安"]},{"n":13,"t":"在巴比伦与你们同蒙拣选的教会向你们问安。我儿子马可也向你们问安。","notes":[]},{"n":14,"t":"你们要用爱心彼此亲吻问安。愿平安归给你们所有在基督里的人！","notes":["“平安”或译“和平”。"]}]}},"2PE":{"1":{"heading":"问候","verses":[{"n":1,"t":"耶稣基督的仆人和使徒西门．彼得写信给那因我们的神和救主耶稣基督的义，与我们同得一样宝贵信心的人。","notes":["有古卷是“西面．彼得”。","有古卷没有“和”。"]},{"n":2,"t":"愿恩惠、平安，因你们认识神和我们的主耶稣，多多加给你们！","notes":["“平安”或译“和平”。"]},{"n":3,"t":"神的神能已把一切关乎生命和虔敬的事赐给我们，因我们认识那用自己荣耀和美德召我们的神。","notes":[],"heads":["信徒的蒙召和被选"]},{"n":4,"t":"因此，他已把又宝贵又极大的应许赐给我们，使我们既脱离世上从情欲来的败坏，就得分享神的本性。","notes":[]},{"n":5,"t":"正因这缘故，你们要分外地努力。有了信心，又要加上德行；有了德行，又要加上知识；","notes":[]},{"n":6,"t":"有了知识，又要加上节制；有了节制，又要加上忍耐；有了忍耐，又要加上虔敬；","notes":[]},{"n":7,"t":"有了虔敬，又要加上爱弟兄的心；有了爱弟兄的心，又要加上爱众人的心。","notes":[]},{"n":8,"t":"你们有了这几样，再继续增长，就必使你们在认识我们的主耶稣基督上，不至于懒散和不结果子了。","notes":[]},{"n":9,"t":"没有这几样的人就是瞎眼，是短视，忘了他过去的罪已经得了洁净。","notes":[]},{"n":10,"t":"所以，弟兄们，要更加努力，使你们的蒙召和被选坚定不移。你们实行这几样，就永不失脚。","notes":[]},{"n":11,"t":"这样，必叫你们丰丰富富地得以进入我们主－救主耶稣基督永远的国度。","notes":[]},{"n":12,"t":"虽然你们已经知道这些事，并且在你们已有的真道上得到坚固，我还是要常常提醒你们这些事。","notes":[]},{"n":13,"t":"我认为趁我还在这帐棚的时候，应该激发你们的记忆，","notes":[]},{"n":14,"t":"因为知道我脱离这帐棚的时候快到了，正如我们的主耶稣基督所指示我的。","notes":[]},{"n":15,"t":"我也要尽心竭力，使你们在我去世以后时常记念这些事。","notes":[]},{"n":16,"t":"我们从前把我们主耶稣基督的大能和他来临的事告诉你们，并不是随从一些捏造出来的无稽传说，我们是曾经亲眼见过他的威荣的人。","notes":[],"heads":["基督的荣耀和先知的信息"]},{"n":17,"t":"他从父神得尊贵荣耀的时候，从至高无上的荣耀有声音出来，对他说：“这是我的爱子，我所喜悦的。”","notes":[]},{"n":18,"t":"我们同他在圣山的时候，亲自听见这声音从天上出来。","notes":[]},{"n":19,"t":"我们有先知更确实的信息，你们要好好地留意这信息，如同留意照耀在暗处的明灯，直等到天亮，晨星在你们心里升起的时候。","notes":[]},{"n":20,"t":"第一要紧的，你们要知道，经上所有的预言是不可随私意解释的，","notes":[]},{"n":21,"t":"因为预言从来没有出于人意的，而是人被圣灵感动说出神的话来。","notes":[]}]},"2":{"heading":"假先知和假教师","verses":[{"n":1,"t":"从前在民间有假先知起来；同样，将来在你们中间也会有假教师，偷偷地引进使人灭亡的异端。他们甚至不认买他们的主人，自取迅速灭亡。","notes":[]},{"n":2,"t":"许多人会随从他们淫荡的行为，以致真理之道因他们的缘故被毁谤。","notes":[]},{"n":3,"t":"他们因贪婪，要用捏造的言语在你们身上取得利益。他们的惩罚，自古以来并不迟延；他们的灭亡也必迅速来到。","notes":[]},{"n":4,"t":"既然神没有宽容犯了罪的天使，反而把他们丢在地狱里，囚禁在幽暗中等候审判；","notes":[]},{"n":5,"t":"既然神也没有宽容上古的世界，曾叫洪水临到那不敬虔的世界，只保护了报公义信息的挪亚一家八口；","notes":[]},{"n":6,"t":"既然神判决了所多玛和蛾摩拉，将二城倾覆，焚烧成灰，作为后世不敬虔人的鉴戒，","notes":["有古卷没有“倾覆”。"]},{"n":7,"t":"只搭救了那常为恶人的淫荡忧伤的义人罗得—","notes":[]},{"n":8,"t":"因为那义人住在他们当中，他正义的心因天天看见和听见他们不法的事而伤痛；","notes":[]},{"n":9,"t":"那么，主知道搭救敬虔的人脱离试炼，把不义的人留在惩罚之下等候审判的日子，","notes":[]},{"n":10,"t":"尤其那些随从肉体、放纵污秽的情欲、藐视主的权威的人更是如此。他们胆大任性，无惧地毁谤众尊荣者；","notes":[]},{"n":11,"t":"就是天使，虽然力量权能更大，在对他们宣告从主来的审判的时候还不用毁谤的话。","notes":["“在对他们…的话”：有古卷没有“从主来的”；另有古卷是“还不用毁谤的话在主面前控告他们”。"]},{"n":12,"t":"但这些人好像没有理性的牲畜，生来就是要被捉拿宰杀的。他们毁谤自己所不知道的事，正在败坏人的时候，自己也遭遇败坏，","notes":[]},{"n":13,"t":"为所行的不义受不义的工钱。他们喜爱白昼狂欢，他们已被玷污，又有瑕疵，正与你们一同欢宴，以自己的诡诈为乐。","notes":[]},{"n":14,"t":"他们满眼是淫色，是止不住的罪，引诱心不坚定的人，心中习惯了贪婪，正是被诅咒的种类。","notes":[]},{"n":15,"t":"他们离弃了正路，走入歧途，随从比珥的儿子巴兰的路；巴兰就是那贪爱不义的工钱的人，","notes":["有古卷是“比索”。"]},{"n":16,"t":"他却为自己的过犯受了责备，而那不能说话的驴以人的声音阻止了先知的狂妄。","notes":[]},{"n":17,"t":"这些人是无水的泉源，是狂风催逼的雾气，有漆黑的幽暗为他们存留。","notes":[]},{"n":18,"t":"他们说虚妄夸大的话，用肉体的情欲和淫荡的事引诱那些刚脱离错谬生活的人。","notes":[]},{"n":19,"t":"他们应许人自由，自己却作了腐败的奴隶，因为人被谁制伏就是谁的奴隶。","notes":[]},{"n":20,"t":"倘若他们因认识我们的主和救主耶稣基督而得以脱离世上的污秽，后来又被污秽缠住，被制伏，他们末后的景况就比先前更不好了。","notes":[]},{"n":21,"t":"他们知道义路，竟背弃了传授给他们那神圣的诫命，倒不如不知道为妙。","notes":[]},{"n":22,"t":"俗语说得好，这话正印证在他们身上了：“狗转过来吃自己所吐的；”又说：“猪洗净了，又回到烂泥里打滚。”","notes":[]}]},"3":{"heading":"主再来的应许","verses":[{"n":1,"t":"亲爱的，我现在写给你们的是第二封信。在这两封信里，我都提醒你们，激发你们真诚的心，","notes":[]},{"n":2,"t":"要你们记得圣先知预先所说的话和主—救主的命令，就是使徒所传给你们的。","notes":[]},{"n":3,"t":"第一要紧的，你们要知道，在末世必有好讥诮的人随从自己的私欲出来讥诮，","notes":[]},{"n":4,"t":"说：“他要来临的应许在哪里呢？因为从列祖长眠以来，万物与起初创造的时候仍是一样啊！”","notes":[]},{"n":5,"t":"他们故意忘记这事，就是从太古凭神的话有了天，并由水而出和藉着水而成的地；","notes":[]},{"n":6,"t":"藉着水，当时的世界被水淹没而消灭了。","notes":[]},{"n":7,"t":"但现在的天地还是凭着神的话存留，直留到不敬虔之人受审判遭沉沦的日子，用火焚烧。","notes":[]},{"n":8,"t":"亲爱的，有一件事你们不可忘记，就是：主看一日如千年，千年如一日。","notes":[]},{"n":9,"t":"主没有迟延他的应许，就如有人以为他是迟延，其实他是宽容你们，不愿一人沉沦，而是人人都来悔改。","notes":[]},{"n":10,"t":"但主的日子要像贼一样来到；那日，天必在轰然一声中消失，天体都要被烈火熔化，地和地上的万物都要烧尽。","notes":["“烧尽”：有古卷是“暴露无遗”；另有古卷是“消灭”或“消失”。"]},{"n":11,"t":"既然这一切都要如此消失，你们处世为人必须圣洁敬虔，","notes":["有古卷是“我们”。"]},{"n":12,"t":"等候并催促神的日子来到。因为在那日，天要被火烧而消灭，天体都要被烈火熔化。","notes":[]},{"n":13,"t":"但照他的应许，我们等候新天新地，其中有正义常住。","notes":[]},{"n":14,"t":"所以，亲爱的，既然你们等候这些事，就要竭力使自己没有玷污，无可指责，在主前和睦；","notes":[]},{"n":15,"t":"并且要以我们主的容忍作为你们得救的机会，就如我们所亲爱的弟兄保罗，照着所赐给他的智慧写信给你们。","notes":[]},{"n":16,"t":"他一切的信上都谈到这事。信中有些难明白的，那无学问、不坚定的人加以曲解，如曲解别的经书一样，自取灭亡。","notes":[]},{"n":17,"t":"所以，亲爱的，既然你们预先知道这事，就当防备，免得被恶人的错谬诱惑，从自己稳定的立场上坠落。","notes":[]},{"n":18,"t":"你们倒要在我们的主和救主耶稣基督的恩典和知识上有长进。愿荣耀归给他，从今直到永远之日。阿们！","notes":["有古卷没有“阿们！”"]}]}},"1JN":{"1":{"heading":"生命之道","verses":[{"n":1,"t":"论到从起初原有的生命之道，就是我们所听见、所看见、亲眼看过、亲手摸过的－","notes":[]},{"n":2,"t":"这生命已经显现出来，我们看见了，现在又作见证，把原与父同在，并且向我们显现过的那永远的生命传扬给你们－","notes":[]},{"n":3,"t":"我们把所看见、所听见的传扬给你们，为要使你们也与我们有团契，而我们的团契是与父和他儿子耶稣基督所共有的。","notes":[]},{"n":4,"t":"我们把这些事写给你们，使我们的喜乐得以满足。","notes":["“我们”：有古卷是“你们”。"]},{"n":5,"t":"神就是光，在他毫无黑暗；这是我们从主所听见，又报给你们的信息。","notes":[],"heads":["神就是光"]},{"n":6,"t":"我们若说，我们与神有团契，却仍在黑暗里行走，就是说谎话，不实行真理了。","notes":[]},{"n":7,"t":"我们若在光明中行走，如同神在光明中，就彼此有团契，他儿子耶稣的血就洗净我们一切的罪。","notes":[]},{"n":8,"t":"我们若说自己没有罪，就是欺骗自己，真理就不在我们里面了。","notes":[]},{"n":9,"t":"我们若认自己的罪，神是信实的，是公义的，必要赦免我们的罪，洗净我们一切的不义。","notes":[]},{"n":10,"t":"我们若说自己没有犯过罪，就是把神当作说谎的，他的道就不在我们里面了。","notes":[]}]},"2":{"heading":"我们的中保基督","verses":[{"n":1,"t":"我的孩子们哪，我把这些话写给你们，是要你们不犯罪。若有人犯罪，在父那里我们有一位中保，就是那义者耶稣基督。","notes":[]},{"n":2,"t":"他为我们的罪作了赎罪祭，不单是为我们的罪，也是为普天下人的罪。","notes":[]},{"n":3,"t":"我们若遵守神的命令，就知道我们确实认识他。","notes":[]},{"n":4,"t":"人若说“我认识他”，却不遵守他的命令，就是说谎话的，真理就不在他里面了。","notes":[]},{"n":5,"t":"凡遵守他的道的，爱神的心确实地在他里面达到完全了。由此我们知道我们是在他里面。","notes":[]},{"n":6,"t":"凡说自己住在他里面的，就该照着他所行的去行。","notes":[]},{"n":7,"t":"亲爱的，我写给你们的不是一条新命令，而是你们从起初所受的旧命令；这旧命令就是你们所听过的道。","notes":[],"heads":["新命令"]},{"n":8,"t":"然而，我写给你们的是一条新命令，在基督里是真实的，在你们也是真实的，因为黑暗渐渐消逝，真光已经在照耀。","notes":[]},{"n":9,"t":"人若说自己在光明中，却恨他的弟兄，他到如今还是在黑暗里。","notes":[]},{"n":10,"t":"那爱弟兄的，就是住在光明中，他不会使人失足犯罪。","notes":["“他不会…犯罪”或译“在光里并没有任何绊脚石”。"]},{"n":11,"t":"惟独那恨弟兄的，是在黑暗里，也在黑暗里行走，不知道往哪里去，因为黑暗使他的眼睛瞎了。","notes":[]},{"n":12,"t":"孩子们哪，我写信给你们，因为你们的罪藉着基督的名得了赦免。","notes":[]},{"n":13,"t":"父老们啊，我写信给你们，因为你们认识从起初就有的那一位。青年们哪，我写信给你们，因为你们胜过了那恶者。","notes":[]},{"n":14,"t":"孩子们哪，我曾写信给你们，因为你们认识父。父老们啊，我曾写信给你们，因为你们认识从起初就有的那一位。青年们哪，我曾写信给你们，因为你们刚强，神的道常存在你们心里，你们也胜过了那恶者。","notes":[]},{"n":15,"t":"不要爱世界和世界上的东西，若有人爱世界，爱父的心就不在他里面了。","notes":[]},{"n":16,"t":"因为凡世界上的东西，好比肉体的情欲、眼目的情欲和今生的骄傲，都不是从父来的，而是从世界来的。","notes":[]},{"n":17,"t":"这世界和世上的情欲都要消逝，惟独那遵行神旨意的人永远常存。","notes":[]},{"n":18,"t":"孩子们哪，如今是末世的时光了。你们曾听过那敌基督者要来，现在有好些敌基督者已经出来了；由此我们就知道，如今是末世的时光了。","notes":[],"heads":["敌基督者"]},{"n":19,"t":"他们从我们中间出去，却不是属我们的，若是属我们的，就必仍旧与我们同在。他们出去，这就显明他们都不是属我们的。","notes":[]},{"n":20,"t":"你们从那圣者受了恩膏，并且你们大家都知道。","notes":["“你们大家都知道”：有古卷是“你们知道这一切的事”。"]},{"n":21,"t":"我写信给你们，不是因你们不认识真理，而是因你们认识，并且知道一切虚谎都不是从真理出来的。","notes":[]},{"n":22,"t":"谁是说谎话的呢？不就是那不认耶稣为基督的吗？那不认父与子的，这个人就是敌基督的。","notes":[]},{"n":23,"t":"凡不认子的，就没有父；宣认子的，连父也有了。","notes":[]},{"n":24,"t":"论到你们，务要将那从起初所听见的常存在心里；若将从起初所听见的存在心里，你们就会住在子里面，也会住在父里面。","notes":[]},{"n":25,"t":"基督所应许我们的就是永生。","notes":[]},{"n":26,"t":"我将这些话写给你们，是论到那些迷惑你们的人说的。","notes":[]},{"n":27,"t":"至于你们，你们从基督所受的恩膏常存在你们心里，并不用人教导你们，自有他的恩膏在凡事上教导你们。这恩膏是真的，不是假的，你们要按这恩膏的教导住在他里面。","notes":[]},{"n":28,"t":"孩子们哪，你们要住在基督里面。这样，他若显现，我们就可以坦然无惧；当他来临的时候，在他面前不至于惭愧。","notes":[],"heads":["神的儿女"]},{"n":29,"t":"你们若知道他是公义的，就知道凡行公义的人都是他所生的。","notes":[]}]},"3":{"heading":"彼此相爱","verses":[{"n":1,"t":"你们看父赐给我们的是何等的慈爱，让我们得以称为神的儿女；我们也真是他的儿女。世人不认识我们的理由，是因他们未曾认识父。","notes":["“我们”：有古卷是“你们”。"]},{"n":2,"t":"亲爱的，我们现在是神的儿女，将来如何还未显明。我们所知道的是：基督显现的时候，我们会像他，因为我们将见到他的本相。","notes":[]},{"n":3,"t":"凡对他有这指望的，就洁净自己，像他是洁净的一样。","notes":[]},{"n":4,"t":"凡犯罪的，就是做违背律法的事；违背律法就是罪。","notes":[]},{"n":5,"t":"你们知道，基督曾显现是要除掉罪；在他并没有罪。","notes":["“罪”：有古卷是“我们的罪”；另有古卷是“世人的罪”。"]},{"n":6,"t":"凡住在他里面的，不犯罪；凡犯罪的，未曾看见他，也未曾认识他。","notes":[]},{"n":7,"t":"孩子们哪，不要让人迷惑了你们；行义的才是义人，正如基督是义的。","notes":[]},{"n":8,"t":"犯罪的是出于魔鬼，因为魔鬼从起初就犯罪。神的儿子显现出来，是为了要毁灭魔鬼的作为。","notes":[]},{"n":9,"t":"凡从神生的，不犯罪，因神的道存在他里面，他也不能犯罪，因为他是由神所生的。","notes":["“道”：原文直译“种”。"]},{"n":10,"t":"这就显明谁是神的儿女，谁是魔鬼的儿女了。凡不行义的，不是出于神，不爱他弟兄的，也是如此。","notes":[]},{"n":11,"t":"我们要彼此相爱。这就是你们从起初所听到的信息。","notes":[]},{"n":12,"t":"不要像该隐；他是属那邪恶者，杀了自己的弟弟。为什么杀了他呢？因为自己的行为是邪恶的，而弟弟的行为是正直的。","notes":[]},{"n":13,"t":"弟兄们，世人若恨你们，不要惊讶。","notes":[]},{"n":14,"t":"我们知道，我们已经出死入生了，因为我们爱弟兄。没有爱心的，仍住在死中。","notes":[]},{"n":15,"t":"凡恨自己弟兄的，就是杀人的；你们知道，凡杀人的，没有永生住在他里面。","notes":[]},{"n":16,"t":"基督为我们舍命，我们从此就知道何为爱；我们也当为弟兄舍命。","notes":[]},{"n":17,"t":"凡有世上财物的，看见弟兄缺乏，却关闭了恻隐的心，神的爱怎能住在他里面呢？","notes":[]},{"n":18,"t":"孩子们哪，我们相爱，不要只在言语或舌头上，总要以行为和真诚表现出来。","notes":[]},{"n":19,"t":"从这一点，我们会知道，我们是出于真理的，并且我们在神面前可以安心，","notes":[],"heads":["在神面前坦然无惧"]},{"n":20,"t":"即使我们的心责备自己，神比我们的心大，他知道一切。","notes":[]},{"n":21,"t":"亲爱的，我们的心若不责备我们，在神面前就可以坦然无惧了。","notes":[]},{"n":22,"t":"我们一切所求的，就从他得着，因为我们遵守他的命令，行他所喜悦的事。","notes":[]},{"n":23,"t":"神的命令就是：我们要信他儿子耶稣基督的名，并且照他所赐给我们的命令彼此相爱。","notes":[]},{"n":24,"t":"遵守神命令的，住在神里面，而神也住在他里面。从这一点，我们知道神住在我们里面，这是由于他所赐给我们的圣灵。","notes":[]}]},"4":{"heading":"神的灵和敌基督者的灵","verses":[{"n":1,"t":"亲爱的，一切的灵不可都信，总要察验那些灵是否出于神，因为有许多假先知已经来到世上。","notes":[]},{"n":2,"t":"凡宣认耶稣基督是成了肉身而来的灵就是出于神的，由此你们可以认出神的灵来；","notes":[]},{"n":3,"t":"凡不宣认耶稣的灵，不是出于神。这是那敌基督者的灵；你们从前听见他要来，现在他已经在世上了。","notes":[]},{"n":4,"t":"孩子们哪，你们是属神的，并且胜过了假先知，因为那在你们里面的比那在世界上的更大。","notes":[]},{"n":5,"t":"他们是属世界的，所以讲论世界的事，而世人也听从他们。","notes":[]},{"n":6,"t":"我们是属神的，认识神的就听从我们；不属神的就不听从我们。从此我们可以认出真理的灵和错谬的灵来。","notes":[]},{"n":7,"t":"亲爱的，我们要彼此相爱，因为爱是从神来的。凡有爱的都是由神而生，并且认识神。","notes":[],"heads":["神就是爱"]},{"n":8,"t":"没有爱的就不认识神，因为神就是爱。","notes":[]},{"n":9,"t":"神差他独一的儿子到世上来，使我们藉着他得生命；由此，神对我们的爱就显明了。","notes":[]},{"n":10,"t":"不是我们爱神，而是神爱我们，差他的儿子为我们的罪作了赎罪祭；这就是爱。","notes":[]},{"n":11,"t":"亲爱的，既然神这样爱我们，我们也要彼此相爱。","notes":[]},{"n":12,"t":"从来没有人见过神，我们若彼此相爱，神就住在我们里面，他的爱在我们里面得以完满了。","notes":[]},{"n":13,"t":"因为神将他的灵赐给我们，由此我们知道我们是住在他里面，而他也住在我们里面。","notes":[]},{"n":14,"t":"父差子作世人的救主，这是我们所看见并且作见证的。","notes":[]},{"n":15,"t":"凡宣认耶稣为神儿子的，神就住在他里面，而他也住在神里面。","notes":[]},{"n":16,"t":"我们知道并且深信神是爱我们的。神就是爱，住在爱里面的就是住在神里面；神也住在他里面。","notes":[]},{"n":17,"t":"由此，爱在我们里面得以完满：我们可以在审判的日子坦然无惧，因为基督如何，我们在这世上也如何。","notes":[]},{"n":18,"t":"在爱里没有惧怕；完满的爱把惧怕驱逐出去，因为惧怕里含着惩罚，惧怕的人在爱里尚未得到完满。","notes":[]},{"n":19,"t":"我们爱，因为神先爱我们。","notes":[]},{"n":20,"t":"人若说“我爱神”，却恨他的弟兄，就是说谎了；不爱他看得见的弟兄，就不能爱看不见的神。","notes":["有古卷是“怎能爱没有看见的神呢？”"]},{"n":21,"t":"爱神的，也要爱弟兄；这是我们从神所受的命令。","notes":[]}]},"5":{"heading":"信心使我们胜过世界","verses":[{"n":1,"t":"凡信耶稣是基督的，都是从神生的；凡爱生他之神的，也必爱从神生的。","notes":["“凡信…神生的”或译“凡爱那生他的，也要爱那由他而生的”。"]},{"n":2,"t":"我们爱神，又实行他的命令，由此就知道我们爱神的儿女了。","notes":["有古卷是“遵行”。"]},{"n":3,"t":"我们遵守神的命令，这就是爱他了，而且他的命令并不是难守的。","notes":[]},{"n":4,"t":"因为凡从神生的就胜过世界；使我们胜过世界的就是我们的信心。","notes":[]},{"n":5,"t":"胜过世界的是谁呢？不就是那信耶稣是神儿子的吗？","notes":[]},{"n":6,"t":"这藉着水和血而来的，就是耶稣基督，不是单用水，而是用水又用血，并且有圣灵作见证，因为圣灵就是真理。","notes":[],"heads":["神为他儿子作的见证"]},{"n":7,"t":"作见证的有三：","notes":[]},{"n":8,"t":"就是圣灵、水与血，这三样也都是一致的。","notes":[]},{"n":9,"t":"既然我们领受人的见证，神的见证更该领受了，因为神的见证是为他儿子作的。","notes":["“该领受”：原文直译“大”。"]},{"n":10,"t":"信神儿子的，就有这见证在他心里；不信神的，就是把神当作说谎的，因为不信神为他儿子作的见证。","notes":[]},{"n":11,"t":"这见证就是：神赐给我们永生，而这永生是在他儿子里面的。","notes":[]},{"n":12,"t":"那有神儿子的，就有生命；没有神儿子的，就没有生命。","notes":[]},{"n":13,"t":"我把这些话写给你们信奉神儿子之名的人，要让你们知道自己有永生。","notes":[],"heads":["知道自己有永生"]},{"n":14,"t":"我们若照着神的旨意祈求，他就垂听我们；这就是我们对他所存坦然无惧的心。","notes":[]},{"n":15,"t":"既然我们知道他听我们一切所求的，就知道我们所求于他的，无不得着。","notes":[]},{"n":16,"t":"人若看见弟兄犯了不至于死的罪，就要为他祈求，神必将生命赐给他—有些人犯的罪是不至于死的；有的是至于死的罪，我不是说要为这罪祈求。","notes":[]},{"n":17,"t":"一切不义的事都是罪，但也有不至于死的罪。","notes":[]},{"n":18,"t":"我们知道，凡从神生的，必不犯罪；从神生的那一位，必保守他，那邪恶者无法加害于他。","notes":[]},{"n":19,"t":"我们知道，我们是属神的，而全世界都伏在那邪恶者的权势之下。","notes":[]},{"n":20,"t":"我们知道，神的儿子已经来到，并且将悟性赐给我们，使我们认识那位真实者，我们也在那位真实者里面，就是在他儿子耶稣基督里面。这是真神，也是永生。","notes":[]},{"n":21,"t":"孩子们哪，你们要远避偶像。","notes":[]}]}},"2JN":{"1":{"heading":"问候","verses":[{"n":1,"t":"我作长老的写信给蒙拣选的夫人和她的儿女，就是我真心所爱的；不但我爱，也是一切认识真理的人所爱的，","notes":["“夫人”或译“教会”；5节同。"]},{"n":2,"t":"这是因为真理住在我们里面，也必与我们同在直到永远。","notes":[]},{"n":3,"t":"愿恩惠、怜悯、平安从父神和他儿子耶稣基督，在真理和爱中必与我们同在。","notes":["“平安”或译“和平”。"]},{"n":4,"t":"我非常欢喜见你的儿女，有照我们从父所受之命令遵行真理的。","notes":[],"heads":["真理和爱"]},{"n":5,"t":"夫人哪，我现在请求你，我们大家要彼此相爱。我写给你的，并不是一条新命令，而是我们从起初就有的。","notes":[]},{"n":6,"t":"这就是爱，就是照他的命令行事；这就是命令，你们要照这命令行，正如你们从起初所听见的。","notes":[]},{"n":7,"t":"有许多迷惑人的已经来到世上，他们不宣认耶稣基督是成了肉身来的；这样的人是迷惑人的，是敌基督的。","notes":[]},{"n":8,"t":"你们要小心，不要失去你们所完成的工作，而要得到充足的赏赐。","notes":["“你们”：有古卷是“我们”。"]},{"n":9,"t":"凡越过基督的教导而不持守的，就没有神；凡持守这教导的，就有父又有子。","notes":[]},{"n":10,"t":"若有人到你们那里而不传这教导，不要接他到家里，也不要向他问安；","notes":[]},{"n":11,"t":"因为向他问安的，就在他的恶行上有份。","notes":[]},{"n":12,"t":"我还有许多事要写给你们，却不愿意用纸用墨，但盼望到你们那里，与你们面对面谈论，使我们的喜乐得以满足。","notes":[],"heads":["结束的问安"]},{"n":13,"t":"你那蒙拣选的姊妹的儿女向你问安。","notes":[]}]}},"3JN":{"1":{"heading":"问候","verses":[{"n":1,"t":"我作长老的写信给亲爱的该犹，就是我真心所爱的。","notes":[]},{"n":2,"t":"亲爱的，我愿你事事安宁，身体健康，正如你的心神安宁一样。","notes":[]},{"n":3,"t":"我非常欢喜，有弟兄到这里来，证实你对真理的忠诚，就是你按着真理而行。","notes":[]},{"n":4,"t":"我听见我的儿女按真理而行，我的欢喜没有比这个更大的。","notes":[]},{"n":5,"t":"亲爱的，你对弟兄，特别是对作客旅的弟兄所做的都是忠诚的。","notes":[],"heads":["合作和反对"]},{"n":6,"t":"他们在教会面前证实了你的爱；你若以对得起神的方式，为他们送行就好了；","notes":[]},{"n":7,"t":"因为他们是为基督的名出外，并没有从未信的人接受什么。","notes":["“基督的名”： 原文直译“那名”。"]},{"n":8,"t":"所以，我们应当接待这样的人，好让我们与他们在真理上成为同工。","notes":[]},{"n":9,"t":"我曾写过一些东西给教会，但他们中间那好作领袖的丢特腓不接纳我们。","notes":[]},{"n":10,"t":"为此，我若去，要提起他所做的事，就是他用恶言攻击我们，还不满足，他自己不接纳弟兄，有人愿意接纳，他还阻止，并且把接纳弟兄的人赶出教会。","notes":[]},{"n":11,"t":"亲爱的，不要效法恶，只要效法善。行善的人属乎神；行恶的人未曾见过神。","notes":[]},{"n":12,"t":"低米丢行善，有众人给他作见证，又有真理给他作见证，就是我们也给他作见证，你知道我们的见证是真的。","notes":[]},{"n":13,"t":"我还有许多事要写给你，却不愿意用笔墨来写给你，","notes":[],"heads":["问安"]},{"n":14,"t":"但盼望很快见到你，我们好面对面谈论。","notes":[]},{"n":15,"t":"愿你平安！朋友们都向你问安。请你替我按着名字一一向朋友们问安。","notes":[]}]}},"JUD":{"1":{"heading":"假教师受惩罚","verses":[{"n":1,"t":"耶稣基督的仆人、雅各的兄弟犹大，写信给那些被召、在父神里蒙爱、为耶稣基督保守的人。","notes":[]},{"n":2,"t":"愿怜悯、平安、慈爱多多加给你们！","notes":["“平安”或译“和平”。"]},{"n":3,"t":"亲爱的，我一直很迫切地想要写信给你们，论到我们同享的救恩，但我觉得有必要现在就写信劝你们，要为从前一次交付给圣徒的真道竭力奋斗。","notes":[]},{"n":4,"t":"因为有些人偷偷地进来，就是早就被判定受惩罚的不虔诚的人，他们把我们神的恩典变为放纵情欲的机会，并且不认独一的主宰—我们的主耶稣基督。","notes":[]},{"n":5,"t":"这一切的事，你们虽然知道，我却仍要提醒你们：从前主只一次就救了他的百姓出埃及地，后来却把那些不信的灭绝了。","notes":["“主”：有古卷是“耶稣”；另有古卷是“神”。","“只一次就”：有古卷把这句话放在“你们虽然”后面。"]},{"n":6,"t":"至于那些不守本位、离开自己住处的天使，主用锁链把他们永远拘留在黑暗里，等候大日子的审判。","notes":[]},{"n":7,"t":"同样，所多玛、蛾摩拉和周围城镇的人也跟着他们一样犯淫乱，随从逆性的情欲，以致遭受永不熄灭之火的惩罚，作为众人的鉴戒。","notes":[]},{"n":8,"t":"照样，这些做梦的人也污秽身体，轻慢掌权者，毁谤众尊荣者。","notes":[]},{"n":9,"t":"天使长米迦勒为摩西的尸首与魔鬼争辩的时候，尚且不敢用毁谤的话谴责他，只说：“主责备你吧！”","notes":[]},{"n":10,"t":"但这些人毁谤他们所不知道的。他们与那些没有理性的牲畜一样，只做本性所知道的事，败坏了自己。","notes":[]},{"n":11,"t":"他们有祸了！因为他们走该隐的道路，又为财利往巴兰的错谬里直奔，并在可拉的背叛中灭亡了。","notes":[]},{"n":12,"t":"这样的人是你们爱筵上的污点；他们无所惧怕地同你们宴乐，仿佛牧人只顾喂饱自己。他们是无雨的浮云，被风飘荡；是秋天没有果子的树，死而又死，连根被拔出来；","notes":["“污点”：原文或译“礁石”。"]},{"n":13,"t":"是海里的狂浪，涌出自己可耻的沫子来；是流荡的星，有漆黑的幽暗永远为他们保留着。","notes":[]},{"n":14,"t":"亚当的七世孙以诺曾预言这些人说：“看哪，主带着他的千万圣者来临，","notes":[]},{"n":15,"t":"要审判众人，证实一切不敬虔的人所妄行一切不敬虔的事，又证实不敬虔的罪人所说顶撞他的刚愎的话。”","notes":[]},{"n":16,"t":"这些人喜出怨言，责怪他人，随从自己的情欲而行，口说夸大的话，为自己的利益谄媚人。","notes":[]},{"n":17,"t":"亲爱的，至于你们，要记得我们主耶稣基督的使徒从前所说的话。","notes":[],"heads":["警告和劝勉"]},{"n":18,"t":"他们曾对你们说过，末世必有好嘲弄的人随从自己不敬虔的私欲而行。","notes":[]},{"n":19,"t":"这就是那些好结党分派、属乎血气、没有圣灵的人。","notes":[]},{"n":20,"t":"亲爱的，至于你们，要在至圣的真道上造就自己，藉着圣灵祷告，","notes":[]},{"n":21,"t":"保守自己常在神的爱中，仰望我们主耶稣基督的怜悯，进入永生。","notes":[]},{"n":22,"t":"有些人心中犹疑，你们要怜悯他们；","notes":["“心中犹疑”：有古卷是“惹起争辩”。","“怜悯”：有古卷是“驳斥”；23节同。"]},{"n":23,"t":"有些人你们要从火中抢出来，搭救他们；有些人你们要存惧怕的心怜悯他们，连那被情欲污染的衣服也要厌恶。","notes":["有古卷是“存惧怕的心搭救他们”。"]},{"n":24,"t":"愿那能保守你们不失脚，使你们无瑕无疵、欢欢喜喜站在他荣耀之前的、","notes":[],"heads":["祝福"]},{"n":25,"t":"我们的救主独一的神，藉着我们的主耶稣基督，得享荣耀、威严、能力、权柄，从万古以前，到现今，直到永永远远。阿们！","notes":[]}]}},"REV":{"1":{"heading":"引言和问候","verses":[{"n":1,"t":"耶稣基督的启示，就是神赐给他，要他将必须快要发生的事指示他的众仆人。他差遣使者指明给他的仆人约翰，","notes":[]},{"n":2,"t":"约翰就将神的道和耶稣基督的见证，凡自己所看见的，都见证出来。","notes":[]},{"n":3,"t":"诵读这书上预言的，和那些听见又遵守其中所记载的，都是有福的，因为时候近了。","notes":[]},{"n":4,"t":"约翰写信给亚细亚的七个教会。愿那位今在、昔在、以后永在的神，与他宝座前的七灵，和那忠信的见证者、从死人中复活的首生者、世上君王的元首耶稣基督，赐恩惠和平安给你们。他爱我们，用自己的血使我们从罪中得释放 ，","notes":["“首生者”或译“长子”。","“平安”或译“和平”。","“得释放”：有古卷是“洗去”。"],"end":5},{"n":6,"t":"又使我们成为国度，作他父神的祭司。愿荣耀、权能归给他，直到永永远远。阿们！","notes":["有古卷是“直到永远”。"]},{"n":7,"t":"“看哪，他驾云降临；众目都要看见他，连刺他的人也要看见他；地上的万族要因他哀哭。”这是真实的。阿们！","notes":[]},{"n":8,"t":"主神说：“我是阿拉法，我是俄梅戛 ，是今在、昔在、以后永在的全能者。”","notes":["“阿拉法”、“俄梅戛”是希腊文首末的二个字母；21．6，22．13同。"]},{"n":9,"t":"我—约翰就是你们的弟兄，在耶稣里和你们一同在患难、国度、忍耐里有份的，为神的道，并为给耶稣作的见证，曾在那名叫拔摩的海岛上。","notes":[],"heads":["基督向约翰显现"]},{"n":10,"t":"有一主日我被圣灵感动，听见在我后面有大声音如吹号，","notes":[]},{"n":11,"t":"说：“把你所看见的写在书上，寄给以弗所、士每拿、别迦摩、推雅推喇、撒狄、非拉铁非、老底嘉那七个教会。”","notes":[]},{"n":12,"t":"我转过身来要看看是谁的声音在跟我说话。我一转过来，看见了七个金灯台；","notes":[]},{"n":13,"t":"在灯台中间有一位好像人子的，身穿垂到脚的长袍，胸间束着金带。","notes":[]},{"n":14,"t":"他的头与发皆白，如白羊毛，如雪；他的眼睛好像火焰，","notes":[]},{"n":15,"t":"双脚好像在炉中锻鍊得发亮的铜，声音好像众水的声音。","notes":[]},{"n":16,"t":"他右手拿着七颗星，从他口中吐出一把两刃的利剑，面貌好像烈日放光。","notes":[]},{"n":17,"t":"我看见了他，就仆倒在他脚前，像死人一样。他用右手按着我说：“不要怕。我是首先的，是末后的，","notes":[]},{"n":18,"t":"又是永活的。我曾死过，看哪，我是活着的，直到永永远远；并且我拿着死亡和阴间的钥匙。","notes":[]},{"n":19,"t":"所以，你要把所看见的事、现在的事和以后将发生的事，都写下来。","notes":[]},{"n":20,"t":"至于你所看见、在我右手中的七颗星和那七个金灯台的奥秘就是：七颗星是七个教会的使者，七个灯台是七个教会。”","notes":[]}]},"2":{"heading":"给以弗所教会的信","verses":[{"n":1,"t":"“你要写信给以弗所教会的使者，说：‘那右手拿着七颗星，在七个金灯台中间行走的这样说：","notes":[]},{"n":2,"t":"我知道你的行为、劳碌、忍耐，也知道你不容忍恶人。你也曾察验那自称为使徒却不是使徒的，看出他们是假的。","notes":[]},{"n":3,"t":"你能忍耐，曾为我的名劳苦而不困倦。","notes":[]},{"n":4,"t":"然而，有一件事我要责备你，就是你把起初的爱心抛弃了。","notes":[]},{"n":5,"t":"所以你要回想你是从哪里坠落的，并且要悔改，做起初所做的工作。你若不悔改，我要到你那里去，把你的灯台从原处挪去。","notes":[]},{"n":6,"t":"然而你还有一件可取的事，就是你恨恶尼哥拉派的行为，这种行为也是我所恨恶的。","notes":[]},{"n":7,"t":"凡有耳朵的都应当听圣灵向众教会所说的话。得胜的，我必将神乐园中生命树的果子赐给他吃。’”","notes":[]},{"n":8,"t":"“你要写信给士每拿教会的使者，说：‘那首先的、末后的，死过又活了的这样说：","notes":[],"heads":["给士每拿教会的信"]},{"n":9,"t":"我知道你的患难和贫穷—其实你却是富足的，也知道那自称是犹太人的所说毁谤的话，其实他们不是犹太人，而是撒但会堂的人。","notes":[]},{"n":10,"t":"你将要受的苦，你不用怕。看哪！魔鬼要把你们中间几个人下在监里，使你们受考验，你们要遭受苦难十日。你务要至死忠心，我就赐给你那生命的冠冕。","notes":[]},{"n":11,"t":"凡有耳朵的都应当听圣灵向众教会所说的话。得胜的必不受第二次死的害。’”","notes":[]},{"n":12,"t":"“你要写信给别迦摩教会的使者，说：‘那有两刃利剑的这样说：","notes":[],"heads":["给别迦摩教会的信"]},{"n":13,"t":"我知道你的居所，就是有撒但座位之处；当我忠心的见证人安提帕在你们中间，在撒但所住的地方被杀之时，你还坚守我的名，没有否认对我的信仰。","notes":[]},{"n":14,"t":"然而，有几件事我要责备你，就是在你那里有人服从了巴兰的教训；这巴兰曾教唆巴勒将绊脚石放在以色列人面前，使他们吃祭过偶像之物，并且犯淫乱。","notes":[]},{"n":15,"t":"同样，你那里也有人服从了尼哥拉派的教训。","notes":[]},{"n":16,"t":"所以，你当悔改；若不悔改，我很快就到你那里来，用我口中的剑攻击他们。","notes":[]},{"n":17,"t":"凡有耳朵的都应当听圣灵向众教会所说的话。得胜的，我必将那隐藏的吗哪赐给他，并赐他一块白石，石上写着新的名字，除了那领受的以外，没有人认识。’”","notes":[]},{"n":18,"t":"“你要写信给推雅推喇教会的使者，说：‘神的儿子，那位眼睛如火焰、双脚像发亮的铜的这样说：","notes":[],"heads":["给推雅推喇教会的信"]},{"n":19,"t":"我知道你的行为：爱心、信心、勤劳、忍耐；又知道你末后所行的善事比起初所行的更多。","notes":[]},{"n":20,"t":"然而，有一件事我要责备你，就是你容忍那自称是先知的妇人耶洗别教唆我的仆人，引诱他们犯淫乱，吃祭过偶像之物。","notes":[]},{"n":21,"t":"我曾给她悔改的机会，她却不肯悔改她的淫行。","notes":[]},{"n":22,"t":"看吧，我要使她病倒在床上。那些与她犯奸淫的人若不悔改他们的行为，我也要使他们同受大患难。","notes":[]},{"n":23,"t":"我又要杀死她的儿女，众教会就知道，我是那察看人肺腑心肠的，我要照你们的行为报应各人。","notes":[]},{"n":24,"t":"至于你们其余的推雅推喇人，就是一切不随从这教训，不明白他们所谓撒但深奥之理的人，我告诉你们，我不会再把别的担子放在你们身上。","notes":[]},{"n":25,"t":"你们只要持守那已经有的，直到我来。","notes":[]},{"n":26,"t":"那得胜又遵守我命令到底的，我要赐给他权柄制伏列国；","notes":[]},{"n":27,"t":"他必用铁杖管辖他们，如同打碎陶器，","notes":[]},{"n":28,"t":"像我也从我父领受了权柄一样。我又要把晨星赐给他。","notes":[]},{"n":29,"t":"凡有耳朵的都应当听圣灵向众教会所说的话。’”","notes":[]}]},"3":{"heading":"给撒狄教会的信","verses":[{"n":1,"t":"“你要写信给撒狄教会的使者，说：‘那有神的七灵和七颗星的这样说：我知道你的行为，就是名义上你是活的，实际上你是死的。","notes":[]},{"n":2,"t":"你要警醒，坚固那些剩下、快要死的，因为我发现你的行为，在我神面前没有一样是完全的。","notes":[]},{"n":3,"t":"所以，要记得你所领受和听见的；要遵守，并要悔改。你若不警醒，我必如贼一样来到；我几时来到你那里，你绝不会知道。","notes":[]},{"n":4,"t":"然而，在撒狄你还有几位是未曾污秽自己衣服的，他们会穿白衣与我同行，因为他们是配穿的。","notes":[]},{"n":5,"t":"得胜的必这样穿白衣，我也不从生命册上涂去他的名；我要在我父面前，和我父的众使者面前，宣认他的名。","notes":[]},{"n":6,"t":"凡有耳朵的都应当听圣灵向众教会所说的话。’”","notes":[]},{"n":7,"t":"“你要写信给非拉铁非教会的使者，说：‘那神圣、真实的，拿着大卫的钥匙，开了就没有人能关，关了就没有人能开的这样说：","notes":[],"heads":["给非拉铁非教会的信"]},{"n":8,"t":"我知道你的行为。看哪，我在你面前给你一个敞开的门，是没有人能关的。我知道你有一点力量，也遵守我的道，没有否认我的名。","notes":[]},{"n":9,"t":"那属撒但会堂的，自称是犹太人，其实不是犹太人，而是说谎话的，我要使他们来到你脚前下拜，使他们知道我已经爱你了。","notes":[]},{"n":10,"t":"因为你遵守了我坚忍的道，我也必在普天下人受试炼的时候保守你免受试炼。","notes":[]},{"n":11,"t":"我必快来，你要持守你所有的，免得人夺去你的冠冕。","notes":[]},{"n":12,"t":"得胜的，我要使他在我神的殿中作柱子，他必不再从那里出去。我又要把我神的名和我神城的名—从天上我神那里降下来的新耶路撒冷，和我的新名，都写在他上面。","notes":[]},{"n":13,"t":"凡有耳朵的都应当听圣灵向众教会所说的话。’”","notes":[]},{"n":14,"t":"“你要写信给老底嘉教会的使者，说：‘那位阿们、诚信真实的见证者、神创造的根源这样说：","notes":[],"heads":["给老底嘉教会的信"]},{"n":15,"t":"我知道你的行为，你也不冷也不热；我巴不得你或冷或热。","notes":[]},{"n":16,"t":"既然你如温水，也不冷也不热，我要从我口中把你吐出去。","notes":[]},{"n":17,"t":"你说：我是富足的，已经发了财，一样都不缺，却不知道你是困苦、可怜、贫穷、瞎眼、赤身的。","notes":[]},{"n":18,"t":"我劝你向我买从火中锻鍊出来的金子，使你富足；又买白衣穿上，使你赤身的羞耻不露出来；又买眼药抹你的眼睛，使你能看见。","notes":[]},{"n":19,"t":"凡我所疼爱的，我就责备管教。所以，你要发热心，也要悔改。","notes":[]},{"n":20,"t":"看哪，我站在门外叩门，若有听见我声音而开门的，我要进到他那里去，我与他，他与我一起吃饭。","notes":[]},{"n":21,"t":"得胜的，我要赐他在我宝座上与我同坐，就如我得了胜，在我父的宝座上与他同坐一般。","notes":[]},{"n":22,"t":"凡有耳朵的都应当听圣灵向众教会所说的话。’”","notes":[]}]},"4":{"heading":"天上的敬拜","verses":[{"n":1,"t":"这些事以后，我观看，看见天上有一道门开着。我头一次听见的那好像吹号的声音对我说：“你上这里来，我要把此后必须发生的事指示你。”","notes":[]},{"n":2,"t":"我立刻被圣灵感动，见有一个宝座安置在天上，有一位坐在宝座上。","notes":[]},{"n":3,"t":"那坐着的，看来好像碧玉和红宝石；又有彩虹围着宝座，光彩好像绿宝石。","notes":[]},{"n":4,"t":"宝座的周围又有二十四个座位，上面坐着二十四位长老，身穿白衣，头上戴着金冠冕。","notes":[]},{"n":5,"t":"有闪电、声音、雷轰从宝座中发出。在宝座前点着七支火炬，就是神的七灵。","notes":[]},{"n":6,"t":"宝座前有一个如同水晶的玻璃海。宝座的周围，四边有四个活物，遍体前后都长满了眼睛。","notes":[]},{"n":7,"t":"第一个活物像狮子，第二个像牛犊，第三个的脸像人脸，第四个像飞鹰。","notes":[]},{"n":8,"t":"四个活物各有六个翅膀，遍体内外都长满了眼睛。他们昼夜不住地说：“圣哉！圣哉！圣哉！主—全能的神；昔在、今在、以后永在！”","notes":[]},{"n":9,"t":"每逢四活物将荣耀、尊贵、感谢归给那坐在宝座上、活到永永远远者的时候，","notes":[]},{"n":10,"t":"二十四位长老就俯伏敬拜坐在宝座上活到永永远远的那一位，又把他们的冠冕放在宝座前，说：","notes":[]},{"n":11,"t":"“我们的主，我们的神，你配得荣耀、尊贵、权柄，因为你创造了万物，万物因你的旨意被创造而存在。”","notes":[]}]},"5":{"heading":"书卷和羔羊","verses":[{"n":1,"t":"我看见坐在宝座那位的右手中有书卷，正反面都写着字，用七个印密封着。","notes":[]},{"n":2,"t":"我又看见一位大力的天使大声宣告说：“有谁配展开那书卷，揭开那七个印呢？”","notes":[]},{"n":3,"t":"在天上、地上、地底下，没有人能展开、能阅览那书卷。","notes":[]},{"n":4,"t":"因为没有人配展开、阅览那书卷，我就大哭。","notes":[]},{"n":5,"t":"长老中有一位对我说：“不要哭。看哪，犹大支派中的狮子，大卫的根，他已得胜，能展开那书卷，揭开那七个印。”","notes":[]},{"n":6,"t":"我又看见宝座和四个活物，以及长老之中有羔羊站着，像是被杀的，有七个角七只眼睛，就是神的七灵，奉差遣往普天下去的。","notes":["有古卷没有“七”。"]},{"n":7,"t":"这羔羊前来，从坐在宝座上那位的右手中拿了书卷。","notes":[]},{"n":8,"t":"他一拿了书卷，四活物和二十四位长老就俯伏在羔羊面前，各拿着琴和盛满了香的金炉；这香就是众圣徒的祈祷。","notes":[]},{"n":9,"t":"他们唱新歌，说：“你配拿书卷，配揭开它的七印；因为你曾被杀，用自己的血从各支派、各语言、各民族、各邦国中买了人来，使他们归于神，","notes":[]},{"n":10,"t":"又使他们成为国民和祭司，归于我们的神；他们将在地上执掌王权。”","notes":[]},{"n":11,"t":"我又观看，我听见宝座和活物及长老的周围有许多天使的声音；他们的数目有千千万万，","notes":[]},{"n":12,"t":"大声说：“被杀的羔羊配得权能、丰富、智慧、力量、尊贵、荣耀、颂赞。”","notes":[]},{"n":13,"t":"我又听见在天上、地上、地底下、沧海里和天地间一切所有被造之物，都说：“愿颂赞、尊贵、荣耀、权势，都归给坐在宝座上的那位和羔羊，直到永永远远！”","notes":[]},{"n":14,"t":"四活物就说：“阿们！”众长老也俯伏敬拜。","notes":[]}]},"6":{"heading":"揭开密封的印","verses":[{"n":1,"t":"我看见羔羊揭开七个印中第一个印的时候，听见四活物中的一个活物，声音如雷，说：“你来！”","notes":[]},{"n":2,"t":"我就观看，看见一匹白马，骑在马上的拿着弓，并有冠冕赐给他。他出来征服，胜而又胜。","notes":[]},{"n":3,"t":"羔羊揭开第二个印的时候，我听见第二个活物说：“你来！”","notes":[]},{"n":4,"t":"就另有一匹马出来，是红色的；有权柄赐给了那骑马的，要从地上夺去太平，使人彼此相杀；他又接受了一把大刀。","notes":[]},{"n":5,"t":"羔羊揭开第三个印的时候，我听见第三个活物说：“你来！”我就观看，看见一匹黑马；骑在马上的，手里拿着天平。","notes":[]},{"n":6,"t":"我听见在四个活物中似乎有声音说：“一个银币买一升麦子，一个银币买三升大麦；油和酒不可糟蹋。”","notes":[]},{"n":7,"t":"羔羊揭开第四个印的时候，我听见第四个活物说：“你来！”","notes":[]},{"n":8,"t":"我就观看，看见一匹灰色马；骑在马上的，名字叫作“死”，阴间也随着他；有权柄赐给他们，可以用刀剑、饥荒、瘟疫、野兽，杀害地上四分之一的人。","notes":[]},{"n":9,"t":"羔羊揭开第五个印的时候，我看见在祭坛底下有曾为神的道，并为作见证而被杀的人的灵魂，","notes":[]},{"n":10,"t":"大声喊着说：“神圣真实的主宰啊，你不审判住在地上的人，为我们所流的血伸冤，要到几时呢？”","notes":[]},{"n":11,"t":"于是有白袍赐给他们各人；又有话吩咐他们还要歇息片刻，等到与他们同作仆人的，和他们的弟兄，像他们一样被杀的人的数目凑足的时候。","notes":[]},{"n":12,"t":"羔羊揭开第六个印的时候，我看见地大震动，太阳变黑像粗麻布，整个月亮变红像血，","notes":[]},{"n":13,"t":"天上的星辰坠落在地上，如同无花果树被大风摇动，落下未熟的果子一样。","notes":[]},{"n":14,"t":"天就裂开，好像书卷被卷起来；山岭海岛都被移动离开原位。","notes":[]},{"n":15,"t":"地上的君王、臣宰、将军、富户、壮士，和一切为奴的、自主的，都藏在山洞和岩石穴里，","notes":[]},{"n":16,"t":"向山和岩石说：“倒在我们身上吧！把我们藏起来，躲避坐宝座者的脸面和羔羊的愤怒；","notes":[]},{"n":17,"t":"因为他们遭愤怒的大日子到了，谁能站得住呢？”","notes":[]}]},"7":{"heading":"十四万四千以色列人受印","verses":[{"n":1,"t":"此后，我看见四位天使站在地的四角，执掌地上四方的风，使风不吹在地上、海上和各种树上。","notes":[]},{"n":2,"t":"我又看见另有一位天使从日出之地上来，拿着永生神的印。他向那得到权柄能伤害地和海的四位天使大声喊着，","notes":[]},{"n":3,"t":"说：“你们不可伤害地、海和树林，等我们在我们神众仆人的额上盖了印。”","notes":[]},{"n":4,"t":"我听见以色列人各支派中受印的数目有十四万四千；","notes":[]},{"n":5,"t":"犹大支派中受印的有一万二千；吕便支派中有一万二千；迦得支派中有一万二千；","notes":[]},{"n":6,"t":"亚设支派中有一万二千；拿弗他利支派中有一万二千；玛拿西支派中有一万二千；","notes":[]},{"n":7,"t":"西缅支派中有一万二千；利未支派中有一万二千；以萨迦支派中有一万二千；","notes":[]},{"n":8,"t":"西布伦支派中有一万二千；约瑟支派中有一万二千；便雅悯支派中受印的有一万二千。","notes":[]},{"n":9,"t":"此后，我观看，看见有许多人，没有人能计算，是从各邦国、各支派、各民族、各语言来的，站在宝座和羔羊面前，身穿白衣，手拿棕树枝，","notes":[],"heads":["无数的人从各国而来"]},{"n":10,"t":"大声喊着说：“愿救恩归于坐在宝座上我们的神，也归于羔羊！”","notes":[]},{"n":11,"t":"众天使都站在宝座和众长老，以及四个活物的周围，俯伏在宝座前，敬拜神，","notes":[]},{"n":12,"t":"说：“阿们！颂赞、荣耀、智慧、感谢、尊贵、权能、力量都归于我们的神，直到永永远远。阿们！”","notes":[]},{"n":13,"t":"长老中有一位回应我说：“这些穿白衣的是谁？是从哪里来的？”","notes":[]},{"n":14,"t":"我对他说：“我主啊，你是知道的。”他向我说：“这些人是从大患难中出来的，他们曾用羔羊的血把衣裳洗得洁白。","notes":[]},{"n":15,"t":"所以，他们在神宝座前，昼夜在他殿中事奉他；那坐在宝座上的要用帐幕覆庇他们。","notes":[]},{"n":16,"t":"他们不再饥，不再渴；太阳必不伤害他们，任何炎热也不伤害他们，","notes":[]},{"n":17,"t":"因为宝座中的羔羊必牧养他们，领他们到生命水的泉源；神必擦去他们一切的眼泪。”","notes":[]}]},"8":{"heading":"第七个印和金香炉","verses":[{"n":1,"t":"羔羊揭开第七个印的时候，天上寂静约有半小时。","notes":[]},{"n":2,"t":"我看见那站在神面前的七位天使，有七枝号赐给他们。","notes":[]},{"n":3,"t":"另有一位天使拿着金香炉来，站在祭坛旁边；有许多香赐给他，要和众圣徒的祈祷一同献在宝座前的金坛上。","notes":[]},{"n":4,"t":"那香的烟和众圣徒的祈祷从天使的手中一同升到神面前。","notes":[]},{"n":5,"t":"天使拿着香炉，盛满了坛上的火，倒在地上；就有雷轰、响声、闪电、地震。","notes":[]},{"n":6,"t":"拿着七枝号筒的七位天使预备好要吹号。","notes":[],"heads":["七枝号筒"]},{"n":7,"t":"第一位天使吹号，就有冰雹和火搀着血扔在地上；地的三分之一和树的三分之一被烧掉了，一切的青草也被烧掉了。","notes":[]},{"n":8,"t":"第二位天使吹号，就有像火烧着的大山扔在海中；海的三分之一变成血，","notes":[]},{"n":9,"t":"海中有生命的被造之物死了三分之一，船只也毁坏了三分之一。","notes":[]},{"n":10,"t":"第三位天使吹号，就有烧着的大星好像火把从天上坠下来，落在江河的三分之一和众水的泉源上。","notes":[]},{"n":11,"t":"这星名叫“苦艾”；众水的三分之一变为苦艾，许多人因水变苦而死了。","notes":[]},{"n":12,"t":"第四位天使吹号，太阳的三分之一、月亮的三分之一、星辰的三分之一都被击打，以致日月星的三分之一变黑了，白昼的三分之一没有光，黑夜也是这样。","notes":[]},{"n":13,"t":"我观看，听见一只在空中飞的鹰大声说：“祸哉！祸哉！祸哉！地上的居民哪，其余的三位天使快要吹号了！”","notes":[]}]},"9":{"heading":"","verses":[{"n":1,"t":"第五位天使吹号，我就看见一颗星从天上坠落到地上；有无底坑的钥匙赐给它。","notes":[]},{"n":2,"t":"它开了无底坑，就有烟从坑里往上冒，好像大火炉的烟；太阳和天空都因这烟昏暗了。","notes":[]},{"n":3,"t":"有蝗虫从烟中出来，飞到地上，有权柄赐给它们，好像地上的蝎子有权柄一样。","notes":[]},{"n":4,"t":"它们奉命不可伤害地上的草、各样绿色植物和各种树木，惟独可伤害额上没有神印记的人；","notes":[]},{"n":5,"t":"但是不许蝗虫害死他们，只可使他们受痛苦五个月；这痛苦就像人被蝎子螫了的痛苦一样。","notes":[]},{"n":6,"t":"在那些日子，人求死，却死不了；想死，死却避开他们。","notes":[]},{"n":7,"t":"蝗虫的形状好像预备上阵的战马一样，头上戴的好像金冠冕，脸面好像男人的脸面，","notes":[]},{"n":8,"t":"头发像女人的头发，牙齿像狮子的牙齿；","notes":[]},{"n":9,"t":"它们胸前有甲，好像铁甲；又有翅膀的响声，好像许多车马奔跑上阵的声音。","notes":[]},{"n":10,"t":"它们有尾巴像蝎子，长着毒刺，尾巴上的毒刺有能力伤害人五个月。","notes":[]},{"n":11,"t":"它们有无底坑的使者作它们的王，按着希伯来话名叫亚巴顿，希腊话名叫亚玻伦。","notes":[]},{"n":12,"t":"第一样灾祸过去了；看哪，还有两样灾祸要来。","notes":[]},{"n":13,"t":"第六位天使吹号，我听见有声音从神面前金坛的四角发出来，","notes":["有古卷没有“四”。"]},{"n":14,"t":"吩咐那吹号的第六位天使，说：“把那捆绑在幼发拉底大河的四个使者释放了。”","notes":[]},{"n":15,"t":"那四个使者就被释放；他们原是预备好，在特定的年、月、日、时，要杀人类的三分之一。","notes":[]},{"n":16,"t":"骑兵有二亿；他们的数目我听见了。","notes":[]},{"n":17,"t":"我在异象中看见那些马和骑马的：骑马的穿着火红、紫玛瑙及硫磺色的胸甲；马的头好像狮子的头，有火、有烟、有硫磺从马的口中喷出来。","notes":[]},{"n":18,"t":"从马的口中所喷出来的火、烟和硫磺这三样灾害杀了人类的三分之一。","notes":[]},{"n":19,"t":"马的能力在于它们的口和尾巴；它们的尾巴像蛇，有头，用头来伤害人。","notes":[]},{"n":20,"t":"其余未曾被这些灾难所杀的人仍旧不为自己手所做的悔改，还是去拜鬼魔和那些不能看、不能听、不能走，用金、银、铜、木、石所造的偶像。","notes":[]},{"n":21,"t":"他们也不为自己所犯的那些凶杀、邪术、淫乱、偷窃的事悔改。","notes":[]}]},"10":{"heading":"天使和小书卷","verses":[{"n":1,"t":"我又看见另一位大力的天使从天降下，披着云彩，头上有彩虹，脸面像太阳，两脚像火柱。","notes":[]},{"n":2,"t":"他手里拿着展开的小书卷。他右脚踏海，左脚踏地，","notes":[]},{"n":3,"t":"大声呼喊，好像狮子吼叫。呼喊完了，就有七个雷发出声音。","notes":[]},{"n":4,"t":"七个雷发声后，我正要写出来，就听见从天上有声音说：“七个雷所说的，你要封上，不可写出来。”","notes":[]},{"n":5,"t":"我所看见的那踏海踏地的天使向天举起右手，","notes":[]},{"n":6,"t":"指着创造天和天上之物、地和地上之物、海和海中之物、直活到永永远远的那位起誓，说：“不再有时日了。”","notes":["“不再有时日了”或译“不再耽延了”。"]},{"n":7,"t":"但在第七位天使要吹号的日子，神的奥秘就要成全了，正如神向他仆人众先知所宣告的。","notes":[]},{"n":8,"t":"我先前从天上所听见的那声音又吩咐我说：“你去，把那踏海踏地之天使手中展开的小书卷拿过来。”","notes":[]},{"n":9,"t":"我就走到天使那里，对他说，请他把小书卷给我。他对我说：“你拿去，把它吃光。它会使你肚子发苦，然而在你口中会甘甜如蜜。”","notes":[]},{"n":10,"t":"于是我从天使手中把小书卷接过来，把它吃光了，在我口中果然甘甜如蜜，吃了以后，我肚子觉得发苦。","notes":[]},{"n":11,"t":"天使们对我说：“你必须指着许多民族、邦国、语言、君王再说预言。”","notes":[]}]},"11":{"heading":"两个见证人","verses":[{"n":1,"t":"有一根芦苇，像丈量的杖，赐给我；且有话说：“起来！将神的殿和祭坛，以及在殿中礼拜的人，都量一量。","notes":[]},{"n":2,"t":"只是殿外的院子不用量，因为这是要给外邦人的；他们将践踏圣城四十二个月。","notes":[]},{"n":3,"t":"“我要赐权柄给我那两个见证人，穿着粗麻衣说预言一千二百六十天。”","notes":[]},{"n":4,"t":"他们就是那站在世界之主面前的两棵橄榄树和两个灯台。","notes":[]},{"n":5,"t":"若有人想要害他们，就有火从他们口中喷出来，烧灭仇敌；凡想要害他们的都必须这样被杀。","notes":[]},{"n":6,"t":"这二人有权柄关闭天空，使他们说预言的日子不下雨；又有权柄使水变为血，并且能随时随意用各样的灾害击打大地。","notes":[]},{"n":7,"t":"他们作完见证的时候，那从无底坑里上来的兽要跟他们交战，并且得胜，把他们杀了。","notes":[]},{"n":8,"t":"他们的尸首将倒在大城的街道上；这城按着灵意叫所多玛，又叫埃及，就是他们的主钉十字架的地方。","notes":[]},{"n":9,"t":"从各民族、支派、语言、邦国中有人观看他们的尸首三天半，又不许人把尸首安放在坟墓里。","notes":[]},{"n":10,"t":"住在地上的人会因他们而欢喜快乐，互相馈送礼物，因为这两位先知曾使住在地上的人受痛苦。","notes":[]},{"n":11,"t":"过了这三天半，有生命的气息从神那里进入他们里面，他们就站起来；看见他们的人都大大惧怕。","notes":[]},{"n":12,"t":"两位先知听见有大声音从天上对他们说：“上这里来。”他们就驾着云上了天，他们的仇敌也看见了。","notes":[]},{"n":13,"t":"正在那时候，地大震动，城倒塌了十分之一；因地震而死的有七千人，其余的都恐惧，归荣耀给天上的神。","notes":[]},{"n":14,"t":"第二样灾祸过去了；看哪，第三样灾祸快到了。","notes":[]},{"n":15,"t":"第七位天使吹号，天上就有大声音说：“世上的国已成了我们的主和他所立的基督的国了。他要作王直到永永远远！”","notes":[],"heads":["第七枝号筒"]},{"n":16,"t":"在神面前，坐在自己座位上的二十四位长老都俯伏在地上敬拜神，","notes":[]},{"n":17,"t":"说：“今在昔在的主—全能的神啊，我们感谢你！因你执掌大权作王了。","notes":[]},{"n":18,"t":"外邦发怒，你的愤怒临到了。审判死人的时候也到了；你的仆人众先知、众圣徒及敬畏你名的人，连大带小得赏赐的时候到了；你毁灭那些毁灭大地者的时候也到了。”","notes":[]},{"n":19,"t":"于是，神天上的圣所开了，在他圣所中，他的约柜出现了；随后有闪电、响声、雷轰、地震、大冰雹。","notes":[]}]},"12":{"heading":"妇人和龙","verses":[{"n":1,"t":"天上出现了一个大兆头：有一个妇人身披太阳，脚踏月亮，头戴十二颗星的冠冕；","notes":[]},{"n":2,"t":"她怀了孕，在生产的阵痛中疼痛地喊叫。","notes":[]},{"n":3,"t":"天上又出现了另一个兆头：有一条大红龙，有七个头十个角；七个头上戴着七个冠冕。","notes":["“龙”：原文音译“杜拉根”，指万恶之兽。"]},{"n":4,"t":"它的尾巴拖拉着天上星辰的三分之一，把它们摔在地上。然后龙站在那将要生产的妇人面前，等她生产后要吞吃她的孩子。","notes":[]},{"n":5,"t":"妇人生了一个男孩子，就是将来要用铁杖管辖万国的；她的孩子被提到神和他宝座那里去。","notes":["“管辖”：原文直译“牧养”。"]},{"n":6,"t":"妇人就逃到旷野，在那里有神给她预备的地方，使她在那里被供养一千二百六十天。","notes":[]},{"n":7,"t":"天上发生了争战。米迦勒同他的使者与龙作战，龙同它的使者也起来应战，","notes":[]},{"n":8,"t":"它们都打败了，天上再也没有它们的地方。","notes":[]},{"n":9,"t":"大龙就是那古蛇，名叫魔鬼，又叫撒但，是迷惑普天下的；它被摔在地上，它的使者也一同被摔下去。","notes":[]},{"n":10,"t":"我听见在天上有大声音说：“我神的救恩、能力、国度，和他所立的基督的权柄现在都来到了。因为那个在我们神面前、昼夜控告我们弟兄的，已经被摔下去了。","notes":[]},{"n":11,"t":"弟兄胜过那条龙是因羔羊的血，和因自己所见证的道。虽然至于死，他们也不惜自己的性命。","notes":[]},{"n":12,"t":"所以，诸天和住在其中的，你们都快乐吧！只是地和海有祸了！因为魔鬼知道自己的时候不多，就气愤愤地下到你们那里去了。”","notes":[]},{"n":13,"t":"龙见自己被摔在地上，就迫害那生男孩子的妇人。","notes":[]},{"n":14,"t":"于是有大鹰的两个翅膀赐给妇人，让她能飞到旷野，到自己的地方，躲避那蛇。她在那里受供养一载二载半载。","notes":[]},{"n":15,"t":"蛇在妇人背后，从口中喷出水来，像河一样，要将妇人冲走。","notes":[]},{"n":16,"t":"地却帮助了妇人，开口吞了从龙口喷出来的水。","notes":[]},{"n":17,"t":"于是龙向妇人发怒，去与她其余的儿女作战，就是与那些遵守神命令、为耶稣作见证的。","notes":["“命令”或译“诫命”。","“为耶稣作见证的”：原文直译“有耶稣的见证的”；19．10同。"]},{"n":18,"t":"那时龙站在海边沙滩上。","notes":[]}]},"13":{"heading":"两只兽","verses":[{"n":1,"t":"我又看见一只兽从海里上来，有十个角七个头；在十个角上戴着十个冠冕，七个头上有亵渎的名号。","notes":[]},{"n":2,"t":"我所看见的兽，形状像豹，脚像熊的脚，口像狮子的口。那条龙将自己的能力、座位和大权柄都给了它。","notes":[]},{"n":3,"t":"我看见兽的七个头中，有一个似乎受了致命伤，那伤却医好了。全地的人都很惊讶，跟从了那只兽。","notes":[]},{"n":4,"t":"他们都拜那条龙，因为它把自己的权柄给了兽；又拜那只兽，说：“谁能比这只兽，谁能与它交战呢？”","notes":[]},{"n":5,"t":"龙又赐给那只兽说夸大亵渎话的口，又赐给它权柄可以任意行事四十二个月。","notes":[]},{"n":6,"t":"那兽就开口向神说亵渎的话，亵渎神的名和他的帐幕，就是那些住在天上的。","notes":[]},{"n":7,"t":"它又被准许与圣徒作战，并且得胜，也赐给它权柄，可以制伏各支派、各民族、各语言、各邦国。","notes":[]},{"n":8,"t":"凡住在地上、名字从创世以来没有记在被杀羔羊的生命册上的人都要拜它。","notes":[]},{"n":9,"t":"凡有耳朵的都听吧！","notes":[]},{"n":10,"t":"该被掳掠的，必被掳掠；该被刀杀的，必被刀杀。在此，圣徒要有耐心和信心。","notes":[]},{"n":11,"t":"我又看见另一只兽从地里上来。它有两个角如同羔羊，说话好像龙。","notes":[]},{"n":12,"t":"它在第一只兽面前施行第一只兽所有的权柄，并且使地和住在地上的人拜那致命伤被医好了的第一只兽。","notes":[]},{"n":13,"t":"这只兽又行大奇事，甚至在人面前使火从天降在地上。","notes":[]},{"n":14,"t":"它得了权柄在第一只兽面前能行奇事，迷惑住在地上的人，告诉他们要为那受过刀伤还活着的兽造个像。","notes":[]},{"n":15,"t":"又有权柄赐给它，让那只兽的像有生气，并且能说话，又使所有不拜兽像的人都被杀害。","notes":[]},{"n":16,"t":"它又使众人，无论大小、贫富，自主的、为奴的，都在右手上，或是在额上，打一个印记；","notes":[]},{"n":17,"t":"这样，除了那有印记，有兽的名或有兽名数字的，都不得买或卖。","notes":[]},{"n":18,"t":"在此，要有智慧：让有悟性的人解开兽的数目吧，因为这是一个人的数字，那数字是六百六十六。","notes":[]}]},"14":{"heading":"十四万四千人的歌","verses":[{"n":1,"t":"我又观看，看见羔羊站在锡安山，和他在一起的有十四万四千人，都有他的名和他父亲的名写在额上。","notes":[]},{"n":2,"t":"我听见从天上有声音，像众水的声音和大雷的声音，我所听见的声音好像琴师所弹的琴声。","notes":[]},{"n":3,"t":"他们在宝座前，和在四活物及众长老前唱新歌，除了从地上买来的那十四万四千人以外，没有人能学这歌。","notes":[]},{"n":4,"t":"这些人未曾沾染妇女，他们原是童身。羔羊无论往哪里去，他们都跟随他。他们是从人间买来的，作为初熟的果子归给神和羔羊。","notes":[]},{"n":5,"t":"在他们口中找不出谎言，他们是没有瑕疵的。","notes":[]},{"n":6,"t":"我又看见另一位天使在空中飞翔，有永远的福音要传给住在地上的人，就是各邦国、各支派、各语言、各民族。","notes":[],"heads":["三位天使的信息"]},{"n":7,"t":"他大声说：“要敬畏神，把荣耀归给他，因为他施行审判的时候已经到了。要敬拜那创造天、地、海和水源的主。”","notes":[]},{"n":8,"t":"另有第二位天使接着说：“倾覆了！那曾叫列国喝淫乱、烈怒之酒的大巴比伦倾覆了！”","notes":[]},{"n":9,"t":"另有第三位天使接着他们，大声说：“若有人拜那只兽和兽像，在额上或在手上受了印记，","notes":[]},{"n":10,"t":"他也必喝神烈怒的酒；这酒是斟在神愤怒的杯中的纯酒。他要在圣天使和羔羊面前，在火与硫磺之中受痛苦。","notes":[]},{"n":11,"t":"使他们受痛苦的烟往上冒，直到永永远远。那些拜兽和兽像，受了它名字的印记的人，昼夜不得安宁。”","notes":[]},{"n":12,"t":"在此，遵守神命令和坚信耶稣真道的圣徒要有耐心。","notes":["“命令”或译“诫命”。"]},{"n":13,"t":"我听见从天上有声音说：“你要写下：从今以后，在主里死去的人有福了。”圣灵说：“是的，他们要从自己的劳苦中得安息，因为工作的成果永随着他们。”","notes":[]},{"n":14,"t":"我又观看，看见有一片白云，云上坐着一位好像是人子的，头上戴着金冠冕，手里拿着锋利的镰刀。","notes":[],"heads":["地上的收割"]},{"n":15,"t":"另有一位天使从圣所出来，向那坐在云上的大声喊着：“伸出你的镰刀来收割吧，因为收割的时候已经到了，地上的庄稼已经熟透了。”","notes":[]},{"n":16,"t":"于是那坐在云上的把镰刀向地上挥去，地上的庄稼就收割了。","notes":[]},{"n":17,"t":"另有一位天使从天上的圣所出来，他也拿着锋利的镰刀。","notes":[]},{"n":18,"t":"另有一位天使从祭坛出来，是有权柄管火的，向那拿着锋利镰刀的大声喊着说：“伸出锋利的镰刀来，收取地上葡萄树的果子，因为葡萄熟透了。”","notes":[]},{"n":19,"t":"那天使就把镰刀向地上挥去，收取了地上的葡萄，扔进神愤怒的大榨酒池里。","notes":[]},{"n":20,"t":"那榨酒池在城外被踹踏，有血从榨酒池里流出来，涨到马的嚼环那么高，约有一千六百斯他迪那么远。","notes":["“斯他迪”：古希腊长度单位；21．16同；参“度量衡表”。"]}]},"15":{"heading":"七位天使掌管最后的灾难","verses":[{"n":1,"t":"我看见在天上有另一兆头，大而且奇，就是七位天使掌管末了的七种灾难，因为神的烈怒在这七种灾难中发尽了。","notes":[]},{"n":2,"t":"我看见仿佛有搀杂火的玻璃海；又看见那些胜了那兽和兽像，以及它名字的数字的人，都站在玻璃海上，拿着神的竖琴。","notes":[]},{"n":3,"t":"他们唱神仆人摩西的歌和羔羊的歌，说：“主—全能的神啊，你的作为又伟大又奇妙！万国之王啊，你的道路又公义又真实！","notes":[]},{"n":4,"t":"主啊，谁敢不敬畏你，不把荣耀归于你的名？因为只有你是神圣的。万民都要来，在你面前敬拜，因你公义的作为已经彰显了。”","notes":[]},{"n":5,"t":"此后，我看见在天上那存放法柜的圣所开了。","notes":[]},{"n":6,"t":"那掌管七种灾难的七位天使从圣所出来，穿着洁白明亮的细麻衣，胸间束着金带。","notes":["“细麻衣”：有古卷是“宝石”。"]},{"n":7,"t":"四个活物中，有一个把盛满了活到永永远远之神烈怒的七个金碗给了那七位天使。","notes":[]},{"n":8,"t":"圣所中充满了神的荣耀和权能而来的烟。没有人能进入圣所，直等到那七位天使降完了七种灾难。","notes":[]}]},"16":{"heading":"神烈怒的碗","verses":[{"n":1,"t":"我听见有大声音从圣所里出来，向那七位天使说：“你们去，把盛着神烈怒的七碗倾倒在地上。”","notes":[]},{"n":2,"t":"第一位天使去，把碗倾倒在地上，就有又臭又毒的疮生在那些有兽的印记和拜兽像的人身上。","notes":[]},{"n":3,"t":"第二位天使把碗倾倒在海里，海就变成像死人的血一样，海里所有的活物都死了。","notes":[]},{"n":4,"t":"第三位天使把碗倾倒在河流和水源里，水就变成血了。","notes":[]},{"n":5,"t":"我听见掌管众水的天使说：“昔在、今在的圣者啊，你做的判断公义；","notes":[]},{"n":6,"t":"因他们曾流过圣徒与先知的血，现在你给他们血喝，这是他们该受的。”","notes":[]},{"n":7,"t":"我又听见祭坛中有声音说：“是的，主—全能的神啊，你的判断又真实又公义！”","notes":[]},{"n":8,"t":"第四位天使把碗倾倒在太阳上，使太阳可用火烤人。","notes":[]},{"n":9,"t":"人被炎热所烤，就亵渎那有权掌管这些灾难的神的名，他们没有悔改，也没有把荣耀归给神。","notes":[]},{"n":10,"t":"第五位天使把碗倾倒在兽的座位上，兽的国就变成黑暗。人因疼痛而咬自己的舌头；","notes":[]},{"n":11,"t":"又因所受的疼痛和生的疮，就亵渎天上的神，也没有为他们的行为悔改。","notes":[]},{"n":12,"t":"第六位天使把碗倾倒在大幼发拉底河上，河水就干了，为要给从日出之地所来的众王预备道路。","notes":[]},{"n":13,"t":"我又看见三个污秽的灵，好像青蛙，从龙的口、兽的口和假先知的口中出来。","notes":[]},{"n":14,"t":"他们本是鬼魔的灵，施行奇事，到普天下众王那里去，召集他们在全能者神的大日子作战。","notes":[]},{"n":15,"t":"看哪，我来像贼一样。那警醒、穿着衣服的人有福了；他不至于赤身而行，给人看见他的羞耻。","notes":[]},{"n":16,"t":"于是，那三个鬼魔把众王聚集在希伯来话叫作哈米吉多顿的地方。","notes":[]},{"n":17,"t":"第七位天使把碗倾倒在空中，就有大声音从圣所的宝座上出来，说：“成了！”","notes":[]},{"n":18,"t":"又有闪电、响声、雷轰、大地震，自从地上有人以来没有这样大、这样厉害的地震。","notes":[]},{"n":19,"t":"那大城裂为三段，列国的城也都倒塌了。神记起了大巴比伦城，把那盛自己烈怒的酒杯递给她。","notes":[]},{"n":20,"t":"各海岛都逃避了，众山也不见了。","notes":[]},{"n":21,"t":"又有大冰雹从天掉落在人身上，每一个约重一他连得，以致人因冰雹的灾难而亵渎神，因为那灾难太大了。","notes":[]}]},"17":{"heading":"大淫妇和兽","verses":[{"n":1,"t":"拿着七个碗的七位天使中，有一位前来对我说：“来，我要让你看那坐在众水之上的大淫妇所要受的惩罚；","notes":[]},{"n":2,"t":"地上的君王都曾与她行淫，住在地上的人也喝醉了她淫乱的酒。”","notes":[]},{"n":3,"t":"我在圣灵感动下，被天使带到旷野去，我看见一个女人骑在朱红色的兽上；那只兽有七个头十个角，遍体有亵渎的名号。","notes":[]},{"n":4,"t":"那女人穿着紫色和朱红色的衣服，用金子、宝石、珍珠作妆饰，手拿着金杯，杯中盛满了可憎之物和她淫乱的污秽。","notes":[]},{"n":5,"t":"在她额上写着奥秘的名字，说：“大巴比伦，世上的淫妇和一切可憎之物的母。”","notes":[]},{"n":6,"t":"我又看见那女人喝醉了圣徒的血和为耶稣作见证的人的血。我看见她，非常诧异。","notes":[]},{"n":7,"t":"天使对我说：“你为什么诧异呢？我要把这女人和驮着她那七头十角的兽的奥秘告诉你。","notes":[]},{"n":8,"t":"你曾看见的兽，以前有，现在没有，将来要从无底坑里上来，又归于沉沦。凡住在地上、名字从创世以来没有记在生命册上的人看见那只兽都要诧异，因为它以前有，现在没有，以后再有。","notes":[]},{"n":9,"t":"在此要有智慧的心思：那七个头就是女人所坐的七座山；他们又是七个王，","notes":[]},{"n":10,"t":"五个已经倒了，一个还在，一个还没有来到；他来的时候必须只暂时停留。","notes":[]},{"n":11,"t":"那以前有、现在没有的兽就是第八个，他也和那七个同列，正归于沉沦。","notes":[]},{"n":12,"t":"你曾看见的那十个角就是十个王；他们还没有得到国度，但他们要和那只兽同得权柄作王一个时辰。","notes":[]},{"n":13,"t":"他们同心把自己的能力权柄交给那只兽。","notes":[]},{"n":14,"t":"他们将与羔羊作战，羔羊必胜过他们，因为羔羊是万主之主、万王之王，而同羔羊在一起的是蒙召、被选、忠心的人。”","notes":[]},{"n":15,"t":"天使又对我说：“你所看见那淫妇坐的众水，就是许多民族、人民、邦国、语言。","notes":[]},{"n":16,"t":"你所看见的那十个角与兽必恨这淫妇，他们要使她孤独赤身，又要吃她的肉，用火将她烧尽。","notes":[]},{"n":17,"t":"因为神使诸王同心执行他的旨意，把他们自己的国交给那只兽，直等到神的话都应验了。","notes":[]},{"n":18,"t":"你所看见的那女人就是管辖地上众王的大城。”","notes":[]}]},"18":{"heading":"巴比伦倾覆","verses":[{"n":1,"t":"此后，我看见另一位有大权柄的天使从天降下，地由于他的荣耀而发光。","notes":[]},{"n":2,"t":"他以强而有力的声音喊着说：“倾覆了！大巴比伦倾覆了！她成了鬼魔的住处，各样污秽之灵的巢穴，各样污秽之鸟的窝，各样污秽可憎之兽的出没处。","notes":["“各样污秽之鸟…出没处”：有古卷是“各样污秽可憎之鸟的窝”。"]},{"n":3,"t":"因为列国都喝了她淫乱大怒的酒；地上的君王和她行淫；地上的商人因她极度奢华而发了财。”","notes":["“喝了…酒”：有古卷是“因她淫乱大怒的酒而倾倒了”。"]},{"n":4,"t":"我又听见另一个声音从天上说：“我的民哪，从那城出来吧！免得和她在罪上有份，受她所受的灾殃；","notes":[]},{"n":5,"t":"因她的罪恶滔天，神已经记得她的不义。","notes":[]},{"n":6,"t":"她怎样待人，也要怎样待她，按她所行的加倍地报应她；用她调酒的杯加倍调给她喝。","notes":[]},{"n":7,"t":"她怎样荣耀自己，怎样奢华，也要使她照样痛苦悲哀。因她心里说：‘我坐了皇后的位，并不是寡妇，绝不至于悲哀。’","notes":[]},{"n":8,"t":"所以在一天之内，她的灾殃要一齐来到，就是死亡、悲哀、饥荒。她将被火烧尽，因为审判她的主神大有能力。”","notes":[]},{"n":9,"t":"地上的君王，与她行淫、一同奢华的，看见烧她的烟，就必为她哭泣哀号；","notes":[]},{"n":10,"t":"因怕她的痛苦，就远远地站着，说：“祸哉，祸哉，这大城！坚固的巴比伦城啊！一时之间，你的审判要来到了。”","notes":[]},{"n":11,"t":"地上的商人也都为她哭泣悲哀，因为没有人再买他们的货物了；","notes":[]},{"n":12,"t":"这货物就是金、银、宝石、珍珠、细麻布、丝绸、紫色和朱红色衣料、各样香木、各样象牙的器皿、各样极宝贵的木头和铜、铁、大理石的器皿，","notes":[]},{"n":13,"t":"和肉桂、豆蔻、香料、香膏、乳香、酒、油、细面、麦子、牛、羊、马、马车，以及奴隶、人口。","notes":[]},{"n":14,"t":"“你所贪爱的果子离开了你；你一切的珍馐美味和华美的物件都从你那里毁灭，绝对见不到了。”","notes":[]},{"n":15,"t":"贩卖这些货物、藉着她发财的商人，因怕她的痛苦，就远远地站着哭泣悲哀，","notes":[]},{"n":16,"t":"说：“祸哉，祸哉，这大城！她穿着细麻、紫色、朱红色的衣服，用金子、宝石、珍珠为妆饰。","notes":[]},{"n":17,"t":"一时之间，这么多的财富就归于无有了。”所有的船长和到处航海的，水手以及所有靠海为业的，都远远地站着，","notes":[]},{"n":18,"t":"看见烧她的烟，就喊着说：“有哪一个城能跟这大城比呢？”","notes":[]},{"n":19,"t":"于是他们把灰尘撒在头上，哭泣悲哀地喊着说：“祸哉，祸哉，这大城！凡有船在海中的，都因她的珍宝成了富足。她在一时之间就成为荒芜。","notes":[]},{"n":20,"t":"天哪，众圣徒、众使徒、众先知啊！你们都要因她欢喜，因为神已经在她身上为你们伸了冤。”","notes":[]},{"n":21,"t":"有一位大力的天使举起一块石头，好像大磨石，扔在海里，说：“巴比伦大城也必这样猛力地被扔下去，绝对见不到了。","notes":[]},{"n":22,"t":"弹琴、歌唱、吹笛、吹号的声音，在你中间绝对听不见了；各行手艺的技工在你中间绝对见不到了；推磨的声音在你中间绝对听不见了；","notes":[]},{"n":23,"t":"灯台的光在你中间绝对不再照耀了；新郎和新娘的声音在你中间绝对听不见了。你的商人原来是地上的显要；万国也被你的邪术迷惑了。","notes":[]},{"n":24,"t":"先知、圣徒和地上一切被杀的人的血都在这城里找到了。”","notes":[]}]},"19":{"heading":"羔羊的婚宴","verses":[{"n":1,"t":"此后，我听见好像有一大群人在天上大声说：“哈利路亚！救恩、荣耀、权能都属于我们的神。","notes":["“哈利路亚”就是“要赞美耶和华”的意思。"]},{"n":2,"t":"他的判断又真实又公义；因他判断了那大淫妇，她用淫行败坏了世界。神为他的仆人伸冤，向淫妇讨流仆人血的罪。”","notes":[]},{"n":3,"t":"他们又一次说：“哈利路亚！烧淫妇的烟往上冒，直到永永远远。”","notes":[]},{"n":4,"t":"那二十四位长老和四活物就俯伏敬拜坐在宝座上的神，说：“阿们。哈利路亚！”","notes":[]},{"n":5,"t":"接着，有声音从宝座出来说：“神的众仆人哪，凡敬畏他的，无论大小，都要赞美我们的神！”","notes":[]},{"n":6,"t":"我听见好像一大群人的声音，像众水的声音，像大雷的声音，说：“哈利路亚！因为主─我们的神、全能者，作王了。","notes":["“主─我们的神”：有古卷是“神我们的主”；另有古卷是“我们的神”，或“主神”，或“主”。"]},{"n":7,"t":"我们要欢喜快乐，将荣耀归给他；因为羔羊的婚期到了，他的新娘也自己预备好了，","notes":[]},{"n":8,"t":"她蒙恩得穿明亮洁白的细麻衣：这细麻衣就是圣徒们的义行。”","notes":[]},{"n":9,"t":"天使对我说：“你要写下来：凡被请赴羔羊婚宴的人有福了！”他又对我说：“这些都是神真实的话。”","notes":[]},{"n":10,"t":"我就俯伏在他脚前要拜他。他对我说：“千万不可！我和你，以及那些为耶稣作见证的弟兄同是仆人。你要敬拜神。”因为那些为耶稣作见证的人有预言的灵。","notes":[]},{"n":11,"t":"后来我看见天开了。有一匹白马，骑在马上的称为“诚信”、“真实”，他审判和争战都凭着公义。","notes":["有古卷没有“称为”。"],"heads":["白马骑士"]},{"n":12,"t":"他的眼睛如火焰，头上戴着许多冠冕；他身上写着一个名字，除了他自己没有人知道。","notes":["有古卷没有“如”。"]},{"n":13,"t":"他穿着浸过血的衣服；他的名称为“神之道”。","notes":[]},{"n":14,"t":"众天军都骑着白马，穿着又白又洁净的细麻衣跟随他。","notes":[]},{"n":15,"t":"有利剑从他口中出来，用来击打列国。他要用铁杖管辖他们，并且要踹全能神烈怒的榨酒池。","notes":["“管辖”：原文直译“牧养”。"]},{"n":16,"t":"在他衣服和大腿上写着“万王之王，万主之主”的名号。","notes":[]},{"n":17,"t":"我又看见一位天使站在太阳中，向天空一切的飞鸟大声喊着说：“你们聚集来赴神的大宴席，","notes":[]},{"n":18,"t":"为要吃君王的肉、将军的肉、壮士的肉、马和骑士的肉、一切自主的和为奴的，以及尊贵的和卑贱的肉。”","notes":[]},{"n":19,"t":"我又看见那兽和地上的君王，和他们的军队都聚集，要与白马骑士和他的军队作战。","notes":[]},{"n":20,"t":"那兽被擒拿了；那在兽面前曾行奇事、迷惑了接受兽的印记和拜兽像的人的假先知，也与兽同被擒拿。他们两个就活生生地被扔进烧着硫磺的火湖里，","notes":[]},{"n":21,"t":"其余的人被白马骑士口中吐出来的剑杀了；所有的飞鸟都吃饱了他们的肉。","notes":[]}]},"20":{"heading":"一千年","verses":[{"n":1,"t":"我又看见一位天使从天降下，手里拿着无底坑的钥匙和一条大铁链。","notes":[]},{"n":2,"t":"他抓住那龙，那古蛇，就是魔鬼、撒但，把它捆绑了一千年，","notes":[]},{"n":3,"t":"扔在无底坑里，把无底坑关闭，用印封上，使它不再迷惑列国，等到那一千年满了。这些事以后，它必须暂时被释放。","notes":[]},{"n":4,"t":"我又看见一些宝座，坐在上面的有审判的权柄赐给他们。我又看见那些因为给耶稣作见证，并为神之道被斩首的人的灵魂，和没有拜过那兽与兽像、也没有在额上和手上打过它印记的人的灵魂。他们都复活了，与基督一同作王一千年。","notes":[]},{"n":5,"t":"这是头一次的复活。其余的死人还没有复活，直等那一千年满了。","notes":[]},{"n":6,"t":"在头一次复活有份的有福了，圣洁了！第二次的死在他们身上没有权柄，但他们要作神和基督的祭司，也要与基督一同作王一千年。","notes":[]},{"n":7,"t":"那一千年满了，撒但会从监牢里被释放，","notes":[],"heads":["击败撒但"]},{"n":8,"t":"出来要迷惑地上四方的列国，就是歌革和玛各，使他们聚集争战。他们的人数多如海沙。","notes":[]},{"n":9,"t":"他们上来布满了全地，围住圣徒的营与蒙爱的城，就有火从天降下，烧灭了他们。","notes":[]},{"n":10,"t":"那迷惑他们的魔鬼被扔进硫磺的火湖里，就是那兽和假先知所在的地方，他们会昼夜受折磨，直到永永远远。","notes":[]},{"n":11,"t":"我又看见一个白色的大宝座和那坐在上面的；天和地都从他面前逃避，再也找不到它们的位置了。","notes":[],"heads":["末日的审判"]},{"n":12,"t":"我又看见死了的人，无论大小，都站在宝座前。案卷都展开了，并另有一卷展开，就是生命册。死了的人都凭着这些案卷所记载的，照他们所行的受审判。","notes":[]},{"n":13,"t":"于是海交出其中的死人，死亡和阴间也交出其中的死人；他们都照各人所行的受审判。","notes":[]},{"n":14,"t":"死亡和阴间也被扔进火湖里，这火湖就是第二次的死。","notes":[]},{"n":15,"t":"凡名字没有记在生命册上的人，就被扔进火湖里。","notes":[]}]},"21":{"heading":"新天新地","verses":[{"n":1,"t":"我又看见一个新天新地，因为先前的天和先前的地已经过去了，海也不再有了。","notes":[]},{"n":2,"t":"我又看见圣城，新耶路撒冷由神那里，从天而降，预备好了，就如新娘打扮整齐，等候丈夫。","notes":[]},{"n":3,"t":"我听见有大声音从宝座出来，说：“看哪，神的帐幕在人间！他要和他们同住，他们要作他的子民。神要亲自与他们同在。","notes":["有古卷加“作他们的神。”"]},{"n":4,"t":"神要擦去他们一切的眼泪；不再有死亡，也不再有悲哀、哭号、痛苦，因为先前的事都过去了。”","notes":[]},{"n":5,"t":"那位坐在宝座上的说：“看哪，我把一切都更新了！”他又说：“你要写下来，因为这些话是可信靠的，是真实的。”","notes":[]},{"n":6,"t":"他又对我说：“成了！我是阿拉法，我是俄梅戛；我是开始，我是终结。我要把生命的泉水白白赐给那口渴的人喝。","notes":[]},{"n":7,"t":"得胜的要承受这些为业；我要作他的神，他要作我的儿子。","notes":[]},{"n":8,"t":"至于胆怯的、不信的、可憎的、杀人的、淫乱的、行邪术的、拜偶像的和一切说谎话的人，他们将在烧着硫磺的火湖里有份；这是第二次的死。”","notes":[]},{"n":9,"t":"拿着七个金碗、盛满末后七种灾祸的七位天使中，有一位来对我说：“你来，我要给你看新娘，就是羔羊的妻子。”","notes":[],"heads":["新耶路撒冷"]},{"n":10,"t":"我在圣灵感动下，天使带我到一座高大的山，给我看由神那里、从天而降的圣城耶路撒冷，","notes":[]},{"n":11,"t":"这城有神的荣耀，它光辉如同极贵的宝石，好像碧玉，明如水晶。","notes":[]},{"n":12,"t":"它有高大的墙，有十二个门，门上有十二位天使，门上又写着以色列人十二个支派的名字。","notes":["有古卷没有“的名字”。"]},{"n":13,"t":"东边有三个门，北边有三个门，南边有三个门，西边有三个门。","notes":[]},{"n":14,"t":"城墙有十二个根基，根基上有羔羊十二使徒的名字。","notes":[]},{"n":15,"t":"那对我说话的天使拿着金的芦苇当尺，要量那城、城门和城墙。","notes":[]},{"n":16,"t":"城是四方的，长宽一样。天使用芦苇量那城，共有一万二千斯他迪，长、宽、高都是一样。","notes":[]},{"n":17,"t":"他又量了城墙，按着人的尺寸，就是天使的尺寸，共有一百四十四肘。","notes":[]},{"n":18,"t":"墙是碧玉造的；城是纯金的，如同明净的玻璃。","notes":[]},{"n":19,"t":"城墙的根基是用各样宝石修饰的：第一个根基是碧玉，第二是蓝宝石，第三是绿玛瑙，第四是绿宝石，","notes":[]},{"n":20,"t":"第五是红玛瑙，第六是红宝石，第七是黄璧玺，第八是水苍玉，第九是红璧玺，第十是翡翠，第十一是紫玛瑙，第十二是紫晶。","notes":[]},{"n":21,"t":"十二个门是十二颗珍珠；每一个门是一颗珍珠造的。城内的街道是纯金的，好像透明的玻璃。","notes":[]},{"n":22,"t":"我没有看见城内有殿，因主—全能者神和羔羊就是城的殿。","notes":[]},{"n":23,"t":"那城内不用日月光照，因为有神的荣耀光照，又有羔羊为城的灯。","notes":[]},{"n":24,"t":"列国要藉着城的光行走；地上的君王要把自己的荣耀带给那城。","notes":[]},{"n":25,"t":"城门白昼总不关闭，在那里没有黑夜。","notes":[]},{"n":26,"t":"人要将列国的荣耀尊贵带给那城。","notes":[]},{"n":27,"t":"凡不洁净的，和那行可憎与虚谎之事的人，都不得进那城，只有名字写在羔羊生命册上的才得进去。","notes":[]}]},"22":{"heading":"基督来临","verses":[{"n":1,"t":"天使又让我看一道生命水的河，明亮如水晶，从神和羔羊的宝座流出来，","notes":[]},{"n":2,"t":"经过城内街道的中央；在河的两边有生命树，结十二样 的果子，每月都结果子；树上的叶子可作医治万民之用。","notes":["“样”或译“回”。"]},{"n":3,"t":"以后不再有任何诅咒。在城里将有神和羔羊的宝座。他的仆人都要事奉他，","notes":[]},{"n":4,"t":"也要见他的面。他的名字将写在他们的额上。","notes":[]},{"n":5,"t":"不再有黑夜；他们也不需要灯光或日光，因为主神要光照他们。他们要作王，直到永永远远。","notes":[]},{"n":6,"t":"天使又对我说：“这些话是可信靠的，是真实的。主，就是赐灵感给众先知的神，差遣他的使者，要将必须快要发生的事指示他的众仆人。”","notes":[]},{"n":7,"t":"“看哪，我必快来！凡遵守这书上预言的有福了。”","notes":[]},{"n":8,"t":"这些事是我－约翰所听见所看见的。当我听见看见时，就俯伏在指示我的天使脚前要拜他。","notes":[]},{"n":9,"t":"他对我说：“千万不可！我与你和你的弟兄众先知，以及那些守这书上的话的人，同是作仆人。你要敬拜神。”","notes":[]},{"n":10,"t":"他又对我说：“不可封了这书上的预言，因为时候近了。","notes":[]},{"n":11,"t":"不义的，让他仍旧不义；污秽的，让他仍旧污秽；为义的，让他仍旧为义；圣洁的，让他仍旧圣洁。”","notes":[]},{"n":12,"t":"“看哪，我必快来！赏罚在我，要照每个人所行的报应他。","notes":[]},{"n":13,"t":"我是阿拉法，我是俄梅戛；我是首先的，我是末后的；我是开始，我是终结。”","notes":[]},{"n":14,"t":"那些洗净自己衣服的有福了！他们可得权柄到生命树那里，也能从门进城。","notes":[]},{"n":15,"t":"城外有犬类、行邪术的、淫乱的、杀人的、拜偶像的，以及所有喜爱和行虚谎的人。","notes":[]},{"n":16,"t":"“我－耶稣差遣我的使者，为了众教会向你们证明这些事。我是大卫的根，是他的后裔；我是明亮的晨星。”","notes":[]},{"n":17,"t":"圣灵和新娘都说：“来！”听见的人也要说：“来！”口渴的人也要来，愿意的人都可以白白取生命的水喝。","notes":[]},{"n":18,"t":"我警告一切听见这书上预言的人：若有人在这预言上加添什么，神必将记在这书上的灾祸加在他身上。","notes":[]},{"n":19,"t":"这书上的预言，若有人删去什么，神必从这书上所记的生命树和圣城删去他的份。","notes":[]},{"n":20,"t":"证明这些事的说：“是的，我必快来！”阿们！主耶稣啊，我愿你来！","notes":[]},{"n":21,"t":"愿主耶稣的恩惠与众圣徒同在。阿们！","notes":["有古卷没有“阿们！”"]}]}}},"traditional":{"GEN":{"1":{"heading":"神的創造","verses":[{"n":1,"t":"起初，神創造天地。","notes":["本節或譯「起初，神創造天地的時候，」"]},{"n":2,"t":"地是空虛混沌，深淵上面一片黑暗；神的靈 運行在水面上。","notes":["「神的靈」或譯「神的風」。","「起初，神創造...水面上」或譯「起初，當神創造天地，地是空虛混沌，深淵的表面黑暗，神的靈運行在水面上的時候」。"]},{"n":3,"t":"神說：「要有光」，就有了光。","notes":[]},{"n":4,"t":"神看光是好的，於是神就把光和暗分開。","notes":[]},{"n":5,"t":"神稱光為「晝」，稱暗為「夜」。有晚上，有早晨，這是第一日。","notes":[]},{"n":6,"t":"神說：「眾水之間要有穹蒼，把水和水分開。」","notes":[]},{"n":7,"t":"神就造了穹蒼，把穹蒼以下的水和穹蒼以上的水分開。事就這樣成了。","notes":[]},{"n":8,"t":"神稱穹蒼為「天」。有晚上，有早晨，這是第二日。","notes":[]},{"n":9,"t":"神說：「天下面的水要聚集在一處，使乾地露出來。」事就這樣成了。","notes":[]},{"n":10,"t":"神稱乾地為「地」，稱聚集在一起的水為「海」。神看為好的。","notes":[]},{"n":11,"t":"神說：「地要長出植物，就是含種子的五穀菜蔬，和會結果子、果子裏有種子的樹，在地上各從其類。」事就這樣成了。","notes":[]},{"n":12,"t":"於是地長出了植物：含種子的五穀菜蔬，各從其類；會結果子、果子裏有種子的樹，各從其類。神看為好的。","notes":[]},{"n":13,"t":"有晚上，有早晨，這是第三日。","notes":[]},{"n":14,"t":"神說：「天上要有光體來分晝夜，讓它們作記號，定季節、日子、年份，","notes":[]},{"n":15,"t":"它們要在天空發光，照在地上。」事就這樣成了。","notes":[]},{"n":16,"t":"於是神造了兩個大光體，大的管晝，小的管夜，又造了星辰。","notes":[]},{"n":17,"t":"神把這些光體擺列在天空，照在地上，","notes":[]},{"n":18,"t":"管理晝夜，分別光暗。神看為好的。","notes":[]},{"n":19,"t":"有晚上，有早晨，這是第四日。","notes":[]},{"n":20,"t":"神說：「水要滋生眾多有生命之物；要有鳥飛在地面以上，天空之中。」","notes":[]},{"n":21,"t":"神就創造了大魚和在水裏滋生的各樣活動的生物，各從其類，以及各樣有翅膀的鳥，各從其類。神看為好的。","notes":[]},{"n":22,"t":"神就賜福給這一切，說：「要繁殖增多，充滿在海的水裏；飛鳥也要在地上增多。」","notes":[]},{"n":23,"t":"有晚上，有早晨，這是第五日。","notes":[]},{"n":24,"t":"神說：「地要生出有生命之物，各從其類，就是牲畜、爬行動物、地上的走獸，各從其類。」事就這樣成了。","notes":[]},{"n":25,"t":"於是神造了地上的走獸，各從其類；牲畜，各從其類；和地上一切的爬行動物，各從其類。神看為好的。","notes":[]},{"n":26,"t":"神說：「我們要照著我們的形像，按著我們的樣式造人，使他們管理海裏的魚、天空的鳥、地上的牲畜和全地，以及地上爬的一切爬行動物。」","notes":[]},{"n":27,"t":"神就照著他的形像創造人，照著神的形像創造他們；他創造了他們，有男有女。","notes":["「他們」：原文是「他」。"]},{"n":28,"t":"神賜福給他們，神對他們說：「要生養眾多，遍滿這地，治理它；要管理海裏的魚、天空的鳥和地上各樣活動的生物。」","notes":[]},{"n":29,"t":"神說：「看哪，我把全地一切含種子的五穀菜蔬和一切會結果子、果子裏有種子的樹，都賜給你們；這些都可作食物。","notes":[]},{"n":30,"t":"至於地上一切的走獸、天空一切的飛鳥，並一切在地上爬行的，有生命的動物，我把綠色植物賜給牠們作食物。」事就這樣成了。","notes":[]},{"n":31,"t":"神看一切所造的，看哪，都非常好。有晚上，有早晨，這是第六日。","notes":[]}]},"2":{"heading":"創造的另一記載","verses":[{"n":1,"t":"天和地，以及萬象都完成了。","notes":[]},{"n":2,"t":"到第七日，神已經完成了造物之工，就在第七日安息了，歇了他所做一切的工。","notes":[]},{"n":3,"t":"神賜福給第七日，將它分別為聖，因為在這日，神安息了，歇了他所做一切創造的工。","notes":[]},{"n":4,"t":"這就是天地創造的來歷。在耶和華神造地和天的時候，","notes":[]},{"n":5,"t":"地上還沒有田野的草木，田間的菜蔬還沒有長出來，因為耶和華神還沒有降雨在地上，也沒有人耕種土地。","notes":[]},{"n":6,"t":"但是，有霧氣從地上騰，滋潤整個土地的表面。","notes":[]},{"n":7,"t":"耶和華神用地上的塵土造人，將生命之氣吹進他的鼻孔，這人就成了有靈的活人。","notes":["「有靈的活人」或譯「有生命的人」；參林前15．45。"]},{"n":8,"t":"耶和華神在東方的伊甸栽了一個園子，把所造的人安置在那裏。","notes":[]},{"n":9,"t":"耶和華神使各樣的樹從土地裏長出來，可以悅人的眼目，好作食物。園子當中有生命樹和知善惡的樹 。","notes":["「知善惡的樹」或譯「賜一切知識的樹」；下同。"]},{"n":10,"t":"有一條河從伊甸流出來，滋潤那園子，從那裏分成四個源頭：","notes":[]},{"n":11,"t":"第一條名叫比遜，它環繞哈腓拉全地，在那裏有金子。","notes":[]},{"n":12,"t":"那地的金子很好，在那裏也有珍珠和紅瑪瑙。","notes":["「珍珠」也可能指一種可作香料的珍貴樹脂；參民11．7。"]},{"n":13,"t":"第二條河名叫基訓，它環繞古實全地。","notes":[]},{"n":14,"t":"第三條河名叫底格里斯，它流到亞述的東邊。第四條河就是幼發拉底。","notes":[]},{"n":15,"t":"耶和華神把那人安置在伊甸園，讓他耕耘看管。","notes":[]},{"n":16,"t":"耶和華神吩咐那人說：「園中各樣樹上所出的，你可以隨意吃，","notes":[]},{"n":17,"t":"只是知善惡的樹所出的，你不可吃，因為你吃它的日子必定死！」","notes":[]},{"n":18,"t":"耶和華神說：「那人單獨一個不好，我要為他造一個配偶幫助他。」","notes":[]},{"n":19,"t":"耶和華神用泥土造了野地各樣的走獸和天空各樣的飛鳥，都帶到那人面前，看他叫甚麼。那人怎樣叫各樣的動物，那就是牠的名字。","notes":[]},{"n":20,"t":"那人就給一切牲畜、天空的飛鳥和野地各樣的走獸都起了名。只是亞當沒有找到配偶幫助他。","notes":["「亞當」或譯「那人」。"]},{"n":21,"t":"耶和華神使他沉睡，他就睡了；於是取下他的一根肋骨，又在原處把肉合起來。","notes":[]},{"n":22,"t":"耶和華神就用那人身上所取的肋骨造了一個女人，帶她到那人面前。","notes":[]},{"n":23,"t":"那人說：「這是我骨中的骨，肉中的肉，可以稱她為女人，因為她是從男人身上取出來的。」","notes":[]},{"n":24,"t":"因此，人要離開父母，與妻子結合，二人成為一體。","notes":[]},{"n":25,"t":"當時夫妻二人赤身露體，並不覺得羞恥。","notes":[]}]},"3":{"heading":"人違背命令","verses":[{"n":1,"t":"耶和華神所造的，惟有蛇比田野一切的走獸更狡猾。蛇對女人說：「神豈是真說，你們不可吃園中任何樹上所出的嗎？」","notes":[]},{"n":2,"t":"女人對蛇說：「園中樹上的果子，我們都可以吃；","notes":[]},{"n":3,"t":"只是園子中間那棵樹的果子，神曾說：『你們不可吃，也不可摸，免得你們死。』」","notes":[]},{"n":4,"t":"蛇對女人說：「你們不一定死；","notes":[]},{"n":5,"t":"因為神知道，你們吃的日子眼睛就開了，你們就像神一樣知道善惡。」","notes":[]},{"n":6,"t":"於是女人見那棵樹好作食物，又悅人的眼目，那樹令人喜愛，能使人有智慧，她就摘下果子吃了，又給了與她一起的丈夫，他也吃了。","notes":[]},{"n":7,"t":"他們二人的眼睛就開了，知道自己赤身露體，就編織無花果樹的葉子，為自己做成裙子。","notes":[]},{"n":8,"t":"天起了涼風，那人和他妻子聽見耶和華神在園中來回行走的聲音，就藏在園裏的樹木中，躲避耶和華神的面。","notes":[]},{"n":9,"t":"耶和華神呼喚那人，對他說：「你在哪裏？」","notes":[]},{"n":10,"t":"他說：「我在園中聽見你的聲音，我就害怕；因為我赤身露體，我就藏了起來。」","notes":[]},{"n":11,"t":"耶和華神說：「誰告訴你，你是赤身露體呢？莫非你吃了那樹上所出的，就是我吩咐你不可吃的嗎？」","notes":[]},{"n":12,"t":"那人說：「你賜給我、與我一起的女人，是她把那樹上所出的給我，我就吃了。」","notes":[]},{"n":13,"t":"耶和華神對女人說：「你怎麼會做這種事呢？」女人說：「那蛇引誘我，我就吃了。」","notes":[]},{"n":14,"t":"耶和華神對蛇說：「你既做了這事，就必受詛咒，比一切的牲畜和野獸更重。你必用肚子行走，終生吃土。","notes":[],"heads":["神的宣判"]},{"n":15,"t":"我要使你和女人彼此為仇，你的後裔和女人的後裔也彼此為仇。他要傷你的頭，你要傷他的腳跟。 」","notes":[]},{"n":16,"t":"又對女人說：「我必多多加增你懷胎的痛苦，你生兒女時必多受痛苦。你必戀慕你丈夫，他必管轄你。」","notes":[]},{"n":17,"t":"又對亞當說：「你既聽從你妻子的話，吃了那樹上所出的，就是我吩咐你不可吃的，土地必因你的緣故受詛咒；你必終生勞苦才能從土地得吃的。","notes":[]},{"n":18,"t":"土地必給你長出荊棘和蒺藜來；你也要吃田間的五穀菜蔬。","notes":[]},{"n":19,"t":"你必汗流滿面才有食物可吃，直到你歸了土地，因為你是從土地而出的。你本是塵土，仍要歸回塵土。」","notes":[]},{"n":20,"t":"那人給他妻子起名叫夏娃，因為她是眾生之母 。","notes":["「眾生之母」或譯「人類的母親」。"]},{"n":21,"t":"耶和華神用獸皮做衣服給亞當和他的妻子穿。","notes":[]},{"n":22,"t":"耶和華神說：「看哪，那人已經像我們中間的一個，知道善惡，現在恐怕他又伸手摘生命樹所出的來吃，就永遠活著。」","notes":[],"heads":["亞當和夏娃被趕出伊甸園"]},{"n":23,"t":"耶和華神就驅逐他出伊甸園，使他耕種土地，他原是從土地裏被取出來的。","notes":[]},{"n":24,"t":"耶和華神把那人趕出去，就在伊甸園東邊安設基路伯和發出火焰轉動的劍，把守生命樹的道路。","notes":[]}]},"4":{"heading":"該隱和亞伯","verses":[{"n":1,"t":"那人和他妻子夏娃同房，夏娃就懷孕，生了該隱 ，她說：「我靠耶和華得了一個男的。」","notes":["「該隱」意思是「得」。"]},{"n":2,"t":"她又生了該隱的弟弟亞伯。亞伯是牧羊的；該隱是耕地的。","notes":[]},{"n":3,"t":"過了一些日子，該隱拿地裏的出產為供物獻給耶和華；","notes":[]},{"n":4,"t":"亞伯也把他羊群中頭生的和羊的脂肪獻上。耶和華看中了亞伯和他的供物，","notes":[]},{"n":5,"t":"卻看不中該隱和他的供物。該隱就非常生氣，沉下臉來。","notes":[]},{"n":6,"t":"耶和華對該隱說：「你為甚麼生氣呢？你為甚麼沉下臉來呢？","notes":[]},{"n":7,"t":"你若做得對，豈不仰起頭來嗎？你若做得不對，罪就伏在門前。它想要控制你，你卻要制伏它。」","notes":[]},{"n":8,"t":"該隱與他弟弟亞伯說話 。 二人正在田間時，該隱起來攻擊他弟弟亞伯，把他殺了。","notes":["「該隱...說話。」撒瑪利亞五經、七十士譯本和其他古譯本是「該隱對他弟弟亞伯說：『讓我們到田間去吧！』」"]},{"n":9,"t":"耶和華對該隱說：「你弟弟亞伯在哪裏？」他說：「我不知道！我豈是看守我弟弟的嗎？」","notes":[]},{"n":10,"t":"耶和華說：「你做了甚麼事呢？你弟弟血的聲音從地裏向我哀號。","notes":[]},{"n":11,"t":"現在你必從這地受詛咒，這地開了口，從你手裏接受你弟弟的血。","notes":[]},{"n":12,"t":"你耕種土地，它不再給你效力；你必流離飄蕩在地上。」","notes":[]},{"n":13,"t":"該隱對耶和華說：「我的懲罰太重，過於我所能承當的。","notes":[]},{"n":14,"t":"看哪，今日你趕我離開這塊土地，不能見你的面；我必流離飄蕩在地上，凡遇見我的必殺我。」","notes":[]},{"n":15,"t":"耶和華對他說：「既然如此 ，凡殺該隱的，必遭報七倍。」耶和華就給該隱立一個記號，免得人遇見他就殺他。","notes":[]},{"n":16,"t":"於是該隱離開了耶和華的面，去住在伊甸東邊挪得之地。","notes":["「挪得」 意思是「流蕩」。"]},{"n":17,"t":"該隱與妻子同房，她就懷孕，生了以諾。該隱建造一座城，就照他兒子的名字稱那城為以諾。","notes":[],"heads":["該隱的後代"]},{"n":18,"t":"以諾生以拿，以拿生米戶雅利，米戶雅利生瑪土撒利，瑪土撒利生拉麥。","notes":[]},{"n":19,"t":"拉麥娶了兩個妻子：一個名叫亞大，一個名叫洗拉。","notes":[]},{"n":20,"t":"亞大生雅八；雅八是住帳棚、牧養牲畜之人的祖師。","notes":[]},{"n":21,"t":"雅八的兄弟名叫猶八；他是所有彈琴吹簫之人的祖師。","notes":[]},{"n":22,"t":"洗拉又生了土八‧該隱；他是打造各樣銅器鐵器的工匠。土八‧該隱的妹妹是拿瑪。","notes":[]},{"n":23,"t":"拉麥對他兩個妻子說：亞大、洗拉啊，聽我的聲音；拉麥的妻子啊，側耳聽我的言語：大人傷我，我把他殺了；小孩損我，我把他害了。","notes":["「大人...害了」或譯「我殺大人卻傷自己，我害小孩卻損本身」。"]},{"n":24,"t":"若殺該隱，遭報七倍，殺拉麥的，必遭報七十七倍。","notes":[]},{"n":25,"t":"亞當又與妻子同房，她就生了一個兒子，給他起名叫塞特，說：「神給我立了另一個子嗣代替亞伯，因為該隱殺了他。」","notes":[],"heads":["塞特和以挪士"]},{"n":26,"t":"塞特也生了一個兒子，起名叫以挪士。那時候，人開始求告耶和華的名。","notes":[]}]},"5":{"heading":"亞當的後代","verses":[{"n":1,"t":"這是亞當後代的家譜。當神造人的日子，他照著自己的樣式造人。","notes":[]},{"n":2,"t":"他造男造女。在他們被造的日子，神賜福給他們，稱他們為人。","notes":[]},{"n":3,"t":"亞當活到一百三十歲，生了一個兒子，形像樣式和自己相似，就給他起名叫塞特。","notes":[]},{"n":4,"t":"亞當生塞特之後，又活了八百年，並且生兒育女。","notes":[]},{"n":5,"t":"亞當共活了九百三十年，就死了。","notes":[]},{"n":6,"t":"塞特活到一百零五歲，生了以挪士。","notes":[]},{"n":7,"t":"塞特生以挪士之後，又活了八百零七年，並且生兒育女。","notes":[]},{"n":8,"t":"塞特共活了九百一十二年，就死了。","notes":[]},{"n":9,"t":"以挪士活到九十歲，生了該南。","notes":[]},{"n":10,"t":"以挪士生該南之後，又活了八百一十五年，並且生兒育女。","notes":[]},{"n":11,"t":"以挪士共活了九百零五年，就死了。","notes":[]},{"n":12,"t":"該南活到七十歲，生了瑪勒列。","notes":[]},{"n":13,"t":"該南生瑪勒列之後，又活了八百四十年，並且生兒育女。","notes":[]},{"n":14,"t":"該南共活了九百一十年，就死了。","notes":[]},{"n":15,"t":"瑪勒列活到六十五歲，生了雅列。","notes":[]},{"n":16,"t":"瑪勒列生雅列之後，又活了八百三十年，並且生兒育女。","notes":[]},{"n":17,"t":"瑪勒列共活了八百九十五年，就死了。","notes":[]},{"n":18,"t":"雅列活到一百六十二歲，生了以諾。","notes":[]},{"n":19,"t":"雅列生以諾之後，又活了八百年，並且生兒育女。","notes":[]},{"n":20,"t":"雅列共活了九百六十二年，就死了。","notes":[]},{"n":21,"t":"以諾活到六十五歲，生了瑪土撒拉。","notes":[]},{"n":22,"t":"以諾生瑪土撒拉之後，與神同行三百年，並且生兒育女。","notes":[]},{"n":23,"t":"以諾共活了三百六十五年。","notes":[]},{"n":24,"t":"以諾與神同行，神把他接去，他就不在了。","notes":[]},{"n":25,"t":"瑪土撒拉活到一百八十七歲，生了拉麥。","notes":[]},{"n":26,"t":"瑪土撒拉生拉麥之後，又活了七百八十二年，並且生兒育女。","notes":[]},{"n":27,"t":"瑪土撒拉共活了九百六十九年，就死了。","notes":[]},{"n":28,"t":"拉麥活到一百八十二歲，生了一個兒子，","notes":[]},{"n":29,"t":"給他起名叫挪亞，說：「在耶和華所詛咒的地上，這個兒子必使我們從工作和手中的勞苦得到安慰。」","notes":[]},{"n":30,"t":"拉麥生挪亞之後，又活了五百九十五年，並且生兒育女。","notes":[]},{"n":31,"t":"拉麥共活了七百七十七年，就死了。","notes":[]},{"n":32,"t":"挪亞活到五百歲，生了閃、含和雅弗。","notes":[]}]},"6":{"heading":"人類的邪惡","verses":[{"n":1,"t":"當人開始在地面上增多、又生女兒的時候，","notes":[]},{"n":2,"t":"神的兒子們看見人的女子美貌，就隨意挑選，娶來為妻。","notes":[]},{"n":3,"t":"耶和華說：「人既屬乎血氣，我的靈就不永遠住在他裏面；然而他的年歲還可到一百二十年。」","notes":[]},{"n":4,"t":"那時候有巨人在地上，後來也有；神的兒子們和人的女子們交合，生了孩子。那些人就是古代的勇士，有名的人物。","notes":[]},{"n":5,"t":"耶和華見人在地上罪大惡極，終日心裏所想的盡都是惡事，","notes":[]},{"n":6,"t":"耶和華就因造人在地上感到遺憾，心中憂傷。","notes":[]},{"n":7,"t":"耶和華說：「我要把所造的人和走獸，爬行動物，以及天空的飛鳥，都從地面上除滅，因為我造了他們感到遺憾。」","notes":[]},{"n":8,"t":"只有挪亞在耶和華眼前蒙恩。","notes":[]},{"n":9,"t":"這是挪亞的後代。挪亞是個義人，在他的世代中是個完全人。挪亞與神同行。","notes":[],"heads":["挪亞造方舟"]},{"n":10,"t":"挪亞生了三個兒子，就是閃、含和雅弗。","notes":[]},{"n":11,"t":"這地在神面前敗壞了，地上充滿了暴力。","notes":[]},{"n":12,"t":"神觀看這地，看哪，它敗壞了，因為凡血肉之軀在地上的行為都敗壞了。","notes":[]},{"n":13,"t":"神對挪亞說：「在我面前，凡血肉之軀的結局已經臨到，因著他們，地上充滿了暴力。看哪，我要把他們和這地一起毀滅。","notes":[]},{"n":14,"t":"你要為自己用歌斐木造一艘方舟，並在方舟內造房間，內外都要抹上瀝青。","notes":[]},{"n":15,"t":"方舟的造法是這樣：要長三百肘，寬五十肘，高三十肘。","notes":[]},{"n":16,"t":"方舟上面要造天窗，向上一肘。方舟的門要開在旁邊。方舟要分上、中、下三層。","notes":[]},{"n":17,"t":"看哪，我要使洪水氾濫在地上，毀滅天下凡有生命氣息的血肉之軀，地上的一切都要滅亡。","notes":[]},{"n":18,"t":"但我要與你立約；你同你的兒子、妻子和媳婦都要進入方舟。","notes":[]},{"n":19,"t":"凡有血肉的動物，每樣一對，一公一母，你要帶進方舟，好跟你一起保全生命。","notes":[]},{"n":20,"t":"飛鳥各從其類，牲畜各從其類，地上的爬行動物各從其類，每樣一對，都要到你那裏，好保全生命。","notes":[]},{"n":21,"t":"你要拿各樣可吃的食物，儲存在你那裏，作你和牠們的糧食。」","notes":[]},{"n":22,"t":"挪亞就去做了；凡神吩咐他的，他都照樣去做。","notes":[]}]},"7":{"heading":"洪水","verses":[{"n":1,"t":"耶和華對挪亞說：「你和你的全家都要進入方舟，因為在這世代中，我看你在我面前是個義人。","notes":[]},{"n":2,"t":"凡潔淨的牲畜，你要各取七公七母；不潔淨的牲畜，你要各取一公一母；","notes":[]},{"n":3,"t":"天空的飛鳥也要各取七公七母，為了要留種，活在全地面上。","notes":[]},{"n":4,"t":"因為再過七天，我要降雨在地上四十晝夜，把我所造的一切生物從地面上除滅。」","notes":[]},{"n":5,"t":"挪亞就遵照耶和華吩咐他的去做。","notes":[]},{"n":6,"t":"當洪水在地上氾濫的時候，挪亞已六百歲。","notes":["「洪水」：原文是「洪水的水」。"]},{"n":7,"t":"挪亞同他的兒子、妻子和媳婦都進入方舟，躲避洪水。","notes":[]},{"n":8,"t":"潔淨的牲畜和不潔淨的牲畜，飛鳥及所有爬行在土地上的，","notes":[]},{"n":9,"t":"都一對一對，有公有母，到挪亞那裏，進入方舟，正如神所吩咐挪亞的。","notes":[]},{"n":10,"t":"過了七天，洪水氾濫在地上。","notes":[]},{"n":11,"t":"挪亞六百歲那一年的二月十七日，就在那一天，大深淵的泉源都裂開，天上的窗戶也敞開了，","notes":[]},{"n":12,"t":"四十晝夜有大雨降在地上。","notes":[]},{"n":13,"t":"正在那日，挪亞和他的兒子閃、含、雅弗，以及挪亞的妻子和三個媳婦，都一同進入方舟。","notes":[]},{"n":14,"t":"他們和一切走獸，各從其類；一切牲畜，各從其類；地上爬的一切爬行動物，各從其類；一切的鳥，就是一切有翅膀的飛禽，各從其類；","notes":[]},{"n":15,"t":"凡有生命氣息的血肉之軀，都一對一對到挪亞那裏，進入方舟。","notes":[]},{"n":16,"t":"凡有血肉的，都一公一母進入方舟，正如神所吩咐挪亞的。耶和華就把他關在方舟裏。","notes":[]},{"n":17,"t":"洪水在地上氾濫四十天，水往上漲，使方舟浮起，方舟就從地上漂起來。","notes":[]},{"n":18,"t":"水勢洶湧，在地上大大上漲，方舟在水面上漂蕩。","notes":[]},{"n":19,"t":"水勢在地上極其浩大，普天下所有的高山都淹沒了。","notes":[]},{"n":20,"t":"水勢洶湧，比山高出十五肘 ，山嶺都淹沒了。","notes":[]},{"n":21,"t":"凡有血肉在地上行動的，就是飛鳥、牲畜、走獸和地上成群的群聚動物，以及所有的人，都死了。","notes":[]},{"n":22,"t":"在乾地上凡鼻孔裏有生命氣息的都死了。","notes":[]},{"n":23,"t":"耶和華除滅了地面上各類的生物，包括人和牲畜、爬行動物，以及天空的飛鳥；他們就都從地上除滅了，只剩下挪亞和那些與他同在方舟裏的。","notes":[]},{"n":24,"t":"水勢洶湧，在地上共一百五十天。","notes":[]}]},"8":{"heading":"洪水消退","verses":[{"n":1,"t":"神記念挪亞和挪亞方舟裏的一切走獸牲畜。神使風吹地，水勢漸落。","notes":[]},{"n":2,"t":"深淵的泉源和天上的窗戶都關閉了，雨不再從天降下。","notes":[]},{"n":3,"t":"水從地上逐漸消退。過了一百五十天，水就退了。","notes":[]},{"n":4,"t":"七月十七日，方舟停在亞拉臘山上。","notes":[]},{"n":5,"t":"水繼續退去，直到十月；十月初一，山頂都露出來了。","notes":[]},{"n":6,"t":"過了四十天，挪亞打開他所造的方舟的窗戶，","notes":[]},{"n":7,"t":"放出一隻烏鴉。那烏鴉飛來飛去，直到地上的水都乾了。","notes":[]},{"n":8,"t":"他又從他那裏放出一隻鴿子，要看水從地面上退了沒有。","notes":[]},{"n":9,"t":"但全地面都是水，鴿子找不到落腳之地，就回到方舟挪亞那裏。挪亞伸手接了鴿子，把牠帶進方舟。","notes":[]},{"n":10,"t":"挪亞又另外等了七天，再把鴿子從方舟放出去。","notes":[]},{"n":11,"t":"到了晚上，鴿子回到他那裏，看哪，嘴裏有一片剛啄下來的橄欖葉，挪亞就知道水已經從地上退了。","notes":[]},{"n":12,"t":"他又另外等了七天，再放出鴿子，這次鴿子不再回到他那裏了。","notes":[]},{"n":13,"t":"當挪亞六百零一歲，正月初一的時候，地上的水都乾了。挪亞打開方舟的蓋觀看，看哪，地面乾了。","notes":[]},{"n":14,"t":"到了二月二十七日，地就都乾了。","notes":[]},{"n":15,"t":"神對挪亞說：","notes":[]},{"n":16,"t":"「你同你的妻子、兒子、媳婦都要出方舟。","notes":[]},{"n":17,"t":"凡與你一起有血肉的生物，就是飛鳥、牲畜和地上爬的一切爬行動物，都要帶出來。 牠們要在地上滋生，繁殖增多。」","notes":[]},{"n":18,"t":"於是挪亞同他的兒子、妻子、媳婦都出來了。","notes":[]},{"n":19,"t":"一切走獸、爬行動物和飛鳥，地上所有的動物，各從其類，也都出了方舟。","notes":[]},{"n":20,"t":"挪亞為耶和華築了一座壇，拿各種潔淨的牲畜和各種潔淨的飛鳥，獻在壇上為燔祭。","notes":[],"heads":["挪亞獻祭"]},{"n":21,"t":"耶和華聞了那馨香之氣，耶和華心裏說：「我不再因人的緣故詛咒土地，因為人從幼年就心裏懷著惡念；我也不再照我曾做的毀滅一切生物了。","notes":[]},{"n":22,"t":"地還存在的時候，撒種、收割、寒暑、冬夏、晝夜都永不止息。」","notes":[]}]},"9":{"heading":"神與挪亞立約","verses":[{"n":1,"t":"神賜福給挪亞和他的兒子，對他們說：「你們要生養眾多，遍滿這地。","notes":[]},{"n":2,"t":"地上一切的走獸、天空一切的飛鳥、所有爬行在土地上的和海裏一切的魚都必怕你們，畏懼你們，牠們都要交在你們手裏。","notes":[]},{"n":3,"t":"凡活的動物都可作你們的食物。這一切我都賜給你們，如同綠色的菜蔬一樣。","notes":[]},{"n":4,"t":"只是帶著生命的肉，就是帶著血的，你們不可吃。","notes":[]},{"n":5,"t":"流你們血、害你們命的，我必向他追討；我要向一切走獸追討，向人和向人的弟兄追討人命。","notes":[]},{"n":6,"t":"凡流人血的，他的血也必被人所流，因為神造人，是照自己的形像造的。","notes":[]},{"n":7,"t":"你們要生養眾多，在地上繁衍昌盛。」","notes":[]},{"n":8,"t":"神對挪亞和同他一起的兒子說：","notes":[]},{"n":9,"t":"「看哪，我要與你們和你們後裔立我的約，","notes":[]},{"n":10,"t":"包括和你們一起所有的生物，就是飛鳥、牲畜、地上一切的走獸，凡從方舟裏出來地上一切的生物。","notes":[]},{"n":11,"t":"我與你們立我的約：凡有血肉的，不再被洪水滅絕，也不再有洪水毀壞這地了。」","notes":[]},{"n":12,"t":"神說：「這是我與你們，以及和你們一起的一切生物所立之永約的記號，直到萬代：","notes":[]},{"n":13,"t":"我把彩虹放在雲中，這就是我與地立約的記號了。","notes":[]},{"n":14,"t":"我使雲遮地的時候，會有彩虹出現在雲中，","notes":[]},{"n":15,"t":"我就記念我與你們，以及各樣有血肉的生物所立的約：不再有洪水氾濫去毀滅一切有血肉的了。","notes":[]},{"n":16,"t":"彩虹出現在雲中，我看見了，就要記念神與地上一切有血肉的生物所立的永約。」","notes":[]},{"n":17,"t":"神對挪亞說：「這就是我與地上一切有血肉的立約的記號。」","notes":[]},{"n":18,"t":"挪亞的兒子，從方舟出來的，有閃、含和雅弗。含是迦南的父親。","notes":[],"heads":["挪亞和他的兒子們"]},{"n":19,"t":"這是挪亞的三個兒子，他們的後裔散佈全地。","notes":[]},{"n":20,"t":"挪亞是農夫，是他開始栽葡萄園的。","notes":[]},{"n":21,"t":"他喝了一些酒就醉了，在他的帳棚裏赤著身子。","notes":[]},{"n":22,"t":"迦南的父親含看見他父親赤身，就到外面告訴他的兩個兄弟。","notes":[]},{"n":23,"t":"於是閃和雅弗拿了外衣搭在二人肩上，倒退著進去，遮蓋父親的赤身；他們背著臉，看不見父親的赤身。","notes":[]},{"n":24,"t":"挪亞酒醒以後，知道小兒子向他所做的事，","notes":[]},{"n":25,"t":"就說：「迦南當受詛咒，必給他弟兄作奴僕的奴僕。」","notes":[]},{"n":26,"t":"又說：「耶和華—閃的神是應當稱頌的！願迦南作閃的奴僕。","notes":[]},{"n":27,"t":"願神使雅弗擴張，願他住在閃的帳棚裏；願迦南作他的奴僕。」","notes":[]},{"n":28,"t":"洪水以後，挪亞又活了三百五十年。","notes":[]},{"n":29,"t":"挪亞共活了九百五十年，就死了。","notes":[]}]},"10":{"heading":"閃、含、雅弗的後代","verses":[{"n":1,"t":"這是挪亞的兒子閃、含、雅弗的後代。洪水以後，他們都生了兒子。","notes":[]},{"n":2,"t":"雅弗的兒子是歌篾、瑪各、瑪代、雅完、土巴、米設、提拉。","notes":[]},{"n":3,"t":"歌篾的兒子是亞實基拿、利法、陀迦瑪。","notes":[]},{"n":4,"t":"雅完的兒子是以利沙、他施、基提、羅單人。","notes":["「羅單人」是根據一些古卷、撒瑪利亞五經和七十士譯本，原文是「多單人」；參代上1．7。"]},{"n":5,"t":"從這些人中有沿海國家的人散居各處，有自己的土地，各有各的語言、宗族、國家。","notes":[]},{"n":6,"t":"含的兒子是古實、麥西、弗、迦南。","notes":[]},{"n":7,"t":"古實的兒子是西巴、哈腓拉、撒弗他、拉瑪、撒弗提迦。拉瑪的兒子是示巴、底但。","notes":[]},{"n":8,"t":"古實又生寧錄，他是地上第一個勇士。","notes":[]},{"n":9,"t":"他在耶和華面前是個英勇的獵人，所以有話說：「像寧錄在耶和華面前是個英勇的獵人。」","notes":[]},{"n":10,"t":"他王國的開始是在巴別、以力、亞甲、甲尼，都在示拿地。","notes":[]},{"n":11,"t":"他從那地出來往亞述去，建造了尼尼微、利河伯、迦拉，","notes":[]},{"n":12,"t":"以及尼尼微和迦拉之間的利鮮，那是座大城。","notes":[]},{"n":13,"t":"麥西生路低人、亞拿米人、利哈比人、拿弗土希人、","notes":[]},{"n":14,"t":"帕斯魯細人、迦斯路希人、迦斐託人；非利士人是從迦斐託人出來的。","notes":["「迦斐託人」：原文是「迦斯路希人」。"]},{"n":15,"t":"迦南生了長子西頓，又生赫","notes":[]},{"n":16,"t":"和耶布斯人、亞摩利人、革迦撒人、","notes":[]},{"n":17,"t":"希未人、亞基人、西尼人、","notes":[]},{"n":18,"t":"亞瓦底人、洗瑪利人、哈馬人，後來迦南的家族散開了。","notes":[]},{"n":19,"t":"迦南的疆界是從西頓到基拉耳，直到迦薩，又到所多瑪、蛾摩拉、押瑪、洗扁，直到拉沙。","notes":[]},{"n":20,"t":"這就是含的後裔，各有自己的宗族、語言、土地和國家。","notes":[]},{"n":21,"t":"閃也生了兒子，他是雅弗的哥哥，是希伯人的祖先。","notes":["「雅弗的哥哥」：七十士譯本是「雅弗的弟弟」。"]},{"n":22,"t":"閃的兒子是以攔、亞述、亞法撒、路德、亞蘭。","notes":[]},{"n":23,"t":"亞蘭的兒子是烏斯、戶勒、基帖、瑪施。","notes":[]},{"n":24,"t":"亞法撒生沙拉，沙拉生希伯。","notes":[]},{"n":25,"t":"希伯生了兩個兒子，一個名叫法勒 ，因為那時人分地居住；法勒的兄弟名叫約坍。","notes":["「法勒」意思是「分」。"]},{"n":26,"t":"約坍生亞摩答、沙列、哈薩瑪非、耶拉、","notes":[]},{"n":27,"t":"哈多蘭、烏薩、德拉、","notes":[]},{"n":28,"t":"俄巴路、亞比瑪利、示巴、","notes":[]},{"n":29,"t":"阿斐、哈腓拉、約巴，這些都是約坍的兒子。","notes":[]},{"n":30,"t":"他們所住的地方是從米沙直到西發，到東邊的山。","notes":[]},{"n":31,"t":"這就是閃的後裔，各有自己的宗族、語言、土地和國家。","notes":[]},{"n":32,"t":"這些是挪亞兒子的宗族，按著他們的後代立國。洪水以後，邦國就從他們散佈在地上。","notes":[]}]},"11":{"heading":"巴別塔","verses":[{"n":1,"t":"那時，全地只有一種語言，都說一樣的話。","notes":[]},{"n":2,"t":"他們向東遷移的時候，在示拿地找到一片平原，就住在那裏。","notes":[]},{"n":3,"t":"他們彼此商量說：「來，讓我們來做磚，把磚燒透了。」他們就拿磚當石頭，又拿柏油當泥漿。","notes":[]},{"n":4,"t":"他們說：「來，讓我們建造一座城和一座塔，塔頂通天。我們要為自己立名，免得我們分散在全地面上。」","notes":[]},{"n":5,"t":"耶和華降臨，要看世人所建造的城和塔。","notes":[]},{"n":6,"t":"耶和華說：「看哪，他們成了同一個民族，都有一樣的語言。這只是他們開始做的事，現在他們想要做的任何事，就沒有甚麼可攔阻他們了。","notes":[]},{"n":7,"t":"來，我們下去，在那裏變亂他們的語言，使他們彼此語言不通。」","notes":[]},{"n":8,"t":"於是耶和華使他們從那裏分散在全地面上；他們就停止建造那城了。","notes":[]},{"n":9,"t":"因為耶和華在那裏變亂了全地的語言，把人從那裏分散在全地面上，所以那城名叫巴別 。","notes":["「巴別」意思是「變亂」。"]},{"n":10,"t":"這是閃的後代。洪水以後二年，閃一百歲生了亞法撒。","notes":[],"heads":["閃的後代"]},{"n":11,"t":"閃生亞法撒之後又活了五百年，並且生兒育女。","notes":[]},{"n":12,"t":"亞法撒活到三十五歲，生了沙拉。","notes":[]},{"n":13,"t":"亞法撒生沙拉之後又活了四百零三年，並且生兒育女。","notes":[]},{"n":14,"t":"沙拉活到三十歲，生了希伯。","notes":[]},{"n":15,"t":"沙拉生希伯之後又活了四百零三年，並且生兒育女。","notes":[]},{"n":16,"t":"希伯活到三十四歲，生了法勒。","notes":[]},{"n":17,"t":"希伯生法勒之後又活了四百三十年，並且生兒育女。","notes":[]},{"n":18,"t":"法勒活到三十歲，生了拉吳。","notes":[]},{"n":19,"t":"法勒生拉吳之後又活了二百零九年，並且生兒育女。","notes":[]},{"n":20,"t":"拉吳活到三十二歲，生了西鹿。","notes":[]},{"n":21,"t":"拉吳生西鹿之後又活了二百零七年，並且生兒育女。","notes":[]},{"n":22,"t":"西鹿活到三十歲，生了拿鶴。","notes":[]},{"n":23,"t":"西鹿生拿鶴之後又活了二百年，並且生兒育女。","notes":[]},{"n":24,"t":"拿鶴活到二十九歲，生了他拉。","notes":[]},{"n":25,"t":"拿鶴生他拉之後又活了一百一十九年，並且生兒育女。","notes":[]},{"n":26,"t":"他拉活到七十歲，生了亞伯蘭、拿鶴和哈蘭。","notes":[]},{"n":27,"t":"這是他拉的後代。他拉生亞伯蘭、拿鶴和哈蘭；哈蘭生羅得。","notes":[],"heads":["他拉的後代"]},{"n":28,"t":"哈蘭死在他父親他拉的面前，死在他的出生地迦勒底的吾珥。","notes":[]},{"n":29,"t":"亞伯蘭、拿鶴各娶了妻。亞伯蘭的妻子名叫撒萊，拿鶴的妻子名叫密迦，是哈蘭的女兒。哈蘭是密迦和亦迦的父親。","notes":[]},{"n":30,"t":"撒萊不生育，沒有孩子。","notes":[]},{"n":31,"t":"他拉帶著他兒子亞伯蘭和他孫子，哈蘭的兒子羅得，以及他的媳婦，亞伯蘭的妻子撒萊，一同出了迦勒底的吾珥，要往迦南地去；他們來到哈蘭，就住在那裏。","notes":[]},{"n":32,"t":"他拉共活了二百零五年，就死在哈蘭。","notes":[]}]},"12":{"heading":"神呼召亞伯蘭","verses":[{"n":1,"t":"耶和華對亞伯蘭說：「你要離開本地、本族、父家，往我所要指示你的地去。","notes":[]},{"n":2,"t":"我必使你成為大國，我必賜福給你，使你的名為大；你要使別人得福。","notes":["「你要使別人得福」：原文是「你要成為福氣」。"]},{"n":3,"t":"為你祝福的，我必賜福給他；詛咒你的，我必詛咒他。地上的萬族都必因你得福。」","notes":[]},{"n":4,"t":"亞伯蘭就遵照耶和華的吩咐去了；羅得也和他同去。亞伯蘭離開哈蘭的時候年七十五歲。","notes":[]},{"n":5,"t":"亞伯蘭帶著他妻子撒萊和姪兒羅得，以及他們在哈蘭積蓄的財物、獲得的人口，往迦南地去。他們就來到了迦南地。","notes":[]},{"n":6,"t":"亞伯蘭經過那地，直到示劍地方，摩利橡樹那裏；當時迦南人住在那地。","notes":[]},{"n":7,"t":"耶和華向亞伯蘭顯現，說：「我要把這地賜給你的後裔。」亞伯蘭就在那裏為向他顯現的耶和華築了一座壇。","notes":[]},{"n":8,"t":"從那裏他又遷到伯特利東邊的山，支搭帳棚；西邊是伯特利，東邊是艾。他在那裏又為耶和華築了一座壇，求告耶和華的名。","notes":[]},{"n":9,"t":"後來亞伯蘭漸漸遷往尼革夫去。","notes":["「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」；本卷書下同。"]},{"n":10,"t":"那地遭遇饑荒。亞伯蘭因那地的饑荒嚴重，就下到埃及，要在那裏寄居。","notes":[],"heads":["亞伯蘭到埃及"]},{"n":11,"t":"將近埃及，他對妻子撒萊說：「看哪，我知道你是美貌的女人。","notes":[]},{"n":12,"t":"埃及人看見你會說：『這是他的妻子』，他們就會殺我，卻讓你活著。","notes":[]},{"n":13,"t":"所以，請你說你是我的妹妹，使我可以因你得平安，我的性命也因你存活。」","notes":[]},{"n":14,"t":"亞伯蘭到達埃及時，埃及人看見那女人極其美貌。","notes":[]},{"n":15,"t":"法老的臣僕看見了她，就在法老面前稱讚她。那女人就被帶進法老的宮中。","notes":[]},{"n":16,"t":"法老就因她厚待亞伯蘭，給了亞伯蘭許多牛、羊、公驢、奴僕、婢女、母驢、駱駝。","notes":[]},{"n":17,"t":"耶和華因亞伯蘭妻子撒萊的緣故，降大災擊打法老和他的全家。","notes":[]},{"n":18,"t":"法老召了亞伯蘭來，說：「你向我做的是甚麼事呢？為甚麼沒有告訴我她是你的妻子？","notes":[]},{"n":19,"t":"為甚麼說『她是我的妹妹』，以致我把她接來要作我的妻子呢？現在 ，看哪，你的妻子在這裏，帶她走吧！」","notes":[]},{"n":20,"t":"於是法老吩咐人把亞伯蘭和他妻子，以及他一切所有的都送走了。","notes":[]}]},"13":{"heading":"亞伯蘭跟羅得分手","verses":[{"n":1,"t":"亞伯蘭帶著他的妻子與羅得，以及一切所有的，從埃及上尼革夫去。","notes":[]},{"n":2,"t":"亞伯蘭的牲畜和金銀極多。","notes":[]},{"n":3,"t":"他從尼革夫漸漸往伯特利去，到了伯特利和艾的中間，當初他支搭帳棚的地方，","notes":[]},{"n":4,"t":"也是他起先築壇的地方。亞伯蘭在那裏求告耶和華的名。","notes":[]},{"n":5,"t":"與亞伯蘭同行的羅得也有牛群、羊群、帳棚。","notes":[]},{"n":6,"t":"那地容不下他們住在一起；因為他們的財物非常多，使他們不能同住一起。","notes":[]},{"n":7,"t":"當時，迦南人與比利洗人在那地居住。亞伯蘭的牧人和羅得的牧人之間起了爭端。","notes":[]},{"n":8,"t":"亞伯蘭就對羅得說：「你我不可以相爭，你的牧人和我的牧人也不可以相爭，因為我們是一家人。","notes":[]},{"n":9,"t":"遍地不都在你眼前嗎？請你離開我吧！你向左，我就向右；你向右，我就向左。」","notes":[]},{"n":10,"t":"羅得舉目，看見約旦河整個平原，直到瑣珥，都是水源充足之地。在耶和華未毀滅所多瑪、蛾摩拉以前，那地好像耶和華的園子，又像埃及地。","notes":[]},{"n":11,"t":"於是羅得選擇了約旦河整個平原。羅得往東遷移，他們就彼此分開了。","notes":[]},{"n":12,"t":"亞伯蘭住在迦南地；羅得住在平原的城鎮，他漸漸遷移帳棚，直到所多瑪。","notes":[]},{"n":13,"t":"所多瑪人在耶和華面前罪大惡極。","notes":[]},{"n":14,"t":"羅得離開亞伯蘭以後，耶和華對亞伯蘭說：「你要從你所在的地方，舉目向東西南北觀看；","notes":[],"heads":["亞伯蘭遷往希伯崙"]},{"n":15,"t":"你所看見一切的地，我都要把它賜給你和你的後裔，直到永遠。","notes":[]},{"n":16,"t":"我要使你的後裔好像地上的塵沙，人若能數地上的塵沙，才能數你的後裔。","notes":[]},{"n":17,"t":"你起來，縱橫走遍這地，因為我必把這地賜給你。」","notes":[]},{"n":18,"t":"亞伯蘭就遷移帳棚，來到希伯崙，幔利的橡樹那裏居住，在那裏為耶和華築了一座壇。","notes":[]}]},"14":{"heading":"亞伯蘭搶救羅得","verses":[{"n":1,"t":"當暗拉非作示拿王，亞略作以拉撒王，基大老瑪作以攔王，提達作戈印王的時候，","notes":[]},{"n":2,"t":"他們攻打所多瑪王比拉、蛾摩拉王比沙、押瑪王示納、洗扁王善以別和比拉王，比拉就是瑣珥。","notes":[]},{"n":3,"t":"這些王都會合在西訂谷，西訂谷就是鹽海。","notes":[]},{"n":4,"t":"他們已經服事基大老瑪十二年，第十三年就背叛了。","notes":[]},{"n":5,"t":"第十四年，基大老瑪和與他結盟的王都來了，在亞特律‧加寧擊敗利乏音人，在哈麥擊敗蘇西人，在沙微‧基列亭擊敗以米人，","notes":[]},{"n":6,"t":"在何利人的西珥山擊敗何利人，一直到靠近曠野的伊勒‧巴蘭。","notes":[]},{"n":7,"t":"他們轉回，來到安‧密巴，就是加低斯，擊敗了亞瑪力全地的人，以及住在哈洗遜‧他瑪的亞摩利人。","notes":[]},{"n":8,"t":"於是所多瑪王、蛾摩拉王、押瑪王、洗扁王和比拉王，比拉就是瑣珥，都出來，在西訂谷擺陣，與他們交戰，","notes":[]},{"n":9,"t":"就是與以攔王基大老瑪、戈印王提達、示拿王暗拉非、以拉撒王亞略交戰；這就是四王對五王之戰。","notes":[]},{"n":10,"t":"西訂谷有許多柏油坑。所多瑪王和蛾摩拉王逃跑，掉在坑裏，其餘的人都往山上逃跑。","notes":[]},{"n":11,"t":"四王就把所多瑪和蛾摩拉所有的財物和所有的糧食都擄掠去了；","notes":[]},{"n":12,"t":"他們也把亞伯蘭的姪兒羅得和羅得的財物都擄掠去了。當時羅得住在所多瑪。","notes":[]},{"n":13,"t":"有一個逃脫的人來告訴希伯來人亞伯蘭；亞伯蘭正住在亞摩利人幔利的橡樹那裏。幔利、以實各和亞乃都是弟兄，曾與亞伯蘭結盟。","notes":[]},{"n":14,"t":"亞伯蘭聽見他姪兒 被擄去，就把三百一十八個生在他家中、受過訓練的壯丁全都出動去追，一直到但。","notes":["「姪兒」：原文是「弟兄」；下同。","「就把...全都出動」：有古卷是「就率領三百一十八個生在他家中、受過訓練的壯丁」。"]},{"n":15,"t":"在夜間，他和他的僕人分隊擊敗了敵人，並且追殺他們，直到大馬士革北邊的何把。","notes":[]},{"n":16,"t":"他把一切被擄掠的財物奪回，也把他姪兒羅得和他的財物，以及人和婦女都奪回來。","notes":[]},{"n":17,"t":"亞伯蘭擊敗基大老瑪和與他結盟的王回來的時候，所多瑪王出來，在沙微谷迎接他，沙微谷就是王的谷。","notes":[],"heads":["麥基洗德祝福亞伯蘭"]},{"n":18,"t":"又有撒冷王麥基洗德帶著餅和酒出來；他是至高神的祭司。","notes":[]},{"n":19,"t":"他為亞伯蘭祝福，說：「願至高的神、天地的主賜福給亞伯蘭！","notes":[]},{"n":20,"t":"至高的神把敵人交在你手裏，他是應當稱頌的！」亞伯蘭就把所有的拿出十分之一給他。","notes":[]},{"n":21,"t":"所多瑪王對亞伯蘭說：「你把人還給我，財物你自己拿去吧！」","notes":[]},{"n":22,"t":"亞伯蘭對所多瑪王說：「我指著耶和華—至高的神、天地的主起誓：","notes":[]},{"n":23,"t":"凡是你的東西，就是一根線、一條鞋帶，我都不拿，免得你說：『是我使亞伯蘭富足！』","notes":[]},{"n":24,"t":"我甚麼都不要，只是僕人所吃的，以及與我同去的亞乃、以實各、幔利所應得的份，讓他們拿去吧！」","notes":[]}]},"15":{"heading":"神與亞伯蘭立約","verses":[{"n":1,"t":"這些事以後，耶和華的話在異象中臨到亞伯蘭，說：「亞伯蘭哪，不要懼怕！我是你的盾牌，你必得豐富的賞賜。」","notes":[]},{"n":2,"t":"亞伯蘭說：「主耶和華啊，我還沒有兒子，你能賜我甚麼呢？承受我家業的是大馬士革人以利以謝。」","notes":[]},{"n":3,"t":"亞伯蘭又說：「看哪，你沒有給我後嗣。你看，那生在我家中的人要繼承我。」","notes":[]},{"n":4,"t":"看哪，耶和華的話又臨到他，說：「這人不會繼承你，你本身所生的才會繼承你。」","notes":[]},{"n":5,"t":"於是耶和華帶他到外面，說：「你向天觀看，去數星星，你能數得清嗎？」又對他說：「你的後裔將要如此。」","notes":[]},{"n":6,"t":"亞伯蘭信耶和華，耶和華就以此算他為義。","notes":[]},{"n":7,"t":"耶和華又對他說：「我是耶和華，曾領你出迦勒底的吾珥，為要把這地賜你為業。」","notes":[]},{"n":8,"t":"亞伯蘭說：「主耶和華啊，我怎能知道我必得這地為業呢？」","notes":[]},{"n":9,"t":"耶和華對他說：「你為我取一頭三歲的母牛犢，一隻三歲的母山羊，一隻三歲的公綿羊，一隻斑鳩和一隻雛鴿。」","notes":[]},{"n":10,"t":"亞伯蘭就把這些都取來，每樣從中間劈成兩半，一半對著另一半排列，只有鳥沒有劈開。","notes":[]},{"n":11,"t":"當鷙鳥下來，落在這些屍體上時，亞伯蘭就把牠們趕走了。","notes":[]},{"n":12,"t":"日落的時候，亞伯蘭沉睡了。看哪，有大而可怕的黑暗落在他身上。","notes":[]},{"n":13,"t":"耶和華對亞伯蘭說：「你要確實知道，你的後裔必寄居在別人的地，服事那地的人；那地的人要虐待他們四百年。","notes":[]},{"n":14,"t":"但我要懲罰他們所服事的那國，以後他們必帶著許多財物從那裏出來。","notes":[]},{"n":15,"t":"至於你，你要平平安安歸到你祖先那裏，必享長壽，被人埋葬。","notes":[]},{"n":16,"t":"到了第四代，他們必回到這裏，因為亞摩利人的罪惡到現在還沒有滿盈。」","notes":[]},{"n":17,"t":"日落天黑的時候，看哪，有冒煙的爐和燒著的火把從那些肉塊中經過。","notes":[]},{"n":18,"t":"在那日，耶和華與亞伯蘭立約，說：「我已賜給你的後裔這一片地，從埃及河直到大河，幼發拉底河，","notes":[]},{"n":19,"t":"就是基尼人、基尼洗人、甲摩尼人、","notes":[]},{"n":20,"t":"赫人、比利洗人、利乏音人、","notes":[]},{"n":21,"t":"亞摩利人、迦南人、革迦撒人、耶布斯人的地。」","notes":[]}]},"16":{"heading":"夏甲與以實瑪利","verses":[{"n":1,"t":"亞伯蘭的妻子撒萊沒有為他生孩子。撒萊有一個婢女，是埃及人，名叫夏甲。","notes":[]},{"n":2,"t":"撒萊對亞伯蘭說：「看哪，耶和華使我不能生育。你來和我的婢女同房，也許我可以從她得孩子 。」亞伯蘭聽從了撒萊的話。","notes":["「得孩子」：原文是「被建立」。"]},{"n":3,"t":"於是亞伯蘭的妻子撒萊把她的婢女，埃及人夏甲，給了丈夫為妾；那時亞伯蘭在迦南已經住了十年。","notes":[]},{"n":4,"t":"亞伯蘭與夏甲同房，夏甲就懷了孕。她看見自己有孕，就輕視她的女主人。","notes":[]},{"n":5,"t":"撒萊對亞伯蘭說：「我因你受了委屈。我把我的婢女放在你懷中，她見自己懷了孕，就輕視我。願耶和華在你我之間判斷。」","notes":[]},{"n":6,"t":"亞伯蘭對撒萊說：「看哪，婢女在你手裏，你可以照你看為好的對待她。」於是，撒萊虐待她，她就從撒萊面前逃走了。","notes":[]},{"n":7,"t":"耶和華的使者在曠野的水泉旁，在書珥路上的水泉旁遇見夏甲，","notes":[]},{"n":8,"t":"對她說：「撒萊的婢女夏甲，你從哪裏來？要到哪裏去？」她說：「我從我的女主人撒萊面前逃出來。」","notes":[]},{"n":9,"t":"耶和華的使者對她說：「你要回到你的女主人那裏，屈服在她手下。」","notes":[]},{"n":10,"t":"耶和華的使者對她說：「我必使你的後裔極其繁多，多到不可勝數。」","notes":[]},{"n":11,"t":"耶和華的使者又對她說：「看哪，你已懷孕，要生一個兒子。你要給他起名叫以實瑪利 ，因為耶和華聽見了你的苦楚。","notes":["「以實瑪利」意思是「神聽見」。"]},{"n":12,"t":"他為人必像野驢。他的手要攻打人，人的手也要攻打他；他必常與他的眾弟兄作對 。」","notes":["「他必...作對」或譯「他必住在眾弟兄的對面」。"]},{"n":13,"t":"夏甲就稱那向她說話的耶和華為「你是看見的神」，因為她說：「他看見了我之後，我還能在這裏看見他嗎？」","notes":["「看見」或譯「看顧」。"]},{"n":14,"t":"所以這井名叫庇耳‧拉海‧萊，看哪，它位於加低斯和巴列的中間。","notes":["「庇耳‧拉海‧萊」意思是「『看見我的永活者』之井」。"]},{"n":15,"t":"後來夏甲為亞伯蘭生了一個兒子；亞伯蘭給夏甲生的兒子起名叫以實瑪利。","notes":[]},{"n":16,"t":"夏甲為亞伯蘭生以實瑪利的時候，亞伯蘭年八十六歲。","notes":[]}]},"17":{"heading":"割禮為立約的記號","verses":[{"n":1,"t":"亞伯蘭九十九歲時，耶和華向他顯現，對他說：「我是全能的神。你當在我面前行走，作完全的人，","notes":[]},{"n":2,"t":"我要與你立約，使你的後裔極其繁多。」","notes":[]},{"n":3,"t":"亞伯蘭臉伏於地；神又對他說：","notes":[]},{"n":4,"t":"「看哪，這就是我與你立的約，你要成為多國的父。","notes":[]},{"n":5,"t":"從今以後，你的名字不再叫亞伯蘭，要叫亞伯拉罕，因為我已經立你作多國之父。","notes":[]},{"n":6,"t":"我必使你生養極其繁多；國度要從你而立，君王要從你而出。","notes":[]},{"n":7,"t":"我要與你，以及你世世代代的後裔堅立我的約，成為永遠的約，是要作你和你後裔的神。","notes":[]},{"n":8,"t":"我要把你現在寄居的地，就是迦南全地，賜給你和你的後裔永遠為業；我也必作他們的神。」","notes":[]},{"n":9,"t":"神又對亞伯拉罕說：「你和你的後裔一定要世世代代遵守我的約。","notes":[]},{"n":10,"t":"這就是我與你，以及你的後裔所立的約，是你們所當遵守的，你們所有的男子都要受割禮。","notes":[]},{"n":11,"t":"你們要割去肉體的包皮，這是我與你們立約的記號。","notes":[]},{"n":12,"t":"你們世世代代的男子，無論是在家裏生的，或是用銀子從外人買來而不是你後裔生的，都要在生下來的第八日受割禮。","notes":[]},{"n":13,"t":"你家裏生的和你用銀子買的，都必須受割禮。這樣，我的約就在你們肉體上成為永遠的約。","notes":[]},{"n":14,"t":"不受割禮的男子都必從民中剪除，因他違背了我的約。」","notes":[]},{"n":15,"t":"神又對亞伯拉罕說：「至於你的妻子撒萊，不可再叫她撒萊，她的名要叫撒拉。","notes":[]},{"n":16,"t":"我必賜福給她，也要從她賜一個兒子給你。我必賜福給撒拉，她要興起多國；必有百姓的君王從她而出。」","notes":[]},{"n":17,"t":"亞伯拉罕就臉伏於地竊笑，心裏想：「一百歲的人還能有孩子嗎？撒拉已經九十歲了，還能生育嗎？」","notes":[]},{"n":18,"t":"亞伯拉罕對神說：「但願以實瑪利活在你面前。」","notes":[]},{"n":19,"t":"神說：「不！你妻子撒拉必為你生一個兒子，你要給他起名叫以撒。我要與他堅立我的約，成為他後裔永遠的約。","notes":[]},{"n":20,"t":"至於以實瑪利，我已聽見你了：看哪，我必賜福給他，使他興旺，極其繁多。他必生十二個族長，我要使他成為大國。","notes":[]},{"n":21,"t":"到明年所定的時候，撒拉必為你生以撒，我要與他堅立我的約。」","notes":[]},{"n":22,"t":"神和亞伯拉罕說完了話，就離開他上升去了。","notes":[]},{"n":23,"t":"在那一天，亞伯拉罕遵照神所說的，給他的兒子以實瑪利和家裏所有的男丁，無論是在家裏生的，或是用銀子買來的，都行了割禮。","notes":["「行了割禮」：原文是「割了肉體的包皮」；24、 25節的「割禮」同。"]},{"n":24,"t":"亞伯拉罕受割禮時，年九十九歲。","notes":[]},{"n":25,"t":"他兒子以實瑪利受割禮時，年十三歲。","notes":[]},{"n":26,"t":"在那一天，亞伯拉罕和他兒子以實瑪利一同受了割禮。","notes":[]},{"n":27,"t":"家裏所有的男人，無論是在家裏生的，或是用銀子從外人買來的，也都一同受了割禮。","notes":[]}]},"18":{"heading":"亞伯拉罕得兒子的應許","verses":[{"n":1,"t":"耶和華在幔利橡樹那裏向亞伯拉罕顯現。天正熱的時候，亞伯拉罕坐在帳棚門口。","notes":[]},{"n":2,"t":"他舉目觀看，看哪，有三個人站在他附近。他一看見，就從帳棚門口跑去迎接他們，俯伏在地，","notes":[]},{"n":3,"t":"說：「我主，我若在你眼前蒙恩，請不要離開你的僕人走過去。","notes":[]},{"n":4,"t":"容我拿點水來，請你們洗腳，在樹下休息。","notes":[]},{"n":5,"t":"既然你們來到僕人這裏了，我再拿點餅來，讓你們恢復心力，然後再走。」他們說：「就照你說的去做吧。」","notes":[]},{"n":6,"t":"亞伯拉罕急忙進帳棚到撒拉那裏，說：「你趕快拿三細亞細麵，揉麵做餅。」","notes":[]},{"n":7,"t":"亞伯拉罕又跑到牛群裏，牽了一頭又嫩又好的牛犢來，交給僕人，僕人就急忙去預備。","notes":[]},{"n":8,"t":"亞伯拉罕取了乳酪和奶，以及預備好了的牛犢來，擺在他們面前，自己在樹下站在旁邊，他們就吃了。","notes":[]},{"n":9,"t":"他們對亞伯拉罕說：「你妻子撒拉在哪裏？」他說：「看哪，在帳棚裏。」","notes":[]},{"n":10,"t":"有一位說：「明年這時候 ，我一定會回到你這裏。看哪，你的妻子撒拉會生一個兒子。」撒拉在那人後面的帳棚門口也聽見了。","notes":["「明年這時候」：原文是「生命足月的時候」；14節同。"]},{"n":11,"t":"亞伯拉罕和撒拉都年紀老邁，撒拉的月經已停了。","notes":[]},{"n":12,"t":"撒拉心裏竊笑，說：「我已衰老，我的主也老了，怎能有這喜事呢？」","notes":[]},{"n":13,"t":"耶和華對亞伯拉罕說：「撒拉為甚麼竊笑，說：『我已年老，果真能生育嗎？』","notes":[]},{"n":14,"t":"耶和華豈有難成的事嗎？到了所定的時候，我必回到你這裏。明年這時候，撒拉會生一個兒子。」","notes":[]},{"n":15,"t":"撒拉因為害怕，就不承認，說：「我沒有笑。」那人說：「不，你的確笑了。」","notes":[]},{"n":16,"t":"三人從那裏起程，面向所多瑪觀望，亞伯拉罕與他們同行，要送他們一程。","notes":[],"heads":["亞伯拉罕為所多瑪祈求"]},{"n":17,"t":"耶和華說：「我所要做的事豈可瞞著亞伯拉罕呢？","notes":[]},{"n":18,"t":"亞伯拉罕必要成為強大的國；地上的萬國都必因他得福。","notes":[]},{"n":19,"t":"我揀選他，為要叫他命令他的子孫和後代家屬遵行耶和華的道，秉公行義，使耶和華所應許亞伯拉罕的話都實現了。」","notes":["「揀選他」：原文是「認識他」。"]},{"n":20,"t":"耶和華說：「所多瑪和蛾摩拉罪惡極其嚴重，控告他們的聲音很大。","notes":[]},{"n":21,"t":"我要下去察看他們所做的，是否真的像那達到我這裏的聲音一樣；如果不是，我也要知道。」","notes":[]},{"n":22,"t":"二人轉身離開那裏，往所多瑪去；但亞伯拉罕仍然站在耶和華面前。","notes":[]},{"n":23,"t":"亞伯拉罕近前來，說：「你真的要把義人和惡人一同剿滅嗎？","notes":[]},{"n":24,"t":"假若那城裏有五十個義人，你真的還要剿滅，不因城裏這五十個義人饒了那地方嗎？","notes":[]},{"n":25,"t":"你絕不會做這樣的事，把義人與惡人一同殺了，使義人與惡人一樣。你絕不會這樣！審判全地的主豈不做公平的事嗎？」","notes":[]},{"n":26,"t":"耶和華說：「我若在所多瑪城裏找到五十個義人，我就為他們的緣故饒恕那整個地方。」","notes":[]},{"n":27,"t":"亞伯拉罕回答說：「看哪，我雖只是塵土灰燼，還敢向主說話。","notes":[]},{"n":28,"t":"假若這五十個義人少了五個，你就因為少了五個而毀滅全城嗎？」他說：「我在那裏若找到四十五個，就不毀滅。」","notes":[]},{"n":29,"t":"亞伯拉罕又對他說：「假若在那裏找到四十個呢？」他說：「為這四十個的緣故，我也不做。」","notes":[]},{"n":30,"t":"亞伯拉罕說：「求主不要生氣，容我說，假若在那裏找到三十個呢？」他說：「我在那裏若找到三十個，我也不做。」","notes":[]},{"n":31,"t":"亞伯拉罕說：「看哪，我還敢向主說，假若在那裏找到二十個呢？」他說：「為這二十個的緣故，我也不毀滅。」","notes":[]},{"n":32,"t":"亞伯拉罕說：「求主不要生氣，我再說一次，假若在那裏找到十個呢？」他說：「為這十個的緣故，我也不毀滅。」","notes":[]},{"n":33,"t":"耶和華與亞伯拉罕說完了話就走了；亞伯拉罕也回到自己的地方去了。","notes":[]}]},"19":{"heading":"所多瑪的罪惡","verses":[{"n":1,"t":"兩個天使在傍晚到了所多瑪，羅得正坐在所多瑪的城門口。羅得一看見，就起身迎接他們，臉伏於地下拜，","notes":[]},{"n":2,"t":"說：「看哪，我主，請你們轉到僕人家裏過夜，洗你們的腳，清早起來再上路。」他們說：「不！我們要在廣場上過夜。」","notes":[]},{"n":3,"t":"羅得懇切地請他們，他們就轉向他，進到他屋裏。羅得為他們預備宴席，烤無酵餅，他們就吃了。","notes":[]},{"n":4,"t":"他們還沒有躺下，所多瑪城的人，連老帶少所有的人，個個都來圍住那屋子。","notes":[]},{"n":5,"t":"他們呼叫羅得，對他說：「今天晚上到你這裏來的人在哪裏？把他們帶出來，讓我們親近他們。」","notes":[]},{"n":6,"t":"羅得出了門，把身後的門關上，到眾人那裏，","notes":[]},{"n":7,"t":"說：「我的弟兄們，請你們不要做這惡事。","notes":[]},{"n":8,"t":"看哪，我有兩個女兒，還沒有親近過男人，讓我領她們出來給你們，就照你們看為好的對待她們吧！只是這兩個人既然到我舍下，請不要向他們做這事。」","notes":[]},{"n":9,"t":"眾人說：「站到一邊去吧！」又說：「這個人來寄居，還想扮審判官呢！現在我們要害你比害他們更厲害。」眾人就往前衝向羅得，要攻破大門。","notes":[]},{"n":10,"t":"那兩個人伸出手來，把羅得拉進屋子他們那裏，就關上門。","notes":[]},{"n":11,"t":"他們擊打門外的人，無論老少，都眼睛迷糊，找門找得很煩躁。","notes":[]},{"n":12,"t":"那兩個人對羅得說：「你這裏還有甚麼人嗎？無論是女婿，是兒女，這城中所有屬你的人，你都要把他們從這地方帶出去。","notes":[],"heads":["羅得離開所多瑪"]},{"n":13,"t":"我們要毀滅這地方，因為控告城內百姓的聲音在耶和華面前非常大，耶和華派我們來毀滅這城。」","notes":[]},{"n":14,"t":"羅得出去，告訴娶了他女兒的女婿們說：「起來，離開這地方，因為耶和華要毀滅這城。」他的女婿們卻以為他說的是笑話。","notes":["「娶了」或譯「將要娶」。"]},{"n":15,"t":"天亮了，天使催逼羅得說：「起來！帶著你的妻子和你這裏的兩個女兒出去，免得你因這城的罪孽同被剿滅。」","notes":[]},{"n":16,"t":"但羅得遲延不走。二人因為耶和華憐憫羅得，就拉著他的手和他妻子的手，以及他兩個女兒的手，把他們領出來，安置在城外；","notes":[]},{"n":17,"t":"領他們出來以後，就說：「逃命吧！不可回頭看，也不可在平原站住。要往山上逃跑，免得你被剿滅。」","notes":[]},{"n":18,"t":"羅得對他們說：「我主啊，不要這樣！","notes":[]},{"n":19,"t":"看哪，你僕人已經在你眼前蒙恩，你又向我大施慈愛，救我的性命。但是我不能逃到山上去，恐怕這災禍追上我，我就死了。","notes":[]},{"n":20,"t":"看哪，這城又近又小，比較容易逃到那裏。這不是一座小城嗎？求你容我逃到那裏，使我的性命可以存活。」","notes":[]},{"n":21,"t":"天使對他說：「看哪，這事我也應允你，不傾覆你所說的這城。","notes":[]},{"n":22,"t":"你要趕快逃到那城，因為你還沒有到那裏，我不能做甚麼。」因此那城名叫瑣珥 。","notes":["「瑣珥」意思是「小」。"]},{"n":23,"t":"羅得到了瑣珥，太陽已經升出地面。","notes":[],"heads":["所多瑪蛾摩拉的毀滅"]},{"n":24,"t":"當時，耶和華把硫磺與火，從天上耶和華那裏降與所多瑪和蛾摩拉，","notes":[]},{"n":25,"t":"把那些城和全平原，城裏所有的居民和土地上生長的，都毀滅了。","notes":[]},{"n":26,"t":"羅得的妻子在他後邊回頭一看，就變成了一根鹽柱。","notes":[]},{"n":27,"t":"亞伯拉罕清早起來，到了他先前站在耶和華面前的地方，","notes":[]},{"n":28,"t":"面向所多瑪和蛾摩拉，以及平原全地觀望。他觀看，看哪，那地有濃煙上騰，好像燒窯的濃煙。","notes":[]},{"n":29,"t":"當神毀滅平原諸城的時候，他記念亞伯拉罕；在傾覆羅得所住之城的時候，就把羅得從傾覆中帶出來。","notes":[]},{"n":30,"t":"羅得因為怕住在瑣珥，就同他兩個女兒從瑣珥上去，住在山上。他和兩個女兒住在一個洞裏。","notes":[],"heads":["摩押人和亞捫人的起源"]},{"n":31,"t":"大女兒對小女兒說：「我們的父親老了，這地又沒有男人可以照世上的禮俗來與我們結合。","notes":[]},{"n":32,"t":"來！我們叫父親喝酒，然後與他同寢。這樣，我們可以從我們的父親存留後裔。」","notes":[]},{"n":33,"t":"於是，那晚她們叫父親喝酒，大女兒就進去和她父親同寢；她幾時躺下，幾時起來，父親都不知道。","notes":[]},{"n":34,"t":"第二天，大女兒對小女兒說：「看哪，我昨夜與父親同寢。今晚我們再叫他喝酒，你進去與他同寢。這樣，我們可以從父親存留後裔。」","notes":[]},{"n":35,"t":"於是，那晚她們又叫父親喝酒，小女兒起來與她父親同寢；她幾時躺下，幾時起來，父親都不知道。","notes":[]},{"n":36,"t":"這樣，羅得的兩個女兒都從她們的父親懷了孕。","notes":[]},{"n":37,"t":"大女兒生了兒子，給他起名叫摩押，就是現今摩押人的始祖。","notes":[]},{"n":38,"t":"小女兒也生了兒子，給他起名叫便‧亞米，就是現今亞捫人的始祖。","notes":[]}]},"20":{"heading":"亞伯拉罕和亞比米勒","verses":[{"n":1,"t":"亞伯拉罕從那裏往尼革夫遷移，寄居在加低斯和書珥之間的基拉耳。","notes":[]},{"n":2,"t":"亞伯拉罕稱他的妻子撒拉為妹妹。基拉耳王亞比米勒派人把撒拉帶走。","notes":[]},{"n":3,"t":"夜間，神在夢中來到亞比米勒那裏，對他說：「看哪，你要死了，因為你帶來的女人，她是有丈夫的女子！」","notes":[]},{"n":4,"t":"亞比米勒還未親近撒拉；他說：「主啊，連公義的國，你也要毀滅嗎？","notes":[]},{"n":5,"t":"那人豈不是自己對我說『她是我妹妹』嗎？連這女人自己也說：『他是我哥哥。』我做這事是心正手潔的。」","notes":[]},{"n":6,"t":"神在夢中對他說：「我也知道你做這事是心中正直的；是我攔阻了你，免得你得罪我。所以我不讓你侵犯她。","notes":[]},{"n":7,"t":"現在你當把這人的妻子歸還給他；因為他是先知，他要為你禱告，使你存活。你若不歸還，你當知道，你和你所有的人都必定死。」","notes":[]},{"n":8,"t":"亞比米勒清早起來，叫了他的眾臣僕來，把這一切事說給他們聽，他們就很害怕。","notes":[]},{"n":9,"t":"亞比米勒召了亞伯拉罕來，對他說：「你怎麼向我這樣做呢？我甚麼事得罪你，你竟使我和我的國陷在大罪中呢？你對我做了不該做的事了！」","notes":[]},{"n":10,"t":"亞比米勒對亞伯拉罕說：「你看見甚麼才做這事呢？」","notes":[]},{"n":11,"t":"亞伯拉罕說：「我以為這地方的人根本不敬畏神，必為我妻子的緣故殺我。","notes":[]},{"n":12,"t":"況且她也真是我的妹妹；她與我是同父異母的，後來作了我的妻子。","notes":[]},{"n":13,"t":"當神叫我離開父家、飄流在外的時候，我對她說：我們無論走到甚麼地方，你要對人說：『他是我哥哥』，這就是你以慈愛待我了。」","notes":[]},{"n":14,"t":"亞比米勒把牛、羊、奴僕、婢女送給亞伯拉罕，也把他的妻子撒拉歸還給他。","notes":[]},{"n":15,"t":"亞比米勒說：「看哪，我的地都在你面前，你看為好的地方就居住吧。」","notes":[]},{"n":16,"t":"他對撒拉說：「看哪，我給你哥哥一千銀子。看哪，這要在你全家人面前遮羞，向眾人證實你是清白的。」","notes":["「羞」：原文是「眼」。"]},{"n":17,"t":"亞伯拉罕向神禱告，神就醫好亞比米勒和他的妻子，以及他的使女們，他們就能生育。","notes":[]},{"n":18,"t":"因耶和華為亞伯拉罕的妻子撒拉的緣故，已經使亞比米勒家中的婦人不能懷孕。","notes":[]}]},"21":{"heading":"以撒出生","verses":[{"n":1,"t":"耶和華照著他所說的眷顧撒拉，耶和華實現了他對撒拉的應許。","notes":[]},{"n":2,"t":"亞伯拉罕年老，到神對他說的那所定的時候，撒拉懷了孕，給他生了一個兒子。","notes":[]},{"n":3,"t":"亞伯拉罕給撒拉所生的兒子起名叫以撒。","notes":[]},{"n":4,"t":"以撒出生後第八日，亞伯拉罕遵照神所吩咐的，為以撒行割禮。","notes":[]},{"n":5,"t":"他兒子以撒出生的時候，亞伯拉罕年一百歲。","notes":[]},{"n":6,"t":"撒拉說：「神使我歡笑，凡聽見的人必與我一同歡笑」，","notes":[]},{"n":7,"t":"又說：「誰能預先對亞伯拉罕說，撒拉要乳養孩子呢？因為在他年老的時候，我為他生了一個兒子。」","notes":[]},{"n":8,"t":"孩子漸漸長大，就斷了奶。以撒斷奶的那一天，亞伯拉罕擺設豐盛的宴席。","notes":[]},{"n":9,"t":"那時，撒拉看見埃及人夏甲為亞伯拉罕所生的兒子戲笑，","notes":[],"heads":["夏甲和以實瑪利被逐"]},{"n":10,"t":"就對亞伯拉罕說：「你把這使女和她兒子趕出去！因為這使女的兒子不可與我的兒子以撒一同承受產業。」","notes":[]},{"n":11,"t":"亞伯拉罕為這事非常憂愁，因為關乎他的兒子。","notes":[]},{"n":12,"t":"神對亞伯拉罕說：「你不必為這孩子和你的使女憂愁。撒拉對你說的話，你都要聽從；因為從以撒生的，才要稱為你的後裔。","notes":[]},{"n":13,"t":"至於使女的兒子，我也必使他成為一國，因為他是你的後裔。」","notes":[]},{"n":14,"t":"亞伯拉罕清早起來，拿餅和一皮袋水，給了夏甲，搭在她肩上，把她和孩子一起送走。夏甲就走了，但她卻在別是巴的曠野流浪。","notes":[]},{"n":15,"t":"皮袋的水用完了，夏甲就把孩子放在一棵小樹下，","notes":[]},{"n":16,"t":"自己走開約有一箭之遠，相對而坐，說：「我不忍心看見孩子死」。她就坐在對面，放聲大哭。","notes":[]},{"n":17,"t":"神聽見孩子的聲音，神的使者就從天上呼叫夏甲說：「夏甲，你為何這樣呢？不要害怕，神已經聽見孩子在那裏的聲音了。","notes":[]},{"n":18,"t":"起來！把孩子扶起來，用你的手握住他，因我必使他成為大國。」","notes":[]},{"n":19,"t":"神開了夏甲的眼睛，她就看見一口水井。她就去，把皮袋裝滿了水，給孩子喝。","notes":[]},{"n":20,"t":"神與這孩子同在，他就漸漸長大，住在曠野，成了一個弓箭手。","notes":[]},{"n":21,"t":"他住在巴蘭的曠野；他母親從埃及地為他娶了一個妻子。","notes":[]},{"n":22,"t":"那時候，亞比米勒和他的將軍非各對亞伯拉罕說：「凡你所做的事，神都與你同在。","notes":[],"heads":["亞伯拉罕與亞比米勒立約"]},{"n":23,"t":"我願你如今在這裏指著神對我起誓，不要虧待我和我的兒子，以及我的子孫。我怎樣忠誠待你，你也要照樣忠誠待我和你所寄居的這地。」","notes":[]},{"n":24,"t":"亞伯拉罕說：「我願意起誓。」","notes":[]},{"n":25,"t":"先前，亞比米勒的僕人霸佔了一口水井，亞伯拉罕為這事責備亞比米勒。","notes":[]},{"n":26,"t":"亞比米勒說：「我不知道誰做了這事，你也沒有告訴我，我到今日才聽到。」","notes":[]},{"n":27,"t":"亞伯拉罕把羊和牛給了亞比米勒，二人就彼此立約。","notes":[]},{"n":28,"t":"亞伯拉罕把七隻小母羊另放在一處。","notes":[]},{"n":29,"t":"亞比米勒對亞伯拉罕說：「你把這七隻小母羊另放一處是甚麼意思呢？」","notes":[]},{"n":30,"t":"他說：「你要從我手裏接受這七隻小母羊，作我挖了這口井的證據。」","notes":[]},{"n":31,"t":"所以他給那地方起名叫別是巴，因為他們二人在那裏起了誓。","notes":["「別是巴」意思是「盟誓的井」。"]},{"n":32,"t":"他們在別是巴立了約，亞比米勒就和他的將軍非各起身回非利士人的地去了。","notes":[]},{"n":33,"t":"亞伯拉罕就在別是巴種了一棵柳樹，在那裏求告耶和華—永恆神的名。","notes":[]},{"n":34,"t":"亞伯拉罕在非利士人的地寄居了許多日子。","notes":[]}]},"22":{"heading":"亞伯拉罕獻以撒","verses":[{"n":1,"t":"這些事以後，神考驗亞伯拉罕，對他說：「亞伯拉罕！」他說：「我在這裏。」","notes":[]},{"n":2,"t":"神說：「你要帶你的兒子，就是你所愛的獨子以撒，往摩利亞地去，在我指示你的一座山上，把他獻為燔祭。」","notes":[]},{"n":3,"t":"亞伯拉罕清早起來，預備了驢，帶著跟他一起的兩個僕人和他兒子以撒，劈好了燔祭的柴，就起身往神指示他的地方去了。","notes":[]},{"n":4,"t":"到了第三日，亞伯拉罕舉目遙望那地方。","notes":[]},{"n":5,"t":"亞伯拉罕對他的僕人說：「你們和驢留在這裏，我和孩子要去那裏敬拜，然後回到你們這裏來。」","notes":[]},{"n":6,"t":"亞伯拉罕把燔祭的柴放在他兒子以撒身上，自己手裏拿著火與刀；於是二人同行。","notes":[]},{"n":7,"t":"以撒對他父親亞伯拉罕說：「我父啊！」亞伯拉罕說：「我兒，我在這裏。」以撒說：「看哪，火與柴都有了，但燔祭的羔羊在哪裏呢？」","notes":[]},{"n":8,"t":"亞伯拉罕說：「我兒，神必自己預備燔祭的羔羊。」於是二人同行。","notes":[]},{"n":9,"t":"他們到了神指示他的地方，亞伯拉罕在那裏築壇，把柴擺好，綁了他兒子以撒，放在壇的柴上。","notes":[]},{"n":10,"t":"亞伯拉罕就伸手拿刀，要殺他的兒子。","notes":[]},{"n":11,"t":"耶和華的使者從天上呼喚他說：「亞伯拉罕！亞伯拉罕！」他說：「我在這裏。」","notes":[]},{"n":12,"t":"天使說：「不可在這孩子身上下手！一點也不可傷害他！現在我知道你是敬畏神的人了，因為你沒有把你的兒子，就是你的獨子，留下不給我。」","notes":[]},{"n":13,"t":"亞伯拉罕舉目觀看，看哪，一隻公綿羊兩角纏在灌木叢中。亞伯拉罕就去牽了那隻公綿羊，獻為燔祭，代替他的兒子。","notes":[]},{"n":14,"t":"亞伯拉罕給那地方起名叫「耶和華以勒」 。直到今日人還說：「在耶和華的山上必有預備。」","notes":["「耶和華以勒」意思是「耶和華必預備」。"]},{"n":15,"t":"耶和華的使者第二次從天上呼喚亞伯拉罕，","notes":[]},{"n":16,"t":"說：「耶和華說：『你既行了這事，沒有留下你的兒子，就是你的獨子，我指著自己起誓：","notes":[]},{"n":17,"t":"我必多多賜福給你，我必使你的後裔大大增多，如同天上的星、海邊的沙。你的後裔必得仇敵的城門，","notes":[]},{"n":18,"t":"並且地上的萬國都必因你的後裔得福，因為你聽從了我的話。』」","notes":[]},{"n":19,"t":"於是亞伯拉罕回到他僕人那裏。他們一同起身，往別是巴去，亞伯拉罕就住在別是巴。","notes":[]},{"n":20,"t":"這些事以後，有人告訴亞伯拉罕說：「看哪，密迦也為你兄弟拿鶴生了幾個兒子：","notes":[],"heads":["拿鶴的後代"]},{"n":21,"t":"長子烏斯、他的兄弟布斯、亞蘭的父親基摩利、","notes":[]},{"n":22,"t":"基薛、哈瑣、必達、益拉和彼土利。」","notes":[]},{"n":23,"t":"彼土利生利百加。這八個人都是密迦為亞伯拉罕的兄弟拿鶴生的。","notes":[]},{"n":24,"t":"拿鶴的妾名叫流瑪，她也生了提八、迦含、他轄和瑪迦。","notes":[]}]},"23":{"heading":"亞伯拉罕買墳地葬撒拉","verses":[{"n":1,"t":"撒拉享壽一百二十七歲，這是撒拉一生的歲數。","notes":["七十士譯本沒有「這是...歲數」。"]},{"n":2,"t":"撒拉死在迦南地的基列‧亞巴，就是希伯崙。亞伯拉罕來哀悼撒拉，為她哭泣。","notes":[]},{"n":3,"t":"然後，亞伯拉罕起來，離開死人面前，對赫人說：","notes":[]},{"n":4,"t":"「我在你們中間是外人，是寄居的。請給我你們那裏的一塊墳地，我好埋葬我的亡妻，使她不在我的面前。」","notes":[]},{"n":5,"t":"赫人回答亞伯拉罕說：","notes":[]},{"n":6,"t":"「我主請聽。你在我們中間是一位尊貴的王子，只管在我們最好的墳地裏埋葬你的死人；我們沒有一人會拒絕你在他的墳地裏埋葬你的死人。」","notes":[]},{"n":7,"t":"於是，亞伯拉罕起來，向當地的百姓赫人下拜，","notes":[]},{"n":8,"t":"對他們說：「你們若願意讓我埋葬我的亡妻，使她不在我面前，就請聽我，為我求瑣轄的兒子以弗崙，","notes":[]},{"n":9,"t":"把他田地盡頭的麥比拉洞賣給我。他可以按照足價賣給我，作為我在你們中間的墳地。」","notes":[]},{"n":10,"t":"那時，以弗崙正坐在赫人中間。赫人以弗崙就回答亞伯拉罕，說給所有出入城門的赫人聽：","notes":[]},{"n":11,"t":"「不，我主請聽。我要把這塊田送給你，連田間的洞也送給你，在我同族的人眼前都給你，讓你埋葬你的死人。」","notes":[]},{"n":12,"t":"亞伯拉罕就在當地的百姓面前下拜，","notes":[]},{"n":13,"t":"對以弗崙說，也給當地百姓聽：「你若應允，請你聽我。我要把田的價錢給你，請你收下，我就在那裏埋葬我的死人。」","notes":[]},{"n":14,"t":"以弗崙回答亞伯拉罕說：","notes":[]},{"n":15,"t":"「我主請聽。四百舍客勒銀子的地，在你我中間算甚麼呢？只管埋葬你的死人吧！」","notes":[]},{"n":16,"t":"亞伯拉罕聽從了以弗崙。亞伯拉罕就照著他說給赫人聽的，把買賣通用的銀子，秤了四百舍客勒銀子給以弗崙。","notes":[]},{"n":17,"t":"於是，以弗崙把那塊位於幔利對面的麥比拉田，和其中的洞，以及田間周圍的樹木都成交了，","notes":[]},{"n":18,"t":"在所有出入城門的赫人眼前，賣給亞伯拉罕作為他的產業。","notes":[]},{"n":19,"t":"後來，亞伯拉罕把他妻子撒拉安葬在迦南地幔利對面的麥比拉田間的洞裏，幔利就是希伯崙。","notes":[]},{"n":20,"t":"從此，那塊田和田間的洞就從赫人移交給亞伯拉罕作墳地的產業。","notes":[]}]},"24":{"heading":"以撒娶妻","verses":[{"n":1,"t":"亞伯拉罕年紀老邁，耶和華在一切事上都賜福給他。","notes":[]},{"n":2,"t":"亞伯拉罕對他家中管理他一切產業最老的僕人說：「把你的手放在我大腿底下。","notes":[]},{"n":3,"t":"我要叫你指著耶和華—天和地的神起誓，不要為我兒子娶我所居住的迦南地的女子為妻。","notes":[]},{"n":4,"t":"你要往我的本地本族去，為我的兒子以撒娶妻。」","notes":[]},{"n":5,"t":"僕人對他說：「如果那女子不肯跟我來到這地，我必須把你的兒子帶回到你出來的地方嗎？」","notes":[]},{"n":6,"t":"亞伯拉罕對他說：「你要謹慎，不可帶我兒子回那裏去。","notes":[]},{"n":7,"t":"耶和華—天上的神曾帶領我離開父家和本族的地，對我說話，向我起誓說：『我要將這地賜給你的後裔。』他要差遣使者在你面前，你就可以從那裏為我兒子娶妻。","notes":[]},{"n":8,"t":"倘若那女子不肯跟你來，我叫你起的誓就與你無關了，只是你不可帶我的兒子回到那裏去。」","notes":[]},{"n":9,"t":"僕人就把手放在他主人亞伯拉罕的大腿底下，為這事向他起誓。","notes":[]},{"n":10,"t":"那僕人從他主人的駱駝中取了十匹駱駝，他手中也帶著他主人各樣的貴重物品離開，起身往美索不達米亞去，到了拿鶴的城。","notes":["七十士譯本沒有「離開」。"]},{"n":11,"t":"傍晚時，眾女子出來打水，他就讓駱駝跪在城外的水井旁。","notes":[]},{"n":12,"t":"他說：「耶和華—我主人亞伯拉罕的神啊，求你施恩給我的主人亞伯拉罕，讓我今日就遇見吧！","notes":[]},{"n":13,"t":"看哪，我站在井旁，城內居民的女子們正出來打水。","notes":[]},{"n":14,"t":"我向哪一個少女說：『請你放下水瓶來，給我水喝』，她若說：『請喝！我也給你的駱駝喝』，願她作你所選定給你僕人以撒的妻。這樣，我就知道你施恩給我的主人了。」","notes":[]},{"n":15,"t":"話還沒說完，看哪，利百加肩頭上扛著水瓶出來。利百加是彼土利所生的；彼土利是亞伯拉罕的兄弟拿鶴妻子密迦的兒子。","notes":[]},{"n":16,"t":"那少女容貌極其美麗，是未曾與人親近的童女。她下到井旁，打滿了瓶子的水，就上來。","notes":[]},{"n":17,"t":"僕人跑上前去迎著她，說：「請你讓我喝你瓶子裏的一點水。」","notes":[]},{"n":18,"t":"少女說：「我主請喝！」就急忙拿下瓶子托在手上，給他喝水。","notes":[]},{"n":19,"t":"那少女給他喝足了，又說：「我也為你的駱駝打水，直到駱駝喝足了。」","notes":[]},{"n":20,"t":"她就急忙把瓶子裏的水倒在槽裏，又跑到井旁打水，為所有的駱駝打了水。","notes":[]},{"n":21,"t":"那人定睛看著少女，一句話也不說，要知道耶和華是否使他的道路亨通。","notes":[]},{"n":22,"t":"駱駝喝足了，那人就拿出一個比加重的金環，一對十舍客勒重的金手鐲，","notes":["「比加」：重量單位；參「度量衡表」。"]},{"n":23,"t":"說：「請告訴我，你是誰的女兒？你父親家裏有沒有地方可以讓我們過夜？」","notes":[]},{"n":24,"t":"少女說：「我是密迦為拿鶴生的兒子彼土利的女兒。」","notes":[]},{"n":25,"t":"又說：「我們家裏有充足的乾草和飼料，也有住宿的地方。」","notes":[]},{"n":26,"t":"那人就低頭向耶和華敬拜，","notes":[]},{"n":27,"t":"說：「耶和華—我主人亞伯拉罕的神是應當稱頌的，因他不斷以慈愛信實待我主人。至於我，耶和華一路引領我，直到我主人的兄弟家裏。」","notes":[]},{"n":28,"t":"那少女跑去，把這些話告訴她母親家裏的人。","notes":[]},{"n":29,"t":"利百加有一個哥哥，名叫拉班，拉班就跑到外面井旁那人那裏。","notes":[]},{"n":30,"t":"當他看見金環和戴在他妹妹手上的金鐲，又聽見他妹妹利百加說的話：「那人如此對我說」，他就來到那人面前，看哪，他還站在井旁的駱駝旁邊，","notes":[]},{"n":31,"t":"就對他說：「你這蒙耶和華賜福的人，請進來吧！為甚麼站在外面？我已經收拾了房屋，也為駱駝預備了地方。」","notes":[]},{"n":32,"t":"那人就進了拉班的家。拉班卸了駱駝，用飼料餵牠們，拿水給那人和隨從他的人洗腳，","notes":[]},{"n":33,"t":"把食物擺在他面前，請他吃。他卻說：「我不吃，等我把我的事情說完了再吃。」拉班說：「請說。」","notes":[]},{"n":34,"t":"他說：「我是亞伯拉罕的僕人。","notes":[]},{"n":35,"t":"耶和華大大地賜福給我主人，使他發達，賜給他羊群、牛群、金銀、奴僕、婢女、駱駝和驢。","notes":[]},{"n":36,"t":"我主人的妻子撒拉年老的時候為我主人生了一個兒子；我主人把他一切所有的都給了他。","notes":[]},{"n":37,"t":"我主人叫我起誓說：『不要為我兒子娶我所居住的迦南地的女子為妻。","notes":[]},{"n":38,"t":"你要往我父家、我本族那裏去，為我的兒子娶妻。』","notes":[]},{"n":39,"t":"我對我主人說：『恐怕那女子不肯跟我來。』","notes":[]},{"n":40,"t":"他就說：『我所事奉的耶和華必要差遣他的使者與你同去，使你的道路亨通，你就可以在我父家、我本族那裏，為我的兒子娶妻。","notes":[]},{"n":41,"t":"只要你到了我本族那裏，我叫你起的誓就與你無關。他們若不把女子交給你，我叫你起的誓也與你無關。』","notes":[]},{"n":42,"t":"「我今日到了井旁，就說：『耶和華—我主人亞伯拉罕的神啊，願你使我所行的道路亨通。","notes":[]},{"n":43,"t":"看哪，我站在井旁，對哪一個出來打水的女子說：請你讓我喝你瓶子裏的一點水，","notes":[]},{"n":44,"t":"她若說：你只管喝，我也為你的駱駝打水；願那女子作耶和華給我主人兒子所選定的妻子。』","notes":[]},{"n":45,"t":"「我心裏的話還沒有說完，看哪，利百加肩頭上扛著水瓶出來，下到井旁打水。我對她說：『請你給我水喝。』","notes":[]},{"n":46,"t":"她就急忙從肩頭上拿下瓶子來，說：『請喝！我也給你的駱駝喝。』我就喝了；她也給我的駱駝喝了。","notes":[]},{"n":47,"t":"我問她說：『你是誰的女兒？』她說：『我是彼土利的女兒，彼土利是密迦和拿鶴生的兒子。』我就把環子戴在她鼻子上，把鐲子戴在她雙手上。","notes":[]},{"n":48,"t":"然後我低頭向耶和華敬拜，稱頌耶和華—我主人亞伯拉罕的神，因為他引導我走合適的道路，使我得著我主人兄弟的孫女，給我主人的兒子為妻。","notes":[]},{"n":49,"t":"現在你們若願以慈愛誠信待我主人，就告訴我；若不然，也告訴我，使我可以或向左，或向右。」","notes":[]},{"n":50,"t":"拉班和彼土利回答說：「這事既然出於耶和華，我們不能向你說好說歹。","notes":[]},{"n":51,"t":"看哪，利百加就在你面前，可以將她帶去，遵照耶和華所說的，給你主人的兒子為妻。」","notes":[]},{"n":52,"t":"亞伯拉罕的僕人聽見他們這些話，就向耶和華俯伏在地。","notes":[]},{"n":53,"t":"僕人拿出金器、銀器和衣服送給利百加，又將貴重的物品送給她哥哥和她母親。","notes":[]},{"n":54,"t":"然後，僕人和隨從的人才吃喝，並且住了一夜。早晨起來，僕人說：「請讓我回我主人那裏去吧。」","notes":[]},{"n":55,"t":"利百加的哥哥和母親說：「讓她同我們再住幾天，也許十天，然後她可以去。」","notes":[]},{"n":56,"t":"僕人對他們說：「耶和華既然使我道路亨通，你們就不要耽誤我，請讓我走，回我主人那裏去吧！」","notes":[]},{"n":57,"t":"他們說：「我們把她叫來問問她。」","notes":["「她」：原文是「她的口」。"]},{"n":58,"t":"他們就叫了利百加來，對她說：「你和這人同去嗎？」她說：「我去。」","notes":[]},{"n":59,"t":"於是他們送他們的妹妹利百加和她的奶媽，同亞伯拉罕的僕人，以及隨從他的人走了。","notes":[]},{"n":60,"t":"他們就為利百加祝福，對她說：「我們的妹妹啊，願你作千萬人的母親！願你的後裔得著仇敵的城門！」","notes":[]},{"n":61,"t":"利百加和她的女僕們起來，騎上駱駝，跟著那人去。僕人就帶著利百加走了。","notes":[]},{"n":62,"t":"那時，以撒住在尼革夫。他剛從庇耳‧拉海‧萊回來。","notes":[]},{"n":63,"t":"傍晚時，以撒出來，到田間默想。他舉目一看，看哪，來了一隊駱駝。","notes":[]},{"n":64,"t":"利百加舉目看見以撒，就急忙下了駱駝，","notes":[]},{"n":65,"t":"對那僕人說：「這從田間走來迎接我們的人是誰？」僕人說：「他是我的主人。」利百加就拿面紗蓋住自己。","notes":[]},{"n":66,"t":"僕人把他所做的一切事都告訴以撒。","notes":[]},{"n":67,"t":"以撒就領利百加進了母親撒拉的帳棚，娶了她為妻，並且愛她。以撒自從母親離世以後，這才得了安慰。","notes":[]}]},"25":{"heading":"亞伯拉罕的其他後代","verses":[{"n":1,"t":"亞伯拉罕再娶了一個妻子，名叫基土拉。","notes":[]},{"n":2,"t":"她為他生了心蘭、約珊、米但、米甸、伊施巴和書亞。","notes":[]},{"n":3,"t":"約珊生了示巴和底但。底但的子孫是亞書利族、利都是族和利烏米族。","notes":[]},{"n":4,"t":"米甸的兒子是以法、以弗、哈諾、亞比大和以勒大。這些都是基土拉的子孫。","notes":[]},{"n":5,"t":"亞伯拉罕把他一切所有的都給了以撒。","notes":[]},{"n":6,"t":"至於亞伯拉罕妾的兒子，亞伯拉罕趁著自己還活著的時候把財物分給他們，打發他們離開他的兒子以撒，往東方去，直到東方之地。","notes":[]},{"n":7,"t":"這是亞伯拉罕一生的年日，他活了一百七十五年。","notes":[],"heads":["亞伯拉罕的死和安葬"]},{"n":8,"t":"亞伯拉罕壽高年邁，安享天年，息勞而終，歸到他祖先 那裏。","notes":["「他祖先」：原文是「他百姓」；下同。"]},{"n":9,"t":"他兩個兒子以撒、以實瑪利把他安葬在麥比拉洞裏。這洞在幔利的對面、赫人瑣轄的兒子以弗崙的田中，","notes":[]},{"n":10,"t":"就是亞伯拉罕向赫人買的那塊田。亞伯拉罕和他妻子撒拉都葬在那裏。","notes":[]},{"n":11,"t":"亞伯拉罕死了以後，神賜福給他的兒子以撒。以撒住在庇耳‧拉海‧萊附近。","notes":[]},{"n":12,"t":"這是撒拉的婢女、埃及人夏甲為亞伯拉罕生的兒子以實瑪利的後代。","notes":[],"heads":["以實瑪利的後代"]},{"n":13,"t":"以實瑪利兒子們的名字，按著他們後代的名字如下：以實瑪利的長子尼拜約，又有基達、亞德別、米比衫、","notes":[]},{"n":14,"t":"米施瑪、度瑪、瑪撒、","notes":[]},{"n":15,"t":"哈大、提瑪、伊突、拿非施和基底瑪。","notes":[]},{"n":16,"t":"這些都是以實瑪利的兒子們。他們的村莊和營寨按著他們命名；他們作了十二族的族長。","notes":[]},{"n":17,"t":"以實瑪利一生的歲數是一百三十七歲，斷氣而死，歸到他祖先那裏。","notes":[]},{"n":18,"t":"他的子孫住在哈腓拉，直到埃及東邊的書珥，向著亞述，在他眾弟兄的對面安頓下來。","notes":["「安頓下來」：原文是「落下」。"]},{"n":19,"t":"這是亞伯拉罕的兒子以撒的後代。亞伯拉罕生以撒。","notes":[],"heads":["以掃和雅各的出生"]},{"n":20,"t":"以撒四十歲時娶利百加為妻。利百加是巴旦‧亞蘭地的亞蘭人彼土利的女兒，是亞蘭人拉班的妹妹。","notes":[]},{"n":21,"t":"以撒因他妻子不生育，就為她祈求耶和華。耶和華應允他的祈求，他的妻子利百加就懷了孕。","notes":[]},{"n":22,"t":"胎兒們在她腹中彼此相爭，她就說：「若是如此，我為甚麼會這樣呢？」她就去求問耶和華。","notes":["「我為甚麼會這樣呢」：敘利亞譯本是「我為甚麼要活著呢」。"]},{"n":23,"t":"耶和華對她說：兩國在你腹中；兩族要從你身上分立。這族必強於那族；將來大的要服侍小的。","notes":[]},{"n":24,"t":"到了生產的日期，看哪，腹中是對雙胞胎。","notes":[]},{"n":25,"t":"先出生的身體帶紅，渾身有毛，好像皮衣；他們就給他起名叫以掃。","notes":["「以掃」與「多毛」的希伯來話發音略為相近。"]},{"n":26,"t":"隨後，以掃的弟弟也出生，他的手抓住以掃的腳跟，因此給他起名叫雅各。兩個兒子出生時，以撒六十歲。","notes":["「雅各」與「腳跟」的希伯來話發音相近。"]},{"n":27,"t":"兩個孩子漸漸長大，以掃善於打獵，常在田野；雅各為人安靜，常住在帳棚裏。","notes":[],"heads":["以掃出賣長子的名分"]},{"n":28,"t":"以撒愛以掃，因為常吃他的野味；利百加卻愛雅各。","notes":[]},{"n":29,"t":"有一天，雅各熬了湯，以掃從田野回來，疲憊不堪。","notes":[]},{"n":30,"t":"以掃對雅各說：「我累死了，請你讓我吃這紅的，這紅的湯吧！」因此以掃又叫以東。","notes":["「以東」意思是「紅」。"]},{"n":31,"t":"雅各說：「你今日把長子的名分賣給我吧。」","notes":[]},{"n":32,"t":"以掃說：「看哪，我快要死了，這長子的名分對我有甚麼用呢？」","notes":[]},{"n":33,"t":"雅各說：「你今日對我起誓吧。」以掃就向他起誓，把長子的名分賣給了雅各。","notes":[]},{"n":34,"t":"於是雅各把餅和豆湯給了以掃，以掃吃喝以後，起來走了。這樣，以掃輕看他長子的名分。","notes":[]}]},"26":{"heading":"以撒住在基拉耳","verses":[{"n":1,"t":"那地有了饑荒，不是亞伯拉罕的時候曾有過的那次饑荒，以撒就到基拉耳，非利士人的王亞比米勒那裏去。","notes":[]},{"n":2,"t":"耶和華向以撒顯現，說：「你不要下埃及去，要住在我所指示你的地。","notes":[]},{"n":3,"t":"你要寄居在這地，我必與你同在，賜福給你，因為我要將這一切的地都賜給你和你的後裔。我必堅定我向你父親亞伯拉罕所起的誓。","notes":[]},{"n":4,"t":"我要使你的後裔增多，好像天上的星，又要將這一切的地賜給你的後裔，並且地上的萬國都必因你的後裔得福，","notes":[]},{"n":5,"t":"因為亞伯拉罕聽從我的話，遵守我的吩咐、誡令、律例和教導。」","notes":[]},{"n":6,"t":"於是，以撒住在基拉耳。","notes":[]},{"n":7,"t":"那地方的人問起他的妻子，他就說：「她是我的妹妹。」原來他害怕說「我的妻子」。他想：「或許這地方的人會因利百加殺我，因為她容貌美麗。」","notes":[]},{"n":8,"t":"他在那裏住了一段很長的日子。有一天，非利士人的王亞比米勒從窗戶往外觀看，看哪，以撒在撫愛他的妻子利百加。","notes":[]},{"n":9,"t":"亞比米勒召以撒來，說：「看哪，她實在是你的妻子，你怎麼說『她是我的妹妹』呢？」以撒對他說：「因為我想，恐怕我會因她而死。」","notes":[]},{"n":10,"t":"亞比米勒說：「你向我們做的是甚麼事呢？百姓中有一個人幾乎要和你的妻子同寢，你就把我們陷在罪中了。」","notes":[]},{"n":11,"t":"於是亞比米勒命令眾百姓說：「凡侵犯這個人，或他妻子的，必要把他處死。」","notes":[]},{"n":12,"t":"以撒在那地耕種，那一年有百倍的收成。耶和華賜福給他，","notes":[]},{"n":13,"t":"他就發達，日漸昌盛，成了大富翁。","notes":[]},{"n":14,"t":"他有羊群牛群，又有許多僕人，非利士人就嫉妒他。","notes":[]},{"n":15,"t":"他父親亞伯拉罕在世的時候，他父親的僕人所挖的井，非利士人全都塞住，填滿了土。","notes":[]},{"n":16,"t":"亞比米勒對以撒說：「你離開我們去吧，因為你比我們強盛得多。」","notes":[]},{"n":17,"t":"以撒就離開那裏，在基拉耳谷支搭帳棚，住在那裏。","notes":[]},{"n":18,"t":"他父親亞伯拉罕在世的時候所挖的水井，在亞伯拉罕死後，都被非利士人塞住了，以撒就重新把井挖出來，仍照他父親所取的名為它們命名。","notes":[]},{"n":19,"t":"以撒的僕人在谷中挖井，就在那裏得了一口活水井。","notes":[]},{"n":20,"t":"基拉耳的牧人與以撒的牧人相爭，說：「這水是我們的。」以撒就給那井起名叫埃色，因為他們和他相爭。","notes":["「埃色」意思是「相爭」。"]},{"n":21,"t":"以撒的僕人又挖了一口井，他們又為這井相爭，以撒就給這井起名叫西提拿。","notes":["「西提拿」意思是「為敵」。"]},{"n":22,"t":"以撒離開那裏，又挖了一口井，他們不再為這井相爭了，他就給那井起名叫利河伯。他說：「耶和華現在給我們寬闊之地，我們必在這地興旺。」","notes":["「利河伯」意思是「寬闊」。"]},{"n":23,"t":"以撒從那裏上別是巴去。","notes":[]},{"n":24,"t":"當夜耶和華向他顯現，說：「我是你父親亞伯拉罕的神。不要懼怕，因為我與你同在，要賜福給你，也要為我僕人亞伯拉罕的緣故，使你的後裔增多。」","notes":[]},{"n":25,"t":"以撒就在那裏築了一座壇，求告耶和華的名，並且在那裏支搭帳棚；他的僕人就在那裏挖了一口井。","notes":[]},{"n":26,"t":"亞比米勒同他的顧問亞戶撒和他軍隊的元帥非各，從基拉耳來到以撒那裏。","notes":[],"heads":["以撒與亞比米勒立約"]},{"n":27,"t":"以撒對他們說：「你們既然恨我，趕我離開你們，為甚麼又到我這裏來呢？」","notes":[]},{"n":28,"t":"他們說：「我們明明看見耶和華與你同在；因此就說，讓我們雙方彼此起誓，我們跟你立約，","notes":[]},{"n":29,"t":"使你不加害我們，正如我們未曾侵犯你，素來善待你，並且送你平平安安地走。你是蒙耶和華賜福的！」","notes":[]},{"n":30,"t":"以撒為他們擺設宴席，他們就一起吃喝。","notes":[]},{"n":31,"t":"他們清早起來，彼此起誓。以撒送他們走，他們就平平安安地離開他去了。","notes":[]},{"n":32,"t":"那一天，以撒的僕人來，把挖井的消息告訴他，說：「我們得到水了。」","notes":[]},{"n":33,"t":"他就給那井起名叫示巴，因此那城名叫別是巴，直到今日。","notes":["「示巴」與「起誓」的希伯來話發音相近。","「別是巴」意思是「起誓的井」或「七井」。"]},{"n":34,"t":"以掃四十歲的時候娶了赫人比利的女兒猶滴，和赫人以倫的女兒巴實抹為妻。","notes":[],"heads":["以掃的外族妻子"]},{"n":35,"t":"她們使以撒和利百加心裏愁煩。","notes":[]}]},"27":{"heading":"以撒祝福雅各","verses":[{"n":1,"t":"以撒年老，眼睛昏花，不能看見，就叫他大兒子以掃來，對他說：「我兒。」以掃對他說：「我在這裏。」","notes":[]},{"n":2,"t":"他說：「看哪，我老了，不知道哪一天死。","notes":[]},{"n":3,"t":"現在拿你打獵的工具，就是箭囊和弓，到田野去為我打獵，","notes":[]},{"n":4,"t":"照我所愛的做成美味，拿來給我吃，好讓我在未死之前為你祝福。」","notes":[]},{"n":5,"t":"以撒對他兒子以掃說話的時候，利百加聽見了。以掃往田野去打獵，要把獵物帶回來。","notes":[]},{"n":6,"t":"利百加就對她兒子雅各說：「看哪，我聽見你父親對你哥哥以掃說：","notes":[]},{"n":7,"t":"『你去把獵物帶回來，做成美味給我吃，讓我在未死之前，在耶和華面前為你祝福。』","notes":[]},{"n":8,"t":"現在，我兒，你要聽我的話，照我所吩咐你的，","notes":[]},{"n":9,"t":"到羊群裏去，從那裏牽兩隻肥美的小山羊來給我，我就照你父親所愛的，把牠們做成美味給他。","notes":[]},{"n":10,"t":"然後，你拿到你父親那裏給他吃，好讓他在未死之前為你祝福。」","notes":[]},{"n":11,"t":"雅各對他母親利百加說：「看哪，我哥哥以掃渾身都有毛，我身上卻是光滑的；","notes":[]},{"n":12,"t":"倘若父親摸著我，我在他眼中就是騙子了。這樣，我就自招詛咒，而不是祝福。」","notes":[]},{"n":13,"t":"他母親對他說：「我兒，你所受的詛咒臨到我身上吧！你只管聽我的話，去牽小山羊來給我。」","notes":[]},{"n":14,"t":"他就去牽來，交給他母親。他母親就照他父親所愛的，做成美味。","notes":[]},{"n":15,"t":"利百加把大兒子以掃在家裏最好的衣服給她小兒子雅各穿，","notes":[]},{"n":16,"t":"又用小山羊的皮包在雅各的手上和頸項光滑的地方，","notes":[]},{"n":17,"t":"就把所做的美味和餅交在她兒子雅各的手裏。","notes":[]},{"n":18,"t":"雅各來到他父親那裏，說：「我的父親！」他說：「我在這裏。我兒，你是誰？」","notes":[]},{"n":19,"t":"雅各對他父親說：「我是你的長子以掃。我已照你吩咐我的做了。請起來坐著，吃我的野味，你好為我祝福。」","notes":[]},{"n":20,"t":"以撒對他兒子說：「我兒，你怎麼這樣快就找到了呢？」他說：「因為這是耶和華—你的神使我遇見的。」","notes":[]},{"n":21,"t":"以撒對雅各說：「我兒，靠近一點，讓我摸摸你，你真的是我的兒子以掃嗎？」","notes":[]},{"n":22,"t":"雅各就靠近他父親以撒。以撒摸著他，說：「聲音是雅各的聲音，手卻是以掃的手。」","notes":[]},{"n":23,"t":"以撒認不出他來，因為他手上有毛，像他哥哥以掃的手一樣。於是，以撒就為他祝福。","notes":[]},{"n":24,"t":"以撒說：「你真的是我兒子以掃嗎？」他說：「我是。」","notes":[]},{"n":25,"t":"以撒說：「拿給我，讓我吃我兒子的野味，我好為你祝福。」雅各拿給他，他就吃了，又拿酒給他，他也喝了。","notes":[]},{"n":26,"t":"他父親以撒對他說：「我兒，靠近一點來親我！」","notes":[]},{"n":27,"t":"他就近前親吻父親。他父親一聞他衣服上的香氣，就為他祝福，說：「看，我兒的香氣好像耶和華賜福之田地的香氣。","notes":[]},{"n":28,"t":"願神賜你天上的甘露，地上的肥土，和豐富的五穀新酒。","notes":[]},{"n":29,"t":"願萬民事奉你，萬族向你下拜。願你作你弟兄的主，你母親的兒子向你下拜。詛咒你的，願他受詛咒；祝福你的，願他蒙祝福。」","notes":[]},{"n":30,"t":"以撒為雅各祝福完畢，雅各才從他父親那裏出來，他哥哥以掃正打獵回來。","notes":[],"heads":["以掃求以撒祝福"]},{"n":31,"t":"以掃也做了美味，拿來給他父親，對他父親說：「父親，請起來，吃你兒子的野味，你好為我祝福。」","notes":[]},{"n":32,"t":"他父親以撒對他說：「你是誰？」他說：「我是你的兒子，你的長子以掃。」","notes":[]},{"n":33,"t":"以撒就大大戰兢，說：「那麼，是誰打了獵物拿來給我呢？你未來之前我已經吃了，也為他祝福了，他將來就必蒙福。」","notes":[]},{"n":34,"t":"以掃聽了他父親的話，就大聲痛哭，對他父親說：「我父啊，求你也為我祝福！」","notes":[]},{"n":35,"t":"以撒說：「你弟弟已經用詭計來把你的福分奪去了。」","notes":[]},{"n":36,"t":"以掃說：「他名叫雅各，豈不是這樣嗎？他欺騙了我兩次：他先前奪了我長子的名分，看哪，他現在又奪了我的福分。」以掃又說：「你沒有留下給我的祝福嗎？」","notes":["「雅各」與「欺騙」的希伯來話發音相近。"]},{"n":37,"t":"以撒回答以掃說：「看哪，我已立他作你的主，使他的弟兄都給他作僕人，並賜他五穀新酒可以養生。我兒，那麼，現在我還能為你做甚麼呢？」","notes":[]},{"n":38,"t":"以掃對他父親說：「我父啊，你只有一個祝福嗎？我父啊，求你也為我祝福！」以掃就放聲而哭。","notes":[]},{"n":39,"t":"他父親以撒回答說：「看哪，你所住的地方必缺乏肥沃的土地，缺乏天上的甘露。","notes":["「你所住...甘露」或譯「地上的肥土必為你所住；天上的甘露必為你所得」。"]},{"n":40,"t":"你必倚靠刀劍度日，又必服侍你的兄弟；到你強盛的時候，必從你頸項上掙開他的軛。","notes":[]},{"n":41,"t":"以掃因他父親給雅各的祝福，就怨恨雅各，心裏說：「為我父親居喪的時候近了，到那時候，我要殺我的弟弟雅各。」","notes":[]},{"n":42,"t":"有人把利百加大兒子以掃的話告訴利百加，她就派人去，叫了她小兒子雅各來，對他說：「看哪，你哥哥以掃想要殺你來洩恨。","notes":[]},{"n":43,"t":"現在，我兒，聽我的話，起來，逃往哈蘭，到我哥哥拉班那裏去，","notes":[]},{"n":44,"t":"同他住一段日子，直等到你哥哥的怒氣消了。","notes":[]},{"n":45,"t":"等到你哥哥向你消了怒氣，忘了你向他所做的事，我就派人去，把你從那裏帶回來。我何必在一天之內喪失你們二人呢？」","notes":[]},{"n":46,"t":"利百加對以撒說：「我因這赫人的女子活得不耐煩了；倘若雅各也從本地女子中娶像這樣的赫人女子為妻，我為甚麼要活著呢？」","notes":[],"heads":["以撒差雅各到拉班的家"]}]},"28":{"heading":"以掃另娶一妻","verses":[{"n":1,"t":"以撒叫了雅各來，為他祝福，並吩咐他說：「你不要娶迦南的女子為妻。","notes":[]},{"n":2,"t":"你起身往巴旦‧亞蘭去，到你外祖父彼土利的家，從你舅父拉班的女兒中娶一位作你的妻子。","notes":[]},{"n":3,"t":"願全能的神賜福給你，使你生養眾多，成為許多民族，","notes":[]},{"n":4,"t":"將應許亞伯拉罕的福賜給你和你的後裔，使你承受你所寄居的地為業，就是神賜給亞伯拉罕的地。」","notes":[]},{"n":5,"t":"以撒送雅各走了，雅各就往巴旦‧亞蘭去，到亞蘭人彼土利的兒子拉班那裏，拉班是利百加的哥哥，利百加是雅各和以掃的母親。","notes":[]},{"n":6,"t":"以掃見以撒已經為雅各祝福，而且送他往巴旦‧亞蘭去，在那裏娶妻，並且見以撒祝福雅各的時候吩咐他說：「不要娶迦南的女子為妻」，","notes":[]},{"n":7,"t":"又見雅各聽從父母的話往巴旦‧亞蘭去了，","notes":[]},{"n":8,"t":"以掃就看出他父親以撒看迦南女子不順眼。","notes":[]},{"n":9,"t":"於是他往以實瑪利那裏去，在兩個妻子之外， 又娶了瑪哈拉為妻，她是亞伯拉罕兒子以實瑪利的女兒，是尼拜約的妹妹。","notes":[]},{"n":10,"t":"雅各離開別是巴，往哈蘭去。","notes":[],"heads":["雅各在伯特利做的夢"]},{"n":11,"t":"到了一個地方，因為已經日落，就在那裏過夜。他拾起那地方的一塊石頭枕在頭下，就躺在那地方。","notes":[]},{"n":12,"t":"他做夢，看哪，一個梯子立在地上，梯子的頂端直伸到天；看哪，神的使者在梯子上，上去下來。","notes":[]},{"n":13,"t":"看哪，耶和華站在梯子上面 ，說：「我是耶和華—你祖父亞伯拉罕的神，以撒的神。你現在躺臥之地，我要將它賜給你和你的後裔。","notes":["「站在梯子上面」或譯「站在他旁邊」。"]},{"n":14,"t":"你的後裔必像地上的塵沙，必向東西南北開展；地上萬族必因你和你的後裔得福。","notes":[]},{"n":15,"t":"看哪，我必與你同在，無論你往哪裏去，我必保佑你，領你歸回這地。我總不離棄你，直到我實現了對你所說的話。」","notes":[]},{"n":16,"t":"雅各睡醒了，說：「耶和華真的在這裏，我竟不知道！」","notes":[]},{"n":17,"t":"他就懼怕，說：「這地方何等可畏！這不是別的，是神的殿，是天的門。」","notes":[]},{"n":18,"t":"雅各清早起來，拿起枕在頭下的石頭，立作柱子，澆油在上面。","notes":[]},{"n":19,"t":"他給那地方起名叫伯特利 ；那地方原先名叫路斯。","notes":["「伯特利」意思是「神的殿」。"]},{"n":20,"t":"雅各許願說：「神若與我同在，在我所行的路上保佑我，給我食物吃，衣服穿，","notes":[]},{"n":21,"t":"使我平平安安回到我父親的家，我就必以耶和華為我的神。","notes":[]},{"n":22,"t":"我所立為柱子的這塊石頭必作神的殿；凡你所賜給我的，我必將十分之一獻給你。」","notes":[]}]},"29":{"heading":"雅各到拉班的家","verses":[{"n":1,"t":"雅各起行，到了東方人之地。","notes":[]},{"n":2,"t":"他觀看，看哪，田間有一口井，看哪，有三群羊臥在井旁；因為人都取那井裏的水給羊喝。井口上的那塊石頭很大。","notes":[]},{"n":3,"t":"羊群都在那裏聚集，人就把石頭移開井口，取水給羊喝，然後又把石頭放回井口原處。","notes":[]},{"n":4,"t":"雅各對他們說：「弟兄們，你們從哪裏來？」他們說：「我們是從哈蘭來的。」","notes":[]},{"n":5,"t":"他對他們說：「你們認識拿鶴的孫子拉班嗎？」他們說：「我們認識。」","notes":[]},{"n":6,"t":"雅各對他們說：「他平安嗎？」他們說：「平安。看哪，他女兒拉結和羊一起來了。」","notes":[]},{"n":7,"t":"雅各說：「看哪，日正當中，不是牲畜聚集的時候。你們取水給羊喝，再去牧放吧！」","notes":[]},{"n":8,"t":"他們說：「我們不能這樣，必須等所有的羊群聚集，人把石頭移開井口，我們才可以取水給羊喝。」","notes":[]},{"n":9,"t":"雅各正和他們說話的時候，拉結和她父親的羊來了，因為她是牧羊的。","notes":[]},{"n":10,"t":"雅各看見他舅父拉班的女兒拉結和舅父拉班的羊群，就上前把石頭移開井口，取水給舅父拉班的羊喝。","notes":[]},{"n":11,"t":"雅各親了拉結，就放聲大哭。","notes":[]},{"n":12,"t":"雅各告訴拉結，自己是她父親的親戚，是利百加的兒子。拉結就跑去告訴她父親。","notes":["「親戚」：原文是「兄弟」；下同。"]},{"n":13,"t":"拉班聽見外甥雅各的消息，就跑去迎接他，抱著他，親他，帶他到自己的家。雅各把這一切的事告訴拉班。","notes":[]},{"n":14,"t":"拉班對他說：「你實在是我的骨肉。」雅各就和他同住了一個月。","notes":[]},{"n":15,"t":"拉班對雅各說：「雖然你是我的親戚，怎麼可以讓你白白服事我呢？告訴我，你要甚麼作工資呢？」","notes":[],"heads":["雅各為拉結和利亞服事拉班"]},{"n":16,"t":"拉班有兩個女兒，大的名叫利亞，小的名叫拉結。","notes":[]},{"n":17,"t":"利亞的雙眼無神，拉結卻長得美貌秀麗。","notes":[]},{"n":18,"t":"雅各愛拉結，就說：「我願為你的小女兒拉結服事你七年。」","notes":[]},{"n":19,"t":"拉班說：「我把她給你，勝過給別人，你與我同住吧！」","notes":[]},{"n":20,"t":"雅各就為拉結服事了七年；他因為愛拉結，就看這七年如同幾天。","notes":[]},{"n":21,"t":"雅各對拉班說：「日期已經滿了，請把我的妻子給我，我好與她同房。」","notes":[]},{"n":22,"t":"拉班就擺設宴席，請了當地所有的人。","notes":[]},{"n":23,"t":"到了晚上，拉班帶女兒利亞來送給雅各，雅各就與她同房。","notes":[]},{"n":24,"t":"拉班也把自己的婢女悉帕給女兒利亞作婢女。","notes":[]},{"n":25,"t":"到了早晨，看哪，她是利亞，雅各對拉班說：「你向我做的是甚麼事呢？我服事你，不是為拉結嗎？你為甚麼欺騙我呢？」","notes":[]},{"n":26,"t":"拉班說：「大女兒還沒有給人就先把小女兒給人，我們這地方沒有這樣的規矩。","notes":[]},{"n":27,"t":"你先為這個滿了七日，我們就把那個也給你，不過你要另外再服事我七年。」","notes":[]},{"n":28,"t":"雅各就這樣做了。滿了利亞的七日，拉班就把女兒拉結給雅各為妻。","notes":[]},{"n":29,"t":"拉班又把自己的婢女辟拉給女兒拉結作婢女。","notes":[]},{"n":30,"t":"雅各也與拉結同房，並且愛拉結勝過愛利亞，於是他又服事了拉班七年。","notes":[]},{"n":31,"t":"耶和華見利亞失寵，就使她生育，拉結卻不生育。","notes":["「失寵」：原文是「被恨」；下同。"],"heads":["雅各的兒女"]},{"n":32,"t":"利亞懷孕生子，給他起名叫呂便，因為她說：「耶和華看見我的苦情，如今我的丈夫必愛我。」","notes":["「呂便」意思是「看見兒子」。"]},{"n":33,"t":"她又懷孕生子，給他起名叫西緬，說：「耶和華因為聽見我失寵，所以又賜給我這個兒子。」","notes":["「西緬」意思是「聽見」。"]},{"n":34,"t":"她又懷孕生子，說：「我給丈夫生了三個兒子，現在，這次他必親近我了。」因此，雅各給他起名叫利未。","notes":["「利未」意思是「親近」。"]},{"n":35,"t":"她又懷孕生子，說：「這次我要讚美耶和華。」因此給他起名叫猶大。於是她停了生育。","notes":["「猶大」意思是「讚美」。"]}]},"30":{"heading":"雅各和拉班定工資","verses":[{"n":1,"t":"拉結見自己不給雅各生孩子，就嫉妒她姊姊，對雅各說：「你給我孩子，不然，讓我死了吧。」","notes":[]},{"n":2,"t":"雅各對拉結生氣，說：「是我代替神使你生不出孩子的嗎？」","notes":[]},{"n":3,"t":"拉結說：「看哪，我的使女辟拉在這裏，你可以與她同房，使她生子歸在我膝下，我也可以藉著她得孩子。」","notes":["「得孩子」：原文是「被建立」。"]},{"n":4,"t":"拉結就把她的婢女辟拉給丈夫為妾，雅各與她同房。","notes":[]},{"n":5,"t":"辟拉懷孕，為雅各生了一個兒子。","notes":[]},{"n":6,"t":"拉結給他起名叫但，說：「神為我伸冤，也聽了我的聲音，賜給我一個兒子。」","notes":["「但」意思是「伸冤、審判」。"]},{"n":7,"t":"拉結的婢女辟拉又懷孕，為雅各生了第二個兒子。","notes":[]},{"n":8,"t":"拉結給他起名叫拿弗他利，說：「我與我姊姊大大較力，並且得勝了。」","notes":["「拿弗他利」意思是「較力」。"]},{"n":9,"t":"利亞見自己停了生育，就把她的婢女悉帕給雅各為妾。","notes":[]},{"n":10,"t":"利亞的婢女悉帕為雅各生了一個兒子。","notes":[]},{"n":11,"t":"利亞給他起名叫迦得，說：「真是幸運！」","notes":["「迦得」意思是「幸運」。"]},{"n":12,"t":"利亞的婢女悉帕又為雅各生了第二個兒子。","notes":[]},{"n":13,"t":"利亞給他起名叫亞設，說：「我真有福啊，眾女子都要稱我有福。」","notes":["「亞設」意思是「有福」。"]},{"n":14,"t":"收割麥子的時候，呂便到田裏去，找到曼陀羅草，就拿給他的母親利亞。拉結對利亞說：「請你給我一些你兒子的曼陀羅草吧。」","notes":["「曼陀羅草」或譯「愛情花」；下同。"]},{"n":15,"t":"利亞對她說：「你奪走了我的丈夫還是小事嗎？你還要奪取我兒子的曼陀羅草嗎？」拉結說：「今夜他可以與你同寢，來交換你兒子的曼陀羅草。」","notes":[]},{"n":16,"t":"到了晚上，雅各從田裏回來，利亞出來迎接他，說：「你要與我同寢，因為我真的用我兒子的曼陀羅草把你雇下了。」那一夜，雅各就與她同寢。","notes":[]},{"n":17,"t":"神應允了利亞，她就懷孕，為雅各生了第五個兒子。","notes":[]},{"n":18,"t":"利亞給他起名叫以薩迦，說：「神給了我工價，因為我把婢女給了我的丈夫。」","notes":["「以薩迦」意思是「工價」。"]},{"n":19,"t":"利亞又懷孕，為雅各生了第六個兒子。","notes":[]},{"n":20,"t":"利亞給他起名叫西布倫，說：「神賜給我厚禮了；這次，我丈夫必看重我，因為我為他生了六個兒子。」","notes":["「西布倫」意思是「看重、同住」。"]},{"n":21,"t":"後來她又生了一個女兒，給她起名叫底拿。","notes":[]},{"n":22,"t":"神顧念拉結，應允她，使她能生育。","notes":[]},{"n":23,"t":"拉結懷孕生子，說：「神除去了我的羞恥。」","notes":[]},{"n":24,"t":"拉結就給他起名叫約瑟，說：「願耶和華再增添一個兒子給我。」","notes":["「約瑟」意思是「增添」。"]},{"n":25,"t":"拉結生約瑟之後，雅各對拉班說：「請讓我走，回到我的本鄉本土去。","notes":[]},{"n":26,"t":"請你把我服事你所得的妻子和孩子給我，讓我走吧！我怎樣服事你，你都知道。」","notes":[]},{"n":27,"t":"拉班對他說：「願你看得起我，因我占卜得知，耶和華賜福給我是因你的緣故。」","notes":[]},{"n":28,"t":"又說：「請為我定你的工資，我就給你。」","notes":[]},{"n":29,"t":"雅各對他說：「我怎樣服事你，你的牲畜在我這裏變得怎樣，你都知道。","notes":[]},{"n":30,"t":"我未來以前，你擁有的很少，現在卻已大量增加，因為耶和華隨著我的腳步賜福給你。現在，我到甚麼時候才可以成家立業呢？」","notes":[]},{"n":31,"t":"拉班說：「我該給你甚麼呢？」雅各說：「你甚麼也不必給我，只要你為我做這件事，我就繼續牧放你的羊群。","notes":[]},{"n":32,"t":"今天我要走遍你的羊群，把綿羊中凡有點的、有斑的，和小綿羊中凡是黑色的羊；以及山羊中凡有斑的、有點的，都從那裏挑出來，作為我的工資。","notes":[]},{"n":33,"t":"以後你來當面查看我的工資，任何我這裏的山羊不是有點有斑的，小綿羊不是黑色的，就算是我偷的。這就可以證明我是正直的。」","notes":[]},{"n":34,"t":"拉班說：「看哪，就照你所說的做吧。」","notes":[]},{"n":35,"t":"當日，拉班把有紋的、有斑的公山羊，一切有點的、有斑的、有少許白色的母山羊，以及小綿羊中所有黑色的，都挑出來，交在他兒子們的手裏，","notes":["「白色」與「拉班」的希伯來文同字。","「所有黑色的」或譯「全黑的」；40節同。"]},{"n":36,"t":"又使自己和雅各相隔三天的路程。雅各就牧放拉班其餘的羊。","notes":[]},{"n":37,"t":"雅各拿楊樹、杏樹、楓樹的嫩枝，把皮剝出白色的條紋，使枝子露出白色來。","notes":[]},{"n":38,"t":"他把剝了皮的枝子對著羊群，插在羊喝水的水溝和水槽裏。羊來喝水的時候，牠們彼此交配。","notes":[]},{"n":39,"t":"羊對著枝子交配，就生下有紋的、有點的、有斑的來。","notes":[]},{"n":40,"t":"雅各把小綿羊分出來，讓羊對著拉班羊群中有紋的和所有黑色的。於是他把自己的羊群分開，不叫牠們和拉班的羊混在一起。","notes":[]},{"n":41,"t":"當肥壯的羊交配的時候，雅各就把枝子插在水溝裏，使羊對著枝子交配。","notes":[]},{"n":42,"t":"可是當瘦弱的羊交配的時候，他就不插枝子。這樣，瘦弱的就歸拉班，肥壯的就歸雅各。","notes":[]},{"n":43,"t":"於是這人極其發達，擁有許多的羊群、奴僕、婢女、駱駝和驢。","notes":[]}]},"31":{"heading":"雅各逃離拉班","verses":[{"n":1,"t":"雅各聽見拉班兒子們的話，說：「雅各把我們父親所有的都奪去了！他從我們父親所擁有的獲得這一切的財富。」","notes":[]},{"n":2,"t":"雅各見拉班的臉色，看哪，待他不如從前了。","notes":[]},{"n":3,"t":"耶和華對雅各說：「你要回你祖先之地，到你本族那裏去，我必與你同在。」","notes":[]},{"n":4,"t":"雅各就派人叫拉結和利亞到田野他的羊群那裏去，","notes":[]},{"n":5,"t":"對她們說：「我看你們父親待我的臉色不如從前了，但我父親的神向來與我同在。","notes":[]},{"n":6,"t":"你們也知道，我盡了全力服事你們的父親。","notes":[]},{"n":7,"t":"可是你們的父親欺騙我，十次更改我的工資，但神不容許他害我。","notes":[]},{"n":8,"t":"他若說：『有點的歸給你作工資』，羊群所生的都是有點的；他若說：『有紋的歸給你作工資』，羊群所生的都是有紋的。","notes":[]},{"n":9,"t":"這樣，神把你們父親的牲畜拿來賜給我了。","notes":[]},{"n":10,"t":"「羊群交配的時候，我在夢中舉目一看，看哪，跳母羊的公羊都是有紋的、有點的、有花斑的。","notes":[]},{"n":11,"t":"神的使者在夢中呼叫我說：『雅各。』我說：『我在這裏。』","notes":[]},{"n":12,"t":"他說：『你舉目觀看，跳母羊的公羊都是有紋的、有點的、有花斑的。拉班向你所做的一切，我都看見了。","notes":[]},{"n":13,"t":"我是伯特利的神；你曾在那裏用油膏過柱子，向我許過願。現在你起來，離開這地，回你本族之地去吧！』」","notes":[]},{"n":14,"t":"拉結和利亞回答雅各說：「在我們父親家裏還有我們可分得的產業嗎？","notes":[]},{"n":15,"t":"我們不是被他看作外人嗎？因為他賣了我們，還吞吃了我們的銀錢。","notes":[]},{"n":16,"t":"神從我們父親所拿走的一切財物，都是我們和我們孩子的。現在，凡神所吩咐你的，你只管去做吧！」","notes":[]},{"n":17,"t":"雅各起來，叫他的孩子和妻子都騎上駱駝，","notes":[]},{"n":18,"t":"又趕著他一切的牲畜和他所得的一切財物，就是他在巴旦‧亞蘭所得的，他擁有的牲畜，往迦南地他父親以撒那裏去了。","notes":["「又趕著他一切的牲畜...他擁有的牲畜」：七十士譯本是「又帶著他擁有的一切和所有的家具，都是他在美索不達米亞獲得的」。"]},{"n":19,"t":"當時拉班去剪羊毛，拉結偷了他父親家中的神像。","notes":[]},{"n":20,"t":"雅各瞞住亞蘭人拉班，不通知他就逃走了。","notes":[]},{"n":21,"t":"雅各帶著他所有的逃走了；他起程，渡過大河，面向著基列山。","notes":[]},{"n":22,"t":"到第三天，有人告訴拉班，雅各逃跑了。","notes":[],"heads":["拉班追趕雅各"]},{"n":23,"t":"拉班帶著他的弟兄們去追他，追了七天，就在基列山追上了。","notes":[]},{"n":24,"t":"夜間，神來到亞蘭人拉班那裏，在夢中對他說：「你要小心，不可對雅各說好說歹。」","notes":[]},{"n":25,"t":"拉班追上雅各。雅各在山上支搭帳棚；拉班和他的弟兄們也在基列山上支搭帳棚。","notes":[]},{"n":26,"t":"拉班對雅各說：「你做的是甚麼事呢？你瞞著我把我的女兒們帶走，好像用刀劍擄去一般。","notes":[]},{"n":27,"t":"你為甚麼暗暗地逃跑，瞞著我，不通知我一聲，叫我可以歡樂、唱歌、擊鼓、彈琴送你回去呢？","notes":[]},{"n":28,"t":"為甚麼不容許我與外孫和女兒吻別呢？你現在所做的真是愚蠢！","notes":[]},{"n":29,"t":"我的手本有能力害你，只是你父親的神昨夜對我說：『你要小心，不可對雅各說好說歹。』","notes":[]},{"n":30,"t":"現在你既然這麼想念你的父家，不得不去，為甚麼又偷了我的神明呢？」","notes":[]},{"n":31,"t":"雅各回答拉班說：「因為我害怕，我想，恐怕你把你的女兒從我這裏奪走。","notes":[]},{"n":32,"t":"至於你的神明，你若在誰那裏搜出來，就不讓誰活。當著我們弟兄面前，你認一認在我這裏有甚麼東西是你的，你就拿去吧。」原來雅各並不知道拉結偷了神明。","notes":[]},{"n":33,"t":"拉班進了雅各、利亞，以及兩個使女的帳棚，卻沒有找到，就從利亞的帳棚出來，進入拉結的帳棚。","notes":[]},{"n":34,"t":"拉結拿了神像，藏在駱駝的鞍子裏，自己坐在上面。拉班搜遍了那帳棚，並沒有找到。","notes":[]},{"n":35,"t":"拉結對她父親說：「請我主不要生氣，因為我恰有月事，不能在你面前起來。」拉班搜尋，卻找不到神像。","notes":[]},{"n":36,"t":"於是雅各發怒，斥責拉班。雅各對拉班說：「我有甚麼過犯，有甚麼罪惡，你竟這樣火速地追我？","notes":[]},{"n":37,"t":"你搜遍了我一切的物件，你找到甚麼呢？可以放在你我弟兄面前，叫他們在我們兩個之間評評理。","notes":[]},{"n":38,"t":"我在你那裏這二十年，你的母綿羊、母山羊沒有掉過胎。你羊群中的公綿羊，我沒有吃過；","notes":[]},{"n":39,"t":"被野獸撕裂的，我沒有帶來給你，是我自己賠償的。無論是白日被偷的，或是黑夜被偷的，你都從我手中索取。","notes":[]},{"n":40,"t":"我常常白日受盡炎熱，黑夜受盡寒霜，不得合眼入睡。","notes":[]},{"n":41,"t":"我這二十年在你家裏，為你兩個女兒服事了你十四年，為你的羊群服事了你六年，你卻十次更改我的工資。","notes":[]},{"n":42,"t":"若不是我父親以撒所敬畏的神，就是亞伯拉罕的神與我同在，你如今必定打發我空手而去。神看見我的苦情和我手的辛勞，就在昨夜責備了你。」","notes":[]},{"n":43,"t":"拉班回答雅各說：「這兩個女兒是我的女兒，這些孩子是我的孩子，這些羊群也都是我的羊群；凡你所看見的都是我的。我的女兒和她們所生的孩子，我今日還能對他們做甚麼呢？","notes":[],"heads":["雅各和拉班立約"]},{"n":44,"t":"現在，來吧！讓我和你立約，作你我之間的證據。」","notes":[]},{"n":45,"t":"雅各就拿一塊石頭立作柱子，","notes":[]},{"n":46,"t":"對弟兄們說：「大家來堆積石頭。」他們拿石頭堆成一堆，於是在那裏，在石堆旁邊吃喝。","notes":[]},{"n":47,"t":"拉班稱那石堆為伊迦爾‧撒哈杜他，雅各卻稱那石堆為迦累得 。","notes":["「伊迦爾‧撒哈杜他」是亞蘭文，「迦累得」是希伯來文，都是「石堆為證」的意思。"]},{"n":48,"t":"拉班說：「今日這石堆成為你我之間的證據。」因此這地方名叫迦累得，","notes":[]},{"n":49,"t":"又叫米斯巴，因為他說：「我們彼此離別以後，願耶和華在你我中間鑒察 。","notes":["「鑒察」與「米斯巴」的希伯來話發音相近。"]},{"n":50,"t":"你若苦待我的女兒，或在我的女兒以外另娶妻，雖沒有人在場，你看，有神在你我中間作證。」","notes":[]},{"n":51,"t":"拉班又對雅各說：「看哪，這石堆，看哪，這柱子，是我在你我中間所立的。","notes":[]},{"n":52,"t":"這石堆是證據，這柱子也是證據。我必不越過這石堆去害你；你也不可越過這石堆和柱子來害我。","notes":[]},{"n":53,"t":"願亞伯拉罕的神和拿鶴的神，就是他們父親的神，在你我中間判斷。」雅各就指著他父親以撒所敬畏的神起誓，","notes":["有些古卷和七十士譯本沒有「就是他們父親的神」。"]},{"n":54,"t":"又在山上獻祭，請弟兄們來吃飯。他們吃了飯，就在山上過夜。","notes":[]},{"n":55,"t":"拉班清早起來，與他外孫和女兒親吻，為他們祝福，就回到自己的地方去了。","notes":[]}]},"32":{"heading":"雅各準備迎見以掃","verses":[{"n":1,"t":"雅各繼續行路，神的使者遇見他。","notes":[]},{"n":2,"t":"雅各看見他們就說：「這是神的軍營。」於是給那地方起名叫瑪哈念 。","notes":["「瑪哈念」意思是「兩個軍營」。"]},{"n":3,"t":"雅各派使者在他前面到西珥地，就是以東地他哥哥以掃那裏。","notes":[]},{"n":4,"t":"他吩咐他們說：「你們要對我主以掃說：『你的僕人雅各這樣說：我在拉班那裏寄居，延遲到如今。","notes":[]},{"n":5,"t":"我有牛、驢、羊群、奴僕、婢女，現在派人來報告我主，為了要在你眼前蒙恩。』」","notes":[]},{"n":6,"t":"使者回到雅各那裏，說：「我們到了你哥哥以掃那裏。他正迎著你來，並且有四百人和他一起。」","notes":[]},{"n":7,"t":"雅各就很懼怕，而且愁煩。他把跟他同行的人和羊群、牛群、駱駝分成兩隊，","notes":[]},{"n":8,"t":"說：「以掃若來擊殺其中一隊，剩下的另一隊還可以逃脫。」","notes":[]},{"n":9,"t":"雅各說：「耶和華—我祖父亞伯拉罕的神，我父親以撒的神啊，你曾對我說：『回你本地本族去，我要厚待你。』","notes":[]},{"n":10,"t":"你向僕人所施的一切慈愛和信實，我一點也不配得。我先前只用我的一根杖過這約旦河，如今我卻成了兩隊。","notes":[]},{"n":11,"t":"求你救我脫離我哥哥的手，脫離以掃的手，因為我怕他來殺我，連母親和兒女都不放過。","notes":[]},{"n":12,"t":"你曾說：『我必定厚待你，使你的後裔如同海邊的沙，多得不可勝數。』」","notes":[]},{"n":13,"t":"當夜，雅各在那裏住宿，就從他手中所擁有的拿禮物要送給他哥哥以掃，","notes":[]},{"n":14,"t":"就是二百隻母山羊、二十隻公山羊、二百隻母綿羊、二十隻公綿羊、","notes":[]},{"n":15,"t":"三十匹哺乳的母駱駝和牠們的小駱駝、四十頭母牛、十頭公牛、二十匹母驢和十匹公驢。","notes":[]},{"n":16,"t":"他把每種牲畜各分一群，交在僕人手中，對僕人說：「你們要在我的前頭過去，使群和群之間保持一段距離」。","notes":[]},{"n":17,"t":"他又吩咐領頭的人說：「我哥哥以掃遇見你的時候，問你說：『你是誰的人？要往哪裏去？你前面這些是誰的？』","notes":[]},{"n":18,"t":"你就說：『是你僕人雅各的，是送給我主以掃的禮物。看哪，他自己也在我們後面。』」","notes":[]},{"n":19,"t":"他又吩咐第二、第三和所有趕畜群的人說：「你們遇見以掃的時候要照這樣的話對他說，","notes":[]},{"n":20,"t":"你們還要說：『看哪，你僕人雅各在我們後面。』」因雅各說：「我藉著在我前面送去的禮物給他面子，然後再見他的面，或許他會寬容我。」","notes":[]},{"n":21,"t":"於是禮物在他前面過去了；那夜，雅各在營中住宿。","notes":[]},{"n":22,"t":"他夜間起來，帶著兩個妻子，兩個婢女和十一個孩子，過了雅博渡口。","notes":[],"heads":["雅各在毗努伊勒摔跤"]},{"n":23,"t":"他帶著他們，送他們過河，他所有的一切也都過去，","notes":[]},{"n":24,"t":"只剩下雅各一人。有一個人來和他摔跤，直到黎明。","notes":[]},{"n":25,"t":"那人見自己勝不過他，就摸了他的大腿窩一下。雅各的大腿窩就在和那人摔跤的時候扭了。","notes":[]},{"n":26,"t":"那人說：「天快亮了，讓我走吧！」雅各說：「你不給我祝福，我就不讓你走。」","notes":[]},{"n":27,"t":"那人說：「你叫甚麼名字？」他說：「雅各。」","notes":[]},{"n":28,"t":"那人說：「你的名字不要再叫雅各，要叫以色列，因為你與神和人較力，都得勝了。」","notes":[]},{"n":29,"t":"雅各問他說：「請告訴我你的名字。」那人說：「何必問我的名字呢？」於是他在那裏為雅各祝福。","notes":[]},{"n":30,"t":"雅各就給那地方起名叫毗努伊勒 ，說：「我面對面見了神，我的性命仍得保全。」","notes":["「毗努伊勒」意思是「神之面」。"]},{"n":31,"t":"太陽剛出來的時候，雅各經過毗努伊勒，他的大腿就瘸了。","notes":[]},{"n":32,"t":"因此，以色列人不吃大腿窩的筋，直到今日，因為那人摸了雅各大腿窩的筋。","notes":[]}]},"33":{"heading":"雅各和以掃相見","verses":[{"n":1,"t":"雅各舉目觀看，看哪，以掃來了，有四百人和他一起。雅各就把孩子們分開交給利亞、拉結和兩個婢女。","notes":[]},{"n":2,"t":"他叫兩個婢女和她們的孩子走在前頭，利亞和她的孩子跟在後面，而拉結和約瑟在最後。","notes":[]},{"n":3,"t":"他自己卻走到他們前面，一連七次俯伏在地才挨近他哥哥。","notes":[]},{"n":4,"t":"以掃跑來迎接他，將他抱住，伏在他的頸項上親他，他們都哭了。","notes":[]},{"n":5,"t":"以掃舉目看見婦人和孩子，就說：「這些和你一起的是誰呢？」雅各說：「這些孩子是神施恩給你僕人的。」","notes":[]},{"n":6,"t":"於是兩個婢女和她們的孩子前來下拜，","notes":[]},{"n":7,"t":"利亞和她的孩子也前來下拜，隨後約瑟和拉結也前來下拜。","notes":[]},{"n":8,"t":"以掃說：「我所遇見的這些畜群是甚麼意思呢？」雅各說：「是為了要在我主眼前蒙恩。」","notes":[]},{"n":9,"t":"以掃說：「弟弟啊，我的已經夠了，你的你自己留著吧！」","notes":[]},{"n":10,"t":"雅各說：「不，我若在你眼前蒙恩，就請你從我手裏收下這禮物；因為我見了你的面，如同見了神的面，並且你也寬容了我。","notes":[]},{"n":11,"t":"請你收下我帶來給你的禮物，因為神恩待我，使我一切都充足。」雅各再三求他，他才收下。","notes":[]},{"n":12,"t":"以掃說：「讓我們起身前行，我和你一起走吧。」","notes":[]},{"n":13,"t":"雅各對他說：「我主知道孩子們還年幼嬌嫩，我的牛羊也正在哺乳中，只要催趕一天，群羊都會死了。","notes":[]},{"n":14,"t":"請我主在僕人前面先走，我要按著在我面前的牲畜和孩子的步伐慢慢前進，直走到西珥我主那裏。」","notes":[]},{"n":15,"t":"以掃說：「讓我把跟隨我的人留幾個在你這裏。」雅各說：「何必這樣呢？只要能在我主眼前蒙恩就夠了。」","notes":[]},{"n":16,"t":"於是，以掃當日起行，回西珥去了。","notes":[]},{"n":17,"t":"雅各就往疏割去，在那裏為自己蓋房屋，又為牲畜搭棚，因此那地方叫疏割 。","notes":["「疏割」意思是「棚」。"]},{"n":18,"t":"雅各從巴旦‧亞蘭平安地回到迦南地的示劍城，他在城的前面支搭帳棚。","notes":[]},{"n":19,"t":"他用一百可錫塔從示劍的父親哈抹的眾子手中買了搭帳棚的那塊地。","notes":["「可錫塔」：古希伯來錢幣單位；參「度量衡表」。"]},{"n":20,"t":"雅各在那裏築了一座壇，起名叫伊利‧伊羅伊‧以色列。","notes":["「伊利‧伊羅伊‧以色列」意思是「神─以色列的神」。"]}]},"34":{"heading":"底拿受辱","verses":[{"n":1,"t":"利亞給雅各所生的女兒底拿出去，要探望那地的女子們。","notes":[]},{"n":2,"t":"那地的族長希未人哈抹的兒子示劍看見她，就拉住她，與她同寢，玷辱了她。","notes":[]},{"n":3,"t":"示劍的心喜歡雅各的女兒底拿，愛上這少女，甜言蜜語地安慰她。","notes":[]},{"n":4,"t":"示劍對他父親哈抹說：「求你為我聘這女孩為妻。」","notes":[]},{"n":5,"t":"雅各聽見示劍污辱了他的女兒底拿。那時他的兒子們正和牲畜在田野，雅各就沉默，等他們回來。","notes":[]},{"n":6,"t":"示劍的父親哈抹出來，到雅各那裏，要和他講話。","notes":[]},{"n":7,"t":"雅各的兒子們聽見這事，就從田野回來，人人悲憤，十分惱怒，因示劍在以色列中做了醜事，與雅各的女兒同寢，這本是不該做的事。","notes":[]},{"n":8,"t":"哈抹和他們談話，說：「我兒子示劍的心喜歡你們家的女兒，請你們把她嫁給我的兒子。","notes":[]},{"n":9,"t":"你們與我們彼此結親；你們可以把你們家的女兒嫁給我們，也可以娶我們家的女兒。","notes":[]},{"n":10,"t":"你們與我們同住吧！這地都在你們面前，只管在這裏居住，做買賣，置產業。」","notes":[]},{"n":11,"t":"示劍對女子的父親和兄弟們說：「願你們看得起我，你們向我要甚麼，我必給你們，","notes":[]},{"n":12,"t":"無論向我要多貴重的聘金和禮物，我必照你們所說的給你們，只要你們將這少女嫁給我。」","notes":[]},{"n":13,"t":"雅各的兒子們因示劍污辱了他們的妹妹底拿，就用詭詐的話回答示劍和他父親哈抹，","notes":[]},{"n":14,"t":"對他們說：「我們不能做這樣的事，把我們的妹妹嫁給沒有受割禮的人為妻，因為那是我們的羞恥。","notes":[]},{"n":15,"t":"惟有一個條件，我們才答應你們，就是你們所有的男丁都要受割禮，和我們一樣，","notes":[]},{"n":16,"t":"我們就把我們家的女兒嫁給你們，也娶你們家的女兒；我們就與你們同住，大家成為一族人。","notes":[]},{"n":17,"t":"倘若你們不聽從我們受割禮，我們就帶我們家的女兒走了。」","notes":[]},{"n":18,"t":"這些話在哈抹和他兒子示劍的眼中看為美。","notes":[]},{"n":19,"t":"那年輕人毫不遲延做這事，因為他愛上了雅各的女兒；他在他父親家中也是最受人尊重的。","notes":[]},{"n":20,"t":"哈抹和他兒子示劍到他們的城門口，對城裏的人講說：","notes":[]},{"n":21,"t":"「這些人對我們友善，不如允許他們在這地居住，做買賣；看哪，這地寬闊，足以容納他們。我們可以娶他們家的女兒，也可以把我們家的女兒嫁給他們。","notes":[]},{"n":22,"t":"惟有一個條件，這些人才答應和我們同住，成為一族人，就是我們中間所有的男丁都要受割禮，和他們一樣。","notes":[]},{"n":23,"t":"他們的牲畜、財物和一切的牲口豈不都歸給我們嗎？只要答應他們，他們就與我們同住。」","notes":[]},{"n":24,"t":"凡從城門出入的人都聽從了哈抹和他兒子示劍的話。於是，凡從城門出入的男丁都受了割禮。","notes":[]},{"n":25,"t":"到第三天，他們正疼痛的時候，雅各的兩個兒子，就是底拿的哥哥西緬和利未，各拿刀劍，不動聲色地來到城中，把所有的男丁都殺了，","notes":[]},{"n":26,"t":"又用刀殺了哈抹和他兒子示劍，把底拿從示劍家裏帶走，就離開了。","notes":[]},{"n":27,"t":"雅各的兒子們因為他們的妹妹受污辱，就來到被殺的人那裏，洗劫那城，","notes":[]},{"n":28,"t":"奪走了他們的羊群、牛群和驢，以及城裏和田間所有的；","notes":[]},{"n":29,"t":"又俘擄搶劫他們一切的財物、孩童、婦女，以及房屋中所有的。","notes":[]},{"n":30,"t":"雅各對西緬和利未說：「你們連累了我，使我在這地的居民中，就是在迦南人和比利洗人中壞了名聲。我的人丁稀少，他們必聚集來擊殺我，我和全家的人都要被滅絕。」","notes":[]},{"n":31,"t":"他們卻說：「他豈可待我們的妹妹如同妓女呢？」","notes":[]}]},"35":{"heading":"神在伯特利賜福雅各","verses":[{"n":1,"t":"神對雅各說：「起來！上伯特利去，住在那裏。在那裏築一座壇給神，就是你逃避你哥哥以掃的時候向你顯現的神。」","notes":[]},{"n":2,"t":"雅各就對他家中的人，以及所有和他一起的人說：「除掉你們中間外邦的神明，要自潔，更換衣服。","notes":[]},{"n":3,"t":"我們要起來，上伯特利去，在那裏我要築一座壇給神，就是在我遭難的日子應允我，在我行走的路上與我同在的神。」","notes":[]},{"n":4,"t":"他們就把手中所有外邦的神明和自己耳朵上的環子交給雅各；雅各把它們埋在示劍那裏的橡樹下。","notes":[]},{"n":5,"t":"他們起行。神使周圍城鎮的人都驚恐，就不追趕雅各的兒子們了。","notes":[]},{"n":6,"t":"於是雅各和所有與他一起的人到了迦南地的路斯，就是伯特利。","notes":[]},{"n":7,"t":"他在那裏築了一座壇，給那地方起名叫伊勒‧伯特利，因為他逃避他哥哥的時候，神曾在那裏向他顯現。","notes":["「伊勒‧伯特利」意思是「伯特利之神」。"]},{"n":8,"t":"利百加的奶媽底波拉死了，葬在伯特利下邊的橡樹下；那棵樹名叫亞倫‧巴古。","notes":[]},{"n":9,"t":"雅各從巴旦‧亞蘭回來，神又向他顯現，賜福給他。","notes":[]},{"n":10,"t":"神對他說：「你的名原是雅各，從今以後不要再叫雅各，你的名要叫以色列。」於是，神就叫他的名為以色列。","notes":[]},{"n":11,"t":"神又對他說：「我是全能的神；你要生養眾多，將來有一國和許多的國從你而來，又有許多君王從你生出。","notes":["「從你生出」：原文是「從你腰間而出」。"]},{"n":12,"t":"至於我賜給亞伯拉罕和以撒的地，我必賜給你；我必賜這地給你的後裔。」","notes":[]},{"n":13,"t":"神就從與雅各說話的那地方升上去了。","notes":[]},{"n":14,"t":"雅各就在神與他說話的地方立了一根柱子，就是石柱，在它上面獻澆酒祭，又澆油。","notes":[]},{"n":15,"t":"雅各就給神與他說話的那地方起名叫伯特利。","notes":[]},{"n":16,"t":"他們從伯特利起行，到以法他還有一段路程，拉結生產，生得十分艱難。","notes":[],"heads":["拉結去世"]},{"n":17,"t":"她生得十分艱難的時候，接生婆對她說：「不要怕，你又要有一個兒子了。」","notes":[]},{"n":18,"t":"她快要死，還有一口氣的時候，就給她兒子起名叫便‧俄尼；他父親卻給他起名叫便雅憫。","notes":["「便‧俄尼」意思是「我憂傷之子」。","「便雅憫」意思是「我右手之子」。"]},{"n":19,"t":"拉結死了，葬在往以法他的路旁；以法他就是伯利恆。","notes":[]},{"n":20,"t":"雅各在她的墳上立了一塊碑，就是拉結的墓碑，到今日還在。","notes":[]},{"n":21,"t":"以色列起行，在以得臺的那一邊支搭帳棚。","notes":[]},{"n":22,"t":"以色列住在那地的時候，呂便去與他父親的妾辟拉同寢，以色列也聽見了這件事。雅各共有十二個兒子。","notes":["「以色列也聽見了這件事」：七十士譯本是「以色列聽見這事，就看為惡」。"],"heads":["雅各的兒子們"]},{"n":23,"t":"利亞的兒子是雅各的長子呂便，還有西緬、利未、猶大、以薩迦、西布倫。","notes":[]},{"n":24,"t":"拉結的兒子是約瑟、便雅憫。","notes":[]},{"n":25,"t":"拉結的婢女辟拉的兒子是但、拿弗他利。","notes":[]},{"n":26,"t":"利亞的婢女悉帕的兒子是迦得、亞設。這是雅各在巴旦‧亞蘭所生的兒子。","notes":[]},{"n":27,"t":"雅各來到他父親以撒那裏，到了幔利，基列‧亞巴，就是希伯崙，是亞伯拉罕和以撒寄居的地方。","notes":[],"heads":["以撒的死"]},{"n":28,"t":"以撒共活了一百八十年。","notes":[]},{"n":29,"t":"以撒年紀老邁，安享天年，息勞而終，歸到他祖先那裏。他兩個兒子以掃和雅各把他安葬了。","notes":["「他祖先」：原文是「他百姓」。"]}]},"36":{"heading":"以掃的後代","verses":[{"n":1,"t":"這是以掃的後代，以掃就是以東。","notes":[]},{"n":2,"t":"以掃娶迦南的女子為妻，就是赫人以倫的女兒亞大和希未人祭便的孫女，亞拿的女兒阿何利巴瑪，","notes":[]},{"n":3,"t":"又娶了以實瑪利的女兒，尼拜約的妹妹巴實抹。","notes":[]},{"n":4,"t":"亞大為以掃生了以利法；巴實抹生了流珥；","notes":[]},{"n":5,"t":"阿何利巴瑪生了耶烏施、雅蘭、可拉。這些都是以掃的兒子，是在迦南地生的。","notes":[]},{"n":6,"t":"以掃帶著他的妻子、兒女和家中所有的人，以及他的牛羊、牲畜和一切財物，就是他在迦南地所得的，往別處去，離開了他的兄弟雅各。","notes":[]},{"n":7,"t":"因為他們擁有的很多，不能住在一起。因為牲畜的緣故，寄居的地方容不下他們。","notes":[]},{"n":8,"t":"於是以掃住在西珥山；以掃就是以東。","notes":[]},{"n":9,"t":"這是以掃的後代，他是西珥山裏以東人的始祖。","notes":[]},{"n":10,"t":"以掃子孫的名字如下：以掃的妻子亞大生以利法；以掃的妻子巴實抹生流珥。","notes":[]},{"n":11,"t":"以利法的兒子是提幔、阿抹、洗玻、迦坦、基納斯。","notes":[]},{"n":12,"t":"亭納是以掃兒子以利法的妾，她為以利法生了亞瑪力。這是以掃的妻子亞大的子孫。","notes":[]},{"n":13,"t":"流珥的兒子是拿哈、謝拉、沙瑪、米撒。這是以掃妻子巴實抹的子孫。","notes":[]},{"n":14,"t":"以掃的妻子阿何利巴瑪是祭便的孫女，亞拿的女兒。她為以掃生了耶烏施、雅蘭、可拉。","notes":[]},{"n":15,"t":"這是以掃子孫中作族長的：以掃的長子以利法的子孫中，有提幔族長、阿抹族長、洗玻族長、基納斯族長、","notes":[]},{"n":16,"t":"可拉族長、迦坦族長、亞瑪力族長。這是在以東地，從以利法所出的族長，是亞大的子孫。","notes":[]},{"n":17,"t":"以掃的兒子流珥的子孫中，有拿哈族長、謝拉族長、沙瑪族長、米撒族長。這是在以東地，從流珥所出的族長，是以掃妻子巴實抹的子孫。","notes":[]},{"n":18,"t":"以掃的妻子阿何利巴瑪的子孫中，有耶烏施族長、雅蘭族長、可拉族長。這是從以掃的妻子，亞拿的女兒阿何利巴瑪的子孫中所出的族長。","notes":[]},{"n":19,"t":"以上的族長都是以掃的子孫；以掃就是以東。","notes":[]},{"n":20,"t":"這是那地原來的居民，何利人西珥的子孫：羅坍、朔巴、祭便、亞拿、","notes":[],"heads":["西珥的子孫"]},{"n":21,"t":"底順、以察、底珊。這是在以東地，從何利人西珥子孫中所出的族長。","notes":[]},{"n":22,"t":"羅坍的兒子是何利、希幔，羅坍的妹妹是亭納。","notes":[]},{"n":23,"t":"朔巴的兒子是亞勒文、瑪拿轄、以巴錄、示玻、阿南。","notes":[]},{"n":24,"t":"祭便的兒子是愛亞、亞拿，當時在曠野牧放他父親祭便的驢，發現溫泉的就是這亞拿。","notes":[]},{"n":25,"t":"亞拿的兒子是底順，亞拿的女兒是阿何利巴瑪。","notes":[]},{"n":26,"t":"底順的兒子是欣但、伊是班、益蘭、基蘭。","notes":[]},{"n":27,"t":"以察的兒子是辟罕、撒番、亞干。","notes":[]},{"n":28,"t":"底珊的兒子是烏斯、亞蘭。","notes":[]},{"n":29,"t":"這是從何利人所出的族長：羅坍族長、朔巴族長、祭便族長、亞拿族長、","notes":[]},{"n":30,"t":"底順族長、以察族長、底珊族長。這是從何利人所出的族長，都在西珥地，按著族長來分。","notes":["「族長」：七十士譯本是「宗族」。"]},{"n":31,"t":"以色列未有君王治理之前，這些是在以東地作王的。","notes":[],"heads":["以東諸王"]},{"n":32,"t":"比珥的兒子比拉在以東作王，他的城名叫亭哈巴。","notes":[]},{"n":33,"t":"比拉死了，波斯拉人謝拉的兒子約巴接續他作王。","notes":[]},{"n":34,"t":"約巴死了，提幔人之地的戶珊接續他作王。","notes":[]},{"n":35,"t":"戶珊死了，比達的兒子哈達接續他作王，哈達曾在摩押地擊敗米甸人，他的城名叫亞未得。","notes":[]},{"n":36,"t":"哈達死了，瑪士利加人桑拉接續他作王。","notes":[]},{"n":37,"t":"桑拉死了，大河邊的利河伯人掃羅接續他作王。","notes":[]},{"n":38,"t":"掃羅死了，亞革波的兒子巴勒‧哈南接續他作王。","notes":[]},{"n":39,"t":"亞革波的兒子巴勒‧哈南死了，哈達爾接續他作王，他的城名叫巴烏。他的妻子名叫米希她別，是米‧薩合的孫女，瑪特列的女兒。","notes":["「哈達爾」：有古卷是「哈達」；參代上1．50。"]},{"n":40,"t":"這是以掃的族長，按著他們的宗族、住處和名字：亭納族長、亞勒瓦族長、耶帖族長、","notes":[]},{"n":41,"t":"阿何利巴瑪族長、以拉族長、比嫩族長、","notes":[]},{"n":42,"t":"基納斯族長、提幔族長、米比薩族長、","notes":[]},{"n":43,"t":"瑪基疊族長、以蘭族長。這些是以東人在所得為業的地上，按著他們住處的族長。以掃是以東人的始祖。","notes":[]}]},"37":{"heading":"約瑟和他的兄弟","verses":[{"n":1,"t":"雅各住在迦南地，就是他父親寄居的地。","notes":[]},{"n":2,"t":"這是雅各的事蹟。約瑟十七歲與他哥哥們一同牧羊。他是個少年，與他父親的妾辟拉和悉帕的兒子們常在一起。約瑟把他們的惡行報給父親。","notes":[]},{"n":3,"t":"以色列愛約瑟過於其他的兒子，因為約瑟是他年老生的；他給約瑟做了一件長袍。","notes":["「長袍」：七十士譯本和其他古譯本是「彩衣」；下同。"]},{"n":4,"t":"哥哥們見父親愛約瑟過於他們，就恨約瑟，不與他說友善的話。","notes":[]},{"n":5,"t":"約瑟做了一個夢，告訴他哥哥們，他們就更加恨他。","notes":[]},{"n":6,"t":"約瑟對他們說：「請聽我做的這個夢：","notes":[]},{"n":7,"t":"看哪，我們在田裏捆禾稼；看哪，我的捆起來站著；看哪，你們的捆圍著我的捆下拜。」","notes":[]},{"n":8,"t":"他的哥哥們對他說：「難道你真的要作我們的王嗎？難道你真的要統治我們嗎？」他們就因他的夢和他的話更加恨他。","notes":[]},{"n":9,"t":"後來他又做了另一個夢，告訴他哥哥們說：「看哪，我又做了一個夢；看哪，太陽、月亮和十一顆星都向我下拜。」","notes":[]},{"n":10,"t":"約瑟告訴他父親和哥哥們，他父親就責備他說：「你做的這是甚麼夢！難道我和你母親、你的兄弟真的要俯伏在地，來向你下拜嗎？」","notes":[]},{"n":11,"t":"他的哥哥們都嫉妒他，他父親卻把這事存在心裏。","notes":[]},{"n":12,"t":"約瑟的哥哥們到示劍去放他們父親的羊。","notes":[],"heads":["約瑟被賣到埃及"]},{"n":13,"t":"以色列對約瑟說：「你哥哥們不是在示劍放羊嗎？來，我派你到他們那裏去。」約瑟對他說：「我在這裏。」","notes":[]},{"n":14,"t":"以色列對他說：「你去看看你哥哥們是否平安，羊群是否平安，再回來告訴我。」於是他派約瑟出希伯崙谷，約瑟就往示劍去了。","notes":[]},{"n":15,"t":"有人遇見他，看哪，他在田野走迷了路。那人問他說：「你找甚麼？」","notes":[]},{"n":16,"t":"他說：「我找我的哥哥們，請告訴我，他們在哪裏放羊。」","notes":[]},{"n":17,"t":"那人說：「他們已經離開這裏走了，我聽見他們說：『我們往多坍去。』」約瑟就去追哥哥們，在多坍找到了他們。","notes":[]},{"n":18,"t":"他們遠遠看見他，趁他還沒有走近他們，就圖謀要殺死他。","notes":[]},{"n":19,"t":"他們彼此說：「看哪！那做夢的來了。","notes":[]},{"n":20,"t":"現在，來吧！我們把他殺了，丟在一個坑裏，就說有惡獸把他吃了。我們且看他的夢將來怎麼樣。」","notes":[]},{"n":21,"t":"呂便聽見了，要救約瑟脫離他們的手，說：「我們不可害他的性命。」","notes":[]},{"n":22,"t":"呂便又對他們說：「不可流他的血，可以把他丟在這曠野的坑裏，不可下手害他。」呂便要救他脫離他們的手，把他還給他父親。","notes":[]},{"n":23,"t":"約瑟到了他哥哥們那裏，他們就剝去他的外衣，就是他身上那件長袍。","notes":[]},{"n":24,"t":"他們抓住他，把他丟在坑裏。那坑是空的，裏頭沒有水。","notes":[]},{"n":25,"t":"他們坐下吃飯，舉目觀看，看哪，有一群以實瑪利人從基列來，用駱駝馱著香料、乳香、沒藥，要帶下埃及去。","notes":[]},{"n":26,"t":"猶大對他的兄弟們說：「我們殺我們的弟弟，遮掩他的血有甚麼好處呢？","notes":[]},{"n":27,"t":"來，我們把他賣給以實瑪利人，不要下手害他，因為他是我們的弟弟，我們的骨肉。」他的兄弟們就聽從了他。","notes":[]},{"n":28,"t":"那時，有些米甸的商人從那裏經過，就把約瑟從坑裏拉上來。他們以二十塊銀子把約瑟賣給以實瑪利人，他們就把約瑟帶到埃及去了。","notes":[]},{"n":29,"t":"呂便回到坑旁，看哪，約瑟不在坑裏，就撕裂自己的衣服，","notes":[]},{"n":30,"t":"回到他兄弟們那裏，說：「孩子不在了。我往哪裏去才好呢？」","notes":[]},{"n":31,"t":"於是，他們宰了一隻公山羊，拿了約瑟的那件外衣染上了血，","notes":[]},{"n":32,"t":"派人把長袍送到他們的父親那裏，說：「我們發現這個， 請認一認，是不是你兒子的外衣？」","notes":[]},{"n":33,"t":"他認出來，就說：「這是我兒子的外衣，惡獸把他吃了，約瑟一定被撕碎了！」","notes":[]},{"n":34,"t":"雅各就撕裂衣服，腰間圍上麻布，為他兒子哀傷了多日。","notes":[]},{"n":35,"t":"他的兒女都起來安慰他，他卻不肯受安慰，說：「我必哀傷著下陰間，到我兒子那裏。」約瑟的父親就為他哀哭。","notes":[]},{"n":36,"t":"米甸人把約瑟賣到埃及，給法老的官員，就是護衛長波提乏。","notes":[]}]},"38":{"heading":"猶大和她瑪","verses":[{"n":1,"t":"那時，猶大離開他兄弟們下去，到一個名叫希拉的亞杜蘭人的家附近支搭帳棚。","notes":[]},{"n":2,"t":"猶大在那裏看見一個名叫拔‧書亞的迦南女子，就娶她為妻，與她同房，","notes":[]},{"n":3,"t":"她就懷孕生了兒子，猶大給他起名叫珥。","notes":[]},{"n":4,"t":"她又懷孕生了兒子，給他起名叫俄南。","notes":[]},{"n":5,"t":"她又再生了兒子，給他起名叫示拉。她生示拉的時候，猶大正在基悉。","notes":[]},{"n":6,"t":"猶大為長子珥娶妻，名叫她瑪。","notes":[]},{"n":7,"t":"猶大的長子珥在耶和華眼中看為惡，耶和華就殺死了他。","notes":[]},{"n":8,"t":"猶大對俄南說：「你當與你哥哥的妻子同房，向她盡你的本分，為你哥哥生子立後。」","notes":[]},{"n":9,"t":"俄南知道如果與嫂嫂同房，所生的孩子不屬於自己，就洩在地上，不為哥哥生子立後。","notes":[]},{"n":10,"t":"俄南所做的在耶和華眼中看為惡，耶和華也殺死了他。","notes":[]},{"n":11,"t":"猶大對他媳婦她瑪說：「你去住在你父親家裏守寡，等我兒子示拉長大。」因為他說：「恐怕示拉也像兩個哥哥一樣死去。」她瑪就去，住在她父親家裏。","notes":[]},{"n":12,"t":"過了一段很長的日子，猶大的妻子，書亞的女兒死了。猶大受到了安慰，就和他朋友亞杜蘭人希拉上亭拿去，到他的剪羊毛的人那裏。","notes":[]},{"n":13,"t":"有人告訴她瑪說：「看哪，你的公公上亭拿剪羊毛去了。」","notes":[]},{"n":14,"t":"她瑪見示拉已經長大，卻還沒有娶她為妻，就脫去她寡婦的衣裳，用面紗蒙著，蓋住自己，坐在往亭拿的路上，伊拿印城門口。","notes":[]},{"n":15,"t":"猶大看見她，以為是妓女，因為她蒙著臉。","notes":[]},{"n":16,"t":"猶大就轉到路邊她那裏，說：「來吧！讓我與你同寢。」他並不知道她就是他的媳婦。她瑪說：「你要與我同寢，把甚麼給我呢？」","notes":[]},{"n":17,"t":"猶大說：「我從羊群裏取一隻小山羊，派人送來給你。」她瑪說：「在未送之前，你能給我一個信物嗎？」","notes":[]},{"n":18,"t":"他說：「我給你甚麼信物呢？」她瑪說：「你的印、你的帶子和你手裏的杖。」於是猶大給了她，與她同寢，她就從猶大懷了孕。","notes":["「帶子」指「繫印的帶子」；下同。"]},{"n":19,"t":"她瑪起來走了，除去面紗，照常穿上寡婦的衣裳。","notes":[]},{"n":20,"t":"猶大託他朋友亞杜蘭人送一隻小山羊去，要從那女人手裏取回信物，卻找不到她。","notes":[]},{"n":21,"t":"他問那地方的人說：「伊拿印路旁的神廟娼妓在哪裏？」他們說：「這裏沒有神廟娼妓。」","notes":[]},{"n":22,"t":"他回到猶大那裏說：「我找不到她，並且那地方的人說：『這裏沒有神廟娼妓。』」","notes":[]},{"n":23,"t":"猶大說：「讓她拿去吧，免得我們被人譏笑。看哪，我把這小山羊送去了，可是你找不到她。」","notes":[]},{"n":24,"t":"大約過了三個月，有人告訴猶大說：「你的媳婦她瑪行淫，並且，看哪，她因行淫而懷了孕。」猶大說：「拉她出來，把她燒了！」","notes":[]},{"n":25,"t":"她瑪被拉出來的時候，就派人到她公公那裏，對他說：「這些東西是誰的，我就是從誰懷了孕。」她又說：「請你認一認，這印、這帶子和這杖是誰的？」","notes":[]},{"n":26,"t":"猶大承認說：「她比我更有理，因為我沒有把她給我的兒子示拉。」猶大再也不跟她同寢。","notes":[]},{"n":27,"t":"她瑪生產的時候到了，看哪，腹裏懷的是雙胞胎。","notes":[]},{"n":28,"t":"生產的時候，一個孩子伸出手來；接生婆拿紅線綁在他手上，說：「這是頭生的。」","notes":[]},{"n":29,"t":"這孩子把手收回去，看哪，他哥哥生出來了；接生婆說：「你竟然為自己衝出一個裂縫！」於是，他的名字叫法勒斯。","notes":["「法勒斯」意思是「裂縫」。"]},{"n":30,"t":"後來，那手上有紅線的兄弟也生出來，他的名字叫謝拉。","notes":["「謝拉」意思是「明亮」，也許暗示「鮮紅」。"]}]},"39":{"heading":"約瑟和波提乏之妻","verses":[{"n":1,"t":"約瑟被帶下埃及去。有一個埃及人波提乏，是法老的官員，是護衛長，他從那些帶約瑟下來的以實瑪利人手中把約瑟買了去。","notes":[]},{"n":2,"t":"約瑟在他埃及主人的家中，耶和華與他同在，他是一個通達的人。","notes":[]},{"n":3,"t":"他主人見耶和華與他同在，又見耶和華使他手裏所辦的事都順利，","notes":[]},{"n":4,"t":"約瑟就在主人眼前蒙恩，伺候他主人，主人派他管理家務，把一切所有的都交在他手裏。","notes":[]},{"n":5,"t":"自從主人派約瑟管理家務和他一切所有的，耶和華就因約瑟的緣故賜福給那埃及人的家；凡家裏和田間一切所有的，都蒙耶和華賜福。","notes":[]},{"n":6,"t":"波提乏把他一切所有的都交在約瑟手中，除了自己所吃的食物，其他的事一概不知。約瑟英俊健美。","notes":[]},{"n":7,"t":"這些事以後，約瑟主人的妻子以目送情給約瑟，說：「你與我同寢吧！」","notes":[]},{"n":8,"t":"約瑟拒絕，對他主人的妻子說：「看哪，一切家務我主人一概不知，他把所有的都交在我手裏。","notes":[]},{"n":9,"t":"在這家裏沒有人比我更大，除你以外，他也沒有留下一樣不交給我，因為你是他的妻子。我怎能行這麼大的惡，得罪神呢？」","notes":[]},{"n":10,"t":"她天天這樣對約瑟說，約瑟卻不聽從她，不與她同寢，也不和她在一起。","notes":[]},{"n":11,"t":"有一天，約瑟進屋裏去辦事，家裏沒有一個人在那屋子裏，","notes":[]},{"n":12,"t":"婦人就拉住他的衣服，說：「你與我同寢吧！」約瑟把衣服留在她手裏，逃出外面去了。","notes":[]},{"n":13,"t":"婦人看見約瑟把衣服留在她手裏逃到外面，","notes":[]},{"n":14,"t":"就叫了家裏的人來，對他們說：「看，他帶了一個希伯來人到我們這裏戲弄我們。他到我這裏來，要與我同寢，我就大聲喊叫。","notes":[]},{"n":15,"t":"他聽見我放聲大喊，就把他的衣服留在我這裏，逃出外面去了。」","notes":[]},{"n":16,"t":"婦人把約瑟的衣服放在身邊，直到他主人回家，","notes":[]},{"n":17,"t":"就用這樣的話對他說：「你帶到我們這裏來的那希伯來僕人進來要調戲我，","notes":[]},{"n":18,"t":"我放聲大喊，他就把衣服留在我身邊，逃到外面。」","notes":[]},{"n":19,"t":"主人聽見他妻子對他說的話，說：「你的僕人就是這樣對待我」，就非常生氣。","notes":[]},{"n":20,"t":"約瑟的主人把他抓起來，關在監獄裏，就是王的囚犯被關的地方。於是約瑟在那裏坐牢。","notes":[]},{"n":21,"t":"但耶和華與約瑟同在，向他施恩，使他在監獄長的眼前蒙恩。","notes":[]},{"n":22,"t":"監獄長就把監獄裏所有的囚犯都交在約瑟手下；在那裏的一切事都由他處理。","notes":[]},{"n":23,"t":"任何交在約瑟手中的事，監獄長一概不察，因為耶和華與約瑟同在，耶和華使他所做的都順利。","notes":[]}]},"40":{"heading":"約瑟為囚犯解夢","verses":[{"n":1,"t":"這些事以後，埃及王的司酒長和司膳長得罪了他們的主埃及王。","notes":[]},{"n":2,"t":"法老就對司酒長和司膳長兩個官員發怒，","notes":[]},{"n":3,"t":"把他們關在護衛長府內的監獄裏，就是約瑟被囚的地方。","notes":[]},{"n":4,"t":"護衛長把他們交給約瑟，約瑟就伺候他們。他們被關了一段日子。","notes":[]},{"n":5,"t":"關在監獄裏的這兩個人，就是埃及王的司酒長和司膳長，在同一個晚上各自做了一個夢，每個夢都有自己的解釋。","notes":[]},{"n":6,"t":"到了早晨，約瑟來到他們那裏看他們，看哪，他們很憂愁。","notes":[]},{"n":7,"t":"他就問一同關在他主人府內法老的官員，說：「你們今日為甚麼面帶愁容呢？」","notes":[]},{"n":8,"t":"他們對他說：「我們各自做了一個夢，卻沒有人能講解。」約瑟對他們說：「解夢不是出於神嗎？請你們把夢告訴我。」","notes":[]},{"n":9,"t":"司酒長就把夢告訴約瑟，對他說：「在我的夢中，看哪，有一棵葡萄樹在我面前，","notes":[]},{"n":10,"t":"樹上有三根枝子。枝子發了芽，開了花，結出串串成熟的葡萄。","notes":[]},{"n":11,"t":"法老的杯在我手中，我就拿葡萄擠在法老的杯裏，把杯遞到他手中。」","notes":[]},{"n":12,"t":"約瑟對他說：「夢的解釋是這樣：三根枝子就是三天；","notes":[]},{"n":13,"t":"三天之內，法老要讓你抬起頭來，叫你官復原職。你仍要遞杯在法老的手中，像先前作他的司酒長一樣。","notes":[]},{"n":14,"t":"但你得福的時候，請你記得我，向我施慈愛，在法老面前提起我，救我出這監牢。","notes":[]},{"n":15,"t":"我實在是從希伯來人之地被拐來的，我在這裏也沒有做過甚麼，好叫他們把我關在牢裏。」","notes":[]},{"n":16,"t":"司膳長見夢解得好，就對約瑟說：「在我夢中，看哪，我頭上頂著三個裝餅的籃子；","notes":[]},{"n":17,"t":"最上面的籃子裏有為法老烤的各樣食物，有飛鳥來吃我頭上籃子裏的食物。」","notes":[]},{"n":18,"t":"約瑟說：「夢的解釋是這樣：三個籃子就是三天；","notes":[]},{"n":19,"t":"三天之內，法老要讓你抬起頭來，身首異處，把你掛在木架上，必有飛鳥來吃你身上的肉。」","notes":[]},{"n":20,"t":"到了第三天，正是法老的生日，他為眾臣僕擺設宴席，使司酒長和司膳長從眾臣僕中抬起頭來，","notes":[]},{"n":21,"t":"讓司酒長官復原職，仍舊遞杯在法老手中，","notes":[]},{"n":22,"t":"卻把司膳長掛起來，正如約瑟向他們所講解的。","notes":[]},{"n":23,"t":"然而，司酒長不記得約瑟，竟忘了他。","notes":[]}]},"41":{"heading":"約瑟為法老解夢","verses":[{"n":1,"t":"過了兩年，法老做夢，看哪，自己站在尼羅河邊，","notes":[]},{"n":2,"t":"看哪，有七頭母牛從尼羅河裏上來，長相俊美，肌肉肥壯，在蘆葦中吃草。","notes":[]},{"n":3,"t":"看哪，隨後又有七頭母牛從尼羅河裏上來，長相醜陋，肌肉乾瘦，與那七頭母牛一同站在河邊。","notes":[]},{"n":4,"t":"這長相醜陋，肌肉乾瘦的七頭母牛吃了那長相俊美又肥壯的七頭母牛。法老就醒了。","notes":[]},{"n":5,"t":"他又睡著，第二次做夢，看哪，一株麥桿長了七個穗子，又肥大又佳美，","notes":[]},{"n":6,"t":"看哪，隨後又長出七個穗子，又細弱又被東風吹焦了。","notes":[]},{"n":7,"t":"這細弱的穗子吞了那七個又肥大又飽滿的穗子。法老醒了，看哪，是個夢。","notes":[]},{"n":8,"t":"到了早晨，法老心裏不安，就派人把埃及所有的術士和智慧人都召來。法老把所做的夢告訴他們，但是沒有人能為法老解夢。","notes":[]},{"n":9,"t":"那時司酒長對法老說：「我今日想起我的罪來。","notes":[]},{"n":10,"t":"從前法老對臣僕發怒，把我和司膳長關在護衛長府內的監牢裏。","notes":[]},{"n":11,"t":"我們兩人在同一晚上各做一夢，每個夢都有各自的解釋。","notes":[]},{"n":12,"t":"同我們在一起有一個希伯來的年輕人，是護衛長的僕人。我們告訴他，他就為我們解夢，照著各人的夢講解。","notes":[]},{"n":13,"t":"後來事情正如他給我們講解的實現了，我官復原職，司膳長被掛起來了。」","notes":[]},{"n":14,"t":"於是法老派人去召約瑟，他們就急忙把他從牢裏提出來。他就剃頭刮臉，換衣服，進到法老面前。","notes":[]},{"n":15,"t":"法老對約瑟說：「我做了一個夢，沒有人能講解。我聽人說，你聽了夢就能講解。」","notes":[]},{"n":16,"t":"約瑟回答法老說：「這不在乎我。神必應允法老平安。」","notes":[]},{"n":17,"t":"法老對約瑟說：「在我的夢中，看哪，我站在尼羅河邊，","notes":[]},{"n":18,"t":"看哪，有七頭母牛從尼羅河裏上來，肌肉肥壯，外形俊美，在蘆葦中吃草。","notes":[]},{"n":19,"t":"看哪，隨後又有七頭母牛上來，虛弱，外形很醜陋，肌肉又乾瘦，在埃及全地，我沒有見過這樣醜陋的牛。","notes":[]},{"n":20,"t":"這乾瘦又醜陋的母牛吃了那先前的七頭肥母牛，","notes":[]},{"n":21,"t":"進了肚子以後卻看不出已經進了肚子，那醜陋的長相仍舊和先前一樣。我就醒了。","notes":[]},{"n":22,"t":"我又在夢中觀看，看哪，一株麥桿長了七個穗子，又飽滿又佳美，","notes":[]},{"n":23,"t":"看哪，隨後又長出七個穗子，枯槁，細弱，又被東風吹焦了。","notes":[]},{"n":24,"t":"這些細弱的穗子吞了那七個佳美的穗子。我告訴術士，卻沒有人能為我講解。」","notes":[]},{"n":25,"t":"約瑟對法老說：「法老的夢是同一個。神已把要做的事指示法老了。","notes":[]},{"n":26,"t":"七頭好母牛是七年，七個佳美的穗子也是七年，這是同一個夢。","notes":[]},{"n":27,"t":"那隨後上來的七頭乾瘦又醜陋的母牛是七年；那七個空心，被東風吹焦的穗子也一樣，都是七個荒年。","notes":[]},{"n":28,"t":"這就是我對法老所說，神已把要做的事顯明給法老了。","notes":[]},{"n":29,"t":"看哪，必有七個大豐年來到埃及全地，","notes":[]},{"n":30,"t":"隨後又有七個荒年，甚至埃及地的人都忘了先前的豐收，這地必被饑荒所滅。","notes":[]},{"n":31,"t":"因為那後來的饑荒非常嚴重，就不覺得這地先前有豐收。","notes":[]},{"n":32,"t":"至於法老兩次做夢，是因為神已經確定這事，神必速速成就。","notes":[]},{"n":33,"t":"現在，請法老選一個聰明又有智慧的人，委派他治理埃及地。","notes":[]},{"n":34,"t":"請法老這樣做，委派官員治理這地，在七個豐年的期間，徵收埃及地出產的五分之一，","notes":[]},{"n":35,"t":"叫他們聚集未來豐年一切的糧食，積存五穀歸在法老的手下作糧食，儲藏在各城裏。","notes":[]},{"n":36,"t":"這糧食可以為這地作儲備，為了埃及地要來的七個荒年，免得這地被饑荒所滅。」","notes":[]},{"n":37,"t":"這事在法老和他眾臣僕眼中都覺得好。","notes":[],"heads":["約瑟被立為埃及的宰相"]},{"n":38,"t":"法老對臣僕說：「像這樣的人，有神的靈在他裏面，我們豈能找得著呢？」","notes":[]},{"n":39,"t":"法老對約瑟說：「神既指示你這一切事，就沒有人像你這樣聰明又有智慧。","notes":[]},{"n":40,"t":"你可以治理我的家；我的百姓都必服從你口中的命令。惟獨在寶座上，我比你大。」","notes":[]},{"n":41,"t":"法老又對約瑟說：「看，我委派你治理埃及全地。」","notes":[]},{"n":42,"t":"法老就脫下手上帶印的戒指，戴在約瑟的手上，給他穿上細麻衣，把金鏈戴在他的頸項上，","notes":[]},{"n":43,"t":"又給約瑟坐他的副座車，在他前面有人呼叫說：「跪下。」於是，法老委派他治理埃及全地。","notes":["「跪下」或譯「讓開」。"]},{"n":44,"t":"法老對約瑟說：「我是法老，若沒有你的命令，埃及全地的人都不可擅自辦事。」","notes":["「擅自辦事」：原文是「動手動腳」。"]},{"n":45,"t":"法老給約瑟起名叫撒發那特‧巴內亞，又將安城的祭司波提‧非拉的女兒亞西納給他為妻。約瑟就出去治理埃及地。","notes":[]},{"n":46,"t":"約瑟在埃及王法老面前侍立的時候年三十歲。約瑟從法老面前出去，巡行埃及全地。","notes":[]},{"n":47,"t":"七個豐年之內，地的出產極其豐盛，","notes":["「極其豐盛」：原文是「一把一把的」。"]},{"n":48,"t":"約瑟聚集埃及地七年一切的糧食，把糧食積存在各城裏，就是把各城周圍田地的糧食都積存在該城裏。","notes":[]},{"n":49,"t":"約瑟積存的五穀很多，如同海邊的沙，無法計算，數也數不清。","notes":[]},{"n":50,"t":"荒年未到以前，安城的祭司波提‧非拉的女兒亞西納為約瑟生了兩個兒子。","notes":[]},{"n":51,"t":"約瑟給長子起名叫瑪拿西，因為他說：「神使我忘了一切的困苦和我父的全家。」","notes":["「瑪拿西」意思是「使忘記」。"]},{"n":52,"t":"他給次子起名叫以法蓮，因為他說：「神使我在受苦的地方興盛。」","notes":["「以法蓮」意思是「興盛」。"]},{"n":53,"t":"埃及地的七個豐年一過，","notes":[]},{"n":54,"t":"七個荒年就來了，正如約瑟所說的。各地都有饑荒，惟獨埃及全地有糧食。","notes":[]},{"n":55,"t":"等到埃及全地也有了饑荒，眾百姓就向法老哀求糧食。法老對所有的埃及人說：「你們到約瑟那裏去，凡他所說的，你們都要做。」","notes":[]},{"n":56,"t":"當時饑荒遍滿了全地，約瑟就開了各處的糧倉，賣糧食給埃及人。埃及地的饑荒非常嚴重。","notes":["「各處的糧倉」是根據七十士譯本和其他古譯本；原文是「所有在它們裏面的」。"]},{"n":57,"t":"各地的人都去埃及，到約瑟那裏買糧食，因為全地的饑荒非常嚴重。","notes":[]}]},"42":{"heading":"約瑟的哥哥到埃及買糧","verses":[{"n":1,"t":"雅各見埃及有糧，就對兒子們說：「你們為甚麼彼此對看呢？」","notes":[]},{"n":2,"t":"他又說：「看哪，我聽見埃及有糧，你們可以下到那裏，從那裏為我們買些糧來，我們就可以存活，不至於死。」","notes":[]},{"n":3,"t":"於是，約瑟的十個哥哥都下去，到埃及買糧食。","notes":[]},{"n":4,"t":"至於約瑟的弟弟便雅憫，雅各沒有派他和哥哥們同去，因為雅各說：「恐怕他遭難。」","notes":[]},{"n":5,"t":"以色列的兒子們來了，在前來的人當中，為要買糧食，因為迦南地也有饑荒。","notes":[]},{"n":6,"t":"當時在埃及地掌權的人是約瑟，賣糧給各地眾百姓的就是他。約瑟的哥哥們來了，臉伏於地，向他下拜。","notes":[]},{"n":7,"t":"約瑟看見他哥哥們，就認出他們，卻對他們裝作陌生人，向他們說嚴厲的話，對他們說：「你們從哪裏來？」他們說：「我們從迦南地來買糧。」","notes":[]},{"n":8,"t":"約瑟認得他哥哥們，他們卻不認得他。","notes":[]},{"n":9,"t":"約瑟想起從前所做的那兩個夢，就對他們說：「你們是奸細，你們來是要窺探這地的虛實。」","notes":[]},{"n":10,"t":"他們對他說：「我主啊，不是的，僕人們是來買糧的。","notes":[]},{"n":11,"t":"我們都是同一個人的兒子，我們是誠實的人。僕人們並不是奸細。」","notes":[]},{"n":12,"t":"約瑟對他們說：「不，你們一定是窺探這地的虛實來的。」","notes":[]},{"n":13,"t":"他們說：「僕人們本是兄弟十二人，我們都是迦南地同一個人的兒子。看哪，最小的今日在我們父親那裏，有一個不在了。」","notes":[]},{"n":14,"t":"約瑟對他們說：「我剛才對你們說過了，你們是奸細！","notes":[]},{"n":15,"t":"我指著法老的性命起誓，若是你們最小的弟弟不到這裏來，你們就不可以離開這裏；這樣你們就可以證實自己了。","notes":[]},{"n":16,"t":"要派你們當中的一個人去，把你們的弟弟帶來。至於你們，都要關在這裏，好證實你們的話是不是真的。若不是，我指著法老的性命起誓，你們一定是奸細。」","notes":[]},{"n":17,"t":"於是約瑟把他們一起都關在監裏三天。","notes":[]},{"n":18,"t":"第三天，約瑟對他們說：「我是敬畏神的，你們這麼做就可以活。","notes":[]},{"n":19,"t":"如果你們是誠實的人，留你們兄弟中的一個關在監牢裏，你們帶糧食回去，救你們家的饑荒，","notes":[]},{"n":20,"t":"再把你們最小的弟弟帶到我這裏來。如此，你們的話就是真的了，你們也不至於死。」他們就照樣做了。","notes":[]},{"n":21,"t":"他們彼此說：「我們在弟弟身上實在犯了罪。他哀求我們的時候，我們看見他的痛苦，卻不肯聽，所以這場苦難臨到我們。」","notes":[]},{"n":22,"t":"呂便回答他們說：「我不是對你們說過，不可傷害那孩子嗎？只是你們不肯聽，看哪，他的血在追討了。」","notes":[]},{"n":23,"t":"他們不知道約瑟在聽，因為在他們之間有傳譯官。","notes":[]},{"n":24,"t":"約瑟轉身離開他們，哭了一場，又回來對他們說話，就從他們中間抓了西緬，在他們眼前捆綁他。","notes":[]},{"n":25,"t":"約瑟吩咐人把他們的器皿裝滿糧食，把各人的銀子退還在各人的袋裏，又給他們路上需用的食物。人就為他們這樣做了。","notes":[],"heads":["約瑟的哥哥回迦南地"]},{"n":26,"t":"他們把糧食馱在驢上，離開那裏去了。","notes":[]},{"n":27,"t":"到了住宿的地方，有一個人打開袋子，要拿飼料餵驢，就看見自己的銀子，看哪，仍在袋口上。","notes":[]},{"n":28,"t":"他對兄弟們說：「我的銀子退回來了，看哪，還在我袋子裏！」他們戰戰兢兢，心都快跳出來了，彼此說：「神向我們做的是甚麼呢？」","notes":[]},{"n":29,"t":"他們來到迦南地他們的父親雅各那裏，把所遭遇的事都告訴他，說：","notes":[]},{"n":30,"t":"「那地的主對我們說嚴厲的話，把我們當作窺探那地的奸細。","notes":[]},{"n":31,"t":"我們對他說：『我們是誠實的人，並不是奸細。","notes":[]},{"n":32,"t":"我們本是兄弟十二人，都是同一個父親的兒子，有一個不在了，最小的今日和我們父親在迦南地。』","notes":[]},{"n":33,"t":"那地的主對我們說：『只有這樣我才知道你們是誠實的人：留你們兄弟中的一個在我這裏，你們帶糧食回去，救你們家的饑荒，","notes":[]},{"n":34,"t":"再把你們最小的弟弟帶到我這裏來，我就知道你們不是奸細，是誠實的人。然後，我就把你們的兄弟交還你們，你們也可以在此地做買賣。』」","notes":[]},{"n":35,"t":"後來他們倒空袋子，看哪，各人的銀囊都在袋子裏。他們和父親看見銀囊就都害怕。","notes":[]},{"n":36,"t":"他們的父親雅各對他們說：「你們害我喪失了我的兒子：約瑟不在了，西緬也不在了，你們還要帶走便雅憫！這些事都臨到我身上了。」","notes":[]},{"n":37,"t":"呂便對他父親說：「我若不帶他回來給你，你可以殺我的兩個兒子。只管把他交在我手裏，我必帶他回來給你。」","notes":[]},{"n":38,"t":"雅各說：「我的兒子不可與你們一同下去。他哥哥死了，只剩下他。他若在你們行走的路上遭難，你們就害我白髮蒼蒼、悲悲慘慘下陰間去了。」","notes":[]}]},"43":{"heading":"約瑟的哥哥帶便雅憫到埃及","verses":[{"n":1,"t":"那地的饑荒非常嚴重。","notes":[]},{"n":2,"t":"他們從埃及帶來的糧食吃完了，父親對他們說：「你們再去給我們買些糧來。」","notes":[]},{"n":3,"t":"猶大對他說：「那人嚴厲地警告我們說：『你們的弟弟若不和你們同來，你們就不要來見我的面。』","notes":[]},{"n":4,"t":"你若派我們的弟弟跟我們同去，我們就下去給你買糧；","notes":[]},{"n":5,"t":"你若不派他去，我們就不下去，因為那人對我們說：『你們的弟弟若不和你們同來，你們就不要來見我的面。』」","notes":[]},{"n":6,"t":"以色列說：「你們為甚麼這樣害我，告訴那人你們還有弟弟呢？」","notes":[]},{"n":7,"t":"他們說：「那人詳細問到我們和我們的家人，說：『你們的父親還在嗎？你們還有兄弟嗎？』我們就按著他的這些話告訴他，我們怎麼知道他會說：『把你們的弟弟帶下來』呢？」","notes":[]},{"n":8,"t":"猶大又對他父親以色列說：「請派這年輕人和我同去，我們就動身前去，好叫我們和你，以及我們的孩子都得存活，不至於死。","notes":[]},{"n":9,"t":"我為他擔保，你可以從我手中要人，我若不帶他回來交在你面前，我就對你永遠擔當這罪。","notes":[]},{"n":10,"t":"我們若沒有耽擱，現在第二趟都回來了。」","notes":[]},{"n":11,"t":"父親以色列對他們說：「如果必須如此，你們要這樣做：把本地土產中最好的乳香、蜂蜜、香料、沒藥、堅果、杏仁各取一點，放在器皿裏，帶下去送給那人作禮物。","notes":[]},{"n":12,"t":"手裏要帶雙倍的銀子，把退還在你們袋口的銀子親手帶回去；或許那是個失誤。","notes":[]},{"n":13,"t":"帶著你們的弟弟，動身再去見那人。","notes":[]},{"n":14,"t":"願全能的神使你們在那人面前蒙憐憫，放你們另一個兄弟和便雅憫回來。我若要失喪兒子，就喪了吧！」","notes":[]},{"n":15,"t":"於是，他們拿著那些禮物，手裏也帶雙倍的銀子，並且帶著便雅憫，動身下到埃及，站在約瑟面前。","notes":[]},{"n":16,"t":"約瑟見便雅憫和他們同來，就對管家說：「把這些人領到屋裏。要宰殺牲畜，預備宴席，因為中午這些人要跟我吃飯。」","notes":[]},{"n":17,"t":"那人就照約瑟所說的去做，領他們進約瑟的屋裏。","notes":[]},{"n":18,"t":"這些人因為被領到約瑟的屋裏，就害怕，說：「領我們到這裏來，必是因為當初退還在我們袋裏的銀子，要設計害我們，抓我們去當奴隸，搶奪我們的驢。」","notes":[]},{"n":19,"t":"他們就挨近約瑟的管家，在屋子門口和他說話，","notes":[]},{"n":20,"t":"說：「我主啊，求求你，我們當初下來，真的是要買糧食。","notes":[]},{"n":21,"t":"後來到了住宿的地方，我們打開袋子，看哪，各人的銀子還在自己的袋口上，銀子的分量一點不少。現在我們親手把它帶回來，","notes":[]},{"n":22,"t":"我們手裏又帶了另外的銀子來買糧食。我們不知道是誰把銀子放在我們袋裏的。」","notes":[]},{"n":23,"t":"他說：「你們平安！不要害怕，是你們的神和你們父親的神把財寶放在你們的袋裏。你們的銀子，我已經收了。」他就把西緬帶出來，交給他們。","notes":[]},{"n":24,"t":"那人領這些人進約瑟的屋裏，給他們水洗腳，又給他們飼料餵驢。","notes":[]},{"n":25,"t":"他們預備好禮物，等候約瑟中午來，因為他們聽說他們要在那裏吃飯。","notes":[]},{"n":26,"t":"約瑟來到家裏，他們就把手中的禮物拿進屋裏給他，俯伏在地，向他下拜。","notes":[]},{"n":27,"t":"約瑟問他們安，又說：「你們的父親，就是你們所說的那位老人家平安嗎？他還在嗎？」","notes":[]},{"n":28,"t":"他們說：「你僕人，我們的父親平安，他還在。」於是他們低頭下拜。","notes":[]},{"n":29,"t":"約瑟舉目看見他同母的弟弟便雅憫，就說：「你們向我所說那最小的弟弟就是這位嗎？」又說：「我兒啊，願神賜恩給你！」","notes":[]},{"n":30,"t":"約瑟愛弟之情激動，就急忙找個地方去哭。他進入自己的房間，哭了一場。","notes":[]},{"n":31,"t":"他洗了臉出來，勉強忍住，就說：「開飯吧！」","notes":[]},{"n":32,"t":"他們為約瑟單獨擺了一席，為那些人又擺了一席，也為和約瑟同吃飯的埃及人另擺了一席，因為埃及人不和希伯來人一同吃飯；那是埃及人所厭惡的。","notes":[]},{"n":33,"t":"兄弟們被安排在約瑟面前坐席，都按著長幼的次序，這些人彼此感到詫異。","notes":[]},{"n":34,"t":"約瑟把他面前的食物分給他們，但便雅憫所得的比別人多五倍。他們就喝酒，和約瑟一同暢飲。","notes":[]}]},"44":{"heading":"約瑟用計留住便雅憫","verses":[{"n":1,"t":"約瑟吩咐管家說：「按照他們的驢子所能馱的，把這些人的袋子裝滿糧食，再把各人的銀子放在各人的袋口上，","notes":[]},{"n":2,"t":"我的杯，就是那個銀杯，要和買糧的銀子一同放在最年輕的那個人的袋口上。」管家就照約瑟所說的話去做了。","notes":[]},{"n":3,"t":"天一亮，這些人和他們的驢子就被送走了。","notes":[]},{"n":4,"t":"他們出城走了不遠，約瑟對管家說：「起來，去追那些人，追上了就對他們說：『你們為甚麼以惡報善呢？","notes":[]},{"n":5,"t":"這不是我主人用來飲酒，確實用它來占卜的嗎？你們這麼做是不對的！』」","notes":[]},{"n":6,"t":"管家追上他們，把這些話對他們說了。","notes":[]},{"n":7,"t":"他們對他說：「我主為甚麼說這樣的話呢？你僕人們絕不會做這樣的事。","notes":[]},{"n":8,"t":"看哪，我們從前在袋口上發現的銀子，尚且從迦南地帶來還你，我們又怎麼會從你主人家裏偷竊金銀呢？","notes":[]},{"n":9,"t":"你僕人中無論在誰那裏找到杯子，就叫他死，我們也要作我主的奴隸。」","notes":[]},{"n":10,"t":"管家說：「現在就照你們的話做吧！在誰那裏找到杯子，誰就作我的奴隸，其餘的人都沒有罪。」","notes":[]},{"n":11,"t":"於是他們各人急忙把袋子卸在地上，各人打開自己的袋子。","notes":[]},{"n":12,"t":"管家就搜查，從年長的開始到年幼的為止，那杯竟在便雅憫的袋子裏找到了。","notes":[]},{"n":13,"t":"他們就撕裂衣服，各人把馱子抬在驢上，回城去了。","notes":[]},{"n":14,"t":"猶大和他兄弟們來到約瑟的屋裏，約瑟還在那裏，他們就在他面前俯伏於地。","notes":[]},{"n":15,"t":"約瑟對他們說：「你們做的是甚麼事呢？你們豈不知像我這樣的人必懂得占卜嗎？」","notes":[]},{"n":16,"t":"猶大說：「我們對我主能說甚麼呢？還有甚麼話可說呢？我們還能為自己表白嗎？神已經查出你僕人的罪孽了。看哪，我們與那在他手中找到杯子的人都是我主的奴隸。」","notes":[]},{"n":17,"t":"約瑟說：「我絕不能做這樣的事！誰的手中找到杯子，誰就作我的奴隸。至於你們，可以平平安安上到你們父親那裏去。」","notes":[]},{"n":18,"t":"猶大挨近他，說：「我主啊，求求你，讓僕人說一句話給我主聽，不要向僕人發烈怒，因為你如同法老一樣。","notes":[],"heads":["猶大替便雅憫哀求"]},{"n":19,"t":"我主曾問僕人們說：『你們有父親、兄弟沒有？』","notes":[]},{"n":20,"t":"我們對我主說：『我們有父親，他已經年老，還有他老年所生的一個小兒子。他哥哥死了，他的母親只剩下他一個孩子，父親也疼愛他。』","notes":[]},{"n":21,"t":"你對僕人說：『把他帶下到我這裏來，讓我親眼看看他。』","notes":[]},{"n":22,"t":"我們對我主說：『這年輕人不能離開他父親，若是離開，父親就會死。』","notes":[]},{"n":23,"t":"你對僕人說：『你們最小的弟弟若不和你們一同下來，你們就不要來見我的面。』","notes":[]},{"n":24,"t":"我們上到你僕人，我們父親那裏，就把我主的話告訴了他。","notes":[]},{"n":25,"t":"後來，我們的父親說：『你們再去給我買些糧來。』","notes":[]},{"n":26,"t":"我們說：『我們不能下去。最小的弟弟若和我們同去，我們就可以下去。因為，最小的弟弟若不和我們同去，我們必不能見那人的面。』","notes":[]},{"n":27,"t":"你僕人，我父親對我們說：『你們知道我的妻子給我生了兩個兒子。","notes":[]},{"n":28,"t":"一個離開我走了，我說他必是被野獸撕碎了，直到如今我再沒有見過他；","notes":[]},{"n":29,"t":"現在你們又要把這個從我面前帶走。倘若他遭難，那麼你們就害我白髮蒼蒼、悲悲慘慘下陰間去了。』","notes":[]},{"n":30,"t":"如今我回到你僕人，我父親那裏，若沒有這年輕人和我們同去，我父親的命是與這年輕人的命相連的，","notes":[]},{"n":31,"t":"當我們的父親看見沒有了這年輕人，他就會死。這樣，我們就害你僕人，我們的父親白髮蒼蒼、悲悲慘慘下陰間去了。","notes":[]},{"n":32,"t":"僕人曾向我父親為這年輕人擔保，說：『我若不帶他回來交給父親，我就在父親面前永遠擔當這罪。』","notes":[]},{"n":33,"t":"現在，求你把僕人留下，代替這年輕人作我主的奴隸，讓這年輕人和他哥哥們一同上去。","notes":[]},{"n":34,"t":"若這年輕人不和我一起，我怎能上到我父親那裏呢？恐怕我要看到災禍臨到我父親了。」","notes":[]}]},"45":{"heading":"約瑟和兄弟相認","verses":[{"n":1,"t":"約瑟在所有侍立在他旁邊的人面前情不自禁，就喊叫說：「每一個人都離開我，出去吧！」約瑟和兄弟相認的時候沒有一人站在他那裏。","notes":[]},{"n":2,"t":"他放聲大哭，埃及人聽見了，法老家中的人也聽見了。","notes":[]},{"n":3,"t":"約瑟對他兄弟們說：「我就是約瑟。我的父親還在嗎？」他兄弟們不敢回答他，因為他們在他面前都很驚惶。","notes":[]},{"n":4,"t":"約瑟又對他兄弟們說：「靠近我一點。」他們就近前來。他說：「我是被你們賣到埃及的兄弟約瑟。","notes":[]},{"n":5,"t":"現在，不要因為把我賣到這裏而憂傷，對自己生氣，因為神差我在你們以先來，為要保全性命。","notes":[]},{"n":6,"t":"現在這地的饑荒已經二年了，還有五年不能耕種，沒有收成。","notes":[]},{"n":7,"t":"神差我在你們以先來，為要給你們在世上存留餘種，大施拯救，保全你們的性命。","notes":[]},{"n":8,"t":"這樣看來，差我到這裏來的不是你們，而是神。他又使我如同法老之父，作他全家之主，和埃及全地掌權的人。","notes":[]},{"n":9,"t":"你們要趕緊上到我父親那裏，對他說：『你兒子約瑟這樣說：神已立我作全埃及之主，請你下到我這裏來，不要耽擱。","notes":[]},{"n":10,"t":"你和你的兒子孫子，羊群牛群，以及一切所有的，都可以住在歌珊地，與我相近。","notes":[]},{"n":11,"t":"我要在那裏奉養你，因為還有五年的饑荒，免得你和你的家屬，以及一切所有的，都陷入窮困中。』","notes":[]},{"n":12,"t":"看哪，你們的眼睛和我弟弟便雅憫的眼睛都看見，是我親口對你們說話。","notes":[]},{"n":13,"t":"你們要把我在埃及一切的尊榮和你們所有看見的事情都告訴我父親，也要趕緊請我父親下到這裏來。」","notes":[]},{"n":14,"t":"於是約瑟伏在他弟弟便雅憫的頸項上哭，便雅憫也在他的頸項上哭。","notes":[]},{"n":15,"t":"他又親眾兄弟，伏著他們哭。過後，他的兄弟就和他說話。","notes":[]},{"n":16,"t":"這消息傳到法老的宮裏，說：「約瑟的兄弟們來了。」法老和他的臣僕眼中都看為好。","notes":[]},{"n":17,"t":"法老對約瑟說：「你要吩咐你的兄弟們說：『你們要這樣做：把馱子抬在牲口上，動身到迦南地去，","notes":[]},{"n":18,"t":"請你們的父親和你們的家屬都到我這裏來，我要把埃及地的美物賜給你們，你們也要吃這地肥美的出產。』","notes":[]},{"n":19,"t":"你要吩咐他們：『要這樣做：從埃及地帶著車輛去，把你們的孩子和妻子，以及你們的父親都接來。","notes":[]},{"n":20,"t":"你們的眼不要顧惜你們的家具，因為埃及全地的美物都是你們的。』」","notes":[]},{"n":21,"t":"以色列的兒子們就照樣做了。約瑟遵照法老的吩咐，給他們車輛和路上需用的食物。","notes":[]},{"n":22,"t":"他又給所有哥哥每人一套衣服， 卻給便雅憫三百銀子，五套衣服。","notes":[]},{"n":23,"t":"他也送給父親十匹公驢，馱著埃及的美物，以及十匹母驢，馱著給他父親在路上需用的穀物、餅和糧食。","notes":[]},{"n":24,"t":"於是約瑟送他的兄弟們回去，對他們說：「你們不要在路上爭吵。」","notes":[]},{"n":25,"t":"他們從埃及上去，來到迦南地他們的父親雅各那裏，","notes":[]},{"n":26,"t":"告訴他說：「約瑟還活著，並且作了埃及全地掌權的人。」雅各心裏冰涼，因為不信他們。","notes":[]},{"n":27,"t":"他們就把約瑟對他們所說一切的話都告訴了他。他看見約瑟派來接他的車輛，他們父親雅各的靈就甦醒了。","notes":[]},{"n":28,"t":"以色列說：「夠了！我的兒子約瑟還活著，我要趁我未死之前去見他。」","notes":[]}]},"46":{"heading":"雅各帶家屬到埃及","verses":[{"n":1,"t":"以色列帶著一切所有的，起程到別是巴去，獻祭給他父親以撒的神。","notes":[]},{"n":2,"t":"夜間，神在異象中對以色列說：「雅各！雅各！」他說：「我在這裏。」","notes":[]},{"n":3,"t":"神說：「我是神，你父親的神。不要害怕下埃及去，因為我必使你在那裏成為大國。","notes":[]},{"n":4,"t":"我要和你同下埃及去，也必定帶你上來；約瑟要親手合上你的眼睛。」","notes":[]},{"n":5,"t":"雅各就從別是巴起行。以色列的兒子讓他們的父親雅各和他們的孩子、妻子都坐在法老為雅各派來的車上。","notes":[]},{"n":6,"t":"他們也帶著迦南地所得的牲畜和財物來到埃及。雅各和他所有的子孫都一同來了。","notes":[]},{"n":7,"t":"他把他的兒子、孫子、女兒、孫女，他所有的子孫一同帶到埃及。","notes":[]},{"n":8,"t":"這些是來到埃及的以色列人，雅各和他子孫的名字：雅各的長子是呂便。","notes":[]},{"n":9,"t":"呂便的兒子是哈諾、法路、希斯倫、迦米。","notes":[]},{"n":10,"t":"西緬的兒子是耶母利、雅憫、阿轄、雅斤、瑣轄，還有迦南女子生的兒子掃羅。","notes":[]},{"n":11,"t":"利未的兒子是革順、哥轄、米拉利。","notes":[]},{"n":12,"t":"猶大的兒子是珥、俄南、示拉、法勒斯、謝拉；珥與俄南死在迦南地。法勒斯的兒子是希斯崙、哈母勒。","notes":[]},{"n":13,"t":"以薩迦的兒子是陀拉、普瓦、約伯、伸崙。","notes":[]},{"n":14,"t":"西布倫的兒子是西烈、以倫、雅利。","notes":[]},{"n":15,"t":"這是利亞在巴旦‧亞蘭為雅各所生的兒孫，還有女兒底拿，兒孫共三十三人。","notes":[]},{"n":16,"t":"迦得的兒子是洗非芸、哈基、書尼、以斯本、以利、亞羅底、亞列利。","notes":[]},{"n":17,"t":"亞設的兒子是音拿、亦施瓦、亦施韋、比利亞，還有他們的妹妹西拉。比利亞的兒子是希別、瑪結。","notes":[]},{"n":18,"t":"這是拉班給他女兒利亞的婢女悉帕的兒孫，她為雅各所生的共有十六人。","notes":[]},{"n":19,"t":"雅各之妻拉結的兒子是約瑟和便雅憫。","notes":[]},{"n":20,"t":"約瑟在埃及地生了瑪拿西和以法蓮，是安城的祭司波提‧非拉的女兒亞西納為約瑟生的。","notes":[]},{"n":21,"t":"便雅憫的兒子是比拉、比結、亞實別、基拉、乃幔、以希、羅實、母平、戶平、亞勒。","notes":[]},{"n":22,"t":"這是拉結為雅各所生的兒孫，共有十四人。","notes":[]},{"n":23,"t":"但的兒子是戶伸。","notes":[]},{"n":24,"t":"拿弗他利的兒子是雅薛、沽尼、耶色、示冷。","notes":[]},{"n":25,"t":"這是拉班給他女兒拉結的婢女辟拉的兒孫，她為雅各所生的共有七人。","notes":[]},{"n":26,"t":"那與雅各同到埃及的，除了他媳婦之外，凡從他生的共有六十六人。","notes":[]},{"n":27,"t":"還有約瑟在埃及所生的兩個兒子。到埃及的雅各全家共有七十人。","notes":[]},{"n":28,"t":"雅各派猶大先到約瑟那裏，請他先指示到歌珊去的路；於是他們來到了歌珊地。","notes":[],"heads":["雅各和家屬在歌珊"]},{"n":29,"t":"約瑟備好座車，上歌珊去迎接他的父親以色列。他見到父親，就伏在父親的頸項上，在父親的頸項上哭了許久。","notes":[]},{"n":30,"t":"以色列對約瑟說：「我見了你的面，知道你還活著，現在我可以死了。」","notes":[]},{"n":31,"t":"約瑟對他兄弟和他父親的全家說：「我要上去告訴法老，對他說：『我在迦南地的兄弟和我父親的全家，都到我這裏來了。","notes":[]},{"n":32,"t":"他們是牧羊人，是牧放牲畜的人；他們把羊群牛群和一切所有的都帶來了。』","notes":[]},{"n":33,"t":"等到法老召見你們，說：『你們是做甚麼的？』","notes":[]},{"n":34,"t":"你們就說：『你的僕人，從幼年直到現在，都是牧放牲畜的人，我們和我們的祖宗都是這樣。』如此，你們就可以住在歌珊地，因為凡牧羊的都被埃及人厭惡。」","notes":[]}]},"47":{"heading":"嚴重的饑荒","verses":[{"n":1,"t":"約瑟進去告訴法老說：「我的父親和我的兄弟帶著羊群牛群，以及他們一切所有的，從迦南地來了。看哪，他們正在歌珊地。」","notes":[]},{"n":2,"t":"約瑟從他所有兄弟中挑選五個人，引他們到法老面前。","notes":[]},{"n":3,"t":"法老對約瑟的兄弟說：「你們是做甚麼的？」他們對法老說：「你僕人是牧羊的，我們和我們的祖宗都是這樣。」","notes":[]},{"n":4,"t":"他們又對法老說：「迦南地的饑荒非常嚴重，僕人的羊群沒有牧草，所以我們來到這地寄居。現在求你准許僕人住在歌珊地。」","notes":[]},{"n":5,"t":"法老對約瑟說：「你的父親和你的兄弟到你這裏來了，","notes":[]},{"n":6,"t":"埃及地都在你面前，只管讓你父親和你兄弟住在最好的地，他們可以住在歌珊地。你若知道他們中間有能幹的人，就派他們看管我的牲畜。」","notes":[]},{"n":7,"t":"約瑟帶他父親雅各來，站在法老面前，雅各就為法老祝福。","notes":[]},{"n":8,"t":"法老對雅各說：「你平生的年日是多少呢？」","notes":[]},{"n":9,"t":"雅各對法老說：「我在世寄居的年日是一百三十年，我一生的歲月又短又苦，比不上我祖先在世寄居的年日。」","notes":[]},{"n":10,"t":"雅各又為法老祝福，就從法老面前退出去了。","notes":[]},{"n":11,"t":"約瑟安頓他的父親和兄弟，遵照法老的命令，把埃及境內最好的地，就是蘭塞地，給他們作為產業。","notes":[]},{"n":12,"t":"約瑟用糧食供給他父親和兄弟們，以及他父親全家的人，照扶養親屬的人口供給。","notes":[]},{"n":13,"t":"饑荒非常嚴重，全地都絕了糧，埃及地和迦南地都因饑荒耗損了。","notes":[]},{"n":14,"t":"約瑟收集了埃及地和迦南地所有的銀子，就是眾人買糧的銀子，約瑟就把那些銀子都帶到法老的宮裏。","notes":[]},{"n":15,"t":"埃及地和迦南地的銀子都花光了，埃及眾人到約瑟那裏，說：「我們的銀子都用完了，求你給我們糧食吧！我們為甚麼要死在你面前呢？」","notes":[]},{"n":16,"t":"約瑟說：「銀子若是用完了，可以把你們的牲畜賣給我，我就以你們的牲畜換糧食給你們。」","notes":[]},{"n":17,"t":"於是他們把牲畜帶到約瑟那裏，約瑟就拿糧食換了他們的馬、羊、牛、驢；那一年他因換他們一切的牲畜，用糧食養活他們。","notes":[]},{"n":18,"t":"那一年過去，第二年他們又來到約瑟那裏，對他說：「不瞞我主，我們的銀子都花光了，牲畜也都歸於我主了。我們在我主面前，除了自己的身體和土地以外，一無所剩。","notes":[]},{"n":19,"t":"你為甚麼要眼看著我們人死地荒呢？求你用糧食買我們和我們的地，我們和我們的地就要為法老效力。求你給我們種子，使我們可以存活，不致死亡，土地也不致荒蕪。」","notes":[]},{"n":20,"t":"於是，約瑟為法老買了埃及所有的土地，埃及人因饑荒所迫，都賣了自己的田地；那些地都歸給法老了。","notes":[]},{"n":21,"t":"至於百姓，從埃及邊界的一端到另一端，約瑟使他們作奴隸。","notes":["本節是根據撒瑪利亞五經和七十士譯本；原文是「至於百姓，約瑟把他們遷移到城鎮中，從埃及邊界的一端到另一端。」"]},{"n":22,"t":"只有祭司的土地，約瑟沒有買，因為祭司從法老領取薪俸，靠法老的薪俸過活，所以沒有賣自己的土地。","notes":[]},{"n":23,"t":"約瑟對百姓說：「看哪，我今日為法老買了你們和你們的土地。看哪，這些種子是給你們的，你們可以耕種土地。","notes":[]},{"n":24,"t":"將來收割的時候，你們要把五分之一納給法老，另外四分可以給你們作田地的種子，作你們和你們全家大小的食物。」","notes":[]},{"n":25,"t":"他們說：「你救了我們的性命，願我們在我主眼前蒙恩，我們情願作法老的奴隸。」","notes":[]},{"n":26,"t":"於是約瑟為埃及的土地立下定例，直到今日，就是收成的五分之一要歸法老。惟獨祭司的土地例外，不歸於法老。","notes":[]},{"n":27,"t":"以色列人住在埃及境內的歌珊地。他們在那裏得了產業，並且生養眾多。","notes":[],"heads":["雅各最後的吩咐"]},{"n":28,"t":"雅各住在埃及地十七年。雅各一生的年日是一百四十七年。","notes":[]},{"n":29,"t":"以色列的死期快到了，就叫了他兒子約瑟來，對他說：「我若在你眼前蒙恩，把你的手放在我大腿底下，以慈愛和誠實向我承諾，必不將我葬在埃及。","notes":[]},{"n":30,"t":"我與我祖先同睡的時候，你要將我帶出埃及，把我葬在他們所葬的地方。」約瑟說：「我必遵照你的吩咐去做。」","notes":[]},{"n":31,"t":"雅各說：「你向我起誓吧！」約瑟就向他起了誓。於是以色列在床頭敬拜。","notes":["「在床頭」或譯「扶著杖頭」。"]}]},"48":{"heading":"雅各祝福約瑟的兩個兒子","verses":[{"n":1,"t":"這些事以後，有人告訴約瑟說：「看哪，你的父親病了。」他就帶著兩個兒子瑪拿西和以法蓮同去。","notes":[]},{"n":2,"t":"有人告訴雅各說：「看哪，你的兒子約瑟到你這裏來了。」以色列就勉強在床上坐起來。","notes":[]},{"n":3,"t":"雅各對約瑟說：「全能的神曾在迦南地的路斯向我顯現，賜福給我，","notes":[]},{"n":4,"t":"對我說：『看哪，我必使你生養眾多，成為許多民族，又要將這地賜給你的後裔，永遠為業。』","notes":[]},{"n":5,"t":"我未到埃及你那裏之前，你在埃及地所生的以法蓮和瑪拿西這兩個兒子，現在他們是我的，正如呂便和西緬是我的一樣。","notes":[]},{"n":6,"t":"你在他們以後所生的後裔就是你的，這些後裔可以在自己兄弟的名下得產業。","notes":[]},{"n":7,"t":"至於我，我從巴旦回來的時候，拉結在我身旁死了，就是在往迦南地的路上，離以法他還有一段路程。我就把她葬在往以法他的路旁；以法他就是伯利恆。」","notes":[]},{"n":8,"t":"以色列看見約瑟的兒子，就說：「這些是誰？」","notes":[]},{"n":9,"t":"約瑟對他父親說：「這是神在這裏賜給我的兒子。」以色列說：「領他們到我跟前，我要為他們祝福。」","notes":[]},{"n":10,"t":"以色列年紀老邁，眼睛昏花，不能看見。約瑟領他們到他跟前，他就和他們親吻，抱著他們。","notes":[]},{"n":11,"t":"以色列對約瑟說：「我沒有想到能夠見你的面。看哪，神還讓我看見你的兒子。」","notes":[]},{"n":12,"t":"約瑟把他們從以色列兩膝中間領出來，自己臉伏於地下拜。","notes":[]},{"n":13,"t":"然後，約瑟牽著他們兩個，帶到父親跟前，右手牽以法蓮到以色列的左邊，左手牽瑪拿西到以色列的右邊。","notes":[]},{"n":14,"t":"以色列卻伸出右手來，按在次子以法蓮的頭上，又交叉伸出左手來，按在長子瑪拿西的頭上。","notes":[]},{"n":15,"t":"他就為約瑟祝福說：「願我祖父亞伯拉罕和我父親以撒所事奉的神，就是一生牧養我直到今日的神，","notes":[]},{"n":16,"t":"救贖我脫離一切患難的那位使者，賜福給這兩個孩子。願我的名，我祖父亞伯拉罕和我父親以撒的名藉著他們得以流傳。又願他們在全地上多多繁衍。」","notes":[]},{"n":17,"t":"約瑟見父親把右手按在以法蓮的頭上，他看為不好，就提起他父親的手，要從以法蓮的頭上移到瑪拿西的頭上。","notes":[]},{"n":18,"t":"約瑟對父親說：「我父，不是這樣。這個才是長子，請你把右手按在他頭上。」","notes":[]},{"n":19,"t":"他父親卻不肯，說：「我知道，我兒，我知道。他也要成為一族，也要強大。可是他的弟弟將來比他還要強大；他弟弟的後裔要成為許多國家。」","notes":[]},{"n":20,"t":"以色列就在當日為他們祝福，說：「以色列人要指著你們祝福，說：『願神使你如以法蓮、瑪拿西一樣。』」於是他立以法蓮在瑪拿西之上。","notes":[]},{"n":21,"t":"以色列又對約瑟說：「看哪，我快要死了，但神必與你們同在，領你們回到你們祖先之地。","notes":[]},{"n":22,"t":"從前我用刀用弓從亞摩利人手下奪取的那一份，我要把它賜給你，使你比你的兄弟多得一份。」","notes":["「比你的兄弟多得一份」或譯「使你擁有示劍城，超過你的兄弟」。"]}]},"49":{"heading":"雅各的遺言","verses":[{"n":1,"t":"雅各叫了他的兒子來，說：「你們都來聚集，讓我把你們日後要遇到的事告訴你們。","notes":[]},{"n":2,"t":"雅各的兒子們，你們要聚集，要聆聽，聽你們父親以色列的話。","notes":[]},{"n":3,"t":"呂便啊，你是我的長子，我的力量，我壯年頭生之子，極有尊榮，權力超群。","notes":[]},{"n":4,"t":"你卻放縱如水，必不得居首位；因為你上了你父親的床，你上了我的榻，污辱了它！","notes":["「你」是根據七十士譯本和其他古譯本；原文是「他」。"]},{"n":5,"t":"西緬和利未是兄弟；他們的刀劍是殘暴的兵器。","notes":[]},{"n":6,"t":"願我的心不與他們同謀，願我的靈不與他們合夥；因為他們在烈怒中殺人，任意割斷牛腿的筋。","notes":["「靈」：原文是「榮耀」。"]},{"n":7,"t":"他們火爆的烈怒可詛，他們兇殘的憤恨可咒！我要把他們分散在雅各中，使他們散居在以色列。","notes":[]},{"n":8,"t":"猶大啊，你的兄弟必讚美你，你的手必掐住仇敵的頸項，你父親的兒子要向你下拜。","notes":[]},{"n":9,"t":"猶大是隻小獅子；我兒啊，你捕獲了獵物就上去。他蹲伏，他躺臥，如公獅，又如母獅，誰敢惹他呢？","notes":[]},{"n":10,"t":"權杖必不離猶大，統治者的杖必不離他兩腳之間，直等細羅來到，萬民都要歸順他。","notes":["「細羅」意思不清楚，可指「貢物」或「那應得權杖者」。"]},{"n":11,"t":"猶大把小驢拴在葡萄樹上，把驢駒拴在佳美的葡萄樹上。他在葡萄酒中洗衣服，在葡萄汁中洗長袍。","notes":["「汁」：原文是「血」。"]},{"n":12,"t":"他的眼睛比酒紅潤，他的牙齒比奶潔白。","notes":["「比」或譯「因」；下同。"]},{"n":13,"t":"西布倫必住在海邊，必成為停船的港口；他的疆界必延到西頓。","notes":[]},{"n":14,"t":"以薩迦是匹強壯的驢，臥在羊圈之中。","notes":[]},{"n":15,"t":"他看見居所安舒，土地肥美，就屈肩負重，成為服勞役的僕人。","notes":[]},{"n":16,"t":"但必為他的百姓伸冤，作為以色列支派之一。","notes":["「伸冤」與「但」的希伯來話發音相近。"]},{"n":17,"t":"但必作道旁的蛇，路邊的毒蛇，咬傷馬蹄，使騎馬的人向後墜落。","notes":[]},{"n":18,"t":"耶和華啊，我等候你的救恩。","notes":[]},{"n":19,"t":"迦得必被襲擊者襲擊，他卻要襲擊他們的腳跟。","notes":["「襲擊」與「迦得」的希伯來話發音相近。"]},{"n":20,"t":"亞設必出豐盛的糧食，要供應君王的佳肴。","notes":[]},{"n":21,"t":"拿弗他利是被釋放的母鹿，他要生出可愛的小鹿。","notes":["「可愛的小鹿」或譯「佳美的言語」。"]},{"n":22,"t":"約瑟是多結果子的樹枝，是泉旁多結果的枝子；他的枝條伸出牆外。","notes":[]},{"n":23,"t":"弓箭手惡意攻擊他，敵對他，向他射箭。","notes":[]},{"n":24,"t":"但他的弓仍舊堅硬，他的手臂靈活敏捷，這是因雅各的大能者的手，從那裏，他是以色列的牧者，以色列的磐石。","notes":["「從那裏...磐石」：原文另譯「因為以色列的牧者，以色列的磐石的名」；七十士譯本是「從那裏他降服了以色列」。"]},{"n":25,"t":"你父親的神必幫助你；全能者必賜福給你：天上的福，深淵下面蘊藏的福，以及生育哺養的福。","notes":[]},{"n":26,"t":"你父親的福勝過我祖先的福，直到永世山嶺的極限。這些福必降在約瑟的頭上，臨到那與兄弟有分別之人的頭頂上。","notes":[]},{"n":27,"t":"便雅憫是隻抓撕掠物的狼，早晨要吃他的獵物，晚上要分他的擄物。」","notes":[]},{"n":28,"t":"這一切是以色列的十二個支派。這是他們的父親對他們所說的話，他按照各人的福分為他們祝福。","notes":[]},{"n":29,"t":"他又吩咐他們說：「我快要歸到我祖先那裏。你們要將我葬在赫人以弗崙田間的洞裏，與我的祖先在一處，","notes":["「我祖先」：原文是「我百姓」。"],"heads":["雅各的死和安葬"]},{"n":30,"t":"就是在迦南地幔利對面的麥比拉田間的洞裏，那田是亞伯拉罕向赫人以弗崙買來作墳地的產業。","notes":[]},{"n":31,"t":"亞伯拉罕和他的妻子撒拉葬在那裏；以撒和他的妻子利百加也葬在那裏。我也在那裏葬了利亞。","notes":[]},{"n":32,"t":"那塊田和田間的洞是向赫人買的。」","notes":[]},{"n":33,"t":"雅各囑咐眾子完畢後，就把腳收在床上斷了氣，歸到他祖先那裏去了。","notes":["「他祖先」：原文是「他百姓」。"]}]},"50":{"heading":"約瑟安慰哥哥們","verses":[{"n":1,"t":"約瑟伏在他父親的臉上，在他臉上哭，又親他。","notes":[]},{"n":2,"t":"約瑟吩咐伺候他的醫生們用香料塗他父親，醫生就用香料塗了以色列。","notes":[]},{"n":3,"t":"四十天滿了，就是塗香料所規定的日子滿了。埃及人為他哀哭了七十天。","notes":[]},{"n":4,"t":"過了哀悼的日子，約瑟對法老家中的人說：「我若在你們眼前蒙恩，請你們對法老說：","notes":[]},{"n":5,"t":"『我父親曾叫我起誓說：看哪，我快要死了，你要將我葬在迦南地，在我為自己所掘的墳墓裏。』現在求你准我上去葬我父親，然後我必回來。」","notes":[]},{"n":6,"t":"法老說：「你可以上去，照你父親叫你起的誓，將他安葬。」","notes":[]},{"n":7,"t":"於是約瑟上去葬他父親。與他一同上去的有法老的眾臣僕和法老家中的長老，以及埃及地所有的長老，","notes":[]},{"n":8,"t":"還有約瑟的全家和他的兄弟們，以及他父親的家屬；只留下他們的孩子和羊群牛群在歌珊地。","notes":[]},{"n":9,"t":"又有車輛和駕駛兵和他一同上去，隊伍非常龐大。","notes":[]},{"n":10,"t":"他們到了約旦河東亞達的禾場，就在那裏大大地號咷痛哭。約瑟為他父親哀哭了七天。","notes":[]},{"n":11,"t":"迦南的居民看見亞達禾場上的哀哭，就說：「這是埃及人一場極大的哀哭。」因此那地方名叫亞伯‧麥西，是在約旦河東。","notes":["「亞伯‧麥西」意思是「埃及人的哀哭」。"]},{"n":12,"t":"雅各的兒子們遵照父親的吩咐去辦了，","notes":[]},{"n":13,"t":"他們把他送到迦南地，葬在幔利對面的麥比拉田間的洞裏；那田是亞伯拉罕向赫人以弗崙買來作墳地的產業。","notes":[]},{"n":14,"t":"約瑟葬了他父親以後，就和他的兄弟，以及所有同他上去葬他父親的人，都回埃及去了。","notes":[]},{"n":15,"t":"約瑟的哥哥們見父親死了，就說：「也許約瑟仍然懷恨我們，會照我們從前待他一切的惡，重重報復我們。」","notes":[]},{"n":16,"t":"他們就傳口信給約瑟說：「你父親未死之前曾吩咐說：","notes":[]},{"n":17,"t":"『你們要對約瑟這樣說：從前你哥哥們惡待你，你要饒恕他們的過犯和罪惡。』現在求你饒恕你父親的神之僕人們的過犯。」他們對約瑟說了這話，約瑟就哭了。","notes":[]},{"n":18,"t":"他的哥哥們又來俯伏在他面前，說：「看哪，我們是你的奴隸。」","notes":[]},{"n":19,"t":"約瑟對他們說：「不要怕，我豈能代替神呢？","notes":[]},{"n":20,"t":"從前你們的意思是要害我，但神的意思原是好的，要使許多百姓得以存活，成就今日的光景。","notes":[]},{"n":21,"t":"現在你們不要害怕，我必養活你們和你們的孩子。」於是約瑟安慰他們，講了使他們安心的話。","notes":[]},{"n":22,"t":"約瑟和他父親的家屬都住在埃及。約瑟活了一百一十年。","notes":[],"heads":["約瑟的死"]},{"n":23,"t":"約瑟看到以法蓮第三代的子孫。瑪拿西的孫子，瑪吉的兒子，出生時都放在約瑟的膝上。","notes":[]},{"n":24,"t":"約瑟對他的兄弟說：「我快要死了，但神必定看顧你們，領你們從這地上去，到他起誓應許給亞伯拉罕、以撒、雅各之地。」","notes":[]},{"n":25,"t":"約瑟叫以色列的子孫起誓：「神必定眷顧你們，你們要把我的骸骨從這裏帶上去。」","notes":[]},{"n":26,"t":"約瑟死了，那時他一百一十歲。人用香料塗了他，把他收殮在棺材裏，停放在埃及。","notes":[]}]}},"EXO":{"1":{"heading":"以色列人生養眾多","verses":[{"n":1,"t":"以色列的眾兒子各帶著家眷，和雅各一同來到埃及，他們的名字如下：","notes":[]},{"n":2,"t":"呂便、西緬、利未、猶大、","notes":[]},{"n":3,"t":"以薩迦、西布倫、便雅憫、","notes":[]},{"n":4,"t":"但、拿弗他利、迦得、亞設。","notes":[]},{"n":5,"t":"凡從雅各生的，共有七十人。那時，約瑟已經在埃及。","notes":[]},{"n":6,"t":"約瑟和他所有的兄弟，以及那一代的人都死了。","notes":[]},{"n":7,"t":"然而，以色列人生養眾多，繁衍昌盛，極其強盛，遍滿了那地。","notes":[]},{"n":8,"t":"有一位不認識約瑟的新王興起，統治埃及。","notes":[],"heads":["以色列人受虐待"]},{"n":9,"t":"他對自己的百姓說：「看哪，以色列人的百姓比我們還多，又比我們強盛。","notes":[]},{"n":10,"t":"來吧，讓我們機巧地待他們，恐怕他們增多起來，將來若有戰爭，他們就聯合我們的仇敵來攻擊我們，然後離開這地去了。」","notes":[]},{"n":11,"t":"於是埃及人派監工管轄他們，用勞役苦待他們。他們為法老建造儲貨城，就是比東和蘭塞。","notes":[]},{"n":12,"t":"可是越苦待他們，他們就越發增多，更加繁衍，埃及人就因以色列人愁煩。","notes":[]},{"n":13,"t":"埃及人嚴厲地強迫以色列人做工，","notes":[]},{"n":14,"t":"使他們因苦工而生活痛苦；無論是和泥，是做磚，是做田間各樣的工，一切的工埃及人都嚴厲地對待他們。","notes":[]},{"n":15,"t":"埃及王又對希伯來的接生婆，一個名叫施弗拉，另一個名叫普阿的說：","notes":[]},{"n":16,"t":"「你們為希伯來婦人接生，臨盆的時候要注意，若是男的，就把他殺了，若是女的，就讓她活。」","notes":["「臨盆的時候要注意」：原文直譯「要注意那石凳」或「要注意那兩顆石頭」。"]},{"n":17,"t":"但是接生婆敬畏神，不照埃及王的吩咐去做，卻讓男孩活著。","notes":[]},{"n":18,"t":"埃及王召了接生婆來，對她們說：「你們為甚麼做這事，讓男孩活著呢？」","notes":[]},{"n":19,"t":"接生婆對法老說：「因為希伯來婦人與埃及婦人不同；希伯來婦人健壯，接生婆還沒有到，她們已經生產了。」","notes":[]},{"n":20,"t":"神恩待接生婆；以色列人增多起來，極其強盛。","notes":[]},{"n":21,"t":"接生婆因為敬畏神，神就叫她們成立家室。","notes":[]},{"n":22,"t":"法老吩咐他的眾百姓說：「把所生的每一個男孩都丟到尼羅河裏去，讓所有的女孩存活。」","notes":["「所生的」：有些古卷、七十士譯本和其他古譯本是「希伯來人所生的」。"]}]},"2":{"heading":"摩西的出生","verses":[{"n":1,"t":"有一個利未家的人娶了一個利未女子為妻。","notes":[]},{"n":2,"t":"那女人懷孕，生了一個兒子，見他俊美，就把他藏了三個月，","notes":[]},{"n":3,"t":"後來不能再藏，就取了一個蒲草箱，抹上柏油和樹脂，將孩子放在裏面，把箱子擱在尼羅河邊的蘆葦中。","notes":[]},{"n":4,"t":"孩子的姊姊遠遠站著，要知道他究竟會怎樣。","notes":[]},{"n":5,"t":"法老的女兒來到尼羅河邊洗澡，她的女僕們在河邊行走。她看見在蘆葦中的箱子，就派一個使女把它拿來。","notes":[]},{"n":6,"t":"她打開箱子，看見那孩子。看哪，男孩在哭，她就可憐他，說：「這是希伯來人的一個孩子。」","notes":[]},{"n":7,"t":"孩子的姊姊對法老的女兒說：「我去叫一個希伯來婦人來作奶媽，替你乳養這孩子，好嗎？」","notes":[]},{"n":8,"t":"法老的女兒對她說：「去吧！」那女孩就去叫了孩子的母親來。","notes":[]},{"n":9,"t":"法老的女兒對她說：「你把這孩子抱去，替我乳養這孩子，我必給你工錢。」那婦人就把孩子接過來，乳養他。","notes":[]},{"n":10,"t":"孩子長大了，婦人把他帶到法老的女兒那裏，就作了她的兒子。她給孩子起名叫摩西，說：「因我把他從水裏拉出來。」","notes":[]},{"n":11,"t":"過了一段日子，摩西長大了，他出去到他同胞那裏，看見他們的勞役。他看見一個埃及人打他的同胞，一個希伯來人。","notes":[],"heads":["摩西逃往米甸"]},{"n":12,"t":"他左右觀看，見沒有人，就把埃及人打死了，藏在沙土裏。","notes":[]},{"n":13,"t":"第二天他出去，看哪，有兩個希伯來人在打架，他就對那兇惡的人說：「你為甚麼打你同族的人呢？」","notes":[]},{"n":14,"t":"那人說：「誰立你作我們的領袖和審判官呢？難道你要殺我，像殺那埃及人一樣嗎？」摩西就懼怕，說：「這事一定是讓人知道了。」","notes":[]},{"n":15,"t":"法老聽見這事，就設法要殺摩西。於是摩西逃走，躲避法老，到了米甸地，坐在井旁。","notes":[]},{"n":16,"t":"米甸的祭司有七個女兒；她們來打水，打滿了槽，要給父親的羊群喝水。","notes":[]},{"n":17,"t":"有一些牧羊人來，把她們趕走，摩西卻起來幫助她們，取水給她們的羊群喝。","notes":[]},{"n":18,"t":"她們回到父親流珥那裏；他說：「今日你們為何這麼快就回來了呢？」","notes":[]},{"n":19,"t":"她們說：「有一個埃及人來救我們脫離牧羊人的手，他甚至打水給我們的羊群喝。」","notes":[]},{"n":20,"t":"他對女兒們說：「那人在哪裏？你們為甚麼撇下他呢？去請他來吃飯吧！」","notes":[]},{"n":21,"t":"摩西願意和那人同住， 那人就把女兒西坡拉給摩西為妻。","notes":[]},{"n":22,"t":"西坡拉生了一個兒子，摩西給他起名叫革舜，因他說：「我在外地作了寄居者。」","notes":[]},{"n":23,"t":"過了許多年，埃及王死了。以色列人因做苦工，就嘆息哀求；他們因苦工所發出的哀聲達於神。","notes":[]},{"n":24,"t":"神聽見他們的哀聲，就記念他與亞伯拉罕、以撒、雅各所立的約。","notes":[]},{"n":25,"t":"神看顧以色列人，神是知道的。","notes":["「神是知道的」：七十士譯本是「神是他們所知道的」。"]}]},"3":{"heading":"神呼召摩西","verses":[{"n":1,"t":"摩西牧放他岳父米甸祭司葉特羅的羊群，他領羊群往曠野的那一邊去，到了神的山，就是何烈山。","notes":[]},{"n":2,"t":"耶和華的使者在荊棘的火焰中向他顯現。摩西觀看，看哪，荊棘在火中焚燒，卻沒有燒燬。","notes":[]},{"n":3,"t":"摩西說：「我要轉過去看這大異象，這荊棘為何沒有燒燬呢？」","notes":[]},{"n":4,"t":"耶和華見摩西轉過去看，神就從荊棘裏呼叫他說：「摩西！摩西！」他說：「我在這裏。」","notes":[]},{"n":5,"t":"神說：「不要靠近這裏。把你腳上的鞋脫下來，因為你所站的地方是聖地」。","notes":[]},{"n":6,"t":"他又說：「我是你父親的神，是亞伯拉罕的神，以撒的神，雅各的神。」摩西蒙上臉，因為怕看神。","notes":[]},{"n":7,"t":"耶和華說：「我確實看見了我百姓在埃及所受的困苦，我也聽見了他們因受監工苦待所發的哀聲；我確實知道他們的痛苦。","notes":[]},{"n":8,"t":"我下來是要救他們脫離埃及人的手，領他們從那地上來，到美好與寬闊之地，到流奶與蜜之地，就是迦南人、赫人、亞摩利人、比利洗人、希未人、耶布斯人之地。","notes":[]},{"n":9,"t":"現在，看哪，以色列人的哀聲達到我這裏，我也看見埃及人怎樣欺壓他們。","notes":[]},{"n":10,"t":"現在，你去，我要差派你到法老那裏，把我的百姓以色列人從埃及領出來。」","notes":[]},{"n":11,"t":"摩西對神說：「我是甚麼人，竟能去見法老，把以色列人從埃及領出來呢？」","notes":[]},{"n":12,"t":"神說：「我必與你同在。這就是我差派你去，給你的憑據：你把百姓從埃及領出來之後，你們必在這山上事奉神。」","notes":[]},{"n":13,"t":"摩西對神說：「看哪，我到以色列人那裏，對他們說：『你們祖宗的神差派我到你們這裏來。』他們若對我說：『他叫甚麼名字？』我要對他們說甚麼呢？」","notes":[]},{"n":14,"t":"神對摩西說：「我是自有永有的」；又說：「你要對以色列人這樣說：『那自有永有的差派我到你們這裏來。』」","notes":[]},{"n":15,"t":"神又對摩西說：「你要對以色列人這樣說：『耶和華－你們祖宗的神，就是亞伯拉罕的神，以撒的神，雅各的神差派我到你們這裏來。』這是我的名，直到永遠；這也是我的稱號，直到萬代。","notes":["「稱號」或譯「紀念」。"]},{"n":16,"t":"你去召集以色列的長老，對他們說：『耶和華－你們祖宗的神，就是亞伯拉罕的神，以撒的神，雅各的神向我顯現，說：我實在眷顧了你們，眷顧你們在埃及的遭遇。","notes":[]},{"n":17,"t":"我也曾說：要把你們從埃及的困苦中領出來，往迦南人、赫人、亞摩利人、比利洗人、希未人、耶布斯人的地去，就是到流奶與蜜之地。』","notes":[]},{"n":18,"t":"他們必聽你的話。你和以色列的長老要到埃及王那裏，對他說：『耶和華－希伯來人的神向我們顯現，現在求你讓我們往曠野去，走三天的路程，為要向耶和華我們的神獻祭。』","notes":[]},{"n":19,"t":"我知道若不用大能的手，埃及王不會放你們走。","notes":[]},{"n":20,"t":"因此，我必伸出我的手，在埃及施行我一切的神蹟，擊打這地，然後，他才放你們走。","notes":[]},{"n":21,"t":"我必使埃及人看得起你們，你們離開的時候就不至於空手而去。","notes":[]},{"n":22,"t":"每一個婦女必向她的鄰舍，以及寄居在她家裏的女人，索取金器、銀器和衣裳，給你們的兒女穿戴。這樣你們就掠奪了埃及人。」","notes":[]}]},"4":{"heading":"摩西行神蹟的權能","verses":[{"n":1,"t":"摩西回答說：「看哪！他們不會信我，也不會聽我的話，因為他們必說：『耶和華並沒有向你顯現。』」","notes":[]},{"n":2,"t":"耶和華對摩西說：「你手裏的是甚麼？」他說：「是杖。」","notes":[]},{"n":3,"t":"耶和華說：「把它丟在地上！」他一丟在地上，杖就變成一條蛇；摩西逃走避開牠。","notes":[]},{"n":4,"t":"耶和華對摩西說：「伸出手來，拿住牠的尾巴─摩西就伸出手，抓住牠，牠就在摩西的手掌中變為杖─","notes":[]},{"n":5,"t":"為了要使他們信耶和華他們祖宗的神，就是亞伯拉罕的神，以撒的神，雅各的神，曾向你顯現了。」","notes":[]},{"n":6,"t":"耶和華又對他說：「把手放進懷裏。」他就把手放進懷裏。當他把手抽出來，看哪，手竟然長了痲瘋，像雪一樣白。","notes":["「痲瘋」泛指傳染性皮膚病。"]},{"n":7,"t":"耶和華說：「把手放回懷裏─他就把手放回懷裏。當他把手從懷裏再抽出來，看哪，手復原了，與全身的肉一樣─","notes":[]},{"n":8,"t":"倘若他們不信你，也不聽第一個神蹟的聲音，他們會信第二個神蹟的聲音。","notes":[]},{"n":9,"t":"倘若他們不信這兩個神蹟，不聽你的話，你就從尼羅河裏取些水，倒在乾的地上。你從尼羅河裏所取的水必在乾地上變成血。」","notes":[]},{"n":10,"t":"摩西對耶和華說：「主啊，求求你，我並不是一個能言善道的人，以前這樣，就是你對僕人說話以後也是這樣，因為我是拙口笨舌的。」","notes":[]},{"n":11,"t":"耶和華對他說：「誰造人的口呢？誰使人口啞、耳聾、目明、眼瞎呢？豈不是我－耶和華嗎？","notes":[]},{"n":12,"t":"現在，去吧，我必賜你口才，指教你應當說的。」","notes":[]},{"n":13,"t":"摩西說：「主啊，求求你，你要藉著誰的手，就差派誰去吧！」","notes":[]},{"n":14,"t":"耶和華的怒氣向摩西發作，說：「你不是有一個哥哥利未人亞倫嗎？我知道他是個能言善道的人。看哪，他正出來迎接你。他一見到你，心裏就歡喜。","notes":[]},{"n":15,"t":"你要跟他說話，把話放在他的口裏，我要賜你口才，也要賜他口才，又要教你們做當做的事。","notes":[]},{"n":16,"t":"他要替你向百姓說話；他要當你的口，你要當他的神。","notes":[]},{"n":17,"t":"你手裏要拿這杖，用它來行神蹟。」","notes":[]},{"n":18,"t":"於是，摩西回到他岳父葉特羅那裏，對他說：「請你讓我回埃及我同胞那裏，看他們還在不在。」葉特羅對摩西說：「平平安安地去吧！」","notes":[],"heads":["摩西返回埃及"]},{"n":19,"t":"耶和華在米甸對摩西說：「你要回埃及去，因為那些尋索你命的人都死了。」","notes":[]},{"n":20,"t":"摩西就帶著妻子和兩個兒子，讓他們騎上驢，回埃及地去。摩西手裏拿著神的杖。","notes":[]},{"n":21,"t":"耶和華對摩西說：「你回到埃及去的時候，要留意將我交在你手中的一切奇事行在法老面前。但我要任憑他的心剛硬，他必不放百姓走。","notes":[]},{"n":22,"t":"你要對法老說：『耶和華如此說：以色列是我的兒子，我的長子。","notes":[]},{"n":23,"t":"我對你說過：放我的兒子走，好事奉我。你還是不肯放他走。看哪，我要殺你頭生的兒子。』」","notes":[]},{"n":24,"t":"在路上住宿的地方，耶和華遇見摩西，想要殺他。","notes":[]},{"n":25,"t":"西坡拉就拿一塊火石，割下她兒子的包皮，碰觸摩西的腳，說：「你真是我血的新郎了。」","notes":["「碰觸...新郎了。」或譯「碰觸她兒子的腳，說：『你真是我受割禮的孩子了。』」"]},{"n":26,"t":"這樣，耶和華才放了他。那時，西坡拉說：「你因割禮就是血的新郎了」。","notes":["「血的新郎」或譯「受割禮的孩子」。"]},{"n":27,"t":"耶和華對亞倫說：「你往曠野去迎接摩西。」他就去，在神的山遇見摩西，就親他。","notes":[]},{"n":28,"t":"摩西將耶和華差派他所說的話和吩咐他所行的神蹟都告訴了亞倫。","notes":[]},{"n":29,"t":"摩西和亞倫就去召集以色列的眾長老。","notes":[]},{"n":30,"t":"亞倫將耶和華對摩西所說的一切話述說了一遍，又在百姓眼前行了那些神蹟，","notes":[]},{"n":31,"t":"百姓就信了。他們聽見耶和華眷顧以色列人，鑒察他們的困苦，就低頭敬拜。","notes":[]}]},"5":{"heading":"摩西和亞倫見埃及法老","verses":[{"n":1,"t":"後來，摩西和亞倫去對法老說：「耶和華－以色列的神這樣說：『放我的百姓走，好讓他們在曠野向我守節。』」","notes":[]},{"n":2,"t":"法老說：「耶和華是誰，要我聽他的話，讓以色列人去？我不認識耶和華，也不放以色列人走！」","notes":[]},{"n":3,"t":"他們說：「希伯來人的神已向我們顯現了。求你讓我們往曠野去，走三天的路程，向耶和華我們的神獻祭，免得他用瘟疫、刀劍攻擊我們。」","notes":[]},{"n":4,"t":"埃及王對他們說：「摩西、亞倫！你們為甚麼叫百姓不做工呢？去，服你們的勞役吧！」","notes":[]},{"n":5,"t":"他又說：「看哪，這地的以色列人如今這麼多，你們竟然叫他們歇下勞役！」","notes":[]},{"n":6,"t":"當天，法老吩咐監工和工頭說：","notes":[]},{"n":7,"t":"「你們不可照以前一樣提供草給百姓做磚，要叫他們自己去撿草。","notes":[]},{"n":8,"t":"他們平時做磚的數目，你們仍舊向他們要，一點不可減少，因為他們是懶惰的，所以才呼求說：『讓我們去向我們的神獻祭。』","notes":[]},{"n":9,"t":"你們要把更重的工作加在這些人身上，使他們在其中勞碌，不去理會謊言。」","notes":[]},{"n":10,"t":"監工和工頭出來對百姓說：「法老這樣說：『我不給你們草，","notes":[]},{"n":11,"t":"你們自己在哪裏能找到草，就往哪裏去找吧！但你們的工作一點也不可減少。』」","notes":[]},{"n":12,"t":"於是，百姓分散在埃及全地，撿碎稭當草用。","notes":[]},{"n":13,"t":"監工催逼他們，說：「你們每天要做完一天的工，與先前有草一樣。」","notes":[]},{"n":14,"t":"法老的監工擊打他們所派的以色列工頭，說：「為甚麼昨天和今天你們沒有按照以前做磚的數目，完成你們的工作呢？」","notes":[]},{"n":15,"t":"以色列人的工頭來哀求法老說：「為甚麼這樣待你的僕人呢？","notes":[]},{"n":16,"t":"監工不把草給僕人，並且對我們說：『做磚吧！』看哪，你僕人挨了打，其實是你百姓的錯。」","notes":[]},{"n":17,"t":"法老卻說：「懶惰，你們真是懶惰！所以你們說：『讓我們去向耶和華獻祭吧。』","notes":[]},{"n":18,"t":"現在，去做工吧！草是不會給你們，磚卻要如數交納。」","notes":[]},{"n":19,"t":"以色列人的工頭聽見「你們每天做磚的工作一點也不可減少」，就知道惹上禍了。","notes":[]},{"n":20,"t":"他們離開法老出來，正遇見摩西和亞倫站在那裏等候他們，","notes":[]},{"n":21,"t":"就向他們說：「願耶和華鑒察你們，施行判斷，因為你們使我們在法老和他臣僕面前有了臭名，把刀遞在他們手中來殺我們。」","notes":[]},{"n":22,"t":"摩西回到耶和華那裏，說：「主啊，你為甚麼苦待這百姓呢？為甚麼差派我呢？","notes":[]},{"n":23,"t":"自從我到法老那裏，奉你的名說話，他就苦待這百姓，你卻一點也沒有拯救你的百姓。」","notes":[]}]},"6":{"heading":"神應許拯救以色列","verses":[{"n":1,"t":"耶和華對摩西說：「現在你必看見我向法老所行的事，使他因我大能的手放以色列人走，因我大能的手把他們趕出他的地。」","notes":[]},{"n":2,"t":"神吩咐摩西，對他說：「我是耶和華。","notes":[]},{"n":3,"t":"我從前向亞伯拉罕、以撒、雅各顯現為全能的神；至於我的名耶和華，我未曾讓他們知道。","notes":[]},{"n":4,"t":"我要與他們堅立我的約，要把迦南地，他們寄居的地賜給他們。","notes":[]},{"n":5,"t":"我聽見以色列人被埃及人奴役的哀聲，我就記念我的約。","notes":[]},{"n":6,"t":"所以你要對以色列人說：『我是耶和華；我要除去埃及人加給你們的勞役，救你們脫離他們的奴役。我要用伸出來的膀臂，藉嚴厲的懲罰救贖你們。","notes":[]},{"n":7,"t":"我要以你們為我的百姓，我也要作你們的神。我除去埃及人加給你們的勞役，你們就知道我是耶和華你們的神。","notes":[]},{"n":8,"t":"我起誓應許給亞伯拉罕、以撒、雅各的地，我要領你們進去，將那地賜給你們為業。我是耶和華。』」","notes":[]},{"n":9,"t":"摩西把這話告訴以色列人，但是他們因心裏愁煩，又因苦工，就不肯聽摩西的話。","notes":[]},{"n":10,"t":"耶和華吩咐摩西說：","notes":[]},{"n":11,"t":"「你去對埃及王法老說，讓以色列人離開他的地。」","notes":[]},{"n":12,"t":"摩西在耶和華面前說：「看哪，以色列人尚且不聽我，法老怎麼會聽我這不會講話的人呢？」","notes":[]},{"n":13,"t":"耶和華吩咐摩西和亞倫，命令他們到以色列人和埃及王法老那裏，把以色列人從埃及地領出來。","notes":[]},{"n":14,"t":"以色列人族長的名字如下：以色列長子呂便的兒子是哈諾、法路、希斯倫、迦米；這是呂便的家族。","notes":[],"heads":["亞倫和摩西的家譜"]},{"n":15,"t":"西緬的兒子是耶母利、雅憫、阿轄、雅斤、瑣轄，和迦南女子生的兒子掃羅；這是西緬的家族。","notes":[]},{"n":16,"t":"以下是利未的兒子按著家譜的名字：革順、哥轄、米拉利。利未一生的歲數是一百三十七歲。","notes":[]},{"n":17,"t":"革順的兒子按著家族是立尼、示每。","notes":[]},{"n":18,"t":"哥轄的兒子是暗蘭、以斯哈、希伯倫、烏薛。哥轄一生的歲數是一百三十三歲。","notes":[]},{"n":19,"t":"米拉利的兒子是抹利和母示；這是利未按著家譜的家族。","notes":[]},{"n":20,"t":"暗蘭娶了他父親的妹妹約基別為妻，她為他生了亞倫和摩西。暗蘭一生的歲數是一百三十七歲。","notes":[]},{"n":21,"t":"以斯哈的兒子是可拉、尼斐、細基利。","notes":[]},{"n":22,"t":"烏薛的兒子是米沙利、以利撒反、西提利。","notes":[]},{"n":23,"t":"亞倫娶了亞米拿達的女兒，拿順的妹妹，以利沙巴為妻，她為他生了拿答、亞比戶、以利亞撒、以他瑪。","notes":[]},{"n":24,"t":"可拉的兒子是亞惜、以利加拿、亞比亞撒；這是可拉的家族。","notes":[]},{"n":25,"t":"亞倫的兒子以利亞撒娶了普鐵的一個女兒為妻，她為他生了非尼哈。這是利未人按著家族的族長。","notes":[]},{"n":26,"t":"這就是曾聽見耶和華說「把以色列人按著隊伍從埃及地領出來」的亞倫和摩西，","notes":[]},{"n":27,"t":"對埃及王法老說要將以色列人從埃及領出來的，也是這摩西和亞倫。","notes":[]},{"n":28,"t":"當耶和華在埃及地對摩西說話的時候，","notes":[],"heads":["摩西和亞倫奉命去見法老"]},{"n":29,"t":"耶和華對摩西說：「我是耶和華；我對你所說的一切話，你都要告訴埃及王法老。」","notes":[]},{"n":30,"t":"摩西在耶和華面前說：「看哪，我是不會講話的人，法老怎麼會聽我呢？」","notes":[]}]},"7":{"heading":"亞倫的杖","verses":[{"n":1,"t":"耶和華對摩西說：「我使你在法老面前像神一樣，你的哥哥亞倫是你的代言人。","notes":["「代言人」：原文是「先知」。"]},{"n":2,"t":"凡我所吩咐你的，你都要說。你的哥哥亞倫要對法老說，讓以色列人離開他的地。","notes":[]},{"n":3,"t":"我要使法老的心固執，我也要在埃及地多行神蹟奇事。","notes":[]},{"n":4,"t":"法老必不聽從你們，因此我要伸手嚴厲地懲罰埃及，把我的軍隊，就是我的百姓以色列人從埃及地領出來。","notes":[]},{"n":5,"t":"我伸手攻擊埃及，把以色列人從他們中間領出來的時候，埃及人就知道我是耶和華。」","notes":[]},{"n":6,"t":"摩西和亞倫就去做；他們照耶和華吩咐的去做了。","notes":[]},{"n":7,"t":"摩西和亞倫與法老說話的時候，摩西八十歲，亞倫八十三歲。","notes":[]},{"n":8,"t":"耶和華對摩西和亞倫說：","notes":[]},{"n":9,"t":"「法老若吩咐你們說：『你們行一件奇事吧！』你就對亞倫說：『把杖丟在法老面前！杖會變成蛇。』」","notes":[]},{"n":10,"t":"摩西和亞倫到法老那裏去，照耶和華所吩咐的去做。亞倫把杖丟在法老和他臣僕面前，杖就變成蛇。","notes":[]},{"n":11,"t":"法老也召了智慧人和行邪術的人來，這些埃及術士也用邪術照樣做。","notes":[]},{"n":12,"t":"他們各人丟下自己的杖，杖就變成蛇；但亞倫的杖吞了他們的杖。","notes":[]},{"n":13,"t":"法老心裏剛硬，不聽摩西和亞倫，正如耶和華所說的。","notes":[]},{"n":14,"t":"耶和華對摩西說：「法老心硬，不肯放百姓走。","notes":[],"heads":["第一災：水變血"]},{"n":15,"t":"明天早晨你要到法老那裏去，看哪，他出來往水邊去，你要到尼羅河邊去迎見他，手裏拿著那根變過蛇的杖。","notes":[]},{"n":16,"t":"你要對他說：『耶和華－希伯來人的神差派我到你這裏，說：放我的百姓走，到曠野事奉我。看哪，到如今你還是不聽。","notes":[]},{"n":17,"t":"耶和華如此說：看哪，我要用我手裏的杖擊打尼羅河中的水，水就變成血；這樣，你就知道我是耶和華。","notes":[]},{"n":18,"t":"河裏的魚必死，河也要發臭，埃及人就厭惡喝這河裏的水。』」","notes":[]},{"n":19,"t":"耶和華對摩西說：「你要對亞倫說：『拿你的杖，伸出你的手在埃及所有的水上，在他們的江、河、池塘，所有水聚集的地方上，叫水變成血。在埃及全地，無論在木器中，石器中，都必有血。』」","notes":[]},{"n":20,"t":"摩西和亞倫就照耶和華所吩咐的去做。亞倫在法老和他臣僕眼前舉杖擊打尼羅河裏的水，河裏的水都變成血了。","notes":[]},{"n":21,"t":"河裏的魚死了，河也臭了，埃及人就不能喝這河裏的水；埃及遍地都有了血。","notes":[]},{"n":22,"t":"但是，埃及的術士也用邪術照樣做了；法老心裏剛硬，不聽摩西和亞倫，正如耶和華所說的。","notes":[]},{"n":23,"t":"法老轉身回宮去，並不把這事放在心上。","notes":[]},{"n":24,"t":"所有的埃及人都沿著尼羅河邊挖掘，要找水喝，因為他們不能喝河裏的水。","notes":[]},{"n":25,"t":"耶和華擊打尼羅河後，過了七天。","notes":[]}]},"8":{"heading":"第二災：蛙災","verses":[{"n":1,"t":"耶和華對摩西說：「你要到法老那裏，對他說：『耶和華如此說：放我的百姓走，好事奉我。","notes":[]},{"n":2,"t":"你若不肯放他們走，看哪，我必以青蛙之災擊打你的疆土。","notes":[]},{"n":3,"t":"尼羅河要滋生青蛙；這青蛙要上來進你的宮殿和你的臥房，上你的床榻，進你臣僕的房屋，上你百姓的身上，進你的爐灶和你的揉麵盆。","notes":[]},{"n":4,"t":"這些青蛙要跳上你、你百姓和你眾臣僕的身上。』」","notes":[]},{"n":5,"t":"耶和華對摩西說：「你要對亞倫說：『伸出你手裏的杖在江、河、池塘上，把青蛙帶上埃及地來。』」","notes":[]},{"n":6,"t":"亞倫伸手在埃及的眾水上，青蛙就上來，遮滿了埃及地。","notes":[]},{"n":7,"t":"術士也用他們的邪術照樣去做，把青蛙帶上埃及地。","notes":[]},{"n":8,"t":"法老召摩西和亞倫來，說：「請你們祈求耶和華使這些青蛙離開我和我的百姓，我就讓這百姓去向耶和華獻祭。」","notes":[]},{"n":9,"t":"摩西對法老說：「悉聽尊便，告訴我何時為你、你臣僕和你的百姓祈求，使青蛙被剪除，離開你和你的宮殿，只留在尼羅河裏。」","notes":[]},{"n":10,"t":"他說：「明天。」摩西說：「就照你的話吧，為要叫你知道沒有像耶和華我們神的，","notes":[]},{"n":11,"t":"青蛙必會離開你、你宮殿、你臣僕和你的百姓，只留在尼羅河裏。」","notes":[]},{"n":12,"t":"於是摩西和亞倫離開法老出去。摩西為了青蛙的事呼求耶和華，因為他帶來青蛙攪擾法老。","notes":[]},{"n":13,"t":"耶和華就照摩西的請求去做；在屋裏、院中、田間的青蛙都死了。","notes":[]},{"n":14,"t":"眾人把青蛙聚攏成堆，地就發出臭氣。","notes":[]},{"n":15,"t":"但法老見災禍舒緩了，就硬著心，不聽從他們，正如耶和華所說的。","notes":[]},{"n":16,"t":"耶和華對摩西說：「你要對亞倫說：『伸出你的杖擊打地上的塵土，使塵土在埃及全地變成蚊子。』」","notes":["「蚊子」：有古譯本是「虱子」或「虼蚤」或「蟲」；下同。"],"heads":["第三災：蚊災"]},{"n":17,"t":"他們就照樣做了。亞倫伸出他手裏的杖，擊打地上的塵土，人和牲畜身上就有了蚊子；埃及全地的塵土都變成蚊子了。","notes":[]},{"n":18,"t":"術士也用邪術要照樣產生蚊子，卻做不成。於是人和牲畜的身上都有了蚊子。","notes":[]},{"n":19,"t":"術士對法老說：「這是神的手指。」法老心裏剛硬，不聽摩西和亞倫，正如耶和華所說的。","notes":[]},{"n":20,"t":"耶和華對摩西說：「你要清早起來，站在法老面前。看哪，法老來到水邊，你就對他說：『耶和華如此說：放我的百姓走，好事奉我。","notes":[],"heads":["第四災： 蠅災"]},{"n":21,"t":"你若不放我的百姓走，看哪，我要派成群的蒼蠅到你、你臣僕和你百姓身上，進你的宮殿；埃及人的房屋和他們所住的地都要滿了成群的蒼蠅。","notes":[]},{"n":22,"t":"那一日，我必把我百姓所住的歌珊地分別出來，使那裏沒有成群的蒼蠅，好叫你知道我─耶和華是在全地之中。","notes":[]},{"n":23,"t":"我要施行救贖，區隔我的百姓和你的百姓。明天必有這神蹟。』」","notes":[]},{"n":24,"t":"耶和華就這樣做了。大群的蒼蠅進入法老的宮殿和他臣僕的房屋；在埃及全地，地就因這成群的蒼蠅毀壞了。","notes":[]},{"n":25,"t":"法老召了摩西和亞倫來，說：「去，在此地向你們的神獻祭。」","notes":[]},{"n":26,"t":"摩西說：「這樣做是不妥的，因為我們要獻給耶和華－我們神的祭物是埃及人所厭惡的；看哪，我們在埃及人眼前獻他們所厭惡的，他們豈不拿石頭打死我們嗎？","notes":[]},{"n":27,"t":"我們要遵照耶和華－我們神所吩咐我們的，往曠野去，走三天路程，向他獻祭。」","notes":[]},{"n":28,"t":"法老說：「我可以放你們走，在曠野向耶和華－你們的神獻祭，只是不可走得太遠。你們要為我祈禱。」","notes":[]},{"n":29,"t":"摩西說：「看哪，我要從你這裏出去祈求耶和華，使成群的蒼蠅明天離開法老、法老的臣僕和法老的百姓；法老卻不可再欺騙，不讓百姓去向耶和華獻祭。」","notes":[]},{"n":30,"t":"於是摩西離開法老，去祈求耶和華。","notes":[]},{"n":31,"t":"耶和華就照摩西的請求去做，使成群的蒼蠅離開法老、他的臣僕和他的百姓，一隻也沒有留下。","notes":[]},{"n":32,"t":"但這一次法老又硬著心，不放百姓走。","notes":[]}]},"9":{"heading":"第五災：瘟災","verses":[{"n":1,"t":"耶和華對摩西說：「你要到法老那裏，對他說：『耶和華－希伯來人的神如此說：放我的百姓走，好事奉我。","notes":[]},{"n":2,"t":"你若不肯放他們走，仍要強留他們，","notes":[]},{"n":3,"t":"看哪，耶和華的手必以嚴重的瘟疫加在你田間的牲畜上，就是在馬、驢、駱駝、牛群和羊群的身上。","notes":[]},{"n":4,"t":"耶和華卻要分別以色列的牲畜和埃及的牲畜，凡屬以色列人的，一隻都不死。』」","notes":[]},{"n":5,"t":"耶和華就設定時間，說：「明天耶和華必在此地行這事。」","notes":[]},{"n":6,"t":"第二天，耶和華行了這事。埃及的牲畜全都死了，只是以色列人的牲畜，一隻都沒有死。","notes":[]},{"n":7,"t":"法老派人去，看哪，以色列人的牲畜連一隻都沒有死。可是法老硬著心，不放百姓走。","notes":[]},{"n":8,"t":"耶和華對摩西和亞倫說：「你們從爐裏滿滿捧出爐灰，摩西要在法老眼前把它撒在空中。","notes":[],"heads":["第六災：瘡災"]},{"n":9,"t":"這灰要在埃及全地變成塵土，使埃及全地的人和牲畜身上起泡生瘡。」","notes":[]},{"n":10,"t":"摩西和亞倫取了爐灰，站在法老面前。摩西把它撒在空中，人和牲畜的身上就起泡生瘡了。","notes":[]},{"n":11,"t":"因為這瘡，術士在摩西面前站立不住，術士和所有埃及人的身上都生了瘡。","notes":[]},{"n":12,"t":"但耶和華任憑法老的心剛硬，不聽摩西和亞倫，正如耶和華對摩西所說的。","notes":[]},{"n":13,"t":"耶和華對摩西說：「你要清早起來，站在法老面前，對他說：『耶和華－希伯來人的神如此說：放我的百姓走，好事奉我。","notes":[],"heads":["第七災：雹災"]},{"n":14,"t":"因為這一次我要使一切的災禍臨到你自己，你臣僕和你百姓的身上，為要叫你知道在全地沒有像我的。","notes":[]},{"n":15,"t":"現在，我若伸手用瘟疫攻擊你和你的百姓，你就會從地上除滅了。","notes":[]},{"n":16,"t":"然而，我讓你存活，是為了要使你看見我的大能，並要使我的名傳遍全地。","notes":[]},{"n":17,"t":"可是你仍然向我的百姓自高自大，不放他們走。","notes":[]},{"n":18,"t":"看哪，明天大約這時候，我必使大量的冰雹降下，這是從埃及立國直到如今沒有出現過的。","notes":[]},{"n":19,"t":"現在，你要派人把你的牲畜和你田間一切所有的帶去躲避；任何在田間，無論是人是牲畜沒有回到屋內的，冰雹必降在他們身上，他們就必死。』」","notes":[]},{"n":20,"t":"法老的臣僕中，懼怕耶和華這話的，就讓他的奴僕和牲畜逃進屋裏。","notes":[]},{"n":21,"t":"但那不把耶和華這話放在心上的，就把他的奴僕和牲畜留在田裏。","notes":[]},{"n":22,"t":"耶和華對摩西說：「你向天伸出你的手，使冰雹降在埃及全地，降在埃及地的人和牲畜身上，以及田間各樣菜蔬上。」","notes":[]},{"n":23,"t":"摩西向天伸杖，耶和華就打雷下雹，有火降到地上；耶和華下雹在埃及地上。","notes":[]},{"n":24,"t":"那時，有雹，也有火在雹中閃爍，極其嚴重；自從埃及立國以來，全地沒有像這樣的。","notes":[]},{"n":25,"t":"在埃及全地，冰雹擊打田間所有的人和牲畜，擊打一切的菜蔬，也打壞了田間一切的樹木。","notes":[]},{"n":26,"t":"惟獨以色列人所住的歌珊地沒有冰雹。","notes":[]},{"n":27,"t":"法老差派人去召摩西和亞倫來，對他們說：「這一次我犯罪了。耶和華是公義的；我和我的百姓是邪惡的。","notes":[]},{"n":28,"t":"請你們祈求耶和華，因神的雷轟和冰雹已經夠了。我要放你們走，你們不用再留下來了。」","notes":[]},{"n":29,"t":"摩西對他說：「我一出城就向耶和華舉起雙手；雷必止住，也不再有冰雹，叫你知道地是屬於耶和華的。","notes":[]},{"n":30,"t":"至於你和你的臣僕，我知道你們仍然不敬畏耶和華神。」","notes":[]},{"n":31,"t":"那時，亞麻和大麥被摧毀了，因為大麥已經吐穗，亞麻也開了花。","notes":[]},{"n":32,"t":"只是小麥和粗麥沒有被摧毀，因為它們還沒有長成。","notes":[]},{"n":33,"t":"摩西離開法老出了城，向耶和華舉起雙手，雷和雹就止住，雨也不再下在地上了。","notes":[]},{"n":34,"t":"法老見雨、雹、雷止住，又再犯罪；他和他的臣僕都硬著心。","notes":[]},{"n":35,"t":"法老的心剛硬，不放以色列人走，正如耶和華藉著摩西所說的。","notes":[]}]},"10":{"heading":"第八災：蝗災","verses":[{"n":1,"t":"耶和華對摩西說：「你要到法老那裏，因我使他硬著心，也使他臣僕硬著心，為要在他們中間顯出我的這些神蹟來，","notes":["「在他們中間」是根據七十士譯本；原文是「在他中間」。"]},{"n":2,"t":"並要叫你將我嚴厲對付埃及的事，和在他們中間所行的神蹟，傳於兒子和孫子的耳中，好叫你們知道我是耶和華。」","notes":[]},{"n":3,"t":"摩西和亞倫就到法老那裏，對他說：「耶和華－希伯來人的神這樣說：『你在我面前不肯謙卑要到幾時呢？放我的百姓走，好事奉我。","notes":[]},{"n":4,"t":"你若不肯放我的百姓走，看哪，明天我要使蝗蟲進入你的境內，","notes":[]},{"n":5,"t":"遮滿地面，甚至地也看不見了。牠們要吃那冰雹後所剩，就是留給你們的；並且要吃那生長在田間的一切樹木。","notes":["「地面」：原文是「地的眼睛」；15節同。"]},{"n":6,"t":"你的宮殿和你眾臣僕的房屋，以及一切埃及人的房屋，都要被蝗蟲佔滿；你祖宗和你祖宗的祖宗在世以來，直到今日都沒有見過。』」摩西就轉身離開法老出去。","notes":[]},{"n":7,"t":"法老的臣僕對法老說：「這傢伙成為我們的羅網要到幾時呢？讓這些人去事奉耶和華－他們的神吧！埃及快要滅亡了，你還不知道嗎？」","notes":[]},{"n":8,"t":"於是摩西和亞倫被召回來見法老。法老對他們說：「去，事奉耶和華－你們的神吧！但要去的是哪些人呢？」","notes":[]},{"n":9,"t":"摩西說：「我們要帶著年老的和年少的同去，要帶著我們的兒子和女兒，以及我們的羊群牛群一起去，因為我們要向耶和華守節。」","notes":[]},{"n":10,"t":"法老對他們說：「願耶和華與你們同在吧！我若讓你們帶著你們的孩子同去，看，災禍就在你們面前！","notes":["「災禍就在你們面前」或譯「你們存著惡意」。"]},{"n":11,"t":"不可都去！你們壯年人去事奉耶和華吧，因為這是你們所求的。」於是法老把他們從自己面前趕出去。","notes":[]},{"n":12,"t":"耶和華對摩西說：「你向埃及地伸出你的手，使蝗蟲上到埃及地，吃地上冰雹後所剩一切的植物。」","notes":[]},{"n":13,"t":"摩西就向埃及地伸杖；整整一晝一夜，耶和華使東風颳在埃及地上，到了早晨，東風把蝗蟲颳了來。","notes":[]},{"n":14,"t":"蝗蟲上到埃及全地，落在埃及全境，非常厲害；蝗蟲這麼多，是空前絕後的。","notes":[]},{"n":15,"t":"蝗蟲遮滿地面，地上一片黑暗。牠們吃盡了地上一切的植物和冰雹過後所剩樹上的果子。埃及全地，無論是樹木，是田間的植物，連一點綠的也沒有留下。","notes":[]},{"n":16,"t":"於是法老急忙召了摩西和亞倫來，說：「我得罪了耶和華－你們的神，又得罪了你們。","notes":[]},{"n":17,"t":"現在求你，就這一次，饒恕我的罪，祈求耶和華－你們的神救我脫離這次的死亡。」","notes":[]},{"n":18,"t":"摩西就離開法老，去祈求耶和華。","notes":[]},{"n":19,"t":"耶和華轉變風向，使強勁的西風吹來，把蝗蟲颳起，吹入紅海；在埃及全境連一隻也沒有留下。","notes":["「紅海」是根據七十士譯本，原文是「蘆葦海」；本卷書下同。"]},{"n":20,"t":"但耶和華任憑法老的心剛硬，不放以色列人走。","notes":[]},{"n":21,"t":"耶和華對摩西說：「你向天伸出你的手，使黑暗籠罩埃及地；這黑暗甚至可以摸得到。」","notes":[],"heads":["第九災：黑暗之災"]},{"n":22,"t":"摩西向天伸出他的手，濃密的黑暗就籠罩了埃及全地三天之久。","notes":[]},{"n":23,"t":"三天內，人人彼此看不見，誰也不敢起身離開原地；但所有以色列人住的地方卻有光。","notes":[]},{"n":24,"t":"法老就召摩西來，說：「去，事奉耶和華吧！只是你們的羊群牛群要留下來。你們的孩子可以和你們同去。」","notes":[]},{"n":25,"t":"摩西說：「你必須把祭物和燔祭牲交在我們手中，讓我們可以向耶和華我們的神獻祭。","notes":[]},{"n":26,"t":"我們的牲畜也要與我們同去，連一蹄也不留下，因為我們要從牲畜中挑選來事奉耶和華－我們的神。未到那裏之前，我們還不知道要用甚麼來事奉耶和華。」","notes":[]},{"n":27,"t":"但耶和華任憑法老的心剛硬，法老不肯放他們走。","notes":[]},{"n":28,"t":"法老對摩西說：「離開我去吧！你要小心，不要再見我的面，因為再見我面的那日，你就必死！」","notes":[]},{"n":29,"t":"摩西說：「就照你說的，我也不要再見你的面了！」","notes":[]}]},"11":{"heading":"最後一災的警告","verses":[{"n":1,"t":"耶和華對摩西說：「我要再降一個災禍給法老和埃及，然後他必讓你們離開這裏。他放你們走的時候，一定會趕你們全都離開這裏。","notes":[]},{"n":2,"t":"你要傳於百姓耳中，叫他們男的女的各向鄰舍索取金器銀器。」","notes":[]},{"n":3,"t":"耶和華使埃及人看得起他的百姓，並且摩西在埃及地，在法老臣僕和百姓眼中看為偉大。","notes":["「他的百姓」是根據七十士譯本；原文是「百姓」。"]},{"n":4,"t":"摩西說：「耶和華如此說：『約到半夜，我必出去走遍埃及。","notes":[]},{"n":5,"t":"凡在埃及地，從坐寶座的法老到推磨的婢女所生的長子，以及一切頭生的牲畜，都必死。","notes":["「推磨」：原文是「在石磨後」。"]},{"n":6,"t":"埃及全地必有大大的哀號，這將是空前絕後的。","notes":[]},{"n":7,"t":"至於以色列人中，無論是人是牲畜，連狗也不敢向他們吠叫，使你們知道耶和華區別埃及和以色列。』","notes":[]},{"n":8,"t":"你所有的這些臣僕都要下到我這裏，向我下拜說：『請你和跟從你的百姓都離開吧！』然後我才離開。」於是，摩西氣憤憤地離開法老出去了。","notes":[]},{"n":9,"t":"耶和華對摩西說：「法老必不聽你們，為了要使我在埃及地多行奇事。」","notes":[]},{"n":10,"t":"摩西和亞倫在法老面前行了這一切奇事，但耶和華任憑法老的心剛硬，不讓以色列人離開他的地。","notes":[]}]},"12":{"heading":"耶和華的逾越","verses":[{"n":1,"t":"耶和華在埃及地對摩西和亞倫說：","notes":[]},{"n":2,"t":"「你們要以本月為正月，為一年之首。","notes":[]},{"n":3,"t":"你們要吩咐以色列全會眾說：本月初十，各人要按著家庭取羔羊，一家一隻羔羊。","notes":["「家庭」：原文是「父家(以父為主的家庭)」。"]},{"n":4,"t":"若一家的人太少，吃不了一隻羔羊，就要按照人數和隔壁的鄰舍共取一隻；你們要按每人的食量來估算羔羊。","notes":[]},{"n":5,"t":"你們要從綿羊或山羊中取一隻無殘疾、一歲的公羔羊，","notes":[]},{"n":6,"t":"要把牠留到本月十四日；那日黃昏的時候，以色列全會眾要把羔羊宰了。","notes":[]},{"n":7,"t":"他們要取一些血，塗在他們吃羔羊的房屋兩邊的門框上和門楣上。","notes":[]},{"n":8,"t":"當晚要吃羔羊的肉；要用火烤了，與無酵餅和苦菜一起吃。","notes":[]},{"n":9,"t":"不可吃生的，或用水煮的，要把羔羊連頭帶腿和內臟用火烤了吃。","notes":[]},{"n":10,"t":"一點也不可留到早晨；若有留到早晨的，要用火燒了。","notes":[]},{"n":11,"t":"你們要這樣吃羔羊：腰間束帶，腳上穿鞋，手中拿杖，快快地吃。這是耶和華的逾越。","notes":[]},{"n":12,"t":"因為那夜我要走遍埃及地，把埃及地一切頭生的，無論是人是牲畜，都擊殺了；我要對埃及所有的神明施行審判。我是耶和華。","notes":[]},{"n":13,"t":"這血要在你們所住的房屋上作記號；我一見這血，就逾越你們。我擊打埃及地的時候，災殃必不臨到你們身上施行毀滅。」","notes":[]},{"n":14,"t":"「你們要記念這日，世世代代守這日為耶和華的節日，作為你們永遠的定例。","notes":[],"heads":["除酵節"]},{"n":15,"t":"你們要吃無酵餅七日。第一日要把酵從你們各家中除去，因為從第一日到第七日，任何吃有酵之物的，必從以色列中剪除。","notes":[]},{"n":16,"t":"第一日當有聖會，第七日也當有聖會。在這兩日，任何工作都不可做，只能預備各人的食物，這是惟一可做的工作。","notes":[]},{"n":17,"t":"你們要守除酵節，因為我在這一日把你們的軍隊從埃及地領出來。所以，你們要世世代代守這日，立為永遠的定例。","notes":[]},{"n":18,"t":"從正月十四日晚上，直到二十一日晚上，你們要吃無酵餅。","notes":[]},{"n":19,"t":"在你們各家中，七日之內不可有酵，因為凡吃有酵之物的，無論是寄居的，是本地的，必從以色列的會中剪除。","notes":[]},{"n":20,"t":"任何有酵的物，你們都不可吃；在你們一切的住處要吃無酵餅。」","notes":[]},{"n":21,"t":"於是，摩西召了以色列的眾長老來，對他們說：「你們要為家人取羔羊，把逾越的羔羊宰了。","notes":[],"heads":["逾越節的建立"]},{"n":22,"t":"要拿一把牛膝草，蘸盆裏的血，把盆裏的血塗在門楣上和兩邊的門框上。直到早晨你們誰也不可出自己家裏的門。","notes":[]},{"n":23,"t":"因為耶和華要走遍埃及，施行擊殺，他看見血在門楣上和兩邊的門框上，耶和華就必逾越那門，不讓滅命者進你們的家，施行擊殺。","notes":[]},{"n":24,"t":"你們要守這命令，作為你們和你們子孫永遠的定例。","notes":[]},{"n":25,"t":"日後，你們到了耶和華所應許賜給你們的那地，就要守這禮儀。","notes":[]},{"n":26,"t":"你們的兒女對你們說：『這禮儀是甚麼意思呢？』","notes":[]},{"n":27,"t":"你們就說：『這是獻給耶和華逾越節的祭物。當耶和華擊殺埃及人的時候，他逾越了以色列人在埃及的房屋，救了我們各家。』」於是百姓低頭敬拜。","notes":[]},{"n":28,"t":"以色列人就去做；他們照耶和華吩咐摩西和亞倫的去做了。","notes":[]},{"n":29,"t":"到了半夜，耶和華把埃及地所有頭生的，就是從坐寶座的法老，到關在牢裏的人的長子，以及一切頭生的牲畜，盡都殺了。","notes":[],"heads":["第十災：頭生的被殺"]},{"n":30,"t":"法老和他眾臣僕，以及所有的埃及人，都在夜間起來了。在埃及有大大的哀號，因為沒有一家不死人的。","notes":[]},{"n":31,"t":"夜間，法老召了摩西和亞倫來，說：「起來！你們和以色列人，都離開我的百姓出去，照你們所說的，去事奉耶和華吧！","notes":[]},{"n":32,"t":"照你們所說的，連羊群牛群也帶走，也為我祝福吧！」","notes":[]},{"n":33,"t":"埃及人催促百姓趕快離開那地，因為埃及人說：「我們都快死了。」","notes":[]},{"n":34,"t":"百姓就拿著沒有發酵的生麵，把揉麵盆包在衣服中，扛在肩上。","notes":[]},{"n":35,"t":"以色列人照摩西的話去做，向埃及人索取金器、銀器和衣裳。","notes":[]},{"n":36,"t":"耶和華使埃及人看得起他的百姓，埃及人就給了他們所要的。他們就掠奪了埃及人。","notes":[]},{"n":37,"t":"以色列人從蘭塞起程，往疏割去。除了小孩，步行的男人約有六十萬。","notes":[],"heads":["出埃及"]},{"n":38,"t":"又有許多不同族群的人，以及眾多的羊群牛群，和他們一同上去。","notes":[]},{"n":39,"t":"他們用埃及帶出來的生麵烤成無酵餅。這生麵是沒有發酵的；因為他們被催促離開埃及，不能耽延，就沒有為自己預備食物。","notes":[]},{"n":40,"t":"以色列人住在埃及共四百三十年。","notes":[]},{"n":41,"t":"正滿四百三十年的那一天，耶和華的全軍從埃及地出來了。","notes":[]},{"n":42,"t":"這是向耶和華守的夜，他領他們出埃及地；這是以色列眾人世世代代要向耶和華守的夜。","notes":[]},{"n":43,"t":"耶和華對摩西和亞倫說：「逾越節的條例是這樣：外邦人不可吃這羔羊。","notes":[],"heads":["逾越節的條例"]},{"n":44,"t":"但是你們用銀子買來，又受過割禮的奴僕可以吃。","notes":[]},{"n":45,"t":"寄居的和雇工都不可吃。","notes":[]},{"n":46,"t":"應當在一個屋子裏吃，不可把肉帶到屋外，骨頭一根也不可折斷。","notes":[]},{"n":47,"t":"以色列全會眾都要守這禮儀。","notes":[]},{"n":48,"t":"若有外人寄居在你那裏，要向耶和華守逾越節，他所有的男子務要先受割禮，然後才可以當他是本地人，容許他守這禮儀。但未受割禮的都不可吃這羔羊。","notes":[]},{"n":49,"t":"本地人和寄居在你們中間的外人當守同一個條例。」","notes":[]},{"n":50,"t":"以色列眾人就去做，他們照耶和華吩咐摩西和亞倫的去做了。","notes":[]},{"n":51,"t":"正當那日，耶和華將以色列人按著他們的隊伍從埃及地領了出來。","notes":[]}]},"13":{"heading":"頭生的分別為聖","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「頭生的要分別為聖歸我；以色列中凡頭生的，無論是人是牲畜，都是我的。」","notes":[]},{"n":3,"t":"摩西對百姓說：「你們要記念從埃及為奴之家出來的這日，因為耶和華用大能的手將你們從這地領出來。有酵之物都不可吃。","notes":[],"heads":["除酵節"]},{"n":4,"t":"亞筆月的這一日你們走出來了。","notes":[]},{"n":5,"t":"將來耶和華領你進迦南人、赫人、亞摩利人、希未人、耶布斯人之地，就是他向你祖宗起誓應許給你的那流奶與蜜之地，那時你要在這一個月守這禮儀。","notes":[]},{"n":6,"t":"你要吃無酵餅七日，在第七日要向耶和華守節。","notes":[]},{"n":7,"t":"這七日之內，要吃無酵餅；在你的全境內不可見有酵之物，也不可見酵母。","notes":[]},{"n":8,"t":"當那日，你要告訴你的兒子說：『這樣做是因為耶和華在我出埃及的時候為我所做的事。』","notes":[]},{"n":9,"t":"這要在你手上作記號，在你額上作紀念，使耶和華的教導常在你口中，因為耶和華用大能的手將你從埃及領出來。","notes":["「額上」：原文是「兩眼之間」；16節同。"]},{"n":10,"t":"所以你每年要按著日期守這條例。」","notes":[]},{"n":11,"t":"「當耶和華照他向你和你祖宗所起的誓將你領進迦南人之地，把那地賜給你的時候，","notes":[],"heads":["頭生的獻給主"]},{"n":12,"t":"你要將一切頭生的獻給耶和華；你牲畜中頭生的，公的都歸耶和華。","notes":[]},{"n":13,"t":"然而，凡頭生的驢，你要用羔羊贖回；若不贖牠，就要打斷牠的頸項。你兒子中的長子都要贖出來。","notes":[]},{"n":14,"t":"日後，你的兒子問你說：『這是甚麼意思？』你就說：『耶和華用大能的手將我們從埃及為奴之家領出來。","notes":[]},{"n":15,"t":"那時法老固執，不肯放我們走，耶和華就把埃及地所有頭生的，無論是人是牲畜，都殺了。因此，我把一切頭生的公的牲畜獻給耶和華為祭，卻將所有頭生的兒子贖出來。","notes":[]},{"n":16,"t":"這要在你手上作記號，在你額上作經匣，因為耶和華用大能的手將我們從埃及領出來。』」","notes":["「經匣」指「把經文放在皮製的匣中作額飾」。"]},{"n":17,"t":"法老放百姓走的時候，非利士人之地的路雖近，神卻不領他們從那裏走，因為神說：「恐怕百姓遇見戰爭就後悔，轉回埃及去。」","notes":[],"heads":["雲柱和火柱"]},{"n":18,"t":"神領百姓繞道而行，走曠野的路到紅海。以色列人出埃及地，都帶著兵器上去。","notes":["「以色列人...都帶著兵器上去」：七十士譯本是「以色列中第五代的人也出埃及地上去」。"]},{"n":19,"t":"摩西把約瑟的骸骨一起帶走；因為約瑟曾叫以色列人鄭重地起誓，對他們說：「神必定眷顧你們，你們要把我的骸骨從這裏一起帶上去。」","notes":[]},{"n":20,"t":"他們從疏割起程，在曠野邊上的以倘安營。","notes":[]},{"n":21,"t":"耶和華走在他們前面，日間用雲柱引領他們的路，夜間用火柱照亮他們，使他們日夜都可以行走。","notes":[]},{"n":22,"t":"日間的雲柱，夜間的火柱，總不離開百姓的面前。","notes":[]}]},"14":{"heading":"過紅海","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你吩咐以色列人轉回，要在比‧哈希錄前面，密奪和海的中間，巴力‧洗分的前面安營。你們要在對面，靠近海邊安營。","notes":[]},{"n":3,"t":"以色列人這樣做，法老必說：『他們在此地迷了路，曠野把他們困住了。』","notes":[]},{"n":4,"t":"我要任憑法老的心剛硬，他要追趕他們。我必在法老和他全軍身上得榮耀，埃及人就知道我是耶和華。」於是以色列人照樣做了。","notes":[]},{"n":5,"t":"有人報告埃及王說：「百姓逃跑了！」法老和他的臣僕對百姓改變了心意，說：「我們放以色列人走，不再服事我們，我們怎麼會做這種事呢？」","notes":[]},{"n":6,"t":"法老就預備戰車，帶領他的軍兵同去，","notes":[]},{"n":7,"t":"他帶了六百輛特選的戰車和埃及所有的戰車，每輛都有軍官。","notes":[]},{"n":8,"t":"耶和華任憑埃及王法老的心剛硬，他就追趕以色列人；以色列人卻抬起頭來出去了。","notes":["「抬起頭」：原文是「舉起手」。"]},{"n":9,"t":"埃及人追趕他們，法老一切的馬匹、戰車、戰車長，與軍兵就在海邊上，靠近比‧哈希錄，在巴力‧洗分的前面，在他們安營的地方追上了。","notes":[]},{"n":10,"t":"法老逼近的時候，以色列人舉目，看哪，埃及人追來了，就非常懼怕，以色列人向耶和華哀求。","notes":[]},{"n":11,"t":"他們對摩西說：「難道埃及沒有墳地，你要把我們帶來死在曠野嗎？你為甚麼這樣待我們，將我們從埃及領出來呢？","notes":[]},{"n":12,"t":"我們在埃及豈沒有對你說過，不要攪擾我們，讓我們服事埃及人嗎？因為服事埃及人總比死在曠野好。」","notes":[]},{"n":13,"t":"摩西對百姓說：「不要怕，要站穩，看耶和華今天向你們所要施行的拯救，因為你們今天所看見的埃及人必永遠不再看見了。","notes":[]},{"n":14,"t":"耶和華必為你們爭戰，你們要安靜！」","notes":[]},{"n":15,"t":"耶和華對摩西說：「你為甚麼向我哀求呢？你吩咐以色列人往前走。","notes":[]},{"n":16,"t":"你舉手向海伸杖，把水分開。以色列人要下到海中，走在乾地上。","notes":[]},{"n":17,"t":"看哪，我要任憑埃及人的心剛硬，他們就跟著下去。我要在法老和他的全軍、戰車、戰車長身上得榮耀。","notes":[]},{"n":18,"t":"我在法老和他的戰車、戰車長身上得榮耀的時候，埃及人就知道我是耶和華。」","notes":[]},{"n":19,"t":"在以色列營前行走的神的使者移動，走到他們後面；雲也從他們的前面移動，站在他們後面。","notes":[]},{"n":20,"t":"它來到埃及營和以色列營的中間：一邊有雲和黑暗，另一邊它照亮夜晚，整夜彼此不得接近。","notes":[]},{"n":21,"t":"摩西向海伸手，耶和華就用強勁的東風，使海水在一夜間退去，海就成了乾地；水分開了。","notes":[]},{"n":22,"t":"以色列人下到海中，走在乾地上，水在他們左右成了牆壁。","notes":[]},{"n":23,"t":"埃及人追趕他們，法老一切的馬匹、戰車和戰車長都跟著下到海中。","notes":[]},{"n":24,"t":"破曉時分，耶和華從雲柱、火柱中瞭望埃及的軍兵，使埃及的軍兵混亂。","notes":[]},{"n":25,"t":"他使他們的車輪脫落，難以前行，埃及人說：「我們從以色列人面前逃跑吧！因耶和華為他們作戰，攻擊埃及了。」","notes":["「脫落」：撒瑪利亞五經、七十士譯本和其他古譯本是「受阻」。"]},{"n":26,"t":"耶和華對摩西說：「你要向海伸手，使水回流到埃及人，他們的戰車和戰車長身上。」","notes":[]},{"n":27,"t":"摩西就向海伸手，到了天亮的時候，海恢復原狀。埃及人逃避水的時候，耶和華把他們推入海中。","notes":[]},{"n":28,"t":"海水回流，淹沒了戰車和戰車長，以及那些跟著以色列人下到海中的法老全軍，連一個也沒有剩下。","notes":[]},{"n":29,"t":"以色列人卻在海中走乾地，水在他們的左右成了牆壁。","notes":[]},{"n":30,"t":"那一日，耶和華拯救以色列脫離埃及人的手。以色列人看見埃及人死在海邊。","notes":[]},{"n":31,"t":"以色列人看見耶和華向埃及人所施展的大能，百姓就敬畏耶和華，並且信服耶和華和他的僕人摩西。","notes":[]}]},"15":{"heading":"摩西之歌","verses":[{"n":1,"t":"那時，摩西和以色列人向耶和華唱這歌，說：「我要向耶和華歌唱，因他大大得勝，將馬和騎馬的投在海中。","notes":[]},{"n":2,"t":"耶和華是我的力量，是我的詩歌，他也成了我的拯救。這是我的神，我要讚美他；我父親的神，我要尊崇他。","notes":[]},{"n":3,"t":"耶和華是戰士；耶和華是他的名。","notes":[]},{"n":4,"t":"「法老的戰車、軍兵，他已拋在海中；法老精選的軍官都沉於紅海。","notes":[]},{"n":5,"t":"深水淹沒他們；他們好像石頭墜到深處。","notes":[]},{"n":6,"t":"耶和華啊，你的右手施展能力，大顯榮耀；耶和華啊，你的右手摔碎仇敵。","notes":[]},{"n":7,"t":"你大發威嚴，摧毀了你的敵人；你發出烈怒，吞滅他們如同碎稭。","notes":[]},{"n":8,"t":"因你鼻中的氣，水就聚成堆，大水豎立如壘，海的中心深水凝結。","notes":[]},{"n":9,"t":"仇敵說：『我要追趕，我要追上，我要分擄物，在他們身上滿足我的心願，我要拔刀，親手毀滅他們。』","notes":[]},{"n":10,"t":"你用風一吹，海水就淹沒他們；他們像鉛沉在大水之中。","notes":[]},{"n":11,"t":"「耶和華啊，眾神明中，誰能像你？誰能像你，至聖至榮，可頌可畏，施行奇事！","notes":[]},{"n":12,"t":"你伸出右手，地就吞滅他們。","notes":[]},{"n":13,"t":"「你以慈愛引領你所救贖的百姓；你以能力引導他們到你的聖所。","notes":[]},{"n":14,"t":"萬民聽見就戰抖；疼痛抓住非利士的居民。","notes":[]},{"n":15,"t":"那時，以東的族長驚惶，摩押的英雄被戰兢抓住，迦南所有的居民都融化。","notes":[]},{"n":16,"t":"驚駭恐懼臨到他們；耶和華啊，因你膀臂的大能，他們如石頭寂靜不動，等候你百姓過去，等候你所贖的百姓過去。","notes":[]},{"n":17,"t":"你要將他們領進去，栽在你產業的山上，耶和華啊，就是你為自己所造的住處，主啊，就是你手所建立的聖所。","notes":[]},{"n":18,"t":"耶和華必作王，直到永永遠遠！」","notes":[]},{"n":19,"t":"法老的馬匹、戰車和戰車長下到海中，耶和華使海水回流到他們身上；以色列人卻走在海中的乾地上。","notes":[]},{"n":20,"t":"那時，米利暗女先知，亞倫的姊姊，手裏拿著鈴鼓；眾婦女也跟她出去打鼓跳舞。","notes":[],"heads":["米利暗的歌"]},{"n":21,"t":"米利暗回應他們：「你們要歌頌耶和華，因他大大得勝，將馬和騎馬的投在海中。」","notes":[]},{"n":22,"t":"摩西領以色列人從紅海起程，到了書珥的曠野，在曠野走了三天，找不到水。","notes":[],"heads":["苦水變甜"]},{"n":23,"t":"到了瑪拉，他們不能喝瑪拉的水，因為水是苦的；所以那地名叫瑪拉。","notes":[]},{"n":24,"t":"百姓就向摩西發怨言，說：「我們喝甚麼呢？」","notes":[]},{"n":25,"t":"摩西呼求耶和華，耶和華指示他一棵樹。他把樹丟在水裏，水就變甜了。耶和華在那裏為他們定了律例、典章，在那裏考驗他們。","notes":["「一棵樹」或譯「一塊木頭」。"]},{"n":26,"t":"他說：「你若留心聽從耶和華－你神的話，行我眼中看為正的事，側耳聽我的誡令，遵守我一切的律例，我就不將所加於埃及人的疾病加在你身上，因為我是醫治你的耶和華。」","notes":[]},{"n":27,"t":"他們到了以琳，在那裏有十二股水泉，七十棵棕樹；他們就在那裏的水邊安營。","notes":[]}]},"16":{"heading":"嗎哪和鵪鶉","verses":[{"n":1,"t":"以色列全會眾從以琳起程，在出埃及之後第二個月十五日到了以琳和西奈中間，汛的曠野。","notes":[]},{"n":2,"t":"以色列全會眾在曠野向摩西和亞倫發怨言。","notes":[]},{"n":3,"t":"以色列人對他們說：「我們寧願在埃及地死在耶和華手中！那時我們坐在肉鍋旁，吃餅得飽。你們卻將我們領出來，到這曠野，要叫這全會眾都餓死啊！」","notes":[]},{"n":4,"t":"耶和華對摩西說：「看哪，我要從天降食物給你們。百姓可以出去，每天收集當天的分量。這樣，我就可以考驗他們是否遵行我的指示。","notes":[]},{"n":5,"t":"到第六天，他們預備食物，所收集的分量要比每天所收的多一倍。」","notes":[]},{"n":6,"t":"摩西和亞倫對以色列眾人說：「到了晚上，你們就知道是耶和華將你們從埃及地領出來的。","notes":[]},{"n":7,"t":"早晨，你們要看見耶和華的榮耀，因為耶和華聽見你們向他所發的怨言了。我們算甚麼，你們竟然向我們發怨言呢？」","notes":[]},{"n":8,"t":"摩西又說：「耶和華晚上必給你們肉吃，早晨必給你們食物得飽，因為耶和華已經聽見你們向他所發的怨言。我們算甚麼呢？你們的怨言不是向我們發的，而是向耶和華發的。」","notes":[]},{"n":9,"t":"摩西對亞倫說：「你對以色列全會眾說：『你們來到耶和華面前，因為他已經聽見你們的怨言了。』」","notes":[]},{"n":10,"t":"亞倫正對以色列全會眾說話的時候，他們轉向曠野，看哪，耶和華的榮光在雲中顯現。","notes":[]},{"n":11,"t":"耶和華吩咐摩西說：","notes":[]},{"n":12,"t":"「我已經聽見以色列人的怨言了。你要對他們說：『到黃昏的時候，你們要吃肉，早晨也必有食物得飽。你們就知道我是耶和華－你們的神。』」","notes":["「黃昏的時候」：原文是「兩個黃昏之間」。"]},{"n":13,"t":"到了晚上，有鵪鶉上來，遮滿營地；早晨，營地周圍有一層露水。","notes":[]},{"n":14,"t":"那一層露水蒸發之後，看哪，曠野的表面出現了小圓物，好像地上的薄霜一樣。","notes":[]},{"n":15,"t":"以色列人看見了，不知道是甚麼，就彼此說：「這是甚麼？」摩西對他們說：「這是耶和華給你們吃的食物。","notes":["「這是甚麼？」是根據七十士譯本；原文是「這是嗎哪。」"]},{"n":16,"t":"耶和華所吩咐的是這樣：『你們每個人要按自己的食量收集，各人要為帳棚裏的人收集，按照人口數每個人一俄梅珥。』」","notes":[]},{"n":17,"t":"以色列人就照樣去做；有的收多，有的收少。","notes":[]},{"n":18,"t":"用俄梅珥量一量，多收的沒有餘，少收的也沒有缺；各人都按著自己的食量收集。","notes":[]},{"n":19,"t":"摩西對他們說：「任何人都不可以把所收的留到早晨。」","notes":[]},{"n":20,"t":"然而他們不聽從摩西，當中有人把食物留到早晨，食物就生蟲發臭了。摩西就向他們發怒。","notes":[]},{"n":21,"t":"他們每日早晨按著各人的食量收集；太陽一發熱，食物就融化了。","notes":[]},{"n":22,"t":"到第六天，他們收集了雙倍的食物，每個人二俄梅珥。會眾的官長來告訴摩西，","notes":[]},{"n":23,"t":"摩西對他們說：「耶和華吩咐：『明天是安息日，是向耶和華守的聖安息日。你們要烤的就烤，要煮的就煮，所剩下的都留到早晨。』」","notes":[]},{"n":24,"t":"他們就照摩西的吩咐把剩下的留到早晨，這些食物既不發臭，裏頭也沒有生蟲。","notes":[]},{"n":25,"t":"摩西說：「你們今天就吃這些吧！因為今天是向耶和華守的安息日，你們在野外必找不著食物了。","notes":[]},{"n":26,"t":"六天可以收集，第七天是安息日，這一天甚麼也沒有了。」","notes":[]},{"n":27,"t":"第七天，百姓中有人出去收，甚麼也找不著。","notes":[]},{"n":28,"t":"耶和華對摩西說：「你們不肯遵守我的誡令和教導，要到幾時呢？","notes":[]},{"n":29,"t":"你們看，耶和華既然將安息日賜給你們，所以第六天他就賜給你們兩天的食物，第七天各人都要留在自己的地方，不許任何人從這裏出去。」","notes":[]},{"n":30,"t":"於是百姓在第七天安息了。","notes":[]},{"n":31,"t":"以色列家給這食物取名叫嗎哪，它的樣子像芫荽子，顏色是白的，吃起來像和蜜的薄餅。","notes":[]},{"n":32,"t":"摩西說：「耶和華所吩咐的是這樣：『要裝滿一俄梅珥的嗎哪留給你們的後代，使他們可以看見我領你們出埃及地的時候，在曠野所給你們吃的食物。』」","notes":[]},{"n":33,"t":"摩西對亞倫說：「你拿一個罐子，裝滿一俄梅珥的嗎哪，存在耶和華面前，留給你們的後代。」","notes":[]},{"n":34,"t":"耶和華怎麼吩咐摩西，亞倫就照樣做，把嗎哪存留作見證。","notes":["「作見證」或譯「在法櫃前」。"]},{"n":35,"t":"以色列人吃嗎哪共四十年，直到進入有人居住的地方；他們吃嗎哪，直到迦南地的邊境。","notes":[]},{"n":36,"t":"一俄梅珥是一伊法的十分之一。","notes":[]}]},"17":{"heading":"磐石出水","verses":[{"n":1,"t":"以色列全會眾遵照耶和華的吩咐，從汛的曠野一段一段地往前行。他們在利非訂安營，但百姓沒有水喝。","notes":[]},{"n":2,"t":"百姓就與摩西爭鬧，說：「給我們水喝吧！」摩西對他們說：「你們為甚麼與我爭鬧呢？你們為甚麼試探耶和華呢？」","notes":[]},{"n":3,"t":"百姓在那裏口渴要喝水，就向摩西發怨言，說：「你為甚麼把我們從埃及領出來，使我們和我們的兒女，以及牲畜都渴死呢？」","notes":[]},{"n":4,"t":"摩西就呼求耶和華說：「我要怎樣對待這百姓呢？他們差一點就要拿石頭打死我了。」","notes":[]},{"n":5,"t":"耶和華對摩西說：「你帶著以色列的幾個長老，走在百姓前面，手裏拿著你先前擊打尼羅河的杖，去吧！","notes":[]},{"n":6,"t":"看哪，我要在何烈的磐石那裏，站在你面前。你要擊打磐石，水就會從磐石流出來，給百姓喝。」摩西就在以色列的長老眼前這樣做了。","notes":[]},{"n":7,"t":"他給那地方起名叫瑪撒，又叫米利巴，因為以色列人在那裏爭鬧，並且試探耶和華，說：「耶和華是否在我們中間呢？」","notes":["「瑪撒」意思是「試探」。","「米利巴」意思是「爭鬧」。"]},{"n":8,"t":"那時，亞瑪力來到利非訂，和以色列爭戰。","notes":[],"heads":["擊敗亞瑪力人"]},{"n":9,"t":"摩西對約書亞說：「你為我們選出人來，出去和亞瑪力爭戰。明天我要站在山頂上，手裏拿著神的杖。」","notes":[]},{"n":10,"t":"於是，約書亞照著摩西對他所說的話去做，和亞瑪力爭戰。摩西、亞倫和戶珥都上了山頂。","notes":[]},{"n":11,"t":"摩西何時舉手，以色列就得勝；何時垂手，亞瑪力就得勝。","notes":[]},{"n":12,"t":"但摩西的雙手沉重，他們就搬一塊石頭來放在他下面，他就坐在上面。亞倫與戶珥扶著他的手，一個在這邊，一個在那邊，他的手就穩住，直到日落。","notes":[]},{"n":13,"t":"約書亞用刀打敗了亞瑪力和他的百姓。","notes":[]},{"n":14,"t":"耶和華對摩西說：「你要把這事記錄在書上作紀念，又念給約書亞聽：我要把亞瑪力的名字從天下全然塗去。」","notes":[]},{"n":15,"t":"摩西築了一座壇，起名叫「耶和華尼西」。","notes":["「耶和華尼西」意思是「耶和華是我的旌旗」。"]},{"n":16,"t":"他說：「我指著耶和華的寶座發誓，耶和華必世世代代和亞瑪力爭戰。」","notes":["「我指著...發誓」：原文直譯「向耶和華的寶座舉手」。"]}]},"18":{"heading":"葉特羅的探視","verses":[{"n":1,"t":"摩西的岳父，米甸祭司葉特羅，聽見神為摩西和為他百姓以色列所行的一切事，就是耶和華將以色列從埃及領了出來。","notes":[]},{"n":2,"t":"摩西的岳父葉特羅帶著西坡拉，就是摩西先前送回家的妻子，","notes":[]},{"n":3,"t":"又帶著她的兩個兒子：一個名叫革舜，因為摩西說：「我在外地作了寄居者」；","notes":[]},{"n":4,"t":"另一個名叫以利以謝，因為他說：「我父親的神幫助我，救我脫離法老的刀。」","notes":[]},{"n":5,"t":"摩西的岳父葉特羅帶著摩西的妻子和兩個兒子來到神的山，就是摩西在曠野安營的地方。","notes":[]},{"n":6,"t":"他對摩西說：「我是你岳父葉特羅，帶著你的妻子和兩個兒子來到你這裏。」","notes":["「他對摩西說：我是」：撒瑪利亞五經、七十士譯本和其他古譯本是「有人對摩西說：看哪」。"]},{"n":7,"t":"摩西迎接他的岳父，向他下拜，親他，彼此問安，然後進入帳棚。","notes":[]},{"n":8,"t":"摩西將耶和華為以色列的緣故向法老和埃及人所行的一切事，他們在路上遭遇的一切艱難，以及耶和華怎樣搭救他們，都述說給他的岳父聽。","notes":[]},{"n":9,"t":"葉特羅因耶和華待以色列的一切恩惠，就是拯救他們脫離埃及人的手，就非常喜樂。","notes":[]},{"n":10,"t":"葉特羅說：「耶和華是應當稱頌的，他救了你們脫離埃及人和法老的手，將這百姓從埃及人的手裏救出來。","notes":["七十士譯本沒有「將這百姓從埃及人的手裏救出來」。"]},{"n":11,"t":"現在，從埃及人狂傲地對待以色列人這件事上，我知道耶和華比萬神更大。」","notes":[]},{"n":12,"t":"摩西的岳父葉特羅把燔祭和祭物獻給神。亞倫和以色列的眾長老都來了，與摩西的岳父在神面前吃飯。","notes":[]},{"n":13,"t":"第二天，摩西坐著審判百姓，百姓從早到晚站在摩西的旁邊。","notes":[],"heads":["選立百姓的官長"]},{"n":14,"t":"摩西的岳父看見他為百姓所做的一切事，就說：「你為百姓所做的，這是甚麼事呢？你為甚麼獨自一人坐著，而眾百姓從早到晚都站在你旁邊呢？」","notes":[]},{"n":15,"t":"摩西對岳父說：「這是因為百姓到我這裏來求問神。","notes":[]},{"n":16,"t":"他們有事的時候，就到我這裏來，我就在雙方之間作判決；我又叫他們知道神的律例和法度。」","notes":[]},{"n":17,"t":"摩西的岳父對他說：「你這樣做不好。","notes":[]},{"n":18,"t":"你和這些與你在一起的百姓都必疲憊，因為這事太重，你獨自一人做不了。","notes":[]},{"n":19,"t":"現在，聽我的話，我給你出個主意，願神與你同在。你要代替百姓到神面前，將事件帶到神那裏，","notes":[]},{"n":20,"t":"又要用律例和法度警戒他們，指示他們當行的道，當做的事。","notes":[]},{"n":21,"t":"你也要從百姓中選出有才能的人，敬畏神、誠實可靠、恨惡不義之財的人，派他們作千夫長、百夫長、五十夫長、十夫長來管理百姓。","notes":[]},{"n":22,"t":"他們要隨時審判百姓；重大的事要送到你這裏，小事就由他們自行判決。這樣，你就可以輕省一些，他們可以與你分擔。","notes":[]},{"n":23,"t":"你若這樣做，神也這樣吩咐你，你就能承受得住，眾百姓也可以和睦地回到自己的地方。」","notes":[]},{"n":24,"t":"摩西聽了他岳父的話，照著他所說的一切去做。","notes":[]},{"n":25,"t":"摩西從以色列人中選出有才能的人，立他們為百姓的領袖，作千夫長、百夫長、五十夫長、十夫長。","notes":[]},{"n":26,"t":"他們隨時審判百姓：難斷的事就送到摩西那裏，各樣小事就由他們自行判決。","notes":[]},{"n":27,"t":"於是，摩西給他的岳父送行，他就回到本地去了。","notes":[]}]},"19":{"heading":"以色列人在西奈山","verses":[{"n":1,"t":"以色列人出埃及地以後，第三個月的初一，就在那一天他們來到了西奈的曠野。","notes":[]},{"n":2,"t":"他們從利非訂起程，來到西奈的曠野，在那裏的山下安營。","notes":[]},{"n":3,"t":"摩西到神那裏，耶和華從山上呼喚他說：「你要這樣告訴雅各家，對以色列人說：","notes":[]},{"n":4,"t":"『我向埃及人所行的事，你們都看見了， 我如鷹將你們背在翅膀上，帶你們來歸我。","notes":[]},{"n":5,"t":"如今你們若真的聽從我的話，遵守我的約，就要在萬民中作屬我的子民，因為全地都是我的。","notes":["「子民」：原文是「寶貴的產業」。"]},{"n":6,"t":"你們要歸我作祭司的國度，為神聖的國民。』這些話你要告訴以色列人。」","notes":[]},{"n":7,"t":"摩西去召了百姓中的長老來，將耶和華吩咐他的話當面告訴他們。","notes":[]},{"n":8,"t":"百姓都同聲回答：「凡耶和華所說的，我們一定遵行。」摩西就將百姓的話回覆耶和華。","notes":[]},{"n":9,"t":"耶和華對摩西說：「看哪，我要在密雲中臨到你那裏，叫百姓在我與你說話的時候可以聽見，就可以永遠相信你了。」於是，摩西將百姓的話稟告耶和華。","notes":[]},{"n":10,"t":"耶和華對摩西說：「你往百姓那裏去，使他們今天明天分別為聖，又叫他們洗衣服。","notes":[]},{"n":11,"t":"第三天要預備好，因為第三天耶和華要在眾百姓眼前降臨在西奈山。","notes":[]},{"n":12,"t":"你要在山的周圍給百姓劃定界限，說：『你們當謹慎，不可上山去，也不可摸山的邊界。凡摸這山的，必被處死。","notes":[]},{"n":13,"t":"不可用手碰他，要用石頭打死，或射死；無論是人是牲畜，都不可活。』到角聲拉長的時候，他們才可到山腳來。」","notes":[]},{"n":14,"t":"摩西下山到百姓那裏去，使他們分別為聖，他們就洗衣服。","notes":[]},{"n":15,"t":"他對百姓說：「第三天要預備好；不可親近女人。」","notes":[]},{"n":16,"t":"到了第三天早晨，山上有雷轟、閃電和密雲，並且角聲非常響亮，營中的百姓盡都戰抖。","notes":[]},{"n":17,"t":"摩西率領百姓出營迎見神，都站在山下。","notes":[]},{"n":18,"t":"西奈山全山冒煙，因為耶和華在火中降臨山上。山的煙霧上騰，彷彿燒窯，整座山劇烈震動。","notes":[]},{"n":19,"t":"角聲越來越響，摩西說話，神以聲音回答他。","notes":[]},{"n":20,"t":"耶和華降臨在西奈山頂上，耶和華召摩西上山頂，摩西就上去了。","notes":[]},{"n":21,"t":"耶和華對摩西說：「你下去警告百姓，免得他們闖過來看耶和華，就會有許多人死亡。","notes":[]},{"n":22,"t":"那些親近耶和華的祭司也要把自己分別為聖，免得耶和華忽然出來擊殺他們。」","notes":[]},{"n":23,"t":"摩西對耶和華說：「百姓不能上西奈山，因為你已經警告我們說：『要在山的周圍劃定界限，使山成聖。』」","notes":[]},{"n":24,"t":"耶和華對他說：「下去吧，你要和亞倫一起上來；只是祭司和百姓不可闖上來到耶和華這裏，免得耶和華忽然出來擊殺他們。」","notes":[]},{"n":25,"t":"於是，摩西下到百姓那裏告訴他們。","notes":[]}]},"20":{"heading":"十誡","verses":[{"n":1,"t":"神吩咐這一切的話，說：","notes":[]},{"n":2,"t":"「我是耶和華－你的神，曾將你從埃及地為奴之家領出來。","notes":[]},{"n":3,"t":"「除了我以外，你不可有別的神。","notes":[]},{"n":4,"t":"「不可為自己雕刻偶像，也不可做甚麼形像，彷彿上天、下地和地底下水中的百物。","notes":[]},{"n":5,"t":"不可跪拜那些像，也不可事奉它們，因為我耶和華─你的神是忌邪的神。恨我的，我必懲罰他們的罪，自父及子，直到三、四代；","notes":["「忌邪」：原文是「妒忌」，意思是「不容許有對立的神明」。"]},{"n":6,"t":"愛我，守我誡命的，我必向他們施慈愛，直到千代。","notes":[]},{"n":7,"t":"「不可妄稱耶和華－你神的名，因為妄稱耶和華名的，耶和華必不以他為無罪。","notes":[]},{"n":8,"t":"「當記念安息日，守為聖日。","notes":[]},{"n":9,"t":"六日要勞碌做你一切的工，","notes":[]},{"n":10,"t":"但第七日是向耶和華─你的神當守的安息日。這一日你和你的兒女、奴僕、婢女、牲畜，以及你城裏寄居的客旅，都不可做任何的工。","notes":[]},{"n":11,"t":"因為六日之內，耶和華造天、地、海和其中的萬物，第七日就安息了；所以耶和華賜福與安息日，定為聖日。","notes":[]},{"n":12,"t":"「當孝敬父母，使你的日子在耶和華－你神所賜你的地上得以長久。","notes":[]},{"n":13,"t":"「不可殺人。","notes":[]},{"n":14,"t":"「不可姦淫。","notes":[]},{"n":15,"t":"「不可偷盜。","notes":[]},{"n":16,"t":"「不可做假見證陷害你的鄰舍。","notes":[]},{"n":17,"t":"「不可貪戀你鄰舍的房屋；不可貪戀你鄰舍的妻子、奴僕、婢女、牛驢，以及他一切所有的。」","notes":[]},{"n":18,"t":"眾百姓見雷轟、閃電、角聲、山上冒煙，百姓看見就都戰抖，遠遠站著。","notes":["「看見」：撒瑪利亞五經、七十士譯本和其他古譯本是「害怕」。"],"heads":["眾民戰懼"]},{"n":19,"t":"他們對摩西說：「請你向我們說話，我們必聽；不要讓神向我們說話，免得我們死亡。」","notes":[]},{"n":20,"t":"摩西對百姓說：「不要害怕；因為神降臨是要考驗你們，要你們敬畏他，不致犯罪。」","notes":[]},{"n":21,"t":"於是百姓遠遠站著，但摩西卻挨近神所在的幽暗中。","notes":[]},{"n":22,"t":"耶和華對摩西說：「你要向以色列人這樣說：『你們親自看見我從天上向你們說話了。","notes":[],"heads":["祭壇的條例"]},{"n":23,"t":"你們不可為我製造偶像，不可為自己造任何金銀的神像。","notes":[]},{"n":24,"t":"你要為我築一座土壇，在上面獻牛羊為燔祭和平安祭。凡在我叫你記念我名的地方，我必到那裏賜福給你。","notes":[]},{"n":25,"t":"你若為我築一座石壇，不可用鑿過的石頭，因為你在石頭上動了工具，就使壇污穢了。","notes":[]},{"n":26,"t":"你不可用臺階上我的壇，免得露出你的下體來。』」","notes":[]}]},"21":{"heading":"奴婢的條例","verses":[{"n":1,"t":"「你在百姓面前所要立的典章是這樣：","notes":[]},{"n":2,"t":"「你若買希伯來人作奴僕，他服事你六年，第七年他可以自由，白白地離去。","notes":[]},{"n":3,"t":"他若單身來就可以單身去；他若是有妻子的，他的妻子可以同他離去。","notes":[]},{"n":4,"t":"若他主人給他娶了妻，妻子為他生了兒子或女兒，妻子和兒女要歸主人，他要獨自離去。","notes":[]},{"n":5,"t":"倘若奴僕聲明：『我愛我的主人和我的妻子兒女，不願意自由離去。』","notes":[]},{"n":6,"t":"他的主人就要帶他到審判官前，再帶他到門或門框那裏，用錐子穿他的耳朵，他就要永遠服事主人。","notes":["「審判官」或譯「神」；22節同。"]},{"n":7,"t":"「人若賣女兒作婢女，婢女不可像男的奴僕那樣離去。","notes":[]},{"n":8,"t":"主人若選定她歸自己，後來看不順眼，就要允許她贖身；主人既然對她失信，就沒有權柄把她賣給外邦人。","notes":[]},{"n":9,"t":"主人若選定她給自己的兒子，就當照女兒的規矩對待她。","notes":[]},{"n":10,"t":"若另娶一個，她的飲食、衣服和房事不可減少。","notes":[]},{"n":11,"t":"若不向她行這三樣，她就可以白白離去，不必付贖金。」","notes":[]},{"n":12,"t":"「打人致死的，必被處死。","notes":[],"heads":["懲罰暴行的條例"]},{"n":13,"t":"他若不是出於預謀，而是神交在他手中，我就設立一個地方，讓他可以逃到那裏。","notes":["「出於預謀」：原文直譯「埋伏」。"]},{"n":14,"t":"人若蓄意用詭計殺了他的鄰舍，就是逃到我的壇那裏，也當把他捉去處死。","notes":[]},{"n":15,"t":"「打父母的，必被處死。","notes":[]},{"n":16,"t":"「誘拐人口的，無論是把人賣了，或是扣留在他手中，必被處死。","notes":[]},{"n":17,"t":"「咒罵父母的，必被處死。","notes":[]},{"n":18,"t":"「人若彼此爭吵，一個用石頭或拳頭打另一個，被打的人沒有死去，卻要躺臥在床，","notes":[]},{"n":19,"t":"若他還能起來扶杖行走，那打他的可免處刑，卻要賠償他不能工作的損失，並要把他完全醫好。","notes":[]},{"n":20,"t":"「人若用棍子打奴僕或婢女，當場死在他的手下，他必受報應。","notes":[]},{"n":21,"t":"若能撐過一兩天，主人就不必受懲罰，因為那是他的財產。","notes":[]},{"n":22,"t":"「人若彼此打鬥，傷害有孕的婦人，以致胎兒掉了出來，隨後卻無別的傷害，那傷害她的人，總要按婦人的丈夫所提出的，照審判官所裁定的賠償。","notes":[]},{"n":23,"t":"若有別的傷害，就要以命抵命，","notes":[]},{"n":24,"t":"以眼還眼，以牙還牙，以手還手，以腳還腳，","notes":[]},{"n":25,"t":"以灼傷還灼傷，以損傷還損傷，以鞭打還鞭打。","notes":[]},{"n":26,"t":"「人若打奴僕或婢女的眼睛，毀了一隻，就要因他的眼讓他自由離去。","notes":[]},{"n":27,"t":"若打掉了奴僕或婢女的一顆牙，就要因他的牙讓他自由離去。」","notes":[]},{"n":28,"t":"「牛若牴死男人或女人，總要用石頭打死那牛，卻不可吃牠的肉；牛的主人可免處刑。","notes":[],"heads":["物主的責任"]},{"n":29,"t":"倘若那牛向來是牴人的，牛的主人雖然受過警告，仍不把牠拴好，以致把男人或女人牴死，牛要用石頭打死，主人也要被處死。","notes":[]},{"n":30,"t":"若罰他付贖命的賠款，他就要照所罰的數目贖他的命。","notes":[]},{"n":31,"t":"牛若牴了男孩或女孩，也要照這條例處理。","notes":[]},{"n":32,"t":"牛若牴了奴僕或婢女，就要把三十舍客勒銀子給奴僕的主人，牛要用石頭打死。","notes":[]},{"n":33,"t":"「人若敞開井口，或挖井不蓋住它，有牛或驢掉進井裏，","notes":[]},{"n":34,"t":"井的主人要拿錢賠償牲畜的主人，死牲畜要歸自己。","notes":[]},{"n":35,"t":"「人的牛若牴死鄰舍的牛，他們就要賣了那活牛，平分價錢；也要平分死牛。","notes":[]},{"n":36,"t":"若這牛向來是以好牴人出名的，主人竟不把牛拴好，他必要以牛賠牛，死牛卻歸自己。」","notes":[]}]},"22":{"heading":"賠償的條例","verses":[{"n":1,"t":"「人若偷牛或羊，無論是宰了或賣了，他就要以五牛賠一牛， 四羊賠一羊。","notes":[]},{"n":2,"t":"賊挖洞，若被發現而被打死，打的人沒有流血的罪。","notes":[]},{"n":3,"t":"若太陽已經出來，打的人就有流血的罪。賊總要賠償，若他一無所有，就要被賣來還他所偷的東西。","notes":[]},{"n":4,"t":"若發現他所偷的，無論是牛、驢，或羊，在他手中還活著，他就要加倍賠償。","notes":[]},{"n":5,"t":"「人若在田間或葡萄園裏牧放牲畜，任憑牲畜上別人田裏去吃，他就要拿自己田間和葡萄園裏上好的賠償。","notes":["「去吃」：七十士譯本是「去吃，他要拿自己田裏的作物來賠償；倘若牲畜把整片作物吃光了」。"]},{"n":6,"t":"「若火冒出，延燒到荊棘，以致將堆積的禾捆，直立的莊稼，或田地，都燒盡了，那點火的必要賠償。","notes":[]},{"n":7,"t":"「人若將銀錢或物件託鄰舍保管，東西從這人的家中被偷去，若找到了賊，賊要加倍賠償；","notes":[]},{"n":8,"t":"若找不到賊，這家的主人就要到審判官那裏，聲明自己沒有伸手拿鄰舍的物件。","notes":["「審判官」或譯「神」；9節同。","「聲明」或譯「宣誓作證」。"]},{"n":9,"t":"「關於任何侵害的案件，無論是為牛、驢、羊、衣服，或任何失物，有一人說：『這是我的』，雙方就要將案件帶到審判官面前，審判官定誰有罪，誰就要加倍賠償給他的鄰舍。","notes":[]},{"n":10,"t":"「人將驢、牛、羊，或別的牲畜託鄰舍看管，若牲畜死亡，受了傷，或被搶走，無人看見，","notes":[]},{"n":11,"t":"雙方要在耶和華前起誓，受託人要表明自己沒有伸手拿鄰舍的東西，原主要接受誓言，受託人不必賠償。","notes":[]},{"n":12,"t":"牲畜若從受託人那裏被偷去，他就要賠償原主；","notes":[]},{"n":13,"t":"若被野獸撕碎，受託人要帶回來作證據，被撕碎的就不必賠償。","notes":[]},{"n":14,"t":"「人若向鄰舍借牲畜，所借的或傷或死，原主沒有在場，借的人總要賠償。","notes":["原文沒有「牲畜」。"]},{"n":15,"t":"若原主在場，借的人不必賠償；若是租用的，只要付租金。」","notes":["「只要付租金」：原文是「牠來是為了租金」。"]},{"n":16,"t":"「人若引誘沒有訂婚的處女，與她同寢，他就必須交出聘禮，娶她為妻。","notes":[],"heads":["道德和宗教的條例"]},{"n":17,"t":"若女子的父親堅決不將女子給他，他就要按著處女的聘禮交出錢來。","notes":[]},{"n":18,"t":"「行邪術的女人，不可讓她存活。","notes":[]},{"n":19,"t":"「凡與獸交合的，必被處死。","notes":[]},{"n":20,"t":"「向別神獻祭，不單單獻給耶和華的，那人必要滅絕。","notes":[]},{"n":21,"t":"「不可虧待寄居的，也不可欺壓他，因為你們在埃及地也作過寄居的。","notes":[]},{"n":22,"t":"不可苛待寡婦和孤兒；","notes":[]},{"n":23,"t":"若你確實苛待他，他向我苦苦哀求，我一定會聽他的呼求，","notes":[]},{"n":24,"t":"並要發烈怒，用刀殺你們，使你們的妻子成為寡婦，兒女成為孤兒。","notes":[]},{"n":25,"t":"「我的子民中有困苦人在你那裏，你若借錢給他，不可如放債的向他取利息。","notes":[]},{"n":26,"t":"你果真拿了鄰舍的外衣作抵押，也要在日落前還給他；","notes":[]},{"n":27,"t":"因為他只有這一件用來作被子，是他蔽體的衣服。他還可以拿甚麼睡覺呢？當他哀求我，我就應允，因為我是有恩惠的。","notes":[]},{"n":28,"t":"「不可毀謗神；也不可詛咒你百姓的領袖。","notes":[]},{"n":29,"t":"「不可遲延獻你的莊稼、酒和油。「要將你頭生的兒子歸給我。","notes":["「你的莊稼、酒和油」：原文直譯「你的豐收和你的汁液」。"]},{"n":30,"t":"你的牛羊也要照樣做：七天當跟著牠母親，第八天你要把牠歸給我。","notes":[]},{"n":31,"t":"「你們要分別為聖歸給我。因此，田間被野獸撕裂的肉，你們不可吃，要把它丟給狗。」","notes":[]}]},"23":{"heading":"正義和公正","verses":[{"n":1,"t":"「不可散佈謠言；不可與惡人連手作惡意的見證。","notes":[]},{"n":2,"t":"不可附和群眾作惡；不可在訴訟中附和群眾歪曲公正，作歪曲的見證；","notes":[]},{"n":3,"t":"也不可在訴訟中偏袒貧寒人。","notes":[]},{"n":4,"t":"「若遇見你仇敵的牛或驢迷了路，務必牽回來交給他。","notes":[]},{"n":5,"t":"若看見恨你的人的驢被壓在重馱之下，不可走開，務要和他一同卸下驢的重馱。","notes":[]},{"n":6,"t":"「不可在貧窮人的訴訟中屈枉正直。","notes":[]},{"n":7,"t":"當遠離誣告的事。不可殺害無辜和義人，因我必不以惡人為義。","notes":[]},{"n":8,"t":"不可接受賄賂，因為賄賂能使明眼人變瞎，又能曲解義人的證詞。","notes":[]},{"n":9,"t":"「不可欺壓寄居的，因為你們在埃及地作過寄居的，知道寄居者的心情。」","notes":[]},{"n":10,"t":"「六年你要耕種田地，收集地的出產。","notes":[],"heads":["安息年和安息日"]},{"n":11,"t":"只是第七年你要讓地歇息，不耕不種，使你百姓中的貧窮人有吃的；他們吃剩的，野獸可以吃。你的葡萄園和橄欖園也要照樣辦理。","notes":[]},{"n":12,"t":"「六日你要做工，第七日要安息，使牛、驢可以歇息，也讓你使女的兒子和寄居的可以恢復精力。","notes":[]},{"n":13,"t":"「凡我對你們說的話，你們都要謹守。別神的名，你不可提，也不可用口說給人聽。」","notes":[]},{"n":14,"t":"「一年三次，你要向我守節。","notes":[],"heads":["三大節期"]},{"n":15,"t":"你要守除酵節，照我所吩咐你的，在亞筆月內所定的日期吃無酵餅七天，因為你是在這月離開了埃及。誰也不可空手來朝見我。","notes":[]},{"n":16,"t":"你要守收割節，收田間所種、勞碌所得初熟之物。你年底收藏田間勞碌所得時，要守收藏節。","notes":[]},{"n":17,"t":"所有的男丁都要一年三次朝見主耶和華。","notes":[]},{"n":18,"t":"「不可將我祭牲的血和有酵之物一同獻上，也不可將我節期中祭牲的脂肪留到早晨。","notes":[]},{"n":19,"t":"「要把地裏最好的初熟之物帶到耶和華－你神的殿中。「不可用母山羊的奶來煮牠的小山羊。」","notes":[]},{"n":20,"t":"「看哪，我要差遣使者在你前面，在路上保護你，領你到我所預備的地方。","notes":[],"heads":["應許和警戒"]},{"n":21,"t":"你們要在他面前謹慎，聽從他的話。不可抗拒他，否則他必不赦免你們的過犯，因為我的名在他身上。","notes":["「抗拒」：原文是「使他受苦」。"]},{"n":22,"t":"「你若真的聽從他的話，照我一切所說的去做，我就以你的仇敵為仇敵，以你的敵人為敵人。","notes":[]},{"n":23,"t":"「我的使者要走在你前面，領你到亞摩利人、赫人、比利洗人、迦南人、希未人、耶布斯人那裏，我必將他們除滅。","notes":[]},{"n":24,"t":"你不可跪拜事奉他們的神明，也不可隨從他們的習俗，卻要徹底廢除，完全打碎他們的柱像。","notes":[]},{"n":25,"t":"你們要事奉耶和華－你們的神，他必賜福給你的糧食和水，也必從你中間除去疾病。","notes":[]},{"n":26,"t":"你境內必沒有流產的、不生育的。我要使你享滿你年日的數目。","notes":[]},{"n":27,"t":"凡你所到的地方，我要使那裏的眾百姓在你面前驚慌失措，又要使你所有的仇敵轉身逃跑。","notes":[]},{"n":28,"t":"我要派瘟疫在你的前面，把希未人、迦南人、赫人從你面前趕出去。","notes":["「瘟疫」或譯「黃蜂」。"]},{"n":29,"t":"我不在一年之內把他們從你面前趕出去，恐怕地會荒廢，野地的走獸增多危害你。","notes":[]},{"n":30,"t":"我要逐漸把他們從你面前趕出去，直到你的人數增多，承受那地為業。","notes":[]},{"n":31,"t":"我要定你的疆界，從紅海直到非利士海，從曠野直到大河。我要把那地的居民交在你手中，你要把他們從你面前趕出去。","notes":[]},{"n":32,"t":"不可跟他們和他們的神明立約。","notes":[]},{"n":33,"t":"他們不可住在你的地上，免得他們使你得罪我。你若事奉他們的神明，必成為你的圈套。」","notes":[]}]},"24":{"heading":"立約的血","verses":[{"n":1,"t":"耶和華對摩西說：「你和亞倫、拿答、亞比戶，以及以色列長老中的七十人，都要上到耶和華這裏來，遠遠地下拜。","notes":[]},{"n":2,"t":"只有摩西可以接近耶和華，其他的人卻不可接近；百姓也不可和他一同上來。」","notes":[]},{"n":3,"t":"摩西下山，向百姓陳述耶和華一切的命令和典章。眾百姓齊聲說：「耶和華所吩咐的一切，我們都必遵行。」","notes":[]},{"n":4,"t":"摩西將耶和華一切的命令都寫下來。他清早起來，在山腳築了一座壇，按著以色列十二支派立了十二根石柱。","notes":[]},{"n":5,"t":"他差派以色列的年輕人去獻燔祭，又宰牛獻給耶和華為平安祭。","notes":[]},{"n":6,"t":"摩西將血的一半盛在盆中，另一半灑在壇上。","notes":[]},{"n":7,"t":"然後，他拿起約書來，念給百姓聽。他們說：「耶和華所吩咐的一切，我們都必遵行，也必聽從。」","notes":[]},{"n":8,"t":"摩西把血灑在百姓身上，說：「看哪！這是立約的血，是耶和華按照這一切的命令和你們立約的憑據。」","notes":[]},{"n":9,"t":"摩西、亞倫、拿答、亞比戶，以及以色列長老中的七十人都上去，","notes":[]},{"n":10,"t":"看見了以色列的神。在他的腳下，彷彿有藍寶石鋪道，明淨如天。","notes":[]},{"n":11,"t":"他不把手伸在以色列領袖的身上。他們瞻仰神，又吃又喝。","notes":[]},{"n":12,"t":"耶和華對摩西說：「你上山到我這裏來，就在那裏，我要將石版，就是我所寫的律法和誡命賜給你，使你可以教導他們。」","notes":[],"heads":["摩西在西奈山上"]},{"n":13,"t":"摩西和他的助手約書亞站起來；摩西上了神的山。","notes":[]},{"n":14,"t":"摩西對長老們說：「你們在這裏等我們，直到我們再回到你們這裏。看哪，亞倫和戶珥與你們同在。誰有訴訟，可以去找他們。」","notes":[]},{"n":15,"t":"摩西上山，有雲彩把山遮蓋。","notes":[]},{"n":16,"t":"耶和華的榮耀駐在西奈山，雲彩遮蓋了山六天，第七天他從雲中呼叫摩西。","notes":[]},{"n":17,"t":"耶和華的榮耀在山頂上，在以色列人眼前，形狀如吞噬的火。","notes":[]},{"n":18,"t":"摩西進入雲中，登上了山。摩西在山上四十晝夜。","notes":[]}]},"25":{"heading":"為聖所奉獻","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人獻禮物給我。凡甘心樂意獻給我的禮物，你們都可以收下。","notes":[]},{"n":3,"t":"要從他們收的禮物是：金、銀、銅，","notes":[]},{"n":4,"t":"藍色、紫色、朱紅色紗，細麻，山羊毛，","notes":["原文沒有「紗」；本卷書下同。"]},{"n":5,"t":"染紅的公羊皮、精美的皮料，金合歡木，","notes":[]},{"n":6,"t":"點燈的油，做膏油的香料、做香的香料，","notes":[]},{"n":7,"t":"紅瑪瑙與寶石，可以鑲嵌在以弗得和胸袋上。","notes":[]},{"n":8,"t":"他們要為我造聖所，使我住在他們中間。","notes":[]},{"n":9,"t":"你們要按照我指示你的，帳幕和其中一切器具的樣式，照樣去做。」","notes":[]},{"n":10,"t":"「他們要用金合歡木做一個櫃子，長二肘半，寬一肘半，高一肘半。","notes":[],"heads":["約櫃"]},{"n":11,"t":"你要把它裏裏外外包上純金，四圍要鑲上金邊。","notes":[]},{"n":12,"t":"要鑄造四個金環，安在櫃子的四腳上；這邊兩個環，那邊兩個環。","notes":[]},{"n":13,"t":"要用金合歡木做兩根槓，包上金子。","notes":[]},{"n":14,"t":"要把槓穿過櫃旁的環，以便抬櫃。","notes":[]},{"n":15,"t":"這槓要留在櫃的環內，不可抽出來。","notes":[]},{"n":16,"t":"要把我所要賜給你的法版放在櫃裏。","notes":["「法版」：原文是「見證」，指「立約的法度」；下同。"]},{"n":17,"t":"要用純金做一個櫃蓋，長二肘半，寬一肘半。","notes":["「櫃蓋」：原意「蓋住」，指「蓋住罪」，後來也稱為「施恩座」；本卷書下同。"]},{"n":18,"t":"要造兩個用金子錘出的基路伯，從櫃蓋的兩端錘出它們。","notes":[]},{"n":19,"t":"這端錘出一個基路伯，那端錘出一個基路伯；從櫃蓋的兩端錘出兩個基路伯。","notes":[]},{"n":20,"t":"二基路伯的翅膀要向上張開，用翅膀遮住櫃蓋，臉要彼此相對；基路伯的臉要朝向櫃蓋。","notes":[]},{"n":21,"t":"要把櫃蓋安在櫃的上邊，又要把我所要賜給你的法版放在櫃裏。","notes":[]},{"n":22,"t":"我要在那裏與你相會，並要從法版之櫃的櫃蓋上，兩個基路伯的中間，將我要吩咐以色列人的一切事告訴你。」","notes":[]},{"n":23,"t":"「你要用金合歡木做一張供桌，長二肘，寬一肘，高一肘半，","notes":[],"heads":["供桌"]},{"n":24,"t":"把它包上純金，四圍鑲上金邊。","notes":[]},{"n":25,"t":"供桌的四圍各做一掌寬的邊緣，邊緣周圍要鑲上金邊。","notes":[]},{"n":26,"t":"要為供桌做四個金環，把環安在四個桌腳的四角上。","notes":[]},{"n":27,"t":"環要靠近邊緣，以便穿槓抬供桌。","notes":[]},{"n":28,"t":"要用金合歡木做兩根槓，包上金子，用來抬供桌。","notes":[]},{"n":29,"t":"要用純金做桌上的盤、碟，以及澆酒祭的壺和杯。","notes":[]},{"n":30,"t":"要把供餅擺在桌上，常在我面前。」","notes":[]},{"n":31,"t":"「你要造一座用純金錘出的燈臺。燈臺的座、幹、杯、花萼和花瓣，都要和燈臺接連一塊。","notes":[],"heads":["燈臺"]},{"n":32,"t":"燈臺兩旁要伸出六根枝子：這邊三根，那邊三根。","notes":[]},{"n":33,"t":"這邊枝子上有三個杯，形狀像杏花，有花萼有花瓣；那邊枝子上也有三個杯，形狀像杏花，有花萼有花瓣。從燈臺伸出來的六根枝子都是如此。","notes":[]},{"n":34,"t":"燈臺本身要有四個杯，形狀像杏花，有花萼有花瓣。","notes":[]},{"n":35,"t":"燈臺的第一對枝子下面有花萼，燈臺的第二對枝子下面有花萼，燈臺的第三對枝子下面也有花萼；燈臺伸出的六根枝子都是如此。","notes":[]},{"n":36,"t":"花萼和枝子都要和燈臺接連一塊，全是從一塊純金錘出來的。","notes":[]},{"n":37,"t":"要做燈臺的七盞燈，燈要點燃，照亮前面。","notes":[]},{"n":38,"t":"要用純金做燈剪和燈盤。","notes":[]},{"n":39,"t":"做燈臺和這一切的器具要用一他連得純金。","notes":[]},{"n":40,"t":"要謹慎，照著在山上指示你的樣式去做。」","notes":[]}]},"26":{"heading":"帳幕","verses":[{"n":1,"t":"「你要用十幅幔子做帳幕。這些幔子要用搓的細麻和藍色、紫色、朱紅色紗織成，並且以刺繡的手藝繡上基路伯。","notes":[]},{"n":2,"t":"每幅幔子要長二十八肘，每幅幔子寬四肘，全部的幔子尺寸都要一樣。","notes":[]},{"n":3,"t":"這五幅幔子要彼此相連；那五幅幔子也彼此相連。","notes":[]},{"n":4,"t":"在這一組相連幔子的末幅邊上要縫藍色的鈕環；在另一組相連幔子的末幅邊上也要照樣做。","notes":[]},{"n":5,"t":"這幅幔子上要縫五十個鈕環，另一組相連幔子的末幅上也縫五十個鈕環，環環相對。","notes":[]},{"n":6,"t":"要做五十個金鉤，用鉤子使幔子彼此相連，成為一個帳幕。","notes":[]},{"n":7,"t":"「你要用山羊毛織十一幅幔子來作帳幕的罩棚。","notes":[]},{"n":8,"t":"每幅幔子要長三十肘，每幅幔子寬四肘；十一幅幔子的尺寸都要一樣。","notes":[]},{"n":9,"t":"要把五幅幔子連成一幅，又把六幅幔子連成一幅，這第六幅幔子要在罩棚的前面摺上去。","notes":[]},{"n":10,"t":"在這一組相連幔子的末幅邊上要縫五十個鈕環；在另一組相連幔子的末幅邊上也縫五十個鈕環。","notes":[]},{"n":11,"t":"要做五十個銅鉤，鉤在鈕環中，使罩棚相連成為一個。","notes":[]},{"n":12,"t":"罩棚幔子餘下垂著的，那餘下的半幅要垂在帳幕的背面。","notes":[]},{"n":13,"t":"罩棚的幔子兩旁所餘下的，這邊一肘，那邊一肘，要垂在帳幕的兩邊，蓋住帳幕。","notes":[]},{"n":14,"t":"要用染紅的公羊皮做罩棚的蓋，再用精美皮料做外層的蓋。","notes":[]},{"n":15,"t":"「你要用金合歡木做豎立帳幕的木板，","notes":[]},{"n":16,"t":"木板要長十肘，每塊板寬一肘半，","notes":[]},{"n":17,"t":"每塊板有兩個榫頭可以彼此銜接。帳幕一切的板都要這樣做。","notes":[]},{"n":18,"t":"你要做帳幕的木板：南面，就是面向南方的那一邊，要做二十塊板。","notes":[]},{"n":19,"t":"在這二十塊板底下要做四十個帶卯眼的銀座；兩個卯眼接連這塊板上的兩個榫頭，另外兩個卯眼接連那塊板上的兩個榫頭。","notes":[]},{"n":20,"t":"帳幕的第二邊，就是北面，也要做二十塊板，","notes":[]},{"n":21,"t":"和四十個帶卯眼的銀座；這塊板底下有兩個卯眼，那塊板底下也有兩個卯眼。","notes":[]},{"n":22,"t":"帳幕的後面，就是西面，要做六塊板。","notes":[]},{"n":23,"t":"帳幕後面的角落要做兩塊板。","notes":[]},{"n":24,"t":"下端的板是成雙的，上端要連在一起，直到頂端的第一個環子；兩塊板都要這樣，做成兩個角落。","notes":[]},{"n":25,"t":"一共有八塊板和十六個帶卯眼的銀座；這塊板底下有兩個卯眼，那塊板底下也有兩個卯眼。","notes":[]},{"n":26,"t":"「你要用金合歡木做橫木：為帳幕這面的板做五根橫木，","notes":[]},{"n":27,"t":"為帳幕那面的板做五根橫木，又為帳幕後面，就是朝西的板做五根橫木。","notes":[]},{"n":28,"t":"板腰間的橫木，要從一頭通到另一頭。","notes":[]},{"n":29,"t":"板要包上金子，又要做板上的金環來套橫木；橫木也要包上金子。","notes":[]},{"n":30,"t":"要照著在山上所指示你的樣式，把帳幕豎立起來。","notes":[]},{"n":31,"t":"「你要用藍色、紫色、朱紅色紗，和搓的細麻織幔子，以刺繡的手藝繡上基路伯。","notes":[]},{"n":32,"t":"要把幔子掛在四根包金的金合歡木柱子上，柱子有金鉤，並且安在四個帶卯眼的銀座上。","notes":[]},{"n":33,"t":"要把幔子垂掛在鉤子上，把法櫃抬進幔子內；這幔子要將聖所和至聖所隔開。","notes":[]},{"n":34,"t":"又要把櫃蓋安在至聖所內的法櫃上，","notes":[]},{"n":35,"t":"把供桌安在幔子的外面，供桌在北面，燈臺在帳幕的南面，和供桌相對。","notes":[]},{"n":36,"t":"「你要用藍色、紫色、朱紅色紗，和搓的細麻，以刺繡的手藝為帳幕織門簾。","notes":[]},{"n":37,"t":"要用金合歡木為簾子做五根柱子，包上金子。柱子有金鉤，又為柱子鑄造五個帶卯眼的銅座。」","notes":[]}]},"27":{"heading":"祭壇","verses":[{"n":1,"t":"「你要用金合歡木做祭壇，長五肘，寬五肘，這壇是正方形的，高三肘。","notes":[]},{"n":2,"t":"要在壇的四角做四個翹角，與壇接連一塊；要把壇包上銅。","notes":[]},{"n":3,"t":"要做桶子來盛壇上的灰，又要做鏟子、盤子、肉叉和火盆；壇上一切的器具都要用銅做。","notes":[]},{"n":4,"t":"要為壇做一個銅網，在網的四角做四個銅環，","notes":[]},{"n":5,"t":"把網安在壇四圍的邊的下面，使網垂到壇的半腰。","notes":[]},{"n":6,"t":"又要用金合歡木為壇做槓，包上銅。","notes":[]},{"n":7,"t":"這槓要穿過壇兩旁的環子，用來抬壇。","notes":[]},{"n":8,"t":"要用板做壇，壇的中心是空的，都照著在山上所指示你的樣式做。」","notes":[]},{"n":9,"t":"「你要做帳幕的院子。南面，就是面向南方的那一邊，要用搓的細麻做院子的帷幔，長一百肘，","notes":[],"heads":["院子"]},{"n":10,"t":"院子要有二十根柱子，二十個帶卯眼的銅座。要用銀做柱子的鉤和箍。","notes":[]},{"n":11,"t":"北面的長度也一樣，帷幔長一百肘，要有二十根柱子，二十個帶卯眼的銅座。要用銀做柱子的鉤和箍。","notes":[]},{"n":12,"t":"院子的西面有帷幔，寬五十肘，帷幔要有十根柱子，十個帶卯眼的座。","notes":[]},{"n":13,"t":"院子的東面，就是面向東方的那一邊，寬五十肘。","notes":[]},{"n":14,"t":"一邊的帷幔有十五肘，要有三根柱子，三個帶卯眼的座。","notes":[]},{"n":15,"t":"另一邊的帷幔也有十五肘，要有三根柱子，三個帶卯眼的座。","notes":[]},{"n":16,"t":"院子的門要有二十肘長的簾子，用藍色、紫色、朱紅色紗，和搓的細麻，以刺繡的手藝織成；要有四根柱子，四個帶卯眼的座。","notes":[]},{"n":17,"t":"院子四圍一切的柱子都要用銀子箍著，要用銀做柱子的鉤子，用銅做帶卯眼的座。","notes":[]},{"n":18,"t":"院子要長一百肘，寬五十肘，高五肘。要用搓的細麻做帷幔，用銅做帶卯眼的座。","notes":["「五十肘」是根據撒瑪利亞五經；原文是「五十、五十」，指從南到北都是五十。"]},{"n":19,"t":"帳幕中各樣用途的器具，以及帳幕一切的橛子和院子裏一切的橛子，都要用銅做。」","notes":[]},{"n":20,"t":"「你要吩咐以色列人，把搗成的純橄欖油拿來給你，用以點燈，使燈經常點著；","notes":[],"heads":["燃燈的條例"]},{"n":21,"t":"在會幕中法櫃前的幔子外，亞倫和他的兒子要從晚上到早晨，在耶和華面前照管這燈。這要成為以色列人世世代代永遠的定例。」","notes":[]}]},"28":{"heading":"祭司的聖服","verses":[{"n":1,"t":"「你要從以色列人中，叫你的哥哥亞倫和他的兒子拿答、亞比戶、以利亞撒、以他瑪一同親近你，作事奉我的祭司。","notes":[]},{"n":2,"t":"你要為你哥哥亞倫做聖衣，以示尊嚴和華美。","notes":[]},{"n":3,"t":"要吩咐一切心中有智慧的，就是我用智慧的靈所充滿的人，為亞倫做衣服，使他分別為聖，作事奉我的祭司。","notes":[]},{"n":4,"t":"所要做的是胸袋、以弗得、外袍、織成的內袍、禮冠和腰帶。他們要為你哥哥亞倫和他的兒子做聖衣，使他們作祭司事奉我。","notes":[]},{"n":5,"t":"要用金色、藍色、紫色、朱紅色紗，和細麻去縫製。」","notes":[]},{"n":6,"t":"「他們要用金色、藍色、紫色、朱紅色紗，和搓的細麻，以刺繡的手藝做以弗得。","notes":[],"heads":["以弗得"]},{"n":7,"t":"以弗得當有兩條肩帶，接上兩端，使它相連。","notes":[]},{"n":8,"t":"以弗得的精緻帶子，要以一樣的手藝，用金色、藍色、紫色、朱紅色紗，和搓的細麻縫製，與以弗得接連在一起。","notes":[]},{"n":9,"t":"要取兩塊紅瑪瑙，在上面刻以色列兒子的名字：","notes":[]},{"n":10,"t":"六個名字在一塊寶石上，六個名字在另一塊寶石上，都按照他們出生的次序。","notes":[]},{"n":11,"t":"要以雕刻寶石的手藝，如同刻印章，把以色列兒子的名字刻在這兩塊寶石上，並把寶石鑲在金槽裏。","notes":[]},{"n":12,"t":"要把這兩塊寶石安在以弗得的兩條肩帶上，為以色列人作紀念石。亞倫要在耶和華面前把他們的名字帶在兩肩上，作為紀念。","notes":[]},{"n":13,"t":"要用金子做兩個槽，","notes":[]},{"n":14,"t":"再用純金打兩條鏈子，像編成的繩子一樣，把這編成的金鏈扣在槽上。」","notes":[]},{"n":15,"t":"「你要以刺繡的手藝做一個決斷的胸袋，和做以弗得的方法一樣，用金色、藍色、紫色、朱紅色紗，和搓的細麻縫製。","notes":[],"heads":["胸袋"]},{"n":16,"t":"胸袋是正方形的，疊成兩層，長一虎口，寬一虎口。","notes":[]},{"n":17,"t":"要在上面鑲四行寶石：第一行是紅寶石、紅璧璽、紅玉；","notes":[]},{"n":18,"t":"第二行是綠寶石、藍寶石、金剛石；","notes":[]},{"n":19,"t":"第三行是紫瑪瑙、白瑪瑙、紫晶；","notes":[]},{"n":20,"t":"第四行是水蒼玉、紅瑪瑙、碧玉。這些都要鑲在金槽中。","notes":[]},{"n":21,"t":"這些寶石要有以色列十二個兒子的名字，如同刻印章，每一顆有自己的名字，代表十二個支派。","notes":[]},{"n":22,"t":"要在胸袋上用純金打鏈子，像編成的繩子一樣。","notes":[]},{"n":23,"t":"要為胸袋做兩個金環，把這兩個環安在胸袋的兩端。","notes":[]},{"n":24,"t":"要把那兩條編成的金鏈繫在胸袋兩端的兩個環上。","notes":[]},{"n":25,"t":"又要把鏈子的另外兩端扣在兩個槽上，安在以弗得前面的肩帶上。","notes":[]},{"n":26,"t":"要做兩個金環，安在胸袋的兩端，在以弗得裏面的邊上。","notes":[]},{"n":27,"t":"再做兩個金環，安在以弗得前面兩條肩帶的下邊，靠近接縫處，在以弗得精緻帶子的上面。","notes":[]},{"n":28,"t":"要用藍色的帶子把胸袋的環與以弗得的環繫住，使胸袋綁在以弗得的精緻帶子上，不致鬆脫。","notes":[]},{"n":29,"t":"亞倫進聖所的時候，要把刻著以色列兒子名字的決斷胸袋帶著，放在心上，在耶和華面前常作紀念。","notes":[]},{"n":30,"t":"又要將烏陵和土明放在決斷胸袋裏；亞倫進到耶和華面前的時候，要放在心上。這樣，亞倫在耶和華面前要把以色列人的決斷胸袋常常帶著，放在心上。」","notes":["「烏陵和土明」指祭司用以求問神旨意的神器。"]},{"n":31,"t":"「你要做以弗得的外袍，顏色全是藍的。","notes":[],"heads":["祭司的其他聖服"]},{"n":32,"t":"袍上方的中間要留一個領口，領口周圍的領邊要以手藝編織而成，好像鎧甲的領口，免得破裂。","notes":[]},{"n":33,"t":"袍子下襬，就是下襬的周圍要用藍色、紫色、朱紅色紗做石榴，周圍的石榴中間要有金鈴鐺：","notes":[]},{"n":34,"t":"一個金鈴鐺一個石榴，一個金鈴鐺一個石榴，在袍子下襬的周圍。","notes":[]},{"n":35,"t":"亞倫供職的時候要穿這袍。他進入聖所到耶和華面前，以及出來的時候，袍上的鈴聲必被聽見，使他不至於死。","notes":[]},{"n":36,"t":"「你要用純金做一面牌，如同刻印章，在上面刻『歸耶和華為聖』。","notes":[]},{"n":37,"t":"要用藍色的帶子把牌繫在禮冠上，在禮冠的正前面。","notes":[]},{"n":38,"t":"這牌必在亞倫的額上，亞倫要擔當干犯聖物的罪孽；這聖物是以色列人在一切聖禮物上所分別為聖的。這牌要常在他的額上，使他們可以在耶和華面前蒙悅納。","notes":[]},{"n":39,"t":"要用細麻編織內袍，用細麻做禮冠，又以刺繡的手藝做腰帶。","notes":[]},{"n":40,"t":"「你要為亞倫的兒子做內袍、腰帶、頭巾，以示尊嚴和華美。","notes":[]},{"n":41,"t":"要把這些給你哥哥亞倫和他的兒子穿戴，又要膏他們，授予聖職，使他們分別為聖，作事奉我的祭司。","notes":[]},{"n":42,"t":"要用細麻布給他們做褲子來遮掩下體，從腰間直到大腿。","notes":[]},{"n":43,"t":"亞倫和他兒子進入會幕，或接近祭壇，在聖所供職的時候要穿上褲子，免得擔當罪孽而死。這要成為亞倫和他後裔永遠的定例。」","notes":[]}]},"29":{"heading":"祭司的聖職禮","verses":[{"n":1,"t":"「這是你使他們分別為聖，作事奉我的祭司時要做的事：取一頭公牛犢，兩隻無殘疾的公綿羊，","notes":[]},{"n":2,"t":"無酵餅、用油調和的無酵餅，和抹油的無酵薄餅；這些餅都要用細麥麵做成。","notes":[]},{"n":3,"t":"這些餅要裝在一個籃子裏，用籃子帶來，又把公牛和兩隻公綿羊牽來。","notes":[]},{"n":4,"t":"要帶亞倫和他兒子到會幕的門口，用水洗他們。","notes":[]},{"n":5,"t":"要拿服裝，給亞倫穿上內袍和以弗得的外袍，以及以弗得，又帶上胸袋，束上以弗得精緻的帶子。","notes":[]},{"n":6,"t":"要把禮冠戴在他頭上，將聖冕加在禮冠上，","notes":[]},{"n":7,"t":"把膏油倒在他頭上膏他。","notes":[]},{"n":8,"t":"要帶他的兒子來，給他們穿上內袍。","notes":[]},{"n":9,"t":"要給亞倫和他的兒子束上腰帶，裹上頭巾，他們就憑永遠的定例得祭司的職分。又要授聖職給亞倫和他的兒子。","notes":[]},{"n":10,"t":"「你要把公牛牽到會幕前，亞倫和他的兒子要按手在公牛的頭上。","notes":[]},{"n":11,"t":"你要在耶和華面前，在會幕的門口宰這公牛。","notes":[]},{"n":12,"t":"要取些公牛的血，用指頭抹在祭壇的四個翹角上，把其餘的血全倒在壇的底座上。","notes":[]},{"n":13,"t":"要把所有包著內臟的脂肪、肝上的網油、兩個腎和腎上的脂肪，都燒在壇上。","notes":[]},{"n":14,"t":"只是公牛的肉、皮、糞都要在營外用火焚燒；這牛是贖罪祭。","notes":[]},{"n":15,"t":"「你要牽一隻公綿羊來，亞倫和他兒子要按手在這羊的頭上。","notes":[]},{"n":16,"t":"你要宰這羊，把血灑在祭壇的周圍。","notes":[]},{"n":17,"t":"再把羊切成肉塊，洗淨內臟和腿，連肉塊和頭放在一處。","notes":[]},{"n":18,"t":"要把全羊燒在壇上。這是獻給耶和華的燔祭，是獻給耶和華馨香的火祭。」","notes":[]},{"n":19,"t":"「你要把第二隻公綿羊牽來，亞倫和他兒子要按手在這羊的頭上。","notes":[]},{"n":20,"t":"你要宰這羊，取些血抹在亞倫的右耳垂和他兒子的右耳垂上，又抹在他們右手的大拇指和右腳的大腳趾上，然後把其餘的血灑在壇的周圍。","notes":[]},{"n":21,"t":"你要取些膏油和壇上的血，彈在亞倫和他的衣服上，以及他兒子和他們的衣服上；亞倫和他的衣服，他兒子和他們的衣服都成為聖了。","notes":[]},{"n":22,"t":"「你要取這羊的脂肪，肥尾巴、包著內臟的脂肪、肝上的網油、兩個腎、腎上的脂肪和右腿，這是聖職禮所獻的公綿羊；","notes":[]},{"n":23,"t":"再從耶和華面前那裝無酵餅的籃子中取一個餅、一個油餅和一個薄餅，","notes":[]},{"n":24,"t":"把它們都放在亞倫的手和他兒子的手上，在耶和華面前搖一搖，作為搖祭。","notes":[]},{"n":25,"t":"然後，你要從他們手中接過來，放在燔祭上，一起燒在壇上，作為耶和華面前馨香之氣；這是獻給耶和華的火祭。","notes":[]},{"n":26,"t":"「你要取亞倫聖職禮所獻公綿羊的胸，在耶和華面前搖一搖，作為搖祭；這份就是你的。","notes":[]},{"n":27,"t":"那搖祭的胸和舉祭的腿，就是聖職禮獻公綿羊時所搖的、所舉的，你要使它們分別為聖，是歸給亞倫和他兒子的。","notes":[]},{"n":28,"t":"這是亞倫和他子孫憑永遠的定例從以色列人中所應得的；因為這是舉祭，是從以色列人的平安祭中取出，作為獻給耶和華的舉祭。","notes":[]},{"n":29,"t":"「亞倫的聖衣要傳給他的子孫，使他們在受膏和承接聖職的時候穿上。","notes":[]},{"n":30,"t":"他的子孫接續他當祭司的，每逢進入會幕在聖所供職的時候，要穿這聖衣七天。","notes":[]},{"n":31,"t":"「你要拿聖職禮所獻的公綿羊，在聖處煮牠的肉。","notes":[]},{"n":32,"t":"亞倫和他兒子要在會幕的門口吃這羊的肉和籃子裏的餅。","notes":[]},{"n":33,"t":"他們要吃那些用來贖罪之物，好承接聖職，使他們分別為聖。外人不可吃，因為這是聖物。","notes":[]},{"n":34,"t":"那聖職禮所獻的肉或餅，若有剩餘留到早晨，就要把剩下的用火燒了，不可再吃，因為這是聖物。","notes":[]},{"n":35,"t":"「你要這樣照我一切所吩咐的，向亞倫和他兒子行授聖職禮七天。","notes":[]},{"n":36,"t":"為了贖罪，每天要獻一頭公牛為贖罪祭。你要為祭壇贖罪，使壇潔淨，並要用膏抹壇，使壇成為聖。","notes":[]},{"n":37,"t":"要為壇贖罪七天，使壇成為聖，壇就成為至聖。凡觸摸壇的都成為聖。」","notes":[]},{"n":38,"t":"「這是你要獻在壇上的：每天不可間斷地獻兩隻一歲的羔羊；","notes":[],"heads":["每天當獻的祭"]},{"n":39,"t":"早晨獻第一隻羔羊，黃昏獻第二隻羔羊。","notes":[]},{"n":40,"t":"獻第一隻羔羊時，要同時獻上十分之一伊法細麵，調和四分之一欣搗成的油，再獻四分之一欣酒作澆酒祭。","notes":[]},{"n":41,"t":"黃昏你獻第二隻羔羊，要照早晨的素祭和同獻的澆酒祭獻上，作為獻給耶和華馨香的火祭。","notes":[]},{"n":42,"t":"這要在耶和華面前，在會幕的門口，作為你們世世代代經常獻的燔祭。我要在那裏與你們相會，和你說話。","notes":["「你們」：七十士譯本是「你」。"]},{"n":43,"t":"我要在那裏與以色列人相會，會幕就要因我的榮耀成為聖。","notes":[]},{"n":44,"t":"我要使會幕和祭壇分別為聖，也要使亞倫和他的兒子分別為聖，作事奉我的祭司。","notes":[]},{"n":45,"t":"我要住在以色列人中，作他們的神。","notes":[]},{"n":46,"t":"他們必知道我是耶和華－他們的神，是將他們從埃及地領出來的，為要住在他們中間。我是耶和華－他們的神 。」","notes":[]}]},"30":{"heading":"香壇","verses":[{"n":1,"t":"「你要用金合歡木做一座燒香的壇，","notes":[]},{"n":2,"t":"長一肘，寬一肘，這壇是正方形的，高二肘。壇的四個翹角與壇接連一塊。","notes":[]},{"n":3,"t":"要把壇的上面與壇的四圍，以及壇的四個翹角包上純金；又要在壇的四圍鑲上金邊。","notes":[]},{"n":4,"t":"要在壇的兩個對側，金邊下面做兩個金環，用來穿槓抬壇。","notes":[]},{"n":5,"t":"要用金合歡木做槓，包上金子。","notes":[]},{"n":6,"t":"要把壇放在法櫃前的幔子外，對著法櫃上的櫃蓋，就是我與你相會的地方。","notes":[]},{"n":7,"t":"亞倫要在壇上燒芬芳的香；每早晨整理燈的時候，他都要燒這香。","notes":[]},{"n":8,"t":"黃昏點燈的時候，亞倫也要燒這香。這是你們世世代代在耶和華面前常燒的香。","notes":[]},{"n":9,"t":"在這壇上不可燒別樣的香，不可獻燔祭、素祭，也不可獻澆酒祭。","notes":[]},{"n":10,"t":"亞倫每年一次要為壇的四個翹角贖罪。他每年一次要用贖罪祭的血為壇贖罪，作為世世代代的定例。這壇在耶和華面前是至聖的。」","notes":[]},{"n":11,"t":"耶和華吩咐摩西說：","notes":[],"heads":["贖命的禮物"]},{"n":12,"t":"「你數點以色列人，計算人頭時，被數的每一個人要把他生命的贖價獻給耶和華，免得災殃在數點中臨到他們。","notes":[]},{"n":13,"t":"每一個被數的人要按照聖所的舍客勒，付半舍客勒，一舍客勒是二十季拉；這半舍客勒是獻給耶和華的禮物。","notes":[]},{"n":14,"t":"每一個被數的人，就是二十歲以上的，要將這禮物獻給耶和華。","notes":[]},{"n":15,"t":"富有的不必多付，貧窮的也不可少出，各人都要獻半舍客勒給耶和華，作你們生命的贖價。","notes":[]},{"n":16,"t":"你要向以色列人收這贖罪的銀子，用在會幕的事工。這要在耶和華面前為以色列人作紀念，作你們生命的贖價。」","notes":[]},{"n":17,"t":"耶和華吩咐摩西說：","notes":[],"heads":["銅盆"]},{"n":18,"t":"「你要用銅做洗濯盆和盆座，用來洗濯。要將盆放在會幕和祭壇的中間，盆裏盛水。","notes":[]},{"n":19,"t":"亞倫和他的兒子要用這盆洗手洗腳。","notes":[]},{"n":20,"t":"他們進會幕，或是走近壇前供職，獻火祭給耶和華的時候，必須用水洗濯，免得死亡；","notes":[]},{"n":21,"t":"他們要洗手洗腳，免得死亡。這是亞倫和他的後裔世世代代永遠的定例。」","notes":[]},{"n":22,"t":"耶和華吩咐摩西說：","notes":[],"heads":["聖膏油"]},{"n":23,"t":"「你要取上等的香料，就是五百舍客勒流質的沒藥、二百五十香肉桂、二百五十香菖蒲，","notes":[]},{"n":24,"t":"和五百桂皮，都按照聖所的舍客勒；再取一欣橄欖油，","notes":[]},{"n":25,"t":"以做香的方法調和製成聖膏油，它就成為聖膏油。","notes":[]},{"n":26,"t":"要用這膏油抹會幕和法櫃，","notes":[]},{"n":27,"t":"供桌和供桌的一切器具，燈臺和燈臺的器具，以及香壇、","notes":["「器具」：有古卷和七十士譯本是「一切器具」。"]},{"n":28,"t":"燔祭壇和壇的一切器具，洗濯盆和盆座。","notes":[]},{"n":29,"t":"你要使這些分別為聖，成為至聖；凡觸摸它們的都成為聖。","notes":[]},{"n":30,"t":"要膏亞倫和他的兒子，使他們分別為聖，作事奉我的祭司。","notes":[]},{"n":31,"t":"你要吩咐以色列人說：『你們要世世代代以這油為我的聖膏油。","notes":[]},{"n":32,"t":"不可把這油倒在別人身上，也不可用配製這膏油的方法製成同樣的膏油。這膏油是聖的，你們要以它為聖。","notes":[]},{"n":33,"t":"凡調和與此類似的膏油，或將它膏在別人身上的，這人要從百姓中剪除。』」","notes":[]},{"n":34,"t":"耶和華吩咐摩西說：「你要取香料，就是拿他弗、施喜列、喜利比拿，這些香料再加純乳香，每樣都要相同的分量。","notes":[],"heads":["香的做法"]},{"n":35,"t":"你要用這些加上鹽，以配製香料的方法，製成純淨又神聖的香。","notes":[]},{"n":36,"t":"要取一點這香，搗成細的粉，放在會幕中的法櫃前，就是我和你相會的地方。你們要以這香為至聖。","notes":[]},{"n":37,"t":"你們不可用這配製的方法為自己做香；要以這香為聖，歸於耶和華。","notes":[]},{"n":38,"t":"為要聞香味而配製同樣的香的，這人要從百姓中剪除。」","notes":[]}]},"31":{"heading":"會幕的技工","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你看，我已經題名召猶大支派中戶珥的孫子，烏利的兒子比撒列。","notes":[]},{"n":3,"t":"我以神的靈充滿他，使他有智慧，有聰明，有知識，能做各樣的工，","notes":[]},{"n":4,"t":"能設計圖案，用金、銀、銅製造各物，","notes":[]},{"n":5,"t":"又能雕刻鑲嵌用的寶石，雕刻木頭，做各樣的工。","notes":[]},{"n":6,"t":"看哪，我委派但支派中亞希撒抹的兒子亞何利亞伯與他同工。凡心裏有智慧的，我更要賜給他們智慧的心，能做我所吩咐的一切，","notes":[]},{"n":7,"t":"就是會幕、法櫃和其上的櫃蓋、會幕中一切的器具、","notes":[]},{"n":8,"t":"供桌和供桌的器具、純金的燈臺和燈臺的一切器具、香壇、","notes":[]},{"n":9,"t":"燔祭壇和壇的一切器具、洗濯盆與盆座、","notes":[]},{"n":10,"t":"供祭司職分用的精緻禮服，亞倫祭司的聖衣和他兒子的衣服，","notes":[]},{"n":11,"t":"以及膏油和聖所用的芬芳的香。他們都要照我所吩咐的一切去做。」","notes":[]},{"n":12,"t":"耶和華對摩西說：","notes":[],"heads":["要守安息日"]},{"n":13,"t":"「你要吩咐以色列人說：『你們務要守我的安息日，因為這是你我之間世世代代的記號，叫你們知道我是耶和華，是使你們分別為聖的。","notes":[]},{"n":14,"t":"你們要守安息日，以它為聖日。凡干犯這日的，必被處死；凡在這日做工的，那人必從百姓中剪除。","notes":[]},{"n":15,"t":"六日要做工，但第七日是向耶和華守完全安息的安息聖日。凡在安息日做工的，必被處死。』","notes":[]},{"n":16,"t":"以色列人要守安息日，世世代代守安息日為永遠的約。","notes":[]},{"n":17,"t":"這是我和以色列人之間永遠的記號，因為六日之內耶和華造天地，第七日就安息舒暢。」","notes":[]},{"n":18,"t":"耶和華在西奈山和摩西說完了話，就把兩塊法版交給他，是神用指頭寫的石版。","notes":[]}]},"32":{"heading":"金牛犢","verses":[{"n":1,"t":"百姓見摩西遲遲不下山，就聚集到亞倫那裏，對他說：「起來！為我們造神明，在我們前面引路，因為領我們出埃及地的那個摩西，我們不知道他遭遇了甚麼事。」","notes":[]},{"n":2,"t":"亞倫對他們說：「你們去摘下你們妻子、兒女耳上的金環，拿來給我。」","notes":[]},{"n":3,"t":"眾百姓就摘下他們耳上的金環，拿來給亞倫。","notes":[]},{"n":4,"t":"亞倫從他們手裏接過來，用模子塑造它，把它鑄成一頭牛犢。他們就說：「以色列啊，這是領你出埃及地的神明！」","notes":[]},{"n":5,"t":"亞倫看見，就在牛犢面前築壇。亞倫宣告說：「明日要向耶和華守節。」","notes":[]},{"n":6,"t":"次日清早，百姓起來獻燔祭和平安祭，就坐下吃喝，起來玩樂。","notes":[]},{"n":7,"t":"耶和華吩咐摩西：「下去吧，因為你從埃及領上來的百姓已經敗壞了。","notes":[]},{"n":8,"t":"他們這麼快偏離了我所吩咐的道，為自己鑄了一頭牛犢，向它跪拜，向它獻祭，說：『以色列啊，這就是領你出埃及地的神明。』」","notes":[]},{"n":9,"t":"耶和華對摩西說：「我看這百姓，看哪，他們真是硬著頸項的百姓。","notes":[]},{"n":10,"t":"現在，你且由著我，我要向他們發烈怒，滅絕他們，但我要使你成為大國。」","notes":[]},{"n":11,"t":"摩西就懇求耶和華－他的神，說：「耶和華啊，你為甚麼向你的百姓發烈怒呢？這百姓是你用大能大力的手從埃及地領出來的！","notes":[]},{"n":12,"t":"為甚麼讓埃及人說：『他領他們出去，是要降災禍給他們，在山中把他們殺了，將他們從地上除滅』呢？求你回心轉意，不發你的烈怒，不降災禍給你的百姓。","notes":[]},{"n":13,"t":"求你記念你的僕人亞伯拉罕、以撒、以色列。你曾向他們指著自己起誓說：『我必使你們的後裔像天上的星那樣多，並且我要將所應許的這全地賜給你們的後裔，讓他們永遠承受為業。』」","notes":[]},{"n":14,"t":"於是耶和華改變心意，不把所說的災禍降給他的百姓。","notes":[]},{"n":15,"t":"摩西轉身下山，手裏拿著兩塊法版。這版的兩面都寫著字，正面背面都有字。","notes":[]},{"n":16,"t":"版是神的工作，字是神寫的字，刻在版上。","notes":[]},{"n":17,"t":"約書亞一聽見百姓呼喊的聲音，就對摩西說：「在營裏有戰爭的聲音。」","notes":[]},{"n":18,"t":"摩西說：「這不是打勝仗的聲音，也不是打敗仗的聲音，我聽見的是歌唱的聲音。」","notes":[]},{"n":19,"t":"摩西走近營前，看見牛犢，又看見人在跳舞，就發烈怒，把兩塊版從手中扔到山下摔碎了。","notes":[]},{"n":20,"t":"他將他們所鑄的牛犢用火焚燒，磨得粉碎，撒在水面上，叫以色列人喝。","notes":[]},{"n":21,"t":"摩西對亞倫說：「這百姓向你做了甚麼呢？你竟使他們陷入大罪中！」","notes":[]},{"n":22,"t":"亞倫說：「求我主不要發烈怒。你知道這百姓，他們是向惡的。","notes":[]},{"n":23,"t":"他們對我說：『你為我們造神明，在我們前面引路，因為領我們出埃及地的那個摩西，我們不知道他遭遇了甚麼事。』","notes":[]},{"n":24,"t":"我對他們說：『凡有金環的可以摘下來』，他們就給了我。我把金環扔在火中，這牛犢就出來了。」","notes":[]},{"n":25,"t":"摩西見百姓放肆，因亞倫縱容他們，使這事成了敵人的笑柄，","notes":[]},{"n":26,"t":"就站在營門前，說：「凡屬耶和華的人，都到我這裏來！」於是利未人都聚集到他那裏。","notes":[]},{"n":27,"t":"他對他們說：「耶和華－以色列的神這樣說：『你們各人把刀佩在腰間，從這門到那門，來回走遍全營，各人要殺自己的弟兄、鄰舍和親人。』」","notes":[]},{"n":28,"t":"利未人遵照摩西的話做了。那一天百姓中倒下的約有三千人。","notes":[]},{"n":29,"t":"摩西說：「今天你們要奉獻自己來事奉耶和華，因為各人犧牲自己的兒子和弟兄，使耶和華今天賜福給你們。」","notes":["「你們要奉獻自己」：七十士譯本是「你們已奉獻自己」。"]},{"n":30,"t":"第二天，摩西對百姓說：「你們犯了大罪。我如今要上耶和華那裏去，或許可以為你們贖罪。」","notes":[]},{"n":31,"t":"摩西回到耶和華那裏，說：「唉！這百姓犯了大罪，為自己造了金的神明。","notes":[]},{"n":32,"t":"現在，求你赦免他們的罪；不然，就把我從你所寫的冊上除名。」","notes":[]},{"n":33,"t":"耶和華對摩西說：「誰得罪我，我就把他從我的冊上除去。","notes":[]},{"n":34,"t":"現在你去，領這百姓往我所告訴你的地方去，看哪，我的使者必在你的前面引路。到了該懲罰的時候，我必懲罰他們的罪。」","notes":[]},{"n":35,"t":"耶和華降災與百姓，因為他們和亞倫一起造了牛犢。","notes":[]}]},"33":{"heading":"起程的吩咐","verses":[{"n":1,"t":"耶和華吩咐摩西說：「去，離開這裏，你和你從埃及地領出來的百姓要上到我起誓應許給亞伯拉罕、以撒和雅各之地去；我曾對他們說：『我要將這地賜給你的後裔』。","notes":[]},{"n":2,"t":"我要差遣使者在你前面，把迦南人、亞摩利人、赫人、比利洗人、希未人、耶布斯人趕出","notes":[]},{"n":3,"t":"那流奶與蜜之地。但我不與你們上去，因為你們是硬著頸項的百姓，免得我在路上把你們滅絕。」","notes":[]},{"n":4,"t":"百姓一聽見這壞的信息，他們就悲哀，沒有人佩戴首飾。","notes":[]},{"n":5,"t":"耶和華對摩西說：「你對以色列人說：『你們是硬著頸項的百姓，我若在你們中間一起上去，只一瞬間，就必把你們滅絕。現在把你們身上的首飾摘下來，我好知道該怎樣處置你們。』」","notes":[]},{"n":6,"t":"以色列人離開何烈山以後，就把身上的首飾摘下來。","notes":[]},{"n":7,"t":"摩西拿一個帳棚支搭在營外，離營有一段距離，他稱這帳棚為會幕。凡求問耶和華的，就到營外的會幕那裏去。","notes":[],"heads":["摩西進會幕"]},{"n":8,"t":"當摩西出營到會幕去的時候，百姓就都起來，各人站在自己帳棚的門口，望著摩西，直到他進了會幕。","notes":[]},{"n":9,"t":"摩西進會幕的時候，雲柱就降下來，停在會幕的門前，耶和華就與摩西說話。","notes":[]},{"n":10,"t":"眾百姓看見雲柱停在會幕的門前，就都起來，各人在自己帳棚的門口下拜。","notes":[]},{"n":11,"t":"耶和華與摩西面對面說話，好像人與朋友說話。摩西回到營裏去，他的年輕助手嫩的兒子約書亞卻沒有離開會幕。","notes":[]},{"n":12,"t":"摩西對耶和華說：「看，你曾對我說：『將這百姓領上去』；卻沒有讓我知道你要差派誰與我同去。你還說：『我按你的名認識你，你也在我眼前蒙了恩。』","notes":[],"heads":["耶和華應許跟百姓同去"]},{"n":13,"t":"我如今若在你眼前蒙恩，求你將你的道指示我，使我可以認識你，並在你眼前蒙恩。求你顧念這國是你的子民。」","notes":[]},{"n":14,"t":"耶和華說：「我必親自去，讓你安心。」","notes":[]},{"n":15,"t":"摩西說：「你若不親自去，就不要把我們從這裏領上去。","notes":[]},{"n":16,"t":"現在，人如何得知我和你的百姓在你眼前蒙恩呢？豈不是因為你與我們同去，使我和你的百姓與地面上的萬民有分別嗎？」","notes":[]},{"n":17,"t":"耶和華對摩西說：「你所說的這件事，我也會去做，因為你在我眼前蒙了恩，並且我按你的名認識你。」","notes":[]},{"n":18,"t":"摩西說：「求你顯出你的榮耀給我看。」","notes":[]},{"n":19,"t":"耶和華說：「我要顯示我一切的美善，在你面前經過，並要在你面前宣告耶和華的名。我要恩待誰就恩待誰，要憐憫誰就憐憫誰。」","notes":[]},{"n":20,"t":"他又說：「只是你不能看見我的面，因為沒有人看見我還可以存活。」","notes":[]},{"n":21,"t":"耶和華說：「看哪，靠近我這裏有個地方，你可以站在這磐石上。","notes":[]},{"n":22,"t":"當我的榮耀經過的時候，我必將你放在磐石縫裏，用我的手掌遮掩你，等我過去，","notes":[]},{"n":23,"t":"然後我要將我的手掌收回，你就可以看見我的背，卻看不到我的面。」","notes":[]}]},"34":{"heading":"復造法版","verses":[{"n":1,"t":"耶和華對摩西說：「你要鑿出兩塊石版，和先前的一樣；我要把你摔碎的那版上先前所寫的字，寫在這版上。","notes":[]},{"n":2,"t":"明日早晨，你要預備好了，上西奈山，在山頂那裏站在我面前。","notes":[]},{"n":3,"t":"誰也不可和你上去，整座山都不可見到人，也不可有羊群牛群在山下吃草。」","notes":[]},{"n":4,"t":"摩西就鑿出兩塊石版，和先前的一樣。他清晨起來，遵照耶和華吩咐他的，上西奈山去，手裏拿著兩塊石版。","notes":[]},{"n":5,"t":"耶和華在雲中降臨，與摩西一同站在那裏，宣告耶和華的名。","notes":[]},{"n":6,"t":"耶和華在他面前經過，宣告：「耶和華，耶和華，有憐憫，有恩惠的神，不輕易發怒，且有豐盛的慈愛和信實，","notes":[]},{"n":7,"t":"為千代的人存留慈愛，赦免罪孽、過犯和罪惡，萬不以有罪的為無罪，必懲罰人的罪，自父及子，直到三、四代。」","notes":[]},{"n":8,"t":"摩西急忙俯伏在地敬拜，","notes":[]},{"n":9,"t":"說：「主啊，我若在你眼前蒙恩，求主在我們中間同行。雖然這是硬著頸項的百姓，求你赦免我們的罪孽和罪惡，接納我們為你的產業。」","notes":[]},{"n":10,"t":"耶和華說：「看哪，我要立約，要在你眾百姓面前行奇妙的事，是在全地萬國中未曾做過的。你周圍的萬民要看見我藉著你所行，耶和華可畏懼的作為。","notes":[],"heads":["重新立約"]},{"n":11,"t":"「我今天所吩咐你的，你要謹守。看哪，我要從你面前趕出亞摩利人、迦南人、赫人、比利洗人、希未人、耶布斯人。","notes":[]},{"n":12,"t":"你要謹慎，不可與你所要去那地的居民立約，免得他們成為你中間的圈套。","notes":[]},{"n":13,"t":"你要拆毀他們的祭壇，打碎他們的柱像，砍斷他們的亞舍拉。","notes":[]},{"n":14,"t":"不可敬拜別神，因為耶和華是忌邪的神，他的名是忌邪者。","notes":["「忌邪」：原文是「妒忌」，意思是「不容許有對立的神明」。"]},{"n":15,"t":"你不可與那地的居民立約，因為他們隨從自己的神明行淫；祭他們神明的時候，有人邀請你參加，你就會吃他的祭物。","notes":[]},{"n":16,"t":"你為你兒子娶他們的女兒為妻，他們的女兒因著隨從她們的神明行淫，就引誘你的兒子也隨從她們的神明行淫。","notes":[]},{"n":17,"t":"「不可為自己鑄造神像。","notes":[]},{"n":18,"t":"「你要守除酵節，照我所吩咐你的，在亞筆月內所定的日期吃無酵餅七天，因為你是在亞筆月內出了埃及。","notes":[]},{"n":19,"t":"「凡頭生的都是我的；無論是牛是羊，一切頭生的公的牲畜都要分別出來。","notes":["「一切頭生...分別出來」或譯「一切頭生的牲畜都要被記念」。"]},{"n":20,"t":"頭生的驢可以用羔羊代贖。若不贖牠，就要打斷牠的頸項。凡頭生的兒子都要贖出來。沒有人可以空手來朝見我。","notes":[]},{"n":21,"t":"「六日你要做工，第七日要安息，即使在耕種或收割的時候也要安息。","notes":[]},{"n":22,"t":"在收割初熟麥子的時候要守七七節，又要在年底守收藏節。","notes":[]},{"n":23,"t":"你所有的男丁要一年三次朝見主耶和華－以色列的神。","notes":[]},{"n":24,"t":"我要從你面前趕走列國，擴張你的疆界。你一年三次上去朝見耶和華－你神的時候，必沒有人貪圖你的地。","notes":[]},{"n":25,"t":"「不可將我祭牲的血和有酵之物一同獻上。逾越節的祭牲也不可留到早晨。","notes":[]},{"n":26,"t":"土地裏上好的初熟之物要奉到耶和華－你神的殿。不可用母山羊的奶來煮牠的小山羊。」","notes":[]},{"n":27,"t":"耶和華對摩西說：「你要將這些話寫上，因為我按這話與你和以色列人立約。」","notes":[]},{"n":28,"t":"摩西在耶和華那裏四十晝夜，不吃飯不喝水。他把這約的話，那十條誡命，寫在版上。","notes":["「十條誡命」：原文是「十句話」。"]},{"n":29,"t":"摩西下西奈山。摩西從山上下來的時候，手裏拿著兩塊法版。摩西不知道自己臉上的皮膚因耶和華和他說話而發光。","notes":[],"heads":["摩西下西奈山"]},{"n":30,"t":"亞倫和以色列眾人看見摩西，看哪，他臉上的皮膚發光，他們就怕靠近他。","notes":[]},{"n":31,"t":"摩西叫他們來，亞倫和會眾的官長回到他那裏，摩西就跟他們說話。","notes":[]},{"n":32,"t":"隨後以色列眾人都近前來，他就把耶和華在西奈山與他所說的一切話都吩咐他們。","notes":[]},{"n":33,"t":"摩西跟他們說完了話，就用面紗蒙上臉。","notes":[]},{"n":34,"t":"但摩西進到耶和華面前與他說話的時候，就把面紗揭下，直到出來。摩西出來，將所吩咐他的話告訴以色列人。","notes":[]},{"n":35,"t":"以色列人看見摩西的臉，他臉上的皮膚發光。摩西就用面紗蒙上臉，直到他進去與耶和華說話才揭下。","notes":[]}]},"35":{"heading":"安息日的條例","verses":[{"n":1,"t":"摩西召集以色列全會眾，對他們說：「這是耶和華吩咐你們遵行的事：","notes":[]},{"n":2,"t":"六日要做工，第七日你們要奉為向耶和華守完全安息的安息聖日。凡在這日做工的，要被處死。","notes":[]},{"n":3,"t":"在安息日這一天，不可在你們一切的住處生火。」","notes":[]},{"n":4,"t":"摩西對以色列全會眾說：「這是耶和華所吩咐的話，說：","notes":[],"heads":["為會幕奉獻"]},{"n":5,"t":"要從你們當中拿禮物獻給耶和華；凡甘心樂意的，可以把耶和華的禮物拿來，就是金、銀、銅，","notes":[]},{"n":6,"t":"藍色、紫色、朱紅色紗，細麻，山羊毛，","notes":[]},{"n":7,"t":"染紅的公羊皮，精美的皮料，金合歡木，","notes":[]},{"n":8,"t":"點燈的油，做膏油的香料、做香的香料，","notes":[]},{"n":9,"t":"紅瑪瑙與寶石，可以鑲嵌在以弗得和胸袋上。」","notes":[]},{"n":10,"t":"「你們當中凡心裏有智慧的都要來，製造一切耶和華所吩咐的，","notes":[],"heads":["會幕的器具"]},{"n":11,"t":"就是帳幕、帳幕的罩棚、帳幕的蓋、鉤子、豎板、橫木、柱子和帶卯眼的座，","notes":[]},{"n":12,"t":"櫃子、櫃子的槓、櫃蓋和遮掩的幔子，","notes":[]},{"n":13,"t":"供桌、供桌的槓、供桌一切的器具和供餅，","notes":[]},{"n":14,"t":"燈臺、燈臺的器具、燈和點燈的油，","notes":[]},{"n":15,"t":"香壇、壇的槓、膏油和芬芳的香，帳幕門口的門簾，","notes":[]},{"n":16,"t":"燔祭壇、壇的銅網、壇的槓和壇的一切器具，洗濯盆和盆座，","notes":[]},{"n":17,"t":"院子的帷幔、柱子、帶卯眼的座和院子的門簾，","notes":[]},{"n":18,"t":"帳幕的橛子、院子的橛子和繩子，","notes":[]},{"n":19,"t":"以及聖所事奉用的精緻禮服，亞倫祭司的聖衣和他兒子的衣服，供祭司職分用。」","notes":[]},{"n":20,"t":"以色列全會眾從摩西的面前出去。","notes":[],"heads":["百姓奉獻禮物"]},{"n":21,"t":"凡心受感動，靈被驅策的，都帶耶和華的禮物來，為要造會幕和其中一切的器具，以及縫製聖衣。","notes":[]},{"n":22,"t":"凡甘心樂意的，連男帶女都來了，各將金器，就是胸針、耳環、打印的戒指，和項鏈帶來，搖著金器的搖祭獻給耶和華。","notes":[]},{"n":23,"t":"凡有藍色、紫色、朱紅色紗、細麻、山羊毛、染紅的公羊皮、精美皮料的，都拿了來；","notes":[]},{"n":24,"t":"凡願意獻銀和銅作禮物的，都拿禮物來獻給耶和華；凡有金合歡木可做各種用途的也都拿了來。","notes":[]},{"n":25,"t":"凡心中有智慧，可以親手紡織的婦女，也把所紡的藍色、紫色、朱紅色紗，和細麻都拿了來。","notes":[]},{"n":26,"t":"凡有智慧，心裏受感動的婦女都來紡山羊毛。","notes":[]},{"n":27,"t":"眾官長把紅瑪瑙和寶石，可以鑲嵌在以弗得與胸袋上的，都拿了來，","notes":[]},{"n":28,"t":"又拿做香，做膏油，和點燈所需的香料和油來。","notes":[]},{"n":29,"t":"以色列人，無論男女，凡心裏受感動的，都帶甘心祭來獻給耶和華，為要做耶和華藉摩西所吩咐的一切工。","notes":[]},{"n":30,"t":"摩西對以色列人說：「看，猶大支派中戶珥的孫子，烏利的兒子比撒列，耶和華已經題名召他，","notes":[],"heads":["造會幕的技工"]},{"n":31,"t":"又以神的靈充滿他，使他有智慧、聰明、知識，能做各樣的工，","notes":[]},{"n":32,"t":"能設計圖案，用金、銀、銅製造各物，","notes":[]},{"n":33,"t":"又能雕刻鑲嵌用的寶石，雕刻木頭，做各樣精巧的工。","notes":[]},{"n":34,"t":"耶和華又賜給他和但支派中，亞希撒抹的兒子亞何利亞伯能教導人的心。","notes":[]},{"n":35,"t":"耶和華使他們的心滿有智慧，能做各樣的工，無論是雕刻的工，圖案設計的工，用藍色、紫色、朱紅色紗，和細麻作刺繡的工，以及編織的工，他們都能勝任，也能設計圖案。」","notes":[]}]},"36":{"heading":"百姓的奉獻","verses":[{"n":1,"t":"比撒列和亞何利亞伯，以及一切心裏有智慧，蒙耶和華賜智慧和聰明，懂得做聖所各樣用途之工的人，都照耶和華所吩咐的去做。","notes":[]},{"n":2,"t":"摩西把比撒列和亞何利亞伯，以及那些蒙耶和華賜他心裏有智慧，心受感動願意前來做工的人都召來。","notes":[]},{"n":3,"t":"這些人就從摩西收了以色列人為建造聖所，以及聖所各用途之工而奉獻的禮物。每天早晨，百姓繼續把甘心祭拿來。","notes":[]},{"n":4,"t":"凡有智慧能做聖所一切工的人，都各自離開他們原本的工作前來，","notes":[]},{"n":5,"t":"對摩西說：「百姓送來的禮物很多，已經超過耶和華吩咐建造之工所需要的了。」","notes":[]},{"n":6,"t":"摩西吩咐，他們就在營中傳令說：「無論男女，不必再為聖所的禮物做任何的工。」這樣才使百姓停止，不再拿禮物來，","notes":[]},{"n":7,"t":"他們所有的材料已經足夠整個工程之用，而且有餘。","notes":[]},{"n":8,"t":"做工的人當中，凡心裏有智慧的，用十幅幔子做帳幕，幔子是用搓的細麻和藍色、紫色、朱紅色紗織成的，並且以刺繡的手藝繡上基路伯。","notes":[],"heads":["造帳幕"]},{"n":9,"t":"每幅幔子長二十八肘，每幅幔子寬四肘，全部的幔子都是一樣的尺寸。","notes":[]},{"n":10,"t":"他使這五幅幔子彼此相連，又使那五幅幔子彼此相連。","notes":[]},{"n":11,"t":"他在這一組相連幔子的末幅邊上縫了藍色的鈕環；在另一組相連幔子的末幅邊上也照樣做。","notes":[]},{"n":12,"t":"他在這幅幔子上縫五十個鈕環，在另一組相連幔子的末幅上也縫五十個鈕環，環環相對。","notes":[]},{"n":13,"t":"他又做了五十個金鉤，用鉤子使幔子彼此相連，成為一個帳幕。","notes":[]},{"n":14,"t":"他用山羊毛織十一幅幔子，作為帳幕上的罩棚。","notes":[]},{"n":15,"t":"每幅幔子長三十肘，每幅幔子寬四肘；十一幅幔子都是一樣的尺寸。","notes":[]},{"n":16,"t":"他把五幅幔子連成一幅，又把六幅幔子連成一幅。","notes":[]},{"n":17,"t":"他在這一組相連幔子的末幅邊上縫了五十個鈕環；在另一組相連幔子的末幅邊上也縫了五十個鈕環。","notes":[]},{"n":18,"t":"他又做五十個銅鉤，使罩棚相連成為一個。","notes":[]},{"n":19,"t":"他用染紅的公羊皮做罩棚的蓋，再用精美皮料做外層的蓋。","notes":[]},{"n":20,"t":"他用金合歡木做豎立帳幕的木板，","notes":[]},{"n":21,"t":"木板長十肘，每塊板寬一肘半，","notes":[]},{"n":22,"t":"每塊板有兩個榫頭可以彼此銜接。帳幕一切的板都是這樣做。","notes":[]},{"n":23,"t":"他做帳幕的木板：南面，就是面向南方的那一邊，做二十塊板，","notes":[]},{"n":24,"t":"在這二十塊板底下做了四十個帶卯眼的銀座：兩個卯眼接連這塊板上的兩個榫頭，另外兩個卯眼接連那塊板上的兩個榫頭。","notes":[]},{"n":25,"t":"他在帳幕的第二邊，就是北面，也做二十塊板，","notes":[]},{"n":26,"t":"和四十個帶卯眼的銀座；這塊板底下有兩個卯眼，那塊板底下也有兩個卯眼。","notes":[]},{"n":27,"t":"他在帳幕的後面，就是西面，做六塊板，","notes":[]},{"n":28,"t":"在帳幕後面的角落做兩塊板。","notes":[]},{"n":29,"t":"下端的板是成雙的，上端連在一起，直到頂端的第一個環子；兩塊板都是這樣，做成兩個角落。","notes":[]},{"n":30,"t":"一共有八塊板和十六個帶卯眼的銀座，每塊板底下有兩個卯眼。","notes":[]},{"n":31,"t":"他用金合歡木做橫木：為帳幕這面的板做五根橫木，","notes":[]},{"n":32,"t":"為帳幕那面的板做五根橫木，又為帳幕後面，就是朝西的板做五根橫木，","notes":[]},{"n":33,"t":"他做了板腰間的橫木，從一頭通到另一頭。","notes":[]},{"n":34,"t":"他將板包上金子，又做板上的金環來套橫木；橫木也包上金子。","notes":[]},{"n":35,"t":"他用藍色、紫色、朱紅色紗，和搓的細麻織幔子，以刺繡的手藝繡上基路伯。","notes":[]},{"n":36,"t":"他又用金合歡木為幔子做四根柱子，包上金子，柱子有金鉤，又為柱子鑄了四個帶卯眼的銀座。","notes":[]},{"n":37,"t":"他用藍色、紫色、朱紅色紗，和搓的細麻，以刺繡的手藝為帳幕織門簾，","notes":[]},{"n":38,"t":"又為簾子做五根柱子和柱子的鉤子，把柱頂和柱子的箍包上金子。柱子有五個帶卯眼的銅座。","notes":[]}]},"37":{"heading":"造約櫃","verses":[{"n":1,"t":"比撒列用金合歡木做一個櫃子，長二肘半，寬一肘半，高一肘半。","notes":[]},{"n":2,"t":"裏裏外外包上純金，四圍鑲上金邊。","notes":[]},{"n":3,"t":"他又鑄了四個金環，安在櫃子的四腳上；這邊兩個環，那邊兩個環。","notes":[]},{"n":4,"t":"他用金合歡木做了兩根槓，包上金子，","notes":[]},{"n":5,"t":"又把槓穿過櫃旁的環，以便抬櫃。","notes":[]},{"n":6,"t":"他用純金做了一個櫃蓋，長二肘半，寬一肘半，","notes":[]},{"n":7,"t":"他造兩個用金子錘出的基路伯，從櫃蓋的兩端錘出它們。","notes":[]},{"n":8,"t":"這端一個基路伯，那端一個基路伯；從櫃蓋的兩端錘出兩個基路伯。","notes":[]},{"n":9,"t":"二基路伯的翅膀向上張開，用翅膀遮住櫃蓋，臉彼此相對；基路伯的臉朝向櫃蓋。","notes":[]},{"n":10,"t":"他用金合歡木做了一張供桌，長二肘，寬一肘，高一肘半，","notes":[],"heads":["造供桌"]},{"n":11,"t":"把它包上純金，四圍鑲上金邊。","notes":[]},{"n":12,"t":"供桌的四圍各做了一掌寬的邊緣，邊緣鑲上金邊。","notes":[]},{"n":13,"t":"他又鑄了四個金環，把環安在四個桌腳的四角上。","notes":[]},{"n":14,"t":"環靠近邊緣，以便穿槓抬供桌。","notes":[]},{"n":15,"t":"他用金合歡木做了兩根槓，包上金子，用來抬供桌。","notes":[]},{"n":16,"t":"他又用純金做了桌上的器具，就是盤、碟，以及澆酒祭的杯和壺。","notes":[]},{"n":17,"t":"他造一座用純金錘出的燈臺；燈臺的座、幹、杯、花萼和花瓣，都和燈臺接連一塊。","notes":[],"heads":["造燈臺"]},{"n":18,"t":"燈臺兩旁伸出六根枝子：這邊三根，那邊三根。","notes":[]},{"n":19,"t":"這邊的枝子上有三個杯，形狀像杏花，有花萼有花瓣；那邊的枝子上也有三個杯，形狀像杏花，有花萼有花瓣。從燈臺伸出來的六根枝子都是如此。","notes":[]},{"n":20,"t":"燈臺本身有四個杯，形狀像杏花，有花萼有花瓣。","notes":[]},{"n":21,"t":"燈臺的第一對枝子下面有花萼，燈臺的第二對枝子下面有花萼，燈臺的第三對枝子下面也有花萼；燈臺伸出的六根枝子都是如此。","notes":[]},{"n":22,"t":"花萼和枝子都和燈臺接連一塊，全是從一塊純金錘出來的。","notes":[]},{"n":23,"t":"他用純金做燈臺的七盞燈，以及燈剪和燈盤。","notes":[]},{"n":24,"t":"他用一他連得的純金做燈臺和燈臺的一切器具。","notes":[]},{"n":25,"t":"他用金合歡木做香壇，長一肘，寬一肘，這壇是正方形的，高二肘。壇的四個翹角與壇接連一塊。","notes":[],"heads":["造香壇"]},{"n":26,"t":"他把壇的上面與壇的四圍，以及壇的四個翹角包上純金，又在壇的四圍鑲上金邊。","notes":[]},{"n":27,"t":"他在壇的兩個對側，金邊下面做了兩個金環，用來穿槓抬壇。","notes":[]},{"n":28,"t":"他又用金合歡木做槓，包上金子。","notes":[]},{"n":29,"t":"他按配製香料的方法製成聖膏油和芬芳的純香。","notes":[],"heads":["造聖膏油和香"]}]},"38":{"heading":"造燔祭壇","verses":[{"n":1,"t":"他用金合歡木做燔祭壇，長五肘，寬五肘，是正方形的，高三肘。","notes":[]},{"n":2,"t":"在壇的四角做四個翹角，與壇接連一塊，把壇包上銅。","notes":[]},{"n":3,"t":"他做壇的一切器具，就是桶子、鏟子、盤子、肉叉和火盆；這一切器具都是用銅做的。","notes":[]},{"n":4,"t":"他又為壇做一個銅網，安在壇四圍的邊的下面，垂到壇的半腰。","notes":[]},{"n":5,"t":"他在銅網的四角上鑄了四個環，用來穿槓。","notes":[]},{"n":6,"t":"他用金合歡木做槓，包上銅，","notes":[]},{"n":7,"t":"把槓穿過壇兩旁的環子，用來抬壇。他用板做壇，壇的中心是空的。","notes":[]},{"n":8,"t":"他用銅做洗濯盆和盆座，是用會幕門前事奉之婦人的銅鏡做的。","notes":[],"heads":["造洗濯盆"]},{"n":9,"t":"他又做院子，在南面，就是面向南方的那一邊，用搓的細麻做院子的帷幔，一百肘。","notes":[],"heads":["造院子"]},{"n":10,"t":"帷幔有二十根柱子，二十個帶卯眼的銅座；柱子的鉤和箍都是銀的。","notes":[]},{"n":11,"t":"北面的帷幔一百肘。帷幔有二十根柱子，二十個帶卯眼的銅座；柱子的鉤和箍都是銀的。","notes":[]},{"n":12,"t":"西面的帷幔五十肘。帷幔有十根柱子，十個帶卯眼的座；柱子的鉤和箍都是銀的。","notes":[]},{"n":13,"t":"院子的東面，就是面向東方的那一邊，五十肘。","notes":[]},{"n":14,"t":"一邊的帷幔有十五肘，有三根柱子，三個帶卯眼的座。","notes":[]},{"n":15,"t":"另一邊也一樣，院子門口左右的帷幔也有十五肘，有三根柱子，三個帶卯眼的座。","notes":[]},{"n":16,"t":"院子四面的帷幔都是用搓的細麻做的。","notes":[]},{"n":17,"t":"柱子帶卯眼的座是銅的，柱子的鉤和箍是銀的，柱頂是用銀包的。院子一切的柱子都是用銀子箍著的。","notes":[]},{"n":18,"t":"院子的門簾是以刺繡的手藝，用藍色、紫色、朱紅色紗，和搓的細麻織的，長二十肘，寬也就是高五肘，與院子帷幔的高度相同。","notes":[]},{"n":19,"t":"門簾有四根柱子，四個帶卯眼的銅座；柱子上的鉤和箍是銀的，柱頂是用銀包的。","notes":[]},{"n":20,"t":"帳幕一切的橛子和院子四圍的橛子都是銅的。","notes":[]},{"n":21,"t":"這是帳幕，就是法櫃帳幕中物件的總數，是照摩西的吩咐，亞倫祭司的兒子以他瑪經手，利未人數點的。","notes":[],"heads":["造會幕所用的金屬"]},{"n":22,"t":"凡耶和華吩咐摩西的，都是由猶大支派中戶珥的孫子，烏利的兒子比撒列去做的；","notes":[]},{"n":23,"t":"與他同工的有但支派中亞希撒抹的兒子亞何利亞伯；他是雕刻師，也是設計師，又是用藍色、紫色、朱紅色紗，和細麻的刺繡師。","notes":[]},{"n":24,"t":"為聖所一切工作用的金子，就是所奉獻的金子，按聖所的舍客勒，一共是二十九他連得，七百三十舍客勒。","notes":[]},{"n":25,"t":"會中被數的人所獻的銀子，按聖所的舍客勒，一共是一百他連得，一千七百七十五舍客勒。","notes":[]},{"n":26,"t":"凡曾被數的，就是二十歲以上的人，共有六十萬零三千五百五十人。按聖所的舍客勒，每人半舍客勒，就是一比加。","notes":[]},{"n":27,"t":"一百他連得銀子是用來鑄造聖所帶卯眼的座和幔子下帶卯眼的座；用一百他連得鑄造一百個帶卯眼的座，每個帶卯眼的座一他連得。","notes":[]},{"n":28,"t":"一千七百七十五舍客勒是用來鑄造柱子的鉤，包柱頂，以及箍著柱子。","notes":[]},{"n":29,"t":"所奉獻的銅共有七十他連得，二千四百舍客勒。","notes":[]},{"n":30,"t":"這些銅是用來做會幕門口帶卯眼的座，銅壇、壇的銅網和壇的一切器具，","notes":[]},{"n":31,"t":"院子四圍帶卯眼的座和院子門口帶卯眼的座，以及帳幕一切的橛子和院子四圍所有的橛子。","notes":[]}]},"39":{"heading":"為祭司製聖服","verses":[{"n":1,"t":"他們用藍色、紫色、朱紅色紗縫製精緻的禮服，在聖所用以供職；他們為亞倫做聖衣，是照耶和華所吩咐摩西的。","notes":[]},{"n":2,"t":"以弗得是用金色、藍色、紫色、朱紅色紗，和搓的細麻做的。","notes":[]},{"n":3,"t":"他們把金子錘成薄片，剪成細線，與藍色、紫色、朱紅色紗，以刺繡的手藝織在一起。","notes":[]},{"n":4,"t":"他們又為以弗得做兩條相連的肩帶，接連在以弗得的兩端。","notes":[]},{"n":5,"t":"以弗得的精緻帶子以一樣的手藝，用金色、藍色、紫色、朱紅色紗，和搓的細麻縫製，與以弗得接連在一起，是照耶和華所吩咐摩西的。","notes":[]},{"n":6,"t":"他們琢出兩塊紅瑪瑙，鑲在金槽裏，如同刻印章，刻上以色列眾子的名字。","notes":[]},{"n":7,"t":"他把這兩塊寶石安在以弗得的兩條肩帶上，為以色列人作紀念石，是照耶和華所吩咐摩西的。","notes":[]},{"n":8,"t":"胸袋是以刺繡的手藝，如同以弗得的做法，用金色、藍色、紫色、朱紅色紗，和搓的細麻縫製。","notes":[]},{"n":9,"t":"胸袋是正方形的，他們把它做成兩層，這兩層各長一虎口，寬一虎口。","notes":[]},{"n":10,"t":"他們在上面鑲四行寶石：第一行是紅寶石、紅璧璽、紅玉；","notes":[]},{"n":11,"t":"第二行是綠寶石、藍寶石、金剛石；","notes":[]},{"n":12,"t":"第三行是紫瑪瑙、白瑪瑙、紫晶；","notes":[]},{"n":13,"t":"第四行是水蒼玉、紅瑪瑙、碧玉。這些都鑲在金槽中。","notes":[]},{"n":14,"t":"這些寶石有以色列十二個兒子的名字，如同刻印章，每一顆有自己的名字，代表十二個支派。","notes":[]},{"n":15,"t":"他們在胸袋上用純金打鏈子，像編成的繩子一樣。","notes":[]},{"n":16,"t":"他們又做了兩個金槽和兩個金環，把這兩個環安在胸袋的兩端。","notes":[]},{"n":17,"t":"他們把那兩條編成的金鏈繫在胸袋兩端的兩個環上，","notes":[]},{"n":18,"t":"又把鏈子的另外兩端扣在兩個槽上，安在以弗得前面的肩帶上。","notes":[]},{"n":19,"t":"他們做了兩個金環，安在胸袋的兩端，在以弗得裏面的邊上，","notes":[]},{"n":20,"t":"又做兩個金環，安在以弗得前面兩條肩帶的下邊，靠近接縫處，在精緻帶子的上面。","notes":[]},{"n":21,"t":"他們用藍色的帶子把胸袋的環與以弗得的環繫住，使胸袋綁在以弗得精緻的帶子上，不致鬆脫，是照耶和華所吩咐摩西的。","notes":[]},{"n":22,"t":"以弗得的外袍是以編織的手藝做的，顏色全是藍的。","notes":[]},{"n":23,"t":"袍上方的中間留了一個領口，領口的周圍織出領邊，好像鎧甲的領口，免得破裂。","notes":[]},{"n":24,"t":"他們在袍子下襬用藍色、紫色、朱紅色紗，和搓的細麻做石榴，","notes":["原文沒有「細麻」。"]},{"n":25,"t":"又用純金鑄了鈴鐺，把鈴鐺釘在石榴中間，袍子下襬周圍的石榴中間：","notes":[]},{"n":26,"t":"一個鈴鐺一個石榴，一個鈴鐺一個石榴，在袍子下襬的周圍，用以供職，是照耶和華所吩咐摩西的。","notes":[]},{"n":27,"t":"他們用編織的工為亞倫和他的兒子做細麻布內袍、","notes":[]},{"n":28,"t":"細麻布禮冠、細麻布精緻頭巾，和搓的細麻布褲子，","notes":[]},{"n":29,"t":"又用藍色、紫色、朱紅色紗，和搓的細麻，以刺繡的手藝做腰帶，是照耶和華所吩咐摩西的。","notes":[]},{"n":30,"t":"他們用純金做一面聖冠上的牌，如同刻印章，在上面寫著「歸耶和華為聖」，","notes":[]},{"n":31,"t":"又用藍色的帶子把牌繫在禮冠上，是照耶和華所吩咐摩西的。","notes":[]},{"n":32,"t":"會幕的帳幕一切的工程就這樣做完了。凡耶和華所吩咐摩西的，以色列人都照樣做了。","notes":[],"heads":["會幕完工"]},{"n":33,"t":"他們把帳幕運到摩西那裏，帳幕和帳幕的一切器具，就是鉤、板、橫木、柱子、帶卯眼的座，","notes":[]},{"n":34,"t":"染紅公羊皮的蓋、精美皮料的蓋、遮掩的幔子，","notes":[]},{"n":35,"t":"法櫃、櫃的槓、櫃蓋，","notes":[]},{"n":36,"t":"供桌、供桌的一切器具、供餅，","notes":[]},{"n":37,"t":"純金的燈臺、擺列的燈、燈臺的一切器具、點燈的油，","notes":[]},{"n":38,"t":"金壇、膏油、芬芳的香、帳幕的門簾，","notes":[]},{"n":39,"t":"銅壇、壇的銅網、壇的槓、壇的一切器具，洗濯盆和盆座，","notes":[]},{"n":40,"t":"院子的帷幔、柱子、帶卯眼的座、院子的門簾、繩子、橛子，帳幕，就是會幕使用的一切器具，","notes":[]},{"n":41,"t":"以及聖所事奉用的精緻禮服，亞倫祭司的聖衣和他兒子的衣服，供祭司職分用。","notes":[]},{"n":42,"t":"這一切工作都是以色列人照耶和華所吩咐摩西做的。","notes":[]},{"n":43,"t":"摩西看見這一切的工，看哪，耶和華怎樣吩咐，他們就照樣做了，摩西就為他們祝福。","notes":[]}]},"40":{"heading":"耶和華會幕的建立和奉獻","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「正月初一，你要立起會幕的帳幕，","notes":[]},{"n":3,"t":"把法櫃安放在裏面，用幔子將櫃遮掩。","notes":[]},{"n":4,"t":"把供桌搬進去，擺設桌上的器具。又把燈臺搬進去，點上燈。","notes":[]},{"n":5,"t":"把金香壇安在法櫃前，掛上帳幕的門簾。","notes":[]},{"n":6,"t":"把燔祭壇安在會幕的帳幕門前。","notes":[]},{"n":7,"t":"把洗濯盆安在會幕和壇的中間，在盆裏盛水。","notes":[]},{"n":8,"t":"又要在院子周圍支起帷幔，把院子的門簾掛上。","notes":[]},{"n":9,"t":"你要用膏油抹帳幕和其中所有的，使帳幕和一切器具分別為聖，就都成為聖。","notes":[]},{"n":10,"t":"又要抹燔祭壇和壇的一切器具，使壇分別為聖，壇就成為至聖。","notes":[]},{"n":11,"t":"要抹洗濯盆和盆座，使盆分別為聖。","notes":[]},{"n":12,"t":"你要帶亞倫和他兒子到會幕門口，用水洗身。","notes":[]},{"n":13,"t":"要給亞倫穿上聖衣，又膏他，使他分別為聖，作事奉我的祭司。","notes":[]},{"n":14,"t":"又要帶他的兒子來，給他們穿上內袍。","notes":[]},{"n":15,"t":"你怎樣膏他們的父親，也要照樣膏他們，使他們成為事奉我的祭司。他們受了膏，就必世世代代永遠得祭司的職分。」","notes":[]},{"n":16,"t":"摩西這樣做了；耶和華怎樣吩咐摩西，他就照樣做了。","notes":[]},{"n":17,"t":"第二年正月初一，帳幕就立起來。","notes":[]},{"n":18,"t":"摩西支起帳幕，安上帶卯眼的座，安上板，穿上橫木，立起柱子。","notes":[]},{"n":19,"t":"他在帳幕的上面搭上罩棚，把罩棚外層的蓋子蓋在其上，是照著耶和華所吩咐他的。","notes":[]},{"n":20,"t":"他把法版放在櫃裏，把槓穿在櫃的兩旁，把櫃蓋安在櫃上。","notes":[]},{"n":21,"t":"把櫃抬進帳幕，掛上遮掩櫃的幔子，把法櫃遮蓋了，是照耶和華所吩咐摩西的。","notes":[]},{"n":22,"t":"他把供桌安在會幕內，在帳幕的北邊，幔子的外面。","notes":[]},{"n":23,"t":"把餅擺設在供桌上，在耶和華面前，是照耶和華所吩咐摩西的。","notes":[]},{"n":24,"t":"他把燈臺安在會幕內，在帳幕的南邊，供桌的對面，","notes":[]},{"n":25,"t":"並在耶和華面前點燈，是照耶和華所吩咐摩西的。","notes":[]},{"n":26,"t":"他把金壇安在會幕內，幔子的前面，","notes":[]},{"n":27,"t":"又在壇上燒芬芳的香，是照耶和華所吩咐摩西的。","notes":[]},{"n":28,"t":"他又掛上帳幕的門簾。","notes":[]},{"n":29,"t":"在會幕的帳幕門口安設燔祭壇，把燔祭和素祭獻在壇上，是照耶和華所吩咐摩西的。","notes":[]},{"n":30,"t":"他又把洗濯盆安在會幕和祭壇的中間，盆裏盛水，以便洗濯。","notes":[]},{"n":31,"t":"摩西和亞倫，以及亞倫的兒子用這盆洗手洗腳。","notes":[]},{"n":32,"t":"他們進會幕或走近壇的時候，就都洗濯，是照耶和華所吩咐摩西的。","notes":[]},{"n":33,"t":"他在帳幕和祭壇的四圍支起院子的帷幔，把院子的門簾掛上。這樣，摩西就做完了工。","notes":[]},{"n":34,"t":"那時，雲彩遮蓋會幕，耶和華的榮光充滿了帳幕。","notes":[],"heads":["雲彩和榮光"]},{"n":35,"t":"摩西不能進會幕，因為雲彩停在其上，耶和華的榮光充滿了帳幕。","notes":[]},{"n":36,"t":"每逢雲彩從帳幕升上去，以色列人就起程前行；","notes":[]},{"n":37,"t":"雲彩若不升上去，他們就不起程，直等到雲彩升上去。","notes":[]},{"n":38,"t":"在他們所行的路上，在以色列全家的眼前，白天，耶和華的雲彩在帳幕上，黑夜，有火在雲彩中。","notes":[]}]}},"LEV":{"1":{"heading":"燔祭的條例","verses":[{"n":1,"t":"耶和華從會幕中呼叫摩西，吩咐他說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人，對他們說：你們中間若有人要獻供物給耶和華，可以從牛群羊群中獻牲畜為供物。","notes":[]},{"n":3,"t":"「他的供物若以牛為燔祭，要獻一頭沒有殘疾的公牛，獻在會幕的門口，他就可以在耶和華面前蒙悅納。","notes":[]},{"n":4,"t":"他要按手在燔祭牲的頭上，為自己贖罪，就蒙悅納。","notes":[]},{"n":5,"t":"他要在耶和華面前宰公牛犢；亞倫子孫作祭司的要獻上血，把血灑在會幕門口壇的周圍。","notes":[]},{"n":6,"t":"他要剝去燔祭牲的皮，把燔祭牲切成塊。","notes":[]},{"n":7,"t":"亞倫祭司的子孫要在壇上生火，把柴擺在火上。","notes":[]},{"n":8,"t":"亞倫子孫作祭司的要把肉塊連頭和脂肪，擺在壇上燒著火的柴上。","notes":[]},{"n":9,"t":"燔祭牲的內臟與小腿要用水洗淨，祭司要把整隻全燒在壇上，當作燔祭，是獻給耶和華為馨香的火祭。","notes":[]},{"n":10,"t":"「人的供物若以綿羊或山羊為燔祭，要獻一隻沒有殘疾的公羊。","notes":[]},{"n":11,"t":"他要在壇的北邊，在耶和華面前宰羊；亞倫子孫作祭司的要把血灑在壇的周圍。","notes":[]},{"n":12,"t":"他要把燔祭牲切成塊，祭司就要把肉塊連頭和脂肪，擺在壇上燒著火的柴上。","notes":[]},{"n":13,"t":"內臟與小腿要用水洗淨，祭司要把整隻獻上，全燒在壇上。這是燔祭，是獻給耶和華為馨香的火祭。","notes":[]},{"n":14,"t":"「人獻給耶和華的供物若以鳥為燔祭，就要獻斑鳩或雛鴿為他的供物。","notes":[]},{"n":15,"t":"祭司要把鳥拿到壇前，扭斷牠的頭，把鳥燒在壇上，鳥的血要流在壇的旁邊；","notes":[]},{"n":16,"t":"又要把鳥的嗉囊和裏面的髒物除掉，丟在壇東邊倒灰的地方。","notes":["「髒物」或譯「羽毛」。"]},{"n":17,"t":"他要拿著鳥的兩個翅膀，把鳥撕開，卻不可撕斷；祭司要把牠擺在壇上燒著火的柴上焚燒。這是燔祭，是獻給耶和華為馨香的火祭。」","notes":[]}]},"2":{"heading":"素祭的條例","verses":[{"n":1,"t":"「若有人獻素祭為供物給耶和華，就要獻細麵為供物，把油澆在上面，加上乳香，","notes":[]},{"n":2,"t":"帶到亞倫子孫作祭司的那裏。祭司要從細麵中取出滿滿的一把，又取些油和所有的乳香，把這些作為紀念的燒在壇上，是獻給耶和華為馨香的火祭。","notes":[]},{"n":3,"t":"素祭所剩的要歸給亞倫和他的子孫；在獻給耶和華的火祭中，這是至聖的。","notes":[]},{"n":4,"t":"「若獻爐中烤的素祭為供物，要用調了油的無酵細麵餅，或抹了油的無酵薄餅。","notes":[]},{"n":5,"t":"若以鐵盤上的素祭為供物，就要用調了油的無酵細麵，","notes":[]},{"n":6,"t":"分成小塊，澆上油；這是素祭。","notes":[]},{"n":7,"t":"若以煎鍋煎的素祭為供物，就要用油與細麵做成。","notes":[]},{"n":8,"t":"要把這樣做成的素祭帶到耶和華面前，拿給祭司，祭司要帶到壇前。","notes":[]},{"n":9,"t":"祭司要從素祭中取出作為紀念的燒在壇上，是獻給耶和華為馨香的火祭。","notes":[]},{"n":10,"t":"素祭所剩的要歸給亞倫和他的子孫；在獻給耶和華的火祭中，這是至聖的。","notes":[]},{"n":11,"t":"「凡獻給耶和華的素祭都不可以有酵，因為你們不可把任何的酵或蜜燒了，當作火祭獻給耶和華。","notes":[]},{"n":12,"t":"你們可以把這些獻給耶和華當作初熟的供物，但是不可獻在壇上作為馨香的祭。","notes":[]},{"n":13,"t":"凡獻為素祭的供物都要用鹽調和；在素祭中，不可缺少你與神立約的鹽。一切的供物都要加鹽獻上。","notes":[]},{"n":14,"t":"「你若獻初熟之物給耶和華為素祭，就要獻在火中烘過的新麥穗，就是磨碎的新穀物，當作初熟之物的素祭。","notes":[]},{"n":15,"t":"你要加上油和乳香；這是素祭。","notes":[]},{"n":16,"t":"祭司要把供物中作為紀念的，就是一些磨碎的新穀物和一些油，以及所有的乳香，都焚燒，是獻給耶和華的火祭。」","notes":[]}]},"3":{"heading":"平安祭的條例","verses":[{"n":1,"t":"「人獻平安祭為供物，若是從牛群中獻，無論是公的母的，要用沒有殘疾的，獻在耶和華面前。","notes":[]},{"n":2,"t":"他要按手在供物的頭上，在會幕的門口宰了牠。亞倫子孫作祭司的，要把血灑在壇的周圍。","notes":[]},{"n":3,"t":"從平安祭中，他要把火祭獻給耶和華，就是包著內臟的脂肪和內臟上所有的脂肪，","notes":[]},{"n":4,"t":"兩個腎和腎上的脂肪，即靠近腎兩旁的脂肪，以及肝上的網油，連同腎一起取下。","notes":[]},{"n":5,"t":"亞倫的子孫要把這些擺在燒著火的柴上，燒在壇的燔祭上，是獻給耶和華為馨香的火祭。","notes":[]},{"n":6,"t":"「人向耶和華獻平安祭為供物，若是從羊群中獻，無論是公的母的，要用沒有殘疾的。","notes":[]},{"n":7,"t":"若他獻一隻綿羊為供物，就要把牠獻在耶和華面前。","notes":[]},{"n":8,"t":"要按手在供物的頭上，在會幕前宰了牠。亞倫的子孫要把血灑在壇的周圍。","notes":[]},{"n":9,"t":"從平安祭中，他要取脂肪當作火祭獻給耶和華，就是靠近脊骨處取下的整條肥尾巴，包著內臟的脂肪和內臟上所有的脂肪，","notes":[]},{"n":10,"t":"兩個腎和腎上的脂肪，即靠近腎兩旁的脂肪，以及肝上的網油，連同腎一起取下。","notes":[]},{"n":11,"t":"祭司要把這些燒在壇上，是獻給耶和華為食物的火祭。","notes":[]},{"n":12,"t":"「人的供物若是山羊，就要把牠獻在耶和華面前。","notes":[]},{"n":13,"t":"要按手在牠的頭上，在會幕前宰了牠。亞倫的子孫要把血灑在壇的周圍，","notes":[]},{"n":14,"t":"又要從供物中把火祭獻給耶和華，就是包著內臟的脂肪和內臟上所有的脂肪，","notes":[]},{"n":15,"t":"兩個腎和腎上的脂肪，即靠近腎兩旁的脂肪，以及肝上的網油，連同腎一起取下。","notes":[]},{"n":16,"t":"祭司要把這些燒在壇上，作為馨香火祭的食物；所有的脂肪都是耶和華的。","notes":[]},{"n":17,"t":"在你們一切的住處，脂肪和血都不可吃，這要成為你們世世代代永遠的定例。」","notes":[]}]},"4":{"heading":"贖罪祭的條例","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人說：若有人無意中犯罪，在任何事上犯了一條耶和華所吩咐的禁令，","notes":[]},{"n":3,"t":"或是受膏的祭司犯了罪，使百姓陷在罪裏，他就當為自己所犯的罪，把沒有殘疾的公牛犢獻給耶和華為贖罪祭。","notes":[]},{"n":4,"t":"他要把公牛牽到會幕的門口，在耶和華面前按手在牛的頭上，把牛宰於耶和華面前。","notes":[]},{"n":5,"t":"受膏的祭司要取些公牛的血，帶到會幕那裏。","notes":[]},{"n":6,"t":"祭司要把手指蘸在血中，在耶和華面前對著聖所的幔子彈血七次，","notes":[]},{"n":7,"t":"又要把一些血抹在會幕內，耶和華面前香壇的四個翹角上，再把公牛其餘的血全倒在會幕門口燔祭壇的底座上；","notes":[]},{"n":8,"t":"又要取出這頭贖罪祭公牛所有的脂肪，就是包著內臟的脂肪和內臟上所有的脂肪，","notes":[]},{"n":9,"t":"兩個腎和腎上的脂肪，即靠近腎兩旁的脂肪，以及肝上的網油，連同腎一起取下，","notes":[]},{"n":10,"t":"正如從平安祭的牛身上所取的，祭司要把這些燒在燔祭壇上。","notes":[]},{"n":11,"t":"但公牛的皮和所有的肉，以及頭、腿、內臟、糞，","notes":[]},{"n":12,"t":"就是全公牛，要搬到營外清潔的地方倒灰之處，放在柴上用火焚燒。","notes":[]},{"n":13,"t":"「以色列全會眾若犯了錯，在任何事上犯了一條耶和華所吩咐的禁令，而有了罪，會眾看不出這隱藏的事；","notes":[]},{"n":14,"t":"他們一知道犯了罪，就要獻一頭公牛犢為贖罪祭，牽牠到會幕前。","notes":[]},{"n":15,"t":"會眾的長老要在耶和華面前按手在公牛的頭上，把牛宰於耶和華面前。","notes":[]},{"n":16,"t":"受膏的祭司要取些公牛的血，帶到會幕那裏。","notes":[]},{"n":17,"t":"祭司要用手指蘸一些血，在耶和華面前對著幔子彈七次，","notes":[]},{"n":18,"t":"又要把一些血抹在會幕內，耶和華面前壇的四個翹角上，再把其餘的血全倒在會幕門口燔祭壇的底座上。","notes":[]},{"n":19,"t":"他要取出公牛所有的脂肪，燒在壇上。","notes":[]},{"n":20,"t":"他要處理這牛，正如處理那頭贖罪祭的公牛一樣，他要如此去做。祭司要為他們贖罪，他們就蒙赦免。","notes":[]},{"n":21,"t":"他要把牛搬到營外燒了，像燒前一頭公牛一樣；這是會眾的贖罪祭。","notes":[]},{"n":22,"t":"「官長若犯罪，在任何事上無意中犯了一條耶和華－他的神所吩咐的禁令，而有了罪，","notes":[]},{"n":23,"t":"他一知道自己犯了罪，就要牽一隻沒有殘疾的公山羊為供物。","notes":[]},{"n":24,"t":"他要按手在羊的頭上，在耶和華面前宰燔祭牲的地方把牠宰了；這是贖罪祭。","notes":[]},{"n":25,"t":"祭司要用手指蘸一些贖罪祭牲的血，抹在燔祭壇的四個翹角上，再把其餘的血倒在燔祭壇的底座上。","notes":[]},{"n":26,"t":"祭牲所有的脂肪都要燒在壇上，正如平安祭的脂肪一樣。祭司要為他的罪贖了他，他就蒙赦免。","notes":[]},{"n":27,"t":"「這地的百姓若有人無意中犯罪，在任何事上犯了一條耶和華所吩咐的禁令，而有了罪，","notes":[]},{"n":28,"t":"他一知道自己犯了罪，就要為所犯的罪牽一隻沒有殘疾的母山羊為供物。","notes":[]},{"n":29,"t":"他要按手在贖罪祭牲的頭上，在燔祭牲的地方把牠宰了。","notes":[]},{"n":30,"t":"祭司要用手指蘸一些祭牲的血，抹在燔祭壇的四個翹角上，再把其餘的血全倒在壇的底座上；","notes":[]},{"n":31,"t":"又要把祭牲所有的脂肪都取下，正如取平安祭牲的脂肪一樣。祭司要把脂肪燒在壇上，在耶和華面前作為馨香的祭。祭司要為他贖罪，他就蒙赦免。","notes":[]},{"n":32,"t":"「人若牽一隻綿羊為贖罪祭作供物，就要牽一隻沒有殘疾的母羊。","notes":[]},{"n":33,"t":"他要按手在贖罪祭牲的頭上，在宰燔祭牲的地方宰了牠，作為贖罪祭。","notes":[]},{"n":34,"t":"祭司要用手指蘸一些贖罪祭牲的血，抹在燔祭壇的四個翹角上，再把其餘的血全倒在壇的底座上；","notes":[]},{"n":35,"t":"又要把祭牲所有的脂肪都取下，正如取平安祭的羊的脂肪一樣。祭司要按獻給耶和華火祭的條例，把脂肪燒在壇上。祭司要為他所犯的罪贖了他，他就蒙赦免。」","notes":[]}]},"5":{"heading":"贖愆祭的條例","verses":[{"n":1,"t":"「若有人犯了罪，就是聽見了誓言，他本來可以作證，卻不把所看見、所知道的說出來，必須擔當他的罪孽。","notes":[]},{"n":2,"t":"若有人摸了任何不潔之物，無論是野獸的不潔屍體，家畜的不潔屍體，或是群聚動物的不潔屍體，他雖不察覺，也是不潔淨，就有罪了。","notes":[]},{"n":3,"t":"或是他摸了人的不潔之物，就是任何使人成為不潔的不潔之物，他雖不察覺，但一知道，就有罪了。","notes":[]},{"n":4,"t":"若有人隨口發誓，或出於惡意，或出於善意，這人無論在甚麼事上隨意發誓，雖不察覺，但一知道，就在這其中的一件事上有罪了。","notes":[]},{"n":5,"t":"當他在這其中的一件事上有罪的時候，就要承認所犯的罪，","notes":[]},{"n":6,"t":"並要為所犯的罪，把他的贖愆祭牲，就是羊群中的一隻母綿羊或母山羊，獻給耶和華為贖罪祭，祭司要為他的罪贖了他。","notes":[]},{"n":7,"t":"「若他的力量不夠獻一隻綿羊，就要為所犯的罪，把兩隻斑鳩或是兩隻雛鴿獻給耶和華為贖愆祭：一隻作贖罪祭，一隻作燔祭。","notes":[]},{"n":8,"t":"他要把這些帶到祭司那裏，祭司就先把贖罪祭獻上，從鳥的頸項上扭斷牠的頭，但不把鳥撕斷。","notes":[]},{"n":9,"t":"祭司要把一些贖罪祭牲的血彈在祭壇的邊上，其餘的血要倒在壇的底座上；這是贖罪祭。","notes":[]},{"n":10,"t":"他要依照條例獻第二隻鳥為燔祭。祭司要為他所犯的罪贖了他，他就蒙赦免。","notes":[]},{"n":11,"t":"「他的力量若不夠獻兩隻斑鳩或兩隻雛鴿，就要為所犯的罪把供物，就是十分之一伊法細麵，獻上為贖罪祭；不可加上油，也不可加上乳香，因為這是贖罪祭。","notes":[]},{"n":12,"t":"他要把細麵帶到祭司那裏，祭司要取出滿滿的一把，作為紀念，按照獻火祭給耶和華的條例把它燒在壇上；這是贖罪祭。","notes":[]},{"n":13,"t":"至於他在這幾件事中所犯的任何罪，祭司要為他贖了，他就蒙赦免。剩下的都歸給祭司，和素祭一樣。」","notes":[]},{"n":14,"t":"耶和華吩咐摩西說：","notes":[]},{"n":15,"t":"「若有人在耶和華的聖物上無意中犯了罪，有了過犯，就要獻羊群中一隻沒有殘疾的公綿羊給耶和華為贖愆祭，或依聖所的舍客勒所估定的銀子，作為贖愆祭。","notes":[]},{"n":16,"t":"他要為在聖物上的疏忽賠償，另外加五分之一，把這些都交給祭司。祭司要用贖愆祭的公綿羊為他贖罪，他就蒙赦免。","notes":[]},{"n":17,"t":"「若有人犯罪，在任何事上犯了一條耶和華所吩咐的禁令，他雖不察覺，仍算有罪，必須擔當自己的罪孽。","notes":[]},{"n":18,"t":"他要牽羊群中一隻沒有殘疾的公綿羊，或照你所估定的價值，給祭司作贖愆祭。祭司要為他贖他因不知道而無意中所犯的罪，他就蒙赦免。","notes":[]},{"n":19,"t":"這是贖愆祭；因他確實得罪了耶和華。」","notes":[]}]},"6":{"heading":"祭司獻燔祭的責任","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「若有人犯罪，得罪了耶和華，就是在鄰舍寄託他的東西或抵押品上行詭詐，或搶奪，或欺壓鄰舍，","notes":[]},{"n":3,"t":"或是撿了失物行了詭詐，起了假誓，在人所做的任何事上犯了罪；","notes":[]},{"n":4,"t":"他既犯了罪，有了過犯，就要歸還他所搶奪的，或是因欺壓所得的，或是別人寄託他的，或是他所撿到的失物，","notes":[]},{"n":5,"t":"或是起假誓得來的任何東西，就要全數歸還，另外再加五分之一。在查出他有罪的日子，就要立刻賠還給原主。","notes":[]},{"n":6,"t":"他要獻羊群中一隻沒有殘疾的公綿羊，給耶和華為贖愆祭，或照你所估定的價值，給祭司作贖愆祭。","notes":["七十士譯本沒有「給祭司」。"]},{"n":7,"t":"祭司要在耶和華面前為他贖罪；他無論做了甚麼事，以致有了罪，都必蒙赦免。」","notes":[]},{"n":8,"t":"耶和華吩咐摩西說：","notes":[]},{"n":9,"t":"「你要吩咐亞倫和他的子孫說，燔祭的條例是這樣：燔祭要放在壇的底盤上，從晚上到天亮，壇上的火要不斷地燒著。","notes":[]},{"n":10,"t":"祭司要穿上細麻布衣服，又要把細麻布褲子穿在身上，把在壇上燒剩的燔祭灰收起來，放在壇的旁邊。","notes":[]},{"n":11,"t":"然後，他要脫去這衣服，穿上別的衣服，把灰拿到營外潔淨之處。","notes":[]},{"n":12,"t":"壇上的火要不斷地燒著，不可熄滅。每日早晨，祭司要在壇上燒柴，把燔祭擺在壇上，並燒平安祭牲的脂肪。","notes":[]},{"n":13,"t":"壇上的火要不斷地燒著，不可熄滅。」","notes":[]},{"n":14,"t":"「素祭的條例是這樣：亞倫的子孫要在壇前把這祭獻在耶和華面前。","notes":[],"heads":["祭司獻素祭的責任"]},{"n":15,"t":"祭司要從素祭中的細麵取出一把，再取些油和素祭上所有的乳香，把這些作為紀念的燒在壇上，是獻給耶和華為馨香的祭。","notes":[]},{"n":16,"t":"亞倫和他子孫要吃素祭剩下的；要在聖處吃這無酵餅，在會幕的院子裏吃。","notes":[]},{"n":17,"t":"烤餅不可加酵。這是從獻給我的火祭中歸給他們的一份；如贖罪祭和贖愆祭一樣，這份是至聖的。","notes":[]},{"n":18,"t":"亞倫子孫中的男丁都要吃，因為這是你們世世代代從獻給耶和華的火祭中，他們永遠應得的份。凡摸這些祭物的都要成為聖。」","notes":[]},{"n":19,"t":"耶和華吩咐摩西說：","notes":[]},{"n":20,"t":"「這是亞倫受膏的日子，他和他的子孫所要獻給耶和華的供物：十分之一伊法細麵，如他們經常獻的素祭，早晨一半，晚上一半。","notes":[]},{"n":21,"t":"要在鐵盤上用油調和，調勻後，就拿去烤。素祭烤熟了要分成小塊，作為獻給耶和華馨香的祭。","notes":[]},{"n":22,"t":"亞倫子孫中接續他受膏為祭司的，要把這素祭獻上，全燒給耶和華。這是永遠的定例。","notes":[]},{"n":23,"t":"祭司一切的素祭要全部燒了，不可以吃。」","notes":[]},{"n":24,"t":"耶和華吩咐摩西說：","notes":[],"heads":["祭司獻贖罪祭的責任"]},{"n":25,"t":"「你要吩咐亞倫和他的子孫說，贖罪祭的條例是這樣：要在耶和華面前宰燔祭牲的地方宰贖罪祭牲；這是至聖的。","notes":[]},{"n":26,"t":"獻贖罪祭的祭司要吃這祭物；要在聖處，就是在會幕的院子裏吃。","notes":[]},{"n":27,"t":"凡摸這祭肉的都要成為聖；這祭牲的血若濺在衣服上，你要在聖處洗淨那濺到血的衣服。","notes":["「你要...衣服」：原文另譯「那濺到血的地方要在聖處洗淨」。"]},{"n":28,"t":"煮這祭物的瓦器要打碎；若祭物是在銅器裏煮，要把這銅器擦淨，用水沖洗。","notes":[]},{"n":29,"t":"祭司中所有的男丁都可以吃；這是至聖的。","notes":[]},{"n":30,"t":"若將任何贖罪祭的血帶進會幕，為要在聖所贖罪，那肉就不可吃，要用火焚燒。」","notes":[]}]},"7":{"heading":"祭司獻贖愆祭的責任","verses":[{"n":1,"t":"「贖愆祭的條例是這樣：這祭是至聖的。","notes":[]},{"n":2,"t":"人在哪裏宰燔祭牲，也要在哪裏宰贖愆祭牲；其血，祭司要灑在壇的周圍。","notes":[]},{"n":3,"t":"祭司要獻上牠所有的脂肪，把肥尾巴和包著內臟的脂肪，","notes":[]},{"n":4,"t":"兩個腎和腎上的脂肪，即靠近腎兩旁的脂肪，以及肝上的網油，連同腎一起取下。","notes":[]},{"n":5,"t":"祭司要把這些燒在壇上，獻給耶和華為火祭，作為贖愆祭。","notes":[]},{"n":6,"t":"祭司中所有的男丁都可以吃這祭物，要在聖處吃；這是至聖的。","notes":[]},{"n":7,"t":"贖罪祭怎樣，贖愆祭也是怎樣，都有一樣的條例，用贖愆祭贖罪的祭司要得這祭物。","notes":[]},{"n":8,"t":"獻燔祭的祭司，無論為誰獻，所獻燔祭牲的皮要歸給那祭司，那是他的。","notes":[]},{"n":9,"t":"任何素祭，無論是在爐中烤的，用煎鍋或鐵盤做成的，都要歸給獻祭的祭司。","notes":[]},{"n":10,"t":"任何素祭，無論是用油調和的，是乾的，都要歸亞倫的子孫，大家均分。」","notes":[]},{"n":11,"t":"「獻給耶和華平安祭的條例是這樣：","notes":[],"heads":["祭司獻平安祭的責任"]},{"n":12,"t":"若有人為感謝獻祭，就要把用油調和的無酵餅、抹了油的無酵薄餅，和用油調勻細麵做成的餅，與感謝祭一同獻上。","notes":[]},{"n":13,"t":"要用有酵的餅，和那為感謝而獻的平安祭，與供物一同獻上。","notes":[]},{"n":14,"t":"他要從每一種供物中拿一個餅，獻給耶和華為舉祭，是要歸給那灑平安祭牲血的祭司。","notes":[]},{"n":15,"t":"為感謝而獻的平安祭的肉，要在獻祭當天吃，一點也不可留到早晨。","notes":[]},{"n":16,"t":"若所獻的是還願祭或甘心祭，要在獻祭當天吃，剩下的，第二天也可以吃。","notes":[]},{"n":17,"t":"第三天，所剩下的祭肉要用火焚燒。","notes":[]},{"n":18,"t":"第三天若吃平安祭的肉，必不蒙悅納，所獻的也不算為祭；這祭物是不潔淨的，凡吃這祭物的，必擔當自己的罪孽。","notes":[]},{"n":19,"t":"「沾了不潔淨之物的肉就不可吃，要用火焚燒。至於其他的肉，凡潔淨的人都可以吃這肉；","notes":[]},{"n":20,"t":"但不潔淨的人若吃了獻給耶和華平安祭的肉，這人必從民中剪除。","notes":[]},{"n":21,"t":"若有人摸了不潔之物，無論是人體的不潔淨，或是不潔的牲畜，或是不潔的可憎之物 ，再吃了獻給耶和華平安祭的肉，這人必從民中剪除。」","notes":["「可憎之物」：有古卷是「群聚動物」。"]},{"n":22,"t":"耶和華吩咐摩西說：","notes":[]},{"n":23,"t":"「你要吩咐以色列人說：牛、綿羊、山羊的脂肪，你們都不可吃。","notes":[]},{"n":24,"t":"自然死去的或被野獸撕裂的，那脂肪可以作別的用途，你們卻萬不可吃。","notes":[]},{"n":25,"t":"任何人吃了獻給耶和華作火祭祭牲的脂肪，這人必從民中剪除。","notes":[]},{"n":26,"t":"在你們一切的住處，無論是鳥或獸的血，你們都不可吃。","notes":[]},{"n":27,"t":"無論誰吃了血，這人必從民中剪除。」","notes":[]},{"n":28,"t":"耶和華吩咐摩西說：","notes":[]},{"n":29,"t":"「你要吩咐以色列人說：獻平安祭給耶和華的，要從他的平安祭中取些供物來獻給耶和華。","notes":[]},{"n":30,"t":"他要親手把獻給耶和華的火祭帶來，要把脂肪和胸帶來，把胸在耶和華面前搖一搖，作為搖祭。","notes":[]},{"n":31,"t":"祭司要把脂肪燒在壇上，但胸要歸給亞倫和他的子孫。","notes":[]},{"n":32,"t":"你們要從平安祭牲中把右腿作為舉祭，送給祭司。","notes":[]},{"n":33,"t":"亞倫子孫中獻平安祭牲的血和脂肪的，要得這右腿，作為他當得的份。","notes":[]},{"n":34,"t":"因為我從以色列人的平安祭中，把這搖祭的胸和這舉祭的腿給亞倫祭司和他子孫，作為他們在以色列人中永遠當得的份。」","notes":[]},{"n":35,"t":"這是從耶和華的火祭中取出，作為亞倫和他子孫受膏的份，就是摩西叫他們前來，給耶和華供祭司職分的那一天開始的。","notes":[],"heads":["祭司責任的結語"]},{"n":36,"t":"這是在摩西膏他們的日子，耶和華吩咐給他們的，作為他們在以色列人中世世代代永遠當得的份。","notes":[]},{"n":37,"t":"這就是燔祭、素祭、贖罪祭、贖愆祭、聖職禮和平安祭的條例，","notes":[]},{"n":38,"t":"都是耶和華在西奈山上吩咐摩西的，也是他在西奈曠野吩咐以色列人獻供物給耶和華的日子所說的。","notes":[]}]},"8":{"heading":"祭司的條例","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你領亞倫和他兒子前來，並將聖衣、膏油，與贖罪祭的一頭公牛、兩隻公綿羊、一筐無酵餅都一同帶來；","notes":[]},{"n":3,"t":"又要召集全會眾到會幕的門口。」","notes":[]},{"n":4,"t":"摩西就遵照耶和華的吩咐做了，於是會眾聚集在會幕的門口。","notes":[]},{"n":5,"t":"摩西對會眾說：「這是耶和華所吩咐當做的事。」","notes":[]},{"n":6,"t":"摩西領了亞倫和他兒子前來，用水洗他們。","notes":[]},{"n":7,"t":"他給亞倫穿上內袍，束上腰帶，套上外袍，加上以弗得，再束上精緻的帶子，把以弗得繫在他身上。","notes":[]},{"n":8,"t":"他又給亞倫戴上胸袋，把烏陵和土明放在胸袋內。","notes":[]},{"n":9,"t":"他把禮冠戴在亞倫的頭上，禮冠前面安上金牌，成為聖冕，是照耶和華所吩咐摩西的。","notes":[]},{"n":10,"t":"摩西用膏油抹帳幕和其中所有的，使它們成為聖。","notes":[]},{"n":11,"t":"他又用膏油在祭壇上彈了七次，抹了壇和壇的一切器皿，以及洗濯盆和盆座，使它們成為聖。","notes":[]},{"n":12,"t":"他把膏油倒在亞倫的頭上膏他，使他成為聖。","notes":[]},{"n":13,"t":"摩西帶了亞倫的兒子來，給他們穿上內袍，束上腰帶，裹上頭巾，是照耶和華所吩咐摩西的。","notes":[]},{"n":14,"t":"他把贖罪祭的公牛牽來，亞倫和他兒子按手在贖罪祭公牛的頭上，","notes":[]},{"n":15,"t":"就宰了公牛。摩西取了血，用指頭抹在祭壇周圍的四個翹角上，使壇潔淨，再把其餘的血倒在壇的底座上，使壇成為聖，為壇贖罪。","notes":[]},{"n":16,"t":"摩西把內臟所有的脂肪和肝上的網油，以及兩個腎與腎上的脂肪取出，都燒在壇上。","notes":[]},{"n":17,"t":"至於公牛，連皮帶肉和糞，他都用火燒在營外，是照耶和華所吩咐摩西的。","notes":[]},{"n":18,"t":"他把燔祭的公綿羊牽來，亞倫和他兒子按手在羊的頭上，","notes":[]},{"n":19,"t":"就宰了公羊。摩西把血灑在祭壇的周圍，","notes":[]},{"n":20,"t":"把羊切成塊，把頭和肉塊，以及脂肪拿去燒，","notes":[]},{"n":21,"t":"他用水洗了內臟和腿之後，就把全羊燒在壇上，作為馨香的燔祭，是獻給耶和華的火祭，都是照耶和華所吩咐摩西的。","notes":[]},{"n":22,"t":"他又牽來第二隻公綿羊，就是聖職禮的羊，亞倫和他兒子按手在羊的頭上，","notes":[]},{"n":23,"t":"就宰了羊。摩西把一些血抹在亞倫的右耳垂上，右手的大拇指上和右腳的大腳趾上。","notes":[]},{"n":24,"t":"他領了亞倫的兒子來，把一些血抹在他們的右耳垂上，右手的大拇指上和右腳的大腳趾上。摩西把其餘的血灑在壇的周圍。","notes":[]},{"n":25,"t":"他把脂肪，肥尾巴、內臟所有的脂肪、肝上的網油、兩個腎、腎上的脂肪，和右腿取下，","notes":[]},{"n":26,"t":"再從耶和華面前那裝無酵餅的籃子中取一個無酵餅、一個油餅和一個薄餅，把這些放在脂肪和右腿上。","notes":[]},{"n":27,"t":"他把這一切放在亞倫和他兒子的手上，在耶和華面前搖一搖，作為搖祭。","notes":[]},{"n":28,"t":"摩西從他們的手上把這些祭物拿來，放在壇的燔祭上燒，這就是聖職禮中獻給耶和華馨香的火祭。","notes":[]},{"n":29,"t":"摩西拿羊的胸，在耶和華面前搖一搖，作為搖祭，這是聖職禮的羊歸給摩西的一份，是照耶和華所吩咐摩西的。","notes":[]},{"n":30,"t":"摩西取些膏油和壇上的血，彈在亞倫和他的衣服上，以及他兒子和他們的衣服上，使亞倫和他的衣服，他兒子和他們的衣服都成為聖。","notes":[]},{"n":31,"t":"摩西對亞倫和他兒子說：「你們要在會幕的門口把肉煮了，在那裏吃這肉和聖職禮中籃子裏的餅，按我所吩咐的說：『這是亞倫和他兒子當吃的。』","notes":[]},{"n":32,"t":"剩下的肉和餅，你們要用火焚燒。","notes":[]},{"n":33,"t":"這七天，你們不可走出會幕的門口，直等到你們聖職禮的日子滿了，因為授予你們聖職需要七天。","notes":["「授予...七天」或譯「主叫你們七天承接聖職」。"]},{"n":34,"t":"今天所做的，都是耶和華吩咐要做的，好為你們贖罪。","notes":[]},{"n":35,"t":"這七天，你們要晝夜留在會幕門內，遵守耶和華所吩咐的，免得你們死亡，因為所吩咐我的就是這樣。」","notes":[]},{"n":36,"t":"於是，亞倫和他的兒子就做了耶和華藉著摩西所吩咐的一切事。","notes":[]}]},"9":{"heading":"亞倫獻祭","verses":[{"n":1,"t":"到了第八天，摩西召亞倫和他兒子，以及以色列的眾長老來，","notes":[]},{"n":2,"t":"對亞倫說：「你當取一頭公牛犢作贖罪祭，一隻公綿羊作燔祭，都要沒有殘疾的，獻在耶和華面前。","notes":[]},{"n":3,"t":"你要對以色列人說：『你們當取一隻公山羊作贖罪祭，再取一頭牛犢和一隻小綿羊，都要一歲沒有殘疾的，作燔祭；","notes":[]},{"n":4,"t":"又當取一頭公牛、一隻公綿羊作平安祭，宰殺獻在耶和華面前，再加上調油的素祭。因為今天耶和華要向你們顯現。』」","notes":[]},{"n":5,"t":"於是，他們把摩西所吩咐的帶到會幕前；全會眾都近前來，站在耶和華面前。","notes":[]},{"n":6,"t":"摩西說：「這是耶和華吩咐你們當做的事，耶和華的榮光要向你們顯現。」","notes":[]},{"n":7,"t":"摩西對亞倫說：「你靠近祭壇前，獻你的贖罪祭和燔祭，為自己與百姓贖罪，再獻上百姓的供物，為他們贖罪，都是照耶和華所吩咐的。」","notes":[]},{"n":8,"t":"於是，亞倫靠近壇前，宰了那頭為自己贖罪的牛犢。","notes":[]},{"n":9,"t":"亞倫的兒子把血遞給他，他就把指頭蘸在血中，抹在壇的四個翹角上，再把其餘的血倒在壇的底座上。","notes":[]},{"n":10,"t":"他把贖罪祭的脂肪和腎，以及肝上的網油，燒在壇上，是照耶和華所吩咐摩西的。","notes":[]},{"n":11,"t":"他用火將肉和皮燒在營外。","notes":[]},{"n":12,"t":"亞倫把燔祭牲宰了，他兒子把血遞給他，他就把血灑在壇的周圍。","notes":[]},{"n":13,"t":"他們又把燔祭一塊一塊地，連頭遞給他，他就燒在壇上。","notes":[]},{"n":14,"t":"他又洗了內臟和腿，放在壇的燔祭上燒。","notes":[]},{"n":15,"t":"然後，他奉上百姓的供物。他牽來給百姓作贖罪祭的公山羊，把牠宰了，獻為贖罪祭，和先前的一樣。","notes":[]},{"n":16,"t":"他也奉上燔祭，按照條例獻上。","notes":[]},{"n":17,"t":"除了早晨的燔祭以外，他又獻上素祭，用手取了滿滿的一把，燒在壇上。","notes":[]},{"n":18,"t":"亞倫宰了那給百姓作平安祭的公牛和公綿羊，他兒子把血遞給他，他就把血灑在壇的周圍；","notes":[]},{"n":19,"t":"他們把公牛和公綿羊的脂肪、肥尾巴，包著內臟的脂肪，腎和肝上的網油，都遞給他。","notes":[]},{"n":20,"t":"他們把脂肪放在祭牲的胸上，他就把脂肪燒在壇上。","notes":[]},{"n":21,"t":"亞倫把祭牲的胸和右腿在耶和華面前搖一搖，作為搖祭，是照摩西所吩咐的。","notes":[]},{"n":22,"t":"亞倫向百姓舉手，為他們祝福。他獻了贖罪祭、燔祭、平安祭就下來了。","notes":[]},{"n":23,"t":"摩西和亞倫進了會幕。他們出來，為百姓祝福；耶和華的榮光向全體百姓顯現。","notes":[]},{"n":24,"t":"有火從耶和華面前出來，焚燒了壇上的燔祭和脂肪；全體百姓一看見，就都歡呼，臉伏於地。","notes":[]}]},"10":{"heading":"拿答和亞比戶","verses":[{"n":1,"t":"亞倫的兒子拿答和亞比戶各拿著自己的香爐，把火放在爐裏，加上香，在耶和華面前獻上凡火，是耶和華沒有吩咐他們的。","notes":[]},{"n":2,"t":"有火從耶和華面前出來，把他們吞滅，他們就死在耶和華面前。","notes":[]},{"n":3,"t":"於是，摩西對亞倫說：「這就是耶和華所吩咐的，說：『我在那親近我的人中要顯為聖；在全體百姓面前，我要得著榮耀。』」亞倫就默默不言。","notes":[]},{"n":4,"t":"摩西召亞倫的叔父烏薛的兒子米沙利和以利撒反前來，對他們說：「過來，把你們的親屬從聖所前抬到營外。」","notes":[]},{"n":5,"t":"於是，二人過來把屍體連袍子一起抬到營外，是照摩西所吩咐的。","notes":[]},{"n":6,"t":"摩西對亞倫和他兒子以利亞撒和以他瑪說：「不可蓬頭散髮，也不可撕裂衣服，免得你們死亡，免得耶和華向全會眾發怒。但你們的弟兄以色列全家卻要為耶和華發出的火哀哭。","notes":[]},{"n":7,"t":"你們也不可出會幕的門口，免得你們死亡，因為耶和華的膏油在你們身上。」他們就遵照摩西的話去做了。","notes":[]},{"n":8,"t":"耶和華吩咐亞倫說：","notes":[]},{"n":9,"t":"「你和你兒子進會幕的時候，清酒烈酒都不可喝，免得你們死亡，這要作你們世世代代永遠的定例。","notes":[]},{"n":10,"t":"你們必須分辨聖的俗的，潔淨的和不潔淨的，","notes":[]},{"n":11,"t":"也要將耶和華藉摩西吩咐以色列人的一切律例教導他們。」","notes":[]},{"n":12,"t":"摩西對亞倫和他剩下的兒子以利亞撒和以他瑪說：「獻給耶和華的火祭中所剩下的素祭，你們要拿來，在祭壇旁吃這無酵餅，因為它是至聖的。","notes":[]},{"n":13,"t":"你們要在聖處吃，因為在獻給耶和華的火祭中，這是你和你兒子當得的份；所吩咐我的就是這樣。","notes":[]},{"n":14,"t":"這搖祭的胸和這舉祭的腿，你要在潔淨的地方和你的兒女一同吃，因為這些是從以色列人的平安祭中歸給你，作為你和你兒子當得的份。","notes":[]},{"n":15,"t":"他們要把舉祭的腿、搖祭的胸和火祭的脂肪一同帶來，在耶和華面前搖一搖，作為搖祭。這些要歸給你和你兒子，作永遠當得的份，都是照耶和華所吩咐的。」","notes":[]},{"n":16,"t":"那時，摩西急切地尋找那隻贖罪祭的公山羊，看哪，牠已經燒掉了。他向亞倫剩下的兒子以利亞撒和以他瑪發怒，說：","notes":[]},{"n":17,"t":"「你們為何沒有在聖所吃這贖罪祭呢？它是至聖的，是耶和華給你們的，為了除掉會眾的罪孽，在耶和華面前為他們贖罪。","notes":[]},{"n":18,"t":"看哪，這祭牲的血沒有拿到聖所裏去！你們應當照我所吩咐的，在聖所裏吃這祭肉。」","notes":[]},{"n":19,"t":"亞倫對摩西說：「看哪，他們今天在耶和華面前獻上贖罪祭和燔祭，但是我卻遭遇這樣的災難。我若今天吃這贖罪祭，耶和華豈能看為美呢？」","notes":[]},{"n":20,"t":"摩西聽了，就看為美。","notes":[]}]},"11":{"heading":"潔淨與不潔淨的食物","verses":[{"n":1,"t":"耶和華吩咐摩西和亞倫，對他們說：","notes":[]},{"n":2,"t":"「你們要吩咐以色列人說，地上一切的走獸中可吃的動物是這些：","notes":[]},{"n":3,"t":"凡蹄分兩瓣，分趾蹄而又反芻食物的走獸，你們都可以吃。","notes":[]},{"n":4,"t":"但那反芻或分蹄之中不可吃的是：駱駝，反芻卻不分蹄，對你們是不潔淨的；","notes":[]},{"n":5,"t":"石獾，反芻卻不分蹄，對你們是不潔淨的；","notes":[]},{"n":6,"t":"兔子，反芻卻不分蹄，對你們是不潔淨的；","notes":[]},{"n":7,"t":"豬，蹄分兩瓣，分趾蹄卻不反芻，對你們是不潔淨的。","notes":[]},{"n":8,"t":"這些獸的肉，你們不可吃；牠們的屍體，你們也不可摸，對你們都是不潔淨的。","notes":[]},{"n":9,"t":"「水中可吃的是這些：凡在水裏，無論是海或河，有鰭有鱗的，都可以吃。","notes":[]},{"n":10,"t":"凡在海裏、河裏和水裏滋生的動物，就是在水裏所有的動物，無鰭無鱗的，對你們是可憎的。","notes":[]},{"n":11,"t":"牠們對你們都是可憎的。你們不可吃牠們的肉；牠們的屍體，也當以為可憎。","notes":[]},{"n":12,"t":"凡在水裏無鰭無鱗的，對你們是可憎的。","notes":[]},{"n":13,"t":"「飛鳥中你們當以為可憎，不可吃且可憎的是：鵰、狗頭鵰、紅頭鵰，","notes":[]},{"n":14,"t":"鷂鷹、小鷹的類群，","notes":[]},{"n":15,"t":"所有烏鴉的類群，","notes":[]},{"n":16,"t":"鴕鳥、夜鷹、魚鷹、鷹的類群，","notes":[]},{"n":17,"t":"鴞鳥、鸕鶿、貓頭鷹，","notes":[]},{"n":18,"t":"角鴟、鵜鶘、禿鵰，","notes":[]},{"n":19,"t":"鸛、鷺鷥的類群，戴鵀與蝙蝠。","notes":[]},{"n":20,"t":"「凡有翅膀卻用四足爬行的群聚動物，對你們是可憎的。","notes":[]},{"n":21,"t":"只是有翅膀卻用四足爬行的群聚動物中，足上有腿在地上跳的，你們還可以吃；","notes":[]},{"n":22,"t":"其中你們可以吃的有蝗蟲的類群，螞蚱的類群，蟋蟀的類群和蚱蜢的類群。","notes":[]},{"n":23,"t":"其餘有翅膀有四足的群聚動物，對你們都是可憎的。","notes":[]},{"n":24,"t":"「這些都能使你們不潔淨。凡摸牠們屍體的，必不潔淨到晚上。","notes":[]},{"n":25,"t":"任何人搬動了牠們的屍體，要把衣服洗淨，必不潔淨到晚上。","notes":[]},{"n":26,"t":"凡蹄分兩瓣卻不分趾或不反芻食物的走獸，對你們是不潔淨的；誰摸了牠們就不潔淨。","notes":[]},{"n":27,"t":"凡用腳掌行走，四足行走的動物，對你們是不潔淨的；凡摸牠們屍體的，必不潔淨到晚上。","notes":[]},{"n":28,"t":"誰搬動了牠們的屍體，要把衣服洗淨，必不潔淨到晚上。這些對你們是不潔淨的。","notes":[]},{"n":29,"t":"「在地上成群的群聚動物中，對你們不潔淨的是這些：鼬鼠、鼫鼠、蜥蜴的類群，","notes":[]},{"n":30,"t":"壁虎、龍子、守宮、蛇醫、蝘蜓。","notes":[]},{"n":31,"t":"這些群聚動物對你們都是不潔淨的。在牠們死後，凡摸了牠們屍體的，必不潔淨到晚上。","notes":[]},{"n":32,"t":"其中死了的，若掉在任何東西上，這東西就不潔淨，無論是木器、衣服、皮革、麻袋，或是任何工作需用的器皿，都要泡在水中，必不潔淨到晚上，然後才是潔淨的。","notes":[]},{"n":33,"t":"若有一點掉在瓦器裏，裏面的任何東西就不潔淨了； 你們要把這瓦器打破。","notes":[]},{"n":34,"t":"其中一切可吃的食物，沾到那水的就不潔淨；器皿裏可喝的東西，也必不潔淨。","notes":[]},{"n":35,"t":"牠們的屍體，只要有一點掉在任何物件上，那物件就不潔淨。無論是烤爐或爐灶，都要打碎；它們不潔淨，而且對你們也不潔淨。","notes":[]},{"n":36,"t":"但是水泉或池子，就是聚水的地方，仍是潔淨的；凡摸這些屍體的才不潔淨。","notes":[]},{"n":37,"t":"若牠們的屍體有一點掉在要播的種子上，種子仍是潔淨的；","notes":[]},{"n":38,"t":"若水已經澆在種子上，牠們的屍體有一點掉在上面，這種子對你們就是不潔淨的了。","notes":[]},{"n":39,"t":"「你們可吃的走獸中若有死了的，誰摸了牠的屍體，就必不潔淨到晚上。","notes":[]},{"n":40,"t":"人若吃了那已死的走獸，要把衣服洗淨，必不潔淨到晚上。人若搬動了那已死的走獸，要把衣服洗淨，必不潔淨到晚上。","notes":[]},{"n":41,"t":"「凡在地上成群的群聚動物都是可憎的，都不可吃。","notes":[]},{"n":42,"t":"凡用肚子爬行或用四腳爬行，或是用多足的，地上一切群聚的動物，你們都不可吃，因為是可憎的。","notes":[]},{"n":43,"t":"你們不可因任何群聚的動物使自己成為可憎的，也不可因牠們成為不潔淨，染了污穢。","notes":[]},{"n":44,"t":"我是耶和華－你們的神。你們要使自己分別為聖，要成為聖，因為我是神聖的。你們不可因地上爬行的群聚動物使自己不潔淨。","notes":[]},{"n":45,"t":"我是把你們從埃及地領出來的耶和華，要作你們的神。你們要成為聖，因為我是神聖的。」","notes":[]},{"n":46,"t":"這是走獸、飛鳥、水中一切游動的生物和地上一切爬行的動物的條例，","notes":[]},{"n":47,"t":"為要使你們能分辨潔淨的和不潔淨的，可吃的和不可吃的動物。","notes":[]}]},"12":{"heading":"產婦潔淨的條例","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人說：婦人若懷孕生男孩，就不潔淨七天，像在月經污穢的期間不潔淨一樣。","notes":[]},{"n":3,"t":"第八天，要給嬰孩行割禮。","notes":[]},{"n":4,"t":"婦人產後流血的潔淨，要家居三十三天。她潔淨的日子未滿，不可摸聖物，也不可進入聖所。","notes":[]},{"n":5,"t":"她若生女孩，就不潔淨兩個七天，像經期中一樣。她產後流血的潔淨，要家居六十六天。","notes":[]},{"n":6,"t":"「潔淨的日子滿了，無論生兒子或女兒，她要把一隻一歲的羔羊作燔祭，一隻雛鴿或一隻斑鳩作贖罪祭，帶到會幕的門口交給祭司。","notes":[]},{"n":7,"t":"祭司要把這祭物獻在耶和華面前，為她贖罪。這樣，她就從流血中得潔淨了。這是為生男或生女之婦人的條例。","notes":[]},{"n":8,"t":"婦人的能力若不足，無法獻一隻羔羊，她就要取兩隻斑鳩或兩隻雛鴿，一隻為燔祭，一隻為贖罪祭。祭司要為她贖罪，她就潔淨了。」","notes":[]}]},"13":{"heading":"有關皮膚病的條例","verses":[{"n":1,"t":"耶和華吩咐摩西和亞倫說：","notes":[]},{"n":2,"t":"「人身上的皮膚若腫脹，或發疹，或有斑點，可能成為痲瘋 的災病，就要把他帶到亞倫祭司或亞倫的一個作祭司的子孫那裏。","notes":["「痲瘋」泛指傳染性皮膚病；下同。"]},{"n":3,"t":"祭司要檢查他身上皮膚的患處，若患處的毛已經變白，災病的現象深入身上皮膚內，這就是痲瘋的災病。祭司檢查後，要宣佈他為不潔淨。","notes":[]},{"n":4,"t":"若這人身上的皮膚有白斑，看起來並沒有深入皮膚內，其上的毛也沒有變白，祭司就要將這病人隔離七天。","notes":[]},{"n":5,"t":"第七天，祭司要檢查他，看哪，若災病在祭司眼前止住了，沒有在皮膚上擴散，要將他再隔離七天。","notes":[]},{"n":6,"t":"到了第七天，祭司要再檢查他。看哪，若災病減輕，沒有在皮膚上擴散，祭司就要宣佈他為潔淨，因為他患的不過是疹子。那人要洗自己的衣服，就潔淨了。","notes":[]},{"n":7,"t":"他給祭司檢查宣佈為潔淨後，疹子若在皮膚上大大擴散，他就要再給祭司檢查。","notes":[]},{"n":8,"t":"祭司要檢查，看哪，疹子若在皮膚上擴散了，祭司就要宣佈他為不潔淨，是痲瘋病。","notes":[]},{"n":9,"t":"「人若得了痲瘋的災病，就要把他帶到祭司那裏。","notes":[]},{"n":10,"t":"祭司要檢查，看哪，若皮膚有白色腫塊，使毛變白，腫塊裏有嫩的新長的肉，","notes":[]},{"n":11,"t":"這就是他身上皮膚慢性的痲瘋病。祭司要宣佈他為不潔淨，不必將他隔離，因為他已是不潔淨了。","notes":[]},{"n":12,"t":"若痲瘋在皮膚四處擴散，長滿在患災病之人的皮膚上，據祭司察看，從頭到腳無處不有，","notes":[]},{"n":13,"t":"祭司就要檢查，看哪，若這病人全身已長滿了痲瘋，就要宣佈他為潔淨；他全身都變白了，他是潔淨的。","notes":[]},{"n":14,"t":"但他身上一旦出現新長的肉，就不潔淨了。","notes":[]},{"n":15,"t":"祭司一見新長的肉，就要宣佈他為不潔淨。新長的肉是不潔淨的，這就是痲瘋病。","notes":[]},{"n":16,"t":"新長的肉若變白了，他就要到祭司那裏。","notes":[]},{"n":17,"t":"祭司要檢查，看哪，患處若變白了，祭司就要宣佈那患災病的人為潔淨，他就潔淨了。","notes":[]},{"n":18,"t":"「人身上的皮膚若長了瘡，卻已經好了，","notes":["「人身上的皮膚」：撒瑪利亞五經是「人身上」。"]},{"n":19,"t":"在長瘡之處又發腫變白，或是出現白中帶紅的斑點，就要給祭司檢查。","notes":[]},{"n":20,"t":"祭司要檢查，看哪，若災病的現象已深入皮膚內，其上的毛也變白了，祭司就要宣佈他為不潔淨，有痲瘋的災病生在瘡中。","notes":[]},{"n":21,"t":"祭司若檢查，看哪，其上沒有白毛，也沒有深入皮膚內，而且災病減輕，祭司就要將他隔離七天。","notes":[]},{"n":22,"t":"若在皮膚上大大擴散，祭司就要宣佈他為不潔淨，這是災病。","notes":[]},{"n":23,"t":"斑點若留在原處，沒有擴散，這就是瘡的疤痕，祭司就要宣佈他為潔淨。","notes":[]},{"n":24,"t":"「人身上的皮膚若被火燒傷，傷口新長的肉有了斑點，無論是白中帶紅，或是全白，","notes":[]},{"n":25,"t":"祭司就要檢查，看哪，斑點上的毛若變白了，現象又深入皮膚內，這就是痲瘋長在燒傷處；祭司就要宣佈他為不潔淨，是痲瘋的災病。","notes":[]},{"n":26,"t":"若祭司檢查，看哪，斑點上沒有白毛，也沒有深入皮膚內，而且災病減輕，祭司就要將他隔離七天。","notes":[]},{"n":27,"t":"第七天，祭司要檢查他。斑點若在皮膚上大大擴散，祭司就要宣佈他為不潔淨，是患了痲瘋的災病。","notes":[]},{"n":28,"t":"斑點若留在原處，沒有在皮膚上擴散，並減輕了，它只是燒傷的腫塊，祭司要宣佈他為潔淨，這不過是燒傷後的疤痕。","notes":[]},{"n":29,"t":"「無論男女，若在頭上或下巴有災病，","notes":[]},{"n":30,"t":"祭司就要檢查這災病，看哪，若災病的現象深入皮膚內，其上有黃色的細毛，祭司就要宣佈他為不潔淨，這是疥瘡，是頭上或下巴的痲瘋病。","notes":[]},{"n":31,"t":"祭司要檢查這疥瘡的災病，看哪，現象若未深入皮膚內，其上也沒有黑毛，祭司就要將長疥瘡的人隔離七天。","notes":[]},{"n":32,"t":"第七天，祭司要檢查這災病，看哪，若疥瘡沒有擴散，其上沒有黃色的毛，疥瘡的現象也沒有深入皮膚內，","notes":[]},{"n":33,"t":"那人就要剃去鬚髮，但不可剃長疥瘡之處。祭司要將那長疥瘡的人，再隔離七天。","notes":[]},{"n":34,"t":"第七天，祭司要檢查疥瘡，看哪，疥瘡若沒有在皮膚上擴散，現象也未深入在皮膚內，祭司就要宣佈他為潔淨；那人要洗自己的衣服，就潔淨了。","notes":[]},{"n":35,"t":"但他被宣佈為潔淨後，疥瘡若在皮膚上大大擴散，","notes":[]},{"n":36,"t":"祭司就要檢查他。看哪，疥瘡若在皮膚上擴散，祭司就不必找黃色的毛，這人是不潔淨了。","notes":[]},{"n":37,"t":"若疥瘡在祭司眼前止住了，其上長了黑毛，疥瘡就已痊癒了，那人是潔淨的，祭司要宣佈他為潔淨。","notes":[]},{"n":38,"t":"「無論男女，身上的皮膚若有斑點，是白色的斑點，","notes":[]},{"n":39,"t":"祭司就要檢查，看哪，若皮膚的斑點是暗白色的，這是皮膚長了斑；那人是潔淨的。","notes":[]},{"n":40,"t":"「人的頭髮若掉了，變成禿頭，他是潔淨的。","notes":[]},{"n":41,"t":"他頭頂的前面若掉了頭髮，以致頂門光禿，他是潔淨的。","notes":[]},{"n":42,"t":"頭禿處或頂門禿處，若有白中帶紅的災病，這就是痲瘋長在他的頭禿處或頂門禿處。","notes":[]},{"n":43,"t":"祭司要檢查他，看哪，若頭禿處或頂門禿處的災病腫塊白中帶紅，像身上皮膚痲瘋病的現象一樣，","notes":[]},{"n":44,"t":"那人就是患了痲瘋病，是不潔淨的。祭司要宣佈他為不潔淨；他的災病是生在頭上。","notes":[]},{"n":45,"t":"「患有痲瘋災病的人，他的衣服要撕裂，也要蓬頭散髮，遮住上唇，喊著說：『不潔淨！不潔淨！』","notes":[]},{"n":46,"t":"災病還在他身上的時候，他就是不潔淨的；既然不潔淨，他就要獨居，住在營外。」","notes":[]},{"n":47,"t":"「衣服若發霉了，無論是羊毛衣服、麻布衣服，","notes":["「霉」：原文與「痲瘋的災病」相同；下同。"],"heads":["衣服發霉的條例"]},{"n":48,"t":"無論是經線、緯線，是麻布的、羊毛的，是皮革，或是任何皮製的物件；","notes":[]},{"n":49,"t":"若是衣服、皮革、經線、緯線，或是任何皮製的物件呈現綠色或紅色，這就是發霉，必須給祭司檢查。","notes":[]},{"n":50,"t":"祭司要檢查這霉，把發霉的物件隔離七天。","notes":[]},{"n":51,"t":"第七天，他要檢查這霉。若霉在衣服上，無論是經線、緯線，或任何用途的皮製物件上擴散，這是侵蝕性的霉，是不潔淨的。","notes":[]},{"n":52,"t":"發霉的衣服，無論在經線、緯線，羊毛的、麻布的，或是任何皮製物件，都要把它燒掉；因為這是侵蝕性的霉，必須用火焚燒。","notes":[]},{"n":53,"t":"祭司檢查，看哪，霉若在衣服上，無論是經線、緯線，或在任何的皮製物件上沒有擴散，","notes":[]},{"n":54,"t":"祭司就要吩咐人把發霉的物件洗了，再隔離七天。","notes":[]},{"n":55,"t":"洗過之後，祭司要檢查，看哪，若那霉在他眼前沒有變色，霉雖沒有擴散，也是不潔淨的。這是侵蝕性的災病，無論是在正面或反面，都要用火焚燒那物件。","notes":[]},{"n":56,"t":"祭司若檢查，看哪，那霉在洗過之後已經褪色，他就要從衣服，皮革，或經線、緯線，把發霉的部分撕去。","notes":[]},{"n":57,"t":"若霉再出現在衣服上，無論是經線、緯線、或在任何皮製物件上，這就是舊霉復發，必須用火將那發霉的物件焚燒。","notes":[]},{"n":58,"t":"洗過的衣服，或是經線，緯線，或是任何皮製的物件，若霉已經消失了，仍要再洗，這衣服就潔淨了。」","notes":[]},{"n":59,"t":"這就是衣服發霉的條例。無論是羊毛衣服，麻布衣服，或是經線、緯線，或任何皮製的物件，都按照這條例宣佈為潔淨或不潔淨。","notes":[]}]},"14":{"heading":"痊癒後的潔淨條例","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「這是患痲瘋病的人得潔淨時的條例：要帶他到祭司那裏，","notes":[]},{"n":3,"t":"祭司要出到營外，檢查那患痲瘋病的人，看哪，他的痲瘋災病已經痊癒了，","notes":[]},{"n":4,"t":"祭司就要吩咐人為那求潔淨的人帶兩隻潔淨的活鳥和香柏木、朱紅色紗，以及牛膝草來。","notes":[]},{"n":5,"t":"祭司要吩咐用瓦器盛清水，把第一隻鳥宰在上面。","notes":[]},{"n":6,"t":"至於那隻活鳥，祭司要把牠和香柏木、朱紅色紗，以及牛膝草，一同蘸在宰於清水上的鳥血中。","notes":[]},{"n":7,"t":"他要向那從痲瘋病中得潔淨的人身上彈血七次，宣佈他為潔淨，然後把那活鳥在野地裏放走。","notes":[]},{"n":8,"t":"求潔淨的人要洗衣服，剃去所有的毛髮，用水洗澡，他就潔淨了。然後，他可以進營，不過仍要在自己的帳棚外居住七天。","notes":[]},{"n":9,"t":"到了第七天，他要剃所有的毛髮，頭髮、鬍鬚、眼睛的眉毛，他全身的毛都剃了；然後，他要洗衣服，用水洗身，才潔淨了。","notes":[]},{"n":10,"t":"「第八天，他要取兩隻沒有殘疾的小公羊和一隻沒有殘疾、一歲的小母羊，以及作為素祭的十分之三伊法調了油的細麵和一羅革的油。","notes":[]},{"n":11,"t":"宣佈潔淨的祭司要將那求潔淨的人，連同這些東西，安置在耶和華面前，會幕的門口。","notes":[]},{"n":12,"t":"祭司要取一隻小公羊獻為贖愆祭，又取一羅革的油，把它們在耶和華面前搖一搖，作為搖祭；","notes":[]},{"n":13,"t":"再把小公羊宰於聖處，就是宰贖罪祭牲和燔祭牲的地方。贖愆祭要歸給祭司，與贖罪祭一樣，是至聖的。","notes":[]},{"n":14,"t":"祭司要取一些贖愆祭牲的血，抹在求潔淨的人的右耳垂上、右手的大拇指上和右腳的大腳趾上。","notes":[]},{"n":15,"t":"祭司要從那一羅革的油中，取一些倒在自己的左手掌裏，","notes":[]},{"n":16,"t":"祭司要用右手指蘸在他左手掌的油裏，在耶和華面前用手指彈七次。","notes":[]},{"n":17,"t":"祭司要把手掌裏剩下的油抹在那求潔淨的人的右耳垂上、右手的大拇指上和右腳的大腳趾上，在贖愆祭牲之血抹過的上面。","notes":[]},{"n":18,"t":"祭司手掌裏剩下的油要抹在那求潔淨的人的頭上，祭司就在耶和華面前為他贖罪。","notes":[]},{"n":19,"t":"祭司要獻贖罪祭，為那從不潔淨中得潔淨的人贖罪，然後要宰燔祭牲，","notes":[]},{"n":20,"t":"祭司要把燔祭和素祭獻在壇上，祭司要為他贖罪，他就潔淨了。","notes":[]},{"n":21,"t":"「他若貧窮，手頭財力不及，就要取一隻小公羊作贖愆祭，作搖祭為他贖罪。他也要把作為素祭的十分之一伊法調了油的細麵，和一羅革的油，一同取來。","notes":[]},{"n":22,"t":"他又要照手頭財力所及，取兩隻斑鳩或兩隻雛鴿，一隻作贖罪祭，一隻作燔祭。","notes":[]},{"n":23,"t":"第八天，為了使自己潔淨，他要把這些祭物帶到耶和華面前，在會幕的門口交給祭司。","notes":[]},{"n":24,"t":"祭司要把贖愆祭的羔羊和那一羅革的油一同在耶和華面前搖一搖，作為搖祭。","notes":[]},{"n":25,"t":"祭司要宰贖愆祭的羔羊，取一些贖愆祭牲的血，抹在那求潔淨的人的右耳垂上、右手的大拇指上和右腳的大腳趾上。","notes":[]},{"n":26,"t":"祭司要把一些油倒在自己的左手掌裏，","notes":[]},{"n":27,"t":"祭司要用右手指，把他左手掌裏的油在耶和華面前彈七次。","notes":[]},{"n":28,"t":"祭司要把手掌裏的油抹一些在那求潔淨的人的右耳垂上、右手的大拇指上和右腳的大腳趾上，在贖愆祭牲之血抹過之處的上面。","notes":[]},{"n":29,"t":"祭司手掌裏剩下的油要抹在那求潔淨的人的頭上，在耶和華面前為他贖罪。","notes":[]},{"n":30,"t":"那人又要照他手頭財力所及，獻上斑鳩中的一隻或雛鴿中的一隻，","notes":[]},{"n":31,"t":"照他手頭財力所及，一隻為贖罪祭，一隻為燔祭，與素祭一同獻上。祭司就在耶和華面前為他贖罪。","notes":[]},{"n":32,"t":"這是為患痲瘋災病，手頭財力不及而求潔淨的人所定的條例。」","notes":[]},{"n":33,"t":"耶和華吩咐摩西和亞倫說：","notes":[],"heads":["房屋發霉的條例"]},{"n":34,"t":"「你們到了我所賜給你們為業的迦南地，我若使你們所得為業之地的房屋發霉，","notes":["「霉」：原文與「痲瘋的災病」相同；下同。"]},{"n":35,"t":"屋主就要去告訴祭司說：『據我看，房屋似乎發霉了。』","notes":[]},{"n":36,"t":"祭司進去檢查這霉之前，要吩咐把屋內的東西全部搬走，免得屋子裏所有的東西成為不潔淨。然後，祭司要進去檢查房屋。","notes":[]},{"n":37,"t":"他要檢查這霉，看哪，若屋子牆上的霉有發綠或發紅凹入的斑紋，其現象深入牆內，","notes":[]},{"n":38,"t":"祭司就要出到屋子的門外，把屋子封鎖七天。","notes":[]},{"n":39,"t":"第七天，祭司要再去檢查，看哪，霉若在屋子的牆上擴散，","notes":[]},{"n":40,"t":"祭司要吩咐把發霉的石頭挖出來，扔在城外不潔淨之處。","notes":[]},{"n":41,"t":"他也要叫人刮屋內的四圍，把刮出來的灰泥倒在城外不潔淨之處。","notes":[]},{"n":42,"t":"他們要用別的石頭取代挖出來的石頭，用別的灰泥塗抹屋子。","notes":[]},{"n":43,"t":"「他挖出石頭，刮了屋子，塗抹以後，霉若又在屋子裏出現，","notes":[]},{"n":44,"t":"祭司就要進去檢查，看哪，霉若在屋子裏擴散，那就是有侵蝕性的霉在屋子裏，是不潔淨的。","notes":[]},{"n":45,"t":"他要拆毀屋子，把石頭、木料和所有的灰泥都搬到城外不潔淨之處。","notes":[]},{"n":46,"t":"屋子封鎖的任何時候，進去的人必不潔淨到晚上。","notes":[]},{"n":47,"t":"在屋子裏躺臥的人必須把衣服洗淨，在屋子裏吃飯的人也必須把衣服洗淨。","notes":[]},{"n":48,"t":"「屋子塗抹了之後，祭司若進去檢查，看哪，霉沒有在屋內擴散，就要宣佈這房屋為潔淨，因為霉已經消除了。","notes":[]},{"n":49,"t":"他要為潔淨房屋取兩隻鳥和香柏木、朱紅色紗，以及牛膝草，","notes":[]},{"n":50,"t":"用瓦器盛清水，把一隻鳥宰在上面。","notes":[]},{"n":51,"t":"他要把香柏木、牛膝草、朱紅色紗和那一隻活鳥，都蘸在被宰的鳥血和清水中，用來彈屋子七次。","notes":[]},{"n":52,"t":"他要用鳥血、清水、活鳥、香柏木、牛膝草和朱紅色紗潔淨那房屋。","notes":[]},{"n":53,"t":"他要把活鳥在城外野地裏放走。他要為房屋贖罪，房屋就潔淨了。」","notes":[]},{"n":54,"t":"這條例是為痲瘋災病和疥瘡，","notes":[]},{"n":55,"t":"衣服和房屋發霉，","notes":[]},{"n":56,"t":"以及皮膚腫脹、發疹、有斑點等，","notes":[]},{"n":57,"t":"用以分辨何時潔淨，何時不潔淨。這是痲瘋病的條例。","notes":[]}]},"15":{"heading":"患漏症的條例","verses":[{"n":1,"t":"耶和華吩咐摩西和亞倫說：","notes":[]},{"n":2,"t":"「你們要吩咐以色列人，對他們說：人若身體患了漏症，他因這症就不潔淨了。","notes":["「身體」指「下體」；下同。"]},{"n":3,"t":"這就是他因漏症而有的不潔淨：無論是身體流出液體，或身體已經止住不再有液體，他都是不潔淨的。","notes":[]},{"n":4,"t":"那患漏症的人所躺的床都不潔淨，所坐的任何東西也不潔淨。","notes":[]},{"n":5,"t":"凡摸他床的人，要洗衣服，用水洗澡，必不潔淨到晚上。","notes":[]},{"n":6,"t":"人坐了漏症患者坐過的東西，他要洗衣服，用水洗澡，必不潔淨到晚上。","notes":[]},{"n":7,"t":"人摸了漏症患者，他要洗衣服，用水洗澡，必不潔淨到晚上。","notes":[]},{"n":8,"t":"若漏症患者吐唾沫在潔淨的人身上，這人要洗衣服，用水洗澡，必不潔淨到晚上。","notes":[]},{"n":9,"t":"漏症患者所騎的任何鞍子也不潔淨。","notes":[]},{"n":10,"t":"凡摸了他坐過的任何東西，必不潔淨到晚上；拿了這些東西的，要洗衣服，用水洗澡，必不潔淨到晚上。","notes":[]},{"n":11,"t":"漏症患者若沒有用水沖洗他的手，無論摸了誰，誰就要洗衣服，用水洗澡，必不潔淨到晚上。","notes":[]},{"n":12,"t":"漏症患者所摸的瓦器必要打破；他所摸的一切木器必要用水沖洗。","notes":[]},{"n":13,"t":"「漏症患者的漏症痊癒了，就要為潔淨自己計算七天，也要洗衣服，用清水洗身，就潔淨了。","notes":[]},{"n":14,"t":"第八天，他要帶兩隻斑鳩或兩隻雛鴿，來到耶和華面前，在會幕門口把鳥交給祭司。","notes":[]},{"n":15,"t":"祭司要獻上一隻為贖罪祭，一隻為燔祭。祭司要因這人所患的漏症，在耶和華面前為他贖罪。","notes":[]},{"n":16,"t":"「人若遺精，他要用水洗全身，必不潔淨到晚上。","notes":[]},{"n":17,"t":"無論是衣服或皮革，若沾染了精液，要用水洗淨，必不潔淨到晚上。","notes":[]},{"n":18,"t":"女人，若有男人與她同寢，沾染了精液，二人要用水洗澡，必不潔淨到晚上。」","notes":[]},{"n":19,"t":"「女人月經期間，有血從體內流出，她必不潔淨七天；凡摸她的，必不潔淨到晚上。","notes":[],"heads":["月經的條例"]},{"n":20,"t":"在不潔淨期間，女人所躺的東西都不潔淨，所坐的任何東西也不潔淨。","notes":[]},{"n":21,"t":"凡摸她床的，要洗衣服，用水洗澡，必不潔淨到晚上；","notes":[]},{"n":22,"t":"凡摸她坐過的東西的，要洗衣服，用水洗澡，必不潔淨到晚上；","notes":[]},{"n":23,"t":"不論是床，或她坐過的東西，人摸了，必不潔淨到晚上。","notes":[]},{"n":24,"t":"男人若和這女人同寢，沾了她的不潔淨，就不潔淨七天，所躺的床也都不潔淨。","notes":[]},{"n":25,"t":"「女人若在經期之外仍然流血多日，或是經期過長，她在流血的一切日子都不潔淨，和她在經期的日子不潔淨一樣。","notes":[]},{"n":26,"t":"在流血的日子，她所躺的床、所坐的任何東西都不潔淨，和在月經期間不潔淨一樣。","notes":[]},{"n":27,"t":"凡摸這些東西的，就不潔淨；他要洗衣服，用水洗澡，必不潔淨到晚上。","notes":[]},{"n":28,"t":"這女人的血漏若痊癒了，就要計算七天，然後才潔淨。","notes":[]},{"n":29,"t":"第八天，她要取兩隻斑鳩或兩隻雛鴿，帶到會幕門口祭司那裏。","notes":[]},{"n":30,"t":"祭司要獻一隻為贖罪祭，一隻為燔祭。祭司要因這女人血漏的不潔淨，在耶和華面前為她贖罪。","notes":[]},{"n":31,"t":"「你們要使以色列人與他們的不潔淨隔離，免得他們玷污我在他們中間的帳幕，因自己的不潔淨死亡。」","notes":[]},{"n":32,"t":"這條例是為漏症患者或遺精而不潔淨者，","notes":[]},{"n":33,"t":"女人經期的不潔，男女患漏症，以及男人與不潔淨女人同寢而立的。","notes":[]}]},"16":{"heading":"贖罪日","verses":[{"n":1,"t":"亞倫的兩個兒子靠近耶和華面前，死了。他們死後，耶和華吩咐摩西；","notes":[]},{"n":2,"t":"耶和華對摩西說：「你要吩咐你哥哥亞倫，不可隨時進入聖所的幔子內、到櫃蓋前，免得他死亡，因為我在櫃蓋上的雲中顯現。","notes":["「蓋」：原意「蓋住」，指「蓋住罪」，後來也稱為「施恩座」；下同。"]},{"n":3,"t":"亞倫進聖所要帶這些：一頭公牛犢為贖罪祭，一隻公綿羊為燔祭。","notes":[]},{"n":4,"t":"他要穿上細麻布聖內袍，把細麻布褲子穿在身上，腰束細麻布帶子，頭戴細麻布禮冠；這些都是聖服。他要用水洗身，然後穿上聖服。","notes":[]},{"n":5,"t":"他要從以色列會眾中取兩隻公山羊為贖罪祭，一隻公綿羊為燔祭。","notes":[]},{"n":6,"t":"「亞倫要把他自己贖罪祭的公牛獻上，為自己和家人贖罪；","notes":[]},{"n":7,"t":"也要把兩隻公山羊牽到耶和華面前，安置在會幕的門口。","notes":[]},{"n":8,"t":"亞倫要為那兩隻山羊抽籤，一籤歸給耶和華，一籤歸給阿撒瀉勒。","notes":[]},{"n":9,"t":"亞倫要把那抽中歸給耶和華的山羊牽來獻為贖罪祭，","notes":[]},{"n":10,"t":"至於抽中歸給阿撒瀉勒的山羊，卻要活著安放在耶和華面前，用以贖罪，然後送到曠野去，歸給阿撒瀉勒。","notes":[]},{"n":11,"t":"「亞倫要把他自己贖罪祭的公牛獻上，為自己和家人贖罪，他要宰作自己贖罪祭的公牛。","notes":[]},{"n":12,"t":"他要從耶和華面前的壇上取盛滿火炭的香爐，再拿一捧搗細的香料，把這些都帶入幔子內。","notes":[]},{"n":13,"t":"在耶和華面前，他要把香放在火上，使香的煙雲遮著法櫃上的蓋子，免得他死亡。","notes":[]},{"n":14,"t":"他要取一些公牛的血，用手指彈在櫃蓋的前面，就是東面，又在櫃蓋的前面用手指彈血七次。","notes":[]},{"n":15,"t":"「他要宰那隻為百姓作贖罪祭的公山羊，把羊的血帶入幔子內，把血彈在櫃蓋的上面和前面，好像彈公牛的血一樣。","notes":[]},{"n":16,"t":"因以色列人的不潔淨和過犯，就是他們一切的罪，他要為聖所贖罪；因會幕在他們不潔淨之中，他也要為會幕照樣做。","notes":[]},{"n":17,"t":"他進聖所贖罪的時候，會幕裏都不准有人，直等到他為自己和家人，以及以色列全會眾贖了罪出來。","notes":[]},{"n":18,"t":"他出來後，要到耶和華面前的祭壇那裏，為壇贖罪。他要取一些公牛的血和公山羊的血，抹在壇周圍的四個翹角上。","notes":[]},{"n":19,"t":"他也要用手指把血彈在壇上七次，使壇從以色列人的不潔淨中得以潔淨，成為聖。」","notes":[]},{"n":20,"t":"「亞倫為聖所和會幕，以及祭壇贖罪後，就要把那隻活的公山羊牽來。","notes":[],"heads":["代罪的山羊"]},{"n":21,"t":"他的雙手要按在活的山羊的頭上，承認以色列人所有的罪孽過犯，就是他們一切的罪，把這些罪都歸在羊的頭上，再指派一個人把牠送到曠野去。","notes":[]},{"n":22,"t":"這羊要擔當他們一切的罪孽，帶到無人之地；那人要把羊送到曠野去。","notes":[]},{"n":23,"t":"「亞倫要進入會幕，把他進聖所時所穿的細麻布衣服脫下，放在那裏，","notes":[]},{"n":24,"t":"又要在聖處用水洗身，穿上衣服出來，把自己的燔祭和百姓的燔祭獻上，為自己和百姓贖罪。","notes":[]},{"n":25,"t":"贖罪祭牲的脂肪要燒在壇上。","notes":[]},{"n":26,"t":"那放走山羊歸給阿撒瀉勒的人要洗衣服，用水洗身，然後才可以回到營裏。","notes":[]},{"n":27,"t":"作贖罪祭的公牛和作贖罪祭的公山羊的血被帶入聖所贖罪之後，就要把這牛羊搬到營外，皮、肉、糞都用火焚燒。","notes":[]},{"n":28,"t":"焚燒的人要洗衣服，用水洗身，然後才可以回到營裏。」","notes":[]},{"n":29,"t":"「這是你們永遠的定例：每年七月初十，你們要刻苦己心；無論是本地人，是寄居在你們中間的外人，任何工都不可做。","notes":[],"heads":["贖罪日"]},{"n":30,"t":"因為這日要為你們贖罪，潔淨你們，使你們脫離一切的罪，在耶和華面前得以潔淨。","notes":[]},{"n":31,"t":"這日你們要守完全安息的安息日，刻苦己心；這是永遠的定例。","notes":[]},{"n":32,"t":"那受膏接續他父親擔任聖職的祭司要贖罪，穿上細麻布衣服，就是聖衣，","notes":[]},{"n":33,"t":"為至聖所和會幕贖罪，為祭壇贖罪，並要為祭司和會眾的全體百姓贖罪。","notes":[]},{"n":34,"t":"這要作你們永遠的定例：因以色列人一切的罪，要一年一次為他們贖罪。」於是，亞倫照耶和華所吩咐摩西的做了 。","notes":["「於是...做了」或譯「摩西做了，正如耶和華所吩咐他的」。"]}]},"17":{"heading":"宰祭牲的條例","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐亞倫和他兒子，以及以色列眾人，對他們說，耶和華所吩咐的話是這樣：","notes":[]},{"n":3,"t":"凡以色列家中的人宰公牛，或小綿羊，或山羊，無論是在營內或營外，","notes":[]},{"n":4,"t":"若不把牲畜牽到會幕門口耶和華的帳幕前，獻給耶和華為供物，所流的血必歸到那人身上。他既使血流出，就要從百姓中剪除。","notes":[]},{"n":5,"t":"這是為要使以色列人把他們在野地裏所宰的祭牲帶來，帶到耶和華前，會幕門口祭司那裏，宰殺這些祭牲，把牠們獻給耶和華為平安祭。","notes":[]},{"n":6,"t":"祭司要在會幕門口，把血灑在耶和華的祭壇上，把脂肪焚燒，獻給耶和華為馨香的祭。","notes":[]},{"n":7,"t":"他們不可再宰殺祭牲獻給他們行淫所隨從的山羊鬼魔。這要作他們世世代代永遠的定例。","notes":[]},{"n":8,"t":"「你要對他們說：凡以色列家中的任何人，或寄居在他們中間的外人獻燔祭或祭物，","notes":[]},{"n":9,"t":"若不帶到會幕門口獻給耶和華，那人必從百姓中剪除。」","notes":[]},{"n":10,"t":"「凡以色列家中的任何人，或寄居在他們中間的外人，吃任何的血，我必向那吃血的人變臉，把他從百姓中剪除。","notes":[],"heads":["不可吃血"]},{"n":11,"t":"因為動物的生命是在血中。我把這血賜給你們，可以在祭壇上為你們的生命贖罪；因為血就是生命，能夠贖罪。","notes":[]},{"n":12,"t":"因此，我對以色列人說：你們都不可吃血；寄居在你們中間的外人也不可吃血。","notes":[]},{"n":13,"t":"凡以色列人，或寄居在他們中間的外人，獵取了可吃的飛禽走獸，必須把牠的血放出來，用土掩蓋。","notes":[]},{"n":14,"t":"「因一切動物的生命，牠的血就是牠的生命。所以我對以色列人說：無論甚麼動物的血，你們都不可吃，因為一切動物的生命就是牠的血。凡吃血的必被剪除。","notes":[]},{"n":15,"t":"無論是本地人，是寄居的，若吃了自然死去或被野獸撕裂的動物，要洗衣服，用水洗澡，必不潔淨到晚上，晚上就潔淨了。","notes":[]},{"n":16,"t":"但他若不洗衣服，也不洗身，就要擔當自己的罪孽。」","notes":[]}]},"18":{"heading":"淫亂的禁令","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人，對他們說：我是耶和華－你們的神。","notes":[]},{"n":3,"t":"你們不可做你們從前住埃及地的人所做的，也不可做我要領你們去的迦南地的人所做的。你們不可照他們的習俗行。","notes":[]},{"n":4,"t":"你們要遵行我的典章，謹守我的律例，按此而行。我是耶和華－你們的神。","notes":[]},{"n":5,"t":"你們要謹守我的律例典章；遵行的人就必因此得生。我是耶和華。","notes":[]},{"n":6,"t":"「任何人都不可親近骨肉之親，露其下體。我是耶和華。","notes":[]},{"n":7,"t":"你父親的下體，就是你母親的下體，你不可露；她是你的母親，不可露她的下體。","notes":[]},{"n":8,"t":"不可露你繼母的下體，就是你父親的下體。","notes":[]},{"n":9,"t":"你姊妹的下體，或是同父異母的，或是同母異父的，無論生在家或生在外的，都不可露她們的下體。","notes":[]},{"n":10,"t":"不可露你孫女或外孫女的下體，因為她們的下體就是你自己的下體。","notes":[]},{"n":11,"t":"你繼母為你父親所生的女兒是你的姊妹，不可露她的下體。","notes":[]},{"n":12,"t":"不可露你姑母的下體；她是你父親的骨肉之親。","notes":[]},{"n":13,"t":"不可露你姨母的下體；她是你母親的骨肉之親。","notes":[]},{"n":14,"t":"不可露你叔伯的下體，不可親近他的妻子；她是你的叔母、伯母。","notes":[]},{"n":15,"t":"不可露你媳婦的下體，她是你兒子的妻，不可露她的下體。","notes":[]},{"n":16,"t":"不可露你兄弟妻子的下體，這是你兄弟的下體。","notes":[]},{"n":17,"t":"不可露婦人的下體，又露她女兒的下體，也不可娶她的孫女或外孫女，露她們的下體；她們是骨肉之親。這是邪惡的事。","notes":["「骨肉之親」：原文另譯「她的骨肉之親」；七十士譯本是「你的骨肉之親」。"]},{"n":18,"t":"你妻子還活著的時候，不可另娶她的姊妹與她作對，露她姊妹的下體。","notes":[]},{"n":19,"t":"「不可親近經期中不潔淨的女人，露她的下體。","notes":[]},{"n":20,"t":"不可跟鄰舍的妻交合，因她玷污自己。","notes":[]},{"n":21,"t":"不可使你兒女經火獻給摩洛，也不可褻瀆你神的名。我是耶和華。","notes":[]},{"n":22,"t":"不可跟男人同寢，像跟女人同寢；這是可憎惡的事。","notes":[]},{"n":23,"t":"不可跟獸交合，因牠玷污自己。女人也不可站在獸前，與牠交合；這是逆性的事。","notes":[]},{"n":24,"t":"「在這一切的事上，你們都不可玷污自己，因為我在你們面前所逐出的列國，在這一切的事上玷污了自己。","notes":[]},{"n":25,"t":"連地也玷污了，我懲罰那地的罪孽，地就吐出它的居民來。","notes":[]},{"n":26,"t":"但你們要遵守我的律例典章。這一切可憎惡的事，無論是本地人或寄居在你們中間的外人，都不可以做。","notes":[]},{"n":27,"t":"在你們之前居住那地的人做了這一切可憎惡的事，地就玷污了。","notes":[]},{"n":28,"t":"不要讓地因你們玷污了它而把你們吐出來，像吐出在你們之前的國一樣。","notes":[]},{"n":29,"t":"無論是誰，若做了這其中一件可憎惡的事，必從百姓中剪除。","notes":[]},{"n":30,"t":"你們要遵守我的吩咐，免得你們隨從那些可憎的習俗，就是在你們之前的人所做的，玷污了自己。我是耶和華－你們的神。」","notes":[]}]},"19":{"heading":"成聖和公正的條例","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列全會眾，對他們說：你們要成為聖，因為我耶和華－你們的神是神聖的。","notes":[]},{"n":3,"t":"你們各人都當孝敬父母，也要守我的安息日。我是耶和華－你們的神。","notes":[]},{"n":4,"t":"你們不可轉向虛無的神明，也不可為自己鑄造神像。我是耶和華－你們的神。","notes":[]},{"n":5,"t":"「你們宰殺祭牲獻平安祭給耶和華的時候，要獻得使你們可蒙悅納。","notes":[]},{"n":6,"t":"這祭物要在獻的當天或第二天吃；若有剩到第三天的，就要用火焚燒。","notes":[]},{"n":7,"t":"第三天若再吃，這祭物是不潔淨的，必不蒙悅納。","notes":[]},{"n":8,"t":"吃的人必擔當自己的罪孽，因為他褻瀆了耶和華的聖物，這人必從百姓中剪除。","notes":[]},{"n":9,"t":"「你們在自己的地收割莊稼時，不可割盡田的角落，也不可拾取莊稼所掉落的。","notes":[]},{"n":10,"t":"不可摘盡葡萄園的葡萄，也不可拾取葡萄園中掉落的葡萄，要把它們留給窮人和寄居的。我是耶和華－你們的神。","notes":[]},{"n":11,"t":"「你們不可偷盜，不可欺騙，也不可彼此說謊。","notes":[]},{"n":12,"t":"不可指著我的名起假誓，褻瀆你神的名。我是耶和華。","notes":[]},{"n":13,"t":"「不可欺壓你的鄰舍，也不可偷盜。雇工的工錢不可在你那裏過夜，留到早晨。","notes":[]},{"n":14,"t":"不可咒罵聾子，也不可將絆腳石放在盲人面前。你要敬畏你的神。我是耶和華。","notes":[]},{"n":15,"t":"「你們審判的時候，不可不公正；不可偏護貧窮人，也不可看重有權勢人的臉，總要公平審判你的鄰舍。","notes":[]},{"n":16,"t":"不可在百姓中到處搬弄是非，不可陷害鄰舍的性命。我是耶和華。","notes":["「陷害...性命」：原文直譯「站在鄰舍的血上」。"]},{"n":17,"t":"「不可心裏恨你的弟兄；要指摘你的鄰舍，免得因他承擔罪過。","notes":[]},{"n":18,"t":"不可報仇，也不可埋怨你本國的子民。你要愛鄰如己。我是耶和華。","notes":[]},{"n":19,"t":"「你們要遵守我的律例。不可使你的牲畜與異類交配；不可在你的田地播下兩樣的種子；也不可穿兩種原料做成的衣服。","notes":[]},{"n":20,"t":"「若有人與女子同寢交合，而她是婢女，許配了丈夫，尚未被贖或得自由，就要受到懲罰，卻不可把他們處死，因為婢女還沒有得自由。","notes":[]},{"n":21,"t":"男的要把贖愆祭，就是一隻公綿羊牽到耶和華面前，會幕的門口。","notes":[]},{"n":22,"t":"祭司要用贖愆祭的羊在耶和華面前為他所犯的罪贖罪，他所犯的罪就必蒙赦免。","notes":[]},{"n":23,"t":"「你們到了迦南地，栽種各樣的果樹，就要把所結的果子當作不潔淨的；三年之內，你們要把它視為不潔淨，是不可吃的。","notes":["「不潔淨的」：原文是「未受割禮的」；下同。"]},{"n":24,"t":"但第四年所結的果子全是聖的，用以讚美耶和華。","notes":["「用以讚美耶和華」：撒瑪利亞五經是「作一般用途的啟用典禮的供物，獻給耶和華」。"]},{"n":25,"t":"第五年，你們就可以吃樹上的果子，使樹給你們結出更多的果子。我是耶和華－你們的神。","notes":[]},{"n":26,"t":"「你們不可吃帶血的食物。不可占卜，也不可觀星象。","notes":[]},{"n":27,"t":"頭的周圍不可剃，鬍鬚的周圍不可損壞。","notes":["「頭的周圍」或譯「兩鬢」。"]},{"n":28,"t":"不可為死人割劃自己的身體，也不可在身上刺花紋。我是耶和華。","notes":[]},{"n":29,"t":"「不可侮辱你的女兒，使她淪為娼妓，免得這地行淫亂，地就充滿了邪惡。","notes":[]},{"n":30,"t":"你們要謹守我的安息日，敬畏我的聖所。我是耶和華。","notes":[]},{"n":31,"t":"「不可轉向招魂的，也不可求問行巫術的，免得被他們玷污。我是耶和華－你們的神。","notes":[]},{"n":32,"t":"「在白髮的人面前，你要站起來，要尊敬老人；要敬畏你的神，我是耶和華。","notes":[]},{"n":33,"t":"「若有外人寄居在你們的地上和你同住，不可欺負他。","notes":[]},{"n":34,"t":"寄居在你們那裏的外人，你們要看他如本地人，並要愛他如己，因為你們在埃及地也作過寄居的。我是耶和華－你們的神。","notes":[]},{"n":35,"t":"「你們審判的時候，不可用不公正的度量衡。","notes":[]},{"n":36,"t":"你們要用公正的天平、公正的法碼、公正的伊法和公正的欣。我是耶和華－你們的神，曾把你們從埃及地領出來。","notes":[]},{"n":37,"t":"你們要謹守我一切的律例典章，遵行它們。我是耶和華。」","notes":[]}]},"20":{"heading":"懲罰的條例","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要對以色列人說：凡以色列人，或是寄居在以色列的外人，把自己兒女獻給摩洛的，必被處死；本地的百姓要用石頭打死他。","notes":[]},{"n":3,"t":"我也要向那人變臉，把他從百姓中剪除，因為他把兒女獻給摩洛，玷污了我的聖所，褻瀆了我的聖名。","notes":[]},{"n":4,"t":"那人把兒女獻給摩洛，本地的百姓若假裝沒看見，不把他處死，","notes":[]},{"n":5,"t":"我就要向這人和他的家人變臉，把他和所有跟隨他與摩洛行淫的人都從百姓中剪除。","notes":[]},{"n":6,"t":"「人若轉向招魂的和行巫術的，隨從他們行淫，我就要向這人變臉，把他從百姓中剪除。","notes":[]},{"n":7,"t":"你們要使自己分別為聖，要成為聖，因為我是耶和華－你們的神。","notes":[]},{"n":8,"t":"你們要謹守我的律例，遵行它們；我是使你們分別為聖的耶和華。","notes":[]},{"n":9,"t":"凡咒罵父母的，必被處死；他咒罵了父母，他的血要歸在他身上。","notes":[]},{"n":10,"t":"「凡與有夫之婦行姦淫，就是與鄰舍的妻子行姦淫的，姦夫淫婦必被處死。","notes":[]},{"n":11,"t":"人若與繼母同寢，就是露了父親的下體，二人必被處死，血要歸在他們身上。","notes":[]},{"n":12,"t":"人若與媳婦同寢，二人必被處死；他們行了亂倫的事，血要歸在他們身上。","notes":[]},{"n":13,"t":"男人若跟男人同寢，像跟女人同寢，他們二人行了可憎惡的事，必被處死，血要歸在他們身上。","notes":[]},{"n":14,"t":"人若娶妻，又娶妻子的母親，這是邪惡的事；要把這三人用火焚燒，在你們中間除去這邪惡。","notes":[]},{"n":15,"t":"人若與獸交合，必被處死；你們也要殺死那獸。","notes":[]},{"n":16,"t":"女人若與獸親近，與牠交合，你要把那女人和獸殺死；他們必被處死，血要歸在他們身上。","notes":[]},{"n":17,"t":"「人若娶自己的姊妹，或是同父異母的，或是同母異父的，彼此見了下體，這是可恥的事；他們必在自己百姓眼前被剪除。他露了姊妹的下體，必擔當自己的罪孽。","notes":[]},{"n":18,"t":"若有人跟經期中的婦人同寢，露了她的下體，暴露婦人的血源，婦人也露了自己的血源，二人必從百姓中剪除。","notes":[]},{"n":19,"t":"不可露姨母或姑母的下體，因為這是露了骨肉之親的下體，他們必擔當自己的罪孽。","notes":[]},{"n":20,"t":"人若與叔伯之妻同寢，就露了他叔伯的下體，他們必擔當自己的罪，必沒有子女而死。","notes":[]},{"n":21,"t":"人若娶了自己兄弟的妻子，就露了他兄弟的下體，這是不潔淨的事，他們必沒有子女。","notes":[]},{"n":22,"t":"「你們要謹守我一切的律例典章，遵行它們，免得我領你們去住的那地把你們吐出來。","notes":[]},{"n":23,"t":"我在你們面前所逐出的國民，你們不可隨從他們的風俗。因為他們行了這一切的事，所以我厭惡他們。","notes":[]},{"n":24,"t":"但我對你們說過，你們要承受他們的土地；我要把這流奶與蜜之地賜給你們，作為你們的產業。我是耶和華－你們的神，是把你們從萬民中分別出來的。","notes":[]},{"n":25,"t":"你們要分辨潔淨和不潔淨的飛禽走獸；不可因我定為不潔淨的飛禽走獸，或爬行在土地上的任何生物，使自己成為可憎惡的。","notes":[]},{"n":26,"t":"你們要歸我為聖，因為－我耶和華是神聖的；我把你們從萬民中分別出來，作我的子民。","notes":[]},{"n":27,"t":"「無論男女，是招魂的或行巫術的，他們必被處死。人要用石頭打死他們，血要歸在他們身上。」","notes":[]}]},"21":{"heading":"祭司成聖的條例","verses":[{"n":1,"t":"耶和華對摩西說：「你要告訴亞倫子孫作祭司的，對他們說：祭司不可為自己百姓中的死人玷污自己，","notes":[]},{"n":2,"t":"除非是他的骨肉之親，他的父母、兒女、兄弟、","notes":[]},{"n":3,"t":"或未出嫁還是處女的姊妹，因她是至親，才可以玷污自己。","notes":[]},{"n":4,"t":"祭司既然在自己百姓中為首，就不可從俗玷污自己。","notes":["「祭司...玷污自己」：原文另譯「祭司雖然作為丈夫，也不可為姻親從俗玷污自己」。"]},{"n":5,"t":"「不可使頭光禿，不可剃除鬍鬚的邊緣，也不可割劃自己的身體。","notes":[]},{"n":6,"t":"他們要歸神為聖，不可褻瀆他們神的名，因為耶和華的火祭，就是神的食物，是他們獻的，所以他們要成為聖。","notes":[]},{"n":7,"t":"「祭司不可娶妓女，或被玷污的女人為妻，也不可娶被休的婦人為妻，因為他是歸神為聖的。","notes":[]},{"n":8,"t":"你要使祭司分別為聖，因為他獻你神的食物。你要以他為聖，因為我是使你們分別為聖的耶和華，是神聖的。","notes":["「使你們分別為聖」：撒瑪利亞五經和七十士譯本是「使他們分別為聖」。"]},{"n":9,"t":"「祭司的女兒若行淫玷污自己，就侮辱了父親，要用火將她焚燒。","notes":[]},{"n":10,"t":"「在弟兄中作大祭司的，頭上倒了膏油，承接聖職，穿了聖衣，不可蓬頭散髮，也不可撕裂衣服；","notes":[]},{"n":11,"t":"不可挨近任何死屍，即使為了父母也不可玷污自己。","notes":[]},{"n":12,"t":"他不可出聖所，免得褻瀆了神的聖所，因為在他身上有神的膏油為聖冕。我是耶和華。","notes":[]},{"n":13,"t":"他要娶處女為妻。","notes":[]},{"n":14,"t":"大祭司不可娶寡婦，被休的婦人，或被玷污的妓女為妻；他只可以娶自己百姓中的處女為妻。","notes":[]},{"n":15,"t":"他不可在自己百姓中侮辱他的兒女，因為我是使他分別為聖的耶和華。」","notes":[]},{"n":16,"t":"耶和華吩咐摩西說：","notes":[]},{"n":17,"t":"「你吩咐亞倫說：你世世代代的後裔，凡有殘疾的都不可近前來獻神的食物。","notes":[]},{"n":18,"t":"因為凡有殘疾的，無論是失明的、瘸腿的、五官不正的、肢體之一過長的、","notes":[]},{"n":19,"t":"斷腳的、斷手的、","notes":[]},{"n":20,"t":"駝背的、侏儒的、有眼疾的、長癬的、長疥的，或是睪丸壓傷的，都不可近前來。","notes":[]},{"n":21,"t":"亞倫祭司的後裔，凡有殘疾的都不可近前來獻耶和華的火祭。他有殘疾，不可近前來獻神的食物。","notes":[]},{"n":22,"t":"神的食物，無論是聖的，或是至聖的，他都可以吃。","notes":[]},{"n":23,"t":"但他不可進到幔子前，也不可挨近祭壇前，因為他有殘疾，免得他褻瀆我的聖所。我是使他們分別為聖的耶和華。」","notes":[]},{"n":24,"t":"於是，摩西吩咐了亞倫和他的兒子，以及以色列眾人。","notes":[]}]},"22":{"heading":"吃聖物的條例","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐亞倫和他子孫說：你們要謹慎處理以色列人所分別為聖，歸給我的聖物，免得褻瀆我的聖名。我是耶和華。","notes":["「謹慎處理」：原文是「遠離」。"]},{"n":3,"t":"你要對他們說：你們世世代代的後裔，凡不潔淨的，卻挨近以色列人所分別為聖，歸給耶和華的聖物，那人必從我面前剪除。我是耶和華。","notes":[]},{"n":4,"t":"亞倫的後裔中，凡有痲瘋病的，或患漏症的，都不可吃聖物，直等他潔淨了。無論誰摸了那因屍體而不潔淨的東西，或遺精的人，","notes":[]},{"n":5,"t":"或摸到任何使他不潔淨的群聚動物或使他不潔淨的人，無論那人有甚麼不潔淨，","notes":[]},{"n":6,"t":"摸了這些的人必不潔淨到晚上；若不用水洗身，就不可吃聖物。","notes":[]},{"n":7,"t":"日落的時候，他就潔淨了，然後可以吃聖物，因為這是他的食物。","notes":[]},{"n":8,"t":"自然死去的或被野獸撕裂的，他不可吃，免得玷污自己。我是耶和華。","notes":[]},{"n":9,"t":"他們要遵守我的吩咐，免得因褻瀆聖物，擔當自己的罪而死。我是使他們分別為聖的耶和華。","notes":["「聖物」：原文是「它」。"]},{"n":10,"t":"「任何外人都不可吃聖物；寄居在祭司家的，或雇工，都不可吃聖物。","notes":[]},{"n":11,"t":"若是祭司用自己的銀錢買來的人，就可以吃聖物；在他家出生的人也可以吃他的食物。","notes":[]},{"n":12,"t":"祭司的女兒若嫁給外人，就不可吃舉祭的聖物。","notes":[]},{"n":13,"t":"但祭司的女兒若成為寡婦或被休，又沒有後裔，她回到父家，好像年輕的時候，就可以吃她父親的食物。只是任何外人都不可吃它。","notes":[]},{"n":14,"t":"若有人誤吃了聖物，要把聖物加上五分之一交給祭司。","notes":[]},{"n":15,"t":"祭司不可褻瀆以色列人獻給耶和華的聖物，","notes":[]},{"n":16,"t":"免得他們因吃聖物而自取罪孽。我是使他們分別為聖的耶和華。」","notes":[]},{"n":17,"t":"耶和華吩咐摩西說：","notes":[],"heads":["蒙悅納的祭物"]},{"n":18,"t":"「你要吩咐亞倫和他子孫，以及以色列眾人，對他們說：以色列家中的人，或在以色列中寄居的 ，若要獻供物給耶和華作燔祭，無論是為所許的願或是甘心獻的，","notes":["「寄居的」：有古卷和撒瑪利亞五經是「寄居的外人」。"]},{"n":19,"t":"就要將一頭公的，沒有殘疾的牛，或綿羊，或山羊獻上，這樣你們才蒙悅納。","notes":[]},{"n":20,"t":"凡有殘疾的，你們不可獻上，因為這樣你們必不蒙悅納。","notes":[]},{"n":21,"t":"若有人從牛群或羊群中，將平安祭獻給耶和華，無論是為還所許特別的願，或是甘心獻的，所獻的必須是健康、無任何殘疾的，才蒙悅納。","notes":[]},{"n":22,"t":"凡瞎眼的、受傷的、斷腿的、潰爛的、長癬的、長疥的，都不可獻給耶和華，不可在壇上作為火祭獻給耶和華。","notes":[]},{"n":23,"t":"無論是公牛或小綿羊，若一條腿太長或太短，只可作甘心祭獻上；若用來還願，就不蒙悅納。","notes":[]},{"n":24,"t":"凡睪丸損傷，或壓碎，或破裂，或閹割的，都不可獻給耶和華；不可在你們的地上行這事。","notes":[]},{"n":25,"t":"從外人的手裏得到任何這類的動物，也不可獻上作你們神的食物；因為牠們有缺陷，有殘疾，牠們必不為你們而蒙悅納。」","notes":[]},{"n":26,"t":"耶和華吩咐摩西說：","notes":[]},{"n":27,"t":"「剛出生的公牛，或綿羊，或山羊，七天當跟著牠的母親；從第八天起，可以當供物作為耶和華的火祭，這是蒙悅納的。","notes":[]},{"n":28,"t":"無論是牛或羊，不可在同一日宰牠和牠的小牛小羊。","notes":[]},{"n":29,"t":"你們宰殺祭牲獻感謝祭給耶和華，要獻得使你們可蒙悅納；","notes":[]},{"n":30,"t":"要在當天吃，一點也不可留到早晨。我是耶和華。","notes":[]},{"n":31,"t":"「你們要謹守我的誡命，遵行它們。我是耶和華。","notes":[]},{"n":32,"t":"你們不可褻瀆我的聖名；我在以色列人中要被尊為聖。我是使你們分別為聖的耶和華，","notes":[]},{"n":33,"t":"曾把你們從埃及地領出來，作你們的神。我是耶和華。」","notes":[]}]},"23":{"heading":"耶和華的節期","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人，對他們說：以下是我的節期，是你們要宣告為聖會的耶和華的節期。」","notes":[]},{"n":3,"t":"「六日要做工，第七日是完全安息的安息日，要有聖會；你們任何工都不可做。這是在你們一切的住處向耶和華當守的安息日。」","notes":[],"heads":["安息日"]},{"n":4,"t":"「以下是你們要按時宣告為聖會的耶和華的節期。」","notes":[]},{"n":5,"t":"「正月十四日黃昏的時候，是向耶和華守的逾越節。","notes":["「黃昏的時候」：原文是「兩個黃昏之間」。"],"heads":["逾越節和除酵節"]},{"n":6,"t":"這月的十五日是向耶和華守的除酵節；你們要吃無酵餅七日。","notes":[]},{"n":7,"t":"第一日要有聖會，任何勞動的工都不可做；","notes":[]},{"n":8,"t":"要將火祭獻給耶和華七日。第七日要有聖會，任何勞動的工都不可做。」","notes":[]},{"n":9,"t":"耶和華吩咐摩西說：","notes":[],"heads":["初熟莊稼的奉獻"]},{"n":10,"t":"「你要吩咐以色列人，對他們說：你們到了我賜給你們的地，收割莊稼的時候，要把初熟莊稼中的一捆拿來給祭司。","notes":[]},{"n":11,"t":"他要把這捆在耶和華面前搖一搖，使你們蒙悅納。祭司要在安息日的次日把這捆搖一搖。","notes":[]},{"n":12,"t":"搖這捆的那一日，你們要獻一隻一歲沒有殘疾的小公綿羊，給耶和華作燔祭。","notes":[]},{"n":13,"t":"同獻的素祭是十分之二伊法調了油的細麵，作為獻給耶和華馨香的火祭；同獻的澆酒祭是四分之一欣酒。","notes":[]},{"n":14,"t":"無論是餅，是烘熟的穀物，是新穗子，你們都不可吃；直等到你們把這供物帶來獻給你們神的那一天，才可以吃。在你們一切的住處，這要成為你們世世代代永遠的定例。」","notes":[]},{"n":15,"t":"「你們要從安息日的次日，就是獻那捆莊稼為搖祭的那日起，計算足足的七個安息日。","notes":[],"heads":["七七收穫節"]},{"n":16,"t":"到第七個安息日的次日，共計五十天，你們要將新的素祭獻給耶和華。","notes":[]},{"n":17,"t":"要從你們的住處取十分之二伊法細麵，加酵烤成兩個搖祭的餅，作為初熟之物獻給耶和華。","notes":[]},{"n":18,"t":"又要將七隻一歲沒有殘疾的羔羊、一頭公牛犢、兩隻公綿羊和餅一同奉上。這些要和素祭和澆酒祭一同作為燔祭獻給耶和華，作馨香的火祭獻給耶和華。","notes":[]},{"n":19,"t":"你們要獻一隻公山羊為贖罪祭，兩隻一歲的小公綿羊為平安祭。","notes":[]},{"n":20,"t":"祭司要把這些和初熟莊稼做成的餅，與兩隻小公綿羊一同在耶和華面前搖一搖，作為搖祭。這些獻給耶和華的聖物是歸給祭司的。","notes":[]},{"n":21,"t":"在這一日，你們要宣告聖會；任何勞動的工都不可做。在你們一切的住處，這要成為你們世世代代永遠的定例。","notes":[]},{"n":22,"t":"「你們在自己的地收割莊稼時，不可割盡田的角落，也不可拾取莊稼所掉落的，要把它們留給窮人和寄居的。我是耶和華－你們的神。」","notes":[]},{"n":23,"t":"耶和華吩咐摩西說：","notes":[],"heads":["新年"]},{"n":24,"t":"「你要吩咐以色列人說：七月初一，你們要守為完全安息的日子，要吹角作紀念，當有聖會。","notes":[]},{"n":25,"t":"任何勞動的工都不可做；要將火祭獻給耶和華。」","notes":[]},{"n":26,"t":"耶和華吩咐摩西說：","notes":[],"heads":["贖罪日"]},{"n":27,"t":"「但是，七月初十是贖罪日；你們要守為聖會，刻苦己心，並要將火祭獻給耶和華。","notes":[]},{"n":28,"t":"在這一日，任何工都不可做；因為這是贖罪日，要在耶和華－你們的神面前贖罪。","notes":[]},{"n":29,"t":"在這一日，凡不刻苦己心的，必從百姓中剪除。","notes":[]},{"n":30,"t":"凡在這一日做任何工的，我必將他從百姓中除滅。","notes":[]},{"n":31,"t":"任何工你們都不可做。在你們一切的住處，這要成為你們世世代代永遠的定例。","notes":[]},{"n":32,"t":"你們要守這日為完全安息的安息日，刻苦己心；從這月初九晚上到次日晚上，你們要守為安息日。」","notes":[]},{"n":33,"t":"耶和華吩咐摩西說：","notes":[],"heads":["住棚節"]},{"n":34,"t":"「你要吩咐以色列人說：這七月十五日是住棚節，要向耶和華守這節七日。","notes":[]},{"n":35,"t":"第一日當有聖會，任何勞動的工都不可做。","notes":[]},{"n":36,"t":"要將火祭獻給耶和華七日。第八日當守聖會，並要獻火祭給耶和華。這是嚴肅會，任何勞動的工都不可做。","notes":[]},{"n":37,"t":"「這是耶和華的節期，就是你們要宣告為聖會的節期；要將火祭，就是燔祭、素祭、祭物和澆酒祭，按照每日的規定獻給耶和華。","notes":[]},{"n":38,"t":"除此之外，還有耶和華的安息日，你們獻給耶和華的供物，一切的還願祭，和一切的甘心祭。","notes":[]},{"n":39,"t":"「但是，從七月十五日起，你們收藏了地的出產之後，要守耶和華的節期七日。第一日為要完全安息，第八日也要完全安息。","notes":[]},{"n":40,"t":"第一日，你們要拿美好樹上的果子、棕樹枝、樹葉茂密的枝條和河邊的柳枝，在耶和華－你們的神面前歡樂七日。","notes":[]},{"n":41,"t":"每年你們要向耶和華守這節七日。你們在七月裏所守的節，要成為世世代代永遠的定例。","notes":[]},{"n":42,"t":"你們要住在棚裏七日；凡以色列家出生的人都要住在棚裏，","notes":[]},{"n":43,"t":"好叫你們世世代代知道，我領以色列人出埃及地的時候，曾使他們住在棚裏。我是耶和華－你們的神。」","notes":[]},{"n":44,"t":"於是，摩西向以色列人頒佈了耶和華的節期。","notes":[]}]},"24":{"heading":"點燈","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人，把那搗成的純橄欖油拿來給你，用以點燈，使燈經常點著。","notes":[]},{"n":3,"t":"在會幕中法櫃前的幔子外，亞倫從晚上到早晨要在耶和華面前照管這燈。這要成為你們世世代代永遠的定例。","notes":[]},{"n":4,"t":"他要在耶和華面前經常照管純金燈臺上的燈。」","notes":["「純金」：原文是「純」；下同。"]},{"n":5,"t":"「你要取細麵，烤成十二個餅，每個用十分之二伊法。","notes":[],"heads":["供餅"]},{"n":6,"t":"要把餅排成兩行，每行六個，供在耶和華面前的純金桌子上。","notes":["「行」或譯「堆」；下同。"]},{"n":7,"t":"再把純乳香撒在每行餅上，作為紀念，是獻給耶和華為食物的火祭。","notes":[]},{"n":8,"t":"每個安息日，亞倫要把餅不間斷地供在耶和華面前。這是以色列人永遠的約。","notes":[]},{"n":9,"t":"這餅要歸給亞倫和他的子孫。他們要在聖處吃這餅，因為在獻給耶和華的火祭中，這餅是至聖的，歸給他作永遠當得的份。」","notes":[]},{"n":10,"t":"有一個以色列婦人的兒子，他父親是埃及人。有一日他出去，到以色列人中。這以色列婦人的兒子和一個以色列人在營裏爭吵。","notes":[],"heads":["褻瀆罪的判例"]},{"n":11,"t":"以色列婦人的兒子詛咒，褻瀆了聖名。有人把他送到摩西那裏。他的母親名叫示羅密，是但支派底伯利的女兒。","notes":[]},{"n":12,"t":"他們把這人收押在監裏，等候耶和華指示的話。","notes":[]},{"n":13,"t":"耶和華吩咐摩西說：","notes":[]},{"n":14,"t":"「把那詛咒的人帶到營外。凡聽見的人都要把手放在他頭上，全會眾要用石頭打死他。","notes":[]},{"n":15,"t":"你要吩咐以色列人說：凡詛咒神的，必要擔當自己的罪。","notes":[]},{"n":16,"t":"褻瀆耶和華名的，必被處死；全會眾必須用石頭打死他。無論是寄居的，是本地人，他褻瀆聖名的時候必被處死。","notes":[]},{"n":17,"t":"「打死人的，必被處死；","notes":[]},{"n":18,"t":"打死牲畜的，必賠上牲畜，以命償命。","notes":[]},{"n":19,"t":"人若傷害鄰舍以致殘疾，他怎樣做，也要照樣向他做：","notes":[]},{"n":20,"t":"以傷還傷，以眼還眼，以牙還牙。他怎樣使人有殘疾，也要照樣向他做。","notes":[]},{"n":21,"t":"打死牲畜的，必賠上牲畜；打死人的，必被處死。","notes":[]},{"n":22,"t":"無論是寄居的，是本地人，都依照同一條例。我是耶和華－你們的神。」","notes":[]},{"n":23,"t":"於是，摩西吩咐以色列人，他們就把那詛咒的人帶到營外，用石頭打死。以色列人就照耶和華所吩咐摩西的做了。","notes":[]}]},"25":{"heading":"安息年","verses":[{"n":1,"t":"耶和華在西奈山吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人，對他們說：你們到了我所賜你們那地的時候，地要休耕，向耶和華守安息。","notes":[]},{"n":3,"t":"你們六年要耕種田地，六年要修整葡萄園，收藏地的出產。","notes":[]},{"n":4,"t":"第七年，地要守完全安息的安息年，就是向耶和華守安息。你們不可耕種田地，也不可修整葡萄園。","notes":[]},{"n":5,"t":"不可收割自然生長的莊稼，也不可摘取沒有修剪的葡萄樹上的葡萄。這年，地要完全安息。","notes":[]},{"n":6,"t":"地在安息年所長出的，要給你和你的奴僕、使女、雇工，以及寄居在你那裏的外人作食物。","notes":[]},{"n":7,"t":"所有的出產也要給你的牲畜和你地上的走獸作食物。」","notes":[]},{"n":8,"t":"「你要計算七個安息年，就是七個七年。這就成為你的七個安息年，一共四十九年。","notes":[],"heads":["禧年"]},{"n":9,"t":"七月初十，你要大聲吹角；這是贖罪日，你要在全地吹角。","notes":[]},{"n":10,"t":"你們要以第五十年為聖年，在全地向所有的居民宣告自由。這是你們的禧年，各人的產業要歸還自己，各人要歸回自己的家。","notes":[]},{"n":11,"t":"第五十年要作為你們的禧年。你們不可耕種，不可收割自然生長的莊稼，也不可摘取沒有修剪的葡萄樹上的葡萄。","notes":[]},{"n":12,"t":"因為這是禧年，是你們的聖年；你們要吃地中自然生長的農作物。","notes":[]},{"n":13,"t":"「這禧年，你們各人的產業要歸還自己。","notes":[]},{"n":14,"t":"無論你賣甚麼給鄰舍，或從鄰舍的手中買甚麼，彼此不可虧負。","notes":[]},{"n":15,"t":"你要按照禧年後的年數向鄰舍買；他要按照可收成的年數賣給你；","notes":[]},{"n":16,"t":"年數越多，價錢就越高；年數越少，價錢就越低，因為他賣給你的是收成的數量。","notes":[]},{"n":17,"t":"你們彼此不可虧負，只要敬畏你的神，因為我是耶和華－你們的神。」","notes":[]},{"n":18,"t":"「你們要遵行我的律例，謹守我的典章，遵行它們，就可以在那地上安然居住。","notes":[],"heads":["安息年的食物"]},{"n":19,"t":"地必出產果實，你們可以吃飽，在那地上安然居住。","notes":[]},{"n":20,"t":"你們若說：『看哪，第七年我們不耕種，也不收藏農作物，我們吃甚麼呢？』","notes":[]},{"n":21,"t":"我必在第六年發令賜福給你們，地就長出三年的農作物來。","notes":[]},{"n":22,"t":"第八年你們要耕種，也要吃陳糧；等到第九年農作物收成的時候，你們還有陳糧吃。」","notes":[]},{"n":23,"t":"「地不可以賣斷，因為地是我的；你們在我面前是客旅，是寄居的。","notes":[],"heads":["贖房地產的條例"]},{"n":24,"t":"在你們所得為業的全地，要准許人有權將地贖回。","notes":[]},{"n":25,"t":"「你的弟兄若漸漸貧窮，賣了他的一些產業，他的至親就要來把弟兄所賣的贖回。","notes":[]},{"n":26,"t":"若沒有人能為他贖回，他的手頭漸漸寬裕，能夠贖回，","notes":[]},{"n":27,"t":"就要計算賣後的年數，把剩餘年數的價錢歸還給那買主，他的地業便歸還自己。","notes":[]},{"n":28,"t":"若他手頭的財力不夠贖回，所賣的地就要留在買主的手裏，直到禧年。到了禧年，地業要歸還賣主。","notes":[]},{"n":29,"t":"「人若賣城牆內的住宅，賣了以後，一整年內他有權贖回；這是他可以贖回的期限。","notes":[]},{"n":30,"t":"若他在一整年內不贖回，這有牆之城的房屋就確定永歸買主，直到世世代代；在禧年也不必歸還。","notes":[]},{"n":31,"t":"但周圍無城牆之村莊的房屋，要看為鄉下的田地，可以贖回；到了禧年就要歸還。","notes":[]},{"n":32,"t":"至於利未人所得為業的城鎮，利未人可以隨時贖回他們城鎮中的房屋。","notes":[]},{"n":33,"t":"在所得為業的城鎮，利未人若賣了房屋，又不贖回，到了禧年仍要歸還原主，因為利未人城鎮的房屋是他們在以色列人中的產業。","notes":[]},{"n":34,"t":"但是利未人各城郊外之地是不可賣的，因為這是他們永遠的產業。」","notes":[]},{"n":35,"t":"「你的弟兄在你那裏若漸漸貧窮，手頭缺乏，你就要幫補他，使他與你一同生活，像外人和寄居的一樣。","notes":[],"heads":["借貸給窮人的條例"]},{"n":36,"t":"不可向他取利息，也不可向他索取高利；要敬畏你的神，使你的弟兄與你一同生活。","notes":[]},{"n":37,"t":"你不可為了利息借錢給他，也不可為了高利而借糧。","notes":[]},{"n":38,"t":"我是耶和華－你們的神，曾領你們從埃及地出來，為要把迦南地賜給你們，要作你們的神。","notes":[]},{"n":39,"t":"「你的弟兄在你那裏若漸漸貧窮，將自己賣給你，你不可叫他像奴僕服事你。","notes":[]},{"n":40,"t":"他在你那裏要像雇工和寄居的，服事你直到禧年。","notes":[]},{"n":41,"t":"他和他兒女要離開你，一同出去，歸回自己的家，回到他祖宗的地業去。","notes":[]},{"n":42,"t":"因為他們是我的僕人，是我從埃及地領出來的。他們不可被賣為奴僕。","notes":[]},{"n":43,"t":"不可苛刻管轄他，只要敬畏你的神。","notes":[]},{"n":44,"t":"至於你所要的奴僕和使女，可以來自你們四圍的列國，你們可以從他們中買奴僕和使女。","notes":[]},{"n":45,"t":"那些寄居在你們中間的外人和他們的家屬，就是在你們地上所生的，你們可以從其中買人；他們要作你們的產業。","notes":[]},{"n":46,"t":"你們可以把他們遺留給你們後代的子孫，作為永遠繼承的產業；你們可以使他們作奴僕。至於你們的弟兄以色列人，你們彼此不可苛刻管轄。","notes":[]},{"n":47,"t":"「住在你那裏的外人或寄居的，若手頭漸漸寬裕，你的弟兄卻漸漸貧窮，將自己賣給那外人或寄居的，或外人家族的一支，","notes":[]},{"n":48,"t":"賣了以後，有權把自己贖回。他弟兄中的一位可以把他贖回。","notes":[]},{"n":49,"t":"他的叔伯或叔伯的兒子可以贖他。他家族中的骨肉之親也可以贖他。他自己若手頭漸漸寬裕，也可以贖回自己。","notes":[]},{"n":50,"t":"他要跟買主計算，從賣自己的那年起，算到禧年；所賣的價錢要按照年數計算，就是雇工跟買主在一起的日子。","notes":[]},{"n":51,"t":"若剩餘的年數多，就要按著年數從買價中償還他的贖價。","notes":[]},{"n":52,"t":"若到禧年只剩下幾年，就要按著年數跟買主計算，償還他的贖價。","notes":[]},{"n":53,"t":"他和買主同住，要像按年雇用的工人，買主不可苛刻管轄他。","notes":[]},{"n":54,"t":"他若不這樣被贖，到了禧年，仍要和他的兒女一同出去。","notes":[]},{"n":55,"t":"因為以色列人都是我的僕人，他們是我的僕人，是我領他們從埃及地出來的。我是耶和華－你們的神。」","notes":[]}]},"26":{"heading":"遵行誡命者蒙福","verses":[{"n":1,"t":"「你們不可為自己造虛無的神明，不可豎立雕刻的偶像或柱像，也不可在你們的地上安放石像，向它跪拜，因為我是耶和華－你們的神。","notes":[]},{"n":2,"t":"你們要謹守我的安息日，敬畏我的聖所。我是耶和華。","notes":[]},{"n":3,"t":"「你們若遵行我的律例，謹守我的誡命，實行它們，","notes":[]},{"n":4,"t":"我必按時降雨給你們，使地長出農作物，田野的樹結出果實。","notes":[]},{"n":5,"t":"你們打穀物要打到摘葡萄的時候，摘葡萄要摘到播種的時候。你們要吃糧食得飽足，在你們的地上安然居住。","notes":[]},{"n":6,"t":"我要賜平安在地上；你們躺臥，無人驚嚇。我要使你們地上的惡獸消滅，刀劍必不穿越你們的地。","notes":[]},{"n":7,"t":"你們要追趕仇敵，他們必倒在你們刀下。","notes":[]},{"n":8,"t":"你們五個人要追趕一百人，一百人要追趕一萬人；仇敵必在你們面前倒在刀下。","notes":[]},{"n":9,"t":"我要眷顧你們，使你們生養眾多，也要與你們堅立我的約。","notes":[]},{"n":10,"t":"你們要吃儲存的陳糧，又要為新糧清理陳糧。","notes":[]},{"n":11,"t":"我要在你們中間立我的帳幕，我的心也不厭惡你們。","notes":[]},{"n":12,"t":"我要行走在你們中間，作你們的神，你們要作我的子民。","notes":[]},{"n":13,"t":"我是耶和華－你們的神，曾將你們從埃及地領出來，使你們不再作埃及人的奴僕；我曾折斷你們所負的軛，使你們挺身前行。」","notes":[]},{"n":14,"t":"「你們若不聽從我，不遵行我這一切的誡命，","notes":[],"heads":["違反誡命者遭禍"]},{"n":15,"t":"厭棄我的律例，心中厭惡我的典章，不遵行我一切的誡命，背棄了我的約，","notes":[]},{"n":16,"t":"我就要這樣對待你們：我必使驚惶臨到你們，使你們患癆病，害熱病，以致眼睛失明，身體衰弱。你們要白白撒種，因為仇敵要吃盡你們所種的。","notes":[]},{"n":17,"t":"我要向你們變臉，使你們敗在仇敵的面前。恨惡你們的必管轄你們；無人追趕，你們卻要逃跑。","notes":[]},{"n":18,"t":"如果這樣，你們還不聽從我，我就要因你們的罪，加重七倍懲罰你們。","notes":[]},{"n":19,"t":"我必粉碎你們因勢力而有的驕傲，又要使你們的天堅如鐵，地硬如銅。","notes":[]},{"n":20,"t":"你們勞力卻白費，因為你們的地沒有出產，地上的樹也不結果實。","notes":[]},{"n":21,"t":"「你們行事若與我作對，不肯聽從我，我就要因你們的罪，加重七倍災禍擊打你們。","notes":[]},{"n":22,"t":"我要打發野地的走獸到你們中間，奪去你們的兒女，吞滅你們的牲畜，使你們人數減少，道路荒涼。","notes":[]},{"n":23,"t":"「如果這樣，你們還不接受管教歸向我，行事與我作對，","notes":[]},{"n":24,"t":"我就要行事與你們作對，因你們的罪，加重七倍擊打你們。","notes":[]},{"n":25,"t":"我要使刀劍臨到你們，報復你們的背約。你們若被趕入城中，我要降瘟疫在你們中間，把你們交在仇敵手中。","notes":[]},{"n":26,"t":"我要斷絕你們糧食的供應，使十個女人用一個烤爐給你們烤餅，按配給的定量秤給你們。你們要吃，卻吃不飽。","notes":["「糧食的供應」：原文直譯「糧食的杖」。"]},{"n":27,"t":"「如果這樣，你們還不聽從我，行事與我作對，","notes":[]},{"n":28,"t":"我就要向你們發烈怒，行事與你們作對，因你們的罪，加重七倍懲罰你們。","notes":[]},{"n":29,"t":"你們要吃你們兒子的肉，也要吃你們女兒的肉。","notes":[]},{"n":30,"t":"我要摧毀你們的丘壇，砍掉你們的香壇，把你們的屍首扔在你們偶像的殘骸上。我的心也必厭惡你們，","notes":[]},{"n":31,"t":"使你們的城鎮變成廢墟，你們的眾聖所變荒涼，我也不聞你們芬芳的香氣。","notes":[]},{"n":32,"t":"我要使這地變荒涼，甚至佔領這地的敵人都驚訝。","notes":[]},{"n":33,"t":"我要把你們驅散到列國中，也要拔刀追趕你們。你們的地要成為荒涼，你們的城鎮要變成廢墟。","notes":[]},{"n":34,"t":"「當你們在敵人之地的時候，你們的地要在一切荒涼的日子重享安息；在那時候，地要休息，重享安息。","notes":[]},{"n":35,"t":"地在一切荒涼的日子都要安息，這是你們住在其上的時候所不能得的安息。","notes":[]},{"n":36,"t":"至於你們倖存的人，我要使他們在敵人之地心中驚慌，甚至風吹落葉的聲音也把他們嚇跑。他們要逃避，像人逃避刀劍，雖無人追趕，卻要跌倒。","notes":[]},{"n":37,"t":"雖然無人追趕，他們卻要彼此絆倒，像逃避刀劍一樣。你們在仇敵面前必站立不住。","notes":[]},{"n":38,"t":"你們要在列國中滅亡，敵人之地要吞滅你們，","notes":[]},{"n":39,"t":"你們倖存的人必因自己的罪孽在敵人之地衰殘，也要因祖先的罪孽衰殘。","notes":[]},{"n":40,"t":"「他們要承認自己的罪孽和祖先的罪孽，就是背叛我，行事與我作對的過犯。","notes":[]},{"n":41,"t":"我也行事與他們作對，把他們遣送到敵人之地。那時，他們未受割禮的心若肯謙卑，也服了罪孽的懲罰，","notes":[]},{"n":42,"t":"我就要記念我與雅各的約，記念我與以撒的約，與亞伯拉罕的約；我也要記念這地。","notes":[]},{"n":43,"t":"地被他們離棄，因他們不在而荒涼的時候，就要重享安息。他們服了罪孽的懲罰，因為他們厭棄我的典章，心中厭惡我的律例。","notes":[]},{"n":44,"t":"雖然如此，當他們在敵人之地時，我卻不厭棄他們，不厭惡他們，將他們全然滅絕，也不背棄我與他們的約，因為我是耶和華－他們的神。","notes":[]},{"n":45,"t":"我要為他們的緣故記念我與他們祖先的約；我在列國眼前曾把他們的祖先從埃及地領出來，為要作他們的神。我是耶和華。」","notes":[]},{"n":46,"t":"這些律例、典章和法度是耶和華在西奈山上藉著摩西與以色列人立的。","notes":[]}]},"27":{"heading":"還願和估價的條例","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人，對他們說：人向耶和華許特別的願，要按照你所估一個人的價錢。","notes":[]},{"n":3,"t":"你所估的是：二十歲到六十歲男的，按照聖所的舍客勒，估價是五十舍客勒銀子。","notes":[]},{"n":4,"t":"若是女的，估價是三十舍客勒。","notes":[]},{"n":5,"t":"五歲到二十歲男的，估價是二十舍客勒，女的十舍客勒。","notes":[]},{"n":6,"t":"一個月到五歲男的，估價是五舍客勒，女的三舍客勒。","notes":[]},{"n":7,"t":"六十歲以上男的，估價是十五舍客勒，女的十舍客勒。","notes":[]},{"n":8,"t":"他若貧窮，不能按照你的估價，就要把他帶到祭司面前，讓祭司為他估價；祭司要按許願者手頭財力所及估價。","notes":[]},{"n":9,"t":"「許願要獻給耶和華的供物若是牲畜，凡這類獻給耶和華的都要成為聖。","notes":[]},{"n":10,"t":"不可更換，也不可用另一隻取代，無論是好的換壞的，或是壞的換好的，都不可。若一定要以牲畜取代牲畜，所許的與所取代的都要成為聖。","notes":[]},{"n":11,"t":"若牲畜不潔淨，不可獻給耶和華為供物，就要把牲畜帶到祭司面前。","notes":[]},{"n":12,"t":"祭司要估價；牲畜是好是壞，祭司怎樣估定，就是你的估價。","notes":[]},{"n":13,"t":"許願者若一定要把牠贖回，就要在你的估價上加五分之一。","notes":[]},{"n":14,"t":"「人將房屋分別為聖，歸給耶和華為聖，祭司就要估價。房屋是好是壞，祭司怎樣估定，就要以他的估價為準。","notes":[]},{"n":15,"t":"將房屋分別為聖的人，若要贖回房屋，必須付你所估定的價錢，再加上五分之一，房屋才可以歸還給他。","notes":[]},{"n":16,"t":"「人若將所繼承的一塊田地分別為聖，歸給耶和華，就要按照這地撒種多少來估價；能撒一賀梅珥大麥種子的，是五十舍客勒銀子。","notes":[]},{"n":17,"t":"他若從禧年起將地分別為聖，就要以你的估價為準。","notes":[]},{"n":18,"t":"倘若他在禧年以後將地分別為聖，祭司就要按照從那時到下一個禧年所剩的年數推算，從你的估價中減掉。","notes":[]},{"n":19,"t":"將地分別為聖的人若要把地贖回，必須付你所估定的價錢，再加上五分之一，地才可以歸還給他。","notes":[]},{"n":20,"t":"他若不贖回那地，或是將地賣給別人，就不能再贖了。","notes":[]},{"n":21,"t":"到了禧年，那田地要從買主手中退還，歸耶和華為聖，和永獻的地一樣，要歸祭司為業。","notes":[]},{"n":22,"t":"若分別為聖歸耶和華的田地不是繼承的，而是買來的，","notes":[]},{"n":23,"t":"祭司就要依照你的估價，推算到禧年。當天，這人要將你所估的歸給耶和華為聖。","notes":[]},{"n":24,"t":"到了禧年，那田地要退還給賣主，就是繼承那地的原主。","notes":[]},{"n":25,"t":"凡你所估的價錢都要按照聖所的舍客勒：二十季拉是一舍客勒。","notes":[]},{"n":26,"t":"「頭生的，就是牲畜中頭生屬耶和華的，人不可再將牠分別為聖，無論是牛是羊都是耶和華的。","notes":[]},{"n":27,"t":"頭生的牲畜若是不潔淨的，就要按照所估定的價錢，再加上五分之一，把牠贖回。若不贖回，就要按照你的估價把牠賣了。","notes":[]},{"n":28,"t":"「但一切永獻作當滅的，就是人從他所有永獻給耶和華作當滅的，無論是人，是牲畜，是他繼承的田地，都不可賣，也不可贖。凡永獻作當滅的都歸耶和華為至聖。","notes":[]},{"n":29,"t":"凡從人中永獻作當滅的都不可贖，必被處死。","notes":[]},{"n":30,"t":"「地上所有的，無論是地上的種子，是樹上的果子，十分之一是耶和華的，是歸耶和華為聖的。","notes":[]},{"n":31,"t":"人若要贖回這十分之一，就要另加五分之一。","notes":[]},{"n":32,"t":"凡牛群羊群中的十分之一，就是一切從牧人杖下經過的，每第十隻要歸耶和華為聖。","notes":[]},{"n":33,"t":"不可追究是好是壞，也不可取代；若一定要取代，所取代的和本來當獻的牲畜都要成為聖，不可贖回。」","notes":[]},{"n":34,"t":"這些是耶和華在西奈山為以色列人所吩咐摩西的命令。","notes":[]}]}},"NUM":{"1":{"heading":"第一次人口普查","verses":[{"n":1,"t":"以色列人出埃及地後第二年二月初一，耶和華在西奈曠野，在會幕中吩咐摩西說：","notes":[]},{"n":2,"t":"「你要按宗族、父家、人名的數目計算以色列全會眾，數點所有的男丁。","notes":[]},{"n":3,"t":"以色列中凡二十歲以上能出去打仗的，你和亞倫要按照他們的隊伍數點。","notes":[]},{"n":4,"t":"每支派要有一個人，就是父家的家長跟你們一起。","notes":[]},{"n":5,"t":"這是幫助你們的人的名字：屬呂便的，示丟珥的兒子以利蓿；","notes":[]},{"n":6,"t":"屬西緬的，蘇利沙代的兒子示路蔑；","notes":[]},{"n":7,"t":"屬猶大的，亞米拿達的兒子拿順；","notes":[]},{"n":8,"t":"屬以薩迦的，蘇押的兒子拿坦業；","notes":[]},{"n":9,"t":"屬西布倫的，希倫的兒子以利押；","notes":[]},{"n":10,"t":"約瑟子孫、屬以法蓮的，亞米忽的兒子以利沙瑪；屬瑪拿西的，比大蓿的兒子迦瑪列；","notes":[]},{"n":11,"t":"屬便雅憫的，基多尼的兒子亞比但；","notes":[]},{"n":12,"t":"屬但的，亞米沙代的兒子亞希以謝；","notes":[]},{"n":13,"t":"屬亞設的，俄蘭的兒子帕結；","notes":[]},{"n":14,"t":"屬迦得的，丟珥的兒子以利雅薩；","notes":[]},{"n":15,"t":"屬拿弗他利的，以南的兒子亞希拉。」","notes":[]},{"n":16,"t":"這些是從會眾中選出來的父系支派的領袖，是以色列部隊的官長。","notes":[]},{"n":17,"t":"於是，摩西和亞倫帶著這些按名指定的人，","notes":[]},{"n":18,"t":"在二月初一召集全會眾。會眾就照他們的宗族、父家、人名的數目，登記二十歲以上的人口。","notes":[]},{"n":19,"t":"耶和華怎樣吩咐摩西，他就照樣在西奈的曠野數點他們。","notes":[]},{"n":20,"t":"以色列的長子，呂便子孫的後代，照著宗族、父家、人名的數目，他們的人口凡二十歲以上能出去打仗的男丁，","notes":[]},{"n":21,"t":"呂便支派被數的共有四萬六千五百名。","notes":[]},{"n":22,"t":"西緬子孫的後代，照著宗族、父家、被數人名的數目，他們的人口凡二十歲以上能出去打仗的男丁，","notes":["有古卷、七十士譯本和其他古譯本沒有「被數」。"]},{"n":23,"t":"西緬支派被數的共有五萬九千三百名。","notes":[]},{"n":24,"t":"迦得子孫的後代，照著宗族、父家、人名的數目，凡二十歲以上能出去打仗的，","notes":[]},{"n":25,"t":"迦得支派被數的共有四萬五千六百五十名。","notes":[]},{"n":26,"t":"猶大子孫的後代，照著宗族、父家、人名的數目，凡二十歲以上能出去打仗的，","notes":[]},{"n":27,"t":"猶大支派被數的共有七萬四千六百名。","notes":[]},{"n":28,"t":"以薩迦子孫的後代，照著宗族、父家、人名的數目，凡二十歲以上能出去打仗的，","notes":[]},{"n":29,"t":"以薩迦支派被數的共有五萬四千四百名。","notes":[]},{"n":30,"t":"西布倫子孫的後代，照著宗族、父家、人名的數目，凡二十歲以上能出去打仗的，","notes":[]},{"n":31,"t":"西布倫支派被數的共有五萬七千四百名。","notes":[]},{"n":32,"t":"約瑟子孫屬以法蓮子孫的後代，照著宗族、父家、人名的數目，凡二十歲以上能出去打仗的，","notes":[]},{"n":33,"t":"以法蓮支派被數的共有四萬零五百名。","notes":[]},{"n":34,"t":"瑪拿西子孫的後代，照著宗族、父家、人名的數目，凡二十歲以上能出去打仗的，","notes":[]},{"n":35,"t":"瑪拿西支派被數的共有三萬二千二百名。","notes":[]},{"n":36,"t":"便雅憫子孫的後代，照著宗族、父家、人名的數目，凡二十歲以上能出去打仗的，","notes":[]},{"n":37,"t":"便雅憫支派被數的共有三萬五千四百名。","notes":[]},{"n":38,"t":"但子孫的後代，照著宗族、父家、人名的數目，凡二十歲以上能出去打仗的，","notes":[]},{"n":39,"t":"但支派被數的共有六萬二千七百名。","notes":[]},{"n":40,"t":"亞設子孫的後代，照著宗族、父家、人名的數目，凡二十歲以上能出去打仗的，","notes":[]},{"n":41,"t":"亞設支派被數的共有四萬一千五百名。","notes":[]},{"n":42,"t":"拿弗他利子孫的後代，照著宗族、父家、人名的數目，凡二十歲以上能出去打仗的，","notes":[]},{"n":43,"t":"拿弗他利支派被數的共有五萬三千四百名。","notes":[]},{"n":44,"t":"這些就是被數點的，是摩西、亞倫和以色列十二個領袖所數點的；每一個領袖代表他們的父家。","notes":[]},{"n":45,"t":"以色列人被數點的總數，以色列中照著父家，凡二十歲以上能出去打仗的，","notes":[]},{"n":46,"t":"他們被數點的總數是六十萬三千五百五十名。","notes":[]},{"n":47,"t":"利未人卻沒有按照父系支派數在其中。","notes":[]},{"n":48,"t":"耶和華吩咐摩西說：","notes":[]},{"n":49,"t":"「惟獨利未支派你不可數點，也不可在以色列人中計算他們的人口。","notes":[]},{"n":50,"t":"你要派利未人管理法櫃的帳幕和其中一切的器具，以及屬帳幕的一切。他們要抬帳幕和其中一切的器具，並要辦理帳幕的事務，在帳幕的四圍安營。","notes":[]},{"n":51,"t":"帳幕將往前行的時候，利未人要拆卸；將駐紮的時候，利未人要支搭帳幕。近前來的外人必被處死。","notes":[]},{"n":52,"t":"以色列人要按照各自的隊伍安營，各歸本營，各歸本旗。","notes":[]},{"n":53,"t":"但利未人要在法櫃帳幕的四圍安營，免得憤怒臨到以色列會眾；利未人要負責看守法櫃的帳幕。」","notes":[]},{"n":54,"t":"以色列人就這樣做了。凡耶和華所吩咐摩西的，他們都照樣做了。","notes":[]}]},"2":{"heading":"安營和行軍的次序","verses":[{"n":1,"t":"耶和華吩咐摩西和亞倫說：","notes":[]},{"n":2,"t":"「以色列人各人要在自己的旗幟下，按照自己父家的旗號安營，對著會幕的四圍安營。","notes":[]},{"n":3,"t":"「在東邊，向日出的方向，猶大營按照他們的隊伍，在它的旗幟下安營。猶大人的領袖是亞米拿達的兒子拿順，","notes":[]},{"n":4,"t":"他的軍隊被數的有七萬四千六百名。","notes":[]},{"n":5,"t":"在他旁邊安營的是以薩迦支派。以薩迦人的領袖是蘇押的兒子拿坦業，","notes":[]},{"n":6,"t":"他的軍隊被數的有五萬四千四百名。","notes":[]},{"n":7,"t":"還有西布倫支派，西布倫人的領袖是希倫的兒子以利押，","notes":[]},{"n":8,"t":"他的軍隊被數的有五萬七千四百名。","notes":[]},{"n":9,"t":"凡屬猶大營，照他們隊伍被數的共有十八萬六千四百名；他們要作第一隊往前行。","notes":[]},{"n":10,"t":"「在南邊，按照他們的隊伍是呂便營的旗幟。呂便人的領袖是示丟珥的兒子以利蓿，","notes":[]},{"n":11,"t":"他的軍隊被數的有四萬六千五百名。","notes":[]},{"n":12,"t":"在他旁邊安營的是西緬支派。西緬人的領袖是蘇利沙代的兒子示路蔑，","notes":[]},{"n":13,"t":"他的軍隊被數的有五萬九千三百名。","notes":[]},{"n":14,"t":"還有迦得支派，迦得人的領袖是丟珥的兒子以利雅薩，","notes":[]},{"n":15,"t":"他的軍隊被數的有四萬五千六百五十名。","notes":[]},{"n":16,"t":"凡屬呂便營，照他們隊伍被數的共有十五萬一千四百五十名；他們要作第二隊往前行。","notes":[]},{"n":17,"t":"「會幕與利未營在諸營中間往前行。他們怎樣安營就怎樣往前行，各按本位，各歸本旗。","notes":[]},{"n":18,"t":"「在西邊，按照他們的隊伍是以法蓮營的旗幟。以法蓮人的領袖是亞米忽的兒子以利沙瑪，","notes":[]},{"n":19,"t":"他的軍隊被數的有四萬零五百名。","notes":[]},{"n":20,"t":"在他旁邊的是瑪拿西支派。瑪拿西人的領袖是比大蓿的兒子迦瑪列，","notes":[]},{"n":21,"t":"他的軍隊被數的有三萬二千二百名。","notes":[]},{"n":22,"t":"還有便雅憫支派，便雅憫人的領袖是基多尼的兒子亞比但，","notes":[]},{"n":23,"t":"他的軍隊被數的有三萬五千四百名。","notes":[]},{"n":24,"t":"凡屬以法蓮營，照他們隊伍被數的共有十萬八千一百名；他們要作第三隊往前行。","notes":[]},{"n":25,"t":"「在北邊，按照他們的隊伍是但營的旗幟。但人的領袖是亞米沙代的兒子亞希以謝，","notes":[]},{"n":26,"t":"他的軍隊被數的有六萬二千七百名。","notes":[]},{"n":27,"t":"在他旁邊安營的是亞設支派。亞設人的領袖是俄蘭的兒子帕結，","notes":[]},{"n":28,"t":"他的軍隊被數的有四萬一千五百名。","notes":[]},{"n":29,"t":"還有拿弗他利支派，拿弗他利人的領袖是以南的兒子亞希拉，","notes":[]},{"n":30,"t":"他的軍隊被數的有五萬三千四百名。","notes":[]},{"n":31,"t":"凡屬但營被數的共有十五萬七千六百名；他們隨著自己的旗幟行在最後。」","notes":[]},{"n":32,"t":"以上是以色列人按照各自的父家被數的，在諸營中按照各自的隊伍被數的，共有六十萬三千五百五十名。","notes":[]},{"n":33,"t":"但利未人沒有數在以色列人中，正如耶和華所吩咐摩西的。","notes":[]},{"n":34,"t":"以色列人就照著耶和華所吩咐摩西的做了，在各自的旗幟下安營，隨著各自的宗族、父家起行。","notes":[]}]},"3":{"heading":"亞倫的兒子","verses":[{"n":1,"t":"耶和華在西奈山與摩西說話的日子，亞倫和摩西的後代如下：","notes":[]},{"n":2,"t":"這些是亞倫兒子的名字，長子拿答，及亞比戶、以利亞撒、以他瑪。","notes":[]},{"n":3,"t":"這些是亞倫兒子的名字，都是受膏的祭司，是摩西授聖職使他們擔任祭司職分的。","notes":[]},{"n":4,"t":"拿答、亞比戶在西奈的曠野向耶和華獻上凡火的時候，死在耶和華面前。他們沒有兒子。以利亞撒和以他瑪在他們的父親亞倫面前擔任祭司的職分。","notes":[]},{"n":5,"t":"耶和華吩咐摩西說：","notes":[],"heads":["利未人的職責"]},{"n":6,"t":"「你要帶利未支派近前來，站在亞倫祭司面前伺候他。","notes":[]},{"n":7,"t":"他們要替他，又替全會眾，在會幕前執行任務，辦理帳幕的事。","notes":[]},{"n":8,"t":"他們要看守會幕一切的器具，為以色列人執行任務，辦理帳幕的事。","notes":[]},{"n":9,"t":"你要把利未人給亞倫和他的兒子；他們是從以色列人中選出來完全給他的。","notes":[]},{"n":10,"t":"你要指派亞倫和他的兒子謹守祭司的職分；近前來的外人必被處死。」","notes":[]},{"n":11,"t":"耶和華吩咐摩西說：","notes":[]},{"n":12,"t":"「看哪，我從以色列人中選了利未人，代替以色列人中所有頭胎的長子；利未人要歸我。","notes":[]},{"n":13,"t":"因為凡頭生的是我的；我在埃及地擊殺所有頭生的那日，就把以色列中所有頭生的，無論是人或牲畜，都分別為聖歸我；他們定要屬我。我是耶和華。」","notes":[]},{"n":14,"t":"耶和華在西奈的曠野吩咐摩西說：","notes":[],"heads":["利未人的人口調查"]},{"n":15,"t":"「你要照父家、宗族計算利未人。凡一個月以上的男子都要數點。」","notes":[]},{"n":16,"t":"於是摩西遵照耶和華的吩咐，按所指示的數點他們。","notes":[]},{"n":17,"t":"利未兒子的名字是革順、哥轄、米拉利。","notes":[]},{"n":18,"t":"按照宗族，革順兒子的名字是立尼、示每。","notes":[]},{"n":19,"t":"按照宗族，哥轄的兒子是暗蘭、以斯哈、希伯倫、烏薛。","notes":[]},{"n":20,"t":"按照宗族，米拉利的兒子是抹利、母示。按照父家，這些都是利未人的宗族。","notes":[]},{"n":21,"t":"屬革順的有立尼族、示每族，他們是革順人的宗族。","notes":[]},{"n":22,"t":"他們被數的，一個月以上所有男子的數目共有七千五百名。","notes":[]},{"n":23,"t":"這革順人的宗族要在西邊，在帳幕後面安營。","notes":[]},{"n":24,"t":"革順人父家的領袖是拉伊勒的兒子以利雅薩。","notes":[]},{"n":25,"t":"革順的子孫在會幕中要看守的是帳幕、罩棚、罩棚的蓋、會幕的門簾、","notes":[]},{"n":26,"t":"帳幕和祭壇周圍院子的帷幔和門簾，以及所有需用的繩子。","notes":[]},{"n":27,"t":"屬哥轄的有暗蘭族、以斯哈族、希伯倫族、烏薛族，他們是哥轄人的宗族。","notes":[]},{"n":28,"t":"一個月以上所有男子的數目共有八千六百名；他們負責看守聖所。","notes":["「八千六百」：七十士譯本的一個抄本是「八千三百」。"]},{"n":29,"t":"哥轄子孫的宗族要在帳幕的南邊安營。","notes":[]},{"n":30,"t":"哥轄人父家宗族的領袖是烏薛的兒子以利撒反。","notes":[]},{"n":31,"t":"他們要看守的是約櫃、供桌、燈臺、祭壇、香壇、祭司在聖所內用的器皿、簾子，與一切相關事奉的物件。","notes":[]},{"n":32,"t":"亞倫祭司的兒子以利亞撒是利未人眾領袖的主管，他要監督那些負責看守聖所的人。","notes":[]},{"n":33,"t":"屬米拉利的有抹利族、母示族，他們是米拉利的宗族。","notes":[]},{"n":34,"t":"他們被數的，一個月以上所有男子的數目共有六千二百名。","notes":[]},{"n":35,"t":"米拉利宗族的領袖是亞比亥的兒子蘇列，他們要在帳幕的北邊安營。","notes":[]},{"n":36,"t":"米拉利子孫的職分是看守帳幕的豎板、橫木、柱子、帶卯眼的座和一切的器具，就是一切相關事奉的物件，","notes":[]},{"n":37,"t":"以及院子四圍的柱子、其上帶卯眼的座、橛子和繩子。","notes":[]},{"n":38,"t":"在帳幕前東邊，向日出的方向，安營的是摩西、亞倫和亞倫的兒子。他們負責看守聖所，是為以色列人看守的。近前來的外人必被處死。","notes":[]},{"n":39,"t":"凡被數的利未人，就是摩西、亞倫照耶和華所指示、按宗族所數的，一個月以上所有的男子共有二萬二千名。","notes":[]},{"n":40,"t":"耶和華對摩西說：「你要數點以色列人中凡一個月以上頭生的男子，登記他們的名字。","notes":[],"heads":["利未人代替長子"]},{"n":41,"t":"我是耶和華。你要揀選利未人歸我，代替所有頭生的以色列人，也取利未人的牲畜代替以色列人所有頭生的牲畜。」","notes":[]},{"n":42,"t":"摩西就遵照耶和華所吩咐的，把所有以色列人頭生的都數點了。","notes":[]},{"n":43,"t":"按人名的數目，凡一個月以上頭生的男子共有二萬二千二百七十三名。","notes":[]},{"n":44,"t":"耶和華吩咐摩西說：","notes":[]},{"n":45,"t":"「你要揀選利未人代替所有頭生的以色列人，也要取利未人的牲畜代替以色列人的牲畜。利未人要歸我，我是耶和華。","notes":[]},{"n":46,"t":"以色列人頭生的男子比利未人多了二百七十三名，必須把他們贖出來；","notes":[]},{"n":47,"t":"按照人丁，照聖所的舍客勒，每人當付五舍客勒，一舍客勒是二十季拉。","notes":[]},{"n":48,"t":"你要把這些多出來的人的贖銀交給亞倫和他的兒子。」","notes":[]},{"n":49,"t":"於是摩西從那被利未人所贖以外多出來的人取了贖銀。","notes":[]},{"n":50,"t":"從頭生的以色列人所取的銀子，按照聖所的舍客勒，共計一千三百六十五舍客勒。","notes":[]},{"n":51,"t":"摩西遵照耶和華指示的話，把贖銀交給亞倫和他的兒子，正如耶和華所吩咐的。","notes":[]}]},"4":{"heading":"哥轄的子孫","verses":[{"n":1,"t":"耶和華吩咐摩西和亞倫說：","notes":[]},{"n":2,"t":"「你要照宗族、父家計算利未人中哥轄子孫的人口，","notes":[]},{"n":3,"t":"就是從三十歲到五十歲，凡前來任職，在會幕裏事奉的人。","notes":[]},{"n":4,"t":"這是哥轄子孫在會幕裏有關至聖之物的職責。","notes":[]},{"n":5,"t":"「拔營的時候，亞倫和他兒子要進去，把遮掩的幔子取下，用它來遮蓋法櫃，","notes":[]},{"n":6,"t":"又用精美皮料蓋在上面，鋪上純藍色的布，再把槓穿上。","notes":[]},{"n":7,"t":"他們要用藍色的布鋪在供餅的桌上，將盤、碟，以及澆酒祭的杯和壺擺在上面；經常供的餅也要留在桌上。","notes":[]},{"n":8,"t":"他們要在這些東西的上面鋪上朱紅色的布，把精美皮料蓋在上面，再把槓穿上。","notes":[]},{"n":9,"t":"他們要用藍色的布遮蓋供職用的燈臺、燈臺上的燈盞、燈剪、燈盤，以及所有盛油的器皿；","notes":[]},{"n":10,"t":"又要用精美皮料把燈臺和燈臺的一切器具包好，放在抬架上。","notes":[]},{"n":11,"t":"他們要用藍色的布鋪在金壇上，用精美皮料蓋在上面，再把槓穿上。","notes":[]},{"n":12,"t":"要用藍色的布把聖所供職用的一切器具包好，再用精美皮料蓋在上面，放在抬架上。","notes":[]},{"n":13,"t":"他們要清理祭壇上的灰，用紫色的布鋪在壇上；","notes":[]},{"n":14,"t":"又要把供職用的一切器具，就是祭壇一切的器具，火盆、肉叉、鏟子和盤子，都擺在壇上，鋪上精美皮料，再把槓穿上。","notes":[]},{"n":15,"t":"「拔營的時候，亞倫和他兒子把聖所和聖所一切的器具蓋好之後，哥轄的子孫才好來抬，免得他們摸聖物而死；這是哥轄子孫在會幕裏所當抬的。","notes":[]},{"n":16,"t":"「祭司亞倫的兒子以利亞撒所要照管的是點燈的油和香料，以及常獻的素祭和膏油。他要照管整個帳幕和其中所有的，以及聖所和聖所的器具。」","notes":[]},{"n":17,"t":"耶和華吩咐摩西和亞倫說：","notes":[]},{"n":18,"t":"「你們不可使哥轄人宗族的這一支從利未人中剪除。","notes":[]},{"n":19,"t":"他們挨近至聖之物的時候，要向他們這樣做，使他們存活，不致死亡；亞倫和他的兒子要進去，分派各人當做的，當抬的。","notes":[]},{"n":20,"t":"但是他們不可進去觀看聖所的拆卸，免得死亡。」","notes":["「觀看聖所的拆卸」：七十士譯本是「觀看聖物片刻」。"]},{"n":21,"t":"耶和華吩咐摩西說：","notes":[],"heads":["革順的子孫"]},{"n":22,"t":"「你要照父家、宗族計算革順子孫的人口；","notes":[]},{"n":23,"t":"從三十歲到五十歲，凡前來任職，在會幕裏事奉的，都要數點。","notes":[]},{"n":24,"t":"這是革順人宗族的職責，要做的事，要抬的東西如下：","notes":[]},{"n":25,"t":"他們要抬帳幕的幔子、會幕和會幕的蓋、外層精美皮料的蓋、會幕的門簾、","notes":[]},{"n":26,"t":"帳幕和祭壇周圍院子的帷幔和門簾、繩子，以及所有需用的器具；一切與這些東西相關的事務，他們要盡職。","notes":[]},{"n":27,"t":"革順人的子孫一切的事奉，就是所當抬的，所當做的，都要遵照亞倫和他兒子的指示；他們所當抬的，你們要派他們負責。","notes":[]},{"n":28,"t":"這是革順人子孫的宗族在會幕裏的事奉；他們要在亞倫祭司的兒子以他瑪的手下盡職。」","notes":[]},{"n":29,"t":"「至於米拉利的子孫，你要照宗族、父家數點他們；","notes":[],"heads":["米拉利的子孫"]},{"n":30,"t":"從三十歲到五十歲，凡前來任職，在會幕裏事奉的，你都要數點。","notes":[]},{"n":31,"t":"這是他們在會幕裏的事奉，他們負責要抬的是帳幕的豎板、橫木、柱子和帶卯眼的座，","notes":[]},{"n":32,"t":"院子四圍的柱子和其上帶卯眼的座、橛子、繩子和一切的器具，與一切相關事奉的物件。你們要按名指定他們要抬的器具。","notes":[]},{"n":33,"t":"這是米拉利子孫的宗族在會幕裏的事奉，都在亞倫祭司的兒子以他瑪的手下。」","notes":[]},{"n":34,"t":"摩西、亞倫和會眾的領袖按照宗族、父家數點哥轄人的子孫；","notes":[],"heads":["利未人男丁的調查"]},{"n":35,"t":"從三十歲到五十歲，凡前來任職，在會幕裏事奉的，","notes":[]},{"n":36,"t":"按照宗族被數的共有二千七百五十名。","notes":[]},{"n":37,"t":"這是所有在會幕裏事奉的哥轄人宗族中被數的，是摩西和亞倫遵照耶和華藉摩西所指示數點的。","notes":[]},{"n":38,"t":"革順子孫被數的，按照宗族、父家，","notes":[]},{"n":39,"t":"從三十歲到五十歲，凡前來任職，在會幕裏事奉的，","notes":[]},{"n":40,"t":"按照宗族、父家被數的共有二千六百三十名。","notes":[]},{"n":41,"t":"這是所有在會幕裏事奉的革順子孫宗族中被數的，是摩西和亞倫遵照耶和華的指示所數點的。","notes":[]},{"n":42,"t":"米拉利子孫宗族被數的，按照宗族、父家，","notes":[]},{"n":43,"t":"從三十歲到五十歲，凡前來任職，在會幕裏事奉的，","notes":[]},{"n":44,"t":"按照宗族被數的共有三千二百名。","notes":[]},{"n":45,"t":"這是米拉利子孫宗族中被數的，是摩西和亞倫遵照耶和華藉摩西所指示數點的。","notes":[]},{"n":46,"t":"摩西、亞倫和以色列領袖按照宗族、父家數點利未人，","notes":[]},{"n":47,"t":"從三十歲到五十歲，凡前來任職，在會幕裏事奉，做抬物之工的，","notes":[]},{"n":48,"t":"他們被數的共有八千五百八十名。","notes":[]},{"n":49,"t":"按照耶和華藉摩西所指示的來分派，各人都有自己所做的事、所抬的物；他們就這樣被數點，正如耶和華所吩咐摩西的。","notes":[]}]},"5":{"heading":"不潔淨的人","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人，把一切患痲瘋的、患漏症的和因屍體而不潔淨的，都送到營外去。","notes":["「痲瘋」泛指傳染性皮膚病。"]},{"n":3,"t":"無論男女你都要送，把他們送到營外，免得他們玷污了他們的營，這是我住在他們中間的地方。」","notes":[]},{"n":4,"t":"以色列人就照樣做，把他們送到營外去。耶和華怎樣吩咐摩西，以色列人就照樣做了。","notes":[]},{"n":5,"t":"耶和華吩咐摩西說：","notes":[],"heads":["認罪和賠償"]},{"n":6,"t":"「你要吩咐以色列人：無論男女，若犯了人所常犯的任何罪，以致干犯耶和華，那人就有了罪。","notes":["「若犯了人所常犯的任何罪」或譯「若犯了任何虧負人的罪」。"]},{"n":7,"t":"他要承認所犯的罪，將所虧負人的如數賠償，另外再加五分之一，交給所虧負的人。","notes":[]},{"n":8,"t":"那人若沒有至親可接受所賠償的，所賠償的就要歸耶和華，交給祭司；另外還要獻一隻贖罪的公羊為他贖罪。","notes":[]},{"n":9,"t":"以色列人一切的聖物中，所奉給祭司的一切禮物都要歸給祭司。","notes":[]},{"n":10,"t":"各人自己的聖物歸自己，給祭司的要歸給祭司。」","notes":[]},{"n":11,"t":"耶和華吩咐摩西說：","notes":[],"heads":["疑妻不貞的案件"]},{"n":12,"t":"「你要吩咐以色列人，對他們說：若任何人的妻子背離婦道，對丈夫不貞，","notes":[]},{"n":13,"t":"有人與她同寢交合，這事瞞過她的丈夫，沒有被發現；她玷污自己，沒有證人指控她，也沒有被捉住；","notes":[]},{"n":14,"t":"丈夫若生了疑忌的心，對妻子起了疑忌，認為她玷污自己；或是丈夫生了疑忌的心，對妻子起了疑忌，雖然她沒有玷污自己，","notes":[]},{"n":15,"t":"這人要帶妻子到祭司那裏，同時為她帶十分之一伊法大麥麵粉作供物。不可澆上油，也不可加乳香，因為這是疑忌的素祭，是紀念的素祭，使人記得罪孽。","notes":[]},{"n":16,"t":"「祭司要使那婦人近前來，站在耶和華面前。","notes":[]},{"n":17,"t":"祭司要把聖水盛在瓦器裏，從帳幕的地上取些塵土，放在水中。","notes":[]},{"n":18,"t":"祭司要帶那婦人站在耶和華面前，使她蓬頭散髮，再把紀念的素祭，就是疑忌的素祭，放在她的手掌，祭司手裏捧著致詛咒的苦水。","notes":[]},{"n":19,"t":"祭司要叫婦人起誓，對她說：『若沒有人與你同寢，若你未曾背著丈夫做污穢的事，你就能免去這致詛咒的苦水。","notes":[]},{"n":20,"t":"但你背著丈夫，玷污自己，跟丈夫以外的人同寢。』","notes":[]},{"n":21,"t":"祭司叫婦人賭咒起誓，祭司對她說：『當耶和華使你大腿萎縮，肚腹腫脹時，願耶和華使你在你百姓中成為詛咒和咒罵；","notes":[]},{"n":22,"t":"願這致詛咒的水進入你體內，使你肚腹腫脹，大腿萎縮。』婦人要說：『阿們，阿們。』","notes":[]},{"n":23,"t":"「祭司要把這詛咒寫在冊上，然後用苦水塗去，","notes":[]},{"n":24,"t":"又叫婦人喝這致詛咒的苦水，這詛咒的水要進入她裏面，令她痛苦。","notes":[]},{"n":25,"t":"祭司要從婦人手中取那疑忌的素祭，把素祭在耶和華面前搖一搖，拿到祭壇前；","notes":[]},{"n":26,"t":"又要從素祭中取出一把，作為紀念，燒在壇上，然後叫婦人喝這水。","notes":[]},{"n":27,"t":"祭司叫她喝了以後，她若玷污自己，確實對丈夫不貞，這致詛咒的水必進入她裏面，令她痛苦，她的肚腹就要腫脹起來，大腿萎縮；這婦人就在她百姓中成為詛咒。","notes":[]},{"n":28,"t":"這婦人若沒有玷污自己，是貞潔的，就要免受這災，並且能夠生育。","notes":[]},{"n":29,"t":"「這是疑忌的條例。妻子背離丈夫玷污自己，","notes":[]},{"n":30,"t":"或是丈夫生了疑忌的心，對妻子起了疑忌，祭司要使那婦人站在耶和華面前，在她身上照這條例而行。","notes":[]},{"n":31,"t":"男人可免罪責；女人必須擔當自己的罪孽。」","notes":[]}]},"6":{"heading":"拿細耳人的條例","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人，對他們說：無論男女，若許了特別的願，就是拿細耳人的願，願意離俗歸耶和華，","notes":[]},{"n":3,"t":"他就要遠離清酒烈酒，也不可喝任何清酒烈酒做的醋；不可喝任何葡萄汁，也不可吃鮮葡萄和乾葡萄。","notes":[]},{"n":4,"t":"在一切離俗的日子，任何葡萄樹上所結的，甚至果核和果皮，都不可吃。","notes":[]},{"n":5,"t":"「在他一切許願離俗的日子，不可用剃刀剃頭。在離俗歸耶和華的日子未滿之前，他要成為聖，要任由頭上的髮綹生長。","notes":[]},{"n":6,"t":"在他一切離俗歸耶和華的日子，不可挨近死屍。","notes":[]},{"n":7,"t":"即使他的父母或兄弟姊妹死了，他也不可因他們使自己不潔淨，因為他頭上有離俗歸神的記號 。","notes":["原文沒有「記號」。"]},{"n":8,"t":"在他一切離俗的日子，他是歸耶和華為聖的。","notes":[]},{"n":9,"t":"「若在他旁邊忽然有人死了，因而玷污了他離俗的頭，他要在第七日，得潔淨的日子剃頭。","notes":[]},{"n":10,"t":"第八日，他要把兩隻斑鳩或兩隻雛鴿帶到會幕門口，交給祭司。","notes":[]},{"n":11,"t":"祭司要獻一隻作贖罪祭，一隻作燔祭，為他贖因屍體而有的罪，並要在當日使他的頭分別為聖。","notes":[]},{"n":12,"t":"他要另選離俗歸耶和華的日子，牽一隻一歲的小公羊來作贖愆祭。先前的那段日子算為無效，因為他在離俗期間被玷污了。","notes":[]},{"n":13,"t":"「拿細耳人的條例是這樣的：離俗的日子滿了，祭司要領他到會幕門口，","notes":[]},{"n":14,"t":"他要將供物獻給耶和華，就是一隻沒有殘疾的一歲小公羊作燔祭，一隻沒有殘疾的一歲小母羊作贖罪祭，和一隻沒有殘疾的公綿羊作平安祭，","notes":[]},{"n":15,"t":"一籃用油調和的無酵細麵餅和抹了油的無酵薄餅，以及同獻的素祭和澆酒祭。","notes":[]},{"n":16,"t":"祭司要來到耶和華面前，獻上那人的贖罪祭和燔祭。","notes":[]},{"n":17,"t":"祭司要把公綿羊和那籃無酵餅獻給耶和華作平安祭，又要獻上同獻的素祭和澆酒祭。","notes":[]},{"n":18,"t":"拿細耳人要在會幕門口剃離俗的頭，把離俗頭上的髮放在平安祭下的火上。","notes":[]},{"n":19,"t":"他剃了離俗的頭以後，祭司要取那煮好的公綿羊的一條前腿，連同籃子裏的一塊無酵餅和一塊無酵薄餅，放在他手掌上。","notes":[]},{"n":20,"t":"祭司要拿這些在耶和華面前搖一搖，作為搖祭；這和所搖的胸、所舉的腿一樣是聖物，是歸給祭司的。然後拿細耳人才可以喝酒。","notes":[]},{"n":21,"t":"「這是拿細耳人許願的條例，除了他手頭財力所及之外，他要為離俗獻供物給耶和華。他怎樣許願，就當照離俗的條例做。」","notes":[]},{"n":22,"t":"耶和華吩咐摩西說：","notes":[],"heads":["祭司的祝福"]},{"n":23,"t":"「你要吩咐亞倫和他兒子說：你們要這樣為以色列人祝福，對他們說：","notes":[]},{"n":24,"t":"『願耶和華賜福給你，保護你。","notes":[]},{"n":25,"t":"願耶和華使他的臉光照你，賜恩給你。","notes":[]},{"n":26,"t":"願耶和華向你仰臉，賜你平安。』","notes":[]},{"n":27,"t":"「他們要如此奉我的名為以色列人祝福；我也要賜福給他們。」","notes":[]}]},"7":{"heading":"各族長的奉獻","verses":[{"n":1,"t":"摩西豎立帳幕後，就用膏抹了帳幕，使它分別為聖，又用膏抹其中的一切器具，以及祭壇和壇上的一切器具，使它們分別為聖。","notes":[]},{"n":2,"t":"以色列的領袖，各父家的家長，都前來奉獻。他們是各支派的領袖，管理那些被數的人。","notes":[]},{"n":3,"t":"他們把自己的供物送到耶和華面前，就是六輛篷車和十二頭公牛。每兩個領袖奉獻一輛車，每個領袖奉獻一頭牛。他們把這些都帶到帳幕前。","notes":[]},{"n":4,"t":"耶和華對摩西說：","notes":[]},{"n":5,"t":"「你要從他們收下這些，作為會幕事奉的用途，照著利未人所事奉的交給他們各人。」","notes":[]},{"n":6,"t":"於是摩西收了車和牛，交給利未人。","notes":[]},{"n":7,"t":"他把兩輛車和四頭牛，照著革順子孫所事奉的交給他們，","notes":[]},{"n":8,"t":"又把四輛車和八頭牛，照著米拉利子孫所事奉的交給他們。他們都在亞倫祭司的兒子以他瑪的手下。","notes":[]},{"n":9,"t":"但沒有交給哥轄子孫任何東西，因為他們所事奉的是聖物，必須抬在肩頭上。","notes":[]},{"n":10,"t":"用膏抹祭壇的那一天，眾領袖前來為獻壇奉獻；眾領袖都在祭壇前獻供物。","notes":[]},{"n":11,"t":"耶和華對摩西說：「眾領袖為獻壇奉獻供物，每天要有一個領袖前來奉獻。」","notes":[]},{"n":12,"t":"第一天獻供物的是猶大支派的亞米拿達的兒子拿順。","notes":[]},{"n":13,"t":"他的供物是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":14,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":15,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":16,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":17,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是亞米拿達的兒子拿順的供物。","notes":[]},{"n":18,"t":"第二天來獻的是以薩迦的領袖，蘇押的兒子拿坦業。","notes":[]},{"n":19,"t":"他獻為供物的是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":20,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":21,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":22,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":23,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是蘇押的兒子拿坦業的供物。","notes":[]},{"n":24,"t":"第三天是西布倫子孫的領袖，希倫的兒子以利押。","notes":[]},{"n":25,"t":"他的供物是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":26,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":27,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":28,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":29,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是希倫的兒子以利押的供物。","notes":[]},{"n":30,"t":"第四天是呂便子孫的領袖，示丟珥的兒子以利蓿。","notes":[]},{"n":31,"t":"他的供物是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":32,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":33,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":34,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":35,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是示丟珥的兒子以利蓿的供物。","notes":[]},{"n":36,"t":"第五天是西緬子孫的領袖，蘇利沙代的兒子示路蔑。","notes":[]},{"n":37,"t":"他的供物是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":38,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":39,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":40,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":41,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是蘇利沙代的兒子示路蔑的供物。","notes":[]},{"n":42,"t":"第六天是迦得子孫的領袖，丟珥的兒子以利雅薩。","notes":[]},{"n":43,"t":"他的供物是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":44,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":45,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":46,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":47,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是丟珥的兒子以利雅薩的供物。","notes":[]},{"n":48,"t":"第七天是以法蓮子孫的領袖，亞米忽的兒子以利沙瑪。","notes":[]},{"n":49,"t":"他的供物是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":50,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":51,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":52,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":53,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是亞米忽的兒子以利沙瑪的供物。","notes":[]},{"n":54,"t":"第八天是瑪拿西子孫的領袖，比大蓿的兒子迦瑪列。","notes":[]},{"n":55,"t":"他的供物是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":56,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":57,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":58,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":59,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是比大蓿的兒子迦瑪列的供物。","notes":[]},{"n":60,"t":"第九天是便雅憫子孫的領袖，基多尼的兒子亞比但。","notes":[]},{"n":61,"t":"他的供物是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":62,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":63,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":64,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":65,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是基多尼的兒子亞比但的供物。","notes":[]},{"n":66,"t":"第十天是但子孫的領袖，亞米沙代的兒子亞希以謝。","notes":[]},{"n":67,"t":"他的供物是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":68,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":69,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":70,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":71,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是亞米沙代的兒子亞希以謝的供物。","notes":[]},{"n":72,"t":"第十一天是亞設子孫的領袖，俄蘭的兒子帕結。","notes":[]},{"n":73,"t":"他的供物是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":74,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":75,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":76,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":77,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是俄蘭的兒子帕結的供物。","notes":[]},{"n":78,"t":"第十二天是拿弗他利子孫的領袖，以南兒子亞希拉。","notes":[]},{"n":79,"t":"他的供物是：一個重一百三十舍客勒的銀盤，一個重七十舍客勒的銀碗，都是按照聖所的舍客勒，裏面盛滿了調油的細麵作素祭；","notes":[]},{"n":80,"t":"一個重十舍客勒的金碟子，盛滿了香；","notes":[]},{"n":81,"t":"一頭公牛犢、一隻公綿羊、一隻一歲的小公羊作燔祭；","notes":[]},{"n":82,"t":"一隻公山羊作贖罪祭；","notes":[]},{"n":83,"t":"兩頭公牛、五隻公綿羊、五隻公山羊、五隻一歲的小公羊作平安祭。這是以南的兒子亞希拉的供物。","notes":[]},{"n":84,"t":"用膏抹祭壇的那一天，以色列的眾領袖為獻壇所獻的是：銀盤十二個、銀碗十二個、金碟子十二個；","notes":[]},{"n":85,"t":"一個銀盤重一百三十，一個碗七十。一切器皿的銀子，按照聖所的舍客勒共二千四百舍客勒。","notes":[]},{"n":86,"t":"十二個金碟子盛滿了香，按照聖所的舍客勒，一個碟子重十舍客勒，所有碟子的金子共一百二十舍客勒。","notes":[]},{"n":87,"t":"作燔祭的共有公牛十二頭、公羊十二隻、一歲的小公羊十二隻，和同獻的素祭，以及作贖罪祭的公山羊十二隻；","notes":[]},{"n":88,"t":"作平安祭的共有公牛二十四頭、公綿羊六十隻、公山羊六十隻、一歲的小公羊六十隻。這就是用膏抹壇之後，為獻壇的奉獻。","notes":[]},{"n":89,"t":"摩西進會幕要與耶和華說話的時候，聽見法櫃的櫃蓋以上二基路伯中間有對他說話的聲音。耶和華向他說話。","notes":[]}]},"8":{"heading":"七盞燈","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐亞倫，對他說：點燈的時候，七盞燈都要照亮燈臺前面。」","notes":[]},{"n":3,"t":"亞倫就照樣做了；他點燈，照亮了燈臺前面，正如耶和華所吩咐摩西的。","notes":[]},{"n":4,"t":"燈臺是這樣造的：燈臺是用金子錘出來的，連座帶花都是錘出來的。摩西照著耶和華所指示的樣式造了燈臺。","notes":[]},{"n":5,"t":"耶和華吩咐摩西說：","notes":[],"heads":["利未人的潔淨禮和奉獻禮"]},{"n":6,"t":"「你要從以色列人中選出利未人來，潔淨他們。","notes":[]},{"n":7,"t":"你要這樣做來潔淨他們：要用潔淨的水彈在他們身上，又叫他們用剃刀剃刮全身，洗淨衣服，潔淨自己。","notes":[]},{"n":8,"t":"然後他們要取一頭公牛犢，以及同獻的素祭，就是調油的細麵。你要另取一頭公牛犢作贖罪祭。","notes":[]},{"n":9,"t":"你要帶利未人到會幕前，並且要召集以色列全會眾。","notes":[]},{"n":10,"t":"你要把利未人帶到耶和華面前，以色列人要為利未人按手。","notes":[]},{"n":11,"t":"亞倫要從以色列人中將利未人奉獻在耶和華面前，作為搖祭，使他們事奉耶和華。","notes":["「奉獻」：原文直譯「搖一搖」；下同。"]},{"n":12,"t":"利未人要按手在那兩頭牛的頭上；你要將一頭作贖罪祭，一頭作燔祭，獻給耶和華，為利未人贖罪。","notes":[]},{"n":13,"t":"你也要使利未人站在亞倫和他兒子面前，將他們奉獻給耶和華，作為搖祭。","notes":[]},{"n":14,"t":"「你從以色列人中將利未人分別出來，利未人就歸我了。","notes":[]},{"n":15,"t":"你潔淨了利未人，奉獻他們作為搖祭之後，他們就可以進會幕事奉。","notes":[]},{"n":16,"t":"因為他們是從以色列人中全然獻給我的；我選他們歸我，代替以色列人中所有頭胎的長子。","notes":[]},{"n":17,"t":"因為以色列人中凡頭生的，無論是人或牲畜，都是我的。我在埃及地擊殺所有頭生的那日，已將他們分別為聖歸我。","notes":[]},{"n":18,"t":"我選利未人代替以色列人中所有頭生的。","notes":[]},{"n":19,"t":"我從以色列人中將利未人給亞倫和他的兒子作為賞賜，在會幕中為以色列人事奉，又為以色列人贖罪，免得以色列人因挨近聖所而遭受災禍。」","notes":[]},{"n":20,"t":"摩西、亞倫和以色列全會眾就向利未人這樣做。關於利未人，凡耶和華怎樣吩咐摩西，以色列人就向他們照樣做了。","notes":[]},{"n":21,"t":"於是利未人從罪中潔淨自己，洗淨衣服。亞倫將他們奉獻在耶和華面前，作為搖祭，又為他們贖罪，潔淨他們。","notes":[]},{"n":22,"t":"然後利未人進去，在亞倫和他兒子面前，在會幕中事奉。關於利未人，耶和華怎樣吩咐摩西，他們就向利未人照樣做了。","notes":[]},{"n":23,"t":"耶和華吩咐摩西說：","notes":[]},{"n":24,"t":"「這是有關利未人的：二十五歲以上的人都要前來任職，在會幕裏事奉。","notes":[]},{"n":25,"t":"到了五十歲，他們就要從事奉的工作中退休，不再事奉，","notes":[]},{"n":26,"t":"只可在會幕裏輔助他們的弟兄盡責，他們自己不再事奉了。關於利未人的職責，你要向他們這樣做。」","notes":[]}]},"9":{"heading":"在西奈山守逾越節","verses":[{"n":1,"t":"以色列人出埃及地以後，第二年正月，耶和華在西奈的曠野吩咐摩西說：","notes":[]},{"n":2,"t":"「以色列人應當在所定的日期守逾越節。","notes":[]},{"n":3,"t":"你們要在本月十四日黃昏的時候，在所定的日期守這節，按照一切的律例典章守節。」","notes":["「黃昏的時候」：原文是「兩個黃昏之間」；下同。"]},{"n":4,"t":"於是摩西吩咐以色列人守逾越節。","notes":[]},{"n":5,"t":"正月十四日黃昏的時候，他們就在西奈的曠野守逾越節。凡耶和華所吩咐摩西的，以色列人都照樣做了。","notes":[]},{"n":6,"t":"有幾個人因屍體成了不潔淨，不能在那日守逾越節。當天他們到摩西、亞倫面前。","notes":[]},{"n":7,"t":"那些人對他說：「我們因屍體而不潔淨，為何禁止我們，不能和以色列人在所定的日期獻供物給耶和華呢？」","notes":[]},{"n":8,"t":"摩西對他們說：「你們稍等，讓我去聽耶和華對你們有甚麼吩咐。」","notes":[]},{"n":9,"t":"耶和華吩咐摩西說：","notes":[]},{"n":10,"t":"「你要吩咐以色列人說：你們和你們後代中，若有人因屍體成了不潔淨，或出外遠行，仍然要向耶和華守逾越節，","notes":[]},{"n":11,"t":"他們就要在二月十四日黃昏的時候守節，要吃羔羊，以及無酵餅和苦菜。","notes":[]},{"n":12,"t":"他們不可留一點食物到早晨；羔羊的骨頭一根也不可折斷。他們要照逾越節的一切律例守這節。","notes":[]},{"n":13,"t":"但潔淨又不出外遠行的人若不守逾越節，那人要從百姓中剪除，因為他沒有在所定的日期獻供物給耶和華，必須擔當自己的罪。","notes":[]},{"n":14,"t":"若有寄居在你們那裏的外人要向耶和華守逾越節，他要照逾越節的律例和典章做。無論是寄居的或是本地人，都用同樣的律例。」","notes":[]},{"n":15,"t":"立起帳幕的那日，有雲彩遮蓋帳幕，就是法櫃的帳幕；從晚上到早晨，雲彩在帳幕上，形狀如火。","notes":[],"heads":["雲彩遮蓋帳幕"]},{"n":16,"t":"經常都是這樣：雲彩遮蓋帳幕，夜間雲彩形狀如火。","notes":[]},{"n":17,"t":"雲彩幾時從帳幕上升，以色列人就幾時起行；雲彩在哪裏停住，以色列人就在哪裏安營。","notes":[]},{"n":18,"t":"以色列人遵照耶和華的指示起行，也遵照耶和華的指示安營。雲彩在帳幕上停留多久，他們就留在營裏多久。","notes":[]},{"n":19,"t":"雲彩在帳幕上停留許多日子，以色列人就遵照耶和華的吩咐不起行。","notes":[]},{"n":20,"t":"有時雲彩在帳幕上只停了幾天，他們就遵照耶和華的指示留在營裏，也遵照耶和華的指示起行。","notes":[]},{"n":21,"t":"有時雲彩從晚上留到早晨；早晨雲彩上升，他們就起行。無論是白天是黑夜，當雲彩上升的時候，他們就要起行。","notes":[]},{"n":22,"t":"雲彩停留在帳幕上，無論是兩天，一個月，或更長的日子，以色列人就留在營裏不起行；但雲彩一上升，他們就起行。","notes":[]},{"n":23,"t":"他們遵照耶和華的指示安營，也遵照耶和華的指示起行。他們遵守耶和華的吩咐，是耶和華藉摩西所指示的話。","notes":[]}]},"10":{"heading":"銀號筒","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要用銀子做兩枝號筒，把它們錘出來，給你用來召集會眾，拔營起行。","notes":[]},{"n":3,"t":"吹號的時候，全會眾要到你那裏，聚集在會幕的門口。","notes":[]},{"n":4,"t":"若只吹一枝，眾領袖，就是以色列部隊的官長，要到你那裏聚集。","notes":[]},{"n":5,"t":"你們大聲吹號的時候，東邊安營的要起行。","notes":[]},{"n":6,"t":"第二次大聲吹號的時候，南邊安營的要起行。起行的時候，要大聲吹號；","notes":[]},{"n":7,"t":"但召集會眾的時候，你們要吹號，卻不要吹出大聲。","notes":[]},{"n":8,"t":"亞倫子孫作祭司的要吹這號筒，作為你們世世代代永遠的定例。","notes":[]},{"n":9,"t":"當你們在自己的土地上，與欺壓你們的敵人打仗時，要用號筒吹出大聲。你們就在耶和華－你們的神面前得蒙記念，也必蒙拯救脫離仇敵。","notes":[]},{"n":10,"t":"在快樂的日子，節期和初一，獻燔祭與平安祭的時候，你們要吹號筒，在你們的神面前作為紀念。我是耶和華－你們的神。」","notes":[]},{"n":11,"t":"第二年二月二十日，雲彩從法櫃的帳幕上升。","notes":[],"heads":["離開西奈山"]},{"n":12,"t":"以色列人離開西奈的曠野，一段一段地往前行，雲彩停在巴蘭的曠野。","notes":[]},{"n":13,"t":"他們遵照耶和華藉摩西所指示的，初次往前行。","notes":[]},{"n":14,"t":"按照隊伍首先起行的是猶大營旗幟下的人，帶隊的是亞米拿達的兒子拿順。","notes":[]},{"n":15,"t":"以薩迦支派帶隊的是蘇押的兒子拿坦業。","notes":[]},{"n":16,"t":"西布倫支派帶隊的是希倫的兒子以利押。","notes":[]},{"n":17,"t":"帳幕拆卸了，革順的子孫和米拉利的子孫就抬著帳幕往前行。","notes":[]},{"n":18,"t":"按照隊伍往前行的是呂便營旗幟下的人，帶隊的是示丟珥的兒子以利蓿。","notes":[]},{"n":19,"t":"西緬支派帶隊的是蘇利沙代的兒子示路蔑。","notes":[]},{"n":20,"t":"迦得支派帶隊的是丟珥的兒子以利雅薩。","notes":[]},{"n":21,"t":"哥轄人抬著聖物往前行。他們未到以前，帳幕已經立好了。","notes":[]},{"n":22,"t":"按照隊伍往前行的是以法蓮營旗幟下的人，帶隊的是亞米忽的兒子以利沙瑪。","notes":[]},{"n":23,"t":"瑪拿西支派帶隊的是比大蓿的兒子迦瑪列。","notes":[]},{"n":24,"t":"便雅憫支派帶隊的是基多尼的兒子亞比但。","notes":[]},{"n":25,"t":"作全營後衛，按隊伍往前行的是但營旗幟下的人，帶隊的是亞米沙代的兒子亞希以謝。","notes":[]},{"n":26,"t":"亞設支派帶隊的是俄蘭的兒子帕結。","notes":[]},{"n":27,"t":"拿弗他利支派帶隊的是以南的兒子亞希拉。","notes":[]},{"n":28,"t":"以色列人就這樣按著隊伍往前行。","notes":[]},{"n":29,"t":"摩西對他岳父米甸人流珥的兒子何巴說：「我們要往前行，到耶和華所說的地方；他曾說：『我要將這地賜給你們。』現在請你和我們同去，我們必善待你，因為耶和華已經應許賜福氣給以色列人。」","notes":["「岳父」或譯「內兄」。"]},{"n":30,"t":"何巴對他說：「我不去，我要回本地本族去。」","notes":[]},{"n":31,"t":"摩西說：「請你不要離開我們，因為你知道我們要在曠野安營，你可以當我們的眼目。","notes":[]},{"n":32,"t":"你若和我們同去，將來耶和華以甚麼福氣恩待我們，我們也必這樣善待你。」","notes":[]},{"n":33,"t":"以色列人離開耶和華的山，往前行了三天的路程。耶和華的約櫃在前面行了三天的路程，為他們尋找安歇的地方。","notes":[],"heads":["約櫃和百姓往前行"]},{"n":34,"t":"他們拔營往前行，日間有耶和華的雲彩在他們上面。","notes":[]},{"n":35,"t":"約櫃往前行的時候，摩西說：「耶和華啊，求你興起！願你的仇敵潰散！願恨你的人從你面前逃跑！」","notes":[]},{"n":36,"t":"約櫃停住的時候，他說：「以色列千萬人的耶和華啊，求你回來！」","notes":["「以色列...回來」或譯「耶和華啊，求你回到以色列的千萬人中」。"]}]},"11":{"heading":"在曠野發怨言","verses":[{"n":1,"t":"百姓發怨言，惡言傳達到耶和華的耳中。耶和華聽見了就怒氣發作，耶和華的火在他們中間焚燒，燒燬營的外圍。","notes":[]},{"n":2,"t":"百姓向摩西哀求，摩西祈求耶和華，火就熄了。","notes":[]},{"n":3,"t":"那地方就叫做他備拉，因為耶和華的火曾在他們中間焚燒。","notes":[]},{"n":4,"t":"他們中間的閒雜人動了貪慾的心；以色列人又再哭著說：「誰給我們肉吃呢？","notes":[]},{"n":5,"t":"我們記得在埃及的時候，不花錢就可以吃魚，還有黃瓜、西瓜、韭菜、蔥、蒜。","notes":[]},{"n":6,"t":"現在我們的精力枯乾了。除了這嗎哪以外，在我們眼前甚麼都沒有。」","notes":[]},{"n":7,"t":"嗎哪好像芫荽子，看上去如同樹脂的樣子。","notes":[]},{"n":8,"t":"百姓四處走動撿取嗎哪，把它用磨磨碎或用臼搗成粉，在鍋中煮了做成餅，滋味好像油烤餅的滋味。","notes":[]},{"n":9,"t":"夜間露水降在營中，嗎哪也隨著降下。","notes":[]},{"n":10,"t":"摩西聽見百姓家家戶戶在帳棚門口哀哭。因此， 耶和華的怒氣大大發作，摩西看了也不高興。","notes":[]},{"n":11,"t":"摩西對耶和華說：「你為何苦待僕人？我為何不在你眼前蒙恩，竟把這眾百姓的擔子加在我身上呢？","notes":[]},{"n":12,"t":"這眾百姓豈是我懷的胎，豈是我生下來的呢？你竟對我說：『把他們抱在懷裏，如養育之父抱著吃奶的嬰孩，一直抱到你起誓應許給他們祖宗的土地去。』","notes":[]},{"n":13,"t":"我從哪裏拿肉給這眾百姓吃呢？他們都向我哭著說：『給我們肉吃！』","notes":[]},{"n":14,"t":"我不能獨自帶領這眾百姓，這對我太沉重了。","notes":[]},{"n":15,"t":"如果你這樣待我，倒不如立刻把我殺了吧！我若在你眼前蒙恩，求你不要讓我再受這樣的苦。」","notes":[]},{"n":16,"t":"耶和華對摩西說：「你要從以色列的長老中為我召集七十個人，就是你所認識，作百姓的長老和官長的，領他們到會幕，使他們和你一同站在那裏。","notes":[],"heads":["七十個長老"]},{"n":17,"t":"我要在那裏降臨，與你說話，把降給你的靈分給他們。他們就和你分擔帶領百姓的擔子，免得你獨自承擔。","notes":[]},{"n":18,"t":"你要對百姓說：『你們要為了明天使自己分別為聖，你們將有肉吃。因你們哭著說：誰給我們肉吃呢？我們在埃及多麼好！這聲音傳到了耶和華的耳中，所以他必給你們肉吃。","notes":[]},{"n":19,"t":"你們不只吃一天、兩天、五天、十天、二十天，","notes":[]},{"n":20,"t":"而是整整一個月，直到肉從你們的鼻孔噴出來，使你們厭惡。因為你們厭棄那住在你們中間的耶和華，在他面前哭著說：我們為何出埃及呢？』」","notes":[]},{"n":21,"t":"摩西說：「跟我在一起的百姓，步行的男人就有六十萬，你還說：『我要把肉賜給他們，使他們可以整整吃一個月。』","notes":[]},{"n":22,"t":"難道宰了羊群牛群，就夠給他們嗎？或者把海中所有的魚都捕來，就夠給他們嗎？」","notes":[]},{"n":23,"t":"耶和華對摩西說：「耶和華的膀臂豈是縮短了嗎？現在你要看我的話向你應驗不應驗。」","notes":["「膀臂」：原文是「手」。"]},{"n":24,"t":"摩西出去，把耶和華的話告訴百姓，並從百姓的長老中召集七十個人來，叫他們站在會幕的四圍。","notes":[]},{"n":25,"t":"耶和華在雲中降臨，對摩西說話，把降給他的靈分給那七十個長老。靈停在他們身上的時候，他們就說預言，以後卻沒有再說了。","notes":[]},{"n":26,"t":"但有兩個人仍在營裏，一個名叫伊利達，一個名叫米達。他們本是在那些登記的人中，卻沒有到會幕那裏去。靈停在他們身上，他們就在營裏說預言。","notes":[]},{"n":27,"t":"有一個年輕人跑來告訴摩西說：「伊利達和米達在營裏說預言。」","notes":[]},{"n":28,"t":"嫩的兒子約書亞，年輕時就作摩西的助手，說：「請我主摩西禁止他們。」","notes":["「年輕時...助手」：七十士譯本是「被選輔助摩西的那人」。"]},{"n":29,"t":"摩西對他說：「你為我的緣故嫉妒嗎？惟願耶和華的百姓都是先知，願耶和華把他的靈降在他們身上！」","notes":[]},{"n":30,"t":"於是，摩西回到營裏去，以色列的長老也回去了。","notes":[]},{"n":31,"t":"有一陣風從耶和華那裏颳起，把鵪鶉從海上颳來，散落在營地和周圍；一邊約有一天的路程，另一邊也約有一天的路程，離地面約有二肘。","notes":[],"heads":["鵪鶉"]},{"n":32,"t":"百姓起來，整天整夜，甚至次日一整天，都在捕捉鵪鶉。每人至少捉到十賀梅珥，各自擺在營的四圍。","notes":[]},{"n":33,"t":"但肉在他們牙間還未咀嚼時，耶和華的怒氣向百姓發作，用極重的災禍擊殺百姓。","notes":[]},{"n":34,"t":"那地方就叫基博羅‧哈他瓦 ，因為他們在那裏埋葬了貪慾的百姓。","notes":["「基博羅‧哈他瓦」意思是「貪慾之人的墳墓」。"]},{"n":35,"t":"百姓從基博羅‧哈他瓦起程，到哈洗錄，就住在哈洗錄。","notes":[]}]},"12":{"heading":"米利暗和亞倫批評摩西","verses":[{"n":1,"t":"摩西娶了古實女子為妻。米利暗和亞倫因他娶了古實女子就批評他，","notes":[]},{"n":2,"t":"他們說：「難道耶和華只與摩西說話嗎？他不也與我們說話嗎？」耶和華聽見了。","notes":[]},{"n":3,"t":"摩西為人極其謙和，勝過地面上的任何人。","notes":[]},{"n":4,"t":"忽然，耶和華對摩西、亞倫和米利暗說：「你們三個人都出來，到會幕這裏。」他們三個人就出來了。","notes":[]},{"n":5,"t":"耶和華在雲柱中降臨，停在會幕門口，叫亞倫和米利暗。二人就出來，","notes":[]},{"n":6,"t":"耶和華說：「你們要聽我的話：你們中間若有先知，我－耶和華必在異象中向他顯現，在夢中與他說話；","notes":[]},{"n":7,"t":"但我的僕人摩西不是這樣，他在我全家是盡忠的。","notes":[]},{"n":8,"t":"我與他面對面說話，清清楚楚，不用謎語，他甚至看見我的形像。你們為何批評我的僕人摩西而不懼怕呢？」","notes":[]},{"n":9,"t":"耶和華向他們怒氣發作，就離開了。","notes":[]},{"n":10,"t":"當雲彩從帳幕上離開時，看哪，米利暗長了痲瘋，像雪那麼白。亞倫轉向米利暗，看哪，她長了痲瘋。","notes":[]},{"n":11,"t":"亞倫對摩西說：「我主啊，求你不要因我們愚昧，因我們犯罪，就將這罪加在我們身上。","notes":[]},{"n":12,"t":"求你不要使她像那一出母腹、肉已侵蝕了一半的死胎。」","notes":[]},{"n":13,"t":"於是摩西哀求耶和華說：「神啊，求你醫治她！」","notes":[]},{"n":14,"t":"耶和華對摩西說：「她父親若吐唾沫在她臉上，她豈不蒙羞七天嗎？現在要把她隔離在營外七天，然後才領她回來。」","notes":[]},{"n":15,"t":"於是米利暗被隔離在營外七天；百姓沒有起程，直等到米利暗回來。","notes":[]},{"n":16,"t":"以後百姓從哈洗錄起行，來到巴蘭的曠野安營。","notes":[]}]},"13":{"heading":"派遣探子進迦南","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要派人去窺探我所賜給以色列人的迦南地；每個父系支派要派一個人，是他們中間的族長。」","notes":[]},{"n":3,"t":"摩西就遵照耶和華的指示，從巴蘭曠野差派他們去；他們都是以色列人中的領袖。","notes":[]},{"n":4,"t":"這是他們的名字：屬呂便支派的，撒刻的兒子沙母亞。","notes":[]},{"n":5,"t":"屬西緬支派的，何利的兒子沙法。","notes":[]},{"n":6,"t":"屬猶大支派的，耶孚尼的兒子迦勒。","notes":[]},{"n":7,"t":"屬以薩迦支派的，約色的兒子以迦。","notes":[]},{"n":8,"t":"屬以法蓮支派的，嫩的兒子何西阿。","notes":["「何西阿」和何西阿先知同名；下同。"]},{"n":9,"t":"屬便雅憫支派的，拉孚的兒子帕提。","notes":[]},{"n":10,"t":"屬西布倫支派的，梭底的兒子迦疊。","notes":[]},{"n":11,"t":"屬約瑟支派，就是瑪拿西支派的，穌西的兒子迦底。","notes":[]},{"n":12,"t":"屬但支派的，基瑪利的兒子亞米利。","notes":[]},{"n":13,"t":"屬亞設支派的，米迦勒的兒子西帖。","notes":[]},{"n":14,"t":"屬拿弗他利支派的，縛西的兒子拿比。","notes":[]},{"n":15,"t":"屬迦得支派的，瑪基的兒子臼利。","notes":[]},{"n":16,"t":"這些是摩西差派去窺探那地之人的名字。摩西叫嫩的兒子何西阿為約書亞。","notes":[]},{"n":17,"t":"摩西差派他們去窺探迦南地，對他們說：「你們上到尼革夫那裏，上到山區去，","notes":["「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」；本卷書下同。"]},{"n":18,"t":"看看那地如何：住那裏的百姓是強是弱，是多是少，","notes":[]},{"n":19,"t":"他們所住的地是好是壞，所住的城鎮是營地還是堡壘，","notes":[]},{"n":20,"t":"那地是肥沃還是貧瘠，當中有樹木沒有。你們要放膽，把那地的果子帶些回來。」那時正是葡萄初熟的季節。","notes":[]},{"n":21,"t":"他們上去窺探那地，從尋的曠野到利合，直到哈馬口。","notes":[]},{"n":22,"t":"他們從尼革夫上去，到了希伯崙。在那裏有亞衲族的亞希幔人、示篩人和撻買人。希伯崙的建造比埃及的瑣安早七年。","notes":[]},{"n":23,"t":"他們到了以實各谷，從那裏砍下葡萄樹枝，上面有一掛葡萄，兩個人用槓抬著，又帶了一些石榴和無花果。","notes":[]},{"n":24,"t":"以色列人從那裏砍下一掛葡萄，所以那地方就叫以實各谷。","notes":[]},{"n":25,"t":"他們窺探那地四十天之後，就回來了。","notes":[],"heads":["探子的報告"]},{"n":26,"t":"他們來到巴蘭曠野的加低斯，摩西、亞倫，以及以色列全會眾那裏，向他們和全會眾報告，又把那地的果子給他們看。","notes":[]},{"n":27,"t":"他們告訴摩西說：「我們到了你派我們去的那地，果然是流奶與蜜之地；這就是那地的果子。","notes":[]},{"n":28,"t":"但是住那地的百姓很強悍，城鎮又大又堅固，我們也在那裏看見了亞衲族人。","notes":[]},{"n":29,"t":"亞瑪力人住在尼革夫；赫人、耶布斯人和亞摩利人住在山區；迦南人住在沿海一帶和約旦河旁。」","notes":[]},{"n":30,"t":"迦勒在摩西面前安撫百姓，說：「我們立刻上去得那地吧！我們必能征服它。」","notes":[]},{"n":31,"t":"但那些和他同去的人卻說：「我們不能上去攻打那些百姓，因為他們比我們強大。」","notes":[]},{"n":32,"t":"於是探子中有人向以色列人散佈有關所窺探之地的謠言，說：「我們所走過、所窺探之地是吞沒居民之地，並且我們在那裏所看見的百姓都身材高大。","notes":[]},{"n":33,"t":"我們在那裏看見巨人，就是巨人中的亞衲族人。我們在自己眼中像蚱蜢一樣，而在他們眼中，我們也確是這樣。」","notes":[]}]},"14":{"heading":"以色列人抱怨","verses":[{"n":1,"t":"全會眾大聲喧嚷，那夜百姓哭號。","notes":[]},{"n":2,"t":"以色列眾人向摩西和亞倫發怨言，全會眾對他們說：「我們寧願死在埃及地，寧願死在這曠野！","notes":[]},{"n":3,"t":"耶和華為甚麼要把我們領到那地，讓我們倒在刀下呢？我們的妻子和孩子必成為擄物。我們回埃及去豈不更好嗎？」","notes":[]},{"n":4,"t":"他們彼此說：「我們不如選一個領袖，回埃及去吧！」","notes":[]},{"n":5,"t":"摩西和亞倫在以色列全會眾面前臉伏於地。","notes":[]},{"n":6,"t":"窺探那地的人中，嫩的兒子約書亞和耶孚尼的兒子迦勒撕裂衣服，","notes":[]},{"n":7,"t":"對以色列全會眾說：「我們所走過、所窺探之地是極美之地。","notes":[]},{"n":8,"t":"耶和華若喜愛我們，就必領我們進入那地，把這流奶與蜜之地賜給我們。","notes":[]},{"n":9,"t":"但你們不可背叛耶和華，也不要怕那地的百姓，因為他們是我們的食物。保護他們的已經離開他們，耶和華卻與我們同在。不要怕他們！」","notes":[]},{"n":10,"t":"當全會眾正說著要拿石頭打死他們的時候，耶和華的榮光在會幕中向以色列眾人顯現。","notes":[]},{"n":11,"t":"耶和華對摩西說：「這百姓藐視我要到幾時呢？我在他們中間行了這一切神蹟，他們還不信我要到幾時呢？","notes":[],"heads":["摩西為以色列人禱告"]},{"n":12,"t":"我要用瘟疫擊殺他們，使他們不得承受那地。我要使你成為大國，比他們強大。」","notes":[]},{"n":13,"t":"摩西對耶和華說：「埃及人必聽見，因你曾施展大能，領這百姓從他們中間出來。","notes":[]},{"n":14,"t":"埃及人要告訴這地的居民，他們已經聽見你─耶和華是在這百姓中間，因為你─耶和華面對面顯示自己，你的雲彩停在他們以上。你日間在雲柱中，夜間在火柱中，在他們的前面行。","notes":["「面對面」：原文是「眼對眼」。"]},{"n":15,"t":"你若把這百姓殺了，好像殺一個人那樣，那聽見你名聲的列國必說：","notes":[]},{"n":16,"t":"『耶和華因為不能把這百姓領進他向他們起誓應許之地，所以在曠野把他們殺了。』","notes":[]},{"n":17,"t":"現在求主顯出大能，照你說過的話說：","notes":[]},{"n":18,"t":"『耶和華不輕易發怒，且有豐盛的慈愛。他赦免罪孽和過犯，萬不以有罪的為無罪，必懲罰人的罪，從父到子，直到三、四代。』","notes":[]},{"n":19,"t":"求你照你的大慈愛赦免這百姓的罪孽，好像你從埃及到如今饒恕這百姓一樣。」","notes":[]},{"n":20,"t":"耶和華說：「我照著你的話赦免他們。","notes":[]},{"n":21,"t":"然而，我指著我的永生與遍地充滿了耶和華的榮耀起誓：","notes":[]},{"n":22,"t":"這些人雖然都看過我的榮耀和我在埃及與曠野所行的神蹟，仍然這十次試探我，不聽從我的話，","notes":[]},{"n":23,"t":"他們絕不能看見我向他們祖宗所起誓應許之地；凡藐視我的，一個也不得看見。","notes":[]},{"n":24,"t":"惟獨我的僕人迦勒，因他另有一個心志，專心跟從我，我要領他進入他所去過的那地；他的後裔必得那地為業。","notes":[]},{"n":25,"t":"亞瑪力人和迦南人住在谷中，明天你們要轉回去，沿著紅海的路往曠野去。」","notes":["「紅海」是根據七十士譯本，原文是「蘆葦海」；本卷書下同。"]},{"n":26,"t":"耶和華對摩西和亞倫說：","notes":[],"heads":["以色列人受懲罰"]},{"n":27,"t":"「這邪惡的會眾向我發怨言要到幾時呢？以色列人向我發的怨言，我都聽見了。","notes":[]},{"n":28,"t":"你要告訴他們，耶和華說：『我指著我的永生起誓，我必照你們在我耳中所說的待你們。","notes":[]},{"n":29,"t":"你們的屍體必倒在這曠野中。你們中間被數點，凡二十歲以上向我發怨言的，","notes":[]},{"n":30,"t":"必不得進我所起誓應許給你們居住的那地。惟有耶孚尼的兒子迦勒和嫩的兒子約書亞才能進去。","notes":[]},{"n":31,"t":"你們的孩子，就是你們說要成為擄物的，我必領他們進去，他們就得知你們所厭棄的那地。","notes":[]},{"n":32,"t":"至於你們，你們的屍體必倒在這曠野中；","notes":[]},{"n":33,"t":"你們的兒女必在曠野遊牧四十年，擔當你們不信的罪，直到你們的屍體在曠野消滅為止。","notes":["「不信的罪」：原文是「淫行」。"]},{"n":34,"t":"按你們窺探那地的四十日，一年抵一日，你們要擔當你們的罪孽四十年，你們就知道我疏遠你們了。』","notes":[]},{"n":35,"t":"我－耶和華說過，我必這樣對待這一切聚集對抗我的邪惡會眾。他們必在這曠野中消滅，死在這裏。」","notes":[]},{"n":36,"t":"摩西所差派去窺探那地的人回來，散佈有關那地的謠言，使全會眾向摩西發怨言，","notes":[]},{"n":37,"t":"這些散佈謠言的人都遭受瘟疫，死在耶和華面前。","notes":[]},{"n":38,"t":"窺探那地的人中，惟有嫩的兒子約書亞和耶孚尼的兒子迦勒得以存活。","notes":[]},{"n":39,"t":"摩西把這些話告訴以色列眾人，他們都極其悲哀。","notes":[],"heads":["進攻迦南卻被擊退"]},{"n":40,"t":"他們清晨起來，上到山頂，說：「看哪，我們要上到耶和華所說的地方；因為我們犯了罪。」","notes":[]},{"n":41,"t":"摩西說：「你們為何要這樣違背耶和華的指示呢？這事必不能順利。","notes":[]},{"n":42,"t":"不要上去，因為耶和華不在你們中間，恐怕你們在仇敵面前被擊敗。","notes":[]},{"n":43,"t":"亞瑪力人和迦南人都在你們面前，你們必倒在刀下。因為你們背離不跟從耶和華，耶和華必不與你們同在。」","notes":[]},{"n":44,"t":"他們卻擅自上到山頂。但耶和華的約櫃和摩西都沒有離開營地。","notes":[]},{"n":45,"t":"於是亞瑪力人和住在那山區的迦南人下來，擊敗他們，追擊他們直到何珥瑪。","notes":[]}]},"15":{"heading":"獻祭的條例","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人，對他們說：你們到了我所賜給你們居住的地，","notes":[]},{"n":3,"t":"你們要從牛群羊群中取牲畜獻給耶和華為火祭，無論是燔祭或祭物，為要還所許特別的願或甘心祭，或節期的祭，作為獻給耶和華的馨香之祭，","notes":[]},{"n":4,"t":"那獻供物的要將十分之一伊法細麵和四分之一欣油調和作素祭，獻給耶和華。","notes":[]},{"n":5,"t":"無論是燔祭或祭物，要為每隻小綿羊預備四分之一欣酒作澆酒祭。","notes":[]},{"n":6,"t":"要為每隻公綿羊預備十分之二伊法細麵，和三分之一欣油調和作素祭，","notes":[]},{"n":7,"t":"又用三分之一欣酒作澆酒祭，獻給耶和華為馨香之祭。","notes":[]},{"n":8,"t":"你預備公牛獻給耶和華作燔祭或祭物，為要還所許特別的願，或平安祭，","notes":[]},{"n":9,"t":"就要把十分之三伊法細麵和半欣油調和作素祭，和公牛一同獻上，","notes":[]},{"n":10,"t":"又用半欣酒作澆酒祭，獻給耶和華為馨香的火祭。","notes":[]},{"n":11,"t":"「獻公牛、或公綿羊、或小綿羊、或小山羊，每隻都要這樣處理；","notes":[]},{"n":12,"t":"無論你們所獻的數目多少，照著數目每隻都要這樣處理。","notes":[]},{"n":13,"t":"凡本地人將馨香的火祭獻給耶和華，都要照樣處理。","notes":[]},{"n":14,"t":"若有外人寄居在你們那裏，或有人世世代代住在你們中間，願意將馨香的火祭獻給耶和華，你們怎樣處理，他也要照樣處理。","notes":[]},{"n":15,"t":"至於會眾，無論是你們或寄居的外人都要遵守同一條例；這是你們世世代代永遠的定例。在耶和華面前，你們怎樣，寄居的也要怎樣。","notes":[]},{"n":16,"t":"你們和寄居在你們那裏的外人要遵守同一律法，同一典章。」","notes":[]},{"n":17,"t":"耶和華吩咐摩西說：","notes":[]},{"n":18,"t":"「你要吩咐以色列人，對他們說：你們到了我領你們進去的那地，","notes":[]},{"n":19,"t":"吃那地的糧食時，要把舉祭獻給耶和華。","notes":[]},{"n":20,"t":"你們要用初熟的麥子磨麵，做成餅當舉祭獻上。你們要舉上，如同舉禾場的舉祭。","notes":[]},{"n":21,"t":"你們世世代代要用初熟的麥子磨麵，當舉祭獻給耶和華。","notes":[]},{"n":22,"t":"「你們若犯了錯，不遵守耶和華所吩咐摩西的這一切命令，","notes":[]},{"n":23,"t":"就是耶和華藉摩西一切所命令你們的，從耶和華命令的那日直到你們的世世代代，","notes":[]},{"n":24,"t":"會眾因沒有察覺而犯了無心之過，全會眾就要將一頭公牛犢作燔祭，遵照典章把素祭和澆酒祭一同獻給耶和華為馨香的祭，又要獻一隻公山羊作贖罪祭。","notes":[]},{"n":25,"t":"祭司要為以色列全會眾贖罪，他們就必蒙赦免，因為這是無心之過。他們要因自己的無心之過，把供物，就是向耶和華當獻的火祭和贖罪祭，帶到耶和華面前。","notes":[]},{"n":26,"t":"以色列全會眾和寄居在他們中間的外人就必蒙赦免，因為這是眾百姓的無心之過。","notes":[]},{"n":27,"t":"「若有一個人無意中犯了罪，他就要獻一隻一歲的母山羊作贖罪祭。","notes":[]},{"n":28,"t":"這誤犯罪的人因無意中犯了罪，祭司要在耶和華面前為他贖罪，他就必蒙赦免。","notes":[]},{"n":29,"t":"以色列中的本地人和寄居在他們中間的外人，若無意中犯了罪，都要遵守同一律法。","notes":[]},{"n":30,"t":"但那故意犯罪的人，無論是本地人是寄居的，褻瀆了耶和華，這人必從百姓中剪除。","notes":[]},{"n":31,"t":"因為他藐視耶和華的話，違背耶和華的命令，這人一定要剪除；他的罪孽要歸到自己身上。」","notes":[]},{"n":32,"t":"以色列人還在曠野的時候，發現有一個人在安息日撿柴。","notes":[],"heads":["違反安息日的人"]},{"n":33,"t":"發現他撿柴的人把他帶到摩西、亞倫以及全會眾那裏。","notes":[]},{"n":34,"t":"他們把他收押在監裏，因為還不知道要怎樣懲罰他。","notes":[]},{"n":35,"t":"耶和華吩咐摩西說：「這人應當處死；全會眾要在營外用石頭打死他。」","notes":[]},{"n":36,"t":"於是全會眾把他帶到營外，用石頭打死他，是照耶和華所吩咐摩西的。","notes":[]},{"n":37,"t":"耶和華對摩西說：","notes":[],"heads":["有關衣服繸子的條例"]},{"n":38,"t":"「你吩咐以色列人，對他們說，他們世世代代要在衣服邊上縫繸子，並在邊上的繸子釘一條藍色帶子。","notes":[]},{"n":39,"t":"你們要佩帶這繸子，好叫你們看見它就記起耶和華一切的命令，並且遵行，不隨從自己內心和眼目的情慾而跟著行淫。","notes":[]},{"n":40,"t":"這樣，你們就必記得並遵行我一切的命令，成為聖，歸你們的神。","notes":[]},{"n":41,"t":"「我是耶和華－你們的神，曾把你們從埃及地領出來，要作你們的神。我是耶和華－你們的神。」","notes":[]}]},"16":{"heading":"可拉、大坍、亞比蘭和安的叛變","verses":[{"n":1,"t":"利未的曾孫，哥轄的孫子，以斯哈的兒子可拉，連同呂便子孫中以利押的兒子大坍和亞比蘭，與比勒的兒子安，帶了","notes":[]},{"n":2,"t":"以色列人中的二百五十個領袖，就是有名望、從會眾中選出來的人，在摩西面前一同起來，","notes":[]},{"n":3,"t":"聚集攻擊摩西、亞倫，說：「你們太過分了！全會眾人人都成為聖，耶和華也在他們中間。你們為甚麼抬高自己，在耶和華的會眾之上呢？」","notes":[]},{"n":4,"t":"摩西聽見就臉伏於地，","notes":[]},{"n":5,"t":"對可拉和他所有同夥的人說：「到了早晨，耶和華必指示誰是屬他的，誰是成為聖的，就准許誰親近他。他要叫自己所揀選的人親近他。","notes":[]},{"n":6,"t":"可拉和你所有同夥的人哪，你們要這樣做：要拿著香爐，","notes":[]},{"n":7,"t":"明天在耶和華面前把火盛在爐中，把香放在上面。耶和華揀選誰，誰就成為聖。利未的子孫哪，你們太過分了！」","notes":[]},{"n":8,"t":"摩西又對可拉說：「利未的子孫，聽吧！","notes":[]},{"n":9,"t":"以色列的神將你們從以色列會眾中分別出來，使你們親近他，在耶和華的帳幕中事奉，並且站在會眾面前替他們供職。這對你們豈是小事嗎？","notes":[]},{"n":10,"t":"耶和華已經准許你和你所有的弟兄，就是利未的子孫，一同親近他，你們還要求祭司的職分嗎？","notes":[]},{"n":11,"t":"所以，你和你所有同夥的人聚集是在攻擊耶和華。亞倫算甚麼，你們竟向他發怨言？」","notes":[]},{"n":12,"t":"摩西派人去叫以利押的兒子大坍和亞比蘭。他們卻說：「我們不上去！","notes":[]},{"n":13,"t":"你把我們從流奶與蜜之地領出來，讓我們死在曠野，這豈是小事？你還要自立為王管轄我們嗎？","notes":[]},{"n":14,"t":"你根本沒有領我們到流奶與蜜之地，也沒有給我們田地和葡萄園作為產業。難道你想要挖這些人的眼睛嗎？我們不上去！」","notes":[]},{"n":15,"t":"摩西非常生氣，就對耶和華說：「求你不要接受他們的供物。我並沒有奪過他們一匹驢，也沒有害過他們中任何一個人。」","notes":[]},{"n":16,"t":"摩西對可拉說：「明天，你和你所有同夥的人，以及亞倫，都要站在耶和華面前。","notes":[]},{"n":17,"t":"你們各人要拿一個香爐，把香放在上面，各人帶香爐到耶和華面前，共二百五十個；你和亞倫也各拿自己的香爐。」","notes":[]},{"n":18,"t":"於是他們各人拿一個香爐，盛著火，加上香，和摩西、亞倫一同站在會幕的門口。","notes":[]},{"n":19,"t":"可拉召集全會眾到會幕門口攻擊摩西和亞倫。這時，耶和華的榮光向全會眾顯現。","notes":[]},{"n":20,"t":"耶和華吩咐摩西和亞倫說：","notes":[]},{"n":21,"t":"「你們離開這會眾，我好立刻把他們滅絕。」","notes":[]},{"n":22,"t":"摩西、亞倫臉伏於地，說：「神，賜萬人氣息的神啊，一人犯罪，你就要向全會眾發怒嗎？」","notes":[]},{"n":23,"t":"耶和華吩咐摩西說：","notes":[]},{"n":24,"t":"「你吩咐會眾說：『你們遠離可拉、大坍和亞比蘭帳棚的周圍。』」","notes":[]},{"n":25,"t":"摩西起來，到大坍、亞比蘭那裏去；以色列的長老也都跟著他去。","notes":[]},{"n":26,"t":"他吩咐會眾說：「你們離開這些惡人的帳棚吧！不可碰他們的任何東西，免得你們因他們一切的罪而消滅。」","notes":[]},{"n":27,"t":"於是會眾遠離了可拉、大坍和亞比蘭的帳棚。大坍和亞比蘭帶著妻子、兒女和小孩子出來，站在自己的帳棚門口。","notes":[]},{"n":28,"t":"摩西說：「因這件事，你們就必知道這一切事是耶和華差派我做的，並非出於我的心意。","notes":[]},{"n":29,"t":"這些人的死若和世人無異，或者他們所遭遇的和其他人相同，那麼耶和華就不曾差派我了。","notes":[]},{"n":30,"t":"但是，倘若耶和華創作一件新事，使地開了裂口，把他們和一切屬他們的都吞下去，叫他們活活墜落陰間，你們就知道是這些人藐視了耶和華。」","notes":[]},{"n":31,"t":"摩西剛說完這些話，他們腳下的地就裂開，","notes":[]},{"n":32,"t":"地開了裂口，把他們和他們的家眷，以及一切屬可拉的人和財物，都吞了下去。","notes":[]},{"n":33,"t":"他們和一切屬他們的，都活活墜落陰間；地在他們上面又合攏起來，他們就從會眾中滅亡了。","notes":[]},{"n":34,"t":"在他們四圍的以色列眾人聽見他們的叫聲，就都逃跑，說：「恐怕地也要把我們吞下去了！」","notes":[]},{"n":35,"t":"有火從耶和華那裏出來，吞滅了那上香的二百五十人。","notes":[]},{"n":36,"t":"耶和華吩咐摩西說：","notes":[]},{"n":37,"t":"「你要對亞倫祭司的兒子以利亞撒說，把香爐從火中移開，再把炭火撒在別處，因為這些香爐是分別為聖的。","notes":[]},{"n":38,"t":"要把那些犯罪自喪己命之人的香爐錘成薄片，用以包祭壇；因為這些本是他們在耶和華面前獻過，分別為聖的，可以給以色列人作記號。」","notes":[]},{"n":39,"t":"於是以利亞撒祭司把被燒死的人所獻的銅香爐拿來；它們被錘出來，用以包壇，","notes":[]},{"n":40,"t":"給以色列人作紀念，為要叫亞倫子孫之外的人不得近前來，在耶和華面前燒香，免得他和可拉與同他一夥的人一樣，正如耶和華藉摩西所吩咐的。","notes":[]},{"n":41,"t":"第二天，以色列全會眾都向摩西、亞倫發怨言說：「你們殺了耶和華的百姓了。」","notes":[]},{"n":42,"t":"會眾聚集攻擊摩西、亞倫的時候，摩西和亞倫轉向會幕，看哪，雲彩遮蓋會幕，耶和華的榮光顯現。","notes":[]},{"n":43,"t":"摩西、亞倫就來到會幕前。","notes":[]},{"n":44,"t":"耶和華吩咐摩西說：","notes":[]},{"n":45,"t":"「你們離開這會眾，我好立刻把他們滅絕。」他們二人就臉伏於地。","notes":[]},{"n":46,"t":"摩西對亞倫說：「拿你的香爐，把祭壇的火盛在裏面，加上香，趕快帶到會眾那裏，為他們贖罪。因為有憤怒從耶和華面前發出，瘟疫已經開始了。」","notes":[]},{"n":47,"t":"亞倫照摩西所說的拿了香爐，跑到會眾中。看哪，瘟疫已經在百姓中開始了。他就加上香，為百姓贖罪。","notes":[]},{"n":48,"t":"他站在活人和死人之間，瘟疫就止住了。","notes":[]},{"n":49,"t":"除了因可拉事件死的以外，遭瘟疫死的共有一萬四千七百人。","notes":[]},{"n":50,"t":"亞倫回到會幕門口 ，到摩西那裏，瘟疫已經止住了。","notes":[]}]},"17":{"heading":"亞倫的杖","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人，從他們當中取杖，每父家一根；從他們所有的領袖，按著父家，共取十二根。你要把各人的名字寫在他的杖上，","notes":[]},{"n":3,"t":"並要把亞倫的名字寫在利未的杖上，因為各父家的家長都有一根杖。","notes":[]},{"n":4,"t":"你要把這些杖放在會幕裏法櫃前，我與你們相會的地方。","notes":["「與你們」：有古卷和七十士譯本是「與你」。"]},{"n":5,"t":"我所揀選的人，他的杖必發芽。我就平息了以色列人向你們所發的怨言，不再達到我這裏。」","notes":[]},{"n":6,"t":"於是，摩西吩咐以色列人，他們的眾領袖就把杖給他，一個領袖一根杖，按照父家一個領袖一根杖，共有十二根；亞倫的杖也在其中。","notes":[]},{"n":7,"t":"摩西把這些杖放在耶和華面前，在法櫃的帳幕裏。","notes":[]},{"n":8,"t":"第二天，摩西進到法櫃的帳幕去，看哪，利未族亞倫的杖已經發芽，長了花苞，開了花，也結出熟的杏子！","notes":[]},{"n":9,"t":"摩西把所有的杖從耶和華面前拿出來，給以色列眾人看。他們都看見了，各領袖就把自己的杖拿去。","notes":[]},{"n":10,"t":"耶和華吩咐摩西說：「把亞倫的杖放回法櫃前，給這些背叛之子留作記號。你就可以平息他們向我所發的怨言，他們也不會死亡。」","notes":[]},{"n":11,"t":"摩西就照樣做了；耶和華怎樣吩咐他，他就照樣做。","notes":[]},{"n":12,"t":"以色列人對摩西說：「看哪，我們死啦！我們滅亡啦！我們全都滅亡啦！","notes":[]},{"n":13,"t":"凡挨近耶和華帳幕的，就必死亡。我們都要消滅而死嗎？」","notes":[]}]},"18":{"heading":"祭司和利未人的職責","verses":[{"n":1,"t":"耶和華對亞倫說：「你和你的兒子，以及你父家的人，要一同擔當干犯聖所的罪孽；你和你的兒子也要擔當干犯祭司職分的罪孽。","notes":[]},{"n":2,"t":"你也要帶你弟兄利未人，就是你父系支派的人前來，與你聯合，服事你。你和你的兒子要一起在法櫃的帳幕前；","notes":[]},{"n":3,"t":"他們要遵守你的吩咐，負責看守整個帳幕，只是不可挨近聖所的器具和祭壇，免得他們和你們都死亡。","notes":[]},{"n":4,"t":"他們要與你聯合，負責看守會幕和帳幕一切的事；只是外人不可挨近你們。","notes":[]},{"n":5,"t":"你們要負責看守聖所和祭壇，免得憤怒再臨到以色列人。","notes":[]},{"n":6,"t":"看哪，我已從以色列人中選了你們的弟兄利未人，交給你們為賞賜，歸給耶和華，為要在會幕裏事奉。","notes":[]},{"n":7,"t":"你和你的兒子要謹守祭司的職分，負責一切關於祭壇和幔子內的事。我把祭司的職分賜給你們，作為賞賜好事奉我；凡挨近的外人必被處死。」","notes":[]},{"n":8,"t":"耶和華吩咐亞倫說：「看哪，我已將歸我的舉祭，就是以色列人一切分別為聖之物，交給你照管；我把受膏的份賜給你和你的子孫，作為永遠當得的份。","notes":[],"heads":["祭司和利未人應得的份"]},{"n":9,"t":"這是至聖供物中所給你的，一切獻給我為至聖的素祭、贖罪祭、贖愆祭，其中所有不被火燒的供物，都要歸你和你的子孫。","notes":[]},{"n":10,"t":"你要把它當作至聖之物吃；凡男丁都可以吃。你要以這祭物為聖。","notes":["「你要...吃」或譯「你要在至聖的地方吃」。"]},{"n":11,"t":"這也是你的，以色列人所獻的舉祭和搖祭，我已賜給你和你的兒女，作為永遠當得的份；你家中任何潔淨的人都可以吃。","notes":[]},{"n":12,"t":"凡最好的新油、最好的新酒和五穀，就是以色列人獻給耶和華的初熟之物，我都賜給你。","notes":[]},{"n":13,"t":"凡他們從地上所帶來給耶和華的初熟之物也都要歸給你。你家中任何潔淨的人都可以吃。","notes":[]},{"n":14,"t":"以色列中一切永獻的都必歸給你。","notes":[]},{"n":15,"t":"他們所有奉給耶和華的，無論是人是牲畜，凡頭胎的，都要歸給你；但是人的長子，一定要贖出來。不潔淨牲畜中頭生的，也要贖出來。","notes":[]},{"n":16,"t":"其中一個月以上所當贖的，要照你的估價，按聖所的舍客勒，付五舍客勒銀子將他贖回，一舍客勒是二十季拉。","notes":[]},{"n":17,"t":"但是頭生的牛，或頭生的綿羊，或頭生的山羊，卻不可贖，因為牠們都是聖的。要把牠們的血灑在祭壇上，把牠們的脂肪焚燒，當作馨香的火祭獻給耶和華。","notes":[]},{"n":18,"t":"牠們的肉必歸你，像被搖的胸、被舉的右腿歸你一樣。","notes":[]},{"n":19,"t":"凡以色列人所獻給耶和華聖物中的舉祭，我都賜給你和你的兒女，作為永遠當得的份。這要成為你和你的後裔在耶和華面前永遠的鹽約。","notes":["「鹽」指「不廢壞」的意思。"]},{"n":20,"t":"耶和華對亞倫說：「你在以色列人的境內不可有產業，在他們中間也不可有份。在以色列人中，我是你的份，你的產業。","notes":[]},{"n":21,"t":"「至於利未的子孫，看哪，我已賜給他們以色列所有出產的十分之一為業，作為他們在會幕中事奉的酬勞。","notes":[]},{"n":22,"t":"以色列人不可再挨近會幕，免得他們擔當罪而死。","notes":[]},{"n":23,"t":"惟獨利未人要在會幕中事奉，他們要擔當罪孽，作為你們世世代代永遠的定例。他們在以色列人中不可有產業；","notes":[]},{"n":24,"t":"因為以色列人出產的十分之一，就是獻給耶和華為舉祭的，我已賜給利未人為業。所以我對他們說，他們不可在以色列人中有產業。」","notes":[]},{"n":25,"t":"耶和華吩咐摩西說：","notes":[],"heads":["利未人的十一奉獻"]},{"n":26,"t":"「你要吩咐利未人，對他們說：你們從以色列人中所取的十分之一，就是我給你們為業的，要從這十分之一中取十分之一，作為獻給耶和華的舉祭。","notes":[]},{"n":27,"t":"這可算為你們的舉祭，如同禾場上的穀，酒池中盛滿的酒。","notes":[]},{"n":28,"t":"這樣，從以色列人中所收取所有的十分之一，你們要從其中取舉祭獻給耶和華；你們要把獻給耶和華的舉祭歸給亞倫祭司。","notes":[]},{"n":29,"t":"你們要將給你們一切禮物中最好的，就是分別為聖的，獻給耶和華為舉祭。","notes":[]},{"n":30,"t":"你要對利未人說：當你們把其中最好的獻上為舉祭之後，這剩下的就算是你們禾場上的農作物，酒池中的酒。","notes":[]},{"n":31,"t":"你們和你們的家人可以在任何地方吃；這本是你們的賞賜，是你們在會幕裏事奉的酬勞。","notes":[]},{"n":32,"t":"當你們把其中最好的獻上為舉祭，就不致於因它擔當罪。你們不可玷污以色列人的聖物，免得死亡。」","notes":[]}]},"19":{"heading":"紅母牛祭禮","verses":[{"n":1,"t":"耶和華吩咐摩西和亞倫說：","notes":[]},{"n":2,"t":"「耶和華所吩咐的律法中，其中一條律例這樣說：要吩咐以色列人，把一頭健康、沒有殘疾、未曾負軛的紅母牛牽到你這裏來，","notes":[]},{"n":3,"t":"交給以利亞撒祭司。他要把牛牽到營外，人就在他面前把牛宰了。","notes":[]},{"n":4,"t":"以利亞撒祭司要用指頭蘸這牛的血，向會幕前面彈七次。","notes":[]},{"n":5,"t":"人要在他眼前焚燒這母牛，牛的皮、肉、血和糞都要焚燒。","notes":[]},{"n":6,"t":"祭司要把香柏木、牛膝草和朱紅色紗都丟在焚燒牛的火中。","notes":[]},{"n":7,"t":"祭司要洗衣服，用水洗身，然後才可以進營；祭司必不潔淨到晚上。","notes":[]},{"n":8,"t":"焚燒牛的人也要用水洗衣服，用水洗身，必不潔淨到晚上。","notes":[]},{"n":9,"t":"一個潔淨的人要收母牛的灰，存放在營外潔淨的地方，為以色列會眾留作除污穢的水之用。這是為除罪用的。","notes":[]},{"n":10,"t":"收取母牛灰的人要洗衣服，必不潔淨到晚上。這要成為以色列人和寄居在他們中間的外人永遠的定例。","notes":[]},{"n":11,"t":"「摸了任何人死屍的，必不潔淨七天。","notes":[]},{"n":12,"t":"那人要在第三天和第七天潔淨自己，他就潔淨了。若他不在第三天和第七天潔淨自己，他就不潔淨了。","notes":[]},{"n":13,"t":"凡摸了死屍，就是死了的人的屍體，又不潔淨自己的，就玷污了耶和華的帳幕，這人必從以色列中剪除；因為那除污穢的水沒有灑在他身上，他就不潔淨，污穢還在他身上。","notes":[]},{"n":14,"t":"「若有人死在帳棚裏，條例是這樣：凡進那帳棚的，和所有在帳棚裏的人，都必不潔淨七天。","notes":[]},{"n":15,"t":"凡敞開的，沒有用繩子紮好蓋子的器皿，也不潔淨。","notes":[]},{"n":16,"t":"任何人在田野裏摸了被刀殺的，或自然死的，或人的骨頭，或墳墓，就必不潔淨七天。","notes":[]},{"n":17,"t":"要為這不潔淨的人拿一些燒好的除罪灰放在器皿裏，倒上清水。","notes":[]},{"n":18,"t":"一個潔淨的人要拿牛膝草蘸在這水中，把水彈在帳棚上，和一切器皿以及帳棚內的人身上，又要彈在那摸了骨頭，或摸了被殺的或自然死的，或摸了墳墓的人身上。","notes":[]},{"n":19,"t":"那潔淨的人要在第三天和第七天把水彈在不潔淨的人身上，在第七天潔淨那人。那人要洗衣服，用水洗澡，到晚上就潔淨了。","notes":[]},{"n":20,"t":"但任何不潔淨的人，他若不潔淨自己，那人要從會中剪除，因為他玷污了耶和華的聖所，除污穢的水沒有灑在他身上，他是不潔淨的。","notes":[]},{"n":21,"t":"這要成為你們永遠的定例。此外，那彈除污穢水的人也要洗衣服。凡碰除污穢水的，必不潔淨到晚上。","notes":[]},{"n":22,"t":"不潔淨的人所摸的任何東西都不潔淨；摸了這東西的人必不潔淨到晚上。」","notes":[]}]},"20":{"heading":"米利巴水","verses":[{"n":1,"t":"正月間，以色列全會眾到了尋的曠野；百姓住在加低斯。米利暗死在那裏，也葬在那裏。","notes":[]},{"n":2,"t":"會眾沒有水，就聚集反對摩西和亞倫。","notes":[]},{"n":3,"t":"百姓與摩西爭鬧，說：「我們恨不得與我們的弟兄一同死在耶和華面前。","notes":[]},{"n":4,"t":"你們為甚麼領耶和華的會眾到這曠野，使我們和我們的牲畜都死在這裏呢？","notes":[]},{"n":5,"t":"你們為甚麼領我們從埃及上來，把我們帶到這壞的地方呢？這地方不能撒種，沒有無花果樹、葡萄樹、石榴樹，也沒有水喝。」","notes":[]},{"n":6,"t":"摩西、亞倫離開會眾面前，到會幕的門口，臉伏於地；耶和華的榮光向他們顯現。","notes":[]},{"n":7,"t":"耶和華吩咐摩西說：","notes":[]},{"n":8,"t":"「你拿著杖去，和你的哥哥亞倫召集會眾，在他們眼前吩咐磐石湧出水來，水就會從磐石流出，給會眾和他們的牲畜喝。」","notes":[]},{"n":9,"t":"於是摩西遵照耶和華所吩咐他的，從耶和華面前拿了杖去。","notes":[]},{"n":10,"t":"摩西和亞倫召集會眾到磐石前。摩西對他們說：「聽著，你們這些悖逆的人！我們要叫這磐石流出水來給你們嗎？」","notes":[]},{"n":11,"t":"摩西舉起手來，用杖擊打磐石兩下，就有許多水流出來，會眾和他們的牲畜都喝了。","notes":[]},{"n":12,"t":"但是耶和華對摩西、亞倫說：「因為你們不信我，沒有在以色列人眼前尊我為聖，所以你們必不能領這會眾進入我所要賜給他們的地去。」","notes":[]},{"n":13,"t":"這就是米利巴水，因以色列人與耶和華爭鬧，耶和華在他們面前顯為聖。","notes":["「米利巴」意思是「爭鬧」。"]},{"n":14,"t":"摩西從加低斯差遣使者到以東王那裏，說：「你的弟兄以色列這樣說：『你知道我們所遭遇的一切困難。","notes":[],"heads":["以東王不准過境"]},{"n":15,"t":"我們的祖先曾下到埃及，我們也在埃及住了很多年。然而，埃及人卻惡待我們和我們的祖先。","notes":[]},{"n":16,"t":"我們哀求耶和華，他垂聽了我們的聲音，差遣使者把我們從埃及領出來。看哪，我們到了你邊界的加低斯城。","notes":[]},{"n":17,"t":"求你讓我們穿越你的地。我們不走田間和葡萄園，也不喝井裏的水。我們只走王的大道，不偏左右，直到過了你的邊界。』」","notes":[]},{"n":18,"t":"但是，以東對他說：「你不可從我這裏穿越！否則，我要帶刀出去攻擊你。」","notes":[]},{"n":19,"t":"以色列人對他說：「我們只上大道。如果我和我的牲畜喝了你的水，我必付錢給你。我不求別的事，只求讓我步行過去。」","notes":[]},{"n":20,"t":"以東說：「你不可經過！」他就率領一大群軍隊，以強硬的手出來攻擊以色列。","notes":[]},{"n":21,"t":"這樣，以東不肯讓以色列穿越他的境內，以色列就轉去，離開他了。","notes":[]},{"n":22,"t":"以色列全會眾從加低斯起行，到了何珥山。","notes":[],"heads":["亞倫逝世"]},{"n":23,"t":"耶和華在以東地邊界的何珥山對摩西、亞倫說：","notes":[]},{"n":24,"t":"「亞倫要歸到他祖先那裏。他必不得進入我所賜給以色列人的地，因為你們在米利巴水的事上違背了我的指示。","notes":["「他祖先」：原文是「他百姓」。"]},{"n":25,"t":"你要帶亞倫和他的兒子以利亞撒上何珥山，","notes":[]},{"n":26,"t":"把亞倫的聖衣脫下，給他的兒子以利亞撒穿上。亞倫必歸去，死在那裏。」","notes":[]},{"n":27,"t":"摩西就遵照耶和華的吩咐去做，他們在全會眾的眼前上了何珥山。","notes":[]},{"n":28,"t":"摩西把亞倫的聖衣脫下，給他的兒子以利亞撒穿上，亞倫就死在山頂那裏。於是，摩西和以利亞撒下了山。","notes":[]},{"n":29,"t":"全會眾見亞倫死了，以色列全家就為亞倫舉哀三十天。","notes":[]}]},"21":{"heading":"戰勝迦南人","verses":[{"n":1,"t":"住尼革夫的迦南人的亞拉得王，聽說以色列從亞他林路來，就和以色列交戰，擄去他們一些人。","notes":[]},{"n":2,"t":"以色列向耶和華許願說：「你若把這百姓真的交在我手中，我就把他們的城鎮徹底毀滅。」","notes":[]},{"n":3,"t":"耶和華垂聽了以色列的聲音，把迦南人交出來。以色列就把迦南人和他們的城鎮徹底毀滅。因此，那地方名叫何珥瑪 。","notes":["「何珥瑪」意思是「毀滅」。"]},{"n":4,"t":"他們從何珥山起行，繞過以東地往紅海那條路走。在路上，百姓心中煩躁。","notes":[],"heads":["銅製的蛇"]},{"n":5,"t":"百姓向神和摩西發怨言，說：「你們為甚麼把我們從埃及領上來，使我們死在曠野呢？這裏沒有糧食，沒有水，我們厭惡這淡而無味的食物。」","notes":["「你們...領上來」：七十士譯本是「你為甚麼把我們從埃及領出來」。"]},{"n":6,"t":"耶和華派火蛇進入百姓當中去咬他們，於是以色列中死了許多百姓。","notes":[]},{"n":7,"t":"百姓到摩西那裏，說：「我們有罪了，因為我們向耶和華和你發怨言。求你向耶和華禱告，叫蛇離開我們。」於是摩西為百姓禱告。","notes":[]},{"n":8,"t":"耶和華對摩西說：「你要造一條火蛇，掛在杆子上。凡被咬的，一望這蛇就必存活。」","notes":[]},{"n":9,"t":"摩西就造了一條銅蛇，掛在杆子上。凡被蛇咬的，一望這銅蛇就活了。","notes":[]},{"n":10,"t":"以色列人起行，安營在阿伯。","notes":[],"heads":["從何珥山到摩押谷"]},{"n":11,"t":"又從阿伯起行，安營在以耶‧亞巴琳，在摩押對面的曠野，向日出的方向。","notes":[]},{"n":12,"t":"又從那裏起行，安營在撒烈谷。","notes":[]},{"n":13,"t":"從那裏再起行，安營在亞嫩河的另一邊。這亞嫩河在曠野，從亞摩利人的境內流出來；亞嫩河是摩押的邊界，在摩押和亞摩利人之間。","notes":[]},{"n":14,"t":"所以《耶和華的戰記》中提到：「蘇法的哇哈伯，亞嫩河谷，","notes":[]},{"n":15,"t":"以及亞珥地區眾河床的斜坡，都靠近摩押的邊境。」","notes":[]},{"n":16,"t":"以色列人從那裏起行，到了比珥 。從前耶和華對摩西說：「召集百姓，我要給他們水」，說的就是這井。","notes":["「比珥」意思是「井」。"]},{"n":17,"t":"當時，以色列人唱這首歌：「井啊，湧出水來！你們要向它歌唱！","notes":[]},{"n":18,"t":"這井是領袖用權杖所挖，是百姓中的貴族用手杖所掘。」以色列人從曠野往瑪他拿去，","notes":[]},{"n":19,"t":"從瑪他拿到拿哈列，從拿哈列到巴末，","notes":[]},{"n":20,"t":"從巴末到摩押地的谷，又到那可以瞭望曠野的毗斯迦山頂。","notes":[]},{"n":21,"t":"以色列差遣使者到亞摩利人的王西宏那裏，說：","notes":[],"heads":["戰勝亞摩利王和巴珊王"]},{"n":22,"t":"「求你讓我們穿越你的地；我們不岔進田間和葡萄園，也不喝井裏的水，只走王的大道，直到過了你的邊界。」","notes":[]},{"n":23,"t":"但西宏不讓以色列人穿越他的境內，就召集他的眾百姓出到曠野，要攻擊以色列，到了雅雜與以色列交戰。","notes":[]},{"n":24,"t":"以色列人用刀殺了他，佔領了他的地，從亞嫩河到雅博河，直到亞捫人的邊界，因為亞捫人的邊防堅固。","notes":[]},{"n":25,"t":"以色列人奪取這裏所有的城鎮，就住在亞摩利人的城鎮中，包括希實本和所屬的一切鄉鎮。","notes":["「鄉鎮」：原文直譯「女子們」；本卷書下同。"]},{"n":26,"t":"希實本是亞摩利王西宏的首都；西宏曾與先前的摩押王交戰，從他手中奪取了他所有的地，直到亞嫩河。","notes":[]},{"n":27,"t":"所以那些作詩歌的說：你們到希實本來吧；願西宏的城被修造建立。","notes":[]},{"n":28,"t":"因為有火從希實本發出，有火焰從西宏的城冒出，燒燬了摩押的亞珥，亞嫩河丘壇的主。","notes":["「亞嫩河丘壇的主」：原文另譯「亞嫩河丘壇的諸巴力」；七十士譯本是「亞嫩河的柱像」。"]},{"n":29,"t":"摩押啊，你有禍了！基抹的百姓啊，你們滅亡了！基抹的男子逃亡，女子被擄，交給了亞摩利王西宏。","notes":[]},{"n":30,"t":"我們射了他們；希實本直到底本盡都毀滅。我們劫掠，直到挪法；這挪法直延到米底巴。","notes":["「我們...毀滅」：七十士譯本是「他們的後代滅亡，從希實本直到底本」。"]},{"n":31,"t":"這樣，以色列人就住在亞摩利人的地。","notes":[]},{"n":32,"t":"摩西差派人去窺探雅謝；以色列人佔領了雅謝附近的鄉村，趕出那裏的亞摩利人。","notes":[]},{"n":33,"t":"後來，以色列人轉回，往上巴珊的路去。巴珊王噩率領他的眾百姓出來，在以得來與他們交戰。","notes":[]},{"n":34,"t":"耶和華對摩西說：「不要怕他！因為我已將他和他的眾百姓，以及他的地都交在你手中。你要待他如同待住在希實本的亞摩利王西宏一樣。」","notes":[]},{"n":35,"t":"於是他們殺了巴珊王和他的眾子，以及他的眾百姓，沒有留下一個倖存者，並且佔領了他的地。","notes":[]}]},"22":{"heading":"摩押王召巴蘭","verses":[{"n":1,"t":"以色列人起行，在摩押平原，約旦河東，對著耶利哥安營。","notes":[]},{"n":2,"t":"西撥的兒子巴勒看見以色列向亞摩利人所做的一切。","notes":[]},{"n":3,"t":"摩押因以色列百姓這麼多，非常懼怕。摩押因以色列人的緣故就憂懼。","notes":[]},{"n":4,"t":"摩押對米甸的長老說：「現在這群人要舔盡我們四圍的一切，好像牛舔盡田間的草一樣。」那時，西撥的兒子巴勒作摩押王。","notes":[]},{"n":5,"t":"他派使者往大河附近的毗奪去，到比珥的兒子巴蘭的家鄉，召巴蘭來，說：「看哪，有一群百姓從埃及出來；看哪，他們遮滿地面，住在我的對面。","notes":["「家鄉」：有古譯本是「亞茅人的地」。"]},{"n":6,"t":"現在請你來，為我詛咒這百姓，因為他們比我強大，或許我能打敗他們，把他們趕出此地。因為我知道，你為誰祝福，誰就得福；你詛咒誰，誰就受詛咒。」","notes":[]},{"n":7,"t":"摩押的長老和米甸的長老手裏拿著占卜的禮金到巴蘭那裏，將巴勒的話告訴他。","notes":[]},{"n":8,"t":"巴蘭對他們說：「今晚你們在這裏過夜，我必照著耶和華向我說的話給你們答覆。」摩押的官員就在巴蘭那裏住下。","notes":[]},{"n":9,"t":"神臨到巴蘭那裏，說：「你這裏的這些人是誰？」","notes":[]},{"n":10,"t":"巴蘭對神說：「摩押王西撥的兒子巴勒送信給我：","notes":[]},{"n":11,"t":"『看哪，從埃及出來的百姓遮滿了地面，現在請你來，為我詛咒他們，或許我能打敗他們，把他們趕走。』」","notes":[]},{"n":12,"t":"神對巴蘭說：「你不可跟他們去，也不可詛咒這百姓，因為他們是蒙福的。」","notes":[]},{"n":13,"t":"巴蘭早晨起來，對巴勒的官員說：「你們回本地去吧，因為耶和華不允許我和你們一起去。」","notes":[]},{"n":14,"t":"摩押的官員就起來，到巴勒那裏，說：「巴蘭不肯和我們一起來。」","notes":[]},{"n":15,"t":"巴勒又差遣比這些更多，更尊貴的官員。","notes":[]},{"n":16,"t":"他們來到巴蘭那裏，對他說：「西撥的兒子巴勒這樣說：『請你不要再推辭到我這裏來！","notes":[]},{"n":17,"t":"我必使你得極大的尊榮，無論你向我要甚麼，我都給你。只求你來為我詛咒這百姓。』」","notes":[]},{"n":18,"t":"巴蘭回答巴勒的臣僕說：「巴勒就是將他滿屋的金銀給我，我也不能做任何大小的事，違背耶和華－我神的指示。","notes":[]},{"n":19,"t":"現在請你們今晚也在這裏住下，我好知道耶和華還要對我說甚麼。」","notes":[]},{"n":20,"t":"神在夜裏臨到巴蘭那裏，說：「這些人若來求你，你就起來跟他們去吧，只是你必須照著我對你說的話去做。」","notes":[]},{"n":21,"t":"巴蘭早晨起來，備了驢，就和摩押的官員一同去了。","notes":[],"heads":["巴蘭和他的驢"]},{"n":22,"t":"神因他去就怒氣發作；耶和華的使者站在路中間敵對他。他騎著驢，有兩個僕人跟隨他。","notes":[]},{"n":23,"t":"驢看見耶和華的使者站在路中間，手裏有拔出來的刀，就離開了路，岔入田間。巴蘭就打驢，要牠回到路上。","notes":[]},{"n":24,"t":"耶和華的使者站在葡萄園的窄路上，這邊有牆，那邊也有牆。","notes":[]},{"n":25,"t":"驢看見耶和華的使者，就往牆擠去，把巴蘭的腳擠到牆上；巴蘭再打驢。","notes":[]},{"n":26,"t":"耶和華的使者又往前去，站在狹窄的地方，那裏左右都無路可轉。","notes":[]},{"n":27,"t":"驢看見耶和華的使者，就伏在巴蘭底下。巴蘭怒氣發作，用杖打驢。","notes":[]},{"n":28,"t":"耶和華使驢開口，對巴蘭說：「我向你做了甚麼，你竟打我這三次呢？」","notes":[]},{"n":29,"t":"巴蘭對驢說：「因為你戲弄我，我恨不得手中有刀，現在就把你殺了。」","notes":[]},{"n":30,"t":"驢對巴蘭說：「我不是你從小直到今天所騎的驢嗎？我平時有這樣待過你嗎？」巴蘭說：「沒有。」","notes":[]},{"n":31,"t":"耶和華使巴蘭的眼目明亮，他看見耶和華的使者站在路中間，手裏有拔出來的刀；巴蘭就低頭俯伏下拜。","notes":[]},{"n":32,"t":"耶和華的使者對他說：「你為甚麼這三次打你的驢呢？看哪，我出來敵對你，因為這路在我面前已經偏離了。","notes":[]},{"n":33,"t":"驢看見我就從我面前迴避了這三次；驢若沒有迴避我，我早把你殺了，留牠存活。」","notes":[]},{"n":34,"t":"巴蘭對耶和華的使者說：「我有罪了。我不知道你站在路中間阻擋我；現在你若看為不好，我就回去。」","notes":[]},{"n":35,"t":"耶和華的使者對巴蘭說：「你和這些人去吧！你只要說我對你說的話。」於是巴蘭和巴勒的官員一同去了。","notes":[]},{"n":36,"t":"巴勒聽見巴蘭來了，就到摩押的城去迎接他；這城是在邊界的亞嫩河旁。","notes":["「摩押的城」：原文另譯「亞珥‧摩押」。"],"heads":["巴勒歡迎巴蘭"]},{"n":37,"t":"巴勒對巴蘭說：「我不是急切地派人到你那裏去召你嗎？你為何不到我這裏來呢？我豈不能使你得尊榮嗎？」","notes":[]},{"n":38,"t":"巴蘭對巴勒說：「看哪，我已經到你這裏來了！現在我豈能擅自說甚麼呢？神將甚麼話放在我口中，我就說甚麼。」","notes":[]},{"n":39,"t":"巴蘭和巴勒同去，來到基列‧胡瑣。","notes":[]},{"n":40,"t":"巴勒宰了牛羊為祭物，送給巴蘭和陪伴他的官員。","notes":[]},{"n":41,"t":"到了早晨，巴勒領巴蘭到巴末‧巴力，從那裏可以看到一部分以色列的百姓。","notes":[],"heads":["巴蘭首次預言"]}]},"23":{"heading":"巴蘭第二次預言","verses":[{"n":1,"t":"巴蘭對巴勒說：「你要在這裏為我築七座壇，又要在這裏為我預備七頭公牛、七隻公羊。」","notes":[]},{"n":2,"t":"巴勒照巴蘭的話做了。巴勒和巴蘭在每座壇上獻一頭公牛、一隻公羊。","notes":[]},{"n":3,"t":"巴蘭對巴勒說：「你站在你的燔祭旁邊，我要往前去，或許耶和華會向我顯現。他指示我甚麼事，我必告訴你。」於是巴蘭上到一個光禿的高地。","notes":[]},{"n":4,"t":"神向巴蘭顯現。巴蘭對他說：「我預備了七座壇，在每座壇上獻了一頭公牛、一隻公羊。」","notes":[]},{"n":5,"t":"耶和華把話放在巴蘭口中，說：「你回到巴勒那裏，要這樣說。」","notes":[]},{"n":6,"t":"他就回到巴勒那裏，看哪，巴勒和摩押的眾官員站在燔祭旁邊。","notes":[]},{"n":7,"t":"巴蘭唱起詩歌說：「巴勒領我出亞蘭，摩押王領我出東方的山脈：『來啊，為我詛咒雅各；來啊，怒罵以色列。』","notes":[]},{"n":8,"t":"神沒有詛咒的，我焉能詛咒？耶和華沒有怒罵的，我豈能怒罵？","notes":[]},{"n":9,"t":"我從磐石的巔峰看到他，我從山丘望見他。看哪，這是獨居的民，不算在列國中。","notes":[]},{"n":10,"t":"誰能數點雅各的塵土？誰能計算以色列的塵沙 ？我願如正直人之死而死；我願如正直人之終而終。」","notes":["「塵沙」或譯「四分之一」。"]},{"n":11,"t":"巴勒對巴蘭說：「你向我做的是甚麼呢？我帶你來詛咒我的仇敵，看哪，你竟為他們祝福。」","notes":[]},{"n":12,"t":"他回答說：「耶和華放在我口中的話，我豈能不謹慎地說呢？」","notes":[]},{"n":13,"t":"巴勒對他說：「請你跟我到別的地方，在那裏可以看見他們。你只能看見他們的一部分，卻不能看見全部。請你在那裏為我詛咒他們。」","notes":[]},{"n":14,"t":"於是巴勒領巴蘭到了瑣腓的田野，上了毗斯迦山頂，築了七座壇，在每座壇上獻一頭公牛、一隻公羊。","notes":["「到了...頂」或譯「到了毗斯迦山頂上的瞭望臺」。"]},{"n":15,"t":"巴蘭對巴勒說：「你站在你的燔祭旁邊，我要到那邊去看看。」","notes":[]},{"n":16,"t":"耶和華向巴蘭顯現，把話放在他口中，說：「你回到巴勒那裏，要這樣說。」","notes":[]},{"n":17,"t":"他回到巴勒那裏，看哪，巴勒站在燔祭旁邊，摩押的官員也和他在一起。巴勒對他說：「耶和華說了甚麼呢？」","notes":[]},{"n":18,"t":"巴蘭唱起詩歌說：「巴勒啊，起來，聽；西撥的兒子啊，側耳聽我。","notes":[]},{"n":19,"t":"神非人，必不致說謊，也非人子，必不致後悔。他說了豈不照著做呢？他發了言豈不實現呢？","notes":[]},{"n":20,"t":"看哪，我奉命祝福；神賜福，我不能扭轉。","notes":[]},{"n":21,"t":"他未見雅各中有災難 ，也未見以色列中有禍患。耶和華－他的神和他同在；在他中間有歡呼王的聲音。","notes":["「災難」或譯「罪孽」。","「禍患」或譯「奸惡」。"]},{"n":22,"t":"神領他們出埃及，為以色列有如野牛的角。","notes":[]},{"n":23,"t":"絕沒有法術可以傷雅各，沒有占卜可以害以色列。現在，人論及雅各，論及以色列必說：『神成就了何等的事啊！』","notes":[]},{"n":24,"t":"看哪，這百姓興起如母獅，挺身像公獅，未曾吃獵物，未曾喝被殺者的血，絕不躺臥。」","notes":[]},{"n":25,"t":"巴勒對巴蘭說：「你一點也不要詛咒他們，一點也不要為他們祝福！」","notes":[]},{"n":26,"t":"巴蘭回答巴勒說：「我不是告訴過你：『凡耶和華所說的，我必須遵行』嗎？」","notes":[]},{"n":27,"t":"巴勒對巴蘭說：「來，我領你到別的地方，或許神喜歡你在那裏為我詛咒他們。」","notes":[]},{"n":28,"t":"巴勒就領巴蘭到那可瞭望曠野的毗珥山頂。","notes":[]},{"n":29,"t":"巴蘭對巴勒說：「你要在這裏為我築七座壇，又要在這裏為我預備七頭公牛、七隻公羊。」","notes":[]},{"n":30,"t":"巴勒就照巴蘭的話做，在每座壇上獻一頭公牛、一隻公羊。","notes":[]}]},"24":{"heading":"巴蘭第三次預言","verses":[{"n":1,"t":"巴蘭見耶和華喜歡賜福給以色列，就不像前兩次去求法術，卻面向曠野。","notes":[]},{"n":2,"t":"巴蘭舉目，看見以色列人照著支派紮營。神的靈就臨到他身上，","notes":[]},{"n":3,"t":"他唱起詩歌說：「比珥的兒子巴蘭說，眼目關閉的人說，","notes":["「關閉」：七十士譯本是「看得清楚」；下同。"]},{"n":4,"t":"聽見神的言語，得見全能者的異象，俯伏著，眼睛卻睜開的人說：","notes":[]},{"n":5,"t":"雅各啊，你的帳棚何等華美！以色列啊，你的帳幕何其華麗！","notes":[]},{"n":6,"t":"如連綿的山谷，如河畔的園子，如耶和華栽種的沉香樹，又如水邊的香柏木。","notes":[]},{"n":7,"t":"水要從他的桶裏流出，種子要撒在多水之處。他的王必超越亞甲，他的國必要振興。","notes":[]},{"n":8,"t":"神領他出埃及，為他有如野牛的角。他要吞滅那敵對他的國，壓碎他們的骨頭，用箭射透他們。","notes":[]},{"n":9,"t":"他蹲如公獅，臥如母獅，誰敢惹他？凡為你祝福的，願他蒙福；凡詛咒你的，願他受詛咒。」","notes":[]},{"n":10,"t":"巴勒向巴蘭怒氣發作，就緊握拳頭。巴勒對巴蘭說：「我召你來詛咒我的仇敵，看哪，你竟然這三次為他們祝福。","notes":["「緊握拳頭」：原文直譯「擊掌」。"],"heads":["巴蘭第四次預言"]},{"n":11,"t":"如今你趕快回本地去吧！我想使你大得尊榮，看哪，耶和華卻阻止你得尊榮。」","notes":[]},{"n":12,"t":"巴蘭對巴勒說：「我不是對你所差遣到我那裏的使者說：","notes":[]},{"n":13,"t":"『巴勒就是把他滿屋的金銀給我，我也不能違背耶和華的指示，隨自己的心意做好做歹。耶和華說甚麼，我就說甚麼。』","notes":[]},{"n":14,"t":"現在，看哪，我要回到我的百姓那裏。來，讓我告訴你這百姓日後要怎樣對待你的百姓。」","notes":[]},{"n":15,"t":"他就唱起詩歌說：「比珥的兒子巴蘭說，眼目關閉的人說，","notes":[]},{"n":16,"t":"聽見神的言語，明白至高者的知識，看見全能者的異象，俯伏著，眼睛卻睜開的人說：","notes":[]},{"n":17,"t":"我看見他，卻不在現時；我望見他，卻不在近處。有星出於雅各，有杖從以色列興起，必打破摩押的額頭，必毀壞所有的塞特人 。","notes":["「必毀壞...塞特人」：有古卷是「所有塞特人的頭頂」。"]},{"n":18,"t":"以東將成為產業，西珥將成為它敵人的產業；但以色列卻要得勝。","notes":["「以東...它敵人的產業」或譯「他必得以東為產業，又得仇敵之地西珥為產業」。"]},{"n":19,"t":"有一位出於雅各的，必掌大權，他要除滅城中的倖存者。」","notes":[]},{"n":20,"t":"巴蘭看見亞瑪力人，就唱起詩歌說：「亞瑪力是諸國之首，但它終必永遠沉淪。」","notes":["「但它終必永遠沉淪」：撒瑪利亞五經是「直到它終於沉淪」。"]},{"n":21,"t":"巴蘭看見基尼人，就唱起詩歌說：「你的住處堅固；你的巢窩造在巖石中。","notes":[]},{"n":22,"t":"然而基尼族必被吞滅，直到何時亞述把你擄去？」","notes":["「基尼族」與「巢窩」的希伯來話發音相近。","「然而...擄去？」七十士譯本是「雖然比珥有造得堅固的巢窩，亞述人必把你擄去。」"]},{"n":23,"t":"巴蘭又唱起詩歌說：「哀哉！若神做這事，誰能存活呢？","notes":["「若神...存活呢？」原文另譯「聚集在北方的那些人是誰呢？」"]},{"n":24,"t":"有船隻從基提邊界來到，要壓制亞述，要壓制希伯；他也必永遠沉淪。」","notes":["「有船隻」：七十士譯本是「有人」。","「他也必永遠沉淪」：撒瑪利亞五經是「直到他沉淪」。"]},{"n":25,"t":"於是巴蘭起來，回本地去；巴勒也回他的路去了。","notes":[]}]},"25":{"heading":"在毗珥拜巴力","verses":[{"n":1,"t":"以色列人住在什亭，百姓開始與摩押女子行淫。","notes":[]},{"n":2,"t":"這些女子請百姓一同為她們的神明獻祭，百姓吃了祭物，跪拜她們的神明。","notes":[]},{"n":3,"t":"以色列與巴力‧毗珥聯合，耶和華的怒氣就向以色列發作。","notes":[]},{"n":4,"t":"耶和華對摩西說：「拿下百姓中所有的領袖，對著太陽把他們懸掛在我面前，使我向以色列所發的怒氣可以平息。」","notes":[]},{"n":5,"t":"於是摩西對以色列的審判官說：「你們的人若有與巴力‧毗珥聯合的，你們各人就要把他們殺了。」","notes":[]},{"n":6,"t":"摩西和以色列全會眾在會幕門口哭泣的時候，看哪，有一個以色列人，在他們眼前帶著一個米甸女子，到他弟兄那裏。","notes":[]},{"n":7,"t":"亞倫祭司的孫子，以利亞撒的兒子非尼哈看見了，就從會眾中起來，手裏拿著槍，","notes":[]},{"n":8,"t":"跟這以色列人進入帳棚，刺穿了二人，就是以色列人和那女子的肚腹。這樣，以色列人遭受的瘟疫就停止了。","notes":[]},{"n":9,"t":"遭瘟疫死的，有二萬四千人。","notes":[]},{"n":10,"t":"耶和華吩咐摩西說：","notes":[]},{"n":11,"t":"「亞倫祭司的孫子，以利亞撒的兒子非尼哈，使我的憤怒轉離以色列人，因為在他們中間，他以我的妒忌為他的妒忌，使我不在妒忌中毀滅以色列人。","notes":[]},{"n":12,"t":"因此，你要說：『看哪，我將我平安的約賜給他。","notes":[]},{"n":13,"t":"這是他和他的後裔永遠當祭司職任的約，因他為了神而妒忌，他為以色列人贖罪。』」","notes":[]},{"n":14,"t":"那與米甸女子一起被殺的以色列人，名叫心利，是撒路的兒子，是西緬一個父家的領袖。","notes":[]},{"n":15,"t":"那被殺的米甸女子，名叫哥斯比，是蘇珥的女兒；蘇珥是米甸一個父家的領袖。","notes":[]},{"n":16,"t":"耶和華吩咐摩西說：","notes":[]},{"n":17,"t":"「你要苦害米甸人，擊殺他們；","notes":[]},{"n":18,"t":"因為他們用詭計苦害你們，在毗珥的事上和他們的姊妹，米甸領袖的女兒哥斯比的事上，欺騙了你們；在瘟疫的日子，這女子因毗珥的事件被殺了。」","notes":[]}]},"26":{"heading":"第二次人口普查","verses":[{"n":1,"t":"瘟疫過了之後，耶和華對摩西和亞倫祭司的兒子以利亞撒說：","notes":[]},{"n":2,"t":"「你們要將以色列全會眾，按他們的父家，凡二十歲以上能出去為以色列打仗的，計算總數。」","notes":[]},{"n":3,"t":"摩西和以利亞撒祭司在摩押平原與耶利哥相對的約旦河邊吩咐他們說：","notes":[]},{"n":4,"t":"「計算你們中間從二十歲以上的人數。」正如耶和華所吩咐摩西的。從埃及地出來的以色列人如下：","notes":[]},{"n":5,"t":"以色列的長子是呂便。呂便的眾子：屬哈諾的，有哈諾族；屬法路的，有法路族；","notes":[]},{"n":6,"t":"屬希斯倫的，有希斯倫族；屬迦米的，有迦米族。","notes":[]},{"n":7,"t":"這就是呂便的各族；被數的共有四萬三千七百三十名。","notes":[]},{"n":8,"t":"法路的兒子是以利押。","notes":[]},{"n":9,"t":"以利押的兒子是尼母利、大坍、亞比蘭。這大坍、亞比蘭，就是從會中選出來，當可拉一夥的人向耶和華爭鬧的時候，一起向摩西、亞倫爭鬧的；","notes":[]},{"n":10,"t":"地開了裂口，吞了他們和可拉，可拉一夥的人也一同死亡。當時火吞滅了二百五十個人；他們就成為鑒戒。","notes":[]},{"n":11,"t":"然而可拉的眾子沒有死亡。","notes":[]},{"n":12,"t":"按著宗族，西緬的眾子：屬尼母利的，有尼母利族；屬雅憫的，有雅憫族；屬雅斤的，有雅斤族；","notes":[]},{"n":13,"t":"屬謝拉的，有謝拉族；屬掃羅的，有掃羅族。","notes":[]},{"n":14,"t":"這就是西緬的各族，共有二萬二千二百名。","notes":[]},{"n":15,"t":"按著宗族，迦得的眾子：屬洗分的，有洗分族；屬哈基的，有哈基族；屬書尼的，有書尼族；","notes":[]},{"n":16,"t":"屬阿斯尼的，有阿斯尼族；屬以利的，有以利族；","notes":[]},{"n":17,"t":"屬亞律的，有亞律族；屬亞列利的，有亞列利族。","notes":[]},{"n":18,"t":"這就是迦得子孫的各族；他們被數的共有四萬零五百名。","notes":[]},{"n":19,"t":"猶大的兒子是珥和俄南。珥和俄南死在迦南地。","notes":[]},{"n":20,"t":"按著宗族，猶大的眾子：屬示拉的，有示拉族；屬法勒斯的，有法勒斯族；屬謝拉的，有謝拉族。","notes":[]},{"n":21,"t":"法勒斯的眾子：屬希斯崙的，有希斯崙族；屬哈母勒的，有哈母勒族。","notes":[]},{"n":22,"t":"這就是猶大的各族；他們被數的共有七萬六千五百名。","notes":[]},{"n":23,"t":"按著宗族，以薩迦的眾子：屬陀拉的，有陀拉族；屬普瓦的，有普瓦族；","notes":[]},{"n":24,"t":"屬雅述的，有雅述族；屬伸崙的，有伸崙族。","notes":[]},{"n":25,"t":"這就是以薩迦的各族；他們被數的共有六萬四千三百名。","notes":[]},{"n":26,"t":"按著宗族，西布倫的眾子：屬西烈的，有西烈族；屬以倫的，有以倫族；屬雅利的，有雅利族。","notes":[]},{"n":27,"t":"這就是西布倫的各族；他們被數的共有六萬零五百名。","notes":[]},{"n":28,"t":"按著宗族，約瑟的兒子有瑪拿西、以法蓮。","notes":[]},{"n":29,"t":"瑪拿西的眾子：屬瑪吉的，有瑪吉族；瑪吉生基列；屬基列的，有基列族。","notes":[]},{"n":30,"t":"這就是基列的眾子：屬伊以謝的，有伊以謝族；屬希勒的，有希勒族；","notes":[]},{"n":31,"t":"屬亞斯烈的，有亞斯烈族；屬示劍的，有示劍族；","notes":[]},{"n":32,"t":"屬示米大的，有示米大族；屬希弗的，有希弗族。","notes":[]},{"n":33,"t":"希弗的兒子西羅非哈沒有兒子，只有女兒。西羅非哈的女兒的名字是瑪拉、挪阿、曷拉、密迦、得撒。","notes":[]},{"n":34,"t":"這就是瑪拿西的各族；他們被數的共有五萬二千七百名。","notes":[]},{"n":35,"t":"這就是按著宗族，以法蓮的眾子：屬書提拉的，有書提拉族；屬比結的，有比結族；屬他罕的，有他罕族。","notes":[]},{"n":36,"t":"這就是書提拉的眾子：屬以蘭的，有以蘭族。","notes":[]},{"n":37,"t":"這就是以法蓮子孫的各族；他們被數的共有三萬二千五百名。按著宗族，以上這些都是約瑟的子孫。","notes":[]},{"n":38,"t":"按著宗族，便雅憫的眾子：屬比拉的，有比拉族；屬亞實別的，有亞實別族；屬亞希蘭的，有亞希蘭族；","notes":[]},{"n":39,"t":"屬書反的，有書反族；屬戶反的，有戶反族。","notes":[]},{"n":40,"t":"比拉的兒子是亞勒、乃幔；屬亞勒的，有亞勒族；屬乃幔的，有乃幔族。","notes":["「屬亞勒的」是根據某些古卷和七十士譯本，原文沒有。"]},{"n":41,"t":"按著宗族，這就是便雅憫的子孫；他們被數的共有四萬五千六百名。","notes":[]},{"n":42,"t":"這就是按著宗族，但的眾子：屬書含的，有書含族。按著宗族，這就是但的各族。","notes":[]},{"n":43,"t":"按照他們被數的，書含全宗族共有六萬四千四百名。","notes":[]},{"n":44,"t":"按著宗族，亞設的眾子：屬音拿的，有音拿族；屬亦施韋的，有亦施韋族；屬比利亞的，有比利亞族。","notes":[]},{"n":45,"t":"比利亞的眾子：屬希別的，有希別族；屬瑪結的，有瑪結族。","notes":[]},{"n":46,"t":"亞設的女兒名叫西拉。","notes":[]},{"n":47,"t":"這就是亞設子孫的各族；他們被數的共有五萬三千四百名。","notes":[]},{"n":48,"t":"按著宗族，拿弗他利的眾子：屬雅薛的，有雅薛族；屬沽尼的，有沽尼族；","notes":[]},{"n":49,"t":"屬耶色的，有耶色族；屬示冷的，有示冷族。","notes":[]},{"n":50,"t":"按著宗族，這就是拿弗他利的各族；他們被數的共有四萬五千四百名。","notes":[]},{"n":51,"t":"這就是以色列人中被數的，共有六十萬零一千七百三十名。","notes":[]},{"n":52,"t":"耶和華吩咐摩西說：","notes":[]},{"n":53,"t":"「你要按著人名的數目，將地分給這些人為產業。","notes":[]},{"n":54,"t":"人多的要多給他們產業，人少的要少給他們產業；各照被數的人數分配產業。","notes":[]},{"n":55,"t":"此外，要以抽籤來分地，按著父系各支派的名字承受產業。","notes":[]},{"n":56,"t":"要根據抽籤，看人數的多寡，給他們分配產業。」","notes":[]},{"n":57,"t":"這就是按著宗族，被數的利未人：屬革順的，有革順族；屬哥轄的，有哥轄族；屬米拉利的，有米拉利族。","notes":[]},{"n":58,"t":"這就是利未的宗族：立尼族、希伯倫族、瑪利族、母示族、可拉族。哥轄生暗蘭。","notes":[]},{"n":59,"t":"暗蘭的妻子名叫約基別，是利未的女兒，是利未在埃及所生的。她給暗蘭生了亞倫、摩西，和他們的姊姊米利暗。","notes":[]},{"n":60,"t":"亞倫生拿答、亞比戶、以利亞撒、以他瑪。","notes":[]},{"n":61,"t":"拿答、亞比戶在耶和華面前獻凡火的時候死了。","notes":[]},{"n":62,"t":"利未人中，凡一個月以上所有被數的男子，共有二萬三千名。他們沒有數在以色列人中；因為在以色列人中，沒有分給他們產業。","notes":[]},{"n":63,"t":"這些是摩西和以利亞撒祭司所數的；他們在摩押平原與耶利哥相對的約旦河邊數點以色列人。","notes":[]},{"n":64,"t":"這些被數的人中，沒有一個是摩西和亞倫祭司先前在西奈曠野所數的以色列人，","notes":[]},{"n":65,"t":"因為耶和華論到他們說：「他們必死在曠野。」所以，除了耶孚尼的兒子迦勒和嫩的兒子約書亞以外，他們一個也沒有存留。","notes":[]}]},"27":{"heading":"西羅非哈的女兒","verses":[{"n":1,"t":"約瑟的兒子瑪拿西的宗族中，有瑪拿西的玄孫，瑪吉的曾孫，基列的孫子，希弗的兒子西羅非哈的女兒，名叫瑪拉、挪阿、曷拉、密迦、得撒。她們前來，","notes":[]},{"n":2,"t":"站在會幕門口，在摩西和以利亞撒祭司，以及眾領袖與全會眾面前，說：","notes":[]},{"n":3,"t":"「我們的父親死在曠野。他沒有與可拉同夥聚集攻擊耶和華，是在自己的罪中死的；他沒有兒子。","notes":[]},{"n":4,"t":"為甚麼因我們的父親沒有兒子就把他的名從他族中除掉呢？求你們在我們父親的兄弟中分給我們產業。」","notes":[]},{"n":5,"t":"於是，摩西將她們的案件呈到耶和華面前。","notes":[]},{"n":6,"t":"耶和華對摩西說：","notes":[]},{"n":7,"t":"「西羅非哈的女兒說得有理。你定要在她們父親的兄弟中，把地分給她們為業，把她們父親的產業傳給她們。","notes":[]},{"n":8,"t":"你也要吩咐以色列人說：『人死了，若沒有兒子，就要把他的產業傳給他的女兒。","notes":[]},{"n":9,"t":"他若沒有女兒，就要把他的產業給他的兄弟。","notes":[]},{"n":10,"t":"他若沒有兄弟，就要把他的產業給他父親的兄弟。","notes":[]},{"n":11,"t":"他父親若沒有兄弟，就要把他的產業給他族中最近的親屬繼承為業。』」這要作以色列人的律例典章，是照耶和華所吩咐摩西的。","notes":[]},{"n":12,"t":"耶和華對摩西說：「你上這亞巴琳山脈，看我所賜給以色列人的地。","notes":[],"heads":["約書亞被選為摩西的繼承人"]},{"n":13,"t":"看了以後，你也必歸到你祖先那裏，像你哥哥亞倫歸去一樣。","notes":["「你祖先」：原文是「你百姓」。"]},{"n":14,"t":"因為你們在尋的曠野，當會眾爭鬧的時候，違背了我的命令，在取水之事上沒有在會眾眼前尊我為聖。」這水就是尋的曠野中，加低斯的米利巴水。","notes":[]},{"n":15,"t":"摩西對耶和華說：","notes":[]},{"n":16,"t":"「願耶和華，賜萬人氣息的神，立一個人治理會眾，","notes":[]},{"n":17,"t":"可以在他們面前出入，引導他們進出，免得耶和華的會眾如同沒有牧人的羊群一般。」","notes":[]},{"n":18,"t":"耶和華對摩西說：「嫩的兒子約書亞是一個有聖靈的人；你要領他來，為他按手，","notes":[]},{"n":19,"t":"使他站在以利亞撒祭司和全會眾面前，在他們眼前委派他，","notes":[]},{"n":20,"t":"又將你的尊榮給他一些，好使以色列全會眾都聽從他。","notes":[]},{"n":21,"t":"他要站在以利亞撒祭司面前；以利亞撒要憑烏陵的判斷，在耶和華面前為他求問。他和以色列全會眾都要照以利亞撒的指示出入。」","notes":[]},{"n":22,"t":"於是摩西照耶和華所吩咐他的，將約書亞領來，使他站在以利亞撒祭司和全會眾面前，","notes":[]},{"n":23,"t":"為他按手，委派他，是照耶和華藉摩西所說的。","notes":[]}]},"28":{"heading":"每日經常獻的祭","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人說：『你們要按時把我的供物，就是獻給我作馨香火祭的食物，獻給我。』","notes":[]},{"n":3,"t":"要對他們說：『這是當獻給耶和華的火祭：每天兩隻沒有殘疾一歲的小公羊，作為經常獻的燔祭。","notes":[]},{"n":4,"t":"早晨獻第一隻小公羊，黃昏獻第二隻小公羊；","notes":[]},{"n":5,"t":"又用十分之一伊法細麵和四分之一欣搗成的油，調和作為素祭。","notes":[]},{"n":6,"t":"這是在西奈山上規定為經常獻的燔祭，是獻給耶和華為馨香的火祭。","notes":[]},{"n":7,"t":"為每隻小公羊，要有四分之一欣的澆酒祭；在聖所中，你要將醇酒獻給耶和華作澆酒祭。","notes":[]},{"n":8,"t":"黃昏你獻第二隻小公羊，要照早晨的素祭和同獻的澆酒祭獻上，作為馨香的火祭，獻給耶和華。』」","notes":[]},{"n":9,"t":"「在安息日，要獻兩隻沒有殘疾，一歲的小公羊、十分之二伊法調了油的細麵為素祭，和同獻的澆酒祭。","notes":[],"heads":["安息日獻的祭"]},{"n":10,"t":"除了經常獻的燔祭和同獻的澆酒祭之外，這是每一個安息日當獻的燔祭。」","notes":[]},{"n":11,"t":"「每月初一，要將兩頭公牛犢、一隻公綿羊、七隻沒有殘疾一歲的小公羊，獻給耶和華為燔祭。","notes":[],"heads":["初一獻的祭"]},{"n":12,"t":"為每頭公牛，要用十分之三伊法調了油的細麵作為素祭；為那隻公綿羊，要用十分之二伊法調了油的細麵作為素祭；","notes":[]},{"n":13,"t":"為每隻小公羊，要用十分之一伊法調了油的細麵作為素祭。這是馨香的燔祭，是獻給耶和華的火祭。","notes":[]},{"n":14,"t":"每頭公牛要有半欣的澆酒祭，每隻公綿羊三分之一欣的澆酒祭，每隻小公羊四分之一欣的澆酒祭。這是一年之中每月初一當獻的燔祭。","notes":[]},{"n":15,"t":"除了經常獻的燔祭和同獻的澆酒祭之外，又要將一隻公山羊，獻給耶和華為贖罪祭。」","notes":[]},{"n":16,"t":"「正月十四日是向耶和華守的逾越節。","notes":[],"heads":["逾越節獻的祭"]},{"n":17,"t":"這月十五日是節期，要吃無酵餅七日。","notes":[]},{"n":18,"t":"第一日要有聖會，任何勞動的工都不可做。","notes":[]},{"n":19,"t":"要把火祭，就是兩頭公牛犢，一隻公綿羊、七隻一歲的小公羊，都要沒有殘疾的，獻給耶和華為燔祭。","notes":[]},{"n":20,"t":"要同時獻調了油的細麵為素祭：每頭公牛要獻十分之三伊法；每隻公綿羊要獻十分之二伊法；","notes":[]},{"n":21,"t":"為那七隻小公羊，每隻要獻十分之一伊法。","notes":[]},{"n":22,"t":"此外，要獻一隻公山羊作贖罪祭，為你們贖罪。","notes":[]},{"n":23,"t":"除了早晨經常獻的燔祭之外，你們也要獻這些祭。","notes":[]},{"n":24,"t":"一連七天，在經常獻的燔祭和同獻的澆酒祭之外，每天要這樣把馨香火祭的食物獻給耶和華。","notes":[]},{"n":25,"t":"第七日要有聖會，任何勞動的工都不可做。」","notes":[]},{"n":26,"t":"「七七初熟節，就是你們獻初熟穀物給耶和華為素祭的那一天，要宣告聖會；任何勞動的工都不可做。","notes":[],"heads":["七七初熟節獻的祭"]},{"n":27,"t":"要將兩頭公牛犢，一隻公綿羊，七隻一歲的小公羊，作為馨香的燔祭獻給耶和華。","notes":[]},{"n":28,"t":"要同時獻調了油的細麵為素祭：每頭公牛要獻十分之三伊法；每隻公綿羊要獻十分之二伊法；","notes":[]},{"n":29,"t":"為那七隻小公羊，每隻要獻十分之一伊法。","notes":[]},{"n":30,"t":"此外，要獻一隻公山羊為你們贖罪。","notes":[]},{"n":31,"t":"除了經常獻的燔祭和同獻的素祭，你們也要獻上這些沒有殘疾的，和同獻的澆酒祭。」","notes":[]}]},"29":{"heading":"新年獻的祭","verses":[{"n":1,"t":"「七月初一，你們當有聖會；任何勞動的工都不可做，是你們當守為吹角的日子。","notes":[]},{"n":2,"t":"你們要將一頭公牛犢、一隻公綿羊、七隻一歲的小公羊，都是沒有殘疾的，獻給耶和華為馨香的燔祭。","notes":[]},{"n":3,"t":"要同時獻調了油的細麵為素祭：每頭公牛要獻十分之三伊法；每隻公綿羊要獻十分之二伊法；","notes":[]},{"n":4,"t":"為那七隻小公羊，每隻要獻十分之一伊法。","notes":[]},{"n":5,"t":"此外，要獻一隻公山羊作贖罪祭，為你們贖罪。","notes":[]},{"n":6,"t":"除了初一的燔祭和同獻的素祭、經常獻的燔祭與同獻的素祭，以及同獻的澆酒祭以外，這些都照例作為馨香的火祭獻給耶和華。」","notes":[]},{"n":7,"t":"「七月初十，你們當有聖會；要刻苦己心，任何工都不可做。","notes":[],"heads":["贖罪日獻的祭"]},{"n":8,"t":"要將一頭公牛犢、一隻公綿羊、七隻一歲的小公羊，都是沒有殘疾的，獻給耶和華為馨香的燔祭。","notes":[]},{"n":9,"t":"要同時獻調了油的細麵為素祭：每頭公牛要獻十分之三伊法；每隻公綿羊要獻十分之二伊法；","notes":[]},{"n":10,"t":"為那七隻小公羊，每隻要獻十分之一伊法。","notes":[]},{"n":11,"t":"又要獻一隻公山羊為贖罪祭。這是在贖罪祭和經常獻的燔祭，以及同獻的素祭和澆酒祭以外所獻的。」","notes":[]},{"n":12,"t":"「七月十五日，你們當有聖會；任何勞動的工都不可做，要向耶和華守節七天。","notes":[],"heads":["住棚節獻的祭"]},{"n":13,"t":"要將十三頭公牛犢、兩隻公綿羊、十四隻一歲的小公羊，都是沒有殘疾的，獻上作火祭，是獻給耶和華馨香的燔祭。","notes":[]},{"n":14,"t":"要同時獻調了油的細麵為素祭：為那十三頭公牛犢，每頭要獻十分之三伊法；為那兩隻公綿羊，每隻要獻十分之二伊法；","notes":[]},{"n":15,"t":"為那十四隻小公羊，每隻要獻十分之一伊法。","notes":[]},{"n":16,"t":"又要獻一隻公山羊為贖罪祭。這是在經常獻的燔祭、同獻的素祭和澆酒祭以外所獻的。","notes":[]},{"n":17,"t":"「第二日要獻十二頭公牛犢、兩隻公綿羊、十四隻一歲的小公羊，都是沒有殘疾的，","notes":[]},{"n":18,"t":"並為公牛、公綿羊和小公羊，按數照例奉獻同獻的素祭和澆酒祭。","notes":[]},{"n":19,"t":"又要獻一隻公山羊為贖罪祭。這是在經常獻的燔祭、同獻的素祭和澆酒祭以外所獻的。","notes":[]},{"n":20,"t":"「第三日要獻十一頭公牛、兩隻公綿羊、十四隻一歲的小公羊，都是沒有殘疾的，","notes":[]},{"n":21,"t":"並為公牛、公綿羊和小公羊，按數照例奉獻同獻的素祭和澆酒祭。","notes":[]},{"n":22,"t":"又要獻一隻公山羊為贖罪祭。這是在經常獻的燔祭、同獻的素祭和澆酒祭以外所獻的。","notes":[]},{"n":23,"t":"「第四日要獻十頭公牛、兩隻公綿羊、十四隻一歲的小公羊，都是沒有殘疾的，","notes":[]},{"n":24,"t":"並為公牛、公綿羊和小公羊，按數照例奉獻同獻的素祭和澆酒祭。","notes":[]},{"n":25,"t":"又要獻一隻公山羊為贖罪祭。這是在經常獻的燔祭、同獻的素祭和澆酒祭以外所獻的。","notes":[]},{"n":26,"t":"「第五日要獻九頭公牛、兩隻公綿羊、十四隻一歲的小公羊，都是沒有殘疾的，","notes":[]},{"n":27,"t":"並為公牛、公綿羊和小公羊，按數照例奉獻同獻的素祭和澆酒祭。","notes":[]},{"n":28,"t":"又要獻一隻公山羊為贖罪祭。這是在經常獻的燔祭、同獻的素祭和澆酒祭以外所獻的。","notes":[]},{"n":29,"t":"「第六日要獻八頭公牛、兩隻公綿羊、十四隻一歲的小公羊，都是沒有殘疾的，","notes":[]},{"n":30,"t":"並為公牛、公綿羊和小公羊，按數照例奉獻同獻的素祭和澆酒祭。","notes":[]},{"n":31,"t":"又要獻一隻公山羊為贖罪祭。這是在經常獻的燔祭、同獻的素祭和澆酒祭以外所獻的。","notes":[]},{"n":32,"t":"「第七日要獻七頭公牛、兩隻公綿羊、十四隻一歲的小公羊，都是沒有殘疾的，","notes":[]},{"n":33,"t":"並為公牛、公綿羊和小公羊，按數照例奉獻同獻的素祭和澆酒祭。","notes":[]},{"n":34,"t":"又要獻一隻公山羊為贖罪祭。這是在經常獻的燔祭、同獻的素祭和澆酒祭以外所獻的。","notes":[]},{"n":35,"t":"「第八日你們當有嚴肅會；任何勞動的工都不可做；","notes":[]},{"n":36,"t":"要將一頭公牛、一隻公綿羊、七隻一歲的小公羊，都是沒有殘疾的，獻上作火祭，是獻給耶和華馨香的燔祭。","notes":[]},{"n":37,"t":"要為公牛、公綿羊和小公羊，按數照例奉獻同獻的素祭和澆酒祭。","notes":[]},{"n":38,"t":"又要獻一隻公山羊為贖罪祭。這是在經常獻的燔祭、同獻的素祭和澆酒祭以外所獻的。","notes":[]},{"n":39,"t":"「這些祭要在你們的節期獻給耶和華，都是在所許的願和甘心獻的以外所獻的，作為你們的燔祭、素祭、澆酒祭和平安祭。」","notes":[]},{"n":40,"t":"於是，摩西照耶和華所吩咐他的一切話告訴以色列人。","notes":[]}]},"30":{"heading":"許願的條例","verses":[{"n":1,"t":"摩西對以色列各支派的領袖說：「這是耶和華所吩咐的話：","notes":[]},{"n":2,"t":"人若向耶和華許願或起誓，要約束自己，就不可食言，必須照口中所出的一切話去做。","notes":[]},{"n":3,"t":"女子年輕，還在父家的時候，若向耶和華許願，要約束自己，","notes":[]},{"n":4,"t":"她父親聽見她所許的願和約束自己的話，卻向她默默不言，她所許的願和約束自己的話就都有效。","notes":[]},{"n":5,"t":"但是，若她父親在聽見的日子不允許她一切所許的願和約束自己的話，這就不算為有效；耶和華也必赦免她，因為她的父親不允許。","notes":[]},{"n":6,"t":"她若已出嫁，有願在身，或口中出了約束自己的冒失話，","notes":[]},{"n":7,"t":"她丈夫聽見了，卻在聽見的日子向她默默不言，她所許的願和約束自己的話就都有效。","notes":[]},{"n":8,"t":"但是，若她丈夫在聽見的日子不允許，丈夫就廢了她所許的願和口中所出約束自己的冒失話；耶和華也必赦免她。","notes":[]},{"n":9,"t":"寡婦或被休的婦人所許的願，她所有約束自己的話，都是有效的。","notes":[]},{"n":10,"t":"她若在丈夫家裏許了願或起了誓，要約束自己，","notes":[]},{"n":11,"t":"丈夫聽見了，卻向她默默不言，沒有不允許，她所許的願和約束自己的話就都有效。","notes":[]},{"n":12,"t":"她丈夫聽見的日子，若把這些全廢了，她口中一切所許的願或約束自己的話就不算為有效。她丈夫已把這些都廢了，耶和華也必赦免她。","notes":[]},{"n":13,"t":"凡她所許的願和刻苦約束自己所起的誓，丈夫可以堅立，也可以廢去。","notes":[]},{"n":14,"t":"倘若她丈夫天天向她默默不言，這就算是堅立她一切所許的願或約束自己的話；因為丈夫在聽見的日子向她默默不言，就算是堅立了這些話。","notes":[]},{"n":15,"t":"但她丈夫聽見了，以後若再廢了這些話，就要擔當婦人的罪孽。」","notes":[]},{"n":16,"t":"這是關於丈夫待妻子，父親待女兒，女兒年輕還在父家，耶和華所吩咐摩西的條例。","notes":[]}]},"31":{"heading":"戰勝米甸人","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要為以色列人向米甸人報仇，然後歸到你祖先那裏。」","notes":["「你祖先」：原文是「你百姓」。"]},{"n":3,"t":"摩西吩咐百姓說：「要在你們中間叫人帶兵器去攻擊米甸，為耶和華向米甸報仇。","notes":[]},{"n":4,"t":"從以色列眾支派中，每支派要派一千人去打仗。」","notes":[]},{"n":5,"t":"於是從以色列千萬人中，每支派徵召一千人，一共一萬二千名，帶著兵器預備打仗。","notes":[]},{"n":6,"t":"摩西派他們去打仗，每支派一千人；又派以利亞撒祭司的兒子非尼哈同去；非尼哈手裏拿著聖所的器皿和吹號的號筒。","notes":[]},{"n":7,"t":"他們遵照耶和華所吩咐摩西的，與米甸打仗，殺了所有的男丁。","notes":[]},{"n":8,"t":"在所殺的人中，他們殺了米甸的王，就是以未、利金、蘇珥、戶珥、利巴五個米甸的王，又用刀殺了比珥的兒子巴蘭。","notes":[]},{"n":9,"t":"以色列人擄了米甸的婦女和孩童，搶奪他們一切的牲畜、牛羊和所有的財物，","notes":[]},{"n":10,"t":"又用火焚燒了他們所住的一切城鎮和所有的營寨。","notes":[]},{"n":11,"t":"以色列人把一切擄物和掠物，連人和牲畜都帶走，","notes":[]},{"n":12,"t":"將俘虜、掠物、擄物帶到摩押平原，在約旦河邊與耶利哥相對的營地，交給摩西和以利亞撒祭司，以及以色列的會眾。","notes":[]},{"n":13,"t":"摩西和以利亞撒祭司，以及會眾中所有的領袖，都出營迎接他們。","notes":[],"heads":["軍隊返回"]},{"n":14,"t":"摩西向打仗回來的軍官，就是千夫長和百夫長發怒。","notes":[]},{"n":15,"t":"摩西對他們說：「你們要讓這所有的婦女活著嗎？","notes":[]},{"n":16,"t":"看哪，正是這些婦女，因巴蘭的話，在毗珥的事上導致以色列人背叛耶和華，以致耶和華的會眾遭遇瘟疫。","notes":[]},{"n":17,"t":"現在，你們要殺所有的男孩，也要把所有曾與男人同房共寢的女子都殺了。","notes":[]},{"n":18,"t":"但那些未曾與男人同房共寢的女孩，你們可以讓她們存活。","notes":[]},{"n":19,"t":"你們和你們所擄來的人，要住在營外七天；凡殺了人的，和一切摸了屍體的，要在第三日和第七日潔淨自己。","notes":[]},{"n":20,"t":"你們也要潔淨一切的衣服，以及用皮革、山羊毛和木頭做的任何東西。」","notes":[]},{"n":21,"t":"以利亞撒祭司對打仗回來的士兵說：「耶和華所吩咐摩西律法中的條例是這樣：","notes":[]},{"n":22,"t":"金、銀、銅、鐵、錫、鉛，","notes":[]},{"n":23,"t":"凡能耐火的，你們要使它經過火，它就潔淨，然而還要用除污穢的水來潔淨它；凡不能耐火的，你們要使它經過水。","notes":[]},{"n":24,"t":"第七日，你們要洗衣服，才為潔淨，然後可以進營。」","notes":[]},{"n":25,"t":"耶和華對摩西說：","notes":[],"heads":["分戰利品"]},{"n":26,"t":"「你和以利亞撒祭司，以及會眾的各父系家長，要計算所擄掠的人和牲畜的總數。","notes":[]},{"n":27,"t":"要把所擄掠的分成兩半：一半給那出去打仗的精兵，一半給全會眾。","notes":[]},{"n":28,"t":"再從那出去打仗的戰士所得的人、牛、驢、羊中，每五百取一，獻給耶和華為貢物。","notes":[]},{"n":29,"t":"要從他們那一半中取出這些，交給以利亞撒祭司，作為耶和華的舉祭。","notes":[]},{"n":30,"t":"又要從以色列人的那一半中，就是從人、牛、驢、羊，各樣牲畜中，每五十取一，交給照管耶和華帳幕的利未人。」","notes":[]},{"n":31,"t":"於是摩西和以利亞撒祭司遵照耶和華所吩咐摩西的做了。","notes":[]},{"n":32,"t":"除了士兵所奪的財物以外，所擄來的有羊六十七萬五千隻，","notes":[]},{"n":33,"t":"牛七萬二千頭，","notes":[]},{"n":34,"t":"驢六萬一千匹；","notes":[]},{"n":35,"t":"至於人，就是未曾與男人同房共寢的女子，總共三萬二千名。","notes":[]},{"n":36,"t":"出去打仗之人的那份，就是他們所得的一半，共計羊三十三萬七千五百隻，","notes":[]},{"n":37,"t":"其中歸耶和華為貢物的羊，六百七十五隻；","notes":[]},{"n":38,"t":"牛三萬六千頭，其中歸耶和華為貢物的七十二頭；","notes":[]},{"n":39,"t":"驢三萬零五百匹，其中歸耶和華為貢物的六十一匹；","notes":[]},{"n":40,"t":"人一萬六千名，其中歸耶和華的三十二名。","notes":[]},{"n":41,"t":"摩西把貢物，就是歸給耶和華的舉祭，交給以利亞撒祭司，是照耶和華所吩咐摩西的。","notes":[]},{"n":42,"t":"以色列人所得的另一半，是摩西從打仗的人取來分給他們的。","notes":[]},{"n":43,"t":"會眾的這一半有羊三十三萬七千五百隻，","notes":[]},{"n":44,"t":"牛三萬六千頭，","notes":[]},{"n":45,"t":"驢三萬零五百匹，","notes":[]},{"n":46,"t":"人一萬六千名。","notes":[]},{"n":47,"t":"無論是人或牲畜，摩西都每五十取一，交給照管耶和華帳幕的利未人，是照耶和華所吩咐摩西的。","notes":[]},{"n":48,"t":"帶領眾軍隊的軍官，就是千夫長、百夫長，進到摩西那裏，","notes":[]},{"n":49,"t":"對他說：「你的僕人已經計算屬下戰士的總數，一個也沒有少。","notes":[]},{"n":50,"t":"如今我們把各人所得的金器，就是腳鏈子、手鐲、打印的戒指、耳環、項鏈，都送給耶和華為供物，好在耶和華面前為我們贖罪。」","notes":[]},{"n":51,"t":"摩西和以利亞撒祭司就收了他們的金子，就是各樣的首飾。","notes":[]},{"n":52,"t":"千夫長、百夫長所獻給耶和華為舉祭的金子共有一萬六千七百五十舍客勒。","notes":[]},{"n":53,"t":"打仗的人都把自己所掠奪的各自留下。","notes":[]},{"n":54,"t":"摩西和以利亞撒祭司收了千夫長、百夫長的金子，就帶進會幕，好使以色列人在耶和華面前蒙記念。","notes":[]}]},"32":{"heading":"約旦河東的支派","verses":[{"n":1,"t":"呂便子孫和迦得子孫的牲畜極其眾多。他們看到雅謝地和基列地；看哪，這是可牧放牲畜的地方。","notes":[]},{"n":2,"t":"呂便子孫和迦得子孫就到摩西和以利亞撒祭司，以及會眾的領袖那裏，說：","notes":[]},{"n":3,"t":"「亞他錄、底本、雅謝、寧拉、希實本、以利亞利、示班、尼波、比穩，","notes":[]},{"n":4,"t":"就是耶和華在以色列會眾面前所攻取之地，是可牧放牲畜之地，而你的僕人也有牲畜。」","notes":[]},{"n":5,"t":"又說：「我們若在你眼前蒙恩，求你把這地給我們為業；不要領我們過約旦河。」","notes":[]},{"n":6,"t":"摩西對迦得子孫和呂便子孫說：「難道你們的弟兄去打仗，你們卻留在這裏嗎？","notes":[]},{"n":7,"t":"你們為甚麼使以色列人灰心，不渡過去，進入耶和華所賜給他們的那地呢？","notes":[]},{"n":8,"t":"我從加低斯‧巴尼亞派你們的父執之輩去窺探那地時，他們就曾這樣做過。","notes":[]},{"n":9,"t":"他們上到以實各谷，窺探了那地之後，竟然使以色列人灰心，不願進入耶和華所賜給他們的地。","notes":[]},{"n":10,"t":"當日，耶和華的怒氣發作，起誓說：","notes":[]},{"n":11,"t":"『凡從埃及上來二十歲以上的人，斷不得看見我對亞伯拉罕、以撒、雅各起誓應許之地，因為他們沒有專心跟從我；","notes":[]},{"n":12,"t":"惟有基尼洗族耶孚尼的兒子迦勒，還有嫩的兒子約書亞可以看見，因為他們專心跟從耶和華。』","notes":[]},{"n":13,"t":"耶和華的怒氣向以色列發作，使他們在曠野飄流四十年，直到在耶和華眼前作惡的那一代都消滅了。","notes":[]},{"n":14,"t":"看哪，你們這一夥罪人，竟然接續你們父執之輩，再增加耶和華對以色列所發的怒氣。","notes":[]},{"n":15,"t":"你們若轉離不跟從他，他要再把以色列人撇在曠野；這樣，你們就使這眾百姓滅亡了。」","notes":[]},{"n":16,"t":"他們挨近摩西，說：「我們要在這裏為牲畜築圈，為孩童建城。","notes":[]},{"n":17,"t":"我們自己卻要帶兵器，急速行在以色列人的前面，領他們直到他們的地方。我們的孩童可以留在堅固的城內，躲避當地的居民。","notes":[]},{"n":18,"t":"我們必不回自己的家，直等到以色列人各自承受了自己的產業。","notes":[]},{"n":19,"t":"我們不和他們在約旦河那邊分產業，因為我們的產業是在約旦河的東邊。」","notes":[]},{"n":20,"t":"摩西對他們說：「你們若要這麼做，若要在耶和華面前帶著兵器出去打仗，","notes":[]},{"n":21,"t":"你們中間所有帶兵器的人都要在耶和華面前過約旦河，直到耶和華把仇敵從他面前趕出去。","notes":[]},{"n":22,"t":"那地在耶和華面前被征服以後，你們方可回來。這樣，你們向耶和華和以色列才算為無罪，這地也必在耶和華面前歸你們為業。","notes":[]},{"n":23,"t":"倘若你們不這樣做，看哪，你們就得罪了耶和華，當知道你們的罪必找上你們。","notes":[]},{"n":24,"t":"如今你們可以為孩童建城，為羊群築圈，但你們口所講出來的話，必須實踐。」","notes":[]},{"n":25,"t":"迦得子孫和呂便子孫對摩西說：「你的僕人們必照我主所吩咐的去做。","notes":[]},{"n":26,"t":"我們的孩子、妻子、牛羊和所有的牲畜都要留在基列的各城。","notes":[]},{"n":27,"t":"但你的僕人，凡能帶兵器上戰場的，都要照我主所說的話，在耶和華面前渡過去打仗。」","notes":[]},{"n":28,"t":"於是，摩西為他們吩咐以利亞撒祭司和嫩的兒子約書亞，以及以色列人各支派父系的領袖。","notes":[]},{"n":29,"t":"摩西對他們說：「迦得子孫和呂便子孫，凡帶兵器在耶和華面前去打仗的，若與你們一同渡過約旦河，那地被你們征服以後，你們就要把基列地給他們為業。","notes":[]},{"n":30,"t":"倘若他們不帶兵器與你們一同渡過去，他們就要在迦南地你們中間得產業。」","notes":[]},{"n":31,"t":"迦得子孫和呂便子孫回答說：「耶和華怎樣吩咐僕人，我們就必照樣做。","notes":[]},{"n":32,"t":"我們自己必帶著兵器，在耶和華面前渡過去，進入迦南地，好使我們在約旦河這邊得到我們的產業。」","notes":[]},{"n":33,"t":"摩西把亞摩利王西宏的國和巴珊王噩的國，就是他們的國土和周圍的城鎮，都給了迦得子孫和呂便子孫，以及約瑟的兒子瑪拿西半個支派。","notes":[]},{"n":34,"t":"迦得子孫建造了底本、亞他錄、亞羅珥、","notes":[]},{"n":35,"t":"亞他錄‧朔反、雅謝、約比哈、","notes":[]},{"n":36,"t":"伯‧寧拉、伯‧哈蘭，都是堅固城，並築有羊圈。","notes":[]},{"n":37,"t":"呂便子孫建造了希實本、以利亞利、基列亭、","notes":[]},{"n":38,"t":"尼波、巴力‧免（名字是改了的）、西比瑪；他們給建造的城另起別名。","notes":[]},{"n":39,"t":"瑪拿西的兒子瑪吉的子孫往基列去，佔了那地，趕出那裏的亞摩利人。","notes":[]},{"n":40,"t":"摩西把基列賜給瑪拿西的兒子瑪吉，他就住在那裏。","notes":[]},{"n":41,"t":"瑪拿西的子孫睚珥佔了基列的城鎮，就稱這些城鎮為哈倭特‧睚珥。","notes":[]},{"n":42,"t":"挪巴佔了基納和基納的鄉鎮，就照自己的名字稱基納為挪巴。","notes":[]}]},"33":{"heading":"從埃及到摩押","verses":[{"n":1,"t":"這是以色列人按著隊伍，在摩西、亞倫的手下，出埃及地的行程。","notes":[]},{"n":2,"t":"摩西遵照耶和華的指示記錄他們每段行程的起點，這些行程的起點如下：","notes":[]},{"n":3,"t":"第一個月，就是正月十五日，逾越的第二天，他們從蘭塞起行，在所有埃及人的眼前抬起頭來出去了。","notes":["「抬起頭」：原文是「舉起手」。"]},{"n":4,"t":"那時，埃及人正埋葬他們的長子，就是耶和華在他們中間所擊殺的；耶和華也懲治了他們的眾神明。","notes":[]},{"n":5,"t":"以色列人從蘭塞起行，安營在疏割。","notes":[]},{"n":6,"t":"從疏割起行，安營在曠野邊上的以倘。","notes":[]},{"n":7,"t":"從以倘起行，轉向巴力‧洗分對面的比‧哈希錄，安營在密奪。","notes":[]},{"n":8,"t":"從比‧哈希錄起行，經過海，進入曠野，在以倘的曠野走了三天的路程，就安營在瑪拉。","notes":[]},{"n":9,"t":"從瑪拉起行，來到以琳，以琳有十二股水泉，七十棵棕樹，就安營在那裏。","notes":[]},{"n":10,"t":"從以琳起行，安營在紅海邊。","notes":[]},{"n":11,"t":"從紅海邊起行，安營在汛的曠野。","notes":[]},{"n":12,"t":"從汛的曠野起行，安營在脫加。","notes":[]},{"n":13,"t":"從脫加起行，安營在亞錄。","notes":[]},{"n":14,"t":"從亞錄起行，安營在利非訂；在那裏，百姓沒有水喝。","notes":[]},{"n":15,"t":"從利非訂起行，安營在西奈的曠野。","notes":[]},{"n":16,"t":"從西奈的曠野起行，安營在基博羅‧哈他瓦。","notes":[]},{"n":17,"t":"從基博羅‧哈他瓦起行，安營在哈洗錄。","notes":[]},{"n":18,"t":"從哈洗錄起行，安營在利提瑪。","notes":[]},{"n":19,"t":"從利提瑪起行，安營在臨門‧帕烈。","notes":[]},{"n":20,"t":"從臨門‧帕烈起行，安營在立拿。","notes":[]},{"n":21,"t":"從立拿起行，安營在勒撒。","notes":[]},{"n":22,"t":"從勒撒起行，安營在基希拉他。","notes":[]},{"n":23,"t":"從基希拉他起行，安營在沙斐山。","notes":[]},{"n":24,"t":"從沙斐山起行，安營在哈拉大。","notes":[]},{"n":25,"t":"從哈拉大起行，安營在瑪吉希錄。","notes":[]},{"n":26,"t":"從瑪吉希錄起行，安營在他哈。","notes":[]},{"n":27,"t":"從他哈起行，安營在他拉。","notes":[]},{"n":28,"t":"從他拉起行，安營在密加。","notes":[]},{"n":29,"t":"從密加起行，安營在哈摩拿。","notes":[]},{"n":30,"t":"從哈摩拿起行，安營在摩西錄。","notes":[]},{"n":31,"t":"從摩西錄起行，安營在比尼‧亞干。","notes":[]},{"n":32,"t":"從比尼‧亞干起行，安營在曷‧哈及甲。","notes":[]},{"n":33,"t":"從曷‧哈及甲起行，安營在約巴他。","notes":[]},{"n":34,"t":"從約巴他起行，安營在阿博拿。","notes":[]},{"n":35,"t":"從阿博拿起行，安營在以旬‧迦別。","notes":[]},{"n":36,"t":"從以旬‧迦別起行，安營在尋的曠野，就是加低斯。","notes":[]},{"n":37,"t":"從加低斯起行，安營在以東地邊界的何珥山。","notes":[]},{"n":38,"t":"以色列人出埃及地後四十年，五月初一，亞倫祭司遵照耶和華的指示，上何珥山，死在那裏。","notes":[]},{"n":39,"t":"亞倫死在何珥山的時候一百二十三歲。","notes":[]},{"n":40,"t":"住在迦南地尼革夫的迦南人亞拉得王聽說以色列人來了。","notes":[]},{"n":41,"t":"以色列人從何珥山起行，安營在撒摩拿。","notes":[]},{"n":42,"t":"從撒摩拿起行，安營在普嫩。","notes":[]},{"n":43,"t":"從普嫩起行，安營在阿伯。","notes":[]},{"n":44,"t":"從阿伯起行，安營在摩押境內的以耶‧亞巴琳。","notes":[]},{"n":45,"t":"從以耶‧亞巴琳起行，安營在底本‧迦得。","notes":[]},{"n":46,"t":"從底本‧迦得起行，安營在亞門‧低比拉太音。","notes":[]},{"n":47,"t":"從亞門‧低比拉太音起行，安營在尼波前面的亞巴琳山脈。","notes":[]},{"n":48,"t":"從亞巴琳山脈起行，安營在約旦河邊，耶利哥對面的摩押平原。","notes":[]},{"n":49,"t":"他們在摩押平原，沿著約旦河安營，從伯‧耶施末直到亞伯‧什亭。","notes":[]},{"n":50,"t":"耶和華在約旦河邊，耶利哥對面的摩押平原吩咐摩西說：","notes":[],"heads":["過約旦河前的指示"]},{"n":51,"t":"「你要吩咐以色列人說：你們過約旦河進迦南地的時候，","notes":[]},{"n":52,"t":"要從你們面前趕出那地所有的居民，摧毀他們一切的石像和鑄成的偶像，也要拆毀他們一切的丘壇。","notes":[]},{"n":53,"t":"你們要佔領那地，住在那裏，因我已把那地賜給你們為業。","notes":[]},{"n":54,"t":"你們要按照宗族抽籤，承受土地：人多的要多給他們產業；人少的要少給他們產業。抽到何地給何人，那地就屬於他。你們要按照父系的支派承受產業。","notes":[]},{"n":55,"t":"倘若你們不把那地的居民從你們面前趕出去，那留下的居民就必成為你們眼中的刺，肋下的荊棘，也必在你們所住的地上擾亂你們；","notes":[]},{"n":56,"t":"我想要怎樣待他們，也必照樣待你們。」","notes":[]}]},"34":{"heading":"迦南的地界","verses":[{"n":1,"t":"耶和華吩咐摩西說：","notes":[]},{"n":2,"t":"「你要吩咐以色列人，對他們說：你們到了迦南地，這就是歸你們為業的地，迦南地和它四周的邊界：","notes":[]},{"n":3,"t":"你們的南邊是從尋的曠野起，沿著以東的邊界；南邊的地界從鹽海東邊開始，","notes":[]},{"n":4,"t":"繞過亞克拉濱斜坡的南邊，經過尋，直通到加低斯‧巴尼亞的南邊，又通到哈薩‧亞達，經過押們，","notes":[]},{"n":5,"t":"從押們轉向埃及溪谷，直通到海。","notes":[]},{"n":6,"t":"「你們西邊的地界要以大海為邊界；這就是你們西邊的地界。","notes":[]},{"n":7,"t":"「你們北邊的地界要從大海開始劃界，直到何珥山，","notes":[]},{"n":8,"t":"從何珥山劃到哈馬口，直通到西達達，","notes":[]},{"n":9,"t":"又通到西斐崙，直達哈薩‧以難。這就是你們北邊的地界。","notes":[]},{"n":10,"t":"「東邊的地界，你們要從哈薩‧以難開始劃界，直到示番，","notes":[]},{"n":11,"t":"這地界要從示番下到亞延東邊的利比拉，這地界要下延到基尼烈海的東邊，","notes":[]},{"n":12,"t":"這地界又下到約旦河，直通到鹽海。這就是你們的地和它四圍的邊界。」","notes":[]},{"n":13,"t":"摩西吩咐以色列人說：「這就是耶和華吩咐抽籤給九個半支派承受為業的地。","notes":[]},{"n":14,"t":"因為呂便子孫的支派按著父家、迦得子孫的支派按著父家，和瑪拿西半個支派已經得到了他們的產業：","notes":[]},{"n":15,"t":"這兩個半支派已經在耶利哥對面，約旦河東邊，向日出的方向承受了產業。」","notes":[]},{"n":16,"t":"耶和華吩咐摩西說：","notes":[],"heads":["負責分地的領袖"]},{"n":17,"t":"「這是為你們分地為業的人的名字：以利亞撒祭司和嫩的兒子約書亞。","notes":[]},{"n":18,"t":"你要從每個支派中選一個領袖來分配產業。","notes":[]},{"n":19,"t":"這些人的名字如下：猶大支派，耶孚尼的兒子迦勒。","notes":[]},{"n":20,"t":"西緬子孫的支派，亞米忽的兒子示母利。","notes":[]},{"n":21,"t":"便雅憫支派，基斯倫的兒子以利達。","notes":[]},{"n":22,"t":"但子孫支派的領袖，約利的兒子布基。","notes":[]},{"n":23,"t":"約瑟的子孫，瑪拿西子孫支派的領袖：以弗的兒子漢尼業。","notes":[]},{"n":24,"t":"以法蓮子孫支派的領袖：拾弗但的兒子基摩利。","notes":[]},{"n":25,"t":"西布倫子孫支派的領袖：帕納的兒子以利撒番。","notes":[]},{"n":26,"t":"以薩迦子孫支派的領袖：阿散的兒子帕鐵。","notes":[]},{"n":27,"t":"亞設子孫支派的領袖：示羅米的兒子亞希忽。","notes":[]},{"n":28,"t":"拿弗他利子孫支派的領袖：亞米忽的兒子比大黑。」","notes":[]},{"n":29,"t":"這些就是耶和華所吩咐，在迦南地為以色列人分產業的人。","notes":[]}]},"35":{"heading":"利未人的城","verses":[{"n":1,"t":"耶和華在約旦河邊，耶利哥對面的摩押平原吩咐摩西說：","notes":[]},{"n":2,"t":"「你吩咐以色列人，要從所得為業的地中把一些城給利未人居住，也要把這些城四圍的郊野給利未人。","notes":[]},{"n":3,"t":"這些城鎮要歸他們居住，郊外可以給他們牧放牛羊、牲畜和所有的動物。","notes":[]},{"n":4,"t":"你們給利未人城的郊外，要從城牆量起，四圍往外量一千肘。","notes":[]},{"n":5,"t":"你們要往東量二千肘，往南量二千肘，往西量二千肘，往北量二千肘為邊界，以城為中心；這城鎮的郊外要歸給他們。」","notes":[]},{"n":6,"t":"「你們給利未人的城鎮中，要設立六座逃城，讓誤殺人的可以逃到那裏。此外還要給他們四十二座城。","notes":[],"heads":["逃城的設立和條例"]},{"n":7,"t":"所以，給利未人的城一共有四十八座，連同城的郊外都給他們。","notes":[]},{"n":8,"t":"從以色列人所得的產業中給利未人的這些城鎮，多的要多給，少的要少給；各支派要按照所承受為業之地的多少把城鎮給利未人。」","notes":[]},{"n":9,"t":"耶和華吩咐摩西說：","notes":[]},{"n":10,"t":"「你要吩咐以色列人，對他們說：你們過了約旦河，進入迦南地，","notes":[]},{"n":11,"t":"要指定幾座城，作為你們的逃城，使誤殺人的可以逃到那裏。","notes":[]},{"n":12,"t":"這些城要作為逃避報仇者的城，使誤殺人的不至於死，等他站在會眾面前受審判。","notes":[]},{"n":13,"t":"「你們指定的城，是要作你們的六座逃城。","notes":[]},{"n":14,"t":"約旦河東指定三座，迦南地也指定三座，作為逃城。","notes":[]},{"n":15,"t":"這六座城要給以色列人和他們中間的外人，以及寄居者，作為逃城，讓誤殺人的可以逃到那裏。","notes":[]},{"n":16,"t":"「倘若人用鐵器打死人，他是故意殺人的；故意殺人的必被處死。","notes":[]},{"n":17,"t":"若用手中可以致命的石頭打死人，他是故意殺人的；故意殺人的必被處死。","notes":[]},{"n":18,"t":"若用手中可以致命的木器打死人，他是故意殺人的；故意殺人的必被處死。","notes":[]},{"n":19,"t":"報血仇者可以親自殺死那故意殺人的；他一找到兇手，就可以殺死他。","notes":[]},{"n":20,"t":"人若因怨恨把人推倒，或埋伏等著丟東西砸人，以至於死，","notes":[]},{"n":21,"t":"或因仇恨用手打死人，打人的必被處死，他是故意殺人的；報血仇者一遇見兇手就可以殺死他。","notes":[]},{"n":22,"t":"「人若不是出於仇恨，把人推倒，或不是埋伏等著丟東西砸人，","notes":[]},{"n":23,"t":"或是在不注意的時候，用可以致命的石頭扔在人身上，以至於死，彼此沒有仇恨，也無意害對方，","notes":[]},{"n":24,"t":"會眾就要照著這些典章，在殺人者和報血仇者中間審判。","notes":[]},{"n":25,"t":"會眾要救這誤殺人的脫離報血仇者的手，送他回到他曾逃入的逃城那裏。他要住在城中，直到受聖膏的大祭司去世。","notes":[]},{"n":26,"t":"但誤殺人的，無論甚麼時候，若離開了他所逃入的逃城邊界，","notes":[]},{"n":27,"t":"報血仇者在逃城邊界外遇見他，把兇手殺了，報血仇者就沒有流人血之罪。","notes":[]},{"n":28,"t":"因為誤殺人的應該住在逃城裏，直到大祭司去世。大祭司去世以後，誤殺人的才可以回到他所得為業之地。","notes":[]},{"n":29,"t":"在你們一切的住處，這些都要作為你們世世代代的律例典章。","notes":[]},{"n":30,"t":"「無論誰殺了人，必須憑幾個證人的口，才可把那故意殺人的處死；只憑一個證人，不足以判人死。","notes":[]},{"n":31,"t":"那犯死罪的殺人犯，你們不可收贖價來代替他的命；他必須被處死。","notes":[]},{"n":32,"t":"那逃到逃城的人，你們不可向他收贖價，使他在大祭司未死以先回本地居住。","notes":[]},{"n":33,"t":"這樣，你們就不會污穢所住之地，因為血能使地污穢；若有血流在地上，除非流那殺人者的血，否則那地就不得潔淨。","notes":[]},{"n":34,"t":"你們不可玷污所住之地，就是我住在當中的地，因為我－耶和華住在以色列人中間。」","notes":[]}]},"36":{"heading":"女繼承人的結婚條例","verses":[{"n":1,"t":"約瑟子孫的宗族，瑪拿西的孫子，瑪吉的兒子基列，他父系宗族的領袖來到摩西和作領袖的以色列眾父系家長面前，說：","notes":[]},{"n":2,"t":"「耶和華曾吩咐我主抽籤分地給以色列人為業，我主也遵照耶和華的吩咐，把我們兄弟西羅非哈的產業給他的女兒。","notes":[]},{"n":3,"t":"她們若嫁給以色列別個支派的人，必拿走我們祖宗所遺留的產業，加在她們丈夫支派的產業上。這樣，我們抽籤所得的產業就要減少了。","notes":[]},{"n":4,"t":"到了以色列人的禧年，她們的產業就必加在她們丈夫支派的產業上。這樣，我們祖宗支派的產業就要減少了。」","notes":[]},{"n":5,"t":"摩西照耶和華的指示吩咐以色列人說：「約瑟子孫支派的人說得有理。","notes":[]},{"n":6,"t":"關於西羅非哈的女兒們，這是耶和華吩咐的話說：『她們可以隨意嫁人，只是必須嫁給同宗，她們父親支派的人。","notes":[]},{"n":7,"t":"這樣，以色列人的產業就不會從這支派轉到另一個支派，因為以色列人要各自守住祖宗支派的產業。","notes":[]},{"n":8,"t":"凡在以色列支派中得了產業的女兒，必須嫁給同宗，她們父親支派的人，好使以色列人各自承受他們祖宗的產業。","notes":[]},{"n":9,"t":"產業不可從一個支派轉到另一個支派，因為以色列支派的人要各自守住自己的產業。』」","notes":[]},{"n":10,"t":"耶和華怎樣吩咐摩西，西羅非哈的女兒就照樣做。","notes":[]},{"n":11,"t":"西羅非哈的女兒瑪拉、得撒、曷拉、密迦、挪阿都嫁給她們叔伯的兒子。","notes":[]},{"n":12,"t":"她們嫁給了約瑟兒子瑪拿西子孫宗族的人；她們的產業保留在同宗，她們父親的支派中。","notes":[]},{"n":13,"t":"這是耶和華在約旦河邊，耶利哥對面的摩押平原，藉著摩西吩咐以色列人的命令和典章。","notes":[]}]}},"DEU":{"1":{"heading":"摩西的回憶","verses":[{"n":1,"t":"以下是摩西在約旦河東的曠野，疏弗對面的亞拉巴，就是在巴蘭、陀弗、拉班、哈洗錄、底撒哈之間，向以色列眾人所說的話。","notes":[]},{"n":2,"t":"從何烈山經過西珥山到加低斯‧巴尼亞要十一天的路程。","notes":[]},{"n":3,"t":"第四十年十一月初一，摩西照耶和華所吩咐他一切有關以色列人的話，都告訴他們。","notes":[]},{"n":4,"t":"那時，他已經擊敗了住希實本的亞摩利王西宏和住亞斯她錄、以得來的巴珊王噩。","notes":[]},{"n":5,"t":"摩西在約旦河東的摩押地講解這律法，說：","notes":[]},{"n":6,"t":"「耶和華－我們的神在何烈山吩咐我們說：你們住在這山上已經夠久了。","notes":[]},{"n":7,"t":"要起行，轉到亞摩利人的山區和附近的地區，就是亞拉巴、山區、謝非拉、尼革夫、沿海一帶，迦南人的地和黎巴嫩，直到大河，就是幼發拉底河。","notes":["「謝非拉」是音譯，意思是「低地」。","「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」；本卷書下同。"]},{"n":8,"t":"看，我將這地擺在你們面前。你們要進去得這地，就是耶和華向你們列祖亞伯拉罕、以撒、雅各起誓要賜給他們和他們後裔為業之地。」","notes":[]},{"n":9,"t":"「那時，我對你們說：『我獨自一人無法承擔你們的事。","notes":[],"heads":["選立審判官"]},{"n":10,"t":"耶和華－你們的神使你們增多。看哪，你們今日好像天上的星那樣多。","notes":[]},{"n":11,"t":"惟願耶和華－你們列祖的神使你們更增加千倍，照他所應許你們的賜福給你們。","notes":[]},{"n":12,"t":"但你們的擔子，你們的重任，以及你們的爭訟，我獨自一人怎能承擔呢？","notes":[]},{"n":13,"t":"你們要按著各支派選出有智慧、明辨是非、為人所知的人來，我就立他們為你們的領袖。』","notes":[]},{"n":14,"t":"你們回答我說：『你說要做的事很好！』","notes":[]},{"n":15,"t":"我就將你們各支派的領袖，就是有智慧、為人所知的人，立他們為領袖，作你們各支派的千夫長、百夫長、五十夫長、十夫長等官長，來管理你們。","notes":[]},{"n":16,"t":"「當時，我吩咐你們的審判官說：『你們聽訟，無論是弟兄之間的訴訟，或與寄居者之間的訴訟，都要秉公判斷。","notes":[]},{"n":17,"t":"審判的時候不可看人的情面；無論大小，你們都要聽訟。不可因人而懼怕，因為審判是神的事。你們當中若有難斷的案件，可以呈到我這裏，讓我來聽訟。』","notes":[]},{"n":18,"t":"那時，我已經把你們所當做的事都吩咐你們了。」","notes":[]},{"n":19,"t":"「我們照著耶和華－我們神所吩咐的，從何烈山起行，經過你們所看見那一切大而可怕的曠野，往亞摩利人的山區去，到了加低斯‧巴尼亞。","notes":[],"heads":["以色列人拒進迦南"]},{"n":20,"t":"我對你們說：『你們已經到了耶和華－我們神所賜給我們的亞摩利人之山區。","notes":[]},{"n":21,"t":"看，耶和華－你的神已將那地擺在你面前，你要照耶和華－你列祖的神所說的，上去得那地為業。不要懼怕，也不要驚惶。』","notes":[]},{"n":22,"t":"你們都來到我這裏，說：『讓我們先派人去，為我們窺探那地，把我們上去該走的路線和該進的城鎮回報我們。』","notes":[]},{"n":23,"t":"這話我看為美，就從你們中間選取十二個人，每支派一人。","notes":[]},{"n":24,"t":"於是他們起身上山區去，到以實各谷，窺探那地。","notes":[]},{"n":25,"t":"他們的手帶著那地的一些果子，下到我們這裏，回報我們說：『耶和華－我們的神所賜給我們的是美地。』","notes":[]},{"n":26,"t":"「你們卻不肯上去，竟違背了耶和華─你們神的指示，","notes":[]},{"n":27,"t":"在帳棚內發怨言說：『耶和華因為恨我們，所以將我們從埃及地領出來，要把我們交在亞摩利人的手中，除滅我們。","notes":[]},{"n":28,"t":"我們上哪裏去呢？我們的弟兄使我們膽戰心驚，說那裏的百姓比我們又大又高 ，那裏的城鎮又大，城牆又堅固，如天一樣高，並且我們在那裏看見亞衲族人。』","notes":["「膽戰心驚」：原文直譯「心消化了」。","「高」：有古卷是「多」。"]},{"n":29,"t":"我就對你們說：『不要驚惶，也不要怕他們。","notes":[]},{"n":30,"t":"在你們前面行的耶和華－你們的神必為你們爭戰，正如他在埃及，在你們眼前為你們所做的一樣；","notes":[]},{"n":31,"t":"並且你們在曠野所行的一切路上，也看見了耶和華─你們的神背著你們，如同人背自己的兒子一樣，直到你們來到這地方。』","notes":[]},{"n":32,"t":"你們在這事上卻不信耶和華─你們的神。","notes":[]},{"n":33,"t":"他一路行在你們前面，為你們尋找安營的地方；他夜間在火中，日間在雲中，指示你們當走的路。」","notes":[]},{"n":34,"t":"「耶和華聽見你們的怨言，就發怒，起誓說：","notes":[],"heads":["以色列人受懲罰"]},{"n":35,"t":"『這邪惡世代的人，一個也不得看見我起誓要賜給你們列祖的美地；","notes":[]},{"n":36,"t":"惟有耶孚尼的兒子迦勒必得看見，並且我要將他所踏過的地賜給他和他的子孫，因為他專心跟從我。』","notes":[]},{"n":37,"t":"耶和華也因你們的緣故向我發怒，說：『你也不得進入那地。","notes":[]},{"n":38,"t":"那侍候你，嫩的兒子約書亞必得進入那地。你要勉勵他，因為他要使以色列承受那地為業。","notes":[]},{"n":39,"t":"你們的孩子，你們說要成為擄物的，就是今日尚不知善惡的兒女，必進入那地。我要將那地賜給他們，他們必得為業。","notes":[]},{"n":40,"t":"至於你們，要轉回，從紅海的路往曠野去。』","notes":["「紅海」是根據七十士譯本，原文是「蘆葦海」；本卷書下同。"]},{"n":41,"t":"「你們回答我說：『我們得罪了耶和華！現在我們願遵照耶和華─我們神一切所吩咐的上去爭戰。』於是你們各人帶著兵器，以為很容易就能上到山區去。","notes":[]},{"n":42,"t":"耶和華對我說：『你對他們說：不要上去，也不要爭戰，因我不在你們中間，恐怕你們在仇敵面前被擊敗。』","notes":[]},{"n":43,"t":"我就告訴了你們，你們卻不聽從，竟違背耶和華的指示，擅自上到山區去。","notes":[]},{"n":44,"t":"住在那山區的亞摩利人像蜂群一樣出來迎擊你們，追趕你們，在西珥擊敗你們，直到何珥瑪。","notes":[]},{"n":45,"t":"你們就回來，在耶和華面前哭泣；耶和華卻不聽你們的聲音，也不向你們側耳。","notes":[]},{"n":46,"t":"你們照著所停留的日子，在加低斯停留了許多日子。」","notes":[]}]},"2":{"heading":"在曠野流浪","verses":[{"n":1,"t":"「我們轉回，從紅海的路往曠野去，正如耶和華所吩咐我的。我們在西珥山繞行了許多日子。","notes":[]},{"n":2,"t":"耶和華對我說：","notes":[]},{"n":3,"t":"『你們繞行這山已經夠久了，要轉向北方。","notes":[]},{"n":4,"t":"你要吩咐百姓說：你們弟兄以掃的子孫住在西珥，你們要經過他們的邊界。他們必懼怕你們，但你們要分外謹慎。","notes":[]},{"n":5,"t":"不可向他們挑戰；他們的地，連腳掌可踏之處，我都不給你們，因我已將西珥山賜給以掃為業。","notes":[]},{"n":6,"t":"你們要用錢向他們買糧吃，也要用錢向他們買水喝。","notes":[]},{"n":7,"t":"因為耶和華─你的神在你手裏所做的一切事上已賜福給你。你走這大曠野，他都知道。這四十年，耶和華─你的神與你同在，因此你一無所缺。』","notes":[]},{"n":8,"t":"「於是，我們經過我們弟兄以掃子孫所住的西珥，從亞拉巴的路，經過以拉他、以旬‧迦別，轉向摩押曠野的路去。","notes":[]},{"n":9,"t":"耶和華對我說：『不可侵犯摩押，也不可向他們挑戰。他們的地，我不賜給你為業，因我已將亞珥賜給羅得的子孫為業。』","notes":[]},{"n":10,"t":"先前，以米人住在那裏，百姓又大又多，像亞衲人一樣高大。","notes":[]},{"n":11,"t":"他們跟亞衲人一樣，也算是利乏音人，但摩押人卻稱他們為以米人。","notes":[]},{"n":12,"t":"從前，何利人也住在西珥，但以掃的子孫把他們除滅，佔領了他們的地，接續他們在那裏居住，如同以色列在耶和華賜給他們為業之地所做的一樣。","notes":[]},{"n":13,"t":"『現在，起來，過撒烈溪！』於是我們過了撒烈溪。","notes":[]},{"n":14,"t":"從離開加低斯‧巴尼亞到渡過撒烈溪，這段時期共三十八年，直到這一代的戰士都從營中滅盡，正如耶和華向他們所起的誓。","notes":[]},{"n":15,"t":"耶和華的手也攻擊他們，將他們從營中除滅，直到滅盡。","notes":[]},{"n":16,"t":"「百姓中所有的戰士滅盡死亡以後，","notes":[]},{"n":17,"t":"耶和華吩咐我說：","notes":[]},{"n":18,"t":"『你今日要經過摩押的邊界亞珥，","notes":[]},{"n":19,"t":"走到亞捫人之地。不可侵犯他們，也不可向他們挑戰。亞捫人的地，我不賜給你們為業，因我已將那地賜給羅得的子孫為業。』","notes":[]},{"n":20,"t":"那地也算是利乏音人之地，因為先前利乏音人住在那裏，亞捫人稱他們為散送冥人。","notes":[]},{"n":21,"t":"那裏的百姓又大又多，像亞衲人一樣高大，但耶和華從亞捫人面前除滅他們，亞捫人就佔領他們的地，接續他們在那裏居住。","notes":[]},{"n":22,"t":"這正如耶和華從前為住在西珥的以掃子孫，將何利人從他們面前除滅，使他們得了何利人的地，接續他們在那裏居住，直到今日一樣。","notes":[]},{"n":23,"t":"亞衛人先前住在鄉村直到迦薩；從迦斐託出來的迦斐託人將亞衛人除滅，接續他們在那裏居住。","notes":[]},{"n":24,"t":"你們起來往前去，過亞嫩谷。看，我已將亞摩利人希實本王西宏和他的地交在你手中，你要開始去得他的地為業，向他挑戰。","notes":[]},{"n":25,"t":"從今日起，我要讓天下萬民驚慌懼怕你，聽見你的名聲，就因你發顫傷慟。」","notes":[]},{"n":26,"t":"「我從基底莫的曠野派遣使者到希實本王西宏那裏，用和平的話說：","notes":[],"heads":["打敗希實本王西宏"]},{"n":27,"t":"『求你讓我穿越你的地，我走路的時候，只走大路，不偏左右。","notes":[]},{"n":28,"t":"你可以賣糧給我吃，賣水給我喝；只要讓我步行過去，","notes":[]},{"n":29,"t":"就如住在西珥的以掃子孫和住在亞珥的摩押人待我一樣，等我過了約旦河，進入耶和華－我們神所賜給我們的地。』","notes":[]},{"n":30,"t":"但希實本王西宏不肯讓我們從他那裏經過，因為耶和華－你的神使他性情頑梗，內心剛硬，為要把他交在你手中，像今日一樣。","notes":[]},{"n":31,"t":"耶和華對我說：『看，我已開始把西宏和他的地交給你了，你要開始得他的地為業。』","notes":[]},{"n":32,"t":"「西宏和他的眾百姓出來迎擊我們，在雅雜與我們交戰。","notes":[]},{"n":33,"t":"耶和華－我們的神把他交給我們，我們就殺了他和他的眾兒子，以及他所有的百姓。","notes":[]},{"n":34,"t":"那時，我們奪了他一切的城鎮，毀滅各城的男人、女人、孩子，沒有留下一個倖存者。","notes":[]},{"n":35,"t":"只有牲畜和所奪各城的財物，我們都取為自己的掠物。","notes":[]},{"n":36,"t":"從亞嫩谷旁的亞羅珥和谷中的城，直到基列，沒有一座城是高得我們不能攻取的；耶和華－我們的神把它們全都交給我們了。","notes":[]},{"n":37,"t":"只有亞捫人之地，雅博河沿岸，以及山區的城鎮，你沒有挨近，這全是耶和華－我們神所吩咐的。」","notes":[]}]},"3":{"heading":"打敗巴珊王噩","verses":[{"n":1,"t":"「我們又轉回，朝巴珊的路上去。巴珊王噩和他的眾百姓出來迎擊我們，在以得來與我們交戰。","notes":[]},{"n":2,"t":"耶和華對我說：『不要怕他！因我已把他和他的眾百姓，以及他的地，都交在你手中；你要待他像從前待住在希實本的亞摩利王西宏一樣。』","notes":[]},{"n":3,"t":"於是耶和華－我們的神也把巴珊王噩和他的眾百姓都交在我們手中；我們殺了他，沒有給他留下一個倖存者。","notes":[]},{"n":4,"t":"那時，我們奪了他一切的城鎮，共六十座，沒有一座城不被我們所奪，這是亞珥歌伯的全境，巴珊王噩的國度。","notes":[]},{"n":5,"t":"這些堅固的城都有高的城牆，有門有閂，此外，還有許多無城牆的鄉村。","notes":[]},{"n":6,"t":"我們把這些都毀滅了，像從前待希實本王西宏一樣，毀滅各城的男人、女人、孩子；","notes":[]},{"n":7,"t":"只有一切牲畜和城中的財物，我們取為自己的掠物。","notes":[]},{"n":8,"t":"那時，我們從兩個亞摩利王的手裏把約旦河東邊的地奪過來，從亞嫩谷直到黑門山，","notes":[]},{"n":9,"t":"這黑門山，西頓人稱為西連，亞摩利人稱為示尼珥。","notes":[]},{"n":10,"t":"我們奪了平原的各城、基列全地、巴珊全地，直到撒迦和以得來，都是巴珊王噩國內的城鎮。","notes":[]},{"n":11,"t":"利乏音人所剩下的只有巴珊王噩。看哪，他的床是鐵床，按照人肘的度量，長九肘，寬四肘，現今不是在亞捫人的拉巴嗎？」","notes":[]},{"n":12,"t":"「那時，我們得了這地。從亞嫩谷旁的亞羅珥起，連同基列山區的一半和境內的城鎮，我都給了呂便人和迦得人。","notes":[],"heads":["約旦河東土地的分配"]},{"n":13,"t":"基列其餘的地和巴珊全地，就是噩的國度，我給了瑪拿西半支派。亞珥歌伯全境就是巴珊全地，也稱為利乏音人之地。","notes":[]},{"n":14,"t":"瑪拿西的子孫睚珥佔領了亞珥歌伯全境，直到基述人和瑪迦人的邊界，就按自己的名字稱這些地，就是巴珊，為哈倭特‧睚珥，直到今日。","notes":[]},{"n":15,"t":"我又將基列給了瑪吉。","notes":[]},{"n":16,"t":"我給了呂便人和迦得人從基列到亞嫩谷，以谷的中央為界，直到亞捫人邊界的雅博河；","notes":[]},{"n":17,"t":"還有亞拉巴和靠近約旦河之地，從基尼烈直到亞拉巴海，就是鹽海，以及毗斯迦山斜坡的山腳東邊之地。","notes":[]},{"n":18,"t":"「那時，我吩咐你們說：『耶和華－你們的神已將這地賜給你們為業；你們所有的勇士都要帶著兵器，在你們的弟兄以色列人前面過去。","notes":[]},{"n":19,"t":"但你們的妻子、孩子、牲畜，可以住在我所賜給你們的各城裏，我知道你們有許多牲畜。","notes":[]},{"n":20,"t":"等到耶和華讓你們的弟兄像你們一樣，得享太平，他們在約旦河另一邊，也得了耶和華－你們的神所賜給他們的地，你們各人才可以回到我所賜給你們為業之地。』","notes":[]},{"n":21,"t":"那時，我吩咐約書亞說：『你親眼看見了耶和華－你們的神向這兩個王一切所做的事，耶和華也必向你所要去的各國照樣做。","notes":[]},{"n":22,"t":"不要怕他們，因為那為你們爭戰的是耶和華－你們的神。』」","notes":[]},{"n":23,"t":"「那時，我懇求耶和華說：","notes":[],"heads":["摩西不得進入迦南"]},{"n":24,"t":"『主耶和華啊，你已開始將你的偉大和你大能的手顯給你僕人看。在天上，在地下，有甚麼神明能像你行事，像你有大能的作為呢？","notes":[]},{"n":25,"t":"求你讓我過去，看約旦河另一邊的美地，就是那佳美的山區和黎巴嫩。』","notes":[]},{"n":26,"t":"但耶和華因你們的緣故向我發怒，不應允我。耶和華對我說：『你夠了吧！不要再向我提這事。","notes":[]},{"n":27,"t":"你上毗斯迦山頂去，向東、西、南、北舉目，用你的眼睛觀看，因為你必不能過這約旦河。","notes":[]},{"n":28,"t":"你卻要吩咐約書亞，勉勵他，使他壯膽，因為他必在這百姓前面過去，使他們承受你所要觀看之地。』","notes":[]},{"n":29,"t":"於是我們停留在伯‧毗珥對面的谷中。」","notes":[]}]},"4":{"heading":"摩西勸以色列人遵守律法","verses":[{"n":1,"t":"「現在，以色列啊，聽我所教導你們的律例典章，要遵行，好使你們存活，得以進入耶和華－你們列祖之神所賜給你們的地，承受為業。","notes":[]},{"n":2,"t":"我吩咐你們的話，你們不可加添，也不可刪減，好叫你們遵守耶和華－你們神的命令，就是我所吩咐你們的。","notes":[]},{"n":3,"t":"你們已親眼看見耶和華因巴力‧毗珥所做的。凡隨從巴力‧毗珥的人，耶和華－你的神都從你中間除滅了。","notes":[]},{"n":4,"t":"只有你們這緊緊跟隨耶和華－你們神的人，今日全都存活。","notes":[]},{"n":5,"t":"看，我照著耶和華－我的神所吩咐我的，將律例和典章教導你們，使你們在所要進去得為業的地上遵行。","notes":[]},{"n":6,"t":"你們要謹守遵行；這就是你們在萬民眼前的智慧和聰明。他們聽見這一切律例，必說：『這大國的人真是有智慧，有聰明！』","notes":[]},{"n":7,"t":"哪一大國有神明與他們相近，像耶和華－我們的神在我們求告他的時候與我們相近呢？","notes":[]},{"n":8,"t":"哪一大國有這樣公義的律例典章，像我今日在你們面前所頒佈的這一切律法呢？","notes":[]},{"n":9,"t":"「但你要謹慎，殷勤保守你的心靈，免得忘記你親眼所看見的事，又免得在你一生的年日這些事離開你的心，總要把它們傳給你的子子孫孫。","notes":[]},{"n":10,"t":"你在何烈山站在耶和華－你神面前的那日，耶和華對我說：『你為我召集百姓，我要叫他們聽見我的話，使他們活在世上的日子，可以學習敬畏我，又可以教導他們的兒女。』","notes":[]},{"n":11,"t":"那時，你們近前來，站在山下；山上有火燃燒，直沖天頂，並有黑暗、密雲、幽暗。","notes":[]},{"n":12,"t":"耶和華從火焰中對你們說話，你們聽見說話的聲音，只有聲音，卻沒有看見形像。","notes":[]},{"n":13,"t":"他將所吩咐你們當守的約指示你們，就是十條誡命，並將誡命寫在兩塊石版上。","notes":["「十條誡命」：原文是「十句話」；10．4同。"]},{"n":14,"t":"那時，耶和華吩咐我將律例典章教導你們，使你們在所要過去得為業的地上遵行。」","notes":[]},{"n":15,"t":"「所以，你們為自己的緣故要分外謹慎；因為耶和華在何烈山，從火中對你們說話的那日，你們沒有看見任何形像。","notes":[],"heads":["禁拜偶像"]},{"n":16,"t":"惟恐你們的行為敗壞，為自己雕刻任何形狀的偶像，無論是男像或女像，","notes":[]},{"n":17,"t":"或地上任何走獸的像，或任何飛在空中有翅膀的鳥的像，","notes":[]},{"n":18,"t":"或地上任何爬行動物的像，或地底下任何水中魚的像。","notes":[]},{"n":19,"t":"又恐怕你向天舉目，看見耶和華－你的神為天下萬民所擺列的日月星辰，就是天上的萬象，就被誘惑去敬拜它們，事奉它們。","notes":[]},{"n":20,"t":"耶和華將你們從埃及帶領出來，脫離鐵爐，是要你們成為他產業的子民，像今日一樣。","notes":[]},{"n":21,"t":"「耶和華又因你們的緣故向我發怒，起誓不容我過約旦河，不讓我進入耶和華－你神所賜你為業的那美地。","notes":[]},{"n":22,"t":"我只好死在這地，不能過約旦河；但你們必過去得那美地。","notes":[]},{"n":23,"t":"你們要謹慎，免得忘記耶和華－你們的神與你們所立的約，為自己雕刻任何形狀的偶像，就是耶和華－你神所禁止的，","notes":[]},{"n":24,"t":"因為耶和華－你的神是吞滅的火，是忌邪的神。","notes":["「忌邪」：原文是「妒忌」，意思是「不容許有對立的神明」。"]},{"n":25,"t":"「你們在那地住久了，生子生孫，若行為敗壞，為自己雕刻任何形狀的偶像，行耶和華－你神眼中看為惡的事，惹他發怒，","notes":[]},{"n":26,"t":"我今日呼天喚地向你們作見證，你們在過約旦河得為業的地上必迅速滅亡！你們在那地的日子必不長久，必全然滅絕。","notes":[]},{"n":27,"t":"耶和華必將你們分散在萬民中；在耶和華領你們到的列國中，你們剩下的人丁稀少。","notes":[]},{"n":28,"t":"在那裏，你們必事奉人手所造的神明，它們是木頭，是石頭，不能看，不能聽，不能吃，不能聞。","notes":[]},{"n":29,"t":"你們在那裏必尋求耶和華－你的神。你若盡心盡性尋求他，就必尋見。","notes":[]},{"n":30,"t":"日後你在患難中，當這一切的事臨到你，你必歸回耶和華－你的神，聽從他的話。","notes":[]},{"n":31,"t":"耶和華－你的神是有憐憫的神，他不撇下你，不滅絕你，也不忘記他起誓與你列祖所立的約。","notes":[]},{"n":32,"t":"「你去問，在你先前的時代，自從神造人在地上以來，從天這邊到天那邊，曾有過或聽過這樣的大事嗎？","notes":[]},{"n":33,"t":"有哪些百姓聽見神在火中說話的聲音，像你聽見了還能存活呢？","notes":[]},{"n":34,"t":"神何曾為自己嘗試從別的國中領出一國的子民來，用考驗、神蹟、奇事、戰爭、大能的手、伸出來的膀臂和大可畏的事，像耶和華－你們的神在埃及，在你們眼前為你們所做的一切事呢？","notes":[]},{"n":35,"t":"這是要顯給你看，使你知道，惟有耶和華他是神，除他以外，再沒有別的了。","notes":[]},{"n":36,"t":"他從天上使你聽見他的聲音，為要教導你，又在地上使你看見他的烈火，並且聽見他從火中所說的話。","notes":[]},{"n":37,"t":"因為他愛你的列祖，揀選他們的後裔，親自用大能領你出了埃及，","notes":["「他們的後裔」是根據撒瑪利亞五經、七十士譯本和其他古譯本；原文是「他」，「他」指雅各。"]},{"n":38,"t":"要將比你強大的列國從你面前趕出，領你進去，把他們的地賜你為業，像今日一樣。","notes":[]},{"n":39,"t":"所以，今日你要知道，也要記在心裏，天上地下惟有耶和華他是神，再沒有別的了。","notes":[]},{"n":40,"t":"我今日吩咐你的律例誡命，你要遵守，使你和你的後裔可以得福，並使你的日子一直在耶和華－你神賜你的地上得以長久。」","notes":[]},{"n":41,"t":"「那時，摩西在約旦河東邊，向日出的方向，指定三座城，","notes":[],"heads":["約旦河東的三座逃城"]},{"n":42,"t":"使那素無仇恨、無意中殺了鄰舍的兇手，可以逃到這三座城中的一座，就得存活：","notes":[]},{"n":43,"t":"屬呂便人的是曠野平坦之地的比悉，屬迦得人的是基列的拉末，屬瑪拿西人的是巴珊的哥蘭。」","notes":[]},{"n":44,"t":"這是摩西在以色列人面前頒佈的律法。","notes":[],"heads":["摩西頒佈神的律法"]},{"n":45,"t":"這些法度、律例、典章是摩西在以色列人出埃及後對他們說的，","notes":[]},{"n":46,"t":"在約旦河東伯‧毗珥對面的谷中，在住希實本的亞摩利王西宏之地；這西宏是摩西和以色列人出埃及後所擊殺的。","notes":[]},{"n":47,"t":"他們得了他的地，又得了巴珊王噩的地，就是兩個亞摩利王，在約旦河東，向日出方向的地：","notes":[]},{"n":48,"t":"從亞嫩谷旁的亞羅珥，直到西雲山，就是黑門山，","notes":[]},{"n":49,"t":"還有約旦河東的整個亞拉巴，向日出方向，直到亞拉巴海，靠近毗斯迦山斜坡的山腳。","notes":[]}]},"5":{"heading":"十誡","verses":[{"n":1,"t":"摩西召集以色列眾人，對他們說：「以色列啊，要聽我今日在你們耳中所吩咐的律例典章，要學習，謹守遵行。","notes":[]},{"n":2,"t":"耶和華－我們的神在何烈山與我們立約。","notes":[]},{"n":3,"t":"這約耶和華不是與我們列祖立的，而是與我們，就是今日在這裏還活著的人立的。","notes":[]},{"n":4,"t":"耶和華在山上，從火中，面對面與你們說話。","notes":[]},{"n":5,"t":"那時我站在耶和華和你們之間，要將耶和華的話傳給你們，因為你們懼怕那火，沒有上山。他說：","notes":[]},{"n":6,"t":"「『我是耶和華－你的神，曾將你從埃及地為奴之家領出來。","notes":[]},{"n":7,"t":"「『除了我以外，你不可有別的神。","notes":[]},{"n":8,"t":"「『不可為自己雕刻偶像，也不可做甚麼形像，彷彿上天、下地和地底下水中的百物。","notes":[]},{"n":9,"t":"不可跪拜那些像，也不可事奉它們，因為我耶和華－你的神是忌邪的神。恨我的，我必懲罰他們的罪，自父及子，直到三、四代；","notes":["「忌邪」：原文是「妒忌」，意思是「不容許有對立的神明」。"]},{"n":10,"t":"愛我、守我誡命的，我必向他們施慈愛，直到千代。","notes":[]},{"n":11,"t":"「『不可妄稱耶和華－你神的名，因為妄稱耶和華名的，耶和華必不以他為無罪。","notes":[]},{"n":12,"t":"「『當守安息日為聖日，正如耶和華－你神所吩咐的。","notes":[]},{"n":13,"t":"六日要勞碌做你一切的工，","notes":[]},{"n":14,"t":"但第七日是向耶和華－你的神當守的安息日。這一日，你和你的兒女、僕婢、牛、驢、牲畜，以及你城裏寄居的客旅，都不可做任何的工，使你的僕婢可以和你一樣休息。","notes":[]},{"n":15,"t":"你要記念你在埃及地作過奴僕，耶和華－你的神用大能的手和伸出來的膀臂領你從那裏出來。因此，耶和華－你的神吩咐你守安息日。","notes":[]},{"n":16,"t":"「『當孝敬父母，正如耶和華－你神所吩咐的，使你得福，並使你的日子在耶和華－你神所賜給你的地上得以長久。","notes":[]},{"n":17,"t":"「『不可殺人。","notes":[]},{"n":18,"t":"「『不可姦淫。","notes":[]},{"n":19,"t":"「『不可偷盜。","notes":[]},{"n":20,"t":"「『不可做假見證陷害你的鄰舍。","notes":[]},{"n":21,"t":"「『不可貪戀你鄰舍的妻子；也不可貪圖你鄰舍的房屋、田地、僕婢、牛驢，以及他一切所有的。』","notes":[]},{"n":22,"t":"「這些話是耶和華在山上，從火焰、密雲、幽暗中，大聲吩咐你們全會眾的，再沒有加添別的話了。他把這些話寫在兩塊石版上，交給我。","notes":[],"heads":["摩西傳達律法"]},{"n":23,"t":"山被火焰燒著，你們聽見從黑暗中發出的聲音，那時，你們各支派的領袖和長老都挨近我。","notes":[]},{"n":24,"t":"你們說：『看哪，耶和華－我們的神將他的榮耀和他的偉大顯給我們看，我們也聽見他從火中發出的聲音。今日我們看到神與人說話，人還活著。","notes":[]},{"n":25,"t":"現在這大火將要吞滅我們，我們何必死呢？若再聽見耶和華我們神的聲音，我們就必死。","notes":[]},{"n":26,"t":"凡血肉之軀，有誰像我們一樣，聽見了永生神從火中講話的聲音還能活著呢？","notes":[]},{"n":27,"t":"求你近前去，聽耶和華－我們神所要說的一切話，將耶和華－我們神對你說的話都傳給我們，我們就聽從遵行。』","notes":[]},{"n":28,"t":"「你們對我說的話，耶和華都聽見了。耶和華對我說：『這百姓對你說的話，我聽見了；他們所說的都對。","notes":[]},{"n":29,"t":"惟願他們存這樣的心敬畏我，常遵守我一切的誡命，使他們和他們的子孫永遠得福。","notes":[]},{"n":30,"t":"你去對他們說：你們回帳棚去吧！","notes":[]},{"n":31,"t":"至於你，可以站在我這裏，我要將一切誡命、律例、典章傳給你。你要教導他們，使他們在我賜他們為業的地上遵行。』","notes":[]},{"n":32,"t":"所以，你們要照耶和華－你們神所吩咐的謹守遵行，不可偏離左右。","notes":[]},{"n":33,"t":"你們要走耶和華－你們的神所吩咐的一切道路，使你們可以存活得福，並使你們的日子在所要承受的地上得以長久。」","notes":[]}]},"6":{"heading":"","verses":[{"n":1,"t":"「這是耶和華－你們的神所吩咐要教導你們的誡命、律例、典章，叫你們在所要過去得為業的地上遵行，","notes":[]},{"n":2,"t":"好叫你和你的子孫在一生的日子都敬畏耶和華－你的神，謹守他的一切律例、誡命，就是我所吩咐你的，使你的日子得以長久。","notes":[]},{"n":3,"t":"以色列啊，你要聽，要謹守遵行，使你可以在那流奶與蜜之地得福，人數極其增多，正如耶和華－你列祖的神所應許你的。","notes":[]},{"n":4,"t":"「以色列啊，你要聽！耶和華－我們的神是獨一的主。","notes":["「主」：原文是「耶和華」。"]},{"n":5,"t":"你要盡心、盡性、盡力愛耶和華－你的神。","notes":[]},{"n":6,"t":"我今日吩咐你的這些話都要記在心上，","notes":[]},{"n":7,"t":"也要殷勤教導你的兒女。無論你坐在家裏，走在路上，躺下，起來，都要吟誦。","notes":[]},{"n":8,"t":"要繫在手上作記號，戴在額上作經匣；","notes":["「額上」：原文是「兩眼之間」。","「經匣」指「把經文放在皮製的匣中作額飾」；11．18同。"]},{"n":9,"t":"又要寫在你房屋的門框上和你的城門上。","notes":[]},{"n":10,"t":"「耶和華－你的神必領你進他向你列祖亞伯拉罕、以撒、雅各起誓要給你的地。那裏有又大又美的城鎮，不是你建造的；","notes":[]},{"n":11,"t":"有裝滿各樣美物的房屋，不是你裝滿的；有挖成的水井，不是你挖的；有葡萄園、橄欖園，不是你栽植的；你吃了而且飽足。","notes":[]},{"n":12,"t":"你要謹慎，免得你忘記領你從埃及地為奴之家出來的耶和華。","notes":[]},{"n":13,"t":"你要敬畏耶和華－你的神，事奉他，奉他的名起誓。","notes":[]},{"n":14,"t":"不可隨從別神，就是你們四圍民族的眾神明，","notes":[]},{"n":15,"t":"因為在你中間的耶和華－你的神是忌邪的神，恐怕耶和華－你神的怒氣向你發作，把你從地上除滅。","notes":["「忌邪」：原文是「妒忌」，意思是「不容許有對立的神明」。"]},{"n":16,"t":"「你們不可試探耶和華－你們的神，像你們在瑪撒那樣試探他。","notes":[]},{"n":17,"t":"要謹慎遵守耶和華－你們神的誡命，和他所吩咐的法度、律例。","notes":[]},{"n":18,"t":"耶和華眼中看為正直和美善的事，你都要遵行，使你得福，可以進去得耶和華向你列祖起誓應許的美地，","notes":[]},{"n":19,"t":"可以從你面前趕出你所有的仇敵，正如耶和華所說的。","notes":[]},{"n":20,"t":"「日後，你的兒子問你說：『耶和華－我們神吩咐你們的法度、律例、典章是甚麼意思呢？』","notes":[]},{"n":21,"t":"你要告訴你的兒子說：『我們在埃及作過法老的奴僕，耶和華用大能的手將我們從埃及領出來。","notes":[]},{"n":22,"t":"在我們眼前，他施行重大可怕的神蹟奇事對付埃及、法老和他的全家。","notes":[]},{"n":23,"t":"他將我們從那裏領出來，為要領我們進入他向我們列祖起誓應許之地，把這地賜給我們。","notes":[]},{"n":24,"t":"耶和華又吩咐我們遵行這一切的律例，敬畏耶和華－我們的神，使我們一生得福，得以存活，像今日一樣。","notes":[]},{"n":25,"t":"我們若照耶和華－我們神所吩咐的，在他面前謹守遵行這一切誡命，這就是我們的義了。』」","notes":[]}]},"7":{"heading":"選民","verses":[{"n":1,"t":"「耶和華－你的神領你進入你要得為業之地，從你面前趕出許多國家，就是比你更強大的七個國家：赫人、革迦撒人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人。","notes":[]},{"n":2,"t":"當耶和華－你的神把他們交給你，你擊殺他們的時候，你要完全消滅他們，不可與他們立約，也不可憐惜他們。","notes":[]},{"n":3,"t":"不可與他們結親；不可將你的女兒嫁給他的兒子，也不可叫你的兒子娶他的女兒。","notes":[]},{"n":4,"t":"因為他必使你的兒女離棄我，去事奉別神，以致耶和華的怒氣向你們發作，迅速將你除滅。","notes":[]},{"n":5,"t":"你們卻要這樣處置他們：拆毀他們的祭壇，打碎他們的柱像，砍斷他們的亞舍拉，用火焚燒他們雕刻的偶像。","notes":[]},{"n":6,"t":"「因為你是屬於耶和華－你神神聖的子民；耶和華－你的神從地面上的萬民中揀選你，作自己寶貴的子民。","notes":[]},{"n":7,"t":"耶和華專愛你們，揀選你們，並非因你們人數比任何民族多，其實你們的人數在各民族中是最少的。","notes":[]},{"n":8,"t":"因為耶和華愛你們，又因要遵守他向你們列祖所起的誓，耶和華就用大能的手領你們出來，救贖你脫離為奴之家，脫離埃及王法老的手。","notes":[]},{"n":9,"t":"所以，你知道耶和華－你的神，他是神，是信實的神。他向愛他、守他誡命的人守約施慈愛，直到千代；","notes":[]},{"n":10,"t":"向恨他的人，他必當面報應，消滅他們。凡恨他的，他必當面報應，絕不遲延。","notes":[]},{"n":11,"t":"所以，你要謹守我今日所吩咐你的誡命、律例、典章，遵行它們。」","notes":[]},{"n":12,"t":"「你們若聽從這些典章，謹守遵行，耶和華－你的神必照他向你列祖所起的誓，對你守約，施慈愛。","notes":[],"heads":["遵行誡命必蒙福"]},{"n":13,"t":"他必愛你，賜福給你，使你人數增多，也必在他向你列祖起誓要給你的地上賜福給你身所生的，你地所產的，你的五穀、新酒和新的油，以及你的牛犢、羔羊。","notes":[]},{"n":14,"t":"你必蒙福勝過萬民；你沒有不育的男人和不孕的女人，牲畜也沒有不生育的。","notes":[]},{"n":15,"t":"耶和華必使一切的疾病遠離你；你所知道埃及各樣的惡疾，他不加在你身上，反要加在所有恨你的人身上。","notes":[]},{"n":16,"t":"你要吞滅耶和華－你的神交給你的各民族，你的眼目不可顧惜他們。你也不可事奉他們的神明，因為這必成為你的圈套。","notes":[]},{"n":17,"t":"「你若心裏說，這些國的人數比我多，我怎能趕出他們呢？","notes":[]},{"n":18,"t":"你不必怕他們，要牢牢記住耶和華－你神向法老和埃及全地所行的事，","notes":[]},{"n":19,"t":"你親眼見過的大考驗、神蹟、奇事、大能的手和伸出來的膀臂，都是耶和華－你神領你出來所施行的。耶和華－你的神也必照樣處置你所懼怕的各民族，","notes":[]},{"n":20,"t":"並且耶和華－你的神必派瘟疫 攻擊他們，直到那剩下而躲起來的人都從你面前滅亡。","notes":["「瘟疫」或譯「黃蜂」。"]},{"n":21,"t":"不要因他們驚恐，因為耶和華－你的神在你中間是大而可畏的神。","notes":[]},{"n":22,"t":"耶和華－你的神必將這些國從你面前漸漸趕出；你不可迅速把他們消滅，免得野地的走獸多起來危害你。","notes":[]},{"n":23,"t":"耶和華－你的神必將他們交給你，大大擾亂他們，直到他們被除滅。","notes":[]},{"n":24,"t":"他又要將他們的君王交在你手中，你必從天下除去他們的名；必無一人能在你面前站立得住，直到你把他們除滅了。","notes":[]},{"n":25,"t":"你們要用火焚燒他們神明的雕刻偶像；不可貪愛偶像上的金銀，也不可私自收起來，免得你因此陷入圈套，因為這是耶和華－你神所憎惡的。","notes":[]},{"n":26,"t":"你不可把可憎之物帶進你的家，否則，你就像它一樣成為當毀滅的。你要徹底憎恨它，極其厭惡它，因為這是當毀滅的。」","notes":[]}]},"8":{"heading":"將得美地","verses":[{"n":1,"t":"「我今日所吩咐你的一切誡命，你們要謹守遵行，好使你們存活，人數增多，可以進去得耶和華向你們列祖起誓應許的那地。","notes":[]},{"n":2,"t":"你要記得，這四十年耶和華─你的神在曠野一路引導你，是要磨煉你，考驗你，為要知道你的心如何，是否願意遵守他的誡命。","notes":[]},{"n":3,"t":"他磨煉你，任你飢餓，將你和你列祖所不認識的嗎哪賜給你吃，使你知道，人活著，不是單靠食物，乃是靠耶和華口裏所出的一切話。","notes":[]},{"n":4,"t":"這四十年，你身上的衣服沒有穿破，你的腳也沒有腫。","notes":[]},{"n":5,"t":"你心裏要知道，耶和華─你的神管教你，像人管教兒女一樣。","notes":[]},{"n":6,"t":"你要謹守耶和華─你神的誡命，遵行他的道，敬畏他。","notes":[]},{"n":7,"t":"「耶和華─你的神必領你進入美地，那地有河流，有泉源和深淵的水從谷中和山上流出。","notes":[]},{"n":8,"t":"那地有小麥、大麥、葡萄樹、無花果樹、石榴樹，那地也有橄欖油和蜂蜜。","notes":[]},{"n":9,"t":"那地沒有缺乏，你在那裏有食物吃，一無所缺；那地的石頭是鐵，山中可以挖銅。","notes":[]},{"n":10,"t":"你吃得飽足，要稱頌耶和華─你的神，因為他將那美地賜給你。」","notes":[]},{"n":11,"t":"「你要謹慎，免得忘記耶和華─你的神，不守他的誡命、典章、律例，就是我今日吩咐你的。","notes":[],"heads":["不可忘記耶和華"]},{"n":12,"t":"免得你吃得飽足，建造上好的房屋，住在其中，","notes":[]},{"n":13,"t":"你的牛羊增多，你的金銀增多，你擁有的一切全都增多，","notes":[]},{"n":14,"t":"於是你的心高傲，忘記耶和華─你的神。他曾將你從埃及地為奴之家領出來，","notes":[]},{"n":15,"t":"曾引領你經過那大而可怕的曠野，有火蛇、蠍子、乾旱無水之地。他也曾為你使水從堅硬的磐石中流出來，","notes":[]},{"n":16,"t":"又在曠野將你列祖所不認識的嗎哪賜給你吃，為要磨煉你，考驗你，終久使你享福。","notes":[]},{"n":17,"t":"你心裏說：『這財富是我的力量、我手的能力得來的。』","notes":[]},{"n":18,"t":"你要記得耶和華─你的神，因為得財富的能力是他給你的，為要堅守他向你列祖起誓所立的約，像今日一樣。","notes":[]},{"n":19,"t":"你若忘記耶和華─你的神，隨從別神，事奉它們，敬拜它們，我今日警告你們，你們必定滅亡。","notes":[]},{"n":20,"t":"耶和華在你們面前怎樣使列國滅亡，你們也必照樣滅亡，因為你們不聽從耶和華─你們神的話。」","notes":[]}]},"9":{"heading":"百姓悖逆","verses":[{"n":1,"t":"「以色列啊，你要聽！你今日要過約旦河，進去佔領比你更強大的列國，那裏的城鎮又大，城牆又堅固，如天一樣高。","notes":[]},{"n":2,"t":"那裏的百姓是亞衲族人，又高又壯，是你所知道的；你也聽說過：『誰能在亞衲族人面前站立得住呢？』","notes":[]},{"n":3,"t":"你今日應當知道，耶和華─你的神在你前面渡過去，如同吞噬的火，要除滅他們，並要在你面前將他們制伏，使你可以趕出他們，速速消滅他們，正如耶和華向你所說的。","notes":[]},{"n":4,"t":"「耶和華─你的神將他們從你面前趕出以後，你心裏不可說：『耶和華領我得這地是因我的義。』其實，耶和華將這些國家從你面前趕出去是因他們的惡。","notes":[]},{"n":5,"t":"你能進去得他們的地，並不是因你的義，也不是因你心裏正直，而是因這些國家的惡，耶和華─你的神才把他們從你面前趕出去，為了應驗耶和華向你列祖亞伯拉罕、以撒、雅各起誓應許的話。」","notes":[]},{"n":6,"t":"「你當知道，耶和華─你的神將這美地賜你為業，並不是因你的義；你本是硬著頸項的百姓。","notes":[],"heads":["金牛犢"]},{"n":7,"t":"你要記得，不要忘記，你在曠野怎樣惹耶和華－你的神發怒。自從你出了埃及地的那日，直到你們來到這地方，你們常常悖逆耶和華。","notes":[]},{"n":8,"t":"你們在何烈山惹耶和華發怒，耶和華對你們動怒，甚至要除滅你們。","notes":[]},{"n":9,"t":"我上了山，要領受兩塊石版，就是耶和華與你們立約的版。那時我在山上住了四十晝夜，沒有吃飯，也沒有喝水。","notes":[]},{"n":10,"t":"耶和華把那兩塊石版交給我，是神用指頭寫成的；版上是耶和華在大會的那一天，在山上從火中對你們所說的一切話。","notes":[]},{"n":11,"t":"過了四十晝夜，耶和華把那兩塊石版，就是約版，交給我。","notes":[]},{"n":12,"t":"耶和華對我說：『起來，趕快從這裏下去！因為你從埃及領出來的百姓已經敗壞了；他們這麼快偏離了我所吩咐的道，為自己鑄造偶像。』","notes":[]},{"n":13,"t":"「耶和華對我說：『我看這百姓，看哪，他們是硬著頸項的百姓。","notes":[]},{"n":14,"t":"你且由著我，我要除滅他們，從天下塗去他們的名，我要使你成為比他們更大更強的國。』","notes":[]},{"n":15,"t":"於是我轉身下山，山上有火燃燒，兩塊約版在我雙手中。","notes":[]},{"n":16,"t":"我觀看，看哪，你們得罪了耶和華－你們的神，為自己鑄成了一頭牛犢，迅速偏離了耶和華所吩咐你們的道，","notes":[]},{"n":17,"t":"我拿著那兩塊石版，從我雙手中扔出去，在你們眼前把它們摔碎了。","notes":[]},{"n":18,"t":"因為你們所犯的一切罪，做了耶和華眼中看為惡的事，惹他發怒，我就像從前一樣俯伏在耶和華面前四十晝夜，沒有吃飯，沒有喝水。","notes":[]},{"n":19,"t":"我很害怕，因為耶和華向你們大發烈怒，要除滅你們。但那一次耶和華又應允了我。","notes":[]},{"n":20,"t":"耶和華也向亞倫非常生氣，甚至要除滅他；那時我也為亞倫祈禱。","notes":[]},{"n":21,"t":"我把那使你們犯罪所鑄的牛犢拿來，用火焚燒，搗碎後再磨成粉末，好像灰塵。我把這灰塵撒在從山上流下來的溪水中。","notes":[]},{"n":22,"t":"「你們在他備拉、瑪撒、基博羅‧哈他瓦又惹耶和華發怒。","notes":[]},{"n":23,"t":"耶和華叫你們離開加低斯‧巴尼亞，說：『你們上去得我所賜給你們的地。』那時，你們違背了耶和華－你們神的指示，不信服他，不聽從他的話。","notes":[]},{"n":24,"t":"自從我認識你們的日子以來，你們常常悖逆耶和華。","notes":["本節撒瑪利亞五經和七十士譯本是「自從主認識你們的日子以來，你們常常悖逆他。」"]},{"n":25,"t":"「我因耶和華說要除滅你們，就在耶和華面前俯伏四十晝夜，像我以前俯伏一樣。","notes":[]},{"n":26,"t":"我向耶和華祈禱，說：『主耶和華啊，求你不要滅絕你的百姓，你的產業。他們是你用大能救贖，用你強有力的手從埃及領出來的。","notes":[]},{"n":27,"t":"求你記念你的僕人亞伯拉罕、以撒、雅各，不看這百姓的頑梗、邪惡、罪愆，","notes":[]},{"n":28,"t":"免得你領我們出來的那地之人說：耶和華因為不能將這百姓領進他所應許之地，又因恨他們，所以領他們出去，要在曠野殺他們。","notes":[]},{"n":29,"t":"其實他們是你的百姓，你的產業，是你用大能和伸出的膀臂領出來的。』」","notes":[]}]},"10":{"heading":"摩西重新接受誡命","verses":[{"n":1,"t":"「那時，耶和華對我說：『你要鑿出兩塊石版，和先前的一樣，上山到我這裏來。你也要造一個木櫃。","notes":[]},{"n":2,"t":"我要把你先前摔碎的版上所寫的字，寫在這版上；你要把這版放在櫃裏。』","notes":[]},{"n":3,"t":"於是我用金合歡木造了一個櫃子，又鑿出兩塊石版，和先前的一樣。我手裏拿著這兩塊版上山。","notes":[]},{"n":4,"t":"耶和華將那大會之日、在山上從火中所吩咐你們的十條誡命，照先前所寫的寫在這版上。耶和華把它們交給我。","notes":[]},{"n":5,"t":"我轉身下山，將這版放在我所造的櫃裏，現今這版還在那裏，正如耶和華所吩咐我的。","notes":[]},{"n":6,"t":"（以色列人從比羅比尼‧亞干起行，來到摩西拉，亞倫死在那裏，就葬在那裏。他的兒子以利亞撒接續他擔任祭司的職分。","notes":["「比羅比尼‧亞干」或譯「比尼‧亞干井」。"]},{"n":7,"t":"他們從那裏起行，來到谷歌大，又從谷歌大來到約巴他，有溪水之地。","notes":[]},{"n":8,"t":"那時，耶和華將利未支派分別出來，抬耶和華的約櫃，又侍立在耶和華面前事奉他，奉他的名祝福，直到今日。","notes":[]},{"n":9,"t":"因此，利未沒有像他的弟兄有產業，耶和華是他的產業，正如耶和華－你神所應許他的。）","notes":[]},{"n":10,"t":"「我又像先前一樣在山上停留了四十晝夜。這一次耶和華也應允我，不將你滅絕。","notes":[]},{"n":11,"t":"耶和華對我說：『起來，走在百姓前面，領他們進去得我向他們列祖起誓要給他們的地。』」","notes":[]},{"n":12,"t":"「以色列啊，現在耶和華－你的神向你要的是甚麼呢？只要你敬畏耶和華－你的神，遵行他一切的道，愛他，盡心盡性事奉耶和華－你的神，","notes":[],"heads":["神的要求"]},{"n":13,"t":"遵守耶和華的誡命律例，就是我今日所吩咐你的，為要使你得福。","notes":[]},{"n":14,"t":"看哪，天和天上的天，地和地上所有的，都屬耶和華－你的神。","notes":[]},{"n":15,"t":"然而，耶和華專愛你的列祖，愛他們，從萬民中揀選你們，就是他們的後裔，像今日一樣。","notes":[]},{"n":16,"t":"所以你們的心要受割禮，不可再硬著頸項。","notes":[]},{"n":17,"t":"因為耶和華－你們的神是萬神之神，萬主之主，是偉大、強有力、可畏的神，不看人的情面，也不受賄賂。","notes":[]},{"n":18,"t":"他為孤兒寡婦伸冤，愛護寄居的，賜給他衣食。","notes":[]},{"n":19,"t":"所以你們要愛護寄居的，因為你們在埃及地也作過寄居的。","notes":[]},{"n":20,"t":"你要敬畏耶和華－你的神，事奉他，緊緊跟隨他，奉他的名起誓。","notes":[]},{"n":21,"t":"他是你當讚美的，是你的神，為你做了大而可畏的事，這些是你親眼見過的。","notes":[]},{"n":22,"t":"你的列祖七十人下埃及，現在耶和華－你的神卻使你如同天上的星那樣多。」","notes":[]}]},"11":{"heading":"神的偉大","verses":[{"n":1,"t":"「你要愛耶和華－你的神，天天遵守他的吩咐、律例、典章、誡命。","notes":[]},{"n":2,"t":"今日你們應當知道，而不是你們的兒女，因為他們不知道，也沒有見過耶和華─你們神的管教、他的偉大、他大能的手和伸出來的膀臂，","notes":[]},{"n":3,"t":"以及他在埃及向埃及王法老和其全地所行的神蹟奇事；","notes":[]},{"n":4,"t":"他怎樣對待埃及的軍隊、馬和戰車，他們追趕你們的時候，耶和華怎樣用紅海的水淹沒他們，消滅了他們，直到今日；","notes":[]},{"n":5,"t":"他在曠野怎樣待你們，直到你們來到這地方，","notes":[]},{"n":6,"t":"以及他怎樣待呂便子孫，以利押的兒子大坍、亞比蘭，地怎樣在以色列人中開了裂口，吞了他們和他們的家眷，帳棚，以及跟他們在一起所有活著的。","notes":[]},{"n":7,"t":"惟有你們親眼見過耶和華所做的一切大事。」","notes":[]},{"n":8,"t":"「所以，你們要遵守我今日所吩咐的一切誡命，使你們剛強，可以進去得你們所要得的那地，就是你們將過河到那裏要得的，","notes":[],"heads":["應許之地的福澤"]},{"n":9,"t":"也使你們的日子，在耶和華向你們列祖起誓要給他們和他們後裔的地上得以長久，那是流奶與蜜之地。","notes":[]},{"n":10,"t":"你要進去得為業的那地，不像你出來的埃及地。在埃及，你撒種後，要用腳澆灌，像澆灌菜園一樣。","notes":[]},{"n":11,"t":"你們要過去得為業的那地乃是有山有谷、天上的雨水滋潤之地，","notes":[]},{"n":12,"t":"是耶和華－你神所眷顧的地；從歲首到年終，耶和華－你神的眼目時常看顧那地。","notes":[]},{"n":13,"t":"「你們若留心聽從我今日所吩咐你們的誡命，愛耶和華－你們的神，盡心盡性事奉他，","notes":[]},{"n":14,"t":"我必按時降下雨水在你們的地上，就是秋雨和春雨，使你們可以收藏五穀、新酒和新的油，","notes":["「我」：撒瑪利亞五經、七十士譯本和其他古譯本是「他」。"]},{"n":15,"t":"也必使田野為你的牲畜長出草來；這樣，你必吃得飽足。","notes":[]},{"n":16,"t":"你們要謹慎，免得心受誘惑，轉去事奉別神，敬拜它們，","notes":[]},{"n":17,"t":"以致耶和華的怒氣向你們發作，使天封閉不下雨，使地不出產，使你們在耶和華所賜給你們的美地上速速滅亡。","notes":[]},{"n":18,"t":"「你們要將我這些話存在心裏，留在意念中，繫在手上作記號，戴在額上作經匣。","notes":["「額上」：原文是「兩眼之間」。"]},{"n":19,"t":"你們也要將這些話教導你們的兒女，無論坐在家裏，行在路上，躺下，起來，都要講論，","notes":[]},{"n":20,"t":"又要寫在房屋的門框上和你的城門上。","notes":[]},{"n":21,"t":"這樣，你們和你們子孫的日子必在耶和華向你們列祖起誓要給他們的地上得以增多，如天地之長久。","notes":[]},{"n":22,"t":"你們若留心謹守遵行我所吩咐這一切的誡命，愛耶和華－你們的神，遵行他一切的道，緊緊跟隨他，","notes":[]},{"n":23,"t":"他必從你們面前趕出這一切國家，你們也要佔領比你們更大更強的國家。","notes":[]},{"n":24,"t":"凡你們腳掌所踏之地都必歸於你們；從曠野到黎巴嫩，從幼發拉底大河，直到西邊的海，都要成為你們的疆土。","notes":[]},{"n":25,"t":"必無一人能在你們面前站立得住；耶和華－你們的神必照他所說的，使懼怕驚恐臨到你們所踏的全地。","notes":[]},{"n":26,"t":"「看，我今日將祝福與詛咒都陳明在你們面前。","notes":[]},{"n":27,"t":"你們若聽從耶和華─你們神的誡命，就是我今日所吩咐你們的，就必蒙福。","notes":[]},{"n":28,"t":"你們若不聽從耶和華─你們神的誡命，偏離我今日所吩咐你們的道，去隨從你們所不認識的別神，就必受詛咒。","notes":[]},{"n":29,"t":"當耶和華－你的神領你進入要得為業的那地，你就要在基利心山上宣佈祝福，在以巴路山上宣佈詛咒。","notes":[]},{"n":30,"t":"這二座山豈不是在約旦河的那邊，日落的方向，在住亞拉巴的迦南人之地，吉甲的前面，靠近摩利橡樹嗎？","notes":[]},{"n":31,"t":"你們過約旦河，進去得耶和華－你們的神所賜你們為業之地；當你們佔領它，在那地居住的時候，","notes":[]},{"n":32,"t":"你們要謹守遵行我今日在你們面前頒佈的一切律例典章。」","notes":[]}]},"12":{"heading":"惟一的敬拜場所","verses":[{"n":1,"t":"「你們活在世上的日子，在耶和華─你列祖的神所賜你為業的地上，你們要謹守遵行這些律例典章：","notes":[]},{"n":2,"t":"你們佔領的國家所事奉他們眾神明的地方，無論是在高山，在小山，在一切的青翠樹下，你們要徹底毀壞；","notes":[]},{"n":3,"t":"要拆毀他們的祭壇，打碎他們的柱像，用火焚燒他們的亞舍拉，砍斷他們神明的雕刻偶像，並要從那地方除去他們的名。","notes":[]},{"n":4,"t":"你們不可那樣敬拜耶和華－你們的神。","notes":[]},{"n":5,"t":"但耶和華－你們的神在你們各支派中選擇何處作為立他名的居所，你們就要到那裏求問，","notes":[]},{"n":6,"t":"將你們的燔祭、祭物、十一奉獻、手中的舉祭、還願祭、甘心祭，以及牛群羊群中頭生的，都帶到那裏。","notes":[]},{"n":7,"t":"在那裏，你們和你們的全家都可以在耶和華─你們神的面前吃，並且因你們手所做的一切蒙耶和華－你的神賜福而歡樂。","notes":[]},{"n":8,"t":"你們不可做像我們今日在這裏所做的，各人行自己眼中看為正的一切事；","notes":[]},{"n":9,"t":"因為你們現在還沒有進入耶和華－你神所賜你的安息，所給你的產業。","notes":[]},{"n":10,"t":"你們過了約旦河，住在耶和華─你們神給你們承受為業的地；他又使你們得享太平，不受四圍一切仇敵擾亂，使你們安然居住。","notes":[]},{"n":11,"t":"那時你們要將我所吩咐你們的燔祭、祭物、十一奉獻、手中的舉祭，和向耶和華許願的一切上好的祭，都帶到耶和華─你們神所選擇立他名的居所。","notes":[]},{"n":12,"t":"你們和兒女、僕婢，以及住在你們城裏，沒有與你們一起分得產業的利未人，都要在耶和華－你們的神面前歡樂。","notes":[]},{"n":13,"t":"你要謹慎，不可在自己所看中的各處獻燔祭。","notes":[]},{"n":14,"t":"惟獨耶和華從你的一個支派中所選擇的地方，你要在那裏獻燔祭，在那裏遵行我一切所吩咐你的。","notes":[]},{"n":15,"t":"「然而，你在各城裏都可以照著耶和華－你神所賜給你的福分，隨心所欲宰牲吃肉；無論潔淨的人不潔淨的人都可以吃，就如吃羚羊和鹿的肉一樣。","notes":[]},{"n":16,"t":"只是血，你不可吃，要把它倒在地上，如同倒水一樣。","notes":[]},{"n":17,"t":"你的五穀、新酒和新油的十分之一，或是牛群羊群中頭生的，或是你的許願祭、甘心祭和手中的舉祭，都不可在你的城裏吃，","notes":[]},{"n":18,"t":"必須在耶和華－你的神面前吃，在耶和華－你神所選擇的地方，你和兒女、僕婢，以及住在你城裏的利未人都可以吃，並要因你手所做的一切，在耶和華－你神面前歡樂。","notes":[]},{"n":19,"t":"你要謹慎，在你所住的地上，你永不可離棄利未人。","notes":[]},{"n":20,"t":"「耶和華－你的神照他的應許擴張你疆土的時候，你心裏想要吃肉，說：『我要吃肉』，就可以隨心所欲吃肉。","notes":[]},{"n":21,"t":"耶和華－你神選擇立他名的地方若離你太遠，你可以照我所吩咐的，將耶和華賜給你的牛羊取些宰了，隨心所欲在你的城裏吃。","notes":[]},{"n":22,"t":"其實，就如吃羚羊和鹿的肉一樣，你要這樣吃它，無論潔淨的人不潔淨的人都可以一起吃。","notes":[]},{"n":23,"t":"但是你要堅定，不可吃血，因為血是生命；不可將生命與肉一起吃。","notes":[]},{"n":24,"t":"你不可吃血，要把它倒在地上，如同倒水一樣。","notes":[]},{"n":25,"t":"不可吃血，好讓你和你的子孫可以得福，因為你行了耶和華眼中看為正的事。","notes":[]},{"n":26,"t":"只是你分別為聖的物和你所還的願，都要帶到耶和華所選擇的地方去。","notes":[]},{"n":27,"t":"你的燔祭，連肉帶血，都要獻在耶和華－你神的壇上。祭物的血要倒在耶和華－你神的壇上；肉你可以吃。","notes":[]},{"n":28,"t":"你要謹守聽從我所吩咐的一切話，好讓你和你的子孫可以永遠得福，因為你行耶和華－你神眼中看為善、看為正的事。」","notes":[]},{"n":29,"t":"「耶和華－你神把你要進去趕出的列國從你面前剪除，並且你得了他們的地為業居住，","notes":[],"heads":["不可敬拜別神"]},{"n":30,"t":"那時你要謹慎，在他們從你面前被除滅之後，你不可受引誘隨從他們，也不可求問他們的神明，說：『這些國家怎樣事奉他們的神明，我也要照樣做。』","notes":[]},{"n":31,"t":"你不可向耶和華－你的神這樣做，因為他們向他們的神明做了耶和華所憎恨、所厭惡的一切事，甚至將自己的兒女用火焚燒，獻給他們的神明。","notes":[]},{"n":32,"t":"凡我所吩咐你們的事，你們都要謹守遵行，不可加添，也不可刪減。」","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"「你中間若有先知或是做夢的人起來，向你顯神蹟奇事，","notes":[]},{"n":2,"t":"他對你說的神蹟奇事應驗了，說：『我們去隨從別神，事奉它們吧。』那是你不認識的。","notes":[]},{"n":3,"t":"你不可聽那先知或是那做夢之人的話，因為這是耶和華－你們的神考驗你們，要知道你們是否盡心盡性愛耶和華－你們的神。","notes":[]},{"n":4,"t":"你們要順從耶和華－你們的神，敬畏他，謹守他的誡命，聽從他的話，事奉他，緊緊跟隨他。","notes":[]},{"n":5,"t":"那先知或那做夢的人要被處死，因為他出言悖逆那領你們出埃及地、救贖你脫離為奴之家的耶和華－你們的神，要引誘你離開耶和華－你神吩咐你要行的道。這樣，你就把惡從你中間除掉。","notes":[]},{"n":6,"t":"「你的同胞兄弟，或是你的兒女，或是你懷中的妻，或是如同自己性命的朋友，若暗中引誘你，說：『我們去事奉別神吧。』那是你和你列祖所不認識的，","notes":[]},{"n":7,"t":"你四圍列國的神明，無論是離你近或離你遠，從地這邊到地那邊，","notes":[]},{"n":8,"t":"你都不可附和他，也不要聽從他。你的眼不可顧惜他，不可憐憫他，也不可袒護他。","notes":[]},{"n":9,"t":"你務必殺他；你先下手，然後眾百姓才下手，把他處死。","notes":[]},{"n":10,"t":"要用石頭打死他，因為他想引誘你離開那領你出埃及地為奴之家的耶和華－你的神。","notes":[]},{"n":11,"t":"全以色列都要聽見而害怕，不敢在你中間再行這樣的惡事了。","notes":[]},{"n":12,"t":"「若你聽見人說，在耶和華－你神所賜給你居住的城鎮中的一座，","notes":[]},{"n":13,"t":"有些無賴之徒從你中間出來，引誘本城的居民，說：『我們去事奉別神吧。』那是你們不認識的，","notes":[]},{"n":14,"t":"你就要調查，探聽，細心詢問。看哪，是真的，確實有這可憎的事在你中間發生，","notes":[]},{"n":15,"t":"你務必用刀殺那城裏的居民，把城裏所有的，連牲畜都用刀滅盡。","notes":[]},{"n":16,"t":"你要把從城裏所奪取的一切財物堆在廣場中，用火將那城和其中奪取的一切財物全燒給耶和華－你的神。那城要永遠成為廢墟，不得重建。","notes":[]},{"n":17,"t":"那當毀滅的物一點都不可黏你的手，好讓耶和華轉回，不向你發烈怒，卻恩待你，憐憫你，照他向你列祖所起的誓使你人數增多；","notes":[]},{"n":18,"t":"因為你聽從耶和華－你神的話，遵守我今日所吩咐你的一切誡命，行耶和華－你神眼中看為正的事。」","notes":[]}]},"14":{"heading":"舉哀時的禁例","verses":[{"n":1,"t":"「你們是耶和華─你們神的兒女。不可為了死人割劃自己，也不可使額上光禿；","notes":["「額上」：原文是「兩眼之間」。"]},{"n":2,"t":"因為你是屬於耶和華－你神神聖的子民，耶和華從地面上的萬民中揀選了你，作自己寶貴的子民。」","notes":[]},{"n":3,"t":"「凡可憎的物， 你都不可吃。","notes":[],"heads":["潔淨和不潔淨的食物"]},{"n":4,"t":"可吃的牲畜是：牛、綿羊、山羊、","notes":[]},{"n":5,"t":"鹿、羚、麃子、野山羊、瞪羚、羚羊、山綿羊。","notes":[]},{"n":6,"t":"凡蹄分兩瓣，分趾蹄而又反芻食物的牲畜，你們都可以吃。","notes":[]},{"n":7,"t":"但那反芻或分蹄之中不可吃的是：駱駝、兔子、石獾，雖然反芻卻不分蹄，對你們是不潔淨的；","notes":[]},{"n":8,"t":"豬，雖然分蹄卻不反芻，對你們也是不潔淨的。牠們的肉，你們一點都不可吃；牠們的屍體，你們也不可摸。","notes":[]},{"n":9,"t":"「水中可吃的是這些：凡有鰭有鱗的都可以吃；","notes":[]},{"n":10,"t":"凡無鰭無鱗的都不可吃，對你們是不潔淨的。","notes":[]},{"n":11,"t":"「凡潔淨的鳥，你們都可以吃。","notes":[]},{"n":12,"t":"不可吃的是：鵰、狗頭鵰、紅頭鵰、","notes":[]},{"n":13,"t":"鸇、小鷹、鷂鷹的類群，","notes":[]},{"n":14,"t":"各種烏鴉的類群、","notes":[]},{"n":15,"t":"鴕鳥、夜鷹、魚鷹、鷹的類群、","notes":[]},{"n":16,"t":"鴞鳥、貓頭鷹、角鴟、","notes":[]},{"n":17,"t":"鵜鶘、禿鵰、鸕鶿、","notes":[]},{"n":18,"t":"鸛、鷺鷥的類群、戴鵀與蝙蝠。","notes":[]},{"n":19,"t":"凡有翅膀卻爬行的群聚動物對你們是不潔淨的，都不可吃。","notes":[]},{"n":20,"t":"凡潔淨的鳥，你們都可以吃。","notes":[]},{"n":21,"t":"「凡自然死去的動物，你們都不可吃，可以給城裏寄居的人吃，或賣給外人，因為你是屬於耶和華－你神神聖的子民。「不可用母山羊的奶來煮牠的小山羊。」","notes":[]},{"n":22,"t":"「每年，你務必從你播種的一切收成，田地所出產的，取十分之一獻上。","notes":[],"heads":["十一奉獻的條例"]},{"n":23,"t":"要在耶和華－你神面前，就是他選擇那裏作為他名居所的地方，吃你所獻十分之一的五穀、新酒和新的油，以及牛群羊群中頭生的，好讓你天天學習敬畏耶和華－你的神。","notes":[]},{"n":24,"t":"當耶和華－你的神賜福給你的時候，耶和華－你神選擇立他名的地方若離你太遠，路途太長，使你不能把這東西帶到那裏去，","notes":[]},{"n":25,"t":"你可以把它換成銀子，把銀子包起來，拿在手中，往耶和華－你神所選擇的地方去。","notes":[]},{"n":26,"t":"在那裏，你可以隨心所欲用銀子或買牛羊，或買清酒烈酒，或買任何你心所想的。你和你的全家要在耶和華－你神面前吃喝歡樂。","notes":[]},{"n":27,"t":"「住在你城裏的利未人，你不可離棄他，因為他在你那裏沒有分得產業。","notes":[]},{"n":28,"t":"每三年的最後一年，你要把那一年收成的十分之一取出來，積存在你的城中；","notes":[]},{"n":29,"t":"那沒有與你一起分得產業的利未人，和城裏的寄居者，以及孤兒寡婦，都可以前來，吃得飽足，好讓耶和華－你的神在你手裏所做的一切事上賜福給你。」","notes":[]}]},"15":{"heading":"安息年的條例","verses":[{"n":1,"t":"「每七年的最後一年，你要施行豁免。","notes":[]},{"n":2,"t":"豁免的方式是這樣：凡債主要把手裏所借給鄰舍的全豁免，不可向鄰舍和弟兄追討，因為耶和華的豁免已經宣告了。","notes":[]},{"n":3,"t":"你可以向外邦人追討；但你弟兄欠你的，無論是甚麼，你都要放手豁免。","notes":[]},{"n":4,"t":"其實，在你中間不會有貧窮人；因為在耶和華－你神所賜你為業的地上，耶和華必大大賜福給你。","notes":[]},{"n":5,"t":"只要你留心聽從耶和華－你神的話，謹守遵行我今日所吩咐你這一切的命令，","notes":[]},{"n":6,"t":"因為耶和華－你的神會照他所應許你的賜福給你，你必借給許多國家，卻不需要去借貸；你要管轄許多國家，它們卻不能管轄你。","notes":[]},{"n":7,"t":"「在耶和華－你神所賜給你的地上，任何一座城裏，你弟兄中若有一個貧窮人，你不可硬著心，袖手不幫助你貧窮的弟兄。","notes":[]},{"n":8,"t":"你總要伸手幫助他，照他所缺乏的借給他，補他的不足。","notes":[]},{"n":9,"t":"你要謹慎，不可心起惡念，說：『第七年的豁免年快到了』，你就冷眼看你貧窮的弟兄，甚麼都不給他。他若為你的緣故求告耶和華，你就有罪了。","notes":[]},{"n":10,"t":"你要慷慨解囊，給他的時候不要心疼，因為耶和華－你的神必為這事，在你一切的工作上和你手所做的一切賜福給你。","notes":[]},{"n":11,"t":"因為地上的貧窮人永遠不會斷絕，所以我吩咐你說：『總要伸手幫助你地上困苦貧窮的弟兄。』」","notes":[]},{"n":12,"t":"「你弟兄中，若有一個希伯來男人或希伯來女人賣給你，已服事你六年，到了第七年就要讓他自由離開你。","notes":[],"heads":["奴婢的條例"]},{"n":13,"t":"你讓他自由離開的時候，不可讓他空手而去，","notes":[]},{"n":14,"t":"要從你的羊群、禾場、壓酒池中取一些，慷慨地送給他；耶和華－你的神怎樣賜福給你，你也要照樣給他。","notes":[]},{"n":15,"t":"要記得你在埃及地作過奴僕，耶和華－你的神救贖了你。為此，我今日將這事吩咐你。","notes":[]},{"n":16,"t":"他若對你說：『我不願意離開你』，因為他愛你和你的家，並且他在你那裏很好，","notes":[]},{"n":17,"t":"你要拿錐子在門上穿透他的耳朵，他就永遠成為你的奴僕了。你待婢女也要這樣。","notes":[]},{"n":18,"t":"你讓他從你那裏自由離開的時候，不要看作困難，因為他已服事你六年，相當於雇工雙倍的工錢。這樣，耶和華－你的神必在你所做的一切事上賜福給你。」","notes":[]},{"n":19,"t":"「你牛群羊群中頭生的，凡是公的，都要分別為聖，歸給耶和華－你的神。頭生的牛，不可用牠來耕作；頭生的羊，不可剪牠的毛。","notes":[],"heads":["頭生牛羊的條例"]},{"n":20,"t":"這頭生的，你和你全家每年要到耶和華所選擇的地方，在耶和華－你神面前吃。","notes":[]},{"n":21,"t":"這頭生的若有殘疾，瘸腿的或瞎眼的，若有任何嚴重缺陷，都不可獻給耶和華－你的神。","notes":[]},{"n":22,"t":"你們可以在城裏吃，潔淨的人和不潔淨的人都可以吃，就如吃羚羊和鹿一樣。","notes":[]},{"n":23,"t":"只是牠的血，你不可吃，要倒在地上，如同倒水一樣。」","notes":[]}]},"16":{"heading":"逾越節","verses":[{"n":1,"t":"「你要守亞筆月，向耶和華－你的神守逾越節，因為在亞筆月，耶和華－你的神在夜間領你出埃及。","notes":[]},{"n":2,"t":"你當在那裏，耶和華選擇作為他名居所的地方，從羊群牛群中，將逾越節的祭牲獻給耶和華－你的神。","notes":[]},{"n":3,"t":"這祭牲不可和有酵的東西一起吃。因為你曾匆忙離開埃及地，你要吃無酵餅，就是困苦餅七日，好讓你一生的年日記得你從埃及地出來的那一日。","notes":[]},{"n":4,"t":"在你全境內，七日不可見到酵母。第一日晚上所獻的肉，一點也不可留到早晨。","notes":[]},{"n":5,"t":"你不可在耶和華－你神所賜的各城中，任何一座城裏，獻逾越節的祭，","notes":[]},{"n":6,"t":"只可在那裏，耶和華－你神選擇作為他名居所的地方，在晚上日落的時候，就是你出埃及的時候，獻逾越節的祭。","notes":[]},{"n":7,"t":"你要在耶和華－你神所選擇的地方把肉烤來吃，次日早晨就回到你的帳棚去。","notes":[]},{"n":8,"t":"你要吃無酵餅六日，第七日要向耶和華－你的神守嚴肅會，不可做工。」","notes":[]},{"n":9,"t":"「你要計算七個七日：從你用鐮刀開始收割莊稼時算起，一共七個七日。","notes":[],"heads":["七七收穫節"]},{"n":10,"t":"你要向耶和華－你的神守七七節，按照耶和華－你神所賜你的福，獻上你手裏的甘心祭。","notes":[]},{"n":11,"t":"你和你的兒女、僕婢，以及住在你城裏的利未人、在你中間寄居的和孤兒寡婦，都要在那裏，耶和華－你神選擇作為他名居所的地方，在耶和華－你神面前歡樂。","notes":[]},{"n":12,"t":"你要記得你在埃及作過奴僕，也要謹守遵行這些律例。」","notes":[]},{"n":13,"t":"「你收藏了禾場和壓酒池的出產以後，就要守住棚節七日。","notes":[],"heads":["住棚節"]},{"n":14,"t":"在節期中，你和你的兒女、僕婢，以及住在你城裏的利未人、寄居的和孤兒寡婦，都要歡樂。","notes":[]},{"n":15,"t":"在耶和華所選擇的地方，你要向耶和華－你的神守節七日，因為耶和華－你的神要在你一切的收成上和你手裏所做的一切賜福給你，你就非常歡樂。","notes":[]},{"n":16,"t":"「你所有的男丁要在除酵節、七七節、住棚節，一年三次，在耶和華－你神所選擇的地方朝見他，不可空手朝見耶和華。","notes":[]},{"n":17,"t":"各人要按自己手中的能力，照耶和華－你神所賜你的福，奉獻禮物。」","notes":[]},{"n":18,"t":"「你要在耶和華－你神所賜的各城中，為各支派設立審判官和官長。他們要按公義的判斷審判百姓，","notes":[],"heads":["秉公審斷"]},{"n":19,"t":"不可屈枉正直，不可看人的情面，也不可接受賄賂，因為賄賂能使智慧人的眼睛變瞎，又能曲解義人的證詞。","notes":[]},{"n":20,"t":"公正！你要追求公正，好使你存活，承受耶和華－你神所賜你的地。」","notes":[]},{"n":21,"t":"「你為耶和華－你的神築壇，不可在壇旁栽種任何樹木作亞舍拉，","notes":[],"heads":["神所憎惡的敬拜"]},{"n":22,"t":"也不可為自己設立柱像，這是耶和華－你的神所憎恨的。」","notes":[]}]},"17":{"heading":"立王的指示","verses":[{"n":1,"t":"「凡有殘疾，有任何惡疾的牛羊，你都不可獻給耶和華－你的神，因為這是耶和華－你神所憎惡的。","notes":[]},{"n":2,"t":"「在你中間，在耶和華－你神所賜你的各城中，任何一座城裏，若有男人或女人做了耶和華－你神眼中看為惡的事，違背了他的約，","notes":[]},{"n":3,"t":"去事奉別神，敬拜它們，或拜太陽，或拜月亮，或拜天上的萬象，是我不曾吩咐的。","notes":["「我」：七十士譯本是「他」。"]},{"n":4,"t":"有人告訴你，你也聽見了，就要細心探聽。看哪，是真的，確實有這可憎的事在以色列中發生，","notes":[]},{"n":5,"t":"你就要將行這惡事的男人或女人拉到城門外，用石頭把這男人或女人處死。","notes":[]},{"n":6,"t":"要憑兩個證人或三個證人的口，才可以把他處死，不可只憑一個證人的口處死他。","notes":[]},{"n":7,"t":"證人要先動手，然後眾百姓也動手把他處死。這樣，你就把惡從你中間除掉。","notes":[]},{"n":8,"t":"「你城中若有難以判斷的案件，涉及流血，訴訟，或毆打等爭訟的事，你就要起來，上到那裏，耶和華－你神所選擇的地方，","notes":[]},{"n":9,"t":"去見利未家的祭司和當時的審判官，求問他們，他們必將判決指示你。","notes":[]},{"n":10,"t":"他們在耶和華所選擇的地方指示你的判決，你要執行，謹守遵行他們一切所教導你的。","notes":[]},{"n":11,"t":"要按照所教導你的律法、所告訴你的典章去執行；他們指示你的判決，你不可偏離左右。","notes":[]},{"n":12,"t":"若有人擅自行事，不聽從那侍立在耶和華－你神那裏事奉的祭司，或不聽從審判官，那人就要處死。這樣，你就把惡從以色列中除掉。","notes":[]},{"n":13,"t":"眾百姓聽見了都要害怕，不再擅自行事了。」","notes":[]},{"n":14,"t":"「你到了耶和華－你神所賜你的地，得了那地居住在其中的時候，若說：『我要立王治理我，像我四圍所有的國家一樣』，","notes":[]},{"n":15,"t":"你一定要立耶和華－你神所揀選的人為你的王。要從你弟兄中立一人為你的王，不可立你弟兄之外的外邦人治理你。","notes":[]},{"n":16,"t":"只是王不可為自己加添馬匹，也不可為加添馬匹使百姓回埃及去，因耶和華曾對你們說：『不可再回那條路去。』","notes":[]},{"n":17,"t":"王不可為自己多立妃嬪，免得他的心偏離；也不可為自己多積金銀。","notes":[]},{"n":18,"t":"他登了國度的王位之後，要在利未家的祭司面前，將這律法書為自己抄寫一份在書卷上。","notes":[]},{"n":19,"t":"這書要存在他那裏，他一生的年日要誦讀，好使他學習敬畏耶和華－他的神，謹守遵行這律法書上的一切話和這些律例，","notes":[]},{"n":20,"t":"免得他的心向弟兄高傲，偏離了這誡命，或向右或向左。這樣，他和他的子孫就可以長久作王治理以色列。」","notes":[]}]},"18":{"heading":"祭司和利未人應得的份","verses":[{"n":1,"t":"「利未家的祭司和利未全支派在以色列中沒有分得產業；他們可以吃耶和華的火祭，那是他的產業。","notes":[]},{"n":2,"t":"他在弟兄中沒有產業；耶和華是他的產業，正如耶和華所應許他的。","notes":[]},{"n":3,"t":"祭司從百姓當得的權益是這樣：凡獻牛或羊為祭物的，要把前腿、兩腮和胃給祭司。","notes":[]},{"n":4,"t":"初收的五穀、新酒和新的油，以及初剪的羊毛，也要給他。","notes":[]},{"n":5,"t":"因為耶和華－你的神從你眾支派中揀選他，使他和他子孫永遠奉耶和華的名侍立、事奉。","notes":[]},{"n":6,"t":"「利未人若離開他在以色列中所居住的任何一座城，一心願意到耶和華所選擇的地方，","notes":[]},{"n":7,"t":"就要在那裏奉耶和華－他神的名事奉，正如他的眾弟兄利未人在耶和華面前侍立一樣。","notes":[]},{"n":8,"t":"除了賣祖產所得的以外，他們要吃同等分量的祭物。」","notes":["「他們」：撒瑪利亞五經和七十士譯本是「他」。"]},{"n":9,"t":"「你到了耶和華－你神所賜你之地，不可學那些國家行可憎惡的事。","notes":[],"heads":["禁止異教的習俗"]},{"n":10,"t":"你中間不可有人使兒女經火，也不可有占卜的、觀星象的、行法術的 、行邪術的、","notes":[]},{"n":11,"t":"施符咒的、招魂的、行巫術的和求問死人的。","notes":[]},{"n":12,"t":"凡做這些事的都是耶和華所憎惡的；因這可憎惡的事，耶和華－你的神把他們從你面前趕出去。","notes":[]},{"n":13,"t":"你要向耶和華－你的神作完全人。","notes":[]},{"n":14,"t":"你所要趕出的那些國家都聽從觀星象的和占卜的，但是耶和華－你的神從來不准你這樣做。」","notes":[]},{"n":15,"t":"「耶和華－你的神要從你弟兄中給你興起一位先知像我，你們要聽他。","notes":[],"heads":["興起像摩西的先知"]},{"n":16,"t":"這正如你在何烈山大會的那日向耶和華－你的神所求的一切，說：『求你不要再叫我聽見耶和華－我神的聲音，也不要再叫我看見這大火，免得我死亡。』","notes":[]},{"n":17,"t":"耶和華對我說：『他們說得對。","notes":[]},{"n":18,"t":"我必在他們弟兄中給他們興起一位先知像你。我要將當說的話放在他口裏；他要將我一切所吩咐的都告訴他們。","notes":[]},{"n":19,"t":"誰不聽從他奉我名所說的話，我必親自向他追究。","notes":[]},{"n":20,"t":"若有先知擅自奉我的名說了我未曾吩咐他說的話，或是奉別神的名說話，那先知就必處死。』","notes":[]},{"n":21,"t":"你心裏若說：『我們怎能知道那話是耶和華未曾吩咐的呢？』","notes":[]},{"n":22,"t":"先知奉耶和華的名說話，所說的若沒有實現，或不應驗，這話就是耶和華未曾吩咐的，而是那先知擅自說的，你不必怕他。」","notes":[]}]},"19":{"heading":"逃城的設立","verses":[{"n":1,"t":"「耶和華－你的神將列國剪除，他們的地耶和華－你神已賜給你，你又趕出他們，並且住在他們的城鎮和房屋，","notes":[]},{"n":2,"t":"那時，你要在耶和華－你神所賜你為業的地上，為自己指定三座城。","notes":[]},{"n":3,"t":"你要預備道路，將耶和華－你神使你承受為業的地分為三區，使任何一個殺人的可以逃到那裏去。","notes":[]},{"n":4,"t":"「殺人的逃到那裏得以存活的案例是這樣：凡素無仇恨，無意中殺了鄰舍的，","notes":[]},{"n":5,"t":"就如人與鄰舍同入林中伐木，手拿斧子一砍，本想砍下樹木，斧頭卻脫了把，飛落在鄰舍身上，以致那人死去，這人就可以逃到那些城中的一座，得以存活，","notes":[]},{"n":6,"t":"免得報血仇的心中發火，去追趕那殺了人的，因為路途遙遠就能追上他，把他殺死。其實他是不該死的，因為他與被殺者素無仇恨。","notes":[]},{"n":7,"t":"所以我吩咐你說，要為自己指定三座城。","notes":[]},{"n":8,"t":"耶和華－你的神若照他向你列祖所起的誓擴張你的疆土，將所應許賜你列祖的全地給你，","notes":[]},{"n":9,"t":"你若謹守遵行我今日所吩咐的這一切誡命，愛耶和華－你的神，天天遵行他的道，就要在這三座城之外，再添三座城，","notes":[]},{"n":10,"t":"免得無辜人的血流在耶和華－你神所賜你為業的地中間，血就歸到你身上了。","notes":[]},{"n":11,"t":"「若有人恨他的鄰舍，埋伏等著，起來擊殺他，把他殺死，然後逃到這些城中的一座，","notes":[]},{"n":12,"t":"他本城的長老就要派人去，從那裏把他帶出來，交在報血仇者的手中，把他處死。","notes":[]},{"n":13,"t":"你的眼不可顧惜他，要從以色列中除掉流無辜血的罪，使你得福。」","notes":[]},{"n":14,"t":"「在耶和華－你神所賜你承受為業，所分得的地上，不可挪移你鄰舍的地界，因為這是前人所定的。」","notes":[],"heads":["地界"]},{"n":15,"t":"「人無論犯甚麼罪，作甚麼惡，不可單憑一個人的見證，總要憑兩個證人的口或三個證人的口才可定案。","notes":[],"heads":["證人的條例"]},{"n":16,"t":"若有人懷惡意，起來作證，控告他人犯法，","notes":[]},{"n":17,"t":"這兩個爭訟的人就要站在耶和華面前，和當時的祭司與審判官面前，","notes":[]},{"n":18,"t":"審判官要細心調查。看哪，證人作的是偽證，要用偽證陷害弟兄，","notes":[]},{"n":19,"t":"你們就要對付他如同他想要對付的弟兄一樣。這樣，你就把惡從你中間除掉。","notes":[]},{"n":20,"t":"其他的人聽見就害怕，不敢在你中間再行這樣的惡事了。","notes":[]},{"n":21,"t":"你的眼不可顧惜，要以命償命，以眼還眼，以牙還牙，以手還手，以腳還腳。」","notes":[]}]},"20":{"heading":"戰爭的條例","verses":[{"n":1,"t":"「你出去與仇敵作戰，若看見馬匹、戰車，以及比你更多的士兵，不要怕他們，因為領你出埃及地的耶和華－你的神與你同在。","notes":[]},{"n":2,"t":"你們將要上陣的時候，祭司要來，向士兵宣告，","notes":[]},{"n":3,"t":"對他們說：『以色列啊，要聽！你們今日將要與仇敵作戰，不要心驚膽戰，不要懼怕戰兢，也不要因他們驚慌，","notes":[]},{"n":4,"t":"因為與你們同去的是耶和華－你們的神，他要為你們與仇敵作戰，拯救你們。』","notes":[]},{"n":5,"t":"官長也要向士兵宣告說：『誰建了新的房屋尚未奉獻，他可以回家去，免得他陣亡，別人去奉獻。","notes":[]},{"n":6,"t":"誰栽植了葡萄園尚未享用所結的果子，他可以回家去，免得他陣亡，別人去享用。","notes":[]},{"n":7,"t":"誰與女子訂了婚尚未迎娶，他可以回家去，免得他陣亡，別人去娶。』","notes":[]},{"n":8,"t":"官長要繼續對士兵說：『誰懼怕，心驚膽戰，可以回家去，免得他弟兄的心像他的心一樣消沉。』","notes":[]},{"n":9,"t":"官長向士兵宣告完畢，軍官就率領士兵去了。","notes":[]},{"n":10,"t":"「你來到一座城，要攻城之前，先向它宣告和平。","notes":[]},{"n":11,"t":"那城若願意以和平回應，給你開城，城裏所有的人就要為你做苦工，服事你。","notes":[]},{"n":12,"t":"若那城拒絕和平，卻要與你打仗，你就要圍困那城。","notes":[]},{"n":13,"t":"耶和華－你的神把那城交在你手裏時，你就要用刀殺盡城裏的男丁。","notes":[]},{"n":14,"t":"至於婦女、孩童、牲畜和城裏所有的，你都可以取為自己的掠物。從仇敵所掠奪的，就是耶和華－你神所賜給你的，你都可以享用。","notes":[]},{"n":15,"t":"離你很遠的各城，就是不屬於這些國家的城鎮，你都要這樣對待他們。","notes":[]},{"n":16,"t":"但是這些民族的城鎮，就是耶和華－你神所賜給你的產業，其中凡有氣息的，一個都不可存留。","notes":[]},{"n":17,"t":"你要照耶和華－你神所吩咐的，將這些赫人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人全都滅絕，","notes":[]},{"n":18,"t":"免得他們教導你們去行一切可憎惡的事，就是他們向自己神明所行的，使你們得罪耶和華－你們的神。","notes":[]},{"n":19,"t":"「你若圍困一座城，需要攻打許多日子才能奪取，就不可用斧頭砍壞樹木。你可以吃樹上的果子，卻不可把樹砍下來。田間的樹木豈是人，讓你去圍攻的嗎？","notes":[]},{"n":20,"t":"只有那些你知道不能生產食物的樹才可以毀壞；你可以把它們砍下來造攻城的工具，攻打那與你打仗的城，直到把城攻下。」","notes":[]}]},"21":{"heading":"未結案的謀殺案件","verses":[{"n":1,"t":"「在耶和華－你神所賜你為業的地上，若發現有人被殺，暴屍野地，不知道是誰殺的，","notes":[]},{"n":2,"t":"長老和審判官就要出去，從屍體那裏量起，量到四圍的城鎮，","notes":["「審判官」：撒瑪利亞五經是「官長」。"]},{"n":3,"t":"看哪一座城最靠近這屍體，那城的幾位長老就要取一頭未曾耕地、未曾負軛的母牛犢；","notes":[]},{"n":4,"t":"那城的長老要把這母牛犢牽到流著溪水、未曾耕耘、未曾撒種的山谷去，在谷中打斷牠的頸項。","notes":[]},{"n":5,"t":"利未人祭司要近前來，因為耶和華－你的神揀選他們來事奉他，奉耶和華的名祝福，並且有任何的爭訟和毆打，都由他們的口判決。","notes":[]},{"n":6,"t":"離屍體最近的那座城的每位長老要在山谷中，在頸項被打斷的母牛犢上面洗手，","notes":[]},{"n":7,"t":"聲明說：『我們的手未曾流這人的血；我們的眼也未曾看見這事。","notes":[]},{"n":8,"t":"耶和華啊，求你赦免你所救贖的百姓以色列，不要讓無辜的血歸在你的百姓以色列中間。』這樣，他們流血的罪就必得赦免。","notes":[]},{"n":9,"t":"你行了耶和華眼中看為正的事，就可以從你中間除掉無辜的血。」","notes":[]},{"n":10,"t":"「你出去與仇敵作戰的時候，耶和華－你的神將他交在你手中，你就擄了他為俘虜。","notes":[],"heads":["娶女俘虜的條例"]},{"n":11,"t":"若你在被擄的人中看見美麗的女子，喜歡她，要娶她為妻，","notes":[]},{"n":12,"t":"就可以帶她到你家去。她要剪頭髮，修指甲，","notes":[]},{"n":13,"t":"脫去被擄時所穿的衣服，住在你家裏為自己父母哀哭一個月。然後，你就可以與她同房；你作她的丈夫，她作你的妻子。","notes":[]},{"n":14,"t":"以後你若不喜歡她，就要讓她自由離開，絕不可為錢把她賣了，也不可把她當奴隸看待，因為你已經佔有過她。」","notes":[]},{"n":15,"t":"「人若有兩個妻子，一個是他寵愛的，另一個是失寵的，她們都給他生了兒子，但長子是他失寵妻子生的；","notes":["「失寵的」：原文是「被恨的」；下同。"],"heads":["長子的繼承權"]},{"n":16,"t":"到了分產業給兒子的時候，不可將自己寵愛的妻子所生的兒子立為長子，在他失寵妻子所生的長子之上。","notes":[]},{"n":17,"t":"他必須認失寵妻子所生的兒子為長子，在所有的產業中給他雙分，因為這兒子是他壯年時生的，長子的名分應當是他的。」","notes":[]},{"n":18,"t":"「人若有頑梗忤逆的兒子，不聽從父母的話，他們雖然懲戒他，他還是不聽從他們，","notes":[],"heads":["逆子的處置"]},{"n":19,"t":"父母就要抓住他，帶他出去到當地的城門，本城的長老那裏，","notes":[]},{"n":20,"t":"對本城的長老說：『我們這個兒子頑梗忤逆，不聽從我們的話，是貪食好酒的人。』","notes":[]},{"n":21,"t":"然後，城裏的眾人就要用石頭將他打死。這樣，你就把惡從你中間除掉，全以色列聽見了都要害怕。」","notes":[]},{"n":22,"t":"「人若犯了死罪被處死，你把他掛在木頭上，","notes":[],"heads":["其他條例"]},{"n":23,"t":"不可讓屍體留在木頭上過夜，一定要當日把他埋葬，因為被掛的人是神所詛咒的。你不可玷污耶和華－你神所賜你為業的地。」","notes":[]}]},"22":{"heading":"貞潔的條例","verses":[{"n":1,"t":"「你若看見弟兄的牛或羊迷了路，不可避開牠們，總要把牠們牽回來交給你的弟兄。","notes":[]},{"n":2,"t":"你弟兄若離你遠，或是你不認識他，你就要牽到你家，留在你那裏，等你的弟兄來尋找就還給他。","notes":[]},{"n":3,"t":"你弟兄所失落的，無論是驢，衣服，或任何東西，你若發現，都要這樣做，不能避開。","notes":[]},{"n":4,"t":"你若看見你弟兄的牛或驢在路上跌倒了，不可避開牠們，總要幫助他把牛或驢拉起來。","notes":[]},{"n":5,"t":"「婦女不可穿戴男子所穿戴的，男人也不可穿婦女的衣服，因為這樣做是耶和華－你神所憎惡的。","notes":[]},{"n":6,"t":"「你若路上看見鳥窩，無論在樹上或地上，裏頭有小鳥或有蛋，母鳥伏在小鳥或蛋上，你不可連母鳥帶小鳥一起拿去。","notes":[]},{"n":7,"t":"總要放母鳥走，只可以取小鳥。這樣你就可以享福，日子得以長久。","notes":[]},{"n":8,"t":"「你若建造新房屋，要在屋頂安欄杆，免得有人從屋頂掉下來，血就歸於你家。","notes":[]},{"n":9,"t":"「不可在你的葡萄園裏栽種別的種子，免得你栽種所結的和葡萄園的果子都成了聖物。","notes":[]},{"n":10,"t":"不可並用牛和驢來耕地。","notes":[]},{"n":11,"t":"不可穿羊毛和細麻混合做成的衣服。","notes":[]},{"n":12,"t":"「你要在所披外衣的四個邊上縫繸子。」","notes":[]},{"n":13,"t":"「人若娶妻，與她同房後恨惡她，","notes":[]},{"n":14,"t":"捏造她行可恥的事，把醜名加在她身上，說：『我娶了這女人，親近她，卻發現她沒有貞潔的憑據』。","notes":[]},{"n":15,"t":"女方的父母就要把這女子貞潔的憑據拿出去，到城門的本城長老那裏。","notes":[]},{"n":16,"t":"女方的父親要對長老說：『我把女兒嫁給這人，他卻恨惡她，","notes":[]},{"n":17,"t":"看哪，他捏造可恥的事，說：我發現你女兒沒有貞潔的憑據。但是，這就是我女兒貞潔的憑據。』父母要把那布鋪在本城長老的面前。","notes":[]},{"n":18,"t":"那城的長老要拿住那人，懲罰他，","notes":[]},{"n":19,"t":"罰他一百銀子，給女方的父親，因為他把醜名加在以色列一個少女身上。這女子仍是他的妻子，那人終身不可休她。","notes":[]},{"n":20,"t":"但若這事是真的，找不到女子貞潔的憑據，","notes":[]},{"n":21,"t":"他們就要把這女子帶到她父家的門口，城裏的人要用石頭打死她，因為她在父家犯了淫亂，在以色列中做了可恥的事。這樣，你就把惡從你中間除掉。","notes":[]},{"n":22,"t":"「若發現有人與有夫之婦同寢，就要將姦夫淫婦一起處死。這樣，你就把惡從以色列中除掉。","notes":[]},{"n":23,"t":"「若一女子是處女，已經許配了人，有男子在城裏遇見她，與她同寢，","notes":[]},{"n":24,"t":"你們就要把這二人帶到那城的城門口，用石頭打死他們。處死女子是因為她雖然在城裏， 卻沒有喊叫；處死男子是因為他玷污了鄰舍的妻子。這樣，你就把惡從你中間除掉。","notes":[]},{"n":25,"t":"「若有男子在野地遇見已經許配人的女子，抓住她與她同寢，只要處死那與女子同寢的男子。","notes":[]},{"n":26,"t":"不可對女子處刑，這女子沒有該死的罪。這案件就好比人起來攻擊鄰舍，把他殺了一樣。","notes":[]},{"n":27,"t":"因為男子是在野地遇見她，這已經許配了人的女子雖然喊叫，卻沒有人救她。","notes":[]},{"n":28,"t":"「若有男子遇見沒有許配人的少女，抓住她與她同寢，被人發現，","notes":[]},{"n":29,"t":"這男子就要拿五十銀子給女子的父親，並要娶她為妻，終身不可休她，因為他玷污了這女子。","notes":[]},{"n":30,"t":"「人不可娶繼母為妻，不可掀開父親衣服的下邊。」","notes":["「掀開...下邊」意思是「侵犯父親的權益」；27．20同。"]}]},"23":{"heading":"不可進入聖會的人","verses":[{"n":1,"t":"「凡外腎損傷的，或被閹割的，不可入耶和華的會。","notes":[]},{"n":2,"t":"「私生子不可入耶和華的會；甚至到第十代，也不可入耶和華的會。","notes":[]},{"n":3,"t":"「亞捫人或摩押人不可入耶和華的會；甚至到第十代，也永不可入耶和華的會。","notes":[]},{"n":4,"t":"因為你們出埃及的時候，他們沒有拿食物和水在路上迎接你們，並且雇了美索不達米亞的毗奪人，比珥的兒子巴蘭來詛咒你。","notes":[]},{"n":5,"t":"然而耶和華－你的神不願聽巴蘭，耶和華－你的神為你使詛咒變為祝福，因為耶和華－你的神愛你。","notes":[]},{"n":6,"t":"你一生一世永不可為他們求平安和福氣。","notes":[]},{"n":7,"t":"「不可憎惡以東人，因為他是你的弟兄。不可憎惡埃及人，因為你曾在他的地上作過寄居的。","notes":[]},{"n":8,"t":"他們所生的第三代子孫可以入耶和華的會。」","notes":[]},{"n":9,"t":"「你出兵攻打敵人，要遠離一切惡事。","notes":[],"heads":["軍營的衛生"]},{"n":10,"t":"「你中間若有人因夜間夢遺而不潔淨，就要出到營外，不可入營。","notes":[]},{"n":11,"t":"到了傍晚，他要用水洗澡，等到日落才可以入營。","notes":[]},{"n":12,"t":"「你要在營外劃定一個地方，你可以出去在那裏方便。","notes":[]},{"n":13,"t":"在你器械中當有一把鍬；你出營外便溺以後，要用它挖洞，轉身掩蓋排泄物。","notes":[]},{"n":14,"t":"因為耶和華－你的神在你營中走動，要拯救你，將仇敵交給你，所以你的營應當聖潔，免得他見你那裏有污穢之物就轉身離開你。」","notes":[]},{"n":15,"t":"「你不可把從主人身邊逃到你那裏的奴僕，交回給他的主人，","notes":[],"heads":["一般條例"]},{"n":16,"t":"要讓他在你那裏與你同住，由他在你的城鎮中選擇一個自己喜歡的地方居住，不可欺負他。","notes":[]},{"n":17,"t":"「以色列的女子中不可作神廟娼妓；以色列的男子中也不可作神廟娼妓。","notes":[]},{"n":18,"t":"妓女和男娼的賞金，都不可帶進耶和華－你神的殿中還願，因為兩者都是耶和華－你神所憎惡的。","notes":["「男娼」：原文是「狗」。"]},{"n":19,"t":"「你借給你弟兄的，無論是錢財是糧食，或任何可生利息的財物，都不可取利。","notes":[]},{"n":20,"t":"借給外邦人可以取利，但借給你的弟兄就不可取利；好讓耶和華－你的神在你去得為業的地上和你手裏所做的一切，賜福給你。","notes":[]},{"n":21,"t":"「你向耶和華－你的神許願，不可遲延還願，因為耶和華－你的神必定向你追討，你就有罪了。","notes":[]},{"n":22,"t":"你若不許願，倒沒有罪。","notes":[]},{"n":23,"t":"你嘴唇所說的，你親口承諾的，要照你甘心向耶和華－你神許的願謹守遵行。","notes":[]},{"n":24,"t":"「你進入鄰舍的葡萄園，可以隨意吃葡萄，直到飽足，卻不可裝在器皿中。","notes":[]},{"n":25,"t":"你進入鄰舍的莊稼中，可以用手摘麥穗，卻不可用鐮刀割取莊稼。」","notes":[]}]},"24":{"heading":"休妻和再婚的條例","verses":[{"n":1,"t":"「人若娶妻，作了她的丈夫，發現她有不合宜的事不喜歡她，而寫休書交在她手中，打發她離開夫家，","notes":[]},{"n":2,"t":"婦人若離開夫家以後，去嫁別人，","notes":[]},{"n":3,"t":"後夫若恨惡她，寫休書交在她手中，打發她離開夫家，又或者娶她為妻的後夫死了，","notes":[]},{"n":4,"t":"那休她的前夫就不可在婦人玷污之後再娶她為妻，因為這是耶和華所憎惡的。不可使耶和華－你神所賜為業之地蒙受玷污。","notes":[]},{"n":5,"t":"「人若娶了新娘，不可從軍出征，也不可派他辦理任何事情。他可以在家清閒一年，使他所娶的妻快活。","notes":[],"heads":["一般條例"]},{"n":6,"t":"「不可拿人的石磨或上面的磨石作抵押，因為這是拿人的命作抵押。","notes":[]},{"n":7,"t":"「若發現有人綁架以色列人中的一個弟兄，把他當奴隸對待，或把他賣了，那綁架人的就必處死。這樣，你就把惡從你中間除掉。","notes":[]},{"n":8,"t":"「關於痲瘋的災病，你們要謹慎，照利未家的祭司一切所指教你們的留心遵行。我怎樣吩咐他們，你們要照樣遵行。","notes":["「痲瘋」泛指傳染性皮膚病。"]},{"n":9,"t":"要記得，在你們出埃及後的路途中，耶和華－你的神向米利暗所做的事。","notes":[]},{"n":10,"t":"「你借給鄰舍，無論是甚麼，不可進他家拿抵押品。","notes":[]},{"n":11,"t":"要站在外面，等那借貸的人把抵押品拿出來交給你。","notes":[]},{"n":12,"t":"他若是困苦的人，你不可用他的抵押品蓋著睡覺。","notes":[]},{"n":13,"t":"日落的時候，總要把抵押品還給他，讓他用那件外衣蓋著睡覺，他就為你祝福。這在耶和華－你的神面前就是你的義行了。","notes":[]},{"n":14,"t":"「困苦貧窮的雇工，無論是你的弟兄，或是住在你境內，在你城裏寄居的，你都不可欺負他。","notes":["「欺負他」：七十士譯本是「扣留他的工錢」。"]},{"n":15,"t":"要當日給他工錢，不可等到日落，因為他困苦，需要靠工錢過活，免得他因你的緣故求告耶和華，罪就歸於你了。","notes":[]},{"n":16,"t":"「不可因兒子處死父親，也不可因父親處死兒子；各人要因自己的罪被處死。","notes":[]},{"n":17,"t":"「不可對寄居的和孤兒屈枉正直，也不可拿寡婦的衣服作抵押。","notes":[]},{"n":18,"t":"要記得你曾在埃及作過奴僕，耶和華－你的神從那裏救贖了你，所以我吩咐你遵行這事。","notes":[]},{"n":19,"t":"「你在田間收割莊稼，若忘了一捆在田間，就不要再回去拿，要留給寄居的、孤兒和寡婦；好讓耶和華－你的神在你手裏所做的一切，賜福給你。","notes":[]},{"n":20,"t":"你打了橄欖樹，枝上剩下的不可再打，要留給寄居的、孤兒和寡婦。","notes":[]},{"n":21,"t":"你摘葡萄園的葡萄，掉落的不可拾取，要留給寄居的、孤兒和寡婦。","notes":[]},{"n":22,"t":"你要記得你曾在埃及地作過奴僕，所以我吩咐你遵行這事。","notes":[]}]},"25":{"heading":"為去世的兄弟傳宗接代","verses":[{"n":1,"t":"「人與人若有爭訟，要求審判，當宣判義人為義，惡人有罪的時候，","notes":[]},{"n":2,"t":"惡人若該受責打，審判官就要叫他當著面，伏在地上，按他的罪照數責打。","notes":[]},{"n":3,"t":"只能打四十下，不可加多；多過這數目就是在你眼中作賤你的弟兄了。","notes":[]},{"n":4,"t":"「牛在踹穀的時候，不可籠住牠的嘴。」","notes":[]},{"n":5,"t":"「兄弟住在一起，若其中一個死了，沒有兒子，死者的妻子就不可出去嫁給陌生人。她丈夫的兄弟應當盡兄弟的本分，娶她為妻，與她同房。","notes":[]},{"n":6,"t":"婦人生的長子要歸在已故兄弟的名下，免得他的名在以色列中塗去了。","notes":[]},{"n":7,"t":"那人若不情願娶他兄弟的妻子，他兄弟的妻子就要上到城門長老那裏，說：『我丈夫的兄弟拒絕在以色列中為他的兄弟留名，不願意為我盡兄弟的本分。』","notes":[]},{"n":8,"t":"本城的長老就要召那人來，跟他談話。若他堅持說：『我不情願娶她。』","notes":[]},{"n":9,"t":"他兄弟的妻子就要在長老眼前來到那人跟前，脫下他腳上的鞋，吐唾沫在他臉上，回應說：『凡不為兄弟建立家室的都要這樣待他。』","notes":[]},{"n":10,"t":"在以色列中，他要以『脫鞋之家』聞名。」","notes":[]},{"n":11,"t":"「若有人和弟兄爭鬥，其中一人的妻子近前去，為了救丈夫脫離那打丈夫之人的手，伸手抓住那人的下體，","notes":[],"heads":["其他條例"]},{"n":12,"t":"你就要砍斷婦人的手，你的眼不可顧惜。","notes":[]},{"n":13,"t":"「你袋中不可有一大一小兩樣的法碼。","notes":[]},{"n":14,"t":"你家裏不可有一大一小兩樣的伊法。","notes":["「伊法」是量固體的量器或單位；下同。"]},{"n":15,"t":"當用準確公正的法碼和伊法，好使你的日子在耶和華－你神所賜你的地上得以長久。","notes":[]},{"n":16,"t":"因為行這一切不義之事的人都是耶和華－你神所憎惡的。」","notes":[]},{"n":17,"t":"「你要記得你們出埃及的時候，亞瑪力在路上怎樣對待你，","notes":[],"heads":["命令消滅亞瑪力人"]},{"n":18,"t":"在路上迎擊你，趁你疲乏困倦時擊殺所有在你後面軟弱的人；並不敬畏神。","notes":[]},{"n":19,"t":"所以，當耶和華－你的神使你不被四圍一切仇敵擾亂，在耶和華－你神賜你為業的地上得享平靜的時候，你要把亞瑪力的名從天下塗去；你不可忘記這事。」","notes":[]}]},"26":{"heading":"奉獻初熟的土產","verses":[{"n":1,"t":"「你進去得了耶和華－你神所賜你為業的地，並且居住在那裏的時候，","notes":[]},{"n":2,"t":"就要從耶和華－你神所賜你的地上，將收成的各種初熟土產取一些來，盛在筐子裏，帶到那裏，耶和華－你神選擇作為他名居所的地方，","notes":[]},{"n":3,"t":"到當時的祭司那裏，對他說：『我今日向耶和華－你的神宣認，我已來到耶和華向我們列祖起誓要賜給我們的地。』","notes":[]},{"n":4,"t":"祭司就從你手裏把筐子接過來，供在耶和華－你神的祭壇前。","notes":[]},{"n":5,"t":"你要在耶和華－你神面前告白說：『我的祖先原是一個流亡的亞蘭人，帶著稀少的人丁下到埃及寄居。在那裏，他卻成了又大又強、人數眾多的國。","notes":[]},{"n":6,"t":"埃及人惡待我們，迫害我們，將苦工加在我們身上。","notes":[]},{"n":7,"t":"於是我們哀求耶和華我們列祖的神。耶和華聽見我們的聲音，看見我們所受的困苦、勞役和欺壓，","notes":[]},{"n":8,"t":"耶和華就用大能的手和伸出來的膀臂，以及大而可畏的事和神蹟奇事，領我們出了埃及，","notes":[]},{"n":9,"t":"將我們領進這地方，把這流奶與蜜之地賜給我們。","notes":[]},{"n":10,"t":"耶和華啊，看哪，現在我把你所賜我地上初熟的土產供上。』隨後你要把筐子供在耶和華－你神面前，向耶和華－你的神下拜。","notes":[]},{"n":11,"t":"你和利未人，以及在你中間寄居的，要因耶和華－你神所賜你和你家的一切福分歡樂。","notes":[]},{"n":12,"t":"「每逢第三年，就是捐十分之一的那年，你從你一切土產中取了十分之一，要分給利未人、寄居的、孤兒和寡婦，使他們在你的城鎮中可以吃得飽足。","notes":[]},{"n":13,"t":"你又要在耶和華－你神面前說：『我已將聖物從家裏拿出來，給了利未人、寄居的、孤兒和寡婦，是遵照你吩咐我的一切命令。你的命令，我沒有違背，也沒有忘記。","notes":[]},{"n":14,"t":"我守喪的時候，沒有吃這聖物，不潔淨的時候，也沒有拿出來，又沒有把它獻給死人。我聽從了耶和華－我神的話，都照你一切所吩咐的做了。","notes":[]},{"n":15,"t":"求你從天上，從你的聖所垂看，賜福給你的百姓以色列和你向我們列祖起誓所賜給我們的這片土地，就是流奶與蜜之地。』」","notes":[]},{"n":16,"t":"「耶和華－你的神今日吩咐你遵行這些律例典章，所以你要盡心盡性謹守遵行。","notes":[],"heads":["作神聖的子民"]},{"n":17,"t":"你今日宣認耶和華為你的神，承諾遵行他的道，謹守他的律例、誡命、典章，聽從他的話。","notes":[]},{"n":18,"t":"耶和華今日照他所應許你的，也認你為他寶貴的子民，叫你謹守他的一切誡命，","notes":[]},{"n":19,"t":"要使你得稱讚、美名、尊榮，超乎他所造的萬國之上，並且照他所應許的，使你歸耶和華－你的神為神聖的子民。」","notes":[]}]},"27":{"heading":"寫在石頭上的律法和石壇","verses":[{"n":1,"t":"摩西和以色列的眾長老吩咐百姓說：「你們要遵守我今日所吩咐的一切誡命。","notes":[]},{"n":2,"t":"你們過了約旦河，到耶和華－你神所賜給你的地，當日要豎立幾塊大石頭，塗上石灰。","notes":[]},{"n":3,"t":"當你過了河，進入耶和華－你神所賜給你流奶與蜜之地，正如耶和華－你列祖的神所應許你的，你要把這律法的一切話寫在石頭上。","notes":[]},{"n":4,"t":"你們過了約旦河，就要在基利心山上照我今日所吩咐的，把這些石頭豎立起來，塗上石灰。","notes":["「基利心山」是根據撒瑪利亞五經和一些古譯本；原文是「以巴路山」。"]},{"n":5,"t":"你在那裏要為耶和華－你的神築一座石壇，卻不可動用鐵器在石頭上。","notes":[]},{"n":6,"t":"要用沒有鑿過的石頭築耶和華－你神的壇，在壇上將燔祭獻給耶和華－你的神，","notes":[]},{"n":7,"t":"又要獻平安祭，在那裏吃，在耶和華－你的神面前歡樂。","notes":[]},{"n":8,"t":"你要將這律法的一切話清楚地寫在石頭上。」","notes":[]},{"n":9,"t":"摩西和利未家的祭司吩咐以色列眾人說：「以色列啊，你要靜默傾聽！你今日已成為耶和華－你神的子民了。","notes":[]},{"n":10,"t":"你要聽從耶和華－你神的話，遵行他的誡命律例，就是我今日所吩咐你的。」","notes":[]},{"n":11,"t":"當日，摩西吩咐百姓說：","notes":[],"heads":["違命必受詛咒"]},{"n":12,"t":"「你們過了約旦河，西緬、利未、猶大、以薩迦、約瑟和便雅憫等支派的人要站在基利心山上為百姓祝福。","notes":[]},{"n":13,"t":"呂便、迦得、亞設、西布倫、但和拿弗他利等支派的人要站在以巴路山上宣佈詛咒。","notes":[]},{"n":14,"t":"利未人要大聲對以色列眾人說：","notes":[]},{"n":15,"t":"「『凡製造耶和華所憎惡的偶像，無論是雕刻的，是鑄造的，就是工匠用手造的，或暗中設置的，這人必受詛咒！』眾百姓要回應說：『阿們！』","notes":[]},{"n":16,"t":"「『輕慢父母的，必受詛咒！』眾百姓要說：『阿們！』","notes":[]},{"n":17,"t":"「『挪移鄰舍地界的，必受詛咒！』眾百姓要說：『阿們！』","notes":[]},{"n":18,"t":"「『引領瞎子走錯路的，必受詛咒！』眾百姓要說：『阿們！』","notes":[]},{"n":19,"t":"「『對寄居的、孤兒和寡婦屈枉正直的，必受詛咒！』眾百姓要說：『阿們！』","notes":[]},{"n":20,"t":"「『與繼母同寢的，必受詛咒！因為他掀開父親衣服的下邊。』眾百姓要說：『阿們！』","notes":[]},{"n":21,"t":"「『與獸交合的，必受詛咒！』眾百姓要說：『阿們！』","notes":[]},{"n":22,"t":"「『與同父異母，或同母異父的姊妹同寢的，必受詛咒！』眾百姓要說：『阿們！』","notes":[]},{"n":23,"t":"「『與岳母同寢的，必受詛咒！』眾百姓要說：『阿們！』","notes":[]},{"n":24,"t":"「『暗中擊殺鄰舍的，必受詛咒！』眾百姓要說：『阿們！』","notes":[]},{"n":25,"t":"「『受賄賂擊殺人而流無辜之血的，必受詛咒！』眾百姓要說：『阿們！』","notes":[]},{"n":26,"t":"「『不堅守遵行這律法之話的，必受詛咒！』眾百姓要說：『阿們！』」","notes":[]}]},"28":{"heading":"遵行誡命蒙福","verses":[{"n":1,"t":"「你若留心聽從耶和華－你神的話，謹守遵行他的一切誡命，就是我今日所吩咐你的，他必使你超乎地上的萬國之上。","notes":[]},{"n":2,"t":"你若聽從耶和華－你神的話，這一切的福氣必臨到你身上，追隨你：","notes":[]},{"n":3,"t":"你在城裏必蒙福，在田間也必蒙福。","notes":[]},{"n":4,"t":"你身所生的，你地所產的，你牲畜所生的，牛犢、羔羊，都必蒙福。","notes":[]},{"n":5,"t":"你的筐子和你的揉麵盆都必蒙福。","notes":[]},{"n":6,"t":"你出也蒙福，入也蒙福。","notes":[]},{"n":7,"t":"「耶和華必使那起來攻擊你的仇敵在你面前潰敗。他們從一條路來攻擊你，必在你面前從七條路逃跑。","notes":[]},{"n":8,"t":"在你倉房裏，以及你手所做的一切，耶和華必發令賜福給你。耶和華－你神也必在所賜你的地上賜福給你。","notes":[]},{"n":9,"t":"你若謹守耶和華－你神的誡命，遵行他的道，他必照他向你所起的誓立你為自己神聖的子民。","notes":[]},{"n":10,"t":"地上的萬民見你歸在耶和華的名下，就必懼怕你。","notes":[]},{"n":11,"t":"在耶和華向你列祖起誓應許賜你的土地上，他必使你身所生的，牲畜所生的，地所產的，都豐富有餘。","notes":[]},{"n":12,"t":"耶和華必為你敞開天上的寶庫，按時降雨在你的地上。他必賜福你手裏所做的一切。你必借給許多國家，卻不必去借貸。","notes":[]},{"n":13,"t":"你若聽從耶和華－你神的誡命，就是我今日所吩咐你的，謹守遵行，耶和華就必使你作首不作尾，居上不居下，","notes":[]},{"n":14,"t":"只要你不偏左右，不背離我今日所吩咐你的一切話，也不隨從別神，事奉它們。」","notes":[]},{"n":15,"t":"「你若不聽從耶和華－你神的話，不謹守遵行他的一切誡命律例，就是我今日所吩咐你的，這一切的詛咒必臨到你身上，追隨你：","notes":[],"heads":["違反誡命遭禍"]},{"n":16,"t":"你在城裏必受詛咒，在田間也必受詛咒。","notes":[]},{"n":17,"t":"你的筐子和你的揉麵盆都必受詛咒。","notes":[]},{"n":18,"t":"你身所生的，你地所產的，以及牛犢、羔羊，都必受詛咒。","notes":[]},{"n":19,"t":"你出也受詛咒，入也受詛咒。","notes":[]},{"n":20,"t":"耶和華因你作惡離棄他，必在你手裏所做的一切，使詛咒、困擾、責罰臨到你，直到你被除滅，直到你迅速滅亡。","notes":[]},{"n":21,"t":"耶和華必使瘟疫緊貼著你，直到他把你從所進去得為業的地上滅絕。","notes":[]},{"n":22,"t":"耶和華要用癆病、熱病、發炎、高燒、刀劍、焚風和霉爛攻擊你；這些要追趕你，直到你滅亡。","notes":["「刀劍」：原文另譯「乾旱」。","「焚風」或譯「蟲害」。"]},{"n":23,"t":"你頭上的天要變成銅，下面的地要化為鐵。","notes":[]},{"n":24,"t":"耶和華要使那降在你地上的雨變為灰塵，塵土從天落在你身上，直到你被除滅。","notes":[]},{"n":25,"t":"「耶和華必使你在仇敵面前潰敗。你從一條路去攻擊他們，必從七條路逃跑。地上萬國必因你而驚駭。","notes":[]},{"n":26,"t":"你的屍首必給空中的飛鳥和地上的走獸作食物，卻無人鬨趕。","notes":[]},{"n":27,"t":"耶和華必用埃及人的瘡、潰瘍、癬和疥攻擊你，使你不得醫治。","notes":[]},{"n":28,"t":"耶和華必用癲狂、眼瞎、心驚攻擊你。","notes":[]},{"n":29,"t":"你必在午間摸索，好像盲人在黑暗中摸索。你的道路必不亨通，天天受人欺壓、搶奪，無人搭救。","notes":[]},{"n":30,"t":"你聘了妻子，別人必與她同寢；你建了房屋，卻不得住在其內；你栽植了葡萄園，卻不得享用所結的果子。","notes":[]},{"n":31,"t":"你的牛在你眼前宰了，你吃不到牠的肉；你的驢在你眼前被人搶奪，卻討不回來；你的羊被敵人拿走，無人幫助你。","notes":[]},{"n":32,"t":"你的兒女被交給別國的民；你的眼目終日切望，甚至失明，你的手卻無能為力。","notes":[]},{"n":33,"t":"你地所產的和你勞力所得的，必被你所不認識的百姓吃盡。你天天只被欺負，受壓制，","notes":[]},{"n":34,"t":"甚至你因眼中所見的景象而瘋狂。","notes":[]},{"n":35,"t":"耶和華必攻擊你，使你膝上腿上，從腳掌到頭頂，都長滿了毒瘡，無法醫治。","notes":[]},{"n":36,"t":"「耶和華必將你和你所立統治你的王，領到你和你列祖不認識的國去；在那裏你必事奉別神，就是木頭和石頭。","notes":[]},{"n":37,"t":"你在耶和華趕你到的萬民中，要令人驚駭，成為笑柄，被人譏誚。","notes":[]},{"n":38,"t":"你撒在田裏的種子雖多，收的卻少，因為蝗蟲把它吃光了。","notes":[]},{"n":39,"t":"你栽植修整葡萄園，卻沒有酒喝，也不得儲存，因為蟲子把它吃了。","notes":[]},{"n":40,"t":"你全境有橄欖樹，卻得不到油抹身，因為你的橄欖都掉光了。","notes":[]},{"n":41,"t":"你生兒育女，卻不屬於你，因為他們必被擄去。","notes":[]},{"n":42,"t":"你所有的樹木和你地裏的出產必被蝗蟲吃盡了。","notes":[]},{"n":43,"t":"在你中間寄居的必上升高過你，高而又高；你必下降，低而又低。","notes":[]},{"n":44,"t":"他必借給你，你卻不能借給他；他必作首，你必作尾。","notes":[]},{"n":45,"t":"這一切的詛咒必臨到你，追趕你，趕上你，直到把你除滅，因為你不聽從耶和華－你神的話，不遵守他吩咐的誡命律例。","notes":[]},{"n":46,"t":"這些詛咒必在你和你後裔身上成為神蹟奇事，直到永遠！","notes":[]},{"n":47,"t":"因為你富裕的時候，不以歡喜快樂的心事奉耶和華－你的神，","notes":[]},{"n":48,"t":"所以你必在飢餓、乾渴、赤身、缺乏中事奉仇敵，那是耶和華派來攻擊你的。他必把鐵軛加在你的頸項上，直到把你除滅。","notes":[]},{"n":49,"t":"耶和華要從遠方、地極之處帶一國來，如鷹飛來攻擊你；這國的語言，你聽不懂。","notes":[]},{"n":50,"t":"這國的人面貌兇惡，不給長者面子，也不恩待年輕人。","notes":[]},{"n":51,"t":"他們必吃你牲畜所生的和你土地所產的，直到你被除滅。你的五穀、新酒和新的油，以及牛犢、羔羊，他都不給你留下，直到使你滅亡。","notes":[]},{"n":52,"t":"他們必在你的各城圍困你，直到你在全地所倚靠、高大堅固的城牆都倒塌。他們必在耶和華－你神所賜給你全地的各城圍困你。","notes":[]},{"n":53,"t":"你在仇敵圍困的窘迫中，必吃你本身所生的，就是耶和華－你神所賜給你的兒女之肉。","notes":[]},{"n":54,"t":"你中間，連那溫和文雅的人都必冷眼惡待自己的兄弟和懷中的妻子，以及他所剩下其餘的兒女，","notes":[]},{"n":55,"t":"不把所吃兒女的肉分一點給他們任何一個人，因為在被仇敵圍困、陷入窘迫的各城中，他已經一無所剩了。","notes":[]},{"n":56,"t":"你中間柔順嬌嫩的婦人，甚至因柔順嬌嫩腳不肯踏地的婦人，也必冷眼惡待她懷中的丈夫和自己的兒女。","notes":[]},{"n":57,"t":"在被仇敵圍困、陷入窘迫的城鎮中，她因缺乏一切，就要暗中把從她兩腿中間出來的胞衣和所生下的兒女吃了。","notes":[]},{"n":58,"t":"「這書上所寫律法的一切話，是叫你敬畏耶和華－你神尊榮可畏的名，你若不謹守遵行，","notes":[]},{"n":59,"t":"耶和華就必將奇異的災害，就是嚴重持久的災害和長期難治的疾病，加在你和你後裔的身上。","notes":[]},{"n":60,"t":"他必使你所畏懼、埃及一切的疾病臨到你，緊貼著你，","notes":[]},{"n":61,"t":"沒有寫在這律法書上的各樣疾病、災害，耶和華也必降在你身上，直到你被除滅。","notes":[]},{"n":62,"t":"你們雖然曾像天上的星那樣多，卻因不聽從耶和華－你神的話，所剩的人丁就稀少了。","notes":[]},{"n":63,"t":"耶和華先前怎樣喜愛善待你們，使你們增多，耶和華也要照樣喜愛消滅你們，使你們滅絕。你們必從所要進去得為業的地上被拔除。","notes":[]},{"n":64,"t":"耶和華必把你們分散在萬民中，從地的這邊到地的另一邊，在那裏你必事奉你和你列祖不認識的神明，就是木頭和石頭。","notes":[]},{"n":65,"t":"在那些國中，你必得不到安寧，腳掌也沒有安歇之處；耶和華卻要使你在那裏心中發顫，眼目失明，精神沮喪。","notes":[]},{"n":66,"t":"你的一生懸空不安；你晝夜恐懼，生命沒有保障。","notes":[]},{"n":67,"t":"你因心中的恐懼，眼睛所見的景象，早晨必說：『但願現在是晚上！』晚上必說：『但願現在是早晨！』","notes":[]},{"n":68,"t":"耶和華要用船把你送回埃及去，走那我曾告訴你不再看見的路；在那裏你們必賣身給你的仇敵作奴婢，卻沒有人要買。」","notes":[]}]},"29":{"heading":"在摩押重新立約","verses":[{"n":1,"t":"耶和華在何烈山與以色列人立約以外，這是耶和華在摩押地吩咐摩西與以色列人立約的話。","notes":[]},{"n":2,"t":"摩西召全以色列來，對他們說：「耶和華在埃及地，在你們眼前向法老和他眾臣僕，以及他的全地所做的一切事，你們都看見了，","notes":[]},{"n":3,"t":"就是你親眼看見的大考驗，那些神蹟和大奇事。","notes":[]},{"n":4,"t":"但耶和華到今日還沒有使你們心能明白，眼能看見，耳能聽見。","notes":[]},{"n":5,"t":"我領你們在曠野四十年，你們身上的衣服沒有穿破，腳上的鞋也沒有穿壞；","notes":[]},{"n":6,"t":"你們沒有吃餅，也沒有喝清酒烈酒，好讓你們知道『我─耶和華是你們的神』。","notes":[]},{"n":7,"t":"你們來到這地方，希實本王西宏和巴珊王噩出來迎擊我們，與我們交戰，我們擊敗了他們，","notes":[]},{"n":8,"t":"取了他們的地，給呂便支派、迦得支派和瑪拿西半支派為業。","notes":[]},{"n":9,"t":"所以你們要謹守這約的話，遵行它們，好使你們在一切所做的事上亨通。","notes":[]},{"n":10,"t":"「今日你們全都要站在耶和華－你們的神面前，就是各領袖、族長、長老、官長、以色列所有的男子、","notes":["「族長」：原文是「支派」。"]},{"n":11,"t":"你們的妻子兒女、你營中寄居的，從為你砍柴到為你挑水的人，","notes":[]},{"n":12,"t":"為要使你進入耶和華－你神的約，就是耶和華－你神今日向你起誓所立的；","notes":[]},{"n":13,"t":"這樣，他今日要立你作他的子民，他作你的神，是照他向你所應許的，又照他向你列祖亞伯拉罕、以撒、雅各所起的誓。","notes":[]},{"n":14,"t":"我不單單與你們立這約，起這誓，","notes":[]},{"n":15,"t":"就是今日與我們一同站在耶和華－我們神面前的，而且也包括今日不在我們這裏的人。","notes":[]},{"n":16,"t":"「你們知道，我們曾住過埃及地，也經過列國，從他們中間穿越。","notes":[]},{"n":17,"t":"你們也見過他們的可憎之物，他們木、石、金、銀的偶像。","notes":[]},{"n":18,"t":"惟恐你們中間有人，或男或女，或宗族或支派，今日心裏偏離耶和華－我們的神，去事奉那些國的神明，又怕你們中間有根長出苦菜和茵蔯來。","notes":[]},{"n":19,"t":"這樣的人聽見這詛咒的話，心裏還慶幸，說：『我雖然隨著頑固的心行事，卻還是平安無事。』以致有水的和無水的都消滅了。","notes":[]},{"n":20,"t":"耶和華必不願饒恕他；耶和華的怒氣與妒忌必向他如煙冒出，將這書上所寫的一切詛咒都加在他身上，耶和華也要從天下塗去他的名。","notes":[]},{"n":21,"t":"耶和華又必照著寫在律法書上，約中的一切詛咒，將他從以色列眾支派中分別出來，使他遭受禍害。","notes":[]},{"n":22,"t":"你們的後代，就是接續你們興起的子孫，和遠方來的外邦人，看見這地的災禍，以及耶和華所降於這地的疾病，","notes":[]},{"n":23,"t":"遍地都被硫磺和鹽所侵蝕，不能耕種，沒有出產，連草都長不出來，好像耶和華在怒氣和憤怒中所傾覆的所多瑪、蛾摩拉、押瑪、洗扁一樣，","notes":[]},{"n":24,"t":"萬國必說：『耶和華為甚麼向此地這樣做呢？為甚麼要大發烈怒呢？』","notes":[]},{"n":25,"t":"人必說：『這是因為這地的人離棄了耶和華─他們列祖的神領他們出埃及地的時候與他們所立的約，","notes":[]},{"n":26,"t":"去事奉別神，敬拜他們所不認識的神明，這是耶和華未曾允許的。","notes":[]},{"n":27,"t":"所以耶和華的怒氣向這地發作，將這書上所寫的一切詛咒都降在這地上。","notes":[]},{"n":28,"t":"耶和華在怒氣、憤怒、大惱恨中將他們從本地拔出來，扔到別的地上，像今日一樣。』","notes":[]},{"n":29,"t":"「隱祕的事是屬耶和華─我們神的，但明顯的事是永遠屬我們和我們子孫的，為要叫我們遵行這律法上的一切話。」","notes":[]}]},"30":{"heading":"回轉和蒙福","verses":[{"n":1,"t":"「當這一切的事，就是我擺在你面前的祝福和詛咒臨到你的時候，你在耶和華－你神趕逐你去的萬國中，心裏回想這些事，","notes":[]},{"n":2,"t":"你和你的子孫若盡心盡性歸向耶和華－你的神，照我今日一切所吩咐你的，聽從他的話，","notes":[]},{"n":3,"t":"耶和華－你的神就必憐憫你，使你這被擄的子民歸回。耶和華－你的神必轉回，從分散你到的萬民中把你召集回來。","notes":[]},{"n":4,"t":"你就是被趕逐到天涯，耶和華－你的神也必從那裏召集你，從那裏領你回來。","notes":[]},{"n":5,"t":"耶和華－你的神必領你進入你列祖所得的地，你必得著這地為業。他必善待你，使你增多，勝過你的列祖。","notes":[]},{"n":6,"t":"耶和華－你的神要使你的心和你後裔的心受割禮，好叫你盡心盡性愛耶和華－你的神，使你可以存活。","notes":[]},{"n":7,"t":"耶和華－你的神必將這一切詛咒加在你仇敵和恨惡你、迫害你的人身上。","notes":[]},{"n":8,"t":"你必回轉，聽從耶和華的話，遵行他的一切誡命，就是我今日所吩咐你的。","notes":[]},{"n":9,"t":"耶和華－你的神必使你手裏所做的一切，以及你身所生的，牲畜所生的，土地所產的都豐富有餘，而且順利；耶和華必再喜愛善待你，正如他喜愛你的列祖一樣，","notes":[]},{"n":10,"t":"只要你聽從耶和華－你神的話，謹守這律法書上所寫的誡命律例，盡心盡性歸向耶和華－你的神。」","notes":[]},{"n":11,"t":"「我今日所吩咐你的誡命，對你並不困難，也不太遠；","notes":[],"heads":["生命之道"]},{"n":12,"t":"不是在天上，使你說：『誰為我們上天去取來給我們，使我們聽了可以遵行呢？』","notes":[]},{"n":13,"t":"也不是在海的那邊，使你說：『誰為我們渡海到另一邊，去取來給我們，使我們聽了可以遵行呢？』","notes":[]},{"n":14,"t":"因這話離你很近，就在你口中，在你心裏，使你可以遵行。","notes":[]},{"n":15,"t":"「看，我今日將生死禍福擺在你面前。","notes":[]},{"n":16,"t":"我今日所吩咐你的，就是要愛耶和華－你的神，遵行他的道，謹守他的誡命、律例、典章，使你可以存活，增多，而且耶和華－你的神必在你所要進去得為業的地上賜福給你。","notes":["「我今日所吩咐你的」：七十士譯本是「如果你遵行主－你神的誡命，就是我今日所吩咐你的」。"]},{"n":17,"t":"倘若你的心偏離，不肯聽從，卻被引誘去敬拜別神，事奉它們，","notes":[]},{"n":18,"t":"我今日向你們申明，你們必定滅亡；在你過約旦河進去得為業的地上，你的日子必不長久。","notes":[]},{"n":19,"t":"我今日呼天喚地向你作見證：我已經將生與死，祝福與詛咒，擺在你面前。所以你要揀選生命，好使你和你的後裔都得存活。","notes":[]},{"n":20,"t":"要愛耶和華－你的神，聽從他的話，緊緊跟隨他，因為他是你的生命，必使你的日子得以長久，可以在耶和華向你列祖亞伯拉罕、以撒、雅各起誓要給他們的地上居住。」","notes":[]}]},"31":{"heading":"約書亞繼承摩西","verses":[{"n":1,"t":"摩西去把這些話吩咐以色列眾人，","notes":["「去...眾人」：死海古卷和七十士譯本是「對以色列眾人說完了這一切話」。"]},{"n":2,"t":"對他們說：「我已經一百二十歲了，現在不能照常出入。耶和華曾對我說：『你不得過這約旦河。』","notes":[]},{"n":3,"t":"耶和華－你的神必在你面前過河，把這些國從你面前除滅，你就必得他們的地。約書亞要在你面前過河，是照耶和華所吩咐的。","notes":[]},{"n":4,"t":"耶和華必對待他們，如同從前待他所除滅的亞摩利人的王西宏與噩，以及他們的國一樣。","notes":[]},{"n":5,"t":"耶和華必將他們交在你們面前，你們要照我所吩咐的一切命令待他們。","notes":[]},{"n":6,"t":"你們當剛強壯膽，不要害怕，也不要畏懼他們，因為耶和華－你的神必與你同去；他必不撇下你，也不丟棄你。」","notes":[]},{"n":7,"t":"摩西召了約書亞來，在以色列眾人眼前對他說：「你當剛強壯膽！因為你要和這百姓一同進入耶和華向他們列祖起誓要給他們的地，你也要使他們承受那地為業。","notes":["「和這百姓一同進入」：撒瑪利亞五經和一些古卷是「領這百姓進入」。"]},{"n":8,"t":"耶和華必在你前面行，他必親自與你同在，必不撇下你，也不丟棄你。你不要懼怕，也不要驚惶。」","notes":[]},{"n":9,"t":"摩西寫下這律法，交給抬耶和華約櫃的利未人祭司和以色列的眾長老。","notes":[],"heads":["每七年要誦讀律法一次"]},{"n":10,"t":"摩西吩咐他們說：「每逢七年的最後一年，就是定期的豁免年，在住棚節的時候，","notes":[]},{"n":11,"t":"當以色列眾人來到耶和華－你神所選擇的地方朝見他的時候，你要在以色列眾人面前念這律法給他們聽。","notes":[]},{"n":12,"t":"要召集百姓，男人、女人、孩子，和在你城裏寄居的，叫他們都得以聽見，好學習敬畏耶和華－你們的神，謹守遵行這律法的一切話。","notes":[]},{"n":13,"t":"他們的兒女，就是那未曾認識的，也可以聽，學習敬畏耶和華－你們的神；你們一生的日子，在你們過約旦河得為業的地上，都要這樣做。」","notes":[]},{"n":14,"t":"耶和華對摩西說：「看哪，你的死期已近了。要召約書亞來，和你一起站在會幕裏，我好吩咐他。」於是摩西和約書亞去站在會幕裏。","notes":[],"heads":["對摩西最後的指示"]},{"n":15,"t":"耶和華在會幕裏，在雲柱中顯現，雲柱停在會幕門口的上面。","notes":[]},{"n":16,"t":"耶和華對摩西說：「看哪，你必和你的祖先同睡。這百姓要起來，在他們所要去的地上，在那地的人中，隨從外邦的神明行淫，離棄我，違背我與他們所立的約。","notes":[]},{"n":17,"t":"那時，我的怒氣必向他們發作，我必離棄他們，轉臉不顧他們，以致他們被吞滅，並有許多的禍患災難臨到他們。在那日，人必說：『這些禍患臨到我，豈不是因為我的神不在我中間嗎？』","notes":[]},{"n":18,"t":"在那日，因人偏向別神所行的一切惡事，我必定轉臉不顧。","notes":[]},{"n":19,"t":"現在你們要寫下這首歌，教導以色列人，放在他們口中，使這首歌成為我指責以色列人的見證。","notes":[]},{"n":20,"t":"因為我將他們領進我向他們列祖起誓應許那流奶與蜜之地，他們在那裏吃得飽足，長得肥胖，就偏向別神，事奉它們，藐視我，背棄我的約。","notes":[]},{"n":21,"t":"當許多禍患災難臨到他們的時候，這首歌必在他們面前作見證，因為他們後裔的口必吟誦不忘。我未領他們到我所起誓應許之地以先，他們所懷的意念我都知道了。」","notes":[]},{"n":22,"t":"當日摩西就寫了一首歌，教導以色列人。","notes":[]},{"n":23,"t":"耶和華吩咐嫩的兒子約書亞說：「你當剛強壯膽，因為你必領以色列人進入我所起誓應許他們的地，我必與你同在。」","notes":[]},{"n":24,"t":"當摩西把這律法的話寫完在書上，到完成的時候，","notes":[]},{"n":25,"t":"摩西吩咐抬耶和華約櫃的利未人說：","notes":[]},{"n":26,"t":"「把這律法書拿來，放在耶和華－你們神的約櫃旁，可以在那裏作指責你們的見證。","notes":[]},{"n":27,"t":"因為我知道你們是悖逆的，是硬著頸項的。看哪，我今日還活著與你們同在，你們尚且悖逆耶和華，何況我死後呢？","notes":[]},{"n":28,"t":"你們要召集你們支派的眾長老和官長到我這裏來，我好把這些話說給他們聽，並且呼喚天地見證他們的不是。","notes":[]},{"n":29,"t":"我知道我死後你們必全然敗壞，偏離我所吩咐你們的道。日後必有禍患臨到你們，因為你們做了耶和華眼中看為惡的事，以你們手中所做的惹他發怒。」","notes":[]},{"n":30,"t":"摩西把這首歌的話，從頭到尾吟誦給以色列全會眾聽。","notes":[],"heads":["摩西之歌"]}]},"32":{"heading":"預告摩西的死","verses":[{"n":1,"t":"「諸天哪，要側耳聽我說話；願地聆聽我口中的言語。","notes":[]},{"n":2,"t":"我的教導要淋漓如雨，我的言語要滴落如露，如細雨降在嫩草上，如甘霖降在蔬菜中。","notes":[]},{"n":3,"t":"因為我要宣揚耶和華的名，你們要把偉大歸給我們的神。","notes":[]},{"n":4,"t":"「他是磐石，他的作為完全，他一切所行的都公平；他是信實無偽的神，又公義，又正直。","notes":[]},{"n":5,"t":"這乖僻彎曲的世代向他行了敗壞的事；因著他們的弊病，不再是他的兒女。","notes":[]},{"n":6,"t":"愚昧無知的百姓啊，你們這樣報答耶和華嗎？他豈不是你的父，創造了你嗎？他造了你，堅立你。","notes":[]},{"n":7,"t":"你當回想上古之日，思念歷代之年；問你的父親，他必告訴你；問你的長者，他必向你述說。","notes":[]},{"n":8,"t":"至高者將地業賜給列國，將世人分開，他按照神明的數目，為萬民劃定疆界。","notes":["「神明」是根據死海古卷，直譯「神的眾子」；原文是「以色列人」；七十士譯本是「天使」。"]},{"n":9,"t":"因為耶和華的份是他的百姓，他的產業就是雅各。","notes":[]},{"n":10,"t":"「耶和華在曠野之地，在空曠，野獸吼叫之荒地遇見他，就環繞他，看顧他，保護他，如同保護眼中的瞳人。","notes":[]},{"n":11,"t":"鷹怎樣攪動巢窩，在雛鷹上面飛翔，展開雙翅接住雛鷹，背在兩翼之上，","notes":[]},{"n":12,"t":"耶和華也照樣獨自引導他，並無外邦神明與他同在。","notes":[]},{"n":13,"t":"耶和華使他馳騁在地的高處，他吃田間的出產；耶和華使他從巖石中吃蜜，從堅石中吸油，","notes":[]},{"n":14,"t":"也吃牛的乳酪、羊的奶、羔羊的脂肪，巴珊所出的公綿羊和山羊，和上好的麥子。你要喝葡萄汁釀的美酒。","notes":[]},{"n":15,"t":"「耶書崙漸漸肥胖，能踢跳。你長得肥胖，粗壯，豐潤。他離棄造他的神，輕看救他的磐石。","notes":["死海古卷、撒瑪利亞五經、其他古卷和七十士譯本在此加：「雅各吃了而且飽足」。"]},{"n":16,"t":"他們用外邦神明惹神妒忌，以可憎之物惹他發怒。","notes":[]},{"n":17,"t":"他們祭祀鬼魔，而非神，是他們不認識的神明，是近來新興的，是你們列祖所不畏懼的。","notes":[]},{"n":18,"t":"你輕忽生你的磐石，忘記生產你的神。","notes":[]},{"n":19,"t":"「耶和華看見了，因他兒女惹動他就拋棄他們，","notes":[]},{"n":20,"t":"說：『我要轉臉離開他們，看他們的結局如何。他們是極乖謬的世代，是不忠實的兒女。","notes":[]},{"n":21,"t":"他們以那不是神的激起我妒忌，以虛無的神明惹我發怒。我要以不成國的激起你們嫉妒，我要以愚頑的國惹起你們發怒。","notes":["「虛無的神明」：原文是「虛無」。"]},{"n":22,"t":"因為我的怒火焚燒，直燒到極深的陰間，吞噬地和地的出產，連山的根基也燒著了。","notes":[]},{"n":23,"t":"「『我要把禍患堆在他們身上，我用盡我的箭射向他們：","notes":[]},{"n":24,"t":"餓死人的饑荒、灼人的熱症、痛苦的災害。我要叫野獸用牙齒咬他們，叫土中爬行的用毒液害他們。","notes":[]},{"n":25,"t":"外有刀劍使人喪亡，內有驚恐，少男少女是如此，吃奶的、白髮的也是如此。","notes":[]},{"n":26,"t":"我曾說，我要粉碎他們，使他們的名從人間消失。","notes":["「名」：原文是「紀念」。"]},{"n":27,"t":"惟恐仇敵挑釁，他們的敵人誤解，說，我們的手得勝了，這一切並非耶和華做的。』","notes":[]},{"n":28,"t":"「因為他們是缺乏智謀的國家，他們裏面毫無聰明。","notes":[]},{"n":29,"t":"惟願他們有智慧，能明白這事，他們就會想到自己的結局。","notes":[]},{"n":30,"t":"若非他們的磐石賣了他們，若非耶和華交出他們，一人豈能追趕千人，二人焉能使萬人逃跑呢？","notes":[]},{"n":31,"t":"甚至我們的仇敵都承認，他們的磐石不如我們的磐石。","notes":[]},{"n":32,"t":"他們的葡萄樹是所多瑪的葡萄樹，是蛾摩拉田園所長的；他們的葡萄是毒葡萄，整串都是苦的。","notes":[]},{"n":33,"t":"他們的酒是大蛇的毒液，是毒蛇劇烈的毒汁。","notes":[]},{"n":34,"t":"「這豈不都存放在我這裏，封存在我庫房中嗎？","notes":[]},{"n":35,"t":"伸冤報應在我，到了時候他們會失腳。因為他們遭難的日子近了，他們的厄運快要臨到。","notes":["「伸冤報應在我」：撒瑪利亞五經和七十士譯本是「伸冤的日子我必報應」。"]},{"n":36,"t":"耶和華見他的百姓毫無能力，無論是為奴的、自由的，都沒有存留，就必為他們伸冤，為自己的僕人發憐憫。","notes":[]},{"n":37,"t":"他必說：『他們的神明，他們所投靠的磐石，在哪裏呢？","notes":[]},{"n":38,"t":"吃了他們祭牲脂肪的，喝了他們澆酒祭之酒的，叫那些神明站出來幫助你們，作為你們的保障吧！","notes":[]},{"n":39,"t":"「『如今，看！我，惟有我是神；我以外並無別神。我使人死，我使人活；我擊傷人，也醫治人，沒有人能從我手中救出來。","notes":["「神」：原文直譯「他」。"]},{"n":40,"t":"我向天舉手，我憑我的永生起誓說：","notes":[]},{"n":41,"t":"我若磨我閃亮的刀，我的手掌握審判權，就必報復我的敵人，報應那些恨我的人。","notes":[]},{"n":42,"t":"我要使我的箭飲血而醉，就是被殺被擄之人的血；我的刀也要吃肉，就是仇敵披髮頭顱的肉。』","notes":["「頭顱」或譯「領袖」。"]},{"n":43,"t":"「列國啊，當與耶和華的子民一同歡呼；因為他要為他僕人所流的血伸冤，報應他的敵人，救贖他的土地和他的子民 。」","notes":["「列國...歡呼」：死海古卷是「諸天啊，當與他一同歡樂；神的眾子都要拜他」；七十士譯本是「諸天啊，當與他一同歡樂；神的眾子都要拜他；外邦人哪，你們要與他的子民一同歡樂；神的眾天使都加添力量給他」。","「他僕人」：死海古卷和七十士譯本是「他兒女」。","「報應他的敵人」：死海古卷和七十士譯本是「報應他的敵人，報應那些恨他的人」。","「他的土地和他的子民」：死海古卷、撒瑪利亞五經和七十士譯本是「他百姓的土地」。"]},{"n":44,"t":"摩西和嫩的兒子約書亞前來把這首歌的一切話吟誦給百姓聽。","notes":["「約書亞」是根據撒瑪利亞五經、七十士譯本和其他古譯本；原文是「何西阿」。"]},{"n":45,"t":"摩西向以色列眾人吟誦完了這一切話，","notes":[]},{"n":46,"t":"對他們說：「我今日以這一切話警戒你們，你們都要記在心中，要吩咐你們的子孫謹守遵行這律法上一切的話。","notes":[]},{"n":47,"t":"因為這不是與你們無關的空話，而是你們的生命；因遵行這話，你們的日子必在你們過約旦河得為業的地上得以長久。」","notes":[]},{"n":48,"t":"就在那日，耶和華吩咐摩西說：","notes":[]},{"n":49,"t":"「你上摩押地的亞巴琳山脈，到面對耶利哥的尼波山去，看我所要賜給以色列人為業的迦南地。","notes":[]},{"n":50,"t":"你必死在你所登的山上，歸到你祖先那裏，像你哥哥亞倫死在何珥山上，歸到他祖先那裏一樣。","notes":["「你祖先」：原文是「你百姓」。","「他祖先」：原文是「他百姓」。"]},{"n":51,"t":"因為你們在以色列人中得罪了我，在尋的曠野，加低斯的米利巴水那裏，在以色列人中沒有尊我為聖。","notes":[]},{"n":52,"t":"我所賜給以色列人的地，你只可從對面觀看，卻不得進到那裏去。」","notes":[]}]},"33":{"heading":"摩西祝福以色列眾支派","verses":[{"n":1,"t":"這是神人摩西未死以前為以色列人的祝福。","notes":[]},{"n":2,"t":"他說：「耶和華從西奈來，從西珥向他們顯現，從巴蘭山發出光輝；從萬萬聖者中來臨，從他右手向他們發出烈火的律法。","notes":["「從萬萬聖者中來臨」：撒瑪利亞五經、七十士譯本和其他古譯本是「有萬萬聖者在一起」。","「從...律法」或譯「從他右手有烈火照耀他們」。"]},{"n":3,"t":"他實在疼愛萬民。他的眾聖徒都在你手中，他們坐在你的腳下，領受你的言語。」","notes":[]},{"n":4,"t":"摩西將律法傳給我們，作為雅各會眾的產業。","notes":[]},{"n":5,"t":"「耶和華在耶書崙作王；百姓的眾領袖和以色列各支派一同歡聚。","notes":["「耶和華」：原文是「他」。"]},{"n":6,"t":"願呂便存活，不致死亡，雖然他的人丁稀少。","notes":[]},{"n":7,"t":"關於猶大，他這麼說：『耶和華啊，求你垂聽猶大的聲音，引導他歸回他的百姓中。他曾用手為自己爭戰，你必幫助他攻擊敵人。』","notes":[]},{"n":8,"t":"關於利未，他說：『願你的土明和烏陵都在你的虔誠人那裏。你在瑪撒曾考驗他，在米利巴水與他爭論。","notes":["「願你的...那裏」：死海古卷和七十士譯本是「願你的土明給利未人，你的烏陵給虔誠人」。"]},{"n":9,"t":"關於自己的父母，他說：我未曾關注。他的弟兄，他不承認，他的兒女，他也不認識，因為利未人遵行你的話，謹守你的約。","notes":[]},{"n":10,"t":"他們將你的典章教導雅各，將你的律法教導以色列。他們奉上香讓你聞，把全牲的燔祭獻在你壇上。","notes":[]},{"n":11,"t":"求耶和華賜福給他的財物，悅納他手裏的工作。求你刺透起來攻擊他的人的腰，使那些恨惡他的人不再起來。』","notes":["「財物」或譯「力量」。"]},{"n":12,"t":"關於便雅憫，他說：『耶和華所親愛的必同耶和華安然居住，耶和華終日庇護他，他也住在耶和華兩肩之中。』","notes":["「他也住在...之中」或譯「耶和華也住在他的兩座山之間」。"]},{"n":13,"t":"關於約瑟，他說：『願他的地蒙耶和華賜福，得天上的甘露，地下的泉源；","notes":[]},{"n":14,"t":"得太陽下的美果，月光中的佳穀；","notes":[]},{"n":15,"t":"得古老山嶽的至寶，永恆山嶺的寶物；","notes":[]},{"n":16,"t":"得地的寶物和其中所充滿的，得住在荊棘中者的喜悅。願這些福都臨到約瑟的頭上，臨到那與兄弟有分別之人的頭頂上。","notes":[]},{"n":17,"t":"他是牛群中頭生的，大有威嚴；他的雙角是野牛的角，用以牴觸萬民，直到地極。這對角是以法蓮的萬萬，這對角是瑪拿西的千千。』","notes":[]},{"n":18,"t":"關於西布倫，他說：『西布倫哪，你出外可以歡喜。以薩迦啊，你在帳棚裏可以快樂。","notes":[]},{"n":19,"t":"他們要召集萬民到山上，在那裏獻公義的祭。因為他們要吸取海裏的財富，沙中隱藏的珍寶。』","notes":[]},{"n":20,"t":"關於迦得，他說：『那使迦得擴張的，當受稱頌！迦得臥如母獅，撕裂膀臂和頭皮。","notes":[]},{"n":21,"t":"他為自己看中了最好的，因為那是為掌權者所存留的一份。他與百姓的領袖同來，執行耶和華的公義和耶和華為以色列所立的典章。』","notes":["「因為...同來」：原文另譯「因為那是掌權者的份，他與百姓的領袖一同聚集」。"]},{"n":22,"t":"關於但，他說：『但是小獅子，從巴珊跳出來。』","notes":[]},{"n":23,"t":"關於拿弗他利，他說：『拿弗他利啊，你享足恩寵，滿得耶和華的福，可以得西方和南方為業。』","notes":[]},{"n":24,"t":"關於亞設，他說：『願亞設在眾子中蒙福，願他得他弟兄的喜悅，可以把腳蘸在油中。","notes":["「願亞設在眾子中蒙福」或譯「眾子中最蒙福的是亞設」。"]},{"n":25,"t":"你的門閂是鐵的，是銅的。只要你有多少日子，你就有多少力量。』","notes":["「只要...力量」或譯「你的日子如何，你的力量也必如何」。"]},{"n":26,"t":"「耶書崙哪，沒有誰能比神！他騰雲，大顯威榮，從天空來幫助你。","notes":[]},{"n":27,"t":"亙古的神是避難所，下面有永久的膀臂。他從你面前趕走仇敵，說：『毀滅吧！』","notes":[]},{"n":28,"t":"因此，以色列獨自安然居住，雅各的泉源在五穀新酒之地，他的天也滴下露水。","notes":[]},{"n":29,"t":"以色列啊，你有福了！蒙耶和華拯救的百姓啊，誰能像你？他是幫助你的盾牌，是你威榮的刀劍。你的仇敵要屈身就你；你卻要踐踏他們的背脊。」","notes":["「背脊」或譯「高處」。"]}]},"34":{"heading":"摩西的死","verses":[{"n":1,"t":"摩西從摩押平原登上尼波山，到了耶利哥對面的毗斯迦山頂。耶和華把全地指給他看：從基列到但，","notes":[]},{"n":2,"t":"拿弗他利全地，以法蓮、瑪拿西的地，猶大全地直到西邊的海，","notes":[]},{"n":3,"t":"尼革夫，從棕樹城耶利哥的平原到瑣珥。","notes":[]},{"n":4,"t":"耶和華對他說：「這就是我向亞伯拉罕、以撒、雅各起誓應許之地，說：『我必將這地賜給你的後裔。』現在我使你親眼看見了，你卻不得過到那裏去。」","notes":[]},{"n":5,"t":"於是耶和華的僕人摩西死在摩押地那裏，正如耶和華所說的。","notes":[]},{"n":6,"t":"耶和華將他葬在摩押地，伯‧毗珥對面的谷中，只是到今日，沒有人知道他的墳墓。","notes":[]},{"n":7,"t":"摩西死的時候一百二十歲，眼目沒有昏花，力量沒有衰退。","notes":[]},{"n":8,"t":"以色列人在摩押平原為摩西哀哭了三十天，為摩西哀哭居喪的日期才結束。","notes":[]},{"n":9,"t":"嫩的兒子約書亞，因為摩西曾為他按手，他就被智慧的靈充滿。以色列人聽從他，照著耶和華所吩咐摩西的去做。","notes":[]},{"n":10,"t":"以後，以色列中再沒有興起一位先知像摩西的，他是耶和華面對面所認識的。","notes":[]},{"n":11,"t":"耶和華差派他在埃及地，向法老和他的一切臣僕，以及他的全地，行了各樣神蹟奇事，","notes":[]},{"n":12,"t":"又在以色列眾人眼前顯出大能的手，行了一切大而可畏的事。","notes":[]}]}},"JOS":{"1":{"heading":"神命令約書亞征服迦南","verses":[{"n":1,"t":"耶和華的僕人摩西死了以後，耶和華對摩西的助手嫩的兒子約書亞說：","notes":[]},{"n":2,"t":"「我的僕人摩西死了。現在你要起來，和眾百姓過這約旦河，往我所要賜給以色列人的地去。","notes":[]},{"n":3,"t":"凡你們腳掌所踏之地，我都照我所應許摩西的話賜給你們了。","notes":[]},{"n":4,"t":"從曠野和這黎巴嫩，直到大河，就是幼發拉底河，赫人的全地，又到大海日落的方向，都要作你們的疆土。","notes":[]},{"n":5,"t":"你一生的日子，必無人能在你面前站立得住。我怎樣與摩西同在，也必照樣與你同在；我必不撇下你，也不丟棄你。","notes":[]},{"n":6,"t":"你當剛強壯膽，因為你必使這百姓承受那地為業，就是我向他們列祖起誓要給他們的地。","notes":[]},{"n":7,"t":"只要剛強，大大壯膽，謹守遵行我僕人摩西所吩咐你的一切律法，不可偏離左右，使你無論往哪裏去，都可以順利。","notes":[]},{"n":8,"t":"這律法書不可離開你的口，總要晝夜思想，好使你謹守遵行這書上所寫的一切話。如此，你的道路就可以亨通，凡事順利。","notes":["「思想」或譯「默念」。"]},{"n":9,"t":"我豈沒有吩咐你嗎？你當剛強壯膽，不要懼怕，也不要驚惶，因為你無論往哪裏去，耶和華你的神必與你同在。」","notes":[]},{"n":10,"t":"於是，約書亞吩咐百姓的官長說：","notes":[],"heads":["準備過約旦河"]},{"n":11,"t":"「你們要走遍營中，吩咐百姓說：『當預備食物， 因為三日之內你們要過這約旦河，進去得耶和華－你們神賜給你們為業之地。』」","notes":[]},{"n":12,"t":"約書亞對呂便人、迦得人和瑪拿西半支派的人說：","notes":[]},{"n":13,"t":"「你們要記得耶和華的僕人摩西所吩咐你們的話說：『耶和華－你們的神使你們得享安寧，必將這地賜給你們。』","notes":[]},{"n":14,"t":"你們的妻子、孩子和牲畜可以留在約旦河東、摩西所給你們的地。但你們中間所有大能的勇士都要帶著兵器，在你們的弟兄前面過去，你們要幫助他們。","notes":[]},{"n":15,"t":"等到耶和華使你們的弟兄和你們一樣得享平靜，並且得著耶和華－你們神所賜他們為業之地的時候，你們才可以回到你們所得之地，承受為業，就是耶和華的僕人摩西在約旦河東、向日出的方向所給你們的地。」","notes":[]},{"n":16,"t":"他們回答約書亞說：「凡你吩咐我們的，我們都必做；凡你差我們去的地方，我們都必去。","notes":[]},{"n":17,"t":"我們在一切事上怎樣聽從摩西，也必照樣聽從你。惟願耶和華－你的神與你同在，像與摩西同在一樣。","notes":[]},{"n":18,"t":"無論甚麼人違背你的命令，不聽從你所吩咐他的一切話，就必處死。你只要剛強壯膽！」","notes":[]}]},"2":{"heading":"派探子進耶利哥","verses":[{"n":1,"t":"嫩的兒子約書亞從什亭暗中派兩個人作探子，說：「你們去窺探那地和耶利哥。」於是二人去了，來到一個名叫喇合的妓女家裏，在那裏睡覺。","notes":[]},{"n":2,"t":"有人告訴耶利哥王說：「看哪，今夜有以色列人到這裏來窺探此地。」","notes":[]},{"n":3,"t":"耶利哥王派人到喇合那裏， 說：「你要交出那來到你這裏、進了你家的人，因為他們來是要窺探全地。」","notes":[]},{"n":4,"t":"但女人已把二人藏起來，卻說：「那兩個人確實到我這裏來過，他們從哪裏來，我卻不知道。","notes":[]},{"n":5,"t":"天黑、要關城門的時候，他們就出去了。他們往哪裏去我也不知道。你們趕快去追他們，就必追上。」","notes":[]},{"n":6,"t":"其實，這女人已經領二人上了屋頂，把他們藏在她擺列在屋頂的亞麻梗中。","notes":[]},{"n":7,"t":"那些人就往約旦河的路上追趕他們，直到渡口。追趕他們的人一出去，城門就關了。","notes":[]},{"n":8,"t":"二人還沒有睡之前，女人就上屋頂，到他們那裏，","notes":[]},{"n":9,"t":"對他們說：「我知道耶和華已經把這地賜給你們了，並且我們也都懼怕你們。這地所有的居民在你們面前都融化了。","notes":[]},{"n":10,"t":"因為我們聽見你們出埃及的時候，耶和華怎樣在你們前面使紅海的水乾了，並且你們怎樣處置約旦河東的兩個亞摩利王，西宏和噩，把他們完全消滅。","notes":["「紅海」是根據七十士譯本，原文是「蘆葦海」；本卷書下同。"]},{"n":11,"t":"我們一聽見就膽戰心驚，人人因你們的緣故勇氣全失。耶和華－你們的神是天上地下的神。","notes":["「膽戰心驚」：原文是「心消化了」；本卷書下同。"]},{"n":12,"t":"現在我既然恩待你們，求你們指著耶和華向我起誓，你們也要恩待我的父家。請你們給我一個確實的憑據，","notes":[]},{"n":13,"t":"要救活我的父母、兄弟、姊妹，和所有屬他們的，拯救我們的性命脫離死亡。」","notes":[]},{"n":14,"t":"那二人對她說：「我們願意以性命來替你們死。你們若不洩漏我們這件事，當耶和華將這地賜給我們的時候，我們必以慈愛和誠信待你。」","notes":[]},{"n":15,"t":"於是女人用繩子把二人從窗戶縋下去，因為她的屋子是在城牆邊上，她也住在城牆上。","notes":[]},{"n":16,"t":"她對他們說：「你們暫且往山上去，免得追趕的人遇見你們。要在那裏躲藏三天，等追趕的人回來，你們才可以走自己的路。」","notes":[]},{"n":17,"t":"二人對她說：「你叫我們所起的誓與我們無關，","notes":[]},{"n":18,"t":"除非，看哪，當我們來到這地的時候，你把這條朱紅線繩子繫在縋我們下去的窗戶上，並要叫你的父母、兄弟和你父的全家都聚集在你家中。","notes":[]},{"n":19,"t":"凡離開你家門往街上去的，他的血必歸到自己頭上，與我們無關；凡在你家裏的，若有人下手害他，他的血就歸到我們頭上。","notes":[]},{"n":20,"t":"你若洩漏我們這件事，你叫我們所起的誓就與我們無關了。」","notes":["「你叫我們所起的誓」：七十士譯本是「你這個誓言」。"]},{"n":21,"t":"女人說：「就照你們的話吧！」於是她送他們走了，就把朱紅繩子繫在窗戶上。","notes":[]},{"n":22,"t":"二人離開，到山上去，在那裏停留三天，直等到追趕的人回去。追趕的人一路尋找，卻找不著。","notes":[]},{"n":23,"t":"二人回來，下了山，過了河，來到嫩的兒子約書亞那裏，向他報告他們所遭遇的一切事。","notes":[]},{"n":24,"t":"他們對約書亞說：「耶和華果然將那全地交在我們手中了，並且那地所有的居民在我們面前都融化了。」","notes":[]}]},"3":{"heading":"以色列人過約旦河","verses":[{"n":1,"t":"約書亞清早起來，和以色列眾人起行，離開什亭，來到約旦河，過河以前住在那裏。","notes":[]},{"n":2,"t":"過了三天，官長走遍營中，","notes":[]},{"n":3,"t":"吩咐百姓說：「當你們看見利未家的祭司抬著耶和華－你們神的約櫃的時候，你們就要起行離開所住的地方，跟著約櫃走，","notes":[]},{"n":4,"t":"使你們知道所當走的路，因為這條路是你們從來沒有走過的。只是你們要與約櫃相隔約二千肘，不可太靠近約櫃。」","notes":[]},{"n":5,"t":"約書亞吩咐百姓說：「你們要使自己分別為聖，因為明天耶和華必在你們中間行奇事。」","notes":[]},{"n":6,"t":"約書亞對祭司說：「你們抬起約櫃，在百姓的前面過去。」於是他們抬起約櫃，走在百姓前面。","notes":[]},{"n":7,"t":"耶和華對約書亞說：「從今日起，我必使你在以色列眾人眼前被尊為大，使他們知道我怎樣與摩西同在，也必照樣與你同在。","notes":[]},{"n":8,"t":"你要吩咐抬約櫃的祭司說：『你們到了約旦河的水邊，要在約旦河中站著。』」","notes":[]},{"n":9,"t":"約書亞對以色列人說：「你們近前，到這裏來，聽耶和華－你們神的話。」","notes":[]},{"n":10,"t":"約書亞說：「你們因這事會知道永生的神在你們中間，他必從你們面前趕出迦南人、赫人、希未人、比利洗人、革迦撒人、亞摩利人、耶布斯人。","notes":[]},{"n":11,"t":"看哪！全地之主的約櫃必在你們的前面過去，到約旦河裏。","notes":[]},{"n":12,"t":"現在， 你們要從以色列支派中選出十二個人，每支派一人。","notes":[]},{"n":13,"t":"當抬耶和華全地之主約櫃的祭司，腳掌踏入約旦河水裏的時候，約旦河的水，就是從上往下流的水，必然中斷，豎立成壘。」","notes":[]},{"n":14,"t":"百姓起行離開帳棚過約旦河的時候，抬約櫃的祭司在百姓的前面。","notes":[]},{"n":15,"t":"那時正是收割的日子，約旦河的水漲滿兩岸。抬約櫃的人到了約旦河，抬約櫃的祭司腳一入水邊，","notes":[]},{"n":16,"t":"那從上往下流的水就在很遠的地方，在撒拉但旁邊的亞當城那裏停住，豎立成壘；那往亞拉巴海，就是鹽海下流的水全然中斷。於是，百姓在耶利哥的對面過了河。","notes":[]},{"n":17,"t":"抬耶和華約櫃的祭司在約旦河中的乾地上穩穩站著，以色列眾人都從乾地上過去，直到全國都過了約旦河。","notes":[]}]},"4":{"heading":"立石為記","verses":[{"n":1,"t":"當全民都過了約旦河，耶和華對約書亞說：","notes":[]},{"n":2,"t":"「你要從百姓中選出十二個人，每支派一人，","notes":[]},{"n":3,"t":"吩咐他們說：『你們從這裏，從約旦河中祭司的腳穩穩站立的地方，取十二塊石頭，一起帶過去，放在你們今夜住宿的地方。』」","notes":["「從約旦河中...石頭」：七十士譯本是「從約旦河中取十二塊準備好的石頭」。"]},{"n":4,"t":"於是約書亞召集了他從以色列人中所選的十二個人，每支派一人。","notes":[]},{"n":5,"t":"約書亞對他們說：「你們要過去，到約旦河中，耶和華－你們神的約櫃前面，按以色列人支派的數目，每人各取一塊石頭扛在肩上。","notes":[]},{"n":6,"t":"這些石頭在你們中間將成為記號。日後，你們的子孫問你們說：『這些石頭對你們有甚麼意思呢？』","notes":[]},{"n":7,"t":"你們就對他們說：『這是因為約旦河的水在耶和華的約櫃前中斷；約櫃過約旦河的時候，約旦河的水就中斷了。這些石頭要作以色列人永遠的紀念。』」","notes":[]},{"n":8,"t":"以色列人就照約書亞所吩咐的做了。他們按以色列人支派的數目，從約旦河中取了十二塊石頭，正如耶和華所吩咐約書亞的。他們把石頭帶過去，到他們所住宿的地方，就放在那裏。","notes":[]},{"n":9,"t":"約書亞另外把十二塊石頭立在約旦河的中間，在抬約櫃祭司的腳站立的地方；直到今日，石頭還在那裏。","notes":[]},{"n":10,"t":"抬約櫃的祭司站在約旦河的中間，直到耶和華命令約書亞告訴百姓的一切事辦完為止，正如摩西所吩咐約書亞的一切話。於是，百姓急速過了河。","notes":[]},{"n":11,"t":"全體百姓都過了河之後，耶和華的約櫃和祭司才過去，到百姓的前面。","notes":[]},{"n":12,"t":"呂便人、迦得人、瑪拿西半支派的人都照摩西所吩咐他們的，帶著兵器在以色列人的前面過去。","notes":[]},{"n":13,"t":"約有四萬帶兵器的軍隊在耶和華面前過去，到耶利哥的平原，準備上陣。","notes":[]},{"n":14,"t":"在那日，耶和華使約書亞在以色列眾人眼前被尊為大。在他一生的年日中，百姓敬服他，像從前敬服摩西一樣。","notes":[]},{"n":15,"t":"耶和華對約書亞說：","notes":[]},{"n":16,"t":"「你吩咐抬法櫃的祭司從約旦河上來。」","notes":[]},{"n":17,"t":"約書亞就吩咐祭司說：「你們從約旦河上來。」","notes":[]},{"n":18,"t":"抬耶和華約櫃的祭司從約旦河中上來，腳掌一落乾地，約旦河的水就流回原處，仍舊漲滿兩岸。","notes":[]},{"n":19,"t":"正月初十，百姓從約旦河上來，就在耶利哥東邊的吉甲安營。","notes":[]},{"n":20,"t":"約書亞把他們從約旦河取來的那十二塊石頭立在吉甲，","notes":[]},{"n":21,"t":"對以色列人說：「日後，你們的子孫問他們的父親說：『這些石頭是甚麼意思呢？』","notes":[]},{"n":22,"t":"你們就讓你們的子孫知道，說：『以色列人曾走乾地過這約旦河。』","notes":[]},{"n":23,"t":"因為耶和華－你們的神在你們前面使約旦河的水乾了，直到你們過來，就如耶和華－你們的神從前在我們前面使紅海乾了，直到我們過來一樣，","notes":[]},{"n":24,"t":"要使地上萬民都知道，耶和華的手大有能力，也要使你們天天敬畏耶和華－你們的神。」","notes":[]}]},"5":{"heading":"在吉甲行割禮","verses":[{"n":1,"t":"約旦河西亞摩利人的眾王和靠海迦南人的眾王，聽見耶和華在以色列人前面使約旦河的水乾了，直到他們過了河，眾王因以色列人的緣故都膽戰心驚，勇氣全失。","notes":["「他們過了河」：原文另譯「我們過了河」。"]},{"n":2,"t":"那時，耶和華對約書亞說：「你要造火石刀，第二次為以色列人行割禮。」","notes":[]},{"n":3,"t":"約書亞就造了火石刀，在哈爾拉勒山為以色列人行割禮。","notes":["「哈爾拉勒山」意思是「包皮山」。"]},{"n":4,"t":"約書亞行割禮的原因是這樣：從埃及出來的眾百姓，所有能打仗的男丁，出了埃及以後，都死在曠野的路上。","notes":[]},{"n":5,"t":"這些從埃及出來的眾百姓都受過割禮；但是那些出埃及以後，在曠野的路上所生的眾百姓卻沒有受過割禮。","notes":[]},{"n":6,"t":"以色列人在曠野走了四十年，直到那從埃及出來，全國能打仗的人都消滅了，因為他們沒有聽從耶和華的話。耶和華曾向他們起誓，必不容許他們看見耶和華向他們列祖起誓要給我們的地，就是流奶與蜜之地。","notes":[]},{"n":7,"t":"他們的子孫，就是耶和華興起接續他們的，都沒有受過割禮；因為在路上他們沒有受割禮，約書亞就為他們行割禮。","notes":[]},{"n":8,"t":"全國的人都受了割禮，留在營中自己的地方，直到痊癒。","notes":[]},{"n":9,"t":"耶和華對約書亞說：「我今日將埃及的羞辱從你們身上除掉了。」因此，那地方名叫吉甲，直到今日。","notes":["「吉甲」意思是「除掉、滾離」。"]},{"n":10,"t":"以色列人在吉甲安營。正月十四日晚上，他們在耶利哥的平原守逾越節。","notes":[],"heads":["在吉甲守逾越節"]},{"n":11,"t":"逾越節的第二日，他們吃了當地的出產，就在那一天，吃了無酵餅和烘過的穀物。","notes":[]},{"n":12,"t":"他們吃了當地出產的第二日，嗎哪就停止了。以色列人不再有嗎哪了。那一年，他們就吃迦南地的出產。","notes":[]},{"n":13,"t":"約書亞靠近耶利哥的時候，舉目觀看，看哪，有一個人站在他對面，手裏拿著拔出來的刀。約書亞到他那裏，對他說：「你是屬我們的，還是屬我們敵人的呢？」","notes":[],"heads":["耶和華軍隊的元帥"]},{"n":14,"t":"他說：「不，我現在來是要作耶和華軍隊的元帥。」約書亞就臉伏於地下拜，說：「我主有甚麼話，請吩咐僕人吧！」","notes":[]},{"n":15,"t":"耶和華軍隊的元帥對約書亞說：「把你腳上的鞋脫下來，因為你所站的地方是聖的。」約書亞就照著做了。","notes":[]}]},"6":{"heading":"耶利哥城陷落","verses":[{"n":1,"t":"耶利哥的城門因以色列人的緣故，關得嚴緊，無人出入。","notes":[]},{"n":2,"t":"耶和華對約書亞說：「看，我已經把耶利哥城和耶利哥王，以及大能的勇士，都交在你手中。","notes":[]},{"n":3,"t":"你們要圍繞這城，所有的士兵繞城一次，六日你都要這樣做。","notes":[]},{"n":4,"t":"七個祭司要拿七個羊角走在約櫃前。到了第七日，你們要圍繞這城七次，祭司也要吹角。","notes":[]},{"n":5,"t":"羊角聲拖長的時候，你們一聽見角聲，眾百姓要大聲呼喊，城牆就必倒塌，各人要往前直上。」","notes":[]},{"n":6,"t":"嫩的兒子約書亞召了祭司來，對他們說：「你們抬起約櫃來，要有七個祭司拿七個羊角在耶和華的約櫃前。」","notes":[]},{"n":7,"t":"他又對百姓說：「你們向前去圍繞那城，帶兵器的要在耶和華的約櫃前過去。」","notes":[]},{"n":8,"t":"按照約書亞對百姓所說的，七個祭司拿了七個羊角在耶和華面前過去，他們吹著角，耶和華的約櫃在他們後面跟著。","notes":[]},{"n":9,"t":"帶兵器的走在吹角的祭司前面，後隊跟著約櫃走，號角繼續在吹。","notes":[]},{"n":10,"t":"約書亞吩咐百姓說：「你們不可呼喊，不可讓人聽見你們的聲音，連一句話也不可出你們的口，直到我對你們說『呼喊』的那日，你們才呼喊。」","notes":[]},{"n":11,"t":"這樣，約書亞使耶和華的約櫃圍繞那城，把城繞了一次。然後，眾人回到營裏，就在營裏住宿。","notes":[]},{"n":12,"t":"約書亞清早起來，祭司又抬起耶和華的約櫃。","notes":[]},{"n":13,"t":"七個祭司拿七個羊角，走在耶和華的約櫃前，他們吹著角；帶兵器的走在他們前面，後隊跟著耶和華的約櫃走，號角繼續在吹。","notes":[]},{"n":14,"t":"第二日，他們再把城圍繞一次，就回營裏去。六日都是這樣做。","notes":[]},{"n":15,"t":"第七日清早黎明時，他們起來，以同樣的方式圍繞城七次；惟獨這一日他們圍繞城七次。","notes":[]},{"n":16,"t":"到了第七次，祭司吹角的時候，約書亞對百姓說：「呼喊吧，因為耶和華已經把城交給你們了！","notes":[]},{"n":17,"t":"這城和其中所有的都要永獻給耶和華作當毀滅的，只有妓女喇合與她家中所有的可以存活，因為她隱藏了我們所派的使者。","notes":[]},{"n":18,"t":"但你們務必謹慎，不可取那當滅的物，免得你們受詛咒，取了那當滅的物，使以色列全營成為詛咒而遭受災禍。","notes":[]},{"n":19,"t":"只有金子、銀子和銅鐵的器皿都要歸耶和華為聖，放入耶和華的庫房中。」","notes":[]},{"n":20,"t":"於是百姓呼喊，祭司吹角。百姓一聽見角聲就大聲呼喊，城牆隨著倒塌。百姓上去進城，各人往前直上，把城奪取。","notes":[]},{"n":21,"t":"他們把城中所有的，無論男女老少，牛羊和驢，都用刀殺盡。","notes":[]},{"n":22,"t":"約書亞對窺探這地的兩個人說：「你們進那妓女的家，照你們向她所起的誓，將那女人和她所有的都從那裏帶出來。」","notes":[]},{"n":23,"t":"兩個作過探子的青年進去，把喇合與她的父母、兄弟，和她所有的帶出來，他們把她所有的親屬都帶出來，安置在以色列的營外。","notes":[]},{"n":24,"t":"他們用火焚燒了那城和其中所有的，只有金子、銀子和銅鐵的器皿都放在耶和華殿的庫房中。","notes":[]},{"n":25,"t":"至於妓女喇合和她父家，以及她所有的，約書亞保存了他們的性命。她就住在以色列中，直到今日，因為她隱藏了約書亞派來窺探耶利哥的使者。","notes":[]},{"n":26,"t":"當時，約書亞叫眾人起誓說：「凡興起重修這耶利哥城的，當在耶和華面前受詛咒。他立根基的時候，必喪長子，安城門的時候，必喪幼子。」","notes":["「這耶利哥城」：七十士譯本是「這城」。"]},{"n":27,"t":"耶和華與約書亞同在，約書亞的名聲傳遍全地。","notes":[]}]},"7":{"heading":"亞干犯罪","verses":[{"n":1,"t":"以色列人在當滅之物上犯了罪。猶大支派中，謝拉的曾孫，撒底的孫子，迦米的兒子亞干取了當滅之物，耶和華的怒氣就向以色列人發作。","notes":[]},{"n":2,"t":"約書亞從耶利哥派人往伯特利東邊，靠近伯‧亞文的艾城去，對他們說：「你們上去窺探那地。」那些人就上去窺探艾城。","notes":["七十士譯本沒有「靠近伯‧亞文」。"]},{"n":3,"t":"他們回到約書亞那裏，對他說：「眾百姓不必都上去，只要二、三千人上去就能攻取艾城；不必勞動眾百姓都上去，因為他們人少。」","notes":[]},{"n":4,"t":"於是百姓中約有三千人上那裏去，但他們竟在艾城的人面前逃跑。","notes":[]},{"n":5,"t":"艾城的人擊殺他們約三十六人，從城門前追趕他們，直到示巴琳，在下坡的地方擊敗他們。他們都膽戰心驚，融化如水。","notes":[]},{"n":6,"t":"約書亞和以色列的長老就撕裂衣服，在耶和華的約櫃前臉伏於地，直到晚上。他們把灰撒在頭上。","notes":[]},{"n":7,"t":"約書亞說：「唉！主耶和華啊，你為甚麼領這百姓過約旦河，把我們交在亞摩利人手中，使我們滅亡呢？我們不如住在約旦河的那邊！","notes":[]},{"n":8,"t":"主啊，求求你，以色列人既在仇敵面前轉身逃跑，我還有甚麼可說的呢？","notes":[]},{"n":9,"t":"迦南人和這地所有的居民聽見了就必圍困我們，把我們的名從地上除去。那時，你為你至大的名要怎樣做呢？」","notes":[]},{"n":10,"t":"耶和華對約書亞說：「起來！你的臉為何這樣俯伏呢？","notes":[]},{"n":11,"t":"以色列犯了罪，又違背了我所吩咐他們的約，又取了當滅之物。他們又偷竊，又行詭詐，又把那當滅的物與自己的器皿放在一起。","notes":[]},{"n":12,"t":"因此，以色列人在仇敵面前站立不住。他們在仇敵面前轉身逃跑，因為他們成了當滅的物。你們若不把當滅的物從你們中間除掉，我就不再與你們同在了。","notes":[]},{"n":13,"t":"你起來，去叫百姓分別為聖，說：『你們要為了明天使自己分別為聖，因為耶和華－以色列的神這樣說：以色列啊，在你中間有當滅的物；你們若不把你們中間當滅之物除掉，你在仇敵面前必站立不住！』","notes":[]},{"n":14,"t":"到了早晨，你們要按著支派近前來。耶和華所選的支派，要按著宗族近前來；耶和華所選的宗族，要按著家族近前來；耶和華所選的家族，要按著男丁，一個一個近前來。","notes":[]},{"n":15,"t":"被選的人有當滅之物在他那裏，他和他所有的必被火焚燒，因為他違背了耶和華的約，又因他在以色列中做了愚妄的事。」","notes":[]},{"n":16,"t":"於是，約書亞清早起來，召以色列按著支派近前來。選出來的是猶大支派。","notes":[]},{"n":17,"t":"他召猶大的宗族近前來，選出來的是謝拉宗族。他召謝拉宗族，按著男丁，一個一個近前來，選出來的是撒底。","notes":["「按著男丁」：有古卷和古譯本是「按著家族」。"]},{"n":18,"t":"他召撒底的家族，按著男丁，一個一個近前來，就選出猶大支派，謝拉的曾孫，撒底的孫子，迦米的兒子亞干。","notes":[]},{"n":19,"t":"約書亞對亞干說：「我兒，我勸你將榮耀歸給耶和華－以色列的神，在他面前認罪，把你所做的事告訴我，不可向我隱瞞。」","notes":[]},{"n":20,"t":"亞干回答約書亞說：「我實在得罪了耶和華－以色列的神。這是我所做的：","notes":[]},{"n":21,"t":"我在所奪取的財物中看見一件美好的示拿外袍，二百舍客勒銀子，一條重五十舍客勒的金子。我貪愛這些物件，就拿去了。看哪，這些東西都埋在我帳棚內的地裏，銀子在外袍底下。」","notes":[]},{"n":22,"t":"約書亞就派使者跑到亞干的帳棚裏。看哪，那件外袍藏在他的帳棚裏，銀子在外袍底下。","notes":[]},{"n":23,"t":"他們從帳棚裏把這些東西取出來，拿到約書亞和以色列眾人那裏，倒在耶和華面前。","notes":["「眾人」：七十士譯本是「長老」。"]},{"n":24,"t":"約書亞和以色列眾人把謝拉的曾孫亞干和那銀子、那件外袍、那條金子，以及亞干的兒女、牛、驢、羊、帳棚，和他所有的，都帶著上到亞割谷去。","notes":["「亞割谷」意思是「災禍谷」。"]},{"n":25,"t":"約書亞說：「你為甚麼給我們招惹災禍呢？今日耶和華必使你遭受災禍。」於是以色列眾人用石頭打死他，用火焚燒他們，把石頭扔在其上。","notes":[]},{"n":26,"t":"眾人在亞干身上堆了一大堆石頭，直存到今日。於是耶和華轉意，不發他的烈怒。因此，那地方名叫亞割谷，直到今日。","notes":[]}]},"8":{"heading":"攻取艾城","verses":[{"n":1,"t":"耶和華對約書亞說：「不要懼怕，也不要驚惶。你起來，率領所有作戰的士兵上艾城去。看，我已經把艾城的王和他的百姓、他的城，以及他的地，都交在你手裏。","notes":[]},{"n":2,"t":"你怎樣處置耶利哥和耶利哥的王，也當照樣處置艾城和艾城的王。只是城內所奪的財物和牲畜，你們可以取為自己的掠物。你要在城的後面設下伏兵。","notes":[]},{"n":3,"t":"於是，約書亞和所有作戰的士兵都起來，上艾城去。約書亞選了三萬大能的勇士，夜間派遣他們前去，","notes":[]},{"n":4,"t":"吩咐他們說：「看，你們要在城的後面埋伏，不可離城太遠，各人都要準備。","notes":[]},{"n":5,"t":"我與我所帶領的眾士兵要向城前進。城裏的人像上一次那樣出來迎擊我們的時候，我們就在他們面前逃跑。","notes":[]},{"n":6,"t":"他們會出來追趕我們，直到我們引誘他們遠離那城。因為他們必說：『這些人像上次那樣在我們面前逃跑。』所以我們要在他們面前逃跑。","notes":["七十士譯本沒有「所以我們要在他們面前逃跑」。"]},{"n":7,"t":"那時，你們就從埋伏的地方起來，奪取那城，因為耶和華－你們的神必把城交在你們的手裏。","notes":[]},{"n":8,"t":"你們奪了城以後，要放火燒城，照耶和華的話去做。看，這是我吩咐你們的。」","notes":[]},{"n":9,"t":"於是，約書亞派遣他們前去。他們行軍到埋伏的地方，伏在伯特利和艾城的中間，就是艾城的西邊。這夜，約書亞在士兵中間過夜。","notes":[]},{"n":10,"t":"約書亞清早起來，點齊士兵。他和以色列的長老在百姓前面上艾城去。","notes":[]},{"n":11,"t":"所有跟他一起作戰的士兵都上去，向前逼近，來到城前，就在艾城北邊安營。約書亞與艾城之間隔著一個山谷。","notes":[]},{"n":12,"t":"他選了約五千人，安排他們埋伏在伯特利和艾城的中間，就是艾城的西邊。","notes":[]},{"n":13,"t":"於是，他們佈署軍隊，就是城北的全軍和城西的伏兵。當夜約書亞進入山谷之中。","notes":[]},{"n":14,"t":"艾城的王看見了，就和城裏的人清早起來，急忙出去，他和所有的士兵到了所定的地點，在亞拉巴前，迎擊以色列，與之交戰；王並不知道城的後面有伏兵。","notes":[]},{"n":15,"t":"約書亞和以色列眾人在他們面前裝敗，往曠野的路逃跑。","notes":[]},{"n":16,"t":"城內所有的百姓都被召來追趕他們。艾城的人追趕約書亞的時候，就被引誘遠離了城。","notes":[]},{"n":17,"t":"艾城和伯特利沒有一人不出來追趕以色列人的。他們撇下敞開的城門，去追趕以色列人。","notes":[]},{"n":18,"t":"耶和華對約書亞說：「你向艾城伸出手裏的標槍，因為我要把那城交在你手裏。」約書亞就向那城伸出手裏的標槍。","notes":[]},{"n":19,"t":"他一伸手，伏兵立刻從埋伏的地方衝出來，直攻入城，奪了它，立刻放火燒城。","notes":[]},{"n":20,"t":"艾城的人回頭，往後一看，看哪，城中煙氣沖天，他們向這邊或那邊都無處可逃。往曠野逃跑的百姓就轉身攻擊那些追趕他們的人。","notes":[]},{"n":21,"t":"約書亞和以色列眾人見伏兵已經奪了城，城中煙氣上騰，就轉身擊殺艾城的人。","notes":[]},{"n":22,"t":"伏兵也出城追擊他們，他們就被以色列人前後夾攻，四面受敵。於是以色列人擊殺他們，沒有留下一個倖存者，也沒有一個逃脫。","notes":[]},{"n":23,"t":"以色列人生擒了艾城的王，把他解到約書亞那裏。","notes":[]},{"n":24,"t":"以色列人在田間和曠野殺盡了追趕他們的艾城所有的居民。他們全倒在刀下，直到滅盡。以色列眾人就回到艾城，用刀殺了城中的人。","notes":[]},{"n":25,"t":"當日殺死的人，連男帶女共有一萬二千，這也是艾城所有的人。","notes":[]},{"n":26,"t":"約書亞沒有收回手裏所伸出來的標槍，直到他滅絕艾城所有的居民。","notes":[]},{"n":27,"t":"只是牲畜和城內所奪的財物，以色列人都照耶和華所吩咐約書亞的話，取為自己的掠物。","notes":[]},{"n":28,"t":"約書亞焚燒艾城，使城成為永遠的廢墟，直到今日還是荒涼。","notes":[]},{"n":29,"t":"他把艾城的王掛在樹上，直到晚上。日落的時候，約書亞吩咐人把屍首從樹上取下來，丟在城門口，並在屍首上堆了一大堆石頭，直存到今日。","notes":[]},{"n":30,"t":"那時，約書亞在以巴路山上為耶和華－以色列的神築一座壇。","notes":[],"heads":["在以巴路山上宣讀律法"]},{"n":31,"t":"這壇是照耶和華的僕人摩西吩咐以色列人，用沒有動過鐵器的整塊石頭所築的，正如摩西律法書上所寫的。他們在這壇上給耶和華奉獻燔祭，又宰牲作為平安祭。","notes":[]},{"n":32,"t":"約書亞在那裏，當著以色列人面前，將摩西所寫的律法抄寫在石頭上。","notes":[]},{"n":33,"t":"以色列眾人，無論是本地人或寄居的，都和他們的長老、官長和審判官，站在約櫃兩旁，在抬耶和華約櫃的利未家的祭司面前，一半對著基利心山，一半對著以巴路山，照耶和華的僕人摩西先前所吩咐的，為以色列百姓祝福。","notes":[]},{"n":34,"t":"隨後，約書亞將律法上祝福和詛咒的話，照著律法書上一切所寫的，宣讀一遍。","notes":[]},{"n":35,"t":"摩西所吩咐的一切話，約書亞在以色列全會眾和婦女、孩童，以及住在他們中間的外人面前，沒有一句不宣讀的。","notes":[]}]},"9":{"heading":"基遍人欺騙約書亞","verses":[{"n":1,"t":"約旦河西，住山區、低地和沿大海一帶直到黎巴嫩的諸王，就是赫人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人的諸王，聽見這事，","notes":[]},{"n":2,"t":"就都聚集，同心合意要與約書亞和以色列人作戰。","notes":[]},{"n":3,"t":"基遍的居民聽見約書亞向耶利哥和艾城所做的事，","notes":[]},{"n":4,"t":"就設詭計，假扮使者出去。他們拿舊布袋和破裂補過的舊皮酒袋馱在驢上，","notes":["「假扮使者」：有古卷、七十士譯本和其他古譯本是「帶著糧食」。"]},{"n":5,"t":"將補過的舊鞋穿在腳上，把舊衣服穿在身上，作食物的餅都又乾又長了霉。","notes":["「長了霉」或譯「碎」；下同。"]},{"n":6,"t":"他們到吉甲營中約書亞那裏，對他和以色列人說：「我們是從遠地來的，現在求你與我們立約。」","notes":[]},{"n":7,"t":"以色列人對希未人說：「或許你是住在我附近的。若是這樣，我怎能和你立約呢？」","notes":[]},{"n":8,"t":"他們對約書亞說：「我們是你的僕人。」約書亞對他們說：「你們是甚麼人？是從哪裏來的？」","notes":[]},{"n":9,"t":"他們對他說：「你的僕人是因耶和華－你神的名從極遠之地來的。我們聽見他的名聲，他在埃及所做的一切，","notes":[]},{"n":10,"t":"以及他向約旦河東的兩個亞摩利王，希實本王西宏和在亞斯她錄的巴珊王噩所做的一切。","notes":[]},{"n":11,"t":"我們的長老和我們當地所有的居民對我們說：『你們手裏要帶著路上用的乾糧去迎接以色列人，對他們說：我們是你們的僕人。現在求你們與我們立約。』","notes":[]},{"n":12,"t":"我們出來要往你們這裏來的那日，這從我們家裏帶出來的餅是熱的；看哪，現在這餅又乾又長了霉。","notes":[]},{"n":13,"t":"這些皮酒袋，我們盛酒的時候還是新的；看哪，現在已經破裂了。我們這些衣服和鞋，因為路途非常遙遠，也都穿舊了。」","notes":[]},{"n":14,"t":"以色列人收下他們的一些食物，但是沒有求問耶和華的指示。","notes":[]},{"n":15,"t":"於是約書亞與他們建立和好關係，與他們立約，讓他們存活；會眾的領袖也向他們起誓。","notes":[]},{"n":16,"t":"以色列人與他們立約之後，過了三天才聽說他們是近鄰，住在附近。","notes":[]},{"n":17,"t":"以色列人起行，第三天就到了他們的城鎮，他們的城鎮是基遍、基非拉、比錄和基列‧耶琳。","notes":[]},{"n":18,"t":"因為會眾的領袖已經指著耶和華－以色列的神向他們起誓，所以以色列人不擊殺他們。全會眾就向領袖發怨言。","notes":[]},{"n":19,"t":"眾領袖對全會眾說：「我們已經指著耶和華－以色列的神向他們起誓，現在我們不能碰他們。","notes":[]},{"n":20,"t":"我們要這樣對待他們，讓他們存活，免得因我們向他們所起的誓而憤怒臨到我們。」","notes":[]},{"n":21,"t":"領袖對會眾說：「讓他們活著吧。」於是他們照領袖所說的，為全會眾作劈柴挑水的人。","notes":[]},{"n":22,"t":"約書亞召了他們來，對他們說：「你們為甚麼欺騙我們說：『我們離你們很遠』呢？其實你們就住在我們附近。","notes":[]},{"n":23,"t":"現在你們當受詛咒！你們中間必不斷有人作奴僕，為我神的殿作劈柴挑水的人。」","notes":[]},{"n":24,"t":"他們回答約書亞說：「因為確實有人告訴你的僕人，耶和華－你的神曾吩咐他的僕人摩西，把這全地賜給你們，並要在你們面前除滅這地所有的居民。我們因你們的緣故很怕自己喪命，就做了這事。","notes":[]},{"n":25,"t":"現在，看哪，我們在你手中，你看怎樣待我們是好的，是對的，就這樣做吧！」","notes":[]},{"n":26,"t":"於是約書亞就這樣對待他們，他救了他們脫離以色列人的手，以色列人沒有殺他們。","notes":[]},{"n":27,"t":"那日，約書亞分派他們到耶和華選擇的地方，為會眾和耶和華的壇劈柴挑水，直到今日。","notes":[]}]},"10":{"heading":"擊敗亞摩利人","verses":[{"n":1,"t":"耶路撒冷王亞多尼‧洗德聽見約書亞奪了艾城，徹底毀滅，處置艾城和艾城的王像處置耶利哥和耶利哥的王一樣，又聽見基遍的居民與以色列人立了和約，住在他們中間，","notes":[]},{"n":2,"t":"耶路撒冷人就很懼怕，因為基遍是一座大城，如京城一樣，比艾城更大，並且城內的人都是勇士。","notes":[]},{"n":3,"t":"耶路撒冷王亞多尼‧洗德派人去見希伯崙王何咸、耶末王毗蘭、拉吉王雅非亞和伊磯倫王底璧，說：","notes":[]},{"n":4,"t":"「求你們上來幫助我，我們好攻打基遍，因為它與約書亞和以色列人立了和約。」","notes":[]},{"n":5,"t":"於是五個亞摩利王，就是耶路撒冷王、希伯崙王、耶末王、拉吉王和伊磯倫王，聯合上去，率領他們所有的軍隊，對著基遍安營，要攻打基遍。","notes":[]},{"n":6,"t":"基遍人就派人到吉甲的營中約書亞那裏，說：「不要袖手不顧你的僕人，求你趕快上來拯救我們，幫助我們，因為住山區亞摩利人的諸王已經聯合來攻擊我們。」","notes":[]},{"n":7,"t":"於是約書亞和所有跟他一起作戰的士兵，以及大能的勇士，從吉甲上去。","notes":[]},{"n":8,"t":"耶和華對約書亞說：「不要怕他們， 因為我已將他們交在你手裏，他們沒有一人能在你面前站立得住。」","notes":[]},{"n":9,"t":"約書亞就連夜從吉甲上去，猛然襲擊他們。","notes":[]},{"n":10,"t":"耶和華使他們在以色列人面前潰亂。約書亞在基遍大大擊殺他們，在伯‧和崙的上坡路上追趕他們，擊殺他們，直到亞西加和瑪基大。","notes":[]},{"n":11,"t":"他們在以色列人面前逃跑。正在伯‧和崙下坡的時候，耶和華從天上降下大冰雹在他們身上，直降到亞西加，打死他們。被冰雹打死的，比以色列人用刀殺死的還多。","notes":["「冰雹」：原文是「石頭」。"]},{"n":12,"t":"當耶和華將亞摩利人交給以色列人的那一日，約書亞向耶和華說話，在以色列人眼前說：「太陽啊，停在基遍；月亮啊，停在亞雅崙谷。」","notes":[]},{"n":13,"t":"太陽就停住，月亮就止住，直到國家向敵人報仇。這事豈不是寫在《雅煞珥書》上嗎？太陽停在天空當中，沒有急速落下，約有一整天。","notes":[]},{"n":14,"t":"在這日以前，這日以後，耶和華聽人的聲音，沒有像這日的，這是因為耶和華為以色列作戰。","notes":[]},{"n":15,"t":"約書亞和跟他一起的以色列眾人回到吉甲的營中。","notes":[]},{"n":16,"t":"那五個王逃跑，躲在瑪基大洞裏。","notes":[],"heads":["生擒亞摩利的五王"]},{"n":17,"t":"有人告訴約書亞說：「那五個王已經找到了，都躲在瑪基大洞裏。」","notes":[]},{"n":18,"t":"約書亞說：「你們把幾塊大石頭滾到洞口，派人在那裏看守他們。","notes":[]},{"n":19,"t":"你們卻不可停留，要追趕你們的仇敵，從後面攻擊他們，不讓他們進到自己的城鎮，因為耶和華－你們的神已經把他們交在你們手裏。」","notes":[]},{"n":20,"t":"約書亞和以色列人徹底擊敗他們，直到把他們滅盡，只剩下少許的人逃進堅固的城。","notes":[]},{"n":21,"t":"眾百姓就安然回到瑪基大營中，到約書亞那裏。沒有人敢向以色列人饒舌。","notes":["七十士譯本沒有「營中」。"]},{"n":22,"t":"約書亞說：「打開洞口，把那五個王從洞裏帶出來，到我這裏。」","notes":[]},{"n":23,"t":"眾人就這樣做，把那五個王，就是耶路撒冷王、希伯崙王、耶末王、拉吉王和伊磯倫王，從洞裏帶出來，到約書亞那裏。","notes":[]},{"n":24,"t":"他們帶出那五個王到約書亞那裏的時候，約書亞就召了以色列眾人來，對和他同去的軍官說：「你們近前來，把腳踏在這些王的頸項上。」他們就近前來，把腳踏在這些王的頸項上。","notes":[]},{"n":25,"t":"約書亞對他們說：「你們不要懼怕，也不要驚惶。當剛強壯膽，因為耶和華必這樣處置你們要攻打的所有仇敵。」","notes":[]},{"n":26,"t":"隨後，約書亞把這五個王殺死，掛在五棵樹上。他們就被掛在樹上，直到晚上。","notes":[]},{"n":27,"t":"日落的時候，約書亞吩咐人把屍首從樹上取下來，丟在他們躲過的洞裏，把幾塊大石頭放在洞口，直存到今日。","notes":[]},{"n":28,"t":"當日，約書亞奪了瑪基大，用刀擊殺城中的人和王，把城中所有人完全滅盡，沒有留下一個倖存者。他處置瑪基大王，像從前處置耶利哥王一樣。","notes":[],"heads":["攻取更多的城鎮"]},{"n":29,"t":"約書亞和跟他一起的以色列眾人從瑪基大往立拿去，攻打立拿。","notes":[]},{"n":30,"t":"耶和華將立拿和立拿的王也交在以色列人手裏。約書亞攻打這城，用刀擊殺了城中所有的人，沒有留下一個倖存者。他處置立拿王，像從前處置耶利哥王一樣。","notes":[]},{"n":31,"t":"約書亞和跟他一起的以色列眾人從立拿往拉吉去，對著拉吉安營，攻打這城。","notes":[]},{"n":32,"t":"耶和華將拉吉交在以色列人的手裏。第二日約書亞就奪了拉吉，用刀擊殺了城中所有的人，正如他向立拿一切所做的。","notes":[]},{"n":33,"t":"那時基色王何蘭上來幫助拉吉，約書亞就把他和他的百姓都擊殺了，沒有留下一個倖存者。","notes":[]},{"n":34,"t":"約書亞和跟他一起的以色列眾人從拉吉往伊磯倫去，對著伊磯倫安營，攻打這城。","notes":[]},{"n":35,"t":"當日約書亞就奪了城，用刀擊殺了城中的人。那日，約書亞把城中所有的人完全滅盡，正如他向拉吉一切所做的。","notes":[]},{"n":36,"t":"約書亞和跟他一起的以色列眾人從伊磯倫上希伯崙去，攻打這城，","notes":[]},{"n":37,"t":"奪了希伯崙，用刀擊敗希伯崙、它的王和屬它的一切城鎮，以及城中所有的人；他沒有留下一個倖存者，正如他向伊磯倫所做的，把城中所有的人完全滅盡。","notes":[]},{"n":38,"t":"約書亞和跟他一起的以色列眾人回到底璧，攻打這城，","notes":[]},{"n":39,"t":"奪了底璧和屬它的一切城鎮，又擒獲它的王，用刀把城中所有的人完全滅盡，沒有留下一個倖存者。他處置底璧和它的王，像從前處置希伯崙，處置立拿和它的王一樣。","notes":[]},{"n":40,"t":"這樣，約書亞擊敗全地的人，就是山區、尼革夫、低地、山坡的人，和那裏的眾王，沒有留下一個倖存者。他把凡有氣息的完全滅盡，正如耶和華－以色列的神所吩咐的。","notes":["「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」；本卷書下同。"]},{"n":41,"t":"約書亞從加低斯‧巴尼亞攻到迦薩，又攻打歌珊全地，直到基遍。","notes":[]},{"n":42,"t":"約書亞一舉擊敗了這些王，奪了他們的地，因為耶和華－以色列的神為以色列作戰。","notes":[]},{"n":43,"t":"於是約書亞和跟他一起的以色列眾人回到吉甲的營中。","notes":[]}]},"11":{"heading":"擊敗眾王的聯軍","verses":[{"n":1,"t":"夏瑣王耶賓聽見了，就派人到瑪頓王約巴、伸崙王、押煞王，","notes":["「瑪頓」：七十士譯本是「瑪倫」。","「伸崙」：七十士譯本是「伸門」。"]},{"n":2,"t":"和北方山區、基尼烈南邊的亞拉巴、低地、西邊多珥山岡的諸王，","notes":["「山岡」或譯「全境」。"]},{"n":3,"t":"以及東方和西方的迦南人、山區的亞摩利人、赫人、比利洗人、耶布斯人，和黑門山下米斯巴地的希未人那裏。","notes":[]},{"n":4,"t":"他們和他們的眾軍都出來，一大隊人馬，多如海邊的沙，並有極多的戰車戰馬。","notes":[]},{"n":5,"t":"眾王組成聯軍，來到米倫水邊一同安營，要與以色列作戰。","notes":[]},{"n":6,"t":"耶和華對約書亞說：「你不要怕他們。明日這時，我必把他們全部交給以色列人殺滅。你要砍斷他們馬的蹄筋，用火焚燒他們的戰車。」","notes":[]},{"n":7,"t":"於是約書亞和所有跟他一起作戰的士兵，來到米倫水邊，突然攻擊他們。","notes":[]},{"n":8,"t":"耶和華將他們交在以色列人手裏，以色列人就擊殺他們，追趕他們到西頓大城，到米斯利弗‧瑪音，直到東邊米斯巴的山谷。以色列人擊殺他們，沒有留下一個倖存者。","notes":[]},{"n":9,"t":"約書亞照耶和華所吩咐他的去做，砍斷他們馬的蹄筋，用火焚燒他們的戰車。","notes":[]},{"n":10,"t":"那時，約書亞轉回，奪了夏瑣，用刀殺了夏瑣王。先前夏瑣在這些王國中是為首的。","notes":[]},{"n":11,"t":"以色列人用刀擊殺城中所有的人，把他們完全滅盡；凡有氣息的，沒有留下一個。約書亞又用火焚燒夏瑣。","notes":[]},{"n":12,"t":"約書亞奪了這些王的一切城鎮，擒獲了這些王，用刀殺了他們，把他們完全滅盡，正如耶和華的僕人摩西所吩咐的。","notes":[]},{"n":13,"t":"至於造在山岡上的城鎮，除了夏瑣以外，以色列人都沒有焚燒。約書亞只焚燒了夏瑣。","notes":[]},{"n":14,"t":"從那些城鎮所奪的財物和牲畜，以色列人都取為自己的掠物。至於所有的人，他們都用刀殺了，直到滅盡；凡有氣息的，沒有留下一個。","notes":[]},{"n":15,"t":"耶和華怎樣吩咐他的僕人摩西，摩西就這樣吩咐約書亞，約書亞也照樣做了。凡耶和華所吩咐摩西的，約書亞沒有一件偏離不做的。","notes":[]},{"n":16,"t":"約書亞奪了那全地，就是山區、整個尼革夫、歌珊全地、低地、亞拉巴、以色列的山區和山下的低地，","notes":[],"heads":["佔領的土地"]},{"n":17,"t":"從上西珥的哈拉山，直到黑門山下面黎巴嫩平原的巴力‧迦得。他擒獲了那裏的眾王，把他們殺死。","notes":[]},{"n":18,"t":"約書亞和這些王作戰了很長的一段日子。","notes":[]},{"n":19,"t":"除了希未人基遍的居民之外，沒有一城與以色列人講和，都是以色列人作戰奪來的。","notes":[]},{"n":20,"t":"因為耶和華的意思是要使他們的心剛硬，來與以色列人作戰，好使他們全被殺滅，不蒙憐憫，反被除滅，正如耶和華所吩咐摩西的。","notes":[]},{"n":21,"t":"那時約書亞來到，剪除了住山區、希伯崙、底璧、亞拿伯、整個猶大山區和以色列山區的亞衲族人。約書亞把他們和他們的城鎮盡都毀滅。","notes":[]},{"n":22,"t":"以色列人的地中沒有留下一個亞衲族人，只有一些還留在迦薩、迦特和亞實突。","notes":[]},{"n":23,"t":"這樣，約書亞照著耶和華所吩咐摩西的一切話奪了那全地，就按著以色列支派所得的份把地分給他們為業。於是國中太平，沒有戰爭了。","notes":[]}]},"12":{"heading":"摩西擊敗的諸王","verses":[{"n":1,"t":"這些是以色列人在約旦河東，向日出的方向，從亞嫩谷直到黑門山，以及東邊亞拉巴的整個地區所擊殺的王和所得的地：","notes":[]},{"n":2,"t":"有住希實本的亞摩利王西宏，他統治的地從亞嫩谷邊的亞羅珥起，包括谷中之城和基列的一半，直到亞捫人邊界的雅博河，","notes":[]},{"n":3,"t":"以及從東邊的亞拉巴，直到基尼烈海，又向東通過伯‧耶施末的路，直到亞拉巴的海，就是鹽海，再往南直到毗斯迦山斜坡的山腳。","notes":[]},{"n":4,"t":"又有巴珊王噩，他是利乏音人所剩下的，住在亞斯她錄和以得來。","notes":["「又有巴珊王噩」是根據七十士譯本；原文是「以下是巴珊王噩的疆土」。"]},{"n":5,"t":"他統治的地是黑門山、撒迦、巴珊全地，直到基述人和瑪迦人的邊界，以及基列的一半，直到希實本王西宏的邊界。","notes":[]},{"n":6,"t":"這兩個王是耶和華的僕人摩西和以色列人所擊殺的。耶和華的僕人摩西把他們的地賜給呂便人、迦得人和瑪拿西半支派的人為業。","notes":[]},{"n":7,"t":"這些是約書亞和以色列人在約旦河西所擊殺的諸王，他們的地從黎巴嫩平原的巴力‧迦得，直上到西珥的哈拉山。約書亞按著以色列支派所得的份把這地分給他們為業，","notes":[],"heads":["約書亞擊敗的諸王"]},{"n":8,"t":"就是赫人、亞摩利人、迦南人、比利洗人、希未人、耶布斯人的地，包括山區、低地、亞拉巴、山坡、曠野和尼革夫。","notes":[]},{"n":9,"t":"這些王是：耶利哥王一人，靠近伯特利的艾城王一人，","notes":[]},{"n":10,"t":"耶路撒冷王一人，希伯崙王一人，","notes":[]},{"n":11,"t":"耶末王一人，拉吉王一人，","notes":[]},{"n":12,"t":"伊磯倫王一人，基色王一人，","notes":[]},{"n":13,"t":"底璧王一人，基德王一人，","notes":[]},{"n":14,"t":"何珥瑪王一人，亞拉得王一人，","notes":[]},{"n":15,"t":"立拿王一人，亞杜蘭王一人，","notes":[]},{"n":16,"t":"瑪基大王一人，伯特利王一人，","notes":[]},{"n":17,"t":"他普亞王一人，希弗王一人，","notes":[]},{"n":18,"t":"亞弗王一人，拉沙崙王一人，","notes":[]},{"n":19,"t":"瑪頓王一人，夏瑣王一人，","notes":[]},{"n":20,"t":"伸崙‧米崙王一人，押煞王一人，","notes":["「伸崙‧米崙王一人」：七十士譯本是「伸門王一人，米崙王一人」。"]},{"n":21,"t":"他納王一人，米吉多王一人，","notes":[]},{"n":22,"t":"基低斯王一人，靠近迦密的約念王一人，","notes":[]},{"n":23,"t":"多珥山岡的多珥王一人，吉甲的戈印王一人，","notes":["「山岡」或譯「全境」。","「吉甲的」：七十士譯本是「加利利的」。"]},{"n":24,"t":"得撒王一人，共三十一個王。","notes":[]}]},"13":{"heading":"未得之地","verses":[{"n":1,"t":"約書亞年紀老邁，耶和華對他說：「你年紀老邁了，還有極多剩下的未得之地。","notes":[]},{"n":2,"t":"這是剩下的地：非利士人的全境和一切屬於基述人的，","notes":[]},{"n":3,"t":"是從埃及東邊的西曷河往北，直到以革倫的邊界，算是屬迦南人的地，那裏有非利士人五個領袖統治迦薩人、亞實突人、亞實基倫人、迦特人、以革倫人；還有屬於亞衛人的，","notes":[]},{"n":4,"t":"在南邊；還有迦南人的全地，以及西頓人的米亞拉到亞弗，直到亞摩利人的邊界；","notes":["「西頓人的米亞拉」：原文另譯「從西頓人的亞拉」。"]},{"n":5,"t":"還有迦巴勒人的地，以及向日出方向的黎巴嫩全地，從黑門山下的巴力‧迦得，直到哈馬口；","notes":[]},{"n":6,"t":"從黎巴嫩直到米斯利弗‧瑪音，一切山區的居民，就是所有的西頓人，我必在以色列人面前趕走他們。你只管照我所吩咐的，抽籤將這地分給以色列人為業。","notes":[]},{"n":7,"t":"現在你要把這地分給九個支派和瑪拿西半個支派為業。」","notes":[]},{"n":8,"t":"呂便、迦得二支派已經和瑪拿西另外半個支派得了產業，就是耶和華的僕人摩西在約旦河東所賜給他們的：","notes":[],"heads":["約旦河東之地的分配"]},{"n":9,"t":"從亞嫩谷邊的亞羅珥和谷中之城，米底巴的整個平原，直到底本；","notes":[]},{"n":10,"t":"還有在希實本作王的亞摩利王西宏的諸城，直到亞捫人的邊界；","notes":[]},{"n":11,"t":"還有基列，基述人和瑪迦人的邊界，整個黑門山、整個巴珊，直到撒迦；","notes":[]},{"n":12,"t":"還有在亞斯她錄和以得來作王的巴珊王噩的整個國土，噩是利乏音人惟一存留的。摩西擊敗了這些人，把他們趕走。","notes":[]},{"n":13,"t":"以色列人卻沒有趕走基述人和瑪迦人；基述人和瑪迦人仍住在以色列中，直到今日。","notes":[]},{"n":14,"t":"只是利未支派，摩西沒有分產業給他們。他們的產業是獻給耶和華－以色列神的火祭，正如耶和華對他們說的。","notes":[]},{"n":15,"t":"摩西按著呂便支派的宗族分產業給他們。","notes":[],"heads":["分給呂便的土地"]},{"n":16,"t":"他們的地界是亞嫩谷邊的亞羅珥和谷中之城，靠近米底巴的整個平原；","notes":[]},{"n":17,"t":"還有希實本和屬希實本平原的各城，底本、巴末‧巴力、伯‧巴力‧勉、","notes":[]},{"n":18,"t":"雅雜、基底莫、米法押、","notes":[]},{"n":19,"t":"基列亭、西比瑪、谷中山岡上的細列‧沙轄、","notes":[]},{"n":20,"t":"伯‧毗珥、毗斯迦山斜坡、伯‧耶施末；","notes":[]},{"n":21,"t":"還有平原的各城，和亞摩利王西宏的整個國土。這西宏曾在希實本作王，摩西把他和米甸的族長以未、利金、蘇珥、戶珥、利巴擊殺了；他們都是屬西宏的領袖，曾住在這地。","notes":[]},{"n":22,"t":"以色列人殺了這些人時，也用刀殺了比珥的兒子占卜的巴蘭。","notes":[]},{"n":23,"t":"呂便人的地界就是約旦河和靠近約旦河的地。以上是呂便人按著宗族所得為業的城鎮和所屬的村莊。","notes":[]},{"n":24,"t":"摩西按著迦得支派的宗族分產業給他們。","notes":[],"heads":["分給迦得的土地"]},{"n":25,"t":"他們的地界是雅謝和基列的各城，以及亞捫人之地的一半，直到拉巴前面的亞羅珥；","notes":[]},{"n":26,"t":"還有從希實本到拉抹‧米斯巴和比多寧，又從瑪哈念到底璧的邊界，","notes":["「底璧」：原文另譯「羅‧底巴」。"]},{"n":27,"t":"和谷中的伯‧亞蘭、伯‧寧拉、疏割、撒分，就是希實本王西宏國土中其餘的地，以及約旦河與靠近約旦河的地，直到基尼烈海的邊緣，都在約旦河東。","notes":[]},{"n":28,"t":"以上是迦得人按著宗族所得為業的城鎮和所屬的村莊。","notes":[]},{"n":29,"t":"摩西分產業給瑪拿西半支派，這是按著瑪拿西半支派的宗族分的。","notes":[],"heads":["分給瑪拿西半支派的土地"]},{"n":30,"t":"他們的地界是從瑪哈念起，包括整個巴珊全地，就是巴珊王噩的整個國土，以及在巴珊、睚珥的一切城鎮，共六十個；","notes":[]},{"n":31,"t":"還有基列的一半，以及巴珊國的王噩的亞斯她錄和以得來兩座城。這些地是按著宗族分給瑪拿西兒子瑪吉子孫的，就是給瑪吉一半子孫的。","notes":[]},{"n":32,"t":"以上是摩西在約旦河東，耶利哥對面的摩押平原所分配的產業。","notes":[]},{"n":33,"t":"只是利未支派，摩西沒有把產業分給他們。耶和華－以色列的神是他們的產業，正如耶和華對他們說的。","notes":[]}]},"14":{"heading":"約旦河西之地的分配","verses":[{"n":1,"t":"這是以色列人在迦南地所得的產業，就是祭司以利亞撒和嫩的兒子約書亞，以及以色列人各支派父系的領袖所分給他們的。","notes":[]},{"n":2,"t":"他們照耶和華藉摩西所吩咐的，抽籤分產業給九個半支派。","notes":[]},{"n":3,"t":"摩西在約旦河東已經分了產業給另外兩個半支派。但是，他在他們中間沒有分產業給利未人。","notes":[]},{"n":4,"t":"因約瑟的子孫成了兩個支派，就是瑪拿西和以法蓮。雖然他們沒有分地給利未人，卻給利未人城鎮居住，以及城鎮的郊外供他們牧養牲畜，安置財物。","notes":[]},{"n":5,"t":"耶和華怎樣吩咐摩西，以色列人就照樣做，把地分了。","notes":[]},{"n":6,"t":"猶大人來到吉甲，約書亞那裏，基尼洗族耶孚尼的兒子迦勒對約書亞說：「耶和華在加低斯‧巴尼亞指著我和你對神人摩西所說的話，你都知道。","notes":[],"heads":["迦勒分得希伯崙"]},{"n":7,"t":"耶和華的僕人摩西從加低斯‧巴尼亞差派我窺探這地的時候，我剛四十歲。我把心裏的話向他報告。","notes":[]},{"n":8,"t":"雖然同我上去的眾弟兄使百姓膽戰心驚，我仍然專心跟從耶和華－我的神。","notes":[]},{"n":9,"t":"那日，摩西起誓說：『你腳所踏之地必要歸你和你的子孫永遠為業，因為你專心跟從耶和華－我的神。』","notes":[]},{"n":10,"t":"現在，看哪，耶和華照他所說的使我活了這四十五年。當以色列人在曠野飄流的時候，耶和華曾對摩西說了這話。現在，看哪，我已經八十五歲了。","notes":[]},{"n":11,"t":"現今我還很健壯，像摩西差派我去的那天一樣；無論是戰爭，是出入，我現在的力量和那時的力量一樣。","notes":[]},{"n":12,"t":"請你將耶和華那日所說的這山區給我。那日你也曾聽說，這裏有亞衲族人，以及寬大堅固的城，或許耶和華會照他所說的與我同在，我就把他們趕出去。」","notes":[]},{"n":13,"t":"於是約書亞為耶孚尼的兒子迦勒祝福，把希伯崙給他為業。","notes":[]},{"n":14,"t":"所以希伯崙成了基尼洗族耶孚尼的兒子迦勒的產業，直到今日，因為他專心跟從耶和華－以色列的神。","notes":[]},{"n":15,"t":"希伯崙從前名叫基列‧亞巴；亞巴是亞衲族最尊貴的人。於是國中太平，沒有戰爭了。","notes":["「亞巴」：原文是「他」，「亞巴」是人名。"]}]},"15":{"heading":"分給猶大的土地","verses":[{"n":1,"t":"猶大支派按著宗族抽籤所得之地是在最南端，到以東的邊界，往南直到尋的曠野。","notes":[]},{"n":2,"t":"他們南邊的地界是從鹽海的頂端，就是朝南的海灣開始，","notes":[]},{"n":3,"t":"通到亞克拉濱斜坡的南邊，經過尋，上到加低斯‧巴尼亞的南邊，又經過希斯崙，上到亞達珥，轉到甲加，","notes":[]},{"n":4,"t":"再經過押們，順著埃及溪谷，這地界直通到海為止。這就是你們南邊的地界。","notes":["「你們」：七十士譯本是「他們」。"]},{"n":5,"t":"東邊的地界是從鹽海到約旦河口。北邊的地界是從約旦河口的海灣開始，","notes":[]},{"n":6,"t":"這地界上到伯‧曷拉，經過伯‧亞拉巴的北邊，這地界上到呂便之子波罕的磐石。","notes":[]},{"n":7,"t":"這地界是從亞割谷往北上到底璧，直向亞都冥斜坡對面的吉甲，就是河的南邊，這地界再經過隱‧示麥泉，直通到隱‧羅結。","notes":[]},{"n":8,"t":"這地界又上到欣嫩子谷，耶布斯斜坡的南方，耶布斯就是耶路撒冷，這地界又上到欣嫩谷西邊對面的山頂，就是在利乏音谷的最北端。","notes":[]},{"n":9,"t":"這地界又從山頂延伸到尼弗多亞水泉，通到以弗崙山的城鎮，這地界又延伸到巴拉，巴拉就是基列‧耶琳。","notes":[]},{"n":10,"t":"這地界又從巴拉往西繞到西珥山，經過耶琳山斜坡的北邊，耶琳就是基撒崙，從那裏又下到伯‧示麥，經過亭拿，","notes":[]},{"n":11,"t":"這地界通到以革倫斜坡的北邊。這地界又延伸到施基崙，經過巴拉山到雅比聶，這地界直通到海為止。","notes":[]},{"n":12,"t":"西邊的地界就是大海和沿海一帶之地。這是猶大人按著宗族所得之地四圍的邊界。","notes":[]},{"n":13,"t":"約書亞照耶和華所指示的，把猶大人中的一份土地，就是基列‧亞巴，分給耶孚尼的兒子迦勒。亞巴是亞衲族的祖先，基列‧亞巴就是希伯崙。","notes":[],"heads":["迦勒攻佔的土地"]},{"n":14,"t":"迦勒從那裏趕出亞衲的三族，就是亞衲族的示篩人、亞希幔人和撻買人。","notes":[]},{"n":15,"t":"他又從那裏上去，攻擊底璧的居民，這底璧從前名叫基列‧西弗。","notes":[]},{"n":16,"t":"迦勒說：「誰能攻打基列‧西弗，奪取那城，我就把我女兒押撒嫁給他。」","notes":[]},{"n":17,"t":"迦勒兄弟基納斯的兒子俄陀聶奪取了那城，迦勒就把女兒押撒嫁給他。","notes":[]},{"n":18,"t":"押撒來的時候，催促丈夫向她父親要一塊田。押撒一下驢，迦勒就對她說：「你要甚麼？」","notes":[]},{"n":19,"t":"她說：「求你給我福分；你既然把我安置在尼革夫地，求你也給我水泉。」她父親就把上泉和下泉都賜給她。","notes":[]},{"n":20,"t":"這是猶大支派按著宗族所得的產業。","notes":[],"heads":["猶大分得的城鎮"]},{"n":21,"t":"猶大支派最南端，靠近以東邊界的城鎮，是甲薛、以得、雅姑珥、","notes":[]},{"n":22,"t":"基拿、底摩拿、亞大達、","notes":[]},{"n":23,"t":"基低斯、夏瑣、以提楠、","notes":[]},{"n":24,"t":"西弗、提鍊、比亞綠、","notes":[]},{"n":25,"t":"夏瑣‧哈大他、加略‧希斯崙，加略‧希斯崙就是夏瑣，","notes":[]},{"n":26,"t":"亞曼、示瑪、摩拉大、","notes":[]},{"n":27,"t":"哈薩‧迦大、黑實門、伯‧帕列、","notes":[]},{"n":28,"t":"哈薩‧書亞、別是巴、比斯約他、","notes":[]},{"n":29,"t":"巴拉、以因、以森、","notes":[]},{"n":30,"t":"伊勒多臘、基失、何珥瑪、","notes":[]},{"n":31,"t":"洗革拉、麥瑪拿、三撒拿、","notes":[]},{"n":32,"t":"利巴勿、實忻、亞因、臨門，共二十九座城，還有所屬的村莊。","notes":[]},{"n":33,"t":"在低地有以實陶、瑣拉、亞實拿、","notes":[]},{"n":34,"t":"撒挪亞、隱‧干寧、他普亞、以楠、","notes":[]},{"n":35,"t":"耶末、亞杜蘭、梭哥、亞西加、","notes":[]},{"n":36,"t":"沙拉音、亞底他音、基底拉、基底羅他音，共十四座城，還有所屬的村莊。","notes":[]},{"n":37,"t":"又有洗楠、哈大沙、麥大‧迦得、","notes":[]},{"n":38,"t":"底連、米斯巴、約帖、","notes":[]},{"n":39,"t":"拉吉、波斯加、伊磯倫、","notes":[]},{"n":40,"t":"迦本、拉幔、基提利、","notes":[]},{"n":41,"t":"基低羅、伯‧大袞、拿瑪、瑪基大，共十六座城，還有所屬的村莊。","notes":[]},{"n":42,"t":"又有立拿、以帖、亞珊、","notes":[]},{"n":43,"t":"益弗他、亞實拿、尼悉、","notes":[]},{"n":44,"t":"基伊拉、亞革悉、瑪利沙，共九座城，還有所屬的村莊。","notes":[]},{"n":45,"t":"又有以革倫和所屬的鄉鎮與村莊，","notes":["「鄉鎮」：原文直譯「女子們」；本卷書下同。"]},{"n":46,"t":"從以革倫直到海，一切靠近亞實突之地，以及所屬的村莊、","notes":[]},{"n":47,"t":"亞實突和所屬的鄉鎮與村莊，迦薩和所屬的鄉鎮與村莊，到埃及溪谷，直到大海以及沿海一帶之地。","notes":[]},{"n":48,"t":"在山區有沙密、雅提珥、梭哥、","notes":[]},{"n":49,"t":"大拿、基列‧薩拿，基列‧薩拿就是底璧，","notes":[]},{"n":50,"t":"亞拿伯、以實提莫、亞念、","notes":[]},{"n":51,"t":"歌珊、何崙、基羅，共十一座城，還有所屬的村莊。","notes":[]},{"n":52,"t":"又有亞拉、度瑪、以珊、","notes":[]},{"n":53,"t":"雅農、伯‧他普亞、亞非加、","notes":[]},{"n":54,"t":"宏他、基列‧亞巴，基列‧亞巴就是希伯崙，洗珥，共九座城，還有所屬的村莊。","notes":[]},{"n":55,"t":"又有瑪雲、迦密、西弗、淤他、","notes":[]},{"n":56,"t":"耶斯列、約甸、撒挪亞、","notes":[]},{"n":57,"t":"該隱、基比亞、亭拿，共十座城，還有所屬的村莊。","notes":[]},{"n":58,"t":"又有哈忽、伯‧夙、基突、","notes":[]},{"n":59,"t":"瑪臘、伯‧亞諾、伊勒提君，共六座城，還有所屬的村莊。","notes":[]},{"n":60,"t":"又有基列‧巴力，基列‧巴力就是基列‧耶琳，拉巴，共兩座城，還有所屬的村莊。","notes":[]},{"n":61,"t":"在曠野有伯‧亞拉巴、密丁、西迦迦、","notes":[]},{"n":62,"t":"匿珊、鹽城、隱‧基底，共六座城，還有所屬的村莊。","notes":[]},{"n":63,"t":"至於住耶路撒冷的耶布斯人，猶大人不能把他們趕出去。於是，耶布斯人與猶大人同住在耶路撒冷，直到今日。","notes":[]}]},"16":{"heading":"分給約瑟子孫的土地","verses":[{"n":1,"t":"約瑟的子孫抽籤所得之地是從靠近耶利哥的約旦河起，以耶利哥東邊的河水為邊界，經過曠野，從耶利哥上去，直到伯特利的山區；","notes":[]},{"n":2,"t":"從伯特利又到路斯，經過亞基人的邊界，直到亞大錄；","notes":[]},{"n":3,"t":"又往西，下到押利提人的邊界，到下伯‧和崙的邊界，到基色，直通到海為止。","notes":[]},{"n":4,"t":"約瑟的兒子瑪拿西、以法蓮得了地業。","notes":[]},{"n":5,"t":"以法蓮子孫的地界，按著宗族所得的如下：他們地業的東界，是從亞大錄‧亞達到上伯‧和崙，","notes":[],"heads":["分給以法蓮的土地"]},{"n":6,"t":"這地界直通到海。在北邊，這地界是從密米他，向東繞到他納‧示羅，又經過雅挪哈的東邊，","notes":[]},{"n":7,"t":"從雅挪哈下到亞大錄和拿拉，再到耶利哥，直到約旦河為止。","notes":[]},{"n":8,"t":"這地界又從他普亞，順著加拿河往西延伸，直通到海為止。這就是以法蓮支派按著宗族所得的地業。","notes":[]},{"n":9,"t":"在瑪拿西人地業的一切城鎮和所屬的村莊中，也保留一些城鎮給以法蓮的子孫。","notes":[]},{"n":10,"t":"他們卻沒有趕出住在基色的迦南人。迦南人就住在以法蓮人中，成為服勞役的僕人，直到今日。","notes":[]}]},"17":{"heading":"分給西瑪拿西半支派的土地","verses":[{"n":1,"t":"瑪拿西是約瑟的長子，這是他的支派抽籤所得之地。瑪拿西的長子，基列的父親瑪吉，因為是勇士，就得了基列和巴珊。","notes":[]},{"n":2,"t":"瑪拿西其餘的子孫，就是亞比以謝的子孫，希勒的子孫，亞斯烈的子孫，示劍的子孫，希弗的子孫，示米大的子孫，都按著宗族抽籤得了地。這都是約瑟的兒子瑪拿西子孫中各宗族的男丁。","notes":[]},{"n":3,"t":"瑪拿西的玄孫，瑪吉的曾孫，基列的孫子，希弗的兒子西羅非哈沒有兒子，只有女兒。他的女兒名叫瑪拉、挪阿、曷拉、密迦、得撒。","notes":[]},{"n":4,"t":"她們來到以利亞撒祭司和嫩的兒子約書亞以及眾領袖面前，說：「耶和華曾吩咐摩西在我們兄弟中分產業給我們。」於是約書亞照耶和華的指示，在她們叔伯中，把產業分給她們。","notes":[]},{"n":5,"t":"除了約旦河東的基列和巴珊地之外，還有十份的地業是屬於瑪拿西的，","notes":[]},{"n":6,"t":"因為瑪拿西支派的女子也在男子中分得產業。基列地屬於瑪拿西其餘的子孫。","notes":[]},{"n":7,"t":"瑪拿西的地界是從亞設起，到示劍前面的密米他，往右到隱‧他普亞居民之地。","notes":["「往右」或譯「往南」。"]},{"n":8,"t":"他普亞地歸於瑪拿西，只是瑪拿西邊界的他普亞城卻歸於以法蓮子孫。","notes":[]},{"n":9,"t":"這地界從那裏下到加拿河。河南邊的城鎮雖然在瑪拿西境內，卻是屬於以法蓮的。瑪拿西的地界是在河的北邊直通到海為止。","notes":[]},{"n":10,"t":"南邊屬於以法蓮，北邊屬於瑪拿西，以海為界；北邊達到亞設，東邊達到以薩迦。","notes":[]},{"n":11,"t":"瑪拿西在以薩迦和亞設境內，有伯‧善和所屬的鄉鎮，以伯蓮和所屬的鄉鎮，多珥和所屬鄉鎮的居民；還有隱‧多珥和所屬鄉鎮的居民，他納和所屬鄉鎮的居民，米吉多和所屬鄉鎮的居民，共三個山岡。","notes":["「共三個山岡」：原文另譯「第三個是山岡」。"]},{"n":12,"t":"只是瑪拿西的子孫不能趕出這些城鎮的居民，迦南人仍堅持住在那地。","notes":[]},{"n":13,"t":"以色列人強盛的時候，就叫迦南人做苦工，沒有把他們全然趕走。","notes":[]},{"n":14,"t":"約瑟的子孫對約書亞說：「耶和華到如今這樣賜福給我，我百姓眾多，你為甚麼只給我抽一籤，分一份的土地為業呢？」","notes":[],"heads":["約瑟的子孫要求更多土地"]},{"n":15,"t":"約書亞對他們說：「如果你百姓眾多，而以法蓮山區太窄小，那麼你可以上比利洗人和利乏音人之地的樹林中，在那裏開墾。」","notes":[]},{"n":16,"t":"約瑟的子孫說：「那山區容不下我們，而且住平原的迦南人，就是住伯‧善和所屬的鄉鎮，以及住在耶斯列平原的人，都有鐵的戰車。」","notes":[]},{"n":17,"t":"約書亞對約瑟家，就是以法蓮和瑪拿西人，說：「你百姓眾多，並且強大，不可只有一籤而已。","notes":[]},{"n":18,"t":"那山區也要歸你，雖然是樹林，你可以去開墾，邊緣之地也必歸你。迦南人縱然強盛，有鐵的戰車，你也能把他們趕出去。」","notes":[]}]},"18":{"heading":"其餘支派的土地分配","verses":[{"n":1,"t":"以色列全會眾都聚集在示羅，把會幕設立在那裏。那地已經被他們征服了。","notes":[]},{"n":2,"t":"以色列人中剩下七個支派還沒有分得他們的地業。","notes":[]},{"n":3,"t":"約書亞對以色列人說：「耶和華－你們列祖的神所賜給你們的地，你們耽延不去得，要到幾時呢？","notes":[]},{"n":4,"t":"你們每支派要選三個人，我好派他們去，他們要起身走遍那地，按照各支派應得的地業寫明，然後回到我這裏來。","notes":[]},{"n":5,"t":"他們要把地分成七份。猶大在南方，住在他的境內。約瑟家在北方，住在他們的境內。","notes":[]},{"n":6,"t":"你們把地劃成七份之後，就要把所寫的帶到我這裏來。我要在耶和華－我們的神面前，為你們抽籤。","notes":[]},{"n":7,"t":"利未人在你們中間沒有分得地業，因為耶和華祭司的職分就是他們的產業。迦得支派、呂便支派和瑪拿西半支派已經在約旦河東得了地業，是耶和華的僕人摩西給他們的。」","notes":[]},{"n":8,"t":"那些去劃地的人起來正要去的時候，約書亞吩咐他們說：「你們去走遍那地，把地劃分以後，就回到我這裏來。我要在示羅這裏，在耶和華面前為你們抽籤。」","notes":[]},{"n":9,"t":"那些人就去了，走遍那地，按照城鎮把地劃成七份，寫在冊上，回到示羅營中約書亞那裏。","notes":["「回到」：七十士譯本是「帶回到」。"]},{"n":10,"t":"約書亞就在示羅，在耶和華面前為他們抽籤。約書亞按照以色列人的支派，在那裏把地分給他們。","notes":[]},{"n":11,"t":"便雅憫支派，按著宗族抽籤所得之地，是在猶大子孫和約瑟子孫之間。","notes":[],"heads":["分給便雅憫的土地"]},{"n":12,"t":"他們北邊的地界是從約旦河起，上到耶利哥斜坡的北邊，再往西上到山區，直到伯‧亞文的曠野。","notes":[]},{"n":13,"t":"這地界從那裏往南經過路斯，直到路斯的斜坡，路斯就是伯特利，又下到亞他錄‧亞達，直到下伯‧和崙南邊的山。","notes":[]},{"n":14,"t":"這地界往西延伸，又轉向南，從伯‧和崙南邊對面的山，直通到猶大人的城基列‧巴力，基列‧巴力就是基列‧耶琳。這就是西邊的地界。","notes":[]},{"n":15,"t":"南邊是從基列‧耶琳的頂端為起點，這地界往西通到尼弗多亞水泉，","notes":["「這地界往西」：七十士譯本是「這地界向迦薩」。"]},{"n":16,"t":"這地界又下到欣嫩子谷對面山的邊緣，就是利乏音谷的北邊；又下到欣嫩谷，沿著耶布斯斜坡的南邊，下到隱‧羅結；","notes":[]},{"n":17,"t":"又往北轉彎，通到隱‧示麥，直到亞都冥斜坡對面的基利綠，又下到呂便之子波罕的磐石，","notes":[]},{"n":18,"t":"又往北經過亞拉巴對面的斜坡，下到亞拉巴。","notes":["「亞拉巴對面的斜坡」：七十士譯本是「伯‧亞拉巴的斜坡」。"]},{"n":19,"t":"這地界又經過伯‧曷拉斜坡的北邊，直通到鹽海的北灣，就是約旦河的南端為止。這就是南邊的地界。","notes":[]},{"n":20,"t":"東邊的地界是約旦河。這是便雅憫人按著宗族，照著他們四圍的邊界所得的地業。","notes":[]},{"n":21,"t":"便雅憫支派按著宗族所得的城鎮就是：耶利哥、伯‧曷拉、伊麥‧基悉、","notes":[],"heads":["便雅憫分得的城鎮"]},{"n":22,"t":"伯‧亞拉巴、洗瑪臉、伯特利、","notes":[]},{"n":23,"t":"亞文、巴拉、俄弗拉、","notes":[]},{"n":24,"t":"基法‧阿摩尼、俄弗尼和迦巴，共十二座城，以及所屬的村莊；","notes":[]},{"n":25,"t":"又有基遍、拉瑪、比錄、","notes":[]},{"n":26,"t":"米斯巴、基非拉、摩撒、","notes":[]},{"n":27,"t":"利堅、伊利毗勒、他拉拉、","notes":[]},{"n":28,"t":"洗拉、以利弗、耶布斯，耶布斯就是耶路撒冷，基比亞、基列，共十四座城，以及所屬的村莊。這是便雅憫人按著宗族所得的地業。","notes":[]}]},"19":{"heading":"分給西緬的土地","verses":[{"n":1,"t":"第二籤是西緬，是西緬支派的人按著宗族抽出的，他們所得的地業是在猶大人地業的中間。","notes":[]},{"n":2,"t":"他們所得為業之地是：別是巴，或名示巴，摩拉大、","notes":[]},{"n":3,"t":"哈薩‧書亞、巴拉、以森、","notes":[]},{"n":4,"t":"伊勒多臘、比土力、何珥瑪、","notes":[]},{"n":5,"t":"洗革拉、伯‧瑪加博、哈薩‧蘇撒、","notes":[]},{"n":6,"t":"伯‧利巴勿、沙魯險，共十三座城，還有所屬的村莊；","notes":[]},{"n":7,"t":"又有亞因、利門、以帖、亞珊，共四座城，還有所屬的村莊；","notes":[]},{"n":8,"t":"以及這些城鎮周圍一切的村莊，直到巴拉‧比珥，就是尼革夫的拉瑪。這是西緬支派的人按著宗族所得的地業。","notes":[]},{"n":9,"t":"西緬人的地業取自猶大人的土地，因為猶大人所得的份過多，所以西緬人從猶大人的地業中取了地業。","notes":[]},{"n":10,"t":"第三籤是西布倫人按著宗族抽到的。他們地業的邊界延伸到撒立。","notes":[],"heads":["分給西布倫的土地"]},{"n":11,"t":"他們的地界往西，上到瑪拉拉，達到大巴設，又達到約念前面的河。","notes":[]},{"n":12,"t":"又從撒立往東轉到向日出的方向，經過吉斯綠‧他泊的邊界，到大比拉，又上到雅非亞。","notes":[]},{"n":13,"t":"又從那裏往東，經過迦特‧希弗，到以特‧加汛，通到臨門，延伸到尼亞。","notes":[]},{"n":14,"t":"這地界在北邊繞過尼亞，到哈拿頓，直通到伊弗他‧伊勒谷，","notes":[]},{"n":15,"t":"包括加他、拿哈拉、伸崙、以大拉、伯利恆，共十二座城，還有所屬的村莊。","notes":[]},{"n":16,"t":"這些城鎮和所屬的村莊是西布倫人按著宗族所得的地業。","notes":[]},{"n":17,"t":"第四籤是以薩迦，是以薩迦人按著宗族抽出的。","notes":[],"heads":["分給以薩迦的土地"]},{"n":18,"t":"他們的地界是到耶斯列、基蘇律、書念、","notes":[]},{"n":19,"t":"哈弗連、示按、亞拿哈拉、","notes":[]},{"n":20,"t":"拉璧、基善、亞別、","notes":[]},{"n":21,"t":"利篾、隱‧干寧、隱‧哈大、伯‧帕薛。","notes":[]},{"n":22,"t":"這地界達到他泊、沙哈洗瑪、伯‧示麥，他們的地界直通到約旦河為止，共十六座城，還有所屬的村莊。","notes":[]},{"n":23,"t":"這些城鎮和所屬的村莊是以薩迦支派的人按著宗族所得的地業。","notes":[]},{"n":24,"t":"第五籤是亞設支派的人按著宗族抽出的。","notes":[],"heads":["分給亞設的土地"]},{"n":25,"t":"他們的地界是黑甲、哈利、比田、押煞、","notes":[]},{"n":26,"t":"亞拉米勒、亞末、米沙勒，往西達到迦密，又到希曷‧立納，","notes":[]},{"n":27,"t":"又轉到向日出方向的伯‧大袞，達到細步綸；又往北到伊弗他‧伊勒谷，到伯‧以墨和尼業，也通到迦步勒的左邊，","notes":["「左邊」或譯「北邊」。"]},{"n":28,"t":"又到義伯崙、利合、哈們、加拿，直到西頓大城。","notes":[]},{"n":29,"t":"這地界轉到拉瑪，直到堅固的推羅城。這地界又轉到何薩，靠近亞革悉一帶的地方，直通到海為止。","notes":["「靠近亞革悉一帶的地方」：原文另譯「亞革悉、瑪哈拉」。"]},{"n":30,"t":"又有烏瑪、亞弗、利合，共二十二座城，還有所屬的村莊。","notes":[]},{"n":31,"t":"這些城鎮和所屬的村莊是亞設支派的人按著宗族所得的地業。","notes":[]},{"n":32,"t":"第六籤是拿弗他利人，是拿弗他利人按著宗族抽出的。","notes":[],"heads":["分給拿弗他利的土地"]},{"n":33,"t":"他們的地界是從希利弗，從撒拿音的橡樹、亞大米‧尼吉和雅比聶，直到拉共，直通到約旦河為止。","notes":[]},{"n":34,"t":"這地界往西轉到亞斯納‧他泊，從那裏通到戶割，南邊達到西布倫，西邊達到亞設，向日出的方向達到約旦河的猶大。","notes":[]},{"n":35,"t":"堅固的城有西丁、側耳、哈末、拉甲、基尼烈、","notes":[]},{"n":36,"t":"亞大瑪、拉瑪、夏瑣、","notes":[]},{"n":37,"t":"基低斯、以得來、隱‧夏瑣、","notes":[]},{"n":38,"t":"以利穩、密大‧伊勒、和璉、伯‧亞納、伯‧示麥，共十九座城，還有所屬的村莊。","notes":[]},{"n":39,"t":"這些城鎮和所屬的村莊是拿弗他利支派的人按著宗族所得的地業。","notes":[]},{"n":40,"t":"但支派，按著宗族，抽到第七籤。","notes":[],"heads":["分給但的土地"]},{"n":41,"t":"他們地業的邊界是瑣拉、以實陶、伊珥‧示麥、","notes":[]},{"n":42,"t":"沙拉賓、亞雅崙、伊提拉、","notes":[]},{"n":43,"t":"以倫、亭拿、以革倫、","notes":[]},{"n":44,"t":"伊利提基、基比頓、巴拉、","notes":[]},{"n":45,"t":"伊胡得、比尼‧比拉、迦特‧臨門、","notes":[]},{"n":46,"t":"美‧耶昆、拉昆，以及約帕對面的地界。","notes":[]},{"n":47,"t":"當但的子孫失去他們疆土的時候，就上去攻取利善，用刀擊殺城中的人，得了那城，住在城中，以他們祖先但的名字將利善改名為但。","notes":[]},{"n":48,"t":"這些城鎮和所屬的村莊是但支派的人按著宗族所得的地業。","notes":[]},{"n":49,"t":"以色列人按著疆土完成了地業的分配，就在他們中間把地給嫩的兒子約書亞為業。","notes":[],"heads":["給約書亞的城"]},{"n":50,"t":"他們照著耶和華的指示，把約書亞所要的城，就是以法蓮山區的亭拿‧西拉給了他。約書亞修建那城，住在城中。","notes":[]},{"n":51,"t":"這就是以利亞撒祭司和嫩的兒子約書亞，以及以色列人各支派父系的領袖，在示羅會幕的門口，耶和華面前抽籤所分的地業。這樣， 他們就完成了分地的事。","notes":[]}]},"20":{"heading":"設立逃城","verses":[{"n":1,"t":"耶和華吩咐約書亞說：","notes":[]},{"n":2,"t":"「你吩咐以色列人說：『你們要照我藉摩西所吩咐你們的，為自己設立逃城，","notes":[]},{"n":3,"t":"使那無意中誤殺人的，可以逃到那裏。這些要作為你們逃避報血仇者的城。","notes":[]},{"n":4,"t":"殺人者要逃到這些城中的一座，站在城門口，把他的事情陳訴給那城的長老聽。他們就要接他入城，給他地方，讓他住在他們中間。","notes":[]},{"n":5,"t":"若是報血仇者追上了他，長老不可把他交在報血仇者的手裏，因為他是無意中殺了鄰舍的，並非過去彼此之間有仇恨。","notes":[]},{"n":6,"t":"他要住在那城裏，直到他站在會眾面前受審判；等到當時的大祭司死後，殺人者才可以回到本城本家，就是他所逃出來的那城。』」","notes":[]},{"n":7,"t":"於是，以色列人劃分拿弗他利山區加利利的基低斯、以法蓮山區的示劍和猶大山區的基列‧亞巴，基列‧亞巴就是希伯崙。","notes":[]},{"n":8,"t":"他們在約旦河的另一邊，就是耶利哥的東邊，從呂便支派中，在曠野的平原設立比悉，從迦得支派中設立基列的拉末，從瑪拿西支派中設立巴珊的哥蘭。","notes":[]},{"n":9,"t":"這都是為以色列眾人和在他們中間寄居的外人所指定的城鎮，使凡誤殺人者可以逃到那裏，不至於死在報血仇者的手中，直到他站在會眾面前受審判。","notes":["「受審判」是根據七十士譯本，原文沒有。"]}]},"21":{"heading":"利未人的城","verses":[{"n":1,"t":"利未人的眾族長近前來到以利亞撒祭司和嫩的兒子約書亞，以及以色列人各支派父系的領袖那裏，","notes":[]},{"n":2,"t":"在迦南地的示羅對他們說：「從前耶和華曾藉著摩西吩咐給我們城鎮居住，以及城鎮的郊外供我們牧養牲畜。」","notes":[]},{"n":3,"t":"於是以色列人照耶和華的指示，從自己的地業中，把這些城鎮和城鎮的郊外給了利未人。","notes":[]},{"n":4,"t":"哥轄族抽了籤。利未人中亞倫祭司的子孫，從猶大支派、西緬支派、便雅憫支派的地業中，抽籤得了十三座城。","notes":[]},{"n":5,"t":"哥轄其餘的子孫，從以法蓮支派、但支派、瑪拿西半支派宗族的地業中，抽籤得了十座城。","notes":[]},{"n":6,"t":"革順的子孫，從以薩迦支派、亞設支派、拿弗他利支派、住巴珊的瑪拿西半支派宗族的地業中，抽籤得了十三座城。","notes":[]},{"n":7,"t":"米拉利的子孫，按著宗族，從呂便支派、迦得支派、西布倫支派的地業中，得了十二座城。","notes":[]},{"n":8,"t":"以色列人照耶和華藉摩西所吩咐的，把這些城鎮和城鎮的郊外，抽籤給利未人。","notes":[]},{"n":9,"t":"他們從猶大支派和西緬支派的地業中，給了以下所記名字的各城，","notes":[]},{"n":10,"t":"就是給利未人哥轄宗族的亞倫子孫，因為他們抽到第一籤：","notes":[]},{"n":11,"t":"把猶大山區的基列‧亞巴，就是希伯崙，和四圍的郊野給了他們。亞巴是亞衲族的祖先。","notes":[]},{"n":12,"t":"但是，這城的田地和所屬的村莊卻給了耶孚尼的兒子迦勒為業。","notes":[]},{"n":13,"t":"他們把希伯崙，就是誤殺人的逃城和城的郊外，給了亞倫祭司的子孫；又給了立拿和城的郊外、","notes":[]},{"n":14,"t":"雅提珥和城的郊外、以實提莫和城的郊外、","notes":[]},{"n":15,"t":"何崙和城的郊外、底璧和城的郊外、","notes":[]},{"n":16,"t":"亞因和城的郊外、淤他和城的郊外，以及伯‧示麥和城的郊外，共九座城，都是從這二支派中分出來的。","notes":[]},{"n":17,"t":"又從便雅憫支派的地業中給了基遍和城的郊外、迦巴和城的郊外、","notes":[]},{"n":18,"t":"亞拿突和城的郊外，以及亞勒們和城的郊外，共四座城。","notes":[]},{"n":19,"t":"亞倫子孫作祭司的共有十三座城，以及城的郊外。","notes":[]},{"n":20,"t":"利未人哥轄的宗族，就是哥轄其餘的子孫，抽籤所得的城是從以法蓮支派來的。","notes":[]},{"n":21,"t":"他們把以法蓮山區的示劍，就是誤殺人的逃城和城的郊外給了哥轄其餘的子孫；又給了基色和城的郊外、","notes":[]},{"n":22,"t":"基伯先和城的郊外，以及伯‧和崙和城的郊外，共四座城。","notes":[]},{"n":23,"t":"又從但支派的地業中給了伊利提基和城的郊外、基比頓和城的郊外、","notes":[]},{"n":24,"t":"亞雅崙和城的郊外，以及迦特‧臨門和城的郊外，共四座城。","notes":[]},{"n":25,"t":"又從瑪拿西半支派的地業中給了他納和城的郊外，以及迦特‧臨門和城的郊外，共兩座城。","notes":[]},{"n":26,"t":"哥轄其餘的子孫共有十座城，以及城的郊外。","notes":[]},{"n":27,"t":"利未人宗族中革順的子孫，從瑪拿西半支派的地業中所得的是巴珊的哥蘭，就是誤殺人的逃城和城的郊外，以及比‧施提拉和城的郊外，共兩座城。","notes":[]},{"n":28,"t":"從以薩迦支派的地業中所得的是基善和城的郊外、大比拉和城的郊外、","notes":[]},{"n":29,"t":"耶末和城的郊外，以及隱‧干寧和城的郊外，共四座城。","notes":[]},{"n":30,"t":"從亞設支派的地業中所得的是米沙勒和城的郊外、押頓和城的郊外、","notes":[]},{"n":31,"t":"黑甲和城的郊外，以及利合和城的郊外，共四座城。","notes":[]},{"n":32,"t":"從拿弗他利支派的地業中所得的是加利利的基低斯，就是誤殺人的逃城和城的郊外、哈末‧多珥和城的郊外，以及加珥坦和城的郊外，共三座城。","notes":[]},{"n":33,"t":"革順人按著宗族共有十三個城，以及城的郊外。","notes":[]},{"n":34,"t":"其餘的利未人，就是米拉利的子孫，按著宗族從西布倫支派的地業中所得的是約念和城的郊外、加珥他和城的郊外、","notes":[]},{"n":35,"t":"丁拿和城的郊外，以及拿哈拉和城的郊外，共四座城。","notes":[]},{"n":36,"t":"從呂便支派的地業中所得的是比悉和城的郊外、雅雜和城的郊外、","notes":[]},{"n":37,"t":"基底莫和城的郊外，以及米法押和城的郊外，共四座城。","notes":[]},{"n":38,"t":"從迦得支派的地業中所得的是基列的拉末，就是誤殺人的逃城和城的郊外、瑪哈念和城的郊外、","notes":[]},{"n":39,"t":"希實本和城的郊外，以及雅謝和城的郊外，共四座城。","notes":[]},{"n":40,"t":"利未宗族其餘的人，就是米拉利的子孫，按著宗族抽籤所得的，共十二座城。","notes":[]},{"n":41,"t":"利未人在以色列人的地業中所得的城，共四十八個，還有城的郊外。","notes":[]},{"n":42,"t":"這些城的四圍都有郊野，每個城都是如此。","notes":[]},{"n":43,"t":"這樣，耶和華將從前向他們列祖起誓要給他們的全地賜給以色列人，他們就得了為業，住在其中。","notes":[],"heads":["以色列人得地為業"]},{"n":44,"t":"耶和華照著向他們列祖起誓所應許的一切，賜給他們全境安寧。他們所有的仇敵，沒有一個能在他們面前站立得住。耶和華把所有仇敵都交在他們手中。","notes":[]},{"n":45,"t":"耶和華應許賜福給以色列家的話，一句都沒有落空，全都應驗了。","notes":[]}]},"22":{"heading":"東岸的支派回去","verses":[{"n":1,"t":"此後，約書亞召了呂便人、迦得人和瑪拿西半支派的人來，","notes":[]},{"n":2,"t":"對他們說：「耶和華的僕人摩西所吩咐你們的，你們都遵守了；我吩咐你們的話，你們也都聽從了。","notes":[]},{"n":3,"t":"你們這許多日子，都沒有撇棄你們的弟兄，直到今日，並且遵守了耶和華你們神所吩咐的命令。","notes":[]},{"n":4,"t":"如今耶和華－你們的神已經照著他所應許的，使你們的弟兄得享安寧。你們現在可以返回自己的帳棚，回到耶和華的僕人摩西在約旦河東所賜給你們為業之地。","notes":[]},{"n":5,"t":"只是務要謹守遵行耶和華的僕人摩西所吩咐你們的誡命和律法，愛耶和華－你們的神，行他一切的道，守他的誡命，緊緊跟隨他，盡心盡性事奉他。」","notes":[]},{"n":6,"t":"於是約書亞為他們祝福，送他們回去，他們就回到自己的帳棚去了。","notes":[]},{"n":7,"t":"摩西在巴珊曾把地業分給瑪拿西的半支派；然後約書亞在約旦河的西岸，在他們弟兄中，又把地業分給瑪拿西的另外半支派。約書亞送他們回帳棚的時候，為他們祝福，","notes":[]},{"n":8,"t":"對他們說：「你們要把許多財物，許多牲畜，和金、銀、銅、鐵，以及許多衣服，帶回你們的帳棚去，要把你們從仇敵奪來的東西分給你們的眾弟兄。」","notes":[]},{"n":9,"t":"於是呂便人、迦得人、瑪拿西半支派的人從迦南地的示羅起行，離開以色列人，回到他們已得為業的基列地，就是他們照耶和華藉摩西所吩咐而得的。","notes":[]},{"n":10,"t":"呂便人、迦得人和瑪拿西半支派的人到了迦南地的約旦河一帶地方，就在約旦河那裏築了一座壇，一座高大壯觀的壇。","notes":[],"heads":["約旦河旁的祭壇"]},{"n":11,"t":"以色列人聽見了，說：「看哪，呂便人、迦得人、瑪拿西半支派的人在迦南地對面，約旦河一帶地方，以色列人的境內，築了一座壇。」","notes":[]},{"n":12,"t":"以色列人一聽見，全會眾的以色列人就聚集在示羅，要上去攻打他們。","notes":[]},{"n":13,"t":"以色列人派以利亞撒祭司的兒子非尼哈，往基列地，到呂便人、迦得人和瑪拿西半支派的人那裏。","notes":[]},{"n":14,"t":"和他同去的還有十個領袖，以色列每個支派在父家中各派一個領袖，這些人每一個在以色列族系中都是父家的領袖。","notes":[]},{"n":15,"t":"他們來到基列地，到呂便人、迦得人和瑪拿西半支派的人那裏，對他們說：","notes":[]},{"n":16,"t":"「耶和華全會眾這樣說：『你們今日離棄耶和華不跟從他，干犯以色列的神，悖逆耶和華，為自己築了一座壇，你們所犯的是何等的罪！","notes":[]},{"n":17,"t":"從前我們在毗珥犯的罪孽，導致瘟疫臨到耶和華的會眾，甚至到今日都還沒有洗淨，這還算小事嗎？","notes":[]},{"n":18,"t":"你們今日竟然離棄耶和華不跟從他！你們今日既然悖逆耶和華，明日他必向以色列全會眾發怒。","notes":[]},{"n":19,"t":"若你們認為所得為業之地不潔淨，可以過來，到耶和華之地，就是耶和華的帳幕所居住之地，在我們中間得地業。你們卻不可悖逆耶和華，也不可背叛我們，在耶和華－我們神的壇以外為自己築壇。","notes":[]},{"n":20,"t":"從前謝拉的曾孫亞干豈不是在那當滅的物上犯了罪，導致憤怒臨到以色列全會眾嗎？死在他所犯的罪中的，不只是他一個人而已！』」","notes":[]},{"n":21,"t":"於是呂便人、迦得人、瑪拿西半支派的人回答以色列族系的領袖，說：","notes":[]},{"n":22,"t":"「大能者神耶和華！大能者神耶和華！他已知道，願以色列人也知道，我們若有悖逆的行為，或是干犯耶和華，你今日就不要讓我們活著！","notes":[]},{"n":23,"t":"若我們為自己築壇，離棄耶和華不跟從他，或將燔祭、素祭、平安祭獻在壇上，願耶和華親自追究。","notes":[]},{"n":24,"t":"不是這樣！我們做這事的原因是懼怕將來你們的子孫對我們的子孫說：『你們與耶和華－以色列的神有甚麼關係呢？","notes":[]},{"n":25,"t":"因為耶和華以約旦河作我們和你們呂便人、迦得人的交界，所以你們在耶和華裏無份。』這樣，你們的子孫就使我們的子孫不再敬畏耶和華了。","notes":[]},{"n":26,"t":"因此我們說：『不如為自己築一座壇，不是為獻燔祭，也不是為獻別樣的祭，","notes":[]},{"n":27,"t":"而是為你我之間和後代子孫之間作證據，好使我們也在耶和華面前獻我們的燔祭、平安祭和別樣的祭來事奉他，免得你們的子孫將來對我們的子孫說，你們在耶和華裏無份。』","notes":[]},{"n":28,"t":"所以我們說：『將來他們若對我們，或對我們的子孫這樣說，我們就可以回答說：你們看，我們列祖所築的壇是耶和華壇的樣式，這並不是為獻燔祭，也不是為獻別樣的祭，而是作為你們和我們之間的證據。』","notes":[]},{"n":29,"t":"除了耶和華－我們神帳幕前的壇以外，我們絕沒有意思要為著獻燔祭、素祭和別樣的祭而另外築一座壇，悖逆耶和華，今日離棄不跟從他。」","notes":[]},{"n":30,"t":"非尼哈祭司與會眾中的領袖，就是與他同來那些以色列族系的領袖，聽見呂便人、迦得人、瑪拿西人所說的話，就都看為美。","notes":[]},{"n":31,"t":"以利亞撒祭司的兒子非尼哈對呂便人、迦得人、瑪拿西人說：「今日我們知道耶和華在我們中間，因為你們沒有向他犯悖逆的罪。現在你們把以色列人從耶和華的手中救出來了。」","notes":[]},{"n":32,"t":"以利亞撒祭司的兒子非尼哈與眾領袖離開了呂便人和迦得人，從基列地回迦南地，到了以色列人那裏，就把這事向他們回報。","notes":[]},{"n":33,"t":"以色列人看這事為美；以色列人就稱頌神，不再說要上去攻打呂便人和迦得人，毀壞他們所住的地了。","notes":[]},{"n":34,"t":"呂便人和迦得人給這壇起了名，因為這壇在我們之間見證耶和華是神。","notes":[]}]},"23":{"heading":"約書亞的遺言","verses":[{"n":1,"t":"耶和華使以色列人從四圍所有的仇敵中得享安寧，已經有很多日子了。約書亞年紀老邁，","notes":[]},{"n":2,"t":"就召了全以色列的眾長老、領袖、審判官和官長來，對他們說：「我年紀已經老邁。","notes":[]},{"n":3,"t":"耶和華－你們的神因你們的緣故向這些國家所做的一切，你們都親眼看見了，那為你們作戰的是耶和華－你們的神。","notes":[]},{"n":4,"t":"看，我已經把所剩下的列國，連同從約旦河起到大海日落的方向，我所剪除的列國，都抽籤分給你們各支派為業了。","notes":[]},{"n":5,"t":"耶和華－你們的神必將他們從你們面前趕出去，使他們離開你們，你們就必得他們的地為業，正如耶和華－你們的神向你們所應許的。","notes":[]},{"n":6,"t":"你們要大大壯膽，謹守遵行寫在摩西律法書上的一切話，不可偏離左右。","notes":[]},{"n":7,"t":"不可與你們中間所剩下的這些國家往來。你們不可提他們神明的名，不可指著它們起誓，不可事奉它們，也不可敬拜它們。","notes":[]},{"n":8,"t":"只要緊緊跟隨耶和華－你們的神，就像你們直到今日所做的。","notes":[]},{"n":9,"t":"因為耶和華已經把又大又強的列國從你們面前趕出；直到今日，沒有一人能在你們面前站立得住。","notes":[]},{"n":10,"t":"你們一人必追趕千人，因為耶和華－你們的神照他向你們所應許的，為你們作戰。","notes":[]},{"n":11,"t":"你們要分外謹慎，愛耶和華－你們的神。","notes":[]},{"n":12,"t":"你們若斷然轉離，緊緊跟隨你們中間所剩下的這些國家，彼此結親，互相往來，","notes":[]},{"n":13,"t":"就要確實知道，耶和華－你們的神必不再將他們從你們面前趕出；他們卻要成為你們的羅網、圈套、肋上的鞭、眼中的刺，直到你們在耶和華－你們神所賜的這美地上滅亡。","notes":[]},{"n":14,"t":"「看哪，我今日要走世人必走的路了。你們要一心一意知道，耶和華－你們神所應許要賜給你們的一切福氣，沒有一件落空，都應驗在你們身上了。","notes":[]},{"n":15,"t":"耶和華－你們的神所應許的一切福氣怎樣臨到你們身上，耶和華也必照樣使各樣災禍臨到你們身上，直到他把你們從耶和華－你們神所賜給你們的這美地上除滅。","notes":[]},{"n":16,"t":"你們若違背耶和華－你們神吩咐你們所守的約，去事奉別神，敬拜它們，耶和華的怒氣必向你們發作，使你們在他所賜給你們的美地上迅速滅亡。」","notes":[]}]},"24":{"heading":"約書亞在示劍最後的講話","verses":[{"n":1,"t":"約書亞召集以色列的眾支派到示劍，他召了以色列的長老、領袖、審判官和官長來；他們都站在神面前。","notes":[]},{"n":2,"t":"約書亞對眾百姓說：「耶和華－以色列的神如此說：『古時你們的列祖，就是亞伯拉罕和拿鶴的父親他拉，住在大河那邊事奉別神。","notes":[]},{"n":3,"t":"我將你們的祖宗亞伯拉罕從大河那邊帶出來，領他走遍迦南全地，又使他的子孫眾多。我把以撒賜給他，","notes":[]},{"n":4,"t":"我又把雅各和以掃賜給以撒，將西珥山賜給以掃為業。但雅各和他的子孫下到埃及去了。","notes":[]},{"n":5,"t":"我差遣摩西和亞倫，照我在埃及中間所做的，降災與埃及，然後把你們領出來。","notes":[]},{"n":6,"t":"我領你們的祖宗出埃及，你們就到了紅海。埃及人帶領戰車騎兵，追趕你們的祖宗到紅海。","notes":[]},{"n":7,"t":"你們的祖宗哀求耶和華，他就用黑暗把你們和埃及人隔開了，又使海水衝向埃及人，淹沒他們。我在埃及所做的，你們都親眼見過。你們在曠野住了很多日子。","notes":[]},{"n":8,"t":"我領你們到約旦河東亞摩利人所住之地。他們與你們爭戰，我把他們交在你們手中，你們就得了他們的地為業。我也在你們面前滅絕他們。","notes":[]},{"n":9,"t":"那時，摩押王西撥的兒子巴勒起來攻擊以色列人，派人去召比珥的兒子巴蘭來詛咒你們。","notes":[]},{"n":10,"t":"但我不願聽巴蘭，所以他反而為你們連連祝福。這樣，我救了你們脫離他的手。","notes":[]},{"n":11,"t":"你們過了約旦河，來到耶利哥。耶利哥人、亞摩利人、比利洗人、迦南人、赫人、革迦撒人、希未人、耶布斯人都與你們爭戰，我卻把他們交在你們手裏。","notes":[]},{"n":12,"t":"我派遣瘟疫在你們前面，將亞摩利人的兩個王從你們面前趕出，並不是用你的刀，也不是用你的弓。","notes":["「瘟疫」或譯「黃蜂」。"]},{"n":13,"t":"我賜給你們的地，不是你們開墾的；我賜給你們的城鎮，不是你們建造的。你們卻住在其中，又得吃那不是你們栽植的葡萄園和橄欖園的果子。』","notes":[]},{"n":14,"t":"「現在你們要敬畏耶和華，誠心誠意事奉他，除掉你們列祖在大河那邊和在埃及事奉的神明，事奉耶和華。","notes":[]},{"n":15,"t":"若你們認為事奉耶和華不好，今日就可以選擇所要事奉的：是你們列祖在大河那邊所事奉的神明，或是你們所住這地亞摩利人的神明呢？至於我和我家，我們必定事奉耶和華。」","notes":[]},{"n":16,"t":"百姓回答說：「我們絕不離棄耶和華去事奉別神。","notes":[]},{"n":17,"t":"因為耶和華－我們的神曾領我們和我們的祖宗從埃及地為奴之家出來，在我們眼前行了那些大神蹟，並在我們所行的一切路上，和所經過的各民族中保護了我們。","notes":[]},{"n":18,"t":"耶和華又把各民族和住此地的亞摩利人都從我們面前趕出去。所以，我們也必事奉耶和華，因為他是我們的神。」","notes":[]},{"n":19,"t":"約書亞對百姓說：「你們不能事奉耶和華，因為他是神聖的神，是忌邪的神，必不赦免你們的過犯罪惡。","notes":["「忌邪」：原文是「妒忌」，意思是「不容許有對立的神明」。"]},{"n":20,"t":"你們若離棄耶和華去事奉外邦的神明，耶和華在降福之後，必轉而降禍給你們，把你們滅絕。」","notes":[]},{"n":21,"t":"百姓對約書亞說：「不，我們要事奉耶和華。」","notes":[]},{"n":22,"t":"約書亞對百姓說：「你們選擇耶和華，要事奉他，你們自己作證吧！」他們說：「我們願意作證。」","notes":[]},{"n":23,"t":"「現在，你們要除掉你們中間外邦的神明，專心歸向耶和華─以色列的神。」","notes":[]},{"n":24,"t":"百姓對約書亞說：「我們必事奉耶和華─我們的神，聽從他的話。」","notes":[]},{"n":25,"t":"那日，約書亞就與百姓立約，在示劍為他們制定律例典章。","notes":[]},{"n":26,"t":"約書亞把這些話寫在神的律法書上，又拿一塊大石頭立在橡樹下耶和華聖所的旁邊。","notes":[]},{"n":27,"t":"約書亞對眾百姓說：「看哪，這石頭可以向我們作見證，因為它聽見了耶和華所吩咐我們的一切話；這石頭將向你們作見證，免得你們背叛你們的神。」","notes":[]},{"n":28,"t":"於是約書亞解散百姓，各自回到自己的地業去了。","notes":[]},{"n":29,"t":"這些事以後，耶和華的僕人，嫩的兒子約書亞死了，那時他一百一十歲。","notes":[],"heads":["約書亞和以利亞撒去世"]},{"n":30,"t":"以色列人把他葬在他自己地業的境內，以法蓮山區的亭拿‧西拉，在迦實山的北邊。","notes":[]},{"n":31,"t":"約書亞在世的日子和他死了以後，那些知道耶和華為以色列所做一切事的長老還在世的時候，以色列人事奉耶和華。","notes":[]},{"n":32,"t":"以色列人把從埃及所帶來約瑟的骸骨安葬在示劍，就是雅各從前用一百可錫塔向示劍的父親哈抹的眾子所買的那塊地；這塊地就成了約瑟子孫的產業。","notes":["「可錫塔」：古希伯來錢幣單位；參「度量衡表」。"]},{"n":33,"t":"亞倫的兒子以利亞撒也死了，他們把他葬在他兒子非尼哈所得以法蓮山區的小山上。","notes":["「小山上」或譯「基比亞」。"]}]}},"JDG":{"1":{"heading":"猶大和西緬打敗亞多尼‧比色","verses":[{"n":1,"t":"約書亞死後，以色列人求問耶和華說：「我們中間誰當首先上去攻打迦南人，與他們爭戰呢？」","notes":[]},{"n":2,"t":"耶和華說：「猶大要先上去。看哪，我已將那地交在他手中。」","notes":[]},{"n":3,"t":"猶大對他哥哥西緬說：「請你同我上到我抽籤所得之地，與迦南人爭戰；我也同你去你抽籤所得之地。」於是西緬與他同去。","notes":[]},{"n":4,"t":"猶大就上去，耶和華把迦南人和比利洗人交在他們手中。他們在比色擊殺了一萬人。","notes":[]},{"n":5,"t":"他們在比色遇見亞多尼‧比色，與他爭戰，擊敗了迦南人和比利洗人。","notes":[]},{"n":6,"t":"亞多尼‧比色逃跑，他們追趕他，捉住他，砍斷他大拇指和大腳趾。","notes":[]},{"n":7,"t":"亞多尼‧比色說：「從前有七十個王，大拇指和大腳趾都被我砍斷，在我桌子底下拾取零碎食物。現在神照著我所做的報應我了。」他們把亞多尼‧比色帶到耶路撒冷，他就死在那裏。","notes":[]},{"n":8,"t":"猶大人攻打耶路撒冷，奪取了它，用刀殺城內的人，並且放火燒城。","notes":[]},{"n":9,"t":"後來猶大人下去，與住山區、尼革夫和低地的迦南人爭戰。","notes":["「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」；下同。"]},{"n":10,"t":"猶大去攻打住希伯崙的迦南人，殺了示篩、亞希幔、撻買。希伯崙從前名叫基列‧亞巴。","notes":[]},{"n":11,"t":"猶大從那裏去攻擊底壁的居民。底壁從前名叫基列‧西弗。","notes":[]},{"n":12,"t":"迦勒說：「誰能攻打基列‧西弗，奪取那城，我就把我女兒押撒嫁給他。」","notes":[]},{"n":13,"t":"迦勒的弟弟基納斯的兒子俄陀聶奪取了那城，迦勒就把女兒押撒嫁給他。","notes":[]},{"n":14,"t":"押撒來的時候，催促丈夫向她父親要一塊田。押撒一下驢，迦勒就對她說：「你要甚麼？」","notes":["「催促丈夫」：七十士譯本是「俄陀聶催促她」。"]},{"n":15,"t":"她對迦勒說：「求你賜我福分；你既然把尼革夫給了我，求你也給我水泉。」迦勒就把上泉和下泉都賜給她。","notes":[]},{"n":16,"t":"摩西的岳父是基尼人，他的子孫與猶大人一起上到棕樹城，往亞拉得以南的猶大曠野去，住在百姓當中。","notes":["「亞拉得以南的猶大曠野」：七十士譯本是「猶大南方亞拉得斜坡下的曠野」。","「在百姓當中」有古譯本是「在亞瑪力人當中」；另有古譯本是「亞瑪力人去住在他們當中」。"],"heads":["猶大和便雅憫的勝利"]},{"n":17,"t":"猶大和他哥哥西緬同去，擊殺了住洗法的迦南人，將城徹底毀滅。因此，那城名叫何珥瑪。","notes":[]},{"n":18,"t":"猶大攻取了迦薩和所屬的領土，亞實基倫和所屬的領土，以革倫和所屬的領土。","notes":[]},{"n":19,"t":"耶和華與猶大同在，猶大取得了山區，卻不能趕出平原的居民，因為他們有鐵的戰車。","notes":[]},{"n":20,"t":"以色列人照摩西所說的，把希伯崙給了迦勒。迦勒從那裏趕出亞衲的三支後裔。","notes":[]},{"n":21,"t":"至於住耶路撒冷的耶布斯人，便雅憫人沒有把他們趕出。於是，耶布斯人與便雅憫人同住在耶路撒冷，直到今日。","notes":[]},{"n":22,"t":"約瑟家也上到伯特利去，耶和華與他們同在。","notes":[],"heads":["以法蓮和瑪拿西攻取伯特利"]},{"n":23,"t":"約瑟家去窺探伯特利，那城起先名叫路斯。","notes":[]},{"n":24,"t":"探子看見一個人從城裏出來，就對他說：「請你把進城的路指示我們，我們會厚待你。」","notes":[]},{"n":25,"t":"那人把進城的路指示他們。他們就用刀擊殺了城中的居民，卻放走那人和他的全家。","notes":[]},{"n":26,"t":"那人往赫人之地去，建造了一座城，起名叫路斯。那城到如今還叫這名。","notes":[]},{"n":27,"t":"瑪拿西沒有趕出伯˙善和所屬鄉鎮的居民，他納和所屬鄉鎮的居民，多珥和所屬鄉鎮的居民，以伯蓮和所屬鄉鎮的居民，米吉多和所屬鄉鎮的居民；迦南人仍堅持住在這地。","notes":["「鄉鎮」：原文直譯「女子們」；本卷書下同。"],"heads":["以色列未趕出的民"]},{"n":28,"t":"以色列強盛的時候，就叫迦南人做苦工，沒有把他們全然趕走。","notes":[]},{"n":29,"t":"以法蓮沒有趕出住基色的迦南人。於是迦南人仍住在基色，在以法蓮中間。","notes":[]},{"n":30,"t":"西布倫沒有趕出基倫的居民和拿哈拉的居民。於是迦南人仍住在西布倫中間，成了服勞役的人。","notes":[]},{"n":31,"t":"亞設沒有趕出亞柯的居民和西頓的居民，以及亞黑拉、亞革悉、黑巴、亞弗革和利合的居民。","notes":[]},{"n":32,"t":"亞設人因為沒有趕出那地的居民迦南人，就住在他們中間。","notes":[]},{"n":33,"t":"拿弗他利沒有趕出伯˙示麥和伯˙亞納的居民。於是拿弗他利就住在那地的居民迦南人中，而伯˙示麥和伯˙亞納的居民卻成了為他們服勞役的人。","notes":[]},{"n":34,"t":"亞摩利人強逼但人住在山區，不准他們下到平原。","notes":[]},{"n":35,"t":"亞摩利人仍堅持住在希烈山、亞雅崙和沙賓；然而約瑟家權勢強盛的時候，他們成為服勞役的人。","notes":[]},{"n":36,"t":"亞摩利人的地界是從亞克拉濱斜坡，從西拉延伸而上。","notes":["「亞摩利人」：七十士譯本的一些抄本是「亞摩利人即以東人」。"]}]},"2":{"heading":"耶和華的使者在波金","verses":[{"n":1,"t":"耶和華的使者從吉甲上到波金，說：「我領你們從埃及上來，帶你們到我向你們列祖起誓應許之地。我曾說：『我永不廢棄我與你們的約。","notes":[]},{"n":2,"t":"你們不可與這地的居民立約，要拆毀他們的祭壇。』你們竟沒有聽從我的話。你們為何這樣做呢！","notes":[]},{"n":3,"t":"因此我說：『我必不將他們從你們面前趕出。他們必作你們肋下的荊棘，他們的神明必成為你們的圈套。』」","notes":["「肋下的荊棘」：原文是「肋旁」；原文另譯「敵人」。"]},{"n":4,"t":"耶和華的使者向以色列眾人說這些話的時候，百姓放聲大哭。","notes":[]},{"n":5,"t":"於是他們給那地方起名叫波金，並在那裏向耶和華獻祭。","notes":["「波金」意思是「哭」。"]},{"n":6,"t":"約書亞解散百姓，以色列人回到自己的地業，佔各自的地。","notes":[],"heads":["約書亞去世"]},{"n":7,"t":"約書亞在世的日子和他死了以後，那些見過耶和華為以色列所做一切大事的長老還在世的時候，百姓都事奉耶和華。","notes":[]},{"n":8,"t":"耶和華的僕人，嫩的兒子約書亞死了，那時他一百一十歲。","notes":[]},{"n":9,"t":"以色列人把他葬在他自己地業的境內，以法蓮山區的亭拿‧希烈，在迦實山的北邊。","notes":[]},{"n":10,"t":"那世代的人也都歸到自己的列祖。後來興起的另一世代不認識耶和華，也不知道他為以色列所做的事。","notes":[]},{"n":11,"t":"以色列人行耶和華眼中看為惡的事，去事奉諸巴力。","notes":[],"heads":["以色列離棄耶和華"]},{"n":12,"t":"他們離棄領他們出埃及地的耶和華－他們列祖的神，去隨從別神，就是四圍列國的神明，向它們叩拜，惹耶和華發怒。","notes":[]},{"n":13,"t":"他們離棄了耶和華，去事奉巴力和亞斯她錄。","notes":[]},{"n":14,"t":"耶和華的怒氣向以色列發作，把他們交在搶奪他們的人手中，又把他們交給四圍仇敵的手中，以致他們在仇敵面前再也不能站立得住。","notes":["「交給<ins>.手中」：原文是「賣給</ins>.手中」；本卷書下同。"]},{"n":15,"t":"他們無論往何處去，耶和華的手都以災禍攻擊他們，正如耶和華所說的，又如耶和華向他們所起的誓；他們就極其困苦。","notes":[]},{"n":16,"t":"耶和華興起士師，士師就拯救他們脫離搶奪他們之人的手。","notes":[]},{"n":17,"t":"然而，他們卻不聽從士師，竟隨從別神而行淫，向它們叩拜。他們列祖所行的道，所聽從耶和華的命令，他們都速速偏離了，並不照樣遵行。","notes":[]},{"n":18,"t":"耶和華為他們興起士師，耶和華與士師同在。士師在世的一切日子，耶和華拯救他們脫離仇敵的手。耶和華因他們受欺壓迫害所發出的哀聲，就憐憫他們。","notes":[]},{"n":19,"t":"但士師一死，他們又轉去行惡，比他們祖宗更壞，去隨從別神，事奉叩拜它們，總不放棄他們的惡習和頑梗的行為。","notes":[]},{"n":20,"t":"於是耶和華的怒氣向以色列發作，說：「因為這國違背我吩咐他們列祖當守的約，不聽從我的話，","notes":[]},{"n":21,"t":"約書亞死的時候所剩下的各國，我必不再從他們面前趕出任何一個，","notes":[]},{"n":22,"t":"為要藉此考驗以色列是否肯謹守遵行耶和華的道，像他們列祖一樣地謹守。」","notes":[]},{"n":23,"t":"耶和華留下那些國家，不將他們速速趕出，也不把他們交在約書亞的手中。","notes":[]}]},"3":{"heading":"留下來的國家","verses":[{"n":1,"t":"耶和華留下這些國家，為要考驗所有未曾經歷迦南任何戰役的以色列人，","notes":[]},{"n":2,"t":"只是為了要以色列人的後代認識戰爭，教導他們，尤其那些未曾認識這些事的人。","notes":[]},{"n":3,"t":"留下的有非利士的五個領袖，所有的迦南人，西頓人，以及從巴力‧黑門山到哈馬口，住黎巴嫩山的希未人。","notes":[]},{"n":4,"t":"他們是為了要考驗以色列，好知道他們是否肯聽從耶和華藉摩西吩咐他們列祖的命令。","notes":[]},{"n":5,"t":"以色列人住在迦南人、赫人、亞摩利人、比利洗人、希未人、耶布斯人中間，","notes":[]},{"n":6,"t":"娶他們的女兒，將自己的女兒嫁給他們的兒子，並事奉他們的神明。","notes":[]},{"n":7,"t":"以色列人行耶和華眼中看為惡的事，忘記耶和華－他們的神，去事奉諸巴力和亞舍拉，","notes":[],"heads":["俄陀聶"]},{"n":8,"t":"所以耶和華的怒氣向以色列發作，把他們交給美索不達米亞王古珊‧利薩田的手中。以色列人服事古珊‧利薩田八年。","notes":["「美索不達米亞」或譯「兩河間的亞蘭」。"]},{"n":9,"t":"以色列人呼求耶和華，耶和華就為以色列人興起一位拯救者來救他們，就是迦勒的弟弟基納斯的兒子俄陀聶。","notes":[]},{"n":10,"t":"耶和華的靈降在他身上，他就作了以色列的士師。他出去爭戰，耶和華將亞蘭王古珊‧利薩田交在他手中，他的手戰勝了古珊‧利薩田。","notes":[]},{"n":11,"t":"於是這地太平四十年。基納斯的兒子俄陀聶死了。","notes":[]},{"n":12,"t":"以色列人又行耶和華眼中看為惡的事。耶和華使摩押王伊磯倫強大，攻擊以色列，因為他們行耶和華眼中看為惡的事。","notes":[],"heads":["以笏"]},{"n":13,"t":"伊磯倫召集亞捫人和亞瑪力人到他那裏，他就去攻打以色列，佔據了棕樹城。","notes":[]},{"n":14,"t":"於是以色列人服事摩押王伊磯倫十八年。","notes":[]},{"n":15,"t":"以色列人呼求耶和華，耶和華就為他們興起一位拯救者，便雅憫人基拉的兒子以笏，他是個慣用左手的人。以色列人託他送禮物給摩押王伊磯倫。","notes":["「慣用左手的人」：原文直譯「右手綁著的人」；「便雅憫」與「右手」希伯來話發音相近；七十士譯本是「左右手兼用的人」; 20．16同。"]},{"n":16,"t":"以笏打造了一把兩刃的劍，長一短肘，綁在右腿上衣服裏面。","notes":["「短肘」或譯「肘」；參「度量衡表」。"]},{"n":17,"t":"他把禮物獻給摩押王伊磯倫。伊磯倫是個很肥胖的人。","notes":[]},{"n":18,"t":"以笏獻完禮物的時候，就把抬禮物的人送走。","notes":[]},{"n":19,"t":"但他自己卻從靠近吉甲的雕像那裏轉回來，說：「王啊，我有一件機密的事要奏告你。」王說：「迴避吧！」於是所有侍立在他左右的人都退去了。","notes":[]},{"n":20,"t":"以笏來到王那裏，那時他獨自一人坐在陰涼的頂樓。以笏說：「我有神的話向你報告。」王就從座位上站起來。","notes":[]},{"n":21,"t":"以笏伸出左手，從右腿上拔出劍來，刺入王的肚腹。","notes":[]},{"n":22,"t":"劍柄連同劍刃都刺進去了，肥肉夾住了劍刃。他沒有把劍從王的肚腹拔出來，糞便就流出來了。","notes":["「糞便就流出來了」或譯「劍就穿通了後身」，或「就從後門出去了」。"]},{"n":23,"t":"以笏出到門廊，把王關在樓門裏面，就上了鎖。","notes":[]},{"n":24,"t":"以笏出來之後，王的僕人就來了。他們觀看，看哪，樓門鎖住，就說：「他必是在陰涼的房間裏大解。」","notes":[]},{"n":25,"t":"他們等得不耐煩，看哪，樓門仍然不開，就拿鑰匙打開樓門，看哪，他們的主人已經倒在地上死了。","notes":[]},{"n":26,"t":"他們耽延的時候，以笏就逃跑了。他經過雕像那裏，逃到西伊拉。","notes":[]},{"n":27,"t":"他到了那裏，就在以法蓮山區吹角。以色列人跟隨他從山區下來，他在他們前面引路，","notes":[]},{"n":28,"t":"對他們說：「緊跟著我！因為耶和華已經把你們的仇敵摩押交在你們手中。」於是他們跟著他下去，佔據了摩押對面約旦河的渡口，不准一人過去。","notes":[]},{"n":29,"t":"那時，他們擊殺了約一萬摩押人，都是強壯的勇士，連一個也沒有逃脫。","notes":[]},{"n":30,"t":"那日，摩押在以色列手下制伏了。於是這地太平八十年。","notes":[]},{"n":31,"t":"以笏之後，有亞拿的兒子珊迦，他用趕牛的棍子打死六百非利士人。他也拯救了以色列。","notes":[],"heads":["珊迦"]}]},"4":{"heading":"底波拉和巴拉","verses":[{"n":1,"t":"以笏死後，以色列人又行耶和華眼中看為惡的事。","notes":[]},{"n":2,"t":"耶和華把他們交給在夏瑣作王的迦南王耶賓手中；他的將軍是西西拉，住在夏羅設‧哈歌印。","notes":["「夏羅設‧哈歌印」或譯「外邦人的夏羅設」；下同。"]},{"n":3,"t":"以色列人呼求耶和華，因為耶賓王有鐵的戰車九百輛，並且殘酷欺壓以色列人二十年。","notes":[]},{"n":4,"t":"有一位女先知底波拉，是拉比多的妻子，當時作以色列的士師。","notes":[]},{"n":5,"t":"她住在以法蓮山區拉瑪和伯特利的中間，在底波拉的棕樹下。以色列人都上到她那裏去聽審判。","notes":[]},{"n":6,"t":"她派人從拿弗他利的基低斯把亞比挪菴的兒子巴拉召來，對他說：「耶和華－以色列的神吩咐你：『你要率領一萬拿弗他利人和西布倫人上他泊山去。","notes":[]},{"n":7,"t":"我必使耶賓的將軍西西拉率領他的戰車和全軍往基順河，到你那裏去，我必把他交在你手中。』」","notes":[]},{"n":8,"t":"巴拉對她說：「你若同我去，我就去；你若不同我去，我就不去。」","notes":[]},{"n":9,"t":"底波拉說：「我一定會與你同去，然而你在所行的路上必得不著榮耀，因為耶和華要把西西拉交給一個婦人的手裏。」於是底波拉起來，與巴拉一同往基低斯去了。","notes":[]},{"n":10,"t":"巴拉召集西布倫人和拿弗他利人到基低斯，跟他上去的有一萬人。底波拉也同他上去。","notes":[]},{"n":11,"t":"摩西岳父何巴的後裔，基尼人希百離開了基尼族，到靠近基低斯的撒拿音橡樹旁支搭帳棚。","notes":[]},{"n":12,"t":"有人告訴西西拉：「亞比挪菴的兒子巴拉已經上了他泊山。」","notes":[]},{"n":13,"t":"西西拉就召集所有的鐵戰車九百輛和隨從的全軍，從夏羅設‧哈歌印出來，到了基順河。","notes":[]},{"n":14,"t":"底波拉對巴拉說：「起來，今日就是耶和華把西西拉交在你手中的日子。耶和華豈不在你前面行嗎?」於是巴拉下了他泊山，跟隨他的有一萬人。","notes":[]},{"n":15,"t":"耶和華使西西拉和他一切的戰車，以及全軍潰亂，在巴拉面前倒在刀下。西西拉下了車，徒步逃跑。","notes":[]},{"n":16,"t":"巴拉追趕戰車、軍隊，直到夏羅設‧哈歌印。西西拉的全軍都倒在刀下，一個也沒有留下。","notes":[]},{"n":17,"t":"只有西西拉徒步逃跑到基尼人希百之妻雅億的帳棚，因為夏瑣王耶賓與基尼人的希百家和平共處。","notes":[]},{"n":18,"t":"雅億出來迎接西西拉，對他說：「請我主進來，進到我這裏來，不要怕。」西西拉就進了她的帳棚，雅億用被子將他蓋住。","notes":[]},{"n":19,"t":"西西拉對雅億說：「我渴了，求你給我一點水喝。」雅億就打開裝奶的皮袋，給他喝，再把他蓋住。","notes":[]},{"n":20,"t":"西西拉對雅億說：「請你站在帳棚門口，若有人來問你說：『有人在這裏嗎？』你就說：『沒有。』」","notes":[]},{"n":21,"t":"西西拉疲乏沉睡了。希百的妻雅億取了帳棚的橛子，手拿著錘子，靜悄悄地到他那裏，將橛子從他的太陽穴釘進去，直釘到地裏。西西拉就死了。","notes":[]},{"n":22,"t":"看哪，巴拉追趕西西拉，雅億出來迎接他，對他說：「來，我給你看你要找的人。」他就進入帳棚，看哪，西西拉已經倒在地上死了，橛子還在他的太陽穴中。","notes":[]},{"n":23,"t":"那日，神在以色列人面前制伏了迦南王耶賓。","notes":[]},{"n":24,"t":"從此，以色列人的手對迦南王耶賓越來越強硬，直到將迦南王耶賓剪除。","notes":[]}]},"5":{"heading":"底波拉之歌","verses":[{"n":1,"t":"那日，底波拉和亞比挪菴的兒子巴拉唱歌，說：","notes":[]},{"n":2,"t":"「以色列有領袖率領，百姓甘心犧牲自己，你們當稱頌耶和華！","notes":["「有領袖率領」或譯「任由髮綹垂下」。"]},{"n":3,"t":"「君王啊，要聽！王子啊，要側耳！我要，我要向耶和華歌唱；我要歌頌耶和華－以色列的神。","notes":[]},{"n":4,"t":"「耶和華啊，你從西珥出來，從以東田野向前行，地震動天滴下，雲也滴下雨水。","notes":[]},{"n":5,"t":"眾山在耶和華面前搖動，西奈山在耶和華－以色列神面前也搖動。","notes":[]},{"n":6,"t":"「在亞拿之子珊迦的時候，在雅億的日子，大道無人行走，過路人繞道而行。","notes":[]},{"n":7,"t":"以色列農村荒蕪，空無一人，直到我底波拉興起，興起作以色列之母！","notes":[]},{"n":8,"t":"以色列人選擇新的諸神，戰爭就臨到城門。以色列四萬人中，看得見盾牌槍矛嗎？","notes":[]},{"n":9,"t":"我心嚮往以色列的領袖，他們在民中甘心犧牲自己。你們應當稱頌耶和華！","notes":[]},{"n":10,"t":"「騎淺色母驢的、坐繡花毯子的、行走在路上的，你們都當思想！","notes":[]},{"n":11,"t":"打水的聲音勝過弓箭的響聲，那裏，人要述說耶和華公義的作為，他對以色列鄉民公義的作為。「那時，耶和華的子民下到城門。","notes":[]},{"n":12,"t":"「底波拉啊，興起！興起！當興起，興起，唱歌！巴拉啊，你當興起！亞比挪菴的兒子啊，當俘擄你的俘虜！","notes":[]},{"n":13,"t":"那時，貴族中的倖存者前進，耶和華的百姓為我前進攻擊勇士。","notes":[]},{"n":14,"t":"源自亞瑪力的人從以法蓮下來，跟著你，你的族人便雅憫；有領袖從瑪吉下來，手握官員權杖的從西布倫下來。","notes":["「源自...下來」：有希臘文譯本是「從以法蓮來的人進入山谷」。"]},{"n":15,"t":"以薩迦的領袖與底波拉一起；巴拉怎樣，以薩迦也怎樣；他跟隨巴拉衝下平原。呂便支派有胸懷大志的人。","notes":["「跟隨巴拉」或譯「徒步」。","「呂便支派」或譯「在呂便的溪水旁」；下同。"]},{"n":16,"t":"你為何坐在羊圈內，聽羊群中吹笛的聲音呢？呂便支派具心有大謀的人。","notes":[]},{"n":17,"t":"基列安居在約旦河東。但為何住在船上呢？亞設在海邊居住，它在港口安居。","notes":[]},{"n":18,"t":"西布倫是拚命敢死的百姓，拿弗他利在田野的高處也是如此。","notes":[]},{"n":19,"t":"「君王都來爭戰；那時迦南諸王在米吉多水旁的他納爭戰，卻得不到擄掠的銀錢。","notes":[]},{"n":20,"t":"星宿從天上爭戰，從它們的軌道攻擊西西拉。","notes":[]},{"n":21,"t":"基順的急流沖走他們，古老的急流，基順的急流。我的靈啊，努力前進！","notes":[]},{"n":22,"t":"「那時馬蹄踢踏，壯馬奔馳飛騰。","notes":[]},{"n":23,"t":"「耶和華的使者說：『要詛咒米羅斯，重重詛咒其中的居民，因為他們不來幫助耶和華，不來幫助耶和華攻擊壯士。』","notes":[]},{"n":24,"t":"「願基尼人希百的妻子雅億比眾婦人多得福氣，比帳棚中的婦人更蒙福祉。","notes":[]},{"n":25,"t":"西西拉求水，雅億給他奶，用貴重的碗裝乳酪給他。","notes":[]},{"n":26,"t":"雅億左手拿著帳棚的橛子，右手拿著工匠的錘子，擊打西西拉，打碎他的頭，打破穿透他的太陽穴。","notes":[]},{"n":27,"t":"西西拉在她腳下曲身，仆倒，躺臥，在她腳下曲身，仆倒；他在哪裏曲身，就在哪裏仆倒，死亡。","notes":[]},{"n":28,"t":"「西西拉的母親從窗戶裏往外觀看，她在窗格子中哀號：『他的戰車為何遲遲未歸？他的車輪為何走得那麼慢呢？』","notes":[]},{"n":29,"t":"她聰明的宮女回答她，她也自言自語說：","notes":[]},{"n":30,"t":"『或許他們得了戰利品而分，每個壯士得了一兩個女子？西西拉得了彩衣為擄物，得了繡花的彩衣為掠物，這兩面繡花的彩衣，披在頸項上作為戰利品。』","notes":[]},{"n":31,"t":"「耶和華啊，願你的仇敵都這樣滅亡！願愛你的人如太陽上升，大發光輝！」於是這地太平四十年。","notes":[]}]},"6":{"heading":"基甸","verses":[{"n":1,"t":"以色列人又行耶和華眼中看為惡的事，耶和華就把他們交在米甸手裏七年。","notes":[]},{"n":2,"t":"米甸的手戰勝以色列；以色列人躲避米甸人，就在山中挖洞穴，挖洞建營寨。","notes":[]},{"n":3,"t":"每當以色列人撒種之後，米甸、亞瑪力和東邊的人都上來攻打他們，","notes":[]},{"n":4,"t":"對著他們安營，毀壞那地的農作物，直到迦薩，沒有給以色列留下食物，牛、羊、驢也沒有留下。","notes":[]},{"n":5,"t":"因為那些人帶著他們的牲畜和帳棚上來，像蝗蟲那樣多；人和駱駝無數，都進入境內，毀壞全地。","notes":[]},{"n":6,"t":"以色列因米甸的緣故極其窮乏，以色列人就呼求耶和華。","notes":[]},{"n":7,"t":"以色列人因米甸的緣故呼求耶和華的時候，","notes":[]},{"n":8,"t":"耶和華就差遣先知到以色列人那裏，對他們說：「耶和華－以色列的神如此說：『我曾領你們從埃及上來，從為奴之家出來，","notes":[]},{"n":9,"t":"救你們脫離埃及人的手，脫離一切欺壓你們之人的手。我從你們面前趕出他們，把他們的地賜給你們。","notes":[]},{"n":10,"t":"我對你們說，我是耶和華－你們的神。你們住在亞摩利人的地，不可敬畏他們的神明，但你們卻不聽從我的話。』」","notes":[]},{"n":11,"t":"耶和華的使者到了俄弗拉，坐在亞比以謝族約阿施的橡樹下。約阿施的兒子基甸正在醡酒池那裏打麥子，為了躲避米甸人。","notes":[],"heads":["基甸蒙選召"]},{"n":12,"t":"耶和華的使者向基甸顯現，對他說：「大能的勇士啊，耶和華與你同在！」","notes":[]},{"n":13,"t":"基甸對他說：「主啊，請容許我說，耶和華若與我們同在，我們怎麼會遭遇這一切事呢？我們的列祖告訴我們：『耶和華領我們從埃及上來』，他那奇妙的作為在哪裏呢？現在耶和華卻丟棄了我們，把我們交在米甸人的手掌中。」","notes":[]},{"n":14,"t":"耶和華轉向基甸，說：「去，靠著你這能力拯救以色列脫離米甸人的手掌。我豈不是已經差遣了你嗎？」","notes":[]},{"n":15,"t":"基甸對他說：「主啊，請容許我說，我怎能拯救以色列呢？看哪，我這一支在瑪拿西支派中是最貧寒的，我在我父家又是最微小的。」","notes":[]},{"n":16,"t":"耶和華對他說：「我與你同在，你就必擊敗米甸，如擊打一個人。」","notes":[]},{"n":17,"t":"基甸對他說：「我若在你眼前蒙恩，求你給我一個證據，證明是你在跟我說話。","notes":[]},{"n":18,"t":"求你不要離開這裏，等我回來，將供物帶來，供在你面前。」他說：「我必等你回來。」","notes":[]},{"n":19,"t":"基甸去預備一隻小山羊，用一伊法細麵做了無酵餅，將肉放在籃子裏，將湯盛在壺中，帶到他那裏，在橡樹下獻上。","notes":[]},{"n":20,"t":"神的使者對基甸說：「將肉和無酵餅放在這磐石上，把湯倒出來。」他就照樣做了。","notes":[]},{"n":21,"t":"耶和華的使者伸出手裏的杖，杖頭一碰到肉和無酵餅，就有火從磐石中出來，吞滅了肉和無酵餅。耶和華的使者就從他眼前消失了。","notes":[]},{"n":22,"t":"基甸見他是耶和華的使者，就說：「哎呀！主耶和華啊！因為我真的面對面看見了耶和華的使者。」","notes":[]},{"n":23,"t":"耶和華對他說：「安心吧，不要怕，你不會死。」","notes":[]},{"n":24,"t":"於是基甸在那裏為耶和華築了一座壇，起名叫「耶和華沙龍」。這壇至今還在亞比以謝族的俄弗拉。","notes":["「耶和華沙龍」意思是「耶和華賜平安」。"]},{"n":25,"t":"那夜，耶和華對基甸說：「你要把你父親的公牛，就是那七歲的第二頭公牛取來，並拆毀你父親為巴力築的壇，砍下壇旁的亞舍拉，","notes":["「就是」或譯「和」。"]},{"n":26,"t":"在這堡壘頂上整整齊齊地為耶和華－你的神築一座壇，將第二頭公牛獻為燔祭，用你所砍下的亞舍拉當柴。」","notes":[]},{"n":27,"t":"基甸就從他僕人中選了十個人，照耶和華吩咐他的做了。他因怕父家和本城的人，不敢在白天做這事，就在夜間做。","notes":[]},{"n":28,"t":"城裏的人清早起來，看哪，巴力的壇被拆毀，壇旁的亞舍拉被砍下，第二頭公牛獻在築好的壇上，","notes":[],"heads":["基甸拆毀巴力的壇"]},{"n":29,"t":"就彼此問：「這是誰做的事呢？」他們尋找查訪之後，就說：「這是約阿施的兒子基甸做的事。」","notes":[]},{"n":30,"t":"城裏的人對約阿施說：「把你的兒子交出來，我們要處死他，因為他拆毀了巴力的壇，砍下了壇旁的亞舍拉。」","notes":[]},{"n":31,"t":"約阿施對站著敵對他的眾人說：「你們是為巴力辯護嗎？你們要救它嗎？誰為它辯護，就在早晨把誰處死吧！巴力如果是神，有人拆毀了它的壇，就讓它為自己辯護吧！」","notes":[]},{"n":32,"t":"所以那日人稱基甸為耶路巴力，意思是：「他拆毀了巴力的壇，讓巴力與他爭辯吧。」","notes":[]},{"n":33,"t":"那時，所有的米甸人、亞瑪力人和東邊的人都聚集在一起，過了河，在耶斯列平原安營。","notes":[]},{"n":34,"t":"耶和華的靈降在基甸身上；他吹角，亞比以謝族都聚集跟隨他。","notes":[]},{"n":35,"t":"他派使者走遍瑪拿西，瑪拿西人也聚集跟隨他。他又派使者到亞設、西布倫、拿弗他利，他們也都上來會合。","notes":[]},{"n":36,"t":"基甸對神說：「你如果真的照你所說的，藉我的手拯救以色列，","notes":[],"heads":["羊毛的神蹟"]},{"n":37,"t":"看哪，我把一團羊毛放在禾場上，若單是羊毛上有露水，遍地都是乾的，我就知道你必照你所說的，藉我的手拯救以色列。」","notes":[]},{"n":38,"t":"一切果然發生了。次日早晨基甸起來，把羊毛擰一擰，從羊毛中擠出露水來，裝滿一碗的水。","notes":[]},{"n":39,"t":"基甸又對神說：「求你不要向我發怒，我再說一次，讓我用羊毛再試一次，但願羊毛是乾的，遍地都有露水。」","notes":[]},{"n":40,"t":"這夜，神也照樣做，遍地都有露水，只有羊毛是乾的。","notes":[]}]},"7":{"heading":"基甸擊敗米甸人","verses":[{"n":1,"t":"耶路巴力，就是基甸，和所有跟隨他的人早晨起來，在哈律泉旁安營。米甸營在他北邊，靠近摩利岡的平原。","notes":[]},{"n":2,"t":"耶和華對基甸說：「跟隨你的人太多，我不能把米甸交在他們手中，免得以色列向我自誇，說：『是我自己的手救了我。』","notes":[]},{"n":3,"t":"現在你要向這百姓宣告說：『凡懼怕戰兢的，可以離開基列山回去。』」於是有二萬二千人回去，只剩下一萬人。","notes":[]},{"n":4,"t":"耶和華對基甸說：「人還是太多。你要帶他們下到水旁，我好在那裏為你試試他們。我指著誰對你說：『這人可以跟你去』，他就可以跟你去；我指著誰對你說：『這人不可跟你去』，他就不可跟你去。」","notes":[]},{"n":5,"t":"基甸就帶百姓下到水旁。耶和華對基甸說：「凡用舌頭舔水像狗一樣舔的，要使他單獨站在一處；那些用雙膝跪下喝水的，也要使他單獨站在一處。」","notes":[]},{"n":6,"t":"用手捧到嘴邊舔水的數目有三百人，其餘的百姓都用雙膝跪下喝水。","notes":[]},{"n":7,"t":"耶和華對基甸說：「我要用這舔水的三百人拯救你們，把米甸交在你手中；其餘的百姓都可以各回自己的地方去。」","notes":[]},{"n":8,"t":"百姓手裏拿著食物和角；其餘的以色列人，基甸都打發他們各自回到自己的帳棚，只留下這三百人。米甸營在他下邊的平原上。","notes":[]},{"n":9,"t":"那夜，耶和華對基甸說：「起來，下去攻營，因我已把它交在你手中。","notes":[]},{"n":10,"t":"倘若你害怕下去，可以帶你的僕人普拉下到那營裏去，","notes":[]},{"n":11,"t":"你必聽見他們所說的，這樣你的手就有力量下去攻營。」於是基甸帶著僕人普拉下到軍營裏帶著兵器的人邊上。","notes":[]},{"n":12,"t":"米甸人、亞瑪力人和所有東邊的人都散佈在平原，如同蝗蟲那樣多。他們的駱駝無數，多如海邊的沙。","notes":[]},{"n":13,"t":"基甸到了那裏，看哪，有一人把夢告訴同伴說：「看哪，我做了一個夢。看哪，一個大麥餅滾入米甸營中，來到帳幕，把帳幕撞倒，帳幕就翻轉倒塌了。」","notes":[]},{"n":14,"t":"同伴回答說：「這不是別的，而是以色列人約阿施的兒子基甸的刀。神已把米甸和全軍都交在他手中了。」","notes":[]},{"n":15,"t":"基甸聽見這夢的敘述和夢的解釋，就敬拜神。他回到以色列營中，說：「起來吧！耶和華已把米甸軍隊交在你們手中了。」","notes":[]},{"n":16,"t":"於是基甸將三百人分成三隊，把角和空瓶交在每個人手中，瓶內有火把。","notes":[]},{"n":17,"t":"他對他們說：「看著我，你們要照樣做。看哪，我來到營邊，我怎樣做，你們也要照樣做。","notes":[]},{"n":18,"t":"我和所有跟隨我的人吹角的時候，你們也要在營的四圍吹角，喊叫：『為耶和華！為基甸！』」","notes":[]},{"n":19,"t":"基甸和跟隨他的一百人，在半夜之初換崗哨的時候來到營旁。他們就吹角，打破手中的瓶；","notes":[]},{"n":20,"t":"三隊的人都吹角，打破瓶子。他們左手拿著火把，右手拿著吹的角，喊叫：「耶和華和基甸的刀！」","notes":[]},{"n":21,"t":"他們圍著軍營，各人站在自己的地方；全營的人都逃竄，一面喊，一面逃跑。","notes":[]},{"n":22,"t":"三百人就吹角，耶和華使全營的人用刀自相擊殺。全營的人逃往西利拉的伯‧哈示他，一直逃到靠近他巴的亞伯‧米何拉。","notes":[]},{"n":23,"t":"從拿弗他利、亞設和瑪拿西全地來的以色列人被召來，追趕米甸人。","notes":[]},{"n":24,"t":"基甸也派人走遍以法蓮山區，說：「你們下來迎擊米甸人，在他們的前面沿著約旦河把守渡口，直到伯‧巴拉。」於是以法蓮眾人聚集，沿著約旦河把守渡口，直到伯‧巴拉。","notes":[]},{"n":25,"t":"他們捉住了米甸的兩個領袖，俄立和西伊伯。他們在俄立磐石上殺了俄立，在西伊伯酒池那裏殺了西伊伯。他們追趕米甸人，把俄立和西伊伯的首級帶到約旦河對岸，到基甸那裏。","notes":[]}]},"8":{"heading":"基甸追趕米甸王","verses":[{"n":1,"t":"以法蓮人對基甸說：「你去與米甸爭戰，沒有召我們同去，你為甚麼這樣待我們呢？」他們就和基甸激烈地爭吵。","notes":[]},{"n":2,"t":"基甸對他們說：「我現在所做的怎麼與你們所做的相比呢？以法蓮拾取剩下的葡萄不強過亞比以謝族所摘的葡萄嗎？","notes":[]},{"n":3,"t":"神已把米甸的兩個領袖俄立和西伊伯交在你們手中；我所做的怎能與你們所做的相比呢？」基甸說了這話，他們對他的怒氣就消了。","notes":[]},{"n":4,"t":"基甸和跟隨他的三百人來到約旦河，渡了過去；他們雖然疲乏，還是追趕。","notes":[]},{"n":5,"t":"基甸對疏割人說：「請你們拿幾塊餅來給跟隨我的百姓，因為他們疲乏了。我正在追擊米甸王西巴和撒慕拿。」","notes":[]},{"n":6,"t":"疏割人的領袖回答說：「西巴和撒慕拿的手掌現在已經在你手裏，因此我們該將餅送給你的軍隊嗎？」","notes":[]},{"n":7,"t":"基甸說：「好吧！耶和華將西巴和撒慕拿交在我手之後，我必用曠野的荊棘和枳條鞭打你們。」","notes":[]},{"n":8,"t":"基甸從那裏上到毗努伊勒，對那裏的人也提出同樣的請求；毗努伊勒人給他的答覆跟疏割人的答覆一樣。","notes":[]},{"n":9,"t":"他也對毗努伊勒人說：「我平平安安回來的時候，必拆毀這城樓。」","notes":[]},{"n":10,"t":"那時西巴和撒慕拿，以及跟隨他們的軍隊都在加各，約有一萬五千人，是東邊的人全軍所剩下的，因為拿刀戰死的約有十二萬人。","notes":[]},{"n":11,"t":"基甸從挪巴和約比哈的東邊，從住帳棚人的路上去，趁米甸的軍兵以為安全的時候攻擊他們。","notes":["「住帳棚人」意思是「商隊」。"]},{"n":12,"t":"西巴和撒慕拿逃跑；基甸追趕他們，捉住米甸的兩個王西巴和撒慕拿，使他們全軍潰散。","notes":[]},{"n":13,"t":"約阿施的兒子基甸從戰場，沿著希列斯斜坡回來，","notes":[]},{"n":14,"t":"捉住疏割人的一個少年，查問他。他就為基甸寫下疏割的領袖和長老的名字，共七十七人。","notes":[]},{"n":15,"t":"基甸到了疏割人那裏，說：「你們從前譏笑我說：『西巴和撒慕拿的手掌現在已經在你手裏，因此我們該將餅送給跟隨你的疲乏的人嗎？』看哪，西巴和撒慕拿在這裏。」","notes":[]},{"n":16,"t":"於是他拿住城內的長老，用曠野的荊棘和枳條責打疏割人。","notes":["「責打」是根據七十士譯本；原文是「教訓」。"]},{"n":17,"t":"他又拆了毗努伊勒的城樓，殺了城裏的人。","notes":[]},{"n":18,"t":"基甸對西巴和撒慕拿說：「你們在他泊山所殺的人是甚麼樣子的？」他們說：「他們很像你，個個都有王子的樣子。」","notes":[]},{"n":19,"t":"基甸說：「他們都是我的兄弟，我母親的兒子。我指著永生的耶和華起誓，你們若存留他們的性命，我就不殺你們了。」","notes":[]},{"n":20,"t":"他對他的長子益帖說：「你起來殺他們！」但是這少年害怕，不敢拔刀，因為他還是個少年。","notes":[]},{"n":21,"t":"西巴和撒慕拿說：「你自己起來殺我們吧！因為人如何，力量也如何。」基甸就起來，殺了西巴和撒慕拿，取了他們駱駝頸項上的月牙圈。","notes":[]},{"n":22,"t":"以色列人對基甸說：「你既然救我們脫離米甸的手，願你治理我們，你的兒子孫子也治理我們。」","notes":[],"heads":["基甸在俄弗拉設立以弗得"]},{"n":23,"t":"基甸對他們說：「我不治理你們，我的兒子也不治理你們，耶和華會治理你們。」","notes":[]},{"n":24,"t":"基甸又對他們說：「我有一件事求你們，請你們各人把所奪的耳環給我。」因敵人都戴金耳環，他們是以實瑪利人。","notes":[]},{"n":25,"t":"以色列人說：「我們情願送給你！」他們就鋪開一件外衣，各人將所奪的耳環丟在上面。","notes":[]},{"n":26,"t":"基甸所要求的金耳環，重一千七百舍客勒金子。此外還有米甸王所戴的月牙圈、耳環，和所穿的紫色衣服，以及駱駝頸項上的鏈子。","notes":[]},{"n":27,"t":"基甸以此造了一個以弗得，設立在他的本城俄弗拉。全以色列就在那裏拜這以弗得行淫，這就成了基甸和他全家的圈套。","notes":[]},{"n":28,"t":"這樣，米甸就被以色列人制伏了，再也不能抬頭。基甸還在的日子，這地太平四十年。","notes":[]},{"n":29,"t":"約阿施的兒子耶路巴力回去，住在自己家裏。","notes":[],"heads":["基甸去世"]},{"n":30,"t":"基甸有七十個親生的兒子，因為他有許多妻子。","notes":[]},{"n":31,"t":"他在示劍的妾也為他生了一個兒子，基甸給他起名叫亞比米勒。","notes":[]},{"n":32,"t":"約阿施的兒子基甸年紀老邁而死，葬在亞比以謝族的俄弗拉，他父親約阿施的墳墓裏。","notes":[]},{"n":33,"t":"基甸死後，以色列人又去隨從諸巴力而行淫，以巴力‧比利土為他們的神明。","notes":[]},{"n":34,"t":"以色列人不記得耶和華－他們的神，就是那位拯救他們脫離四圍仇敵之手的，","notes":[]},{"n":35,"t":"也不照著耶路巴力，就是基甸向以色列所施的恩惠善待他的家。","notes":[]}]},"9":{"heading":"亞比米勒","verses":[{"n":1,"t":"耶路巴力的兒子亞比米勒到示劍他的母舅那裏，對他們和他外祖父全家的人說：","notes":[]},{"n":2,"t":"「請你們問示劍所有的居民：『是耶路巴力的眾兒子七十人都治理你們好，還是一人治理你們好呢？』你們要記得，我是你們的骨肉。」","notes":[]},{"n":3,"t":"他的母舅們為他把這一切話說給示劍所有的居民聽，他們的心就傾向亞比米勒，因為他們說：「他是我們的弟兄。」","notes":[]},{"n":4,"t":"他們從巴力‧比利土的廟中取了七十銀子給亞比米勒，亞比米勒用這些錢雇了一些無賴匪徒跟隨他。","notes":[]},{"n":5,"t":"他來到俄弗拉他父親的家，在一塊磐石上把他的兄弟，就是耶路巴力的七十個兒子都殺了，只剩下耶路巴力的小兒子約坦，因為他躲了起來。","notes":[]},{"n":6,"t":"示劍所有的居民和全伯‧米羅都聚集在一起，到示劍橡樹旁的柱子那裏，立亞比米勒為王。","notes":[]},{"n":7,"t":"有人將這事告訴約坦，他就去站在基利心山頂上，高聲喊叫，對他們說：「示劍的居民哪，你們要聽我，神也就會聽你們。","notes":[]},{"n":8,"t":"有一次，樹木要膏一王治理他們，就去對橄欖樹說：『請你來作王治理我們！』","notes":[]},{"n":9,"t":"橄欖樹對它們說：『我豈可停止生產使神明和人得尊榮的油，而行走飄搖在眾樹之上呢？』","notes":[]},{"n":10,"t":"樹木對無花果樹說：『請你來作王治理我們！』","notes":[]},{"n":11,"t":"無花果樹對它們說：『我豈可停止結甜美的果子，而行走飄搖在眾樹之上呢？』","notes":[]},{"n":12,"t":"樹木對葡萄樹說：『請你來作王治理我們！』","notes":[]},{"n":13,"t":"葡萄樹對它們說：『我豈可停止出產使神明和人歡樂的新酒，而行走飄搖在眾樹之上呢。』","notes":[]},{"n":14,"t":"眾樹對荊棘說：『請你來作王治理我們！』","notes":[]},{"n":15,"t":"荊棘對眾樹說：『你們若真的要膏我作王治理你們，就要來到我的蔭下尋求庇護；不然，願火從荊棘裏出來，吞滅黎巴嫩的香柏樹。』","notes":[]},{"n":16,"t":"「現在你們若以誠實正直立亞比米勒為王，若善待耶路巴力和他的家，若照他手所做的回報他─","notes":[]},{"n":17,"t":"從前我父為你們爭戰，冒生命的危險救你們脫離米甸的手，","notes":[]},{"n":18,"t":"但是你們如今起來攻擊我的父家，在一塊磐石上把他的七十個兒子全殺了，又立他使女所生的兒子亞比米勒為示劍居民的王，因為他是你們的弟兄─","notes":[]},{"n":19,"t":"你們如今若以誠實正直對待耶路巴力和他的家，就可以因亞比米勒歡樂，他也可以因你們歡樂；","notes":[]},{"n":20,"t":"不然，願火從亞比米勒發出，吞滅示劍居民和伯‧米羅，又願火從示劍居民和伯‧米羅發出，吞滅亞比米勒。」","notes":[]},{"n":21,"t":"約坦因躲避他的兄弟亞比米勒就逃跑，去到比珥，住在那裏。","notes":[]},{"n":22,"t":"亞比米勒治理以色列三年。","notes":[]},{"n":23,"t":"神派邪靈到亞比米勒和示劍居民中間，示劍居民就以詭詐待亞比米勒。","notes":[]},{"n":24,"t":"這是要使耶路巴力七十個兒子受害所流的血，歸於他們的兄弟亞比米勒，因他殺害他們，也歸於那些出手幫助他殺害兄弟的示劍居民。","notes":[]},{"n":25,"t":"示劍居民在山頂上設下埋伏，等候亞比米勒。凡沿著那條路，從他們那裏經過的人，他們就搶劫。有人把這事告訴亞比米勒。","notes":[]},{"n":26,"t":"以別的兒子迦勒和他的弟兄經過，來到示劍，示劍居民都信任他。","notes":[]},{"n":27,"t":"他們出到田間，摘下葡萄，踹酒，作樂。他們進入他們神明的廟中吃喝，詛咒亞比米勒。","notes":[]},{"n":28,"t":"以別的兒子迦勒說：「亞比米勒是誰，我們示劍人是誰，叫我們服事他呢？他不是耶路巴力的兒子嗎？他的助手不是西布勒嗎？你們應當服事示劍的父親哈抹的後裔！我們為何要服事亞比米勒呢？","notes":[]},{"n":29,"t":"惟願這民歸到我的手下，我就除掉亞比米勒。」他就對亞比米勒說：「增加你的軍兵，出來吧！」","notes":["本節七十士譯本是「惟願這民歸到我的手下，我就除掉亞比米勒。我對亞比米勒說：『增加你的軍兵，出來吧！』」"]},{"n":30,"t":"西布勒市長聽見以別的兒子迦勒的話，就怒氣大發。","notes":[]},{"n":31,"t":"他悄悄地派一些使者到亞比米勒那裏，說：「看哪，以別的兒子迦勒和他的弟兄到了示劍。看哪，他們煽動那城攻擊你。","notes":[]},{"n":32,"t":"現在，你和跟隨你的百姓要夜間起來，在田間埋伏。","notes":[]},{"n":33,"t":"早晨太陽一出，你就趁早攻城。看哪，迦勒和跟隨他的百姓出來攻擊你的時候，你就全力對付他們。」","notes":[]},{"n":34,"t":"於是，亞比米勒和跟隨他的眾百姓夜間起來，兵分四隊，埋伏攻擊示劍。","notes":[]},{"n":35,"t":"以別的兒子迦勒出去，站在城門口。亞比米勒和跟隨他的百姓從埋伏之處起來。","notes":[]},{"n":36,"t":"迦勒看見百姓，就對西布勒說：「看哪，有百姓從山頂上下來。」西布勒對他說：「你把山的影子看作是人了。」","notes":[]},{"n":37,"t":"迦勒又繼續講，他說：「看哪，有百姓從地的高處下來，又有一隊從米惡尼尼橡樹的路前來。」","notes":["「米惡尼尼橡樹」或譯「占卜者的橡樹」。"]},{"n":38,"t":"西布勒對他說：「你所誇口的在哪裏呢？你曾說：『亞比米勒是誰，叫我們服事他呢？』這不是你所藐視的百姓嗎？你現在出去，與他們交戰吧！」","notes":[]},{"n":39,"t":"於是迦勒率領示劍居民出去，與亞比米勒交戰。","notes":[]},{"n":40,"t":"亞比米勒追趕迦勒，迦勒在他面前逃跑。有許多人被刺傷仆倒，直到城門口。","notes":[]},{"n":41,"t":"亞比米勒住在亞魯瑪。西布勒趕出迦勒和他的弟兄，不准他們住在示劍。","notes":[]},{"n":42,"t":"次日，百姓出到田間，有人告訴亞比米勒，","notes":[]},{"n":43,"t":"他就帶領百姓，把他們分成三隊，埋伏在田間窺探。看哪，示劍居民從城裏出來，他就起來擊殺他們。","notes":[]},{"n":44,"t":"亞比米勒和跟隨他的一隊向前衝，站在城門口；另外兩隊直衝向田間，擊殺了眾人。","notes":[]},{"n":45,"t":"亞比米勒攻城一整天，將城奪取，殺了其中的百姓，把城拆毀，撒上了鹽。","notes":[]},{"n":46,"t":"示劍城樓裏所有的居民聽見了，就進入伊勒‧比利土廟的地窖裏。","notes":[]},{"n":47,"t":"有人告訴亞比米勒，示劍城樓裏所有的居民都聚在一起。","notes":[]},{"n":48,"t":"亞比米勒和所有跟隨他的百姓都上撒們山去。亞比米勒手拿斧子，砍下一根樹枝，舉起來，扛在肩上，對跟隨他的百姓說：「你們看我做甚麼，就趕快照樣做。」","notes":[]},{"n":49,"t":"眾百姓也都各砍一根樹枝，跟亞比米勒走，把樹枝堆在地窖上，放火燒地窖。這樣，示劍城樓裏所有的人都死了，男女約有一千。","notes":[]},{"n":50,"t":"亞比米勒到提備斯，對著提備斯安營，攻取了那城。","notes":[]},{"n":51,"t":"城中有一座堅固的樓；城裏所有的居民，無論男女，都逃到那裏，關上門，上了樓頂。","notes":[]},{"n":52,"t":"亞比米勒到了樓前，攻打它。他挨近樓門，要放火焚燒。","notes":[]},{"n":53,"t":"有一個婦人把一塊上磨石拋在亞比米勒的頭上，打破了他的頭蓋骨。","notes":[]},{"n":54,"t":"他就急忙叫拿他兵器的青年來，對他說：「拔出你的刀來，殺了我吧！免得有人提到我說：『他被一個婦人殺了。』」於是那青年把他刺透，他就死了。","notes":[]},{"n":55,"t":"以色列人見亞比米勒死了，就各回自己的地方去了。","notes":[]},{"n":56,"t":"這樣，神報應了亞比米勒向他父親所做的惡事，就是殺了自己七十個兄弟。","notes":[]},{"n":57,"t":"示劍人的一切惡事，神也都報應在他們頭上；耶路巴力的兒子約坦的詛咒都臨到他們身上了。","notes":[]}]},"10":{"heading":"陀拉","verses":[{"n":1,"t":"亞比米勒以後，陀拉興起，拯救以色列，他是朵多的孫子，普瓦的兒子，以薩迦人，住在以法蓮山區的沙密。","notes":[]},{"n":2,"t":"陀拉作以色列的士師二十三年。他死了，葬在沙密。","notes":[]},{"n":3,"t":"陀拉以後有基列人睚珥興起，作以色列的士師二十二年。","notes":[],"heads":["睚珥"]},{"n":4,"t":"他有三十個兒子，騎著三十匹驢駒。他們有三十座城，叫作哈倭特‧睚珥，直到如今，都在基列地。","notes":[]},{"n":5,"t":"睚珥死了，葬在加們。","notes":[]},{"n":6,"t":"以色列人又行耶和華眼中看為惡的事，去事奉諸巴力和亞斯她錄，以及亞蘭的神明、西頓的神明、摩押的神明、亞捫人的神明、非利士人的神明。他們離棄耶和華，不事奉他。","notes":[],"heads":["耶弗他"]},{"n":7,"t":"耶和華的怒氣向以色列發作，把他們交給非利士人和亞捫人的手中。","notes":[]},{"n":8,"t":"從那年起，他們欺壓迫害以色列人，在約旦河東，亞摩利人境內，基列一帶所有的以色列人，長達十八年。","notes":[]},{"n":9,"t":"亞捫人渡過約旦河去攻打猶大和便雅憫，以及以法蓮家族。以色列的處境非常困苦。","notes":[]},{"n":10,"t":"以色列人哀求耶和華說：「我們得罪了你，因為我們離棄了我們的神，去事奉諸巴力。」","notes":[]},{"n":11,"t":"耶和華對以色列人說：「我豈沒有救你們脫離埃及人、亞摩利人、亞捫人和非利士人嗎？","notes":[]},{"n":12,"t":"西頓人、亞瑪力人和馬雲人欺壓你們，你們哀求我，我也拯救你們脫離他們的手。","notes":["「馬雲人」：七十士譯本是「米甸人」。"]},{"n":13,"t":"你們竟離棄我去事奉別神！所以我不再救你們了。","notes":[]},{"n":14,"t":"你們去哀求你們所選擇的神明；你們遭遇急難的時候，讓它們救你們吧！」","notes":[]},{"n":15,"t":"以色列人對耶和華說：「我們犯罪了，照你看為好的待我們，只求你今日拯救我們吧！」","notes":[]},{"n":16,"t":"以色列人就除掉他們中間的外邦神明，事奉耶和華。耶和華因以色列所受的苦難而心裏焦急。","notes":[]},{"n":17,"t":"亞捫人被召來，在基列安營；以色列人也聚集，在米斯巴安營。","notes":[]},{"n":18,"t":"基列百姓中的領袖彼此說：「誰領先出去攻打亞捫人，誰就作基列所有居民的領袖。」","notes":[]}]},"11":{"heading":"耶弗他的出生","verses":[{"n":1,"t":"基列人耶弗他是個大能的勇士，是妓女的兒子。基列生了耶弗他。","notes":[]},{"n":2,"t":"基列的妻子也給他生了幾個兒子。他妻子生的兒子長大後，就把耶弗他趕出去，說：「你不可在我們父家繼承產業，因為你是別的女人生的兒子。」","notes":[]},{"n":3,"t":"耶弗他就逃離他的兄弟，住在陀伯地。有些無賴的人聚集在他那裏，與他一同出入。","notes":[]},{"n":4,"t":"過了些日子，亞捫人攻打以色列。","notes":[]},{"n":5,"t":"亞捫人攻打以色列的時候，基列的長老去請耶弗他從陀伯地回來。","notes":[]},{"n":6,"t":"他們對耶弗他說：「請你來作我們的指揮官，好讓我們跟亞捫人打仗。」","notes":[]},{"n":7,"t":"耶弗他對基列的長老說：「你們不是恨我，把我趕出父家嗎？現在你們遭遇急難，為何到我這裏來呢？」","notes":[]},{"n":8,"t":"基列的長老對耶弗他說：「現在我們回到你這裏，是要請你同我們去跟亞捫人打仗，作基列所有居民的領袖。」","notes":[]},{"n":9,"t":"耶弗他對基列的長老說：「若你們請我回去跟亞捫人打仗，耶和華把他們交給我，我就作你們的領袖。」","notes":[]},{"n":10,"t":"基列的長老對耶弗他說：「有耶和華在你我之間作證，我們必定照你的話做。」","notes":[]},{"n":11,"t":"於是耶弗他與基列的長老同去，百姓就立耶弗他作他們的領袖和指揮官。耶弗他在米斯巴將他一切的事陳述在耶和華面前。","notes":[]},{"n":12,"t":"耶弗他派使者到亞捫人的王那裏，說：「你與我有甚麼相干，竟來到我這裏攻打我的地呢？」","notes":[]},{"n":13,"t":"亞捫人的王對耶弗他的使者說：「因為以色列從埃及上來的時候佔據我的地，從亞嫩河到雅博河，直到約旦河。現在你要和平歸還這些地方！」","notes":[]},{"n":14,"t":"耶弗他又派使者到亞捫人的王那裏，","notes":[]},{"n":15,"t":"對他說：「耶弗他如此說：以色列並沒有佔據摩押地和亞捫人的地。","notes":[]},{"n":16,"t":"以色列人從埃及上來，是經過曠野到紅海，來到加低斯。","notes":["「紅海」：原文是「蘆葦海」。"]},{"n":17,"t":"那時，以色列派使者去以東王那裏，說：『求你讓我穿越你的地。』以東王卻不聽。以色列又照樣派使者去摩押王那裏，他也不肯。於是以色列人就住在加低斯。","notes":[]},{"n":18,"t":"他們又經過曠野，繞過以東地和摩押地，到摩押地的東邊，在亞嫩河邊安營，並沒有進入摩押的境內，因為亞嫩河是摩押的邊界。","notes":["「東邊」：原文是「日出的方向」。"]},{"n":19,"t":"以色列派使者去亞摩利王，就是希實本王西宏那裏；以色列對他說：『求你讓我們穿越你的地，到我自己的地方去。』","notes":[]},{"n":20,"t":"西宏卻不信任以色列，不讓他們穿越他的疆界。他召集了他的眾百姓在雅雜安營，與以色列爭戰。","notes":[]},{"n":21,"t":"耶和華－以色列的神將西宏和他的眾百姓都交在以色列手中，以色列人就擊殺他們，佔領了那地居民亞摩利人的全地。","notes":[]},{"n":22,"t":"他們佔領了亞摩利人所有的疆土，從亞嫩河到雅博河，從曠野直到約旦河。","notes":[]},{"n":23,"t":"耶和華－以色列的神如今從他百姓以色列面前趕出亞摩利人，你竟要佔領它嗎？","notes":[]},{"n":24,"t":"你不是已經得了你的神明基抹賜給你的地為業嗎？耶和華－我們的神在我們面前所趕出的，我們也要得它為業。","notes":[]},{"n":25,"t":"現在你比西撥的兒子摩押王巴勒還強嗎？他真的曾與以色列爭執，或是真的與他們爭戰了嗎？","notes":[]},{"n":26,"t":"以色列人住希實本和所屬的鄉鎮，亞羅珥和所屬的鄉鎮，以及沿著亞嫩河的一切城鎮，已經有三百年了。在這期間，你們為甚麼不取回呢？","notes":[]},{"n":27,"t":"我並沒有得罪你，你卻要攻打我，加害於我。願審判人的耶和華今日在以色列人和亞捫人之間判斷是非。」","notes":[]},{"n":28,"t":"但亞捫人的王不聽耶弗他傳達給他的話。","notes":[]},{"n":29,"t":"耶和華的靈降在耶弗他身上，他就經過基列和瑪拿西，經過基列的米斯巴，又從基列的米斯巴過到亞捫人那裏。","notes":[]},{"n":30,"t":"耶弗他向耶和華許願，說：「你若真的將亞捫人交在我手中，","notes":[]},{"n":31,"t":"我從亞捫人那裏平平安安回來的時候，無論誰先從我家門出來迎接我，就要歸給耶和華，我必將他獻上作為燔祭。」","notes":[]},{"n":32,"t":"於是耶弗他往亞捫人那裏去，與他們爭戰。耶和華將他們交在他手中，","notes":[]},{"n":33,"t":"他就徹底擊敗他們，從亞羅珥到米匿，直到亞備勒‧基拉明，攻取了二十座城。這樣，亞捫人就在以色列人面前被制伏了。","notes":[]},{"n":34,"t":"耶弗他回米斯巴去，到了自己的家，看哪，他女兒拿著手鼓跳舞出來迎接他。她是耶弗他的獨生女，除她以外，沒有別的兒女。","notes":[],"heads":["耶弗他的女兒"]},{"n":35,"t":"耶弗他一看見她，就撕裂衣服，說：「哀哉！我的女兒啊，你使我非常悲痛，叫我十分為難了。因為我已經向耶和華開了口，不能收回。」","notes":[]},{"n":36,"t":"他女兒對他說：「我的父親啊，你既向耶和華開了口，就當照你口中所說的向我行，因為耶和華已經在你的仇敵亞捫人身上為你報了仇。」","notes":[]},{"n":37,"t":"她又對父親說：「我只求你這一件事，給我兩個月，讓我和同伴下到山裏，好為我的童貞哀哭。」","notes":[]},{"n":38,"t":"耶弗他說：「你去吧！」他就讓她離開兩個月。她和同伴去了，在山裏為她的童貞哀哭。","notes":[]},{"n":39,"t":"過了兩個月，她回到父親那裏，父親就照所許的願向她行了。她從來沒有親近男人。於是以色列中有個風俗，","notes":[]},{"n":40,"t":"每年按著日期以色列的女子要去為基列人耶弗他的女兒哀哭四天。","notes":[]}]},"12":{"heading":"耶弗他與以法蓮人交戰","verses":[{"n":1,"t":"以法蓮人被召來，渡河來到撒分。他們對耶弗他說：「你去與亞捫人爭戰，為甚麼沒有召我們同去呢？我們必用火將你和你的家燒了。」","notes":["「撒分」或譯「北方」。"]},{"n":2,"t":"耶弗他對他們說：「我和我的百姓與亞捫人有極大的衝突；我曾召你們來，你們卻沒有來救我脫離他們的手。","notes":[]},{"n":3,"t":"我見你們不來救我，就拚了命前去攻打亞捫人，耶和華就將他們交在我手中。你們今日為甚麼上我這裏來攻打我呢？」","notes":[]},{"n":4,"t":"於是耶弗他召集基列所有的人，要與以法蓮人爭戰。基列人擊殺以法蓮人，因以法蓮人曾說：「你們基列人在以法蓮和瑪拿西中，不過是以法蓮逃亡的人而已。」","notes":[]},{"n":5,"t":"基列人把守約旦河的渡口，不許以法蓮人過去。逃跑的以法蓮人若說：「讓我過河。」基列人就問他說：「你是不是以法蓮人？」他若說：「不是」，","notes":[]},{"n":6,"t":"基列人就對他說：「你說『示播列』。」以法蓮人因為發音不準，就會說成「西播列」。基列人就捉住他，在約旦河的渡口把他殺了。那時，以法蓮人被殺的有四萬二千人。","notes":[]},{"n":7,"t":"耶弗他作以色列的士師六年。基列人耶弗他死了，葬在基列的城裏。","notes":["「基列的城裏」：七十士譯本是「他的城基列」。"]},{"n":8,"t":"耶弗他以後，有伯利恆人以比讚作以色列的士師。","notes":[],"heads":["以比讚、以倫、押頓"]},{"n":9,"t":"他有三十個兒子。他把三十個女兒都嫁出去了，也為他的兒子從外面娶了三十個媳婦。他作以色列的士師七年。","notes":[]},{"n":10,"t":"以比讚死了，葬在伯利恆。","notes":[]},{"n":11,"t":"以比讚以後，有西布倫人以倫作以色列的士師，他作以色列的士師十年。","notes":[]},{"n":12,"t":"西布倫人以倫死了，葬在西布倫地的亞雅崙。","notes":[]},{"n":13,"t":"以倫以後，有比拉頓人希列的兒子押頓作以色列的士師。","notes":[]},{"n":14,"t":"他有四十個兒子，三十個孫子，騎著七十匹驢駒。押頓作以色列的士師八年。","notes":[]},{"n":15,"t":"比拉頓人希列的兒子押頓死了，葬在以法蓮地的比拉頓，就在亞瑪力人的山區。","notes":[]}]},"13":{"heading":"參孫","verses":[{"n":1,"t":"以色列人又行耶和華眼中看為惡的事，耶和華將他們交在非利士人手中四十年。","notes":[]},{"n":2,"t":"那時，有一個但支派的瑣拉人，名叫瑪挪亞。他的妻子不懷孕，不生育。","notes":[],"heads":["參孫出生"]},{"n":3,"t":"耶和華的使者向那婦人顯現，對她說：「看哪，以前你不懷孕，不生育，如今你必懷孕生一個兒子。","notes":[]},{"n":4,"t":"現在你要謹慎，清酒烈酒都不可喝，任何不潔之物都不可吃，","notes":[]},{"n":5,"t":"看哪，你必懷孕，生一個兒子。不可用剃刀剃他的頭，因為這孩子一出母胎就歸給神作拿細耳人。他必開始拯救以色列脫離非利士人的手。」","notes":[]},{"n":6,"t":"那婦人來對丈夫說：「有一個神人到我這裏來，他的容貌如神使者的容貌，非常可畏。我沒有問他從哪裏來，他也沒有把他的名字告訴我。","notes":[]},{"n":7,"t":"他對我說：『看哪，你要懷孕，生一個兒子 。現在，清酒烈酒都不可喝，任何不潔之物都不可吃，因為這孩子從出母胎一直到死的那一天，要歸給神作拿細耳人。』」","notes":[]},{"n":8,"t":"瑪挪亞祈求耶和華說：「主啊，求你再差遣那神人到我們這裏來，指示我們對這將要生的孩子該怎樣作。」","notes":[]},{"n":9,"t":"神垂聽了瑪挪亞的聲音。那婦人坐在田間的時候，神的使者又到她那裏，但是她的丈夫瑪挪亞沒有同她在一起。","notes":[]},{"n":10,"t":"婦人急忙跑去告訴丈夫，對他說：「看哪，那日到我這裏來的人又向我顯現了。」","notes":[]},{"n":11,"t":"瑪挪亞起來，跟隨他的妻子來到那人那裏，對他說：「你就是跟這婦人說話的那個人嗎？」他說：「是我。」","notes":[]},{"n":12,"t":"瑪挪亞說：「現在，願你的話應驗！這孩子該如何管教呢？他當做甚麼呢？」","notes":[]},{"n":13,"t":"耶和華的使者對瑪挪亞說：「我告訴這婦人的一切事，她都要遵守。","notes":[]},{"n":14,"t":"葡萄樹所結的不可吃，清酒烈酒都不可喝，任何不潔之物也不可吃。凡我所吩咐的，她都當遵守。」","notes":[]},{"n":15,"t":"瑪挪亞對耶和華的使者說：「請容許我們留你下來，好為你預備一隻小山羊。」","notes":[]},{"n":16,"t":"耶和華的使者對瑪挪亞說：「你雖然留我，我卻不吃你的食物。你若預備燔祭，就當獻給耶和華。」因瑪挪亞不知道他是耶和華的使者。","notes":[]},{"n":17,"t":"瑪挪亞對耶和華的使者說：「請問大名？好讓我們在你的話應驗的時候尊敬你。」","notes":[]},{"n":18,"t":"耶和華的使者對他說：「你何必問我的名字呢？我的名字是奇妙的。」","notes":[]},{"n":19,"t":"瑪挪亞取一隻小山羊和素祭，在磐石上獻給耶和華。他行奇妙的事，瑪挪亞和他的妻子觀看，","notes":[]},{"n":20,"t":"火焰從壇上往上升，耶和華的使者也在壇上的火焰中升上去了。瑪挪亞和他的妻子看見，就臉伏於地。","notes":[]},{"n":21,"t":"耶和華的使者不再向瑪挪亞和他的妻子顯現了。那時，瑪挪亞才知道他是耶和華的使者。","notes":[]},{"n":22,"t":"瑪挪亞對他的妻子說：「我們一定會死，因為我們看見了神。」","notes":[]},{"n":23,"t":"他的妻子卻對他說：「耶和華若有意要我們死，就不會從我們手中接受燔祭和素祭，不會將這一切事指示我們，這時也不會讓我們聽到這話。」","notes":[]},{"n":24,"t":"後來婦人生了一個兒子，給他起名叫參孫。孩子漸漸長大，耶和華賜福給他。","notes":[]},{"n":25,"t":"在瑣拉和以實陶之間的瑪哈尼‧但，耶和華的靈開始感動參孫。","notes":["「瑪哈尼‧但」意思是「但支派的營中」。"]}]},"14":{"heading":"參孫娶妻","verses":[{"n":1,"t":"參孫下到亭拿，在亭拿看見一個女子，是非利士人的女兒。","notes":[]},{"n":2,"t":"他上來告訴他父母說：「我在亭拿看見一個女子，是非利士人的女兒，現在請你們給我娶她為妻。」","notes":[]},{"n":3,"t":"他父母對他說：「在你弟兄的女兒中，或在本族所有的人中，難道沒有女子嗎？你何必在未受割禮的非利士人中去娶妻呢？」參孫對他父親說：「請你給我娶那女子，因為我喜歡她。」","notes":[]},{"n":4,"t":"他的父母並不知道這事是出於耶和華，因為他在找機會攻擊非利士人。那時，非利士人轄制以色列人。","notes":[]},{"n":5,"t":"參孫跟他父母下亭拿去，他們到了亭拿的葡萄園。看哪，有一隻少壯獅子對著他吼叫。","notes":[]},{"n":6,"t":"耶和華的靈大大感動參孫，他就手無寸鐵撕裂獅子，如撕裂小山羊一樣。他做這事，並沒有告訴他的父母親。","notes":[]},{"n":7,"t":"參孫下去跟那女子說話，看著就喜歡她。","notes":[]},{"n":8,"t":"過了些日子，他回來要娶那女子，繞道去看獅子的殘骸，看哪，有一群蜜蜂在獅子的屍體內，也有蜜在裏面。","notes":[]},{"n":9,"t":"他就取了蜜，放在手掌上，邊走邊吃。他到了父母那裏，給他們蜜，他們也吃了。但他沒有告訴他們，這蜜是從獅子的屍體內取來的。","notes":[]},{"n":10,"t":"他父親下到女子那裏去。參孫在那裏擺設宴席， 因為這是當時年輕人的習俗。","notes":[]},{"n":11,"t":"他們看見參孫，就請了三十個人陪伴他。","notes":[]},{"n":12,"t":"參孫對他們說：「我給你們出個謎語，你們若能在七日宴席之內，猜出謎底告訴我，我就給你們三十件細麻內衣和三十套更換的衣服。","notes":[]},{"n":13,"t":"但你們若不能告訴我，你們就給我三十件細麻內衣和三十套更換的衣服。」他們對他說：「請把謎語說給我們聽。」","notes":[]},{"n":14,"t":"參孫對他們說：「吃的從吃者出來；甜的從強者出來」。三日之久，他們都猜不出謎語來。","notes":[]},{"n":15,"t":"第七日，他們對參孫的妻子說：「你哄騙你的丈夫，為我們探出謎底來，否則我們就用火燒你和你的父家。你們請我們來，是不是要奪走我們所有的呢？」","notes":["「第七日」：七十士譯本和其他古譯本是「第四日」。"]},{"n":16,"t":"參孫的妻子在丈夫面前哭哭啼啼說：「你只是恨我，並不愛我。你給我本族的人出謎語，卻不把謎底告訴我。」參孫對她說：「看哪，連我的父母我都沒有說，我怎麼可以告訴你呢？」","notes":[]},{"n":17,"t":"在七日宴席中，她一直在丈夫面前哭哭啼啼。第七日，參孫因妻子的催逼就把謎底告訴了她。她把謎底告訴了她本族的人。","notes":[]},{"n":18,"t":"第七日日落以前，那城裏的人對參孫說：「有甚麼比蜜還甜呢？有甚麼比獅子更強呢？」參孫對他們說：「你們若不用我的母牛犢耕地，就無法猜出我的謎底來。」","notes":[]},{"n":19,"t":"耶和華的靈大大感動參孫，他就下到亞實基倫，擊殺了三十個人，奪了他們身上的衣服，把衣服給了猜出謎語的人。參孫怒氣大發，就上他父親的家去了。","notes":[]},{"n":20,"t":"參孫的妻子就歸了參孫的一個同伴，就是作過他伴郎的。","notes":[]}]},"15":{"heading":"參孫擊敗非利士人","verses":[{"n":1,"t":"過了些日子，在割麥子的時候，參孫帶著一隻小山羊去探望他的妻子，說：「我要進內室到我妻子那裏。」他岳父不許他進去。","notes":[]},{"n":2,"t":"他岳父說：「我以為你極其恨她，因此我把她給了你的同伴。她妹妹不是比她更美麗嗎？你可以娶來代替她！」","notes":[]},{"n":3,"t":"參孫對他們說：「這一次我若加害非利士人，就不算是我的錯了。」","notes":[]},{"n":4,"t":"於是參孫去捉了三百隻狐狸，把牠們的尾巴一對一對地綁住，再將火把綁在兩條尾巴中間。","notes":[]},{"n":5,"t":"他點著火把，把狐狸放進非利士人直立的莊稼，把堆積的禾捆和直立的莊稼，葡萄園、橄欖園全都燒了。","notes":[]},{"n":6,"t":"非利士人說：「這事是誰做的呢？」有人說：「是亭拿人的女婿參孫做的，因為他岳父把他的妻子給了他的同伴。」於是非利士人上去，用火燒了女子和她的父親。","notes":[]},{"n":7,"t":"參孫對他們說：「你們既然這麼做，我必向你們報仇才肯罷休。」","notes":[]},{"n":8,"t":"參孫狠狠擊殺他們，把他們連腿帶腰都砍了。過後，他就下去，住在以坦巖的石洞裏。","notes":[]},{"n":9,"t":"非利士人上去，安營在猶大，侵犯利希。","notes":[]},{"n":10,"t":"猶大人說：「你們為何上來攻擊我們呢？」他們說：「我們上來是要捆綁參孫，照他向我們所做的對待他。」","notes":[]},{"n":11,"t":"於是，三千猶大人下到以坦巖的石洞裏，對參孫說：「非利士人轄制我們，你不知道嗎？你向我們做的是甚麼事呢？」他說：「他們向我怎樣做，我也要向他們怎樣做。」","notes":[]},{"n":12,"t":"猶大人對他說：「我們下來是要捆綁你，把你交在非利士人手中。」參孫說：「你們要向我起誓，你們自己不殺害我。」","notes":[]},{"n":13,"t":"他們說：「我們絕不殺你，只把你捆綁，交在非利士人手中。」於是他們用兩條新繩綁住參孫，把他從以坦巖帶上去。","notes":[]},{"n":14,"t":"參孫到了利希，非利士人對著他喊叫。耶和華的靈大大感動參孫，他手臂上的繩子就像著火的麻一樣，綁他的繩子從他手上脫落下來。","notes":[]},{"n":15,"t":"他找到一塊未乾的驢腮骨，就伸手拾起來，用它殺了一千人。","notes":[]},{"n":16,"t":"參孫說：「用驢腮骨，一堆又一堆；用驢腮骨，我殺了一千人。」","notes":["「一堆又一堆」：七十士譯本是「我把他們完全除掉」。"]},{"n":17,"t":"說完這話，就把那腮骨從手裏拋出去。因此，那地叫作拉末‧利希。","notes":["「拉末‧利希」意思是「腮骨岡」。"]},{"n":18,"t":"參孫非常口渴，就求告耶和華說：「你既藉僕人的手施行這麼大的拯救，現在我要渴死，落在未受割禮的人手中嗎？」","notes":[]},{"n":19,"t":"神就使利希的窪地裂開，從中湧出水來。參孫喝了，精神恢復。因此那泉名叫隱‧哈歌利，直到今日它仍在利希。","notes":["「隱‧哈歌利」意思是「呼求者的水泉」。"]},{"n":20,"t":"在非利士人轄制的時候，參孫作以色列的士師二十年。","notes":[]}]},"16":{"heading":"參孫和大利拉","verses":[{"n":1,"t":"參孫到了迦薩，在那裏看見一個妓女，就與她親近。","notes":[]},{"n":2,"t":"有人告訴迦薩人說：「參孫到這裏來了！」他們就包圍起來，整夜在城門埋伏等著他。他們整夜靜悄悄地，說：「等到天一亮我們就殺他。」","notes":[]},{"n":3,"t":"參孫睡到半夜，在半夜起來，抓住城門的門扇和兩個門框，把它們和門閂一起拆下來，扛在肩上，抬到希伯崙前面的山頂上。","notes":[]},{"n":4,"t":"這事以後，參孫在梭烈谷愛上了一個女子，名叫大利拉。","notes":[]},{"n":5,"t":"非利士人的領袖上去，到那女子那裏，對她說：「請你哄騙參孫，探出他為何有這麼大的力氣，以及我們要用甚麼方法才能勝他，將他捆綁制伏。我們就每人給你一千一百塊銀子。」","notes":[]},{"n":6,"t":"大利拉對參孫說：「請你告訴我，你為何有這麼大的力氣，要用甚麼方法才能捆綁制伏你。」","notes":[]},{"n":7,"t":"參孫對她說：「若用七條未乾的新繩子捆綁我，我就像平常人一樣軟弱。」","notes":[]},{"n":8,"t":"於是非利士人的領袖拿了七條未乾的新繩子來，交給她，她就用繩子捆綁參孫。","notes":[]},{"n":9,"t":"當時，埋伏的人正在她的內室等著。她對參孫說：「參孫，非利士人來捉你了！」參孫就掙斷繩子，繩子如遇到火的麻線斷裂一樣。這樣，人還是不知道他的力量從哪裏來。","notes":[]},{"n":10,"t":"大利拉對參孫說：「看哪，你欺騙我，對我說謊。現在請你告訴我，要用甚麼方法才能捆綁你。」","notes":[]},{"n":11,"t":"參孫對她說：「若用未曾用過的新繩子捆綁我，我就像平常人一樣軟弱。」","notes":[]},{"n":12,"t":"大利拉就用新繩子捆綁他，對他說：「參孫，非利士人來捉你了！」當時，埋伏的人在內室等著。參孫掙斷手臂上的繩子，如掙斷一條線一樣。","notes":[]},{"n":13,"t":"大利拉對參孫說：「你到現在還是欺騙我，對我說謊。請你告訴我，要用甚麼方法才能捆綁你。」參孫對她說：「只要用織布的線將我頭上的七條髮綹編織起來就可以了」。","notes":[]},{"n":14,"t":"於是大利拉用梭子將他的髮綹釘住，對他說：「參孫，非利士人來捉你了！」參孫從睡中醒來，將織布機上的梭子和織布的線一齊都拔出來了。","notes":[]},{"n":15,"t":"大利拉對參孫說：「你既不與我同心，怎麼能說『我愛你』呢？你這三次欺騙我，不告訴我，你為甚麼有這麼大的力氣。」","notes":[]},{"n":16,"t":"大利拉天天用話催逼他，糾纏他，他就心裏煩得要死，","notes":[]},{"n":17,"t":"終於把心中的一切都告訴她。參孫對她說：「從來沒有人用剃刀剃我的頭，因為我一出母胎就歸給神作拿細耳人。若有人剃了我的頭髮，我的力氣就會離開我，我就像平常人一樣軟弱。」","notes":[]},{"n":18,"t":"大利拉見他說出了心中的一切，就派人去召非利士人的領袖，說：「請再上來一次，因為他已經說出了心中的一切。」於是非利士人的領袖手裏拿著銀子，上到她那裏。","notes":[]},{"n":19,"t":"大利拉哄參孫睡在她的膝上，叫一個人來剃掉參孫頭上的七條髮綹。於是大利拉開始制伏參孫，他的力氣就離開他了。","notes":[]},{"n":20,"t":"大利拉說：「參孫，非利士人來捉你了！」參孫從睡中醒來，說：「我要像前幾次一樣脫身而去。」他卻不知道耶和華已經離開他了。","notes":[]},{"n":21,"t":"非利士人逮住他，挖了他的眼睛，帶他下到迦薩，用銅鏈鎖住他，叫他在監獄裏推磨。","notes":[]},{"n":22,"t":"然而他的頭髮被剃以後，又開始長起來了。","notes":[]},{"n":23,"t":"非利士人的領袖聚集，要向他們的神明大袞獻大祭，並且慶祝，說：「我們的神明把我們的仇敵參孫交在我們手中了。」","notes":[],"heads":["參孫的死"]},{"n":24,"t":"眾人看見參孫，就讚美他們的神明說：「我們的神明把那毀壞我們的地、殺害我們許多人的仇敵交在我們手中了。」","notes":[]},{"n":25,"t":"他們心裏高興的時候，就說：「叫參孫來，逗我們歡樂。」於是他們把參孫從監獄裏提出來，在他們面前戲耍。他們叫他站在兩根柱子中間。","notes":[]},{"n":26,"t":"參孫對牽他手的僮僕說：「讓我摸摸支撐這廟宇的柱子，我要靠一靠。」","notes":[]},{"n":27,"t":"那時廟宇內充滿男女，非利士人的眾領袖也都在那裏，屋頂上約有三千男女觀看參孫逗他們歡樂。","notes":[]},{"n":28,"t":"參孫求告耶和華說：「主耶和華啊，求你眷念我。神啊，就這一次，求你賜給我力量，使我向非利士人報那挖我雙眼的仇。」","notes":[]},{"n":29,"t":"參孫抱住中間支撐廟宇的兩根柱子，左手抱一根，右手抱一根。","notes":[]},{"n":30,"t":"然後他說：「讓我與非利士人一起死吧！」他盡力彎腰，廟宇就倒塌了，壓住領袖和廟宇內的眾人。這樣，參孫死的時候所殺的人比活著所殺的還多。","notes":[]},{"n":31,"t":"他的兄弟和他父親的全家都下去收他的屍首，抬上去，葬在瑣拉和以實陶中間、他父親瑪挪亞的墳墓裏。參孫作以色列的士師二十年。","notes":[]}]},"17":{"heading":"米迦的偶像","verses":[{"n":1,"t":"以法蓮山區有一個人，名叫米迦。","notes":[]},{"n":2,"t":"他對母親說：「你的一千一百塊銀子被人拿走了，為此你發咒起誓，也說給我聽。看哪，銀子在我這裏，是我拿的。」他母親說：「願我兒蒙耶和華賜福！」","notes":[]},{"n":3,"t":"米迦把這一千一百塊銀子還他母親。他母親說：「我把這銀子分別為聖，親手獻給耶和華，為我兒子造一尊雕刻的像，以及一尊鑄成的像。現在我把銀子交給你。」","notes":[]},{"n":4,"t":"米迦把銀子還他母親，他母親把二百塊銀子交給銀匠，去造一尊雕刻的像，以及一尊鑄成的像，安置在米迦的房子裏。","notes":[]},{"n":5,"t":"米迦這個人有了神堂，又造了以弗得和家中的神像，派他的一個兒子作祭司。","notes":[]},{"n":6,"t":"那時，以色列中沒有王，各人照自己眼中看為對的去做。","notes":[]},{"n":7,"t":"猶大的伯利恆有一個年輕人，是猶大族的人。他是利未人，寄居在那裏。","notes":[]},{"n":8,"t":"這人離開猶大的伯利恆城，要找一個可住的地方。他來到以法蓮山區米迦的家，還要往前走。","notes":[]},{"n":9,"t":"米迦對他說：「你從哪裏來？」他說：「我從猶大的伯利恆來。我是利未人，要找一個可住的地方。」","notes":[]},{"n":10,"t":"米迦說：「你就住在我這裏吧！我以你為父為祭司，每年給你十塊銀子和一套衣服，以及生活所需的食物。」利未人就來了。","notes":[]},{"n":11,"t":"利未人願意和這人同住；他待這年輕人如自己的兒子一樣。","notes":[]},{"n":12,"t":"米迦授這年輕的利未人祭司的職任，他就住在米迦的家裏。","notes":[]},{"n":13,"t":"米迦說：「現在我知道耶和華必恩待我，因為我有利未人作我的祭司。」","notes":[]}]},"18":{"heading":"但支派的遷移","verses":[{"n":1,"t":"那時，以色列中沒有王。但支派的人還在覓地居住，因為直到那日，他們還沒有在以色列支派中抽籤得地為業。","notes":[]},{"n":2,"t":"但人從瑣拉和以實陶派本族中的五個勇士，去窺探偵察那地，對他們說：「你們去偵察那地。」他們來到以法蓮山區米迦的家中，就在那裏住宿。","notes":[]},{"n":3,"t":"他們臨近米迦的家，聽出那年輕的利未人的口音，就繞到那裏，對他說：「誰領你到這裏來？你在這裏做甚麼？你在這裏得了甚麼？」","notes":[]},{"n":4,"t":"他對他們說：「米迦如此如此待我，他雇用我，我就作了他的祭司。」","notes":[]},{"n":5,"t":"他們對他說：「請你求問神，使我們知道所走的道路是否通達。」","notes":[]},{"n":6,"t":"祭司對他們說：「你們平平安安去吧，你們所行的道路是在耶和華面前的。」","notes":[]},{"n":7,"t":"五人就走了，來到拉億，見那裏的人安居，像西頓人的生活一樣安寧無慮，那地無人羞辱他們，無人奪取侵略。他們離西頓人很遠，與世無爭。","notes":["「與世無爭」：七十士譯本是「與敘利亞沒有爭執」；下同。"]},{"n":8,"t":"五人回到瑣拉和以實陶他們的弟兄那裏。他們的弟兄對他們說：「你們怎麼了？」","notes":[]},{"n":9,"t":"他們說：「起來，我們上去攻打他們吧！我們已經窺探了那地，看哪，那地非常好。你們還要待在這裏嗎？不要再遲延了，立刻出發去得那地為業吧！","notes":[]},{"n":10,"t":"你們去，必來到安居的百姓和兩邊遼闊的地。神已將那地方交在你們手中了；那裏不缺地上的任何東西。」","notes":[]},{"n":11,"t":"於是但族的六百人，各帶兵器，從瑣拉和以實陶出發，","notes":[]},{"n":12,"t":"上到猶大的基列‧耶琳，在那裏安營。因此那地方名叫瑪哈尼‧但，直到今日。看哪，它在基列‧耶琳的西邊。","notes":[]},{"n":13,"t":"他們從那裏往以法蓮山區去，來到米迦的家。","notes":[]},{"n":14,"t":"先前窺探拉億地的五個人對他們的弟兄說：「你們知道嗎？這些屋子裏有以弗得和家中的神像，以及一尊雕刻的像與一尊鑄成的像。現在你們要知道該怎麼做。」","notes":[]},{"n":15,"t":"五人轉身，進入米迦的家，來到那年輕利未人的房間，向他問安。","notes":[]},{"n":16,"t":"六百但人各帶兵器，站在門口。","notes":[]},{"n":17,"t":"那窺探這地的五個人上前去，進入裏面，拿走雕刻的像、以弗得、家中的神像，以及鑄成的像。祭司和帶兵器的六百人一同站在門口。","notes":[]},{"n":18,"t":"當五個人進入米迦的家，拿走雕刻的像、以弗得、家中的神像，以及鑄成的像，祭司對他們說：「你們做甚麼呢？」","notes":[]},{"n":19,"t":"他們對他說：「不要作聲，用手摀口，跟我們去吧！我們必以你為父為祭司。你作一家的祭司好呢？還是作以色列一支派一族的祭司好呢？」","notes":[]},{"n":20,"t":"祭司心裏歡喜，拿著以弗得和家中的神像，以及雕刻的像，跟這些百姓走了。","notes":[]},{"n":21,"t":"他們轉身離開那裏，把孩子、牲畜、財物安排在前頭。","notes":[]},{"n":22,"t":"他們離了米迦的家已遠，米迦家附近的鄰居被召來，追趕但人。","notes":[]},{"n":23,"t":"他們呼叫但人，但人回頭對米迦說：「你召集這許多人來做甚麼呢？」","notes":[]},{"n":24,"t":"米迦說：「你們把我所造的神像，還有祭司，都帶走了，我還有甚麼呢？你怎麼還對我說『你在做甚麼』呢？」","notes":[]},{"n":25,"t":"但人對米迦說：「你不要讓我們再聽見你的聲音，恐怕這群惱怒成性的人會攻擊你們，你和你的全家就會喪命。」","notes":[]},{"n":26,"t":"但人仍走他們的路。米迦見他們的勢力比自己強，就轉身回家去了。","notes":[]},{"n":27,"t":"但人把米迦造的神像和他的祭司帶走，來到拉億安寧無慮的百姓那裏，用刀殺了他們，放火燒了那城。","notes":[]},{"n":28,"t":"沒有人來搭救，因為這城離西頓很遠，他們又與世無爭；這城在靠近伯‧利合的平原。但人建造這城，在那裏居住，","notes":[]},{"n":29,"t":"並照著他們祖先以色列之子但的名字，給這城起名叫但。原先這城名叫拉億。","notes":[]},{"n":30,"t":"但人為自己設立了那雕刻的像。摩西的孫子，革舜的兒子約拿單和他的子孫作但支派的祭司，直到那地遭擄掠的日子。","notes":[]},{"n":31,"t":"神的家在示羅多少日子，但人為自己設立米迦所雕刻的像也在但多少日子。","notes":[]}]},"19":{"heading":"一個利未人和他的妾","verses":[{"n":1,"t":"當以色列中沒有王的時候，有一個利未人寄居以法蓮山區的邊界，他娶了一個猶大伯利恆的女子為妾。","notes":[]},{"n":2,"t":"這妾對丈夫生氣，離開丈夫，回到猶大伯利恆的父家，在那裏住了四個月。","notes":["「對丈夫生氣」或譯「行淫，對丈夫不忠」。"]},{"n":3,"t":"她的丈夫起來，帶著一個僕人、兩匹驢跟著她去，要用好話勸她回來。女子就帶丈夫進到父親家裏。女子的父親看見了他，就歡歡喜喜地迎接他。","notes":[]},{"n":4,"t":"這岳父，就是女子的父親，留他住了三天。他們在那裏吃喝，住宿。","notes":[]},{"n":5,"t":"第四日，他們清早起來，利未人起身要走，女子的父親對女婿說：「先吃點東西，加添心力，然後你們才走。」","notes":[]},{"n":6,"t":"於是二人坐下，一同吃喝。女子的父親對那人說：「請你答應再住一夜，使你的心舒暢。」","notes":[]},{"n":7,"t":"那人起身要走，他岳父挽留他，他就留下，在那裏又住了一夜。","notes":[]},{"n":8,"t":"第五日，他清早起來要走，女子的父親說：「來，請加添心力，留到太陽偏西吧。」於是二人一同再吃。","notes":[]},{"n":9,"t":"那人同他的妾和僕人起身要走，但他岳父，就是女子的父親，對他說：「看哪，太陽下山，天快晚了，你們再住一夜吧。看哪，太陽偏西了，就在這裏住宿，使你的心舒暢，明天你們一早起來上路，回你的帳棚去。」","notes":[]},{"n":10,"t":"那人不願再住一夜，就備上兩匹驢，帶著他的妾起身走了，來到耶布斯的對面，耶布斯就是耶路撒冷。","notes":[]},{"n":11,"t":"將近耶布斯的時候，太陽快下山了，僕人對主人說：「來吧，我們進這耶布斯人的城，在這裏住宿。」","notes":[]},{"n":12,"t":"主人對他說：「我們不可進入外邦人的城，那不是以色列人的地方，我們越過這裏到基比亞去吧。」","notes":[]},{"n":13,"t":"他又對僕人說：「來，讓我們到基比亞或拉瑪的一個地方住宿。」","notes":[]},{"n":14,"t":"於是他們越過那裏往前走，將到便雅憫的基比亞的時候，太陽已經下山了。","notes":[]},{"n":15,"t":"他們進入基比亞要在那裏住宿。他來坐在城裏的廣場上，但沒有人接待他們到家裏住宿。","notes":[]},{"n":16,"t":"看哪，晚上有一個老人從田間做工回來。他是以法蓮山區的人，寄居在基比亞；那地方的人是便雅憫人。","notes":[]},{"n":17,"t":"老人舉目看見那過路的人在城裏的廣場上，就說：「你從哪裏來？要到哪裏去？」","notes":[]},{"n":18,"t":"他對他說：「我們從猶大的伯利恆過來，要到以法蓮山區的邊界去。我是那裏的人，去了猶大的伯利恆，現在要到耶和華的家去，卻沒有人接待我到他的家。","notes":[]},{"n":19,"t":"其實我有飼料草料可以餵驢，我和你的使女，以及與我們在一起的僕人都有餅有酒，甚麼都不缺。」","notes":[]},{"n":20,"t":"老人說：「願你平安！你所需用的我都會給你們，只是不可在廣場上過夜。」","notes":[]},{"n":21,"t":"於是老人領他到家裏，餵上驢。他們洗了腳，就吃喝起來。","notes":[]},{"n":22,"t":"他們心裏歡樂的時候，看哪，城中的無賴圍住房子，連連叩門，對老人，這家的主人說：「把那進你家的人帶出來，我們要與他交合。」","notes":[],"heads":["基比亞的惡行"]},{"n":23,"t":"這家的主人出來對他們說：「弟兄們，不要做這樣的惡事。這人既然進了我的家，你們就不要做這樣可恥的事。","notes":[]},{"n":24,"t":"看哪，我有個女兒還是處女，還有這人的妾，我把她們領出來任由你們污辱她們，就照你們看為好的對待她們吧！但對這人你們不要做這樣可恥的事。」","notes":[]},{"n":25,"t":"那些人卻不肯聽從他。那人抓住他的妾，把她拉出去給他們。他們強姦了她，整夜凌辱她，直到早晨，天色快亮才放她走。","notes":[]},{"n":26,"t":"到了早晨，婦人回來，仆倒在留她主人住宿的那人的家門前，直到天亮。","notes":[]},{"n":27,"t":"早晨，她的主人起來開了門，出去要上路。看哪，那婦人，他的妾倒在屋子門前，雙手搭在門檻上。","notes":[]},{"n":28,"t":"他對婦人說：「起來，我們走吧！」婦人卻沒有回應。那人就將她馱在驢上，起身回自己的地方去了。","notes":[]},{"n":29,"t":"到了家裏，他拿刀，抓住他的妾，把她的屍身切成十二塊，分送到以色列全境。","notes":[]},{"n":30,"t":"凡看見的人都說：「自從以色列人離開埃及地上來，直到今日，像這樣的事還沒有發生過，也沒有見過。大家應當想一想，商討一下再說。」","notes":[]}]},"20":{"heading":"以色列人準備打仗","verses":[{"n":1,"t":"於是以色列眾人從但到別是巴，以及從基列地出來，如同一人，聚集在米斯巴耶和華那裏。","notes":[]},{"n":2,"t":"以色列各支派中眾百姓的領袖，都站在神百姓的會中。拿刀的步兵共有四十萬。","notes":[]},{"n":3,"t":"便雅憫人聽見以色列人上了米斯巴。以色列人說：「請說，這惡事是怎麼發生的呢？」","notes":[]},{"n":4,"t":"那利未人，就是被害婦人的丈夫，回答說：「我和我的妾來到便雅憫的基比亞住宿。","notes":[]},{"n":5,"t":"基比亞人夜間起來攻擊我，包圍我住的屋子。他們想要殺我，並把我的妾污辱致死。","notes":[]},{"n":6,"t":"我把我的妾切成塊，分送到以色列得為業的全地，因為基比亞人在以色列中做了邪惡可恥的事。","notes":[]},{"n":7,"t":"看哪，你們大家，以色列人哪，在此提出你們的建議和對策吧！」","notes":[]},{"n":8,"t":"眾百姓都起來如同一人，說：「我們誰也不回自己的帳棚，誰也不回自己的家去！","notes":[]},{"n":9,"t":"現在，我們要這樣對付基比亞，照所抽的籤去攻打他們。","notes":[]},{"n":10,"t":"我們要在以色列各支派中，一百人選十人，一千人選一百人，一萬人選一千人，為那到便雅憫的迦巴去的士兵運糧；因為基比亞在以色列中行了可恥的事。」","notes":[]},{"n":11,"t":"於是以色列眾人彼此聯合如同一人，聚集攻擊那城。","notes":[]},{"n":12,"t":"以色列眾支派派人去，問便雅憫支派的各家說：「你們中間怎麼做了這樣的惡事呢？","notes":[]},{"n":13,"t":"現在你們要把基比亞的那些無賴交出來，我們好處死他們，從以色列中除掉這惡。」便雅憫人卻不肯聽從他們弟兄以色列人的話。","notes":[]},{"n":14,"t":"便雅憫人從各城聚集到基比亞，出來要與以色列人打仗。","notes":[]},{"n":15,"t":"那日，便雅憫人從各城裏徵召了拿刀的士兵，共有二萬六千，另外還從基比亞居民中徵召七百個精兵。","notes":[]},{"n":16,"t":"全軍中有特選的七百個精兵，都是慣用左手的，個個能用機弦甩石，毫髮不差。","notes":[]},{"n":17,"t":"以色列人，除了便雅憫之外，共徵召了四十萬拿刀的，個個都是戰士。","notes":[]},{"n":18,"t":"以色列人起來，上到伯特利去求問神說：「我們中間誰當首先上去與便雅憫人爭戰呢？」耶和華說：「猶大先上去。」","notes":[],"heads":["以色列人擊敗便雅憫人"]},{"n":19,"t":"以色列人早晨起來，對著基比亞安營。","notes":[]},{"n":20,"t":"以色列人出來與便雅憫人打仗，以色列人在基比亞對著他們擺陣。","notes":[]},{"n":21,"t":"便雅憫人從基比亞出來，當日把以色列中二萬二千人殺倒在地。","notes":[]},{"n":22,"t":"以色列人的士兵鼓起勇氣，在第一日擺陣的地方又擺陣。","notes":[]},{"n":23,"t":"因以色列人上去，在耶和華面前哀哭，直到晚上。他們求問耶和華說：「我可以再出兵與我弟兄便雅憫人打仗嗎？」耶和華說：「可以上去攻打他們。」","notes":[]},{"n":24,"t":"第二日，以色列人就上前攻擊便雅憫人。","notes":[]},{"n":25,"t":"便雅憫人也在第二日從基比亞出來與他們交戰，又把以色列人一萬八千個拿刀的士兵殺倒在地。","notes":[]},{"n":26,"t":"以色列眾人和全體士兵上到伯特利，坐在耶和華面前哭泣。那日，他們禁食直到晚上，又在耶和華面前獻燔祭和平安祭。","notes":[]},{"n":27,"t":"以色列人去求問耶和華；那時，神的約櫃在那裏。","notes":[]},{"n":28,"t":"那時，亞倫的孫子，以利亞撒的兒子非尼哈侍立在約櫃前。他們說：「我可以再出去與我弟兄便雅憫人打仗嗎？還是停戰呢？」耶和華說：「你們可以上去，因為明日我必把他交在你手中。」","notes":[]},{"n":29,"t":"以色列在基比亞的四圍設下埋伏。","notes":[]},{"n":30,"t":"第三日，以色列人又上去攻擊便雅憫人，在基比亞前擺陣，與前兩次一樣。","notes":[]},{"n":31,"t":"便雅憫人也出來迎敵，就被引誘出城外。在田間的兩條路上，一條通往伯特利，一條通往基比亞，他們像前兩次一樣，動手殺了約三十個以色列人。","notes":[]},{"n":32,"t":"便雅憫人說：「他們仍像以前一樣敗在我們面前。」但以色列人說：「讓我們逃跑，引誘他們離開城到路上來。」","notes":[]},{"n":33,"t":"以色列眾人都起來，在巴力‧他瑪擺陣，以色列的伏兵從馬利‧迦巴埋伏的地方衝上前去。","notes":[]},{"n":34,"t":"全以色列中的一萬精兵來到基比亞前，戰爭十分激烈。便雅憫人卻不知道災禍臨近了。","notes":[]},{"n":35,"t":"耶和華在以色列面前擊打便雅憫。那日，以色列人殲滅二萬五千一百個便雅憫人，都是拿刀的士兵。","notes":[]},{"n":36,"t":"便雅憫人看到自己戰敗了。以色列人因為信任在基比亞前所設的伏兵，就在便雅憫人面前假裝撤退。","notes":[],"heads":["以色列人得勝"]},{"n":37,"t":"伏兵迅速闖進基比亞；他們繼續前進，用刀殺死全城的人。","notes":[]},{"n":38,"t":"以色列人預先與伏兵約定在城內放火，以上騰的煙為信號。","notes":[]},{"n":39,"t":"以色列人從陣上撤退，便雅憫人動手殺死以色列人，約有三十個，就說：「他們仍像以前一樣敗在我們面前。」","notes":[]},{"n":40,"t":"當煙如柱一般從城中上騰的時候，便雅憫人回頭，看哪，全城已經濃煙沖天了。","notes":[]},{"n":41,"t":"以色列人又轉身回來，便雅憫人就很驚惶，因為看見災禍臨到自己了。","notes":[]},{"n":42,"t":"他們在以色列人面前轉身往曠野逃跑，戰況對他們不利，那從城裏出來的也去夾攻，殺滅他們。","notes":[]},{"n":43,"t":"以色列人圍攻便雅憫人，追趕他們，在他們歇腳之處，直到向日出方向的基比亞的對面，踐踏他們。","notes":[]},{"n":44,"t":"便雅憫人倒下的有一萬八千名，這些全都是勇士。","notes":[]},{"n":45,"t":"其餘的人轉身往曠野逃跑，到臨門巖去。以色列人在路上殺了五千人，如拾穗一樣，緊追他們直到基頓，又殺了二千人。","notes":[]},{"n":46,"t":"那日便雅憫人倒下的有二萬五千名，這些全都是拿刀的勇士。","notes":[]},{"n":47,"t":"有六百人轉身往曠野逃跑，到了臨門巖，在臨門巖住了四個月。","notes":[]},{"n":48,"t":"以色列人又轉回去攻擊便雅憫人，凡經過的各城，其中的人和牲畜都用刀殺了，又放火燒了所經過的一切城鎮。","notes":[]}]},"21":{"heading":"為便雅憫人找妻子","verses":[{"n":1,"t":"以色列人在米斯巴曾起誓說：「我們中誰都不把女兒嫁給便雅憫人。」","notes":[]},{"n":2,"t":"以色列人來到伯特利，坐在那裏直到晚上，在神面前放聲大哭，","notes":[]},{"n":3,"t":"說：「耶和華－以色列的神啊，為何以色列中會發生這樣的事，使以色列今日缺了一個支派呢？」","notes":[]},{"n":4,"t":"次日，百姓清早起來，在那裏築了一座壇，獻燔祭和平安祭。","notes":[]},{"n":5,"t":"以色列人說：「以色列各支派中，誰沒有同會眾一起上到耶和華那裏呢？」因為以色列人曾起重誓說：「凡不上米斯巴到耶和華那裏的，必被處死。」","notes":[]},{"n":6,"t":"以色列人憐憫他們的弟兄便雅憫，說：「如今以色列中斷絕一個支派了。","notes":[]},{"n":7,"t":"我們既然向耶和華起誓說，必不把我們的女兒嫁給便雅憫人，現在我們該怎麼辦，使他們剩下的人可以娶妻呢？」","notes":[]},{"n":8,"t":"他們又說：「以色列支派中誰沒有上米斯巴到耶和華那裏呢？」看哪，基列的雅比沒有一人進營到會眾那裏，","notes":[]},{"n":9,"t":"百姓被數點的時候，看哪，基列的雅比居民沒有一人在那裏。","notes":[]},{"n":10,"t":"會眾就派一萬二千名大勇士，吩咐他們說：「你們去用刀把基列的雅比居民連婦女帶孩子都殺了。","notes":[]},{"n":11,"t":"這是你們當做的事：要把所有男人和曾與男人同房共寢的女人全都殺了。」","notes":[]},{"n":12,"t":"他們在基列的雅比居民中，找到四百個未曾與男人同房共寢的處女，就帶她們到迦南地的示羅營裏。","notes":[]},{"n":13,"t":"全會眾派人到臨門巖的便雅憫人那裏，與他們講和。","notes":[]},{"n":14,"t":"當時便雅憫人回來了，以色列人就把所留下，基列的雅比活著的女子嫁給他們，可是還是不夠。","notes":[]},{"n":15,"t":"百姓憐憫便雅憫人，因為耶和華使以色列支派中有一個缺口。","notes":[]},{"n":16,"t":"會眾中的長老說：「便雅憫中的女子既然都除滅了，我們該怎麼辦，使剩下的人可以娶妻呢？」","notes":[]},{"n":17,"t":"他們又說：「便雅憫逃脫的人應當有地業，免得以色列中的一個支派被塗去。","notes":[]},{"n":18,"t":"只是我們不能把自己的女兒嫁給他們。」因為以色列人曾起誓說：「把女兒嫁給便雅憫人的必受詛咒。」","notes":[]},{"n":19,"t":"他們又說：「看哪，一年一度耶和華的節期正在示羅舉行。」示羅位於利波拿的南邊，伯特利的北邊，從伯特利往示劍大路的東邊。","notes":[]},{"n":20,"t":"他們吩咐便雅憫人說：「你們去，躲在葡萄園中，","notes":[]},{"n":21,"t":"觀看；看哪，若示羅的女子出來跳舞，你們就從葡萄園出來，各人從示羅的女子中搶一個為妻，然後到便雅憫地去。","notes":[]},{"n":22,"t":"他們的父親或兄弟若來與我們爭論，我們就對他們說：『請看我們的情面恩待這些人吧！因為我們在戰爭的時候沒有給他們任何人留下女子為妻。這次也不是你們給他們的，若是你們給的，就算有罪了。』」","notes":[]},{"n":23,"t":"於是便雅憫人就照樣做了，按照他們的人數，把從跳舞女子中搶來的娶為妻子，帶回自己的地業，重建城鎮，居住在其中。","notes":[]},{"n":24,"t":"那時以色列人離開那裏，各自回到自己的支派、宗族；他們從那裏起行，各自回到自己的地業去了。","notes":[]},{"n":25,"t":"那時，以色列中沒有王，各人照自己眼中看為對的去做。","notes":[]}]}},"RUT":{"1":{"heading":"以利米勒全家遷往摩押","verses":[{"n":1,"t":"士師統治的時候，國中有饑荒。在猶大的伯利恆，有一個人帶著妻子和兩個兒子往摩押地去寄居。","notes":[]},{"n":2,"t":"這人名叫以利米勒，他的妻子名叫拿娥米；他兩個兒子，一個名叫瑪倫，一個名叫基連，都是猶大伯利恆的以法他人。他們到了摩押地，就住在那裏。","notes":[]},{"n":3,"t":"後來拿娥米的丈夫以利米勒死了，剩下她和兩個兒子。","notes":[]},{"n":4,"t":"兩個兒子娶了摩押女子，一個名叫俄珥巴，第二個名叫路得，在那裏住了約有十年。","notes":[]},{"n":5,"t":"瑪倫和基連二人也死了，剩下拿娥米，沒有丈夫，也沒有兒子。","notes":[]},{"n":6,"t":"拿娥米與兩個媳婦起身，要從摩押地回去，因為她在摩押地聽見耶和華眷顧自己的百姓，賜糧食給他們。","notes":[],"heads":["路得跟拿娥米回伯利恆"]},{"n":7,"t":"她和兩個媳婦就起行，離開所住的地方，上路回猶大地去。","notes":[]},{"n":8,"t":"拿娥米對兩個媳婦說：「你們各自回娘家去吧！願耶和華恩待你們，像你們待已故的人和我一樣。","notes":[]},{"n":9,"t":"願耶和華使你們各自在新的丈夫家中得歸宿！」於是拿娥米與她們親吻，她們就放聲大哭，","notes":[]},{"n":10,"t":"對她說：「不，我們要與你一同回你的百姓那裏去。」","notes":[]},{"n":11,"t":"拿娥米說：「我的女兒啊，回去吧！為何要跟我去呢？我還能生兒子作你們的丈夫嗎？","notes":[]},{"n":12,"t":"我的女兒啊，回去吧！我年紀老了，不能再有丈夫。就算我還有希望，今夜有丈夫，而且也生了兒子，","notes":[]},{"n":13,"t":"你們豈能等著他們長大呢？你們能守住自己不嫁人嗎？我的女兒啊，不要這樣。我比你們更苦，因為耶和華伸手擊打我。」","notes":[]},{"n":14,"t":"兩個媳婦又放聲大哭，俄珥巴與婆婆吻別，但是路得卻緊跟著拿娥米。","notes":[]},{"n":15,"t":"拿娥米說：「看哪，你嫂嫂已經回她的百姓和她的神明那裏去了，你也跟你嫂嫂回去吧！」","notes":[]},{"n":16,"t":"路得說：「不要勸我離開你，轉去不跟隨你。你往哪裏去，我也往哪裏去；你在哪裏住，我也在哪裏住；你的百姓就是我的百姓；你的神就是我的神。","notes":[]},{"n":17,"t":"你死在哪裏，我也死在哪裏，葬在哪裏。只有死能使你我分離；不然，願耶和華重重懲罰我！」","notes":[]},{"n":18,"t":"拿娥米見路得決意要跟自己去，就不再對她說甚麼了。","notes":[]},{"n":19,"t":"於是二人同行，來到伯利恆。她們到了伯利恆，全城因她們騷動起來。婦女們說：「這是拿娥米嗎？」","notes":[]},{"n":20,"t":"拿娥米對她們說：「不要叫我拿娥米，要叫我瑪拉，因為全能者使我受盡了苦。","notes":["「拿娥米」意思是「甜」。","「瑪拉」意思是「苦」。"]},{"n":21,"t":"我滿滿地出去，耶和華使我空空地回來。耶和華使我受苦，全能者降禍於我。你們為何還叫我拿娥米呢？」","notes":[]},{"n":22,"t":"拿娥米從摩押地回來了，她的媳婦摩押女子路得跟她在一起。她們到了伯利恆，正是開始收割大麥的時候。","notes":[]}]},"2":{"heading":"路得在田間遇見波阿斯","verses":[{"n":1,"t":"拿娥米有一個親戚，是她丈夫以利米勒本族的人，名叫波阿斯，是個大財主。","notes":[]},{"n":2,"t":"摩押女子路得對拿娥米說：「讓我到田裏去拾取麥穗，我在誰的眼中蒙恩，就跟在誰的身後。」拿娥米說：「女兒啊，你去吧。」","notes":[]},{"n":3,"t":"路得就去了。她來到田間，在收割的人身後拾取麥穗。她恰巧來到以利米勒本族的人波阿斯那塊田裏。","notes":[]},{"n":4,"t":"看哪，波阿斯正從伯利恆來，對收割的人說：「願耶和華與你們同在！」他們對他說：「願耶和華賜福給你！」","notes":[]},{"n":5,"t":"波阿斯對監督收割的僕人說：「那是誰家的女子？」","notes":[]},{"n":6,"t":"監督收割的僕人回答說：「她是摩押女子，跟隨拿娥米從摩押地回來的。","notes":[]},{"n":7,"t":"她說：『請你容許我拾取麥穗，在收割的人身後撿禾捆中掉落的麥穗。』她就來了，從早晨直到如今，除了在屋子裏坐一會兒，她都留在這裏。」","notes":[]},{"n":8,"t":"波阿斯對路得說：「女兒啊，聽我說，不要到別人田裏去拾取麥穗，也不要離開這裏，要緊跟著我的女僕們。","notes":[]},{"n":9,"t":"你要看好我的僕人正在哪塊田收割，就跟著女僕們去。我已經吩咐僕人不可侵犯你。你渴了，可以到水缸那裏喝僕人打來的水。」","notes":[]},{"n":10,"t":"路得就臉伏於地叩拜，對他說：「我既是外邦女子，怎麼會在你眼中蒙恩，使你這樣照顧我呢？」","notes":[]},{"n":11,"t":"波阿斯回答她說：「自從你丈夫死後，凡你向婆婆所行的，以及你離開父母和你的出生地，到素不相識的百姓中，這些事人都告訴我了。","notes":[]},{"n":12,"t":"願耶和華照你所行的報償你。你來投靠在耶和華－以色列神的翅膀下，願你滿得他的報償。」","notes":[]},{"n":13,"t":"路得說：「我主啊，願我在你眼前蒙恩。我雖然不及你的一個婢女，你還安慰我，對你的婢女說關心的話。」","notes":[]},{"n":14,"t":"吃飯的時候，波阿斯對路得說：「你到這裏來吃些餅，把你的一塊蘸在醋裏。」路得就在收割的人旁邊坐下。波阿斯把烘了的穗子遞給她。她吃飽了，還有剩餘的。","notes":[]},{"n":15,"t":"她又起來拾取麥穗，波阿斯吩咐僕人說：「她即使在禾捆中拾取麥穗，也不可羞辱她。","notes":[]},{"n":16,"t":"你們還要從捆裏抽一些出來，留給她拾取，不可責備她。」","notes":[]},{"n":17,"t":"這樣，路得在田間拾取麥穗，直到晚上。她把所拾取的麥穗打了約有一伊法的大麥。","notes":[]},{"n":18,"t":"路得把所拾取的帶進城去給婆婆看，又把她吃飽所剩的拿出來，給了婆婆。","notes":[]},{"n":19,"t":"婆婆問她說：「你今日在哪裏拾取麥穗？在哪裏做工呢？願那照顧你的得福。」路得告訴婆婆，她在誰那裏做工，說：「我今日在一個名叫波阿斯的人那裏做工。」","notes":[]},{"n":20,"t":"拿娥米對媳婦說：「願那人蒙耶和華賜福，因為他不斷地恩待活人死人。」拿娥米又對她說：「那人是我們本族的人，是一個可以贖我們產業的至親。」","notes":[]},{"n":21,"t":"摩押女子路得說：「他還對我說：『你要緊跟著我的僕人拾取麥穗，直到他們把我所有的莊稼收割完畢。』」","notes":[]},{"n":22,"t":"拿娥米對媳婦路得說：「女兒啊，你要跟著他的女僕出去，免得你在別人的田間受人騷擾。」","notes":[]},{"n":23,"t":"於是路得緊跟著波阿斯的女僕拾取麥穗，直到大麥和小麥收割完畢。路得仍與婆婆同住。","notes":[]}]},"3":{"heading":"拿娥米為路得找歸宿","verses":[{"n":1,"t":"路得的婆婆拿娥米對她說：「女兒啊，我不該為你找個歸宿，使你享福嗎？","notes":[]},{"n":2,"t":"你與波阿斯的女僕常在一處，現在，波阿斯不是我們的親人嗎？看哪，他今夜將在禾場簸大麥。","notes":[]},{"n":3,"t":"你要沐浴抹膏，穿上外衣，下到禾場，一直到那人吃喝完了，都不要讓他認出你來。","notes":[]},{"n":4,"t":"他躺下的時候，你看準他躺臥的地方，就進去掀露他的腳，躺臥在那裏，他必告訴你所當做的事。」","notes":[]},{"n":5,"t":"路得說：「凡你所吩咐我的，我必遵行。」","notes":[]},{"n":6,"t":"路得就下到禾場，照她婆婆吩咐她的一切去做。","notes":[]},{"n":7,"t":"波阿斯吃喝完了，心情暢快，就去躺臥在麥堆旁邊。路得悄悄走來，掀露他的腳，躺臥在那裏。","notes":[]},{"n":8,"t":"到了半夜，那人驚醒，翻過身來，看哪，有個女子躺在他的腳旁。","notes":[]},{"n":9,"t":"他就說：「你是誰？」路得說：「我是你的使女路得。請你用你衣服的邊來遮蓋你的使女，因為你是可以贖我產業的至親。」","notes":[]},{"n":10,"t":"波阿斯說：「女兒啊，願你蒙耶和華賜福。你後來的忠誠比先前的更美，因為無論貧富的年輕人，你都沒有跟從。","notes":[]},{"n":11,"t":"女兒啊，現在不要懼怕，凡你所說的，我必為你做，因為我城裏的百姓都知道你是個賢德的女子。","notes":[]},{"n":12,"t":"現在，我的確是一個可以贖你產業的至親，可是還有一個人比我更親。","notes":[]},{"n":13,"t":"你今夜在這裏住宿，明早他若肯為你盡至親的本分，很好，就由他吧！倘若他不肯，我指著永生的耶和華起誓，我必為你盡上至親的本分。你只管躺到早晨。」","notes":[]},{"n":14,"t":"路得就在他腳旁躺到早晨，在人還無法彼此辨認的時候就起來了。波阿斯說：「不可讓人知道有女子到禾場來。」","notes":[]},{"n":15,"t":"他又對路得說：「把你所披的外衣拿來，握緊它。」她就握緊外衣，波阿斯量了六簸箕的大麥，幫路得扛上，他就進城去了。」","notes":["「他就進城去了」：有古卷和其他古譯本是「她就進城去了」。"]},{"n":16,"t":"路得回到婆婆那裏，婆婆說：「女兒啊，怎麼樣了？」路得就把那人向她所做的一切都告訴了婆婆，","notes":["「怎麼樣了」：原文直譯「你是誰」。"]},{"n":17,"t":"又說：「那人給了我這六簸箕的大麥，對我說：『你不可空手回去見婆婆。』」","notes":[]},{"n":18,"t":"婆婆說：「女兒啊，等著吧，看這事結果如何，因為那人今日不辦妥這事，必不罷休。」","notes":[]}]},"4":{"heading":"波阿斯娶路得","verses":[{"n":1,"t":"波阿斯上到城門，坐在那裏，看哪，波阿斯所說那個可以贖產業的至親經過。波阿斯說：「某某先生，請你轉回來，坐在這裏。」他就轉回來坐下。","notes":[]},{"n":2,"t":"波阿斯又請了本城的十個長老來，對他們說：「請你們坐在這裏。」他們就都坐下。","notes":[]},{"n":3,"t":"波阿斯對那至親說：「從摩押地回來的拿娥米，現在要賣我們弟兄以利米勒的那塊地。","notes":[]},{"n":4,"t":"我想我應該向你說清楚：你可以買那塊地，當著在座的眾人和我百姓的長老面前，你若要贖就贖吧！倘若你不贖就告訴我，讓我知道，因為除了你以外，沒有人可以先贖，在你之後才輪到我。」那人說：「我要贖。」","notes":["「你不贖」是根據一些古卷和七十士譯本；原文是「他不贖」。"]},{"n":5,"t":"波阿斯說：「你從拿娥米和摩押女子路得手中買這地的時候，也當買死人的妻子，使死人在產業上留名。」","notes":[]},{"n":6,"t":"那至親說：「這樣我就不能贖了，免得對我的產業有損。你儘管去贖我所當贖的吧，我不能贖了！」","notes":[]},{"n":7,"t":"從前，在以色列中要確認任何交易，無論是贖業或買賣，一方必須脫鞋給另一方。以色列中都以此為證。","notes":[]},{"n":8,"t":"那至親對波阿斯說：「你自己買吧！」於是把鞋脫了下來。","notes":[]},{"n":9,"t":"波阿斯對長老和所有在場的百姓說：「你們今日都是證人；凡屬以利米勒，以及基連和瑪倫的，我都從拿娥米手中買下來了。","notes":[]},{"n":10,"t":"我也娶瑪倫的妻子摩押女子路得，好讓死人可以在產業上留名，免得他的名在本族本鄉的城門中消失了。你們今日都是證人。」","notes":[]},{"n":11,"t":"在城門坐著的所有百姓和長老說：「我們都是證人。願耶和華使進你家的這女子，像建立以色列家的拉結和利亞二人一樣。又願你在以法他得亨通，在伯利恆有名聲。","notes":[]},{"n":12,"t":"願耶和華從這年輕女子賜你後裔，使你的家像她瑪從猶大所生法勒斯的家一樣。」","notes":[]},{"n":13,"t":"於是，波阿斯娶了路得為妻，與她同房。耶和華使她懷孕生了一個兒子。","notes":[],"heads":["大衛的家譜"]},{"n":14,"t":"婦女們對拿娥米說：「耶和華是應當稱頌的！因為他今日沒有使你斷絕可以贖產業的至親。願這孩子在以色列中得名聲。","notes":[]},{"n":15,"t":"他必振奮你的精神，奉養你的晚年，因為他是愛慕你的媳婦所生的。有這樣的媳婦，比有七個兒子更好！」","notes":[]},{"n":16,"t":"拿娥米接過孩子來，抱在懷中撫養他。","notes":[]},{"n":17,"t":"鄰居的婦人給孩子起名，說：「拿娥米得了一個孩子了！」她們就給他起名叫俄備得。俄備得是耶西的父親，是大衛的祖父。","notes":[]},{"n":18,"t":"這是法勒斯的後代：法勒斯生希斯崙；","notes":[]},{"n":19,"t":"希斯崙生蘭；蘭生亞米拿達；","notes":[]},{"n":20,"t":"亞米拿達生拿順；拿順生撒門；","notes":[]},{"n":21,"t":"撒門生波阿斯；波阿斯生俄備得；","notes":[]},{"n":22,"t":"俄備得生耶西；耶西生大衛。","notes":[]}]}},"1SA":{"1":{"heading":"以利加拿和他的家眷","verses":[{"n":1,"t":"以法蓮山區有一個拉瑪的瑣非人，名叫以利加拿，他是蘇弗的玄孫，託戶的曾孫，以利戶的孫子，耶羅罕的兒子，是以法蓮人。","notes":["「拉瑪的瑣非人」或譯「拉瑪‧瑣非人」。"]},{"n":2,"t":"他有兩個妻子：一個名叫哈拿，另一個名叫毗尼拿。毗尼拿有孩子，哈拿卻沒有孩子。","notes":[]},{"n":3,"t":"這人每年從本城上到示羅，敬拜萬軍之耶和華，向他獻祭。在那裏有以利的兩個兒子何弗尼和非尼哈當耶和華的祭司。","notes":[]},{"n":4,"t":"每逢獻祭的日子，以利加拿把祭肉分給他的妻子毗尼拿和毗尼拿所生的兒女。","notes":[]},{"n":5,"t":"他給哈拿的卻是雙分，因為他愛哈拿。耶和華卻不使哈拿生育。","notes":[]},{"n":6,"t":"她的對頭毗尼拿因耶和華不使哈拿生育，就常常惹她發怒，要使她生氣。","notes":[]},{"n":7,"t":"年年都是如此。每當她上到耶和華殿的時候，毗尼拿就這樣惹她發怒，以致她哭泣不吃飯。","notes":[]},{"n":8,"t":"她丈夫以利加拿對她說：「哈拿，你為何哭泣？為何不吃飯？為何傷心難過呢？有我不比有十個兒子更好嗎？」","notes":[]},{"n":9,"t":"他們在示羅吃喝完了，哈拿就站起來。祭司以利坐在耶和華殿門框旁邊的位子上。","notes":[],"heads":["哈拿和以利"]},{"n":10,"t":"哈拿心裏愁苦，就痛痛哭泣，向耶和華祈禱。","notes":[]},{"n":11,"t":"她許願說：「萬軍之耶和華啊，你若垂顧你使女的苦情，眷念不忘你的使女，賜你的使女一個子嗣，我必使他終生歸給耶和華，不用剃刀剃他的頭。」","notes":[]},{"n":12,"t":"哈拿在耶和華面前不住地祈禱，以利注意她的嘴。","notes":[]},{"n":13,"t":"哈拿心中默禱，只動嘴唇，聽不到她的聲音，因此以利以為她喝醉了。","notes":[]},{"n":14,"t":"以利對她說：「你要醉到幾時呢？不要再喝酒了！」","notes":[]},{"n":15,"t":"哈拿回答說：「我主啊，不是這樣。我是心裏愁苦的婦人，清酒烈酒都沒有喝，只在耶和華面前傾心吐意。","notes":[]},{"n":16,"t":"不要將你的使女看作不正經的女子。我因極其難過和生氣，所以一直禱告到如今。」","notes":[]},{"n":17,"t":"以利回答說：「平平安安地回去吧。願以色列的神允准你向他所求的！」","notes":[]},{"n":18,"t":"哈拿說：「願你的婢女在你眼前蒙恩。」於是婦人上路，去吃飯，臉上不再帶愁容了。","notes":[]},{"n":19,"t":"他們清早起來，在耶和華面前敬拜，就回去，往拉瑪自己的家裏。以利加拿和妻子哈拿同房，耶和華顧念哈拿。","notes":[],"heads":["撒母耳出生和奉獻"]},{"n":20,"t":"時候到了，哈拿懷孕生了一個兒子，給他起名叫撒母耳，說：「這是我從耶和華那裏求來的。」","notes":[]},{"n":21,"t":"以利加拿和他全家都上去，要向耶和華獻年祭和還願祭。","notes":[]},{"n":22,"t":"哈拿卻沒有上去，因為她對丈夫說：「等孩子斷了奶，我就帶他上去朝見耶和華，讓他永遠住在那裏。」","notes":[]},{"n":23,"t":"她丈夫以利加拿對她說：「就照你看為好的去做吧！可以留到兒子斷了奶，願耶和華應驗他的話。」於是婦人留在家裏乳養兒子，直到他斷了奶。","notes":[]},{"n":24,"t":"斷奶之後，她就帶著孩子，連同一頭三歲的公牛，一伊法細麵，一皮袋酒，上示羅耶和華的殿去。那時，孩子還小。","notes":["「一頭三歲的公牛」是根據死海古卷、七十士譯本和其他古譯本；原文是「三頭公牛」。","「一伊法細麵」：七十士譯本和其他古譯本是「餅和一伊法細麵」。"]},{"n":25,"t":"他們宰了公牛，就領孩子到以利面前。","notes":[]},{"n":26,"t":"婦人說：「我主啊，請容許我說，我向你，我的主起誓，從前在你這裏站著祈求耶和華的那婦人就是我。","notes":[]},{"n":27,"t":"我祈求為要得這孩子，耶和華已將我向他所求的賜給我了。","notes":[]},{"n":28,"t":"所以，我將這孩子獻給耶和華，使他終生歸給耶和華。」他就在那裏敬拜耶和華。","notes":[]}]},"2":{"heading":"哈拿的禱告","verses":[{"n":1,"t":"哈拿禱告說：「我的心因耶和華快樂，我的角因耶和華高舉。我的口向仇敵張開；我因你的救恩歡欣。","notes":[]},{"n":2,"t":"「沒有一位聖者像耶和華，除你以外沒有別的了，也沒有磐石像我們的神。","notes":[]},{"n":3,"t":"不要誇口說驕傲的話，也不要口出狂妄的言語，因耶和華是有知識的神，人的行為被他衡量。","notes":[]},{"n":4,"t":"勇士的弓折斷，跌倒的人以力量束腰。","notes":[]},{"n":5,"t":"飽足的人作雇工求食；飢餓的人也不再飢餓。不生育的生了七個；兒女多的反倒孤獨。","notes":[]},{"n":6,"t":"耶和華使人死，也使人活，使人下陰間，也使人往上升。","notes":[]},{"n":7,"t":"耶和華使人貧窮，也使人富足；使人降卑，也使人升高。","notes":[]},{"n":8,"t":"他從灰塵裏抬舉貧寒人，從糞堆中提拔貧窮人，使他們與貴族同坐，繼承榮耀的座位。地的柱子屬耶和華，他將世界立在其上。","notes":[]},{"n":9,"t":"「他必保護他聖民的腳步，但惡人卻在黑暗中毀滅，因為人不是靠力量得勝。","notes":[]},{"n":10,"t":"與耶和華相爭的，必被打碎；他必從天上打雷攻擊他們。耶和華審判地極的人，將力量賜給所立的王，高舉受膏者的角。」","notes":[]},{"n":11,"t":"以利加拿往拉瑪回自己的家去了。那孩子在以利祭司面前事奉耶和華。","notes":[]},{"n":12,"t":"以利的兩個兒子是無賴，不認識耶和華。","notes":[],"heads":["以利的兩個兒子"]},{"n":13,"t":"這二祭司對待百姓的規矩是這樣：凡有人獻祭，正煮肉的時候，祭司的僕人就手拿三齒的叉子來，","notes":[]},{"n":14,"t":"將叉子往盆裏，或鍋裏，或釜裏，或壺裏一插，插上來的肉，祭司都拿了去。他們對所有上到示羅的以色列人都這樣做。","notes":[]},{"n":15,"t":"甚至在未燒脂肪之前，祭司的僕人就來對獻祭的人說：「把肉給祭司，讓他烤吧。他不要拿你煮過的肉，要生的。」","notes":[]},{"n":16,"t":"獻祭的人若說：「他們必須先燒脂肪，然後你才可以隨意拿。」僕人就說：「不，你立刻給我，不然我就要搶了。」","notes":[]},{"n":17,"t":"這些年輕人的罪在耶和華面前非常嚴重，因為這些人藐視耶和華的祭物。","notes":[]},{"n":18,"t":"那時，撒母耳還是孩子，穿著細麻布的以弗得，侍立在耶和華面前。","notes":[],"heads":["撒母耳在示羅"]},{"n":19,"t":"他母親每年為他做一件小外袍，同丈夫上來獻年祭的時候帶來給他。","notes":[]},{"n":20,"t":"以利為以利加拿和他妻子祝福，說：「願耶和華由這婦人再賜你後裔，代替從耶和華求來的孩子。」他們就回自己的地方去了。","notes":[]},{"n":21,"t":"耶和華眷顧哈拿，她就懷孕生了三個兒子，兩個女兒。那孩子撒母耳在耶和華面前漸漸長大。","notes":[]},{"n":22,"t":"以利年紀老邁，聽見他兩個兒子對以色列眾人所做一切的事，又聽見他們與會幕門前伺候的婦人同寢，","notes":[],"heads":["預言以利家遭禍"]},{"n":23,"t":"就對他們說：「你們為何做這樣的事呢？我從這眾百姓聽見了你們的惡行。","notes":[]},{"n":24,"t":"我兒啊，不可這樣！我聽到耶和華的百姓傳出你們不好的名聲。","notes":["「我聽到...名聲」或譯「我聽到你們的名聲不好，你們使耶和華的百姓犯了罪」。"]},{"n":25,"t":"人若得罪人，有神可以裁決；人若得罪耶和華，誰能為他代求呢？」然而他們還是不聽父親的話，因為耶和華想要他們死。","notes":["「神」或譯「審判官」。"]},{"n":26,"t":"撒母耳這孩子漸漸長大，耶和華與人越發喜愛他。","notes":[]},{"n":27,"t":"有神人來見以利，對他說：「耶和華如此說：『你祖宗的家在埃及法老家的時候，我不是向他們顯現嗎？","notes":["「法老家」：死海古卷和七十士譯本是「法老家作奴僕」。"]},{"n":28,"t":"在以色列眾支派中，我不是揀選他作我的祭司，上我的祭壇，燒香，在我面前穿以弗得嗎？我不是將以色列人所獻的火祭都賜給你祖宗的家嗎？","notes":[]},{"n":29,"t":"你們為何踐踏我所吩咐獻在我居所的祭物和供物呢？你為何尊重你的兒子過於尊重我，將我百姓以色列所獻美好的祭物都拿去養肥你們自己呢？』","notes":["「你們為何<ins>.呢」：七十士譯本是「你們為何貪婪地注視著我所吩咐獻的祭物和供物呢」。"]},{"n":30,"t":"因此，耶和華－以色列的神說：『我確實說過，你和你祖宗的家必永遠行在我面前，但現在耶和華卻說，我絕不會這樣做。因為尊重我的，我必尊重他；藐視我的，他必被輕視。","notes":[]},{"n":31,"t":"看哪，日子將到，我要折斷你的膀臂和你祖宗家的膀臂，使你家中沒有一個老年人。","notes":[]},{"n":32,"t":"你在以色列人享福的時候必看見我居所的衰敗，你家中必永遠沒有一個老年人。","notes":["「你在</ins>.衰敗」：七十士譯本的一些抄本是「你必在痛苦中以貪婪的眼睛看著以色列人享福」。"]},{"n":33,"t":"你家中的人，我沒有從我壇前剪除的，必使你眼睛失明，心中憂傷。你家中所添的人口都必夭折。","notes":[]},{"n":34,"t":"你的兩個兒子何弗尼、非尼哈所遭遇的事是給你的預兆：他們二人必在同一日死亡。","notes":[]},{"n":35,"t":"我要為自己立一個忠心的祭司，他行事必照我的心、如我的意。我要為他建立堅固的家，他必天天行走在我受膏者的面前。","notes":[]},{"n":36,"t":"你家所剩下的人都必來叩拜他，求一塊銀子，一個餅，說：求你給我一個祭司的職分，好使我得點餅吃。』」","notes":[]}]},"3":{"heading":"耶和華向撒母耳顯現","verses":[{"n":1,"t":"那孩子撒母耳在以利面前事奉耶和華。在那些日子，耶和華的言語稀少，不常有異象。","notes":[]},{"n":2,"t":"那時，以利在自己的地方睡覺；他眼目開始昏花，不能看見。","notes":[]},{"n":3,"t":"神的燈還沒有熄滅，撒母耳睡在耶和華的殿內，神的約櫃就在那裏。","notes":[]},{"n":4,"t":"耶和華呼喚撒母耳，撒母耳說：「我在這裏！」","notes":[]},{"n":5,"t":"他跑到以利那裏，說：「你叫我嗎？我在這裏。」以利說：「我沒有叫你，回去睡吧。」他就回去睡了。","notes":[]},{"n":6,"t":"耶和華又呼喚撒母耳。撒母耳起來，到以利那裏，說：「你叫我嗎？我在這裏。」以利說：「我兒，我沒有叫你，回去睡吧。」","notes":[]},{"n":7,"t":"那時撒母耳還未認識耶和華，耶和華的話也未曾向他啟示。","notes":[]},{"n":8,"t":"耶和華第三次再呼喚撒母耳。撒母耳起來，到以利那裏，說：「你叫我嗎？我在這裏。」以利才明白是耶和華呼喚這小孩。","notes":[]},{"n":9,"t":"以利對撒母耳說：「你回去睡吧。他若再叫你，你就說：『耶和華啊，請說，僕人敬聽！』」撒母耳就回去，仍睡在原處。","notes":[]},{"n":10,"t":"耶和華來站著，像前幾次呼喚：「撒母耳！撒母耳！」撒母耳說：「請說，僕人敬聽！」","notes":[]},{"n":11,"t":"耶和華對撒母耳說：「看哪，我在以色列中必行一件事，凡聽見的人都必雙耳齊鳴。","notes":[]},{"n":12,"t":"我指著以利家所說的話，到了時候，必從頭到尾應驗在以利身上。","notes":[]},{"n":13,"t":"我曾告訴他，我必永遠懲罰他的家，因為他知道自己的兒子作惡，褻瀆神，卻不禁止他們。","notes":["「褻瀆神」是根據七十士譯本和其他古譯本；原文是「自招詛咒」。"]},{"n":14,"t":"所以我向以利家起誓：『以利家的罪孽，就是獻祭物和供物，也永不得贖。』」","notes":[]},{"n":15,"t":"撒母耳睡到天亮，就開了耶和華殿的門。撒母耳害怕，不敢將異象告訴以利。","notes":[]},{"n":16,"t":"以利呼喚撒母耳說：「我兒撒母耳！」撒母耳說：「我在這裏！」","notes":[]},{"n":17,"t":"以利說：「他對你說了甚麼話，你不要向我隱瞞。你若將他對你所說的話向我隱瞞一句，願神重重懲罰你。」","notes":[]},{"n":18,"t":"撒母耳就把一切話都告訴以利，並沒有隱瞞。以利說：「他是耶和華，願他照他看為好的去做。」","notes":[]},{"n":19,"t":"撒母耳長大了，耶和華與他同在，使他所說的話一句都不落空。","notes":[]},{"n":20,"t":"從但到別是巴，所有的以色列人都知道耶和華立撒母耳為先知。","notes":[]},{"n":21,"t":"耶和華又在示羅顯現，因為耶和華在示羅藉他的話向撒母耳啟示他自己。","notes":[]}]},"4":{"heading":"約櫃被擄","verses":[{"n":1,"t":"撒母耳的話傳遍了全以色列。以色列人出去與非利士人打仗，安營在以便‧以謝，非利士人安營在亞弗。","notes":[]},{"n":2,"t":"非利士人向以色列人擺陣。兩軍交戰的時候，以色列人敗在非利士人面前；非利士人在戰場上殺了他們約四千人。","notes":[]},{"n":3,"t":"百姓回到營裏，以色列的長老說：「耶和華今日為何使我們敗在非利士人面前呢？我們要將耶和華的約櫃從示羅抬到我們這裏來，好讓他來到我們中間，救我們脫離敵人的手掌。」","notes":[]},{"n":4,"t":"於是百姓派人到示羅，從那裏將坐在二基路伯上萬軍之耶和華的約櫃抬來。以利的兩個兒子何弗尼、非尼哈也與神的約櫃同來。","notes":[]},{"n":5,"t":"耶和華的約櫃到了營中，全以色列就大聲歡呼，連地都震動。","notes":[]},{"n":6,"t":"非利士人聽見歡呼的聲音，就說：「為何希伯來人在營裏這麼大聲歡呼呢？」他們知道耶和華的約櫃到了營中。","notes":[]},{"n":7,"t":"非利士人就懼怕，說：「有神明到了他們營中。」又說：「我們有禍了！從來不曾有這樣的事。","notes":[]},{"n":8,"t":"我們有禍了！誰能救我們脫離這些大能之神明的手呢？從前在曠野用各樣災禍擊打埃及人的，就是這些神明。","notes":[]},{"n":9,"t":"非利士人哪，要剛強，要作大丈夫，免得作希伯來人的奴僕，如同他們作你們的奴僕一樣。你們要作大丈夫，與他們爭戰。」","notes":[]},{"n":10,"t":"非利士人進攻，以色列人敗了，各往自己的家逃跑。被殺的人很多，以色列倒下的步兵有三萬。","notes":[]},{"n":11,"t":"神的約櫃被擄去，以利的兩個兒子何弗尼、非尼哈也都被殺了。","notes":[]},{"n":12,"t":"有一個便雅憫人從戰場上逃跑，衣服撕裂，頭蒙灰塵，當日來到示羅。","notes":[],"heads":["以利的死"]},{"n":13,"t":"他到了的時候，看哪，以利正坐在路旁的位子上觀望，為神的約櫃心裏擔憂。那人進城報信，全城的人就都呼喊起來。","notes":[]},{"n":14,"t":"以利聽見呼喊的聲音就說：「這喧嚷的聲音是甚麼呢？」那人急忙來報信給以利。","notes":[]},{"n":15,"t":"那時以利九十八歲了，兩眼發直，不能看見。","notes":[]},{"n":16,"t":"那人對以利說：「我是從戰場上來的，今日剛從戰場上逃回來。」以利說：「我兒，事情怎樣了？」","notes":[]},{"n":17,"t":"報信的回答說：「以色列人在非利士人面前逃跑，百姓中被殺的很多！你的兩個兒子何弗尼和非尼哈也都死了，並且神的約櫃已經被擄去了。」","notes":[]},{"n":18,"t":"他一提到神的約櫃，以利就從城門旁自己的位子上往後跌倒，折斷頸項而死，因為他年紀老邁，身體沉重。以利作以色列的士師四十年。","notes":[]},{"n":19,"t":"以利的媳婦，非尼哈的妻子懷孕將到產期，她聽見神的約櫃被擄，公公和丈夫都死了，就曲身生產，極其疼痛。","notes":[],"heads":["非尼哈遺孀的死"]},{"n":20,"t":"她將要死的時候，旁邊站著的婦人們對她說：「不要怕！你生了男孩了。」她不回答，也不放在心上。","notes":[]},{"n":21,"t":"她給孩子起名叫以迦博，說：「榮耀離開以色列了！」這是因為神的約櫃被擄去，又因為她公公和丈夫都死了。","notes":["「以迦博」意思是「沒有榮耀」。"]},{"n":22,"t":"她又說：「榮耀離開以色列，因為神的約櫃被擄去了。」","notes":[]}]},"5":{"heading":"約櫃在非利士人當中","verses":[{"n":1,"t":"非利士人擄去神的約櫃，從以便‧以謝帶到亞實突。","notes":[]},{"n":2,"t":"非利士人擄了神的約櫃，帶進大袞廟，放在大袞的旁邊。","notes":[]},{"n":3,"t":"次日，亞實突人清早起來，看哪，大袞仆倒在耶和華的約櫃前，臉伏於地，他們就扶起大袞，把它放回原處。","notes":[]},{"n":4,"t":"又次日，他們清早起來，看哪，大袞仆倒在耶和華的約櫃前，臉伏於地，並且大袞的頭和兩手都在門檻上折斷，只剩下大袞的軀幹。","notes":[]},{"n":5,"t":"因此，大袞的祭司和所有進大袞廟的人，都不踏亞實突的大袞廟的門檻，直到今日。","notes":[]},{"n":6,"t":"耶和華的手重重擊打亞實突人，使他們恐懼，使亞實突和亞實突周圍的人都生痔瘡。","notes":[]},{"n":7,"t":"亞實突人見這情況，就說：「以色列神的約櫃不可留在我們這裏，因為他的手重重擊打我們和我們的神明大袞」。","notes":[]},{"n":8,"t":"他們就派人去請非利士的眾領袖來聚集，對他們說：「我們向以色列神的約櫃應當怎樣做呢？」他們說：「可以把以色列神的約櫃運到迦特去。」於是他們把以色列神的約櫃運到那裏。","notes":[]},{"n":9,"t":"運到之後，耶和華的手擊打那城，使那城的人非常驚慌，無論大小都生痔瘡。","notes":[]},{"n":10,"t":"他們就把神的約櫃送到以革倫。神的約櫃到了以革倫，以革倫人就呼喊說：「他們把以色列神的約櫃運到我這裏，要害我和我的百姓！」","notes":[]},{"n":11,"t":"於是他們派人去請非利士的眾領袖來，說：「請你們把以色列神的約櫃送回原處，免得害死我和我的百姓！」原來神的手重重攻擊那城，死亡的恐懼瀰漫全城，","notes":[]},{"n":12,"t":"沒有死的人都受痔瘡的折磨。城裏的哀聲上達於天。","notes":[]}]},"6":{"heading":"送回約櫃","verses":[{"n":1,"t":"耶和華的約櫃在非利士人之地七個月。","notes":[]},{"n":2,"t":"非利士人召了祭司和占卜的來，說：「我們向耶和華的約櫃應當怎樣做呢？請指示我們要用甚麼方法把約櫃送回原處。」","notes":[]},{"n":3,"t":"他們說：「若要將以色列神的約櫃送回去，不可空手送回，一定要給他獻賠罪的禮物，然後你們才可以得痊癒，並且知道他的手為何不離開你們。」","notes":[]},{"n":4,"t":"非利士人說：「應當用甚麼獻為賠罪的禮物呢？」他們說：「當按照非利士領袖的數目，獻五個金痔瘡和五個金老鼠，因為你們眾人和領袖所遭遇的都是一樣的災禍。","notes":[]},{"n":5,"t":"當製造你們痔瘡的像和毀壞田地老鼠的像，並要將榮耀歸給以色列的神，或者他向你們和你們的神明，以及你們的田地，把手放輕些。","notes":[]},{"n":6,"t":"你們為何硬著心，像埃及人和法老硬著心一樣呢？神豈不是嚴厲對付埃及，使埃及人釋放以色列人，他們就走了嗎？","notes":[]},{"n":7,"t":"現在你們應當造一輛新車，把兩頭未曾負軛，還在哺乳的母牛套在車上，趕牛犢離開母牛，回家去。","notes":[]},{"n":8,"t":"你們要把耶和華的約櫃放在車上，把所獻賠罪的金器裝在匣子裏，放在櫃旁，送走櫃子，讓它去。","notes":[]},{"n":9,"t":"你們要觀察：車若直行過以色列的邊界，上到伯‧示麥去，這大災禍就是耶和華降在我們身上的；若不然，我們就知道，這不是他的手擊打我們，而是我們偶然遭遇的。」","notes":[]},{"n":10,"t":"非利士人就照樣做了。他們取了兩頭哺乳的母牛套在車上，把牛犢關在家裏，","notes":[]},{"n":11,"t":"把耶和華的約櫃和裝金老鼠以及金痔瘡像的匣子都放在車上。","notes":[]},{"n":12,"t":"牛直行大路，在往伯‧示麥的一條大道上，一面走一面叫，不偏左右。非利士的領袖跟在後面，直到伯‧示麥的地界。","notes":[]},{"n":13,"t":"那時，伯‧示麥人正在平原收割麥子，舉目看見約櫃，就歡歡喜喜地迎見它。","notes":[]},{"n":14,"t":"車到了伯‧示麥人約書亞的田間，就在那裏停了。在那裏有一塊大磐石，他們把車的木頭劈了，把兩頭母牛獻給耶和華為燔祭。","notes":[]},{"n":15,"t":"利未人將耶和華的約櫃和櫃子旁邊裝金器的匣子拿下來，放在大磐石上。當日伯‧示麥人獻上燔祭，又獻其他祭物給耶和華。","notes":[]},{"n":16,"t":"非利士人的五個領袖看見了，當日就回以革倫去。","notes":[]},{"n":17,"t":"非利士人獻給耶和華作賠罪的金痔瘡像如下：一個為亞實突，一個為迦薩，一個為亞實基倫，一個為迦特，一個為以革倫。","notes":[]},{"n":18,"t":"金老鼠的數目是按照非利士五個領袖的城鎮，就是堅固的城鎮和鄉村，以及大磐石。這磐石是安放耶和華約櫃的，到今日還在伯‧示麥人約書亞的田間。","notes":[]},{"n":19,"t":"耶和華擊殺伯‧示麥人，因為他們觀看他的約櫃。他擊殺了百姓七十人 。百姓因耶和華大大擊殺他們，就哀哭了。","notes":["「七十人」是根據一些古卷；原文是「七十人，五萬人」，可能指「七十人加五萬人」或「五萬人中的七十人」。","「耶和華...七十人」：七十士譯本是「主擊殺耶哥尼雅的子孫七十人，因為他們沒有和伯‧示麥人歡歡喜喜地迎見約櫃」。"],"heads":["約櫃在基列‧耶琳"]},{"n":20,"t":"伯‧示麥人說：「誰能在耶和華這位聖潔的神面前侍立呢？這約櫃可以從我們這裏上到誰那裏去呢？」","notes":[]},{"n":21,"t":"於是他們派使者到基列‧耶琳的居民那裏，說：「非利士人將耶和華的約櫃送回來了，你們下來將約櫃接了，上到你們那裏去吧！」","notes":[]}]},"7":{"heading":"撒母耳治理以色列","verses":[{"n":1,"t":"基列‧耶琳人就來了，將耶和華的約櫃接上去，抬到山上亞比拿達的家中，將他兒子以利亞撒分別為聖，看守耶和華的約櫃。","notes":[]},{"n":2,"t":"從約櫃留在基列‧耶琳的那天起，經過了許多日子，有二十年；以色列全家都哀哭歸向耶和華。","notes":[]},{"n":3,"t":"撒母耳對以色列全家說：「你們若全心回轉歸向耶和華，就要從你們中間除掉外邦的神明和亞斯她錄，預備你們的心歸向耶和華，單單事奉他，他必救你們脫離非利士人的手。」","notes":[]},{"n":4,"t":"以色列人就除掉諸巴力和亞斯她錄，單單事奉耶和華。","notes":[]},{"n":5,"t":"撒母耳說：「要召集以色列眾人到米斯巴去，我好為你們向耶和華禱告。」","notes":[]},{"n":6,"t":"他們就聚集在米斯巴，打水澆在耶和華面前。當日他們禁食，說：「我們得罪了耶和華。」撒母耳在米斯巴作以色列人的士師。","notes":[]},{"n":7,"t":"非利士人聽見以色列人聚集在米斯巴，非利士的領袖就上來要攻擊以色列。以色列人聽見，就懼怕非利士人。","notes":[]},{"n":8,"t":"以色列人對撒母耳說：「願你不住為我們呼求耶和華－我們的神，救我們脫離非利士人的手。」","notes":[]},{"n":9,"t":"撒母耳就把一隻吃奶的羔羊獻給耶和華作全牲的燔祭，為以色列人呼求耶和華，耶和華就應允他。","notes":[]},{"n":10,"t":"撒母耳正獻燔祭的時候，非利士人前來要與以色列爭戰。當日，耶和華打雷，發出極大的聲音，使非利士人潰亂，他們就敗在以色列面前。","notes":[]},{"n":11,"t":"以色列人從米斯巴出來，追趕非利士人，擊殺他們，直到伯‧甲的下邊。","notes":[]},{"n":12,"t":"撒母耳拿一塊石頭立在米斯巴和善的中間，給石頭起名叫以便‧以謝，說：「到如今耶和華都幫助我們。」","notes":[]},{"n":13,"t":"因此，非利士人被制伏了，不再入侵以色列境內。撒母耳有生之年，耶和華的手攻擊非利士人。","notes":[]},{"n":14,"t":"非利士人所奪取以色列的城鎮，從以革倫直到迦特，都歸回以色列了。以色列也從非利士人手中收回這些城所屬的地界。那時以色列與亞摩利人和平相處。","notes":[]},{"n":15,"t":"撒母耳一生作以色列的士師。","notes":[]},{"n":16,"t":"他每年巡行到伯特利、吉甲、米斯巴，在這些地方審判以色列人。","notes":[]},{"n":17,"t":"隨後他回到拉瑪，因為他的家在那裏；他在那裏審判以色列人，並且在那裏為耶和華築了一座壇。","notes":[]}]},"8":{"heading":"以色列人要求立王","verses":[{"n":1,"t":"撒母耳年紀老邁，就立他的兒子作以色列的士師。","notes":[]},{"n":2,"t":"他的長子名叫約珥，次子名叫亞比亞；他們在別是巴作士師。","notes":[]},{"n":3,"t":"他的兒子不行他的道，貪圖財利，收取賄賂，屈枉正直。","notes":[]},{"n":4,"t":"以色列的長老都聚集在拉瑪，來到撒母耳那裏，","notes":[]},{"n":5,"t":"對他說：「看哪，你年紀老了，你的兒子又不行你的道。現在請你為我們立一個王治理我們，像列國一樣。」","notes":[]},{"n":6,"t":"撒母耳不喜悅他們說「立一個王治理我們」，他就向耶和華禱告。","notes":[]},{"n":7,"t":"耶和華對撒母耳說：「你只管聽從百姓向你說的一切話，因為他們不是厭棄你，而是厭棄我，不要我作他們的王。","notes":[]},{"n":8,"t":"自從我領他們出埃及的日子到如今，他們離棄我，事奉別神；正像他們從前所做的一切事，現在他們也照樣向你做了。","notes":[]},{"n":9,"t":"現在你只管聽從他們的話，不過要嚴厲警告他們，告訴他們將來王會用甚麼方式管轄他們。」","notes":[]},{"n":10,"t":"撒母耳將耶和華一切的話轉告求他立王的百姓。","notes":[]},{"n":11,"t":"他說：「管轄你們的王必用這樣的方式：他必派你們的兒子為他駕車，趕馬，在他的戰車前奔跑。","notes":[]},{"n":12,"t":"他要為自己立千夫長、五十夫長；耕種他的田地，收割他的莊稼；打造他的兵器和車上的器械。","notes":[]},{"n":13,"t":"他必叫你們的女兒為他製造香膏，作廚師與烤餅的，","notes":[]},{"n":14,"t":"也必取你們最好的田地、葡萄園、橄欖園，賜給他的臣僕。","notes":[]},{"n":15,"t":"你們的糧食和葡萄園所出產的，他必徵收十分之一給他的官員和臣僕，","notes":[]},{"n":16,"t":"又必叫你們的僕人婢女，健壯的青年和你們的驢為他做工。","notes":[]},{"n":17,"t":"你們的羊群，他必徵收十分之一，你們自己也必作他的僕人。","notes":[]},{"n":18,"t":"那日，你們必因自己所選的王哀求耶和華，但那日耶和華卻不應允你們。」","notes":[]},{"n":19,"t":"百姓卻不肯聽撒母耳的話，說：「不！我們一定要一個王治理我們，","notes":[]},{"n":20,"t":"使我們像列國一樣，有王治理我們，率領我們，為我們爭戰。」","notes":[]},{"n":21,"t":"撒母耳聽見百姓這一切話，就稟告給耶和華聽。","notes":[]},{"n":22,"t":"耶和華對撒母耳說：「你只管聽從他們的話，為他們立一個王。」撒母耳對以色列人說：「去，你們各歸各城吧！」","notes":[]}]},"9":{"heading":"掃羅見撒母耳","verses":[{"n":1,"t":"有一個便雅憫人名叫基士，是便雅憫人亞斐亞的玄孫，比歌拉的曾孫，洗羅的孫子，亞別的兒子，是個大能的勇士。","notes":["「大能的勇士」或譯「大財主」。"]},{"n":2,"t":"他有一個兒子名叫掃羅，又健壯、又英俊，在以色列人中沒有一個可以與他相比；他比眾百姓高出一個頭。","notes":["「他比眾百姓高出一個頭」：原文直譯「從他的肩膀及以上，他都比眾百姓高」；10．23同。"]},{"n":3,"t":"掃羅的父親基士丟失了幾匹母驢，他就吩咐兒子掃羅說：「起來，帶一個僕人去尋找驢子。」","notes":[]},{"n":4,"t":"掃羅走過以法蓮山區，又過沙利沙地，都沒有找著。他們走過沙琳地，驢不在那裏，又走過便雅憫地，也沒有找到。","notes":[]},{"n":5,"t":"到了蘇弗地，掃羅對跟隨他的僕人說：「我們不如回去，免得我父親不為驢掛慮，反為我們擔憂。」","notes":[]},{"n":6,"t":"僕人對他說：「看哪，這城裏有一位神人，受人敬重，凡他所說的全都應驗。現在讓我們到他那裏去，或者他能指示我們當走的路。」","notes":[]},{"n":7,"t":"掃羅對僕人說：「看哪，我們若去，送甚麼給那人呢？我們袋子裏的食物都吃完了，也沒有禮物可以送給神人，我們還有些甚麼呢？」","notes":[]},{"n":8,"t":"僕人又回答掃羅說：「看哪，我手裏還有四分之一舍客勒的銀子，可以送給神人，請他指示我們當走的路。」","notes":[]},{"n":9,"t":"從前以色列中，若有人去求問神，就這麼說：「來，我們到先見那裏去吧！」因現在的先知，從前稱為先見。","notes":[]},{"n":10,"t":"掃羅對僕人說：「好主意！來，我們去吧。」於是他們往神人所住的城裏去了。","notes":[]},{"n":11,"t":"他們上坡要進城，遇見幾個少女出來打水，就問她們說：「先見有沒有在這裏呢？」","notes":[]},{"n":12,"t":"她們回答說：「有的，看哪，他就在你們前面。快！他今日正來到城裏，因為今日百姓要在丘壇獻祭。","notes":[]},{"n":13,"t":"你們一進城，他還沒有上丘壇吃祭物之前，就會遇見他。因為他沒有到，百姓不能吃，必須等他先為祭物祝謝，然後受邀的人才可以吃。現在就上去吧，因為這時候你們會遇見他。」","notes":[]},{"n":14,"t":"他們就上到那城，進入城中的時候，看哪，撒母耳正迎著他們來，要上丘壇去。","notes":[]},{"n":15,"t":"掃羅還沒有到的前一日，耶和華已經對撒母耳啟示說：","notes":[]},{"n":16,"t":"「明日這時候，我必使一個人從便雅憫地到你這裏來，你要膏他作我百姓以色列的君王。他必救我的百姓脫離非利士人的手，因為我眷顧我的百姓，他們的哀聲已上達於我。」","notes":["「我眷顧我的百姓」：七十士譯本是「我已看到我百姓的困苦」。"]},{"n":17,"t":"撒母耳看見掃羅的時候，耶和華對他說：「看哪，這就是我對你所說的人，他必治理我的百姓。」","notes":[]},{"n":18,"t":"掃羅在城門中走到撒母耳跟前，說：「請告訴我，先見的家在哪裏？」","notes":[]},{"n":19,"t":"撒母耳回答掃羅說：「我就是先見。你在我前面先上丘壇去，因為你們今日必跟我同席。明日早晨我送你走，會把你心裏一切的事都告訴你。","notes":[]},{"n":20,"t":"至於你前三日所丟失的幾匹母驢，你心裏不必掛慮，都已經找到了。以色列眾人所仰慕的是誰呢？不是仰慕你和你父的全家嗎？」","notes":[]},{"n":21,"t":"掃羅回答說：「我不是以色列支派中最小的便雅憫人嗎？我的家族不是便雅憫支派中最小的家族嗎？你為何對我說這樣的話呢？」","notes":[]},{"n":22,"t":"撒母耳領掃羅和他的僕人進了大廳，使他們在受邀的人中坐首位；受邀者約有三十個。","notes":[]},{"n":23,"t":"撒母耳對廚師說：「我交給你的那一份祭肉，吩咐你收存的，現在可以拿來。」","notes":[]},{"n":24,"t":"廚師就舉起祭肉的腿和腿上的部分，擺在掃羅面前。撒母耳說：「看哪，所存留的擺在你面前了。吃吧！因為這是為你保留到這特定的時候的，好讓你說，是我請了這百姓來。」當日，掃羅就與撒母耳同席。","notes":["「祭肉的腿和腿上的部分」：原文另譯「祭肉的腿和肥尾巴」。"]},{"n":25,"t":"他們從丘壇下來進城，撒母耳和掃羅在房頂上說話。","notes":[],"heads":["撒母耳膏掃羅作王"]},{"n":26,"t":"次日他們清早起來。黎明的時候，撒母耳呼叫在房頂上的掃羅，說：「起來，我好送你回去。」掃羅就起來，和撒母耳二人一同到外面去。","notes":[]},{"n":27,"t":"二人下到城邊，撒母耳對掃羅說：「你要吩咐僕人先走，僕人走了以後， 你要留在這裏，這時候我要將神的話傳給你聽。」","notes":[]}]},"10":{"heading":"掃羅受感說話","verses":[{"n":1,"t":"撒母耳拿一瓶膏油倒在掃羅的頭上，親吻他，說：「耶和華豈不是膏你作他產業的君王嗎？","notes":["「耶和華...君王嗎？」七十士譯本是「主膏你治理他百姓以色列。你要治理主的百姓，救他們脫離四圍敵人的手。這就是主膏你作他產業的君王的證據。」"]},{"n":2,"t":"你今日離開我之後，會在便雅憫境內的謝撒，靠近拉結的墳墓，遇見兩個人。他們會對你說：『你要找的幾匹母驢已經找到了。看哪，你父親不為驢子的事掛慮，反為你擔憂，說：我為兒子該做些甚麼呢？』","notes":[]},{"n":3,"t":"你從那裏往前走，到了他泊的橡樹那裏，會遇見三個往伯特利去敬拜神的人：一個帶著三隻小山羊，一個帶著三個餅，一個帶著一皮袋酒。","notes":[]},{"n":4,"t":"他們會向你問安，給你兩個餅，你就從他們手中接過來。","notes":[]},{"n":5,"t":"然後你要到神的山去，在那裏有非利士的駐軍。你到了城裏的時候，會遇見一隊先知從丘壇下來，前面有鼓瑟的、擊鼓的、吹笛的、彈琴的，他們都受感說話。","notes":[]},{"n":6,"t":"耶和華的靈必大大感動你，你就與他們一同受感說話，轉變成另一個人。","notes":[]},{"n":7,"t":"這徵兆臨到你，你就要趁機做該做的事，因為神與你同在。","notes":[]},{"n":8,"t":"你要在我以先下到吉甲。看哪，我必下到你那裏獻燔祭和平安祭。你要等候七日，等我到你那裏指示你當做的事。」","notes":[]},{"n":9,"t":"掃羅轉身離開撒母耳，神就改變他，賜給他另一顆心。當日這一切徵兆都應驗了。","notes":[]},{"n":10,"t":"他們來到那座山，看哪，有一隊先知遇見掃羅。神的靈大大感動他，他就在先知中受感說話。","notes":[]},{"n":11,"t":"所有先前認識掃羅的人看見了，看哪，他和先知一同受感說話，百姓就彼此說：「基士的兒子遇見了甚麼呢？掃羅也在先知中嗎？」","notes":[]},{"n":12,"t":"那地方有一個人說：「這些人的父親是誰呢？」因此就有一句俗語說：「掃羅也在先知中嗎？」","notes":[]},{"n":13,"t":"掃羅受感說完了話，就上丘壇去了。","notes":[]},{"n":14,"t":"掃羅的叔叔問掃羅和他的僕人說：「你們到哪裏去了？」他說：「我們找驢子去了。但我們找不到，就去了撒母耳那裏。」","notes":[]},{"n":15,"t":"掃羅的叔叔說：「告訴我撒母耳對你們說了些甚麼。」","notes":[]},{"n":16,"t":"掃羅對他的叔叔說：「他明明告訴我們，驢子已經找到了。」至於撒母耳所說君王的事，掃羅沒有告訴叔叔。","notes":[]},{"n":17,"t":"撒母耳召集百姓到米斯巴耶和華那裏。","notes":[],"heads":["抽籤得掃羅為王"]},{"n":18,"t":"他對以色列眾人說：「耶和華－以色列的神如此說：『我領以色列出埃及，救你們脫離埃及人的手，以及脫離欺壓你們各國之人的手。』","notes":[]},{"n":19,"t":"你們今日卻厭棄救你們脫離一切災禍和患難的神，對他說：『求你立一個王治理我們。』現在你們應當按支派和宗族站在耶和華面前。」","notes":[]},{"n":20,"t":"於是，撒母耳叫以色列眾支派近前來抽籤，抽到了便雅憫支派。","notes":[]},{"n":21,"t":"然後，他叫便雅憫支派按宗族近前來，抽到了瑪特利族，接著又抽到了基士的兒子掃羅。眾人尋找他卻找不到，","notes":[]},{"n":22,"t":"就再問耶和華說：「那人來到這裏了沒有？」耶和華說：「看哪，他藏在物品堆中。」","notes":[]},{"n":23,"t":"眾人就跑去從那裏領他出來。他站在百姓中間，比眾百姓高出一個頭。","notes":[]},{"n":24,"t":"撒母耳對眾百姓說：「你們看到了耶和華所揀選的人嗎？眾百姓中沒有人可以與他相比。」眾百姓就歡呼說：「願王萬歲！」","notes":[]},{"n":25,"t":"撒母耳將君王的典章對百姓說明，又記在書上，放在耶和華面前，然後撒母耳遣散眾百姓，各回自己的家去了。","notes":[]},{"n":26,"t":"掃羅也往基比亞自己的家去，有一群心中被神感動的勇士跟隨他。","notes":[]},{"n":27,"t":"但有些無賴之輩說：「這人怎麼能救我們呢？」他們就藐視他，不送禮物給他。掃羅卻保持沉默。","notes":[]}]},"11":{"heading":"掃羅擊敗亞捫人","verses":[{"n":1,"t":"亞捫人拿轄上來，對著基列的雅比安營。雅比眾人對拿轄說：「你與我們立約，我們就服事你。」","notes":[]},{"n":2,"t":"亞捫人拿轄對他們說：「你們若由我挖出你們各人的右眼，以此凌辱以色列眾人，我就與你們立約。」","notes":[]},{"n":3,"t":"雅比的長老對他說：「求你寬容我們七日，等我們派人到以色列的全境去。若沒有人來救我們，我們就出來歸順你。」","notes":[]},{"n":4,"t":"使者到了掃羅住的基比亞，把這事說給百姓聽，眾百姓就都放聲大哭。","notes":[]},{"n":5,"t":"看哪，掃羅正從田間趕牛回來，說：「百姓為甚麼哭呢？」眾人把雅比人的話告訴他。","notes":[]},{"n":6,"t":"掃羅聽見這些話，就被神的靈催逼，大發怒氣。","notes":[]},{"n":7,"t":"他把一對牛切成小塊，吩咐使者傳送到以色列全境，說：「凡不出來跟隨掃羅和撒母耳的，就必這樣待他的牛。」耶和華使百姓懼怕，他們就都出來如同一人。","notes":[]},{"n":8,"t":"掃羅在比色數點他們：以色列人有三十萬，猶大人有三萬。","notes":[]},{"n":9,"t":"他們對那些來的使者說：「你們要對基列的雅比人這樣說，明天太陽快到中午的時候，你們必得解救。」使者回去告訴雅比人，他們就歡喜了。","notes":[]},{"n":10,"t":"於是雅比人對亞捫人說：「明日我們出來歸順你們，可以照你們看為好的待我們。」","notes":[]},{"n":11,"t":"第二日，掃羅把百姓分為三隊，在清晨換崗哨的時候入侵亞捫人的軍營，擊殺他們直到中午的時候。逃脫的人都分散了，甚至沒有兩個人同在一起。","notes":[]},{"n":12,"t":"百姓對撒母耳說：「那說『掃羅豈能作我們的王』的是誰呢？把他們交出來，我們好處死他們。」","notes":[]},{"n":13,"t":"掃羅說：「今日耶和華在以色列中施行拯救，所以今日不可處死人。」","notes":[]},{"n":14,"t":"撒母耳對百姓說：「來，我們到吉甲去，在那裏開始新的王國。」","notes":[]},{"n":15,"t":"眾百姓到了吉甲那裏，在耶和華面前擁立掃羅為王，又在耶和華面前獻平安祭。掃羅和以色列眾人在那裏都非常歡喜。","notes":[]}]},"12":{"heading":"撒母耳臨別贈言","verses":[{"n":1,"t":"撒母耳對以色列眾人說：「看哪，我已聽了你們對我所說一切的話，為你們立了一個王。","notes":[]},{"n":2,"t":"現在，看哪，有這王行走在你們前面。我已年老髮白，看哪，我的兒子都在你們這裏。我從幼年直到今日都行走在你們前面。","notes":[]},{"n":3,"t":"我在這裏，你們要在耶和華和他的受膏者面前為我作證，我奪過誰的牛，搶過誰的驢，欺負過誰，虐待過誰，從誰手裏收過賄賂而蒙蔽自己的眼目呢？若有，我必償還。」","notes":[]},{"n":4,"t":"眾人說：「你未曾欺負我們，虐待我們，也未曾從任何人手裏收過任何東西。」","notes":[]},{"n":5,"t":"撒母耳對他們說：「你們在我手裏沒有找著甚麼，有耶和華在你們中間作證，也有他的受膏者今日作證。」他們說：「願耶和華作證。」","notes":["「他們說」是根據七十士譯本；原文是「他說」。"]},{"n":6,"t":"撒母耳對百姓說：「從前立摩西和亞倫，又領你們祖先出埃及地的是耶和華。","notes":[]},{"n":7,"t":"現在你們要站住，讓我在耶和華面前，以耶和華向你們和你們祖先所行一切公義的事來和你們爭辯。","notes":[]},{"n":8,"t":"從前雅各到了埃及，後來你們的祖先呼求耶和華，耶和華就差遣摩西和亞倫領你們的祖先出埃及，來到這地方居住。","notes":[]},{"n":9,"t":"他們卻忘記耶和華－他們的神，他就把他們交給夏瑣將軍西西拉的手中，以及非利士人和摩押王的手中。於是這些人常來攻擊他們。","notes":["「交給<ins>.手中」：原文是「賣給</ins>.手中」。"]},{"n":10,"t":"他們呼求耶和華說：『我們離棄了耶和華去事奉諸巴力和亞斯她錄，我們有罪了。現在求你救我們脫離仇敵的手，我們必事奉你。』","notes":[]},{"n":11,"t":"耶和華就差遣耶路巴力、比但、耶弗他、撒母耳救你們脫離四圍仇敵的手，你們才安然居住。","notes":[]},{"n":12,"t":"你們見亞捫人的王拿轄來攻擊你們，就對我說：『不，要有一個王治理我們。』其實耶和華－你們的神是你們的王。","notes":[]},{"n":13,"t":"現在，看哪，這就是你們所選的、你們所求的王。看哪，耶和華已經為你們立王了。","notes":[]},{"n":14,"t":"你們若敬畏耶和華，事奉他，聽從他的話，不違背耶和華的命令，你們和治理你們的王也都跟從耶和華－你們的神就好了。","notes":[]},{"n":15,"t":"倘若不聽從耶和華的話，違背他的命令，耶和華的手必攻擊你們，像從前攻擊你們祖先一樣。","notes":[]},{"n":16,"t":"現在你們要站住，看耶和華在你們眼前要行的一件大事。","notes":[]},{"n":17,"t":"這不是割麥子的時候嗎？我求告耶和華，他必打雷降雨，讓你們知道並且看出，你們為自己求立王的事在耶和華眼前是犯大罪了。」","notes":[]},{"n":18,"t":"於是撒母耳求告耶和華，耶和華就在這日打雷降雨，眾百姓就非常懼怕耶和華和撒母耳。","notes":[]},{"n":19,"t":"眾百姓對撒母耳說：「請你為僕人向耶和華－你的神禱告，免得我們死亡，因為我們求立王的事，正是罪上加罪了。」","notes":[]},{"n":20,"t":"撒母耳對百姓說：「不要懼怕！你們雖然行了這惡，卻不要偏離耶和華，只要盡心事奉他。","notes":[]},{"n":21,"t":"不可偏離去隨從那沒有益處、不能救人的虛無的神明，因為它們是虛無的。","notes":["「虛無的神明」：原文是「虛無」。"]},{"n":22,"t":"耶和華必因他大名的緣故不撇棄他的子民，因為耶和華喜悅你們作他的子民。","notes":[]},{"n":23,"t":"至於我，我如果停止為你們禱告，就得罪耶和華了，我絕不會這樣做。我必以善道正路指教你們。","notes":[]},{"n":24,"t":"但你們要敬畏耶和華，誠誠實實地盡心事奉他，因你們要留意，他向你們所行的事何等大。","notes":[]},{"n":25,"t":"你們若不斷作惡，你們和你們的王必一同滅亡。」","notes":[]}]},"13":{"heading":"與非利士人爭戰","verses":[{"n":1,"t":"掃羅登基的時候年三十歲，作以色列王二年。","notes":["「三十」是根據七十士譯本的一些後期抄本，原文沒有。","「二年」指大衛受膏以前的年數，根據徒13．21，掃羅作王四十年。"]},{"n":2,"t":"掃羅從以色列中選出三千人：二千跟隨掃羅在密抹和伯特利山區，一千跟隨約拿單在便雅憫的基比亞。其餘的百姓，掃羅打發他們各自回自己的帳棚去了。","notes":[]},{"n":3,"t":"約拿單攻擊非利士人在迦巴的駐軍，非利士人聽見了這事。掃羅就在遍地吹角，說：「讓希伯來人都聽見。」","notes":["「非利士人聽見了...都聽見。」原文另譯「非利士人聽見了這事，說：『希伯來人反叛了！』掃羅就在遍地吹角。」"]},{"n":4,"t":"以色列眾人聽見掃羅攻擊非利士的駐軍，又聽見以色列為非利士人所憎惡，百姓就跟隨掃羅，在吉甲集合。","notes":[]},{"n":5,"t":"非利士人集合，要與以色列人作戰。他們有戰車三萬輛，騎兵六千，士兵像海邊的沙那樣多。他們上來，在伯‧亞文東邊的密抹安營。","notes":[]},{"n":6,"t":"以色列人見自己危急，軍隊被圍攻，百姓就藏在山洞、叢林、巖隙、地窖和深坑中。","notes":[]},{"n":7,"t":"有些希伯來人過了約旦河，逃到迦得和基列地。掃羅還在吉甲，所有的人都戰戰兢兢地跟隨他。","notes":[]},{"n":8,"t":"掃羅照著撒母耳所定的日期等了七日。但是，撒母耳還沒有來到吉甲，百姓就離開掃羅散去了。","notes":[],"heads":["掃羅不合法的獻祭"]},{"n":9,"t":"於是掃羅說：「把燔祭和平安祭帶到我這裏來。」掃羅就獻上燔祭。","notes":[]},{"n":10,"t":"他剛獻完燔祭，看哪，撒母耳就到了。掃羅出去迎接他，向他問安。","notes":[]},{"n":11,"t":"撒母耳說：「你做了甚麼事啊？」掃羅說：「因為我見百姓離開我散去，你又不照所定的日期來到，而且非利士人已在密抹集合；","notes":[]},{"n":12,"t":"我說：『現在非利士人已經下到吉甲來攻擊我，可是我還沒有向耶和華禱告。』所以我就勉強獻上燔祭。」","notes":[]},{"n":13,"t":"撒母耳對掃羅說：「你做了糊塗事了，沒有遵守耶和華－你神吩咐你的命令。不然，耶和華會在以色列中堅立你的國度，直到永遠。","notes":[]},{"n":14,"t":"現在你的國度必不長久。耶和華已經尋著一個合他心意的人，立他作百姓的君王，因為你沒有遵守耶和華所吩咐你的。」","notes":[]},{"n":15,"t":"撒母耳就起來，從吉甲上到便雅憫的基比亞。掃羅數點跟隨他的百姓，約有六百人。","notes":[]},{"n":16,"t":"掃羅和他兒子約拿單，以及跟隨他們的百姓，都住在便雅憫的迦巴，非利士人卻在密抹安營。","notes":[]},{"n":17,"t":"有突擊隊從非利士營中出來，分成三隊：一隊往俄弗拉到書亞地去，","notes":[]},{"n":18,"t":"一隊往伯‧和崙去，一隊往邊界，下望朝著曠野的洗波音谷。","notes":[]},{"n":19,"t":"那時，以色列全地找不到一個鐵匠，因為非利士人說：「恐怕希伯來人製造刀槍。」","notes":[]},{"n":20,"t":"以色列眾人要磨鋤、犁、斧、鏟，就各自下到非利士人那裏去磨。","notes":[]},{"n":21,"t":"磨鋤或犁的價錢是三分之二舍客勒，磨斧或修整刺棒的價錢是三分之一舍客勒。","notes":[]},{"n":22,"t":"所以到了戰爭的日子，所有跟隨掃羅和約拿單的百姓找不到一個手裏有刀有槍的，惟掃羅和他兒子約拿單有。","notes":[]},{"n":23,"t":"非利士人的一隊駐軍出來，到密抹的隘口。","notes":[]}]},"14":{"heading":"約拿單的戰績","verses":[{"n":1,"t":"有一日，掃羅的兒子約拿單對拿他兵器的青年說：「來，我們過去到非利士的駐軍那裏。」但他沒有告訴父親。","notes":[]},{"n":2,"t":"掃羅在基比亞的郊外，坐在米磯崙的石榴樹下，跟隨他的百姓約有六百人。","notes":[]},{"n":3,"t":"在那裏有亞希突的兒子亞希亞，穿著以弗得。亞希突是以迦博的哥哥，非尼哈的兒子，以利的孫子。以利從前在示羅作耶和華的祭司。約拿單去了，百姓卻不知道。","notes":[]},{"n":4,"t":"約拿單要從隘口過到非利士駐軍那裏去。這隘口兩邊各有一座齒狀峭壁：一座名叫播薛，另一座名叫西尼；","notes":[]},{"n":5,"t":"一座向北，對著密抹，一座向南，對著迦巴。","notes":[]},{"n":6,"t":"約拿單對拿兵器的青年說：「來，我們過去到那些未受割禮之人的駐軍那裏，或者耶和華為我們施展能力，因為耶和華使人得勝，不在乎人多人少。」","notes":["「因為<ins>.人少」：原文直譯「不論人多人少，都不能攔阻耶和華拯救我們。」"]},{"n":7,"t":"拿兵器的對他說：「隨你的心意做吧。你上去，看哪，我一定跟隨你，與你同心。」","notes":[]},{"n":8,"t":"約拿單說：「看哪，我們要過去到那些人那裏，在他們那裏展現我們自己。","notes":[]},{"n":9,"t":"他們若對我們這麼說：『站住，等我們到你們那裏去』，我們就站在原地，不上他們那裏去；","notes":[]},{"n":10,"t":"但他們若這麼說：『上到我們這裏來吧』，我們就上去，因為耶和華把他們交在我們手裏了。這就是我們的憑據。」","notes":[]},{"n":11,"t":"二人就讓非利士的駐軍看見。非利士人說：「看哪，希伯來人從躲藏的洞穴裏出來了！」","notes":[]},{"n":12,"t":"站崗的士兵對約拿單和拿兵器的人說：「上到這裏來，我們有一件事要告訴你們。」約拿單就對拿兵器的人說：「跟我上去，因為耶和華把他們交在以色列人手裏了。」","notes":[]},{"n":13,"t":"約拿單手腳並用爬上去，拿兵器的人跟隨他。非利士人仆倒在約拿單面前，拿兵器的人跟著他，殺死他們。","notes":[]},{"n":14,"t":"約拿單和拿兵器的人第一次擊殺的約有二十人，都在一畝 地的半犁溝之內。","notes":["「畝」：原文音譯「策密德」，古希伯來面積單位；參「度量衡表」。"]},{"n":15,"t":"於是在軍營、在田野、在眾百姓中，人心惶惶，駐軍和突擊隊都戰兢；地也震動，這是從神那裏來的驚恐。","notes":["「這是</ins>.驚恐」或譯「戰兢之勢甚大」。"]},{"n":16,"t":"在便雅憫的基比亞，掃羅的哨兵觀看，看哪，非利士全軍潰亂，四處亂竄。","notes":[],"heads":["非利士人敗退"]},{"n":17,"t":"掃羅就對跟隨他的百姓說：「你們去數點人數，看是誰從我們這裏出去。」他們一數點，看哪，約拿單和拿兵器的人不在其中。","notes":[]},{"n":18,"t":"那時神的約櫃在以色列人那裏。掃羅對亞希亞說：「你把神的約櫃請到這裏來。」","notes":["「神的約櫃」：七十士譯本是「以弗得」。"]},{"n":19,"t":"掃羅正與祭司說話的時候，非利士營中的騷亂越來越劇烈；掃羅就對祭司說：「停手吧！」","notes":[]},{"n":20,"t":"掃羅和所有跟隨他的百姓都集合，來到戰場，看哪，非利士人用刀互相擊殺，大大混亂。","notes":[]},{"n":21,"t":"那先前由四方來跟隨非利士人、在他們營中的希伯來人，現在也轉過來幫助跟隨掃羅和約拿單的以色列人了。","notes":[]},{"n":22,"t":"那藏在以法蓮山區的以色列眾人聽說非利士人逃跑，就出來緊緊地追擊他們。","notes":[]},{"n":23,"t":"那日，耶和華使以色列人得勝，戰爭一直打到伯‧亞文。","notes":[]},{"n":24,"t":"那日，以色列人非常困憊，因為掃羅叫百姓起誓說：「凡不等到晚上我向敵人報完了仇就吃東西的，必受詛咒。」因此所有的百姓都沒有嘗食物。","notes":[],"heads":["掃羅草率的誓言"]},{"n":25,"t":"所有的百姓進入樹林，見地面上有蜜。","notes":["「百姓」：原文是「地」。"]},{"n":26,"t":"百姓進了樹林，看哪，有蜜流出來，卻沒有人敢用手取蜜入口，因為百姓怕那誓言。","notes":[]},{"n":27,"t":"約拿單沒有聽見他父親叫百姓起誓，所以他伸出手中的杖，以杖頭蘸在蜂房裏，用手取回送入口內，他的眼睛就明亮了。","notes":[]},{"n":28,"t":"百姓中有一人對他說：「你父親曾叫百姓嚴嚴地起誓說，今日吃東西的人必受詛咒；因此百姓就疲乏了。」","notes":[]},{"n":29,"t":"約拿單說：「我父親給這地添麻煩了。你們看，我嘗了這一點蜜，眼睛就明亮了。","notes":[]},{"n":30,"t":"今日百姓若隨意吃了從仇敵奪來的東西，現在擊殺的非利士人豈不更多嗎？」","notes":[]},{"n":31,"t":"這日，以色列人擊殺非利士人，從密抹直到亞雅崙。但百姓非常疲乏，","notes":[]},{"n":32,"t":"就急著撲向掠物，奪取牛羊和牛犢，宰於地上，連肉帶血吃了。","notes":[]},{"n":33,"t":"有人告訴掃羅說：「看哪，百姓吃帶血的肉，得罪耶和華了。」掃羅說：「你們行了詭詐，今日把一塊大石頭滾到我這裏來吧。」","notes":[]},{"n":34,"t":"掃羅又說：「你們分散到百姓中，對他們說，你們各人把牛羊牽到我這裏來宰了吃，不可吃帶血的肉得罪耶和華。」那夜，所有的百姓把自己手中的牛牽到那裏宰了。","notes":["「自己手中的牛」：七十士譯本是「自己手中所有的」。"]},{"n":35,"t":"掃羅為耶和華築了一座壇，這是他開始為耶和華築的壇。","notes":[]},{"n":36,"t":"掃羅說：「我們要在夜裏下去追趕非利士人，搶掠他們，直到天亮，不給他們留下一人。」眾百姓說：「你看怎樣好就做吧！」祭司說：「我們要先在這裏親近神。」","notes":[]},{"n":37,"t":"掃羅求問神說：「我可以下去追趕非利士人嗎？你把他們交在以色列人手裏嗎？」這日神沒有回答他。","notes":[]},{"n":38,"t":"掃羅說：「百姓中的眾領袖，你們都要近前來到這裏，查明今日這罪是怎樣發生的。","notes":[]},{"n":39,"t":"我指著拯救以色列的永生的耶和華起誓，就是我兒子約拿單犯了罪，他也必被處死。」但眾百姓中無人回答他。","notes":[]},{"n":40,"t":"掃羅對以色列眾人說：「你們站在一邊，我與我兒子約拿單也站在一邊。」百姓對掃羅說：「你看怎樣好就做吧！」","notes":[]},{"n":41,"t":"掃羅向耶和華－以色列的神禱告說：「求你指示正確的答案。」抽中的是掃羅和約拿單，百姓盡都無事。","notes":[]},{"n":42,"t":"掃羅說：「你們再抽籤，看是我，還是我兒子約拿單。」抽中的是約拿單。","notes":[]},{"n":43,"t":"掃羅對約拿單說：「你告訴我，你做了甚麼事？」約拿單說：「我只是用手中的杖，以杖頭蘸了一點蜜嘗嘗，看哪，我就要死嗎？」","notes":[]},{"n":44,"t":"掃羅說：「約拿單哪，你一定要死！若不然，願神重重懲罰我。」","notes":[]},{"n":45,"t":"百姓對掃羅說：「約拿單在以色列中大行拯救，豈可死呢？絕對不可！我們指著永生的耶和華起誓，連他的一根頭髮也不可落地，因為他今日與神一同做事。」於是百姓救約拿單免了死亡。","notes":[]},{"n":46,"t":"掃羅上去，不追趕非利士人，非利士人也回本地去了。","notes":[]},{"n":47,"t":"掃羅執掌以色列的國權，攻打他四圍所有的仇敵，就是摩押人、亞捫人、以東人和瑣巴諸王，以及非利士人。他無論往何處去，都打敗他們。","notes":[],"heads":["掃羅的王權和家眷"]},{"n":48,"t":"掃羅奮勇作戰，擊敗亞瑪力人，救了以色列脫離搶掠他們之人的手。","notes":[]},{"n":49,"t":"掃羅的兒子是約拿單、亦施韋、麥基‧舒亞。他的兩個女兒：長女名叫米拉，次女名叫米甲。","notes":[]},{"n":50,"t":"掃羅的妻子名叫亞希暖，是亞希瑪斯的女兒。掃羅軍隊的元帥名叫押尼珥，是掃羅的叔叔尼珥的兒子。","notes":[]},{"n":51,"t":"掃羅的父親基士，押尼珥的父親尼珥，都是亞別的兒子。","notes":[]},{"n":52,"t":"掃羅有生之年常與非利士人激烈爭戰，他看到任何有能力的人或勇士，都招募來跟隨他。","notes":[]}]},"15":{"heading":"與亞瑪力人爭戰","verses":[{"n":1,"t":"撒母耳對掃羅說：「耶和華差遣我膏你為王，治理他的百姓以色列，現在你要聽從耶和華的話。","notes":[]},{"n":2,"t":"萬軍之耶和華如此說：『以色列人從埃及上來的時候，在路上亞瑪力人怎樣待他們，怎樣抵擋他們，我都要懲罰。","notes":[]},{"n":3,"t":"現在你要去攻打亞瑪力人，滅盡他們所有的，不可憐惜他們，將男女、孩童、吃奶的，以及牛、羊、駱駝和驢全都殺死。』」","notes":[]},{"n":4,"t":"於是掃羅在提拉因召集百姓，數點他們，共有二十萬步兵和一萬猶大人。","notes":[]},{"n":5,"t":"掃羅到了亞瑪力的京城，在谷中設下埋伏。","notes":[]},{"n":6,"t":"掃羅對基尼人說：「你們離開亞瑪力人下去吧，免得我把你們和亞瑪力人一同殺滅，因為以色列眾人從埃及上來的時候，你們曾恩待他們。」於是基尼人離開了亞瑪力人。","notes":[]},{"n":7,"t":"掃羅攻打亞瑪力人，從哈腓拉直到埃及東邊的書珥，","notes":[]},{"n":8,"t":"生擒了亞瑪力王亞甲，用刀殺盡亞瑪力的眾百姓。","notes":[]},{"n":9,"t":"掃羅和百姓卻憐惜亞甲，愛惜上好的牛、羊、牛犢、羔羊，以及一切美物，不肯滅絕。但是凡看不上眼和沒有價值的，他們盡都殺了。","notes":[]},{"n":10,"t":"耶和華的話臨到撒母耳說：","notes":[],"heads":["掃羅被廢"]},{"n":11,"t":"「我立掃羅為王，我感到遺憾，因為他轉去不跟從我，不遵守我的命令。」撒母耳就很生氣，終夜哀求耶和華。","notes":[]},{"n":12,"t":"撒母耳清早起來，去見掃羅。有人告訴撒母耳說：「掃羅到了迦密，看哪，他在那裏為自己立了紀念碑，又轉身下到吉甲。」","notes":[]},{"n":13,"t":"撒母耳到了掃羅那裏，掃羅對他說：「願耶和華賜福給你，耶和華的命令我已遵守了。」","notes":[]},{"n":14,"t":"撒母耳說：「我耳中聽見有羊叫、牛鳴的聲音，又是甚麼呢？」","notes":[]},{"n":15,"t":"掃羅說：「這是百姓從亞瑪力人那裏帶來的，因為他們愛惜上好的牛羊，要獻給耶和華－你的神。其餘的，我們都滅盡了。」","notes":[]},{"n":16,"t":"撒母耳對掃羅說：「住口吧！等我把耶和華昨夜向我所說的話告訴你。」掃羅說：「請說。」","notes":[]},{"n":17,"t":"撒母耳說：「你雖然看自己為小，你豈不是作了以色列諸支派的元首嗎？耶和華膏你作了以色列的王。","notes":[]},{"n":18,"t":"耶和華差遣你，吩咐你說：『你去除滅那些犯罪的亞瑪力人，攻打他們，直到把他們完全滅盡。』","notes":[]},{"n":19,"t":"你為何沒有聽從耶和華的話呢？你為何急著撲向掠物，行耶和華眼中看為惡的事呢？」","notes":[]},{"n":20,"t":"掃羅對撒母耳說：「我聽從了耶和華的話，行了耶和華派我行的路，擒了亞瑪力王亞甲來，滅盡了亞瑪力人。","notes":[]},{"n":21,"t":"百姓卻從掠物中取了牛羊，是當滅之物中最好的，要在吉甲獻給耶和華－你的神。」","notes":[]},{"n":22,"t":"撒母耳說：「耶和華喜愛燔祭和祭物，豈如喜愛人聽從他的話呢？看哪，聽命勝於獻祭，順從勝於公羊的脂肪。","notes":[]},{"n":23,"t":"悖逆與占卜的罪相等，頑梗與拜偶像的罪孽相同。因為你厭棄耶和華的命令，耶和華也厭棄你作王。」","notes":[]},{"n":24,"t":"掃羅對撒母耳說：「我有罪了！我違背了耶和華的指示和你的命令；因為我懼怕百姓，聽從了他們的話。","notes":[],"heads":["掃羅認罪"]},{"n":25,"t":"現在求你赦免我的罪，同我回去，我好敬拜耶和華。」","notes":[]},{"n":26,"t":"撒母耳對掃羅說：「我不同你回去，因為你厭棄耶和華的命令，耶和華也厭棄你作以色列的王。」","notes":[]},{"n":27,"t":"撒母耳轉身要走，掃羅抓住他外袍的衣角，外袍就斷裂了。","notes":[]},{"n":28,"t":"撒母耳對他說：「今日耶和華使以色列國與你斷絕，把這國賜給另一個比你更好的人。","notes":[]},{"n":29,"t":"以色列的大能者必不說謊，也不後悔，因為他不是世人，絕不後悔。」","notes":[]},{"n":30,"t":"掃羅說：「我有罪了。現在求你在我百姓的長老和以色列人面前尊重我，同我回去，我好敬拜耶和華－你的神。」","notes":[]},{"n":31,"t":"於是撒母耳轉身跟隨掃羅回去，掃羅就敬拜耶和華。","notes":[]},{"n":32,"t":"撒母耳說：「把亞瑪力王亞甲帶到我這裏來。」亞甲就歡歡喜喜地來到他面前，說：「死亡的苦難必定過去了。」","notes":["「就歡歡喜喜地...過去了。」死海古卷和七十士譯本是「就戰戰兢兢地來到他面前，說：『這真是死亡的苦難。』」"]},{"n":33,"t":"撒母耳說：「你既用刀使婦人喪子，你母親在婦人中也必照樣喪子。」於是，撒母耳在吉甲耶和華面前把亞甲砍碎了。","notes":[]},{"n":34,"t":"撒母耳回了拉瑪。掃羅上他所住的基比亞，回自己的家去了。","notes":[]},{"n":35,"t":"撒母耳直到死的日子，再沒有見掃羅。但撒母耳為掃羅悲傷，因為耶和華遺憾立掃羅為以色列的王。","notes":[]}]},"16":{"heading":"大衛被膏立為王","verses":[{"n":1,"t":"耶和華對撒母耳說：「我既厭棄掃羅作以色列的王，你為他悲傷要到幾時呢？你將膏油盛滿了角；來，我差遣你到伯利恆人耶西那裏去，因為我在他兒子中已看中了一個為我作王的。」","notes":[]},{"n":2,"t":"撒母耳說：「我怎麼能去呢？掃羅一聽見，就會殺我。」耶和華說：「你可以手裏牽一頭小母牛去，說：『我來是要向耶和華獻祭。』","notes":[]},{"n":3,"t":"你要請耶西來一同獻祭，我會指示你當做的事。我對你說的那個人，你要為我膏他。」","notes":[]},{"n":4,"t":"撒母耳遵照耶和華的話去做，來到伯利恆，城裏的長老都戰戰兢兢出來迎接他，有人問他說：「你是為平安來的嗎？」","notes":[]},{"n":5,"t":"他說：「為平安來的，我來是要向耶和華獻祭。你們要使自己分別為聖，來跟我一同獻祭。」撒母耳把耶西和他眾兒子分別為聖，請他們來一同獻祭。","notes":[]},{"n":6,"t":"他們來的時候，撒母耳看見以利押，就心裏說，耶和華的受膏者一定在耶和華面前了。","notes":[]},{"n":7,"t":"耶和華卻對撒母耳說：「不要只看他的外貌和他身材高大，我不揀選他。因為耶和華不像人看人，人是看外貌，耶和華是看內心。」","notes":["「外貌」：原文直譯「眼睛看得到的」。"]},{"n":8,"t":"耶西叫亞比拿達從撒母耳面前經過，撒母耳說：「耶和華也不揀選他。」","notes":[]},{"n":9,"t":"耶西又叫沙瑪經過，撒母耳說：「耶和華也不揀選他。」","notes":[]},{"n":10,"t":"耶西叫他七個兒子都從撒母耳面前經過，撒母耳對耶西說：「這些都不是耶和華所揀選的。」","notes":[]},{"n":11,"t":"撒母耳對耶西說：「你的兒子都在這裏了嗎？」他說：「還有一個最小的，看哪，他正在放羊。」撒母耳對耶西說：「你派人去叫他來；他若不來這裏，我們必不坐席。」","notes":[]},{"n":12,"t":"耶西就派人去叫他來。他面色紅潤，雙目清秀，容貌俊美。耶和華說：「起來，膏他，因為這就是他了。」","notes":[]},{"n":13,"t":"撒母耳就用角裏的膏油，在他的兄長中膏了他。從這日起，耶和華的靈就大大感動大衛。撒母耳起身回拉瑪去了。","notes":[]},{"n":14,"t":"耶和華的靈離開掃羅，有邪靈從耶和華那裏來擾亂他。","notes":[],"heads":["大衛在掃羅的宮裏"]},{"n":15,"t":"掃羅的臣僕對他說：「看哪，有邪靈從神那裏來擾亂你。","notes":[]},{"n":16,"t":"我們的主可以吩咐你面前的臣僕，去找一個善於彈琴的來。神那裏來的邪靈臨到你身上的時候，他用手彈琴，你就會感覺爽快。」","notes":[]},{"n":17,"t":"掃羅對臣僕說：「你們給我找一個善於彈琴的，帶到我這裏來。」","notes":[]},{"n":18,"t":"僕人中有一個回答說：「看哪，我曾見伯利恆人耶西的一個兒子善於彈琴，是大能的勇士，說話合宜，容貌俊美，耶和華也與他同在。」","notes":[]},{"n":19,"t":"於是掃羅差遣使者到耶西那裏，說：「叫你放羊的兒子大衛到我這裏來。」","notes":[]},{"n":20,"t":"耶西把幾個餅和一皮袋酒，以及一隻小山羊，馱在驢上，由兒子大衛的手送給掃羅。","notes":[]},{"n":21,"t":"大衛到了掃羅那裏，就侍立在掃羅面前。掃羅很喜歡他，他就作了掃羅拿兵器的人。","notes":[]},{"n":22,"t":"掃羅派人到耶西那裏，說：「讓大衛侍立在我面前，因為他在我眼前蒙了恩寵。」","notes":[]},{"n":23,"t":"從神那裏來的邪靈臨到掃羅身上的時候，大衛就拿琴，用手彈奏，使掃羅舒暢，感覺爽快，那邪靈就離開他了。","notes":[]}]},"17":{"heading":"大衛和歌利亞","verses":[{"n":1,"t":"非利士人召集他們的軍隊來爭戰。他們聚集在猶大的梭哥，在梭哥和亞西加中間的以弗‧大憫安營。","notes":[]},{"n":2,"t":"掃羅和以色列人也聚集，在以拉谷安營，擺陣迎戰，要與非利士人打仗。","notes":[]},{"n":3,"t":"非利士人站在這邊的山上，以色列人站在那邊的山上，當中有谷。","notes":[]},{"n":4,"t":"從非利士營中出來一個挑戰的人，名叫歌利亞，是迦特人，身高六肘一虎口。","notes":[]},{"n":5,"t":"他頭戴銅盔，身穿鎧甲，甲重五千舍客勒銅。","notes":[]},{"n":6,"t":"他腿上有銅護膝，兩肩之中背負銅矛。","notes":[]},{"n":7,"t":"他的槍桿粗如織布機的軸，槍頭的鐵重六百舍客勒。有一個拿盾牌的人走在他前面。","notes":[]},{"n":8,"t":"歌利亞站著，對以色列的軍隊喊叫，對他們說：「你們出來擺陣作戰是為了甚麼呢？我不是非利士人嗎？你們不是掃羅的僕人嗎？你們選一個人出來，叫他下來到我這裏吧。","notes":[]},{"n":9,"t":"他若能與我決鬥，把我殺死，我們就作你們的奴隸；我若勝了他，把他殺死，你們就作我們的奴隸，服事我們。」","notes":[]},{"n":10,"t":"那非利士人又說：「我今日向以色列的軍隊罵陣。你們叫一個人出來，跟我決鬥吧。」","notes":[]},{"n":11,"t":"掃羅和以色列眾人聽見非利士人這些話就驚惶，非常害怕。","notes":[]},{"n":12,"t":"大衛是猶大伯利恆的以法他人耶西的兒子，耶西有八個兒子。在掃羅的時候，這人年老，在眾人中受敬重。","notes":["「這人...受敬重」：七十士譯本和其他古譯本是「這人已經年紀老邁了」。"]},{"n":13,"t":"耶西最大的三個兒子跟隨掃羅出征。出征的三個兒子名字是：長子以利押，次子亞比拿達，三子沙瑪。","notes":[]},{"n":14,"t":"大衛是最小的，最大的三個兒子跟隨掃羅。","notes":[]},{"n":15,"t":"大衛有時離開掃羅，回伯利恆為他父親放羊。","notes":[]},{"n":16,"t":"那非利士人早晚都出來站著，共四十日。","notes":[]},{"n":17,"t":"耶西對他兒子大衛說：「你拿一伊法烘了的穗子和十個餅，跑到營裏去，交給你的哥哥，","notes":[]},{"n":18,"t":"再拿這十塊奶餅，送給他們的千夫長，並要問你哥哥好，向他們要個憑據回來。」","notes":[]},{"n":19,"t":"掃羅和大衛的三個哥哥，以及以色列眾人，都在以拉谷與非利士人打仗。","notes":[]},{"n":20,"t":"大衛早晨起來，把羊交託一個看守的人，照耶西所吩咐的帶著食物去了。到了軍營，軍隊剛出到戰場，吶喊叫陣。","notes":[]},{"n":21,"t":"以色列人和非利士人都擺列陣勢，彼此相對。","notes":[]},{"n":22,"t":"大衛把東西留在看守物件的人手中，跑到戰場，問他哥哥好。","notes":[]},{"n":23,"t":"他與他們說話的時候，看哪，那挑戰的人，就是迦特的非利士人歌利亞，從非利士隊伍中上來，說了同樣的話，大衛聽見了。","notes":[]},{"n":24,"t":"以色列眾人看見那人就非常害怕，從他面前逃跑。","notes":[]},{"n":25,"t":"以色列人說：「這上來的人你看見了嗎？他上來是要向以色列人罵陣。若有人能殺他，王必賞賜他大財，將自己的女兒嫁給他，並在以色列人中免除他父家納糧服役。」","notes":[]},{"n":26,"t":"大衛對站在旁邊的人說：「若有人殺這非利士人，除掉以色列人的羞辱，他會怎樣呢？這未受割禮的非利士人是誰，竟敢向永生神的軍隊罵陣！」","notes":[]},{"n":27,"t":"百姓照同樣的話對他說：「若有人殺了那人，必這樣待他。」","notes":[]},{"n":28,"t":"大衛的長兄以利押聽見大衛與他們所說的話，就向他發怒，說：「你下來做甚麼呢？在曠野的那幾隻羊，你交託誰了呢？我知道你的驕傲和你心裏的惡意，你下來只是為了看戰爭！」","notes":[]},{"n":29,"t":"大衛說：「我現在做了甚麼呢？只是問一句話也不可以嗎？」","notes":[]},{"n":30,"t":"大衛離開他轉向別人，問了同樣的事，百姓也照先前的話回答他。","notes":[]},{"n":31,"t":"有人聽見大衛所說的話，就在掃羅面前報告；掃羅就派人叫他來。","notes":[]},{"n":32,"t":"大衛對掃羅說：「人不必因那非利士人灰心。你的僕人要去與他決鬥。」","notes":[]},{"n":33,"t":"掃羅對大衛說：「你不能去與那非利士人決鬥，因為你年紀太輕，他從小就是戰士。」","notes":[]},{"n":34,"t":"大衛對掃羅說：「你僕人為父親放羊，有時獅子來了，有時熊來了，從群中抓走一隻羔羊。","notes":[]},{"n":35,"t":"我就追趕牠，擊打牠，把羔羊從牠口中救出來。牠起來攻擊我，我就揪牠的鬍子，打死牠。","notes":[]},{"n":36,"t":"你僕人曾打死獅子和熊，這未受割禮的非利士人必像獅子和熊一樣，因為他向永生神的軍隊罵陣。」","notes":[]},{"n":37,"t":"大衛又說：「耶和華救我脫離獅子和熊的爪，他必救我脫離這非利士人的手。」掃羅對大衛說：「你去吧！耶和華必與你同在。」","notes":[]},{"n":38,"t":"掃羅把自己的戰衣給大衛穿上，將銅盔戴在他頭上，又給他穿上鎧甲。","notes":[]},{"n":39,"t":"大衛佩刀在戰衣上，試著走走看。因大衛沒有試過，就對掃羅說：「我穿戴這些不能走路，因為我沒有試過。」於是他脫下身上的這些軍裝。","notes":[]},{"n":40,"t":"他手中拿杖，又在溪中挑選了五塊光滑的石子，放在袋裏，就是牧人帶的囊裏，手裏拿著甩石的機弦，迎向那非利士人。","notes":[]},{"n":41,"t":"那非利士人漸漸走近大衛，拿盾牌的人在他前面。","notes":[]},{"n":42,"t":"非利士人觀看，見了大衛，就藐視他，因為他年輕，面色紅潤，容貌俊美。","notes":[]},{"n":43,"t":"非利士人對大衛說：「你拿著杖到我這裏來，我豈是狗嗎？」非利士人就指著自己的神明詛咒大衛。","notes":[]},{"n":44,"t":"非利士人又對大衛說：「來吧！我要把你的肉給空中的飛鳥和田野的走獸。」","notes":[]},{"n":45,"t":"大衛對非利士人說：「你來攻擊我，是靠著刀槍和銅矛，但我來攻擊你，是靠著萬軍之耶和華的名，就是你所辱罵、帶領以色列軍隊的神。","notes":[]},{"n":46,"t":"今日耶和華必將你交在我手裏。我必殺你，砍下你的頭，今日我要把非利士軍兵的屍體給空中的飛鳥和地上的野獸，使全地的人都知道以色列中有神，","notes":[]},{"n":47,"t":"又使這裏的全會眾知道，耶和華使人得勝，不是用刀用槍，因為戰爭全在乎耶和華。他必將你們交在我們手裏。」","notes":[]},{"n":48,"t":"那非利士人起來，迎向大衛，走近前來。大衛急忙往戰場，迎向非利士人跑去。","notes":[]},{"n":49,"t":"大衛伸手入囊中，從裏面掏出一塊石子來，用機弦甩去，擊中非利士人的前額，石子進入額內，他就仆倒，面伏於地。","notes":[]},{"n":50,"t":"這樣，大衛用機弦和石子勝了那非利士人，擊中了他，把他殺死；大衛手中沒有刀。","notes":[]},{"n":51,"t":"大衛跑去，站在那非利士人身旁，把他的刀從鞘中拔出來，殺死他，用刀割下他的頭。非利士眾人看見他們的勇士死了，就都逃跑。","notes":[]},{"n":52,"t":"以色列人和猶大人就起來吶喊，追趕非利士人，直到該和以革倫的城門。被殺的非利士人倒在路上，從沙拉音直到迦特和以革倫。","notes":["「該」：七十士譯本和其他古譯本是「迦特」。"]},{"n":53,"t":"以色列人追趕非利士人回來，搶奪了他們的軍營。","notes":[]},{"n":54,"t":"大衛拿著那非利士人的頭帶到耶路撒冷，卻把那非利士人的軍裝放在自己的帳棚裏。","notes":[]},{"n":55,"t":"掃羅看見大衛去迎戰非利士人，就問押尼珥元帥說：「押尼珥，那年輕人是誰的兒子？」押尼珥說：「王啊，我在你面前起誓，我不知道。」","notes":[],"heads":["大衛覲見掃羅"]},{"n":56,"t":"王說：「你可以問問那孩子是誰的兒子。」","notes":[]},{"n":57,"t":"大衛打死那非利士人回來，押尼珥領他到掃羅面前，大衛手中拿著非利士人的頭。","notes":[]},{"n":58,"t":"掃羅問他說：「年輕人，你是誰的兒子？」大衛說：「我是你僕人伯利恆人耶西的兒子。」","notes":[]}]},"18":{"heading":"大衛與約拿單","verses":[{"n":1,"t":"大衛對掃羅說完了話，約拿單的心與大衛的心深相契合。約拿單愛大衛，如同愛自己的性命。","notes":[]},{"n":2,"t":"那日掃羅留住大衛，不讓他回父家。","notes":[]},{"n":3,"t":"約拿單愛大衛如同愛自己的性命，就與他立約。","notes":[]},{"n":4,"t":"約拿單從身上脫下外袍，給了大衛，又把戰衣、刀、弓、腰帶都給了他。","notes":[]},{"n":5,"t":"掃羅無論差遣大衛往何處去，他都做事精明。掃羅立他作軍隊的指揮官，眾百姓和掃羅的臣僕都看為美。","notes":[]},{"n":6,"t":"大衛打死了那非利士人，同眾人回來的時候，婦女們從以色列各城裏出來，歡歡喜喜，打鼓奏樂，唱歌跳舞，迎接掃羅王。","notes":[],"heads":["掃羅妒忌大衛"]},{"n":7,"t":"眾婦女歡樂唱和，說：「掃羅殺死千千，大衛殺死萬萬。」","notes":[]},{"n":8,"t":"掃羅非常憤怒，不喜歡這話。他說：「將萬萬歸給大衛，千千歸給我，只剩下王國沒有給他！」","notes":[]},{"n":9,"t":"從這日起，掃羅就敵視大衛。","notes":[]},{"n":10,"t":"次日，從神來的邪靈緊抓住掃羅，他就在家中胡言亂語。大衛照常彈琴，掃羅手裏拿著槍。","notes":[]},{"n":11,"t":"掃羅把槍一擲，心裏說：「我要將大衛刺透，釘在牆上。」大衛閃避了他兩次。","notes":[]},{"n":12,"t":"掃羅懼怕大衛，因為耶和華離開自己，與大衛同在。","notes":[]},{"n":13,"t":"所以掃羅叫大衛離開自己，立他為千夫長，他就領兵出入。","notes":[]},{"n":14,"t":"大衛所做的每一件事都精明，耶和華也與他同在。","notes":[]},{"n":15,"t":"掃羅見大衛做事精明，就更怕他。","notes":[]},{"n":16,"t":"但以色列和猶大眾人都愛大衛，因為他領他們出入。","notes":[]},{"n":17,"t":"掃羅對大衛說：「看哪，我將大女兒米拉嫁給你，只要你作我的勇士，為耶和華爭戰。」掃羅心裏說：「我不好親手害他，要藉非利士人的手害他。」","notes":[],"heads":["大衛娶掃羅的女兒"]},{"n":18,"t":"大衛對掃羅說：「我是誰，我是甚麼出身，我父家在以色列中算甚麼，豈敢作王的女婿呢？」","notes":[]},{"n":19,"t":"掃羅的女兒米拉到了當嫁給大衛的時候，掃羅卻將她嫁給了米何拉人亞得列。","notes":[]},{"n":20,"t":"掃羅的女兒米甲愛大衛。有人告訴掃羅，這件事在掃羅眼中看為合宜。","notes":[]},{"n":21,"t":"掃羅心裏說：「我把這女兒嫁給大衛，作他的圈套，好藉非利士人的手害他。」所以掃羅第二次對大衛說：「你今日可以作我的女婿。」","notes":[]},{"n":22,"t":"掃羅吩咐臣僕：「你們暗中對大衛說：『看哪，王喜歡你，王的臣僕也都愛戴你，現在你就作王的女婿吧。』」","notes":[]},{"n":23,"t":"掃羅的臣僕照這話說給大衛聽。大衛說：「你們把作王的女婿看為小事嗎？我是貧窮卑微的人。」","notes":[]},{"n":24,"t":"掃羅的臣僕回奏說，大衛說了這樣的話。","notes":[]},{"n":25,"t":"掃羅說：「你們要對大衛這樣說：『王不要甚麼聘禮，只要一百非利士人的包皮，好在王的仇敵身上報仇。』」掃羅的意圖是要大衛落在非利士人的手中。","notes":[]},{"n":26,"t":"掃羅的臣僕把這話告訴大衛，大衛就歡喜作王的女婿。日期還沒有到，","notes":[]},{"n":27,"t":"大衛和跟隨他的人起來前往，殺了二百非利士人，將包皮足數交給王，為要作王的女婿。於是掃羅將女兒米甲嫁給大衛。","notes":["「二百」：七十士譯本是「一百」。"]},{"n":28,"t":"掃羅見耶和華與大衛同在，女兒米甲又愛大衛，","notes":[]},{"n":29,"t":"就更怕大衛，常常與大衛為敵。","notes":[]},{"n":30,"t":"每逢非利士的軍官出來打仗，大衛做事比掃羅任何臣僕更精明，因此他的名極受尊重。","notes":[]}]},"19":{"heading":"掃羅迫害大衛","verses":[{"n":1,"t":"掃羅吩咐他兒子約拿單和眾臣僕要殺大衛，但掃羅的兒子約拿單卻很喜愛大衛。","notes":[]},{"n":2,"t":"約拿單告訴大衛說：「我父掃羅想要殺你，現在你要小心，明日早晨留在一個僻靜的地方藏起來。","notes":[]},{"n":3,"t":"我會出去，到你所藏的田裏，站在我父親旁邊，與父親談論到你。我看情形怎樣，會告訴你。」","notes":[]},{"n":4,"t":"約拿單向他父親掃羅說大衛的好話，對他說：「王不可得罪王的僕人大衛，因為他未曾得罪你，他所行的對你都很有益處。","notes":[]},{"n":5,"t":"他拚了命殺那非利士人，並且耶和華為全以色列大施拯救。那時你看見，也很歡喜，現在為何要犯罪，流無辜人的血，無緣無故殺大衛呢？」","notes":[]},{"n":6,"t":"掃羅聽了約拿單的話，就指著永生的耶和華起誓：「我絕不殺他。」","notes":[]},{"n":7,"t":"約拿單叫大衛來，把這一切事告訴他。約拿單帶他去見掃羅，他就像以前一樣侍立在掃羅面前。","notes":[]},{"n":8,"t":"此後又有戰爭，大衛出去與非利士人打仗。他大大擊敗他們，他們就在他面前逃跑。","notes":[]},{"n":9,"t":"從耶和華來的邪靈又降在掃羅身上，掃羅手裏拿槍坐在屋裏，大衛正用手彈琴。","notes":[]},{"n":10,"t":"掃羅想要用槍刺透大衛，把他釘在牆上，他卻躲開掃羅，掃羅的槍刺入牆內。當夜大衛逃走，躲起來了。","notes":[]},{"n":11,"t":"掃羅派一些使者到大衛的房屋那裏守著他，等到天亮要殺他。大衛的妻子米甲對大衛說：「你今夜若不逃命，明日就要被殺。」","notes":[]},{"n":12,"t":"於是米甲將大衛從窗戶縋下去，讓他走；大衛就逃走，躲起來了。","notes":[]},{"n":13,"t":"米甲把家中的神像放在床上，頭枕在山羊毛的枕頭上，用衣服蓋起來。","notes":[]},{"n":14,"t":"掃羅派一些使者去捉拿大衛，米甲說：「他病了。」","notes":[]},{"n":15,"t":"掃羅又派一些使者去看大衛，說：「把他連床一起抬到我這裏，我好殺他。」","notes":[]},{"n":16,"t":"使者進去，看哪，神像在床上，頭枕在山羊毛的枕頭上。","notes":[]},{"n":17,"t":"掃羅對米甲說：「你為甚麼這樣欺騙我，放我仇敵逃走呢？」米甲對掃羅說：「他對我說：『你放我走吧，我何必要殺你呢？』」","notes":[]},{"n":18,"t":"大衛逃跑躲避，來到拉瑪的撒母耳那裏，把掃羅向他所行的事全告訴他。他和撒母耳就去，住在拿約。","notes":[]},{"n":19,"t":"有人告訴掃羅說：「看哪，大衛在拉瑪的拿約」。","notes":[]},{"n":20,"t":"掃羅派一些使者去捉拿大衛。去的人見一隊先知受感說話，撒母耳站在當中領導他們，掃羅派去的使者也受神的靈感動說話。","notes":[]},{"n":21,"t":"有人把這事告訴掃羅，他又派另一些使者去，他們也受感說話。掃羅第三次派使者去，他們也受感說話。","notes":[]},{"n":22,"t":"然後掃羅親自往拉瑪去，到了西沽的大井，問人說：「撒母耳和大衛在哪裏？」有人說：「看哪，在拉瑪的拿約。」","notes":[]},{"n":23,"t":"他就往那裏去，到了拉瑪的拿約。神的靈也臨到他，他一面走一面受感說話，直到拉瑪的拿約。","notes":[]},{"n":24,"t":"他也脫了衣服，也在撒母耳面前受感說話，一日一夜赤身躺臥。因此有人說：「掃羅也在先知中嗎？」","notes":[]}]},"20":{"heading":"約拿單幫助大衛","verses":[{"n":1,"t":"大衛從拉瑪的拿約逃跑，來到約拿單面前，對他說：「我做了甚麼，有甚麼罪孽，在你父親面前犯了甚麼罪，他竟要尋索我的性命呢？」","notes":[]},{"n":2,"t":"約拿單對他說：「絕無此事！你必不至於死。看哪，我父做事，無論大小，沒有不告訴我的。我父親為甚麼要隱瞞我這件事呢？不會這樣的！」","notes":[]},{"n":3,"t":"大衛又起誓說：「你父親確實知道我在你眼前蒙恩。所以他說，『這事不要讓約拿單知道，免得他愁煩。』我指著永生的耶和華起誓，又指著你的性命起誓，我離死只差一步而已。」","notes":[]},{"n":4,"t":"約拿單對大衛說：「你心裏所求的，我必為你成就。」","notes":[]},{"n":5,"t":"大衛對約拿單說：「看哪，明日是初一，我必須與王同席用餐，求你讓我去藏在田野，直到第三日傍晚。","notes":[]},{"n":6,"t":"你父親若見我不在席上，你就說：『大衛懇求我允許他趕回本城伯利恆去，因為他全家在那裏獻年祭。』","notes":[]},{"n":7,"t":"你父親若說好，你的僕人就平安了；他若大怒，你就知道他決意行惡。","notes":[]},{"n":8,"t":"求你施恩於僕人，因你在耶和華面前曾與僕人立約。我若有罪孽，你就親自殺死我，何必把我交給你父親呢？」","notes":[]},{"n":9,"t":"約拿單說：「絕無此事！我若確實知道我父親決意害你，怎麼會不告訴你呢？」","notes":[]},{"n":10,"t":"大衛對約拿單說：「你父親若嚴厲回答你，誰來告訴我呢？」","notes":[]},{"n":11,"t":"約拿單對大衛說：「來，讓我們到田野去。」二人就往田野去了。","notes":[]},{"n":12,"t":"約拿單對大衛說：「願耶和華－以色列的神作證。明日約在這時候，或第三日，我一探出我父親的心意，看哪，若對大衛是好意，我怎麼會不派人來告訴你呢？","notes":[]},{"n":13,"t":"我父親若有意害你，而我不告訴你，送你平安地離開，願耶和華重重懲罰約拿單。願耶和華與你同在，如同從前與我父親同在一樣。","notes":[]},{"n":14,"t":"你要照耶和華的慈愛恩待我，不但我活著的時候免我死亡，","notes":[]},{"n":15,"t":"就是耶和華從地面逐一剪除大衛仇敵的時候，你也永不可向我家斷絕恩惠。」","notes":[]},{"n":16,"t":"於是約拿單與大衛家立約：「願耶和華從大衛仇敵的手來追討。」","notes":["「大衛仇敵」是「大衛子孫」的委婉用語，避免詛咒大衛的子孫。"]},{"n":17,"t":"約拿單因愛大衛如同愛自己的性命，就叫他再起誓。","notes":[]},{"n":18,"t":"約拿單對他說：「明日是初一，你的座位空著，人必察覺你不在。","notes":[]},{"n":19,"t":"到第三日，就要走一段長路下去，去到你遇事那天所藏的地方，在以色磐石的旁邊等候。","notes":["「就要走一段長路下去」：七十士譯本是「人家更會察覺」。","「以色磐石」：七十士譯本是「石堆」。"]},{"n":20,"t":"我會向磐石旁邊射三箭，如同射箭靶一樣。","notes":[]},{"n":21,"t":"看哪，我會派僮僕，說：『去把箭找來。』我若對僮僕喊說：『看哪，箭在你的這邊，把箭拿來』，你就可以平安回來；我指著永生的耶和華起誓，你一定沒有事。","notes":[]},{"n":22,"t":"我若對孩子說：『看哪，箭在你的前方』，你就要離開，因為是耶和華差你去的。","notes":[]},{"n":23,"t":"至於你和我，我們所說的話，看哪，耶和華在你我中間作證，直到永遠。」","notes":[]},{"n":24,"t":"大衛就去藏在田野。到了初一，王要坐席用餐。","notes":[]},{"n":25,"t":"王照常坐在靠牆的位子上，約拿單在對面，押尼珥坐在掃羅旁邊，大衛的座位卻是空的。","notes":["「在對面」是根據七十士譯本；原文是「起身」。"]},{"n":26,"t":"這日掃羅沒有說甚麼，因為他說：「大衛或許有事，偶染不潔，還未得潔淨。」","notes":[]},{"n":27,"t":"初二，大衛的座位還空著。掃羅對他兒子約拿單說：「耶西的兒子為何昨日、今日都沒有來用餐呢？」","notes":[]},{"n":28,"t":"約拿單回答掃羅說：「大衛懇求我允許他回伯利恆去，","notes":[]},{"n":29,"t":"說：『求你讓我去，因為我家在城裏有獻祭的事，我哥哥吩咐我去。如今我若在你眼前蒙恩，求你讓我去見我的兄弟。』所以大衛沒有來赴王的筵席。」","notes":[]},{"n":30,"t":"掃羅向約拿單怒氣大發，對他說：「你這頑梗悖逆之婦人所生的，我怎麼會不知道你選擇耶西的兒子，自取羞辱，也使你母親露體蒙羞呢？","notes":["「選擇耶西的兒子」：七十士譯本是「作耶西兒子的朋友」。"]},{"n":31,"t":"只要耶西的兒子還活在世上一天，你和你的國必保不住。現在你要派人去，把他帶到我這裏來，因為他是該死的。」","notes":[]},{"n":32,"t":"約拿單回答父親掃羅說：「他為甚麼該死呢？他做了甚麼呢？」","notes":[]},{"n":33,"t":"掃羅向約拿單擲槍要刺他，約拿單就知道他父親決意要殺死大衛。","notes":[]},{"n":34,"t":"於是約拿單氣憤憤地從席上起來。他在初二這天沒有吃飯，因為他為大衛愁煩，又因為他父親羞辱了他。","notes":[]},{"n":35,"t":"次日早晨，約拿單按著與大衛約定的時候到田野去，有一個小僮僕跟隨他。","notes":[]},{"n":36,"t":"約拿單對僮僕說：「你跑去把我所射的箭找來。」僮僕跑去，約拿單就把箭射在僮僕的前方。","notes":[]},{"n":37,"t":"僮僕到了約拿單落箭之地，約拿單呼叫僮僕說：「箭不是在你的前方嗎？」","notes":[]},{"n":38,"t":"約拿單又呼叫僮僕說：「快去，不要站在那裏！」僮僕就撿起箭來，回到主人那裏。","notes":[]},{"n":39,"t":"僮僕不知道這是甚麼意思，只有約拿單和大衛知道這事。","notes":[]},{"n":40,"t":"約拿單把他的弓箭交給僮僕，吩咐他說：「你拿到城裏去。」","notes":[]},{"n":41,"t":"僮僕一去，大衛就從南邊出來，俯伏在地，拜了三拜。他們彼此親吻，一起哭泣，大衛哭得更悲哀。","notes":["「南邊」：七十士譯本是「石堆的旁邊」。"]},{"n":42,"t":"約拿單對大衛說：「你平平安安地去吧！因為我們二人曾指著耶和華的名起誓說：『願耶和華在你我中間，以及你我後裔中間作證，直到永遠。』」大衛就起身走了，約拿單也回城裏去了。","notes":[]}]},"21":{"heading":"大衛逃離掃羅","verses":[{"n":1,"t":"大衛到了挪伯的亞希米勒祭司那裏，亞希米勒戰戰兢兢地出來迎接他，對他說：「你為甚麼獨自一人，沒有人跟隨你呢？」","notes":[]},{"n":2,"t":"大衛對亞希米勒祭司說：「王吩咐我一件事，對我說：『我差遣你，吩咐你的這件事，不可讓任何人知道。』因此我已告訴一些僕人到某處去。","notes":["「告訴...去」：死海古卷和一些其他古譯本是「和一些僕人約在某處相會」。"]},{"n":3,"t":"現在你手中有甚麼？請你給我五個餅或是可以找到的食物。」","notes":[]},{"n":4,"t":"祭司對大衛說：「我手中沒有普通的餅，只有聖餅，只能給沒有親近婦人的年輕人。」","notes":[]},{"n":5,"t":"大衛回答祭司說：「我們確實沒有親近婦人，如同往常我出征的時候一樣。平常行路，僕人的身體都還分別為聖，何況今日豈不更使自己分別為聖嗎？」","notes":["「身體」：原文是「器皿」。"]},{"n":6,"t":"祭司拿聖餅給他，因為在那裏沒有別的餅，只有那從耶和華面前撤下的供餅，就是換上熱餅的日子取下來的。","notes":[]},{"n":7,"t":"當日，有掃羅的一個臣僕在那裏，他留在耶和華的面前，名叫多益，是以東人，作掃羅的畜牧長。","notes":[]},{"n":8,"t":"大衛對亞希米勒說：「你手中有沒有槍或刀？因為王的事緊急，連刀劍兵器我都沒有帶。」","notes":[]},{"n":9,"t":"祭司說：「你在以拉谷所殺的非利士人歌利亞的那刀，看哪，裹在布中，放在以弗得後邊。你若要可以拿去，除此以外，再沒有別的了。」大衛說：「沒有甚麼可以跟它比的了！請你給我。」","notes":[]},{"n":10,"t":"那日大衛起來，躲避掃羅，逃到迦特王亞吉那裏。","notes":[]},{"n":11,"t":"亞吉的臣僕對他說：「這不是那地的國王大衛嗎？那裏的人跳舞唱和：『掃羅殺死千千，大衛殺死萬萬』，不是指著他說的嗎？」","notes":[]},{"n":12,"t":"大衛把這些話放在心裏，就很懼怕迦特王亞吉。","notes":[]},{"n":13,"t":"於是他在眾人眼前一反常態，在他們中間裝瘋作癲，在城門的門扇上胡寫亂畫，任由唾沫流在鬍子上。","notes":["「在他們中間」：原文是「在他們手中」。"]},{"n":14,"t":"亞吉對臣僕說：「看哪，你們看這人瘋了，為甚麼帶他到我這裏來呢？","notes":[]},{"n":15,"t":"我豈缺少瘋子，你們竟然帶這人到我面前瘋癲嗎？這個人可以進我的家嗎？」","notes":[]}]},"22":{"heading":"掃羅殘殺祭司","verses":[{"n":1,"t":"大衛離開那裏，逃到亞杜蘭洞。他的兄弟和他父親全家聽見了，都下到他那裏去。","notes":[]},{"n":2,"t":"凡生活窘迫的、欠債的、心裏苦惱的都聚集到大衛那裏，他就作他們的領袖，跟隨他的約有四百人。","notes":[]},{"n":3,"t":"大衛從那裏往摩押的米斯巴去，對摩押王說：「請你讓我父母搬來，跟你們在一起，等我知道神要為我怎樣做。」","notes":[]},{"n":4,"t":"大衛領他父母到摩押王面前。大衛住山寨一切的日子，他父母也都住在摩押王那裏。","notes":["「領他父母到」：有些古譯本是「留他父母在」。"]},{"n":5,"t":"先知迦得對大衛說：「你不要住在山寨，要到猶大地去。」大衛就去，來到哈列的樹林。","notes":[]},{"n":6,"t":"掃羅聽見大衛和跟隨他之人的下落，掃羅正在基比亞，坐在山頂的柳樹下，手裏拿著槍，眾臣僕侍立在左右。","notes":["「山頂」或譯「拉瑪」。"]},{"n":7,"t":"掃羅對左右侍立的臣僕說：「便雅憫人哪，聽著！耶西的兒子也能把田地和葡萄園賜給你們各人嗎？他能立你們各人作千夫長和百夫長嗎？","notes":[]},{"n":8,"t":"你們竟都結黨害我！我兒子與耶西的兒子立約的時候，無人告訴我；我兒子挑唆我的臣僕謀害我，像今日這樣，也無人告訴我，為我憂慮。」","notes":[]},{"n":9,"t":"那時以東人多益站在掃羅的臣僕中，回答說：「我曾看見耶西的兒子往挪伯去，到了亞希突的兒子亞希米勒那裏。","notes":[]},{"n":10,"t":"亞希米勒為他求問耶和華，給他食物，又把非利士人歌利亞的刀給了他。」","notes":[]},{"n":11,"t":"王就派人把亞希突的兒子亞希米勒祭司和他父親的全家，就是在挪伯的祭司都召了來，他們都來到王那裏。","notes":[]},{"n":12,"t":"掃羅說：「亞希突的兒子，聽著！」他說：「我主，我在這裏。」","notes":[]},{"n":13,"t":"掃羅對他說：「你為甚麼與耶西的兒子結黨害我，把食物和刀給他，又為他求問神，使他起來謀害我，像今日這樣？」","notes":[]},{"n":14,"t":"亞希米勒回答王說：「王的眾臣僕中有誰比大衛忠心呢？他是王的女婿，又是你的侍衛長，並且是你宮中受敬重的人。","notes":["「又是你的侍衛長」是根據七十士譯本和其他古譯本；原文是「他離開你的侍衛」。"]},{"n":15,"t":"我今日才開始為他求問神嗎？絕非如此！王不要歸罪於我和我父全家，因為這事，無論大小，僕人都不知情。」","notes":[]},{"n":16,"t":"王說：「亞希米勒，你和你父全家都是該死的！」","notes":[]},{"n":17,"t":"王吩咐左右的侍衛說：「你們轉身去殺耶和華的祭司吧！因為他們幫助大衛，知道大衛逃跑卻不告訴我。」但王的臣僕都不願動手殺耶和華的祭司。","notes":[]},{"n":18,"t":"王吩咐多益說：「你轉身去殺祭司吧！」以東人多益就轉身去殺祭司，那日殺了穿細麻布以弗得的，共八十五人，","notes":[]},{"n":19,"t":"又用刀把祭司城挪伯中的男女、孩童和吃奶的都殺了，又用刀殺了牛、羊和驢子。","notes":[]},{"n":20,"t":"亞希突的兒子亞希米勒有一個兒子逃脫了；他名叫亞比亞他，逃到大衛那裏。","notes":[]},{"n":21,"t":"亞比亞他把掃羅殺耶和華祭司的事告訴大衛。","notes":[]},{"n":22,"t":"大衛對亞比亞他說：「那日我見以東人多益在那裏，就知道他一定會告訴掃羅。你父的全家喪命，都是因我的緣故。","notes":[]},{"n":23,"t":"你可以住在我這裏，不要懼怕。因為尋索你命的也要尋索我的命，你在我這裏可得保護。」","notes":[]}]},"23":{"heading":"大衛救了基伊拉城","verses":[{"n":1,"t":"有人告訴大衛說：「看哪，非利士人攻擊基伊拉，搶奪禾場。」","notes":[]},{"n":2,"t":"大衛求問耶和華說：「我可以去嗎？我可以去攻打那些非利士人嗎？」耶和華對大衛說：「你可以去攻打非利士人，拯救基伊拉。」","notes":[]},{"n":3,"t":"大衛的人對他說：「看哪，我們在猶大這裏尚且懼怕，何況到基伊拉去攻打非利士人的軍隊呢？」","notes":[]},{"n":4,"t":"大衛又再求問耶和華，耶和華回答說：「你起身下基伊拉去，我必將非利士人交在你手裏。」","notes":[]},{"n":5,"t":"於是大衛和他的人往基伊拉去，與非利士人打仗，大大擊敗他們，奪取他們的牲畜。這樣，大衛救了基伊拉的居民。","notes":[]},{"n":6,"t":"亞希米勒的兒子亞比亞他逃往基伊拉到大衛那裏的時候，手裏拿著以弗得。","notes":[]},{"n":7,"t":"有人告訴掃羅，大衛到了基伊拉。掃羅說：「神將他交在我手裏了，因為他進了有門有閂的城，把自己關起來了。」","notes":[]},{"n":8,"t":"於是掃羅召集眾百姓，要下去攻打基伊拉，圍困大衛和他的人。","notes":[]},{"n":9,"t":"大衛知道掃羅設計陷害他，就對亞比亞他祭司說：「把以弗得拿過來。」","notes":[]},{"n":10,"t":"大衛說：「耶和華－以色列的神啊，你僕人確實聽見掃羅設法要到基伊拉來，為我的緣故毀滅這城。","notes":[]},{"n":11,"t":"基伊拉人會把我交在掃羅手裏嗎？掃羅會下來，正如你僕人所聽見的嗎？耶和華－以色列的神啊，求你指示僕人！」耶和華說：「他會下來。」","notes":[]},{"n":12,"t":"大衛又說：「基伊拉人會把我和我的人交在掃羅手裏嗎？」耶和華說：「他們會交出來。」","notes":[]},{"n":13,"t":"於是大衛和他的人約有六百名起身離開基伊拉，往他們所能去的地方去。有人告訴掃羅，大衛離開基伊拉逃走了，掃羅就停止出發了。","notes":[]},{"n":14,"t":"大衛住在曠野的山寨裏，在西弗曠野的山區。掃羅天天尋索大衛，神卻不將大衛交在他手裏。","notes":[],"heads":["大衛在曠野躲避掃羅"]},{"n":15,"t":"大衛看到掃羅出來尋索他的命。那時，他住在西弗曠野的樹林裏；","notes":["「樹林裏」或音譯「何列施」；下同。"]},{"n":16,"t":"掃羅的兒子約拿單起身，到樹林裏去見大衛，使他的手倚靠神得以堅固，","notes":[]},{"n":17,"t":"對他說：「不要懼怕！我父掃羅的手無法害你 ，你必作以色列的王，我必作你的宰相。我父掃羅也知道這事。」","notes":[]},{"n":18,"t":"於是二人在耶和華面前立約。大衛仍住在樹林裏，約拿單就回家去了。","notes":[]},{"n":19,"t":"西弗人上基比亞到掃羅那裏，說：「大衛不是在我們那裏，在樹林裏的山寨中，在荒野南邊的哈基拉山藏著嗎？","notes":["「荒野」或音譯「約斯門」；下同。"]},{"n":20,"t":"現在，王啊，請隨你的心願要下來，就請下來；至於我們，一定會把他交在王的手裏。」","notes":[]},{"n":21,"t":"掃羅說：「願耶和華賜福給你們，因為你們體恤我。","notes":[]},{"n":22,"t":"請你們回去，再確定一下，調查並看清楚他落腳的地方，是誰看見他在那裏，因為有人告訴我他很狡猾。","notes":["「調查...在那裏」：七十士譯本是「快快調查並看清楚他落腳的地方在哪裏」。"]},{"n":23,"t":"你們要看清楚，調查他藏匿的每一個地方，回來給我確實的報告，我就與你們同去。他若在境內，我必從猶大的千門萬戶中搜出他來。」","notes":[]},{"n":24,"t":"西弗人動身，在掃羅以先往西弗去。大衛和他的人卻在瑪雲曠野，在荒野南邊的亞拉巴。","notes":[]},{"n":25,"t":"掃羅和他的人去尋索大衛。有人告訴大衛，他就下到巖石那裏，留在瑪雲的曠野。掃羅聽見了，就在瑪雲的曠野追趕大衛。","notes":[]},{"n":26,"t":"掃羅在山的這一邊走，大衛和他的人在山的那一邊。大衛急忙躲避掃羅，掃羅和他的人正四面圍住大衛和他的人，要捉拿他們。","notes":[]},{"n":27,"t":"有使者來對掃羅說：「非利士人入境搶掠，請快快回去！」","notes":[]},{"n":28,"t":"於是掃羅不再追趕大衛，回去迎擊非利士人。因此那地方名叫西拉‧哈瑪希羅結。","notes":["「西拉‧哈瑪希羅結」意思是「隔離巖」。"]},{"n":29,"t":"大衛從那裏上去，住在隱‧基底的山寨裏。","notes":[]}]},"24":{"heading":"大衛饒掃羅的命","verses":[{"n":1,"t":"掃羅追趕非利士人回來，有人告訴他說：「看哪，大衛在隱‧基底的曠野。」","notes":[]},{"n":2,"t":"掃羅就從全以色列中挑選三千精兵，往野山羊磐石的東邊去，尋索大衛和他的人。","notes":["「東邊」或譯「前面」。"]},{"n":3,"t":"到了路旁的羊圈，在那裏有個洞，掃羅進去大解。大衛和他的人正藏在洞裏的深處。","notes":[]},{"n":4,"t":"大衛的人對大衛說：「看哪，這日子到了！耶和華曾對你說：『看哪，我要將你的仇敵交在你手裏，你可以照你看為好的對待他。』」大衛就起來，悄悄地割下掃羅外袍的衣角。","notes":[]},{"n":5,"t":"隨後大衛心中自責，因為他割下了掃羅的衣角。","notes":[]},{"n":6,"t":"他對他的人說：「耶和華絕不允許我對我的主，耶和華的受膏者做這事，伸手害他，因為他是耶和華的受膏者。」","notes":[]},{"n":7,"t":"大衛用這話勸阻他的人，不許他們起來害掃羅。掃羅起來，從洞裏出去，預備上路。","notes":[]},{"n":8,"t":"然後大衛也起來，從洞裏出去，呼喚掃羅說：「我主，我王！」掃羅回頭觀看，大衛就屈身，臉伏於地下拜。","notes":[]},{"n":9,"t":"大衛對掃羅說：「你為何聽信人的讒言，說『看哪，大衛想要害你』呢？","notes":[]},{"n":10,"t":"看哪，今日你親眼看見，在洞中耶和華將你交在我手裏。有人要我殺你，我卻愛惜你，說：『我不敢伸手害我的主，因為他是耶和華的受膏者。』","notes":[]},{"n":11,"t":"我父啊，請看，看你外袍的衣角在我手中。我割下你外袍的衣角，卻沒有殺你。你知道，並且看見我沒有惡意要悖逆你。你雖然要獵取我的命，我卻沒有得罪你。","notes":[]},{"n":12,"t":"願耶和華在你我中間判斷，願耶和華在你身上為我伸冤，我卻不親手加害於你。","notes":[]},{"n":13,"t":"古人有句俗語說：『惡事出於惡人。』我卻不親手加害於你。","notes":[]},{"n":14,"t":"以色列王出來要尋找誰呢？你要追趕誰呢？不過是一條死狗，一隻跳蚤而已。","notes":[]},{"n":15,"t":"願耶和華作仲裁者，在你我中間判斷。願他鑒察，為我伸冤，救我脫離你的手。」","notes":[]},{"n":16,"t":"大衛向掃羅說完了這些話，掃羅說：「我兒大衛，這是你的聲音嗎？」於是掃羅放聲大哭，","notes":[]},{"n":17,"t":"對大衛說：「你比我公義，因為你以善待我，我卻以惡待你。","notes":[]},{"n":18,"t":"今日你已顯明是以善待我，因為耶和華將我交在你手裏，你卻沒有殺我。","notes":[]},{"n":19,"t":"人若遇見仇敵，豈肯放他平安上路呢？願耶和華因你今日向我所做的，以善回報你。","notes":[]},{"n":20,"t":"現在，看哪，我知道你一定會作王，以色列的國必要堅立在你手裏。","notes":[]},{"n":21,"t":"現在你要指著耶和華向我起誓，你必不剪除我的後裔，必不從我父家除去我的名。」","notes":[]},{"n":22,"t":"於是大衛向掃羅起誓，掃羅就回家去，大衛和他的人也上山寨去了。","notes":[]}]},"25":{"heading":"撒母耳去世","verses":[{"n":1,"t":"撒母耳死了，以色列眾人聚集，為他哀哭，把他葬在拉瑪他的家裏。大衛動身，下到巴蘭的曠野。","notes":[]},{"n":2,"t":"在瑪雲有一個人，他的產業在迦密。這人是一個大富翁，有三千隻綿羊，一千隻山羊；他正在迦密剪羊毛。","notes":[]},{"n":3,"t":"這人名叫拿八，他的妻子名叫亞比該。拿八的妻子有美好的見識，又有美麗的容貌，但拿八為人剛愎兇惡，是迦勒族的人。","notes":[]},{"n":4,"t":"大衛在曠野聽見拿八正在剪羊毛，","notes":[]},{"n":5,"t":"就派十個僕人，對他們說：「你們上迦密到拿八那裏，提我的名向他問安。","notes":[]},{"n":6,"t":"你們要如此說：『願你來年平安，願你家平安，願你一切所有的都平安。","notes":["「你們要...來年平安」：有古譯本是「你們要向我的弟兄如此說：願你平安」。"]},{"n":7,"t":"現在我聽說你有剪羊毛的人，你的牧人和我們在一起，他們在迦密一切的日子，我們沒有欺負過他們，他們也未曾失去甚麼。","notes":[]},{"n":8,"t":"你問你的僕人，他們會告訴你。願我的僕人在你眼前得歡心，因為我們是在好日子來的。請你隨手分點食物給僕人和你兒子大衛。』」","notes":[]},{"n":9,"t":"大衛的僕人到了，就提大衛的名，把這一切話告訴拿八，他們就停頓下來。","notes":[]},{"n":10,"t":"拿八回答大衛的僕人說：「大衛是誰？耶西的兒子是誰？今日悖逆主人奔逃的僕人很多。","notes":[]},{"n":11,"t":"我豈可把飲食，以及我為剪羊毛的人所宰的肉給那些我不知道從哪裏來的人呢？」","notes":[]},{"n":12,"t":"大衛的僕人轉身從原路回去，照這一切的話告訴大衛。","notes":[]},{"n":13,"t":"大衛對他的人說：「你們各人都要佩上刀！」各人就都佩上刀，大衛也佩上刀。跟隨大衛上去的約有四百人，留下二百人看守物件。","notes":[]},{"n":14,"t":"拿八的一個僕人告訴拿八的妻子亞比該說：「看哪，大衛從曠野派使者來向我主人問安，主人卻辱罵他們。","notes":[]},{"n":15,"t":"但是那些人待我們真好；我們在田野與他們一切來往的日子，沒有受他們欺負，也未曾失去甚麼。","notes":[]},{"n":16,"t":"我們在他們那裏牧羊，一切的日子他們晝夜保護我們。","notes":["「保護我們」：原文直譯「作我們的牆壁」。"]},{"n":17,"t":"現在，你當知道，看怎樣做才好。不然，禍患必定臨到我主人和他全家。他性情兇暴，無人敢與他說話。」","notes":[]},{"n":18,"t":"亞比該急忙將二百個餅，兩皮袋酒，五隻宰好的羊，五細亞烘熟的穗子，一百個葡萄乾餅，二百個無花果餅，都馱在驢上，","notes":[]},{"n":19,"t":"對僕人說：「你們在我前面走，看哪，我跟著你們去。」她卻沒有告訴丈夫拿八。","notes":[]},{"n":20,"t":"亞比該騎著驢，正下山坡，看哪，大衛和他的人正迎著亞比該下來，她就去迎接他們。","notes":[]},{"n":21,"t":"大衛曾說：「我在曠野為那人看守他一切所有的，以致他未失去任何一樣東西，實在是徒然了！他竟然向我以惡報善。","notes":[]},{"n":22,"t":"凡屬拿八的男丁，我若留一個到明日早晨，願神重重懲罰大衛！」","notes":["「大衛」是根據七十士譯本；原文是「大衛的仇敵」。"]},{"n":23,"t":"亞比該看見大衛，就急忙下驢，在大衛面前臉伏於地叩拜。","notes":[]},{"n":24,"t":"她俯伏在大衛的腳前，說：「我主啊，願這罪歸於我！求你容許使女向你進言，更求你聽使女的話。","notes":[]},{"n":25,"t":"我主不必理會拿八這性情兇暴的人，他就像他的名字一樣；他名叫拿八，為人也真是愚頑。至於我，你的使女並沒有看見我主所派來的僕人。","notes":["「拿八」意思是「愚頑」。"]},{"n":26,"t":"現在，我主啊，耶和華既然阻止你親手報仇，避免流人的血，我指著永生的耶和華起誓，又指著你的性命起誓：『現在，願你的仇敵和謀害我主的人都像拿八一樣。』","notes":[]},{"n":27,"t":"現在求我主把婢女送來的禮物給跟隨我主的僕人。","notes":[]},{"n":28,"t":"求你原諒使女的冒犯。耶和華必為我主建立堅固的家，因為我主為耶和華爭戰，並且你一生的日子查不出有甚麼惡來。","notes":[]},{"n":29,"t":"雖有人起來追逼你，要尋索你的性命，我主的性命在耶和華－你的神那裏，如同藏在生命的寶藏中。至於你仇敵的性命，耶和華必甩去，如用機弦甩石一樣。","notes":[]},{"n":30,"t":"耶和華照所應許你的福氣賜給我主，立你作以色列王的時候，","notes":[]},{"n":31,"t":"我主就不至於因為親手報仇，流了無辜人的血，而心裏不安，良心有虧了。耶和華賜福給我主的時候，求你記得你的使女。」","notes":[]},{"n":32,"t":"大衛對亞比該說：「耶和華－以色列的神是應當稱頌的，因為他今日派你來迎接我。","notes":[]},{"n":33,"t":"你和你的見識也配得稱讚，因為你今日攔阻我親手報仇、流人的血。","notes":[]},{"n":34,"t":"我指著阻止我加害於你的耶和華－以色列永生的神起誓，若不是你很快地來迎接我，到早晨天亮的時候，凡屬拿八的男丁，必定一個也不留。」","notes":[]},{"n":35,"t":"大衛從亞比該手中收了她帶來的禮物，對她說：「平平安安上你的家去吧！你看，我看了你的情面，聽了你的話。」","notes":[]},{"n":36,"t":"亞比該到拿八那裏，看哪，他在家裏擺設宴席，如同王的宴席。拿八心情舒暢，酩酊大醉。所以亞比該大小事都沒有告訴他，直等到早晨天亮的時候。","notes":[]},{"n":37,"t":"到了早晨，拿八酒醒了，他的妻子把這些事都告訴他，他就發心臟病快死了，僵如石頭。","notes":[]},{"n":38,"t":"過了十天，耶和華擊打拿八，他就死了。","notes":[]},{"n":39,"t":"大衛聽見拿八死了，就說：「耶和華是應當稱頌的，因為我從拿八手中受了羞辱，他為我伸冤，又阻止他的僕人行惡；耶和華使拿八的惡歸到他自己頭上。」於是大衛派人去向亞比該說，要娶她為妻。","notes":[]},{"n":40,"t":"大衛的僕人來到迦密，到亞比該那裏，對她說：「大衛派我們到你這裏，要娶你作他的妻子。」","notes":[]},{"n":41,"t":"亞比該起來叩拜，俯伏在地，說：「看哪，你的使女情願作婢女，為我主的僕人洗腳。」","notes":[]},{"n":42,"t":"亞比該立刻起身，騎上驢，五個女僕跟著她走。她跟從大衛的使者去，就作了大衛的妻子。","notes":[]},{"n":43,"t":"大衛先前娶了耶斯列人亞希暖，她們二人都作了他的妻子。","notes":[]},{"n":44,"t":"掃羅已把他的女兒米甲，就是大衛的妻子，給了迦琳人拉億的兒子帕提為妻。","notes":[]}]},"26":{"heading":"大衛又饒掃羅的命","verses":[{"n":1,"t":"西弗人來到基比亞，到掃羅那裏，說：「大衛不是在荒野東邊的哈基拉山藏著嗎？」","notes":["「荒野」或音譯「約斯門」；下同。","「東邊」或譯「前面」；下同。"]},{"n":2,"t":"掃羅動身，帶領以色列人中挑選的三千精兵下到西弗的曠野，要在那裏尋索大衛。","notes":[]},{"n":3,"t":"掃羅在荒野東邊的哈基拉山，在路旁安營。那時大衛住在曠野，看見掃羅到曠野來追趕他，","notes":[]},{"n":4,"t":"大衛就派人去探聽，知道掃羅果然來了。","notes":[]},{"n":5,"t":"大衛起來，到掃羅安營的地方，看見掃羅和尼珥的兒子押尼珥元帥躺臥之處；掃羅睡在軍營裏，士兵安營在他周圍。","notes":[]},{"n":6,"t":"大衛對赫人亞希米勒和洗魯雅的兒子約押的兄弟亞比篩說：「誰同我下到掃羅營裏去？」亞比篩說：「我同你下去。」","notes":[]},{"n":7,"t":"於是大衛和亞比篩夜間到了士兵那裏；看哪，掃羅睡在軍營裏，他的槍在頭旁，插在地上。押尼珥和士兵睡在他周圍。","notes":[]},{"n":8,"t":"亞比篩對大衛說：「神將你的仇敵交在你手裏，現在讓我拿槍把他刺透在地上，一刺就成，不用再刺他了。」","notes":[]},{"n":9,"t":"大衛對亞比篩說：「不可殺害他！有誰伸手害耶和華的受膏者而無罪呢？」","notes":[]},{"n":10,"t":"大衛又說：「我指著永生的耶和華起誓，他或被耶和華擊殺，或死期到了，或出戰陣亡，","notes":[]},{"n":11,"t":"耶和華絕不允許我伸手害耶和華的受膏者。現在你可以把他頭旁的槍和水壺拿來，我們就走。」","notes":[]},{"n":12,"t":"大衛從掃羅的頭旁拿了槍和水壺，他們就走了。沒有人看見，沒有人知道，也沒有人醒過來。他們都睡著了，因為耶和華使他們沉睡了。","notes":[]},{"n":13,"t":"大衛過到另一邊去，遠遠地站在山頂上，與他們相離很遠。","notes":[]},{"n":14,"t":"大衛呼叫百姓和尼珥的兒子押尼珥說：「押尼珥，你為何不回答呢？」押尼珥回答說：「你是誰？竟敢呼喚王呢？」","notes":[]},{"n":15,"t":"大衛對押尼珥說：「你不是個大丈夫嗎？以色列中誰能比你呢？百姓中有一個人進來要害死你主你王，你為何沒有保護你主你王呢？","notes":[]},{"n":16,"t":"你做的這件事不好！我指著永生的耶和華起誓，你們都是該死的，因為你們沒有保護你們的主，就是耶和華的受膏者。現在你看，王頭旁的槍和水壺在哪裏？」","notes":[]},{"n":17,"t":"掃羅認出大衛的聲音，就說：「我兒大衛，這是你的聲音嗎？」大衛說：「我主我王啊，是我的聲音。」","notes":[]},{"n":18,"t":"又說：「我主為何要追趕僕人呢？我做了甚麼？我手做了甚麼惡事呢？","notes":[]},{"n":19,"t":"現在求我主我王聽僕人的話：若是耶和華激發你來攻擊我，願耶和華悅納供物；若是出於人，願他們在耶和華面前受詛咒，因為他們今日趕逐我，不讓我在耶和華的產業中有分，說：『你去事奉別神吧！』","notes":[]},{"n":20,"t":"現在不要使我的血流在遠離耶和華面的地上。因為以色列王出來，只不過是尋找一隻跳蚤，如同人在山上獵取一隻鷓鴣。」","notes":[]},{"n":21,"t":"掃羅說：「我有罪了！我兒大衛，回來吧！我必不再加害於你，因為你今日看我的性命為寶貴。看哪，我是個糊塗人，大大錯了。」","notes":[]},{"n":22,"t":"大衛回答說：「看哪，這是王的槍，可以吩咐一個僕人過來拿去。","notes":[]},{"n":23,"t":"今日耶和華將王交在我手裏，我卻不肯伸手害耶和華的受膏者。耶和華必照各人的公義誠實報應他。","notes":[]},{"n":24,"t":"看哪，我今日看重你的性命，願耶和華也照樣看重我的性命，並且拯救我脫離一切患難。」","notes":[]},{"n":25,"t":"掃羅對大衛說：「我兒大衛，願你得福！你必做大事，也必得勝。」於是大衛上路，掃羅也回自己的地方去了。","notes":[]}]},"27":{"heading":"大衛在非利士人中","verses":[{"n":1,"t":"大衛心裏說：「總有一天我會死在掃羅手裏，現在我最好逃到非利士人的地去，掃羅就會絕望，不會繼續在以色列全境內尋索我了。這樣，我才可以脫離他的手。」","notes":[]},{"n":2,"t":"於是大衛動身，和跟隨他的六百人投奔瑪俄的兒子迦特王亞吉去了。","notes":[]},{"n":3,"t":"大衛和他的兩個妻子，就是耶斯列人亞希暖和作過拿八妻子的迦密人亞比該，以及他的人，連同各人的眷屬，都住在迦特的亞吉那裏。","notes":[]},{"n":4,"t":"有人告訴掃羅：「大衛逃到迦特。」掃羅就不再尋索他了。","notes":[]},{"n":5,"t":"大衛對亞吉說：「我若蒙你看得起，求你在郊外的城鎮中賜我一個地方，讓我住在那裏。僕人何必與王同住京城呢？」","notes":[]},{"n":6,"t":"當日亞吉把洗革拉賜給他，因此洗革拉屬於猶大王，直到今日。","notes":[]},{"n":7,"t":"大衛在非利士人的地，住的期間有一年四個月。","notes":[]},{"n":8,"t":"大衛和他的人上去，侵奪基述人、基色人、亞瑪力人，這些是從帖蘭經過書珥直到埃及地的居民。","notes":["「這些是<ins>.的居民」是根據七十士譯本；原文是「這些居民歷來就在那地，從書珥直到埃及地」。"]},{"n":9,"t":"大衛攻擊那地，無論男女沒有留下一個活口，又奪獲牛、羊、驢、駱駝和衣服，回來到亞吉那裏。","notes":[]},{"n":10,"t":"亞吉說：「今日你們沒有去搶奪甚麼地方吧？」大衛說：「侵奪了猶大、耶拉篾、基尼等地的南方。」","notes":["「今日</ins>.地方吧」：死海古卷和一些古譯本是「你們今日侵奪了誰呢」。"]},{"n":11,"t":"無論男女，大衛沒有留下一個活口帶到迦特來。他說：「恐怕他們把我們的事告訴人，說：『大衛如此做了。』」這是他住在非利士人之地一切日子的慣例。","notes":[]},{"n":12,"t":"亞吉信了大衛，說：「大衛已經使本族以色列人憎惡他，所以他必永遠作我的僕人了。」","notes":[]}]},"28":{"heading":"掃羅求問女巫","verses":[{"n":1,"t":"那時，非利士人召集軍隊，要與以色列打仗。亞吉對大衛說：「你當知道，你和你的人都要隨我出征。」","notes":[]},{"n":2,"t":"大衛對亞吉說：「好，僕人所能做的事，王都知道。」亞吉對大衛說：「好，我立你終生作我的侍衛。」","notes":["「我」：原文是「我的頭」。"]},{"n":3,"t":"那時撒母耳已經死了，以色列眾人為他哀哭，把他葬在他的本城拉瑪。掃羅曾在國內驅除招魂的和行巫術的人。","notes":[]},{"n":4,"t":"非利士人集合，來到書念安營；掃羅集合以色列眾人在基利波安營。","notes":[]},{"n":5,"t":"掃羅看見非利士的軍隊，就懼怕，心中大大戰兢。","notes":[]},{"n":6,"t":"掃羅求問耶和華，耶和華卻不藉夢，或烏陵，或先知回答他。","notes":[]},{"n":7,"t":"掃羅吩咐臣僕說：「為我找一個招魂的婦人，我好去問她。」臣僕對他說：「看哪，在隱‧多珥有一個招魂的婦人。」","notes":[]},{"n":8,"t":"於是掃羅改了裝，穿上別的衣服，帶著兩個人，夜裏去見那婦人。掃羅說：「請你用招魂的法術，把我所告訴你的死人，為我招上來。」","notes":[]},{"n":9,"t":"婦人對他說：「看哪，你知道掃羅所做的，他從國中剪除招魂的和行巫術的。你為何為我的性命設下羅網，要害死我呢？」","notes":[]},{"n":10,"t":"掃羅向婦人指著耶和華起誓說：「我指著永生的耶和華起誓，你必不因這事受罰。」","notes":[]},{"n":11,"t":"婦人說：「我為你招誰上來呢？」他說：「為我招撒母耳上來。」","notes":[]},{"n":12,"t":"婦人看見撒母耳，就大聲喊叫。婦人對掃羅說：「你是掃羅，為甚麼欺騙我呢？」","notes":[]},{"n":13,"t":"王對婦人說：「不要懼怕，你看見甚麼呢？」婦人對掃羅說：「我看見有神明從地裏上來。」","notes":[]},{"n":14,"t":"掃羅說：「他是怎樣的形狀？」婦人說：「有一個老人上來，身穿長袍。」掃羅知道是撒母耳，就屈身，臉伏於地下拜。","notes":[]},{"n":15,"t":"撒母耳對掃羅說：「你為甚麼攪擾我，招我上來呢？」掃羅說：「我十分為難，因為非利士人攻擊我，神離開我，不再藉先知或夢回答我。因此請你上來，好指示我應當怎樣做。」","notes":[]},{"n":16,"t":"撒母耳說：「耶和華已經離開你，與你為敵，你何必問我呢？","notes":[]},{"n":17,"t":"耶和華照他藉我所說的話為他自己實現了。耶和華已經從你手裏奪去國權，賜給別人，就是大衛。","notes":["「為他自己」：七十士譯本是「向你」。"]},{"n":18,"t":"因為你沒有聽從耶和華的話，沒有執行他對亞瑪力人的惱怒，所以今日耶和華向你做這事。","notes":[]},{"n":19,"t":"耶和華也必將你和以色列交在非利士人手裏。明日你和你兒子們必與我在一處了；耶和華也必將以色列的軍兵交在非利士人手裏。」","notes":[]},{"n":20,"t":"掃羅突然全身仆倒在地，因為撒母耳的話令他十分懼怕。他毫無氣力，因為他一日一夜都沒有吃甚麼。","notes":[]},{"n":21,"t":"婦人到掃羅面前，見他極其驚恐，對他說：「看哪，婢女聽從了你，不顧惜自己的性命，遵從你吩咐我的話。","notes":[]},{"n":22,"t":"現在求你也聽婢女的話，讓我在你面前擺上一點食物，你吃了才有氣力上路。」","notes":[]},{"n":23,"t":"掃羅不肯，說：「我不吃。」但他的僕人和那婦人再三勸他，他才聽他們的話，從地上起來，坐在床上。","notes":[]},{"n":24,"t":"婦人急忙把家裏的一隻肥牛犢宰了，又拿麵來揉，烤成無酵餅，","notes":[]},{"n":25,"t":"擺在掃羅和他僕人面前。他們吃了，當夜就起身走了。","notes":[]}]},"29":{"heading":"非利士人拒絕大衛","verses":[{"n":1,"t":"非利士人聚集他們所有的軍隊到亞弗；以色列人在耶斯列的泉旁安營。","notes":[]},{"n":2,"t":"非利士人的領袖各率隊伍，或百或千的前進；大衛和他的人同亞吉跟在後邊前進。","notes":[]},{"n":3,"t":"非利士人的領袖說：「這些希伯來人在這裏做甚麼呢？」亞吉對非利士人的領袖說：「這不是以色列王掃羅的臣僕大衛嗎？他在我這裏有些年日了。自從他投降直到今日，我未曾見他有甚麼過錯。」","notes":[]},{"n":4,"t":"非利士人的領袖向亞吉發怒，對他說：「叫這人回去！叫他回到你指派他的地方去，不可讓他同我們出征，免得他在陣上反成為我們的敵人。他用甚麼與他主人復和呢？豈不是用我們這些人的首級嗎？","notes":[]},{"n":5,"t":"有人跳舞唱和說：『掃羅殺死千千，大衛殺死萬萬』，不就是這個大衛嗎？」","notes":[]},{"n":6,"t":"亞吉叫大衛來，對他說：「我指著永生的耶和華起誓，你是個正直人。你隨我在軍中出入，我也很滿意。自從你投奔我到如今，我未曾看見你有甚麼過失，但是眾領袖看你不順眼。","notes":[]},{"n":7,"t":"現在你平平安安地回去，不要做非利士人領袖眼中看為惡的事。」","notes":[]},{"n":8,"t":"大衛對亞吉說：「但我做了甚麼呢？自從僕人到你面前，直到今日，你查出我有甚麼過錯，使我不去攻擊我主我王的仇敵呢？」","notes":[]},{"n":9,"t":"亞吉回答大衛說：「我知道你在我眼中是好人，如同神的使者一樣，只是非利士人的領袖說：『這人不可同我們上戰場。』","notes":[]},{"n":10,"t":"現在，你和跟隨你來的，就是你主人的僕人，清晨要早早起來，回到我所指派你的地方去，不要把中傷的話放在心上，因為你在我面前很好。你們清晨早早起來，天一亮就回去吧！」","notes":["「回到...很好」是根據七十士譯本；原文沒有。"]},{"n":11,"t":"於是大衛和他的人清晨早早起來，回到非利士人的地去。非利士人也上耶斯列去了。","notes":[]}]},"30":{"heading":"與亞瑪力人爭戰","verses":[{"n":1,"t":"第三日，大衛和他的人到了洗革拉。亞瑪力人已經侵奪尼革夫和洗革拉。他們攻破洗革拉，用火焚燒。","notes":[]},{"n":2,"t":"他們擄去城內的婦女和城中的大小人口，一個都沒有殺，全都帶走，他們就上路去了。","notes":[]},{"n":3,"t":"大衛和他的人到了那城，看哪，城已被火燒燬，他們的妻子兒女都被擄去了。","notes":[]},{"n":4,"t":"大衛和跟隨他的百姓就放聲大哭，直到沒有氣力再哭。","notes":[]},{"n":5,"t":"大衛的兩個妻子，耶斯列人亞希暖和作過拿八妻子的迦密人亞比該，也被擄去了。","notes":[]},{"n":6,"t":"大衛非常焦急，因為眾百姓為自己的兒女痛心，說要用石頭打死他。大衛卻倚靠耶和華─他的神，堅定自己。","notes":[]},{"n":7,"t":"大衛對亞希米勒的兒子亞比亞他祭司說：「請你把以弗得拿來給我。」亞比亞他就把以弗得拿給大衛。","notes":[]},{"n":8,"t":"大衛求問耶和華說：「我追趕這群人，是否追得上呢？」耶和華對他說：「你可以追，一定追得上，也一定救得回來。」","notes":[]},{"n":9,"t":"於是，大衛出發，他和跟隨他的六百人來到比梭溪，那些不能前去的就留在那裏。","notes":[]},{"n":10,"t":"大衛帶著四百人往前追趕；有二百人疲乏，不能過比梭溪，留在那裏。","notes":[]},{"n":11,"t":"這四百人在田野遇見一個埃及人，就帶他到大衛面前，給他餅吃，給他水喝，","notes":[]},{"n":12,"t":"又給他一塊無花果餅，兩個葡萄乾餅。他吃了，精神就恢復了，因為他三日三夜沒有吃餅，沒有喝水。","notes":[]},{"n":13,"t":"大衛對他說：「你是誰的人？你從哪裏來？」他說：「我是埃及的青年，是亞瑪力人的奴僕。因為我三天前生病，我主人就把我撇棄了。","notes":[]},{"n":14,"t":"我們侵奪了基利提的南方和屬猶大的地，以及迦勒地的南方，又用火燒了洗革拉。」","notes":[]},{"n":15,"t":"大衛對他說：「你肯領我們下到那群人那裏嗎？」他說：「你要向我指著神起誓，你不殺我，也不把我交在我主人手裏，我就領你下到那群人那裏。」","notes":[]},{"n":16,"t":"那人領大衛下去，看哪，他們分散在全地面，吃喝跳舞，因為他們從非利士人的地和猶大地擄來的財物非常多。","notes":[]},{"n":17,"t":"大衛擊殺他們，從黎明直到次日晚上，除了四百個騎駱駝逃走的青年之外，一個也沒有逃脫。","notes":[]},{"n":18,"t":"亞瑪力人所擄去的財物，大衛全都奪回，並救回他的兩個妻子。","notes":[]},{"n":19,"t":"凡亞瑪力人所擄去的，無論大小、兒女、掠物和一切被擄去的，大衛全都奪回來。","notes":[]},{"n":20,"t":"大衛所奪來的牛群羊群，有人趕在群畜前面，說：「這是大衛的掠物。」","notes":[]},{"n":21,"t":"大衛到了那疲乏不能跟隨、留在比梭溪的二百人那裏。他們出來迎接大衛和跟隨他的百姓。大衛上前向他們問安。","notes":[]},{"n":22,"t":"跟隨大衛去的人中，每一個惡人和無賴都說：「這些人既然沒有和我同去，我們所奪的財物就不分給他們，只把他們各人的妻子兒女給他們，讓他們帶回去就好了。」","notes":[]},{"n":23,"t":"大衛說：「我的弟兄，耶和華所賜給我們的，你們不可這麼做，因為他保佑了我們，把那群來攻擊我們的人交在我們手裏。","notes":[]},{"n":24,"t":"誰肯在這事上聽你們呢？上陣的分得多少，留下看守物件的也分得多少，大家應當平分。」","notes":[]},{"n":25,"t":"從那日起，大衛定此為以色列的律例典章，直到今日。","notes":[]},{"n":26,"t":"大衛到了洗革拉，從掠物中取些送給他的朋友，就是猶大的長老，說：「看哪，這是從耶和華仇敵那裏奪來的，送給你們作禮物。」","notes":[]},{"n":27,"t":"有在伯特利的，尼革夫之拉末的，雅提珥的，","notes":["「伯特利」可能是「彼土利」；參代上 4．30。"]},{"n":28,"t":"有在亞羅珥的，息末的，以實提莫的，","notes":[]},{"n":29,"t":"有在拉哈勒的，耶拉篾各城的，基尼各城的，","notes":[]},{"n":30,"t":"有在何珥瑪的，坡拉珊的，亞撻的，","notes":["「坡拉珊」：有古卷是「歌拉珊」。"]},{"n":31,"t":"有在希伯崙的，以及大衛和跟隨他的人經常進出之處的。","notes":[]}]},"31":{"heading":"掃羅和他兒子的死","verses":[{"n":1,"t":"非利士人攻打以色列。以色列人在非利士人面前逃跑，很多人在基利波山被殺仆倒。","notes":["「很多人」：原文是「他們」。"]},{"n":2,"t":"非利士人緊追掃羅和他的兒子，殺了掃羅的兒子約拿單、亞比拿達、麥基‧舒亞。","notes":[]},{"n":3,"t":"攻擊掃羅的戰事激烈，弓箭手追上他，他被弓箭手射中，傷勢很重。","notes":["「他被...傷勢很重」或譯「他在弓箭手前渾身戰抖」。"]},{"n":4,"t":"掃羅吩咐拿他兵器的人說：「你拔出刀來，把我刺死，免得那些未受割禮的人來刺我，凌辱我。」但拿兵器的人不肯，因為他非常懼怕。於是掃羅拿起刀來，伏在刀上。","notes":[]},{"n":5,"t":"拿兵器的人見掃羅已死，也伏在刀上跟他一起死。","notes":[]},{"n":6,"t":"這樣，掃羅和他三個兒子，與拿他兵器的人，以及他所有的人，都在那日一起死了。","notes":["七十士譯本沒有「以及他所有的人」。"]},{"n":7,"t":"住平原那邊和約旦河那邊的以色列人，見以色列軍兵逃跑，掃羅和他兒子都死了，就棄城逃跑。非利士人前來住在其中。","notes":[]},{"n":8,"t":"次日，非利士人來剝那些被殺之人的衣服，看見掃羅和他三個兒子仆倒在基利波山。","notes":[]},{"n":9,"t":"他們割下他的首級，剝了他的盔甲，派人到非利士人之地的四境，報信給他們廟裏的偶像和眾百姓。","notes":[]},{"n":10,"t":"他們將掃羅的盔甲放在亞斯她錄廟裏，把他的屍身釘在伯‧珊的城牆上。","notes":[]},{"n":11,"t":"基列的雅比居民聽見非利士人向掃羅所行的事，","notes":[]},{"n":12,"t":"他們所有的勇士就起身，走了一夜，把掃羅和他兒子的屍身從伯‧珊城牆上取下來，送到雅比，在那裏用火燒了，","notes":[]},{"n":13,"t":"把骸骨葬在雅比的柳樹下，並且禁食七日。","notes":[]}]}},"2SA":{"1":{"heading":"大衛為掃羅和約拿單悲泣","verses":[{"n":1,"t":"掃羅死後，大衛擊殺亞瑪力人回來，在洗革拉住了兩天。","notes":[]},{"n":2,"t":"第三天，看哪，有一人從掃羅的營裏出來，衣服撕裂，頭蒙灰塵，到大衛面前伏地叩拜。","notes":[]},{"n":3,"t":"大衛對他說：「你從哪裏來？」他說：「我從以色列的營裏逃來。」","notes":[]},{"n":4,"t":"大衛又對他說：「事情怎麼樣？請你告訴我。」他說：「士兵從陣上逃跑，也有許多士兵仆倒死亡，掃羅和他兒子約拿單也死了。」","notes":[]},{"n":5,"t":"大衛問報信的青年說：「你怎麼知道掃羅和他兒子約拿單死了呢？」","notes":[]},{"n":6,"t":"報信的青年說：「我恰巧到基利波山，看哪，掃羅靠在自己的槍上，看哪，有戰車、騎兵緊緊地追他。","notes":[]},{"n":7,"t":"他回頭看見我，就呼叫我。我說：『我在這裏。』","notes":[]},{"n":8,"t":"他問我說：『你是甚麼人？』我說：『我是亞瑪力人。』","notes":[]},{"n":9,"t":"他對我說：『請你站到我這裏來，把我殺死，因為我非常痛苦，只剩下一口氣。』","notes":[]},{"n":10,"t":"我就站到他那裏，殺了他，因為我知道他一倒下就活不了。然後，我把他頭上的冠冕和臂上的鐲子拿到我主這裏來。」","notes":[]},{"n":11,"t":"大衛就抓著自己的衣服，把衣服撕裂，所有跟隨他的人也都如此。","notes":[]},{"n":12,"t":"他們為掃羅和他兒子約拿單，以及耶和華的百姓和以色列家的人悲哀哭泣，禁食到晚上，因為他們都倒在刀下。","notes":[]},{"n":13,"t":"大衛問報信的青年說：「你是哪裏人？」他說：「我是一個寄居者的兒子，是亞瑪力人。」","notes":[]},{"n":14,"t":"大衛對他說：「你動手殺害耶和華的受膏者，怎麼不畏懼呢？」","notes":[]},{"n":15,"t":"大衛叫了一個僕人來，說：「來，殺了他！」僕人擊殺他，他就死了。","notes":[]},{"n":16,"t":"大衛對他說：「你的血歸到你自己頭上，因為你親口作證控訴自己，說：『我殺了耶和華的受膏者。』」","notes":[]},{"n":17,"t":"大衛作了這首哀歌，哀悼掃羅和他兒子約拿單，","notes":[],"heads":["大衛為掃羅和約拿單作哀歌"]},{"n":18,"t":"並吩咐人把這首「弓歌」教導猶大人，看哪，它寫在《雅煞珥書》上：","notes":[]},{"n":19,"t":"以色列啊，尊榮者在你的高處被殺！大英雄竟然仆倒！","notes":[]},{"n":20,"t":"不要在迦特報告，不要在亞實基倫街上傳揚，免得非利士的女子歡喜，免得未受割禮之人的女子歡樂。","notes":[]},{"n":21,"t":"基利波山哪，願你那裏沒有雨，沒有露！願你的田地無土產可作供物！因為英雄的盾牌在那裏受辱，掃羅的盾牌沒有抹油。","notes":[]},{"n":22,"t":"在被殺者的血前，在勇士的脂肪前，約拿單的弓絕不退縮，掃羅的刀斷不虛回。","notes":[]},{"n":23,"t":"掃羅和約拿單生時相悅相愛，死時也不分離。他們比鷹更快，比獅子還強。","notes":[]},{"n":24,"t":"以色列的女子啊，當為掃羅哭泣！他曾使你們穿朱紅色的美衣，使你們衣服有黃金的妝飾。","notes":[]},{"n":25,"t":"英雄竟然在陣上仆倒！約拿單竟然在你的高處被殺！","notes":[]},{"n":26,"t":"我兄約拿單哪，我為你悲傷！我甚喜愛你！你對我的愛何等奇妙，過於婦女的愛情。","notes":[]},{"n":27,"t":"英雄竟然仆倒！兵器竟然廢棄！","notes":[]}]},"2":{"heading":"大衛受膏為猶大王","verses":[{"n":1,"t":"此後，大衛求問耶和華說：「我可以上猶大的一個城去嗎？」耶和華對他說：「可以上去。」大衛說：「我上哪一個城去呢？」耶和華說：「希伯崙。」","notes":[]},{"n":2,"t":"於是大衛和他的兩個妻子，一個是耶斯列人亞希暖，一個是作過迦密人拿八妻子的亞比該，都上那裏去了。","notes":[]},{"n":3,"t":"大衛也把跟隨他的人和他們各人的眷屬一同帶上去，住在希伯崙的城鎮中。","notes":[]},{"n":4,"t":"猶大人來，在那裏膏大衛作猶大家的王。有人告訴大衛說：「埋葬掃羅的是基列的雅比人。」","notes":[]},{"n":5,"t":"大衛就派使者到基列的雅比人那裏，對他們說：「願耶和華賜福給你們！因為你們忠心對待你們的主掃羅，埋葬了他。","notes":[]},{"n":6,"t":"你們既做了這事，願耶和華以慈愛和信實待你們，我也要為此厚待你們。","notes":[]},{"n":7,"t":"現在，你們的主掃羅死了，猶大家也已經膏我作他們的王，你們的手要堅強，要作英勇的人。」","notes":[]},{"n":8,"t":"掃羅軍隊的元帥，尼珥的兒子押尼珥，曾將掃羅的兒子伊施‧波設帶過河，到瑪哈念，","notes":["「伊施‧波設」又名「伊施巴力」；參代上8．33，9．39；又名「亦施韋」，參撒上14．49；本卷書下同。"],"heads":["伊施‧波設作以色列王"]},{"n":9,"t":"立他作王，治理基列、亞書利、耶斯列、以法蓮、便雅憫和以色列眾人。","notes":[]},{"n":10,"t":"掃羅的兒子伊施‧波設登基的時候年四十歲，作以色列王二年，但是猶大家卻隨從大衛。","notes":[]},{"n":11,"t":"大衛在希伯崙作猶大家的王，共七年六個月。","notes":[]},{"n":12,"t":"尼珥的兒子押尼珥和掃羅的兒子伊施‧波設的僕人從瑪哈念出來，往基遍去。","notes":[],"heads":["掃羅家和大衛家爭戰"]},{"n":13,"t":"洗魯雅的兒子約押和大衛的僕人也出來，在基遍池旁與他們相遇；一隊坐在池的這邊，一隊坐在池的那邊。","notes":[]},{"n":14,"t":"押尼珥對約押說：「讓年輕人起來，在我們面前較量一下吧！」約押說：「讓他們起來吧。」","notes":[]},{"n":15,"t":"他們就起來，點了人數過來：屬掃羅兒子伊施‧波設的有便雅憫人十二名，大衛的僕人也有十二名。","notes":[]},{"n":16,"t":"每人抓住對方的頭，用刀刺對方的肋旁，一同仆倒。所以，那地叫做希利甲‧哈素林，就在基遍。","notes":[]},{"n":17,"t":"那日戰況激烈，押尼珥和以色列人敗在大衛的僕人面前。","notes":[]},{"n":18,"t":"在那裏有洗魯雅的三個兒子：約押、亞比篩、亞撒黑。亞撒黑的腳快如野地裏的羚羊；","notes":[]},{"n":19,"t":"亞撒黑追趕押尼珥，直追趕他不偏左右。","notes":[]},{"n":20,"t":"押尼珥回頭說：「亞撒黑，是你嗎？」他說：「是我。」","notes":[]},{"n":21,"t":"押尼珥對他說：「你轉左或轉右，去抓一個年輕人，剝去他的戰衣吧。」亞撒黑卻不肯轉開而不追趕他。","notes":[]},{"n":22,"t":"押尼珥又對亞撒黑說：「轉開，不要再追我了！我何必把你擊殺在地上呢？我若殺了你，怎麼有臉見你哥哥約押呢？」","notes":[]},{"n":23,"t":"亞撒黑仍不肯轉開，押尼珥就用回馬槍刺入他的肚腹，甚至槍從背後穿出，亞撒黑就仆倒在那裏，當場死了。眾人趕到亞撒黑仆倒而死的地方，就都站住。","notes":["「用回馬槍」或譯「用槍的後端」。"]},{"n":24,"t":"約押和亞比篩追趕押尼珥。日落的時候，他們到了通往基遍曠野的路旁，基亞對面的亞瑪山。","notes":[]},{"n":25,"t":"便雅憫人聚集在押尼珥後面，成為一隊，站在一座山頂上。","notes":[]},{"n":26,"t":"押尼珥呼叫約押說：「刀劍豈可永遠吞噬呢？你豈不知，結局必是痛苦的嗎？你要等到何時才叫百姓回去，不追趕他們的弟兄呢？」","notes":[]},{"n":27,"t":"約押說：「我指著永生的神起誓：你若沒有這麼說，百姓就必繼續追趕弟兄，直到早晨。」","notes":["「你若沒有這麼說...早晨」或譯「你若不曾那麼說，百姓就不會從早晨起來追趕他們的弟兄了。」"]},{"n":28,"t":"於是約押吹角，眾百姓就站住，不再追趕以色列人，也不再打仗了。","notes":[]},{"n":29,"t":"押尼珥和他的人整夜行過亞拉巴。他們過了約旦河，走過畢倫，到了瑪哈念。","notes":["「走過畢倫」或譯「走了一個上午」。"]},{"n":30,"t":"約押追趕押尼珥回來，聚集眾百姓，大衛的僕人中缺少了十九個人和亞撒黑。","notes":[]},{"n":31,"t":"但大衛的僕人殺了押尼珥的人，便雅憫人三百六十名。","notes":[]},{"n":32,"t":"他們把亞撒黑送到伯利恆，葬在他父親的墳墓裏。約押和他的人走了一整夜，天亮的時候他們才到希伯崙。","notes":[]}]},"3":{"heading":"大衛的兒子","verses":[{"n":1,"t":"掃羅家和大衛家爭戰許久。大衛家日見強盛，掃羅家卻日見衰弱。","notes":[]},{"n":2,"t":"大衛在希伯崙生了幾個兒子：長子暗嫩是耶斯列人亞希暖所生的；","notes":[]},{"n":3,"t":"次子基利押是作過迦密人拿八的妻子亞比該所生的；三子押沙龍是基述王達買的女兒瑪迦所生的；","notes":["「基利押」：代上3．1稱「但以利」。"]},{"n":4,"t":"四子亞多尼雅是哈及所生的；五子示法提雅是亞比她所生的；","notes":[]},{"n":5,"t":"六子以特念是大衛的妻子以格拉所生的。大衛這六個兒子都是在希伯崙生的。","notes":[]},{"n":6,"t":"掃羅家和大衛家爭戰的時候，押尼珥在掃羅家大有權勢。","notes":[],"heads":["押尼珥投效大衛"]},{"n":7,"t":"掃羅有一妃子，名叫利斯巴，是愛亞的女兒。一日，伊施‧波設對押尼珥說：「你為甚麼與我父的妃子同寢呢？」","notes":[]},{"n":8,"t":"押尼珥因伊施‧波設的話非常生氣，說：「我豈是狗的頭，向著猶大呢？我今日忠心對待你父掃羅的家和他的弟兄、朋友，不將你交在大衛手裏，今日你竟為這婦人責備我嗎？","notes":[]},{"n":9,"t":"願神重重懲罰押尼珥！我要照著耶和華起誓應許大衛的話為他成就，","notes":[]},{"n":10,"t":"廢去掃羅家的國度，建立大衛的王位，使他治理以色列和猶大，從但直到別是巴。」","notes":[]},{"n":11,"t":"伊施‧波設懼怕押尼珥，一句話也不能回答。","notes":[]},{"n":12,"t":"押尼珥派使者到大衛所在的地方，說：「這地歸誰呢？」又說：「你與我立約，看哪，我必幫助你，使全以色列都擁護你。」","notes":["「大衛所在的地方」：七十士譯本是「希伯崙大衛那裏」。"]},{"n":13,"t":"大衛說：「好！我與你立約。但有一件事我要求你，你來見我面的時候，除非把掃羅的女兒米甲帶來，就不必來見我的面了。」","notes":[]},{"n":14,"t":"大衛派使者到掃羅的兒子伊施‧波設那裏，說：「你要把我的妻子米甲歸還我；她是我從前用一百非利士人的包皮所聘定的。」","notes":[]},{"n":15,"t":"伊施‧波設就派人去，把米甲從拉億的兒子，她丈夫帕鐵那裏帶來。","notes":["「帕鐵」又名「帕提」；參撒上25．44。"]},{"n":16,"t":"米甲的丈夫跟著她，一面走一面哭，直跟到巴戶琳。押尼珥對他說：「你回去吧！」帕鐵就回去了。","notes":[]},{"n":17,"t":"押尼珥與以色列長老商議，說：「從前你們企盼大衛作王治理你們，","notes":[]},{"n":18,"t":"現在你們可以這樣做了。因為耶和華曾論到大衛說：『我必藉我僕人大衛的手，救我民以色列脫離非利士人和眾仇敵的手。』」","notes":[]},{"n":19,"t":"押尼珥也說給便雅憫人聽。押尼珥又到希伯崙，把以色列人和便雅憫全家所看為好的，說給大衛聽。","notes":[]},{"n":20,"t":"押尼珥帶著二十個人來到希伯崙大衛那裏，大衛就為押尼珥和他帶來的人擺設宴席。","notes":[]},{"n":21,"t":"押尼珥對大衛說：「我要起身去召集全以色列，來到我主我王這裏，與你立約，你就可以照你的心願作王，統治一切。」於是大衛送走押尼珥，他就平安地去了。","notes":[]},{"n":22,"t":"看哪，大衛的僕人和約押突擊回來，帶回許多掠物。那時押尼珥不在希伯崙大衛那裏，因大衛已經送他走，他也平安地去了。","notes":[],"heads":["押尼珥被殺"]},{"n":23,"t":"約押和跟隨他的全軍到了，有人告訴約押說：「尼珥的兒子押尼珥來到王這裏，王送走他，他也平安地去了。」","notes":[]},{"n":24,"t":"約押到王那裏，說：「你這是做甚麼呢？看哪，押尼珥來到你這裏，你為何送他走，讓他去了呢？","notes":[]},{"n":25,"t":"你知道，尼珥的兒子押尼珥來，是要騙你，要打聽你的出入，知道你一切所行的事。」","notes":[]},{"n":26,"t":"約押從大衛那裏出來，派些使者去追押尼珥，從西拉井那裏帶他回來，大衛卻不知道。","notes":[]},{"n":27,"t":"押尼珥回到希伯崙，約押領他到城門中間，要與他私下交談，就在那裏刺穿了他的肚腹。他就死了，因為他流了約押兄弟亞撒黑的血。","notes":[]},{"n":28,"t":"這事以後，大衛聽見了，說：「流尼珥兒子押尼珥的血，我和我的國在耶和華面前永遠是無辜的。","notes":[]},{"n":29,"t":"願這血歸到約押頭上和他父的全家；又願約押家不斷有患漏症的，長痲瘋的，架柺杖而行的，仆倒在刀下的，缺乏食物的。」","notes":["「痲瘋」泛指傳染性皮膚病。","「架柺杖而行的」是根據七十士譯本；原文直譯「把著紡車的」，意思是男人只能做當時女人做的工作。"]},{"n":30,"t":"約押和他弟弟亞比篩殺了押尼珥，是因為在基遍戰爭的時候，押尼珥殺了他們的弟弟亞撒黑。","notes":[]},{"n":31,"t":"大衛對約押和跟隨他的眾百姓說：「你們當撕裂衣服，腰束麻布，在押尼珥前面哀哭。」大衛王也跟在棺木後面。","notes":[],"heads":["安葬押尼珥"]},{"n":32,"t":"他們把押尼珥葬在希伯崙。王在押尼珥的墓旁放聲大哭，眾百姓也都哭了。","notes":[]},{"n":33,"t":"王為押尼珥舉哀，說：押尼珥怎麼會像愚頑人一樣地死呢？","notes":[]},{"n":34,"t":"你手未曾被捆綁，腳未曾被腳鐐鎖住。你仆倒，如仆倒在兇惡之子手下一樣。於是眾百姓又為押尼珥哀哭。","notes":[]},{"n":35,"t":"白天的時候，眾百姓來勸大衛吃飯，但大衛起誓說：「我若在太陽未下山以前吃飯，或吃任何東西，願神重重懲罰我！」","notes":[]},{"n":36,"t":"眾百姓知道了就看為好。凡王所做的，眾百姓都看為好。","notes":[]},{"n":37,"t":"那日，以色列眾百姓才知道殺尼珥的兒子押尼珥並非出於王意。","notes":[]},{"n":38,"t":"王對臣僕說：「你們豈不知今日在以色列中倒了一個作元帥的大人物嗎？","notes":[]},{"n":39,"t":"我雖然受膏為王，今日還是軟弱。洗魯雅的兩個兒子，這些人比我強硬。願耶和華照著惡人所行的惡報應他。」","notes":[]}]},"4":{"heading":"伊施‧波設被殺","verses":[{"n":1,"t":"掃羅的兒子伊施‧波設聽見押尼珥死在希伯崙，手就發軟，全以色列也都驚惶。","notes":[]},{"n":2,"t":"掃羅的兒子伊施‧波設有兩個軍官，一個叫巴拿，第二個叫利甲，都是便雅憫支派比錄人臨門的兒子；因為比錄也算是屬於便雅憫的。","notes":[]},{"n":3,"t":"比錄人先前逃到基他音，在那裏寄居，直到今日。","notes":[]},{"n":4,"t":"掃羅的兒子約拿單有一個兒子，名叫米非波設，是瘸腿的。掃羅和約拿單的消息從耶斯列傳來的時候，他才五歲。他的奶媽抱著他逃跑；因為跑得太急，孩子掉在地上，腿就瘸了。","notes":["「米非波設」：代上8．34，9．40稱「米力‧巴力」；七十士譯本的一些抄本是「米非巴力」；本卷書下同。"]},{"n":5,"t":"比錄人臨門的兩個兒子利甲和巴拿出去，天正熱的時候到了伊施‧波設的家。那時，伊施‧波設在睡午覺。","notes":[]},{"n":6,"t":"婦人進到房子中間，要取麥子。利甲和他的哥哥巴拿刺穿了伊施‧波設的肚腹，然後逃跑了。","notes":["本節七十士譯本是「看哪，看門的婦人清理麥子，累了就睡著了。利甲和巴拿兩兄弟就溜進去。」"]},{"n":7,"t":"他們進到房子的時候，伊施‧波設正躺在臥房的床上，他們就把他殺死，割了他的首級，拿著首級在亞拉巴的路上走了一整夜。","notes":[]},{"n":8,"t":"他們把伊施‧波設的首級拿到希伯崙大衛那裏，對王說：「王的仇敵掃羅曾尋索你的性命。看哪，這是他兒子伊施‧波設的首級；耶和華今日為我主我王在掃羅和他後裔身上報了仇。」","notes":[]},{"n":9,"t":"大衛回答比錄人臨門的兒子利甲和他哥哥巴拿說：「我指著救我性命脫離一切苦難、永生的耶和華起誓：","notes":[]},{"n":10,"t":"從前有人告訴我說：『看哪，掃羅死了。』他自以為報好消息，我就拿住他，把他殺在洗革拉，作為他報消息的賞賜。","notes":[]},{"n":11,"t":"更何況惡人把義人殺在他家的床上，我豈不從你們手中追討他的血，從地上除滅你們嗎？」","notes":[]},{"n":12,"t":"於是大衛吩咐僕人把他們殺了，砍斷他們的手腳，掛在希伯崙的池旁。然後，他們把伊施‧波設的首級葬在希伯崙押尼珥的墳墓裏。","notes":[]}]},"5":{"heading":"大衛作全以色列的王","verses":[{"n":1,"t":"以色列眾支派來到希伯崙見大衛，說：「看哪，我們是你的骨肉。","notes":[]},{"n":2,"t":"從前掃羅作我們王的時候，率領以色列人出入的是你。耶和華也曾對你說：『你必牧養我的百姓以色列，你必作以色列的君王。』」","notes":[]},{"n":3,"t":"於是以色列的眾長老都來到希伯崙見王 。大衛在希伯崙，在耶和華面前與他們立約，他們就膏大衛作以色列的王。","notes":[]},{"n":4,"t":"大衛登基的時候年三十歲，作王四十年。","notes":[]},{"n":5,"t":"他在希伯崙作猶大王七年六個月，在耶路撒冷作以色列和猶大王三十三年。","notes":[]},{"n":6,"t":"王和他的人到了耶路撒冷，要攻打住那地方的耶布斯人。耶布斯人對大衛說：「你必不能進到這裏，就是盲人、瘸子都可以把你擊退。」就是說：「大衛絕不能進到這裏。」","notes":[]},{"n":7,"t":"然而大衛攻取了錫安的堡壘，就是大衛的城。","notes":[]},{"n":8,"t":"當日，大衛說：「誰攻打耶布斯人，就要從水道上去，攻打我心裏所恨惡的瘸子、盲人。」因此有人說：「盲人和瘸子不得進殿裏去。」","notes":["「我心裏所恨惡的」：原文另譯「那些恨惡大衛的」。"]},{"n":9,"t":"大衛住在堡壘裏，給它起名叫大衛城。大衛又從米羅往內，周圍建築。","notes":["「米羅」是音譯，指「土堆的防禦工事」。"]},{"n":10,"t":"大衛日見強大，耶和華－萬軍之神與他同在。","notes":[]},{"n":11,"t":"推羅王希蘭派使者把香柏木運到大衛那裏，又派木匠和石匠給大衛建造宮殿。","notes":[]},{"n":12,"t":"大衛知道耶和華堅立他作以色列王，又為自己百姓以色列的緣故，使他的國興盛。","notes":[]},{"n":13,"t":"大衛離開希伯崙之後，在耶路撒冷又立后妃，又生兒女。","notes":[]},{"n":14,"t":"在耶路撒冷所生的孩子的名字是沙母亞、朔罷、拿單、所羅門、","notes":[]},{"n":15,"t":"益轄、以利書亞、尼斐、雅非亞、","notes":[]},{"n":16,"t":"以利沙瑪、以利雅大、以利法列。","notes":[]},{"n":17,"t":"非利士人聽見大衛受膏作以色列王，非利士眾人就上來尋索大衛。大衛聽見了，就下到堡壘去。","notes":[],"heads":["戰勝非利士人"]},{"n":18,"t":"非利士人來了，散佈在利乏音谷。","notes":[]},{"n":19,"t":"大衛求問耶和華說：「我可以上去攻打非利士人嗎？你將他們交在我手裏嗎？」耶和華對大衛說：「你可以上去，我必將非利士人交在你手裏。」","notes":[]},{"n":20,"t":"大衛來到巴力‧毗拉心，在那裏擊敗了非利士人。他說：「耶和華在我面前沖破敵人，如水沖破一樣。」因此他稱那地方為巴力‧毗拉心。","notes":[]},{"n":21,"t":"非利士人把偶像拋棄在那裏，大衛和他的人拿去了。","notes":[]},{"n":22,"t":"非利士人又上來，散佈在利乏音谷。","notes":[]},{"n":23,"t":"大衛求問耶和華；耶和華說：「不要直上，要繞到他們後頭，從桑樹林對面攻打他們。","notes":[]},{"n":24,"t":"你聽見桑樹梢上有腳步的聲音，就要急速前去，因為那時耶和華已經出去，在你前頭攻打非利士人的軍隊了。」","notes":[]},{"n":25,"t":"大衛就遵照耶和華所吩咐的去做，攻打非利士人，從迦巴直到基色。","notes":[]}]},"6":{"heading":"接約櫃到耶路撒冷","verses":[{"n":1,"t":"大衛又聚集以色列中所有挑選的人，共三萬名。","notes":[]},{"n":2,"t":"大衛起身，和跟隨他的眾百姓前往，要從巴拉‧猶大那裏將神的約櫃接上來；這約櫃是以坐在二基路伯上萬軍之耶和華的名所命名的。","notes":[]},{"n":3,"t":"他們將神的約櫃從山岡上亞比拿達的家裏抬出來，放在新車上；亞比拿達的兒子烏撒和亞希約趕這新車。","notes":[]},{"n":4,"t":"他們將神的約櫃從山岡上亞比拿達家裏抬出來，亞希約在約櫃前行走。","notes":["「趕這新車...抬出來」：七十士譯本是「趕這新車，神的約櫃在上面」。"]},{"n":5,"t":"大衛和以色列全家在耶和華面前，隨著松木製造的各樣樂器和琴、瑟、鼓、鈸、鑼跳舞。","notes":["「隨著松木製造的各樣樂器」：死海古卷一份抄本和七十士譯本是「竭盡力量，隨著詩歌」；參代上13．8。"]},{"n":6,"t":"到了拿艮的禾場，因為牛失前蹄 ，烏撒就伸手扶住神的約櫃。","notes":["「拿艮」：代上13．9是「基頓」。","「失前蹄」或譯「驚跳」。"]},{"n":7,"t":"耶和華的怒氣向烏撒發作；神因這冒犯在那裏擊打他，他就死在那裏，在神的約櫃旁。","notes":[]},{"n":8,"t":"大衛因耶和華突然衝出撞死烏撒就生氣，稱那地方為毗列斯‧烏撒，直到今日。","notes":[]},{"n":9,"t":"那日，大衛懼怕耶和華，說：「耶和華的約櫃怎可到我這裏來呢？」","notes":[]},{"n":10,"t":"於是大衛不願將耶和華的約櫃接進大衛城他自己的地方，卻轉送到迦特人俄別‧以東的家中。","notes":[]},{"n":11,"t":"耶和華的約櫃停在迦特人俄別‧以東家中三個月，耶和華賜福給俄別‧以東和他的全家。","notes":[]},{"n":12,"t":"有人告訴大衛王說：「耶和華因約櫃的緣故賜福給俄別‧以東的家和一切屬他的。」大衛就去，歡歡喜喜地將神的約櫃從俄別‧以東家中接上來，到大衛城裏。","notes":[]},{"n":13,"t":"抬耶和華約櫃的人走了六步，大衛就獻牛與肥畜為祭。","notes":[]},{"n":14,"t":"大衛穿著細麻布以弗得，在耶和華面前極力跳舞。","notes":[]},{"n":15,"t":"這樣，大衛和以色列全家歡呼吹角，將耶和華的約櫃接了上來。","notes":[]},{"n":16,"t":"耶和華的約櫃進大衛城的時候，掃羅的女兒米甲從窗戶裏往外觀看，見大衛王在耶和華面前踴躍跳舞，心裏就輕視他。","notes":[]},{"n":17,"t":"眾人將耶和華的約櫃請進去，安放在所預備的地方，就是大衛為它搭的帳幕中。大衛在耶和華面前獻燔祭和平安祭。","notes":[]},{"n":18,"t":"大衛獻完了燔祭和平安祭，就奉萬軍之耶和華的名祝福百姓，","notes":[]},{"n":19,"t":"並且分給以色列眾人，所有的百姓，無論男女，每人一個餅，一個棗子餅，一個葡萄餅。眾人就各自回家去了。","notes":["「一個棗子餅」：有古譯本是「一塊肉」。"]},{"n":20,"t":"大衛回去要為家裏的人祝福，掃羅的女兒米甲出來迎接他，說：「以色列王今日有好大的榮耀啊！他今日在臣僕的使女眼前露體，如同一個無賴赤身露體一樣。」","notes":[]},{"n":21,"t":"大衛對米甲說：「這是在耶和華面前的。耶和華已揀選我，在你父和你父的全家之上，立我作耶和華百姓以色列的君王，所以我在耶和華面前跳舞，","notes":[]},{"n":22,"t":"我也必更加卑微，自己看為低賤。至於你所說的那些使女，她們反而尊重我。」","notes":["「自己看為低賤」：七十士譯本是「被你看為低賤」。"]},{"n":23,"t":"掃羅的女兒米甲，直到死的那日沒有孩子。","notes":[]}]},"7":{"heading":"拿單傳信息給大衛","verses":[{"n":1,"t":"王住在自己宮中，耶和華使他平靜，不被四圍的仇敵擾亂。","notes":[]},{"n":2,"t":"王對拿單先知說：「你看，我住在香柏木的宮中，神的約櫃卻停在幔子裏。」","notes":[]},{"n":3,"t":"拿單對王說：「你可以完全照你的心意去做，因為耶和華與你同在。」","notes":[]},{"n":4,"t":"當夜耶和華的話臨到拿單，說：","notes":[]},{"n":5,"t":"「你去對我僕人大衛說：『耶和華如此說：你要建造殿宇給我居住嗎？","notes":[]},{"n":6,"t":"自從我領以色列人從埃及上來，直到今日，我未曾住過殿宇，卻在會幕和帳幕中行走。","notes":[]},{"n":7,"t":"凡我同以色列人所走的地方，我何曾向以色列任何一個領袖，就是我吩咐牧養我百姓以色列的，說過這話：你們為何不給我建造香柏木的殿宇呢？』","notes":["「領袖」：原文是「支派」。"]},{"n":8,"t":"現在，你要對我僕人大衛這樣說：『萬軍之耶和華如此說：我從羊圈中將你召來，叫你不再牧放羊群，立你作我百姓以色列的君王。","notes":[]},{"n":9,"t":"你無論往哪裏去，我都與你同在，剪除你所有的仇敵。我必使你得大名，好像世上偉人的名一樣。","notes":[]},{"n":10,"t":"我必為我百姓以色列選定一個地方，栽植他們，使他們住自己的地方，不再受攪擾；兇惡之子也不像從前那樣苦待他們，","notes":[]},{"n":11,"t":"並不像我命令士師治理我百姓以色列的日子。我必使你平靜，不受任何仇敵攪擾，並且耶和華應許你，耶和華必為你建立家室。","notes":[]},{"n":12,"t":"當你壽數滿足、與你祖先同睡的時候，我必使你身所生的後裔接續你；我也必堅定他的國。","notes":[]},{"n":13,"t":"他必為我的名建造殿宇，我必堅定他國度的王位，直到永遠。","notes":[]},{"n":14,"t":"我要作他的父，他要作我的子；他若犯了罪，我必用人的杖，用世人的鞭責罰他。","notes":[]},{"n":15,"t":"但我的慈愛仍不離開他，像離開在你面前所廢的掃羅一樣。","notes":[]},{"n":16,"t":"你的家和你的國必在你面前永遠堅立，你的王位也必堅定，直到永遠。』」","notes":["「你」：有古卷和七十士譯本是「我」。"]},{"n":17,"t":"拿單就按這一切話，照這一切異象告訴大衛。","notes":[]},{"n":18,"t":"於是大衛王進去，坐在耶和華面前，說：「主耶和華啊，我是誰，我的家算甚麼，你竟帶領我到這地步呢？","notes":[],"heads":["大衛的祈禱和感恩"]},{"n":19,"t":"主耶和華啊，這在你眼中還看為小，你又說到你僕人的家將來的情況。主耶和華啊，這豈是人的常理嗎？","notes":[]},{"n":20,"t":"大衛還有甚麼可以對你說呢？主耶和華啊，你是知道你僕人的。","notes":[]},{"n":21,"t":"你行這一切大事，使你的僕人明白，是因你應許的緣故，也照著你的心意。","notes":[]},{"n":22,"t":"因此，主耶和華啊，你本為大；照我們耳中一切所聽見的，沒有可比你的，除你以外再沒有神。","notes":[]},{"n":23,"t":"誰像你的百姓以色列呢？神親自去救贖世上的一國，作自己的子民，顯出他的大名；為了你的地，從列國和他們的神明中，在你親自從埃及贖出來的子民面前，為自己行了大而可畏的事。","notes":["「誰像<ins>.一國」：七十士譯本是「世上有何國能比你的百姓以色列呢？神親自去救贖」。","「為了你的地</ins>.大而可畏的事」：七十士譯本是「在你親自從埃及贖出來的子民面前，為自己行了大而可畏的事，驅逐了列國和他們的神明」。"]},{"n":24,"t":"你曾堅立你的百姓以色列作你的子民，直到永遠；你－耶和華也作他們的神。","notes":[]},{"n":25,"t":"現在，耶和華神啊，你所應許僕人和僕人家的話，求你堅定，直到永遠；求你照你所說的而行。","notes":[]},{"n":26,"t":"願人永遠尊你的名為大，說：『萬軍之耶和華是治理以色列的神。』這樣，你僕人大衛的家必在你面前堅立。","notes":[]},{"n":27,"t":"萬軍之耶和華－以色列的神啊，因你啟示你的僕人說：『我必為你建立家室』，所以僕人大膽向你如此祈禱。","notes":[]},{"n":28,"t":"現在，主耶和華啊，惟有你是神！你的話是真實的，你也應許將這福氣賜給僕人。","notes":[]},{"n":29,"t":"現在，求你賜福給你僕人的家，可以永存在你面前。主耶和華啊，因為這是你所應許的。願你的福分永遠賜給你僕人的家，使之蒙福！」","notes":[]}]},"8":{"heading":"耶和華使大衛得勝","verses":[{"n":1,"t":"此後，大衛攻打非利士人，制伏了他們。大衛從非利士人手中奪取了京城的治理權。","notes":["「京城的治理權」：原文音譯「米特‧雅瑪」，意思是「母城的嚼環」。"]},{"n":2,"t":"他又攻打摩押人，使他們躺臥在地上，用繩來量，量二繩的殺了，量一繩的活著。摩押人就臣服大衛，向他進貢。","notes":[]},{"n":3,"t":"利合的兒子瑣巴王哈大底謝往幼發拉底河去，要奪回他的國權，大衛就攻打他，","notes":[]},{"n":4,"t":"俘擄了他的騎兵一千七百人，步兵二萬人。大衛把所有戰馬的蹄筋砍斷，只留下一百輛戰車。","notes":[]},{"n":5,"t":"大馬士革的亞蘭人來幫助瑣巴王哈大底謝，大衛殺了亞蘭人二萬二千。","notes":[]},{"n":6,"t":"於是大衛在大馬士革的亞蘭設立軍營，亞蘭人就臣服大衛，向他進貢。大衛無論往哪裏去，耶和華都使他得勝。","notes":[]},{"n":7,"t":"大衛奪了哈大底謝臣僕擁有的金盾牌，帶到耶路撒冷。","notes":[]},{"n":8,"t":"大衛王又從哈大底謝的比他和比羅他二城奪取了許多的銅。","notes":[]},{"n":9,"t":"哈馬王陀以聽見大衛擊敗哈大底謝的全軍，","notes":[]},{"n":10,"t":"就派他兒子約蘭到大衛王那裏，向他請安，為他祝福，因他與哈大底謝爭戰，並且擊敗了他；原來哈大底謝與陀以常常爭戰。約蘭手裏帶了金銀銅的器皿來。","notes":["「約蘭」：有古卷是「哈多蘭」；參代上18．10。"]},{"n":11,"t":"大衛王把這些器皿分別為聖，連同他制伏各國所分別為聖的金銀，獻給耶和華，","notes":[]},{"n":12,"t":"就是從亞蘭、摩押、亞捫人、非利士人、亞瑪力人，以及從利合的兒子瑣巴王哈大底謝所掠之物。","notes":["「亞蘭」：有古卷、七十士譯本和其他古譯本是「以東」。"]},{"n":13,"t":"大衛得了名聲。當他回來的時候，在鹽谷擊殺了一萬八千以東人。","notes":["「以東」是根據七十士譯本；原文是「亞蘭」。"]},{"n":14,"t":"大衛在以東設立軍營；他在全以東設立軍營，以東人就都臣服他。大衛無論往哪裏去，耶和華都使他得勝。","notes":[]},{"n":15,"t":"大衛作全以色列的王，又向眾百姓秉公行義。","notes":[]},{"n":16,"t":"洗魯雅的兒子約押作元帥；亞希律的兒子約沙法作史官；","notes":[]},{"n":17,"t":"亞希突的兒子撒督和亞比亞他的兒子亞希米勒作祭司；西萊雅作書記；","notes":[]},{"n":18,"t":"耶何耶大的兒子比拿雅管轄基利提人和比利提人。大衛的眾子都作祭司。","notes":["「管轄」是根據有些古卷和古譯本；參代上18．17；原文沒有。"]}]},"9":{"heading":"大衛和米非波設","verses":[{"n":1,"t":"大衛說：「掃羅家還有剩下的人沒有？我要因約拿單的緣故向他施恩。」","notes":[]},{"n":2,"t":"掃羅家有一個僕人名叫洗巴，有人叫他來到大衛那裏。王對他說：「你是洗巴嗎？」他說：「僕人是。」","notes":[]},{"n":3,"t":"王說：「掃羅家還有沒有剩下的人？我要照神的慈愛恩待他。」洗巴對王說：「還有約拿單的一個兒子，雙腿是瘸的。」","notes":[]},{"n":4,"t":"王對他說：「他在哪裏？」洗巴對王說：「看哪，他在羅‧底巴，亞米利的兒子瑪吉家裏。」","notes":[]},{"n":5,"t":"於是大衛王派人去，從羅‧底巴，亞米利的兒子瑪吉家裏召了他來。","notes":[]},{"n":6,"t":"掃羅的孫子，約拿單的兒子米非波設來到大衛那裏，臉伏於地叩拜。大衛說：「米非波設！」米非波設說：「看哪，僕人在此。」","notes":[]},{"n":7,"t":"大衛對他說：「你不要懼怕，我必因你父親約拿單的緣故向你施恩，把你祖父掃羅的一切田地都歸還你，你也可以常與我同席吃飯。」","notes":[]},{"n":8,"t":"米非波設叩拜，說：「你的僕人算甚麼，不過如死狗一般，竟蒙你這樣眷顧！」","notes":[]},{"n":9,"t":"王召了掃羅的僕人洗巴來，對他說：「我已把屬掃羅和他的一切家產都賜給你主人的兒子了。","notes":[]},{"n":10,"t":"你、你的眾子和僕人要為你主人的兒子耕種田地，把所收穫的拿來供他食用；你主人的兒子米非波設卻要常與我同席吃飯。」洗巴有十五個兒子和二十個僕人。","notes":[]},{"n":11,"t":"洗巴對王說：「凡我主我王吩咐僕人的，僕人都必遵行。」於是米非波設與王同席吃飯，如王的兒子一樣。","notes":["「王」：原文是「我」。"]},{"n":12,"t":"米非波設有一個小兒子，名叫米迦。凡住在洗巴家裏的人都作了米非波設的僕人。","notes":[]},{"n":13,"t":"米非波設住在耶路撒冷，常與王同席吃飯。他兩腿都是瘸的。","notes":[]}]},"10":{"heading":"擊敗亞捫人和亞蘭人","verses":[{"n":1,"t":"此後，亞捫人的王死了，他兒子哈嫩接續他作王。","notes":[]},{"n":2,"t":"大衛說：「哈嫩的父親拿轄怎樣向我施恩，我也要怎樣向哈嫩施恩。」於是大衛派臣僕為他的父親安慰他。當大衛的臣僕到了亞捫人的境內，","notes":[]},{"n":3,"t":"亞捫人的領袖對他們的主哈嫩說：「大衛派人來安慰你，你看他是要尊敬你父親嗎？大衛派臣僕到你這裏，不是為了要窺探偵察，而傾覆這城嗎？」","notes":[]},{"n":4,"t":"哈嫩就抓住大衛的臣僕，把他們的鬍鬚剃去一半，又割斷他們下半截的袍子，露出下體，然後放了他們。","notes":[]},{"n":5,"t":"有人告訴大衛，他就派人去迎接他們，因為這些人覺得很羞恥。王說：「可以住在耶利哥，等到鬍鬚長出來再回來。」","notes":[]},{"n":6,"t":"亞捫人看到大衛憎惡他們，就派人去雇用伯‧利合的亞蘭人和瑣巴的亞蘭人，步兵二萬，以及瑪迦王的人一千、陀伯人一萬二千。","notes":[]},{"n":7,"t":"大衛聽見了，就派約押和所有勇猛的軍隊出去。","notes":[]},{"n":8,"t":"亞捫人出來，在城門前擺陣；瑣巴與利合的亞蘭人、陀伯人，以及瑪迦人另外在郊野擺陣。","notes":[]},{"n":9,"t":"約押看見戰陣對著他前後擺列，就把從以色列所有精兵中挑選出來的，擺陣迎戰亞蘭人。","notes":[]},{"n":10,"t":"他把其餘的兵交在他兄弟亞比篩手裏，亞比篩就擺陣迎戰亞捫人。","notes":[]},{"n":11,"t":"約押對亞比篩說：「亞蘭人若強過我，你就來幫助我；亞捫人若強過你，我就去幫助你。","notes":[]},{"n":12,"t":"你要剛強，我們要為自己的百姓，為我們神的城鎮奮勇。願耶和華照他所看為好的去做！」","notes":[]},{"n":13,"t":"於是，約押和跟隨他的士兵前進攻打亞蘭人；亞蘭人在他面前逃跑。","notes":[]},{"n":14,"t":"亞捫人見亞蘭人逃跑，他們也在亞比篩面前逃跑進城。約押就離開亞捫人，回耶路撒冷去了。","notes":[]},{"n":15,"t":"亞蘭人見自己被以色列打敗，就集合起來。","notes":[]},{"n":16,"t":"哈大底謝派人去，把大河那邊的亞蘭人調來；他們到了希蘭，由哈大底謝的將軍朔法在他們前面率領。","notes":[]},{"n":17,"t":"有人告訴大衛，他就聚集以色列眾人過約旦河，來到希蘭。亞蘭人迎著大衛擺陣，與他打仗。","notes":[]},{"n":18,"t":"亞蘭人在以色列人面前逃跑。大衛殺了亞蘭七百輛戰車的士兵，四萬騎兵，又擊殺亞蘭的將軍朔法，他就死在那裏。","notes":["「騎兵」：七十士譯本的一些抄本是「步兵」；參代上19．18。"]},{"n":19,"t":"哈大底謝屬下的諸王見自己被以色列打敗，就與以色列講和，臣服他們。於是亞蘭人害怕，不再幫助亞捫人了。","notes":[]}]},"11":{"heading":"大衛和拔示巴","verses":[{"n":1,"t":"過了一年，正是諸王出戰的時候，大衛派約押率領臣僕和以色列眾人出去。他們打敗亞捫人，圍攻拉巴。大衛仍然留在耶路撒冷。","notes":[]},{"n":2,"t":"黃昏的時候，大衛從床上起來，在王宮的平頂上散步。他從平頂上看見一個婦人沐浴，這婦人容貌非常美麗。","notes":[]},{"n":3,"t":"大衛派人打聽那婦人是誰。有人說：「她不是以連的女兒，赫人烏利亞的妻子拔示巴嗎？」","notes":[]},{"n":4,"t":"大衛派使者去把婦人接來；她來到大衛那裏，那時她的月經剛潔淨，大衛與她同寢。她就回家去了。","notes":[]},{"n":5,"t":"那婦人懷了孕，派人去告訴大衛說：「我懷孕了。」","notes":[]},{"n":6,"t":"大衛派人告訴約押：「你派赫人烏利亞到我這裏來。」約押就派烏利亞到大衛那裏。","notes":[]},{"n":7,"t":"烏利亞來到大衛那裏，大衛問約押好，也問士兵好，又問戰爭的情況。","notes":[]},{"n":8,"t":"大衛對烏利亞說：「下到你家去，洗洗腳吧！」烏利亞出了王宮，隨後王送他一份禮物。","notes":[]},{"n":9,"t":"烏利亞卻和他主人所有的僕人一同睡在王宮門口，沒有下到他家去。","notes":[]},{"n":10,"t":"有人告訴大衛說：「烏利亞沒有下到他的家。」大衛就對烏利亞說：「你不是從遠路上來嗎？為甚麼不下到你家去呢？」","notes":[]},{"n":11,"t":"烏利亞對大衛說：「約櫃，以色列和猶大都留在棚裏，我主約押和我主的僕人都在田野安營，我豈可回家吃喝，與妻子同房呢？我指著王和王的性命起誓：『我絕不做這事！』」","notes":[]},{"n":12,"t":"大衛對烏利亞說：「你今日仍留在這裏，明日我打發你去。」於是烏利亞那日留在耶路撒冷。次日，","notes":[]},{"n":13,"t":"大衛召了烏利亞來，叫他在自己面前吃喝，使他喝醉。黃昏的時候，烏利亞出去，躺臥在自己的床上；與他主的僕人在一起，並沒有下到他的家去。","notes":[]},{"n":14,"t":"早晨，大衛寫信給約押，交烏利亞親手帶去。","notes":[],"heads":["大衛謀殺烏利亞"]},{"n":15,"t":"他在信內寫著說：「要派烏利亞到戰爭激烈的前線去，然後你們撤退離開他，使他被擊殺而死。」","notes":[]},{"n":16,"t":"約押偵察城的時候，知道敵人哪裏有勇士，就派烏利亞到那地方。","notes":[]},{"n":17,"t":"城裏的人出來和約押打仗，大衛的僕人中有幾個士兵被殺，赫人烏利亞也死了。","notes":[]},{"n":18,"t":"於是，約押派人去將戰爭的一切事奏告大衛，","notes":[]},{"n":19,"t":"又吩咐使者說：「你把戰爭的一切事對王說完了，","notes":[]},{"n":20,"t":"王若發怒，對你說：『你們打仗為甚麼挨近城呢？豈不知敵人會從城牆上射箭嗎？","notes":[]},{"n":21,"t":"從前擊殺耶路比設的兒子亞比米勒的是誰呢？豈不是一個婦人從城牆上拋下一塊上磨石來，打在他身上，他就死在提備斯嗎？你們為甚麼挨近城牆呢？』你就說：『你的僕人赫人烏利亞也死了。』」","notes":["「耶路比設」：七十士譯本是「耶路巴力」；參士9．1；撒上12．11。"]},{"n":22,"t":"使者就去，照著約押所吩咐的一切話來奏告大衛。","notes":["七十士譯本在此加：「大衛對約押發怒，對使者說：『你們打仗為甚麼挨近城呢？豈不知你們會從城牆受到傷害嗎？從前擊殺耶路巴力的兒子亞比米勒的是誰呢？豈不是一個婦人從城牆上拋下一塊上磨石來，打在他身上，他就死在提備斯嗎？你們為甚麼挨近城牆呢？』」"]},{"n":23,"t":"使者對大衛說：「敵人強過我們，出到郊外攻打我們，我們把他們趕回到城門口。","notes":[]},{"n":24,"t":"弓箭手從城牆上射你的僕人，射死幾個王的僕人，你的僕人赫人烏利亞也死了。」","notes":[]},{"n":25,"t":"大衛向使者說：「你對約押這樣說：『不要為這事難過，因為刀劍可能吞滅這人或那人。你只管竭力攻城，將城傾覆。』你要勉勵約押。」","notes":[]},{"n":26,"t":"烏利亞的妻聽見丈夫烏利亞死了，就為丈夫哀哭。","notes":[]},{"n":27,"t":"居喪的日子過了，大衛派人把她接到宮裏，她就作了大衛的妻子，給大衛生了一個兒子。但大衛做的這事，耶和華的眼中看為惡。","notes":[]}]},"12":{"heading":"拿單的信息和大衛的悔改","verses":[{"n":1,"t":"耶和華差遣拿單到大衛那裏。拿單到了他那裏，對他說：「在一座城裏有兩個人，一個是富翁，一個是窮人。","notes":[]},{"n":2,"t":"富翁有極多的牛群羊群；","notes":[]},{"n":3,"t":"窮人除了所買來養活的一隻小母羊之外，一無所有。小羊在他家裏和他兒女一同長大，吃他所吃的，喝他所喝的，睡在他懷中，在他看來如同女兒一樣。","notes":[]},{"n":4,"t":"有一客人來到這富翁那裏，富翁捨不得從自己的牛群羊群中取一隻招待來到他那裏的旅客，卻取了窮人的小母羊，招待來到他那裏的人。」","notes":[]},{"n":5,"t":"大衛就非常惱怒那人，對拿單說：「我指著永生的耶和華起誓，做這事的人該死！","notes":[]},{"n":6,"t":"他必須償還小母羊四倍，因為他做這事，沒有憐憫的心。」","notes":[]},{"n":7,"t":"拿單對大衛說：「你就是那人！耶和華－以色列的神如此說：『我膏你作以色列的王，我救你脫離掃羅的手；","notes":[]},{"n":8,"t":"我將你主人的家業賜給你，將你主人的妃嬪交在你懷裏，又將以色列和猶大家賜給你；若還嫌少，我也會如此這般加倍賜給你。","notes":[]},{"n":9,"t":"你為甚麼藐視耶和華的命令，做他眼中看為惡的事呢？你用刀擊殺赫人烏利亞，又娶了他的妻子為妻，借亞捫人的刀殺死他。","notes":[]},{"n":10,"t":"現在刀劍必永不離開你的家，因你藐視我，娶了赫人烏利亞的妻子為妻。』","notes":[]},{"n":11,"t":"耶和華如此說：『看哪，我必從你家中興起災禍攻擊你；我必在你眼前把你的妃嬪賜給你身邊的人，他要在光天化日下與你的妃嬪同寢。","notes":[]},{"n":12,"t":"你在暗中做那事，我卻要在以色列眾人面前，在日光之下做這事。』」","notes":[]},{"n":13,"t":"大衛對拿單說：「我得罪耶和華了！」拿單說：「耶和華已經除去你的罪，你必不至於死。","notes":[]},{"n":14,"t":"只是在這事上，你大大藐視耶和華，因此，你生的孩子必定要死。」","notes":["「耶和華」：原文是「耶和華的仇敵」；此句可能指「叫耶和華的仇敵大得褻瀆的機會」。"]},{"n":15,"t":"拿單就回家去了。耶和華擊打烏利亞的妻子為大衛生的孩子，他就得了重病。","notes":[]},{"n":16,"t":"大衛為這孩子懇求神。大衛刻苦禁食，到裏面去，躺在地上過夜。","notes":[]},{"n":17,"t":"他家中的老臣來到他旁邊，要把他從地上扶起來，他卻不肯，也不同他們吃飯。","notes":[]},{"n":18,"t":"到第七日，孩子死了。大衛的臣僕不敢告訴他孩子死了，因他們說：「看哪，孩子還活著的時候，我們勸他，他尚且不聽我們的話，我們怎麼能告訴他孩子死了，讓他做出不好的事呢？」","notes":[]},{"n":19,"t":"大衛見臣僕彼此低聲說話，就知道孩子死了。他問臣僕說：「孩子死了嗎？」他們說：「死了。」","notes":[]},{"n":20,"t":"大衛就從地上起來，沐浴，抹膏，換了衣服，進耶和華的殿敬拜。然後他回宮，吩咐人為他擺飯，他就吃了。","notes":[]},{"n":21,"t":"臣僕對他說：「你所做的是甚麼事呢？孩子活著的時候，你為他禁食哭泣；孩子死了，你卻起來吃飯。」","notes":[]},{"n":22,"t":"大衛說：「孩子還活著，我禁食哭泣，因為我想，或許耶和華憐憫我，會讓孩子活下來。","notes":[]},{"n":23,"t":"現在孩子死了，我何必禁食呢？我能使他回來嗎？我必往他那裏去，他卻不能回到我這裏來。」","notes":[]},{"n":24,"t":"大衛安慰他的妻子拔示巴，與她同房，她就生了兒子，給他起名叫所羅門。耶和華喜愛他，","notes":[],"heads":["所羅門出生"]},{"n":25,"t":"就藉拿單先知賜他一個名字，叫耶底底亞；這是為了耶和華的緣故。","notes":["「耶底底亞」意思是「耶和華所愛的」。"]},{"n":26,"t":"約押攻打亞捫人的拉巴，攻佔了京城。","notes":[],"heads":["大衛攻取拉巴"]},{"n":27,"t":"約押派使者到大衛那裏，說：「我攻打拉巴， 也攻佔了水城。","notes":[]},{"n":28,"t":"現在你要召集其餘的軍兵，安營圍攻這城，攻佔它，免得我攻佔這城，人就以我的名叫這城。」","notes":[]},{"n":29,"t":"於是大衛召集全軍，往拉巴去攻城，就攻佔了它。","notes":[]},{"n":30,"t":"他也奪了米勒公頭上所戴的冠冕，其上的金子重一他連得，又嵌著寶石。這冠冕就戴在大衛頭上。大衛又從城裏奪了許多財物，","notes":["「米勒公」是根據七十士譯本和其他古譯本，亞捫人神明的名字，又名「摩洛」；原文是「他們的王」，音譯「瑪勒堪」。"]},{"n":31,"t":"把城裏的百姓拉出來，叫他們用鋸，用鐵耙，用鐵斧做工，派他們在磚窯中服役；大衛待亞捫各城的居民都是如此。於是，大衛和全軍都回耶路撒冷去了。","notes":[]}]},"13":{"heading":"暗嫩和她瑪","verses":[{"n":1,"t":"後來發生了一件事。大衛的兒子押沙龍有一個美貌的妹妹，名叫她瑪。大衛的兒子暗嫩愛上了她。","notes":[]},{"n":2,"t":"暗嫩為他妹妹她瑪苦戀成疾，因為她瑪還是處女，暗嫩眼看難以向她行事。","notes":[]},{"n":3,"t":"暗嫩有一個密友，名叫約拿達，是大衛長兄示米亞的兒子。這約拿達為人極其狡猾。","notes":[]},{"n":4,"t":"他對暗嫩說：「王的兒子啊，你何不告訴我，為何你一天比一天憔悴呢？」暗嫩對他說：「我愛上了我兄弟押沙龍的妹妹她瑪。」","notes":[]},{"n":5,"t":"約拿達對他說：「你躺在床上裝病，等你父親來看你，就對他說：『請讓我妹妹她瑪來，給我東西吃，在我眼前預備食物，使我可以看見，好從她手裏接過來吃。』」","notes":[]},{"n":6,"t":"於是暗嫩躺著裝病，王來看他。暗嫩對王說：「請讓我妹妹她瑪來，在我眼前為我做兩個餅，我好從她手裏接過來吃。」","notes":[]},{"n":7,"t":"大衛就派人去宮裏，到她瑪那裏，說：「你到你哥哥暗嫩的屋裏去，為他預備食物。」","notes":[]},{"n":8,"t":"她瑪就到她哥哥暗嫩的屋裏，那時暗嫩正躺著。她瑪拿了麵團揉麵，在他眼前做餅，把餅烤熟了。","notes":[]},{"n":9,"t":"她瑪拿了鍋子，在他面前把餅倒出來，他卻不肯吃。暗嫩說：「每一個人都離開我，出去吧！」眾人就都離開他，出去了。","notes":[]},{"n":10,"t":"暗嫩對她瑪說：「你把食物拿進臥房，我好從你手裏接過來吃。」她瑪就把所做的餅拿進臥房，到她哥哥暗嫩那裏。","notes":[]},{"n":11,"t":"她瑪上前去給他吃，他就拉住她瑪，對她說：「我妹妹，你來與我同寢。」","notes":[]},{"n":12,"t":"她瑪對他說：「哥哥，不可以！不要玷辱我！以色列中不可以這樣做，你不要做這醜事！","notes":[]},{"n":13,"t":"我蒙受恥辱，該往那裏去呢？至於你，你在以色列中也成了一個愚頑人。現在你可以求王，他必不禁止我歸你。」","notes":[]},{"n":14,"t":"但暗嫩不肯聽她的話，因他比她更有力，就玷辱她，與她同寢。","notes":[]},{"n":15,"t":"隨後，暗嫩極其恨她，恨她的心比先前愛她的心更甚，就對她說：「你起來，去吧！」","notes":[]},{"n":16,"t":"她瑪對暗嫩說：「不要這樣！你趕我出去的這惡比你剛才向我所做的更嚴重！」但暗嫩不肯聽她，","notes":[]},{"n":17,"t":"就叫伺候自己的僕人來，說：「把這女子從我這裏趕出去！她一出去，你就閂上門。」","notes":[]},{"n":18,"t":"那時她瑪穿著彩衣，因為沒有出嫁的公主都穿這樣的外袍。暗嫩的僕人把她趕出去，她一出去，僕人就閂上門。","notes":[]},{"n":19,"t":"她瑪把灰塵撒在頭上，撕裂所穿的彩衣，以手抱頭，一面走一面哭喊。","notes":[]},{"n":20,"t":"她胞兄押沙龍對她說：「你哥哥暗嫩與你親近了嗎？妹妹，現在暫且不要作聲，他是你的哥哥，不要把這事放在心上。」她瑪就孤孤單單地住在她胞兄押沙龍的家裏。","notes":[]},{"n":21,"t":"大衛王聽見這一切的事，就非常憤怒。","notes":["七十士譯本在此加：「但他沒有為他兒子暗嫩的靈而憂愁，因為暗嫩是他所寵愛的長子。」"]},{"n":22,"t":"押沙龍卻不和暗嫩說好說歹；因為暗嫩玷辱他妹妹她瑪，所以押沙龍恨惡他。","notes":[]},{"n":23,"t":"過了二年，有人在靠近以法蓮的巴力‧夏瑣為押沙龍剪羊毛。押沙龍請了王所有的兒子來。","notes":[],"heads":["押沙龍為妹報仇"]},{"n":24,"t":"押沙龍來到王那裏，說：「看哪，有人正為你的僕人剪羊毛，請王和王的臣僕與你的僕人同去。」","notes":[]},{"n":25,"t":"王對押沙龍說：「不，我兒，我們不必都去，免得成了你的負擔。」押沙龍再三請王，王仍是不肯去，只為他祝福。","notes":[]},{"n":26,"t":"押沙龍說：「王若不去，請讓我哥哥暗嫩與我們同去。」王對他說：「為何要他與你同去呢？」","notes":[]},{"n":27,"t":"押沙龍再三求王，王就派暗嫩和王所有的兒子與他同去。","notes":[]},{"n":28,"t":"押沙龍吩咐僕人說：「你們注意， 暗嫩開懷暢飲的時候，我對你們說擊殺暗嫩，你們就殺他。不要懼怕，這不是我吩咐你們的嗎？你們要剛強，作勇士！」","notes":[]},{"n":29,"t":"押沙龍的僕人就照押沙龍所吩咐的，向暗嫩行了。王所有的兒子都起來，各人騎上騾子逃跑了。","notes":[]},{"n":30,"t":"他們還在路上，就有風聲傳到大衛那裏，說：「押沙龍擊殺了王所有的兒子，沒有留下一個。」","notes":[]},{"n":31,"t":"王就起來，撕裂衣服，躺在地上。王的臣僕全都撕裂衣服，站在旁邊。","notes":[]},{"n":32,"t":"大衛的長兄示米亞的兒子約拿達說：「我主，不要以為他們把所有的年輕人，就是王的兒子都殺了，只有暗嫩一個人死了。自從暗嫩玷辱了押沙龍的妹妹她瑪那日，押沙龍已經決定這事了。","notes":[]},{"n":33,"t":"現在，我主我王，不要把這事放在心上，以為王所有的兒子都死了。其實，只有暗嫩一人死了。」","notes":[]},{"n":34,"t":"押沙龍逃跑了。守望的年輕人舉目觀看，看哪，有許多人從何羅念山坡的路上來。","notes":["「何羅念」是參照七十士譯本；原文是「他後面」；「何羅念」在此指「上伯‧和崙」和「下伯‧和崙」。"]},{"n":35,"t":"約拿達對王說：「看哪，王的兒子都來了，正如你僕人所說的，事情就這樣發生了。」","notes":[]},{"n":36,"t":"話剛說完，看哪，王的兒子都到了，放聲大哭。王和他的眾臣僕也都號咷痛哭。","notes":[]},{"n":37,"t":"押沙龍逃到亞米忽的兒子基述王達買那裏去了。大衛天天為他兒子悲哀。","notes":[]},{"n":38,"t":"押沙龍逃到基述去了，在那裏住了三年。","notes":[]},{"n":39,"t":"王想要出去對付押沙龍的心化解了，因為王對暗嫩之死這事已經得了安慰。","notes":["「王想要...化解了」是根據一些古卷、死海古卷和七十士譯本；原文是「大衛王停止出去對付押沙龍」。"]}]},"14":{"heading":"約押設計讓押沙龍返回","verses":[{"n":1,"t":"洗魯雅的兒子約押知道王心裏想念押沙龍。","notes":[]},{"n":2,"t":"他派人往提哥亞去，從那裏叫了一個有智慧的婦人來，對她說：「請你裝作居喪的人，穿上喪服，不用膏抹身，裝作為死者悲哀多日的婦人。","notes":[]},{"n":3,"t":"你到王那裏，對王如此如此說。」於是約押把當說的話放在她口中。","notes":[]},{"n":4,"t":"提哥亞婦人到王面前，臉伏於地叩拜，說：「王啊，求你拯救！」","notes":["「到王面前」：有古卷是「奏告王」。"]},{"n":5,"t":"王對她說：「你有甚麼事呢？」她說：「我實在是個寡婦，我丈夫死了。","notes":[]},{"n":6,"t":"婢女有兩個兒子，二人在田間打架，沒有人從中勸解，一個擊殺另一個，把他打死了。","notes":[]},{"n":7,"t":"看哪，全家族都起來攻擊婢女，說：『把那打死兄弟的交出來，我們好處死他，為他所打死的兄弟償命，滅絕那承受家業的。』這樣，他們要把我剩下的炭火滅盡，不給我丈夫留名或留後在地面上。」","notes":[]},{"n":8,"t":"王對婦人說：「你回家去吧！我必為你下個命令。」","notes":[]},{"n":9,"t":"提哥亞婦人又對王說：「我主我王，願這罪孽歸我和我的父家，與王和王的位無關。」","notes":[]},{"n":10,"t":"王說：「有人說話難為你，你就帶他到我這裏來，他必不再攪擾你。」","notes":[]},{"n":11,"t":"婦人說：「願王對耶和華－你的神發誓，不許報血仇的人施行毀滅，免得他們滅絕我的兒子。」王說：「我指著永生的耶和華起誓：你的兒子連一根頭髮也不致落在地上。」","notes":[]},{"n":12,"t":"婦人說：「求我主我王容許婢女再說一句話。」王說：「你說吧！」","notes":[]},{"n":13,"t":"婦人說：「王為何起意做這事，要害神的百姓呢？王不使那逃亡的人回來，王說這話就證實自己錯了！","notes":[]},{"n":14,"t":"我們都必死，如同水潑在地上，不能收回。神不會讓人不死，但仍設法使逃亡的人不致成為趕出、回不來的人。","notes":["「但仍設法」：七十士譯本是「願王設法」。"]},{"n":15,"t":"現在我來將這話告訴我主我王，是因百姓使我懼怕。婢女想：『不如告訴王，或者王會成就使女所求的。","notes":[]},{"n":16,"t":"人要把我和我兒子從神的地業上一同除滅，王必應允救使女脫離他的手。』","notes":[]},{"n":17,"t":"婢女想：『我主我王的話必安慰我』；因為我主我王能辨別是非，如同神的使者一樣。惟願耶和華－你的神與你同在！」","notes":[]},{"n":18,"t":"王回答婦人說：「我問你一句話，你一點也不可瞞我。」婦人說：「我主我王，請說。」","notes":[]},{"n":19,"t":"王說：「這一切莫非是約押的手指使你的嗎？」婦人回答說：「我敢在我主我王面前起誓：我主我王所說的一切不偏左右，這是王的僕人約押吩咐我的，這一切話是他放在婢女口中的。","notes":[]},{"n":20,"t":"王的僕人約押做這事，為要扭轉局面。我主的智慧卻如神使者的智慧，能知地上一切的事。」","notes":[]},{"n":21,"t":"王對約押說：「看哪，我應允這事。你去，把那年輕人押沙龍帶回來。」","notes":[]},{"n":22,"t":"約押臉伏於地叩拜，為王祝福，說：「王既應允僕人這件事，僕人今日知道在我主我王眼前蒙恩寵了。」","notes":[]},{"n":23,"t":"於是約押起身往基述去，把押沙龍帶回耶路撒冷。","notes":[]},{"n":24,"t":"王說：「讓他回自己的家去，不要來見我的面。」押沙龍就回自己的家去，沒有見王的面。","notes":[]},{"n":25,"t":"全以色列中，無人像押沙龍那樣俊美，得人稱讚，從腳底到頭頂毫無瑕疵。","notes":[],"heads":["大衛饒恕押沙龍"]},{"n":26,"t":"他的頭髮很重，每到年底剪髮一次，所剪下來的，按王的秤稱一稱，重二百舍客勒。","notes":[]},{"n":27,"t":"押沙龍生了三個兒子，一個女兒。女兒名叫她瑪，是個容貌美麗的女子。","notes":[]},{"n":28,"t":"押沙龍住在耶路撒冷，足足有二年沒有見王的面。","notes":[]},{"n":29,"t":"押沙龍派人去叫約押來，要託他到王那裏去，約押卻不肯來。押沙龍第二次派人去叫他，他仍不肯來。","notes":[]},{"n":30,"t":"於是押沙龍對僕人說：「你們看，約押有一塊田靠近我的田，其中有大麥，你們去放火把它燒了。」押沙龍的僕人就去放火燒了那田。","notes":["七十士譯本在此加：「約押的僕人來到約押那裏，衣服撕裂，說：『押沙龍的僕人放火燒了你的田。』」"]},{"n":31,"t":"於是約押起來，到了押沙龍家裏，對他說：「你的僕人為何放火燒我的田呢？」","notes":[]},{"n":32,"t":"押沙龍對約押說：「看哪，我派人去請你來，好託你到王那裏去，說：『我為何從基述回來呢？我仍在那裏比較好。』現在讓我去見王的面；我若有罪孽，就任憑王殺了我吧。」","notes":[]},{"n":33,"t":"於是約押到王那裏，奏告王，王就叫押沙龍來。押沙龍到王那裏，在王面前臉伏於地，王就親吻押沙龍。","notes":[]}]},"15":{"heading":"押沙龍陰謀造反","verses":[{"n":1,"t":"此後，押沙龍為自己預備車馬，又派五十人在他前頭奔跑。","notes":[]},{"n":2,"t":"押沙龍常常早晨起來，站在城門的路旁，任何人有爭訟要去求王判決，押沙龍就叫他過來，說：「你是哪一城的人？」他說：「僕人是以色列某支派的人。」","notes":[]},{"n":3,"t":"押沙龍就對他說：「看，你的案件合情合理，無奈王沒有委派人聽你申訴。」","notes":[]},{"n":4,"t":"押沙龍又說：「恨不得我作這地的審判官！凡有爭訟的人可以到我這裏來，我必秉公判斷。」","notes":["「恨不得...審判官！」原文直譯「誰能立我作這地的審判官呢？」"]},{"n":5,"t":"若有人近前來要拜押沙龍，押沙龍就伸手拉住他，親吻他。","notes":[]},{"n":6,"t":"以色列中，凡到王那裏求判決的，押沙龍都這麼做。這樣，押沙龍暗中贏得了以色列人的心。","notes":[]},{"n":7,"t":"過了四年，押沙龍對王說：「求你准我往希伯崙去，還我向耶和華所許的願。","notes":["「四年」是根據一些抄本和古譯本；原文是「四十年」；有古卷是「四十天」。"]},{"n":8,"t":"因為僕人住在亞蘭的基述時，曾許願說：『耶和華若使我再回耶路撒冷，我必事奉他。』」","notes":["「我必事奉他」：七十士譯本的一些抄本是「我必在希伯崙事奉他」。"]},{"n":9,"t":"王對他說：「你平安地去吧！」押沙龍就動身，往希伯崙去了。","notes":[]},{"n":10,"t":"押沙龍派密使走遍以色列各支派，說：「你們一聽見角聲就說：『押沙龍在希伯崙作王了！』」","notes":[]},{"n":11,"t":"押沙龍在耶路撒冷請了二百人與他同去，都是誠心誠意去的，一點也不知道實情。","notes":[]},{"n":12,"t":"押沙龍獻祭的時候，派人去把大衛的謀士，基羅人亞希多弗從他本城基羅請來。於是叛亂越發強大，因為隨從押沙龍的百姓日漸增多。","notes":["「派人...請來」是根據七十士譯本和死海古卷；原文是「委派大衛的謀士，來自基羅城的基羅人亞希多弗」。"]},{"n":13,"t":"報信的人來到大衛那裏，說：「以色列人的心都歸向押沙龍了！」","notes":[],"heads":["大衛逃離耶路撒冷"]},{"n":14,"t":"大衛就對耶路撒冷所有跟隨他的臣僕說：「起來，我們逃吧！否則，我們來不及逃避押沙龍。要快點離開，免得他很快追上我們，加害於我們，用刀擊殺城裏的人。」","notes":[]},{"n":15,"t":"王的臣僕對王說：「我主我王所決定的一切，看哪，僕人都願遵行。」","notes":[]},{"n":16,"t":"於是王出去了，他的全家都跟隨他，但留下十個妃嬪看守宮殿。","notes":[]},{"n":17,"t":"王出去，眾百姓都跟隨他；到了最後一座屋子，他們就停下來。","notes":["「最後一座屋子」或譯「伯‧墨哈」。"]},{"n":18,"t":"王的眾臣僕都在他旁邊過去。基利提人、比利提人，和從迦特跟隨王來的六百個迦特人，也都在王面前過去。","notes":[]},{"n":19,"t":"王對迦特人以太說：「你是外邦人，從你本地逃來的，為甚麼與我們同去呢？你回去留在新王那裏吧！","notes":[]},{"n":20,"t":"你昨天才到，我今日怎好叫你與我們一同流亡，而我卻要到處飄流呢？回去吧，你帶你的弟兄回去吧！願主用慈愛信實待你。」","notes":["「你帶你的弟兄...待你」是根據七十士譯本；原文是「你用慈愛和誠實帶你的弟兄回去吧」。"]},{"n":21,"t":"以太回答王說：「我指著永生的耶和華起誓，又敢在王面前起誓：無論生死，王在哪裏，你的僕人也必在哪裏。」","notes":[]},{"n":22,"t":"大衛對以太說：「去，過去吧！」於是迦特人以太帶著所有跟隨他的人和孩子過去了。","notes":[]},{"n":23,"t":"眾百姓過去時，當地的人全都放聲大哭。王過了汲淪溪，眾百姓就往曠野的路上去了。","notes":[]},{"n":24,"t":"看哪，撒督和所有抬神約櫃的利未人也一同來了。他們將神的約櫃放下，亞比亞他上來，直到眾百姓從城裏出來走過去為止。","notes":["「放下...上來」：原文另譯「放在亞比亞他的旁邊」。"]},{"n":25,"t":"王對撒督說：「你將神的約櫃請回城去。我若在耶和華眼前蒙恩，他必使我回來，再見到約櫃和他的居所。","notes":[]},{"n":26,"t":"倘若他說：『我不喜愛你』；我在這裏，就照他眼中看為好的待我！」","notes":[]},{"n":27,"t":"王對撒督祭司說：「你不是先見嗎？你可以平安地回城，你兒子亞希瑪斯和亞比亞他的兒子約拿單，你們二人的兒子可以與你們同去。","notes":[]},{"n":28,"t":"看，我在曠野的渡口那裏等，直到你們來報信給我。」","notes":[]},{"n":29,"t":"於是撒督和亞比亞他將神的約櫃請回耶路撒冷，他們就留在那裏。","notes":[]},{"n":30,"t":"大衛蒙頭赤腳走上橄欖山的斜坡，一面上一面哭。所有跟隨他的百姓也都各自蒙頭哭著上去；","notes":[]},{"n":31,"t":"有人告訴大衛說：「亞希多弗也在叛黨之中，隨從押沙龍。」大衛說：「耶和華啊，求你使亞希多弗的計謀變為愚拙！」","notes":["「有人告訴大衛說」是根據七十士譯本和死海古卷；原文是「大衛說」。"]},{"n":32,"t":"大衛到了山頂，敬拜神的地方，看哪，亞基人戶篩衣服撕裂，頭蒙灰塵來迎見他。","notes":[]},{"n":33,"t":"大衛對他說：「你若與我一同過去，必拖累我；","notes":[]},{"n":34,"t":"你若回城去，對押沙龍說：『王啊，我願作你的僕人。我向來作你父親的僕人，現在我也願意作你的僕人。』你就可以為我破壞亞希多弗的計謀。","notes":[]},{"n":35,"t":"撒督和亞比亞他二位祭司豈不都在你那裏嗎？你在王宮裏聽見甚麼，就要告訴撒督和亞比亞他二位祭司。","notes":[]},{"n":36,"t":"看哪，撒督的兒子亞希瑪斯，亞比亞他的兒子約拿單，也跟二位祭司在那裏。凡你們所聽見的事，可以託這二人來向我報告。」","notes":[]},{"n":37,"t":"於是，大衛的朋友戶篩進了城，押沙龍也進了耶路撒冷。","notes":[]}]},"16":{"heading":"大衛和洗巴","verses":[{"n":1,"t":"大衛剛過山頂，看哪，米非波設的僕人洗巴拉著裝好鞍子的兩匹驢，驢上馱著二百個麵餅，一百個葡萄餅，一百個夏天的果餅，一皮袋酒來迎接他。","notes":[]},{"n":2,"t":"王對洗巴說：「你的這些東西是甚麼意思呢？」洗巴說：「驢是給王的家眷騎的，麵餅和夏天的果餅是給年輕人吃的，酒是給在曠野疲乏的人喝的。」","notes":[]},{"n":3,"t":"王說：「你主人的兒子在哪裏呢？」洗巴對王說：「看哪，他留在耶路撒冷，因他說：『以色列家今日必將我父的國歸還我。』」","notes":[]},{"n":4,"t":"王對洗巴說：「看哪，凡屬米非波設的都是你的了。」洗巴說：「我叩拜我主我王，願我在你眼前蒙恩寵。」","notes":[]},{"n":5,"t":"大衛王到了巴戶琳，看哪，有一個人從那裏出來，是掃羅家族中基拉的兒子，名叫示每。他一面走一面咒罵，","notes":[],"heads":["大衛和示每"]},{"n":6,"t":"又向大衛王和王的眾臣僕扔石頭；眾百姓和勇士都在王的左右。","notes":[]},{"n":7,"t":"示每這樣咒罵說：「你這好流人血的，你這無賴，滾吧！滾吧！","notes":[]},{"n":8,"t":"你流了掃羅全家的血，接續他作王，耶和華把這罪歸在你身上。耶和華將這國交在你兒子押沙龍的手中。看哪，你咎由自取，因為你是好流人血的人。」","notes":[]},{"n":9,"t":"洗魯雅的兒子亞比篩對王說：「這死狗為何咒罵我主我王呢？讓我過去，割下他的頭來。」","notes":[]},{"n":10,"t":"王說：「洗魯雅的兒子，我與你們有何相干呢？他這樣咒罵是因耶和華吩咐他：『你要咒罵大衛。』如此，誰敢說：『你為甚麼這樣做呢？』」","notes":[]},{"n":11,"t":"大衛又對亞比篩和眾臣僕說：「看哪，我親生的兒子尚且尋索我的性命，何況現在這便雅憫人呢？由他咒罵吧！因為這是耶和華吩咐他的。","notes":[]},{"n":12,"t":"或者耶和華見我遭難，因我今日被這人咒罵而向我施恩。」","notes":["「我遭難」是根據一些古卷、七十士譯本和其他古譯本；原文是「我的眼睛」或「我的罪孽」。"]},{"n":13,"t":"於是大衛和他的人在路上走。示每走在大衛對面的山坡，一面走一面咒罵，又向他扔石頭，揚起塵土。","notes":[]},{"n":14,"t":"王和跟隨他的眾百姓來了，非常疲乏，就在那裏歇息。","notes":[]},{"n":15,"t":"押沙龍和以色列眾百姓來到耶路撒冷，亞希多弗也與他同來。","notes":[],"heads":["押沙龍在耶路撒冷"]},{"n":16,"t":"大衛的朋友亞基人戶篩來到押沙龍那裏，對他說：「願王萬歲！願王萬歲！」","notes":[]},{"n":17,"t":"押沙龍對戶篩說：「你這樣做是忠誠對待你的朋友嗎？為甚麼不與你的朋友同去呢？」","notes":[]},{"n":18,"t":"戶篩對押沙龍說：「不，誰是耶和華和這百姓，以及以色列眾人所揀選的，我必歸順他，留在他那裏。","notes":[]},{"n":19,"t":"再者，我當服事誰呢？豈不是前王的兒子嗎？我怎樣服事你父親，也必照樣服事你。」","notes":[]},{"n":20,"t":"押沙龍對亞希多弗說：「你們出個主意，我們該怎麼做？」","notes":[]},{"n":21,"t":"亞希多弗對押沙龍說：「你父親所留下看守宮殿的妃嬪，你可以與她們親近。以色列眾人聽見你敢惹你父親憎惡你，凡歸順你人的手就更堅強了。」","notes":[]},{"n":22,"t":"於是他們為押沙龍在屋頂上支搭帳棚，押沙龍就在以色列眾人眼前，與他父親的妃嬪親近。","notes":[]},{"n":23,"t":"那時亞希多弗所出的主意好像人從神求問得來的話一樣；他給大衛，給押沙龍所出的一切主意，都是這樣。","notes":[]}]},"17":{"heading":"戶篩破壞亞希多弗的計謀","verses":[{"n":1,"t":"亞希多弗對押沙龍說：「請讓我挑選一萬二千人，今夜起身追趕大衛。","notes":[]},{"n":2,"t":"我必趁他疲乏手軟的時候追上他，使他驚惶。跟隨他的眾百姓必都逃跑，我就只殺王一個人。","notes":[]},{"n":3,"t":"我必使眾百姓都歸順你，正如眾人歸順你所追殺的人一樣，眾百姓就都平安無事了。」","notes":["「正如...一樣」：七十士譯本是「如同新娘歸回丈夫一樣，你單追殺一人」。"]},{"n":4,"t":"這話在押沙龍和以色列眾長老的眼中都看為好。","notes":[]},{"n":5,"t":"押沙龍說：「把亞基人戶篩也召來，我們也要聽他怎麼說。」","notes":[]},{"n":6,"t":"戶篩到了押沙龍那裏，押沙龍向他說：「亞希多弗說了這樣的話，我們要照他的話做嗎？若不可，你就說吧！」","notes":[]},{"n":7,"t":"戶篩對押沙龍說：「亞希多弗這次所出的主意不好。」","notes":[]},{"n":8,"t":"戶篩又說：「你知道，你父親和他的人都是勇士，他們心裏惱怒，如同田野中失去小熊的母熊一樣；而且你父親是個戰士，必不和百姓一同住宿。","notes":[]},{"n":9,"t":"看哪，他現今或藏在一個坑中或在別處，若我們有人首先被殺，聽見的必說：『跟隨押沙龍的百姓被殺了。』","notes":["「我們」是根據七十士譯本的一些抄本；原文是「他們」。"]},{"n":10,"t":"雖有勇士膽大如獅子，他的心也必定融化，因為全以色列都知道你父親是英雄，跟隨他的人都是勇士。","notes":[]},{"n":11,"t":"依我之計，要把如同海邊的沙那樣多的以色列眾人，從但直到別是巴，聚集到你這裏來，由你親自率領他們出戰。","notes":[]},{"n":12,"t":"我們到他那裏，在任何地方遇見他，就突然臨到他，如同露水滴在泥土上。這樣，他和所有跟隨他的人，一個也不留。","notes":[]},{"n":13,"t":"他若撤退到一座城，以色列眾人必帶繩子去那城，把城拉到河裏，甚至連一塊小石子也找不到。」","notes":[]},{"n":14,"t":"押沙龍和以色列眾人都說：「亞基人戶篩的計謀比亞希多弗的更好！」這是因為耶和華定意破壞亞希多弗的良謀，為的是耶和華要降禍給押沙龍。","notes":[]},{"n":15,"t":"戶篩對撒督和亞比亞他二位祭司說：「亞希多弗為押沙龍和以色列的長老出的主意是如此如此，我出的主意是如此如此。","notes":[],"heads":["大衛獲警告而逃脫"]},{"n":16,"t":"現在你們要急速派人去告訴大衛說：『今夜不可在曠野的渡口住宿，務要過河，免得王和所有跟隨他的百姓都被吞滅。』」","notes":[]},{"n":17,"t":"約拿單和亞希瑪斯在隱‧羅結等候，不敢進城，恐怕被人看見。有一個婢女出來，把這話告訴他們，他們就去報信給大衛王。","notes":[]},{"n":18,"t":"然而有一個僮僕看見他們，就去告訴押沙龍。他們二人急忙離開，跑到巴戶琳一個人的家裏。那人院中有一口井，他們就下到那裏。","notes":[]},{"n":19,"t":"那家的婦人用蓋蓋上井口，又在上頭鋪上碎麥，事情就沒有洩漏。","notes":[]},{"n":20,"t":"押沙龍的僕人來到婦人的家，說：「亞希瑪斯和約拿單在哪裏？」婦人對他們說：「他們過了河了。」僕人搜尋，卻找不著，就回耶路撒冷去了。","notes":[]},{"n":21,"t":"他們走後，二人從井裏上來，去告訴大衛王。他們對大衛說：「亞希多弗出這樣的主意要害你，你們起來，快快過河。」","notes":[]},{"n":22,"t":"於是大衛和所有跟隨他的百姓都起來，過約旦河。到了天亮，無一人不過約旦河的。","notes":[]},{"n":23,"t":"亞希多弗見他的計謀不被接納，就備上驢，動身歸回本城，到了自己的家。他留下遺囑給他的家，就上吊死了，葬在他父親的墳墓裏。","notes":[]},{"n":24,"t":"大衛到了瑪哈念，押沙龍和跟隨他的以色列眾人也都過了約旦河。","notes":[]},{"n":25,"t":"押沙龍立亞瑪撒作元帥，取代約押。亞瑪撒是以實瑪利人以特拉的兒子。以特拉曾與拿轄的女兒亞比該親近；這亞比該與約押的母親洗魯雅是姊妹。","notes":["「以實瑪利人」是根據七十士譯本的一些抄本﹔原文是「以色列人」﹔參代上2．17。","「拿轄」：七十士譯本是「耶西」；參代上2．16。"]},{"n":26,"t":"押沙龍和以色列人安營在基列地。","notes":[]},{"n":27,"t":"大衛到了瑪哈念，亞捫族的拉巴人拿轄的兒子朔比，羅‧底巴人亞米利的兒子瑪吉，來自羅基琳的基列人巴西萊，","notes":[]},{"n":28,"t":"帶著被褥、盆、瓦器，還有小麥、大麥、麥麵、烤熟的穀穗、豆子、紅豆、炒豆、","notes":[]},{"n":29,"t":"蜂蜜、奶油、綿羊、奶餅，供給大衛和跟隨他的人吃，因為他們想：「百姓在曠野中，必定又飢渴又疲乏。」","notes":[]}]},"18":{"heading":"押沙龍敗亡","verses":[{"n":1,"t":"大衛數點跟隨他的百姓，立千夫長、百夫長率領他們。","notes":[]},{"n":2,"t":"大衛把軍兵分為三隊：三分之一在約押手下，三分之一在洗魯雅的兒子約押弟弟亞比篩手下，三分之一在迦特人以太手下。王對軍兵說：「我必與你們一同出戰。」","notes":["「把軍兵分為三隊」是根據七十士譯本的一些抄本；原文是「派遣軍兵」。"]},{"n":3,"t":"軍兵卻說：「你不可出戰。若是我們逃跑，敵人不會把心放在我們身上；我們陣亡一半，敵人也不會把心放在我們身上。但現在你一人抵過我們萬人，所以你最好留在城裏支援我們。」","notes":[]},{"n":4,"t":"王對他們說：「你們看怎樣好，我就怎樣做。」於是王站在城門旁，所有的軍兵成百成千地挨次出戰去了。","notes":[]},{"n":5,"t":"王囑咐約押、亞比篩、以太說：「你們要為我的緣故寬待那年輕人押沙龍。」王為押沙龍的事囑咐眾將領的話，所有的軍兵都聽見了。","notes":[]},{"n":6,"t":"軍兵出到田野迎戰以色列，在以法蓮的樹林裏交戰。","notes":[]},{"n":7,"t":"在那裏，以色列百姓敗在大衛的臣僕面前。那日在那裏陣亡的很多，共有二萬人。","notes":[]},{"n":8,"t":"戰爭蔓延到整個地面，那日被樹林吞噬的軍兵比被刀劍吞噬的更多。","notes":[]},{"n":9,"t":"押沙龍剛好遇見了大衛的臣僕。押沙龍騎著騾子，從大橡樹密枝底下經過，他的頭被橡樹夾住，懸掛在空中，所騎的騾子就離他去了。","notes":["「空中」：原文直譯「天和地之間」。"]},{"n":10,"t":"有個人看見，就告訴約押說：「看哪，我看見押沙龍掛在橡樹上了。」","notes":[]},{"n":11,"t":"約押對報信的人說：「看哪，你既看見了，為甚麼不當場把他擊殺在地呢？我必賞你十個銀子和一條帶子。」","notes":[]},{"n":12,"t":"那人對約押說：「即使我手裏得了一千銀子，也不敢伸手害王的兒子，因為我們聽見王囑咐你、亞比篩、以太說：『你們要謹慎，不可害那年輕人押沙龍。』","notes":[]},{"n":13,"t":"我若冒著生命危險做這傻事，無論何事都瞞不過王，你自己也必遠遠站在一旁。」","notes":["「我若...這傻事」：原文另譯「我若妄為害了他的性命」。"]},{"n":14,"t":"約押說：「我不能在你面前這樣耗下去！」約押手拿三枝短槍，趁押沙龍在橡樹上還活著，就刺透他的心。","notes":["「在橡樹上」：原文直譯「在橡樹的心」。"]},{"n":15,"t":"給約押拿兵器的十個青年圍著押沙龍，擊殺他，將他殺死。","notes":[]},{"n":16,"t":"約押吹角，軍兵就回來，不去追趕以色列人，因為約押制止了軍兵。","notes":[]},{"n":17,"t":"他們拿下押沙龍，把他丟在樹林中一個大坑裏，上頭堆起一大堆石頭。以色列眾人都逃跑，各回自己的帳棚去了。","notes":[]},{"n":18,"t":"押沙龍活著的時候，曾在王谷立了一根柱子，因他說：「我沒有兒子為我留名。」他就以自己的名字稱那柱子為押沙龍碑，直到今日。","notes":[]},{"n":19,"t":"撒督的兒子亞希瑪斯說：「讓我跑去報信給王，耶和華已經為王伸冤，使他脫離仇敵的手了。」","notes":[],"heads":["大衛聽聞押沙龍死訊"]},{"n":20,"t":"約押對他說：「你今日不可作報信的人，改日再去報信；因為今日王的兒子死了，所以你不可去報信。」","notes":[]},{"n":21,"t":"約押對古實人說：「你去把你所看見的告訴王。」古實人向約押叩拜後，就跑去了。","notes":[]},{"n":22,"t":"撒督的兒子亞希瑪斯又對約押說：「無論怎樣，讓我隨著古實人跑去吧！」約押說：「我兒，你報這信息，既不得賞賜，何必要跑去呢？」","notes":[]},{"n":23,"t":"他說：「無論怎樣，我要跑去。」約押對他說：「你跑去吧！」亞希瑪斯就從平原的路往前跑，越過了古實人。","notes":[]},{"n":24,"t":"大衛正坐在內外城門之間。守望的人上到城牆，在城門的頂上舉目觀看，看哪，有一個人獨自跑來。","notes":[]},{"n":25,"t":"守望的人就大聲告訴王。王說：「他若獨自來，必是報口信的。」那人跑得越來越近了。","notes":[]},{"n":26,"t":"守望的人又見一人跑來，就對守城門的人喊說：「看哪，又有一人獨自跑來。」王說：「這也是報信的。」","notes":[]},{"n":27,"t":"守望的人說：「我看前面那人的跑法，好像撒督的兒子亞希瑪斯的跑法。」王說：「他是個好人，是來報好消息的。」","notes":[]},{"n":28,"t":"亞希瑪斯向王呼叫說：「平安了！」他就臉伏於地向王叩拜，說：「耶和華－你的神是應當稱頌的，他已把那些舉手攻擊我主我王的人交出來了。」","notes":[]},{"n":29,"t":"王說：「年輕人押沙龍平安嗎？」亞希瑪斯說：「約押派王的僕人，就是你的僕人時，我看見一陣大騷動，卻不知道是甚麼事。」","notes":[]},{"n":30,"t":"王說：「你退去，站在這裏。」他就退去，站著。","notes":[]},{"n":31,"t":"看哪，古實人也來到，說：「有信息報給我主我王！耶和華今日為你伸冤，使你脫離一切起來攻擊你之人的手。」","notes":[]},{"n":32,"t":"王對古實人說：「年輕人押沙龍平安嗎？」古實人說：「願我主我王的仇敵，和一切起來惡意要害你的人，都像那年輕人一樣。」","notes":[]},{"n":33,"t":"王戰抖，就上城門的樓房去痛哭，一面走一面說：「我兒押沙龍啊！我兒，我兒押沙龍啊！我恨不得替你死，押沙龍啊，我兒！我兒！」","notes":[]}]},"19":{"heading":"約押勸諫王","verses":[{"n":1,"t":"有人告訴約押：「看哪，王為押沙龍悲哀哭泣。」","notes":[]},{"n":2,"t":"那日眾軍兵聽說王為他兒子悲傷，他們得勝的日子變成悲哀了。","notes":[]},{"n":3,"t":"那日軍兵暗暗地進城，如同戰場上逃跑、羞愧的士兵一般。","notes":[]},{"n":4,"t":"王蒙著臉，大聲哭號說：「我兒押沙龍啊！押沙龍，我兒，我兒啊！」","notes":[]},{"n":5,"t":"約押進了宮到王那裏，說：「你今日使你眾臣僕的臉面羞愧了！他們今日救了你的性命和你兒女妻妾的性命，","notes":[]},{"n":6,"t":"你卻愛那些恨你的人，恨那些愛你的人。今日你擺明了不以將帥、臣僕為念。我今日看得出，若押沙龍活著，我們今日全都死了，你就高興了。","notes":[]},{"n":7,"t":"現在你要起來，出去安慰你臣僕的心。我指著耶和華起誓：你若不出去，今夜必沒有一人跟你在一起了。這禍患比你從幼年到如今所遭受的更嚴重！」","notes":[]},{"n":8,"t":"於是王起來，坐在城門口。有人告訴眾軍兵說：「看哪，王坐在城門口。」眾軍兵就都到王的面前。那時，以色列人已經逃跑，各回自己的帳棚去了。","notes":[]},{"n":9,"t":"以色列眾支派的百姓都議論紛紛，說：「王曾救我們脫離仇敵的手，又救我們脫離非利士人的手，現在他為了押沙龍逃離這地了。","notes":[]},{"n":10,"t":"我們所膏治理我們的押沙龍已經陣亡。現在你們為甚麼沉默，不請王回來呢？」","notes":[]},{"n":11,"t":"大衛王派人到撒督和亞比亞他二位祭司那裏，說：「你們當向猶大長老說：『以色列眾人已經有話到了王那裏，你們為甚麼最後才請王回宮呢？","notes":["「到了王那裏」是根據七十士譯本；原文是「到了王那裏，到了宮裏」。"]},{"n":12,"t":"你們是我的弟兄，是我的骨肉，為甚麼最後才請王回來呢？』","notes":[]},{"n":13,"t":"你們要對亞瑪撒說：『你不是我的骨肉嗎？我若不立你在我面前取代約押永久作元帥，願神重重懲罰我！』」","notes":[]},{"n":14,"t":"這樣，他挽回了猶大眾人的心，如同一人。他們就派人到王那裏，說：「請王和王的眾臣僕回來。」","notes":[]},{"n":15,"t":"王回來了，到約旦河。猶大人來到吉甲，去迎接王，請王過約旦河。","notes":[]},{"n":16,"t":"來自巴戶琳的便雅憫人基拉的兒子示每急忙與猶大人一同下去迎接大衛王。","notes":[]},{"n":17,"t":"跟從示每的有一千個便雅憫人，還有掃羅家的僕人洗巴和他十五個兒子、二十個隨從僕人，他們都趕緊過約旦河到王的面前。","notes":[]},{"n":18,"t":"渡船就渡王的家眷過河，照王看為好的去做。王過約旦河的時候，基拉的兒子示每俯伏在王面前，","notes":["「渡船...過河」：七十士譯本是「他們過到渡口，把王的家眷渡過河」。"]},{"n":19,"t":"對王說：「我主我王離開耶路撒冷的那日，僕人行了悖逆的事，現在求我主不要因此加罪於僕人，不要記得，也不要放在心上。","notes":[]},{"n":20,"t":"僕人明知自己有罪，看哪，約瑟全家之中，今日我首先下來迎接我主我王。」","notes":[]},{"n":21,"t":"洗魯雅的兒子亞比篩回答說：「示每既然咒罵耶和華的受膏者，不應當為這緣故處死他嗎？」","notes":[]},{"n":22,"t":"大衛說：「洗魯雅的兒子，我與你們有何相干，你們今日要跟我作對嗎？今日在以色列中豈可把任何人處死呢？我豈不知今日我是以色列的王嗎？」","notes":[]},{"n":23,"t":"於是王對示每說：「你必不死。」王就向他起誓。","notes":[]},{"n":24,"t":"掃羅的孫子米非波設也下去迎接王。他自從王離開的那一日，直到王平安回耶路撒冷的日子，沒有修腳，沒有剃鬍鬚，也沒有洗衣服。","notes":[],"heads":["大衛善待米非波設"]},{"n":25,"t":"他來迎接王的時候，王對他說：「米非波設，你為甚麼沒有與我同去呢？」","notes":["「直到王平安回耶路撒冷的日子...迎接王的時候」：原文是「直到王平安回來的日子，沒有修腳，沒有剃鬍鬚，也沒有洗衣服。他來到耶路撒冷迎接王的時候」。"]},{"n":26,"t":"他說：「我主我王啊，我的僕人欺騙了我。那日僕人想要備驢騎上，與王同去，因為僕人是瘸腿的。","notes":[]},{"n":27,"t":"他卻在我主我王面前毀謗僕人。然而我主我王如同神的使者一樣，你看怎樣好，就怎樣做吧！","notes":[]},{"n":28,"t":"因為我祖全家的人，在我主我王面前不過是該死的人，王卻使僕人列在王的席上吃飯的人當中，我現在還有甚麼權利能向王請求呢？」","notes":[]},{"n":29,"t":"王對他說：「你何必再提你的事呢？我說，你與洗巴要平分土地。」","notes":[]},{"n":30,"t":"米非波設對王說：「我主我王既然平安地回宮，甚至讓洗巴全都拿去也沒關係。」","notes":[]},{"n":31,"t":"基列人巴西萊從羅基琳下來，要護送王過約旦河，就跟王一同過約旦河。","notes":[],"heads":["大衛善待巴西萊"]},{"n":32,"t":"巴西萊年紀老邁，已經八十歲了。王住在瑪哈念的時候，他拿食物來供給王，因他是個大富翁。","notes":[]},{"n":33,"t":"王對巴西萊說：「你與我一同渡過去，我要在耶路撒冷我的身邊奉養你。」","notes":[]},{"n":34,"t":"巴西萊對王說：「我還能活多少年日，可以與王一同上耶路撒冷呢？","notes":[]},{"n":35,"t":"今日我已八十歲了，還能辨別美醜嗎？僕人還能嘗出飲食的滋味嗎？還能聽男女歌唱的聲音嗎？僕人何必拖累我主我王呢？","notes":[]},{"n":36,"t":"僕人護送王過約旦河只是一件小事，王何必用這樣的賞賜來報答我呢？","notes":[]},{"n":37,"t":"請讓我回去，死在我本城，葬在我父母的墓旁。看哪，這裏有金罕作王的僕人，讓他同我主我王過去，你看怎樣好，就怎樣對待他吧。」","notes":[]},{"n":38,"t":"王說：「金罕可以與我一同過去，我必照你看為好的待他。你要我做的，我都會為你做。」","notes":[]},{"n":39,"t":"於是眾百姓過了約旦河，王也過去了。王親吻巴西萊，為他祝福，巴西萊就回自己的地方去了。","notes":[]},{"n":40,"t":"王渡過去，到了吉甲，金罕也跟他過去。猶大眾百姓和以色列百姓的一半也都送王過去。","notes":["「王渡過去」：七十士譯本是「王繼續前進」。"]},{"n":41,"t":"看哪，以色列眾人來到王那裏，對王說：「我們的弟兄猶大人為甚麼暗暗地送王和王的家眷，以及所有跟隨王的人，過約旦河呢？」","notes":[],"heads":["以色列人和猶大人為王起爭論"]},{"n":42,"t":"猶大眾人回答以色列人說：「因為王與我們是親屬，你們為何因這事發怒呢？我們靠王吃了甚麼呢？王真正給了我們甚麼賞賜呢？」","notes":[]},{"n":43,"t":"以色列人回答猶大人說：「我們與王有十倍的關係，就是在大衛身上，我們也比你們更有權利。你們為何藐視我們呢？我們不是最先提議請王回來的嗎？」但猶大人的話比以色列人的話更強硬。","notes":["「我們也比你們更有權利」：原文是「我也比你更有權利」；七十士譯本是「我也比你年長」。"]}]},"20":{"heading":"示巴反叛","verses":[{"n":1,"t":"在那裏恰巧有一個無賴，名叫示巴，是便雅憫人比基利的兒子。他吹角，說：「我們與大衛無份，與耶西的兒子無關。以色列啊，各回自己的帳棚去吧！」","notes":[]},{"n":2,"t":"於是以色列眾人都離棄大衛去跟隨比基利的兒子示巴，但猶大人從約旦河直到耶路撒冷，都緊緊跟隨他們的王。","notes":[]},{"n":3,"t":"大衛王來到耶路撒冷，進了宮，就把從前留下看守宮殿的十個妃嬪軟禁在冷宮，養活她們，卻不與她們親近。她們被關起來，活著如同寡婦，直到死的日子。","notes":[]},{"n":4,"t":"王對亞瑪撒說：「你要在三日之內召集猶大人到我這裏來，你自己也要留在這裏。」","notes":[]},{"n":5,"t":"亞瑪撒就去召集猶大人，不過他卻耽延，過了王所定的期限。","notes":[]},{"n":6,"t":"大衛對亞比篩說：「現在比基利的兒子示巴對我們的危害恐怕比押沙龍更大。你要帶領你主的一些僕人追趕他，免得他得了堅固的城鎮，在我們眼前逃脫。」","notes":["「在我們眼前逃脫」：原文另譯「帶給我們麻煩」。"]},{"n":7,"t":"約押的人和基利提人、比利提人，以及所有的勇士都跟著亞比篩，從耶路撒冷出去追趕比基利的兒子示巴。","notes":[]},{"n":8,"t":"他們到了基遍的大石頭那裏，亞瑪撒來迎接他們。那時約押穿著戰衣，腰束佩刀的帶子，刀在鞘內。約押前行時，刀從鞘內掉出來。","notes":[]},{"n":9,"t":"約押對亞瑪撒說：「我的弟兄，你平安嗎？」他就用右手抓住亞瑪撒的鬍子，要親吻他。","notes":[]},{"n":10,"t":"亞瑪撒沒有防備約押手裏拿著的刀；約押用刀刺入他的肚腹，他的腸子流在地上，約押沒有再刺，他就死了。約押和他弟弟亞比篩往前追趕比基利的兒子示巴。","notes":[]},{"n":11,"t":"有約押的一個僕人站在亞瑪撒屍體的旁邊，說：「誰喜愛約押，誰歸順大衛，就當跟隨約押。」","notes":[]},{"n":12,"t":"亞瑪撒渾身是血，躺在路中間。那人見眾百姓都站住，就把亞瑪撒的屍體從路上移到田間，把衣服蓋在他身上，因為他看見眾人經過時都站住。","notes":[]},{"n":13,"t":"屍體從路上移走之後，眾人就都跟隨約押去追趕比基利的兒子示巴。","notes":[]},{"n":14,"t":"示巴走遍以色列各支派，直到伯‧瑪迦的亞比拉；所有精選的人都聚集跟隨他。","notes":["「精選的人」：原文是「比利人」。"]},{"n":15,"t":"跟隨約押的眾百姓到了伯‧瑪迦的亞比拉，圍困示巴，對著城建土堆，與城郭相對。他們猛撞城牆，要使城倒塌。","notes":[]},{"n":16,"t":"一個有智慧的婦人從城上呼叫：「聽啊，聽啊，請你們告訴約押：『近前來到這裏，我好與你說話。』」","notes":[]},{"n":17,"t":"約押就近前到她那裏，婦人對他說：「你是約押嗎？」他說：「我是。」婦人對他說：「請你聽使女的話。」約押說：「我正在聽。」","notes":[]},{"n":18,"t":"婦人說：「古時有話說，當在亞比拉求問，事情就可以解決。","notes":[]},{"n":19,"t":"我在以色列中是和平、忠誠的。你現在想要毀壞這城，以色列的根源，為何你要吞滅耶和華的產業呢？」","notes":["「根源」：原文是「母親」。"]},{"n":20,"t":"約押回答說：「不，我絕不吞滅和毀壞！","notes":[]},{"n":21,"t":"話不是這麼說的，只是因為有一個以法蓮山區的人，就是比基利的兒子名叫示巴，他舉手攻擊大衛王；你們只要把他一人交出來，我就離城而去。」婦人對約押說：「看哪，他的首級必從城牆上丟給你。」","notes":[]},{"n":22,"t":"婦人憑她的智慧去勸眾百姓，他們就割下比基利的兒子示巴的首級，丟給約押。約押吹角，眾人就離城散開，各回自己的帳棚去了。約押回耶路撒冷，到王那裏。","notes":[]},{"n":23,"t":"約押統管以色列全軍；耶何耶大的兒子比拿雅統管基利提人和比利提人；","notes":[]},{"n":24,"t":"亞多蘭管理勞役的人；亞希律的兒子約沙法作史官；","notes":[]},{"n":25,"t":"示法作書記；撒督和亞比亞他作祭司；","notes":[]},{"n":26,"t":"睚珥人以拉也作大衛的祭司。","notes":[]}]},"21":{"heading":"掃羅的後代被處死","verses":[{"n":1,"t":"大衛在位年間有饑荒，一連三年，大衛求問耶和華，耶和華說：「掃羅和他家犯了流人血之罪，因為他殺死了基遍人。」","notes":[]},{"n":2,"t":"大衛王召了基遍人來，跟他們說話。基遍人不是以色列人，而是亞摩利人中所剩下的人。以色列人曾向他們起誓，掃羅卻為以色列人和猶大人大發熱心，追殺他們，為了要消滅他們。","notes":[]},{"n":3,"t":"大衛對基遍人說：「我當為你們做甚麼呢？要用甚麼贖這罪，使你們為耶和華的產業祝福呢？」","notes":[]},{"n":4,"t":"基遍人對他說：「我們和掃羅以及他家的事與金銀無關，也不要因我們的緣故殺任何以色列人。」大衛說：「你們怎樣說，我就為你們怎樣做。」","notes":[]},{"n":5,"t":"他們對王說：「那謀害我們、要消滅我們、使我們不得住以色列境內的人，","notes":[]},{"n":6,"t":"請把他的子孫七人交給我們，我們好在耶和華面前，把他們懸掛在基比亞，就是耶和華揀選掃羅的地方。」王說：「我必交給你們。」","notes":[]},{"n":7,"t":"王顧惜掃羅的孫子，約拿單的兒子米非波設，因為在大衛和掃羅的兒子約拿單之間，有指著耶和華的誓言。","notes":[]},{"n":8,"t":"王卻把愛亞的女兒利斯巴為掃羅所生的兩個兒子亞摩尼和米非波設，以及掃羅的女兒米拉為米何拉人巴西萊兒子亞得列所生的五個兒子","notes":["「米拉」是根據有些古卷和其他古譯本；原文是「米甲」。"]},{"n":9,"t":"交在基遍人的手裏。基遍人在耶和華面前把他們懸掛在山上，這七人就一起死了。他們被殺的時候正是收割的頭幾天，就是開始收割大麥的時候。","notes":[]},{"n":10,"t":"愛亞的女兒利斯巴用麻布舖在磐石上搭棚，從收割的開始直到天降雨在屍體上，她白日不許空中的飛鳥落在屍體上，夜間不讓田野的走獸前來。","notes":[]},{"n":11,"t":"有人把掃羅的妃子愛亞女兒利斯巴所做的事告訴大衛。","notes":[]},{"n":12,"t":"大衛就去，從基列的雅比人那裏把掃羅和他兒子約拿單的骸骨搬來。先前非利士人在基利波殺了掃羅，把屍體懸掛在伯‧珊的廣場上，後來基列的雅比人把屍體偷走。","notes":[]},{"n":13,"t":"大衛把掃羅和他兒子約拿單的骸骨從那裏搬上來，又收殮了被懸掛的那些人的骸骨。","notes":[]},{"n":14,"t":"他們將掃羅和他兒子約拿單的骸骨葬在便雅憫的洗拉，在掃羅父親基士的墳墓裏。他們遵照王所吩咐的一切做了。此後神垂聽了為那地的祈求。","notes":[]},{"n":15,"t":"非利士人與以色列人打仗。大衛帶領僕人下去，與非利士人交戰，大衛就疲乏了。","notes":[],"heads":["攻打非利士巨人"]},{"n":16,"t":"巨人族的後裔以實‧比諾說要殺大衛；他的銅槍重三百舍客勒，腰間又佩著新刀。","notes":["原文沒有「刀」。"]},{"n":17,"t":"但洗魯雅的兒子亞比篩幫助大衛攻擊非利士人，殺死了他。當日，大衛的人向大衛起誓說：「你不可再與我們一同出戰，免得以色列的燈熄滅了。」","notes":[]},{"n":18,"t":"後來，在歌伯又與非利士人打仗，那時戶沙人西比該殺了巨人族的後裔撒弗。","notes":[]},{"n":19,"t":"他們又在歌伯與非利士人打仗，伯利恆人雅雷的兒子伊勒哈難殺了迦特人歌利亞；這人的槍桿粗如織布機的軸。","notes":["「雅雷」：原文是「雅雷‧俄珥金」；原文另譯「睚珥」；參代上20．5。"]},{"n":20,"t":"又有一次，他們在迦特打仗。那裏有一個身材高大的人，雙手各有六根手指，雙腳各有六根腳趾，共有二十四根；他也是巨人族的後裔。","notes":[]},{"n":21,"t":"他向以色列罵陣，大衛的哥哥示米亞的兒子約拿單就殺了他。","notes":[]},{"n":22,"t":"這四個人是迦特巨人族的後裔，都仆倒在大衛和他僕人的手下。","notes":[]}]},"22":{"heading":"大衛的凱歌","verses":[{"n":1,"t":"當耶和華救大衛脫離所有仇敵和掃羅之手的日子，他用這詩的歌詞向耶和華說話。","notes":[]},{"n":2,"t":"他說：耶和華是我的巖石、我的山寨、我的救主、","notes":[]},{"n":3,"t":"我的神、我的磐石、我所投靠的。他是我的盾牌，是拯救我的角，是我的碉堡，是我的避難所，是我的救主，救我脫離兇暴的。","notes":[]},{"n":4,"t":"我要求告當讚美的耶和華，我必從仇敵手中被救出來。","notes":[]},{"n":5,"t":"死亡的波浪環繞我，毀滅的急流驚嚇我，","notes":[]},{"n":6,"t":"陰間的繩索纏繞我，死亡的圈套臨到我。","notes":[]},{"n":7,"t":"我在急難中求告耶和華，向我的神呼求。他從殿中聽了我的聲音；我的呼求進入他的耳中。","notes":[]},{"n":8,"t":"那時，因他發怒地就搖撼震動；天的根基也戰抖搖撼。","notes":[]},{"n":9,"t":"他的鼻孔冒煙上騰；他的口發火焚燒，連煤炭也燒著了。","notes":[]},{"n":10,"t":"他使天下垂，親自降臨；黑雲在他腳下。","notes":[]},{"n":11,"t":"他乘坐基路伯飛行，在風的翅膀上顯現。","notes":[]},{"n":12,"t":"他以黑暗和聚集的水、天空的密雲為四圍的行宮。","notes":[]},{"n":13,"t":"因他發出光輝，火炭都燒著了。","notes":[]},{"n":14,"t":"耶和華在天上打雷；至高者發出聲音。","notes":[]},{"n":15,"t":"他射出箭來，使仇敵四散；發出閃電，擊潰他們。","notes":[]},{"n":16,"t":"耶和華的斥責一發，鼻孔的氣一出，海底就顯現，大地的根基也暴露。","notes":[]},{"n":17,"t":"他從高天伸手抓住我，把我從大水中拉上來。","notes":[]},{"n":18,"t":"他救我脫離我的強敵，脫離那些恨我的人，因為他們比我強盛。","notes":[]},{"n":19,"t":"我遭遇災難的日子，他們來攻擊我；但耶和華是我的倚靠。","notes":[]},{"n":20,"t":"他領我到寬闊之處，他救拔我，因他喜愛我。","notes":[]},{"n":21,"t":"耶和華必按我的公義報答我，按我手中的清潔賞賜我。","notes":[]},{"n":22,"t":"因為我遵守耶和華的道，未曾作惡離開我的神。","notes":[]},{"n":23,"t":"他的一切典章在我面前，他的律例我也未曾丟棄。","notes":[]},{"n":24,"t":"我在他面前作了完全人，我也持守自己遠離罪孽。","notes":[]},{"n":25,"t":"所以耶和華按我的公義，在他眼前按我的清潔賞賜我。","notes":[]},{"n":26,"t":"慈愛的人，你以慈愛待他；完全的人，你以完善待他；","notes":[]},{"n":27,"t":"清潔的人，你以清潔待他；歪曲的人，你以彎曲待他。","notes":[]},{"n":28,"t":"困苦的百姓，你必拯救；但你的眼目察看高傲的人，使他們降卑。","notes":[]},{"n":29,"t":"耶和華啊，你是我的燈；耶和華必照明我的黑暗。","notes":[]},{"n":30,"t":"我藉著你衝入敵軍，藉著我的神跳過城牆。","notes":[]},{"n":31,"t":"至於神，他的道是完全的；耶和華的話是純淨的。凡投靠他的，他就作他們的盾牌。","notes":[]},{"n":32,"t":"除了耶和華，誰是神呢？除了我們的神，誰是磐石呢？","notes":[]},{"n":33,"t":"神是我堅固的保障，他為我開完全的路。","notes":[]},{"n":34,"t":"他使我的腳快如母鹿，使我站穩在高處。","notes":[]},{"n":35,"t":"他教導我的手能爭戰，我的膀臂能開銅造的弓。","notes":[]},{"n":36,"t":"你賜救恩給我作盾牌，你的庇護使我為大。","notes":["「庇護」或譯「溫和」。"]},{"n":37,"t":"你使我腳步寬闊，我的腳踝未曾滑跌。","notes":[]},{"n":38,"t":"我追趕我的仇敵，消滅他們；若不將他們滅絕，我總不歸回。","notes":[]},{"n":39,"t":"我滅絕了他們，打傷了他們，使他們站不起來；他們都倒在我的腳下。","notes":[]},{"n":40,"t":"你曾以力量束我的腰，使我能爭戰；也曾使那起來攻擊我的，都服在我以下。","notes":[]},{"n":41,"t":"你又使我的仇敵在我面前轉身逃跑，使我能殲滅那恨我的人。","notes":[]},{"n":42,"t":"他們仰望，卻無人拯救；就是呼求耶和華，他也不應允。","notes":[]},{"n":43,"t":"我搗碎他們，如同地上的灰塵；踐踏壓碎他們，如同街上的泥土。","notes":[]},{"n":44,"t":"你救我脫離我百姓的紛爭，保護我作列國的元首；我素不認識的百姓必事奉我。","notes":["「我百姓」：有古卷和七十士譯本是「百姓」。"]},{"n":45,"t":"外邦人要向我投降，一聽見我的名聲就必順從我。","notes":[]},{"n":46,"t":"外邦人要喪膽，戰戰兢兢地出營寨。","notes":[]},{"n":47,"t":"耶和華永遠活著。願我的磐石被稱頌，願神－救我的磐石受尊崇。","notes":[]},{"n":48,"t":"這位神為我伸冤，使萬民服在我以下。","notes":[]},{"n":49,"t":"他救我脫離仇敵，又把我舉起，高過那些起來攻擊我的人，救我脫離殘暴的人。","notes":[]},{"n":50,"t":"耶和華啊，因此我要在列國中稱謝你，歌頌你的名。","notes":[]},{"n":51,"t":"耶和華賜極大的救恩給他所立的王，施慈愛給他的受膏者，就是給大衛和他的後裔，直到永遠！","notes":[]}]},"23":{"heading":"大衛的遺言","verses":[{"n":1,"t":"以下是大衛末了的話：「耶西的兒子大衛的話，得居高位的，雅各的神所膏的，以色列所喜愛的詩人的話。","notes":[]},{"n":2,"t":"耶和華的靈藉著我說話，他的言語在我的舌頭上。","notes":[]},{"n":3,"t":"以色列的神說，以色列的磐石向我說：『那以公義治理人，以敬畏神來治理的，","notes":[]},{"n":4,"t":"他必像晨光，如無雲清晨的日出，如雨後的光輝，在嫩草地上。』","notes":[]},{"n":5,"t":"我的家在神面前不是如此嗎？神與我立永遠的約，這約既全備又穩妥。我的一切救恩和我一切所想望的，他豈不成全嗎？","notes":[]},{"n":6,"t":"但無賴全都像被丟棄的荊棘；它們不能用手去拿；","notes":[]},{"n":7,"t":"碰它們的人必須用鐵器和槍桿，它們必在那裏被火燒盡。」","notes":[]},{"n":8,"t":"大衛勇士的名字如下：哈革摩尼人約設‧巴設，他是三勇士之首；他又名叫伊斯尼人亞底挪，曾一次就擊殺了八百人。","notes":["「哈革摩尼人」是根據可能較早的讀法；原文是「他革捫人」；參代上11．11。","「他又名...八百人」：七十士譯本是「他曾一次舉槍擊殺了八百人」；參代上11．11。"],"heads":["大衛的勇士"]},{"n":9,"t":"跟隨大衛的三勇士中，其次是亞何亞人朵多的兒子以利亞撒。從前非利士人聚集要打仗，他們向非利士人罵陣。以色列人上去的時候，","notes":[]},{"n":10,"t":"他起來擊殺非利士人，直到手臂疲乏，手黏住刀把。那日耶和華大獲全勝，百姓跟在以利亞撒後面只顧奪取掠物。","notes":[]},{"n":11,"t":"再其次是哈拉人亞基的兒子沙瑪。一次，非利士人聚集在利希，在一塊長滿紅豆的田裏，百姓在非利士人面前逃跑。","notes":["「亞基」：原文另譯「以拉」。","「在利希」是根據可能是較早的讀法；原文是「成群」。"]},{"n":12,"t":"沙瑪卻站在那田的中間，防守那田，擊敗了非利士人。耶和華大獲全勝。","notes":[]},{"n":13,"t":"開始收割的時候，三個侍衛下到亞杜蘭洞，到大衛那裏。非利士的軍兵在利乏音谷安營。","notes":["「三個」：原文另譯「三十個」。","「侍衛」是根據可能是較早的讀法；原文是「三十」。"]},{"n":14,"t":"那時大衛在山寨，非利士人的駐軍在伯利恆。","notes":[]},{"n":15,"t":"大衛渴想著說：「但願有人從伯利恆城門旁的井裏打水來給我喝！」","notes":[]},{"n":16,"t":"這三個勇士就闖過非利士人的軍營，從伯利恆城門旁的井裏打水，拿來給大衛喝。他卻不肯喝，將水澆在耶和華面前，","notes":[]},{"n":17,"t":"說：「耶和華啊，我絕不做這事！這三個人冒生命的危險，這不是他們的血嗎？」大衛不肯喝這水。這是三個勇士所做的事。","notes":[]},{"n":18,"t":"洗魯雅的兒子，約押的兄弟亞比篩是這三個勇士的領袖；他曾舉槍殺了三百人，就在三個勇士中得了名。","notes":[]},{"n":19,"t":"他在這三個勇士中是最有名望的，所以作他們的領袖，只是不及前三個勇士。","notes":["「三個」：原文另譯「三十個」。"]},{"n":20,"t":"耶何耶大的兒子比拿雅是來自甲薛的勇士，曾行了大事。他殺了摩押人亞利伊勒的兩個兒子，又在下雪的時候下到坑裏去，殺了一隻獅子。","notes":[]},{"n":21,"t":"他又殺了一個魁梧的埃及人；埃及人手裏拿著槍。比拿雅只拿著棍子下到他那裏去，從埃及人手裏奪過槍來，用那槍殺死了他。","notes":[]},{"n":22,"t":"這些是耶何耶大的兒子比拿雅所做的事，就在三個勇士裏得了名。","notes":[]},{"n":23,"t":"他比那三十個勇士更有名望，只是不及前三個勇士。大衛立他作護衛長。","notes":["「那三十個勇士」：有古卷是「那些侍衛」。"]},{"n":24,"t":"三十個勇士中有約押的兄弟亞撒黑，伯利恆人朵多的兒子伊勒哈難，","notes":[]},{"n":25,"t":"哈律人沙瑪，哈律人以利加，","notes":[]},{"n":26,"t":"帕勒提人希利斯，提哥亞人益吉的兒子以拉，","notes":[]},{"n":27,"t":"亞拿突人亞比以謝，戶沙人米本乃，","notes":[]},{"n":28,"t":"亞何亞人撒們，尼陀法人瑪哈萊，","notes":[]},{"n":29,"t":"尼陀法人巴拿的兒子希立，便雅憫族基比亞人利拜的兒子以太，","notes":[]},{"n":30,"t":"比拉頓人比拿雅，迦實溪人希太，","notes":[]},{"n":31,"t":"亞拉巴人亞比‧亞本，巴魯米人押斯瑪弗，","notes":[]},{"n":32,"t":"沙本人以利雅哈巴，雅善兒子中的約拿單，","notes":[]},{"n":33,"t":"哈拉人沙瑪，哈拉人沙拉的兒子亞希暗，","notes":["「雅善兒子中...沙瑪」：原文另譯「沽尼族的雅善，哈拉人沙瑪的兒子約拿單」。"]},{"n":34,"t":"瑪迦人亞哈拜的兒子以利法列，基羅人亞希多弗的兒子以連，","notes":[]},{"n":35,"t":"迦密人希斯萊，亞巴人帕萊，","notes":[]},{"n":36,"t":"瑣巴人拿單的兒子以甲，迦得人巴尼，","notes":[]},{"n":37,"t":"亞捫人洗勒，比錄人拿哈萊，是給洗魯雅的兒子約押拿兵器的，","notes":[]},{"n":38,"t":"以帖人以拉，以帖人迦立，","notes":[]},{"n":39,"t":"赫人烏利亞，共三十七人。","notes":[]}]},"24":{"heading":"大衛調查人口","verses":[{"n":1,"t":"耶和華的怒氣又向以色列發作，激起大衛來對付他們，說：「去，數點以色列人和猶大人。」","notes":[]},{"n":2,"t":"大衛對跟隨他的約押元帥說：「你來回走遍以色列眾支派，從但直到別是巴，數點百姓，我好知道百姓的數目。」","notes":[]},{"n":3,"t":"約押對王說：「願耶和華－你的神使百姓的數目增加百倍，使我主我王親眼得見。我主我王何必要做這事呢？」","notes":[]},{"n":4,"t":"但王堅持他對約押和眾軍官的命令。約押和眾軍官就從王面前出去，數點以色列的百姓。","notes":[]},{"n":5,"t":"他們過約旦河，在迦得谷中、城的右邊亞羅珥安營，與雅謝相對。","notes":[]},{"n":6,"t":"他們來到基列，到了他停‧合示地，又來到但‧雅安，繞到西頓。","notes":["「他停‧合示地」：七十士譯本的一些抄本是「赫人的加低斯」。"]},{"n":7,"t":"他們來到推羅的堡壘，以及希未人和迦南人的各城，又出來，到猶大尼革夫的別是巴。","notes":["「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」。"]},{"n":8,"t":"他們來回走遍全地，過了九個月又二十天，就回到耶路撒冷。","notes":[]},{"n":9,"t":"約押向王報告百姓的總數：以色列拿刀的勇士有八十萬；猶大有五十萬人。","notes":[]},{"n":10,"t":"大衛數點百姓以後，心中自責。大衛向耶和華說：「我做這事大大有罪了。耶和華啊，現在求你除掉僕人的罪孽，因我所做的非常愚昧。」","notes":[]},{"n":11,"t":"大衛早晨起來，耶和華的話臨到迦得先知，就是大衛的先見，說：","notes":[]},{"n":12,"t":"「你去告訴大衛：『耶和華如此說：我向你提出三樣，隨你選擇一樣，我好降給你。』」","notes":[]},{"n":13,"t":"於是迦得來到大衛那裏告訴他，問他：「你要國中有七年的饑荒呢？或是你在敵人面前逃跑，被追趕三個月呢？或是在你國中有三日的瘟疫呢？現在你要考慮思量，我怎樣去回覆那差我來的。」","notes":["「七」：七十士譯本是「三」；參代上21．12。"]},{"n":14,"t":"大衛對迦得說：「我很為難。我們寧願落在耶和華的手裏，因為他有豐盛的憐憫；我不願落在人的手裏。」","notes":[]},{"n":15,"t":"於是，耶和華降瘟疫給以色列。自早晨到所定的時候，從但直到別是巴，百姓中死了七萬人。","notes":[]},{"n":16,"t":"天使向耶路撒冷伸手要毀滅這城的時候，耶和華改變心意，不降那災難，就對那在百姓中施行毀滅的天使說：「夠了！住手吧！」耶和華的使者正在耶布斯人亞勞拿的禾場那裏。","notes":[]},{"n":17,"t":"大衛看見那在百姓中施行毀滅的天使，就向耶和華說：「看哪，我犯了罪，行了惡，但這群羊做了甚麼呢？願你的手攻擊我和我的父家。」","notes":[]},{"n":18,"t":"當日，迦得來到大衛那裏，對他說：「你上去，在耶布斯人亞勞拿的禾場上為耶和華立一座壇。」","notes":[]},{"n":19,"t":"大衛就照著迦得的話，照著耶和華所吩咐的上去了。","notes":[]},{"n":20,"t":"亞勞拿觀看，看見王和臣僕向他走過來。亞勞拿就出去，臉伏於地，向王下拜。","notes":[]},{"n":21,"t":"亞勞拿說：「我主我王為何來到僕人這裏呢？」大衛說：「我要買你這禾場，為耶和華築一座壇，使瘟疫在百姓中停止。」","notes":[]},{"n":22,"t":"亞勞拿對大衛說：「我主我王，你眼中看為好，就拿去獻祭。看，這裏有牛可以作燔祭，有打糧的器具和套牛的軛可以當作柴。","notes":[]},{"n":23,"t":"王啊，這一切，亞勞拿都獻給王。」亞勞拿又對王說：「願耶和華－你的神悅納你。」","notes":[]},{"n":24,"t":"王對亞勞拿說：「不，我一定要按價錢向你買；我不能用白白得來的東西作燔祭獻給耶和華－我的神。」大衛就用五十舍客勒銀子買了那禾場與牛。","notes":[]},{"n":25,"t":"大衛在那裏為耶和華築了一座壇，獻燔祭和平安祭。耶和華垂聽了為那地的祈求，瘟疫就在以色列中停止了。","notes":[]}]}},"1KI":{"1":{"heading":"大衛王的晚年","verses":[{"n":1,"t":"大衛王年紀老邁，雖然蓋著外袍，仍不夠暖和。","notes":[]},{"n":2,"t":"臣僕對他說：「不如為我主我王找一個年輕的少女，侍立在王面前，照顧王，睡在王的懷中，好使我主我王得暖。」","notes":[]},{"n":3,"t":"於是他們在以色列全境尋找美貌的少女，找到了一個書念女子亞比煞，帶到王那裏。","notes":[]},{"n":4,"t":"這少女極其美貌，她照顧王，伺候王，王卻沒有與她親近。","notes":[]},{"n":5,"t":"那時，哈及的兒子亞多尼雅妄自尊大，說：「我要作王」，就為自己預備座車、騎兵，又派五十人在他前頭奔跑。","notes":[],"heads":["亞多尼雅謀篡王位"]},{"n":6,"t":"他父親從來沒有責怪他，說：「你為何這麼做？」他非常俊美，生在押沙龍之後。","notes":[]},{"n":7,"t":"亞多尼雅與洗魯雅的兒子約押和亞比亞他祭司商議；他們就順從亞多尼雅，幫助他。","notes":[]},{"n":8,"t":"但撒督祭司、耶何耶大的兒子比拿雅、拿單先知、示每、利以，以及大衛自己的勇士都不順從亞多尼雅。","notes":["「利以，以及大衛自己的勇士」：原文另譯「他的同伴，大衛自己的勇士」。"]},{"n":9,"t":"亞多尼雅在隱‧羅結旁瑣希列磐石那裏獻牛羊、肥犢為祭，請了他的眾兄弟，就是王的眾兒子，以及所有作王臣僕的猶大人。","notes":[]},{"n":10,"t":"但他沒有邀請拿單先知、比拿雅和勇士們，以及他的弟弟所羅門。","notes":[]},{"n":11,"t":"拿單對所羅門的母親拔示巴說：「哈及的兒子亞多尼雅作王了，你沒有聽見嗎？我們的主大衛卻不知道。","notes":[],"heads":["所羅門被立為王"]},{"n":12,"t":"現在，來，我給你出個主意，好保全你和你兒子所羅門的性命。","notes":[]},{"n":13,"t":"你去，進到大衛王那裏，對他說：『我主我王啊，你不是曾向使女起誓說：你兒子所羅門必接續我作王，他必坐在我的王位上嗎？亞多尼雅怎麼作了王呢？』","notes":[]},{"n":14,"t":"看哪，你還在那裏與王說話的時候，我會隨後進去，證實你的話。」","notes":[]},{"n":15,"t":"拔示巴進入內室，到王那裏。那時，王很老了，書念女子亞比煞正伺候著王。","notes":[]},{"n":16,"t":"拔示巴向王屈身下拜，王說：「你要甚麼？」","notes":[]},{"n":17,"t":"她對王說：「我主啊，你曾向使女指著耶和華－你的神起誓：『你兒子所羅門必接續我作王，他必坐在我的王位上。』","notes":[]},{"n":18,"t":"現在，看哪，亞多尼雅作王了，你，我主我王卻不知道。","notes":["「你」是根據一些古卷和七十士譯本；原文是「現在」。"]},{"n":19,"t":"他獻許多牛羊、肥犢為祭，請了王的眾兒子和亞比亞他祭司，以及約押元帥，他卻沒有請王的僕人所羅門。","notes":[]},{"n":20,"t":"但你，我主我王啊，以色列眾人的眼目都仰望你，等你告訴他們，在我主我王之後誰坐你的王位。","notes":["「你」：有些古卷和其他古譯本是「現在」。"]},{"n":21,"t":"若不然，我主我王與祖先同睡的時候，我和我兒子所羅門必列為罪犯了。」","notes":[]},{"n":22,"t":"看哪，拔示巴還與王說話的時候，拿單先知也進來了。","notes":[]},{"n":23,"t":"有人奏告王說：「看哪，拿單先知來了。」拿單進到王面前，臉伏於地，向王叩拜。","notes":[]},{"n":24,"t":"拿單說：「我主我王，你果真說過『亞多尼雅必接續我作王，他要坐在我的王位上』嗎？","notes":[]},{"n":25,"t":"他今日下去，獻了許多牛羊、肥犢為祭，請了王的眾兒子和軍官們，以及亞比亞他祭司；看哪，他們正在亞多尼雅面前吃喝，說：『亞多尼雅王萬歲！』","notes":[]},{"n":26,"t":"至於我，就是你的僕人，和撒督祭司、耶何耶大的兒子比拿雅、王的僕人所羅門，他都沒有請。","notes":[]},{"n":27,"t":"這事果真出於我主我王嗎？王卻沒有告訴僕人們，在我主我王之後誰坐你的王位。」","notes":[]},{"n":28,"t":"大衛王回答說：「召拔示巴到我這裏來。」拔示巴就來，站在王面前。","notes":[]},{"n":29,"t":"王起誓說：「我指著救我性命脫離一切苦難的永生的耶和華起誓。","notes":[]},{"n":30,"t":"我既然指著耶和華－以色列的神向你起誓說：你兒子所羅門必接續我作王，他必繼承我坐在我的王位上，我今日必這樣做。」","notes":[]},{"n":31,"t":"於是，拔示巴屈身，臉伏於地，向王叩拜，說：「我主大衛王萬歲！」","notes":[]},{"n":32,"t":"大衛王又說：「召撒督祭司、拿單先知、耶何耶大的兒子比拿雅到我這裏來！」他們就都來到王面前。","notes":[]},{"n":33,"t":"王對他們說：「要帶領你們主的僕人，讓我兒子所羅門騎我自己的騾子，送他下到基訓。","notes":[]},{"n":34,"t":"在那裏，撒督祭司和拿單先知要膏他作以色列的王；你們也要吹角，說：『所羅門王萬歲！』","notes":[]},{"n":35,"t":"你們要跟隨他上來，使他坐在我的王位上，他要接續我作王。我已立他作以色列和猶大的君王。」","notes":[]},{"n":36,"t":"耶何耶大的兒子比拿雅回應王說：「阿們！願耶和華－我主我王的神這樣說。","notes":[]},{"n":37,"t":"耶和華怎樣與我主我王同在，願他照樣與所羅門同在，使他的王位比我主大衛王的王位更大。」","notes":[]},{"n":38,"t":"於是，撒督祭司、拿單先知、耶何耶大的兒子比拿雅，以及基利提人和比利提人都下去，讓所羅門騎上大衛王的騾子，送他到基訓。","notes":[]},{"n":39,"t":"撒督祭司從帳幕中取了盛膏油的角來，膏所羅門。他們就吹角，眾百姓都說：「所羅門王萬歲！」","notes":[]},{"n":40,"t":"眾百姓跟隨他上來，吹著笛，大大歡呼，地被他們的聲音震裂。","notes":[]},{"n":41,"t":"亞多尼雅和所有的賓客剛吃完，聽見這聲音；約押聽見角聲就說：「城中為何有這響聲呢？」","notes":[]},{"n":42,"t":"他正說話的時候，看哪，亞比亞他祭司的兒子約拿單來了。亞多尼雅說：「進來吧！你是個賢明的人，必是來報好消息的。」","notes":[]},{"n":43,"t":"約拿單回答亞多尼雅說：「我們的主大衛王已經立所羅門為王了！","notes":[]},{"n":44,"t":"王派撒督祭司、拿單先知、耶何耶大的兒子比拿雅，以及基利提人和比利提人和所羅門一起去，叫他騎上王的騾子。","notes":[]},{"n":45,"t":"撒督祭司和拿單先知已經在基訓膏他作王了。他們從那裏歡呼著上來，城都震動，這就是你們所聽見的聲音。","notes":[]},{"n":46,"t":"所羅門也已經登上國度的王位了。","notes":[]},{"n":47,"t":"王的臣僕也來為我們的主大衛王祝福，說：『願神使所羅門的名比你的名更尊榮，使他的王位比你的王位更大。』王在床上屈身敬拜，","notes":[]},{"n":48,"t":"王也這樣說：『耶和華－以色列的神是應當稱頌的，因他今日賞賜一個人坐在我的王位上，我也親眼看見了。』」","notes":[]},{"n":49,"t":"亞多尼雅所有的賓客都戰兢，起來，各走各路去了。","notes":[]},{"n":50,"t":"亞多尼雅懼怕所羅門，就起來，去抓住祭壇的翹角。","notes":[]},{"n":51,"t":"有人告訴所羅門說：「看哪，亞多尼雅懼怕所羅門王。看哪，他抓住祭壇的翹角，說：『願所羅門王先向我起誓，必不用刀殺死僕人。』」","notes":[]},{"n":52,"t":"所羅門說：「他若作賢明的人，連一根頭髮也不致落在地上；他若作惡，必要死亡。」","notes":[]},{"n":53,"t":"於是所羅門王派人叫亞多尼雅從壇上下來，他就來向所羅門王下拜。所羅門對他說：「你回家去吧！」","notes":[]}]},"2":{"heading":"大衛給所羅門的遺訓","verses":[{"n":1,"t":"大衛的死期臨近了，就吩咐他兒子所羅門說：","notes":[]},{"n":2,"t":"「我要走世人必走的路了。你當剛強，作大丈夫，","notes":[]},{"n":3,"t":"遵守耶和華－你神所吩咐的，照著摩西律法上所寫的行耶和華的道，謹守他的律例、誡命、典章、法度，好讓你無論做甚麼，不拘往何處去，盡都亨通。","notes":[]},{"n":4,"t":"耶和華必成就他所說關於我的話，說：『你的子孫若謹慎自己的行為，盡心盡意憑信實行在我面前，就不斷有人坐以色列的王位。』","notes":[]},{"n":5,"t":"你也知道洗魯雅的兒子約押向我所做的事，他對付以色列的兩個元帥，尼珥的兒子押尼珥和益帖的兒子亞瑪撒，殺了他們。他在太平之時，如同戰爭一般，流這二人的血，把這戰爭的血染了他腰間束的帶和腳上穿的鞋。","notes":[]},{"n":6,"t":"所以你要照你的智慧去做，不讓他白髮安然下陰間。","notes":[]},{"n":7,"t":"你當恩待基列人巴西萊的眾兒子，請他們常與你同席吃飯，因為我躲避你哥哥押沙龍的時候，他們親近我。","notes":[]},{"n":8,"t":"看哪，在你這裏有來自巴戶琳的便雅憫人，基拉的兒子示每。我到瑪哈念去的那日，他用狠毒的言語咒罵我。後來他卻下約旦河迎接我，我就指著耶和華向他起誓說：『我必不用刀殺死你。』","notes":[]},{"n":9,"t":"但現在你不要以他為無罪。你是有智慧的人，必知道怎樣待他，使他白髮流血下陰間。」","notes":[]},{"n":10,"t":"大衛與他祖先同睡，葬在大衛城。","notes":[],"heads":["大衛壽終"]},{"n":11,"t":"大衛作以色列王四十年：在希伯崙作王七年，在耶路撒冷作王三十三年。","notes":[]},{"n":12,"t":"所羅門坐他父親大衛的王位，他的國度非常穩固。","notes":[]},{"n":13,"t":"哈及的兒子亞多尼雅到所羅門的母親拔示巴那裏，拔示巴問他說：「你是為平安來的嗎？」他說：「為平安來的。」","notes":[],"heads":["亞多尼雅的死"]},{"n":14,"t":"他又說：「我有話對你說。」拔示巴說：「你說吧。」","notes":[]},{"n":15,"t":"亞多尼雅說：「你知道這國原是歸我的，全以色列也都期望我作王。然而，這國反歸了我兄弟，因這國歸了他是出乎耶和華。","notes":[]},{"n":16,"t":"現在我有一件事求你，請你不要推辭。」拔示巴對他說：「你說吧。」","notes":[]},{"n":17,"t":"他說：「求你請所羅門王把書念女子亞比煞賜我為妻，因他必不拒絕你。」","notes":[]},{"n":18,"t":"拔示巴說：「好，我必為你對王提說。」","notes":[]},{"n":19,"t":"於是，拔示巴來到所羅門王那裏，要為亞多尼雅說話。王起來迎接，向她下拜，然後坐在自己的位上，又為王的母親設一座位，她就坐在王的右邊。","notes":[]},{"n":20,"t":"拔示巴說：「我要向你提出一個小小的請求，請你不要回絕我。」王對她說：「母親，請提出來，我必不回絕你。」","notes":[]},{"n":21,"t":"拔示巴說：「請你把書念女子亞比煞賜給你哥哥亞多尼雅為妻。」","notes":[]},{"n":22,"t":"所羅門王回答母親說：「為何替亞多尼雅求書念女子亞比煞呢？可以為他求王國吧！他是我的兄長，不但為他，也為亞比亞他祭司和洗魯雅的兒子約押求吧！」","notes":["「不但為他...求吧！」有古譯本是「亞比亞他祭司和洗魯雅的兒子約押也擁護他。」"]},{"n":23,"t":"所羅門王指著耶和華起誓說：「亞多尼雅講這話是自己送命，不然，願神重重懲罰我。","notes":[]},{"n":24,"t":"耶和華堅立我，使我坐在父親大衛的王位上，照著他所應許的為我建立家室；現在我指著永生的耶和華起誓，亞多尼雅今日必被處死。」","notes":[]},{"n":25,"t":"於是所羅門王派耶何耶大的兒子比拿雅去擊殺亞多尼雅，他就死了。","notes":[]},{"n":26,"t":"王對亞比亞他祭司說：「你回亞拿突歸自己的田地去吧！你本是該死的，但因你在我父親大衛面前抬過主耶和華的約櫃，又與我父親同受一切苦難，所以我今日不殺死你。」","notes":[],"heads":["亞比亞他被廢和約押的死"]},{"n":27,"t":"所羅門就革除亞比亞他，不讓他作耶和華的祭司。這就應驗了耶和華在示羅論以利家所說的話。","notes":[]},{"n":28,"t":"雖然約押沒有擁護押沙龍，卻擁護了亞多尼雅；這消息傳到約押那裏，他就逃到耶和華的帳幕，抓住祭壇的翹角。","notes":[]},{"n":29,"t":"有人告訴所羅門王：「約押逃到耶和華的帳幕，看哪，他在祭壇的旁邊。」所羅門就派耶何耶大的兒子比拿雅，說：「去，殺了他。」","notes":["七十士譯本在此加「所羅門派人到約押那裏，說：『你為何要逃到祭壇那裏？』約押說：『因為我怕你，所以我逃到主那裏。』」"]},{"n":30,"t":"比拿雅來到耶和華的帳幕，對約押說：「王這樣吩咐：『你出來吧！』」他說：「不，我要死在這裏。」比拿雅就去回覆王，說：「約押這樣說，他這樣回答我。」","notes":[]},{"n":31,"t":"王對他說：「你可以照著他的話去做，殺了他，把他葬了，好叫約押流無辜人血的罪不歸在我和我的父家。","notes":[]},{"n":32,"t":"耶和華必使約押的血歸到他自己頭上，因為他擊殺兩個比他又公義又良善的人，就是尼珥的兒子以色列的元帥押尼珥和益帖的兒子猶大的元帥亞瑪撒，用刀殺了他們，我父親大衛卻不知道。","notes":[]},{"n":33,"t":"這二人的血必歸到約押和他後裔頭上，直到永遠；惟有大衛和他的後裔，以及他的家與王位，必從耶和華那裏得平安，直到永遠。」","notes":[]},{"n":34,"t":"於是耶何耶大的兒子比拿雅上去，擊殺約押，殺死他，把他葬在曠野約押自己的家裏。","notes":[]},{"n":35,"t":"王就立耶何耶大的兒子比拿雅作元帥，代替約押，又使撒督祭司代替亞比亞他。","notes":[]},{"n":36,"t":"王派人召示每來，對他說：「你要在耶路撒冷為自己建造房屋，住在那裏，不可從那裏出來到任何地方去。","notes":[],"heads":["示每的死"]},{"n":37,"t":"你當確實知道，你何日出來過汲淪溪，就必定死！你的血必歸到自己頭上。」","notes":[]},{"n":38,"t":"示每對王說：「這話很好！我主我王怎樣說，僕人必照樣做。」於是示每住在耶路撒冷許多日子。","notes":[]},{"n":39,"t":"過了三年，示每的兩個奴僕逃到瑪迦的兒子迦特王亞吉那裏去。有人告訴示每說：「看哪，你的奴僕在迦特。」","notes":[]},{"n":40,"t":"示每起來，備上驢，往迦特到亞吉那裏去找他的奴僕，從迦特帶他的奴僕回來。","notes":[]},{"n":41,"t":"有人告訴所羅門：「示每出耶路撒冷到迦特去，又回來了。」","notes":[]},{"n":42,"t":"王就派人召示每來，對他說：「我豈不是叫你指著耶和華起誓，並且警告你說『你當確實知道，你何日出來到任何地方去，就必定死』嗎？你也對我說：『這話很好，我必聽從。』","notes":[]},{"n":43,"t":"你為何不遵守你對耶和華的誓言和我吩咐你的命令呢？」","notes":[]},{"n":44,"t":"王又對示每說：「你向我父親大衛所做的一切惡事，你自己心裏都知道，耶和華必使你的罪惡歸到你自己的頭上。","notes":[]},{"n":45,"t":"但所羅門王必蒙福，大衛的王位必在耶和華面前堅立，直到永遠。」","notes":[]},{"n":46,"t":"於是王吩咐耶何耶大的兒子比拿雅，他就出去，擊殺示每，示每就死了。這樣，國度在所羅門的手中鞏固了。","notes":[]}]},"3":{"heading":"所羅門的祈禱","verses":[{"n":1,"t":"所羅門與埃及王法老結親，娶了法老的女兒，接她進入大衛城，直等到建完了自己的宮和耶和華的殿，以及耶路撒冷周圍的城牆。","notes":[]},{"n":2,"t":"當那些日子，百姓仍在丘壇獻祭，因為還沒有為耶和華的名建殿。","notes":[]},{"n":3,"t":"所羅門愛耶和華，遵行他父親大衛的律例，只是還在丘壇獻祭燒香。","notes":[]},{"n":4,"t":"所羅門王到基遍，在那裏獻祭，因為基遍有極大的丘壇。所羅門在那壇上獻了一千祭牲為燔祭。","notes":[]},{"n":5,"t":"在基遍，耶和華夜間在夢中向所羅門顯現；神說：「你願我賜你甚麼，你可以求。」","notes":[]},{"n":6,"t":"所羅門說：「你曾向你僕人我父親大衛大施慈愛，因為他用忠信、公義、正直的心行在你面前。你又為他存留大慈愛，賜他一個兒子坐在他的王位上，正如今日一樣。","notes":[]},{"n":7,"t":"現在，耶和華－我的神啊，你使僕人接續我父親大衛作王；但我是幼小的孩子，不知道應當怎樣出入。","notes":[]},{"n":8,"t":"僕人住在你揀選的百姓中，這百姓之多，多得不可點，不可算。","notes":[]},{"n":9,"t":"所以求你賜僕人善於了解的心，可以判斷你的百姓，辨別是非。不然，誰能判斷你這麼多的百姓呢？」","notes":[]},{"n":10,"t":"所羅門因為求這事，就蒙主喜悅。","notes":[]},{"n":11,"t":"神對他說：「你既然求這事，不為自己求壽、求富，也不求滅絕你仇敵的性命，只求能明辨，可以聽訟，","notes":[]},{"n":12,"t":"看哪，我會照你的話去做，看哪，我會賜你智慧和明辨的心，在你以前沒有像你的，在你以後也沒有興起像你的。","notes":[]},{"n":13,"t":"你沒有求的，我也賜給你，就是富足、尊榮，使你在世一切的日子，列王中沒有一個能比你的。","notes":[]},{"n":14,"t":"你若遵行我的道，謹守我的律例、誡命，正如你父親大衛所行的，我必使你長壽。」","notes":[]},{"n":15,"t":"所羅門醒了，看哪，是個夢。他就來到耶路撒冷，站在耶和華的約櫃前，獻燔祭和平安祭，又為眾臣僕擺設宴席。","notes":[]},{"n":16,"t":"那時，有兩個妓女來，站在王面前。","notes":[],"heads":["所羅門審疑難的案件"]},{"n":17,"t":"一個婦人說：「我主啊，我和這婦人同住一屋。她在屋子裏的時候，我生了一個孩子。","notes":[]},{"n":18,"t":"我生了以後第三天，這婦人也生了。我們是一起的，屋子裏除了我們二人之外，再沒有別人在屋子裏。","notes":[]},{"n":19,"t":"夜間，這婦人的兒子死了，因為她壓在她的兒子身上。","notes":[]},{"n":20,"t":"她半夜起來，趁你使女睡著的時候，從我旁邊把我兒子抱走，放在她懷裏，又把她死的兒子放在我懷裏。","notes":[]},{"n":21,"t":"清早，我起來要給我的兒子吃奶，看哪，他死了；早晨我仔細察看他，看哪，他不是我所生的兒子。」","notes":[]},{"n":22,"t":"另一個婦人說：「不！我的兒子是活的，你的兒子是死的。」但這一個說：「不！你的兒子是死的，我的兒子是活的。」她們就在王面前爭吵。","notes":[]},{"n":23,"t":"王說：「這婦人說：『這是我的兒子，他是活的，你的兒子是死的。』那婦人說：『不！你的兒子是死的，我的兒子是活的。』」","notes":[]},{"n":24,"t":"王就說：「給我拿刀來！」人就把刀拿到王面前來。","notes":[]},{"n":25,"t":"王說：「把活孩子劈成兩半，一半給這婦人，一半給那婦人。」","notes":[]},{"n":26,"t":"活孩子的母親為自己的兒子心急如焚，對王說：「求我主把活孩子給那婦人吧，萬不可殺死他！」那婦人說：「這孩子也不歸我，也不歸你，你們就劈了吧！」","notes":[]},{"n":27,"t":"王回應說：「把活孩子給這婦人，萬不可殺死他，因為這婦人是他的母親。」","notes":[]},{"n":28,"t":"全以色列聽見王這樣判斷，就都敬畏王，因為他們看見他心中有神的智慧，能夠斷案。","notes":[]}]},"4":{"heading":"所羅門的臣僕","verses":[{"n":1,"t":"所羅門作全以色列的王。","notes":[]},{"n":2,"t":"這些是他的官員：撒督的兒子亞撒利雅作祭司，","notes":[]},{"n":3,"t":"示沙的兩個兒子以利何烈、亞希亞作書記，亞希律的兒子約沙法作史官，","notes":[]},{"n":4,"t":"耶何耶大的兒子比拿雅作元帥，撒督和亞比亞他作祭司，","notes":[]},{"n":5,"t":"拿單的兒子亞撒利雅作宰相，拿單的兒子撒布得作祭司和王的顧問，","notes":[]},{"n":6,"t":"亞希煞作管家，亞比大的兒子亞多尼蘭掌管服勞役的工人。","notes":[]},{"n":7,"t":"所羅門在全以色列有十二個官員，供給王和王室的食物，每年各人供給一個月。","notes":[]},{"n":8,"t":"這些是他們的名字：在以法蓮山區有便‧戶珥；","notes":[]},{"n":9,"t":"在瑪迦斯、沙賓、伯‧示麥、以倫‧伯‧哈南有便‧底甲；","notes":[]},{"n":10,"t":"在亞魯泊有便‧希悉，他管理梭哥和希弗全地；","notes":[]},{"n":11,"t":"在多珥山岡有便‧亞比拿達，他娶了所羅門的女兒她法為妻；","notes":["「山岡」或譯「全境」。"]},{"n":12,"t":"在他納和米吉多，以及靠近撒拉他拿、耶斯列下邊的伯‧善全地，從伯‧善到亞伯‧米何拉直到約緬的另一邊有亞希律的兒子巴拿；","notes":[]},{"n":13,"t":"在基列的拉末有便‧基別，他管理在基列的瑪拿西子孫睚珥的城鎮，巴珊的亞珥歌伯地的六十座大城，各有城牆和銅閂；","notes":[]},{"n":14,"t":"在瑪哈念有易多的兒子亞希拿達；","notes":[]},{"n":15,"t":"在拿弗他利有亞希瑪斯，他也娶了所羅門的一個女兒巴實抹為妻；","notes":[]},{"n":16,"t":"在亞設和亞祿有戶篩的兒子巴拿；","notes":[]},{"n":17,"t":"在以薩迦有帕路亞的兒子約沙法；","notes":[]},{"n":18,"t":"在便雅憫有以拉的兒子示每；","notes":[]},{"n":19,"t":"在基列地，就是亞摩利王西宏和巴珊王噩之地，有烏利的兒子基別，他一個官員管理這地 。","notes":["「有烏利的兒子基別，他一個官員管理這地」或譯「有烏利的兒子基別。另有一個官員管理這地」；後者的「這地」指猶大。"]},{"n":20,"t":"猶大人和以色列人如同海邊的沙那樣多，都吃喝快樂。","notes":[],"heads":["所羅門的富強"]},{"n":21,"t":"所羅門統治諸國，從大河到非利士地，直到埃及的邊界。所羅門在世的日子，這些國都向他進貢，服事他。","notes":[]},{"n":22,"t":"所羅門每日所用的食物：三十歌珥細麵，六十歌珥粗麵，","notes":[]},{"n":23,"t":"十頭肥牛，二十頭草場的牛，一百隻羊，還有鹿、羚羊、麃子，以及肥禽。","notes":[]},{"n":24,"t":"所羅門管理整個大河西邊，從提弗薩直到迦薩，以及大河西邊的諸王，屬他的四境盡都平安。","notes":[]},{"n":25,"t":"所羅門在世的日子，從但到別是巴，猶大和以色列各人都在自己的葡萄樹下和無花果樹下安然居住。","notes":[]},{"n":26,"t":"所羅門擁有給戰車用的四萬個馬棚，還有一萬二千名騎兵。","notes":["「四萬個」：原文另譯「四千個」；參代下9．25。"]},{"n":27,"t":"這些官員各按自己的月份供給所羅門王，以及一切與他同席之人的食物，一無所缺。","notes":[]},{"n":28,"t":"他們各按其分，把給馬與快馬吃的大麥和乾草送到指定的地方去。","notes":[]},{"n":29,"t":"神賜給所羅門極大的智慧和聰明，以及寬闊的心，如同海邊的沙。","notes":[],"heads":["所羅門的智慧"]},{"n":30,"t":"所羅門的智慧超過所有東方人的智慧，和埃及人一切的智慧。","notes":[]},{"n":31,"t":"他的智慧勝過萬人，勝過以斯拉人以探，以及瑪曷的兒子希幔、甲各、達大。他的名聲傳遍四圍的列國。","notes":[]},{"n":32,"t":"他作箴言三千句，詩歌一千零五首。","notes":[]},{"n":33,"t":"他講論草木，從黎巴嫩的香柏樹直到牆上長的牛膝草，又講論飛禽、走獸、爬行動物和魚類。","notes":[]},{"n":34,"t":"地上凡曾聽過他智慧的君王，都派人來；萬民都有人來聽所羅門的智慧。","notes":[]}]},"5":{"heading":"所羅門準備建殿","verses":[{"n":1,"t":"推羅王希蘭是大衛平生的好友。希蘭聽見以色列人膏所羅門接續他父親作王，就派臣僕到他那裏。","notes":[]},{"n":2,"t":"所羅門也派人到希蘭那裏，說：","notes":[]},{"n":3,"t":"「你知道我父親大衛因四圍的戰爭，不能為耶和華－他神的名建殿，直等到耶和華使仇敵都服在他腳下。","notes":[]},{"n":4,"t":"現在耶和華－我的神使我四圍太平，沒有仇敵，沒有災禍。","notes":[]},{"n":5,"t":"看哪，我吩咐要為耶和華－我神的名建殿，是照耶和華向我父親大衛說的：『我必使你兒子接續你，坐你的王位，他必為我的名建殿。』","notes":[]},{"n":6,"t":"現在，請吩咐人在黎巴嫩為我砍伐香柏木，我的僕人必幫助你的僕人。至於你僕人的工錢，我必照你所定的給你。你知道，在我們中間沒有人像西頓人那樣擅長砍伐樹木。」","notes":[]},{"n":7,"t":"希蘭聽見所羅門的話，就很高興，說：「今日耶和華是應當稱頌的，因為他賜給大衛一個有智慧的兒子，治理這眾多的百姓。」","notes":[]},{"n":8,"t":"希蘭送信給所羅門，說：「你派人向我所提的那事，我已聽見了；論到香柏木和松木，我必照你一切的心願去做。","notes":[]},{"n":9,"t":"我的僕人必把這木料從黎巴嫩運到海裏，我會把它們紮成筏子浮在海上，運到你告訴我的地方，在那裏拆開，你就可以收取；你也要照我的心願做，把食物給我的家。」","notes":[]},{"n":10,"t":"於是希蘭照所羅門的心願，給他香柏木和松木；","notes":[]},{"n":11,"t":"所羅門給希蘭二萬歌珥麥子，二十歌珥搗成的油，作他家的食物。所羅門每年都是這樣給希蘭。","notes":["「二十歌珥」：七十士譯本是「二萬罷特」﹔參代下2．10。"]},{"n":12,"t":"耶和華照著所應許的賜智慧給所羅門。希蘭與所羅門和平相處，二人彼此立約。","notes":[]},{"n":13,"t":"所羅門王從全以色列挑取服勞役的人，徵來的人有三萬，","notes":[]},{"n":14,"t":"派他們輪流每月一萬人上黎巴嫩去；一個月在黎巴嫩，兩個月在家裏。亞多尼蘭管理他們。","notes":[]},{"n":15,"t":"所羅門有七萬扛抬的，八萬在山上鑿石頭的。","notes":[]},{"n":16,"t":"此外，所羅門有三千三百個監督工作的官長，監管百姓做工。","notes":[]},{"n":17,"t":"王下令，他們就鑿出又大又貴重的石頭來，用以立殿的根基。","notes":[]},{"n":18,"t":"所羅門的工匠和希蘭的工匠，以及迦巴勒人，把石頭鑿好，預備了木料和石頭來建殿。","notes":[]}]},"6":{"heading":"所羅門建造聖殿","verses":[{"n":1,"t":"以色列人出埃及地後四百八十年，所羅門作以色列王第四年西弗月，就是二月，他開工建造耶和華的殿。","notes":[]},{"n":2,"t":"所羅門王為耶和華所建的殿，長六十肘，寬二十肘，高三十肘。","notes":[]},{"n":3,"t":"殿的正堂前走廊長二十肘，與殿的寬度一樣，殿前寬十肘；","notes":[]},{"n":4,"t":"他為殿做了有框嵌壁式的窗戶。","notes":[]},{"n":5,"t":"靠著殿牆，圍著外殿和內殿的牆，周圍建造了廂房；","notes":[]},{"n":6,"t":"下層寬五肘，中層寬六肘，第三層寬七肘。他在殿牆的周圍造坎，免得梁木插入殿牆裏。","notes":[]},{"n":7,"t":"殿是用山中鑿成的石頭建的，所以建殿的時候，鎚子、斧子和別樣鐵器的響聲都沒有聽見。","notes":[]},{"n":8,"t":"在殿右邊當中的廂房有門，可以從螺旋梯上到中層，再從中層上到第三層。","notes":[]},{"n":9,"t":"所羅門完成殿的建造。他用香柏木作梁木和橫板，遮蓋殿頂。","notes":[]},{"n":10,"t":"靠著整個殿所造的廂房，每層高五肘，香柏木的梁板擱在殿的牆坎上。","notes":[]},{"n":11,"t":"耶和華的話臨到所羅門，說：","notes":[],"heads":["耶和華的約"]},{"n":12,"t":"「論到你所建的這殿，你若遵行我的律例，謹守我的典章，遵從我的一切誡命，行在其中，我必向你應驗我所應許你父親大衛的話。","notes":[]},{"n":13,"t":"我必住在以色列人中間，並不丟棄我的百姓以色列。」","notes":[]},{"n":14,"t":"所羅門完成殿的建造。","notes":[],"heads":["殿內的設備"]},{"n":15,"t":"他用香柏木板建造殿的內牆，從殿的地到牆頂都貼上木板，又用松木板鋪地。","notes":["「牆頂」：原文另譯「天花板的椽子」。"]},{"n":16,"t":"他在殿的後部建了一間內殿，長二十肘，從地到牆用香柏木板，作為至聖所。","notes":["「牆」：原文另譯「椽子」。"]},{"n":17,"t":"殿，就在內殿的前面，長四十肘。","notes":["「就在內殿的前面」：原文另譯「就是至聖所前面的內殿」。"]},{"n":18,"t":"殿裏一點石頭都不顯露，一概用香柏木遮蔽；香柏木上刻著野瓜和綻開的花。","notes":[]},{"n":19,"t":"他在殿的中間預備內殿，在那裏安放耶和華的約櫃。","notes":[]},{"n":20,"t":"內殿長二十肘，寬二十肘，高二十肘，都貼上純金。他又用香柏木做壇。","notes":["「內殿」：原文是「內殿的前面」。"]},{"n":21,"t":"所羅門用純金貼殿內，又用金鏈子掛在內殿前，內殿也貼上金子。","notes":[]},{"n":22,"t":"整個殿都貼上金子，直到貼滿；內殿前的整個壇，也都包上金子。","notes":[]},{"n":23,"t":"他在內殿裏用橄欖木做兩個基路伯，各高十肘。","notes":[],"heads":["造二基路伯"]},{"n":24,"t":"這基路伯的一個翅膀長五肘，另一個翅膀長五肘，從一個翅膀尖到另一個翅膀尖共有十肘；","notes":[]},{"n":25,"t":"第二個基路伯也是十肘；兩個基路伯的尺寸、形狀都一樣。","notes":[]},{"n":26,"t":"這一個基路伯高十肘，第二個基路伯也是如此。","notes":[]},{"n":27,"t":"他把兩個基路伯安在內殿中間。基路伯的翅膀是張開的，這基路伯的一個翅膀挨著這邊的牆，第二個基路伯的一個翅膀挨著那邊的牆，向內的兩個翅膀在殿中間彼此相接。","notes":[]},{"n":28,"t":"二基路伯都包上金子。","notes":[]},{"n":29,"t":"殿周圍的牆上全都刻著基路伯、棕樹和綻開的花，內外都是如此。","notes":[],"heads":["殿的裝飾"]},{"n":30,"t":"殿的地板都貼上金子，內外都是如此。","notes":[]},{"n":31,"t":"他用橄欖木製造內殿的入口、門楣和五邊形的門柱。","notes":[]},{"n":32,"t":"在橄欖木做的兩門扇上刻著基路伯、棕樹和綻開的花，都貼上金子。基路伯和棕樹上也灑上金子。","notes":[]},{"n":33,"t":"他又為外殿的入口，用橄欖木製造門柱，是四邊形的。","notes":[]},{"n":34,"t":"他用松木做兩扇門。這一扇有兩葉摺疊，第二扇也有兩葉摺疊。","notes":["「葉」：原文是「帷幕」。"]},{"n":35,"t":"上面刻著基路伯、棕樹和綻開的花，雕刻物都均勻地貼上金子。","notes":[]},{"n":36,"t":"他又用三層鑿成的石頭、香柏木一層建造內院。","notes":[]},{"n":37,"t":"所羅門在位第四年西弗月，立了耶和華殿的根基。","notes":[]},{"n":38,"t":"到十一年布勒月，就是八月，殿和一切屬殿的都按著樣式造成。他建殿共用了七年。","notes":[]}]},"7":{"heading":"所羅門的王宮","verses":[{"n":1,"t":"所羅門為自己建造宮殿，十三年方才建成整座宮殿。","notes":[]},{"n":2,"t":"他建造黎巴嫩林宮，長一百肘，寬五十肘，高三十肘，有四行香柏木柱，柱上有香柏木橫梁；","notes":[]},{"n":3,"t":"廂房以上覆蓋著香柏木，在四十五根柱子之上，每行十五根。","notes":[]},{"n":4,"t":"窗戶有三排，三排的窗與窗相對。","notes":[]},{"n":5,"t":"所有的門和門柱都有四方形的框，共有三行，彼此相對。","notes":[]},{"n":6,"t":"他建造有柱子的廳，長五十肘，寬三十肘。在這前面有走廊，前面有柱子和頂蓋。","notes":["「頂蓋」或譯「臺階」。"]},{"n":7,"t":"他又建造一個有座位的廳，就是審判廳，他在那裏審判；這廳的地板從這邊到那邊都鋪上香柏木。","notes":[]},{"n":8,"t":"廳後面的院內有所羅門自己住的宮殿，都用同樣的建造方式。所羅門又為所娶法老的女兒建造一座宮，建造方式與這廳一樣。","notes":[]},{"n":9,"t":"建造這一切所用的石頭都是貴重的，按著尺寸鑿成，用鋸子裏外鋸齊；從根基直到房檐，從外頭直到大院，都是如此。","notes":[]},{"n":10,"t":"根基是貴重的大石頭，有長十肘的，有長八肘的；","notes":[]},{"n":11,"t":"上面有香柏木和按著尺寸鑿成的貴重石頭。","notes":[]},{"n":12,"t":"大院周圍有鑿成的石頭三層、香柏木板一層，都照耶和華殿的內院和殿的走廊的樣式。","notes":[]},{"n":13,"t":"所羅門王派人從推羅把戶蘭接來。","notes":["「戶蘭」：原文是「希蘭」；下同。"],"heads":["戶蘭的工作"]},{"n":14,"t":"他是拿弗他利支派中一個寡婦的兒子，父親是推羅人，是作銅匠的。戶蘭滿有智慧、聰明、技能，善作各樣的銅器。他來到所羅門王那裏，為王做一切的工。","notes":[]},{"n":15,"t":"戶蘭製造兩根銅柱，一根高十八肘，第二根柱子用繩子量，周圍是十二肘；","notes":["「一根...十二肘」：原文另譯「一根高十八肘，用繩子量，周圍是十二肘，第二根柱子也一樣」。"],"heads":["兩根銅柱"]},{"n":16,"t":"他做了兩個柱頂安在柱上，是用銅鑄造的，一個柱頂高五肘，第二個柱頂也高五肘。","notes":[]},{"n":17,"t":"柱子頂上有裝飾的網子和編成的鏈子，一個柱頂有七個，第二個柱頂也有七個。","notes":[]},{"n":18,"t":"他做了柱子，第一根柱子的柱頂上，周圍有兩行網子在柱子上面遮蓋柱頂，第二根柱頂也是這樣做。","notes":["「柱子」：有些古卷是「石榴」。","「柱子」是根據許多古卷；原文是「石榴」。"]},{"n":19,"t":"走廊柱子頂上的柱頂高四肘，刻著百合花。","notes":[]},{"n":20,"t":"兩根柱子上面有柱頂，柱頂靠近網子的圓凸面上，有石榴的行列環繞著，共二百個，第二個柱頂也是如此。","notes":[]},{"n":21,"t":"他把兩根柱子立在殿的走廊前：右邊立一根，起名叫雅斤；左邊立一根，起名叫波阿斯。","notes":[]},{"n":22,"t":"柱頂上刻著百合花。這樣，柱子的工程就完畢了。","notes":[]},{"n":23,"t":"他又鑄一個銅海，周圍是圓的，直徑十肘，高五肘，用繩子量周圍是三十肘。","notes":[],"heads":["銅海"]},{"n":24,"t":"銅海邊緣下面的周圍有野瓜的形狀，每肘十個，共兩行，繞著銅海，是造銅海的時候鑄上去的。","notes":[]},{"n":25,"t":"銅海安在十二頭銅牛上：三頭向北，三頭向西，三頭向南，三頭向東。銅海安在牛上，牛尾都向內。","notes":[]},{"n":26,"t":"銅海厚一掌，邊如杯邊，像百合花，容量是二千罷特。","notes":[]},{"n":27,"t":"他用銅製造十個盆座，每座長四肘，寬四肘，高三肘。","notes":[],"heads":["銅座"]},{"n":28,"t":"銅座的造法是這樣：周圍各有嵌邊，嵌邊裝在框架中。","notes":[]},{"n":29,"t":"裝在框架中的嵌邊上有獅子和牛，以及基路伯。框架上有小座，獅子和牛的上面和下面有錘成的花紋浮雕。","notes":[]},{"n":30,"t":"每座有四個銅輪和銅軸，它有四個支架在盆以下，這些支架是鑄成的，各邊都有花紋。","notes":[]},{"n":31,"t":"它的口在柱頂裏，向上高一肘，口是圓的，做法如座一樣，直徑是一肘半，口上也有雕工。嵌邊是方形的，不是圓的。","notes":[]},{"n":32,"t":"四個輪子在嵌邊以下，輪軸與座相連，每輪高一肘半。","notes":[]},{"n":33,"t":"輪的樣式如同車的輪子；軸、輞、輻、轂都是鑄成的。","notes":[]},{"n":34,"t":"每個座四邊有四個盆形的支架，這些支架是與座從一整塊鑄成的。","notes":[]},{"n":35,"t":"座頂有圓架，高半肘；座頂有支柱和嵌邊，是與座從一整塊鑄成的。","notes":[]},{"n":36,"t":"他在支柱和嵌邊上，每個空處刻上基路伯、獅子和棕樹，周圍有花紋。","notes":[]},{"n":37,"t":"他按照這樣的做法造了十個盆座，它們的鑄法、尺寸、樣式全都相同。","notes":[]},{"n":38,"t":"他又造十個銅盆，每盆的容量四十罷特，直徑四肘。在十個座上，每座安設一盆。","notes":[]},{"n":39,"t":"他把五個安置在殿的右邊，五個安置在殿的左邊，又把銅海安置在殿的右旁，在東南邊。","notes":[]},{"n":40,"t":"戶蘭又造了盆、鏟子和盤子。這樣，戶蘭為所羅門王做完了耶和華殿一切的工：","notes":[],"heads":["聖殿設備清單"]},{"n":41,"t":"兩根柱子和柱子頂上兩個如碗的柱頂，以及蓋著如碗柱頂的兩個網子；","notes":[]},{"n":42,"t":"四百個石榴，安在兩個網子上，每網兩行石榴，蓋著柱子上面兩個如碗的柱頂；","notes":[]},{"n":43,"t":"十個盆座和其上的十個盆；","notes":[]},{"n":44,"t":"銅海和其下的十二頭牛；","notes":[]},{"n":45,"t":"盆、鏟子、盤子。戶蘭給所羅門王為耶和華殿造的這一切器皿都是用光亮的銅，","notes":[]},{"n":46,"t":"是王在約旦平原、疏割和撒拉但中間的泥巴地鑄成的。","notes":[]},{"n":47,"t":"所羅門允許這一切器皿不過秤，因為所用的銅太多，重量無法計算。","notes":[]},{"n":48,"t":"所羅門又為耶和華的殿造了各樣的器皿：金壇和獻供餅的金供桌；","notes":[]},{"n":49,"t":"內殿前的純金燈臺，右邊五個，左邊五個，以及其上的花、燈盞、燈剪，都是金的；","notes":[]},{"n":50,"t":"純金的杯、鉗子、盤子、勺子 、火盆，以及聖殿的最裏面，就是至聖所的門樞和外殿的門樞，都是金的。","notes":[]},{"n":51,"t":"所羅門王做完了耶和華殿一切的工，就把他父親大衛分別為聖的金銀和器皿都帶來，放在耶和華殿的庫房裏。","notes":[],"heads":["殿工告竣"]}]},"8":{"heading":"接約櫃入殿","verses":[{"n":1,"t":"那時，所羅門召集以色列的長老、各支派的領袖和以色列人的族長到耶路撒冷，所羅門王那裏，要把耶和華的約櫃從大衛城，就是錫安，接上來。","notes":[]},{"n":2,"t":"以他念月，就是七月，在節期時，所有的以色列人都聚集到所羅門王那裏。","notes":[]},{"n":3,"t":"以色列眾長老一來到，祭司就抬起約櫃。","notes":[]},{"n":4,"t":"祭司和利未人將耶和華的約櫃請上來，又把會幕和會幕一切的聖器皿都帶上來。","notes":[]},{"n":5,"t":"所羅門王和聚集到他那裏的以色列全會眾一同在約櫃前獻牛羊為祭，多得不可勝數，無法計算。","notes":[]},{"n":6,"t":"祭司將耶和華的約櫃請進內殿，就是至聖所，安置在兩個基路伯的翅膀底下約櫃的地方。","notes":[]},{"n":7,"t":"基路伯張開翅膀在約櫃上面的地方，從上面遮住約櫃和抬櫃的槓。","notes":[]},{"n":8,"t":"這槓很長，從內殿前的聖所可以看見槓頭，從外面卻看不見。這槓直到今日還在那裏。","notes":[]},{"n":9,"t":"約櫃裏沒有別的，只有兩塊石版，就是以色列人出埃及地，耶和華與他們立約的時候，摩西在何烈山放在那裏的。","notes":[]},{"n":10,"t":"祭司從聖所出來的時候，有雲充滿耶和華的殿，","notes":[]},{"n":11,"t":"祭司因雲彩的緣故不能站立供職，因為耶和華的榮光充滿了耶和華的殿。","notes":[]},{"n":12,"t":"那時，所羅門說：「耶和華曾說要住在幽暗之處。","notes":["「耶和華...幽暗之處」：七十士譯本是「主曾安置太陽在天空，卻說要住在幽暗之處」；本句七十士譯本放在53節。"]},{"n":13,"t":"我的確為你建了一座雄偉的殿宇，作為你永遠居住的地方。」","notes":[]},{"n":14,"t":"王轉過臉來為以色列全會眾祝福，以色列全會眾都站立。","notes":[],"heads":["所羅門向百姓講話"]},{"n":15,"t":"所羅門說：「耶和華－以色列的神是應當稱頌的！因他親口向我父大衛應許的，也親手成就了；他曾說：","notes":[]},{"n":16,"t":"『自從那日我領我百姓以色列出埃及以來，我未曾在以色列各支派中選擇一城，在那裏為我的名建造殿宇，但我揀選大衛治理我的百姓以色列。』","notes":[]},{"n":17,"t":"我父大衛的心意是要為耶和華－以色列神的名建殿。","notes":[]},{"n":18,"t":"耶和華卻對我父大衛說：『你有心為我的名建殿，這心意是好的；","notes":[]},{"n":19,"t":"但你不可建殿，惟有你親生的兒子才可為我的名建殿。』","notes":[]},{"n":20,"t":"現在耶和華實現了他所應許的話，使我接續我父大衛坐以色列的王位，正如耶和華所說的，我也為耶和華－以色列神的名建造了這殿。","notes":[]},{"n":21,"t":"我也在那裏為約櫃預備一處。約櫃那裏有耶和華的約，就是他領我們列祖出埃及地的時候，與他們所立的約。」","notes":[]},{"n":22,"t":"所羅門當著以色列全會眾，站在耶和華的壇前，向天舉手，","notes":[],"heads":["所羅門的禱告"]},{"n":23,"t":"說：「耶和華－以色列的神啊，天上地下沒有神明可與你相比！你向那些盡心行在你面前的僕人守約施慈愛，","notes":[]},{"n":24,"t":"這約是你向你僕人大衛守的，是你應許他的。你親口應許，親手成就，正如今日一樣。","notes":[]},{"n":25,"t":"耶和華－以色列的神啊，你向你僕人我父大衛應許說：『你的子孫若謹慎自己的行為，在我面前行事像你所行的一樣，就不斷有人在我面前坐以色列的王位。』現在求你信守這話。","notes":[]},{"n":26,"t":"以色列的神啊，現在求你成就向你僕人我父大衛所應許的話。","notes":[]},{"n":27,"t":"「神果真住在地上嗎？看哪，天和天上的天尚且不足容納你，何況我所建的這殿呢？","notes":[]},{"n":28,"t":"惟求耶和華－我的神垂顧僕人的禱告祈求，俯聽僕人今日在你面前的祈禱呼求。","notes":[]},{"n":29,"t":"願你的眼目晝夜看顧這殿，就是你說要作為你名的居所；求你垂聽禱告，你僕人向此處的禱告。","notes":[]},{"n":30,"t":"你僕人和你百姓以色列向此處祈禱的時候，求你在你天上的居所垂聽，垂聽而赦免。","notes":[]},{"n":31,"t":"「人若得罪鄰舍，有人強迫他，要他起誓，他來到這殿，在你的壇前起誓，","notes":[]},{"n":32,"t":"求你在天上垂聽、處理，向你的僕人施行審判，定惡人有罪，照他所行的報應在他頭上；定義人為義，照他的義賞賜他。","notes":[]},{"n":33,"t":"「你的百姓以色列若得罪你，敗在仇敵面前，卻又歸向你，宣認你的名，在這殿裏向你祈求禱告，","notes":[]},{"n":34,"t":"求你在天上垂聽，赦免你百姓以色列的罪，使他們歸回你賜給他們列祖的地。","notes":[]},{"n":35,"t":"「你的百姓若得罪了你，你使天閉塞不下雨；他們若向此處禱告，宣認你的名，因你的懲罰而離開他們的罪，","notes":[]},{"n":36,"t":"求你在天上垂聽，赦免你僕人你百姓以色列的罪，將當行的善道教導他們，並降雨在你的地，就是你賜給你百姓為業之地。","notes":[]},{"n":37,"t":"「這地若有饑荒、瘟疫、焚風、霉爛、蝗蟲、螞蚱，或有仇敵圍困這地的城門，無論遭遇甚麼災禍疾病，","notes":["「焚風」或譯「蟲害」。","「這地的」：七十士譯本和其他古譯本是「任何一個」。"]},{"n":38,"t":"你的百姓以色列，或眾人或一人，內心知道有禍，向這殿舉手，無論祈求甚麼，禱告甚麼，","notes":[]},{"n":39,"t":"求你在天上你的居所垂聽、赦免、處理。因為你知道人心，惟有你知道世人的心，求你照各人所行的一切待他們，","notes":[]},{"n":40,"t":"使他們在你賜給我們列祖的土地上一生一世敬畏你。","notes":[]},{"n":41,"t":"「論到不屬你百姓以色列的外邦人，若為你的名從遠方而來，","notes":[]},{"n":42,"t":"他們因聽見你的大名和大能的手，以及伸出來的膀臂，來向這殿禱告，","notes":[]},{"n":43,"t":"求你在天上你的居所垂聽，照著外邦人向你所求的一切而行，使地上萬民都認識你的名，敬畏你，像你的百姓以色列一樣，又使他們知道我所建造的是稱為你名下的殿。","notes":[]},{"n":44,"t":"「你的百姓若奉你的派遣出去，無論往何處與仇敵爭戰，他們若向耶和華所選擇的城，以及我為你名所建造的這殿禱告，","notes":[]},{"n":45,"t":"求你在天上垂聽他們的禱告祈求，為他們伸張正義。","notes":[]},{"n":46,"t":"「你的百姓若得罪你，因為沒有人不犯罪，你向他們發怒，把他們交在仇敵面前，擄他們的人把他們帶到仇敵之地，或遠或近，","notes":[]},{"n":47,"t":"他們若在被擄之地那裏回心轉意，在擄掠者之地悔改，向你懇求說：『我們有罪了，我們悖逆了，我們作惡了』；","notes":[]},{"n":48,"t":"他們若在擄他們的仇敵之地盡心盡性歸向你，又向自己的地，就是你賜給他們列祖的地和你所選擇的城，以及我為你名所建造的這殿禱告，","notes":[]},{"n":49,"t":"求你在天上你的居所垂聽他們的禱告祈求，為他們伸張正義，","notes":[]},{"n":50,"t":"饒恕得罪你的子民，赦免他們向你所犯一切的過犯，使他們在擄他們的人面前蒙憐憫。","notes":[]},{"n":51,"t":"因為他們是你的子民，你的產業，是你從埃及，從鐵爐中領出來的。","notes":[]},{"n":52,"t":"願你的眼目看顧僕人和你百姓以色列的祈求；他們無論何時向你呼求，願你垂聽。","notes":[]},{"n":53,"t":"主耶和華啊，你將他們從地上萬民中分別出來作你的產業，是照著你領我們列祖出埃及的時候，藉你僕人摩西所應許的。」","notes":[]},{"n":54,"t":"所羅門在耶和華的壇前屈膝跪著，向天舉手；他在耶和華面前禱告祈求完畢的時候，就起來，","notes":[],"heads":["為民祝福"]},{"n":55,"t":"站著，大聲為以色列全會眾祝福，說：","notes":[]},{"n":56,"t":"「耶和華是應當稱頌的！因為他照著一切所應許的賜平安給他的百姓以色列，凡藉他僕人摩西應許賜福的話，一句都沒有落空。","notes":[]},{"n":57,"t":"願耶和華－我們的神與我們同在，像與我們列祖同在一樣，不撇下我們，不丟棄我們，","notes":[]},{"n":58,"t":"使我們的心歸向他，遵行他一切的道，謹守他吩咐我們列祖的誡命、律例、典章。","notes":[]},{"n":59,"t":"願我在耶和華面前祈求的這些話，晝夜靠近耶和華－我們的神，好讓他每日為他僕人和他百姓以色列伸張正義，","notes":[]},{"n":60,"t":"使地上的萬民都知道惟獨耶和華是神，沒有別的了。","notes":[]},{"n":61,"t":"所以你們當向耶和華－我們的神存純正的心，遵行他的律例，謹守他的誡命，如同今日一樣。」","notes":[]},{"n":62,"t":"王和全以色列一同在耶和華面前獻祭。","notes":[],"heads":["奉獻聖殿"]},{"n":63,"t":"所羅門向耶和華獻平安祭，二萬二千頭牛，十二萬隻羊。這樣，王和全以色列為耶和華的殿行了奉獻之禮。","notes":[]},{"n":64,"t":"當日，王因耶和華殿前的銅壇太小，容不下燔祭、素祭和平安祭牲的脂肪，就將耶和華殿前院子的中間分別為聖，在那裏獻燔祭、素祭和平安祭牲的脂肪。","notes":[]},{"n":65,"t":"那時所羅門守節，從哈馬口直到埃及溪谷的以色列眾人都與他同在一起，成了一個盛大的會，在耶和華－我們的神面前七日又七日，共十四日。","notes":[]},{"n":66,"t":"第八日，王遣散百姓；他們都為王祝福。他們為耶和華向他僕人大衛和他百姓以色列所施的一切恩惠都心中喜樂，愉快地各回自己的帳棚去了。","notes":[]}]},"9":{"heading":"耶和華再向所羅門顯現","verses":[{"n":1,"t":"所羅門建造耶和華的殿和王宮，以及一切所想要建造的都完畢了，","notes":[]},{"n":2,"t":"耶和華第二次向所羅門顯現，如先前在基遍向他顯現一樣。","notes":[]},{"n":3,"t":"耶和華對他說：「我已聽了你在我面前的禱告和祈求，將你所建的這殿分別為聖，使我的名永遠立在那裏；我的眼、我的心也必時常在那裏。","notes":[]},{"n":4,"t":"你若以純正的心和正直行在我面前，效法你父大衛所行的，遵行我一切所吩咐你的，謹守我的律例典章，","notes":[]},{"n":5,"t":"我就必堅固你在以色列國度的王位，直到永遠，正如我應許你父大衛說：『你的子孫必不斷有人坐以色列的王位。』","notes":[]},{"n":6,"t":"倘若你們和你們的子孫轉去不跟從我，不守我擺在你們面前的誡命律例，去事奉別神，敬拜它們，","notes":[]},{"n":7,"t":"我就必把以色列從我賜給他們的地上剪除，也必從我面前捨棄那為我名所分別為聖的殿，使以色列在萬民中成為笑柄，被人譏誚。","notes":[]},{"n":8,"t":"這殿雖然崇高，將來凡經過的人必驚訝，嗤笑，說：『耶和華為何向這地和這殿如此行呢？』","notes":["「雖然崇高」：有古譯本是「必成為廢墟」。"]},{"n":9,"t":"人必說：『因為此地的人離棄領他們祖先出埃及地的耶和華－他們的神，去親近別神，敬拜事奉它們，所以耶和華使這一切災禍臨到他們。』」","notes":[]},{"n":10,"t":"所羅門建造耶和華殿和王宮這兩座殿宇，用了二十年才完成。","notes":[],"heads":["所羅門跟希蘭訂約"]},{"n":11,"t":"推羅王希蘭曾照所羅門所要的資助他香柏木、松木和金子，所羅門王就把加利利地的二十座城給了希蘭。","notes":[]},{"n":12,"t":"希蘭從推羅出來，察看所羅門給他的城鎮，看不順眼，","notes":[]},{"n":13,"t":"就說：「我兄啊，你給我的是甚麼城鎮呢？」他就給這些城鎮起名叫迦步勒地，直到今日。","notes":["「迦步勒」意思是「沒有價值」。"]},{"n":14,"t":"希蘭曾給所羅門一百二十他連得金子。","notes":[]},{"n":15,"t":"所羅門王挑取服勞役的工人，為要建造耶和華的殿、自己的宮、米羅、耶路撒冷的城牆、夏瑣、米吉多和基色。","notes":["「米羅」是音譯，指「土堆的防禦工事」；本卷書下同。"],"heads":["所羅門其他政績"]},{"n":16,"t":"先前埃及王法老上來攻取基色，用火焚燒，殺了城內居住的迦南人，把城賜給他的女兒，就是所羅門的妻子，作為嫁妝。","notes":[]},{"n":17,"t":"所羅門建造基色、下伯‧和崙、","notes":[]},{"n":18,"t":"巴拉，和位於境內曠野的達莫。","notes":[]},{"n":19,"t":"所羅門建造一切的儲貨城、戰車城、戰馬城，以及他所想要建造的，在耶路撒冷、黎巴嫩和自己治理全國中的一切建設。","notes":[]},{"n":20,"t":"至於所有剩下的百姓，不屬以色列人的亞摩利人、赫人、比利洗人、希未人、耶布斯人，","notes":[]},{"n":21,"t":"那些以色列人在當地不能滅盡的人，所羅門徵召他們剩下的後代作服勞役的奴僕，直到今日。","notes":[]},{"n":22,"t":"惟有以色列人，所羅門不使他們作奴僕，而是作他的戰士、臣僕、官長、軍官、戰車長、騎兵長。","notes":[]},{"n":23,"t":"這些是所羅門工程的五百五十個監工，他們在百姓中監管作工的人。","notes":[]},{"n":24,"t":"法老的女兒從大衛城上到所羅門為她建造的宮裏。那時，所羅門才建造米羅。","notes":[]},{"n":25,"t":"所羅門每年三次在他為耶和華所築的壇上獻燔祭和平安祭，又在耶和華面前的壇上燒香。這樣，他完成了建殿。","notes":[]},{"n":26,"t":"所羅門王在以東地紅海邊，靠近以祿的以旬‧迦別製造船隻。","notes":[]},{"n":27,"t":"希蘭派他的僕人，就是熟悉航海的船員，與所羅門的僕人一同坐船航海。","notes":[]},{"n":28,"t":"他們到了俄斐，從那裏得了四百二十他連得金子，運到所羅門王那裏。","notes":[]}]},"10":{"heading":"示巴女王拜訪所羅門","verses":[{"n":1,"t":"示巴女王聽見所羅門因耶和華的名所得的名聲，就來要用難題考問所羅門。","notes":[]},{"n":2,"t":"她帶著很多的隨從來到耶路撒冷，有駱駝馱著香料、極多金子和寶石。她來到所羅門那裏，向他提出心中所有的問題。","notes":[]},{"n":3,"t":"所羅門回答了她所有的問題，沒有一個問題太難，王不能向她解答的。","notes":[]},{"n":4,"t":"示巴女王看見所羅門一切的智慧，和他所建造的宮殿，","notes":[]},{"n":5,"t":"席上的食物，坐著的群臣，侍立的僕人，他們的服裝，和他的司酒長，以及他在耶和華殿裏所獻的燔祭，就詫異得神不守舍。","notes":["「他在耶和華...燔祭」或譯「他上耶和華殿的臺階」。"]},{"n":6,"t":"她對王說：「我在本國所聽到的話，論到你的事和你的智慧是真的！","notes":[]},{"n":7,"t":"我本來不信那些話，及至我來親眼看見了，看哪，人所告訴我的還不到一半，你的智慧和你的福分超過我所聽見的傳聞。","notes":[]},{"n":8,"t":"你的人是有福的！你這些僕人常侍立在你面前、聽你智慧的話是有福的！","notes":["「你的人」：七十士譯本和其他古譯本是「你的后妃」。"]},{"n":9,"t":"耶和華－你的神是應當稱頌的！他喜愛你，使你坐以色列的王位，因為他永遠愛以色列，所以立你作王，使你秉公行義。」","notes":[]},{"n":10,"t":"於是，示巴女王把一百二十他連得金子、極多的香料和寶石送給所羅門王；送來的香料，從來沒有像示巴女王送給他的那麼多。","notes":[]},{"n":11,"t":"希蘭的船隻也從俄斐運了金子來，又從俄斐運了許多檀香木和寶石來。","notes":[]},{"n":12,"t":"王用檀香木為耶和華的殿和王宮做欄杆，又為歌唱的人做琴瑟。以後再沒有這樣的檀香木運進來，也再沒有人見過，直到如今。","notes":[]},{"n":13,"t":"所羅門王除了照自己的厚意餽贈示巴女王之外，凡她所提出的一切要求，所羅門王都送給她。於是女王和她臣僕轉回，到本國去了。","notes":[]},{"n":14,"t":"所羅門每年所得的金子，重六百六十六他連得；","notes":[],"heads":["所羅門的財富"]},{"n":15,"t":"另外還有來自商人和做生意的商品，以及阿拉伯諸王和各地省長的。","notes":["「商人」：原文直譯「商人的人」或「商人的稅金」；七十士譯本是「臣民的貢品」。"]},{"n":16,"t":"所羅門王用錘出來的金子打成二百面盾牌，每面盾牌用六百舍客勒金子；","notes":[]},{"n":17,"t":"又用錘出來的金子打成三百面小盾牌，每面小盾牌用三彌那金子。王把它們放在黎巴嫩林宮裏。","notes":[]},{"n":18,"t":"王又製造一個大的象牙寶座，包上純金。","notes":[]},{"n":19,"t":"寶座有六層臺階，座的後背是圓的，座位之處兩旁有扶手，靠近扶手有兩隻獅子站立。","notes":[]},{"n":20,"t":"六層臺階上有十二隻獅子站立，分站左邊和右邊；任何國度都沒有這樣做的。","notes":[]},{"n":21,"t":"所羅門王一切的飲器都是金的，黎巴嫩林宮裏所有的器皿都是純金的。在所羅門的日子，銀子算不了甚麼。","notes":[]},{"n":22,"t":"王有他施船隻與希蘭的船隻一同航海，他施船隻每三年一次把金、銀、象牙、猿猴、孔雀運回來。","notes":["「孔雀」或譯「狒狒」。"]},{"n":23,"t":"所羅門王的財寶與智慧勝過地上的眾王。","notes":[]},{"n":24,"t":"全地都求見所羅門的面，要聽神放在他心裏的智慧。","notes":[]},{"n":25,"t":"他們各帶貢物，就是銀器、金器、衣服、兵器、香料、馬、騾子，每年都有一定的數量。","notes":[]},{"n":26,"t":"所羅門聚集戰車騎兵；他有一千四百輛戰車，一萬二千名騎兵，安置在屯車城，在耶路撒冷的王那裏。","notes":[],"heads":["所羅門的兵力和財力"]},{"n":27,"t":"王在耶路撒冷使銀子多如石頭，香柏木多如謝非拉的桑樹。","notes":["「謝非拉」是音譯，意思是「低地」。"]},{"n":28,"t":"所羅門的馬是從埃及和科威運來的，是王的商人按著定價從科威買來的。","notes":["「埃及」不是南方的埃及，而是美索不達米亞北方的一國；下同。","「科威」可能是「基利亞」，是北方埃及的鄰國；下同。"]},{"n":29,"t":"從埃及進口的戰車，每輛六百舍客勒銀子，馬每匹一百五十舍客勒；赫人眾王和亞蘭諸王的戰車和馬，也是經由他們的手出口的。","notes":[]}]},"11":{"heading":"所羅門離棄神","verses":[{"n":1,"t":"所羅門王在法老的女兒之外，又寵愛許多外邦女子，就是摩押女子、亞捫女子、以東女子、西頓女子、赫人女子。","notes":[]},{"n":2,"t":"論到這些國的人，耶和華曾吩咐以色列人說：「你們不可跟他們通婚，他們也不可跟你們在一起，因為他們一定會誘惑你們的心去隨從他們的神明。」所羅門卻為了愛，緊緊跟從他們。","notes":[]},{"n":3,"t":"所羅門娶七百個公主，三百個妃嬪。這些妻妾誘惑他的心。","notes":[]},{"n":4,"t":"所羅門年老的時候，他的妻妾誘惑他的心去隨從別神，不像他父親大衛以純正的心順服耶和華－他的神。","notes":[]},{"n":5,"t":"所羅門隨從西頓人的女神亞斯她錄和亞捫人可憎的米勒公。","notes":[]},{"n":6,"t":"所羅門行耶和華眼中看為惡的事，不像他父親大衛專心順從耶和華。","notes":[]},{"n":7,"t":"那時，所羅門為摩押可憎的基抹和亞捫人可憎的摩洛，在耶路撒冷對面的山上建造丘壇。","notes":[]},{"n":8,"t":"他為所有的妻妾，就是那些向自己神明燒香獻祭的外邦女子，也是這樣做。","notes":[]},{"n":9,"t":"耶和華向所羅門發怒，因為他的心偏離了向他顯現兩次的耶和華－以色列的神。","notes":[]},{"n":10,"t":"耶和華曾吩咐他這件事，不可隨從別神，他卻沒有遵守耶和華所吩咐的。","notes":[]},{"n":11,"t":"所以耶和華對他說：「你既然是這樣，不遵守我所吩咐你守的約和律例，我必定把國度撕裂離開你，將它賜給你的大臣。","notes":[]},{"n":12,"t":"然而，因你父親大衛的緣故，我不在你的日子行這事，而要從你兒子的手中撕裂這國。","notes":[]},{"n":13,"t":"只是我不撕裂全國，卻要因我僕人大衛和我所選擇的耶路撒冷，保留一個支派給你的兒子。」","notes":[]},{"n":14,"t":"耶和華使以東人哈達興起，作所羅門的敵人；他是以東王的後裔。","notes":[],"heads":["所羅門的敵人"]},{"n":15,"t":"大衛在以東的時候，約押元帥上去埋葬陣亡的人，殺了以東所有的男丁。","notes":[]},{"n":16,"t":"約押和以色列眾人在以東住了六個月，直到把以東的男丁盡都剪除。","notes":[]},{"n":17,"t":"那時哈達還是幼童；他和他父親的臣僕，以及幾個以東人逃往埃及。","notes":[]},{"n":18,"t":"他們從米甸起行，到了巴蘭，再從巴蘭帶著幾個人來到埃及，到埃及王法老那裏。法老給他房屋，吩咐給他糧食，又把地賜給他。","notes":[]},{"n":19,"t":"哈達在法老眼前大蒙恩寵，法老就把王后答比匿的妹妹嫁給他。","notes":[]},{"n":20,"t":"答比匿的妹妹給哈達生了一個兒子，叫基努拔。答比匿使基努拔在法老的宮裏斷奶，基努拔就與法老的眾子一同住在法老的宮裏。","notes":[]},{"n":21,"t":"哈達在埃及聽見大衛與他祖先同睡，約押元帥也死了，就對法老說：「請你讓我走，我要回本國去。」","notes":[]},{"n":22,"t":"法老對他說：「你在我這裏有甚麼缺乏？看哪，你竟想要回你本國去！」他說：「我沒有缺乏甚麼，只是懇求王准我回去。」","notes":[]},{"n":23,"t":"神又使以利亞大的兒子利遜興起，作所羅門的敵人。他曾逃避主人瑣巴王哈大底謝。","notes":[]},{"n":24,"t":"大衛擊殺瑣巴人的時候，利遜召集了一群人，自己作他們的領袖。他們往大馬士革，住在那裏，在大馬士革建立王國。","notes":[]},{"n":25,"t":"所羅門活著的時候，除了哈達為患之外，利遜也作以色列的敵人。他憎恨以色列，作了亞蘭人的王。","notes":[]},{"n":26,"t":"尼八的兒子耶羅波安也舉起手來攻擊王。他是所羅門的臣僕，以法蓮支派的洗利達人；他母親是個寡婦，名叫洗魯阿。","notes":[],"heads":["神給耶羅波安的應許"]},{"n":27,"t":"他舉手攻擊王是因先前所羅門建造米羅，修補他父親大衛城缺口的這件事。","notes":[]},{"n":28,"t":"耶羅波安是個大有才能的人。所羅門見這青年殷勤，就派他監管約瑟家所有服勞役的工人。","notes":[]},{"n":29,"t":"那時，耶羅波安出了耶路撒冷，示羅人亞希雅先知在路上遇見他；亞希雅身上穿著一件新衣。田野中只有他們二人，沒有其他的人。","notes":[]},{"n":30,"t":"亞希雅拿起穿在自己身上的新衣，把它撕成十二片，","notes":[]},{"n":31,"t":"對耶羅波安說：「你可以拿十片。耶和華－以色列的神如此說：『看哪，我必從所羅門手裏撕裂這國，把十個支派賜給你。","notes":[]},{"n":32,"t":"我因我僕人大衛和我在以色列眾支派中所選擇的耶路撒冷城的緣故，仍為所羅門留一個支派。","notes":[]},{"n":33,"t":"因為他們離棄我，敬拜西頓人的女神亞斯她錄、摩押的神明基抹和亞捫人的神明米勒公，沒有像他父親大衛一樣遵從我的道，行我眼中看為正的事，守我的律例典章。","notes":["「他們」：七十士譯本是「他」。"]},{"n":34,"t":"但我不從他手裏奪走整個國家，卻使他在活著的日子作君王，是因我所揀選的僕人大衛遵守我的誡命律例。","notes":[]},{"n":35,"t":"我必從他兒子手裏將王國奪走，賜給你十個支派，","notes":[]},{"n":36,"t":"只留一個支派給他的兒子，使我僕人大衛在我所選擇立我名的耶路撒冷城那裏，在我面前常有燈光。","notes":[]},{"n":37,"t":"我選你，使你照你心裏一切所願的作王，成為以色列的王。","notes":[]},{"n":38,"t":"你若聽從我一切所吩咐你的，遵行我的道，行我眼中看為正的事，謹守我的律例誡命，像我僕人大衛所行的，我就與你同在，為你立堅固的家，像我為大衛所立的一樣，將以色列賜給你。","notes":[]},{"n":39,"t":"我必因這事使大衛的後裔遭受患難，但不是永遠的。』」","notes":[]},{"n":40,"t":"所羅門想要殺耶羅波安，耶羅波安起身逃往埃及。他到了埃及王示撒那裏，就住在埃及，直到所羅門死了。","notes":[]},{"n":41,"t":"所羅門其餘的事，凡他所做的和他的智慧，不都寫在《所羅門記》上嗎？","notes":[],"heads":["所羅門去世"]},{"n":42,"t":"所羅門在耶路撒冷作全以色列的王四十年。","notes":[]},{"n":43,"t":"所羅門與他祖先同睡，葬在他父親大衛的城裏，他兒子羅波安接續他作王。","notes":[]}]},"12":{"heading":"北方支派的反叛","verses":[{"n":1,"t":"羅波安往示劍去，因以色列眾人都到了示劍，要立他作王。","notes":[]},{"n":2,"t":"尼八的兒子耶羅波安先前躲避所羅門王，逃往埃及，住在那裏。他還在埃及，聽見了這事，","notes":["「住在那裏...這事」：七十士譯本和其他古譯本是「他還在埃及，聽見了這事，就從埃及回來」。"]},{"n":3,"t":"以色列人派人去請他來。耶羅波安就和以色列全會眾來，與羅波安談話，說：","notes":[]},{"n":4,"t":"「你父親使我們負重軛，現在求你減輕你父親所加給我們的苦工和重軛，我們就服事你。」","notes":[]},{"n":5,"t":"羅波安對他們說：「你們走吧，過三天再來見我。」百姓就走了。","notes":[]},{"n":6,"t":"羅波安的父親所羅門在世的日子，有侍立在他面前的長者，羅波安王和他們商議，說：「你們出個主意，好把話帶回給這百姓。」","notes":[]},{"n":7,"t":"他們對他說：「現在王若像僕人一樣服事這百姓，用好話回覆他們，他們就永遠作王的僕人了。」","notes":[]},{"n":8,"t":"王不採納長者給他出的主意，卻和那些與他一同長大、在他面前侍立的年輕人商議。","notes":[]},{"n":9,"t":"他對他們說：「這百姓對我說：『你父親使我們負重軛，求你減輕一些。』你們出個甚麼主意，我們好把話帶回給他們。」","notes":[]},{"n":10,"t":"那些與他一同長大的年輕人對他說：「這百姓對王說：『你父親使我們負重軛，求你給我們減輕一些。』王要對他們如此說：『我的小指頭比我父親的腰還粗呢！","notes":[]},{"n":11,"t":"我父親使你們負重軛，現在我必使你們負更重的軛！我父親用鞭子懲罰你們，我要用蠍子懲罰你們！』」","notes":[]},{"n":12,"t":"耶羅波安和眾百姓遵照王所說「你們第三天再來見我」的話，第三天來到羅波安那裏。","notes":[]},{"n":13,"t":"王嚴厲地回答百姓，不採納長者給他出的主意。","notes":[]},{"n":14,"t":"他照著年輕人所出的主意對他們說：「我父親使你們負重軛，我必使你們負更重的軛！我父親用鞭子懲罰你們，我卻要用蠍子懲罰你們！」","notes":[]},{"n":15,"t":"王不依從百姓，因這事件是出於耶和華，為要應驗耶和華藉示羅人亞希雅對尼八的兒子耶羅波安所說的話。","notes":[]},{"n":16,"t":"以色列眾人見王不依從他們，百姓就回話給王，說：「我們在大衛中有甚麼份呢？我們在耶西的兒子中沒有產業！以色列啊，回你的帳棚去吧！大衛啊，現在你顧自己的家吧！」於是，以色列人都回自己的帳棚去了；","notes":[]},{"n":17,"t":"至於住猶大城鎮的以色列人，羅波安仍作他們的王。","notes":[]},{"n":18,"t":"羅波安王派監管勞役的亞多蘭去，以色列眾人用石頭打他，他就死了。羅波安王急忙上車，逃回耶路撒冷去了。","notes":[]},{"n":19,"t":"這樣，以色列背叛大衛家，直到今日。","notes":[]},{"n":20,"t":"以色列眾人聽見耶羅波安回來了，就派人去請他到會眾那裏，立他作全以色列的王。除了猶大支派，沒有跟從大衛家的。","notes":[]},{"n":21,"t":"羅波安來到耶路撒冷，召集了猶大全家和便雅憫支派的人共十八萬，都是精選的戰士，要與以色列家打仗，好將王國奪回，歸所羅門的兒子羅波安。","notes":[],"heads":["示瑪雅的預言"]},{"n":22,"t":"但神的話臨到神人示瑪雅，說：","notes":[]},{"n":23,"t":"「你去告訴所羅門的兒子猶大王羅波安，猶大和便雅憫全家，以及其餘的百姓，說：","notes":[]},{"n":24,"t":"『耶和華如此說：你們不可上去與你們的弟兄以色列人打仗。你們各自回家去吧！因為這事是出於我。』」眾人就聽從耶和華的話，遵照耶和華的話回去了。","notes":[]},{"n":25,"t":"耶羅波安在以法蓮山區建了示劍，住在其中，又從示劍出去，建了毗努伊勒。","notes":[],"heads":["耶羅波安離棄神"]},{"n":26,"t":"耶羅波安心裏說：「現在，這國恐怕仍會歸大衛家；","notes":[]},{"n":27,"t":"這百姓若上耶路撒冷去，在耶和華的殿裏獻祭，他們的心必歸向他們的主猶大王羅波安。他們會殺了我，仍歸猶大王羅波安。」","notes":[]},{"n":28,"t":"耶羅波安王就籌劃，鑄造了兩個金牛犢，對眾百姓說：「你們上耶路撒冷去實在夠久了。以色列啊，看哪，這是領你出埃及地的神明。」","notes":[]},{"n":29,"t":"他把一個安置在伯特利，另一個安置在但。","notes":[]},{"n":30,"t":"這事使百姓陷入罪裏，因為他們甚至到但去拜那牛犢。","notes":[]},{"n":31,"t":"耶羅波安在一些丘壇建神殿，立不屬利未人的平民百姓為祭司。","notes":[]},{"n":32,"t":"耶羅波安定八月十五日為節期，像在猶大的節期一樣，自己上壇獻祭。他在伯特利這樣做，向他所鑄的牛犢獻祭，又把他所立丘壇的祭司安置在伯特利。","notes":[],"heads":["在伯特利的敬拜被定罪"]},{"n":33,"t":"他在八月十五日，就是他自己心中所定的月份，在伯特利上到自己所造的祭壇；他為以色列人定了一個節期，親自上壇燒香。","notes":[]}]},"13":{"heading":"伯特利的老先知","verses":[{"n":1,"t":"看哪，有一個神人遵照耶和華的話從猶大來到伯特利。耶羅波安正站在壇旁燒香；","notes":[]},{"n":2,"t":"神人遵照耶和華的話向壇呼叫，說：「壇哪，壇哪！耶和華如此說：『看哪，大衛家必生一個兒子，名叫約西亞，他必將在你上面燒香的丘壇祭司，宰殺在你上面，人的骨頭也必燒在你上面。』」","notes":[]},{"n":3,"t":"當日，神人設個預兆，說：「這是耶和華說的預兆：『看哪，這壇必破裂，壇上的灰必傾倒出來。』」","notes":[]},{"n":4,"t":"耶羅波安王聽見神人向伯特利的壇呼叫的話，就從壇上伸手，說：「拿住他！」王向神人所伸的手卻萎縮了，不能彎回。","notes":[]},{"n":5,"t":"壇也破裂了，壇上的灰傾倒出來，正如神人遵照耶和華的話所設的預兆。","notes":[]},{"n":6,"t":"王對神人說：「請你為我禱告，向耶和華－你的神懇求恩惠，使我的手復原。」於是神人向耶和華懇求，王的手就復原了，如平常一樣。","notes":[]},{"n":7,"t":"王對神人說：「請你跟我回宮，讓你恢復心力，我必給你賞賜。」","notes":[]},{"n":8,"t":"神人對王說：「你就是把你一半的王宮給我，我也不跟你進去，也不在這地方吃飯喝水，","notes":[]},{"n":9,"t":"因為耶和華的話這樣吩咐我說：『不可吃飯喝水，也不可從你去的原路回來。』」","notes":[]},{"n":10,"t":"於是神人從別的路回去，不從他到伯特利來的原路回去。","notes":[]},{"n":11,"t":"有一個老先知住在伯特利，他的兒子來，把神人當日在伯特利所做的一切事和他向王所說的話，都告訴了父親。","notes":[]},{"n":12,"t":"父親對他們說：「神人從哪條路去了呢？」他的兒子都看到從猶大來的神人所去的路。","notes":["「看到」：七十士譯本是「指給他看」。"]},{"n":13,"t":"老先知吩咐兒子說：「你們為我備驢。」他們備好了驢，他就騎上，","notes":[]},{"n":14,"t":"去追神人，遇見神人坐在橡樹底下，就對他說：「你是不是從猶大來的神人？」他說：「是我。」","notes":[]},{"n":15,"t":"老先知對他說：「請你跟我一起回家吃飯。」","notes":[]},{"n":16,"t":"神人說：「我不能跟你回去，與你同行，也不能在這地方跟你一起吃飯喝水，","notes":[]},{"n":17,"t":"因為有耶和華的話吩咐我說：『你在那裏不可吃飯喝水，也不可從你去的原路回來。』」","notes":[]},{"n":18,"t":"老先知對他說：「我也是先知，和你一樣。有天使遵照耶和華的話對我說：『你去帶他一同回你的家，給他吃飯喝水。』」老先知在欺騙他。","notes":[]},{"n":19,"t":"於是神人跟老先知回去，在他家裏吃飯喝水。","notes":[]},{"n":20,"t":"他們坐席的時候，耶和華的話臨到那帶神人回來的先知，","notes":[]},{"n":21,"t":"他就對從猶大來的神人宣告說：「耶和華如此說：『你既違背耶和華的指示，不遵守耶和華－你神的命令，","notes":[]},{"n":22,"t":"反倒回來，在耶和華禁止你吃飯喝水的地方吃了飯喝了水，因此你的屍體必不得葬在你祖先的墳墓裏。』」","notes":[]},{"n":23,"t":"神人吃喝完了，老先知為他帶回來的先知備驢。","notes":[]},{"n":24,"t":"神人就去了，在路上有隻獅子遇見他，把他咬死。他的屍體倒在路上，驢站在屍體旁邊，獅子也站在屍體旁邊。","notes":[]},{"n":25,"t":"看哪，有人經過，看見屍體倒在路上，獅子站在屍體旁邊，就來到老先知所住的城裏述說這事。","notes":[]},{"n":26,"t":"那帶神人回來的先知聽見了，就說：「這是那違背了耶和華指示的神人，所以耶和華把他交給獅子；獅子撕裂他，咬死他，正如耶和華對他說的話。」","notes":[]},{"n":27,"t":"老先知吩咐他兒子說：「你們為我備驢。」他們就備了驢。","notes":[]},{"n":28,"t":"他去了，發現神人的屍體倒在路上，驢和獅子站在屍體旁邊，獅子卻沒有吃屍體，也沒有撕裂驢。","notes":[]},{"n":29,"t":"老先知把神人的屍體抬起，馱在驢上，帶回自己的城裏，要為他哀哭，為他安葬。","notes":[]},{"n":30,"t":"老先知把屍體葬在自己的墳裏，為他哀哭，說：「哀哉！我的弟兄啊！」","notes":[]},{"n":31,"t":"安葬之後，老先知對他兒子說：「我死了，你們要把我葬在神人所葬的墳裏，使我的屍骨在他的屍骨旁邊，","notes":[]},{"n":32,"t":"因為他遵照耶和華的話，指著伯特利的壇和撒瑪利亞各城丘壇神殿所宣告的話必定應驗。」","notes":[]},{"n":33,"t":"這事以後，耶羅波安仍不離開他的惡道，立平民百姓為丘壇的祭司；凡願意的，他都分別為聖，立為丘壇的祭司。","notes":[],"heads":["耶羅波安的嚴重罪行"]},{"n":34,"t":"這事使耶羅波安的家陷入罪裏，甚至他的家被剪除，從地面上消滅了。","notes":[]}]},"14":{"heading":"耶羅波安的兒子去世","verses":[{"n":1,"t":"那時，耶羅波安的兒子亞比雅病了。","notes":[]},{"n":2,"t":"耶羅波安對他的妻子說：「你起來改裝，使人認不出你是耶羅波安的妻子。你往示羅去，看哪，那裏有先知亞希雅，他曾告訴我說，你必作這百姓的王。","notes":[]},{"n":3,"t":"現在你手裏要帶十個餅、幾個薄餅和一瓶蜜到他那裏去，他必告訴你，孩子會怎樣。」","notes":[]},{"n":4,"t":"耶羅波安的妻子就照樣做，起身往示羅去，到了亞希雅的家。亞希雅因年紀老邁，兩眼發直，不能看見。","notes":[]},{"n":5,"t":"耶和華對亞希雅說：「看哪，耶羅波安的妻子來問你她兒子的事，因她兒子病了，你當如此如此告訴她。她進來的時候會扮成別的婦人。」","notes":[]},{"n":6,"t":"她剛進門，亞希雅聽見她的腳步聲，就說：「耶羅波安的妻子，進來吧！你為何扮成別的婦人呢？我奉差遣將凶信告訴你。","notes":[]},{"n":7,"t":"你回去告訴耶羅波安說：『耶和華－以色列的神如此說：我從百姓中提拔了你，立你作我百姓以色列的君王，","notes":[]},{"n":8,"t":"將大衛家的國撕裂，賜給你，你卻不效法我僕人大衛，遵守我的誡命，全心順從我，行我眼中看為正的事。","notes":[]},{"n":9,"t":"你反倒行惡，比在你之前所有的人更嚴重；你離開了我，為自己立了別神，鑄了偶像，惹我發怒，將我丟在背後。","notes":[]},{"n":10,"t":"因此，看哪，我必使災禍臨到耶羅波安的家，把屬耶羅波安的男丁，無論是奴役的、自由的，都從以色列中剪除。我必除滅耶羅波安的家，如同人掃除糞土，直到消滅。","notes":[]},{"n":11,"t":"凡屬耶羅波安的人，死在城中的必被狗吃，死在田野的必被空中的鳥吃。這是耶和華說的。』","notes":[]},{"n":12,"t":"你起身回家去吧！你的腳一進城，孩子就死了。","notes":[]},{"n":13,"t":"以色列眾人必為他哀哭，為他安葬。凡屬耶羅波安的人，只有他可以葬入墳墓，因為在耶羅波安的家中，只有他向耶和華－以色列的神表現出好的行為。","notes":[]},{"n":14,"t":"耶和華必另立一王治理以色列，這一天，他必剪除耶羅波安的家；甚麼時候呢？現在就是了。","notes":[]},{"n":15,"t":"耶和華必擊打以色列，使他們搖動，像水中的蘆葦一樣，又將他們從耶和華賜給他們列祖的美地上拔出來，分散在大河那邊，因為他們造了亞舍拉，惹耶和華發怒。","notes":[]},{"n":16,"t":"因耶羅波安所犯的罪，又因他使以色列陷入罪裏，耶和華必將以色列交出來。」","notes":[]},{"n":17,"t":"耶羅波安的妻子起身回去，到了得撒，剛到門檻，孩子就死了。","notes":[]},{"n":18,"t":"以色列眾人為他安葬，為他哀哭，正如耶和華藉他僕人亞希雅先知所說的話。","notes":[]},{"n":19,"t":"耶羅波安其餘的事，他怎樣打仗，怎樣作王，看哪，都寫在《以色列諸王記》上。","notes":[],"heads":["耶羅波安去世"]},{"n":20,"t":"耶羅波安作王二十二年，就與他祖先同睡，他兒子拿答接續他作王。","notes":[]},{"n":21,"t":"所羅門的兒子羅波安作猶大王。他登基的時候年四十一歲，在耶路撒冷，就是耶和華從以色列眾支派中所選擇立他名的城，作王十七年。羅波安的母親名叫拿瑪，是亞捫人。","notes":[],"heads":["猶大王羅波安"]},{"n":22,"t":"猶大人行耶和華眼中看為惡的事，以所犯的罪惹動他的妒忌，比他們的祖先所犯的一切更嚴重。","notes":[]},{"n":23,"t":"因為他們在各高岡上，各青翠樹下築丘壇，立柱像和亞舍拉。","notes":[]},{"n":24,"t":"國中也有男的廟妓。他們效法耶和華在以色列人面前所趕出的外邦人，行一切可憎惡的事。","notes":[]},{"n":25,"t":"羅波安王第五年，埃及王示撒上來攻打耶路撒冷，","notes":[]},{"n":26,"t":"奪了耶和華殿和王宮裏的寶物，盡都帶走，又奪走所羅門製造的一切金盾牌。","notes":[]},{"n":27,"t":"羅波安王製造銅盾牌代替那些金盾牌，交給看守王宮宮門的護衛長看管。","notes":[]},{"n":28,"t":"每逢王進耶和華的殿，護衛兵就舉起這些盾牌；隨後仍將盾牌送回護衛室。","notes":[]},{"n":29,"t":"羅波安其餘的事，凡他所做的，不都寫在《猶大列王記》上嗎？","notes":[]},{"n":30,"t":"羅波安與耶羅波安時常交戰。","notes":[]},{"n":31,"t":"羅波安與他祖先同睡，與他祖先同葬在大衛城。他母親名叫拿瑪，是亞捫人，他兒子亞比央接續他作王。","notes":["「亞比央」又名「亞比雅」，本卷書下同；參代上3．10，代下12．16。"]}]},"15":{"heading":"猶大王亞比央","verses":[{"n":1,"t":"尼八的兒子耶羅波安王十八年，亞比央登基作猶大王，","notes":[]},{"n":2,"t":"在耶路撒冷作王三年。他母親名叫瑪迦，是押沙龍的女兒。","notes":[]},{"n":3,"t":"亞比央行他父親從前所犯一切的罪，他的心不像他曾祖父大衛以純正的心順服耶和華－他的神。","notes":[]},{"n":4,"t":"然而耶和華－他的神因大衛的緣故，仍使大衛在耶路撒冷有燈光，立他兒子接續他作王，又堅立耶路撒冷。","notes":[]},{"n":5,"t":"因為大衛除了赫人烏利亞那件事，都行耶和華眼中看為正的事，一生沒有違背耶和華一切所吩咐的。","notes":[]},{"n":6,"t":"羅波安在世的日子常與耶羅波安交戰。","notes":[]},{"n":7,"t":"亞比央其餘的事，凡他所做的，不都寫在《猶大列王記》上嗎？亞比央常與耶羅波安交戰。","notes":[]},{"n":8,"t":"亞比央與他祖先同睡，葬在大衛城，他兒子亞撒接續他作王。","notes":[]},{"n":9,"t":"以色列王耶羅波安第二十年，亞撒登基作猶大王，","notes":[],"heads":["猶大王亞撒"]},{"n":10,"t":"在耶路撒冷作王四十一年。他祖母名叫瑪迦，是押沙龍的女兒。","notes":[]},{"n":11,"t":"亞撒效法他的高祖父大衛行耶和華眼中看為正的事，","notes":[]},{"n":12,"t":"從國中除去男的廟妓，又除掉他祖先所造的一切偶像。","notes":[]},{"n":13,"t":"他甚至廢了他祖母瑪迦太后的位，因瑪迦造了可憎的亞舍拉。亞撒砍下她的偶像，在汲淪溪邊燒了，","notes":[]},{"n":14,"t":"只是丘壇還沒有廢去。亞撒一生向耶和華存純正的心。","notes":[]},{"n":15,"t":"亞撒將他父親所分別為聖與自己所分別為聖的金銀和器皿都奉到耶和華的殿裏。","notes":[]},{"n":16,"t":"亞撒和以色列王巴沙在世的日子常常交戰。","notes":[]},{"n":17,"t":"以色列王巴沙上來攻擊猶大，修築拉瑪，不許人從猶大王亞撒那裏出入。","notes":[]},{"n":18,"t":"於是亞撒把耶和華殿和王宮府庫裏所剩下的金銀都交在他臣僕手中，派他們到住在大馬士革的亞蘭王，就是希旬的孫子，他伯利門的兒子便‧哈達那裏去，說：","notes":[]},{"n":19,"t":"「你父曾與我父立約，我與你也要這樣立約。看哪，我把金銀送給你作禮物，請你廢掉你與以色列王巴沙所立的約，使他從我這裏撤退。」","notes":[]},{"n":20,"t":"便‧哈達聽從了亞撒王，就派遣他的軍官去攻打以色列的城鎮，攻下了以雲、但、亞伯‧伯‧瑪迦、全基尼烈、拿弗他利全地。","notes":[]},{"n":21,"t":"巴沙聽見了，就停工不修築拉瑪，仍住在得撒。","notes":[]},{"n":22,"t":"於是亞撒王向猶大眾人宣佈，不准任何人推辭，吩咐他們運走巴沙修築拉瑪所用的石頭和木料。亞撒王用它們來修築便雅憫的迦巴和米斯巴。","notes":[]},{"n":23,"t":"亞撒其餘的事，他英勇的事蹟，凡他所做的，以及他所建築的城鎮，不都寫在《猶大列王記》上嗎？只是亞撒年老的時候患有腳疾。","notes":[]},{"n":24,"t":"亞撒與他祖先同睡，與他祖先同葬在大衛城，他兒子約沙法接續他作王。","notes":[]},{"n":25,"t":"猶大王亞撒第二年，耶羅波安的兒子拿答登基作以色列王二年，","notes":[],"heads":["以色列王拿答"]},{"n":26,"t":"拿答行耶和華眼中看為惡的事，行他父親所行的道，犯他父親使以色列陷入罪裏的那罪。","notes":[]},{"n":27,"t":"以薩迦人亞希雅的兒子巴沙背叛拿答，在非利士人的基比頓殺了他，那時拿答和以色列眾人正圍困基比頓。","notes":[],"heads":["以色列王巴沙"]},{"n":28,"t":"猶大王亞撒第三年，巴沙殺了拿答，篡了他的位。","notes":[]},{"n":29,"t":"巴沙一作王就殺了耶羅波安全家，耶羅波安家凡有氣息的，一個也沒有留下，都殺滅了，正如耶和華藉他僕人示羅人亞希雅所說的話。","notes":[]},{"n":30,"t":"這是因為耶羅波安所犯的罪，他使以色列陷入罪裏，激怒了耶和華－以色列的神。","notes":[]},{"n":31,"t":"拿答其餘的事，凡他所做的，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":32,"t":"亞撒和以色列王巴沙在世的日子常常交戰。","notes":[]},{"n":33,"t":"猶大王亞撒第三年，亞希雅的兒子巴沙在得撒登基，作全以色列的王二十四年。","notes":[]},{"n":34,"t":"他行耶和華眼中看為惡的事，行耶羅波安所行的道，犯他使以色列陷入罪裏的那罪。","notes":[]}]},"16":{"heading":"以色列王以拉","verses":[{"n":1,"t":"耶和華的話臨到哈拿尼的兒子耶戶，責備巴沙說：","notes":[]},{"n":2,"t":"「我既從塵埃中提拔你，立你作我百姓以色列的君王，你竟行耶羅波安所行的道，使我的百姓以色列陷入罪裏，以他們的罪惹我發怒，","notes":[]},{"n":3,"t":"看哪，我必除盡巴沙和他的家，使你的家像尼八的兒子耶羅波安的家一樣。","notes":[]},{"n":4,"t":"凡屬巴沙的人，死在城中的必被狗吃，死在田野的必被空中的鳥吃。」","notes":[]},{"n":5,"t":"巴沙其餘的事，凡他所做的和他英勇的事蹟，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":6,"t":"巴沙與他祖先同睡，葬在得撒，他兒子以拉接續他作王。","notes":[]},{"n":7,"t":"耶和華的話臨到哈拿尼的兒子耶戶先知，責備巴沙和他的家，因他行耶和華眼中看為惡的一切事，以他手所做的惹耶和華發怒，像耶羅波安的家一樣，又因他殺了耶羅波安全家。","notes":[]},{"n":8,"t":"猶大王亞撒第二十六年，巴沙的兒子以拉在得撒登基，作以色列王二年。","notes":[]},{"n":9,"t":"他的大臣心利，就是管理他一半戰車的軍官背叛他。當他在得撒，在王宮的管家亞雜家裏喝醉的時候，","notes":[]},{"n":10,"t":"心利進去擊殺他，把他殺死，篡了他的位。這是猶大王亞撒第二十七年的事。","notes":[]},{"n":11,"t":"心利一坐上王位就殺了巴沙全家，連他的親屬和朋友，一個男丁也沒有留下。","notes":[]},{"n":12,"t":"心利滅絕巴沙全家，正如耶和華藉耶戶先知責備巴沙的話。","notes":[]},{"n":13,"t":"這是因為巴沙和他兒子以拉的一切罪，就是他們使以色列陷入罪裏的那罪，以虛無的神明惹耶和華－以色列的神發怒。","notes":["「虛無的神明」：原文是「虛無」；26節同。"]},{"n":14,"t":"以拉其餘的事，凡他所做的，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":15,"t":"猶大王亞撒第二十七年，心利在得撒作王七日。那時軍兵正安營圍攻非利士人的基比頓。","notes":[],"heads":["以色列王心利"]},{"n":16,"t":"軍兵在營中聽說心利已經背叛，殺了王，以色列眾人當日就在營中立暗利元帥作以色列王。","notes":[]},{"n":17,"t":"暗利率領以色列眾人，從基比頓上去，圍困得撒。","notes":[]},{"n":18,"t":"心利見城被攻陷，就進了王宮的堡壘，放火焚燒宮殿，自焚而死。","notes":[]},{"n":19,"t":"這是因為他犯罪，行耶和華眼中看為惡的事，行耶羅波安所行的道，犯他使以色列陷入罪裏的那罪。","notes":[]},{"n":20,"t":"心利其餘的事和他背叛的事，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":21,"t":"那時，以色列百姓分為兩半：一半隨從基納的兒子提比尼，要擁立他作王；另一半隨從暗利。","notes":[],"heads":["以色列王暗利"]},{"n":22,"t":"但隨從暗利的百姓勝過隨從基納兒子提比尼的百姓。提比尼死了，暗利就作了王。","notes":[]},{"n":23,"t":"猶大王亞撒第三十一年，暗利登基作以色列王十二年；他在得撒作王六年。","notes":[]},{"n":24,"t":"暗利用二他連得銀子向撒瑪買了撒瑪利亞山，在山上建城，按著山的原主撒瑪的名，給所建的城起名叫撒瑪利亞。","notes":[]},{"n":25,"t":"暗利行耶和華眼中看為惡的事，比他以前所有的王作惡更嚴重。","notes":[]},{"n":26,"t":"因為他行了尼八的兒子耶羅波安所行的道，犯他使以色列陷入罪裏的那罪，以虛無的神明惹耶和華－以色列的神發怒。","notes":[]},{"n":27,"t":"暗利其餘的事，他所做的和所顯出的英勇事蹟，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":28,"t":"暗利與他祖先同睡，葬在撒瑪利亞，他兒子亞哈接續他作王。","notes":[]},{"n":29,"t":"猶大王亞撒第三十八年，暗利的兒子亞哈登基作以色列王。暗利的兒子亞哈在撒瑪利亞作以色列王二十二年。","notes":[],"heads":["以色列王亞哈"]},{"n":30,"t":"暗利的兒子亞哈行耶和華眼中看為惡的事，比他以前所有的王更嚴重。","notes":[]},{"n":31,"t":"他犯了尼八的兒子耶羅波安所犯的罪，還當作是小事，又娶了西頓王謁巴力的女兒耶洗別為妻，去事奉巴力，敬拜它，","notes":[]},{"n":32,"t":"又在撒瑪利亞建巴力廟，在廟裏為巴力築壇。","notes":[]},{"n":33,"t":"亞哈又造亞舍拉，他所做的惹耶和華－以色列的神發怒，比他以前所有的以色列王更嚴重。","notes":[]},{"n":34,"t":"亞哈的日子，伯特利人希伊勒重修耶利哥。立根基的時候，他喪了長子亞比蘭；安門的時候，他喪了幼子西割，正如耶和華藉嫩的兒子約書亞所說的話。","notes":[]}]},"17":{"heading":"以利亞和旱災","verses":[{"n":1,"t":"住在基列的提斯比人以利亞對亞哈說：「我指著所事奉永生的耶和華－以色列的神起誓，這幾年我若不禱告，必不降露水，也不下雨。」","notes":[]},{"n":2,"t":"耶和華的話臨到以利亞，說：","notes":[]},{"n":3,"t":"「你離開這裏往東去，躲在約旦河東邊的基立溪旁。","notes":[]},{"n":4,"t":"你要喝那溪裏的水，我已吩咐烏鴉在那裏供養你。」","notes":[]},{"n":5,"t":"於是以利亞去了，他遵照耶和華的話做，去住在約旦河東的基立溪旁。","notes":[]},{"n":6,"t":"烏鴉早上給他叼餅和肉來，晚上也有餅和肉，他又喝溪裏的水。","notes":[]},{"n":7,"t":"過了些日子溪水乾了，因為雨沒有下在地上。","notes":[]},{"n":8,"t":"耶和華的話臨到他，說：","notes":[],"heads":["以利亞和撒勒法的寡婦"]},{"n":9,"t":"「你起身到西頓的撒勒法去，住在那裏，看哪，我已吩咐那裏的一個寡婦供養你。」","notes":[]},{"n":10,"t":"以利亞就起身往撒勒法去。他到了城門，看哪，有一個寡婦在那裏撿柴。以利亞呼喚她說：「請你用器皿取點水來給我喝。」","notes":[]},{"n":11,"t":"她去取水的時候，以利亞又呼喚她說：「請你手裏也拿點餅來給我。」","notes":[]},{"n":12,"t":"她說：「我指著永生的耶和華－你的神起誓，我沒有餅，罈內只有一把麵，瓶裏只有一點油。看哪，我去找兩根柴，帶回家為我和我兒子做餅。我們吃了，就等死吧！」","notes":[]},{"n":13,"t":"以利亞對她說：「不要怕！你去照你所說的做吧！只要先為我做一個小餅，拿來給我，然後為你和你的兒子做餅；","notes":[]},{"n":14,"t":"因為耶和華－以色列的神如此說：『罈內的麵必不用盡，瓶裏的油必不短缺，直到耶和華使雨降在地上的日子。』」","notes":[]},{"n":15,"t":"婦人就照以利亞的話去做。她和以利亞，以及她家中的人，吃了許多日子。","notes":[]},{"n":16,"t":"罈內的麵果然沒有用盡，瓶裏的油也不短缺，正如耶和華藉以利亞所說的話。","notes":[]},{"n":17,"t":"這事以後，那婦人，就是那家的女主人，她的兒子病了，病得很重，甚至沒有氣息。","notes":[]},{"n":18,"t":"婦人對以利亞說：「神人哪，我跟你有甚麼關係，你竟到我這裏來，使神記起我的罪，以致我的兒子死了呢？」","notes":[]},{"n":19,"t":"以利亞對她說：「把你兒子交給我。」以利亞就從婦人懷中接過孩子來，抱到他所住的頂樓，放在自己的床上。","notes":[]},{"n":20,"t":"他求告耶和華說：「耶和華－我的神啊，我寄居在這寡婦的家裏，你卻降禍於她，使她的兒子死了嗎？」","notes":[]},{"n":21,"t":"以利亞三次伏在孩子的身上，求告耶和華說：「耶和華－我的神啊，求你使這孩子的生命歸回給他吧！」","notes":[]},{"n":22,"t":"耶和華聽了以利亞的呼求，孩子的生命歸回給他，他就活了。","notes":[]},{"n":23,"t":"以利亞把孩子從樓上抱下來，進了房間交給他母親，說：「看，你的兒子活了！」","notes":[]},{"n":24,"t":"婦人對以利亞說：「現在我知道你是神人，耶和華藉你口所說的話是真的。」","notes":[]}]},"18":{"heading":"以利亞和巴力的先知","verses":[{"n":1,"t":"過了許多日子，到了第三年，耶和華的話臨到以利亞，說：「你去，讓亞哈看見你，我要降雨在地面上。」","notes":[]},{"n":2,"t":"以利亞就去，要讓亞哈見到他。那時，撒瑪利亞的饑荒非常嚴重。","notes":[]},{"n":3,"t":"亞哈召來他的管家俄巴底。俄巴底非常敬畏耶和華。","notes":[]},{"n":4,"t":"耶洗別殺耶和華先知的時候，俄巴底把一百個先知藏了，每五十人藏在一個洞裏，拿餅和水供養他們。","notes":[]},{"n":5,"t":"亞哈對俄巴底說：「我們要走遍這地，到一切水泉旁和一切溪邊，或者能找到青草，可以救活馬和騾子，免得喪失一些牲畜。」","notes":[]},{"n":6,"t":"於是二人分地巡查，亞哈獨自走一路，俄巴底獨自走另一路。","notes":[]},{"n":7,"t":"俄巴底在路上時，看哪，以利亞遇見他。俄巴底認出他來，就臉伏於地，說：「你是我主以利亞嗎？」","notes":[]},{"n":8,"t":"以利亞對他說：「我是。你去，告訴你主人說：『看哪，以利亞在這裏。』」","notes":[]},{"n":9,"t":"俄巴底說：「僕人犯了甚麼罪，你竟要把我交在亞哈手裏，使他殺我呢？","notes":[]},{"n":10,"t":"我指著永生的耶和華－你的神起誓，無論哪一邦哪一國，我主都派人去找你。若他們說：『不在這裏』，他就叫那邦那國的人起誓說，他們實在找不到你。","notes":[]},{"n":11,"t":"現在你說：『你去告訴你主人說，看哪，以利亞在這裏』；","notes":[]},{"n":12,"t":"恐怕我一離開你，耶和華的靈就把你提到我所不知道的地方去。這樣，我去告訴亞哈，他若找不到你，就必殺我。僕人是自幼敬畏耶和華的。","notes":[]},{"n":13,"t":"耶洗別殺耶和華先知的時候，我把耶和華的一百個先知藏了，每五十人藏在一個洞裏，拿餅和水供養他們，難道沒有人把我做的這事告訴我主嗎？","notes":[]},{"n":14,"t":"現在你說：『你去告訴你主人說，看哪，以利亞在這裏』，他一定會殺我。」","notes":[]},{"n":15,"t":"以利亞說：「我指著所事奉永生的萬軍之耶和華起誓，我今日要讓亞哈見到我。」","notes":[]},{"n":16,"t":"於是俄巴底去迎見亞哈，告訴他這事。亞哈就去見以利亞。","notes":[]},{"n":17,"t":"亞哈見了以利亞，就說：「真的是你嗎？你這使以色列遭殃的人！」","notes":[]},{"n":18,"t":"以利亞說：「使以色列遭殃的不是我，而是你和你的父家，因為你們離棄耶和華的誡命，去隨從巴力。","notes":["「耶和華的誡命」：七十士譯本是「你們的主神」。"]},{"n":19,"t":"現在你要派人去召集以色列眾人，以及耶洗別所供養的四百五十個巴力的先知和四百個亞舍拉的先知，叫他們都上迦密山到我這裏來。」","notes":[]},{"n":20,"t":"亞哈就派人到以色列眾人那裏，召集先知上迦密山。","notes":[]},{"n":21,"t":"以利亞近前來對眾百姓說：「你們心持二意要到幾時呢？如果耶和華是神，就當順從耶和華；如果是巴力，就當順從巴力。」百姓一言不答。","notes":[]},{"n":22,"t":"以利亞對百姓說：「作耶和華先知的只剩下我一個；巴力的先知卻有四百五十人。","notes":[]},{"n":23,"t":"請給我們兩頭牛犢，巴力的先知可以為自己挑選一頭牛犢，切成小塊，放在柴上，不要點火；我也預備一頭牛犢放在柴上，也不點火。","notes":[]},{"n":24,"t":"你們求告你們神明的名，我也求告耶和華的名。那應允禱告降火的就是神。」眾百姓回答說：「好主意。」","notes":[]},{"n":25,"t":"以利亞對巴力的先知說：「因為你們人多，先挑選一頭牛犢，預備好了，求告你們神明的名，卻不要點火。」","notes":[]},{"n":26,"t":"他們把所給他們的牛犢預備好了，從早晨到中午，求告巴力的名說：「巴力啊，求你應允我們！」卻沒有聲音，也沒有回應。他們就在所築的壇四圍蹦跳。","notes":[]},{"n":27,"t":"到了正午，以利亞嘲笑他們，說：「大聲求告吧！因為它是神明，它或許在默想，或許正忙著，或許在路上，或許在睡覺，它該醒過來了。」","notes":["「正忙著」或譯「在大解」。"]},{"n":28,"t":"他們大聲求告，按著他們的儀式，用刀槍刺割自己，直到渾身流血。","notes":[]},{"n":29,"t":"中午過去了，他們狂呼亂叫，直到獻晚祭的時候，卻沒有聲音，沒有回應的，也沒有理睬的。","notes":[]},{"n":30,"t":"以利亞對眾百姓說：「你們到我這裏來。」眾百姓就到他那裏，他把那已經毀壞了的耶和華的壇修好。","notes":[]},{"n":31,"t":"以利亞按照雅各子孫支派的數目，取了十二塊石頭；耶和華的話曾臨到雅各，說：「你的名要叫以色列。」","notes":[]},{"n":32,"t":"以利亞用這些石頭為耶和華的名築一座壇，在壇的四圍挖溝，可容納二細亞穀種。","notes":[]},{"n":33,"t":"他又在壇上擺好了柴，把牛犢切成小塊放在柴上，說：「你們用四個桶盛滿水，倒在燔祭和柴上。」","notes":[]},{"n":34,"t":"他又說：「倒第二次。」他們就倒第二次。他又說：「倒第三次。」他們就倒第三次。","notes":[]},{"n":35,"t":"水流到壇的四圍，溝裏也滿了水。","notes":[]},{"n":36,"t":"到了獻晚祭的時候，先知以利亞近前來，說：「耶和華－亞伯拉罕、以撒、以色列的神啊，求你今日使人知道你是以色列的神，我是你的僕人，我遵照你的話做這一切事。","notes":[]},{"n":37,"t":"求你應允我，耶和華啊，應允我，使這百姓知道你－耶和華是神，是你叫他們回心轉意的。」","notes":[]},{"n":38,"t":"於是，耶和華降下火來，燒盡燔祭、木柴、石頭、塵土，又燒乾了溝裏的水。","notes":[]},{"n":39,"t":"眾百姓看見了，就臉伏於地，說：「耶和華是神！耶和華是神！」","notes":[]},{"n":40,"t":"以利亞對他們說：「拿住巴力的先知，不讓任何人逃走！」眾人就拿住他們。以利亞帶他們到基順河邊，在那裏殺了他們。","notes":[]},{"n":41,"t":"以利亞對亞哈說：「你現在可以上去吃喝，因為有暴雨的響聲了。」","notes":[],"heads":["旱災停止"]},{"n":42,"t":"亞哈就上去吃喝。以利亞上了迦密山頂，屈身在地，把臉伏在兩膝之中。","notes":[]},{"n":43,"t":"他對僕人說：「你上去，向海觀看。」僕人就上去觀看，說：「沒有甚麼。」以利亞說：「你再去。」如此七次。","notes":[]},{"n":44,"t":"第七次，僕人說：「看哪，有一小片雲從海裏上來，好像人的手掌那麼大。」以利亞說：「你上去告訴亞哈，當套車下去，免得被雨阻擋。」","notes":[]},{"n":45,"t":"霎時間，天因風雲黑暗，降下大雨。亞哈就坐上車，往耶斯列去了。","notes":[]},{"n":46,"t":"耶和華的手按在以利亞身上，他就束上腰，奔在亞哈前頭，一路到耶斯列。","notes":[]}]},"19":{"heading":"以利亞在何烈山上","verses":[{"n":1,"t":"亞哈把以利亞一切所做的和他用刀殺眾先知的事都告訴耶洗別。","notes":[]},{"n":2,"t":"耶洗別就派使者到以利亞那裏，說：「明日約這時候，我若不使你的性命像那些人的性命一樣，願神明重重懲罰我。」","notes":[]},{"n":3,"t":"以利亞害怕，就起來逃命，到了猶大的別是巴，把僕人留在那裏。","notes":["「害怕」是根據一些古卷和七十士譯本；原文是「看見」。"]},{"n":4,"t":"他自己在曠野走了一日的路程，來到一棵羅騰樹下，就坐在那裏求死，說：「耶和華啊，現在夠了！求你取我的性命吧，因為我不比我的祖先好。」","notes":["「羅騰」是音譯，小樹名，松類；下同。"]},{"n":5,"t":"他躺在羅騰樹下睡著了。看哪，有一個天使拍他，對他說：「起來吃吧！」","notes":[]},{"n":6,"t":"他觀看，看哪，頭旁有燒熱的石頭烤的餅和一壺水，他就吃了喝了，又再躺下。","notes":[]},{"n":7,"t":"耶和華的使者回來，第二次拍他，說：「起來吃吧！因為你要走的路很遠。」","notes":[]},{"n":8,"t":"他就起來吃了喝了，仗著這飲食的力走了四十晝夜，到了神的山，就是何烈山。","notes":[]},{"n":9,"t":"他在那裏進了一個洞，在洞中過夜。看哪，耶和華的話臨到他，說：「以利亞，你在這裏做甚麼？」","notes":[]},{"n":10,"t":"他說：「我為耶和華－萬軍之神大發熱心，因為以色列人背棄了你的約，毀壞了你的壇，用刀殺了你的先知，只剩下我一人，他們還要追殺我。」","notes":[]},{"n":11,"t":"耶和華說：「你出來站在山上，在耶和華面前。」看哪，耶和華從那裏經過。在耶和華面前有烈風大作，山崩石裂，耶和華卻不在風中；風後有地震，耶和華也不在其中；","notes":[]},{"n":12,"t":"地震後有火，耶和華也不在火中；火以後，有輕微細小的聲音。","notes":[]},{"n":13,"t":"以利亞聽見，就用外衣蒙臉，出來站在洞口。聽啊，有聲音向他說：「以利亞，你在這裏做甚麼？」","notes":[]},{"n":14,"t":"他說：「我為耶和華－萬軍之神大發熱心，因為以色列人背棄了你的約，毀壞了你的壇，用刀殺了你的先知，只剩下我一人，他們還要追殺我。」","notes":[]},{"n":15,"t":"耶和華對他說：「去吧，從原路回去，往大馬士革的曠野去。到了那裏，你要膏哈薛作亞蘭王，","notes":[]},{"n":16,"t":"又膏寧示的孫子耶戶作以色列王，並膏亞伯‧米何拉人沙法的兒子以利沙作先知接續你。","notes":[]},{"n":17,"t":"將來逃過哈薛之刀的，必被耶戶所殺；逃過耶戶之刀的，必被以利沙所殺。","notes":[]},{"n":18,"t":"但我在以色列中留下七千人，是未曾向巴力屈膝，未曾親吻巴力的。」","notes":[]},{"n":19,"t":"於是，以利亞離開那裏走了，遇見沙法的兒子以利沙；他正在耕田，在他前頭有十二對牛，自己趕著第十二對。以利亞經過他，把自己的外衣搭在他身上。","notes":[],"heads":["以利沙蒙選召"]},{"n":20,"t":"以利沙就離開牛，跑到以利亞那裏，說：「請你讓我先與父母吻別，然後我就跟隨你。」以利亞對他說：「因我對你所做的事，你去吧，然後回來。」","notes":["「因我...回來。」或譯「你去吧，然後回來，我向你做了甚麼呢？」"]},{"n":21,"t":"以利沙離開他回去，宰了一對牛，用套牛的器具煮肉給百姓吃，隨後就起身跟隨以利亞，服事他。","notes":[]}]},"20":{"heading":"與亞蘭人爭戰","verses":[{"n":1,"t":"亞蘭王便‧哈達召集他的全軍，率領三十二個王，帶著馬和戰車，上來圍困撒瑪利亞，要攻打它。","notes":[]},{"n":2,"t":"他派使者進城到以色列王亞哈那裏，對他說：「便‧哈達如此說：","notes":[]},{"n":3,"t":"『你的金銀都要歸我，你妻妾兒女中最美的也要歸我。』」","notes":[]},{"n":4,"t":"以色列王回答說：「我主我王啊，就照著你的話，我和我所有的都歸你。」","notes":[]},{"n":5,"t":"使者又來說：「便‧哈達如此說：『我已派人到你那裏，要你把你的金銀、妻妾、兒女都歸我。』","notes":[]},{"n":6,"t":"但明日約在這時候，我還要派臣僕到你那裏，搜查你的家和你僕人的家，你眼中一切所喜愛的都由他們的手拿走。」","notes":[]},{"n":7,"t":"以色列王召了國內所有的長老來，說：「你們要知道，看，這人是來找麻煩的！他派人到我這裏來，要我的妻妾、兒女和金銀，我並沒有拒絕他。」","notes":[]},{"n":8,"t":"所有的長老和眾百姓對王說：「不要聽從他，也不要答應他。」","notes":[]},{"n":9,"t":"以色列王對便‧哈達的使者說：「你們告訴我主我王說：『王頭一次派人向僕人所要的一切，僕人都依從，但這事我不能依從。』」使者就去回覆便‧哈達。","notes":[]},{"n":10,"t":"便‧哈達又派人到亞哈那裏，說：「撒瑪利亞的塵土若足夠跟從我的軍兵每人手拿一把，願神明重重懲罰我！」","notes":[]},{"n":11,"t":"以色列王回答說：「你們告訴他說，『剛束上腰帶的，不要像已卸下的那樣誇口。』」","notes":[]},{"n":12,"t":"便‧哈達和諸王正在帳幕裏喝酒，聽見這話，就對他臣僕說：「擺陣吧！」他們就擺陣攻城。","notes":[]},{"n":13,"t":"看哪，一個先知靠近以色列王亞哈，說：「耶和華如此說：『這一大群人你看見了嗎？看哪，今日我必把他們交在你手裏，你就知道我是耶和華。』」","notes":[]},{"n":14,"t":"亞哈說：「藉著誰呢？」他說：「耶和華如此說：『藉著跟從省長的年輕人。』」亞哈說：「誰要開戰呢？」他說：「你！」","notes":[]},{"n":15,"t":"於是亞哈數點跟從省長的年輕人，共二百三十二名，然後又數點以色列的眾軍兵，共七千名。","notes":[]},{"n":16,"t":"中午，他們出了城；便‧哈達和幫助他的三十二個王正在帳幕裏暢飲。","notes":[]},{"n":17,"t":"跟從省長的年輕人先出城。便‧哈達派人去，他們回報說：「有人從撒瑪利亞出來了。」","notes":[]},{"n":18,"t":"他說：「他們若為求和出來，要活捉他們，若為打仗出來，也要活捉他們。」","notes":[]},{"n":19,"t":"跟從省長的年輕人，和跟隨他們的軍兵，都出了城，","notes":[]},{"n":20,"t":"各人遇見敵人就擊殺。亞蘭人逃跑，以色列人追趕他們；亞蘭王便‧哈達騎著馬和騎兵一同逃跑。","notes":[]},{"n":21,"t":"以色列王出城攻擊馬和戰車，大大擊殺亞蘭人。","notes":["「攻擊」：七十士譯本是「擄獲一切的」。"]},{"n":22,"t":"那先知靠近以色列王，對他說：「去吧，你當自強，看清楚，也要知道你所要做的事，因為再過一年，亞蘭王會上來攻擊你。」","notes":[]},{"n":23,"t":"亞蘭王的臣僕對他說：「他們的神是山神，所以他們勝過我們。但在平原與他們打仗，我們一定勝過他們。","notes":[],"heads":["亞蘭人第二次來犯"]},{"n":24,"t":"王當做這樣的事，把諸王革去，派軍官代替他們，","notes":[]},{"n":25,"t":"又照著王喪失軍兵的數目，再招募一支軍隊，馬補馬，車補車。然後在平原與他們打仗，我們一定勝過他們。」王就聽臣僕的話，照樣去做。","notes":[]},{"n":26,"t":"過了一年，便‧哈達果然召集亞蘭人上亞弗去，要與以色列人打仗。","notes":[]},{"n":27,"t":"以色列人也召集軍兵，預備食物，去迎戰亞蘭人。 以色列人對著他們安營，好像兩小群的山羊；亞蘭人卻佈滿了地面。","notes":[]},{"n":28,"t":"有神人靠近，對以色列王說：「耶和華如此說：『亞蘭人既說我－耶和華是山神，不是平原之神，我必將這一大群人全都交在你手中，你們就知道我是耶和華。』」","notes":[]},{"n":29,"t":"以色列人與亞蘭人相對安營七日，到第七日兩軍開戰。那一日以色列人殺了亞蘭的十萬步兵，","notes":[]},{"n":30,"t":"其餘的都逃向亞弗，到了城裏，城牆倒塌，壓死了剩下的二萬七千人。便‧哈達也逃入城內，藏在嚴密的內室裏。","notes":[]},{"n":31,"t":"他的臣僕對他說：「看哪，我們聽說以色列家的王都是仁慈的王；讓我們腰束麻布，頭套繩索，出去到以色列王那裏，也許他會存留王的性命。」","notes":[]},{"n":32,"t":"於是他們腰束麻布，頭套繩索，來到以色列王那裏，說：「王的僕人便‧哈達說：『求王饒我一命。』」亞哈說：「他還活著嗎？他是我的兄弟。」","notes":[]},{"n":33,"t":"這些人正在探測吉凶，就立即抓住他的話說：「便‧哈達是王的兄弟！」王說：「你們去請他來。」便‧哈達出來到王那裏，王就請他上車。","notes":[]},{"n":34,"t":"便‧哈達對王說：「我父從你父那裏所奪的城鎮，我必歸還給你。你可以在大馬士革為你自己設立街市，像我父在撒瑪利亞所設立的一樣。」亞哈說：「我照此立約，放你回去。」王就與他立約，放了他。","notes":[]},{"n":35,"t":"有一個人是先知的門徒，遵照耶和華的話對他同伴說：「你打我吧！」那人不肯打他。","notes":[],"heads":["先知責亞哈縱敵"]},{"n":36,"t":"他就對那人說：「你既不聽從耶和華的話，看哪，你一離開我，必有獅子咬死你。」那人一離開他，果然遇見獅子，把他咬死了。","notes":[]},{"n":37,"t":"先知的門徒又遇見一個人，對他說：「你打我吧！」那人就打他，把他打傷。","notes":[]},{"n":38,"t":"那先知就去了，用頭巾蒙眼，改了裝，在路旁等候王。","notes":[]},{"n":39,"t":"王從那裏經過，他向王呼叫說：「僕人出戰的時候，看哪，有人轉過來，帶了一個人到我這裏來，說：『你要看守這人，若他真的失蹤了，你的性命必代替他的性命，否則，你就要交出一他連得銀子來。』","notes":[]},{"n":40,"t":"僕人正在到處忙碌的時候，那人就不見了。」以色列王對他說：「你自己決定了，就必照樣判你。」","notes":[]},{"n":41,"t":"他急忙除掉蒙眼的頭巾，以色列王就認出他是一個先知。","notes":[]},{"n":42,"t":"他對王說：「耶和華如此說：『因你把我決定要消滅的人從你手中放走，所以你的命必代替他的命，你的百姓必代替他的百姓。』」","notes":[]},{"n":43,"t":"於是以色列王生氣，憂悶地回撒瑪利亞，到自己的宮去了。","notes":[]}]},"21":{"heading":"拿伯的葡萄園","verses":[{"n":1,"t":"這些事以後，又有一事。耶斯列人拿伯在耶斯列有一個葡萄園，靠近撒瑪利亞，亞哈王的宮。","notes":[]},{"n":2,"t":"亞哈對拿伯說：「把你的葡萄園給我作菜園，因為它靠近我的宮，我就把更好的葡萄園換給你。你若要銀子，我就按著價錢給你。」","notes":[]},{"n":3,"t":"拿伯對亞哈說：「耶和華不准我把我祖先留下的產業給你。」","notes":[]},{"n":4,"t":"亞哈因耶斯列人拿伯說「我不把我祖先留下的產業給你」，就生氣，憂悶地回宮，躺在床上，臉轉向內，也不吃飯。","notes":[]},{"n":5,"t":"耶洗別王后來對他說：「你為甚麼心裏這樣生氣，不吃飯呢？」","notes":[]},{"n":6,"t":"他對王后說：「我向耶斯列人拿伯說：『把你的葡萄園按價錢賣給我，或是你願意，我可以把別的葡萄園換給你。』他卻說：『我不把我的葡萄園給你。』」","notes":[]},{"n":7,"t":"耶洗別王后對王說：「你現在是不是治理以色列國呢？只管起來，心裏暢暢快快地吃飯，我會把耶斯列人拿伯的葡萄園給你。」","notes":[]},{"n":8,"t":"於是王后以亞哈的名義寫信，蓋上王的印，把信送給那些與拿伯同城居住的長老和貴族。","notes":[]},{"n":9,"t":"她在信上寫著說：「你們當宣告禁食，叫拿伯坐在百姓的高位上，","notes":[]},{"n":10,"t":"又叫兩個無賴坐在拿伯對面，作證告他說：『你詛咒了神和王。』然後把他拉出去用石頭打死。」","notes":[]},{"n":11,"t":"那些與拿伯同城居住的長老和貴族，照耶洗別送給他們的信去做。正如她送的信上所寫，","notes":[]},{"n":12,"t":"他們宣告禁食，叫拿伯坐在百姓的高位上。","notes":[]},{"n":13,"t":"有兩個無賴來，坐在拿伯對面。無賴當著百姓作證告他說：「拿伯詛咒神和王了！」眾人就把他拉到城外，用石頭打他，他就死了。","notes":[]},{"n":14,"t":"於是他們派人到耶洗別那裏，說：「拿伯被石頭打死了。」","notes":[]},{"n":15,"t":"耶洗別聽見拿伯被石頭打死，就對亞哈說：「你起來，去取得耶斯列人拿伯不肯出價賣給你的葡萄園吧！因為拿伯不在了，他已經死了。」","notes":[]},{"n":16,"t":"亞哈聽見拿伯死了，就起來，下去要取得耶斯列人拿伯的葡萄園。","notes":[]},{"n":17,"t":"耶和華的話臨到提斯比人以利亞，說：","notes":[]},{"n":18,"t":"「你起來，去見在撒瑪利亞的以色列王亞哈。看哪，他下去要取得拿伯的葡萄園，他正在那園裏。","notes":[]},{"n":19,"t":"你要對他說：『耶和華如此說：你殺了人，還要取得他的產業嗎？』又要對他說：『耶和華如此說：狗在何處舔拿伯的血，狗也必在何處舔你的血。』」","notes":[]},{"n":20,"t":"亞哈對以利亞說：「我的仇敵啊，你找到我了嗎？」他說：「我找到你了。因為你出賣自己，行了耶和華眼中看為惡的事。","notes":[]},{"n":21,"t":"耶和華說：『看哪，我必使災禍臨到你，把你除滅。以色列中凡屬亞哈的男丁，無論是奴役的、自由的，我都要剪除。","notes":[]},{"n":22,"t":"我必使你的家像尼八的兒子耶羅波安的家，又像亞希雅的兒子巴沙的家，因為你惹我發怒，又使以色列陷入罪裏。』","notes":[]},{"n":23,"t":"論到耶洗別，耶和華說：『狗必在耶斯列的城郭吃耶洗別。","notes":["「城郭」：有些古卷和古譯本是「田間」。"]},{"n":24,"t":"凡屬亞哈的人，死在城中的必被狗吃，死在田野的必被空中的鳥吃。』」","notes":[]},{"n":25,"t":"（只是從來沒有像亞哈的，因他受耶洗別王后的唆使，出賣自己，行了耶和華眼中看為惡的事。","notes":[]},{"n":26,"t":"他行了最可憎的事，隨從偶像，正如耶和華在以色列人面前趕出的亞摩利人所行的一切。）","notes":[]},{"n":27,"t":"亞哈聽見這些話，就撕裂衣服，禁食，貼身穿著麻布，也睡在麻布上，沮喪地走來走去。","notes":[]},{"n":28,"t":"耶和華的話臨到提斯比人以利亞，說：","notes":[]},{"n":29,"t":"「亞哈在我面前這樣謙卑，你看見了嗎？因為他在我面前謙卑，所以在他的日子，我不降這禍；到他兒子的時候，我必降這禍於他的家。」","notes":[]}]},"22":{"heading":"米該雅警告亞哈","verses":[{"n":1,"t":"亞蘭和以色列之間連續三年沒有戰爭。","notes":[]},{"n":2,"t":"到了第三年，猶大王約沙法下去見以色列王。","notes":[]},{"n":3,"t":"以色列王對臣僕說：「你們不知道基列的拉末是屬我們的嗎？我們豈可不採取行動，把它從亞蘭王手裏奪回來呢？」","notes":[]},{"n":4,"t":"亞哈問約沙法說：「你肯同我去攻打基列的拉末嗎？」約沙法對以色列王說：「你我不分彼此，我的軍隊就是你的軍隊，我的馬就是你的馬。」","notes":[]},{"n":5,"t":"約沙法對以色列王說：「請你先求問耶和華的話。」","notes":[]},{"n":6,"t":"於是以色列王召集先知，約有四百人，問他們說：「我可以上去攻打基列的拉末嗎？還是不要上去呢？」他們說：「可以上去，因為主必將那城交在王的手裏。」","notes":[]},{"n":7,"t":"約沙法說：「這裏還有沒有耶和華的先知，我們好求問他呢？」","notes":[]},{"n":8,"t":"以色列王對約沙法說：「還有一個人，是音拉的兒子米該雅，我們可以託他求問耶和華。只是我真的很恨他，因為他對我說預言，從不說吉言，總是說凶信。」約沙法說：「請王不要這麼說。」","notes":[]},{"n":9,"t":"以色列王召了一個官員來，說：「你快去，把音拉的兒子米該雅召來。」","notes":[]},{"n":10,"t":"以色列王和猶大王約沙法在撒瑪利亞城門前的禾場，各穿朝服，坐在寶座上，所有的先知都在他們面前說預言。","notes":[]},{"n":11,"t":"基拿拿的兒子西底家造了鐵角，說：「耶和華如此說：『你要用這些角牴觸亞蘭人，直到將他們滅盡。』」","notes":[]},{"n":12,"t":"所有的先知也都這樣預言說：「可以上基列的拉末去，必然得勝，因為耶和華必將那城交在王的手中。」","notes":[]},{"n":13,"t":"那去召米該雅的使者對他說：「看哪，眾先知都異口同聲向王說吉言，你也跟他們說一樣的話，說吉言吧！」","notes":[]},{"n":14,"t":"米該雅說：「我指著永生的耶和華起誓，耶和華向我說甚麼，我就說甚麼。」","notes":[]},{"n":15,"t":"米該雅來到王那裏，王問他：「米該雅，我們可以上去攻打基列的拉末嗎？還是不要上去呢？」他對王說：「你可以上去，必然得勝，耶和華必將那城交在王的手中。」","notes":[]},{"n":16,"t":"王對他說：「我要你發誓多少次，你才會奉耶和華的名向我說實話呢？」","notes":[]},{"n":17,"t":"米該雅說：「我看見以色列眾人散佈在山上，如同沒有牧人的羊群一般。耶和華說：『這些人沒有主人，他們可以平安地各自回家去。』」","notes":[]},{"n":18,"t":"以色列王對約沙法說：「我豈沒有告訴你，這人對我說預言，從不說吉言，只說凶信嗎？」","notes":[]},{"n":19,"t":"米該雅說：「因此你要聽耶和華的話！我看見耶和華坐在寶座上，天上的萬軍侍立在他左右。","notes":[]},{"n":20,"t":"耶和華說：『誰去引誘亞哈上基列的拉末去陣亡呢？』這個這樣說，那個那樣說。","notes":[]},{"n":21,"t":"隨後有一個靈出來，站在耶和華面前，說：『我去引誘他。』","notes":[]},{"n":22,"t":"耶和華問他：『用甚麼方法呢？』他說：『我要出去，在他眾先知的口中成為謊言的靈。』耶和華說：『這樣，你去引誘他，必能成功。你出去，照樣做吧！』","notes":[]},{"n":23,"t":"現在，看哪，耶和華使謊言的靈入了你所有的這些先知的口，並且耶和華已經宣告要降禍於你。」","notes":[]},{"n":24,"t":"基拿拿的兒子西底家前來，打米該雅一巴掌，說：「耶和華的靈從哪裏離開我向你說話呢？」","notes":[]},{"n":25,"t":"米該雅說：「看哪，你進入嚴密的內室躲藏的那日，就必看見。」","notes":[]},{"n":26,"t":"以色列王說：「把米該雅帶走，交回給亞們市長和約阿施王子，","notes":[]},{"n":27,"t":"你們要說：『王如此說，把這個人關在監獄裏，使他受苦，吃不飽喝不足，直等到我平安回來。』」","notes":[]},{"n":28,"t":"米該雅說：「你若真的能平安回來，那就是耶和華沒有藉我說這話了。」他又說：「眾百姓啊，你們都要聽！」","notes":[]},{"n":29,"t":"以色列王和猶大王約沙法上基列的拉末去。","notes":[],"heads":["亞哈陣亡"]},{"n":30,"t":"以色列王對約沙法說：「我要改裝上陣，你可以仍穿王袍。」以色列王就改裝上陣去了。","notes":[]},{"n":31,"t":"亞蘭王吩咐他的三十二個戰車長說：「你們不要與他們的大將或小兵交戰，只要單單攻擊以色列王。」","notes":[]},{"n":32,"t":"那些戰車長看見約沙法就說：「這一定是以色列王！」他們轉過去與他交戰，約沙法就呼喊起來。","notes":[]},{"n":33,"t":"戰車長見他不是以色列王，就轉身不追他了。","notes":[]},{"n":34,"t":"有一人開弓，並不知情，箭恰巧射入以色列王鎧甲的縫裏。王對駕車的說：「我受重傷了，你掉過車來，載我離開戰場！」","notes":[]},{"n":35,"t":"那日，戰況越來越猛，有人扶著王站在戰車上，面對亞蘭人。到了傍晚，王就死了，血從傷處流入車底。","notes":[]},{"n":36,"t":"約在日落的時候，有喊聲傳遍軍中，說：「大家各歸本城，各歸本地吧！」","notes":[]},{"n":37,"t":"王死了，人把他送到撒瑪利亞，葬在撒瑪利亞。","notes":[]},{"n":38,"t":"他們在撒瑪利亞的水池旁洗他的車，有狗來舔他的血，有妓女在那裏洗澡，正如耶和華所說的話。","notes":[]},{"n":39,"t":"亞哈其餘的事，凡他所做的、他所修造的象牙宮和所建築的一切城鎮，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":40,"t":"亞哈與他祖先同睡，他兒子亞哈謝接續他作王。","notes":[]},{"n":41,"t":"以色列王亞哈第四年，亞撒的兒子約沙法登基作猶大王。","notes":[],"heads":["猶大王約沙法"]},{"n":42,"t":"約沙法登基的時候年三十五歲，在耶路撒冷作王二十五年。他母親名叫阿蘇巴，是示利希的女兒。","notes":[]},{"n":43,"t":"約沙法效法他父親亞撒所行的道，不偏離左右，行耶和華眼中看為正的事。只是丘壇還沒有廢去，百姓仍在那裏獻祭燒香。","notes":[]},{"n":44,"t":"約沙法與以色列王和平相處。","notes":[]},{"n":45,"t":"約沙法其餘的事和他所行的英勇事蹟，以及他的戰役，不都寫在《猶大列王記》上嗎？","notes":[]},{"n":46,"t":"約沙法把他父親亞撒的日子所剩下男的廟妓都從國中除去了。","notes":[]},{"n":47,"t":"那時以東沒有立王，由總督治理。","notes":[]},{"n":48,"t":"約沙法造了他施船隻，要往俄斐去，把金子運來，卻沒有啟航，因為船在以旬‧迦別毀壞了。","notes":[]},{"n":49,"t":"亞哈的兒子亞哈謝對約沙法說：「讓我的僕人和你的僕人坐船同去吧！」約沙法卻不肯。","notes":[]},{"n":50,"t":"約沙法與他祖先同睡，與他祖先同葬在大衛城，他兒子約蘭接續他作王。","notes":[]},{"n":51,"t":"猶大王約沙法第十七年，亞哈的兒子亞哈謝在撒瑪利亞登基作以色列王；他作以色列王二年。","notes":[],"heads":["以色列王亞哈謝"]},{"n":52,"t":"他行耶和華眼中看為惡的事，行他父母的道，又行尼八的兒子耶羅波安的道，使以色列陷入罪裏。","notes":[]},{"n":53,"t":"他事奉巴力，敬拜它，惹耶和華－以色列的神發怒，正如他父親一切所行的。","notes":[]}]}},"2KI":{"1":{"heading":"以利亞和亞哈謝王","verses":[{"n":1,"t":"亞哈死後，摩押背叛以色列。","notes":[]},{"n":2,"t":"亞哈謝在撒瑪利亞，一日從樓上的欄杆跌下來，就病了。於是他派使者，對他們說：「你們去問以革倫的神明巴力‧西卜，我這病是否能痊癒。」","notes":[]},{"n":3,"t":"但耶和華的使者對提斯比人以利亞說：「你起來，上去迎見撒瑪利亞王的使者，對他們說：『你們去問以革倫的神明巴力‧西卜，是因為以色列中沒有神嗎？』","notes":[]},{"n":4,"t":"所以耶和華如此說：『你必不能下你所上的床，因為你一定會死！』」以利亞就去了。","notes":[]},{"n":5,"t":"使者回到王那裏，王對他們說：「你們為甚麼回來了呢？」","notes":[]},{"n":6,"t":"他們對王說：「有一個人上來迎見我們，對我們說：『去，回到差你們來的王那裏，對他說：耶和華如此說，你派人去問以革倫的神明巴力‧西卜，是因為以色列中沒有神嗎？所以你必不能下所上的床，你一定會死。』」","notes":[]},{"n":7,"t":"王對他們說：「上來迎見你們，告訴你們這些話的人是甚麼樣子呢？」","notes":[]},{"n":8,"t":"他們對王說：「這人身穿毛衣，腰束皮帶。」王說：「他一定是提斯比人以利亞。」","notes":["「身穿毛衣」或譯「全身長毛」。"]},{"n":9,"t":"於是，王派了一個五十夫長，帶領五十人到以利亞那裏。他上來，看哪，以利亞正坐在山頂上。五十夫長對他說：「神人哪，王吩咐你下來！」","notes":[]},{"n":10,"t":"以利亞回答五十夫長說：「我若是神人，願火從天上降下來，吞滅你和你的五十個人！」於是有火從天上降下來，吞滅五十夫長和他的五十個人。","notes":[]},{"n":11,"t":"王又派另一個五十夫長，帶領五十人到以利亞那裏。五十夫長對他說：「神人哪，王這樣吩咐，快快下來！」","notes":[]},{"n":12,"t":"以利亞回答他們說：「我若是神人，願火從天上降下來，吞滅你和你的五十個人！」於是神的火從天上降下來，吞滅五十夫長和他的五十個人。","notes":["「神的火」或譯「大火」。"]},{"n":13,"t":"王第三次又派一個五十夫長，帶領五十人去。第三個五十夫長上去，雙膝跪在以利亞面前，哀求他說：「神人哪，願我的性命和你這五十個僕人的性命在你眼中看為寶貴！","notes":[]},{"n":14,"t":"看哪，已經有火從天上降下來，吞滅前兩次來的五十夫長和他們的五十個人，現在願我的性命在你眼中看為寶貴！」","notes":[]},{"n":15,"t":"耶和華的使者對以利亞說：「你跟他下去，不要怕他！」以利亞就起來，跟他下到王那裏去。","notes":[]},{"n":16,"t":"他對王說：「耶和華如此說：『你派人去問以革倫的神明巴力‧西卜，是因為以色列中沒有神可以讓你求問他的話嗎？所以你必不能下所上的床，你一定會死！』」","notes":[]},{"n":17,"t":"亞哈謝死了，正如耶和華藉以利亞所說的話。猶大王約沙法的兒子約蘭第二年，亞哈謝的兄弟約蘭接續他作王，因亞哈謝沒有兒子。","notes":["「亞哈謝的兄弟」是根據七十士譯本的一些抄本和其他古譯本；原文沒有。"],"heads":["亞哈謝死後約蘭繼位"]},{"n":18,"t":"亞哈謝其餘所做的事，不都寫在《以色列諸王記》上嗎？","notes":[]}]},"2":{"heading":"以利亞被接升天","verses":[{"n":1,"t":"耶和華要用旋風接以利亞升天的時候，以利亞與以利沙從吉甲往前行。","notes":[]},{"n":2,"t":"以利亞對以利沙說：「耶和華差遣我往伯特利去，你可以留在這裏。」以利沙說：「我指著永生的耶和華，又指著你的性命起誓，我必不離開你。」於是二人下到伯特利。","notes":[]},{"n":3,"t":"在伯特利的先知的門徒出來，到以利沙那裏，對他說：「耶和華今日要接你的師父離開你，你知不知道？」他說：「我知道，你們不要作聲。」","notes":["「要接你的師父離開你」：原文直譯「要從你頭上接走你的師父」；下同。"]},{"n":4,"t":"以利亞對以利沙說：「耶和華差遣我往耶利哥去，你可以留在這裏。」以利沙說：「我指著永生的耶和華，又指著你的性命起誓，我必不離開你。」於是二人到了耶利哥。","notes":[]},{"n":5,"t":"在耶利哥的先知的門徒來靠近以利沙，對他說：「耶和華今日要接你的師父離開你，你知不知道？」他說：「我知道，你們不要作聲。」","notes":[]},{"n":6,"t":"以利亞對以利沙說：「耶和華差遣我往約旦河去，你可以留在這裏。」以利沙說：「我指著永生的耶和華，又指著你的性命起誓，我必不離開你。」於是二人一同往前行。","notes":[]},{"n":7,"t":"有五十個先知的門徒同去，遠遠地站在他們對面；他們二人在約旦河邊站住。","notes":[]},{"n":8,"t":"以利亞捲起自己的外衣，用來打水，水就左右分開，二人走乾地過去。","notes":[]},{"n":9,"t":"過去之後，以利亞對以利沙說：「我未被接去離開你以前，你要我為你做甚麼，只管求。」以利沙說：「願感動你的靈雙倍感動我。」","notes":[]},{"n":10,"t":"以利亞說：「你求的是一件難事。我被接去離開你的時候，你若看見我，就必得著；若不然，就得不著了。」","notes":[]},{"n":11,"t":"他們邊走邊說話的時候，看哪，有火馬和火焰車出現，把二人隔開，以利亞就乘旋風升天去了。","notes":[],"heads":["以利亞乘旋風升天"]},{"n":12,"t":"以利沙看見，就呼叫說：「我父啊！我父啊！以色列的戰車騎兵啊！」以利沙不再看見他的時候，就把自己的衣服撕為兩片。","notes":[]},{"n":13,"t":"他拾起以利亞身上掉下來的外衣，回去站在約旦河邊。","notes":[]},{"n":14,"t":"他用以利亞身上掉下來的外衣打水，說：「耶和華－以利亞的神在哪裏呢？」打水之後，水也左右分開，以利沙就過去了。","notes":[]},{"n":15,"t":"在耶利哥的先知的門徒從對面看見他，說：「感動以利亞的靈臨到以利沙身上了。」他們就來迎接他，俯伏於地，向他下拜，","notes":[]},{"n":16,"t":"對他說：「看哪，僕人這裏有五十個壯士，請你讓他們去尋找你師父，或者耶和華的靈將他提起來，投在某山某谷。」以利沙說：「你們不必派人去。」","notes":[]},{"n":17,"t":"他們再三催促，直到他不好意思，就說：「你們派人去吧！」他們就派了五十個人去，尋找了三天，也沒有找著他。","notes":[]},{"n":18,"t":"以利沙仍然留在耶利哥，他們回到他那裏，他對他們說：「我不是告訴你們不必去嗎？」","notes":[]},{"n":19,"t":"耶利哥城的人對以利沙說：「看哪，這城的地勢美好，正如我主所看見的，只是水質惡劣，地也沒有生產。」","notes":[],"heads":["以利沙的神蹟"]},{"n":20,"t":"以利沙說：「你們拿一個新的瓶子來，裏面裝鹽。」他們就拿給他。","notes":[]},{"n":21,"t":"他出去到了水源，把鹽倒在那裏，說：「耶和華如此說：『我治好了這水，從那裏不會再有死亡和不生產的事了。』」","notes":[]},{"n":22,"t":"於是那水治好了，直到今日，正如以利沙所說的話。","notes":[]},{"n":23,"t":"以利沙從那裏上伯特利去。正上路的時候，有些孩童從城裏出來，譏笑他，對他說：「禿頭的，上去吧！禿頭的，上去吧！」","notes":[]},{"n":24,"t":"他轉過身來瞪著他們，奉耶和華的名詛咒他們。於是有兩隻母熊從林中出來，撕裂他們當中的四十二個孩童。","notes":[]},{"n":25,"t":"以利沙從伯特利上迦密山，又從那裏回到撒瑪利亞。","notes":[]}]},"3":{"heading":"以色列與摩押打仗","verses":[{"n":1,"t":"猶大王約沙法第十八年，亞哈的兒子約蘭在撒瑪利亞登基，作以色列王十二年。","notes":[]},{"n":2,"t":"他行耶和華眼中看為惡的事，但不致像他父母所行的，因為他除掉他父所造巴力的柱像。","notes":[]},{"n":3,"t":"然而，他依戀尼八的兒子耶羅波安使以色列陷入罪裏的那罪，總不離開。","notes":[]},{"n":4,"t":"摩押王米沙牧養許多羊，曾向以色列王進貢十萬羔羊和十萬公綿羊的毛。","notes":[]},{"n":5,"t":"亞哈死後，摩押王背叛以色列王。","notes":[]},{"n":6,"t":"那時約蘭王出撒瑪利亞，數點以色列眾人。","notes":[]},{"n":7,"t":"他向前行，派人到猶大王約沙法那裏，說：「摩押王背叛我，你肯同我去攻打摩押嗎？」約沙法說：「我肯上去，你我不分彼此，我的軍隊就是你的軍隊，我的馬就是你的馬。」","notes":[]},{"n":8,"t":"然後約沙法說：「我們從哪條路上去呢？」約蘭說：「從以東曠野的路上去。」","notes":[]},{"n":9,"t":"於是，以色列王和猶大王，以及以東王，都一同去。他們繞行了七日的路程，軍隊和所帶的牲畜都沒有水喝。","notes":[]},{"n":10,"t":"以色列王說：「哀哉！耶和華召集我們這三王，是要交在摩押人的手裏。」","notes":[]},{"n":11,"t":"約沙法說：「這裏不是有耶和華的先知嗎？我們可以託他求問耶和華。」以色列王的一個大臣回答說：「這裏有沙法的兒子以利沙，就是從前服事以利亞的。」","notes":["「服事以利亞的」：原文直譯「倒水在以利亞手上的」。"]},{"n":12,"t":"約沙法說：「他必有耶和華的話。」於是以色列王、約沙法和以東王都下去見他。","notes":[]},{"n":13,"t":"以利沙對以色列王說：「我跟你有甚麼關係呢？去問你父親的先知和你母親的先知吧！」以色列王對他說：「不，因為耶和華召集我們這三王，是要交在摩押人的手裏。」","notes":[]},{"n":14,"t":"以利沙說：「我指著所事奉永生的萬軍之耶和華起誓，我若不看猶大王約沙法的情面，必不理你，不睬你。","notes":[]},{"n":15,"t":"現在你們給我找一個彈琴的人來。」彈琴的人彈奏的時候，耶和華的手就按在以利沙身上。","notes":[]},{"n":16,"t":"他就說：「耶和華如此說：『你們要在這谷中到處挖溝。』","notes":[]},{"n":17,"t":"因為耶和華如此說：『你們雖不見風，也不見雨，這谷卻必滿了水，使你們和你們的牛羊牲畜都有水喝。』","notes":[]},{"n":18,"t":"在耶和華眼中這還算是小事，他也必將摩押人交在你們手中。","notes":[]},{"n":19,"t":"你們必攻破一切堡壘和美好的城鎮，砍伐各種好樹，塞住一切水泉，用石頭毀壞一切良田。」","notes":[]},{"n":20,"t":"到了早晨，約在獻祭的時候，看哪，有水從以東而來，遍地就滿了水。","notes":[]},{"n":21,"t":"摩押眾人聽見這三王上來要與他們打仗，凡能束上腰帶的，無論老少，都被召集站在邊界上。","notes":[],"heads":["摩押人敗遁"]},{"n":22,"t":"摩押人清早起來，日光照在水上，他們看見對面水紅如血，","notes":[]},{"n":23,"t":"就說：「這是血啊！必是三王互相擊殺，全都滅亡了。摩押人哪，我們現在去搶奪財物吧！」","notes":[]},{"n":24,"t":"摩押人到了以色列營，以色列人起來攻打他們，他們就在以色列人面前逃跑。以色列人追殺摩押人，直殺入摩押境內。","notes":["「以色列人追殺...境內」：原文另譯「以色列人前進，擊殺摩押人」。"]},{"n":25,"t":"他們拆毀摩押的城鎮，各人拋石頭填滿一切良田，塞住一切水泉，砍伐各種好樹，只剩下吉珥‧哈列設的石牆，但甩石的兵仍然包圍攻打那城。","notes":[]},{"n":26,"t":"摩押王見戰事激烈，對他不利，就率領七百個拿刀的兵，想突圍逃到以東王那裏，卻沒有成功。","notes":["「以東」：原文另譯「亞蘭」。"]},{"n":27,"t":"於是他在城牆上，把那應當接續他作王的長子獻為燔祭。 有極大的憤怒臨到以色列，於是三王離開摩押王，各自回本地去了。","notes":[]}]},"4":{"heading":"以利沙幫助窮寡婦","verses":[{"n":1,"t":"有個先知門徒的妻子哀求以利沙說：「你的僕人，我丈夫死了，他敬畏耶和華是你所知道的。現在有債主來，要帶走我的兩個孩子給他作奴隸。」","notes":[]},{"n":2,"t":"以利沙對她說：「我可以為你做甚麼呢？告訴我，你家裏有甚麼？」她說：「婢女家中除了一瓶油之外，甚麼也沒有。」","notes":[]},{"n":3,"t":"以利沙說：「你到外面去向所有的鄰舍借器皿，要空的器皿，不要少借。","notes":[]},{"n":4,"t":"然後你回家，關上門，你和你兒子在裏面把油倒在所有的器皿裏，倒滿了就放在一邊。」","notes":[]},{"n":5,"t":"於是婦人離開以利沙去了。她關上門，把自己和兒子關在家裏。他們把器皿拿給她，她就倒油。","notes":[]},{"n":6,"t":"器皿都滿了，她對兒子說：「再給我拿器皿來。」兒子對她說：「沒有器皿了。」油就止住了。","notes":[]},{"n":7,"t":"婦人去告訴神人，神人說：「你去賣了油還債，你和你兩個兒子可以靠著所剩的過活。」","notes":[]},{"n":8,"t":"一日，以利沙經過書念，在那裏有一個富有的婦人強留他吃飯。此後，以利沙每次經過就轉到那裏去吃飯。","notes":[],"heads":["書念婦人接待以利沙"]},{"n":9,"t":"婦人對丈夫說：「看哪，我知道那常從我們這裏經過的是神聖的神人。","notes":[]},{"n":10,"t":"我們可以為他蓋一間有牆的小閣樓，裏面安放床榻、桌子、椅子、燈臺。每當他來到我們這裏，就可以住在那裏。」","notes":[]},{"n":11,"t":"一日，以利沙來到那裏，轉進那閣樓，躺臥在那裏。","notes":[]},{"n":12,"t":"以利沙吩咐僕人基哈西說：「你叫這書念婦人來。」他把婦人叫了來，婦人就站在以利沙面前。","notes":[]},{"n":13,"t":"以利沙吩咐僕人說：「你對她說：『看哪，你為我們費了許多心思，我可以為你做甚麼呢？我可以為你向王或元帥求甚麼呢？』」她說：「我已住在自己百姓之中。」","notes":[]},{"n":14,"t":"以利沙說：「究竟可以為她做甚麼呢？」基哈西說：「她真的沒有兒子，她丈夫也老了。」","notes":[]},{"n":15,"t":"以利沙說：「叫她回來。」於是他叫了她來，她就站在門口。","notes":[]},{"n":16,"t":"以利沙說：「明年這時候，你必抱一個兒子。」她說：「神人，我主啊，不要這樣欺哄婢女。」","notes":["「明年這時候」：原文是「生命足月的時候」。"]},{"n":17,"t":"婦人果然懷孕，到了明年那時候，生了一個兒子，正如以利沙向她所說的。","notes":[]},{"n":18,"t":"孩子長大，一日出去到他父親和收割的人那裏。","notes":[]},{"n":19,"t":"他對父親說：「我的頭啊，我的頭啊！」他父親對僕人說：「把他抱到他母親那裏。」","notes":[]},{"n":20,"t":"僕人抱去，交給他母親。孩子坐在母親的膝上，到中午就死了。","notes":[]},{"n":21,"t":"他母親上去，把他放在神人的床上，關了門出來，","notes":[]},{"n":22,"t":"呼叫她丈夫說：「你叫一個僕人給我牽一匹驢來，我要趕去見神人，然後回來。」","notes":[]},{"n":23,"t":"丈夫說：「今日不是初一，也不是安息日，你為何要到他那裏去呢？」婦人說：「平安無事。」","notes":[]},{"n":24,"t":"於是她備上驢，對僕人說：「走，趕緊走，除非我吩咐你，不要為了我而慢下來。」","notes":[]},{"n":25,"t":"婦人往迦密山去，到了神人那裏。神人遠遠看見她，對僕人基哈西說：「看哪，書念的婦人來了！","notes":[]},{"n":26,"t":"現在你跑去迎接她，對她說，你平安嗎？你丈夫平安嗎？孩子平安嗎？」她說：「平安。」","notes":[]},{"n":27,"t":"婦人上了山，到神人那裏，就抱住神人的腳。基哈西前來要推開她，神人說：「由她吧！因為她心裏愁苦。但耶和華向我隱瞞這事，沒有告訴我。」","notes":[]},{"n":28,"t":"婦人說：「我何嘗向我主求過兒子呢？我豈不是說過，不要欺哄我嗎？」","notes":[]},{"n":29,"t":"以利沙吩咐基哈西說：「你束上腰，手拿我的杖前去。若遇見人，不要向他問安，人若向你問安，也不要回答。要把我的杖放在孩子臉上。」","notes":[]},{"n":30,"t":"孩子的母親說：「我指著永生的耶和華，又指著你的性命起誓，我必不離開你。」於是以利沙起身，隨著她去了。","notes":[]},{"n":31,"t":"基哈西在他們以先去了，把杖放在孩子臉上，卻沒有聲音，也沒有動靜。基哈西回去，迎見以利沙，告訴他說：「孩子還沒有醒過來。」","notes":[]},{"n":32,"t":"以利沙進了屋子，看哪，孩子死了，放在自己的床上。","notes":[]},{"n":33,"t":"他進去，關上門，只有他們兩個人，他就向耶和華祈禱。","notes":[]},{"n":34,"t":"他上去伏在孩子身上，口對口，眼對眼，手對手。他伏在孩子身上，孩子的身體就漸漸暖和了。","notes":[]},{"n":35,"t":"然後他下來，在屋裏來回走了一趟，又上去伏在孩子身上。孩子打了七個噴嚏，眼睛就睜開了。","notes":[]},{"n":36,"t":"以利沙叫基哈西說：「你叫這書念婦人來。」於是他叫了她來。婦人來到以利沙那裏，以利沙說：「把你兒子抱起來。」","notes":[]},{"n":37,"t":"婦人就進來，在以利沙腳前俯伏於地，向他下拜，然後抱起她兒子出去了。","notes":[]},{"n":38,"t":"以利沙回到吉甲，那地正有饑荒。先知的門徒坐在他面前，他吩咐僕人說：「你把大鍋放在火上，給先知的門徒熬湯。」","notes":[],"heads":["兩件神蹟"]},{"n":39,"t":"有一個人去到田野摘菜，發現一棵野瓜藤，就摘了滿滿一兜的野瓜回來，切了放進熬湯的鍋中，並不知道那是甚麼。","notes":[]},{"n":40,"t":"他們把湯倒出來給大家吃。他們吃湯裏東西的時候，喊叫說：「神人哪，鍋子裏的東西會死人！」所以他們不能吃了。","notes":[]},{"n":41,"t":"以利沙說：「拿點麵來。」他把麵撒在鍋中，說：「倒出來，給大家吃吧！」鍋中就沒有毒了。","notes":[]},{"n":42,"t":"有一個人從巴力‧沙利沙來，帶著初熟果子的食物、二十個大麥做的餅和新麥穗，裝在袋子裏送給神人。神人說：「把這些給大家吃。」","notes":[]},{"n":43,"t":"僕人說：「這些豈可擺在一百人面前呢？」以利沙說：「你只管給大家吃吧！因為耶和華如此說，他們必吃了，還有剩下的。」","notes":[]},{"n":44,"t":"僕人就擺在他們面前，他們吃了，還有剩下，正如耶和華所說的。","notes":[]}]},"5":{"heading":"乃縵得醫治","verses":[{"n":1,"t":"亞蘭王的元帥乃縵在他主人面前是一個偉大的人，得王的喜悅，因為耶和華曾藉他使亞蘭人得勝。他雖然是大能的勇士，卻染上了痲瘋。","notes":["「痲瘋」泛指傳染性皮膚病；本卷書下同。"]},{"n":2,"t":"亞蘭人成群出征的時候，從以色列地擄了一個小女孩，她就服事乃縵的妻子。","notes":[]},{"n":3,"t":"她對女主人說：「我希望主人去見撒瑪利亞的先知，他必能治好主人的痲瘋。」","notes":[]},{"n":4,"t":"乃縵去告訴他主人說，從以色列地來的女孩如此如此說。","notes":[]},{"n":5,"t":"亞蘭王說：「你可以去，我也會送信給以色列王。」於是乃縵手裏帶十他連得銀子、六千舍客勒金子和十套衣裳去了。","notes":[]},{"n":6,"t":"他帶著這信給以色列王，說：「現在你接到這信，看哪，我派臣僕乃縵到你這裏來，你要治好他的痲瘋。」","notes":[]},{"n":7,"t":"以色列王讀了信就撕裂衣服，說：「我豈是神，能使人死使人活呢？這人竟派人來，叫我治好一個人的痲瘋。你們要知道，看，這人是找機會來跟我吵架的。」","notes":[]},{"n":8,"t":"神人以利沙聽見以色列王撕裂衣服，就派人到王那裏，說：「你為甚麼撕裂衣服呢？讓那人到我這裏來，他會知道以色列中有先知。」","notes":[]},{"n":9,"t":"於是乃縵帶著車馬到了以利沙的家，站在門前。","notes":[]},{"n":10,"t":"以利沙派一個使者，對乃縵說：「去，在約旦河中沐浴七次，你的肉就必復原，你會得潔淨。」","notes":[]},{"n":11,"t":"乃縵卻發怒走了。他說：「看哪，我以為他必定會出來，到我這裏，站著求告耶和華－他神的名，在患處上搖手，治好這痲瘋。","notes":[]},{"n":12,"t":"大馬士革的亞瑪拿河和法珥法河豈不比以色列的一切水更好嗎？我難道不可以在那裏沐浴而得潔淨嗎？」於是他生氣，轉身走了。","notes":["「亞瑪拿」：原文另譯「亞罷拿」。"]},{"n":13,"t":"他的僕人近前來，對他說：「我父啊，先知若吩咐你做一件大事，你豈不做嗎？何況是吩咐你去沐浴，得潔淨呢？」","notes":[]},{"n":14,"t":"於是乃縵下去，照著神人的話，在約旦河裏浸了七次。他的肉復原，好像小孩的肉，他就潔淨了。","notes":[]},{"n":15,"t":"乃縵帶著所有跟隨他的人，回到神人那裏，站在他面前，說：「看哪，我知道，除了以色列，全地沒有神。現在請你收下僕人的禮物。」","notes":[]},{"n":16,"t":"以利沙說：「我指著所事奉永生的耶和華起誓，我必不接受。」乃縵再三請他收下，他卻不肯。","notes":[]},{"n":17,"t":"乃縵說：「你若不肯，請把兩匹騾子能馱的土賜給僕人，僕人必不再把燔祭或祭物獻給別神，只獻給耶和華。","notes":[]},{"n":18,"t":"惟有一件事，願耶和華饒恕你僕人：我主人進臨門廟在那裏叩拜的時候，他總是扶著我的手，所以我也在臨門廟叩拜。我在臨門廟叩拜的這事，願耶和華饒恕你僕人。」","notes":[]},{"n":19,"t":"以利沙對他說：「你平安地回去吧！」乃縵離開他去了。走了一小段路，","notes":[]},{"n":20,"t":"神人以利沙的僕人基哈西說：「看哪，我主人不願從這亞蘭人乃縵手裏接受他帶來的禮物，我指著永生的耶和華起誓，我必跑去追上他，向他拿些東西。」","notes":[]},{"n":21,"t":"於是基哈西去追乃縵。乃縵看見有人追來，就下車迎著他，說：「都平安嗎？」","notes":[]},{"n":22,"t":"他說：「都平安！我主人派我來說：『看哪，現在有兩個年輕人，是先知的門徒，從以法蓮山區來到我這裏，請你給他們一他連得銀子，兩套衣裳。』」","notes":[]},{"n":23,"t":"乃縵說：「好啊，請收下二他連得。」他再三請求，就把二他連得銀子裝在兩個袋子裏，連同兩套衣裳交給兩個僕人；他們就在基哈西前頭抬著走。","notes":[]},{"n":24,"t":"到了山岡，基哈西從他們手中接過來，放在屋裏，打發這些人走了。","notes":[]},{"n":25,"t":"基哈西進去，站在主人面前。以利沙對他說：「基哈西，你從哪裏來？」他說：「僕人哪裏也沒去。」","notes":[]},{"n":26,"t":"以利沙對他說：「那人下車轉過來迎著你的時候，我的心豈沒有去呢？這豈是接受銀子，接受衣裳、橄欖園、葡萄園、牛羊、僕婢的時候呢？","notes":[]},{"n":27,"t":"因此，乃縵的痲瘋必緊隨你和你的後裔，直到永遠。」基哈西從以利沙面前出去，就長了痲瘋，像雪一樣。","notes":[]}]},"6":{"heading":"找回斧子的頭","verses":[{"n":1,"t":"先知的門徒對以利沙說：「看哪，我們在你面前居住的地方，那裏對我們太窄小了。","notes":[]},{"n":2,"t":"讓我們往約旦河去，各人從那裏取一根木料，在那裏為自己建造居住的地方。」他說：「你們去吧！」","notes":[]},{"n":3,"t":"有一人說：「請你與僕人同去。」他說：「我可以去。」","notes":[]},{"n":4,"t":"於是以利沙與他們同去。到了約旦河，他們砍伐樹木。","notes":[]},{"n":5,"t":"有一人砍樹的時候，斧子的頭掉在水裏，他就喊著說：「不好了！我主啊，斧子是借來的。」","notes":[]},{"n":6,"t":"神人說：「掉在哪裏了？」他把那地方指給以利沙看。以利沙砍了一塊木頭，拋在水裏，就使斧子的頭浮上來了。","notes":[]},{"n":7,"t":"以利沙說：「拿起來吧！」那人就伸手拿起來了。","notes":[]},{"n":8,"t":"亞蘭王與以色列作戰，他和臣僕商議說：「我要在某處某處安營。」","notes":["「安營」或譯「攻擊」。"],"heads":["亞蘭軍隊進攻受挫"]},{"n":9,"t":"神人派人到以色列王那裏，說：「你要小心，不要從某處經過，因為亞蘭人下到那裏去了。」","notes":[]},{"n":10,"t":"以色列王派人到神人告訴他的地方去。神人警告他，他就在那裏有所防備，不止一兩次。","notes":[]},{"n":11,"t":"亞蘭王因這事心裏氣憤，召了臣僕來，對他們說：「我們當中有誰幫助以色列王，你們不告訴我嗎？」","notes":[]},{"n":12,"t":"有一個臣僕說：「不，我主，我王！只有以色列中的先知以利沙，把王在臥房所說的話告訴以色列王。」","notes":[]},{"n":13,"t":"王說：「你們去查看他在哪裏，我好派人去捉拿他。」有人告訴王說：「看哪，他在多坍。」","notes":[]},{"n":14,"t":"王就派遣車馬和大軍往那裏去，夜間他們到了，圍困那城。","notes":[]},{"n":15,"t":"神人的僕人清早起來出去，看哪，車馬軍兵圍困了城。僕人對神人說：「不好了！我主啊，我們該怎麼辦呢？」","notes":[]},{"n":16,"t":"神人說：「不要懼怕！因與我們同在的比與他們同在的更多。」","notes":[]},{"n":17,"t":"以利沙禱告說：「耶和華啊，求你開他的眼目，使他能看見。」耶和華開了這年輕人的眼目，他就看見了，看哪，滿山有火馬和火焰車圍繞以利沙。","notes":[]},{"n":18,"t":"亞蘭人下到以利沙那裏，以利沙向耶和華禱告說：「求你擊打這國，使他們眼目失明。」耶和華就照以利沙的話，擊打他們，使他們眼目失明。","notes":[]},{"n":19,"t":"以利沙對他們說：「這不是那條路，也不是那座城。你們跟我走，我必領你們到你們要尋找的人那裏。」於是他領他們到了撒瑪利亞。","notes":[]},{"n":20,"t":"他們進了撒瑪利亞，以利沙說：「耶和華啊，求你開這些人的眼目，使他們能看見。」耶和華開了他們的眼目，他們就看見了，看哪，是在撒瑪利亞城中。","notes":[]},{"n":21,"t":"以色列王看見他們，就對以利沙說：「我父啊，我真的可以擊殺他們嗎？」","notes":[]},{"n":22,"t":"他說：「不可擊殺！這些人豈是你用刀用弓擄來給你擊殺的呢？當在他們面前擺設飲食給他們吃喝，讓他們回到他們主人那裏。」","notes":[]},{"n":23,"t":"王為他們預備了盛大的宴席。他們吃喝完了，王就送他們回到他們主人那裏。此後，亞蘭的軍隊不再侵犯以色列地了。","notes":[]},{"n":24,"t":"此後，亞蘭王便‧哈達召集他的全軍，上來圍困撒瑪利亞。","notes":[],"heads":["圍困撒瑪利亞"]},{"n":25,"t":"看哪，被圍困的時候，撒瑪利亞有大饑荒，甚至一個驢頭值八十舍客勒，四分之一卡布 的鴿子糞值五舍客勒。","notes":["「卡布」：容量單位；參「度量衡表」。"]},{"n":26,"t":"一日，以色列王在城牆上經過，有一個婦人向他呼叫說：「我主，我王啊！求你幫助。」","notes":[]},{"n":27,"t":"王說：「耶和華不幫助你，我從哪裏幫助你呢？是從禾場，或從壓酒池嗎？」","notes":[]},{"n":28,"t":"王對婦人說：「你有甚麼事？」她說：「這婦人對我說：『把你的兒子交出來，我們今日可以吃他，明日可以吃我的兒子。』","notes":[]},{"n":29,"t":"我們就煮了我的兒子吃了。次日我對她說：『要把你的兒子交出來，我們可以吃。』她卻把她的兒子藏起來。」","notes":[]},{"n":30,"t":"王聽見婦人的話，就撕裂衣服；那時，王在城牆上經過，百姓看見了，看哪，王貼身穿著麻布。","notes":[]},{"n":31,"t":"王說：「我今日若容許沙法的兒子以利沙的頭還留在他身上，願神重重懲罰我！」","notes":[]},{"n":32,"t":"那時，以利沙正坐在家中，有長老與他同坐。王派一個人先去，使者還沒有到，以利沙對長老說：「你們看，這兇手之子派人來斬我的頭。你們注意，當使者來到，你們就關上門，把他關在門外。在他後頭不就是他主人的腳步聲嗎？」","notes":[]},{"n":33,"t":"正與他們說話的時候，看哪，使者下到他那裏，說：「看哪，這災禍是從耶和華來的，我何必再仰望耶和華呢？」","notes":["「使者」：原文另譯「王」。"]}]},"7":{"heading":"亞蘭軍隊棄營逃命","verses":[{"n":1,"t":"以利沙說：「你們要聽耶和華的話，耶和華如此說：明日約這時候，在撒瑪利亞城門口，一細亞細麵只賣一舍客勒，二細亞大麥也賣一舍客勒。」","notes":[]},{"n":2,"t":"有一個攙扶王的軍官回答神人說：「看哪，即使耶和華打開天上的窗戶，也不可能有這事。」以利沙說：「看哪，你必親眼看見，在那裏卻吃不到甚麼。」","notes":[]},{"n":3,"t":"在城門口有四個長痲瘋的人，他們彼此說：「我們為何坐在這裏等死呢？","notes":[]},{"n":4,"t":"我們若說要進城去，城裏有饑荒，我們必死在那裏。若我們在這裏坐著不動，也必死。現在，來吧，我們去向亞蘭人的軍隊投降。若他們饒我們的命，我們就活著；若殺我們，我們就死吧！」","notes":[]},{"n":5,"t":"黃昏的時候，他們起來往亞蘭人的軍營去；到了營邊，看哪，沒有一人在那裏。","notes":[]},{"n":6,"t":"因為主使亞蘭人的軍隊聽見戰車戰馬的聲音，大軍的聲音，他們就彼此說：「看哪，這必是以色列王雇用赫人諸王和埃及諸王來攻擊我們。」","notes":[]},{"n":7,"t":"所以，在黃昏的時候他們起來逃跑，撇下帳棚、馬、驢，把軍營留在原處，只顧逃命。","notes":[]},{"n":8,"t":"那些長痲瘋的人到了營邊，進了一座帳棚，吃了喝了，從當中拿走金銀和衣服，收藏起來。他們又回來，進了另一座帳棚，從當中拿走財物去收藏。","notes":[]},{"n":9,"t":"那時，他們彼此說：「我們所做的不對了！這一天是有好消息的日子，我們竟不作聲！若等到天亮，我們就有罪了。現在，來，我們去向王室報信吧！」","notes":[]},{"n":10,"t":"他們就去叫守城門的人，告訴他們說：「我們到了亞蘭人的軍營，看哪，沒有一人在那裏，也無人聲，只有拴著的馬和驢，帳棚都留在原處。」","notes":[]},{"n":11,"t":"守城門的人就呼叫，他們向城內的王室報信。","notes":[]},{"n":12,"t":"王夜間起來，對臣僕說：「我告訴你們亞蘭人向我們做的事。他們知道我們飢餓，所以離營，埋伏在田野，說：『以色列人出城的時候，我們活捉他們，我們就可以進到城裏去。』」","notes":[]},{"n":13,"t":"王的一個臣僕回答說：「不如叫人從城裏剩下的馬中取五匹，看哪，這些馬像以色列大眾一樣，快要滅亡了；我們派人去窺探吧！」","notes":["「不如叫人...一樣」是根據一些古卷；原文是「不如叫人從城裏剩下的，從城裏剩下的馬中取五匹，看哪，這些馬像以色列大眾一樣，看哪，這些馬像以色列大眾一樣」。"]},{"n":14,"t":"於是他們取了兩輛車和馬，王派人去跟蹤亞蘭人的軍隊，說：「你們去窺探吧。」","notes":[]},{"n":15,"t":"他們去跟蹤亞蘭人，直到約旦河。看哪，整條路上都是亞蘭人匆忙逃跑時所丟棄的衣服和器具，使者就回來向王報告。","notes":[]},{"n":16,"t":"百姓就出去，擄掠亞蘭人的軍營。於是一細亞細麵只賣一舍客勒，二細亞大麥也賣一舍客勒，正如耶和華所說的。","notes":[]},{"n":17,"t":"王派攙扶他的那軍官在城門指揮，百姓在城門把他踩死了，正如神人在王下到他那裏的時候所說的。","notes":[]},{"n":18,"t":"神人曾對王說：「明日約這時候，在撒瑪利亞城門口，二細亞大麥只賣一舍客勒，一細亞細麵也賣一舍客勒。」","notes":[]},{"n":19,"t":"那軍官回答神人說：「看哪，即使耶和華打開天上的窗戶，也不可能有這事。」神人說：「看哪，你必親眼看見，在那裏卻吃不到甚麼。」","notes":[]},{"n":20,"t":"這話果然應驗在他身上，因為百姓在城門把他踩死了。","notes":[]}]},"8":{"heading":"書念的婦人回原住地","verses":[{"n":1,"t":"以利沙曾對他救活的孩子的母親說：「你和你的全家要起身，往你可住的地方去住，因為耶和華已令饑荒降在這地七年。」","notes":[]},{"n":2,"t":"婦人就起身，照神人的話去做，帶著全家往非利士人的地去，寄居了七年。","notes":[]},{"n":3,"t":"過了七年，那婦人從非利士人的地回來，就出去為自己的房屋田地哀求王。","notes":[]},{"n":4,"t":"那時王正與神人的僕人基哈西談話，說：「你把以利沙所做的一切大事告訴我。」","notes":[]},{"n":5,"t":"基哈西告訴王以利沙如何使死人復活，看哪，以利沙所救活的孩子的母親正為自己的房屋田地來哀求王。基哈西說：「我主我王，這就是那婦人，這是她的兒子，就是以利沙所救活的。」","notes":[]},{"n":6,"t":"王問那婦人，她就把事情告訴王。於是王為她派一個官員，說：「凡屬這婦人的都還給她，自從她離開本地直到今日，她田地的出產也都還給她。」","notes":[]},{"n":7,"t":"以利沙來到大馬士革，亞蘭王便‧哈達正患病。有人告訴王說：「神人來到這裏了。」","notes":[],"heads":["以利沙和便‧哈達王"]},{"n":8,"t":"王就吩咐哈薛說：「你帶著禮物去見神人，託他求問耶和華，我這病能不能好？」","notes":[]},{"n":9,"t":"於是哈薛用四十匹駱駝，馱著大馬士革的各樣美物為禮物，去迎見以利沙。哈薛到了那裏，站在他面前，說：「你兒子亞蘭王便‧哈達派我到你這裏，問說：『我這病會不會好？』」","notes":[]},{"n":10,"t":"以利沙對哈薛說：「你回去告訴他說：『你一定會好。』但耶和華指示我，他必定會死。」","notes":[]},{"n":11,"t":"神人定睛看著哈薛，直到他感到羞愧。神人就哭了。","notes":[]},{"n":12,"t":"哈薛說：「我主為甚麼哭？」他說：「因為我知道你必虐待以色列人，用火焚燒他們的堡壘，用刀殺死他們的壯丁，摔死他們的嬰孩，剖開他們的孕婦。」","notes":[]},{"n":13,"t":"哈薛說：「僕人算甚麼，不過是一條狗，怎麼能行這大事呢？」以利沙說：「耶和華指示我，你必作亞蘭王。」","notes":[]},{"n":14,"t":"哈薛離開以利沙，回到他主人那裏。主人對他說：「以利沙對你說了甚麼？」他說：「他告訴我你必能好。」","notes":[]},{"n":15,"t":"次日，哈薛拿被子浸在水中，蒙住王的臉，王就死了。於是哈薛篡了他的位。","notes":[]},{"n":16,"t":"亞哈的兒子以色列王約蘭第五年－約沙法曾作猶大王－猶大王約沙法的兒子約蘭登基作了猶大王。","notes":["有些古卷、七十士譯本和其他古譯本沒有「約沙法曾作猶大王」。"],"heads":["猶大王約蘭"]},{"n":17,"t":"約蘭登基的時候年三十二歲，在耶路撒冷作王八年。","notes":[]},{"n":18,"t":"他行以色列諸王的道，正如亞哈家所行的，因他娶了亞哈的女兒為妻，行耶和華眼中看為惡的事。","notes":[]},{"n":19,"t":"耶和華卻因他僕人大衛的緣故，不肯滅絕猶大，要照他所應許的，永遠賜燈光給大衛和他的子孫。","notes":[]},{"n":20,"t":"約蘭在位期間，以東背叛，自己立王治理他們，脫離猶大的權勢。","notes":[]},{"n":21,"t":"約蘭率領所有的戰車過到撒益去。他夜間起來，攻打圍困他的以東人和戰車長；猶大軍兵逃跑，各回自己的帳棚去了；","notes":[]},{"n":22,"t":"這樣，以東背叛，脫離猶大的權勢，直到今日。那時立拿也背叛了。","notes":[]},{"n":23,"t":"約蘭其餘的事，凡他所做的，不都寫在《猶大列王記》上嗎？","notes":[]},{"n":24,"t":"約蘭與他祖先同睡，與他祖先同葬在大衛城，他兒子亞哈謝接續他作王。","notes":[]},{"n":25,"t":"亞哈的兒子以色列王約蘭第十二年，猶大王約蘭的兒子亞哈謝登基。","notes":[],"heads":["猶大王亞哈謝"]},{"n":26,"t":"他登基的時候年二十二歲，在耶路撒冷作王一年。他母親名叫亞她利雅，是以色列王暗利的孫女。","notes":[]},{"n":27,"t":"亞哈謝行亞哈家的道，行耶和華眼中看為惡的事，與亞哈家一樣，因為他是亞哈家的女婿。","notes":[]},{"n":28,"t":"他與亞哈的兒子約蘭同往基列的拉末去，與亞蘭王哈薛交戰。亞蘭人打傷了約蘭，","notes":[]},{"n":29,"t":"約蘭王回到耶斯列，醫治在拉末與亞蘭王哈薛打仗時，被亞蘭人擊打所受的傷。約蘭的兒子猶大王亞哈謝因為亞哈的兒子約蘭病了，就下到耶斯列看望他。","notes":["「拉末」是根據七十士譯本；原文是「拉瑪」，可能是「基列的拉末」的簡稱。"]}]},"9":{"heading":"耶戶被膏為以色列王","verses":[{"n":1,"t":"以利沙先知叫了一個先知的門徒來，吩咐他：「你束上腰，手拿這瓶膏油往基列的拉末去。","notes":[]},{"n":2,"t":"你到了那裏，要在那裏尋找寧示的孫子，約沙法的兒子耶戶。你去，使他從弟兄中起來，帶他進最裏面的內室，","notes":[]},{"n":3,"t":"把瓶裏的膏油倒在他頭上，說：『耶和華如此說：我膏你作以色列王。』然後你就開門逃跑，不要等候。」","notes":[]},{"n":4,"t":"於是那青年，那年輕的先知往基列的拉末去了。","notes":[]},{"n":5,"t":"他到了那裏，看哪，眾軍官都坐著，就說：「長官，我有話對你說。」耶戶說：「你要對我們哪一個說呢？」他說：「長官，我要對你說。」","notes":[]},{"n":6,"t":"耶戶就起來，進了內室，那青年把膏油倒在他頭上，對他說：「耶和華－以色列的神如此說：『我膏你作耶和華百姓以色列的王。","notes":[]},{"n":7,"t":"你要擊殺你主人亞哈的全家，我好在耶洗別身上，為我僕人眾先知和耶和華所有僕人的血伸冤。","notes":[]},{"n":8,"t":"亞哈全家都必滅亡，凡屬亞哈的男丁，無論是奴役的、自由的，我必從以色列中剪除。","notes":[]},{"n":9,"t":"我必使亞哈的家像尼八兒子耶羅波安的家，又像亞希雅兒子巴沙的家。","notes":[]},{"n":10,"t":"至於耶洗別，狗必在耶斯列田裏吃她，無人埋葬。』」於是那青年就開門逃跑了。","notes":[]},{"n":11,"t":"耶戶出來，回到他主人的臣僕那裏，有一人問他說：「平安嗎？這瘋狂的人為甚麼到你這裏來呢？」他對他們說：「你們認得那人，也知道他在胡說。」","notes":[]},{"n":12,"t":"他們說：「說謊！告訴我們吧。」他說：「他如此如此對我說：『耶和華如此說：我膏你作以色列的王。』」","notes":[]},{"n":13,"t":"他們各人就急忙把自己的衣服鋪在臺階的上層，在耶戶的下面；他們吹角，說：「耶戶作王了！」","notes":[]},{"n":14,"t":"這樣，寧示的孫子，約沙法的兒子耶戶背叛了約蘭。先前約蘭和以色列眾人因為亞蘭王哈薛的緣故，把守基列的拉末。","notes":[],"heads":["以色列王約蘭被殺"]},{"n":15,"t":"後來約蘭王回到耶斯列，醫治他與亞蘭王哈薛打仗時，被亞蘭人擊打所受的傷。耶戶說：「若你們有這樣的意思，就不要讓人溜出城，到耶斯列去報信。」","notes":[]},{"n":16,"t":"於是耶戶駕戰車往耶斯列去，因為約蘭臥病在那裏。猶大王亞哈謝已經下去看望他。","notes":[]},{"n":17,"t":"有一個守望的人站在耶斯列的城樓上，看見耶戶帶著一隊人來，就說：「我看見一隊人。」約蘭說：「派一個騎兵去迎接他們，問說：『平安嗎？』」","notes":[]},{"n":18,"t":"騎兵就去迎接耶戶，說：「王如此說：『平安嗎？』」耶戶說：「平安不平安跟你有甚麼關係呢？轉身跟在我後面吧！」守望的人說：「使者到了他們那裏，卻不回來。」","notes":[]},{"n":19,"t":"王又派第二個騎兵去。這人到了他們那裏，說：「王如此說：『平安嗎？』」耶戶說：「平安不平安跟你有甚麼關係呢？轉身跟在我後面吧！」","notes":[]},{"n":20,"t":"守望的人又說：「他到了他們那裏，也不回來。車駕得很兇猛，好像寧示的孫子耶戶在駕車。」","notes":[]},{"n":21,"t":"約蘭吩咐說：「套車！」人就給他套車。以色列王約蘭和猶大王亞哈謝各坐自己的車出去迎接耶戶，在耶斯列人拿伯的田那裏遇見他。","notes":[]},{"n":22,"t":"約蘭見耶戶就說：「耶戶，平安嗎？」耶戶說：「你母親耶洗別的淫行邪術這樣多，怎麼能平安呢？」","notes":[]},{"n":23,"t":"約蘭用手轉過車來逃跑，對亞哈謝說：「亞哈謝啊，反了！」","notes":[]},{"n":24,"t":"耶戶全力拉弓，射中約蘭兩臂中間，箭從心窩穿出，約蘭就仆倒在車上。","notes":[]},{"n":25,"t":"耶戶對他的軍官畢甲說：「把他拋在耶斯列人拿伯的田裏。你當記得，你我一同駕車跟隨他父親亞哈的時候，耶和華對亞哈說了預言，","notes":[]},{"n":26,"t":"耶和華說：『我昨日看見拿伯的血和他眾子的血，我發誓我必在這塊田上報應你。』這是耶和華說的。現在你要照著耶和華的話，把他拋在這田裏。」","notes":[]},{"n":27,"t":"猶大王亞哈謝看見了，就沿著伯‧哈干的路逃跑。耶戶追趕他，說：「把這人也擊殺在車上，在靠近以伯蓮的姑珥坡上。」他逃到米吉多，就死在那裏。","notes":["「把這人...坡上」：七十士譯本是「『把這人也擊殺了！』有一人就在靠近以伯蓮的蓋坡上把他擊殺在車上」。"],"heads":["猶大王亞哈謝被殺"]},{"n":28,"t":"他的臣僕用車把他的屍體運回耶路撒冷，與他祖先同葬在大衛城，他自己的墳墓裏。","notes":[]},{"n":29,"t":"亞哈的兒子約蘭第十一年，亞哈謝登基作了猶大王。","notes":[]},{"n":30,"t":"耶戶到了耶斯列。耶洗別聽見了，就畫眼影、梳頭，從窗戶往外觀看。","notes":[],"heads":["耶洗別王后被殺"]},{"n":31,"t":"耶戶進了城門，耶洗別說：「殺主人的心利啊，平安嗎？」","notes":[]},{"n":32,"t":"耶戶向窗戶抬頭，說：「有誰順從我？誰？」有兩三個太監向外看他。","notes":[]},{"n":33,"t":"耶戶說：「把她拋下來！」他們就把她拋下來。她的血濺在牆上和馬上，耶戶踐踏在她身上。","notes":[]},{"n":34,"t":"耶戶進去，吃了喝了，說：「你們去處理這被詛咒的婦人，埋了她，因為她是王的女兒。」","notes":[]},{"n":35,"t":"他們去了，要埋葬她，卻只找到她的頭骨和腳，以及手掌。","notes":[]},{"n":36,"t":"他們回來報告耶戶，耶戶說：「這正應驗耶和華藉他僕人提斯比人以利亞所說的話，說：『在耶斯列田裏，狗必吃耶洗別的肉，","notes":[]},{"n":37,"t":"耶洗別的屍體必在耶斯列田裏的地面上如同糞土，甚至沒有人可說：這是耶洗別。』」","notes":[]}]},"10":{"heading":"耶戶的信","verses":[{"n":1,"t":"亞哈有七十個兒子在撒瑪利亞。耶戶寫信送到撒瑪利亞，給耶斯列的領袖和長老，以及教養亞哈眾兒子的人，說：","notes":["「耶斯列的領袖和長老」：有古卷是「耶斯列的領袖，就是長老」。"]},{"n":2,"t":"「你們主人的眾兒子既然在你們那裏，你們又有戰車、馬匹、兵器、堅固城，現在你們接了這信，","notes":[]},{"n":3,"t":"可以在你們主人的眾兒子中選一個賢能正直的，使他坐他父親的王位，你們也可以為你們主人的家作戰。」","notes":[]},{"n":4,"t":"他們卻非常懼怕，說：「看哪，兩個王在他面前尚且站立不住，我們怎能站立得住呢？」","notes":[]},{"n":5,"t":"王宮總管、市長和長老，並教養眾兒子的人，派人到耶戶那裏，說：「我們是你的僕人，凡你所吩咐的，我們都必遵行。我們不立誰作王，你看怎樣好就怎樣做吧。」","notes":[]},{"n":6,"t":"耶戶寫第二封信給他們，說：「你們若歸順我，聽從我的話，明日這時候，要帶著你們主人眾兒子的首級，來到耶斯列我這裏。」那時王的兒子七十人都住在城中教養他們的那些尊貴人家裏。","notes":[],"heads":["亞哈的眾兒子被殺"]},{"n":7,"t":"信一到他們那裏，他們就把王的七十個兒子殺了，將首級裝在筐裏，送到耶斯列，耶戶那裏。","notes":[]},{"n":8,"t":"有使者來告訴耶戶說：「他們把王眾兒子的首級送來了。」耶戶說：「把首級分成兩堆，放在城門口，直到早晨。」","notes":[]},{"n":9,"t":"次日早晨，耶戶出來，站著對眾百姓說：「你們都是公義的！看哪，我背叛了我的主人，把他殺了，但這所有的人又是誰殺的呢？","notes":[]},{"n":10,"t":"由此可知，耶和華指著亞哈家所說的話一句也沒有落空，因為耶和華實現了他藉他僕人以利亞所說的話。」","notes":[]},{"n":11,"t":"凡亞哈家在耶斯列所剩下的，他的大臣、密友、祭司，耶戶全都殺了，沒有留下一個倖存者。","notes":[]},{"n":12,"t":"耶戶起身往撒瑪利亞去。路途中，在牧人聚集的伯‧艾克特，","notes":[],"heads":["亞哈謝的親屬被殺"]},{"n":13,"t":"耶戶遇見猶大王亞哈謝的兄弟，說：「你們是誰？」他們說：「我們是亞哈謝的兄弟，現在下去要向王和太后的眾兒子問安。」","notes":[]},{"n":14,"t":"耶戶說：「活捉他們！」人就活捉了他們，把他們殺在伯‧艾克特的坑邊，共四十二人，一個也沒有留下。","notes":[]},{"n":15,"t":"耶戶從那裏往前行，遇見利甲的兒子約拿達來迎接他，耶戶向他問安，對他說：「你的心，像我的心待你的心那樣正直嗎？」約拿達說：「是。」耶戶說：「若是這樣，請你伸出手來。」他伸出手，耶戶就拉他上車。","notes":["「你的心」：七十士譯本是「你的心待我的心」。"]},{"n":16,"t":"耶戶說：「你和我同去，看我為耶和華怎樣熱心。」於是他們請他坐在車上。","notes":[]},{"n":17,"t":"到了撒瑪利亞，耶戶把亞哈家在撒瑪利亞剩下的人全都殺了，直到滅盡，正如耶和華對以利亞所說的話。","notes":[]},{"n":18,"t":"耶戶召集眾百姓，對他們說：「亞哈事奉巴力還不夠熱心，耶戶更要熱心。","notes":[],"heads":["拜巴力的人被殺"]},{"n":19,"t":"現在你們召集巴力的眾先知和所有拜巴力的人，以及巴力的眾祭司，都到我這裏來，一個也不可缺少，因為我要給巴力獻大祭；凡不來的必不得活。」耶戶行詭詐，為要消滅拜巴力的人。","notes":[]},{"n":20,"t":"耶戶說：「要為巴力召集嚴肅會！」於是他們宣告了。","notes":[]},{"n":21,"t":"耶戶派人走遍以色列；凡拜巴力的人都來齊了，沒有留下一個不來的。他們進了巴力廟，巴力廟中前後都擠滿了人。","notes":[]},{"n":22,"t":"耶戶對掌管服裝的人說：「拿出袍子來，給所有拜巴力的人穿。」他就拿出禮服來給了他們。","notes":[]},{"n":23,"t":"耶戶和利甲的兒子約拿達進了巴力廟，對拜巴力的人說：「你們要搜查察看，不可以有耶和華的僕人在你們這裏，只可以有拜巴力的人。」","notes":[]},{"n":24,"t":"他們進去，獻上祭物和燔祭，耶戶先安排八十人在廟外，說：「我把這些人交在你們手中，誰放走其中一人，誰就要以命償命！」","notes":[]},{"n":25,"t":"耶戶獻完了燔祭，就對護衛兵和眾軍官說：「進去殺他們，不要讓一人逃脫！」護衛兵和軍官用刀殺了他們，將屍體拋出去，然後進入巴力廟的堡壘，","notes":[]},{"n":26,"t":"將巴力廟中的柱像都拿出來焚燒。","notes":["「柱像都」：七十士譯本和其他古譯本是「那根柱像」。"]},{"n":27,"t":"他們毀壞巴力的柱像，拆毀了巴力廟當廁所，直到今日。","notes":[]},{"n":28,"t":"這樣，耶戶在以色列中消滅了巴力。","notes":[]},{"n":29,"t":"只是耶戶不離開尼八的兒子耶羅波安使以色列人陷入罪裏的那罪，就是拜伯特利和但的金牛犢。","notes":[]},{"n":30,"t":"耶和華對耶戶說：「因你辦好我眼中看為正的事，照我的心意待亞哈家，你的子孫必接續你坐以色列的王位，直到第四代。」","notes":[]},{"n":31,"t":"只是耶戶不盡心遵守耶和華－以色列神的律法，不離開耶羅波安使以色列人陷入罪裏的那罪。","notes":[]},{"n":32,"t":"在那些日子，耶和華開始削弱以色列。哈薛在以色列各邊界攻擊他們，","notes":[],"heads":["耶戶去世"]},{"n":33,"t":"就是約旦河東基列全地，從靠近亞嫩谷邊的亞羅珥起，包括基列和巴珊，就是迦得人、呂便人、瑪拿西人的地。","notes":[]},{"n":34,"t":"耶戶其餘的事，凡他所做的和他英勇的事蹟，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":35,"t":"耶戶與他祖先同睡，葬在撒瑪利亞，他兒子約哈斯接續他作王。","notes":[]},{"n":36,"t":"耶戶在撒瑪利亞作以色列王二十八年。","notes":[]}]},"11":{"heading":"亞她利雅篡位","verses":[{"n":1,"t":"亞哈謝的母親亞她利雅見她兒子死了，就起來剿滅王室所有的後裔。","notes":[]},{"n":2,"t":"但約蘭王的女兒，亞哈謝的妹妹約示巴，將亞哈謝的兒子約阿施從被殺的王子中偷出來，把他和他的奶媽藏在臥房裏，躲避了亞她利雅，沒有被殺。","notes":[]},{"n":3,"t":"亞她利雅治理這地的時候，約阿施和他的奶媽在耶和華的殿裏藏了六年。","notes":[]},{"n":4,"t":"第七年，耶何耶大派人叫迦利人和護衛兵的眾百夫長來，領他們進耶和華的殿，與他們立約，使他們在耶和華殿裏起誓，又把王的兒子指給他們看，","notes":[]},{"n":5,"t":"吩咐他們說：「你們要這樣做：你們當中在安息日值班的，三分之一要把守王宮，","notes":[]},{"n":6,"t":"三分之一要在蘇珥門，三分之一要在護衛兵院的後門；你們要這樣輪流把守王宮。","notes":[]},{"n":7,"t":"你們安息日所有不值班的兩隊人員要在耶和華的殿裏護衛王；","notes":[]},{"n":8,"t":"各人手拿兵器，四圍保護王。凡擅自闖入你們行列的，要被處死。王出入的時候，你們當跟隨他。」","notes":[]},{"n":9,"t":"眾百夫長就照著耶何耶大祭司一切所吩咐的去做，各帶自己的人，無論安息日值班或不值班的，都到耶何耶大祭司那裏。","notes":[]},{"n":10,"t":"祭司就把耶和華殿裏所藏大衛王的槍和盾牌交給百夫長。","notes":[]},{"n":11,"t":"護衛兵手中各拿兵器，在祭壇和殿那裏，從殿南到殿北，站在王的四圍。","notes":[]},{"n":12,"t":"耶何耶大領約阿施 出來，給他戴上冠冕，把律法書交給他，膏他作王；眾人都鼓掌說：「願王萬歲！」","notes":["「約阿施」：原文是「王的兒子」。"]},{"n":13,"t":"亞她利雅聽見護衛兵和百姓的聲音，就進耶和華的殿，到百姓那裏。","notes":[]},{"n":14,"t":"她觀看，看哪，王照儀式站在柱旁，百夫長和號手在王旁邊，國中的眾百姓歡樂吹號。亞她利雅就撕裂衣服，喊著說：「反了！反了！」","notes":[]},{"n":15,"t":"耶何耶大祭司吩咐管軍兵的百夫長，對他們說：「把她從行列之間趕出去，凡跟隨她的必用刀殺死！」因為祭司說：「不可在耶和華殿裏殺她。」","notes":[]},{"n":16,"t":"他們就下手拿住她；她進入通往王宮的馬門，就在那裏被殺。","notes":[]},{"n":17,"t":"耶何耶大使王和百姓與耶和華立約，作耶和華的子民，又使王與百姓立約。","notes":[],"heads":["耶何耶大的改革"]},{"n":18,"t":"於是國中的眾百姓都到巴力廟去，拆毀了廟，徹底打碎祭壇和偶像，又在壇前把巴力的祭司瑪坦殺了。耶何耶大祭司派官員看守耶和華的殿，","notes":[]},{"n":19,"t":"又率領百夫長，迦利人和護衛兵，以及國中的眾百姓，請王從耶和華的殿下來，由護衛兵的門進入王宮，他就坐上王位。","notes":[]},{"n":20,"t":"國中的眾百姓都歡樂，合城也都平靜。他們已將亞她利雅在王宮那裏用刀殺了。","notes":[]},{"n":21,"t":"約阿施登基的時候年方七歲。","notes":[]}]},"12":{"heading":"猶大王約阿施","verses":[{"n":1,"t":"耶戶第七年，約阿施登基，在耶路撒冷作王四十年。他母親名叫西比亞，是別是巴人。","notes":[]},{"n":2,"t":"約阿施在耶何耶大祭司教導他的一切日子，行耶和華眼中看為正的事。","notes":[]},{"n":3,"t":"只是丘壇還沒有廢去，百姓仍在丘壇獻祭燒香。","notes":[]},{"n":4,"t":"約阿施對眾祭司說：「凡獻到耶和華殿分別為聖的銀子，無論是人的贖價，各人生命的贖價， 或自願獻給耶和華殿的銀子，","notes":[]},{"n":5,"t":"祭司可以各自從認識的人收取，用來修理殿的破壞之處，就是在那裏發現的一切破壞之處。」","notes":[]},{"n":6,"t":"然而，到了約阿施王第二十三年，祭司仍未修理殿的破壞之處。","notes":[]},{"n":7,"t":"所以約阿施王召了耶何耶大祭司和眾祭司來，對他們說：「你們怎麼不修理殿的破壞之處呢？現在，不要再從認識的人收銀子了，但要為了殿的破壞之處，把銀子交出來。」","notes":[]},{"n":8,"t":"眾祭司答應不再收百姓的銀子，也不再修理殿的破壞之處。","notes":[]},{"n":9,"t":"耶何耶大祭司取了一個櫃子，在櫃蓋上鑽了一個洞，放在祭壇旁，在進耶和華殿的右邊；守門的祭司將獻到耶和華殿的一切銀子投在櫃裏。","notes":[]},{"n":10,"t":"他們見櫃裏的銀子多了，就叫王的書記和大祭司上來，將耶和華殿裏所得的銀子數點了，包起來。","notes":[]},{"n":11,"t":"他們把秤好了的銀子交在管理耶和華殿督工的手裏，督工就支付給木匠和建造耶和華殿的工人，","notes":[]},{"n":12,"t":"瓦匠和石匠，又買木料和鑿成的石頭，用來修理耶和華殿的破壞之處，以及其他修理殿的各項費用。","notes":[]},{"n":13,"t":"但這些獻到耶和華殿的銀子，並沒有用來造耶和華殿裏的銀杯、鉗子、盤子、號筒和其他的金銀器皿。","notes":[]},{"n":14,"t":"他們把這銀子交給工人，用來整修耶和華的殿。","notes":[]},{"n":15,"t":"他們不用跟這些經手接受銀子去支付工人的人算賬，因為這些人辦事誠實。","notes":[]},{"n":16,"t":"贖愆祭和贖罪祭的銀子沒有獻到耶和華的殿裏，都歸給祭司。","notes":[]},{"n":17,"t":"那時，亞蘭王哈薛上來攻打迦特，攻取了它。哈薛就定意上來攻打耶路撒冷。","notes":[]},{"n":18,"t":"猶大王約阿施將他祖先猶大王約沙法、約蘭、亞哈謝所分別為聖的物和自己所分別為聖的物，以及耶和華殿與王宮府庫裏所有的金子都送給亞蘭王哈薛；哈薛就不上耶路撒冷來了。","notes":[]},{"n":19,"t":"約阿施其餘的事，凡他所做的，不都寫在《猶大列王記》上嗎？","notes":[]},{"n":20,"t":"約阿施的臣僕起來背叛，在下到悉拉路上的米羅宮那裏把他殺了。","notes":[]},{"n":21,"t":"殺他的臣僕就是示米押的兒子約撒拔和朔默的兒子約薩拔。他與祖先同葬在大衛城，他兒子亞瑪謝接續他作王。","notes":["「約撒拔」：有古卷是「約撒甲」。"]}]},"13":{"heading":"以色列王約哈斯","verses":[{"n":1,"t":"亞哈謝的兒子猶大王約阿施第二十三年，耶戶的兒子約哈斯在撒瑪利亞登基作以色列王十七年。","notes":[]},{"n":2,"t":"約哈斯行耶和華眼中看為惡的事，效法尼八的兒子耶羅波安使以色列陷入罪裏的那罪，總不離開。","notes":[]},{"n":3,"t":"於是，耶和華的怒氣向以色列發作，將他們屢次交在亞蘭王哈薛和他兒子便‧哈達的手裏。","notes":[]},{"n":4,"t":"約哈斯懇求耶和華，耶和華就應允他，因為耶和華看見以色列所受的欺壓，因亞蘭王欺壓他們。","notes":[]},{"n":5,"t":"耶和華賜給以色列一位拯救者，使他們脫離亞蘭人的手，於是以色列人仍舊安居在自己的帳棚裏。","notes":[]},{"n":6,"t":"然而他們不離開耶羅波安家使以色列陷入罪裏的那罪，仍行在罪中，並且在撒瑪利亞留下亞舍拉。","notes":[]},{"n":7,"t":"亞蘭王滅絕約哈斯的軍隊，踐踏他們如禾場上的塵沙，只給約哈斯留下五十騎兵，十輛戰車，一萬步兵。","notes":[]},{"n":8,"t":"約哈斯其餘的事，凡他所做的和他英勇的事蹟，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":9,"t":"約哈斯與他祖先同睡，葬在撒瑪利亞，他兒子約阿施接續他作王。","notes":[]},{"n":10,"t":"猶大王約阿施第三十七年，約哈斯的兒子約阿施在撒瑪利亞登基作以色列王十六年。","notes":[],"heads":["以色列王約阿施"]},{"n":11,"t":"他行耶和華眼中看為惡的事，不離開尼八的兒子耶羅波安使以色列陷入罪裏的一切罪，仍行在罪中。","notes":[]},{"n":12,"t":"約阿施其餘的事，凡他所做的和他與猶大王亞瑪謝交戰的英勇事蹟，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":13,"t":"約阿施與他祖先同睡，耶羅波安坐上他的王位。約阿施與以色列諸王一同葬在撒瑪利亞。","notes":[]},{"n":14,"t":"以利沙得了致命的病，以色列王約阿施下來看他，伏在他臉上哭泣，說：「我父啊！我父啊！以色列的戰車和騎兵啊！」","notes":[],"heads":["以利沙去世"]},{"n":15,"t":"以利沙對他說：「把弓箭拿來。」王就拿了弓箭來。","notes":[]},{"n":16,"t":"以利沙對以色列王說：「你用手開弓。」王就用手開弓。以利沙按手在王的手上，","notes":[]},{"n":17,"t":"說：「打開朝東的窗戶。」他就打開。以利沙說：「射箭！」他就射箭。以利沙說：「這是耶和華得勝的箭，是戰勝亞蘭人的箭，因為你必在亞弗攻打亞蘭人，直到滅盡他們。」","notes":[]},{"n":18,"t":"以利沙又說：「拿幾枝箭來。」他就拿了來。以利沙對以色列王說：「打地吧！」他打了三次，就停止了。","notes":[]},{"n":19,"t":"神人向他發怒，說：「你應當擊打五六次，就能攻打亞蘭人直到滅盡；現在你只能打敗亞蘭人三次。」","notes":[]},{"n":20,"t":"以利沙死了，人把他埋葬了。新的一年，摩押人成群結隊入侵境內。","notes":[]},{"n":21,"t":"有人正在埋葬死人，看哪，他們看見一群人來，就把死人拋在以利沙的墳墓裏，逃跑了。死人一碰到以利沙的骸骨，就活過來，用腳站了起來。","notes":[]},{"n":22,"t":"約哈斯在位年間，亞蘭王哈薛屢次欺壓以色列。","notes":[],"heads":["以色列與亞蘭爭戰"]},{"n":23,"t":"耶和華卻因與亞伯拉罕、以撒、雅各所立的約，仍施恩給以色列人，憐憫他們，眷顧他們，不肯滅盡他們，直到現在仍不趕逐他們離開自己面前。","notes":["七十士譯本沒有「直到現在」。"]},{"n":24,"t":"亞蘭王哈薛死了，他兒子便‧哈達接續他作王。","notes":[]},{"n":25,"t":"從前哈薛和約阿施的父親約哈斯交戰，攻取了些城鎮，現在約哈斯的兒子約阿施三次打敗哈薛的兒子便‧哈達，從他手中收回了以色列的城鎮。","notes":[]}]},"14":{"heading":"猶大王亞瑪謝","verses":[{"n":1,"t":"約哈斯的兒子以色列王約阿施第二年，猶大王約阿施的兒子亞瑪謝登基。","notes":[]},{"n":2,"t":"他登基的時候年二十五歲，在耶路撒冷作王二十九年。他母親名叫約耶但，是耶路撒冷人。","notes":[]},{"n":3,"t":"亞瑪謝行耶和華眼中看為正的事，但不如他祖先大衛。他效法他父親約阿施一切所行的。","notes":[]},{"n":4,"t":"只是丘壇還沒有廢去，百姓仍在丘壇獻祭燒香。","notes":[]},{"n":5,"t":"王國在他手裏鞏固的時候，他就把殺他父王的臣僕殺了，","notes":[]},{"n":6,"t":"卻沒有處死殺王兇手的兒子，正如摩西律法書上耶和華所吩咐的說：「不可因子殺父，也不可因父殺子，各人要為自己的罪而死。」","notes":[]},{"n":7,"t":"亞瑪謝在鹽谷殺了一萬以東人，又在戰役中攻取了西拉，稱它為約帖，直到今日。","notes":[]},{"n":8,"t":"那時，亞瑪謝派使者到耶戶的孫子，約哈斯的兒子以色列王約阿施那裏，說：「來，讓我們面對面較量吧！」","notes":[]},{"n":9,"t":"以色列王約阿施派人去見猶大王亞瑪謝，說：「黎巴嫩的蒺藜派人去見黎巴嫩的香柏樹，說：『將你的女兒嫁給我的兒子。』但有一隻野獸經過黎巴嫩，把蒺藜踐踏了。","notes":[]},{"n":10,"t":"你果然打敗了以東，就心高氣傲。你以此為榮，就待在自己家裏算了吧，為何要惹禍，使自己和猶大一同敗亡呢？」","notes":[]},{"n":11,"t":"亞瑪謝卻不肯聽從。於是以色列王約阿施上來，在猶大的伯‧示麥與猶大王亞瑪謝面對面較量。","notes":[]},{"n":12,"t":"猶大敗在以色列面前，他們逃跑，各人逃回自己的帳棚去了。","notes":[]},{"n":13,"t":"以色列王約阿施在伯‧示麥擒住亞哈謝的孫子，約阿施的兒子猶大王亞瑪謝，就來到耶路撒冷，拆毀耶路撒冷的城牆，從以法蓮門直到角門共四百肘。","notes":[]},{"n":14,"t":"他又拿了耶和華殿裏與王宮府庫裏所有的金銀和器皿，並帶著人質，回撒瑪利亞去了。","notes":[]},{"n":15,"t":"約阿施其餘所做的事和他英勇的事蹟，以及他與猶大王亞瑪謝交戰的事，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":16,"t":"約阿施與他祖先同睡，與以色列諸王一同葬在撒瑪利亞，他兒子耶羅波安接續他作王。","notes":[]},{"n":17,"t":"約哈斯的兒子以色列王約阿施死後，猶大王約阿施的兒子亞瑪謝又活了十五年。","notes":[],"heads":["猶大王亞瑪謝去世"]},{"n":18,"t":"亞瑪謝其餘的事，不都寫在《猶大列王記》上嗎？","notes":[]},{"n":19,"t":"耶路撒冷有人背叛亞瑪謝，亞瑪謝逃往拉吉；他們卻派人追到拉吉，在那裏殺了他。","notes":[]},{"n":20,"t":"有人用馬將他馱回，葬在耶路撒冷，與他祖先一同葬在大衛城。","notes":[]},{"n":21,"t":"猶大眾百姓立亞撒利雅接續他父親亞瑪謝作王，那時他年十六歲。","notes":["「亞撒利雅」又名「烏西雅」，下同﹔參王下15．13。"]},{"n":22,"t":"亞瑪謝王與他祖先同睡之後，亞撒利雅收復以拉他回歸猶大，又重新整修。","notes":[]},{"n":23,"t":"約阿施的兒子猶大王亞瑪謝第十五年，以色列王約阿施的兒子耶羅波安在撒瑪利亞登基，作王四十一年。","notes":[],"heads":["以色列王耶羅波安二世"]},{"n":24,"t":"他行耶和華眼中看為惡的事，不離開尼八的兒子耶羅波安使以色列陷入罪裏的一切罪。","notes":[]},{"n":25,"t":"他收回以色列邊界之地，從哈馬口直到亞拉巴海，正如耶和華－以色列的神藉他僕人迦特‧希弗人亞米太的兒子約拿先知所說的。","notes":[]},{"n":26,"t":"因耶和華看見以色列非常艱苦的困境；沒有奴役的，沒有自由的，也沒有人來幫助以色列。","notes":[]},{"n":27,"t":"耶和華並沒有說要將以色列的名從天下塗抹，卻要藉約阿施的兒子耶羅波安拯救他們。","notes":[]},{"n":28,"t":"耶羅波安其餘的事，凡他所做的和他英勇的事蹟，他怎樣作戰，怎樣收復大馬士革和先前屬猶大的哈馬回歸以色列，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":29,"t":"耶羅波安與他祖先以色列諸王同睡，他兒子撒迦利雅接續他作王。","notes":[]}]},"15":{"heading":"猶大王亞撒利雅","verses":[{"n":1,"t":"以色列王耶羅波安第二十七年，猶大王亞瑪謝的兒子亞撒利雅登基。","notes":[]},{"n":2,"t":"他登基的時候年十六歲，在耶路撒冷作王五十二年。他母親名叫耶可利雅，是耶路撒冷人。","notes":[]},{"n":3,"t":"亞撒利雅行耶和華眼中看為正的事，效法他父親亞瑪謝一切所行的。","notes":[]},{"n":4,"t":"只是丘壇還沒有廢去，百姓仍在丘壇獻祭燒香。","notes":[]},{"n":5,"t":"耶和華降災於王，使他長了痲瘋，直到死的那日。他住在隔離的行宮裏，他兒子約坦管理王的家，治理這地的百姓。","notes":[]},{"n":6,"t":"亞撒利雅其餘的事，凡他所做的，不都寫在《猶大列王記》上嗎？","notes":[]},{"n":7,"t":"亞撒利雅與他祖先同睡，與他祖先同葬在大衛城，他兒子約坦接續他作王。","notes":[]},{"n":8,"t":"猶大王亞撒利雅第三十八年，耶羅波安的兒子撒迦利雅登基，在撒瑪利亞作以色列王六個月。","notes":[],"heads":["以色列王撒迦利雅"]},{"n":9,"t":"他行耶和華眼中看為惡的事，效法他祖先所行的，不離開尼八的兒子耶羅波安使以色列陷入罪裏的那罪。","notes":[]},{"n":10,"t":"雅比的兒子沙龍背叛他，在百姓面前擊殺他，篡了他的位。","notes":["「在百姓面前」：七十士譯本的一些抄本是「在以伯蓮」。"]},{"n":11,"t":"撒迦利雅其餘的事，看哪，都寫在《以色列諸王記》上。","notes":[]},{"n":12,"t":"這就是耶和華應許耶戶的話：「你的子孫必坐以色列的王位，直到第四代。」這事果然發生了。","notes":[]},{"n":13,"t":"猶大王烏西雅第三十九年，雅比的兒子沙龍登基，在撒瑪利亞作王一個月。","notes":["「烏西雅」又名「亞撒利雅」，下同；參王下14．21。"],"heads":["以色列王沙龍"]},{"n":14,"t":"迦底的兒子米拿現從得撒上撒瑪利亞，殺了雅比的兒子沙龍，篡了他的位。","notes":[]},{"n":15,"t":"沙龍其餘的事和他陰謀背叛的事，看哪，都寫在《以色列諸王記》上。","notes":[]},{"n":16,"t":"那時，米拿現從得撒起擊殺提斐薩和城中所有的人，以及它周圍的地區，因為他們沒有給他開城門。他擊殺他們，剖開其中所有的孕婦。","notes":["「提斐薩」：七十士譯本的一些抄本是「他普亞」。"]},{"n":17,"t":"猶大王亞撒利雅第三十九年，迦底的兒子米拿現登基，在撒瑪利亞作以色列王十年。","notes":[],"heads":["以色列王米拿現"]},{"n":18,"t":"他行耶和華眼中看為惡的事，終生不離開尼八的兒子耶羅波安使以色列陷入罪裏的那罪。","notes":[]},{"n":19,"t":"亞述王普勒來攻擊這地，米拿現給他一千他連得銀子，為了請普勒幫助他鞏固他所掌握的國度。","notes":[]},{"n":20,"t":"米拿現向以色列所有的富豪索取銀子，要他們各出五十舍客勒，交給亞述王。於是亞述王回去了，不在境內停留。","notes":[]},{"n":21,"t":"米拿現其餘的事，凡他所做的，不都寫在《以色列諸王記》上嗎？","notes":[]},{"n":22,"t":"米拿現與他祖先同睡，他兒子比加轄接續他作王。","notes":[]},{"n":23,"t":"猶大王亞撒利雅第五十年，米拿現的兒子比加轄登基，在撒瑪利亞作以色列王二年。","notes":[],"heads":["以色列王比加轄"]},{"n":24,"t":"他行耶和華眼中看為惡的事，不離開尼八的兒子耶羅波安使以色列陷入罪裏的那罪。","notes":[]},{"n":25,"t":"比加轄的將軍，利瑪利的兒子比加背叛他，在撒瑪利亞王宮的堡壘殺了他。亞珥歌伯和亞利耶並基列的五十人幫助比加；比加擊殺他，篡了他的位。","notes":[]},{"n":26,"t":"比加轄其餘的事，凡他所做的，看哪，都寫在《以色列諸王記》上。","notes":[]},{"n":27,"t":"猶大王亞撒利雅第五十二年，利瑪利的兒子比加登基，在撒瑪利亞作以色列王二十年。","notes":[],"heads":["以色列王比加"]},{"n":28,"t":"他行耶和華眼中看為惡的事，不離開尼八的兒子耶羅波安使以色列陷入罪裏的那罪。","notes":[]},{"n":29,"t":"在以色列王比加的日子，亞述王提革拉‧毗列色來奪取以雲、亞伯‧伯‧瑪迦、亞挪、基低斯、夏瑣、基列、加利利和拿弗他利全地，把這些地方的居民都擄到亞述去了。","notes":["「提革拉‧毗列色」又名「普勒」﹔參19節。"]},{"n":30,"t":"烏西雅的兒子約坦第二十年，以拉的兒子何細亞背叛利瑪利的兒子比加，擊殺他，篡了他的位。","notes":[]},{"n":31,"t":"比加其餘的事，凡他所做的，看哪，都寫在《以色列諸王記》上。","notes":[]},{"n":32,"t":"利瑪利的兒子以色列王比加第二年，猶大王烏西雅的兒子約坦登基。","notes":[],"heads":["猶大王約坦"]},{"n":33,"t":"他登基的時候年二十五歲，在耶路撒冷作王十六年。他母親名叫耶路沙，是撒督的女兒。","notes":[]},{"n":34,"t":"約坦行耶和華眼中看為正的事，效法他父親烏西雅一切所行的。","notes":[]},{"n":35,"t":"只是丘壇還沒有廢去，百姓仍在丘壇獻祭燒香。約坦建了耶和華殿的上門。","notes":[]},{"n":36,"t":"約坦其餘的事，凡他所做的，不都寫在《猶大列王記》上嗎？","notes":[]},{"n":37,"t":"在那些日子，耶和華開始差亞蘭王利汛和利瑪利的兒子比加去攻擊猶大。","notes":[]},{"n":38,"t":"約坦與他祖先同睡，與他祖先同葬在大衛城，他兒子亞哈斯接續他作王。","notes":[]}]},"16":{"heading":"猶大王亞哈斯","verses":[{"n":1,"t":"利瑪利的兒子比加第十七年，猶大王約坦的兒子亞哈斯登基。","notes":[]},{"n":2,"t":"他登基的時候年二十歲，在耶路撒冷作王十六年。他不像他祖先大衛行耶和華－他神眼中看為正的事，","notes":[]},{"n":3,"t":"卻行以色列諸王的道，又照著耶和華從以色列人面前趕出的外邦人所行可憎的事，使他的兒子經火，","notes":[]},{"n":4,"t":"並在丘壇上、山岡上、各青翠樹下獻祭燒香。","notes":[]},{"n":5,"t":"那時，亞蘭王利汛和利瑪利的兒子以色列王比加上來攻打耶路撒冷，圍困亞哈斯，卻不能打勝。","notes":[]},{"n":6,"t":"當時亞蘭王利汛收復以拉他回歸亞蘭，把猶大人從以拉他趕出去。以東人來到以拉他，住在那裏，直到今日。","notes":[]},{"n":7,"t":"亞哈斯派使者到亞述王提革拉‧毗列色那裏，說：「我是你的僕人，你的兒子。現在亞蘭王和以色列王攻擊我，求你上來，救我脫離他們的手。」","notes":[]},{"n":8,"t":"亞哈斯將耶和華殿裏和王宮府庫裏所有的金銀都送給亞述王為禮物。","notes":[]},{"n":9,"t":"亞述王答應了他，上去攻打大馬士革，攻下了城，殺了利汛，把居民擄到吉珥。","notes":[]},{"n":10,"t":"亞哈斯王到大馬士革迎接亞述王提革拉‧毗列色，在大馬士革看見一座壇。亞哈斯王把壇的規模和樣式，以及作法的細節，送到烏利亞祭司那裏。","notes":[]},{"n":11,"t":"烏利亞祭司照著亞哈斯王從大馬士革所送來的一切，在亞哈斯王還未從大馬士革回來之前，築了一座壇。","notes":[]},{"n":12,"t":"王從大馬士革回來，看見壇，走近壇前，在壇上獻祭。","notes":[]},{"n":13,"t":"他燒燔祭和素祭，獻澆酒祭，將平安祭牲的血灑在壇上。","notes":[]},{"n":14,"t":"他移動耶和華面前的銅壇，從殿的前面，新壇和耶和華殿的中間，搬到新壇的北邊。","notes":[]},{"n":15,"t":"亞哈斯王吩咐烏利亞祭司說：「早晨的燔祭、晚上的素祭，王的燔祭、素祭，國內眾百姓的燔祭、素祭、澆酒祭都要燒在大壇上。燔祭牲和其他祭牲的血全都要灑在這壇上。至於銅壇，我要作求問之用。」","notes":[]},{"n":16,"t":"烏利亞祭司就照著亞哈斯王所吩咐的一切做了。","notes":[]},{"n":17,"t":"亞哈斯王把盆座四面的嵌邊拆下來，把盆從座上挪下來，又將銅海從馱銅海的銅牛上搬下來，放在石板鋪的地上。","notes":[]},{"n":18,"t":"他為了亞述王的緣故，在耶和華的殿裏移動殿裏為安息日所蓋的遮棚和王從外面進來的入口。","notes":["「在耶和華的殿裏移動」：有些古譯本是「從耶和華的殿移走」。","「為安息日所蓋的遮棚」：七十士譯本是「寶座的底座」。"]},{"n":19,"t":"亞哈斯其餘所做的事，不都寫在《猶大列王記》上嗎？","notes":[]},{"n":20,"t":"亞哈斯與他祖先同睡， 與他祖先同葬在大衛城，他兒子希西家接續他作王。","notes":[]}]},"17":{"heading":"以色列王何細亞","verses":[{"n":1,"t":"猶大王亞哈斯第十二年，以拉的兒子何細亞在撒瑪利亞登基作以色列王九年。","notes":[]},{"n":2,"t":"他行耶和華眼中看為惡的事，只是不像在他以前的以色列諸王。","notes":[]},{"n":3,"t":"亞述王撒縵以色上來攻擊何細亞，何細亞就服事他，向他進貢。","notes":[]},{"n":4,"t":"何細亞背叛，派使者到埃及王梭那裏，不照往年所行的向亞述王進貢。亞述王知道了，就逮捕他，把他囚在監裏。","notes":["「到埃及王梭那裏」或譯「到梭，埃及王那裏」。"]},{"n":5,"t":"亞述王上來攻擊以色列全地，上到撒瑪利亞，圍困這城三年。","notes":[]},{"n":6,"t":"何細亞第九年，亞述王攻取了撒瑪利亞，把以色列人擄到亞述，安置在哈臘與歌散的哈博河邊，以及瑪代人的城鎮。","notes":[]},{"n":7,"t":"這是因為以色列人得罪了那領他們出埃及地、脫離埃及王法老之手的耶和華－他們的神，去敬畏別神，","notes":[]},{"n":8,"t":"隨從耶和華在以色列人面前所趕出外邦人的風俗和以色列諸王所立的規條。","notes":[]},{"n":9,"t":"以色列人暗中行不正的事，違背耶和華－他們的神，在他們所有的城鎮，從瞭望樓直到堅固城，建築丘壇；","notes":[]},{"n":10,"t":"在各高岡上、各青翠樹下立柱像和亞舍拉；","notes":[]},{"n":11,"t":"在各丘壇上燒香，效法耶和華在他們面前趕出的外邦人所行的，又行惡事，惹耶和華發怒。","notes":[]},{"n":12,"t":"他們事奉偶像，耶和華對他們說：「你們不可做這事。」","notes":[]},{"n":13,"t":"耶和華藉眾先知、先見勸戒以色列和猶大說：「當離開你們的惡行，謹守我的誡命律例，遵行我吩咐你們祖先、藉我僕人眾先知所傳給你們的一切律法。」","notes":[]},{"n":14,"t":"他們卻不聽從，竟硬著頸項，像他們祖先一樣，不信服耶和華－他們的神。","notes":[]},{"n":15,"t":"他們厭棄他的律例，和他與他們列祖所立的約，以及他勸戒他們的話，去隨從虛無的神明，自己成為虛妄，效法周圍的列國，就是耶和華囑咐他們不可效法的。","notes":["「虛無的神明」：原文是「虛無」。"]},{"n":16,"t":"他們離棄耶和華－他們神的一切誡命，為自己鑄造了兩個牛犢的像，立了亞舍拉，敬拜天上的萬象，事奉巴力，","notes":[]},{"n":17,"t":"使他們的兒女經火，占卜，行法術，出賣自己，行耶和華眼中看為惡的事，惹他發怒。","notes":[]},{"n":18,"t":"所以耶和華向以色列大大發怒，從自己面前趕出他們，只剩下猶大一個支派。","notes":[]},{"n":19,"t":"但是，猶大也不遵守耶和華－他們神的誡命，效法以色列所立的規條。","notes":[]},{"n":20,"t":"耶和華就厭棄以色列所有的後裔，使他們受苦，把他們交在搶奪他們的人手中，直到他把他們從自己面前趕出去。","notes":[]},{"n":21,"t":"當他使以色列從大衛家分離出來的時候，他們立尼八的兒子耶羅波安作王。耶羅波安引誘以色列不隨從耶和華，陷入大罪中。","notes":[]},{"n":22,"t":"以色列人行耶羅波安所犯的一切罪，總不離開，","notes":[]},{"n":23,"t":"以致耶和華把他們從自己面前趕出去，正如他藉他僕人眾先知所說的。這樣，以色列人從自己的土地被擄到亞述，直到今日。","notes":[]},{"n":24,"t":"亞述王從巴比倫、古他、亞瓦、哈馬和西法瓦音遷移人來，安置在撒瑪利亞的城鎮，代替以色列人；他們就佔據了撒瑪利亞，住在城中。","notes":[],"heads":["亞述人定居於撒瑪利亞"]},{"n":25,"t":"他們開始住在那裏的時候，不敬畏耶和華，所以耶和華叫獅子進入他們中間，咬死了一些人。","notes":[]},{"n":26,"t":"有人對亞述王說：「你所遷移安置在撒瑪利亞城鎮的各國的人，他們不知道那地之神的規矩，所以他叫獅子進入他們中間。看哪，獅子咬死了他們，因為他們不知道那地之神的規矩。」","notes":[]},{"n":27,"t":"亞述王吩咐說：「當派一個從那裏擄來的祭司回去，叫他住在那裏，將那地之神的規矩指導他們。」","notes":[]},{"n":28,"t":"於是有一個從撒瑪利亞擄去的祭司回來，住在伯特利，教導他們怎樣敬畏耶和華。","notes":[]},{"n":29,"t":"然而，各國的人在所住的城裏為自己製造神像，安置在撒瑪利亞人所建有丘壇的廟中。","notes":[]},{"n":30,"t":"巴比倫人造疏割‧比訥像；古他人造匿甲像；哈馬人造亞示瑪像；","notes":[]},{"n":31,"t":"亞瓦人造匿哈和他珥他像；西法瓦音人用火焚燒兒女，獻給西法瓦音的神明亞得米勒和亞拿米勒。","notes":[]},{"n":32,"t":"他們懼怕耶和華，卻從他們中間立丘壇的祭司，在丘壇的廟中為他們獻祭。","notes":[]},{"n":33,"t":"他們懼怕耶和華，但又事奉自己的神明，從何邦遷來，就隨從那裏的風俗，","notes":[]},{"n":34,"t":"直到如今仍照先前的風俗去行。他們不敬畏耶和華，不遵守耶和華吩咐雅各後裔的律例、典章、律法、誡命；雅各就是從前耶和華起名叫以色列的。","notes":[]},{"n":35,"t":"耶和華曾與他們立約，吩咐他們說：「不可敬畏別神，不可跪拜事奉它們，也不可向它們獻祭。","notes":[]},{"n":36,"t":"惟有那用大能和伸出來的膀臂領你們出埃及地的耶和華，你們當敬畏他，向他跪拜，向他獻祭。","notes":[]},{"n":37,"t":"他給你們寫的律例、典章、律法、誡命，你們應當永遠謹守遵行。你們不可敬畏別神。","notes":[]},{"n":38,"t":"你們不可忘記我與你們所立的約，也不可敬畏別神。","notes":[]},{"n":39,"t":"只要敬畏耶和華－你們的神，他必救你們脫離一切仇敵的手。」","notes":[]},{"n":40,"t":"他們卻不聽從，仍照先前的風俗去行。","notes":[]},{"n":41,"t":"這樣，這些國家又懼怕耶和華，又事奉他們的偶像。他們子子孫孫也都照樣行，效法他們的祖宗，直到今日。","notes":[]}]},"18":{"heading":"猶大王希西家","verses":[{"n":1,"t":"以拉的兒子以色列王何細亞第三年，猶大王亞哈斯的兒子希西家登基。","notes":[]},{"n":2,"t":"他登基的時候年二十五歲，在耶路撒冷作王二十九年。他母親名叫亞比，是撒迦利雅的女兒。","notes":[]},{"n":3,"t":"希西家行耶和華眼中看為正的事，效法他祖先大衛一切所行的。","notes":[]},{"n":4,"t":"他廢去丘壇，毀壞柱像，砍下亞舍拉，打碎摩西所造的銅蛇，因為到那時以色列人仍向銅蛇燒香。人叫銅蛇為尼忽士但。","notes":["「尼忽士但」是音譯，發音與「蛇」和「銅」相近。"]},{"n":5,"t":"希西家倚靠耶和華－以色列的神，在他之前和在他之後的猶大列王中沒有一個像他一樣的。","notes":[]},{"n":6,"t":"因為他緊緊跟隨耶和華，謹守耶和華所吩咐摩西的誡命，總不離開。","notes":[]},{"n":7,"t":"耶和華與他同在，他無論往何處去盡都亨通。他背叛亞述王，不服事他。","notes":[]},{"n":8,"t":"希西家攻擊非利士人，直到迦薩，以及所屬的領土，從瞭望樓到堅固城。","notes":[]},{"n":9,"t":"希西家王第四年，也就是以拉的兒子以色列王何細亞第七年，亞述王撒縵以色上來圍困撒瑪利亞。","notes":[]},{"n":10,"t":"過了三年，他們攻取了城。希西家第六年，以色列王何細亞第九年，撒瑪利亞被攻取了。","notes":[]},{"n":11,"t":"亞述王把以色列人擄到亞述，安置在哈臘與歌散的哈博河邊，以及瑪代人的城鎮。","notes":[]},{"n":12,"t":"這是因為他們不聽從耶和華－他們的神的話，違背了他的約；他們既不聽從，也不遵行耶和華僕人摩西一切所吩咐的。","notes":[]},{"n":13,"t":"希西家王十四年，亞述王西拿基立上來攻擊猶大的一切堅固的城，將城攻取。","notes":[],"heads":["亞述威脅耶路撒冷"]},{"n":14,"t":"猶大王希西家派人到拉吉，亞述王那裏，說：「我錯了，求你撤退離開我；凡你罰我的，我必承當。」於是亞述王罰猶大王希西家三百他連得銀子，三十他連得金子。","notes":[]},{"n":15,"t":"希西家把耶和華殿裏和王宮府庫裏所有的銀子都給了他。","notes":[]},{"n":16,"t":"那時，猶大王希西家將耶和華殿門上的金子和他自己包在柱子上的金子都刮下來，給了亞述王。","notes":[]},{"n":17,"t":"亞述王從拉吉差遣元帥、太監長和將軍率領大軍前往耶路撒冷，到希西家王那裏去。他們上來，到耶路撒冷。他們上來之後，站在上池的水溝旁，在往漂布地的大路上。","notes":["「元帥」：原文是亞述的官職「他珥探」。","「太監長」：原文是亞述的官職「拉伯‧撒利」。","「將軍」：原文是亞述的官職「拉伯‧沙基」，司令官；下同。"]},{"n":18,"t":"他們呼叫王，希勒家的兒子以利亞敬宮廷總管，舍伯那書記和亞薩的兒子約亞史官就出來見他們。","notes":[]},{"n":19,"t":"將軍對他們說：「你們去告訴希西家，大王亞述王如此說：『你倚靠甚麼，讓你如此自信滿滿？","notes":[]},{"n":20,"t":"你說，你有打仗的計謀和能力，我看不過是空話。你到底倚靠誰，竟敢背叛我呢？","notes":[]},{"n":21,"t":"現在，看哪，你自己所倚靠的埃及是那斷裂的葦杖，人若倚靠這杖，它就刺進他的手，穿透它。埃及王法老向所有倚靠他的人都是這樣。","notes":[]},{"n":22,"t":"你們若對我說：我們倚靠耶和華－我們的神，希西家豈不是將神的丘壇和祭壇廢去，並且吩咐猶大和耶路撒冷的人說：你們當在耶路撒冷這壇前敬拜嗎？","notes":[]},{"n":23,"t":"現在你與我主亞述王打賭，我給你兩千匹馬，看你能否派得出騎士來騎牠們。","notes":[]},{"n":24,"t":"若不然，怎能使我主臣僕中最小的一個軍官轉臉而逃呢？你難道要倚靠埃及的戰車和騎兵嗎？","notes":[]},{"n":25,"t":"現在我上來攻擊毀滅這地方，豈不是出於耶和華嗎？耶和華吩咐我說，你上去攻擊這地，毀滅它吧！』」","notes":[]},{"n":26,"t":"希勒家的兒子以利亞敬，舍伯那和約亞對將軍說：「求你用亞蘭話對僕人說，因為我們聽得懂；不要用猶大話對我們說，免得傳到城牆上百姓的耳中。」","notes":[]},{"n":27,"t":"將軍對他們說：「我主差遣我來，豈是單對你和你的主人說這些話嗎？不也是對這些坐在城牆上、要與你們一同吃自己糞、喝自己尿的人說的嗎？」","notes":[]},{"n":28,"t":"於是亞述將軍站著，用猶大話大聲喊著說：「你們當聽大王亞述王的話，","notes":[]},{"n":29,"t":"王如此說：『你們不要被希西家欺哄了，因他不能救你們脫離我的手。","notes":[]},{"n":30,"t":"不要聽憑希西家說服你們倚靠耶和華，他說，耶和華必要拯救我們，這城必不交在亞述王的手中。』","notes":[]},{"n":31,"t":"你們不要聽希西家的話！因亞述王如此說：『你們要與我講和，出來投降我，各人就可以吃自己葡萄樹和無花果樹的果子，喝自己井裏的水，","notes":[]},{"n":32,"t":"等我來領你們到一個地方，與你們本地一樣，就是有五穀和新酒之地，有糧食和葡萄園之地，有橄欖樹和蜂蜜之地，好使你們存活，不至於死。不要聽希西家的話，因為他誤導你們說：耶和華必拯救我們。","notes":[]},{"n":33,"t":"列國的神明有哪一個曾救它本國脫離亞述王的手呢？","notes":[]},{"n":34,"t":"哈馬、亞珥拔的神明在哪裏呢？西法瓦音、希拿、以瓦的神明在哪裏呢？它們曾救撒瑪利亞脫離我的手嗎？","notes":["七十士譯本的一些抄本和其他古譯本有「撒瑪利亞地的神明在哪裏呢？」"]},{"n":35,"t":"這些國的神明有誰曾救自己的國脫離我的手呢？難道耶和華能救耶路撒冷脫離我的手嗎？』」","notes":[]},{"n":36,"t":"百姓靜默不言，一句不答，因為希西家王曾吩咐說：「不要回答他。」","notes":[]},{"n":37,"t":"當下，希勒家的兒子以利亞敬宮廷總管、舍伯那書記和亞薩的兒子約亞史官，都撕裂衣服，來到希西家那裏，將亞述將軍的話告訴他。","notes":[]}]},"19":{"heading":"希西家王派人問以賽亞","verses":[{"n":1,"t":"希西家王聽見了，就撕裂衣服，披上麻布，進了耶和華的殿。","notes":[]},{"n":2,"t":"他差遣以利亞敬宮廷總管和舍伯那書記，並祭司中年長的，都披上麻布，到亞摩斯的兒子以賽亞先知那裏去。","notes":[]},{"n":3,"t":"他們對他說：「希西家如此說：『今日是急難、懲罰、凌辱的日子，就如嬰孩快要出生，卻沒有力氣生產。","notes":[]},{"n":4,"t":"或許耶和華－你的神聽見亞述將軍一切的話，就是他主人亞述王差他來辱罵永生神的話，耶和華－你的神就斥責所聽見的這些話。求你為倖存的餘民揚聲禱告。』」","notes":[]},{"n":5,"t":"希西家王的臣僕來到以賽亞那裏的時候，","notes":[]},{"n":6,"t":"以賽亞對他們說：「要對你們的主人這樣說，耶和華如此說：『你聽見亞述王的僕人褻瀆我的話，不要懼怕。","notes":[]},{"n":7,"t":"看哪，我必驚動他的心，他要聽見風聲就歸回本地，在那裏我必使他倒在刀下。』」","notes":["「驚動他的心」：原文是「使靈進入他裏面」。"]},{"n":8,"t":"亞述將軍聽見亞述王已拔營離開拉吉，就啟程返回，正遇見亞述王去攻打立拿。","notes":[],"heads":["亞述王再度威脅"]},{"n":9,"t":"亞述王聽見有人談論古實王特哈加說：「看哪，他出來要與你爭戰。」於是亞述王又差使者去見希西家，說：","notes":[]},{"n":10,"t":"「你們要對猶大王希西家如此說：『不要聽你所倚靠的神欺哄你說：耶路撒冷必不交在亞述王的手中。","notes":[]},{"n":11,"t":"看哪，你總聽說亞述諸王向列國所行的是盡行滅絕，難道你能倖免嗎？","notes":[]},{"n":12,"t":"我祖先所毀滅的，就是歌散、哈蘭、利色和提‧拉撒的伊甸人；這些國的神明何曾拯救他們呢？","notes":[]},{"n":13,"t":"哈馬的王，亞珥拔的王，西法瓦音城的王，希拿和以瓦的王，都在哪裏呢？』」","notes":[]},{"n":14,"t":"希西家從使者手裏接過書信，讀完了，就上耶和華的殿，在耶和華面前展開書信。","notes":[]},{"n":15,"t":"希西家向耶和華禱告說：「坐在基路伯之上耶和華－以色列的神啊，你，惟有你是地上萬國的神，你創造了天和地。","notes":[]},{"n":16,"t":"耶和華啊，求你側耳而聽；耶和華啊，求你睜眼而看，聽西拿基立差遣使者辱罵永生神的話。","notes":[]},{"n":17,"t":"耶和華啊，亞述諸王果然使列國和列國之地變為荒蕪，","notes":[]},{"n":18,"t":"將列國的神像扔在火裏，因為它們不是神，是人手所造的，是木頭、石頭，所以被滅絕了。","notes":[]},{"n":19,"t":"耶和華－我們的神啊，現在求你救我們脫離亞述王的手，使地上萬國都知道惟獨你－耶和華是神！」","notes":[]},{"n":20,"t":"亞摩斯的兒子以賽亞差人去見希西家，說：「耶和華－以色列的神如此說：你因亞述王西拿基立的事向我祈求，我已聽見了。","notes":[],"heads":["以賽亞給王的信息"]},{"n":21,"t":"耶和華論他這樣說：『少女錫安藐視你，嘲笑你；耶路撒冷向你搖頭。","notes":["「少女錫安」：原文直譯「少女錫安女子」。","「耶路撒冷」：原文直譯「 耶路撒冷女子」。"]},{"n":22,"t":"『你辱罵誰，褻瀆誰，揚起聲來，高舉眼目攻擊誰呢？你攻擊的是以色列的聖者。","notes":[]},{"n":23,"t":"你藉你的使者辱罵主說：我率領許多戰車登上高山，到黎巴嫩的頂端；我要砍伐其中高大的香柏樹和上好的松樹；我必進到極遙遠的住所，進入最茂盛的森林裏。","notes":[]},{"n":24,"t":"我已經在外邦挖井喝水；我必用腳掌踏乾埃及一切的河流。","notes":[]},{"n":25,"t":"『你豈沒有聽見我早先所定、古時所立、現今實現的事嗎？就是讓你去毀壞堅固的城鎮，使它們變為廢墟；","notes":[]},{"n":26,"t":"城裏的居民力量微小，他們驚惶羞愧；像野草，像青菜，如房頂上的草，又如未長成而枯乾的禾稼。","notes":[]},{"n":27,"t":"『你坐下，你出去，你進來，你向我發烈怒，我都知道。","notes":[]},{"n":28,"t":"因你向我發烈怒，你的狂傲上達我耳中，我要用鉤子鉤住你的鼻子，將嚼環放在你口裏，使你從原路轉回去。』","notes":[]},{"n":29,"t":"「這是給你的預兆：你們今年要吃野生的，明年也要吃自長的；後年，你們就要耕種收割，栽葡萄園，吃其中的果子。","notes":[]},{"n":30,"t":"猶大家所逃脫剩餘的，仍要往下扎根，向上結果。","notes":[]},{"n":31,"t":"必有剩餘的民從耶路撒冷而出，有逃脫的人從錫安山而來。萬軍之耶和華的熱心必成就這事。","notes":[]},{"n":32,"t":"「所以耶和華論亞述王如此說：他必不得來到這城，也不在這裏射箭，不得拿盾牌到城前，也不建土堆攻城。","notes":[]},{"n":33,"t":"他從哪條路來，必從那條路回去，必不得來到這城。這是耶和華說的。","notes":[]},{"n":34,"t":"因我為自己的緣故，又為我僕人大衛的緣故，必保護拯救這城。」","notes":[]},{"n":35,"t":"當夜，耶和華的使者出去，在亞述營中殺了十八萬五千人。清早有人起來，看哪，都是死屍。","notes":[]},{"n":36,"t":"亞述王西拿基立就拔營回去，住在尼尼微。","notes":[]},{"n":37,"t":"一日，他在他的神明尼斯洛廟裏叩拜，他兒子亞得米勒和沙利色用刀殺了他，然後逃到亞拉臘地；他兒子以撒‧哈頓接續他作王。","notes":[]}]},"20":{"heading":"希西家病重康復","verses":[{"n":1,"t":"那些日子，希西家病得要死，亞摩斯的兒子以賽亞先知來見他，對他說：「耶和華如此說：『你當留遺囑給你的家，因為你必死，不能活了。』」","notes":[]},{"n":2,"t":"希西家轉臉朝牆，向耶和華禱告說：","notes":[]},{"n":3,"t":"「耶和華啊，求你記念我在你面前怎樣存完全的心，按誠實行事，又做你眼中看為善的事。」希西家就痛哭。","notes":[]},{"n":4,"t":"以賽亞出來，還沒有離開中院，耶和華的話就臨到他，說：","notes":[]},{"n":5,"t":"「你回去告訴我百姓的君王希西家說：耶和華－你祖先大衛的神如此說：『我聽見了你的禱告，看見了你的眼淚。看哪，我必醫治你；到第三日，你必上到耶和華的殿。","notes":[]},{"n":6,"t":"我必加添你十五年的壽數，並且我要救你和這城脫離亞述王的手。我為自己和我僕人大衛的緣故，必保護這城。』」","notes":[]},{"n":7,"t":"以賽亞說：「取一塊無花果餅來。」人就取了來，貼在瘡上，王就痊癒了。","notes":[]},{"n":8,"t":"希西家對以賽亞說：「耶和華必醫治我，到第三日我能上耶和華的殿，有甚麼預兆呢？」","notes":[]},{"n":9,"t":"以賽亞說：「耶和華必成就他所說的這話。這是耶和華給你的預兆：你要日影向前進十度呢？或是要往後退十度呢？」","notes":[]},{"n":10,"t":"希西家說：「日影向前進十度容易；不，讓日影往後退十度吧。」","notes":[]},{"n":11,"t":"以賽亞先知求告耶和華，耶和華就使亞哈斯日晷上照下來的日影，往後退了十度。","notes":[]},{"n":12,"t":"那時，巴拉但的兒子，巴比倫王米羅達‧巴拉但聽見希西家生病了，就送書信和禮物給他。","notes":[],"heads":["巴比倫來的使者"]},{"n":13,"t":"希西家聽使者的話，就將自己一切寶庫裏的金子、銀子、香料、貴重的膏油和他軍械庫裏的兵器，以及他所有的財寶，都給他們看；在他家中和全國之內，希西家沒有一樣東西不給他們看的。","notes":["「聽使者的話」：有古卷、七十士譯本和其他古譯本是「因他們而歡喜」。"]},{"n":14,"t":"於是以賽亞先知到希西家王那裏去，對他說：「這些人說了些甚麼？他們從哪裏來見你？」希西家說：「他們從遠方的巴比倫來。」","notes":[]},{"n":15,"t":"以賽亞說：「他們在你家裏看見了甚麼？」希西家說：「凡我家中所有的，他們都看見了；我財寶中沒有一樣東西不給他們看的。」","notes":[]},{"n":16,"t":"以賽亞對希西家說：「你要聽耶和華的話：","notes":[]},{"n":17,"t":"耶和華說：『看哪，日子將到，凡你家裏所有的，並你祖先積蓄到如今的一切，都要被擄到巴比倫去，不留下一樣；","notes":[]},{"n":18,"t":"從你本身所生的孩子，其中必有被擄到巴比倫王宮當太監的。』」","notes":[]},{"n":19,"t":"希西家對以賽亞說：「你所說耶和華的話甚好。」因為他想：「在我有生之年豈不是有太平和安穩嗎？」","notes":[]},{"n":20,"t":"希西家其餘的事和他一切英勇的事蹟，他怎樣造池、挖溝、引水入城，不都寫在《猶大列王記》上嗎？","notes":[],"heads":["希西家逝世"]},{"n":21,"t":"希西家與他祖先同睡，他兒子瑪拿西接續他作王。","notes":[]}]},"21":{"heading":"猶大王瑪拿西","verses":[{"n":1,"t":"瑪拿西登基的時候年十二歲，在耶路撒冷作王五十五年。他母親名叫協西巴。","notes":[]},{"n":2,"t":"瑪拿西行耶和華眼中看為惡的事，效法耶和華在以色列人面前趕出的列國那些可憎的事。","notes":[]},{"n":3,"t":"他重新建築他父親希西家所毀壞的丘壇，又為巴力築壇，造亞舍拉，效法以色列王亞哈所行的，敬拜天上的萬象，事奉它們。","notes":[]},{"n":4,"t":"他在耶和華殿中築壇，耶和華曾指著這殿說：「我必立我的名在耶路撒冷。」","notes":[]},{"n":5,"t":"他在耶和華殿的兩個院子為天上的萬象築壇，","notes":[]},{"n":6,"t":"並使他的兒子經火，又觀星象，行法術，求問招魂的和行巫術的，多行耶和華眼中看為惡的事，惹他發怒。","notes":[]},{"n":7,"t":"他又把自己所造的亞舍拉雕像立在殿內，耶和華曾對大衛和他兒子所羅門說：「我在以色列眾支派中所選擇的耶路撒冷和這殿，必立我的名，直到永遠。","notes":[]},{"n":8,"t":"只要以色列人謹守遵行我一切所吩咐的和我僕人摩西所吩咐的一切律法，我就不再使他們的腳挪移，離開我所賜給他們列祖之地。」","notes":[]},{"n":9,"t":"他們卻不聽從，並且瑪拿西引誘他們行惡，比耶和華在以色列人面前所滅的列國更嚴重。","notes":[]},{"n":10,"t":"耶和華藉他僕人眾先知說：","notes":[]},{"n":11,"t":"「因猶大王瑪拿西行這些可憎的惡事，比先前亞摩利人所行的一切更壞，使猶大人拜偶像，陷入罪裏，","notes":[]},{"n":12,"t":"所以耶和華－以色列的神如此說：看哪，我必降禍於耶路撒冷和猶大，凡聽見的人都必雙耳齊鳴。","notes":[]},{"n":13,"t":"我必用量撒瑪利亞的準繩和亞哈家的鉛垂線拉在耶路撒冷之上；我必擦拭耶路撒冷，如人擦盤子，把盤子翻過來。","notes":[]},{"n":14,"t":"我必撇棄我產業中的餘民，把他們交在仇敵手中，使他們成為所有仇敵的擄物和掠物，","notes":[]},{"n":15,"t":"因為自從他們的祖先出埃及的那日直到今日，他們常行我眼中看為惡的事，惹我發怒。」","notes":[]},{"n":16,"t":"瑪拿西行耶和華眼中看為惡的事，使猶大陷入罪裏，又流許多無辜人的血，直到這血充滿了耶路撒冷，從這邊到那邊。","notes":[]},{"n":17,"t":"瑪拿西其餘的事，凡他所做的和他所犯的罪，不都寫在《猶大列王記》上嗎？","notes":[]},{"n":18,"t":"瑪拿西與他祖先同睡，葬在自己王宮的園子，烏撒園裏，他兒子亞們接續他作王。","notes":[]},{"n":19,"t":"亞們登基的時候年二十二歲，在耶路撒冷作王二年。他母親名叫米舒利密，是約提巴人哈魯斯的女兒。","notes":[],"heads":["猶大王亞們"]},{"n":20,"t":"亞們行耶和華眼中看為惡的事，效法他父親瑪拿西所行的。","notes":[]},{"n":21,"t":"他行他父親一切所行的道，事奉他父親所事奉的偶像，敬拜它們，","notes":[]},{"n":22,"t":"離棄耶和華－他列祖的神，不遵行耶和華的道。","notes":[]},{"n":23,"t":"亞們的臣僕背叛他，在宮裏殺了王。","notes":[]},{"n":24,"t":"但這地的百姓殺了所有背叛亞們王的人；這地的百姓立他兒子約西亞接續他作王。","notes":[]},{"n":25,"t":"亞們其餘所做的事，不都寫在《猶大列王記》上嗎？","notes":[]},{"n":26,"t":"亞們葬在烏撒園內自己的墳墓裏，他兒子約西亞接續他作王。","notes":[]}]},"22":{"heading":"猶大王約西亞","verses":[{"n":1,"t":"約西亞登基的時候年八歲，在耶路撒冷作王三十一年。他母親名叫耶底大，是波斯加人亞大雅的女兒。","notes":[]},{"n":2,"t":"約西亞行耶和華眼中看為正的事，行他祖先大衛一切所行的道，不偏左右。","notes":[]},{"n":3,"t":"約西亞王十八年，王派米書蘭的孫子，亞薩利雅的兒子沙番書記上耶和華殿去，說：","notes":[],"heads":["發現律法書"]},{"n":4,"t":"「你上到希勒家大祭司那裏，請他把奉獻到耶和華殿的銀子，就是門口的守衛從百姓中收來的銀子，結算清楚，","notes":[]},{"n":5,"t":"交在管理耶和華殿督工的手裏，由他們支付給在耶和華殿裏做工的人，好修理殿的破壞之處，","notes":[]},{"n":6,"t":"就是木匠、工人和瓦匠，又買木料和鑿成的石頭，來整修殿宇。","notes":[]},{"n":7,"t":"但他們不用跟這些經手接受銀子的人算帳，因為這些人辦事誠實。」","notes":[]},{"n":8,"t":"希勒家大祭司對沙番書記說：「我在耶和華殿裏發現了律法書。」希勒家把書遞給沙番，沙番就讀了。","notes":[]},{"n":9,"t":"沙番書記到王那裏，把這事回覆王說：「你的僕人已把殿裏所發現的銀子倒出來，交在管理耶和華殿督工的手裏了。」","notes":[]},{"n":10,"t":"沙番書記又向王報告說：「希勒家祭司遞給我一卷書。」沙番就在王面前朗讀那書。","notes":[]},{"n":11,"t":"王聽見律法書上的話，就撕裂衣服。","notes":[]},{"n":12,"t":"王吩咐希勒家祭司與沙番的兒子亞希甘、米該亞的兒子亞革波、沙番書記和王的臣僕亞撒雅，說：","notes":[]},{"n":13,"t":"「你們去，以所發現這書上的話，為我、為百姓、為全猶大求問耶和華；因為我們祖先沒有聽從這書上的話，沒有遵照一切所寫有關我們的去行，耶和華就向我們大發烈怒。」","notes":["「所寫有關我們的」：有古卷和七十士譯本是「它上面所寫的」；參代下34．21。"]},{"n":14,"t":"於是，希勒家祭司和亞希甘、亞革波、沙番、亞撒雅都去見戶勒大女先知，她是掌管禮服的沙龍的妻子；沙龍是哈珥哈斯的孫子，特瓦的兒子。戶勒大住在耶路撒冷第二區。他們向她請教。","notes":[]},{"n":15,"t":"她對他們說：「耶和華－以色列的神如此說：『你們可以回覆那派你們來見我的人說，","notes":[]},{"n":16,"t":"耶和華如此說：看哪，我必照著猶大王所讀那書上的一切話，降禍於這地方和其上的居民。","notes":[]},{"n":17,"t":"因為他們離棄我，向別神燒香，用他們手所做的一切惹我發怒，所以我的憤怒必向這地方發作，總不止息。』","notes":[]},{"n":18,"t":"然而，派你們來求問耶和華的猶大王，你們要這樣回覆他：『耶和華－以色列的神如此說：至於你所聽見的話，","notes":[]},{"n":19,"t":"就是聽見我指著這地方和其上的居民說，要使這地方變為荒蕪、百姓受詛咒的話，你的心就軟化，在耶和華面前謙卑下來，撕裂衣服，向我哭泣，因此我應允你。這是耶和華說的。","notes":[]},{"n":20,"t":"因此，看哪，我必使你歸到你祖先那裏，平安地進入墳墓；我要降於這地方的一切災禍，你不會親眼看見。』」他們就去把這話回覆王。","notes":[]}]},"23":{"heading":"約西亞的改革","verses":[{"n":1,"t":"王派人召集猶大和耶路撒冷的眾長老來。","notes":[]},{"n":2,"t":"王和猶大眾人、耶路撒冷的居民、祭司、先知，以及所有的百姓，無論大小，都一同上到耶和華的殿去；王把耶和華殿裏所發現的約書上一切的話讀給他們聽。","notes":[]},{"n":3,"t":"王站在柱子旁邊，在耶和華面前立約，要盡心盡性跟從耶和華，遵守他的誡命、法度、律例，實行這書上所寫這約的話。全體百姓都願遵守所立的約。","notes":[]},{"n":4,"t":"王吩咐希勒家大祭司和副祭司，以及把守殿門的，把那些為巴力和亞舍拉，以及天上萬象所造的器皿，都從耶和華殿裏搬出來，在耶路撒冷外汲淪的田間燒了，把灰拿到伯特利去。","notes":[]},{"n":5,"t":"從前猶大列王所立拜偶像的祭司，在猶大城鎮的丘壇和耶路撒冷周圍燒香，現在王都廢去，他們是向巴力和日、月、行星，以及天上萬象燒香的人。","notes":[]},{"n":6,"t":"他把亞舍拉從耶和華殿裏搬到耶路撒冷外的汲淪溪，在汲淪溪邊焚燒，打碎成灰，把灰撒在平民的墳上。","notes":[]},{"n":7,"t":"他又拆毀耶和華殿裏男的廟妓的屋子，就是婦女在那裏為亞舍拉編織衣服的屋子。","notes":[]},{"n":8,"t":"他從猶大的城鎮將眾祭司帶來，從迦巴直到別是巴，玷污祭司燒香的丘壇。他又拆毀城門旁的丘壇，這丘壇是在約書亞市長的城門前，在人進城門的左邊。","notes":[]},{"n":9,"t":"只是丘壇的祭司不登耶路撒冷耶和華的壇，僅在他們弟兄中間吃無酵餅。","notes":[]},{"n":10,"t":"他又玷污欣嫩子谷的陀斐特，不許人在那裏使兒女經火獻給摩洛。","notes":[]},{"n":11,"t":"他把在耶和華殿門旁、靠近拿單‧米勒官員走廊的屋子，猶大列王獻給太陽的馬廢去，且用火焚燒獻給太陽的戰車。","notes":[]},{"n":12,"t":"猶大列王在亞哈斯樓房頂上所築的壇和瑪拿西在耶和華殿兩院中所築的壇，王都拆毀，從那裏移走，把灰倒在汲淪溪中。","notes":["「移走」：原文直譯「跑走」。"]},{"n":13,"t":"從前以色列王所羅門在耶路撒冷東邊、邪僻山南邊為西頓人可憎的亞斯她錄、摩押人可憎的基抹、亞捫人可憎的米勒公所築的丘壇，王都玷污了，","notes":["「邪僻山」就是「橄欖山」。"]},{"n":14,"t":"又打碎柱像，砍下亞舍拉，用人的骨頭填滿那地方。","notes":[]},{"n":15,"t":"此外，在伯特利丘壇的壇，就是尼八的兒子耶羅波安所築、使以色列人陷入罪裏的，他也把這壇和丘壇都拆毀了，又焚燒丘壇，打碎成灰，並焚燒了亞舍拉。","notes":["「又焚燒丘壇」：七十士譯本是「把石頭拆下來」。"]},{"n":16,"t":"約西亞轉頭，看見山上的墳墓，就派人取出墳墓裏的骸骨，燒在壇上，玷污了壇，正如從前耶羅波安在節期中站在壇旁時，耶和華藉神人所宣告的話。約西亞轉頭看見了宣告這些話的神人的墳墓。","notes":["「正如從前...墳墓」是根據七十士譯本；原文是「正如耶和華從前藉宣告這些事的神人所宣告的話」。"]},{"n":17,"t":"他說：「我看見的這碑是甚麼呢？」那城裏的人對他說：「這是神人的墳墓，他從猶大來，宣告了王向伯特利的壇所做的這些事。」","notes":[]},{"n":18,"t":"約西亞說：「讓他安息吧！不要挪移他的骸骨。」他們就保存了他的骸骨和從撒瑪利亞來的那先知的骸骨。","notes":[]},{"n":19,"t":"從前以色列諸王在撒瑪利亞的城鎮所建一切惹動怒氣的丘壇的廟，約西亞也都廢去了，正如他在伯特利所做的。","notes":[]},{"n":20,"t":"他又把在那裏所有丘壇的祭司都殺在壇上，並在壇上燒人的骨頭。於是他回耶路撒冷去了。","notes":[]},{"n":21,"t":"王吩咐眾百姓說：「你們當照這約書上所寫的，向耶和華－你們的神守逾越節。」","notes":[],"heads":["約西亞守逾越節"]},{"n":22,"t":"自從士師治理以色列，到以色列諸王、猶大列王在位的一切日子，從來沒有守過這樣的逾越節，","notes":[]},{"n":23,"t":"只有在約西亞王十八年，才在耶路撒冷向耶和華守這逾越節。","notes":[]},{"n":24,"t":"此外，在猶大地和耶路撒冷所見那些招魂的、行巫術的，家中的神像和偶像，以及一切可憎之物，約西亞盡都除掉，實行了希勒家祭司在耶和華殿裏所發現的律法書上所寫的話。","notes":[],"heads":["約西亞的其他改革"]},{"n":25,"t":"在約西亞以前，沒有王像他盡心、盡性、盡力地歸向耶和華，遵行摩西的一切律法；在他以後，也沒有興起一個王像他。","notes":[]},{"n":26,"t":"然而，耶和華向猶大所發猛烈的怒氣仍不止息，因為瑪拿西種種的惡事激怒了他。","notes":[]},{"n":27,"t":"耶和華說：「我也必將猶大從我面前趕出，如同趕出以色列一樣。我必撇棄我從前所選擇的這城耶路撒冷和我所說我的名必留在那裏的殿。」","notes":[]},{"n":28,"t":"約西亞其餘的事，凡他所做的，不都寫在《猶大列王記》上嗎？","notes":[],"heads":["約西亞逝世"]},{"n":29,"t":"約西亞的日子，埃及王法老尼哥上到幼發拉底河，到亞述王那裏；約西亞王去迎擊他。埃及王在米吉多看見約西亞，就殺了他。","notes":[]},{"n":30,"t":"他的臣僕用車把他的屍體從米吉多送到耶路撒冷，葬在他自己的墳墓裏。這地的百姓選約西亞的兒子約哈斯，膏立他，接續他父親作王。","notes":[]},{"n":31,"t":"約哈斯登基的時候年二十三歲，在耶路撒冷作王三個月。他母親名叫哈慕她，是立拿人耶利米的女兒。","notes":[],"heads":["猶大王約哈斯"]},{"n":32,"t":"約哈斯行耶和華眼中看為惡的事，效法他祖先一切所行的。","notes":[]},{"n":33,"t":"法老尼哥把約哈斯監禁在哈馬地的利比拉，不許他在耶路撒冷作王，又罰這地一百他連得銀子，一他連得金子。","notes":["「法老尼哥...作王」：原文另譯「當約哈斯在耶路撒冷作王的時候，法老尼哥把他監禁在哈馬地的利比拉」。"]},{"n":34,"t":"法老尼哥立約西亞的兒子以利雅敬接續他父親約西亞作王，給他改名叫約雅敬，卻把約哈斯帶到埃及，他就死在那裏。","notes":[]},{"n":35,"t":"約雅敬進貢金銀給法老，照著法老的指示在這地徵收銀子，向這地的百姓按各人的能力索取金銀，要送給法老尼哥。","notes":[],"heads":["猶大王約雅敬"]},{"n":36,"t":"約雅敬登基的時候年二十五歲，在耶路撒冷作王十一年。他母親名叫西布大，是魯瑪人毗大雅的女兒。","notes":[]},{"n":37,"t":"約雅敬行耶和華眼中看為惡的事，效法他祖先一切所行的。","notes":[]}]},"24":{"heading":"猶大王約雅斤","verses":[{"n":1,"t":"約雅敬的日子，巴比倫王尼布甲尼撒上來；約雅敬服事他三年，以後又背叛他。","notes":[]},{"n":2,"t":"耶和華派迦勒底、亞蘭、摩押和亞捫人的軍隊來攻擊約雅敬；耶和華派他們來攻擊猶大，要毀滅它，正如耶和華藉他僕人眾先知所說的話。","notes":[]},{"n":3,"t":"這事臨到猶大，誠然是出於耶和華的命令，要把猶大從自己面前趕出去，是因瑪拿西所犯的一切罪，","notes":["「命令」：七十士譯本和其他古譯本是「憤怒」。"]},{"n":4,"t":"又因他流無辜人的血，使無辜人的血充滿耶路撒冷；耶和華不願赦免。","notes":[]},{"n":5,"t":"約雅敬其餘的事，凡他所做的，不都寫在《猶大列王記》上嗎？","notes":[]},{"n":6,"t":"約雅敬與他祖先同睡，他兒子約雅斤接續他作王。","notes":[]},{"n":7,"t":"埃及王不再從他的國出征，因為巴比倫王把埃及王所管之地，從埃及溪谷直到幼發拉底河都奪去了。","notes":[]},{"n":8,"t":"約雅斤登基的時候年十八歲，在耶路撒冷作王三個月。他母親名叫尼護施她，是耶路撒冷人以利拿單的女兒。","notes":[]},{"n":9,"t":"約雅斤行耶和華眼中看為惡的事，效法他父親一切所行的。","notes":[]},{"n":10,"t":"那時，巴比倫王尼布甲尼撒的軍兵上到耶路撒冷，城被圍困。","notes":[]},{"n":11,"t":"當他的軍兵圍困城的時候，巴比倫王尼布甲尼撒親自來到耶路撒冷。","notes":[]},{"n":12,"t":"猶大王約雅斤和他母親、臣僕、王子、官員一同出來，向巴比倫王投降。巴比倫王俘擄了他，那時是巴比倫王第八年。","notes":[]},{"n":13,"t":"巴比倫王把耶和華殿裏和王宮裏一切的寶物從那裏拿走，又把以色列王所羅門所造耶和華殿裏一切的金器都毀壞了，正如耶和華所說的。","notes":[]},{"n":14,"t":"他把全耶路撒冷眾領袖和所有大能的勇士，共一萬人，連同所有的木匠和鐵匠都擄了去，只留下這地最貧窮的百姓。","notes":[]},{"n":15,"t":"他把約雅斤和他的母親、后妃、官員，以及這地的貴族，都從耶路撒冷擄到巴比倫去了，","notes":[]},{"n":16,"t":"又把所有的勇士七千人，木匠和鐵匠一千人，全是能上陣的勇士，都擄到巴比倫去了。","notes":[]},{"n":17,"t":"巴比倫王立約雅斤的叔父瑪探雅取代他作王，給瑪探雅改名叫西底家。","notes":[]},{"n":18,"t":"西底家登基的時候年二十一歲，在耶路撒冷作王十一年。他母親名叫哈慕她，是立拿人耶利米的女兒。","notes":[],"heads":["猶大王西底家"]},{"n":19,"t":"西底家行耶和華眼中看為惡的事，正如約雅敬一切所行的。","notes":[]},{"n":20,"t":"因此，耶和華向耶路撒冷和猶大發怒，以致把他們從自己面前趕出去。西底家背叛巴比倫王。","notes":[]}]},"25":{"heading":"聖殿被毀","verses":[{"n":1,"t":"西底家作王第九年十月初十，巴比倫王尼布甲尼撒率領全軍前來攻擊耶路撒冷，對城安營，四圍築堡壘攻城。","notes":[]},{"n":2,"t":"城被圍困，直到西底家王十一年。","notes":[]},{"n":3,"t":"四月初九，城裏的饑荒非常嚴重，當地的百姓都沒有糧食。","notes":[]},{"n":4,"t":"城被攻破，士兵全都在夜間從靠近王的花園、兩城牆中間的門逃跑。迦勒底人正在四圍攻城，王就往亞拉巴逃去。","notes":[]},{"n":5,"t":"迦勒底的軍隊追趕王，在耶利哥的平原追上他；他的全軍都離開他潰散了。","notes":[]},{"n":6,"t":"迦勒底人就拿住王，帶他到利比拉的巴比倫王那裏；他們就判他的罪。","notes":[]},{"n":7,"t":"他們在西底家眼前殺了他的兒女，挖了西底家的眼睛，用銅鏈鎖著他，帶到巴比倫去。","notes":[]},{"n":8,"t":"巴比倫王尼布甲尼撒十九年五月初七，巴比倫王的臣僕尼布撒拉旦護衛長進入耶路撒冷，","notes":[]},{"n":9,"t":"他焚燒了耶和華的殿、王宮和耶路撒冷一切的房屋；用火焚燒所有大戶人家的房屋。","notes":[]},{"n":10,"t":"跟從護衛長的迦勒底全軍拆毀了耶路撒冷四圍的城牆。","notes":[]},{"n":11,"t":"那時尼布撒拉旦護衛長將城裏剩下的百姓和那些投降巴比倫王的人，以及其餘的眾人，都擄去了。","notes":[]},{"n":12,"t":"但護衛長留下一些當地最窮的人，叫他們修整葡萄園，耕種田地。","notes":[]},{"n":13,"t":"耶和華殿的銅柱並殿內的盆座和銅海，迦勒底人都打碎了，把那些銅運到巴比倫去。","notes":[]},{"n":14,"t":"他們又帶走鍋、鏟子、鉗子、勺子和供奉用的一切銅器；","notes":[]},{"n":15,"t":"火盆和碗，無論金的銀的，護衛長都帶走了；","notes":[]},{"n":16,"t":"還有所羅門為耶和華殿所造的兩根柱子、一個銅海和盆座，這一切器皿的銅多得無法可秤。","notes":[]},{"n":17,"t":"這一根柱子高十八肘，柱上有銅頂，銅頂高三肘；銅頂的周圍有網子和石榴，也都是銅的。第二根柱子與此相同，也有網子。","notes":[]},{"n":18,"t":"護衛長拿住西萊雅大祭司、西番亞副祭司和門口的三個守衛，","notes":[],"heads":["猶大人被擄到巴比倫"]},{"n":19,"t":"又從城中拿住一個管理士兵的官，並在城裏所找到王面前的五個親信，和召募當地百姓之將軍的書記官，以及在城中找到的六十個當地百姓。","notes":["「官」或譯「太監」。"]},{"n":20,"t":"尼布撒拉旦護衛長把這些人帶到利比拉的巴比倫王那裏。","notes":[]},{"n":21,"t":"巴比倫王擊殺他們，在哈馬地的利比拉把他們處死。這樣，猶大人就被擄去離開本地。","notes":[]},{"n":22,"t":"至於猶大地剩下的百姓，就是巴比倫王尼布甲尼撒所留下的，巴比倫王立了沙番的孫子，亞希甘的兒子基大利作他們的省長。","notes":[],"heads":["基大利出任省長"]},{"n":23,"t":"所有的軍官和屬他們的人聽見巴比倫王立了基大利作省長，尼探雅的兒子以實瑪利、加利亞的兒子約哈難、尼陀法人單戶蔑的兒子西萊雅、瑪迦人的兒子雅撒尼亞，和屬他們的人，都來到米斯巴的基大利那裏。","notes":[]},{"n":24,"t":"基大利向他們和屬他們的人起誓說：「你們不必懼怕迦勒底臣僕，只管住在這地，服事巴比倫王，就可以得福。」","notes":[]},{"n":25,"t":"七月中，王室後裔以利沙瑪的孫子，尼探雅的兒子以實瑪利帶著十個人來，擊殺了基大利和同他在米斯巴的猶大人與迦勒底人，把他們殺死。","notes":[]},{"n":26,"t":"於是眾人，無論大小，連同軍官，因為懼怕迦勒底人，都起身逃到埃及去了。","notes":[]},{"n":27,"t":"巴比倫王以未‧米羅達作王的元年，就是猶大王約雅斤被擄後三十七年，十二月二十七日，他使猶大王約雅斤抬起頭來，提他出監，","notes":[],"heads":["約雅斤被釋放"]},{"n":28,"t":"對他說好話，使他的位高過與他一同被擄在巴比倫眾王的位；","notes":[]},{"n":29,"t":"又給他脫了囚服，使他終身常在巴比倫王面前吃飯。","notes":[]},{"n":30,"t":"王賜給他日常需用的食物，每日一份，終身都是這樣。","notes":[]}]}},"1CH":{"1":{"heading":"從亞當到亞伯拉罕","verses":[{"n":1,"t":"亞當，塞特，以挪士，","notes":[]},{"n":2,"t":"該南，瑪勒列，雅列，","notes":[]},{"n":3,"t":"以諾，瑪土撒拉，拉麥，","notes":[]},{"n":4,"t":"挪亞，閃，含，雅弗。","notes":[]},{"n":5,"t":"雅弗的兒子是歌篾、瑪各、瑪代、雅完、土巴、米設和提拉。","notes":[]},{"n":6,"t":"歌篾的兒子是亞實基拿、低法和陀迦瑪。","notes":["「低法」：有古卷是「利法」；參創 10．3。"]},{"n":7,"t":"雅完的兒子是以利沙、他施、基提和羅單人。","notes":["「羅單人」：參創10．4。"]},{"n":8,"t":"含的兒子是古實、麥西、弗和迦南。","notes":["「麥西」即「埃及」；下同。"]},{"n":9,"t":"古實的兒子是西巴、哈腓拉、撒弗他、拉瑪和撒弗提迦。拉瑪的兒子是示巴和底但。","notes":[]},{"n":10,"t":"古實又生寧錄，他是地上第一個勇士。","notes":[]},{"n":11,"t":"麥西生路低人、亞拿米人、利哈比人、拿弗土希人、","notes":[]},{"n":12,"t":"帕斯魯細人、迦斯路希人和迦斐託人；非利士人是從迦斐託人出來的。","notes":["「迦斐託人」：原文是「迦斯路希人」。"]},{"n":13,"t":"迦南生了長子西頓，又生赫","notes":[]},{"n":14,"t":"和耶布斯人、亞摩利人、革迦撒人、","notes":[]},{"n":15,"t":"希未人、亞基人、西尼人、","notes":[]},{"n":16,"t":"亞瓦底人、洗瑪利人和哈馬人。","notes":[]},{"n":17,"t":"閃的兒子是以攔、亞述、亞法撒、路德、亞蘭、烏斯、戶勒、基帖和米設。","notes":["「米設」：創10．23是「瑪施」。"]},{"n":18,"t":"亞法撒生沙拉；沙拉生希伯。","notes":[]},{"n":19,"t":"希伯生了兩個兒子：一個名叫法勒，因為那時人分地居住；法勒的兄弟名叫約坍。","notes":["「法勒」意思是「分」。"]},{"n":20,"t":"約坍生亞摩答、沙列、哈薩瑪非、耶拉、","notes":[]},{"n":21,"t":"哈多蘭、烏薩、德拉、","notes":[]},{"n":22,"t":"以巴錄、亞比瑪利、示巴、","notes":["「以巴錄」：創10．28稱「俄巴路」。"]},{"n":23,"t":"阿斐、哈腓拉和約巴。這些都是約坍的兒子。","notes":[]},{"n":24,"t":"閃，亞法撒，沙拉，","notes":[]},{"n":25,"t":"希伯，法勒，拉吳，","notes":[]},{"n":26,"t":"西鹿，拿鶴，他拉，","notes":[]},{"n":27,"t":"亞伯蘭，亞伯蘭就是亞伯拉罕。","notes":[]},{"n":28,"t":"亞伯拉罕的兒子是以撒和以實瑪利。","notes":[],"heads":["以實瑪利的後裔"]},{"n":29,"t":"以實瑪利的後代如下：以實瑪利的長子是尼拜約，又有基達、亞德別、米比衫、","notes":[]},{"n":30,"t":"米施瑪、度瑪、瑪撒、哈大、提瑪、","notes":[]},{"n":31,"t":"伊突、拿非施和基底瑪。這些都是以實瑪利的兒子。","notes":[]},{"n":32,"t":"亞伯拉罕的妾基土拉所生的兒子，就是心蘭、約珊、米但、米甸、伊施巴和書亞。約珊的兒子是示巴和底但。","notes":[]},{"n":33,"t":"米甸的兒子是以法、以弗、哈諾、亞比大和以勒大。這些都是基土拉的子孫。","notes":[]},{"n":34,"t":"亞伯拉罕生以撒；以撒的兒子是以掃和以色列。","notes":[],"heads":["以掃的後裔"]},{"n":35,"t":"以掃的兒子是以利法、流珥、耶烏施、雅蘭和可拉。","notes":[]},{"n":36,"t":"以利法的兒子是提幔、阿抹、洗玻、迦坦、基納斯、亭納和亞瑪力。","notes":[]},{"n":37,"t":"流珥的兒子是拿哈、謝拉、沙瑪和米撒。","notes":[]},{"n":38,"t":"西珥的兒子是羅坍、朔巴、祭便、亞拿、底順、以察和底珊。","notes":[],"heads":["西珥的後裔"]},{"n":39,"t":"羅坍的兒子是何利和荷幔；羅坍的妹妹是亭納。","notes":["「荷幔」：創36．22稱「希幔」。"]},{"n":40,"t":"朔巴的兒子是亞勒文、瑪拿轄、以巴錄、示非和阿南。祭便的兒子是愛亞和亞拿。","notes":["「示非」：創36．23稱「示玻」。"]},{"n":41,"t":"亞拿的兒子是底順。底順的兒子是哈默蘭、伊是班、益蘭和基蘭。","notes":["「哈默蘭」：創36．26稱「欣但」。"]},{"n":42,"t":"以察的兒子是辟罕、撒番和亞干。底珊的兒子是烏斯和亞蘭。","notes":["「亞干」是根據一些古卷和七十士譯本；原文是「約亞干」；參創36．27。","「底珊」：原文是「底順」。"]},{"n":43,"t":"以色列人未有君王治理之前，這些是在以東地作王的。有比珥的兒子比拉，他的城名叫亭哈巴。","notes":[],"heads":["以東諸王"]},{"n":44,"t":"比拉死了，波斯拉人謝拉的兒子約巴接續他作王。","notes":[]},{"n":45,"t":"約巴死了，提幔人之地的戶珊接續他作王。","notes":[]},{"n":46,"t":"戶珊死了，比達的兒子哈達接續他作王，哈達曾在摩押地擊敗米甸人，他的城名叫亞未得。","notes":[]},{"n":47,"t":"哈達死了，瑪士利加人桑拉接續他作王。","notes":[]},{"n":48,"t":"桑拉死了，大河邊的利河伯人掃羅接續他作王。","notes":[]},{"n":49,"t":"掃羅死了，亞革波的兒子巴勒‧哈南接續他作王。","notes":[]},{"n":50,"t":"巴勒‧哈南死了，哈達接續他作王，他的城名叫巴伊。他的妻子名叫米希她別，是米‧薩合的孫女，瑪特列的女兒。","notes":["「巴伊」：創36．39稱「巴烏」。"]},{"n":51,"t":"哈達死了。以東的族長有：亭納族長、亞勒瓦族長、耶帖族長、","notes":[]},{"n":52,"t":"阿何利巴瑪族長、以拉族長、比嫩族長、","notes":[]},{"n":53,"t":"基納斯族長、提幔族長、米比薩族長、","notes":[]},{"n":54,"t":"瑪基疊族長、以蘭族長。這些都是以東的族長。","notes":[]}]},"2":{"heading":"猶大的後裔","verses":[{"n":1,"t":"以色列的兒子是呂便、西緬、利未、猶大、以薩迦、西布倫、","notes":[]},{"n":2,"t":"但、約瑟、便雅憫、拿弗他利、迦得和亞設。","notes":[]},{"n":3,"t":"猶大的兒子是珥、俄南和示拉，這三人是迦南女子拔‧書亞所生的。猶大的長子珥在耶和華眼中看為惡，耶和華就殺死了他。","notes":[]},{"n":4,"t":"猶大的媳婦她瑪為猶大生了法勒斯和謝拉。猶大共有五個兒子。","notes":[]},{"n":5,"t":"法勒斯的兒子是希斯崙和哈母勒。","notes":[]},{"n":6,"t":"謝拉的兒子是心利、以探、希幔、甲各和大拉，共五人。","notes":["「大拉」：七十士譯本的一些抄本和其他古譯本是「達大」；參王上4．31。"]},{"n":7,"t":"迦米的兒子是亞迦，他在當滅的物上犯了罪，連累了以色列人。","notes":["「亞迦」：有古卷是「亞干」；參書7．18。"]},{"n":8,"t":"以探的兒子是亞撒利雅。","notes":[]},{"n":9,"t":"希斯崙所生的兒子是耶拉篾、蘭和基路拜。","notes":[],"heads":["大衛王的家譜"]},{"n":10,"t":"蘭生亞米拿達；亞米拿達生拿順，拿順是猶大人的領袖。","notes":[]},{"n":11,"t":"拿順生撒門；撒門生波阿斯；","notes":[]},{"n":12,"t":"波阿斯生俄備得；俄備得生耶西；","notes":[]},{"n":13,"t":"耶西生長子以利押，次子亞比拿達，三子示米亞，","notes":["「示米亞」：撒上16．9稱「沙瑪」。"]},{"n":14,"t":"四子拿坦業，五子拉代，","notes":[]},{"n":15,"t":"六子阿鮮，七子大衛。","notes":[]},{"n":16,"t":"他們的姊妹是洗魯雅和亞比該。洗魯雅的兒子是亞比篩、約押和亞撒黑，共三人。","notes":[]},{"n":17,"t":"亞比該生亞瑪撒；亞瑪撒的父親是以實瑪利人益帖。","notes":[]},{"n":18,"t":"希斯崙的兒子迦勒娶阿蘇巴和耶略為妻，阿蘇巴的兒子是耶設、朔罷和押墩。","notes":[],"heads":["希斯崙的後裔"]},{"n":19,"t":"阿蘇巴死了，迦勒又娶以法她，生了戶珥。","notes":[]},{"n":20,"t":"戶珥生烏利；烏利生比撒列。","notes":[]},{"n":21,"t":"後來，希斯崙六十歲時娶了基列的父親瑪吉的女兒，與她同房；瑪吉的女兒為他生了西割；","notes":[]},{"n":22,"t":"西割生睚珥。睚珥在基列地有二十三座城。","notes":[]},{"n":23,"t":"後來基述和亞蘭奪了哈倭特‧睚珥，以及基納和所屬的鄉鎮，共六十個。這些城鎮的人全都是基列的父親瑪吉的子孫。","notes":["「鄉鎮」：原文直譯「女子們」；本卷書下同。"]},{"n":24,"t":"希斯崙在迦勒‧以法他死後，他的妻子亞比雅為他生了提哥亞的父親亞施戶。","notes":["本節七十士譯本是「希斯崙死後，迦勒到了以法他。希斯崙的妻子是亞比雅，為他生了提哥亞的父親亞施戶。」"]},{"n":25,"t":"希斯崙的長子耶拉篾的兒子有長子蘭、布拿、阿連、阿鮮和亞希雅。","notes":[],"heads":["耶拉篾的後裔"]},{"n":26,"t":"耶拉篾又娶一妻名叫亞她拉，是阿南的母親。","notes":[]},{"n":27,"t":"耶拉篾的長子蘭的兒子有瑪斯、雅憫和以結。","notes":[]},{"n":28,"t":"阿南的兒子是沙買和雅大。沙買的兒子是拿答和亞比述。","notes":[]},{"n":29,"t":"亞比述的妻子名叫亞比孩，為他生了亞辦和摩利。","notes":[]},{"n":30,"t":"拿答的兒子是西列和亞遍；西列死了，沒有兒子。","notes":[]},{"n":31,"t":"亞遍的兒子是以示；以示的兒子是示珊；示珊的兒子是亞來。","notes":[]},{"n":32,"t":"沙買的兄弟雅大的兒子是益帖和約拿單；益帖死了，沒有兒子。","notes":[]},{"n":33,"t":"約拿單的兒子是比勒和撒薩。這些都是耶拉篾的子孫。","notes":[]},{"n":34,"t":"示珊沒有兒子，只有女兒。示珊有一個僕人名叫耶哈，是埃及人。","notes":[]},{"n":35,"t":"示珊把女兒嫁給僕人耶哈，她為他生了亞太。","notes":[]},{"n":36,"t":"亞太生拿單；拿單生撒拔；","notes":[]},{"n":37,"t":"撒拔生以弗拉；以弗拉生俄備得；","notes":[]},{"n":38,"t":"俄備得生耶戶；耶戶生亞撒利雅；","notes":[]},{"n":39,"t":"亞撒利雅生希利斯；希利斯生以利亞薩；","notes":[]},{"n":40,"t":"以利亞薩生西斯買；西斯買生沙龍；","notes":[]},{"n":41,"t":"沙龍生耶加米雅；耶加米雅生以利沙瑪。","notes":[]},{"n":42,"t":"耶拉篾的兄弟迦勒的眾兒子：長子是米沙，米沙是西弗的父親，還有希伯倫的父親瑪利沙的眾兒子。","notes":[],"heads":["迦勒的其餘後裔"]},{"n":43,"t":"希伯倫的兒子是可拉、他普亞、利肯和示瑪。","notes":[]},{"n":44,"t":"示瑪生拉含，是約干之祖。利肯生沙買。","notes":["「約干」：原文另譯「約甸」；參書15．56。"]},{"n":45,"t":"沙買的兒子是瑪雲；瑪雲是伯‧夙的父親。","notes":[]},{"n":46,"t":"迦勒的妾以法生哈蘭、摩撒和迦謝；哈蘭生迦卸。","notes":[]},{"n":47,"t":"雅代的兒子是利健、約坦、基珊、毗力、以法和沙亞弗。","notes":[]},{"n":48,"t":"迦勒的妾瑪迦生示別和特哈拿，","notes":[]},{"n":49,"t":"又生麥瑪拿的父親沙亞弗，又生抹比拿和基比亞的父親示法。迦勒的女兒是押撒。","notes":[]},{"n":50,"t":"這些都是迦勒的子孫。以法她的長子戶珥的子孫：基列‧耶琳之祖朔巴，","notes":[]},{"n":51,"t":"伯利恆之祖薩瑪，伯‧迦得之祖哈勒。","notes":[]},{"n":52,"t":"基列‧耶琳之祖朔巴的子孫是哈羅以和一半的米努哈人。","notes":["「米努哈人」就是「瑪拿哈人」；參54節。"]},{"n":53,"t":"基列‧耶琳的宗族有以帖人、布特人、舒瑪人、密來人，又從這些宗族生出瑣拉人和以實陶人。","notes":[]},{"n":54,"t":"薩瑪的子孫有伯利恆人、尼陀法人、亞他綠‧伯‧約押人、一半的瑪拿哈人、瑣利人。","notes":[]},{"n":55,"t":"住雅比斯的文士的宗族有特拉人、示米押人和蘇甲人。這些都是利甲家之祖哈末所生的基尼人。","notes":[]}]},"3":{"heading":"大衛的兒女","verses":[{"n":1,"t":"大衛在希伯崙所生的兒子如下：長子暗嫩是耶斯列人亞希暖生的。次子但以利是迦密人亞比該生的。","notes":["「但以利」：撒下3‧3稱「基利押」。"]},{"n":2,"t":"三子押沙龍是基述王達買的女兒瑪迦生的。四子亞多尼雅是哈及生的。","notes":[]},{"n":3,"t":"五子示法提雅是亞比她生的。六子以特念是大衛的妻子以格拉生的。","notes":[]},{"n":4,"t":"這六人都是大衛在希伯崙生的。大衛在希伯崙作王七年六個月，在耶路撒冷作王三十三年。","notes":[]},{"n":5,"t":"大衛在耶路撒冷所生的兒子是示米亞、朔罷、拿單和所羅門。這四人是亞米利的女兒拔‧書亞生的。","notes":["「示米亞」：撒下5．14，代上14．4稱「沙母亞」。"]},{"n":6,"t":"還有益轄、以利沙瑪、以利法列、","notes":["「以利沙瑪」：撒下5．15，代上14．5稱「以利書亞」。","「以利法列」：代上14．5稱「以法列」。"]},{"n":7,"t":"挪迦、尼斐、雅非亞、","notes":[]},{"n":8,"t":"以利沙瑪、以利雅大、以利法列，共九人。","notes":["「以利雅大」：代上14．7稱「比利雅大」。"]},{"n":9,"t":"這些全都是大衛的兒子，妃嬪的兒子不在其內；她瑪是他們的妹妹。","notes":[]},{"n":10,"t":"所羅門的後裔如下：羅波安，他的兒子亞比雅，他的兒子亞撒，他的兒子約沙法，","notes":["「亞比雅」：王上14．31稱「亞比央」。"],"heads":["所羅門的後裔"]},{"n":11,"t":"他的兒子約蘭，他的兒子亞哈謝，他的兒子約阿施，","notes":[]},{"n":12,"t":"他的兒子亞瑪謝，他的兒子亞撒利雅，他的兒子約坦；","notes":[]},{"n":13,"t":"他的兒子亞哈斯，他的兒子希西家，他的兒子瑪拿西，","notes":[]},{"n":14,"t":"他的兒子亞們，他的兒子約西亞，","notes":[]},{"n":15,"t":"他的長子約哈難，次子約雅敬，三子西底家，四子沙龍。","notes":["「沙龍」：王下23．30稱「約哈斯」。"]},{"n":16,"t":"約雅敬的後裔：他的兒子耶哥尼雅，他的兒子西底家。","notes":["「耶哥尼雅」：王下24．6稱「約雅斤」。"]},{"n":17,"t":"被擄的耶哥尼雅的後裔如下：他的兒子撒拉鐵、","notes":[],"heads":["耶哥尼雅的後裔"]},{"n":18,"t":"瑪基蘭、毗大雅、示拿薩、耶加米、何沙瑪和尼大比雅。","notes":[]},{"n":19,"t":"毗大雅的兒子是所羅巴伯和示每。所羅巴伯的兒子是米書蘭和哈拿尼雅，示羅密是他們的妹妹；","notes":[]},{"n":20,"t":"還有哈舒巴、阿黑、比利家、哈撒底、于沙‧希悉，共五人。","notes":["「還有哈舒巴...于沙‧希悉」可能是所羅巴伯被擄歸回後所生，也可能是另一妻所生；原文另譯「米書蘭的兒子是哈舒巴、阿黑、比利家、哈撒底、于沙‧希悉」。"]},{"n":21,"t":"哈拿尼雅的兒子是毗拉提和耶篩亞。還有利法雅的眾兒子，亞珥難的眾兒子，俄巴底亞的眾兒子，示迦尼的眾兒子。","notes":["本節七十士譯本是「哈拿尼雅的後裔如下：毗拉提，他的兒子耶篩亞，他的兒子利法雅，他的兒子亞珥難，他的兒子俄巴底亞，他的兒子示迦尼。」"]},{"n":22,"t":"示迦尼的後裔：示瑪雅，示瑪雅的兒子哈突、以甲、巴利亞、尼利雅、沙法，共六人。","notes":["「示瑪雅的兒子哈突」：原文另譯「哈突」。"]},{"n":23,"t":"尼利雅的兒子是以利約乃、希西家、亞斯利干，共三人。","notes":[]},{"n":24,"t":"以利約乃的兒子是何大雅、以利亞實、毗萊雅、阿谷、約哈難、第萊雅、阿拿尼，共七人。","notes":[]}]},"4":{"heading":"復記猶大的後裔","verses":[{"n":1,"t":"猶大的兒子是法勒斯、希斯崙、迦米、戶珥和朔巴。","notes":[]},{"n":2,"t":"朔巴的兒子利亞雅生雅哈；雅哈生亞戶買和拉哈。這些是瑣拉人的宗族。","notes":[],"heads":["－朔巴"]},{"n":3,"t":"以坦之祖是耶斯列、伊施瑪和伊得巴；他們的妹妹名叫哈悉勒玻尼。","notes":["「以坦之祖」：七十士譯本是「以坦的兒子」。"],"heads":["－戶珥"]},{"n":4,"t":"基多之祖是毗努伊勒。戶沙之祖是以謝珥。這些都是伯利恆之祖，以法她的長子戶珥的後裔。","notes":[]},{"n":5,"t":"提哥亞的父親亞施戶有兩個妻子，希拉和拿拉。","notes":[],"heads":["－亞施戶"]},{"n":6,"t":"拿拉為亞施戶生亞戶撒、希弗、提米尼和哈轄斯他利。這些都是拿拉的兒子。","notes":[]},{"n":7,"t":"希拉生的是洗列、瑣轄和伊提南。","notes":[]},{"n":8,"t":"哥斯生亞諾、瑣比巴和哈崙的兒子亞哈黑的宗族。","notes":[]},{"n":9,"t":"雅比斯比他眾兄弟更尊貴，他母親給他起名叫雅比斯，意思說：「我生他甚是痛苦。」","notes":[]},{"n":10,"t":"雅比斯求告以色列的神說：「甚願你賜福與我，擴張我的疆界，你的手常與我同在，保佑我不遭患難，不受艱苦。」神就應允他所求的。","notes":[]},{"n":11,"t":"書哈的兄弟基綠生米黑，米黑是伊施屯的父親。","notes":[],"heads":["－迦勒"]},{"n":12,"t":"伊施屯生伯拉巴、巴西亞和珥‧拿轄之祖提欣拿。這些都是利迦人。","notes":[]},{"n":13,"t":"基納斯的兒子是俄陀聶和西萊雅。俄陀聶的兒子是哈塔。","notes":[]},{"n":14,"t":"憫挪太生俄弗拉；西萊雅生革‧夏納欣之祖約押。他們都是工匠。","notes":[]},{"n":15,"t":"耶孚尼的兒子迦勒的後裔：以路、以拉和拿安。以拉的兒子是基納斯。","notes":[]},{"n":16,"t":"耶哈利勒的兒子是西弗、西法、提利和亞撒列。","notes":[]},{"n":17,"t":"以斯拉的兒子是益帖、米列、以弗和雅倫。米列所娶法老的女兒比提雅的後裔如下：她懷了米利暗、沙買，和以實提摩之祖益巴。米列的猶大妻子生基多之祖雅列，梭哥之祖希伯，和撒挪亞之祖耶古鐵。","notes":[],"end":18},{"n":19,"t":"拿含的妹妹，荷第雅的妻子所生的是達利亞，迦米人基伊拉和瑪迦人以實提摩的祖先。","notes":["「達利亞」是根據七十士譯本的一些抄本；原文沒有。"]},{"n":20,"t":"示門的兒子是暗嫩、林拿、便‧哈南和提倫。以示的兒子是梭黑和便‧梭黑。","notes":[]},{"n":21,"t":"猶大的兒子示拉的後裔：利迦之祖珥，瑪利沙之祖拉大，和住在伯‧亞實比織細麻布的各宗族。","notes":[],"heads":["－示拉"]},{"n":22,"t":"還有約敬、哥西巴人、約阿施，和那在摩押娶妻，回到利恆的薩拉。這都是古時的記載。","notes":["「在摩押...薩拉」是根據一些古譯本；原文是「在摩押和雅叔比‧利恆掌權的薩拉」。"]},{"n":23,"t":"這些人都是陶匠，是尼他應和基底拉的居民。他們住在王那裏，為王做工。","notes":[]},{"n":24,"t":"西緬的後裔如下：尼母利、雅憫、雅立、謝拉和掃羅；","notes":[],"heads":["西緬的後裔"]},{"n":25,"t":"他的兒子沙龍，他的兒子米比衫，他的兒子米施瑪；","notes":[]},{"n":26,"t":"米施瑪的後裔：他的兒子哈母利，他的兒子撒刻，他的兒子示每。","notes":[]},{"n":27,"t":"示每有十六個兒子和六個女兒，但他兄弟的兒女不多，他們各家族也不如猶大族那樣人丁興旺。","notes":[]},{"n":28,"t":"西緬人住在別是巴、摩拉大、哈薩‧書亞、","notes":[]},{"n":29,"t":"辟拉、以森、陀臘、","notes":[]},{"n":30,"t":"彼土利、何珥瑪、洗革拉、","notes":[]},{"n":31,"t":"伯‧瑪加博、哈薩‧蘇撒、伯‧比利和沙拉音，這些城鎮直到大衛作王的時候都是屬西緬人的；","notes":[]},{"n":32,"t":"還有所屬的村莊以坦、亞因、臨門、陀健、亞珊，共五個城鎮；","notes":[]},{"n":33,"t":"連同環繞這些城鎮的一切鄉村，直到巴力。這是他們的住處，他們都有家譜。","notes":[]},{"n":34,"t":"還有米所巴、雅米勒、亞瑪謝的兒子約沙、","notes":[]},{"n":35,"t":"約珥，和亞薛的曾孫，西萊雅的孫子，約示比的兒子耶戶。","notes":[]},{"n":36,"t":"還有以利約乃、雅哥巴、約朔海、亞帥雅、亞底業、耶西篾、比拿雅、","notes":[]},{"n":37,"t":"細撒；細撒是示非的兒子，示非是亞龍的兒子，亞龍是耶大雅的兒子，耶大雅是申利的兒子，申利是示瑪雅的兒子。","notes":[]},{"n":38,"t":"以上所記的人名都是作族長的，他們父系的家屬大量增加。","notes":[]},{"n":39,"t":"他們往平原東邊基多口去，尋找牧放羊群的草場，","notes":["「基多口」：七十士譯本是「基拉耳口」。"]},{"n":40,"t":"找到了肥沃優美的草場，又寬闊又平靜安寧之地；從前住那裏的是含族的人。","notes":[]},{"n":41,"t":"以上紀錄上有名的人，在猶大王希西家的日子，來攻擊含族人的帳棚和那裏所有的米烏尼人，把他們滅盡，就住在他們的地方，直到今日，因為那裏有草場可以牧放羊群。","notes":[]},{"n":42,"t":"這些西緬人中有五百人上西珥山，率領他們的是以示的兒子毗拉提、尼利雅、利法雅和烏薛。","notes":[]},{"n":43,"t":"他們殺了亞瑪力剩下的殘存之民，就住在那裏，直到今日。","notes":[]}]},"5":{"heading":"呂便的後裔","verses":[{"n":1,"t":"以色列的長子呂便的後裔。呂便玷污了父親的床，他長子的名分就歸了以色列的兒子約瑟的後裔；因此，家譜就不按出生順序登錄。","notes":[]},{"n":2,"t":"雖然猶大比他兄弟強盛，君王也從他而出，然而長子的名分卻歸約瑟。","notes":[]},{"n":3,"t":"以色列長子呂便的後裔如下：哈諾、法路、希斯倫和迦米。","notes":[]},{"n":4,"t":"約珥的後裔：他的兒子示瑪雅，他的兒子歌革，他的兒子示每，","notes":[]},{"n":5,"t":"他的兒子米迦，他的兒子利亞雅，他的兒子巴力，","notes":[]},{"n":6,"t":"他的兒子備拉；這備拉作呂便支派的領袖，被亞述王提革拉‧毗列色擄去。","notes":[]},{"n":7,"t":"他的弟兄照著宗族，按著家譜作族長的是耶利、撒迦利雅、","notes":[]},{"n":8,"t":"比拉；比拉是亞撒的兒子，亞撒是示瑪的兒子，示瑪是約珥的兒子；約珥住在亞羅珥，直到尼波和巴力‧免。","notes":[]},{"n":9,"t":"他也住在東邊，直到幼發拉底河這邊的曠野邊界，因為他們在基列地牲畜增多。","notes":[]},{"n":10,"t":"掃羅年間，他們與夏甲人爭戰，夏甲人倒在他們手下，他們就在基列東邊的全地，住在夏甲人的帳棚裏。","notes":[]},{"n":11,"t":"迦得的後裔在呂便對面，住在巴珊地，延伸到撒迦：","notes":[],"heads":["迦得的後裔"]},{"n":12,"t":"有作族長的約珥，有作副族長的沙番，還有雅乃和住在巴珊的沙法。","notes":[]},{"n":13,"t":"按著家族，他們的弟兄是米迦勒、米書蘭、示巴、約賴、雅干、細亞和希伯，共七人。","notes":[]},{"n":14,"t":"這些都是亞比孩的兒子；亞比孩是戶利的兒子，戶利是耶羅亞的兒子，耶羅亞是基列的兒子，基列是米迦勒的兒子，米迦勒是耶示篩的兒子，耶示篩是耶哈多的兒子，耶哈多是布斯的兒子；","notes":[]},{"n":15,"t":"古尼的孫子，押比疊的兒子亞希是他們的族長。","notes":[]},{"n":16,"t":"他們住在基列、巴珊和所屬的鄉鎮，以及沙崙一切的郊野，直到四圍的交界。","notes":[]},{"n":17,"t":"這些人在猶大王約坦和以色列王耶羅波安年間，都載入家譜。","notes":[]},{"n":18,"t":"呂便人、迦得人和瑪拿西半支派的人，能拿盾牌和刀劍、拉弓、出征善戰的勇士共有四萬四千七百六十名。","notes":[],"heads":["呂便迦得瑪拿西族的軍隊"]},{"n":19,"t":"他們與夏甲人、伊突人、拿非施人、挪答人打仗。","notes":[]},{"n":20,"t":"他們在打仗的時候得了神的幫助，夏甲人和所有跟隨夏甲人的人都交在他們手中；因為他們在陣上呼求神，倚賴他，他就應允他們。","notes":[]},{"n":21,"t":"他們擄掠了夏甲人的牲畜，有五萬匹駱駝，二十五萬隻羊，二千匹驢，又有十萬人；","notes":[]},{"n":22,"t":"被殺仆倒的很多，因為這戰爭是出乎神。他們就住在夏甲人的地上，直到被擄的時候。","notes":[]},{"n":23,"t":"瑪拿西半支派的人住在那地，從巴珊延到巴力‧黑門、示尼珥和黑門山，他們人數增多。","notes":["「人數增多」：七十士譯本是「他們在黎巴嫩人數增多」。"],"heads":["瑪拿西半支派"]},{"n":24,"t":"他們的族長如下：以弗、以示、以利業、亞斯列、耶利米、何達威雅和雅疊；他們都是大能的勇士，有名的人，是作族長的。","notes":[]},{"n":25,"t":"但他們得罪了他們列祖的神，隨從當地百姓的神明而行淫，這百姓就是神在他們面前所除滅的。","notes":[]},{"n":26,"t":"因此，以色列的神激發亞述王普勒，就是亞述王提革拉‧毗列色的心，他擄掠了呂便人、迦得人、瑪拿西半支派的人，把他們帶到哈臘、哈博、哈拉與歌散河邊，直到今日。","notes":["七十士譯本沒有「哈拉」。"]}]},"6":{"heading":"利未的後裔","verses":[{"n":1,"t":"利未的後裔：革順、哥轄和米拉利。","notes":[]},{"n":2,"t":"哥轄的兒子是暗蘭、以斯哈、希伯倫和烏薛。","notes":[]},{"n":3,"t":"暗蘭的兒女是亞倫、摩西和米利暗。亞倫的兒子是拿答、亞比戶、以利亞撒和以他瑪。","notes":[]},{"n":4,"t":"以利亞撒生非尼哈；非尼哈生亞比書；","notes":[]},{"n":5,"t":"亞比書生布基；布基生烏西；","notes":[]},{"n":6,"t":"烏西生西拉希雅；西拉希雅生米拉約；","notes":[]},{"n":7,"t":"米拉約生亞瑪利雅；亞瑪利雅生亞希突；","notes":[]},{"n":8,"t":"亞希突生撒督；撒督生亞希瑪斯；","notes":[]},{"n":9,"t":"亞希瑪斯生亞撒利雅；亞撒利雅生約哈難；","notes":[]},{"n":10,"t":"約哈難生亞撒利雅，亞撒利雅在所羅門建造的耶路撒冷殿中擔任祭司的職分；","notes":[]},{"n":11,"t":"亞撒利雅生亞瑪利雅；亞瑪利雅生亞希突；","notes":[]},{"n":12,"t":"亞希突生撒督；撒督生沙龍；","notes":[]},{"n":13,"t":"沙龍生希勒家；希勒家生亞撒利雅；","notes":[]},{"n":14,"t":"亞撒利雅生西萊雅；西萊雅生約薩答。","notes":[]},{"n":15,"t":"當耶和華藉尼布甲尼撒的手擄掠猶大和耶路撒冷的時候，約薩答也被擄去。","notes":[]},{"n":16,"t":"利未的後裔：革順、哥轄和米拉利。","notes":[],"heads":["利未其餘的後裔"]},{"n":17,"t":"革順的兒子名叫立尼和示每。","notes":[]},{"n":18,"t":"哥轄的兒子是暗蘭、以斯哈、希伯倫和烏薛。","notes":[]},{"n":19,"t":"米拉利的兒子是抹利和母示。這是按著父系所分利未人的宗族。","notes":[]},{"n":20,"t":"屬革順的：他的兒子立尼，他的兒子雅哈，他的兒子薪瑪，","notes":[]},{"n":21,"t":"他的兒子約亞，他的兒子易多，他的兒子謝拉，他的兒子耶特賴。","notes":[]},{"n":22,"t":"哥轄的後裔：他的兒子亞米拿達，他的兒子可拉，他的兒子亞惜，","notes":[]},{"n":23,"t":"他的兒子以利加拿，他的兒子以比雅撒，他的兒子亞惜，","notes":[]},{"n":24,"t":"他的兒子他哈，他的兒子烏列，他的兒子烏西雅，他的兒子少羅。","notes":[]},{"n":25,"t":"以利加拿的兒子是亞瑪賽、亞希摩、","notes":[]},{"n":26,"t":"以利加拿。以利加拿的後裔：他的兒子瑣菲，他的兒子拿哈，","notes":["「以利加拿。以利加拿的後裔：他的兒子瑣菲」：七十士譯本是「他的兒子以利加拿，他的兒子瑣菲」。"]},{"n":27,"t":"他的兒子以利押，他的兒子耶羅罕，他的兒子以利加拿，他的兒子撒母耳。","notes":[]},{"n":28,"t":"撒母耳的兒子是長子約珥和次子亞比亞。","notes":["「長子約珥和次子亞比亞」是根據七十士譯本和其他古譯本，原文是「長子瓦希尼和亞比亞」；參本章33節，撒上8．2。"]},{"n":29,"t":"米拉利的後裔：抹利，他的兒子立尼，他的兒子示每，他的兒子烏撒，","notes":[]},{"n":30,"t":"他的兒子示米亞，他的兒子哈基雅，他的兒子亞帥雅。","notes":[]},{"n":31,"t":"這些是約櫃安設之後，大衛派在耶和華殿中管理歌唱事奉的人。","notes":[],"heads":["聖殿中的歌唱者"]},{"n":32,"t":"他們在會幕前負責歌唱的事奉，及至所羅門在耶路撒冷建造了耶和華的殿，他們就按著班次供職。","notes":[]},{"n":33,"t":"供職的人和他們的子孫如下：哥轄的子孫中有歌唱的希幔；希幔是約珥的兒子，約珥是撒母耳的兒子，","notes":[]},{"n":34,"t":"撒母耳是以利加拿的兒子，以利加拿是耶羅罕的兒子，耶羅罕是以利業的兒子，以利業是陀亞的兒子，","notes":[]},{"n":35,"t":"陀亞是蘇弗的兒子，蘇弗是以利加拿的兒子，以利加拿是瑪哈的兒子，瑪哈是亞瑪賽的兒子，","notes":[]},{"n":36,"t":"亞瑪賽是以利加拿的兒子，以利加拿是約珥的兒子，約珥是亞撒利雅的兒子，亞撒利雅是西番雅的兒子，","notes":[]},{"n":37,"t":"西番雅是他哈的兒子，他哈是亞惜的兒子，亞惜是以比雅撒的兒子，以比雅撒是可拉的兒子，","notes":[]},{"n":38,"t":"可拉是以斯哈的兒子，以斯哈是哥轄的兒子，哥轄是利未的兒子，利未是以色列的兒子。","notes":[]},{"n":39,"t":"希幔的弟兄亞薩在希幔的右邊供職；亞薩是比利家的兒子，比利家是示米亞的兒子，","notes":[]},{"n":40,"t":"示米亞是米迦勒的兒子，米迦勒是巴西雅的兒子，巴西雅是瑪基雅的兒子，","notes":[]},{"n":41,"t":"瑪基雅是伊特尼的兒子，伊特尼是謝拉的兒子，謝拉是亞大雅的兒子，","notes":[]},{"n":42,"t":"亞大雅是以探的兒子，以探是薪瑪的兒子，薪瑪是示每的兒子，","notes":[]},{"n":43,"t":"示每是雅哈的兒子，雅哈是革順的兒子，革順是利未的兒子。","notes":[]},{"n":44,"t":"他們的弟兄米拉利的子孫，在他們左邊供職的有以探；以探是基示的兒子，基示是亞伯底的兒子，亞伯底是瑪鹿的兒子，","notes":[]},{"n":45,"t":"瑪鹿是哈沙比雅的兒子，哈沙比雅是亞瑪謝的兒子，亞瑪謝是希勒家的兒子，","notes":[]},{"n":46,"t":"希勒家是暗西的兒子，暗西是巴尼的兒子，巴尼是沙麥的兒子，","notes":[]},{"n":47,"t":"沙麥是末力的兒子，末力是母示的兒子，母示是米拉利的兒子，米拉利是利未的兒子。","notes":[]},{"n":48,"t":"他們的弟兄利未人也被派辦理神殿中帳幕的一切事務。","notes":[]},{"n":49,"t":"亞倫和他的子孫在燔祭壇和香壇上獻祭燒香，辦理至聖所一切的事，為以色列贖罪，正如神僕人摩西所吩咐的一切。","notes":[],"heads":["亞倫的後裔"]},{"n":50,"t":"亞倫的後裔如下：他的兒子以利亞撒，他的兒子非尼哈，他的兒子亞比書，","notes":[]},{"n":51,"t":"他的兒子布基，他的兒子烏西，他的兒子西拉希雅，","notes":[]},{"n":52,"t":"他的兒子米拉約，他的兒子亞瑪利雅，他的兒子亞希突，","notes":[]},{"n":53,"t":"他的兒子撒督，他的兒子亞希瑪斯。","notes":[]},{"n":54,"t":"他們的住處按著境內的營寨如下：亞倫的子孫哥轄族先抽籤得地，","notes":[],"heads":["利未支派居住地"]},{"n":55,"t":"得了猶大地的希伯崙和四圍的郊野；","notes":[]},{"n":56,"t":"只是這城的田地和所屬的村莊都為耶孚尼的兒子迦勒所得。","notes":[]},{"n":57,"t":"亞倫的子孫所得逃城如下：希伯崙、立拿與其郊野、雅提珥、以實提莫與其郊野、","notes":[]},{"n":58,"t":"希崙與其郊野、底璧與其郊野、","notes":["「希崙」是根據七十士譯本，原文是「希列茲」，原文另譯「何崙」；參書21．15。"]},{"n":59,"t":"亞珊與其郊野、伯‧示麥與其郊野。","notes":[]},{"n":60,"t":"他們也從便雅憫支派中得了迦巴與其郊野、阿勒篾與其郊野、亞拿突與其郊野。他們宗族所得的城共十三座。","notes":[]},{"n":61,"t":"哥轄族其餘的人抽籤，按支派的宗族，從半個支派，就是瑪拿西半支派中得了十座城。","notes":[]},{"n":62,"t":"革順族按著宗族，從以薩迦支派、亞設支派、拿弗他利支派、巴珊內的瑪拿西支派中，得了十三座城。","notes":[]},{"n":63,"t":"米拉利族按著宗族抽籤，從呂便支派、迦得支派、西布倫支派中，得了十二座城。","notes":[]},{"n":64,"t":"以色列人把這些城與其郊野給了利未人。","notes":[]},{"n":65,"t":"以色列人用抽籤的方式，從猶大人、西緬人、便雅憫人三支派中，把以上提到名字的城給了他們。","notes":[]},{"n":66,"t":"哥轄子孫中有幾個宗族從以法蓮支派中也得了城鎮作為他們的區域。","notes":[]},{"n":67,"t":"他們在以法蓮山區所得的逃城：示劍與其郊野、基色與其郊野、","notes":[]},{"n":68,"t":"約緬與其郊野、伯‧和崙與其郊野、","notes":[]},{"n":69,"t":"亞雅崙與其郊野、迦特‧臨門與其郊野。","notes":[]},{"n":70,"t":"哥轄其餘的子孫從瑪拿西半支派中得了亞乃與其郊野、比連與其郊野。","notes":[]},{"n":71,"t":"革順子孫從瑪拿西半支派中得了巴珊的哥蘭與其郊野、亞斯她錄與其郊野；","notes":[]},{"n":72,"t":"從以薩迦支派中得了基低斯與其郊野、大比拉與其郊野、","notes":[]},{"n":73,"t":"拉末與其郊野、亞年與其郊野；","notes":[]},{"n":74,"t":"從亞設支派中得了瑪沙與其郊野、押頓與其郊野、","notes":[]},{"n":75,"t":"戶割與其郊野、利合與其郊野；","notes":[]},{"n":76,"t":"從拿弗他利支派中得了加利利的基低斯與其郊野、哈們與其郊野、基列亭與其郊野。","notes":[]},{"n":77,"t":"米拉利其餘的子孫從西布倫支派中得了臨摩挪與其郊野、他泊與其郊野；","notes":["「臨摩挪」：書19．13稱「臨門」。"]},{"n":78,"t":"又在耶利哥的約旦河東，從呂便支派中得了曠野的比悉與其郊野、雅雜與其郊野，","notes":[]},{"n":79,"t":"基底莫與其郊野、米法押與其郊野；","notes":[]},{"n":80,"t":"又從迦得支派中得了基列的拉末與其郊野、瑪哈念與其郊野、","notes":[]},{"n":81,"t":"希實本與其郊野、雅謝與其郊野。","notes":[]}]},"7":{"heading":"以薩迦的後裔","verses":[{"n":1,"t":"以薩迦的後裔：陀拉、普瓦、雅述和伸崙，共四人。","notes":["「雅述」：創46．13稱「約伯」。"]},{"n":2,"t":"陀拉的後裔：烏西、利法雅、耶勒、雅買、易伯散和示母利，都是陀拉的族長，在他們世代中是大能的勇士。到大衛年間，他們的人數共有二萬二千六百名。","notes":[]},{"n":3,"t":"烏西的後裔：伊斯拉希，伊斯拉希的兒子米迦勒、俄巴底亞、約珥和伊示雅，共五人，全都是族長。","notes":[]},{"n":4,"t":"他們所率領的，按著家譜，照著父家，可作戰的軍隊共有三萬六千人，因為他們的妻子和兒子眾多。","notes":[]},{"n":5,"t":"他們的弟兄在以薩迦各族中的大能勇士，登記在家譜中的全部共有八萬七千人。","notes":[]},{"n":6,"t":"便雅憫：比拉、比結和耶疊，共三人。","notes":["「便雅憫」：七十士譯本的一些抄本是「便雅憫的兒子」。"],"heads":["便雅憫的後裔"]},{"n":7,"t":"比拉的兒子：以斯本、烏西、烏薛、耶利末和以利，共五人，都是族長，是大能的勇士。登記在家譜中的人共有二萬二千零三十四人。","notes":[]},{"n":8,"t":"比結的兒子：細米拉、約阿施、以利以謝、以利約乃、暗利、耶利末、亞比雅、亞拿突和亞拉篾；這些全都是比結的兒子。","notes":[]},{"n":9,"t":"登記在家譜中，按家譜的族長，大能的勇士，共有二萬零二百人。","notes":[]},{"n":10,"t":"耶疊的後裔：比勒罕，比勒罕的兒子耶烏施、便雅憫、以笏、基拿拿、細坦、他施和亞希沙哈。","notes":[]},{"n":11,"t":"這些全都是耶疊的後裔，都是族長，是大能的勇士，能上陣打仗的共有一萬七千二百人。","notes":[]},{"n":12,"t":"還有以珥的兒子書品和戶品，以及亞黑的兒子戶伸。","notes":[]},{"n":13,"t":"拿弗他利的後裔：雅薛、沽尼、耶色和沙龍，都是辟拉的子孫。","notes":[],"heads":["拿弗他利的後裔"]},{"n":14,"t":"瑪拿西的兒子亞斯烈是他的妾亞蘭女子所生的；她又生了瑪吉，是基列的父親。","notes":[],"heads":["瑪拿西的後裔"]},{"n":15,"t":"瑪吉為戶品和書品各娶了一妻，他的姊妹名叫瑪迦。第二個名叫西羅非哈；西羅非哈只有女兒。","notes":[]},{"n":16,"t":"瑪吉的妻子瑪迦生了一個兒子，瑪迦給他起名叫毗利施。毗利施的弟弟名叫示利施；示利施的兒子是烏蘭和利金。","notes":[]},{"n":17,"t":"烏蘭的兒子是比但。這些都是基列的子孫；基列是瑪吉的兒子，瑪吉是瑪拿西的兒子。","notes":[]},{"n":18,"t":"基列的妹妹哈摩利吉生了伊施荷、亞比以謝和瑪拉。","notes":[]},{"n":19,"t":"示米大的兒子是亞現、示劍、利克希和阿尼安。","notes":[]},{"n":20,"t":"以法蓮的後裔：書提拉，他的兒子比列，他的兒子他哈，他的兒子以拉大，他的兒子他哈，","notes":[],"heads":["以法蓮的後裔"]},{"n":21,"t":"他的兒子撒拔，他的兒子書提拉。以法蓮又生以謝和以列；這二人因為下去奪取迦特人的牲畜，被本地的迦特人殺了。","notes":[]},{"n":22,"t":"他們的父親以法蓮為他們悲哀了多日，他的兄弟都來安慰他。","notes":[]},{"n":23,"t":"以法蓮與妻子同房，妻子懷孕生了一子，以法蓮因為家裏遭禍，就給這兒子起名叫比利亞。","notes":[]},{"n":24,"t":"他的女兒名叫舍伊拉，舍伊拉建築了上伯‧和崙、下伯‧和崙和烏羨‧舍伊拉。","notes":[]},{"n":25,"t":"他的兒子利法和利悉，他的兒子他拉，他的兒子他罕，","notes":[]},{"n":26,"t":"他的兒子拉但，他的兒子亞米忽，他的兒子以利沙瑪，","notes":[]},{"n":27,"t":"他的兒子嫩，他的兒子約書亞。","notes":[]},{"n":28,"t":"以法蓮人的地業和住處是伯特利和所屬的鄉鎮，東邊拿蘭，西邊基色和所屬的鄉鎮，示劍和所屬的鄉鎮，直到艾雅和所屬的鄉鎮；","notes":[]},{"n":29,"t":"還有靠近瑪拿西人的邊界，伯‧善和所屬的鄉鎮，他納和所屬的鄉鎮，米吉多和所屬的鄉鎮，多珥和所屬的鄉鎮。以色列兒子約瑟的子孫住在這些地方。","notes":[]},{"n":30,"t":"亞設的後裔：音拿、亦施瓦、亦施韋和比利亞，還有他們的妹妹西拉。","notes":[],"heads":["亞設的後裔"]},{"n":31,"t":"比利亞的兒子是希別和瑪結；瑪結是比撒威的父親。","notes":[]},{"n":32,"t":"希別生雅弗勒、朔默、何坦和他們的妹妹書雅。","notes":[]},{"n":33,"t":"雅弗勒的兒子是巴薩、賓哈和亞施法；這些都是雅弗勒的兒子。","notes":[]},{"n":34,"t":"朔默的兒子是亞希、羅迦、耶戶巴和亞蘭。","notes":[]},{"n":35,"t":"朔默的兄弟希連的兒子是瑣法、音那、示利斯和亞抹。","notes":[]},{"n":36,"t":"瑣法的兒子是書亞、哈尼弗、書阿勒、比利、音拉、","notes":[]},{"n":37,"t":"比悉、河得、珊瑪、施沙、益蘭和比拉。","notes":[]},{"n":38,"t":"益帖的兒子是耶孚尼、毗斯巴和亞拉。","notes":[]},{"n":39,"t":"烏拉的兒子是亞拉、漢尼業和利寫。","notes":[]},{"n":40,"t":"這些全都是亞設的子孫，都是族長，是精壯大能的勇士，也是領袖中的領袖。登記在家譜中，能上陣打仗的共有二萬六千人。","notes":[]}]},"8":{"heading":"便雅憫的後裔","verses":[{"n":1,"t":"便雅憫生長子比拉，次子亞實別，三子亞哈拉，","notes":[]},{"n":2,"t":"四子挪哈，五子拉法。","notes":[]},{"n":3,"t":"比拉的兒子是亞大、基拉、亞比忽、","notes":[]},{"n":4,"t":"亞比書、乃幔、亞何亞、","notes":[]},{"n":5,"t":"基拉、示孚汛和戶蘭。","notes":[]},{"n":6,"t":"以忽的後裔如下，他們是迦巴居民的族長，曾被擄到瑪拿轄：","notes":[]},{"n":7,"t":"乃幔、亞希亞、基拉；他擄了他們，又生了烏撒和亞希忽。","notes":[]},{"n":8,"t":"沙哈連休了兩個妻子戶伸和巴拉之後，在摩押地生了兒子。","notes":[]},{"n":9,"t":"他與妻子賀得生了約巴、洗比雅、米沙、瑪拉干、","notes":[]},{"n":10,"t":"耶烏斯、沙迦和米瑪；這些是他的兒子，都是族長。","notes":[]},{"n":11,"t":"戶伸為他生了亞比突和以利巴力。","notes":[]},{"n":12,"t":"以利巴力的兒子是希伯、米珊和沙麥；沙麥建立阿挪、羅德和所屬的鄉鎮。","notes":[]},{"n":13,"t":"比利亞和示瑪是亞雅崙居民的族長，他們驅逐了迦特的居民。","notes":[]},{"n":14,"t":"亞希約、沙煞、耶利末、","notes":["「亞希約、沙煞」：七十士譯本是「他們的弟兄是沙煞」。"]},{"n":15,"t":"西巴第雅、亞拉得、亞得、","notes":[]},{"n":16,"t":"米迦勒、伊施巴和約哈都是比利亞的兒子。","notes":[]},{"n":17,"t":"西巴第雅、米書蘭、希西基、希伯、","notes":[]},{"n":18,"t":"伊施米萊、伊斯利亞和約巴都是以利巴力的兒子。","notes":[]},{"n":19,"t":"雅金、細基利、撒底、","notes":[]},{"n":20,"t":"以利乃、洗勒太、以利業、","notes":[]},{"n":21,"t":"亞大雅、比拉雅和申拉都是示每的兒子。","notes":[]},{"n":22,"t":"伊施班、希伯、以利業、","notes":[]},{"n":23,"t":"亞伯頓、細基利、哈難、","notes":[]},{"n":24,"t":"哈拿尼雅、以攔、安陀提雅、","notes":[]},{"n":25,"t":"伊弗底雅、毗努伊勒都是沙煞的兒子。","notes":[]},{"n":26,"t":"珊示萊、示哈利、亞他利雅、","notes":[]},{"n":27,"t":"雅利西、以利亞和細基利都是耶羅罕的兒子。","notes":[]},{"n":28,"t":"這些人按照他們的家譜都是族長，是領袖，都住在耶路撒冷。","notes":[]},{"n":29,"t":"在基遍住的有基遍的父親耶利，他的妻子名叫瑪迦；","notes":[],"heads":["掃羅王的家族"]},{"n":30,"t":"他的長子是亞伯頓，還有蘇珥、基士、巴力、拿答、","notes":["「巴力」：七十士譯本的一些抄本是「巴力、尼珥」；參代上9．36。"]},{"n":31,"t":"基多、亞希約和撒迦。","notes":["七十士譯本在此加「米基羅」；參代上9．37。"]},{"n":32,"t":"米基羅生示米暗。這些人在他們弟兄的對面，和他們的弟兄同住在耶路撒冷。","notes":[]},{"n":33,"t":"尼珥生基士；基士生掃羅；掃羅生約拿單、麥基‧舒亞、亞比拿達和伊施巴力。","notes":["「伊施巴力」又名「伊施‧波設」，見撒下2．8；又名「亦施韋」，見撒上14．49；代上9．39同。"]},{"n":34,"t":"約拿單的兒子是米力‧巴力；米力‧巴力生米迦。","notes":["「米力‧巴力」：撒下4．4稱「米非波設」；代上9．40同。"]},{"n":35,"t":"米迦的兒子是毗敦、米勒、他利亞和亞哈斯；","notes":[]},{"n":36,"t":"亞哈斯生耶何阿達；耶何阿達生亞拉篾、亞斯瑪威和心利；心利生摩撒；","notes":[]},{"n":37,"t":"摩撒生比尼亞；比尼亞的兒子是拉法，拉法的兒子是以利亞薩，以利亞薩的兒子是亞悉。","notes":[]},{"n":38,"t":"亞悉有六個兒子，他們的名字是亞斯利干、波基路、以實瑪利、示亞利雅、俄巴底雅和哈難；這些全都是亞悉的兒子。","notes":["「亞斯利干、波基路」：七十士譯本是「他的長子亞斯利干」。"]},{"n":39,"t":"亞悉兄弟以設的兒子：長子是烏蘭，次子是耶烏施，三子是以利法列。","notes":[]},{"n":40,"t":"烏蘭的兒子都是大能的勇士，是弓箭手，他們有許多的子孫，共一百五十名，都是便雅憫人。","notes":[]}]},"9":{"heading":"被擄歸回的人","verses":[{"n":1,"t":"以色列眾人按家譜登記，看哪，都寫在《以色列諸王記》上。猶大人因背叛被擄到巴比倫。","notes":[]},{"n":2,"t":"從巴比倫先回來，住在自己地業城鎮中的有以色列人、祭司、利未人和殿役。","notes":[]},{"n":3,"t":"住在耶路撒冷的有猶大人、便雅憫人、以法蓮人和瑪拿西人：","notes":[]},{"n":4,"t":"猶大兒子法勒斯的子孫中有烏太，烏太是亞米忽的兒子，亞米忽是暗利的兒子，暗利是音利的兒子，音利是巴尼的兒子；","notes":[]},{"n":5,"t":"示羅人中有長子亞帥雅和他的眾兒子；","notes":[]},{"n":6,"t":"謝拉的子孫中有耶烏利和他的弟兄，共六百九十人；","notes":[]},{"n":7,"t":"便雅憫人中有哈西努亞的曾孫，何達威雅的孫子，米書蘭的兒子撒路；","notes":[]},{"n":8,"t":"又有耶羅罕的兒子伊比內雅；米基立的孫子，烏西的兒子以拉；伊比尼雅的曾孫，流珥的孫子，示法提雅的兒子米書蘭；","notes":[]},{"n":9,"t":"和他們的弟兄，按著家譜登記，共有九百五十六名；這些人都是族長。","notes":[]},{"n":10,"t":"祭司中有耶大雅、耶何雅立、雅斤，","notes":[],"heads":["住耶路撒冷的祭司"]},{"n":11,"t":"還有管理神殿的亞撒利雅，亞撒利雅是希勒家的兒子，希勒家是米書蘭的兒子，米書蘭是撒督的兒子，撒督是米拉約的兒子，米拉約是亞希突的兒子。","notes":[]},{"n":12,"t":"還有瑪基雅的曾孫，巴施戶珥的孫子，耶羅罕的兒子亞大雅；又有瑪賽，瑪賽是亞第業的兒子，亞第業是雅希細拉的兒子，雅希細拉是米書蘭的兒子，米書蘭是米實利密的兒子，米實利密是音麥的兒子。","notes":[]},{"n":13,"t":"他們和他們的弟兄都是族長，共有一千七百六十人，都善於做神殿的事工。","notes":[]},{"n":14,"t":"利未人米拉利的子孫中有哈沙比雅的曾孫，押利甘的孫子，哈述的兒子示瑪雅；","notes":[],"heads":["住耶路撒冷的利未人"]},{"n":15,"t":"有拔巴甲、黑勒施、加拉和亞薩的曾孫，細基利的孫子，米迦的兒子瑪探雅；","notes":[]},{"n":16,"t":"又有耶杜頓的曾孫，加拉的孫子，示瑪雅的兒子俄巴底，還有以利加拿的孫子，亞撒的兒子比利家。他們都住在尼陀法人的村莊。","notes":[]},{"n":17,"t":"守衛是沙龍、亞谷、達們、亞希幔和他們的弟兄；沙龍是領袖。","notes":[],"heads":["住耶路撒冷的聖殿守衛"]},{"n":18,"t":"從前這些人看守朝東的王門，如今是利未人營中的守衛。","notes":[]},{"n":19,"t":"可拉的曾孫，以比雅撒的孫子，可利的兒子沙龍，和他父家的弟兄可拉人管理事務，看守會幕的門。他們的祖宗曾管理耶和華的軍營，把守營的入口。","notes":[]},{"n":20,"t":"從前以利亞撒的兒子非尼哈管理他們，耶和華也與他同在。","notes":[]},{"n":21,"t":"米施利米雅的兒子撒迦利雅是看守會幕門口的。","notes":[]},{"n":22,"t":"被選作門口守衛的總共有二百一十二名。他們在自己的村莊，按著家譜登記，是大衛和撒母耳先見所派擔當這受託之職任的。","notes":[]},{"n":23,"t":"他們和他們的子孫看守耶和華殿的門，就是會幕的門口。","notes":[]},{"n":24,"t":"在東西南北，四方都有守衛。","notes":["「四方」：原文是「四風」。"]},{"n":25,"t":"他們的弟兄住在村莊，每七日來與他們換班。","notes":[]},{"n":26,"t":"這些守衛的四個領袖都是利未人，各有受託的職任，看守神殿的房間和寶庫。","notes":[]},{"n":27,"t":"他們住在神殿的四圍，受託看守聖殿，負責每日早晨開門。","notes":[]},{"n":28,"t":"利未人中有人管理所使用的器皿，拿出拿入都按數目點算。","notes":[],"heads":["其餘的利未人"]},{"n":29,"t":"又有人管理器具和聖所一切的器皿，以及細麵、酒、油、乳香和香料。","notes":[]},{"n":30,"t":"祭司的子孫中有人用香料做膏油。","notes":[]},{"n":31,"t":"利未人瑪他提雅是可拉族沙龍的長子，他受託做烤餅。","notes":[]},{"n":32,"t":"他們弟兄哥轄子孫中，有人負責每安息日排列供餅。","notes":[]},{"n":33,"t":"歌唱的有利未人的族長，住在殿的房間，晝夜供職，不做別樣的工。","notes":[]},{"n":34,"t":"以上都是利未人的族長，按各世系作領袖，他們都住在耶路撒冷。","notes":[]},{"n":35,"t":"在基遍住的有基遍的父親耶利，他的妻子名叫瑪迦；","notes":[],"heads":["掃羅王的祖先和後代"]},{"n":36,"t":"他的長子是亞伯頓，還有蘇珥、基士、巴力、尼珥、拿答、","notes":[]},{"n":37,"t":"基多、亞希約、撒迦利雅和米基羅。","notes":["「撒迦利雅」：代上8．31稱「撒迦」。"]},{"n":38,"t":"米基羅生示米暗。這些人在他們弟兄的對面，和他們的弟兄同住在耶路撒冷。","notes":[]},{"n":39,"t":"尼珥生基士；基士生掃羅；掃羅生約拿單、麥基‧舒亞、亞比拿達和伊施巴力。","notes":[]},{"n":40,"t":"約拿單的兒子是米力‧巴力；米力‧巴力生米迦。","notes":[]},{"n":41,"t":"米迦的兒子是毗敦、米勒、他利亞和亞哈斯。","notes":["原文沒有「亞哈斯」；參代上8．35。"]},{"n":42,"t":"亞哈斯生雅拉；雅拉生亞拉篾、亞斯瑪威和心利；心利生摩撒；","notes":["「雅拉」：代上8．36稱「耶何阿達」。"]},{"n":43,"t":"摩撒生比尼亞；比尼亞的兒子是利法雅，利法雅的兒子是以利亞薩，以利亞薩的兒子是亞悉。","notes":["「利法雅」：代上8．37稱「拉法」。"]},{"n":44,"t":"亞悉有六個兒子，他們的名字是亞斯利干、波基路、以實瑪利、示亞利雅、俄巴底雅和哈難；這些都是亞悉的兒子。","notes":["「亞斯利干、波基路」：七十士譯本是「他的長子亞斯利干」。"]}]},"10":{"heading":"掃羅逝世","verses":[{"n":1,"t":"非利士人攻打以色列。以色列人在非利士人面前逃跑，很多人在基利波山被殺仆倒。","notes":["「很多人」：原文是「他們」。"]},{"n":2,"t":"非利士人緊追掃羅和他的兒子，殺了掃羅的兒子約拿單、亞比拿達、麥基‧舒亞。","notes":[]},{"n":3,"t":"攻擊掃羅的戰事激烈，掃羅被弓箭手射中，被他們射傷。","notes":[]},{"n":4,"t":"掃羅吩咐拿他兵器的人說：「你拔出刀來，把我刺死，免得那些未受割禮的人來凌辱我。」但拿兵器的人非常懼怕，不肯刺他。於是掃羅拿起刀來，伏在刀上。","notes":[]},{"n":5,"t":"拿兵器的人見掃羅已死，也伏在刀上死了。","notes":[]},{"n":6,"t":"這樣，掃羅和他三個兒子，以及他的全家都一起陣亡了。","notes":[]},{"n":7,"t":"住平原的以色列眾人見以色列軍兵逃跑，掃羅和他兒子都死了，就棄城逃跑。非利士人前來，佔據了他們的城。","notes":["「以色列軍兵」：原文是「他們」。"]},{"n":8,"t":"次日，非利士人來剝那些被殺之人的衣服，看見掃羅和他兒子仆倒在基利波山。","notes":[]},{"n":9,"t":"他們剝了他的軍裝，拿著他的首級和盔甲，派人到非利士人之地的四境，報信給他們的偶像和百姓。","notes":[]},{"n":10,"t":"他們將掃羅的盔甲放在他們神明的廟裏，把他的首級釘在大袞廟中。","notes":[]},{"n":11,"t":"基列的雅比居民聽見非利士人向掃羅所行的一切事，","notes":[]},{"n":12,"t":"他們中間所有的勇士就起身，把掃羅和他兒子的屍身送到雅比，把他們的屍骨葬在雅比的橡樹下，禁食七日。","notes":[]},{"n":13,"t":"這樣，掃羅為了他的不忠死了；因為他干犯耶和華，沒有遵守耶和華的話，又因他求問招魂的婦人，","notes":[]},{"n":14,"t":"不求問耶和華，所以耶和華使他被殺，把王國給了耶西的兒子大衛。","notes":[]}]},"11":{"heading":"大衛作全以色列的王","verses":[{"n":1,"t":"以色列眾人聚集到希伯崙見大衛，說：「看哪，我們是你的骨肉。","notes":[]},{"n":2,"t":"從前掃羅作王的時候，率領以色列人出入的是你；耶和華－你的神也曾對你說：『你必牧養我的百姓以色列，你必作我百姓以色列的君王。』」","notes":[]},{"n":3,"t":"於是以色列的眾長老都來到希伯崙見王。大衛在希伯崙，在耶和華面前與他們立約，他們就膏大衛作以色列的王，正如耶和華藉撒母耳所說的話。","notes":[]},{"n":4,"t":"大衛和以色列眾人到了耶路撒冷，就是耶布斯；那時耶布斯人住在那裏。","notes":[]},{"n":5,"t":"耶布斯人對大衛說：「你必不能進到這裏。」然而大衛攻取了錫安的堡壘，就是大衛的城。","notes":[]},{"n":6,"t":"大衛說：「誰先攻打耶布斯人，必作領袖，作元帥。」洗魯雅的兒子約押先上去，就作了領袖。","notes":[]},{"n":7,"t":"大衛住在堡壘裏，所以那堡壘叫作大衛城。","notes":[]},{"n":8,"t":"大衛又從米羅起，四圍建築城牆，其餘的由約押修建。","notes":["「米羅」是音譯，指「土堆的防禦工事」。"]},{"n":9,"t":"大衛日見強大，萬軍之耶和華與他同在。","notes":[]},{"n":10,"t":"以下是跟隨大衛勇士的領袖；他們奮勇幫助他得到國度，並照著耶和華吩咐以色列的話，與以色列眾人一同立他作王。","notes":[],"heads":["大衛的勇士"]},{"n":11,"t":"大衛勇士的名單如下：哈革摩尼的兒子雅朔班，他是軍官的統領，曾一次舉槍殺了三百人。","notes":["「軍官的統領」：原文另譯「三十勇士之首」；有古譯本是「三勇士之首」。"]},{"n":12,"t":"其次是亞何亞人朵多的兒子以利亞撒，他是三個勇士裏的一個。","notes":[]},{"n":13,"t":"他從前與大衛在巴斯‧大憫，非利士人聚集要打仗。那裏有一塊長滿大麥的田。百姓在非利士人面前逃跑，","notes":[]},{"n":14,"t":"他們卻站在那塊田的中間，防守那田，擊敗了非利士人。耶和華大獲全勝。","notes":["「他們」：七十士譯本是「他」。"]},{"n":15,"t":"三十個領袖中的三個人下到磐石那裏，進了亞杜蘭洞見大衛；非利士的軍隊在利乏音谷安營。","notes":[]},{"n":16,"t":"那時大衛在山寨，非利士人的駐軍在伯利恆。","notes":[]},{"n":17,"t":"大衛渴想著說：「但願有人從伯利恆城門旁的井裏打水來給我喝！」","notes":[]},{"n":18,"t":"這三個勇士就闖過非利士人的軍營，從伯利恆城門旁的井裏打水，拿來給大衛喝。大衛卻不肯喝，將水澆在耶和華面前，","notes":[]},{"n":19,"t":"說：「我的神啊，我絕不做這事！這些人冒死去打水，這水是他們用生命換來的，我怎能喝他們的血呢？」大衛不肯喝這水。這是三個勇士所做的事。","notes":[]},{"n":20,"t":"約押的兄弟亞比篩是這三個勇士的領袖；他曾舉槍殺了三百人，就在三個勇士中得了名。","notes":["「三個」：有古譯本是「三十個」。"]},{"n":21,"t":"他在這三個勇士裏比其他兩個更有名望，所以作他們的領袖，只是不及前三個勇士。","notes":[]},{"n":22,"t":"耶何耶大的兒子比拿雅是來自甲薛的勇士，曾行了大事。他殺了摩押人亞利伊勒的兩個兒子，又在下雪的時候下到坑裏去，殺了一隻獅子。","notes":[]},{"n":23,"t":"他又殺了一個身高五肘的埃及人；埃及人手裏拿著槍，槍桿粗如織布機的軸。比拿雅只拿著棍子下到他那裏去，從埃及人手裏奪過槍來，用那槍殺死了他。","notes":[]},{"n":24,"t":"這些是耶何耶大的兒子比拿雅所做的事，就在三個勇士裏得了名。","notes":[]},{"n":25,"t":"看哪，他比那三十個勇士更有名望，只是不及前三個勇士。大衛立他作護衛長。","notes":[]},{"n":26,"t":"軍中的勇士有約押的兄弟亞撒黑，伯利恆人朵多的兒子伊勒哈難，","notes":[]},{"n":27,"t":"哈律人沙瑪，比倫人希利斯，","notes":[]},{"n":28,"t":"提哥亞人益吉的兒子以拉，亞拿突人亞比以謝，","notes":[]},{"n":29,"t":"戶沙人西比該，亞何亞人以來，","notes":[]},{"n":30,"t":"尼陀法人瑪哈萊，尼陀法人巴拿的兒子希立，","notes":[]},{"n":31,"t":"便雅憫族基比亞人利拜的兒子以太，比拉頓人比拿雅，","notes":[]},{"n":32,"t":"迦實溪人戶萊，亞拉巴人亞比，","notes":[]},{"n":33,"t":"巴路米人押斯瑪弗，沙本人以利雅哈巴，","notes":[]},{"n":34,"t":"基孫人哈深的眾兒子，哈拉人沙基的兒子約拿單，","notes":[]},{"n":35,"t":"哈拉人沙甲的兒子亞希暗，吾珥的兒子以利法勒，","notes":[]},{"n":36,"t":"米基拉人希弗，比倫人亞希雅，","notes":[]},{"n":37,"t":"迦密人希斯羅，伊斯拜的兒子拿萊，","notes":[]},{"n":38,"t":"拿單的兄弟約珥，哈基利的兒子彌伯哈，","notes":[]},{"n":39,"t":"亞捫人洗勒，比錄人拿哈萊，他是給洗魯雅的兒子約押拿兵器的，","notes":[]},{"n":40,"t":"以帖人以拉，以帖人迦立，","notes":[]},{"n":41,"t":"赫人烏利亞，亞萊的兒子撒拔，","notes":[]},{"n":42,"t":"呂便人示撒的兒子亞第拿，是呂便支派中的一個領袖，率領三十人，","notes":[]},{"n":43,"t":"瑪迦的兒子哈難，彌特尼人約沙法，","notes":[]},{"n":44,"t":"亞施他拉人烏西亞，亞羅珥人何坦的兒子沙瑪和耶利，","notes":[]},{"n":45,"t":"提洗人申利的兒子耶疊和他的兄弟約哈，","notes":[]},{"n":46,"t":"瑪哈未人以利業，伊利拿安的兒子耶利拜和約沙未雅，摩押人伊特瑪、","notes":[]},{"n":47,"t":"以利業、俄備得，以及米瑣八人雅西業。","notes":[]}]},"12":{"heading":"早期跟隨大衛的便雅憫人","verses":[{"n":1,"t":"以下是大衛因基士的兒子掃羅的緣故被放逐到洗革拉的時候，到他那裏幫助他打仗的勇士；","notes":[]},{"n":2,"t":"他們是弓箭手，能左右甩石，開弓射箭，都是便雅憫人掃羅同族的弟兄：","notes":[]},{"n":3,"t":"為首的是亞希以謝，其次是約阿施，都是基比亞人示瑪的兒子。還有亞斯瑪威的兒子耶薛和毗力，比拉迦，亞拿突人耶戶，","notes":[]},{"n":4,"t":"基遍人以實買雅，他在三十人中是勇士，管理這三十人，又有耶利米，雅哈悉，約哈難，基底拉人約撒拔，","notes":[]},{"n":5,"t":"伊利烏賽，耶利末，比亞利雅，示瑪利雅，哈律弗人示法提雅，","notes":[]},{"n":6,"t":"可拉人以利加拿、耶西亞、亞薩列、約以謝、雅朔班，","notes":[]},{"n":7,"t":"基多人耶羅罕的兒子猶拉和西巴第雅。","notes":[]},{"n":8,"t":"迦得人中有人到曠野的山寨投奔大衛，都是大能的勇士，能拿盾牌和槍的戰士。他們的面貌好像獅子，敏捷如山上的鹿。","notes":[],"heads":["跟隨大衛的迦得人"]},{"n":9,"t":"第一以薛，第二俄巴底雅，第三以利押，","notes":[]},{"n":10,"t":"第四彌施瑪拿，第五耶利米，","notes":[]},{"n":11,"t":"第六亞太，第七以利業，","notes":[]},{"n":12,"t":"第八約哈難，第九以利薩巴，","notes":[]},{"n":13,"t":"第十耶利米，第十一末巴奈。","notes":[]},{"n":14,"t":"這些都是迦得人中的軍官，小的能抵一百人，大的能抵一千人。","notes":["「小的能抵...一千人」或譯「較小的率領一百人，較大的率領一千人」。"]},{"n":15,"t":"正月，約旦河水漲過兩岸的時候，他們過河，使所有住河谷的人東奔西逃。","notes":[]},{"n":16,"t":"便雅憫人和猶大人中有人來到山寨大衛那裏。","notes":[],"heads":["跟隨大衛的便雅憫人和猶大人"]},{"n":17,"t":"大衛出去迎接他們，回答他們說：「你們若和平地來幫助我，我的心就與你們契合；但你們若把我這雙手無辜的人賣給敵人，願我們列祖的神察看責罰。」","notes":[]},{"n":18,"t":"那時軍官的領袖亞瑪撒受靈的感動說：「大衛啊，我們歸向你！耶西的兒子啊，我們幫助你！願你平平安安，願幫助你的也都平安！因為你的神幫助你。」大衛就收留他們，派他們作軍官。","notes":["「軍官」：原文另譯「那三十個勇士」。"]},{"n":19,"t":"大衛從前與非利士人同去，要與掃羅爭戰，有些瑪拿西人來投奔大衛。其實他們並沒有幫助非利士人，因為非利士人的領袖商議，打發他回去，說：「恐怕大衛拿我們的首級去向他的主人掃羅投誠。」","notes":[],"heads":["跟隨大衛的瑪拿西人"]},{"n":20,"t":"大衛往洗革拉去的時候，有瑪拿西人的千夫長押拿、約撒拔、耶疊、米迦勒、約撒拔、以利戶、洗勒太都來投奔他。","notes":[]},{"n":21,"t":"他們幫助大衛攻擊敵軍；因為他們都是大能的勇士，又作軍官。","notes":[]},{"n":22,"t":"那時天天有人來幫助大衛，以致成了強大的軍隊，如神的軍隊一樣。","notes":[]},{"n":23,"t":"以下是來到希伯崙見大衛，要照耶和華的話把掃羅的國位歸給大衛的武裝士兵的數目：","notes":[],"heads":["大衛的軍力"]},{"n":24,"t":"猶大人，拿盾牌和槍的武裝戰士有六千八百人。","notes":[]},{"n":25,"t":"西緬人中，能上陣的大能勇士有七千一百人。","notes":[]},{"n":26,"t":"利未人中，有四千六百人。","notes":[]},{"n":27,"t":"耶何耶大是亞倫家的領袖，跟從他的有三千七百人。","notes":[]},{"n":28,"t":"還有大能的青年勇士撒督，同他本族的二十二個軍官。","notes":[]},{"n":29,"t":"便雅憫人中，掃羅同族的弟兄也有三千人；直到現在他們大部分仍然效忠掃羅家。","notes":[]},{"n":30,"t":"以法蓮人中，在本族中著名的大能勇士有二萬零八百人。","notes":[]},{"n":31,"t":"瑪拿西半支派，冊上有名來擁立大衛作王的，有一萬八千人。","notes":[]},{"n":32,"t":"以薩迦人中，通達時務，知道以色列所當行，同族弟兄也都聽從他們命令的族長有二百人。","notes":[]},{"n":33,"t":"西布倫中，能上陣用各樣作戰的兵器、不生二心幫助打仗的有五萬人。","notes":[]},{"n":34,"t":"拿弗他利中，有一千個軍官；跟從他們、拿盾牌和槍的有三萬七千人。","notes":[]},{"n":35,"t":"但人中，能擺陣的有二萬八千六百人。","notes":[]},{"n":36,"t":"亞設中，能上陣打仗的有四萬人。","notes":[]},{"n":37,"t":"約旦河東的呂便人、迦得人、瑪拿西半支派，拿各樣兵器打仗的有十二萬人。","notes":[]},{"n":38,"t":"以上都是能列隊上陣的戰士，他們都全心來到希伯崙，要擁立大衛作全以色列的王。以色列其餘的人也都一心要擁立大衛作王。","notes":[]},{"n":39,"t":"他們在那裏三日，與大衛一同吃喝，因為他們同族的弟兄已經為他們預備好了。","notes":[]},{"n":40,"t":"他們附近的人，以及以薩迦、西布倫、拿弗他利人，都將食物，許多麵餅、無花果餅、乾葡萄、酒、油，用驢、駱駝、騾子、牛馱來，又帶了許多的牛和羊來，因為在以色列中充滿了歡樂。","notes":[]}]},"13":{"heading":"約櫃遷出基列‧耶琳","verses":[{"n":1,"t":"大衛與千夫長、百夫長，以及所有的領袖商議。","notes":[]},{"n":2,"t":"大衛對以色列全會眾說：「你們若以為好，見這事是出於耶和華－我們的神，我們就派人到遠近各處去見仍留在以色列各地我們的弟兄，以及住在有郊野之城的祭司和利未人，使他們都到我們這裏來聚集。","notes":[]},{"n":3,"t":"我們要把神的約櫃接到這裏來；因為在掃羅年間，我們沒有去尋求約櫃。」","notes":["「約櫃」或譯「神」。"]},{"n":4,"t":"全會眾都說可以這麼做，因這事在眾百姓眼中都看為好。","notes":[]},{"n":5,"t":"於是，大衛把以色列眾人從埃及的西曷河直到哈馬口都召集了來，要從基列‧耶琳將神的約櫃接來。","notes":[]},{"n":6,"t":"大衛率領以色列眾人上到巴拉，就是屬猶大的基列‧耶琳，要將耶和華神的約櫃從那裏接上來，他坐在二基路伯之上，這約櫃是以他的名來命名的。","notes":[]},{"n":7,"t":"他們將神的約櫃從亞比拿達的家裏抬出來，放在新車上，由烏撒和亞希約趕車。","notes":[]},{"n":8,"t":"大衛和以色列眾人在神面前隨著詩歌、琴、瑟、鼓、鈸、號，極力跳舞。","notes":[]},{"n":9,"t":"到了基頓的禾場，因為牛失前蹄，烏撒就伸手扶住約櫃。","notes":["「基頓」：撒下6．6是「拿艮」。","「失前蹄」或譯「驚跳」。"]},{"n":10,"t":"耶和華的怒氣向烏撒發作，因他伸手扶住約櫃而擊殺他，他就死在那裏，在神面前。","notes":[]},{"n":11,"t":"大衛因耶和華突然衝出撞死烏撒就生氣，稱那地方為毗列斯‧烏撒，直到今日。","notes":[]},{"n":12,"t":"那日，大衛懼怕神，說：「我怎能將神的約櫃接到我這裏來呢？」","notes":[]},{"n":13,"t":"於是大衛不將約櫃接進大衛城他自己的地方，卻轉送到迦特人俄別‧以東的家中。","notes":[]},{"n":14,"t":"神的約櫃停在俄別‧以東家中三個月，耶和華賜福給俄別‧以東的家和他一切所有的。","notes":[]}]},"14":{"heading":"大衛在耶路撒冷的活動","verses":[{"n":1,"t":"推羅王希蘭派使者把香柏木運到大衛那裏，又派石匠和木匠給大衛建造宮殿。","notes":[]},{"n":2,"t":"大衛知道耶和華堅立他作以色列王，又為自己百姓以色列的緣故，使他的國興盛。","notes":[]},{"n":3,"t":"大衛在耶路撒冷又立后妃，又生兒女。","notes":[]},{"n":4,"t":"在耶路撒冷所生的孩子名字是沙母亞、朔罷、拿單、所羅門、","notes":["「沙母亞」：代上3．5稱「示米亞」。"]},{"n":5,"t":"益轄、以利書亞、以法列、","notes":["「以利書亞」：代上3．6稱「以利沙瑪」。","「以法列」：代上3．6稱「以利法列」。"]},{"n":6,"t":"挪迦、尼斐、雅非亞、","notes":[]},{"n":7,"t":"以利沙瑪、比利雅大、以利法列。","notes":["「比利雅大」：撒下5．16，代上3．8稱「以利雅大」。"]},{"n":8,"t":"非利士人聽見大衛受膏作全以色列的王，非利士眾人就上來尋索大衛。大衛聽見了，就出去迎敵。","notes":[],"heads":["戰勝非利士人"]},{"n":9,"t":"非利士人來了，侵犯利乏音谷。","notes":[]},{"n":10,"t":"大衛求問神說：「我可以上去攻打非利士人嗎？你將他們交在我手裏嗎？」耶和華對他說：「你可以上去，我必將他們交在你手裏。」","notes":[]},{"n":11,"t":"非利士人上到巴力‧毗拉心，大衛在那裏擊敗他們。大衛說：「神藉我的手沖破敵人，如水沖破一樣。」因此那地方稱為巴力‧毗拉心。","notes":[]},{"n":12,"t":"非利士人把神像拋棄在那裏，大衛吩咐人用火焚燒了。","notes":[]},{"n":13,"t":"非利士人又侵犯利乏音谷。","notes":[]},{"n":14,"t":"大衛再求問神。神對他說：「不要從他們後頭追上去，要繞道離開他們，從桑樹林對面攻打他們。","notes":[]},{"n":15,"t":"你聽見桑樹梢上有腳步的聲音，那時你就要出戰，因為神已經出去，在你前頭攻打非利士人的軍隊了。」","notes":[]},{"n":16,"t":"大衛就遵照神所吩咐的去做，攻打非利士人的軍隊，從基遍直到基色。","notes":[]},{"n":17,"t":"於是大衛的名傳揚到萬邦，耶和華使萬國都懼怕他。","notes":[]}]},"15":{"heading":"準備迎接約櫃","verses":[{"n":1,"t":"大衛在大衛城為自己建造宮殿，又為神的約櫃預備地方，支搭帳幕。","notes":[]},{"n":2,"t":"那時大衛說：「除了利未人之外，無人可抬神的約櫃，因為耶和華揀選他們抬神的約櫃，永遠事奉他。」","notes":[]},{"n":3,"t":"大衛召集以色列眾人到耶路撒冷，要將耶和華的約櫃接到他所預備的地方。","notes":[]},{"n":4,"t":"大衛又召集亞倫的子孫和利未人：","notes":[]},{"n":5,"t":"哥轄子孫中有領袖烏列和他的弟兄一百二十人，","notes":[]},{"n":6,"t":"米拉利子孫中有領袖亞帥雅和他的弟兄二百二十人，","notes":[]},{"n":7,"t":"革順子孫中有領袖約珥和他的弟兄一百三十人，","notes":[]},{"n":8,"t":"以利撒反子孫中有領袖示瑪雅和他的弟兄二百人，","notes":[]},{"n":9,"t":"希伯倫子孫中有領袖以利業和他的弟兄八十人，","notes":[]},{"n":10,"t":"烏薛子孫中有領袖亞米拿達和他的弟兄一百一十二人。","notes":[]},{"n":11,"t":"大衛召來撒督和亞比亞他二位祭司，以及利未人烏列、亞帥雅、約珥、示瑪雅、以利業、亞米拿達，","notes":[]},{"n":12,"t":"對他們說：「你們是利未人的族長，你們和你們的弟兄應當使自己分別為聖，好將耶和華－以色列神的約櫃接到我所預備的地方。","notes":[]},{"n":13,"t":"因為你們上一次沒有抬這約櫃，並且我們沒有按規矩求問耶和華－我們的神，所以他衝出來攻擊我們。」","notes":[]},{"n":14,"t":"於是祭司和利未人使自己分別為聖，將耶和華－以色列神的約櫃接上來。","notes":[]},{"n":15,"t":"利未子孫用槓，把神的約櫃抬在肩上，正如摩西按照耶和華的話所吩咐的。","notes":[]},{"n":16,"t":"大衛吩咐利未人的領袖派他們歌唱的弟兄用琴瑟和鈸的樂器奏樂，歡歡喜喜地大聲歌頌。","notes":[]},{"n":17,"t":"於是利未人派約珥的兒子希幔和他弟兄中比利家的兒子亞薩，以及他們同族弟兄米拉利子孫裏古沙雅的兒子以探。","notes":[]},{"n":18,"t":"其次還有跟隨他們的弟兄撒迦利雅、便‧雅薛、示米拉末、耶歇、烏尼、以利押、比拿雅、瑪西雅、瑪他提雅、以利斐利戶、彌克尼雅，以及門口的守衛俄別‧以東和耶利。","notes":["「便‧雅薛」：有古卷和七十士譯本是「雅薛」。"]},{"n":19,"t":"歌唱的希幔、亞薩和以探，敲銅鈸，聲音響亮；","notes":[]},{"n":20,"t":"撒迦利雅、雅薛、示米拉末、耶歇、烏尼、以利押、瑪西雅、比拿雅鼓瑟，調用女音；","notes":[]},{"n":21,"t":"瑪他提雅、以利斐利戶、彌克尼雅、俄別‧以東、耶利、亞撒西雅用琴指揮，調用第八。","notes":[]},{"n":22,"t":"基拿尼雅是利未人聖詠團的領袖，又教導人唱歌，因為他精通此事。","notes":[]},{"n":23,"t":"比利家和以利加拿是約櫃的守衛。","notes":[]},{"n":24,"t":"示巴尼、約沙法、拿坦業、亞瑪賽、撒迦利雅、比拿亞、以利以謝眾祭司在神的約櫃前吹號。俄別‧以東和耶希亞也是約櫃的守衛。","notes":[]},{"n":25,"t":"於是，大衛和以色列的長老，以及千夫長都去，歡歡喜喜地將耶和華的約櫃從俄別‧以東家中接上來。","notes":[],"heads":["約櫃遷入耶路撒冷"]},{"n":26,"t":"神賜恩給抬耶和華約櫃的利未人，他們就獻上七頭公牛、七隻公羊。","notes":[]},{"n":27,"t":"大衛和所有抬約櫃的利未人，以及聖詠團的領袖基拿尼雅和歌唱的人，都穿著細麻布外袍；大衛另外穿著細麻布以弗得。","notes":[]},{"n":28,"t":"這樣，以色列眾人歡呼、吹角、吹號、敲鈸、鼓瑟、彈琴，聲音響亮，將耶和華的約櫃接上來。","notes":[]},{"n":29,"t":"耶和華的約櫃進大衛城的時候，掃羅的女兒米甲從窗戶裏往外觀看，見大衛王踴躍跳舞，心裏就輕視他。","notes":[]}]},"16":{"heading":"頌讚之歌","verses":[{"n":1,"t":"眾人將神的約櫃請進去，安放在大衛為它搭的帳幕中，就在神面前獻燔祭和平安祭。","notes":[]},{"n":2,"t":"大衛獻完了燔祭和平安祭，就奉耶和華的名祝福百姓，","notes":[]},{"n":3,"t":"並且分給每一個以色列人，無論男女，每人一個餅，一個棗子餅，一個葡萄餅。","notes":["「一個棗子餅」：有古譯本是「一塊肉」。"]},{"n":4,"t":"大衛派幾個利未人在耶和華的約櫃前事奉，頌揚，稱謝，讚美耶和華－以色列的神：","notes":[]},{"n":5,"t":"為首的是亞薩，其次是撒迦利雅、耶利、示米拉末、耶歇、瑪他提雅、以利押、比拿雅、俄別‧以東、耶利；他們鼓瑟彈琴，亞薩敲鈸，聲音響亮；","notes":["「耶利」：原文另譯「雅薛」；參代上15．18，20。"]},{"n":6,"t":"比拿雅和雅哈悉二位祭司常在神的約櫃前吹號。","notes":[]},{"n":7,"t":"那日，大衛初次指派亞薩和他的弟兄稱謝耶和華。","notes":[]},{"n":8,"t":"你們要稱謝耶和華，求告他的名，在萬民中傳揚他的作為！","notes":[]},{"n":9,"t":"要向他唱詩，向他歌頌，述說他一切奇妙的作為！","notes":[]},{"n":10,"t":"要誇耀他的聖名！願尋求耶和華的人心中歡喜！","notes":[]},{"n":11,"t":"要尋求耶和華與他的能力，時常尋求他的面。","notes":[]},{"n":12,"t":"他僕人以色列的後裔，他所揀選雅各的子孫哪，要記念他奇妙的作為和他的奇事，並他口中的判語。","notes":[],"end":13},{"n":14,"t":"他是耶和華－我們的神，全地都有他的判斷。","notes":[]},{"n":15,"t":"要記念他的約，直到永遠；記念他吩咐的話，直到千代，","notes":[]},{"n":16,"t":"就是他與亞伯拉罕所立的約，向以撒所起的誓。","notes":[]},{"n":17,"t":"他將這約向雅各定為律例，向以色列定為永遠的約，","notes":[]},{"n":18,"t":"說：「我必將迦南地賜給你，作你們應得的產業。」","notes":[]},{"n":19,"t":"當時，你們人丁有限，數目稀少，在那地寄居。","notes":[]},{"n":20,"t":"他們從這邦遊到那邦，從這國去到另一民族。","notes":[]},{"n":21,"t":"他不容人欺負他們，為他們的緣故責備君王：","notes":[]},{"n":22,"t":"「不可傷害我的受膏者，也不可惡待我的先知。」","notes":[]},{"n":23,"t":"全地都要向耶和華歌唱！天天傳揚他的救恩！","notes":[]},{"n":24,"t":"在列國中述說他的榮耀！在萬民中述說他的奇事！","notes":[]},{"n":25,"t":"因耶和華本為大，當受極大的讚美；他在萬神之上，當受敬畏。","notes":[]},{"n":26,"t":"因萬民的神明都屬虛無；惟獨耶和華創造諸天。","notes":[]},{"n":27,"t":"有尊榮和威嚴在他面前，有能力和喜樂在他自己的地方。","notes":[]},{"n":28,"t":"民中的萬族啊，要將榮耀、能力歸給耶和華，都歸給耶和華！","notes":[]},{"n":29,"t":"要將耶和華的名所當得的榮耀歸給他，拿供物來獻在他面前；當敬拜神聖榮耀的耶和華。","notes":["「當敬拜...耶和華」或譯「當以聖潔的妝飾敬拜耶和華」。"]},{"n":30,"t":"全地都要在他面前戰抖！世界堅定，不得動搖。","notes":[]},{"n":31,"t":"願天歡喜，願地快樂！願人在列國中說：「耶和華作王了！」","notes":[]},{"n":32,"t":"願海和其中所充滿的澎湃！願田和其中所有的都歡樂！","notes":[]},{"n":33,"t":"那時，林中的樹木都要在耶和華面前歡呼，因為他來要審判全地。","notes":[]},{"n":34,"t":"你們要稱謝耶和華，因他本為善，他的慈愛永遠長存！","notes":[]},{"n":35,"t":"你們要說：「拯救我們的神啊，求你拯救我們，聚集我們，救我們脫離列國，我們好頌揚你的聖名，以讚美你為誇勝。","notes":[]},{"n":36,"t":"耶和華－以色列的神是應當稱頌的，從亙古直到永遠。」全體百姓都說：「阿們！」並且讚美耶和華。","notes":[]},{"n":37,"t":"大衛把亞薩和他的弟兄留在耶和華的約櫃那裏，經常在約櫃前事奉，天天盡本分供職，","notes":[],"heads":["在耶路撒冷和基遍的敬拜"]},{"n":38,"t":"又有俄別‧以東和他的弟兄六十八人；耶杜頓的兒子俄別‧以東，以及何薩作門口的守衛。","notes":[]},{"n":39,"t":"還有撒督祭司和他弟兄眾祭司在基遍的丘壇、耶和華的帳幕前，","notes":[]},{"n":40,"t":"在燔祭壇上，每日早晚，照著寫在耶和華律法書上所吩咐以色列的，經常獻燔祭給耶和華。","notes":[]},{"n":41,"t":"與他們一同的還有希幔、耶杜頓，和其餘被選、名字錄在冊上的，為要稱謝耶和華，因他的慈愛永遠長存。","notes":[]},{"n":42,"t":"希幔、耶杜頓同他們吹號、敲鈸，聲音響亮，並用其他樂器配合，歌頌神。耶杜頓的子孫作門口的守衛。","notes":[]},{"n":43,"t":"於是眾百姓各自回家，大衛也回去為家人祝福。","notes":[]}]},"17":{"heading":"拿單傳給大衛的信息","verses":[{"n":1,"t":"大衛住在自己宮中，對拿單先知說：「看哪，我住在香柏木的宮中，耶和華的約櫃卻在幔子裏。」","notes":[]},{"n":2,"t":"拿單對大衛說：「你可以完全照你的心意去做，因為神與你同在。」","notes":[]},{"n":3,"t":"當夜神的話臨到拿單，說：","notes":[]},{"n":4,"t":"「你去對我僕人大衛說：『耶和華如此說：你不可建造殿宇給我居住。","notes":[]},{"n":5,"t":"自從我領以色列人上來，直到今日，我未曾住過殿宇；我從這會幕到那會幕，從這帳幕到那帳幕。","notes":["原文沒有「到那帳幕」。"]},{"n":6,"t":"凡我同以色列人所走的地方，我何曾向以色列的一個士師，就是我吩咐牧養我百姓的，說過這話：你們為何不給我建造香柏木的殿宇呢？』","notes":[]},{"n":7,"t":"現在，你要對我僕人大衛這樣說：『萬軍之耶和華如此說：我從羊圈中將你召來，叫你不再牧放羊群，立你作我百姓以色列的君王。","notes":[]},{"n":8,"t":"你無論往哪裏去，我都與你同在，剪除你所有的仇敵。我必使你得大名，好像世上偉人的名一樣。","notes":[]},{"n":9,"t":"我必為我百姓以色列選定一個地方，栽植他們，使他們住自己的地方，不再受攪擾；兇惡之子也不再像從前那樣擾亂他們，","notes":[]},{"n":10,"t":"並不像我命令士師治理我百姓以色列的日子。我必制伏你所有的仇敵，並且我應許你，耶和華必為你建立家室。","notes":["「我應許你」：七十士譯本是「我要使你為大」。"]},{"n":11,"t":"當你壽數滿足歸你祖先的時候，我必使你的後裔，你自己的兒子接續你；我也必堅定他的國。","notes":[]},{"n":12,"t":"他必為我建造殿宇，我必堅定他的王位，直到永遠。","notes":[]},{"n":13,"t":"我要作他的父，他要作我的子；我必不使我的慈愛離開他，像離開在你以前的那位一樣。","notes":[]},{"n":14,"t":"我要永遠堅立他在我的家和我的國裏；他的王位也必堅定，直到永遠。』」","notes":[]},{"n":15,"t":"拿單就按這一切話，照這一切異象告訴大衛。","notes":[]},{"n":16,"t":"於是大衛王進去，坐在耶和華面前，說：「耶和華神啊，我是誰，我的家算甚麼，你竟帶領我到這地步呢？","notes":[],"heads":["感恩的禱告"]},{"n":17,"t":"神啊，這在你眼中還看為小，你又說到你僕人的家將來的情況。耶和華神啊，你看顧我好像看顧尊貴的人。","notes":[]},{"n":18,"t":"你加於僕人的尊榮，大衛還有甚麼可以對你說呢？你是知道你僕人的。","notes":[]},{"n":19,"t":"耶和華啊，因你僕人的緣故，也照著你的心意，你行這一切大事，為了顯明這一切偉大的事。","notes":[]},{"n":20,"t":"耶和華啊，照我們耳中一切所聽見的，沒有可比你的，除你以外再沒有神。","notes":[]},{"n":21,"t":"世上有何國能比你的百姓以色列呢？神親自去救贖世上的一國，作自己的子民，又行大而可畏的事，顯出你的大名，在你從埃及贖出來的子民面前驅逐了列國。","notes":["「世上...一國」：七十士譯本是「世上沒有另一國能比你的百姓以色列，是神親自去救贖」。"]},{"n":22,"t":"你使你的百姓以色列作你的子民，直到永遠；你－耶和華也作他們的神。","notes":[]},{"n":23,"t":"現在，耶和華啊，你所應許僕人和僕人家的話，求你堅定，直到永遠；求你照你所說的而行。","notes":[]},{"n":24,"t":"願你的名永遠堅立，被尊為大，人要說：『萬軍之耶和華－以色列的神，是以色列的神。』這樣，你僕人大衛的家必在你面前堅立。","notes":[]},{"n":25,"t":"我的神啊，因你啟示你的僕人，要為他建立家室，所以僕人大膽在你面前祈禱。","notes":[]},{"n":26,"t":"現在，耶和華啊，惟有你是神！你應許將這福氣賜給僕人。","notes":[]},{"n":27,"t":"現在，你喜悅賜福給僕人的家，可以永存在你面前。耶和華啊，因你已經賜福，還要賜福到永遠。」","notes":[]}]},"18":{"heading":"耶和華使大衛得勝","verses":[{"n":1,"t":"此後，大衛攻打非利士人，制伏了他們，從非利士人手中奪取了迦特和所屬的鄉鎮。","notes":[]},{"n":2,"t":"他又攻打摩押，摩押人就臣服大衛，向他進貢。","notes":[]},{"n":3,"t":"瑣巴王哈大底謝往幼發拉底河去，要鞏固自己的國權。大衛攻打他，直到哈馬，","notes":["「哈大底謝」：有許多抄本是「哈大利謝」；本卷書下同。"]},{"n":4,"t":"奪了他的戰車一千，俘擄了騎兵七千人，步兵二萬人。大衛把所有戰馬的蹄筋砍斷，只留下一百輛戰車。","notes":[]},{"n":5,"t":"大馬士革的亞蘭人來幫助瑣巴王哈大底謝，大衛殺了亞蘭人二萬二千。","notes":[]},{"n":6,"t":"於是大衛在大馬士革的亞蘭地設立軍營，亞蘭人就臣服大衛，向他進貢。大衛無論往哪裏去，耶和華都使他得勝。","notes":["「設立軍營」是根據一些古卷和七十士譯本，原文沒有「軍營」；參撒下8．6。"]},{"n":7,"t":"大衛奪了哈大底謝臣僕擁有的金盾牌，帶到耶路撒冷。","notes":[]},{"n":8,"t":"大衛又從哈大底謝的提巴和均二城奪取了許多的銅；後來所羅門用這些銅製造銅海、銅柱和銅器。","notes":[]},{"n":9,"t":"哈馬王陀烏聽見大衛擊敗瑣巴王哈大底謝的全軍，","notes":["「陀烏」：撒下8．9稱「陀以」；下同。"]},{"n":10,"t":"就派他兒子哈多蘭到大衛王那裏，向他請安，為他祝福，因他與哈大底謝爭戰，並且擊敗了他；原來哈大底謝與陀烏常常爭戰。哈多蘭帶了金銀銅的各樣器皿來。","notes":["「哈多蘭」：撒下8．10稱「約蘭」。"]},{"n":11,"t":"大衛王把這些器皿，以及從各國奪來的金銀，就是從以東、摩押、亞捫人、非利士人、亞瑪力所奪來的，都分別為聖獻給耶和華。","notes":[]},{"n":12,"t":"洗魯雅的兒子亞比篩在鹽谷擊殺了一萬八千以東人。","notes":[]},{"n":13,"t":"大衛在以東設立軍營，以東人就都臣服他。大衛無論往哪裏去，耶和華都使他得勝。","notes":[]},{"n":14,"t":"大衛作全以色列的王，又向眾百姓秉公行義。","notes":[]},{"n":15,"t":"洗魯雅的兒子約押作元帥；亞希律的兒子約沙法作史官；","notes":[]},{"n":16,"t":"亞希突的兒子撒督和亞比亞他的兒子亞希米勒作祭司；沙威沙作書記；","notes":[]},{"n":17,"t":"耶何耶大的兒子比拿雅管轄基利提人和比利提人。大衛的眾兒子都在王的左右作領袖。","notes":[]}]},"19":{"heading":"擊敗亞捫人和亞蘭人","verses":[{"n":1,"t":"此後，亞捫人的王拿轄死了，他兒子接續他作王。","notes":[]},{"n":2,"t":"大衛說：「哈嫩的父親拿轄怎樣向我施恩，我也要怎樣向哈嫩施恩。」於是大衛派使者為他的父親安慰他。大衛的臣僕到了亞捫人的境內來見哈嫩，要安慰他。","notes":[]},{"n":3,"t":"但亞捫人的領袖對哈嫩說：「大衛派人來安慰你，你看他是要尊敬你父親嗎？他的臣僕來見你，不是為了要窺探偵察，而傾覆這地嗎？」","notes":[]},{"n":4,"t":"哈嫩就抓住大衛的臣僕，剃去他們的鬍鬚，又割斷他們下半截的衣服，露出臀部，然後放了他們。","notes":[]},{"n":5,"t":"他們走了，有人把臣僕所遭遇的事告訴大衛，他就派人去迎接他們，因為這些人覺得很羞恥。王說：「可以住在耶利哥，等到鬍鬚長出來再回來。」","notes":[]},{"n":6,"t":"亞捫人看到大衛憎惡他們，哈嫩和亞捫人就派人拿一千他連得銀子，從美索不達米亞、亞蘭‧瑪迦、瑣巴雇用戰車和騎兵。","notes":[]},{"n":7,"t":"他們雇了三萬二千輛戰車，以及瑪迦王和他的軍兵；這些部隊來安營在米底巴前。亞捫人也從他們的城裏出來，聚集預備作戰。","notes":[]},{"n":8,"t":"大衛聽見了，就派約押和所有勇猛的軍隊出去。","notes":[]},{"n":9,"t":"亞捫人出來，在城門前擺陣，前來的諸王另在郊野擺陣。","notes":[]},{"n":10,"t":"約押看見戰陣對著他前後擺列，就把從以色列所有精兵中挑選出來的，擺陣迎戰亞蘭人。","notes":[]},{"n":11,"t":"他把其餘的兵交在他兄弟亞比篩手裏，他們就擺陣迎戰亞捫人。","notes":[]},{"n":12,"t":"約押說：「亞蘭人若強過我，你就來幫助我；亞捫人若強過你，我就去幫助你。","notes":[]},{"n":13,"t":"你要剛強，我們要為自己的百姓，為我們神的城鎮奮勇。願耶和華照他所看為好的去做！」","notes":[]},{"n":14,"t":"於是，約押和跟隨他的士兵前進攻打亞蘭人；亞蘭人在他面前逃跑。","notes":[]},{"n":15,"t":"亞捫人見亞蘭人逃跑，他們也在約押的兄弟亞比篩面前逃跑進城。約押就回耶路撒冷去了。","notes":[]},{"n":16,"t":"亞蘭人見自己被以色列打敗，就派使者把大河那邊的亞蘭人調來，由哈大底謝的將軍朔法在他們前面率領。","notes":[]},{"n":17,"t":"有人告訴大衛，他就聚集以色列眾人過約旦河，來到亞蘭人那裏，迎著他們擺陣。大衛擺陣攻擊亞蘭人，亞蘭人就與他打仗。","notes":[]},{"n":18,"t":"亞蘭人在以色列人面前逃跑。大衛殺了亞蘭七千輛戰車的士兵，四萬步兵，又殺死亞蘭的將軍朔法。","notes":[]},{"n":19,"t":"哈大底謝的臣僕見自己被以色列打敗，就與大衛講和，臣服他。於是亞蘭人不願再幫助亞捫人了。","notes":[]}]},"20":{"heading":"大衛攻取拉巴","verses":[{"n":1,"t":"到了年初，諸王出征的時候，約押率領軍兵蹂躪亞捫人的地，前來圍攻拉巴；大衛仍住在耶路撒冷。約押攻打拉巴，把它毀壞。","notes":[]},{"n":2,"t":"大衛奪了米勒公所戴的冠冕，其上的金子重一他連得，又嵌著寶石。這冠冕就戴在大衛頭上。大衛又從城裏奪了許多財物，","notes":["「米勒公」是根據七十士譯本和其他古譯本，亞捫人神明的名字，又名「摩洛」；原文是「他們的王」，音譯「瑪勒堪」。"]},{"n":3,"t":"把城裏的百姓拉出來，放在鋸下，或鐵耙下，或斧的下面；大衛待亞捫各城的居民都是如此。於是，大衛和全軍都回耶路撒冷去了。","notes":["「斧」是根據一些古卷；原文是「鋸」。"]},{"n":4,"t":"後來，以色列人在基色與非利士人打仗。戶沙人西比該殺了巨人族的後裔細派，非利士人就被制伏了。","notes":[],"heads":["與非利士巨人爭戰"]},{"n":5,"t":"他們又與非利士人打仗。睚珥的兒子伊勒哈難殺了迦特人歌利亞的兄弟拉哈米；這人的槍桿粗如織布機的軸。","notes":[]},{"n":6,"t":"又有一次，他們在迦特打仗。那裏有一個身材高大的人，手指腳趾都是六根，共有二十四根；他也是巨人族的後裔。","notes":[]},{"n":7,"t":"他向以色列罵陣，大衛的哥哥示米亞的兒子約拿單就殺了他。","notes":[]},{"n":8,"t":"這些人是迦特巨人族的後裔，都仆倒在大衛和他僕人的手下。","notes":[]}]},"21":{"heading":"大衛數點以色列民","verses":[{"n":1,"t":"撒但起來攻擊以色列，激起大衛數點以色列人。","notes":[]},{"n":2,"t":"大衛對約押和百姓的領袖說：「去，數點以色列人，從別是巴直到但，回來告訴我，我好知道他們的數目。」","notes":[]},{"n":3,"t":"約押說：「願耶和華使他的百姓比現在加增百倍。我主我王啊，他們不都是我主的僕人嗎？我主為何吩咐行這事，為何使以色列陷入罪裏呢？」","notes":[]},{"n":4,"t":"但王堅持他對約押的命令。約押就出去，來回走遍以色列，然後回到耶路撒冷。","notes":[]},{"n":5,"t":"約押向大衛報告百姓的總數：全以色列拿刀的有一百一十萬人；猶大拿刀的有四十七萬人。","notes":[]},{"n":6,"t":"惟有利未人和便雅憫人沒有算在其中，因為約押厭惡王的這命令。","notes":[]},{"n":7,"t":"這件事在神眼中看為惡，神就降災給以色列。","notes":[]},{"n":8,"t":"大衛對神說：「我做這事大大有罪了。現在求你除掉僕人的罪孽，因為我所做的非常愚昧。」","notes":[]},{"n":9,"t":"耶和華吩咐迦得，大衛的先見，說：","notes":[]},{"n":10,"t":"「你去告訴大衛說：『耶和華如此說：我列出三樣災禍給你，隨你選擇一樣，我好降與你。』」","notes":[]},{"n":11,"t":"於是，迦得來到大衛那裏，對他說：「耶和華如此說：『你可以隨意選擇：","notes":[]},{"n":12,"t":"三年的饑荒，或敗在敵人面前，被敵人的刀追殺三個月，或在國中三日有耶和華的刀，就是瘟疫，讓耶和華的使者在以色列全境施行毀滅呢？』現在你要想一想，我怎樣去回覆那差我來的。」","notes":[]},{"n":13,"t":"大衛對迦得說：「我很為難。我寧願落在耶和華的手裏，因為他有豐盛的憐憫；我不願落在人的手裏。」","notes":[]},{"n":14,"t":"於是，耶和華降瘟疫給以色列，以色列中死了七萬人。","notes":[]},{"n":15,"t":"神派遣使者去毀滅耶路撒冷，剛要毀滅的時候，耶和華看見就改變心意，不降這災了。他吩咐那滅城的天使說：「夠了，住手吧！」耶和華的使者正站在耶布斯人阿珥楠的禾場那裏。","notes":["「阿珥楠」：撒下24．16稱「亞勞拿」；下同。"]},{"n":16,"t":"大衛舉目，看見耶和華的使者站在天和地之間，手裏有拔出來的刀，伸在耶路撒冷以上。大衛和長老都披上麻布，臉伏於地。","notes":[]},{"n":17,"t":"大衛向神說：「吩咐數點百姓的不是我嗎？是我犯了罪，行了大惡，但這群羊做了甚麼呢？耶和華－我的神啊，願你的手攻擊我和我的父家，不要降瘟疫給你的百姓。」","notes":[]},{"n":18,"t":"耶和華的使者吩咐迦得去告訴大衛，叫他上去，在耶布斯人阿珥楠的禾場上為耶和華立一座壇。","notes":[]},{"n":19,"t":"大衛就照著迦得奉耶和華名所說的話上去。","notes":[]},{"n":20,"t":"阿珥楠回頭看見天使，跟他在一起的四個兒子都藏起來了，阿珥楠繼續打麥子。","notes":[]},{"n":21,"t":"大衛到了阿珥楠那裏，阿珥楠觀看，看見大衛，就從禾場上出去，臉伏於地，向他下拜。","notes":[]},{"n":22,"t":"大衛對阿珥楠說：「你把這禾場的地方給我，照著十足的價錢賣給我，我好在其上為耶和華築一座壇，使瘟疫在百姓中停止。」","notes":[]},{"n":23,"t":"阿珥楠對大衛說：「請用這禾場吧，願我主我王照你眼中看為好的去做。看，我提供牛作燔祭，打糧的器具作柴，麥子作素祭，這一切我全都提供。」","notes":[]},{"n":24,"t":"大衛王對阿珥楠說：「不，我一定要按十足的價錢買；因我不能用你的東西獻給耶和華，也不能用白得之物獻為燔祭。」","notes":[]},{"n":25,"t":"於是大衛為那個地方付了六百舍客勒重的金子給阿珥楠。","notes":[]},{"n":26,"t":"大衛在那裏為耶和華築了一座壇，獻燔祭和平安祭，求告耶和華。耶和華就應允他，使火從天降在燔祭壇上。","notes":[]},{"n":27,"t":"耶和華吩咐使者，他就收刀入鞘。","notes":[]},{"n":28,"t":"那時，大衛見耶和華在耶布斯人阿珥楠的禾場上應允了他，就在那裏獻祭。","notes":[]},{"n":29,"t":"摩西在曠野所造之耶和華的帳幕和燔祭壇，當時都在基遍的丘壇，","notes":[]},{"n":30,"t":"只是大衛不能前去求問神，因為他懼怕耶和華使者的刀。","notes":[]}]},"22":{"heading":"籌備建殿","verses":[{"n":1,"t":"大衛說：「這是耶和華神的殿，這是以色列獻燔祭的壇。」","notes":[]},{"n":2,"t":"大衛吩咐人召集住以色列地的寄居者，又派石匠鑿石頭，要建造神的殿。","notes":[]},{"n":3,"t":"大衛預備許多鐵，要做門上的釘子和鉤子，又預備許多銅，多得無法可秤；","notes":[]},{"n":4,"t":"還有無數的香柏木，因為西頓人和推羅人給大衛運了許多香柏木來。","notes":[]},{"n":5,"t":"大衛說：「我兒子所羅門還年幼脆弱，要為耶和華建造的殿宇必須高大輝煌，使名聲榮耀傳遍萬國，所以我要為殿預備。」於是，大衛在未死之前預備了許多材料。","notes":[]},{"n":6,"t":"大衛召了他兒子所羅門來，吩咐他為耶和華－以色列的神建造殿宇。","notes":[]},{"n":7,"t":"大衛對所羅門說：「我兒啊，我心裏本想為耶和華－我神的名建造殿宇，","notes":[]},{"n":8,"t":"可是耶和華的話臨到我說：『你流了許多的血，打了多次大仗；你不可為我的名建造殿宇，因為你在我面前使許多血流在地上。","notes":[]},{"n":9,"t":"看哪，你要生一個兒子，他必成為安寧的人；我必使他得享安寧，不被四圍仇敵擾亂。他的名字要叫所羅門，在他的日子，我必使以色列平安康泰。","notes":["「所羅門」意思是「平安」。"]},{"n":10,"t":"他必為我的名建造殿宇。他要作我的子，我要作他的父。我必堅定他國度的王位，使他治理以色列，直到永遠。』","notes":[]},{"n":11,"t":"我兒啊，現今願耶和華與你同在，使你亨通，建造耶和華－你神的殿，正如他指著你所說的。","notes":[]},{"n":12,"t":"但願耶和華賜你聰明智慧，好按著他吩咐你的去治理以色列，遵行耶和華－你神的律法。","notes":[]},{"n":13,"t":"那時候，你若謹守遵行耶和華藉摩西吩咐以色列的律例典章，就得亨通。你當剛強壯膽，不要懼怕，也不要驚惶。","notes":[]},{"n":14,"t":"看哪，我辛苦地為耶和華的殿預備了十萬他連得金子，一百萬他連得銀子，銅和鐵多得無法可秤；我也預備了木頭、石頭，你還可以增添。","notes":[]},{"n":15,"t":"你有許多工匠，就是石匠、木匠，和一切能做各樣工的巧匠，","notes":[]},{"n":16,"t":"以及無數的金銀銅鐵。你當起來做工，願耶和華與你同在。」","notes":[]},{"n":17,"t":"大衛又吩咐以色列的眾官長幫助他兒子所羅門：","notes":[]},{"n":18,"t":"「耶和華－你們的神不是與你們同在嗎？他不是使你們四圍都平安嗎？因他已將這地的居民交在我手中，這地已在耶和華與他百姓面前制伏了。","notes":[]},{"n":19,"t":"現在你們應當立定心意，尋求耶和華－你們的神。你們當起來建造耶和華神的聖所，好將耶和華的約櫃和神神聖的器皿都搬進為耶和華的名建造的殿裏。」","notes":[]}]},"23":{"heading":"利未人的職務","verses":[{"n":1,"t":"大衛年紀老邁，日子滿足，就立他兒子所羅門作以色列的王。","notes":[]},{"n":2,"t":"大衛召集以色列的眾領袖、祭司和利未人。","notes":[]},{"n":3,"t":"利未人三十歲以上的都被數點，他們男丁的數目共有三萬八千；","notes":[]},{"n":4,"t":"其中有二萬四千人管理耶和華殿的事務，有六千人作官長和審判官，","notes":[]},{"n":5,"t":"有四千人作門口的守衛，又有四千人頌讚耶和華，用大衛造的樂器來頌讚。","notes":["「大衛」：原文是「我」。"]},{"n":6,"t":"大衛把利未人革順、哥轄、米拉利的子孫分了班次。","notes":[]},{"n":7,"t":"屬革順的有拉但和示每。","notes":[]},{"n":8,"t":"拉但的長子是耶歇，還有西坦和約珥，共三人。","notes":[]},{"n":9,"t":"示每的兒子是示羅密、哈薛、哈蘭三人。這是拉但族的族長。","notes":[]},{"n":10,"t":"示每的兒子是雅哈、細拿、耶烏施、比利亞，這四人是示每的兒子。","notes":["「細拿」:有古卷、七十士譯本和其他古譯本是「細撒」。"]},{"n":11,"t":"雅哈是長子，細撒是次子。但耶烏施和比利亞的子孫不多，所以算為一族。","notes":[]},{"n":12,"t":"哥轄的兒子是暗蘭、以斯哈、希伯倫、烏薛，共四人。","notes":[]},{"n":13,"t":"暗蘭的兒子是亞倫和摩西。亞倫被分別出來，把至聖之物分別為聖，使他和他的子孫在耶和華面前燒香、事奉他，奉他的名祝福，直到永遠。","notes":[]},{"n":14,"t":"至於神人摩西，他的子孫記名在利未支派下。","notes":[]},{"n":15,"t":"摩西的兒子是革舜和以利以謝。","notes":[]},{"n":16,"t":"革舜的兒子，長子是細布業；","notes":[]},{"n":17,"t":"以利以謝的兒子，長子是利哈比雅。以利以謝沒有別的兒子，但利哈比雅的子孫很多。","notes":[]},{"n":18,"t":"以斯哈的兒子，長子是示羅密。","notes":[]},{"n":19,"t":"希伯倫的兒子，長子是耶利雅，次子是亞瑪利亞，三子是雅哈悉，四子是耶加面。","notes":[]},{"n":20,"t":"烏薛的兒子，長子是米迦，次子是耶西雅。","notes":[]},{"n":21,"t":"米拉利的兒子是抹利和母示。抹利的兒子是以利亞撒和基士。","notes":[]},{"n":22,"t":"以利亞撒死了，沒有兒子，只有女兒，他們本族基士的幾個兒子娶了她們為妻。","notes":[]},{"n":23,"t":"母示的兒子是末力、以得、耶利末，共三人。","notes":[]},{"n":24,"t":"以上是利未子孫作族長的，按著父系、照著男丁的數目，二十歲以上登記的，都辦理耶和華殿的事務。","notes":[]},{"n":25,"t":"大衛說：「耶和華－以色列的神已經使他的百姓得享安寧，他永遠住在耶路撒冷。","notes":[]},{"n":26,"t":"因此，利未人不必再抬帳幕和其中所使用的一切器皿了。」","notes":[]},{"n":27,"t":"照著大衛臨終的話，利未人二十歲以上的都被數點。","notes":[]},{"n":28,"t":"他們的職務是作亞倫子孫的幫手，在耶和華的殿事奉，照管院子和屋子，潔淨一切聖物，辦理神殿的事務。","notes":[]},{"n":29,"t":"他們負責預備供餅、素祭的細麵和無酵薄餅，或用盤烤，或用油調和的祭物，確認其數量和大小。","notes":[]},{"n":30,"t":"每日早晚、安息日、初一，以及節期，按數照例，經常獻燔祭給耶和華的時候，他們站立稱謝讚美耶和華。","notes":[],"end":31},{"n":32,"t":"他們照管會幕和聖所，服事他們的弟兄亞倫的子孫，辦理耶和華殿的事務。","notes":[]}]},"24":{"heading":"祭司的職務","verses":[{"n":1,"t":"亞倫子孫的班次如下：亞倫的兒子是拿答、亞比戶、以利亞撒、以他瑪。","notes":[]},{"n":2,"t":"拿答和亞比戶死在他們父親之先，沒有留下兒子；因此，以利亞撒和以他瑪擔任祭司的職分。","notes":[]},{"n":3,"t":"大衛和以利亞撒的子孫撒督，以及以他瑪的子孫亞希米勒，把他們按照任務分成班次，","notes":[]},{"n":4,"t":"發現以利亞撒子孫中作領袖的，比以他瑪子孫中作領袖的更多，就分班如下：以利亞撒的子孫中有十六個族長，以他瑪的子孫中有八個族長。","notes":[]},{"n":5,"t":"他們抽籤分配，彼此一樣。在聖所和神面前作領袖的有以利亞撒的子孫，也有以他瑪的子孫。","notes":[]},{"n":6,"t":"作書記的利未人拿坦業的兒子示瑪雅在王和領袖，與撒督祭司、亞比亞他的兒子亞希米勒，以及祭司和利未人的族長面前記錄他們的名字；在以利亞撒的子孫中取一族，在以他瑪的子孫中也取一族。","notes":[]},{"n":7,"t":"抽籤的時候，第一籤抽到的是耶何雅立，第二是耶大雅，","notes":[]},{"n":8,"t":"第三是哈琳，第四是梭琳，","notes":[]},{"n":9,"t":"第五是瑪基雅，第六是米雅民，","notes":[]},{"n":10,"t":"第七是哈歌斯，第八是亞比雅，","notes":[]},{"n":11,"t":"第九是耶書亞，第十是示迦尼，","notes":[]},{"n":12,"t":"第十一是以利亞實，第十二是雅金，","notes":[]},{"n":13,"t":"第十三是胡巴，第十四是耶是比押，","notes":[]},{"n":14,"t":"第十五是璧迦，第十六是音麥，","notes":[]},{"n":15,"t":"第十七是希悉，第十八是哈闢悉，","notes":[]},{"n":16,"t":"第十九是毗他希雅，第二十是以西結，","notes":[]},{"n":17,"t":"第二十一是雅斤，第二十二是迦末，","notes":[]},{"n":18,"t":"第二十三是第來雅，第二十四是瑪西亞。","notes":[]},{"n":19,"t":"這就是他們事奉的班次，要照耶和華－以色列的神藉他們祖宗亞倫所吩咐的條例，進入耶和華的殿辦理事務。","notes":[]},{"n":20,"t":"利未其餘的子孫如下：暗蘭的子孫中有書巴業；書巴業的子孫中有耶希底亞。","notes":[],"heads":["利未人名單"]},{"n":21,"t":"屬利哈比雅，利哈比雅的兒子中有長子伊示雅。","notes":[]},{"n":22,"t":"屬以斯哈人的有示羅摩；示羅摩的子孫中有雅哈。","notes":[]},{"n":23,"t":"希伯倫的兒子中有長子耶利雅，次子亞瑪利亞，三子雅哈悉，四子耶加面。","notes":["「希伯倫...耶利雅」：原文是「我的兒子中有耶利雅」，有古卷是「耶利雅的兒子」；參代上23．19。"]},{"n":24,"t":"烏薛的子孫中有米迦；米迦的子孫中有沙密。","notes":[]},{"n":25,"t":"米迦的兄弟是伊示雅；伊示雅的子孫中有撒迦利雅。","notes":[]},{"n":26,"t":"米拉利的兒子是抹利和母示；雅西雅的子孫中有比挪；","notes":[]},{"n":27,"t":"米拉利的子孫中有屬雅西雅的比挪、朔含、撒刻、伊比利。","notes":[]},{"n":28,"t":"屬抹利的有以利亞撒；以利亞撒沒有兒子。","notes":[]},{"n":29,"t":"屬基士，基士的子孫中有耶拉篾。","notes":[]},{"n":30,"t":"母示的兒子是末力、以得、耶利末。按著宗族，這些都是利未的子孫。","notes":[]},{"n":31,"t":"他們在大衛王和撒督，以及亞希米勒與祭司和利未人的族長面前也抽籤，正如他們弟兄亞倫的子孫一樣。各族的族長與最年輕的兄弟都一樣。","notes":[]}]},"25":{"heading":"聖殿中的聖樂人員","verses":[{"n":1,"t":"大衛和事奉團隊的眾領袖分派亞薩、希幔，以及耶杜頓的子孫唱歌，以彈琴、鼓瑟、敲鈸伴奏。他們供職的人數如下：","notes":["「唱歌」：原文是「說預言」；下同。"]},{"n":2,"t":"亞薩的兒子撒刻、約瑟、尼探雅、亞薩利拉，亞薩的兒子都在亞薩的指導下，遵王的指示唱歌。","notes":[]},{"n":3,"t":"屬耶杜頓，耶杜頓的兒子基大利、西利、耶篩亞、示每、哈沙比雅、瑪他提雅共六人，都在他們父親耶杜頓的指導下唱歌，以彈琴伴奏，稱謝，頌讚耶和華。","notes":["「示每」是根據一些古卷和七十士譯本的一些抄本；原文沒有。"]},{"n":4,"t":"屬希幔，希幔的兒子是布基雅、瑪探雅、烏薛、細布業、耶利末、哈拿尼雅、哈拿尼、以利亞他、基大利提、羅幔提‧以謝、約施比加沙、瑪羅提、何提、瑪哈秀。","notes":[]},{"n":5,"t":"這些都是希幔的兒子；希幔奉神之命作王的先見，吹角頌讚。神賜給希幔十四個兒子，三個女兒，","notes":[]},{"n":6,"t":"他們都在父親的指導下，在耶和華的殿唱歌，以敲鈸、彈琴、鼓瑟伴奏，遵從王的指示，在神的殿裏事奉。亞薩、耶杜頓、希幔，","notes":[]},{"n":7,"t":"他們和他們的弟兄學習頌讚耶和華，精通者的數目共有二百八十八人。","notes":[]},{"n":8,"t":"這些人無論大小，為師的、為徒的，都一同抽籤分了班次。","notes":[]},{"n":9,"t":"抽籤的時候，第一籤抽到的是亞薩的兒子約瑟。第二是基大利；他和他兄弟，以及兒子共十二人。","notes":[]},{"n":10,"t":"第三是撒刻，他兒子和他兄弟共十二人。","notes":[]},{"n":11,"t":"第四是伊洗利，他兒子和他兄弟共十二人。","notes":[]},{"n":12,"t":"第五是尼探雅，他兒子和他兄弟共十二人。","notes":[]},{"n":13,"t":"第六是布基雅，他兒子和他兄弟共十二人。","notes":[]},{"n":14,"t":"第七是耶薩利拉，他兒子和他兄弟共十二人。","notes":[]},{"n":15,"t":"第八是耶篩亞，他兒子和他兄弟共十二人。","notes":[]},{"n":16,"t":"第九是瑪探雅，他兒子和他兄弟共十二人。","notes":[]},{"n":17,"t":"第十是示每，他兒子和他兄弟共十二人。","notes":[]},{"n":18,"t":"第十一是亞薩烈，他兒子和他兄弟共十二人。","notes":[]},{"n":19,"t":"第十二是哈沙比雅，他兒子和他兄弟共十二人。","notes":[]},{"n":20,"t":"第十三是書巴業，他兒子和他兄弟共十二人。","notes":[]},{"n":21,"t":"第十四是瑪他提雅，他兒子和他兄弟共十二人。","notes":[]},{"n":22,"t":"第十五是耶利末，他兒子和他兄弟共十二人。","notes":[]},{"n":23,"t":"第十六是哈拿尼雅，他兒子和他兄弟共十二人。","notes":[]},{"n":24,"t":"第十七是約施比加沙，他兒子和他兄弟共十二人。","notes":[]},{"n":25,"t":"第十八是哈拿尼，他兒子和他兄弟共十二人。","notes":[]},{"n":26,"t":"第十九是瑪羅提，他兒子和他兄弟共十二人。","notes":[]},{"n":27,"t":"第二十是以利亞他，他兒子和他兄弟共十二人。","notes":[]},{"n":28,"t":"第二十一是何提，他兒子和他兄弟共十二人。","notes":[]},{"n":29,"t":"第二十二是基大利提，他兒子和他兄弟共十二人。","notes":[]},{"n":30,"t":"第二十三是瑪哈秀，他兒子和他兄弟共十二人。","notes":[]},{"n":31,"t":"第二十四是羅幔提‧以謝，他兒子和他兄弟共十二人。","notes":[]}]},"26":{"heading":"聖殿的守衛","verses":[{"n":1,"t":"門口守衛的班次如下：可拉族以比雅撒的子孫中，有可利的兒子米施利米雅。","notes":["「以比雅撒」是根據七十士譯本，原文是「亞薩」；參代上9．19。"]},{"n":2,"t":"米施利米雅的長子是撒迦利亞，次子是耶疊，三子是西巴第雅，四子是耶提聶，","notes":[]},{"n":3,"t":"五子是以攔，六子是約哈難，七子是以利約乃。","notes":[]},{"n":4,"t":"俄別‧以東的長子是示瑪雅，次子是約薩拔，三子是約亞，四子是沙甲，五子是拿坦業，","notes":[]},{"n":5,"t":"六子是亞米利，七子是以薩迦，八子是毗烏利太，因為神賜福給俄別‧以東。","notes":[]},{"n":6,"t":"他的兒子示瑪雅生了幾個兒子，都是大能的勇士，管理父親的家。","notes":[]},{"n":7,"t":"示瑪雅的兒子是俄得尼、利法益、俄備得、以利薩巴。以利薩巴的兄弟以利戶和西瑪迦是能人。","notes":[]},{"n":8,"t":"這些都是俄別‧以東的子孫，他們和他們的兒子，以及兄弟，都是善於辦事的能人。屬俄別‧以東的共六十二人。","notes":[]},{"n":9,"t":"米施利米雅的兒子和兄弟都是能人，共十八人。","notes":[]},{"n":10,"t":"米拉利子孫中的何薩有幾個兒子：為首的是申利；他原不是長子，是他父親立他為首的，","notes":[]},{"n":11,"t":"次子是希勒家，三子是底巴利雅，四子是撒迦利亞。何薩的兒子和兄弟共十三人。","notes":[]},{"n":12,"t":"這些是門口守衛的班次，各隨他們的班長，與他們的兄弟一同在耶和華殿裏按班供職。","notes":[]},{"n":13,"t":"他們無論大小，都按著父系抽籤，分守各門。","notes":[]},{"n":14,"t":"抽到東門的是示利米雅；他的兒子撒迦利亞是精明的謀士，抽到北門。","notes":[]},{"n":15,"t":"俄別‧以東守南門，他的兒子守倉庫。","notes":[]},{"n":16,"t":"書聘與何薩守西門，在靠近沙利基門、通往上去的街道上，守衛與守衛相對。","notes":[]},{"n":17,"t":"東門有六個利未人，北門每日有四人，南門每日有四人，庫房有兩人輪流替換。","notes":["「東門有六個利未人」：七十士譯本是「東門每日有六人」。"]},{"n":18,"t":"至於走廊，在西面街道上有四人，在走廊上有兩人。","notes":[]},{"n":19,"t":"以上是可拉子孫和米拉利子孫門口守衛的班次。","notes":[]},{"n":20,"t":"利未人中有亞希雅管理神殿的庫房和聖物的庫房。","notes":["「亞希雅」：七十士譯本是「他們的弟兄」。"],"heads":["其他職務"]},{"n":21,"t":"拉但子孫中，革順族屬拉但、作族長的是革順族屬拉但的耶希伊利。","notes":[]},{"n":22,"t":"耶希伊利的兒子西坦和他兄弟約珥管理耶和華殿的庫房。","notes":[]},{"n":23,"t":"暗蘭人、以斯哈人、希伯倫人、烏薛人也有職務。","notes":[]},{"n":24,"t":"摩西的孫子，革舜的兒子細布業管理庫房。","notes":[]},{"n":25,"t":"還有他的弟兄：以利以謝，以利以謝的兒子利哈比雅，利哈比雅的兒子耶篩亞，耶篩亞的兒子約蘭，約蘭的兒子細基利，細基利的兒子示羅密。","notes":[]},{"n":26,"t":"這示羅密和他的兄弟管理一切庫房的聖物，就是大衛王和眾族長、千夫長、百夫長，以及軍官所分別為聖之物。","notes":[]},{"n":27,"t":"他們把打仗時奪取的一些財物分別為聖，用來修造耶和華的殿。","notes":[]},{"n":28,"t":"凡撒母耳先見、基士的兒子掃羅、尼珥的兒子押尼珥、洗魯雅的兒子約押分別為聖的，一切分別為聖之物都歸示羅密和他的兄弟掌管。","notes":[]},{"n":29,"t":"以斯哈人有基拿尼雅和他眾兒子作官長和審判官，管理以色列對外的事務。","notes":[],"heads":["其餘利未人的職務"]},{"n":30,"t":"希伯倫人有哈沙比雅和他弟兄一千七百人，都是能人，在約旦河西監督以色列人，辦理耶和華的一切工作和王的事務。","notes":[]},{"n":31,"t":"希伯倫人中有耶利雅作族長。大衛作王第四十年在各族各家從事尋訪，在基列的雅謝，從這族中發現大能的勇士。","notes":[]},{"n":32,"t":"耶利雅的弟兄有二千七百人，都是能人，又是族長；大衛王派他們在呂便人、迦得人、瑪拿西半支派中管理神和王的一切事務。","notes":[]}]},"27":{"heading":"軍官的名單","verses":[{"n":1,"t":"以色列人的族長、千夫長、百夫長和官長都分配班次，每班二萬四千人，整年按月輪流出入，按班次服事王。","notes":[]},{"n":2,"t":"正月第一班的班長是撒巴第業的兒子雅朔班；他班內有二萬四千人。","notes":[]},{"n":3,"t":"他是法勒斯的後裔，統管正月軍隊所有的官長。","notes":[]},{"n":4,"t":"二月的班長是亞何亞人朵代，他的班有總長密基羅；他班內有二萬四千人。","notes":[]},{"n":5,"t":"三月第三班的班長是耶何耶大祭司長的兒子比拿雅；他班內有二萬四千人。","notes":[]},{"n":6,"t":"這比拿雅是那三十人中的勇士，管理那三十人；他班內又有他兒子暗米薩拔。","notes":["「他班內又有他兒子暗米薩拔」：七十士譯本和其他古譯本是「他兒子暗米薩拔管理他的班」。"]},{"n":7,"t":"四月第四班的班長是約押的兄弟亞撒黑。接續他的是他兒子西巴第雅；他班內有二萬四千人。","notes":[]},{"n":8,"t":"五月第五班的班長是伊斯拉人珊合；他班內有二萬四千人。","notes":[]},{"n":9,"t":"六月第六班的班長是提哥亞人益吉的兒子以拉；他班內有二萬四千人。","notes":[]},{"n":10,"t":"七月第七班的班長是以法蓮族比倫人希利斯；他班內有二萬四千人。","notes":[]},{"n":11,"t":"八月第八班的班長是謝拉族戶沙人西比該；他班內有二萬四千人。","notes":[]},{"n":12,"t":"九月第九班的班長是便雅憫族亞拿突人亞比以謝；他班內有二萬四千人。","notes":[]},{"n":13,"t":"十月第十班的班長是謝拉族尼陀法人瑪哈萊；他班內有二萬四千人。","notes":[]},{"n":14,"t":"十一月第十一班的班長是以法蓮族比拉頓人比拿雅；他班內有二萬四千人。","notes":[]},{"n":15,"t":"十二月第十二班的班長是俄陀聶族尼陀法人黑玳；他班內有二萬四千人。","notes":[]},{"n":16,"t":"管理以色列眾支派的如下：管呂便人的是細基利的兒子以利以謝；管西緬人的是瑪迦的兒子示法提雅；","notes":[],"heads":["以色列各支派的行政長官"]},{"n":17,"t":"管利未的是基摩利的兒子哈沙比雅；管亞倫子孫的是撒督；","notes":[]},{"n":18,"t":"管猶大的是大衛的一個哥哥以利戶；管以薩迦的是米迦勒的兒子暗利；","notes":[]},{"n":19,"t":"管西布倫的是俄巴第雅的兒子伊施瑪雅；管拿弗他利的是亞斯列的兒子耶利摩；","notes":[]},{"n":20,"t":"管以法蓮的是阿撒細雅的兒子何細亞；管瑪拿西半支派的是毗大雅的兒子約珥；","notes":[]},{"n":21,"t":"管基列地瑪拿西半支派的是撒迦利亞的兒子易多；管便雅憫的是押尼珥的兒子雅西業；","notes":[]},{"n":22,"t":"管但的是耶羅罕的兒子亞薩列。以上是以色列眾支派的領袖。","notes":[]},{"n":23,"t":"以色列人二十歲以下的，大衛沒有記其數目；因耶和華曾應許，必加增以色列人如天上的星那樣多。","notes":[]},{"n":24,"t":"洗魯雅的兒子約押開始數點，卻還沒有數完。為了這事，烈怒臨到以色列，數點的數目也沒有寫在《大衛王記》上。","notes":[]},{"n":25,"t":"管理王的庫房的是亞疊的兒子押斯馬威。管理田野、城鎮、村莊、堡壘之倉庫的是烏西雅的兒子約拿單。","notes":[],"heads":["管理王產的官員"]},{"n":26,"t":"管理耕田種地的是基綠的兒子以斯利。","notes":[]},{"n":27,"t":"管理葡萄園的是拉瑪人示每。管理葡萄園酒窖的是實弗米人撒巴底。","notes":[]},{"n":28,"t":"管理謝非拉橄欖樹和桑樹的是基第利人巴勒‧哈南。管理油庫的是約阿施。","notes":["「謝非拉」是音譯，意思是「低地」。"]},{"n":29,"t":"管理沙崙牧放牛群的是沙崙人施提萊。管理山谷牧養牛群的是亞第萊的兒子沙法。","notes":[]},{"n":30,"t":"管理駱駝群的是以實瑪利人阿比勒。管理驢群的是米崙人耶希底亞。管理羊群的是夏甲人雅悉。","notes":[]},{"n":31,"t":"這些都是為大衛王管理產業的領袖。","notes":[]},{"n":32,"t":"大衛的叔父約拿單作謀士；這人有智慧，又作書記。哈摩尼的兒子耶歇陪伴王的眾兒子。","notes":[],"heads":["大衛的謀士"]},{"n":33,"t":"亞希多弗作王的謀士。亞基人戶篩作王的顧問。","notes":[]},{"n":34,"t":"亞希多弗之後，有比拿雅的兒子耶何耶大，以及亞比亞他接續他。約押作王的元帥。","notes":[]}]},"28":{"heading":"大衛對建殿的指示","verses":[{"n":1,"t":"大衛召集以色列所有的領袖，各支派的領袖、輪班服事王的官長、千夫長、百夫長、掌管王和王子一切產業牲畜的、宮廷官員、勇士，和所有大能的勇士，都到耶路撒冷來。","notes":[]},{"n":2,"t":"大衛王站起來，說：「我的弟兄，我的百姓啊，請聽我說！我心裏本想建造殿宇，安放耶和華的約櫃，作為我們神的腳凳，並且我已經預備了建造的材料。","notes":[]},{"n":3,"t":"只是神對我說：『你不可為我的名建造殿宇，因你是戰士，流了人的血。』","notes":[]},{"n":4,"t":"然而，耶和華－以色列的神在我父的全家揀選我作以色列的王，直到永遠。因他揀選猶大為領袖，在猶大家中揀選我父家，在我父的眾兒子裏喜悅我，立我作全以色列的王。","notes":[]},{"n":5,"t":"耶和華賜我許多兒子，在我兒子中揀選我兒子所羅門坐耶和華國度的王位，治理以色列。","notes":[]},{"n":6,"t":"耶和華對我說：『你兒子所羅門必建造我的殿和院宇，因為我揀選他作我的子，我也必作他的父。","notes":[]},{"n":7,"t":"他若恆久遵行我的誡命典章如今日一樣，我就必堅定他的國，直到永遠。』","notes":[]},{"n":8,"t":"現今在以色列眾人眼前，在耶和華的會中，在我們神的垂聽下，你們務要遵行並尋求耶和華－你們神的一切誡命，如此你們就可以承受這美地，並留給你們的子孫，永遠為業。","notes":[]},{"n":9,"t":"「我兒所羅門哪，你當認識耶和華－你父的神，全心樂意地事奉他，因為耶和華鑒察眾人的心，知道一切心思意念。你若尋求他，他必使你尋見；你若離棄他，他必永遠丟棄你。","notes":[]},{"n":10,"t":"現在你當謹慎，因耶和華揀選你建造殿宇作為聖所。你當剛強去做。」","notes":[]},{"n":11,"t":"大衛指示他兒子所羅門有關殿的走廊、屋子、庫房、樓房、內殿和櫃蓋之處的樣式，","notes":["「櫃蓋」：原意「蓋住」，指「蓋住罪」，後來也稱為「施恩座」。"]},{"n":12,"t":"被靈感動所得的一切樣式：耶和華殿的院子、周圍一切的房屋、神殿的庫房和聖物庫房；","notes":[]},{"n":13,"t":"祭司和利未人的班次，耶和華殿裏各樣事奉的工作，耶和華殿裏一切事奉用的器皿，","notes":[]},{"n":14,"t":"以及各樣事奉所用金器的重量，和各樣事奉所用銀器的重量，","notes":[]},{"n":15,"t":"金燈臺和金燈的重量，按每一個燈臺和燈的重量；銀燈臺和銀燈的重量，按每一個燈臺和燈的重量，都按照每一個燈臺的用途；","notes":[]},{"n":16,"t":"每張供餅桌子的金子重量，和銀桌子的銀子重量，","notes":[]},{"n":17,"t":"純金的肉叉子、盤子，和壺的重量，金碗，按每個金碗的重量，和銀碗，按每個銀碗的重量，","notes":[]},{"n":18,"t":"純金香壇的重量，金基路伯座車的樣式，基路伯張開翅膀，遮蓋耶和華的約櫃。","notes":[]},{"n":19,"t":"大衛說：「這一切，所有工作的樣式，是耶和華用手寫的文件使我明白的。」","notes":[]},{"n":20,"t":"大衛又對他兒子所羅門說：「你當剛強壯膽去做！不要懼怕，也不要驚惶，因為耶和華神，我的神與你同在。他必不撇下你，也不丟棄你，直到耶和華殿的工作都完畢。","notes":[]},{"n":21,"t":"看哪，有祭司和利未人的班次，為要辦理神殿各樣的事務，又有擅長做各樣事務的人，樂意在各樣工作上幫助你，並且領袖和眾百姓也都聽從你的一切命令。」","notes":[]}]},"29":{"heading":"為建殿而獻的禮物","verses":[{"n":1,"t":"大衛王對全會眾說：「我兒子所羅門是神特選的，還年幼脆弱，但這工程浩大，因這殿不是為人，而是為耶和華神建造的。","notes":[]},{"n":2,"t":"我為我神的殿已經盡力，預備金子做金器，銀子做銀器，銅做銅器，鐵做鐵器，木做木器，還有紅瑪瑙、可鑲嵌的寶石、彩石、各樣的寶石和許多大理石。","notes":[]},{"n":3,"t":"此外，因我愛慕我神的殿，在預備建造聖殿的一切材料之外，又將我自己積蓄的金銀獻給我神的殿，","notes":[]},{"n":4,"t":"就是三千他連得俄斐金子、七千他連得純銀，用來貼殿的牆；","notes":[]},{"n":5,"t":"金子做金器，銀子做銀器，並藉工匠的手做一切的工。今日有誰願意將自己獻給耶和華呢？」","notes":[]},{"n":6,"t":"於是，眾族長和以色列各支派的領袖、千夫長、百夫長，以及監管王工作的官長，都樂意奉獻。","notes":[]},{"n":7,"t":"他們為神殿的工程獻上五千他連得又一萬達利克金子，一萬他連得銀子，一萬八千他連得銅，十萬他連得鐵。","notes":["「達利克」﹕古波斯金幣；參「度量衡表」。"]},{"n":8,"t":"凡有寶石的都送入耶和華殿的庫房，由革順人耶歇的手管理。","notes":[]},{"n":9,"t":"因這些人全心樂意獻給耶和華，百姓就歡喜，大衛王也大大歡喜。","notes":[]},{"n":10,"t":"大衛在全會眾眼前稱頌耶和華；大衛說：「耶和華－以色列的神，我們的父，你是應當稱頌的，直到永永遠遠！","notes":[],"heads":["大衛稱頌耶和華"]},{"n":11,"t":"耶和華啊，尊大、能力、榮耀、勝利、威嚴都是你的；天上地下的一切都是你的；耶和華啊，國度是你的，並且你為至高，為萬有之首。","notes":[]},{"n":12,"t":"豐富尊榮都從你而來，你也治理萬物。在你手裏有大能大力，你的手使人尊大強盛。","notes":[]},{"n":13,"t":"我們的神啊，現在我們稱謝你，讚美你榮耀之名！","notes":[]},{"n":14,"t":"「我算甚麼，我的百姓算甚麼，竟然能夠如此樂意奉獻？因為萬物都從你而來，我們把從你的手得來的獻給你。","notes":[]},{"n":15,"t":"我們在你面前是客旅，是寄居的，與我們的列祖一樣。我們在世的日子如影子，沒有盼望。","notes":[]},{"n":16,"t":"耶和華－我們的神啊，我們預備這許多材料，要為你的聖名建造殿宇，都是從你的手而來，都是屬你的。","notes":[]},{"n":17,"t":"我的神啊，我知道你察驗人心，喜悅正直；我以正直的心樂意獻上這一切。現在我歡喜見你的百姓在此樂意奉獻給你。","notes":[]},{"n":18,"t":"耶和華－我們列祖亞伯拉罕、以撒、以色列的神啊，求你使你的百姓心中常存這樣的心思意念，堅定他們的心歸向你，","notes":[]},{"n":19,"t":"又求你賜我兒子所羅門全心遵守你的命令、法度、律例，成就這一切的事，用我所預備的建造殿宇。」","notes":[]},{"n":20,"t":"大衛對全會眾說：「你們應當稱頌耶和華－你們的神。」於是全會眾稱頌耶和華－他們列祖的神，低頭向耶和華和王下拜。","notes":[]},{"n":21,"t":"次日，他們向耶和華獻平安祭和燔祭，獻一千頭公牛、一千隻公綿羊、一千隻羔羊，以及同獻的澆酒祭，並為以色列眾人獻許多的祭。","notes":[]},{"n":22,"t":"那日，他們在耶和華面前吃喝，大大歡樂。他們再次立大衛的兒子所羅門作王，膏他歸耶和華作君王，又膏撒督作祭司。","notes":[]},{"n":23,"t":"於是所羅門坐在耶和華所賜的王位上，接續他父親大衛作王；他萬事亨通，全以色列都聽從他。","notes":[]},{"n":24,"t":"眾領袖和勇士，以及大衛王的眾兒子，都順服所羅門王。","notes":[]},{"n":25,"t":"耶和華使所羅門在以色列眾人眼前非常尊大，賜他君王的威嚴，勝過他以前任何一位以色列王。","notes":[]},{"n":26,"t":"耶西的兒子大衛作全以色列的王。","notes":[],"heads":["大衛政績簡述"]},{"n":27,"t":"他作以色列王的時期共四十年：在希伯崙作王七年，在耶路撒冷作王三十三年。","notes":[]},{"n":28,"t":"他死的時候年紀老邁，日子滿足，享盡榮華富貴。他的兒子所羅門接續他作王。","notes":[]},{"n":29,"t":"大衛王自始至終的事蹟，看哪，都寫在撒母耳先見的書上、拿單先知的書上和迦得先見的書上，","notes":[]},{"n":30,"t":"包括他治國的一切和他英勇的事蹟，以及他和以色列與世上列國所經歷的事。","notes":[]}]}},"2CH":{"1":{"heading":"所羅門祈求智慧","verses":[{"n":1,"t":"大衛的兒子所羅門鞏固他的國度；耶和華－他的神與他同在，使他極其尊大。","notes":[]},{"n":2,"t":"所羅門吩咐全以色列，就是千夫長、百夫長、審判官、全以色列的眾領袖和族長前來。","notes":[]},{"n":3,"t":"所羅門率領全會眾往基遍的丘壇去，因那裏有神的會幕，就是耶和華的僕人摩西在曠野所造的。","notes":[]},{"n":4,"t":"只是神的約櫃，大衛已經從基列‧耶琳接到他所預備的地方，因他曾在耶路撒冷為約櫃支搭了帳幕，","notes":[]},{"n":5,"t":"把戶珥的孫子，烏利的兒子比撒列所造的銅壇擺在基遍耶和華的會幕前。所羅門和會眾求告耶和華。","notes":["「把戶珥...擺在基遍」：有古卷、七十士譯本和其他古譯本是「戶珥的孫子，烏利亞的兒子比撒列所造的銅壇在基遍那裏」。"]},{"n":6,"t":"所羅門上到耶和華面前會幕的銅壇那裏，在壇上獻一千祭牲為燔祭。","notes":[]},{"n":7,"t":"當夜，神向所羅門顯現，對他說：「你願我賜你甚麼，你可以求。」","notes":[]},{"n":8,"t":"所羅門對神說：「你曾向我父親大衛大施慈愛，使我接續他作王。","notes":[]},{"n":9,"t":"耶和華神啊，現在求你實現向我父親大衛所應許的話；因你立我作這百姓的王，他們如同地上的塵沙那樣多。","notes":[]},{"n":10,"t":"現在，求你賜我智慧聰明，好在這百姓面前出入；不然，誰能判斷你這麼多的百姓呢？」","notes":[]},{"n":11,"t":"神對所羅門說：「你有這心意，不求資財、豐富、尊榮，也不求滅絕恨你之人的性命，又不求長壽；我既立你作我百姓的王，你只求智慧聰明，好審判我的百姓，","notes":[]},{"n":12,"t":"我必賜你智慧聰明，也必賜你資財、豐富、尊榮，在你以前的列王未曾有過，在你以後也不會再有。」","notes":[]},{"n":13,"t":"於是，所羅門從基遍丘壇會幕前回到耶路撒冷，治理以色列。","notes":[]},{"n":14,"t":"所羅門聚集戰車騎兵；他有一千四百輛戰車，一萬二千名騎兵，安置在屯車城，在耶路撒冷的王那裏。","notes":[],"heads":["所羅門的兵力和財力"]},{"n":15,"t":"王在耶路撒冷使金銀多如石頭，香柏木多如謝非拉的桑樹。","notes":["「謝非拉」是音譯，意思是「低地」；本卷書下同。"]},{"n":16,"t":"所羅門的馬是從埃及和科威運來的，是王的商人按著定價從科威買來的。","notes":["「埃及」可能不是南方的埃及，而是美索不達米亞北方的一國；下同。","「科威」可能是「基利家」。"]},{"n":17,"t":"他們從埃及進口戰車，每輛六百舍客勒銀子，馬每匹一百五十舍客勒；赫人眾王和亞蘭諸王的戰車和馬，也是經由他們的手出口的。","notes":[]}]},"2":{"heading":"所羅門準備建殿","verses":[{"n":1,"t":"所羅門吩咐要為耶和華的名建造殿宇，又為自己的王國建造宮殿。","notes":[]},{"n":2,"t":"所羅門徵召七萬名扛抬的，八萬個在山上鑿石頭的人，三千六百個監工。","notes":[]},{"n":3,"t":"所羅門派人去見推羅王希蘭，說：「你曾運香柏木給我父親大衛建造宮殿居住，請你也這樣待我。","notes":["「希蘭」：原文是「戶蘭」；下同。"]},{"n":4,"t":"看哪，我要為耶和華－我神的名建造殿宇，分別為聖獻給他，在他面前燒芬芳的香，經常獻供餅，每早晚、安息日、初一，以及耶和華－我們神所定的節期獻燔祭。這是以色列人永遠的定例。","notes":[]},{"n":5,"t":"我所要建造的殿宇宏大，因為我們的神至大，超乎眾神。","notes":[]},{"n":6,"t":"天和天上的天，尚且不足他居住，誰能為他建造殿宇呢？我是誰，能為他建造殿宇嗎？不過在他面前燒香而已！","notes":[]},{"n":7,"t":"現在請你派一個巧匠來，就是善用金、銀、銅、鐵，和紫色、朱紅色、藍色線做工，並精於雕刻之工的巧匠，與跟我一起在猶大和耶路撒冷、我父親大衛所預備的巧匠一同做工；","notes":[]},{"n":8,"t":"又請你從黎巴嫩運香柏木、松木、檀香木到我這裏來，因我知道你的僕人擅長砍伐黎巴嫩的樹木。看哪，我的僕人必幫助你的僕人，","notes":[]},{"n":9,"t":"好為我預備許多的木料，因我要建造的殿宇高大出奇。","notes":[]},{"n":10,"t":"看哪，我必給你僕人，就是砍伐樹木的伐木工，二萬歌珥壓碎的小麥，二萬歌珥大麥，二萬罷特酒，二萬罷特油。」","notes":["「二萬歌珥壓碎的小麥」：七十士譯本是「食物：二萬歌珥小麥」。"]},{"n":11,"t":"推羅王希蘭寫信回答所羅門說：「耶和華因為愛他的百姓，所以立你作他們的王。」","notes":[]},{"n":12,"t":"又說：「創造天和地的耶和華－以色列的神是應當稱頌的！他賜給大衛王一個有智慧的兒子，使他有見識，有聰明，可以為耶和華建造殿宇，又為自己的王國建造宮殿。","notes":[]},{"n":13,"t":"「現在我派一個精巧聰明的人去，他是我的師父戶蘭，","notes":[]},{"n":14,"t":"是但支派一個婦人的兒子，父親是推羅人。他善用金、銀、銅、鐵、石、木，和紫色、藍色、細麻和朱紅色線製造各物，並精於雕刻，又能設計各樣交給他做的圖案。我派這人與你的巧匠和你父親－我主大衛的巧匠一同做工。","notes":[]},{"n":15,"t":"我主所說的小麥、大麥、酒、油，請運來給眾僕人。","notes":[]},{"n":16,"t":"我們必照你所需用的，從黎巴嫩砍伐樹木，紮成筏子，浮海運到約帕；你可以從那裏運到耶路撒冷。」","notes":[]},{"n":17,"t":"所羅門仿照他父親大衛數點所有在以色列地寄居的外邦人，共有十五萬三千六百名。","notes":[]},{"n":18,"t":"他叫其中的七萬人作扛抬，八萬人在山上鑿石頭，三千六百人監督百姓工作。","notes":[]}]},"3":{"heading":"聖殿工程動工","verses":[{"n":1,"t":"所羅門在耶路撒冷開工建造耶和華的殿，就在耶和華向他父親大衛顯現的摩利亞山上，耶布斯人阿珥楠的禾場，大衛指定的地方。","notes":[]},{"n":2,"t":"所羅門作王第四年二月初二開工建造。","notes":["有古卷、七十士譯本和其他古譯本沒有「初二」；參王上6．1。"]},{"n":3,"t":"所羅門所建築的神殿的根基是這樣：長六十肘，寬二十肘，都按著古時的尺寸。","notes":[]},{"n":4,"t":"前面的走廊長二十肘，與殿的寬度一樣，高一百二十肘；裏面貼上純金。","notes":["「前面的」：七十士譯本是「殿前的」。"]},{"n":5,"t":"大殿的牆都用松木板遮蔽，又貼上純金，上面刻著棕樹和鏈子。","notes":[]},{"n":6,"t":"他用寶石裝飾這殿，使殿華美；金子都是巴瓦音的金子。","notes":[]},{"n":7,"t":"他用金子貼殿和殿的棟梁、門檻、牆壁、門扇；牆上刻著基路伯。","notes":[]},{"n":8,"t":"他建造至聖所，長二十肘，與殿的寬度一樣，寬二十肘，都貼上純金，共用了六百他連得金子。","notes":[]},{"n":9,"t":"金的釘子重五十舍客勒。樓房都貼上金子。","notes":[]},{"n":10,"t":"他又在至聖所用雕刻的手藝造兩個基路伯，包上金子。","notes":[]},{"n":11,"t":"兩個基路伯的翅膀共長二十肘。這基路伯的一個翅膀長五肘，挨著殿這邊的牆；另一個翅膀也長五肘，與那基路伯翅膀相接。","notes":[]},{"n":12,"t":"那基路伯的一個翅膀長五肘，挨著殿那邊的牆；另一個翅膀也長五肘，與這基路伯的翅膀相接。","notes":[]},{"n":13,"t":"這兩個基路伯張開翅膀，共長二十肘，用腳站立，臉面向殿。","notes":[]},{"n":14,"t":"他又用藍色、紫色、朱紅色線和細麻織幔子，在其上繡基路伯。","notes":[]},{"n":15,"t":"他在殿前造了兩根柱子，高三十五肘；柱子上面的柱頂高五肘。","notes":[],"heads":["兩根銅柱"]},{"n":16,"t":"他造鏈子在內殿裏，安在柱頂上，又做一百個石榴，安在鏈子上。","notes":[]},{"n":17,"t":"他把兩根柱子立在殿前，一根在右邊，一根在左邊；右邊的起名叫雅斤，左邊的起名叫波阿斯。","notes":[]}]},"4":{"heading":"聖殿的設備","verses":[{"n":1,"t":"他造一座銅壇，長二十肘，寬二十肘，高十肘。","notes":[]},{"n":2,"t":"他又鑄一個銅海，周圍是圓的，直徑十肘，高五肘，用繩子量周圍是三十肘。","notes":[]},{"n":3,"t":"銅海下面的周圍有牛的樣式，有十肘，繞著銅海；牛有兩行，是造銅海的時候鑄上去的。","notes":[]},{"n":4,"t":"銅海安在十二頭銅牛上：三頭向北，三頭向西，三頭向南，三頭向東。銅海安在牛上，牛尾都向內。","notes":[]},{"n":5,"t":"銅海厚一掌，邊如杯邊，像百合花，容量是三千罷特。","notes":[]},{"n":6,"t":"他又造十個盆：五個放在右邊，五個放在左邊，作洗滌之用。獻燔祭所用之物都洗在盆內；但銅海是為祭司洗滌用的。","notes":[]},{"n":7,"t":"他照所定的樣式造十個金燈臺，放在殿裏：五個在右邊，五個在左邊。","notes":[]},{"n":8,"t":"他造十張桌子，放在殿裏：五張在右邊，五張在左邊。他又造一百個金碗。","notes":[]},{"n":9,"t":"他建造祭司院和大院，以及院門，門扇包上銅。","notes":[]},{"n":10,"t":"他把銅海安在殿的右邊，就是東南邊。","notes":[]},{"n":11,"t":"戶蘭又造了盆、鏟子和盤子。這樣，戶蘭為所羅門王做完了神殿的工：","notes":[]},{"n":12,"t":"兩根柱子和柱子頂上兩個如碗的柱頂，以及蓋著如碗柱頂的兩個網子；","notes":[]},{"n":13,"t":"四百個石榴，安在兩個網子上，每網兩行石榴，蓋著柱子上面兩個如碗的柱頂。","notes":[]},{"n":14,"t":"他造盆座，又造其上的盆；","notes":[]},{"n":15,"t":"銅海和其下的十二頭牛；","notes":[]},{"n":16,"t":"盆、鏟子、肉叉。巧匠戶蘭給所羅門王為耶和華殿造的這一切器皿都是用磨亮的銅，","notes":[]},{"n":17,"t":"是王在約旦平原、疏割和撒利但中間的泥巴地鑄成的。","notes":[]},{"n":18,"t":"所羅門造這一切器皿，數量很多，銅的重量無法計算。","notes":[]},{"n":19,"t":"所羅門又為神的殿造了各樣的器皿：金壇和獻供餅的供桌；","notes":[]},{"n":20,"t":"純金的燈臺和燈盞，可以照定例點在內殿前；","notes":[]},{"n":21,"t":"燈臺上的花和燈盞，以及燈剪，都是金的，而且是純金的；","notes":[]},{"n":22,"t":"純金的鉗子、盤子、勺子、火盆。至於殿門和至聖所的門扇，以及殿的門扇，都是金的。","notes":[]}]},"5":{"heading":"接約櫃入殿","verses":[{"n":1,"t":"所羅門王做完了耶和華殿一切的工，就把他父親大衛分別為聖的金銀和一切器皿都帶來，放在神殿的庫房裏。","notes":[]},{"n":2,"t":"於是，所羅門召集以色列的長老、各支派的領袖和以色列人的族長到耶路撒冷，要把耶和華的約櫃從大衛城，就是錫安，接上來。","notes":[]},{"n":3,"t":"在七月節期的時候，所有的以色列人都聚集到王那裏。","notes":[]},{"n":4,"t":"以色列眾長老一來到，利未人就抬起約櫃。","notes":[]},{"n":5,"t":"祭司和利未人將約櫃請上來，又把會幕和會幕一切的聖器皿都帶上來。","notes":[]},{"n":6,"t":"所羅門王和聚集到他那裏的以色列全會眾都在約櫃前獻牛羊為祭，多得不可勝數，無法計算。","notes":[]},{"n":7,"t":"祭司將耶和華的約櫃請進內殿，就是至聖所，安置在兩個基路伯的翅膀底下約櫃自己的地方。","notes":[]},{"n":8,"t":"基路伯張開翅膀在約櫃上面的地方，從上面遮住約櫃和抬櫃的槓。","notes":[]},{"n":9,"t":"這槓很長，從內殿前的約櫃可以看見槓頭，從外面卻看不見。這槓直到今日還在那裏。","notes":[]},{"n":10,"t":"約櫃裏沒有別的，只有兩塊石版，就是以色列人出埃及，耶和華與他們立約的時候，摩西在何烈山所放的。","notes":[]},{"n":11,"t":"當時，所有在那裏的祭司，不論哪個班次供職的，都使自己分別為聖。祭司從聖所出來的時候，","notes":[],"heads":["神的榮光"]},{"n":12,"t":"所有歌唱的利未人，亞薩、希幔、耶杜頓，和他們的眾兒子、眾弟兄都穿細麻布衣服，站在祭壇的東邊敲鈸，鼓瑟，彈琴，和他們一起的還有一百二十個吹號的祭司。","notes":[]},{"n":13,"t":"吹號的、歌唱的都合一齊聲，讚美稱謝耶和華。他們配合號筒、鐃鈸和其他樂器，揚聲讚美耶和華：「耶和華本為善，他的慈愛永遠長存！」那時，耶和華的殿充滿了雲彩。","notes":[]},{"n":14,"t":"祭司因雲彩的緣故不能站立供職，因為耶和華的榮光充滿了神的殿。","notes":[]}]},"6":{"heading":"所羅門向百姓講話","verses":[{"n":1,"t":"那時，所羅門說：「耶和華曾說要住在幽暗之處。","notes":[]},{"n":2,"t":"我為你建了一座雄偉的殿宇，作為你永遠居住的地方。」","notes":[]},{"n":3,"t":"王轉過臉來為以色列全會眾祝福，以色列全會眾都站立。","notes":[]},{"n":4,"t":"所羅門說：「耶和華－以色列的神是應當稱頌的！因他親口向我父大衛應許的，也親手成就了；他曾說：","notes":[]},{"n":5,"t":"『自從那日我領我百姓出埃及地以來，我未曾在以色列各支派中選擇一城，在那裏為我的名建造殿宇，也未曾揀選一人作我百姓以色列的君王。","notes":[]},{"n":6,"t":"但我選擇耶路撒冷，使我的名留在那裏，又揀選大衛治理我的百姓以色列。』","notes":[]},{"n":7,"t":"我父大衛的心意是要為耶和華－以色列神的名建殿。","notes":[]},{"n":8,"t":"耶和華卻對我父大衛說：『你有心為我的名建殿，這心意是好的；","notes":[]},{"n":9,"t":"但你不可建殿，惟有你親生的兒子才可為我的名建殿。』","notes":[]},{"n":10,"t":"現在耶和華實現了他所應許的話，使我接續我父大衛坐以色列的王位，正如耶和華所說的，我也為耶和華－以色列神的名建造了這殿。","notes":[]},{"n":11,"t":"我將約櫃安置在那裏，櫃內有耶和華的約，就是他與以色列人所立的約。」","notes":[]},{"n":12,"t":"所羅門當著以色列全會眾，站在耶和華的壇前，舉起手來。","notes":[],"heads":["所羅門的禱告"]},{"n":13,"t":"所羅門曾造一個銅臺，長五肘，寬五肘，高三肘，放在院中。他站在臺上，當著以色列全會眾雙膝跪下，向天舉手，","notes":[]},{"n":14,"t":"說：「耶和華－以色列的神啊，天上地下沒有神明可與你相比！你向那些盡心行在你面前的僕人守約施慈愛，","notes":[]},{"n":15,"t":"這約是你向你僕人大衛守的，是你應許他的。你親口應許，親手成就，正如今日一樣。","notes":[]},{"n":16,"t":"耶和華－以色列的神啊，你向你僕人我父大衛應許說：『你的子孫若謹慎自己的行為，遵行我的律法，像你在我面前所行的，就不斷有人在我面前坐以色列的王位。』現在求你信守這話。","notes":[]},{"n":17,"t":"耶和華－以色列的神啊，現在求你成就向你僕人大衛所應許的話。","notes":[]},{"n":18,"t":"「神果真與世人同住在地上嗎？看哪，天和天上的天尚且不足容納你，何況我所建的這殿呢？","notes":[]},{"n":19,"t":"惟求耶和華－我的神垂顧僕人的禱告祈求，俯聽僕人在你面前的祈禱呼求。","notes":[]},{"n":20,"t":"願你的眼目晝夜看顧這殿，就是你應許立為你名的居所；求你垂聽禱告，你僕人向此處的禱告。","notes":[]},{"n":21,"t":"你僕人和你百姓以色列向此處祈禱的時候，求你從天上你的居所垂聽，垂聽而赦免。","notes":[]},{"n":22,"t":"「人若得罪鄰舍，有人強迫他，要他起誓，他來到這殿，在你的壇前起誓，","notes":[]},{"n":23,"t":"求你從天上垂聽、處理，向你的僕人施行審判，定惡人有罪，照他所行的報應在他頭上；定義人為義，照他的義賞賜他。","notes":[]},{"n":24,"t":"「你的百姓以色列若得罪你，敗在仇敵面前，卻又歸向你，宣認你的名，在這殿裏向你祈求禱告，","notes":[]},{"n":25,"t":"求你從天上垂聽，赦免你百姓以色列的罪，使他們歸回你賜給他們和他們列祖之地。","notes":[]},{"n":26,"t":"「你的百姓若得罪了你，你使天閉塞不下雨；他們若向此處禱告，宣認你的名，因你的懲罰而離開他們的罪，","notes":[]},{"n":27,"t":"求你在天上垂聽，赦免你僕人你百姓以色列的罪，將當行的善道教導他們，並降雨在你的地，就是你賜給你百姓為業之地。","notes":[]},{"n":28,"t":"「這地若有饑荒、瘟疫、焚風、霉爛、蝗蟲、螞蚱，或有仇敵圍困這地的城門，無論遭遇甚麼災禍疾病，","notes":["「焚風」或譯「蟲害」。"]},{"n":29,"t":"你的百姓以色列，或眾人或一人，自覺災禍困苦，向這殿舉手，無論祈求甚麼，禱告甚麼，","notes":[]},{"n":30,"t":"求你從天上你的居所垂聽赦免。因為你知道人心，惟有你知道世人的心，求你照各人所行的一切待他們，","notes":[]},{"n":31,"t":"使他們在你賜給我們列祖的土地上一生一世敬畏你，遵行你的道。","notes":[]},{"n":32,"t":"「論到不屬你百姓以色列的外邦人，若為你的大名和大能的手，以及伸出來的膀臂，從遠方而來，來向這殿禱告，","notes":[]},{"n":33,"t":"求你從天上你的居所垂聽，照著外邦人向你所求的一切而行，使地上萬民都認識你的名，敬畏你，像你的百姓以色列一樣，又使他們知道我所建造的是稱為你名下的殿。","notes":[]},{"n":34,"t":"「你的百姓若奉你的派遣出去，無論往何處與仇敵爭戰，他們若向你所選擇的這城和我為你名所建造的殿禱告，","notes":[]},{"n":35,"t":"求你從天上垂聽他們的禱告祈求，為他們伸張正義。","notes":[]},{"n":36,"t":"「你的百姓若得罪你，因為沒有人不犯罪，你向他們發怒，把他們交在仇敵面前，擄他們的人把他們帶到或遠或近之地；","notes":[]},{"n":37,"t":"他們若在被擄之地那裏回心轉意，在被擄之地悔改，向你懇求說：『我們有罪了，我們悖逆了，我們作惡了』；","notes":[]},{"n":38,"t":"他們若在被擄之地盡心盡性歸向你，又向自己的地，就是你賜給他們列祖的地和你所選擇的城，以及我為你名所建造的這殿禱告，","notes":[]},{"n":39,"t":"求你從天上你的居所垂聽他們的禱告祈求，為他們伸張正義，赦免你的百姓向你犯的罪。","notes":[]},{"n":40,"t":"我的神啊，現在求你睜眼看，側耳聽在此處所獻的禱告。","notes":[]},{"n":41,"t":"「耶和華神啊，現在求你興起，與你有能力的約櫃同入安歇之所。耶和華神啊，願你的祭司披上救恩，願你的聖民蒙福歡樂。","notes":[]},{"n":42,"t":"耶和華神啊，求你不要厭棄你的受膏者，要記得向你僕人大衛所施的慈愛。」","notes":[]}]},"7":{"heading":"聖殿的奉獻禮","verses":[{"n":1,"t":"所羅門祈禱完畢，就有火從天降下來，燒盡燔祭和祭物。耶和華的榮光充滿了殿；","notes":[]},{"n":2,"t":"因耶和華的榮光充滿了耶和華的殿，所以祭司不能進耶和華的殿。","notes":[]},{"n":3,"t":"那火降下、耶和華的榮光在殿上的時候，以色列眾人看見，就在石板地俯伏敬拜，稱謝耶和華：「耶和華本為善，他的慈愛永遠長存！」","notes":[]},{"n":4,"t":"王和眾百姓在耶和華面前獻祭。","notes":[]},{"n":5,"t":"所羅門王獻二萬二千頭牛、十二萬隻羊為祭。這樣，王和眾百姓為神的殿行了奉獻之禮。","notes":[]},{"n":6,"t":"祭司各供其職侍立，利未人拿著耶和華的樂器，就是大衛王所造、為要頌讚耶和華的樂器，因他的慈愛永遠長存；他們為大衛的讚美詩奏樂；祭司在眾人面前吹號，以色列眾人都站立。","notes":[]},{"n":7,"t":"所羅門因他所造的銅壇容不下燔祭、素祭和脂肪，就將耶和華殿前院子的中間分別為聖，在那裏獻燔祭和平安祭牲的脂肪。","notes":[]},{"n":8,"t":"那時所羅門守節七日，從哈馬口直到埃及溪谷的以色列眾人都與他同在一起，成了一個極其盛大的會。","notes":[]},{"n":9,"t":"第八日他們舉行嚴肅會，行奉獻壇的禮七日，守節七日。","notes":[]},{"n":10,"t":"七月二十三日，王差遣百姓回自己的帳棚去；他們為耶和華向大衛和所羅門，以及他百姓以色列所施的恩惠，心裏都歡喜快樂。","notes":[]},{"n":11,"t":"所羅門建完了耶和華的殿和王宮；在耶和華的殿和王宮的工程上，凡他心中所要做的，都順利做成了。","notes":[],"heads":["神再次向所羅門顯現"]},{"n":12,"t":"夜間耶和華向所羅門顯現，對他說：「我已聽了你的禱告，也選擇這地方歸我作獻祭的殿宇。","notes":[]},{"n":13,"t":"我若使天閉塞不下雨，或使蝗蟲吃這地的出產，或降瘟疫在我子民中，","notes":[]},{"n":14,"t":"這稱為我名下的子民，若是謙卑自己，禱告，尋求我的面，轉離他們的惡行，我必從天上垂聽，赦免他們的罪，醫治他們的地。","notes":[]},{"n":15,"t":"我必睜眼看，側耳聽在此處所獻的禱告。","notes":[]},{"n":16,"t":"現在我已選擇這殿，分別為聖，使我的名永在其中；我的眼、我的心也必時常在那裏。","notes":[]},{"n":17,"t":"你若行在我面前，效法你父大衛所行的，遵行我一切所吩咐你的，謹守我的律例典章，","notes":[]},{"n":18,"t":"我就必堅固你國度的王位，正如我與你父大衛所立的約，說：『你的子孫必不斷有人治理以色列。』","notes":[]},{"n":19,"t":"「倘若你們轉去，離棄我擺在你們面前的律例誡命，去事奉別神，敬拜它們，","notes":[]},{"n":20,"t":"我就必把以色列人從我賜給他們的地上連根拔起，也必從我面前捨棄那為我名所分別為聖的殿，使它在萬民中成為笑柄，被人譏誚。","notes":[]},{"n":21,"t":"這殿雖然崇高，將來凡經過的人必驚訝說：『耶和華為何向這地和這殿如此行呢？』","notes":[]},{"n":22,"t":"人必說：『因為此地的人離棄領他們祖先出埃及地的耶和華－他們的神，去親近別神，敬拜事奉它們，所以耶和華使這一切災禍臨到他們。』」","notes":[]}]},"8":{"heading":"所羅門的成就","verses":[{"n":1,"t":"所羅門建造耶和華的殿和王宮，用了二十年才完成。","notes":[]},{"n":2,"t":"所羅門修築希蘭送給他的城鎮，使以色列人住在那裏。","notes":[]},{"n":3,"t":"所羅門往哈馬‧瑣巴去，攻取了那地方。","notes":[]},{"n":4,"t":"所羅門建造曠野的達莫，建造哈馬一切的儲貨城，","notes":[]},{"n":5,"t":"又建造上伯‧和崙、下伯‧和崙，成為有牆、門、閂的堡壘城。","notes":[]},{"n":6,"t":"所羅門建造巴拉和一切的儲貨城、戰車城、戰馬城，以及他所想要建造的，在耶路撒冷、黎巴嫩，和自己所治理全國中的一切建設。","notes":[]},{"n":7,"t":"至於所有剩下的百姓，不屬以色列的赫人、亞摩利人、比利洗人、希未人、耶布斯人，","notes":[]},{"n":8,"t":"那些以色列人在當地不能滅盡的人，所羅門徵召他們剩下的後代服勞役，直到今日。","notes":[]},{"n":9,"t":"惟有以色列人，所羅門不使他們當奴僕做工，而是作他的戰士、軍官、戰車長、騎兵長。","notes":[]},{"n":10,"t":"這些是所羅門王的監工，共有二百五十名百姓的監工。","notes":[]},{"n":11,"t":"所羅門把法老的女兒遷出大衛城，上到他為她建造的宮裏，因所羅門說：「耶和華約櫃所到之處都是聖地，所以我的妻子不可住在以色列王大衛的宮裏。」","notes":[]},{"n":12,"t":"那時，所羅門在走廊前他所築的耶和華的壇上，向耶和華獻燔祭，","notes":[]},{"n":13,"t":"又遵照摩西的吩咐，在安息日、初一，以及每年在除酵節、七七節、住棚節三個節期，獻每日所當獻上的祭。","notes":[]},{"n":14,"t":"所羅門照著他父親大衛所定的條例，分派祭司的班次，擔任他們的職務，又分派利未人的任務，負責頌讚，並在祭司面前做每日當做的事，又派門口的守衛按著班次看守各門，因為神人大衛是這樣吩咐的。","notes":[]},{"n":15,"t":"王對眾祭司和利未人的吩咐，無論是管理庫房或任何事務，他們都不違背。","notes":[]},{"n":16,"t":"所羅門所有的工作都準備就緒，從立耶和華殿的根基直到完工的日子。耶和華的殿就完成了。","notes":[]},{"n":17,"t":"那時，所羅門往以東地海岸的以旬‧迦別和以祿去。","notes":[]},{"n":18,"t":"希蘭派他的臣僕，把船隻和熟悉航海的僕人送到所羅門那裏。他們同所羅門的僕人到了俄斐，從那裏得了四百五十他連得金子，運到所羅門王那裏。","notes":[]}]},"9":{"heading":"示巴女王拜訪所羅門","verses":[{"n":1,"t":"示巴女王聽見所羅門的名聲，就來到耶路撒冷，要用難題考問所羅門。她帶著很多的隨從，有駱駝馱著香料、許多金子和寶石。她來到所羅門那裏，向他提出心中所有的問題。","notes":[]},{"n":2,"t":"所羅門回答了她所有的問題，沒有一個問題太難，是所羅門不能向她解答的。","notes":[]},{"n":3,"t":"示巴女王看見所羅門的智慧和他所建造的宮殿，","notes":[]},{"n":4,"t":"席上的食物，坐著的群臣，侍立的僕人和他們的服裝，司酒長和他們的服裝，以及他上耶和華殿的臺階，就詫異得神不守舍。","notes":["「臺階」或譯「樓房」；「他上耶和華殿的臺階」：七十士譯本和其他古譯本是「他在耶和華殿裏所獻的燔祭」；參王上10．5。"]},{"n":5,"t":"她對王說：「我在本國所聽到的話，論到你的事和你的智慧是真的！","notes":[]},{"n":6,"t":"我本來不信那些話，及至我來親眼看見了，看哪，人所告訴我的，還不及你豐富智慧的一半，超過我所聽見的傳聞。","notes":[]},{"n":7,"t":"你的人是有福的！你這些常侍立在你面前、聽你智慧話的僕人是有福的！","notes":[]},{"n":8,"t":"耶和華－你的神是應當稱頌的！他喜愛你，使你坐他的王位，為耶和華－你的神作王；因為你的神愛以色列，要永遠堅立它，所以立你作他們的王，使你秉公行義。」","notes":[]},{"n":9,"t":"於是示巴女王把一百二十他連得金子、極多的香料和寶石送給所羅門王；從來沒有像示巴女王送給所羅門王那麼多的香料。","notes":[]},{"n":10,"t":"希蘭的僕人和所羅門的僕人也從俄斐運了金子來，又運了檀香木和寶石來。","notes":[]},{"n":11,"t":"王用檀香木為耶和華的殿和王宮做階梯，又為歌唱的人做琴瑟；猶大地從來沒有見過這樣的。","notes":[]},{"n":12,"t":"所羅門王除了回贈示巴女王所帶來的，凡她所提出的一切要求，所羅門王都送給她。於是女王和她臣僕轉回，到本國去了。","notes":[]},{"n":13,"t":"所羅門每年所得的金子，重六百六十六他連得，","notes":[],"heads":["所羅門的財富"]},{"n":14,"t":"另外還有從商人和貿易所收到的，以及阿拉伯諸王和各地的省長進貢給所羅門的金銀。","notes":[]},{"n":15,"t":"所羅門王用錘出來的金子打成二百面盾牌，每面盾牌用六百舍客勒錘出來的金子；","notes":[]},{"n":16,"t":"又用錘出來的金子打成三百面小盾牌，每面小盾牌用三百舍客勒金子。王把它們放在黎巴嫩林宮裏。","notes":[]},{"n":17,"t":"王又製造一個大的象牙寶座，包上純金。","notes":[]},{"n":18,"t":"寶座有六層臺階，又有金腳凳，與寶座相連。座位之處兩旁有扶手，靠近扶手有兩隻獅子站立。","notes":[]},{"n":19,"t":"六層臺階上有十二隻獅子站立，分站左邊和右邊；任何國度都沒有這樣做的。","notes":[]},{"n":20,"t":"所羅門王一切的飲器都是金的，黎巴嫩林宮裏所有的器皿都是純金的。在所羅門的日子，銀子算不了甚麼。","notes":[]},{"n":21,"t":"因王的船隻與希蘭的僕人一同往他施去，他施船隻每三年一次把金、銀、象牙、猿猴、孔雀運回來。","notes":["「孔雀」或譯「狒狒」。"]},{"n":22,"t":"所羅門王的財寶與智慧勝過地上的眾王。","notes":[]},{"n":23,"t":"地上的眾王都求見所羅門的面，要聽神放在他心裏的智慧。","notes":[]},{"n":24,"t":"他們各帶貢物，就是銀器、金器、衣服、兵器、香料、馬、騾子，每年都有一定的數量。","notes":[]},{"n":25,"t":"所羅門擁有給戰車和馬用的四千個棚子，還有一萬二千名騎兵，安置在屯車城，在耶路撒冷的王那裏。","notes":[]},{"n":26,"t":"所羅門統管諸王，從大河到非利士人的地，直到埃及的邊界。","notes":[]},{"n":27,"t":"王在耶路撒冷使銀子多如石頭，香柏木多如謝非拉的桑樹。","notes":[]},{"n":28,"t":"有人從埃及和各國為所羅門把馬匹運來。","notes":["「埃及」可能不是南方的埃及，而是美索不達米亞北方的一國。"]},{"n":29,"t":"所羅門其餘的事，自始至終，不都寫在拿單先知的書上和示羅人亞希雅的《預言書》上，以及易多先見論尼八兒子耶羅波安的《默示書》上嗎？","notes":[],"heads":["所羅門去世"]},{"n":30,"t":"所羅門在耶路撒冷作全以色列的王四十年。","notes":[]},{"n":31,"t":"所羅門與他祖先同睡，葬在他父親大衛的城裏，他兒子羅波安接續他作王。","notes":[]}]},"10":{"heading":"北方支派的反叛","verses":[{"n":1,"t":"羅波安往示劍去，因以色列眾人都到了示劍，要立他作王。","notes":[]},{"n":2,"t":"尼八的兒子耶羅波安先前躲避所羅門王，逃往埃及，住在那裏；他聽見這事，就從埃及回來。","notes":[]},{"n":3,"t":"以色列人派人去請他來。耶羅波安就和以色列眾人來，與羅波安談話，說：","notes":[]},{"n":4,"t":"「你父親使我們負重軛，現在求你減輕你父親所加給我們的苦工和重軛，我們就服事你。」","notes":[]},{"n":5,"t":"羅波安對他們說：「過三天再來見我吧！」百姓就走了。","notes":[]},{"n":6,"t":"羅波安的父親所羅門在世的時候，有侍立在他面前的長者，羅波安王和他們商議，說：「你們出個主意，好把話帶回給這百姓。」","notes":[]},{"n":7,"t":"他們對他說：「王若恩待這百姓，使他們喜悅，跟他們說好話，他們就永遠作王的僕人了。」","notes":[]},{"n":8,"t":"王不採納長者給他出的主意，卻和那些與他一同長大、在他面前侍立的年輕人商議。","notes":[]},{"n":9,"t":"他對他們說：「這百姓對我說：『你父親使我們負重軛，求你減輕一些。』你們出個甚麼主意，我們好把話帶回給他們。」","notes":[]},{"n":10,"t":"那些與他一同長大的年輕人對他說：「這些百姓對王說：『你父親使我們負重軛，求你給我們減輕一些。』王要對他們如此說：『我的小指頭比我父親的腰還粗呢！","notes":[]},{"n":11,"t":"我父親使你們負重軛，現在我必使你們負更重的軛！我父親用鞭子懲罰你們，我卻要用蠍子！』」","notes":[]},{"n":12,"t":"耶羅波安和眾百姓遵照王所說「你們第三天再來見我」的話，第三天來到羅波安那裏。","notes":[]},{"n":13,"t":"王嚴厲地回答他們。羅波安王不採納長者所出的主意，","notes":[]},{"n":14,"t":"卻照著年輕人所出的主意對他們說：「我使你們負重軛，我必使你們負更重的軛！我父親用鞭子懲罰你們，我卻要用蠍子！」","notes":["「我」：有些古卷、七十士譯本和其他古譯本是「我父親」；參王上12．14。"]},{"n":15,"t":"王不依從百姓，因這事件是出於神，為要應驗耶和華藉示羅人亞希雅對尼八的兒子耶羅波安所說的話。","notes":[]},{"n":16,"t":"以色列眾人見王不依從他們，百姓就回覆王說：「我們在大衛中有甚麼分呢？我們在耶西的兒子中沒有產業！以色列啊，各回自己的帳棚去吧！大衛啊，現在你顧自己的家吧！」於是，以色列眾人都回自己的帳棚去了；","notes":[]},{"n":17,"t":"至於住猶大城鎮的以色列人，羅波安仍作他們的王。","notes":[]},{"n":18,"t":"羅波安王派監管勞役的哈多蘭去，以色列人用石頭打他，他就死了。羅波安王急忙上車，逃回耶路撒冷去了。","notes":["「哈多蘭」：王上12．18稱「亞多蘭」。"]},{"n":19,"t":"這樣，以色列背叛大衛家，直到今日。","notes":[]}]},"11":{"heading":"示瑪雅的預言","verses":[{"n":1,"t":"羅波安來到耶路撒冷，召集猶大家和便雅憫家，共十八萬人，都是精選的戰士，要與以色列爭戰，好將國奪回再歸自己。","notes":[]},{"n":2,"t":"但耶和華的話臨到神人示瑪雅，說：","notes":[]},{"n":3,"t":"「你去告訴所羅門的兒子猶大王羅波安和住猶大、便雅憫的以色列眾人，說：","notes":[]},{"n":4,"t":"『耶和華如此說：你們不可上去與你們的弟兄爭戰。各自回家去吧！因為這事是出於我。』」眾人就聽從耶和華的話回去，不去與耶羅波安爭戰。","notes":[]},{"n":5,"t":"羅波安住在耶路撒冷，在猶大為防禦修築城鎮，","notes":[],"heads":["羅波安修築諸城"]},{"n":6,"t":"他修築伯利恆、以坦、提哥亞、","notes":[]},{"n":7,"t":"伯‧夙、梭哥、亞杜蘭、","notes":[]},{"n":8,"t":"迦特、瑪利沙、西弗、","notes":[]},{"n":9,"t":"亞多萊音、拉吉、亞西加、","notes":[]},{"n":10,"t":"瑣拉、亞雅崙、希伯崙。這都是猶大和便雅憫的堅固城。","notes":[]},{"n":11,"t":"羅波安又鞏固這些堡壘，在其中安置軍官，儲備糧食、油和酒。","notes":[]},{"n":12,"t":"他在各城裏預備盾牌和槍，使城極其堅固。猶大和便雅憫都歸了他。","notes":[]},{"n":13,"t":"全以色列的祭司和利未人都從四方來歸羅波安。","notes":[],"heads":["祭司和利未人都歸猶大"]},{"n":14,"t":"利未人放棄他們的郊野和產業，來到猶大與耶路撒冷，因為耶羅波安和他的兒子拒絕他們，不許他們擔任祭司事奉耶和華。","notes":[]},{"n":15,"t":"耶羅波安為丘壇，為山羊鬼魔，為自己所造的牛犢設立祭司。","notes":[]},{"n":16,"t":"以色列各支派中，凡立定心意尋求耶和華－以色列神的，都隨從利未人來到耶路撒冷獻祭給耶和華－他們列祖的神。","notes":[]},{"n":17,"t":"這就鞏固了猶大王國，使所羅門的兒子羅波安強盛三年，因為這三年他們遵行大衛和所羅門的道。","notes":["「他們遵行」：七十士譯本是「他遵行」。"]},{"n":18,"t":"羅波安娶大衛兒子耶利末的女兒瑪哈拉為妻，又娶耶西兒子以利押的女兒亞比孩為妻，","notes":[],"heads":["羅波安的家室"]},{"n":19,"t":"從她生了幾個兒子，就是耶烏施、示瑪利雅和撒罕。","notes":[]},{"n":20,"t":"後來他又娶押沙龍的女兒瑪迦，從她生了亞比雅、亞太、細撒和示羅密。","notes":[]},{"n":21,"t":"羅波安有十八個妻和六十個妾，生了二十八個兒子，六十個女兒；他卻愛押沙龍的女兒瑪迦，過於愛其他的妻妾。","notes":[]},{"n":22,"t":"羅波安立瑪迦的兒子亞比雅作太子，在他兄弟中為首，因為要立他作王。","notes":[]},{"n":23,"t":"羅波安辦事精明，把他眾兒子分散在猶大和便雅憫全地各堅固城裏，賜他們大量的糧食，又給他們娶許多妻子。","notes":[]}]},"12":{"heading":"埃及侵犯猶大","verses":[{"n":1,"t":"羅波安的王國穩固，他強盛的時候就離棄耶和華的律法，全以色列都跟從他。","notes":[]},{"n":2,"t":"羅波安王第五年，埃及王示撒上來攻打耶路撒冷，因為他們背叛了耶和華。","notes":[]},{"n":3,"t":"示撒帶著一千二百輛戰車，六萬名騎兵，以及跟隨他從埃及出來的路比人、蘇基人和古實人的軍隊，多得不可勝數。","notes":[]},{"n":4,"t":"他攻取了猶大的堅固城，來到耶路撒冷。","notes":[]},{"n":5,"t":"那時，猶大的領袖因為示撒的緣故聚集在耶路撒冷，有先知示瑪雅去見羅波安和眾領袖，對他們說：「耶和華如此說：『你們離棄了我，所以我也離棄你們，把你們交在示撒手裏。』」","notes":[]},{"n":6,"t":"於是以色列的領袖和王都謙卑說：「耶和華是公義的。」","notes":[]},{"n":7,"t":"耶和華見他們謙卑，耶和華的話就臨到示瑪雅，說：「他們既謙卑，我必不滅絕他們；我要使他們暫時得拯救，不藉著示撒的手將我的怒氣倒在耶路撒冷。","notes":[]},{"n":8,"t":"然而他們必作示撒的僕人，好叫他們知道，服事我與服事地上邦國有何分別。」","notes":[]},{"n":9,"t":"於是，埃及王示撒上來攻取耶路撒冷，奪了耶和華殿和王宮裏的寶物，盡都帶走，又奪走所羅門製造的金盾牌。","notes":[]},{"n":10,"t":"羅波安王製造銅盾牌代替那些金盾牌，交給看守王宮宮門的護衛長看管。","notes":[]},{"n":11,"t":"每逢王進耶和華的殿，護衛兵就來，舉起這些盾牌；隨後仍將盾牌送回護衛室。","notes":[]},{"n":12,"t":"王謙卑的時候，耶和華的怒氣就轉消了，不全然滅盡，並且在猶大中，情況也有好轉。","notes":[]},{"n":13,"t":"羅波安王自強，在耶路撒冷作王。他登基的時候年四十一歲，在耶路撒冷，就是耶和華從以色列眾支派中所選擇立他名的城，作王十七年。羅波安的母親名叫拿瑪，是亞捫人。","notes":[],"heads":["羅波安政績簡述"]},{"n":14,"t":"羅波安行惡，因他沒有立定心意尋求耶和華。","notes":[]},{"n":15,"t":"羅波安的事蹟，自始至終不都寫在示瑪雅先知和易多先見的《史記》上嗎？羅波安與耶羅波安時常交戰。","notes":[]},{"n":16,"t":"羅波安與他祖先同睡，葬在大衛城，他的兒子亞比雅接續他作王。","notes":["「亞比雅」：王上14．31稱「亞比央」。"]}]},"13":{"heading":"亞比雅與耶羅波安爭戰","verses":[{"n":1,"t":"耶羅波安王十八年，亞比雅登基作猶大王，","notes":[]},{"n":2,"t":"在耶路撒冷作王三年。他母親名叫米該亞，是基比亞人烏列的女兒。亞比雅常與耶羅波安交戰。","notes":["「米該亞...烏列的女兒」：11．20稱「押沙龍的女兒瑪迦」。"]},{"n":3,"t":"有一次亞比雅率領四十萬精選的士兵出戰，他們都是勇敢的戰士；耶羅波安也率領八十萬精選的大能勇士，迎著亞比雅擺陣。","notes":[]},{"n":4,"t":"亞比雅站在以法蓮山區中的洗瑪臉山上，說：「耶羅波安和以色列眾人哪，要聽我說！","notes":[]},{"n":5,"t":"耶和華－以色列的神曾立鹽約，將以色列國永遠賜給大衛和他的子孫，你們不知道嗎？","notes":[]},{"n":6,"t":"但大衛兒子所羅門的臣僕、尼八的兒子耶羅波安起來背叛他的主人。","notes":[]},{"n":7,"t":"有些無賴的歹徒聚集跟從他，逞強攻擊所羅門的兒子羅波安；那時羅波安還年輕，心志軟弱，不能抵擋他們。","notes":[]},{"n":8,"t":"「現在你們說要抗拒大衛子孫手下所治理的耶和華的國，你們的人數眾多，你們那裏又有耶羅波安為你們所造當作神明的金牛犢。","notes":[]},{"n":9,"t":"你們不是驅逐耶和華的祭司亞倫的後裔和利未人嗎？不是照著外邦人的惡俗為自己立祭司嗎？無論何人牽一頭公牛犢、七隻公綿羊將自己分別出來，就可作虛無神明的祭司。","notes":[]},{"n":10,"t":"至於我們，耶和華是我們的神，我們並沒有離棄他。我們有事奉耶和華的祭司，都是亞倫的後裔，並有利未人各盡其職。","notes":[]},{"n":11,"t":"他們每日早晚向耶和華獻燔祭，燒芬芳的香，又在純金的供桌上擺供餅，每晚點燃金燈臺上的燈盞，因為我們遵守耶和華－我們神的命令，但你們卻離棄了他。","notes":["「純金的」：原文沒有「金」；或譯「潔淨的」。"]},{"n":12,"t":"看哪，率領我們的是神，又有他的祭司拿號向你們吹出響聲。以色列人哪，不要與耶和華－你們列祖的神爭戰，因你們必不能得勝。」","notes":[]},{"n":13,"t":"耶羅波安卻在猶大人的後頭設伏兵。這樣，以色列人在猶大人的前頭，伏兵在猶大人的後頭。","notes":[]},{"n":14,"t":"猶大人轉過來，看哪，前後都有戰事，就呼求耶和華，祭司也吹號。","notes":[]},{"n":15,"t":"於是猶大人吶喊。猶大人吶喊的時候，神就擊打耶羅波安和以色列眾人，使他們敗在亞比雅與猶大人面前。","notes":[]},{"n":16,"t":"以色列人在猶大人面前逃跑，神將他們交在猶大人手裏。","notes":[]},{"n":17,"t":"亞比雅和他的軍兵大大擊殺以色列人，以色列人被殺仆倒的精兵有五十萬。","notes":[]},{"n":18,"t":"那時，以色列人被制伏了。猶大人得勝，因為他們倚靠耶和華－他們列祖的神。","notes":[]},{"n":19,"t":"亞比雅追趕耶羅波安，攻取了他的幾座城，就是伯特利和所屬的鄉鎮，耶沙拿和所屬的鄉鎮，以法拉音和所屬的鄉鎮。","notes":["「鄉鎮」：原文直譯「女子們」；本卷書下同。","「以法拉音」：原文另譯「以弗崙」。"]},{"n":20,"t":"亞比雅在世的時候，耶羅波安不再強盛；耶和華擊打他，他就死了。","notes":[]},{"n":21,"t":"亞比雅卻漸漸強盛。他娶了十四個妻妾，生了二十二個兒子，十六個女兒。","notes":[]},{"n":22,"t":"亞比雅其餘的事和他的言行都寫在易多先知的評傳上。","notes":[]}]},"14":{"heading":"亞撒王擊敗古實人","verses":[{"n":1,"t":"亞比雅與他祖先同睡，葬在大衛城，他的兒子亞撒接續他作王。亞撒在位期間，國中太平十年。","notes":[]},{"n":2,"t":"亞撒行耶和華－他神眼中看為善為正的事，","notes":[]},{"n":3,"t":"除掉外邦的祭壇和丘壇，打碎柱像，砍下亞舍拉，","notes":[]},{"n":4,"t":"吩咐猶大人尋求耶和華－他們列祖的神，遵行他的律法和誡命，","notes":[]},{"n":5,"t":"又在猶大各城鎮除掉丘壇和香壇。在他治理下，國中太平。","notes":[]},{"n":6,"t":"他在猶大建造了幾座堅固城。那些年間，國中太平，沒有戰爭，因為耶和華賜他平安。","notes":[]},{"n":7,"t":"他對猶大人說：「我們要建造這些城鎮，四圍築牆，蓋城樓，安門，做閂；地仍屬於我們，因為我們尋求耶和華－我們的神；我們尋求他，他就賜我們四境平安。」於是他們建造城鎮，諸事亨通。","notes":[]},{"n":8,"t":"亞撒的軍兵，出自猶大拿盾牌拿槍的三十萬人，出自便雅憫拿小盾牌拉弓的二十八萬人；這些全都是大能的勇士。","notes":[]},{"n":9,"t":"古實人謝拉率領一百萬軍兵，三百輛戰車，出來攻擊猶大人，到了瑪利沙。","notes":[]},{"n":10,"t":"亞撒出去迎戰，在瑪利沙的洗法谷彼此擺陣。","notes":[]},{"n":11,"t":"亞撒呼求耶和華－他的神說：「耶和華啊，在強弱之間，惟有你能幫助。耶和華－我們的神啊，求你幫助我們，因為我們仰賴你，奉你的名來抵擋這大軍。耶和華啊，你是我們的神，不要讓人勝過你。」","notes":[]},{"n":12,"t":"於是耶和華擊打古實人，使他們敗在亞撒和猶大人面前，古實人就逃跑了。","notes":[]},{"n":13,"t":"亞撒和跟隨他的軍兵追趕他們，直到基拉耳。古實人被殺的很多，無法復原，因為他們在耶和華與他軍兵面前被擊潰。猶大人奪了許多財物，","notes":[]},{"n":14,"t":"又攻打基拉耳四圍一切的城鎮；城中的人都懼怕耶和華。猶大人擄掠了一切的城鎮，因其中的財物很多，","notes":[]},{"n":15,"t":"又毀壞了群畜的圈，奪取許多的羊和駱駝，就回耶路撒冷去了。","notes":[]}]},"15":{"heading":"亞撒的改革","verses":[{"n":1,"t":"神的靈臨到俄德的兒子亞撒利雅。","notes":[]},{"n":2,"t":"他出來迎接亞撒，對他說：「亞撒，猶大和便雅憫眾人哪，要聽我說：你們若順從耶和華，耶和華必與你們同在；你們若尋求他，就必尋見；你們若離棄他，他必離棄你們。","notes":[]},{"n":3,"t":"以色列人不信真神，沒有訓誨的祭司，也沒有律法，已經許多日子了。","notes":[]},{"n":4,"t":"但他們在急難的時候歸向耶和華－以色列的神，尋求他，他就被他們尋見。","notes":[]},{"n":5,"t":"那時，出入的人不得平安，各地的居民都遭大亂；","notes":[]},{"n":6,"t":"他們被破壞殆盡，這國攻擊那國，這城攻擊那城，因為神用各樣災難擾亂他們。","notes":[]},{"n":7,"t":"現在你們要剛強，不要手軟，因你們所行的必得賞賜。」","notes":[]},{"n":8,"t":"亞撒聽見這些話和俄德先知的預言，就壯起膽來，在猶大和便雅憫全地，以及以法蓮山區所奪的各城，把其中的可憎之物盡都除掉，又在耶和華殿的走廊前重新修築耶和華的壇。","notes":[]},{"n":9,"t":"他又召集猶大和便雅憫眾人，以及他們中間寄居的以法蓮人、瑪拿西人、西緬人。有許多以色列人歸順亞撒，因為他們看見耶和華－他的神與他同在。","notes":[]},{"n":10,"t":"亞撒作王第十五年三月，他們都聚集在耶路撒冷。","notes":[]},{"n":11,"t":"那日他們從所取的擄物中，將七百頭牛和七千隻羊獻給耶和華。","notes":[]},{"n":12,"t":"他們立約，要盡心盡性尋求耶和華－他們列祖的神。","notes":[]},{"n":13,"t":"凡不尋求耶和華－以色列神的，無論大小、男女，必被處死。","notes":[]},{"n":14,"t":"他們就大聲歡呼，吹號吹角，向耶和華起誓。","notes":[]},{"n":15,"t":"猶大眾人為所起的誓歡喜，因他們盡心起誓，盡意尋求耶和華，耶和華就被他們尋見，且賜他們四境平安。","notes":[]},{"n":16,"t":"亞撒王甚至廢了他祖母瑪迦太后的位，因瑪迦造了可憎的亞舍拉。亞撒砍下她的偶像，搗得粉碎，在汲淪溪邊燒了，","notes":[]},{"n":17,"t":"只是丘壇還沒有從以色列中廢去，然而亞撒一生有純正的心。","notes":[]},{"n":18,"t":"亞撒將他父親所分別為聖與自己所分別為聖的金銀和器皿都奉到神的殿裏。","notes":[]},{"n":19,"t":"亞撒作王直到第三十五年，都沒有戰事。","notes":[]}]},"16":{"heading":"猶大與以色列爭戰","verses":[{"n":1,"t":"亞撒作王第三十六年，以色列王巴沙上來攻擊猶大，修築拉瑪，不許人從猶大王亞撒那裏出入。","notes":[]},{"n":2,"t":"於是亞撒從耶和華殿和王宮的府庫裏拿出金銀來，送給住在大馬士革的亞蘭王便‧哈達，說：","notes":[]},{"n":3,"t":"「你父曾與我父立約，我與你也要這樣立約。看哪，我把金銀送給你，請你廢掉你與以色列王巴沙所立的約，使他從我這裏撤退。」","notes":[]},{"n":4,"t":"便‧哈達聽從了亞撒王，就派遣他的軍官去攻打以色列的城鎮。他們攻下了以雲、但、亞伯‧瑪音和拿弗他利一切的儲貨城。","notes":[]},{"n":5,"t":"巴沙聽見了，就停工不修築拉瑪，任由他的工程停止。","notes":[]},{"n":6,"t":"於是亞撒王率領猶大眾人，運走巴沙修築拉瑪所用的石頭和木料，用以修築迦巴和米斯巴。","notes":[]},{"n":7,"t":"那時，哈拿尼先見來見猶大王亞撒，對他說：「因你仰賴亞蘭王，沒有仰賴耶和華－你的神，所以亞蘭王的軍兵逃脫了你的手。","notes":[],"heads":["哈拿尼先見"]},{"n":8,"t":"古實人和路比人的軍隊不是非常強大嗎？他們的戰車騎兵不是極多嗎？只因你仰賴耶和華，他就將他們交在你手裏。","notes":[]},{"n":9,"t":"因為耶和華的眼目遍察全地，要堅固向他存純正之心的人。你在這事上行得愚昧；因此，以後你必有戰爭。」","notes":[]},{"n":10,"t":"亞撒惱恨先見，為了這事向他發怒，將他囚在監裏。那時亞撒也虐待一些百姓。","notes":[]},{"n":11,"t":"亞撒自始至終的事蹟，看哪，都寫在《猶大和以色列諸王記》上。","notes":[],"heads":["亞撒逝世"]},{"n":12,"t":"亞撒作王三十九年的時候患了腳疾，非常嚴重。他生病的時候沒有求耶和華，只求醫生。","notes":[]},{"n":13,"t":"他作王四十一年死了，與他祖先同睡，","notes":[]},{"n":14,"t":"葬在大衛城自己所鑿的墳墓裏。人把他放在床上，床上堆滿各樣馨香的香料，就是按做香的作法調和的香料，又為他生一堆大火誌哀。","notes":[]}]},"17":{"heading":"猶大王約沙法","verses":[{"n":1,"t":"亞撒的兒子約沙法接續他作王，奮勇自強，防備以色列。","notes":[]},{"n":2,"t":"他安置軍兵在猶大一切堅固城裏，又安置駐軍在猶大地和他父親亞撒所得以法蓮的城鎮中。","notes":[]},{"n":3,"t":"耶和華與約沙法同在，因為他行他祖先大衛從前所行的道，不去尋求諸巴力，","notes":["有些抄本和七十士譯本沒有「大衛」。"]},{"n":4,"t":"只尋求他父親的神，遵行他的誡命，不效法以色列人的行為。","notes":[]},{"n":5,"t":"所以耶和華堅定約沙法手中的國，猶大眾人給他進貢；約沙法大有財富和尊榮。","notes":[]},{"n":6,"t":"他樂意遵行耶和華的道，並且從猶大再次除掉一切丘壇和亞舍拉。","notes":[]},{"n":7,"t":"他作王第三年，差遣官員便‧亥伊勒、俄巴底、撒迦利雅、拿坦業、米該亞往猶大各城去教導百姓。","notes":[]},{"n":8,"t":"跟他們一同去的有利未人示瑪雅、尼探雅、西巴第雅、亞撒黑、示米拉末、約拿單、亞多尼雅、多比雅、駝‧巴多尼雅；跟他們一同的又有以利沙瑪和約蘭二位祭司。","notes":[]},{"n":9,"t":"他們在猶大教導，帶著耶和華的律法書，走遍猶大各城教導百姓。","notes":[]},{"n":10,"t":"猶大四圍地上的邦國都懼怕耶和華，不敢與約沙法爭戰。","notes":[],"heads":["約沙法的功績"]},{"n":11,"t":"有些非利士人送禮物，進貢銀子給約沙法。阿拉伯人也送他七千七百隻公綿羊，七千七百隻公山羊。","notes":[]},{"n":12,"t":"約沙法日漸強大，他在猶大建造堡壘和儲貨城。","notes":[]},{"n":13,"t":"他在猶大城鎮中有許多工程，在耶路撒冷又有戰士，就是大能的勇士。","notes":[]},{"n":14,"t":"他們按著父家的數目如下：猶大族的千夫長以押拿為首，率領三十萬大能的勇士；","notes":[]},{"n":15,"t":"其次是約哈難千夫長，率領二十八萬；","notes":[]},{"n":16,"t":"其次是細基利的兒子亞瑪斯雅，他是一個自願奉獻給耶和華的人，率領二十萬大能的勇士。","notes":[]},{"n":17,"t":"便雅憫族有大能的勇士以利雅大，率領二十萬拿弓箭和盾牌的人；","notes":[]},{"n":18,"t":"其次是約薩拔，率領十八萬預備打仗的人。","notes":[]},{"n":19,"t":"這些都是伺候王的，還有王在全猶大的堅固城所安置的不在其內。","notes":[]}]},"18":{"heading":"米該雅警告亞哈","verses":[{"n":1,"t":"約沙法大有財富和尊榮，他與亞哈結親。","notes":[]},{"n":2,"t":"過了幾年，他下到撒瑪利亞去見亞哈；亞哈為他和跟從他的人宰了許多牛羊，勸他一同上去攻打基列的拉末。","notes":[]},{"n":3,"t":"以色列王亞哈問猶大王約沙法說：「你肯同我去攻打基列的拉末嗎？」他回答說：「你我不分彼此，我的軍隊就是你的軍隊，我們必與你一同去爭戰。」","notes":[]},{"n":4,"t":"約沙法對以色列王說：「請你先求問耶和華的話。」","notes":[]},{"n":5,"t":"於是以色列王召集先知四百人，問他們說：「我可以上去攻打基列的拉末嗎？還是不要上去呢？」他們說：「可以上去，因為神必將那城交在王的手裏。」","notes":[]},{"n":6,"t":"約沙法說：「這裏還有沒有耶和華的先知，我們好求問他呢？」","notes":[]},{"n":7,"t":"以色列王對約沙法說：「還有一個人，是音拉的兒子米該雅，我們可以託他求問耶和華。只是我真的很恨他，因為他對我說預言，從不說吉言，總是說凶信。」約沙法說：「請王不要這麼說。」","notes":[]},{"n":8,"t":"以色列王就召了一個官員來，說：「你快去，把音拉的兒子米該雅召來。」","notes":[]},{"n":9,"t":"以色列王和猶大王約沙法在撒瑪利亞城門前的禾場，各穿朝服，坐在寶座上，所有的先知都在他們面前說預言。","notes":[]},{"n":10,"t":"基拿拿的兒子西底家為自己造了鐵角，說：「耶和華如此說：『你要用這些角牴觸亞蘭人，直到將他們滅盡。』」","notes":[]},{"n":11,"t":"所有的先知也都這樣預言說：「可以上基列的拉末去，必然得勝，因為耶和華必將那城交在王的手中。」","notes":[]},{"n":12,"t":"那去召米該雅的使者對他說：「看哪，眾先知都異口同聲向王說吉言，你也跟他們說一樣的話，說吉言吧！」","notes":[]},{"n":13,"t":"米該雅說：「我指著永生的耶和華起誓，我的神說甚麼，我就說甚麼。」","notes":[]},{"n":14,"t":"米該雅來到王那裏，王問他：「米該雅啊，我們可以上去攻打基列的拉末嗎？還是不要上去呢？」他說：「可以上去，必然得勝，敵人必交在你們手裏。」","notes":[]},{"n":15,"t":"王對他說：「我要你發誓多少次，你才會奉耶和華的名向我說實話呢？」","notes":[]},{"n":16,"t":"米該雅說：「我看見以色列眾人散佈在山上，如同沒有牧人的羊群一般。耶和華說：『這些人沒有主人，他們可以平安地各自回家去。』」","notes":[]},{"n":17,"t":"以色列王對約沙法說：「我豈沒有告訴你，這人對我說預言，從不說吉言，只說凶信嗎？」","notes":[]},{"n":18,"t":"米該雅說：「因此你們要聽耶和華的話！我看見耶和華坐在寶座上，天上的萬軍侍立在他左右。","notes":[]},{"n":19,"t":"耶和華說：『誰去引誘以色列王亞哈上基列的拉末去陣亡呢？』這個這樣說，那個那樣說。","notes":[]},{"n":20,"t":"隨後有一個靈出來，站在耶和華面前，說：『我去引誘他。』耶和華問他：『用甚麼方法呢？』","notes":[]},{"n":21,"t":"他說：『我要出去，在他眾先知的口中成為謊言的靈。』耶和華說：『這樣，你去引誘他，必能成功。你出去，照樣做吧！』","notes":[]},{"n":22,"t":"現在，看哪，耶和華使謊言的靈入了你的這些先知的口，並且耶和華已經宣告要降禍於你。」","notes":[]},{"n":23,"t":"基拿拿的兒子西底家前來打米該雅一巴掌，說：「耶和華的靈從哪裏離開我向你說話呢？」","notes":[]},{"n":24,"t":"米該雅說：「看哪，你進入嚴密的內室躲藏的那日，就必看見。」","notes":[]},{"n":25,"t":"以色列王說：「把米該雅帶走，交回給亞們市長和約阿施王子。","notes":[]},{"n":26,"t":"你們要說：『王如此說：把這個人關在監獄裏，使他受苦，吃不飽喝不足，直等到我平安回來。』」","notes":[]},{"n":27,"t":"米該雅說：「你若真的能平安回來，那就是耶和華沒有藉我說話了。」他又說：「眾百姓啊，你們都要聽！」","notes":[]},{"n":28,"t":"以色列王和猶大王約沙法上基列的拉末去。","notes":[],"heads":["亞哈陣亡"]},{"n":29,"t":"以色列王對約沙法說：「我要改裝上陣，你可以仍穿王服。」於是以色列王改裝，他們上陣去了。","notes":[]},{"n":30,"t":"亞蘭王吩咐他的戰車長說：「你們不要與他們的大將或小兵交戰，只要單單攻擊以色列王。」","notes":[]},{"n":31,"t":"那些戰車長看見約沙法就說：「這一定是以色列王！」他們轉過去與他交戰。約沙法一呼喊，耶和華就幫助他，神使他們轉離他。","notes":[]},{"n":32,"t":"戰車長見他不是以色列王，就轉身不追他了。","notes":[]},{"n":33,"t":"有一人開弓，並不知情，箭恰巧射入以色列王鎧甲的縫裏。王對駕車的說：「我受重傷了，你掉過車來，載我離開戰場！」","notes":[]},{"n":34,"t":"那日，戰況越來越猛，以色列王勉強站在戰車上，面對亞蘭人，直到傍晚。日落的時候，王就死了。","notes":[]}]},"19":{"heading":"先知斥責約沙法","verses":[{"n":1,"t":"猶大王約沙法平安回耶路撒冷，到自己的宮裏。","notes":[]},{"n":2,"t":"哈拿尼的兒子耶戶先見出來迎接約沙法王，對他說：「你怎麼可以幫助惡人，愛那恨耶和華的人呢？因此耶和華的憤怒臨到你了。","notes":[]},{"n":3,"t":"然而你還有善行，因你從國中除掉亞舍拉，立定心意尋求神。」","notes":[]},{"n":4,"t":"約沙法住在耶路撒冷，以後又出巡民間，從別是巴直到以法蓮山區，引導百姓歸向耶和華－他們列祖的神。","notes":[],"heads":["約沙法的改革"]},{"n":5,"t":"他在國中，在猶大一切堅固城設立審判官，各城都是如此。","notes":[]},{"n":6,"t":"他對審判官說：「你們應當謹慎所做的事，因為你們審判不是為人，而是為耶和華。在審判的事上，他必與你們同在。","notes":[]},{"n":7,"t":"現在，你們應當敬畏耶和華，謹慎辦事，因為耶和華－我們的神沒有不義，不看人的情面，也不受賄賂。」","notes":[]},{"n":8,"t":"約沙法從利未人和祭司，以及以色列族長中，也委派人在耶路撒冷為耶和華施行審判，為耶路撒冷的居民聽訟斷案。","notes":["「為耶路撒冷的居民聽訟斷案」是根據七十士譯本；原文是「聽訟斷案。他們就回耶路撒冷去了」。"]},{"n":9,"t":"約沙法吩咐他們說：「你們當這樣，以敬畏耶和華、誠實和純正的心辦事。","notes":[]},{"n":10,"t":"你們住在各城的弟兄，若有爭訟的案件呈到你們這裏，或為流血，或犯律法、誡命、律例、典章，你們要警戒他們，免得他們得罪耶和華，以致憤怒臨到你們和你們的弟兄；你們當這樣行，就沒有罪了。","notes":[]},{"n":11,"t":"看哪，凡屬耶和華的事，有亞瑪利雅祭司長管理你們；凡屬王的事，有猶大家的領袖以實瑪利的兒子西巴第雅管理你們；在你們面前有利未人作官長。你們應當壯膽辦事，願耶和華與善人同在。」","notes":[]}]},"20":{"heading":"與以東交戰","verses":[{"n":1,"t":"此後，摩押人和亞捫人，連同一些米烏尼人來攻擊約沙法。","notes":["「一些米烏尼人」是根據七十士譯本；原文是「亞捫人」。"]},{"n":2,"t":"有人來報告約沙法說：「從海的那邊，以東有大軍來攻擊你，看哪，他們在哈洗遜‧他瑪，就是隱‧基底。」","notes":["「以東」是根據一些古卷和其他古譯本；原文是「亞蘭」。"]},{"n":3,"t":"約沙法懼怕，就定意尋求耶和華，在全猶大宣告禁食。","notes":[]},{"n":4,"t":"於是猶大人聚集，求耶和華幫助，甚至他們從猶大各城前來尋求耶和華。","notes":[]},{"n":5,"t":"約沙法站在猶大和耶路撒冷的會眾中，在耶和華殿新的院子前，","notes":[]},{"n":6,"t":"說：「耶和華－我們列祖的神啊，你不是天上的神嗎？你不是萬邦萬國的主宰嗎？在你手中有大能大力，無人能抵擋你。","notes":[]},{"n":7,"t":"我們的神啊，你不是曾在你百姓以色列面前驅逐這地的居民，將這地賜給你朋友亞伯拉罕的後裔永遠為業嗎？","notes":[]},{"n":8,"t":"他們住在這地，又為你的名建造聖所，說：","notes":[]},{"n":9,"t":"『若有禍患臨到我們，或刀兵的懲罰，或瘟疫饑荒，我們在急難的時候，站在這殿前向你呼求，你必垂聽並且拯救，因為你的名在這殿裏。』","notes":[]},{"n":10,"t":"現在，看哪，以色列人出埃及地的時候，你不容許以色列人侵犯亞捫人、摩押人和西珥山人，以色列人就離開他們，不滅絕他們。","notes":[]},{"n":11,"t":"看哪，他們這樣回報我們，要來驅逐我們離開你賜給我們為業之地。","notes":[]},{"n":12,"t":"我們的神啊，你不懲罰他們嗎？因為我們無力抵擋這來攻擊我們的大軍。我們不知道該怎麼做，我們的眼目單仰望你。」","notes":[]},{"n":13,"t":"猶大眾人和他們的孩童、妻子、兒女都站在耶和華面前。","notes":[]},{"n":14,"t":"那時，耶和華的靈在會眾中臨到利未人亞薩的後裔雅哈悉，他是瑪探雅的玄孫，耶利的曾孫，比拿雅的孫子，撒迦利雅的兒子。","notes":[]},{"n":15,"t":"他說：「猶大眾人、耶路撒冷的居民和約沙法王啊，你們要留心聽，耶和華對你們如此說：『不要因這大軍恐懼驚惶，因為勝敗不在乎你們，而是在乎神。","notes":[]},{"n":16,"t":"明日你們要下去迎敵；看哪，他們從洗斯坡上來，你們必在耶魯伊勒曠野前的谷口遇見他們。","notes":[]},{"n":17,"t":"猶大和耶路撒冷人哪，這次你們不要爭戰，要擺陣站著，看耶和華為你們施行拯救。不要恐懼，也不要驚惶。明日當出去迎敵，因為耶和華與你們同在。』」","notes":[]},{"n":18,"t":"約沙法屈身，臉伏於地，猶大眾人和耶路撒冷的居民也俯伏在耶和華面前，敬拜耶和華。","notes":[]},{"n":19,"t":"哥轄子孫和可拉子孫的利未人都起來，用極大的聲音讚美耶和華－以色列的神。","notes":[]},{"n":20,"t":"清晨，眾人早起往提哥亞的曠野去。出去的時候，約沙法站著說：「猶大人和耶路撒冷的居民哪，要聽我說：信靠耶和華－你們的神就必站立得穩；信賴他的先知就必亨通。」","notes":[]},{"n":21,"t":"約沙法與百姓商議，就設立歌唱的人，頌讚耶和華，使他們穿上聖潔的禮服，走在軍隊前讚美耶和華：「當稱謝耶和華，因他的慈愛永遠長存！」","notes":[]},{"n":22,"t":"他們開始唱歌讚美的時候，耶和華派伏兵擊殺那來攻擊猶大的亞捫人、摩押人和西珥山人，他們就被打敗了。","notes":[]},{"n":23,"t":"亞捫人和摩押人起來，擊殺住西珥山的人，把他們滅盡；滅盡住西珥山的人之後，他們又彼此自相擊殺。","notes":[]},{"n":24,"t":"猶大人來到曠野的瞭望樓，向那大軍觀看，看哪，遍地都是屍體，沒有一個逃脫的。","notes":[]},{"n":25,"t":"約沙法和他的百姓就來收取掠物，找到許多牲畜、財物、衣服和珍寶。他們取掠物歸為己有，直到無法攜帶；因為掠物太多，他們足足收取了三日。","notes":["「找到許多牲畜」是根據七十士譯本；原文是「在他們當中找到」。","「衣服」是根據一些古卷和其他古譯本；原文是「屍體」。"]},{"n":26,"t":"第四日，眾人聚集在比拉迦谷，在那裏稱頌耶和華；因此那地方名叫比拉迦谷，直到今日。","notes":["「比拉迦」意思是「稱頌」。"]},{"n":27,"t":"在約沙法率領下，猶大人和耶路撒冷人都歡歡喜喜地回耶路撒冷，耶和華使他們因戰勝仇敵而喜樂。","notes":[]},{"n":28,"t":"他們彈琴、鼓瑟、吹號來到耶路撒冷，進了耶和華的殿。","notes":[]},{"n":29,"t":"地上所有的邦國聽見耶和華打敗以色列的仇敵，就都懼怕神。","notes":[]},{"n":30,"t":"這樣，約沙法的國得享太平，因為神賜他四境平安。","notes":[]},{"n":31,"t":"約沙法作猶大王，登基的時候年三十五歲，在耶路撒冷作王二十五年。他母親名叫阿蘇巴，是示利希的女兒。","notes":[],"heads":["約沙法逝世"]},{"n":32,"t":"約沙法效法他父親亞撒所行的道，不偏離左右，行耶和華眼中看為正的事。","notes":[]},{"n":33,"t":"只是丘壇還沒有廢去，百姓也沒有立定心意歸向他們列祖的神。","notes":[]},{"n":34,"t":"約沙法其餘的事，看哪，自始至終都寫在哈拿尼的兒子耶戶的書上，這些事也記載在《以色列諸王記》上。","notes":[]},{"n":35,"t":"此後，猶大王約沙法與以色列王亞哈謝結盟；亞哈謝多行惡事。","notes":[]},{"n":36,"t":"他們合夥造船要往他施去，就在以旬‧迦別造船。","notes":[]},{"n":37,"t":"瑪利沙人多大瓦的兒子以利以謝向約沙法預言說：「因你與亞哈謝結盟，耶和華必破壞你所造的。」後來那些船果然毀壞，不能往他施去了。","notes":[]}]},"21":{"heading":"猶大王約蘭","verses":[{"n":1,"t":"約沙法與他祖先同睡，與他祖先同葬在大衛城，他的兒子約蘭接續他作王。","notes":[]},{"n":2,"t":"約蘭有幾個兄弟，就是約沙法的兒子亞撒利雅、耶歇、撒迦利雅、亞撒列夫、米迦勒、示法提雅；這些都是以色列王約沙法的兒子。","notes":["「以色列」：有許多古卷、七十士譯本和其他古譯本是「猶大」。"]},{"n":3,"t":"他們的父親把許多禮物，金銀財寶和猶大的堅固城賜給他們，卻把國賜給約蘭，因為他是長子。","notes":[]},{"n":4,"t":"約蘭起來治理他父親的國，奮勇自強，用刀殺了他所有的兄弟和以色列的幾個領袖。","notes":[]},{"n":5,"t":"約蘭登基的時候年三十二歲，在耶路撒冷作王八年。","notes":[]},{"n":6,"t":"他行以色列諸王的道，正如亞哈家所行的，因他娶了亞哈的女兒為妻，行耶和華眼中看為惡的事。","notes":[]},{"n":7,"t":"耶和華卻因自己與大衛所立的約，不肯滅絕大衛的家，要照他所應許的，永遠賜燈光給大衛和他的子孫。","notes":[]},{"n":8,"t":"約蘭在位期間，以東背叛，自己立王治理他們，脫離猶大的權勢。","notes":[]},{"n":9,"t":"約蘭就率領他的軍官和所有的戰車過去。他夜間起來，攻打圍困他的以東人和戰車長。","notes":[]},{"n":10,"t":"這樣，以東背叛，脫離猶大的權勢，直到今日。那時，立拿也背叛了，脫離它的權勢，因為約蘭離棄耶和華－他列祖的神。","notes":[]},{"n":11,"t":"他又在猶大山嶺建造丘壇，使耶路撒冷的居民行淫，誘惑猶大。","notes":["「山嶺」：有許多古卷、七十士譯本和其他古譯本是「城鎮」。"]},{"n":12,"t":"以利亞先知寫信給約蘭說：「耶和華－你祖先大衛的神如此說：『因為你不行你父約沙法和猶大王亞撒的道，","notes":[]},{"n":13,"t":"反而行以色列諸王的道，使猶大和耶路撒冷居民行淫，像亞哈家行淫一樣，又殺了你父家比你好的那些兄弟。","notes":[]},{"n":14,"t":"看哪，耶和華必降大災於你的百姓和你的妻妾、兒女，以及你一切所有的。","notes":[]},{"n":15,"t":"至於你，你必患許多的病，你的腸子也必生病，日漸沉重，直到腸子墜落下來。』」","notes":["「許多的病」：有些古卷、七十士譯本和其他古譯本是「嚴重的病」。"]},{"n":16,"t":"耶和華激發非利士人和靠近古實人的阿拉伯人的心來攻擊約蘭。","notes":[]},{"n":17,"t":"他們上來攻擊猶大，侵入境內，擄掠了王宮裏所有的財物和他的妻妾、兒女，除了他的小兒子約哈斯之外，沒有留下一個兒子。","notes":["「約哈斯」：七十士譯本是「亞哈謝」；參代下22章。"]},{"n":18,"t":"這一切事以後，耶和華擊打約蘭，使他的腸子患不能醫治的病。","notes":[]},{"n":19,"t":"這病纏綿日久，過了二年，腸子墜落下來，他就病重而死。他的百姓沒有為他生火誌哀，像從前為他祖先生火一樣。","notes":[]},{"n":20,"t":"約蘭登基的時候年三十二歲，在耶路撒冷作王八年。他逝世無人思慕，眾人把他葬在大衛城，只是不在列王的墳墓裏。","notes":[]}]},"22":{"heading":"猶大王亞哈謝","verses":[{"n":1,"t":"耶路撒冷的居民立約蘭的小兒子亞哈謝接續他作王，因為跟隨阿拉伯人來攻營的軍兵把亞哈謝所有的兄長都殺了；猶大王約蘭的兒子亞哈謝就作了王。","notes":[]},{"n":2,"t":"亞哈謝登基的時候年四十二歲，在耶路撒冷作王一年。他母親名叫亞她利雅，是暗利的孫女。","notes":["「四十二歲」：王下8．26是「二十二歲」。"]},{"n":3,"t":"亞哈謝也行亞哈家的道，因為他母親給他主謀，使他行惡。","notes":[]},{"n":4,"t":"他行耶和華眼中看為惡的事，像亞哈家一樣；因他父親死後，他們給他主謀，使他敗壞。","notes":[]},{"n":5,"t":"他也聽從他們的計謀，與以色列王亞哈的兒子約蘭同往基列的拉末去，與亞蘭王哈薛交戰。亞蘭人打傷了約蘭，","notes":[]},{"n":6,"t":"他回到耶斯列，醫治在拉末與亞蘭王哈薛打仗時被擊打所受的傷。約蘭的兒子猶大王亞哈謝因為亞哈的兒子約蘭病了，就下到耶斯列看望他。","notes":["「拉末」是根據七十士譯本；原文是「拉瑪」，可能是「基列的拉末」的簡稱。","「亞哈謝」是根據一些古卷、七十士譯本和其他古譯本；原文是「亞撒利雅」。"]},{"n":7,"t":"亞哈謝去見約蘭而遇害，這是出乎神；因為他一到就同約蘭出去攻擊寧示的孫子耶戶；這耶戶是耶和華所膏，使他剪除亞哈家的。","notes":[]},{"n":8,"t":"耶戶向亞哈家施行懲罰的時候，遇見猶大的眾領袖和亞哈謝的姪子們正服事亞哈謝，就把他們都殺了。","notes":[]},{"n":9,"t":"亞哈謝躲在撒瑪利亞，耶戶尋找他，眾人把他拿住，送到耶戶那裏，就殺了他。他們把他埋葬，因他們說，他是那盡心尋求耶和華之約沙法的兒子。這樣，亞哈謝的家無力保住國權。","notes":[]},{"n":10,"t":"亞哈謝的母親亞她利雅見她兒子死了，就起來剿滅猶大王室所有的後裔。","notes":[],"heads":["亞她利雅篡位"]},{"n":11,"t":"但王的女兒約示巴將亞哈謝的兒子約阿施從那被殺的王子中偷出來，把他和他的奶媽藏在臥房裏。約示巴是約蘭王的女兒，亞哈謝的妹妹，祭司耶何耶大的妻子。她藏了約阿施，躲避亞她利雅，免受殺害。","notes":[]},{"n":12,"t":"亞她利雅治理這地的時候，約阿施和他們一同在神殿裏藏了六年。","notes":[]}]},"23":{"heading":"推翻亞她利雅","verses":[{"n":1,"t":"第七年，耶何耶大奮勇自強，叫了耶羅罕的兒子亞撒利雅、約哈難的兒子以實瑪利、俄備得的兒子亞撒利雅、亞大雅的兒子瑪西雅，和細基利的兒子以利沙法等眾百夫長，與他們立約。","notes":[]},{"n":2,"t":"他們走遍猶大，從猶大各城召集利未人和以色列的眾族長到耶路撒冷來。","notes":[]},{"n":3,"t":"全會眾在神殿裏與王立約。耶何耶大對他們說：「看哪，王的兒子必作王，正如耶和華指著大衛子孫所應許的。","notes":[]},{"n":4,"t":"你們要這樣做：在安息日值班的祭司和利未人，三分之一要把守各門，","notes":[]},{"n":5,"t":"三分之一要在王宮，三分之一要在根基門；眾百姓都要在耶和華殿的院內。","notes":[]},{"n":6,"t":"除了祭司和供職的利未人之外，不准別人進耶和華的殿；只有他們可以進去，因為他們是神聖的。眾百姓都要遵守耶和華所吩咐的。","notes":[]},{"n":7,"t":"利未人要手中各拿兵器，四圍保護王；凡擅自進殿的，要被處死。王出入的時候，你們當跟隨他。」","notes":[]},{"n":8,"t":"利未人和猶大眾人都照著耶何耶大祭司一切所吩咐的去做，各帶自己的人，無論安息日值班或不值班的都來，因為耶何耶大祭司不許他們下班。","notes":[]},{"n":9,"t":"耶何耶大祭司就把神殿裏所藏大衛王的槍和大小盾牌交給百夫長，","notes":[]},{"n":10,"t":"又分派眾百姓手中各拿兵器，在祭壇和殿那裏，從殿南到殿北，站在王的四圍；","notes":[]},{"n":11,"t":"他們領約阿施 出來，給他戴上冠冕，把律法書交給他，立他作王。耶何耶大和他的兒子們膏他，他們說：「願王萬歲！」","notes":["「約阿施」：原文是「王的兒子」。"]},{"n":12,"t":"亞她利雅聽見百姓奔走讚美王的聲音，就進耶和華的殿，到百姓那裏。","notes":[]},{"n":13,"t":"她觀看，看哪，王站在殿門的柱旁，百夫長和號手在王旁邊，國中的眾百姓都歡樂吹號，又有歌唱的人用樂器領人歌唱讚美。亞她利雅就撕裂衣服，喊著說：「反了！反了！」","notes":[]},{"n":14,"t":"耶何耶大祭司帶領管軍兵的百夫長出來，對他們說：「把她從行列之間趕出去，凡跟隨她的必用刀殺死！」因為祭司說：「不可在耶和華殿裏殺她。」","notes":[]},{"n":15,"t":"他們就下手拿住她；她進入通往王宮的馬門，他們就在那裏把她殺了。","notes":[]},{"n":16,"t":"耶何耶大與眾百姓，又與王立約，要作耶和華的子民。","notes":[],"heads":["耶何耶大的改革"]},{"n":17,"t":"於是眾百姓到巴力廟去，拆毀了廟，打碎祭壇和偶像，又在壇前把巴力的祭司瑪坦殺了。","notes":[]},{"n":18,"t":"耶何耶大派官員在利未家的祭司手下看守耶和華的殿，他們是大衛所分派的，在耶和華殿中照摩西律法上所寫，獻燔祭給耶和華，又按大衛所定的，歡樂歌唱。","notes":[]},{"n":19,"t":"耶何耶大又設立守衛把守耶和華殿的各門，無論因何事而不潔淨的人，都不准進去。","notes":[]},{"n":20,"t":"他又率領百夫長和貴族，與民間的官長，以及國中的眾百姓，請王從耶和華的殿下來，由上門正中進入王宮，使王坐在國度的王位上。","notes":[]},{"n":21,"t":"國中的眾百姓都歡樂，合城也都平靜。他們已將亞她利雅用刀殺了。","notes":[]}]},"24":{"heading":"猶大王約阿施","verses":[{"n":1,"t":"約阿施登基的時候年方七歲，在耶路撒冷作王四十年。他母親名叫西比亞，是別是巴人。","notes":[]},{"n":2,"t":"耶何耶大祭司在世的日子，約阿施行耶和華眼中看為正的事。","notes":[]},{"n":3,"t":"耶何耶大為他娶了兩個妻子，他生兒育女。","notes":[]},{"n":4,"t":"此後，約阿施有心重修耶和華的殿，","notes":[]},{"n":5,"t":"就召集祭司和利未人，吩咐他們說：「你們要往猶大各城去，向以色列眾人徵收銀子，按每年的需要整修你們神的殿；你們要急速辦理這事。」但利未人沒有急速辦理。","notes":[]},{"n":6,"t":"王召了耶何耶大祭司長來，對他說：「從前耶和華的僕人摩西，為法櫃的帳幕與以色列會眾所定的捐獻，你為何不叫利未人照這例向猶大和耶路撒冷徵收呢？」","notes":[]},{"n":7,"t":"因為那惡婦亞她利雅的兒子們曾拆毀神的殿，又用耶和華殿中分別為聖的物供奉諸巴力。","notes":[]},{"n":8,"t":"於是王下令造一個櫃子，放在耶和華殿的門外，","notes":[]},{"n":9,"t":"又通告猶大和耶路撒冷，要將神僕人摩西在曠野所吩咐以色列的捐獻送來給耶和華。","notes":[]},{"n":10,"t":"眾領袖和百姓都歡歡喜喜帶捐獻來，投入櫃中，直到投滿。","notes":[]},{"n":11,"t":"利未人見銀子多了，把櫃子抬到王所派的官長面前；這時王的書記和祭司長的助手就會來把櫃子倒空，然後放回原處。日日都是這樣做，積蓄的銀子很多。","notes":[]},{"n":12,"t":"王與耶何耶大把銀子交給耶和華殿裏辦事的人，他們就雇了石匠、木匠重修耶和華的殿，又雇了鐵匠、銅匠整修耶和華的殿。","notes":[]},{"n":13,"t":"工人做工，修理工程在他們手中漸漸完成，他們將神的殿修理得如同從前一樣，非常堅固。","notes":[]},{"n":14,"t":"他們做完了，就把多餘的銀子拿到王與耶何耶大面前，用以製造耶和華殿供奉所用的器皿和調羹，以及金銀的器皿。耶何耶大在世的日子，眾人經常在耶和華殿裏獻燔祭。","notes":[]},{"n":15,"t":"耶何耶大年紀老邁，日子滿足而死，死的時候年一百三十歲。","notes":[]},{"n":16,"t":"眾人把他與列王同葬在大衛城，因為他在以色列中為神和他的殿做了美善的事。","notes":[]},{"n":17,"t":"耶何耶大死後，猶大的眾領袖來叩拜王，那時王就聽了他們。","notes":[]},{"n":18,"t":"他們離棄耶和華－他們列祖神的殿，去事奉亞舍拉和偶像；因他們這罪，就有憤怒臨到猶大和耶路撒冷。","notes":[]},{"n":19,"t":"但神仍差遣先知到他們那裏，引導他們歸向耶和華。先知警戒他們，他們卻不肯聽。","notes":[]},{"n":20,"t":"那時，神的靈感動耶何耶大的兒子撒迦利亞祭司，他就站在上面，對百姓說：「神如此說：『你們為何干犯耶和華的誡命，以致不得亨通呢？因為你們離棄耶和華，所以他也離棄你們。』」","notes":[]},{"n":21,"t":"眾人謀害撒迦利亞，照著王的吩咐，在耶和華殿的院內用石頭打死他。","notes":[]},{"n":22,"t":"這樣，約阿施王不記念撒迦利亞的父親耶何耶大向自己所施的恩，殺了他的兒子。撒迦利亞臨死的時候說：「願耶和華鑒察伸冤！」","notes":[]},{"n":23,"t":"年底的時候，亞蘭的軍兵上來攻擊約阿施，來到猶大和耶路撒冷，殺了百姓中的眾領袖，把所掠取的財物全送到大馬士革王那裏。","notes":[],"heads":["約阿施被殺"]},{"n":24,"t":"亞蘭的軍兵雖只來了一小隊人，耶和華卻將極大的軍隊交在他們手裏；因為猶大人離棄耶和華－他們列祖的神，所以亞蘭人懲罰約阿施。","notes":[]},{"n":25,"t":"亞蘭人離開約阿施的時候，他患重病；他的臣僕背叛他，要報耶何耶大祭司兒子的流血之仇，在床上殺了他。他就死了，葬在大衛城，只是不葬在列王的墳墓裏。","notes":["「他患重病」或譯「他受了重傷」。","「兒子」是根據七十士譯本和其他古譯本；原文是「兒子們」。"]},{"n":26,"t":"背叛他的是亞捫婦人示米押的兒子撒拔和摩押婦人示米利的兒子約薩拔。","notes":[]},{"n":27,"t":"至於他的兒子們和他所受的眾多警戒，以及他重修神殿的事，看哪，都寫在《列王評傳》上。他的兒子亞瑪謝接續他作王。","notes":[]}]},"25":{"heading":"猶大王亞瑪謝","verses":[{"n":1,"t":"亞瑪謝登基的時候年二十五歲，在耶路撒冷作王二十九年。他母親名叫約耶但，是耶路撒冷人。","notes":[]},{"n":2,"t":"亞瑪謝行耶和華眼中看為正的事，只是沒有純正的心。","notes":[]},{"n":3,"t":"他的王國一鞏固，就把殺他父王的臣僕殺了，","notes":[]},{"n":4,"t":"卻沒有處死他們的兒子，這是照摩西律法書上耶和華所吩咐的說：「不可因子殺父，也不可因父殺子，各人要為自己的罪而死。」","notes":[]},{"n":5,"t":"亞瑪謝召集猶大人，按著父家為全猶大和便雅憫設立千夫長、百夫長，又數點人數，從二十歲以上，能拿槍拿盾牌出去打仗的精兵共有三十萬；","notes":[],"heads":["與以東交戰"]},{"n":6,"t":"又用一百他連得銀子，從以色列招募了十萬大能的勇士。","notes":[]},{"n":7,"t":"有一個神人來見亞瑪謝，對他說：「王啊，不要帶領以色列的軍兵與你同去，因為耶和華不和以色列，和任何以法蓮的子孫同在。","notes":[]},{"n":8,"t":"你若一定要去，就奮勇作戰吧！但神必使你敗在敵人面前，因為神能助人得勝，也能使人落敗。」","notes":[]},{"n":9,"t":"亞瑪謝問神人：「我給了以色列軍隊的那一百他連得銀子怎麼樣呢？」神人回答：「耶和華會把比這些更多的賜給你。」","notes":[]},{"n":10,"t":"於是亞瑪謝把那從以法蓮來的軍兵分別出來，叫他們到自己的地方去。他們非常惱怒猶大，氣憤地回自己的地方去了。","notes":[]},{"n":11,"t":"亞瑪謝壯起膽來，率領他的軍隊到鹽谷，殺了一萬西珥人。","notes":[]},{"n":12,"t":"猶大人又生擒了一萬人，把他們帶到西拉山頂上，從西拉山頂扔下去，把他們全都摔碎了。","notes":[]},{"n":13,"t":"但亞瑪謝所打發回去、不許一同出征的那些軍兵劫掠猶大各城，從撒瑪利亞直到伯‧和崙，殺了三千人，搶了許多財物。","notes":[]},{"n":14,"t":"亞瑪謝擊殺以東人回來以後，他把西珥人的神像帶回，立為自己的神明，在它們面前叩拜燒香。","notes":[]},{"n":15,"t":"耶和華的怒氣向亞瑪謝發作，差派一個先知去見他，對他說：「這些神明不能救自己的百姓脫離你的手，你為何尋求它們呢？」","notes":[]},{"n":16,"t":"先知與王說話的時候，王對他說：「難道我們立你作王的謀士嗎？你住口吧！為何要挨打呢？」先知就止住了，卻說：「我知道神已定意要消滅你，因為你行這事，不聽從我的勸戒。」","notes":[]},{"n":17,"t":"猶大王亞瑪謝經商議後，就派人去見耶戶的孫子，約哈斯的兒子以色列王約阿施，說：「來，讓我們面對面較量吧！」","notes":[],"heads":["與以色列爭戰"]},{"n":18,"t":"以色列王約阿施派人去見猶大王亞瑪謝，說：「黎巴嫩的蒺藜派人去見黎巴嫩的香柏樹，說：『將你的女兒嫁給我的兒子。』但有一隻野獸經過黎巴嫩，把蒺藜踐踏了。","notes":[]},{"n":19,"t":"你說，看哪，你打敗了以東，就心高氣傲，以此為榮。現在，你待在家裏算了吧，為何要惹禍使自己和猶大一同敗亡呢？」","notes":[]},{"n":20,"t":"亞瑪謝卻不肯聽從。這是出乎神，好將他們交在敵人手裏，因為他們尋求以東的神明。","notes":[]},{"n":21,"t":"於是以色列王約阿施上來，在猶大的伯‧示麥與猶大王亞瑪謝面對面較量。","notes":[]},{"n":22,"t":"猶大敗在以色列面前，他們逃跑，各人逃回自己的帳棚去了。","notes":[]},{"n":23,"t":"以色列王約阿施在伯‧示麥擒住約哈斯的孫子，約阿施的兒子猶大王亞瑪謝，把他帶到耶路撒冷，又拆毀耶路撒冷的城牆，從以法蓮門直到角門共四百肘。","notes":["「約哈斯」就是「亞哈謝」；參王下14．13。"]},{"n":24,"t":"他帶著俄別‧以東所看守神殿裏的一切金銀和器皿，與王宮裏的財寶，又帶著人質，回撒瑪利亞去了。","notes":[]},{"n":25,"t":"約哈斯的兒子以色列王約阿施死後，猶大王約阿施的兒子亞瑪謝又活了十五年。","notes":[]},{"n":26,"t":"亞瑪謝其餘的事，自始至終，看哪，不都寫在《猶大和以色列諸王記》上嗎？","notes":[]},{"n":27,"t":"自從亞瑪謝離棄耶和華之後，在耶路撒冷有人背叛他，他就逃往拉吉；他們卻派人追到拉吉，在那裏殺了他。","notes":[]},{"n":28,"t":"有人用馬將他馱回，把他與祖先一同葬在猶大的城。","notes":["「猶大的城」：有古卷和七十士譯本是「大衛城」；參王下14．20。"]}]},"26":{"heading":"猶大王烏西雅","verses":[{"n":1,"t":"猶大眾百姓立烏西雅接續他父親亞瑪謝作王，那時他年十六歲。","notes":["「烏西雅」又名「亞撒利雅」；參王下14．21。"]},{"n":2,"t":"亞瑪謝王與他祖先同睡之後，烏西雅收復以祿回歸猶大，又重新修建。","notes":[]},{"n":3,"t":"烏西雅登基的時候年十六歲，在耶路撒冷作王五十二年。他母親名叫耶可利雅，是耶路撒冷人。","notes":[]},{"n":4,"t":"烏西雅行耶和華眼中看為正的事，效法他父親亞瑪謝一切所行的。","notes":[]},{"n":5,"t":"撒迦利亞是一個通曉神默示的人，他在世的日子，烏西雅定意尋求神；烏西雅尋求耶和華的日子，神使他亨通。","notes":["「通曉神默示的人」：有古卷和七十士譯本是「教導人敬畏神的人」。"]},{"n":6,"t":"他出去攻擊非利士人，拆毀了迦特、雅比尼和亞實突的城牆，又在非利士人中，在亞實突境內建築城鎮。","notes":[]},{"n":7,"t":"神幫助他攻擊非利士人和住在姑珥‧巴力的阿拉伯人，以及米烏尼人。","notes":[]},{"n":8,"t":"米烏尼人向烏西雅進貢。他的名聲傳到埃及，因他非常強盛。","notes":["「米烏尼人」是根據七十士譯本；原文是「亞捫人」。"]},{"n":9,"t":"烏西雅在耶路撒冷的角門和谷門，以及城牆轉角之處建築城樓，非常堅固。","notes":[]},{"n":10,"t":"他在曠野建築瞭望樓，又挖了許多井，因為他在謝非拉和平原有很多牲畜。他在山區和肥沃的土地雇用耕種田地和修整葡萄園的人，因為他喜愛土地。","notes":[]},{"n":11,"t":"烏西雅又有軍兵，照書記耶利和官長瑪西雅所數點的，在王的一個將軍哈拿尼雅手下，分隊出戰。","notes":[]},{"n":12,"t":"族長和大能勇士的總數共二千六百人，","notes":[]},{"n":13,"t":"他們手下的軍兵共三十萬七千五百人，都大有能力，善於作戰，幫助王攻擊仇敵。","notes":[]},{"n":14,"t":"烏西雅為全軍預備盾牌、頭盔、鎧甲、槍、弓和甩石的機弦，","notes":[]},{"n":15,"t":"又在耶路撒冷叫巧匠設計機器，安在城樓和角樓上，用以射箭，投擲大石。烏西雅的名聲傳到遠方，因為他得了非凡的幫助，極其強盛。","notes":[]},{"n":16,"t":"烏西雅既強盛，就心高氣傲，以致敗壞。他干犯耶和華－他的神，進耶和華的殿，要在香壇上燒香。","notes":[],"heads":["烏西雅因驕傲受懲"]},{"n":17,"t":"亞撒利雅祭司率領八十名勇敢的耶和華的祭司，跟隨他進去。","notes":[]},{"n":18,"t":"他們阻止烏西雅王，對他說：「烏西雅啊，給耶和華燒香不是你的事，而是亞倫子孫的事，他們是分別為聖來燒香的祭司。你出聖殿吧！因為你犯了罪，耶和華神必不使你得尊榮。」","notes":[]},{"n":19,"t":"烏西雅發怒，手拿香爐要燒香。他在耶和華殿中香壇旁向眾祭司發怒的時候，他的額頭在眾祭司面前忽然長出痲瘋。","notes":["「痲瘋」泛指傳染性皮膚病；下同。"]},{"n":20,"t":"亞撒利雅祭司長和眾祭司轉向他，看哪，他的額頭長出痲瘋，就催他離開那裏；他自己也急速出去，因為耶和華降災於他。","notes":[]},{"n":21,"t":"烏西雅王患痲瘋直到死的那日；他因為染上痲瘋，就住在隔離的行宮裏，與耶和華的殿隔絕。他兒子約坦管理王的家，治理這地的百姓。","notes":[]},{"n":22,"t":"烏西雅其餘的事，自始至終，亞摩斯的兒子以賽亞先知都記錄下來。","notes":[]},{"n":23,"t":"烏西雅與他祖先同睡，與他祖先同葬在田間的王陵；因為人說，他是長痲瘋的。他的兒子約坦接續他作王。","notes":[]}]},"27":{"heading":"猶大王約坦","verses":[{"n":1,"t":"約坦登基的時候年二十五歲，在耶路撒冷作王十六年。他母親名叫耶路沙，是撒督的女兒。","notes":[]},{"n":2,"t":"約坦行耶和華眼中看為正的事，效法他父親烏西雅一切所行的，只是他不入耶和華的殿。百姓仍舊行敗壞的事。","notes":[]},{"n":3,"t":"約坦建造耶和華殿的上門，在俄斐勒城牆上有很多建設，","notes":[]},{"n":4,"t":"又在猶大山區建造城鎮，在樹林中建築營寨和瞭望樓。","notes":[]},{"n":5,"t":"約坦與亞捫人的王打仗，勝了他們。那年亞捫人向他進貢一百他連得銀子，一萬歌珥小麥，一萬歌珥大麥；第二年、第三年亞捫人也這樣做。","notes":[]},{"n":6,"t":"約坦日漸強盛，因為他在耶和華－他神面前行正道。","notes":[]},{"n":7,"t":"約坦其餘的事和一切戰役，以及他的行為，看哪，都寫在《以色列和猶大列王記》上。","notes":[]},{"n":8,"t":"他登基的時候年二十五歲，在耶路撒冷作王十六年。","notes":[]},{"n":9,"t":"約坦與他祖先同睡，葬在大衛城，他兒子亞哈斯接續他作王。","notes":[]}]},"28":{"heading":"猶大王亞哈斯","verses":[{"n":1,"t":"亞哈斯登基的時候年二十歲，在耶路撒冷作王十六年。他不像他祖先大衛行耶和華眼中看為正的事，","notes":[]},{"n":2,"t":"卻行以色列諸王的道，又鑄造諸巴力的像，","notes":[]},{"n":3,"t":"照著耶和華從以色列人面前趕出的外邦人所行可憎的事，在欣嫩子谷燒香，用火焚燒他的兒女，","notes":[]},{"n":4,"t":"又在丘壇上、山岡上、各青翠樹下獻祭燒香。","notes":[]},{"n":5,"t":"耶和華－他的神將他交在亞蘭王手裏。亞蘭王打敗他，從他擄走了許多人，帶到大馬士革去。神又將他交在以色列王手裏，以色列王向他大行殺戮。","notes":[]},{"n":6,"t":"利瑪利的兒子比加一日之內在猶大殺了十二萬人，都是勇士，因為他們離棄了耶和華－他們列祖的神。","notes":[]},{"n":7,"t":"有一個叫細基利的以法蓮勇士，殺了瑪西雅王子、押斯利甘宮廷總管和以利加拿宰相。","notes":[]},{"n":8,"t":"以色列人擄了他們的弟兄，連婦人帶兒女共二十萬，又掠取了許多財物，把這些掠物帶到撒瑪利亞去。","notes":[],"heads":["先知俄德"]},{"n":9,"t":"但那裏有耶和華的一個先知，名叫俄德，出來迎接往撒瑪利亞去的軍兵，對他們說：「看哪，耶和華－你們列祖的神惱怒猶大人，將他們交在你們手裏，你們竟怒氣沖天，向他們大行殺戮。","notes":[]},{"n":10,"t":"如今你們又有意強逼猶大人和耶路撒冷人作你們的奴婢，你們豈不是也得罪了耶和華－你們的神嗎？","notes":[]},{"n":11,"t":"現在你們當聽我說，要將從你們弟兄中擄來的釋放回去，因耶和華的烈怒已臨到你們了。」","notes":[]},{"n":12,"t":"於是，以法蓮人的幾個領袖，就是約哈難的兒子亞撒利雅、米實利末的兒子比利家、沙龍的兒子耶希西家、哈得萊的兒子亞瑪撒，起來攔阻從戰場上回來的人，","notes":[]},{"n":13,"t":"對他們說：「你們不可把這些被擄的人帶到這裏，因我們已經得罪耶和華了。你們還想加增我們的罪惡過犯嗎？因為我們的罪過深重，已經有烈怒臨到以色列了。」","notes":[]},{"n":14,"t":"於是帶兵器的人將擄來的人口和掠取的財物都留在眾領袖和全會眾面前。","notes":[]},{"n":15,"t":"以上提名的那些人就起來，照顧被擄的人；其中凡赤身的，就從所掠取的財物中拿出衣服和鞋來，給他們穿，又給他們吃喝，用膏抹他們；其中凡軟弱的，就使他們騎驢，送到棕樹城耶利哥他們弟兄那裏。然後，他們就回撒瑪利亞去了。","notes":[]},{"n":16,"t":"那時，亞哈斯王派人去求亞述諸王來幫助他，","notes":["「諸王」：有古卷、七十士譯本和其他古譯本是「王」；參王下16．7。"],"heads":["亞哈斯向亞述王求援"]},{"n":17,"t":"因為以東人又來攻擊猶大，擄掠俘虜。","notes":[]},{"n":18,"t":"非利士人也來侵佔謝非拉和猶大的尼革夫的城鎮，攻取了伯‧示麥、亞雅崙、基低羅、梭哥和所屬的鄉鎮、亭拿和所屬的鄉鎮、瑾鎖和所屬的鄉鎮，就住在那裏。","notes":["「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」。"]},{"n":19,"t":"因為以色列王亞哈斯在猶大放肆，大大干犯耶和華，所以耶和華使猶大卑微。","notes":["「以色列」：有古卷、七十士譯本和其他古譯本是「猶大」。"]},{"n":20,"t":"亞述王提革拉‧毗列色來攻擊他，不幫助他，反倒欺負他。","notes":[]},{"n":21,"t":"亞哈斯從耶和華殿裏和王宮中，以及眾領袖家中取財寶送給亞述王，也無濟於事。","notes":[]},{"n":22,"t":"這亞哈斯王在急難的時候，越發得罪耶和華。","notes":[],"heads":["亞哈斯的罪行"]},{"n":23,"t":"他向那攻擊他的大馬士革的神明獻祭，說：「因為亞蘭王的神明幫助他們，我也要向這些神明獻祭，好讓它們幫助我。」但那些神明卻使他和全以色列敗亡。","notes":[]},{"n":24,"t":"亞哈斯聚集神殿裏的器皿，把神殿裏的器皿都打碎了，並且封鎖耶和華殿的門，又在耶路撒冷各處的轉角為自己建築祭壇。","notes":[]},{"n":25,"t":"他在猶大各城建立丘壇，向別神燒香，惹耶和華－他列祖的神發怒。","notes":[]},{"n":26,"t":"亞哈斯其餘的事和他一切的行為，自始至終，看哪，都寫在《猶大和以色列諸王記》上。","notes":[]},{"n":27,"t":"亞哈斯與他祖先同睡，葬在耶路撒冷城裏，卻沒有送入以色列諸王的墳墓。他的兒子希西家接續他作王。","notes":[]}]},"29":{"heading":"猶大王希西家","verses":[{"n":1,"t":"希西家登基的時候年二十五歲，在耶路撒冷作王二十九年。他母親名叫亞比雅，是撒迦利雅的女兒。","notes":["「亞比雅」：王下18．2稱「亞比」。"]},{"n":2,"t":"希西家行耶和華眼中看為正的事，效法他祖先大衛一切所行的。","notes":[]},{"n":3,"t":"元年正月，他開了耶和華殿的門，重新整修。","notes":[],"heads":["潔淨聖殿"]},{"n":4,"t":"他召祭司和利未人來，聚集在東邊的廣場，","notes":[]},{"n":5,"t":"對他們說：「利未人哪，當聽我說：現在你們要將自己分別為聖，又將耶和華－你們列祖神的殿分別為聖，從聖所中除去污穢之物。","notes":[]},{"n":6,"t":"因我們的祖先犯了罪，行耶和華－我們神眼中看為惡的事，離棄他，轉臉背向耶和華的居所。","notes":[]},{"n":7,"t":"他們又封鎖走廊的門，吹滅燈火，不在聖所中向以色列的神燒香，或獻燔祭。","notes":[]},{"n":8,"t":"耶和華的憤怒臨到猶大和耶路撒冷，使他們恐懼，令人驚駭，使人嗤笑，正如你們親眼所見的。","notes":[]},{"n":9,"t":"看哪，我們的祖宗倒在刀下，我們的妻子兒女也為此被擄掠。","notes":[]},{"n":10,"t":"現在我心中有意與耶和華－以色列的神立約，好使他的烈怒轉離我們。","notes":[]},{"n":11,"t":"我的眾子啊，現在不要懈怠；因為耶和華揀選你們站在他面前事奉他，作他的僕人，向他燒香。」","notes":[]},{"n":12,"t":"於是，利未人起來，當中有哥轄的子孫，亞瑪賽的兒子瑪哈、亞撒利雅的兒子約珥；米拉利的子孫，亞伯底的兒子基士、耶哈利勒的兒子亞撒利雅；革順人，薪瑪的兒子約亞、約亞的兒子伊甸；","notes":[]},{"n":13,"t":"以利撒反的子孫申利和耶利；亞薩的子孫，撒迦利雅和瑪探雅；","notes":[]},{"n":14,"t":"希幔的子孫耶歇和示每；耶杜頓的子孫示瑪雅和烏薛。","notes":[]},{"n":15,"t":"他們聚集他們的弟兄，將自己分別為聖，照著耶和華的話和王的吩咐，進去潔淨耶和華的殿。","notes":[]},{"n":16,"t":"祭司進入耶和華的內殿要潔淨殿，把耶和華殿中所發現一切污穢之物都搬出去，搬到耶和華殿的院子，由利未人接走，搬出去到外頭的汲淪溪。","notes":[]},{"n":17,"t":"從正月初一開始分別為聖，初八就來到耶和華殿的走廊。他們又用了八日使耶和華的殿分別為聖，到正月十六日才完成。","notes":[]},{"n":18,"t":"於是，他們到裏面去見希西家王，說：「我們已將耶和華的全殿和燔祭壇，以及壇的一切器皿、供餅的供桌，與供桌的一切器皿都潔淨了；","notes":[]},{"n":19,"t":"並且連亞哈斯王在位犯罪的時候所廢棄的器皿，我們也都預備齊全，分別為聖，看哪，它們都在耶和華的祭壇前。」","notes":[]},{"n":20,"t":"希西家王清早起來，召集城裏的領袖都上耶和華的殿。","notes":[],"heads":["重新奉獻聖殿"]},{"n":21,"t":"他們牽了七頭公牛、七隻公羊、七隻羔羊、七隻公山羊，要為國、為殿、為猶大作贖罪祭。王吩咐亞倫的子孫眾祭司在耶和華的壇上獻祭。","notes":[]},{"n":22,"t":"他們宰了公牛，祭司將血接來，灑在壇上；他們宰了公羊，把血灑在壇上，又宰了羔羊，也把血灑在壇上。","notes":[]},{"n":23,"t":"他們把那些作贖罪祭的公山羊牽到王和會眾面前，按手在公山羊上。","notes":[]},{"n":24,"t":"祭司宰了羊，將血獻在壇上作贖罪祭，為全以色列贖罪，因為王吩咐要為全以色列獻上燔祭和贖罪祭。","notes":[]},{"n":25,"t":"王又派利未人在耶和華殿中敲鈸，鼓瑟，彈琴，正如大衛和王的先見迦得，以及拿單先知所吩咐的，就是耶和華藉先知所吩咐的。","notes":[]},{"n":26,"t":"利未人拿大衛的樂器，祭司拿號，一同站立。","notes":[]},{"n":27,"t":"希西家吩咐在壇上獻燔祭，開始獻燔祭的時候，他們就唱讚美耶和華的歌，吹號，並用以色列王大衛的樂器伴奏。","notes":[]},{"n":28,"t":"全會眾都敬拜，歌唱的歌唱，吹號的吹號，如此直到燔祭獻完了。","notes":[]},{"n":29,"t":"獻完了祭，王和所有在場跟隨他的人都俯伏敬拜。","notes":[]},{"n":30,"t":"希西家王與眾領袖吩咐利未人用大衛和亞薩先見的詩詞頌讚耶和華，他們歡歡喜喜地頌讚，低頭敬拜。","notes":[]},{"n":31,"t":"希西家回應說：「如今你們既承接聖職歸耶和華，就要前來把祭物和感謝祭奉到耶和華的殿裏。」會眾就奉上祭物和感謝祭，凡甘心樂意的也奉上燔祭。","notes":[]},{"n":32,"t":"會眾所奉的燔祭數目如下：七十頭公牛、一百隻公羊、二百隻羔羊，這些全都是要作燔祭獻給耶和華的；","notes":[]},{"n":33,"t":"又有分別為聖之物，就是六百頭公牛、三千隻綿羊。","notes":[]},{"n":34,"t":"但祭司太少，不能剝盡所有燔祭牲的皮，所以他們的弟兄利未人幫助他們，直等獻祭的事完畢，直到其他的祭司也分別為聖了；因利未人以正直的心分別為聖，勝過祭司。","notes":[]},{"n":35,"t":"燔祭和平安祭牲的脂肪，以及與燔祭同獻的澆酒祭很多。這樣，耶和華殿中的事務俱都齊備了。","notes":[]},{"n":36,"t":"希西家和眾百姓都因神為百姓所預備的而喜樂，因為這事辦得很迅速。","notes":[]}]},"30":{"heading":"預備守逾越節","verses":[{"n":1,"t":"希西家派人去見以色列和猶大眾人，又寫信給以法蓮和瑪拿西人，要他們到耶路撒冷耶和華的殿，向耶和華－以色列的神守逾越節，","notes":[]},{"n":2,"t":"因為王和眾領袖，以及耶路撒冷全會眾已經商議，要在二月份守逾越節。","notes":[]},{"n":3,"t":"那時他們不能守，因為分別為聖的祭司不夠，百姓也還沒有聚集在耶路撒冷。","notes":[]},{"n":4,"t":"這事在王與全會眾眼中都看為合宜。","notes":[]},{"n":5,"t":"於是他們下令，通告全以色列，從別是巴直到但，吩咐百姓都來，在耶路撒冷向耶和華－以色列的神守逾越節，因為他們已經許久沒有照所寫的守這節了。","notes":["「他們已經...守這節了」或譯「照所寫的條例守這節的人已經不多了」。"]},{"n":6,"t":"信差遵著王命，拿著王和眾領袖所發的信，送達全以色列和猶大，說：「以色列人哪，當轉向耶和華－亞伯拉罕、以撒、以色列的神，好叫他轉向你們這些脫離亞述諸王之手的餘民。","notes":[]},{"n":7,"t":"不要效法你們的祖先和你們的弟兄；他們干犯耶和華－他們列祖的神，以致耶和華使他們令人驚駭，正如你們所見的。","notes":[]},{"n":8,"t":"現在，不要像你們祖先硬著頸項，只要歸順耶和華，進入他的聖所，就是永遠成聖的居所，又要事奉耶和華－你們的神，好使他的烈怒轉離你們。","notes":[]},{"n":9,"t":"你們若轉向耶和華，你們的弟兄和兒女必在擄掠他們的人面前蒙憐憫，得以歸回這地，因為耶和華－你們的神有恩惠，有憐憫。你們若轉向他，他必不會轉臉不顧你們。」","notes":[]},{"n":10,"t":"信差從這城跑到那城，傳遍了以法蓮和瑪拿西之地，直到西布倫；那裏的人卻戲笑他們，譏誚他們。","notes":[]},{"n":11,"t":"然而亞設、瑪拿西、西布倫中也有人謙卑自己，來到耶路撒冷。","notes":[]},{"n":12,"t":"神也按手在猶大人身上，使他們一心遵行王與眾領袖照著耶和華的話所發的命令。","notes":[]},{"n":13,"t":"二月時，許多百姓聚集在耶路撒冷，成為一個盛大的會，要守除酵節。","notes":[],"heads":["守逾越節"]},{"n":14,"t":"他們起來，把耶路撒冷的祭壇和燒香的壇盡都除去，扔在汲淪溪中。","notes":[]},{"n":15,"t":"二月十四日，他們宰了逾越節的羔羊。祭司與利未人覺得慚愧，就使自己分別為聖，把燔祭奉到耶和華的殿中。","notes":[]},{"n":16,"t":"他們遵照神人摩西的律法，按定例站在自己的地方；祭司從利未人手裏接過血來，灑出去。","notes":[]},{"n":17,"t":"會眾中有許多人尚未分別為聖，所以利未人為所有不潔的人宰逾越節的羔羊，使他們歸耶和華為聖。","notes":[]},{"n":18,"t":"從以法蓮、瑪拿西、以薩迦、西布倫來的許多百姓尚未自潔，他們卻吃逾越節的羔羊，不合所寫的條例。希西家為他們禱告說：「求至善的耶和華饒恕","notes":[]},{"n":19,"t":"那凡專心尋求神耶和華－他列祖的神，卻未照聖所潔淨禮自潔的人。」","notes":[]},{"n":20,"t":"耶和華應允希西家，醫治了百姓。","notes":[]},{"n":21,"t":"在耶路撒冷的以色列人守除酵節七日，大大喜樂。利未人和祭司為耶和華演奏響亮的樂器，天天頌讚耶和華。","notes":[]},{"n":22,"t":"希西家慰勞所有精通禮儀，事奉耶和華的利未人。於是眾人吃節期的筵席七日，又獻平安祭，並且稱謝耶和華－他們列祖的神。","notes":[]},{"n":23,"t":"全會眾商議，要再守節七日；於是他們歡歡喜喜地又守節七日。","notes":[],"heads":["再度守節"]},{"n":24,"t":"猶大王希西家賜給會眾一千頭公牛、七千隻羊；眾領袖也賜給會眾一千頭公牛、一萬隻羊，並有許多祭司將自己分別為聖。","notes":[]},{"n":25,"t":"猶大全會眾、祭司、利未人和從以色列來的全會眾，以及那些從以色列地來的和住在猶大的寄居的人，盡都喜樂。","notes":[]},{"n":26,"t":"這樣，在耶路撒冷大有喜樂，因自從以色列王大衛的兒子所羅門以來，在耶路撒冷從未有過這樣的喜樂。","notes":[]},{"n":27,"t":"那時，祭司和利未人起來，為百姓祝福。他們的聲音蒙神垂聽，他們的禱告達到他天上的聖所。","notes":[]}]},"31":{"heading":"希西家的改革","verses":[{"n":1,"t":"這一切事都完畢以後，在那裏的以色列眾人就到猶大的城鎮，打碎柱像，砍斷亞舍拉，又在猶大、便雅憫、以法蓮、瑪拿西遍地把丘壇和祭壇完全拆毀。於是以色列眾人各回各城，各歸自己產業的地去了。","notes":[]},{"n":2,"t":"希西家分派祭司和利未人的班次，使祭司和利未人照各自的班次，按各自的職分獻燔祭和平安祭，又在耶和華殿的門內事奉，稱謝頌讚耶和華。","notes":["「殿」：原文是「營」。"]},{"n":3,"t":"王又從自己的產業中分出一份來作燔祭，就是早晚的燔祭，和安息日、初一，以及節期的燔祭，都是按耶和華律法上所記載的。","notes":[]},{"n":4,"t":"他又吩咐住耶路撒冷的百姓將祭司和利未人所應得的份給他們，使他們堅守耶和華的律法。","notes":[]},{"n":5,"t":"命令一出，以色列人就把初熟的五穀、新酒、新油、蜜和田地的出產多多送來；他們把各樣出產的十分之一大量送來。","notes":[]},{"n":6,"t":"住猶大各城的以色列人和猶大人也將牛羊的十分之一，以及分別為聖歸耶和華－他們神之物，就是十分取一之物，盡都送來，積成一堆一堆；","notes":[]},{"n":7,"t":"他們從三月開始堆積，到七月才完成。","notes":[]},{"n":8,"t":"希西家和眾領袖來，看見這些堆積物，就稱頌耶和華，又為耶和華的百姓以色列祝福。","notes":[]},{"n":9,"t":"希西家向祭司和利未人查問這些堆積物。","notes":[]},{"n":10,"t":"撒督家的亞撒利雅祭司長告訴他說：「自從禮物開始送到耶和華的殿以來，我們不但吃飽，而且剩下的很多；因為耶和華賜福給他的百姓，所剩下的才這樣豐盛。」","notes":[]},{"n":11,"t":"希西家吩咐要在耶和華殿裏預備倉房，他們就預備了。","notes":[]},{"n":12,"t":"他們誠心將禮物，十分取一之物，就是分別為聖之物，都搬入倉內。利未人歌楠雅主管這事，他的兄弟示每是副主管。","notes":[]},{"n":13,"t":"耶歇、亞撒細雅、拿哈、亞撒黑、耶利摩、約撒拔、以列、伊斯瑪基雅、瑪哈、比拿雅都是督辦，在歌楠雅和他兄弟示每的手下，是希西家王和管理神殿的亞撒利雅所委派的。","notes":[]},{"n":14,"t":"守東門的利未人音拿的兒子可利，掌管獻給神的甘心祭，發放獻給耶和華的禮物和至聖的物。","notes":[]},{"n":15,"t":"在祭司的各城裏，在他手下忠心協助他的有伊甸、珉雅珉、耶書亞、示瑪雅、亞瑪利雅、示迦尼雅，都按著班次分給他們的弟兄，無論大小，","notes":[]},{"n":16,"t":"不論是否登錄在家譜，凡三歲以上的男丁，每日進耶和華殿、按班次供職事奉的，都分給他，","notes":[]},{"n":17,"t":"也發放給按父家登錄在家譜的祭司；又按班次職任分給二十歲以上的利未人，","notes":[]},{"n":18,"t":"又按家譜的登記，分給他們的小孩、妻子、兒女，給全體會眾；因為他們忠誠，將自己分別為聖。","notes":[]},{"n":19,"t":"住在各城郊野亞倫的子孫、按名受委任的人，要把應得的份給祭司中所有的男丁和載入家譜的利未人。","notes":[]},{"n":20,"t":"希西家在全猶大都這樣辦理，在耶和華－他神面前行良善、正直、忠誠的事。","notes":[]},{"n":21,"t":"凡他所行的，無論是開始辦神殿的事，是遵律法守誡命，是尋求他的神，他都盡心去做，無不亨通。","notes":[]}]},"32":{"heading":"亞述人恐嚇耶路撒冷","verses":[{"n":1,"t":"在這些虔誠的事以後，亞述王西拿基立來侵犯猶大，圍困堅固城，想要攻破它們。","notes":[]},{"n":2,"t":"希西家見西拿基立來，定意要攻打耶路撒冷，","notes":[]},{"n":3,"t":"就與領袖和勇士商議，塞住城外的泉源；他們都幫助他。","notes":[]},{"n":4,"t":"於是許多百姓聚集，塞住一切泉源，以及國中流通的小河，說：「亞述諸王來，為何讓他們得著許多水呢？」","notes":[]},{"n":5,"t":"希西家奮勇自強，修築所有毀壞的城牆，升高城樓，又在城外築另一片城牆，堅固大衛城的米羅，製造許多兵器和盾牌。","notes":["「米羅」是音譯，指「土堆的防禦工事」。"]},{"n":6,"t":"他設立軍事將領管理百姓，召集他們在城門的廣場，勉勵他們，說：","notes":[]},{"n":7,"t":"「你們當剛強壯膽，不要因亞述王和跟隨他的大軍恐懼驚慌，因為與我們同在的，比與他們同在的更大。","notes":[]},{"n":8,"t":"與他們同在的是血肉之臂，但與我們同在的是耶和華－我們的神，他必幫助我們，為我們爭戰。」百姓因猶大王希西家的話就得到鼓勵。","notes":[]},{"n":9,"t":"此後，亞述王西拿基立和跟隨他的全軍攻打拉吉，派臣僕到耶路撒冷見猶大王希西家和所有在耶路撒冷的猶大人，說：","notes":[]},{"n":10,"t":"「亞述王西拿基立如此說：『你們倚靠甚麼，還留在耶路撒冷受困嗎？","notes":[]},{"n":11,"t":"希西家說：耶和華－我們的神必救我們脫離亞述王的手，這不是誘惑你們，使你們受飢渴而死嗎？","notes":[]},{"n":12,"t":"希西家豈不是將耶和華的丘壇和祭壇廢去，並且吩咐猶大與耶路撒冷的人說：你們當在一個壇前敬拜，在其上燒香嗎？","notes":[]},{"n":13,"t":"我與我祖先向列邦民族所行的，你們豈不知道嗎？列邦的神明何嘗能救自己的國脫離我的手呢？","notes":[]},{"n":14,"t":"我祖先所滅的那些國的神明，有誰能救自己的百姓脫離我的手呢？難道你們的神能救你們脫離我的手嗎？","notes":[]},{"n":15,"t":"現在，不要讓希西家這樣欺騙你們，誘惑你們，也不要相信他，因為沒有一國一邦的神明能救自己的百姓脫離我的手和我祖先的手，你們的神也絕不能救你們脫離我的手。』」","notes":[]},{"n":16,"t":"西拿基立的臣僕還說了一些話來毀謗耶和華神和他的僕人希西家。","notes":[]},{"n":17,"t":"西拿基立也寫信毀謗耶和華－以色列的神，說：「列邦的神明既不能救自己的百姓脫離我的手，希西家的神也不能救他的百姓脫離我的手。」","notes":[]},{"n":18,"t":"亞述王的臣僕用猶大話向耶路撒冷城牆上的百姓大聲呼喊，要恐嚇他們，擾亂他們，以便取城。","notes":[]},{"n":19,"t":"他們談論耶路撒冷的神，如同談論世上人手所造的神明一樣。","notes":[]},{"n":20,"t":"希西家王和亞摩斯的兒子以賽亞先知為此禱告，向天呼求。","notes":[]},{"n":21,"t":"耶和華就差遣一個使者進入亞述王的營中，把所有大能的勇士、官長和將領盡都滅了。亞述王滿面羞愧地回到本國，進了他神明的廟中，他幾個親生的兒子在那裏用刀殺了他。","notes":[]},{"n":22,"t":"這樣，耶和華救希西家和耶路撒冷的居民脫離亞述王西拿基立的手，也脫離一切仇敵的手，又賜他們四境平安。","notes":["「賜他們四境平安」是根據七十士譯本和其他古譯本；原文是「在四境引導他們」。"]},{"n":23,"t":"有許多人到耶路撒冷將供物獻與耶和華，又將寶物送給猶大王希西家。自此之後，希西家在列國人的眼中受人尊崇。","notes":[]},{"n":24,"t":"那些日子，希西家病得要死，就向耶和華禱告，耶和華應允他，賜他一個預兆。","notes":[],"heads":["希西家的疾病和驕傲"]},{"n":25,"t":"希西家卻沒有照他所蒙的恩回報，因他心裏驕傲，所以憤怒要臨到他，臨到猶大和耶路撒冷。","notes":[]},{"n":26,"t":"但希西家和耶路撒冷的居民為了心裏驕傲，就一同謙卑，以致耶和華的憤怒在希西家的日子沒有臨到他們。","notes":[]},{"n":27,"t":"希西家大有財富和尊榮，他為自己建造府庫，收藏金銀、寶石、香料、盾牌和各樣的寶器，","notes":[],"heads":["希西家的財富和尊榮"]},{"n":28,"t":"又建造倉房，收藏五穀、新酒和新的油，又為各類牲畜蓋棚立圈，","notes":[]},{"n":29,"t":"並且為自己建立城鎮，也擁有許多的羊群牛群，因為神賜他極多的財產。","notes":[]},{"n":30,"t":"這希西家也塞住基訓的上源，引水直下，流在大衛城的西邊。希西家所行的事盡都亨通。","notes":[]},{"n":31,"t":"但當巴比倫諸侯差遣使者來見希西家，詢問國中所發生的奇事時，神離開他，要考驗他，好知道他心裏的一切。","notes":[]},{"n":32,"t":"希西家其餘的事和他的善行，看哪，都寫在亞摩斯的兒子以賽亞先知的《默示書》上和《猶大和以色列諸王記》上。","notes":[],"heads":["希西家逝世"]},{"n":33,"t":"希西家與他祖先同睡，葬在大衛子孫陵墓的斜坡上。他死的時候，猶大眾人和耶路撒冷的居民都向他致敬。他的兒子瑪拿西接續他作王。","notes":[]}]},"33":{"heading":"猶大王瑪拿西","verses":[{"n":1,"t":"瑪拿西登基的時候年十二歲，在耶路撒冷作王五十五年。","notes":[]},{"n":2,"t":"他行耶和華眼中看為惡的事，效法耶和華在以色列人面前趕出的列國那些可憎的事。","notes":[]},{"n":3,"t":"他重新建築他父親希西家所拆毀的丘壇，為諸巴力築壇，造亞舍拉，又敬拜天上的萬象，事奉它們。","notes":[]},{"n":4,"t":"他在耶和華殿中築壇，耶和華曾指著這殿說：「我的名必永遠在耶路撒冷。」","notes":[]},{"n":5,"t":"他在耶和華殿的兩個院子為天上的萬象築壇，","notes":[]},{"n":6,"t":"並在欣嫩子谷使他的兒子經火，又觀星象，行法術，行邪術，求問招魂的和行巫術的，多行耶和華眼中看為惡的事，惹他發怒。","notes":[]},{"n":7,"t":"他在神殿內立雕刻的偶像；神曾對大衛和他兒子所羅門說：「我在以色列眾支派中所選擇的耶路撒冷和這殿，必立我的名，直到永遠。","notes":[]},{"n":8,"t":"只要以色列人謹守遵行我藉摩西吩咐他們的一切律法、律例、典章，我就不再使他們的腳挪移，離開我所賜給他們列祖之土地。」","notes":[]},{"n":9,"t":"瑪拿西引誘猶大和耶路撒冷的居民行惡，比耶和華在以色列人面前所滅的列國更嚴重。","notes":[]},{"n":10,"t":"耶和華警戒瑪拿西和他的百姓，他們卻不聽。","notes":[],"heads":["瑪拿西悔改"]},{"n":11,"t":"所以耶和華使亞述王的將領來攻擊他們，用手銬銬住瑪拿西，用銅鏈鎖住他，把他帶到巴比倫去。","notes":[]},{"n":12,"t":"他在急難的時候懇求耶和華－他的神，並在他列祖的神面前極其謙卑。","notes":[]},{"n":13,"t":"他祈禱耶和華，耶和華就應允他，垂聽他的禱告，使他歸回耶路撒冷，仍坐王位。瑪拿西這才知道惟獨耶和華是神。","notes":[]},{"n":14,"t":"此後，瑪拿西在大衛城外，從谷內基訓西邊直到魚門口，建築城牆，環繞俄斐勒；這牆建得很高。他又在猶大各堅固城內設立將領。","notes":[]},{"n":15,"t":"他除掉外邦人的神像與耶和華殿中的偶像，又將他在耶和華殿的山上和耶路撒冷所築的各壇都拆毀，拋在城外。","notes":[]},{"n":16,"t":"他重修耶和華的祭壇，在壇上獻平安祭和感謝祭，並吩咐猶大人事奉耶和華－以色列的神。","notes":[]},{"n":17,"t":"百姓卻仍在丘壇上獻祭，不過，他們只獻給耶和華－他們的神。","notes":[]},{"n":18,"t":"瑪拿西其餘的事和他向神的禱告，以及先見奉耶和華－以色列神的名警戒他的話，看哪，都在《以色列諸王記》上。","notes":[],"heads":["瑪拿西逝世"]},{"n":19,"t":"他的禱告，神怎樣應允他，他未謙卑以前的一切罪愆過犯，以及在何處建築丘壇，設立亞舍拉和雕刻的偶像，看哪，都寫在何賽的書上。","notes":["「何賽」意思是「我的先見」。"]},{"n":20,"t":"瑪拿西與他祖先同睡，葬在自己的宮中，他兒子亞們接續他作王。","notes":[]},{"n":21,"t":"亞們登基的時候年二十二歲，在耶路撒冷作王二年。","notes":[],"heads":["猶大王亞們"]},{"n":22,"t":"他行耶和華眼中看為惡的事，效法他父親瑪拿西所行的，祭祀他父親瑪拿西所雕刻的一切偶像，事奉它們，","notes":[]},{"n":23,"t":"但他不像他父親瑪拿西在耶和華面前那樣謙卑下來。這亞們的罪越犯越大。","notes":[]},{"n":24,"t":"他的臣僕背叛他，在宮裏殺了他。","notes":[]},{"n":25,"t":"但這地的百姓殺了所有背叛亞們王的人；這地的百姓立他兒子約西亞接續他作王。","notes":[]}]},"34":{"heading":"猶大王約西亞","verses":[{"n":1,"t":"約西亞登基的時候年八歲，在耶路撒冷作王三十一年。","notes":[]},{"n":2,"t":"他行耶和華眼中看為正的事，行他祖先大衛所行的道，不偏左右。","notes":[]},{"n":3,"t":"他作王第八年，尚且年輕，就尋求他祖先大衛的神。到了十二年，他開始潔淨猶大和耶路撒冷，除掉丘壇、亞舍拉、雕刻的像和鑄造的像。","notes":[]},{"n":4,"t":"眾人在他面前拆毀諸巴力的壇，砍斷壇上高高的香壇，又把亞舍拉和雕刻的像，以及鑄造的像打碎成灰，撒在向偶像獻祭之人的墳上，","notes":[]},{"n":5,"t":"把祭司的骸骨燒在他們的壇上，潔淨了猶大和耶路撒冷。","notes":[]},{"n":6,"t":"他又在瑪拿西、以法蓮、西緬、拿弗他利各城和四圍的廢墟，","notes":["「和四圍的廢墟」：原文另譯「查訪他們的屋子」。"]},{"n":7,"t":"拆毀祭壇，把亞舍拉和雕刻的像打碎成灰，砍斷以色列全地所有的香壇。於是他回耶路撒冷去了。","notes":[]},{"n":8,"t":"約西亞王十八年，這地和殿潔淨了之後，他派亞薩利雅的兒子沙番、瑪西雅市長、約哈斯的兒子約亞史官去整修耶和華－他神的殿。","notes":[],"heads":["發現律法書"]},{"n":9,"t":"他們去見希勒家大祭司，把奉到神殿的銀子交給他；這銀子是看守殿門的利未人從瑪拿西、以法蓮，和以色列所有倖存的人，以及猶大、便雅憫眾人和耶路撒冷的居民收來的。","notes":[]},{"n":10,"t":"他們把這銀子交給耶和華殿裏督工的，由他們轉交整修耶和華殿的工匠，","notes":[]},{"n":11,"t":"就是交給木匠和石匠，好為猶大王所毀壞的殿，買鑿成的石頭和作鉤子與棟梁的木料。","notes":[]},{"n":12,"t":"這些人辦事誠實，管理他們的是利未人米拉利的子孫雅哈和俄巴底，又有哥轄人撒迦利亞和米書蘭；還有所有善於奏樂的利未人。","notes":[]},{"n":13,"t":"他們監督扛抬的人，督導一切做各樣工的人。利未人中也有作書記、官員、守衛的。","notes":[]},{"n":14,"t":"他們把奉到耶和華殿的銀子運出來的時候，希勒家祭司發現了耶和華藉摩西所傳的律法書。","notes":[]},{"n":15,"t":"希勒家對沙番書記說：「我在耶和華殿裏發現了律法書。」希勒家把書遞給沙番。","notes":[]},{"n":16,"t":"沙番把書拿到王那裏，又把這事回覆王說：「凡交給僕人的手所辦的事，他們都辦好了。","notes":[]},{"n":17,"t":"耶和華殿裏所發現的銀子已經倒出來，交在督工和工匠的手裏了。」","notes":[]},{"n":18,"t":"沙番書記又向王報告說：「希勒家祭司遞給我一卷書。」沙番就在王面前朗讀那書。","notes":[]},{"n":19,"t":"王聽見律法的話，就撕裂衣服。","notes":[]},{"n":20,"t":"王吩咐希勒家與沙番的兒子亞希甘、米迦的兒子亞比頓、沙番書記和王的臣僕亞撒雅，說：","notes":["「米迦」是「米該亞」的小名；參王下22．12。","「亞比頓」：王下22．12稱「亞革波」。"]},{"n":21,"t":"「你們去，以所發現這書上的話，為我、為以色列和猶大倖存的人求問耶和華；因為我們的祖先沒有遵守耶和華的話，沒有照這書上所記的一切去做，耶和華的烈怒就倒在我們身上。」","notes":[]},{"n":22,"t":"於是，希勒家和王的人都去見戶勒大女先知，她是掌管禮服的沙龍的妻子，沙龍是哈斯拉的孫子，特瓦的兒子。戶勒大住在耶路撒冷第二區。他們向她說明來意。","notes":["「王的人」：有古卷和古譯本是「王所派的人」。"]},{"n":23,"t":"她對他們說：「耶和華－以色列的神如此說：『你們可以回覆那派你們來見我的人說，","notes":[]},{"n":24,"t":"耶和華如此說：看哪，我必照著在猶大王面前所讀那書上記載的一切詛咒，降禍於這地方和其上的居民。","notes":[]},{"n":25,"t":"因為他們離棄我，向別神燒香，用他們手所做的一切惹我發怒，所以我的憤怒必倒在這地方，總不止息。』","notes":[]},{"n":26,"t":"然而，派你們來求問耶和華的猶大王，你們要這樣回覆他：『耶和華－以色列的神如此說：至於你所聽見的話，","notes":[]},{"n":27,"t":"就是聽見我指著這地方和其上居民所說的話，你的心就軟化，在我面前謙卑下來，撕裂衣服，向我哭泣，因此我應允你。這是耶和華說的。","notes":[]},{"n":28,"t":"看哪，我必使你歸到你祖先那裏，平安地進入墳墓，我要降於這地方和其上居民的一切災禍，你不會親眼看見。』」他們就去把這話回覆王。","notes":[]},{"n":29,"t":"王派人召集猶大和耶路撒冷的眾長老來。","notes":[],"heads":["約西亞立約順從主"]},{"n":30,"t":"王和猶大眾人、耶路撒冷的居民、祭司、利未人，以及所有的百姓，無論大小，都一同上到耶和華的殿去；王把殿裏所發現的約書上面一切的話讀給他們聽。","notes":[]},{"n":31,"t":"王站在自己的位上，在耶和華面前立約，要盡心盡性跟從耶和華，遵守他的誡命、法度、律例，實行這書上所記這約的話；","notes":[]},{"n":32,"t":"又使所有住耶路撒冷和便雅憫的人都服從這約。於是耶路撒冷的居民都遵行神，就是他們列祖之神的約。","notes":[]},{"n":33,"t":"約西亞從以色列各處把一切可憎之物盡都除掉，使以色列境內的人都事奉耶和華－他們的神。約西亞在世的日子，眾人都跟從耶和華－他們列祖的神，總不離開。","notes":[]}]},"35":{"heading":"約西亞守逾越節","verses":[{"n":1,"t":"約西亞在耶路撒冷向耶和華守逾越節。正月十四日，他們宰了逾越節的羔羊。","notes":[]},{"n":2,"t":"王分派祭司各盡其職，又勉勵他們辦耶和華殿中的事。","notes":[]},{"n":3,"t":"他對那歸耶和華為聖、教導以色列眾人的利未人說：「你們將聖約櫃安放在以色列王大衛兒子所羅門建造的殿裏，不必再用肩扛抬。現在你們要服事耶和華－你們的神和他的百姓以色列。","notes":[]},{"n":4,"t":"你們應當按著父家，照著班次，遵照以色列王大衛和他兒子所羅門所寫的，預備自己。","notes":[]},{"n":5,"t":"要按著你們百姓的弟兄、父家的班次，侍立在聖所；每父家的班次中要有幾個利未人。","notes":[]},{"n":6,"t":"要宰逾越節的羔羊，將自己分別為聖，為你們的弟兄預備，好遵守耶和華藉摩西所吩咐的話。」","notes":[]},{"n":7,"t":"約西亞從群畜中賜給所有在場的百姓，三萬隻小綿羊和小山羊，三千頭牛，作逾越節的祭物；這些都是出自王的產業。","notes":[]},{"n":8,"t":"約西亞的眾領袖也樂意把祭牲給百姓、祭司和利未人；管理神殿的希勒家、撒迦利亞、耶歇，把二千六百隻羔羊和三百頭牛給祭司作逾越節的祭物。","notes":[]},{"n":9,"t":"利未人的族長歌楠雅和他兩個兄弟示瑪雅、拿坦業，與哈沙比雅、耶利、約撒拔，把五千隻羔羊和五百頭牛給利未人作逾越節的祭物。","notes":[]},{"n":10,"t":"這樣，事奉的工作都安排好了，照王所吩咐的，祭司站在自己的位上，利未人按著班次侍立。","notes":[]},{"n":11,"t":"他們宰了逾越節的羔羊，祭司從他們手裏接過血來灑出去；利未人剝皮，","notes":["原文沒有「接過血來」。"]},{"n":12,"t":"把燔祭拿走，再按著父家的班次分給眾百姓，照摩西書上所寫的獻給耶和華；獻牛也是這樣。","notes":[]},{"n":13,"t":"他們按著常例，用火烤逾越節的羔羊。至於其他的聖物，他們用盆，用鍋，用釜煮了，速速地送給眾百姓。","notes":[]},{"n":14,"t":"然後他們為自己和祭司預備祭物，因為作祭司的亞倫子孫獻燔祭和脂肪，直到晚上。所以利未人為自己和作祭司的亞倫子孫預備。","notes":[]},{"n":15,"t":"歌唱的亞薩子孫，照著大衛、亞薩、希幔和王的先見耶杜頓所吩咐的，站在自己的位上。守門的看守各門，不用離開他們的職守，因為他們的弟兄利未人給他們預備。","notes":[]},{"n":16,"t":"當日，一切供奉耶和華、守逾越節，以及在耶和華壇上獻燔祭的事，都照約西亞王的吩咐預備好了。","notes":[]},{"n":17,"t":"那時，在場的以色列人都守逾越節，又守除酵節七日。","notes":[]},{"n":18,"t":"自從撒母耳先知的日子以來，在以色列中沒有守過這樣的逾越節，以色列諸王也沒有守過像約西亞、祭司、利未人、所有住猶大和以色列的人，以及耶路撒冷居民所守的逾越節。","notes":[]},{"n":19,"t":"這逾越節是約西亞作王十八年時守的。","notes":[]},{"n":20,"t":"約西亞為殿做完這一切事以後，埃及王尼哥上來，要攻打靠近幼發拉底河的迦基米施；約西亞出去迎擊他。","notes":[],"heads":["約西亞逝世"]},{"n":21,"t":"他派使者來見約西亞，說：「猶大王啊，我跟你有甚麼相干呢？我今日來不是要攻打你，而是要攻打與我爭戰之家，並且神吩咐我從速行事。你不要干預與我同在的神，免得他毀滅你。」","notes":[]},{"n":22,"t":"約西亞卻不轉臉離開他，反而改裝要與他打仗。他不聽從神藉尼哥的口所說的話，就來到米吉多平原爭戰。","notes":[]},{"n":23,"t":"弓箭手射中約西亞王。王對他的臣僕說：「我受了重傷，你們載我離開戰場吧！」","notes":[]},{"n":24,"t":"他的臣僕扶他下了戰車，上了他的副座車，送他到耶路撒冷。他就死了，葬在他祖先的墳墓裏。全猶大和耶路撒冷都哀悼約西亞。","notes":[]},{"n":25,"t":"耶利米為約西亞作哀歌，所有歌唱的男女也唱哀歌，追悼約西亞，直到今日。他們在以色列中以此為定例；看哪，這些哀歌寫在《哀歌書》上。","notes":[]},{"n":26,"t":"約西亞其餘的事和他遵照耶和華律法上所記而行的善事，","notes":[]},{"n":27,"t":"以及他自始至終所行的，看哪，都寫在《以色列和猶大列王記》上。","notes":[]}]},"36":{"heading":"猶大王約哈斯","verses":[{"n":1,"t":"這地的百姓立約西亞的兒子約哈斯在耶路撒冷接續他父親作王。","notes":[]},{"n":2,"t":"約哈斯登基的時候年二十三歲，在耶路撒冷作王三個月。","notes":[]},{"n":3,"t":"埃及王在耶路撒冷廢了他，又罰這地一百他連得銀子，一他連得金子。","notes":[]},{"n":4,"t":"埃及王尼哥立約哈斯的哥哥以利雅敬作猶大和耶路撒冷的王，給他改名叫約雅敬。尼哥卻將他的弟弟約哈斯帶到埃及去。","notes":[]},{"n":5,"t":"約雅敬登基的時候年二十五歲，在耶路撒冷作王十一年。他行耶和華－他神眼中看為惡的事。","notes":[],"heads":["猶大王約雅敬"]},{"n":6,"t":"巴比倫王尼布甲尼撒上來攻擊他，用銅鏈鎖著他，要把他帶到巴比倫去。","notes":[]},{"n":7,"t":"尼布甲尼撒又將耶和華殿裏的一些器皿帶到巴比倫，放在巴比倫自己的宮裏。","notes":["「自己的宮裏」或譯「他的廟裏」。"]},{"n":8,"t":"約雅敬其餘的事和他所行可憎的事，以及發生在他身上的事，看哪，都寫在《以色列和猶大列王記》上，他兒子約雅斤接續他作王。","notes":[]},{"n":9,"t":"約雅斤登基的時候年八歲，在耶路撒冷作王三個月十天，他行耶和華眼中看為惡的事。","notes":["「八歲」：王下24．8是「十八歲」。"],"heads":["猶大王約雅斤"]},{"n":10,"t":"過了一年，尼布甲尼撒王差遣人將約雅斤和耶和華殿裏寶貴的器皿帶到巴比倫，然後立約雅斤的叔父西底家作猶大和耶路撒冷的王。","notes":["「叔父」：原文是「兄弟」。"]},{"n":11,"t":"西底家登基的時候年二十一歲，在耶路撒冷作王十一年。","notes":[],"heads":["猶大王西底家"]},{"n":12,"t":"他行耶和華－他神眼中看為惡的事，沒有謙卑聽從耶利米先知所傳達耶和華的話。","notes":[]},{"n":13,"t":"尼布甲尼撒王曾叫他指著神起誓，他卻背叛，硬著頸項，內心頑固，不歸向耶和華－以色列的神。","notes":[]},{"n":14,"t":"眾祭司長和百姓也多多犯罪，效法列國一切可憎的事，玷污耶和華在耶路撒冷分別為聖的殿。","notes":[]},{"n":15,"t":"耶和華－他們列祖的神因為愛惜自己的百姓和居所，一再差遣使者去警戒他們。","notes":[]},{"n":16,"t":"他們卻嘲笑神的使者，藐視他的話，譏誚他的先知，以致耶和華向他的百姓大發烈怒，甚至無法可救。","notes":[]},{"n":17,"t":"所以，耶和華使迦勒底人的王來攻擊他們，在他們聖殿裏用刀殺了他們的壯丁，不憐憫他們的少男少女、老人長者。耶和華把所有的人都交在他手裏。","notes":[]},{"n":18,"t":"他把神殿裏一切的大小器皿與耶和華殿裏的財寶，以及王和眾領袖的財寶，全都帶到巴比倫去。","notes":[]},{"n":19,"t":"迦勒底人焚燒了神的殿，拆毀耶路撒冷的城牆，用火燒了城裏所有的宮殿，毀壞了城裏一切寶貴的器皿。","notes":[]},{"n":20,"t":"凡脫離刀劍的倖存者，迦勒底王都擄到巴比倫去，作他和他子孫的僕婢，直到波斯國興起。","notes":[]},{"n":21,"t":"這就應驗耶和華藉耶利米的口所說的話：地得享安息；在荒涼的日子，地就守安息，直到滿了七十年。","notes":[]},{"n":22,"t":"波斯王居魯士元年，耶和華為要應驗藉耶利米的口所說的話，就激發波斯王居魯士的心，使他下詔書通告全國，說：","notes":[],"heads":["猶大人返國"]},{"n":23,"t":"「波斯王居魯士如此說：耶和華－天上的神已將地上萬國賜給我，又委派我在猶大的耶路撒冷為他建造殿宇。你們中間凡作他子民的可以上去，願耶和華－他的神與他同在。」","notes":[]}]}},"EZR":{"1":{"heading":"居魯士下令猶太人返國","verses":[{"n":1,"t":"波斯王居魯士元年，耶和華為要應驗藉耶利米的口所說的話，就激發波斯王居魯士的心，使他下詔書通告全國，說：","notes":[]},{"n":2,"t":"「波斯王居魯士如此說：耶和華天上的神已將地上萬國賜給我，又委派我在猶大的耶路撒冷為他建造殿宇。","notes":[]},{"n":3,"t":"你們中間凡作他子民的，可以上猶大的耶路撒冷去，重建耶和華－以色列神的殿，他是在耶路撒冷的神；願神與這人同在。","notes":[]},{"n":4,"t":"凡存留的人，無論寄居何處，那地的人要用金銀、財物、牲畜幫助他，還要為耶路撒冷神的殿甘心獻上禮物。」","notes":[]},{"n":5,"t":"於是，猶大和便雅憫的族長、祭司、利未人，凡是心被神感動的人都起來，要上耶路撒冷去建造耶和華的殿。","notes":[]},{"n":6,"t":"四圍所有的人都拿銀器、金子、財物、牲畜、珍寶支持他們，此外還有甘心獻的一切禮物。","notes":["「銀器」：原文另譯「一切的東西，銀子」。","「支持他們」：原文是「堅固他們的手」。","「此外還有甘心獻的一切禮物」：原文另譯「甘心獻的禮物很多」。"]},{"n":7,"t":"居魯士王也把耶和華殿的器皿拿出來，這些器皿是尼布甲尼撒從耶路撒冷掠取，放在自己神明廟中的。","notes":[]},{"n":8,"t":"波斯王居魯士派米提利達司庫把這些器皿拿出來，點交給猶大的領袖設巴薩。","notes":[]},{"n":9,"t":"它們的數目如下：金盤三十個，銀盤一千個，刀二十九把，","notes":[]},{"n":10,"t":"金碗三十個，備用銀碗四百一十個，其他器皿一千件。","notes":[]},{"n":11,"t":"金銀器皿共有五千四百件。被擄的人從巴比倫上耶路撒冷的時候，設巴薩把這一切都帶了上來。","notes":[]}]},"2":{"heading":"被擄歸回者的名單","verses":[{"n":1,"t":"這些是從被擄之地上來的省民，巴比倫王尼布甲尼撒把他們擄到巴比倫，他們重返耶路撒冷和猶大，各歸本城。","notes":[]},{"n":2,"t":"他們是同所羅巴伯、耶書亞、尼希米、西萊雅、利來雅、末底改、必珊、米斯拔、比革瓦伊、利宏、巴拿一起回來的。以色列百姓的人數如下：","notes":[]},{"n":3,"t":"巴錄的子孫二千一百七十二名；","notes":[]},{"n":4,"t":"示法提雅的子孫三百七十二名；","notes":[]},{"n":5,"t":"亞拉的子孫七百七十五名；","notes":[]},{"n":6,"t":"巴哈‧摩押的後裔，就是耶書亞和約押的子孫二千八百一十二名；","notes":[]},{"n":7,"t":"以攔的子孫一千二百五十四名；","notes":[]},{"n":8,"t":"薩土的子孫九百四十五名；","notes":[]},{"n":9,"t":"薩改的子孫七百六十名；","notes":[]},{"n":10,"t":"巴尼的子孫六百四十二名；","notes":[]},{"n":11,"t":"比拜的子孫六百二十三名；","notes":[]},{"n":12,"t":"押甲的子孫一千二百二十二名；","notes":[]},{"n":13,"t":"亞多尼干的子孫六百六十六名；","notes":[]},{"n":14,"t":"比革瓦伊的子孫二千零五十六名；","notes":[]},{"n":15,"t":"亞丁的子孫四百五十四名；","notes":[]},{"n":16,"t":"亞特的後裔，就是希西家的子孫九十八名；","notes":[]},{"n":17,"t":"比賽的子孫三百二十三名；","notes":[]},{"n":18,"t":"約拉的子孫一百一十二名；","notes":[]},{"n":19,"t":"哈順的子孫二百二十三名；","notes":[]},{"n":20,"t":"吉罷珥人九十五名；","notes":[]},{"n":21,"t":"伯利恆人一百二十三名；","notes":[]},{"n":22,"t":"尼陀法人五十六名；","notes":[]},{"n":23,"t":"亞拿突人一百二十八名；","notes":[]},{"n":24,"t":"亞斯瑪弗人四十二名；","notes":[]},{"n":25,"t":"基列‧耶琳人、基非拉人、比錄人共七百四十三名；","notes":[]},{"n":26,"t":"拉瑪人和迦巴人共六百二十一名；","notes":[]},{"n":27,"t":"默瑪人一百二十二名；","notes":[]},{"n":28,"t":"伯特利人和艾人共二百二十三名；","notes":[]},{"n":29,"t":"尼波人五十二名；","notes":[]},{"n":30,"t":"末必人一百五十六名；","notes":[]},{"n":31,"t":"另一個以攔的子孫一千二百五十四名；","notes":[]},{"n":32,"t":"哈琳的子孫三百二十名；","notes":[]},{"n":33,"t":"羅德人、哈第人、阿挪人共七百二十五名；","notes":[]},{"n":34,"t":"耶利哥人三百四十五名；","notes":[]},{"n":35,"t":"西拿人三千六百三十名。","notes":[]},{"n":36,"t":"祭司：耶書亞家耶大雅的子孫九百七十三名；","notes":[]},{"n":37,"t":"音麥的子孫一千零五十二名；","notes":[]},{"n":38,"t":"巴施戶珥的子孫一千二百四十七名；","notes":[]},{"n":39,"t":"哈琳的子孫一千零一十七名。","notes":[]},{"n":40,"t":"利未人：何達威雅的後裔，就是耶書亞和甲篾的子孫七十四名。","notes":[]},{"n":41,"t":"歌唱的：亞薩的子孫一百二十八名。","notes":[]},{"n":42,"t":"門口的守衛：沙龍的子孫、亞特的子孫、達們的子孫、亞谷的子孫、哈底大的子孫、朔拜的子孫，共一百三十九名。","notes":[]},{"n":43,"t":"殿役：西哈的子孫、哈蘇巴的子孫、答巴俄的子孫、","notes":[]},{"n":44,"t":"基綠的子孫、西亞的子孫、巴頓的子孫、","notes":[]},{"n":45,"t":"利巴拿的子孫、哈迦巴的子孫、亞谷的子孫、","notes":[]},{"n":46,"t":"哈甲的子孫、薩買的子孫、哈難的子孫、","notes":[]},{"n":47,"t":"吉德的子孫、迦哈的子孫、利亞雅的子孫、","notes":[]},{"n":48,"t":"利汛的子孫、尼哥大的子孫、迦散的子孫、","notes":[]},{"n":49,"t":"烏撒的子孫、巴西亞的子孫、比賽的子孫、","notes":[]},{"n":50,"t":"押拿的子孫、米烏寧的子孫、尼普心的子孫、","notes":[]},{"n":51,"t":"巴卜的子孫、哈古巴的子孫、哈忽的子孫、","notes":[]},{"n":52,"t":"巴洗律的子孫、米希大的子孫、哈沙的子孫、","notes":[]},{"n":53,"t":"巴柯的子孫、西西拉的子孫、答瑪的子孫、","notes":[]},{"n":54,"t":"尼細亞的子孫、哈提法的子孫。","notes":[]},{"n":55,"t":"所羅門僕人的後裔：瑣太的子孫、瑣斐列的子孫、比路大的子孫、","notes":[]},{"n":56,"t":"雅拉的子孫、達昆的子孫、吉德的子孫、","notes":[]},{"n":57,"t":"示法提雅的子孫、哈替的子孫、玻黑列‧哈斯巴音的子孫、亞米的子孫。","notes":[]},{"n":58,"t":"殿役和所羅門僕人的後裔共三百九十二名。","notes":[]},{"n":59,"t":"從特‧米拉、特‧哈薩、基綠、亞頓、音麥上來，不能證明他們的父系家族和後裔是否屬以色列的如下：","notes":[]},{"n":60,"t":"第萊雅的子孫、多比雅的子孫、尼哥大的子孫，共六百五十二名。","notes":[]},{"n":61,"t":"祭司中，哈巴雅的子孫、哈哥斯的子孫、巴西萊的子孫，巴西萊因為娶了基列人巴西萊的女兒為妻，所以就以此為名。","notes":[]},{"n":62,"t":"這些人在族譜之中尋查自己的譜系，卻尋不著，因此算為不潔，不得作祭司。","notes":[]},{"n":63,"t":"省長對他們說，不可吃至聖的物，直到有會用烏陵和土明的祭司興起來。","notes":[]},{"n":64,"t":"全會眾共有四萬二千三百六十名。","notes":[]},{"n":65,"t":"此外，還有他們的僕婢七千三百三十七名，又有歌唱的男女二百名。","notes":[]},{"n":66,"t":"他們有七百三十六匹馬，二百四十五匹騾子，","notes":[]},{"n":67,"t":"四百三十五匹駱駝，六千七百二十匹驢。","notes":[]},{"n":68,"t":"有些族長到了耶路撒冷耶和華的殿，為神的殿甘心獻上禮物，要在原有的根基上重新建造。","notes":[]},{"n":69,"t":"他們量力捐入工程的庫房，有六萬一千達利克金子，五千彌那銀子，以及一百件祭司的禮服。","notes":["「達利克」﹕古波斯金幣；參「度量衡表」；8．27同。"]},{"n":70,"t":"於是祭司、利未人、百姓中的一些人、歌唱的、門口的守衛、殿役，各住在自己的城裏；以色列眾人都住在自己的城裏。","notes":[]}]},"3":{"heading":"恢復敬拜神的生活","verses":[{"n":1,"t":"到了七月，以色列人住在自己的城裏；那時他們如同一人，聚集在耶路撒冷。","notes":[]},{"n":2,"t":"約薩達的兒子耶書亞和他的弟兄眾祭司，以及撒拉鐵的兒子所羅巴伯和他的弟兄，都起來建築以色列神的壇，要照神人摩西律法書上所寫的，在壇上獻燔祭。","notes":[]},{"n":3,"t":"他們在原有的根基上築壇，因為他們懼怕鄰邦民族，又在其上向耶和華早晚獻燔祭，","notes":[]},{"n":4,"t":"並照律法書上所寫的守住棚節，按數照例每日獻所當獻的燔祭。","notes":[]},{"n":5,"t":"此後，他們獻常獻的燔祭，並在初一和耶和華一切分別為聖的節期獻祭，又向耶和華獻各人的甘心祭。","notes":[]},{"n":6,"t":"從七月初一起，雖然耶和華殿的根基尚未立定，他們開始向耶和華獻燔祭。","notes":[]},{"n":7,"t":"他們把銀子給石匠、木匠，把糧食、酒、油給西頓人、推羅人，好將香柏樹從黎巴嫩浮海運到約帕，是照波斯王居魯士所允准他們的。","notes":[]},{"n":8,"t":"他們到了耶路撒冷神殿的第二年，二月的時候，撒拉鐵的兒子所羅巴伯，約薩達的兒子耶書亞和其餘的弟兄，就是祭司和利未人，以及所有被擄歸回耶路撒冷的人，就開工建造；他們派二十歲以上的利未人，監督建造耶和華殿的工作。","notes":[],"heads":["重建聖殿"]},{"n":9,"t":"於是何達威雅的後裔，就是耶書亞和他的子孫與弟兄、甲篾和他的子孫，他們和利未人希拿達的子孫與弟兄，都起來如同一人，監督那些在神殿裏做工的人。","notes":["「何達威雅」：原文是「猶大」；參2．40。"]},{"n":10,"t":"工匠立耶和華殿根基的時候，祭司穿禮服吹號，利未人亞薩的子孫敲鈸，都照以色列王大衛親手所定的，站著讚美耶和華。","notes":[]},{"n":11,"t":"他們彼此唱和，讚美稱謝耶和華：「他本為善，他向以色列永施慈愛。」他們讚美耶和華的時候，眾百姓大聲呼喊，因為耶和華殿的根基已經立定。","notes":[]},{"n":12,"t":"然而有許多祭司、利未人和族長，就是見過先前那殿的老年人，現在親眼看見這殿立了根基，就大聲哭號，也有許多人大聲歡呼，","notes":[]},{"n":13,"t":"百姓不能分辨歡呼的聲音或哭號的聲音，因為百姓大聲呼喊，聲音連遠處都可聽到。","notes":[]}]},"4":{"heading":"建殿之工受阻","verses":[{"n":1,"t":"猶大和便雅憫的敵人聽說被擄歸回的人為耶和華－以色列的神建造殿宇，","notes":[]},{"n":2,"t":"就去見所羅巴伯和族長，對他們說：「請讓我們與你們一同建造，因為我們也與你們一樣尋求你們的神。自從亞述王以撒‧哈頓帶我們上這地的日子以來，我們常向神獻祭。」","notes":[]},{"n":3,"t":"但所羅巴伯、耶書亞和其餘以色列的族長對他們說：「我們建造神的殿與你們無關，因為我們要照波斯王居魯士所吩咐的，自己為耶和華－以色列的神協力建造。」","notes":[]},{"n":4,"t":"那地的人就在猶大百姓建造的時候，使他們的手發軟，擾亂他們。","notes":[]},{"n":5,"t":"從波斯王居魯士年間，直到波斯王大流士在位的時候，那些人賄賂謀士，要破壞他們的計劃。","notes":[]},{"n":6,"t":"亞哈隨魯在位，他的國度剛開始的時候，他們上書控告猶大和耶路撒冷的居民。","notes":[],"heads":["阻撓重建耶路撒冷"]},{"n":7,"t":"亞達薛西年間，比施蘭、米特利達、他別和他們的同僚上書奏告波斯王亞達薛西。奏文是用亞蘭文寫的，以亞蘭文呈上。","notes":["「他們」：原文是「他」。"]},{"n":8,"t":"利宏省長、伸帥書記也上奏亞達薛西王，控告耶路撒冷如下","notes":["從 4．8－6．18，以及7．12－26，原文是亞蘭文。"]},{"n":9,"t":"（那時，利宏省長、伸帥書記和他們其餘的同僚，法官、官員、軍官、波斯官員、亞基衛人、巴比倫人，和書珊迦人，就是以攔人，","notes":["「法官、官員、軍官、波斯官員」：原文音譯「底拿人、亞法薩提迦人、他毗拉人、亞法撒人」。","「就是以攔人」：原文另譯「底亥人、以攔人」。"]},{"n":10,"t":"以及被亞斯那巴大人遷移、安置在撒瑪利亞城和大河西邊一帶地方其餘的人。現在 ，","notes":[]},{"n":11,"t":"這是他們上奏亞達薛西王奏文的抄本）：「河西的臣僕上奏亞達薛西王，現在","notes":[]},{"n":12,"t":"請王知道，從王那裏上到我們這裏的猶太人，已經抵達耶路撒冷。他們正在重建這反叛惡劣的城，已經完成了城牆，正要修復根基。","notes":[]},{"n":13,"t":"如今請王知道，這城若再建造，城牆完工，他們就不再進貢、納糧、繳稅，王的國庫必受虧損。","notes":[]},{"n":14,"t":"如今，我們吃的鹽既然全是宮廷的鹽，就不忍見王吃虧，因此奏告於王，","notes":[]},{"n":15,"t":"請王考察先王史籍，必會在史籍上查知這城是反叛的城，對列王和各省有害；自古以來，城中常有悖逆的事，因此這城曾被拆毀。","notes":[]},{"n":16,"t":"我們謹奏王知，這城若再建造，城牆完工，河西之地王就無份了。」","notes":[]},{"n":17,"t":"那時王諭覆利宏省長、伸帥書記和他們其餘的同僚，就是住撒瑪利亞和河西一帶地方的人，說：「願你們平安。現在","notes":[]},{"n":18,"t":"你們所呈給我們的奏本，已經清楚地在我面前讀了。","notes":[]},{"n":19,"t":"我已下令考查，得知這城自古以來果然背叛列王，其中常有反叛悖逆的事。","notes":[]},{"n":20,"t":"也曾有強大的君王治理耶路撒冷，統管河西全地，人就給他們進貢、納糧、繳稅。","notes":[]},{"n":21,"t":"現在你們要下令叫這些人停工，使這城不得建造，等到我再降旨。","notes":[]},{"n":22,"t":"你們當謹慎辦這事，不可遲延，何必讓損害加重，使王受虧損呢？」","notes":[]},{"n":23,"t":"亞達薛西王上諭的抄本在利宏和伸帥書記，以及他們的同僚面前宣讀，他們就急忙往耶路撒冷去見猶太人，用勢力和強權叫他們停工。","notes":[]},{"n":24,"t":"於是，在耶路撒冷神殿的工程就停止了，直停到波斯王大流士第二年。","notes":[],"heads":["恢復重建聖殿工作"]}]},"5":{"heading":"","verses":[{"n":1,"t":"那時，哈該先知和易多的孫子撒迦利亞，兩個先知奉以色列神的名向猶大和耶路撒冷的猶太人說預言。","notes":[]},{"n":2,"t":"於是撒拉鐵的兒子所羅巴伯和約薩達的兒子耶書亞起來，開始建造耶路撒冷神的殿，有神的先知在那裏幫助他們。","notes":[]},{"n":3,"t":"當時河西的達乃總督和示他‧波斯乃，以及他們的同僚來對猶太人這樣說：「誰降旨讓你們建造這殿，完成這建築呢？」","notes":[]},{"n":4,"t":"於是我們告訴他們建造這建築物的人叫甚麼名字。","notes":[]},{"n":5,"t":"但神的眼目看顧猶太人的長老，以致沒有人叫他們停工，直到奏文上告大流士，得著他對這事的回諭。","notes":[]},{"n":6,"t":"這是河西的達乃總督和示他‧波斯乃，以及他們的同僚，就是住河西的官員，上書奏告大流士王的抄本，","notes":["「官員」：原文音譯「亞法薩迦人」；6．6同。"]},{"n":7,"t":"他們上書給王的奏文，其中寫著：「願大流士王諸事平安。","notes":[]},{"n":8,"t":"請王知道，我們往猶大省去，到了至大神的殿。這殿是用鑿成的石頭建造的，梁木插入牆內。這項工程進行迅速，在他們手中順利。","notes":[]},{"n":9,"t":"於是我們問那些長老，對他們這樣說：『誰降旨讓你們建造這殿，完成這建築呢？』","notes":[]},{"n":10,"t":"我們又問他們的名字，要記下他們領袖的名字，奏告於王。","notes":[]},{"n":11,"t":"他們這樣回答我們說：『我們是天和地之神的僕人，重建多年前所建造的殿，就是以色列一位偉大的君王建造完成的。","notes":[]},{"n":12,"t":"但因我們祖先惹天上的神發怒，神把他們交在迦勒底人巴比倫王尼布甲尼撒的手中，他就拆毀這殿，又把百姓擄到巴比倫。","notes":[]},{"n":13,"t":"然而巴比倫王居魯士元年，他降旨允准建造神的這殿。","notes":[]},{"n":14,"t":"神殿中的金銀器皿，就是尼布甲尼撒從耶路撒冷殿中掠取帶到巴比倫廟裏的，居魯士王從巴比倫廟裏取出來，交給派為省長，名叫設巴薩的，","notes":[]},{"n":15,"t":"對他說：可以將這些器皿帶去，放在耶路撒冷的殿中，在原處建造神的殿。","notes":[]},{"n":16,"t":"於是那位設巴薩來建立耶路撒冷神殿的根基。但從那時直到如今，這殿尚未修建完畢。』","notes":[]},{"n":17,"t":"現在，王若以為好，請查閱巴比倫王的檔案庫，看居魯士王有沒有降旨允准在耶路撒冷建造神的殿。請降旨指示我們王對這件事的心意。」","notes":[]}]},"6":{"heading":"發現居魯士王的詔令","verses":[{"n":1,"t":"於是大流士王降旨，要尋察典籍庫，就是在巴比倫藏檔案之處；","notes":[]},{"n":2,"t":"在瑪代省亞馬他城的宮內尋得一卷，其中這樣寫著，「記錄如下：","notes":[]},{"n":3,"t":"居魯士王元年，王降旨論到在耶路撒冷神的殿，要建造這殿作為獻祭之處，堅固它的根基。殿高六十肘，寬六十肘，","notes":[]},{"n":4,"t":"要用三層鑿成的石頭，一層木頭，經費可出於王的庫房。","notes":["「一層木頭」：有古卷是「一層新木頭」。"]},{"n":5,"t":"至於神殿的金銀器皿，就是尼布甲尼撒從耶路撒冷的殿中掠取帶到巴比倫的，必須歸還，帶回耶路撒冷的殿中，各按原處放在神的殿裏。」","notes":[]},{"n":6,"t":"「現在，河西的達乃總督和示他‧波斯乃，以及他們的同僚，就是住河西的官員，你們當遠離那裏。","notes":[],"heads":["大流士王下令繼續建殿"]},{"n":7,"t":"不要攔阻這神殿的工作，任由猶太人的省長和長老在原處建造神的這殿。","notes":[]},{"n":8,"t":"我又降旨，吩咐你們為建造神的殿當向猶太人的長老這樣行：從王的財產中，由河西所繳納的貢銀，迅速支付這些人，免得工程停頓。","notes":[]},{"n":9,"t":"他們向天上的神獻燔祭所需用的公牛犢、公綿羊、小綿羊，以及麥子、鹽、酒、油，都要照耶路撒冷祭司的話，每日供給他們，不得有誤；","notes":[]},{"n":10,"t":"好叫他們獻馨香的祭給天上的神，又為王和王眾子的壽命祈禱。","notes":[]},{"n":11,"t":"我再降旨，無論誰更改這命令，必從他房屋中拆出一根梁木，把他舉起，懸在其上，又使他的房屋為此成為糞堆。","notes":[]},{"n":12,"t":"任何王或百姓若伸手更改這命令，拆毀在耶路撒冷神的這殿，願那立他名在那裏的神將他們滅絕。我大流士降這諭旨，你們要速速遵行。」","notes":[]},{"n":13,"t":"於是，河西的達乃總督和示他‧波斯乃，以及他們的同僚，急速遵行大流士王所頒的命令。","notes":[],"heads":["聖殿奉獻禮"]},{"n":14,"t":"猶太人的長老因哈該先知和易多的孫子撒迦利亞的預言，就建造這殿，凡事順利。他們遵照以色列神的命令和波斯王居魯士、大流士、亞達薛西的諭旨，建造完畢。","notes":[]},{"n":15,"t":"大流士王第六年，亞達月初三，這殿完工了。","notes":[]},{"n":16,"t":"以色列人、祭司和利未人，以及其餘被擄歸回的人都歡歡喜喜地為神的這殿行奉獻禮。","notes":[]},{"n":17,"t":"他們為這神殿的奉獻禮獻了一百頭公牛、二百隻公綿羊、四百隻小綿羊，又照以色列支派的數目獻十二隻公山羊，作以色列眾人的贖罪祭。","notes":[]},{"n":18,"t":"他們派祭司按著班次，利未人也按著班次在耶路撒冷事奉神，正如摩西律法書上所寫的。","notes":[]},{"n":19,"t":"正月十四日，被擄歸回的人守逾越節。","notes":[],"heads":["守逾越節"]},{"n":20,"t":"祭司和利未人一同自潔，他們全都潔淨了。利未人為被擄歸回的眾人和他們的弟兄眾祭司，並為自己宰逾越節的羔羊。","notes":[]},{"n":21,"t":"從被擄之地歸回的以色列人，並所有歸附他們、除掉這地外邦人的污穢、尋求耶和華－以色列神的人，都吃這羔羊。","notes":[]},{"n":22,"t":"他們歡歡喜喜地守除酵節七日，因為耶和華使他們歡喜。耶和華又使亞述王的心轉向他們，堅固他們的手，去做神－以色列神殿的工。","notes":[]}]},"7":{"heading":"以斯拉到達耶路撒冷","verses":[{"n":1,"t":"這些事以後，波斯王亞達薛西在位的時候，有個人叫以斯拉，他是西萊雅的兒子，西萊雅是亞撒利雅的兒子，亞撒利雅是希勒家的兒子，","notes":[]},{"n":2,"t":"希勒家是沙龍的兒子，沙龍是撒督的兒子，撒督是亞希突的兒子，","notes":[]},{"n":3,"t":"亞希突是亞瑪利雅的兒子，亞瑪利雅是亞撒利雅的兒子，亞撒利雅是米拉約的兒子，","notes":[]},{"n":4,"t":"米拉約是西拉希雅的兒子，西拉希雅是烏西的兒子，烏西是布基的兒子，","notes":[]},{"n":5,"t":"布基是亞比書的兒子，亞比書是非尼哈的兒子，非尼哈是以利亞撒的兒子，以利亞撒是亞倫大祭司的兒子。","notes":[]},{"n":6,"t":"這以斯拉從巴比倫上來，他是一個文士，精通耶和華－以色列神所賜摩西的律法。王允准他一切所求的，因為耶和華－他神的手幫助他。","notes":[]},{"n":7,"t":"亞達薛西王第七年，有些以色列人、一些祭司、利未人、歌唱的、門口的守衛、殿役，上耶路撒冷去。","notes":[]},{"n":8,"t":"王第七年五月，以斯拉到了耶路撒冷。","notes":[]},{"n":9,"t":"正月初一，他從巴比倫起程，五月初一就到了耶路撒冷，因為他神施恩的手幫助他。","notes":[]},{"n":10,"t":"以斯拉立志考究遵行耶和華的律法，又將律例典章教導以色列人。","notes":[]},{"n":11,"t":"亞達薛西王賜給精通耶和華誡命和以色列律例的文士以斯拉祭司的諭旨，抄本如下：","notes":[],"heads":["亞達薛西王給以斯拉的文件"]},{"n":12,"t":"「諸王之王亞達薛西，達於精通天上之神律法的以斯拉祭司文士等等：現在","notes":[]},{"n":13,"t":"住在我國中的以色列百姓、祭司、利未人，凡願意上耶路撒冷去的，我降旨准他們與你同去。","notes":[]},{"n":14,"t":"既然王與七個謀士派你去，照你手中神的律法視察猶大和耶路撒冷的景況；","notes":[]},{"n":15,"t":"你又帶著王和謀士樂意獻給住耶路撒冷、以色列神的金銀，","notes":[]},{"n":16,"t":"和你在巴比倫全省所得的一切金銀，以及百姓、祭司甘心獻給耶路撒冷他們神殿的禮物，","notes":[]},{"n":17,"t":"那麼，你就當用這銀子急速買公牛、公綿羊、小綿羊，和同獻的素祭、澆酒祭，獻在耶路撒冷你們神殿的壇上。","notes":[]},{"n":18,"t":"剩下的金銀，你和你的弟兄看怎樣好，就怎樣用，但總要遵照你們神的旨意。","notes":[]},{"n":19,"t":"你要帶著交託給你、在神殿中事奉用的器皿，到耶路撒冷神面前。","notes":[]},{"n":20,"t":"你神殿裏若再有需用的經費，是你負責供應的，可以從王的寶庫裏支取。","notes":[]},{"n":21,"t":"「我亞達薛西王又降旨達於河西所有的司庫：『精通天上之神律法的以斯拉祭司文士無論向你們要甚麼，你們要速速辦理，","notes":[]},{"n":22,"t":"直至一百他連得銀子，一百柯珥麥子，一百罷特酒，一百罷特油，鹽不限其數。","notes":["「柯珥」﹕亞蘭文音譯，即希伯來固體容量單位「歌珥」；參「度量衡表」。"]},{"n":23,"t":"凡天上之神所吩咐的，當為天上之神的殿切實辦理。何必使憤怒臨到王和王眾子的國呢？","notes":[]},{"n":24,"t":"我再吩咐你們：至於任何祭司、利未人、歌唱的、門口的守衛和殿役，以及在神的這殿事奉的人，不可要求他們進貢，納糧，繳稅。』","notes":[]},{"n":25,"t":"「你，以斯拉啊，要照著你神賜你的智慧，指派所有明白你神律法的人作官長、審判官，治理河西所有的百姓，教導不明白神律法的人。","notes":[]},{"n":26,"t":"凡不遵行你神律法和王命令的人，當速速定他的罪，或處死，或充軍，或抄家，或囚禁。」","notes":[]},{"n":27,"t":"以斯拉說：「耶和華－我們列祖的神是應當稱頌的！因他使王起這心願，使耶路撒冷耶和華的殿得榮耀，","notes":[],"heads":["以斯拉稱頌耶和華"]},{"n":28,"t":"他又在王和謀士，以及王所有大能的軍官面前施恩於我。我因耶和華－我神的手的幫助，得以堅強，從以色列中召集領袖，與我一同上來。」","notes":[]}]},"8":{"heading":"從被擄之地回來的人","verses":[{"n":1,"t":"這些是亞達薛西王在位的時候，同我從巴比倫上來的族長和他們的家譜：","notes":[]},{"n":2,"t":"屬非尼哈的子孫有革順；屬以他瑪的子孫有但以理；屬大衛的子孫有哈突；","notes":[]},{"n":3,"t":"屬示迦尼的子孫；屬巴錄的子孫有撒迦利亞，同著他按家譜計算，男丁一百五十人；","notes":[]},{"n":4,"t":"屬巴哈‧摩押的子孫有西拉希雅的兒子以利約乃，同著他有男丁二百人；","notes":[]},{"n":5,"t":"屬薩土的子孫有雅哈悉的兒子示迦尼，同著他有男丁三百人；","notes":["「屬薩土<ins>.示迦尼」是根據七十士譯本；原文是「屬示迦尼的子孫有雅哈悉的兒子」。"]},{"n":6,"t":"屬亞丁的子孫有約拿單的兒子以別，同著他有男丁五十人；","notes":[]},{"n":7,"t":"屬以攔的子孫有亞他利雅的兒子耶篩亞，同著他有男丁七十人；","notes":[]},{"n":8,"t":"屬示法提雅的子孫有米迦勒的兒子西巴第雅，同著他有男丁八十人；","notes":[]},{"n":9,"t":"屬約押的子孫有耶歇的兒子俄巴底亞，同著他有男丁二百一十八人；","notes":[]},{"n":10,"t":"屬巴尼的子孫有約細斐的兒子示羅密，同著他有男丁一百六十人；","notes":["「屬巴尼</ins>.示羅密」是根據七十士譯本；原文是「屬示羅密的子孫有約細斐的兒子」。"]},{"n":11,"t":"屬比拜的子孫有比拜的兒子撒迦利亞，同著他有男丁二十八人；","notes":[]},{"n":12,"t":"屬押甲的子孫有哈加坦的兒子約哈難，同著他有男丁一百一十人；","notes":[]},{"n":13,"t":"屬亞多尼干的子孫，就是晚到的，他們的名字是以利法列、耶利、示瑪雅，同著他們有男丁六十人；","notes":[]},{"n":14,"t":"屬比革瓦伊的子孫有烏太和撒刻，同著他們有男丁七十人。","notes":["「撒刻」：原文另譯「撒布」。"]},{"n":15,"t":"我召集這些人在流入亞哈瓦的河旁邊，我們在那裏紮營三日。我查看百姓和祭司，發現並沒有利未人在那裏，","notes":[],"heads":["以斯拉召集利未人"]},{"n":16,"t":"就派人到以利以謝、亞列、示瑪雅、以利拿單、雅立、以利拿單、拿單、撒迦利亞、米書蘭等領袖，以及約雅立和以利拿單教師那裏。","notes":["七十士譯本的一些抄本沒有「約雅立和以利拿單」。"]},{"n":17,"t":"我吩咐他們往迦西斐雅地方去見那裏的領袖易多，又告訴他們當向易多和他的弟兄，就是迦西斐雅那地方的殿役說甚麼話，好為我們神的殿帶事奉的人來。","notes":[]},{"n":18,"t":"蒙我們神施恩的手幫助我們，他們在以色列的曾孫，利未的孫子，抹利的後裔中帶了一個精明的人來，就是示利比，還有他的眾子與兄弟共十八人。","notes":[]},{"n":19,"t":"另外，還有哈沙比雅，同著他有米拉利的子孫耶篩亞，以及他的眾子和兄弟共二十人。","notes":[]},{"n":20,"t":"從前大衛和眾領袖派殿役服事利未人，現在從這殿役中也帶了二百二十人來，全都是按名指定的。","notes":[]},{"n":21,"t":"那時，我在亞哈瓦河邊宣告禁食，為要在我們神面前刻苦己心，求他使我們和我們的孩子，以及一切所有的，都得平坦的道路。","notes":[],"heads":["以斯拉禁食禱告"]},{"n":22,"t":"我以求王撥步兵騎兵幫助我們抵擋路上的仇敵為羞愧，因我們曾對王說：「我們神施恩的手必幫助凡尋求他的，但他的能力和憤怒必攻擊凡離棄他的。」","notes":[]},{"n":23,"t":"我們為此禁食祈求我們的神，他就應允我們。","notes":[]},{"n":24,"t":"我分派十二位祭司長，就是示利比、哈沙比雅和與他們一起的兄弟十人，","notes":[],"heads":["獻給聖殿的禮物"]},{"n":25,"t":"把王和謀士、軍官，並在那裏的以色列眾人為我們神殿所獻的金銀和器皿，都秤了交給他們。","notes":[]},{"n":26,"t":"我秤了交在他們手中的有六百五十他連得銀子，一百他連得銀器，一百他連得金子，","notes":[]},{"n":27,"t":"二十個金碗，值一千達利克，上等光亮的銅器皿兩個，珍貴如金。","notes":[]},{"n":28,"t":"我對他們說：「你們歸耶和華為聖，器皿也歸為聖；金銀是甘心獻給耶和華－你們列祖之神的。","notes":[]},{"n":29,"t":"你們要警醒看守，直到你們在祭司長和利未族長，以及以色列的各族長面前，在耶路撒冷耶和華殿的庫房內，把這些過了秤。」","notes":[]},{"n":30,"t":"於是，祭司和利未人把秤過的金銀和器皿接過來，要帶到耶路撒冷我們神的殿裏。","notes":[]},{"n":31,"t":"正月十二日，我們從亞哈瓦河邊起行，要往耶路撒冷去。我們神的手保佑我們，救我們脫離仇敵和路上埋伏之人的手。","notes":[],"heads":["返回耶路撒冷"]},{"n":32,"t":"我們到了耶路撒冷，在那裏住了三日。","notes":[]},{"n":33,"t":"第四日，金銀和器皿都在我們神的殿裏過了秤，交在烏利亞的兒子米利末祭司的手中。同著他的有非尼哈的兒子以利亞撒，還有利未人耶書亞的兒子約撒拔和賓內的兒子挪亞底。","notes":[]},{"n":34,"t":"那時，這一切都點過秤過了，重量全寫在冊上。","notes":[]},{"n":35,"t":"從被擄之地歸回的人向以色列的神獻燔祭，為以色列眾人獻十二頭公牛、九十六隻公綿羊、七十七隻小綿羊，又獻十二隻公山羊作贖罪祭，這些全都是獻給耶和華的燔祭。","notes":[]},{"n":36,"t":"被擄歸回的人把王的諭旨交給王的總督與河西的省長，他們就支助百姓和神的殿。","notes":[]}]},"9":{"heading":"譴責跟異族通婚","verses":[{"n":1,"t":"這些事完成以後，眾領袖來接近我，說：「以色列百姓、祭司和利未人沒有棄絕迦南人、赫人、比利洗人、耶布斯人、亞捫人、摩押人、埃及人和亞摩利人等列邦民族所行可憎的事。","notes":[]},{"n":2,"t":"因他們為自己和兒子娶了這些外邦女子，以致聖潔的種籽和列邦民族混雜，而且領袖和官長在這事上是罪魁。」","notes":[]},{"n":3,"t":"我一聽見這事，就撕裂衣服和外袍，拔了頭髮和鬍鬚，驚惶地坐著。","notes":[]},{"n":4,"t":"凡為以色列神言語戰兢的人，都因被擄歸回之人所犯的罪，聚集到我這裏來。我驚惶地坐著，直到獻晚祭的時候。","notes":[]},{"n":5,"t":"獻晚祭的時候我從愁煩中起來，穿著撕裂的衣服和外袍，雙膝跪下，向耶和華－我的神舉手，","notes":[]},{"n":6,"t":"說：「我的神啊，我抱愧蒙羞，不敢向你－我的神仰面，因為我們的罪孽多到滅頂，我們的罪惡滔天。","notes":[]},{"n":7,"t":"從我們祖先的日子直到今日，我們的罪惡深重；因我們的罪孽，我們和君王、祭司都交在鄰國諸王的手中，被殺害，擄掠，搶奪，臉上蒙羞，正如今日的景況。","notes":[]},{"n":8,"t":"現在耶和華－我們的神暫且向我們施恩，為我們留下一些殘存之民，使我們如釘子釘在他的聖所，讓我們的神光照我們的眼目，使我們在受轄制之中稍微復興。","notes":[]},{"n":9,"t":"我們是奴僕，然而在受轄制之中，我們的神沒有丟棄我們，在波斯諸王面前向我們施恩，叫我們復興，能重建我們神的殿，修補毀壞之處，使我們在猶大和耶路撒冷有城牆。","notes":[]},{"n":10,"t":"「我們的神啊，既然如此，現在我們還有甚麼話可說呢？因為我們離棄了你的誡命，","notes":[]},{"n":11,"t":"就是你藉你僕人眾先知所吩咐的，說：『你們要去得為業之地是污穢之地，因列邦民族的污穢和可憎的事，叫這地從這邊到那邊都充滿了污穢。","notes":[]},{"n":12,"t":"現在，不可把你們的女兒嫁給他們的兒子，也不可為你們的兒子娶他們的女兒，永不可求他們的平安和他們的利益，這樣你們就可以強盛，吃這地的美物，並把這地留給你們的子孫永遠為業。』","notes":[]},{"n":13,"t":"我們因自己的惡行和大罪，遭遇這一切的事，但你－我們的神懲罰我們輕於我們罪所當得的，又為我們留下這些殘存之民。","notes":[]},{"n":14,"t":"我們豈可再違背你的誡命，與行這些可憎之事的民族結親呢？若我們這樣行，你豈不向我們發怒，將我們滅絕，以致沒有一個餘民或殘存之民嗎？","notes":[]},{"n":15,"t":"耶和華－以色列的神啊，你是公義的，我們才能剩下這些殘存之民，正如今日的景況。看哪，我們在你面前有罪惡，因此無人能在你面前站立得住。」","notes":[]}]},"10":{"heading":"終止與異族通婚的措施","verses":[{"n":1,"t":"以斯拉禱告，認罪，哭泣，俯伏在神殿前的時候，有以色列中的男女和孩童聚集到以斯拉那裏，成了一個盛大的會，百姓無不痛哭。","notes":[]},{"n":2,"t":"以攔的子孫，耶歇的兒子示迦尼對以斯拉說：「我們娶了這地的外邦女子，干犯了我們的神，然而現在以色列人在這事上還有指望。","notes":[]},{"n":3,"t":"現在，我們要與我們的神立約，送走所有的妻子和她們所生的，照著主和那些因我們神誡命戰兢之人所議定的，按律法去行。","notes":[]},{"n":4,"t":"起來，這是你當辦的事，我們必支持你，你當奮勇而行。」","notes":[]},{"n":5,"t":"以斯拉就起來，叫祭司長和利未人，以及以色列眾人起誓，要照這話去做；他們就起了誓。","notes":[]},{"n":6,"t":"以斯拉從神殿前起來，進入以利亞實的兒子約哈難的屋裏，到了那裏不吃飯，也不喝水，為被擄歸回之人所犯的罪悲傷。","notes":[]},{"n":7,"t":"他們通告猶大和耶路撒冷，叫所有被擄歸回的人聚集在耶路撒冷。","notes":[]},{"n":8,"t":"凡不遵照領袖和長老所議定，三日之內不來的，就必毀壞他所有的財產，把他從被擄歸回之人的會中開除。","notes":[]},{"n":9,"t":"於是，猶大和便雅憫眾人三日之內都聚集在耶路撒冷。那時是九月，那月的二十日，眾百姓坐在神殿前的廣場，因這事，又因下大雨，就都戰抖。","notes":[]},{"n":10,"t":"以斯拉祭司站起來，對他們說：「你們有罪了，因為你們娶了外邦女子，增添以色列的罪惡。","notes":[]},{"n":11,"t":"現在當向耶和華－你們列祖的神認罪，遵行他的旨意，離開這地的百姓和外邦女子。」","notes":[]},{"n":12,"t":"全會眾大聲回答說：「好！我們必照著你的話去做。","notes":[]},{"n":13,"t":"只是百姓眾多，又逢大雨的季節，我們沒有氣力站在外面；這也不是一兩天可以辦完的事，因我們在這事上犯了大罪。","notes":[]},{"n":14,"t":"讓我們的領袖代表全會眾留在那裏。我們城鎮中凡娶外邦女子的，當按所定的日期，會同本城的長老和審判官前來，直到辦完這事，神的烈怒轉離我們。」","notes":["「直到...轉離我們」：有些古卷和七十士譯本是「直到神因這事的烈怒轉離我們」。"]},{"n":15,"t":"惟有亞撒黑的兒子約拿單，特瓦的兒子雅哈謝反對這事，並有米書蘭和利未人沙比太支持他們。","notes":[]},{"n":16,"t":"被擄歸回的人就如此做了。以斯拉祭司按著父家指名選派一些族長。十月初一，他們一同坐下來查辦這事，","notes":["「以斯拉...族長」是根據七十士譯本的一些抄本和其他古譯本；原文是「選出來的有以斯拉祭司、一些人和按著父家所有指名的族長」。"]},{"n":17,"t":"到正月初一，才查清所有娶外邦女子的人數。","notes":[]},{"n":18,"t":"在祭司中查出娶外邦女子的：耶書亞的子孫中，有約薩達的兒子，和他兄弟瑪西雅、以利以謝、雅立、基大利，","notes":[],"heads":["娶外邦女子的人"]},{"n":19,"t":"他們承諾要送走他們的妻子。他們因有罪，就獻羊群中的一隻公綿羊贖罪；","notes":[]},{"n":20,"t":"音麥的子孫中，有哈拿尼、西巴第雅；","notes":[]},{"n":21,"t":"哈琳的子孫中，有瑪西雅、以利雅、示瑪雅、耶歇、烏西雅；","notes":[]},{"n":22,"t":"巴施戶珥的子孫中，有以利約乃、瑪西雅、以實瑪利、拿坦業、約撒拔、以利亞薩。","notes":[]},{"n":23,"t":"利未人中，有約撒拔、示每、基拉雅，基拉雅就是基利他，還有毗他希雅、猶大、以利以謝。","notes":[]},{"n":24,"t":"歌唱的人中有以利亞實。門口的守衛中，有沙龍、提聯、烏利。","notes":[]},{"n":25,"t":"以色列人巴錄的子孫中，有拉米、耶西雅、瑪基雅、米雅民、以利亞撒、瑪基雅、比拿雅。","notes":[]},{"n":26,"t":"以攔的子孫中，有瑪他尼、撒迦利亞、耶歇、押底、耶列末、以利雅。","notes":[]},{"n":27,"t":"薩土的子孫中，有以利約乃、以利亞實、瑪他尼、耶列末、撒拔、亞西撒。","notes":[]},{"n":28,"t":"比拜的子孫中，有約哈難、哈拿尼雅、薩拜、亞勒。","notes":[]},{"n":29,"t":"巴尼的子孫中，有米書蘭、瑪鹿、亞大雅、雅述、示押、拉末。","notes":["「拉末」：原文另譯「耶列末」。"]},{"n":30,"t":"巴哈‧摩押的子孫中，有阿底拿、基拉、比拿雅、瑪西雅、瑪他尼、比撒列、賓內、瑪拿西。","notes":[]},{"n":31,"t":"哈琳的子孫中，有以利以謝、伊示雅、瑪基雅、示瑪雅、西緬、","notes":[]},{"n":32,"t":"便雅憫、瑪鹿、示瑪利雅。","notes":[]},{"n":33,"t":"哈順的子孫中，有瑪特乃、瑪達他、撒拔、以利法列、耶利買、瑪拿西、示每。","notes":[]},{"n":34,"t":"巴尼的子孫中，有瑪玳、暗蘭、烏益、","notes":[]},{"n":35,"t":"比拿雅、比底雅、基祿、","notes":[]},{"n":36,"t":"瓦尼雅、米利末、以利亞實、","notes":[]},{"n":37,"t":"瑪他尼、瑪特乃、雅掃、","notes":[]},{"n":38,"t":"巴尼、賓內、示每、","notes":[]},{"n":39,"t":"示利米雅、拿單、亞大雅、","notes":[]},{"n":40,"t":"瑪拿底拜、沙賽、沙賴、","notes":[]},{"n":41,"t":"亞薩利、示利米雅、示瑪利雅、","notes":[]},{"n":42,"t":"沙龍、亞瑪利雅、約瑟。","notes":[]},{"n":43,"t":"尼波的子孫中，有耶利、瑪他提雅、撒拔、西比拿、雅玳、約珥、比拿雅。","notes":[]},{"n":44,"t":"這些人全都娶了外邦女子，其中也有生了兒女的。","notes":["「其中也有生了兒女的」：原文另譯「他們就將妻子和兒女送走」。"]}]}},"NEH":{"1":{"heading":"尼希米關心耶路撒冷","verses":[{"n":1,"t":"哈迦利亞的兒子尼希米的言語如下：亞達薛西王二十年基斯流月，我在書珊城堡中。","notes":[]},{"n":2,"t":"那時，我有一個兄弟哈拿尼，同幾個人從猶大來。我問他們那些被擄歸回、剩下殘存的猶太人和耶路撒冷的情況。","notes":[]},{"n":3,"t":"他們對我說：「那些被擄歸回剩下的餘民在猶大省那裏遭大難，受凌辱；耶路撒冷的城牆被拆毀，城門被火焚燒。」","notes":[]},{"n":4,"t":"我聽見這話，就坐下哭泣，悲哀幾日，在天上的神面前禁食祈禱，","notes":[]},{"n":5,"t":"說：「唉，耶和華－天上大而可畏的神，向愛你、守你誡命的人守約施慈愛的神啊，","notes":[]},{"n":6,"t":"願你睜眼看，側耳聽你僕人今日晝夜在你面前，為你眾僕人以色列人的祈禱，承認我們以色列人向你所犯的罪；我與我父家都犯了罪。","notes":[]},{"n":7,"t":"我們向你所行的非常敗壞，沒有遵守你吩咐你僕人摩西的誡命、律例、典章。","notes":[]},{"n":8,"t":"求你記念所吩咐你僕人摩西的話，說：『你們若犯罪，我就把你們分散在萬民中；","notes":[]},{"n":9,"t":"但你們若歸向我，謹守遵行我的誡命，你們被趕散的人雖在天涯，我也必從那裏將他們召集回來，帶到我所選擇立為我名居所的地方。』","notes":[]},{"n":10,"t":"他們是你的僕人和你的百姓，是你用大力和大能的手所救贖的。","notes":[]},{"n":11,"t":"唉，主啊，求你側耳聽你僕人的祈禱，聽喜愛敬畏你名眾僕人的祈禱，使你僕人今日亨通，在這人面前蒙恩。」我是王的酒政。","notes":[]}]},"2":{"heading":"尼希米返回耶路撒冷","verses":[{"n":1,"t":"亞達薛西王二十年尼散月，酒擺在王面前，我拿起酒來奉給王。我在王面前從來沒有愁容。","notes":["「王面前」：七十士譯本和古譯本是「我面前」。"]},{"n":2,"t":"王對我說：「你既沒有病，為甚麼面帶愁容呢？這不是別的，必是你心中愁煩。」於是我非常懼怕。","notes":[]},{"n":3,"t":"我對王說：「願王萬歲！我祖先墳墓所在的那城荒涼，城門被火焚燒，我豈能面無愁容呢？」","notes":[]},{"n":4,"t":"王對我說：「你想求甚麼？」於是我向天上的神祈禱。","notes":[]},{"n":5,"t":"我對王說：「王若以為好，僕人若在王面前蒙恩，求王差遣我往猶大，到我祖先墳墓所在的那城去，我好重新建造。」","notes":[]},{"n":6,"t":"那時王后坐在王的旁邊，王對我說：「你要去多久？幾時回來？」王看這事為好，就派我去。我給王定了日期。","notes":[]},{"n":7,"t":"我又對王說：「王若以為好，求王賜我詔書，通知河西的省長准我經過，直到猶大；","notes":[]},{"n":8,"t":"又賜詔書，通知管理王園林的亞薩，叫他給我木材，作為殿的營樓之門、城牆，和我自己要住的房屋的橫梁。」王就允准我，因為我神施恩的手幫助我。","notes":[]},{"n":9,"t":"王派了軍官和騎兵護送我。我到了河西的省長那裏，將王的詔書交給他們。","notes":[]},{"n":10,"t":"和倫人參巴拉和作臣僕的亞捫人多比雅，聽見有人來為以色列人爭取利益，就很惱怒。","notes":[]},{"n":11,"t":"我到了耶路撒冷，在那裏停留了三天。","notes":[]},{"n":12,"t":"夜間我和跟隨我的幾個人起來；但神感動我心要為耶路撒冷做的事，我並沒有告訴人。只有我自己騎的牲口，沒有別的牲口在我那裏。","notes":[]},{"n":13,"t":"當夜，我出了谷門，往野狗泉去，到了糞廠門，察看耶路撒冷的城牆，城牆被拆毀，城門被火焚燒。","notes":[]},{"n":14,"t":"我又往前，到了泉門，又到王池，但所騎的牲口沒有地方可以過去。","notes":[]},{"n":15,"t":"於是我夜間沿溪而上，察看城牆，又轉身進入谷門，就回來了。","notes":[]},{"n":16,"t":"我往哪裏去，我做甚麼事，官長都不知道。我也沒有告訴猶大人、祭司、貴族、官長和其餘做工的人。","notes":[]},{"n":17,"t":"以後，我對他們說：「我們所遭的難，耶路撒冷怎樣荒涼，城門被火焚燒，你們都看見了。來吧，讓我們重建耶路撒冷的城牆，免得再受凌辱！」","notes":[]},{"n":18,"t":"我告訴他們我神施恩的手怎樣幫助我，以及王向我所說的話。他們就說：「我們起來建造吧！」於是他們使自己的手堅強，做這美好的工作。","notes":[]},{"n":19,"t":"但和倫人參巴拉、作臣僕的亞捫人多比雅和阿拉伯人基善聽見就嗤笑我們，藐視我們，說：「你們所做的這事是甚麼呢？要背叛王嗎？」","notes":[]},{"n":20,"t":"我回答他們的話，對他們說：「天上的神必使我們亨通。我們作他僕人的，要起來建造；你們卻在耶路撒冷無份、無權、無名號。」","notes":["「名號」：原文是「紀念」，意思是「使人記得他們」。"]}]},"3":{"heading":"重建耶路撒冷城牆","verses":[{"n":1,"t":"那時，以利亞實大祭司和他的弟兄眾祭司起來建立羊門，將門分別為聖，安立門扇，直到哈米亞樓。他們又將它分別為聖，直到哈楠業樓。","notes":[]},{"n":2,"t":"在他旁邊建造的是耶利哥人。在他旁邊建造的是音利的兒子撒刻。","notes":[]},{"n":3,"t":"哈西拿的子孫建立魚門，架橫梁、安門扇，裝閂和鎖。","notes":[]},{"n":4,"t":"在他們旁邊修造的是哈哥斯的孫子，烏利亞的兒子米利末。在他們旁邊修造的是米示薩別的孫子，比利迦的兒子米書蘭。在他們旁邊修造的是巴拿的兒子撒督。","notes":[]},{"n":5,"t":"在他們旁邊修造的是提哥亞人；但是他們的貴族不用肩扛他們主人的工作。","notes":["「肩」：原文是「頸項」。"]},{"n":6,"t":"巴西亞的兒子耶何耶大與比所玳的兒子米書蘭修造古門，架橫梁，安門扇，裝閂和鎖。","notes":[]},{"n":7,"t":"在他們旁邊修造的是基遍人米拉提、米倫人雅頓、基遍人，和河西總督所管的米斯巴人。","notes":[]},{"n":8,"t":"在他旁邊修造的是哈海雅的兒子烏薛銀匠。在他旁邊修造的是做香料的哈拿尼雅。他們修復耶路撒冷，直到寬牆。","notes":[]},{"n":9,"t":"在他們旁邊修造的是管理耶路撒冷城區的一半、戶珥的兒子利法雅。","notes":[]},{"n":10,"t":"在他們旁邊的是哈路抹的兒子耶大雅在自己房屋的對面修造。在他旁邊修造的是哈沙尼的兒子哈突。","notes":[]},{"n":11,"t":"哈琳的兒子瑪基雅和巴哈‧摩押的兒子哈述修造下一段和爐樓。","notes":[]},{"n":12,"t":"在他旁邊修造的是管理耶路撒冷城區的另一半、哈羅黑的兒子沙龍和他的女兒們。","notes":[]},{"n":13,"t":"哈嫩和撒挪亞的居民修造谷門；他們立門，安門扇，裝閂和鎖，又修造城牆一千肘，直到糞廠門。","notes":[]},{"n":14,"t":"管理伯‧哈基琳區、利甲的兒子瑪基雅修造糞廠門；他立門，安門扇，裝閂和鎖。","notes":[]},{"n":15,"t":"管理米斯巴區、各‧荷西的兒子沙崙修造泉門；他立門，蓋門頂，安門扇，裝閂和鎖，又修造靠近王的花園西羅亞池的城牆，直到那從大衛城下來的臺階。","notes":[]},{"n":16,"t":"接續他修造的是管理伯‧夙區的一半、押卜的兒子尼希米，直到大衛墳地的對面，又到人造池，到達勇士的房屋。","notes":[]},{"n":17,"t":"接續他修造的是利未人巴尼的兒子利宏。在他旁邊的是管理基伊拉區一半的哈沙比雅為本區修造。","notes":[],"heads":["造城牆的利未人"]},{"n":18,"t":"接續他修造的是他們弟兄中管理基伊拉區的另一半、希拿達的兒子賓內。","notes":["「賓內」是根據一些古卷、七十士譯本和其他古譯本；原文是「巴瓦伊」。"]},{"n":19,"t":"在他旁邊的是管理米斯巴、耶書亞的兒子以謝珥修造武庫的上坡對面、城牆轉彎處的那一段。","notes":[]},{"n":20,"t":"接續他的是薩拜的兒子巴錄竭力修造下一段，從轉彎處，直到以利亞實大祭司的府門。","notes":[]},{"n":21,"t":"接續他的是哈哥斯的孫子，烏利亞的兒子米利末修造下一段，從以利亞實的府門，直到以利亞實府的盡頭。","notes":[]},{"n":22,"t":"接續他修造的是住平原的祭司。","notes":[],"heads":["造城牆的祭司"]},{"n":23,"t":"接續他的是便雅憫與哈述在自己房屋的對面修造。接續他的是亞難尼的孫子，瑪西雅的兒子亞撒利雅在自己房屋的旁邊修造。","notes":[]},{"n":24,"t":"接續他的是希拿達的兒子賓內修造下一段，從亞撒利雅的房屋直到轉彎處，又到城角。","notes":[]},{"n":25,"t":"烏賽的兒子巴拉修造轉彎處的對面和靠近護衛院、王宮上層凸出來的城樓。接續他的是巴錄的兒子毗大雅，","notes":[]},{"n":26,"t":"（殿役住在俄斐勒，直到朝東水門的對面和凸出來的城樓。）","notes":[]},{"n":27,"t":"接續他的是提哥亞人又修造一段，對著那凸出來的大城樓，直到俄斐勒的城牆。","notes":[]},{"n":28,"t":"從馬門往上，祭司各在自己房屋的對面修造。","notes":[]},{"n":29,"t":"接續他的是音麥的兒子撒督在自己房屋的對面修造。接續他修造的是東門的守衛、示迦尼的兒子示瑪雅。","notes":[]},{"n":30,"t":"接續他的是示利米雅的兒子哈拿尼雅和薩拉的第六個兒子哈嫩修造下一段。接續他的是比利迦的兒子米書蘭在自己房屋的對面修造。","notes":[]},{"n":31,"t":"接續他的是瑪基雅銀匠修造，直到殿役和商人的房屋，對著集合門，直到角樓。","notes":["「集合門」或音譯「哈米弗甲門」。"]},{"n":32,"t":"銀匠與商人在角樓和羊門之間修造。","notes":[]}]},"4":{"heading":"尼希米勝過阻擋他工作的人","verses":[{"n":1,"t":"參巴拉聽見我們建造城牆就發怒，非常惱恨，並嗤笑猶太人。","notes":[]},{"n":2,"t":"他對他的弟兄和撒瑪利亞的軍兵說：「這些軟弱的猶太人做甚麼呢？要為自己重建嗎？要獻祭嗎？要一日完工嗎？要使土堆裏火燒過的石頭再有用嗎？」","notes":["「要為自己重建嗎」或譯「要把一切交託神嗎」。"]},{"n":3,"t":"亞捫人多比雅在一旁說：「他們所修造的石牆，就是狐狸上去也必崩裂。」","notes":[]},{"n":4,"t":"我們的神啊，求你垂聽，因為我們被藐視。求你使他們的毀謗歸於他們自己頭上，使他們在被擄之地成為掠物。","notes":[]},{"n":5,"t":"不要遮掩他們的罪孽，不要使他們的罪惡從你面前塗去，因為他們在修造的人前面惹你發怒。","notes":[]},{"n":6,"t":"這樣，我們修造城牆，整個城牆就連接起來，到一半高，因為百姓一心做工。","notes":[]},{"n":7,"t":"參巴拉、多比雅、阿拉伯人、亞捫人和亞實突人聽見耶路撒冷城牆正在修造，破裂的地方開始進行修補，就非常憤怒。","notes":[]},{"n":8,"t":"大家同謀要來攻打耶路撒冷，使城混亂。","notes":[]},{"n":9,"t":"然而，我們向我們的神禱告，又因他們的緣故，就派人站崗，晝夜防備他們。","notes":[]},{"n":10,"t":"但猶大有話說：「扛抬的人力氣衰弱，瓦礫太多，我們自己不可能建造城牆。」","notes":[]},{"n":11,"t":"我們的敵人說：「趁他們不知道，看不見的時候，我們進入他們中間，殺了他們，使工作停止。」","notes":[]},{"n":12,"t":"那靠近敵人居住的猶太人十次從各處來見我們，說：「你們必須回到我們那裏。」","notes":[]},{"n":13,"t":"我叫百姓站在城牆後邊低窪的空處，使百姓各按宗族站著，拿刀、拿槍、拿弓。","notes":[]},{"n":14,"t":"我察看了，就起來對貴族、官長和其餘的百姓說：「不要怕他們！當記得主是大而可畏的。你們要為你們的弟兄、兒女、妻子、家園爭戰。」","notes":[]},{"n":15,"t":"仇敵聽見我們知道了他們的計謀，神也破壞他們的計謀，我們就都回到城牆那裏，各做各的工。","notes":[]},{"n":16,"t":"從那日起，我的僕人一半做工，一半拿槍、拿盾牌、拿弓、穿鎧甲，官長都站在猶大全家的後邊。","notes":[]},{"n":17,"t":"他們建造城牆；扛抬材料的人扛抬的時候，一手做工，一手拿兵器。","notes":[]},{"n":18,"t":"建造的人都腰間佩刀建造，吹角的人在我旁邊。","notes":[]},{"n":19,"t":"我對貴族、官長和其餘的百姓說：「這工程浩大，範圍遼闊，我們在城牆上彼此相離很遠。","notes":[]},{"n":20,"t":"你們一聽見角聲在哪裏，就聚集到我們那裏去。我們的神必為我們爭戰。」","notes":[]},{"n":21,"t":"於是，我們做這工程，一半的人拿槍，從天亮直到星宿出現的時候。","notes":[]},{"n":22,"t":"那時，我又對百姓說：「各人和他的僕人當在耶路撒冷過夜，好為我們夜間守衛，白晝做工。」","notes":[]},{"n":23,"t":"這樣，我和弟兄僕人，以及跟從我的衛兵都不脫衣服，各人打水時也拿著自己的兵器。","notes":["「打水時」：原文另譯「手裏」或「右手」。"]}]},"5":{"heading":"尼希米處理官長們的剝削","verses":[{"n":1,"t":"百姓和他們的妻子大大呼號，埋怨他們的弟兄猶太人。","notes":[]},{"n":2,"t":"有的說：「我們和兒女人口眾多，必須得糧食吃，才能活下去。」","notes":[]},{"n":3,"t":"有的說：「我們典押了田地、葡萄園、房屋，才得糧食充飢。」","notes":[]},{"n":4,"t":"有的說：「我們借了錢付田地和葡萄園的稅給王。","notes":[]},{"n":5,"t":"現在，我們的身體與我們弟兄的身體是一樣的，我們的兒女與他們的兒女沒有差別。看哪，我們卻要迫使兒女作人的奴婢。我們有些女兒已被搶走了，我們卻無能為力，因為我們的田地和葡萄園已經歸了別人。」","notes":[]},{"n":6,"t":"我聽見他們的呼號和這些話，就非常憤怒。","notes":[]},{"n":7,"t":"我心裏作了決定，就斥責貴族和官長，對他們說：「你們各人借錢給弟兄，竟然索取利息！」於是我召開大會攻擊他們。","notes":[]},{"n":8,"t":"我對他們說：「我們已盡力贖回我們的弟兄，就是賣到列國的猶太人；你們還要賣弟兄，讓我們去買回來嗎？」他們就靜默不語，無話可答。","notes":[]},{"n":9,"t":"我又說：「你們做的這事不對！你們行事不是應該敬畏我們的神，免得列國我們的仇敵毀謗我們嗎？","notes":[]},{"n":10,"t":"我和我的弟兄僕人也要把銀錢糧食借給百姓，大家都當免除利息。","notes":[]},{"n":11,"t":"就在今日，你們要把他們的田地、葡萄園、橄欖園、房屋，以及向他們所取銀錢的利息、糧食、新酒和新油都歸還他們。」","notes":["「銀錢的利息」或譯「百分之一的銀錢」。"]},{"n":12,"t":"貴族和官長說：「我們必歸還，不再向他們索取，必照你所說的去做。」我就召了祭司來，叫貴族和官長起誓，必照這話去做。","notes":[]},{"n":13,"t":"我也抖著胸前的衣袋，說：「凡不實行這話的，願神照樣抖他離開他的家和他勞碌得來的，直到抖空了。」全會眾都說：「阿們！」又讚美耶和華。百姓就照著這話去做。","notes":[]},{"n":14,"t":"自從我奉派作猶大地省長的那日，就是從亞達薛西王二十年直到三十二年，共十二年之久，我與我弟兄都沒有吃省長的俸祿。","notes":[],"heads":["尼希米大公無私"]},{"n":15,"t":"在我以前的省長加重百姓的負擔，向百姓索取糧食和酒，以及四十舍客勒銀子，甚至他們的僕人也轄制百姓，但我因敬畏神不這樣做。","notes":["「向百姓...銀子」：有古譯本是「每日向百姓索取糧食、酒、四十舍客勒銀子」。"]},{"n":16,"t":"我也努力修造城牆。我們並沒有購置田地，我所有的僕人也都聚集在那裏做工。","notes":[]},{"n":17,"t":"除了從四圍列國來的人以外，有猶太人和官長一百五十人與我同席。","notes":[]},{"n":18,"t":"每日預備一頭公牛、六隻肥羊，又為我預備飛禽；每十日一次多多預備各樣的酒。雖然如此，我並不索取省長的俸祿，因為這百姓負的勞役很重。","notes":[]},{"n":19,"t":"我的神啊，求你記念我為這百姓所做的一切，施恩於我。","notes":[]}]},"6":{"heading":"敵對尼希米的陰謀","verses":[{"n":1,"t":"參巴拉、多比雅、阿拉伯人基善和我們其餘的仇敵聽見我已經建造了城牆，沒有破裂之處在其中，那時我還沒有在城門安門扇；","notes":[]},{"n":2,"t":"參巴拉和基善就派人來見我，說：「請你來，我們在阿挪平原的村莊見面。」其實，他們想要害我。","notes":[]},{"n":3,"t":"於是我派使者到他們那裏，說：「我正在進行大的工程，不能下去。我怎麼能離開，下去見你們，而讓工程停頓呢？」","notes":[]},{"n":4,"t":"他們這樣派人來見我四次，我都用這話回答他們。","notes":[]},{"n":5,"t":"參巴拉第五次同樣派僕人來見我，手裏拿著未封的信，","notes":[]},{"n":6,"t":"信上寫著：「列國中有風聲，基善也說，你和猶太人謀反，所以你建造城牆。據說，你要作他們的王，","notes":["「基善」：參尼2．19﹔原文譯「迦施慕」。"]},{"n":7,"t":"並且你派先知在耶路撒冷指著你宣講說，『在猶大有王。』如今這些話必傳給王知，現在請你來，我們一起商議。」","notes":[]},{"n":8,"t":"我就派人到他那裏，說：「你所說的這些事，一概沒有，是你心裏捏造的。」","notes":[]},{"n":9,"t":"他們全都要使我們懼怕，說：「他們的手必軟弱，不能工作，以致不能完工。」現在，求你堅固我的手。","notes":[]},{"n":10,"t":"我到了米希大別的孫子，第來雅的兒子示瑪雅家裏；那時，他閉門不出。他說：「我們可以在神的殿裏，就在殿的中間會面，鎖住殿門，因為他們要來殺你，要在夜裏來殺你。」","notes":[]},{"n":11,"t":"我說：「像我這樣的人豈會逃跑呢？像我這樣的人豈能進入殿裏保全生命呢？我不進去！」","notes":[]},{"n":12,"t":"我看清楚了，看哪，神並沒有派他，是他自己說預言攻擊我，是多比雅和參巴拉收買了他；","notes":[]},{"n":13,"t":"收買他的目的是要叫我懼怕，依從他犯罪，留下一個壞名聲，好讓他們毀謗我。","notes":[]},{"n":14,"t":"我的神啊，求你記得多比雅、參巴拉、挪亞底女先知和其餘的先知，因他們行這些事，要叫我懼怕。","notes":[]},{"n":15,"t":"以祿月二十五日，城牆修完了，共修了五十二天。","notes":[],"heads":["工程結束"]},{"n":16,"t":"我們所有的仇敵聽見了，四圍的列國就懼怕，愁眉不展，因為他們知道這工作得以完成，是出於我們的神。","notes":[]},{"n":17,"t":"而且，在那些日子，猶大的貴族屢次寄信給多比雅，多比雅也回信給他們。","notes":[]},{"n":18,"t":"在猶大有許多人與多比雅結盟，因為他是亞拉的兒子示迦尼的女婿，並且他的兒子約哈難娶了比利迦的兒子米書蘭的女兒。","notes":[]},{"n":19,"t":"他們也在我面前說多比雅的好話，又把我的話傳給他。多比雅常寄信來，要叫我懼怕。","notes":[]}]},"7":{"heading":"被擄歸回者的名單","verses":[{"n":1,"t":"城牆修完，我安了門扇，門口的守衛、歌唱的和利未人都已派定。","notes":[]},{"n":2,"t":"我吩咐我的兄弟哈拿尼和城堡的官長哈拿尼雅管理耶路撒冷，因為哈拿尼雅是一個忠信的人，敬畏神過於眾人。","notes":[]},{"n":3,"t":"我對他們說：「等到太陽熱的時候才可開耶路撒冷的城門；要派耶路撒冷的居民，各按班次在自己房屋的前面站崗。他們還在站崗的時候，就要關門上閂。」","notes":[]},{"n":4,"t":"城又寬又大，城中的百姓卻稀少，房屋也還沒有建造。","notes":[]},{"n":5,"t":"我的神感動我的心，我就召集貴族、官長和百姓，要登記家譜。我找到第一次上來之人的家譜，發現上面寫著：","notes":[]},{"n":6,"t":"這些是從被擄之地上來的省民，巴比倫王尼布甲尼撒把他們擄去，他們重返耶路撒冷和猶大，各歸本城。","notes":[]},{"n":7,"t":"他們是同所羅巴伯、耶書亞、尼希米、亞撒利雅、拉米、拿哈瑪尼、末底改、必珊、米斯毗列、比革瓦伊、尼宏、巴拿一起回來的。以色列百姓的人數如下：","notes":[]},{"n":8,"t":"巴錄的子孫二千一百七十二名；","notes":[]},{"n":9,"t":"示法提雅的子孫三百七十二名；","notes":[]},{"n":10,"t":"亞拉的子孫六百五十二名；","notes":[]},{"n":11,"t":"巴哈‧摩押的後裔，就是耶書亞和約押的子孫二千八百一十八名；","notes":[]},{"n":12,"t":"以攔的子孫一千二百五十四名；","notes":[]},{"n":13,"t":"薩土的子孫八百四十五名；","notes":[]},{"n":14,"t":"薩改的子孫七百六十名；","notes":[]},{"n":15,"t":"賓內的子孫六百四十八名；","notes":[]},{"n":16,"t":"比拜的子孫六百二十八名；","notes":[]},{"n":17,"t":"押甲的子孫二千三百二十二名；","notes":[]},{"n":18,"t":"亞多尼干的子孫六百六十七名；","notes":[]},{"n":19,"t":"比革瓦伊的子孫二千零六十七名；","notes":[]},{"n":20,"t":"亞丁的子孫六百五十五名；","notes":[]},{"n":21,"t":"亞特的後裔，就是希西家的子孫九十八名；","notes":[]},{"n":22,"t":"哈順的子孫三百二十八名；","notes":[]},{"n":23,"t":"比賽的子孫三百二十四名；","notes":[]},{"n":24,"t":"哈拉的子孫一百一十二名；","notes":[]},{"n":25,"t":"基遍人九十五名；","notes":[]},{"n":26,"t":"伯利恆人和尼陀法人共一百八十八名；","notes":[]},{"n":27,"t":"亞拿突人一百二十八名；","notes":[]},{"n":28,"t":"伯‧亞斯瑪弗人四十二名；","notes":[]},{"n":29,"t":"基列‧耶琳人、基非拉人、比錄人共七百四十三名；","notes":[]},{"n":30,"t":"拉瑪人和迦巴人共六百二十一名；","notes":[]},{"n":31,"t":"默瑪人一百二十二名；","notes":[]},{"n":32,"t":"伯特利人和艾人共一百二十三名；","notes":[]},{"n":33,"t":"別的尼波人五十二名；","notes":[]},{"n":34,"t":"另一個以攔子孫一千二百五十四名；","notes":[]},{"n":35,"t":"哈琳的子孫三百二十名；","notes":[]},{"n":36,"t":"耶利哥人三百四十五名；","notes":[]},{"n":37,"t":"羅德人、哈第人、阿挪人共七百二十一名；","notes":[]},{"n":38,"t":"西拿人三千九百三十名。","notes":[]},{"n":39,"t":"祭司：耶書亞家，耶大雅的子孫九百七十三名；","notes":[]},{"n":40,"t":"音麥的子孫一千零五十二名；","notes":[]},{"n":41,"t":"巴施戶珥的子孫一千二百四十七名；","notes":[]},{"n":42,"t":"哈琳的子孫一千零一十七名。","notes":[]},{"n":43,"t":"利未人：何達威的後裔，就是耶書亞和甲篾的子孫七十四名。","notes":[]},{"n":44,"t":"歌唱的：亞薩的子孫一百四十八名。","notes":[]},{"n":45,"t":"門口的守衛：沙龍的子孫、亞特的子孫、達們的子孫、亞谷的子孫、哈底大的子孫、朔拜的子孫，共一百三十八名。","notes":[]},{"n":46,"t":"殿役：西哈的子孫、哈蘇巴的子孫、答巴俄的子孫、","notes":[]},{"n":47,"t":"基綠的子孫、西亞的子孫、巴頓的子孫、","notes":[]},{"n":48,"t":"利巴拿的子孫、哈迦巴的子孫、薩買的子孫、","notes":[]},{"n":49,"t":"哈難的子孫、吉德的子孫、迦哈的子孫、","notes":[]},{"n":50,"t":"利亞雅的子孫、利汛的子孫、尼哥大的子孫、","notes":[]},{"n":51,"t":"迦散的子孫、烏撒的子孫、巴西亞的子孫、","notes":[]},{"n":52,"t":"比賽的子孫、米烏寧的子孫、尼普心的子孫、","notes":[]},{"n":53,"t":"巴卜的子孫、哈古巴的子孫、哈忽的子孫、","notes":[]},{"n":54,"t":"巴洗律的子孫、米希大的子孫、哈沙的子孫、","notes":[]},{"n":55,"t":"巴柯的子孫、西西拉的子孫、答瑪的子孫、","notes":[]},{"n":56,"t":"尼細亞的子孫、哈提法的子孫。","notes":[]},{"n":57,"t":"所羅門僕人的後裔：瑣太的子孫、瑣斐列的子孫、比路大的子孫、","notes":[]},{"n":58,"t":"雅拉的子孫、達昆的子孫、吉德的子孫、","notes":[]},{"n":59,"t":"示法提雅的子孫、哈替的子孫、玻黑列‧哈斯巴音的子孫、亞們的子孫。","notes":[]},{"n":60,"t":"殿役和所羅門僕人的後裔共三百九十二名。","notes":[]},{"n":61,"t":"從特‧米拉、特‧哈薩、基綠、亞頓、音麥上來，不能證明他們的父系家族和後裔是否屬以色列的如下：","notes":[]},{"n":62,"t":"第萊雅的子孫、多比雅的子孫、尼哥大的子孫，共六百四十二名。","notes":[]},{"n":63,"t":"祭司中，哈巴雅的子孫、哈哥斯的子孫、巴西萊的子孫，巴西萊因為娶了基列人巴西萊的女兒為妻，所以就以此為名。","notes":[]},{"n":64,"t":"這些人在族譜之中尋查自己的譜系，卻尋不著，因此算為不潔，不得作祭司。","notes":[]},{"n":65,"t":"省長對他們說，不可吃至聖的物，直到有會用烏陵和土明的祭司興起來。","notes":[]},{"n":66,"t":"全會眾共有四萬二千三百六十名。","notes":[]},{"n":67,"t":"此外，還有他們的僕婢七千三百三十七名，又有歌唱的男女二百四十五名。","notes":[]},{"n":68,"t":"他們有七百三十六匹馬，二百四十五匹騾子，","notes":[]},{"n":69,"t":"四百三十五匹駱駝，六千七百二十匹驢。","notes":[]},{"n":70,"t":"有些族長為工程捐助。省長捐入庫房中的有一千達利克金子，五十個碗，五百三十件祭司的禮服。","notes":["「達利克」：古波斯金幣，參「度量衡表」；下節同。"]},{"n":71,"t":"有些族長捐入工程的庫房，有二萬達利克金子，二千二百彌那銀子。","notes":[]},{"n":72,"t":"其餘百姓所捐的有二萬達利克金子，二千彌那銀子，六十七件祭司的禮服。","notes":[]},{"n":73,"t":"於是祭司、利未人、門口的守衛、歌唱的、百姓中的一些人、殿役，並以色列眾人，都住在自己的城裏。到了七月，以色列人住在自己的城裏。","notes":[]}]},"8":{"heading":"住棚節","verses":[{"n":1,"t":"那時，眾百姓如同一人聚集在水門前的廣場，請以斯拉文士將耶和華吩咐以色列的摩西的律法書帶來。","notes":[]},{"n":2,"t":"七月初一，以斯拉祭司將律法書帶到聽了能明白的男女會眾面前。","notes":[]},{"n":3,"t":"他在水門前的廣場，從清早到中午，在男女和能明白的人面前讀這律法書，眾百姓都側耳而聽。","notes":[]},{"n":4,"t":"以斯拉文士站在為這事特製的木臺上。站在他旁邊的有瑪他提雅、示瑪、亞奈雅、烏利亞和希勒家；站在他右邊的有瑪西雅；站在他左邊的有毗大雅、米沙利、瑪基雅、哈順、哈拔大拿、撒迦利亞和米書蘭。","notes":[]},{"n":5,"t":"以斯拉站在上面，在眾百姓眼前展開這書。他一展開，眾百姓都站起來。","notes":[]},{"n":6,"t":"以斯拉稱頌耶和華至大的神，眾百姓都舉手應聲說：「阿們！阿們！」他們低頭，俯伏在地，敬拜耶和華。","notes":[]},{"n":7,"t":"耶書亞、巴尼、示利比、雅憫、亞谷、沙比太、荷第雅、瑪西雅、基利他、亞撒利雅、約撒拔、哈難、毗萊雅和利未人使百姓明白律法；百姓都站在自己的地方。","notes":[]},{"n":8,"t":"他們清清楚楚地念神的律法書，講明意思，使百姓明白所念的。","notes":[]},{"n":9,"t":"尼希米省長、以斯拉祭司文士，和教導百姓的利未人對眾百姓說：「今日是耶和華－你們神的聖日，不要悲哀，也不要哭泣。」這是因為眾百姓聽見律法書上的話都哭了。","notes":[]},{"n":10,"t":"尼希米對他們說：「你們去吃肥美的，喝甘甜的，有不能預備的就分給他，因為今日是我們主的聖日。你們不要憂愁，因靠耶和華而得的喜樂是你們的力量。」","notes":[]},{"n":11,"t":"於是利未人叫眾百姓安靜，說：「安靜，因今日是聖日，不要憂愁。」","notes":[]},{"n":12,"t":"眾百姓去吃喝，也分給別人，都大大喜樂，因為他們明白所教導他們的話。","notes":[]},{"n":13,"t":"次日，眾百姓的族長、祭司和利未人都聚集到以斯拉文士那裏，要明白律法書上的話。","notes":[]},{"n":14,"t":"他們發現律法書上寫著，耶和華藉摩西吩咐以色列人要在七月的節期中住在棚裏，","notes":[]},{"n":15,"t":"並要在各城和耶路撒冷傳揚宣告說：「你們當出去，上山，把橄欖樹、野橄欖樹、番石榴樹、棕樹和各樣茂密樹的枝子取來，照著所寫的搭棚。」","notes":[]},{"n":16,"t":"於是百姓出去，取了樹枝來，各人在自己的房頂上、院子裏、神殿的院內、水門的廣場和以法蓮門的廣場搭棚。","notes":[]},{"n":17,"t":"從被擄之地歸回的全會眾就搭棚，住在棚裏。從嫩的兒子約書亞的時候直到這日，以色列人沒有這樣行。他們都大大喜樂。","notes":[]},{"n":18,"t":"從第一天直到末一天，以斯拉天天朗讀神的律法書。他們守節七日，第八日照例有嚴肅會。","notes":[]}]},"9":{"heading":"以色列人的認罪","verses":[{"n":1,"t":"這月二十四日，以色列人聚集禁食，他們披麻蒙灰。","notes":[]},{"n":2,"t":"以色列的後裔與所有的外邦人分別出來，站著承認自己的罪和祖先的罪孽。","notes":[]},{"n":3,"t":"那日的四分之一，他們站在自己的地方念耶和華－他們神的律法書，又在那日的四分之一認罪，敬拜耶和華－他們的神。","notes":[]},{"n":4,"t":"耶書亞、巴尼、甲篾、示巴尼、布尼、示利比、巴尼、基拿尼站在利未人的臺階上，大聲哀求耶和華－他們的神。","notes":[]},{"n":5,"t":"利未人耶書亞、甲篾、巴尼、哈沙尼、示利比、荷第雅、示巴尼、毗他希雅說：「起來，稱頌耶和華－你們的神，永世無盡：『你榮耀之名是應當稱頌的，超乎一切稱頌和讚美。","notes":[]},{"n":6,"t":"「『你，惟獨你是耶和華！你造了天和天上的天，以及天上的萬象，地和地上的萬物，海和海中所有的；一切的生命全都是你賞賜的。天軍都敬拜你。","notes":[]},{"n":7,"t":"你是耶和華神，曾揀選亞伯蘭，領他出迦勒底的吾珥，給他改名叫亞伯拉罕。","notes":[]},{"n":8,"t":"你發現他在你面前心裏忠誠，就與他立約，要把迦南人、赫人、亞摩利人、比利洗人、耶布斯人、革迦撒人之地賜給他的後裔，並且你也實現了你的話，因為你是公義的。","notes":[]},{"n":9,"t":"「『你曾看見我們祖先在埃及所受的困苦，垂聽他們在紅海邊的哀求，","notes":["「紅海」是根據七十士譯本；原文是「蘆葦海」。"]},{"n":10,"t":"施行神蹟奇事在法老和他所有臣僕，以及他國中眾百姓身上，因為你知道他們向我們祖先行事狂傲。你也得了名聲，正如今日一樣。","notes":[]},{"n":11,"t":"你在我們祖先面前把海分開，使他們走過海中乾地，將追趕他們的人拋在深海，如石頭拋在大水中。","notes":[]},{"n":12,"t":"白晝你用雲柱引導他們，黑夜你用火柱照亮他們當行的路。","notes":[]},{"n":13,"t":"你降臨在西奈山，從天上與他們說話，賜給他們正直的典章、真實的律法、美好的律例與誡命，","notes":[]},{"n":14,"t":"又使他們知道你的聖安息日，並藉你僕人摩西傳給他們誡命、律例、律法。","notes":[]},{"n":15,"t":"你從天上賜下糧食給他們充飢，使水從磐石流出給他們解渴。你吩咐他們進去，得你起誓應許要賜給他們的地。","notes":[]},{"n":16,"t":"「『但我們的祖先行事狂傲，硬著頸項不聽從你的誡命。","notes":[]},{"n":17,"t":"他們不肯順從，也不記念你在他們中間所行的奇事，竟硬著頸項，居心悖逆，自立領袖，要回埃及他們為奴之地。但你是樂意饒恕人，有恩惠，有憐憫，不輕易發怒，有豐盛慈愛的神，並沒有丟棄他們。","notes":["「要回埃及他們為奴之地」是根據一些古卷和七十士譯本；原文是「要在背叛中回他們為奴之地」。"]},{"n":18,"t":"他們雖然為自己鑄了一頭牛犢，說，這就是領你出埃及的神明，因而犯了褻瀆的大罪，","notes":[]},{"n":19,"t":"你還是有豐富的憐憫，不把他們丟棄在曠野。白晝，雲柱不離開他們，仍引導他們行路；黑夜，火柱仍照亮他們當行的路。","notes":[]},{"n":20,"t":"你賜下你良善的靈教導他們，沒有收回嗎哪不給他們吃，仍賜水給他們解渴。","notes":[]},{"n":21,"t":"在曠野四十年，你養育他們，他們一無所缺，衣服沒有穿破，腳也沒有腫。","notes":[]},{"n":22,"t":"你將列國和諸民族交給他們，把那些角落分給他們，他們就得了西宏之地，就是希實本王之地，和巴珊王噩之地。","notes":[]},{"n":23,"t":"你使他們的子孫多如天上的星，帶他們到你對他們祖先說要進去得為業之地。","notes":[]},{"n":24,"t":"這樣，這些子孫進去得了那地。你在他們面前制伏那地的居民迦南人，把迦南人和他們的君王，以及那地的民族，都交在他們手裏，讓他們任意處置。","notes":[]},{"n":25,"t":"他們得了堅固的城鎮、肥沃的土地，取了裝滿各樣美物的房屋、挖成的水井、葡萄園、橄欖園，以及許多果樹。他們就吃了，而且飽足，身體肥胖，因你的大恩活得快樂。","notes":[]},{"n":26,"t":"「『然而，他們不順從，竟背叛你，將你的律法丟在背後，又殺害那些勸他們回轉歸向你的眾先知，犯了褻瀆的大罪。","notes":[]},{"n":27,"t":"所以你將他們交在敵人的手中，敵人就折磨他們。他們遭難的時候哀求你，你就從天上垂聽，照你豐富的憐憫賜給他們拯救者，救他們脫離敵人的手。","notes":[]},{"n":28,"t":"但他們得享太平之後，又在你面前行惡，所以你丟棄他們，交在仇敵的手中，仇敵就轄制他們；然而他們轉回哀求你，你就從天上垂聽，屢次照你的憐憫拯救他們，","notes":[]},{"n":29,"t":"你警戒他們，要使他們歸順你的律法。他們卻行事狂傲，不聽從你的誡命，干犯你的典章，人若遵行就必因此存活。他們頑梗地扭轉肩頭，硬著頸項，不肯聽從。","notes":[]},{"n":30,"t":"但你多年寬容他們，又以你的靈藉眾先知勸戒他們，他們仍不側耳而聽，所以你將他們交在列邦民族的手中。","notes":[]},{"n":31,"t":"然而因你豐富的憐憫，你不全然滅絕他們，也不丟棄他們，因為你是有恩惠、有憐憫的神。","notes":[]},{"n":32,"t":"「『現在，我們的神啊，你是至大、至能、至可畏、守約施慈愛的神；我們的君王、官長、祭司、先知、祖先和你的眾百姓，從亞述諸王的時候直到今日所遭遇的一切苦難，求你不要看為小事。","notes":[]},{"n":33,"t":"在一切臨到我們的事上，你是公義的，因為你所行的是信實，我們所做的是邪惡。","notes":[]},{"n":34,"t":"我們的君王、官長、祭司、祖先都不遵守你的律法，不聽從你的誡命和你警戒他們的話。","notes":[]},{"n":35,"t":"他們在本國領受你大恩的時候，在你所賜給他們這廣大肥沃之地不事奉你，也不轉離他們的惡行。","notes":[]},{"n":36,"t":"看哪，我們今日成了奴僕！你賜給我們祖先享受土產和美物的地，看哪，我們在這地上竟作了奴僕！","notes":[]},{"n":37,"t":"這地許多的出產都歸了諸王，就是你因我們的罪派來轄制我們的。他們任意轄制我們的身體和牲畜，我們遭了大難。』」","notes":[]},{"n":38,"t":"因這一切，我們立確實的約，寫在冊上。我們的領袖、利未人和祭司都用了印。","notes":[]}]},"10":{"heading":"在公約上簽名的人","verses":[{"n":1,"t":"用印的是哈迦利亞的兒子尼希米省長、西底家；","notes":[]},{"n":2,"t":"還有西萊雅、亞撒利雅、耶利米、","notes":[]},{"n":3,"t":"巴施戶珥、亞瑪利雅、瑪基雅、","notes":[]},{"n":4,"t":"哈突、示巴尼、瑪鹿、","notes":[]},{"n":5,"t":"哈琳、米利末、俄巴底亞、","notes":[]},{"n":6,"t":"但以理、近頓、巴錄、","notes":[]},{"n":7,"t":"米書蘭、亞比雅、米雅民、","notes":[]},{"n":8,"t":"瑪西亞、璧該、示瑪雅等祭司；","notes":[]},{"n":9,"t":"又有利未人亞散尼的兒子耶書亞、希拿達的子孫賓內、甲篾，","notes":[]},{"n":10,"t":"他們的弟兄示巴尼、荷第雅、基利他、毗萊雅、哈難、","notes":[]},{"n":11,"t":"米迦、利合、哈沙比雅、","notes":[]},{"n":12,"t":"撒刻、示利比、示巴尼、","notes":[]},{"n":13,"t":"荷第雅、巴尼、比尼努；","notes":[]},{"n":14,"t":"還有百姓中的領袖巴錄、巴哈‧摩押、以攔、薩土、巴尼、","notes":[]},{"n":15,"t":"布尼、押甲、比拜、","notes":[]},{"n":16,"t":"亞多尼雅、比革瓦伊、亞丁、","notes":[]},{"n":17,"t":"亞特、希西家、押朔、","notes":[]},{"n":18,"t":"荷第雅、哈順、比賽、","notes":[]},{"n":19,"t":"哈拉、亞拿突、尼拜、","notes":[]},{"n":20,"t":"抹比押、米書蘭、希悉、","notes":[]},{"n":21,"t":"米示薩別、撒督、押杜亞、","notes":[]},{"n":22,"t":"毗拉提、哈難、亞奈雅、","notes":[]},{"n":23,"t":"何細亞、哈拿尼雅、哈述、","notes":[]},{"n":24,"t":"哈羅黑、毗利哈、朔百、","notes":[]},{"n":25,"t":"利宏、哈沙拿、瑪西雅、","notes":[]},{"n":26,"t":"亞希雅、哈難、亞難、","notes":[]},{"n":27,"t":"瑪鹿、哈琳、巴拿。","notes":[]},{"n":28,"t":"其餘的百姓、祭司、利未人、門口的守衛、歌唱的、殿役，所有與鄰邦民族分別出來、歸服神律法的，以及他們的妻子、兒女，凡有知識、能明白的，","notes":[],"heads":["公約的內容"]},{"n":29,"t":"都隨從他們貴族的弟兄發咒起誓，要遵行神藉他僕人摩西所賜的律法，謹守遵行耶和華－我們主的一切誡命、典章、律例。","notes":[]},{"n":30,"t":"我們不把我們的女兒嫁給這地的居民，也不為我們的兒子娶他們的女兒。","notes":[]},{"n":31,"t":"這地的民族若在安息日，或甚麼聖日，帶了貨物或糧食來賣，我們必不買。每逢第七年必不耕種，凡欠我們債的必不追討。","notes":[]},{"n":32,"t":"我們又為自己定例，每年各人捐獻三分之一舍客勒，作為我們神殿之用：","notes":[]},{"n":33,"t":"為供餅、常獻的素祭和燔祭，安息日、初一、節期所獻的祭和聖物，以色列的贖罪祭，以及我們神殿裏一切工作之用。","notes":[]},{"n":34,"t":"我們的祭司、利未人和百姓都抽籤，每年按父家定期將奉獻的木柴帶到我們神的殿裏，照著律法上所寫的，燒在耶和華－我們神的壇上。","notes":[]},{"n":35,"t":"每年我們又將地上初熟的土產和各樣樹上初熟的果子，都奉到耶和華的殿裏。","notes":[]},{"n":36,"t":"我們又照律法上所寫的，將我們頭胎的兒子和首生的牛羊都奉到我們神的殿，交給在神殿裏供職的祭司；","notes":[]},{"n":37,"t":"並將初熟麥子所磨的麵和舉祭、各樣樹上的果子、新酒與新油奉給祭司，收在我們神殿的庫房裏，又把我們土地所產的十分之一奉給利未人，因利未人在我們一切城鎮的土產中當取十分之一。","notes":[]},{"n":38,"t":"利未人取十分之一的時候，亞倫的子孫中當有一個祭司與利未人同在。利未人也當從十分之一中取十分之一，奉到我們神的殿，收在庫房的倉裏。","notes":[]},{"n":39,"t":"因以色列人和利未人要把禮物，就是五穀、新酒和新油，帶到收存聖所器皿的倉裏，供職的祭司、門口的守衛、歌唱的都在那裏。我們絕不會不顧我們神的殿。","notes":[]}]},"11":{"heading":"住在耶路撒冷的人","verses":[{"n":1,"t":"百姓的領袖住在耶路撒冷。其餘的百姓抽籤，每十人中選一人來住在聖城耶路撒冷，另外九人住在別的城鎮。","notes":[]},{"n":2,"t":"凡甘心樂意住在耶路撒冷的，百姓都為他們祝福。","notes":[]},{"n":3,"t":"以色列人、祭司、利未人、殿役和所羅門僕人的後裔都住在猶大的城鎮，各在自己城內的地業中。本省的領袖住在耶路撒冷的如下：","notes":[]},{"n":4,"t":"住在耶路撒冷的有一些猶大人和便雅憫人。猶大人中有法勒斯的子孫亞他雅；亞他雅是烏西雅的兒子，烏西雅是撒迦利雅的兒子，撒迦利雅是亞瑪利雅的兒子，亞瑪利雅是示法提雅的兒子，示法提雅是瑪勒列的兒子；","notes":[]},{"n":5,"t":"又有瑪西雅；瑪西雅是巴錄的兒子，巴錄是谷‧何西的兒子，谷‧何西是哈賽雅的兒子，哈賽雅是亞大雅的兒子，亞大雅是約雅立的兒子，約雅立是撒迦利雅的兒子，撒迦利雅是示羅尼的兒子；","notes":[]},{"n":6,"t":"住在耶路撒冷所有法勒斯的子孫共四百六十八名，都是勇士。","notes":[]},{"n":7,"t":"便雅憫人中有撒路；撒路是米書蘭的兒子，米書蘭是約葉的兒子，約葉是毗大雅的兒子，毗大雅是哥賴雅的兒子，哥賴雅是瑪西雅的兒子，瑪西雅是以鐵的兒子，以鐵是耶篩亞的兒子；","notes":[]},{"n":8,"t":"其次有迦拜、撒來，共九百二十八名。","notes":[]},{"n":9,"t":"細基利的兒子約珥是他們的長官；哈西努亞的兒子猶大是耶路撒冷的副長官。","notes":[]},{"n":10,"t":"祭司中有約雅立的兒子耶大雅，又有雅斤，","notes":[]},{"n":11,"t":"還有管理神殿的西萊雅；西萊雅是希勒家的兒子，希勒家是米書蘭的兒子，米書蘭是撒督的兒子，撒督是米拉約的兒子，米拉約是亞希突的兒子；","notes":[]},{"n":12,"t":"還有他們的弟兄在殿裏供職的，共八百二十二名；又有亞大雅；亞大雅是耶羅罕的兒子，耶羅罕是毗拉利的兒子，毗拉利是暗洗的兒子，暗洗是撒迦利亞的兒子，撒迦利亞是巴施戶珥的兒子，巴施戶珥是瑪基雅的兒子；","notes":[]},{"n":13,"t":"還有他的弟兄作族長的，共二百四十二名；又有亞瑪帥；亞瑪帥是亞薩列的兒子，亞薩列是亞哈賽的兒子，亞哈賽是米實利末的兒子，米實利末是音麥的兒子；","notes":[]},{"n":14,"t":"還有他們的弟兄，大能的勇士共一百二十八名；哈基多琳的兒子撒巴第業是他們的長官。","notes":[]},{"n":15,"t":"利未人中有示瑪雅；示瑪雅是哈述的兒子，哈述是押利甘的兒子，押利甘是哈沙比雅的兒子，哈沙比雅是布尼的兒子；","notes":[]},{"n":16,"t":"又有利未人的族長沙比太和約撒拔管理神殿外面的事務；","notes":[]},{"n":17,"t":"祈禱的時候，瑪他尼是主禮，開始稱謝；瑪他尼是米迦的兒子，米迦是撒底的兒子，撒底是亞薩的兒子；又有瑪他尼弟兄中的八布迦為副；還有押大；押大是沙母亞的兒子，沙母亞是加拉的兒子，加拉是耶杜頓的兒子；","notes":[]},{"n":18,"t":"在聖城所有的利未人共二百八十四名。","notes":[]},{"n":19,"t":"門口的守衛是亞谷和達們，以及他們的弟兄，看守各門，共一百七十二名。","notes":[]},{"n":20,"t":"其餘的以色列人、祭司、利未人都住在猶大一切的城鎮，各在自己的地業中。","notes":[]},{"n":21,"t":"殿役卻住在俄斐勒；西哈和基斯帕管理他們。","notes":[]},{"n":22,"t":"在耶路撒冷，利未人的長官，管理神殿事務的是歌唱者亞薩的子孫烏西；烏西是巴尼的兒子，巴尼是哈沙比雅的兒子，哈沙比雅是瑪他尼的兒子，瑪他尼是米迦的兒子。","notes":[]},{"n":23,"t":"王為歌唱者下命令，確定他們每日當辦的事。","notes":["「確定他們每日當辦的事」或譯「每日供給他們固定的口糧」。"]},{"n":24,"t":"猶大的兒子謝拉的子孫，米示薩別的兒子毗他希雅輔助王辦理百姓一切的事。","notes":[]},{"n":25,"t":"至於村莊和所屬的田地，有猶大人住在基列‧亞巴和所屬的鄉鎮、底本和所屬的鄉鎮、葉甲薛和所屬的村莊、","notes":["「鄉鎮」：原文直譯「女子們」；下同。"],"heads":["住在其他城鎮的人"]},{"n":26,"t":"耶書亞、摩拉大、伯‧帕列、","notes":[]},{"n":27,"t":"哈薩‧書亞、別是巴和所屬的鄉鎮、","notes":[]},{"n":28,"t":"洗革拉、米哥拿和所屬的鄉鎮、","notes":[]},{"n":29,"t":"隱‧臨門、瑣拉、耶末、","notes":[]},{"n":30,"t":"撒挪亞、亞杜蘭和屬它們的村莊、拉吉和所屬的田地、亞西加和所屬的鄉鎮；他們所住的地方是從別是巴直到欣嫩谷。","notes":[]},{"n":31,"t":"便雅憫人從迦巴起，住在密抹、亞雅、伯特利和所屬的鄉鎮、","notes":[]},{"n":32,"t":"亞拿突、挪伯、亞難雅、","notes":[]},{"n":33,"t":"夏瑣、拉瑪、基他音、","notes":[]},{"n":34,"t":"哈第、洗編、尼八拉、","notes":[]},{"n":35,"t":"羅德、阿挪、革‧夏納欣。","notes":[]},{"n":36,"t":"在猶大地區的利未人中，有些已歸屬便雅憫。","notes":[]}]},"12":{"heading":"祭司和利未人的名單","verses":[{"n":1,"t":"這些是同撒拉鐵的兒子所羅巴伯以及耶書亞一起上來的祭司和利未人：西萊雅、耶利米、以斯拉、","notes":[]},{"n":2,"t":"亞瑪利雅、瑪鹿、哈突、","notes":[]},{"n":3,"t":"示迦尼、利宏、米利末、","notes":[]},{"n":4,"t":"易多、近頓、亞比雅、","notes":[]},{"n":5,"t":"米雅民、瑪底雅、璧迦、","notes":[]},{"n":6,"t":"示瑪雅、約雅立、耶大雅、","notes":[]},{"n":7,"t":"撒路、亞木、希勒家、耶大雅；這些人在耶書亞的時代作祭司和他們弟兄的領袖。","notes":[]},{"n":8,"t":"利未人有耶書亞、賓內、甲篾、示利比、猶大、瑪他尼；瑪他尼和他的弟兄負責讚美詩歌。","notes":[]},{"n":9,"t":"他們的弟兄八布迦和烏尼按照班次站在他們的對面。","notes":[]},{"n":10,"t":"耶書亞生約雅金，約雅金生以利亞實，以利亞實生耶何耶大，","notes":[],"heads":["耶書亞大祭司的後代"]},{"n":11,"t":"耶何耶大生約拿單，約拿單生押杜亞。","notes":[]},{"n":12,"t":"在約雅金的時代，祭司作族長的，西萊雅族有米拉雅，耶利米族有哈拿尼雅，","notes":[],"heads":["作族長的祭司"]},{"n":13,"t":"以斯拉族有米書蘭，亞瑪利雅族有約哈難，","notes":[]},{"n":14,"t":"米利古族有約拿單，示巴尼族有約瑟，","notes":[]},{"n":15,"t":"哈琳族有押拿，米拉約族有希勒愷，","notes":[]},{"n":16,"t":"易多族有撒迦利亞，近頓族有米書蘭，","notes":[]},{"n":17,"t":"亞比雅族有細基利，米拿民族，摩亞底族有毗勒太，","notes":[]},{"n":18,"t":"璧迦族有沙母亞，示瑪雅族有約拿單，","notes":[]},{"n":19,"t":"約雅立族有瑪特乃，耶大雅族有烏西，","notes":[]},{"n":20,"t":"撒來族有加萊，亞木族有希伯，","notes":[]},{"n":21,"t":"希勒家族有哈沙比雅，耶大雅族有拿坦業。","notes":[]},{"n":22,"t":"在以利亞實、耶何耶大、約哈難、押杜亞的時代，利未人的族長都記在冊上，祭司也一樣，直到波斯王大流士在位的時候。","notes":[]},{"n":23,"t":"利未人作族長的記在史籍上，一直記到以利亞實的兒子約哈難的時代。","notes":[]},{"n":24,"t":"利未人的族長是哈沙比雅、示利比、甲篾的兒子耶書亞，他們的弟兄站在他們的對面，照神人大衛的命令按著班次讚美稱謝。","notes":["「甲篾的兒子耶書亞」：原文另譯「賓內、甲篾、耶書亞」；參尼10．9，12．8。"]},{"n":25,"t":"瑪他尼、八布迦、俄巴底亞、米書蘭、達們、亞谷是門口的守衛，在庫房的門口站崗。","notes":[]},{"n":26,"t":"這些人都在約撒達的孫子，耶書亞的兒子約雅金和尼希米省長，以及以斯拉祭司文士的時代供職。","notes":[]},{"n":27,"t":"為耶路撒冷城牆行奉獻禮的時候，眾人把各處的利未人召到耶路撒冷，要以稱謝、歌唱、敲鈸、鼓瑟、彈琴，喜樂地行奉獻禮。","notes":[],"heads":["城牆奉獻禮"]},{"n":28,"t":"歌唱的人從耶路撒冷的周圍聚集，從尼陀法人的村莊、","notes":[]},{"n":29,"t":"伯‧吉甲，以及迦巴和亞斯瑪弗的田地而來；因為歌唱的人在耶路撒冷四圍為自己建立了村莊。","notes":[]},{"n":30,"t":"祭司和利未人就潔淨自己，也潔淨百姓，以及城門和城牆。","notes":[]},{"n":31,"t":"我帶猶大的領袖上城牆，把稱謝的人分為兩大隊，在城牆上往右邊的糞廠門行進，","notes":[]},{"n":32,"t":"在他們後面行進的有何沙雅與猶大一半的領袖，","notes":[]},{"n":33,"t":"又有亞撒利雅、以斯拉、米書蘭、","notes":[]},{"n":34,"t":"猶大、便雅憫、示瑪雅、耶利米。","notes":[]},{"n":35,"t":"還有祭司的子孫，吹號的有撒迦利亞；撒迦利亞是約拿單的兒子，約拿單是示瑪雅的兒子，示瑪雅是瑪他尼的兒子，瑪他尼是米該亞的兒子，米該亞是撒刻的兒子，撒刻是亞薩的兒子；","notes":[]},{"n":36,"t":"又有撒迦利亞的弟兄示瑪雅、亞撒利、米拉萊、基拉萊、瑪艾、拿坦業、猶大、哈拿尼，各拿著神人大衛的樂器，由以斯拉文士在前面引領。","notes":[]},{"n":37,"t":"他們經過泉門往前，登大衛城的臺階，上城牆的斜坡，從大衛宮殿之上，直到朝東的水門。","notes":[]},{"n":38,"t":"第二隊稱謝的人要往反方向而行。我和一半的百姓在城牆上跟隨他們，從爐樓之上，直到寬牆；","notes":[]},{"n":39,"t":"又過了以法蓮門、古門、魚門、哈楠業樓、哈米亞樓，直到羊門，就在護衛門站住。","notes":[]},{"n":40,"t":"於是，這兩隊稱謝的人連同我和一半跟隨我的官長，站在神的殿裏。","notes":[]},{"n":41,"t":"還有以利亞金、瑪西雅、米拿民、米該亞、以利約乃、撒迦利亞、哈楠尼亞等吹號的祭司；","notes":[]},{"n":42,"t":"又有瑪西雅、示瑪雅、以利亞撒、烏西、約哈難、瑪基雅、以攔和以謝。歌唱的大聲唱歌，有伊斯拉希雅作指揮。","notes":[]},{"n":43,"t":"那日，眾人獻上豐盛的祭物，並且歡樂，因為神使他們大大歡樂，連婦女帶孩童也都歡樂，甚至從遠處都可聽到耶路撒冷的歡聲。","notes":[]},{"n":44,"t":"當日，有些人受派管理庫房，把舉祭、初熟之物，和所取的十一奉獻，按各城的田地，照律法所定，歸給祭司和利未人的份，都收在庫房裏。猶大人因祭司和利未人供職就歡樂。","notes":[],"heads":["聖殿的各種職責"]},{"n":45,"t":"祭司和利未人遵守神所吩咐的，守潔淨禮。歌唱的和門口的守衛照著大衛和他兒子所羅門的命令也如此行。","notes":[]},{"n":46,"t":"古時，在大衛和亞薩的日子，有歌唱者的指揮，也有讚美稱謝神的詩歌。","notes":[]},{"n":47,"t":"在所羅巴伯和尼希米的時代，以色列眾人把歌唱者和門口的守衛每日當得的份供給他們，又把給利未人的分別出來；利未人又把給亞倫子孫的分別出來。","notes":[]}]},"13":{"heading":"與外邦人隔離","verses":[{"n":1,"t":"在那日，百姓聽到人朗讀摩西的律法書，發現書上寫著，亞捫人和摩押人永不可入神的會；","notes":[]},{"n":2,"t":"因為他們沒有拿食物和水來迎接以色列人，卻雇了巴蘭詛咒他們，但我們的神使那詛咒變為祝福。","notes":[]},{"n":3,"t":"以色列人聽見這律法，就與所有不同族群的人分別出來。","notes":[]},{"n":4,"t":"在這之前，與多比雅結親的以利亞實祭司，受派管理我們神殿中的庫房，","notes":[],"heads":["尼希米的改革"]},{"n":5,"t":"為多比雅預備了一間大屋子，就是從前收存素祭、乳香、器皿，和照例供給利未人、歌唱者、門口守衛的五穀、新酒和新油的十分之一，以及歸祭司之舉祭的屋子。","notes":[]},{"n":6,"t":"當這一切事發生的時候，我不在耶路撒冷，因為巴比倫王亞達薛西三十二年，我回到王那裏。過了多日，我又向王告假。","notes":[]},{"n":7,"t":"我來到耶路撒冷，才知道以利亞實為多比雅所做、在神殿的院內為他預備屋子的那件惡事。","notes":[]},{"n":8,"t":"我非常憤怒，就把多比雅的一切家具都從屋子裏拋出去。","notes":[]},{"n":9,"t":"我又吩咐人潔淨這屋子，然後將神殿的器皿、素祭和乳香搬回那裏。","notes":[]},{"n":10,"t":"我發現利未人當得的份無人供給他們，甚至供職的利未人與歌唱的都各奔回自己的田地去了。","notes":[]},{"n":11,"t":"我就斥責官長說：「你們為何不顧神的殿呢？」於是我召集利未人，使他們在自己的崗位上供職。","notes":[]},{"n":12,"t":"猶大眾人就把五穀、新酒和新油的十分之一送入庫房。","notes":[]},{"n":13,"t":"我派示利米雅祭司、撒督文士和利未人毗大雅作司庫管理庫房，副手是哈難；哈難是撒刻的兒子，撒刻是瑪他尼的兒子；這些人都是忠實的，他們的職務是分派他們弟兄所當得的份。","notes":[]},{"n":14,"t":"我的神啊，求你因這事記念我，不要塗去我為神的殿與其中的禮儀所獻的忠心。","notes":[]},{"n":15,"t":"那些日子，我在猶大見有人在安息日踹醡酒池，搬運禾捆馱在驢上，又把酒、葡萄、無花果和各樣的擔子在安息日扛入耶路撒冷，我就在他們賣食物的那日警戒他們。","notes":[]},{"n":16,"t":"有一些住在城裏的推羅人也把魚和各樣貨物運進來，甚至在耶路撒冷，在安息日賣給猶大人。","notes":[]},{"n":17,"t":"我就斥責猶大的貴族，對他們說：「你們怎麼會做這惡事干犯安息日呢！","notes":[]},{"n":18,"t":"你們祖先豈不是這樣做，以致我們的神使一切災禍臨到我們和這城嗎？你們竟干犯安息日，使憤怒越發臨到以色列！」","notes":[]},{"n":19,"t":"安息日前一日黃昏的時候，我吩咐人把耶路撒冷城門鎖上；我又吩咐，不過安息日不准開門。我也派幾個僕人在城門口站崗，免得有人在安息日挑擔子進城。","notes":[]},{"n":20,"t":"於是商人和販賣各樣貨物的人，有一兩次在耶路撒冷城外過夜。","notes":[]},{"n":21,"t":"我警告他們說：「你們為何在城牆前過夜呢？若再這樣，我必下手辦你們。」從此以後，他們在安息日就不再來了。","notes":[]},{"n":22,"t":"我吩咐利未人潔淨自己來守城門，使安息日分別為聖。我的神啊，求你因這事記念我，照你豐盛的慈愛憐憫我。","notes":[]},{"n":23,"t":"那些日子，我又看見猶太人娶了亞實突、亞捫和摩押的女子為妻。","notes":[]},{"n":24,"t":"他們的兒女，一半說亞實突話，或其他種族的方言，不會說猶大話。","notes":[]},{"n":25,"t":"我就斥責他們，詛咒他們，打了他們幾個人，拔下他們的鬍鬚，叫他們指著神起誓：「你們不可把自己的女兒嫁給外邦人的兒子，也不可為自己和兒子娶他們的女兒。","notes":[]},{"n":26,"t":"以色列王所羅門不也在這樣的事上犯罪嗎？在許多國家中並沒有一位王像他，蒙他神喜愛，神立他作王治理全以色列。然而，連他也被外邦女子引誘犯罪。","notes":[]},{"n":27,"t":"我們豈能聽憑你們行這一切大惡，娶外邦女子干犯我們的神呢？」","notes":[]},{"n":28,"t":"以利亞實大祭司的孫子，耶何耶大的一個兒子是和倫人參巴拉的女婿，我就把他從我這裏趕出去。","notes":[]},{"n":29,"t":"我的神啊，求你記得他們的罪，因為他們玷污了祭司的職分，違背祭司和利未人的約。","notes":[]},{"n":30,"t":"這樣，我潔淨他們，使他們脫離屬外邦人的一切；我又分派祭司和利未人的班次，使他們各盡其職，","notes":[]},{"n":31,"t":"按定期奉獻木柴和初熟的土產。我的神啊，求你記念我，施恩於我。","notes":[]}]}},"EST":{"1":{"heading":"亞哈隨魯王廢瓦實提王后","verses":[{"n":1,"t":"這事發生在亞哈隨魯的時代，亞哈隨魯從印度直到古實統治一百二十七個省，","notes":[]},{"n":2,"t":"就是亞哈隨魯王在書珊城堡中坐國度王位的那些日子。","notes":[]},{"n":3,"t":"他在位第三年，為所有官員和臣僕擺設宴席，有波斯和瑪代的權貴，各省的貴族與領袖在他面前。","notes":[]},{"n":4,"t":"他把他榮耀國度的豐富和他偉大威嚴的尊貴給他們看了許多日子，共一百八十天。","notes":[]},{"n":5,"t":"這些日子滿了，王又為所有住書珊城堡的百姓，無論大小，在御花園的院子裏擺設宴席七日。","notes":[]},{"n":6,"t":"院子裏有白色棉和藍色線，用細麻繩、紫色繩繫在白玉石柱的銀環上，又有金銀的床榻擺在紅、白、黃、黑大理石鑲嵌的地上。","notes":[]},{"n":7,"t":"用金器皿盛酒，有很多不同的器皿，照王的厚意提供豐富的御酒。","notes":[]},{"n":8,"t":"飲酒有規定，不准勉強人，因為王吩咐宮裏所有的臣宰，讓人各隨己意。","notes":["「飲酒有規定，不准勉強人」或譯「飲酒用大酒壺，沒有限制」。"]},{"n":9,"t":"瓦實提王后在亞哈隨魯王的宮內也為婦女擺設宴席。","notes":[]},{"n":10,"t":"第七日，亞哈隨魯王飲酒，心中快樂，就吩咐在他面前侍立的七個太監米戶幔、比斯他、哈波拿、比革他、亞拔他、西達、甲迦，","notes":[]},{"n":11,"t":"請瓦實提王后頭戴王后的冠冕到王面前，讓各民族和官員觀看她的美貌，因為她容貌美麗。","notes":[]},{"n":12,"t":"瓦實提王后卻不肯遵照太監所傳的王命前來，所以王非常憤怒，怒火中燒。","notes":[]},{"n":13,"t":"按王的常規，辦事必先詢問知例明法的人。那時，王詢問通達時務的智慧人，","notes":[]},{"n":14,"t":"就是在王左右常見王面、在國中坐高位的波斯和瑪代的七個大臣，甲示拿、示達、押瑪他、他施斯、米力、瑪西拿、米慕干：","notes":[]},{"n":15,"t":"「瓦實提王后不遵照太監所傳的王命，照例應當怎樣辦理呢？」","notes":[]},{"n":16,"t":"米慕干在王和眾官長面前回答說：「瓦實提王后這事，不但得罪王，並且有害於亞哈隨魯王各省的臣民。","notes":[]},{"n":17,"t":"因為王后這事必傳到眾婦人那裏，她們就會藐視自己的丈夫，說：『亞哈隨魯王吩咐瓦實提王后到王面前，她卻不來。』","notes":[]},{"n":18,"t":"今日波斯和瑪代的眾夫人聽見王后這事，必向王所有的官長照樣說，如此必造成無數的藐視和憤怒。","notes":[]},{"n":19,"t":"王若以為好，請降諭旨，寫在波斯和瑪代人的條例中，永不更改，不准瓦實提再到亞哈隨魯王面前，把她王后的位分賜給比她更好的妃子。","notes":[]},{"n":20,"t":"王的諭旨一傳遍全國，國土縱然遼闊，凡作妻子的，無論丈夫是尊貴或卑賤，都必尊敬他。」","notes":[]},{"n":21,"t":"王和眾官長都以這話為美，王就照米慕干的建議去做。","notes":[]},{"n":22,"t":"王下詔書，用各省的文字、各族的語言通知各省，使凡作丈夫的在家中作主，各說本地的語言。","notes":["七十士譯本沒有「各說本地的語言」。"]}]},"2":{"heading":"以斯帖被立為王后","verses":[{"n":1,"t":"這些事以後，亞哈隨魯王的憤怒平息，就想起瓦實提和她所做的，以及自己怎樣降旨辦她。","notes":[]},{"n":2,"t":"於是王的侍臣對王說：「請派人為王尋找美貌的少女；","notes":[]},{"n":3,"t":"請王派官員在國中各省招聚所有美貌的少女到書珊城堡的女院，交給王所派掌管女子的太監希該，給她們香膏塗抹。","notes":[]},{"n":4,"t":"王眼中看為好的女子可以立為王后，代替瓦實提。」王以這話為美，就照樣做。","notes":[]},{"n":5,"t":"書珊城堡中有一個猶太人名叫末底改，是便雅憫人基士的曾孫，示每的孫子，睚珥的兒子。","notes":[]},{"n":6,"t":"從前巴比倫王尼布甲尼撒把猶大王耶哥尼雅和百姓從耶路撒冷擄來，末底改也在被擄的人當中。","notes":["「耶哥尼雅」又名「約雅斤」；參王下24．6。"]},{"n":7,"t":"末底改撫養他叔叔的女兒哈大沙，就是以斯帖，因為她沒有父母。這女子容貌美麗；她父母死了，末底改收她為自己的女兒。","notes":[]},{"n":8,"t":"王的諭旨和敕令傳出之後，許多女子被招聚到書珊城堡，交給掌管女子的希該；以斯帖也被送入王宮，交給希該。","notes":[]},{"n":9,"t":"希該眼中寵愛以斯帖，就恩待她，急忙給她塗抹的香膏和當得的份，又從王宮裏挑選七個宮女來服事她，使她和她的宮女搬入女院上好的房屋。","notes":[]},{"n":10,"t":"以斯帖未曾將自己的籍貫宗族告訴人，因為末底改囑咐她不可叫人知道。","notes":[]},{"n":11,"t":"末底改天天在女院前徘徊，要知道以斯帖是否平安，過得如何。","notes":[]},{"n":12,"t":"眾女子照例先塗抹身體十二個月：六個月用沒藥油，六個月用香料和塗抹的香膏。滿了日期，每個女子挨次進去朝見亞哈隨魯王。","notes":[]},{"n":13,"t":"女子進去朝見王是這樣：從女院到王宮的時候，凡她所要的都必給她帶進去。","notes":[]},{"n":14,"t":"晚上她進去，次日回到另一個女院，交給掌管妃嬪的太監沙甲。除非王喜愛她，再提名召她，她就不再進去見王。","notes":[]},{"n":15,"t":"末底改的叔叔亞比孩的女兒，就是末底改收為自己女兒的以斯帖，按次序要進去朝見王的時候，除了掌管女子的太監希該所分派給她的，她別無所求。凡看見以斯帖的都喜歡她。","notes":[]},{"n":16,"t":"亞哈隨魯王第七年十月，就是提別月，以斯帖被引入宮中朝見王。","notes":[]},{"n":17,"t":"王愛以斯帖過於眾女子，她在王面前蒙寵愛勝過眾少女。王把王后的冠冕戴在她頭上，立她為王后，代替瓦實提。","notes":[]},{"n":18,"t":"王為所有的官長和臣僕擺設大宴席，稱為以斯帖的宴席，又豁免各省的租稅，並照王的厚意大頒賞賜。","notes":[]},{"n":19,"t":"第二次招聚少女的時候，末底改坐在朝門。","notes":[],"heads":["末底改救王的命"]},{"n":20,"t":"以斯帖遵照末底改所囑咐的，沒有將籍貫宗族告訴人；以斯帖照末底改的吩咐去做，正如受他撫養的時候一樣。","notes":[]},{"n":21,"t":"那時候，末底改坐在朝門，王有兩個守門的太監，辟探和提列，惱恨亞哈隨魯王，想要下手害他。","notes":[]},{"n":22,"t":"末底改知道了這件事，就告訴以斯帖王后。以斯帖以末底改的名向王報告。","notes":[]},{"n":23,"t":"這事經過查究後發現是真的，二人就被掛在木頭上。這事在王面前記錄在史籍上。","notes":[]}]},"3":{"heading":"哈曼陰謀除滅猶太人","verses":[{"n":1,"t":"這些事以後，亞哈隨魯王使亞甲人哈米大他的兒子哈曼尊大，提升了他，叫他的爵位超過所有與他同朝的官長。","notes":[]},{"n":2,"t":"在朝門，王所有的臣僕都跪拜哈曼，因為王如此吩咐，但末底改不跪不拜。","notes":[]},{"n":3,"t":"在朝門，王的臣僕對末底改說：「你為何違背王的命令呢？」","notes":[]},{"n":4,"t":"他們天天勸他，他還是不聽，他們就告訴哈曼，要看末底改的事是否站得住，因他已經告訴他們自己是猶太人。","notes":[]},{"n":5,"t":"哈曼見末底改不跪不拜，就非常憤怒。","notes":[]},{"n":6,"t":"有人把末底改的宗族告訴哈曼。哈曼看下手只害末底改一人是小事，還圖謀要滅絕亞哈隨魯王全國所有的猶太人，就是末底改的宗族。","notes":[]},{"n":7,"t":"亞哈隨魯王十二年正月，就是尼散月，人在哈曼面前抽普珥，普珥即籤，要定何月何日；抽到了十二月，就是亞達月。","notes":[]},{"n":8,"t":"哈曼對亞哈隨魯王說：「有一民族散居在王國各省的民族中，與眾不同；他們的律例與萬民的律例不同，也不守王的律例，所以容留他們對王無益。","notes":[]},{"n":9,"t":"王若以為好，請下諭旨滅絕他們，我就捐一萬他連得銀子交給管財政的人，納入王的府庫。」","notes":[]},{"n":10,"t":"於是王從自己手上摘下戒指給猶太人的仇敵，亞甲人哈米大他的兒子哈曼。","notes":[]},{"n":11,"t":"王對哈曼說：「這銀子賜給你，這民族也交給你，可以照你眼中看為好的待他們。」","notes":[]},{"n":12,"t":"正月十三日，王的一些書記受召而來，照著哈曼一切所吩咐的，用各省的文字、各族的語言，奉亞哈隨魯王的名寫諭旨，又用王的戒指蓋印，傳給王的總督、各省的省長，以及各族的領袖。","notes":[]},{"n":13,"t":"詔書由信差傳到王的各省，限令一日之內，就是在十二月，亞達月十三日，把所有的猶太人，無論老少婦女孩子，全然剪除，殺戮滅絕，並搶奪他們的財產。","notes":[]},{"n":14,"t":"這諭旨的抄本以敕令的方式在各省頒佈，通知各族，預備等候那日。","notes":[]},{"n":15,"t":"信差奉王的命令急忙起行，敕令傳遍了書珊城堡。王同哈曼坐下飲酒，書珊城堡卻陷入慌亂中。","notes":[]}]},"4":{"heading":"末底改求以斯帖幫忙","verses":[{"n":1,"t":"末底改知道所發生的這一切事，就撕裂衣服，披麻蒙灰，在城中行走，痛哭哀號。","notes":[]},{"n":2,"t":"他到了朝門前就停住腳步，因為穿麻衣的不可進朝門。","notes":[]},{"n":3,"t":"王的諭旨和敕令所到的各省各處，猶太人都極其悲哀，禁食哭泣哀號，許多人躺在麻布和爐灰中。","notes":[]},{"n":4,"t":"以斯帖王后的宮女和太監來把這事告訴以斯帖，她非常憂愁，就送衣服給末底改穿，要他脫下身上的麻衣，他卻不肯接受。","notes":[]},{"n":5,"t":"以斯帖把王所派伺候她的一個太監哈他革召來，吩咐他去見末底改，要知道到底發生了甚麼事，為何如此。","notes":[]},{"n":6,"t":"於是哈他革出來，到朝門前的廣場見末底改。","notes":[]},{"n":7,"t":"末底改把自己遭遇的一切，以及哈曼為滅絕猶太人答應捐入王庫的銀數都告訴了他；","notes":[]},{"n":8,"t":"又把那傳遍書珊、要滅絕猶太人的諭旨抄本交給哈他革，要他給以斯帖看，並向她說明，囑咐她去晉見王，向王懇求，為本族的人在王面前請命。","notes":[]},{"n":9,"t":"哈他革回來，把末底改的話告訴以斯帖。","notes":[]},{"n":10,"t":"以斯帖吩咐哈他革去見末底改，說：","notes":[]},{"n":11,"t":"「王所有的臣僕和各省的百姓都知道有一個定例，若未奉召見，擅入內院見王的，無論男女必被處死；除非王向他伸出金杖，不得存活。但我沒有被召進去見王已經有三十天了。」","notes":[]},{"n":12,"t":"他們把以斯帖的話告訴末底改。","notes":[]},{"n":13,"t":"末底改託人回覆以斯帖說：「你不要自己以為在王宮裏強過任何猶太人，得以倖免。","notes":[]},{"n":14,"t":"此時你若閉口不言，猶太人必從別處得解脫，蒙拯救；你和你父家必致滅亡。焉知你得了王后的位分不是為現今的機會嗎？」","notes":[]},{"n":15,"t":"以斯帖吩咐人回覆末底改說：","notes":[]},{"n":16,"t":"「你當去召集書珊所有的猶太人，為我禁食三晝三夜，不吃不喝；我和我的宮女也要這樣禁食。然後我違例去晉見王，我若死就死吧！」","notes":[]},{"n":17,"t":"於是末底改照以斯帖一切所吩咐的去做。","notes":[]}]},"5":{"heading":"以斯帖為王和哈曼設宴","verses":[{"n":1,"t":"第三日，以斯帖穿上朝服，站立在王宮的內院，對著王宮。王在殿裏坐在寶座上，對著殿的門。","notes":[]},{"n":2,"t":"王見以斯帖王后站在院內，她在王的眼中得恩寵，王向她伸出手中的金杖。以斯帖往前去摸杖頭。","notes":[]},{"n":3,"t":"王對她說：「以斯帖王后啊，你要甚麼？無論你求甚麼，就是國的一半也必賜給你。」","notes":[]},{"n":4,"t":"以斯帖說：「王若以為好，請王帶著哈曼今日赴我為王預備的宴席。」","notes":[]},{"n":5,"t":"王說：「叫哈曼速速照以斯帖的話去做。」於是王帶著哈曼赴以斯帖所預備的宴席。","notes":[]},{"n":6,"t":"在宴席喝酒的時候，王又對以斯帖說：「你要甚麼，必賜給你；無論你求甚麼，就是國的一半也必給你。」","notes":[]},{"n":7,"t":"以斯帖回答說：「我所要的、我所求的，嗯..。","notes":[]},{"n":8,"t":"我若在王眼前蒙恩，王若願意賜我所要的，准我所求的，就請王和哈曼再赴我為你們預備的宴席。明日我必照王的話去做。」","notes":[]},{"n":9,"t":"那日哈曼心中快樂，歡歡喜喜地出來。但是當他看見末底改在朝門不站起來，也不因他動一下，就滿心惱怒末底改。","notes":[],"heads":["哈曼陰謀殺末底改"]},{"n":10,"t":"哈曼忍著氣回家，叫人請他的一些朋友和他妻子細利斯來。","notes":[]},{"n":11,"t":"哈曼將他的榮華富貴、眾多的兒女，和王使他尊大、提升他高過官長和臣僕的事，都述說給他們聽。","notes":[]},{"n":12,"t":"哈曼又說：「以斯帖王后預備宴席，除了我之外不許別人隨王赴席。明日王后又請我隨王赴席。","notes":[]},{"n":13,"t":"只是每當我看見猶太人末底改坐在朝門，這一切對我就都毫無意義了。」","notes":[]},{"n":14,"t":"他的妻子細利斯和他所有的朋友對他說：「叫人做一個五十肘高的木架，早晨求王把末底改掛在其上，然後你可以歡歡喜喜隨王赴席。」哈曼認為這話很好，就叫人做了木架。","notes":[]}]},"6":{"heading":"王賜末底改榮譽","verses":[{"n":1,"t":"那夜王睡不著覺，吩咐人取歷史書，就是史籍，念給他聽，","notes":[]},{"n":2,"t":"發現書上寫著：王有兩個守門的太監辟探和提列，想要下手害亞哈隨魯王，末底改告發了這件事。","notes":[]},{"n":3,"t":"王說：「末底改做了這事，有沒有賜給他甚麼尊榮或高位呢？」伺候王的臣僕說：「沒有賜給他甚麼。」","notes":[]},{"n":4,"t":"王說：「誰在院子裏？」那時哈曼正進入王宮的外院，要請王把末底改掛在他所預備的木架上。","notes":[]},{"n":5,"t":"王的臣僕對他說：「看哪，哈曼站在院子裏。」王說：「叫他進來。」","notes":[]},{"n":6,"t":"哈曼就進去。王對他說：「王所喜愛要賜尊榮的人，當如何待他呢？」哈曼心裏說：「王所喜愛要賜尊榮的人，除了我，還有誰呢？」","notes":[]},{"n":7,"t":"哈曼就對王說：「王所喜愛要賜尊榮的人，","notes":[]},{"n":8,"t":"當把王所穿的王袍拿來，牽了戴冠的御馬，","notes":[]},{"n":9,"t":"把王袍和御馬都交給王一個極尊貴的大臣，吩咐人把王袍給王所喜愛要賜尊榮的人穿上，領他騎著御馬走遍城裏的廣場，在他面前宣告：『王所喜愛要賜尊榮的人，就是這樣待他。』」","notes":[]},{"n":10,"t":"王對哈曼說：「你速速把這王袍和御馬，照你所說的，向坐在朝門的猶太人末底改去做。凡你所說的，一樣都不可缺。」","notes":[]},{"n":11,"t":"於是哈曼把王袍給末底改穿上，領他騎著御馬走遍城裏的廣場，在他面前宣告：「王所喜愛要賜尊榮的人，就是這樣待他。」","notes":[]},{"n":12,"t":"末底改仍回到朝門，哈曼卻憂憂悶悶地蒙著頭，急忙回家去了。","notes":[]},{"n":13,"t":"哈曼把所遭遇的一切都說給他妻子細利斯和他所有的朋友聽。他的智囊團和他的妻子細利斯對他說：「你在末底改面前開始敗落；他既是猶太人，你必不能勝過他，終必在他面前敗落。」","notes":[]},{"n":14,"t":"他們正跟哈曼說話的時候，王的幾位太監來了，催哈曼快去赴以斯帖所預備的宴席。","notes":[]}]},"7":{"heading":"哈曼被處死","verses":[{"n":1,"t":"王帶著哈曼來赴以斯帖王后的宴席。","notes":[]},{"n":2,"t":"第二天在宴席喝酒的時候，王又對以斯帖說：「以斯帖王后啊，你要甚麼，必賜給你；無論你求甚麼，就是國的一半也必給你。」","notes":[]},{"n":3,"t":"以斯帖王后回答說：「王啊，我若在你眼前蒙恩，王若以為好，我所要的，是王把我的性命賜給我；我所求的，是求我的本族。","notes":[]},{"n":4,"t":"因為我和我的本族被出賣了，要被剪除，殺戮，滅絕。我們若被賣為奴為婢，我就閉口不言；但我們的痛苦比起王的損失，算不得甚麼。」","notes":["「但我們的痛苦...算不得甚麼」或譯「但敵人所得的，抵不過王的損失」。"]},{"n":5,"t":"亞哈隨魯王問以斯帖王后說：「擅敢起意如此行的是誰？這人在哪裏呢？」","notes":[]},{"n":6,"t":"以斯帖說：「仇人敵人就是這惡人哈曼！」哈曼在王和王后面前非常驚惶。","notes":[]},{"n":7,"t":"王大怒，起來離開酒席往御花園去了。哈曼見王定意要加罪於他，就留下來求以斯帖王后救他的命。","notes":[]},{"n":8,"t":"王從御花園回到酒席廳，見哈曼伏在以斯帖所靠的榻上；王說：「他竟敢在宮內、在我面前凌辱王后嗎？」這話一出王口，哈曼的臉就被蒙住了。","notes":[]},{"n":9,"t":"有一個伺候王名叫哈波拿的太監說：「看哪，哈曼還為那報告給王、救王有功的末底改做了一個五十肘高的木架，現今立在哈曼的家裏。」王說：「把哈曼掛在木架上。」","notes":[]},{"n":10,"t":"於是哈曼被掛在他為末底改所預備的木架上；王的憤怒才平息了。","notes":[]}]},"8":{"heading":"猶太人的反擊","verses":[{"n":1,"t":"那日，亞哈隨魯王把猶太人的仇敵哈曼的家產賜給以斯帖王后。末底改也來到王面前，因為以斯帖已經告訴王，末底改跟她是甚麼關係。","notes":[]},{"n":2,"t":"王摘下自己的戒指，就是從哈曼取回的，給了末底改。以斯帖派末底改管理哈曼的家產。","notes":[]},{"n":3,"t":"以斯帖又在王面前求情，俯伏在他腳前，流淚哀求他阻止亞甲人哈曼害猶太人的惡謀。","notes":[]},{"n":4,"t":"王向以斯帖伸出金杖，以斯帖就起來，站在王面前，","notes":[]},{"n":5,"t":"說：「王若以為好，我若在王面前蒙恩，王若認為合宜，我若在王眼前得喜悅，請王下諭旨，廢除亞甲人哈米大他的兒子哈曼設謀，要殺滅王各省的猶太人所頒的詔書。","notes":[]},{"n":6,"t":"我何忍見我本族的人受害？何忍見我同宗的人被滅呢？」","notes":[]},{"n":7,"t":"亞哈隨魯王對以斯帖王后和猶太人末底改說：「因為哈曼要下手害猶太人，看哪，我已把他的家產賜給以斯帖，也把哈曼掛在木架上了。","notes":[]},{"n":8,"t":"你們可以照你們看為好的，奉王的名寫諭旨給猶太人，用王的戒指蓋印；因為奉王的名所寫、用王的戒指蓋印的諭旨是不能廢除的。」","notes":[]},{"n":9,"t":"三月，就是西彎月二十三日，當時王的一些書記受召而來，按著末底改所吩咐的，用各省的文字、各族的語言，以及猶太人的文字語言寫諭旨，傳給那從印度直到古實一百二十七省的猶太人，以及總督、省長和領袖。","notes":[]},{"n":10,"t":"末底改奉亞哈隨魯王的名寫諭旨，用王的戒指蓋印，交給信差們騎上御用的王室快馬去頒佈。","notes":[]},{"n":11,"t":"王准各城各鎮的猶太人在一日之內，在十二月，就是亞達月的十三日聚集，在亞哈隨魯王的各省保護自己的性命，剪除，殺戮，滅絕那要攻擊猶太人的各省各族所有的軍隊，以及他們的妻子兒女，奪取他們的財產為掠物。","notes":[],"end":12},{"n":13,"t":"這諭旨的抄本以敕令的方式在各省頒佈，通知各族，使猶太人預備等候那日，好在仇敵身上報仇。","notes":[]},{"n":14,"t":"於是騎御用快馬的信差奉王命催促，急忙起行；敕令傳遍了書珊城堡。","notes":[]},{"n":15,"t":"末底改穿著藍色白色的朝服，頭戴大金冠冕，又穿紫色細麻布的外袍，從王面前出來；書珊城充滿了歡樂的呼聲。","notes":[]},{"n":16,"t":"猶太人有光榮，歡喜快樂，得享尊貴。","notes":[]},{"n":17,"t":"王的諭旨和敕令所到的各省各城，猶太人都歡喜快樂，擺設宴席，以那日為吉日。國中許多民族的人因懼怕猶太人，就自稱為猶太人。","notes":[]}]},"9":{"heading":"猶太人除滅仇敵","verses":[{"n":1,"t":"十二月，就是亞達月十三日，王的諭旨和敕令要執行的那一日，猶太人的仇敵盼望制伏他們，但猶太人反倒制伏了恨他們的人。","notes":[]},{"n":2,"t":"猶太人在亞哈隨魯王各省的城裏聚集，下手擊殺那些要害他們的人。沒有人能在他們面前站立得住，因為各民族都懼怕他們。","notes":[]},{"n":3,"t":"各省的領袖、總督、省長，和辦理王事務的人，因懼怕末底改，就都幫助猶太人。","notes":[]},{"n":4,"t":"末底改在朝中為大，名聲傳遍各省；末底改這人的權勢日漸擴大。","notes":[]},{"n":5,"t":"猶太人用刀擊殺所有的仇敵，殺滅他們，隨意待那些恨他們的人。","notes":[]},{"n":6,"t":"在書珊城堡中，猶太人殺滅了五百人。","notes":[]},{"n":7,"t":"他們殺了巴珊大他、達分、亞斯帕他、","notes":[]},{"n":8,"t":"破拉他、亞大利雅、亞利大他、","notes":[]},{"n":9,"t":"帕瑪斯他、亞利賽、亞利代、瓦耶撒他；","notes":[]},{"n":10,"t":"這十人都是哈米大他的孫子，猶太人的仇敵哈曼的兒子。猶太人卻沒有下手奪取財物。","notes":[]},{"n":11,"t":"那日，書珊城堡中被殺的人數呈報到王面前。","notes":[]},{"n":12,"t":"王對以斯帖王后說：「猶太人在書珊城堡中殺滅了五百人，又殺了哈曼的十個兒子，在王其餘的各省不知如何。你要甚麼，必賜給你；你還求甚麼，也必為你成就。」","notes":[]},{"n":13,"t":"以斯帖說：「王若以為好，求你允准書珊的猶太人，明日也照今日的諭旨去做，並把哈曼十個兒子的屍體掛在木架上。」","notes":[]},{"n":14,"t":"王允准這麼做。敕令傳遍書珊，哈曼十個兒子的屍體被掛了起來。","notes":[]},{"n":15,"t":"亞達月十四日，在書珊的猶太人又聚集，在書珊殺了三百人，卻沒有下手奪取財物。","notes":[]},{"n":16,"t":"亞達月十三日，在王各省其餘的猶太人也都聚集，保護自己的性命，擺脫仇敵得享平安。他們殺了七萬五千個恨他們的人，卻沒有下手奪取財物；十四日他們休息，以這日為設宴歡樂的日子。","notes":[],"end":17},{"n":18,"t":"但書珊的猶太人卻在十三日、十四日聚集；十五日休息，以這日為設宴歡樂的日子。","notes":[]},{"n":19,"t":"所以住在無城牆的鄉村的猶太人，都以亞達月十四日為設宴歡樂的吉日，彼此餽送禮物。","notes":[]},{"n":20,"t":"末底改記錄這些事，寫信給亞哈隨魯王各省遠近所有的猶太人，","notes":[],"heads":["普珥日"]},{"n":21,"t":"吩咐他們每年守亞達月十四、十五兩日，","notes":[]},{"n":22,"t":"以這兩日為猶太人擺脫仇敵得享平安、轉憂為喜、轉悲為樂的吉日，並在這兩日設宴歡樂，彼此餽送禮物，賙濟窮人。","notes":[]},{"n":23,"t":"於是，猶太人照末底改所寫給他們的，把開始所做的作為遵守的定例。","notes":[]},{"n":24,"t":"因為猶太人的仇敵亞甲人哈米大他的兒子哈曼設謀要殺害猶太人，抽普珥，普珥即籤，為要殺盡滅絕他們；","notes":[]},{"n":25,"t":"但這陰謀到了王面前，王卻降旨使哈曼謀害猶太人的惡事歸到他自己的頭上，他和他的眾子都被掛在木架上。","notes":["「這陰謀」或譯「以斯帖」。"]},{"n":26,"t":"所以猶太人照著普珥這名字稱這兩日為普珥日。他們因這信上一切的話，又因所看見所遇見的事，","notes":[]},{"n":27,"t":"就規定自己與後裔，以及歸化他們的人，每年按所寫的、按時守這兩日，永久不廢。","notes":[]},{"n":28,"t":"各省各城、世世代代、家家戶戶都記念並守這兩日，使這普珥日在猶太人中不可廢掉，在他們後裔中也永不遺忘。","notes":[]},{"n":29,"t":"亞比孩的女兒以斯帖王后和猶太人末底改以全權寫第二封信，堅立這普珥日，","notes":[]},{"n":30,"t":"送信給亞哈隨魯王國中一百二十七省所有的猶太人，祝他們平安和安穩，","notes":[]},{"n":31,"t":"勸他們遵照猶太人末底改和以斯帖王后所規定的，按時守這普珥日，並照著猶太人為自己與後裔所規定的，禁食與哀求。","notes":[]},{"n":32,"t":"以斯帖規定了守普珥日的條例，這事也記錄在書上。","notes":[]}]},"10":{"heading":"亞哈隨魯和末底改的功績","verses":[{"n":1,"t":"亞哈隨魯王向國中和海島的人徵稅。","notes":[]},{"n":2,"t":"他以權柄能力所做的一切，以及他使末底改尊大、提升他的事，豈不都寫在瑪代和波斯王的史籍上嗎？","notes":[]},{"n":3,"t":"猶太人末底改作亞哈隨魯王的宰相，在猶太人中為大，得許多弟兄的喜悅，為本族的人爭取福利，為他所有的後代謀求幸福。","notes":[]}]}},"JOB":{"1":{"heading":"撒但試探約伯","verses":[{"n":1,"t":"烏斯地有一個人名叫約伯。這人完全、正直、敬畏神、遠離惡事。","notes":[]},{"n":2,"t":"他生了七個兒子，三個女兒。","notes":[]},{"n":3,"t":"他的家產有七千隻羊，三千匹駱駝，五百對牛，五百匹母驢，並有許多僕婢。這人在東方人中為至大。","notes":[]},{"n":4,"t":"他的兒子按著日子各在自己家裏擺設宴席，派人去請他們的三個姊妹來，與他們一同吃喝。","notes":[]},{"n":5,"t":"宴席的日子過了，約伯派人去叫他們自潔。他清早起來，按著他們眾人的數目獻燔祭，因為他說：「恐怕我的兒子犯了罪，心中背棄神。」約伯常常這樣行。","notes":["「背棄」：原文是「詛咒」；11節同。"]},{"n":6,"t":"有一天，神的眾使者來侍立在耶和華面前，撒但也來在其中。","notes":["「神的眾使者」：原文直譯「神的眾子」。"]},{"n":7,"t":"耶和華對撒但說：「你從哪裏來？」撒但回答耶和華說：「我從地上走來走去，在那裏往返。」","notes":[]},{"n":8,"t":"耶和華對撒但說：「你曾用心察看我的僕人約伯沒有？地上再沒有人像他那樣完全、正直、敬畏神、遠離惡事。」","notes":[]},{"n":9,"t":"撒但回答耶和華說：「約伯敬畏神，豈是無故呢？","notes":[]},{"n":10,"t":"你豈不是四面圈上籬笆圍護他和他的家，以及他一切所有的嗎？他手所做的都蒙你賜福，他的家產也在地上增多。","notes":[]},{"n":11,"t":"但你若伸手毀他一切所有的，他必當面背棄你。」","notes":[]},{"n":12,"t":"耶和華對撒但說：「看哪，凡他所有的都在你手中；只是不可伸手加害於他。」於是撒但從耶和華面前退出去。","notes":[]},{"n":13,"t":"有一天，約伯的兒女正在他們長兄的家裏吃飯喝酒，","notes":[],"heads":["約伯喪失兒女和財產"]},{"n":14,"t":"有報信的來見約伯，說：「牛正耕地，母驢在旁邊吃草，","notes":[]},{"n":15,"t":"示巴人忽然闖來，把牲畜擄去，並用刀殺了僕人；惟有我一人逃脫，來報信給你。」","notes":[]},{"n":16,"t":"他還說話的時候，又有人來說：「神從天上降下火來，把羊群和僕人都吞滅了；惟有我一人逃脫，來報信給你。」","notes":[]},{"n":17,"t":"他還說話的時候，又有人來說：「迦勒底人分成三隊忽然闖來，把駱駝擄去，並用刀殺了僕人；惟有我一人逃脫，來報信給你。」","notes":[]},{"n":18,"t":"他還說話的時候，又有人來說：「你的兒女正在他們長兄的家裏吃飯喝酒，","notes":[]},{"n":19,"t":"看哪，有狂風從曠野颳來，襲擊房屋的四角，房屋倒塌在年輕人身上，他們就都死了；惟有我一人逃脫，來報信給你。」","notes":[]},{"n":20,"t":"約伯就起來，撕裂外袍，剃了頭，俯伏在地敬拜，","notes":[]},{"n":21,"t":"說：「我赤身出於母胎，也必赤身歸回；賞賜的是耶和華，收取的也是耶和華。耶和華的名是應當稱頌的。」","notes":[]},{"n":22,"t":"在這一切的事上，約伯並沒有犯罪，也不以神為狂妄。","notes":[]}]},"2":{"heading":"撒但再試探約伯","verses":[{"n":1,"t":"又有一天，神的眾使者來侍立在耶和華面前，撒但也來在其中。","notes":["「神的眾使者」：原文直譯「神的眾子」。"]},{"n":2,"t":"耶和華問撒但說：「你從哪裏來？」撒但回答說：「我從地上走來走去，在那裏往返。」","notes":[]},{"n":3,"t":"耶和華對撒但說：「你曾用心察看我的僕人約伯沒有？地上再沒有人像他那樣完全、正直、敬畏神、遠離惡事。你雖激起我攻擊他，無故吞滅他，他仍然持守他的純正。」","notes":[]},{"n":4,"t":"撒但回答耶和華說：「人以皮代皮，情願捨去一切所有的，來保全性命。","notes":[]},{"n":5,"t":"但你若伸手傷他的骨頭和他的肉，他必當面背棄你。」","notes":["「背棄」：原文是「詛咒」；9節同。"]},{"n":6,"t":"耶和華對撒但說：「看哪，他在你手中，只要留下他的性命。」","notes":[]},{"n":7,"t":"於是撒但從耶和華面前退出去，擊打約伯，使他從腳掌到頭頂長毒瘡。","notes":[]},{"n":8,"t":"約伯就坐在灰燼中，拿瓦片刮身體。","notes":[]},{"n":9,"t":"他的妻子對他說：「你仍然持守你的純正嗎？你背棄神，死了吧！」","notes":[]},{"n":10,"t":"約伯卻對她說：「你說話，正如愚頑的婦人。唉！難道我們從神手裏得福，不也受禍嗎？」在這一切的事上，約伯並沒有以口犯罪。","notes":[]},{"n":11,"t":"約伯的三個朋友，提幔人以利法、書亞人比勒達、拿瑪人瑣法，聽說這一切的災禍臨到他身上，各人就從自己的地方相約同來，為他悲傷，安慰他。","notes":[],"heads":["三個朋友來安慰約伯"]},{"n":12,"t":"他們遠遠地舉目觀看，認不出他來，就放聲大哭。各人撕裂外袍，向空中撒塵土，落在自己的頭上。","notes":[]},{"n":13,"t":"他們同他七天七夜坐在地上，一句話也不對他說，因為他們見到了極大的痛苦。","notes":[]}]},"3":{"heading":"約伯詛咒自己","verses":[{"n":1,"t":"此後，約伯開口詛咒自己的生日。","notes":["「自己的生日」：原文是「自己的日子」。"]},{"n":2,"t":"約伯說：","notes":[]},{"n":3,"t":"「願我生的那日滅沒，說『懷了男胎』的那夜也滅沒。","notes":[]},{"n":4,"t":"願那日變為黑暗，願神不從上面尋找它，願亮光不照於其上。","notes":[]},{"n":5,"t":"願黑暗和死蔭索取那日，願密雲停在其上，願白天的昏暗恐嚇它。","notes":["「白天的昏暗」或譯「日蝕」。"]},{"n":6,"t":"願那夜被幽暗奪取，不在一年的日子中喜樂，也不列入月中的數目。","notes":[]},{"n":7,"t":"看哪，願那夜沒有生育，其間也沒有歡樂的聲音。","notes":[]},{"n":8,"t":"願那些詛咒日子且能惹動力威亞探的，詛咒那夜。","notes":["「力威亞探」是音譯，一種海獸；或譯「鱷魚」。"]},{"n":9,"t":"願那夜黎明的星宿變為黑暗，盼亮卻不亮，也不見晨曦破曉；","notes":["「晨曦破曉」：原文直譯「清晨的眼皮」。"]},{"n":10,"t":"因它沒有把懷我胎的門關閉，也沒有從我的眼中隱藏患難。","notes":[]},{"n":11,"t":"「我為何不出母胎而死？為何不出母腹就氣絕呢？","notes":[]},{"n":12,"t":"為何有膝蓋接收我？為何有奶哺養我呢？","notes":[]},{"n":13,"t":"不然，我現在已躺臥安睡，而且，早已長眠安息；","notes":[]},{"n":14,"t":"與那些為自己重建荒涼之處，地上的君王和謀士在一起；","notes":[]},{"n":15,"t":"或與把銀子裝滿房屋，擁有金子的王子在一起；","notes":[]},{"n":16,"t":"我為何不像流產的胎兒被埋藏，如同未見光的嬰孩？","notes":[]},{"n":17,"t":"在那裏惡人止息攪擾，在那裏困乏人得享安息，","notes":[]},{"n":18,"t":"被囚的人同得安逸，不再聽見監工的聲音。","notes":[]},{"n":19,"t":"大的小的都在那裏，奴僕脫離主人得自由。","notes":[]},{"n":20,"t":"「遭受患難的人為何有光賜給他呢？心中愁苦的人為何有生命賜給他呢？","notes":[]},{"n":21,"t":"他們等死，卻不得死；求死，勝於求隱藏的珍寶。","notes":[]},{"n":22,"t":"他們尋見墳墓，就歡喜快樂，極其高興。","notes":[]},{"n":23,"t":"這人的道路遮隱，神又四面圍困他。","notes":[]},{"n":24,"t":"我吃飯前就發出嘆息，我的唉哼湧出如水。","notes":[]},{"n":25,"t":"因我所恐懼的臨到我，我所懼怕的迎向我；","notes":[]},{"n":26,"t":"我不得安逸，不得平靜，也不得安息，卻有患難來到。」","notes":[]}]},"4":{"heading":"第一次對話","verses":[{"n":1,"t":"提幔人以利法回答說：","notes":[]},{"n":2,"t":"「人想與你說話，你就厭煩嗎？但誰能忍住不發言呢？","notes":[]},{"n":3,"t":"看哪，你素來教導許多人，又堅固軟弱的手。","notes":[]},{"n":4,"t":"你的言語曾扶助跌倒的人；你使軟弱的膝蓋穩固。","notes":[]},{"n":5,"t":"但現在禍患臨到你，你就煩躁了；它挨近你，你就驚惶。","notes":["「禍患臨到」：原文是「它臨到」。"]},{"n":6,"t":"你的倚靠不是在於你敬畏神嗎？你的盼望不是在於你行事純正嗎？","notes":[]},{"n":7,"t":"「請你追想：無辜的人有誰滅亡？正直的人何處被剪除？","notes":[]},{"n":8,"t":"按我所見，耕罪孽的，種毒害的，照樣收割。","notes":[]},{"n":9,"t":"神一噓氣，他們就滅亡；神一發怒，他們就消失。","notes":[]},{"n":10,"t":"獅子吼叫，猛獅咆哮，少壯獅子的牙齒被敲斷。","notes":[]},{"n":11,"t":"公獅因缺獵物而死，母獅的幼獅都離散。","notes":[]},{"n":12,"t":"「有話暗中傳遞給我，耳朵聽其微小的聲音。","notes":[]},{"n":13,"t":"世人沉睡的時候，從夜間異象的雜念中，","notes":[]},{"n":14,"t":"恐懼戰兢臨到我身，使我百骨戰抖。","notes":[]},{"n":15,"t":"有靈從我面前經過，我身上的毫毛豎立。","notes":[]},{"n":16,"t":"那靈停住，我卻不能辨其形狀；有形像在我眼前。我在靜默中聽見有聲音：","notes":[]},{"n":17,"t":"『必死的人能比神公義嗎？壯士能比造他的主純潔嗎？","notes":[]},{"n":18,"t":"看哪，主不信靠他的僕人，尚且指他的使者為愚昧，","notes":[]},{"n":19,"t":"何況那些住在泥屋、根基在塵土裏、被蛀蟲所毀壞的人呢？","notes":[]},{"n":20,"t":"早晚之間，他們就被毀滅，永歸無有，無人理會。","notes":[]},{"n":21,"t":"他們帳棚的繩索豈不從中拔出來呢？他們死，且是無智慧而死。』」","notes":[]}]},"5":{"heading":"","verses":[{"n":1,"t":"「你呼求吧，有誰回答你呢？聖者之中，你轉向哪一位呢？","notes":[]},{"n":2,"t":"憤怒害死愚妄人，嫉妒殺死愚蠢的人。","notes":[]},{"n":3,"t":"我曾見愚妄人扎下根，但我忽然詛咒他的住處。","notes":[]},{"n":4,"t":"他的兒女遠離穩妥之地，在城門口被欺壓，無人搭救。","notes":[]},{"n":5,"t":"他的莊稼被飢餓的人吃盡了，就是在荊棘裏的也搶去了；他的財寶被陷阱張口吞沒了。","notes":["「陷阱」：有古譯本是「口渴的人」。"]},{"n":6,"t":"因為禍患不是從塵土中出來，患難也不是從土地裏長出。","notes":[]},{"n":7,"t":"人生出來必遭遇患難，如同火花飛騰。","notes":["「火花」或譯「鳥兒」。"]},{"n":8,"t":"「至於我，我必尋求神，把我的事情交託給他。","notes":[]},{"n":9,"t":"他行大事不可測度，行奇事不可勝數。","notes":[]},{"n":10,"t":"他降雨在地面，賜水於田野。","notes":[]},{"n":11,"t":"他將卑微的人安置在高處，將哀痛的人舉到穩妥之地。","notes":[]},{"n":12,"t":"他破壞通達人的計謀，使他們手所做的不得成就。","notes":[]},{"n":13,"t":"他使有智慧的人中了自己的詭計，叫狡詐人的計謀速速落空。","notes":[]},{"n":14,"t":"他們白晝遇見黑暗，午間摸索如在夜間。","notes":[]},{"n":15,"t":"神拯救貧窮人脫離殘暴人的手，脫離他們口中的刀。","notes":[]},{"n":16,"t":"這樣，貧寒人有指望，不義的人閉口無言。","notes":[]},{"n":17,"t":"「看哪，神所懲治的人是有福的！所以你不可輕看全能者的管教。","notes":[]},{"n":18,"t":"因為他打傷，又包紮；他擊傷，又親手醫治。","notes":[]},{"n":19,"t":"你六次遭難，他必救你；就是七次，災禍也無法害你。","notes":[]},{"n":20,"t":"在饑荒中，他必救你脫離死亡；在戰爭中，他必救你脫離刀劍的權勢。","notes":[]},{"n":21,"t":"你必被隱藏，不受口舌之害；災害臨到，你也不懼怕。","notes":[]},{"n":22,"t":"對於災害饑饉，你必譏笑；至於地上的野獸，你也不懼怕。","notes":[]},{"n":23,"t":"因為你必與田間的石頭立約，田裏的野獸也必與你和好。","notes":[]},{"n":24,"t":"你必知道你的帳棚平安，你查看你的羊圈，一無所失。","notes":[]},{"n":25,"t":"你也必知道你的後裔眾多，你的子孫像地上的青草。","notes":[]},{"n":26,"t":"你必壽高年邁才歸墳墓，好像禾捆按時收藏。","notes":[]},{"n":27,"t":"看哪，這道理我們已經考察，本是如此。你須要聽，要親自明白。」","notes":[]}]},"6":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"「惟願我的煩惱被秤一秤，我一切的災害放在天平裏，","notes":[]},{"n":3,"t":"現今都比海沙更重，所以我說話急躁。","notes":[]},{"n":4,"t":"因全能者的箭射中了我，我的靈喝盡其毒；神的驚嚇擺陣攻擊我。","notes":[]},{"n":5,"t":"野驢有草豈會叫喚？牛有飼料豈會吼叫？","notes":[]},{"n":6,"t":"食物淡而無鹽豈可吃呢？蛋白有甚麼滋味呢？","notes":[]},{"n":7,"t":"那些可厭的食物，我心不肯挨近。","notes":[]},{"n":8,"t":"「惟願我得著所求的，神賞賜我所切望的，","notes":[]},{"n":9,"t":"願神把我壓碎，伸手將我剪除。","notes":[]},{"n":10,"t":"我因沒有違棄那聖者的言語，就仍以此為安慰，在不止息的痛苦中還可歡躍。","notes":[]},{"n":11,"t":"我有甚麼氣力使我等候？我有甚麼結局使我忍耐？","notes":[]},{"n":12,"t":"我的氣力豈是石頭的氣力？我的肉身豈是銅呢？","notes":[]},{"n":13,"t":"在我裏面豈不是無助嗎？智慧豈不是從我心中被趕逐嗎？","notes":[]},{"n":14,"t":"「灰心的人，他的朋友當以慈愛待他，因為他將離棄敬畏全能者的心。","notes":[]},{"n":15,"t":"我的弟兄詭詐，好像河道，像溪水流過的河床，","notes":[]},{"n":16,"t":"因結冰而混濁，有雪藏在其中，","notes":[]},{"n":17,"t":"暖和的時候就溶化，炎熱時便從原處乾涸。","notes":[]},{"n":18,"t":"商隊偏離道路，上到荒涼之地而死亡。","notes":[]},{"n":19,"t":"提瑪的商隊瞻望，示巴的旅客等候。","notes":[]},{"n":20,"t":"他們因希望落空就抱愧，來到那裏便蒙羞。","notes":[]},{"n":21,"t":"現在你們正是這樣，看見驚嚇的事就懼怕。","notes":["「你們正是這樣」：原文另譯「你們算不得甚麼」。"]},{"n":22,"t":"我豈說：『請你們供給我，從你們的財物中送禮給我』？","notes":[]},{"n":23,"t":"或說：『請你們拯救我脫離敵人的手，救贖我脫離殘暴人的手』嗎？","notes":[]},{"n":24,"t":"「請你們指教我，我就不作聲；我在何事上有錯，請使我明白。","notes":[]},{"n":25,"t":"正直言語的力量何其大！但你們責備是責備甚麼呢？","notes":[]},{"n":26,"t":"絕望人的講論既然如風，你們還計劃批駁言語嗎？","notes":[]},{"n":27,"t":"你們甚至為孤兒抽籤，把朋友當貨物。","notes":[]},{"n":28,"t":"「現在，請你們看著我，我絕不當面說謊。","notes":[]},{"n":29,"t":"請你們轉意，不要不公義；請再轉意，正義在我這裏。","notes":[]},{"n":30,"t":"我的舌頭豈有不公義嗎？我的上膛豈不辨奸惡嗎？」","notes":[]}]},"7":{"heading":"","verses":[{"n":1,"t":"「人在世上豈無勞役呢？他的日子不像雇工的日子嗎？","notes":[]},{"n":2,"t":"像奴僕切慕陰涼，像雇工等待工錢，","notes":[]},{"n":3,"t":"我也照樣度過虛空的歲月，愁煩的夜晚指定給我。","notes":[]},{"n":4,"t":"我躺臥的時候就說：『我何時可以起來呢？』漫漫長夜，我總是翻來覆去，直到天亮。","notes":[]},{"n":5,"t":"我的肉體以蟲子和塵土為衣，我的皮膚才收了口又流膿。","notes":[]},{"n":6,"t":"我的日子比織布的梭更快，都消耗在沒有指望之中。","notes":[]},{"n":7,"t":"「你要記得，我的生命不過是一口氣，我的眼睛必不再看見福樂。","notes":[]},{"n":8,"t":"觀看我的人，他的眼必不看見我；你的眼目投向我，我卻不在了。","notes":[]},{"n":9,"t":"雲彩消散而去；照樣，人下陰間也不再上來。","notes":[]},{"n":10,"t":"他不再回自己的家，他自己的地方也不再認得他。","notes":[]},{"n":11,"t":"「我甚至不封我的口；我靈愁苦，要發出言語；我心苦惱，要吐露哀情。","notes":[]},{"n":12,"t":"我豈是海洋，豈是大魚，你竟防守著我呢？","notes":[]},{"n":13,"t":"我若說：『我的床必安慰我，我的榻必分擔我的苦情』，","notes":[]},{"n":14,"t":"你就用夢驚擾我，用異象恐嚇我。","notes":[]},{"n":15,"t":"甚至我寧可窒息死亡，勝似留我這副骨頭。","notes":[]},{"n":16,"t":"我厭棄生命，不願永遠活著。你任憑我吧，因我的日子都是虛空。","notes":[]},{"n":17,"t":"人算甚麼，你竟看他為大，將他放在心上，","notes":[]},{"n":18,"t":"每早晨鑒察他，每時刻考驗他？","notes":[]},{"n":19,"t":"你到何時才轉眼不看我，任憑我咽下唾沫呢？","notes":[]},{"n":20,"t":"鑒察人的主啊，我若有罪，於你何妨？為何以我當你的箭靶，使我成為你的重擔呢？","notes":[]},{"n":21,"t":"為何不赦免我的過犯，除掉我的罪孽呢？我現今要躺臥在塵土中；你要切切尋找我，我卻不在了。」","notes":[]}]},"8":{"heading":"","verses":[{"n":1,"t":"書亞人比勒達回答說：","notes":[]},{"n":2,"t":"「這些話你要說到幾時？你口中的言語如狂風要到幾時呢？","notes":[]},{"n":3,"t":"神豈能偏離公平？全能者豈能偏離公義？","notes":[]},{"n":4,"t":"或者你的兒女得罪了他，他就把他們交在過犯的掌控中。","notes":[]},{"n":5,"t":"你若切切尋求神，向全能者懇求；","notes":[]},{"n":6,"t":"你若純潔正直，他必定為你興起，使你公義的居所興旺。","notes":[]},{"n":7,"t":"你起初雖然微小，日後必非常強盛。","notes":[]},{"n":8,"t":"「請你詢問上代，思念他們祖先所查究的。","notes":[]},{"n":9,"t":"我們不過從昨日才有，一無所知，因我們在世的日子好像影子。","notes":[]},{"n":10,"t":"他們豈不指教你，告訴你，說出發自內心的言語呢？","notes":[]},{"n":11,"t":"「蒲草沒有泥豈能生長？蘆荻沒有水豈能長大？","notes":[]},{"n":12,"t":"它還青翠，沒有割下的時候，比百樣的草先枯槁。","notes":[]},{"n":13,"t":"凡忘記神的人，路途也是這樣；不虔敬人的指望要滅沒。","notes":[]},{"n":14,"t":"他所仰賴的必折斷，他所倚靠的是蜘蛛網。","notes":[]},{"n":15,"t":"他要倚靠房屋，房屋卻站立不住；他要抓住房屋，房屋卻不能存留。","notes":[]},{"n":16,"t":"他在日光之下茂盛，嫩枝在園中蔓延；","notes":[]},{"n":17,"t":"他的根盤繞石堆，鑽入石縫。","notes":["「鑽入石縫」：原文是「看見石屋」。"]},{"n":18,"t":"他若從本地被拔出，那地就不認識他，說：『我沒有見過你。』","notes":[]},{"n":19,"t":"看哪，這就是他道路中的喜樂，以後必另有人從塵土而生。","notes":[]},{"n":20,"t":"看哪，神必不丟棄完全人，也不扶助邪惡人的手。","notes":[]},{"n":21,"t":"他還要以喜笑充滿你的口，以歡呼充滿你的嘴唇。","notes":[]},{"n":22,"t":"恨惡你的要披戴羞愧，惡人的帳棚必歸於無有。」","notes":[]}]},"9":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"「我真的知道是這樣，但人在神前怎能成為義呢？","notes":[]},{"n":3,"t":"人若想要與他爭辯，千次中也不能回答一次。","notes":[]},{"n":4,"t":"他心裏有智慧，且大有能力。誰向神剛硬而得平安呢？","notes":[]},{"n":5,"t":"他把山挪移，山卻不知，他在怒氣中，把山翻倒。","notes":[]},{"n":6,"t":"他使地震動，離其本位，地的柱子就搖撼。","notes":[]},{"n":7,"t":"他吩咐太陽，太陽就不出來，又封住眾星。","notes":[]},{"n":8,"t":"他獨自鋪張諸天，步行在海浪之上。","notes":[]},{"n":9,"t":"他造北斗、參星、昴星，以及南方的星宿；","notes":["「南方的星宿」：原文是「南方的內宮」。"]},{"n":10,"t":"他行大事不可測度，行奇事不可勝數。","notes":[]},{"n":11,"t":"看哪，他從我旁邊經過，我看不見；他走過，我沒有察覺他。","notes":[]},{"n":12,"t":"看哪，他奪去，誰能阻擋他？誰敢對他說：『你做甚麼呢？』","notes":[]},{"n":13,"t":"「神必不收回他的怒氣，扶助拉哈伯的，屈身在神以下。","notes":["「拉哈伯」是神話故事中的大海怪。"]},{"n":14,"t":"既是這樣，我怎敢回答他，怎敢在他之前選擇辯詞呢？","notes":[]},{"n":15,"t":"我雖有義，也不能回答，我要向那審判我的懇求。","notes":[]},{"n":16,"t":"我若呼求，縱然他應允我，我仍不信他會側耳聽我的聲音。","notes":[]},{"n":17,"t":"他用暴風摧折我，無故加增我的損傷。","notes":["「用暴風」：原文另譯「為一根頭髮」。"]},{"n":18,"t":"他不容我喘一口氣，倒使我飽受苦惱。","notes":[]},{"n":19,"t":"若論力量，看哪，他真有能力！若論審判，『誰能傳我呢？』","notes":[]},{"n":20,"t":"我雖有義，我的口要定我有罪；我雖完全，他必證明我為彎曲。","notes":[]},{"n":21,"t":"我雖完全，不顧自己；我厭棄我的性命。","notes":[]},{"n":22,"t":"所以我說，都是一樣；完全人和惡人，他都滅絕。","notes":[]},{"n":23,"t":"若災禍忽然帶來死亡，他必戲笑無辜人的苦難。","notes":[]},{"n":24,"t":"世界交在惡人手中；他蒙蔽世界審判官的臉，若不是他，那麼是誰呢？","notes":[]},{"n":25,"t":"「我的日子比奔跑者更快，急速過去，不見福樂。","notes":[]},{"n":26,"t":"我的日子如蒲草船掠過，如鷹俯衝抓食。","notes":[]},{"n":27,"t":"我若說：『我要忘記我的苦情，強顏歡笑』，","notes":[]},{"n":28,"t":"我就因一切的愁苦而懼怕；我知道你必不以我為無辜。","notes":[]},{"n":29,"t":"我必被定罪，我何必徒然勞苦呢？","notes":[]},{"n":30,"t":"我若用雪水洗身，用鹼潔淨我的手掌，","notes":[]},{"n":31,"t":"你還要把我扔在坑裏，我的衣服都憎惡我。","notes":[]},{"n":32,"t":"他不像我是個人，使我可以回答他，使我們可以一同受審判。","notes":[]},{"n":33,"t":"我們中間沒有仲裁者，可以按手在我們兩造之間。","notes":[]},{"n":34,"t":"願他使他的杖離開我，不使他的威嚴恐嚇我，","notes":[]},{"n":35,"t":"我就說話，不懼怕他；但對我來說，我卻不是這樣。」","notes":[]}]},"10":{"heading":"","verses":[{"n":1,"t":"「我厭惡自己的性命，任由我述說自己的苦情；因心裏苦惱，我要說話。","notes":[]},{"n":2,"t":"我對神說，不要定我有罪，要指示我，你為何與我爭辯？","notes":[]},{"n":3,"t":"你手所造的，你又欺壓，又藐視，卻光照惡人的計謀。這事你以為美嗎？","notes":[]},{"n":4,"t":"你的眼豈是肉眼？你察看豈像人察看嗎？","notes":[]},{"n":5,"t":"你的日子豈像人的日子，你的年歲豈像壯士的年歲，","notes":[]},{"n":6,"t":"你就追問我的罪孽，尋察我的罪過嗎？","notes":[]},{"n":7,"t":"其實，你知道我沒有行惡，也無人能施行拯救，脫離你的手。","notes":[]},{"n":8,"t":"你的手塑造我，造了我，但我整個人卻要一起被你吞滅。","notes":[]},{"n":9,"t":"求你記得，你製造我如泥土，你還要使我歸回塵土嗎？","notes":[]},{"n":10,"t":"你不是倒出我來好像奶，使我凝結如同奶酪嗎？","notes":[]},{"n":11,"t":"你以皮和肉給我穿上，用骨與筋把我聯結起來。","notes":[]},{"n":12,"t":"你將生命和慈愛賜給我，你也眷顧保全我的靈。","notes":[]},{"n":13,"t":"然而，你把這些事藏在你心裏，我知道這是你的旨意。","notes":[]},{"n":14,"t":"我若犯罪，你就察看我，並不赦免我的罪。","notes":[]},{"n":15,"t":"我若行惡，我就有禍了；我若行義，也不敢抬頭，而是飽受羞辱，看見我的痛苦。","notes":[]},{"n":16,"t":"你如獅子昂首追捕我，又在我身上顯出奇事。","notes":["「你如...追捕我」：有古譯本是「我若昂首自得，你就追捕我如獅子」。"]},{"n":17,"t":"你更新你的見證對付我，向我加增惱怒，調遣軍隊攻擊我。","notes":[]},{"n":18,"t":"「你為何使我出母胎呢？甚願我當時氣絕，沒有眼睛看見我。","notes":[]},{"n":19,"t":"這樣，就如從未有過我，我一出母胎就被送入墳墓。","notes":[]},{"n":20,"t":"我的日子不是短少嗎？求你停止，求你放過我，使我可以稍得喜樂，","notes":["「求你停止，求你放過我」：原文另譯「願他停止，願他放過我」。"]},{"n":21,"t":"就是在我去而不返，往黑暗和死蔭之地以先。","notes":[]},{"n":22,"t":"那是烏黑之地，猶如幽暗的死蔭，毫無秩序；發出的光輝也像幽暗。」","notes":[]}]},"11":{"heading":"","verses":[{"n":1,"t":"拿瑪人瑣法回答說：","notes":[]},{"n":2,"t":"「這許多的話豈不該回答嗎？多嘴多舌的人豈可成為義呢？","notes":[]},{"n":3,"t":"你誇大的話豈能使人不作聲嗎？你戲笑的時候豈沒有人使你受辱嗎？","notes":[]},{"n":4,"t":"你說：『我的教導純全，我在你眼前是清潔的。』","notes":[]},{"n":5,"t":"但是，惟願神說話，願他張開嘴唇攻擊你。","notes":[]},{"n":6,"t":"願他將智慧的奧祕指示你，因為健全的知識是兩面的。你當知道，神使你忘記你的一些罪孽。","notes":[]},{"n":7,"t":"你能尋見神的奧祕嗎？你能尋見全能者的極限嗎？","notes":[]},{"n":8,"t":"高如諸天，你能做甚麼？比陰間深，你能知道甚麼？","notes":[]},{"n":9,"t":"其量度比地長，比海更寬。","notes":[]},{"n":10,"t":"他若經過，把人拘禁，召集會眾，誰能阻擋他呢？","notes":[]},{"n":11,"t":"因為他知道虛妄的人；當他看見罪惡，豈不留意嗎？","notes":[]},{"n":12,"t":"空虛的人若獲得知識，野驢生下的駒子也成了人。","notes":[]},{"n":13,"t":"「至於你，若堅固己心，又向主舉手；","notes":[]},{"n":14,"t":"你若遠遠脫離你手中的罪孽，不容許不義住在你帳棚之中；","notes":[]},{"n":15,"t":"這樣，你必仰起臉來，毫無瑕疵；你也必安穩，無所懼怕。","notes":[]},{"n":16,"t":"你必忘記你的苦楚，就是想起來，也如流過的水。","notes":[]},{"n":17,"t":"你在世要升高，比正午更明，雖有黑暗，仍像早晨。","notes":[]},{"n":18,"t":"你因有指望就必穩固，也必四圍察看，安然躺下。","notes":["「四圍察看」：原文另譯「得到庇護」。"]},{"n":19,"t":"你躺臥，無人驚嚇，並有許多人向你求恩。","notes":[]},{"n":20,"t":"但惡人的眼睛要失明；他們無路可逃，他們的指望就是氣絕身亡。」","notes":[]}]},"12":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"「你們果真是人物啊！智慧要與你們一同去死。","notes":[]},{"n":3,"t":"但我也有聰明，跟你們一樣，並非不及你們。這些事，誰不知道呢？","notes":[]},{"n":4,"t":"我這求告神、蒙他應允的人竟成了朋友所譏笑的；又公義又完全的人竟遭受譏笑。","notes":[]},{"n":5,"t":"安逸的人心裏藐視災禍，這災禍在等待失足滑跌的人。","notes":[]},{"n":6,"t":"強盜的帳棚安寧，惹神發怒的人穩固，他們把神握在自己手中。","notes":["「神」或譯「神明」。","「他們把神握在自己手中」或譯「神把他們領到自己的手中」。"]},{"n":7,"t":"「你問走獸，走獸必指教你；你問空中的飛鳥，飛鳥必告訴你；","notes":[]},{"n":8,"t":"或者你與地說話，地必指教你；海中的魚也必向你說明。","notes":["「你與...指教你」或譯「你問地上的草木，草木必指教你」。"]},{"n":9,"t":"在這一切當中，有誰不知道這是耶和華的手做成的呢？","notes":[]},{"n":10,"t":"凡動物的生命和人類的氣息都在他手中。","notes":[]},{"n":11,"t":"耳朵豈不辨別言語，正如上膛品嘗食物嗎？","notes":[]},{"n":12,"t":"年老的有智慧，壽高的有知識。","notes":[]},{"n":13,"t":"「在神有智慧和能力，他有謀略和知識。","notes":[]},{"n":14,"t":"看哪，他拆毀，就不能重建；他拘禁人，人就不得釋放。","notes":[]},{"n":15,"t":"看哪，他使水止住，水就乾了；他把水放出，水就淹沒大地。","notes":[]},{"n":16,"t":"在他有能力和智慧，走迷的和使人迷路的都屬他。","notes":[]},{"n":17,"t":"他把謀士剝衣擄去，使審判官變為愚妄。","notes":[]},{"n":18,"t":"他解除君王的權勢，用帶子捆住他們的腰。","notes":["「他解除君王的權勢」：原文另譯「他放鬆君王的捆綁」；「權勢」與「捆綁」的希伯來話發音相近。"]},{"n":19,"t":"他把祭司剝衣擄去，使有權能的人傾覆。","notes":[]},{"n":20,"t":"他廢去忠信者的言論，奪去長者的見識。","notes":[]},{"n":21,"t":"他使貴族蒙羞受辱，放鬆勇士的腰帶。","notes":[]},{"n":22,"t":"他從黑暗中彰顯深奧的事，使死蔭顯出光明。","notes":[]},{"n":23,"t":"他使邦國興旺而又毀滅，使邦國擴展又被掠奪。","notes":[]},{"n":24,"t":"他將地上百姓中領袖的聰明奪去，使他們迷失在荒涼無路之地。","notes":[]},{"n":25,"t":"他們在無光的黑暗中摸索；他使他們搖晃像醉酒的人一樣。」","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"「看哪，這一切，我眼都見過；我耳都聽過，而且明白。","notes":[]},{"n":2,"t":"你們所知道的，我也知道，並非不及你們。","notes":[]},{"n":3,"t":"然而我要對全能者說話，我願與神理論。","notes":[]},{"n":4,"t":"但你們是編造謊言的，全都是無用的醫生。","notes":[]},{"n":5,"t":"惟願你們全然不作聲，這就是你們的智慧！","notes":[]},{"n":6,"t":"請你們聽我的答辯，留心聽我嘴唇的訴求。","notes":[]},{"n":7,"t":"你們要為神說不義的話嗎？要為他說詭詐的言語嗎？","notes":[]},{"n":8,"t":"你們要看神的情面嗎？要為他爭辯嗎？","notes":[]},{"n":9,"t":"他查究你們，這豈是好事嗎？人欺騙人，你們也要照樣欺騙他嗎？","notes":[]},{"n":10,"t":"你們若暗中看人的情面，他必定要責備你們。","notes":[]},{"n":11,"t":"他的尊榮豈不叫你們懼怕嗎？他豈不使驚嚇臨到你們嗎？","notes":[]},{"n":12,"t":"你們可記念的諺語是灰燼的箴言；你們的後盾是泥土的後盾。","notes":[]},{"n":13,"t":"「你們不要向我作聲，讓我說話，無論如何我都承當。","notes":[]},{"n":14,"t":"我為何把我的肉掛在我的牙上，將我的命放在我的手掌中呢？","notes":[]},{"n":15,"t":"看哪，他要殺我，我毫無指望，然而我還要在他面前辯明我所行的。","notes":["「我毫無指望」：原文另譯「我仍要仰望他」。"]},{"n":16,"t":"這要成為我的拯救，因為不虔誠的人不可到他面前。","notes":[]},{"n":17,"t":"你們要細聽我的言語，讓我的申辯入你們耳中。","notes":[]},{"n":18,"t":"看哪，我已陳明我的案，知道自己有義。","notes":[]},{"n":19,"t":"還有誰要和我爭辯，我現在就緘默不言，氣絕而死。","notes":[]},{"n":20,"t":"惟有兩件事不要向我施行，我就不躲開你的面：","notes":[]},{"n":21,"t":"就是把你的手縮回，遠離我身；又不使你的威嚴恐嚇我。","notes":[]},{"n":22,"t":"這樣，你呼叫，我就回答；或是讓我說話，你回答我。","notes":[]},{"n":23,"t":"我的罪孽和我的罪有多少呢？求你叫我知道我的過犯與我的罪。","notes":[]},{"n":24,"t":"你為何轉臉，拿我當仇敵呢？","notes":[]},{"n":25,"t":"你要驚動被風吹的葉子嗎？要追趕枯乾的碎稭嗎？","notes":[]},{"n":26,"t":"你寫下苦楚對付我，又使我擔當幼年的罪孽。","notes":[]},{"n":27,"t":"你把我的腳鎖上木枷，察看我一切的道路，為我的腳掌劃定界限。","notes":[]},{"n":28,"t":"人像滅絕的爛物，像蟲蛀的衣裳。」","notes":[]}]},"14":{"heading":"","verses":[{"n":1,"t":"「人為婦人所生，日子短少，多有患難。","notes":[]},{"n":2,"t":"他出來如花，凋謝而去；他飛逝如影，不能存留。","notes":[]},{"n":3,"t":"這樣的人你豈會睜眼看他，又叫我來，在你那裏受審嗎？","notes":["「我」：七十士譯本和其他古譯本是「他」。"]},{"n":4,"t":"誰能使潔淨出於污穢呢？誰也不能！","notes":[]},{"n":5,"t":"既然人的日子限定，他的月數在於你，你劃定他的界限，他不能越過；","notes":[]},{"n":6,"t":"求你轉眼不看他，使他得歇息，直到他像雇工享受他的一天。","notes":[]},{"n":7,"t":"「因樹有指望，若被砍下，還可發芽，嫩枝生長不息。","notes":[]},{"n":8,"t":"樹根若衰老在地裏，樹幹也死在土中，","notes":[]},{"n":9,"t":"及至得了水氣，還會發芽，長出枝條，像新栽的樹一樣。","notes":[]},{"n":10,"t":"但壯士一死就消逝了；人一氣絕，他在何處呢？","notes":[]},{"n":11,"t":"海中的水枯竭，江河消散乾涸。","notes":[]},{"n":12,"t":"人一躺下就不再起來，等到諸天沒有了，仍不復醒，也不能從睡中喚醒。","notes":["「沒有了」：有古譯本是「廢去了」。"]},{"n":13,"t":"惟願你把我藏在陰間，把我隱藏，直到你的憤怒過去；願你為我定下期限，並記得我。","notes":[]},{"n":14,"t":"壯士若死了能再活嗎？我在一切服役的日子中等待，直到我退伍的時候來到。","notes":[]},{"n":15,"t":"你呼叫，我就回答你；你手所做的，你必期待。","notes":[]},{"n":16,"t":"但如今你數點我的腳步，不察看我的罪。","notes":[]},{"n":17,"t":"我的過犯被你密封在囊中，你遮掩了我的罪孽。","notes":[]},{"n":18,"t":"「然而，山崩變為無有，磐石從原處挪移。","notes":[]},{"n":19,"t":"流水沖蝕石頭，急流洗去地上的塵土；你也照樣滅絕人的指望。","notes":[]},{"n":20,"t":"你終必勝過人，使他消逝；你改變他的容貌，把他送走。","notes":[]},{"n":21,"t":"他的兒子得尊榮，他不知道；他們降為卑，他也不曉得。","notes":[]},{"n":22,"t":"他只覺得身上疼痛，心中為自己悲哀。」","notes":[]}]},"15":{"heading":"第二次對話","verses":[{"n":1,"t":"提幔人以利法回答說：","notes":[]},{"n":2,"t":"「智慧人豈可用虛空的知識回答，用東風充滿自己的肚腹呢？","notes":[]},{"n":3,"t":"他豈可用無益的話，用無濟於事的言語理論呢？","notes":[]},{"n":4,"t":"你誠然廢棄敬畏，不在神面前默想。","notes":[]},{"n":5,"t":"你的罪孽指教你的口；你選用詭詐人的舌頭。","notes":[]},{"n":6,"t":"你自己的口定你有罪，並非是我；你自己的嘴唇見證你的不是。","notes":[]},{"n":7,"t":"「你是頭一個生下來的人嗎？你受造在諸山之先嗎？","notes":[]},{"n":8,"t":"你曾聽見神的密旨嗎？你要獨自得盡智慧嗎？","notes":[]},{"n":9,"t":"甚麼是你知道，我們不知道的呢？甚麼是你明白，我們不明白的呢？","notes":[]},{"n":10,"t":"我們這裏有白髮的和年老的，比你父親還年長。","notes":[]},{"n":11,"t":"神的安慰和對你溫和的話，你以為太小嗎？","notes":[]},{"n":12,"t":"你的心為何失控，你的眼為何冒火，","notes":[]},{"n":13,"t":"以致你的靈反對神，你的口說出這樣的言語呢？","notes":[]},{"n":14,"t":"人是甚麼，竟算為潔淨呢？婦人所生的是甚麼，竟算為義呢？","notes":[]},{"n":15,"t":"看哪，神不信任他的眾聖者；在他眼前，天也不潔淨，","notes":[]},{"n":16,"t":"何況那污穢可憎，喝罪孽如水的世人呢！","notes":[]},{"n":17,"t":"「我指示你，你要聽我；我要陳述我所看見的，","notes":[]},{"n":18,"t":"就是智慧人從列祖所受，傳講而不隱瞞的事。","notes":[]},{"n":19,"t":"這地惟獨賜給他們，並沒有外人從他們中間經過。","notes":[]},{"n":20,"t":"惡人一生的日子絞痛難熬，殘暴人存留的年數也是如此。","notes":[]},{"n":21,"t":"驚嚇的聲音常在他耳中；在平安時，毀滅者必臨到他。","notes":[]},{"n":22,"t":"他不信自己能從黑暗中轉回；他被刀劍看守。","notes":[]},{"n":23,"t":"他飄流在外求食：『哪裏有食物呢？』他知道黑暗的日子在他手邊預備好了。","notes":["「他飄流...有食物呢？」有古譯本是「他被命定作禿鷹的食物。」","本節七十士譯本是「他被派定作禿鷹的食物，知道自己會成為屍體，黑暗的日子要像風把他吹走。」"]},{"n":24,"t":"急難困苦叫他害怕，而且勝過他，好像君王預備上陣。","notes":[]},{"n":25,"t":"因他伸手攻擊神，逞強對抗全能者，","notes":[]},{"n":26,"t":"挺著頸項，用盾牌堅厚的凸面向全能者直闖；","notes":[]},{"n":27,"t":"又因他的臉蒙上油脂，腰上積滿肥肉。","notes":[]},{"n":28,"t":"他住在荒涼的城鎮，房屋無人居住，成為廢墟。","notes":[]},{"n":29,"t":"他不得富足，財物不得常存，產業在地上也不加增。","notes":[]},{"n":30,"t":"他不得脫離黑暗，火焰要把他的嫩枝燒乾；因神口中的氣，他要離去。","notes":[]},{"n":31,"t":"不要讓他倚靠虛假，欺騙自己，因虛假必成為他的報應。","notes":[]},{"n":32,"t":"他的日期未到之先，這事必實現；他的枝子不得青綠。","notes":[]},{"n":33,"t":"他必像葡萄樹，葡萄未熟就掉落；又像橄欖樹，一開花就凋謝。","notes":[]},{"n":34,"t":"因不敬虔之輩必不能生育，受賄賂之人的帳棚必被火吞滅。","notes":[]},{"n":35,"t":"他們所懷的是毒害，所生的是罪孽，肚腹裏所預備的是詭詐。」","notes":[]}]},"16":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"「這樣的話我聽了許多；你們全都是使人愁煩的安慰者。","notes":[]},{"n":3,"t":"如風的言語有窮盡嗎？或者甚麼惹動你回答呢？","notes":[]},{"n":4,"t":"我也能說你們那樣的話，你們若處在我的景況，我也可以堆砌言詞攻擊你們，又可以向你們搖頭。","notes":[]},{"n":5,"t":"但我必用口堅固你們，顫動的嘴唇帶來舒解。","notes":[]},{"n":6,"t":"「我若說話，痛苦仍不得緩解；我若停止，痛苦就離開我嗎？","notes":[]},{"n":7,"t":"但現在神使我困倦，你使所有的親友遠離我，","notes":[]},{"n":8,"t":"你抓住我，成為見證起來攻擊我；我的枯瘦也當著我的面作證。","notes":["「你抓住我」或譯「你使我佈滿皺紋」。"]},{"n":9,"t":"神發怒撕裂我，逼迫我，向我咬牙切齒；我的敵人怒目瞪我。","notes":[]},{"n":10,"t":"他們向我大大張口，打我的耳光羞辱我，聚在一起攻擊我。","notes":[]},{"n":11,"t":"神把我交給不敬虔的人，把我扔到惡人的手中。","notes":[]},{"n":12,"t":"我本是安逸，他折斷我，掐住我的頸項，把我摔碎，又立我作他的箭靶。","notes":[]},{"n":13,"t":"他的弓箭手圍繞我。他刺破我的腎臟，並不留情，把我的膽汁傾倒在地上。","notes":[]},{"n":14,"t":"他使我破裂，破裂又破裂，如同勇士向我直闖。","notes":[]},{"n":15,"t":"「我把麻布縫在我的皮膚上，把我的角放在塵土中。","notes":[]},{"n":16,"t":"我的臉因哭泣變紅，我的眼皮上有死蔭。","notes":[]},{"n":17,"t":"我的手中卻沒有暴力，我的祈禱也是純潔的。","notes":[]},{"n":18,"t":"「地啊，不要遮蓋我的血！不要讓我的哀求有藏匿之處！","notes":[]},{"n":19,"t":"現今，看哪，在天有我的見證，在上有我的保人。","notes":[]},{"n":20,"t":"我的朋友譏誚我，我卻向神眼淚汪汪。","notes":[]},{"n":21,"t":"願人可與神理論，如同人與朋友一樣；","notes":[]},{"n":22,"t":"因為再過幾年，我必走那往而不返之路。」","notes":[]}]},"17":{"heading":"","verses":[{"n":1,"t":"「我的靈耗盡，我的日子消逝；墳墓為我預備好了。","notes":[]},{"n":2,"t":"戲笑的人果真陪伴著我，我的眼睛盯住他們的悖逆。","notes":[]},{"n":3,"t":"「願你親自為我付押擔保。誰還會與我擊掌呢？","notes":[]},{"n":4,"t":"因你蒙蔽他們的心，使不明理，所以你必不高舉他們。","notes":[]},{"n":5,"t":"控告朋友為了分享產業的，他兒女的眼睛要失明。","notes":["「控告」或譯「出賣」或「邀請」。"]},{"n":6,"t":"「神使我成為人群中的笑談，他們吐唾沫在我臉上。","notes":[]},{"n":7,"t":"我的眼睛因憂愁昏花，我的肢體全像影兒。","notes":[]},{"n":8,"t":"正直人因此必驚奇；無辜的人要興起攻擊不敬虔之輩。","notes":[]},{"n":9,"t":"然而，義人要持守所行的道，手潔的人要力上加力。","notes":[]},{"n":10,"t":"至於你們眾人，再回來吧！你們中間，我找不到一個智慧人。","notes":[]},{"n":11,"t":"我的日子已經過去了，我的謀算、我心的願望已經斷絕了。","notes":[]},{"n":12,"t":"他們以黑夜為白晝，即使面臨黑暗，以為亮光已近。","notes":[]},{"n":13,"t":"我若盼望陰間為我的家，若下榻在黑暗中，","notes":[]},{"n":14,"t":"若對地府呼叫：『你是我的父親』，若對蟲呼叫：『你是我的母親、姊妹』，","notes":[]},{"n":15,"t":"這樣，我的盼望在哪裏呢？我所盼望的，誰能看見呢？","notes":[]},{"n":16,"t":"這盼望要下到陰間的門閂嗎？要一起在塵土中安息嗎？」","notes":["「這盼望...門閂嗎」：七十士譯本是「這盼望要與我一起下到陰間嗎」。","「要一起...安息嗎」：七十士譯本和其他古譯本是「我們要一起下入塵土中嗎」。"]}]},"18":{"heading":"","verses":[{"n":1,"t":"書亞人比勒達回答說：","notes":[]},{"n":2,"t":"「你們尋索言語要到幾時呢？你們要明白，然後我們才說話。","notes":["「你們...幾時呢」：原文直譯「你們為言語設陷阱要到幾時呢」；七十士譯本和其他古譯本是「你要說到幾時才停止呢」。"]},{"n":3,"t":"我們為何被視為畜牲，在你們眼中看為愚笨呢？","notes":["「愚笨」或譯「不潔淨」。"]},{"n":4,"t":"在怒氣中將自己撕裂的人哪，難道大地要因你見棄、磐石要挪開原處嗎？","notes":[]},{"n":5,"t":"「惡人的亮光必要熄滅，他的火焰必不照耀。","notes":[]},{"n":6,"t":"他帳棚中的亮光要變黑暗，他上面的燈也必熄滅。","notes":[]},{"n":7,"t":"他強橫的腳步必遭阻礙，他的計謀必將自己絆倒。","notes":[]},{"n":8,"t":"他因自己的腳陷入網中，走在纏人的網子上。","notes":[]},{"n":9,"t":"羅網必抓住他的腳跟，陷阱必擒獲他。","notes":[]},{"n":10,"t":"繩索為他藏在土裏，羈絆為他藏在路上。","notes":[]},{"n":11,"t":"四面的驚嚇使他害怕，在他腳跟後面追趕他。","notes":[]},{"n":12,"t":"他的力量必因飢餓衰敗，禍患要在他的旁邊等候，","notes":[]},{"n":13,"t":"侵蝕他肢體的皮膚；死亡的長子吞吃他的肢體。","notes":[]},{"n":14,"t":"他要從所倚靠的帳棚被拔出來，帶到使人驚恐的王那裏。","notes":[]},{"n":15,"t":"不屬他的必住在他的帳棚裏，硫磺必撒在他所住之處。","notes":[]},{"n":16,"t":"下邊，他的根要枯乾；上邊，他的枝子要剪除。","notes":[]},{"n":17,"t":"他的稱號從地上消失，他的名字不在街上存留。","notes":["「稱號」：原文是「紀念」。"]},{"n":18,"t":"他必從光明中被驅逐到黑暗裏，他必被趕出世界。","notes":[]},{"n":19,"t":"他在自己百姓中必無子無孫，在寄居之地也沒有倖存者。","notes":[]},{"n":20,"t":"以後的人要因他的日子驚訝，以前的人也被驚駭抓住。","notes":["「以後的人」或譯「西方人」。","「以前的人」或譯「東方人」。"]},{"n":21,"t":"不義之人的住處總是這樣，這就是不認識神之人的下場。」","notes":[]}]},"19":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"「你們攪擾我的心，用言語壓碎我要到幾時呢？","notes":[]},{"n":3,"t":"你們這十次羞辱我，苦待我也不以為恥。","notes":[]},{"n":4,"t":"果真我有錯，這錯是在於我。","notes":[]},{"n":5,"t":"若你們真要向我誇大，以我的羞辱來責備我，","notes":[]},{"n":6,"t":"就該知道是神傾覆我，用羅網圍繞我。","notes":[]},{"n":7,"t":"看哪，我喊冤叫屈，卻不蒙應允；我呼求，卻沒有公正。","notes":[]},{"n":8,"t":"神攔住我的道路，使我不得經過；他使黑暗籠罩我的路徑。","notes":[]},{"n":9,"t":"他剝去我的榮光，摘去我頭上的冠冕。","notes":[]},{"n":10,"t":"他在四圍攻擊我，我就走了；他將我的指望如樹拔出。","notes":[]},{"n":11,"t":"他向我發烈怒，以我為他的敵人。","notes":[]},{"n":12,"t":"他的軍隊一齊上來，修築道路攻擊我，在我帳棚的四圍安營。","notes":[]},{"n":13,"t":"「他把我的兄弟隔在遠處，使我認識的人全然與我生疏。","notes":[]},{"n":14,"t":"我的親戚都離開了我；我的密友都忘記了我。","notes":[]},{"n":15,"t":"在我家寄居的和我的使女，都當我是陌生人；我在他們眼中被視為外邦人。","notes":[]},{"n":16,"t":"我呼喚僕人，他卻不回答；我必須親口求他。","notes":[]},{"n":17,"t":"我口的氣味令我妻子厭惡，我的同胞都憎惡我。","notes":[]},{"n":18,"t":"連小男孩也藐視我；我起來，他們都嘲笑我。","notes":[]},{"n":19,"t":"我的知心朋友都憎惡我；我平日所愛的人向我翻臉。","notes":[]},{"n":20,"t":"我的皮和肉緊貼骨頭，我得以逃脫，僅剩牙齒。","notes":["「牙齒」：原文是「牙的皮」。","本節七十士譯本是「我的肉在皮下腐爛，我的骨頭伸出好像牙齒」。"]},{"n":21,"t":"我的朋友啊，可憐我！可憐我！因為神的手攻擊我。","notes":[]},{"n":22,"t":"你們為甚麼彷彿神逼迫我，吃我的肉還不滿足呢？","notes":[]},{"n":23,"t":"「惟願我的言語現在就寫上，都記錄在書上；","notes":[]},{"n":24,"t":"用鐵筆和鉛，刻在磐石上，存到永遠。","notes":[]},{"n":25,"t":"我知道我的救贖主活著，末後他必站在塵土上。","notes":["「救贖主」或譯「伸冤者」。"]},{"n":26,"t":"我這皮肉滅絕之後，我必在肉體之外得見神。","notes":["「我這皮肉滅絕之後」：原文另譯「我醒來之後，他會使我跟他一起站起來」。","「在肉體之外」或譯「在肉體之中」或「從肉體」。"]},{"n":27,"t":"我自己要見他，親眼要看他，並不像陌生人。我的心腸在我裏面耗盡了！","notes":[]},{"n":28,"t":"你們若說：『我們怎麼逼迫他呢？事情的根源是在於他』，","notes":["「他」是根據一些古卷、七十士譯本和其他古譯本；原文是「我」。"]},{"n":29,"t":"你們就當懼怕刀劍，因為憤怒帶來刀劍的刑罰。這樣，你們就知道有審判。」","notes":[]}]},"20":{"heading":"","verses":[{"n":1,"t":"拿瑪人瑣法回答說：","notes":[]},{"n":2,"t":"「這樣，我的思念叫我回答，因為我心中急躁。","notes":[]},{"n":3,"t":"我聽見那羞辱我的責備；我悟性的靈回答我。","notes":[]},{"n":4,"t":"你豈不知道嗎？亙古以來，自從人被安置在地，","notes":[]},{"n":5,"t":"惡人歡樂的聲音是暫時的，不敬虔人的喜樂不過是轉眼之間。","notes":[]},{"n":6,"t":"他的尊榮雖達到天上，頭雖頂到雲中，","notes":[]},{"n":7,"t":"他必永遠滅亡，像自己的糞一樣。看見他的人要說：『他在哪裏呢？』","notes":[]},{"n":8,"t":"他必如夢飛去，不再尋見；他被趕走，如夜間的異象。","notes":[]},{"n":9,"t":"親眼見過他的，必不再見他；他自己的地方也不再見到他。","notes":[]},{"n":10,"t":"他的兒女要向窮人求恩；他的手要賠還錢財。","notes":[]},{"n":11,"t":"他的骨頭雖然滿有年輕的活力，卻要和他一同躺臥在塵土之中。","notes":[]},{"n":12,"t":"「他口中以惡為甘甜，把惡藏在舌頭底下，","notes":[]},{"n":13,"t":"愛戀不捨，含在口中。","notes":[]},{"n":14,"t":"他的食物在肚裏卻要翻轉，在他裏面成為虺蛇的毒液。","notes":[]},{"n":15,"t":"他吞了財寶，還要吐出；神要從他腹中掏出來。","notes":[]},{"n":16,"t":"他必吸飲虺蛇的毒汁，毒蛇的舌頭必殺他。","notes":[]},{"n":17,"t":"他不再看見溪流，流奶與蜜之河。","notes":[]},{"n":18,"t":"他勞碌得來的要賠還，不得吞下；賺取了財貨，也不得歡樂。","notes":[]},{"n":19,"t":"他欺壓窮人，棄之不顧，強取非自己所蓋的房屋。","notes":["「強取...房屋」或譯「強取房屋不得再建造」。"]},{"n":20,"t":"「他的肚腹不知安逸，所貪戀的連一樣也不放過，","notes":[]},{"n":21,"t":"剩餘的沒有一樣他不吞吃，所以他的福樂不能長久。","notes":[]},{"n":22,"t":"他在滿足有餘的時候，必有困苦臨到；凡受苦楚之人的手必加在他身上。","notes":[]},{"n":23,"t":"他的肚腹正要滿足的時候，神必將猛烈的憤怒降在他身上；他正在吃飯的時候，神要將這憤怒如雨降在他身上。","notes":[]},{"n":24,"t":"他要躲避鐵的武器，銅弓要將他射透。","notes":[]},{"n":25,"t":"箭一抽，就從他背上出來，發亮的箭頭從他膽中出來；有驚惶臨到他身上。","notes":[]},{"n":26,"t":"他的財寶隱藏在深沉的黑暗裏；有非人吹起的火要把他吞滅，把他帳棚中所剩下的燒燬。","notes":[]},{"n":27,"t":"天要顯明他的罪孽，地要興起去攻擊他。","notes":[]},{"n":28,"t":"他家裏出產的必消失，在神憤怒的日子被沖走。","notes":[]},{"n":29,"t":"這是惡人從神所得的份，是神為他所定的產業。」","notes":[]}]},"21":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"「你們要細心聽我的言語，這就算是你們的安慰。","notes":[]},{"n":3,"t":"請寬容我，我又要說話；說了以後，任憑你嗤笑吧！","notes":[]},{"n":4,"t":"我豈是向人訴苦？我為何不是沒有耐心呢？","notes":[]},{"n":5,"t":"你們要轉向我而驚奇，要用手摀口。","notes":[]},{"n":6,"t":"我每逢思想，心就驚惶，戰兢抓住我身。","notes":[]},{"n":7,"t":"惡人為何存活，得享高壽，勢力強盛呢？","notes":[]},{"n":8,"t":"他們的後裔與他們一起，堅立在他們面前，他們得以眼見自己的子孫。","notes":["「與他們一起」：原文另譯「他們的百姓」。"]},{"n":9,"t":"他們的家宅平安無懼，神的杖不加在他們身上。","notes":[]},{"n":10,"t":"他們的公牛傳種而不斷絕，母牛生牛犢而不掉胎。","notes":[]},{"n":11,"t":"他們打發小男孩出去，多如羊群，他們的孩子踴躍跳舞。","notes":[]},{"n":12,"t":"他們隨著琴鼓歌唱，因簫聲歡喜。","notes":[]},{"n":13,"t":"他們度日諸事亨通，在平安中下到陰間。","notes":[]},{"n":14,"t":"他們對神說：『離開我們吧！我們不想知道你的道路。","notes":[]},{"n":15,"t":"全能者是誰，我們何必事奉他呢？求告他有甚麼益處呢？』","notes":[]},{"n":16,"t":"看哪，他們亨通不是靠自己的手；惡人的計謀離我好遠。","notes":[]},{"n":17,"t":"「惡人的燈何嘗熄滅？患難何嘗臨到他們呢？神何嘗發怒，把災禍分給他們呢？","notes":[]},{"n":18,"t":"他們何嘗像風前的碎稭，如暴風颳去的糠秕呢？","notes":[]},{"n":19,"t":"神為惡人的兒女積蓄罪孽，不如本人遭報，好使他親自知道。","notes":[]},{"n":20,"t":"願他親眼看見自己敗亡，親自飲全能者的憤怒。","notes":[]},{"n":21,"t":"他的歲月既盡，他身後還顧他的家嗎？","notes":[]},{"n":22,"t":"誰能將知識教導神呢？是他審判那些居高位的。","notes":[]},{"n":23,"t":"有人至死身體強壯，盡得平順安逸；","notes":[]},{"n":24,"t":"他的肚腹充滿奶汁，他的骨髓滋潤。","notes":["「他的肚腹充滿奶汁」或譯「他的桶子裏滿了奶」。"]},{"n":25,"t":"有人至死心中痛苦，從未嘗過福樂的滋味；","notes":[]},{"n":26,"t":"他們同樣躺臥於塵土，蟲子覆蓋他們。","notes":[]},{"n":27,"t":"「看哪，我知道你們的意念，並殘害我的計謀。","notes":[]},{"n":28,"t":"你們說：『權貴的房屋在哪裏？惡人住過的帳棚在哪裏？』","notes":[]},{"n":29,"t":"你們沒有詢問那些過路的人嗎？你們不承認他們的證據嗎？","notes":[]},{"n":30,"t":"就是惡人在患難的日子得存留，在憤怒的日子得逃脫。","notes":[]},{"n":31,"t":"他所行的，有誰當面給他說明？他所做的，有誰報應他呢？","notes":[]},{"n":32,"t":"然而他要被抬到墳地，並有人看守墓穴。","notes":[]},{"n":33,"t":"他要以谷中的土塊為甘甜；人人要跟在他後面，在他前面去的無數。","notes":[]},{"n":34,"t":"你們怎能以空話安慰我呢？你們的對答全都錯謬！」","notes":[]}]},"22":{"heading":"第三次對話","verses":[{"n":1,"t":"提幔人以利法回答說：","notes":[]},{"n":2,"t":"「人能使神有益嗎？智慧人能使他有益嗎？","notes":["「智慧人...有益嗎？」或譯「智慧人但能有益於己。」"]},{"n":3,"t":"你為人公義，豈能叫全能者喜悅呢？你行為完全，豈能使他得利呢？","notes":[]},{"n":4,"t":"他豈是因你敬畏的心就責備你，審判你嗎？","notes":[]},{"n":5,"t":"你的罪惡豈不是大嗎？你的罪孽不是沒有窮盡嗎？","notes":[]},{"n":6,"t":"因你無故強取弟兄的抵押，剝去赤身者的衣服。","notes":[]},{"n":7,"t":"疲乏的人，你沒有給他水喝；飢餓的人，你沒有給他食物。","notes":[]},{"n":8,"t":"有能力的人得土地；尊貴的人住在其中。","notes":[]},{"n":9,"t":"你打發寡婦空手回去，你折斷孤兒的膀臂。","notes":[]},{"n":10,"t":"因此，有羅網環繞你，有恐懼忽然使你驚惶；","notes":[]},{"n":11,"t":"或有黑暗使你看不見，有洪水淹沒你。","notes":["「或有...看不見」：七十士譯本是「你的光變成黑暗」。"]},{"n":12,"t":"「神豈不是在高天嗎？你看星宿的頂點何其高呢！","notes":[]},{"n":13,"t":"你說：『神知道甚麼？他豈能透過幽暗施行審判呢？","notes":[]},{"n":14,"t":"密雲將他遮蓋，使他不能看見；他周遊穹蒼。』","notes":[]},{"n":15,"t":"你要依從上古的道嗎？這道是惡人行過的。","notes":[]},{"n":16,"t":"他們未到時候就被抓去；他們的根基被江河沖去。","notes":["「就被抓去」或譯「佈滿皺紋」。"]},{"n":17,"t":"他們向神說：『離開我們吧！』全能者能把他們怎麼樣呢？","notes":[]},{"n":18,"t":"然而，是神以美物充滿他們的房屋；惡人的計謀離我好遠！","notes":[]},{"n":19,"t":"義人看見他們的結局就歡喜；無辜的人嗤笑他們：","notes":["原文沒有「他們的結局」。"]},{"n":20,"t":"『攻擊我們的果然被剪除，剩餘的都被火吞滅。』","notes":[]},{"n":21,"t":"「你要與神和好，要和平，這樣，福氣必臨到你。","notes":[]},{"n":22,"t":"你當領受他口中的教導，將他的言語存在心裏。","notes":[]},{"n":23,"t":"你若歸向全能者，就必得建立。你要從你帳棚中遠離不義，","notes":[]},{"n":24,"t":"你要將黃金丟到塵土裏，將俄斐的金子丟在溪河石頭之間；","notes":[]},{"n":25,"t":"全能者就必作你的黃金，作你成堆的銀子。","notes":[]},{"n":26,"t":"那時，你要以全能者為喜樂，向神仰臉。","notes":[]},{"n":27,"t":"你要向他禱告，他就聽你；你也要還你的願。","notes":[]},{"n":28,"t":"你定意要做何事，必然為你成就；亮光也必照耀你的路。","notes":[]},{"n":29,"t":"當人降卑，你說：是因驕傲；眼目謙卑的人，神必然拯救。","notes":[]},{"n":30,"t":"不是無辜的人，神尚且要搭救他；他必因你手中的清潔得蒙拯救。」","notes":["「不是無辜的人...搭救他」：七十士譯本是「神搭救無辜的人」。"]}]},"23":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"「如今我的哀告還算為悖逆；我雖唉哼，他的手仍然重重責罰我。","notes":["「他的手...責罰我」是根據七十士譯本和其他古譯本；原文是「我的手是重的」。"]},{"n":3,"t":"惟願我知道哪裏可以尋見神，能到他的臺前，","notes":[]},{"n":4,"t":"我就在他面前陳明我的案件，滿口辯訴。","notes":[]},{"n":5,"t":"我必知道他回答我的言語，明白他向我所要說的。","notes":[]},{"n":6,"t":"他豈用大能與我爭辯呢？不！他必理會我。","notes":[]},{"n":7,"t":"在那裏正直人可以與他辯論，我就必永遠脫離那審判我的。","notes":[]},{"n":8,"t":"「看哪，我往前走，他不在那裏；往後退，也沒有察覺他。","notes":[]},{"n":9,"t":"他在左邊行事，我卻看不見他；他轉向右邊，我也見不到他。","notes":["「他轉向右邊」或譯「他在右邊隱藏」。"]},{"n":10,"t":"然而他知道我所走的路；他試煉我，我就如純金。","notes":[]},{"n":11,"t":"我的腳緊跟他的步伐；我謹守他的道，並不偏離。","notes":[]},{"n":12,"t":"他嘴唇的命令，我未曾背棄；我看重他口中的言語，過於我需用的飲食。","notes":["「我需用的飲食」或譯「我的原則」。","「我看重...飲食。」七十士譯本是「我把他的言語珍藏在我胸懷。」"]},{"n":13,"t":"只是他心志已定，誰能使他轉意呢？他心裏所願的，就行出來。","notes":[]},{"n":14,"t":"因此，為我所定的，他必做成，這類的事他還有許多。","notes":[]},{"n":15,"t":"所以我在他面前驚惶；我思想就懼怕他。","notes":[]},{"n":16,"t":"神使我喪膽，全能者使我驚惶。","notes":[]},{"n":17,"t":"但我並非被黑暗剪除，只是幽暗遮蓋了我的臉。","notes":[]}]},"24":{"heading":"","verses":[{"n":1,"t":"「為何全能者不定下期限？為何認識他的人看不到那些日子呢？","notes":[]},{"n":2,"t":"有人挪移地界，搶奪群畜去放牧。","notes":[]},{"n":3,"t":"他們拉走孤兒的驢，強取寡婦的牛作抵押。","notes":[]},{"n":4,"t":"他們使貧窮人離開正道；世上的困苦人盡都隱藏。","notes":[]},{"n":5,"t":"看哪，他們如同野驢出到曠野，殷勤尋找食物，在野地給孩童餬口。","notes":[]},{"n":6,"t":"他們收割別人田間的莊稼，摘取惡人剩餘的葡萄。","notes":[]},{"n":7,"t":"他們終夜赤身無衣，在寒冷中毫無遮蓋。","notes":[]},{"n":8,"t":"他們在山上被大雨淋濕，因沒有避身之處就擁抱磐石。","notes":[]},{"n":9,"t":"又有人從母懷中搶走孤兒，在困苦人身上強取抵押品。","notes":["「在困苦人身上強取抵押品」：原文另譯「強取困苦人的嬰孩作抵押」。"]},{"n":10,"t":"困苦人赤身無衣，到處流浪，餓著肚子扛抬禾捆，","notes":[]},{"n":11,"t":"他們在圍牆內榨油，踹壓酒池，自己卻口渴。","notes":[]},{"n":12,"t":"在城內垂死的人呻吟，受傷的人哀號；神卻不理會狂妄的事。","notes":[]},{"n":13,"t":"「又有人背棄光明，不認識光明的道，不留在光明的路上。","notes":[]},{"n":14,"t":"殺人者黎明起來，殺害困苦人和貧窮人，夜間又作盜賊。","notes":[]},{"n":15,"t":"姦夫的眼等候黃昏，說：『沒有眼睛能見我』，就把臉蒙住。","notes":[]},{"n":16,"t":"盜賊黑夜挖洞；他們白日躲藏，並不認識光明。","notes":[]},{"n":17,"t":"他們全都看早晨如死蔭，因為他們熟悉死蔭的驚駭。","notes":[]},{"n":18,"t":"「惡人在水面上快速飄盪，他們在地上所得的產業被詛咒；無人再回到他們的葡萄園。","notes":[]},{"n":19,"t":"乾旱炎熱融化雪水；陰間也如此吞沒犯罪的人。","notes":[]},{"n":20,"t":"懷他的母胎忘記他；蟲子要吃他，覺得甘甜；他不再被人記念；不義的人必如樹折斷。","notes":[]},{"n":21,"t":"「他與不懷孕不生育的婦人交往，卻不善待寡婦。","notes":["「他與...交往」：七十士譯本和其他古譯本是「他惡待不懷孕的婦人」。"]},{"n":22,"t":"然而神用能力保全有勢力的人；那性命難保的人仍然興起。","notes":[]},{"n":23,"t":"神使他安穩，他就有所倚靠；神的眼目看顧他們的道路。","notes":[]},{"n":24,"t":"他們高升，不過片刻就沒有了；他們降為卑，被除滅，與眾人一樣，又如穀的穗子被割下。","notes":["「他們降為卑...一樣」或譯「他們像花一樣枯乾凋謝」。"]},{"n":25,"t":"若不是這樣，誰能指證我是說謊的，以我的言語為毫無根據呢？」","notes":[]}]},"25":{"heading":"","verses":[{"n":1,"t":"書亞人比勒達回答說：","notes":[]},{"n":2,"t":"「神有統治之權，威嚴可畏；他在高處施行和平。","notes":[]},{"n":3,"t":"他的軍隊豈能數算？他的光向誰不會升起呢？","notes":["「他的光...升起呢」：七十士譯本是「他向誰不會埋伏呢」。"]},{"n":4,"t":"這樣，在神面前人怎能稱義？婦人所生的怎能潔淨？","notes":[]},{"n":5,"t":"看哪，在神眼前，月亮無光，星宿也不皎潔，","notes":[]},{"n":6,"t":"更何況是如蟲的人，如蛆的世人呢！","notes":[]}]},"26":{"heading":"","verses":[{"n":1,"t":"約伯回答說：","notes":[]},{"n":2,"t":"「無能的人蒙你何等的幫助！膀臂無力的人蒙你何等的拯救！","notes":[]},{"n":3,"t":"無智慧的人蒙你何等的指教！你向他顯出豐富的知識。","notes":[]},{"n":4,"t":"你向誰發出言語？誰的靈從你而出？","notes":[]},{"n":5,"t":"在大水和水族以下，陰魂戰兢。","notes":[]},{"n":6,"t":"在神面前，陰間顯露；冥府也不得遮掩。","notes":["「冥府」：原文音譯「亞巴頓」，意思是「滅亡之地」。"]},{"n":7,"t":"神將北極鋪在空中，將大地懸在虛空。","notes":[]},{"n":8,"t":"他將水包在密雲中，盛水的雲卻不破裂。","notes":[]},{"n":9,"t":"他遮蔽寶座的正面，把他的雲彩鋪在其上。","notes":[]},{"n":10,"t":"他在水面上劃一圓圈，直到光明與黑暗的交界。","notes":[]},{"n":11,"t":"天的柱子震動，因他的斥責驚奇。","notes":[]},{"n":12,"t":"他以能力攪動大海，藉知識打傷拉哈伯。","notes":["「攪動」或譯「平靜」。"]},{"n":13,"t":"他藉自己的靈使天空晴朗；他的手刺殺爬得快的蛇。","notes":[]},{"n":14,"t":"看哪，這不過是神工作的些微；我們聽見他的話，是何等細微的聲音！他大能的雷聲誰能明白呢？」","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"約伯繼續發表他的言論說：","notes":[]},{"n":2,"t":"「我指著奪去我公道的永生神，並使我心中愁苦的全能者起誓：","notes":[]},{"n":3,"t":"只要我的生命尚在我裏面，神所賜的氣息仍在我鼻孔內，","notes":[]},{"n":4,"t":"我的唇絕不說不義，我的舌也不說詭詐。","notes":[]},{"n":5,"t":"我斷不以你們為義；我至死不放棄自己的純正！","notes":[]},{"n":6,"t":"我持定我的義，並不放鬆；在世的日子，我的心不責備我。","notes":[]},{"n":7,"t":"「願我的仇敵如惡人一樣；願那起來攻擊我的，如不義之人一般。","notes":[]},{"n":8,"t":"不敬虔的人有甚麼指望呢？神要剪除他，取他的性命。","notes":["本節或譯「不敬虔的人雖然得利，神奪取其命的時候還有甚麼指望呢？」"]},{"n":9,"t":"患難臨到他，神豈聽他的呼求？","notes":[]},{"n":10,"t":"他豈以全能者為樂，隨時求告神呢？","notes":[]},{"n":11,"t":"神手所做的，我要指教你們；全能者所行的，我也不會隱瞞。","notes":[]},{"n":12,"t":"看哪，你們自己也都見過，為何全變為這樣虛妄呢？","notes":[]},{"n":13,"t":"「這是神為惡人所定的份，殘暴人從全能者所得的產業：","notes":[]},{"n":14,"t":"倘若他的兒女增多，仍被刀所殺；他的子孫必不得飽食。","notes":[]},{"n":15,"t":"他遺留的人必死而埋葬，他的寡婦也不哀哭。","notes":[]},{"n":16,"t":"他雖積蓄銀子如塵沙，堆積衣服如泥土，","notes":[]},{"n":17,"t":"他儘管堆積，義人卻要穿上，無辜的人卻要分取銀子。","notes":[]},{"n":18,"t":"他建造房屋如蟲做窩，又如守望者所搭的棚。","notes":[]},{"n":19,"t":"他雖富足躺臥，卻不得收殮，他張開眼睛，就不在了。","notes":["「卻不得收殮」：七十士譯本和其他古譯本是「卻不會繼續這樣」。"]},{"n":20,"t":"驚恐如洪水將他追上，暴風在夜間將他颳去。","notes":[]},{"n":21,"t":"東風把他吹去，他就走了；風將他颳離原地。","notes":[]},{"n":22,"t":"風無情地擊打他，他試圖逃脫風的手。","notes":["「風」或譯「神」；下同。"]},{"n":23,"t":"風要因他拍掌，並要發叱聲，使他離開原地。」","notes":[]}]},"28":{"heading":"歌頌智慧","verses":[{"n":1,"t":"「銀子有礦；煉金有場。","notes":[]},{"n":2,"t":"鐵從土裏開採，銅從礦石鎔出。","notes":[]},{"n":3,"t":"人探索黑暗的盡頭，查究礦石直到極處，那是幽暗和死蔭；","notes":[]},{"n":4,"t":"他在無人居住之處開鑿礦穴，在無足跡之地被遺忘，與人遠離，懸空搖擺。","notes":["「在無足跡之地被遺忘」或譯「過路的人也想不到他們」。"]},{"n":5,"t":"地出產糧食，地底翻騰如火。","notes":[]},{"n":6,"t":"地的石頭是藍寶石之處，那裏還有金沙。","notes":[]},{"n":7,"t":"鷙鳥不知那條路，鷹眼也未曾見過。","notes":[]},{"n":8,"t":"狂傲的野獸未曾踩踏，猛烈的獅子也未曾經過。","notes":[]},{"n":9,"t":"「人動手鑿開堅石，翻倒山的根基，","notes":[]},{"n":10,"t":"在磐石中鑿出水道，親眼看見各樣寶物。","notes":[]},{"n":11,"t":"他封閉河川不得涓滴，使隱藏之物顯露出來。","notes":["「他封閉河川不得涓滴」：原文另譯「他封閉河川的水源」。"]},{"n":12,"t":"「然而，智慧何處可尋？聰明之地在哪裏？","notes":[]},{"n":13,"t":"智慧的價值無人能知，活人之地也無處可尋。","notes":["「智慧的價值」：七十士譯本是「智慧的道路」。"]},{"n":14,"t":"深淵說：『不在我裏面。』滄海說：『不在我這裏。』","notes":[]},{"n":15,"t":"智慧不可用黃金換取，也不能用白銀秤她的價值。","notes":[]},{"n":16,"t":"俄斐的金子和貴重的紅瑪瑙，以及藍寶石，不足與她比擬；","notes":[]},{"n":17,"t":"黃金和玻璃不足與她比較；純金的器皿不足兌換她。","notes":[]},{"n":18,"t":"珊瑚、水晶都不值得提；智慧的價值勝過寶石。","notes":["「寶石」或譯「珍珠」。"]},{"n":19,"t":"古實的紅璧璽不足與她比較；純金也不足與她比擬。","notes":[]},{"n":20,"t":"「智慧從何處來呢？聰明之地在哪裏？","notes":[]},{"n":21,"t":"她隱藏，遠離眾生的眼目，她掩蔽，遠離空中的飛鳥。","notes":[]},{"n":22,"t":"毀滅和死亡說：『我們風聞其名。』","notes":[]},{"n":23,"t":"「神明白智慧的道路，知道智慧的所在。","notes":[]},{"n":24,"t":"因為他鑒察直到地極，遍觀普天之下，","notes":[]},{"n":25,"t":"要為風定輕重，又度量諸水，","notes":[]},{"n":26,"t":"為雨定律例，為雷電定道路。","notes":[]},{"n":27,"t":"那時他看見智慧，就談論她，堅定她，並且查究她。","notes":[]},{"n":28,"t":"他對人說：『看哪，敬畏主就是智慧；遠離惡事就是聰明。』」","notes":[]}]},"29":{"heading":"約伯最後的申訴","verses":[{"n":1,"t":"約伯繼續發表他的言論說：","notes":[]},{"n":2,"t":"「惟願我如從前的歲月，如神保護我的日子。","notes":[]},{"n":3,"t":"那時他的燈照在我頭上，我藉他的光行過黑暗。","notes":[]},{"n":4,"t":"在我壯年的時候，神親密的情誼臨到我的帳棚中。","notes":[]},{"n":5,"t":"全能者仍與我同在，我的兒女都環繞我。","notes":[]},{"n":6,"t":"我的腳洗在乳酪當中；磐石為我流出油河。","notes":[]},{"n":7,"t":"我出到城門，在廣場安排座位，","notes":[]},{"n":8,"t":"年輕人見我而迴避，老年人起身站立。","notes":[]},{"n":9,"t":"王子都停止說話，用手摀口；","notes":[]},{"n":10,"t":"領袖靜默無聲，舌頭貼住上膛。","notes":[]},{"n":11,"t":"耳朵聽見了，稱我有福；眼睛看見了，就稱讚我。","notes":[]},{"n":12,"t":"因我拯救了哀求的困苦人和無人幫助的孤兒。","notes":[]},{"n":13,"t":"將要滅亡的為我祝福，我使寡婦心中歡呼。","notes":[]},{"n":14,"t":"我穿上公義，它遮蔽我；我的公平如外袍和冠冕。","notes":[]},{"n":15,"t":"我作瞎子的眼，瘸子的腳。","notes":[]},{"n":16,"t":"我作貧窮人的父；我不認識之人的案件，我也去查明。","notes":[]},{"n":17,"t":"我打破不義之人的大牙，從他牙齒中奪走他所搶的。","notes":[]},{"n":18,"t":"我說：『我要增添我的日子如塵沙，我必死在自己家中。","notes":["「自己家中」：原文是「自己的窩裏」。"]},{"n":19,"t":"我的根伸展到水邊，露水夜宿我的枝上。","notes":[]},{"n":20,"t":"我的榮耀在我身上更新，我的弓在我手中日新。』","notes":[]},{"n":21,"t":"「人聽我說話而等候，為我的教導而靜默。","notes":[]},{"n":22,"t":"我說話之後，他們就不再說；我的言語滴在他們身上。","notes":[]},{"n":23,"t":"他們等候我如等雨水，又張口如切慕春雨。","notes":[]},{"n":24,"t":"我向他們微笑，他們不敢相信；他們不使我臉上的光失色。","notes":[]},{"n":25,"t":"我為他們選擇道路，又坐首位；我如君王在軍隊中居住，又如人安慰哀傷的人。」","notes":[]}]},"30":{"heading":"","verses":[{"n":1,"t":"「但如今，比我年輕的人譏笑我；我曾藐視他們的父親，不放在我的牧羊犬中。","notes":[]},{"n":2,"t":"他們的精力既已衰敗，手中的氣力於我何益？","notes":[]},{"n":3,"t":"他們因窮乏飢餓，沒有生氣，在荒廢淒涼的幽暗中啃乾燥之地。","notes":[]},{"n":4,"t":"他們在草叢之中採鹹草，羅騰樹的根成為他們的食物。","notes":["「羅騰」是音譯，小樹名，松類。"]},{"n":5,"t":"他們從人群中被趕出，人追喊他們如賊一般，","notes":[]},{"n":6,"t":"以致他們住在荒谷，住在地洞和巖穴中。","notes":[]},{"n":7,"t":"他們在草叢中叫喚，在荊棘下擠成一團。","notes":[]},{"n":8,"t":"這都是愚頑卑微人的兒女；他們被鞭打，趕出境外。","notes":[]},{"n":9,"t":"「現在這些人以我為歌曲，以我為笑談。","notes":[]},{"n":10,"t":"他們厭惡我，躲避我，不住地吐唾沫在我臉上。","notes":[]},{"n":11,"t":"神鬆開我的弓弦使我受苦，他們就在我面前脫去轡頭。","notes":["「我的弓弦」：原文另譯「他的弓弦」。"]},{"n":12,"t":"這夥人在我右邊起來，他們推開我的腳，築災難之路攻擊我。","notes":[]},{"n":13,"t":"他們毀壞我的道，加增我的災害；他們毋須人幫助。","notes":[]},{"n":14,"t":"他們來，如同闖進大缺口，在暴風間滾動。","notes":[]},{"n":15,"t":"驚恐傾倒在我身上，我的尊榮被逐如風；我的福祿如雲飄去。","notes":[]},{"n":16,"t":"「現在我的心極其悲傷，困苦的日子將我抓住。","notes":[]},{"n":17,"t":"夜間，我裏面的骨頭刺痛，啃著我的沒有止息。","notes":[]},{"n":18,"t":"我的外衣因大力扭皺 ，內衣的領子把我勒住。","notes":["「我的外衣...扭皺」：七十士譯本是「他用大力抓住我的外衣」。"]},{"n":19,"t":"神把我扔在淤泥之中，我就像塵土和灰燼一樣。","notes":[]},{"n":20,"t":"我呼求你，你不應允我；我站起來，你只是望著我。","notes":[]},{"n":21,"t":"你對我變得殘忍，大能的手追逼我。","notes":[]},{"n":22,"t":"你把我提到風中，使我乘風而去，使我消失在烈風之中。","notes":[]},{"n":23,"t":"我知道你要使我歸於死亡，到那為眾生所定的陰宅。","notes":[]},{"n":24,"t":"「然而，人在廢墟豈不伸手？遇災難時一定呼救。","notes":["「遇災難時一定呼救。」原文另譯「遇災難時豈不呼救呢？」或「遇災難時必得幫助。」"]},{"n":25,"t":"人遭難的日子，我豈不為他哭泣呢？人貧窮的時候，我豈不為他憂愁呢？","notes":[]},{"n":26,"t":"我仰望福氣，災禍就來到；我等待光明，黑暗便來臨。","notes":[]},{"n":27,"t":"我內心煩擾不安，困苦的日子臨到我身。","notes":[]},{"n":28,"t":"我在陰暗中行走，沒有日光，我在會眾中站立求救。","notes":["「我在陰暗中...日光」或譯「我變得黝黑並非因日曬」。"]},{"n":29,"t":"我與野狗為弟兄，我跟鴕鳥為同伴。","notes":[]},{"n":30,"t":"我的皮膚變黑脫落，我的骨頭因熱燒焦。","notes":[]},{"n":31,"t":"我的琴音變為哀泣；我的簫聲變為哭聲。」","notes":[]}]},"31":{"heading":"","verses":[{"n":1,"t":"「我與眼睛立約，怎能凝望少女呢？","notes":[]},{"n":2,"t":"從至上的神所得之分，從至高全能者所得之業是甚麼呢？","notes":[]},{"n":3,"t":"豈不是禍患臨到不義的，災害臨到作惡的嗎？","notes":[]},{"n":4,"t":"神豈不察看我的道路，數點我所有的腳步嗎？","notes":[]},{"n":5,"t":"「我若與虛謊同行，我腳若緊跟詭詐，","notes":[]},{"n":6,"t":"願神用公道的天平秤我，願他知道我的純正。","notes":[]},{"n":7,"t":"我的腳步若偏離正路，我的心若隨從我眼目，我的手掌若黏有污穢；","notes":[]},{"n":8,"t":"願我栽種，別人來吃，我的農作物連根拔出。","notes":[]},{"n":9,"t":"「我心若因婦人受迷惑，在鄰舍的門外等候，","notes":[]},{"n":10,"t":"就願我妻子給別人推磨，別人與她同寢。","notes":[]},{"n":11,"t":"因為這是邪惡的事，審判官裁定的罪孽。","notes":[]},{"n":12,"t":"這是一場火，直燒到毀滅，必拔除我一切的家產。","notes":["「毀滅」：原文音譯「亞巴頓」，意思是「滅亡之地」。"]},{"n":13,"t":"「我的僕婢與我爭辯，我若藐視不聽他們的冤情，","notes":[]},{"n":14,"t":"神興起的時候，我怎樣行呢？他察問的時候，我怎樣回答他呢？","notes":[]},{"n":15,"t":"造我在母腹中的，不也是造了他嗎？在母胎中使我們成形的，豈不是同一位嗎？","notes":[]},{"n":16,"t":"「我若不讓貧寒人遂其所願，或是叫寡婦眼中失望，","notes":[]},{"n":17,"t":"或獨自吃自己的食物，孤兒沒有吃其中些許；","notes":[]},{"n":18,"t":"從我年輕時，孤兒就與我一同長大，我好像他的父親，我從出母腹就扶助寡婦；","notes":["「我從出母腹...寡婦」：原文另譯「從他出母腹我就扶助他」。"]},{"n":19,"t":"我若見人因無衣死亡，或見貧窮人毫無遮蓋；","notes":[]},{"n":20,"t":"我若不使他真心為我祝福，不使他因我羊的毛得暖；","notes":[]},{"n":21,"t":"我若舉手攻擊孤兒，因為在城門口見有幫助我的；","notes":[]},{"n":22,"t":"情願我的肩膀從肩胛骨脫落，我的膀臂從肱骨折斷。","notes":[]},{"n":23,"t":"因神降的災禍使我恐懼，因他的威嚴，我甚麼都不能。","notes":["「因神...使我恐懼」：原文另譯「因敬畏神的心臨到我」。"]},{"n":24,"t":"「我若以黃金為我的指望，對純金說：你是我的倚靠；","notes":[]},{"n":25,"t":"我若因財物豐裕，因手多得資財而歡喜；","notes":[]},{"n":26,"t":"我若見太陽發光，明月運行，","notes":[]},{"n":27,"t":"心就暗暗被引誘，口親吻自己的手；","notes":[]},{"n":28,"t":"這也是審判官裁定的罪孽，因為我背棄了至上的神。","notes":[]},{"n":29,"t":"「我若見恨我的遇難就歡喜，見他遭災就高興；","notes":[]},{"n":30,"t":"其實我沒有容許口犯罪，以詛咒要他的性命；","notes":[]},{"n":31,"t":"若我帳棚中的人未曾說：『誰不以他的肉食吃飽呢？』","notes":[]},{"n":32,"t":"我未曾讓旅客在街上過夜，卻開門迎接行路的人；","notes":[]},{"n":33,"t":"我若像亞當遮掩自己的過犯，將罪孽藏在懷中；","notes":["「像亞當」或譯「向人」。"]},{"n":34,"t":"我若因大大懼怕眾人，又因宗族的藐視而恐懼，以致我緘默不言，閉門不出；","notes":[]},{"n":35,"t":"惟願有一位肯聽我！看哪，我的記號，願全能者回答我！願那與我爭訟的寫下狀詞！","notes":[]},{"n":36,"t":"我必把它帶在肩上，綁在頭上為冠冕。","notes":[]},{"n":37,"t":"我必向神述說我腳步的數目，如同王子進到他面前。","notes":[]},{"n":38,"t":"「若我的田地喊冤告我，犁溝也一同哭泣；","notes":[]},{"n":39,"t":"我若吃地的出產不給銀錢，或叫地的原主喪命；","notes":[]},{"n":40,"t":"願蒺藜生長代替麥子，惡臭的草代替大麥。」約伯的話說完了。","notes":[]}]},"32":{"heading":"以利戶的話","verses":[{"n":1,"t":"於是這三個人因約伯看自己為義就停止，不再回答他。","notes":[]},{"n":2,"t":"那時布西人蘭族巴拉迦的兒子以利戶發怒了。他向約伯發怒，因約伯自以為義，不以神為義。","notes":[]},{"n":3,"t":"他又向約伯的三個朋友發怒，因為他們想不出回答的話來，仍以約伯為有罪。","notes":[]},{"n":4,"t":"以利戶因為他們比自己年老，就等候要與約伯說話。","notes":[]},{"n":5,"t":"以利戶見這三個人口中無話回答，就發怒。","notes":[]},{"n":6,"t":"布西人巴拉迦的兒子以利戶回答說：「我年輕，你們年長，因此我退讓，不敢向你們陳述我的意見。","notes":[]},{"n":7,"t":"我說：『年長的當先說話；壽高的當以智慧教導人。』","notes":[]},{"n":8,"t":"其實，是人裏面的靈，全能者的氣使人有聰明。","notes":[]},{"n":9,"t":"壽高的不都有智慧，年老的不都明白公平。","notes":[]},{"n":10,"t":"因此我說：『你們要聽我，我也要陳述我的意見。』","notes":[]},{"n":11,"t":"「看哪，我等候你們的話，側耳聽你們的高見；直到你們找到要說的言語。","notes":[]},{"n":12,"t":"我留心聽你們，看哪，你們中間無一人能折服約伯，回答他的話。","notes":[]},{"n":13,"t":"你們切不可說：『我們尋得智慧；神能勝他，人卻不能。』","notes":["「能勝他」：原文另譯「教導我們」。"]},{"n":14,"t":"約伯沒有用言語與我爭辯；我也不用你們的話回答他。","notes":[]},{"n":15,"t":"「他們驚惶不再回答，一言不發。","notes":[]},{"n":16,"t":"我豈因他們不說話，因他們站住不再回答，仍舊等候呢？","notes":[]},{"n":17,"t":"我也要以我的一番話回答，我也要陳述我的意見。","notes":[]},{"n":18,"t":"因為我滿懷言語，我裏面的靈激動我。","notes":[]},{"n":19,"t":"看哪，我的肚腹如酒囊沒有氣孔，又如新皮袋快要破裂。","notes":["「新皮袋」：原文另譯「鐵匠的風箱」。"]},{"n":20,"t":"我要說話，使我舒暢；我要張開嘴唇回答。","notes":[]},{"n":21,"t":"我必不看人的情面，也不奉承人。","notes":[]},{"n":22,"t":"我不懂得奉承；不然，造我的主必快快除滅我。」","notes":[]}]},"33":{"heading":"","verses":[{"n":1,"t":"「但是，約伯啊，請聽我的言語，側耳聽我一切的話。","notes":[]},{"n":2,"t":"看哪，我開口，我的舌在上膛發言。","notes":[]},{"n":3,"t":"我的言語要表明心中的正直，我嘴唇所知道的就誠實地說。","notes":[]},{"n":4,"t":"神的靈造了我，全能者的氣使我得生。","notes":[]},{"n":5,"t":"你若能夠，就請回答我；請你站起來，在我面前陳明。","notes":[]},{"n":6,"t":"看哪，我在神面前與你一樣，也是用泥土造成的。","notes":[]},{"n":7,"t":"看哪，我不用威嚴恐嚇你，也不用勢力重壓你。","notes":[]},{"n":8,"t":"「其實，你向我耳朵說話，我聽見你言語的聲音：","notes":[]},{"n":9,"t":"『我是純潔無過的，我是無辜的，在我裏面沒有罪孽。","notes":[]},{"n":10,"t":"看哪，神找機會攻擊我，以我為他的仇敵，","notes":[]},{"n":11,"t":"把我的腳鎖上木枷，察看我一切的道路。』","notes":[]},{"n":12,"t":"「看哪，你這話無理，我要回答你，因神比世人更大。","notes":[]},{"n":13,"t":"你為何與他爭論：『他任何事都不向人解答』？","notes":[]},{"n":14,"t":"神說一次、兩次，人卻不理會。","notes":[]},{"n":15,"t":"世人在床上沉睡安眠時，在夢中和夜間的異象裏，","notes":[]},{"n":16,"t":"神就開通世人的耳朵，把警告印在他們心上，","notes":["「把警告印在他們心上」：原文另譯「用警告驚嚇他們」。"]},{"n":17,"t":"好叫人轉離自己的行為，叫壯士遠離驕傲，","notes":[]},{"n":18,"t":"攔阻人不陷入地府，不讓他命喪刀下。","notes":["「命喪刀下」：原文另譯「生命經過死河」。"]},{"n":19,"t":"「人在床上被疼痛懲治，骨頭不住地掙扎，","notes":[]},{"n":20,"t":"以致生命厭棄食物，心中厭惡美味。","notes":[]},{"n":21,"t":"他的肉消瘦，難以看見；先前看不見的骨頭都凸出來。","notes":[]},{"n":22,"t":"他的性命臨近地府，他的生命挨近滅命者。","notes":[]},{"n":23,"t":"一千天使中，若有一個作傳話的臨到他，指示人所當行的事，","notes":[]},{"n":24,"t":"神就施恩給他，說：『要救贖他免得下入地府，我已經得了贖價。","notes":["「救贖他」：有古抄本和古譯本是「釋放他」。"]},{"n":25,"t":"他的肉要比孩童的肉更嫩；他就返老還童。』","notes":[]},{"n":26,"t":"他向神禱告，神就悅納他；他必歡呼朝見神的面，因神恢復他的義。","notes":[]},{"n":27,"t":"他在人前歌唱說：『我犯了罪，顛倒是非，卻沒有受該得的報應。","notes":[]},{"n":28,"t":"神救贖我的性命免入地府，我的生命也必見光。』","notes":[]},{"n":29,"t":"「看哪，神兩次、三次向人行這一切的事，","notes":[]},{"n":30,"t":"為要從地府救回人的性命，使他被生命之光照耀。","notes":[]},{"n":31,"t":"約伯啊，你當留心聽我；不要作聲，我要說話。","notes":[]},{"n":32,"t":"你若有話說，可以回答我；你只管說，因我願以你為義。","notes":[]},{"n":33,"t":"若不然，你當聽我；不要作聲，我要把智慧教導你。」","notes":[]}]},"34":{"heading":"","verses":[{"n":1,"t":"以利戶繼續說：","notes":[]},{"n":2,"t":"「你們智慧人要聽我的言語，有知識的人要側耳聽我。","notes":[]},{"n":3,"t":"因為耳朵辨別言語，好像上膛品嘗食物。","notes":[]},{"n":4,"t":"我們當選擇公理，彼此知道何為善。","notes":[]},{"n":5,"t":"約伯曾說：『我是公義的，神奪去我的公理。","notes":[]},{"n":6,"t":"我有理，豈能說謊呢？我無過，受的箭傷卻不能醫治。』","notes":["「我有理，豈能說謊呢？」原文另譯「我的審判官殘酷待我。」七十士譯本是「在我的案件上，他說謊。」"]},{"n":7,"t":"哪一個人像約伯，喝譏誚如同喝水呢？","notes":[]},{"n":8,"t":"他與作惡的結伴，和惡人同行。","notes":[]},{"n":9,"t":"他說：『人以神為樂，總是無益。』","notes":[]},{"n":10,"t":"「所以，你們明理的人要聽我，神斷不致行惡，全能者斷不致不義。","notes":[]},{"n":11,"t":"他必按人所做的報應人，使各人照所行的得報。","notes":[]},{"n":12,"t":"確實地，神必不作惡，全能者必不偏離公平。","notes":[]},{"n":13,"t":"誰派他治理大地？誰安定全世界呢？","notes":[]},{"n":14,"t":"他若專心為己，將靈和氣收歸自己，","notes":[]},{"n":15,"t":"凡血肉之軀必一同死亡；世人必歸於塵土。","notes":[]},{"n":16,"t":"「你若明理，當聽這話，側耳聽我言語的聲音。","notes":[]},{"n":17,"t":"難道恨惡公平的可以掌權嗎？那有公義、有大能的，你豈可定他有罪呢？","notes":[]},{"n":18,"t":"你會對君王說：『你是卑鄙的』；對貴族說：『你們是邪惡的』嗎？","notes":["本節有古卷和古譯本是「他對君王說：『你是卑鄙的。』對貴族說：『你們是邪惡的。』」"]},{"n":19,"t":"他待王子不徇情面，也不看重富足的過於貧寒的，因為他們都是他手所造的。","notes":[]},{"n":20,"t":"一瞬間他們就死亡。百姓在半夜中被震動而去世；有權力的被奪去，非藉人手。","notes":[]},{"n":21,"t":"「神的眼目觀看人的道路，察看他每一腳步。","notes":[]},{"n":22,"t":"沒有黑暗，沒有死蔭，能給作惡者在那裏藏身。","notes":[]},{"n":23,"t":"神不必再三傳人到他面前受審判。","notes":[]},{"n":24,"t":"他毋須調查就粉碎有大能的人，指定別人代替他們。","notes":[]},{"n":25,"t":"所以他知道他們的行為，使他們在夜間傾倒壓碎。","notes":[]},{"n":26,"t":"他在眾目睽睽下擊打他們，如同擊打惡人。","notes":[]},{"n":27,"t":"因為他們轉離不跟從他，不留心他一切的道，","notes":[]},{"n":28,"t":"甚至使貧寒人的哀聲達到他那裏；他也聽了困苦人的哀聲。","notes":[]},{"n":29,"t":"他安靜，誰能定罪呢？他轉臉，誰能見他呢？無論一國或一人都是如此。","notes":[]},{"n":30,"t":"不虔敬的人不得作王，免得百姓陷入圈套。","notes":[]},{"n":31,"t":"「有誰對神說：『我受了責罰，必不再犯罪；","notes":[]},{"n":32,"t":"我所看不明的，求你指教我；我若行了不義，必不再行』？","notes":[]},{"n":33,"t":"他因你拒絕不接受，就隨你的心願施行報應嗎？選擇的是你，不是我。你所知道的，只管說吧！","notes":[]},{"n":34,"t":"明理的人必對我說，聽我的智慧人也說：","notes":[]},{"n":35,"t":"『約伯說話沒有知識，他的言語毫無智慧。』","notes":[]},{"n":36,"t":"願約伯被考驗到底，因他回答像惡人一樣。","notes":[]},{"n":37,"t":"他在罪上又加悖逆；在我們中間引起疑惑 ，用許多言語輕慢神。」","notes":["「引起疑惑」：原文直譯「敲擊」。"]}]},"35":{"heading":"","verses":[{"n":1,"t":"以利戶繼續說：","notes":[]},{"n":2,"t":"「你以為這話有理，說：『我在神面前是公義的。』","notes":[]},{"n":3,"t":"你說：『這對你有甚麼益處？我不犯罪有甚麼好處呢？』","notes":[]},{"n":4,"t":"至於我，我要用言語回答你和跟你一起的朋友。","notes":[]},{"n":5,"t":"你要向天觀看，瞻望那高於你的穹蒼。","notes":[]},{"n":6,"t":"你若犯罪，能使神受何害呢？你的過犯加增，能使神受何損呢？","notes":[]},{"n":7,"t":"你若是公義，能加增他甚麼呢？他從你手裏還接受甚麼呢？","notes":[]},{"n":8,"t":"你的罪惡只影響像你這類的人；你的公義也只影響世人。","notes":[]},{"n":9,"t":"「人因多受欺壓就哀求，因強權者的膀臂而求救。","notes":[]},{"n":10,"t":"但無人說：『造我的神在哪裏？他使人夜間歌唱，","notes":[]},{"n":11,"t":"教導我們多過地上的走獸，使我們比空中的飛鳥更聰明。』","notes":[]},{"n":12,"t":"因為惡人驕傲，他們在那裏呼求，他卻不回答。","notes":[]},{"n":13,"t":"虛妄的呼求，神必不垂聽；全能者必不留意。","notes":[]},{"n":14,"t":"何況你說，你不得見他。案件就在他面前，你等候他吧。","notes":[]},{"n":15,"t":"但如今因他未曾發怒降罰，也一點都不理會狂傲，","notes":[]},{"n":16,"t":"所以約伯開口說虛妄的話，多多發表無知識的言語。」","notes":[]}]},"36":{"heading":"","verses":[{"n":1,"t":"以利戶繼續說：","notes":[]},{"n":2,"t":"「你再給我片時，我就指示你，因我還有話要為神說。","notes":[]},{"n":3,"t":"我要把我的知識從遠處引來，我要將公義歸給造我的主。","notes":[]},{"n":4,"t":"我的言語絕不虛假，有全備知識的與你同在。","notes":[]},{"n":5,"t":"「看哪，神有大能，並不藐視人；他的心智能力廣大。","notes":[]},{"n":6,"t":"他不讓惡人活著，卻為困苦人伸冤。","notes":[]},{"n":7,"t":"他的眼目不遠離義人，卻使他們和君王同坐寶座，永遠被高舉 。","notes":["「卻使他們...被高舉」或譯「卻使君王坐上寶座，使他們永遠被高舉」。"]},{"n":8,"t":"他們若被鎖鏈捆住，被苦難的繩索纏住，","notes":[]},{"n":9,"t":"他就向他們指示他們的作為和過犯，以及他們的狂妄自大。","notes":[]},{"n":10,"t":"他也開通他們的耳朵來領受教導，吩咐他們回轉離開罪孽。","notes":[]},{"n":11,"t":"他們若聽從事奉他，就必度日亨通，歷年享福。","notes":[]},{"n":12,"t":"他們若不聽從，就要被刀殺滅，無知無識而死。","notes":[]},{"n":13,"t":"「那心中不敬虔的人積蓄怒氣；神捆綁他們，他們竟不求救。","notes":[]},{"n":14,"t":"他們必在青年時死亡，與神廟娼妓一樣喪命。","notes":[]},{"n":15,"t":"神藉著困苦救拔困苦人，藉所受的欺壓開通他們的耳朵。","notes":[]},{"n":16,"t":"神也必引你脫離患難，進入寬闊不狹窄之地；擺在你席上的必滿有肥甘。","notes":[]},{"n":17,"t":"「但你充滿著惡人的辯辭，辯辭和審判抓住你。","notes":[]},{"n":18,"t":"不可讓憤怒觸動你，使你破口謾罵；也不可因贖價大而偏行。","notes":["「不可讓...破口謾罵」：原文另譯「不要因他的富足而讓憤怒觸動你」。"]},{"n":19,"t":"你的呼求和一切的勢力，果真有用，使你不遭患難嗎？","notes":["「你的呼求」或譯「你的資財」。"]},{"n":20,"t":"不要切慕黑夜，就是眾民在本處被除滅的時候。","notes":[]},{"n":21,"t":"你要謹慎，不可偏向罪孽，因你選擇罪孽過於苦難。","notes":[]},{"n":22,"t":"看哪，神因他的能力而崇高；有誰像他那樣作教師呢？","notes":[]},{"n":23,"t":"誰派定他的道路呢？誰能說：『你行了不義』？","notes":[]},{"n":24,"t":"「你要記得頌讚他的作為，就是人所歌頌的。","notes":[]},{"n":25,"t":"他的作為，萬人都看見；世人也從遠處觀看。","notes":[]},{"n":26,"t":"看哪，神崇高，我們不能知道；他的年數，不能測度。","notes":[]},{"n":27,"t":"因他吸取水點，水點就從雲霧中變成雨；","notes":[]},{"n":28,"t":"雲彩將雨落下，沛然降於世人。","notes":[]},{"n":29,"t":"又有誰能明白密雲如何鋪張，和神行宮的雷聲呢？","notes":[]},{"n":30,"t":"看哪，他的亮光普照自己的四圍；他覆蓋海的深處。","notes":[]},{"n":31,"t":"因他用這些審判眾民，又賜豐富的糧食。","notes":["「審判」或譯「治理」。"]},{"n":32,"t":"他以閃電遮手掌，命令它擊中靶子。","notes":[]},{"n":33,"t":"所發的雷聲將他顯明，牲畜也指明要起暴風。」","notes":["「牲畜也指明要起暴風」：原文另譯「他因罪孽而發出妒火的怒氣」。"]}]},"37":{"heading":"","verses":[{"n":1,"t":"「因此我心戰兢，從原處移動。","notes":[]},{"n":2,"t":"聽啊，聽他轟轟的聲音，是神口中所發的響聲。","notes":[]},{"n":3,"t":"他發響聲震遍天下，他的閃電直到地極。","notes":[]},{"n":4,"t":"隨後，人聽見他的聲音，是那轟轟的聲音；他發出威嚴的雷聲，而不加以遏止。","notes":[]},{"n":5,"t":"神發出奇妙的雷聲；他行大事，我們不能測透。","notes":[]},{"n":6,"t":"他對雪說：『要降在地上』；對大雨和暴雨也是這樣說。","notes":[]},{"n":7,"t":"他封住各人的手，叫所造的萬人都知道他的作為。","notes":[]},{"n":8,"t":"野獸進入穴中，臥在自己洞內。","notes":[]},{"n":9,"t":"暴風來自內宮，寒冷出於狂風。","notes":[]},{"n":10,"t":"神噓氣成冰，凝結寬闊之水，","notes":[]},{"n":11,"t":"使密雲盛滿水氣，烏雲散佈閃電。","notes":[]},{"n":12,"t":"雲藉著他的指引遊行旋轉，在世界的地面上行他一切所吩咐的，","notes":[]},{"n":13,"t":"或為責罰，或為他的地，或為慈愛，都是他所行的。","notes":[]},{"n":14,"t":"「約伯啊，側耳聽這話，要站立，思想神奇妙的作為。","notes":[]},{"n":15,"t":"你知道神如何安排這些，如何使雲中的閃電照耀嗎？","notes":[]},{"n":16,"t":"你知道雲彩如何浮於空中，知識全備者奇妙的作為嗎？","notes":[]},{"n":17,"t":"你知道南風使地寂靜，你的衣服就變為熱嗎？","notes":[]},{"n":18,"t":"你豈能與神同鋪穹蒼，堅固如同鑄成的鏡子嗎？","notes":[]},{"n":19,"t":"我們因在黑暗中，不會陳說，請你指教我們該對他說甚麼。","notes":[]},{"n":20,"t":"有人告訴他我要說話嗎？豈有人說他願被吞滅嗎？","notes":[]},{"n":21,"t":"「現在，人不得見穹蒼的亮光；風一吹過，天色晴朗。","notes":[]},{"n":22,"t":"金色的光輝來自北方，在神那裏有可畏的威嚴。","notes":[]},{"n":23,"t":"全能者，我們不能測度；他大有能力，又有公平，滿有公義，必不苦待人。","notes":[]},{"n":24,"t":"所以，世人敬畏他；凡自以為有智慧的，他都不看顧。」","notes":["「自以為」：原文直譯「心中」。"]}]},"38":{"heading":"耶和華回答約伯","verses":[{"n":1,"t":"那時，耶和華從旋風中回答約伯說：","notes":[]},{"n":2,"t":"「誰用無知的言語使我的旨意暗昧不明？","notes":[]},{"n":3,"t":"你要如勇士束腰；我問你，你可以讓我知道。","notes":[]},{"n":4,"t":"「我立大地根基的時候，你在哪裏？你若明白事理，只管說吧！","notes":[]},{"n":5,"t":"你知道是誰定地的尺度，是誰把準繩拉在其上嗎？","notes":[]},{"n":6,"t":"地的根基安置在何處？地的角石是誰安放的？","notes":[]},{"n":7,"t":"那時，晨星一同歌唱；神的眾使者也都歡呼。","notes":[]},{"n":8,"t":"「當海水衝出，如出母胎，誰用門將它關閉呢？","notes":[]},{"n":9,"t":"是我用雲彩當海的衣服，用幽暗當包裹它的布，","notes":[]},{"n":10,"t":"為它定界限，又安門和閂，","notes":[]},{"n":11,"t":"說：『你只可到這裏，不可越過；你狂傲的浪要到此止住。』","notes":[]},{"n":12,"t":"「你有生以來，曾命定晨光，曾使黎明知道自己的地位，","notes":[]},{"n":13,"t":"抓住地的四極，把惡人從其中驅逐出來嗎？","notes":[]},{"n":14,"t":"地改變如泥上蓋印，萬物出現如衣服一樣。","notes":[]},{"n":15,"t":"亮光不照惡人，高舉的膀臂也必折斷。","notes":[]},{"n":16,"t":"「你曾進到海之源，或在深淵的隱密處行走嗎？","notes":[]},{"n":17,"t":"死亡的門曾向你顯露嗎？死蔭的門你曾見過嗎？","notes":[]},{"n":18,"t":"地的廣大，你能測透嗎？你若全知道，只管說吧！","notes":[]},{"n":19,"t":"「往光明居所的路在哪裏？黑暗的地方在何處？","notes":[]},{"n":20,"t":"你能將它帶到其領域，能辨明其居所之路嗎？","notes":[]},{"n":21,"t":"你知道的，因為那時你已出生，你活的日子數目也多。","notes":[]},{"n":22,"t":"「你曾進入雪之庫，或見過雹的倉嗎？","notes":[]},{"n":23,"t":"雪雹是我為災難的時候，為打仗和戰爭的日子所預備。","notes":[]},{"n":24,"t":"光亮從何路分開？東風從何路分散遍地？","notes":[]},{"n":25,"t":"「誰為大雨分道，誰為雷電開路，","notes":[]},{"n":26,"t":"使雨降在無人之地，在無人居住的曠野，","notes":[]},{"n":27,"t":"使荒廢淒涼之地得以豐足，青草得以生長？","notes":[]},{"n":28,"t":"「雨有父親嗎？露珠是誰生的呢？","notes":[]},{"n":29,"t":"冰出於誰的胎？天上的霜是誰生的呢？","notes":[]},{"n":30,"t":"諸水堅硬如石頭，深淵之面凝結成冰。","notes":[]},{"n":31,"t":"「你能為昴星繫結嗎？你能為參星解帶嗎？","notes":[]},{"n":32,"t":"你能按時領出星宿嗎？能引導北斗與其眾星嗎？","notes":[]},{"n":33,"t":"你知道天的定律嗎？你能使地歸其權下嗎？","notes":[]},{"n":34,"t":"「你能向密雲揚起聲來，使傾盆的雨遮蓋你嗎？","notes":[]},{"n":35,"t":"你能發出閃電，使它們行走，並對你說『我們在這裏』嗎？","notes":["「它們」指「閃電」。"]},{"n":36,"t":"誰將智慧放在朱鷺中？誰將聰明賜給雄雞？","notes":["「朱鷺」或譯「懷」。","「雄雞」或譯「心內」。"]},{"n":37,"t":"誰能用智慧數算雲彩？誰能傾倒天上的瓶呢？","notes":[]},{"n":38,"t":"那時，塵土聚集成團，土塊緊緊結連。","notes":[]},{"n":39,"t":"「你能為母獅抓取獵物，使少壯的獅子飽足嗎？","notes":[]},{"n":40,"t":"那時，牠們在洞中蹲伏，在隱密處埋伏。","notes":[]},{"n":41,"t":"誰能為烏鴉預備食物呢？那時，烏鴉之雛哀求神，因無食物飛來飛去。」","notes":[]}]},"39":{"heading":"","verses":[{"n":1,"t":"「你知道巖石間的野山羊幾時生產嗎？你能觀察母鹿下小鹿嗎？","notes":[]},{"n":2,"t":"你能數算牠們懷胎的月數嗎？你知道牠們幾時生產嗎？","notes":[]},{"n":3,"t":"牠們屈身，生下幼兒，就解除了陣痛。","notes":[]},{"n":4,"t":"其子漸漸肥壯，在荒野長大；牠們出去，不再歸回。","notes":[]},{"n":5,"t":"「誰放野驢自由？誰解開快驢的繩索？","notes":[]},{"n":6,"t":"我使曠野作牠的住處，使鹽地當牠的居所。","notes":[]},{"n":7,"t":"牠嘲笑城內的喧嚷，不聽趕牲口的喝聲。","notes":[]},{"n":8,"t":"諸山是牠漫遊的草場，牠尋找各樣青綠之物。","notes":[]},{"n":9,"t":"「野牛豈肯服事你？豈肯在你的槽旁過夜？","notes":[]},{"n":10,"t":"你豈能用套繩將野牛繫於犁溝？牠豈肯隨你耙鬆山谷之地？","notes":[]},{"n":11,"t":"你豈可因牠力大就倚靠牠？豈可把你的工交給牠做呢？","notes":[]},{"n":12,"t":"你豈能靠牠把你的穀物運回，又收聚在你的禾場上嗎？","notes":["本節原文另譯「你豈能信賴牠會回來，又收聚你禾場上的穀物呢？」"]},{"n":13,"t":"「鴕鳥的翅膀歡然拍動，但豈是鸛的翎毛和羽毛嗎？","notes":["「但豈是...羽毛嗎」或譯「牠的翎毛和羽毛豈是顯示慈愛嗎」；「慈愛」與「鸛」的希伯來話發音相近。"]},{"n":14,"t":"因牠把蛋留在地上，使蛋在塵土中得溫暖，","notes":[]},{"n":15,"t":"卻忘記腳會把蛋踹碎，野獸會踐踏它。","notes":[]},{"n":16,"t":"牠粗暴待雛，似乎不是自己生的；雖徒然勞苦，也不懼怕。","notes":["「勞苦」指「孵蛋」。"]},{"n":17,"t":"因為神使牠忘記智慧，也未將悟性分給牠。","notes":[]},{"n":18,"t":"牠幾時挺身展開翅膀，就嘲笑馬和騎馬的人。","notes":[]},{"n":19,"t":"「馬的力量是你所賜的嗎？牠頸項上的鬃是你披上的嗎？","notes":[]},{"n":20,"t":"是你叫牠跳躍像蝗蟲嗎？牠噴氣之威嚴使人驚惶。","notes":[]},{"n":21,"t":"牠用蹄在谷中挖地，以能力歡躍；牠出去迎擊仇敵。","notes":["「牠用蹄...挖地」：原文直譯「牠們在谷中挖地」。","「仇敵」：原文是「兵器」。"]},{"n":22,"t":"牠嘲笑懼怕，並不驚惶，也不因刀劍退卻。","notes":[]},{"n":23,"t":"箭袋在牠身上錚錚有聲，槍和短槍閃閃發亮。","notes":[]},{"n":24,"t":"牠震顫激動，將地吞下 ；一聽角聲就站不住。","notes":["「將地吞下」意思是「全速奔跑」。"]},{"n":25,"t":"每逢角聲一響，牠說：『啊哈！』牠從遠處聞到戰爭的氣息，聽見軍官如雷的吼聲和吶喊。","notes":[]},{"n":26,"t":"「鷹展開翅膀向南飛翔，豈是藉著你的智慧嗎？","notes":[]},{"n":27,"t":"大鷹上騰在高處搭窩，豈是聽你的指示嗎？","notes":[]},{"n":28,"t":"牠住在山巖，以山峰和堅固之所為家，","notes":[]},{"n":29,"t":"從那裏窺察食物，眼睛自遠方瞭望。","notes":[]},{"n":30,"t":"牠的雛吸血；被殺的人在哪裏，牠也在哪裏。」","notes":[]}]},"40":{"heading":"","verses":[{"n":1,"t":"耶和華繼續對約伯說：","notes":[]},{"n":2,"t":"「強辯的豈可與全能者爭論？與神辯駁的可以回答吧！」","notes":[]},{"n":3,"t":"於是，約伯回答耶和華說：","notes":[]},{"n":4,"t":"「看哪，我是卑賤的！我用甚麼回答你呢？我只好用手摀住我的口。","notes":[]},{"n":5,"t":"我說了一次，就不回答；說了兩次，不再說了。」","notes":[]},{"n":6,"t":"於是，耶和華從旋風中回答約伯說：","notes":[]},{"n":7,"t":"「你要如勇士束腰；我問你，你可以讓我知道。","notes":[]},{"n":8,"t":"你豈可廢棄我的判斷？豈可定我有罪，好顯自己為義嗎？","notes":[]},{"n":9,"t":"你有神那樣的膀臂嗎？你能像他那樣發雷聲嗎？","notes":[]},{"n":10,"t":"「你要以榮耀莊嚴為妝飾，以尊榮威嚴為衣服。","notes":[]},{"n":11,"t":"你要發出你滿溢的怒氣，見一切驕傲的人，使他降卑；","notes":[]},{"n":12,"t":"你見一切驕傲的人，將他制伏，把惡人踐踏在原來地方。","notes":[]},{"n":13,"t":"你將他們一同埋藏在塵土中，把他們的臉遮蔽在隱密處。","notes":["「把他們...隱密處」意思是「把他們捆綁在陰間」。"]},{"n":14,"t":"這樣，我也向你承認，你的右手能救你自己。","notes":[]},{"n":15,"t":"「看哪，我造河馬，也造了你；牠吃草像牛一樣。","notes":[]},{"n":16,"t":"看哪，牠的力氣在腰間，能力在肚腹的肌肉上。","notes":[]},{"n":17,"t":"牠挺直尾巴如香柏樹，牠大腿的筋緊密結合。","notes":["「挺直」或譯「垂下」。"]},{"n":18,"t":"牠的骨頭好像銅管；牠的肢體彷彿鐵棍。","notes":[]},{"n":19,"t":"「牠在神所造之物中為首，只有創造牠的能攜刀臨近牠。","notes":[]},{"n":20,"t":"諸山為牠產出食物，百獸也在那裏遊玩。","notes":[]},{"n":21,"t":"牠伏在蓮葉之下，在蘆葦和沼澤的隱密處。","notes":[]},{"n":22,"t":"蓮葉的陰影遮蔽牠，溪旁的柳樹環繞牠。","notes":[]},{"n":23,"t":"看哪，河水氾濫，牠不慌張；連約旦河漲到牠口邊，牠也安然自若。","notes":[]},{"n":24,"t":"誰能在牠眼前捉拿牠呢？誰能以圈套穿牠鼻子呢？」","notes":[]}]},"41":{"heading":"","verses":[{"n":1,"t":"「你能用魚鉤釣上力威亞探嗎？能用繩子壓下牠的舌頭嗎？","notes":["「力威亞探」是音譯，一種海獸；或譯「鱷魚」。"]},{"n":2,"t":"你能用繩索穿牠的鼻子嗎？能用鉤子穿牠的腮骨嗎？","notes":[]},{"n":3,"t":"牠豈向你連連懇求，向你說溫柔的話嗎？","notes":[]},{"n":4,"t":"牠豈肯與你立約，讓你拿牠永遠作奴僕嗎？","notes":[]},{"n":5,"t":"你豈可拿牠當雀鳥玩耍？豈可將牠繫來給你幼女？","notes":[]},{"n":6,"t":"合夥的魚販豈可拿牠當貨物？他們豈可把牠分給商人呢？","notes":[]},{"n":7,"t":"你能用倒鉤扎滿牠的皮，能用魚叉叉滿牠的頭嗎？","notes":[]},{"n":8,"t":"把你的手掌按在牠身上吧！想一想與牠搏鬥，你就不再這樣做了！","notes":[]},{"n":9,"t":"看哪，對牠有指望是徒然的；一見牠，豈不也喪膽嗎？","notes":["「一見牠，豈不也喪膽嗎？」原文另譯「一見到牠，人也喪膽。」有古譯本是「一見牠，神明也喪膽嗎？」"]},{"n":10,"t":"沒有那麼兇猛的人敢惹牠。這樣，誰能在我面前站立得住呢？","notes":["「沒有...敢惹牠。」或譯「牠不是那麼兇猛，以致沒有人敢惹牠嗎？」"]},{"n":11,"t":"誰能與我對質，使我償還呢？天下萬物都是我的。","notes":[]},{"n":12,"t":"「我不能緘默不提牠的肢體和力量，以及健美的骨骼。","notes":[]},{"n":13,"t":"誰能剝牠的外皮？誰能進牠的鎧甲之間呢？","notes":["「牠的鎧甲之間」是根據七十士譯本；原文是「牠轡頭的兩邊」。"]},{"n":14,"t":"誰能開牠的腮頰？牠牙齒的四圍是可畏的。","notes":[]},{"n":15,"t":"牠的背上有一排排的鱗甲，緊緊閉合，封得嚴密。","notes":["「牠的背上...鱗甲」是根據七十士譯本；原文是「牠以一排排的鱗甲為可誇」。"]},{"n":16,"t":"這鱗甲一一相連，氣不得透入其間，","notes":[]},{"n":17,"t":"互相連接，膠結一起，不能分開。","notes":[]},{"n":18,"t":"牠打噴嚏就發出光來，牠的眼睛好像晨曦。","notes":["「好像晨曦」：原文直譯「好像清晨的眼皮」。"]},{"n":19,"t":"從牠口中發出燒著的火把，有火星飛迸出來；","notes":[]},{"n":20,"t":"從牠鼻孔冒出煙來，如燒開的鍋在沸騰。","notes":["「在沸騰」：原文另譯「和蘆葦」。"]},{"n":21,"t":"牠的氣點著煤炭，有火焰從牠口中發出。","notes":[]},{"n":22,"t":"牠頸項中存著勁力，恐懼在牠面前蹦跳。","notes":[]},{"n":23,"t":"牠的肉塊緊緊結連，緊貼其身，不能搖動。","notes":[]},{"n":24,"t":"牠的心結實如石頭，如下面的磨石那樣結實。","notes":[]},{"n":25,"t":"牠一起來，神明都恐懼，因崩潰而驚慌失措。","notes":[]},{"n":26,"t":"人用刀劍扎牠，是無用的，槍、標槍、尖槍也一樣。","notes":[]},{"n":27,"t":"牠以鐵為乾草，以銅為爛木。","notes":[]},{"n":28,"t":"箭不能使牠逃走，牠看彈石如碎稭。","notes":[]},{"n":29,"t":"牠當棍棒作碎稭，牠嘲笑短槍的颼颼聲。","notes":[]},{"n":30,"t":"牠肚腹下面是尖瓦片；牠如釘耙刮過淤泥。","notes":[]},{"n":31,"t":"牠使深淵滾沸如鍋，使海洋如鍋中膏油。","notes":[]},{"n":32,"t":"牠使走過以後的路發光，令人覺得深淵如同白髮。","notes":[]},{"n":33,"t":"塵世上沒有像牠那樣的受造物，一無所懼。","notes":[]},{"n":34,"t":"凡高大的，牠盯著看；牠在一切狂傲的野獸中作王。」","notes":[]}]},"42":{"heading":"結尾","verses":[{"n":1,"t":"約伯回答耶和華說：","notes":[]},{"n":2,"t":"「我知道，你萬事都能做；你的計劃不能攔阻。","notes":[]},{"n":3,"t":"誰無知使你的旨意隱藏呢？因此我說的，我不明白；這些事太奇妙，是我不知道的。","notes":[]},{"n":4,"t":"求你聽我，我要說話；我問你，求你讓我知道。","notes":[]},{"n":5,"t":"我從前風聞有你，現在親眼看見你。","notes":[]},{"n":6,"t":"因此我撤回，在塵土和爐灰中懊悔。」","notes":["「我撤回」或譯「我厭惡」；原文另譯「我瓦解了」。"]},{"n":7,"t":"耶和華對約伯說話以後，耶和華就對提幔人以利法說：「我的怒氣向你和你兩個朋友發作，因為你們議論我，不如我的僕人約伯說的正確。","notes":[]},{"n":8,"t":"現在你們要為自己取七頭公牛、七隻公羊，到我的僕人約伯那裏去，為自己獻上燔祭，我的僕人約伯就為你們祈禱。我必悅納他，不按你們的愚妄處置你們。你們議論我，不如我的僕人約伯說的正確。」","notes":[]},{"n":9,"t":"於是提幔人以利法、書亞人比勒達、拿瑪人瑣法遵照耶和華所吩咐的去做，耶和華就悅納約伯。","notes":[]},{"n":10,"t":"約伯為他的朋友祈禱。耶和華就使約伯從苦境中轉回，並且耶和華賜給他的比他從前所有的加倍。","notes":["「苦境」：原文直譯「擄掠」。"]},{"n":11,"t":"約伯的兄弟、姊妹，和以前所認識的人都來到他那裏，在他家裏跟他一同吃飯。他們因耶和華所降於他的一切災禍，都為他悲傷，安慰他。每人送他一塊可錫塔和一個金環。","notes":["「可錫塔」：古希伯來錢幣單位；參「度量衡表」。"]},{"n":12,"t":"這樣，耶和華後來賜福給約伯比先前更多。他有一萬四千隻羊，六千匹駱駝，一千對牛，一千匹母驢。","notes":[]},{"n":13,"t":"他也有七個兒子，三個女兒。","notes":[]},{"n":14,"t":"他給長女起名叫耶米瑪，次女叫基洗亞，三女叫基連哈樸。","notes":[]},{"n":15,"t":"在全地的婦女中找不著像約伯的女兒那樣美貌的。她們的父親使她們在兄弟中得產業。","notes":[]},{"n":16,"t":"此後，約伯又活了一百四十年，得見他的四代兒孫。","notes":[]},{"n":17,"t":"這樣，約伯年紀老邁，日子滿足而死。","notes":[]}]}},"PSA":{"1":{"heading":"真福","verses":[{"n":1,"t":"不從惡人的計謀，不站罪人的道路，不坐傲慢人的座位，惟喜愛耶和華的律法，晝夜思想他的律法；這人便為有福！","notes":["「思想」或譯「默念」。"],"end":2},{"n":3,"t":"他要像一棵樹栽在溪水旁，按時候結果子，葉子也不枯乾。凡他所做的盡都順利。","notes":[]},{"n":4,"t":"惡人並不是這樣，卻像糠秕被風吹散。","notes":[]},{"n":5,"t":"因此，當審判的時候惡人必站立不住，罪人在義人的會眾中也是如此。","notes":[]},{"n":6,"t":"因為耶和華知道義人的道路，惡人的道路卻必滅亡。","notes":[]}]},"2":{"heading":"神所揀選的君王","verses":[{"n":1,"t":"列國為甚麼爭鬧？萬民為甚麼圖謀虛妄？","notes":[]},{"n":2,"t":"世上的君王都站穩，臣宰一同算計，要對抗耶和華，對抗他的受膏者：","notes":[]},{"n":3,"t":"「我們要掙脫他們的捆綁，脫去他們的繩索。」","notes":[]},{"n":4,"t":"那坐在天上的必譏笑，主必嗤笑他們。","notes":[]},{"n":5,"t":"那時，他要在怒中責備他們，在烈怒中驚嚇他們：","notes":[]},{"n":6,"t":"「我已經在錫安－我的聖山膏立了我的君王。」","notes":[]},{"n":7,"t":"我要傳耶和華的聖旨，他對我說：「你是我的兒子，我今日生了你。","notes":[]},{"n":8,"t":"你求我，我就將列國賜你為基業，將地極賜你為田產。","notes":[]},{"n":9,"t":"你必用鐵杖打破他們，把他們如同陶匠的瓦器摔碎。」","notes":[]},{"n":10,"t":"現在，君王啊，應當謹慎！世上的審判官哪，要聽勸戒！","notes":[]},{"n":11,"t":"當存敬畏的心事奉耶和華，又當戰兢而快樂。","notes":[]},{"n":12,"t":"當親吻兒子，免得他發怒，你們就在半途中滅亡，因為他的怒氣快要發作。凡投靠他的，都是有福的。","notes":[]}]},"3":{"heading":"求助的晨禱","verses":[{"n":1,"t":"耶和華啊，我的敵人何其增多！許多人起來攻擊我。","notes":[]},{"n":2,"t":"許多人議論我：「他得不到神的幫助。」（細拉）","notes":[]},{"n":3,"t":"但你－耶和華是我四圍的盾牌，是我的榮耀，又是令我抬起頭來的。","notes":[]},{"n":4,"t":"我用我的聲音求告耶和華，他就從他的聖山上應允我。（細拉）","notes":[]},{"n":5,"t":"我躺下，我睡覺，我醒來，耶和華都保佑我。","notes":[]},{"n":6,"t":"雖有成萬的百姓周圍攻擊我，我也不懼怕。","notes":[]},{"n":7,"t":"耶和華啊，求你興起！我的神啊，求你救我！因為你打斷我所有仇敵的腮骨，敲碎了惡人的牙齒。","notes":[]},{"n":8,"t":"救恩屬於耶和華；願你賜福給你的百姓。（細拉）","notes":[]}]},"4":{"heading":"求助的晚禱","verses":[{"n":1,"t":"顯我為義的神啊，我呼求的時候，求你應允我！我在困境中，你曾使我寬暢；求你憐憫我，聽我的禱告！","notes":[]},{"n":2,"t":"你們這些人哪，你們把我的尊榮變為羞辱，要到幾時呢？你們喜愛虛妄，尋找虛假，要到幾時呢？（細拉）","notes":["本節七十士譯本是「你們這些人哪，你們的心剛硬要到幾時呢？你們為甚麼喜愛虛妄，尋找虛假呢？」"]},{"n":3,"t":"你們要知道，耶和華已將虔誠人分別出來歸他自己；我求告耶和華，他必垂聽。","notes":[]},{"n":4,"t":"應當畏懼，不可犯罪；在床上的時候，要心裏思想，並要安靜。（細拉）","notes":[]},{"n":5,"t":"當獻上公義的祭，又當倚靠耶和華。","notes":[]},{"n":6,"t":"有許多人說：「誰能指示我們甚麼好處？耶和華啊，求你用你臉上的光照耀我們。」","notes":[]},{"n":7,"t":"你使我心裏喜樂，勝過那豐收五穀新酒的人。","notes":[]},{"n":8,"t":"我必平安地躺下睡覺，因為獨有你－耶和華使我安然居住。","notes":[]}]},"5":{"heading":"求主保護","verses":[{"n":1,"t":"耶和華啊，求你側耳聽我的言語，顧念我的心思！","notes":[]},{"n":2,"t":"我的王，我的神啊，求你留心聽我呼求的聲音！因為我向你祈禱。","notes":[]},{"n":3,"t":"耶和華啊，早晨你必聽我的聲音；早晨我要向你陳明我的心思，並要警醒。","notes":[]},{"n":4,"t":"因為你不是喜愛邪惡的神，惡人不能與你同住。","notes":[]},{"n":5,"t":"狂傲的人不能站在你眼前；凡作惡的，都是你所恨惡的。","notes":[]},{"n":6,"t":"說謊言的，你必滅絕；好流人血、玩弄詭詐的，都為耶和華所憎惡。","notes":[]},{"n":7,"t":"至於我，我必憑你豐盛的慈愛進入你的居所，我要存敬畏你的心向你的聖殿下拜。","notes":[]},{"n":8,"t":"耶和華啊，求你因我仇敵的緣故，憑你的公義引領我，使你的道路在我面前正直。","notes":[]},{"n":9,"t":"因為他們口中沒有誠實，心裏充滿邪惡，他們的喉嚨是敞開的墳墓；他們用舌頭諂媚人。","notes":[]},{"n":10,"t":"神啊，求你定他們的罪！願他們因自己的計謀跌倒；求你因他們過犯眾多趕逐他們，因為他們背叛了你。","notes":[]},{"n":11,"t":"凡投靠你的，願他們喜樂，時常歡呼，因為你庇護他們；又願那愛你名的人都靠你歡欣。","notes":[]},{"n":12,"t":"耶和華啊，因為你必賜福給義人，你必用恩惠如同盾牌四面護衛他。","notes":[]}]},"6":{"heading":"患難中求助的祈禱","verses":[{"n":1,"t":"耶和華啊，求你不要在怒中責備我，不要在烈怒中懲罰我！","notes":[]},{"n":2,"t":"耶和華啊，求你憐憫我，因為我軟弱。耶和華啊，求你醫治我，因為我的骨頭戰抖。","notes":[]},{"n":3,"t":"我的心也大大驚惶。耶和華啊，你要等到幾時呢？","notes":[]},{"n":4,"t":"耶和華啊，求你轉回搭救我，因你的慈愛拯救我。","notes":[]},{"n":5,"t":"因為死了的人不會記念你，在陰間有誰稱謝你？","notes":[]},{"n":6,"t":"我因呻吟而困乏；我每夜流淚，使床鋪漂起，把褥子濕透。","notes":[]},{"n":7,"t":"我的眼睛因憂愁而昏花，因敵人的緣故，我的眼目模糊不清。","notes":[]},{"n":8,"t":"你們所有作惡的人，離開我吧！因為耶和華聽了我哀哭的聲音。","notes":[]},{"n":9,"t":"耶和華聽了我的懇求，耶和華必接納我的禱告。","notes":[]},{"n":10,"t":"我所有的仇敵都必羞愧，大大驚惶；轉眼之間，他們要羞愧撤退。","notes":[]}]},"7":{"heading":"為公義而祈禱","verses":[{"n":1,"t":"耶和華－我的神啊，我投靠你！求你救我脫離所有追趕我的人，搭救我出來！","notes":[]},{"n":2,"t":"免得他們像獅子撕裂我，甚至撕碎，無人搭救。","notes":[]},{"n":3,"t":"耶和華－我的神啊，我若行了這事，若有罪孽在我手裏，","notes":[]},{"n":4,"t":"我若以惡回報我的朋友，連那無故與我為敵的，我也救了他，","notes":["「連那...救了他」：原文另譯「或無緣無故掠奪與我為敵的人」。"]},{"n":5,"t":"就任憑仇敵追趕我，直到追上，把我的性命踏在地上，使我的榮耀歸於灰塵。（細拉）","notes":[]},{"n":6,"t":"耶和華啊，求你在怒中起來，挺身而立，抵擋我敵人的烈怒！求你為我興起！你已經發令施行審判。","notes":[]},{"n":7,"t":"願萬民聚集環繞你！願你居高位統治他們！","notes":[]},{"n":8,"t":"耶和華向萬民施行審判；耶和華啊，求你按我的公義和我心中的純正判斷我。","notes":[]},{"n":9,"t":"願惡人的惡斷絕！願你堅立義人！因為公義的神察驗人的心腸肺腑。","notes":[]},{"n":10,"t":"神是我的盾牌，他拯救心裏正直的人。","notes":[]},{"n":11,"t":"神是公義的審判者，又是天天向惡人發怒的神。","notes":[]},{"n":12,"t":"若有人不回頭，他的刀必磨快，弓必上弦，預備妥當。","notes":[]},{"n":13,"t":"他也預備了致死的兵器，他所射的是火箭。","notes":[]},{"n":14,"t":"看哪，惡人懷邪惡，養毒害，生虛假。","notes":[]},{"n":15,"t":"他掘了坑，挖得太深，竟掉在自己所挖的陷阱裏。","notes":[]},{"n":16,"t":"他的毒害必回到自己頭上，他的殘暴必落到自己的腦袋上。","notes":[]},{"n":17,"t":"我要照著耶和華的公義稱謝他，要歌頌耶和華至高者的名。","notes":[]}]},"8":{"heading":"神的榮耀和人的尊貴","verses":[{"n":1,"t":"耶和華－我們的主啊，你的名在全地何其美！你將你的榮耀彰顯於天。","notes":["「你將...天」：七十士譯本是「你的榮耀高舉於天」。"]},{"n":2,"t":"你因敵人的緣故，從孩童和吃奶的口中建立了能力，使仇敵和報仇的閉口無言。","notes":[]},{"n":3,"t":"我觀看你手指所造的天，並你所陳設的月亮星宿。","notes":[]},{"n":4,"t":"人算甚麼，你竟顧念他！世人算甚麼，你竟眷顧他！","notes":[]},{"n":5,"t":"你使他比神微小一點，賜他榮耀尊貴為冠冕。","notes":["「神」或譯「天使」；七十士譯本是「天使」。"]},{"n":6,"t":"你派他管理你手所造的，使萬物，就是一切的牛羊、田野的牲畜、空中的鳥、海裏的魚，凡游在水裏的，都服在他的腳下。","notes":[],"end":8},{"n":9,"t":"耶和華－我們的主啊，你的名在全地何其美！","notes":[]}]},"9":{"heading":"稱頌耶和華的公義","verses":[{"n":1,"t":"我要一心稱謝耶和華，傳揚你一切奇妙的作為。","notes":[]},{"n":2,"t":"我要因你歡喜快樂；至高者啊，我要歌頌你的名！","notes":[]},{"n":3,"t":"我的仇敵回轉撤退的時候，他們在你面前跌倒滅亡。","notes":[]},{"n":4,"t":"因你已經為我伸冤，為我辯護；你坐在寶座上，按公義審判。","notes":[]},{"n":5,"t":"你曾斥責列國，滅絕惡人；你曾塗去他們的名，直到永永遠遠。","notes":[]},{"n":6,"t":"仇敵到了盡頭；他們遭毀壞，直到永遠。你拆毀他們的城鎮，連他們的名字也都消滅！","notes":["「名字」：原文是「紀念」。"]},{"n":7,"t":"惟耶和華坐在王位上，直到永遠；他已經為審判擺設寶座。","notes":[]},{"n":8,"t":"他要按公義審判世界，按正直判斷萬民。","notes":[]},{"n":9,"t":"耶和華要作受欺壓者的庇護所，在患難時的庇護所。","notes":[]},{"n":10,"t":"耶和華啊，認識你名的人要倚靠你，因你沒有離棄尋求你的人。","notes":[]},{"n":11,"t":"應當歌頌居於錫安的耶和華，將他所做的傳揚在萬民中。","notes":[]},{"n":12,"t":"那位追討流人血的，他記念受屈的人，不忘記困苦人的哀求。","notes":[]},{"n":13,"t":"耶和華啊，求你憐憫我！你是從死門把我提升起來的，求你看那恨我的人所加給我的苦難，","notes":[]},{"n":14,"t":"好讓我述說你一切的美德。我要在錫安的城門因你的救恩歡樂。","notes":["「錫安」：原文直譯「錫安女子」。"]},{"n":15,"t":"外邦人陷在自己所掘的坑中，他們的腳被自己暗設的網羅纏住了。","notes":[]},{"n":16,"t":"耶和華已將自己顯明，他已施行審判；惡人被自己手所做的纏住了。（細拉）","notes":["「惡人...纏住了」或譯「他叫惡人被自己手所做的纏住了」。"]},{"n":17,"t":"惡人，就是忘記神的外邦人，都必歸到陰間。","notes":[]},{"n":18,"t":"貧窮人必不永久被忘，困苦人的指望必不永遠落空。","notes":[]},{"n":19,"t":"耶和華啊，求你興起，不容世人得勝！願外邦人在你面前受審判！","notes":[]},{"n":20,"t":"耶和華啊，求你使他們恐懼，願外邦人知道自己不過是人。（細拉）","notes":[]}]},"10":{"heading":"為公義而祈禱","verses":[{"n":1,"t":"耶和華啊，你為甚麼站在遠處？在患難的時候為甚麼隱藏？","notes":[]},{"n":2,"t":"惡人驕橫地追逼困苦人；願他們陷在自己所設的計謀裏。","notes":[]},{"n":3,"t":"因為惡人以自己的心願自誇，貪財的背棄耶和華，並且輕慢他。","notes":["「貪財的...輕慢他」或譯「他稱讚貪財的，卻輕慢耶和華」。"]},{"n":4,"t":"惡人面帶驕傲，不尋找耶和華；他的思想中全無神。","notes":[]},{"n":5,"t":"他的路時常亨通，你的審判不在他眼裏。至於他所有的敵人，他都向他們發怒氣。","notes":[]},{"n":6,"t":"他心裏說：「我必不動搖，世世代代不遭災難。」","notes":[]},{"n":7,"t":"他滿口咒罵、詭詐、欺壓，舌底盡是毒害、奸惡。","notes":[]},{"n":8,"t":"他在村莊埋伏等候，在隱密處殺害無辜的人，他的眼睛窺探無倚無靠的人。","notes":[]},{"n":9,"t":"他埋伏在暗地，如獅子蹲在洞中。他埋伏，要俘擄困苦人；他拉網，就把困苦人擄去。","notes":[]},{"n":10,"t":"他屈身蹲伏，無倚無靠的人就倒在他的暴力之下。","notes":[]},{"n":11,"t":"他心裏說：「神竟忘記了，神轉臉永不觀看。」","notes":[]},{"n":12,"t":"耶和華啊，求你興起！神啊，求你舉手！不要忘記困苦人！","notes":[]},{"n":13,"t":"惡人為何輕慢神，心裏說「你必不追究」？","notes":[]},{"n":14,"t":"你已經察看，顧念人的憂患和愁苦，放在你的手中。無倚無靠的人把自己交託給你，你向來是幫助孤兒的。","notes":[]},{"n":15,"t":"求你打斷惡人的膀臂，至於壞人，求你追究他的惡，直到淨盡。","notes":[]},{"n":16,"t":"耶和華永永遠遠為王，外邦人從他的地已經滅絕了。","notes":[]},{"n":17,"t":"耶和華啊，困苦人的心願你早已聽見；你必堅固他們的心，也必側耳聽他們的祈求，","notes":[]},{"n":18,"t":"為要給孤兒和受欺壓的人伸冤，使世上的人不再威嚇他們。","notes":[]}]},"11":{"heading":"在主裏得安穩","verses":[{"n":1,"t":"我投靠耶和華；你們怎麼對我說：「你當像鳥逃到你們的山去；","notes":[]},{"n":2,"t":"看哪，惡人彎弓，把箭搭在弦上，要在暗中射那心裏正直的人。","notes":[]},{"n":3,"t":"根基若毀壞，義人還能做甚麼呢？」","notes":[]},{"n":4,"t":"耶和華在他的聖殿裏，耶和華在天上的寶座上；他的眼睛察看，他的眼目察驗世人。","notes":["「眼目」：原文是「眼皮」。"]},{"n":5,"t":"耶和華考驗義人；惟有惡人和喜愛暴力的人，他心裏恨惡。","notes":[]},{"n":6,"t":"他要向惡人密佈羅網，烈火、硫磺、熱風作他們杯中的份。","notes":[]},{"n":7,"t":"因為耶和華是公義的，他喜愛義行，正直人必得見他的面。","notes":[]}]},"12":{"heading":"求助的祈禱","verses":[{"n":1,"t":"耶和華啊，求你幫助，因虔誠人斷絕了，世人中間忠信的人消失了。","notes":[]},{"n":2,"t":"人人向鄰舍說謊；他們說話嘴唇油滑，心口不一。","notes":[]},{"n":3,"t":"願耶和華剪除一切油滑的嘴唇，誇大的舌頭。","notes":[]},{"n":4,"t":"他們說：「我們必能以舌頭取勝，我們的嘴唇是自己的，誰能作我們的主呢？」","notes":[]},{"n":5,"t":"耶和華說：「因為困苦人的冤屈和貧窮人的嘆息，我現在要起來，把他安置在他所切慕的穩妥之地。」","notes":[]},{"n":6,"t":"耶和華的言語是純淨的言語，如同銀子在泥做的爐中煉過七次。","notes":[]},{"n":7,"t":"耶和華啊，你必保護他們，你必保佑他們永遠脫離這世代的人。","notes":[]},{"n":8,"t":"卑鄙的人在世人中高升時，就有惡人四處橫行。","notes":[]}]},"13":{"heading":"求耶和華看顧","verses":[{"n":1,"t":"耶和華啊，你忘記我要到幾時呢？要到永遠嗎？你轉臉不顧我要到幾時呢？","notes":[]},{"n":2,"t":"我心裏籌算，終日愁苦，要到幾時呢？我的仇敵升高壓制我，要到幾時呢？","notes":[]},{"n":3,"t":"耶和華－我的神啊，求你看顧我，應允我！求你使我眼目明亮，免得我沉睡至死；","notes":[]},{"n":4,"t":"免得我的仇敵說「我勝了他」；免得我的敵人在我動搖的時候喜樂。","notes":[]},{"n":5,"t":"但我倚靠你的慈愛，我的心因你的救恩快樂。","notes":[]},{"n":6,"t":"我要向耶和華歌唱，因他厚厚地恩待我。","notes":[]}]},"14":{"heading":"人的邪惡","verses":[{"n":1,"t":"愚頑人心裏說：「沒有神。」他們都敗壞，行了可憎惡的事，沒有一個人行善。","notes":[]},{"n":2,"t":"耶和華從天上垂看世人，要看有明白的沒有，有尋求神的沒有。","notes":[]},{"n":3,"t":"他們都偏離正路，一同變為污穢，沒有行善的，連一個也沒有。","notes":[]},{"n":4,"t":"作惡的都沒有知識嗎？他們吞吃我的百姓如同吃飯一樣，並不求告耶和華。","notes":[]},{"n":5,"t":"他們在那裏大大害怕，因為神在義人的族類中。","notes":[]},{"n":6,"t":"你們叫困苦人的籌算變為羞辱，然而耶和華是他的避難所。","notes":[]},{"n":7,"t":"但願以色列的救恩出自錫安。當耶和華救回他被擄子民的時候，雅各要快樂，以色列要歡喜。","notes":[]}]},"15":{"heading":"得居聖山者的品行","verses":[{"n":1,"t":"耶和華啊，誰能寄居你的帳幕？誰能居住你的聖山？","notes":[]},{"n":2,"t":"就是行為正直、做事公義、心裏說實話的人。","notes":[]},{"n":3,"t":"他不以舌頭讒害人，不惡待朋友，也不隨夥毀謗鄰舍。","notes":[]},{"n":4,"t":"他眼中藐視匪類，卻尊重那敬畏耶和華的人。他發了誓，雖然自己吃虧也不更改。","notes":[]},{"n":5,"t":"他不放債取利，不受賄賂以害無辜。做這些事的人必永不動搖。","notes":[]}]},"16":{"heading":"為信心穩固而祈禱","verses":[{"n":1,"t":"神啊，求你保佑我，因為我投靠你。","notes":[]},{"n":2,"t":"我曾對耶和華說：「你是我的主，我的福氣惟獨從你而來。」","notes":["「我」：有古卷是「你」。"]},{"n":3,"t":"論到世上的聖民，他們是尊貴的人，是我最喜悅的。","notes":[]},{"n":4,"t":"追逐別神的，他們的愁苦必增加；他們所澆奠的血我不獻上，我嘴唇也不提別神的名號。","notes":["「追逐」：原文另譯「選擇」。"]},{"n":5,"t":"耶和華是我的產業，是我杯中的福分；我所得的，你為我持守。","notes":[]},{"n":6,"t":"用繩量給我的地界，坐落在佳美之處；我的產業實在美好。","notes":[]},{"n":7,"t":"我要稱頌那指引我的耶和華，在夜間我的心腸也指教我。","notes":[]},{"n":8,"t":"我讓耶和華常在我面前，因他在我右邊，我就不致動搖。","notes":[]},{"n":9,"t":"因此，我的心歡喜，我的靈快樂；我的肉身也要安然居住。","notes":["「靈」：原文是「榮耀」。"]},{"n":10,"t":"因為你必不將我的靈魂撇在陰間，也不讓你的聖者見地府。","notes":["「我的靈魂」或譯「我」。","「地府」：七十士譯本是「朽壞」。"]},{"n":11,"t":"你必將生命的道路指示我。在你面前有滿足的喜樂，在你右手中有永遠的福樂。","notes":[]}]},"17":{"heading":"無辜的人的禱告","verses":[{"n":1,"t":"耶和華啊，求你垂聽公義的呼聲，留心聽我的呼求！求你側耳聽我這沒有詭詐的嘴唇的祈禱！","notes":[]},{"n":2,"t":"願判我公正的話從你面前發出，願你的眼睛察看正直。","notes":[]},{"n":3,"t":"你已經考驗我的心，你在夜間鑒察我。你熬煉我，卻找不到錯失，我立志叫我口中沒有過失。","notes":[]},{"n":4,"t":"論到人的行為，我謹守你嘴唇的言語，不走殘暴人的道路。","notes":[]},{"n":5,"t":"我的腳緊緊跟隨你的腳蹤，我的兩腳未曾滑跌。","notes":[]},{"n":6,"t":"神啊，我求告你，因為你必應允我；求你向我側耳，聽我的言語。","notes":[]},{"n":7,"t":"求你顯出你奇妙的慈愛，你用右手拯救投靠你的人，脫離那起來攻擊他們的人。","notes":[]},{"n":8,"t":"求你保護我，如同保護眼中的瞳人，把我隱藏在你翅膀的蔭下，","notes":[]},{"n":9,"t":"使我脫離欺壓我的惡人，脫離那圍困我要害我命的仇敵。","notes":[]},{"n":10,"t":"他們的心被油脂包裹，用口說驕傲的話。","notes":[]},{"n":11,"t":"他們追逼我，現在他們圍困了我們，瞪著眼，要把我們推倒在地。","notes":["「他們追逼我」：原文另譯「我們的腳步」。"]},{"n":12,"t":"他像獅子要貪吃獵物，又像少壯獅子蹲伏在暗處。","notes":[]},{"n":13,"t":"耶和華啊，求你興起，前去迎敵，把他打倒！求你用你的刀救我的命脫離惡人。","notes":[]},{"n":14,"t":"耶和華啊，求你用手救我脫離世人，脫離那只在今生有福分的世人！你以財寶充滿他們的肚腹，他們因有兒女就滿足，將其餘的財物留給他們的孩子。","notes":[]},{"n":15,"t":"至於我，我必因公正得見你的面；我醒了的時候，你的形像使我滿足。","notes":[]}]},"18":{"heading":"大衛的勝利之歌","verses":[{"n":1,"t":"耶和華我的力量啊，我愛你！","notes":[]},{"n":2,"t":"耶和華是我的巖石、我的山寨、我的救主、我的神、我的磐石、我所投靠的。他是我的盾牌，是拯救我的角，是我的碉堡。","notes":[]},{"n":3,"t":"我要求告當讚美的耶和華，我必從仇敵手中被救出來。","notes":[]},{"n":4,"t":"死亡的繩索勒住我，毀滅的急流驚嚇我，","notes":[]},{"n":5,"t":"陰間的繩索纏繞我，死亡的圈套臨到我。","notes":[]},{"n":6,"t":"我在急難中求告耶和華，向我的神呼求。他從殿中聽了我的聲音，我在他面前的呼求必進入他耳中。","notes":[]},{"n":7,"t":"那時，因他發怒地就震動戰抖，山的根基也震動挪移。","notes":[]},{"n":8,"t":"他的鼻孔冒煙上騰，他的口發火焚燒，連煤炭也燒著了。","notes":[]},{"n":9,"t":"他使天垂下，親自降臨，黑雲在他腳下。","notes":[]},{"n":10,"t":"他乘坐基路伯飛行，藉著風的翅膀快飛，","notes":[]},{"n":11,"t":"以黑暗為藏身之處，以水的黑暗、天空的密雲作四圍的行宮。","notes":[]},{"n":12,"t":"因他發出光輝，冰雹和火炭穿透密雲。","notes":[]},{"n":13,"t":"耶和華在天上打雷，至高者發出聲音，就有冰雹和火炭。","notes":["有古卷和七十士譯本沒有「就有冰雹和火炭」。"]},{"n":14,"t":"他射出箭來，使仇敵四散；發出連串的閃電，擊潰他們。","notes":[]},{"n":15,"t":"耶和華啊，你的斥責一發，你鼻孔的氣一出，海底就顯現，大地的根基也暴露。","notes":[]},{"n":16,"t":"他從高天伸手抓住我，把我從大水中拉上來。","notes":[]},{"n":17,"t":"他救我脫離強敵和那些恨我的人，因為他們比我強盛。","notes":[]},{"n":18,"t":"我遭遇災難的日子，他們來攻擊我；但耶和華是我的倚靠。","notes":[]},{"n":19,"t":"他領我到寬闊之處，他救拔我，因他喜愛我。","notes":[]},{"n":20,"t":"耶和華必按我的公義報答我，按我手中的清潔賞賜我。","notes":[]},{"n":21,"t":"因為我遵守耶和華的道，未曾作惡離開我的神。","notes":[]},{"n":22,"t":"他的一切典章常在我面前，他的律例我也未曾丟棄。","notes":[]},{"n":23,"t":"我在他面前作了完全人，我也保護自己遠離罪孽。","notes":[]},{"n":24,"t":"所以耶和華按我的公義，在他眼前按我手中的清潔賞賜我。","notes":[]},{"n":25,"t":"慈愛的人，你以慈愛待他；完全的人，你以完善待他。","notes":[]},{"n":26,"t":"清潔的人，你以清潔待他；歪曲的人，你以彎曲待他。","notes":[]},{"n":27,"t":"困苦的百姓，你必拯救；高傲的眼目，你使他降卑。","notes":[]},{"n":28,"t":"你必點亮我的燈；耶和華－我的神必照明我的黑暗。","notes":[]},{"n":29,"t":"我藉著你衝入敵軍，藉著我的神跳過城牆。","notes":[]},{"n":30,"t":"至於神，他的道是完全的；耶和華的話是純淨的。凡投靠他的，他就作他們的盾牌。","notes":[]},{"n":31,"t":"除了耶和華，誰是神呢？除了我們的神，誰是磐石呢？","notes":[]},{"n":32,"t":"惟有那以力量束我的腰、使我行為完全的，他是神。","notes":[]},{"n":33,"t":"他使我的腳快如母鹿，使我站穩在高處。","notes":[]},{"n":34,"t":"他教導我的手能爭戰，我的膀臂能開銅造的弓。","notes":[]},{"n":35,"t":"你賜救恩給我作盾牌，你的右手扶持我，你的庇護使我為大。","notes":["「庇護」或譯「溫和」。"]},{"n":36,"t":"你使我腳步寬闊，我的腳踝未曾滑跌。","notes":[]},{"n":37,"t":"我要追趕我的仇敵，且要追上他們；若不將他們滅絕，我總不歸回。","notes":[]},{"n":38,"t":"我要打傷他們，使他們站不起來；他們必倒在我的腳下。","notes":[]},{"n":39,"t":"你曾以力量束我的腰，使我能爭戰；也曾使那起來攻擊我的，都服在我以下。","notes":[]},{"n":40,"t":"你又使我的仇敵在我面前轉身逃跑，使我剪除那恨我的人。","notes":[]},{"n":41,"t":"他們呼求，卻無人拯救；就是呼求耶和華，他也不應允。","notes":[]},{"n":42,"t":"我搗碎他們，如同風前的灰塵；傾倒他們，如同街上的泥土。","notes":["「傾倒」：有古卷是「踐踏」。"]},{"n":43,"t":"你救我脫離百姓的紛爭，立我作列國的元首；我素不認識的百姓必事奉我。","notes":[]},{"n":44,"t":"他們一聽見我的名聲就必順從我，外邦人要投降我。","notes":[]},{"n":45,"t":"外邦人要喪膽，戰戰兢兢地出營寨。","notes":[]},{"n":46,"t":"耶和華永遠活著。願我的磐石被稱頌，願救我的神受尊崇。","notes":[]},{"n":47,"t":"這位神為我伸冤，使萬民服在我以下。","notes":[]},{"n":48,"t":"他拯救我脫離仇敵，又把我舉起，高過那些起來攻擊我的人，救我脫離殘暴的人。","notes":[]},{"n":49,"t":"耶和華啊，因此我要在外邦中稱謝你，歌頌你的名。","notes":[]},{"n":50,"t":"耶和華賜極大的救恩給他所立的王，施慈愛給他的受膏者，就是給大衛和他的後裔，直到永遠。","notes":[]}]},"19":{"heading":"造化的榮耀","verses":[{"n":1,"t":"諸天述說神的榮耀，穹蒼傳揚他手的作為。","notes":[]},{"n":2,"t":"這日到那日發出言語，這夜到那夜傳出知識。","notes":[]},{"n":3,"t":"無言無語，也無聲音可聽。","notes":[]},{"n":4,"t":"它們的聲浪傳遍天下，它們的言語傳到地極。神在其中為太陽安設帳幕，","notes":["「聲浪」：原文是「繩索」。"]},{"n":5,"t":"太陽如同新郎步出洞房，又如勇士歡然奔路。","notes":[]},{"n":6,"t":"它從天這邊出來，繞到天那邊，沒有一物可隱藏得不到它的熱氣。","notes":[]},{"n":7,"t":"耶和華的律法全備，使人甦醒；耶和華的法度確定，使愚蒙人有智慧。","notes":[],"heads":["耶和華的律法"]},{"n":8,"t":"耶和華的訓詞正直，使人心快活；耶和華的命令清潔，使人眼目明亮。","notes":[]},{"n":9,"t":"耶和華的典章真實，全然公義，敬畏耶和華是純潔的，存到永遠，","notes":[]},{"n":10,"t":"比金子可羨慕，比極多的純金可羨慕；比蜜甘甜，比蜂房下滴的蜜甘甜。","notes":[]},{"n":11,"t":"因此你的僕人受警戒，遵守這些有極大的賞賜。","notes":[]},{"n":12,"t":"誰能察覺自己的錯失呢？求你赦免我隱藏的過犯。","notes":[]},{"n":13,"t":"求你攔阻僕人不犯任意妄為的罪，不容這罪轄制我，我就完全，免犯大罪。","notes":[]},{"n":14,"t":"耶和華－我的磐石，我的救贖主啊，願我口中的言語，心裏的意念在你面前蒙悅納。","notes":[]}]},"20":{"heading":"祈求勝利","verses":[{"n":1,"t":"願耶和華在你患難的日子應允你，願雅各的神的名保護你。","notes":[]},{"n":2,"t":"願他從聖所救助你，從錫安堅固你，","notes":[]},{"n":3,"t":"記念你的一切祭物，悅納你的燔祭，（細拉）","notes":[]},{"n":4,"t":"將你心所願的賜給你，成就你的一切籌算。","notes":[]},{"n":5,"t":"我們要因你的救恩誇勝，要奉我們神的名豎立旌旗。願耶和華成就你一切所求的！","notes":[]},{"n":6,"t":"現在我知道耶和華必救護他的受膏者，從他神聖的天上應允他，用右手的能力救護他。","notes":[]},{"n":7,"t":"有人靠車，有人靠馬，但我們要提耶和華－我們神的名。","notes":[]},{"n":8,"t":"他們都屈身仆倒，我們卻起來，堅立不移。","notes":[]},{"n":9,"t":"耶和華啊，求你拯救；我們呼求的時候，願王應允我們！","notes":["本節七十士譯本是「主啊，求你拯救王；我們呼求你的那一天，求你應允我們！」"]}]},"21":{"heading":"為勝利而歌頌","verses":[{"n":1,"t":"耶和華啊，王必因你的能力歡喜；因你的救恩，他的快樂何其大！","notes":[]},{"n":2,"t":"他心裏所願的，你已經賜給他；他嘴唇所求的，你未嘗不應允。（細拉）","notes":[]},{"n":3,"t":"你以美善的福氣迎接他，把純金的冠冕戴在他頭上。","notes":[]},{"n":4,"t":"他向你祈求長壽，你就賜給他，就是日子長久，直到永遠。","notes":[]},{"n":5,"t":"他因你的救恩大有榮耀，你將尊榮威嚴加在他身上。","notes":[]},{"n":6,"t":"你使他有洪福，直到永遠，又使他在你面前歡喜快樂。","notes":[]},{"n":7,"t":"王倚靠耶和華，因至高者的慈愛，王必不動搖。","notes":[]},{"n":8,"t":"你的手要搜出所有的仇敵，你的右手要搜出那些恨你的人。","notes":[]},{"n":9,"t":"你的臉出現的時候，要使他們如在炎熱的火爐中。耶和華要在他的震怒中吞滅他們，那火要把他們燒盡。","notes":[]},{"n":10,"t":"你必從世上滅絕他們的幼苗，從人間滅絕他們的後裔。","notes":[]},{"n":11,"t":"因為他們有意加害於你；他們想出計謀，卻不能做成。","notes":[]},{"n":12,"t":"你必使他們轉身逃跑，向著他們的臉搭箭在弦。","notes":[]},{"n":13,"t":"耶和華啊，願你因自己的能力顯為至高！這樣，我們就唱詩，歌頌你的大能。","notes":[]}]},"22":{"heading":"痛苦中的禱告和讚美","verses":[{"n":1,"t":"我的神，我的神，為甚麼離棄我？為甚麼遠離不救我，不聽我的呻吟？","notes":[]},{"n":2,"t":"我的神啊，我白日呼求，你不應允；夜間呼求，也不得安寧。","notes":[]},{"n":3,"t":"但你是神聖的，用以色列的讚美為寶座。","notes":[]},{"n":4,"t":"我們的祖宗倚靠你；他們倚靠你，你解救他們。","notes":[]},{"n":5,"t":"他們哀求你，就蒙解救；他們倚靠你，就不羞愧。","notes":[]},{"n":6,"t":"但我是蟲，不是人，被眾人羞辱，被百姓藐視。","notes":[]},{"n":7,"t":"凡看見我的都嗤笑我；他們撇嘴搖頭：","notes":[]},{"n":8,"t":"「他把自己交託給耶和華，讓耶和華救他吧！耶和華既喜愛他，可以搭救他吧！」","notes":[]},{"n":9,"t":"但你是叫我出母腹的，我在母懷裏，你就使我有倚靠的心。","notes":[]},{"n":10,"t":"我自出母胎就交在你手裏，自我出母腹，你就是我的神。","notes":[]},{"n":11,"t":"求你不要遠離我！因為災難臨頭，無人幫助。","notes":[]},{"n":12,"t":"許多公牛環繞我，巴珊大力的公牛四面圍困我。","notes":[]},{"n":13,"t":"牠們向我張口，好像獵食吼叫的獅子。","notes":[]},{"n":14,"t":"我如水被倒出，我的骨頭都脫了節，我的心如蠟，在我裏面熔化。","notes":[]},{"n":15,"t":"我的精力枯乾，如同瓦片，我的舌頭緊貼上顎。你將我安置在死灰中。","notes":[]},{"n":16,"t":"犬類圍著我，惡黨環繞我；他們扎了我的手、我的腳。","notes":[]},{"n":17,"t":"我數遍我的骨頭；他們瞪著眼看我。","notes":[]},{"n":18,"t":"他們分我的外衣，為我的內衣抽籤。","notes":[]},{"n":19,"t":"耶和華啊，求你不要遠離我！我的救主啊，求你快來幫助我！","notes":[]},{"n":20,"t":"求你救我的性命脫離刀劍，使我僅有的脫離犬類，","notes":["「僅有的」就是「生命」。"]},{"n":21,"t":"求你救我脫離獅子的口；你已經應允我，使我脫離野牛的角。","notes":[]},{"n":22,"t":"我要將你的名傳給我的弟兄，在會眾中我要讚美你。","notes":[]},{"n":23,"t":"敬畏耶和華的人哪，要讚美他！雅各的後裔啊，要榮耀他！以色列的後裔啊，要懼怕他！","notes":[]},{"n":24,"t":"因為他沒有藐視、憎惡受苦的人，也沒有轉臉不顧他們；那受苦之人呼求的時候，他就垂聽。","notes":[]},{"n":25,"t":"我在大會中讚美你的話是從你而來，我要在敬畏耶和華的人面前還我的願。","notes":[]},{"n":26,"t":"願困苦的人吃得飽足，願尋求耶和華的人讚美他。願你們的心永遠活著！","notes":[]},{"n":27,"t":"地的四極都要想念耶和華，並且歸順他，列國的萬族都要在你面前敬拜。","notes":[]},{"n":28,"t":"因為國度屬於耶和華，他是管理列國的。","notes":[]},{"n":29,"t":"地上富足的人都必吃喝而敬拜，凡下到塵土中不能存活自己性命的人，都要在他面前下拜；","notes":["「凡...下拜」：原文另譯「凡下到塵土中的人都要在他面前下拜，我的性命為他而存活」。"]},{"n":30,"t":"必有後裔事奉他，主所做的事必傳給後代。","notes":[]},{"n":31,"t":"他們必來傳他的公義給尚未出生的子民，這是他的作為。","notes":[]}]},"23":{"heading":"耶和華是我牧者","verses":[{"n":1,"t":"耶和華是我的牧者，我必不致缺乏。","notes":[]},{"n":2,"t":"他使我躺臥在青草地上，領我在可安歇的水邊。","notes":[]},{"n":3,"t":"他使我的靈魂甦醒，為自己的名引導我走義路。","notes":["「他使我的靈魂甦醒」或譯「他使我的心靈甦醒」或「他使我回轉」。"]},{"n":4,"t":"我雖然行過死蔭的幽谷，也不怕遭害，因為你與我同在；你的杖、你的竿，都安慰我。","notes":[]},{"n":5,"t":"在我敵人面前，你為我擺設筵席；你用油膏了我的頭，使我的福杯滿溢。","notes":[]},{"n":6,"t":"我一生一世必有恩惠慈愛隨著我；我且要住在耶和華的殿中，直到永遠。","notes":["「住在」：原文是「回到」。"]}]},"24":{"heading":"偉大的君王","verses":[{"n":1,"t":"地和其中所充滿的，世界和住在其中的，都屬耶和華。","notes":[]},{"n":2,"t":"他把地建立在海上，安定在江河之上。","notes":[]},{"n":3,"t":"誰能登耶和華的山？誰能站在他的聖所？","notes":[]},{"n":4,"t":"就是手潔心清，意念不向虛妄，起誓不懷詭詐的人。","notes":[]},{"n":5,"t":"他必蒙耶和華賜福，又蒙救他的神使他成義。","notes":[]},{"n":6,"t":"這是尋求耶和華的族類，是尋求你面的雅各。（細拉）","notes":[]},{"n":7,"t":"眾城門哪，要抬起頭來！永久的門戶啊，你們要被舉起！榮耀的王將要進來！","notes":[]},{"n":8,"t":"這榮耀的王是誰呢？就是有力有能的耶和華，在戰場上大有能力的耶和華！","notes":[]},{"n":9,"t":"眾城門哪，要抬起頭來！永久的門戶啊，你們要高舉！榮耀的王將要進來！","notes":[]},{"n":10,"t":"這榮耀的王是誰呢？萬軍之耶和華是榮耀的王！（細拉）","notes":[]}]},"25":{"heading":"求主指引保護","verses":[{"n":1,"t":"耶和華啊，我的心仰望你。","notes":[]},{"n":2,"t":"我的神啊，我素來倚靠你；求你不要叫我羞愧，不要叫我的仇敵向我誇勝。","notes":[]},{"n":3,"t":"凡等候你的必不羞愧，惟有那無故行奸詐的必要羞愧。","notes":[]},{"n":4,"t":"耶和華啊，求你將你的道指示我，將你的路指教我！","notes":[]},{"n":5,"t":"求你指教我，引導我進入你的真理，因為你是救我的神。我整日等候你。","notes":[]},{"n":6,"t":"耶和華啊，求你記念你的憐憫和慈愛，因為這是亙古以來所常有的。","notes":[]},{"n":7,"t":"求你不要記得我幼年的罪愆和我的過犯；耶和華啊，求你因你的良善，按你的慈愛記念我。","notes":[]},{"n":8,"t":"耶和華是良善正直的，因此，他必教導罪人走正路。","notes":[]},{"n":9,"t":"他要按公平引領謙卑人，將他的道指教他們。","notes":[]},{"n":10,"t":"凡遵守他的約和他法度的人，耶和華都以慈愛信實待他。","notes":[]},{"n":11,"t":"耶和華啊，求你因你名的緣故赦免我的罪，因我的罪重大。","notes":[]},{"n":12,"t":"誰敬畏耶和華，耶和華必教導他當選擇的道路。","notes":[]},{"n":13,"t":"他要安然居住，他的後裔必承受土地。","notes":[]},{"n":14,"t":"耶和華與敬畏他的人親密，他要將自己的約指示他們。","notes":[]},{"n":15,"t":"我的眼目時常仰望耶和華，因他必將我的腳從網裏拉出來。","notes":[]},{"n":16,"t":"求你轉向我，憐憫我，因我孤獨困苦。","notes":[]},{"n":17,"t":"我心裏愁苦甚多，求你救我脫離我的禍患。","notes":[]},{"n":18,"t":"求你看顧我的困苦、我的艱難，赦免我一切的罪。","notes":[]},{"n":19,"t":"求你察看我的仇敵，因為他們人數眾多，並且痛恨我。","notes":[]},{"n":20,"t":"求你保護我的性命，搭救我，使我不致羞愧，因為我投靠你。","notes":[]},{"n":21,"t":"願純全、正直保護我，因為我等候你。","notes":[]},{"n":22,"t":"神啊，求你救贖以色列脫離他一切的愁苦。","notes":[]}]},"26":{"heading":"義人的祈禱","verses":[{"n":1,"t":"耶和華啊，求你為我伸冤，因我向來行事純正；我倚靠耶和華，必不動搖。","notes":[]},{"n":2,"t":"耶和華啊，求你察看我，考驗我，熬煉我的肺腑心腸。","notes":[]},{"n":3,"t":"因為你的慈愛常在我眼前，我也按你的真理而行。","notes":[]},{"n":4,"t":"我未曾與虛妄的人同坐，也不與偽善的人來往。","notes":[]},{"n":5,"t":"我痛恨惡人的集會，必不與惡人同坐。","notes":[]},{"n":6,"t":"耶和華啊，我要洗手表明無辜，才環繞你的祭壇；","notes":[]},{"n":7,"t":"我好發出稱謝的聲音，述說你一切奇妙的作為。","notes":[]},{"n":8,"t":"耶和華啊，我喜愛你所住的殿和你顯榮耀的居所。","notes":[]},{"n":9,"t":"不要把我的性命和罪人一同除掉，不要把我的生命和好流人血的一同除掉。","notes":[]},{"n":10,"t":"他們的手中有奸惡，他們的右手滿有賄賂。","notes":[]},{"n":11,"t":"至於我，卻要行事純正；求你救贖我，憐憫我！","notes":[]},{"n":12,"t":"我的腳站在平坦的地方，在聚會中我要稱頌耶和華！","notes":[]}]},"27":{"heading":"讚美的禱告","verses":[{"n":1,"t":"耶和華是我的亮光，是我的拯救，我還怕誰呢？耶和華是我生命的保障，我還懼誰呢？","notes":[]},{"n":2,"t":"那作惡的就是我的仇敵，前來吃我肉的時候就絆跌仆倒。","notes":[]},{"n":3,"t":"雖有軍隊安營攻擊我，我的心也不害怕；雖然興起戰爭攻擊我，我仍舊安穩。","notes":[]},{"n":4,"t":"有一件事，我曾求耶和華，我仍要尋求，就是一生一世住在耶和華的殿中，瞻仰他的榮美，在他的殿宇裏求問。","notes":[]},{"n":5,"t":"因為我遭遇患難，他必將我隱藏在他的帳棚裏，把我藏在他帳幕的隱密處，將我高舉在磐石上。","notes":[]},{"n":6,"t":"現在我得以昂首，高過四面的仇敵。我要在他的帳幕裏歡然獻祭，我要唱詩歌頌耶和華。","notes":[]},{"n":7,"t":"耶和華啊，我呼求的時候，求你垂聽我的聲音；求你憐憫我，應允我。","notes":[]},{"n":8,"t":"你說：「你們當尋求我的面。」那時我的心向你說：「耶和華啊，你的面我正要尋求。」","notes":[]},{"n":9,"t":"求你不要轉臉不顧我，不要發怒趕逐你的僕人，你向來是幫助我的。救我的神啊，不要離開我，也不要撇棄我。","notes":[]},{"n":10,"t":"即使我的父母撇棄我，耶和華終必收留我。","notes":[]},{"n":11,"t":"耶和華啊，求你將你的道指教我，因我仇敵的緣故引導我走平坦的路。","notes":[]},{"n":12,"t":"求你不要把我交給敵人，遂其所願；因為妄作見證的和口吐凶言的都起來攻擊我。","notes":[]},{"n":13,"t":"我深信在活人之地必得見耶和華的恩惠。","notes":[]},{"n":14,"t":"要等候耶和華，當壯膽，堅固你的心，要等候耶和華！","notes":[]}]},"28":{"heading":"求主幫助","verses":[{"n":1,"t":"耶和華啊，我要求告你！我的磐石啊，求你不要向我緘默！倘若你向我閉口，我就如下入地府的人一樣。","notes":[]},{"n":2,"t":"我呼求你，向你至聖所舉手的時候，求你垂聽我懇求的聲音！","notes":[]},{"n":3,"t":"不要把我和壞人並作惡的一同除掉；他們跟鄰舍說平安，心裏卻是奸惡。","notes":[]},{"n":4,"t":"求你按著他們所做的，按他們的惡行對待他們；求你照著他們手所做的對待他們，將他們應得的報應加給他們。","notes":[]},{"n":5,"t":"他們既然不尊重耶和華的作為，也不尊重他手所做的，耶和華就必毀壞他們，不建立他們。","notes":[]},{"n":6,"t":"耶和華是應當稱頌的，因為他聽了我懇求的聲音。","notes":[]},{"n":7,"t":"耶和華是我的力量，是我的盾牌，我心裏倚靠他就得幫助。我心中歡樂，我要用詩歌稱謝他。","notes":[]},{"n":8,"t":"耶和華是他百姓的力量，又是他受膏者得救的保障。","notes":[]},{"n":9,"t":"求你拯救你的百姓，賜福給你的產業；求你牧養他們，扶持他們，直到永遠。","notes":[]}]},"29":{"heading":"耶和華威嚴的聲音","verses":[{"n":1,"t":"神的子民哪，你們要將榮耀、能力歸給耶和華，都歸給耶和華！","notes":["「神的子民」或譯「強有力的」或「諸神」。"]},{"n":2,"t":"要將耶和華的名的榮耀歸給他，要敬拜神聖榮耀的耶和華。","notes":["「要敬拜...耶和華」或譯「以聖潔的妝飾敬拜耶和華」。"]},{"n":3,"t":"耶和華的聲音在眾水上，榮耀的神打雷；耶和華打雷在大水之上。","notes":[]},{"n":4,"t":"耶和華的聲音大有能力，耶和華的聲音滿有威嚴。","notes":[]},{"n":5,"t":"耶和華的聲音震碎香柏樹，耶和華震碎黎巴嫩的香柏樹。","notes":[]},{"n":6,"t":"他使黎巴嫩跳躍如牛犢，使西連跳躍如野牛犢。","notes":[]},{"n":7,"t":"耶和華的聲音使火焰分岔。","notes":[]},{"n":8,"t":"耶和華的聲音震動曠野，耶和華震動加低斯的曠野。","notes":[]},{"n":9,"t":"耶和華的聲音驚動母鹿落胎，樹林也脫落淨光。凡在他殿中的，都述說他的榮耀。","notes":[]},{"n":10,"t":"耶和華坐在洪水之上為王；耶和華坐著為王，直到永遠。","notes":[]},{"n":11,"t":"耶和華必賜力量給他的百姓，耶和華必賜平安的福給他的百姓。","notes":[]}]},"30":{"heading":"感恩的禱告","verses":[{"n":1,"t":"耶和華啊，我要尊崇你，因為你救了我，不讓仇敵向我誇耀。","notes":[]},{"n":2,"t":"耶和華－我的神啊，我呼求你，你醫治了我。","notes":[]},{"n":3,"t":"耶和華啊，你救我的性命脫離陰間，使我存活，不至於下入地府。","notes":[]},{"n":4,"t":"耶和華的聖民哪，你們要歌頌他，要頌揚他神聖的名字。","notes":["「名字」：原文是「紀念」。"]},{"n":5,"t":"因為，他的怒氣不過是轉眼之間，他的恩典乃是一生之久；一宿雖然有哭泣，早晨便必歡呼。","notes":[]},{"n":6,"t":"至於我，我凡事順利，就說：「我永不動搖。」","notes":[]},{"n":7,"t":"耶和華啊，你曾施恩，使我穩固如山；你轉臉不顧，我就驚惶。","notes":[]},{"n":8,"t":"耶和華啊，我曾求告你；我向耶和華懇求：","notes":[]},{"n":9,"t":"「我被害流血，下到地府，有何益處呢？塵土豈能稱謝你、傳揚你的信實嗎？","notes":[]},{"n":10,"t":"耶和華啊，求你應允我，憐憫我！耶和華啊，求你幫助我！」","notes":[]},{"n":11,"t":"你將我的哀哭變為跳舞，脫去我的麻衣，為我披上喜樂，","notes":[]},{"n":12,"t":"使我的靈歌頌你，不致緘默。耶和華－我的神啊，我要稱謝你，直到永遠！","notes":["「靈」：原文是「榮耀」。"]}]},"31":{"heading":"信靠神的祈禱","verses":[{"n":1,"t":"耶和華啊，我投靠你，求你使我永不羞愧，憑你的公義搭救我！","notes":[]},{"n":2,"t":"求你側耳聽我，快快救我！求你作我堅固的磐石，拯救我的保障！","notes":[]},{"n":3,"t":"你真是我的巖石、我的山寨，求你為你名的緣故引導我，指教我。","notes":[]},{"n":4,"t":"求你救我脫離人為我暗設的網羅，因為你是我的保障。","notes":[]},{"n":5,"t":"我將我的靈交在你手裏；耶和華─信實的神啊，你救贖了我。","notes":[]},{"n":6,"t":"我恨惡那信奉虛無神明的人；我卻倚靠耶和華。","notes":["「我」：有古卷、七十士譯本和其他古譯本是「你」。","「虛無神明」：原文是「虛無」。"]},{"n":7,"t":"我要因你的慈愛歡喜快樂，因為你見過我的困苦，知道我心中的艱難。","notes":[]},{"n":8,"t":"你未曾把我交在仇敵手裏，你使我的腳站在寬闊的地方。","notes":[]},{"n":9,"t":"耶和華啊，求你憐憫我，因為我在急難之中；我的眼睛因憂愁而昏花，我的身心也已耗盡。","notes":[]},{"n":10,"t":"我的生命為愁苦所消耗，我的年歲為嘆息所荒廢；我的力量因我的罪孽衰敗，我的骨頭也枯乾。","notes":["「罪孽」：原文另譯「苦難」。"]},{"n":11,"t":"我因所有的敵人成了羞辱，在我鄰舍跟前更加羞辱；那認識我的都懼怕我，在街上看見我的都躲避我。","notes":[]},{"n":12,"t":"我被遺忘，如同死人，無人記念；我好像破碎的器皿。","notes":[]},{"n":13,"t":"我聽見許多人的毀謗，四圍盡是驚嚇；他們一同商議攻擊我，圖謀害我的性命。","notes":[]},{"n":14,"t":"耶和華啊，我仍要倚靠你；我說：「你是我的神。」","notes":[]},{"n":15,"t":"我終生的事在你手中，求你救我脫離仇敵的手和那些迫害我的人。","notes":[]},{"n":16,"t":"求你使你的臉向僕人發光，憑你的慈愛拯救我。","notes":[]},{"n":17,"t":"耶和華啊，求你叫我不致羞愧，因為我曾呼求你；求你使惡人羞愧，使他們在陰間緘默無聲。","notes":[]},{"n":18,"t":"那撒謊的人逞驕傲輕慢，出狂妄的話攻擊義人，願他的嘴啞而無言。","notes":[]},{"n":19,"t":"在世人眼前，你為敬畏你的人所積存的，為投靠你的人所施行的，是何等大的恩惠啊！","notes":[]},{"n":20,"t":"你必將他們藏在你面前的隱密處，免得遭人暗算；你要隱藏他們在棚子裏，免受口舌的爭鬧。","notes":[]},{"n":21,"t":"耶和華是應當稱頌的，因為我在圍城裏，他向我施展奇妙的慈愛。","notes":[]},{"n":22,"t":"至於我，我曾驚惶地說：「我從你眼前被隔絕。」然而，我呼求你的時候，你仍聽我懇求的聲音。","notes":[]},{"n":23,"t":"耶和華的聖民哪，你們都要愛他！耶和華保護誠實可靠的人，卻加倍報應行事驕傲的人。","notes":[]},{"n":24,"t":"凡仰望耶和華的人，你們都要壯膽，堅固你們的心！","notes":[]}]},"32":{"heading":"認罪與蒙赦","verses":[{"n":1,"t":"過犯得赦免，罪惡蒙遮蓋的人有福了！","notes":[]},{"n":2,"t":"耶和華不算為有罪，內心沒有詭詐的人有福了！","notes":[]},{"n":3,"t":"我閉口不認罪的時候，因終日呻吟而骨頭枯乾。","notes":[]},{"n":4,"t":"黑夜白日，你的手壓在我身上沉重；我的精力耗盡，如同夏天的乾旱。（細拉）","notes":["「我的精力耗盡」：有古卷是「田中的殘梗枯乾」。"]},{"n":5,"t":"我向你陳明我的罪，不隱瞞我的惡。我說：「我要向耶和華承認我的過犯」；你就赦免我的罪惡。（細拉）","notes":[]},{"n":6,"t":"為此，凡虔誠人都當趁你可尋找的時候向你禱告；大水氾濫的時候，必不臨到他。","notes":["「趁你可尋找」：原文另譯「在患難」。"]},{"n":7,"t":"你是我藏身之處，你必保佑我脫離苦難，以得救的歡呼四面環繞我。（細拉）","notes":["「得救的歡呼」：原文另譯「得救」。"]},{"n":8,"t":"我要教導你，指示你當行的路，我要定睛在你身上勸戒你。","notes":[]},{"n":9,"t":"你不可像那無知的騾馬，須用嚼環韁繩勒住，不然，牠就不會靠近你。","notes":[]},{"n":10,"t":"惡人必多受苦楚；惟獨倚靠耶和華的，必有慈愛四面環繞他。","notes":[]},{"n":11,"t":"義人哪，你們應當靠耶和華歡喜快樂，心裏正直的人哪，你們都當歡呼。","notes":[]}]},"33":{"heading":"頌讚之歌","verses":[{"n":1,"t":"義人哪，你們當因耶和華歡呼，正直人理當讚美耶和華。","notes":[]},{"n":2,"t":"你們要彈琴稱謝耶和華，用十弦瑟歌頌他。","notes":[]},{"n":3,"t":"應當向他唱新歌，彈得巧妙，聲音洪亮。","notes":[]},{"n":4,"t":"因為耶和華的言語正直，他的作為盡都信實。","notes":[]},{"n":5,"t":"他喜愛公義和公平，遍地滿了耶和華的慈愛。","notes":[]},{"n":6,"t":"諸天藉耶和華的話而造，萬象藉他口中的氣而成。","notes":[]},{"n":7,"t":"他聚集海水如壘，收藏深洋在倉庫。","notes":[]},{"n":8,"t":"願全地都敬畏耶和華！願世上的居民都懼怕他！","notes":[]},{"n":9,"t":"因為他說有，就有，命立，就立。","notes":[]},{"n":10,"t":"耶和華使列國的籌算歸於無有，使萬民的計謀全無功效。","notes":[]},{"n":11,"t":"耶和華的籌算永遠立定，他心中的計劃萬代長存。","notes":[]},{"n":12,"t":"以耶和華為神的，那國有福了！耶和華揀選為自己產業的，那民有福了！","notes":[]},{"n":13,"t":"耶和華從天上觀看，看見所有的人，","notes":[]},{"n":14,"t":"從他的居所察看地上每一個居民，","notes":[]},{"n":15,"t":"他塑造他們的心，洞察他們一切的作為。","notes":[]},{"n":16,"t":"君王不能因兵多得勝，勇士不能因力大得救。","notes":[]},{"n":17,"t":"靠馬得救是枉然的，馬也不能因力大救人。","notes":[]},{"n":18,"t":"看哪，耶和華的眼目看顧敬畏他的人和仰望他慈愛的人，","notes":[]},{"n":19,"t":"要救他們的性命脫離死亡，使他們在饑荒中存活。","notes":[]},{"n":20,"t":"我們的心向來等候耶和華；他是我們的幫助，是我們的盾牌。","notes":[]},{"n":21,"t":"我們的心必靠他歡喜，因為我們向來倚靠他的聖名。","notes":[]},{"n":22,"t":"耶和華啊，求你照著我們所仰望你的，向我們施行慈愛！","notes":[]}]},"34":{"heading":"頌讚神的美善","verses":[{"n":1,"t":"我要時時稱頌耶和華，讚美他的話常在我口中。","notes":[]},{"n":2,"t":"我的心必因耶和華誇耀，謙卑的人聽見就喜樂。","notes":[]},{"n":3,"t":"你們要和我一同尊耶和華為大，讓我們一同高舉他的名。","notes":[]},{"n":4,"t":"我曾尋求耶和華，他就應允我，救我脫離一切的恐懼。","notes":[]},{"n":5,"t":"仰望他的人，就有光榮；他們的臉必不蒙羞。","notes":["「他們」：七十士譯本和其他古譯本是「你們」。"]},{"n":6,"t":"這困苦人呼求，耶和華就垂聽，救他脫離一切的患難。","notes":[]},{"n":7,"t":"耶和華的使者在敬畏他的人四圍安營，要搭救他們。","notes":[]},{"n":8,"t":"你們要嘗嘗主恩的滋味，便知道他是美善；投靠他的人有福了！","notes":[]},{"n":9,"t":"耶和華的聖民哪，你們當敬畏他，因敬畏他的一無所缺。","notes":[]},{"n":10,"t":"少壯獅子尚且缺食忍餓，但尋求耶和華的甚麼好處都不缺。","notes":[]},{"n":11,"t":"孩子們哪，來聽我！我要將敬畏耶和華的道教導你們。","notes":[]},{"n":12,"t":"有誰喜愛生命，愛慕長壽，得享美福？","notes":[]},{"n":13,"t":"你要禁止舌頭不出惡言，嘴唇不說詭詐的話。","notes":[]},{"n":14,"t":"要棄惡行善，尋求和睦，一心追求。","notes":[]},{"n":15,"t":"耶和華的眼目看顧義人，他的耳朵聽他們的呼求。","notes":[]},{"n":16,"t":"耶和華向行惡的人變臉，要從地上除滅他們的名字。","notes":["「名字」：原文是「紀念」。"]},{"n":17,"t":"義人呼求，耶和華聽見了，就拯救他們脫離一切患難。","notes":[]},{"n":18,"t":"耶和華靠近傷心的人，拯救心靈痛悔的人。","notes":[]},{"n":19,"t":"義人多有苦難，但耶和華救他脫離這一切，","notes":[]},{"n":20,"t":"又保護他全身的骨頭，連一根也不折斷。","notes":[]},{"n":21,"t":"惡必害死惡人，恨惡義人的，必被定罪。","notes":[]},{"n":22,"t":"耶和華救贖他僕人的性命，凡投靠他的，必不致定罪。","notes":[]}]},"35":{"heading":"求助的禱告","verses":[{"n":1,"t":"耶和華啊，與我相爭的，求你與他們相爭！與我爭戰的，求你與他們爭戰！","notes":[]},{"n":2,"t":"求你拿著大小盾牌，起來幫助我；","notes":[]},{"n":3,"t":"舉起槍來，抵擋那追趕我的。求你對我說：「我是拯救你的。」","notes":[]},{"n":4,"t":"願那尋索我命的，蒙羞受辱！願那謀害我的，退後羞愧！","notes":[]},{"n":5,"t":"願他們像風前的糠秕，有耶和華的使者趕逐他們。","notes":[]},{"n":6,"t":"願他們的道路又暗又滑，有耶和華的使者追趕他們。","notes":[]},{"n":7,"t":"因他們無故為我暗設網羅，無故挖坑，要害我的命。","notes":[]},{"n":8,"t":"願災禍忽然臨到他身上！願他暗設的網羅纏住自己！願他落在其中遭災禍！","notes":[]},{"n":9,"t":"我的心必靠耶和華快樂，靠他的救恩歡喜。","notes":[]},{"n":10,"t":"我全身的骨頭要說：「耶和華啊，誰能像你救護困苦人脫離那比他強壯的，救護困苦貧窮人脫離那搶奪他的？」","notes":[]},{"n":11,"t":"兇惡的見證人起來，盤問我所不知道的事。","notes":[]},{"n":12,"t":"他們向我以惡報善，使我喪失兒子。","notes":[]},{"n":13,"t":"至於我，他們有病的時候，我穿麻衣，禁食，刻苦己心；我所求的都歸到自己身上。","notes":[]},{"n":14,"t":"我如此行，好像他是我的朋友，我的兄弟；我屈身悲哀，如同哀悼自己的母親。","notes":[]},{"n":15,"t":"我在患難中，他們卻歡喜，大家聚集，我所不認識的卑賤人聚集攻擊我，他們不住地撕裂我。","notes":["「卑賤人」或譯「被擊打的人」；原文另譯「外邦人」。"]},{"n":16,"t":"他們試探我，不斷嘲笑我，向我咬牙切齒。","notes":["「他們...嘲笑我」是根據七十士譯本；原文另譯「他們如同席上好嬉笑的狂妄人」。"]},{"n":17,"t":"主啊，你看著不理要到幾時呢？求你救我的性命脫離他們的殘害，救我僅有的脫離少壯獅子！","notes":["「僅有的」就是「生命」。"]},{"n":18,"t":"我在大會中要稱謝你，在許多百姓中要讚美你。","notes":[]},{"n":19,"t":"求你不容那無理與我為仇的向我誇耀！不容那無故恨我的向我瞪眼！","notes":[]},{"n":20,"t":"因為他們不說平安，倒想出詭詐的言語擾害地上安靜的人。","notes":[]},{"n":21,"t":"他們大大張口攻擊我，說：「啊哈，啊哈，我們已經親眼看見了！」","notes":[]},{"n":22,"t":"耶和華啊，你已經看見了，求你不要沉默！主啊，求你不要遠離我！","notes":[]},{"n":23,"t":"我的神─我的主啊，求你醒來，求你奮起，還我公正，伸明我冤！","notes":[]},{"n":24,"t":"耶和華－我的神啊，求你按你的公義判斷我，不容他們向我誇耀！","notes":[]},{"n":25,"t":"不容他們心裏說：「啊哈，遂我們的心願了！」不容他們說：「我們已經把他吞了！」","notes":[]},{"n":26,"t":"願那喜歡我遭難的一同抱愧蒙羞！願那向我妄自尊大的披戴慚愧，蒙受羞辱！","notes":[]},{"n":27,"t":"願那喜悅我被判為義的歡呼快樂；願他們常說：「當尊耶和華為大！耶和華喜悅他的僕人平安。」","notes":["「被判為義」或譯「冤屈得伸」。"]},{"n":28,"t":"我的舌頭要論說你的公義，要常常讚美你。","notes":[]}]},"36":{"heading":"人的邪惡","verses":[{"n":1,"t":"過犯在惡人的心底向他說話，他的眼中不怕神。","notes":["「過犯...說話」是根據一些古卷和七十士譯本；原文是「過犯在我的心底向惡人說話」。"]},{"n":2,"t":"他自誇自媚，以致罪孽無法察覺，不被恨惡。","notes":[]},{"n":3,"t":"他口中的言語盡是罪孽詭詐，他不再有智慧，也不再行善。","notes":[]},{"n":4,"t":"他在床上圖謀罪孽，定意行不善的道，不憎惡惡事。","notes":[]},{"n":5,"t":"耶和華啊，你的慈愛上及諸天，你的信實達到穹蒼，","notes":[],"heads":["神的良善"]},{"n":6,"t":"你的公義好像高山，你的判斷如同深淵；耶和華啊，人民、牲畜，你都救護。","notes":[]},{"n":7,"t":"神啊，你的慈愛何其寶貴！世人投靠在你翅膀的蔭下。","notes":[]},{"n":8,"t":"他們必因你殿裏的豐盛得以飽足，你也必叫他們喝你那喜樂的泉水。","notes":[]},{"n":9,"t":"因為在你那裏有生命的泉源，在你的光中，我們必得見光。","notes":[]},{"n":10,"t":"願你常施慈愛給認識你的人，常以公義待心裏正直的人。","notes":[]},{"n":11,"t":"不容驕傲人的腳踐踏我，不容兇惡人的手趕逐我。","notes":[]},{"n":12,"t":"在那裏，作惡的人已經仆倒；他們被推倒，不能再起來。","notes":[]}]},"37":{"heading":"義人和惡人的結局","verses":[{"n":1,"t":"不要為作惡的心懷不平，也不要嫉妒那行不義的人。","notes":[]},{"n":2,"t":"因為他們如草快被割下，又如綠色的嫩草快要枯乾。","notes":[]},{"n":3,"t":"你當倚靠耶和華而行善，安居地上，以他的信實為糧；","notes":[]},{"n":4,"t":"又當以耶和華為樂，他就將你心裏所求的賜給你。","notes":[]},{"n":5,"t":"當將你的道路交託耶和華，並倚靠他，他就必成全。","notes":[]},{"n":6,"t":"他要使你的公義如光發出，使你的公平明如正午。","notes":[]},{"n":7,"t":"你當安心倚靠耶和華，耐性等候他，不要因那道路通達的和那惡謀成就的心懷不平。","notes":[]},{"n":8,"t":"當止住怒氣，離棄憤怒；不要心懷不平，以致作惡。","notes":[]},{"n":9,"t":"因為作惡的必被剪除；惟有等候耶和華的必承受土地。","notes":[]},{"n":10,"t":"還有片時，惡人要歸於無有；你就是細察他的住處，也不存在。","notes":[]},{"n":11,"t":"但謙卑的人必承受土地，以豐盛的平安為樂。","notes":[]},{"n":12,"t":"惡人設謀要害義人，向他咬牙。","notes":[]},{"n":13,"t":"但主必笑他，因見他受罰的日子將要來到。","notes":[]},{"n":14,"t":"惡人刀已出鞘，弓已上弦，要砍倒困苦貧窮的人，要殺害行為正直的人。","notes":[]},{"n":15,"t":"他們的刀必刺入自己的心，他們的弓必折斷。","notes":[]},{"n":16,"t":"一個義人所有的雖少，強過許多惡人的富餘。","notes":[]},{"n":17,"t":"因為惡人的膀臂必折斷；但耶和華扶持義人。","notes":[]},{"n":18,"t":"耶和華知道完全人的日子，他們的產業要存到永遠。","notes":[]},{"n":19,"t":"他們在患難的時候必不致羞愧，在饑荒的日子必得飽足。","notes":[]},{"n":20,"t":"惡人卻要滅亡。耶和華的仇敵要像草地的華美；他們要毀滅，在煙中消失。","notes":["「草地的華美」或譯「羔羊的油脂」。","「在煙中消失」：七十士譯本是「要如煙消滅」。"]},{"n":21,"t":"惡人借貸卻不償還；義人恩待人，並且施捨。","notes":[]},{"n":22,"t":"蒙耶和華賜福的必承受土地；他所詛咒的必被剪除。","notes":[]},{"n":23,"t":"義人的腳步為耶和華所穩定；他的道路，耶和華也喜愛。","notes":[]},{"n":24,"t":"他雖失腳也不致全身仆倒，因為耶和華攙扶他的手。","notes":[]},{"n":25,"t":"我從前年幼，現在年老，卻未見過義人被棄，也未見過他的後裔求乞。","notes":[]},{"n":26,"t":"他常常恩待人，借貸給人，他的後裔也必蒙福。","notes":[]},{"n":27,"t":"你當離惡行善，就可永遠安居。","notes":[]},{"n":28,"t":"因為耶和華喜愛公平，不撇棄他的聖民，他們永蒙保佑；但惡人的後裔必被剪除。","notes":[]},{"n":29,"t":"義人必承受土地，永居其上。","notes":[]},{"n":30,"t":"義人的口發出智慧，他的舌頭講說公平。","notes":[]},{"n":31,"t":"神的律法在他心裏，他的步伐總不搖動。","notes":[]},{"n":32,"t":"惡人窺探義人，想要殺他。","notes":[]},{"n":33,"t":"耶和華必不把他交在惡人手中，當審判的時候，也不定他的罪。","notes":[]},{"n":34,"t":"你當等候耶和華，遵守他的道，他就抬舉你，使你承受土地；你必看到惡人被剪除。","notes":[]},{"n":35,"t":"我見過惡人大有勢力，高聳如本地青翠的樹木。","notes":[]},{"n":36,"t":"有人從那裏經過，看哪，他已不存在，我尋找他，卻尋不著了。","notes":["「有人」：七十士譯本和其他古譯本是「我」。"]},{"n":37,"t":"你要細察那完全人，觀看那正直人，因為和平的人有好結局。","notes":[]},{"n":38,"t":"至於罪人，必一同滅絕，惡人的結局必被剪除。","notes":[]},{"n":39,"t":"義人得救是出於耶和華，在患難時耶和華作他們的避難所。","notes":[]},{"n":40,"t":"耶和華幫助他們，解救他們；他解救他們脫離惡人，把他們救出來，因為他們投靠他。","notes":[]}]},"38":{"heading":"受苦者的祈禱","verses":[{"n":1,"t":"耶和華啊，求你不要在怒中責備我，不要在烈怒中懲罰我！","notes":[]},{"n":2,"t":"因為你的箭射入我身，你的手壓住我。","notes":[]},{"n":3,"t":"因你的惱怒，我的肉無一完全；因我的罪過，我的骨頭也不安寧。","notes":[]},{"n":4,"t":"我的罪孽高過我的頭，如同重擔叫我擔當不起。","notes":[]},{"n":5,"t":"因我的愚昧，我的傷發臭流膿。","notes":[]},{"n":6,"t":"我疼痛，大大蜷曲，整日哀痛。","notes":[]},{"n":7,"t":"我滿腰灼熱，我的肉無一完全。","notes":[]},{"n":8,"t":"我被壓碎，身心虛弱；因心裏痛苦，我就呻吟。","notes":[]},{"n":9,"t":"主啊，我的心願都在你面前，我的嘆息不向你隱瞞。","notes":[]},{"n":10,"t":"我心顫慄，體力衰微，眼中無光。","notes":[]},{"n":11,"t":"我遭遇災病，良朋密友都袖手旁觀，我的親戚本家也遠遠站立。","notes":[]},{"n":12,"t":"那尋索我命的設下羅網，那想要害我的口出惡言，整日思想詭計。","notes":[]},{"n":13,"t":"但我如聾子聽不見，像啞巴不能開口。","notes":[]},{"n":14,"t":"我如聽不見的人，無法用口答辯。","notes":[]},{"n":15,"t":"耶和華啊，我仰望你！主－我的神啊，你必應允我！","notes":[]},{"n":16,"t":"我曾說：「恐怕他們向我誇耀，我失腳的時候，他們向我誇口。」","notes":[]},{"n":17,"t":"我就要跌倒，我的痛苦常在我面前。","notes":[]},{"n":18,"t":"我要承認我的罪孽，要因我的罪憂愁。","notes":[]},{"n":19,"t":"但我的仇敵又活潑又強壯，無理恨我的增多了。","notes":[]},{"n":20,"t":"以惡報善的與我作對，但我追求良善。","notes":[]},{"n":21,"t":"耶和華啊，求你不要撇棄我！我的神啊，求你不要遠離我！","notes":[]},{"n":22,"t":"拯救我的主啊，求你快快幫助我！","notes":[]}]},"39":{"heading":"受苦者的認罪","verses":[{"n":1,"t":"我曾說：「我要謹慎我的言行，免得我的舌頭犯罪；惡人在我面前的時候，我要用嚼環勒住我的口。」","notes":[]},{"n":2,"t":"我默然無聲，連好話也不出口，我的愁苦就更加深。","notes":[]},{"n":3,"t":"我的心在我裏面發熱；我默想的時候，火就燒起，我用舌頭說話：","notes":[]},{"n":4,"t":"「耶和華啊，求你讓我曉得我的結局，我的壽數幾何，使我知道我的生命何等短暫！","notes":[]},{"n":5,"t":"看哪，你使我的年日窄如手掌，我一生的年數，在你面前如同無有；各人最穩妥的時候，真是全然虛幻。（細拉）","notes":[]},{"n":6,"t":"世人行動實係幻影，他們忙亂，真是枉然，積蓄財寶，不知將來有誰收取。","notes":[]},{"n":7,"t":"「主啊，如今我等甚麼呢？我的指望在乎你！","notes":[]},{"n":8,"t":"求你救我脫離一切的過犯，不要使我受愚頑人的羞辱。","notes":[]},{"n":9,"t":"我保持沉默，閉口不言，因為這一切都是你所做的。","notes":[]},{"n":10,"t":"求你從我身上免去你的責罰；因你手的責打，我就消滅。","notes":[]},{"n":11,"t":"因人的罪惡你懲罰管教他的時候，如蛀蟲一般，吃掉他所喜愛的。世人真是虛幻！（細拉）","notes":[]},{"n":12,"t":"「耶和華啊，求你聽我的禱告，側耳聽我的呼求！我流淚，求你不要靜默無聲！因為在你面前我是客旅，是寄居的，像我列祖一般。","notes":[]},{"n":13,"t":"求你寬容我，使我在去而不返之先可以喜樂。」","notes":[]}]},"40":{"heading":"頌讚之歌","verses":[{"n":1,"t":"我曾耐性等候耶和華，他垂聽我的呼求。","notes":[]},{"n":2,"t":"他從泥坑裏，從淤泥中，把我拉上來，使我的腳立在磐石上，使我腳步穩健。","notes":[]},{"n":3,"t":"他使我口唱新歌，就是讚美我們神的話。許多人必看見而懼怕，並要倚靠耶和華。","notes":[]},{"n":4,"t":"那倚靠耶和華、不理會狂傲和偏向虛假的，這人有福了！","notes":[]},{"n":5,"t":"耶和華－我的神啊，你所行的奇事和你為我們設想的計劃，多到無法盡述；若要述說陳明，不可勝數。","notes":[]},{"n":6,"t":"祭物和禮物，你不喜愛，你已經開通我的耳朵；燔祭和贖罪祭非你所要。","notes":[]},{"n":7,"t":"那時我說：「看哪，我來了！我的事在經卷上已經記載了。","notes":[]},{"n":8,"t":"我的神啊，我樂意照你的旨意行，你的律法在我心裏。」","notes":[]},{"n":9,"t":"我在大會中傳講公義的佳音，看哪，必不制止我的嘴唇；耶和華啊，這一切你都知道。","notes":[]},{"n":10,"t":"我未曾把你的公義藏在心裏，我已陳明你的信實和你的救恩；在大會中我未曾隱瞞你的慈愛和信實。","notes":[]},{"n":11,"t":"耶和華啊，求你不要向我止住你的憐憫！願你的慈愛和信實常常保佑我！","notes":[]},{"n":12,"t":"因有無數的禍患圍困我，我的罪孽追上了我，使我不能看見，這罪孽比我的頭髮還多，我的膽量喪失了。","notes":[],"heads":["求助的禱告"]},{"n":13,"t":"耶和華啊，求你開恩搭救我！耶和華啊，求你速速幫助我！","notes":[]},{"n":14,"t":"願那些尋找我、要滅我命的，一同抱愧蒙羞！願那些喜悅我遭害的，退後受辱！","notes":[]},{"n":15,"t":"願那些對我說「啊哈、啊哈」的，因羞愧而敗亡！","notes":[]},{"n":16,"t":"願一切尋求你的，因你歡喜快樂！願那些喜愛你救恩的，常說：「當尊耶和華為大！」","notes":[]},{"n":17,"t":"我本是困苦貧窮的，主卻顧念我。你是幫助我的，搭救我的；我的神啊，求你不要耽延！","notes":[]}]},"41":{"heading":"病中祈禱","verses":[{"n":1,"t":"眷顧貧寒人的有福了！在患難的日子，耶和華必搭救他。","notes":["「有福了」：原文另譯「他要賜福給他」。"]},{"n":2,"t":"耶和華必保全他，使他存活，他要在地上享福。求你不要把他交給仇敵，遂其所願。","notes":[]},{"n":3,"t":"他病重在榻，耶和華必扶持他；他在病中，你必使他離開病床。","notes":[]},{"n":4,"t":"我曾說：「耶和華啊，求你憐憫我，醫治我，因為我得罪了你。」","notes":[]},{"n":5,"t":"我的仇敵用惡言議論我：「他幾時才會死，他的名幾時才會消滅呢？」","notes":[]},{"n":6,"t":"當他來看我的時候，說的是假話；他心存奸惡，走到外邊才說出來。","notes":[]},{"n":7,"t":"所有恨我的，都一同交頭接耳議論我，他們設計要害我。","notes":[]},{"n":8,"t":"他們說：「他有怪病纏身，他已躺下，必不能再起來。」","notes":[]},{"n":9,"t":"連我知己的朋友，我所信賴、吃我飯的人也用腳踢我。","notes":[]},{"n":10,"t":"耶和華啊，求你憐憫我，使我起來，好報復他們！","notes":[]},{"n":11,"t":"我因此就知道你喜愛我，我的仇敵不得向我誇勝。","notes":[]},{"n":12,"t":"你因我純正就扶持我，使我永遠站立在你面前。","notes":[]},{"n":13,"t":"耶和華－以色列的神是應當稱頌的，從亙古直到永遠。阿們！阿們！","notes":[]}]},"42":{"heading":"流亡異鄉者的禱告﹙一﹚","verses":[{"n":1,"t":"神啊，我的心切慕你，如鹿切慕溪水。","notes":[]},{"n":2,"t":"我的心渴想神，就是永生神，我幾時得朝見神呢？","notes":[]},{"n":3,"t":"我晝夜以眼淚當食物，人不住地對我說：「你的神在哪裏呢？」","notes":[]},{"n":4,"t":"我從前與眾人同往，領他們到神的殿裏，大家用歡呼稱頌的聲音守節；我追想這些事，我的心極其悲傷。","notes":[]},{"n":5,"t":"我的心哪，你為何憂悶？為何在我裏面煩躁？應當仰望神，我還要稱謝他，我當面的拯救，","notes":[]},{"n":6,"t":"我的神。我的心在我裏面憂悶，所以我從約旦地，從黑門嶺，從米薩山記念你。","notes":["「我當面...憂悶」是根據七十士譯本；原文是「他的臉的拯救。我的神啊，我的心在我裏面憂悶」。"]},{"n":7,"t":"你的瀑布發聲，深淵就與深淵響應，你的波浪洪濤漫過我身。","notes":[]},{"n":8,"t":"白晝，耶和華必施慈愛；黑夜，我要歌頌祈禱賜我生命的神。","notes":[]},{"n":9,"t":"我要對神－我的磐石說：「你為何忘記我呢？我為何因仇敵的欺壓時常哀痛呢？」","notes":[]},{"n":10,"t":"我的敵人辱罵我，好像敲碎我的骨頭，他們不住地對我說：「你的神在哪裏呢？」","notes":[]},{"n":11,"t":"我的心哪，你為何憂悶？為何在我裏面煩躁？應當仰望神，我還要稱謝他，我當面的拯救，我的神。","notes":[]}]},"43":{"heading":"流亡異鄉者的禱告﹙二﹚","verses":[{"n":1,"t":"神啊，求你為我伸冤，向不虔誠的國為我辯護；求你救我脫離詭詐不義的人。","notes":[]},{"n":2,"t":"你是作我保障的神，為何丟棄我呢？我為何因仇敵的欺壓時常哀痛呢？","notes":["「作我保障」：七十士譯本是「賜我力量」。"]},{"n":3,"t":"求你發出你的亮光和信實，好引導我，帶我到你的聖山，到你的居所！","notes":[]},{"n":4,"t":"我就走到神的祭壇，到賜我喜樂的神那裏。神，我的神啊，我要彈琴稱謝你！","notes":[]},{"n":5,"t":"我的心哪，你為何憂悶？為何在我裏面煩躁？應當仰望神，我還要稱謝他，我當面的拯救，我的神。","notes":[]}]},"44":{"heading":"求主保護","verses":[{"n":1,"t":"神啊，你在古時，我們列祖的日子所做的事，我們親耳聽見了，我們的列祖曾為我們述說。","notes":[]},{"n":2,"t":"你曾用手趕出外邦人，卻栽培了我們的列祖；你苦待萬民，卻叫我們的列祖發達。","notes":[]},{"n":3,"t":"因為他們不是靠自己的刀劍承受土地，也不是靠自己的膀臂得勝，而是靠你的右手、你的膀臂，和你臉上的亮光，因為你喜愛他們。","notes":[]},{"n":4,"t":"神啊，你是我的君王，求你發命令使雅各得勝。","notes":[]},{"n":5,"t":"靠你，我們要推倒我們的敵人；靠你的名，我們要踐踏那興起攻擊我們的人。","notes":[]},{"n":6,"t":"因為我必不倚靠我的弓，我的刀也不能使我得勝。","notes":[]},{"n":7,"t":"惟有你拯救我們脫離敵人，使恨我們的人羞愧。","notes":[]},{"n":8,"t":"我們要常常因神誇耀，要永遠頌揚你的名。（細拉）","notes":[]},{"n":9,"t":"但如今你丟棄了我們，使我們受辱，不和我們的軍隊同去。","notes":[]},{"n":10,"t":"你使我們在敵人前轉身撤退，使那恨我們的人任意搶奪。","notes":[]},{"n":11,"t":"你使我們如羊當作食物，把我們分散在列國中。","notes":[]},{"n":12,"t":"你賣了你的子民也不獲利，所得的並未加添你的資財。","notes":[]},{"n":13,"t":"你使我們受鄰國的羞辱，被四圍的人嗤笑譏諷。","notes":[]},{"n":14,"t":"你使我們在列國中成了笑柄，在萬民中使人搖頭。","notes":[]},{"n":15,"t":"因辱罵者和毀謗者的聲音，因仇敵和報仇者的緣故，我的凌辱常常在我面前，我臉上的羞愧將我遮蔽，","notes":[],"end":16},{"n":17,"t":"這些事都臨到我們身上，我們卻沒有忘記你，也沒有違背你的約；","notes":[]},{"n":18,"t":"我們的心並未退縮，我們的腳也沒有偏離你的路。","notes":[]},{"n":19,"t":"你在野狗出沒之處壓傷我們，以死蔭籠罩我們。","notes":[]},{"n":20,"t":"倘若我們忘記神的名，或向外邦神明舉手，","notes":[]},{"n":21,"t":"神豈不鑒察這事嗎？因為他曉得人心裏的隱祕。","notes":[]},{"n":22,"t":"我們為你的緣故終日被殺，人看我們如將宰的羊。","notes":[]},{"n":23,"t":"主啊，求你睡醒，為何儘睡呢？求你醒來，不要永遠丟棄我們！","notes":[]},{"n":24,"t":"你為何轉臉，不顧我們所遭的苦難和所受的欺壓呢？","notes":[]},{"n":25,"t":"我們俯伏在塵土上，我們的肚腹緊貼地面。","notes":[]},{"n":26,"t":"求你興起幫助我們！因你的慈愛救贖我們！","notes":[]}]},"45":{"heading":"皇家婚禮詩歌","verses":[{"n":1,"t":"我心裏湧出美辭，我為王朗誦我的詩章，我的舌頭是敏捷文士的手筆。","notes":[]},{"n":2,"t":"你比世人更美，你嘴裏滿有恩惠；所以神賜福給你，直到永遠。","notes":[]},{"n":3,"t":"勇士啊，願你腰間佩刀，大展榮耀和威嚴，","notes":[]},{"n":4,"t":"為真理、謙卑、公義威嚴地駕車前進，無不得勝；願你的右手顯明可畏的事。","notes":[]},{"n":5,"t":"你的箭鋒快，射中王的仇敵的心，萬民仆倒在你之下。","notes":[]},{"n":6,"t":"神啊，你的寶座是永永遠遠的，你國度的權杖是正直的權杖。","notes":[]},{"n":7,"t":"你喜愛公義，恨惡罪惡，所以神，就是你的神，用喜樂油膏你，勝過膏你的同伴。","notes":[]},{"n":8,"t":"你的衣服散發沒藥、沉香、肉桂的香氣，象牙宮中絲弦樂器的聲音使你歡喜。","notes":[]},{"n":9,"t":"你的妃嬪之中有列王的女兒，王后佩戴俄斐金飾站立在你右邊。","notes":[]},{"n":10,"t":"女子啊，要傾聽，要思想，要側耳而聽！不要記念你本族和你父家，","notes":[]},{"n":11,"t":"王就羨慕你的美貌；因為他是你的主，你當向他下拜。","notes":[]},{"n":12,"t":"推羅必來送禮，百姓中富足的人也必向你求恩。","notes":["「推羅」：原文直譯「推羅女子」。"]},{"n":13,"t":"君王的女兒在宮裏極其榮華，她的衣服是金線繡的；","notes":[]},{"n":14,"t":"她穿錦繡的衣服，引到王面前，陪伴她的童女隨從她，也被帶到你面前。","notes":[]},{"n":15,"t":"她們要歡喜快樂，被引導進入王宮。","notes":[]},{"n":16,"t":"你的子孫要接續你列祖，你要立他們在各地作王。","notes":[]},{"n":17,"t":"我必使萬代記念你的名，萬民要永永遠遠稱謝你。","notes":[]}]},"46":{"heading":"神與我們同在","verses":[{"n":1,"t":"神是我們的避難所，是我們的力量，是我們在患難中隨時的幫助。","notes":[]},{"n":2,"t":"所以，地雖改變，山雖搖動到海心，","notes":[]},{"n":3,"t":"其中的水雖澎湃翻騰，山雖因海漲而戰抖，我們也不害怕。（細拉）","notes":[]},{"n":4,"t":"有一道河，這河的分汊使神的城歡喜，這城就是至高者居住的聖所。","notes":[]},{"n":5,"t":"神在其中，城必不動搖；到天一亮，神必幫助這城。","notes":[]},{"n":6,"t":"萬邦喧嚷，國度動搖；神出聲，地就熔化。","notes":[]},{"n":7,"t":"萬軍之耶和華與我們同在，雅各的神是我們的避難所！（細拉）","notes":[]},{"n":8,"t":"你們來看耶和華的作為，看他使地怎樣荒涼。","notes":[]},{"n":9,"t":"他止息戰爭，直到地極；他折弓、斷槍，把戰車焚燒在火中。","notes":[]},{"n":10,"t":"你們要休息，要知道我是神！我必在列國中受尊崇，在全地也受尊崇。","notes":[]},{"n":11,"t":"萬軍之耶和華與我們同在，雅各的神是我們的避難所！","notes":[]}]},"47":{"heading":"至高的主宰","verses":[{"n":1,"t":"萬民哪，你們都要鼓掌！用歡呼的聲音向神呼喊！","notes":[]},{"n":2,"t":"因為耶和華至高者是可畏的，他是治理全地的大君王。","notes":[]},{"n":3,"t":"他使萬民服在我們以下，又使萬族服在我們腳下。","notes":[]},{"n":4,"t":"他為我們選擇產業，就是他所愛之雅各的榮耀。（細拉）","notes":[]},{"n":5,"t":"神上升，有喊聲相送；耶和華上升，有角聲相送。","notes":[]},{"n":6,"t":"你們要向神歌頌，歌頌！向我們的王歌頌，歌頌！","notes":[]},{"n":7,"t":"因為神是全地的王，你們要用聖詩歌頌！","notes":[]},{"n":8,"t":"神作王治理列國，神坐在他的聖寶座上。","notes":[]},{"n":9,"t":"萬民的君王聚集，要作亞伯拉罕的神的子民，因為地上的盾牌是屬神的，他為至高！","notes":[]}]},"48":{"heading":"錫安－神的城","verses":[{"n":1,"t":"耶和華本為大！在我們神的城中，在他的聖山上，當受大讚美。","notes":[]},{"n":2,"t":"錫安山－大君王的城，在北面居高華美，為全地所喜悅。","notes":[]},{"n":3,"t":"神在城的宮殿中，自顯為避難所。","notes":[]},{"n":4,"t":"看哪，諸王會合，一同經過。","notes":[]},{"n":5,"t":"他們見了這城就驚奇喪膽，急忙逃跑。","notes":[]},{"n":6,"t":"戰兢在那裏抓住他們，他們好像臨產的婦人一樣陣痛。","notes":[]},{"n":7,"t":"神啊，你用東風擊破他施的船隻。","notes":[]},{"n":8,"t":"我們在萬軍之耶和華的城裏，就是我們神的城裏，所看見的正如我們所聽見的。神必堅立這城，直到永遠。（細拉）","notes":[]},{"n":9,"t":"神啊，我們在你的殿中想念你的慈愛。","notes":[]},{"n":10,"t":"神啊，你受的讚美正與你的名相稱，直到地極！你的右手滿了公義。","notes":[]},{"n":11,"t":"因你的判斷，錫安山應當歡喜，猶大的城鎮應當快樂。","notes":["「猶大的城鎮」：原文直譯「猶大眾女子」。"]},{"n":12,"t":"你們當周遊錫安，四圍環繞，數點城樓，","notes":[]},{"n":13,"t":"細看它的城郭，察看它的宮殿，為要傳揚給後代。","notes":[]},{"n":14,"t":"因為這神永永遠遠為我們的神，他必作我們引路的，直到死時。","notes":["「直到死時」：七十士譯本是「直到永遠」。"]}]},"49":{"heading":"恃財之愚","verses":[{"n":1,"t":"萬民哪，你們都當聽這話！世上所有的居民，無論貴賤貧富，都當側耳而聽！","notes":[],"end":2},{"n":3,"t":"我口要說智慧的言語，我心思想通達的道理。","notes":[]},{"n":4,"t":"我要側耳聽比喻，用琴解謎語。","notes":[]},{"n":5,"t":"在患難的日子，追逼我的人的奸惡環繞我，我何必懼怕？","notes":["「追逼我的人的奸惡」：七十士譯本是「奸惡隨我腳跟」。"]},{"n":6,"t":"他們那些倚靠財貨，自誇錢財多的人，","notes":[]},{"n":7,"t":"沒有一個能贖自己的弟兄，能將贖價給神，","notes":["「沒有...弟兄」或譯「哀哉，沒有一個能贖回自己」。"]},{"n":8,"t":"讓他長遠活著，不見地府；因為贖生命的價值極貴，只可永遠罷休。","notes":["「地府」：七十士譯本是「朽壞」。"],"end":9},{"n":10,"t":"他要見智慧人死，愚昧人和畜牲一般的人一同滅亡，把他們的財貨留給別人。","notes":[]},{"n":11,"t":"他們雖以自己的名叫自己的地，墳墓卻作他們永遠的家，作他們世世代代的居所。","notes":["本節根據七十士譯本；原文是「他們心裏思想：他們的家室必永存，住宅必留到萬代；他們就以自己的名稱自己的地。」"]},{"n":12,"t":"人居尊貴中不能長久，如同死亡的畜類一樣。","notes":[]},{"n":13,"t":"他們所行之道本為自己的愚昧，後來的人卻還佩服他們的話語。（細拉）","notes":[]},{"n":14,"t":"他們如同羊群註定要下陰間，死亡必作他們的牧者；到了早晨，正直人必管轄他們。他們的形像必被陰間所滅，無處可容身。","notes":[]},{"n":15,"t":"然而神必救贖我的命脫離陰間的掌控，因他必收納我。（細拉）","notes":[]},{"n":16,"t":"見人發財、家室日益顯赫的時候，你不要懼怕；","notes":[]},{"n":17,"t":"因為他死的時候甚麼也不能帶去，他的榮耀不能隨他下去。","notes":[]},{"n":18,"t":"他活著的時候，雖然自誇為有福─你若自己行得好，人必誇獎你─","notes":[]},{"n":19,"t":"他仍必與歷代的祖宗一樣同歸死亡，永不見光。","notes":[]},{"n":20,"t":"人在尊貴中而不醒悟，就如死亡的畜類一樣。","notes":[]}]},"50":{"heading":"真實的敬拜","verses":[{"n":1,"t":"大能者神－耶和華已經發言呼召天下，從日出之地到日落之處。","notes":[]},{"n":2,"t":"從全然美麗的錫安中，神已經發光了。","notes":[]},{"n":3,"t":"我們的神要來，絕不閉口；有烈火在他面前吞滅，有暴風在他四圍颳起。","notes":[]},{"n":4,"t":"他呼召上天下地，為要審判他的子民：","notes":[]},{"n":5,"t":"「召集我的聖民，就是那些用祭物與我立約的人，到我這裏來。」","notes":[]},{"n":6,"t":"諸天必表明他的公義，因為神是施行審判的。（細拉）","notes":[]},{"n":7,"t":"「聽啊，我的子民，我要說話！以色列啊，我要審問你；我是神，是你的神！","notes":[]},{"n":8,"t":"我並不因你的祭物責備你；你的燔祭常在我面前。","notes":[]},{"n":9,"t":"我不從你家中取公牛，也不從你圈內取公山羊；","notes":[]},{"n":10,"t":"因為，林中的百獸是我的，千山的牲畜也是我的。","notes":[]},{"n":11,"t":"山中的飛鳥，我都知道，田野的走獸也都屬我。","notes":["「山中」：七十士譯本和其他古譯本是「天空」。"]},{"n":12,"t":"「我若是飢餓，不用告訴你，因為世界和其中所充滿的都是我的。","notes":[]},{"n":13,"t":"我豈吃公牛的肉呢？我豈喝公山羊的血呢？","notes":[]},{"n":14,"t":"你們要以感謝為祭獻給神，又要向至高者還你的願，","notes":[]},{"n":15,"t":"並要在患難之日求告我，我必搭救你，你也要榮耀我。」","notes":[]},{"n":16,"t":"但神對惡人說：「你怎敢傳講我的律例，口中提到我的約呢？","notes":[]},{"n":17,"t":"其實你恨惡管教，將我的言語拋在腦後。","notes":[]},{"n":18,"t":"你見了盜賊就樂意與他同夥，又和行姦淫的人同流合污。","notes":[]},{"n":19,"t":"「你的口出惡言，你的舌編造詭詐。","notes":[]},{"n":20,"t":"你坐著，毀謗你的兄弟，讒害你親母的兒子。","notes":[]},{"n":21,"t":"你做了這些事，我閉口不言，你想我正如你一樣；其實我要責備你，將這些事擺在你眼前。","notes":[]},{"n":22,"t":"「你們忘記神的，要思想這事，免得我把你們撕碎，無人搭救。","notes":[]},{"n":23,"t":"凡以感謝獻祭的就是榮耀我；那按正路而行的，我必使他得著神的救恩。」","notes":[]}]},"51":{"heading":"求主赦免","verses":[{"n":1,"t":"神啊，求你按你的慈愛恩待我！按你豐盛的憐憫塗去我的過犯！","notes":[]},{"n":2,"t":"求你將我的罪孽洗滌淨盡，潔除我的罪！","notes":[]},{"n":3,"t":"因為我知道我的過犯；我的罪常在我面前。","notes":[]},{"n":4,"t":"我向你犯罪，惟獨得罪了你，在你眼前行了這惡，以致你責備的時候顯為公義，判斷的時候顯為清白。","notes":[]},{"n":5,"t":"看哪，我是在罪孽裏生的，在我母親懷胎的時候就有了罪。","notes":[]},{"n":6,"t":"你所喜愛的是內心的誠實；求你在我隱密處使我得智慧。","notes":[]},{"n":7,"t":"求你用牛膝草潔淨我，我就乾淨；求你洗滌我，我就比雪更白。","notes":[]},{"n":8,"t":"求你使我得聽歡喜快樂的聲音，使你所壓傷的骨頭可以踴躍。","notes":[]},{"n":9,"t":"求你轉臉不看我的罪，塗去我一切的罪孽。","notes":[]},{"n":10,"t":"神啊，求你為我造清潔的心，使我裏面重新有正直的靈。","notes":["「正直」或譯「堅定」。"]},{"n":11,"t":"不要丟棄我，使我離開你的面；不要從我收回你的聖靈。","notes":[]},{"n":12,"t":"求你使我重得救恩之樂，以樂意的靈來扶持我，","notes":[]},{"n":13,"t":"我就把你的道指教有過犯的人，罪人必歸順你。","notes":[]},{"n":14,"t":"神啊，你是拯救我的神；求你救我脫離流人血的罪！我的舌頭就高唱你的公義。","notes":[]},{"n":15,"t":"主啊，求你使我嘴唇張開，我的口就傳揚讚美你的話！","notes":[]},{"n":16,"t":"你本不喜愛祭物，若喜愛，我就獻上；燔祭你也不喜悅。","notes":[]},{"n":17,"t":"神所要的祭就是憂傷的靈；神啊，憂傷痛悔的心，你必不輕看。","notes":[]},{"n":18,"t":"求你隨你的美意善待錫安，建造耶路撒冷的城牆。","notes":[]},{"n":19,"t":"那時，你必喜愛公義的祭和燔祭，全牲的燔祭；那時，人必將公牛獻在你壇上。","notes":[]}]},"52":{"heading":"神的審判和恩惠","verses":[{"n":1,"t":"勇士啊，你為何作惡自誇？神的慈愛是常存的。","notes":[]},{"n":2,"t":"你這行詭詐的人哪，你的舌頭像快利的剃刀，圖謀毀滅。","notes":[]},{"n":3,"t":"你愛惡勝似愛善，又愛說謊，勝於愛說公義。（細拉）","notes":[]},{"n":4,"t":"詭詐的舌頭啊，你愛說一切毀滅的話！","notes":[]},{"n":5,"t":"神也要毀滅你，直到永遠。他要抓住你，從帳棚中拉你出來，從活人之地將你拔除。（細拉）","notes":[]},{"n":6,"t":"義人要看見而懼怕，並要笑他。","notes":[]},{"n":7,"t":"看哪，這就是那不以神為保障的人，他只倚靠豐富的財物，在邪惡上堅立自己。","notes":[]},{"n":8,"t":"至於我，就像神殿中的青橄欖樹，我永永遠遠倚靠神的慈愛。","notes":[]},{"n":9,"t":"我要稱謝你，直到永遠，因為你做了這事。我也要在你聖民面前仰望你的名，這名本為美好。","notes":[]}]},"53":{"heading":"人的邪惡","verses":[{"n":1,"t":"愚頑人心裏說：「沒有神。」他們都敗壞，行了可憎惡的罪孽，沒有一個人行善。","notes":[]},{"n":2,"t":"神從天上垂看世人，要看有明白的沒有，有尋求神的沒有。","notes":[]},{"n":3,"t":"他們全都退後，一同變為污穢，沒有行善的，連一個也沒有。","notes":[]},{"n":4,"t":"作惡的都沒有知識嗎？他們吞吃我的百姓如同吃飯一樣，並不求告神。","notes":[]},{"n":5,"t":"他們在無可懼怕之處就大大害怕，因為神使那安營攻擊你之人的骨頭散開了。你使他們蒙羞，因為神棄絕了他們。","notes":[]},{"n":6,"t":"但願以色列的救恩出自錫安。當神救回他被擄子民的時候，雅各要快樂，以色列要歡喜。","notes":[]}]},"54":{"heading":"遭敵迫害求主保護","verses":[{"n":1,"t":"神啊，求你因你的名拯救我，憑你的大能為我伸冤。","notes":[]},{"n":2,"t":"神啊，求你聽我的禱告，側耳聽我口中的言語。","notes":[]},{"n":3,"t":"因為陌生人興起攻擊我，強橫的人尋索我的性命；他們眼中沒有神。（細拉）","notes":[]},{"n":4,"t":"看哪，神是幫助我的，主是扶持我性命的，","notes":[]},{"n":5,"t":"他要報應我仇敵所作的惡；求你憑你的信實滅絕他們。","notes":[]},{"n":6,"t":"我要把甘心祭獻給你；耶和華啊，我要頌揚你的名，這名本為美好。","notes":[]},{"n":7,"t":"他從一切的急難中把我救出來，我的眼睛也看見了我的仇敵遭報。","notes":[]}]},"55":{"heading":"被出賣者的禱告","verses":[{"n":1,"t":"神啊，求你側耳聽我的禱告，不要隱藏不聽我的懇求！","notes":[]},{"n":2,"t":"求你留心聽我，應允我。我哀嘆不安，發出呻吟，","notes":[]},{"n":3,"t":"都因仇敵的聲音，惡人的欺壓；他們將罪孽加在我身上，發怒氣加害我。","notes":[]},{"n":4,"t":"我的心在我裏面陣痛，死亡的恐怖落在我身。","notes":[]},{"n":5,"t":"恐懼戰兢臨到了我，驚恐籠罩我。","notes":[]},{"n":6,"t":"我說：「但願我有翅膀像鴿子，我就飛去，得享安息。","notes":[]},{"n":7,"t":"看哪，我要遠走高飛，宿在曠野。（細拉）","notes":[]},{"n":8,"t":"我要速速逃到避難之所，脫離狂風暴雨。」","notes":[]},{"n":9,"t":"主啊，求你吞滅他們，變亂他們的言語！因為我在城中見了兇暴爭吵的事。","notes":[]},{"n":10,"t":"他們晝夜在城牆上繞行，城內也有罪孽和奸惡。","notes":[]},{"n":11,"t":"邪惡在其中，欺壓和詭詐不離街市。","notes":[]},{"n":12,"t":"原來，不是仇敵辱罵我，若是仇敵，還可忍受；也不是恨我的人向我狂妄自大，若是恨我的人，我必躲避他。","notes":[]},{"n":13,"t":"不料是你；你原與我同等，是我的朋友，是我的知己！","notes":[]},{"n":14,"t":"我們素常彼此交談，以為甘甜；我們結伴在神的殿中同行。","notes":[]},{"n":15,"t":"願死亡忽然臨到他們！願他們活生生地下入陰間！因為他們的住處都是邪惡，他們的內心充滿奸惡。","notes":[]},{"n":16,"t":"至於我，我要求告神，耶和華必拯救我。","notes":[]},{"n":17,"t":"晚上、早晨、中午我要哀聲悲嘆，他就垂聽我的聲音。","notes":[]},{"n":18,"t":"他救贖我的命脫離攻擊我的人，使我得享平安，因為與我相爭的人很多。","notes":[]},{"n":19,"t":"那不願改變、不敬畏神的人，從太古常存的神必聽見而使他受苦。（細拉）","notes":[]},{"n":20,"t":"他背了約，伸手攻擊與他和好的人。","notes":[]},{"n":21,"t":"他的口如奶油光滑，他的心卻懷著敵意；他的話比油柔和，其實是拔出的刀。","notes":[]},{"n":22,"t":"你要把你的重擔卸給耶和華，他必扶持你，他永不叫義人動搖。","notes":[]},{"n":23,"t":"神啊，你必使惡人墜入滅亡的坑；那好流人血、行詭詐的人必活不過半生，但我要倚靠你。","notes":[]}]},"56":{"heading":"信靠神的祈禱","verses":[{"n":1,"t":"神啊，求你憐憫我，因為有人踐踏我，終日攻擊欺壓我。","notes":[]},{"n":2,"t":"我的仇敵終日踐踏我，逞驕傲攻擊我的人很多。","notes":[]},{"n":3,"t":"我懼怕的時候要倚靠你。","notes":[]},{"n":4,"t":"我倚靠神，我要讚美他的話語；我倚靠神，必不懼怕。血肉之軀能把我怎麼樣呢？","notes":[]},{"n":5,"t":"他們終日扭曲我的話，千方百計加害於我。","notes":[]},{"n":6,"t":"他們聚集，埋伏，窺探我的腳蹤，等候要害我的命。","notes":[]},{"n":7,"t":"他們豈能脫罪呢？神啊，求你在怒中使萬民敗落！","notes":["「他們豈能脫罪呢」：七十士譯本是「他們不能逃脫」。"]},{"n":8,"t":"我幾次流離，你都數算；求你把我的眼淚裝在你的皮袋裏。這一切不都記在你的冊子上嗎？","notes":[]},{"n":9,"t":"我呼求的日子，仇敵都要轉身撤退。神幫助我，這是我所知道的。","notes":[]},{"n":10,"t":"我倚靠神，我要讚美他的話語；我倚靠耶和華，我要讚美他的話語。","notes":[]},{"n":11,"t":"我倚靠神，必不懼怕。人能把我怎麼樣呢？","notes":[]},{"n":12,"t":"神啊，我要向你還所許的願，我要以感謝祭回報你；","notes":[]},{"n":13,"t":"因為你救我的命脫離死亡。你保護我的腳不跌倒，使我在生命的光中行在神面前。","notes":[]}]},"57":{"heading":"求主拯救","verses":[{"n":1,"t":"神啊，求你憐憫我，憐憫我，因為我的心投靠你。我要投靠在你翅膀蔭下，直等到災害過去。","notes":[]},{"n":2,"t":"我要求告至高的神，就是為我成全萬事的神。","notes":[]},{"n":3,"t":"那踐踏我的人辱罵我的時候，神必從天上施恩救我，(細拉)他必向我施行慈愛和信實。","notes":[]},{"n":4,"t":"至於我的性命，我好像躺臥在吞噬人的獅子當中；他們的牙齒是槍、箭，他們的舌頭是快刀。","notes":[]},{"n":5,"t":"神啊，願你崇高過於諸天！願你的榮耀高過全地！","notes":[]},{"n":6,"t":"他們為我的腳設下網羅，壓迫我；他們在我面前掘了坑，自己反掉在其中。（細拉）","notes":[]},{"n":7,"t":"神啊，我心堅定，我心堅定；我要唱詩，我要歌頌！","notes":[]},{"n":8,"t":"我的靈啊，你當醒起！琴瑟啊，當醒起！我自己要極早醒起！","notes":["「靈」：原文是「榮耀」。"]},{"n":9,"t":"主啊，我要在萬民中稱謝你，在萬族中歌頌你！","notes":[]},{"n":10,"t":"因為你的慈愛高及諸天，你的信實達到穹蒼。","notes":[]},{"n":11,"t":"神啊，願你崇高過於諸天！願你的榮耀高過全地！","notes":[]}]},"58":{"heading":"求神罰惡","verses":[{"n":1,"t":"你們緘默不語，真合公義嗎？你們審判世人，豈按正直嗎？","notes":[]},{"n":2,"t":"不然！你們心中作惡，量出你們在地上手中的殘暴。","notes":[]},{"n":3,"t":"惡人一出母胎就與神疏遠，一離母腹就走錯路，說謊話。","notes":[]},{"n":4,"t":"他們的毒氣好像蛇的毒氣，他們好像聾的毒蛇塞住耳朵，","notes":[]},{"n":5,"t":"聽不見弄蛇者的聲音，也聽不見魔術師的咒語。","notes":[]},{"n":6,"t":"神啊，求你敲碎他們口中的牙！耶和華啊，求你敲掉少壯獅子的大牙！","notes":[]},{"n":7,"t":"願他們消滅，如急流的水一般；他們瞄準射箭的時候，箭頭彷彿折斷。","notes":[]},{"n":8,"t":"願他們像蝸牛腐爛消失，又像婦人流掉的胎兒，未見天日。","notes":[]},{"n":9,"t":"你們用荊棘燒火，鍋還未熱，神就用旋風把未燒著的和已燒著的一齊颳去。","notes":[]},{"n":10,"t":"義人見仇敵遭報就歡喜，他要在惡人的血中洗腳。","notes":[]},{"n":11,"t":"因此，人必說：「義人誠然有善報，在地上果然有施行審判的神！」","notes":[]}]},"59":{"heading":"求主保護","verses":[{"n":1,"t":"我的神啊，求你救我脫離仇敵，把我安置在高處，脫離那些起來攻擊我的人。","notes":[]},{"n":2,"t":"求你救我脫離作惡的人，救我脫離好流人血的人！","notes":[]},{"n":3,"t":"因為他們埋伏要害我命，強悍的人聚集攻擊我，耶和華啊，不是為我的過犯，也不是為我的罪愆。","notes":[]},{"n":4,"t":"我雖然無過，他們急忙擺陣攻擊我。求你興起，來幫助我，來鑒察！","notes":[]},{"n":5,"t":"萬軍之耶和華神－以色列的神啊，求你醒起，懲治萬國！不要憐憫行詭詐的惡人！（細拉）","notes":[]},{"n":6,"t":"他們晚上轉回，叫號如狗，圍城繞行。","notes":[]},{"n":7,"t":"看哪，他們口中噴吐惡言，嘴裏有刀：「有誰聽見呢？」","notes":[]},{"n":8,"t":"但你－耶和華必譏笑他們，你要嗤笑萬國。","notes":[]},{"n":9,"t":"我的力量啊，我要等候你，因為神是我的庇護所。","notes":["「我」：有古卷是「你」。"]},{"n":10,"t":"我的神要以慈愛迎接我，神要叫我看見我的仇敵遭報。","notes":["「我的神要以慈愛」：有古卷是「慈愛的神」。"]},{"n":11,"t":"主，我們的盾牌啊，不要殺他們，免得我的子民遺忘；求你用你的能力使他們四散，使他們降為卑。","notes":[]},{"n":12,"t":"願他們因口中的罪和嘴唇的言語，被自己的驕傲抓住，他們所說的盡是咒罵和謊話。","notes":[]},{"n":13,"t":"求你發怒，使他們消滅，求你使他們消滅，歸於無有，使他們知道神在雅各中間掌權，直到地極。（細拉）","notes":[]},{"n":14,"t":"他們晚上轉回，叫號如狗，圍城繞行。","notes":[]},{"n":15,"t":"他們到處走動覓食，若不飽足就咆哮不已。","notes":[]},{"n":16,"t":"但我要歌頌你的能力，早晨要高唱你的慈愛；因為你是我的庇護所，在急難的日子作過我的避難所。","notes":[]},{"n":17,"t":"我的力量啊，我要歌頌你；因為神是我的庇護所，是賜恩給我的神。","notes":[]}]},"60":{"heading":"求主解救","verses":[{"n":1,"t":"神啊，你丟棄了我們，破壞了我們；你曾發怒，求你使我們復興！","notes":[]},{"n":2,"t":"你使地震動，崩裂；求你將裂口補好，因為地在搖動。","notes":[]},{"n":3,"t":"你讓你的子民遇見艱難，使我們喝那令人東倒西歪的酒。","notes":[]},{"n":4,"t":"你把旌旗賜給敬畏你的人，可以躲避弓箭。（細拉）","notes":["「躲避弓箭」是根據七十士譯本；原文是「為真理揚起來」。"]},{"n":5,"t":"求你應允我們，用右手施行拯救，好讓你所親愛的人得救。","notes":["「我們」：原文另譯「我」。"]},{"n":6,"t":"神在他的聖所說：「我要歡樂；要劃分示劍，丈量疏割谷。","notes":["「在他的聖所」或譯「指著他的聖潔」。"]},{"n":7,"t":"基列是我的，瑪拿西是我的。以法蓮是護衛我頭的，猶大是我的權杖。","notes":[]},{"n":8,"t":"摩押是我的沐浴盆，我要向以東扔鞋。非利士啊，你還能因我歡呼嗎？」","notes":[]},{"n":9,"t":"誰能領我進堅固城？誰能引我到以東地？","notes":[]},{"n":10,"t":"神啊，你真的丟棄了我們嗎？神啊，你不和我們的軍隊同去嗎？","notes":[]},{"n":11,"t":"求你幫助我們攻擊敵人，因為人的幫助是枉然的。","notes":[]},{"n":12,"t":"我們倚靠神才得施展大能，因為踐踏我們敵人的就是他。","notes":[]}]},"61":{"heading":"求主保佑","verses":[{"n":1,"t":"神啊，求你聽我的呼求，留心聽我的禱告！","notes":[]},{"n":2,"t":"我心裏發昏的時候，要從地極求告你。求你領我到那比我更高的磐石，","notes":[]},{"n":3,"t":"因為你是我的避難所，是我的堅固臺，使我脫離仇敵。","notes":[]},{"n":4,"t":"我要永遠住在你的帳幕裏！我要投靠在你翅膀下的隱密處！（細拉）","notes":[]},{"n":5,"t":"神啊，你聽了我所許的願；你將產業賜給敬畏你名的人。","notes":[]},{"n":6,"t":"求你加添王的壽數，使他的年歲存到世世代代。","notes":[]},{"n":7,"t":"願他在神面前永遠坐在王位上，求你預備慈愛和信實保佑他！","notes":[]},{"n":8,"t":"這樣，我要歌頌你的名，直到永遠，天天還我所許的願。","notes":[]}]},"62":{"heading":"在神保佑中安穩自在","verses":[{"n":1,"t":"我的心默默無聲，專等候神，我的救恩從他而來。","notes":[]},{"n":2,"t":"惟獨他是我的磐石，我的拯救；他是我的庇護所，我必不大大動搖。","notes":[]},{"n":3,"t":"你們大家攻擊一人，使他被殺，如歪斜的牆、將倒的壁，要到幾時呢？","notes":[]},{"n":4,"t":"他們彼此商議，要把他從高位上拉下來；他們喜愛謊話，口雖祝福，心卻詛咒。（細拉）","notes":[]},{"n":5,"t":"我的心哪，你當默默無聲，專等候神，因為我的盼望是從他而來。","notes":[]},{"n":6,"t":"惟獨他是我的磐石，我的拯救；他是我的庇護所，我必不動搖。","notes":[]},{"n":7,"t":"我的拯救、我的榮耀都在於神；我力量的磐石、我的避難所都在於神。","notes":[]},{"n":8,"t":"百姓啊，要時時倚靠他，在他面前傾心吐意；神是我們的避難所。（細拉）","notes":[]},{"n":9,"t":"人真是虛空，人真是虛假；放在天平裏就必浮起，他們一共比空氣還輕。","notes":[]},{"n":10,"t":"不要仗勢欺人，也不要因搶奪而驕傲；若財寶加增，不要放在心上。","notes":[]},{"n":11,"t":"神說了一次、兩次，我都聽見了，就是能力屬乎神。","notes":[]},{"n":12,"t":"主啊，慈愛也是屬乎你，因為你照著各人所做的報應他。","notes":[]}]},"63":{"heading":"渴慕神","verses":[{"n":1,"t":"神啊，你是我的神，我要切切尋求你；在乾旱疲乏無水之地，我的心靈渴想你，我的肉身切慕你。","notes":[]},{"n":2,"t":"我在聖所中曾如此瞻仰你，為要見你的能力和你的榮耀。","notes":[]},{"n":3,"t":"因你的慈愛比生命更好，我的嘴唇要頌讚你。","notes":[]},{"n":4,"t":"我還活著的時候要這樣稱頌你，我要奉你的名舉手。","notes":[]},{"n":5,"t":"我在床上記念你，在夜更的時候思念你；我的心像吃飽了骨髓肥油，我也要以歡樂的嘴唇讚美你。","notes":[],"end":6},{"n":7,"t":"因為你曾幫助了我，我要在你翅膀的蔭下歡呼。","notes":[]},{"n":8,"t":"我的心緊緊跟隨你；你的右手扶持了我。","notes":[]},{"n":9,"t":"但那些尋索要滅我命的人必往地底下去；","notes":[]},{"n":10,"t":"他們必被刀劍所殺，成為野狗的食物。","notes":[]},{"n":11,"t":"但是王必因神歡喜，凡指著他發誓的都要誇耀，因為說謊之人的口必被塞住。","notes":[]}]},"64":{"heading":"求主保護","verses":[{"n":1,"t":"神啊，我哀嘆的時候，求你聽我的聲音！求你保護我的性命，不受仇敵的驚嚇！","notes":[]},{"n":2,"t":"求你把我隱藏，使我脫離作惡之人的暗謀，脫離作孽之人的擾亂。","notes":[]},{"n":3,"t":"他們磨舌如刀，發出苦毒的言語，好像瞄準了的箭，","notes":[]},{"n":4,"t":"要在暗地裏射完全人；他們忽然射他，並不懼怕。","notes":[]},{"n":5,"t":"他們彼此勉勵，設下惡計；他們商量，暗設圈套，說：「誰能看見呢？」","notes":[]},{"n":6,"t":"他們圖謀奸惡：「我們完成了精密的策劃。」各人的意念心思是深沉的。","notes":[]},{"n":7,"t":"但神要用箭射他們，他們忽然受了傷。","notes":[]},{"n":8,"t":"他們必然絆跌，被自己的舌頭所害；凡看見他們的都必搖頭。","notes":[]},{"n":9,"t":"眾人都要害怕，要傳揚神的工作，並且明白他的作為。","notes":[]},{"n":10,"t":"義人必因耶和華歡喜，並要投靠他；凡心裏正直的人都必誇耀。","notes":[]}]},"65":{"heading":"頌讚主恩","verses":[{"n":1,"t":"神啊，在錫安，人都等候讚美你，也要向你還所許的願。","notes":[]},{"n":2,"t":"聽禱告的主啊，凡有血肉之軀的都要來就你。","notes":[]},{"n":3,"t":"罪孽勝了我；至於我們的過犯，你都要赦免。","notes":[]},{"n":4,"t":"你所揀選、使他親近你、住在你院中的，這人有福了！我們要因你居所、你聖殿的美福知足。","notes":[]},{"n":5,"t":"拯救我們的神啊，你必以威嚴秉公義應允我們；地極和海角遠方的人都倚靠你。","notes":[]},{"n":6,"t":"你既以大能束腰，就用力量安定諸山，","notes":[]},{"n":7,"t":"使諸海的響聲和其中波浪的響聲，並萬民的喧嘩，都平靜了。","notes":[]},{"n":8,"t":"住在地極的人因你的神蹟懼怕，你使日出日落之地都歡呼。","notes":[]},{"n":9,"t":"你眷顧地，降雨使地大大肥沃。神的河滿了水；你這樣澆灌了地，好為人預備五穀。","notes":[]},{"n":10,"t":"你澆透地的犁溝，潤澤犁脊，降甘霖，使地鬆軟；其中生長的，蒙你賜福。","notes":[]},{"n":11,"t":"你以恩惠為年歲的冠冕，你的路徑都滴下油脂，","notes":[]},{"n":12,"t":"滴在曠野的草場上。小山以歡樂束腰，","notes":[]},{"n":13,"t":"草場以羊群為衣，谷中也長滿了五穀；這一切都歡呼歌唱。","notes":[]}]},"66":{"heading":"頌讚感恩的詩","verses":[{"n":1,"t":"全地都當向神歡呼！","notes":[]},{"n":2,"t":"當歌頌他名的榮耀，使讚美他的話大有榮耀！","notes":[]},{"n":3,"t":"當對神說：「你的作為何等可畏！因你的大能，仇敵要向你投降。","notes":[]},{"n":4,"t":"全地要敬拜你，歌頌你，要歌頌你的名。」（細拉）","notes":[]},{"n":5,"t":"你們來看神所做的，他向世人所做之事是可畏的。","notes":[]},{"n":6,"t":"他將海變成乾地，使百姓步行過河；我們在那裏要因他歡喜。","notes":[]},{"n":7,"t":"他用權能治理，直到永遠。他的眼睛鑒察萬民；悖逆的人不可自高。（細拉）","notes":[]},{"n":8,"t":"萬民哪，你們當稱頌我們的神，使人得聽讚美他的聲音。","notes":[]},{"n":9,"t":"他使我們的性命存活，不叫我們的腳搖動。","notes":[]},{"n":10,"t":"神啊，你曾考驗我們，你熬煉我們，如煉銀子一樣。","notes":[]},{"n":11,"t":"你使我們進入羅網，把重擔放在我們身上。","notes":[]},{"n":12,"t":"你使人坐車軋我們的頭；我們經過水火，你卻使我們到豐富之地。","notes":[]},{"n":13,"t":"我要帶著燔祭進你的殿，向你還我的願，","notes":[]},{"n":14,"t":"就是在急難時我嘴唇所發的、口中所許的。","notes":[]},{"n":15,"t":"我要將肥牛的燔祭和公羊的香祭獻給你，又要把公牛和公山羊獻上。（細拉）","notes":[]},{"n":16,"t":"敬畏神的人哪，你們都來聽！我要述說他為我所做的事。","notes":[]},{"n":17,"t":"我曾用口求告他，我的舌頭也稱他為高。","notes":[]},{"n":18,"t":"我若心裏注重罪孽，主必不聽。","notes":[]},{"n":19,"t":"但神實在聽見了，他留心聽了我禱告的聲音。","notes":[]},{"n":20,"t":"神是應當稱頌的！他沒有推卻我的禱告，也沒有使他的慈愛離開我。","notes":[]}]},"67":{"heading":"感恩的詩","verses":[{"n":1,"t":"願神憐憫我們，賜福給我們，使他的臉向我們發光，（細拉）","notes":[]},{"n":2,"t":"好讓全地得知你的道路，萬國得知你的救恩。","notes":[]},{"n":3,"t":"神啊，願萬民稱謝你！願萬民都稱謝你！","notes":[]},{"n":4,"t":"願萬族都快樂歡呼；因為你必按公正審判萬民，引導地上的萬族。（細拉）","notes":[]},{"n":5,"t":"神啊，願萬民稱謝你！願萬民都稱謝你！","notes":[]},{"n":6,"t":"地已經出了土產，神，我們的神，要賜福給我們。","notes":[]},{"n":7,"t":"神要賜福給我們，地的四極都要敬畏他！","notes":[]}]},"68":{"heading":"勝利之歌","verses":[{"n":1,"t":"願神興起，使他的仇敵四散，使那恨他的人從他面前逃跑。","notes":[]},{"n":2,"t":"你驅逐他們，如煙被吹散；惡人見神的面就消滅，如蠟被火熔化。","notes":["「你驅逐他們」：有古譯本是「他們被驅逐」。"]},{"n":3,"t":"惟有義人必然歡喜，在神面前快樂，他們要在喜樂中歡欣。","notes":[]},{"n":4,"t":"你們當向神唱詩，歌頌他的名；為那駕車經過曠野的修平道路。他的名是耶和華，你們要在他面前歡樂！","notes":["「為那...道路」或譯「為那駕雲的高唱」。"]},{"n":5,"t":"神在他的聖所作孤兒的父，作寡婦的伸冤者。","notes":[]},{"n":6,"t":"神使孤獨的有家，使被囚的出來享福；惟有悖逆的要住在乾旱之地。","notes":[]},{"n":7,"t":"神啊，當你走在百姓前頭，在曠野行進，（細拉）","notes":[]},{"n":8,"t":"地見神的面就震動，天也降雨；西奈山見以色列神的面也震動。","notes":[]},{"n":9,"t":"神啊，你降下大雨；你的產業以色列疲乏的時候，你使他堅固。","notes":[]},{"n":10,"t":"你的會眾住在境內；神啊，你在恩惠中為困苦人預備所需的。","notes":[]},{"n":11,"t":"主發命令，傳好信息的婦女成了大群：","notes":[]},{"n":12,"t":"「統領大軍的君王逃跑了，逃跑了！」在家等候的婦女也分得了掠物。","notes":[]},{"n":13,"t":"你們躺臥在羊圈，好像鴿子的翅膀鍍銀，翎毛鍍金一般。","notes":[]},{"n":14,"t":"全能者在境內趕散列王的時候，勢如飄雪在撒們。","notes":[]},{"n":15,"t":"巴珊山是極其宏偉的山，巴珊山是多峰多嶺的山。","notes":["「極其宏偉」或譯「神」。"]},{"n":16,"t":"你們多峰多嶺的山哪，為何以妒忌的眼光看神所願居住的山？耶和華必住這山，直到永遠！","notes":[]},{"n":17,"t":"神的車輦累萬盈千；主在其中，好像在西奈聖山一樣。","notes":[]},{"n":18,"t":"你已經升上高天，擄掠了俘虜；你在人間，就是在悖逆的人中，受了供獻，使耶和華神可以與他們同住。","notes":[]},{"n":19,"t":"天天背負我們重擔的主，就是拯救我們的神，是應當稱頌的！（細拉）","notes":[]},{"n":20,"t":"神是為我們施行拯救的神；人能脫離死亡是在乎主─耶和華。","notes":[]},{"n":21,"t":"但神要打破他仇敵的頭，就是那常犯罪之人的頭顱。","notes":[]},{"n":22,"t":"主說：「我要使百姓從巴珊歸來，使他們從深海轉回，","notes":[]},{"n":23,"t":"好叫你打碎仇敵，使你的腳踹在血中，使你狗的舌頭也有份。」","notes":[]},{"n":24,"t":"神啊，你是我的神，我的王；人已經看見你行走，進入聖所。","notes":[]},{"n":25,"t":"歌唱的行在前，作樂的隨在後，都在擊鼓的童女中間：","notes":[]},{"n":26,"t":"「從以色列源頭而來的啊，你們當在各會中稱頌神─耶和華！」","notes":[]},{"n":27,"t":"在那裏，有統管他們的小便雅憫，有猶大的領袖和他們的一群人，有西布倫的領袖，有拿弗他利的領袖。","notes":[]},{"n":28,"t":"你的神已賜給你力量；神啊，求你堅固你為我們所成全的事！","notes":["「你的神已賜給你力量」：有古卷是「神啊，求你賞賜你的力量」。"]},{"n":29,"t":"因你耶路撒冷的殿，列王必帶貢物獻給你。","notes":[]},{"n":30,"t":"求你斥責蘆葦中的野獸和公牛群，並萬民中的牛犢。直到他們帶著銀塊來朝貢；神已經趕散好戰的萬民。","notes":["「直到...朝貢」：原文另譯「把銀塊踹在腳下」。","「神...萬民」：原文另譯「趕散好戰的萬民」。"]},{"n":31,"t":"埃及的使臣要出來，古實人要急忙向神伸出手來。","notes":["「古實」：包括蘇丹的大部分和埃塞俄比亞的一部分。"]},{"n":32,"t":"地上的國度啊，你們要向神歌唱，要歌頌主，（細拉）","notes":[]},{"n":33,"t":"就是那駕行在亙古的諸天之上的主！聽啊，他發出聲音，是極大的聲音。","notes":[]},{"n":34,"t":"你們要將能力歸給神；他的威榮在以色列之上，他的能力顯在天上。","notes":[]},{"n":35,"t":"神啊，你從聖所顯為可畏，以色列的神是那將力量權能賜給他百姓的。神是應當稱頌的！","notes":[]}]},"69":{"heading":"求助的禱告","verses":[{"n":1,"t":"神啊，求你救我！因為眾水就要淹沒我。","notes":[]},{"n":2,"t":"我深陷在淤泥中，沒有立腳之地；我到了深水之中，波濤漫過我身。","notes":[]},{"n":3,"t":"我因呼求困乏，喉嚨發乾；我因等候神，眼睛失明。","notes":[]},{"n":4,"t":"無故恨我的，比我的頭髮還多；無理與我為仇、要把我剪除的，甚為強盛。我沒有搶奪，他們竟然要我償還！","notes":[]},{"n":5,"t":"神啊，我的愚昧，你原知道，我的罪愆不能向你隱瞞。","notes":[]},{"n":6,"t":"萬軍之主耶和華啊，求你不要讓那等候你的因我蒙羞！以色列的神啊，求你不要讓那尋求你的因我受辱！","notes":[]},{"n":7,"t":"因我為你的緣故受了辱罵，滿面羞愧。","notes":[]},{"n":8,"t":"我的兄弟把我當陌生人，我母親的兒子把我當外邦人。","notes":[]},{"n":9,"t":"因我為你的殿心裏焦急，如同火燒，並且辱罵你的人的辱罵都落在我身上。","notes":[]},{"n":10,"t":"我哭泣，以禁食刻苦我心；這倒成了我的羞辱。","notes":[]},{"n":11,"t":"我拿麻布當衣裳，卻成了他們的笑柄。","notes":[]},{"n":12,"t":"坐在城門口的談論我，酒徒也以我為歌曲。","notes":[]},{"n":13,"t":"至於我，耶和華啊，在悅納的時候我向你祈禱。神啊，求你按你豐盛的慈愛，憑你拯救的信實應允我！","notes":[]},{"n":14,"t":"求你搭救我脫離淤泥，不叫我陷在其中；求你使我脫離那些恨我的人，使我脫離深水。","notes":[]},{"n":15,"t":"求你不容波濤漫過我，不容深淵吞滅我，不容深坑在我以上合口。","notes":[]},{"n":16,"t":"耶和華啊，求你應允我！因為你的慈愛本為美好；求你按你豐盛的憐憫轉回眷顧我！","notes":[]},{"n":17,"t":"不要轉臉不顧你的僕人；我在急難之中，求你速速應允我！","notes":[]},{"n":18,"t":"求你親近我，救贖我！求你因我仇敵的緣故將我贖回！","notes":[]},{"n":19,"t":"你知道我所受的辱罵、欺凌、羞辱；我的敵人都在你面前。","notes":[]},{"n":20,"t":"辱罵刺傷我的心，使我憂愁。我指望有人體恤，卻沒有一個；指望有人安慰，卻找不著一個。","notes":[]},{"n":21,"t":"他們拿苦膽給我當食物；我渴了，他們拿醋給我喝。","notes":[]},{"n":22,"t":"願他們的筵席在他們面前變為羅網，在他們平安的時候變為圈套。","notes":["「在他們平安的時候」或譯「對他們的朋友」。"]},{"n":23,"t":"願他們的眼睛昏花，看不見；求你使他們的腰常常戰抖。","notes":[]},{"n":24,"t":"求你將你的惱恨倒在他們身上，使你的烈怒追上他們。","notes":[]},{"n":25,"t":"願他們的住處變為廢墟，他們的帳棚無人居住。","notes":[]},{"n":26,"t":"因為你所擊打的，他們就迫害；你所擊傷的，他們述說他的愁苦。","notes":["「述說」：原文另譯「增加」。"]},{"n":27,"t":"求你使他們罪上加罪，不容他們在你面前稱義。","notes":[]},{"n":28,"t":"願他們從生命冊上被塗去，不得名列在義人之中。","notes":[]},{"n":29,"t":"但我困苦憂傷；神啊，願你的救恩將我安置在高處。","notes":[]},{"n":30,"t":"我要以詩歌讚美神的名，以感謝尊他為大！","notes":[]},{"n":31,"t":"這就讓耶和華喜悅，勝似獻牛，獻有角有蹄的公牛。","notes":[]},{"n":32,"t":"謙卑的人看見了就喜樂；尋求神的人，願你們的心甦醒。","notes":[]},{"n":33,"t":"因為耶和華聽了窮乏的人，不藐視被囚的人。","notes":[]},{"n":34,"t":"願天和地、海洋和其中一切的動物都讚美他！","notes":[]},{"n":35,"t":"因為神要拯救錫安，建造猶大的城鎮；他的子民要在那裏居住，得地為業。","notes":[]},{"n":36,"t":"他僕人的後裔要承受這地，愛他名的人要住在其中。","notes":[]}]},"70":{"heading":"求助的祈禱","verses":[{"n":1,"t":"神啊，求你快快搭救我！耶和華啊，求你速速幫助我！","notes":[]},{"n":2,"t":"願那些尋索我命的，抱愧蒙羞；願那些喜悅我遭害的，退後受辱。","notes":[]},{"n":3,"t":"願那些對我說「啊哈、啊哈」的，因羞愧退後。","notes":[]},{"n":4,"t":"願所有尋求你的，因你歡喜快樂；願那些喜愛你救恩的，常說：「當尊神為大！」","notes":[]},{"n":5,"t":"但我是困苦貧窮的；神啊，求你速速到我這裏來！你是幫助我的，搭救我的；耶和華啊，求你不要耽延！","notes":[]}]},"71":{"heading":"老年人的祈禱","verses":[{"n":1,"t":"耶和華啊，我投靠你，求你叫我永不羞愧！","notes":[]},{"n":2,"t":"求你憑你的公義搭救我，救拔我；側耳聽我，拯救我！","notes":[]},{"n":3,"t":"求你作我常來棲身的磐石，你已經吩咐要救我，因為你是我的巖石、我的山寨。","notes":["「棲身」：有古卷是「避難」。"]},{"n":4,"t":"我的神啊，求你救我脫離惡人的手，脫離不義和殘暴之人的手。","notes":[]},{"n":5,"t":"主耶和華啊，你是我所盼望的；自我年幼，你是我所倚靠的。","notes":[]},{"n":6,"t":"我自出母胎被你扶持，使我出母腹的是你。我要常常讚美你！","notes":[]},{"n":7,"t":"許多人看我為異類，但你是我堅固的避難所。","notes":[]},{"n":8,"t":"我要滿口述說讚美你的話終日榮耀你。","notes":[]},{"n":9,"t":"我年老的時候，求你不要丟棄我！我體力衰弱時，求你不要離棄我！","notes":[]},{"n":10,"t":"我的仇敵議論我，那些窺探要害我命的一同商議，","notes":[]},{"n":11,"t":"說：「神已經離棄他；你們去追趕他，捉拿他吧！因為沒有人搭救。」","notes":[]},{"n":12,"t":"神啊，求你不要遠離我！我的神啊，求你速速幫助我！","notes":[]},{"n":13,"t":"願那與我為敵的，羞愧滅亡；願那謀害我的，受辱蒙羞。","notes":[]},{"n":14,"t":"我卻要常常仰望，並要越發讚美你。","notes":[]},{"n":15,"t":"我的口要終日述說你的公義和你的救恩，因我無從計算其數。","notes":[]},{"n":16,"t":"我要述說主耶和華的大能，我單要提說你的公義。","notes":[]},{"n":17,"t":"神啊，自我年幼，你就教導我；直到如今，我傳揚你奇妙的作為。","notes":[]},{"n":18,"t":"神啊，我年老髮白的時候，求你不要離棄我！等我宣揚你的能力給下一代，宣揚你的大能給後世的人。","notes":[]},{"n":19,"t":"神啊，你的公義極高；行過大事的神啊，誰能像你？","notes":[]},{"n":20,"t":"你是叫我多經歷重大急難的，必使我再活過來，從地的深處救我上來。","notes":[]},{"n":21,"t":"你必使我越發昌大，又轉來安慰我。","notes":[]},{"n":22,"t":"我的神啊，我要鼓瑟稱謝你，稱謝你的信實！以色列的聖者啊，我要彈琴歌頌你！","notes":[]},{"n":23,"t":"我歌頌你的時候，我的嘴唇要歡呼；我的性命，就是你所救贖的，也要歡呼。","notes":[]},{"n":24,"t":"我的舌頭也必終日講論你的公義，因為那些謀害我的人已經蒙羞受辱了。","notes":[]}]},"72":{"heading":"為王祈禱","verses":[{"n":1,"t":"神啊，求你將你的公平賜給王，將你的公義賜給王的兒子。","notes":[]},{"n":2,"t":"使他按公義審判你的子民，按公平審判你的困苦人。","notes":[]},{"n":3,"t":"大山小山都要因公義使百姓得享平安。","notes":[]},{"n":4,"t":"他必為百姓中困苦的人伸冤，拯救貧窮之輩，壓碎那欺壓人的人。","notes":[]},{"n":5,"t":"太陽還存，月亮猶在，人要敬畏你，直到萬代！","notes":["「人要敬畏你」：七十士譯本是「願他永活」。"]},{"n":6,"t":"他必降臨，像雨降在已割的草地上，如甘霖滋潤田地。","notes":[]},{"n":7,"t":"在他的日子，公義要興旺，大有平安，除非月亮不在。","notes":["「公義」：有古卷是「義人」。"]},{"n":8,"t":"他要執掌權柄，從這海直到那海，從大河直到地極。","notes":[]},{"n":9,"t":"住在曠野的必在他面前下拜，他的仇敵必要舔土。","notes":[]},{"n":10,"t":"他施和海島的王要進貢，示巴和西巴的王要獻禮物。","notes":[]},{"n":11,"t":"眾王都要叩拜他，萬國都要事奉他。","notes":[]},{"n":12,"t":"貧窮人呼求，他要搭救，無人幫助的困苦人，他也搭救。","notes":[]},{"n":13,"t":"他要憐憫貧寒和貧窮的人，拯救貧窮人的性命。","notes":[]},{"n":14,"t":"他要救贖他們脫離欺壓和殘暴，他們的血在他眼中看為寶貴。","notes":[]},{"n":15,"t":"願他永遠活著，示巴的金子要獻給他；願人常常為他禱告，終日祝福他。","notes":[]},{"n":16,"t":"在地的山頂上，願五穀茂盛，所結的穀實響動，如黎巴嫩的樹林；願城裏的人興旺，如地上的草。","notes":[]},{"n":17,"t":"願他的名存到永遠，他的名如太陽之長久；願人因他蒙福，萬國稱他為有福。","notes":["「長久」：原文另譯「堅定」或「延續」。"]},{"n":18,"t":"惟獨耶和華－以色列的神能行奇事，他是應當稱頌的！","notes":[]},{"n":19,"t":"他榮耀的名也當稱頌，直到永遠。願他的榮耀充滿全地！阿們！阿們！","notes":[]},{"n":20,"t":"耶西的兒子－大衛的祈禱完畢。","notes":[]}]},"73":{"heading":"神的公正","verses":[{"n":1,"t":"神實在恩待以色列那些清心的人！","notes":[]},{"n":2,"t":"至於我，我的腳幾乎失閃，我的步伐險些走偏；","notes":[]},{"n":3,"t":"因為我嫉妒狂傲的人，我看見惡人享平安。","notes":[]},{"n":4,"t":"他們的力氣強壯，他們死的時候也沒有疼痛。","notes":[]},{"n":5,"t":"他們不像別人受苦，也不像別人遭災。","notes":[]},{"n":6,"t":"所以，驕傲如鏈子戴在他們項上，殘暴像衣裳覆蓋在他們身上。","notes":[]},{"n":7,"t":"他們的眼睛因體胖而凸出，他們的內心放任不羈。","notes":["「眼睛」：原文另譯「罪孽」。","「他們的內心放任不羈」：七十士譯本是「他們得到心裏所想的」。"]},{"n":8,"t":"他們譏笑人，憑惡意說欺壓人的話。他們說話自高；","notes":[]},{"n":9,"t":"他們的口褻瀆上天，他們的舌毀謗全地。","notes":[]},{"n":10,"t":"所以他的百姓歸到這裏，享受滿杯的水。","notes":["「享受...水」或譯「喝盡了滿杯的苦水」。"]},{"n":11,"t":"他們說：「神怎能曉得？至高者哪會知道呢？」","notes":[]},{"n":12,"t":"看哪，這就是惡人，他們常享安逸，財寶增多。","notes":[]},{"n":13,"t":"我實在徒然潔淨了我的心，徒然洗手表明我的無辜，","notes":[]},{"n":14,"t":"因為我終日遭災難，每日早晨受懲治。","notes":[]},{"n":15,"t":"我若說「我要這樣講」，就是愧對這世代的眾兒女了。","notes":[]},{"n":16,"t":"我思索要明白這事，眼看實係為難，","notes":[]},{"n":17,"t":"直到我進了神的聖所，思想他們的結局。","notes":[]},{"n":18,"t":"你實在把他們安放在滑地，使他們跌倒滅亡；","notes":[]},{"n":19,"t":"他們轉眼之間成了何等荒涼！他們被驚恐滅盡了。","notes":[]},{"n":20,"t":"人睡醒了，怎樣看夢，主啊，你醒了也必照樣輕看他們的影像。","notes":[]},{"n":21,"t":"因此，我心裏苦惱，肺腑被刺。","notes":[]},{"n":22,"t":"我這樣愚昧無知，在你面前如同畜牲。","notes":[]},{"n":23,"t":"然而，我常與你同在；你攙扶我的右手。","notes":[]},{"n":24,"t":"你要以你的訓言引導我，以後你必接我到榮耀裏。","notes":[]},{"n":25,"t":"除你以外，在天上我有誰呢？除你以外，在地上我也沒有所愛慕的。","notes":[]},{"n":26,"t":"我的肉體和我的心腸衰殘；但神是我心裏的力量，又是我的福分，直到永遠。","notes":[]},{"n":27,"t":"看哪，遠離你的，必要死亡；凡離棄你行淫的，你都滅絕了。","notes":[]},{"n":28,"t":"但我親近神是於我有益；我以主耶和華為我的避難所，好叫我述說你一切的作為。","notes":[]}]},"74":{"heading":"求主解救國家","verses":[{"n":1,"t":"神啊，你為何永遠丟棄我們呢？為何向你草場的羊發怒，如煙冒出呢？","notes":[]},{"n":2,"t":"求你記念你古時得來的會眾，就是你所贖、作你產業支派的，並記念你向來居住的錫安山。","notes":[]},{"n":3,"t":"求你舉步去看那日久荒涼之地，看仇敵在聖所中所做的一切惡事。","notes":[]},{"n":4,"t":"你的敵人在你會中吼叫，他們豎起自己的標幟為記號，","notes":[]},{"n":5,"t":"好像人揚起斧子對著林中的樹，","notes":["「好像人揚起斧子」：七十士譯本和其他古譯本是「好像斧子在入口處」。"]},{"n":6,"t":"現在將聖所中的雕刻，全都用斧子錘子打壞。","notes":["「雕刻」：七十士譯本是「門扉」。"]},{"n":7,"t":"他們用火焚燒你的聖所，褻瀆你名的居所於地。","notes":[]},{"n":8,"t":"他們心裏說「我們要盡行毀滅」；就在遍地燒燬敬拜神聚會的所在。","notes":[]},{"n":9,"t":"我們看不見自己的標幟，不再有先知，我們當中也無人知道這災禍要到幾時。","notes":[]},{"n":10,"t":"神啊，敵人辱罵要到幾時呢？仇敵藐視你的名要到永遠嗎？","notes":[]},{"n":11,"t":"你為甚麼縮回你的右手？求你從懷中伸出手來，毀滅他們。","notes":[]},{"n":12,"t":"神自古以來是我的王，在這地上施行拯救。","notes":[]},{"n":13,"t":"你曾用能力將海分開，你打破水裏大魚的頭。","notes":[]},{"n":14,"t":"你曾壓碎力威亞探的頭，把牠給曠野的禽獸作食物。","notes":["「力威亞探」是音譯，一種海獸。"]},{"n":15,"t":"你曾分裂泉源和溪流；使長流的江河枯乾。","notes":[]},{"n":16,"t":"白晝屬你，黑夜也屬你；亮光和太陽是你預備的。","notes":[]},{"n":17,"t":"地的一切疆界是你立的，夏天和冬天是你定的。","notes":[]},{"n":18,"t":"耶和華啊，仇敵辱罵，愚頑之輩藐視你的名；求你記念這事。","notes":[]},{"n":19,"t":"不要將屬你的斑鳩交給野獸，不要永遠忘記你困苦人的性命。","notes":["「斑鳩」：七十士譯本和其他古譯本是「讚美」。"]},{"n":20,"t":"求你顧念所立的約，因為地上黑暗之處遍滿了兇暴。","notes":[]},{"n":21,"t":"不要讓受欺壓的人蒙羞回去；要使困苦貧窮的人讚美你的名。","notes":[]},{"n":22,"t":"神啊，求你起來為自己辯護！求你記念愚頑人怎樣終日辱罵你。","notes":[]},{"n":23,"t":"不要忘記你敵人的喧鬧，就是那時常上升、起來對抗你之人的喧嘩。","notes":[]}]},"75":{"heading":"神是審判者","verses":[{"n":1,"t":"神啊，我們稱謝你，我們稱謝你！你的名臨近，人都述說你奇妙的作為。","notes":["「人」：七十士譯本是「我」。"]},{"n":2,"t":"我選定了日期，必按正直施行審判。","notes":[]},{"n":3,"t":"地和其上的居民都熔化了；我親自堅立地的柱子。（細拉）","notes":[]},{"n":4,"t":"我對狂傲的人說：「不要狂傲！」對兇惡的人說：「不要舉角！」","notes":[]},{"n":5,"t":"不要把你們的角高舉，不要挺著頸項說話。","notes":["「挺著頸項」：七十士譯本是「頂撞神」。"]},{"n":6,"t":"因為高舉非從東，非從西，也非從南而來。","notes":[]},{"n":7,"t":"惟有神斷定，他使這人降卑，使那人升高。","notes":[]},{"n":8,"t":"耶和華的手裏有杯，杯內滿了調和起沫的酒；他倒出來，地上的惡人都必喝，直到喝盡它的渣滓。","notes":[]},{"n":9,"t":"但我要宣揚，直到永遠！我要歌頌雅各的神！","notes":[]},{"n":10,"t":"惡人一切的角，我要砍斷；惟有義人的角必被高舉。","notes":[]}]},"76":{"heading":"神是勝利者","verses":[{"n":1,"t":"在猶大，神為人所認識；在以色列，他的名為大。","notes":[]},{"n":2,"t":"在撒冷有他的住處，在錫安有他的居所。","notes":[]},{"n":3,"t":"他在那裏折斷弓上的火箭、盾牌、刀劍和戰爭的兵器。（細拉）","notes":[]},{"n":4,"t":"你是光榮的，比獵物之山更威嚴。","notes":["「獵物」：七十士譯本是「永恆」。"]},{"n":5,"t":"心中勇敢的人都被掠奪；他們睡了長覺，沒有一個英雄能措手。","notes":[]},{"n":6,"t":"雅各的神啊，你的斥責一發，戰車和戰馬都沉睡了。","notes":[]},{"n":7,"t":"你，惟獨你是可畏的！你的怒氣一發，誰能在你面前站得住呢？","notes":[]},{"n":8,"t":"你從天上使人聽判斷。神起來施行審判，要救地上所有困苦的人；那時地就懼怕而靜默。（細拉）","notes":[],"end":9},{"n":10,"t":"人的憤怒終必稱謝你，你要以人的餘怒束腰。","notes":[]},{"n":11,"t":"你們當向耶和華－你們的神許願，還願；在他四圍的人都當拿貢物獻給那可畏的主。","notes":[]},{"n":12,"t":"他要挫折王子的驕氣，向地上的君王顯為可畏。","notes":[]}]},"77":{"heading":"遇難時得安慰","verses":[{"n":1,"t":"我要向神發聲呼求；我向神發聲，他必側耳聽我。","notes":[]},{"n":2,"t":"我在患難之日尋求主，在夜間不住地舉手禱告，我的心不肯受安慰。","notes":["「在夜間...禱告」：原文另譯「我的手夜間不住地在他面前」。"]},{"n":3,"t":"我想念神，就煩躁不安；我沉思默想，心靈發昏。（細拉）","notes":[]},{"n":4,"t":"你使我不能閉眼；我心煩亂，甚至不能說話。","notes":[]},{"n":5,"t":"我追想古時之日，上古之年。","notes":[]},{"n":6,"t":"夜間我想起我的歌曲，我的心默想，我的靈仔細省察：","notes":["「想起我的歌曲」：七十士譯本和其他古譯本是「沉思」。"]},{"n":7,"t":"「難道主要永遠丟棄我，不再施恩嗎？","notes":[]},{"n":8,"t":"難道他的慈愛永遠窮盡，他的應許世世廢棄嗎？","notes":[]},{"n":9,"t":"難道神忘記施恩，因發怒就止住他的憐憫嗎？」（細拉）","notes":[]},{"n":10,"t":"我說，至高者右手的能力已改變，這是我的悲哀。","notes":[]},{"n":11,"t":"我要記念耶和華所做的，要記念你古時的奇事；","notes":[]},{"n":12,"t":"我要思想你所做的，默念你的作為。","notes":[]},{"n":13,"t":"神啊，你的道是神聖的；有何神明大如神呢？","notes":[]},{"n":14,"t":"你是行奇事的神，你曾在萬民中彰顯能力。","notes":[]},{"n":15,"t":"你曾用膀臂贖了你的子民，就是雅各和約瑟的子孫。（細拉）","notes":[]},{"n":16,"t":"神啊，眾水見你，眾水一見你就都驚惶，深淵也都戰抖。","notes":[]},{"n":17,"t":"密雲倒出水來，天空發出響聲，你的箭也飛行四方。","notes":[]},{"n":18,"t":"你的雷聲在旋風之中，閃電照亮世界，大地戰抖震動。","notes":[]},{"n":19,"t":"你的道在海中，你的路在大水之中，你的腳蹤無人知道。","notes":[]},{"n":20,"t":"你曾藉摩西和亞倫的手引導你的百姓，好像領羊群一般。","notes":[]}]},"78":{"heading":"神與他的子民","verses":[{"n":1,"t":"我的子民哪，要側耳聽我的訓誨，豎起耳朵聽我口中的言語。","notes":[]},{"n":2,"t":"我要開口說比喻，我要解開古時的謎語，","notes":[]},{"n":3,"t":"是我們所聽見、所知道，我們的祖宗告訴我們的。","notes":[]},{"n":4,"t":"我們不要向子孫隱瞞這些事，而要將耶和華的美德和他的能力，並他所行的奇事，述說給後代聽。","notes":[]},{"n":5,"t":"他在雅各中立法度，在以色列中設律法；他吩咐我們的祖宗要傳給子孫，","notes":[]},{"n":6,"t":"使將要生的後代子孫可以曉得。他們也要起來告訴他們的子孫，","notes":[]},{"n":7,"t":"好讓他們仰望神，不忘記神的作為，惟遵守他的命令；","notes":[]},{"n":8,"t":"不要像他們的祖宗，是頑梗悖逆、心不堅定，向神心不忠實之輩。","notes":[]},{"n":9,"t":"以法蓮人帶著兵器，拿著弓，臨陣之日轉身退後。","notes":[]},{"n":10,"t":"他們不遵守神的約，不肯照他的律法行；","notes":[]},{"n":11,"t":"又忘記他的作為和他所彰顯的奇事。","notes":[]},{"n":12,"t":"他在埃及地，在瑣安田，在他們祖宗眼前施行奇事。","notes":[]},{"n":13,"t":"他把海分開，使他們過去，又叫水立起如壘。","notes":[]},{"n":14,"t":"他白日用雲彩，終夜用火光引導他們。","notes":[]},{"n":15,"t":"他在曠野使磐石裂開，多多地給他們水喝，如從深淵而出。","notes":[]},{"n":16,"t":"他使水從磐石湧出，叫水如江河下流。","notes":[]},{"n":17,"t":"他們卻仍舊得罪他，在乾旱之地悖逆至高者。","notes":[]},{"n":18,"t":"他們心中試探神，隨自己所欲的求食物，","notes":[]},{"n":19,"t":"並且妄論神說：「神豈能在曠野擺設筵席嗎？","notes":[]},{"n":20,"t":"他雖曾擊打磐石，使水湧出，如江河氾濫；他還能賜糧食嗎？還能為他的百姓預備吃的肉嗎？」","notes":[]},{"n":21,"t":"所以，耶和華聽見就發怒，有烈火向雅各點燃，有怒氣向以色列上騰；","notes":[]},{"n":22,"t":"因為他們不信服神，不倚賴他的拯救。","notes":[]},{"n":23,"t":"然而他卻吩咐天空，又敞開天上的門，","notes":[]},{"n":24,"t":"降嗎哪像雨，給他們吃，將天上的糧食賜給他們。","notes":[]},{"n":25,"t":"各人就吃大能者的食物；他賜下糧食，使他們飽足。","notes":[]},{"n":26,"t":"他令東風吹在天空，用能力引來南風。","notes":[]},{"n":27,"t":"他降肉像雨，多如塵土，降飛鳥，多如海沙，","notes":[]},{"n":28,"t":"落在他自己的營中，在他帳幕的四周圍。","notes":[]},{"n":29,"t":"他們吃了，而且飽足；這樣就隨了他們所欲的。","notes":[]},{"n":30,"t":"但在他們滿足食慾以前，食物還在他們口中的時候，","notes":[]},{"n":31,"t":"神的怒氣就向他們上騰，殺了他們當中肥壯的人，打倒以色列的青年。","notes":[]},{"n":32,"t":"雖是這樣，他們仍舊犯罪，不信他奇妙的作為。","notes":[]},{"n":33,"t":"因此，他使他們的日子全歸虛空，叫他們的年歲盡屬驚恐。","notes":[]},{"n":34,"t":"他殺他們的時候，他們才求問他，回心轉意，切切尋求神。","notes":[]},{"n":35,"t":"他們追念神是他們的磐石，至高的神是他們的救贖主。","notes":[]},{"n":36,"t":"他們卻用口諂媚他，用舌向他說謊。","notes":[]},{"n":37,"t":"他們的心向他不堅定，不忠於他的約。","notes":[]},{"n":38,"t":"但他有憐憫，赦免他們的罪孽，沒有滅絕他們，而且屢次撤銷他的怒氣，不發盡他的憤怒。","notes":[]},{"n":39,"t":"他想念他們不過是血肉之軀，是一陣去而不返的風。","notes":[]},{"n":40,"t":"他們在曠野悖逆他，在荒地令他擔憂，何其多呢！","notes":[]},{"n":41,"t":"他們再三試探神，惹動以色列的聖者。","notes":[]},{"n":42,"t":"他們不追念他手的能力，和他救贖他們脫離敵人的日子；","notes":[]},{"n":43,"t":"他怎樣在埃及顯神蹟，在瑣安田顯奇事，","notes":[]},{"n":44,"t":"把江河並河汊的水都變為血，使他們不能喝。","notes":[]},{"n":45,"t":"他使蒼蠅成群落在他們當中，吃盡他們，又叫青蛙滅了他們，","notes":[]},{"n":46,"t":"將他們的果實交給螞蚱，把他們勞碌得來的交給蝗蟲。","notes":[]},{"n":47,"t":"他降冰雹打壞他們的葡萄樹，下寒霜打壞他們的桑樹，","notes":[]},{"n":48,"t":"將他們的牲畜交給冰雹，把他們的群畜交給閃電。","notes":[]},{"n":49,"t":"他使猛烈的怒氣和憤怒、惱恨、苦難，成了一群降災的使者，臨到他們。","notes":[]},{"n":50,"t":"他為自己的怒氣修平了路，將他們的性命交給瘟疫，使他們死亡，","notes":[]},{"n":51,"t":"在埃及擊殺所有的長子，在含的帳棚中擊殺他們壯年時頭生的。","notes":[]},{"n":52,"t":"他卻領出自己的子民如羊，在曠野引導他們如羊群。","notes":[]},{"n":53,"t":"他領他們穩穩妥妥地，使他們不致害怕；海卻淹沒他們的仇敵。","notes":[]},{"n":54,"t":"他帶他們到自己聖地的邊界，到他右手所得的這山地。","notes":[]},{"n":55,"t":"他在他們面前趕出外邦人，用繩子抽籤量地給他們為業，讓以色列支派的人住在自己的帳棚裏。","notes":[]},{"n":56,"t":"他們仍舊試探，悖逆至高的神，不遵守他的法度，","notes":[]},{"n":57,"t":"反倒退後，行詭詐，像他們的祖宗一樣，他們翻轉，如同鬆弛的弓，","notes":[]},{"n":58,"t":"以丘壇惹他發怒，以雕刻的偶像使他忌恨。","notes":[]},{"n":59,"t":"神聽見就發怒，全然棄絕了以色列，","notes":[]},{"n":60,"t":"甚至離棄示羅的帳幕，就是他在人間所搭的帳棚；","notes":[]},{"n":61,"t":"又將他有能力的約櫃交給人擄去，將他的榮耀交在敵人手中；","notes":["「有能力的約櫃」：原文是「能力」。"]},{"n":62,"t":"並將他的百姓交給刀劍，向他的產業發怒。","notes":[]},{"n":63,"t":"壯丁被火燒滅，童女也無婚禮頌歌。","notes":[]},{"n":64,"t":"祭司倒在刀下，寡婦卻不哀哭。","notes":[]},{"n":65,"t":"那時，主像睡覺的人醒來，如勇士飲酒呼喊。","notes":[]},{"n":66,"t":"他擊退敵人，叫他們永蒙羞辱。","notes":[]},{"n":67,"t":"他撇棄約瑟的帳棚，不揀選以法蓮支派，","notes":[]},{"n":68,"t":"卻揀選猶大支派，揀選他所喜愛的錫安山；","notes":[]},{"n":69,"t":"建造他的聖所如同高峰，又像他所建立的永存之地。","notes":[]},{"n":70,"t":"他揀選他的僕人大衛，從羊圈中將他召來，","notes":[]},{"n":71,"t":"叫他不再牧放那些母羊，為要牧養自己的百姓雅各和自己的產業以色列。","notes":[]},{"n":72,"t":"於是，他以純正的心牧養他們，用巧妙的手引導他們。","notes":[]}]},"79":{"heading":"求主解救國家","verses":[{"n":1,"t":"神啊，外邦人侵犯你的產業，玷污你的聖殿，使耶路撒冷變成廢墟，","notes":[]},{"n":2,"t":"將你僕人的屍首交給天空的飛鳥為食，把你聖民的肉交給地上的走獸，","notes":[]},{"n":3,"t":"耶路撒冷的周圍流出他們的血如水，無人埋葬。","notes":[]},{"n":4,"t":"我們成為鄰國羞辱的對象，被四圍的人嗤笑譏刺。","notes":[]},{"n":5,"t":"耶和華啊，你發怒要到幾時呢？要到永遠嗎？你的忌恨要如火焚燒嗎？","notes":[]},{"n":6,"t":"求你將你的憤怒傾倒在那不認識你的萬邦和那不求告你名的國度。","notes":[]},{"n":7,"t":"因為他們吞了雅各，將他的住處變為廢墟。","notes":[]},{"n":8,"t":"求你不要記得我們先前世代的罪孽；願你的憐憫速速臨到我們，因為我們落到極卑微的地步。","notes":[]},{"n":9,"t":"拯救我們的神啊，求你因你名的榮耀幫助我們！為你名的緣故搭救我們，赦免我們的罪。","notes":[]},{"n":10,"t":"為何讓列國說「他們的神在哪裏」呢？求你讓列國知道，你在我們眼前伸你僕人流血的冤。","notes":[]},{"n":11,"t":"願被囚之人的嘆息達到你面前，求你以強大的膀臂存留那些將死的人。","notes":[]},{"n":12,"t":"主啊，求你將我們鄰邦所加給你的羞辱七倍歸到他們身上。","notes":[]},{"n":13,"t":"這樣，你的子民，你草場的羊，要稱謝你，直到永遠；要述說讚美你的話，直到萬代。","notes":[]}]},"80":{"heading":"求主復興國家","verses":[{"n":1,"t":"領約瑟如領羊群的以色列牧者啊，求你側耳而聽！在基路伯之上坐寶座的啊，求你發出光來！","notes":[]},{"n":2,"t":"在以法蓮、便雅憫、瑪拿西面前求你施展你的大能，拯救我們。","notes":[]},{"n":3,"t":"神啊，求你使我們回轉，使你的臉發光，我們就會得救！","notes":["「回轉」或譯「復興」；下同。"]},{"n":4,"t":"耶和華─萬軍之神啊，你因你百姓的禱告發怒，要到幾時呢？","notes":[]},{"n":5,"t":"你以眼淚當食物給他們吃，量出滿碗的眼淚給他們喝。","notes":[]},{"n":6,"t":"你使鄰邦因我們紛爭，我們的仇敵彼此戲笑。","notes":[]},{"n":7,"t":"萬軍之神啊，求你使我們回轉，使你的臉發光，我們就會得救！","notes":[]},{"n":8,"t":"你從埃及拔出一棵葡萄樹，趕出外邦人，把這樹栽上。","notes":[]},{"n":9,"t":"你在它面前清除雜物，它就深深扎根，蔓延滿地。","notes":[]},{"n":10,"t":"它的影子遮蔽群山，枝子好像高大的香柏樹。","notes":[]},{"n":11,"t":"它長出枝子，直到大海，伸展嫩枝，延到大河。","notes":[]},{"n":12,"t":"你為何拆毀這樹的籬笆，任憑路人摘取？","notes":[]},{"n":13,"t":"林中的野豬踐踏它，田裏的走獸吞吃它。","notes":[]},{"n":14,"t":"萬軍之神啊，求你轉回，從天上垂看觀察，眷顧這葡萄樹；","notes":[]},{"n":15,"t":"保護你右手所栽的根，你為自己所堅固的幼苗。","notes":[]},{"n":16,"t":"這樹已經被火焚燒，被刀砍伐，因你臉上的怒容就滅亡了。","notes":[]},{"n":17,"t":"願你的手扶持你右邊的人，你為自己所堅固的人子。","notes":[]},{"n":18,"t":"這樣，我們就不背離你；求你救活我們，讓我們得以求告你的名。","notes":[]},{"n":19,"t":"耶和華─萬軍之神啊，求你使我們回轉，使你的臉發光，我們就會得救！","notes":[]}]},"81":{"heading":"勸戒以色列的剛愎","verses":[{"n":1,"t":"你們當向神－我們的力量大聲歌唱，向雅各的神歡呼！","notes":[]},{"n":2,"t":"高唱詩歌，擊打手鼓，彈奏悅耳的琴瑟。","notes":[]},{"n":3,"t":"當在新月和滿月－我們過節的日期吹角，","notes":[]},{"n":4,"t":"因這是為以色列所定的律例，是雅各神的典章。","notes":[]},{"n":5,"t":"他攻擊埃及地的時候，曾立此為約瑟的法度。我聽見我所不明白的語言：","notes":[]},{"n":6,"t":"「我使你的肩頭得脫重擔，使你的手放下筐子。","notes":["本節的「你」原文是「他」。"]},{"n":7,"t":"你在急難中呼求，我就搭救你，在雷的隱密處應允你，在米利巴水那裏考驗你。（細拉）","notes":[]},{"n":8,"t":"聽啊，我的子民，我要勸戒你；以色列啊，我真願你肯聽從我。","notes":[]},{"n":9,"t":"在你當中，不可有外族的神明；外邦的神明，你也不可下拜。","notes":[]},{"n":10,"t":"我是耶和華－你的神，曾將你從埃及地領上來；你要大大張口，我就使你滿足。","notes":[]},{"n":11,"t":"「無奈，我的子民不聽我的聲音，以色列不肯聽從我。","notes":[]},{"n":12,"t":"我就任憑他們心裏頑梗，隨自己的計謀而行。","notes":[]},{"n":13,"t":"我的子民若肯聽從我，以色列肯行我的道，","notes":[]},{"n":14,"t":"我就速速制伏他們的仇敵，反手攻擊他們的敵人。","notes":[]},{"n":15,"t":"恨耶和華的人必來投降，願他們的厄運直到永遠。","notes":[]},{"n":16,"t":"他必拿上好的麥子給以色列吃，又拿磐石出的蜂蜜使你飽足。 」","notes":["「以色列」：原文是「他」。"]}]},"82":{"heading":"神是最高的主宰","verses":[{"n":1,"t":"神站立在神聖的會中，在諸神中施行審判。","notes":[]},{"n":2,"t":"你們審判不秉公義，抬舉惡人的臉面，要到幾時呢？（細拉）","notes":[]},{"n":3,"t":"當為貧寒的人和孤兒伸冤，為困苦和窮乏的人施行公義。","notes":[]},{"n":4,"t":"當保護貧寒和貧窮的人，救他們脫離惡人的手。","notes":[]},{"n":5,"t":"他們愚昧，他們無知，在黑暗中走來走去；地的根基都搖動了。","notes":[]},{"n":6,"t":"我曾說：「你們是諸神，都是至高者的兒子。","notes":[]},{"n":7,"t":"然而，你們要死去，與世人一樣，要仆倒，像任何一位王子一般。」","notes":[]},{"n":8,"t":"神啊，求你起來審判全地，因為你必得萬國為業。","notes":[]}]},"83":{"heading":"求主敗敵","verses":[{"n":1,"t":"神啊，求你不要靜默！神啊，求你不要閉口，不要不作聲！","notes":[]},{"n":2,"t":"因為你的仇敵喧嚷，恨你的抬起頭來。","notes":[]},{"n":3,"t":"他們同謀奸詐要害你的百姓，彼此商議要害你所保護的人。","notes":[]},{"n":4,"t":"他們說：「來吧，我們將他們除滅，使他們不再成國！使以色列的名不再被人記念！」","notes":[]},{"n":5,"t":"他們同心商議，彼此結盟，要抵擋你；","notes":[]},{"n":6,"t":"他們就是住帳棚的以東和以實瑪利人，摩押和夏甲人，","notes":[]},{"n":7,"t":"迦巴勒、亞捫、亞瑪力、非利士和推羅的居民。","notes":[]},{"n":8,"t":"亞述也與他們聯合，作羅得子孫的幫手。（細拉）","notes":[]},{"n":9,"t":"求你待他們，如待米甸，如在基順河待西西拉和耶賓一樣。","notes":[]},{"n":10,"t":"他們在隱‧多珥滅亡，成了地上的糞土。","notes":[]},{"n":11,"t":"求你使他們的貴族像俄立和西伊伯，使他們的王子都像西巴和撒慕拿。","notes":[]},{"n":12,"t":"因為他們說：「我們要得神的住處，作自己的產業。」","notes":[]},{"n":13,"t":"我的神啊，求你使他們像旋風中的塵土，如風前的碎稭。","notes":[]},{"n":14,"t":"火怎樣焚燒樹林，火焰怎樣燒著山嶺，","notes":[]},{"n":15,"t":"求你也照樣用狂風追趕他們，用暴雨恐嚇他們。","notes":[]},{"n":16,"t":"耶和華啊，求你使他們滿面羞恥，好叫他們尋求你的名！","notes":[]},{"n":17,"t":"願他們永遠羞愧驚惶！願他們慚愧滅亡！","notes":[]},{"n":18,"t":"願他們認識你的名是耶和華，惟獨你是掌管全地的至高者！","notes":[]}]},"84":{"heading":"渴慕耶和華的殿宇","verses":[{"n":1,"t":"萬軍之耶和華啊，你的居所何等可愛！","notes":[]},{"n":2,"t":"我羨慕渴想耶和華的院宇，我的內心，我的肉體向永生神歡呼。","notes":[]},{"n":3,"t":"萬軍之耶和華－我的王，我的神啊，在你祭壇那裏，麻雀為自己找到了家，燕子為自己找著菢雛之窩。","notes":[]},{"n":4,"t":"如此住在你殿中的有福了！他們不斷地讚美你。（細拉）","notes":[]},{"n":5,"t":"靠你有力量、心中嚮往錫安大道的，這人有福了！","notes":[]},{"n":6,"t":"他們經過「流淚谷」，叫這谷變為泉源之地；且有秋雨之福蓋滿了全谷。","notes":["「流淚谷」或譯「乾旱谷」。"]},{"n":7,"t":"他們行走，力上加力，各人到錫安朝見神。","notes":[]},{"n":8,"t":"萬軍之耶和華神啊，求你聽我的禱告！雅各的神啊，求你側耳而聽！（細拉）","notes":[]},{"n":9,"t":"神啊，我們的盾牌，求你觀看，求你垂顧你受膏者的面！","notes":[]},{"n":10,"t":"在你的院宇一日，勝似千日；寧可在我神的殿中看門，不願住在惡人的帳棚裏。","notes":[]},{"n":11,"t":"因為耶和華神是太陽，是盾牌，耶和華要賜下恩惠和榮耀。他未嘗留下福氣不給那些行動正直的人。","notes":[]},{"n":12,"t":"萬軍之耶和華啊，倚靠你的人有福了！","notes":[]}]},"85":{"heading":"為國求福","verses":[{"n":1,"t":"耶和華啊，你已經向你的地施恩，救回被擄的雅各。","notes":[]},{"n":2,"t":"你赦免了你百姓的罪孽，遮蓋了他們一切的過犯。（細拉）","notes":[]},{"n":3,"t":"你收回所發的憤怒，撤銷你猛烈的怒氣。","notes":[]},{"n":4,"t":"拯救我們的神啊，求你使我們回轉，使你向我們所發的憤怒止息。","notes":[]},{"n":5,"t":"你要向我們發怒到永遠嗎？要將你的怒氣延留到萬代嗎？","notes":[]},{"n":6,"t":"你不再將我們救活，使你的百姓因你歡喜嗎？","notes":[]},{"n":7,"t":"耶和華啊，求你使我們得見你的慈愛，又將你的救恩賜給我們。","notes":[]},{"n":8,"t":"我要聽神－耶和華所說的話，因為他必應許賜平安給他的百姓，就是他的聖民；他們卻不可再轉向愚昧。","notes":["「他們...愚昧」：七十士譯本是「和給那些心裏歸向他的人」。"]},{"n":9,"t":"他的救恩誠然與敬畏他的人相近，使榮耀住在我們的地上。","notes":[]},{"n":10,"t":"慈愛和誠實彼此相遇，公義與和平彼此相親。","notes":[]},{"n":11,"t":"誠實從地而生，公義從天而現。","notes":[]},{"n":12,"t":"耶和華必賜福氣給我們；我們的地也要出土產。","notes":[]},{"n":13,"t":"公義要行在他面前，使他的腳蹤有可走之路。","notes":[]}]},"86":{"heading":"求主恩助","verses":[{"n":1,"t":"耶和華啊，求你側耳應允我，因我是困苦貧窮的。","notes":[]},{"n":2,"t":"求你保住我的性命，因我是虔誠的人。我的神啊，求你拯救我這倚靠你的僕人！","notes":[]},{"n":3,"t":"主啊，求你憐憫我，因我終日求告你。","notes":[]},{"n":4,"t":"主啊，求你使你的僕人心裏歡喜，因為我的心仰望你。","notes":[]},{"n":5,"t":"主啊，你本為良善，樂於饒恕人，以豐盛的慈愛對待凡求告你的人。","notes":[]},{"n":6,"t":"耶和華啊，求你側耳聽我的禱告，留心聽我懇求的聲音。","notes":[]},{"n":7,"t":"我在患難之日要求告你，因為你必應允我。","notes":[]},{"n":8,"t":"主啊，諸神之中沒有可與你相比的，你的作為也無以為比。","notes":[]},{"n":9,"t":"主啊，你所造的萬民都要來敬拜你，他們要榮耀你的名。","notes":[]},{"n":10,"t":"因你本為大，且行奇妙的事，惟獨你是神。","notes":[]},{"n":11,"t":"耶和華啊，求你將你的道指教我，我要照你的真理而行；求你使我專心敬畏你的名！","notes":[]},{"n":12,"t":"主－我的神啊，我要一心稱謝你；我要榮耀你的名，直到永遠。","notes":[]},{"n":13,"t":"因為你的慈愛在我身上浩大，你救了我的性命免入陰間的深處。","notes":[]},{"n":14,"t":"神啊，驕傲的人起來攻擊我，又有一群強橫的人尋索我的命；他們沒有將你放在眼裏。","notes":[]},{"n":15,"t":"主啊，你是有憐憫，有恩惠的神，不輕易發怒，並有豐盛的慈愛和信實。","notes":[]},{"n":16,"t":"求你轉向我，憐憫我，將你的力量賜給僕人，拯救你使女的兒子。","notes":[]},{"n":17,"t":"求你向我顯出恩待我的憑據，使恨我的人看見就羞愧，因為你－耶和華幫助我，安慰了我。","notes":[]}]},"87":{"heading":"錫安頌","verses":[{"n":1,"t":"耶和華所立的根基在聖山上。","notes":[]},{"n":2,"t":"耶和華愛錫安的門，勝於愛雅各一切的住處。","notes":[]},{"n":3,"t":"神的城啊，有榮耀的事是指著你說的。（細拉）","notes":[]},{"n":4,"t":"我要提起拉哈伯和巴比倫人，是在認識我之中的；看哪，非利士、推羅和古實人，個個生在那裏。","notes":["「拉哈伯」是神話故事中的大海怪。"]},{"n":5,"t":"論到錫安，必有話說：「這一個、那一個都生在其中」；而且至高者必親自堅立這城。","notes":[]},{"n":6,"t":"當耶和華記錄萬民的時候，他要寫出人的出生地。（細拉）","notes":[]},{"n":7,"t":"歌唱的、跳舞的，都要說：「我的泉源都在你裏面。」","notes":["本節七十士譯本是「他們都以住在你裏面為樂。」"]}]},"88":{"heading":"求主眷顧","verses":[{"n":1,"t":"耶和華－拯救我的神啊，我晝夜在你面前呼求；","notes":[]},{"n":2,"t":"願我的禱告達到你面前，求你側耳聽我的懇求！","notes":[]},{"n":3,"t":"因為我心裏滿了患難，我的性命臨近陰間；","notes":[]},{"n":4,"t":"我與下到地府的人同列，如同無人幫助的人一樣。","notes":[]},{"n":5,"t":"我被丟在死人中，好像被殺的人躺在墳墓裏，不再被你記得，與你的手隔絕了。","notes":[]},{"n":6,"t":"你把我放在極深的地府裏，在黑暗地，在深處。","notes":[]},{"n":7,"t":"你的憤怒重壓我身，你用一切的波浪困住我。（細拉）","notes":[]},{"n":8,"t":"你把我所認識的人隔在遠處，使我為他們所憎惡；我被拘禁，不能出來。","notes":[]},{"n":9,"t":"我的眼睛因困苦而昏花；耶和華啊，我天天求告你，向你舉手。","notes":[]},{"n":10,"t":"你豈要行奇事給死人看嗎？陰魂還能起來稱謝你嗎？（細拉）","notes":[]},{"n":11,"t":"你的慈愛豈能在墳墓裏被人述說嗎？你的信實豈能在冥府被人傳揚嗎？","notes":["「冥府」：原文音譯「亞巴頓」，意思是「滅亡之地」。"]},{"n":12,"t":"你的奇事豈能在幽暗裏為人所知嗎？你的公義豈能在遺忘之地為人所識嗎？","notes":[]},{"n":13,"t":"耶和華啊，至於我，我要呼求你；每早晨，我的禱告要達到你面前。","notes":[]},{"n":14,"t":"耶和華啊，你為何丟棄我？為何轉臉不顧我？","notes":[]},{"n":15,"t":"我自幼受苦，幾乎死亡；你使我驚恐，煩亂不安。","notes":[]},{"n":16,"t":"你的烈怒漫過我身，你用驚嚇把我除滅。","notes":[]},{"n":17,"t":"這些如水終日環繞我，一起圍困我。","notes":[]},{"n":18,"t":"你把我的良朋密友隔在遠處，使我所認識的人都在黑暗裏。","notes":["「使我...黑暗裏」或譯「我所知的盡是黑暗」。"]}]},"89":{"heading":"困難中的聖詩","verses":[{"n":1,"t":"我要歌唱耶和華的慈愛，直到永遠，我要用口將你的信實傳到萬代。","notes":[]},{"n":2,"t":"因我曾說：「你的慈愛必建立到永遠，你的信實必堅立在天上。」","notes":["本節七十士譯本是「你說，慈愛必建立到永遠，你的信實必堅立在天上。」"]},{"n":3,"t":"「我與我所揀選的人立了約，向我的僕人大衛起了誓：","notes":[]},{"n":4,"t":"『我要堅立你的後裔，直到永遠，要建立你的寶座，直到萬代。』」（細拉）","notes":[]},{"n":5,"t":"耶和華啊，諸天要稱謝你的奇事；在聖者的會中，要稱謝你的信實。","notes":[]},{"n":6,"t":"因在天空誰能比耶和華呢？諸神之中，誰能像耶和華呢？","notes":[]},{"n":7,"t":"在聖者的會中，他是大有威嚴的神，比在他四圍所有的更可畏懼。","notes":[]},{"n":8,"t":"耶和華－萬軍之神啊，哪一個大能者像耶和華？你的信實在你四圍。","notes":[]},{"n":9,"t":"你管轄海的狂傲；波浪翻騰，你使它平靜了。","notes":[]},{"n":10,"t":"你打碎了拉哈伯，使牠如遭刺殺的人；你用大能的膀臂打散了你的仇敵。","notes":["「拉哈伯」是神話故事中的大海怪。"]},{"n":11,"t":"天屬你，地也屬你；世界和其中所充滿的都為你所建立。","notes":[]},{"n":12,"t":"南北為你所創造；他泊和黑門都因你的名歡呼。","notes":[]},{"n":13,"t":"你有大能的膀臂，你的手有力，你的右手也高舉。","notes":[]},{"n":14,"t":"公義和公平是你寶座的根基，慈愛和信實行在你前面。","notes":[]},{"n":15,"t":"知道向你歡呼的，那民有福了！耶和華啊，他們要行走在你臉的光中。","notes":[]},{"n":16,"t":"他們因你的名終日歡樂，因你的公義得以高舉。","notes":[]},{"n":17,"t":"你是他們力量的榮耀。我們的角必被高舉，因為你喜愛我們。","notes":[]},{"n":18,"t":"我們的盾牌是耶和華，我們的王是以色列的聖者。","notes":[]},{"n":19,"t":"當時，你在異象中吩咐你的聖民，說：「我已把救助之力加在壯士身上，高舉了那從百姓中所揀選的人。","notes":[],"heads":["神對大衛的應許"]},{"n":20,"t":"我尋得我的僕人大衛，用我的聖膏膏他。","notes":[]},{"n":21,"t":"我的手必使他堅立，我的膀臂也必堅固他。","notes":[]},{"n":22,"t":"仇敵必不勒索他，兇惡之子也不苦害他。","notes":[]},{"n":23,"t":"我要在他面前打碎他的敵人，擊殺那些恨他的人。","notes":[]},{"n":24,"t":"我的信實和我的慈愛要與他同在；因我的名，他的角必被高舉。","notes":[]},{"n":25,"t":"我要使他的手伸到海上，右手伸到河上。","notes":[]},{"n":26,"t":"他要稱呼我說：『你是我的父，是我的神，是拯救我的磐石。』","notes":[]},{"n":27,"t":"我也要立他為長子，為世上最高的君王。","notes":[]},{"n":28,"t":"我要為他存留我的慈愛，直到永遠，我與他所立的約必堅定不移。","notes":[]},{"n":29,"t":"我也要使他的後裔存到永遠，使他的寶座如天之久。","notes":[]},{"n":30,"t":"「倘若他的子孫離棄我的律法，不照我的典章行，","notes":[]},{"n":31,"t":"背棄我的律例，不遵守我的誡命，","notes":[]},{"n":32,"t":"我就要用杖責罰他們的過犯，用鞭責罰他們的罪孽。","notes":[]},{"n":33,"t":"只是我不將我的慈愛全然收回，也不叫我的信實廢除。","notes":[]},{"n":34,"t":"我必不毀損我的約，也不改變我口中所出的話。","notes":[]},{"n":35,"t":"我僅此一次指著自己的神聖起誓，我絕不向大衛說謊！","notes":[]},{"n":36,"t":"他的後裔要存到永遠，他的寶座在我面前如太陽，","notes":[]},{"n":37,"t":"又如月亮永遠堅立；天上的見證是確實的。」（細拉）","notes":[]},{"n":38,"t":"但你惱怒你的受膏者，拒絕他，離棄了他。","notes":[],"heads":["君主慘敗的哀歌"]},{"n":39,"t":"你厭惡與你僕人所立的約，將他的冠冕踐踏於地。","notes":[]},{"n":40,"t":"你拆毀了他一切的圍牆，使他的堡壘變為廢墟。","notes":[]},{"n":41,"t":"過路的人都搶奪他，他成了鄰邦羞辱的對象。","notes":[]},{"n":42,"t":"你高舉了他敵人的右手，使他所有的仇敵歡喜。","notes":[]},{"n":43,"t":"你叫他的刀劍捲刃，使他在戰爭中站立不住。","notes":[]},{"n":44,"t":"你使他的光輝止息，將他的寶座推倒於地。","notes":[]},{"n":45,"t":"你減少他年輕的日子，又使他蒙羞。（細拉）","notes":[]},{"n":46,"t":"耶和華啊，這要到幾時呢？你要隱藏自己到永遠嗎？你的憤怒如火焚燒要到幾時呢？","notes":[],"heads":["求救的禱告"]},{"n":47,"t":"求你想念我的生命是何等短暫。你創造世人，要使他們歸於何等的虛空呢？","notes":[]},{"n":48,"t":"誰能常活不見死亡、救自己脫離陰間的掌控呢？（細拉）","notes":[]},{"n":49,"t":"主啊，你從前憑你的信實向大衛起誓要施行的慈愛在哪裏呢？","notes":[]},{"n":50,"t":"主啊，求你記念僕人們所受的羞辱，記念我怎樣將萬族所加的羞辱都放在我的胸懷。","notes":[]},{"n":51,"t":"耶和華啊，這是你仇敵所加的羞辱，羞辱了你受膏者的腳蹤。","notes":[]},{"n":52,"t":"耶和華是應當稱頌的，直到永遠。阿們！阿們！","notes":[]}]},"90":{"heading":"神與人","verses":[{"n":1,"t":"主啊，你世世代代作我們的居所。","notes":[]},{"n":2,"t":"諸山未曾生出，地與世界你未曾造成，從亙古到永遠，你是神。","notes":[]},{"n":3,"t":"你使人歸於塵土，說：「世人哪，你們要歸回。」","notes":[]},{"n":4,"t":"在你看來，千年如已過的昨日，又如夜間的一更。","notes":[]},{"n":5,"t":"你叫他們如水沖去，他們如睡一覺。早晨，他們如生長的草；","notes":[]},{"n":6,"t":"早晨發芽生長，晚上割下枯乾。","notes":[]},{"n":7,"t":"我們因你的怒氣而消滅，因你的憤怒而驚惶。","notes":[]},{"n":8,"t":"你將我們的罪孽擺在你面前，將我們的隱惡擺在你面光之中。","notes":[]},{"n":9,"t":"我們經過的日子，都在你震怒之下，我們度盡的年歲，好像一聲嘆息。","notes":[]},{"n":10,"t":"我們一生的年日是七十歲，若是強壯可到八十歲；但其中所矜誇的不過是勞苦愁煩，轉眼即逝，我們便如飛而去。","notes":[]},{"n":11,"t":"誰曉得你怒氣的權勢？誰因著敬畏你而曉得你的憤怒呢？","notes":[]},{"n":12,"t":"求你指教我們怎樣數算自己的日子，好叫我們得著智慧的心。","notes":[]},{"n":13,"t":"耶和華啊，我們要等到幾時呢？求你轉回，憐憫你的僕人們。","notes":[]},{"n":14,"t":"求你使我們早早飽得你的慈愛，好叫我們一生一世歡呼喜樂。","notes":[]},{"n":15,"t":"求你照著你使我們受苦的日子，和我們遭難的年歲，使我們喜樂。","notes":[]},{"n":16,"t":"願你的作為向你僕人們顯現，願你的榮耀向他們子孫顯明。","notes":[]},{"n":17,"t":"願主－我們神的恩寵歸於我們身上。願你堅立我們手所做的工，我們手所做的工，願你堅立。","notes":[]}]},"91":{"heading":"神是我們的保護者","verses":[{"n":1,"t":"住在至高者隱密處的，必住在全能者的蔭下。","notes":[]},{"n":2,"t":"我要向耶和華說：「我的避難所、我的山寨、我的神，你是我所倚靠的。」","notes":[]},{"n":3,"t":"他必救你脫離捕鳥者的羅網和毀滅人的瘟疫。","notes":[]},{"n":4,"t":"他必用自己的翎毛遮蔽你；你要投靠在他翅膀底下，他的信實是大小的盾牌。","notes":[]},{"n":5,"t":"你必不怕黑夜的驚駭，或是白日飛的箭，","notes":[]},{"n":6,"t":"也不怕黑夜流行的瘟疫，或是午間滅人的災害。","notes":[]},{"n":7,"t":"雖有千人仆倒在你旁邊，萬人仆倒在你右邊，這災卻不得臨近你。","notes":[]},{"n":8,"t":"你惟親眼觀看，見惡人遭報。","notes":[]},{"n":9,"t":"因為耶和華是我的避難所，你以至高者為居所，","notes":[]},{"n":10,"t":"禍患必不臨到你，災害也不挨近你的帳棚。","notes":[]},{"n":11,"t":"因他要為你命令他的使者，在你所行的一切道路上保護你。","notes":[]},{"n":12,"t":"他們要用手托住你，免得你的腳碰在石頭上。","notes":[]},{"n":13,"t":"你要踹踏獅子和毒蛇，踐踏少壯獅子和大蛇。","notes":[]},{"n":14,"t":"「因為他專心愛我，我要搭救他；因為他認識我的名，我要把他安置在高處。","notes":[]},{"n":15,"t":"他若求告我，我就應允他；他在急難中，我與他同在；我要搭救他，使他尊貴。","notes":[]},{"n":16,"t":"我要使他享足長壽，將我的救恩顯明給他。」","notes":[]}]},"92":{"heading":"頌讚之詩","verses":[{"n":1,"t":"這是多麼好啊！稱謝耶和華，歌頌你至高者的名，","notes":[]},{"n":2,"t":"早晨傳揚你的慈愛，每夜傳揚你的信實。","notes":[]},{"n":3,"t":"用十弦的樂器和瑟，用琴優雅的聲音；","notes":[]},{"n":4,"t":"因你－耶和華藉著你的作為使我高興，我要因你手的工作歡呼。","notes":[]},{"n":5,"t":"耶和華啊，你的工作何其大！你的心思極其深！","notes":[]},{"n":6,"t":"畜牲一般的人不曉得，愚昧人也不明白。","notes":[]},{"n":7,"t":"惡人雖茂盛如草，作惡的人雖全都興旺，他們卻要滅亡，直到永遠。","notes":[]},{"n":8,"t":"耶和華啊，惟有你是至高，直到永遠。","notes":[]},{"n":9,"t":"耶和華啊，看哪，你的仇敵，看哪，你的仇敵都要滅亡；作惡的全都要離散。","notes":[]},{"n":10,"t":"你卻高舉了我的角，如野牛的角；我是被新油膏抹的。","notes":[]},{"n":11,"t":"我的眼睛看見我的仇敵遭報，我的耳朵聽見那些起來攻擊我的惡人受罰。","notes":[]},{"n":12,"t":"義人要興旺如棕樹，生長如黎巴嫩的香柏樹。","notes":[]},{"n":13,"t":"他們栽於耶和華的殿中，發旺在我們神的院裏。","notes":[]},{"n":14,"t":"他們髮白的時候仍結果子，而且鮮美多汁，","notes":[]},{"n":15,"t":"好顯明耶和華是正直的；他是我的磐石，在他毫無不義。","notes":[]}]},"93":{"heading":"神是王","verses":[{"n":1,"t":"耶和華作王！他以威嚴為衣穿上；耶和華以能力為衣，以能力束腰，世界就堅定，不得動搖。","notes":[]},{"n":2,"t":"你的寶座從太初立定，你從亙古就有。","notes":[]},{"n":3,"t":"耶和華啊，大水揚起，大水發聲，大水澎湃。","notes":[]},{"n":4,"t":"耶和華在高處大有威力，勝過諸水的響聲，洋海的大浪。","notes":[]},{"n":5,"t":"耶和華啊，你的法度最為確定；你的殿宜稱為聖，直到永遠。","notes":[]}]},"94":{"heading":"神審判萬人","verses":[{"n":1,"t":"耶和華啊，你是伸冤的神；伸冤的神啊，求你發出光來！","notes":[]},{"n":2,"t":"審判世界的主啊，求你挺身而立，使驕傲的人受應得的報應！","notes":[]},{"n":3,"t":"耶和華啊，惡人誇勝要到幾時呢？要到幾時呢？","notes":[]},{"n":4,"t":"他們咆哮，說狂妄的話，作惡的人全都誇耀自己。","notes":[]},{"n":5,"t":"耶和華啊，他們強壓你的百姓，苦害你的產業。","notes":[]},{"n":6,"t":"他們殺死寡婦和寄居的人，又殺害孤兒。","notes":[]},{"n":7,"t":"他們說：「耶和華必不看見，雅各的神必不留意。」","notes":[]},{"n":8,"t":"百姓中像畜牲一般的人當思想，你們愚昧人要到幾時才有智慧呢？","notes":[]},{"n":9,"t":"造耳朵的，難道自己聽不見嗎？造眼睛的，難道自己看不見嗎？","notes":[]},{"n":10,"t":"管教列國的，就是叫人得知識的，難道自己不懲治人嗎？","notes":[]},{"n":11,"t":"耶和華知道人的意念是虛妄的。","notes":[]},{"n":12,"t":"耶和華啊，你所管教、用律法教導的人有福了！","notes":[]},{"n":13,"t":"你使他在遭難的日子仍得平安，直到為惡人挖好了坑。","notes":[]},{"n":14,"t":"因為耶和華必不丟棄他的百姓，也不離棄他的產業。","notes":[]},{"n":15,"t":"審判要回復公義，心裏正直的，都必跟隨它。","notes":[]},{"n":16,"t":"誰肯為我起來攻擊邪惡的？誰肯為我站起抵擋作惡的？","notes":[]},{"n":17,"t":"若不是耶和華幫助我，我早就住在寂靜之中了。","notes":["「寂靜」就是「死亡」。"]},{"n":18,"t":"我若說：「我失了腳！」耶和華啊，你的慈愛必扶持我。","notes":[]},{"n":19,"t":"我心裏多憂多疑，你的安慰使我歡樂。","notes":[]},{"n":20,"t":"那藉著律例玩弄奸惡、以權位肆行殘害的，豈能與你交往呢？","notes":[]},{"n":21,"t":"他們大家聚集攻擊義人，將無辜的人定了死罪。","notes":[]},{"n":22,"t":"但耶和華向來作我的碉堡，我的神作了我投靠的磐石。","notes":[]},{"n":23,"t":"他叫他們的罪孽歸到自己身上，要因他們的邪惡剪除他們；耶和華－我們的神要把他們剪除。","notes":[]}]},"95":{"heading":"頌讚之詩","verses":[{"n":1,"t":"來啊，我們要向耶和華歌唱，向拯救我們的磐石歡呼！","notes":[]},{"n":2,"t":"我們要以感謝來到他面前，用詩歌向他歡呼！","notes":[]},{"n":3,"t":"因耶和華是偉大的神，是超越萬神的大君王。","notes":[]},{"n":4,"t":"地的深處在他手中；山的高峰也屬他。","notes":[]},{"n":5,"t":"海洋屬他，是他造的；旱地也是他手造成的。","notes":[]},{"n":6,"t":"來啊，我們要俯伏敬拜，在造我們的耶和華面前跪拜。","notes":[]},{"n":7,"t":"因為他是我們的神；我們是他草場的百姓，是他手中的羊。惟願你們今天聽他的話！","notes":[]},{"n":8,"t":"你們不可硬著心，像在米利巴，就是在曠野瑪撒的日子。","notes":[]},{"n":9,"t":"那時，你們的祖宗試我，探我，並且觀看我的作為。","notes":[]},{"n":10,"t":"四十年之久，我厭煩那世代，說：「這是心裏迷糊的百姓，竟不知道我的道路！」","notes":[]},{"n":11,"t":"所以，我在怒中起誓：「他們斷不可進入我的安息！」","notes":[]}]},"96":{"heading":"神是最高的君王","verses":[{"n":1,"t":"你們要向耶和華唱新歌！全地都要向耶和華歌唱！","notes":[]},{"n":2,"t":"要向耶和華歌唱，稱頌他的名！天天傳揚他的救恩！","notes":[]},{"n":3,"t":"在列國中述說他的榮耀！在萬民中述說他的奇事！","notes":[]},{"n":4,"t":"因耶和華本為大，當受極大的讚美；他在萬神之上，當受敬畏。","notes":[]},{"n":5,"t":"因萬民的神明都屬虛無；惟獨耶和華創造諸天。","notes":[]},{"n":6,"t":"有尊榮和威嚴在他面前，有能力與華美在他聖所。","notes":[]},{"n":7,"t":"民中的萬族啊，要將榮耀、能力歸給耶和華，都歸給耶和華！","notes":[]},{"n":8,"t":"要將耶和華的名所當得的榮耀歸給他，拿供物來進入他的院宇。","notes":[]},{"n":9,"t":"當敬拜神聖榮耀的耶和華，全地都要在他面前戰抖！","notes":["「當敬拜...耶和華」或譯「當以聖潔的妝飾敬拜耶和華」。"]},{"n":10,"t":"要在列國中說：「耶和華作王了！世界堅定，不得動搖；他要按公正審判萬民。」","notes":[]},{"n":11,"t":"願天歡喜，願地快樂！願海和其中所充滿的澎湃！","notes":[]},{"n":12,"t":"願田和其中所有的都歡樂！那時，林中的樹木都要在耶和華面前歡呼。","notes":[]},{"n":13,"t":"因為他來了，他來要審判全地。他要按公義審判世界，按信實審判萬民。","notes":[]}]},"97":{"heading":"神是最高的統治者","verses":[{"n":1,"t":"耶和華作王！願地快樂！願眾海島歡喜！","notes":[]},{"n":2,"t":"密雲和幽暗在他四圍，公義和公平是他寶座的根基。","notes":[]},{"n":3,"t":"烈火在他前頭行，燒滅他四圍的敵人。","notes":[]},{"n":4,"t":"他的閃電光照世界，大地看見就震動。","notes":[]},{"n":5,"t":"諸山見耶和華的面，就是全地之主的面，就如蠟熔化。","notes":[]},{"n":6,"t":"諸天表明他的公義，萬民看見他的榮耀。","notes":[]},{"n":7,"t":"願所有事奉雕刻偶像、靠虛無神明自誇的，都蒙羞愧。萬神哪，你們都當拜他。","notes":[]},{"n":8,"t":"耶和華啊，因你的判斷，錫安聽見就歡喜；猶大的城鎮也都快樂。","notes":["「猶大的城鎮」：原文直譯「猶大眾女子」。"]},{"n":9,"t":"因為你－耶和華至高，超乎全地；受尊崇，遠超萬神之上。","notes":[]},{"n":10,"t":"你們愛耶和華的，都當恨惡罪惡；他保護聖民的性命，搭救他們脫離惡人的手。","notes":[]},{"n":11,"t":"散播亮光是為義人，喜樂歸於心裏正直的人。","notes":["「散播亮光是為義人」：有古卷、七十士譯本和其他古譯本是「有亮光照耀著義人」。"]},{"n":12,"t":"義人哪，你們當靠耶和華歡喜，當頌揚他神聖的名字。","notes":["「名字」：原文是「紀念」。"]}]},"98":{"heading":"神掌管世界","verses":[{"n":1,"t":"你們要向耶和華唱新歌！因為他行過奇妙的事，他的右手和聖臂施行救恩。","notes":[]},{"n":2,"t":"耶和華顯明了他的救恩，在列國眼前顯出公義；","notes":[]},{"n":3,"t":"記念他對以色列家的慈愛和信實。地的四極都看見我們神的救恩。","notes":[]},{"n":4,"t":"全地都要向耶和華歡呼，要揚聲，歡唱，歌頌！","notes":[]},{"n":5,"t":"用琴歌頌耶和華，用琴和詩歌的聲音歌頌他！","notes":[]},{"n":6,"t":"用號筒和角聲，在大君王耶和華面前歡呼！","notes":[]},{"n":7,"t":"願海和其中所充滿的澎湃，願世界和住在其間的發聲。","notes":[]},{"n":8,"t":"願大水拍掌，願諸山在耶和華面前一同歡呼；","notes":[]},{"n":9,"t":"因為他來要審判全地。他要按公義審判世界，按公正審判萬民。","notes":[]}]},"99":{"heading":"神是至高之王","verses":[{"n":1,"t":"耶和華作王，萬民當戰抖！他坐在基路伯的寶座上，地當動搖。","notes":[]},{"n":2,"t":"耶和華在錫安為大，他超越萬民之上。","notes":[]},{"n":3,"t":"願他們頌揚他大而可畏的名，他本為聖！","notes":[]},{"n":4,"t":"喜愛公平、大能的王啊，你堅立公正，在雅各中施行公平和公義。","notes":[]},{"n":5,"t":"當尊崇耶和華－我們的神，在他腳凳前下拜。他本為聖！","notes":[]},{"n":6,"t":"在他的祭司中有摩西和亞倫，在求告他名的人中有撒母耳。他們求告耶和華，他就應允他們。","notes":[]},{"n":7,"t":"他在雲柱中向他們說話，他們遵守他的法度和他所賜給他們的律例。","notes":[]},{"n":8,"t":"耶和華－我們的神啊，你應允了他們；你是赦免他們的神，卻按他們所做的報應他們。","notes":[]},{"n":9,"t":"當尊崇耶和華－我們的神，在他的聖山下拜，因為耶和華－我們的神本為聖！","notes":[]}]},"100":{"heading":"頌讚之詩","verses":[{"n":1,"t":"普天下當向耶和華歡呼！","notes":[]},{"n":2,"t":"當樂意事奉耶和華，當歡唱來到他面前！","notes":[]},{"n":3,"t":"當認識耶和華是神！我們是他造的，也是屬他的；我們是他的民，是他草場的羊。","notes":[]},{"n":4,"t":"當稱謝進入他的門，當讚美進入他的院。當感謝他，稱頌他的名！","notes":[]},{"n":5,"t":"因為耶和華本為善；他的慈愛存到永遠，他的信實直到萬代。","notes":[]}]},"101":{"heading":"王的諾言","verses":[{"n":1,"t":"我要歌唱慈愛和公平，耶和華啊，我要向你歌頌！","notes":[]},{"n":2,"t":"我要用智慧行完全的道。你幾時到我這裏來呢？我要以純正的心行在我家中。","notes":[]},{"n":3,"t":"邪僻的事，我都不擺在我眼前；悖逆的人所做的事，我甚恨惡，不容沾在我身上。","notes":[]},{"n":4,"t":"歪曲的心思，我必遠離；邪惡的事情，我不知道。","notes":[]},{"n":5,"t":"暗中讒害他鄰居的，我必將他滅絕；眼目高傲、心裏驕縱的，我必不容忍。","notes":[]},{"n":6,"t":"我眼要看顧地上誠實可靠的人，使他們與我同住；行正直路的，他要侍候我。","notes":[]},{"n":7,"t":"行詭詐的，必不得住在我家裏；說謊言的，必不得立在我眼前。","notes":[]},{"n":8,"t":"我每日早晨要滅絕地上所有的惡人，把作惡的從耶和華的城裏全都剪除。","notes":[]}]},"102":{"heading":"遭難中的祈禱","verses":[{"n":1,"t":"耶和華啊，求你聽我的禱告，願我的呼求達到你面前！","notes":[]},{"n":2,"t":"我急難的日子，求你不要轉臉不顧我！我呼求的日子，求你向我側耳，快快應允我！","notes":[]},{"n":3,"t":"因為我的年日在煙中消失，我的骨頭如火把燒著。","notes":["「在煙中消失」：有古卷、七十士譯本和其他古譯本是「如煙消滅」。"]},{"n":4,"t":"我的心如草被踩碎而枯乾，甚至我忘記吃飯。","notes":[]},{"n":5,"t":"因我嘆息的聲音，我的肉緊貼骨頭。","notes":[]},{"n":6,"t":"我如同曠野的鵜鶘，好像荒地的貓頭鷹。","notes":[]},{"n":7,"t":"我清醒難以入眠，如同房頂上孤單的麻雀。","notes":[]},{"n":8,"t":"我的仇敵整日辱罵我，向我叫號的人指著我賭咒。","notes":[]},{"n":9,"t":"我吃灰燼如同吃飯，我喝的有眼淚攙雜。","notes":[]},{"n":10,"t":"這都因你的惱恨和憤怒，你把我舉起，又把我摔下。","notes":[]},{"n":11,"t":"我的年日如夕陽，我也如草枯乾。","notes":[]},{"n":12,"t":"惟你－耶和華必永遠坐在寶座上，你的名存到萬代。","notes":["「名」：原文是「紀念」。"]},{"n":13,"t":"你必起來憐憫錫安；因現在是可憐它的時候，因所定的日期已經到了。","notes":[]},{"n":14,"t":"你的僕人們喜愛錫安的石頭，憐憫它的塵土。","notes":[]},{"n":15,"t":"列國要敬畏耶和華的名，地上眾王都要敬畏你的榮耀。","notes":[]},{"n":16,"t":"因為耶和華建造了錫安，在他的榮耀裏顯現。","notes":[]},{"n":17,"t":"他垂聽窮乏人的禱告，不藐視他們的祈求。","notes":[]},{"n":18,"t":"這必為後代的人記下，將來受造的百姓要讚美耶和華。","notes":[]},{"n":19,"t":"因為他從至高的聖所垂看；耶和華從天向地觀看，","notes":[]},{"n":20,"t":"要垂聽被囚之人的嘆息，要釋放將死的人，","notes":[]},{"n":21,"t":"使人在錫安傳揚耶和華的名，在耶路撒冷傳揚讚美他的話，","notes":[]},{"n":22,"t":"就是在萬民和列國聚集事奉耶和華的時候。","notes":[]},{"n":23,"t":"他使我的力量半途衰弱，使我的年日短少。","notes":[]},{"n":24,"t":"我說：「我的神啊，不要使我中年去世。你的年數世世無窮！」","notes":[]},{"n":25,"t":"你起初立了地的根基，天也是你手所造的。","notes":[]},{"n":26,"t":"天地都會消滅，你卻長存；天地都會像外衣漸漸舊了。你要將天地如內衣更換，天地就都改變了。","notes":[]},{"n":27,"t":"惟有你永不改變，你的年數沒有窮盡。","notes":[]},{"n":28,"t":"你僕人的子孫要安然居住，他們的後裔要堅立在你面前。","notes":[]}]},"103":{"heading":"耶和華的慈愛","verses":[{"n":1,"t":"我的心哪，你要稱頌耶和華！凡在我裏面的，都要稱頌他的聖名！","notes":[]},{"n":2,"t":"我的心哪，你要稱頌耶和華！不可忘記他一切的恩惠！","notes":[]},{"n":3,"t":"他赦免你一切的罪孽，醫治你一切的疾病。","notes":[]},{"n":4,"t":"他救贖你的命脫離地府，以仁愛和憐憫為你的冠冕。","notes":[]},{"n":5,"t":"他用美物使你的生命得以滿足，以致你如鷹返老還童。","notes":["「你的生命」：七十士譯本是「你所願的」。"]},{"n":6,"t":"耶和華施行公義，為所有受欺壓的人伸冤。","notes":[]},{"n":7,"t":"他使摩西知道他的法則，使以色列人曉得他的作為。","notes":[]},{"n":8,"t":"耶和華有憐憫，有恩惠，不輕易發怒，且有豐盛的慈愛。","notes":[]},{"n":9,"t":"他不長久責備，也不永遠懷怒。","notes":[]},{"n":10,"t":"他沒有按我們的罪待我們，也沒有照我們的罪孽報應我們。","notes":[]},{"n":11,"t":"天離地何等的高，他的慈愛向敬畏他的人也是何等的大！","notes":[]},{"n":12,"t":"東離西有多遠，他叫我們的過犯離我們也有多遠！","notes":[]},{"n":13,"t":"父親怎樣憐憫他的兒女，耶和華也怎樣憐憫敬畏他的人！","notes":[]},{"n":14,"t":"因為他知道我們的本體，思念我們不過是塵土。","notes":[]},{"n":15,"t":"至於世人，他的年日如草一樣。他興旺如野地的花，","notes":[]},{"n":16,"t":"經風一吹，就歸無有，它的原處也不再認識它。","notes":[]},{"n":17,"t":"但耶和華的慈愛歸於敬畏他的人，從亙古到永遠；他的公義也歸於子子孫孫，","notes":[]},{"n":18,"t":"就是那些遵守他的約、記念他的訓詞而遵行的人。","notes":[]},{"n":19,"t":"耶和華在天上立定寶座，他的國統管萬有。","notes":[]},{"n":20,"t":"聽從他命令、成全他旨意、有大能的天使啊，你們都要稱頌耶和華！","notes":[]},{"n":21,"t":"你們行他所喜悅的，作他諸軍，作他僕役的啊，都要稱頌耶和華！","notes":[]},{"n":22,"t":"你們一切被他造的，在他所治理的各處，都要稱頌耶和華！我的心哪，你要稱頌耶和華！","notes":[]}]},"104":{"heading":"造化主頌","verses":[{"n":1,"t":"我的心哪，你要稱頌耶和華！耶和華－我的神啊，你為至大！你以尊榮威嚴為衣，","notes":[]},{"n":2,"t":"披上亮光，如披外袍，鋪張穹蒼，如鋪幔子，","notes":[]},{"n":3,"t":"在水中立樓閣的棟梁，用雲彩為車輦，藉著風的翅膀而行，","notes":[]},{"n":4,"t":"以風為使者，以火焰為僕役，","notes":[]},{"n":5,"t":"將地立在根基上，使地永不動搖。","notes":[]},{"n":6,"t":"你用深水遮蓋地面，猶如衣裳；諸水高過山嶺。","notes":[]},{"n":7,"t":"你的斥責一發，水就奔逃；你的雷聲一發，水就奔流。","notes":[]},{"n":8,"t":"諸山上升，諸谷下沉，歸你為它所立定之地。","notes":[]},{"n":9,"t":"你定了界限，使水不能超越，不再轉回淹沒大地。","notes":[]},{"n":10,"t":"耶和華使泉源湧在山谷，流在山間，","notes":[]},{"n":11,"t":"使野地的走獸有水喝，野驢得解其渴。","notes":[]},{"n":12,"t":"天上的飛鳥在水旁住宿，在枝幹間啼叫。","notes":[]},{"n":13,"t":"他從樓閣中澆灌山嶺；因他作為的功效，地就豐足。","notes":[]},{"n":14,"t":"他使草生長，給牲畜吃，使菜蔬生長，供給人用，使人從地裏得食物，","notes":["「使菜蔬...用」或譯「使人耕種而長菜蔬」。"]},{"n":15,"t":"得酒能悅人心，得油能潤人面，得糧能養人心。","notes":[]},{"n":16,"t":"佳美的樹木，就是耶和華所栽種的黎巴嫩的香柏樹，都滿了汁漿。","notes":[]},{"n":17,"t":"雀鳥在其上搭窩，鸛以松樹為家。","notes":["「松樹」：原文另譯「樹頂」。"]},{"n":18,"t":"高山為野山羊的居所，巖石為石獾的藏身處。","notes":[]},{"n":19,"t":"你安置月亮以定季節，太陽自知沉落。","notes":[]},{"n":20,"t":"你造黑暗為夜，林中的百獸就都爬出來。","notes":[]},{"n":21,"t":"少壯獅子吼叫覓食，向神尋求食物。","notes":[]},{"n":22,"t":"太陽一出，獸就躲避，躺臥在洞裏。","notes":[]},{"n":23,"t":"人出去做工，勞碌直到晚上。","notes":[]},{"n":24,"t":"耶和華啊，你所造的何其多！都是你用智慧造成的，全地遍滿了你所造之物。","notes":[]},{"n":25,"t":"那裏有海，又大又廣，其中有無數的動物，大小活物都有。","notes":[]},{"n":26,"t":"那裏有船行走，有你所造的力威亞探悠游在其中。","notes":["「力威亞探」是音譯，一種海獸。"]},{"n":27,"t":"這些都仰望你按時給牠們食物。","notes":[]},{"n":28,"t":"你給牠們，牠們就拾起來；你張手，牠們就飽得美食。","notes":[]},{"n":29,"t":"你轉臉，牠們就驚惶；你收回牠們的氣，牠們就死亡，歸於塵土。","notes":[]},{"n":30,"t":"你差遣你的靈，牠們就受造；你使地面更換為新。","notes":[]},{"n":31,"t":"願耶和華的榮耀存到永遠！願耶和華喜愛自己所造的！","notes":[]},{"n":32,"t":"他看地，地便震動；他摸山，山就冒煙。","notes":[]},{"n":33,"t":"我一生要向耶和華唱詩！我還活的時候，要向我的神歌頌！","notes":[]},{"n":34,"t":"願他悅納我的默念！我要因耶和華歡喜！","notes":[]},{"n":35,"t":"願罪人從世上消滅！願惡人歸於無有！我的心哪，你要稱頌耶和華！哈利路亞！","notes":["「哈利路亞」意思是「你們要讚美耶和華」；下同。"]}]},"105":{"heading":"神和他的子民","verses":[{"n":1,"t":"你們要稱謝耶和華，求告他的名，在萬民中傳揚他的作為！","notes":[]},{"n":2,"t":"要向他唱詩，向他歌頌，述說他一切奇妙的作為！","notes":[]},{"n":3,"t":"要誇耀他的聖名！願尋求耶和華的人心中歡喜！","notes":[]},{"n":4,"t":"要尋求耶和華與他的能力，時常尋求他的面。","notes":[]},{"n":5,"t":"他僕人亞伯拉罕的後裔，他所揀選雅各的子孫哪，要記念他奇妙的作為和他的奇事，並他口中的判語。","notes":[],"end":6},{"n":7,"t":"他是耶和華－我們的神，全地都有他的判斷。","notes":[]},{"n":8,"t":"他記念他的約，直到永遠；記念他吩咐的話，直到千代，","notes":[]},{"n":9,"t":"就是與亞伯拉罕所立的約，向以撒所起的誓。","notes":[]},{"n":10,"t":"他將這約向雅各定為律例，向以色列定為永遠的約，","notes":[]},{"n":11,"t":"說：「我必將迦南地賜給你，作你們應得的產業。」","notes":[]},{"n":12,"t":"當時，他們人丁有限，數目稀少，在那地寄居。","notes":[]},{"n":13,"t":"他們從這邦遊到那邦，從這國去到另一民族。","notes":[]},{"n":14,"t":"他不容人欺負他們，為他們的緣故責備君王：","notes":[]},{"n":15,"t":"「不可傷害我的受膏者，也不可惡待我的先知。」","notes":[]},{"n":16,"t":"他命饑荒降在那地，斷絕日用的糧食，","notes":["「糧食」：原文直譯「糧食的杖」。"]},{"n":17,"t":"在他們以先差遣一個人前往，約瑟被賣為奴。","notes":[]},{"n":18,"t":"人用腳鐐傷他的腳，他被鐵的項鏈捆鎖。","notes":[]},{"n":19,"t":"耶和華的話試煉他，直等所說的應驗了。","notes":[]},{"n":20,"t":"王差人將他解開，治理萬民的把他釋放，","notes":[]},{"n":21,"t":"立他為王家之主，掌管他一切所有的，","notes":[]},{"n":22,"t":"使他隨意捆綁他的臣宰，將智慧教導他的長老。","notes":[]},{"n":23,"t":"以色列也到了埃及，雅各在含地寄居。","notes":[]},{"n":24,"t":"耶和華使他的百姓生養眾多，使他們比敵人強盛，","notes":[]},{"n":25,"t":"他使敵人的心轉去恨他的百姓，用詭計待他的僕人。","notes":[]},{"n":26,"t":"他差遣他的僕人摩西和他所揀選的亞倫，","notes":[]},{"n":27,"t":"在敵人中間顯他的神蹟，在含地顯他的奇事。","notes":[]},{"n":28,"t":"他差遣黑暗，就有黑暗；他們沒有違背他的話。","notes":[]},{"n":29,"t":"他使埃及的水變為血，令他們的魚死了。","notes":[]},{"n":30,"t":"在他們的地上，青蛙多多滋生，王宮的內室也是如此。","notes":[]},{"n":31,"t":"他一吩咐，蒼蠅就成群飛來，並有蚊子進入他們四境。","notes":[]},{"n":32,"t":"他給他們降下冰雹為雨，在他們的地上降下火焰。","notes":[]},{"n":33,"t":"他擊打他們的葡萄樹和無花果樹，毀壞他們境內的樹木。","notes":[]},{"n":34,"t":"他一吩咐，就有蝗蟲蝻子上來，不計其數，","notes":[]},{"n":35,"t":"吃光他們地上各樣的菜蔬，吞盡他們田地的出產。","notes":[]},{"n":36,"t":"他又擊殺他們國內所有的長子，就是他們強壯時頭生的。","notes":["「他們國內」：有古卷是「埃及」。"]},{"n":37,"t":"他卻帶領自己的百姓帶著金子銀子出來，他支派中沒有一個走不動的。","notes":[]},{"n":38,"t":"他們出來的時候，埃及人就歡喜；因為埃及人懼怕他們。","notes":[]},{"n":39,"t":"他鋪張雲彩當遮蔽，夜間使火光照。","notes":[]},{"n":40,"t":"他們祈求，他就使鵪鶉飛來，並用天上的糧食使他們飽足。","notes":[]},{"n":41,"t":"他敲開磐石，水就湧出；在乾旱之處，水流成河。","notes":[]},{"n":42,"t":"這都因他記念他的聖言和他的僕人亞伯拉罕。","notes":[]},{"n":43,"t":"他帶領自己的百姓歡樂而出，帶領自己的選民歡呼前往。","notes":[]},{"n":44,"t":"他把列國的地賜給他們，他們就承受萬民勞碌得來的，","notes":[]},{"n":45,"t":"好讓他們遵他的律例，守他的律法。哈利路亞！","notes":[]}]},"106":{"heading":"神對他子民的良善","verses":[{"n":1,"t":"哈利路亞！你們要稱謝耶和華，因他本為善，他的慈愛永遠長存！","notes":[]},{"n":2,"t":"誰能傳揚耶和華的大能？誰能表明他一切的美德？","notes":[]},{"n":3,"t":"凡遵守公平、常行公義的，這人有福了！","notes":[]},{"n":4,"t":"耶和華啊，你恩待你百姓的時候，求你記念我；你拯救他們的時候，求你眷顧我，","notes":[]},{"n":5,"t":"好使我經歷你選民的福分，享受你國民的喜樂，與你的產業一同誇耀。","notes":[]},{"n":6,"t":"我們與我們的祖宗一同犯罪，偏邪行惡。","notes":[]},{"n":7,"t":"我們的祖宗在埃及不明白你的奇事，不記念你豐盛的慈愛，反倒在紅海行了悖逆。","notes":["「紅海」是根據七十士譯本，原文是「蘆葦海」；本卷書下同。"]},{"n":8,"t":"然而，他因自己的名拯救他們，為要彰顯他的大能。","notes":[]},{"n":9,"t":"他斥責紅海，海就乾了，帶領他們走過深海，如走曠野。","notes":[]},{"n":10,"t":"他拯救他們脫離恨他們之人的手，從仇敵手中救贖他們。","notes":[]},{"n":11,"t":"水淹沒他們的敵人，沒有一個存留。","notes":[]},{"n":12,"t":"那時，他們才信他的話，歌唱讚美他。","notes":[]},{"n":13,"t":"很快地，他們就忘了他的作為，不仰望他的指引，","notes":[]},{"n":14,"t":"反倒在曠野起了貪婪之心，在荒地試探神。","notes":[]},{"n":15,"t":"他將他們所求的賜給他們，卻使他們心靈軟弱。","notes":[]},{"n":16,"t":"他們在營中嫉妒摩西和耶和華的聖者亞倫。","notes":[]},{"n":17,"t":"地就裂開，吞下大坍，掩蓋亞比蘭一夥的人。","notes":[]},{"n":18,"t":"有火在他們黨中點燃，有火焰燒燬了惡人。","notes":[]},{"n":19,"t":"他們在何烈山造了牛犢，叩拜鑄成的像，","notes":[]},{"n":20,"t":"將他們榮耀的主換為吃草之牛的像，","notes":[]},{"n":21,"t":"忘了神－他們的救主，就是曾在埃及行大事，","notes":[]},{"n":22,"t":"在含地行奇事，在紅海行可畏之事的那位。","notes":[]},{"n":23,"t":"因此，他說要滅絕他們；若非他所揀選的摩西在他面前站在破裂之處，使他的憤怒轉消，恐怕他就滅絕他們了。","notes":[]},{"n":24,"t":"他們又藐視那美地，不信他的話，","notes":[]},{"n":25,"t":"在自己帳棚內發怨言，不聽耶和華的聲音。","notes":[]},{"n":26,"t":"所以他向他們起誓，必叫他們倒在曠野，","notes":[]},{"n":27,"t":"叫他們的後裔倒在列國之中，分散在各地。","notes":[]},{"n":28,"t":"他們又與巴力‧毗珥連合，吃了祭死人的物。","notes":[]},{"n":29,"t":"他們這樣行，惹耶和華發怒，就有瘟疫流行在他們中間。","notes":[]},{"n":30,"t":"那時，非尼哈起而干預，瘟疫這才止息。","notes":[]},{"n":31,"t":"那就算他為義，世世代代，直到永遠。","notes":[]},{"n":32,"t":"他們在米利巴水又惹耶和華發怒，甚至摩西也因他們的緣故受虧損，","notes":[]},{"n":33,"t":"是因他們觸怒了他的靈，摩西就用嘴說了急躁的話。","notes":[]},{"n":34,"t":"他們不照耶和華所吩咐的滅絕外邦人，","notes":[]},{"n":35,"t":"反倒與列國相交，學習他們的行為，","notes":[]},{"n":36,"t":"事奉他們的偶像，這就成了自己的圈套。","notes":[]},{"n":37,"t":"他們把自己的兒女祭祀鬼魔，","notes":[]},{"n":38,"t":"流無辜人的血，就是自己兒女的血，用他們祭祀迦南的偶像，那地就被血玷污了。","notes":[]},{"n":39,"t":"這樣，他們被自己所做的玷污了，在行為上犯了淫亂。","notes":[]},{"n":40,"t":"耶和華的怒氣向他的百姓發作，他憎惡自己的產業，","notes":[]},{"n":41,"t":"將他們交在外邦人手裏，恨他們的人就轄制他們。","notes":[]},{"n":42,"t":"他們的仇敵欺壓他們，他們伏在敵人手下。","notes":[]},{"n":43,"t":"他屢次搭救他們，他們卻圖謀悖逆，就因自己的罪孽降為卑下。","notes":[]},{"n":44,"t":"然而，他聽見他們哀告的時候，就眷顧他們的急難，","notes":[]},{"n":45,"t":"為了他們，他記念自己的約，照他豐盛的慈愛改變心意，","notes":[]},{"n":46,"t":"使他們在凡擄掠他們的人面前蒙憐憫。","notes":[]},{"n":47,"t":"耶和華－我們的神啊，求你拯救我們，從列國中召集我們，我們好頌揚你的聖名，以讚美你為誇勝。","notes":[]},{"n":48,"t":"耶和華－以色列的神是應當稱頌的，從亙古直到永遠。願全體百姓都說：「阿們！」哈利路亞！","notes":[]}]},"107":{"heading":"頌讚神的良善","verses":[{"n":1,"t":"你們要稱謝耶和華，因他本為善，他的慈愛永遠長存！","notes":[]},{"n":2,"t":"願耶和華救贖的百姓說這話，就是他從敵人手中所救贖，","notes":[]},{"n":3,"t":"從各地，從東從西，從北從海那邊召集來的。","notes":[]},{"n":4,"t":"他們在曠野、在荒地飄流，找不到可居住的城，","notes":[]},{"n":5,"t":"又飢又渴，心裏發昏。","notes":[]},{"n":6,"t":"於是他們在急難中哀求耶和華，他就搭救他們脫離禍患，","notes":[]},{"n":7,"t":"又領他們行走直路，前往可居住的城。","notes":[]},{"n":8,"t":"但願人因耶和華的慈愛和他向人所做的奇事都稱謝他；","notes":[]},{"n":9,"t":"因他使心裏渴慕的人得以滿足，使飢餓的人得飽美食。","notes":[]},{"n":10,"t":"那些坐在黑暗中、死蔭裏的人，被困苦和鐵鏈捆鎖，","notes":[]},{"n":11,"t":"是因他們違背神的言語，藐視至高者的旨意。","notes":[]},{"n":12,"t":"所以，他用勞苦制伏他們的心；他們仆倒，無人扶助。","notes":[]},{"n":13,"t":"於是他們在急難中哀求耶和華，他就拯救他們脫離禍患。","notes":[]},{"n":14,"t":"他從黑暗中、從死蔭裏領他們出來，扯斷他們的捆綁。","notes":[]},{"n":15,"t":"但願人因耶和華的慈愛和他向人所做的奇事都稱謝他；","notes":[]},{"n":16,"t":"因為他打破了銅門，砍斷了鐵閂。","notes":[]},{"n":17,"t":"愚妄人因自己叛逆的行徑和自己的罪孽受苦楚。","notes":[]},{"n":18,"t":"他們心裏厭惡各樣的食物，就臨近死亡之門。","notes":[]},{"n":19,"t":"於是他們在急難中哀求耶和華，他就拯救他們脫離禍患。","notes":[]},{"n":20,"t":"他發出自己的話語醫治他們，救他們脫離陰府。","notes":[]},{"n":21,"t":"但願人因耶和華的慈愛和他向人所做的奇事都稱謝他。","notes":[]},{"n":22,"t":"願他們以感謝為祭獻給他，歡呼述說他的作為！","notes":[]},{"n":23,"t":"那些搭船出海，在大水中做生意的，","notes":[]},{"n":24,"t":"他們看見耶和華的作為，並他在深海中的奇事。","notes":[]},{"n":25,"t":"他一出令，狂風捲起，波浪翻騰。","notes":[]},{"n":26,"t":"他們上到天空，下到海底，他們的心因患難而消沉。","notes":[]},{"n":27,"t":"他們搖搖晃晃，東倒西歪，好像醉酒的人，他們的智慧無法可施。","notes":[]},{"n":28,"t":"於是他們在急難中哀求耶和華，他就領他們脫離禍患。","notes":[]},{"n":29,"t":"他使狂風止息，波浪平靜，","notes":[]},{"n":30,"t":"既平靜了，他們就歡喜，他就領他們到想要去的海港。","notes":[]},{"n":31,"t":"但願人因耶和華的慈愛和他向人所做的奇事都稱謝他。","notes":[]},{"n":32,"t":"願他們在百姓的會中尊崇他，在長老的座位上讚美他！","notes":[]},{"n":33,"t":"他使江河變為曠野，叫水泉變為乾涸之地，","notes":[]},{"n":34,"t":"使肥沃之地變為荒蕪的鹽地，都因當地居民的邪惡。","notes":[]},{"n":35,"t":"他使曠野變為水潭，叫旱地變為水泉，","notes":[]},{"n":36,"t":"使飢餓的人住在那裏，建造可居住的城，","notes":[]},{"n":37,"t":"又種田地，栽葡萄園，得享所出產的果實。","notes":[]},{"n":38,"t":"他賜福給他們，使他們生養眾多，也不叫他們的牲畜減少。","notes":[]},{"n":39,"t":"但他們因欺壓、患難、愁苦，人口減少而且卑微。","notes":[]},{"n":40,"t":"他使貴族蒙羞受辱，使他們迷失在荒涼無路之地；","notes":[]},{"n":41,"t":"卻將窮乏人安置在高處，脫離苦難，使他的家屬多如羊群。","notes":[]},{"n":42,"t":"正直的人看見就歡喜，罪孽之輩卻要啞口無言。","notes":[]},{"n":43,"t":"凡有智慧的必在這些事上留心，他必思想耶和華的慈愛。","notes":[]}]},"108":{"heading":"抗敵求助","verses":[{"n":1,"t":"神啊，我心堅定；我口要唱詩歌頌！","notes":["「口」：原文是「榮耀」。"]},{"n":2,"t":"琴瑟啊，當醒起！我要喚起曙光！","notes":[]},{"n":3,"t":"耶和華啊，我要在萬民中稱謝你，在萬族中歌頌你！","notes":[]},{"n":4,"t":"因為你的慈愛大過諸天，你的信實達到穹蒼。","notes":[]},{"n":5,"t":"神啊，願你崇高過於諸天！願你的榮耀高過全地！","notes":[]},{"n":6,"t":"求你應允我，用右手施行拯救，好讓你所親愛的人得救。","notes":[]},{"n":7,"t":"神在他的聖所說：「我要歡樂；要劃分示劍，丈量疏割谷。","notes":["「在他的聖所」或譯「指著他的聖潔」。"]},{"n":8,"t":"基列是我的，瑪拿西是我的，以法蓮是護衛我頭的，猶大是我的權杖。","notes":[]},{"n":9,"t":"摩押是我的沐浴盆，我要向以東扔鞋，我必因勝非利士而歡呼。」","notes":[]},{"n":10,"t":"誰能領我進堅固城？誰能引我到以東地？","notes":[]},{"n":11,"t":"神啊，你真的丟棄了我們嗎？神啊，你不和我們的軍隊同去嗎？","notes":[]},{"n":12,"t":"求你幫助我們攻擊敵人，因為人的幫助是枉然的。","notes":[]},{"n":13,"t":"我們倚靠神才得施展大能，因為踐踏我們敵人的就是他。","notes":[]}]},"109":{"heading":"遭難者的訴苦","verses":[{"n":1,"t":"我所讚美的神啊，求你不要閉口不言。","notes":[]},{"n":2,"t":"因為惡人的嘴和詭詐人的口張開攻擊我，他們用撒謊的舌頭對我說話。","notes":[]},{"n":3,"t":"他們圍繞我，說怨恨的話，又無故地攻打我。","notes":[]},{"n":4,"t":"他們與我作對回報我的愛，但我專心祈禱。","notes":[]},{"n":5,"t":"他們向我以惡報善，以恨報愛。","notes":[]},{"n":6,"t":"求你派惡人轄制他，派對頭站在他右邊！","notes":[]},{"n":7,"t":"他受審判的時候，願他背負罪名而出！願他的祈禱反成為罪！","notes":[]},{"n":8,"t":"願他的年歲短少！願別人得他的職分！","notes":[]},{"n":9,"t":"願他的兒女成為孤兒，他的妻子成為寡婦！","notes":[]},{"n":10,"t":"願他的兒女飄流討飯，從荒涼之處出來求乞！","notes":["「從荒涼之處出來求乞」：七十士譯本是「願他們從荒涼之處被趕出來」。"]},{"n":11,"t":"願債主牢籠他一切所有的！願陌生人搶走他勞碌得來的！","notes":[]},{"n":12,"t":"願無人向他佈施恩惠，無人恩待他的孤兒！","notes":[]},{"n":13,"t":"願他的後人斷絕，名字被塗去，不傳於下代！","notes":[]},{"n":14,"t":"願耶和華記得他祖宗的罪孽，不塗去他母親的罪過！","notes":[]},{"n":15,"t":"願這些罪常在耶和華面前！願他們的名字從地上除滅！","notes":["「名字」：原文是「紀念」。"]},{"n":16,"t":"因為他從未想過要施恩，卻迫害困苦貧窮的和傷心的人，把他們處死。","notes":[]},{"n":17,"t":"他愛咒罵，咒罵就臨到他；他不喜愛祝福，祝福就遠離他！","notes":[]},{"n":18,"t":"他拿咒罵當衣服穿上；這咒罵就如水進到他裏面，如油進入他骨頭。","notes":[]},{"n":19,"t":"願這咒罵當他遮身的衣服，作他經常束腰的帶子！","notes":[]},{"n":20,"t":"這就是那些與我作對、用惡言議論我的人從耶和華所受的報應。","notes":[]},{"n":21,"t":"但是你，主－耶和華啊，求你因你的名採取行動；因你的慈愛美好，求你搭救我！","notes":[]},{"n":22,"t":"因為我困苦貧窮，內心受傷。","notes":[]},{"n":23,"t":"我如日影偏斜而去，如蝗蟲被抖出來。","notes":[]},{"n":24,"t":"我因禁食，膝蓋軟弱；我身體消瘦，不再豐潤。","notes":[]},{"n":25,"t":"我受他們的羞辱，他們看見我就搖頭。","notes":[]},{"n":26,"t":"耶和華－我的神啊，求你幫助我，照你的慈愛拯救我，","notes":[]},{"n":27,"t":"好讓他們知道這是你的手，是你－耶和華所做的事。","notes":[]},{"n":28,"t":"任憑他們咒罵，你卻要賜福；他們幾時起來就必蒙羞，你的僕人卻要歡喜。","notes":[]},{"n":29,"t":"願與我作對的人披戴羞辱！願他們以自己的羞愧作外袍遮身！","notes":[]},{"n":30,"t":"我要用口極力稱謝耶和華，我要在眾人中間讚美他；","notes":[]},{"n":31,"t":"因為他必站在貧窮人的右邊，救他脫離定他死罪的人。","notes":[]}]},"110":{"heading":"耶和華所揀選之王","verses":[{"n":1,"t":"耶和華對我主說：「你坐在我的右邊，等我使你仇敵作你的腳凳。」","notes":[]},{"n":2,"t":"耶和華必使你從錫安伸出你能力的權杖；你務要在仇敵中掌權。","notes":[]},{"n":3,"t":"你在聖山上掌權的日子，你的子民必甘心跟隨；從晨曦初現，你就有清晨的甘露。","notes":["「聖山上」或譯「聖潔妝飾中」。","「你的子民必甘心跟隨」：七十士譯本是「你必有王子的尊嚴」。","「清晨」：原文是「青春」。"]},{"n":4,"t":"耶和華起了誓，絕不改變：「你是照著麥基洗德的體系永遠為祭司。」","notes":[]},{"n":5,"t":"在你右邊的主，當他發怒的日子，必打傷列王。","notes":[]},{"n":6,"t":"他要審判列國，屍首就佈滿各處；他要痛擊遍地的領袖。","notes":[]},{"n":7,"t":"他要喝路旁的河水，因此必抬起頭來。","notes":[]}]},"111":{"heading":"讚美耶和華","verses":[{"n":1,"t":"哈利路亞！我要在正直人的大會和會眾中一心稱謝耶和華。","notes":[]},{"n":2,"t":"耶和華的作為本為大，被所有喜愛的人所探尋。","notes":[]},{"n":3,"t":"他所做的是尊榮和威嚴，他的公義存到永遠。","notes":[]},{"n":4,"t":"他行了奇事，使人記念；耶和華有恩惠，有憐憫。","notes":[]},{"n":5,"t":"他賜糧食給敬畏他的人，他必永遠記念他的約。","notes":[]},{"n":6,"t":"他向百姓顯出大能的作為，將列國賜給他們為業。","notes":[]},{"n":7,"t":"他手所做的信實公平，他的訓詞全然可靠，","notes":[]},{"n":8,"t":"是永永遠遠堅定的，是按信實正直設立的。","notes":[]},{"n":9,"t":"他向百姓施行救贖，頒佈他的約，直到永遠；他的名聖而可畏。","notes":[]},{"n":10,"t":"敬畏耶和華是智慧的開端，凡遵行他命令的有美好的見識。耶和華是永遠當讚美的！","notes":[]}]},"112":{"heading":"義人之福","verses":[{"n":1,"t":"哈利路亞！敬畏耶和華，甚喜愛他命令的，這人有福了！","notes":[]},{"n":2,"t":"他的後裔在世必強盛，正直人的後代必蒙福。","notes":[]},{"n":3,"t":"他的家中有金銀財寶，他的義行存到永遠。","notes":[]},{"n":4,"t":"正直人在黑暗中有光向他照耀，他有恩惠，有憐憫，有公義。","notes":[]},{"n":5,"t":"施恩與人、借貸與人、秉公處事的人必享美福，","notes":[]},{"n":6,"t":"他永不動搖。義人被記念，直到永遠。","notes":[]},{"n":7,"t":"他不懼怕兇惡的信息，他的心堅定，倚靠耶和華。","notes":[]},{"n":8,"t":"他的心確定，總不懼怕，直到他看見敵人遭報。","notes":[]},{"n":9,"t":"他施捨，賙濟貧窮，他的義行存到永遠，他的角必被高舉，大有榮耀。","notes":[]},{"n":10,"t":"惡人看見就憤怒，必咬牙而消亡，惡人的心願要歸於幻滅。","notes":[]}]},"113":{"heading":"讚美耶和華的良善","verses":[{"n":1,"t":"哈利路亞！耶和華的僕人哪，你們要讚美，讚美耶和華的名！","notes":[]},{"n":2,"t":"耶和華的名是應當稱頌的，從今時直到永遠！","notes":[]},{"n":3,"t":"從日出之地到日落之處，耶和華的名是應當讚美的！","notes":[]},{"n":4,"t":"耶和華超乎萬國之上，他的榮耀高過諸天。","notes":[]},{"n":5,"t":"誰像耶和華－我們的神呢？他坐在至高之處，","notes":[]},{"n":6,"t":"自己謙卑，觀看天上地下的事。","notes":[]},{"n":7,"t":"他從灰塵裏抬舉貧寒的人，從糞堆中提拔貧窮的人，","notes":[]},{"n":8,"t":"使他們與貴族同坐，與本國的貴族同坐。","notes":[]},{"n":9,"t":"他使不孕的婦女安居家中，成為快樂的母親，兒女成群。哈利路亞！","notes":[]}]},"114":{"heading":"逾越節之歌","verses":[{"n":1,"t":"以色列出埃及，雅各家離開說陌生語言之民時，","notes":[]},{"n":2,"t":"猶大作主的聖所，以色列為他所治理的國。","notes":[]},{"n":3,"t":"滄海看見就奔逃，約旦河也倒流。","notes":[]},{"n":4,"t":"大山踴躍如公羊，小山跳舞如羔羊。","notes":[]},{"n":5,"t":"滄海啊，你為何奔逃？約旦哪，你為何倒流？","notes":[]},{"n":6,"t":"大山哪，你為何踴躍如公羊？小山哪，你為何跳舞如羔羊？","notes":[]},{"n":7,"t":"大地啊，在主的面前，在雅各的神的面前，震動吧！","notes":[]},{"n":8,"t":"他叫磐石變為水池，使堅石變為泉源。","notes":[]}]},"115":{"heading":"獨一真神","verses":[{"n":1,"t":"耶和華啊，榮耀不要歸與我們，不要歸與我們；要因你的慈愛和信實歸在你的名下！","notes":[]},{"n":2,"t":"為何讓列國說「他們的神在哪裏」呢？","notes":[]},{"n":3,"t":"但是，我們的神在天上，萬事都隨自己的旨意而行。","notes":[]},{"n":4,"t":"他們的偶像是金的，是銀的，是人手所造的，","notes":[]},{"n":5,"t":"有口卻不能言，有眼卻不能看，","notes":[]},{"n":6,"t":"有耳卻不能聽，有鼻卻不能聞，","notes":[]},{"n":7,"t":"有手卻不能摸，有腳卻不能走，有喉卻不能說話。","notes":[]},{"n":8,"t":"造它們的要像它們一樣，凡靠它們的也必如此。","notes":[]},{"n":9,"t":"以色列啊，要倚靠耶和華！他是人的幫助和盾牌。","notes":[]},{"n":10,"t":"亞倫家啊，要倚靠耶和華！他是人的幫助和盾牌。","notes":[]},{"n":11,"t":"敬畏耶和華的人哪，要倚靠耶和華！他是人的幫助和盾牌。","notes":[]},{"n":12,"t":"耶和華向來眷念我們，他還要賜福，賜福給以色列家，賜福給亞倫家。","notes":[]},{"n":13,"t":"凡敬畏耶和華的，無論大小，主必賜福給他。","notes":[]},{"n":14,"t":"願耶和華使你們和你們的子孫日見增加。","notes":[]},{"n":15,"t":"你們蒙了耶和華的福，他是創造天地的主宰。","notes":[]},{"n":16,"t":"天，是耶和華的天；地，他卻給了世人。","notes":[]},{"n":17,"t":"死人不能讚美耶和華，下到寂靜中的也都不能。","notes":["「寂靜」就是「死亡」。"]},{"n":18,"t":"但我們要稱頌耶和華，從今時直到永遠。哈利路亞！","notes":[]}]},"116":{"heading":"為出死入生讚美神","verses":[{"n":1,"t":"我愛耶和華，因為他聽了我的聲音和我的懇求。","notes":[]},{"n":2,"t":"他既向我側耳，我一生要求告他。","notes":[]},{"n":3,"t":"死亡的繩索勒住我，陰間的痛苦抓住我，我遭遇患難愁苦。","notes":[]},{"n":4,"t":"那時，我求告耶和華的名：「耶和華啊，求你救我！」","notes":[]},{"n":5,"t":"耶和華有恩惠，有公義，我們的神有憐憫。","notes":[]},{"n":6,"t":"耶和華保護愚蒙的人；我落到卑微的地步，他救了我。","notes":[]},{"n":7,"t":"我的心哪！你要復歸安寧，因為耶和華用厚恩待你。","notes":[]},{"n":8,"t":"主啊，你救我的命脫離死亡，使我的眼不再流淚，使我的腳不致跌倒。","notes":[]},{"n":9,"t":"我行在耶和華面前，走在活人之地。","notes":[]},{"n":10,"t":"我信，儘管我說：「我受了極大的困苦。」","notes":[]},{"n":11,"t":"我曾驚惶地說：「人都是說謊的！」","notes":[]},{"n":12,"t":"耶和華向我賞賜一切厚恩，我拿甚麼來報答他呢？","notes":[]},{"n":13,"t":"我要舉起救恩的杯，稱揚耶和華的名。","notes":[]},{"n":14,"t":"我要在他的全體百姓面前向耶和華還我所許的願。","notes":[]},{"n":15,"t":"在耶和華眼中，聖民之死極為寶貴。","notes":[]},{"n":16,"t":"耶和華啊，哦，我是你的僕人；我是你的僕人，是你使女的兒子。你已經解開我的捆索。","notes":[]},{"n":17,"t":"我要以感謝為祭獻給你，又要求告耶和華的名。","notes":[]},{"n":18,"t":"我要在耶路撒冷當中，在耶和華殿的院內，在他的全體百姓面前，向耶和華還我所許的願。哈利路亞！","notes":[],"end":19}]},"117":{"heading":"讚美耶和華","verses":[{"n":1,"t":"萬國啊，你們要讚美耶和華！萬族啊，你們都要頌讚他！","notes":[]},{"n":2,"t":"因為他向我們大施慈愛，耶和華的信實存到永遠。哈利路亞！","notes":[]}]},"118":{"heading":"因勝利而稱謝耶和華","verses":[{"n":1,"t":"你們要稱謝耶和華，因他本為善；他的慈愛永遠長存！","notes":[]},{"n":2,"t":"願以色列說：「他的慈愛永遠長存！」","notes":[]},{"n":3,"t":"願亞倫家說：「他的慈愛永遠長存！」","notes":[]},{"n":4,"t":"願敬畏耶和華的人說：「他的慈愛永遠長存！」","notes":[]},{"n":5,"t":"我在急難中求告耶和華，耶和華就應允我，把我安置在寬闊之地。","notes":[]},{"n":6,"t":"耶和華在我這邊，我必不懼怕，人能把我怎麼樣呢？","notes":["「耶和華在我這邊」：七十士譯本是「主是我的幫助」。"]},{"n":7,"t":"在那幫助我的人中，有耶和華幫助我，所以我要看見那些恨我的人遭報。","notes":[]},{"n":8,"t":"投靠耶和華，強似倚賴人；","notes":[]},{"n":9,"t":"投靠耶和華，強似倚賴權貴。","notes":[]},{"n":10,"t":"列邦圍繞我，我靠耶和華的名必剿滅他們。","notes":[]},{"n":11,"t":"他們圍繞我，圍困我，我靠耶和華的名必剿滅他們。","notes":[]},{"n":12,"t":"他們如同蜜蜂一般地圍繞我，他們熄滅，好像燒荊棘的火；我靠耶和華的名，必剿滅他們。","notes":[]},{"n":13,"t":"你用力推我，要叫我跌倒，但耶和華幫助了我。","notes":[]},{"n":14,"t":"耶和華是我的力量，是我的詩歌，他也成了我的拯救。","notes":[]},{"n":15,"t":"在義人的帳棚裏，有歡呼拯救的聲音，耶和華的右手施展大能。","notes":[]},{"n":16,"t":"耶和華的右手高舉，耶和華的右手施展大能。","notes":[]},{"n":17,"t":"我不至於死，仍要存活，並要傳揚耶和華的作為。","notes":[]},{"n":18,"t":"耶和華雖嚴嚴地懲治我，卻未曾將我交於死亡。","notes":[]},{"n":19,"t":"給我敞開義門，我要進去稱謝耶和華！","notes":[]},{"n":20,"t":"這是耶和華的門，義人要進去！","notes":[]},{"n":21,"t":"我要稱謝你，因為你已經應允我，又成了我的拯救！","notes":[]},{"n":22,"t":"匠人所丟棄的石頭已成了房角的頭塊石頭。","notes":[]},{"n":23,"t":"這是耶和華所做的，在我們眼中看為奇妙。","notes":[]},{"n":24,"t":"這是耶和華所定的日子，我們在其中要高興歡喜！","notes":[]},{"n":25,"t":"耶和華啊，求你拯救！耶和華啊，求你使我們順利！","notes":["「求你拯救」：原文音譯「和散那」。"]},{"n":26,"t":"奉耶和華的名來的是應當稱頌的！我們從耶和華的殿中為你們祝福！","notes":[]},{"n":27,"t":"耶和華是神，他光照了我們。你們要用繩索把祭牲拴住，直牽到壇角。","notes":[]},{"n":28,"t":"你是我的神，我要稱謝你！我的神啊，我要尊崇你！","notes":["「我要尊崇你」：七十士譯本是「我要尊崇你！我要稱謝你，因為你已經應允我，又成了我的拯救」。"]},{"n":29,"t":"你們要稱謝耶和華，因他本為善；他的慈愛永遠長存！","notes":[]}]},"119":{"heading":"耶和華的律法","verses":[{"n":1,"t":"行為正直、遵行耶和華律法的，這人有福了！","notes":[]},{"n":2,"t":"遵守他的法度、一心尋求他的，這人有福了！","notes":[]},{"n":3,"t":"他們不做不義的事，但遵行他的道。","notes":[]},{"n":4,"t":"耶和華啊，你曾將你的訓詞吩咐我們，為要我們切實遵守。","notes":[]},{"n":5,"t":"但願我行事堅定，得以遵守你的律例。","notes":[]},{"n":6,"t":"我看重你的一切命令，就不致羞愧。","notes":[]},{"n":7,"t":"我學習你公義的典章，要以正直的心稱謝你。","notes":[]},{"n":8,"t":"我必遵守你的律例，求你不要把我全然棄絕！","notes":[]},{"n":9,"t":"青年要如何保持純潔呢？是要遵行你的話！","notes":[],"heads":["順從耶和華的律法"]},{"n":10,"t":"我曾一心尋求你，求你不要使我偏離你的命令。","notes":[]},{"n":11,"t":"我將你的話藏在心裏，免得我得罪你。","notes":[]},{"n":12,"t":"耶和華啊，你是應當稱頌的！求你將你的律例教導我！","notes":[]},{"n":13,"t":"我用嘴唇傳揚你口中一切的典章。","notes":[]},{"n":14,"t":"我喜愛你的法度，如同喜愛一切的財物。","notes":[]},{"n":15,"t":"我要默想你的訓詞，看重你的道路。","notes":[]},{"n":16,"t":"我要以你的律例為樂，我不忘記你的話。","notes":[]},{"n":17,"t":"求你用厚恩待你的僕人，使我存活，我就遵守你的話。","notes":[],"heads":["因耶和華律法而蒙福"]},{"n":18,"t":"求你開我的眼睛，使我看出你律法中的奇妙。","notes":[]},{"n":19,"t":"我在地上是寄居的人，求你不要向我隱藏你的命令！","notes":[]},{"n":20,"t":"我時常切慕你的典章，耗盡心力。","notes":[]},{"n":21,"t":"受詛咒、偏離你命令的驕傲人，你已經責備他們。","notes":[]},{"n":22,"t":"求你除掉我所受的羞辱和藐視，因我遵守你的法度。","notes":[]},{"n":23,"t":"雖有掌權者坐著妄論我，你僕人卻思想你的律例。","notes":[]},{"n":24,"t":"你的法度也是我的喜樂，我的導師。","notes":["「我的導師」：七十士譯本是「你的律例是我的導師」。"]},{"n":25,"t":"我的性命幾乎歸於塵土，求你照你的話將我救活！","notes":[],"heads":["決意遵行耶和華的律法"]},{"n":26,"t":"我述說我所做的，你應允了我；求你將你的律例教導我！","notes":[]},{"n":27,"t":"求你使我明白你的訓詞，我要默想你的奇事。","notes":[]},{"n":28,"t":"我因愁苦身心耗盡，求你照你的話使我堅立！","notes":[]},{"n":29,"t":"求你使我離開奸詐的道路，開恩將你的律法賜給我！","notes":[]},{"n":30,"t":"我選擇了忠信的道路，將你的典章擺在我面前。","notes":[]},{"n":31,"t":"我持守你的法度；耶和華啊，求你不要叫我羞愧！","notes":[]},{"n":32,"t":"你使我心胸開闊的時候，我就往你命令的道路直奔。","notes":[]},{"n":33,"t":"耶和華啊，求你將你的律例指教我，我必遵守到底！","notes":[],"heads":["求主賜悟性"]},{"n":34,"t":"求你賜我悟性，我就遵守你的律法，且要一心遵守。","notes":[]},{"n":35,"t":"求你叫我遵行你的命令，因為這是我所喜愛的。","notes":[]},{"n":36,"t":"求你使我的心趨向你的法度，不趨向不義之財。","notes":[]},{"n":37,"t":"求你叫我轉眼不看虛假，使我活在你的道路中。","notes":["「道路」：有古卷是「話」。"]},{"n":38,"t":"求你向敬畏你的僕人堅守你的話！","notes":[]},{"n":39,"t":"求你使我所懼怕的羞辱遠離我，因你的典章本為美。","notes":[]},{"n":40,"t":"看哪，我切慕你的訓詞，求你因你的公義賜我生命！","notes":["「因你...生命」或譯「求你使我活在你的公義中」。"]},{"n":41,"t":"耶和華啊，求你使你的慈愛臨到我，照你的話使你的救恩臨到我，","notes":[],"heads":["倚靠耶和華的律法"]},{"n":42,"t":"我就有話回答那羞辱我的，因我倚靠你的話。","notes":[]},{"n":43,"t":"求你叫真理的話總不離開我的口，因我仰望你的典章。","notes":[]},{"n":44,"t":"我要常守你的律法，直到永永遠遠。","notes":[]},{"n":45,"t":"我要自由而行，因我尋求了你的訓詞。","notes":["「自由而行」或譯「行在寬闊之地」。"]},{"n":46,"t":"我要在列王面前宣講你的法度，也不致羞愧。","notes":[]},{"n":47,"t":"我以你的命令為樂，這命令是我所喜愛的。","notes":[]},{"n":48,"t":"我向我所愛的，就是你的命令高舉雙手，我也要默想你的律例。","notes":["「我向...雙手」或譯「我要遵行我所愛的，就是你的命令」。"]},{"n":49,"t":"求你記念你向僕人所說的話，這話使我有盼望。","notes":[],"heads":["因耶和華的律法而安穩"]},{"n":50,"t":"你的話將我救活了；這是我在患難中的安慰。","notes":[]},{"n":51,"t":"驕傲的人極度地侮慢我，我卻未曾偏離你的律法。","notes":[]},{"n":52,"t":"耶和華啊，我記念你從古以來的典章，就得了安慰。","notes":[]},{"n":53,"t":"我因惡人離棄你的律法，怒火中燒。","notes":[]},{"n":54,"t":"我在世寄居，以你的律例為詩歌。","notes":[]},{"n":55,"t":"耶和華啊，我夜間記念你的名，我也要遵守你的律法。","notes":[]},{"n":56,"t":"這臨到我，是因我謹守你的訓詞。","notes":[]},{"n":57,"t":"耶和華是我的福分；我曾說，我要遵守你的話。","notes":[],"heads":["深愛耶和華的律法"]},{"n":58,"t":"我一心懇求你的面，求你照你的話憐憫我！","notes":[]},{"n":59,"t":"我思想自己所行的道路，我的腳步就轉向你的法度。","notes":[]},{"n":60,"t":"我速速遵守你的命令，並不遲延。","notes":[]},{"n":61,"t":"惡人的繩索纏繞我，我卻沒有忘記你的律法。","notes":[]},{"n":62,"t":"我因你公義的典章，夜半起來稱謝你。","notes":[]},{"n":63,"t":"凡敬畏你、守你訓詞的人，我都與他作伴。","notes":[]},{"n":64,"t":"耶和華啊，遍地滿了你的慈愛；求你將你的律例教導我！","notes":[]},{"n":65,"t":"耶和華啊，你照你的話，善待你的僕人。","notes":[],"heads":["耶和華律法的寶貴"]},{"n":66,"t":"求你教我明辨和知識，因我信靠你的命令。","notes":[]},{"n":67,"t":"我未受苦以先曾經迷失，現在卻遵守你的話。","notes":[]},{"n":68,"t":"你本為善，所行的也善；求你將你的律例教導我！","notes":[]},{"n":69,"t":"驕傲的人編造謊言攻擊我，我卻要一心遵守你的訓詞。","notes":[]},{"n":70,"t":"他們的心蒙昧如蒙油脂，我卻喜愛你的律法。","notes":[]},{"n":71,"t":"我受苦是與我有益，為要使我學習你的律例。","notes":[]},{"n":72,"t":"你口中的律法與我有益，勝於千萬金銀。","notes":[]},{"n":73,"t":"你的手造了我，塑造我；求你賜我悟性學習你的命令！","notes":[],"heads":["耶和華律法的公正"]},{"n":74,"t":"敬畏你的人看見我就歡喜，因我仰望你的話。","notes":[]},{"n":75,"t":"耶和華啊，我知道你的典章是公義的；你使我受苦是以信實待我。","notes":[]},{"n":76,"t":"求你照著你向僕人所說的話，以慈愛安慰我。","notes":[]},{"n":77,"t":"求你的憐憫臨到我，使我存活，因你的律法是我的喜樂。","notes":[]},{"n":78,"t":"願驕傲的人蒙羞，因為他們無理傾覆我；但我要默想你的訓詞。","notes":[]},{"n":79,"t":"願敬畏你的人和知道你法度的人都歸向我。","notes":["本節或譯「願敬畏你的人都歸向我，他們就知道你的法度。」"]},{"n":80,"t":"願我的心在你的律例上完全，使我不致蒙羞。","notes":[]},{"n":81,"t":"我渴想你的救恩身心耗盡，我仰望你的話。","notes":[],"heads":["求主解救"]},{"n":82,"t":"我因渴望你的話眼睛失明，說：「你何時安慰我呢？」","notes":[]},{"n":83,"t":"我雖像煙薰的皮囊，卻不忘記你的律例。","notes":[]},{"n":84,"t":"你僕人的年日有多少呢？你幾時向迫害我的人施行審判呢？","notes":[]},{"n":85,"t":"不順從你律法的驕傲人為我掘了坑。","notes":[]},{"n":86,"t":"你的命令盡都信實；他們無理迫害我，求你幫助我！","notes":[]},{"n":87,"t":"他們幾乎把我從世上除滅；但我沒有離棄你的訓詞。","notes":[]},{"n":88,"t":"求你照你的慈愛將我救活，我就遵守你口中的法度。","notes":[]},{"n":89,"t":"耶和華啊，你的話安定在天，直到永遠。","notes":[],"heads":["信賴耶和華的律法"]},{"n":90,"t":"你的信實存到萬代；你堅立了地，地就長存。","notes":[]},{"n":91,"t":"天地照你的典章存到今日；萬物都是你的僕役。","notes":[]},{"n":92,"t":"我若不以你的律法為樂，早就在苦難中滅絕了！","notes":[]},{"n":93,"t":"我永不忘記你的訓詞，因你用這訓詞將我救活。","notes":[]},{"n":94,"t":"我是屬你的，求你救我，因我尋求了你的訓詞。","notes":[]},{"n":95,"t":"惡人等著要滅絕我，我卻要揣摩你的法度。","notes":[]},{"n":96,"t":"我看萬事盡都有限，惟有你的命令極其寬廣。","notes":[]},{"n":97,"t":"我何等愛慕你的律法，終日不住地思想。","notes":[],"heads":["喜愛耶和華的律法"]},{"n":98,"t":"你的命令常存在我心裏，使我比仇敵有智慧。","notes":[]},{"n":99,"t":"我比我的教師更通達，因我思想你的法度。","notes":[]},{"n":100,"t":"我比年老的更明白，因我謹守你的訓詞。","notes":[]},{"n":101,"t":"我阻止我的腳走一切邪路，為要遵守你的話。","notes":[]},{"n":102,"t":"我沒有偏離你的典章，因為你教導了我。","notes":[]},{"n":103,"t":"你的言語在我上膛何等甘美，在我口中比蜜更甜！","notes":[]},{"n":104,"t":"我藉著你的訓詞得以明白，因此，我恨惡一切虛假的行徑。","notes":[]},{"n":105,"t":"你的話是我腳前的燈，是我路上的光。","notes":[],"heads":["耶和華律法的亮光"]},{"n":106,"t":"你公義的典章，我曾起誓遵守，我必按著誓言而行。","notes":[]},{"n":107,"t":"我極其痛苦；耶和華啊，求你照你的話將我救活！","notes":[]},{"n":108,"t":"耶和華啊，求你悅納我口中的讚美為甘心祭，又將你的典章教導我！","notes":[]},{"n":109,"t":"我的性命常在我手掌中，我卻不忘記你的律法。","notes":["「性命常在我手掌中」意思是「危險」。"]},{"n":110,"t":"惡人為我設下羅網，我卻沒有偏離你的訓詞。","notes":[]},{"n":111,"t":"我以你的法度為永遠的產業，因這是我心中所喜愛的。","notes":[]},{"n":112,"t":"我的心傾向你的律例，謹守到底，直到永遠。","notes":[]},{"n":113,"t":"心懷二意的人為我所恨；但你的律法為我所愛。","notes":[],"heads":["因耶和華律法得安全"]},{"n":114,"t":"你是我藏身之處，是我的盾牌；我仰望你的話。","notes":[]},{"n":115,"t":"作惡的人哪，你們離開我吧！我要遵守我神的命令。","notes":[]},{"n":116,"t":"求你照你的話扶持我，使我存活，不要叫我因失望而蒙羞。","notes":[]},{"n":117,"t":"求你扶持我，使我得救，時常看重你的律例。","notes":[]},{"n":118,"t":"凡偏離你律例的人，你都輕看他們，因為他們的詭詐必歸虛空。","notes":[]},{"n":119,"t":"你除掉地上所有的惡人，好像除掉渣滓；因此我喜愛你的法度。","notes":["「你除掉...渣滓」：有古卷和古譯本是「在你看來惡人好像渣滓」。"]},{"n":120,"t":"我因懼怕你，肉體戰慄；我害怕你的典章。","notes":[]},{"n":121,"t":"我行公平和公義，求你不要撇下我，交給欺壓我的人！","notes":[],"heads":["遵從耶和華的律法"]},{"n":122,"t":"求你保證你的僕人得福，不容驕傲的人欺壓我！","notes":[]},{"n":123,"t":"我因盼望你的救恩和你公義的言語眼睛失明。","notes":[]},{"n":124,"t":"求你照你的慈愛待僕人，將你的律例教導我。","notes":[]},{"n":125,"t":"我是你的僕人，求你賜我悟性，得以認識你的法度。","notes":[]},{"n":126,"t":"這是耶和華採取行動的時候，因人廢棄了你的律法。","notes":[]},{"n":127,"t":"所以，我喜愛你的命令勝於金子，更勝於純金。","notes":[]},{"n":128,"t":"你的一切訓詞，在萬事上我都以為正直；我恨惡一切虛假的行徑。","notes":[]},{"n":129,"t":"你的法度奇妙，所以我一心謹守。","notes":[],"heads":["渴慕遵行耶和華的律法"]},{"n":130,"t":"你的話一開啟就發出亮光，使愚蒙人通達。","notes":[]},{"n":131,"t":"我大大張口，呼吸急促，因我切慕你的命令。","notes":[]},{"n":132,"t":"求你轉向我，憐憫我，就像你待那些喜愛你名的人。","notes":[]},{"n":133,"t":"求你用你的言語使我腳步穩健，不容罪孽轄制我。","notes":[]},{"n":134,"t":"求你救我脫離人的欺壓，我要遵守你的訓詞。","notes":[]},{"n":135,"t":"求你使你的臉向僕人發光，又將你的律例教導我。","notes":[]},{"n":136,"t":"我的眼睛流淚成河，因為他們不守你的律法。","notes":[]},{"n":137,"t":"耶和華啊，你是公義的；你的典章正直！","notes":[],"heads":["耶和華律法的公正"]},{"n":138,"t":"你所頒佈的法度是公義的，極其可靠。","notes":[]},{"n":139,"t":"我的狂熱把我燒滅，因我敵人忘記你的話。","notes":[]},{"n":140,"t":"你的言語極其精煉，令你僕人喜愛。","notes":[]},{"n":141,"t":"我渺小，被人藐視，卻不忘記你的訓詞。","notes":[]},{"n":142,"t":"你的公義永遠公義，你的律法是確實的。","notes":[]},{"n":143,"t":"我遭遇患難愁苦，你的命令是我的喜樂。","notes":[]},{"n":144,"t":"你的法度永遠公義；求你賜我悟性，使我存活。","notes":[]},{"n":145,"t":"耶和華啊，我一心呼求你，求你應允我！我必謹守你的律例。","notes":[],"heads":["求主解救"]},{"n":146,"t":"我向你呼求，求你救我！我要遵守你的法度。","notes":[]},{"n":147,"t":"天尚未亮我呼喊求救，我仰望你的話。","notes":[]},{"n":148,"t":"我終夜雙眼睜開，為要思想你的言語。","notes":[]},{"n":149,"t":"求你按你的慈愛聽我的聲音，耶和華啊，求你照你的典章將我救活！","notes":[]},{"n":150,"t":"追逐奸惡的人迫近了，他們遠離你的律法。","notes":["「追逐奸惡的人」：有古卷和古譯本是「以奸惡追逐我的人」。"]},{"n":151,"t":"耶和華啊，你就在我身邊，你一切的命令是確實的！","notes":[]},{"n":152,"t":"我從你的法度早已知道，這法度是你永遠立定的。","notes":[]},{"n":153,"t":"求你看顧我的苦難，搭救我，因我不忘記你的律法。","notes":[],"heads":["請求恩助"]},{"n":154,"t":"求你為我的冤屈辯護，救贖我，照你的言語將我救活。","notes":[]},{"n":155,"t":"救恩遠離惡人，因為他們不尋求你的律例。","notes":[]},{"n":156,"t":"耶和華啊，你的憐憫本為大；求你照你的典章將我救活。","notes":[]},{"n":157,"t":"迫害我的、抵擋我的甚多，我卻沒有偏離你的法度。","notes":[]},{"n":158,"t":"我看見奸惡的人就憎惡，因為他們不遵守你的言語。","notes":[]},{"n":159,"t":"你看我何等喜愛你的訓詞！耶和華啊，求你按你的慈愛將我救活！","notes":[]},{"n":160,"t":"你話語的精髓是真實的，你一切公義的典章永遠長存。","notes":[]},{"n":161,"t":"掌權者無故迫害我，然而我的心畏懼你的話。","notes":[],"heads":["熱愛耶和華的律法"]},{"n":162,"t":"我喜愛你的言語，好像人得到許多戰利品。","notes":[]},{"n":163,"t":"我恨惡，憎惡虛假；惟喜愛你的律法。","notes":[]},{"n":164,"t":"我因你公義的典章一天七次讚美你。","notes":[]},{"n":165,"t":"喜愛你律法的人大有平安，任何事都不能使他們跌倒。","notes":[]},{"n":166,"t":"耶和華啊，我仰望你的救恩，遵行你的命令。","notes":[]},{"n":167,"t":"我心謹守你的法度，這法度我極其喜愛。","notes":[]},{"n":168,"t":"我遵守你的訓詞和法度，因我所行的道路都在你的面前。","notes":[]},{"n":169,"t":"耶和華啊，願我的呼求達到你面前，求你照你的話賜我悟性。","notes":[],"heads":["求主幫助"]},{"n":170,"t":"願我的懇求達到你面前，求你照你的言語搭救我。","notes":[]},{"n":171,"t":"願我的嘴唇發出讚美，因為你將律例教導我。","notes":[]},{"n":172,"t":"願我的舌頭歌唱你的言語，因你一切的命令盡都公義。","notes":[]},{"n":173,"t":"求你用你的手幫助我，因我選擇你的訓詞。","notes":[]},{"n":174,"t":"耶和華啊，我切慕你的救恩！你的律法是我的喜樂。","notes":[]},{"n":175,"t":"願我的性命存活，得以讚美你！願你的典章幫助我！","notes":[]},{"n":176,"t":"我走迷了路如同失喪的羊，求你尋找你的僕人，因我不忘記你的命令。","notes":[]}]},"120":{"heading":"求主恩助","verses":[{"n":1,"t":"我在急難中求告耶和華，他就應允我。","notes":[]},{"n":2,"t":"耶和華啊，求你救我脫離說謊的嘴唇和詭詐的舌頭！","notes":[]},{"n":3,"t":"詭詐的舌頭啊，他會給你甚麼呢？會加給你甚麼呢？","notes":[]},{"n":4,"t":"就是勇士的利箭、羅騰木的炭火。","notes":["「羅騰木」為小樹名，松類。"]},{"n":5,"t":"禍哉！我寄居在米設，住在基達帳棚之中。","notes":[]},{"n":6,"t":"我與那恨惡和平的人許久同住。","notes":[]},{"n":7,"t":"我願和平，當我發言，他們卻要戰爭。","notes":[]}]},"121":{"heading":"耶和華是我們的保護者","verses":[{"n":1,"t":"我要向山舉目，我的幫助從何而來？","notes":[]},{"n":2,"t":"我的幫助從造天地的耶和華而來。","notes":[]},{"n":3,"t":"他不叫你的腳搖動，保護你的必不打盹！","notes":[]},{"n":4,"t":"保護以色列的必不打盹，也不睡覺。","notes":[]},{"n":5,"t":"保護你的是耶和華，耶和華在你右邊蔭庇你。","notes":[]},{"n":6,"t":"白日，太陽必不傷你；夜間，月亮也不害你。","notes":[]},{"n":7,"t":"耶和華要保護你，免受一切的災害，他要保護你的性命。","notes":[]},{"n":8,"t":"你出你入，耶和華要保護你，從今時直到永遠。","notes":[]}]},"122":{"heading":"耶路撒冷頌","verses":[{"n":1,"t":"我喜樂，因人對我說：「我們到耶和華的殿去。」","notes":[]},{"n":2,"t":"耶路撒冷啊，我們的腳站在你門內。","notes":[]},{"n":3,"t":"耶路撒冷被建造，如同連結整齊的一座城。","notes":[]},{"n":4,"t":"眾支派就是耶和華的支派，上那裏去，按以色列的法度頌揚耶和華的名。","notes":[]},{"n":5,"t":"他們在那裏設立審判的寶座，就是大衛家的寶座。","notes":[]},{"n":6,"t":"你們要為耶路撒冷求平安：「願愛你的人興旺！","notes":[]},{"n":7,"t":"願你城中有平安！願你宮內得平靜！」","notes":[]},{"n":8,"t":"為我弟兄和同伴的緣故，我要說：「願你平安！」","notes":[]},{"n":9,"t":"為耶和華－我們神殿的緣故，我要為你求福！","notes":[]}]},"123":{"heading":"求主憐憫","verses":[{"n":1,"t":"坐在天上的主啊，我向你舉目。","notes":[]},{"n":2,"t":"看哪，僕人的眼睛怎樣仰望主人的手，婢女的眼睛怎樣仰望女主人的手，我們的眼睛也照樣仰望耶和華－我們的神，直到他憐憫我們。","notes":[]},{"n":3,"t":"耶和華啊，求你憐憫我們，憐憫我們！因為我們受盡了藐視。","notes":[]},{"n":4,"t":"我們受盡了安逸人的譏誚和驕傲人的藐視。","notes":[]}]},"124":{"heading":"神保護他的子民","verses":[{"n":1,"t":"說吧，以色列：「若不是耶和華幫助我們，","notes":[]},{"n":2,"t":"若不是耶和華幫助我們，當人起來攻擊我們，","notes":[]},{"n":3,"t":"那時，人向我們發怒，就把我們活活吞了；","notes":[]},{"n":4,"t":"那時，波濤必漫過我們，河水必淹沒我們；","notes":[]},{"n":5,"t":"那時，狂傲的水必淹沒我們。」","notes":[]},{"n":6,"t":"耶和華是應當稱頌的！他沒有把我們交給他們，作牙齒的獵物。","notes":[]},{"n":7,"t":"我們好像雀鳥，從捕鳥人的羅網裏逃脫，羅網破裂，我們就逃脫了。","notes":[]},{"n":8,"t":"我們得幫助，是因造天地之耶和華的名。","notes":[]}]},"125":{"heading":"耶和華子民的安全","verses":[{"n":1,"t":"倚靠耶和華的人好像錫安山，安穩坐鎮，永不動搖。","notes":[]},{"n":2,"t":"眾山怎樣圍繞耶路撒冷，耶和華也照樣圍繞他的百姓，從今時直到永遠。","notes":[]},{"n":3,"t":"惡人的杖必不在義人的土地上停留，免得義人伸手作惡。","notes":[]},{"n":4,"t":"耶和華啊，求你善待行善和心裏正直的人。","notes":[]},{"n":5,"t":"至於那偏行彎曲道路的人，耶和華必將他們和作惡的人一同驅逐出去。願平安歸於以色列！","notes":[]}]},"126":{"heading":"被擄歸回者的歡樂","verses":[{"n":1,"t":"當耶和華使錫安被擄的人歸回的時候，我們好像做夢的人。","notes":[]},{"n":2,"t":"那時，我們滿口喜笑、滿舌歡呼；那時，列國中就有人說：「耶和華為他們行了大事！」","notes":[]},{"n":3,"t":"耶和華果然為我們行了大事，我們就歡喜。","notes":[]},{"n":4,"t":"耶和華啊，求你使我們這些被擄的人歸回，好像尼革夫的河水復流。","notes":["「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」。"]},{"n":5,"t":"流淚撒種的，必歡呼收割！","notes":[]},{"n":6,"t":"那帶種流淚出去的，必歡呼地帶禾捆回來！","notes":[]}]},"127":{"heading":"稱頌神的良善","verses":[{"n":1,"t":"若不是耶和華建造房屋，建造的人就枉然勞力；若不是耶和華看守城池，看守的人枉然警醒。","notes":[]},{"n":2,"t":"你們清晨早起，夜晚安歇，吃勞碌得來的飯，本是枉然；惟有耶和華所親愛的，必叫他安然睡覺。","notes":[]},{"n":3,"t":"看哪，兒女是耶和華所賜的產業，所懷的胎是他所給的賞賜。","notes":[]},{"n":4,"t":"人在年輕時生的兒女好像勇士手中的箭。","notes":[]},{"n":5,"t":"箭袋充滿的人有福了！他們在城門口和仇敵爭論時必不蒙羞。","notes":[]}]},"128":{"heading":"順從耶和華的報償","verses":[{"n":1,"t":"凡敬畏耶和華、遵行他道的人有福了！","notes":[]},{"n":2,"t":"你要吃勞碌得來的；你要享福，凡事順利。","notes":[]},{"n":3,"t":"你妻子在你內室，好像多結果子的葡萄樹；你兒女圍繞你的桌子，如同橄欖樹苗。","notes":[]},{"n":4,"t":"看哪，敬畏耶和華的人必要這樣蒙福！","notes":[]},{"n":5,"t":"願耶和華從錫安賜福給你！願你一生一世看見耶路撒冷興旺！","notes":[]},{"n":6,"t":"願你看見你的子子孫孫！願平安歸於以色列！","notes":[]}]},"129":{"heading":"求耶和華退敵","verses":[{"n":1,"t":"說吧，以色列：「從我幼年以來，人屢次苦害我；","notes":[]},{"n":2,"t":"從我幼年以來，人屢次苦害我，卻沒有勝過我。","notes":[]},{"n":3,"t":"扶犁的人在我背上扶犁而耕，耕的犁溝很長。」","notes":[]},{"n":4,"t":"耶和華是公義的，他砍斷了惡人的繩索。","notes":[]},{"n":5,"t":"願恨惡錫安的都蒙羞退後！","notes":[]},{"n":6,"t":"願他們像房頂上的草，一發芽就枯乾，","notes":[]},{"n":7,"t":"收割的不夠用手抓一把，捆禾的也不夠抱滿懷。","notes":[]},{"n":8,"t":"過路的也不說：「願耶和華所賜的福歸與你們！我們奉耶和華的名給你們祝福！」","notes":[]}]},"130":{"heading":"求助的祈禱","verses":[{"n":1,"t":"耶和華啊，我從深處求告你！","notes":[]},{"n":2,"t":"主啊，求你聽我的聲音！求你側耳聽我懇求的聲音！","notes":[]},{"n":3,"t":"耶和華啊，你若究察罪孽，主啊，誰能站得住呢？","notes":[]},{"n":4,"t":"但在你有赦免之恩，要叫人敬畏你。","notes":[]},{"n":5,"t":"我等候耶和華，我的心等候；我也仰望他的話。","notes":[]},{"n":6,"t":"我的心等候主，勝於守夜的等候天亮，勝於守夜的等候天亮。","notes":[]},{"n":7,"t":"以色列啊，你當仰望耶和華，因耶和華有慈愛，有豐盛的救恩。","notes":[]},{"n":8,"t":"他必救贖以色列脫離一切的罪孽。","notes":[]}]},"131":{"heading":"謙卑靠主","verses":[{"n":1,"t":"耶和華啊，我的心不狂妄，我的眼不高傲；重大和測不透的事，我也不敢行。","notes":[]},{"n":2,"t":"我使我心安穩平靜，好像母親懷中斷奶的孩子；我的心在我裏面如同斷過奶的孩子。","notes":[]},{"n":3,"t":"以色列啊，你當仰望耶和華，從今時直到永遠！","notes":[]}]},"132":{"heading":"聖殿頌","verses":[{"n":1,"t":"耶和華啊，求你記念大衛，記念他所受的一切苦難！","notes":[]},{"n":2,"t":"他怎樣向耶和華起誓，向雅各的大能者許願：","notes":[]},{"n":3,"t":"「我必不進我的帳幕，也不上我的床鋪；","notes":[]},{"n":4,"t":"我不容我的眼睛睡覺，也不容我的眼皮打盹；","notes":[]},{"n":5,"t":"直等到我為耶和華尋得所在，為雅各的大能者尋得居所。」","notes":[]},{"n":6,"t":"我們聽說約櫃在以法他，我們在雅珥的田野尋見它。","notes":["「雅珥」曾譯「基列‧耶琳」；「雅珥」意思是「森林」。"]},{"n":7,"t":"「我們要進他的居所，在他腳凳前下拜。」","notes":[]},{"n":8,"t":"耶和華啊，求你興起，與你有能力的約櫃同入安歇之所！","notes":[]},{"n":9,"t":"願你的祭司披上公義！願你的聖民歡呼！","notes":[]},{"n":10,"t":"求你因你僕人大衛的緣故，不要厭棄你的受膏者！","notes":[]},{"n":11,"t":"耶和華憑信實向大衛起了誓，絕不改變：「我要立你身所生的坐在你的寶座上。","notes":[]},{"n":12,"t":"你的眾子若謹守我的約和我所教導他們的法度，他們的子孫必永遠坐在你的寶座上。」","notes":[]},{"n":13,"t":"因為耶和華揀選了錫安，願意當作自己的居所：","notes":[]},{"n":14,"t":"「這是我永遠安歇之所；我要住在這地方，因為我願意在這裏。","notes":[]},{"n":15,"t":"我要賜福使糧食豐足，使其中的貧窮人飽享食物。","notes":[]},{"n":16,"t":"我要使祭司披上救恩，聖民就要大聲歡呼！","notes":[]},{"n":17,"t":"在那裏我要使大衛的角茁壯，為我的受膏者預備明燈。","notes":[]},{"n":18,"t":"我要使他的仇敵披上羞恥；但他的冠冕要在他頭上發光。」","notes":[]}]},"133":{"heading":"弟兄相愛頌","verses":[{"n":1,"t":"看哪，弟兄和睦同住是何等的善，何等的美！","notes":[]},{"n":2,"t":"這好比那貴重的油澆在亞倫的頭上，流到鬍鬚，又流到他的衣襟；","notes":[]},{"n":3,"t":"又好比黑門的甘露降在錫安山；因為在那裏有耶和華所命定的福，就是永遠的生命。","notes":[]}]},"134":{"heading":"宣召稱頌","verses":[{"n":1,"t":"來，稱頌耶和華！夜間侍立在耶和華殿中，耶和華的僕人，","notes":[]},{"n":2,"t":"當向聖所舉手，稱頌耶和華！","notes":[]},{"n":3,"t":"願造天地的耶和華從錫安賜福給你們！","notes":[]}]},"135":{"heading":"稱頌的聖詩","verses":[{"n":1,"t":"哈利路亞！你們要讚美耶和華的名！侍立在耶和華殿中，耶和華的僕人，侍立在我們神殿院中的，要讚美他！","notes":[],"end":2},{"n":3,"t":"你們要讚美耶和華，因耶和華本為善；要歌頌他的名，因為這是美好的。","notes":[]},{"n":4,"t":"耶和華揀選雅各歸自己，揀選以色列作他寶貴的產業。","notes":[]},{"n":5,"t":"我知道耶和華本為大，也知道我們的主超乎萬神之上。","notes":[]},{"n":6,"t":"在天，在地，在海洋，在各深淵，耶和華都隨自己的旨意而行。","notes":[]},{"n":7,"t":"他使雲霧從地極上騰，造電隨雨而閃，從倉庫中吹出風來。","notes":[]},{"n":8,"t":"他將埃及頭生的，連人帶牲畜都擊殺了。","notes":[]},{"n":9,"t":"埃及啊，他施行神蹟奇事，在你們中間，在法老和他所有臣僕身上。","notes":[]},{"n":10,"t":"他擊打許多國家，殺戮大能的君王，","notes":[]},{"n":11,"t":"就是亞摩利王西宏、巴珊王噩，和迦南一切的國度，","notes":[]},{"n":12,"t":"他賞賜他們的地為業，作為自己百姓以色列的產業。","notes":[]},{"n":13,"t":"耶和華啊，你的名字存到永遠！耶和華啊，你的稱號存到萬代！","notes":["「稱號」：原文是「紀念」。"]},{"n":14,"t":"耶和華要為自己的百姓伸冤，為自己的僕人發憐憫。","notes":[]},{"n":15,"t":"外邦的偶像是金的，是銀的，是人手所造的，","notes":[]},{"n":16,"t":"有口卻不能言，有眼卻不能看，","notes":[]},{"n":17,"t":"有耳卻不能聽，口中也沒有氣息。","notes":[]},{"n":18,"t":"造它們的要像它們一樣，凡靠它們的也必如此。","notes":[]},{"n":19,"t":"以色列家啊，要稱頌耶和華！亞倫家啊，要稱頌耶和華！","notes":[]},{"n":20,"t":"利未家啊，要稱頌耶和華！你們敬畏耶和華的，要稱頌耶和華！","notes":[]},{"n":21,"t":"住在耶路撒冷的、錫安的耶和華，是應當稱頌的。哈利路亞！","notes":[]}]},"136":{"heading":"感恩的聖詩","verses":[{"n":1,"t":"你們要稱謝耶和華，因他本為善；他的慈愛永遠長存。","notes":[]},{"n":2,"t":"你們要稱謝萬神之神，因他的慈愛永遠長存。","notes":[]},{"n":3,"t":"你們要稱謝萬主之主，因他的慈愛永遠長存。","notes":[]},{"n":4,"t":"稱謝那惟一能行大奇事的，因他的慈愛永遠長存。","notes":["死海古卷和七十士譯本沒有「大」。"]},{"n":5,"t":"稱謝那用智慧造天的，因他的慈愛永遠長存。","notes":[]},{"n":6,"t":"稱謝那鋪地在水以上的，因他的慈愛永遠長存。","notes":[]},{"n":7,"t":"稱謝那造成大光的，因他的慈愛永遠長存。","notes":[]},{"n":8,"t":"他造太陽管白晝，因他的慈愛永遠長存。","notes":[]},{"n":9,"t":"他造月亮星宿管黑夜，因他的慈愛永遠長存。","notes":[]},{"n":10,"t":"稱謝那擊殺埃及凡是頭生的，因他的慈愛永遠長存。","notes":[]},{"n":11,"t":"他以大能的手和伸出來的膀臂，因他的慈愛永遠長存。領以色列人從埃及人中出來，因他的慈愛永遠長存。","notes":[],"end":12},{"n":13,"t":"稱謝那分裂紅海的，因他的慈愛永遠長存。","notes":[]},{"n":14,"t":"他領以色列從其中經過，因他的慈愛永遠長存；","notes":[]},{"n":15,"t":"卻把法老和他的軍隊推落紅海裏，因他的慈愛永遠長存。","notes":[]},{"n":16,"t":"稱謝那引導自己子民行走曠野的，因他的慈愛永遠長存。","notes":[]},{"n":17,"t":"稱謝那擊殺大君王的，因他的慈愛永遠長存。","notes":[]},{"n":18,"t":"他殺戮威武的君王，因他的慈愛永遠長存；","notes":[]},{"n":19,"t":"殺戮亞摩利王西宏，因他的慈愛永遠長存；","notes":[]},{"n":20,"t":"殺戮巴珊王噩，因他的慈愛永遠長存。","notes":[]},{"n":21,"t":"他賞賜他們的地為業，因他的慈愛永遠長存；","notes":[]},{"n":22,"t":"作為他僕人以色列的產業，因他的慈愛永遠長存。","notes":[]},{"n":23,"t":"我們身處卑微，他顧念我們，因他的慈愛永遠長存。","notes":[]},{"n":24,"t":"他搭救我們脫離敵人，因他的慈愛永遠長存。","notes":[]},{"n":25,"t":"凡有血有肉的，他賜糧食，因他的慈愛永遠長存。","notes":[]},{"n":26,"t":"你們要稱謝天上的神，因他的慈愛永遠長存。","notes":[]}]},"137":{"heading":"被擄的哀歌","verses":[{"n":1,"t":"我們在巴比倫河邊，坐在那裏，追想錫安，就哭了。","notes":[]},{"n":2,"t":"在一排柳樹中，我們掛上我們的豎琴。","notes":[]},{"n":3,"t":"擄掠我們的在那裏要我們唱歌；搶奪我們的要我們為他們作樂：「給我們唱一首錫安的歌吧！」","notes":[]},{"n":4,"t":"我們怎能在外邦之土唱耶和華的歌呢？","notes":[]},{"n":5,"t":"耶路撒冷啊，我若忘記你，寧願我的右手枯萎；","notes":[]},{"n":6,"t":"我若不記得你，不看你過於我最喜樂的，寧願我的舌頭貼於上膛！","notes":[]},{"n":7,"t":"耶路撒冷攻破的日子，以東人說：「拆毀！拆毀！直拆到根基！」耶和華啊，求你記得！","notes":[]},{"n":8,"t":"將要被滅的巴比倫哪，用你待我們的惡行報復你的，那人有福了。","notes":["「巴比倫」：原文直譯「巴比倫女子」。"]},{"n":9,"t":"抓起你的嬰孩摔在磐石上的，那人有福了。","notes":[]}]},"138":{"heading":"感恩之禱","verses":[{"n":1,"t":"我要一心稱謝你，在諸神面前歌頌你。","notes":["「我要一心稱謝你」：有古卷和古譯本是「耶和華啊！我要一心稱謝你」。"]},{"n":2,"t":"我要向你的聖殿下拜，我要因你的慈愛和信實頌揚你的名；因你使你的名和你的言語顯為大，超乎一切。","notes":["「因你...一切」：原文是「因你使你的言語大過你一切的名聲」。"]},{"n":3,"t":"我呼求的日子，你應允我，使我壯膽，心裏有能力。","notes":[]},{"n":4,"t":"耶和華啊，地上的君王都要稱謝你，因他們聽見了你口中的言語。","notes":[]},{"n":5,"t":"他們要歌頌耶和華的作為，因耶和華大有榮耀。","notes":[]},{"n":6,"t":"耶和華雖崇高，卻看顧卑微的人；驕傲的人，他從遠處即能認出。","notes":[]},{"n":7,"t":"我雖困在患難中，你必將我救活；我的仇敵發怒，你必伸手抵擋他們，你的右手也必拯救我。","notes":[]},{"n":8,"t":"耶和華必成全他在我身上的旨意；耶和華啊，你的慈愛永遠長存！求你不要離棄你手所造的。","notes":[]}]},"139":{"heading":"耶和華的全知和眷顧","verses":[{"n":1,"t":"耶和華啊，你已經鑒察我，認識我。","notes":[]},{"n":2,"t":"我坐下，我起來，你都曉得；你從遠處知道我的意念。","notes":[]},{"n":3,"t":"我行路，我躺臥，你都細察；你也深知我一切所行的。","notes":[]},{"n":4,"t":"耶和華啊，我舌頭上的話，你沒有一句不知道的。","notes":[]},{"n":5,"t":"你前後環繞我，按手在我身上。","notes":[]},{"n":6,"t":"這樣的知識奇妙，是我不能測的；至高，是我不能及的。","notes":[]},{"n":7,"t":"我往哪裏去，躲避你的靈？我往哪裏逃，躲避你的面？","notes":[]},{"n":8,"t":"我若升到天上，你在那裏；我若躺在陰間，你也在那裏。","notes":[]},{"n":9,"t":"我若展開清晨的翅膀，飛到海極居住，","notes":[]},{"n":10,"t":"就是在那裏，你的手必引導我，你的右手也必扶持我。","notes":[]},{"n":11,"t":"我若說「黑暗必定壓碎我，我周圍的亮光必成為黑夜」，","notes":[]},{"n":12,"t":"黑暗對你不再是黑暗，黑夜卻如白晝發亮。黑暗和光明，在你看來都是一樣。","notes":[]},{"n":13,"t":"我的肺腑是你所造的，我在母腹中，你已編織我。","notes":["「編織」或譯「覆庇」。"]},{"n":14,"t":"我要稱謝你，因我受造奇妙可畏，你的作為奇妙，這是我心深知道的。","notes":[]},{"n":15,"t":"我在暗中受造，在地的深處被塑造；那時，我的形體並不向你隱藏。","notes":[]},{"n":16,"t":"我未成形的體質，你的眼早已看見了；你所定的日子，我尚未度一日，都在你的冊子寫上了。","notes":[]},{"n":17,"t":"神啊，你的意念向我何等寶貴！其數何等眾多！","notes":[]},{"n":18,"t":"我若數點，比海沙更多；我睡醒的時候，仍和你同在。","notes":[]},{"n":19,"t":"神啊，惟願你殺戮惡人；你們好流人血的，離開我去吧！","notes":[]},{"n":20,"t":"他們說惡言頂撞你，你的仇敵妄稱你的名。","notes":["原文沒有「你的名」。"]},{"n":21,"t":"耶和華啊，恨惡你的，我豈不恨惡他們嗎？攻擊你的，我豈不憎惡他們嗎？","notes":[]},{"n":22,"t":"我恨惡他們到極點，以他們為我的仇敵。","notes":[]},{"n":23,"t":"神啊，求你鑒察我，知道我的心思，試煉我，知道我的意念；","notes":[]},{"n":24,"t":"看在我裏面有甚麼惡行沒有，引導我走永生的道路。","notes":[]}]},"140":{"heading":"求耶和華護佑","verses":[{"n":1,"t":"耶和華啊，求你救我脫離邪惡的人，保護我脫離殘暴的人！","notes":[]},{"n":2,"t":"他們心中圖謀奸惡，日日不停挑起戰爭。","notes":[]},{"n":3,"t":"他們的舌頭銳利如蛇，嘴唇裏有毒蛇的毒液。（細拉）","notes":[]},{"n":4,"t":"耶和華啊，求你庇護我脫離惡人的手，保護我脫離殘暴的人，他們想要推倒我。","notes":[]},{"n":5,"t":"驕傲的人為我暗設羅網和繩索；他們在路旁張開網，為我設下圈套。（細拉）","notes":[]},{"n":6,"t":"我曾對耶和華說：「你是我的神。」耶和華啊，求你側耳聽我懇求的聲音！","notes":[]},{"n":7,"t":"主－耶和華、我救恩的力量啊，在戰爭的日子，你遮蔽了我的頭。","notes":[]},{"n":8,"t":"耶和華啊，求你不要遂惡人的心願；不要成就他們的計謀，免得他們自高。（細拉）","notes":[]},{"n":9,"t":"至於那些昂首圍困我的人，願他們嘴唇的奸惡陷害自己！","notes":["「陷害」：原文是「遮蔽」。"]},{"n":10,"t":"願他們被丟在火中，火炭落在他們身上；願他們被拋在深坑裏，不能再起來！","notes":[]},{"n":11,"t":"願說惡言的人在地上站立不住；願禍患獵取殘暴的人，把他打倒。","notes":[]},{"n":12,"t":"我知道耶和華必為困苦人伸冤，為貧窮人辯護。","notes":[]},{"n":13,"t":"義人必頌揚你的名，正直人要在你面前居住。","notes":[]}]},"141":{"heading":"晚 禱","verses":[{"n":1,"t":"耶和華啊，我曾求告你，求你快快臨到我這裏！我求告你的時候，求你側耳聽我的聲音！","notes":[]},{"n":2,"t":"願我的禱告如香呈到你面前！願我的手舉起，如獻晚祭！","notes":["「手舉起」：在此有「獻供物」的意思。"]},{"n":3,"t":"耶和華啊，求你看守我的口，把守我的嘴唇！","notes":[]},{"n":4,"t":"不要使我的心偏向邪惡的事，以致我和作惡的人一同行惡；也不叫我吃他們的美食。","notes":[]},{"n":5,"t":"任憑義人擊打我，這算為仁慈；任憑他責備我，這算為頭上的膏油；我的頭不躲閃。人正行惡的時候，我仍要祈禱。","notes":[]},{"n":6,"t":"他們的審判官被扔在巖下，他們就要聽我的話，因為這話甘甜。","notes":[]},{"n":7,"t":"我們的骨頭散落在陰間的口，就像人耕田刨地一樣。","notes":["「我們的」：有古譯本是「他們的」。","「人耕田刨地」：原文另譯「磨石破裂」。"]},{"n":8,"t":"主－耶和華啊，我的眼目仰望你；我投靠你，求你不要使我的性命陷入危險！","notes":[]},{"n":9,"t":"求你保護我脫離惡人為我設的羅網和作惡之人的圈套！","notes":[]},{"n":10,"t":"願惡人落在自己的網中，我卻得以逃脫。","notes":[]}]},"142":{"heading":"求主眷顧","verses":[{"n":1,"t":"我出聲哀告耶和華，出聲懇求耶和華。","notes":[]},{"n":2,"t":"我在他面前傾訴我的苦情，在他面前陳說我的患難。","notes":[]},{"n":3,"t":"我的靈在我裏面發昏的時候，你知道我的道路。在我所行的路上，人為我暗設羅網。","notes":[]},{"n":4,"t":"求你留意向我右邊觀看，無人認識我；我無避難之處，也無人眷顧我。","notes":[]},{"n":5,"t":"耶和華啊，我曾向你哀求。我說：「你是我的避難所，在活人之地，你是我的福分。」","notes":[]},{"n":6,"t":"求你留心聽我的呼求，因我落到極卑微之地；求你救我脫離迫害我的人，因為他們比我強盛。","notes":[]},{"n":7,"t":"求你從被囚之地領我出來，我好頌揚你的名。義人必環繞我，因為你用厚恩待我。","notes":[]}]},"143":{"heading":"求主拯救","verses":[{"n":1,"t":"耶和華啊，求你聽我的禱告，側耳聽我的懇求，憑你的信實和公義應允我。","notes":[]},{"n":2,"t":"求你不要審問僕人，因為在你面前，凡活著的人沒有一個是義的。","notes":[]},{"n":3,"t":"因為仇敵迫害我，將我打倒在地，使我住在幽暗之處，像死了許久的人一樣。","notes":[]},{"n":4,"t":"我的靈在我裏面發昏，我的心在我裏面顫慄。","notes":[]},{"n":5,"t":"我追想古時之日，思想你的一切作為，默念你手的工作。","notes":[]},{"n":6,"t":"我向你舉手，我的心渴想你，如乾旱之地盼雨一樣。（細拉）","notes":[]},{"n":7,"t":"耶和華啊，求你速速應允我！我的心神耗盡！求你不要轉臉不顧我，免得我像那些下入地府的人一樣。","notes":[]},{"n":8,"t":"求你使我清晨得聽你慈愛的聲音，因我倚靠你；求你使我知道當走的路，因我的心仰望你。","notes":[]},{"n":9,"t":"耶和華啊，求你救我脫離我的仇敵！我往你那裏藏身。","notes":[]},{"n":10,"t":"求你指教我遵行你的旨意，因你是我的神；願你至善的靈引我到平坦之地。","notes":[]},{"n":11,"t":"耶和華啊，求你為你名的緣故將我救活，憑你的公義，將我從患難中領出來，","notes":[]},{"n":12,"t":"憑你的慈愛剪除我的仇敵，滅絕所有苦待我的人，因我是你的僕人。","notes":[]}]},"144":{"heading":"君王為勝利感恩","verses":[{"n":1,"t":"耶和華─我的磐石是應當稱頌的！他教導我的手爭戰，教導我的指頭打仗。","notes":[]},{"n":2,"t":"他是我慈愛的主、我的山寨、我的碉堡、我的救主、我的盾牌，是我所投靠的。他使我的百姓服在我以下。","notes":["「我的百姓」：有古卷是「列邦」。"]},{"n":3,"t":"耶和華啊，人算甚麼，你竟認識他！世人算甚麼，你竟顧念他！","notes":[]},{"n":4,"t":"人不過像一口氣，他的年日如影消逝。","notes":[]},{"n":5,"t":"耶和華啊，求你使天下垂，親自降臨；求你摸山，使山冒煙。","notes":[]},{"n":6,"t":"求你發出閃電，使仇敵四散，射出你的箭，使他們混亂。","notes":[]},{"n":7,"t":"求你從高處伸手救拔我，救我脫離大水，脫離外邦人的手。","notes":[]},{"n":8,"t":"他們的口說謊話，他們的右手起假誓。","notes":[]},{"n":9,"t":"神啊，我要向你唱新歌，用十弦瑟向你歌頌。","notes":[]},{"n":10,"t":"你是那拯救君王的，你是那救僕人大衛脫離害命之刀的。","notes":[]},{"n":11,"t":"求你救拔我，救我脫離外邦人的手。他們的口說謊話，他們的右手起假誓。","notes":[]},{"n":12,"t":"我們的兒子從幼年好像樹苗長大，我們的女兒如同房角石，按照建宮殿的樣式鑿成。","notes":[]},{"n":13,"t":"我們的倉盈滿，能供應各種糧食；我們的羊在田野孳生千萬。","notes":[]},{"n":14,"t":"我們的牲口馱滿貨物，沒有人闖進來搶奪，也沒有人出去爭戰；我們的街市上也沒有哭號的聲音。","notes":[]},{"n":15,"t":"這樣情況的百姓有福了！以耶和華為他們神的百姓有福了！","notes":[]}]},"145":{"heading":"稱頌之歌","verses":[{"n":1,"t":"我的神、我的王啊、我要尊崇你！我要永永遠遠稱頌你的名！","notes":[]},{"n":2,"t":"我要天天稱頌你，也要永永遠遠讚美你的名！","notes":[]},{"n":3,"t":"耶和華本為大，該受大讚美，其大無法測度。","notes":[]},{"n":4,"t":"這一代要對那一代頌讚你的作為，他們要傳揚你的大能。","notes":[]},{"n":5,"t":"他們要述說你威嚴榮耀的尊榮，我要默念你奇妙的作為。","notes":["本節根據死海古卷；原文是「我要默念你威嚴榮耀的尊榮和你奇妙的作為」。"]},{"n":6,"t":"人要傳講你可畏的能力，我也要傳揚你的偉大。","notes":[]},{"n":7,"t":"他們要將你可記念的大恩傳開，並要高唱你的公義。","notes":[]},{"n":8,"t":"耶和華有恩惠，有憐憫，不輕易發怒，大有慈愛。","notes":[]},{"n":9,"t":"耶和華善待萬有，他的憐憫覆庇他一切所造的。","notes":[]},{"n":10,"t":"耶和華啊，你一切所造的都要稱謝你，你的聖民也要稱頌你。","notes":[]},{"n":11,"t":"他們要傳講你國度的榮耀，談論你的大能，","notes":[]},{"n":12,"t":"好讓世人知道你大能的作為和你國度威嚴的榮耀。","notes":[]},{"n":13,"t":"你的國是永遠的國！你執掌的權柄存到萬代！耶和華一切的話信實可靠，他一切的作為都有慈愛。","notes":["「耶和華...慈愛」是根據死海古卷、七十士譯本和其他古譯本；原文無此句。"]},{"n":14,"t":"耶和華扶起所有跌倒的，扶起所有被壓下的。","notes":[]},{"n":15,"t":"萬有的眼目都仰望你，你按時給他們食物。","notes":[]},{"n":16,"t":"你張手，使一切有生命的都隨願飽足。","notes":[]},{"n":17,"t":"耶和華一切所行的，無不公義，一切所做的，都有慈愛。","notes":[]},{"n":18,"t":"耶和華臨近凡求告他的，臨近所有誠心求告他的人。","notes":[]},{"n":19,"t":"敬畏他的，他必成就他們的心願，也必聽他們的呼求，拯救他們。","notes":[]},{"n":20,"t":"耶和華保護凡愛他的人，卻要滅絕所有的惡人。","notes":[]},{"n":21,"t":"我的口要述說讚美耶和華的話；惟願有血肉之軀的都永永遠遠稱頌他的聖名。","notes":[]}]},"146":{"heading":"讚美耶和華的救助","verses":[{"n":1,"t":"哈利路亞！我的心哪，你要讚美耶和華！","notes":[]},{"n":2,"t":"我一生要讚美耶和華！我還活著的時候要歌頌我的神！","notes":[]},{"n":3,"t":"你們不要倚靠君王，不要倚靠世人，他一點也不能幫助。","notes":[]},{"n":4,"t":"他的氣一斷，就歸回塵土，他所打算的，當日就消滅了。","notes":[]},{"n":5,"t":"以雅各的神為幫助、仰望耶和華－他神的，這人有福了！","notes":[]},{"n":6,"t":"耶和華造天、地、海和其中的萬物，他守信實，直到永遠。","notes":[]},{"n":7,"t":"他為受欺壓的伸冤，賜食物給飢餓的人。耶和華釋放被囚的，","notes":[]},{"n":8,"t":"耶和華開了盲人的眼睛，耶和華扶起被壓下的人，耶和華喜愛義人。","notes":[]},{"n":9,"t":"耶和華保護寄居的，扶持孤兒和寡婦，卻使惡人的道路彎曲。","notes":[]},{"n":10,"t":"耶和華要作王，直到永遠！錫安哪，你的神要作王，直到萬代！哈利路亞！","notes":[]}]},"147":{"heading":"讚美神的全能","verses":[{"n":1,"t":"哈利路亞！歌頌我們的神是美善的，因為他是美好的，讚美他是合宜的。","notes":[]},{"n":2,"t":"耶和華建造耶路撒冷，聚集以色列中被趕散的人。","notes":[]},{"n":3,"t":"他醫好傷心的人，包紮他們的傷處。","notes":[]},{"n":4,"t":"他數點星宿的數目，一一稱它們的名。","notes":[]},{"n":5,"t":"我們的主本為大，大有能力，他的智慧無法測度。","notes":[]},{"n":6,"t":"耶和華扶持謙卑的人，將惡人傾覆於地。","notes":[]},{"n":7,"t":"你們要以感謝向耶和華歌唱，用琴向我們的神歌頌。","notes":[]},{"n":8,"t":"他用密雲遮天，為地預備雨水，使草生長在山上。","notes":[]},{"n":9,"t":"他賜食物給走獸和啼叫的小烏鴉。","notes":[]},{"n":10,"t":"他不喜悅馬的力大，不喜愛人的腿快。","notes":[]},{"n":11,"t":"耶和華喜愛敬畏他和盼望他慈愛的人。","notes":[]},{"n":12,"t":"耶路撒冷啊，要頌讚耶和華！錫安哪，要讚美你的神！","notes":[]},{"n":13,"t":"因為他堅固了你的門閂，賜福給你中間的兒女。","notes":[]},{"n":14,"t":"他使你境內平安，用上好的麥子使你滿足。","notes":[]},{"n":15,"t":"他向大地發出命令，他的話速速頒行。","notes":[]},{"n":16,"t":"他降雪如羊毛，撒霜如灰燼。","notes":[]},{"n":17,"t":"他擲下冰雹如碎渣，他發出寒冷，誰能當得起呢？","notes":[]},{"n":18,"t":"他一出令，這些就都融化，他使風颳起，水便流動。","notes":[]},{"n":19,"t":"他將他的道指示雅各，將他的律例典章指示以色列。","notes":[]},{"n":20,"t":"他未曾這樣對待別國，至於他的典章，他們向來都不知道。哈利路亞！","notes":["「他們向來都不知道」：有古譯本是「他沒有讓他們知道」。"]}]},"148":{"heading":"宣召萬有讚美耶和華","verses":[{"n":1,"t":"哈利路亞！你們要從天上讚美耶和華，在高處讚美他！","notes":[]},{"n":2,"t":"他的眾使者啊，要讚美他！他的諸軍啊，都要讚美他！","notes":[]},{"n":3,"t":"太陽月亮啊，要讚美他！放光的星宿啊，都要讚美他！","notes":[]},{"n":4,"t":"天上的天和天上的水啊，你們都要讚美他！","notes":[]},{"n":5,"t":"願這些都讚美耶和華的名！因他一吩咐就都造成。","notes":[]},{"n":6,"t":"他將這些設定，直到永永遠遠；他訂了律例，不能廢去。","notes":[]},{"n":7,"t":"你們哪，都當讚美耶和華：地上一切所有的，大魚和深洋，","notes":[]},{"n":8,"t":"火和冰雹，雪和霧氣，成就他命令的狂風，","notes":[]},{"n":9,"t":"大山和小山，結果子的樹木和一切香柏樹，","notes":[]},{"n":10,"t":"野獸和一切牲畜，昆蟲和飛鳥，","notes":[]},{"n":11,"t":"世上的君王和萬民，領袖和世上所有的審判官，","notes":[]},{"n":12,"t":"少年和少女，老人和孩童，","notes":[]},{"n":13,"t":"願這些都讚美耶和華的名！因為獨有他的名被尊崇，他的榮耀在天地之上。","notes":[]},{"n":14,"t":"他高舉自己百姓的角，使他的聖民以色列人，就是與他相近的百姓得榮耀。哈利路亞！","notes":["「使...得榮耀」或譯「他一切聖民以色列人， 就是與他相近的百姓，都讚美他」。"]}]},"149":{"heading":"讚美的聖詩","verses":[{"n":1,"t":"哈利路亞！你們要向耶和華唱新歌，在聖民的會中讚美他！","notes":[]},{"n":2,"t":"願以色列因造他的主歡喜！願錫安的民因他們的王快樂！","notes":[]},{"n":3,"t":"願他們跳舞讚美他的名，擊鼓彈琴歌頌他！","notes":[]},{"n":4,"t":"因為耶和華喜愛自己的百姓，他要用救恩當作謙卑人的妝飾。","notes":[]},{"n":5,"t":"願聖民因所得的榮耀歡樂！願他們在床上也歡呼！","notes":[]},{"n":6,"t":"願他們口中稱頌神為至高，手裏有兩刃的劍，","notes":[]},{"n":7,"t":"為要報復列國，懲罰萬民。","notes":[]},{"n":8,"t":"要用鏈子捆他們的君王，用鐵鐐鎖他們的貴族，","notes":[]},{"n":9,"t":"要在他們身上施行所記錄的審判。他的聖民都享榮耀。哈利路亞！","notes":[]}]},"150":{"heading":"讚美耶和華","verses":[{"n":1,"t":"哈利路亞！你們要在神的聖所讚美他！在他顯能力的穹蒼讚美他！","notes":[]},{"n":2,"t":"要因他大能的作為讚美他，因他極其偉大讚美他！","notes":[]},{"n":3,"t":"要用角聲讚美他，鼓瑟彈琴讚美他！","notes":[]},{"n":4,"t":"擊鼓跳舞讚美他！用絲弦的樂器和簫的聲音讚美他！","notes":[]},{"n":5,"t":"用大響的鈸讚美他！用高聲的鈸讚美他！","notes":[]},{"n":6,"t":"凡有生命的都要讚美耶和華！哈利路亞！","notes":[]}]}},"PRO":{"1":{"heading":"箴言的價值","verses":[{"n":1,"t":"大衛的兒子，以色列王所羅門的箴言：","notes":[]},{"n":2,"t":"要使人懂得智慧和訓誨，明白通達的言語，","notes":[]},{"n":3,"t":"使人領受明智的訓誨，就是公義、公平和正直，","notes":[]},{"n":4,"t":"使愚蒙人靈巧，使年輕人有知識，有智謀。","notes":[]},{"n":5,"t":"智慧人聽見，增長學問，聰明人得著智謀，","notes":[]},{"n":6,"t":"明白箴言和譬喻，懂得智慧人的言詞和謎語。","notes":[]},{"n":7,"t":"敬畏耶和華是知識的開端；愚妄人藐視智慧和訓誨。","notes":[]},{"n":8,"t":"我兒啊，要聽你父親的訓誨，不可離棄你母親的教誨；","notes":[],"heads":["給年輕人的忠告"]},{"n":9,"t":"因為這要作你頭上恩惠的華冠，作你頸上的項鏈。","notes":[]},{"n":10,"t":"我兒啊，罪人若引誘你，你不可隨從。","notes":[]},{"n":11,"t":"他們若說：「你與我們同去，我們要埋伏殺人流血，無故地潛藏，殺害無辜；","notes":[]},{"n":12,"t":"我們好像陰間，把他們活活吞下，囫圇吞下，如吞下那下到地府的人；","notes":[]},{"n":13,"t":"我們必得各樣寶物，將所奪來的裝滿房屋；","notes":[]},{"n":14,"t":"你來與我們同夥，共用一個錢囊。」","notes":[]},{"n":15,"t":"我兒啊，不要與他們走同一道路，禁止你的腳走他們的路徑。","notes":[]},{"n":16,"t":"因為他們的腳奔跑行惡，他們急速殺人流血。","notes":[]},{"n":17,"t":"在飛鳥眼前張設網羅，一定會徒勞無功；","notes":[]},{"n":18,"t":"同樣，他們埋伏，是自流己血，他們潛藏，是自害己命。","notes":[]},{"n":19,"t":"凡靠暴力歛財的，所行之路都是如此，這種念頭必奪去自己的生命。","notes":[]},{"n":20,"t":"智慧在街市上呼喊，在廣場上高聲吶喊，","notes":["「智慧」是擬人化的名詞，原文是陰性；下同。"],"heads":["智慧呼喚人"]},{"n":21,"t":"在熱鬧街頭呼叫，在城門口，在城中，發出言語，說：","notes":[]},{"n":22,"t":"「你們無知的人喜愛無知，傲慢人喜歡傲慢，愚昧人恨惡知識，要到幾時呢？","notes":[]},{"n":23,"t":"你們當因我的責備回轉，我要將我的靈澆灌你們，將我的話指示你們。","notes":[]},{"n":24,"t":"因為我呼喚，你們不聽，我招手，無人理會。","notes":[]},{"n":25,"t":"你們忽視我一切的勸戒，拒聽我的責備。","notes":[]},{"n":26,"t":"你們遭難，我就發笑；驚恐臨到你們，驚恐如狂風來臨，災難好像暴風來到，急難痛苦臨到你們身上，我必嗤笑。","notes":[],"end":27},{"n":28,"t":"那時，他們就會呼求我，我卻不回答，懇切尋求我，卻尋不見。","notes":[]},{"n":29,"t":"因為他們恨惡知識，選擇不敬畏耶和華，","notes":[]},{"n":30,"t":"不聽我的勸戒，藐視我一切的責備，","notes":[]},{"n":31,"t":"所以他們要自食其果，飽脹在自己的計謀中。","notes":[]},{"n":32,"t":"愚蒙人背道，害死自己，愚昧人安逸，自取滅亡。","notes":[]},{"n":33,"t":"惟聽從我的，必安然居住，得享寧靜，不怕災禍。」","notes":[]}]},"2":{"heading":"智慧的賞賜","verses":[{"n":1,"t":"我兒啊，你若領受我的言語，珍藏我的命令，","notes":[]},{"n":2,"t":"留心聽智慧，專心求聰明；","notes":[]},{"n":3,"t":"你若呼求明理，揚聲求聰明，","notes":[]},{"n":4,"t":"尋找她，如尋找銀子，搜尋她，如搜尋寶藏，","notes":[]},{"n":5,"t":"你就懂得敬畏耶和華，得以認識神。","notes":[]},{"n":6,"t":"因為耶和華賞賜智慧，知識和聰明都由他口而出。","notes":[]},{"n":7,"t":"他為正直人珍藏健全的知識，給行為純正的人作盾牌，","notes":[]},{"n":8,"t":"為要保護公正的路，庇護虔誠人的道。","notes":[]},{"n":9,"t":"那時，你就明白公義、公平、正直，和一切完善的道路。","notes":[]},{"n":10,"t":"因為智慧要進入你的心，知識要使你內心歡愉。","notes":[]},{"n":11,"t":"智謀要庇護你，聰明必保護你，","notes":[]},{"n":12,"t":"救你脫離惡人的道，脫離言談乖謬的人。","notes":[]},{"n":13,"t":"他們離棄正直的路，行走黑暗的道，","notes":[]},{"n":14,"t":"喜歡作惡，喜愛惡人的錯謬。","notes":[]},{"n":15,"t":"他們的路歪曲，他們偏離中道。","notes":[]},{"n":16,"t":"智慧要救你遠離陌生女子，遠離那油嘴滑舌的外邦女子。","notes":[]},{"n":17,"t":"她離棄年輕時的配偶，忘了自己神聖的盟約。","notes":[]},{"n":18,"t":"她的家陷入死亡，她的路偏向陰魂。","notes":[]},{"n":19,"t":"凡到她那裏去的，不得回轉，也得不到生命的路。","notes":[]},{"n":20,"t":"智慧使你行善人的道，守義人的路。","notes":[]},{"n":21,"t":"正直人必在地上居住，完全人必在其上存留；","notes":[]},{"n":22,"t":"惟惡人要從地上剪除，奸詐人要被拔出。","notes":[]}]},"3":{"heading":"給年輕人的忠告","verses":[{"n":1,"t":"我兒啊，不要忘記我的教誨，你的心要謹守我的命令，","notes":[]},{"n":2,"t":"因為它們必加給你長久的日子，生命的年數與平安。","notes":["「它們」指「教誨」和「命令」。"]},{"n":3,"t":"不可使慈愛和誠信離開你，要繫在你頸項上，刻在你心版上。","notes":[]},{"n":4,"t":"這樣，你必在神和世人眼前蒙恩惠，有美好的見識。","notes":[]},{"n":5,"t":"你要專心仰賴耶和華，不可倚靠自己的聰明，","notes":[]},{"n":6,"t":"在你一切所行的路上都要認定他，他必使你的道路平直。","notes":[]},{"n":7,"t":"不要自以為有智慧；要敬畏耶和華，遠離惡事。","notes":[]},{"n":8,"t":"這便醫治你的肉體，滋潤你的百骨。","notes":["「肉體」：原文是「肚臍」。"]},{"n":9,"t":"你要以財物和一切初熟的土產尊崇耶和華，","notes":[]},{"n":10,"t":"這樣，你的倉庫必充滿有餘，你的酒池有新酒盈溢。","notes":[]},{"n":11,"t":"我兒啊，不可輕看耶和華的管教，也不可厭煩他的責備，","notes":[]},{"n":12,"t":"因為耶和華所愛的，他必責備，正如父親責備所喜愛的兒子。","notes":[]},{"n":13,"t":"得智慧，得聰明的，這人有福了。","notes":[]},{"n":14,"t":"因為智慧的獲利勝過銀子，所得的盈餘強如金子，","notes":[]},{"n":15,"t":"比寶石更寶貴，你一切所喜愛的，都不足與其比較。","notes":["「寶石」或譯「珍珠」；本卷書下同。"]},{"n":16,"t":"她的右手有長壽，左手有富貴。","notes":[]},{"n":17,"t":"她的道是安樂，她的路全是平安。","notes":[]},{"n":18,"t":"她給持守她的人作生命樹，謹守她的必定蒙福。","notes":[]},{"n":19,"t":"耶和華以智慧奠立地基，以聰明鋪設諸天，","notes":[]},{"n":20,"t":"以知識使深淵裂開，使天空滴下甘露。","notes":[]},{"n":21,"t":"我兒啊，要謹守健全的知識和智謀，不可使它們偏離你的眼目。","notes":[]},{"n":22,"t":"這樣，它們必使你的生命有活力，又作你頸項的美飾。","notes":[]},{"n":23,"t":"那時，你就坦然行路，不致跌倒。","notes":[]},{"n":24,"t":"你躺下，必不懼怕；你躺臥，睡得香甜。","notes":[]},{"n":25,"t":"忽然來的驚恐，你不要害怕；惡人遭毀滅，也不要恐懼，","notes":[]},{"n":26,"t":"因為耶和華是你的倚靠，他必保護你的腳不陷入羅網。","notes":[]},{"n":27,"t":"你的手若有行善的力量，不可推辭，要施與那應得的人。","notes":[]},{"n":28,"t":"你若手頭方便，不可對鄰舍說：「去吧，明天再來，我必給你。」","notes":[]},{"n":29,"t":"你的鄰舍既在你附近安居，不可設計害他。","notes":[]},{"n":30,"t":"人若未曾加害你，不可無故與他相爭。","notes":[]},{"n":31,"t":"不可嫉妒殘暴的人，不可選擇他的任何道路。","notes":[]},{"n":32,"t":"因為走偏方向的人是耶和華所憎惡的；正直人為他所親密。","notes":[]},{"n":33,"t":"耶和華詛咒惡人的家；義人的居所他卻賜福。","notes":[]},{"n":34,"t":"他譏誚那愛譏誚的人；但賜恩給謙卑的人。","notes":[]},{"n":35,"t":"智慧人必承受尊榮；愚昧人高升卻是羞辱。","notes":[]}]},"4":{"heading":"智慧的益處","verses":[{"n":1,"t":"孩子們，要聽父親的訓誨，留心明白道理。","notes":[]},{"n":2,"t":"因我給你們好的教導，不可離棄我的教誨。","notes":[]},{"n":3,"t":"當我在父親面前還是小孩，是母親獨一嬌兒的時候，","notes":[]},{"n":4,"t":"他教導我說：「你的心要持守我的話，遵守我的命令，你就會存活。","notes":[]},{"n":5,"t":"要獲得智慧，要獲得聰明，不可忘記， 也不可偏離我口中的言語。","notes":[]},{"n":6,"t":"不可離棄智慧，智慧就庇護你，要愛她，她就保護你。","notes":[]},{"n":7,"t":"智慧為首，所以要獲得智慧，要用你一切所有的換取聰明。","notes":[]},{"n":8,"t":"高舉智慧，她就使你升高，擁抱智慧，她就使你尊榮。","notes":[]},{"n":9,"t":"她必將恩惠的華冠加在你頭上，把榮冕賜給你。」","notes":[]},{"n":10,"t":"我兒啊，要聽，要領受我的言語，你就必延年益壽。","notes":[]},{"n":11,"t":"我已指教你走智慧的道，引導你行正直的路。","notes":[]},{"n":12,"t":"你行走，腳步沒有阻礙；你奔跑，也不致跌倒。","notes":[]},{"n":13,"t":"要持定訓誨，不可放鬆；要謹守它，因為它是你的生命。","notes":[]},{"n":14,"t":"不可行惡人的路，不要走壞人的道；","notes":[]},{"n":15,"t":"要躲避，不可經過，要轉離而去。","notes":[]},{"n":16,"t":"他們若不行惡，難以成眠，不使人跌倒，就睡臥不安；","notes":[]},{"n":17,"t":"因為他們以邪惡當餅吃，以暴力當酒喝。","notes":[]},{"n":18,"t":"但義人的路好像黎明的光，越照越明，直到正午。","notes":[]},{"n":19,"t":"惡人的道幽暗，自己不知因何跌倒。","notes":[]},{"n":20,"t":"我兒啊，要留心聽我的話，側耳聽我的言語，","notes":[]},{"n":21,"t":"不可使它們偏離你的眼目，要存記在你心中。","notes":[]},{"n":22,"t":"因為找到它們的，就找到生命，得到全身的醫治。","notes":[]},{"n":23,"t":"你要保守你心，勝過保守一切，因為生命的泉源由心發出。","notes":[]},{"n":24,"t":"要離開歪曲的口，轉離偏邪的嘴唇。","notes":[]},{"n":25,"t":"你的兩眼要向前看，你的雙目直視前方。","notes":["「雙目」：原文是「眼皮」。"]},{"n":26,"t":"要修平你腳下的路，你一切的道就必穩固。","notes":["「修平」或譯「察驗」。"]},{"n":27,"t":"不可偏左偏右，你的腳要離開邪惡。","notes":[]}]},"5":{"heading":"警告勿犯淫亂","verses":[{"n":1,"t":"我兒啊，要留心聽我的智慧，側耳聽我的聰明，","notes":[]},{"n":2,"t":"為要使你謹守智謀，嘴唇保護知識。","notes":[]},{"n":3,"t":"因為陌生女子的嘴唇滴下蜂蜜，她的口比油更滑，","notes":[]},{"n":4,"t":"後來卻苦似茵蔯，銳利如兩刃的劍。","notes":[]},{"n":5,"t":"她的腳墜落死亡，她的腳步踏入陰間，","notes":[]},{"n":6,"t":"她無法找到生命的道路，她的路變遷不定，自己卻不知道。","notes":[]},{"n":7,"t":"孩子們，現在要聽從我，不可離棄我口中的言語。","notes":[]},{"n":8,"t":"你所行的道要遠離她，不可靠近她家的門口，","notes":[]},{"n":9,"t":"免得將你的尊榮給別人，將你的歲月給殘忍的人；","notes":[]},{"n":10,"t":"免得陌生人滿得你的財富，你勞苦所得的歸入外邦人的家。","notes":[]},{"n":11,"t":"在你人生終結，你皮肉和身體衰殘時，你必唉聲嘆氣，","notes":[]},{"n":12,"t":"說：「我為何恨惡管教，心裏輕看責備呢？","notes":[]},{"n":13,"t":"我不聽從教師的話，也沒有側耳聽那教導我的。","notes":[]},{"n":14,"t":"在聚集的會眾中，我幾乎墜入深淵。」","notes":[]},{"n":15,"t":"你要喝自己池中的水，飲自己井裏的活水。","notes":[]},{"n":16,"t":"你的泉源豈可溢流在外？你的河水豈可流到街上？","notes":[]},{"n":17,"t":"讓它們惟獨歸你，不可與陌生人同享。","notes":[]},{"n":18,"t":"要使你的泉源蒙福，要喜愛你年輕時的妻子。","notes":[]},{"n":19,"t":"她如可愛的母鹿，如優美的母羊，願她的胸懷使你時時滿足，願你常常迷戀她的愛情。","notes":[]},{"n":20,"t":"我兒啊，你為何迷戀陌生女子？為何擁抱外邦女子的胸懷？","notes":[]},{"n":21,"t":"因為人所行的道都在耶和華眼前，他察驗人一切的路。","notes":["「察驗」或譯「修平」。"]},{"n":22,"t":"惡人被自己的罪孽抓住，被自己罪惡的繩索纏繞。","notes":[]},{"n":23,"t":"他因不受管教而死亡，因極度愚昧而走迷。","notes":[]}]},"6":{"heading":"更多的警告","verses":[{"n":1,"t":"我兒啊，你若為朋友擔保，替陌生人擊掌，","notes":[]},{"n":2,"t":"你就被口中的言語套住，被嘴裏的言語抓住。","notes":[]},{"n":3,"t":"我兒啊，你既落在朋友手中，當這樣行才可救自己：你要謙卑自己，去懇求你的朋友。","notes":[]},{"n":4,"t":"不要讓你的眼睛睡覺，不可容你的眼皮打盹。","notes":[]},{"n":5,"t":"要救自己，如羚羊脫離獵人的手，如鳥脫離捕鳥人的手。","notes":[]},{"n":6,"t":"懶惰人哪，你去察看螞蟻的動作，就可得智慧。","notes":[]},{"n":7,"t":"螞蟻沒有領袖，沒有官長，沒有君王，","notes":[]},{"n":8,"t":"尚且在夏天預備食物，在收割時儲存糧食。","notes":[]},{"n":9,"t":"懶惰人哪，你要睡到幾時呢？你甚麼時候才睡醒呢？","notes":[]},{"n":10,"t":"再睡片時，打盹片時，抱著雙臂躺臥片時，","notes":[]},{"n":11,"t":"你的貧窮就如盜賊來到，你的貧乏彷彿拿盾牌的人來臨。","notes":[]},{"n":12,"t":"無賴的惡徒行事全憑歪曲的口，","notes":[]},{"n":13,"t":"他眨眼傳神，以腳示意，用指點劃，","notes":[]},{"n":14,"t":"存心乖謬，常設惡謀，散播紛爭。","notes":[]},{"n":15,"t":"所以，災難必突然臨到他，他必頃刻被毀，無從醫治。","notes":[]},{"n":16,"t":"耶和華所恨惡的有六樣，他心所憎惡的共有七樣：","notes":[]},{"n":17,"t":"就是高傲的眼，撒謊的舌，殺害無辜的手，","notes":[]},{"n":18,"t":"圖謀惡計的心，飛奔行惡的腳，","notes":[]},{"n":19,"t":"口吐謊言的假證人，並在弟兄間散播紛爭的人。","notes":[]},{"n":20,"t":"我兒啊，要遵守你父親的命令，不可離棄你母親的教誨。","notes":[],"heads":["警告勿犯淫亂"]},{"n":21,"t":"要常掛在你心上，繫在你頸項上。","notes":[]},{"n":22,"t":"你行走，她必引導你，你躺臥，她必保護你，你睡醒，她必與你談論。","notes":[]},{"n":23,"t":"因為誡命是燈，教誨是光，管教的責備是生命的道，","notes":[]},{"n":24,"t":"要保護你遠離邪惡的婦女，遠離外邦女子諂媚的舌頭。","notes":[]},{"n":25,"t":"你不要因她的美色而動心，也不要被她的眼皮勾引。","notes":[]},{"n":26,"t":"因為連最後一塊餅都會被妓女拿走；有夫之婦會獵取寶貴的生命。","notes":["「連最後一塊餅都會被妓女拿走」或譯「妓女的雇價只是一塊餅」。"]},{"n":27,"t":"人若兜火在懷中，他的衣服豈能不燒著呢？","notes":[]},{"n":28,"t":"人若走在火炭上，他的腳豈能不燙傷呢？","notes":[]},{"n":29,"t":"與鄰舍之妻同寢的，也是如此，凡親近她的，難免受罰。","notes":[]},{"n":30,"t":"賊因飢餓偷竊充飢，人不藐視他，","notes":[]},{"n":31,"t":"但若被抓到，要賠償七倍，他必賠上家中一切財物。","notes":[]},{"n":32,"t":"與婦人行姦淫的，便是無知，做這事的，必毀了自己。","notes":[]},{"n":33,"t":"他必受損傷和羞辱，他的羞恥不得消除。","notes":[]},{"n":34,"t":"丈夫因嫉恨發怒，報仇的時候絕不留情。","notes":[]},{"n":35,"t":"他不接受任何賠償，你送許多禮物，他也不肯和解。","notes":[]}]},"7":{"heading":"淫亂的婦人","verses":[{"n":1,"t":"我兒啊，要遵守我的言語，存記我的命令。","notes":[]},{"n":2,"t":"遵守我的命令就得存活，謹守我的教誨，好像保護眼中的瞳人。","notes":[]},{"n":3,"t":"要繫在你指頭上，刻在你心版上。","notes":[]},{"n":4,"t":"對智慧說「你是我的姊妹」，稱呼聰明為親人，","notes":[]},{"n":5,"t":"她就保護你遠離陌生女子，遠離油嘴滑舌的外邦女子。","notes":[]},{"n":6,"t":"我曾在我房屋的窗戶內，透過窗格子往外觀看，","notes":[]},{"n":7,"t":"看見在愚蒙人中，注意到孩兒中有一個無知的青年，","notes":[]},{"n":8,"t":"從街上經過，靠近她的巷口，直往她家的路去，","notes":[]},{"n":9,"t":"在黃昏，在傍晚，在半夜，黑暗之中。","notes":[]},{"n":10,"t":"看哪，有一個女子來迎接他，是妓女的打扮，有詭詐的心思。","notes":[]},{"n":11,"t":"她喧嚷，不守約束，她的腳在家裏留不住，","notes":[]},{"n":12,"t":"有時在街市，有時在廣場，或在各巷口等候。","notes":[]},{"n":13,"t":"她拉住那青年吻他，厚著臉皮對他說：","notes":[]},{"n":14,"t":"「我已獻了平安祭，今日我還了所許的願。","notes":[]},{"n":15,"t":"因此，我出來迎接你，渴望見你的面，我總算找到你了！","notes":[]},{"n":16,"t":"我已在床上鋪好被單，是埃及麻織的花紋布，","notes":[]},{"n":17,"t":"又用沒藥、沉香、桂皮薰了我的床。","notes":[]},{"n":18,"t":"你來，讓我們飽享愛情，直到早晨，讓我們彼此親愛歡樂。","notes":[]},{"n":19,"t":"因為我丈夫不在家，出門遠行，","notes":[]},{"n":20,"t":"他手帶錢囊，要到月圓才回家。」","notes":[]},{"n":21,"t":"這女子用許多巧言引誘他，用諂媚的嘴唇催逼他。","notes":[]},{"n":22,"t":"青年立刻跟隨她，好像牛去被宰殺，又像愚妄人帶著腳鐐去受刑，","notes":[]},{"n":23,"t":"直到箭穿進他的肝，如同雀鳥急投羅網，卻不知會賠上自己的生命。","notes":[]},{"n":24,"t":"孩子們，現在要聽從我，要留心聽我口中的言語。","notes":[]},{"n":25,"t":"你的心不可偏向她的道，不要誤入她的迷途。","notes":[]},{"n":26,"t":"因為她擊倒許多人，無數的人被她殺戮。","notes":["「無數的人被她殺戮」或譯「被她殺戮的都是強壯者」。"]},{"n":27,"t":"她的家是在陰間之路，下到死亡之宮。","notes":[]}]},"8":{"heading":"智慧頌","verses":[{"n":1,"t":"智慧豈不呼喚？聰明豈不揚聲？","notes":[]},{"n":2,"t":"她站立在十字路口，在道路旁高處的頂上，","notes":[]},{"n":3,"t":"在城門旁，城門口，入口處，她呼喊：","notes":[]},{"n":4,"t":"「人哪，我呼喚你們，我向世人揚聲。","notes":[]},{"n":5,"t":"愚蒙人哪，你們要學習靈巧，愚昧人哪，你們的心要明辨。","notes":[]},{"n":6,"t":"你們當聽，因我要說尊貴的事，我要張開嘴唇講正直的事。","notes":[]},{"n":7,"t":"我的口要發出真理，我的嘴唇憎惡邪惡。","notes":[]},{"n":8,"t":"我口中的言語都是公義，並無奸詐和歪曲。","notes":[]},{"n":9,"t":"聰明人看為正確，有知識的，都以為正直。","notes":[]},{"n":10,"t":"你們當領受我的訓誨，勝過領受銀子，寧得知識，強如得上選的金子。","notes":[]},{"n":11,"t":"「因為智慧比寶石更美，一切可喜愛的都不足與其比較。","notes":[]},{"n":12,"t":"我－智慧以靈巧為居所，又尋得知識和智謀。","notes":[]},{"n":13,"t":"敬畏耶和華就是恨惡邪惡；我恨惡驕傲、狂妄、惡道，和乖謬的口。","notes":[]},{"n":14,"t":"我有策略和健全的知識，我聰明，又有能力。","notes":[]},{"n":15,"t":"君王藉我治國，王子藉我定公平，","notes":[]},{"n":16,"t":"王公貴族，所有公義的審判官，都藉我掌權。","notes":["本節七十士譯本是「貴族因我而尊大，君王藉著我統治土地」。"]},{"n":17,"t":"愛我的，我也愛他，懇切尋求我的，必尋見。","notes":[]},{"n":18,"t":"財富和尊榮在我，恆久的財寶和繁榮也在我。","notes":["「繁榮」或譯「公義」。"]},{"n":19,"t":"我的果實勝過金子，強如純金，我的出產超乎上選的銀子。","notes":[]},{"n":20,"t":"我在公義的道上走，在公平的路中行，","notes":[]},{"n":21,"t":"使愛我的承受財產，充滿他們的庫房。","notes":[]},{"n":22,"t":"「耶和華在造化的起頭，在太初創造萬物之先，就有了我。","notes":["「有」或譯「造」。"]},{"n":23,"t":"從亙古，從太初，未有大地以前，我已被立。","notes":[]},{"n":24,"t":"沒有深淵，沒有大水的泉源，我已出生。","notes":[]},{"n":25,"t":"大山未曾奠定，小山未有之先，我已出生。","notes":[]},{"n":26,"t":"那時，他還沒有創造大地和田野，並世上頭一撮塵土。","notes":[]},{"n":27,"t":"他立高天，我在那裏，他在淵面的周圍劃出圓圈，","notes":[]},{"n":28,"t":"上使穹蒼堅硬，下使淵源穩固，","notes":[]},{"n":29,"t":"為滄海定出範圍，使水不越過界限，奠定大地的根基。","notes":[]},{"n":30,"t":"那時，我在他旁邊為工程師，天天充滿喜樂，時時在他面前歡笑，","notes":[]},{"n":31,"t":"在他的全地歡笑，喜愛住在人世間。","notes":[]},{"n":32,"t":"「孩子們，現在要聽從我，謹守我道的有福了。","notes":[]},{"n":33,"t":"要聽訓誨，得智慧，不可棄絕。","notes":[]},{"n":34,"t":"聽從我，天天在我門口守望，在我門框旁等候的，那人有福了。","notes":[]},{"n":35,"t":"因為尋得我的，就尋得生命，他必蒙耶和華的恩惠。","notes":[]},{"n":36,"t":"得罪我的，害了自己的生命，凡恨惡我的，喜愛死亡。」","notes":[]}]},"9":{"heading":"智慧和愚蠢","verses":[{"n":1,"t":"智慧建造房屋，鑿成七根柱子，","notes":[]},{"n":2,"t":"宰殺牲畜，調好美酒，又擺設筵席，","notes":[]},{"n":3,"t":"派遣女僕出去，自己在城中至高處呼喚：","notes":[]},{"n":4,"t":"「誰是愚蒙的人，讓他轉到這裏來！」又對那無知的人說：","notes":[]},{"n":5,"t":"「你們來，吃我的餅，喝我調的酒。","notes":[]},{"n":6,"t":"你們要離棄愚蒙，就得存活，並要走明智的道路。」","notes":[]},{"n":7,"t":"糾正傲慢人的，必招羞辱，責備惡人的，必被侮辱。","notes":[]},{"n":8,"t":"不要責備傲慢人，免得他恨你；要責備智慧人，他必愛你。","notes":[]},{"n":9,"t":"教導智慧人，他就越有智慧，指示義人，他就增長學問。","notes":[]},{"n":10,"t":"敬畏耶和華是智慧的開端，認識至聖者便是聰明。","notes":[]},{"n":11,"t":"藉著我，你的日子必增多，你生命的年數也必加添。","notes":[]},{"n":12,"t":"你若有智慧，是自己有智慧；你若傲慢，就自己承擔。","notes":[]},{"n":13,"t":"愚昧的女子喧嚷，她是愚蒙，一無所知。","notes":[]},{"n":14,"t":"她坐在自己家門口，在城中高處的座位上，","notes":[]},{"n":15,"t":"呼喚過路的，向那些在路上直走的人說：","notes":[]},{"n":16,"t":"「誰是愚蒙的人，讓他轉到這裏來！」又對那無知的人說：","notes":[]},{"n":17,"t":"「偷來的水是甜的，暗藏的餅是美的。」","notes":[]},{"n":18,"t":"人卻不知有陰魂在她那裏，她召喚的人是在陰間的深處。","notes":[]}]},"10":{"heading":"所羅門的箴言","verses":[{"n":1,"t":"所羅門的箴言：智慧之子使父親喜樂；愚昧之子使母親擔憂。","notes":[]},{"n":2,"t":"不義之財毫無益處；惟有公義能救人脫離死亡。","notes":[]},{"n":3,"t":"耶和華不使義人捱餓；惡人所欲的，耶和華必拒絕。","notes":[]},{"n":4,"t":"手懶的，必致窮乏；手勤的，卻要富足。","notes":[]},{"n":5,"t":"夏天儲存的，是智慧之子；收割時沉睡的，是蒙羞之子。","notes":[]},{"n":6,"t":"福祉臨到義人頭上；惡人的口藏匿殘暴。","notes":[]},{"n":7,"t":"義人的稱號帶來祝福；惡人的名字必然敗壞。","notes":[]},{"n":8,"t":"智慧的心，領受誡命；愚妄的嘴唇，必致傾倒。","notes":[]},{"n":9,"t":"行正直路的，步步安穩；走彎曲道的，必致敗露。","notes":[]},{"n":10,"t":"擠眉弄眼的，使人憂患；愚妄的嘴唇，必致傾倒。","notes":[]},{"n":11,"t":"義人的口是生命的泉源；惡人的口藏匿殘暴。","notes":[]},{"n":12,"t":"恨能挑啟爭端；愛能遮掩一切過錯。","notes":[]},{"n":13,"t":"聰明人嘴裏有智慧；無知的人背上受刑杖。","notes":[]},{"n":14,"t":"智慧人積存知識；愚妄人的口速致敗壞。","notes":[]},{"n":15,"t":"有錢人的財物是他堅固的城；貧寒人的貧乏使他敗壞。","notes":[]},{"n":16,"t":"義人的報酬帶來生命；惡人的所得用來犯罪。","notes":[]},{"n":17,"t":"遵守訓誨的，行在生命道上；離棄責備的，走迷了路。","notes":[]},{"n":18,"t":"隱藏怨恨的，有說謊的嘴唇；口出毀謗的，是愚昧人。","notes":[]},{"n":19,"t":"多言多語難免有過；節制嘴唇是有智慧。","notes":[]},{"n":20,"t":"義人的舌如上選的銀子；惡人的心所值無幾。","notes":[]},{"n":21,"t":"義人的嘴唇牧養多人；愚妄人因無知而死亡。","notes":[]},{"n":22,"t":"耶和華所賜的福使人富足，並不加上憂慮。","notes":[]},{"n":23,"t":"愚昧人以行惡為樂；聰明人以智慧為樂。","notes":[]},{"n":24,"t":"惡人所怕的，必臨到他；義人的心願，必蒙應允。","notes":[]},{"n":25,"t":"暴風一過，惡人歸於無有；義人卻有永久的根基。","notes":[]},{"n":26,"t":"懶惰人使那差他的人，如醋倒牙，如煙薰目。","notes":[]},{"n":27,"t":"敬畏耶和華使人長壽；惡人的年歲必減少。","notes":[]},{"n":28,"t":"義人的盼望帶來喜樂；惡人的指望必致滅沒。","notes":[]},{"n":29,"t":"耶和華的道是正直人的保障；卻成了作惡人的敗壞。","notes":[]},{"n":30,"t":"義人永不動搖；惡人不得住在地上。","notes":[]},{"n":31,"t":"義人的口結出智慧；乖謬的舌必被割斷。","notes":[]},{"n":32,"t":"義人的嘴唇懂得令人喜悅；惡人的口只知乖謬。","notes":[]}]},"11":{"heading":"","verses":[{"n":1,"t":"詭詐的天平為耶和華所憎惡；公平的法碼為他所喜悅。","notes":[]},{"n":2,"t":"驕傲來，羞恥也來；謙遜人卻有智慧。","notes":[]},{"n":3,"t":"正直人的純正必引導自己；奸詐人的邪惡必毀滅自己。","notes":[]},{"n":4,"t":"遭怒的日子錢財無益；惟有公義能救人脫離死亡。","notes":[]},{"n":5,"t":"完全人的義修平自己的路；但惡人必因自己的惡跌倒。","notes":[]},{"n":6,"t":"正直人的義必拯救自己；奸詐人必被自己的慾望纏住。","notes":[]},{"n":7,"t":"惡人一死，他的指望就滅絕；罪人的盼望也必滅絕。","notes":[]},{"n":8,"t":"義人得脫離患難，有惡人來代替他。","notes":[]},{"n":9,"t":"不虔敬的人用口敗壞鄰舍；義人卻因知識得救。","notes":[]},{"n":10,"t":"義人享福，全城喜樂；惡人滅亡，人人歡呼。","notes":[]},{"n":11,"t":"因正直人的祝福，城必升高；因邪惡人的口，它必傾覆。","notes":[]},{"n":12,"t":"藐視鄰舍的，便是無知；聰明人卻靜默不言。","notes":[]},{"n":13,"t":"到處傳話的，洩漏機密；內心老實的，保守祕密。","notes":[]},{"n":14,"t":"無智謀，民就敗落；謀士多，就必得勝。","notes":[]},{"n":15,"t":"為陌生人擔保的，必受虧損；恨惡擊掌的，卻得安穩。","notes":[]},{"n":16,"t":"恩慈的婦女得尊榮；強壯的男子得財富。","notes":[]},{"n":17,"t":"仁慈的人善待自己；殘忍的人擾害己身。","notes":[]},{"n":18,"t":"惡人做事，得虛幻的報酬；撒公義種子的，得實在的報償。","notes":[]},{"n":19,"t":"真正行義的，必得生命；追求邪惡的，必致死亡。","notes":[]},{"n":20,"t":"心中歪曲的，為耶和華所憎惡；行為正直的，為他所喜悅。","notes":[]},{"n":21,"t":"擊掌保證，惡人難免受罰；義人的後裔必得拯救。","notes":[]},{"n":22,"t":"婦女美貌而無見識，如同金環戴在豬鼻上。","notes":[]},{"n":23,"t":"義人的心願盡是好的；惡人的指望卻帶來憤怒。","notes":[]},{"n":24,"t":"有施捨的，錢財增添；吝惜過度，反致窮乏。","notes":[]},{"n":25,"t":"慷慨待人，必然豐裕；滋潤人的，連自己也得滋潤。","notes":[]},{"n":26,"t":"屯糧不賣的，百姓必詛咒他；願意出售的，祝福臨到頭上。","notes":[]},{"n":27,"t":"懇切求善的，就求得恩寵；但那求惡的，惡必臨到他。","notes":[]},{"n":28,"t":"倚靠財富的，自己必跌倒；義人必興旺如綠葉。","notes":[]},{"n":29,"t":"擾害己家的，必承受虛空；愚妄人作心中有智慧者的僕人。","notes":["「虛空」：原文是「風」。"]},{"n":30,"t":"義人的果實是生命樹；智慧人必能得人。","notes":[]},{"n":31,"t":"看哪，義人在地上尚且受報，何況惡人和罪人呢？","notes":[]}]},"12":{"heading":"","verses":[{"n":1,"t":"喜愛管教的，就是喜愛知識；恨惡責備的，卻像畜牲。","notes":[]},{"n":2,"t":"善人蒙耶和華的恩寵；設詭計的，耶和華必定罪。","notes":[]},{"n":3,"t":"人靠惡行不能堅立；義人的根必不動搖。","notes":[]},{"n":4,"t":"才德的妻子是丈夫的冠冕；蒙羞的婦人使丈夫骨頭朽爛。","notes":[]},{"n":5,"t":"義人的思念是公平；惡人的計謀是詭詐。","notes":[]},{"n":6,"t":"惡人的言論埋伏流人的血；正直人的口卻拯救人。","notes":[]},{"n":7,"t":"惡人傾覆，歸於無有；義人的家卻屹立不倒。","notes":[]},{"n":8,"t":"人按自己的智慧得稱讚；心中偏邪的，必被藐視。","notes":[]},{"n":9,"t":"被人藐視，但有自己僕人的，勝過妄自尊大，卻缺乏食物。","notes":["「有自己僕人」或譯「自己工作」。"]},{"n":10,"t":"義人顧惜他牲畜的命；惡人的憐憫也是殘忍。","notes":[]},{"n":11,"t":"耕種自己田地的，必得飽食；追求虛浮的，卻是無知。","notes":[]},{"n":12,"t":"惡人想得壞人的獵物；義人的根結出果實。","notes":[]},{"n":13,"t":"嘴唇的過錯是惡人的圈套；但義人必脫離患難。","notes":[]},{"n":14,"t":"人因口所結的果實，必飽得美福；人手所做的，必歸到自己身上。","notes":[]},{"n":15,"t":"愚妄人所行的，在自己眼中看為正直；惟智慧人從善如流。","notes":[]},{"n":16,"t":"愚妄人的惱怒立時顯露；通達人卻能忍辱。","notes":[]},{"n":17,"t":"說出真話的，顯明公義；作假見證的，顯出詭詐。","notes":[]},{"n":18,"t":"說話浮躁，猶如刺刀；智慧人的舌頭卻能醫治。","notes":[]},{"n":19,"t":"誠實的嘴唇永遠堅立；說謊的舌頭只存片時。","notes":[]},{"n":20,"t":"圖謀惡事的，心存詭詐；勸人和睦的，便得喜樂。","notes":[]},{"n":21,"t":"義人不遭災害；惡人滿受禍患。","notes":[]},{"n":22,"t":"說謊的嘴唇，為耶和華所憎惡；行事誠實，為他所喜悅。","notes":[]},{"n":23,"t":"通達人隱藏知識；愚昧人的心彰顯愚昧。","notes":[]},{"n":24,"t":"殷勤人的手必掌權；懶惰的人必服苦役。","notes":[]},{"n":25,"t":"人心憂慮，就必沉重；一句良言，使心歡樂。","notes":[]},{"n":26,"t":"義人引導他的鄰舍；惡人的道叫人迷失。","notes":["「義人引導他的鄰舍」或譯「義人慎選他的朋友」，又或譯「義人比他的鄰舍更好」。"]},{"n":27,"t":"懶惰的人不烤獵物；殷勤的人卻得寶貴的財物。","notes":[]},{"n":28,"t":"在公義的路上有生命；在其道上並無死亡。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"智慧之子聽父親的訓誨；傲慢人不聽責備。","notes":[]},{"n":2,"t":"人因口所結的果實，必享美福；奸詐人卻意圖殘暴。","notes":[]},{"n":3,"t":"謹慎守口的，得保生命；大張嘴唇的，必致敗亡。","notes":[]},{"n":4,"t":"懶惰的人奢求，卻無所得；殷勤的人必然豐裕。","notes":[]},{"n":5,"t":"義人恨惡謊言；惡人可憎可恥。","notes":[]},{"n":6,"t":"行為純正的，有公義保護；犯罪的，被罪惡傾覆。","notes":[]},{"n":7,"t":"假冒富足的，一無所有；裝作窮乏的，多有財物。","notes":[]},{"n":8,"t":"財富可作人的生命贖價；窮乏人卻聽不見威嚇的話。","notes":[]},{"n":9,"t":"義人的光使人歡喜；惡人的燈要熄滅。","notes":["「使人歡喜」：原文另譯「明亮」。"]},{"n":10,"t":"驕傲挑啟紛爭；聽勸言卻有智慧。","notes":[]},{"n":11,"t":"不勞而獲之財必減少；逐漸積蓄的必增多。","notes":["「不勞而獲之財」：七十士譯本是「暴發的不義之財」。"]},{"n":12,"t":"盼望遲延，令人心憂；願望實現，就是得到生命樹。","notes":[]},{"n":13,"t":"藐視訓言的，自取滅亡；敬畏誡命的，必得善報。","notes":[]},{"n":14,"t":"智慧人的教誨是生命的泉源，使人避開死亡的圈套。","notes":[]},{"n":15,"t":"美好的見識使人得寵；奸詐人的道路恆久奸詐。","notes":["「恆久奸詐」：原文是「恆久」。"]},{"n":16,"t":"通達人都憑知識行事；愚昧人張揚自己的愚昧。","notes":[]},{"n":17,"t":"邪惡的使者必陷入禍患；忠信的使臣帶來醫治。","notes":[]},{"n":18,"t":"棄絕管教的，必貧窮受辱；領受責備的，必享尊榮。","notes":[]},{"n":19,"t":"願望實現，心覺甘甜；遠離惡事，為愚昧人所憎惡。","notes":[]},{"n":20,"t":"與智慧人同行的，必得智慧；和愚昧人作伴的，必受虧損。","notes":[]},{"n":21,"t":"禍患追趕罪人；義人卻得善報。","notes":[]},{"n":22,"t":"善人給子孫遺留產業；罪人積財卻歸義人。","notes":[]},{"n":23,"t":"窮乏人開墾的地雖多產糧食，卻因不公而被奪走。","notes":[]},{"n":24,"t":"不忍用杖打兒子的，是恨惡他；疼愛兒子的，勤加管教。","notes":[]},{"n":25,"t":"義人吃喝食慾滿足；惡人肚腹卻是缺乏。","notes":[]}]},"14":{"heading":"","verses":[{"n":1,"t":"婦人的智慧建立家室；愚昧卻親手拆毀它。","notes":["本節七十士譯本是「智慧婦人建立家室；愚妄婦人親手拆毀」。"]},{"n":2,"t":"行事正直的，敬畏耶和華；偏離正路的，卻藐視他。","notes":[]},{"n":3,"t":"在愚妄人的口中有驕傲的杖；智慧人的嘴唇必保護自己。","notes":[]},{"n":4,"t":"沒有牛，槽就空空；土產豐盛卻憑牛的力氣。","notes":[]},{"n":5,"t":"誠實的證人不說謊；虛假的證人口吐謊言。","notes":[]},{"n":6,"t":"傲慢人枉尋智慧；聰明人易得知識。","notes":[]},{"n":7,"t":"不要到愚昧人面前，你無法從他嘴唇裏知道知識。","notes":[]},{"n":8,"t":"通達人的智慧使他認清自己的道路；愚昧人的愚昧卻是自欺。","notes":[]},{"n":9,"t":"愚妄人嘲笑贖愆祭；但正直人蒙悅納。","notes":["「贖愆祭」或譯「復和」。"]},{"n":10,"t":"心中的苦楚，只有自己知道；心裏的喜樂，陌生人無法分享。","notes":[]},{"n":11,"t":"惡人的房屋必倒塌；正直人的帳棚必興旺。","notes":[]},{"n":12,"t":"有一條路，人以為正，至終成為死亡之路。","notes":[]},{"n":13,"t":"人在喜笑中，心也會憂愁；快樂的終點就是愁苦。","notes":[]},{"n":14,"t":"心中背道的，必滿嘗其果；善人必從自己的行為得到回報。","notes":[]},{"n":15,"t":"無知的人甚麼話都信；通達人謹慎自己的腳步。","notes":[]},{"n":16,"t":"智慧人有所懼怕，就遠離惡事；愚昧人卻狂傲自恃。","notes":[]},{"n":17,"t":"輕易發怒的，行事愚昧；擅長詭計的，被人恨惡。","notes":[]},{"n":18,"t":"愚蒙人承受愚昧為產業；通達人得知識為冠冕。","notes":[]},{"n":19,"t":"壞人在善人面前俯伏；惡人在義人門口也是如此。","notes":[]},{"n":20,"t":"窮乏人，連鄰舍也恨他；有錢人，愛他的人眾多。","notes":[]},{"n":21,"t":"藐視鄰舍的，這人有罪；施恩給困苦人的，這人有福。","notes":[]},{"n":22,"t":"謀惡的，豈非走入迷途？謀善的，有慈愛和誠實。","notes":[]},{"n":23,"t":"任何勤勞總有收穫；僅耍嘴皮必致窮乏。","notes":[]},{"n":24,"t":"智慧人的冠冕是富有智慧；愚昧人的愚昧終究是愚昧。","notes":[]},{"n":25,"t":"誠實作證，救人性命；口吐謊言是詭詐。","notes":[]},{"n":26,"t":"敬畏耶和華的，大有倚靠；他的兒女也有避難所。","notes":[]},{"n":27,"t":"敬畏耶和華是生命的泉源，使人離開死亡的圈套。","notes":[]},{"n":28,"t":"君王的榮耀在乎民多；沒有百姓，王就衰敗。","notes":[]},{"n":29,"t":"不輕易發怒的，大有聰明；性情暴躁的，大顯愚昧。","notes":[]},{"n":30,"t":"平靜的心使肉體有生氣；嫉妒使骨頭朽爛。","notes":[]},{"n":31,"t":"欺壓貧寒人的，是蔑視造他的主；憐憫貧窮人的，是尊敬主。","notes":[]},{"n":32,"t":"惡人因所行的惡必被推倒；義人臨死，有所投靠。","notes":["「義人臨死」：七十士譯本是「義人因其完全」。"]},{"n":33,"t":"智慧安居在聰明人的心中，在愚昧人的心中卻不認識。","notes":["「在愚昧人...不認識」是根據七十士譯本；原文是「也為愚昧人的心所知」。"]},{"n":34,"t":"公義使邦國高舉；罪惡是百姓的羞辱。","notes":[]},{"n":35,"t":"君王的恩寵臨到智慧的臣僕；但其憤怒臨到蒙羞的臣僕。","notes":[]}]},"15":{"heading":"","verses":[{"n":1,"t":"回答柔和，使怒消退；言語粗暴，觸動怒氣。","notes":[]},{"n":2,"t":"智慧人的舌善發知識；愚昧人的口吐出愚昧。","notes":[]},{"n":3,"t":"耶和華的眼目無處不在，惡人善人，他都鑒察。","notes":[]},{"n":4,"t":"溫良的舌是生命樹；邪惡的舌使人心碎。","notes":[]},{"n":5,"t":"愚妄人藐視父親的管教；領受責備，使人精明。","notes":[]},{"n":6,"t":"義人家中多有財富；惡人獲利反受擾害。","notes":[]},{"n":7,"t":"智慧人的嘴傳揚知識；愚昧人的心並非如此。","notes":[]},{"n":8,"t":"惡人獻祭，為耶和華所憎惡；正直人祈禱，為他所喜悅。","notes":[]},{"n":9,"t":"惡人的道路，為耶和華所憎惡；追求公義的，為他所喜愛。","notes":[]},{"n":10,"t":"背棄正路的，必受嚴刑；恨惡責備的，必致死亡。","notes":[]},{"n":11,"t":"陰間和冥府尚且在耶和華面前，何況世人的心呢？","notes":["「冥府」：原文音譯「亞巴頓」，意思是「滅亡之地」。"]},{"n":12,"t":"傲慢人不愛受責備，也不去接近智慧人。","notes":[]},{"n":13,"t":"心中喜樂，面有喜色；心裏憂愁，靈就憂傷。","notes":[]},{"n":14,"t":"聰明人的心追求知識；愚昧人的口吞吃愚昧。","notes":[]},{"n":15,"t":"困苦人的日子都是愁苦；心中歡暢的，常享宴席。","notes":[]},{"n":16,"t":"財寶稀少，敬畏耶和華，強如財寶眾多，煩亂不安。","notes":[]},{"n":17,"t":"有愛，吃素菜，強如相恨，吃肥牛。","notes":[]},{"n":18,"t":"暴怒的人挑啟爭端；忍怒的人止息紛爭。","notes":[]},{"n":19,"t":"懶惰人的道像荊棘的籬笆；正直人的路是平坦大道。","notes":[]},{"n":20,"t":"智慧之子使父親喜樂；愚昧的人藐視母親。","notes":[]},{"n":21,"t":"無知的人以愚昧為樂；聰明的人按正直而行。","notes":[]},{"n":22,"t":"不先商議，所謀無效；謀士眾多，所謀得成。","notes":[]},{"n":23,"t":"口善應對，自覺喜樂；話合其時，何等美好。","notes":[]},{"n":24,"t":"生命之道使智慧人上升，使他遠離底下的陰間。","notes":[]},{"n":25,"t":"耶和華必拆毀驕傲人的家，卻要立定寡婦的地界。","notes":[]},{"n":26,"t":"惡謀為耶和華所憎惡；良言卻是純淨的。","notes":[]},{"n":27,"t":"暴力歛財的，擾害己家；恨惡賄賂的，必得存活。","notes":[]},{"n":28,"t":"義人的心思量應答；惡人的口吐出惡言。","notes":[]},{"n":29,"t":"耶和華遠離惡人，卻聽義人的祈禱。","notes":[]},{"n":30,"t":"眼睛發光，使心喜樂；好的信息，滋潤骨頭。","notes":[]},{"n":31,"t":"耳聽使人得生命的責備，必居住在智慧人之中。","notes":[]},{"n":32,"t":"棄絕管教的，輕看自己的生命；領受責備的，卻得智慧的心。","notes":[]},{"n":33,"t":"敬畏耶和華是智慧的訓誨；要得尊榮，先有謙卑。","notes":[]}]},"16":{"heading":"","verses":[{"n":1,"t":"心中的籌謀在乎人，舌頭的應對出於耶和華。","notes":[]},{"n":2,"t":"人一切所行的，在自己眼中看為純潔，惟有耶和華衡量人的內心。","notes":[]},{"n":3,"t":"你所做的，要交託耶和華，你所謀的，就必堅立。","notes":[]},{"n":4,"t":"耶和華造萬物各適其用，就是惡人也為禍患的日子所造。","notes":[]},{"n":5,"t":"凡心裏驕傲的，為耶和華所憎惡；擊掌保證，他難免受罰。","notes":[]},{"n":6,"t":"因慈愛和信實，罪孽得贖；敬畏耶和華的，遠離惡事。","notes":[]},{"n":7,"t":"人所行的若蒙耶和華喜悅，耶和華也使仇敵與他和好。","notes":[]},{"n":8,"t":"少獲利，行事公義，強如多獲利，行事不義。","notes":[]},{"n":9,"t":"人心籌算自己的道路；惟耶和華指引他的腳步。","notes":[]},{"n":10,"t":"王的嘴唇有聖言，審判之時，他的口必不差錯。","notes":[]},{"n":11,"t":"公道的秤和天平屬耶和華，囊中一切的法碼是他所定。","notes":[]},{"n":12,"t":"作惡，為王所憎惡，因國位是靠公義堅立。","notes":[]},{"n":13,"t":"公義的嘴唇，王喜悅，說正直話的，他喜愛。","notes":[]},{"n":14,"t":"王的震怒是死亡的使者，但智慧人能平息王怒。","notes":[]},{"n":15,"t":"王臉上的光使人有生命，他的恩惠好像雲帶來的春雨。","notes":[]},{"n":16,"t":"得智慧勝過得金子，選聰明強如選銀子。","notes":[]},{"n":17,"t":"正直人的道遠離惡事，謹守己路的，保全性命。","notes":[]},{"n":18,"t":"驕傲在敗壞以先，內心高傲在跌倒之前。","notes":[]},{"n":19,"t":"心裏謙卑與困苦人來往，強如與驕傲人同分戰利品。","notes":[]},{"n":20,"t":"留心訓言的，必得福樂；倚靠耶和華的，這人有福。","notes":["「留心訓言的」或譯「專注事務的」。"]},{"n":21,"t":"心中有智慧的，必稱為聰明人；嘴唇的甜言，增長人的學問。","notes":[]},{"n":22,"t":"人有智慧就有生命的泉源；愚妄人必受愚妄的懲戒。","notes":[]},{"n":23,"t":"智慧人的心使他的口謹慎，又使他的嘴唇增長學問。","notes":[]},{"n":24,"t":"良言如同蜂巢，使心甘甜，使骨得醫治。","notes":[]},{"n":25,"t":"有一條路，人以為正，至終卻成為死亡之路。","notes":[]},{"n":26,"t":"勞力的人為自己勞力，因為他的口腹催逼他。","notes":[]},{"n":27,"t":"匪徒圖謀奸惡，嘴唇上的言語彷彿燒焦的火。","notes":[]},{"n":28,"t":"乖謬的人散播紛爭，造謠的離間密友。","notes":[]},{"n":29,"t":"殘暴的人引誘鄰舍，領他走不好的道路。","notes":[]},{"n":30,"t":"緊閉雙目的，圖謀乖謬；緊咬嘴唇的，成就惡事。","notes":[]},{"n":31,"t":"白髮是榮耀的冠冕，行在公義道上的，必能得著。","notes":[]},{"n":32,"t":"不輕易發怒的，勝過勇士；控制自己脾氣的，強如取城。","notes":[]},{"n":33,"t":"人雖可擲籤在膝上，定事卻由耶和華。","notes":[]}]},"17":{"heading":"","verses":[{"n":1,"t":"一塊乾餅，大家相安；勝過宴席滿屋，大家相爭。","notes":[]},{"n":2,"t":"明智的僕人必管轄蒙羞的兒子，並在兄弟中同分產業。","notes":[]},{"n":3,"t":"鼎為煉銀，爐為煉金，惟有耶和華熬煉人心。","notes":[]},{"n":4,"t":"行惡的，留心聽惡毒的嘴唇；說謊的，側耳聽邪惡的舌頭。","notes":[]},{"n":5,"t":"譏笑窮乏人的，是蔑視造他的主；幸災樂禍的，難免受罰。","notes":[]},{"n":6,"t":"子孫為老人的冠冕；父母是兒女的榮耀。","notes":[]},{"n":7,"t":"愚頑人說美言並不相宜，君子說謊言也不合宜。","notes":[]},{"n":8,"t":"賄賂在餽贈者的眼中看為玉石，隨處運轉都得順利。","notes":[]},{"n":9,"t":"包容過錯的，尋求友愛；喋喋不休的，離間密友。","notes":[]},{"n":10,"t":"一句責備的話深入聰明人的心，強如打愚昧人一百下。","notes":[]},{"n":11,"t":"惡人只尋求背叛，殘忍的使者必奉差攻擊他。","notes":[]},{"n":12,"t":"寧可遇見失喪小熊的母熊，也不願遇見正行愚昧的愚昧人。","notes":[]},{"n":13,"t":"以惡報善的，禍患必不離他的家。","notes":[]},{"n":14,"t":"紛爭掀起，如同缺口的水；因此，爭端尚未爆發就當制止。","notes":[]},{"n":15,"t":"定惡人為義的，定義人為有罪的，都為耶和華所憎惡。","notes":[]},{"n":16,"t":"愚昧人既無知，為何手拿銀錢去買智慧呢？","notes":[]},{"n":17,"t":"朋友時常親愛，弟兄為患難而生。","notes":[]},{"n":18,"t":"在鄰舍面前擊掌擔保的，是無知的人。","notes":[]},{"n":19,"t":"喜愛爭吵的，是喜愛過犯；門蓋得高的，自取敗壞。","notes":[]},{"n":20,"t":"心中歪曲的，得不著福樂；舌頭顛倒是非的，陷在禍患中。","notes":[]},{"n":21,"t":"生愚昧之子的，自己必愁苦；愚頑人的父親毫無喜樂。","notes":[]},{"n":22,"t":"喜樂的心能治好疾病；憂傷的靈使骨頭枯乾。","notes":[]},{"n":23,"t":"惡人暗中受賄賂，以致彎曲公正的路。","notes":[]},{"n":24,"t":"聰明人面前有智慧；愚昧人眼望地的盡頭。","notes":[]},{"n":25,"t":"愚昧的兒子使父親愁煩，使那生他的母親憂苦。","notes":[]},{"n":26,"t":"刑罰義人實為不善，責打正直的君子也不宜。","notes":[]},{"n":27,"t":"節制言語的，有見識；性情溫良的人，有聰明。","notes":[]},{"n":28,"t":"愚妄人若靜默不言，可算為智慧，閉上嘴唇也可算為聰明。","notes":[]}]},"18":{"heading":"","verses":[{"n":1,"t":"孤僻的人只顧自己的心願，他鄙視一切健全的知識。","notes":["「只顧自己的心願」：七十士譯本和其他古譯本是「只顧為自己找藉口」。"]},{"n":2,"t":"愚昧人不喜愛聰明，只喜愛表達自己的心意。","notes":[]},{"n":3,"t":"邪惡來，藐視跟著來；羞恥到，辱罵同時到。","notes":[]},{"n":4,"t":"人的口所講的話如同深水，智慧之泉如湧流的河水。","notes":[]},{"n":5,"t":"偏袒惡人的情面，是不好的。審判時使義人受屈，也是不善。","notes":[]},{"n":6,"t":"愚昧人的嘴唇挑起爭端，一開口就招鞭打。","notes":[]},{"n":7,"t":"愚昧人的口自取敗壞，他的嘴唇是自己生命的圈套。","notes":[]},{"n":8,"t":"造謠者的話如同美食，深入人的肚腹。","notes":[]},{"n":9,"t":"做工懈怠的，是破壞者的兄弟。","notes":[]},{"n":10,"t":"耶和華的名是堅固臺，義人奔入就得安穩。","notes":[]},{"n":11,"t":"有錢人的財物是他堅固的城，在他幻想中，猶如高牆。","notes":[]},{"n":12,"t":"敗壞之先，人心驕傲；要得尊榮，先有謙卑。","notes":[]},{"n":13,"t":"未聽完就回話的，就是他的愚昧和羞辱。","notes":[]},{"n":14,"t":"人的心靈忍耐疾病；心靈憂傷，誰能承當呢？","notes":[]},{"n":15,"t":"聰明人的心得知識；智慧人的耳求知識。","notes":[]},{"n":16,"t":"人的禮物為他開路，引他到高位的人面前。","notes":[]},{"n":17,"t":"先訴情由的，似乎有理；另一人來到，就察出實情。","notes":[]},{"n":18,"t":"掣籤能止息紛爭，也能化解雙方激烈的爭辯。","notes":[]},{"n":19,"t":"被冒犯的弟兄強如難以攻下的堅城；紛爭如同城堡的門閂。","notes":["「被冒犯的弟兄」：七十士譯本是「弟兄互助」。"]},{"n":20,"t":"人的肚腹必因口所結的果實飽足；他必因嘴唇所出的感到滿足。","notes":[]},{"n":21,"t":"生死在舌頭的掌握之下，喜愛弄舌的，必吃它所結的果實。","notes":[]},{"n":22,"t":"得著妻子的，得著好處，他是蒙了耶和華的恩惠。","notes":[]},{"n":23,"t":"窮乏人說哀求的話；有錢人卻用威嚇的話回答。","notes":[]},{"n":24,"t":"朋友太多的人，必受損害；但有一知己比兄弟更親密。","notes":["「朋友...損害」或譯「有些朋友是玩弄友誼的」。"]}]},"19":{"heading":"","verses":[{"n":1,"t":"行為純正的窮乏人勝過嘴唇歪曲的愚昧人。","notes":[]},{"n":2,"t":"熱心而無見識，實為不善；腳步急快的，易入歧途。","notes":[]},{"n":3,"t":"人因愚昧自毀前途，他的心卻埋怨耶和華。","notes":[]},{"n":4,"t":"財富使朋友增多；貧寒人連僅有的朋友也離棄他。","notes":[]},{"n":5,"t":"作假見證的，難免受罰；口吐謊言的，不能逃脫。","notes":[]},{"n":6,"t":"有權貴的，許多人求他賞臉；愛送禮的，人都作他的朋友。","notes":[]},{"n":7,"t":"窮乏人連兄弟都恨他，何況朋友，更是遠離他！他用言語追隨，他們卻不在。","notes":[]},{"n":8,"t":"得著智慧的，愛惜生命；持守聰明的，尋得好處。","notes":[]},{"n":9,"t":"作假見證的，難免受罰；口吐謊言的，必定滅亡。","notes":[]},{"n":10,"t":"愚昧人奢華度日並不相宜，僕人管轄王子，也不應該。","notes":[]},{"n":11,"t":"人有見識就不輕易發怒，寬恕人的過失便是自己的榮耀。","notes":[]},{"n":12,"t":"王的憤怒好像獅子吼叫；他的恩惠卻如草上的甘露。","notes":[]},{"n":13,"t":"愚昧的兒子是父親的禍患，妻子的爭吵如雨連連滴漏。","notes":[]},{"n":14,"t":"房屋錢財是祖宗所遺留的；惟有賢慧的妻是耶和華所賜的。","notes":[]},{"n":15,"t":"懶惰使人沉睡，懈怠的人必捱餓。","notes":[]},{"n":16,"t":"遵守誡命的，保全生命；輕忽己路的，必致死亡。","notes":[]},{"n":17,"t":"憐憫貧寒人的，就是借給耶和華，他的報償，耶和華必歸還他。","notes":[]},{"n":18,"t":"趁還有指望，管教你的兒子，不可執意摧毀他。","notes":[]},{"n":19,"t":"暴怒的人必受懲罰，你若救他，必須再救。","notes":[]},{"n":20,"t":"要聽勸言，接受訓誨，使你終久有智慧。","notes":[]},{"n":21,"t":"人心多有計謀；惟有耶和華的籌算才能成就。","notes":[]},{"n":22,"t":"仁慈的人令人喜愛，窮乏人強如說謊言的。","notes":["「仁慈...喜愛」或譯「貪心是人的羞恥」。"]},{"n":23,"t":"敬畏耶和華的，得著生命，他必飽足安居，不遭禍患。","notes":[]},{"n":24,"t":"懶惰人把手埋入盤裏，連縮回送進口中也不肯。","notes":[]},{"n":25,"t":"責打傲慢人，能使無知的人變精明；責備聰明人，他就明白知識。","notes":[]},{"n":26,"t":"虐待父親、驅逐母親的，是蒙羞致辱之子。","notes":[]},{"n":27,"t":"我兒啊，停止聽那叫你偏離知識言語的教導。","notes":["「停止...教導」或譯「不可聽了教導而又偏離知識的言語」；又或譯「不可偏離知識的言語，要聽教導」。"]},{"n":28,"t":"卑劣的見證嘲笑公平，惡人的口吞下罪孽。","notes":[]},{"n":29,"t":"刑罰是為傲慢人預備的，鞭打則是為愚昧人的背預備的。","notes":[]}]},"20":{"heading":"","verses":[{"n":1,"t":"酒能使人傲慢，烈酒使人喧嚷，凡沉溺其中的，都無智慧。","notes":[]},{"n":2,"t":"王的威嚇如獅子吼叫，激怒他的是自害己命。","notes":[]},{"n":3,"t":"止息紛爭是人的尊榮，愚妄人爭鬧不休。","notes":[]},{"n":4,"t":"懶惰人因冬寒不去耕種，到收割時，他去尋找，一無所得。","notes":[]},{"n":5,"t":"人心中的籌算如同深水，惟聰明人才能汲引出來。","notes":[]},{"n":6,"t":"很多人聲稱自己忠信，但誠信的人誰能遇著呢？","notes":[]},{"n":7,"t":"義人行為純正，他後代的子孫有福了！","notes":[]},{"n":8,"t":"王坐在審判的位上，以眼目驅散一切邪惡。","notes":[]},{"n":9,"t":"誰能說：「我已經潔淨了我的心，脫淨了我的罪？」","notes":[]},{"n":10,"t":"兩樣的法碼和兩樣的伊法，都為耶和華所憎惡。","notes":["「伊法」是量固體的量器或單位；參「度量衡表」。"]},{"n":11,"t":"孩童的行動或純潔，或正直，都以行為顯明自己。","notes":[]},{"n":12,"t":"能聽的耳，能看的眼，二者都為耶和華所造。","notes":[]},{"n":13,"t":"不要貪睡，免致貧窮；眼要睜開，就可吃飽。","notes":[]},{"n":14,"t":"買東西的說：「不好，不好！」及至離去，他卻自誇。","notes":[]},{"n":15,"t":"有金子和許多寶石，惟知識的嘴唇是貴重的珍寶。","notes":[]},{"n":16,"t":"誰為陌生人擔保，就拿誰的衣服；誰為外邦人作保，誰就要承當。","notes":[]},{"n":17,"t":"靠謊言而得的食物，令人愉悅；到後來，他的口必充滿碎石。","notes":[]},{"n":18,"t":"計謀憑籌算立定，打仗要憑智謀。","notes":[]},{"n":19,"t":"到處傳話的，洩漏機密；口無遮攔的，不可與他結交。","notes":[]},{"n":20,"t":"咒罵父母的，他的燈必熄滅，在漆黑中。","notes":[]},{"n":21,"t":"起初很快得來的產業，終久卻不是福。","notes":[]},{"n":22,"t":"你不要說：「我要以惡報惡」；要等候耶和華，他必拯救你。","notes":[]},{"n":23,"t":"兩樣的法碼為耶和華所憎惡，詭詐的天平也為不善。","notes":[]},{"n":24,"t":"人的腳步為耶和華所定，人豈能明白自己的道路呢？","notes":[]},{"n":25,"t":"人冒失地聲稱：「這是神聖的！」許願之後才細想，就是自陷圈套。","notes":[]},{"n":26,"t":"智慧的王驅散惡人，用輪子滾過他們。","notes":[]},{"n":27,"t":"人的靈是耶和華的燈，鑒察人的內心深處。","notes":[]},{"n":28,"t":"慈愛和誠實庇護君王，他的王位因慈愛而立穩。","notes":[]},{"n":29,"t":"強壯是青年的榮耀；白髮為老人的尊榮。","notes":[]},{"n":30,"t":"鞭傷除淨邪惡，責打可潔淨人心深處。","notes":[]}]},"21":{"heading":"","verses":[{"n":1,"t":"王的心在耶和華手中像河水，他能使它隨意流轉。","notes":[]},{"n":2,"t":"人一切所行的，在自己眼中看為正直，惟有耶和華衡量人心。","notes":[]},{"n":3,"t":"行公義和公平比獻祭更蒙耶和華悅納。","notes":[]},{"n":4,"t":"眼高心傲，就是惡人的燈，都是罪。","notes":[]},{"n":5,"t":"殷勤籌劃的，足致豐裕；行事急躁的，必致缺乏。","notes":[]},{"n":6,"t":"用詭詐之舌所得的財富如被吹散的霧氣，趨向滅亡。","notes":["「趨向滅亡」：有古卷、七十士譯本和其他古譯本是「和死亡的圈套」。"]},{"n":7,"t":"惡人的殘暴必掃去自己，因他們不肯按公平行事。","notes":[]},{"n":8,"t":"有罪的人其路彎曲；純潔的人行為正直。","notes":[]},{"n":9,"t":"寧可住在房頂的一角，也不與好爭吵的婦人同住。","notes":[]},{"n":10,"t":"惡人的心渴想邪惡，他的眼並不憐憫鄰舍。","notes":[]},{"n":11,"t":"傲慢人受懲罰，愚蒙人可得智慧；智慧人受訓誨，便得知識。","notes":[]},{"n":12,"t":"公義的神鑒察惡人的家，他傾覆惡人，以致滅亡。","notes":["「公義的神」或譯「義人」。"]},{"n":13,"t":"塞耳不聽貧寒人哀求的，他自己呼求，也不蒙應允。","notes":[]},{"n":14,"t":"暗中送的禮物挽回怒氣，懷裏的賄賂能止息暴怒。","notes":[]},{"n":15,"t":"秉公行義使義人喜樂，卻使作惡的人敗壞。","notes":[]},{"n":16,"t":"人偏離智慧的路，必與陰魂為伍。","notes":["「必與陰魂為伍」：原文是「必住在陰魂的會中」。"]},{"n":17,"t":"愛宴樂的，必致窮乏；貪愛酒和油的，必不富足。","notes":[]},{"n":18,"t":"惡人作義人的贖價，奸詐人代替正直人。","notes":[]},{"n":19,"t":"寧可住在曠野之地，也不與爭吵易怒的婦人同住。","notes":[]},{"n":20,"t":"智慧人的居所積蓄寶物與膏油；愚昧人卻揮霍一空。","notes":["「智慧人...膏油」：七十士譯本是「渴慕的寶物留在智慧人的嘴上」。"]},{"n":21,"t":"追求公義慈愛的，就尋得生命、公義和尊榮。","notes":["七十士譯本沒有「公義」。"]},{"n":22,"t":"智慧人爬上勇士的城牆，摧毀他所倚靠的堡壘。","notes":[]},{"n":23,"t":"謹守口和舌的，就保護自己免受災難。","notes":[]},{"n":24,"t":"心驕氣傲的人名叫傲慢，他行事出於狂妄驕傲。","notes":[]},{"n":25,"t":"懶惰人的慾望害死自己，因為他的手不肯做工；","notes":[]},{"n":26,"t":"有人終日貪得無饜，義人卻施捨而不吝惜。","notes":[]},{"n":27,"t":"惡人獻的祭是可憎的，何況他存惡意來獻呢？","notes":[]},{"n":28,"t":"不實的見證必消滅；惟聆聽真情的，他的證詞有力。","notes":[]},{"n":29,"t":"惡人臉無羞恥；正直人行事堅定。","notes":["「正直人行事堅定」：原文另譯「正直人明白己道」。"]},{"n":30,"t":"沒有人能以智慧、聰明、謀略抵擋耶和華。","notes":[]},{"n":31,"t":"馬是為打仗之日預備的；得勝卻在於耶和華。","notes":[]}]},"22":{"heading":"智言三十則","verses":[{"n":1,"t":"美名勝過大財，宏恩強如金銀。","notes":[]},{"n":2,"t":"有錢人與窮乏人相遇，他們都為耶和華所造。","notes":["「相遇」或譯「是一樣的」。"]},{"n":3,"t":"通達人見禍就藏躲；愚蒙人卻前往受害。","notes":[]},{"n":4,"t":"敬畏耶和華心存謙卑，就得財富、尊榮、生命為賞賜。","notes":[]},{"n":5,"t":"歪曲的人路上有荊棘和羅網，保護自己生命的，必要遠離。","notes":[]},{"n":6,"t":"教養孩童走當行的道，就是到老他也不偏離。","notes":["七十士譯本沒有本節。"]},{"n":7,"t":"有錢人管轄窮乏人，欠債的是債主的僕人。","notes":[]},{"n":8,"t":"撒不義種子的必收割災禍，他逞怒的杖也必廢掉。","notes":[]},{"n":9,"t":"眼目仁慈的必蒙福，因他將食物分給貧寒人。","notes":[]},{"n":10,"t":"趕出傲慢人，爭端就消除，紛爭和羞辱也必止息。","notes":[]},{"n":11,"t":"喜愛清心，嘴唇有恩言的，王必與他為友。","notes":[]},{"n":12,"t":"耶和華的眼目保護知識，卻毀壞奸詐人的言語。","notes":[]},{"n":13,"t":"懶惰人說：「外面有獅子，我在街上必被殺害。」","notes":[]},{"n":14,"t":"陌生女子的口是深坑，耶和華所憎惡的，必陷在其中。","notes":[]},{"n":15,"t":"愚昧迷住孩童的心，用管教的杖可以遠遠趕除。","notes":[]},{"n":16,"t":"欺壓貧寒人為要利己的，並送禮給有錢人的，都必缺乏。","notes":[]},{"n":17,"t":"你要側耳聽智慧人的言語，留心領會我的知識。","notes":["「你要...言語」：七十士譯本是「智慧人的言語：你要側耳聽我的言語」。"]},{"n":18,"t":"你若心中存記，嘴唇也準備就緒，這是美的。","notes":[]},{"n":19,"t":"我今日特地指教你，為要使你倚靠耶和華。","notes":[]},{"n":20,"t":"謀略和知識的美事，我豈沒有寫給你嗎？","notes":["「美事」：原文另譯「三十句」。"]},{"n":21,"t":"要使你明白真情實理，好將實情回覆那差你來的人。","notes":[]},{"n":22,"t":"不可因人貧寒就搶奪他，也不可在城門口欺壓困苦人，","notes":[]},{"n":23,"t":"因耶和華必為他們辯護，也必奪取那搶奪者的命。","notes":[]},{"n":24,"t":"不可結交好生氣的人，也不可與暴怒的人來往，","notes":[]},{"n":25,"t":"恐怕你效法他的行為，自己就陷在圈套裏。","notes":[]},{"n":26,"t":"不要為人擊掌擔保，也不要為債務作保。","notes":[]},{"n":27,"t":"你若沒有甚麼可償還，何必使人奪去你睡臥的床呢？","notes":[]},{"n":28,"t":"祖先所立的地界，你不可挪移。","notes":[]},{"n":29,"t":"你看見辦事殷勤的人嗎？他必侍立在君王面前，不在平庸的人面前。","notes":[]}]},"23":{"heading":"","verses":[{"n":1,"t":"你若與長官坐席，要留意在你面前的是誰。","notes":[]},{"n":2,"t":"你若是胃口大的人，就當拿刀放在喉嚨上。","notes":[]},{"n":3,"t":"不可貪戀長官的美食，因為那是欺哄人的食物。","notes":[]},{"n":4,"t":"不要勞碌求富，要有聰明來節制。","notes":[]},{"n":5,"t":"你定睛在財富，它就消失，因為它必長翅膀，如鷹向天飛去。","notes":[]},{"n":6,"t":"守財奴的飯，你不要吃，也不要貪戀他的美味；","notes":["「守財奴」：原文直譯「眼目邪惡的人」。"]},{"n":7,"t":"因為他的心怎樣算計，他為人就是這樣。他雖對你說：請吃，請喝，他的心卻與你相背。","notes":["「心怎樣算計」：原文另譯「喉嚨有頭髮」。"]},{"n":8,"t":"你所吃的那點食物必吐出來，你恭維的話語也必落空。","notes":[]},{"n":9,"t":"不要說話給愚昧人聽，因他必藐視你智慧的言語。","notes":[]},{"n":10,"t":"不可挪移古時的地界，也不可侵佔孤兒的田地，","notes":[]},{"n":11,"t":"因他們的救贖者大有能力，他必向你為他們辯護。","notes":["「救贖者」或譯「贖業至親」。"]},{"n":12,"t":"你要留心領受訓誨，側耳聽從知識的言語。","notes":[]},{"n":13,"t":"不可不管教孩童，因為你用杖打他，他不會死。","notes":[]},{"n":14,"t":"你用杖打他，就可以救他的性命免下陰間。","notes":[]},{"n":15,"t":"我兒啊，你若心存智慧，我的心就甚歡喜。","notes":[]},{"n":16,"t":"你的嘴唇若說正直話，我的心腸也必快樂。","notes":[]},{"n":17,"t":"你的心不要羨慕罪人，卻要羨慕常常敬畏耶和華的人，","notes":[]},{"n":18,"t":"因為你必有前途，你的指望也不致斷絕。","notes":[]},{"n":19,"t":"我兒啊，你當聽，當存智慧，好在正道上引導你的心。","notes":[]},{"n":20,"t":"不可與好飲酒的人在一起，也不要跟貪吃肉的人來往，","notes":[]},{"n":21,"t":"因為貪食好酒的，必致貧窮，愛睡覺的，必穿破爛衣服。","notes":[]},{"n":22,"t":"你要聽從生你的父親；不可因母親年老而輕看她。","notes":[]},{"n":23,"t":"你當獲得真理，不可出賣，智慧、訓誨和聰明也是一樣。","notes":[]},{"n":24,"t":"義人的父親必大大快樂，生智慧兒子的，必因他歡喜。","notes":[]},{"n":25,"t":"願你的父母歡喜，願那生你的母親快樂。","notes":[]},{"n":26,"t":"我兒啊，要將你的心歸我，你的眼目也要喜愛我的道路。","notes":["「喜愛」：原文另譯「謹守」。"]},{"n":27,"t":"妓女是深坑，外邦女子是窄井。","notes":[]},{"n":28,"t":"她像強盜埋伏，她使奸詐的人增多。","notes":[]},{"n":29,"t":"誰有禍患？誰有災難？誰有紛爭？誰有焦慮？誰無故受傷？誰的眼目紅赤？","notes":[]},{"n":30,"t":"就是那流連飲酒的人，常去尋找調和的酒。","notes":[]},{"n":31,"t":"酒發紅，在杯中閃爍時，你不可觀看；雖下咽舒暢，終究它必咬你如蛇，刺你如毒蛇。","notes":[],"end":32},{"n":33,"t":"你的眼睛必看見怪異的事，你的心必發出乖謬的話。","notes":[]},{"n":34,"t":"你必像躺在深海中，或臥在桅杆頂上，","notes":[]},{"n":35,"t":"說：「人擊打我，但我未受傷，重擊我，我不覺得。我幾時清醒，還要再去尋酒。」","notes":[]}]},"24":{"heading":"其他智言","verses":[{"n":1,"t":"你不要嫉妒惡人，也不要渴望與他們相處，","notes":[]},{"n":2,"t":"因為他們的心圖謀暴行，他們的嘴唇談論奸惡。","notes":[]},{"n":3,"t":"房屋因智慧建造，因聰明立穩；","notes":[]},{"n":4,"t":"又因知識，屋內充滿各樣美好寶貴的財物。","notes":[]},{"n":5,"t":"有智慧的勇士大有能力，有知識的人力上加力。","notes":[]},{"n":6,"t":"你去打仗，要憑智謀；謀士眾多，就必得勝。","notes":[]},{"n":7,"t":"對愚妄人，智慧高不可及，所以他在城門不敢開口。","notes":[]},{"n":8,"t":"圖謀行惡的，必稱為奸詐人。","notes":[]},{"n":9,"t":"愚妄人的籌劃盡是罪惡，傲慢者為人所憎惡。","notes":[]},{"n":10,"t":"在患難時你若灰心，你的力量就微小。","notes":[]},{"n":11,"t":"人被拉到死亡，你要解救；人將被殺，你須攔阻。","notes":[]},{"n":12,"t":"你若說：「看哪，這事我們不知道」，那衡量人心的豈不明白嗎？保護你性命的豈不知道嗎？他豈不按各人所做的報應各人嗎？","notes":[]},{"n":13,"t":"我兒啊，你要吃蜜，因為它是美好的，要讓甘甜的蜜滴入你的口。","notes":[]},{"n":14,"t":"你要知道，智慧對你的生命正像如此。你若找著，必有前途，你的指望也不致斷絕。","notes":[]},{"n":15,"t":"你這惡人，不可埋伏攻擊義人的家，也不可毀壞他安居之所。","notes":[]},{"n":16,"t":"因為義人雖七次跌倒，仍必興起；惡人卻被禍患傾倒。","notes":[]},{"n":17,"t":"你的仇敵跌倒，你不要歡喜，他傾倒，你的心不要快樂；","notes":[]},{"n":18,"t":"恐怕耶和華看見就不喜悅，將怒氣從仇敵身上轉過來。","notes":[]},{"n":19,"t":"不要為作惡的心懷不平，也不要嫉妒惡人，","notes":[]},{"n":20,"t":"因為壞人沒有前途，惡人的燈也必熄滅。","notes":[]},{"n":21,"t":"我兒啊，你要敬畏耶和華與君王，不可結交反覆無常的人，","notes":[]},{"n":22,"t":"因為他們的災難必忽然興起。誰能知道耶和華與君王所施行的毀滅呢？","notes":[]},{"n":23,"t":"以下也是智慧人的箴言：審判時看人情面是不好的。","notes":[]},{"n":24,"t":"對惡人說「你是義人」的，萬民必詛咒，萬族必惱恨。","notes":[]},{"n":25,"t":"責備惡人的，必得喜悅，美好的福分也必臨到他。","notes":[]},{"n":26,"t":"應對合宜的，猶如與人親吻。","notes":[]},{"n":27,"t":"你要在外面預備材料，在田間為自己準備齊全，然後才建造你的房屋。","notes":[]},{"n":28,"t":"不可無故作證反對鄰舍，也不可用嘴唇欺騙人。","notes":[]},{"n":29,"t":"不可說：「人怎樣待我，我也怎樣待他，我必照他所做的報復他。」","notes":[]},{"n":30,"t":"我經過懶惰人的田地，走過無知人的葡萄園，","notes":[]},{"n":31,"t":"看哪，它長滿了荊棘，蕁麻蓋地面，石牆也坍塌了。","notes":[]},{"n":32,"t":"我看見就留心思想，我看著就領受訓誨。","notes":[]},{"n":33,"t":"再睡片時，打盹片時，抱著雙臂躺臥片時，","notes":[]},{"n":34,"t":"你的貧窮就如盜賊來到，你的貧乏彷彿拿盾牌的人來臨。","notes":[]}]},"25":{"heading":"所羅門的另一些箴言","verses":[{"n":1,"t":"以下也是所羅門的箴言，是猶大王希西家的人所謄錄的。","notes":[]},{"n":2,"t":"隱藏事情是神的榮耀；查明事情乃君王的榮耀。","notes":[]},{"n":3,"t":"天之高，地之深，君王之心測不透。","notes":[]},{"n":4,"t":"除去銀子的渣滓，銀匠就做出器皿來。","notes":[]},{"n":5,"t":"除去王面前的惡人，國位就靠公義堅立。","notes":[]},{"n":6,"t":"不可在君王面前妄自尊大，也不要站在大人的位上。","notes":[]},{"n":7,"t":"寧可讓人家說「請你上到這裏來」，強如在你覲見的貴人面前令你退下。","notes":[]},{"n":8,"t":"不要冒失出去與人爭訟 ，免得你的鄰舍羞辱你，最後你就不知怎麼做。","notes":["「強如...爭訟」或譯「強如在貴人面前令你退下。你所看見的，不要冒失出去與人爭訟」。"]},{"n":9,"t":"要與鄰舍爭辯你的案情，不可洩漏他人的隱密，","notes":[]},{"n":10,"t":"恐怕聽見的人責罵你，你就難以擺脫臭名。","notes":[]},{"n":11,"t":"一句話說得合宜，就如金蘋果在銀網子裏。","notes":["「在銀網子裏」或譯「在銀的底座上」。"]},{"n":12,"t":"智慧人的勸戒在順從的人耳中，好像金環和金首飾。","notes":[]},{"n":13,"t":"忠信的使者對那差他的人，就如收割時有冰雪的涼氣，使主人的心舒暢。","notes":[]},{"n":14,"t":"人空誇禮物而不肯贈送，就好像有風有雲卻無雨。","notes":[]},{"n":15,"t":"恆常的忍耐可以勸服君王，柔和的舌頭能折斷骨頭。","notes":[]},{"n":16,"t":"你得了蜜，吃夠就好，免得過飽就吐出來。","notes":[]},{"n":17,"t":"你的腳要少進鄰舍的家，免得他厭煩你，恨惡你。","notes":[]},{"n":18,"t":"作假見證陷害鄰舍的，就是大錘，是利刀，是快箭。","notes":[]},{"n":19,"t":"患難時倚靠奸詐的人，好像牙齒斷裂，又如腳脫臼。","notes":[]},{"n":20,"t":"對傷心的人唱歌，就如冷天脫他的衣服，又如在鹼上倒醋。","notes":["「在鹼上倒醋」：七十士譯本是「在傷口上灑醋」。"]},{"n":21,"t":"你的仇敵若餓了，就給他飯吃，若渴了，就給他水喝；","notes":[]},{"n":22,"t":"因為你這樣做，就是把炭火堆在他的頭上，耶和華必回報你。","notes":[]},{"n":23,"t":"正如北風生雨，毀謗的舌頭也生怒容。","notes":[]},{"n":24,"t":"寧可住在房頂的一角，也不與好爭吵的婦人同住。","notes":[]},{"n":25,"t":"有好消息從遙遠的地方來，就如涼水滋潤口渴的人。","notes":[]},{"n":26,"t":"義人在惡人面前退縮，好像攪渾之泉，污染之井。","notes":[]},{"n":27,"t":"吃蜜過多是不好的，自求榮耀也是一樣。","notes":[]},{"n":28,"t":"人不克制自己的心，就像毀壞的城沒有牆。","notes":[]}]},"26":{"heading":"","verses":[{"n":1,"t":"愚昧人得尊榮不相宜，正如夏天落雪，收割時下雨。","notes":[]},{"n":2,"t":"詛咒不會無故臨到，正如麻雀掠過，燕子翻飛。","notes":["「詛咒...臨到」：原文另譯「無故的詛咒必返回自己身上」。"]},{"n":3,"t":"鞭子是為打馬，轡頭是為勒驢，刑杖正是為打愚昧人的背。","notes":[]},{"n":4,"t":"不要照愚昧人的愚昧話回答他，免得你與他一樣。","notes":[]},{"n":5,"t":"要照愚昧人的愚昧話回答他，免得他自以為有智慧。","notes":[]},{"n":6,"t":"藉愚昧人的手寄信的，就像砍斷雙腳，喝下殘暴。","notes":[]},{"n":7,"t":"箴言在愚昧人的口中，正如瘸子的腳懸空無用。","notes":[]},{"n":8,"t":"將尊榮給愚昧人的，就像石頭綁在彈弓上。","notes":[]},{"n":9,"t":"箴言在愚昧人的口中，好像荊棘刺入醉漢的手。","notes":[]},{"n":10,"t":"雇愚昧人的，與雇過路人的，就像弓箭手射傷任何人。","notes":[]},{"n":11,"t":"愚昧人重複做愚昧之事，就如狗轉過來吃自己所吐的。","notes":[]},{"n":12,"t":"你看見自以為有智慧的人嗎？愚昧人比他更有指望。","notes":[]},{"n":13,"t":"懶惰人說：「道路有猛獅，街上有壯獅。」","notes":[]},{"n":14,"t":"懶惰人在床上，就像門在軸心上轉動一樣。","notes":[]},{"n":15,"t":"懶惰人把手埋入盤裏，就是送進口中也覺得累。","notes":[]},{"n":16,"t":"懶惰人眼看自己比七個善於應對的人更有智慧。","notes":[]},{"n":17,"t":"過路時捲入與己無關的紛爭，好像人揪住狗耳一般。","notes":[]},{"n":18,"t":"人欺騙鄰舍，卻說「我只是開玩笑而已」，他就像瘋狂的人拋擲致死的火把和利箭。","notes":[],"end":19},{"n":20,"t":"火缺了柴就必熄滅；無人造謠，紛爭就止息。","notes":[]},{"n":21,"t":"好爭吵的人煽動爭端，就如餘火加炭，火上加柴一樣。","notes":[]},{"n":22,"t":"造謠者的話如同美食，深入人的肚腹。","notes":[]},{"n":23,"t":"火熱的嘴唇，邪惡的心，好像銀渣包在瓦器上。","notes":["「火熱的」：七十士譯本是「油滑的」。"]},{"n":24,"t":"仇敵用嘴唇掩飾，心裏卻藏著詭詐；","notes":[]},{"n":25,"t":"他用甜言蜜語，你不能相信他，因為他心中有七樣可憎惡的事。","notes":[]},{"n":26,"t":"他雖用詭詐掩飾怨恨，他的邪惡必在集會中顯露。","notes":[]},{"n":27,"t":"挖陷坑的，自己必陷在其中；滾石頭的，石頭反滾在他身上。","notes":[]},{"n":28,"t":"虛謊的舌憎恨他所壓傷的人；諂媚的口敗壞人的事。","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"不要為明天自誇，因為你不知道每天會發生何事。","notes":[]},{"n":2,"t":"要讓陌生人誇獎你，不可用口自誇；讓外邦人稱讚你，不可用嘴唇稱讚自己。","notes":[]},{"n":3,"t":"石頭沉，沙土重，愚妄人的惱怒比這兩樣更沉重。","notes":[]},{"n":4,"t":"憤怒為殘忍，怒氣像狂瀾，惟有嫉妒，誰能擋得住呢？","notes":[]},{"n":5,"t":"當面的責備勝過隱藏的愛情。","notes":[]},{"n":6,"t":"朋友加的傷痕出於忠誠；敵人的親吻卻是多餘。","notes":[]},{"n":7,"t":"人吃飽了，厭惡蜂房的蜜；人飢餓了，一切苦物都覺甘甜。","notes":[]},{"n":8,"t":"人離故鄉漂泊，就像雀鳥離窩四處飛翔。","notes":[]},{"n":9,"t":"膏油與香料使人心喜悅，朋友誠心的勸勉也是如此甘美。","notes":[]},{"n":10,"t":"你的朋友和父親的朋友，你都不可離棄。你遭難時，不要上兄弟的家去；相近的鄰舍強如遠方的兄弟。","notes":[]},{"n":11,"t":"我兒啊，你要做智慧人，好叫我的心歡喜，使我可以回答那辱罵我的人。","notes":[]},{"n":12,"t":"通達人見禍就藏躲；愚蒙人卻前往受害。","notes":[]},{"n":13,"t":"誰為陌生人擔保，就拿誰的衣服；誰為外邦女子作保，誰就要承當。","notes":[]},{"n":14,"t":"清晨起來大聲給朋友祝福的，就算是詛咒他。","notes":[]},{"n":15,"t":"下雨天連連滴漏，好爭吵的婦人就像這樣；","notes":[]},{"n":16,"t":"攔阻她的，就是攔阻風，又像用右手抓油。","notes":[]},{"n":17,"t":"以鐵磨鐵，越磨越利，朋友當面琢磨，也是如此。","notes":[]},{"n":18,"t":"看守無花果樹的，必吃樹上的果子；敬奉主人的，必得尊榮。","notes":[]},{"n":19,"t":"水中照臉，彼此相符；人心相映，也是如此。","notes":[]},{"n":20,"t":"陰間和冥府永不滿足，人的眼目也是如此。","notes":["「冥府」：原文音譯「亞巴頓」，意思是「滅亡之地」。"]},{"n":21,"t":"鼎為煉銀，爐為煉金，口中的稱讚也試煉人。","notes":[]},{"n":22,"t":"用杵把愚妄人與穀粒一同搗在臼中，他的愚昧還是離不了他。","notes":[]},{"n":23,"t":"你要詳細知道你羊群的景況，留心照顧你的牛群，","notes":[]},{"n":24,"t":"因為財富不能永留，冠冕豈能存到萬代？","notes":[]},{"n":25,"t":"青草除去，嫩草長出，山上的菜蔬也被採收。","notes":[]},{"n":26,"t":"綿羊可以做衣服，公山羊可作田地的價值，","notes":[]},{"n":27,"t":"並有母山羊奶夠你吃，夠你養家和女僕的生活。","notes":[]}]},"28":{"heading":"","verses":[{"n":1,"t":"惡人雖無人追趕也逃跑；義人卻膽壯像獅子。","notes":[]},{"n":2,"t":"地上因有罪過，君王就多更換；因聰明和有見識的人，國必長存。","notes":[]},{"n":3,"t":"窮乏人欺壓貧寒人，好像暴雨掃過，不留糧食。","notes":[]},{"n":4,"t":"離棄律法的，誇獎惡人；遵守律法的，卻與惡人相爭。","notes":[]},{"n":5,"t":"惡人不明白公義；惟有尋求耶和華的，無不明白。","notes":[]},{"n":6,"t":"行為純正的窮乏人勝過行事歪曲的有錢人。","notes":[]},{"n":7,"t":"謹守教誨的，是聰明之子；與貪食者為伍的，卻羞辱其父。","notes":[]},{"n":8,"t":"人以厚利增加財富，是給那憐憫貧寒人的積財。","notes":[]},{"n":9,"t":"轉耳不聽教誨的，他的祈禱也可憎。","notes":[]},{"n":10,"t":"誘惑正直人行惡道的，必掉在自己的坑裏；惟有完全人必承受福分。","notes":[]},{"n":11,"t":"有錢人自以為有智慧，但聰明的貧寒人能看穿他。","notes":[]},{"n":12,"t":"義人高升，有大榮耀；惡人興起，人就躲藏。","notes":[]},{"n":13,"t":"遮掩自己過犯的，必不順利；承認且離棄過犯的，必蒙憐憫。","notes":[]},{"n":14,"t":"常存敬畏的，這人有福了；心裏剛硬的，必陷在禍患裏。","notes":[]},{"n":15,"t":"邪惡的君王壓制貧民，好像吼叫的獅子，又如覓食的熊。","notes":[]},{"n":16,"t":"無知的君王多行暴虐；恨惡非分之財的，必年長日久。","notes":[]},{"n":17,"t":"背負流人血之罪的，必逃跑直到地府；願無人幫助他！","notes":[]},{"n":18,"t":"行為正直的，必蒙拯救；行事彎曲的，立時跌倒。","notes":[]},{"n":19,"t":"耕種自己田地的，糧食充足；追求虛浮的，窮困潦倒。","notes":[]},{"n":20,"t":"誠實人必多得福；想要急速發財的，難免受罰。","notes":[]},{"n":21,"t":"看人情面是不好的；卻有人因一塊餅而犯法。","notes":[]},{"n":22,"t":"守財奴想要急速發財，卻不知窮乏必臨到他身上。","notes":["「守財奴」：原文直譯「眼目邪惡的人」。"]},{"n":23,"t":"責備人的，後來蒙人喜悅，多於那用舌頭諂媚人的。","notes":[]},{"n":24,"t":"搶奪父母竟說「這不是罪過」，此人與毀滅者同類。","notes":[]},{"n":25,"t":"心中貪婪的，挑起爭端；倚靠耶和華的，必得豐裕。","notes":[]},{"n":26,"t":"心中自以為是的，就是愚昧人；憑智慧行事的，必蒙拯救。","notes":[]},{"n":27,"t":"賙濟窮乏人的，不致缺乏；遮眼不看的，多受詛咒。","notes":[]},{"n":28,"t":"惡人興起，人就躲藏；惡人敗亡，義人必增多。","notes":[]}]},"29":{"heading":"","verses":[{"n":1,"t":"人屢次受責罰，仍然硬著頸項，他必頃刻被毀，無從醫治。","notes":[]},{"n":2,"t":"義人增多，民就喜樂；惡人掌權，民就嘆息。","notes":[]},{"n":3,"t":"愛慕智慧的，使父親喜樂；結交妓女的，卻浪費錢財。","notes":[]},{"n":4,"t":"王藉公平，使國堅定；強索貢物的，使它毀壞。","notes":[]},{"n":5,"t":"諂媚鄰舍的，就是設網羅絆他的腳。","notes":[]},{"n":6,"t":"惡人犯罪，自陷圈套；惟獨義人歡呼喜樂。","notes":[]},{"n":7,"t":"義人關注貧寒人的案情；惡人不明瞭這種知識。","notes":[]},{"n":8,"t":"傲慢人煽動全城；智慧人止息眾怒。","notes":[]},{"n":9,"t":"智慧人與愚妄人有爭訟，或怒或笑，總不得安寧。","notes":[]},{"n":10,"t":"好流人血的，恨惡完全人，正直人卻顧惜他的性命。","notes":["「顧惜」：原文是「尋索」。"]},{"n":11,"t":"愚昧人怒氣全發；智慧人自我平息。","notes":[]},{"n":12,"t":"君王若聽謊言，他一切臣僕都是奸惡。","notes":[]},{"n":13,"t":"窮乏人和欺壓者相遇，耶和華使他們的眼目明亮。","notes":["「相遇」或譯「是一樣的」。"]},{"n":14,"t":"君王憑誠信判斷貧寒人，他的國位必永遠堅立。","notes":[]},{"n":15,"t":"杖打和責備能增加智慧；任性的少年使母親羞愧。","notes":[]},{"n":16,"t":"惡人多，過犯也加多，義人必看見他們敗亡。","notes":[]},{"n":17,"t":"管教你的兒子，他就使你得安寧，也使你心裏喜樂。","notes":[]},{"n":18,"t":"沒有異象，民就放肆；惟遵守律法的，便為有福。","notes":["「異象」或譯「默示」。"]},{"n":19,"t":"僕人不能靠言語受教；他即使明白，也不回應。","notes":[]},{"n":20,"t":"你見過言語急躁的人嗎？愚昧人比他更有指望。","notes":[]},{"n":21,"t":"人將僕人從小嬌養，至終必帶來憂傷。","notes":["「至終必帶來憂傷」或譯「這僕人至終必成了他的繼承人」。"]},{"n":22,"t":"好生氣的人挑起爭端，暴怒的人多多犯錯。","notes":[]},{"n":23,"t":"人的高傲使自己蒙羞；心裏謙遜的，必得尊榮。","notes":[]},{"n":24,"t":"與盜賊分贓的，是恨惡自己的性命；他雖聽見發誓的聲音，也不告訴人。","notes":[]},{"n":25,"t":"懼怕人的，陷入圈套；惟有倚靠耶和華的，必得安穩。","notes":[]},{"n":26,"t":"求王恩的人多；人獲公正來自耶和華。","notes":[]},{"n":27,"t":"不義之人，義人憎惡；行事正直的，惡人憎惡。","notes":[]}]},"30":{"heading":"亞古珥語錄","verses":[{"n":1,"t":"雅基的兒子、瑪撒人亞古珥的言語，是這人對以鐵和烏甲說的。","notes":["「雅基...言語」或譯「雅基的兒子亞古珥的言語，就是神諭」。"]},{"n":2,"t":"我比眾人更像畜牲，也沒有人的聰明。","notes":[]},{"n":3,"t":"我沒有學好智慧，也不認識至聖者。","notes":[]},{"n":4,"t":"誰升天又降下來？誰聚風在手掌中？誰包水在衣服裏？誰立定地的四極？他名叫甚麼？他兒子名叫甚麼？你知道嗎？","notes":[]},{"n":5,"t":"神的言語句句都是煉淨的，投靠他的，他便作他們的盾牌。","notes":[]},{"n":6,"t":"你不可加添他的言語，恐怕他責備你，你就顯為說謊的。","notes":[]},{"n":7,"t":"我求你兩件事，在我未死之先，不要拒絕我：","notes":[],"heads":["其他箴言"]},{"n":8,"t":"求你使虛假和謊言遠離我，使我不貧窮也不富足，賜給我需用的飲食。","notes":[]},{"n":9,"t":"免得我飽足了，就不認你，說：「耶和華是誰呢？」又恐怕我貧窮就偷竊，以致褻瀆我神的名。","notes":[]},{"n":10,"t":"不要向主人讒害他的僕人，恐怕他詛咒你，你便算為有罪。","notes":[]},{"n":11,"t":"有一類人，詛咒父親，不給母親祝福。","notes":[]},{"n":12,"t":"有一類人，自以為純潔，卻沒有洗淨自己的污穢。","notes":[]},{"n":13,"t":"有一類人，眼目何其高傲，眼皮也是高舉。","notes":[]},{"n":14,"t":"有一類人，牙如劍，齒如刀，要吞滅地上的困苦人和世間的貧窮人。","notes":[]},{"n":15,"t":"水蛭有兩個女兒：「給呀，給呀。」有三樣不知足的，不說「夠了」的有四樣：","notes":[]},{"n":16,"t":"陰間和不生育的子宮，吸水不足的地，還有不說「夠了」的火。","notes":[]},{"n":17,"t":"嘲笑父親、藐視而不聽從母親的，谷中的烏鴉必啄他的眼睛，小鷹也必吃它。","notes":[]},{"n":18,"t":"我所測不透的奇妙有三樣，我所不知道的有四樣：","notes":[]},{"n":19,"t":"就是鷹在空中飛的道，蛇在磐石上爬的道，船在海中行的道，男與女交合的道。","notes":[]},{"n":20,"t":"淫婦的道是這樣，她吃了，把嘴一擦就說：「我沒有行惡。」","notes":[]},{"n":21,"t":"使地震動的有三樣，地承擔不起的有四樣：","notes":[]},{"n":22,"t":"就是僕人作王，愚頑人吃得飽足，","notes":[]},{"n":23,"t":"令人憎惡的女子出嫁，婢女取代她的女主人。","notes":[]},{"n":24,"t":"地上有四樣東西雖小，卻甚聰明：","notes":[]},{"n":25,"t":"螞蟻是無力之類，卻在夏天預備糧食。","notes":[]},{"n":26,"t":"石獾並非強壯之類，卻在巖石中造房子。","notes":[]},{"n":27,"t":"蝗蟲沒有君王，卻分隊而出。","notes":[]},{"n":28,"t":"壁虎你用手就可抓住，牠卻住在王宮。","notes":[]},{"n":29,"t":"腳步威武的有三樣，行走威武的有四樣：","notes":[]},{"n":30,"t":"獅子－百獸中最勇猛的、無論遇見甚麼絕不退縮，","notes":[]},{"n":31,"t":"獵狗，公山羊，和有整排士兵的君王。","notes":[]},{"n":32,"t":"你若行事愚頑，自高自傲，或是設計惡謀，就當用手摀口。","notes":[]},{"n":33,"t":"攪動牛奶必成乳酪，扭鼻子必出血，照樣，激發烈怒必挑起爭端。","notes":[]}]},"31":{"heading":"給君王的忠告","verses":[{"n":1,"t":"瑪撒王利慕伊勒的言語，就是他母親教導他的。","notes":["「瑪撒王...他的」或譯「利慕伊勒王的言語，是他母親教導他的神諭」。"]},{"n":2,"t":"我兒，怎麼了？我腹中生的兒，怎麼了？我許願而得的兒，怎麼了？","notes":[]},{"n":3,"t":"不要將你的精力給婦女，也不要有敗壞君王的行為。","notes":[]},{"n":4,"t":"利慕伊勒啊，君王不宜，君王不宜喝酒，王子尋找烈酒也不相宜；","notes":[]},{"n":5,"t":"恐怕喝了就忘記所頒的法令，顛倒所有困苦人的是非。","notes":[]},{"n":6,"t":"可以把烈酒給將亡的人喝，把酒給心裏愁苦的人喝，","notes":[]},{"n":7,"t":"讓他喝了，就忘記他的貧窮，不再記得他的苦楚。","notes":[]},{"n":8,"t":"你當為不能自辯的人開口，為所有孤獨無助者伸冤。","notes":["「不能自辯的人」或譯「啞巴」。"]},{"n":9,"t":"你當開口按公義判斷，當為困苦和貧窮的人辯護。","notes":[]},{"n":10,"t":"才德的婦人誰能得著呢？她的價值遠勝過寶石。","notes":["由本節開始，原文是字母詩。"],"heads":["論賢妻"]},{"n":11,"t":"她丈夫心裏信賴她，必不缺少利益；","notes":[]},{"n":12,"t":"她終其一生，使丈夫有益無損。","notes":[]},{"n":13,"t":"她尋找羊毛和麻，歡喜用手做工。","notes":[]},{"n":14,"t":"她好像商船，從遠方運來糧食，","notes":[]},{"n":15,"t":"未到黎明她就起來，把食物分給家中的人，將當做的工分派女僕。","notes":[]},{"n":16,"t":"她想得田地，就去買來，用手中的成果栽葡萄園。","notes":[]},{"n":17,"t":"她以能力束腰，使膀臂有力。","notes":[]},{"n":18,"t":"她覺得自己獲利不錯，她的燈終夜不滅。","notes":[]},{"n":19,"t":"她伸手拿捲線桿，她的手掌把住紡車。","notes":[]},{"n":20,"t":"她張手賙濟困苦人，伸手幫助貧窮人。","notes":[]},{"n":21,"t":"她不因下雪為家裏的人擔心，因為全家都穿上朱紅衣服。","notes":[]},{"n":22,"t":"她為自己製作被單，她的衣服是細麻和紫色布做的。","notes":[]},{"n":23,"t":"她丈夫在城門口與本地的長老同坐，為人所認識。","notes":[]},{"n":24,"t":"她做細麻布衣裳來賣，又將腰帶賣給商家。","notes":[]},{"n":25,"t":"能力和威儀是她的衣服，她想到日後的景況就喜笑。","notes":[]},{"n":26,"t":"她開口就發智慧，她舌上有仁慈的教誨。","notes":[]},{"n":27,"t":"她管理家務，並不吃閒飯。","notes":[]},{"n":28,"t":"她的兒女起來稱她有福，她的丈夫也稱讚她：","notes":[]},{"n":29,"t":"「才德的女子很多，惟獨你超過一切。」","notes":[]},{"n":30,"t":"魅力是虛假的，美貌是虛浮的；惟敬畏耶和華的婦女必得稱讚。","notes":[]},{"n":31,"t":"她手中的成果你們要賞給她，願她的工作在城門口榮耀她。","notes":[]}]}},"ECC":{"1":{"heading":"人生的虛空","verses":[{"n":1,"t":"在耶路撒冷作王、大衛的兒子、傳道者的言語。","notes":[]},{"n":2,"t":"傳道者說：虛空的虛空，虛空的虛空，全是虛空。","notes":[]},{"n":3,"t":"人一切的勞碌，就是他在日光之下的勞碌，有甚麼益處呢？","notes":[]},{"n":4,"t":"一代過去，一代又來，地卻永遠長存。","notes":[]},{"n":5,"t":"太陽上升，太陽落下，急歸所出之地。","notes":[]},{"n":6,"t":"風往南颳，又向北轉，不停旋轉，繞回原路。","notes":[]},{"n":7,"t":"江河都往海裏流，海卻不滿；江河從何處流，仍歸回原處。","notes":[]},{"n":8,"t":"萬事令人厭倦，人不能說盡。眼看，看不飽；耳聽，聽不足。","notes":[]},{"n":9,"t":"已有的事，後必再有；已行的事，後必再行。日光之下並無新事。","notes":[]},{"n":10,"t":"有一件事人指著說：「看，這是新的！」它在我們以前的世代早已有了。","notes":[]},{"n":11,"t":"已過的事，無人記念；將來的事，後來的人也不記念。","notes":[]},{"n":12,"t":"我傳道者在耶路撒冷作過以色列的王。","notes":[],"heads":["傳道者的經驗"]},{"n":13,"t":"我用智慧專心探尋、考察天下所發生的一切事：神給世人何等沉重的擔子，使他們在其中勞苦！","notes":[]},{"n":14,"t":"我見日光之下所發生的一切事，看哪，全是虛空，全是捕風。","notes":[]},{"n":15,"t":"彎曲的，不能變直；缺乏的，不計其數。","notes":[]},{"n":16,"t":"我心裏說：「看哪，我大有智慧，勝過在我以前所有統治耶路撒冷的人；我的心也多經歷智慧和知識的事。」","notes":[]},{"n":17,"t":"我專心想要明白智慧，想要明白狂妄與愚昧，方知這也是捕風。","notes":[]},{"n":18,"t":"因為多有智慧，就多有愁煩；增加知識，就增加憂傷。","notes":[]}]},"2":{"heading":"","verses":[{"n":1,"t":"我心裏說：「來吧，讓我用喜樂試試你，使你享福！」看哪，這也是虛空。","notes":[]},{"n":2,"t":"論嬉笑，我說：「這是狂妄。」論享樂，「這有甚麼用呢？」","notes":[]},{"n":3,"t":"我心以智慧引導我，我心裏探究，如何用酒使身體舒暢，如何抓住愚昧，直等我看明世人在天下短暫一生中，當行何事為美。","notes":[]},{"n":4,"t":"我大興土木，為自己建造房屋，栽葡萄園，","notes":[]},{"n":5,"t":"修造庭園和公園，在其中栽種各樣果樹，","notes":[]},{"n":6,"t":"挖造水池，用以灌溉林中的幼樹。","notes":[]},{"n":7,"t":"我買了僕婢，也有生在家中的僕婢；又有許多牛群羊群，勝過我以前所有在耶路撒冷的人。","notes":[]},{"n":8,"t":"我為自己積蓄金銀，搜集各君王、各省份的財寶；又為自己得男女歌手和世人所喜愛的物，以及一個又一個的妃嬪。","notes":[]},{"n":9,"t":"這樣，我就日漸昌盛，勝過我以前所有在耶路撒冷的人。我的智慧仍然存留。","notes":[]},{"n":10,"t":"凡我眼所求的，我沒有克制它；我心所樂的，我沒有不享受。因我的心要為一切的勞碌快樂，這是我從一切勞碌中所得的報償。","notes":["「報償」或譯「福分」；3．22，5．18，9．9同。"]},{"n":11,"t":"後來，我回顧我手所經營的一切和我勞碌所做的工。看哪，全是虛空，全是捕風；在日光之下毫無益處。","notes":[]},{"n":12,"t":"我轉而回顧智慧、狂妄和愚昧。在王以後來的人又如何呢？不過做先前所做的就是了。","notes":[]},{"n":13,"t":"於是我看出智慧勝過愚昧，如同光明勝過黑暗。","notes":[]},{"n":14,"t":"智慧人的眼目光明，愚昧人卻在黑暗裏行。但我知道他們都有相同的遭遇。","notes":["「光明」：原文是「在他頭上」。"]},{"n":15,"t":"我心裏就說：「愚昧人所遇見的，我也一樣遇見，那麼我何必更有智慧呢？」我心裏說：「這也是虛空。」","notes":[]},{"n":16,"t":"智慧人和愚昧人一樣，不會長久被人記念，因為日後都被遺忘。可嘆！智慧人和愚昧人都一樣會死亡。","notes":[]},{"n":17,"t":"於是我恨惡生命，因為在日光之下所發生的事我都以為煩惱，全是虛空，全是捕風。","notes":[]},{"n":18,"t":"我恨惡一切的勞碌，就是我在日光之下所勞碌的，因為我所得的必須留給我以後的人。","notes":[]},{"n":19,"t":"那人是智慧是愚昧，誰能知道呢？他竟要掌管我在日光之下用智慧勞碌所得的。這也是虛空。","notes":[]},{"n":20,"t":"我轉想我在日光之下所勞碌的一切工作，心就絕望。","notes":[]},{"n":21,"t":"因為有人用智慧、知識、靈巧勞碌工作，所得來的卻要遺留給未曾勞碌的人作產業。這也是虛空，大大不幸。","notes":[]},{"n":22,"t":"人一切的勞碌操心，就是他在日光之下所勞碌的，又得著了甚麼呢？","notes":[]},{"n":23,"t":"他日日憂慮，他的勞苦成為愁煩，連夜間心也不得休息。這也是虛空。","notes":[]},{"n":24,"t":"難道一個人有吃有喝，且在勞碌中享福，不是福氣嗎？我看這也是出於神的手。","notes":[]},{"n":25,"t":"論到吃用、享福，誰能勝過我呢？","notes":[]},{"n":26,"t":"神喜愛誰，就給誰智慧、知識和喜樂；惟有罪人，神使他勞苦，將他所儲藏、所堆積的歸給神所喜愛的人。這也是虛空，也是捕風。","notes":[]}]},"3":{"heading":"萬事都有定時","verses":[{"n":1,"t":"凡事都有定期，天下每一事務都有定時。","notes":[]},{"n":2,"t":"生有時，死有時；栽種有時，拔出有時；","notes":["「拔出」：原文是「拔出所栽種的」。"]},{"n":3,"t":"殺戮有時，醫治有時；拆毀有時，建造有時；","notes":[]},{"n":4,"t":"哭有時，笑有時；哀慟有時，跳舞有時；","notes":[]},{"n":5,"t":"丟石頭有時，撿石頭有時；懷抱有時，不抱有時；","notes":[]},{"n":6,"t":"尋找有時，失落有時；保存有時，拋棄有時；","notes":[]},{"n":7,"t":"撕裂有時，縫補有時；沉默有時，說話有時；","notes":[]},{"n":8,"t":"喜愛有時，恨惡有時；戰爭有時，和平有時。","notes":[]},{"n":9,"t":"這樣，做事的人在他所勞碌的事上得到甚麼益處呢？","notes":[]},{"n":10,"t":"我觀看神給世人的擔子，使他們在其中勞苦：","notes":[]},{"n":11,"t":"神造萬物，各按其時成為美好，又將永恆安放在世人心裏；然而神從始至終的作為，人不能測透。","notes":[]},{"n":12,"t":"我知道，人除了終身喜樂納福，沒有一件幸福的事。","notes":[]},{"n":13,"t":"並且人人吃喝，在他的一切勞碌中享福，這也是神的賞賜。","notes":[]},{"n":14,"t":"我知道神所做的都必存到永遠；無所增添，無所減少。神這樣做，是要人在他面前存敬畏的心。","notes":[]},{"n":15,"t":"現今的事以前就有了，將來的事也早已有了，並且神使已過的事重新再來。","notes":["「使已過的事重新再來」：原文是「再尋回已過的事」。"]},{"n":16,"t":"我又見日光之下，應有公平之處有奸惡，應有公義之處也有奸惡。","notes":[],"heads":["世上的不公平"]},{"n":17,"t":"我心裏說：「神必審判義人和惡人，因為在那裏，各樣事務，一切工作，都有定時。」","notes":[]},{"n":18,"t":"我心裏說：「為世人的緣故，神考驗他們，讓他們看見自己不過像走獸一樣。」","notes":[]},{"n":19,"t":"因為世人遭遇的，走獸也遭遇，所遭遇的都一樣：這個怎樣死，那個也怎樣死，他們都有一樣的氣息。人不能強於走獸，全是虛空；","notes":[]},{"n":20,"t":"都歸一處，都是出於塵土，也都歸於塵土。","notes":[]},{"n":21,"t":"誰知道人的氣息是往上升，走獸的氣息是下入地呢？","notes":["本節或譯「誰知道人的靈是往上升，獸的魂是下入地呢？」"]},{"n":22,"t":"總而言之，人能夠在他經營的事上喜樂，是最好不過了，因為這是他應得的報償。他身後的事誰能領他回來看呢？","notes":[]}]},"4":{"heading":"","verses":[{"n":1,"t":"我轉而觀看日光之下所發生的一切欺壓之事。看哪，受欺壓的流淚，無人安慰；欺壓他們的有權勢，也無人安慰。","notes":[]},{"n":2,"t":"因此，我讚歎那已死的死人，勝過那還活著的活人。","notes":[]},{"n":3,"t":"但那尚未出生，就是未曾見過日光之下所發生之惡事的，比這兩種人更幸福。","notes":[]},{"n":4,"t":"我見人因彼此嫉妒而有一切的勞碌和各樣工作的成就，這也是虛空，也是捕風。","notes":[]},{"n":5,"t":"愚昧人抱著雙臂，自食其肉。","notes":[]},{"n":6,"t":"一掌滿滿而得享安靜，勝過兩掌滿滿而勞碌捕風。","notes":[]},{"n":7,"t":"我轉而觀看日光之下有一件虛空的事：","notes":[]},{"n":8,"t":"有人孤單無雙，無子無兄弟，竟勞碌不息，眼目也不以財富為滿足。他說：「我勞碌，自己卻不享福，到底是為了誰呢？」這也是虛空，是極沉重的擔子。","notes":[]},{"n":9,"t":"兩個人總比一個人好，他們勞碌同得美好的報償。","notes":[]},{"n":10,"t":"若是跌倒，這人可以扶起他的同伴；倘若孤身跌倒，沒有別人扶起他來，這人就有禍了。","notes":[]},{"n":11,"t":"再者，二人同睡就都暖和，一人獨睡怎能暖和呢？","notes":[]},{"n":12,"t":"若遇敵攻擊，孤身難擋，二人就能抵擋他；三股合成的繩子不易折斷。","notes":[]},{"n":13,"t":"貧窮而有智慧的年輕人，勝過年老不再納諫的愚昧王，","notes":[]},{"n":14,"t":"那人從監牢裏出來作王，在國中原是出身貧寒。","notes":[]},{"n":15,"t":"我見日光之下所有行走的活人，都跟隨那年輕人，就是接續作王的那位。","notes":[]},{"n":16,"t":"他的百姓，就是他所治理的眾人，多得無數；但後來的人還是不喜歡他。這也是虛空，也是捕風。","notes":[]}]},"5":{"heading":"不可隨便許願","verses":[{"n":1,"t":"你到神的殿要謹慎你的腳步；近前聽，勝過愚昧人獻祭，他們不知道自己在作惡。","notes":[]},{"n":2,"t":"在神面前你不可冒失開口，也不可心急發言；因為神在天上，你在地上，所以你的話語要少。","notes":[]},{"n":3,"t":"事務多，令人做夢；話語多，顯出愚昧。","notes":[]},{"n":4,"t":"你向神許願，還願不可遲延，因他不喜歡愚昧人，你許的願應當償還。","notes":[]},{"n":5,"t":"你許願不還，不如不許。","notes":[]},{"n":6,"t":"不可放任你的口使肉體犯罪，也不可在使者面前說是錯許了。為何使神因你的聲音發怒，敗壞你手所做的呢？","notes":["「使者」：七十士譯本是「神」。"]},{"n":7,"t":"多夢多言，其中多有虛空，你只要敬畏神。","notes":[]},{"n":8,"t":"你若在一個地區看見窮人受欺壓，公義公平被掠奪，不要因此驚奇；有一位高過居高位的在鑒察，在他們之上還有更高的。","notes":[],"heads":["人生是虛空的"]},{"n":9,"t":"況且地的益處歸眾人，就是君王也受田地的供應。","notes":["本節或譯「君王有耕種的田地，對全地是有益的。」"]},{"n":10,"t":"喜愛銀子的，不因得銀子滿足；喜愛財富的，也不因得利益知足。這也是虛空。","notes":[]},{"n":11,"t":"貨物增添，吃的人也增添，物主得甚麼益處呢？不過眼看而已！","notes":[]},{"n":12,"t":"勞碌的人不拘吃多吃少，睡得香甜；富人的豐足卻不容他睡覺。","notes":[]},{"n":13,"t":"我見日光之下有一件令人憂傷的禍患，就是財主積存財富，反害自己。","notes":[]},{"n":14,"t":"他因遭遇不幸，財產盡失；他生了兒子，手裏卻一無所有。","notes":["「遭遇不幸」或譯「經營不善」。"]},{"n":15,"t":"他怎樣從母胎赤身而來，也必照樣赤身而去；他所勞碌得來的，手中分毫不能帶去。","notes":[]},{"n":16,"t":"這是一件令人憂傷的禍患。他來的時候怎樣，去的時候也必怎樣。他為風勞碌有甚麼益處呢？","notes":[]},{"n":17,"t":"並且他終身在黑暗中吃喝，多有煩惱、病痛和怒氣。","notes":["「在黑暗中吃喝」：七十士譯本是「黑暗和悲傷」。"]},{"n":18,"t":"看哪，我所見為善為美的，就是人在神賜他一生的日子吃喝，享受日光之下勞碌得來的好處，因為這是他應得的報償。","notes":[]},{"n":19,"t":"而且，一個人蒙神賞賜財富與資產，又使他能享用，能獲取自己當有的報償，在他的勞碌中喜樂，這是神的賞賜。","notes":["「自己當有的報償」或譯「自己的福分」。"]},{"n":20,"t":"他不多思念自己一生的日子，因為神使他的心充滿喜樂。","notes":[]}]},"6":{"heading":"","verses":[{"n":1,"t":"我見日光之下有一件禍患重壓在人身上，","notes":[]},{"n":2,"t":"就是人蒙神賜他財富、資產和尊榮，以致他心裏所願的一樣都不缺，只是神使他不能享用，反被外人享用。這是虛空，也是禍患。","notes":[]},{"n":3,"t":"人若生一百個兒子，活許多歲數；他即使壽命很長，心裏卻不因福樂而滿足，又不得埋葬；我說，那流掉的胎比他倒好。","notes":[]},{"n":4,"t":"因為這胎虛虛而來，暗暗而去，名字被黑暗遮蔽，","notes":[]},{"n":5,"t":"而且沒有見過天日，甚麼都不知道，這胎比那人倒享安息。","notes":[]},{"n":6,"t":"那人雖然活千年，再活千年，卻不能享福；眾人豈不都歸同一個地方去嗎？","notes":[]},{"n":7,"t":"人的勞碌都為口腹，心裏卻不知足。","notes":[]},{"n":8,"t":"智慧人比愚昧人有甚麼益處呢？困苦人在眾人面前知道如何行，有甚麼益處呢？","notes":[]},{"n":9,"t":"眼睛所看的比心裏妄想的倒好。這也是虛空，也是捕風。","notes":[]},{"n":10,"t":"先前所有的，早已起了名，人早知道人是如何的，不能與比自己強壯的相爭。","notes":[]},{"n":11,"t":"話語多，虛空也增多，這對人有甚麼益處呢？","notes":[]},{"n":12,"t":"人一生虛度的日子，如影兒經過，誰知道甚麼才是對他有益呢？誰能告訴他身後在日光之下會發生甚麼事呢？","notes":[]}]},"7":{"heading":"智愚之別","verses":[{"n":1,"t":"名譽強如美好的膏油，人死去的日子勝過他出生的日子。","notes":[]},{"n":2,"t":"往喪家去，強如往宴樂的家，因為死是眾人的結局，活人必將這事放在心上。","notes":[]},{"n":3,"t":"憂愁強如喜笑，因為面帶愁容，終必使心喜樂。","notes":[]},{"n":4,"t":"智慧人的心在遭喪之家；愚昧人的心在快樂之家。","notes":[]},{"n":5,"t":"聽智慧人的責備，強如聽愚昧人歌唱；","notes":[]},{"n":6,"t":"因為愚昧人的笑聲，好像鍋子下面燒荊棘的爆聲，這也是虛空。","notes":[]},{"n":7,"t":"勒索使智慧人變為愚妄，賄賂能敗壞人的心。","notes":[]},{"n":8,"t":"事情的終局強如它的起頭；存心忍耐的，勝過居心驕傲的。","notes":[]},{"n":9,"t":"你的心不要急躁惱怒，因為惱怒存在愚昧人的懷中。","notes":[]},{"n":10,"t":"不要說：為甚麼先前的日子強過現今的日子呢？你這樣問不是出於智慧。","notes":[]},{"n":11,"t":"智慧加上產業是美好的，對見天日的人都有益處。","notes":[]},{"n":12,"t":"因為智慧庇護人，好像金錢庇護人一樣；智慧能保全智慧者的生命，這就是知識的益處。","notes":[]},{"n":13,"t":"你要觀看神的作為，誰能使他所彎曲的變直呢？","notes":[]},{"n":14,"t":"順利時要喜樂；患難時當思考。神使這兩樣都發生，因此，人不知將會發生甚麼事。","notes":[]},{"n":15,"t":"在虛度的日子裏，我見過各樣的事情，義人在他的義中滅亡，惡人在他的惡中倒享長壽。","notes":[]},{"n":16,"t":"不要行義過分，也不要過於自逞智慧，何必自取敗亡呢？","notes":[]},{"n":17,"t":"不要行惡過分，也不要為人愚昧，何必未到期而死呢？","notes":[]},{"n":18,"t":"你持守這個，那個也不要鬆手才好。敬畏神的人，這一切都能兼得。","notes":[]},{"n":19,"t":"智慧使擁有智慧的人比城中十個官長更有能力。","notes":[]},{"n":20,"t":"其實世上沒有行善而不犯罪的義人。","notes":[]},{"n":21,"t":"人所說的話，你不要都放在心上，免得聽見你的僕人詛咒你。","notes":[]},{"n":22,"t":"因為你心裏知道，自己也曾屢次詛咒別人。","notes":[]},{"n":23,"t":"我曾用智慧試驗這一切事，我說：「要得智慧。」智慧卻離我遠。","notes":[]},{"n":24,"t":"萬事之理遙不可及，太深奧，誰能測透呢？","notes":[]},{"n":25,"t":"我轉念，一心要知道，要考察，要尋求智慧和萬事的來由，要知道邪惡為愚昧，愚昧為狂妄。","notes":[]},{"n":26,"t":"我發現有一種婦人比死還苦毒：她本身是陷阱，她的心是羅網，手是鎖鏈。凡蒙神喜愛的人必能躲開她；有罪的人卻被她纏住了。","notes":[]},{"n":27,"t":"傳道者說：「你看，我考察一件又一件，為要尋求萬事的來由，這是我所尋得的：","notes":[]},{"n":28,"t":"我繼續尋找，卻未找到；一千當中，我找到一個男的，但在這一切當中，卻找不到一個女的。","notes":[]},{"n":29,"t":"你看，我所找到的只有一件，就是神造的人是正直的，但他們卻尋出許多詭計。」","notes":[]}]},"8":{"heading":"服從君王","verses":[{"n":1,"t":"誰如智慧人呢？誰知道事情的解釋呢？人的智慧使他的臉發光，改變他臉上暴戾之氣。","notes":["「如」：七十士譯本是「知道」。","「改變...暴戾之氣」：七十士譯本是「不知廉恥人的容貌為人所恨惡」。"]},{"n":2,"t":"我勸你因神誓言的緣故，當遵守王的命令。","notes":["七十士譯本沒有「我勸你」。"]},{"n":3,"t":"不要急躁離開王的面前，不要固執行惡，因為他凡事都隨自己心意而行。","notes":[]},{"n":4,"t":"王的話本有權力，誰能對他說：「你在做甚麼？」","notes":[]},{"n":5,"t":"凡遵守命令的，必不經歷禍患；智慧人的心知道適當的時機和必經的過程。","notes":[]},{"n":6,"t":"各樣事務都有時機和過程，但人有苦難重壓在身。","notes":[]},{"n":7,"t":"他不知道將來的事，其實將來如何，誰能告訴他呢？","notes":[]},{"n":8,"t":"沒有人能掌握生命，將生命留住；也沒有人有權力掌管死期。這場爭戰無人能免；邪惡也不能救那行邪惡的人。","notes":[]},{"n":9,"t":"這一切我都見過，我專心考察日光之下所發生的一切事，有時這人管轄那人，令他受害。","notes":[]},{"n":10,"t":"我見惡人被埋葬；從前他們進出聖地，他們在城中的作為被人忘記。這也是虛空。","notes":[],"heads":["惡人和義人"]},{"n":11,"t":"判罪之後不立刻執行，所以世人滿懷作惡的心思。","notes":[]},{"n":12,"t":"罪人雖然作惡百次，倒享長壽；然而我也知道，福樂必臨到敬畏神的人，就是在他面前心存敬畏的人。","notes":[]},{"n":13,"t":"惡人卻不得福樂，他的日子好像影兒不得長久，因為他不敬畏神。","notes":[]},{"n":14,"t":"世上有一件虛空的事，就是義人所遭遇的，反而照惡人所做的；惡人所遭遇的，反而照義人所做的。我說，這也是虛空。","notes":[]},{"n":15,"t":"我就稱讚快樂，原來人在日光之下，最大的福氣莫過於吃喝快樂；他在日光之下，神賜他一生的日子，要從勞碌中享受所得。","notes":[]},{"n":16,"t":"我專心想要明白智慧，要觀看世上所發生的事。有人晝夜不得闔眼睡覺。","notes":[]},{"n":17,"t":"我觀看神一切的作為，知道人不能探求日光之下所發生的事；任憑他費多少力探索，都找不出來，智慧人雖說他明白，仍不能找出來。","notes":[]}]},"9":{"heading":"智慧勝過武力","verses":[{"n":1,"t":"我將這一切事放在心上，詳細研究這些，就知道義人和智慧人，並他們的作為都在神手中；或是愛，或是恨，都在他們面前，但人不能知道。","notes":[]},{"n":2,"t":"凡臨到眾人的際遇都一樣：義人和惡人，好人，潔淨的人和不潔淨的人，獻祭的和不獻祭的，都一樣。好人如何，罪人也如何；起誓的如何，怕起誓的也如何。","notes":["「好人」：七十士譯本是「好人和壞人」。"]},{"n":3,"t":"在日光之下發生的一切事中有一件禍患，就是眾人的際遇都一樣，並且世人的心充滿了惡；活著的時候心裏狂妄，後來就歸死人那裏去了。","notes":[]},{"n":4,"t":"與一切活人相連的，那人還有指望，因為活著的狗勝過死了的獅子。","notes":[]},{"n":5,"t":"活著的人知道必死；死了的人毫無所知，也不再得賞賜，因為他們的名已被遺忘。","notes":["「名」：原文是「紀念」。"]},{"n":6,"t":"他們的愛，他們的恨，他們的嫉妒，早就消滅了。在日光之下所發生的一切事，他們永不再有份了。","notes":[]},{"n":7,"t":"你只管歡歡喜喜吃你的飯，心中快樂喝你的酒，因為神已經悅納你的作為。","notes":[]},{"n":8,"t":"你的衣服要時時潔白，你頭上也不要缺少膏油。","notes":[]},{"n":9,"t":"在你一生虛空的日子，就是神賜你在日光之下虛空的日子，當與你所愛的妻快活度日，因為那是你一生中在日光之下勞碌所得的報償。","notes":["七十士譯本沒有「虛空」。"]},{"n":10,"t":"凡你手所當做的事，要盡力去做；因為在你所必須去的陰間沒有工作，沒有謀算，沒有知識，也沒有智慧。","notes":[]},{"n":11,"t":"我轉而回顧日光之下，快跑的未必能贏，強壯的未必戰勝，智慧的未必得糧食，聰明的未必得財富，有學問的未必得人喜悅，全在乎各人遇上的時候和機會。","notes":[]},{"n":12,"t":"人不知道自己的定期。魚被險惡的網圈住，鳥被羅網捉住，禍患的時刻忽然臨到，世人陷在其中也是如此。","notes":[]},{"n":13,"t":"我見日光之下有一樣智慧，在我看來是偉大的，","notes":[]},{"n":14,"t":"就是有一人口稀少的小城，遇大君王前來攻擊，修築營壘，將城圍困。","notes":[]},{"n":15,"t":"城中有一個貧窮的智慧人，他用智慧救了那城，卻沒有人記念那窮人。","notes":[]},{"n":16,"t":"我就說，智慧勝過勇力；然而那貧窮人的智慧被人藐視，他的話也無人聽從。","notes":[]},{"n":17,"t":"寧可聽智慧人安靜的話語，不聽掌權者在愚昧人中的喊聲。","notes":[]},{"n":18,"t":"智慧勝過打仗的兵器；但一個罪人能敗壞許多善事。","notes":[]}]},"10":{"heading":"","verses":[{"n":1,"t":"死蒼蠅使做香的膏油散發臭氣；同樣，一點愚昧也能壓倒智慧和尊榮。","notes":[]},{"n":2,"t":"智慧人的心居右；愚昧人的心居左。","notes":[]},{"n":3,"t":"愚昧人的行徑顯出無知，對眾人說，他是愚昧人。","notes":[]},{"n":4,"t":"掌權者的怒氣若向你發作，不要離開你的本位，因為鎮定能平息大過。","notes":[]},{"n":5,"t":"我見日光之下有一件禍患，似乎出於統治者的錯誤，","notes":[]},{"n":6,"t":"就是愚昧人立在高位；有錢人卻坐在低位。","notes":[]},{"n":7,"t":"我見僕人騎馬，王子像僕人在地上步行。","notes":[]},{"n":8,"t":"挖陷坑的，自己必陷在其中；拆城牆的，自己必被蛇咬。","notes":[]},{"n":9,"t":"開鑿石頭的，會受損傷；劈開木頭的，必遭危險。","notes":[]},{"n":10,"t":"鐵器鈍了，若不將刃磨快，就必多費力氣；但智慧的益處在於使人成功。","notes":[]},{"n":11,"t":"尚未行法術，蛇若咬人，行法術的人就得不到甚麼好處了。","notes":[]},{"n":12,"t":"智慧人的口說出恩言；愚昧人的嘴吞滅自己，","notes":[]},{"n":13,"t":"他口中的話語起頭是愚昧，終局是邪惡的狂妄。","notes":[]},{"n":14,"t":"愚昧人多有話語。人不知將來會發生甚麼事，他身後的事誰能告訴他呢？","notes":[]},{"n":15,"t":"愚昧人的勞碌使自己困乏，連進城的路他也不知道。","notes":[]},{"n":16,"t":"邦國啊，你的君王若年少，你的群臣早晨宴樂，你就有禍了！","notes":[]},{"n":17,"t":"邦國啊，你的君王若是貴族之子，你的群臣按時吃喝，是為強身，不為酒醉，你就有福了！","notes":[]},{"n":18,"t":"因人懶惰，房頂塌下；因人手懶，房屋滴漏。","notes":[]},{"n":19,"t":"擺設宴席是為歡樂。酒能使人快活，錢能叫萬事應心。","notes":[]},{"n":20,"t":"不可詛咒君王，連起意也不可，在臥室裏也不可詛咒富人；因為空中的飛鳥必傳揚這聲音，有翅膀的必述說這事。","notes":[]}]},"11":{"heading":"智慧人的作為","verses":[{"n":1,"t":"當將你的糧食撒在水面上，因為日子久了，你必能得著它。","notes":[]},{"n":2,"t":"將你所擁有的分給七人，或八人，因為你不知道會有甚麼災禍臨到地上。","notes":[]},{"n":3,"t":"雲若滿了雨，就必傾倒在地上。樹向南倒，或向北倒，樹倒在何處，就留在何處。","notes":[]},{"n":4,"t":"看風的，必不撒種；望雲的，必不收割。","notes":[]},{"n":5,"t":"你不知道氣息如何進入孕婦的骨頭裏；照樣，造萬物之神的作為，你也無從得知。","notes":["「你不知道...骨頭裏」或譯「風從何道來，骨頭在孕婦的胎中如何長成，你尚且不得知道」。"]},{"n":6,"t":"早晨要撒種，晚上也不要歇手，因為你不知道哪一樣發旺；前者或後者，或兩者都一樣好。","notes":[]},{"n":7,"t":"光是甜美的，眼見日光是多麼好啊！","notes":[]},{"n":8,"t":"人活多少年，就當快樂多少年，然而也當想到黑暗的日子；因為這樣的日子必多，所要來臨的全是虛空。","notes":[]},{"n":9,"t":"年輕人哪，你在年少時當快樂；在年輕時使你的心歡暢，做你心所願做的，看你眼所愛看的；卻要知道，為這一切，神必審問你。","notes":[],"heads":["對年輕人的忠告"]},{"n":10,"t":"所以，當從心中除掉愁煩，從肉體除去痛苦；因為年少和年輕之時，全是虛空。","notes":[]}]},"12":{"heading":"結論","verses":[{"n":1,"t":"你趁著年輕、衰老的日子尚未來到，就是你所說，我毫無喜悅的那些歲月來臨之前，當記念造你的主。","notes":[]},{"n":2,"t":"不要等到太陽、光明、月亮、星宿變為黑暗，雨後雲又返回；","notes":[]},{"n":3,"t":"看守房屋的發顫，強壯的屈身，推磨的婦女因人少而停工，從窗戶往外看的眼光變為昏暗；","notes":[]},{"n":4,"t":"街門關閉，推磨的聲音微小，鳥一叫，就驚醒，唱歌女子的聲音也都微弱；","notes":[]},{"n":5,"t":"人怕高處，路上有驚慌；杏樹開花，蚱蜢成為重擔，慾望不再挑起；因為人歸他永遠的家，弔喪的在街上往來。","notes":[]},{"n":6,"t":"不要等到銀鏈折斷，金罐破裂，瓶子在泉旁損壞，水輪在井口斷裂，","notes":["「折斷」：原文另譯「取下」。"]},{"n":7,"t":"塵土仍歸於地，像原來一樣，氣息仍歸於賜氣息的神。","notes":[]},{"n":8,"t":"傳道者說：「虛空的虛空，全是虛空。」","notes":[]},{"n":9,"t":"再者，傳道者因有智慧，將知識教導眾人；他思量，考察，並列舉出許多箴言。","notes":[]},{"n":10,"t":"傳道者專心尋求可喜悅的言語，是憑正直寫的誠實話。","notes":[]},{"n":11,"t":"智慧人的話語如同刺棒；這些嘉言好像釘穩的釘子，都是一個牧者所賜的。","notes":[]},{"n":12,"t":"我兒，還有一點，你當受勸戒：著書多，沒有窮盡；讀書多，身體疲倦。","notes":[]},{"n":13,"t":"這些事都已聽見了，結論就是：敬畏神，謹守他的誡命，這是人當盡的本分。","notes":[]},{"n":14,"t":"因為人所做的事，連一切隱藏的事，無論是善是惡，神都必審問。","notes":[]}]}},"SNG":{"1":{"heading":"第一首","verses":[{"n":1,"t":"所羅門的雅歌。","notes":["「雅歌」：原文直譯「歌中之歌」。"]},{"n":2,"t":"願他用口與我親吻。你的愛情比酒更美，","notes":[]},{"n":3,"t":"你的膏油馨香，你的名如傾瀉而出的香膏，所以童女都愛你。","notes":[]},{"n":4,"t":"願你吸引我跟隨你；讓我們快跑吧！王領我進入他的內室。我們必因你歡喜快樂，我們要思念你的愛情，勝似思念美酒。她們愛你是理所當然的。","notes":[]},{"n":5,"t":"耶路撒冷的女子啊，我雖然黑，卻是秀美，如同基達的帳棚，好像所羅門的幔子，","notes":[]},{"n":6,"t":"不要因太陽把我曬黑了就瞪著我。我母親的兒子向我發怒，他們使我看守葡萄園；我自己的葡萄園我卻沒有看守。","notes":[]},{"n":7,"t":"我心所愛的啊，請告訴我，你在何處牧羊？正午在何處使羊歇臥？我何必像蒙著臉的女子在你同伴的羊群旁邊呢？","notes":[]},{"n":8,"t":"你這女子中最美麗的，你若不知道，只管跟隨羊群的腳蹤行，在牧人的帳棚邊，牧放你的小山羊。","notes":[]},{"n":9,"t":"我的佳偶，你好比法老戰車上的駿馬。","notes":[]},{"n":10,"t":"你的兩頰因髮辮而秀美，你的頸項因珠串而華麗。","notes":[]},{"n":11,"t":"我們要為你編上金鏈，鑲上銀飾。","notes":[]},{"n":12,"t":"王正坐席的時候，我的哪噠香膏散發香氣。","notes":[]},{"n":13,"t":"我的良人好像一袋沒藥，在我胸懷中。","notes":[]},{"n":14,"t":"我的良人好像一束鳳仙花，在隱‧基底的葡萄園中。","notes":[]},{"n":15,"t":"看哪，我的佳偶，你真美麗！看哪，你真美麗！你的眼睛是鴿子。","notes":[]},{"n":16,"t":"看哪，我的良人，你多英俊可愛！讓我們以青草為床榻，","notes":[]},{"n":17,"t":"以香柏樹為房子的棟梁，以松樹作屋頂的椽木。","notes":[]}]},"2":{"heading":"第二首","verses":[{"n":1,"t":"我是沙崙的玫瑰花，是谷中的百合花。","notes":[]},{"n":2,"t":"我的佳偶在女子中，好像荊棘裏的百合花。","notes":[]},{"n":3,"t":"我的良人在男子中，如同蘋果樹在樹林裏。我歡歡喜喜坐在他的蔭下，嘗他果子的滋味，覺得甘甜。","notes":[]},{"n":4,"t":"他領我進入宴會廳，為我插上愛的旗幟。","notes":[]},{"n":5,"t":"請你們用葡萄餅增補我力，以蘋果暢快我的心，因我為愛而生病。","notes":[]},{"n":6,"t":"他的左手在我頭下，他的右手將我環抱。","notes":[]},{"n":7,"t":"耶路撒冷的女子啊，我指著羚羊或田野的母鹿囑咐你們，不要喚醒，不要挑動愛情，等它自發。","notes":[]},{"n":8,"t":"聽啊！我良人的聲音，看哪！他穿山越嶺而來。","notes":[]},{"n":9,"t":"我的良人像羚羊，像小鹿。看哪，他站在我們的牆壁邊，從窗戶往裏觀看，從窗格子往裏窺探。","notes":[]},{"n":10,"t":"我的良人對我說：「我的佳偶，起來！我的美人，與我同去！","notes":[]},{"n":11,"t":"看哪，因為冬天已逝，雨水止住，已經過去了。","notes":[]},{"n":12,"t":"地上百花開放，歌唱的時候到了，斑鳩的聲音在我們境內也聽見了。","notes":[]},{"n":13,"t":"無花果樹的果子漸漸成熟，葡萄樹開花，散發香氣。我的佳偶，起來！我的美人，與我同去！","notes":[]},{"n":14,"t":"我的鴿子啊，你在磐石穴中，在陡巖的隱密處。求你容我得見你的面貌，求你容我得聽你的聲音；因你的聲音悅耳，你的容貌秀美。","notes":[]},{"n":15,"t":"請為我們擒拿狐狸，就是毀壞葡萄園的小狐狸，我們的葡萄正在開花。」","notes":[]},{"n":16,"t":"我的良人屬我，我也屬他，他在百合花中放牧。","notes":[]},{"n":17,"t":"我的良人哪，等到天起涼風、日影飛去的時候，願你歸回，像羚羊，像小鹿，在崎嶇的山上。","notes":["「崎嶇的山」或音譯「比特山」。"]}]},"3":{"heading":"第三首","verses":[{"n":1,"t":"我夜間躺臥在床上，尋找我心所愛的；我尋找他，卻尋不著。","notes":[]},{"n":2,"t":"「我要起來，繞行城中，在街市上，在廣場上，尋找我心所愛的。」我尋找他，卻尋不著。","notes":[]},{"n":3,"t":"城中巡邏的守衛遇見我，「你們看見我心所愛的沒有？」","notes":[]},{"n":4,"t":"我剛離開他們，就遇見我心所愛的。我拉住他，不放他走，領他進入我母親的家，到懷我者的內室。","notes":[]},{"n":5,"t":"耶路撒冷的女子啊，我指著羚羊或田野的母鹿囑咐你們，不要喚醒，不要挑動愛情，等它自發。","notes":[]},{"n":6,"t":"那如煙柱從曠野上來，薰了沒藥、乳香，撲上商人各樣香粉的是誰呢？","notes":[]},{"n":7,"t":"看哪，是所羅門的轎，周圍有六十個勇士，都是以色列中的勇士。","notes":[]},{"n":8,"t":"他們的手都持刀，善於爭戰，各人腰間佩刀，防備夜間恐怖的攻擊。","notes":[]},{"n":9,"t":"所羅門王用黎巴嫩木為自己製作轎子。","notes":[]},{"n":10,"t":"轎柱是用銀做的，轎底是用金做的，坐墊是紫色的，其中所鋪的是耶路撒冷女子的愛情。","notes":[]},{"n":11,"t":"錫安的女子啊，你們要出去觀看所羅門王！他頭戴冠冕，就是在他結婚當天心中喜樂的時候，他母親給他戴上的。","notes":[]}]},"4":{"heading":"","verses":[{"n":1,"t":"看哪，我的佳偶，你真美麗！看哪，你真美麗！你的眼睛在面紗後好像鴿子。你的頭髮如同一群山羊，從基列山下來。","notes":[]},{"n":2,"t":"你的牙齒如新剪毛的一群母羊，洗淨之後走上來，它們成對，沒有一顆是單獨的。","notes":[]},{"n":3,"t":"你的唇好像一條朱紅線，你的嘴秀美。你的鬢角在面紗後，如同迸開的石榴。","notes":[]},{"n":4,"t":"你的頸項猶如大衛為收藏軍器而造的高塔，其上懸掛一千個盾牌，都是勇士的盾牌。","notes":[]},{"n":5,"t":"你的兩乳好像百合花中吃草的一對小鹿，是母鹿雙生的。","notes":[]},{"n":6,"t":"我要往沒藥山和乳香岡去，直到天起涼風、日影飛去的時候。","notes":[]},{"n":7,"t":"我的佳偶，你全然美麗，毫無瑕疵！","notes":[]},{"n":8,"t":"我的新娘，請你與我一同離開黎巴嫩，與我一同離開黎巴嫩。從亞瑪拿山巔，從示尼珥，就是黑門山頂，從獅子的洞，從豹子的山往下觀看。","notes":["「請你與我…與我一同離開黎巴嫩」：七十士譯本是「從黎巴嫩下來，從黎巴嫩下來」。"]},{"n":9,"t":"我的妹子，我的新娘，你奪了我的心。你明眸一瞥，你頸項的鏈子，奪了我的心！","notes":[]},{"n":10,"t":"我的妹子，我的新娘，你的愛情何其美！你的愛情比酒甜美！你膏油的馨香勝過一切香料！","notes":["「愛情」：七十士譯本是「胸懷」；下同。"]},{"n":11,"t":"我的新娘，你的唇滴下蜂蜜，你的舌下有蜜，有奶。你衣服的香氣宛如黎巴嫩的芬芳。","notes":[]},{"n":12,"t":"我的妹子，我的新娘是上鎖的園子，是禁閉的園子，是封閉的泉源。","notes":["「園子」是根據一些古卷和七十士譯本；原文是「井」。"]},{"n":13,"t":"你園內所種的結了石榴，有佳美的果子，並鳳仙花與哪噠樹。","notes":[]},{"n":14,"t":"有哪噠和番紅花，香菖蒲和桂樹，並各樣乳香木、沒藥、沉香，與一切上等的香料。","notes":[]},{"n":15,"t":"你是園中的泉，活水的井，是從黎巴嫩湧流而下的溪水。","notes":[]},{"n":16,"t":"北風啊，興起！南風啊，吹來！吹在我的園內，使其中的香氣散發出來。願我的良人進入自己園裏，吃他佳美的果子。","notes":[]}]},"5":{"heading":"第四首","verses":[{"n":1,"t":"我的妹子，我的新娘，我進入我的園中，採了我的沒藥和香料，吃了我的蜂房和蜂蜜，喝了我的酒和奶。我的朋友，請吃！我親愛的，請喝，多多地喝！","notes":[]},{"n":2,"t":"我身躺臥，我心卻醒。這是我良人的聲音；他敲門：「我的妹子，我的佳偶，我的鴿子，我完美的人兒，請你為我開門；因我的頭沾滿露水，我的髮被夜露滴濕。」","notes":[]},{"n":3,"t":"我脫了衣裳，怎能再穿上呢？我洗了腳，怎可再弄髒呢？","notes":[]},{"n":4,"t":"我的良人從門縫裏伸進他的手，我便因他動了心。","notes":[]},{"n":5,"t":"我起來，要為我的良人開門。我的兩手滴下沒藥，我的指頭有沒藥汁滴在門閂上。","notes":[]},{"n":6,"t":"我為我的良人開了門，我的良人卻已轉身走了。他說話的時候，我魂不守舍。我尋找他，竟尋不著，我呼叫他，他卻不回答。","notes":[]},{"n":7,"t":"城中巡邏的守衛遇見我，打了我，傷了我，看守城牆的人奪去我的披肩。","notes":[]},{"n":8,"t":"耶路撒冷的女子啊，我囑咐你們：若遇見我的良人，要告訴他，我為愛而生病。","notes":[]},{"n":9,"t":"你這女子中最美麗的，你的良人有甚麼勝過別的良人呢？你的良人有甚麼勝過別的良人，使你這樣囑咐我們？","notes":[]},{"n":10,"t":"我的良人紅潤發亮，超乎萬人之上。","notes":[]},{"n":11,"t":"他的頭像千足的純金，他的髮綹卷曲，黑如烏鴉。","notes":[]},{"n":12,"t":"他的眼如溪水旁的鴿子，沐浴在奶中，安得合式。","notes":["「安得合式」或譯「坐在溪水邊」。"]},{"n":13,"t":"他的兩頰如香花園，如香草臺；他的嘴唇像百合花，滴下沒藥汁。","notes":["「如香草臺」：七十士譯本是「散發香味」。"]},{"n":14,"t":"他的雙手宛如金條，鑲嵌水蒼玉；他的身體如同雕刻的象牙，周圍鑲嵌藍寶石。","notes":[]},{"n":15,"t":"他的腿好比白玉石柱，安在精金座上；他的容貌如黎巴嫩，佳美如香柏樹。","notes":[]},{"n":16,"t":"他的口甘甜，他全然可愛。耶路撒冷的女子啊，這是我的良人，這是我的朋友。","notes":[]}]},"6":{"heading":"第五首","verses":[{"n":1,"t":"你這女子中最美麗的，你的良人往何處去？你的良人轉向何處去了？我們好與你同去尋找他。","notes":[]},{"n":2,"t":"我的良人進入自己園中，到香花園，在園內放牧，採百合花。","notes":[]},{"n":3,"t":"我屬我的良人，我的良人屬我；他在百合花中放牧。","notes":[]},{"n":4,"t":"我的佳偶啊，你美麗如得撒，秀美如耶路撒冷，威武如展開旌旗的軍隊。","notes":[]},{"n":5,"t":"求你轉眼不要看我，因你的眼睛使我慌亂。你的頭髮如同一群山羊，從基列山下來。","notes":[]},{"n":6,"t":"你的牙齒如一群母羊，洗淨之後走上來，它們成對，沒有一顆是單獨的。","notes":[]},{"n":7,"t":"你的鬢角在面紗後，如同迸開的石榴。","notes":[]},{"n":8,"t":"雖有六十王后、八十妃嬪，並有無數的童女。","notes":[]},{"n":9,"t":"她是我獨一的鴿子、我完美的人兒，是她母親獨生的，是生養她的所寵愛的。女子見了都稱她有福，王后妃嬪見了也讚美她。","notes":[]},{"n":10,"t":"那俯視如晨曦、美麗如月亮、皎潔如太陽、威武如展開旌旗軍隊的是誰呢？","notes":[]},{"n":11,"t":"我下到堅果園，要看谷中青翠的植物，要看葡萄可曾發芽，石榴可曾放蕊；","notes":[]},{"n":12,"t":"不知不覺，我彷彿坐在我百姓高官的戰車中。","notes":["「我百姓高官」或音譯「亞米‧拿達」。"]},{"n":13,"t":"回來，回來，書拉密的女子；回來，回來，我們要看你。你們為何要觀看書拉密的女子，像觀看兩隊人馬在跳舞呢？","notes":["「兩隊人馬在跳舞」或譯「瑪哈念跳舞的」。"]}]},"7":{"heading":"","verses":[{"n":1,"t":"尊貴的女子啊，你的腳在鞋中何等秀美！你的大腿圓潤，好像美玉，是巧匠的手做成的。","notes":[]},{"n":2,"t":"你的肚臍如圓杯，不缺調和的酒。你的肚子如一堆麥子，周圍有百合花。","notes":[]},{"n":3,"t":"你的兩乳好像一對小鹿，是母鹿雙生的。","notes":[]},{"n":4,"t":"你的頸項如象牙塔，你的眼睛像希實本、巴特‧拉併門旁的水池，你的鼻子彷彿朝向大馬士革的黎巴嫩塔。","notes":[]},{"n":5,"t":"你的頭在你身上好像迦密山 ，你頭上的髮呈紫色，王被這髮綹繫住了。","notes":[]},{"n":6,"t":"我親愛的，喜樂的女子啊，你何等美麗！何等令人喜悅！","notes":["「喜樂的女子啊」是根據一些古譯本；原文是「在喜樂中」。"]},{"n":7,"t":"你的身材好像棕樹，你的兩乳如同纍纍的果實。","notes":[]},{"n":8,"t":"我說：我要爬上棕樹，抓住枝子。願你的兩乳好像葡萄纍纍，願你鼻子的香氣如蘋果；","notes":[]},{"n":9,"t":"你的上顎如美酒，直流入我良人的口裏，流入沉睡者的口中。","notes":["「流入沉睡者的口中」：七十士譯本是「流在我的唇齒之間」。"]},{"n":10,"t":"我屬我的良人，他也戀慕我。","notes":[]},{"n":11,"t":"來吧！我的良人，讓我們往田間去，在村莊住宿。","notes":[]},{"n":12,"t":"早晨讓我們起來往葡萄園去，看葡萄樹發芽沒有，花開了沒有，石榴放蕊沒有，在那裏我要將我的愛情給你。","notes":[]},{"n":13,"t":"曼陀羅草散發香味，在我們的門內有各樣新陳佳美的果子；我的良人，這都是我為你保存的。","notes":["「曼陀羅草」或譯「愛情花」。"]}]},"8":{"heading":"第六首","verses":[{"n":1,"t":"惟願你像我的兄弟，像吃我母親奶的兄弟。我在外頭遇見你就與你親吻，誰也不輕看我。","notes":[]},{"n":2,"t":"我必引導你，領你進入我母親的家，她必教導我，我必使你喝石榴汁釀的香酒。","notes":[]},{"n":3,"t":"他的左手在我頭下，他的右手將我環抱。","notes":[]},{"n":4,"t":"耶路撒冷的女子啊，我囑咐你們，不要喚醒、不要挑動愛情，等它自發。","notes":[]},{"n":5,"t":"那靠著良人從曠野上來的是誰呢？在蘋果樹下，我叫醒了你；在那裏，你母親曾為了生你而陣痛，在那裏，生你的為你陣痛。","notes":[]},{"n":6,"t":"求你將我放在你心上如印記，帶在你臂上如戳記。因為愛情如死之堅強，熱戀如陰間之牢固，所發的光是火焰的光，是極其猛烈的火焰。","notes":["「極其猛烈的火焰」或譯「耶和華的烈焰」。"]},{"n":7,"t":"愛情，眾水不能熄滅，江河也不能淹沒。若有人拿家中所有的財寶要換愛情，就全被藐視。","notes":[]},{"n":8,"t":"我們有一小妹，她還沒有乳房，人來提親的日子，我們當為她怎麼辦呢？","notes":[]},{"n":9,"t":"她若是牆，我們要在其上建造銀塔；她若是門，我們要用香柏木板圍護她。","notes":[]},{"n":10,"t":"我是牆，我的兩乳像塔。那時，我在他眼中是找到平安的人。","notes":[]},{"n":11,"t":"所羅門在巴力‧哈們有一葡萄園，他將這葡萄園租給看守的人，每人為其中的果子要交一千銀子。","notes":[]},{"n":12,"t":"我有屬自己的葡萄園。所羅門哪，一千歸你，兩百歸看守果子的人。","notes":[]},{"n":13,"t":"你這住在園中的，同伴都要聽你的聲音，求你使我也得以聽見。","notes":[]},{"n":14,"t":"我的良人哪，求你快來！像羚羊，像小鹿，在香草山上。","notes":[]}]}},"ISA":{"1":{"heading":"神責備以色列","verses":[{"n":1,"t":"當烏西雅、約坦、亞哈斯、希西家作猶大王的時候，亞摩斯的兒子以賽亞見異象，論到猶大和耶路撒冷。","notes":[]},{"n":2,"t":"天哪，要聽！地啊，側耳而聽！因為耶和華說：「我養育兒女，將他們養大，他們竟悖逆我。","notes":[]},{"n":3,"t":"牛認識主人，驢認識主人的槽；以色列卻不認識，我的民卻不明白。」","notes":[]},{"n":4,"t":"禍哉！犯罪的國民，擔著罪孽的百姓，行惡的族類，敗壞的兒女！他們離棄耶和華，藐視以色列的聖者，背向他，與他疏遠。","notes":[]},{"n":5,"t":"你們為甚麼屢次悖逆，繼續受責打呢？你們已經滿頭疼痛，全心發昏；","notes":[]},{"n":6,"t":"從腳掌到頭頂，沒有一處是完好的，盡是創傷、瘀青，與流血的傷口，未曾擠淨，未曾包紮，也沒有用膏滋潤。","notes":[]},{"n":7,"t":"你們的土地荒蕪，城鎮被火燒燬；你們的田地在你們眼前被陌生人侵吞，既被陌生人傾覆，就成為荒蕪。","notes":["「既被...荒蕪」或譯「成為荒蕪，如同陌生人曾被傾覆一樣」。"]},{"n":8,"t":"僅存的錫安，好似葡萄園的草棚，如瓜田中的茅屋，又如被圍困的城。","notes":["「錫安」：原文直譯「錫安女子」。"]},{"n":9,"t":"若不是萬軍之耶和華為我們留下一些倖存者，我們早已變成所多瑪，像蛾摩拉一樣了。","notes":[]},{"n":10,"t":"所多瑪的官長啊，你們要聽耶和華的言語！蛾摩拉的百姓啊，要側耳聽我們神的教誨！","notes":[]},{"n":11,"t":"耶和華說：「你們許多的祭物於我何益呢？公綿羊的燔祭和肥畜的油脂，我已經膩煩了；公牛、羔羊、公山羊的血，我都不喜悅。","notes":[]},{"n":12,"t":"「你們來朝見我，誰向你們的手要求這些，使你們踐踏我的院宇呢？","notes":[]},{"n":13,"t":"不要再獻無謂的供物了，香是我所憎惡的。我不能容忍行惡又守嚴肅會：初一、安息日和召集的大會。","notes":[]},{"n":14,"t":"你們的初一和節期，我心裏恨惡，它們成了我的重擔，擔當這些，令我厭煩。","notes":[]},{"n":15,"t":"你們舉手禱告，我必遮眼不看，就算你們多多祈禱，我也不聽；你們的手沾滿了血。","notes":[]},{"n":16,"t":"你們要洗滌、自潔，從我眼前除掉惡行；要停止作惡，","notes":[]},{"n":17,"t":"學習行善，尋求公平，幫助受欺壓的，替孤兒伸冤，為寡婦辯護。」","notes":["「幫助受欺壓的」或譯「導正欺壓者」。"]},{"n":18,"t":"耶和華說：「來吧，我們彼此辯論。你們的罪雖像硃紅，必變成雪白；雖紅如丹顏，必白如羊毛。","notes":[]},{"n":19,"t":"你們若甘心聽從，必吃地上的美物；","notes":[]},{"n":20,"t":"若不聽從，反倒悖逆，必被刀劍吞滅；這是耶和華親口說的。」","notes":[]},{"n":21,"t":"忠信的城竟然變為妓女！從前充滿了公平，公義居在其中，現今卻有兇手居住。","notes":[],"heads":["罪大惡極的城"]},{"n":22,"t":"你的銀子變為渣滓，你的酒用水沖淡。","notes":[]},{"n":23,"t":"你的官長悖逆，與盜賊為伍，全都喜愛賄賂，追求贓物；他們不為孤兒伸冤，寡婦的案件也呈不到他們面前。","notes":[]},{"n":24,"t":"因此，主－萬軍之耶和華、以色列的大能者說：「唉！我要向我的對頭雪恨，向我的敵人報仇。","notes":[]},{"n":25,"t":"我必反手對付你，如鹼煉淨你的渣滓，除盡你的雜質。","notes":[]},{"n":26,"t":"我必回復你的審判官，像起初一樣，回復你的謀士，如起先一般。然後，你必稱為公義之城，忠信之邑。」","notes":[]},{"n":27,"t":"錫安必因公平得蒙救贖，其中歸正的人必因公義得蒙救贖。","notes":[]},{"n":28,"t":"但悖逆的和犯罪的必一同敗亡，離棄耶和華的必致消滅。","notes":[]},{"n":29,"t":"那等人必因所喜愛的聖樹抱愧；你們必因所選擇的園子蒙羞，","notes":["「園子」是拜聖樹的地方。"]},{"n":30,"t":"因為你們必如葉子枯乾的橡樹，如無水的園子。","notes":[]},{"n":31,"t":"有權勢的必如麻線，他的作為好像火花，都要一同焚燒，無人撲滅。","notes":[]}]},"2":{"heading":"永恆的和平","verses":[{"n":1,"t":"亞摩斯的兒子以賽亞所見，有關猶大和耶路撒冷的事。","notes":[]},{"n":2,"t":"末後的日子，耶和華殿的山必堅立，超乎諸山，高舉過於萬嶺；萬國都要流歸這山。","notes":[]},{"n":3,"t":"必有許多民族前往，說：「來吧，我們登耶和華的山，到雅各神的殿。他必將他的道教導我們，我們也要行他的路。」因為教誨必出於錫安，耶和華的言語必出於耶路撒冷。","notes":[]},{"n":4,"t":"他必在萬國中施行審判，為許多民族斷定是非。他們要將刀打成犁頭，把槍打成鐮刀；這國不舉刀攻擊那國，他們也不再學習戰事。","notes":[]},{"n":5,"t":"雅各家啊，來吧！讓我們在耶和華的光明中行走。","notes":[]},{"n":6,"t":"你離棄了你的百姓雅各家，因為他們充滿了東方的習俗，又像非利士人一樣觀星象，並與外邦人擊掌。","notes":["原文沒有「習俗」。"],"heads":["驕者必敗"]},{"n":7,"t":"他們的國滿了金銀，財寶也無窮；他們的地滿了馬匹，戰車也無數。","notes":[]},{"n":8,"t":"他們的地滿了偶像；他們跪拜自己手所造的，就是自己手指所做的。","notes":[]},{"n":9,"t":"有人屈膝，有人下跪；所以，不要饒恕他們。","notes":[]},{"n":10,"t":"當進入磐石，藏在土中，躲避耶和華的驚嚇和他威嚴的榮光。","notes":[]},{"n":11,"t":"到那日，眼目高傲的必降卑，狂妄的人必屈膝；惟獨耶和華被尊崇。","notes":[]},{"n":12,"t":"因萬軍之耶和華的一個日子要臨到所有驕傲狂妄的，臨到一切自高的，使他們降為卑；","notes":[]},{"n":13,"t":"臨到黎巴嫩高大的香柏樹、巴珊的橡樹，","notes":[]},{"n":14,"t":"臨到一切高山、一切峻嶺，","notes":[]},{"n":15,"t":"臨到一切碉堡、一切堅固的城牆，","notes":[]},{"n":16,"t":"臨到他施一切的船隻、一切華麗的船艇。","notes":[]},{"n":17,"t":"人的驕傲必屈膝，人的狂妄必降卑；在那日，惟獨耶和華被尊崇，","notes":[]},{"n":18,"t":"偶像必全然廢棄。","notes":[]},{"n":19,"t":"耶和華興起使地大震動的時候，人就進入石洞和土穴裏，躲避耶和華的驚嚇和他威嚴的榮光。","notes":[]},{"n":20,"t":"到那日，人必將造來敬拜的金偶像、銀偶像拋給田鼠和蝙蝠。","notes":[]},{"n":21,"t":"耶和華興起使地大震動的時候，人就進入磐縫和巖隙裏，躲避耶和華的驚嚇和他威嚴的榮光。","notes":[]},{"n":22,"t":"你們不要倚靠世人，他只不過鼻孔裏有氣息，算得了甚麼呢？","notes":[]}]},"3":{"heading":"耶路撒冷的混亂","verses":[{"n":1,"t":"看哪，主－萬軍之耶和華要從耶路撒冷和猶大除掉眾人所倚靠的，所仰賴的，就是所倚靠的糧，所仰賴的水；","notes":[]},{"n":2,"t":"除掉勇士和戰士，審判官和先知，占卜的和長老，","notes":[]},{"n":3,"t":"除掉五十夫長和顯要、謀士和巧匠，以及擅長法術的人。","notes":[]},{"n":4,"t":"我必使孩童作他們的領袖，幼兒管轄他們。","notes":[]},{"n":5,"t":"百姓要彼此欺壓，各人欺壓鄰舍；青年要侮慢老人，卑賤的要侮慢尊貴的。","notes":[]},{"n":6,"t":"人在父家拉住自己的兄弟：「你有外衣，來作我們的官長，讓這些敗壞的事歸於你的手下吧！」","notes":[]},{"n":7,"t":"那時，他必揚聲說：「我不作醫治你們的人；我家裏沒有糧食，也沒有衣服，你們不可立我作百姓的官長。」","notes":[]},{"n":8,"t":"耶路撒冷敗落，猶大傾倒；因為他們的舌頭和行為與耶和華相悖，無視於他榮光的眼目。","notes":[]},{"n":9,"t":"他們的臉色證明自己不正，他們述說自己像所多瑪一樣的罪惡，毫不隱瞞。他們有禍了！因為作惡自害。","notes":[]},{"n":10,"t":"你們要對義人說，他是有福的，因為他必吃自己行為所結的果實。","notes":[]},{"n":11,"t":"惡人有禍了！他必遭災難！因為他要按自己手所做的受報應。","notes":[]},{"n":12,"t":"至於我的百姓，統治者剝削你們，放高利貸的人管轄你們。我的百姓啊，引導你的使你走錯，並毀壞你所行的道路。","notes":["「統治者...管轄你們」是根據七十士譯本；原文是「孩童欺壓他們，婦女管轄他們」。"]},{"n":13,"t":"耶和華興起訴訟，站著審判萬民。","notes":[],"heads":["耶和華審判他的子民"]},{"n":14,"t":"耶和華必審問他國中的長老和領袖：「你們，你們摧毀葡萄園，搶奪困苦人，囤積在你們家中。","notes":[]},{"n":15,"t":"你們為何壓碎我的百姓，碾磨困苦人的臉呢？」這是萬軍之主耶和華說的。","notes":[]},{"n":16,"t":"耶和華說：因為錫安狂傲，行走挺項，賣弄眼目，俏步徐行，腳下玎璫，","notes":["「錫安」：原文直譯「錫安女子」；17節同。"],"heads":["對耶路撒冷的警告"]},{"n":17,"t":"主必使錫安頭頂長瘡，耶和華又暴露其下體。","notes":[]},{"n":18,"t":"到那日，主必除掉華美的足飾、額帶、月牙圈、","notes":[]},{"n":19,"t":"耳環、手鐲、面紗、","notes":[]},{"n":20,"t":"頭巾、足鏈、華帶、香盒、符囊、","notes":[]},{"n":21,"t":"戒指、鼻環、","notes":[]},{"n":22,"t":"禮服、外套、披肩、皮包、","notes":[]},{"n":23,"t":"手鏡、細麻衣、頭飾、紗巾。","notes":[]},{"n":24,"t":"必有腐爛代替馨香，繩子代替腰帶，光禿代替美髮，麻衣繫腰代替華服，烙痕代替美貌。","notes":[]},{"n":25,"t":"你的男丁必倒在刀下，你的勇士必死在陣上。","notes":[]},{"n":26,"t":"錫安的城門必悲傷、哀號；它必荒涼，坐在地上。","notes":[]}]},"4":{"heading":"耶路撒冷的重建","verses":[{"n":1,"t":"在那日，七個女人必拉住一個男人，說：「我們吃自己的食物，穿自己的衣服，但求你允許我們歸你名下，除掉我們的羞恥。」","notes":[]},{"n":2,"t":"在那日，耶和華的苗必華美尊榮，地的出產必成為倖存的以色列民的驕傲和光榮。","notes":[]},{"n":3,"t":"主以公平的靈和焚燒的靈洗淨錫安居民的污穢，又除淨在耶路撒冷流人血的罪。那時，剩在錫安、留在耶路撒冷的，就是一切住耶路撒冷、在生命冊上記名的，必稱為聖。","notes":["「錫安居民」：原文是「錫安眾女子」。"],"end":4},{"n":5,"t":"耶和華必在整座錫安山，在會眾之上，白天造雲，黑夜發出煙和火焰的光，因為在一切榮耀之上必有華蓋；","notes":[]},{"n":6,"t":"這要作為棚子，白天可以遮蔭避暑，暴風雨侵襲時，可作藏身處和避難所。","notes":[]}]},"5":{"heading":"葡萄園之歌","verses":[{"n":1,"t":"我要為我親愛的唱歌，我所愛的、他的葡萄園之歌。我親愛的有葡萄園在肥沃的山岡上。","notes":[]},{"n":2,"t":"他刨挖園子，清除石頭，栽種上等的葡萄樹，在園中蓋了一座樓，又鑿出酒池；指望它結葡萄，反倒結了野葡萄。","notes":[]},{"n":3,"t":"耶路撒冷的居民和猶大人哪，現在，請你們在我與我的葡萄園之間斷定是非。","notes":[]},{"n":4,"t":"我為我葡萄園所做的之外，還有甚麼可做的呢？我指望它結葡萄，怎麼倒結了野葡萄呢？","notes":[]},{"n":5,"t":"現在我告訴你們，我要向我的葡萄園怎麼做。我必撤去籬笆，使它被燒燬；拆毀圍牆，使它被踐踏。","notes":[]},{"n":6,"t":"我必使它荒廢，不再修剪，不再鋤草，任荊棘蒺藜生長；我也必吩咐密雲，不再降雨在其上。","notes":[]},{"n":7,"t":"萬軍之耶和華的葡萄園就是以色列家；他所喜愛的樹就是猶大人。他指望公平，看哪，卻有流血；指望公義，看哪，卻有冤聲。","notes":[]},{"n":8,"t":"禍哉！你們以房接房，以地連地，以致不留餘地，只顧自己獨居境內。","notes":[],"heads":["人的惡行"]},{"n":9,"t":"我耳聞萬軍之耶和華說：「許多房屋必然荒廢；宏偉華麗，無人居住。","notes":[]},{"n":10,"t":"十畝的葡萄園只釀出一罷特的酒，一賀梅珥的穀種只結一伊法糧食。」","notes":["「畝」﹕古希伯來面積單位；參「度量衡表」。"]},{"n":11,"t":"禍哉！那些清晨早起，追尋烈酒，因酒狂熱，流連到深夜的人，","notes":[]},{"n":12,"t":"他們在宴席上彈琴，鼓瑟，擊鼓，吹笛，飲酒，卻不留意耶和華的作為，也不留心他手所做的。","notes":[]},{"n":13,"t":"所以，我的百姓因無知就被擄去；尊貴的人甚是飢餓，平民也極其乾渴。","notes":[]},{"n":14,"t":"因此，陰間胃口大開，張開無限量的口；令耶路撒冷的貴族與平民、狂歡的與作樂的人都掉落其中。","notes":["「胃口」或譯「喉嚨」。"]},{"n":15,"t":"人為之屈膝，人就降為卑；高傲的眼目也降為卑。","notes":[]},{"n":16,"t":"惟有萬軍之耶和華因公平顯為崇高，神聖的神因公義顯為聖。","notes":[]},{"n":17,"t":"羔羊必來吃草，如同在自己的草場；在富有人的廢墟，流浪的牲畜也來吃。","notes":["「在富有人...來吃」或譯「豐肥人的荒場被流浪的人吃盡」。"]},{"n":18,"t":"禍哉！那些以虛假的繩子牽引罪孽，以套車的繩索緊拉罪惡的人。","notes":[]},{"n":19,"t":"他們說：「任以色列的聖者急速前行，快快成就他的作為，好讓我們看看；任他的籌算臨近成就，好使我們知道。」","notes":[]},{"n":20,"t":"禍哉！那些稱惡為善，稱善為惡，以暗為光，以光為暗，以苦為甜，以甜為苦的人。","notes":[]},{"n":21,"t":"禍哉！那些在自己眼中有智慧，在自己面前有通達的人。","notes":[]},{"n":22,"t":"禍哉！那些以飲酒稱雄，以調烈酒稱霸的人。","notes":[]},{"n":23,"t":"他們因受賄賂，就稱惡人為義，將義人的義奪去。","notes":[]},{"n":24,"t":"火苗怎樣吞滅碎稭，乾草怎樣落在火焰之中，照樣，他們的根必然腐朽，他們的花像灰塵揚起；因為他們厭棄萬軍之耶和華的教誨，藐視以色列聖者的言語。","notes":[]},{"n":25,"t":"因此，耶和華的怒氣向他的百姓發作。他伸手攻擊他們，山嶺就震動；他們的屍首在街市上好像糞土。雖然如此，他的怒氣並未轉消，他的手依然伸出。","notes":[]},{"n":26,"t":"他必豎立大旗，召集遠方的國民，把他們從地極叫來。看哪，他們必急速奔來，","notes":[]},{"n":27,"t":"其中沒有疲倦的，絆跌的；沒有打盹的，睡覺的；腰帶並不放鬆，鞋帶也不拉斷。","notes":[]},{"n":28,"t":"他們的箭銳利，弓也上了弦；馬蹄如堅石，車輪像旋風。","notes":[]},{"n":29,"t":"他們要吼叫，像母獅，咆哮，像少壯獅子；他們要咆哮，抓取獵物，穩穩叼走，無人能救回。","notes":[]},{"n":30,"t":"那日，他們要向以色列人咆哮，像海浪澎湃；人若望地，看哪，只有黑暗與禍患，光明因密雲而變黑暗。","notes":[]}]},"6":{"heading":"主呼召以賽亞作先知","verses":[{"n":1,"t":"當烏西雅王崩的那年，我看見主坐在高高的寶座上。他的衣裳下襬遮滿聖殿。","notes":[]},{"n":2,"t":"上有撒拉弗侍立，各有六個翅膀：兩個翅膀遮臉，兩個翅膀遮腳，兩個翅膀飛翔，","notes":[]},{"n":3,"t":"彼此呼喊說：「聖哉！聖哉！聖哉！萬軍之耶和華；他的榮光遍滿全地！」","notes":[]},{"n":4,"t":"因呼喊者的聲音，門檻的根基震動，殿裏充滿了煙雲。","notes":[]},{"n":5,"t":"那時我說：「禍哉！我滅亡了！因為我是嘴唇不潔的人，住在嘴唇不潔的民中，又因我親眼看見大君王－萬軍之耶和華。」","notes":[]},{"n":6,"t":"有一撒拉弗向我飛來，手裏拿著燒紅的炭，是用火鉗從壇上取下來的，","notes":[]},{"n":7,"t":"用炭沾我的口，說：「看哪，這炭沾了你的嘴唇，你的罪孽便除掉，你的罪惡就赦免了。」","notes":[]},{"n":8,"t":"我聽見主的聲音說：「我可以差遣誰呢？誰肯為我們去呢？」我說：「我在這裏，請差遣我！」","notes":[]},{"n":9,"t":"他說：「你去告訴這百姓說：『你們聽了又聽，卻不明白；看了又看，卻不曉得。』","notes":[]},{"n":10,"t":"要使這百姓心蒙油脂，耳朵發沉，眼睛昏花；恐怕他們眼睛看見，耳朵聽見，心裏明白，回轉過來，就得醫治。」","notes":[]},{"n":11,"t":"我就說：「主啊，這到幾時為止呢？」他說：「直到城鎮荒涼，無人居住，房屋空無一人，土地極其荒蕪；","notes":[]},{"n":12,"t":"耶和華將人遷到遠方，國內被撇棄的土地很多。","notes":[]},{"n":13,"t":"國內剩下的人若還有十分之一，也必被吞滅。然而如同大樹與橡樹，雖被砍伐，殘幹卻仍存留，聖潔的苗裔是它的殘幹。」","notes":[]}]},"7":{"heading":"傳給亞哈斯王的信息","verses":[{"n":1,"t":"烏西雅的孫子，約坦的兒子，猶大王亞哈斯在位的時候，亞蘭王利汛和利瑪利的兒子以色列王比加上來攻打耶路撒冷，卻不能攻取。","notes":[]},{"n":2,"t":"有人告訴大衛家說：「亞蘭與以法蓮已經結盟。」王的心和百姓的心就都顫動，好像林中的樹被風吹動一樣。","notes":[]},{"n":3,"t":"耶和華對以賽亞說：「你和你的兒子施亞‧雅述要出去，到上池的水溝盡頭，往漂布地的大路上，迎見亞哈斯，","notes":["「施亞‧雅述」意思是「餘民要歸回」。"]},{"n":4,"t":"對他說：『你要謹慎，要鎮定，不要害怕，不要因利汛和亞蘭，以及利瑪利的兒子這兩個冒煙火把的頭所發的烈怒而心裏膽怯。","notes":[]},{"n":5,"t":"因為亞蘭、以法蓮，和利瑪利的兒子設惡謀要害你，說：","notes":[]},{"n":6,"t":"我們要上去攻擊猶大，擾亂它，攻破它來歸我們，在其中立他比勒的兒子為王。","notes":[]},{"n":7,"t":"主耶和華如此說：這事必站立不住，也不得成就。","notes":[]},{"n":8,"t":"因為亞蘭的首都是大馬士革，大馬士革的領袖是利汛；六十五年之內，以法蓮必然國破族亡，","notes":[]},{"n":9,"t":"以法蓮的首都是撒瑪利亞；撒瑪利亞的領袖是利瑪利的兒子。你們若是不信，必站立不穩。』」","notes":[]},{"n":10,"t":"耶和華又吩咐亞哈斯：","notes":[],"heads":["以馬內利的記號"]},{"n":11,"t":"「你向耶和華－你的神求一個預兆：在陰間的深淵，或往上的高處。」","notes":[]},{"n":12,"t":"但亞哈斯說：「我不求；我不試探耶和華。」","notes":[]},{"n":13,"t":"以賽亞說：「聽啊，大衛家！你們使人厭煩豈算小事，還要使我的神厭煩嗎？","notes":[]},{"n":14,"t":"因此，主自己要給你們一個預兆，看哪，必有童女懷孕生子，給他起名叫以馬內利。","notes":["「以馬內利」意思是「神與我們同在」。"]},{"n":15,"t":"到他曉得棄惡擇善的時候，他必吃乳酪與蜂蜜。","notes":[]},{"n":16,"t":"因為在這孩子還不曉得棄惡擇善之先，你所憎惡的那兩個王的土地必被撇棄。","notes":[]},{"n":17,"t":"耶和華必使亞述王臨到你和你的百姓，並你的父家，自從以法蓮脫離猶大的時候，未曾有過這樣的日子。","notes":[]},{"n":18,"t":"「那時，耶和華要呼叫，召來埃及江河源頭的蒼蠅和亞述地的蜂；","notes":[]},{"n":19,"t":"牠們都必飛來，停在陡峭的谷中、巖石縫裏、一切荊棘叢中和片片草場上。","notes":[]},{"n":20,"t":"「那時，主必用大河外雇來的剃頭刀，就是亞述王，剃去你的頭髮和腳毛，並要剃淨你的鬍鬚。","notes":[]},{"n":21,"t":"「那時，每一個人要養活一頭母牛犢和兩隻母羊；","notes":[]},{"n":22,"t":"因為奶量充足，他就有乳酪可吃，國內剩餘的人也都能吃乳酪與蜂蜜。","notes":[]},{"n":23,"t":"「那時，凡種一千棵葡萄樹、價值一千銀子的地方，必長出荊棘和蒺藜。","notes":[]},{"n":24,"t":"人到那裏去，必帶弓箭，因為遍地長滿了荊棘和蒺藜。","notes":[]},{"n":25,"t":"所有鋤頭刨過的山地，你因懼怕荊棘和蒺藜，不敢到那裏去；只能作放牛之處，羊群踐踏之地。」","notes":[]}]},"8":{"heading":"用以賽亞的兒子作記號","verses":[{"n":1,"t":"耶和華對我說：「你取一塊大板子，拿人的筆，寫上『瑪黑珥‧沙拉勒‧哈施‧罷斯』。","notes":["「拿人的筆」或譯「用普通的字」。","「瑪黑珥‧沙拉勒‧哈施‧罷斯」意思是「擄掠速臨、搶奪即將發生」。"]},{"n":2,"t":"我要用可靠的證人，烏利亞祭司和耶比利家的兒子撒迦利亞為我作證。」","notes":["「我」：有古卷和七十士譯本是「你」。"]},{"n":3,"t":"我親近女先知；她就懷孕生子，耶和華對我說：「給他起名叫瑪黑珥‧沙拉勒‧哈施‧罷斯；","notes":["「女先知」是以賽亞的妻子。"]},{"n":4,"t":"因為在這孩子還不曉得叫爸爸媽媽以前，大馬士革的財寶和撒瑪利亞的擄物必被亞述王掠奪一空。」","notes":[]},{"n":5,"t":"耶和華又吩咐我：","notes":[],"heads":["亞述王速臨"]},{"n":6,"t":"「這百姓既厭棄西羅亞緩流的水，喜歡利汛以及利瑪利的兒子，","notes":[]},{"n":7,"t":"因此，看哪，主必使亞述王和他的威勢如大河翻騰洶湧的水上漲，蓋過他們，必上漲超過一切水道，漲過兩岸，","notes":[]},{"n":8,"t":"必沖入猶大，漲溢氾濫，直到頸項。他展開翅膀，遮蔽你的全地。以馬內利啊！」","notes":[]},{"n":9,"t":"萬民哪，任憑你們行惡，終必毀滅；遠方的眾人哪，當側耳而聽！任憑你們束腰，終必毀滅；你們束起腰來，終必毀滅。","notes":["「行惡」或譯「崩潰」或「喧嚷」。"]},{"n":10,"t":"任憑你們籌算甚麼，終必無效；不管你們講定甚麼，總不成立；因為神與我們同在。","notes":[]},{"n":11,"t":"耶和華以大能的手訓誡我不可行這百姓所行的道，對我這樣說：","notes":["「訓誡我不可行」：死海古卷是「使我遠離」。"],"heads":["耶和華警告先知"]},{"n":12,"t":"「這百姓說同謀背叛的，你們不要說同謀背叛。他們所怕的，你們不要怕，也不要畏懼；","notes":[]},{"n":13,"t":"但要尊萬軍之耶和華為聖，他才是你們所當怕的，所當畏懼的。","notes":[]},{"n":14,"t":"他必作為聖所，卻向以色列的兩家成為絆腳的石頭，使人跌倒的磐石；作耶路撒冷居民的羅網和圈套。","notes":[]},{"n":15,"t":"許多人在其上絆倒，他們跌倒，甚至跌傷，並且落入陷阱，被抓住了。」","notes":[]},{"n":16,"t":"你要捲起律法書，在我門徒中間封住教誨。","notes":[],"heads":["不要求問死人"]},{"n":17,"t":"我要等候那轉臉不顧雅各家的耶和華，也要仰望他。","notes":[]},{"n":18,"t":"看哪，我與耶和華所賜給我的兒女成了以色列的預兆和奇蹟，這是從住在錫安山萬軍之耶和華來的。","notes":[]},{"n":19,"t":"有人對你們說：「當求問招魂的與行巫術的，他們唧唧喳喳，念念有詞。」然而，百姓不當求問自己的神嗎？豈可為活人求問死人呢？","notes":[]},{"n":20,"t":"當以教誨和律法書為準；人所說的若不與此相符，必沒有黎明。","notes":[]},{"n":21,"t":"他必經過這地，遇艱難，受飢餓；飢餓的時候，心中焦躁，咒罵自己的君王和神。他仰觀上天，","notes":[],"heads":["遭難的時候"]},{"n":22,"t":"俯察下地，看哪，盡是艱難、黑暗和駭人的昏暗。他必被趕入幽暗中去。","notes":[]}]},"9":{"heading":"未來的君王","verses":[{"n":1,"t":"但那受過痛苦的必不再見幽暗。從前神使西布倫地和拿弗他利地被藐視，末後卻使這沿海的路，約旦河東，外邦人居住的加利利地得榮耀。","notes":[]},{"n":2,"t":"在黑暗中行走的百姓看見了大光；住在死蔭之地的人有光照耀他們。","notes":[]},{"n":3,"t":"你使這國民眾多，使他們喜樂大增；他們在你面前歡喜，好像收割時的歡喜，又像人分戰利品那樣的快樂。","notes":["「你使這國民眾多」：原文另譯「你增加他們的快樂」。"]},{"n":4,"t":"因為他們所負的重軛和肩頭上的杖，並欺壓者的棍，你都已經折斷，如同在米甸的日子一般。","notes":[]},{"n":5,"t":"戰士在戰亂中所穿的靴子，以及那滾在血中的衣服，都必當作柴火燃燒。","notes":[]},{"n":6,"t":"因有一嬰孩為我們而生；有一子賜給我們。政權必擔在他的肩頭上；他名稱為「奇妙策士、全能的神、永在的父、和平的君」。","notes":[]},{"n":7,"t":"他的政權與平安必加增無窮。他必在大衛的寶座上治理他的國，以公平公義使國堅定穩固，從今直到永遠。萬軍之耶和華的熱心必成就這事。","notes":[]},{"n":8,"t":"主向雅各家發出言語，主的話臨到以色列家。","notes":[],"heads":["耶和華要懲罰以色列"]},{"n":9,"t":"眾百姓，就是以法蓮和撒瑪利亞的居民，都將知道；他們憑驕傲自大的心說：","notes":[]},{"n":10,"t":"「磚塊掉落了，我們要鑿石頭重建；桑樹砍了，我們要改種香柏樹。」","notes":[]},{"n":11,"t":"因此，耶和華興起利汛的敵人前來攻擊以色列，要激起它的仇敵，","notes":["「利汛的敵人」：有些現代的譯本譯為「敵人」、「敵人利汛」或「他們的敵人利汛」。"]},{"n":12,"t":"東有亞蘭人，西有非利士人；他們張口吞吃以色列。雖然如此，耶和華的怒氣並未轉消；他的手依然伸出。","notes":[]},{"n":13,"t":"這百姓還沒有歸向擊打他們的主，也沒有尋求萬軍之耶和華。","notes":[]},{"n":14,"t":"耶和華在一日之間從以色列中剪除了頭與尾－棕樹枝與蘆葦－","notes":[]},{"n":15,"t":"長老和顯要就是頭，以謊言教人的先知就是尾。","notes":[]},{"n":16,"t":"因為引導這百姓的使他們走入迷途，被引導的都必被吞滅。","notes":[]},{"n":17,"t":"所以，主不喜愛他們的青年，也不憐憫他們的孤兒和寡婦；因為他們都是褻瀆的，行惡的，並且各人的口都說愚妄的話。雖然如此，耶和華的怒氣並未轉消；他的手依然伸出。","notes":["「喜愛」有古卷是「喜悅」；死海古卷是「顧惜」。"]},{"n":18,"t":"邪惡如火焚燒，吞滅荊棘和蒺藜，在稠密的樹林中點燃，成為煙柱，旋轉上騰。","notes":[]},{"n":19,"t":"因萬軍之耶和華的烈怒，地都燒遍了；百姓成為柴火，無人憐惜弟兄。","notes":[]},{"n":20,"t":"有人右邊搶奪，猶受飢餓；左邊吞吃，仍不飽足，各人吃自己膀臂上的肉。","notes":[]},{"n":21,"t":"瑪拿西吞吃以法蓮，以法蓮吞吃瑪拿西，他們又一同攻擊猶大。雖然如此，耶和華的怒氣並未轉消；他的手依然伸出。","notes":[]}]},"10":{"heading":"神用亞述王為工具","verses":[{"n":1,"t":"禍哉！那些設立不義之律例的，和記錄奸詐之判詞的，","notes":[]},{"n":2,"t":"為要扭曲貧寒人的案件，奪去我民中困苦人的理，以寡婦當作擄物，以孤兒當作掠物。","notes":[]},{"n":3,"t":"到降罰的日子，災禍從遠方臨到，那時，你們要怎麼辦呢？你們要向誰逃奔求救呢？你們的財寶要存放何處呢？","notes":[]},{"n":4,"t":"他們只得屈身在被擄的人之下，仆倒在被殺的人中間。雖然如此，耶和華的怒氣並未轉消；他的手依然伸出。","notes":["「他們...中間」或譯「那些不願屈身被擄的人，將仆倒在被殺的人中間」。"]},{"n":5,"t":"禍哉！亞述，我怒氣的棍！他們手中的杖是我的惱恨。","notes":[]},{"n":6,"t":"我要差遣他攻擊褻瀆的國，吩咐他對付我所惱怒的民，搶走擄物，奪取掠物，將他們踐踏，如同街上的泥土一般。","notes":[]},{"n":7,"t":"然而，這並非他的意念，他的心不是這樣打算；他的心要摧毀，要剪除不少的國家。","notes":[]},{"n":8,"t":"他說：「我的官長豈不都是君王嗎？","notes":[]},{"n":9,"t":"迦勒挪豈不像迦基米施嗎？哈馬豈不像亞珥拔嗎？撒瑪利亞豈不像大馬士革嗎？","notes":[]},{"n":10,"t":"既然我的手已伸到了這些有偶像的國，他們所雕刻的偶像過於耶路撒冷和撒瑪利亞的偶像，","notes":[]},{"n":11,"t":"我豈不照樣待耶路撒冷和其中的偶像，如同我待撒瑪利亞和其中的偶像嗎？」","notes":[]},{"n":12,"t":"主在錫安山和耶路撒冷成就他一切工作的時候，說：「我必懲罰亞述王自大的心和他高傲尊貴的眼目。」","notes":[]},{"n":13,"t":"因為他說：「我所成就的事是靠我手的能力和我的智慧，因為我本有聰明。我挪移列國的地界，搶奪他們所積蓄的財寶，並且像勇士，使坐寶座的降為卑。","notes":[]},{"n":14,"t":"我的手奪取列國的財寶，好像人奪取鳥窩；我得了全地，好像人拾起被棄的鳥蛋；沒有振動翅膀的，沒有張嘴的，也沒有鳴叫的。」","notes":[]},{"n":15,"t":"斧豈可向用斧砍伐的自誇呢？鋸豈可向拉鋸的自大呢？這好比棍揮動那舉棍的，好比杖舉起那不是木頭的人。","notes":[]},{"n":16,"t":"因此，主－萬軍之耶和華必使亞述王的壯士變為瘦弱，在他的榮華之下必有火點燃，如同火在燃燒一般。","notes":[]},{"n":17,"t":"以色列的光必變成火，它的聖者必成為火焰；一日之間，將亞述王的荊棘和蒺藜焚燒淨盡，","notes":[]},{"n":18,"t":"又毀滅樹林和田園的榮華，連魂帶體，好像病重的人消逝一樣。","notes":["「病重的人消逝」或譯「拿軍旗的昏過去」。"]},{"n":19,"t":"他林中只剩下稀少的樹木，連孩童也能寫其數目。","notes":[]},{"n":20,"t":"到那日，以色列所剩下的和雅各家所逃脫的，必不再倚靠那擊打他們的，卻要誠心仰賴耶和華－以色列的聖者。","notes":[],"heads":["殘存之民歸回"]},{"n":21,"t":"所剩下的，就是雅各家的餘民，必歸回全能的神。","notes":[]},{"n":22,"t":"以色列啊，你的百姓雖多如海沙，惟有剩下的歸回。滅絕之事已成定局，公義必如水漲溢。","notes":[]},{"n":23,"t":"因為萬軍之主耶和華在全地必成就所定的滅絕之事。","notes":[]},{"n":24,"t":"所以，萬軍之主耶和華如此說：「住錫安我的百姓啊，亞述王雖然用棍擊打你，又如埃及舉杖攻擊你，你不要怕他。","notes":[],"heads":["耶和華要懲罰亞述"]},{"n":25,"t":"因為還有一點點時候，我向你們發的憤怒就要結束，我的怒氣要使他們滅亡。","notes":[]},{"n":26,"t":"萬軍之耶和華要舉起鞭子來攻擊他，好像在俄立磐石那裏擊打米甸人一樣。他的杖向海伸出，他必把杖舉起，如在埃及一般。","notes":[]},{"n":27,"t":"到那日，亞述王的重擔必離開你的肩頭，他的軛必離開你的頸項；那軛必因肥壯而撐斷。」","notes":["「他的軛...撐斷」：七十士譯本是「他的軛必折斷離開你的頸項」。"]},{"n":28,"t":"亞述王來到亞葉，經過米磯崙，在密抹安放輜重。","notes":[],"heads":["侵略者進攻"]},{"n":29,"t":"他們過了隘口，要在迦巴住宿。拉瑪戰兢，掃羅的基比亞逃命。","notes":[]},{"n":30,"t":"迦琳哪，要高聲呼喊！注意聽，萊煞啊！困苦的亞拿突啊！","notes":["「迦琳」：原文直譯「迦琳女子」。","「困苦的亞拿突啊」：原文另譯「回應他，亞拿突啊」。"]},{"n":31,"t":"瑪得米那躲避，基柄的居民逃遁。","notes":[]},{"n":32,"t":"當那日，亞述王要在挪伯停留，揮手攻擊錫安的山，就是耶路撒冷的山。","notes":["「錫安」：原文直譯「錫安女子」。"]},{"n":33,"t":"看哪，主－萬軍之耶和華以猛撞削斷樹枝；巨木必被砍下，高大的樹必降為低。","notes":[]},{"n":34,"t":"稠密的樹林，他要用鐵器砍下，黎巴嫩必被大能者伐倒。","notes":["「黎巴嫩必被大能者伐倒」或譯「黎巴嫩的榮華必傾倒」。"]}]},"11":{"heading":"和平的國度","verses":[{"n":1,"t":"從耶西的殘幹必長出嫩枝，他的根所抽的枝子必結果實。","notes":[]},{"n":2,"t":"耶和華的靈必住在他身上，就是智慧和聰明的靈，謀略和能力的靈，知識和敬畏耶和華的靈。","notes":[]},{"n":3,"t":"他必以敬畏耶和華為樂；行審判不憑眼見，斷是非也不憑耳聞；","notes":[]},{"n":4,"t":"卻要以公義審判貧寒人，以正直判斷地上的困苦人，以口中的棍擊打全地，以嘴裏的氣殺戮惡人。","notes":[]},{"n":5,"t":"公義必當他的腰帶，信實必作他脅下的帶子。","notes":[]},{"n":6,"t":"野狼必與小綿羊同住，豹子與小山羊同臥；少壯獅子、牛犢和肥畜同群；孩童要牽引牠們。","notes":["「和肥畜同群」：死海古卷是「一起長大」。"]},{"n":7,"t":"牛必與熊同食，牛犢與小熊同臥；獅子與牛一樣吃草。","notes":[]},{"n":8,"t":"吃奶的嬰孩在虺蛇的洞口玩耍，斷奶的幼兒必按手在毒蛇的穴上。","notes":[]},{"n":9,"t":"在我聖山各處，牠們都不傷人，不害物；因為認識耶和華的知識要遍滿全地，好像水充滿海洋一般。","notes":[]},{"n":10,"t":"到那日，耶西的根立作萬民的大旗；列國的人必尋求他，他安歇之所大有榮耀。","notes":[],"heads":["被擄的人歸回"]},{"n":11,"t":"當那日，主必再度伸手救回自己百姓中所剩餘的，就是在亞述、埃及、巴特羅、古實、以攔、示拿、哈馬，並眾海島所剩下的。","notes":["「古實」包括蘇丹的大部分和埃塞俄比亞的一部分。"]},{"n":12,"t":"他要向列國豎立大旗，召集以色列被趕散的人，又從地極四方聚集分散的猶大人。","notes":[]},{"n":13,"t":"以法蓮的嫉妒必消散，苦待猶大的也被剪除；以法蓮必不嫉妒猶大，猶大也不苦待以法蓮。","notes":[]},{"n":14,"t":"他們要飛向西方，撲在非利士人的肩頭上，他們要一同擄掠東方人，他們的手伸到以東和摩押；亞捫人也必順服他們。","notes":[]},{"n":15,"t":"耶和華必使埃及的海灣全然毀壞，他舉手在大河之上颳起了暴熱的風，擊打它，使它分成七條溪流，人穿鞋便可渡過。","notes":["「全然毀壞」：原文另譯「枯乾」；七十士譯本是「荒蕪」。"]},{"n":16,"t":"必有一條大道，為百姓中從亞述逃脫生還的餘民而開，如當日為以色列從埃及上來一樣。","notes":[]}]},"12":{"heading":"感恩的詩歌","verses":[{"n":1,"t":"在那日，你要說：「耶和華啊，我要稱謝你！因為你雖然向我發怒，你的怒氣卻已轉消；你又安慰了我。","notes":[]},{"n":2,"t":"「看哪！神是我的拯救；我要倚靠他，並不懼怕。因為主耶和華是我的力量，是我的詩歌，他也成了我的拯救。」","notes":[]},{"n":3,"t":"你們必從救恩的泉源歡然取水。","notes":[]},{"n":4,"t":"在那日，你們要說：「當稱謝耶和華，求告他的名；在萬民中傳揚他的作為，宣告他的名已被尊崇。","notes":[]},{"n":5,"t":"「你們要向耶和華唱歌，因他所做的十分宏偉；但願這事遍傳全地。","notes":[]},{"n":6,"t":"錫安的居民哪，當揚聲歡呼，因為在你們當中的以色列聖者最為偉大。」","notes":[]}]},"13":{"heading":"神要懲罰巴比倫","verses":[{"n":1,"t":"亞摩斯的兒子以賽亞所見，有關巴比倫的默示。","notes":[]},{"n":2,"t":"你們要在荒涼的山上豎立大旗，向他們揚聲，揮手招呼他們進入貴族之門。","notes":[]},{"n":3,"t":"我吩咐我所分別為聖的人，召喚我的勇士，就是我那狂喜高傲的人，為要執行我的怒氣。","notes":[]},{"n":4,"t":"聽啊，山間有喧鬧的聲音，好像有許多百姓聚集，聽啊，多國之民聚集鬧鬨的聲音；這是萬軍之耶和華召集作戰的軍隊。","notes":[]},{"n":5,"t":"他們從遠方來，從天邊來，耶和華和他惱恨的兵器要毀滅全地。","notes":[]},{"n":6,"t":"你們要哀號，因為耶和華的日子臨近了！這日來到，好像毀滅從全能者來到。","notes":[]},{"n":7,"t":"因此，人的手都變軟弱，人的心都必惶惶。","notes":[]},{"n":8,"t":"他們必驚恐，悲痛和愁苦將他們抓住。他們陣痛，好像臨產的婦人一樣，彼此驚奇對看，臉如火焰。","notes":[]},{"n":9,"t":"看哪！耶和華的日子臨到，必有殘忍、憤恨、烈怒，使這地荒蕪，除滅其中的罪人。","notes":[]},{"n":10,"t":"天上的星宿都不發光，太陽一升起就變黑暗，月亮也不放光。","notes":[]},{"n":11,"t":"我必因邪惡懲罰世界，因罪孽懲罰惡人，我要止息驕傲人的狂妄，制伏殘暴者的傲慢。","notes":[]},{"n":12,"t":"我要使人比純金更少，比俄斐的赤金還少。","notes":[]},{"n":13,"t":"我，萬軍之耶和華狂怒，就是發烈怒的日子，要令天震動，地必搖撼，離其本位。","notes":[]},{"n":14,"t":"人如被追趕的羚羊，像無人聚集的羊群，各自歸回本族，逃到本地。","notes":[]},{"n":15,"t":"凡被追上的必被刺死，凡被捉拿的必倒在刀下。","notes":[]},{"n":16,"t":"他們的嬰孩必在他們眼前被摔死，他們的房屋被搶劫，他們的妻子被污辱。","notes":[]},{"n":17,"t":"看哪，我必激起瑪代人攻擊他們，瑪代人並不看重銀子，也不喜愛金子。","notes":[]},{"n":18,"t":"他們必用弓擊潰青年，不憐憫婦人所生的；眼也不顧惜孩子。","notes":[]},{"n":19,"t":"巴比倫為列國的榮耀，為迦勒底人所誇耀的華美，必像神所傾覆的所多瑪、蛾摩拉一樣；","notes":[]},{"n":20,"t":"國中必永無人煙，世世代代無人居住；阿拉伯人不在那裏支搭帳棚，牧羊的人也不使羊群躺臥在那裏。","notes":[]},{"n":21,"t":"曠野的走獸躺臥在那裏，咆哮的動物擠滿棲身之所；鴕鳥住在那裏，山羊鬼魔也在那裏跳舞。","notes":[]},{"n":22,"t":"土狼必在它的宮殿 呼號，野狗在華美的殿裏吼叫。巴比倫的時辰臨近了，它的日子必不長久。","notes":["「宮殿」是根據一些古譯本；原文是「寡婦」。"]}]},"14":{"heading":"從被擄中歸回","verses":[{"n":1,"t":"耶和華要憐憫雅各，再度揀選以色列，將他們安頓在本地。寄居的必與他們聯合，加入雅各家。","notes":[]},{"n":2,"t":"外邦人要將他們帶回本地。以色列家必在耶和華的地上得外邦人為僕婢，也要擄掠先前擄掠他們的，轄制先前欺壓他們的。","notes":[]},{"n":3,"t":"當耶和華使你得享安息，脫離愁苦、煩惱，和被迫做苦工的日子，","notes":[],"heads":["巴比倫王下到陰間"]},{"n":4,"t":"你必唱這詩歌嘲諷巴比倫王說：「欺壓人的竟然滅亡！他的兇暴竟然止息！","notes":["「他的兇暴」是根據死海古卷和古譯本；原文是「一堆金子」。"]},{"n":5,"t":"耶和華折斷惡人的杖，打斷統治者的權杖；","notes":[]},{"n":6,"t":"他們在憤怒中連連攻擊萬民，在怒氣中轄制列國，逼迫他們，毫不留情。","notes":[]},{"n":7,"t":"現在全地得安息，享平靜，人都出聲歡呼。","notes":[]},{"n":8,"t":"松樹和黎巴嫩的香柏樹都因你歡樂：自從你仆倒，再也無人上來砍伐我們。","notes":[]},{"n":9,"t":"下面的陰間因你震動，迎接你的到來；在世曾為領袖的陰魂為你驚動，那曾為列國君王的，都從寶座起立。","notes":[]},{"n":10,"t":"他們都要發言，對你說：『你也變為軟弱，像我們一樣嗎？你也成了我們的樣子嗎？』","notes":[]},{"n":11,"t":"你的威嚴和琴瑟的聲音都下到陰間。你下面鋪的是蟲，上面蓋的是蛆。","notes":[]},{"n":12,"t":"「明亮之星，早晨之子啊，你竟然從天墜落！你這攻敗列國的，竟然被砍倒在地上！","notes":[]},{"n":13,"t":"你心裏曾說：『我要升到天上，我要高舉我的寶座在神的眾星之上，我要坐在會眾聚集的山上，在極北的地方。","notes":[]},{"n":14,"t":"我要升到高雲之上，我要與至高者同等。』","notes":[]},{"n":15,"t":"然而，你必墜落陰間，到地府極深之處。","notes":[]},{"n":16,"t":"凡看見你的都要定睛望你，留意看你，說：『就是這個人嗎？他使大地顫抖，使列國震動，","notes":[]},{"n":17,"t":"使世界如同荒野，使城鎮傾覆；是他，不釋放被擄的人歸家。』","notes":[]},{"n":18,"t":"列國的君王各自在自己的墳墓中，在尊榮裏長眠。","notes":[]},{"n":19,"t":"惟獨你被拋棄在你的墳墓之外，有如被厭惡的枝子，被許多用刀刺透殺死的人覆蓋著，一同墜落地府的石頭那裏，像被踐踏的屍首。","notes":["「枝子」與「尼布甲尼撒」的希伯來話發音相近；原文另譯「屍身」。"]},{"n":20,"t":"你不得與君王同葬，因為你毀壞你的國，殺戮你的民。「惡人的後裔永不留名。","notes":[]},{"n":21,"t":"為了祖先的罪孽，要預備他子孫的屠宰場，免得他們興起，奪得全地，使城市遍滿地面。」","notes":[]},{"n":22,"t":"萬軍之耶和華說：「我必起來攻擊他們，將巴比倫的名號和剩餘的人，連子帶孫一併剪除；這是耶和華說的。","notes":[],"heads":["神要毀滅巴比倫"]},{"n":23,"t":"「我必使巴比倫為豪豬佔據，成為泥沼之地；我要用滅命的掃帚掃淨它；這是萬軍之耶和華說的。」","notes":[]},{"n":24,"t":"萬軍之耶和華起誓說：「我怎樣思想，必照樣成就；我怎樣定意，必照樣堅立，","notes":[],"heads":["神要毀滅亞述"]},{"n":25,"t":"要在我的地上擊破亞述，在我的山上將它踐踏。它的軛必離開受壓制的人，它的重擔必離開他們的肩頭。」","notes":[]},{"n":26,"t":"這是向全地所定的旨意，向萬國所伸出的手。","notes":[]},{"n":27,"t":"萬軍之耶和華既然定意，誰能阻撓呢？他的手已經伸出，誰能使它縮回呢？","notes":[]},{"n":28,"t":"亞哈斯王崩的那年，有默示如下：","notes":[],"heads":["神要毀滅非利士"]},{"n":29,"t":"「全非利士啊，不要因擊打你的杖折斷就喜樂。因為蛇必生出毒蛇，牠所生的是會飛的火蛇。","notes":[]},{"n":30,"t":"貧寒人的長子必有得吃；貧窮人必安然躺臥。我必以饑荒滅絕你的根，牠必殺盡你所剩餘的人。","notes":["「牠」：死海古卷是「我」。"]},{"n":31,"t":"門哪，哀號吧！城啊，呼喊吧！全非利士都熔化了！因為有煙從北方而來，在它的行伍中沒有掉隊的。」","notes":[]},{"n":32,"t":"當如何回答外邦的使者呢？「耶和華建立了錫安，在其中他困苦的百姓必有倚靠。」","notes":[]}]},"15":{"heading":"神要毀滅摩押","verses":[{"n":1,"t":"論摩押的默示。一夜之間，摩押的亞珥變為荒廢，歸於無有；一夜之間，摩押的基珥變為荒廢，歸於無有。","notes":[]},{"n":2,"t":"摩押上到神廟和底本的丘壇去哭泣；它因尼波和米底巴哀號，各人頭上光禿，鬍鬚剃淨。","notes":[]},{"n":3,"t":"他們在街市上腰束麻布，都在房頂和廣場上哀號，淚流不停。","notes":[]},{"n":4,"t":"希實本和以利亞利呼喊，他們的聲音達到雅雜，所以摩押的士兵高聲喊叫，他們的心戰兢。","notes":[]},{"n":5,"t":"我的心為摩押哀號；它的難民逃到瑣珥，逃到伊基拉‧施利施亞。他們上魯希坡，隨走隨哭，在何羅念的路上，因毀滅發出哀聲。","notes":["「我的心」：有古卷是「它的心」。"]},{"n":6,"t":"寧林的水乾涸，青草枯乾，嫩草死光，青綠之物，一無所有。","notes":[]},{"n":7,"t":"因此，摩押人所得的財物和積蓄都要運過柳樹河。","notes":[]},{"n":8,"t":"哀聲遍傳摩押四境，哀號的聲音達到以基蓮，哀號的聲音遠及比珥‧以琳。","notes":[]},{"n":9,"t":"底們的水充滿了血，然而我還要加添底們的災難，讓獅子追上摩押的難民和那地剩餘的人。","notes":["「底們」：有古卷是「底本」；下同。","「讓獅子追上」：死海古卷是「我要淹沒」。","「那地」：七十士譯本是「押瑪」。"]}]},"16":{"heading":"摩押的難民逃到猶大","verses":[{"n":1,"t":"你們當將羔羊奉送給那地的掌權者，從西拉往曠野，送到錫安的山。","notes":["「你們當將」：有古卷是「他們將」。","「錫安」：原文直譯「錫安女子」。"]},{"n":2,"t":"摩押的居民來到亞嫩渡口，如逃遁的飛鳥，被趕離鳥巢。","notes":["「摩押的居民」：原文直譯「摩押眾女子」。","「被趕離鳥巢」或譯「如拆窩的雛」。"]},{"n":3,"t":"求你賜謀略，行公平，使你的影子在正午如黑夜，掩護逃亡的人，不洩露逃難者的行蹤。","notes":[]},{"n":4,"t":"願我摩押逃亡的人寄居在你那裏，你作他們的避難所，躲避滅命者的面。勒索的人消失，毀滅的事止息，欺壓者從國中除滅，","notes":["「願我摩押逃亡的人」：原文另譯「摩押逃亡的人」。"]},{"n":5,"t":"在大衛帳幕中必有寶座因慈愛堅立，必有一位君王憑信實坐在其上，施行審判，尋求公平，迅速行公義。","notes":[]},{"n":6,"t":"我們聽聞摩押的驕傲，極其驕傲；它狂妄、驕傲、自大，它誇大的言詞都是空的。","notes":[]},{"n":7,"t":"因此，摩押人必為摩押哀號，人人都要哀號。你們要為吉珥‧哈列設的葡萄餅哀嘆，極其憂傷。","notes":[]},{"n":8,"t":"因為希實本的田地和西比瑪的葡萄樹都衰殘了，列國的君主折斷它的枝幹，這枝子曾長到雅謝，延伸到曠野，嫩枝向外伸出，直伸過海；","notes":[]},{"n":9,"t":"所以，我要為西比瑪的葡萄樹哀哭，像雅謝人一樣哀哭。希實本、以利亞利啊，我要以眼淚澆灌你，你因夏天果子和收割的莊稼，歡呼聲已經止息了。","notes":[]},{"n":10,"t":"田園中不再有歡喜快樂，葡萄園裏必無人歌唱，無人歡呼，在壓酒池中踹酒的不再踹酒了，我使歡呼的聲音止息了。","notes":["「我使...止息了」：七十士譯本是「歡呼的聲音已止息了」。"]},{"n":11,"t":"因此，我的心腸為摩押哀鳴如琴，我的內心為吉珥‧哈列設哀哭。","notes":[]},{"n":12,"t":"當摩押人出現在丘壇，筋疲力盡時，雖然到自己的聖所祈禱，卻仍無濟於事。","notes":[]},{"n":13,"t":"這是耶和華曾論到摩押的話。","notes":[]},{"n":14,"t":"但現在，耶和華說：「三年之內，按照雇工年數的算法，摩押的榮華必變為羞辱，人口雖曾眾多，剩餘的又少又弱。」","notes":[]}]},"17":{"heading":"神要懲罰亞蘭和以色列","verses":[{"n":1,"t":"論大馬士革的默示。看哪，大馬士革不再為城市，變為廢墟。","notes":[]},{"n":2,"t":"亞羅珥的城鎮被撇棄，將成為牧羊之處，羊群在那裏躺臥，無人使牠們驚嚇。","notes":["「亞羅珥...被撇棄」：七十士譯本是「永遠被撇棄」。"]},{"n":3,"t":"以法蓮不再有堡壘，大馬士革失去其王國，亞蘭的百姓所剩無幾，如以色列人的榮美消失一般；這是萬軍之耶和華說的。","notes":[]},{"n":4,"t":"到那日，雅各的榮美必失色，它肥胖的身軀漸漸消瘦；","notes":[]},{"n":5,"t":"像人收割成熟的禾稼，用手臂割取麥穗，又像人在利乏音谷拾取穗子；","notes":[]},{"n":6,"t":"其間所剩不多，好像人打橄欖樹，在最高的樹梢上只剩兩、三顆橄欖，在多結果子的旁枝上只剩四、五顆；這是耶和華－以色列的神說的。","notes":[]},{"n":7,"t":"當那日，人必仰望造他們的主，眼目看著以色列的聖者。","notes":[]},{"n":8,"t":"他們必不仰望自己手所築的祭壇，也不理會自己指頭所造的亞舍拉和香壇。","notes":[]},{"n":9,"t":"當那日，他們堅固的城必因以色列人的緣故，如同樹林中和山頂上所撇棄的地方。這樣，地就荒蕪了。","notes":["「如同...地方」：七十士譯本是「如同亞摩利人和希未人所拋棄的城市」。"]},{"n":10,"t":"因你忘記拯救你的神，忘記那保護你的磐石；所以，你雖栽上佳美的樹苗，插上別樣的枝子，","notes":[]},{"n":11,"t":"栽種的日子，你使它生長，栽種的早晨，你使它開花，但在愁苦、極其傷痛的日子，所收割的都歸無有。","notes":[]},{"n":12,"t":"唉！萬民鬧鬨，好像海浪澎湃，列邦喧鬧，如同洪水滔滔，","notes":[],"heads":["敵國都被擊敗"]},{"n":13,"t":"列邦喧鬧，如同大水滔滔；但神一斥責，他們就遠遠躲避，他們被追趕，如同山上風前的糠秕，又如暴風前的碎稭；","notes":[]},{"n":14,"t":"看哪，晚上有驚嚇，未到早晨它就消失無蹤。這是擄掠我們之人的厄運，是搶奪我們之人的報應。","notes":[]}]},"18":{"heading":"神要責罰古實","verses":[{"n":1,"t":"禍哉！古實河的那一邊、翅膀刷刷作響之地，","notes":[]},{"n":2,"t":"差遣使者在水面上，坐蒲草船過海。你們這些疾行的使者，要到高大光滑的民那裏去；那民遠近都畏懼，是強大好征服的國，土地有河流穿過。","notes":[]},{"n":3,"t":"世上所有的居民，住在地上的人哪，山上大旗豎起時，你們要看，號角吹響時，你們要聽。","notes":[]},{"n":4,"t":"耶和華對我如此說：「我要安靜，從我的居所觀看，如同日光下閃爍的熱氣，又如收割時露水蒸發的雲霧。」","notes":["「收割時」是根據一些古卷、七十士譯本和其他古譯本；原文是「收割的熱氣」。"]},{"n":5,"t":"收割之前，花蕾先謝，花成了將熟的葡萄；他必用刀削去嫩枝，砍掉蔓延的枝條，","notes":[]},{"n":6,"t":"一起丟給山間的鷙鳥和地上的野獸；鷙鳥要在其上避暑，地上一切的野獸都在那裏過冬。","notes":[]},{"n":7,"t":"到那時，這高大光滑的民，遠近都畏懼的民、強大好征服之國、土地有河流穿過；他們必被當作禮物獻給萬軍之耶和華，獻到錫安山－萬軍之耶和華立他名的地方。","notes":["「被當作」：七十士譯本是「將」。"]}]},"19":{"heading":"神要懲罰埃及","verses":[{"n":1,"t":"論埃及的默示。看哪，耶和華乘駕快雲，臨到埃及；埃及的偶像在他面前戰兢，埃及人的心在裏面消溶。","notes":[]},{"n":2,"t":"我要激起埃及人攻擊埃及人，弟兄攻擊弟兄，鄰舍攻擊鄰舍，這城攻擊那城，這國攻擊那國。","notes":[]},{"n":3,"t":"埃及人的心神在裏面耗盡，我要破壞他們的計謀。他們必求問偶像和念咒的，求問招魂的與行巫術的人。","notes":[]},{"n":4,"t":"我要將埃及人交在嚴厲的主人手中，殘暴的君王必管轄他們；這是主－萬軍之耶和華說的。","notes":[]},{"n":5,"t":"海水枯竭，河流乾涸，","notes":[]},{"n":6,"t":"江河發臭，埃及的河水必然減少而枯乾。蘆葦和蘆荻枯萎，","notes":[]},{"n":7,"t":"尼羅河旁的植物，在尼羅河的沿岸，並尼羅河旁所種的一切全都枯焦，被風吹去，歸於無有。","notes":["「植物」：原文是「荒地」。"]},{"n":8,"t":"打魚的哀哭，所有在尼羅河釣魚的都必悲傷，在水上撒網的也都衰殘。","notes":[]},{"n":9,"t":"以細緻的麻編織的必羞愧，織布的必變蒼白；","notes":["本節是根據死海古卷；原文是「以細緻的麻編織的和織白布的，都必羞愧」。"]},{"n":10,"t":"織布的心情沮喪，所有的傭工心都愁煩。","notes":["「織布的心情沮喪」是根據死海古卷；原文是「他的支柱必打碎」。"]},{"n":11,"t":"瑣安的官長極其愚昧，法老智慧的謀士籌劃愚謀；你們怎敢對法老說：「我是智慧人的子孫，是古代國王的後裔？」","notes":[]},{"n":12,"t":"你的智慧人在哪裏？萬軍之耶和華向埃及所定的旨意，他們既然知道，就讓他們告訴你吧！","notes":[]},{"n":13,"t":"瑣安的官長愚昧，挪弗的官長受蒙蔽；作埃及支派棟梁的，帶領埃及走錯了路。","notes":["「挪弗」就是埃及的孟斐斯。"]},{"n":14,"t":"耶和華使歪曲的靈滲入埃及中間，讓他們使埃及一切所做的都出差錯，好像醉酒之人嘔吐時東倒西歪一樣。","notes":[]},{"n":15,"t":"在埃及，無論是頭是尾，棕樹枝與蘆葦，所做的事都不得成就。","notes":[]},{"n":16,"t":"到那日，埃及必像婦人一樣，因萬軍之耶和華揮手攻擊而戰兢懼怕。","notes":[]},{"n":17,"t":"猶大地必使埃及驚恐，不論向誰提起，他都懼怕。這是因萬軍之耶和華向埃及所定的旨意。","notes":[]},{"n":18,"t":"當那日，埃及地必有五個城市的人說迦南的語言，又指著萬軍之耶和華起誓。有一城必稱為「太陽城」。","notes":["「太陽城」是根據死海古卷和許多古卷；原文是「滅亡城」。"]},{"n":19,"t":"在那日，在埃及地將有獻給耶和華的一座壇，邊界上必有為耶和華立的一根柱子。","notes":[]},{"n":20,"t":"這都要在埃及地為萬軍之耶和華作記號和證據。埃及人因受欺壓哀求耶和華，他就差遣一位救主作護衛者，拯救他們，","notes":[]},{"n":21,"t":"耶和華就被埃及所認識。在那日，埃及人要認識耶和華，獻牲祭和素祭敬拜他，並向耶和華許願還願。","notes":[]},{"n":22,"t":"耶和華必擊打埃及，又擊打又醫治，埃及人就歸向耶和華。他必應允他們的禱告，醫治他們。","notes":[]},{"n":23,"t":"在那日，必有從埃及通往亞述的大道。亞述人要進入埃及，埃及人也要進入亞述；埃及人要與亞述人一同敬拜。","notes":[]},{"n":24,"t":"在那日，以色列將與埃及、亞述三國一起，使地上的人得福。","notes":[]},{"n":25,"t":"萬軍之耶和華必賜福給他們，說：「埃及－我的百姓，亞述－我手的工作，以色列－我的產業，都有福了！」","notes":[]}]},"20":{"heading":"赤身赤腳的先知","verses":[{"n":1,"t":"亞述元帥受亞述王撒珥根派遣往亞實突的那年，他攻打亞實突，將城攻取。","notes":["「亞述元帥」：原文是亞述的官職「他珥探」。"]},{"n":2,"t":"那時，耶和華吩咐亞摩斯的兒子以賽亞說：「你去解掉你腰間的麻布，脫下你腳上的鞋。」以賽亞就這樣做，赤身赤腳行走。","notes":[]},{"n":3,"t":"耶和華說：「我僕人以賽亞怎樣赤身赤腳行走三年，作為關於埃及和古實的預兆奇蹟，","notes":[]},{"n":4,"t":"照樣，亞述王必擄去埃及人，掠去古實人，無論老少，都赤身赤腳，露出下體，使埃及蒙羞。","notes":[]},{"n":5,"t":"以色列人必驚惶羞愧，因為他們仰望古實，以埃及為榮。","notes":[]},{"n":6,"t":"「那時，沿海一帶的居民必說：『看哪，我們素來所仰望的，就是為躲避亞述王所逃往求救的，不過如此！我們怎能逃脫呢？』」","notes":["「逃往」：死海古卷是「倚靠」。"]}]},"21":{"heading":"巴比倫的滅亡","verses":[{"n":1,"t":"論海邊曠野的默示。它像尼革夫的旋風掃過，從曠野，從可怕之地而來。","notes":["「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」；本卷書下同。"]},{"n":2,"t":"有悽慘的異象向我揭示：「詭詐的在行詭詐，毀滅的在行毀滅。以攔哪，前進吧！瑪代啊，圍攻吧！我使它一切的嘆息停止了。」","notes":[]},{"n":3,"t":"為此，我腰部滿是疼痛，痛苦將我抓住，好像臨產的婦人一樣的痛。我疼痛甚至不能聽，我驚惶甚至不能看。","notes":["「我疼痛...不能看」或譯「我所聽到的使我疼痛，我所見的使我驚惶」。"]},{"n":4,"t":"我心慌亂，驚恐威嚇我。我所渴望的黃昏，反成為我的恐懼。","notes":[]},{"n":5,"t":"有人擺設筵席，鋪上地毯，又吃又喝。「官長啊，起來，抹亮盾牌。」","notes":[]},{"n":6,"t":"主對我如此說：「你去設立守望者，讓他報告他所看見的。","notes":[]},{"n":7,"t":"他會看見一對一對騎著馬的軍隊，又看見驢隊，駱駝隊，他要留心聽，仔細地聽。」","notes":[]},{"n":8,"t":"他如獅子般吼叫：「主啊，我白天常站在瞭望樓，徹夜立在我的瞭望臺。」","notes":["「他如獅子般吼叫」：死海古卷是「守望者喊叫」。"]},{"n":9,"t":"看哪，有一對一對騎著馬的軍隊前來。他就回應說：「巴比倫傾倒了！傾倒了！他把巴比倫神明的一切雕刻偶像都打碎在地上了。」","notes":[]},{"n":10,"t":"我被打的禾稼，我禾場上的穀物啊，我從萬軍之耶和華－以色列的神那裏所聽見的，都告訴你們了。","notes":[]},{"n":11,"t":"論度瑪的默示。有人聲從西珥呼喊：「守望的啊，夜裏如何？守望的啊，夜裏如何？」","notes":[],"heads":["論以東的信息"]},{"n":12,"t":"守望者說：「早晨來到，黑夜將臨。你們若要問，問吧，也可以回頭再來。」","notes":[]},{"n":13,"t":"論阿拉伯的默示。底但的旅行商隊啊，你們在阿拉伯的樹林中住宿。","notes":[],"heads":["論阿拉伯的信息"]},{"n":14,"t":"提瑪地的居民哪，提水來迎接口渴的人，帶餅來迎接難民。","notes":[]},{"n":15,"t":"他們躲避刀劍和出了鞘的刀，躲避上了弦的弓與戰爭的重災。","notes":[]},{"n":16,"t":"主對我這樣說：「一年之內，按照雇工年數的算法，基達一切的繁華必歸無有。","notes":[]},{"n":17,"t":"基達人中強壯弓箭手剩下的數目甚為稀少，這是耶和華－以色列的神說的。」","notes":[]}]},"22":{"heading":"論耶路撒冷的信息","verses":[{"n":1,"t":"論異象谷的默示。甚麼事使你們上去，全都上到屋頂呢？","notes":[]},{"n":2,"t":"你這四處吶喊、大聲喧嘩的城、歡樂的邑啊，你被殺的並非被刀所殺，也不是因打仗陣亡。","notes":[]},{"n":3,"t":"你所有的官長一同奔逃，不用弓箭就被捆綁；你們即使逃往遠方，也要被找到，一同被捆綁。","notes":["「不用...捆綁」或譯「都為弓箭手所捆綁」。"]},{"n":4,"t":"因此我說：「不要看我，讓我痛哭吧！不要因我百姓的毀滅竭力安慰我。」","notes":["「我百姓」：原文直譯「我百姓的女兒」。"]},{"n":5,"t":"因為這是萬軍之主耶和華使異象谷混亂、踐踏、煩擾的日子；城牆被攻破，哀聲達到山上。","notes":[]},{"n":6,"t":"以攔提著箭袋，有戰車、士兵、騎兵；吉珥亮出盾牌，","notes":[]},{"n":7,"t":"你佳美的山谷遍佈戰車，騎兵排列在城門前。","notes":[]},{"n":8,"t":"他除掉猶大的防禦。那時，你指望森林庫裏的兵器。","notes":[]},{"n":9,"t":"你們看見大衛城缺口很多，就匯集下池的水；","notes":[]},{"n":10,"t":"你們數點耶路撒冷的房屋，拆毀房屋，用以修補城牆，","notes":[]},{"n":11,"t":"又在兩道城牆中間挖水池，用以盛舊池的水，卻不仰望成就這事的主，也不顧念從古時定這事的主。","notes":[]},{"n":12,"t":"當那日，萬軍之主耶和華使人哭泣哀號，頭上光禿，身披麻布。","notes":[]},{"n":13,"t":"看哪，人卻歡喜快樂，宰牛殺羊，吃肉喝酒：「讓我們吃吃喝喝吧！因為明天要死了。」","notes":[]},{"n":14,"t":"萬軍之耶和華開啟我的耳朵：「這罪孽直到你們死，斷不得赦免！」這是萬軍之主耶和華說的。","notes":[]},{"n":15,"t":"萬軍之主耶和華如此說：「你到舍伯那宮廷總管那裏去，說：","notes":[],"heads":["對舍伯那的警告"]},{"n":16,"t":"『你在這裏憑甚麼？你在這裏靠誰？竟敢在這裏為自己鑿墳墓，在高處為自己鑿墳墓，在巖石中為自己挖安身之所！","notes":[]},{"n":17,"t":"你這偉大的人，看哪，耶和華必將你用力拋出，將你緊緊纏裹。","notes":[]},{"n":18,"t":"他必將你捲成一團，好像拋球一樣拋向寬闊之地。你這主人家的羞辱啊，你必死在那裏，你引以為榮的戰車也毀在那裏。","notes":[]},{"n":19,"t":"我要革除你的官職，你必從原位被逐。』","notes":["「你..被逐」：原文是「他必將你逐出原位」。"]},{"n":20,"t":"「到那日，我要召希勒家的兒子─我的僕人以利亞敬來，","notes":[]},{"n":21,"t":"將你的外袍給他穿上，將你的腰帶給他繫緊，將你的政權交在他手中。他必作耶路撒冷居民和猶大家的父。","notes":[]},{"n":22,"t":"我要將大衛家的鑰匙放在他肩頭上。他開了，無人能關；他關了，無人能開。","notes":[]},{"n":23,"t":"我要使他立穩，像釘子釘在堅固的地方；他必成為他父家榮耀的寶座。","notes":[]},{"n":24,"t":"他父家所有的榮耀，連兒女帶子孫，有如杯碗、瓶罐的小器皿，都掛上他身上。","notes":[]},{"n":25,"t":"當那日，萬軍之耶和華說，釘在堅固處的釘子必挪移，被砍斷落地，掛在上面的各樣重擔都被切斷。這是耶和華說的。」","notes":[]}]},"23":{"heading":"論推羅的信息","verses":[{"n":1,"t":"論推羅的默示。哀號吧，他施的船隻！因為推羅已成廢墟，沒有房屋存留，他們從基提地來的時候，得到這個消息。","notes":["「他們...消息」或譯「沒有可進之路。這消息是從基提地得來的」。"]},{"n":2,"t":"沿海的居民，西頓的商家啊，當靜默無聲。你差人航海，","notes":["本節是根據死海古卷；原文是「沿海的居民，就是素來靠航海西頓的商家得豐盛的，你們當靜默無言。」"]},{"n":3,"t":"在大水之上，西曷河的糧食、尼羅河的莊稼是推羅的進項，它就成為列國的商埠。","notes":[]},{"n":4,"t":"西頓，你這海洋中的堡壘啊，應當羞愧，因為大海說：「我未經歷產痛，也沒有生產，未曾養育男孩，也沒有撫養女孩。」","notes":["「西頓...說」或譯「西頓哪，你當慚愧；因為大海說，就是海中的保障說」。"]},{"n":5,"t":"推羅的風聲傳到埃及時，他們為這風聲極其疼痛。","notes":[]},{"n":6,"t":"你們當渡到他施去，哀號吧，沿海的居民！","notes":[]},{"n":7,"t":"這就是你們那古老歡樂的城市嗎？它的腳曾帶人到遠方居住。","notes":[]},{"n":8,"t":"誰定意推羅有這樣的遭遇呢？它本是賜冠冕的，它的商家是王子，生意人是世上尊貴的人。","notes":[]},{"n":9,"t":"這是萬軍之耶和華所定的，為要貶抑一切榮耀的狂傲，使地上一切尊貴的人被藐視。","notes":[]},{"n":10,"t":"他施啊，你要像尼羅河一樣在你的地氾濫，不再有腰帶的束縛了。","notes":["「他施」：原文直譯「他施女子」。","本節七十士譯本是「去耕你田地吧！因船隻不再出離迦太基。」"]},{"n":11,"t":"耶和華已經向海伸手，震動列國；他出令對付迦南，要拆毀其中的堡壘。","notes":[]},{"n":12,"t":"他說：「受欺壓的少女西頓哪，你必不再歡樂。起來！渡到基提去，就是在那裏也不得安歇。","notes":["「少女西頓」：原文直譯「少女西頓女子」。"]},{"n":13,"t":"看哪，迦勒底人之地，這國民如今已不復存在。亞述人使它成為住曠野者的居所。他們建築自己的瞭望樓，拆毀它的宮殿，使它成為荒涼。","notes":["「它」指「推羅」；下同。"]},{"n":14,"t":"哀號吧，他施的船隻！因你們的堡壘已成廢墟。","notes":[]},{"n":15,"t":"到那時，推羅必被忘記七十年，就是一位君王的年數。七十年後，推羅的景況必如妓女之歌：","notes":[]},{"n":16,"t":"「你這被遺忘的妓女啊，帶著琴周遊城內，彈得美妙，唱許多歌，好讓人記得你。」","notes":[]},{"n":17,"t":"七十年後，耶和華必巡視推羅，使它再度獲利，與地面上的世界各國貿易。","notes":["「獲利」：原文是「得賣淫的賞金」；下同。","「貿易」：原文是「行淫」。"]},{"n":18,"t":"它的收益和獲利都要歸耶和華為聖，不再私自屯積存留；因為它的收益必歸給住在耶和華面前的人，使他們吃飽，穿華麗的衣服。","notes":[]}]},"24":{"heading":"耶和華要責罰世界","verses":[{"n":1,"t":"看哪，耶和華使地空虛，變為荒蕪，地面扭曲，居民四散。","notes":[]},{"n":2,"t":"那時，百姓如何，祭司也如何；僕人如何，主人也如何；婢女如何，主母也如何；買主如何，賣主也如何；放債的如何，借貸的也如何；債主如何，欠債的也如何。","notes":[]},{"n":3,"t":"地必全然空虛，盡都荒蕪，因為這話是耶和華說的。","notes":[]},{"n":4,"t":"大地悲哀凋零，世界敗落衰殘，地上居高位的人也沒落了。","notes":[]},{"n":5,"t":"地被其上的居民所污穢，因為他們犯了律法，廢了律例，背了永約。","notes":[]},{"n":6,"t":"所以，詛咒吞滅大地，住在其上的都有罪；地上的居民被火焚燒，剩下的人稀少。","notes":[]},{"n":7,"t":"新酒悲哀，葡萄樹凋殘，心中歡樂的都嘆息。","notes":[]},{"n":8,"t":"擊鼓之樂停止，狂歡者的喧嘩止住，彈琴之樂也停止了。","notes":[]},{"n":9,"t":"人不再飲酒唱歌，喝烈酒的，必以為苦。","notes":[]},{"n":10,"t":"荒涼的城拆毀了，各家關閉，無法進入。","notes":[]},{"n":11,"t":"有人在街上嚷著要酒喝，一切的喜樂變為昏暗，地上的歡樂全都消失。","notes":[]},{"n":12,"t":"城裏盡是荒涼，城門全都摧毀。","notes":[]},{"n":13,"t":"地上的萬民正像打過的橄欖樹，又如葡萄釀酒以後再去摘取，所剩無幾。","notes":[]},{"n":14,"t":"他們要高聲歡呼，從海那邊揚聲讚美耶和華的威嚴。","notes":[]},{"n":15,"t":"因此，你們要在日出之地榮耀耶和華，在眾海島榮耀耶和華－以色列神的名。","notes":[]},{"n":16,"t":"我們聽見從地極有人歌唱：「榮耀歸於公義的那一位！」我卻說：「我滅亡了！我滅亡了，我有禍了！詭詐的還在行詭詐，詭詐的還在大行詭詐。」","notes":[]},{"n":17,"t":"地上的居民哪，驚嚇、陷阱、羅網都臨到你；","notes":[]},{"n":18,"t":"躲過驚嚇之聲的墜入陷阱，逃離陷阱的又被羅網纏住，因為天上的窗戶都打開，地的根基也震動。","notes":[]},{"n":19,"t":"地必全然破壞，盡都崩裂，劇烈震動。","notes":[]},{"n":20,"t":"地要搖搖晃晃，好像醉酒的人，又如小屋子搖來搖去；罪過重壓其上，它就塌陷，不能復起。","notes":[]},{"n":21,"t":"到那日，耶和華在天上必懲罰天上的軍隊，在地上必懲罰地上的列王。","notes":[]},{"n":22,"t":"他們必被聚集，像囚犯困在牢裏，他們被關在監獄，多日之後便受懲罰。","notes":[]},{"n":23,"t":"那時，月亮要蒙羞，太陽要慚愧，因為萬軍之耶和華必在錫安山，在耶路撒冷作王，在他眾長老面前彰顯榮耀。","notes":[]}]},"25":{"heading":"一首讚美詩","verses":[{"n":1,"t":"耶和華啊，你是我的神，我要尊崇你，稱頌你的名。因為你以信實忠信行遠古所定奇妙的事。","notes":[]},{"n":2,"t":"你使城市變為廢墟，使堅固的城荒涼，使外邦人的城堡不再為城，永遠不再重建。","notes":[]},{"n":3,"t":"所以，強大的民必尊敬你，殘暴之國的城必敬畏你。","notes":[]},{"n":4,"t":"因為你是貧寒人的保障，貧窮人急難中的保障，暴風雨之避難所，炎熱地之陰涼處。當殘暴者盛氣凌人的時候，如暴風直吹牆壁，","notes":[]},{"n":5,"t":"如乾旱地的熱氣，你要制止外邦人的喧嚷，殘暴者的歌要停止，好像熱氣因雲的陰影而消失。","notes":[]},{"n":6,"t":"在這山上，萬軍之耶和華必為萬民擺設宴席，有肥甘與美酒，就是滿有骨髓的肥甘與精釀的美酒。","notes":[],"heads":["神為萬民擺設宴席"]},{"n":7,"t":"在這山上，他必吞滅那纏裹萬民的面紗和那遮蓋列國的遮蔽物。","notes":[]},{"n":8,"t":"他已吞滅死亡直到永遠。主耶和華必擦乾各人臉上的眼淚，在全地除去他百姓的羞辱；這是耶和華說的。","notes":[]},{"n":9,"t":"到那日，人必說：「看哪，這是我們的神，我們向來等候他，他必拯救我們。這是耶和華，我們向來等候他，我們必因他的救恩歡喜快樂。」","notes":[]},{"n":10,"t":"耶和華的手必按住這山，摩押人要被踐踏在他底下，好像乾草被踐踏在糞池裏。","notes":["「糞池」：原文另譯「糞池的水」。"],"heads":["神要懲罰摩押"]},{"n":11,"t":"他們要在其中伸展雙手，好像游泳的人伸手游泳。他們的手雖靈巧，耶和華卻使他們的驕傲降為卑下。","notes":[]},{"n":12,"t":"他使你城牆上堅固的碉堡傾倒，夷為平地，化為塵土。","notes":[]}]},"26":{"heading":"神使他的百姓得勝","verses":[{"n":1,"t":"當那日，在猶大地，人必唱這歌：「我們有堅固的城，耶和華賜救恩為城牆，為城郭。","notes":[]},{"n":2,"t":"你們要敞開城門，使守信的公義之民得以進入。","notes":[]},{"n":3,"t":"堅心倚賴你的，你必保守他十分平安，因為他倚靠你。","notes":[]},{"n":4,"t":"你們當倚靠耶和華，直到永遠，因為耶和華，耶和華是永遠的磐石。","notes":[]},{"n":5,"t":"他使居住高處的與高處的城市一同降為卑下，將城拆毀，夷為平地，化為塵土，","notes":[]},{"n":6,"t":"使它被腳踐踏，就是被困苦人和貧寒人的腳踐踏。」","notes":[]},{"n":7,"t":"義人的道是正直的，正直的主啊，你修平義人的路。","notes":[]},{"n":8,"t":"耶和華啊，我們在你行審判的路上等候你，我們心裏所渴慕的，就是你的名和你的稱號。","notes":["「等候你」：死海古卷和一些古譯本是「仰望」。","「稱號」：原文是「紀念」。"]},{"n":9,"t":"夜間，我的心渴想你，我裏面的靈切切尋求你。因為你在地上行審判的時候，世上的居民就學習公義。","notes":[]},{"n":10,"t":"惡人雖然領受恩惠，仍未學到公義。在正直之地，他行不義，也不看耶和華的威嚴。","notes":[]},{"n":11,"t":"耶和華啊，你的手高舉，他們不觀看；願他們觀看你為百姓發的熱心而羞愧，願火吞滅你的敵人。","notes":[]},{"n":12,"t":"耶和華啊，你必賞賜我們平安，因為我們所做的一切，都是你為我們成就的。","notes":[]},{"n":13,"t":"耶和華－我們的神啊，在你以外曾有別的主管轄我們，但我們惟獨稱揚你的名。","notes":[]},{"n":14,"t":"死去的不能再復活，陰魂不能再興起；你懲罰他們，使他們毀滅，他們的名號就全然消滅。","notes":["「名號」：原文是「紀念」。"]},{"n":15,"t":"耶和華啊，你增添國民，你增添國民，得了榮耀，又拓展國土的疆界。","notes":[]},{"n":16,"t":"耶和華啊，他們在急難中尋求你。你的管教臨到他們身上時，他們傾吐低聲的禱告。","notes":["本節有古卷是「耶和華啊，我們在急難中尋求你。你低聲的管教傾倒在我們身上。」"]},{"n":17,"t":"婦人懷孕，臨產疼痛，在痛苦之中喊叫；耶和華啊，我們在你面前也是如此。","notes":[]},{"n":18,"t":"我們曾懷孕，曾疼痛，所生產的竟像風一樣，並未帶給地上任何拯救；世上也未曾有居民生下來。","notes":["「並未...生下來」或譯「並未帶給地上任何勝利，也未曾打敗世上的居民」。"]},{"n":19,"t":"你的死人要復活，我的屍首要起來。睡在塵土裏的啊，要醒起歌唱！你的甘露好像晨曦的甘露，地要交出陰魂。","notes":["「睡...歌唱！」死海古卷和七十士譯本是「睡在塵土裏的必醒起歌唱。」","「晨曦」或譯「菜蔬」。"]},{"n":20,"t":"我的百姓啊，要進入內室，關上你的門，躲避片刻，等到憤怒過去。","notes":[],"heads":["審判和復興"]},{"n":21,"t":"因為，看哪，耶和華從他的居所出來，要懲罰地上居民的罪孽。地必露出其中的血，不再掩蓋被殺的人。","notes":[]}]},"27":{"heading":"","verses":[{"n":1,"t":"到那日，耶和華必用他堅硬銳利的大刀懲罰力威亞探，就是那爬得快的蛇，懲罰力威亞探，就是那彎彎曲曲的蛇，並殺死海裏的大魚。","notes":["「力威亞探」是音譯，一種海獸；下同。"]},{"n":2,"t":"當那日，你們要唱這美好葡萄園的歌：","notes":["「美好」是根據七十士譯本；原文是「出酒」。"]},{"n":3,"t":"「我－耶和華看守葡萄園，按時灌溉，晝夜看守，免得有人損害。","notes":[]},{"n":4,"t":"我心中不存憤怒。惟願在戰爭中我有荊棘和蒺藜，我就起步攻擊他，把他一同焚燒；","notes":[]},{"n":5,"t":"或者讓他緊靠我，以我為避難所，與我和好，與我和好。」","notes":[]},{"n":6,"t":"將來雅各要扎根，以色列要發芽開花，果實遍滿地面。","notes":[]},{"n":7,"t":"耶和華擊打以色列，豈像擊打那些擊打他們的人嗎？以色列被殺戮，豈像其他人所遭遇的殺戮嗎？","notes":[]},{"n":8,"t":"你驅趕他們，放逐他們，與他們相爭。在颳東風的日子，他以暴風趕逐他們。","notes":[]},{"n":9,"t":"所以，雅各的罪孽藉此得赦免，除罪的效果盡在乎此；他使祭壇的石頭變為粉碎的石灰，使亞舍拉和香壇不再立起。","notes":[]},{"n":10,"t":"因為堅固的城變為荒涼，成了被撇棄的居所，像曠野一樣；牛犢在那裏吃草，在那裏躺臥，吃盡其中的樹枝。","notes":[]},{"n":11,"t":"它的枝條一枯乾，就被折斷，婦女用以點火燃燒。因為這百姓蒙昧無知，所以，造他們的必不憐憫他們，造成他們的也不施恩給他們。","notes":[]},{"n":12,"t":"到那日， 以色列人哪，耶和華必像人打樹拾果一般，從大河的支流，直到埃及的溪谷，將你們一一收集。","notes":[]},{"n":13,"t":"當那日，號角大響；在亞述地將亡的，與被趕散至埃及地的，都要前來，在耶路撒冷聖山上敬拜耶和華。","notes":[]}]},"28":{"heading":"對北國的警告","verses":[{"n":1,"t":"禍哉！以法蓮酒徒高傲的冠冕，其榮美竟如花凋殘；他們在肥沃的山谷頂上，被酒擊敗。","notes":[]},{"n":2,"t":"看哪，主有一位大能大力者，如強烈的冰雹，如毀滅的暴風雨，如漲溢的洪水，他必親手將他們摔落在地。","notes":[]},{"n":3,"t":"以法蓮酒徒高傲的冠冕，必被腳踐踏；","notes":[]},{"n":4,"t":"那如凋殘之花的榮美，在肥沃的山谷頂上，必如夏令前初熟的無花果，讓看見的人注意，摘到手裏，隨即吞吃。","notes":[]},{"n":5,"t":"到那日，萬軍之耶和華必成為他餘民的榮冠華冕，","notes":[]},{"n":6,"t":"成為在位審判者的公平之靈，和城門口制敵的力量。","notes":[]},{"n":7,"t":"這些人也因酒搖晃，因烈酒東倒西歪。祭司和先知因烈酒搖晃，被酒所困，因烈酒東倒西歪。他們錯解默示，審判時不分是非。","notes":[],"heads":["以賽亞和猶大酒醉的先知"]},{"n":8,"t":"筵席上都滿了嘔吐的污穢，沒有一處乾淨。","notes":[]},{"n":9,"t":"「他要將知識指教誰呢？要向誰闡明信息呢？是向那些剛斷奶的，離開母親胸懷的嗎？","notes":[]},{"n":10,"t":"因為他咕噥咕噥，咕噥咕噥，嘮嘮叨叨，嘮嘮叨叨，這裏一點，那裏一點。」","notes":[]},{"n":11,"t":"耶和華要藉嘲弄的嘴唇和外邦人的舌頭，向這百姓說話。","notes":[]},{"n":12,"t":"他曾對他們說：「這是安歇之所，你們要使疲乏的人得安歇，這是歇息之處。」他們卻不肯聽。","notes":[]},{"n":13,"t":"耶和華的話對他們而言是「咕噥咕噥，咕噥咕噥，嘮嘮叨叨， 嘮嘮叨叨，這裏一點，那裏一點」；以致他們往前行，卻後仰跌倒，甚至跌傷，落入陷阱，被抓住了。","notes":[]},{"n":14,"t":"因此，你們這些傲慢的人，就是管轄住耶路撒冷這百姓的，要聽耶和華的話。","notes":[],"heads":["錫安的房角石"]},{"n":15,"t":"你們曾說：「我們已與死亡立約，與陰間結盟，不可擋的鞭子揮過時，必不臨到我們；因我們以謊言為避難所，靠虛假來藏身」；","notes":[]},{"n":16,"t":"所以，主耶和華如此說：「看哪，我在錫安放一塊石頭作為根基，是衡量的石頭，是寶貴的房角石，穩固的根基；信靠他的人必不致驚恐。","notes":[]},{"n":17,"t":"我以公平為準繩，以公義為鉛垂線；冰雹必沖去謊言的避難所，大水必漫過藏身之處。","notes":[]},{"n":18,"t":"你們與死亡所立的約必廢除，與陰間所結的盟不得堅立；不可擋的鞭子揮過時，你們必被踐踏。","notes":[]},{"n":19,"t":"每逢它揮來，必將你們擄去；每早晨它必揮過，白晝黑夜都是如此。明白這信息的都必驚恐。」","notes":[]},{"n":20,"t":"床榻短，人不能伸展；被子窄，人無從裹身。","notes":[]},{"n":21,"t":"耶和華必興起，像在毗拉心山，他必發怒，如在基遍谷；為要做成他的工，就是非常的工，成就他的事，就是奇異的事。","notes":[]},{"n":22,"t":"現在你們不可傲慢，免得捆綁你們的繩索更結實，因為我從萬軍之主耶和華那裏聽見，在全地施行滅絕的事已定。","notes":[]},{"n":23,"t":"你們當側耳聽我的聲音，留心聽我的言語。","notes":[],"heads":["神的智慧"]},{"n":24,"t":"那為撒種而耕地的會不停地耕地，鬆土，耙地嗎？","notes":[]},{"n":25,"t":"他剷平了地面，豈不就種小茴香，播種大茴香，按行列種小麥，在定處種大麥，在田邊種粗麥嗎？","notes":[]},{"n":26,"t":"他的神教導他，指導他合宜的方法。","notes":[]},{"n":27,"t":"原來打小茴香，不用尖利的器具，軋大茴香，也不是用車輪；卻要用杖打小茴香，用棍打大茴香。","notes":[]},{"n":28,"t":"穀要打，但不能持續地搗，用車輪和馬軋，卻不軋碎它。","notes":[]},{"n":29,"t":"這也是出於萬軍之耶和華，他的謀略奇妙，他的智慧廣大。","notes":[]}]},"29":{"heading":"耶路撒冷受圍困","verses":[{"n":1,"t":"禍哉！亞利伊勒，亞利伊勒，大衛安營的城，任憑你年復一年，節期照常循環，","notes":["「亞利伊勒」：代表耶路撒冷，意思是「祭壇」；下同。"]},{"n":2,"t":"我卻要使亞利伊勒遭難；它必悲傷哀號，它對我是亞利伊勒。","notes":[]},{"n":3,"t":"我必四圍安營攻擊你，築臺圍困你，堆壘攻擊你。","notes":[]},{"n":4,"t":"你必敗落，從地裏說話，你的言語細微出於塵埃。你的聲音必像那招魂者的聲音出於地，你的言語呢喃出於塵埃。","notes":[]},{"n":5,"t":"你那成群的陌生人要像細塵，暴民要像吹起的糠秕；這事必頃刻之間忽然臨到。","notes":["「你那成群的陌生人」：死海古卷是「你那成群驕傲的人」；七十士譯本是「不敬虔的人的財富」。"]},{"n":6,"t":"萬軍之耶和華必使雷轟、地震、巨響、旋風、暴風，並吞滅的火焰臨到它。","notes":[]},{"n":7,"t":"那時，攻擊亞利伊勒列國的軍隊，與一切攻擊亞利伊勒和它城堡，並帶給它患難的，必如夢，如夜間的異象；","notes":[]},{"n":8,"t":"又像飢餓的人在夢中吃飯，醒了仍覺飢腸轆轆；或像口渴的人在夢中喝水，醒了仍覺發昏，心裏想喝。攻擊錫安山列國的軍隊也必如此。","notes":[]},{"n":9,"t":"你們等候驚奇吧！你們沉迷宴樂吧！他們醉了，卻非因酒；東倒西歪，卻非因烈酒。","notes":[],"heads":["無人聽警告"]},{"n":10,"t":"因為耶和華將沉睡的靈澆灌你們，遮住你們的眼，眼就是先知，覆蓋你們的頭，頭就是先見。","notes":[]},{"n":11,"t":"所有的默示，在你們看來都如封住的書卷，人將這書卷交給識字的人，說：「請念吧！」他說：「我不能念，因為它封住了。」","notes":[]},{"n":12,"t":"又將這書卷交給不識字的人，說：「請念吧！」他說：「我不識字。」","notes":[]},{"n":13,"t":"主說：「因這百姓以口親近我，用嘴唇尊敬我，心卻遠離我；他們敬畏我，不過是領受前人的命令。","notes":[]},{"n":14,"t":"所以，看哪，我要在這百姓中行奇妙的事，就是奇妙又奇妙的事。他們智慧人的智慧必然消滅，聰明人的聰明必然消失。」","notes":[]},{"n":15,"t":"禍哉！那些向耶和華深藏謀略的，他們在暗中行事，說：「有誰看見我們呢？誰會注意我們呢？」","notes":[]},{"n":16,"t":"你們把事情顛倒了，豈可看陶匠如陶土呢？受造物豈可論創造者說，「他並沒有造我」？製成物豈可論製作者說，「他根本不懂」？","notes":[]},{"n":17,"t":"黎巴嫩變為田園，田園看似森林，不是只需要一些時間嗎？","notes":[],"heads":["將來的希望"]},{"n":18,"t":"那時，聾子必聽見這書上的話；盲人的眼必從迷矇黑暗中看見。","notes":[]},{"n":19,"t":"困苦的人必因耶和華增添歡喜，人間貧窮的必因以色列的聖者快樂。","notes":[]},{"n":20,"t":"因為殘暴的人歸於無有，傲慢的人已經滅絕，一切存心作惡的都被剪除。","notes":[]},{"n":21,"t":"他們憑一句話定一個人有罪，為在城門口斷是非的設下羅網，又用虛無的事屈枉義人。","notes":[]},{"n":22,"t":"所以，救贖亞伯拉罕的耶和華論到雅各家時如此說：「雅各必不再羞愧，面容也不再變色。","notes":[]},{"n":23,"t":"當他的兒女看見我的手在他們當中所成就的事情，他們就必尊我的名為聖，尊雅各的聖者為聖，他們必敬畏以色列的神。","notes":["「當...事情」或譯「但他看見他的眾子，就是我手的工作在他那裏」。"]},{"n":24,"t":"心中迷糊的必明白，發怨言的必領受訓誨。」","notes":[]}]},"30":{"heading":"跟埃及訂立無用的條約","verses":[{"n":1,"t":"耶和華說：「禍哉！這悖逆的兒女。他們同謀，卻不出於我，結盟，卻不出於我的靈，以致罪上加罪。","notes":[]},{"n":2,"t":"他們沒有尋求我的指示，就起身下埃及去，要倚靠法老的庇護堅固自己，並投在埃及的蔭下。","notes":[]},{"n":3,"t":"但法老的庇護反成為你們的羞辱；你們投在埃及蔭下，反使你們慚愧。","notes":[]},{"n":4,"t":"他們的領袖已在瑣安，他們的使臣到了哈內斯。","notes":[]},{"n":5,"t":"他們必因那無益於他們的民蒙羞；那民並非幫助，也非有益，只帶來羞恥和凌辱。」","notes":[]},{"n":6,"t":"論尼革夫牲畜的默示。他們將財物馱在驢背上，將寶物馱在駱駝的背脊，經過艱難困苦之地，就是母獅、公獅、毒蛇、飛蛇之地，往那無益於他們的民那裏去。","notes":[]},{"n":7,"t":"埃及的幫助是徒然的，因此，我稱它為「毫不中用的拉哈伯」。","notes":["「拉哈伯」是神話故事中的大海怪。"]},{"n":8,"t":"現在你要去，在他們面前將這話刻在版上，寫在書上，以便流傳後世，直到永永遠遠。","notes":["「直到永永遠遠」：有古卷是「作永遠的見證」。"],"heads":["不順服的百姓"]},{"n":9,"t":"因為他們是悖逆的百姓、說謊的兒女，是不肯聽從耶和華訓誨的兒女。","notes":[]},{"n":10,"t":"他們對先見說：「不要再看了」；對先知說：「不要向我們預言正直的事；要對我們說好聽的話，預言虛幻的事。","notes":[]},{"n":11,"t":"要離開這道，偏離這路，不要在我們面前再提說以色列的聖者。」","notes":[]},{"n":12,"t":"所以，以色列的聖者如此說：「因你們藐視這話，倚賴欺壓和詭詐，以此為可靠，","notes":[]},{"n":13,"t":"因此，這罪孽在你們身上，好像高牆裏有凸起的裂縫，頃刻之間忽然坍下來了；","notes":[]},{"n":14,"t":"它被砸碎，好像把陶匠的瓦器摔碎，毫不顧惜，甚至在碎塊中找不到一片可用以從爐內取火，或從池中舀水。」","notes":[]},{"n":15,"t":"主耶和華－以色列的聖者如此說：「你們得救在乎歸回安息，得力在乎平靜安穩。」你們卻是不肯，","notes":[]},{"n":16,"t":"你們說：「不然，我們要騎馬奔走」，所以你們必然奔走。你們又說：「我們要騎快馬」，所以追趕你們的，也必飛快。","notes":[]},{"n":17,"t":"一人叱喝，令千人逃跑，五人叱喝，你們都逃跑；以致剩下的如山頂的旗杆，如山岡上的大旗。","notes":[]},{"n":18,"t":"耶和華必然等候，要施恩給你們；必然興起，好憐憫你們。因為耶和華是公平的神；凡等候他的都是有福的！","notes":[],"heads":["神要賜福給他的子民"]},{"n":19,"t":"住在錫安、居於耶路撒冷的百姓啊，你必不再哭泣。主必因你哀求的聲音施恩給你，他聽見的時候就必應允你。","notes":[]},{"n":20,"t":"主雖然以艱難給你當餅，以困苦給你當水，你的教師卻不再隱藏，你的眼睛必看見你的教師。","notes":[]},{"n":21,"t":"你或向左或向右，必聽見後邊有聲音說：「這是正路，要行在其間。」","notes":[]},{"n":22,"t":"你要玷污那雕刻偶像所包的銀子和鑄造偶像所鍍的金子。你要拋棄它們，如拋棄污穢之物；對偶像說：「去吧！」","notes":[]},{"n":23,"t":"你撒種在地裏，主必降雨在其上，使地所出的糧食肥美豐盛。那時，你的牲畜必在遼闊的草場吃草。","notes":[]},{"n":24,"t":"耕地的牛和驢必吃加鹽的飼料，是用鏟子和杈子揚淨的。","notes":[]},{"n":25,"t":"在大行殺戮的日子，城樓倒塌的時候，高山峻嶺必有川河湧流。","notes":[]},{"n":26,"t":"當耶和華包紮他百姓的傷口，醫治他所擊打傷痕的日子，月光必像日光，日光必加七倍，像七日的光一樣。","notes":[]},{"n":27,"t":"看哪，耶和華的名從遠方來，他的怒氣燒起，濃煙上騰。他的嘴唇滿有憤恨，他的舌頭像吞滅的火。","notes":[],"heads":["神要懲罰亞述"]},{"n":28,"t":"他的氣息如漲溢的河水，直漲到頸項，要用毀滅的篩網篩淨列國，並在眾民口中安放導錯方向的嚼環。","notes":[]},{"n":29,"t":"你們必唱歌，像守聖節的夜間一樣；並且心中喜樂，像人吹笛，來到耶和華的山，到以色列的磐石那裏。","notes":[]},{"n":30,"t":"耶和華必使人聽見他威嚴的聲音，又以極大的憤怒、吞滅的火焰、雷雨、暴風和像石塊的冰雹，使人看見他降罰的膀臂。","notes":[]},{"n":31,"t":"亞述必因耶和華的聲音驚惶，耶和華必用杖擊打它。","notes":[]},{"n":32,"t":"耶和華必將定規要打的杖加在它身上；每打一下，都必配合擊鼓彈琴的節奏。打仗時，耶和華必振臂與它交戰。","notes":["「定規要打」：有古卷是「懲罰」。"]},{"n":33,"t":"原來陀斐特早已預備好了，是為君王預備的；又深又寬，堆滿了火和木柴；耶和華的氣息猶如一股硫磺使它燃起。","notes":["「陀斐特」是焚燒的地方，在耶路撒冷南方欣嫩子谷的東南端。"]}]},"31":{"heading":"神要保護耶路撒冷","verses":[{"n":1,"t":"禍哉！那些下埃及求幫助的，他們仰賴馬匹，倚靠甚多的戰車，並倚靠強壯的騎兵，卻不仰望以色列的聖者，也不求問耶和華。","notes":[]},{"n":2,"t":"其實，耶和華有智慧，他降災禍，並不撤回自己的話，卻要興起攻擊作惡之家，攻擊那幫助人作惡的。","notes":[]},{"n":3,"t":"埃及人不過是人，並非神，他們的馬不過是血肉，並不是靈。耶和華一伸手，那幫助人的必絆跌，受幫助的也必跌倒，都一同滅亡。","notes":[]},{"n":4,"t":"耶和華對我如此說，獅子和少壯獅子為獵物而咆哮，許多牧人被召來攻擊牠，牠總不因他們的聲音驚惶，也不因他們的喧嚷退縮；萬軍之耶和華也必如此降臨在錫安的大小山岡上爭戰。","notes":[]},{"n":5,"t":"雀鳥盤旋護衛，萬軍之耶和華也必照樣保護耶路撒冷；他必保護拯救，必逾越而搭救。","notes":[]},{"n":6,"t":"以色列人哪，要歸向你們嚴重悖逆的那一位！","notes":[]},{"n":7,"t":"到那日，你們各人要拋棄親手所造、陷自己於罪中的金偶像和銀偶像。","notes":[]},{"n":8,"t":"亞述必倒在刀下，並非人的刀；有刀要將它吞滅，並非人的刀。它要逃避這刀，它的年輕人必做苦工。","notes":[]},{"n":9,"t":"它的磐石必因驚嚇而消失，它的領袖必因大旗驚惶；這是那有火在錫安、有爐在耶路撒冷的耶和華說的。","notes":[]}]},"32":{"heading":"公正的君王","verses":[{"n":1,"t":"看哪，必有一位君王憑公義執政，必有王子藉公平掌權。","notes":[]},{"n":2,"t":"必有一人如避風港，如暴風雨的藏身處；如乾旱地的溪流，又如乾燥地巨石的陰影。","notes":[]},{"n":3,"t":"看的人眼睛不再昏花，聽的人耳朵必留心聽。","notes":[]},{"n":4,"t":"性急的人懂得分辨，口吃的人說話流暢。","notes":[]},{"n":5,"t":"愚頑人不再稱為君子，流氓不再稱為紳士。","notes":[]},{"n":6,"t":"因為愚頑人必說愚妄的話，他的心作惡，行褻瀆的事，傳播惡言攻擊耶和華，使飢餓的人仍然飢餓，口渴的人無水可喝。","notes":["「作惡」：死海古卷是「謀惡」。"]},{"n":7,"t":"流氓的手段邪惡，他圖謀惡計，用謊言毀滅困苦人；貧窮人講求公理時，他也是如此行。","notes":[]},{"n":8,"t":"君子卻圖謀高尚的事，他必因高尚的事站立得穩。","notes":[]},{"n":9,"t":"安逸的婦女啊，起來聽我的聲音！無慮的女子啊，側耳聽我的言語！","notes":[],"heads":["審判和復興"]},{"n":10,"t":"無慮的女子啊，再過一年，你們必顫慄，因為無葡萄可摘，也無果實可收。","notes":[]},{"n":11,"t":"安逸的婦女啊，要戰兢；無慮的女子啊，要顫慄，要脫去衣服，赤著身體，腰束麻布。","notes":[]},{"n":12,"t":"你們要為美好的田地和多結果子的葡萄樹捶胸哀哭。","notes":[]},{"n":13,"t":"刺草和荊棘要長在我百姓的田地上，長在歡樂城中一切快樂家園上。","notes":[]},{"n":14,"t":"宮殿必被撇下，繁華的城必被拋棄，堡壘和瞭望樓永為洞穴，成為野驢的樂土，羊群的草場。","notes":[]},{"n":15,"t":"等到聖靈從高處澆灌我們，曠野將變為田園，田園看似森林。","notes":[]},{"n":16,"t":"公平要居住在曠野，公義要安歇在田園。","notes":[]},{"n":17,"t":"公義的果實是平安，公義的效果是平靜和安穩，直到永遠。","notes":[]},{"n":18,"t":"我的百姓要住在平安的居所，安穩的住處，寧靜的安歇之地。","notes":[]},{"n":19,"t":"雖有冰雹擊倒樹林，城也夷為平地；","notes":[]},{"n":20,"t":"然而你們在水邊撒種，牧放牛驢的有福了！","notes":[]}]},"33":{"heading":"求救的祈禱","verses":[{"n":1,"t":"禍哉！你這未遭毀滅而毀滅人的人，人未以詭詐待你而你以詭詐待人的人！等你行完了毀滅，自己必被毀滅；你行完了詭詐，人必以詭詐待你。","notes":[]},{"n":2,"t":"耶和華啊，求你施恩給我們，我們等候你。求你每早晨作我們的膀臂，遭難時作我們的拯救。","notes":[]},{"n":3,"t":"轟然之聲一發出，萬民就奔逃；你一興起，列國就四散。","notes":["「興起」：死海古卷是「安靜」或「吼叫」。"]},{"n":4,"t":"你們的擄物必被斂盡，有如螞蚱斂盡禾稼；人為擄物奔走，宛如蝗蟲蹦跳。","notes":[]},{"n":5,"t":"耶和華受尊崇，居高處，使公平和公義充滿錫安。","notes":[]},{"n":6,"t":"他是你這世代安定的力量，豐盛的救恩、智慧和知識；敬畏耶和華是錫安的至寶。","notes":[]},{"n":7,"t":"看哪，他們的英雄在外面哀號，求和的使臣在痛哭。","notes":["「看哪...哀號」：有古卷是「我看見他們，他們在外面哀號」；原文另譯「亞利伊勒（參賽29．1）在外面哀號」。"]},{"n":8,"t":"大路荒涼，行人止息；盟約撕毀，見證被棄，人也不受尊重。","notes":["「見證」是根據死海古卷；原文是「城鎮」。"]},{"n":9,"t":"大地悲哀衰殘，黎巴嫩羞愧且枯乾，沙崙好像曠野，巴珊和迦密必凋殘。","notes":[]},{"n":10,"t":"耶和華說：「現在我要興起，要高升，要受尊崇。","notes":[],"heads":["耶和華對敵人的警告"]},{"n":11,"t":"你們懷的是糠秕，生的是碎稭；你們的氣息如火吞滅自己。","notes":[]},{"n":12,"t":"萬民必像燒著的石灰，又如斬斷的荊棘，在火裏燃燒。」","notes":[]},{"n":13,"t":"你們遠方的人，當聽我所做的事；你們近處的人，當承認我的大能。","notes":[]},{"n":14,"t":"錫安的罪人都懼怕，戰兢抓住不敬虔的人。我們中間有誰能與吞噬的火同住？我們中間有誰能與不滅的火共存呢？","notes":[]},{"n":15,"t":"那行事公義、說話正直、憎惡欺壓所得之財、搖手不受賄賂、掩耳不聽流血的計謀、閉眼不看邪惡之事的，","notes":[]},{"n":16,"t":"這人必居高處，他的保障是磐石的堡壘，必有糧食賜給他，飲水也不致斷絕。","notes":[]},{"n":17,"t":"你必親眼看見君王的榮美，看見遼闊之地。","notes":[],"heads":["光榮的將來"]},{"n":18,"t":"你的心必回想那些恐怖的事：「那數算的人在哪裏？秤重的人在哪裏？數點城樓的又在哪裏呢？」","notes":[]},{"n":19,"t":"你必不再看見那兇暴的民，他們嘴唇說艱澀的言語，難以理解；舌頭結巴，說無意義的話。","notes":[]},{"n":20,"t":"你要注視錫安，我們守聖節的城！你必親眼看見耶路撒冷成為安靜的居所，成為不挪移的帳幕，橛子永不拔出，繩索一根也不折斷。","notes":[]},{"n":21,"t":"在那裏，威嚴的耶和華對我們是寬闊的江河，其中必沒有搖槳的小船來往，也沒有巨大的船舶經過。","notes":[]},{"n":22,"t":"耶和華是審判我們的，耶和華為我們設立律法；耶和華是我們的君王，他必拯救我們。","notes":[]},{"n":23,"t":"船上的繩索鬆開，不能穩住桅杆，也無法揚起船帆。那時許多擄物被瓜分，連瘸腿的也能奪走掠物。","notes":[]},{"n":24,"t":"城內的居民無人說：「我病了」；城裏居住的百姓，罪孽都蒙赦免。","notes":[]}]},"34":{"heading":"神要懲罰仇敵","verses":[{"n":1,"t":"列國啊，要近前來聽！萬民哪，要側耳而聽！全地和其上所充滿的，世界和其中所出的，都應當聽！","notes":[]},{"n":2,"t":"因為耶和華向列國發怒，向他們的全軍發烈怒，要將他們滅盡，任人殺戮。","notes":[]},{"n":3,"t":"被殺的人必被拋棄，屍首臭氣上騰，諸山為他們的血所融化。","notes":[]},{"n":4,"t":"天上萬象都要朽壞，天被捲起，有如書卷，其上的萬象盡都衰殘；如葡萄樹的葉子凋落，又如無花果樹枯萎一樣。","notes":[]},{"n":5,"t":"因為我的刀在天上將要顯現；看哪，這刀臨到以東和我所詛咒的民，要施行審判。","notes":["「將要顯現」是根據死海古卷；原文是「已經喝足」。"]},{"n":6,"t":"耶和華的刀沾滿了血，是用油脂和羔羊、公山羊的血，並公綿羊腎上的油脂滋潤的；因為在波斯拉有祭物獻給耶和華，在以東地有大屠殺。","notes":[]},{"n":7,"t":"野牛與他們一起倒下，牛犢和壯牛也一同倒下。他們的地被血染遍，他們的塵土因油脂肥潤。","notes":[]},{"n":8,"t":"這是耶和華報仇之日，為錫安伸冤的報應之年。","notes":[]},{"n":9,"t":"它的河水要變為柏油，塵埃變為硫磺，大地成為燃燒的柏油，","notes":[]},{"n":10,"t":"晝夜總不熄滅，它的煙永遠上騰，必世世代代成為荒廢，永永遠遠無人經過。","notes":[]},{"n":11,"t":"鵜鶘、豪豬要得它為業，貓頭鷹、烏鴉要住在其間。耶和華必將空虛的準繩、混沌的石垂線，拉在以東之上。","notes":[]},{"n":12,"t":"人必宣稱那裏沒有王國，它的貴族和所有領袖都歸於無有。","notes":[]},{"n":13,"t":"以東的宮殿要長出荊棘，城堡要生長蒺藜和刺草；成為野狗的住處，鴕鳥的居所。","notes":[]},{"n":14,"t":"野獸要和土狼相遇，山羊鬼魔要與同伴對唱，莉莉絲必在那裏棲身，為自己尋找安歇之處。","notes":["「莉莉絲」是音譯，中東的雌性鬼怪；或譯「夜間的怪物」。"]},{"n":15,"t":"箭頭蛇要在那裏做窩，下蛋，孵蛋，並招聚幼蛇在其保護之下；鷂鷹也與伴侶聚集在那裏。","notes":[]},{"n":16,"t":"你們要查考並誦讀耶和華的書；這些現象必然存在，沒有一樣動物缺少伴侶。因為是他，藉著我的口吩咐，他的靈將牠們聚集。","notes":["「我的口」：死海古卷是「他的口」。"]},{"n":17,"t":"他為牠們抽籤，親手用準繩為牠們分地；直到牠們永遠得地為業，世世代代住在其間。","notes":[]}]},"35":{"heading":"神聖之路","verses":[{"n":1,"t":"曠野和乾旱之地必然歡喜，沙漠也必快樂；又如玫瑰綻放，","notes":[]},{"n":2,"t":"朵朵繁茂，其樂融融，而且歡呼。黎巴嫩的榮耀，並迦密與沙崙的華美，必賜給它。人要看見耶和華的榮耀，看見我們神的榮美。","notes":[]},{"n":3,"t":"你們要使軟弱的手強壯，使無力的膝蓋穩固；","notes":[]},{"n":4,"t":"對心裏焦急的人說：「要剛強，不要懼怕。看哪，你們的神要來施報，要施行極大的報應，他必來拯救你們。」","notes":[]},{"n":5,"t":"那時，盲人的眼必睜開，聾子的耳必開通。","notes":[]},{"n":6,"t":"那時，瘸子必跳躍如鹿，啞巴的舌頭必歡呼。在曠野有水噴出，在沙漠有江河湧流。","notes":[]},{"n":7,"t":"火熱之地要變為水池，乾渴之地要變為泉源。野狗躺臥休息之處必長出青草、蘆葦和蒲草。","notes":[]},{"n":8,"t":"在那裏必有一條大道，就是一條路，稱為聖路。污穢的人不得經過，是專為走路的人預備的，愚昧的人也不會迷路。","notes":["死海古卷沒有「就是一條路」。","「走路的人」或譯「贖民」。"]},{"n":9,"t":"在那裏沒有獅子，猛獸也不經過；在那裏牠們未現蹤跡，只有救贖的民在那裏行走。","notes":[]},{"n":10,"t":"耶和華救贖的民必歸回，歌唱來到錫安；永遠的快樂必歸到他們頭上，他們必得著歡喜快樂，憂傷嘆息盡都逃避。","notes":[]}]},"36":{"heading":"亞述人威脅耶路撒冷","verses":[{"n":1,"t":"希西家王十四年，亞述王西拿基立上來攻擊猶大的一切堅固的城，將城攻取。","notes":[]},{"n":2,"t":"亞述王從拉吉差遣將軍率領大軍前往耶路撒冷，到希西家王那裏去。將軍站在上池的水溝旁，在往漂布地的大路上。","notes":["「將軍」：原文是亞述的官職「拉伯‧沙基」，司令官；下同。"]},{"n":3,"t":"希勒家的兒子以利亞敬宮廷總管、舍伯那書記和亞薩的兒子約亞史官，出來見他。","notes":[]},{"n":4,"t":"將軍對他們說：「你們去告訴希西家，大王亞述王如此說：『你倚賴甚麼，讓你如此自信滿滿？","notes":[]},{"n":5,"t":"我說，你有打仗的計謀和能力，我看不過是空話。你到底倚靠誰，竟敢背叛我呢？","notes":["「我說」：有古卷是「你說」。"]},{"n":6,"t":"看哪，你所倚靠的埃及是那斷裂的葦杖，人若倚靠這杖，它就刺進他的手，穿透它。埃及王法老向所有倚靠他的人都是這樣。","notes":[]},{"n":7,"t":"你若對我說：我們倚靠耶和華－我們的神，希西家豈不是將神的丘壇和祭壇廢去，且吩咐猶大和耶路撒冷的人說：你們只當在這一個壇前敬拜嗎？","notes":[]},{"n":8,"t":"現在你與我主亞述王打賭，我給你兩千匹馬，看你能否派得出騎士來騎牠們。","notes":[]},{"n":9,"t":"若不然，怎能使我主臣僕中最小的一個軍官轉臉而逃呢？你難道要倚靠埃及的戰車和騎兵嗎？","notes":[]},{"n":10,"t":"現在我上來攻擊毀滅這地，豈不是出於耶和華嗎？耶和華吩咐我說，你上去攻擊這地，毀滅它吧！』」","notes":[]},{"n":11,"t":"以利亞敬、舍伯那、約亞對將軍說：「求你用亞蘭話對僕人說，因為我們聽得懂；不要用猶大話對我們說，免得傳到城牆上百姓的耳中。」","notes":[]},{"n":12,"t":"將軍說：「我主差遣我來，豈是單對你和你的主人說這些話嗎？不也是對這些坐在城牆上，要與你們一同吃自己糞、喝自己尿的人說的嗎？」","notes":[]},{"n":13,"t":"於是亞述將軍站著，用猶大話大聲喊著說：「你們當聽大王亞述王的話，","notes":[]},{"n":14,"t":"王如此說：『你們不要被希西家欺哄了，因他不能拯救你們。","notes":[]},{"n":15,"t":"不要聽憑希西家說服你們倚靠耶和華，他說，耶和華必要拯救我們，這城必不交在亞述王的手中。』","notes":[]},{"n":16,"t":"你們不要聽希西家的話！因亞述王如此說：『你們要與我講和，出來投降，各人就可以吃自己葡萄樹和無花果樹的果子，喝自己井裏的水，","notes":[]},{"n":17,"t":"等我來領你們到一個地方，與你們本地一樣，就是有五穀和新酒之地，有糧食和葡萄園之地。","notes":[]},{"n":18,"t":"恐怕希西家誤導你們說，耶和華必拯救我們。列國的神明有哪一個曾救它本國脫離亞述王的手呢？","notes":[]},{"n":19,"t":"哈馬和亞珥拔的神明在哪裏呢？西法瓦音的神明在哪裏呢？它們曾救撒瑪利亞脫離我的手嗎？","notes":[]},{"n":20,"t":"這些國的神明有誰曾救自己的國家脫離我的手呢？難道耶和華能救耶路撒冷脫離我的手嗎？』」","notes":[]},{"n":21,"t":"百姓靜默不言，一句不答，因為希西家王曾吩咐說：「不要回答他。」","notes":[]},{"n":22,"t":"當下希勒家的兒子以利亞敬宮廷總管、舍伯那書記，和亞薩的兒子約亞史官都撕裂衣服，來到希西家那裏，將亞述將軍的話告訴他。","notes":[]}]},"37":{"heading":"國王差人徵求以賽亞的意見","verses":[{"n":1,"t":"希西家王聽見了，就撕裂衣服，披上麻衣，進了耶和華的殿。","notes":[]},{"n":2,"t":"他差遣以利亞敬宮廷總管和舍伯那書記，並祭司中年長的，都披上麻衣，到亞摩斯的兒子以賽亞先知那裏去。","notes":[]},{"n":3,"t":"他們對他說：「希西家如此說：『今日是急難、懲罰、凌辱的日子，就如嬰孩快要出生，卻沒有力氣生產。","notes":[]},{"n":4,"t":"或許耶和華－你的神聽見亞述將軍的話，就是他主人亞述王差他來辱罵永生神的話，耶和華－你的神就斥責所聽見的這些話。求你為倖存的餘民揚聲禱告。』」","notes":[]},{"n":5,"t":"希西家王的臣僕就來到以賽亞那裏。","notes":[]},{"n":6,"t":"以賽亞對他們說：「要對你們的主人這樣說，耶和華如此說：『你聽見亞述王的僕人褻瀆我的話，不要懼怕。","notes":[]},{"n":7,"t":"看哪，因為我必驚動他的心，他要聽見風聲就歸回本地，在那裏我必使他倒在刀下。』」","notes":["「驚動他的心」：原文是「使靈進入他裏面」。"]},{"n":8,"t":"亞述將軍聽見亞述王已拔營離開拉吉，就啟程返回，正遇見亞述王去攻打立拿。","notes":[],"heads":["亞述王再來威脅"]},{"n":9,"t":"亞述王聽見有人談論古實王特哈加說：「他出來要與你爭戰。」亞述王一聽見，就差使者去見希西家，說：","notes":[]},{"n":10,"t":"「你們要對猶大王希西家如此說：『不要聽你所倚靠的神欺哄你說：耶路撒冷必不交在亞述王的手中。","notes":[]},{"n":11,"t":"看哪，你總聽說亞述諸王向列國所行的是盡行滅絕，難道你能倖免嗎？","notes":[]},{"n":12,"t":"我祖先所毀滅的，就是歌散、哈蘭、利色和提‧拉撒的伊甸人；這些國的神明何曾拯救他們呢？","notes":[]},{"n":13,"t":"哈馬的王，亞珥拔的王，西法瓦音城的王，希拿和以瓦的王，都在哪裏呢？』」","notes":[]},{"n":14,"t":"希西家從使者手裏接過書信，看完了，就上耶和華的殿，在耶和華面前展開書信。","notes":[]},{"n":15,"t":"希西家向耶和華禱告說：","notes":[]},{"n":16,"t":"「坐在基路伯之上萬軍之耶和華－以色列的神啊，你，惟有你是地上萬國的神，你創造了天和地。","notes":[]},{"n":17,"t":"耶和華啊，求你側耳而聽；耶和華啊，求你睜眼而看，聽西拿基立差遣使者辱罵永生神的一切話。","notes":[]},{"n":18,"t":"耶和華啊，亞述諸王果然使列國和列國之地變為荒蕪，","notes":[]},{"n":19,"t":"將列國的神明扔在火裏，因為它們本不是神明，是人手所造的，是木頭、石頭，所以被滅絕了。","notes":[]},{"n":20,"t":"耶和華－我們的神啊，現在求你救我們脫離亞述王的手，使地上萬國都知道惟有你是耶和華。」","notes":[]},{"n":21,"t":"亞摩斯的兒子以賽亞就差人去見希西家，說：「耶和華－以色列的神如此說，你因亞述王西拿基立的事向我祈求，","notes":[],"heads":["以賽亞給王的信息"]},{"n":22,"t":"所以耶和華論他這樣說：『少女錫安藐視你，嘲笑你；耶路撒冷向你搖頭。","notes":["「少女錫安」：原文直譯「少女錫安女子」。","「耶路撒冷」：原文直譯「 耶路撒冷女子」。"]},{"n":23,"t":"「『你辱罵誰，褻瀆誰，揚起聲來，高舉眼目攻擊誰呢？你攻擊的是以色列的聖者。","notes":[]},{"n":24,"t":"你藉臣僕辱罵主說：我率領許多戰車登上高山，到黎巴嫩的頂端；我要砍伐其中高大的香柏樹和上好的松樹。我必上到極高之處，進入茂盛的森林裏。","notes":[]},{"n":25,"t":"我已經挖井喝水；我必用腳掌踏乾埃及一切的河流。","notes":["「挖井喝水」：死海古卷是「在外邦挖井喝水」；參王下19．24。"]},{"n":26,"t":"「『你豈沒有聽見我早先所定、古時所立、現今實現的事嗎？就是讓你去毀壞堅固的城，使它們變為廢墟；","notes":[]},{"n":27,"t":"城裏居民的力量甚小，他們驚惶羞愧；像野草，像青菜，如房頂上的草，被東風颳散。","notes":["「被東風颳散」是根據死海古卷； 原文是「又如田間未長成的禾稼」，並且沒有下節的「你站起」。"]},{"n":28,"t":"「『你站起，你坐下，你出去，你進來，你向我發烈怒，我都知道。","notes":[]},{"n":29,"t":"因你向我發烈怒，你的狂傲上達我耳中，我要用鉤子鉤住你的鼻子，將嚼環放在你口裏，使你從原路轉回去。』","notes":[]},{"n":30,"t":"「我賜給你的預兆：你們今年要吃野生的，明年也要吃自長的；後年，你們就要耕種收割，栽葡萄園，吃其中的果子。","notes":[]},{"n":31,"t":"猶大家所逃脫剩餘的，仍要往下扎根，向上結果。","notes":[]},{"n":32,"t":"必有剩餘的民從耶路撒冷而出；有逃脫的人從錫安山而來。萬軍之耶和華的熱心必成就這事。","notes":[]},{"n":33,"t":"「所以耶和華論亞述王如此說：他必不得來到這城，也不在這裏射箭，不得拿盾牌到城前，也不能建土堆攻城。","notes":[]},{"n":34,"t":"他從哪條路來，必從那條路回去，必不得來到這城。這是耶和華說的。","notes":[]},{"n":35,"t":"因我為自己的緣故，又為我僕人大衛的緣故，必保護拯救這城。」","notes":[]},{"n":36,"t":"耶和華的使者出去，在亞述營中殺了十八萬五千人。清早有人起來，看哪，都是死屍。","notes":[]},{"n":37,"t":"亞述王西拿基立就拔營回去，住在尼尼微。","notes":[]},{"n":38,"t":"一日，他在他的神明尼斯洛廟裏叩拜，他兒子亞得米勒和沙利色用刀殺了他，然後逃到亞拉臘地；他兒子以撒‧哈頓接續他作王。","notes":[]}]},"38":{"heading":"希西家王罹病和痊癒","verses":[{"n":1,"t":"那些日子，希西家病得要死，亞摩斯的兒子以賽亞先知來見他，對他說：「耶和華如此說：『你當留遺囑給你的家，因為你必死，不能活了。』」","notes":[]},{"n":2,"t":"希西家就轉臉朝牆，向耶和華禱告，","notes":[]},{"n":3,"t":"說：「耶和華啊，求你記念我在你面前怎樣存完全的心，按誠實行事，又做你眼中看為善的事。」希西家就痛哭。","notes":[]},{"n":4,"t":"耶和華的話臨到以賽亞說：","notes":[]},{"n":5,"t":"「你去告訴希西家說，耶和華－你祖先大衛的神如此說：『我聽見了你的禱告，看見了你的眼淚。看哪，我必加添你十五年的壽數；","notes":[]},{"n":6,"t":"我要救你和這城脫離亞述王的手，也要保護這城。』","notes":[]},{"n":7,"t":"「耶和華必成就他所說的這話。這是耶和華給你的預兆：","notes":[]},{"n":8,"t":"看哪，我要使亞哈斯日晷上隨太陽前進的影子，往後退十度。」於是，在日晷上照下來的日影果然往後退了十度。","notes":[]},{"n":9,"t":"猶大王希西家患病痊癒後的詩：","notes":[]},{"n":10,"t":"我說，在如日中天的時候我就走了，將剩餘的年歲交給陰間的門。","notes":["本節或譯「我說，在如日中天的時候，我必進入陰間的門，不得享受剩餘的年歲。」"]},{"n":11,"t":"我說，我必不得見耶和華，不得在活人之地見耶和華，也不再看見世人，就是短暫世界中的居民。","notes":["「短暫世界」：有古卷是「世界」。"]},{"n":12,"t":"我的住處好像牧人的帳棚，遭人掀起，離我而去；我將性命捲起，像織布的捲布一樣。他從織布機頭那裏將我剪斷，你使我命喪於旦夕。","notes":[]},{"n":13,"t":"我令自己安靜直到天亮；他像獅子折斷我所有的骨頭，你使我命喪於旦夕。","notes":["「我令自己安靜」：死海古卷是「我被壓碎」；七十士譯本是「我被放棄」。"]},{"n":14,"t":"我像燕子呢喃，像白鶴鳴叫，又如鴿子哀鳴；我因仰望，眼睛困倦。主啊，我受欺壓，求你為我作保。","notes":[]},{"n":15,"t":"我還有甚麼可說的呢？他應許我的，他已成就了。我因心裏的苦楚，在一生的年日必謙卑而行。","notes":["「他應許我的」：死海古卷是「我對他說的」。","「在一生的年日必謙卑而行」：死海古卷是「我的睡眠溜走了」。"]},{"n":16,"t":"主啊，人得存活是在乎此，我的靈存活也全在乎此；求你使我痊癒，仍然存活。","notes":["「我的靈...在乎此」：死海古卷是「萬物的存活都因他的靈」。"]},{"n":17,"t":"看哪，我受大苦是為使我得平安；你愛我，救我的性命脫離敗壞的地府，將我一切的罪扔在你背後。","notes":[]},{"n":18,"t":"原來，陰間不能稱謝你，死亡不能頌揚你，下到地府的人也不能盼望你的信實。","notes":[]},{"n":19,"t":"只有活人，活人必稱謝你，像我今日稱謝你一樣。為父的，必使兒女知道你的信實。","notes":[]},{"n":20,"t":"耶和華肯救我，所以，我們要一生一世在耶和華殿中彈奏我弦樂的歌。","notes":[]},{"n":21,"t":"以賽亞說：「拿一塊無花果餅來，貼在瘡上，王必痊癒。」","notes":[]},{"n":22,"t":"希西家說：「我能上耶和華的殿，有甚麼預兆呢？」","notes":["死海古卷沒有 21、22 節。"]}]},"39":{"heading":"巴比倫王的使節","verses":[{"n":1,"t":"那時，巴拉但的兒子，巴比倫王米羅達‧巴拉但聽見希西家病得痊癒，就送書信和禮物給他。","notes":[]},{"n":2,"t":"希西家歡喜見使者，就將自己寶庫裏的金子、銀子、香料、貴重的膏油和他軍械庫裏一切的兵器，以及他所有的財寶，都給他們看；在他家中和全國之內，希西家沒有一樣不給他們看的。","notes":[]},{"n":3,"t":"於是以賽亞先知到希西家王那裏去，對他說：「這些人說了些甚麼？他們從哪裏來見你？」希西家說：「他們從遠方的巴比倫來見我。」","notes":[]},{"n":4,"t":"以賽亞說：「他們在你家裏看見了甚麼？」希西家說：「凡我家中所有的，他們都看見了；我財寶中沒有一樣東西不給他們看的。」","notes":[]},{"n":5,"t":"以賽亞對希西家說：「你要聽萬軍之耶和華的話，","notes":[]},{"n":6,"t":"耶和華說：『看哪，日子將到，凡你家裏所有的，並你祖先積蓄到如今的一切，都要被擄到巴比倫去，不留下一樣；","notes":[]},{"n":7,"t":"從你本身所生的孩子，其中必有被擄到巴比倫王宮當太監的。』」","notes":[]},{"n":8,"t":"希西家對以賽亞說：「你所說耶和華的話甚好。」因為他想：「在我有生之年必有太平和安穩。」","notes":[]}]},"40":{"heading":"安慰的話","verses":[{"n":1,"t":"你們的神說：「要安慰，安慰我的百姓。","notes":[]},{"n":2,"t":"要對耶路撒冷說安慰的話，向它宣告，它的戰爭已結束，它的罪孽已赦免；它為自己一切的罪，已從耶和華手中加倍受罰。」","notes":[]},{"n":3,"t":"有聲音呼喊著：「要在曠野為耶和華預備道路，在沙漠為我們的神修直大道。","notes":[]},{"n":4,"t":"一切山窪都要填滿，大小山岡都要削平；陡峭的要變為平坦，崎嶇的必成為平原。","notes":[]},{"n":5,"t":"耶和華的榮耀必然顯現，凡有血肉之軀的都一同看見，因為這是耶和華親口說的。」","notes":[]},{"n":6,"t":"有聲音說：「你喊叫吧！」我說：「我喊叫甚麼呢？」凡有血肉之軀的盡都如草，他的一切榮美像野地的花。","notes":["「我」是根據死海古卷和七十士譯本；原文是「他」。"]},{"n":7,"t":"耶和華吹一口氣，草就枯乾，花也凋謝。百姓誠然是草；","notes":[]},{"n":8,"t":"草必枯乾，花必凋謝，惟有我們神的話永遠立定。","notes":[]},{"n":9,"t":"報好信息的錫安哪，要登高山；報好信息的耶路撒冷啊，要極力揚聲。揚聲不要懼怕，對猶大的城鎮說：「看哪，你們的神！」","notes":[]},{"n":10,"t":"看哪，主耶和華必以大能臨到，他的膀臂必為他掌權；看哪，他的賞賜在他那裏，他的報應在他面前。","notes":[]},{"n":11,"t":"他要像牧人牧養自己的羊群，用膀臂聚集羔羊，抱在胸懷，慢慢引導那乳養小羊的。","notes":[]},{"n":12,"t":"誰曾用手心量諸水，用手虎口量蒼天，用升斗盛大地的塵土，用秤稱山嶺，用天平稱岡陵呢？","notes":[],"heads":["以色列的神無可比擬"]},{"n":13,"t":"誰曾測度耶和華的靈，或作他的謀士指教他呢？","notes":[]},{"n":14,"t":"他與誰商議，誰教導他，以公平的路指示他，將知識傳授與他，又將通達的道指教他呢？","notes":[]},{"n":15,"t":"看哪，列國都像水桶裏的一滴，又如天平上的微塵；看哪，他舉起眾海島，好像舉起極微小之物。","notes":[]},{"n":16,"t":"黎巴嫩不夠當柴燒，其中的走獸也不夠作燔祭。","notes":[]},{"n":17,"t":"列國在他面前如同不存在，在他看來微不足道，只是虛空。","notes":[]},{"n":18,"t":"你們究竟將誰比神，用甚麼形像與他相較呢？","notes":[]},{"n":19,"t":"至於偶像，匠人鑄造它，銀匠用金子包裹它，又為它鑄造銀鏈。","notes":[]},{"n":20,"t":"沒有能力捐獻的人，就挑選不易朽壞的木頭，為自己尋找巧匠，豎立不會倒的偶像。","notes":[]},{"n":21,"t":"你們豈不知道嗎？豈未曾聽見嗎？難道沒有人從起頭就告訴你們嗎？自從地的根基立定，你們豈不明白嗎？","notes":[]},{"n":22,"t":"神坐在地的穹窿之上，地上的居民有如蚱蜢。他鋪張穹蒼如幔子，展開諸天如可住的帳棚。","notes":[]},{"n":23,"t":"他使君王歸於虛無，使地上的審判官成為虛空。","notes":[]},{"n":24,"t":"他們剛栽上，剛種好，根也剛扎在地裏，經他一吹，就都枯乾；旋風將他們吹去，像碎稭一樣。","notes":[]},{"n":25,"t":"那聖者說：「你們將誰與我相比，與我相等呢？」","notes":[]},{"n":26,"t":"你們要向上舉目，看是誰創造這萬象，按數目領出它們，一一稱其名，以他的權能和他的大能大力，使它們一個都不缺。","notes":[]},{"n":27,"t":"雅各啊，你為何說，以色列啊，你為何言，「我的道路向耶和華隱藏，我的冤屈神並不查問」？","notes":[]},{"n":28,"t":"你豈不曾知道嗎？你豈未曾聽見嗎？永在的神耶和華，創造地極的主，他不疲乏，也不困倦；他的智慧無法測度。","notes":[]},{"n":29,"t":"疲乏的，他賜能力；軟弱的，他加力量。","notes":[]},{"n":30,"t":"就是年輕人也要疲乏困倦，強壯的也必全然跌倒。","notes":[]},{"n":31,"t":"但那等候耶和華的必重新得力。他們必如鷹展翅上騰；他們奔跑卻不困倦，行走卻不疲乏。","notes":[]}]},"41":{"heading":"神對以色列的保證","verses":[{"n":1,"t":"眾海島啊，在我面前靜默；萬民要重新得力，讓他們近前來陳述，我們可以彼此辯論。","notes":[]},{"n":2,"t":"誰從東方興起一人，憑公義召他來到腳前？誰將列國交給他，使他管轄列王，把他們如灰塵交與他的刀，如風吹的碎稭交與他的弓？","notes":[]},{"n":3,"t":"他追趕君王，安然走過，快速地腳不落地。","notes":["「快速地腳不落地」：死海古卷是「他們不認識腳所走的路」；七十士譯本是「他們腳所走的路」。"]},{"n":4,"t":"誰做成這事，從起初宣召歷代呢？就是我－耶和華！我是首先的，也與末後的同在。","notes":[]},{"n":5,"t":"眾海島看見就都害怕，地極也都戰兢，他們近前來；","notes":[]},{"n":6,"t":"各人互相幫助，對弟兄說：「壯膽吧！」","notes":[]},{"n":7,"t":"木匠鼓勵銀匠，用鎚子打光的鼓勵打砧的，對銲工說：「銲得好！」又用釘子釘穩，免得它倒下。","notes":[]},{"n":8,"t":"惟你以色列，我的僕人，雅各，我所揀選的，我朋友亞伯拉罕的後裔，","notes":[]},{"n":9,"t":"你是我從地極領來，從地角召來的，我對你說：「你是我的僕人；我揀選你，並不棄絕你。」","notes":[]},{"n":10,"t":"你不要害怕，因為我與你同在；不要驚惶，因為我是你的神。我必堅固你，幫助你，用我公義的右手扶持你。","notes":[]},{"n":11,"t":"看哪，凡向你發怒的都抱愧蒙羞，與你相爭的必如無有，並要滅亡。","notes":[]},{"n":12,"t":"與你爭鬥的，你要尋找他們，卻遍尋不著；與你爭戰的必如無有，成為虛無。","notes":[]},{"n":13,"t":"因為我耶和華－你的神必攙扶你的右手，對你說：「不要害怕！我必幫助你。」","notes":[]},{"n":14,"t":"蟲子雅各，以色列人哪，不要害怕！我必幫助你；救贖你的是以色列的聖者。這是耶和華說的。","notes":[]},{"n":15,"t":"看哪，我使你成為全新的打穀機，齒輪銳利；你要把山嶺打得粉碎，使岡陵如同糠秕。","notes":[]},{"n":16,"t":"你要簸揚它們，風要將它們吹去；旋風要颳散它們。你卻要以耶和華為喜樂，因以色列的聖者誇耀。","notes":[]},{"n":17,"t":"困苦貧窮人尋找水，卻尋不著；他們因口渴，舌頭乾燥。我－耶和華必應允他們，我─以色列的神必不離棄他們。","notes":[]},{"n":18,"t":"我要在光禿的高地開江河，在谷中開泉源；我要使沙漠變為水池，使乾地變為湧泉。","notes":[]},{"n":19,"t":"我要在曠野栽植香柏樹、皂莢樹、番石榴樹，和野橄欖樹。在沙漠一同栽上松樹、杉樹，和黃楊樹，","notes":[]},{"n":20,"t":"好叫人看見，知道，思想，明白；這是耶和華親手做的，是以色列的聖者所造的。","notes":[]},{"n":21,"t":"耶和華說：「你們要呈上你們的案件。」雅各的君王說：「你們要提出你們的理由。」","notes":[],"heads":["耶和華向偶像挑戰"]},{"n":22,"t":"讓它們近前來，告訴我們將來要發生甚麼事！你們要說明先前發生的事，好讓我們思索；或者告訴我們將來的事，使我們得知事情的結局。","notes":[]},{"n":23,"t":"你們要指明未來的事，使我們知道你們是神明！你們或降福，或降禍，好使我們驚奇，一同觀看。","notes":[]},{"n":24,"t":"看哪，你們屬乎虛無，你們的作為也屬虛空；那選擇你們的是可憎惡的。","notes":[]},{"n":25,"t":"我從北方興起一人，他從日出之地而來，是求告我名的；他必踩踏掌權者，如踩踏泥土，又如陶匠踹泥一般。","notes":["「踩踏」：原文是「臨到」；下同。"]},{"n":26,"t":"有誰從起初宣佈這事，使我們知道呢？有誰從先前指明，使我們說「他是對的」呢？沒有人宣佈，沒有人指明，也沒有人聽見你們的話。","notes":[]},{"n":27,"t":"我首先對錫安說，看哪，他們在此！我要將一位報好信息的賜給耶路撒冷。","notes":[]},{"n":28,"t":"然而我觀看，並無一人；我詢問的時候，他們中間也沒有謀士可回答。","notes":[]},{"n":29,"t":"看哪，他們盡是麻煩，所做的工都屬虛無；所鑄的偶像是風，是虛空。","notes":["「麻煩」：死海古卷和一些譯本是「虛空」。"]}]},"42":{"heading":"耶和華的僕人","verses":[{"n":1,"t":"看哪，我的僕人，我所扶持、所揀選、心裏所喜悅的！我已將我的靈賜給他，他必將公理傳給萬邦。","notes":[]},{"n":2,"t":"他不喧嚷，不揚聲，也不使街上聽見他的聲音。","notes":[]},{"n":3,"t":"壓傷的蘆葦，他不折斷；將殘的燈火，他不吹滅。他憑信實將公理傳開。","notes":[]},{"n":4,"t":"他不灰心，也不喪膽，直到他在地上設立公理；眾海島都等候他的訓誨。","notes":[]},{"n":5,"t":"那創造諸天，鋪張穹蒼，鋪開地與地的出產，賜氣息給地上眾人，賜生命給行走其上之人的神耶和華如此說：","notes":[]},{"n":6,"t":"「我－耶和華憑公義召你，要攙扶你的手，保護你，要藉著你與百姓立約，使你成為萬邦之光，","notes":[]},{"n":7,"t":"開盲人的眼，領囚犯出監獄，領坐在黑暗中的出地牢。","notes":[]},{"n":8,"t":"我是耶和華，這是我的名；我必不將我的榮耀歸給別神，也不將我所得的頌讚歸給雕刻的偶像。","notes":["「別神」：原文是「別的」。"]},{"n":9,"t":"看哪，先前的事已經成就，現在我要指明新事，告訴你們尚未發生的事。","notes":[]},{"n":10,"t":"航海的人和海中一切所有的，眾海島和其中的居民，都當向耶和華唱新歌，從地極讚美他。","notes":[],"heads":["頌讚之歌"]},{"n":11,"t":"曠野和其中的城鎮，並基達人居住的村莊都當揚聲；西拉的居民當歡呼，在山頂上大聲呼喊。","notes":["「揚聲」：七十士譯本是「歡樂」。"]},{"n":12,"t":"願他們將榮耀歸給耶和華，在海島中傳揚頌讚他的話。","notes":[]},{"n":13,"t":"耶和華必如勇士出征，如戰士激起憤恨，他要喊叫，大聲吶喊，擊敗他的敵人。","notes":[]},{"n":14,"t":"我許久閉口不言，沉默不語；現在我要像臨產的婦人，大聲喊叫，呼吸急促而喘氣。","notes":[],"heads":["神應許幫助他的子民"]},{"n":15,"t":"我要使大小山岡變為荒蕪，使其上的花草都枯乾；我要使江河變為沙洲，使水池盡都乾涸。","notes":[]},{"n":16,"t":"我要引導盲人行他們所不認識的道，引領他們走他們未曾走過的路；我在他們面前使黑暗變為光明，使彎曲變為平直。這些事我都要做，並不離棄他們。","notes":[]},{"n":17,"t":"但那倚靠雕刻的偶像，對鑄造的偶像說：「你是我們的神明」；這種人要退後，大大蒙羞。","notes":[]},{"n":18,"t":"你們這耳聾的，聽吧！你們這眼瞎的，看吧，使你們得以看見！","notes":[],"heads":["以色列人不受教誨"]},{"n":19,"t":"誰比我的僕人眼瞎呢？誰比我所差遣的使者耳聾呢？誰瞎眼像那獻身給我的人？誰瞎眼像耶和華的僕人呢？","notes":["「瞎眼」：有古卷是「耳聾」。"]},{"n":20,"t":"看見許多事卻不領會，耳朵開通卻聽不見。","notes":[]},{"n":21,"t":"耶和華因自己的公義，樂意使律法為大為尊。","notes":[]},{"n":22,"t":"但這百姓是被搶被奪的，全都陷在洞穴中，關在監牢裏；他們成了掠物，無人拯救，成了擄物，無人索還。","notes":[]},{"n":23,"t":"你們中間誰肯側耳聽這話，誰肯留心聽，以防將來呢？","notes":[]},{"n":24,"t":"誰將雅各交出作為擄物，將以色列交給搶奪者呢？豈不是耶和華─我們所得罪的那位嗎？他們不肯遵行他的道，也不聽從他的訓誨。","notes":[]},{"n":25,"t":"所以，他將猛烈的怒氣和戰爭的威力傾倒在以色列身上；在他周圍如火燃起，他竟然不知，燒著了，他也不在意。","notes":[]}]},"43":{"heading":"神應許拯救他的子民","verses":[{"n":1,"t":"雅各啊，創造你的耶和華，以色列啊，造成你的那位，現在如此說：「你不要害怕，因為我救贖了你；我曾提你的名召你，你是屬我的。","notes":[]},{"n":2,"t":"你從水中經過，我必與你同在，你渡過江河，水必不漫過你；你在火中行走，也不被燒傷，火焰必不燒著你身。","notes":[]},{"n":3,"t":"因為我是耶和華－你的神，是以色列的聖者－你的救主；我使埃及作你的贖價，使古實和西巴代替你。","notes":[]},{"n":4,"t":"因我看你為寶貝為尊貴；又因我愛你，所以使人代替你，使萬民替換你的生命。","notes":[]},{"n":5,"t":"你不要害怕，因我與你同在；我必領你的後裔從東方來，又從西方召集你。","notes":[]},{"n":6,"t":"我要對北方說，交出來！對南方說，不可扣留！要將我的兒子從遠方帶來，將我的女兒從地極領回，","notes":[]},{"n":7,"t":"就是凡稱為我名下的人，是我為自己的榮耀創造的，是我所塑造，所做成的。」","notes":[]},{"n":8,"t":"你要將有眼卻瞎、有耳卻聾的民都帶出來！","notes":[],"heads":["以色列是耶和華的見證人"]},{"n":9,"t":"任憑萬國聚集，任憑萬民會合。他們當中誰能說明，並將先前的事指示我們呢？讓他們帶來見證，顯明他們有理，看是否聽見的人會說：「果然是真的。」","notes":[]},{"n":10,"t":"你們是我的見證，是我所揀選的僕人，為了要使你們知道，且信服我，又明白我就是耶和華。在我以前沒有任何被造的真神，在我以後也必沒有。這是耶和華說的。","notes":[]},{"n":11,"t":"我，惟有我是耶和華；除我以外沒有救主。","notes":[]},{"n":12,"t":"我曾指示，我曾拯救，我曾說明，並沒有外族的神明在你們中間。你們是我的見證，我是神。這是耶和華說的。","notes":["「外族的神明」：原文是「外族」。"]},{"n":13,"t":"自有日子以來，我就是神，誰也不能救人脫離我的手。我要行事，誰能逆轉呢？","notes":[]},{"n":14,"t":"耶和華─你們的救贖主、以色列的聖者如此說：「因你們的緣故，我已派遣人到巴比倫去；要使迦勒底人都如難民，坐自己素來宴樂的船下來。","notes":[],"heads":["逃離巴比倫"]},{"n":15,"t":"我是耶和華－你們的聖者，是創造以色列的，是你們的君王。」","notes":[]},{"n":16,"t":"那在滄海中開道，在大水中開路，使戰車、馬匹、軍兵、勇士一同出來，使他們仆倒，不再起來，使他們滅沒，好像熄滅之燈火的耶和華如此說：","notes":[],"end":17},{"n":18,"t":"「你們不要追念從前的事，也不要思想古時的事。","notes":[]},{"n":19,"t":"看哪，我要行一件新事，如今就要顯明，你們豈不知道嗎？我必在曠野開道路，在沙漠開江河。","notes":["「江河」：死海古卷是「路徑」。"]},{"n":20,"t":"野地的走獸要尊敬我，野狗和鴕鳥也必尊敬我。因我使曠野有水，使沙漠有河，好賜給我的百姓、我的選民喝。","notes":[]},{"n":21,"t":"這百姓是我為自己造的，為要述說我的美德。」","notes":[]},{"n":22,"t":"「雅各啊，你並沒有求告我；以色列啊，你倒厭煩我。","notes":[],"heads":["以色列人的罪惡"]},{"n":23,"t":"你並沒有將你的羊帶來獻給我做燔祭，也沒有用牲祭尊敬我；我未曾因素祭使你操勞，也沒有因乳香使你厭煩。","notes":[]},{"n":24,"t":"你沒有用銀子為我買香菖蒲，也沒有用祭物的油脂使我飽足；倒使我因你的罪惡操勞，使我因你的罪孽厭煩。","notes":[]},{"n":25,"t":"我，惟有我為自己的緣故塗去你的過犯，我也不再記得你的罪惡。","notes":[]},{"n":26,"t":"你儘管提醒我，讓我們來辯論；儘管陳述，自顯為義。","notes":[]},{"n":27,"t":"你的始祖犯罪，你的師傅違背我；","notes":[]},{"n":28,"t":"因此，我要凌辱聖所的領袖，使雅各遭毀滅，使以色列受辱罵。」","notes":["「我要...領袖」：七十士譯本是「領袖們褻瀆了我的聖所，於是我要」。"]}]},"44":{"heading":"耶和華是獨一的神","verses":[{"n":1,"t":"「我的僕人雅各，我所揀選的以色列啊，現在你當聽。","notes":[]},{"n":2,"t":"那位造你，使你在母腹中成形，並要幫助你的耶和華如此說：我的僕人雅各，我所揀選的耶書崙哪，不要害怕！","notes":[]},{"n":3,"t":"因為我要把水澆灌乾渴的地方，使水湧流在乾旱之地。我要將我的靈澆灌你的後裔，使我的福臨到你的子孫。","notes":[]},{"n":4,"t":"他們要在草叢中生長，如溪水旁的柳樹。","notes":["「他們...生長」：死海古卷是「他們像在草叢中生長」；七十士譯本是「他們要像草在水中生長」。"]},{"n":5,"t":"這個要說：『我是屬耶和華的』，那個要以雅各的名自稱，又有一個在手上寫著：『歸耶和華』，並自稱為以色列。」","notes":[]},{"n":6,"t":"耶和華－以色列的君王，以色列的救贖主－萬軍之耶和華如此說：「我是首先的，也是末後的；除我以外再沒有神。","notes":[]},{"n":7,"t":"自從古時我設立了人，誰能像我宣告，指明，又為自己陳說呢？讓他指明未來的事和必成的事吧！","notes":[]},{"n":8,"t":"你們不要恐懼，也不要害怕。我豈不是從上古就告訴並指示你們了嗎？你們是我的見證人！除我以外，豈有神呢？誠然沒有磐石，就我所知，一個也沒有！」","notes":[]},{"n":9,"t":"製造偶像的人盡都虛空，他們所喜悅的全無益處；偶像的見證人毫無所見，毫無所知，以致他們羞愧。","notes":[],"heads":["虛無的偶像"]},{"n":10,"t":"誰製造神像，鑄造偶像？這些都是無益的。","notes":[]},{"n":11,"t":"看哪，他的同夥都必羞愧。工匠不過是人，任他們聚集，任他們站立吧！他們都必懼怕，一同羞愧。","notes":[]},{"n":12,"t":"鐵匠用工具在火炭上工作，用鎚打出形狀，用他有力的膀臂來錘。他因飢餓而無力氣；因未喝水而疲倦。","notes":["「鐵匠...工作」：七十士譯本是「工匠磨利鐵器」。"]},{"n":13,"t":"木匠拉線，用筆劃出樣子，用鉋子鉋成形狀，又用圓規劃了模樣。他仿照人的體態，做出美妙的人形，放在廟裏。","notes":[]},{"n":14,"t":"他砍伐香柏樹，又取杉樹和橡樹，在樹林中讓它茁壯；或栽種松樹，得雨水滋潤長大。","notes":[]},{"n":15,"t":"這樹，人可用以生火；他拿一些來取暖，又搧火烤餅，而且做神像供跪拜，做雕刻的偶像向它叩拜。","notes":[]},{"n":16,"t":"他將一半的木頭燒在火中，用它烤肉來吃；吃飽了，就自己取暖說：「啊哈，我暖和了，我看到火了！」","notes":[]},{"n":17,"t":"然後又用剩下的一半做了一個神明，就是雕刻的偶像，向這偶像俯伏叩拜，向它禱告說：「求你拯救我，因你是我的神明。」","notes":[]},{"n":18,"t":"他們既無知，又不思想；因為耶和華蒙蔽他們的眼，使他們看不見，塞住他們的心，使他們不明白。","notes":[]},{"n":19,"t":"沒有一個心裏醒悟，有知識，有聰明，能說：「我曾拿一部分用火燃燒，在炭火上烤餅，也烤肉來吃。這剩下的，我豈要做可憎之像嗎？我豈可向木頭叩拜呢？」","notes":[]},{"n":20,"t":"他以灰塵為食，心裏迷糊，以致偏邪，不能自救，也不能說：「我右手中豈不是有虛謊嗎？」","notes":[]},{"n":21,"t":"雅各啊，要思念這些事；以色列啊，你是我的僕人。我造了你，你是我的僕人，以色列啊，我必不忘記你。","notes":["「我必不忘記你」或譯「你不會忘記我」。"],"heads":["耶和華是創造主也是救贖主"]},{"n":22,"t":"我塗去你的過犯，像厚雲消散；塗去你的罪惡，如薄霧消失。你當歸向我，因我救贖了你。","notes":[]},{"n":23,"t":"諸天哪，應當歌唱，因為耶和華成就這事。地的深處啊，應當歡呼；眾山哪，要出聲歌唱；樹林和其中所有的樹木啊，你們都當歌唱！因為耶和華救贖了雅各，並要因以色列榮耀自己。","notes":[]},{"n":24,"t":"從你在母腹中就造了你，你的救贖主－耶和華如此說：「我－耶和華創造萬物，獨自鋪張諸天，親自展開大地；","notes":["「親自展開大地」：原文另譯「展開大地，誰與我同在呢？」"]},{"n":25,"t":"我使虛謊的預兆失效，愚弄占卜的人，使智慧人退後，使他的知識變為愚拙；","notes":[]},{"n":26,"t":"卻使我僕人的話站得住，成就我使者的籌算。我論耶路撒冷說：『必有人居住』；論猶大的城鎮說：『必被建造，我必重建其中的廢墟。』","notes":[]},{"n":27,"t":"我對深淵說：『乾了吧！我要使你的江河乾涸』；","notes":[]},{"n":28,"t":"論居魯士說：『他是我的牧人，他要成就我所喜悅的，下令建造耶路撒冷，發命令立穩聖殿的根基。』」","notes":[]}]},"45":{"heading":"耶和華立居魯士為王","verses":[{"n":1,"t":"耶和華對所膏的居魯士如此說，他的右手我曾攙扶，使列國降服在他面前，列王的腰帶我曾鬆開，使城門在他面前敞開，不得關閉：","notes":[]},{"n":2,"t":"「我要在你前面行，修平崎嶇之地。我必打破銅門，砍斷鐵閂。","notes":[]},{"n":3,"t":"我要將暗中的寶物和隱藏的財富賜給你，使你知道提名召你的就是我－耶和華，以色列的神。","notes":[]},{"n":4,"t":"因我的僕人雅各，我所揀選的以色列，我提名召你；你雖不認識我，我也加給你名號。","notes":[]},{"n":5,"t":"我是耶和華，再沒有別的了；除了我以外再沒有神。你雖不認識我，我必給你束腰。","notes":[]},{"n":6,"t":"從日出之地到日落之處使人都知道除我以外，沒有別的。我是耶和華，再沒有別的了。","notes":[]},{"n":7,"t":"我造光，又造暗；施平安，又降災禍；做成這一切的是我－耶和華。","notes":[]},{"n":8,"t":"「諸天哪，要如雨傾盆而降，雲要降下公義，地要裂開，救恩湧出，使公義也一同滋長；這都是我－耶和華造的。」","notes":["「救恩湧出」：原文另譯「產出救恩」。"]},{"n":9,"t":"「那與造他的主爭論的人有禍了！他不過是地上瓦塊中的一片。泥土豈可對塑造它的說：『你做的是甚麼？你所做的物怎麼沒有把手呢？』","notes":["「那與...一片」：死海古卷是「那與造他的主爭論的人，就是瓦器與陶匠爭論的，有禍了！」","「你所做...把手呢？」或譯「所做的物豈可說：你沒有手呢 ？」"],"heads":["創造和歷史的主宰"]},{"n":10,"t":"有人對父親說，『你生的是甚麼』，對母親說，『你生產的是甚麼』；這人有禍了！」","notes":["「母親」：原文是「婦人」。"]},{"n":11,"t":"耶和華－以色列的聖者，就是造以色列的如此說：「難道我孩子的未來，你們能質問我，我手的工作，你們可以吩咐我嗎？","notes":[]},{"n":12,"t":"我造大地，又創造人在地上。我親手鋪張諸天，天上萬象也是我所任命的。","notes":[]},{"n":13,"t":"我憑公義興起居魯士，又要修直他一切的道路。他必建造我的城，釋放我被擄的民，不為工價，也不為獎賞。」這是萬軍之耶和華說的。","notes":["「居魯士」：原文是「他」。"]},{"n":14,"t":"耶和華如此說：「埃及的出產和古實的貨物必歸你；身量高大的西巴人，他們必過來歸你，為你所有。他們必帶著鎖鏈過來跟隨你，向你下拜，祈求你說：『神真是在你中間，再沒有別的，沒有別的神。』」","notes":[]},{"n":15,"t":"救主－以色列的神啊，你誠然是隱藏自己的神。","notes":[]},{"n":16,"t":"製造偶像的都要抱愧蒙羞，他們要一同歸於慚愧。","notes":[]},{"n":17,"t":"惟有以色列必蒙耶和華拯救，得永遠的救恩。你們必不蒙羞，也不抱愧，直到永世無盡。","notes":[]},{"n":18,"t":"耶和華如此說，他創造諸天，他是神；他造了地，形成它，堅固它，並非創造它為荒涼，而是要給人居住：「我是耶和華，再沒有別的。","notes":[]},{"n":19,"t":"我不在隱密黑暗之地說話，也沒有對雅各的後裔說，『你們尋求我是徒然的』，我－耶和華所講的是公義，所說的是正直。」","notes":[]},{"n":20,"t":"「你們從列國逃脫的人，要一同聚集前來。那些抬著雕刻的木偶、祈求不能救人之神明的，毫無知識。","notes":[],"heads":["天地之主"]},{"n":21,"t":"你們要近前來說明，讓他們彼此商議。誰從古時指明這事？誰從上古述說它？不是我－耶和華嗎？除了我以外，再沒有神；我是公義的神，又是救主；除了我以外，再沒有別的了。","notes":[]},{"n":22,"t":"「地的四極都當轉向我，就必得救；因為我是神，再沒有別的。","notes":[]},{"n":23,"t":"我指著自己起誓，公義從我的口發出，這話並不返回：『萬膝必向我跪拜，萬口必憑我起誓。』","notes":[]},{"n":24,"t":"「人論我說，『公義、能力，惟獨在乎耶和華。人必歸向他，凡向他發怒的都必蒙羞。","notes":["「人論我說」：七十士譯本是「人說」。"]},{"n":25,"t":"以色列的後裔必因耶和華得稱為義，並要彼此誇耀。』」","notes":[]}]},"46":{"heading":"巴比倫的偶像","verses":[{"n":1,"t":"彼勒叩拜，尼波屈身；巴比倫的偶像馱在走獸和牲畜背上。你們所抬的成了重馱，使牲畜疲乏。","notes":[]},{"n":2,"t":"這些神明一同屈身叩拜，不能救自己，反倒遭人擄去。","notes":["「自己」或譯「重馱」。"]},{"n":3,"t":"雅各家，以色列家所有的餘民哪，你們自從生下就蒙我抱，自出母胎便由我來背，你們都要聽從我。","notes":[]},{"n":4,"t":"直到你們年老，我不改變；直到你們髮白，我仍扶持。我已造你，就必背你；我必抱你，也必拯救。","notes":[]},{"n":5,"t":"你們將誰與我相比，與我相等，將誰與我相較，使我們相似呢？","notes":[]},{"n":6,"t":"他們從錢囊中倒出金子，用天平秤出銀子，雇銀匠造成神像，他們又俯伏，又叩拜。","notes":[]},{"n":7,"t":"他們抬起神像，扛在肩上，安置在定處，使它站立，不離本位；人呼求它，它卻不回答，也無法救人脫離災難。","notes":[]},{"n":8,"t":"你們當記得這事，立定心意。叛逆的人哪，要留心思想。","notes":["「立定心意」或譯「自己做大丈夫」。"]},{"n":9,"t":"要追念上古的事，因為我是神，並無別的；我是神，沒有能與我相比的。","notes":[]},{"n":10,"t":"我從起初就指明末後的事，從古時便言明未成的事，說：「我的籌算必立定；凡我所喜悅的，我必成就。」","notes":[]},{"n":11,"t":"我召鷙鳥從東方來，召那成就我籌算的人從遠方來。我已說出，就必成就；我已謀定，也必做成。","notes":[]},{"n":12,"t":"你們這些心中頑固、遠離公義的人，要聽從我。","notes":[]},{"n":13,"t":"我使我的公義臨近，它已不遠。我的救恩必不遲延。我要為以色列－我的榮耀在錫安施行救恩。","notes":[]}]},"47":{"heading":"審判巴比倫","verses":[{"n":1,"t":"少女巴比倫 哪，下來坐在塵埃；迦勒底啊，沒有寶座，要坐在地上；你不再稱為柔弱嬌嫩。","notes":["「少女巴比倫」：原文直譯「少女巴比倫女子」。","「迦勒底」：原文直譯「迦勒底女子」；下同。"]},{"n":2,"t":"要用磨磨麵，揭去面紗，脫去長裙，露腿渡河。","notes":[]},{"n":3,"t":"你的下體必被露出；你的羞辱必被看見。我要報復，誰也不寬容。","notes":["「誰也不寬容」或譯「誰也不能阻止我」。"]},{"n":4,"t":"我們的救贖主是以色列的聖者，他的名為萬軍之耶和華。","notes":[]},{"n":5,"t":"迦勒底啊，你要靜坐，進入黑暗中，因你不再稱為萬國之后。","notes":[]},{"n":6,"t":"我向我的百姓發怒，使我的產業受凌辱，將他們交在你手中；然而你毫不憐憫他們，連老年人你也加極重的軛。","notes":[]},{"n":7,"t":"你說：「我必永遠為后。」你不將這事放在心上，也不思想事情的結局。","notes":[]},{"n":8,"t":"你這專好宴樂、以為地位穩固的，現在當聽這話。你心中說：「惟有我，除我以外再沒有別的。我必不致寡居，也不經歷喪子之痛。」","notes":[]},{"n":9,"t":"哪知，喪子、寡居這兩件事一日之間忽然臨到你；你雖多行邪術、廣施魔咒，這兩件事必全然臨到你身上。","notes":[]},{"n":10,"t":"你倚靠自己的惡行，說：「無人看見我。」你的智慧聰明使你走偏，你心裏說：「惟有我，除我以外再沒有別的了。」","notes":[]},{"n":11,"t":"但災禍臨到你，你不知如何驅除；災害落在你身上，你也無法除掉，你所不知道的毀滅必忽然臨到你身上。","notes":[]},{"n":12,"t":"儘管使用從幼年就施行的魔符和眾多的邪術吧！或許有些幫助，或許可以致勝。","notes":[]},{"n":13,"t":"你籌劃太多，以致疲倦。讓那些觀天象，看星宿，在初一說預言的都起來，救你脫離所要臨到你的事！","notes":[]},{"n":14,"t":"看哪，他們要像碎稭被火焚燒，無法救自己脫離火焰的魔掌；沒有炭火可以取暖，你也不能坐在火旁。","notes":["「取暖」或譯「烤餅」。"]},{"n":15,"t":"你所操勞的事都像這樣；從你幼年以來與你交易的都各奔己路，沒有一人來救你。","notes":[]}]},"48":{"heading":"神掌管未來","verses":[{"n":1,"t":"雅各家，稱為以色列名下，從猶大的源頭而出的啊，你們指著耶和華的名起誓，提說以色列的神，卻不憑誠信，也不憑公義；你們自稱為聖城之民，倚靠名為萬軍之耶和華－以色列的神；現在，當聽我言：","notes":[],"end":2},{"n":3,"t":"「先前的事，我自古已說明，已從我口而出，是我所指示的；我瞬間行事，事便成就。","notes":[]},{"n":4,"t":"因為我知道你是頑梗的；你的頸項是鐵的，你的額頭是銅的。","notes":[]},{"n":5,"t":"所以，我自古就給你說明，在事未成以先指示你，免得你說：『這些事是我的偶像所行的，是我雕刻的偶像和鑄造的神像所命定的。』","notes":[]},{"n":6,"t":"「你既已聽見，現在要察看這一切；你們不是要說明嗎？從今以後，我要指示你新事，就是你所不知道的隱密事。","notes":[]},{"n":7,"t":"這事是現今造的，並非自古就有，在今日以先，你未曾聽見；免得你說：『看哪，這事我早已知道了。』","notes":[]},{"n":8,"t":"誠然你未曾聽見，也未曾知道；你的耳朵從來未曾開通。我原知道你行事極其詭詐，你自從出母胎以來，就稱為悖逆的。","notes":[]},{"n":9,"t":"「我為我的名暫且忍怒，為了我的榮耀向你容忍，不將你剪除。","notes":[]},{"n":10,"t":"看哪，我熬煉你，卻不像熬煉銀子；你在苦難的火爐中，我試煉你。","notes":["「試煉」是根據死海古卷；原文是「揀選」。"]},{"n":11,"t":"我為自己的緣故必做這事，我豈能被褻瀆？我必不將我的榮耀歸給別神。","notes":["「我豈能被褻瀆？」七十士譯本和其他古譯本是「因為我的名被褻瀆。」","「別神」：原文是「別的」。"]},{"n":12,"t":"雅各－我所選召的以色列啊，當聽從我：我是耶和華，我是首先的，也是末後的。","notes":[]},{"n":13,"t":"我親手立了地的根基，以右手鋪張諸天；我一召喚，天地就都立定。」","notes":[]},{"n":14,"t":"「你們都當聚集而聽，偶像之中誰曾說明這些事？耶和華愛他，他必向巴比倫成就耶和華的旨意，耶和華的膀臂也要加在迦勒底人身上。","notes":["「偶像」：原文是「它們」。","「耶和華愛他...身上」：七十士譯本是「我因愛你，向巴比倫成就了你的旨意，除掉了迦勒底的後裔」。"],"heads":["耶和華揀選居魯士"]},{"n":15,"t":"我，惟有我曾說過，我選召他，領他來，他的道路必亨通。","notes":[]},{"n":16,"t":"你們要接近我來聽這話，我從起初就未曾在隱密之處說話，萬事之始，我就在那裏。」現在，主耶和華差遣了我，帶著他的靈而來。","notes":["「差遣了我，帶著他的靈而來」：原文是「差遣了我和他的靈來」。"]},{"n":17,"t":"耶和華－你的救贖主，以色列的聖者如此說：「我是耶和華－你的神，我教導你，使你得益處，指引你當走的路。","notes":[],"heads":["耶和華對他子民的計劃"]},{"n":18,"t":"甚願你聽從我的命令，你的平安就會如河水，你的公義如海浪，","notes":[]},{"n":19,"t":"你的後裔必多如海沙，你腹中所生的必多如沙粒。他的名絕不從我面前剪除，也不滅絕。」","notes":[]},{"n":20,"t":"你們要從巴比倫出來，從迦勒底人中逃脫，以歡呼的聲音宣告，將這事傳揚到地極，說：耶和華救贖了他的僕人雅各！","notes":[]},{"n":21,"t":"他引導他們經過沙漠，他們卻未嘗乾渴；他為他們使水從磐石流出，磐石裂開，水就湧出。","notes":[]},{"n":22,"t":"耶和華說：「惡人必不得平安！」","notes":[]}]},"49":{"heading":"以色列成為萬邦之光","verses":[{"n":1,"t":"眾海島啊，當聽從我！遠方的眾民哪，要留心聽！自出母胎，耶和華就選召我；自出母腹，他就稱呼我的名。","notes":[]},{"n":2,"t":"他使我的口如快刀，把我藏在他手蔭之下；又使我成為磨利的箭，把我藏在他箭袋之中；","notes":[]},{"n":3,"t":"對我說：「你是我的僕人以色列；我必因你得榮耀。」","notes":[]},{"n":4,"t":"我卻說：「我勞碌是徒然，我盡力是虛無虛空。耶和華誠然以公平待我，我的賞賜在我的神那裏。」","notes":[]},{"n":5,"t":"現在耶和華說話，他從我出母胎，就造我作他的僕人，要使雅各歸向他，使以色列聚集在他那裏。耶和華看我為尊貴，我的神是我的力量。","notes":[]},{"n":6,"t":"他說：「你作我的僕人，使雅各眾支派復興，使以色列中蒙保存的人歸回；然而此事尚小，我還要使你作萬邦之光，使你施行我的救恩，直到地極。」","notes":[]},{"n":7,"t":"救贖主－以色列的聖者耶和華對那被人藐視、本國憎惡、統治者奴役的如此說：「君王看見就站起來，領袖也要下拜；這都是因信實的耶和華，因揀選你的以色列的聖者。」","notes":[]},{"n":8,"t":"耶和華如此說：「在悅納的時候，我應允了你；在拯救的日子，我幫助了你。我要保護你，要藉著你與百姓立約，為了復興遍地，使人承受荒蕪之地為業；","notes":[],"heads":["耶路撒冷的復興"]},{"n":9,"t":"對那被捆綁的人說：『出來吧！』對在黑暗裏的人說：『顯現吧！』他們在路上必得飲食，在光禿的高地必有食物。","notes":[]},{"n":10,"t":"他們不飢不渴，炎熱和烈日必不傷害他們；因為憐憫他們的必引導他們，領他們到水泉旁邊。","notes":[]},{"n":11,"t":"我必在眾山開闢路徑，大道也要填高。","notes":[]},{"n":12,"t":"看哪，他們從遠方來；有些從北方來，有些從西方來，有些從色弗尼地來。」","notes":["「色弗尼」是根據死海古卷，原文是「希尼」；或譯「秦國」。"]},{"n":13,"t":"諸天哪，應當歡呼！大地啊，應當快樂！眾山哪，應當揚聲歌唱！因為耶和華已經安慰他的百姓，他要憐憫他的困苦之民。","notes":[]},{"n":14,"t":"錫安說：「耶和華離棄了我，主忘記了我。」","notes":[]},{"n":15,"t":"婦人焉能忘記她吃奶的嬰孩，不憐憫她所生的兒子？即或有忘記的，我卻不忘記你。","notes":[]},{"n":16,"t":"看哪，我將你銘刻在我掌上，你的城牆常在我眼前。","notes":[]},{"n":17,"t":"建立你的勝過毀壞你的，使你荒廢的必都離你而去。","notes":["本節是根據死海古卷；原文是「你的兒女必急速歸回；毀壞你的，使你荒廢的，必都離你而去。」"]},{"n":18,"t":"你舉目向四圍觀看，他們都聚集來到你這裏。我指著我的永生起誓，你定要以他們為妝飾佩戴，帶著他們，像新娘一樣。這是耶和華說的。","notes":[]},{"n":19,"t":"至於你荒廢淒涼之處，並你被毀壞之地，如今居民必嫌太窄，吞滅你的必離你遙遠。","notes":[]},{"n":20,"t":"你要再聽見喪失子女後所生的兒女說：「這地方我居住太窄，請你給我地方居住。」","notes":[]},{"n":21,"t":"那時你心裏必說：「我既喪子不育，被擄，飄流在外，誰給我生了這些？誰將他們養大呢？看哪，我被撇下獨自一人時，他們都在哪裏呢？」","notes":["七十士譯本沒有「被擄，飄流在外」。"]},{"n":22,"t":"主耶和華如此說：「看哪，我必向列國舉手，向萬民豎立大旗；他們必將你的兒子抱在懷中帶來，將你的女兒背在肩上扛來。","notes":[]},{"n":23,"t":"列王必作你的養父，王后必作你的乳母。他們必以臉伏地，向你下拜，並舔你腳上的塵土。你就知道我是耶和華，等候我的必不致羞愧。」","notes":[]},{"n":24,"t":"勇士搶去的豈能奪回？被殘暴者擄掠的豈能得解救呢？","notes":[]},{"n":25,"t":"但耶和華如此說：「就是勇士所擄掠的，也可以奪回；殘暴者所搶的，也可以得解救。與你相爭的，我必與他相爭，我也要拯救你的兒女。","notes":[]},{"n":26,"t":"我必使那欺壓你的吃自己的肉，飲自己的血，如喝甜酒喝醉一樣。凡有血肉之軀的都必知道我－耶和華是你的救主，是你的救贖主，是雅各的大能者。」","notes":[]}]},"50":{"heading":"耶和華僕人的順服","verses":[{"n":1,"t":"耶和華如此說：「我休了你們的母親，她的休書在哪裏呢？我將你們賣給了我哪一個債主呢？看哪，你們被賣是因你們的罪孽；你們的母親被休，是因你們的過犯。","notes":[]},{"n":2,"t":"我來的時候，為何沒有人呢？我呼喚的時候，為何無人回應呢？我的膀臂豈是過短、不能救贖嗎？我豈無拯救之力嗎？看哪，我一斥責，海就乾了；我使江河變為曠野，其中的魚因無水腥臭，乾渴而死。","notes":[]},{"n":3,"t":"我使諸天以黑暗為衣，以麻布為遮蓋。」","notes":[]},{"n":4,"t":"主耶和華賜我受教者的舌頭，使我知道怎樣用言語扶助疲乏的人。主每天早晨喚醒，喚醒我的耳朵，使我能聽，像受教者一樣。","notes":[]},{"n":5,"t":"主耶和華開啟我的耳朵，我並未違背，也未退後。","notes":[]},{"n":6,"t":"人打我的背，我任他打；人拔我兩頰的鬍鬚，我由他拔；人侮辱我，向我吐唾沫，我並不掩面。","notes":[]},{"n":7,"t":"主耶和華必幫助我，所以我不抱愧。我硬著臉面好像堅石，也知道我必不致蒙羞。","notes":[]},{"n":8,"t":"稱我為義的與我相近；誰與我爭論，讓我們來對質；誰與我作對，讓他近前來吧！","notes":[]},{"n":9,"t":"看哪，主耶和華必幫助我，誰能定我有罪呢？看哪，他們都要像衣服漸漸破舊，被蛀蟲蛀光。","notes":[]},{"n":10,"t":"你們當中有誰是敬畏耶和華，聽從他僕人的話語，卻行在黑暗中，沒有亮光的，當倚靠耶和華的名，仰賴自己的神。","notes":[]},{"n":11,"t":"看哪，你們當中所有點火、以火把圍繞自己的人，當行走在你們的火焰裏，並你們所點的火把中。這是我親手為你們定的：你們必躺臥在悲慘之中。","notes":["「火焰」：七十士譯本和其他古譯本是「火光」。"]}]},"51":{"heading":"安慰錫安的話","verses":[{"n":1,"t":"追求公義、 尋求耶和華的人哪，當聽從我！你們要追想自己是從哪塊磐石鑿出，從哪個巖穴挖掘而來；","notes":[]},{"n":2,"t":"要追想你們的祖宗亞伯拉罕和生你們的撒拉；因為我選召亞伯拉罕時，他只有一個人，但我賜福給他，使他增多。","notes":[]},{"n":3,"t":"耶和華已經安慰錫安，安慰了錫安一切的廢墟，使曠野如伊甸，使沙漠像耶和華的園子；其中必有歡喜、快樂、感謝，和歌唱的聲音。","notes":[]},{"n":4,"t":"我的民哪，要留心聽我，我的國啊，要向我側耳；因為訓誨必從我而出，我必使我的公理成為萬民之光。","notes":[]},{"n":5,"t":"我的公義臨近，我的救恩發出。我的膀臂要審判萬民，眾海島都要等候我，倚賴我的膀臂。","notes":[]},{"n":6,"t":"你們要向天舉目，觀看下面的地；天必像煙雲消散，地必如衣服漸漸破舊；其上的居民也要如此死亡。惟有我的救恩永遠長存，我的公義也不廢掉。","notes":["「如此」：原文另譯「像蠓蟲」。"]},{"n":7,"t":"知道公義、將我的訓誨存在心中的人哪，當聽從我！不要怕人的辱罵，也不要因人的毀謗驚惶。","notes":[]},{"n":8,"t":"因為他們必像衣服被蛀蟲蛀；像羊毛被蟲子咬。惟有我的公義永遠長存，我的救恩直到萬代。","notes":[]},{"n":9,"t":"耶和華的膀臂啊，興起，興起！以能力為衣穿上，像古時的年日，像上古的世代一樣興起！從前砍碎拉哈伯、刺透大魚的，不是你嗎？","notes":["「拉哈伯」是神話故事中的大海怪。"]},{"n":10,"t":"使海與深淵的水乾涸，在海的深處開路，使救贖的民走過的，不是你嗎？","notes":[]},{"n":11,"t":"耶和華救贖的民必歸回，歌唱來到錫安；永恆的喜樂必歸到他們頭上。他們必得著歡喜快樂，憂傷嘆息盡都逃避。","notes":[]},{"n":12,"t":"我，惟有我是安慰你們的。你是誰，竟怕那必死的人，怕那生命如草的世人，","notes":[]},{"n":13,"t":"卻忘記鋪張諸天、立定地基、造你的耶和華？你因欺壓者圖謀毀滅所發的暴怒，終日害怕，其實那欺壓者的暴怒在哪裏呢？","notes":[]},{"n":14,"t":"被擄的即將得釋放，不至於死而下入地府，也不致缺乏食物。","notes":[]},{"n":15,"t":"我是耶和華－你的神，我攪動大海，使海中的波浪澎湃，萬軍之耶和華是我的名。","notes":[]},{"n":16,"t":"我已將我的話放在你口中，用我的手影遮蔽你，為要安定諸天，立定地基，並對錫安說：「你是我的百姓。」","notes":[]},{"n":17,"t":"耶路撒冷啊，興起，興起！站起來！你從耶和華手中喝了他憤怒的杯，那使人東倒西歪的杯，直到喝盡。","notes":[],"heads":["耶路撒冷苦難的終結"]},{"n":18,"t":"她所生育的孩子中，沒有一個攙她的；她所撫養的孩子中，沒有一個扶她的。","notes":[]},{"n":19,"t":"這雙重的災難臨到你，有誰憐憫你呢？破壞和毀滅，饑荒和戰爭臨到，我如何能安慰你呢？","notes":["「我如何能安慰你呢？」死海古卷和七十士譯本是「誰能安慰你呢？」"]},{"n":20,"t":"你的孩子發昏，在各街頭躺臥，如同網羅裏的羚羊，滿了耶和華的憤怒，滿了你神的斥責。","notes":[]},{"n":21,"t":"因此，你這困苦卻非因酒而醉的，當聽這話，","notes":[]},{"n":22,"t":"你的主，耶和華，就是為他百姓辯護的神如此說：「看哪，我已從你手中接過那使人東倒西歪的杯，就是我憤怒的杯，你必不再喝。","notes":[]},{"n":23,"t":"我必將這杯遞在苦待你的人手中。他們曾對你說：『你屈身，任我們踐踏過去吧！』你就以背為地，又如街道，任人走過。","notes":["「苦待你的人」：死海古卷和七十士譯本是「苦待你的人和壓迫你的人」。"]}]},"52":{"heading":"神要拯救耶路撒冷","verses":[{"n":1,"t":"錫安哪，興起！興起！穿上你的能力！聖城耶路撒冷啊，穿上你華美的衣服！因為從今以後，未受割禮、不潔淨的必不再進入你中間。","notes":[]},{"n":2,"t":"耶路撒冷啊，抖去塵埃，起來坐在王位上！被擄的錫安哪，解開你頸上的鎖鏈！","notes":["「錫安」：原文直譯「錫安女子」。"]},{"n":3,"t":"耶和華如此說：「你們白白地被賣，也必不用銀子贖回。」","notes":[]},{"n":4,"t":"主耶和華如此說：「先前我的百姓下到埃及，在那裏寄居，末後又有亞述人欺壓他們。","notes":[]},{"n":5,"t":"我的百姓既是白白地被擄，如今我在這裏做甚麼呢？這是耶和華說的。轄制他們的人歡呼，我的名終日不斷受褻瀆，這是耶和華說的。","notes":["「轄制他們的人歡呼」或譯「百姓的領袖哀號」。"]},{"n":6,"t":"因此，我的百姓必認識我的名；在那日，他們必知道說這話的就是我。看哪，是我！」","notes":[]},{"n":7,"t":"在山上報佳音，傳平安，報好信息，傳揚救恩，那人的腳蹤何等佳美啊！他對錫安說：「你的神作王了！」","notes":[]},{"n":8,"t":"聽啊，你守望之人的聲音，他們揚聲一同歡唱；因為他們必親眼看見耶和華返回錫安。","notes":[]},{"n":9,"t":"耶路撒冷的廢墟啊，要出聲一同歡唱；因為耶和華安慰了他的百姓，救贖了耶路撒冷。","notes":[]},{"n":10,"t":"耶和華在萬國眼前露出聖臂，地的四極都要看見我們神的救恩。","notes":[]},{"n":11,"t":"離開吧！離開吧！你們要從巴比倫出來。你們扛抬耶和華器皿的人哪，不要沾染不潔淨之物，離去時務要保持潔淨。","notes":[]},{"n":12,"t":"你們出來必不致匆忙，也不致奔逃；因為耶和華要在你們前頭行，以色列的神必作你們的後盾。","notes":[]},{"n":13,"t":"看哪，我的僕人行事必有智慧，他必被高升，高舉，升到至高之處。","notes":[],"heads":["受苦的僕人"]},{"n":14,"t":"許多人因他驚奇─他的面貌比別人憔悴，他的外表比世人枯槁─","notes":["「他」：原文是「你」。"]},{"n":15,"t":"同樣，他也必使許多國家驚奇，君王要向他閉口。未曾傳給他們的，他們必看見；未曾聽見過的事，他們要明白。","notes":["「他也必使許多國家驚奇」是根據七十士譯本 ；原文是 「他必洗淨許多國家」。"]}]},"53":{"heading":"","verses":[{"n":1,"t":"我們所傳的有誰信呢？耶和華的膀臂向誰顯露呢？","notes":[]},{"n":2,"t":"他在耶和華面前生長如嫩芽，像根出於乾地。他無佳形美容使我們注視他，也無美貌使我們仰慕他。","notes":[]},{"n":3,"t":"他被藐視，被人厭棄；多受痛苦，常經憂患。他被藐視，好像被人掩面不看的一樣，我們也不尊重他。","notes":[]},{"n":4,"t":"他誠然擔當我們的憂患，背負我們的痛苦；我們卻以為他受責罰，是被神擊打苦待。","notes":[]},{"n":5,"t":"他為我們的過犯受害，為我們的罪孽被壓傷。因他受的懲罰，我們得平安；因他受的鞭傷，我們得醫治。","notes":[]},{"n":6,"t":"我們都如羊走迷，各人偏行己路；耶和華使我們眾人的罪孽都歸在他身上。","notes":[]},{"n":7,"t":"他被欺壓受苦，卻不開口；他像羔羊被牽去宰殺，又像羊在剪毛的人手下無聲，他也是這樣不開口。","notes":[]},{"n":8,"t":"因受欺壓和審判，他被奪去，誰能想到他的世代呢？因為他從活人之地被剪除，為我百姓的罪過他被帶到死裏。","notes":["「我百姓」：死海古卷是「他的百姓」。","「他被帶到死裏」是根據七十士譯本；原文是「為他們受擊打」。","本節或譯「因受欺壓和審判，他被奪去，至於他同世的人，誰想他受鞭打、從活人之地被剪除，是因我百姓的罪過呢？」"]},{"n":9,"t":"他雖然未行殘暴，口中也沒有詭詐，人還使他與惡人同穴，與財主同墓。","notes":["「與財主同墓」是根據死海古卷；原文是「他死的時候與財主一起」。"]},{"n":10,"t":"耶和華的旨意要壓傷他，使他受苦。當他的生命作為贖罪祭時，他必看見後裔，他的年日必然長久。耶和華所喜悅的事，必在他手中亨通。","notes":["「當...贖罪祭時」或譯「當耶和華以他為贖罪祭時」。"]},{"n":11,"t":"因自己的勞苦，他必看見光就心滿意足。因自己的認識，我的義僕使許多人得稱為義，他要擔當他們的罪孽。","notes":["「光」是根據死海古卷和七十士譯本；原文沒有「光」。"]},{"n":12,"t":"因此，我要使他與位大的同份，與強盛的均分擄物。因為他傾倒自己的生命，以致於死，也列在罪犯之中。他卻擔當多人的罪，為他們的過犯代求。","notes":["「為他們的過犯代求」是根據死海古卷和七十士譯本；原文是「又為罪犯代求」。"]}]},"54":{"heading":"耶和華對以色列的愛","verses":[{"n":1,"t":"你這不懷孕、不生育的，要歡呼；你這未曾經過產難的，要歡呼，揚聲呼喊；因為被遺棄的婦人，比有丈夫的人兒女更多；這是耶和華說的。","notes":[]},{"n":2,"t":"要擴張你帳幕之地，伸展你居所的幔子，不要縮回；要放長你的繩子，堅固你的橛子。","notes":[]},{"n":3,"t":"因為你要向左向右開展，你的後裔必得列國為業，又使荒廢的城鎮有人居住。","notes":[]},{"n":4,"t":"不要懼怕，因你必不致蒙羞；不要抱愧，因你必不致受辱。你必忘記年輕時的羞愧，不再記得守寡的恥辱。","notes":[]},{"n":5,"t":"因為造你的是你的丈夫，萬軍之耶和華是他的名；救贖你的是以色列的聖者，他必稱為全地之神。","notes":[]},{"n":6,"t":"耶和華召你，如同召回心中憂傷遭遺棄的婦人，就是年輕時所娶被遺棄的妻子；這是你的神說的。","notes":[]},{"n":7,"t":"我離棄你不過片時，卻要大施憐憫將你尋回。","notes":[]},{"n":8,"t":"我因漲溢的怒氣，一時向你轉臉，但我要以永遠的慈愛憐憫你；這是耶和華－你的救贖主說的。","notes":[]},{"n":9,"t":"這事於我有如挪亞的洪水；我怎樣起誓不再使挪亞的洪水淹沒全地，也照樣起誓不再向你發怒，且不斥責你。","notes":[]},{"n":10,"t":"大山可以挪開，小山可以遷移，但我的慈愛必不離開你，我平安的約也不遷移；這是憐憫你的耶和華說的。","notes":[]},{"n":11,"t":"你這受困苦、被暴風捲走、不得憐憫的城，看哪，我必以灰泥來做你的石頭，以藍寶石立你的根基，","notes":[],"heads":["耶路撒冷的將來"]},{"n":12,"t":"又以紅寶石造你的女牆，以晶瑩的珠玉造你的城門，以珍貴的寶石造你四圍的邊界。","notes":[]},{"n":13,"t":"你的兒女都要領受耶和華的教導，你的兒女必大享平安。","notes":[]},{"n":14,"t":"你必因公義得堅立，必遠離欺壓，毫不懼怕；你必遠離驚嚇，驚嚇必不臨近你。","notes":[]},{"n":15,"t":"若有人攻擊你，這非出於我；凡攻擊你的，必因你仆倒。","notes":[]},{"n":16,"t":"看哪，我造了那吹炭火、打造合用兵器的鐵匠；我也造了那殘害人、行毀滅的人。","notes":[]},{"n":17,"t":"凡為攻擊你而造的兵器必無效用；在審判時興起用口舌攻擊你的，你必駁倒他。這是耶和華僕人的產業，是他們從我所得的義；這是耶和華說的。","notes":[]}]},"55":{"heading":"神要施憐憫","verses":[{"n":1,"t":"來！你們所有乾渴的，都當來到水邊；沒有銀錢的也可以來。你們都來，買了吃；不用銀錢，不付代價，就可買酒和奶。","notes":[]},{"n":2,"t":"你們為何花錢買那不是食物的東西，用勞碌得來的買那無法使人飽足的呢？你們要留意聽從我的話，就能吃那美物，得享肥甘，心中喜樂。","notes":[]},{"n":3,"t":"當側耳而聽，來到我這裏；要聽，就必存活。我要與你們立永約，就是應許給大衛那可靠的慈愛。","notes":[]},{"n":4,"t":"看哪，我已立他作萬民的見證，立他作萬民的君王和發令者。","notes":[]},{"n":5,"t":"看哪，你要召集素不認識的國民，素不認識的國民要奔向你；這都因耶和華─你的神，因以色列的聖者已經榮耀了你。","notes":[]},{"n":6,"t":"當趁耶和華可尋找的時候尋找他，在他接近的時候求告他。","notes":[]},{"n":7,"t":"惡人當離棄自己的道路，不義的人應除掉自己的意念。歸向耶和華，耶和華就必憐憫他；當歸向我們的神，因為他必廣行赦免。","notes":[]},{"n":8,"t":"我的意念非同你們的意念，我的道路非同你們的道路。這是耶和華說的。","notes":[]},{"n":9,"t":"天怎樣高過地，照樣，我的道路高過你們的道路，我的意念高過你們的意念。","notes":[]},{"n":10,"t":"雨雪從天而降，並不返回，卻要滋潤土地，使地面發芽結實，使撒種的有種，使要吃的有糧。","notes":[]},{"n":11,"t":"我口所出的話也必如此，絕不徒然返回，卻要成就我的旨意，達成我差它的目的。","notes":[]},{"n":12,"t":"你們必歡歡喜喜出來，平平安安蒙引導。大山小山必在你們面前歡呼，田野的樹木也都拍掌。","notes":[]},{"n":13,"t":"松樹長出，代替荊棘；番石榴長出，代替蒺藜。這要為耶和華留名，作為永不磨滅的證據。","notes":[]}]},"56":{"heading":"神的子民將遍及各國","verses":[{"n":1,"t":"耶和華如此說：「你們當守公平，行公義；因我的救恩臨近，我的公義將要顯現。","notes":[]},{"n":2,"t":"謹守安息日不予干犯，禁止己手不作惡，如此行、如此持守的人有福了！」","notes":[]},{"n":3,"t":"與耶和華聯合的外邦人不要說：「耶和華將我和他的子民分別出來。」太監也不要說：「看哪，我是枯樹。」","notes":[]},{"n":4,"t":"因為耶和華如此說：「那些謹守我的安息日，選擇我旨意，持守我約的太監，","notes":[]},{"n":5,"t":"我必使他們在我殿中，在我牆內，有紀念碑，有名號，勝過有兒有女；我必賜他們永遠的名，不能剪除。","notes":[]},{"n":6,"t":"「那些與耶和華聯合，事奉他，愛他名，作他僕人的外邦人，凡謹守安息日不予干犯，又持守我約的人，","notes":[]},{"n":7,"t":"我必領他們到我的聖山，使他們在我的禱告的殿中喜樂。他們的燔祭和祭物，在我壇上必蒙悅納，因我的殿必稱為萬民禱告的殿。","notes":[]},{"n":8,"t":"我還要召集更多的人歸併到這些被召集的人中。這是召集被趕散的以色列人的主耶和華說的。」","notes":[]},{"n":9,"t":"野地的走獸，你們都來吞吃吧！林中的野獸，你們也來吞吃！","notes":[],"heads":["以色列的領袖被定罪"]},{"n":10,"t":"以色列的守望者都瞎了眼，沒有知識；都是啞狗，不會吠叫，只知做夢，躺臥，貪睡，","notes":[]},{"n":11,"t":"這些狗貪食，不知飽足。這些牧人不知明辨，他們都偏行己路，人人追求自己的利益。","notes":[]},{"n":12,"t":"他們說：「來吧！我去拿酒，讓我們暢飲烈酒吧！明天必和今天一樣，甚至更好！」","notes":[]}]},"57":{"heading":"以色列拜偶像被定罪","verses":[{"n":1,"t":"義人死亡，無人放在心上；虔誠的人被接去，無人理解；義人被接去，以免禍患。","notes":[]},{"n":2,"t":"行為正直的人進入平安，得以在床上安歇。","notes":["「在床上安歇」或譯「在墳裏安息」。"]},{"n":3,"t":"到這裏來吧！你們這些巫婆的兒子，姦夫和妓女的後代；","notes":[]},{"n":4,"t":"你們向誰戲笑？向誰張口吐舌呢？你們豈不是叛逆所生的兒女，虛謊所生的後代嗎？","notes":[]},{"n":5,"t":"你們在橡樹中間，在各青翠的樹下慾火攻心；在山谷間，在巖隙下殺了兒女；","notes":["「橡樹」或譯「神像」。"]},{"n":6,"t":"去拜谷中光滑的石頭有你們的份，這些就是你們的命運。你向它們獻澆酒祭，獻供物，這事我豈能容忍嗎？","notes":[]},{"n":7,"t":"你在高而又高的山上安設床舖，上那裏去獻祭。","notes":[]},{"n":8,"t":"你在門後，在門框後，立起你的牌來；你離棄了我，赤露己身，又爬上自己所鋪寬闊的床鋪，與它們立約；你喜愛它們的床，看著它們的赤體。","notes":["「赤體」：原文是「手」。"]},{"n":9,"t":"你帶了油到摩洛那裏，加上許多香水。你派遣使者往遠方去，甚至降到陰間，","notes":["「摩洛」或譯「王」。"]},{"n":10,"t":"因路途遙遠，你就疲倦，卻不說，這是枉然，以為能找到復興之力，所以不覺疲憊。","notes":[]},{"n":11,"t":"你怕誰，因誰恐懼，竟說謊，不記得我，不將這事放在心上。是否因我許久閉口不言，你就不怕我了呢？","notes":[]},{"n":12,"t":"我可以宣告你的公義和你的作為，但它們與你無益。","notes":[]},{"n":13,"t":"你哀求的時候，讓你所搜集的神像拯救你吧！風要把它們全都颳散，吹一口氣就都吹走。但那投靠我的必得地產，承受我的聖山為業。","notes":["原文沒有「神像」。"]},{"n":14,"t":"耶和華說：「你們要修築，修築，要預備道路，除掉我百姓路中的絆腳石。」","notes":[],"heads":["神應許幫助和醫治"]},{"n":15,"t":"那至高無上、永遠長存、名為聖者的如此說：「我住在至高至聖的所在，卻與心靈痛悔的謙卑人同住；要使謙卑的人心靈甦醒，使痛悔的人內心復甦。","notes":[]},{"n":16,"t":"我必不長久控訴，也不永遠懷怒，因為我雖使靈性發昏，我也造了人的氣息。","notes":[]},{"n":17,"t":"我因人貪婪的罪孽，發怒擊打他；我轉臉向他發怒，他卻仍隨意背道而行。","notes":[]},{"n":18,"t":"我看見他的行為，要醫治他，引導他，使他和與他一同哀傷的人都得安慰。","notes":["「引導他」：七十士譯本是「安慰他」。"]},{"n":19,"t":"我要醫治他，他要結出嘴唇的果實。平安，平安，歸給遠處和近處的人！這是耶和華說的。」","notes":[]},{"n":20,"t":"但是惡人好像翻騰的海，不得平靜；其中的水常湧出污穢和淤泥。","notes":[]},{"n":21,"t":"我的神說：「惡人必不得平安！」","notes":[]}]},"58":{"heading":"真正的禁食","verses":[{"n":1,"t":"你要大聲喊叫，不要停止；要揚聲，好像吹角；向我的百姓宣告他們的過犯，向雅各家陳述他們的罪惡。","notes":[]},{"n":2,"t":"他們天天尋求我，樂意明白我的道，好像行義的國家，未離棄它的神的典章；他們向我求問公義的判詞，喜悅親近神。","notes":[]},{"n":3,"t":"「我們禁食，你為何不看呢？我們刻苦己心，你為何不理會呢？」看哪，你們禁食的時候仍追求私利，剝削為你們做苦工的人。","notes":[]},{"n":4,"t":"看哪，你們禁食，卻起紛爭興訟，以兇惡的拳頭打人。你們今日這種禁食無法使你們的聲音聽聞於高處。","notes":[]},{"n":5,"t":"這豈是我所要的禁食，為人所用以刻苦己心的日子嗎？我難道只是叫人如蘆葦般低頭，鋪上麻布和灰燼嗎？你能稱此為禁食，為耶和華所悅納的日子嗎？","notes":[]},{"n":6,"t":"我所要的禁食，豈不是要你鬆開兇惡的繩，解開軛上的索，使被欺壓的得自由，折斷一切的軛嗎？","notes":[]},{"n":7,"t":"豈不是要你把食物分給飢餓的人，將流浪的窮人接到家中，見赤身的給他衣服遮體，而不隱藏自己避開你的骨肉嗎？","notes":[]},{"n":8,"t":"這樣，必有光如晨光破曉照耀你，你也要快快得到醫治；你的公義在你前面行，耶和華的榮光必作你的後盾。","notes":[]},{"n":9,"t":"那時你求告，耶和華必應允；你呼求，他必說：「我在這裏。」你若從你中間除掉重軛和指摘人的指頭，並發惡言的事，","notes":[]},{"n":10,"t":"向飢餓的人施憐憫，使困苦的人得滿足；你在黑暗中就必得著光明，你的幽暗必變如正午。","notes":[]},{"n":11,"t":"耶和華必時常引導你，在乾旱之地使你心滿意足，又使你骨頭強壯。你必如有水澆灌的園子，又像水流不絕的泉源。","notes":[]},{"n":12,"t":"你們中間必有人起來修造久已荒廢之處，立起代代相承的根基。你必稱為修補裂痕的，和重修路徑給人居住的。","notes":[]},{"n":13,"t":"你若禁止自己的腳踐踏安息日，不在我的聖日做自己高興的事，稱安息日為「可喜樂的」，稱耶和華的聖日為「可尊重的」，尊敬這日，不走自己的道路，不求自己的喜悅，也不隨意說話；","notes":[],"heads":["守安息日者的報償"]},{"n":14,"t":"那麼，你就會以耶和華為樂。耶和華要使你乘駕於地的高處，又要以你祖先雅各的產業養育你；這是耶和華親口說的。","notes":[]}]},"59":{"heading":"先知指責百姓的罪惡","verses":[{"n":1,"t":"看哪，耶和華的膀臂並非過短，不能拯救，耳朵並非發沉，不能聽見，","notes":[]},{"n":2,"t":"但你們的罪孽使你們與神隔絕，你們的罪惡使他轉臉不聽你們。","notes":[]},{"n":3,"t":"因你們的手掌被血沾染，你們的指頭被罪玷污，你們的嘴唇說謊言，你們的舌頭出惡語。","notes":[]},{"n":4,"t":"無人按公義控訴，也無人憑誠實辯白；卻倚靠虛妄，口說謊言，懷毒害，生罪孽。","notes":[]},{"n":5,"t":"他們孵毒蛇蛋，結蜘蛛網。凡吃這蛋的必死，蛋一打破，就孵出蛇來。","notes":[]},{"n":6,"t":"所結的網不能當衣服，無法掩蓋自己所作所為。他們的行為全是邪惡，手所做的盡都殘暴。","notes":[]},{"n":7,"t":"他們的腳奔跑行惡，急速流無辜者的血；他們的思想全是惡念，走過的路盡是破壞與毀滅。","notes":[]},{"n":8,"t":"平安的路，他們不知道，所行的事無一公平。他們為自己修築彎曲的路，凡走這路的都不得平安。","notes":[]},{"n":9,"t":"因此，公平離我們甚遠，公義追不上我們。我們指望光亮，看哪，卻只有黑暗，指望光明，卻行在幽暗中。","notes":[],"heads":["百姓悔罪"]},{"n":10,"t":"我們用手摸牆，好像盲人，四處摸索，如同失明的人；中午時我們絆倒，如在黃昏一樣，在強壯的人中，我們好像死人一般。","notes":[]},{"n":11,"t":"我們全都咆哮如熊，哀鳴如鴿子；指望公平，卻得不著；指望救恩，它卻遠離。","notes":[]},{"n":12,"t":"我們的過犯在你面前增加，罪惡作證控告我們；過犯與我們同在。至於我們的罪孽，我們都知道：","notes":[]},{"n":13,"t":"就是悖逆，否認耶和華，轉去不跟從我們的神，口說欺壓和叛逆的話，心懷謊言，隨即說出；","notes":[]},{"n":14,"t":"公平轉而退後，公義站在遠處，誠實仆倒在廣場上，正直不得進入；","notes":[]},{"n":15,"t":"誠實少見，離棄邪惡的人反成掠物。那時，耶和華見沒有公平，就不喜悅。","notes":[]},{"n":16,"t":"他見無人，竟無一人代求，甚為詫異，就用自己的膀臂拯救他，以公義扶持他。","notes":[]},{"n":17,"t":"他穿上公義為鎧甲，戴上救恩為頭盔，穿上報復為衣服，披戴熱心為外袍。","notes":[]},{"n":18,"t":"他必按人的行為報應，惱怒他的敵人，報復他的仇敵，向眾海島施行報應。","notes":[]},{"n":19,"t":"在日落之處，人必敬畏耶和華的名；在日出之地，人必敬畏他的榮耀。他必如湍急的河流沖來，耶和華的靈催逼他自己。","notes":[]},{"n":20,"t":"必有一位救贖主來到錫安，來到雅各族中離棄過犯的人那裏；這是耶和華說的。","notes":[]},{"n":21,"t":"耶和華說：「這就是我與他們所立的約：我加給你的靈，傳給你的話，必不離你的口，也不離你後裔與你後裔之後裔的口，從今直到永遠；這是耶和華說的。」","notes":[]}]},"60":{"heading":"耶路撒冷未來的榮耀","verses":[{"n":1,"t":"興起，發光！因為你的光已來到！耶和華的榮光發出照耀著你。","notes":[]},{"n":2,"t":"看哪，黑暗籠罩大地，幽暗遮蓋萬民，耶和華卻要升起照耀你，他的榮光要顯在你身上。","notes":[]},{"n":3,"t":"列國要來就你的光，列王要來就你發出的光輝。","notes":[]},{"n":4,"t":"你舉目向四圍觀看，眾人都聚集到你這裏。你的兒子從遠方來，你的女兒也被抱著帶來。","notes":[]},{"n":5,"t":"那時，你看見就有光榮，你的心興奮歡暢；因為大海那邊的財富必歸你，列國的財寶也來歸你。","notes":["「歡暢」：原文是「寬闊」。"]},{"n":6,"t":"成群的駱駝，並米甸和以法的獨峰駝遮滿你；示巴的眾人都必來到，要奉上黃金和乳香，又要傳揚讚美耶和華的話。","notes":[]},{"n":7,"t":"基達的羊群都聚集到你這裏，尼拜約的公羊供你使用，獻在我壇上蒙悅納；我必榮耀我那榮耀的殿。","notes":[]},{"n":8,"t":"那些飛來如雲、又像鴿子飛向窗戶的是誰呢？","notes":[]},{"n":9,"t":"眾海島必等候我，他施的船隻領先，將你的兒女，連同他們的金銀從遠方帶來，這都因以色列的聖者、耶和華－你神的名，因為他已經榮耀了你。","notes":["「眾海島必等候我」：原文另譯「眾海島的船隻聚集」。"]},{"n":10,"t":"外邦人要建造你的城牆，他們的君王必服事你。我曾發怒擊打你，如今卻施恩憐憫你。","notes":[]},{"n":11,"t":"你的城門必時常開放，晝夜不關，使人將列國的財物帶來歸你，他們的君王也被牽引而來。","notes":[]},{"n":12,"t":"不事奉你的那邦、那國要滅亡，那些國家必全然荒廢。","notes":[]},{"n":13,"t":"黎巴嫩的榮耀，就是松樹、杉樹、黃楊樹，都必一同歸你，用以裝飾我聖所坐落之處；我也要使我腳所踏之地得榮耀。","notes":[]},{"n":14,"t":"壓制你的，他的子孫必來向你屈身；藐視你的，都要在你腳前下拜。人要稱你為「耶和華的城」，為「以色列聖者的錫安」。","notes":[]},{"n":15,"t":"你雖曾被拋棄，被恨惡，甚至無人經過，我卻使你有永遠的榮華，成為世世代代的喜樂。","notes":[]},{"n":16,"t":"你要吃列國的奶，吃列王的乳。你就知道我－耶和華是你的救主，是你的救贖主，是雅各的大能者。","notes":[]},{"n":17,"t":"我要賞賜金子代替銅，賞賜銀子代替鐵，銅代替木頭，鐵代替石頭。我要以和平為你的官長，以公義為你的監督。","notes":[]},{"n":18,"t":"你的地不再聽聞殘暴的事，境內不再聽見破壞與毀滅。你必稱你的牆為「拯救」，稱你的門為「讚美」。","notes":[]},{"n":19,"t":"白晝太陽不再作你的光，月亮也不再發光照耀你；耶和華卻要作你永遠的光，你的神要成為你的榮耀。","notes":["「月亮」：有古卷和七十士譯本是「夜晚月亮」。"]},{"n":20,"t":"你的太陽不再落下，月亮也不消失；因為耶和華必作你永遠的光。你悲哀的日子定要結束。","notes":[]},{"n":21,"t":"你的居民全是義人，永遠得地為業；他們是我栽的苗，是我手的工作，為了彰顯我的榮耀。","notes":[]},{"n":22,"t":"稀少的要成為大族，弱小的要變為強國。我－耶和華到了時候必速速成就這事。","notes":[]}]},"61":{"heading":"拯救的好消息","verses":[{"n":1,"t":"主耶和華的靈在我身上，因為耶和華用膏膏我，叫我報好信息給貧窮的人，差遣我醫好傷心的人，報告被擄的得釋放，被捆綁的得自由；","notes":[]},{"n":2,"t":"宣告耶和華的恩年和我們的神報仇的日子；安慰所有悲哀的人，","notes":[]},{"n":3,"t":"為錫安悲哀的人，賜華冠代替灰燼，喜樂的油代替悲哀，讚美為衣代替憂傷的靈；稱他們為「公義樹」，是耶和華所栽植的，為要彰顯他的榮耀。","notes":[]},{"n":4,"t":"他們必修造久已荒涼的廢墟，建立先前淒涼之處，重修歷代荒涼之城。","notes":[]},{"n":5,"t":"那時，陌生人要伺候、牧放你們的羊群；外邦人必為你們耕種田地，修整你們的葡萄園。","notes":[]},{"n":6,"t":"但你們要稱為「耶和華的祭司」，稱作「我們神的僕人」。你們必享用列國的財物，必承受他們的財富。","notes":["「必...財富」：死海古卷和七十士譯本是「因得他們的榮耀自誇」。"]},{"n":7,"t":"因為他們所受雙倍的羞辱，凌辱被稱為他們的命運，因此，他們在境內必得雙倍的產業，永遠之樂必歸給他們。","notes":[]},{"n":8,"t":"因為我－耶和華喜愛公平，恨惡搶奪與惡行；我要憑誠實施行報償，與我的百姓立永約。","notes":["「恨惡搶奪與惡行」：有古卷是「恨惡搶奪又獻燔祭」。"]},{"n":9,"t":"他們的後裔必在列國中為人所知，他們的子孫在萬民中為人所識；凡看見他們的必承認他們是耶和華所賜福的後裔。","notes":[]},{"n":10,"t":"我因耶和華大大歡喜，我的心因神喜樂；因他以拯救為衣給我穿上，以公義為外袍給我披上，好像新郎戴上華冠，又如新娘佩戴首飾。","notes":[]},{"n":11,"t":"地怎樣使芽長出，園子怎樣使所栽種的生長，主耶和華也必照樣使公義和讚美在萬國中發出。","notes":[]}]},"62":{"heading":"","verses":[{"n":1,"t":"我因錫安必不靜默，為耶路撒冷必不安寧，直到它的公義如光輝發出，它的救恩如火把燃燒。","notes":[]},{"n":2,"t":"列國要看見你的公義，列王要看見你的榮耀。你必得新的名字，是耶和華親口起的。","notes":[]},{"n":3,"t":"你在耶和華的手中成為華冠，在你神的掌上成為冠冕。","notes":[]},{"n":4,"t":"你不再稱為「被撇棄的」，你的地也不再稱為「荒蕪的」；你要稱為「我所喜悅的」，你的地要稱為「有歸屬的」。因為耶和華喜悅你，你的地必歸屬於他。","notes":[]},{"n":5,"t":"年輕人怎樣娶童女，你的百姓也要照樣娶你；新郎怎樣因新娘而喜樂，你的神也要如此以你為樂。","notes":[]},{"n":6,"t":"耶路撒冷啊，我在你城牆上設立守望者，他們晝夜不停地呼喊。呼求耶和華的啊，你們不要歇息，","notes":[]},{"n":7,"t":"也不要使他歇息，直等他建立耶路撒冷，使耶路撒冷在地上為人所讚美。","notes":[]},{"n":8,"t":"耶和華指著自己的右手和大能的膀臂起誓說：「我必不再將你的五穀給仇敵作食物，外邦人也必不再喝你勞碌得來的新酒。","notes":[]},{"n":9,"t":"惟有那收割的要吃，並讚美耶和華；那儲藏葡萄的要在我聖所院內喝。」","notes":[]},{"n":10,"t":"你們當從門經過，經過，預備百姓的路。你們要修築，修築大道，清除石頭，為萬民豎立大旗。","notes":[]},{"n":11,"t":"看哪，耶和華曾宣告到地極，你們要對錫安說：「看哪，你的拯救者已來到。看哪，他的賞賜在他那裏，他的報償在他面前。」","notes":["「錫安」：原文直譯「錫安女子」。"]},{"n":12,"t":"人稱他們為「聖民」，為「耶和華救贖的民」，你也必稱為「受眷顧的」，為「不被撇棄的城」。","notes":[]}]},"63":{"heading":"耶和華恩待以色列","verses":[{"n":1,"t":"這從以東的波斯拉來，穿紅衣服，裝扮華美，能力廣大，大步向前邁進的是誰呢？就是我，憑公義說話，以大能施行拯救的。","notes":[]},{"n":2,"t":"你為何以紅色裝扮？你的衣服為何像踹醡酒池的人呢？","notes":[]},{"n":3,"t":"我獨自踹醡酒池，萬民中並無一人與我同在。我發怒，將他們踹下，發烈怒將他們踐踏。他們的血濺在我的衣服上，玷污了我一切的衣裳。","notes":[]},{"n":4,"t":"因為報仇之日在我心中，救贖我民之年已經來到。","notes":[]},{"n":5,"t":"我仰望，見無人幫助；我詫異，竟無人扶持。因此，我的膀臂為我施行拯救；我的烈怒將我扶持。","notes":[]},{"n":6,"t":"我發怒，踹下眾民；發烈怒，使他們喝醉，又將他們的血倒在地上。","notes":[]},{"n":7,"t":"我要照耶和華一切所賜給我們的，並他憑憐憫與豐盛的慈愛所賜給以色列家的大恩，述說他的慈愛和美德。","notes":[],"heads":["耶和華憐憫以色列"]},{"n":8,"t":"他說：「他們誠然是我的百姓，未行虛假的子民。」這樣，他就作了他們的救主。","notes":[]},{"n":9,"t":"他們在一切苦難當中，他也同受苦難，並且他面前的使者拯救他們。他以慈愛和憐憫救贖他們，在古時的日子時常抱他們，背他們。","notes":["「他也...拯救他們」：七十士譯本是「沒有使者或天使，只有主親自拯救他們」。"]},{"n":10,"t":"他們竟然悖逆，使他的聖靈憂傷。他就轉變，成為他們的仇敵，親自攻擊他們。","notes":[]},{"n":11,"t":"那時，他的百姓想起古時摩西的日子：「那將百姓和牧養群羊的人從海裏領上來的在哪裏呢？那將聖靈降在他們中間，","notes":[]},{"n":12,"t":"以榮耀的膀臂在摩西右邊行動，在百姓面前將水分開，為要建立自己永遠的名，","notes":[]},{"n":13,"t":"又帶領他們經過深處的在哪裏呢？」他們如馬行走曠野，不致絆跌；","notes":[]},{"n":14,"t":"又如牲畜下到山谷，耶和華的靈使他們得安息；照樣，你也引導你的百姓，為要建立自己榮耀的名。","notes":[]},{"n":15,"t":"求你從天上，從你神聖榮耀的居所垂顧觀看。你的熱心和你大能的作為在哪裏呢？你內心的關懷和你的憐憫向我們停止了。","notes":[],"heads":["求主憐憫幫助"]},{"n":16,"t":"亞伯拉罕雖然不承認我們，以色列也不承認我們，你卻是我們的父。耶和華啊，你是我們的父；自古以來，你的名是「我們的救贖主」。","notes":[]},{"n":17,"t":"耶和華啊，你為何使我們偏離你的道，使我們心裏剛硬、不敬畏你呢？求你為你的僕人，為你產業的支派而回轉。","notes":[]},{"n":18,"t":"你的聖民暫時得你的聖所，但我們的敵人踐踏了它。","notes":["本節或譯「我們的敵人暫時趕出你的聖民，他們踐踏了你的聖所。」"]},{"n":19,"t":"我們就成了你未曾治理的人，成了未曾稱為你名下的人。","notes":[]}]},"64":{"heading":"","verses":[{"n":1,"t":"願你破天而降，願山在你面前震動，","notes":[]},{"n":2,"t":"好像火燒乾柴，又如火將水燒開，使你敵人知道你的名，列國必在你面前發顫！","notes":[]},{"n":3,"t":"你曾做我們不能逆料可畏的事；那時你降臨，山嶺在你面前震動。","notes":[]},{"n":4,"t":"自古以來，人未曾聽見，未曾耳聞，未曾眼見，除你以外，還有神能為等候他的人行事。","notes":[]},{"n":5,"t":"你迎見那歡喜行義、記念你道的人；看哪，你曾發怒，因我們犯了罪；這景況已久，我們還能得救嗎？","notes":[]},{"n":6,"t":"我們都如不潔淨的人，所行的義都像污穢的衣服。我們如葉子漸漸枯乾，罪孽像風把我們吹走。","notes":[]},{"n":7,"t":"無人求告你的名，無人奮力抓住你。你轉臉不顧我們，你使我們因罪孽而融化。","notes":["「你使...融化」：七十士譯本和其他古譯本是「你把我們交給罪孽」。"]},{"n":8,"t":"但耶和華啊，現在你仍是我們的父！我們是泥，你是陶匠；我們都是你親手所造的。","notes":[]},{"n":9,"t":"耶和華啊，求你不要大發震怒，也不要永遠記得罪孽；看哪，求你垂顧我們，因我們都是你的百姓。","notes":[]},{"n":10,"t":"你的聖城已變為曠野；錫安變為曠野，耶路撒冷成為廢墟。","notes":[]},{"n":11,"t":"我們那神聖華美的殿，就是我們祖先讚美你的地方，已被火焚燒；我們所羨慕的美地盡都荒蕪。","notes":[]},{"n":12,"t":"耶和華啊，有這些事，你還能忍受嗎？你還靜默，使我們大受苦難嗎？","notes":[]}]},"65":{"heading":"神懲罰悖逆者","verses":[{"n":1,"t":"「沒有求問我的，我要讓他們找到；沒有尋找我的，我要讓他們尋見；我對沒有呼求我名的國說：『我在這裏！我在這裏！』","notes":["「我對...的國」是根據死海古卷；原文是「我對沒有稱為我名下的國」。"]},{"n":2,"t":"我整天向那悖逆的百姓招手，他們隨自己的意念行不善之道。","notes":[]},{"n":3,"t":"這百姓時常當面惹我發怒，在園中獻祭，在磚上燒香，","notes":[]},{"n":4,"t":"在墳墓間停留，在隱密處過夜，吃豬肉，器皿中有不潔淨之肉熬的湯；","notes":[]},{"n":5,"t":"且對人說：『你站開吧！不要挨近我，因為我對你來說太神聖了。』這些人惹我鼻中冒煙，如終日燃燒的火。","notes":["「我對你...神聖了」：原文另譯「我會使你成為聖」。"]},{"n":6,"t":"看哪，這些都寫在我面前。我必不靜默，卻要施行報應，將你們和你們祖先的罪孽全都報應在後人身上；因為他們在山上燒香，在岡上褻瀆我，我要按他們先前所行的，報應在他們身上；這是耶和華說的。」","notes":["「身上」：原文是「懷中」。"],"end":7},{"n":8,"t":"耶和華如此說：「人在葡萄中尋得新酒時會說：『不要毀壞它，因為它還有用處』；同樣，我必因我僕人的緣故，不將他們全然毀滅。","notes":[]},{"n":9,"t":"我必從雅各中領出後裔，從猶大中領出那要繼承我眾山的；我的選民要繼承它，我的僕人要在那裏居住。","notes":[]},{"n":10,"t":"沙崙必成為羊群的圈，亞割谷成為牛群躺臥之處，都為尋求我的民所得。","notes":[]},{"n":11,"t":"但你們這些離棄耶和華，就是忘記我的聖山、為『幸運之神』擺設筵席、為『命運之神』裝滿調和酒的，","notes":[]},{"n":12,"t":"我命定你們歸於刀下，你們都要屈身被殺；因為我呼喚，你們不回應；我說話，你們不聽從；反倒做我眼中看為惡的事，選擇我所不喜悅的事。」","notes":[]},{"n":13,"t":"所以，主耶和華如此說：「看哪，我的僕人必得吃，你們卻飢餓；看哪，我的僕人必得喝，你們卻乾渴；看哪，我的僕人必歡喜，你們卻蒙羞。","notes":[]},{"n":14,"t":"看哪，我的僕人因心中喜樂而歡呼，你們卻因心裏悲痛而哀哭，因靈裏憂傷而哀號。","notes":[]},{"n":15,"t":"你們必留下自己的名給我選民指著賭咒：主耶和華必殺你們，另起別名稱呼他的僕人。","notes":[]},{"n":16,"t":"在地上為自己求福的，必憑真實的神求福；在地上起誓的，必指著真實的神起誓。因為從前的患難已被遺忘，從我眼前消逝。」","notes":[]},{"n":17,"t":"「看哪，我造新天新地！從前的事不再被記念，也不被人放在心上；","notes":[],"heads":["新天新地"]},{"n":18,"t":"當因我所造的歡喜快樂，直到永遠；看哪，因為我造耶路撒冷為人所喜，造其中的居民為人所樂。","notes":[]},{"n":19,"t":"我必因耶路撒冷歡喜，因我的百姓快樂，那裏不再聽見哭泣和哀號的聲音。","notes":[]},{"n":20,"t":"那裏沒有數日夭折的嬰孩，也沒有壽數不滿的老人；因為百歲死的仍算孩童，未達百歲而亡的算是被詛咒的。","notes":["「未達百歲而亡的」或譯「百歲死的罪人」。"]},{"n":21,"t":"他們建造房屋，居住其中，栽葡萄園，吃園中的果子；","notes":[]},{"n":22,"t":"並非造了給別人居住，也非栽種給別人享用；因為我百姓的日子必長久如樹木，我的選民必享受親手勞碌得來的。","notes":[]},{"n":23,"t":"他們必不徒然勞碌，所生產的，也不遭災害，因為他們和他們的子孫都是蒙耶和華賜福的後裔。","notes":[]},{"n":24,"t":"他們尚未求告，我就應允；正說話的時候，我就垂聽。","notes":[]},{"n":25,"t":"野狼必與羔羊同食，獅子必吃草，與牛一樣，蛇必以塵土為食物；在我聖山的遍處，牠們都不傷人，也不害物；這是耶和華說的。」","notes":[]}]},"66":{"heading":"耶和華審判萬民","verses":[{"n":1,"t":"耶和華如此說：「天是我的座位；地是我的腳凳。你們能為我造怎樣的殿宇呢？哪裏是我安歇的地方呢？","notes":[]},{"n":2,"t":"這一切是我手所造的，這一切就都存在了。我所看顧的是困苦、靈裏痛悔、因我言語而戰兢的人。這是耶和華說的。","notes":[]},{"n":3,"t":"「至於那些宰牛，殺人，獻羔羊，打斷狗頸項，獻豬血為供物，燒乳香，稱頌偶像的，他們選擇自己的道路，心裏喜愛可憎惡的事；","notes":[]},{"n":4,"t":"我也必選擇苦待他們，使他們所懼怕的臨到他們；因為我呼喚，無人回應；我說話，他們不聽從；反倒做我眼中看為惡的事，選擇我所不喜悅的事。」","notes":[]},{"n":5,"t":"你們因耶和華言語而戰兢的人哪，當聽他的話：「你們的弟兄，就是恨惡你們，因我名趕出你們的，曾說：『願耶和華彰顯榮耀，好讓我們看見你們的喜樂。』但蒙羞的終究是他們！","notes":["「願耶和華彰顯榮耀」：七十士譯本是「願主的名得榮耀」。"]},{"n":6,"t":"「有喧嘩的聲音出自城中！有聲音來自殿裏！是耶和華向仇敵施行報應的聲音！","notes":[]},{"n":7,"t":"「錫安未曾陣痛就生產，疼痛尚未來到，就生出男孩。","notes":[]},{"n":8,"t":"國豈能一日而生？民豈能一時而產？但錫安一陣痛就生下兒女，這樣的事有誰聽見，有誰看見呢？","notes":[]},{"n":9,"t":"耶和華說：我使人臨產，豈不讓她生產呢？你的神說：我使人生產，難道還讓她關閉不生嗎？","notes":["「她」：本修訂版的「國」和「城」的代名詞都用「它」；本章用「她」。","「關閉」意思是「關閉子宮」。"]},{"n":10,"t":"「你們所有愛慕耶路撒冷的啊，要與她一同歡喜，為她高興；你們所有為她悲哀的啊，都要與她一同樂上加樂；","notes":[]},{"n":11,"t":"使你們在她安慰的懷中吃奶得飽，盡情吸取她豐盛的榮耀，滿心喜樂。」","notes":[]},{"n":12,"t":"耶和華如此說：「看哪，我要使平安臨到她，好像江河；使列國的榮耀及於她，如同漲溢的溪流。你們要盡情吸吮；你們必被抱在身旁，搖弄在膝上。","notes":["「你們要...身旁」：七十士譯本是「她的孩子必舉在肩膀上」。"]},{"n":13,"t":"我要安慰你們，如同母親安慰兒女；你們也必在耶路撒冷得安慰。","notes":[]},{"n":14,"t":"你們看見，心裏就喜樂，你們的骨頭必如草生長；耶和華的手在他僕人身上彰顯，他卻要向他的仇敵發怒。」","notes":[]},{"n":15,"t":"看哪，耶和華必在火中降臨，他的戰車宛如暴風，以烈怒施行報應，以火焰施行責罰；","notes":[]},{"n":16,"t":"耶和華必以火與刀審判凡有血肉之軀的，被耶和華所殺的很多。","notes":[]},{"n":17,"t":"「那些潔淨自己獻給偶像，進入園內，跟隨在其中一個人去吃豬肉和鼠肉，並可憎之物的，他們必一同滅絕。這是耶和華說的。","notes":[]},{"n":18,"t":"「我知道他們的行為和他們的意念。聚集萬國萬族的時候到了，他們要來瞻仰我的榮耀；","notes":["「族」：原文是「舌頭」，即「語言」。","「聚集...到了」：七十士譯本是「我要來聚集萬國萬族」。"]},{"n":19,"t":"我要在他們中間顯神蹟，差遣他們當中的倖存者到列國去，就是到他施、普勒、以善射聞名的路德、土巴、雅完，和未曾聽見我名聲，未曾看見我榮耀的遙遠海島那裏去；他們必在列國中傳揚我的榮耀。","notes":["「普勒」：七十士譯本是「普特」，現在的利比亞。","「以善射聞名的路德」：七十士譯本是「路德、默舍克」。"]},{"n":20,"t":"他們要將你們的弟兄從列國中帶回，或騎馬，或坐車，或乘蓬車，或騎騾子，或騎獨峰駝，到我的聖山耶路撒冷，作為供物獻給耶和華。這是耶和華說的。正如以色列人用潔淨的器皿盛供物奉到耶和華的殿中，","notes":[]},{"n":21,"t":"我也必從他們中間立人作祭司，作利未人。這是耶和華說的。","notes":[]},{"n":22,"t":"「我所造的新天新地在我面前長存，你們的後裔和你們的名號也必照樣長存。這是耶和華說的。","notes":[]},{"n":23,"t":"每逢初一、安息日，凡有血肉之軀的必前來，在我面前下拜；這是耶和華說的。","notes":[]},{"n":24,"t":"「他們要出去觀看那些違背我的人的屍首，他們的蟲是不死的，他們的火是不滅的，凡有血肉之軀的都必憎惡他們。」","notes":[]}]}},"JER":{"1":{"heading":"耶利米蒙選召","verses":[{"n":1,"t":"這些是便雅憫地亞拿突城的祭司，希勒家的兒子耶利米的話。","notes":[]},{"n":2,"t":"亞們的兒子猶大王約西亞在位第十三年，耶和華的話臨到耶利米。","notes":[]},{"n":3,"t":"從約西亞的兒子猶大王約雅敬在位的時候，直到約西亞的兒子猶大王西底家在位的末年，就是第十一年五月間耶路撒冷被擄時，耶和華的話也常臨到耶利米。","notes":[]},{"n":4,"t":"耶利米說，耶和華的話臨到我，說：","notes":[]},{"n":5,"t":"「我尚未將你造在母腹中，就已認識你；你未出母胎，我已將你分別為聖，派你作列國的先知。」","notes":[]},{"n":6,"t":"我就說：「唉！主耶和華，看哪，我不知道怎麼說，因為我年輕。」","notes":[]},{"n":7,"t":"耶和華對我說：「不要說『我年輕』，因為我差遣你到誰那裏去，你都要去；我吩咐你說甚麼話，你都要說。","notes":[]},{"n":8,"t":"你不要怕他們，因為我與你同在，要拯救你。這是耶和華說的。」","notes":[]},{"n":9,"t":"於是耶和華伸手按住我的口，對我說：「看哪，我已將我的話放在你口中。","notes":[]},{"n":10,"t":"我今日立你在列邦列國之上，為要拔出，拆毀，毀壞，傾覆，又要建立，栽植。」","notes":[]},{"n":11,"t":"耶和華的話臨到我，說：「耶利米，你看見甚麼？」我說：「我看見一根杏樹枝。」","notes":[],"heads":["兩個異象"]},{"n":12,"t":"耶和華對我說：「你看得不錯；因為我要看守我的話，使它實現。」","notes":["「看守」與「杏樹枝」的希伯來話發音相近。"]},{"n":13,"t":"耶和華的話第二次臨到我，說：「你看見甚麼？」我說：「我看見一個水燒開的鍋，從北而傾。」","notes":[]},{"n":14,"t":"耶和華對我說：「必有災禍從北方發出，臨到這地所有的居民。","notes":[]},{"n":15,"t":"看哪，我要召北方列國的萬族。這是耶和華說的。他們要來，各安寶座在耶路撒冷的城門口，周圍攻擊城牆，又要攻擊猶大的一切城鎮。","notes":[]},{"n":16,"t":"這民離棄我，向別神燒香，跪拜自己手所造的，我要針對這一切惡行，向他們宣讀我的判決。","notes":[]},{"n":17,"t":"所以你當束腰，起來，將我所吩咐你的一切話都告訴他們；不要因他們驚惶，免得我使你在他們面前驚惶。","notes":[]},{"n":18,"t":"看哪，我今日使你成為堅城、鐵柱、銅牆，對抗全地和猶大的君王、官長、祭司，並這地的百姓。","notes":[]},{"n":19,"t":"他們要攻擊你，卻不能勝過你，因為我與你同在，要拯救你。這是耶和華說的。」","notes":[]}]},"2":{"heading":"神眷顧以色列","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「你去向耶路撒冷居民的耳朵呼喊，耶和華如此說：『你年輕時的恩愛，新婚時的愛情，你怎樣在曠野，在未耕種之地跟隨我，我都記得。","notes":[]},{"n":3,"t":"那時以色列歸耶和華為聖，作為他初熟的土產；凡吞吃它的必算為有罪，災禍必臨到他們。這是耶和華說的。』」","notes":[]},{"n":4,"t":"雅各家，以色列家的各族啊，當聽耶和華的話，","notes":[],"heads":["以色列祖先的罪惡"]},{"n":5,"t":"耶和華如此說：「你們的祖先看我有甚麼錯處，竟遠離我，隨從那虛無的神明，自己成為虛無呢？","notes":["「虛無的神明」：原文是「虛無」。"]},{"n":6,"t":"他們並不問：『那領我們從埃及地上來，引導我們走過曠野、沙漠有坑洞之地，走過乾旱死蔭、無人經過、無人居住之地的耶和華在哪裏呢？』","notes":[]},{"n":7,"t":"我領你們進入肥沃之地，使你們得吃其中的果子和美物；你們進入時，卻使我的地玷污，使我的產業成為可憎的。","notes":[]},{"n":8,"t":"祭司從來不問：『耶和華在哪裏呢？』傳講律法的不認識我，官長違背我，先知藉巴力說預言，隨從無益的東西。」","notes":[]},{"n":9,"t":"「我因此必與你們爭辯，也與你們的子孫爭辯。這是耶和華說的。","notes":[],"heads":["神譴責他的子民"]},{"n":10,"t":"你們且渡到基提海島察看，派人往基達去留心查考，看可曾有過這樣的事。","notes":[]},{"n":11,"t":"豈有一國換了它的神明嗎？其實那不是神明！但我的百姓將他們的榮耀換了那無益的東西。","notes":[]},{"n":12,"t":"諸天哪，要因此震驚，顫慄，極其淒涼！這是耶和華說的。","notes":[]},{"n":13,"t":"因為我的百姓做了兩件惡事：離棄我這活水的泉源；又為自己鑿出水池，卻是破裂不能儲水的池子。」","notes":[]},{"n":14,"t":"「以色列是僕人嗎？是家中生的奴僕嗎？為何成為掠物呢？","notes":[],"heads":["以色列不忠的結局"]},{"n":15,"t":"少壯獅子向它咆哮，大聲吼叫，使它的地荒蕪；城鎮燒燬，無人居住。","notes":[]},{"n":16,"t":"挪弗人和答比匿人打破你的頭顱。","notes":["「挪弗」即埃及的孟斐斯；本卷書44．1；46．14，19同。"]},{"n":17,"t":"這不是你自己招惹的嗎？不是因耶和華－你神引導你行路時，你離棄了他嗎？","notes":[]},{"n":18,"t":"現今你為何在埃及路上喝西曷河的水呢？為何在亞述路上喝大河的水呢？","notes":["「西曷河」是尼羅河的支流。"]},{"n":19,"t":"你自己的惡必懲治你，你背道的事必責罰你。由此可知可見，你離棄耶和華－你的神，不存敬畏我的心，實為惡事，為苦事；這是萬軍之主耶和華說的。」","notes":[]},{"n":20,"t":"「你在古時折斷你的軛，解開你的繩索，說：『我必不事奉耶和華。』你在各高岡上、各青翠的樹下屈身行淫。","notes":["「你」是根據七十士譯本；原文是「我」。","「不事奉耶和華」：原文另譯「不作惡」。"],"heads":["以色列拒絕敬拜耶和華"]},{"n":21,"t":"然而，我栽種你為上等的葡萄樹，全用純正的種子；你怎麼向我變為外邦葡萄樹的壞枝子呢？","notes":[]},{"n":22,"t":"你雖用鹼、多用皂莢清洗，你罪孽的痕跡仍顯在我面前。這是主耶和華說的。","notes":[]},{"n":23,"t":"你怎能說：『我沒有玷污，沒有隨從巴力』？看看你在谷中所做的，思想你自己的所作所為；你是快行的獨峰駝，狂奔亂闖。","notes":[]},{"n":24,"t":"你是野驢，習慣曠野，慾心發動時就呼吸急促，發情時誰能使牠轉回呢？凡尋找牠的必不費力，在牠的季節必能尋見牠。","notes":[]},{"n":25,"t":"你不要弄到赤足而行，喉嚨乾渴。你卻說：『沒有用的，我喜愛陌生人，我必隨從他們。』」","notes":[]},{"n":26,"t":"「賊被捉拿，怎樣羞愧，以色列家和他們的君王、官長、祭司、先知也都照樣羞愧。","notes":[],"heads":["以色列該受懲罰"]},{"n":27,"t":"他們向木頭說：『你是我的父』；向石頭說：『你是生我的。』他們以背向我，不肯以面向我；及至遭遇患難時卻說：『起來拯救我們吧！』","notes":[]},{"n":28,"t":"你為自己做的神明在哪裏呢？你遭遇患難的時候，讓它們起來拯救你吧！猶大啊，你神明的數目與你城的數目相等。","notes":[]},{"n":29,"t":"「你們為何與我爭辯呢？你們都違背了我。這是耶和華說的。","notes":[]},{"n":30,"t":"我責打你們的兒女是徒然的，他們不受管教。你們自己的刀吞滅你們的先知，好像殘害人的獅子。","notes":[]},{"n":31,"t":"這世代的人哪，你們要留意耶和華的話。我向以色列豈是曠野，或幽暗之地呢？我的百姓為何說：『我們脫離約束，不再歸向你了』？","notes":[]},{"n":32,"t":"少女豈能忘記她的妝飾呢？新娘豈能忘記她的美衣呢？我的百姓卻在無數的日子裏忘記了我！","notes":[]},{"n":33,"t":"「你竟然如此精於求愛之道，可把你的門徑教邪惡的女人！","notes":[]},{"n":34,"t":"你衣服的邊上有無辜貧窮人的血，其實你並未發現他們挖洞進屋偷竊。雖有這一切的事，","notes":["參出22．2。","「其實...一切的事」：七十士譯本是「我並沒有在洞裏找到他們，而是在每棵橡樹底下。」"]},{"n":35,"t":"你還說：『我無辜；耶和華的怒氣必定轉離我了。』看哪，我必審問你；因你自己說：『我沒有犯罪。』","notes":[]},{"n":36,"t":"你為何東奔西跑改變你的道路呢？你必因埃及蒙羞，像從前因亞述蒙羞一樣。","notes":[]},{"n":37,"t":"你也必兩手抱頭離開這裏；因為耶和華已經棄絕你所倚靠的，你不能因他們而得順利。」","notes":[]}]},"3":{"heading":"不忠的以色列","verses":[{"n":1,"t":"耶和華說：「人若休妻，妻離他而去，做了別人的妻子，前夫豈能再回到她那裏呢？那地豈不是大大污穢了嗎？但你和許多情郎行淫，還是可以回到我這裏。這是耶和華說的。","notes":["「耶和華說」或譯「有話說」；七十士譯本和其他古譯本沒有「耶和華說」。"]},{"n":2,"t":"你舉目向光禿的高地觀看，何處沒有你的淫行呢？你坐在道路旁等候，好像阿拉伯人在曠野埋伏，你的淫行和邪惡使全地污穢了。","notes":[]},{"n":3,"t":"因此甘霖停止，春雨不降。你還是一副娼妓之臉，不顧羞恥。","notes":[]},{"n":4,"t":"你不是才向我呼叫說：『我父啊，你是我年輕時的密友，","notes":[]},{"n":5,"t":"人豈永遠懷恨，長久存怒嗎？』看哪，你雖這樣說，還是竭盡所能去行惡。」","notes":[]},{"n":6,"t":"約西亞王在位的時候，耶和華對我說：「你看見背道的以色列所做的嗎？她上到各高山，在各青翠的樹下行淫。","notes":[],"heads":["以色列和猶大應當悔改"]},{"n":7,"t":"我說：『她行這些事以後會回轉歸向我』，她卻不回轉。她奸詐的妹妹猶大也看見了。","notes":[]},{"n":8,"t":"我看見背道的以色列行淫，我為這緣故給她休書休了她，她奸詐的妹妹猶大還不懼怕，也去行淫。","notes":[]},{"n":9,"t":"因以色列輕忽了她的淫亂，與石頭和木頭行姦淫，她和這地就都污穢了。","notes":["「與石頭和木頭行姦淫」意思是「拜石頭和木頭」。","「她和...污穢了」：原文另譯「她就使這地污穢了」。"]},{"n":10,"t":"雖有這一切的事，她奸詐的妹妹猶大還不一心歸向我，不過是假意歸我。這是耶和華說的。」","notes":[]},{"n":11,"t":"耶和華對我說：「背道的以色列比奸詐的猶大還顯為義。","notes":[]},{"n":12,"t":"你去向北方宣告這些話，說：『背道的以色列啊，回來吧！這是耶和華說的。我必不怒目看你們，因為我是慈愛的，這是耶和華說的。我必不永遠懷怒；","notes":[]},{"n":13,"t":"只要承認你的罪孽，就是違背耶和華－你的神，在各青翠的樹下追逐外族的神明，沒有聽從我的話。這是耶和華說的。","notes":["「外族的神明」：原文是「外族」。"]},{"n":14,"t":"背道的兒女啊，回來吧！這是耶和華說的。因為我作你們的丈夫，要將你們從一城取一人，從一族取兩人，帶到錫安。","notes":[]},{"n":15,"t":"「『我必將合我心意的牧者賞賜給你們，他們要以知識和智慧牧養你們。","notes":[]},{"n":16,"t":"你們在國中生養眾多的時候，那些日子，人必不再提說耶和華的約櫃，不追想，不記念，不覺缺少，也不再製造。這是耶和華說的。","notes":[]},{"n":17,"t":"那時，人必稱耶路撒冷為耶和華的寶座；萬國聚集在那裏，為耶和華的名來到耶路撒冷，他們必不再隨從自己頑梗的惡心行事。","notes":[]},{"n":18,"t":"當那些日子，猶大家要和以色列家同行，從北方之地一同來到我所賜給你們祖先為業之地。』」","notes":[]},{"n":19,"t":"「我說，我多麼樂意把你列在兒女之中，賜給你美地，就是萬國中最美的產業。我說，你會以『我父啊』稱呼我，不再轉離而跟從我。","notes":[],"heads":["神的子民拜偶像"]},{"n":20,"t":"以色列家啊，你們向我行詭詐，真像妻子行詭詐離開丈夫。這是耶和華說的。」","notes":[]},{"n":21,"t":"有聲音從光禿的高地傳來，就是以色列人哭泣懇求的聲音，因為他們走彎曲之道，忘記耶和華－他們的神。","notes":[]},{"n":22,"t":"「你們這背道的兒女啊，回來吧！我要醫治你們背道的病。」「看哪，我們來到你這裏，因你是耶和華－我們的神。","notes":[]},{"n":23,"t":"從小山來的真是枉然，大山的喧嚷也是枉然。以色列得救，誠然在乎耶和華－我們的神。","notes":["小山和大山是拜偶像的地方。"]},{"n":24,"t":"「從我們幼年以來，那可恥之物吞吃了我們祖先勞碌得來的，就是他們的羊群、牛群和他們的兒女。","notes":["「那可恥之物」就是「偶像」。"]},{"n":25,"t":"我們在羞恥中躺臥吧！願慚愧將我們遮蓋！因為從我們幼年以來，我們和我們的祖先都得罪了耶和華－我們的神，沒有聽從耶和華－我們神的話。」","notes":[]}]},"4":{"heading":"呼召以色列悔改","verses":[{"n":1,"t":"耶和華說：「以色列啊，你若回轉，回轉歸向我，若從我眼前除掉你可憎的偶像，不再猶疑不定，","notes":[]},{"n":2,"t":"憑誠實、公平、公義指著永生的耶和華起誓；列國就必因他蒙福，也必因他誇耀。」","notes":[]},{"n":3,"t":"耶和華對猶大人和耶路撒冷人如此說：「你們要為自己開墾荒地，不要撒種在荊棘裏。","notes":[]},{"n":4,"t":"猶大人和耶路撒冷的居民哪，你們當自行割禮，歸耶和華，將你們心裏的污穢除掉；免得我的憤怒因你們的惡行發作，如火燃起，甚至無人能熄滅！」","notes":["「污穢」﹕原文是「包皮」。"]},{"n":5,"t":"你們要在猶大傳揚，在耶路撒冷宣告，說：「當在國中吹角，高聲呼叫說：『你們當聚集！我們好進入堅固城！』","notes":[],"heads":["外患威脅猶大"]},{"n":6,"t":"應當向錫安豎立大旗。逃吧，不要遲延，因我必使災禍與大毀滅從北方來到。","notes":[]},{"n":7,"t":"有獅子從密林中上來，是毀壞列國的。牠已動身出離本處，要使你的地荒涼，使你的城鎮變為廢墟，無人居住。","notes":[]},{"n":8,"t":"因此，你們當腰束麻布，哭泣哀號，因為耶和華的烈怒並未轉離我們。」","notes":[]},{"n":9,"t":"耶和華說：「到那時，君王和領袖的心要失喪，祭司都要驚奇，先知都要詫異。」","notes":[]},{"n":10,"t":"我說：「哀哉！主耶和華啊，你真是大大欺哄這百姓和耶路撒冷，說：『你們必得平安。』其實刀劍已經抵住喉嚨了！」","notes":[]},{"n":11,"t":"那時，必有話對這百姓和耶路撒冷說：「來自曠野光禿高地的熱風吹向我的百姓，不是為簸揚，也不是為揚淨。","notes":["「我的百姓」：原文直譯「我百姓的女兒」。"]},{"n":12,"t":"又有一陣比這更大的風向我颳來；現在，我要向他們宣讀我的判決。」","notes":[]},{"n":13,"t":"看哪，他必如雲湧上；他的戰車如旋風，他的馬比鷹更快。我們有禍了！我們敗落了！","notes":[],"heads":["猶大被圍困"]},{"n":14,"t":"耶路撒冷啊，你當洗去心中的惡，使你可以得救。惡念在你裏面要存到幾時呢？","notes":[]},{"n":15,"t":"有聲音從但傳出，有災禍從以法蓮山傳來。","notes":[]},{"n":16,"t":"你們當傳給列國，看哪，要向耶路撒冷報告：「有圍攻的人從遠方來到，向猶大的城鎮大聲喊叫。","notes":[]},{"n":17,"t":"他們包圍耶路撒冷，好像看守田園的，因為它背叛了我。這是耶和華說的。","notes":[]},{"n":18,"t":"你的作風和行為招惹這事；這是你罪惡的結果，實在是苦，刺透了你的心！」","notes":[]},{"n":19,"t":"我的肺腑啊，我的肺腑啊，我心疼痛！我的心在我裏面煩躁不安。我不能靜默不言，因我已聽見角聲和打仗的喊聲。","notes":[],"heads":["耶利米為同胞擔憂"]},{"n":20,"t":"毀壞的信息不斷傳來，因為全地荒廢。我的帳棚忽然毀壞，我的幔子頃刻破裂。","notes":[]},{"n":21,"t":"我看見大旗，聽見角聲，要到幾時呢？","notes":[]},{"n":22,"t":"「我的百姓愚頑，不認識我；他們是愚昧無知的兒女，有智慧行惡，沒有知識行善。」","notes":[]},{"n":23,"t":"我觀看地，看哪，地是空虛混沌；我觀看天，天也無光。","notes":[],"heads":["將要來臨的毀滅"]},{"n":24,"t":"我觀看大山，看哪，盡都震動，小山也都搖來搖去。","notes":[]},{"n":25,"t":"我觀看，看哪，無人；空中的飛鳥也都躲避。","notes":[]},{"n":26,"t":"我觀看，看哪，肥田變為荒地；所有城鎮在耶和華面前，因他的烈怒都被拆毀。","notes":[]},{"n":27,"t":"耶和華如此說：「全地必然荒涼，我卻不毀滅淨盡。","notes":[]},{"n":28,"t":"因此，地要悲哀，天上也必黑暗；因為我言已出，我意已定，必不改變，也不由此轉回。」","notes":[]},{"n":29,"t":"各城的人因騎兵和弓箭手的響聲就都逃跑，進入密林，爬上磐石；城鎮都被拋棄，無人住在其中。","notes":[]},{"n":30,"t":"你這被毀滅的啊，你要做甚麼呢？你穿上朱紅衣服，佩戴黃金飾物，用眼影修飾眼睛，徒然美化你自己。戀慕你的卻藐視你，尋索你的性命。","notes":[]},{"n":31,"t":"我聽見有彷彿婦人臨產的聲音，好像是生頭胎疼痛的聲音，原來是錫安的聲音；她喘著氣，伸開手：「我有禍了！在殺人者跟前，我的心靈發昏。」","notes":["「錫安」：原文直譯「錫安女子」。"]}]},"5":{"heading":"耶路撒冷的罪","verses":[{"n":1,"t":"你們要走遍耶路撒冷的街市，在廣場尋找，看是否有人行公平、求誠實；若有，我就赦免這城。","notes":[]},{"n":2,"t":"雖然他們說「我對永生的耶和華發誓」，所起的誓實在是假的。","notes":[]},{"n":3,"t":"耶和華啊，你的眼目不是在尋找誠實嗎？你擊打他們，他們卻不傷慟；你摧毀他們，他們仍不領受管教。他們使臉剛硬過於磐石，不肯回頭。","notes":[]},{"n":4,"t":"我說：「這些人實在是貧寒的，他們是愚昧的，因為不知道耶和華的作為，也不知道他們神的法則。","notes":[]},{"n":5,"t":"我要去見尊貴的人，向他們說話，他們應該知道耶和華的作為，知道他們神的法則。」然而，這些人卻齊心將軛折斷，掙開繩索。","notes":[]},{"n":6,"t":"因此，林中的獅子必害死他們，野地的狼必滅絕他們，豹子在城外窺伺。凡出城的必被撕碎，因為他們的罪過極多，背道的事也增加。","notes":[]},{"n":7,"t":"我怎能赦免你呢？你的兒女離棄我，又指著那不是神的起誓。我使他們飽足，他們就行姦淫，居住在娼妓家裏。","notes":["「居住」是根據七十士譯本；原文是「割劃自己」；另有古譯本是「成群聚集」。"]},{"n":8,"t":"他們如餵飽的馬，精力旺盛，各向鄰舍的妻子吹哨。","notes":[]},{"n":9,"t":"我豈不因這些事施行懲罰嗎？像這樣的國家，我豈能不報復呢？這是耶和華說的。","notes":[]},{"n":10,"t":"你們要上去毀壞它的葡萄園，但不可毀壞淨盡，只可除掉其枝子，因為不屬耶和華。","notes":[]},{"n":11,"t":"以色列家和猶大家向我大行詭詐。這是耶和華說的。","notes":[]},{"n":12,"t":"關乎耶和華他們說了虛謊的話：「他不會的，災禍必不臨到我們，我們也不會遇見刀劍和饑荒。","notes":[],"heads":["耶和華丟棄以色列"]},{"n":13,"t":"先知不過是一陣風，道也不在他們裏面；這災禍必臨到他們身上。」","notes":[]},{"n":14,"t":"所以耶和華－萬軍之神如此說：「因為他們說這話，看哪，我必使我的話在你口中為火，使這百姓為柴，火便將他們燒滅。","notes":[]},{"n":15,"t":"以色列家啊，看哪，我必使一國從遠方來攻擊你，是強盛的國，是古老的國；他們的言語你不知道，所說的話你不明白。這是耶和華說的。","notes":[]},{"n":16,"t":"他們的箭袋有如敞開的墳墓，他們全都是勇士。","notes":[]},{"n":17,"t":"他們必吃盡你的莊稼和糧食，是你兒女該吃的；必吃盡你的牛羊，吃盡你的葡萄和無花果；又必用刀劍毀壞你所倚靠的堅固城。","notes":["「是你兒女該吃的」：七十士譯本是「吃盡你的兒女」。"]},{"n":18,"t":"「就是在那些日子，我也不會將你們毀滅淨盡。這是耶和華說的。","notes":[]},{"n":19,"t":"百姓若說：『耶和華－我們的神為甚麼向我們行這一切事呢？』你就對他們說：『你們怎樣離棄我，在你們的地上事奉外邦神明，也必照樣在不屬你們的地上事奉外族人。』」","notes":[]},{"n":20,"t":"當在雅各家傳揚，在猶大宣告，說：","notes":[],"heads":["神警告他的子民"]},{"n":21,"t":"「愚昧無知的百姓啊，你們有眼不看，有耳不聽，現在當聽這話。","notes":[]},{"n":22,"t":"你們難道不懼怕我嗎？在我面前還不戰兢嗎？這是耶和華說的。我以沙為海的界限，作永遠的條例，使它不得越過。波浪洶湧，卻不能勝過；怒濤澎湃，仍無法越過。","notes":[]},{"n":23,"t":"但這百姓有背叛忤逆的心，他們轉離而去。","notes":[]},{"n":24,"t":"他們心裏並不說：『我們應當敬畏耶和華－我們的神；他按時賜雨，就是秋雨和春雨，又為我們定收割的季節。』","notes":[]},{"n":25,"t":"你們的罪孽使這些轉離你們，你們的罪惡使你們不能得福。","notes":[]},{"n":26,"t":"在我百姓當中有惡人，他們埋伏，好像捕鳥的人在窺探；他們設羅網陷害人。","notes":["「他們...在窺探」：原文另譯「他們設羅網，像捕鳥人的網」。"]},{"n":27,"t":"籠子怎樣裝滿雀鳥，他們的屋裏也照樣充滿詭詐；他們因此得以強大富足。","notes":[]},{"n":28,"t":"他們肥胖光潤，作惡過甚，不為人伸冤，不為孤兒伸冤，使他們勝訴，也不為貧窮人辯護。","notes":[]},{"n":29,"t":"我豈不因這些事施行懲罰嗎？像這樣的國家，我豈能不報復呢？這是耶和華說的。","notes":[]},{"n":30,"t":"「國中有令人驚駭、恐怖的事發生，","notes":[]},{"n":31,"t":"就是先知說假預言，祭司把權柄抓在自己手上，我的百姓也喜愛這樣，到了結局你們要怎麼辦呢？」","notes":[]}]},"6":{"heading":"耶路撒冷遭圍攻","verses":[{"n":1,"t":"便雅憫人哪，當逃離耶路撒冷，在提哥亞吹號角，在伯‧哈基琳升信號，因為有災禍與大毀滅從北方逼近。","notes":[]},{"n":2,"t":"那秀美嬌嫩的錫安，我必剪除。","notes":["「錫安」：原文直譯「錫安女子」。","本節另譯「我把錫安比作最可愛的草場」。"]},{"n":3,"t":"牧人必引領羊群到它那裏，在它周圍支搭帳棚，各在自己的地方放牧。","notes":[]},{"n":4,"t":"「你們要準備攻擊它。起來吧，我們要趁正午上去。」「哀哉！日已漸斜，黃昏的影子拖長了。」","notes":[]},{"n":5,"t":"「起來吧，我們要在夜間上去，毀壞它的宮殿。」","notes":[]},{"n":6,"t":"萬軍之耶和華如此說：「你們要砍伐樹木，建土堆攻打耶路撒冷，就是那該受罰的城，其中盡是欺壓。","notes":["「該受罰的城」：原文另譯「放縱的城」或「被棄的城」。"]},{"n":7,"t":"井怎樣湧出水來，這城也照樣湧出惡來；其中常聽聞殘暴毀滅的事，病痛損傷也常在我面前。","notes":[]},{"n":8,"t":"耶路撒冷啊，當受管教，免得我心與你生疏，免得我使你荒涼，成為無人居住之地。」","notes":[]},{"n":9,"t":"萬軍之耶和華如此說：「他們洗劫以色列剩下的民，如摘淨葡萄一樣；現你的手如採收葡萄的人，在樹枝上採了又採。」","notes":["「你的手...採了又採」：七十士譯本是「你要像摘葡萄的人，回手放在筐子裏」。"],"heads":["叛逆的以色列"]},{"n":10,"t":"現在我可以向誰說話，警告誰，使他們聽呢？看哪，他們的耳朵未受割禮，不能聽見。看哪，他們以耶和華的話為羞辱，不以為喜悅。","notes":[]},{"n":11,"t":"因此我被耶和華的憤怒充滿，難以忍受。「你要把它倒在街上孩童和成群的年輕人身上，他們連夫帶妻，年長者與高齡的人都必被擒拿。","notes":[]},{"n":12,"t":"他們的房屋、田地，和妻子都要一起轉歸別人，我要伸手攻擊這地的居民。」這是耶和華說的。","notes":[]},{"n":13,"t":"「因為他們從最小的到最大的都貪圖不義之財，從先知到祭司全都行事虛假。","notes":[]},{"n":14,"t":"他們輕忽地醫治我百姓的損傷，說：『平安了！平安了！』其實沒有平安。","notes":[]},{"n":15,"t":"他們行可憎之事，應當羞愧；然而他們卻一點也不覺得羞愧，也不知羞恥。因此，他們必與仆倒的人一同仆倒，我懲罰他們的時候，他們必跌倒。」這是耶和華說的。","notes":[]},{"n":16,"t":"耶和華如此說：「你們當站在路邊察看，尋訪古老的路，哪裏是完善的道路，就行走在其上；這樣，你們自己必找到安息。他們卻說：『我們不走。』","notes":[],"heads":["以色列拒絕神的道路"]},{"n":17,"t":"我為你們設立守望的人，要留心聽角聲。他們卻說：『我們不聽。』","notes":[]},{"n":18,"t":"因此，列國啊，當聽！會眾啊，要知道他們必遭遇的事。","notes":[]},{"n":19,"t":"地啊，當聽！看哪，我必使災禍臨到這百姓，是他們計謀所結的果子；因為他們不肯留心聽我的話，至於我的律法，他們也厭棄。","notes":[]},{"n":20,"t":"從示巴來的乳香，從遠方出的香菖蒲，奉來給我有何用呢？你們的燔祭不蒙悅納；你們的祭物，我也不喜悅。」","notes":[]},{"n":21,"t":"所以耶和華如此說：「看哪，我要將絆腳石放在這百姓面前；父親和兒子要一同跌在其上，鄰舍與朋友也都滅亡。」","notes":[]},{"n":22,"t":"耶和華如此說：「看哪，有一民族從北方而來；有一大國被激起，從地極來到。","notes":[],"heads":["北方來的侵略者"]},{"n":23,"t":"他們拿弓和槍，性情殘忍，不施憐憫；他們的聲音如海浪澎湃。錫安哪，他們都騎馬，如上戰場的人擺陣攻擊你。」","notes":["「錫安」：原文直譯「錫安女子」。"]},{"n":24,"t":"我們聽見這樣的風聲，手就發軟；痛苦將我們抓住，疼痛彷彿臨產的婦人。","notes":[]},{"n":25,"t":"你們不要出到田野去，也不要行走在路上，因四圍有仇敵的刀劍和驚嚇。","notes":[]},{"n":26,"t":"我的百姓啊，應當腰束麻布，滾在灰中。要悲傷，如喪獨子般痛痛哭號，因為滅命的忽然臨到我們。","notes":["「我的百姓」：原文直譯「我百姓的女兒」。"]},{"n":27,"t":"我使你作我百姓的測試者和考驗者，使你知道並考驗他們的行為。","notes":["「測試者」或譯「庇護所」。","「考驗者」：原文另譯「堡壘」。"]},{"n":28,"t":"他們極其悖逆，到處毀謗人，他們是銅是鐵，全都敗壞了。","notes":[]},{"n":29,"t":"風箱吹火，鉛被燒燬，煉而又煉，終是徒然，因為惡劣的還未除掉。","notes":[]},{"n":30,"t":"人必稱他們為被拋棄的銀子，因為耶和華已經拋棄了他們。","notes":[]}]},"7":{"heading":"耶利米在聖殿講道","verses":[{"n":1,"t":"耶和華的話臨到耶利米，說：","notes":[]},{"n":2,"t":"「你當站在耶和華殿的門口，在那裏宣講這話說：所有從這些門進來敬拜耶和華的猶大人哪，當聽耶和華的話。","notes":[]},{"n":3,"t":"萬軍之耶和華－以色列的神如此說：你們要改正你們的所作所為，我就使你們仍然居住這地。","notes":["「我就...這地」：有古譯本是「讓我與你們住在這地」。"]},{"n":4,"t":"不要倚靠虛謊的話，說：『這是耶和華的殿，是耶和華的殿，是耶和華的殿！』","notes":[]},{"n":5,"t":"「你們若實在改正你們的所作所為，彼此誠然施行公平，","notes":[]},{"n":6,"t":"不欺壓寄居的和孤兒寡婦，不在這地方流無辜人的血，也不隨從別神陷害自己，","notes":[]},{"n":7,"t":"我就使你們仍然居住這地，就是我從古時所賜給你們祖先的地，從永遠到永遠。","notes":["「我就...這地」：有古譯本是「我就與你們住在這地」。"]},{"n":8,"t":"「看哪，你們倚靠虛謊無益的話語。","notes":[]},{"n":9,"t":"你們豈可偷盜，殺害，姦淫，起假誓，向巴力燒香，隨從素不認識的別神，","notes":[]},{"n":10,"t":"又來到這稱為我名下的殿，在我面前敬拜，說『我們平安無事』，為了要行這一切可憎的事呢？","notes":[]},{"n":11,"t":"這稱為我名下的殿在你們眼中豈可看為賊窩呢？看哪，我真的都看見了。這是耶和華說的。","notes":[]},{"n":12,"t":"你們到我的地方示羅去，就是我先前在那裏立為我名的居所，察看我因這百姓以色列的罪惡向那地方所行的事。","notes":[]},{"n":13,"t":"現在，因你們行了這一切的事，我一再警戒你們，你們卻不聽從；我呼喚你們，你們也不回應。這是耶和華說的。","notes":[]},{"n":14,"t":"所以我要向這稱為我名下、你們所倚靠的殿，與我所賜給你們和你們祖先的地這樣行，正如我從前向示羅所行的。","notes":[]},{"n":15,"t":"我必將你們從我眼前趕出，正如趕出你們的眾弟兄，就是所有以法蓮的後裔。」","notes":[]},{"n":16,"t":"「所以，你不要為這百姓祈禱；不要為他們呼求禱告，也不要為他們向我祈求，因我不聽你。","notes":[],"heads":["百姓違背命令"]},{"n":17,"t":"他們在猶大城鎮和耶路撒冷街上所做的，你難道沒有看見嗎？","notes":[]},{"n":18,"t":"孩子撿柴，父親燒火，婦女揉麵做餅，獻給天后，又向別神獻澆酒祭，惹我發怒。","notes":[]},{"n":19,"t":"他們豈是惹我發怒呢？不是自己惹禍，以致臉上慚愧嗎？這是耶和華說的。」","notes":[]},{"n":20,"t":"所以主耶和華如此說：「看哪，我必將我的怒氣和憤怒傾倒在這地方的人和牲畜身上、田野的樹木和地裏的出產上，它必燃燒，不會熄滅。」","notes":[]},{"n":21,"t":"萬軍之耶和華－以色列的神如此說：「你們要將燔祭加在你們的祭物上，又要吃肉；","notes":[]},{"n":22,"t":"因為我將你們祖先從埃及地領出來的那日，燔祭和祭物的事我並沒有提說，也沒有吩咐他們。","notes":[]},{"n":23,"t":"我只吩咐他們這一件事說：『你們當聽從我的話，我就作你們的神，你們也作我的子民。你們行走我所吩咐的一切道路，就可以得福。』","notes":[]},{"n":24,"t":"他們卻不聽從，也不側耳而聽，竟隨從自己的計謀和頑梗的惡心去行，不進反退。","notes":[]},{"n":25,"t":"自從你們祖先出埃及地的那日，直到今日，我每日一再差遣我的僕人眾先知到你們那裏去。","notes":[]},{"n":26,"t":"你們卻不聽我，不側耳而聽，竟硬著頸項行惡，比你們的祖先更甚。","notes":[]},{"n":27,"t":"「你要將這一切的話告訴他們，他們卻不聽你；呼喚他們，他們卻不回應。","notes":[]},{"n":28,"t":"你要對他們說：『這就是不聽從耶和華－他們神的話、不領受訓誨的國民；誠信已從他們口中消失殆盡了。","notes":[]},{"n":29,"t":"耶路撒冷啊，要剪頭髮，扔掉它，在光禿的高地唱哀歌，因為耶和華棄絕、離棄了惹他發怒的世代。』」","notes":[]},{"n":30,"t":"「猶大人行我眼中看為惡的事，將可憎之偶像立在稱為我名下的殿裏，玷污這殿。這是耶和華說的。","notes":[],"heads":["在欣嫩子谷的罪行"]},{"n":31,"t":"他們在欣嫩子谷建造陀斐特的丘壇，要在火中焚燒自己的兒女。這並不是我所吩咐的，我心裏也從來沒有想過。","notes":[]},{"n":32,"t":"因此，看哪，日子將到，這地方不再稱為陀斐特和欣嫩子谷，反倒稱為殺戮谷。他們要在陀斐特埋葬屍首，甚至無處可葬。這是耶和華說的。","notes":[]},{"n":33,"t":"並且這百姓的屍首要給空中的飛鳥和地上的走獸作食物，無人嚇走牠們。","notes":[]},{"n":34,"t":"那時，我必止息猶大城鎮和耶路撒冷街上歡喜和快樂的聲音、新郎和新娘的聲音，因為這地必然荒蕪。」","notes":[]}]},"8":{"heading":"罪與罰","verses":[{"n":1,"t":"耶和華說：「那時，人必將猶大諸王和領袖的骸骨、祭司和先知的骸骨，以及耶路撒冷居民的骸骨，都從墳墓中取出來，","notes":[]},{"n":2,"t":"散佈在太陽、月亮和天上眾星之下，就是他們從前所喜愛、所事奉、所隨從、所求問、所敬拜的。這些骸骨不被收殮，不被埋葬，必在地面上成為糞土。","notes":[]},{"n":3,"t":"這邪惡家族所倖存的餘民，就是在我趕他們到的各處所剩下的，全都寧可選死不選活。這是萬軍之耶和華說的。」","notes":["有古卷和七十士譯本沒有「所剩下的」。"]},{"n":4,"t":"「你要對他們說，耶和華如此說：人跌倒，不再起來嗎？人轉去，不再轉回來嗎？","notes":[]},{"n":5,"t":"這耶路撒冷的百姓為何永久背道呢？他們抓住詭詐，不肯回頭。","notes":[]},{"n":6,"t":"我留心聽，聽見他們說不誠實的話。無人懊悔自己的惡行，說：『我做的是甚麼呢？』他們全都轉奔己路，如馬直闖戰場。","notes":[]},{"n":7,"t":"空中的鸛鳥知道自己的季節，斑鳩、燕子與白鶴也守候當來的時令；我的百姓卻不知道耶和華的法則。","notes":[]},{"n":8,"t":"「你們怎麼說：『我們有智慧，耶和華的律法在我們這裏』？看哪，其實文士的假筆舞弄虛假。","notes":[]},{"n":9,"t":"智慧人慚愧，驚惶，被擒拿；看哪，他們背棄耶和華的話，還會有甚麼智慧呢？","notes":[]},{"n":10,"t":"因此，我必將他們的妻子給別人，將他們的田地給別人為業；因為他們從最小的到最大的都貪圖不義之財，從先知到祭司全都行事虛假。","notes":[]},{"n":11,"t":"他們輕忽地醫治我百姓的損傷，說：『平安了！平安了！』其實沒有平安。","notes":[]},{"n":12,"t":"他們行可憎之事，應當羞愧；然而他們卻一點也不覺得羞愧，又不知羞恥。因此，他們必與仆倒的人一樣仆倒；我懲罰他們的時候，他們必跌倒。這是耶和華說的。","notes":[]},{"n":13,"t":"我必使他們全然滅絕；葡萄樹上必沒有葡萄，無花果樹上沒有果子，葉子也必枯乾。我所賜給他們的，必離他們而去。這是耶和華說的。」","notes":["「我必...葡萄」：有古譯本是「我要採收果子，但葡萄樹上必沒有葡萄」。"]},{"n":14,"t":"我們為何靜坐不動呢？我們當聚集，進入堅固城，在那裏靜默不言；因為耶和華－我們的神使我們靜默不言，又將苦水給我們喝，都因我們得罪了耶和華。","notes":[]},{"n":15,"t":"我們指望平安，卻得不著福氣；指望痊癒時刻，看哪，受了驚惶。","notes":[]},{"n":16,"t":"「從但那裏傳來敵人的馬噴氣的聲音，壯馬發出嘶聲，全地就都震動；因為他們來吞滅這地和其上所有的，吞滅這城與其中的居民。","notes":[]},{"n":17,"t":"看哪，我必派蛇進到你們中間，就是法術無法驅除的毒蛇，牠們必咬你們。這是耶和華說的。」","notes":[]},{"n":18,"t":"憂愁時我尋找安慰，我心在我裏面發昏。","notes":["「憂愁...安慰」：七十士譯本是「無法醫治的憂傷壓倒你們的心」。"],"heads":["耶利米為同胞悲傷"]},{"n":19,"t":"聽啊，是我百姓呼救的聲音從遠地傳來：「耶和華不是在錫安嗎？錫安的王不是在其中嗎？」「他們為甚麼以自己雕刻的偶像和外邦虛無的神明惹我發怒呢？」","notes":["「虛無的神明」：原文是「虛無」。"]},{"n":20,"t":"「秋收已過，夏季已完，我們還未得救！」","notes":[]},{"n":21,"t":"因我百姓的損傷，我也受了損傷。我哀慟，驚惶將我抓住。","notes":[]},{"n":22,"t":"在基列豈沒有乳香呢？在那裏豈沒有醫生呢？我百姓為何得不著醫治呢？","notes":["「我百姓」：原文直譯「我百姓的女兒」。"]}]},"9":{"heading":"耶路撒冷哀求援助","verses":[{"n":1,"t":"但願我的頭為水，我的眼為淚水的泉源，我好為我百姓中被殺的人晝夜哭泣。","notes":["「我百姓」：原文直譯「我百姓的女兒」。"]},{"n":2,"t":"惟願在曠野有旅客的客棧，我好離開我的百姓而去；因他們全都行姦淫，是行詭詐的一黨。","notes":[]},{"n":3,"t":"他們彎起舌頭像弓，為要說謊話；他們在國中增長勢力，不是為誠信。他們惡上加惡，並不認識我。這是耶和華說的。","notes":[]},{"n":4,"t":"你們各人當謹防鄰舍，不可信賴弟兄；因為弟兄盡行欺騙，鄰舍也都往來毀謗人。","notes":[]},{"n":5,"t":"他們互相欺騙，不說真話，訓練自己的舌頭說謊，竭盡所能地作惡。","notes":[]},{"n":6,"t":"你居住在詭詐的人中；他們因行詭詐，不願意認識我。這是耶和華說的。","notes":["「竭盡...因行詭詐」：七十士譯本是「他們不停地作惡，不知悔改；壓迫又壓迫，欺騙又欺騙 」。"]},{"n":7,"t":"所以萬軍之耶和華如此說：「看哪，我要熬煉他們，考驗他們；不然，為了我的百姓，我該如何行呢？","notes":["「我的百姓」：原文直譯「我百姓的女兒」。"]},{"n":8,"t":"他們的舌頭是毒箭，說話詭詐，跟鄰舍口說平安，心卻謀害他。","notes":[]},{"n":9,"t":"我豈不因這些事向他們施行懲罰嗎？像這樣的國家，我豈能不報復呢？這是耶和華說的。」","notes":[]},{"n":10,"t":"我要為山嶺哭泣悲哀，為曠野的草場揚聲哀號；因為都已枯焦，甚至無人經過。牲畜的鳴叫聽不見，空中的飛鳥和地上的走獸也都逃離。","notes":[]},{"n":11,"t":"我必使耶路撒冷成為廢墟，為野狗的住處，也必使猶大的城鎮荒廢，無人居住。","notes":[]},{"n":12,"t":"誰是智慧人，可以明白這事？耶和華的口可向誰述說，使他傳講呢？這地為何毀滅，枯焦如曠野，無人經過呢？","notes":[]},{"n":13,"t":"耶和華說：「因為這百姓離棄我在他們面前所設立的律法，不聽從我的話，不肯遵行，","notes":[]},{"n":14,"t":"反隨從自己頑梗的心行事，照他們祖先所教訓的隨從諸巴力。」","notes":[]},{"n":15,"t":"所以萬軍之耶和華－以色列的神如此說：「看哪，我必將茵蔯給這百姓吃，又用苦水給他們喝。","notes":[]},{"n":16,"t":"我要把他們分散在他們和他們祖宗所不認識的列國；我也要使刀劍追殺他們，直到將他們滅盡。」","notes":[]},{"n":17,"t":"萬軍之耶和華如此說：「你們要考慮，將唱哀歌的婦女召來，差人召善哭的婦女前來，","notes":[]},{"n":18,"t":"叫她們速速為我們舉哀，使我們淚眼汪汪，使我們的眼皮湧出淚水。","notes":[]},{"n":19,"t":"因為有哀聲從錫安傳來：『我們竟然敗落！我們何等慚愧！我們撇下土地，人拆毀了我們的房屋。』」","notes":[]},{"n":20,"t":"婦女們哪，當聽耶和華的話，領受他口中的言語；當教導你們的女兒舉哀，各人教導女伴唱哀歌。","notes":[]},{"n":21,"t":"因為死亡從窗戶進來，進入我們的宮殿，從外邊剪除孩童，從街上剪除少年。","notes":[]},{"n":22,"t":"你當說，耶和華如此說：人的屍首必倒在田野像糞土，又像收割的人身後遺落的禾稼，無人拾取。","notes":[]},{"n":23,"t":"耶和華如此說：「智慧人不要因他的智慧誇口，勇士不要因他的力氣誇口，財主也不要因他的財富誇口；","notes":[]},{"n":24,"t":"誇口的卻要誇自己有聰明，認識我是耶和華，知道我喜悅在世上施行慈愛、公平和公義。這是耶和華說的。","notes":[]},{"n":25,"t":"「看哪，日子將到，這是耶和華說的，我要懲罰只在肉身受割禮的人，","notes":[]},{"n":26,"t":"就是埃及、猶大、以東、亞捫人、摩押人，和住曠野所有剃鬢髮的人；因為列國都未受割禮，以色列全家心中也未受割禮。」","notes":[]}]},"10":{"heading":"拜偶像和真敬拜","verses":[{"n":1,"t":"以色列家啊，要聽耶和華對你們所說的話，","notes":[]},{"n":2,"t":"耶和華如此說：「不要效法列國的行為，任憑列國因天象驚惶，你們不要驚惶。","notes":[]},{"n":3,"t":"萬民的習俗是虛空的；偶像不過是從樹林中砍來的木頭，是匠人用斧頭做成的手工。","notes":["「偶像」：原文是「它」。"]},{"n":4,"t":"人用金銀妝飾它，用釘子和錘子釘穩，使它不動搖。","notes":[]},{"n":5,"t":"偶像好像瓜田裏的稻草人，不能說話，不能行走，必須有人抬著。不要怕它們，因它們不能降禍，也無力降福。」","notes":[]},{"n":6,"t":"耶和華啊，沒有誰能與你相比！你本為大，你的名也大有能力。","notes":[]},{"n":7,"t":"萬國的王啊，誰不敬畏你？敬畏你本是合宜的；列國所有的智慧人中，在他們一切的國度裏，都沒有能與你相比的。","notes":[]},{"n":8,"t":"他們如同畜牲，盡都愚昧。偶像的訓誨算甚麼呢？偶像不過是木頭，","notes":[]},{"n":9,"t":"錘煉的銀片是從他施來的，金子則從烏法而來，都是匠人和銀匠的手工；又有藍色和紫色的衣服，全都是巧匠的作品。","notes":["「烏法」：有古譯本是「俄斐」。"]},{"n":10,"t":"惟耶和華是真神，是活的神，是永遠的王。他一發怒，大地震動；他一惱恨，列國擔當不起。","notes":[]},{"n":11,"t":"你們要對他們這樣說：「那些不是創造天地的神明，必從地上、從天下被除滅！」","notes":["本節原文是亞蘭文。"]},{"n":12,"t":"耶和華以能力創造大地，以智慧建立世界，以聰明鋪張穹蒼。","notes":[],"heads":["頌讚神的詩"]},{"n":13,"t":"他一出聲，天上就有眾水澎湃；他使雲霧從地極上騰，造電隨雨而閃，從倉庫中吹出風來。","notes":[]},{"n":14,"t":"人人都如同畜牲，毫無知識；銀匠都因偶像羞愧，他所鑄的偶像本是虛假，它們裏面並無氣息。","notes":[]},{"n":15,"t":"偶像都是虛無的，是迷惑人的作品，到受罰的時刻必被除滅。","notes":[]},{"n":16,"t":"雅各所得的福分不是這樣，因主是那創造萬有的，以色列是他產業的支派，萬軍之耶和華是他的名。","notes":["「主」：原文是「他」。"]},{"n":17,"t":"受圍困的居民哪，當收拾你的行囊，離開這地。","notes":[],"heads":["預告被擄"]},{"n":18,"t":"因為耶和華如此說：「看哪，這一次，我必將此地的居民拋出去，又必加害他們，使他們覺悟。」","notes":["「使他們覺悟」：七十士譯本是「你的災難就被發現」。"]},{"n":19,"t":"禍哉！我受損傷，我的傷痕極其重大。我卻說：「這真的是我必須忍受的痛苦。」","notes":[]},{"n":20,"t":"我的帳棚毀壞，我的繩索折斷，我的兒女都離我而去，不在了。再無人來支搭我的帳棚，掛起我的幔子。","notes":[]},{"n":21,"t":"因為牧人如同畜牲，沒有尋求耶和華，所以不得順利；他們的羊群也都分散了。","notes":[]},{"n":22,"t":"有風聲！看哪，來了！有大擾亂從北方而來，要使猶大的城鎮變為廢墟，成為野狗的住處。","notes":[]},{"n":23,"t":"耶和華啊，我知道人的道路不由自己，行路的人也不能定自己的腳步。","notes":[]},{"n":24,"t":"耶和華啊，求你按公平管教我，不要在你的怒中懲治我，免得你使我歸於無有。","notes":[]},{"n":25,"t":"求你將憤怒傾倒在不認識你的列國中，傾倒在不求告你名的各族上；因為他們吞了雅各，不但吞了，而且滅絕，使他的住處變為荒涼。","notes":[]}]},"11":{"heading":"耶利米宣告神的約","verses":[{"n":1,"t":"耶和華的話臨到耶利米，說：","notes":[]},{"n":2,"t":"「當聽這約的話，告訴猶大人和耶路撒冷的居民，","notes":[]},{"n":3,"t":"對他們說，耶和華－以色列的神如此說：『不聽從這約之話的人必受詛咒。","notes":[]},{"n":4,"t":"這約是我將你們祖先從埃及地領出來，脫離鐵爐的那日所吩咐他們的，說：你們要聽從我的話，照我所吩咐的一切去做。這樣，你們作我的子民，我也作你們的神，","notes":[]},{"n":5,"t":"我好堅定我向你們列祖所起的誓，賞賜他們流奶與蜜之地，正如今日一樣。』」我就回應說：「耶和華啊，阿們！」","notes":[]},{"n":6,"t":"耶和華對我說：「你要在猶大城鎮和耶路撒冷街市宣告這一切話，說：『當聽從遵行這約的話，","notes":[]},{"n":7,"t":"因為我將你們祖先從埃及地領出來的那日，直到今日，都一再切切告誡他們說：當聽從我的話。","notes":[]},{"n":8,"t":"他們卻不聽從，也不側耳而聽，竟隨從自己頑梗的惡心去行。我就使這約中一切詛咒的話臨到他們身上；這約是我吩咐他們遵行的，他們卻不遵行。』」","notes":[]},{"n":9,"t":"耶和華對我說：「在猶大人和耶路撒冷居民中有同謀背叛的事。","notes":[]},{"n":10,"t":"他們轉去效法他們祖先的惡行，不肯聽我的話，竟隨從別神，事奉它們。以色列家和猶大家違背了我與他們列祖所立的約。","notes":[]},{"n":11,"t":"所以耶和華如此說：看哪，我必使災禍臨到他們，是他們不能逃脫的。他們向我哀求，我卻不聽。","notes":[]},{"n":12,"t":"那時，猶大城鎮的人和耶路撒冷的居民要哀求他們燒香所供奉的神明；只是遭難的時候，這些神明一點也不能拯救他們。","notes":[]},{"n":13,"t":"猶大啊，你神明的數目與你城鎮的數目相等；你所築可恥的壇，就是向巴力燒香的壇，也與耶路撒冷街道的數目相等。","notes":["「你所築...燒香的壇」：七十士譯本是「你為巴力燒香所築的壇」。"]},{"n":14,"t":"「所以你不要為這百姓祈禱，也不要為他們呼求禱告，因為他們遭難向我哀求的時候，我必不應允。","notes":[]},{"n":15,"t":"我所親愛的既多設惡謀，還能在我殿中做甚麼呢？你因作惡就喜樂，聖肉要離開你。","notes":[]},{"n":16,"t":"從前耶和華給你起名叫青橄欖樹，又華美又結好果子；如今他用一聲巨響點火在其上，枝子就折斷了。","notes":[]},{"n":17,"t":"「原來栽培你的萬軍之耶和華已經說要降禍給你，是因以色列家和猶大家行惡。他們向巴力燒香，惹我發怒，是自作自受。」","notes":[]},{"n":18,"t":"耶和華指示我，我才知道；你將他們所做的給我指明。","notes":[],"heads":["殺害耶利米的陰謀"]},{"n":19,"t":"我像柔順的羔羊被牽去宰殺，並不知道他們設計謀害我：「我們把樹連果子都滅了吧！把他從活人之地剪除，使他的名不再被記得。」","notes":[]},{"n":20,"t":"按公義判斷、察驗人肺腑心腸的萬軍之耶和華啊，求你使我得見你在他們身上報仇，因我已將我的案件向你稟明了。","notes":[]},{"n":21,"t":"所以，耶和華論到尋索你命的亞拿突人如此說：「他們說：你不要奉耶和華的名說預言，免得你死在我們手中。","notes":[]},{"n":22,"t":"所以萬軍之耶和華如此說：看哪，我必懲罰他們；他們的壯丁必被刀劍殺死，他們的兒女必因饑荒而死，","notes":[]},{"n":23,"t":"他們當中必無任何倖存者；因為在他們受罰之年，我必使災禍臨到亞拿突人。」","notes":[]}]},"12":{"heading":"耶利米詢問耶和華","verses":[{"n":1,"t":"耶和華啊，我與你爭辯的時候，你總是顯為義；但有一件，我還要與你理論：惡人的道路為何亨通呢？大行詭詐的為何得安逸呢？","notes":[]},{"n":2,"t":"你栽培了他們，他們也扎了根，長大，而且結果。他們的口與你相近，心卻與你遠離。","notes":[]},{"n":3,"t":"耶和華啊，你認識我，看見我，你察驗我向你的心如何。求你將他們拉出來，如將宰的羊，為殺戮的日子分別出來。","notes":[]},{"n":4,"t":"這地悲哀，一切田野的青草枯乾要到幾時呢？因其上居民的惡行，牲畜和飛鳥都滅絕了。因為他們說：「他看不見我們的結局。」","notes":["「他看不見」：死海古卷是「耶和華不讓你看見」。","「他看不見...結局」：七十士譯本是「神看不見我們的道路」。"]},{"n":5,"t":"「你與步行的人同跑，尚且覺得累，怎能與馬賽跑呢？你在安全之地尚且會跌倒，在約旦河邊的叢林要怎麼辦呢？","notes":["「尚且會跌倒」或譯「感覺安穩」。"]},{"n":6,"t":"因為連你兄弟和你父家都以詭詐待你，甚至在你後邊大聲喊叫。雖然他們向你說好話，你也不要相信他們。」","notes":[]},{"n":7,"t":"我離棄了我的殿宇，撇棄了我的產業，將我心裏所親愛的交在她仇敵手中。","notes":["「她」指的是「所親愛的」、「產業」。"],"heads":["耶和華為他的子民憂傷"]},{"n":8,"t":"我的產業向我如林中的獅子，出聲攻擊我，因此我恨惡她。","notes":[]},{"n":9,"t":"我的產業向我如斑點的鷙鳥，有鷙鳥在四圍攻擊她。你們去聚集田野的百獸，叫牠們來吞吃吧！","notes":[]},{"n":10,"t":"許多牧人毀壞我的葡萄園，踐踏我的地產，使我美好的地產變為荒涼的曠野。","notes":[]},{"n":11,"t":"他們使地荒涼；地既荒涼，就向我哀哭。全地荒涼，卻無人在意。","notes":[]},{"n":12,"t":"滅命的來到曠野中一切光禿的高地；耶和華的刀從地這邊直到地那邊，盡行殺滅，凡血肉之軀都不得平安。","notes":[]},{"n":13,"t":"他們種的是麥子，收的卻是荊棘；辛辛苦苦卻無收穫。因耶和華的烈怒，你們必為自己的收成感到羞愧。","notes":[]},{"n":14,"t":"耶和華如此說：「看哪，我要將所有的惡鄰拔出本地，他們曾佔據了我賜給以色列百姓所承受的產業；我也要將猶大家從他們中間拔出來。","notes":[],"heads":["耶和華對以色列的許諾"]},{"n":15,"t":"我拔出他們以後，必回轉過來憐憫他們，使他們歸回，各歸本業，各歸故土。","notes":[]},{"n":16,"t":"他們若殷勤學習我百姓的道，指著我的名起誓：『我指著永生的耶和華起誓』，正如他們從前教我百姓指著巴力起誓，他們必在我百姓中得以建立。","notes":[]},{"n":17,"t":"他們若是不聽，我必拔出那國，不但拔出，還要毀滅。這是耶和華說的。」","notes":[]}]},"13":{"heading":"腰帶的比喻","verses":[{"n":1,"t":"耶和華對我如此說：「你去買一條麻布帶子，束在你腰上，不可把它泡在水裏。」","notes":[]},{"n":2,"t":"我就照耶和華的話，買了一條帶子，束在我的腰上。","notes":[]},{"n":3,"t":"耶和華的話第二次臨到我，說：","notes":[]},{"n":4,"t":"「要拿你所買、在你腰上的帶子，起來往幼發拉底河去，把腰帶藏在那裏的磐石穴中。」","notes":[]},{"n":5,"t":"我就去，照著耶和華命令我的，把腰帶藏在幼發拉底河邊。","notes":[]},{"n":6,"t":"過了多日，耶和華對我說：「你起來往幼發拉底河去，把我命令你藏在那裏的腰帶取出來。」","notes":[]},{"n":7,"t":"我就往幼發拉底河去，把那腰帶從我所藏的地方挖出來。看哪，腰帶已經破爛，毫無用處了。","notes":[]},{"n":8,"t":"耶和華的話臨到我，說：","notes":[]},{"n":9,"t":"「耶和華如此說：我要照樣敗壞猶大的驕傲和耶路撒冷的狂傲。","notes":[]},{"n":10,"t":"這惡民不肯聽我的話，按自己頑梗的心而行，隨從別神，事奉敬拜它們；這惡民必像這腰帶，毫無用處。","notes":[]},{"n":11,"t":"腰帶怎樣緊貼人的腰，照樣，我也曾使以色列全家和猶大全家緊貼著我，歸我為子民，使我得名聲，得頌讚，得榮耀；他們卻不肯聽從。這是耶和華說的。」","notes":[]},{"n":12,"t":"「所以你要對他們說：『耶和華－以色列的神如此說：各罈都要裝滿酒。』他們必對你說：『我們豈不知道各罈都要裝滿酒嗎？』","notes":[],"heads":["酒罈的比喻"]},{"n":13,"t":"你就對他們說：『耶和華如此說：看哪，我必使這地所有的居民，就是坐大衛寶座的君王、祭司和先知，並耶路撒冷所有的居民，都酩酊大醉。","notes":[]},{"n":14,"t":"我要使他們彼此衝突，連父與子也互相衝突；我必不可憐，不顧惜，不憐憫，以致將他們滅絕。這是耶和華說的。』」","notes":[]},{"n":15,"t":"你們當聽，當側耳而聽；不可驕傲，因為耶和華已經吩咐了。","notes":[],"heads":["耶利米警告狂傲的行為"]},{"n":16,"t":"當耶和華－你們的神尚未使黑暗來臨，在昏暗的山上你們的腳未絆跌以前，要將榮耀歸給他。你們盼望光明，他卻使光明變為死蔭，成為幽暗。","notes":[]},{"n":17,"t":"你們若不聽這話，我的心必因你們的驕傲暗自哭泣；我的眼必痛哭流淚，因為耶和華的羊群被擄去了。","notes":[]},{"n":18,"t":"你要對君王和太后說：「你們當自卑，坐下；因你們的王冠，就是你們華美的冠冕已經掉落了。」","notes":["「因你們...掉落了」：七十士譯本和其他古譯本是「因你們華美的冠冕已經從頭上掉落了」。"]},{"n":19,"t":"尼革夫的城鎮都被關閉，無人打開；猶大全被擄掠，擄掠淨盡。","notes":["「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」；本卷書下同。"]},{"n":20,"t":"你們要舉目觀看從北方來的人。先前賜給你的羊群，就是你所引以為榮的羊，現今在哪裏呢？","notes":[]},{"n":21,"t":"耶和華立你自己所教導的盟友，立他們為頭來轄制你，你還有甚麼話可說呢？痛苦豈不將你抓住像臨產的婦人嗎？","notes":["「耶和華...可說呢？」或譯「當他來懲罰你的時候，你還有甚麼話可說呢？你自己所教導的盟友作頭來轄制你。」"]},{"n":22,"t":"你若心裏說：「這一切的事為何臨到我呢？」是因你罪孽甚多。你的下襬揭起，你的腳跟受傷。","notes":[]},{"n":23,"t":"古實人豈能改變皮膚呢？豹豈能改變斑點呢？若能，你們這善於行惡的便能行善了。","notes":["「古實」包括蘇丹的大部分和埃塞俄比亞的一部分。"]},{"n":24,"t":"我必吹散他們，如碎稭隨曠野的風飄動。","notes":[]},{"n":25,"t":"這是你所當得的，是我量給你的報應；因為你忘記了我，倚靠虛假。這是耶和華說的。","notes":["「我量給你的報應」：七十士譯本是「你們背叛我的報應」。","「虛假」或譯「偶像」。"]},{"n":26,"t":"我要揭起你的下襬，蒙在你臉上，顯露你的羞恥。","notes":[]},{"n":27,"t":"你在田野的山上行姦淫，發嘶聲，謀淫亂，這些可憎之事我都看見了。耶路撒冷啊，你有禍了！你不肯潔淨還要等到幾時呢？","notes":["「你不肯潔淨」：七十士譯本是「你不肯潔淨來跟從我」。"]}]},"14":{"heading":"可怕的旱災","verses":[{"n":1,"t":"耶和華的話臨到耶利米，論到旱災的事：","notes":[]},{"n":2,"t":"「猶大悲哀，城門衰敗；眾人坐在地上哀慟，耶路撒冷的哀聲上達。","notes":[]},{"n":3,"t":"他們的貴族打發僮僕去打水；他們來到水池，找不到水，就拿著空器皿，蒙羞慚愧，抱頭而回。","notes":[]},{"n":4,"t":"因為無雨降在地上，土地就乾裂，農夫為此蒙羞抱頭。","notes":[]},{"n":5,"t":"田野的母鹿因為無草也撇棄才生的小鹿。","notes":[]},{"n":6,"t":"野驢站在光禿的高地喘氣，好像野狗；牠們的眼目因無草而失明。」","notes":[]},{"n":7,"t":"耶和華啊，雖然我們的罪孽控告我們，求你為你名的緣故行動吧！我們本是多次背道，得罪了你。","notes":[]},{"n":8,"t":"以色列所盼望，在患難時作他救主的啊，你在這地為何像寄居的，又如旅行的只住一夜呢？","notes":[]},{"n":9,"t":"你為何像受驚嚇的人，像不能救人的勇士呢？耶和華啊，你在我們中間，我們是稱為你名下的人，求你不要離開我們。","notes":[]},{"n":10,"t":"耶和華論到這百姓如此說：「這百姓喜愛遊蕩，不約束自己的腳步，所以耶和華不悅納他們。現今他要記起他們的罪孽，懲罰他們的罪惡。」","notes":[]},{"n":11,"t":"耶和華又對我說：「不要為這百姓求福。","notes":[]},{"n":12,"t":"他們禁食的時候，我不聽他們的呼求；他們獻燔祭和素祭，我也不悅納。我卻要用刀劍、饑荒、瘟疫滅絕他們。」","notes":[]},{"n":13,"t":"我就說：「唉！主耶和華，看哪，那些先知常對他們說：『你們必不見刀劍，也不遭饑荒；耶和華要在這地方賞賜你們真正的平安。』」","notes":[]},{"n":14,"t":"耶和華對我說：「那些先知託我的名說假預言，我並未差遣他們，沒有吩咐他們，也沒有對他們說話；他們向你們預言的是虛假的異象、占卜、虛無，以及心中的詭詐。","notes":[]},{"n":15,"t":"所以耶和華如此說：『論到託我名說預言的那些先知，我並未差遣他們；他們說這地不會有刀劍、饑荒，其實那些先知自己必被刀劍、饑荒滅絕。","notes":[]},{"n":16,"t":"聽他們說預言的百姓必因饑荒、刀劍被扔在耶路撒冷的街道上，無人埋葬。他們連妻子帶兒女，都是如此。我必將他們的惡倒在他們身上。』」","notes":[]},{"n":17,"t":"你要向他們說這些話：願我眼淚汪汪，晝夜不息，因為少女─我百姓受了重大的打擊，傷口極其嚴重。","notes":["「我百姓」：原文直譯「我百姓的女兒」。"]},{"n":18,"t":"我若出到田間，看哪，有被刀殺的；我若進入城內，看哪，有因饑荒患病的；先知和祭司也在各地往來經商，不知如何是好。","notes":[]},{"n":19,"t":"你全然棄絕猶大嗎？你的心厭惡錫安嗎？你為何擊打我們，使我們無法得醫治呢？我們指望平安，卻得不著福氣；指望痊癒，看哪，受了驚惶。","notes":[],"heads":["百姓懇求耶和華憐憫"]},{"n":20,"t":"耶和華啊，我們承認自己的罪惡和我們祖先的罪孽，因我們得罪了你。","notes":[]},{"n":21,"t":"求你為你名的緣故，不厭惡，不輕視你榮耀的寶座。求你記念，不要違背你與我們所立的約。","notes":[]},{"n":22,"t":"外邦虛無的神明中有能降雨的嗎？天能自降甘霖嗎？耶和華－我們的神啊，不是你嗎？我們要等候你，因為這一切都是你所造的。","notes":["「虛無的神明」：原文是「虛無」。"]}]},"15":{"heading":"猶大百姓的厄運","verses":[{"n":1,"t":"耶和華對我說：「雖有摩西和撒母耳站在我面前，我的心也不顧惜這百姓。你把他們從我眼前趕出，叫他們出去吧！","notes":[]},{"n":2,"t":"他們若問你說：『我們往哪裏去呢？』你就告訴他們，耶和華如此說：『定為死亡的，必致死亡；定為刀殺的，必被刀殺；定為饑荒的，必遭饑荒；定為擄掠的，必被擄掠。』」","notes":[]},{"n":3,"t":"「我命定四樣災害臨到他們，就是刀劍殺戮、群狗拖拉、空中的飛鳥和地上的走獸吞吃毀滅。這是耶和華說的。","notes":[]},{"n":4,"t":"我必使地上萬國因他們而驚駭，都因希西家的兒子猶大王瑪拿西在耶路撒冷所做的事。」","notes":[]},{"n":5,"t":"耶路撒冷啊，有誰同情你呢？有誰為你悲傷呢？有誰轉身問你安呢？","notes":[]},{"n":6,"t":"你棄絕了我，轉身退後；因此我伸手攻擊你，毀滅你，我已憐憫到厭煩了。這是耶和華說的。","notes":[]},{"n":7,"t":"我在境內各關口用簸箕篩我的百姓，使他們喪掉兒女，又毀滅他們，他們仍不轉離所行的道。","notes":[]},{"n":8,"t":"他們的寡婦在我面前比海沙更多；我使滅命者在正午來到，攻擊年輕人的母親，使痛苦驚嚇忽然臨到她身上。","notes":[]},{"n":9,"t":"生過七個孩子的婦人衰弱；尚在白晝，太陽忽然落下，她就抱愧蒙羞。我必當著敵人的面，將他們當中的倖存者交給刀劍。這是耶和華說的。","notes":[]},{"n":10,"t":"我的母親哪，我有禍了！因你生我作全地爭相指控的人。我素來沒有借貸給人，人也沒有借貸給我，人人卻都咒罵我。","notes":[],"heads":["耶利米向耶和華訴苦"]},{"n":11,"t":"耶和華說：「我必定釋放你，使你得福氣。災禍苦難來臨時，我必使仇敵央求你。","notes":["「釋放」：原文另譯「堅固」。"]},{"n":12,"t":"人豈能將銅與鐵，就是北方的鐵折斷呢？","notes":[]},{"n":13,"t":"「我必因你在四境之內所犯的一切罪，將你的貨物財寶當掠物，白白地交出來。","notes":["「白白地交出來」：原文直譯「不以任何代價交出來」；七十士譯本是「作為該付的代價」。"]},{"n":14,"t":"我要使你的仇敵過去，到你所不認識的地方，因為你們要被我怒中所起的火焚燒。」","notes":["「我要...地方」：有古卷和七十士譯本是「我要使你在你所不認識之地服侍你四圍的仇敵」。"]},{"n":15,"t":"耶和華啊，你是知道的；求你記念我，眷顧我，向迫害我的人為我報仇；不要把我取去，因你不輕易發怒，要知道我為你的緣故受了凌辱。","notes":[]},{"n":16,"t":"耶和華－萬軍之神啊，我得著你的話就把它們吃了，你的話是我心中的歡喜快樂；因我是稱為你名下的人。","notes":[]},{"n":17,"t":"我並未坐在享樂人的會中歡樂；因你的手，我就獨自靜坐，你使我滿心憤慨。","notes":[]},{"n":18,"t":"我的痛苦為何長久不止呢？我的傷痕為何無法可醫，不能痊癒呢？難道你以詭詐待我，像流乾的河道嗎？","notes":[]},{"n":19,"t":"所以耶和華如此說：「你若回轉，我就使你歸回，站在我面前。你若能將寶物和無用之物分別出來，你就可以當作我的口。他們必歸向你，你卻不可歸向他們。","notes":[]},{"n":20,"t":"我必使你向這百姓成為堅固的銅牆。他們必攻擊你，卻不能勝過你；因我與你同在，要拯救你，搭救你。這是耶和華說的。","notes":[]},{"n":21,"t":"我必搭救你脫離惡人的手，救贖你脫離殘暴之人的手。」","notes":[]}]},"16":{"heading":"耶和華要耶利米獨身","verses":[{"n":1,"t":"耶和華的話又臨到我，說：","notes":[]},{"n":2,"t":"「你不可在這地方娶妻，為自己生兒育女。","notes":[]},{"n":3,"t":"因為論到在這地方所生的兒女，又論到在這國中生他們的父母，耶和華如此說：","notes":[]},{"n":4,"t":"他們必死於致命的疾病，無人哀哭，不得埋葬，在地上如糞土，因刀劍和饑荒而滅絕；他們的屍首必給空中的飛鳥和地上的走獸作食物。","notes":[]},{"n":5,"t":"「耶和華如此說：不要進入喪家，不要去哀哭，也不要為他們悲傷，因我已使我的平安、慈愛、憐憫離開這百姓。這是耶和華說的。","notes":[]},{"n":6,"t":"他們連大帶小，都必在這地死亡，不得埋葬。人必不為他們哀哭，不為他們割劃自己，也不剃光頭。","notes":[]},{"n":7,"t":"有喪事，人不為他們擘餅 ，也不因死人安慰他們；他們喪父喪母，人也不給他們一杯酒安慰他們。","notes":["「有喪事...擘餅」：有古卷是「人不為喪家擘餅」。"]},{"n":8,"t":"你不可進入宴樂的家，與人同坐又吃又喝，","notes":[]},{"n":9,"t":"因為萬軍之耶和華－以色列的神如此說：看哪，你們還活著的日子，我必在你們眼前止息這地方歡喜和快樂的聲音、新郎和新娘的聲音。","notes":[]},{"n":10,"t":"「你將這一切的話指示這百姓，他們若問你說：『耶和華為甚麼說，要降這大災禍攻擊我們呢？我們有甚麼罪孽呢？我們向耶和華－我們的神犯了甚麼罪呢？』","notes":[]},{"n":11,"t":"你就對他們說：『因為你們祖先離棄了我，隨從別神，事奉敬拜它們，卻離棄我，不遵守我的律法。這是耶和華說的。","notes":[]},{"n":12,"t":"你們行惡比你們祖先更甚，看哪，各人隨從自己頑梗的惡心行事，不聽從我。","notes":[]},{"n":13,"t":"所以我必將你們從這地趕出，直趕到你們和你們祖先素不認識之地。你們在那裏晝夜必事奉別神，因為我必不再向你們施恩。』」","notes":[]},{"n":14,"t":"「看哪，日子將到，人必不再指著那領以色列人從埃及地上來的永生耶和華起誓。這是耶和華說的。","notes":[],"heads":["預告被擄歸回"]},{"n":15,"t":"人卻要指著那領以色列人離開北方之地，離開他們被趕到的各國之永生的耶和華起誓；並且我要領他們歸回我從前賜給他們祖先之地。」","notes":[]},{"n":16,"t":"「看哪，我要差派許多打魚的捕獲他們；以後，我也要派許多打獵的，從各山上、各岡上、各石穴中獵取他們。這是耶和華說的。","notes":[],"heads":["將要臨到的懲罰"]},{"n":17,"t":"因我的眼目察看他們一切的行為；他們不能在我面前遮掩，他們的罪孽也不能在我眼前隱藏。","notes":[]},{"n":18,"t":"我要先加倍報應他們的罪孽和罪惡，因為他們以可憎之偶像的屍首使我的地玷污，使我的產業充斥可厭之物。」","notes":[]},{"n":19,"t":"耶和華啊，你是我的力量，是我的保障，在患難之日是我的避難所。列國的人必從地極來到你這裏，說：「我們祖先所承受的，不過是虛假，是虛空無益之物。","notes":[],"heads":["耶利米的信心祈禱"]},{"n":20,"t":"人豈可為自己製造神明呢？其實它們不是神明。」","notes":[]},{"n":21,"t":"「所以，看哪，我要使他們知道，就是這一次使他們知道我的手和我的能力。他們就知道我的名是耶和華了。」","notes":[]}]},"17":{"heading":"猶大的罪和懲罰","verses":[{"n":1,"t":"猶大的罪是用鐵筆、用金剛石記錄的，銘刻在他們的心版和祭壇角上。","notes":[]},{"n":2,"t":"他們的兒女思念他們在高岡上、青翠樹旁的祭壇和亞舍拉。","notes":[]},{"n":3,"t":"我田野的山哪，因你在全境內的丘壇所犯的罪，我必使你的財富和一切的財寶成為掠物。","notes":[]},{"n":4,"t":"因自己所做的，你必失去我所賜給你的產業。我也必使你在你所不認識的地服侍你的仇敵；因你們激起了我的怒火，直燒到永遠。","notes":["「因自己所做的」：原文另譯「因自己的手所做的」或沒有「因自己所做的」。"]},{"n":5,"t":"耶和華如此說：「倚靠人，以血肉為膀臂，心中離棄耶和華的，那人該受詛咒！","notes":[],"heads":["訓誨集"]},{"n":6,"t":"他必像沙漠裏的矮樹，不見福樂來到；他要住在曠野乾旱之處，無人居住的鹽地。","notes":[]},{"n":7,"t":"倚靠耶和華、以耶和華為他所仰賴的，那人有福了！","notes":[]},{"n":8,"t":"他必像樹栽於水旁，在河邊扎根，炎熱來到，毫不察覺，葉子仍必青翠；在乾旱之年，一無掛慮，並且結果不止。","notes":["「察覺」：原文另譯「懼怕」。"]},{"n":9,"t":"「人心比萬物都詭詐，壞到極處，誰能識透呢？","notes":[]},{"n":10,"t":"我－耶和華是鑒察人心，考驗人肺腑的，要按各人所行的和他做事的結果報應他。」","notes":[]},{"n":11,"t":"那不按正道得財富的，好像鷓鴣孵不是自己生的；到了中年，財富必離開他，終久他必成為愚頑人。","notes":[]},{"n":12,"t":"我們的聖所是榮耀的寶座，從太初就在高處。","notes":[]},{"n":13,"t":"耶和華－以色列的盼望啊，凡離棄你的必蒙羞。離我而去的，他們必被寫在地裏，因為他們離棄耶和華，這活水的泉源。","notes":[]},{"n":14,"t":"耶和華啊，求你醫治我，我就痊癒，拯救我，我便得救；因你是我所讚美的。","notes":[],"heads":["耶利米求耶和華幫助"]},{"n":15,"t":"看哪，他們對我說：「耶和華的話在哪裏呢？讓它應驗吧！」","notes":[]},{"n":16,"t":"至於我，我並沒有逃避作牧人跟隨你，也沒有想望那災殃的日子；這是你所知道的。我嘴唇所出的都在你面前。","notes":["「我並沒有...跟隨你」：原文另譯「我不求你派來災難」。"]},{"n":17,"t":"不要使我因你驚恐；災禍來臨時，你是我的避難所。","notes":[]},{"n":18,"t":"願那些迫害我的蒙羞，卻不要使我蒙羞；使他們驚惶，卻不要使我驚惶；願災禍的日子臨到他們，以加倍的毀壞毀壞他們。","notes":[]},{"n":19,"t":"耶和華對我如此說：「你去站在猶大君王出入的平民門，和耶路撒冷的各城門口，","notes":[],"heads":["關於遵守安息日"]},{"n":20,"t":"對他們說：『你們這猶大君王、猶大眾人和耶路撒冷所有的居民，凡從這些城門進入的，都當聽耶和華的話。","notes":[]},{"n":21,"t":"耶和華如此說：你們要謹慎，不可在安息日挑甚麼擔子進入耶路撒冷的城門，","notes":[]},{"n":22,"t":"也不可在安息日從家中挑擔子出去。無論何工都不可做，只要以安息日為聖日，正如我所吩咐你們祖先的。』","notes":[]},{"n":23,"t":"他們卻不聽從，也不側耳而聽，竟硬著頸項不聽，不肯領受訓誨。","notes":[]},{"n":24,"t":"「你們若留意聽從我，在安息日不挑甚麼擔子進入這城的各門，只以安息日為聖日，在那日不做任何工作，這是耶和華說的，","notes":[]},{"n":25,"t":"就必有坐大衛寶座的君王和領袖，與猶大人，並耶路撒冷的居民，或坐車，或騎馬，進入這城的各門，而且這城必存到永遠。","notes":[]},{"n":26,"t":"也必有人從猶大城鎮和耶路撒冷四圍的各處，從便雅憫地、謝非拉、山區，並尼革夫而來，都帶燔祭和祭物，素祭和乳香，並感謝祭，到耶和華的殿去。","notes":["「謝非拉」是音譯，意思是「低地」；本卷書下同。"]},{"n":27,"t":"你們若不聽從我，不以安息日為聖日，仍在安息日挑擔子進入耶路撒冷的各城門，我必在城門中點火；這火必燒燬耶路撒冷的宮殿，不會熄滅。」","notes":[]}]},"18":{"heading":"耶利米在陶匠的家","verses":[{"n":1,"t":"耶和華的話臨到耶利米，說：","notes":[]},{"n":2,"t":"「你起來，下到陶匠的家裏去，在那裏我要使你聽見我的話。」","notes":[]},{"n":3,"t":"我就下到陶匠的家裏去，看哪，他在轉盤上做器皿。","notes":[]},{"n":4,"t":"陶匠用泥做的器皿在他手中做壞了，他就用它另做別的器皿，照他看為好的去做。","notes":[]},{"n":5,"t":"耶和華的話臨到我，說：","notes":[]},{"n":6,"t":"「以色列家啊，我待你們豈不能像這陶匠弄泥嗎？以色列家，看哪，泥在陶匠的手中怎樣，你們在我的手中也怎樣。這是耶和華說的。","notes":[]},{"n":7,"t":"我何時論到一邦或一國說，要拔出、拆毀、毀壞；","notes":[]},{"n":8,"t":"我所說的那一邦若回轉離開他們的惡，我就改變心意，不將我想要施行的災禍降與他們。","notes":[]},{"n":9,"t":"我何時論到一邦或一國說，要建立、栽植；","notes":[]},{"n":10,"t":"他們若行我眼中看為惡的事，不聽從我的話，我就改變心意，不將我所說的福氣賜給他們。","notes":[]},{"n":11,"t":"現在你要對猶大人和耶路撒冷的居民說：『耶和華如此說：看哪，我捏塑災禍降給你們，定意懲罰你們。你們各人當回轉離開所行的惡道，改正你們的所作所為。』","notes":[]},{"n":12,"t":"「他們卻說：『沒有用的，我們要照自己的計謀去行，各人要隨自己頑梗的惡心行事。』」","notes":[]},{"n":13,"t":"「所以，耶和華如此說：你們且往各國訪問，有誰聽見這樣的事？少女以色列行了一件極恐怖的事。","notes":[],"heads":["百姓忘記耶和華"]},{"n":14,"t":"黎巴嫩的雪豈能從田野的磐石上融化呢？從遠處流下的涼水豈能乾涸呢？","notes":["「田野」：原文另譯「西連」（黎巴嫩山頂）或「全能者」（參創17．1）。","「遠處」：原文是「外國」；原文另譯「山上」。"]},{"n":15,"t":"我的百姓竟忘記我，向那虛無的神明燒香，它們使百姓在所行的路上、在古道上絆跌，去行未修築的斜路，","notes":["「虛無的神明」：原文是「虛無」。"]},{"n":16,"t":"他們的地就變為荒涼，長久被人嘲笑；凡經過這地的必驚駭搖頭。","notes":[]},{"n":17,"t":"在仇敵面前，我必如東風颳散他們，遭難的日子，我要以背向他們，不以臉看他們。」","notes":[]},{"n":18,"t":"他們說：「來吧！讓我們設計謀害耶利米；因為我們有祭司講律法，有智慧人設謀略，有先知說預言，都未曾斷絕。來吧！讓我們用舌頭攻擊他，不要理他一切的話。」","notes":[],"heads":["謀害耶利米"]},{"n":19,"t":"耶和華啊，求你留心聽我，且聽那些指控我的人的話。","notes":[]},{"n":20,"t":"人豈可以惡報善呢？他們竟挖坑要害我的性命！求你記念我站在你面前為他們說好話，要使你的憤怒轉離他們。","notes":[]},{"n":21,"t":"因此，願他們的兒女忍受饑荒，願他們死於刀劍之手；願他們的妻無子，且作寡婦，願他們的男人被死亡所滅，他們的壯丁在陣上被刀擊殺。","notes":[]},{"n":22,"t":"你使敵軍忽然臨到他們的時候，願人聽見哀聲從他們的屋內發出；因他們挖坑要捉拿我，暗設羅網要絆我的腳。","notes":[]},{"n":23,"t":"耶和華啊，他們要殺我的那一切計謀，你都知道。求你不要赦免他們的罪孽，也不要從你面前塗去他們的罪惡。願他們在你面前跌倒，願你在發怒的時候對付他們。","notes":[]}]},"19":{"heading":"破碎的瓶","verses":[{"n":1,"t":"耶和華如此說：「你去買陶匠的瓷瓶 ，你和百姓中的長老、位尊的祭司","notes":["「你和」：七十士譯本和其他古譯本是「帶著」。"]},{"n":2,"t":"出去到欣嫩子谷、哈珥西的門口，在那裏宣告我所吩咐你的話，","notes":["「哈珥西」意思是「瓦片」。"]},{"n":3,"t":"說：『猶大君王和耶路撒冷的居民哪，當聽耶和華的話。萬軍之耶和華－以色列的神如此說：看哪，我必使災禍臨到這地方，凡聽見的人都必耳鳴；","notes":[]},{"n":4,"t":"因為他們和他們祖先，並猶大君王都離棄我，使這地方與我疏遠，在這裏向素不認識的別神燒香，又使這地方遍滿無辜人的血。","notes":["「使這地方與我疏遠」：七十士譯本是「將這地方看為平常」。"]},{"n":5,"t":"他們建造巴力的丘壇，要在火中焚燒自己的兒女，作為燔祭獻給巴力。這不是我命令的，不是我吩咐的，我心裏也從來沒有想過。","notes":[]},{"n":6,"t":"因此，看哪，日子將到，這地方不再稱為陀斐特和欣嫩子谷，反倒稱為殺戮谷。這是耶和華說的。","notes":[]},{"n":7,"t":"我要在這地方使猶大和耶路撒冷的計謀落空，也必使他們在仇敵面前倒在刀下，倒在尋索其命的人手下。我要把他們的屍首給空中的飛鳥和地上的走獸作食物。","notes":[]},{"n":8,"t":"我必使這城令人驚駭嘲笑；凡路過的，必因這城所遭的災難驚駭嘲笑。","notes":[]},{"n":9,"t":"仇敵和尋索其命的人追逼他們，使他們落在圍困窘迫之中，我必使他們各人吃自己兒女的肉和朋友的肉。』","notes":[]},{"n":10,"t":"「你要在跟你同去的人眼前打碎那瓶，","notes":[]},{"n":11,"t":"對他們說：『萬軍之耶和華如此說：我要打碎這民和這城，正如人打碎陶匠的器皿，不能再使其完整。他們要在陀斐特埋葬，甚至無處可葬。","notes":[]},{"n":12,"t":"我必向這地方和其中的居民如此行，使這城與陀斐特一樣。這是耶和華說的。","notes":[]},{"n":13,"t":"耶路撒冷的房屋和猶大君王的宮殿，就是他們在其上向天上的萬象燒香、向別神獻澆酒祭的宮殿房屋，都必被玷污，和陀斐特一樣。』」","notes":[]},{"n":14,"t":"耶利米從耶和華差他去說預言的陀斐特回來，站在耶和華殿的院中對眾百姓說：","notes":[]},{"n":15,"t":"「萬軍之耶和華－以色列的神如此說：『看哪，我必使我所說的一切災禍臨到這城和屬它的城鎮，因為他們硬著頸項不聽我的話。』」","notes":[]}]},"20":{"heading":"耶利米跟巴施戶珥的衝突","verses":[{"n":1,"t":"音麥的兒子巴施戶珥祭司作耶和華殿的總管，聽見耶利米預言這些事，","notes":[]},{"n":2,"t":"就打耶利米先知，用耶和華殿裏上便雅憫門內的枷鎖，把他鎖在那裏。","notes":[]},{"n":3,"t":"次日，巴施戶珥開枷釋放耶利米。於是耶利米對他說：「耶和華不叫你的名為巴施戶珥，而叫你瑪歌珥‧米撒畢，","notes":["「瑪歌珥‧米撒畢」意思是「四面驚嚇」。"]},{"n":4,"t":"因耶和華如此說：『看哪，我要使你和你的眾朋友驚嚇；你們要親眼看見他們倒在仇敵的刀下。我必將猶大人全都交在巴比倫王的手中，他要把他們擄到巴比倫去，用刀殺他們。","notes":[]},{"n":5,"t":"我要將這城中一切的貨財和勞碌得來的，並一切的珍寶，以及猶大君王所有的寶物，都交在仇敵手中。仇敵要搶奪他們，抓住他們，把他們帶到巴比倫去。","notes":[]},{"n":6,"t":"你，巴施戶珥，和所有住在你家中的人都必被擄；你和你的朋友，就是你向他們說假預言的，都要到巴比倫去，死在那裏，葬在那裏。』」","notes":[]},{"n":7,"t":"耶和華啊，你欺哄了我，我也被你欺哄了。你比我強，並且得勝。我終日成為笑柄，人人都戲弄我。","notes":[],"heads":["耶利米埋怨耶和華"]},{"n":8,"t":"我每逢講話的時候，就哀嘆，我喊叫：「有暴力和毀滅！」因為耶和華的話終日成了我的凌辱和譏刺。","notes":[]},{"n":9,"t":"我若說：「我不再提耶和華，也不再奉他的名講論」，我心裏便覺得似乎有燒著的火悶在我骨中，我忍受不住，不能自禁。","notes":[]},{"n":10,"t":"我聽見許多的毀謗，四圍都是驚嚇；連我知己朋友都看著我跌倒：「告他吧，我們要告他！或者他被引誘，我們就能勝他，在他身上報仇。」","notes":[]},{"n":11,"t":"然而，耶和華與我同在，好像可怕的勇士。因此，迫害我的都絆跌，不能得勝；他們大大蒙羞，由於行事沒有智慧，必永遠受那不能忘懷的羞辱。","notes":[]},{"n":12,"t":"考驗義人、察看人肺腑心腸的萬軍之耶和華啊，求你使我得見你在他們身上報仇，因我已將我的案件向你稟明了。","notes":[]},{"n":13,"t":"你們要向耶和華唱歌！要讚美耶和華！因他救了窮人的性命脫離惡人的手。","notes":[]},{"n":14,"t":"願我出生的那日受詛咒！願我母親生我的那天不蒙福！","notes":[]},{"n":15,"t":"報信給我父親說「你得了兒子」，使我父親甚歡喜的，願那人受詛咒。","notes":[]},{"n":16,"t":"願那人像耶和華所傾覆而不憐惜的城鎮；願他早晨聽見哀聲，中午聽見吶喊；","notes":[]},{"n":17,"t":"因他沒有在我未出胎就把我殺了，以致我母親成為我的墳墓，她卻一直懷著胎。","notes":["「她卻一直懷著胎」：七十士譯本是「胎兒就不斷長大」。"]},{"n":18,"t":"我為何出胎見勞碌愁苦，在羞愧中度盡我的年日呢？","notes":[]}]},"21":{"heading":"預言耶路撒冷滅亡","verses":[{"n":1,"t":"耶和華的話臨到耶利米。那時，西底家王差派瑪基雅的兒子巴施戶珥和瑪西雅的兒子西番雅祭司到他那裏去，說：","notes":[]},{"n":2,"t":"「請你為我們求問耶和華，因為巴比倫王尼布甲尼撒前來攻擊我們；或者耶和華照他一切奇妙的作為待我們，使巴比倫王離開我們而去。」","notes":[]},{"n":3,"t":"耶利米對他們說：「你們當對西底家這樣說：","notes":[]},{"n":4,"t":"『耶和華－以色列的神如此說：看哪，我要使你們手中的兵器，就是你們與城外圍困你們的巴比倫王和迦勒底人打仗所用的兵器轉回來，把它們聚集在這城中。","notes":[]},{"n":5,"t":"我要在怒氣、憤怒和大惱怒中，用伸出來的手和大能的膀臂，親自攻擊你們；","notes":[]},{"n":6,"t":"又要擊打這城的居民，他們連人帶牲畜都必遭遇大瘟疫而死亡。","notes":[]},{"n":7,"t":"以後，我要將猶大王西底家和他的臣僕百姓，就是在城內，從瘟疫、刀劍、饑荒中倖存的人，都交在巴比倫王尼布甲尼撒手中，交在仇敵和尋索其命的人手中。巴比倫王必用刀擊殺他們，不顧惜，不同情，不憐憫。這是耶和華說的。』","notes":[]},{"n":8,"t":"「你要對這百姓說：『耶和華如此說：看哪，我將生命的路和死亡的路擺在你們面前。","notes":[]},{"n":9,"t":"住在這城裏的必遭刀劍、饑荒、瘟疫而死；但出去投降圍困你們之迦勒底人的必得存活，保全自己的性命。","notes":[]},{"n":10,"t":"我向這城板臉，降禍不降福；這城必交在巴比倫王的手中，他必用火焚燒。這是耶和華說的。』」","notes":[]},{"n":11,"t":"「至於猶大王的家，你們當聽耶和華的話。","notes":[],"heads":["審判猶大王室"]},{"n":12,"t":"大衛家啊，耶和華如此說：『每早晨你們要施行公平，拯救被搶奪的脫離欺壓者的手，免得我的憤怒因你們的惡行發作，如火燃起，無人能熄滅。』","notes":[]},{"n":13,"t":"住在山谷和平原磐石上的居民啊，看哪，我與你們為敵，因為你們說：『誰能下來攻擊我們？誰能進入我們的住處呢？』這是耶和華說的。","notes":[]},{"n":14,"t":"我必按你們行事的結果懲罰你們，也必使火在耶路撒冷的林中燃起，將四圍所有的盡行燒滅。這是耶和華說的。」","notes":[]}]},"22":{"heading":"耶利米警告猶大王","verses":[{"n":1,"t":"耶和華如此說：「你要下到猶大王的宮中，在那裏說這話，","notes":[]},{"n":2,"t":"你要說：『坐大衛寶座的猶大王啊，你和你的臣僕，並進入這些城門的百姓，都當聽耶和華的話。","notes":[]},{"n":3,"t":"耶和華如此說：你們要施行公平和公義，拯救被搶奪的脫離欺壓者的手，不可虧負寄居的和孤兒寡婦，不可用殘暴對待他們，也不可在這地方流無辜人的血。","notes":[]},{"n":4,"t":"你們若切實遵行這話，就必有坐大衛寶座的君王和他的臣僕百姓，或坐車或騎馬，從這王宮的各門進入。","notes":[]},{"n":5,"t":"你們若不聽這些話，我指著自己起誓，這王宮必變為廢墟。這是耶和華說的。』","notes":[]},{"n":6,"t":"耶和華論到猶大王的家如此說：「我看你如基列，如黎巴嫩的山頂；然而，我必使你變為曠野，成為無人居住的城鎮。","notes":[]},{"n":7,"t":"我要預備施行毀滅的人，各人佩帶兵器攻擊你；他們要砍伐你佳美的香柏樹，扔在火中。","notes":[]},{"n":8,"t":"「許多國的百姓經過這城，就彼此談論說：『耶和華為何向這大城這樣做呢？』","notes":[]},{"n":9,"t":"必有人回答說：『是因他們離棄了耶和華－他們神的約，事奉敬拜別神。』」","notes":[]},{"n":10,"t":"不要為已死的人哀哭，也不要為他悲傷，卻要為離家外出的人大大哀哭；因為他不再回來見自己的出生地。","notes":[],"heads":["關於約哈斯"]},{"n":11,"t":"因為論到離開這地方的約西亞之子猶大王沙龍，就是接續他父親約西亞作王的，耶和華這樣說：「他必不再回到這裏來，","notes":["「沙龍」：王下23．30稱「約哈斯」。"]},{"n":12,"t":"卻要死在被擄去的地方，必不得再見這地。」","notes":[]},{"n":13,"t":"禍哉！那以不公義蓋房，以不公平造樓，白白使鄰舍做工，卻不給工錢的人，","notes":[],"heads":["關於約雅敬"]},{"n":14,"t":"他說：「我要為自己蓋寬敞的房，蓋高大的樓。」他為它開窗戶，以香柏木為牆板，漆上丹紅色。","notes":[]},{"n":15,"t":"難道你作王就是要蓋香柏木樓房爭勝的嗎？你的父親豈不是也吃也喝，也施行公平和公義嗎？那時他得了福樂。","notes":[]},{"n":16,"t":"他為困苦和貧窮的人伸冤，那時就得了福樂。認識我不就在此嗎？這是耶和華說的。","notes":[]},{"n":17,"t":"你的眼和你的心卻專顧不義之財，流無辜人的血，行欺壓和殘暴。","notes":[]},{"n":18,"t":"所以，耶和華論到約西亞的兒子猶大王約雅敬如此說：人必不為他舉哀：「哀哉，我的哥哥！哀哉，我的姊姊！」也不為他舉哀：「哀哉，我的主！哀哉，我主的榮華！」","notes":[]},{"n":19,"t":"他被埋葬好像埋驢子一樣，被拖出去，扔在耶路撒冷城門外。","notes":[]},{"n":20,"t":"你要上黎巴嫩哀號，在巴珊揚聲，從亞巴琳哀號，因為你所親愛的都毀滅了。","notes":[],"heads":["關於耶路撒冷百姓的命運"]},{"n":21,"t":"你興盛的時候，我對你說話；你卻說：「我不聽。」你從年輕時就是這樣，不肯聽我的話。","notes":[]},{"n":22,"t":"你的牧人要被風吞吃，你所親愛的必被擄去；那時你必因你一切的惡行抱愧蒙羞。","notes":[]},{"n":23,"t":"你這住黎巴嫩、在香柏樹上搭窩的，有痛苦臨到你，如疼痛臨到臨產的婦人，那時你何等可憐！","notes":["「何等可憐」：七十士譯本和其他古譯本是「就會呻吟」。"]},{"n":24,"t":"耶和華說：「約雅敬的兒子猶大王哥尼雅，雖是我右手上帶印的戒指，我憑我的永生起誓，我必將你從其上摘下來。","notes":["「哥尼雅」即「耶哥尼雅」，又名「約雅斤」；參王下24．6，耶24．1。"],"heads":["神審判哥尼雅"]},{"n":25,"t":"我要將你交在尋索你命的人和你所懼怕的人手中，就是巴比倫王尼布甲尼撒和迦勒底人手中。","notes":[]},{"n":26,"t":"我也要將你和生你的母親趕到別國，不是你們出生的地方；你們必死在那裏，","notes":[]},{"n":27,"t":"心中雖然很想歸回那地，卻不得歸回。」","notes":[]},{"n":28,"t":"哥尼雅這人是被輕看、遭毀壞的罐子，是無人喜愛的器皿嗎？他和他的後裔為何被趕到素不認識之地呢？","notes":[]},{"n":29,"t":"地啊，地啊，地啊，當聽耶和華的話！","notes":[]},{"n":30,"t":"耶和華如此說：「要把這人登記為無子，是平生不得亨通的人；因為他後裔中再無一人得亨通，能坐在大衛的寶座上治理猶大。」","notes":[]}]},"23":{"heading":"對將來的希望","verses":[{"n":1,"t":"耶和華說：「禍哉！那些殘害、趕散我草場之羊的牧人！」","notes":[]},{"n":2,"t":"耶和華－以色列的神論到那些牧養他百姓的牧人如此說：「你們趕散我的羊群，並未看顧他們；看哪，我必懲罰你們的惡行。這是耶和華說的。","notes":[]},{"n":3,"t":"我要從我趕他們到的各國召集我羊群中剩餘的，領他們歸回本處；他們必生養眾多。","notes":[]},{"n":4,"t":"我必設立牧人照管他們，牧養他們。他們不再懼怕，不再驚惶，沒有一個失喪的。這是耶和華說的。","notes":[]},{"n":5,"t":"「看哪，日子將到，我要為大衛興起公義的苗裔； 他必掌王權，行事有智慧，在地上施行公平和公義。這是耶和華說的。","notes":[]},{"n":6,"t":"在他的日子，猶大必得救，以色列也安然居住。他的名必稱為『耶和華－我們的義』。","notes":[]},{"n":7,"t":"「看哪，日子將到，人必不再指著那領以色列人從埃及地上來的永生耶和華起誓。這是耶和華說的。","notes":[]},{"n":8,"t":"人卻要指著那領以色列家的後裔離開北方之地、離開我趕他們到的各國的永生耶和華起誓。他們必住在本地。」","notes":[]},{"n":9,"t":"論到那些先知，我心在我裏面憂傷，我的骨頭全都發顫；因耶和華和他的聖言，我像醉酒的人，像被酒所勝的人。","notes":[],"heads":["對先知的警告"]},{"n":10,"t":"全地滿了犯姦淫的人！因妄自賭咒，地就悲哀，曠野的草場都枯乾了。他們所行的道是惡的；他們的權力用得不對。","notes":[]},{"n":11,"t":"連先知帶祭司都是褻瀆的，就是在我殿中，我也看見他們的惡行。這是耶和華說的。","notes":[]},{"n":12,"t":"因此，他們的道路必像黑暗中的滑地，他們必被追趕，仆倒在其上；因為在他們受罰之年，我必使災禍臨到他們。這是耶和華說的。","notes":[]},{"n":13,"t":"我在撒瑪利亞的先知中曾見狂妄的事；他們藉巴力說預言，使我的百姓以色列走迷了路。","notes":[]},{"n":14,"t":"我在耶路撒冷的先知中曾見恐怖的事；他們犯姦淫，行虛謊，又堅固惡人的手，無人回轉離開自己的惡行。他們在我面前都像所多瑪，耶路撒冷的居民都像蛾摩拉。","notes":[]},{"n":15,"t":"因此，萬軍之耶和華論到先知如此說：「看哪，我必使他們吃茵蔯，喝苦水；因為褻瀆的事出於耶路撒冷的先知，遍及各地。」","notes":[]},{"n":16,"t":"萬軍之耶和華如此說：「你們不要聽這些先知向你們所說的預言。他們使你們成為虛無，所說的異象是出於自己的心，不是出於耶和華的口。","notes":[]},{"n":17,"t":"他們常對藐視我的人說：『耶和華說：你們必享平安』又對一切按自己頑梗之心而行的人說：『災禍必不臨到你們。』」","notes":["「他們常對...平安』」七十士譯本是「他們常對藐視主的話的人說：『你們必享平安』」。"]},{"n":18,"t":"有誰站在耶和華的會中察看並聽見他的話呢？有誰留心聽他的話呢？","notes":[]},{"n":19,"t":"看哪！耶和華的暴風在震怒中發出，是旋轉的暴風，必轉到惡人頭上。","notes":[]},{"n":20,"t":"耶和華的怒氣必不轉消，直到他心中所定的成就了，實現了。末後的日子，你們要全然明白。","notes":[]},{"n":21,"t":"我並未差遣那些先知，他們竟自奔跑；我沒有對他們說話，他們竟自預言。","notes":[]},{"n":22,"t":"他們若站在我的會中，必使我的百姓聽我的話，又使他們回轉離開惡道，離開他們所行的惡。","notes":[]},{"n":23,"t":"我是靠近你們的神，不是遙遠的神，不是嗎？這是耶和華說的。","notes":["「我是...不是嗎？」或譯「我豈為近處的神呢？不也為遠處的神嗎？」"]},{"n":24,"t":"人豈能在隱密處藏身，使我看不見他呢？這是耶和華說的。我豈不遍滿天和地嗎？這是耶和華說的。","notes":[]},{"n":25,"t":"我已聽見那些先知所說的，他們託我的名說假預言：「我做了夢！我做了夢！」","notes":[]},{"n":26,"t":"所言虛假、心存詭詐的先知，他們這樣存心要到幾時呢？","notes":[]},{"n":27,"t":"他們彼此述說所做的夢，想要使我的百姓忘記我的名，正如他們祖先因巴力忘記我的名一樣。","notes":[]},{"n":28,"t":"得夢的先知可以述說那夢；領受我話的人可以誠實講我的話。糠秕怎能與麥子比較呢？這是耶和華說的。","notes":[]},{"n":29,"t":"我的話豈不像火，又像能打碎磐石的大錘嗎？這是耶和華說的。","notes":[]},{"n":30,"t":"看哪，那些先知各從鄰舍偷竊我的話，因此我必與他們為敵。這是耶和華說的。","notes":[]},{"n":31,"t":"那些先知用自己的舌頭說是耶和華說的；看哪，我必與他們為敵。這是耶和華說的。","notes":[]},{"n":32,"t":"那些以假夢為預言，又述說這夢，以謊言和魯莽使我百姓走迷了路的，看哪，我必與他們為敵。這是耶和華說的。我並未差遣他們，也沒有吩咐他們。他們對這百姓毫無益處。這是耶和華說的。","notes":[]},{"n":33,"t":"無論是這百姓、是先知、是祭司，問你說：「耶和華有甚麼默示呢？」你就對他們說：「甚麼默示啊？我已撇棄你們了。這是耶和華說的。」","notes":["「甚麼默示啊？」：原文另譯「你們就是重擔。」"],"heads":["耶和華的默示"]},{"n":34,"t":"凡說「耶和華的默示」的，無論是先知、是祭司、是百姓，我必懲罰那人和他的家。","notes":[]},{"n":35,"t":"你們各人要對鄰舍、對弟兄如此說：「耶和華回答了甚麼？耶和華說了甚麼呢？」","notes":[]},{"n":36,"t":"你們不可再提「耶和華的默示」，因為各人所說的話必成為自己的重擔；你們錯用了永生神、萬軍之耶和華－我們神的話。","notes":["「重擔」和「默示」原文相同。"]},{"n":37,"t":"你們要對先知如此說：「耶和華回答了你甚麼？耶和華說了甚麼呢？」","notes":[]},{"n":38,"t":"你們若說「耶和華的默示」，耶和華就必如此說：「我曾差人到你們那裏去，告訴你們不可說『耶和華的默示』這幾個字，你們卻說『耶和華的默示』；","notes":[]},{"n":39,"t":"所以，看哪，我必忘記你們，將你們和我所賜給你們並你們祖先的城都撇棄了；","notes":["「忘記你們」：原文另譯「將你們舉起來」。"]},{"n":40,"t":"又必使永遠的凌辱和長久的羞恥臨到你們，是不能忘記的。」","notes":[]}]},"24":{"heading":"兩筐無花果","verses":[{"n":1,"t":"巴比倫王尼布甲尼撒將約雅敬的兒子猶大王耶哥尼雅 和猶大的領袖，並工匠、鐵匠從耶路撒冷擄去，帶到巴比倫。這事以後，耶和華指給我看，看哪，有兩筐無花果放在耶和華殿前。","notes":["「耶哥尼雅」即「哥尼雅」；參耶22．24。"]},{"n":2,"t":"一筐是極好的無花果，像是初熟的；一筐是極壞的無花果，壞得不能吃。","notes":[]},{"n":3,"t":"耶和華對我說：「耶利米，你看見甚麼？」我說：「我看見無花果，好的極好，壞的極壞，壞得不能吃。」","notes":[]},{"n":4,"t":"於是耶和華的話臨到我，說：","notes":[]},{"n":5,"t":"「耶和華－以色列的神如此說：『被擄去的猶大人，就是我所打發離開這地到迦勒底人之地去的，我必看顧他們如這好的無花果，使他們得福樂。","notes":[]},{"n":6,"t":"我要眷顧他們，使他們得福樂，領他們歸回這地。我也要建立他們，必不拆毀；栽植他們，必不拔出。","notes":[]},{"n":7,"t":"我要賜給他們認識我的心，認識我是耶和華。他們要作我的子民，我要作他們的神，他們要一心歸向我。』」","notes":[]},{"n":8,"t":"耶和華如此說：「我必將猶大王西底家和他的眾領袖，以及留在這地耶路撒冷剩餘的人，並住在埃及地的猶大人都交出來，好像那極壞、壞得不能吃的無花果。","notes":[]},{"n":9,"t":"我必使他們在地上萬國中成為恐懼，成為災禍，在我趕逐他們到的各處成為凌辱、笑柄、譏笑、詛咒的對象。","notes":[]},{"n":10,"t":"我必使刀劍、饑荒、瘟疫臨到他們，直到他們從我所賜給他們和他們祖先之地滅絕。」","notes":[]}]},"25":{"heading":"從北方來的敵人","verses":[{"n":1,"t":"約西亞的兒子猶大王約雅敬第四年，就是巴比倫王尼布甲尼撒的元年，耶和華論猶大眾百姓的話臨到耶利米。","notes":[]},{"n":2,"t":"耶利米先知就將這些話對猶大眾百姓和耶路撒冷所有的居民說：","notes":[]},{"n":3,"t":"「從亞們的兒子猶大王約西亞十三年直到今日，在這二十三年中，常有耶和華的話臨到我；我也一再對你們傳講，只是你們不聽從。","notes":[]},{"n":4,"t":"耶和華也曾一再差遣他的僕人眾先知到你們這裏來，只是你們不聽從，也不側耳而聽，","notes":[]},{"n":5,"t":"說：『你們各人當回轉離開惡道和惡行，就可居住耶和華從古時所賜給你們和你們祖先之地，直到永遠。","notes":[]},{"n":6,"t":"不可隨從別神，事奉敬拜它們，以你們手所做的惹我發怒；這樣，我就不會降災禍給你們。","notes":[]},{"n":7,"t":"然而你們不聽從我，竟以手所做的惹我發怒，害了自己。這是耶和華說的。』」","notes":[]},{"n":8,"t":"所以萬軍之耶和華如此說：「因為你們不聽我的話，","notes":[]},{"n":9,"t":"看哪，我必召北方的眾族和我僕人巴比倫王尼布甲尼撒前來攻擊這地和這地的居民，並四圍所有的國民。我要將他們盡行滅絕，以致他們令人驚駭、嗤笑，並且永久荒涼。這是耶和華說的。","notes":["「永久荒涼」：七十士譯本是「成了永久的羞辱」。"]},{"n":10,"t":"我又要止息他們歡喜和快樂的聲音、新郎和新娘的聲音、推磨的聲音和燈的亮光。","notes":[]},{"n":11,"t":"這全地必然荒涼，令人驚駭。這些國家要服事巴比倫王七十年。","notes":[]},{"n":12,"t":"七十年滿了以後，我必懲罰巴比倫王和那國，並迦勒底人之地，因他們的罪孽使那地永遠荒涼。這是耶和華說的。","notes":[]},{"n":13,"t":"我也必使我向那地所說的話，就是所有記在這書上，耶利米向這些國家說的預言，都臨到那地。","notes":[]},{"n":14,"t":"因為必有許多國家和大君王使迦勒底人作奴僕；我也必照他們的行為，按他們手所做的報應他們。」","notes":[]},{"n":15,"t":"耶和華－以色列的神對我如此說：「你從我手中拿這杯憤怒的酒，給我所差遣你去的各國的百姓喝。","notes":[],"heads":["神審判列國"]},{"n":16,"t":"他們喝了就要東倒西歪，並要發狂，因我使刀劍臨到他們中間。」","notes":[]},{"n":17,"t":"我就從耶和華的手中拿了這杯，給耶和華所差遣我去的各國的百姓喝，","notes":[]},{"n":18,"t":"其中有耶路撒冷和猶大的城鎮，並耶路撒冷的君王與領袖；因此這城鎮荒涼，令人驚駭、嗤笑、詛咒，正如今日一樣。","notes":[]},{"n":19,"t":"又有埃及王法老和他的臣僕、官長，以及他的眾百姓，","notes":[]},{"n":20,"t":"並混居的各族和烏斯地的諸王，與非利士人之地的諸王，包括亞實基倫、迦薩、以革倫，以及亞實突剩下的人，","notes":[]},{"n":21,"t":"還有以東、摩押、亞捫人，","notes":[]},{"n":22,"t":"推羅的諸王、西頓的諸王、海的那邊沿海地區的諸王，","notes":[]},{"n":23,"t":"底但、提瑪、布斯，和所有剃鬢髮的人，","notes":[]},{"n":24,"t":"阿拉伯的諸王、住曠野混居各族的諸王、","notes":[]},{"n":25,"t":"心利的諸王、以攔的諸王、瑪代的諸王、","notes":[]},{"n":26,"t":"北方遠近的諸王，以及天下、地面上的萬國也一個一個都喝了，以後示沙克王也要喝。","notes":["「示沙克」就是巴比倫。"]},{"n":27,"t":"「你要對他們說：『萬軍之耶和華－以色列的神如此說：你們要喝，且要喝醉，要嘔吐，且要跌倒，不再起來，都因我使刀劍臨到你們中間。』","notes":[]},{"n":28,"t":"「他們若不肯從你手中拿這杯來喝，你就要對他們說：『萬軍之耶和華如此說：你們一定要喝！","notes":[]},{"n":29,"t":"看哪，我既從稱為我名下的城起首施行災禍，你們能免去懲罰嗎？你們必不能免，因為我要命刀劍臨到地上所有的居民。這是萬軍之耶和華說的。』","notes":[]},{"n":30,"t":"「所以你要向他們預言這一切的話，對他們說：『耶和華從高天吼叫，從聖所發出聲音，向自己的羊群大聲吼叫；他要向地上所有的居民吶喊，像踹葡萄的人一樣。","notes":[]},{"n":31,"t":"必有響聲達到地極，因為耶和華與列國爭辯。凡有血肉之軀的，他必審問；至於惡人，他必交給刀劍。這是耶和華說的。』","notes":[]},{"n":32,"t":"「萬軍之耶和華如此說：看哪，必有災禍發出，從這國到那國，並有大暴風從地極颳起。","notes":[]},{"n":33,"t":"「到那日，從地這邊到地那邊，都有耶和華所殺戮的人。必無人哀哭，不得收殮，不得埋葬，必在地面上成為糞土。","notes":[]},{"n":34,"t":"「牧人哪，你們當哀號，呼喊；羊群的領導者啊，你們要在灰中翻滾；因為你們被宰殺、被分散的日子已經來到。你們要仆倒，好像珍貴的器皿打碎一樣。","notes":["「被分散」是根據一些古卷；原文是「我打碎你們」。"]},{"n":35,"t":"牧人無路可逃，羊群的領導者也無法逃脫。","notes":[]},{"n":36,"t":"聽啊，有牧人呼喊，有羊群領導者哀號的聲音，因為耶和華摧毀他們的草場。","notes":[]},{"n":37,"t":"因耶和華猛烈的怒氣，平安的羊圈都被肅清。","notes":[]},{"n":38,"t":"他像獅子離開洞穴，他們的地因兇猛的怒氣和他強烈的怒氣，都變為荒涼。」","notes":["「兇猛的怒氣」：有古卷和七十士譯本是「殘暴的刀劍」。"]}]},"26":{"heading":"耶利米受審","verses":[{"n":1,"t":"約西亞的兒子猶大王約雅敬登基時，有這話從耶和華臨到耶利米，說：","notes":[]},{"n":2,"t":"「耶和華如此說：你要站在耶和華殿的院內，對猶大所有城鎮的人，就是到耶和華的殿來禮拜的，傳講我所吩咐你的一切話，一字也不可刪減。","notes":[]},{"n":3,"t":"或者他們肯聽從，各人回轉離開惡道，我就改變心意，不將我因他們所行的惡、想要施行的災禍降與他們。","notes":[]},{"n":4,"t":"你要對他們說，耶和華如此說：『你們若不聽從我，不遵行我在你們面前所設立的律法，","notes":[]},{"n":5,"t":"不聽從我一再差遣我僕人眾先知到你們那裏去所說的話，你們果然沒有聽從，","notes":[]},{"n":6,"t":"我就必使這殿如示羅，使這城成為地上萬國所詛咒的。』」","notes":[]},{"n":7,"t":"耶利米在耶和華殿中所說的這些話，祭司、先知與眾百姓都聽見了。","notes":[]},{"n":8,"t":"耶利米說完了耶和華吩咐他對眾百姓說的一切話，祭司、先知與眾百姓都來抓住他，說：「你該死！","notes":[]},{"n":9,"t":"你為何假借耶和華的名預言，說這殿必如示羅，這城必荒廢無人居住呢？」於是眾百姓都聚集在耶和華的殿中圍住耶利米。","notes":[]},{"n":10,"t":"猶大的官長們聽見這些事，就從王宮上到耶和華的殿，坐在耶和華殿新門的入口。","notes":[]},{"n":11,"t":"祭司、先知對官長和眾百姓說：「這人該死，因為他說預言攻擊這城，正如你們親耳聽見的。」","notes":[]},{"n":12,"t":"耶利米就對官長和眾百姓說：「耶和華差遣我預言攻擊這殿和這城，傳講你們所聽見的這一切話。","notes":[]},{"n":13,"t":"現在，要改正你們的所作所為，聽從耶和華－你們神的話，他就必改變心意，不把所說的災禍降與你們。","notes":[]},{"n":14,"t":"至於我，看哪，我在你們手中，你們眼裏看甚麼是好的，是正確的，就那樣待我吧！","notes":[]},{"n":15,"t":"但你們要確實知道，你們若把我處死，就使流無辜人血的罪歸給你們和這城，以及城裏的居民了；因為耶和華確實差遣我到你們這裏來，將這一切話傳到你們耳中。」","notes":[]},{"n":16,"t":"官長和眾百姓對祭司和先知說：「這人是不該死的，因為他奉耶和華－我們神的名向我們說話。」","notes":[]},{"n":17,"t":"國中的長老就有幾個人起來，對聚集的眾百姓說：","notes":[]},{"n":18,"t":"「當猶大王希西家的日子，有摩利沙人彌迦對猶大眾百姓預言說：『萬軍之耶和華如此說：錫安要被耕種像一塊田地，耶路撒冷要變為廢墟，這殿的山必像叢林的高處。』","notes":[]},{"n":19,"t":"猶大王希西家和猶大人豈是把他處死呢？希西家豈不是敬畏耶和華，懇求耶和華施恩嗎？耶和華就改變心意，不把所說的災禍降與他們。若處死這人，我們就做了大惡，害死自己了。」","notes":[]},{"n":20,"t":"有一個人，就是示瑪雅的兒子基列‧耶琳人烏利亞，也奉耶和華的名說預言；他說預言攻擊這城和這地，和耶利米所說的完全一樣。","notes":[]},{"n":21,"t":"約雅敬王和他所有的勇士、官長聽見了烏利亞的話，王想要把他處死。烏利亞聽見就懼怕，逃往埃及去了。","notes":[]},{"n":22,"t":"約雅敬王差亞革波的兒子以利拿單，帶領幾個人前往埃及。","notes":[]},{"n":23,"t":"他們將烏利亞從埃及帶出來，解送到約雅敬王那裏；王用刀殺了他，把他的屍首拋在平民的墳地中。","notes":[]},{"n":24,"t":"然而，沙番的兒子亞希甘保護耶利米，不將他交在百姓手中，以免他們把他處死。","notes":[]}]},"27":{"heading":"耶利米負軛","verses":[{"n":1,"t":"約西亞的兒子猶大王約雅敬登基時，有這話從耶和華臨到耶利米，說：","notes":["「約雅敬」：有古卷是「西底家」；參3、12節。"]},{"n":2,"t":"「耶和華對我如此說：你要為自己做皮帶和木軛，套在你的頸項上，","notes":[]},{"n":3,"t":"然後託那些來到耶路撒冷，到猶大王西底家那裏的使節，把皮帶和木軛送到以東王、摩押王、亞捫王、推羅王、西頓王那裏，","notes":[]},{"n":4,"t":"且囑咐他們轉達他們的主人。萬軍之耶和華－以色列的神如此說，你們要對你們的主人這樣說：","notes":[]},{"n":5,"t":"我用大能和伸出來的膀臂創造大地和地上的人民、牲畜。我看給誰合適，就把地給誰。","notes":[]},{"n":6,"t":"現在我將全地都交在我僕人巴比倫王尼布甲尼撒手中，也把野地的走獸給他使用。","notes":[]},{"n":7,"t":"列國都要服事他和他的子孫，直到他本國遭報的日期來到；那時，許多國家和大君王要使他作奴隸。","notes":[]},{"n":8,"t":"「無論哪一邦、哪一國，不肯服事巴比倫王尼布甲尼撒，不把頸項放在他的軛下，我必用刀劍、饑荒、瘟疫懲罰那邦，直到我藉巴比倫王的手毀滅他們。這是耶和華說的。","notes":[]},{"n":9,"t":"至於你們，不可聽從你們的先知和占卜的、做夢的、觀星象的，以及行邪術的；他們對你們說：『你們必不致服事巴比倫王。』","notes":["「做夢的」是根據七十士譯本和其他古譯本；原文是「夢」。"]},{"n":10,"t":"他們向你們傳的是假預言，要叫你們遠離本地，以致我將你們趕出去，使你們滅亡。","notes":[]},{"n":11,"t":"但哪一邦肯把頸項放在巴比倫王的軛下服事他，我必使那邦仍在本地存留，在那裏耕種居住。這是耶和華說的。」","notes":[]},{"n":12,"t":"我就照這一切話對猶大王西底家說：「你們要把頸項放在巴比倫王的軛下，服事他和他的百姓，就得存活。","notes":[]},{"n":13,"t":"你和你的百姓何必因刀劍、饑荒、瘟疫而死亡，像耶和華所論不肯服事巴比倫王的國家呢？","notes":[]},{"n":14,"t":"不可聽那些先知對你們所說的話，他們說：『你們必不致服事巴比倫王』，其實他們向你們傳的是假預言。","notes":[]},{"n":15,"t":"耶和華說：『我並未差遣他們，他們卻託我的名傳假預言，使我將你們和向你們說預言的那些先知趕出去，一同滅亡。』」","notes":[]},{"n":16,"t":"我又對祭司和這眾百姓說：「耶和華如此說：你們不可聽那先知對你們所說的預言，他們說：『看哪，耶和華殿中的器皿快要從巴比倫帶回來』；其實他們向你們傳的是假預言。","notes":[]},{"n":17,"t":"不可聽從他們，只管服事巴比倫王，就得存活。何必使這城變為廢墟呢？","notes":[]},{"n":18,"t":"他們若真是先知，有耶和華的話臨到他們，讓他們祈求萬軍之耶和華，使耶和華殿中和猶大王宮內，並耶路撒冷剩下的器皿，不致被帶到巴比倫去。","notes":[]},{"n":19,"t":"萬軍之耶和華這樣論柱子、銅海、盆座，並留在這城裏剩下的器皿，","notes":[]},{"n":20,"t":"就是巴比倫王尼布甲尼撒擄掠約雅敬的兒子猶大王耶哥尼雅，並猶大、耶路撒冷所有貴族時，沒有從耶路撒冷掠去巴比倫的器皿。","notes":[]},{"n":21,"t":"論到那在耶和華殿中和猶大王宮內，並耶路撒冷剩下的器皿，萬軍之耶和華－以色列的神如此說：","notes":[]},{"n":22,"t":"它們必被帶到巴比倫，存放在那裏，直到我眷顧以色列人，將這些器皿帶回歸還此地的日子。這是耶和華說的。」","notes":[]}]},"28":{"heading":"耶利米和哈拿尼雅","verses":[{"n":1,"t":"當年，就是猶大王西底家登基第四年五月，押朔的兒子基遍人哈拿尼雅先知，在耶和華的殿中當著祭司和眾百姓的面對我說：","notes":[]},{"n":2,"t":"「萬軍之耶和華－以色列的神如此說：我已經折斷巴比倫王的軛。","notes":[]},{"n":3,"t":"二年之內，我要將巴比倫王尼布甲尼撒從這地擄掠到巴比倫的器皿，就是耶和華殿中的一切器皿，都帶回此地。","notes":[]},{"n":4,"t":"我又要將約雅敬的兒子猶大王耶哥尼雅和被擄到巴比倫所有的猶大人帶回此地，因為我要折斷巴比倫王的軛。這是耶和華說的。」","notes":[]},{"n":5,"t":"耶利米先知當著祭司和站在耶和華殿裏眾百姓的面，對哈拿尼雅先知說：","notes":[]},{"n":6,"t":"「阿們！願耶和華如此行，願耶和華實現你所預言的話，將耶和華殿中的器皿和所有被擄去的人從巴比倫帶回此地。","notes":[]},{"n":7,"t":"然而我在你和眾百姓耳中所要說的話，你應當聽。","notes":[]},{"n":8,"t":"從古以來，在你我以前的眾先知，向多國和大邦說預言，論到戰爭、災禍、瘟疫的事。","notes":["「災禍」：有古卷是「饑荒」。"]},{"n":9,"t":"至於那預言平安的先知，到先知的話應驗的時候，人就知道他真是耶和華所差來的。」","notes":[]},{"n":10,"t":"哈拿尼雅先知就取下耶利米先知頸項上的軛，把它折斷。","notes":[]},{"n":11,"t":"哈拿尼雅又當著眾百姓的面說：「耶和華如此說：二年之內我必照樣從列國的頸項上折斷巴比倫王尼布甲尼撒的軛。」耶利米先知就離開了。","notes":[]},{"n":12,"t":"哈拿尼雅先知折斷耶利米先知頸項上的軛以後，耶和華的話臨到耶利米，說：","notes":[]},{"n":13,"t":"「你去告訴哈拿尼雅說，耶和華如此說：你折斷木軛，卻換來鐵軛！","notes":[]},{"n":14,"t":"萬軍之耶和華－以色列的神如此說：我已將鐵軛加在這些國的頸項上，使他們服事巴比倫王尼布甲尼撒。他們總要服事他，我也把野地的走獸給了他。」","notes":[]},{"n":15,"t":"於是耶利米先知對哈拿尼雅先知說：「哈拿尼雅啊，你應當聽！耶和華並沒有差遣你，你竟使這百姓倚靠謊言。","notes":[]},{"n":16,"t":"所以耶和華如此說：看哪，我要把你從地面上除掉，你今年必死，因為你向耶和華說了叛逆的話。」","notes":[]},{"n":17,"t":"這樣，哈拿尼雅先知當年七月間就死了。","notes":[]}]},"29":{"heading":"耶利米送信給巴比倫的猶大人","verses":[{"n":1,"t":"耶利米先知從耶路撒冷送信給被擄倖存的長老，以及祭司、先知，和尼布甲尼撒從耶路撒冷擄到巴比倫去的眾百姓。","notes":[]},{"n":2,"t":"這是在耶哥尼雅王和太后、太監，並猶大和耶路撒冷的領袖，以及工匠、鐵匠都離開耶路撒冷之後。","notes":[]},{"n":3,"t":"他藉沙番的兒子以利亞薩和希勒家的兒子基瑪利的手送去；他們二人是猶大王西底家差往巴比倫去見巴比倫王尼布甲尼撒的。","notes":[]},{"n":4,"t":"信上說：「萬軍之耶和華－以色列的神對所有被擄的，就是我使他們從耶路撒冷被擄到巴比倫去的人如此說：","notes":[]},{"n":5,"t":"你們要建造房屋，住在其中；要開墾田園，吃園中所出產的；","notes":[]},{"n":6,"t":"要娶妻生兒養女，為你們的兒子娶妻，使你們的女兒嫁人，生兒養女。你們要在那裏生養眾多，不可減少。","notes":[]},{"n":7,"t":"我使你們被擄到的那城，你們要為那城求平安，為那城向耶和華祈求，因為那城得平安，你們也隨著得平安。","notes":[]},{"n":8,"t":"萬軍之耶和華－以色列的神如此說：不要被你們中間的先知和占卜的所誘惑，也不要聽信你們所做的夢，","notes":["「你們」：原文另譯「他們」。"]},{"n":9,"t":"因為他們託我的名對你們說假預言，我並未差遣他們。這是耶和華說的。","notes":[]},{"n":10,"t":"「耶和華如此說：為巴比倫所定的七十年滿了以後，我要眷顧你們，向你們實現我的恩言，使你們歸回此地。","notes":[]},{"n":11,"t":"我知道我向你們所懷的意念是賜平安的意念，不是降災禍的意念，要叫你們末後有指望。這是耶和華說的。","notes":[]},{"n":12,"t":"你們呼求我，向我禱告，我就應允你們。","notes":[]},{"n":13,"t":"你們尋求我，若專心尋求我，就必尋見。","notes":[]},{"n":14,"t":"我必被你們尋見，也必使你們被擄的人歸回。這是耶和華說的。我必將你們從各國和我趕你們到的各處召集過來，又將你們帶回我使你們被擄離開的地方。這是耶和華說的。","notes":[]},{"n":15,"t":"「你們說：『耶和華已在巴比倫為我們興起先知。』","notes":[]},{"n":16,"t":"所以耶和華如此論坐大衛寶座的君王和住在這城裏所有的百姓，就是未曾與你們一同被擄的弟兄，","notes":[]},{"n":17,"t":"萬軍之耶和華如此說：『看哪，我必使刀劍、饑荒、瘟疫臨到他們，使他們像極壞的無花果，壞得不能吃。","notes":[]},{"n":18,"t":"我必用刀劍、饑荒、瘟疫追趕他們，使地上萬國因他們而驚駭；在我趕他們到的各國，令人詛咒、驚駭、嗤笑、羞辱。","notes":[]},{"n":19,"t":"這是因為他們不聽從我先前一再差遣我僕人眾先知說的話。這是耶和華說的。你們也一樣不聽。這是耶和華說的。』","notes":["「你們」：有古譯本是「他們」。"]},{"n":20,"t":"所以你們所有被擄去的，就是我從耶路撒冷放逐到巴比倫去的，當聽耶和華的話。","notes":[]},{"n":21,"t":"萬軍之耶和華－以色列的神論哥賴雅的兒子亞哈和瑪西雅的兒子西底家如此說：『他們託我的名向你們說假預言，看哪，我必把他們交在巴比倫王尼布甲尼撒的手中，他要在你們眼前殺害他們。","notes":[]},{"n":22,"t":"在巴比倫所有被擄的猶大人必藉這二人賭咒說：願耶和華使你像巴比倫王在火中焚燒的西底家和亞哈一樣。","notes":[]},{"n":23,"t":"這二人在以色列中做了醜事，與鄰舍的妻行淫，又假託我的名說我未曾吩咐他們的話。我知道這一切，也作見證。這是耶和華說的。』」","notes":[]},{"n":24,"t":"「你要對尼希蘭人示瑪雅說：","notes":[],"heads":["示瑪雅的信件"]},{"n":25,"t":"萬軍之耶和華－以色列的神如此說：你曾用自己的名送信給耶路撒冷的眾百姓和瑪西雅的兒子西番雅祭司，並眾祭司，說：","notes":[]},{"n":26,"t":"『耶和華已經立你西番雅為祭司，代替耶何耶大祭司，使耶和華的殿中有總管，好把所有狂妄自稱先知的人用枷枷住，用鎖鎖住。","notes":[]},{"n":27,"t":"現在亞拿突人耶利米向你們自稱先知，你為甚麼不責備他呢？","notes":[]},{"n":28,"t":"他送信給我們在巴比倫的人說：被擄的事必長久，你們要建造房屋，住在其中；要開墾田園，吃園中所出產的。』」","notes":[]},{"n":29,"t":"西番雅祭司就把這信念給耶利米先知聽。","notes":[]},{"n":30,"t":"於是耶和華的話臨到耶利米，說：","notes":[]},{"n":31,"t":"「你當送信給所有被擄的人，說：『耶和華論到尼希蘭人示瑪雅說：因為示瑪雅向你們說預言，使你們倚靠謊言，而我並沒有差遣他，","notes":[]},{"n":32,"t":"所以耶和華如此說：看哪，我必懲罰尼希蘭人示瑪雅和他的後裔，他必無一人存留住在這民中，也看不見我所要賞賜給我百姓的福樂，因為他向耶和華說了叛逆的話。這是耶和華說的。』」","notes":[]}]},"30":{"heading":"耶和華給他子民的應許","verses":[{"n":1,"t":"耶和華的話臨到耶利米，說：","notes":[]},{"n":2,"t":"「耶和華－以色列的神如此說：你要將我對你說過的一切話都寫在書上。","notes":[]},{"n":3,"t":"看哪，日子將到，我要使我的百姓以色列和猶大被擄的人歸回。這是耶和華說的。耶和華說：我要使他們回到我所賜給他們祖先之地，他們就得這地為業。」","notes":[]},{"n":4,"t":"以下是耶和華論到以色列和猶大所說的話：","notes":[]},{"n":5,"t":"耶和華如此說：「我們聽見顫抖的聲音，令人懼怕，沒有平安。","notes":[]},{"n":6,"t":"你們且訪查看看，男人會生孩子嗎？我怎麼看見人人都用手撐腰，像臨產的婦人，臉都發白了呢？","notes":[]},{"n":7,"t":"哀哉！那日為大，無日可比；這是雅各遭難的時刻，但他必從患難中得拯救。」","notes":["「臉都...哀哉！」：七十士譯本是「臉都變白了。」"]},{"n":8,"t":"萬軍之耶和華說：「到那日，我必折斷你頸項上仇敵的軛，拉斷你的皮帶。陌生人必不再使他作奴隸。","notes":[]},{"n":9,"t":"他們卻要事奉耶和華－他們的神，事奉我為他們所興起的大衛王。」","notes":[]},{"n":10,"t":"我的僕人雅各啊，不要懼怕；以色列啊，不要驚惶；因我從遠方拯救你，從被擄之地拯救你的後裔；雅各必回來得享平靜安逸，無人能使他害怕。這是耶和華說的。","notes":[]},{"n":11,"t":"因我與你同在，要拯救你，也要將那些國滅絕淨盡，就是我趕你去的那些國；卻不將你滅絕淨盡，倒要從寬懲治你，但絕不能不罰你。這是耶和華說的。","notes":[]},{"n":12,"t":"耶和華如此說：「你的損傷無法醫治，你的傷痕極其重大。","notes":[]},{"n":13,"t":"無人為你的傷痛辯護，也沒有可醫治你的良藥。","notes":[]},{"n":14,"t":"你所親愛的都忘記你，不來探望你。我因你罪孽甚大，罪惡眾多，曾藉仇敵加的傷害傷害你，藉殘忍者懲治你。","notes":[]},{"n":15,"t":"你為何因所受的損傷哀號呢？你的痛苦無法醫治。我因你罪孽甚大，罪惡眾多，曾將這些加在你身上。","notes":[]},{"n":16,"t":"因此，凡吞吃你的必被吞吃，你的敵人個個都被擄去；擄掠你的必成為擄物，我使搶奪你的成為掠物。","notes":[]},{"n":17,"t":"我必使你痊癒，醫好你的傷痕，都因人稱你為被趕散的，這是錫安，是無人來探望的！這是耶和華說的。」","notes":[]},{"n":18,"t":"耶和華如此說：「看哪，我必使雅各被擄去的帳棚歸回，也必顧惜他的住處。城必建造在原有的廢墟上，宮殿也必照樣有人居住。","notes":[]},{"n":19,"t":"必有感謝和歡樂的聲音從其中發出，我使他們增多，不致減少；使他們尊榮，不致卑微。","notes":[]},{"n":20,"t":"他們的兒女必如往昔；他們的會眾堅立在我面前；凡欺壓他們的，我必懲罰。","notes":[]},{"n":21,"t":"他們的君王是他們自己的人，掌權的必出自他們。我要使他接近我，他也要親近我；不然，誰敢放膽親近我呢？這是耶和華說的。","notes":[]},{"n":22,"t":"你們要作我的子民，我要作你們的神。」","notes":[]},{"n":23,"t":"看哪，耶和華的憤怒如暴風已經發出；是掃滅的暴風，必轉到惡人的頭上。","notes":[]},{"n":24,"t":"耶和華的烈怒必不轉消，直到他心中所定的成就了，實現了；末後的日子你們就會明白。","notes":[]}]},"31":{"heading":"以色列人回鄉","verses":[{"n":1,"t":"耶和華說：「那時，我必作以色列各家的神，他們必作我的子民。」","notes":[]},{"n":2,"t":"耶和華如此說：「從刀劍生還的百姓在曠野蒙恩；以色列尋找安歇之處。」","notes":[]},{"n":3,"t":"耶和華從遠方向我顯現：「我以永遠的愛愛你，因此，我以慈愛吸引你。」","notes":[]},{"n":4,"t":"少女以色列啊，我要再建立你，你就得以建立；你必再拿起手鼓，隨著歡樂的舞者而出。","notes":[]},{"n":5,"t":"你必在撒瑪利亞的山上栽葡萄園，栽種的人栽種，而且享用。","notes":[]},{"n":6,"t":"日子將到，守望的人必在以法蓮山上呼叫：「起來吧！我們要上錫安，到耶和華－我們的神那裏去。」","notes":[]},{"n":7,"t":"耶和華如此說：「你們當為雅各歡樂歌唱，為萬國中為首的歡呼。當傳揚，頌讚說：『耶和華啊，求你拯救你的百姓，拯救以色列的餘民。』","notes":["「耶和華啊...你的百姓」：七十士譯本是「主已拯救他的百姓」。"]},{"n":8,"t":"看哪，我必將他們從北方之地領來，從地極召集而來；同他們來的有盲人、瘸子、孕婦、產婦；他們必成群結隊回到這裏。","notes":[]},{"n":9,"t":"他們要哭泣而來。我要照他們懇求的引導他們，使他們在河水旁行走正直的路，他們在其上必不致絆跌；因為我是以色列的父，以法蓮是我的長子。","notes":[]},{"n":10,"t":"列國啊，要聽耶和華的話，要在遠方的海島傳揚，說：「趕散以色列的必召集他，看守他，如牧人看守羊群。」","notes":[]},{"n":11,"t":"因為耶和華救贖了雅各，救贖他脫離比他更強之人的手。","notes":[]},{"n":12,"t":"他們來到錫安的高處歌唱，因耶和華的宏恩而喜樂洋溢，就是五穀、新酒和新的油，並羔羊和牛犢。他們必像有水澆灌的園子，一點也不再有愁煩。","notes":[]},{"n":13,"t":"那時，少女必歡樂跳舞；年輕的、年老的，都一同歡樂；因為我要使他們的悲哀變為歡喜，並要安慰他們，使他們的愁煩轉為喜樂。","notes":[]},{"n":14,"t":"我必以肥油使祭司的心滿足，我的百姓也要因我的恩惠知足。這是耶和華說的。","notes":[]},{"n":15,"t":"耶和華如此說：「在拉瑪聽見號咷痛哭的聲音，是拉結哭她兒女，不肯因她兒女受安慰，因為他們都不在了。」","notes":[],"heads":["耶和華憐憫以色列"]},{"n":16,"t":"耶和華如此說：「不要出聲哀哭，你的眼目也不要流淚；因你的辛勞必有報償，他們必從仇敵之地歸回。這是耶和華說的。","notes":[]},{"n":17,"t":"你末後必有指望，你的兒女必回到自己的疆土。這是耶和華說的。","notes":[]},{"n":18,"t":"我聽見以法蓮為自己悲嘆說：『你管教我，我便受管教，我如未馴服的牛犢。求你使我回轉，我便回轉，因為你是耶和華－我的神。","notes":[]},{"n":19,"t":"我背離以後就懊悔，受教以後就捶胸；我因擔當年輕時的凌辱就抱愧蒙羞。』","notes":["「捶胸」：原文直譯「拍腿」，表示苦惱和悲傷。"]},{"n":20,"t":"以法蓮是我的愛子嗎？是我喜歡的孩子嗎？我每逢責備他，仍深顧念他。因此，我的心腸牽掛著他，我必要憐憫他。這是耶和華說的。","notes":[]},{"n":21,"t":"少女以色列啊，當為自己設立路標，為自己豎起指路牌。要留心向著大道，就是你曾走過的路；你當回轉，回到你自己的城鎮。","notes":[]},{"n":22,"t":"背道的女子啊，你翻來覆去要到幾時呢？耶和華在地上造了一件新事，就是女子護衛男子。」","notes":[]},{"n":23,"t":"萬軍之耶和華－以色列的神如此說：「我使被擄之人歸回的時候，他們在猶大地和其中的城鎮必再這樣說：公義的居所啊，聖山哪，願耶和華賜福給你。","notes":[],"heads":["神子民光明的前途"]},{"n":24,"t":"猶大和猶大城鎮的人，耕地的和帶著群畜遊牧的人，都要一同住在其中。","notes":[]},{"n":25,"t":"疲乏的人，我使他振作；愁煩的人，我使他滿足。」","notes":[]},{"n":26,"t":"於是我醒了，我看到我睡得香甜。","notes":[]},{"n":27,"t":"「看哪，日子將到，我要使人的後代和牲畜的種，在以色列家和猶大家繁衍。這是耶和華說的。","notes":[]},{"n":28,"t":"我先前怎樣看守他們，為要拔出、拆毀、毀壞、傾覆、苦害，也必照樣看守他們，為要建立、栽植。這是耶和華說的。","notes":[]},{"n":29,"t":"當那些日子，人不再說：『父親吃了酸葡萄，兒子牙齒就酸倒。』","notes":[]},{"n":30,"t":"但各人要因自己的罪死亡；凡吃酸葡萄的，自己的牙必酸倒。","notes":[]},{"n":31,"t":"「看哪，日子將到，我要與以色列家和猶大家另立新的約。這是耶和華說的。","notes":[]},{"n":32,"t":"這約不像我拉著他們祖宗的手，領他們出埃及地的時候與他們所立的約。我雖作他們的丈夫，他們卻背了我的約。這是耶和華說的。","notes":[]},{"n":33,"t":"那些日子以後，我與以色列家所立的約是這樣：我要將我的律法放在他們裏面，寫在他們心上。我要作他們的神，他們要作我的子民。這是耶和華說的。","notes":[]},{"n":34,"t":"他們各人不再教導自己的鄰舍和弟兄說：『你該認識耶和華』，因為他們從最小的到最大的都必認識我。我要赦免他們的罪孽，不再記得他們的罪惡。這是耶和華說的。」","notes":[]},{"n":35,"t":"耶和華使太陽白晝發光，按定例使月亮和星辰照耀黑夜，又攪動大海，使海中波浪澎湃，萬軍之耶和華是他的名，他如此說：","notes":[]},{"n":36,"t":"「這些定例若能在我面前廢掉，以色列的後裔才會在我面前斷絕，永遠不再成國。這是耶和華說的。」","notes":[]},{"n":37,"t":"耶和華如此說：「若有人能測量上面的天，探索下面地的根基，我才會因以色列後裔所做的一切棄絕他們。這是耶和華說的。」","notes":[]},{"n":38,"t":"看哪，日子將到，這城必為耶和華而造，從哈楠業樓直到角門。這是耶和華說的。","notes":[]},{"n":39,"t":"丈量的繩子要往外拉出，直到迦立山，又轉到歌亞；","notes":[]},{"n":40,"t":"拋屍的全谷和倒灰之處，並一切田地，直到汲淪溪，又到東邊馬門的角落，都要歸耶和華為聖；不再拔出，不再傾覆，直到永遠。","notes":[]}]},"32":{"heading":"耶利米購置田地","verses":[{"n":1,"t":"猶大王西底家第十年，就是尼布甲尼撒十八年，耶和華的話臨到耶利米。","notes":[]},{"n":2,"t":"那時巴比倫王的軍隊圍困耶路撒冷，耶利米先知被囚在猶大王宮中護衛兵的院內；","notes":[]},{"n":3,"t":"因為猶大王西底家囚禁他，說：「你為甚麼預言耶和華如此說：『看哪，我要把這城交在巴比倫王的手中，他必攻下這城。","notes":[]},{"n":4,"t":"猶大王西底家必不能逃脫迦勒底人的手，定要交在巴比倫王手中，他要親眼看到巴比倫王，親口跟他說話。","notes":[]},{"n":5,"t":"巴比倫王要將西底家帶到巴比倫；西底家必住在那裏，直到我懲罰他的時候。你們雖與迦勒底人爭戰，卻不順利。這是耶和華說的。』」","notes":["「懲罰」或譯「眷顧」。"]},{"n":6,"t":"耶利米說：「耶和華的話臨到我，說：","notes":[]},{"n":7,"t":"『看哪，你叔父沙龍的兒子哈拿篾必到你這裏來，說：請你買我在亞拿突的那塊地，因為你有代贖的責任。』","notes":[]},{"n":8,"t":"我叔父的兒子哈拿篾果然照耶和華的話來到護衛兵的院內，對我說：『請你買我在便雅憫境內、亞拿突的那塊地；因為它應該由你來承受，而且你也有代贖的責任。請你買下它吧！』我就知道這確是耶和華的話。","notes":[]},{"n":9,"t":"「我便向我叔父的兒子哈拿篾買了亞拿突的那塊地，秤了十七舍客勒銀子給他。","notes":[]},{"n":10,"t":"我在契上簽字，將契封緘，又請證人來，用天平把銀子秤給他。","notes":[]},{"n":11,"t":"我又將按照法定條例所立的買契，就是封緘的那一張和敞開的那一張，","notes":[]},{"n":12,"t":"在我叔父的兒子哈拿篾和簽字作證的人，並坐在護衛兵院內所有猶大人眼前，交給瑪西雅的孫子尼利亞的兒子巴錄。","notes":["「我叔父的兒子」是根據一些古卷、七十士譯本和其他古譯本；原文是「我叔父」。"]},{"n":13,"t":"我在眾人眼前囑咐巴錄說：","notes":[]},{"n":14,"t":"『萬軍之耶和華－以色列的神如此說：你拿著這文件，就是封緘的和敞開的買契，把它們放在瓦器裏，以便長久保存。","notes":[]},{"n":15,"t":"因為萬軍之耶和華－以色列的神如此說：將來在這地必有人再購置房屋、田地和葡萄園。』」","notes":[]},{"n":16,"t":"「我將買契交給尼利亞的兒子巴錄以後，就向耶和華禱告說：","notes":[],"heads":["耶利米的祈禱"]},{"n":17,"t":"『唉！主耶和華，看哪，你曾用大能和伸出來的膀臂創造天和地，在你沒有難成的事。","notes":[]},{"n":18,"t":"你施慈愛給千萬人，又將祖先的罪孽報應在他後世子孫身上。至大全能的神啊，萬軍之耶和華是你的名，","notes":[]},{"n":19,"t":"你謀事有大略，行事有大能，注目觀看世人一切的舉動，為要照各人所做的和他做事的結果報應他。","notes":[]},{"n":20,"t":"你在埃及地顯神蹟奇事，直到今日在以色列和世人中間也是如此，建立了自己的名聲，正如今日一樣。","notes":[]},{"n":21,"t":"你用神蹟奇事、大能的手、伸出來的膀臂和大可畏的事，領你的百姓以色列出了埃及，","notes":[]},{"n":22,"t":"把這地賞賜給他們，就是你向他們列祖起誓應許要賜給他們的流奶與蜜之地。","notes":[]},{"n":23,"t":"他們進入並取得這地，卻不聽從你的話，也不遵行你的律法。你吩咐他們所當行的，他們都不去行，因此你使這一切的災禍臨到他們。","notes":[]},{"n":24,"t":"看哪，敵人已經來到，用土堆攻取這城；這城也因刀劍、饑荒、瘟疫被交在攻城的迦勒底人手中。你所說的話都應驗了，看哪，你也看見了。","notes":[]},{"n":25,"t":"主耶和華啊，你卻對我說，要用銀子為自己買那塊地，又請人作證；其實這城已交在迦勒底人的手中了。』」","notes":[]},{"n":26,"t":"耶和華的話臨到耶利米，說：","notes":[]},{"n":27,"t":"「看哪，我是耶和華，是凡有血肉之軀者的神，在我豈有難成的事嗎？","notes":[]},{"n":28,"t":"耶和華如此說：看哪，我必將這城交給迦勒底人的手和巴比倫王尼布甲尼撒的手，他必攻取這城。","notes":[]},{"n":29,"t":"攻城的迦勒底人必來放火焚燒這城和城裏的房屋；人曾在這房頂上向巴力燒香，向別神獻澆酒祭，惹我發怒。","notes":[]},{"n":30,"t":"以色列人和猶大人從年輕時，就專做我眼中看為惡的事。以色列人盡以手所做的惹我發怒。這是耶和華說的。","notes":[]},{"n":31,"t":"這城自從建造的那日直到今日，常惹我的怒氣和憤怒，以致我將這城從我面前除掉；","notes":[]},{"n":32,"t":"這是因以色列人和猶大人一切的邪惡，就是他們和他們的君王、官長、祭司、先知，並猶大人，以及耶路撒冷居民所做的，惹我發怒。","notes":[]},{"n":33,"t":"他們以背向我，不以面向我；我雖然一再教導他們，他們卻不聽從，不領受訓誨，","notes":[]},{"n":34,"t":"竟把可憎之偶像設立在稱為我名下的殿中，玷污了這殿。","notes":[]},{"n":35,"t":"他們在欣嫩子谷建造巴力的丘壇，把自己的兒女經火獻給摩洛；他們行這可憎的事，使猶大陷在罪裏，這並不是我吩咐的，我心裏也從來沒有想過。」","notes":[]},{"n":36,"t":"現在論到這城，就是你們所說，已經因刀劍、饑荒、瘟疫被交在巴比倫王手中的，耶和華－以色列的神如此說：","notes":[],"heads":["復國的應許"]},{"n":37,"t":"「看哪，我曾在怒氣、憤怒和大惱怒中，將以色列人趕到各國；我必從那裏將他們召集出來，領他們回到此地，使他們安然居住。","notes":[]},{"n":38,"t":"他們要作我的子民，我要作他們的神。","notes":[]},{"n":39,"t":"我要使他們彼此同心同道，好叫他們永遠敬畏我，使他們和他們後世的子孫得享福樂。","notes":[]},{"n":40,"t":"我要跟他們立永遠的約，要施恩給他們，絕不轉離；又要把敬畏我的心放在他們心裏，不離棄我。","notes":[]},{"n":41,"t":"我必歡喜施恩給他們，盡心盡意、真誠地將他們栽於此地。","notes":[]},{"n":42,"t":"「因為耶和華如此說：我怎樣使這一切大災禍臨到這百姓，也要照樣使我所應許他們的一切福樂都臨到他們。","notes":[]},{"n":43,"t":"你們所說荒涼、無人、無牲畜，已交給迦勒底人手的這地，必有人購置田地。","notes":[]},{"n":44,"t":"在便雅憫地、耶路撒冷四圍的各處、猶大的城鎮、山地的城鎮、謝非拉的城鎮，並尼革夫的城鎮，人必用銀子買田地，在契上簽字，將契封緘，找人作證，因為我必使被擄的人歸回。這是耶和華說的。」","notes":[]}]},"33":{"heading":"重申復國的應許","verses":[{"n":1,"t":"耶利米還囚在護衛兵的院內，耶和華的話第二次臨到他，說：","notes":[]},{"n":2,"t":"「成事的耶和華，塑造它為要建立它的耶和華，名為耶和華的那位如此說：","notes":[]},{"n":3,"t":"『你求告我，我就應允你，並將你所不知道、又大又隱密的事指示你。","notes":[]},{"n":4,"t":"論到這城中的房屋和猶大君王的宮殿，就是拆毀來擋圍城工事和刀劍的，耶和華－以色列的神如此說：","notes":[]},{"n":5,"t":"他們與迦勒底人爭戰，用我在怒氣和憤怒中所殺之人的屍首塞滿這房屋；我因他們一切的惡，轉臉不顧這城。","notes":[]},{"n":6,"t":"看哪，我要使這城得以痊癒安舒，我要醫治他們，將豐盛的平安與信實顯明給他們。","notes":[]},{"n":7,"t":"我也要使猶大被擄的和以色列被擄的人歸回，並要建立他們，如起初一樣。","notes":[]},{"n":8,"t":"我要洗淨他們干犯我的一切罪，赦免他們干犯我、違背我的一切罪。","notes":[]},{"n":9,"t":"這城在地上萬國面前要因我的緣故，以喜樂得名，得頌讚，得榮耀，因為他們聽見我所賞賜的一切福樂。他們因我向這城所施的一切福樂平安，就懼怕戰兢。」","notes":[]},{"n":10,"t":"耶和華如此說：「你們論這地方，說是荒廢、無人、無牲畜之地，但在這荒涼、無人、無居民、無牲畜的猶大城鎮和耶路撒冷街上，必再聽見","notes":[]},{"n":11,"t":"歡喜和快樂的聲音、新郎和新娘的聲音，並聽見有人說：你們要稱謝萬軍之耶和華，因耶和華本為善，他的慈愛永遠長存！他們奉感謝祭到耶和華的殿中；因為我必使這地被擄的人歸回，如起初一樣。這是耶和華說的。」","notes":[]},{"n":12,"t":"萬軍之耶和華如此說：「在這荒廢、無人、無牲畜之地，並其中所有的城鎮，必再有牧人的草場，可讓羊群躺臥在那裏。","notes":[]},{"n":13,"t":"在山區的城鎮、謝非拉的城鎮、尼革夫的城鎮、便雅憫地、耶路撒冷四圍的各處和猶大的城鎮，必再有羊群從數點的人手下經過。這是耶和華說的。","notes":[]},{"n":14,"t":"「看哪，日子將到，我應許以色列家和猶大家的恩言必然實現。這是耶和華說的。","notes":[]},{"n":15,"t":"在那些日子、那時候，我必使大衛公義的苗裔長起來；他必在地上施行公平和公義。","notes":[]},{"n":16,"t":"在那些日子，猶大必得救，耶路撒冷必安然居住，他的名必稱為『耶和華－我們的義』。","notes":[]},{"n":17,"t":"「因為耶和華如此說：大衛家必永遠不斷有人坐在以色列家的寶座上；","notes":[]},{"n":18,"t":"利未家的祭司也不斷有人在我面前獻燔祭、燒素祭，時常辦理獻祭的事。」","notes":[]},{"n":19,"t":"耶和華的話臨到耶利米，說：","notes":[]},{"n":20,"t":"「耶和華如此說：你們若能廢棄我所立白日黑夜的約，使白日黑夜不按時輪轉，","notes":[]},{"n":21,"t":"就能廢棄我與我僕人大衛所立的約，使他沒有後裔在他的寶座上作王，並能廢棄我與事奉我的利未家的祭司所立的約。","notes":[]},{"n":22,"t":"正如天上的萬象不能數算，海邊的塵沙不能斗量，我必照樣使我僕人大衛的後裔和事奉我的利未人多起來。」","notes":[]},{"n":23,"t":"耶和華的話臨到耶利米，說：","notes":[]},{"n":24,"t":"「你沒有留意這百姓所說的話嗎？他們說：『耶和華所揀選的二族，他已經棄絕了。』他們這樣藐視我的百姓，不把他們當作國來看待。","notes":[]},{"n":25,"t":"耶和華如此說：除非我沒有立白日黑夜之約，也未曾安排天和地的定例，","notes":[]},{"n":26,"t":"否則我不會棄絕雅各的後裔和我僕人大衛的後裔，使大衛的後裔不再治理亞伯拉罕、以撒、雅各的後裔。我必使他們被擄的人歸回，也必憐憫他們。」","notes":[]}]},"34":{"heading":"給西底家的信息","verses":[{"n":1,"t":"巴比倫王尼布甲尼撒率領他的全軍和地上他管轄的各國各邦，攻打耶路撒冷和耶路撒冷所有的城鎮。那時，耶和華的話臨到耶利米，說：","notes":[]},{"n":2,"t":"「耶和華－以色列的神說，你去告訴猶大王西底家，耶和華如此說：看哪，我要把這城交在巴比倫王的手中，他必用火焚燒。","notes":[]},{"n":3,"t":"你必不能逃脫他的手，定被拿住，交在他手中。你要親眼看到巴比倫王，他要親口跟你說話，你也必到巴比倫去。","notes":[]},{"n":4,"t":"猶大王西底家啊，你一定要聽耶和華的話。耶和華論到你如此說：你必不死於刀下；","notes":[]},{"n":5,"t":"必平安而終，人要為你焚燒，好像為你祖先，就是在你以前早先的王焚燒一樣。人要為你舉哀說：『哀哉！我主啊。』這話是我說的。這是耶和華說的。」","notes":[]},{"n":6,"t":"於是，耶利米先知在耶路撒冷把這一切話告訴猶大王西底家。","notes":[]},{"n":7,"t":"那時，巴比倫王的軍隊正攻打耶路撒冷，又攻打猶大僅存的城鎮，就是拉吉和亞西加；原來猶大的堅固城只剩下這兩座。","notes":[]},{"n":8,"t":"西底家王與耶路撒冷的眾百姓立約，要他們宣告自由，叫各人釋放自己的僕人和婢女，使希伯來的男人和女人得自由，誰也不可使他的猶大弟兄作奴僕。這事以後，耶和華的話臨到耶利米。","notes":[],"end":9,"heads":["違背釋放奴隸的約"]},{"n":10,"t":"所有前來立約的領袖和眾百姓都順從，各人釋放自己的僕人和婢女，使他們得自由，不再叫他們作奴僕。大家都順從，將僕婢釋放了。","notes":[]},{"n":11,"t":"但後來他們又反悔，叫被釋放得自由的僕人婢女回來，強迫他們仍為僕婢。","notes":[]},{"n":12,"t":"因此耶和華的話臨到耶利米，說：","notes":[]},{"n":13,"t":"「耶和華－以色列的神如此說：我將你們祖先從埃及地為奴之家領出時，與他們立約說：","notes":[]},{"n":14,"t":"『你的一個希伯來弟兄若賣給你，服事你六年，到第七年你們各人就要釋放他自由出去。』只是你們祖先不聽我，不側耳而聽。","notes":[]},{"n":15,"t":"如今你們回轉，行我眼中看為正的事，各人向鄰舍宣告自由，並且在我面前、在稱為我名下的殿中立約。","notes":[]},{"n":16,"t":"你們卻反悔，褻瀆我的名，各人叫所釋放得自由的僕人婢女回來，強迫他們仍為僕婢。","notes":[]},{"n":17,"t":"所以耶和華如此說：你們不聽從我，各人不向弟兄鄰舍宣告自由。看哪！我要向你們宣告自由，把你們自由地交給刀劍、饑荒、瘟疫，並且使地上萬國因你們而驚駭。這是耶和華說的。","notes":[]},{"n":18,"t":"那些違背我約的人，就是不遵守在我面前立約之話的，我要使他們成了那劈成兩半的牛犢，使人從切塊中經過：","notes":[]},{"n":19,"t":"猶大的領袖、耶路撒冷的領袖、官員、祭司，和從牛犢切塊中經過的這地的眾百姓，","notes":[]},{"n":20,"t":"我必將他們交在仇敵和尋索其命的人手中；他們的屍首必給空中的飛鳥和地上的走獸作食物。","notes":[]},{"n":21,"t":"我必將猶大王西底家和他的眾領袖交在仇敵和尋索其命的人手中，與那暫時離你們而去的巴比倫王軍隊的手中。","notes":[]},{"n":22,"t":"看哪，我要吩咐他們回到這城，攻打這城，將城攻取，用火焚燒；我也要使猶大的城鎮變為廢墟，無人居住。這是耶和華說的。」","notes":[]}]},"35":{"heading":"耶利米和利甲族","verses":[{"n":1,"t":"當約西亞的兒子約雅敬作猶大王的時候，耶和華的話臨到耶利米，說：","notes":[]},{"n":2,"t":"「你去見利甲族的人，吩咐他們，領他們進入耶和華殿的一個房間，給他們酒喝。」","notes":[]},{"n":3,"t":"我就帶哈巴洗尼雅的孫子雅利米雅的兒子雅撒尼亞，和他的兄弟，並他所有的兒子，以及利甲全族的人，","notes":[]},{"n":4,"t":"領他們到耶和華的殿，進入伊基大利的兒子神人哈難兒子們的房間；那房間靠近官長的房間，在沙龍之子門口的守衛瑪西雅的房間上面。","notes":[]},{"n":5,"t":"於是我在利甲族的人面前擺設盛滿了酒的碗和杯，對他們說：「請喝酒。」","notes":[]},{"n":6,"t":"他們卻說：「我們不喝酒，因為我們祖先利甲的兒子約拿達曾吩咐我們說：『你們與你們的子孫永不可喝酒，","notes":[]},{"n":7,"t":"不可蓋房子，不可撒種，也不可栽葡萄園，連擁有都不可；但一生的年日要住帳棚，使你們的日子在寄居的地面上得以長久。』","notes":[]},{"n":8,"t":"凡我們祖先利甲的兒子約拿達所吩咐我們的話，我們都聽從了。我們和我們的妻子兒女一生的年日都不喝酒，","notes":[]},{"n":9,"t":"不蓋房子居住，我們也沒有葡萄園、田地和種子；","notes":[]},{"n":10,"t":"但住在帳棚裏，聽從並遵行我們祖先約拿達所吩咐我們的一切話。","notes":[]},{"n":11,"t":"巴比倫王尼布甲尼撒上來攻打這地的時候，我們說：『來吧，我們到耶路撒冷去，躲避迦勒底的軍隊和亞蘭的軍隊。』這樣，我們才住在耶路撒冷。」","notes":[]},{"n":12,"t":"耶和華的話臨到耶利米，說：","notes":[]},{"n":13,"t":"「萬軍之耶和華－以色列的神如此說：你去對猶大人和耶路撒冷的居民說，你們不肯領受訓誨，聽從我的話嗎？這是耶和華說的。","notes":[]},{"n":14,"t":"利甲的兒子約拿達所吩咐他子孫不可喝酒的話，他們已經遵守了；他們因為聽從祖先的吩咐，直到今日都不喝酒。至於我，我一再警戒你們，你們卻不肯聽從我。","notes":[]},{"n":15,"t":"我一再差遣我的僕人眾先知到你們那裏去，說：『你們各人當回頭離開惡道，改正行為，不再隨從事奉別神，如此，就必住在我所賜給你們和你們祖先的地上。』只是你們不側耳而聽，也不聽我。","notes":[]},{"n":16,"t":"利甲的兒子約拿達的子孫能遵守祖先所吩咐他們的命令，這百姓卻不肯聽從我！","notes":[]},{"n":17,"t":"因此，耶和華－萬軍之神、以色列的神如此說：看哪，我要使我所說的一切災禍臨到猶大人和耶路撒冷所有的居民。因為我向他們說話，他們不聽從；我呼喚他們，他們也沒有回應。」","notes":[]},{"n":18,"t":"耶利米對利甲族的人說：「萬軍之耶和華－以色列的神如此說：因你們聽從你們祖先約拿達的吩咐，謹守他的一切命令，照他所吩咐的去做，","notes":[]},{"n":19,"t":"所以萬軍之耶和華－以色列的神如此說：利甲的兒子約拿達必永遠不斷有人侍立在我面前。」","notes":[]}]},"36":{"heading":"巴錄在聖殿裏宣讀書卷","verses":[{"n":1,"t":"約西亞的兒子猶大王約雅敬第四年，有這話從耶和華臨到耶利米，說：","notes":[]},{"n":2,"t":"「你要取一書卷，把我對你所說攻擊以色列和猶大，並各國的一切話，從我對你說話的那日，就是從約西亞的日子起直到今日，都寫在其上；","notes":[]},{"n":3,"t":"或者猶大家聽見我想要降給他們的一切災禍，各人就回轉離開惡道，我就赦免他們的罪孽和罪惡。」","notes":[]},{"n":4,"t":"耶利米召了尼利亞的兒子巴錄來；巴錄就從耶利米口中，把耶和華對耶利米所說的一切話寫在書卷上。","notes":[]},{"n":5,"t":"耶利米吩咐巴錄說：「我被禁止，不能進耶和華的殿。","notes":[]},{"n":6,"t":"所以你要趁禁食的日子進入耶和華的殿中，把耶和華的話，就是你從我口中寫在書卷上的話，念給百姓和所有從各城鎮前來的猶大人親耳聽；","notes":[]},{"n":7,"t":"或者他們的懇求達到耶和華面前，各人回轉離開惡道，因為耶和華向這百姓所說要發的怒氣和憤怒實在很大。」","notes":[]},{"n":8,"t":"尼利亞的兒子巴錄就照耶利米先知所吩咐的一切去做，在耶和華殿中宣讀書卷上耶和華的話。","notes":[]},{"n":9,"t":"約西亞的兒子猶大王約雅敬第五年九月，耶路撒冷的眾百姓和那從猶大城鎮前來耶路撒冷的眾百姓，在耶和華面前宣告禁食，","notes":[]},{"n":10,"t":"巴錄就在耶和華殿的上院，靠近耶和華殿的新門口，沙番的兒子基瑪利雅文士的房間裏，宣讀書卷上耶利米的話給眾百姓親耳聽。","notes":[]},{"n":11,"t":"沙番的孫子基瑪利雅的兒子米該亞聽見書卷上耶和華的一切話，","notes":[],"heads":["向官長宣讀書卷"]},{"n":12,"t":"就下到王宮，進入書記的房間。看哪，所有的官長都坐在那裏，包括以利沙瑪文士、示瑪雅的兒子第萊雅、亞革波的兒子以利拿單、沙番的兒子基瑪利雅、哈拿尼雅的兒子西底家和其餘的官長。","notes":[]},{"n":13,"t":"米該亞向他們述說他所聽見的一切話，就是當巴錄向眾百姓宣讀那書卷時親耳聽見的。","notes":[]},{"n":14,"t":"官長們就派猶底，就是古示的曾孫、示利米雅的孫子、尼探雅的兒子到巴錄那裏，對他說：「你把你所念給百姓聽的書卷拿在手裏，到我們這裏來。」尼利亞的兒子巴錄就手拿書卷到他們那裏去。","notes":[]},{"n":15,"t":"他們對他說：「請坐下，念給我們親耳聽。」巴錄就念給他們親耳聽。","notes":[]},{"n":16,"t":"他們聽見這一切話就害怕，面面相覷，對巴錄說：「我們必須將這一切話稟告王。」","notes":[]},{"n":17,"t":"他們問巴錄說：「請你告訴我們，你怎樣從他口中寫下這一切話呢？」","notes":[]},{"n":18,"t":"巴錄回答說：「他向我口述這一切話，我就用筆墨把它寫在書卷上。」","notes":[]},{"n":19,"t":"眾官長對巴錄說：「你和耶利米要去躲起來，不可叫人知道你們躲在哪裏。」","notes":[]},{"n":20,"t":"眾官長把書卷留在以利沙瑪文士的房間裏，然後進院見王，把這一切話說給王聽。","notes":[],"heads":["約雅敬焚燒書卷"]},{"n":21,"t":"王就派猶底去拿這書卷來；他就從以利沙瑪文士的房間內取來，念給王和侍立在王左右的眾官長親耳聽。","notes":[]},{"n":22,"t":"那時正是九月，王坐在過冬的房屋裏，王前面有燃燒的火盆。","notes":["「王前面有燃燒的火盆」：七十士譯本是「王前面的火盆中有燃燒的火」。"]},{"n":23,"t":"猶底念了三、四段，王就用文士的刀把書卷割破，丟在火盆裏，直到全卷在火中燒盡了。","notes":["「段」或譯「欄」。"]},{"n":24,"t":"王和聽見這一切話的臣僕都不懼怕，也不撕裂衣服。","notes":[]},{"n":25,"t":"以利拿單和第萊雅，並基瑪利雅懇求王不要燒這書卷，王卻不聽。","notes":[]},{"n":26,"t":"王吩咐王的兒子耶拉篾、亞斯列的兒子西萊雅和亞伯疊的兒子示利米雅，去捉拿巴錄文士和耶利米先知；耶和華卻將他們隱藏起來。","notes":["「王」或譯「哈米勒」。"]},{"n":27,"t":"王燒了有巴錄從耶利米口中所寫之話的書卷以後，耶和華的話臨到耶利米，說：","notes":[],"heads":["耶利米另寫一書卷"]},{"n":28,"t":"「你再取一書卷，將猶大王約雅敬所燒前一卷書上原有的一切話寫在上面。","notes":[]},{"n":29,"t":"論到猶大王約雅敬你要說，耶和華如此說：你燒了這書卷，說：『你為甚麼在上面寫著，巴比倫王必要來毀滅這地，使這地絕了人民和牲畜呢？』","notes":[]},{"n":30,"t":"所以耶和華論到猶大王約雅敬說：他後裔中必沒有人坐在大衛的寶座上；他的屍首必被拋棄，白天受炎熱，黑夜受寒霜。","notes":[]},{"n":31,"t":"我必因他和他後裔，並他臣僕的罪孽懲罰他們。我要使我所說的一切災禍臨到他們和耶路撒冷的居民，並猶大人；只是他們不肯聽從。」","notes":[]},{"n":32,"t":"於是，耶利米又取一書卷交給尼利亞的兒子巴錄文士，他就從耶利米的口中寫了猶大王約雅敬在火中所燒書卷上的一切話，另外又添了許多相仿的話。","notes":[]}]},"37":{"heading":"西底家求耶利米代禱","verses":[{"n":1,"t":"約西亞的兒子西底家接續約雅敬的兒子哥尼雅作王，因為巴比倫王尼布甲尼撒立他在猶大地作王。","notes":[]},{"n":2,"t":"但西底家、他的臣僕和這地的百姓都不聽從耶和華藉耶利米先知所說的話。","notes":[]},{"n":3,"t":"西底家王派示利米雅的兒子猶甲和瑪西雅的兒子西番雅祭司，去見耶利米先知，說：「求你為我們祈求耶和華－我們的神。」","notes":[]},{"n":4,"t":"那時耶利米仍在百姓中進出，因為他們還沒有把他囚在監裏。","notes":[]},{"n":5,"t":"法老的軍隊已經從埃及出來，那圍困耶路撒冷的迦勒底人聽見這風聲，就拔營離開耶路撒冷去了。","notes":[]},{"n":6,"t":"耶和華的話臨到耶利米先知，說：","notes":[]},{"n":7,"t":"「耶和華－以色列的神如此說：你們要對派你們來求問我的猶大王如此說：『看哪，那出來幫助你們的法老軍隊必回埃及本國去。","notes":[]},{"n":8,"t":"迦勒底人必再來攻打這城，並要攻下，用火焚燒。","notes":[]},{"n":9,"t":"耶和華如此說：你們不要自欺說「迦勒底人必定離開我們」，因為他們必不離開。","notes":[]},{"n":10,"t":"你們即使擊敗與你們爭戰的迦勒底全軍，他們當中剩下受傷的人也必各自從帳棚裏起來，用火焚燒這城。』」","notes":[]},{"n":11,"t":"迦勒底的軍隊因躲避法老的軍隊，拔營離開耶路撒冷的時候，","notes":[],"heads":["耶利米被捕入獄"]},{"n":12,"t":"耶利米離開耶路撒冷，往便雅憫地去，要在那裏從百姓當中取得自己的地產。","notes":[]},{"n":13,"t":"他到了便雅憫門，那裏的守門官名叫伊利雅，是哈拿尼亞的孫子，示利米雅的兒子，他逮捕耶利米先知，說：「你是去投降迦勒底人的！」","notes":[]},{"n":14,"t":"耶利米說：「你這是謊話，我並不是去投降迦勒底人。」伊利雅不聽耶利米的話，就逮捕他，把他帶到官長那裏。","notes":[]},{"n":15,"t":"官長們惱怒耶利米，打了他，把他囚在約拿單文士的房屋中，因為他們把這屋子當作監牢。","notes":[]},{"n":16,"t":"耶利米來到地牢，進入牢房，在那裏拘留多日。","notes":[]},{"n":17,"t":"西底家王差人提他出來，在自己的宮內私下問他說：「有甚麼話從耶和華臨到沒有？」耶利米說：「有！」又說：「你必被交在巴比倫王手中。」","notes":[]},{"n":18,"t":"耶利米又對西底家王說：「我在甚麼事上得罪你，或你的臣僕，或這百姓，你們竟將我囚在監裏呢？","notes":[]},{"n":19,"t":"對你們預言『巴比倫王必不來攻擊你們和這地』的先知在哪裏呢？","notes":[]},{"n":20,"t":"主－我的王啊，現在求你垂聽，允准我在你面前的懇求：不要把我送回約拿單文士的房屋中，免得我死在那裏。」","notes":[]},{"n":21,"t":"於是西底家王下令，他們就把耶利米交在護衛兵的院中，每天從餅店街取一個餅給他，直到城中所有的餅都用盡了。這樣，耶利米仍逗留在護衛兵的院中。","notes":[]}]},"38":{"heading":"耶利米在井裏","verses":[{"n":1,"t":"瑪坦的兒子示法提雅、巴施戶珥的兒子基大利、示利米雅的兒子猶甲、瑪基雅的兒子巴示戶珥聽見耶利米對眾百姓所說的話，說：","notes":[]},{"n":2,"t":"「耶和華如此說：留在這城裏的必遭刀劍、饑荒、瘟疫而死，但歸向迦勒底人的必得存活；至少能保全自己的性命，得以存活。","notes":[]},{"n":3,"t":"耶和華如此說：這城必要交在巴比倫王軍隊的手中，他必攻下這城。」","notes":[]},{"n":4,"t":"於是官長們對王說：「求你把這人處死，因他向城裏剩下的士兵和眾人說這樣的話，使他們的手發軟。這人不是為這百姓求平安，而是叫他們受災禍。」","notes":[]},{"n":5,"t":"西底家王說：「看哪，他在你們手中，王不能反對你們所做的事。」","notes":[]},{"n":6,"t":"他們就拿住耶利米，把他丟在王的兒子瑪基雅的井裏；那口井在護衛兵的院中。他們用繩子把耶利米縋下去，井裏沒有水，只有淤泥，耶利米就陷在淤泥中。","notes":["「王」或譯「哈米勒」。"]},{"n":7,"t":"在王宮裏的太監古實人以伯‧米勒，聽見他們把耶利米丟進井裏，那時王坐在便雅憫門前。","notes":[]},{"n":8,"t":"以伯‧米勒從王宮裏出來，對王說：","notes":[]},{"n":9,"t":"「主－我的王啊，這些人向耶利米先知一味地行惡，把他丟在井裏；他在那裏必因飢餓而死，因為城裏不再有糧食了。」","notes":[]},{"n":10,"t":"王就吩咐古實人以伯‧米勒說：「你從這裏帶領三十人，趁耶利米先知還沒死，把他從井裏拉上來。」","notes":[]},{"n":11,"t":"於是以伯‧米勒帶領這些人同去，進入王宮，到庫房以下，從那裏取了些碎布和破衣服，用繩子縋下去，到井裏耶利米那裏。","notes":["「庫房以下」：原文另譯「庫房的衣櫃」。"]},{"n":12,"t":"古實人以伯‧米勒對耶利米說：「你用這些碎布和破衣服放在繩子上，墊你的腋下。」耶利米就照樣做。","notes":[]},{"n":13,"t":"這樣，他們用繩子將耶利米從井裏拉上來。耶利米仍在護衛兵的院中。","notes":[]},{"n":14,"t":"西底家王差人將耶利米先知帶進耶和華殿的第三個門，到王那裏去。王對耶利米說：「我要問你一件事，你一點都不可向我隱瞞。」","notes":[],"heads":["西底家問計於耶利米"]},{"n":15,"t":"耶利米對西底家說：「我若告訴你，你豈不是一定要把我處死嗎？我若勸你，你必不聽我。」","notes":[]},{"n":16,"t":"西底家王就私下對耶利米說：「我指著那造我們生命之永生的耶和華起誓：我必不把你處死，也不將你交在尋索你命的人手中。」","notes":[]},{"n":17,"t":"耶利米對西底家說：「耶和華－萬軍之神、以色列的神如此說：你若歸順巴比倫王的官長，你的命就必存活，這城也不致被火焚燒，你和你的全家都必存活。","notes":[]},{"n":18,"t":"你若不歸順巴比倫王的官長，這城必交在迦勒底人手中。他們必用火焚燒，你也不得脫離他們的手。」","notes":[]},{"n":19,"t":"西底家王對耶利米說：「我怕那些投降迦勒底人的猶大人，恐怕迦勒底人把我交在他們手中，他們就戲弄我。」","notes":[]},{"n":20,"t":"耶利米說：「迦勒底人必不把你交出。求你聽從我對你所說耶和華的話，這樣對你有好處，你的命也必存活。","notes":[]},{"n":21,"t":"你若不肯歸順，耶和華指示我的話是這樣：","notes":[]},{"n":22,"t":"看哪，猶大王宮裏所留下來的婦女必被帶到巴比倫王的官長那裏。這些婦女要說：你知己的朋友引誘你，他們勝過你；你的腳陷入淤泥，他們卻離棄你。","notes":[]},{"n":23,"t":"「人必將你的后妃和你的兒女帶到迦勒底人那裏；你也不得脫離他們的手，必被巴比倫王的手捉住，這城也必被火焚燒。」","notes":["「這城...焚燒」是根據一些古卷和七十士譯本；原文是「你將使這城焚燒」。"]},{"n":24,"t":"西底家對耶利米說：「不要讓人知道這些對話，你就不至於死。","notes":[]},{"n":25,"t":"官長們若聽見我跟你說話，到你那裏對你說：『告訴我們，你對王說了甚麼話，王又向你說了甚麼；不可向我們隱瞞，否則我們就要殺你。』","notes":[]},{"n":26,"t":"你就對他們說：『我在王面前懇求不要把我送回約拿單的房屋，免得我死在那裏。』」","notes":[]},{"n":27,"t":"隨後官長們到耶利米那裏，問他，他就照王所吩咐的一切話回答他們。他們就不再問他，因為事情沒有洩漏。","notes":[]},{"n":28,"t":"於是耶利米仍在護衛兵的院中，直到耶路撒冷被攻下的日子。當耶路撒冷被攻下時，他仍在那裏。","notes":["「當...那裏。」七十士譯本沒有此句。"]}]},"39":{"heading":"耶路撒冷陷落","verses":[{"n":1,"t":"猶大王西底家第九年十月，巴比倫王尼布甲尼撒率領全軍前來圍困耶路撒冷。","notes":[]},{"n":2,"t":"西底家十一年四月初九日，城被攻破。","notes":[]},{"n":3,"t":"耶路撒冷被攻下的時候，巴比倫王的眾官長，尼甲‧沙利薛、三甲‧尼波、撒西金將軍、尼甲‧沙利薛將軍，並巴比倫王其餘的官長都來坐在中門。","notes":["「將軍」：原文是巴比倫的武將官職「拉伯‧撒利」。","「將軍」：原文是巴比倫的武將官職「拉墨」。"]},{"n":4,"t":"猶大王西底家和所有士兵看見他們，就在夜間從靠近王的花園、兩城牆中間的門逃跑出城，往亞拉巴逃去。","notes":[]},{"n":5,"t":"迦勒底的軍隊追趕他們，在耶利哥的平原追上西底家，將他逮住，帶到哈馬地的利比拉、巴比倫王尼布甲尼撒那裏；尼布甲尼撒就判他的罪。","notes":[]},{"n":6,"t":"在利比拉，巴比倫王在西底家眼前殺了他的兒女；巴比倫王又殺了猶大所有的貴族，","notes":[]},{"n":7,"t":"並且挖了西底家的眼睛，用銅鏈鎖住他，要帶到巴比倫去。","notes":[]},{"n":8,"t":"迦勒底人用火焚燒王宮和百姓的房屋，又拆毀耶路撒冷的城牆。","notes":[]},{"n":9,"t":"那時，尼布撒拉旦護衛長把城裏所剩下的百姓和投降他的降民，以及其餘的百姓都擄到巴比倫去了。","notes":[]},{"n":10,"t":"尼布撒拉旦護衛長卻把百姓中一無所有的窮人留在猶大地，當時就賞給他們葡萄園和田地。","notes":["「賞給...田地」：原文另譯「讓他們當葡萄園的園丁和田地的工人」。"]},{"n":11,"t":"巴比倫王尼布甲尼撒為了耶利米，囑咐尼布撒拉旦護衛長：","notes":[],"heads":["耶利米被釋放"]},{"n":12,"t":"「你領他去，好好地看待他，切不可害他；他對你怎麼說，你就向他怎樣做。」","notes":[]},{"n":13,"t":"尼布撒拉旦護衛長和尼布沙斯班將軍、尼甲‧沙利薛將軍，並巴比倫王眾官長，","notes":["「將軍」：原文是巴比倫的武將官職「拉伯‧撒利」。","「將軍」：原文是巴比倫的武將官職「拉墨」。"]},{"n":14,"t":"派人把耶利米從護衛兵的院中提出來，交給沙番的孫子，亞希甘的兒子基大利，讓他自由進出屋子；於是耶利米住在百姓中間。","notes":[]},{"n":15,"t":"耶利米還囚在護衛兵院中的時候，耶和華的話臨到他，說：","notes":[],"heads":["以伯‧米勒的希望"]},{"n":16,"t":"「你去告訴古實人以伯‧米勒說，萬軍之耶和華－以色列的神如此說：看哪，我說降禍不降福的話必臨到這城，到那時必在你面前實現。","notes":[]},{"n":17,"t":"到那日我必拯救你，你必不致交在你所怕的人手中。這是耶和華說的。","notes":[]},{"n":18,"t":"我定要搭救你，你必不致倒在刀下，卻要保全自己的性命，因你倚靠我。這是耶和華說的。」","notes":[]}]},"40":{"heading":"耶利米跟基大利同住","verses":[{"n":1,"t":"耶利米被鏈子鎖在耶路撒冷和猶大被擄到巴比倫的人中，尼布撒拉旦護衛長把他從拉瑪提出來，釋放他以後，耶和華的話臨到耶利米。","notes":[]},{"n":2,"t":"護衛長提耶利米來，對他說：「耶和華－你的神曾說要降這災禍給此地。","notes":[]},{"n":3,"t":"耶和華照他所說的做了，已使這災禍臨到；因你們得罪耶和華，不聽從他的話，所以這事臨到你們。","notes":[]},{"n":4,"t":"看哪，現在我解開你手上的鏈子，你若看與我同往巴比倫去好，就可以去，我必厚待你；你若看與我同往巴比倫去不好，就不必去。看哪，全地在你面前，你以為哪裏美好，哪裏合宜，只管去吧","notes":[]},{"n":5,"t":"─耶利米尚未回去─你可以回到巴比倫王所立管理猶大城鎮的沙番的孫子，亞希甘的兒子基大利那裏去，在他那裏住在百姓當中。不然，你看哪裏合宜就可以去。」於是護衛長送他糧食和禮物，釋放了他。","notes":["「耶利米...回去」：原文另譯「耶利米尚未回答」；有古譯本是「如果你留下來的話」。"]},{"n":6,"t":"耶利米就來到米斯巴，亞希甘的兒子基大利那裏去，與他同住，住在留於境內的百姓當中。","notes":[]},{"n":7,"t":"在鄉間所有的軍官和屬他們的人，聽見巴比倫王立了亞希甘的兒子基大利作當地的省長，並將沒有擄到巴比倫的男人、婦女、孩童和當地極窮的人全交給他，","notes":[],"heads":["基大利出任省長"]},{"n":8,"t":"於是尼探雅的兒子以實瑪利，加利亞的兩個兒子約哈難和約拿單，單戶篾的兒子西萊雅，並尼陀法人以斐的眾子，瑪迦人的兒子耶撒尼亞，和屬他們的人，都來到米斯巴的基大利那裏。","notes":["「耶撒尼亞」：王下25．23稱「雅撒尼亞」。"]},{"n":9,"t":"沙番的孫子，亞希甘的兒子基大利向他們和屬他們的人起誓說：「不要怕服事迦勒底人，只管住在這地，服事巴比倫王，就可以得福。","notes":[]},{"n":10,"t":"至於我，我要住在米斯巴，侍候那些到我們這裏來的迦勒底人；只是你們當積蓄酒、油和夏天的果子，收藏在器皿裏，並住在你們所佔的城鎮中。」","notes":[]},{"n":11,"t":"在摩押地和亞捫人當中，在以東地和各國，所有的猶大人聽見巴比倫王留下一些猶大人，並立沙番的孫子、亞希甘的兒子基大利管理他們，","notes":[]},{"n":12,"t":"所有的猶大人就從被趕到的各處回來，到猶大地米斯巴的基大利那裏。他們積蓄了許多的酒，並夏天的果子。","notes":[]},{"n":13,"t":"加利亞的兒子約哈難和在鄉間的軍官來到米斯巴的基大利那裏，","notes":[],"heads":["基大利被暗殺"]},{"n":14,"t":"對他說：「亞捫人的王巴利斯派尼探雅的兒子以實瑪利來謀害你的命，你知道嗎？」亞希甘的兒子基大利卻不相信他們的話。","notes":[]},{"n":15,"t":"加利亞的兒子約哈難在米斯巴私下對基大利說：「求你容我去殺尼探雅的兒子以實瑪利，必無人知道。何必讓他害你的命，使聚集到你這裏來的猶大人都分散，以致猶大剩餘的人都滅亡呢？」","notes":[]},{"n":16,"t":"亞希甘的兒子基大利對加利亞的兒子約哈難說：「你不可做這事，你所論以實瑪利的話是假的。」","notes":[]}]},"41":{"heading":"","verses":[{"n":1,"t":"七月中，王的大臣，就是王室後裔以利沙瑪的孫子、尼探雅的兒子以實瑪利帶著十個人，來到米斯巴，亞希甘的兒子基大利那裏；他們在米斯巴一同吃飯。","notes":[]},{"n":2,"t":"尼探雅的兒子以實瑪利和同他來的那十個人起來，用刀擊殺沙番的孫子，亞希甘的兒子基大利，就是巴比倫王所立為當地省長的，把他殺死。","notes":[]},{"n":3,"t":"以實瑪利把所有在米斯巴與基大利一起的猶大人，以及他們在那裏所遇見的迦勒底人和士兵都殺了。","notes":[]},{"n":4,"t":"他殺了基大利的第二天，還沒有人知道的時候，","notes":[]},{"n":5,"t":"有八十人從示劍、示羅和撒瑪利亞前來，鬍鬚剃去，衣服撕裂，身體劃破，手拿素祭和乳香，要奉到耶和華的殿。","notes":[]},{"n":6,"t":"尼探雅的兒子以實瑪利從米斯巴出來迎接他們，隨走隨哭，遇見了他們，就對他們說：「你們可以到亞希甘的兒子基大利那裏。」","notes":[]},{"n":7,"t":"他們到了城中，尼探雅的兒子以實瑪利和與他一起的人就把他們殺了，丟在坑裏。","notes":[]},{"n":8,"t":"只是他們中間有十個人對以實瑪利說：「不要殺我們，因為我們有許多大麥、小麥、油和蜜藏在田間。」於是他住手，沒有在弟兄中間殺他們。","notes":[]},{"n":9,"t":"以實瑪利把那些因基大利事件所殺之人的屍首都丟在坑裏；這坑是從前亞撒王因怕以色列王巴沙所挖的。尼探雅的兒子以實瑪利把那些被殺的人填滿了坑。","notes":[]},{"n":10,"t":"以實瑪利把米斯巴剩下的人，就是眾公主和仍住在米斯巴所有的百姓都擄去，他們原是尼布撒拉旦護衛長交給亞希甘的兒子基大利的。尼探雅的兒子以實瑪利擄了他們，要到亞捫人那裏去。","notes":[]},{"n":11,"t":"加利亞的兒子約哈難和與他一起的軍官，聽見尼探雅的兒子以實瑪利所做的一切惡事，","notes":[]},{"n":12,"t":"就帶領眾人前往，要和尼探雅的兒子以實瑪利爭戰，他們在基遍的大水池旁遇見他。","notes":["「大水池」：原文是「大水」。"]},{"n":13,"t":"在以實瑪利那裏的眾人看見加利亞的兒子約哈難和與他一起的軍官，就都歡喜。","notes":[]},{"n":14,"t":"這樣，以實瑪利從米斯巴所擄去的眾人都轉身歸向加利亞的兒子約哈難。","notes":[]},{"n":15,"t":"尼探雅的兒子以實瑪利和八個人脫離約哈難的手，逃到亞捫人那裏去。","notes":[]},{"n":16,"t":"尼探雅的兒子以實瑪利殺了亞希甘的兒子基大利，從米斯巴把所有倖存的百姓、士兵、婦女、孩童、太監擄到基遍之後，加利亞的兒子約哈難和與他一起的軍官把他們都搶回來，","notes":[]},{"n":17,"t":"帶到靠近伯利恆的基羅特金罕住下，要到埃及去，","notes":["「基羅特金罕」或譯「金罕的寓所」。"]},{"n":18,"t":"躲避迦勒底人。他們懼怕迦勒底人，因為尼探雅的兒子以實瑪利殺了巴比倫王所立管理那地的亞希甘的兒子基大利。","notes":[]}]},"42":{"heading":"百姓求耶利米代禱","verses":[{"n":1,"t":"眾軍官和加利亞的兒子約哈難，並何沙雅的兒子耶撒尼亞以及眾百姓，從最小的到最大的都進前來，","notes":["「耶撒尼亞」：七十士譯本是「亞撒利雅」；參43．2。"]},{"n":2,"t":"對耶利米先知說：「請你准我們在你面前祈求，為我們這倖存的人向耶和華－你的神禱告。我們本來眾多，現在剩下的極少，這是你親眼看見的。","notes":[]},{"n":3,"t":"願耶和華－你的神指示我們當走的路，當做的事。」","notes":[]},{"n":4,"t":"耶利米先知對他們說：「我已經聽見了，看哪，我必照你們的話向耶和華－你們的神禱告。耶和華無論回答甚麼，我都必告訴你們，絕不隱瞞。」","notes":[]},{"n":5,"t":"於是他們對耶利米說：「我們若不照耶和華－你神差遣你說的一切話去做，願耶和華在我們中間作真實可靠的見證。","notes":[]},{"n":6,"t":"我們請你到耶和華－我們的神面前，他說的無論是好是歹，我們都必聽從；因為我們聽從耶和華－我們神的話，就可以得福。」","notes":[]},{"n":7,"t":"過了十天，耶和華的話臨到耶利米。","notes":[],"heads":["耶和華回答耶利米"]},{"n":8,"t":"他就將加利亞的兒子約哈難和與他一起所有的軍官和百姓，從最小的到最大的都召來，","notes":[]},{"n":9,"t":"對他們說：「你們請我到耶和華－以色列的神面前為你們祈求，他如此說：","notes":[]},{"n":10,"t":"『你們若仍留在這地，我就建立你們，必不拆毀；栽植你們，必不拔出；因我為所降與你們的災禍感到遺憾。","notes":[]},{"n":11,"t":"不要怕你們所懼怕的巴比倫王。不要怕他！因為我與你們同在，要拯救你們脫離他的手。這是耶和華說的。","notes":[]},{"n":12,"t":"我要向你們施憐憫，他就憐憫你們，使你們歸回本地。』","notes":["「他」：七十士譯本是「我」。"]},{"n":13,"t":"倘若你們說：『我們不留在這地』，不聽從耶和華－你們神的話，","notes":[]},{"n":14,"t":"說：『我們不留在這地，卻要進入埃及地，在那裏我們看不見戰爭，聽不見角聲，也不致缺食挨餓；我們要住在那裏。』","notes":[]},{"n":15,"t":"倖存的猶大人哪，你們現在要聽耶和華的話；萬軍之耶和華－以色列的神如此說：『你們若定意進入埃及，在那裏寄居，","notes":[]},{"n":16,"t":"你們所懼怕的刀劍在埃及地必追上你們，你們所懼怕的饑荒在埃及要緊緊跟隨你們，你們必死在那裏。","notes":[]},{"n":17,"t":"凡定意進入埃及在那裏寄居的，必遭刀劍、饑荒、瘟疫而死，無一人存留，得以逃脫我所降與他們的災禍。』","notes":[]},{"n":18,"t":"「萬軍之耶和華－以色列的神如此說：『我怎樣將我的怒氣和憤怒傾倒在耶路撒冷的居民身上，你們進入埃及的時候，我也必照樣將我的憤怒傾倒在你們身上，以致你們受辱罵、驚駭、詛咒、羞辱，並且不得再看見這地方。』","notes":[]},{"n":19,"t":"倖存的猶大人哪，耶和華論到你們說：『不要進入埃及。』你們要確實知道，我今日已警戒你們了。","notes":[]},{"n":20,"t":"你們行詭詐害自己；因為你們請我到耶和華－你們神那裏，說：『請你為我們向耶和華－我們的神禱告，你把耶和華－我們神所說的一切告訴我們，我們就必遵行。』","notes":[]},{"n":21,"t":"我今日把這話告訴你們，你們卻不聽耶和華－你們神為這一切事差我到你們那裏所說的話。","notes":[]},{"n":22,"t":"現在你們要確實知道，你們在所要去的寄居之地必遭刀劍、饑荒、瘟疫而死。」","notes":[]}]},"43":{"heading":"耶利米被帶到埃及","verses":[{"n":1,"t":"耶利米向眾百姓說完了耶和華－他們神一切的話，就是耶和華－他們神差他去說的這一切話，","notes":[]},{"n":2,"t":"何沙雅的兒子亞撒利雅和加利亞的兒子約哈難，以及所有狂傲的人，就對耶利米說：「你說謊！耶和華－我們的神並沒有差遣你說：『你們不可進入埃及，在那裏寄居。』","notes":[]},{"n":3,"t":"這是尼利亞的兒子巴錄挑唆你害我們，要把我們交在迦勒底人手中，使我們被殺或被擄到巴比倫去。」","notes":[]},{"n":4,"t":"加利亞的兒子約哈難和所有的軍官、百姓，都不肯聽從耶和華的話留在猶大地。","notes":[]},{"n":5,"t":"加利亞的兒子約哈難和所有的軍官卻將倖存的猶大人，就是從被趕到的各國回來，在猶大地寄居的男人、婦女、孩童和眾公主，並尼布撒拉旦護衛長留在沙番的孫子，亞希甘的兒子基大利那裏的眾人，與耶利米先知，以及尼利亞的兒子巴錄，","notes":[],"end":6},{"n":7,"t":"都帶入埃及地，到了答比匿；這是因他們不肯聽從耶和華的話。","notes":[]},{"n":8,"t":"在答比匿，耶和華的話臨到耶利米，說：","notes":[]},{"n":9,"t":"「你要在猶大人眼前用手拿幾塊大石頭，藏在答比匿法老的宮門砌磚的石墩上，","notes":[]},{"n":10,"t":"對他們說：『萬軍之耶和華－以色列的神如此說：看哪，我必召我的僕人巴比倫王尼布甲尼撒前來，安置他的寶座在所藏的這些石頭上；他要在其上支搭華麗的帳幕。","notes":[]},{"n":11,"t":"他要來攻擊埃及地：定為死亡的，必致死亡；定為擄掠的，必遭擄掠；定為刀殺的，必被刀殺。","notes":[]},{"n":12,"t":"我要用火點燃埃及眾神明的廟宇，巴比倫王要焚燒廟宇，擄去神像；他要圍住埃及地，好像牧人披上外衣，從那裏安然而去。","notes":[]},{"n":13,"t":"他必打碎埃及地伯‧示麥的柱像，用火焚燒埃及眾神明的廟宇。』」","notes":[]}]},"44":{"heading":"給流亡埃及以色列人的信息","verses":[{"n":1,"t":"有話臨到耶利米，論到住埃及地所有的猶大人，就是住在密奪、答比匿、挪弗、巴特羅境內的猶大人，說：","notes":[]},{"n":2,"t":"「萬軍之耶和華－以色列的神如此說：我所降與耶路撒冷和猶大各城的一切災禍，你們都看見了。看哪，那些城鎮今日荒涼，無人居住；","notes":[]},{"n":3,"t":"這是因居民所行的惡，去燒香事奉別神，就是他們和你們，以及你們列祖所不認識的神明，惹我發怒。","notes":[]},{"n":4,"t":"我一再差遣我的僕人眾先知去，說：你們切不可行我所厭惡這可憎之事。","notes":[]},{"n":5,"t":"他們卻不聽從，不側耳而聽，也不轉離惡事，仍向別神燒香。","notes":[]},{"n":6,"t":"因此，我的怒氣和憤怒都傾倒出來，在猶大城鎮和耶路撒冷街市上燃起，以致它們都荒廢淒涼，正如今日一樣。","notes":[]},{"n":7,"t":"現在耶和華－萬軍之神、以色列的神如此說：你們為何做這大惡自害己命，使你們的男人、婦女、孩童和吃奶的都從猶大剪除，不留一人呢？","notes":[]},{"n":8,"t":"你們以手所做的，在寄居的埃及地向別神燒香，惹我發怒，使你們被剪除，在天下萬國中受詛咒羞辱。","notes":[]},{"n":9,"t":"你們祖先的惡行，猶大諸王和后妃的惡行，你們自己和你們妻子的惡行，就是在猶大地和耶路撒冷街市上所做的，你們都忘了嗎？","notes":[]},{"n":10,"t":"到如今你們還不懊悔，不懼怕，不肯遵行我在你們和你們祖先面前所設立的法度律例。","notes":[]},{"n":11,"t":"「所以萬軍之耶和華－以色列的神如此說：看哪，我必向你們變臉降災，剪除猶大眾人。","notes":[]},{"n":12,"t":"我必使那定意進入埃及地、在那裏寄居的，就是倖存的猶大人，盡都滅絕。他們必在埃及地仆倒，因刀劍饑荒滅絕，從最小的到最大的都必遭刀劍饑荒而死，甚至受辱罵、驚駭、詛咒、羞辱。","notes":[]},{"n":13,"t":"我怎樣用刀劍、饑荒、瘟疫懲罰耶路撒冷，也必照樣懲罰那些住在埃及地的猶大人。","notes":[]},{"n":14,"t":"那進入埃及地、在那裏寄居的，就是倖存的猶大人，都不得逃脫，也不得歸回猶大地。他們心中很想歸回，居住在那裏；但除了少數逃脫的以外，都不得歸回。」","notes":[]},{"n":15,"t":"那些知道自己妻子向別神燒香的男人，與站在那裏的一大群婦女，就是住埃及地巴特羅所有的百姓，回答耶利米說：","notes":[]},{"n":16,"t":"「論到你奉耶和華的名向我們所說的話，我們必不聽從。","notes":[]},{"n":17,"t":"我們定要照我們口中所說的一切話去做，向天后燒香，獻澆酒祭，按著我們與我們祖先、君王、官長在猶大城鎮和耶路撒冷街市上素常所做的一樣；因為那時我們得以吃飽、享福樂，並未遇見災禍。","notes":[]},{"n":18,"t":"自從我們停止向天后燒香，獻澆酒祭，我們倒缺乏這一切，又因刀劍饑荒滅絕。」","notes":[]},{"n":19,"t":"婦女們說：「我們向天后燒香，獻澆酒祭，做天后像的餅供奉它，向它獻澆酒祭，難道我們的丈夫沒有參與嗎？」","notes":["「婦女們說」是根據古譯本；原文沒有。"]},{"n":20,"t":"耶利米對這樣回答他的男人和婦女說：","notes":[]},{"n":21,"t":"「你們與你們祖先、君王、官長，以及這地的百姓，在猶大城鎮和耶路撒冷街市上所燒的香，耶和華豈不記得，放在他心上嗎？","notes":[]},{"n":22,"t":"耶和華因你們所行的惡、所做可憎的事，不能再容忍，所以使你們的地荒涼，受驚駭詛咒，無人居住，正如今日一樣。","notes":[]},{"n":23,"t":"你們燒香，得罪耶和華，不聽耶和華的話，不遵行他的律法、條例、法度，所以你們遭遇這災禍，正如今日一樣。」","notes":[]},{"n":24,"t":"耶利米又對眾百姓和婦女說：「所有在埃及地的猶大人哪，當聽耶和華的話。","notes":[]},{"n":25,"t":"萬軍之耶和華－以色列的神如此說：你們和你們的妻子口中說過、手裏做到，說：『我們定要向天后還願，向它燒香，獻澆酒祭。』現在你們儘管堅定所許的願，去還願吧！","notes":[]},{"n":26,"t":"所有住埃及地的猶大人哪，當聽耶和華的話。耶和華說：看哪，我指著我至大的名起誓，在埃及全地，我的名必不再被猶大任何人的口呼喊：『我指著主－永生的耶和華起誓。』","notes":[]},{"n":27,"t":"看哪，我看守他們，為要降禍不降福；在埃及地的猶大人必因刀劍、饑荒而滅亡，直到滅絕。","notes":[]},{"n":28,"t":"從埃及地能脫離刀劍、歸回猶大地的人數很少。那進入埃及地、在那裏寄居的，就是倖存的猶大人，必知道是誰的話站得住，是我的話呢，還是他們的話。","notes":[]},{"n":29,"t":"我在這地方懲罰你們，必有預兆，使你們知道我降禍給你們的話必站得住。這是耶和華說的。","notes":[]},{"n":30,"t":"耶和華如此說：看哪，我必將埃及王合弗拉法老交在他仇敵和尋索其命的人手中，像我將猶大王西底家交在他仇敵和尋索其命的巴比倫王尼布甲尼撒手中一樣。」","notes":[]}]},"45":{"heading":"耶和華給巴錄的許諾","verses":[{"n":1,"t":"約西亞的兒子猶大王約雅敬第四年，尼利亞的兒子巴錄把耶利米先知口中所說的話寫在書上；耶利米對巴錄說：","notes":[]},{"n":2,"t":"「巴錄啊，耶和華－以色列的神說：","notes":[]},{"n":3,"t":"你曾說：『哀哉！耶和華使我愁上加愁，我因呻吟而困乏，不得安歇。』","notes":[]},{"n":4,"t":"你要這樣告訴他，耶和華如此說：看哪，我所建立的，我必拆毀；我所栽植的，我必拔出；在全地我都如此行。","notes":[]},{"n":5,"t":"你為自己圖謀大事嗎？不要圖謀！看哪，我必使災禍臨到凡有血肉之軀的。但你無論往哪裏去，我要保全你的性命。這是耶和華說的。」","notes":[]}]},"46":{"heading":"埃及在迦基米施受挫","verses":[{"n":1,"t":"耶和華論列國的話臨到耶利米先知。","notes":[]},{"n":2,"t":"論到埃及，關於埃及王尼哥法老的軍隊，這軍隊安營在幼發拉底河邊的迦基米施，是巴比倫王尼布甲尼撒在約西亞的兒子猶大王約雅敬第四年所打敗的。","notes":[]},{"n":3,"t":"你們要預備大小盾牌，往前上陣，","notes":[]},{"n":4,"t":"套上車，騎上馬！頂盔站立，磨槍披甲！","notes":[]},{"n":5,"t":"我為何看見他們驚惶，轉身退後呢？他們的勇士打敗仗，急忙逃跑，並不回頭；四圍都有驚嚇！這是耶和華說的。","notes":[]},{"n":6,"t":"不要容快跑的逃避，也不要容勇士逃脫；在北方幼發拉底河邊，他們絆跌仆倒。","notes":["「不要...逃脫」或譯「快跑的不能逃避，勇士也不能逃脫」。"]},{"n":7,"t":"這是誰，像尼羅河漲溢，如江河的水翻騰呢？","notes":[]},{"n":8,"t":"埃及像尼羅河漲溢，如江河的水翻騰。它說：「我要漲溢遮蓋全地；我要毀滅城鎮和其中的居民。","notes":[]},{"n":9,"t":"馬匹啊，上去吧！戰車啊，要疾行！手拿盾牌的古實和弗的勇士，擅長拉弓的路德人，前進吧！」","notes":["「弗」是利比亞的一部分。"]},{"n":10,"t":"那日是萬軍之主耶和華報仇的日子，要向敵人報仇。刀劍必吞吃飽足，飲血滿足；因為在北方幼發拉底河邊，有祭物獻給萬軍之主耶和華。","notes":[]},{"n":11,"t":"少女埃及啊，要上基列去取乳香；你雖服用許多藥，還是徒然，不得治好。","notes":["「少女埃及」：原文直譯「少女埃及女子」。"]},{"n":12,"t":"列國聽見你的羞辱，遍地滿了你的哀聲；勇士與勇士彼此相撞，二人一起跌倒。","notes":[]},{"n":13,"t":"以下是耶和華對耶利米先知說的話，論到巴比倫王尼布甲尼撒要來攻擊埃及地。","notes":[],"heads":["尼布甲尼撒來犯"]},{"n":14,"t":"你們要在埃及傳揚，在密奪報告，在挪弗、答比匿宣告說：「要擺好陣勢，預備作戰，因為刀劍在你四圍施行吞滅。」","notes":[]},{"n":15,"t":"你的壯士為何被掃除呢？他們站立不住，因為耶和華驅逐他們；","notes":["「你的...站立不住，」七十士譯本是「阿庇斯（挪弗的牛神）為何逃走呢？你精選的牛為何站立不住呢？」"]},{"n":16,"t":"他使多人絆跌，彼此撞倒。他們說：「起來，讓我們回到自己的同胞、回到自己的出生地去，好躲避欺壓的刀劍。」","notes":[]},{"n":17,"t":"他們在那裏稱埃及王法老為「錯失良機的誇大者」。","notes":["「他們...法老」：七十士譯本是「你們要稱埃及王法老尼哥的名字」。"]},{"n":18,"t":"名為萬軍之耶和華的君王說：我指著我的永生起誓：「尼布甲尼撒來的時候，必像眾山之中的他泊，像海邊的迦密。」","notes":["「尼布甲尼撒」：原文是「他」。"]},{"n":19,"t":"住在埃及的啊，要預備被擄時需用的物品；因為挪弗必成為廢墟，被燒燬，無人居住。","notes":["「埃及」：原文直譯「埃及女子」；本章24節同。"]},{"n":20,"t":"埃及是肥美的母牛犢；但來自北方的牛虻來到了！來到了！","notes":["「來到了！來到了！」有古卷和七十士譯本是「臨到它。」"]},{"n":21,"t":"它的傭兵好像圈裏的肥牛犢，他們轉身退後，一齊逃跑，站立不住；因為他們遭難的日子、受罰的時刻已經來臨。","notes":[]},{"n":22,"t":"它的聲音好像蛇在滑行。敵人要成隊而來，如砍伐樹木的人，手拿斧頭攻擊它。","notes":[]},{"n":23,"t":"雖然它的樹林不易穿過，敵人卻要砍伐，因敵人比蝗蟲還多，不可勝數。這是耶和華說的。","notes":[]},{"n":24,"t":"埃及必然蒙羞，被交在北方人的手中。","notes":[]},{"n":25,"t":"萬軍之耶和華－以色列的神說：「看哪，我要懲罰挪的亞捫和法老、埃及和它的神明，以及君王，也要懲罰法老和倚靠他的人。","notes":["「挪」就是埃及的底比斯。","「亞捫」是埃及的主要神明。"]},{"n":26,"t":"我要將他們交給尋索其命之人的手和巴比倫王尼布甲尼撒與他臣僕的手。但埃及日後必再有人居住，與從前一樣。這是耶和華說的。」","notes":[]},{"n":27,"t":"我的僕人雅各啊，不要懼怕！以色列啊，不要驚惶！因我要從遠方拯救你，從被擄之地拯救你的後裔。雅各必回來，得享平靜安逸，無人令他害怕。","notes":[],"heads":["耶和華要救他的子民"]},{"n":28,"t":"我的僕人雅各啊，不要懼怕！因我與你同在。我要將那些國滅絕淨盡，就是我趕你去的那些國；卻不將你滅絕淨盡，倒要從寬懲治你，但絕不能不罰你。這是耶和華說的。","notes":[]}]},"47":{"heading":"有關非利士的話","verses":[{"n":1,"t":"在法老攻擊迦薩之前，耶和華論非利士人的話臨到耶利米先知。","notes":[]},{"n":2,"t":"耶和華如此說：看哪，有水從北方漲起，成為漲溢的河，要淹沒全地和其中所充滿的，淹沒城和城裏的居民。人必呼喊，境內的居民都必哀號。","notes":[]},{"n":3,"t":"一聽見敵人壯馬蹄踏的響聲、戰車隆隆、車輪轟轟，為父的手就發軟，不能回頭看顧兒女。","notes":[]},{"n":4,"t":"因為日子將到，耶和華必毀滅所有非利士人，剪除推羅、西頓僅存的幫助者；他要毀滅非利士人、迦斐託海島剩餘的人。","notes":[]},{"n":5,"t":"迦薩成了光禿，亞實基倫歸於無有。平原中所剩的啊，你割劃自己，要到幾時呢？","notes":["「平原」：七十士譯本是「亞衲族」。"]},{"n":6,"t":"耶和華的刀劍哪，你要到幾時才止息呢？要入鞘，安靜不動。","notes":[]},{"n":7,"t":"耶和華吩咐它攻擊亞實基倫和海邊之地，既已派定它，你怎能靜止不動呢？","notes":["「你」：七十士譯本是「它」。"]}]},"48":{"heading":"有關摩押的話","verses":[{"n":1,"t":"論摩押。萬軍之耶和華－以色列的神如此說：禍哉，尼波！它要變為廢墟。基列亭蒙羞被攻取，米斯迦蒙羞被毀壞，","notes":["「米斯迦」或譯「碉堡」。"]},{"n":2,"t":"摩押不再被稱讚。有人在希實本設計謀害它：「來吧！我們將它剪除，使它不再成國。」瑪得緬哪，你也必靜默無聲；刀劍必追趕你。","notes":[]},{"n":3,"t":"從何羅念有哀號聲：「荒涼！大毀滅！」","notes":[]},{"n":4,"t":"「摩押毀滅了！」它的孩童哀號，使人聽見。","notes":[]},{"n":5,"t":"人上魯希坡隨走隨哭，因為在何羅念的下坡聽見毀滅的哀聲。","notes":[]},{"n":6,"t":"你們要奔逃，自救己命，使你們的性命如曠野裏的矮樹。","notes":["「矮樹」：七十士譯本是「野驢」。"]},{"n":7,"t":"你因倚靠自己所做的和自己的財寶，必被攻取。基抹和屬它的祭司、官長也要一同被擄去。","notes":["「自己所做的」：七十士譯本是「自己的堡壘」。","「基抹」為摩押的神明；下同。"]},{"n":8,"t":"那行毀滅的要來到各城，並無一城倖免。山谷必敗落，平原必毀壞，正如耶和華所說的。","notes":[]},{"n":9,"t":"你們要將翅膀給摩押，使它可以飛去。它的城鎮必荒涼，無人居住。","notes":["「你們要...飛去」：原文另譯「你們要為摩押灑鹽，因為它一定會滅亡」（參士9．45）七十士譯本是「要給摩押豎立墓碑，它不久將被毀滅」。"]},{"n":10,"t":"懶惰不肯為耶和華做事的，必受詛咒；禁止刀劍不見血的，必受詛咒。","notes":[]},{"n":11,"t":"摩押自幼年以來常享安逸，如沉澱未被攪動的酒，沒有從這器皿倒在那器皿，也未曾被擄掠過。因此，它的原味尚存，香氣未變。","notes":["原文沒有「酒」。"],"heads":["摩押的城鎮被毀滅"]},{"n":12,"t":"看哪，日子將到，我必差倒酒的到它那裏去，將它倒出來；他們要倒空器皿，打碎罈子。這是耶和華說的。","notes":[]},{"n":13,"t":"摩押必因基抹羞愧，像以色列家因倚靠伯特利羞愧一樣。","notes":[]},{"n":14,"t":"你們怎麼說：「我們是勇士，是會打仗的壯士」呢？","notes":[]},{"n":15,"t":"摩押變為廢墟，敵人上去佔它的城鎮。它精良的壯丁都下去遭殺戮；這是名為萬軍之耶和華的君王說的。","notes":[]},{"n":16,"t":"摩押的災殃臨近，災難速速來到。","notes":[]},{"n":17,"t":"凡在它四圍的和認識它名的，都要為它悲傷，說：那結實的杖和美好的棍，竟然折斷了！","notes":[]},{"n":18,"t":"底本的居民哪，要從你榮耀的座位上下來，坐著忍受乾渴；因毀滅摩押的人上來攻擊你，毀壞了你的堡壘。","notes":["「底本」：原文直譯「底本女子」。"]},{"n":19,"t":"住亞羅珥的啊，要站在道路的邊上觀望，問逃跑的男人和逃脫的女人說：「發生了甚麼事呢」？","notes":[]},{"n":20,"t":"摩押因毀壞蒙羞；你們要哀號呼喊，要在亞嫩報告：「摩押已成廢墟！」","notes":[]},{"n":21,"t":"審判臨到平原之地的何倫、雅雜、米法押、","notes":[]},{"n":22,"t":"底本、尼波、伯‧低比拉太音、","notes":[]},{"n":23,"t":"基列亭、伯‧迦末、伯‧米恩、","notes":[]},{"n":24,"t":"加略、波斯拉和摩押地遠近所有的城鎮。","notes":[]},{"n":25,"t":"摩押的角砍斷了，膀臂折斷了。這是耶和華說的。","notes":[]},{"n":26,"t":"你們要使摩押沉醉，因它向耶和華誇大。它要在自己所吐之物中打滾，又要被人嗤笑。","notes":[],"heads":["摩押受凌辱"]},{"n":27,"t":"以色列不是你的笑柄嗎？它難道是在賊中被逮到，使你每逢提到它就搖頭的嗎？","notes":[]},{"n":28,"t":"摩押的居民哪，要離開城鎮，住在山崖裏，像鴿子在峽谷口上搭窩。","notes":[]},{"n":29,"t":"我們聽聞摩押人的驕傲，極其驕傲；他們自高、自傲、自我狂妄、居心自大。","notes":[]},{"n":30,"t":"我知道他們的憤怒是虛空的，他們誇大的話一無所成。這是耶和華說的。","notes":[]},{"n":31,"t":"因此，我要為摩押哀號，為摩押全地呼喊；人必為吉珥‧哈列設人嘆息。","notes":[]},{"n":32,"t":"西比瑪的葡萄樹啊，我為你哀哭，甚於雅謝人的哀哭。你的枝子蔓延過海，直伸到雅謝海。那行毀滅的已經臨到你夏天的果子和葡萄。","notes":[]},{"n":33,"t":"肥田和摩押地的歡喜快樂都被奪去，我使酒池不再流出酒來，無人踹酒歡呼；呼喊的聲音不再是歡呼。","notes":[]},{"n":34,"t":"有哀聲從希實本達到以利亞利，他們發的哀聲達到雅雜；從瑣珥達到何羅念，達到伊基拉‧施利施亞，因為寧林的水必然乾涸。","notes":[]},{"n":35,"t":"我必在摩押地使那在丘壇獻祭的，和那向他的神明燒香的都滅絕了。這是耶和華說的。","notes":[]},{"n":36,"t":"因此，我的心為摩押哀鳴如簫，我的心為吉珥‧哈列設人哀哭；摩押人所得的財物都毀滅了。","notes":[]},{"n":37,"t":"各人頭上光禿，鬍鬚剪短，手有劃傷，腰束麻布。","notes":[]},{"n":38,"t":"在摩押的各房頂上和街市上到處有人哀哭，因我打碎摩押，好像打碎無人喜愛的器皿。這是耶和華說的。","notes":[]},{"n":39,"t":"打得粉碎了！他們要哀號了！摩押要羞愧轉背了！這樣，摩押必受四圍的人嗤笑驚駭。","notes":[]},{"n":40,"t":"耶和華如此說：看哪，仇敵必如鷹展翅快飛，攻擊摩押。","notes":[],"heads":["摩押無路可逃"]},{"n":41,"t":"加略被攻取，堡壘也被佔據。到那日，摩押的勇士心中疼痛如臨產的婦人。","notes":[]},{"n":42,"t":"摩押必被毀滅，不再成國，因它向耶和華誇大。","notes":[]},{"n":43,"t":"摩押的居民哪，驚嚇、陷阱、羅網都臨近你。這是耶和華說的。","notes":[]},{"n":44,"t":"躲過驚嚇的必墜入陷阱，逃離陷阱的又被羅網纏住，因我必使懲罰之年臨到摩押。這是耶和華說的。","notes":[]},{"n":45,"t":"逃難的人站在希實本的蔭下，筋疲力盡，因為有火從希實本發出，有火焰出自西宏，燒盡摩押的鬢角和鬧鬨人的頭頂。","notes":["「西宏」：有古卷是「西宏的家」。"]},{"n":46,"t":"摩押啊，你有禍了！屬基抹的百姓滅亡了！因你的兒子都被擄去，你的女兒也被擄去。","notes":[]},{"n":47,"t":"到末後，我卻要使摩押被擄的人歸回。摩押受審判的話到此為止。這是耶和華說的。","notes":[]}]},"49":{"heading":"有關亞捫的話","verses":[{"n":1,"t":"論亞捫人。耶和華如此說：以色列沒有兒子嗎？沒有後嗣嗎？米勒公為何承受迦得為業呢？屬它的百姓為何住其中的城鎮呢？","notes":["「米勒公」是根據七十士譯本和其他古譯本，亞捫人神明的名字，又名「摩洛」；原文是「他們的王」，音譯「瑪勒堪」；下同。"]},{"n":2,"t":"看哪，日子將到，我必使人聽見打仗的喊聲，攻擊亞捫人所住的拉巴的喊聲。拉巴要成為廢墟，屬它的鄉鎮要被火焚燒。這是耶和華說的。先前承受以色列為業的，此時以色列倒要承受他們為業。這是耶和華說的。","notes":["「鄉鎮」：原文直譯「女子們」；下同。"]},{"n":3,"t":"希實本哪，要哀號，因為愛地已成荒地。拉巴的鄉鎮哪，要呼喊，以麻布束腰；要哭號，在籬笆中往來奔跑；因米勒公和它的祭司、官長要一同被擄去。","notes":[]},{"n":4,"t":"背道的民哪，你為何因有山谷，因有水流的山谷誇耀呢？為何倚靠自己的財寶，說：「誰能來到我們這裏呢？」","notes":["「民」：原文直譯「女子」。"]},{"n":5,"t":"萬軍之主耶和華說：看哪，我要使驚嚇從四圍的鄰邦臨到你們；你們必被趕出，各人一直往前，無人收容難民。","notes":[]},{"n":6,"t":"但後來，我卻要使被擄的亞捫人歸回。這是耶和華說的。","notes":[]},{"n":7,"t":"論以東。萬軍之耶和華如此說：提幔不再有智慧了嗎？聰明人的謀略都用盡了嗎？他們的智慧盡歸無有了嗎？","notes":[],"heads":["有關以東的話"]},{"n":8,"t":"底但的居民哪，要轉身逃跑，住在深密處；因為我懲罰以掃的時候，必使災殃臨到他。","notes":[]},{"n":9,"t":"摘葡萄的若來到你那裏，豈不留下幾串嗎？賊若夜間來到，豈不是只毀壞他們要毀壞的嗎？","notes":[]},{"n":10,"t":"我卻使以掃赤裸，暴露他的藏身處；他不能隱藏自己。他的後裔、弟兄、鄰舍全都滅絕，他也歸於無有。","notes":[]},{"n":11,"t":"你撇下孤兒，我必保全他們的性命；你的寡婦可以倚靠我。","notes":[]},{"n":12,"t":"耶和華如此說：「看哪，既然原不該喝那杯的一定要喝，你能免去懲罰嗎？必不能免，一定要喝！","notes":[]},{"n":13,"t":"我指著自己起誓，波斯拉必令人驚駭、受羞辱、被詛咒，並且全然荒廢。它所有的城鎮都要永遠成為廢墟。這是耶和華說的。」","notes":[]},{"n":14,"t":"我從耶和華那裏聽見消息，有使者被差往列國去，說：「你們要聚集前來攻擊以東，要起來爭戰。」","notes":[]},{"n":15,"t":"看哪，我使你在列國中為最小，在世人中被藐視。","notes":[]},{"n":16,"t":"住在山穴中盤據山頂的啊，你被自己的聲勢與心中的狂傲所蒙蔽；你雖如大鷹高高搭窩，我卻要從那裏拉你下來。這是耶和華說的。","notes":[]},{"n":17,"t":"以東必令人驚駭；凡經過的人都驚駭，又因它一切的災禍嗤笑。","notes":[]},{"n":18,"t":"耶和華說：它要像所多瑪、蛾摩拉和鄰近的城鎮一樣傾覆，必無人住在那裏，也無人在其中寄居。","notes":[]},{"n":19,"t":"看哪，就像獅子從約旦河邊的叢林上來，攻擊堅固的居所，我要在轉眼之間使以東人逃跑，離開這地。我揀選誰，就派誰治理這地。誰能像我呢？誰能召我出庭呢？有哪一個牧人能在我面前站得住呢？","notes":["「誰能召我出庭呢？」原文另譯「誰能與我相比呢？」"]},{"n":20,"t":"你們要聽耶和華攻擊以東所定的計劃和他攻擊提幔居民所定的旨意。他們羊群當中微弱的定要被拖走，他們的草場定要變為荒涼。","notes":[]},{"n":21,"t":"因他們仆倒的聲音，地就震動，哀號的聲音傳到紅海那裏。","notes":["「紅海」是根據七十士譯本；原文是「蘆葦海」。"]},{"n":22,"t":"看哪，仇敵必如大鷹飛起，展開翅膀攻擊波斯拉。到那日，以東的勇士心中疼痛如臨產的婦人。","notes":[]},{"n":23,"t":"論大馬士革。哈馬和亞珥拔蒙羞，因為他們聽見兇惡的消息就融化；焦慮像海浪洶湧，不得平靜。","notes":[],"heads":["有關大馬士革的話"]},{"n":24,"t":"大馬士革發軟，轉身逃跑；戰兢將它捉住，痛苦憂愁將它抓住，如臨產的婦人一樣。","notes":[]},{"n":25,"t":"我所喜樂受稱讚的城，怎能被撇棄呢？","notes":["「怎能被撇棄」是根據一些古譯本；原文是「怎能不被撇棄」。"]},{"n":26,"t":"它的壯丁必仆倒在街上，當那日，戰士全都靜默無聲。這是萬軍之耶和華說的。","notes":[]},{"n":27,"t":"我必用火點燃大馬士革的城牆，燒滅便‧哈達的宮殿。","notes":[]},{"n":28,"t":"論巴比倫王尼布甲尼撒所攻打的基達和夏瑣諸國。耶和華如此說：迦勒底人哪，起來上基達去，毀滅東方人。","notes":[],"heads":["有關基達和夏瑣的話"]},{"n":29,"t":"人要奪去他們的帳棚和羊群，人要帶走他們的幔子、一切器皿，和駱駝，佔為己有。人向他們喊著說：四圍都有驚嚇。","notes":[]},{"n":30,"t":"夏瑣的居民哪，要逃奔遠方，住在深密處；因為巴比倫王尼布甲尼撒設計謀害你們，起意攻擊你們。這是耶和華說的。","notes":[]},{"n":31,"t":"迦勒底人哪，起來！上到安逸無慮的國民那裏去，他們是無門無閂、單獨居住的。這是耶和華說的。","notes":[]},{"n":32,"t":"他們的駱駝必成為掠物，他們眾多的牲畜必成為擄物。我要將剃鬢髮的人分散四方，使災殃從四圍臨到他們。這是耶和華說的。","notes":["「方」：原文是「風」；下同。"]},{"n":33,"t":"夏瑣必成為野狗的住處，永遠荒廢；無人住在那裏，也無人在其中寄居。","notes":[]},{"n":34,"t":"猶大王西底家登基的時候，耶和華論以攔的話臨到耶利米先知，說：","notes":[],"heads":["有關以攔的話"]},{"n":35,"t":"「萬軍之耶和華如此說：看哪，我必折斷以攔人的弓，那是他們戰鬥的主力。","notes":[]},{"n":36,"t":"我要使風從天的四方颳來，臨到以攔，將他們分散四方。以攔被趕散的人沒有一國不到的。","notes":[]},{"n":37,"t":"我必使以攔人在仇敵和尋索其命的人面前驚惶；我也必使災禍，就是我的烈怒臨到他們，又必使刀劍追殺他們，直到將他們滅盡。這是耶和華說的。","notes":[]},{"n":38,"t":"我要在以攔設立我的寶座，在那裏除滅君王和官長。這是耶和華說的。","notes":[]},{"n":39,"t":"「到末後，我卻要使被擄的以攔人歸回。這是耶和華說的。」","notes":[]}]},"50":{"heading":"巴比倫被佔領","verses":[{"n":1,"t":"以下是耶和華藉耶利米先知論巴比倫和迦勒底人之地所說的話。","notes":[]},{"n":2,"t":"你們要在萬國中傳揚，宣告，豎立大旗；要宣告，不可隱瞞，說：「巴比倫被攻取，彼勒蒙羞，米羅達驚惶。巴比倫的神像都蒙羞，它的偶像都驚惶。」","notes":["「彼勒」是巴比倫的主要神明。","「米羅達」是巴比倫的主要神明。"]},{"n":3,"t":"因有一國從北方上來攻擊它，使它的地荒涼，無人居住，連人帶牲畜都逃走了。","notes":[]},{"n":4,"t":"在那日、在那時，以色列人要和猶大人同來，隨走隨哭，尋求耶和華－他們的神。這是耶和華說的。","notes":[],"heads":["以色列人回鄉"]},{"n":5,"t":"他們要問到錫安之路，又面向那裏，說：「來吧，他們要在永不被遺忘的約中與耶和華聯合。」","notes":["「他們要」：有古譯本是「讓我們」。"]},{"n":6,"t":"我的百姓成了失喪的羊，牧人使他們走迷了路，轉入叢山之間。他們從大山走到小山，竟忘了自己安歇之處。","notes":[]},{"n":7,"t":"凡遇見他們的，就把他們吞滅。敵人說：「我們不算有罪；因他們得罪了那可作真正居所的耶和華，就是他們祖先所仰望的耶和華。」","notes":["「真正」或譯「公義」。"]},{"n":8,"t":"「你們要逃離巴比倫，要離開迦勒底人之地，像走在羊群前面的公山羊。","notes":[]},{"n":9,"t":"看哪，因我必激起大國聯盟，帶領他們從北方來攻擊巴比倫，他們要擺陣攻擊它，它必在那裏被攻取。他們的箭好像善射勇士的箭，絕不徒然返回。","notes":["「善射」是根據一些古卷；原文是「使人喪子」。"]},{"n":10,"t":"迦勒底要成為掠物，凡擄掠它的都必心滿意足。這是耶和華說的。」","notes":[]},{"n":11,"t":"搶奪我產業的啊，你們因歡喜快樂，像踹穀嬉戲的母牛犢，又像發嘶聲的壯馬。","notes":["「踹穀」：七十士譯本是「在草地上」。"],"heads":["巴比倫陷落"]},{"n":12,"t":"你們的母親極其抱愧，生你們的必然蒙羞。看哪，她要列在諸國之末，成為曠野、旱地、沙漠；","notes":[]},{"n":13,"t":"因耶和華的憤怒，巴比倫必無人居住，全然荒涼，凡經過的都要受驚駭，又因它所遭的災殃嗤笑。","notes":[]},{"n":14,"t":"所有拉弓的啊，要在巴比倫的四圍擺陣，射箭攻擊它，不用愛惜箭枝，因為它得罪了耶和華。","notes":[]},{"n":15,"t":"要在它四圍吶喊：「它已經投降，堡壘坍塌了，城牆拆毀了！」這是耶和華所報的仇。你們要向它報仇；它怎樣待人，你們也要怎樣待它。","notes":[]},{"n":16,"t":"你們要將巴比倫撒種的和收割時拿鐮刀的全都剪除。他們各人因躲避欺壓的刀劍，必歸回本族，逃到本土。","notes":[]},{"n":17,"t":"以色列是打散的羊，被獅子趕散。首先是亞述王將他吞滅，末後是巴比倫王尼布甲尼撒折斷他的骨頭。","notes":[],"heads":["以色列人回鄉"]},{"n":18,"t":"所以萬軍之耶和華－以色列的神如此說：「看哪，我必懲罰巴比倫王和他的地，像我從前懲罰亞述王一樣。","notes":[]},{"n":19,"t":"我必領以色列回他自己的草場，他要在迦密和巴珊吃草，又在以法蓮山上和基列境內得以飽足。","notes":[]},{"n":20,"t":"在那日、在那時，你尋找以色列的罪孽，一無所有；尋找猶大的罪惡，也無所得；因為我所留下的人，我必赦免。這是耶和華說的。」","notes":[]},{"n":21,"t":"你要上去攻擊米拉大翁之地，又攻擊比割的居民。將他們追殺滅盡，照我所吩咐你的一切去做。這是耶和華說的。","notes":[],"heads":["神審判巴比倫"]},{"n":22,"t":"境內有打仗和大毀滅的響聲。","notes":[]},{"n":23,"t":"全地的大錘竟然砍斷破壞！巴比倫在列國中竟然荒涼！","notes":[]},{"n":24,"t":"巴比倫哪，我為你設下羅網，你被纏住，竟不自覺。你被尋著，也被捉住，因為你對抗耶和華。","notes":[]},{"n":25,"t":"耶和華已經打開軍械庫，拿出他惱恨的兵器；這是萬軍之主耶和華在迦勒底人之地要做的事。","notes":[]},{"n":26,"t":"你們要從極遠的邊界前來攻擊它，要開它的倉廩，將它堆起如高堆，毀滅淨盡，絲毫不留。","notes":["「你們要...它」：原文另譯「它收割的時候到了」。"]},{"n":27,"t":"要殺它一切的牛犢，使牠們下去遭殺戮。他們有禍了，因為他們的日子，就是他們受罰的時刻已經來到。","notes":[]},{"n":28,"t":"從巴比倫之地逃出來的難民，在錫安揚聲宣告耶和華－我們的神要報仇，為他的聖殿報仇。","notes":[]},{"n":29,"t":"你們要招集一切弓箭手來攻擊巴比倫，在巴比倫四圍安營，不容一人逃脫。要照著它所做的報應它；它怎樣待人，你們也要怎樣待它，因為它向耶和華－以色列的聖者狂傲。","notes":[]},{"n":30,"t":"所以它的壯丁必仆倒在街上。當那日，它的士兵全都必靜默無聲。這是耶和華說的。","notes":[]},{"n":31,"t":"「看哪，你這狂傲的啊，我與你為敵，因為你的日子，我懲罰你的時刻已經來到。這是萬軍之主耶和華說的。","notes":[]},{"n":32,"t":"狂傲的必絆跌仆倒，無人扶起。我必用火點燃他的城鎮，將他四圍所有的盡行燒滅。」","notes":[]},{"n":33,"t":"萬軍之耶和華如此說：「以色列人和猶大人一同受欺壓；凡擄掠他們的都緊緊抓住他們，不肯釋放。","notes":[]},{"n":34,"t":"他們的救贖主大有能力，萬軍之耶和華是他的名。他必定為他們伸冤，使全地得享平靜；他卻要攪擾巴比倫的居民。」","notes":[]},{"n":35,"t":"有刀劍臨到迦勒底人和巴比倫的居民，臨到它的領袖與智慧人。這是耶和華說的。","notes":[]},{"n":36,"t":"有刀劍臨到矜誇的人，他們就變為愚昧；有刀劍臨到它的勇士，他們就驚惶。","notes":[]},{"n":37,"t":"有刀劍臨到它的馬匹、戰車，和其中混居的各族，他們變成與婦女一樣；有刀劍臨到它的寶物，寶物就被搶奪。","notes":[]},{"n":38,"t":"有乾旱臨到它的眾水，它們就必乾涸；因為這是雕刻偶像之地，人因偶像顛狂。","notes":["「乾旱」：原文另譯「刀劍」。","「人因偶像顛狂」：有古卷是「人以偶像為榮」。"]},{"n":39,"t":"所以野獸和土狼必住在那裏，鴕鳥也住在其中，永遠無人居住，世世代代無人定居。","notes":[]},{"n":40,"t":"巴比倫要像神所傾覆的所多瑪、蛾摩拉和鄰近的城鎮一樣，必無人住在那裏，也無人在其中寄居。這是耶和華說的。","notes":[]},{"n":41,"t":"看哪，有一民族從北方而來，有一大國和許多君王被激起，從地極來到。","notes":[]},{"n":42,"t":"他們拿弓和槍，性情殘忍，毫不留情；他們的聲音像海浪澎湃。巴比倫啊，他們騎著馬，如上戰場的人擺列隊伍，要攻擊你。","notes":["「 巴比倫」：原文直譯「巴比倫女子」。"]},{"n":43,"t":"巴比倫王聽見他們的風聲，手就發軟，痛苦將他抓住，彷彿臨產的婦人疼痛一般。","notes":[]},{"n":44,"t":"「看哪，就像獅子從約旦河邊的叢林上來，攻擊堅固的居所，我要在轉眼之間使迦勒底人逃跑，離開這地。我揀選誰，就派誰治理這地。誰能像我呢？誰能召我出庭呢？有哪一個牧人能在我面前站得住呢？","notes":[]},{"n":45,"t":"你們要聽耶和華攻擊巴比倫所定的計劃和他攻擊迦勒底人之地所定的旨意。他們羊群當中微弱的定要被拖走，他們的草場定要變為荒涼。","notes":[]},{"n":46,"t":"因巴比倫被攻下的聲音，地就震動，人在列國都聽見呼喊的聲音。」","notes":[]}]},"51":{"heading":"再審判巴比倫","verses":[{"n":1,"t":"耶和華如此說：看哪，我必颳起毀滅的風，攻擊巴比倫和住在立加米的人。","notes":[]},{"n":2,"t":"我要差陌生人來到巴比倫，他們要簸揚它，使它的地空無一物。在它遭禍的日子，他們要四圍攻擊它。","notes":["「陌生人」：有古卷和古譯本是「簸揚的人」。"]},{"n":3,"t":"不要叫拉弓的拉弓，不要叫他佩戴盔甲；不要憐惜巴比倫的壯丁，要滅盡它的全軍。","notes":["「不要叫拉弓...盔甲」是根據原文的另一讀法；原文和七十士譯本是「要叫拉弓的拉弓，要叫他佩戴盔甲」。"]},{"n":4,"t":"他們必在迦勒底人之地被殺仆倒，在巴比倫的街市上被刺透。","notes":[]},{"n":5,"t":"以色列和猶大境內雖然充滿違背以色列聖者的罪，卻沒有被他的神－萬軍之耶和華所遺棄。","notes":[]},{"n":6,"t":"你們要奔逃，離開巴比倫，各救自己的性命！不要陷在它的罪孽中一同滅亡，因為這是耶和華報仇的時刻，他必向巴比倫施行報應。","notes":[]},{"n":7,"t":"巴比倫素來是耶和華手中的金杯，使全地沉醉，列國喝了它的酒就顛狂。","notes":[]},{"n":8,"t":"巴比倫忽然傾覆毀壞；要為它哀號，拿乳香來止它的疼痛，或者可以治好。","notes":[]},{"n":9,"t":"我們想醫治巴比倫，它卻未獲痊癒。離開它吧！讓我們各人歸回本國，因為它受的審判通於上天，達到穹蒼。","notes":[]},{"n":10,"t":"耶和華已經彰顯出我們的義。來吧！我們要在錫安傳揚耶和華－我們神的作為。","notes":[]},{"n":11,"t":"你們要磨尖箭頭，抓住盾牌。論到巴比倫，耶和華定意要毀滅它，所以激起瑪代君王的心；這是耶和華報仇，為他的聖殿報仇。","notes":[]},{"n":12,"t":"你們要豎立大旗，攻擊巴比倫的城牆；要堅固瞭望臺，派定守望的設下埋伏；因為耶和華指著巴比倫居民所說的，他不但這樣定意，也已成就。","notes":[]},{"n":13,"t":"住在眾水之上多有財寶的啊，你的結局已到！你貪婪之量已滿盈！","notes":["「你貪婪之量已滿盈」或譯「你生命的線被剪斷」。"]},{"n":14,"t":"萬軍之耶和華指著自己起誓說：我必使人遍滿各處像蝗蟲一樣，他們必吶喊攻擊你。","notes":[]},{"n":15,"t":"耶和華以能力創造大地，以智慧建立世界，以聰明鋪張穹蒼。","notes":[],"heads":["頌讚神的詩歌"]},{"n":16,"t":"他一出聲，天上就有眾水澎湃；他使雲霧從地極上騰，造電隨雨而閃，從倉庫中吹出風來。","notes":[]},{"n":17,"t":"人人都如同畜牲，毫無知識；銀匠都因偶像羞愧，他所鑄的偶像本為虛假，它們裏面並無氣息。","notes":[]},{"n":18,"t":"它們都是虛無的，是迷惑人的東西，到它們受罰的時刻必被除滅。","notes":[]},{"n":19,"t":"雅各所得的福分不是這樣，因主是那創造萬有的，以色列是他產業的支派，萬軍之耶和華是他的名。","notes":["「主」：原文是「他」。","「以色列」是根據一些古卷；原文是「他」。"]},{"n":20,"t":"你是我爭戰的斧子和打仗的兵器。我要用你打碎列邦，毀滅列國；","notes":[],"heads":["耶和華的大錘"]},{"n":21,"t":"用你打碎馬和騎馬的，打碎戰車和坐在其上的；","notes":[]},{"n":22,"t":"用你打碎男人和女人，打碎老人和少年，打碎壯丁和少女；","notes":[]},{"n":23,"t":"用你打碎牧人和他的羊群，打碎農夫和他的一對耕牛，打碎省長和官員。","notes":[]},{"n":24,"t":"我必在你們眼前報復巴比倫人和迦勒底居民在錫安所做的一切惡事。這是耶和華說的。","notes":[],"heads":["懲罰巴比倫"]},{"n":25,"t":"行毀滅的山，看哪，我與你為敵，你毀滅全地，我必伸手攻擊你，將你從山巖滾下去，使你成為燒燬了的山。這是耶和華說的。","notes":[]},{"n":26,"t":"人必不從你那裏取石頭為房角石，也不取石頭來作根基，因為你必永遠荒廢。這是耶和華說的。","notes":[]},{"n":27,"t":"你們要在境內豎立大旗，在列邦中吹角，使列邦預備攻擊巴比倫。要招集亞拉臘、米尼、亞實基拿各國前來攻擊它，派將軍攻擊它，使馬匹上來如粗暴的蝗蟲；","notes":[]},{"n":28,"t":"使列邦和瑪代君王，省長和官員，他們所管的全地，都預備攻擊它。","notes":[]},{"n":29,"t":"地必震動而移轉；因耶和華向巴比倫旨意已確定，要使巴比倫土地荒涼，無人居住。","notes":[]},{"n":30,"t":"巴比倫的勇士停止爭戰，躲在堡壘之中。他們的力氣耗盡，他們變成與婦女一樣。巴比倫的住處焚燒，門閂都折斷了。","notes":[]},{"n":31,"t":"通報的彼此相遇，送信的彼此相遇，報告巴比倫王，城的四方都被攻下了，","notes":[]},{"n":32,"t":"渡口被佔據了，蘆葦被火焚燒，戰士都驚慌。","notes":[]},{"n":33,"t":"萬軍之耶和華－以色列的神如此說：巴比倫好像踹穀的禾場；再過片時，它收割的時候就到了。","notes":["「巴比倫」：原文直譯「巴比倫女子」。"]},{"n":34,"t":"巴比倫王尼布甲尼撒吞滅我，壓碎我，使我成為空器皿。他如大魚將我吞下，以我的美物充滿他的肚腹，又把我趕出去。","notes":[]},{"n":35,"t":"錫安的居民要說：願我和我骨肉之親所受的殘暴歸給巴比倫。耶路撒冷人要說：願我們所流的血歸給迦勒底的居民。","notes":[]},{"n":36,"t":"所以，耶和華如此說：看哪，我必為你伸冤，為你報仇；我必使巴比倫的海枯竭，使它的泉源乾涸。","notes":[],"heads":["耶和華要幫助以色列"]},{"n":37,"t":"巴比倫必成為廢墟，為野狗的住處，令人驚駭、嗤笑，並且無人居住。","notes":[]},{"n":38,"t":"他們要像少壯獅子一同咆哮，像小獅子吼叫。","notes":[]},{"n":39,"t":"他們食慾一來的時候，我必為他們擺設酒席，使他們沉醉，好叫他們快樂；他們睡了長覺，永不醒起。這是耶和華說的。","notes":[]},{"n":40,"t":"我必使他們像羔羊、像公綿羊和公山羊被牽去宰殺。","notes":[]},{"n":41,"t":"示沙克竟然被攻取！全地所稱讚的被佔據！巴比倫在列國中竟然變為荒涼！","notes":["「示沙克」就是巴比倫。"],"heads":["巴比倫的命運"]},{"n":42,"t":"海水漲起，漫過巴比倫；澎湃的海浪遮蓋了它。","notes":[]},{"n":43,"t":"它的城鎮變廢墟，地變乾旱，成為沙漠，成為無人居住、無人經過之地。","notes":[]},{"n":44,"t":"我要懲罰巴比倫的彼勒，使它吐出所吞之物。列國必不再流歸到它那裏，巴比倫的城牆也必坍塌。","notes":["「彼勒」是巴比倫的主要神明。"]},{"n":45,"t":"我的子民哪，你們要離開巴比倫！各人逃命，躲避耶和華的烈怒。","notes":[]},{"n":46,"t":"不要因境內所聽見的風聲心驚膽怯或懼怕；因為這年有風聲傳來，那年也有風聲傳來；境內有殘暴的事，官長攻擊官長。","notes":[]},{"n":47,"t":"所以，看哪，日子將到，我必懲罰巴比倫雕刻的偶像。它的全地必然抱愧，它被殺的人必仆倒在其上。","notes":[]},{"n":48,"t":"那時，天地和其中所有的，必因巴比倫歡呼，因為行毀滅的要從北方來到它那裏。這是耶和華說的。","notes":[]},{"n":49,"t":"巴比倫要因以色列被殺的人而仆倒，正如全地被刺殺的人是因巴比倫仆倒一般。","notes":[]},{"n":50,"t":"你們躲避刀劍的要快走，不要站住！要在遠方懷念耶和華，心中追想耶路撒冷。","notes":[],"heads":["給在巴比倫以色列人的信息"]},{"n":51,"t":"我們聽見辱罵就蒙羞，滿面慚愧，因為外邦人進入耶和華殿的聖所。","notes":[]},{"n":52,"t":"所以，看哪，日子將到，我必懲罰巴比倫雕刻的偶像，在全境內到處都有刺傷的人在呻吟。這是耶和華說的。","notes":[]},{"n":53,"t":"巴比倫雖升到天上，雖使它堅固的高處更堅固，我也要差毀滅者到它那裏。這是耶和華說的。","notes":[]},{"n":54,"t":"有哀號的聲音從巴比倫出來，有大毀滅從迦勒底人之地而來。","notes":[],"heads":["巴比倫滅亡"]},{"n":55,"t":"耶和華使巴比倫變為廢墟，使其中喧嘩的大聲滅絕。仇敵彷彿眾水，波浪澎湃，發出響聲；","notes":[]},{"n":56,"t":"這是行毀滅的臨到巴比倫。巴比倫的勇士被捉住，他們的弓折斷了；因為耶和華是施行報應的神，他必施行報應。","notes":[]},{"n":57,"t":"我必使巴比倫的領袖、智慧人、省長、官員和勇士都喝醉，使他們永遠沉睡，不再醒起。這是名為萬軍之耶和華的君王說的。","notes":[]},{"n":58,"t":"萬軍之耶和華如此說：巴比倫寬闊的城牆要夷為平地，它高大的城門必被火焚燒。萬民所勞碌的必致虛空，萬族所勞碌的被火焚燒，他們都必困乏。","notes":[]},{"n":59,"t":"猶大王西底家在位第四年，瑪西雅的孫子，尼利亞的兒子西萊雅與王同去巴比倫，西萊雅是王宮的大臣，耶利米先知有話吩咐他。","notes":[],"heads":["耶利米的信息傳到巴比倫"]},{"n":60,"t":"耶利米把一切要臨到巴比倫的災禍，就是論到巴比倫的這一切話，寫在一書卷上。","notes":[]},{"n":61,"t":"耶利米對西萊雅說：「你到了巴比倫，務要宣讀這一切話，","notes":[]},{"n":62,"t":"說：『耶和華啊，你曾論到這地方說：要剪除它，不再有人與牲畜居住此地，必永遠荒涼。』","notes":[]},{"n":63,"t":"你讀完這書卷，就要把一塊石頭拴在其上，投入幼發拉底河中，","notes":[]},{"n":64,"t":"說：『巴比倫因耶和華所要降與它的災禍，必如此沉下去，不再浮起來，百姓也必困乏。』」耶利米的話到此為止。","notes":[]}]},"52":{"heading":"耶路撒冷的陷落","verses":[{"n":1,"t":"西底家登基的時候年二十一歲，在耶路撒冷作王十一年。他母親名叫哈慕她，是立拿人耶利米的女兒。","notes":[]},{"n":2,"t":"西底家行耶和華眼中看為惡的事，像約雅敬所做的一切。","notes":[]},{"n":3,"t":"因此，耶和華向耶路撒冷和猶大發怒，以致把他們從自己面前趕出去。西底家背叛巴比倫王，","notes":[]},{"n":4,"t":"他作王第九年十月初十，巴比倫王尼布甲尼撒率領全軍前來攻擊耶路撒冷，對著城安營，四圍築堡壘攻城，","notes":[]},{"n":5,"t":"城被圍困，直到西底家王十一年。","notes":[]},{"n":6,"t":"四月初九，城裏的饑荒非常嚴重，當地的百姓都沒有糧食。","notes":[]},{"n":7,"t":"城被攻破，士兵全都在夜間從靠近王園兩城牆中間的門逃跑出城；迦勒底人正在四圍攻城，他們就往亞拉巴逃去。","notes":[]},{"n":8,"t":"迦勒底的軍隊追趕西底家王，在耶利哥的平原追上他。他的全軍都離開他潰散了。","notes":[]},{"n":9,"t":"迦勒底人就拿住王，帶他到哈馬地利比拉的巴比倫王那裏；巴比倫王就判他的罪。","notes":[]},{"n":10,"t":"巴比倫王在西底家眼前殺了他的兒女，又在利比拉殺了猶大全體的官長，","notes":[]},{"n":11,"t":"並且挖了西底家的眼睛，用銅鏈鎖著他，帶到巴比倫去，將他囚在監裏，直到他死的日子。","notes":[]},{"n":12,"t":"巴比倫王尼布甲尼撒十九年五月初十，在巴比倫王面前侍立的尼布撒拉旦護衛長進入耶路撒冷，","notes":[],"heads":["聖殿毀滅"]},{"n":13,"t":"他焚燒了耶和華的殿、王宮和耶路撒冷的房屋；用火焚燒所有大戶人家的房屋。","notes":[]},{"n":14,"t":"跟隨護衛長的迦勒底全軍拆毀了耶路撒冷四圍的城牆。","notes":[]},{"n":15,"t":"那時尼布撒拉旦護衛長將百姓中最窮的和城裏所剩下的百姓，並那些投降巴比倫王的人，以及剩下的工匠，都擄去了。","notes":[]},{"n":16,"t":"但尼布撒拉旦護衛長留下一些當地最窮的人，叫他們修整葡萄園，耕種田地。","notes":[]},{"n":17,"t":"耶和華殿的銅柱並殿內的盆座和銅海，迦勒底人都打碎了，把那些銅運到巴比倫去；","notes":[]},{"n":18,"t":"他們又帶走鍋、鏟子、鉗子、盤子、勺子，和供奉用的一切銅器；","notes":[]},{"n":19,"t":"杯、火盆、碗、鍋、燈臺、勺子、酒杯，無論金的銀的，護衛長都帶走了；","notes":[]},{"n":20,"t":"還有所羅門為耶和華殿所造的兩根銅柱、一面銅海，並座下的十二隻銅牛，這些器皿的銅多得無法可秤。","notes":[]},{"n":21,"t":"至於柱子，這一根柱子高十八肘，厚四指，周圍十二肘，中間是空的；","notes":[]},{"n":22,"t":"柱上有銅頂，每個銅頂高五肘；銅頂的周圍有網子和石榴，也都是銅的。另一根柱子與此相同，也有石榴。","notes":[]},{"n":23,"t":"柱子四面有九十六個石榴，在網子周圍，總共有一百個石榴。","notes":[]},{"n":24,"t":"護衛長拿住西萊雅大祭司、西番亞副祭司和門口的三個守衛，","notes":[],"heads":["猶大人被擄到巴比倫"]},{"n":25,"t":"又從城中拿住一個管理士兵的官，並在城裏找到王面前的七個親信，和召募當地百姓之將軍的書記官，以及在城中找到的六十個當地百姓。","notes":["「官」或譯「太監」。"]},{"n":26,"t":"尼布撒拉旦護衛長把這些人帶到利比拉的巴比倫王那裏。","notes":[]},{"n":27,"t":"巴比倫王擊殺他們，在哈馬地的利比拉把他們處死。這樣，猶大人就被擄去離開本地。","notes":[]},{"n":28,"t":"這是尼布甲尼撒所擄百姓的數目：他在位第七年擄去猶大人三千零二十三人；","notes":[]},{"n":29,"t":"尼布甲尼撒十八年從耶路撒冷擄去八百三十二人；","notes":[]},{"n":30,"t":"尼布甲尼撒二十三年，尼布撒拉旦護衛長擄去猶大人七百四十五人；共有四千六百人。","notes":[]},{"n":31,"t":"巴比倫王以未‧米羅達作王的元年，就是猶大王約雅斤被擄後三十七年十二月二十五日，他使猶大王約雅斤抬起頭來，提他出監，","notes":[],"heads":["約雅斤被釋放"]},{"n":32,"t":"對他說好話，使他的位高過與他一同被擄、在巴比倫眾王的位；","notes":[]},{"n":33,"t":"又給他脫了囚服，使他終身常在巴比倫王面前吃飯。","notes":[]},{"n":34,"t":"巴比倫王賜給他日常需用的食物，日日一份，終身都是這樣，直到他死的日子。","notes":[]}]}},"LAM":{"1":{"heading":"耶路撒冷的憂患","verses":[{"n":1,"t":"唉！先前人口稠密的城市，現在為何獨坐！先前在列國中為大的，現在竟如寡婦！先前在各省中為王后的，現在竟成為服苦役的人！","notes":[]},{"n":2,"t":"她夜間痛哭，淚流滿頰，在所有親愛的人中，找不到一個安慰她的。她的朋友都以詭詐待她，成為她的仇敵。","notes":["「她」：本修訂版的「國」和「城」的代名詞都用「它」；本卷用「她」。"]},{"n":3,"t":"猶大被擄，遭遇苦難，多服勞役。她住在列國中，得不著安息；追逼她的在狹窄之地追上她。","notes":[]},{"n":4,"t":"錫安的道路因無人前來過節就哀傷，她的城門荒涼，祭司嘆息，少女悲傷；她自己充滿痛苦。","notes":[]},{"n":5,"t":"她的敵人作主，她的仇敵亨通；耶和華因她過犯多而使她受苦，她的孩童在敵人面前去作俘虜。","notes":[]},{"n":6,"t":"錫安的威榮全都失去。她的領袖如找不著草場的鹿，在追趕的人面前無力行走。","notes":["「錫安」：原文直譯「錫安女子」。"]},{"n":7,"t":"耶路撒冷在困苦窘迫之時，就追想古時一切的榮華。她的百姓落在敵人手中，無人幫助；敵人看見，就因她的毀滅嗤笑。","notes":[]},{"n":8,"t":"耶路撒冷犯了大罪，因此成為不潔淨；素來尊敬她的，見她裸露就都藐視她，她自己也嘆息退後。","notes":[]},{"n":9,"t":"她的污穢是在下襬上；她未曾思想自己的結局，她的敗落令人驚詫，無人安慰她。「耶和華啊，求你看顧我的苦難，因為仇敵強大。」","notes":[]},{"n":10,"t":"敵人伸手奪取她的一切貴重物品；她眼見列國侵入她的聖所，你曾吩咐他們不可進入你的集會。","notes":[]},{"n":11,"t":"她的百姓都嘆息，尋求食物；他們用貴重物品換取糧食，要救性命。「耶和華啊，求你觀看，留意我多麼卑微。」","notes":[]},{"n":12,"t":"所有過路的人哪，願這事不要發生在你們身上。你們要留意觀看，有像這樣臨到我的痛苦沒有？耶和華在他發烈怒的日子使我受苦。","notes":["「願這事...身上」或譯「這事你們不介意嗎」；七十士譯本和其他古譯本沒有本句。"],"heads":["耶路撒冷的哀號"]},{"n":13,"t":"他從高處降火進入我的骨頭，剋制了我；他張開網，絆我的腳，使我退後，又令我終日淒涼發昏。","notes":[]},{"n":14,"t":"他用手綁我罪過的軛，捲繞著加在我頸項上；他使我力量衰敗。主將我交在我不能抵擋的人手中。","notes":[]},{"n":15,"t":"主棄絕我們當中所有的勇士，聚集會眾攻擊我，要壓碎我的年輕人。主踹下少女猶大，在醡酒池中。","notes":["「少女猶大」：原文直譯「少女猶大女子」。"]},{"n":16,"t":"我因這些事哭泣，眼淚汪汪；因為那安慰我、使我重新得力的，離我甚遠。我的兒女孤苦，因為仇敵得勝了。","notes":[]},{"n":17,"t":"錫安伸出雙手，卻無人安慰。論到雅各，耶和華已經出令，使四圍的人作他的仇敵；耶路撒冷在他們中間成為不潔淨。","notes":[]},{"n":18,"t":"耶和華是公義的！我違背了他的命令。萬民哪，請聽，來看我的痛苦；我的少女和壯丁都被擄去。","notes":[]},{"n":19,"t":"我招呼我所親愛的，他們卻欺騙了我。我的祭司和長老尋找食物，要救性命的時候，就在城中斷了氣。","notes":[]},{"n":20,"t":"耶和華啊，求你觀看，因為我在急難中；我的心腸煩亂，我心在我裏面翻轉，因我大大背逆。在外，刀劍使人喪亡；在家，猶如死亡。","notes":[]},{"n":21,"t":"有人聽見我嘆息，卻無人安慰我！我所有的仇敵聽見我的患難就喜樂，因這是你所做的。你使你所宣告的日子來臨，願他們像我一樣。","notes":["「有人...嘆息」：七十士譯本是「聽啊，我在嘆息」。"]},{"n":22,"t":"願他們的惡行都呈現在你面前；你怎樣因我一切的罪過待我，求你也照樣待他們；因我嘆息甚多，心中發昏。","notes":[]}]},"2":{"heading":"耶路撒冷的痛苦","verses":[{"n":1,"t":"唉！主竟發怒，使黑雲遮蔽錫安！他將以色列的華美從天扔在地上，在他發怒的日子並不顧念自己的腳凳。","notes":["「錫安」：原文直譯「錫安女子」；4、8、10、18節同。"]},{"n":2,"t":"主吞滅雅各一切的住處，並不顧惜。他發怒傾覆猶大的堡壘，將它們夷為平地，凌辱這國與她的領袖。","notes":["「猶大」：原文直譯「猶大女子」；下同。"]},{"n":3,"t":"他發烈怒，砍斷以色列一切的角，在仇敵面前收回右手。他將雅各燒燬，如火焰四圍吞滅。","notes":[]},{"n":4,"t":"他張弓好像仇敵，他站立舉起右手，如同敵人殺戮我們眼目所喜愛的。他在錫安的帳棚傾倒憤怒，如火一般。","notes":[]},{"n":5,"t":"主如仇敵吞滅以色列，吞滅它一切的宮殿，毀壞境內的堡壘；在猶大加添悲傷和哭號。","notes":[]},{"n":6,"t":"他摧毀自己的帳幕如摧毀園子，毀壞自己的會幕。耶和華使節慶和安息日在錫安盡被遺忘，又在極其憤怒中厭棄君王與祭司。","notes":[]},{"n":7,"t":"耶和華撇棄自己的祭壇，憎惡自己的聖所，把宮殿的牆交給仇敵。他們在耶和華的殿中喧嚷，如在節慶之日一樣。","notes":[]},{"n":8,"t":"耶和華定意拆毀錫安的城牆；他拉了準繩，不將手收回，定要毀滅。他使城郭和城牆都悲哀，一同衰敗。","notes":[]},{"n":9,"t":"錫安的門陷入地裏，主毀壞，折斷她的門閂。她的君王和官長都置身列國中，沒有律法；她的先知也不再從耶和華領受異象。","notes":[]},{"n":10,"t":"錫安的長老坐在地上，默默無聲；他們揚起塵土落在頭上，腰束麻布；耶路撒冷的少女垂頭至地。","notes":[]},{"n":11,"t":"我的眼睛流淚，以致失明；我的心腸煩亂，肝膽落地，都因我的百姓遭毀滅，又因孩童和吃奶的在城內的廣場上昏厥。","notes":["「我的百姓」：原文直譯「我百姓的女兒」。"]},{"n":12,"t":"他們如受傷的人在城內廣場上昏厥，在母親的懷裏將要喪命時，就對母親說：「餅和酒在哪裏呢？」","notes":[]},{"n":13,"t":"耶路撒冷啊，我可用甚麼向你證明呢？我可用甚麼與你相比呢？少女錫安哪，我拿甚麼和你比較，好安慰你呢？因你的裂傷大如海；誰能醫治你呢？","notes":["「耶路撒冷」：原文直譯「耶路撒冷女子」；下同。","「證明」：原文另譯「比較」。","「少女錫安」：原文直譯「少女錫安女子」。"]},{"n":14,"t":"你的先知為你看見虛假和粉飾的異象，並未揭露你的罪孽，使你被擄的歸回；卻傳給你虛假與誤導人的默示。","notes":[]},{"n":15,"t":"凡過路的都向你拍掌。他們向耶路撒冷嗤笑，搖頭：「這就是人稱為全美的、稱為全地所喜悅的城嗎？」","notes":[]},{"n":16,"t":"你所有的仇敵張口來攻擊你；他們嗤笑，切齒，說：「我們把她吞滅了，這是我們所盼望的日子！我們終於等到了，親眼看見了！」","notes":[]},{"n":17,"t":"耶和華成就了他所定的，應驗了他古時所命定的。他傾覆，並不顧惜，他使仇敵向你誇耀，使你敵人的角高舉。","notes":[]},{"n":18,"t":"他們的心哀求主。錫安的城牆啊，願你日夜淚流如河，不讓自己休息，你眼中的瞳人也不歇息。","notes":[]},{"n":19,"t":"夜間每逢時辰開始，要起來呼喊，在主面前傾心吐意如水。你的孩童在街頭上挨餓昏厥，你要為他們的性命向主舉手。","notes":[]},{"n":20,"t":"耶和華啊，求你觀看，留意你向誰這樣行。婦人豈可吃自己所生、所撫育的嬰孩嗎？祭司和先知豈可在主的聖所中被殺嗎？","notes":[]},{"n":21,"t":"年輕人和老年人躺臥在街上，我的少女和壯丁都倒在刀下。你在發怒的日子殺了他們，你殺戮，並不顧惜。","notes":[]},{"n":22,"t":"你從四圍招聚使我驚嚇的人，像在節慶的日子一樣。耶和華發怒的日子，無人逃脫，無人生還。我所撫育養大的，仇敵都殺盡了。","notes":[]}]},"3":{"heading":"懲罰、悔改、盼望","verses":[{"n":1,"t":"因耶和華憤怒的杖，我是遭遇困苦的人。","notes":[]},{"n":2,"t":"他驅趕我走入黑暗，沒有光明。","notes":[]},{"n":3,"t":"他反手攻擊我，終日不停。","notes":[]},{"n":4,"t":"他使我皮肉枯乾，折斷我的骨頭。","notes":[]},{"n":5,"t":"他築壘攻擊我，以苦楚和艱難圍困我；","notes":[]},{"n":6,"t":"使我住在幽暗之處，像死了許久的人一樣。","notes":[]},{"n":7,"t":"他圍住我，使我無法脫身；他使我的銅鏈沉重。","notes":[]},{"n":8,"t":"儘管我哀號求救，他仍攔阻我的禱告。","notes":[]},{"n":9,"t":"他用鑿過的石頭擋住我的道路，使我的路徑彎曲。","notes":[]},{"n":10,"t":"他向我如埋伏的熊，如在隱密處的獅子。","notes":[]},{"n":11,"t":"他使我轉離正路，把我撕碎，使我淒涼。","notes":["「把我撕碎」：有一古譯本是「使我跛腳」。"]},{"n":12,"t":"他拉弓，命我站立，當作箭靶；","notes":[]},{"n":13,"t":"把箭袋中的箭射入我的肺腑。","notes":[]},{"n":14,"t":"我成了全體百姓的笑柄，成了他們終日的歌曲。","notes":[]},{"n":15,"t":"他使我受盡苦楚，飽食茵蔯；","notes":[]},{"n":16,"t":"用沙石磨斷我的牙，以灰塵覆蓋我。","notes":[]},{"n":17,"t":"你使我遠離平安，我忘了何為福樂。","notes":[]},{"n":18,"t":"於是我說：「我的力量衰敗，在耶和華那裏我毫無指望！」","notes":[]},{"n":19,"t":"求你記得我的困苦和流離，它如茵蔯和苦膽一般；","notes":[]},{"n":20,"t":"我心想念這些，就在我裏面憂悶。","notes":["「憂悶」：原文另譯「沉思」。"]},{"n":21,"t":"但我的心回轉過來，因此就有指望；","notes":[]},{"n":22,"t":"因耶和華的慈愛，我們不致滅絕，因他的憐憫永不斷絕，","notes":["「我們不致滅絕」：有古卷是「從不止息」。"]},{"n":23,"t":"每早晨，這都是新的；你的信實極其廣大！","notes":[]},{"n":24,"t":"我心裏說：「耶和華是我的福分，因此，我要仰望他。」","notes":[]},{"n":25,"t":"凡等候耶和華，心裏尋求他的，耶和華必施恩給他。","notes":[]},{"n":26,"t":"人仰望耶和華，安靜等候他的救恩，這是好的。","notes":[]},{"n":27,"t":"人在年輕時負軛，這是好的。","notes":[]},{"n":28,"t":"他當安靜獨坐，因為這是耶和華加在他身上的。","notes":[]},{"n":29,"t":"讓他臉伏於地吧！或者還會有指望。","notes":["「臉伏於地」：原文是「口貼塵土」。"]},{"n":30,"t":"讓人打他耳光，使他飽受凌辱吧！","notes":[]},{"n":31,"t":"主必不永遠撇棄，","notes":[]},{"n":32,"t":"他雖使人憂愁，還要照他豐盛的慈愛施憐憫；","notes":[]},{"n":33,"t":"他並不存心要人受苦，令世人憂愁。","notes":[]},{"n":34,"t":"把世上所有的囚犯踹在腳下，","notes":[]},{"n":35,"t":"在至高者面前扭曲人的公正，","notes":[]},{"n":36,"t":"在人的訴訟上顛倒是非，這都是主看不中的。","notes":[]},{"n":37,"t":"若非主發命令，誰能說了就成呢？","notes":[]},{"n":38,"t":"是禍，是福，不都出於至高者的口嗎？","notes":[]},{"n":39,"t":"人都有自己的罪，活人有甚麼好發怨言的呢？","notes":[]},{"n":40,"t":"讓我們省察，檢討自己的行為，歸向耶和華吧！","notes":[]},{"n":41,"t":"讓我們獻上我們的心，向天上的神舉手！","notes":[]},{"n":42,"t":"我們犯罪悖逆，你並未赦免。","notes":[]},{"n":43,"t":"你渾身是怒氣，追趕我們；你施行殺戮，並不顧惜。","notes":[]},{"n":44,"t":"你以密雲圍著自己，禱告不能穿透。","notes":[]},{"n":45,"t":"你使我們在萬民中成為污物和垃圾。","notes":[]},{"n":46,"t":"我們所有的仇敵張口來攻擊我們；","notes":[]},{"n":47,"t":"驚嚇和陷阱臨到我們，殘害和毀滅也臨到我們。","notes":[]},{"n":48,"t":"因我百姓遭毀滅，我的眼睛淚流成河。","notes":["「我百姓」：原文直譯「我百姓的女兒」。"]},{"n":49,"t":"我的眼睛流淚不停，流淚不止，","notes":[]},{"n":50,"t":"直等到耶和華垂顧，從天上觀看。","notes":[]},{"n":51,"t":"為我城中的百姓，我眼所見的使我心痛。","notes":["「百姓」：原文直譯「女子們」。"]},{"n":52,"t":"無故與我為敵的追逼我，像追捕雀鳥一樣。","notes":[]},{"n":53,"t":"他們要在坑中了結我的性命，丟石頭在我身上。","notes":[]},{"n":54,"t":"眾水淹沒我的頭，我說：「我沒命了！」","notes":[]},{"n":55,"t":"耶和華啊，在極深的地府裏，我求告你的名。","notes":[]},{"n":56,"t":"我的聲音你聽見了，求你不要掩耳不聽我的呼聲，我的求救。","notes":[]},{"n":57,"t":"我求告你的時候，你臨近我，說：「不要懼怕！」","notes":[]},{"n":58,"t":"主啊，你為我伸冤，你救贖了我的命。","notes":[]},{"n":59,"t":"耶和華啊，你已看見我的委屈，求你為我主持正義。","notes":[]},{"n":60,"t":"他們要報復，謀害我，你都看見了。","notes":[]},{"n":61,"t":"耶和華啊，你聽見他們的辱罵，他們害我的一切計謀，","notes":[]},{"n":62,"t":"那些起來攻擊我的人嘴唇所說的話和他們終日攻擊我的計謀。","notes":[]},{"n":63,"t":"求你留意！他們無論坐下或起來，我都是他們的笑柄。","notes":[]},{"n":64,"t":"耶和華啊，求你照他們手所做的向他們施行報應。","notes":[]},{"n":65,"t":"求你使他們心裏剛硬，使你的詛咒臨到他們。","notes":[]},{"n":66,"t":"求你發怒追趕他們，從耶和華的地上除滅他們。","notes":["「地上」：原文是「諸天底下」。"]}]},"4":{"heading":"耶路撒冷陷落","verses":[{"n":1,"t":"唉！黃金竟然無光！純金竟然變色！聖所的石頭散落在街上。","notes":[]},{"n":2,"t":"錫安寶貝的孩子雖然好比精金，現在竟當作陶匠手所做的瓦瓶！","notes":[]},{"n":3,"t":"野狗尚且哺乳其子，我百姓的婦人反倒殘忍，如曠野的鴕鳥一般；","notes":["「我百姓」：原文直譯「我百姓的女兒」；下同。"]},{"n":4,"t":"吃奶孩子的舌頭因乾渴貼住上膛，孩童求餅，卻無人擘給他們。","notes":[]},{"n":5,"t":"素來吃美好食物的，如今遭遺棄在街上；素來穿著朱紅衣裳長大的，如今卻擁抱糞堆。","notes":[]},{"n":6,"t":"我百姓的罪孽比所多瑪的罪還大；所多瑪雖無人伸手攻擊，轉眼之間就被傾覆。","notes":[]},{"n":7,"t":"錫安的拿細耳人比雪純淨，比奶更白；他們的身體比寶石更紅，身軀之美如藍寶石一般。","notes":["「拿細耳人」：參民6．2。"]},{"n":8,"t":"但如今他們的面貌比煤炭更黑，在街上無人認識；他們的皮膚緊貼骨頭，枯乾形同槁木。","notes":[]},{"n":9,"t":"被刀劍刺殺的勝過因飢餓而死的；飢餓者由於缺乏田裏的出產就消瘦而亡。","notes":["「死」：原文是「被刺殺」。","「亡」：原文是「刺穿」。"]},{"n":10,"t":"當我百姓遭毀滅的時候，慈心的婦人親手烹煮自己的兒女為食物。","notes":[]},{"n":11,"t":"耶和華發盡他的憤怒，傾倒他的烈怒，用火焚燒錫安，燒燬錫安的根基。","notes":[]},{"n":12,"t":"地上的君王和世上的居民都不信敵人和仇敵竟能進入耶路撒冷的城門。","notes":[]},{"n":13,"t":"這都因她先知的罪惡和祭司的罪孽，他們在城中流了義人的血。","notes":[]},{"n":14,"t":"他們如盲人在街上徘徊，又被血玷污，以致人不敢摸他們的衣服。","notes":[]},{"n":15,"t":"人向他們喊著：「你這不潔淨的，走開！走開！走開！不要摸我！」他們逃走流浪的時候，列國中有人說：「他們不可再寄居此地。」","notes":[]},{"n":16,"t":"耶和華親自趕散他們，不再眷顧他們；不看重祭司，也不厚待長老。","notes":[]},{"n":17,"t":"我們的眼目徒然仰望幫助，以致失明，我們從瞭望臺所守望的，竟是一個不能救人的國！","notes":[]},{"n":18,"t":"仇敵追逐我們的腳蹤，使我們不敢在自己的街上行走。我們的結局臨近，日子已滿，我們的結局已經來到。","notes":[]},{"n":19,"t":"追趕我們的比空中的鷹更快；他們在山上追逼我們，在曠野埋伏，等候我們。","notes":[]},{"n":20,"t":"耶和華的受膏者是我們鼻中的氣，被抓到他們的坑裏，論到他，我們曾說：「我們必在他蔭下，在列國中存活。」","notes":[]},{"n":21,"t":"住烏斯地的以東啊，儘管歡喜快樂，苦杯必傳到你那裏；你要喝醉，裸露自己。","notes":["「以東」：原文直譯「以東女子」；下同。"]},{"n":22,"t":"錫安哪，你罪孽的懲罰已經結束，耶和華必不再使你被擄去。以東啊，耶和華必懲罰你的罪孽，揭露你的罪惡。","notes":["「錫安」：原文直譯「錫安女子」。"]}]},"5":{"heading":"求耶和華垂憐","verses":[{"n":1,"t":"耶和華啊，求你顧念我們所遭遇的，留意看我們所受的凌辱。","notes":[]},{"n":2,"t":"我們的產業歸陌生人，我們的房屋歸外邦人。","notes":[]},{"n":3,"t":"我們是無父的孤兒，我們的母親如同寡婦。","notes":[]},{"n":4,"t":"我們出銀錢才得水喝，我們的柴也是用錢買來的。","notes":[]},{"n":5,"t":"我們被追趕，迫及頸項，疲乏卻不得歇息。","notes":[]},{"n":6,"t":"我們束手投降埃及和亞述，為要得糧吃飽。","notes":[]},{"n":7,"t":"我們的祖先犯罪，而今他們不在了，我們卻擔當他們的罪孽。","notes":[]},{"n":8,"t":"奴僕轄制我們，無人救我們脫離他們的手。","notes":[]},{"n":9,"t":"因曠野有刀劍，我們冒生命的危險才能得糧食。","notes":[]},{"n":10,"t":"因饑荒的乾熱，我們的皮膚熱如火爐。","notes":[]},{"n":11,"t":"他們在錫安玷污婦人，在猶大城鎮污辱少女。","notes":[]},{"n":12,"t":"他們吊起領袖的手，使長老臉上無光。","notes":[]},{"n":13,"t":"年輕人扛磨石，孩童背木柴而跌倒。","notes":[]},{"n":14,"t":"城門口不再有老年人，年輕人也不再奏樂。","notes":[]},{"n":15,"t":"我們心中的快樂止息，跳舞轉為悲哀。","notes":[]},{"n":16,"t":"冠冕從我們的頭上掉落；我們有禍了，因為犯了罪。","notes":[]},{"n":17,"t":"因這些事我們心裏發昏，眼睛昏花。","notes":[]},{"n":18,"t":"錫安山荒涼，狐狸行在其上。","notes":[]},{"n":19,"t":"耶和華啊，你治理直到永遠，你的寶座萬代長存。","notes":[]},{"n":20,"t":"你為何全然忘記我們？為何長久離棄我們？","notes":[]},{"n":21,"t":"耶和華啊，求你使我們回轉歸向你，我們就得以回轉。求你更新我們的年日，像古時一樣，","notes":[]},{"n":22,"t":"難道你全然棄絕了我們，向我們大發烈怒？","notes":[]}]}},"EZK":{"1":{"heading":"以西結的第一個異象","verses":[{"n":1,"t":"在三十年四月初五，我在迦巴魯河邊被擄的人當中，那時天開了，我看見神的異象。","notes":[],"heads":["神的寶座"]},{"n":2,"t":"正是約雅斤王被擄的第五年四月初五，","notes":[]},{"n":3,"t":"在迦勒底人之地的迦巴魯河邊，耶和華的話特地臨到布西的兒子以西結祭司，耶和華的手按在他身上。","notes":[]},{"n":4,"t":"我觀看，看哪，狂風從北方颳來，有一朵大雲閃爍著火，周圍有光輝，其中的火好像閃耀的金屬；","notes":[]},{"n":5,"t":"又從其中顯出四個活物的形像。他們的形狀是這樣：有人的形像，","notes":[]},{"n":6,"t":"各有四張臉，四個翅膀。","notes":[]},{"n":7,"t":"他們的腿是直的，腳掌好像牛犢的蹄，燦爛如磨亮的銅。","notes":[]},{"n":8,"t":"在四面的翅膀以下有人的手。這四個活物的臉和翅膀是這樣：","notes":[]},{"n":9,"t":"翅膀彼此相接，行走時並不轉彎，各自往前直行。","notes":[]},{"n":10,"t":"至於臉的形像：四個活物各有人的臉，右面有獅子的臉，左面有牛的臉，也有鷹的臉；","notes":[]},{"n":11,"t":"這就是他們的臉。他們的翅膀向上張開，各有兩個翅膀彼此相接，用另外兩個翅膀遮體。","notes":["七十士譯本沒有「這就是他們的臉」。"]},{"n":12,"t":"他們各自往前直行。靈往哪裏去，他們就往哪裏去，行走時並不轉彎。","notes":[]},{"n":13,"t":"至於四活物的形像，就如燒著火炭的形狀，又如火把的形狀。有火在四活物中間來回移動，這火有光輝，從火中發出閃電。","notes":[]},{"n":14,"t":"這些活物往來奔走，好像電光一閃。","notes":[]},{"n":15,"t":"我觀看活物，看哪，有四張臉的活物旁邊各有一個輪子在地上。","notes":[]},{"n":16,"t":"輪子的形狀結構好像耀眼的水蒼玉。四輪都是一個樣式，形狀結構好像輪中套輪。","notes":["七十士譯本沒有「結構」。","七十士譯本沒有「形狀」。"]},{"n":17,"t":"輪子行走的時候，向四方直行，行走時並不轉彎。","notes":[]},{"n":18,"t":"至於輪圈，高而可畏；四個輪圈周圍佈滿眼睛。","notes":[]},{"n":19,"t":"活物行走，輪子也在旁邊行走；活物離地上升，輪子也上升。","notes":[]},{"n":20,"t":"靈往哪裏去，活物就往哪裏去；輪子在活物旁邊上升，因為活物的靈在輪中。","notes":[]},{"n":21,"t":"活物行走，輪子也行走；活物站住，輪子也站住；活物離地上升，輪子也在旁邊上升，因為活物的靈在輪中。","notes":[]},{"n":22,"t":"活物的頭上面有穹蒼的形像，像耀眼驚人的水晶，鋪張在活物的頭頂上。","notes":[]},{"n":23,"t":"穹蒼之下，活物的翅膀伸直，彼此相對，每個活物用兩個翅膀遮住自己；每個活物用兩個翅膀遮住自己 ，就是自己的身體。","notes":["有古卷和七十士譯本沒有第二次的「每個活物用兩個翅膀遮住自己」。"]},{"n":24,"t":"活物行走的時候，我聽見翅膀的響聲，像大水的聲音，像全能者的聲音，又像軍隊鬧鬨的聲音。活物站住的時候，翅膀垂下。","notes":[]},{"n":25,"t":"在他們頭上的穹蒼之上有聲音。他們站住的時候，翅膀垂下。","notes":[]},{"n":26,"t":"在他們頭上的穹蒼之上有寶座的形像，彷彿藍寶石的樣子；寶座的形像上方有彷彿人的樣子的形像。","notes":[]},{"n":27,"t":"我見他的腰以上有彷彿閃耀的金屬，周圍有彷彿火的形狀，又見他的腰以下有彷彿火的形狀，周圍也有光輝。","notes":[]},{"n":28,"t":"下雨的日子，雲中彩虹的形狀怎樣，周圍光輝的形狀也是怎樣。這就是耶和華榮耀形像的樣式，我一看見就臉伏於地。我又聽見一位說話者的聲音。","notes":[]}]},"2":{"heading":"神選召以西結作先知","verses":[{"n":1,"t":"他對我說：「人子啊，你站起來，我要和你說話。」","notes":[]},{"n":2,"t":"他對我說話的時候，靈進入我裏面，使我站起來，我就聽見他對我說話。","notes":[]},{"n":3,"t":"他對我說：「人子啊，我差你往悖逆我的國家，以色列人那裏去，他們是悖逆我的。他們和他們的祖先違背我，直到今日。","notes":[]},{"n":4,"t":"這些人厚著臉皮，心裏剛硬。我差你到他們那裏去，你要對他們說：『主耶和華如此說。』","notes":[]},{"n":5,"t":"他們是悖逆之家，他們或聽，或不聽，必知道在他們中間有了先知。","notes":[]},{"n":6,"t":"你，人子啊，雖有荊棘和蒺藜在你那裏，你又住在蠍子中間，總不要怕他們，也不要怕他們的話；他們雖是悖逆之家，但你不要怕他們的話，也不要因他們的臉色驚惶。","notes":[]},{"n":7,"t":"他們或聽，或不聽，你只管將我的話告訴他們；他們是極其悖逆的。","notes":[]},{"n":8,"t":"「但是你，人子啊，要聽我對你說的話，不要像那悖逆之家一樣悖逆，要開口吃我所賜給你的。」","notes":[]},{"n":9,"t":"我觀看，看哪，有一隻手向我伸來；看哪，手中有一書卷。","notes":[]},{"n":10,"t":"他在我面前展開書卷，它內外都寫著字，上面所寫的有哀號、嘆息、悲痛的話。","notes":[]}]},"3":{"heading":"耶和華派以西結作守望者","verses":[{"n":1,"t":"他對我說：「人子啊，要吃你所得到的，吃下這書卷；然後要去，對以色列家宣講。」","notes":[]},{"n":2,"t":"於是我張開了口，他就使我吃這書卷。","notes":[]},{"n":3,"t":"他對我說：「人子啊，要吃我所賜給你的這書卷，塞滿你的肚腹。」我就吃了，口中覺得其甜如蜜。","notes":[]},{"n":4,"t":"他對我說：「人子啊，你要到以色列家那裏去，對他們傳講我的話。","notes":[]},{"n":5,"t":"你奉差遣不是往那說話艱澀、言語難懂的民那裏，而是往以色列家去；","notes":[]},{"n":6,"t":"你不是往那說話艱澀、言語難懂的許多民族那裏去，他們的話你不懂。然而，我若差你往他們那裏去，他們會聽從你。","notes":[]},{"n":7,"t":"以色列家卻不肯聽從你，因為他們不肯聽從我；原來以色列全家是額頭堅硬、心裏剛愎的人。","notes":[]},{"n":8,"t":"看哪，我使你的臉堅硬，對抗他們的臉；使你的額頭堅硬，對抗他們的額頭。","notes":[]},{"n":9,"t":"我使你的額頭像金剛石，比火石更堅硬。他們雖是悖逆之家，但你不要怕他們，也不要因他們的臉色而驚惶。」","notes":[]},{"n":10,"t":"他又對我說：「人子啊，我對你說的一切話，你心裏要領會，耳朵要聽。","notes":[]},{"n":11,"t":"要到被擄的人，到你本國百姓那裏去，他們或聽，或不聽，你要對他們宣講，告訴他們這是主耶和華說的。」","notes":[]},{"n":12,"t":"那時，靈將我舉起，我就聽見在我身後有極大震動的聲音：「耶和華的榮耀，從他所在之處，是應當稱頌的！」","notes":[]},{"n":13,"t":"有活物的翅膀相碰的聲音，也有活物旁邊輪子的聲音，是極大震動的聲音。","notes":[]},{"n":14,"t":"於是靈將我舉起，帶著我走。我就去了，十分苦惱，我的靈火熱；耶和華的手重重地按在我身上。","notes":[]},{"n":15,"t":"我就來到提勒‧亞畢那些住在迦巴魯河邊被擄的人那裏，到他們住的地方，在他們中間驚愕地坐了七日。","notes":["「到他們住的地方」：原文另譯「我就住在他們住的地方」。"]},{"n":16,"t":"過了七日，耶和華的話臨到我，說：","notes":[]},{"n":17,"t":"「人子啊，我立你作以色列家的守望者，所以你要聽我口中的話，替我警戒他們。","notes":[]},{"n":18,"t":"我何時指著惡人說：『他必要死』；你若不警戒他，也不勸告他，使他離開惡行，拯救他的性命，這惡人必死在罪孽之中；我卻要從你手裏討他的血債。","notes":[]},{"n":19,"t":"倘若你警戒惡人，他仍不轉離罪惡，也不離開惡行，他必死在罪孽之中，你卻救了自己的命。","notes":[]},{"n":20,"t":"但是義人若轉離他的義而作惡，我要把絆腳石放在他面前，他必死亡；因你沒有警戒他，他必死在罪中，他素來所行的義不被記念；我卻要從你手裏討他的血債。","notes":[]},{"n":21,"t":"倘若你警戒義人，使他不犯罪，他就不犯罪；他因領受警戒就必存活，你也救了自己的命。」","notes":[]},{"n":22,"t":"在那裏耶和華的手按在我身上。他對我說：「起來，到平原去，我要在那裏和你說話。」","notes":[],"heads":["以西結暫成啞巴"]},{"n":23,"t":"於是我起來，到平原去，看哪，耶和華的榮耀停在那裏，正如我在迦巴魯河邊所見到的一樣，我就臉伏於地。","notes":[]},{"n":24,"t":"靈進入我裏面，使我站起來。耶和華對我說：「你進屋裏去，把門關上。","notes":[]},{"n":25,"t":"你，人子，看哪，人要用繩索捆綁你，使你不能出去到他們中間。","notes":[]},{"n":26,"t":"我必使你的舌頭貼住上膛，以致你啞口，不能作責備他們的人；他們原是悖逆之家。","notes":[]},{"n":27,"t":"但我對你說話的時候，必使你開口，你就要對他們說：『主耶和華如此說。』聽的，讓他聽；不聽的，任他不聽，因為他們是悖逆之家。」","notes":[]}]},"4":{"heading":"預演耶路撒冷被困","verses":[{"n":1,"t":"「你，人子啊，拿一塊磚，擺在你面前，將一座城耶路撒冷畫在上面。","notes":[]},{"n":2,"t":"你要圍攻這城，築堡壘，建土堆，安營攻擊，周圍設撞城槌攻城，","notes":[]},{"n":3,"t":"又要拿一個鐵盤放在你和城的中間，作為鐵牆。你要把你的臉對著這城，使城被困。你要圍攻這城，這要成為以色列家的預兆。","notes":[]},{"n":4,"t":"「你要向左側臥，承擔以色列家的罪孽；按你向左側臥的日數，擔當他們的罪孽。","notes":[]},{"n":5,"t":"我已將他們作惡的年數定了日期，就是三百九十天，你要如此擔當以色列家的罪孽。","notes":[]},{"n":6,"t":"這些日子結束之後，你還要向右側臥，擔當猶大家的罪孽。我為你定了四十天，一天頂一年。","notes":[]},{"n":7,"t":"你要把你的臉對著被困的耶路撒冷，露出膀臂，說預言攻擊這城。","notes":[]},{"n":8,"t":"看哪，我用繩索捆綁你，使你不能從這邊翻到那邊，直等到你圍困的日子結束。","notes":[]},{"n":9,"t":"「你要取小麥、大麥、豆子、紅豆、小米、粗麥，裝在一個器皿裏，為自己做餅；在你側臥的三百九十天吃這餅。","notes":[]},{"n":10,"t":"你所吃食物的量是每天二十舍客勒，要按時吃。","notes":[]},{"n":11,"t":"你喝水的量是每天六分之一欣，要按時喝。","notes":[]},{"n":12,"t":"你要吃這餅像大麥餅一樣，在眾人眼前用人的糞烤它。」","notes":[]},{"n":13,"t":"耶和華說：「以色列人在我趕他們到的列國中，也必這樣吃不潔淨的食物。」","notes":[]},{"n":14,"t":"我說：「唉！主耶和華，看哪，我從來未曾被玷污，從幼年到如今沒有吃過自然死的，或被野獸撕裂的，那不潔淨的肉也未曾入我的口。」","notes":[]},{"n":15,"t":"於是他對我說：「看，我給你牛糞代替人糞，你要在上面烤你的餅。」","notes":[]},{"n":16,"t":"他又對我說：「人子，看哪，我必斷絕耶路撒冷糧食的供應。他們要帶著憂慮限量吃餅；帶著驚惶限量喝水。","notes":["「糧食的供應」：原文直譯「糧食的杖」；本卷書下同。"]},{"n":17,"t":"他們因缺糧缺水，彼此驚惶，在自己的罪孽中消滅。」","notes":[]}]},"5":{"heading":"以西結剃髮","verses":[{"n":1,"t":"「你，人子啊，拿一把快刀當作剃刀，用這刀剃你的頭髮和鬍鬚，然後用天平將鬚髮分成幾份。","notes":[]},{"n":2,"t":"圍困的日子滿了，你要把三分之一放在城中用火焚燒；三分之一放在城的四圍用刀砍碎；三分之一任風吹散，我要拔刀追趕它們。","notes":[]},{"n":3,"t":"你要從其中取幾根鬚髮，用衣服的邊包起來，","notes":[]},{"n":4,"t":"再從其中取一些扔在火裏，在火中焚燒；必有火從其中出來燒盡以色列全家。","notes":[]},{"n":5,"t":"主耶和華如此說：這就是耶路撒冷。我曾將它安置在列國中，列邦都在它的四圍。","notes":[]},{"n":6,"t":"耶路撒冷行惡，違背我的典章，過於列國；干犯我的律例，過於四圍的列邦。它棄絕我的典章，也沒有遵行我的律例。","notes":[]},{"n":7,"t":"所以主耶和華如此說：因為你們混亂，過於四圍的列國，不遵行我的律例，不順從我的典章，甚至也不順從四圍列國的規條，","notes":["「甚至...規條」：有古卷和古譯本是「並以遵從四圍列國的惡規尚不滿意」。"]},{"n":8,"t":"所以主耶和華如此說：看哪，我，我必與你為敵，必在列國眼前，在你中間施行審判；","notes":[]},{"n":9,"t":"並且因你一切可憎的事，我要在你中間行未曾行過，將來也不會行的事。","notes":[]},{"n":10,"t":"在你中間，父親要吃兒子，兒子要吃父親。我必向你施行審判，將你剩下的人分散四方。","notes":["「方」：原文是「風」；下同。"]},{"n":11,"t":"主耶和華說：我指著我的永生起誓，因你用一切可憎之物、可厭的事玷污我的聖所，所以，我要把你剃光 ，我的眼必不顧惜你，也不可憐你。","notes":["「把你剃光」：有古卷是「使你減少」；七十士譯本是「棄絕你」。"]},{"n":12,"t":"你的百姓三分之一必遭瘟疫而死，因饑荒在你們中間而消滅；三分之一必在你四圍倒在刀下；我必將三分之一分散四方，要拔刀追趕他們。","notes":[]},{"n":13,"t":"「我要這樣發盡我的怒氣；我向他們發的憤怒停止以後，自己就得到平息。當我向他們發盡我的憤怒時，他們就知道我─耶和華所說的是出於妒忌。","notes":[]},{"n":14,"t":"在四圍的列國中，我要使你成為荒涼，在所有過路人的眼前看為羞辱。","notes":[]},{"n":15,"t":"這樣，我必以怒氣、憤怒和烈怒的責備，向你施行審判。那時，它就在四圍的列國中成為羞辱、譏刺、警戒、驚駭；這是我─耶和華說的。","notes":["「它」：七十士譯本和其他古譯本是「你」。"]},{"n":16,"t":"我向滅亡的人射出饑荒的惡箭，將它們射出，毀滅你們；那時，我要加重你們的饑荒，斷絕你們糧食的供應。","notes":[]},{"n":17,"t":"我要令饑荒和惡獸臨到你，使你喪失兒女。瘟疫和流血的事必在你那裏盛行，我也要使刀劍臨到你。這是我─耶和華說的。」","notes":[]}]},"6":{"heading":"譴責拜偶像的罪","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要面向以色列的眾山說預言。","notes":[]},{"n":3,"t":"你要說：以色列的眾山哪，要聽主耶和華的話。主耶和華對大山、小岡、水溝、山谷如此說：看哪，我要使刀劍臨到你們，也必毀壞你們的丘壇。","notes":[]},{"n":4,"t":"你們的祭壇要荒廢，香壇必打碎。我要使你們當中被殺的人仆倒在你們的偶像面前，","notes":[]},{"n":5,"t":"將以色列人的屍首放在他們的偶像面前，把你們的骸骨拋散在祭壇的四周圍。","notes":[]},{"n":6,"t":"無論你們住在何處，城鎮要變為廢墟，丘壇也必毀壞，以至於你們的祭壇荒廢，被定罪，偶像打碎消除，香壇砍倒；你們所做的被塗去。","notes":["「被定罪」：有古譯本是「毀壞」。"]},{"n":7,"t":"被殺的人必仆倒在你們中間，你們就知道我是耶和華。","notes":[]},{"n":8,"t":"「我必留下一些人，你們中有人得以在列國中脫離刀劍，分散在列邦。","notes":[]},{"n":9,"t":"那些逃脫的人，必在被擄所到的各國中記得我，我心裏何等傷痛，因他們起淫心，離棄我，淫蕩的眼追隨偶像。他們因所做一切可憎的惡事，必厭惡自己。","notes":[]},{"n":10,"t":"他們必知道我是耶和華；我說過要使這災禍臨到他們身上，並非空話。","notes":[]},{"n":11,"t":"「主耶和華如此說：你當擊掌頓足，說：哀哉！以色列家做了這一切可憎的惡事，必仆倒在刀劍、饑荒、瘟疫之下。","notes":[]},{"n":12,"t":"在遠方的，必遭瘟疫而死；在近處的，必倒在刀劍之下；那存留被圍困的，必因饑荒而死；我要在他們身上發盡我的憤怒。","notes":[]},{"n":13,"t":"被殺的要仆倒在祭壇四圍的偶像中，在各高岡、各山頂、各青翠的樹下，和各茂密的橡樹下，就是他們獻馨香的祭給一切偶像的地方。那時，他們就知道我是耶和華。","notes":[]},{"n":14,"t":"我必伸手攻擊他們，使他們的地荒廢，從第伯拉他的曠野起，一切的住處都荒涼。他們就知道我是耶和華。」","notes":["「從第伯拉他的曠野起」：有古卷是「從曠野到利比拉」。"]}]},"7":{"heading":"以色列的結局近了","verses":[{"n":1,"t":"耶和華的話又臨到我，說：","notes":[]},{"n":2,"t":"「你，人子啊，主耶和華對以色列地如此說：結局，結局臨到了地的四境！","notes":[]},{"n":3,"t":"現在你的結局已經來臨；我要使我的怒氣臨到你，也要按你的行為審判你，照你所做一切可憎的事懲罰你。","notes":[]},{"n":4,"t":"我的眼必不顧惜你，也不可憐你，卻要按你所做的報應你，照你們中間可憎的事懲罰你；你就知道我是耶和華。","notes":[]},{"n":5,"t":"「主耶和華如此說：災難，惟一的災難，看哪，臨近了！","notes":["「災難…災難」：有古卷是「災難接著災難」。"]},{"n":6,"t":"結局到了，結局到了，它要醒起來攻擊你。看哪，它已來到！","notes":[]},{"n":7,"t":"境內的居民哪，厄運臨到你；時候到了，日子近了，有鬧鬨，但不是山上歡呼的聲音。","notes":[]},{"n":8,"t":"我快要將我的憤怒傾倒在你身上，向你發盡我的怒氣，按你的行為審判你，照你所做一切可憎的事懲罰你。","notes":[]},{"n":9,"t":"我的眼必不顧惜你，也不可憐你，必按你所做的報應你，照你中間可憎的事懲罰你；你就知道擊打你的是我─耶和華。","notes":[]},{"n":10,"t":"「看哪，那日子！看哪，已來到！厄運已經發生！杖已開花，驕傲已發芽。","notes":[]},{"n":11,"t":"殘暴興起，成了罰惡的杖。他們將一無所有，他們的富足、他們的財寶都不復存在；他們中間也不再有尊榮。","notes":["「富足」或譯「群眾」。","「財寶」或譯「喧囂」。"]},{"n":12,"t":"時候到了，日子近了，買主不可歡喜，賣主也不用愁煩，因為烈怒已經臨到他們眾人身上。","notes":[]},{"n":13,"t":"賣主即使存活，也不能討回所賣的，因為這異象關乎他們眾人；誰都不能討回，也沒有人能在罪孽中使自己的生命剛強。」","notes":[]},{"n":14,"t":"「他們吹了角，預備齊全，卻無一人出戰，因為我的烈怒臨到他們眾人身上。","notes":[],"heads":["懲罰以色列的罪惡"]},{"n":15,"t":"外有刀劍，內有瘟疫、饑荒。在田野的，必因刀劍而死；在城中的，必遭饑荒、瘟疫吞滅。","notes":[]},{"n":16,"t":"其中倖存的要逃脫，各人因自己的罪孽在山上發出悲聲，如谷中的鴿子哀鳴；","notes":[]},{"n":17,"t":"雙手發軟，膝蓋軟弱如水，","notes":[]},{"n":18,"t":"腰束麻布，戰慄籠罩他們；各人臉上羞愧，頭上光禿。","notes":[]},{"n":19,"t":"他們要把銀子拋棄在街上，看金子如污穢之物。正當耶和華發怒的日子，金銀不能拯救他們，不能滿足食慾，也不能使肚腹飽滿，反倒成了自己罪孽的絆腳石。","notes":[]},{"n":20,"t":"他們用所誇耀華美的妝飾製造可憎可厭的偶像，所以我使他們看它如污穢之物。","notes":[]},{"n":21,"t":"我必將它交給外邦人為掠物，交給地上的惡人為擄物；他們要褻瀆它。","notes":[]},{"n":22,"t":"他們褻瀆我寶貴之所，強盜也進去褻瀆它。我必轉臉不顧以色列人。","notes":["「寶貴之所」或譯「隱密之所」。","「以色列人」：原文是「他們」。"]},{"n":23,"t":"「要製造鎖鏈；因為遍地都有流血的罪，滿城都是殘暴的事。","notes":[]},{"n":24,"t":"所以，我要使列國中最兇惡的人前來佔據他們的房屋；我要止息殘暴人的驕傲，他們的聖所也要被褻瀆。","notes":[]},{"n":25,"t":"毀滅來到；他們求平安，卻沒有平安。","notes":[]},{"n":26,"t":"災害加上災害，風聲接連風聲；他們要向先知尋求異象，但祭司的教誨、長老的謀略都必斷絕。","notes":[]},{"n":27,"t":"君王要悲哀，官長要披絕望為衣，這地百姓的手都發顫。我必照他們所做的待他們，按他們所應得的審判他們，他們就知道我是耶和華。」","notes":[]}]},"8":{"heading":"以西結所見的第二個異象","verses":[{"n":1,"t":"第六年六月初五，我坐在家中；猶大的眾長老坐在我面前。在那裏主耶和華的手降在我身上。","notes":[],"heads":["耶路撒冷城裏的偶像崇拜"]},{"n":2,"t":"我觀看，看哪，有形像彷彿火的形狀，從他腰部以下形狀是火，從他腰部以上有光輝的形狀，好像閃耀的金屬。","notes":["「火」：七十士譯本是「人」。"]},{"n":3,"t":"他伸出一隻手的樣式，抓住我的一綹頭髮，靈就將我舉到天地中間；在神的異象中，他帶我到耶路撒冷朝北的內院門口，在那裏有惹動妒忌的偶像的座位，它惹動了妒忌。","notes":[]},{"n":4,"t":"看哪，在那裏有以色列神的榮耀，形狀與我在平原所見的一樣。","notes":[]},{"n":5,"t":"神對我說：「人子啊，你舉目向北觀看。」我就舉目向北觀看，看哪，祭壇門北邊的門口有那惹動妒忌的偶像。","notes":[]},{"n":6,"t":"他又對我說：「人子啊，你看見以色列家所做的嗎？他們在這裏做了極其可憎的事，使我遠離我的聖所。你還要看見另有極其可憎的事。」","notes":[]},{"n":7,"t":"他領我到院子門口。我觀看，看哪，牆上有一個洞。","notes":[]},{"n":8,"t":"他對我說：「人子啊，你要挖牆。」我就挖牆。看哪，有一扇門。","notes":[]},{"n":9,"t":"他說：「你進去，看他們在這裏所做可憎的惡事。」","notes":[]},{"n":10,"t":"於是我進去看。看哪，四面牆上刻著各樣爬行的動物、可憎的走獸和以色列家各樣的偶像。","notes":[]},{"n":11,"t":"以色列家的七十個長老站在這些像前，沙番的兒子雅撒尼亞也站在其中，各人手拿他的香爐，煙雲的香氣上騰。","notes":[]},{"n":12,"t":"他對我說：「人子啊，你看見以色列家的長老，暗中在自己偶像的房間裏所做的嗎？因為他們說：『耶和華看不見我們；耶和華已經離棄這地。』」","notes":[]},{"n":13,"t":"他又說：「你還要看見他們所做另外極其可憎的事。」","notes":[]},{"n":14,"t":"他領我到耶和華殿朝北的門口。看哪，在那裏有婦女們坐著，為搭模斯哭泣。","notes":["「搭模斯」為神明的名字。"]},{"n":15,"t":"他對我說：「人子啊，你看見了嗎？你還要看見比這更可憎的事。」","notes":[]},{"n":16,"t":"然後他領我到耶和華殿的內院。看哪，在耶和華殿門口、走廊和祭壇中間，約有二十五個人背向耶和華的殿，面向東方，向東拜太陽。","notes":[]},{"n":17,"t":"他對我說：「人子啊，你看見了嗎？猶大家在這裏行可憎的事還算為小嗎？他們遍地行殘暴，再三惹我發怒。看哪，他們手拿枝條舉向鼻前！","notes":["「手拿枝條舉向鼻前」：這是侮辱神的動作。"]},{"n":18,"t":"因此，我也要以憤怒行事。我的眼必不顧惜，也不可憐他們；他們雖在我耳邊大聲呼求，我還是不聽。」","notes":[]}]},"9":{"heading":"耶路撒冷受懲罰","verses":[{"n":1,"t":"他在我耳邊大聲喊叫，說：「上前來啊，懲罰這城的人，手中要各拿毀滅的兵器。」","notes":[]},{"n":2,"t":"看哪，有六個人從朝北的上門而來，各人手裏拿著致命的兵器；他們當中有一人身穿細麻衣，腰間繫著文士用的墨盒。他們進來，站在銅的祭壇旁。","notes":[]},{"n":3,"t":"在基路伯之上，以色列神的榮耀從那裏上升，到殿的入口處。神召那身穿細麻衣、腰間繫著墨盒的人前來。","notes":[]},{"n":4,"t":"耶和華對他說：「你去走遍耶路撒冷全城，那些為城中所做可憎之事嘆息哀哭的人，你要在他們額上做記號。」","notes":[]},{"n":5,"t":"我耳中聽見耶和華對其餘的人說：「要跟隨他走遍全城去擊殺。你們的眼不要顧惜，也不要可憐他們。","notes":[]},{"n":6,"t":"要將年老的、年輕的、少女、孩童和婦女，從我的聖所開始全都殺盡，只是不可挨近凡有記號的人。」於是他們從殿前的長老殺起。","notes":[]},{"n":7,"t":"他對他們說：「要使這殿污穢，使院中遍滿被殺的人。你們出去吧！」他們就出去，在城中擊殺。","notes":[]},{"n":8,"t":"他們擊殺的時候，只剩我一人，我就臉伏在地上，呼喊說：「唉！主耶和華啊，你將憤怒傾倒在耶路撒冷，豈要把以色列所剩餘的人都滅絕嗎？」","notes":[]},{"n":9,"t":"他對我說：「以色列家和猶大家的罪孽極其重大。遍地都有流血的事，滿城有冤屈，因為他們說：『耶和華已經離棄這地，他看不見我們。』","notes":[]},{"n":10,"t":"因此，我的眼必不顧惜，也不可憐他們，要照他們所做的報應在他們頭上。」","notes":[]},{"n":11,"t":"看哪，那身穿細麻衣、腰間繫著墨盒的人回覆這事說：「我已經照你所吩咐的做了。」","notes":[]}]},"10":{"heading":"耶和華的榮耀離開聖城","verses":[{"n":1,"t":"我觀看，看哪，在穹蒼之中，也就是基路伯的頭上，有藍寶石的形狀，彷彿寶座的形像顯在他們上面。","notes":[]},{"n":2,"t":"耶和華對那身穿細麻衣的人說：「你進到基路伯下面旋轉的輪子中，從基路伯之間取出火炭裝滿兩手掌，撒在城上。」我親眼看見他進去。","notes":[]},{"n":3,"t":"那人進去的時候，基路伯站在殿的南邊，雲彩充滿了內院。","notes":[]},{"n":4,"t":"耶和華的榮耀從基路伯那裏上升，到殿的入口處；殿內滿佈雲彩，院子也充滿了耶和華榮耀的光輝。","notes":[]},{"n":5,"t":"基路伯翅膀的響聲傳到外院，好像全能神說話的聲音。","notes":[]},{"n":6,"t":"耶和華吩咐那身穿細麻衣的人說：「要從基路伯之間旋轉的輪子中取火。」那人就進去站在一個輪子旁邊。","notes":[]},{"n":7,"t":"基路伯中的一個基路伯伸手到基路伯中間的火那裏，取一些放在那身穿細麻衣人的手掌中，那人拿了就出去。","notes":[]},{"n":8,"t":"在基路伯翅膀以下，顯出有人手的樣式。","notes":[]},{"n":9,"t":"我又觀看，看哪，這些基路伯的旁邊有四個輪子。一個基路伯旁有一個輪子，另一個基路伯旁也有一個輪子；輪子的形狀好像水蒼玉石。","notes":[]},{"n":10,"t":"至於四輪的形狀，都是一個樣式，好像輪中套輪。","notes":[]},{"n":11,"t":"輪子行走的時候，向四方都能直行，行走時並不轉彎。頭轉向何方，它們也隨著向何方行走，行走時並不轉彎。","notes":[]},{"n":12,"t":"基路伯的全身，連背帶手和翅膀，並輪子周圍都佈滿眼睛。他們四個的輪子都是如此。","notes":[]},{"n":13,"t":"我耳中聽見這些輪子稱為「旋轉的輪」。","notes":[]},{"n":14,"t":"基路伯各有四張臉：第一是基路伯的臉，第二是人的臉，第三是獅子的臉，第四是鷹的臉。","notes":[]},{"n":15,"t":"基路伯升上去了；這就是我在迦巴魯河邊所看見的活物。","notes":[]},{"n":16,"t":"基路伯行走，輪子也在旁邊行走。基路伯展開翅膀，離地上升，輪子也不轉離他們的旁邊。","notes":[]},{"n":17,"t":"基路伯站住，輪子也站住；基路伯上升，輪子也跟著上升，因為活物的靈在輪中。","notes":[]},{"n":18,"t":"耶和華的榮耀離開殿的入口處，停在基路伯之上。","notes":[]},{"n":19,"t":"基路伯展開翅膀，在我眼前離地上升；他們離去的時候，輪子在旁邊，都停在耶和華殿的東門口。在他們上面有以色列神的榮耀。","notes":[]},{"n":20,"t":"這是我在迦巴魯河邊所見的活物，他們在以色列神之下；因此我知道他們是基路伯。","notes":[]},{"n":21,"t":"他們各有四張臉、四個翅膀，翅膀以下有人手的樣式。","notes":[]},{"n":22,"t":"至於他們臉的模樣，以及身體的形像，正是我從前在迦巴魯河邊所看見的。他們各自往前直行。","notes":["七十士譯本沒有「以及身體的形像」。"]}]},"11":{"heading":"耶路撒冷被判罪","verses":[{"n":1,"t":"靈將我舉起，帶我到耶和華聖殿面向東方的東門。看哪，門口有二十五個人。我見其中有百姓的領袖押朔的兒子雅撒尼亞和比拿雅的兒子毗拉提。","notes":[]},{"n":2,"t":"耶和華對我說：「人子啊，他們就是圖謀罪孽，在這城中設計惡謀的人。","notes":[]},{"n":3,"t":"他們說：『蓋房屋的時候尚未臨近；這城是鍋，我們是肉。』","notes":[]},{"n":4,"t":"人子啊，因此你當說預言，說預言攻擊他們。」","notes":[]},{"n":5,"t":"耶和華的靈降在我身上，對我說：「你當說，耶和華如此說：以色列家啊，你們所說的，你們心裏所想的，我都知道。","notes":[]},{"n":6,"t":"你們在這城裏大行屠殺，被殺的人遍滿街道。","notes":[]},{"n":7,"t":"所以主耶和華如此說：你們在城中殺的人是肉，這城是鍋；你們卻要從其中被帶出去。","notes":[]},{"n":8,"t":"你們怕刀劍，我卻要使刀劍臨到你們。這是主耶和華說的。","notes":[]},{"n":9,"t":"我要把你們從這城中帶出去，交在外邦人的手裏，且要在你們中間施行審判。","notes":[]},{"n":10,"t":"你們要仆倒在刀下；我必在以色列的邊界審判你們，你們就知道我是耶和華。","notes":[]},{"n":11,"t":"這城必不作你們的鍋，你們也不作鍋中的肉。我要在以色列的邊界審判你們，","notes":[]},{"n":12,"t":"你們就知道我是耶和華；因為你們不遵行我的律例，也不順從我的典章，卻隨從你們四圍列國的規條。」","notes":[]},{"n":13,"t":"我正說預言的時候，比拿雅的兒子毗拉提死了。於是我臉伏在地，大聲呼叫說：「唉！主耶和華啊，你要把以色列剩餘的人都滅絕淨盡嗎？」","notes":[]},{"n":14,"t":"耶和華的話臨到我，說：","notes":[],"heads":["神對被擄者的應許"]},{"n":15,"t":"「人子啊，耶路撒冷的居民對你的兄弟、你的本家、你的親屬、以色列全家所有的人說：『你們遠離耶和華吧！這地是賜給我們為業的。』","notes":[]},{"n":16,"t":"所以你當說：『主耶和華如此說：我雖將以色列全家遠遠流放到列國，使他們分散在列邦，我卻要在他們所到的列邦，暫時作他們的聖所。』","notes":[]},{"n":17,"t":"你當說：『主耶和華如此說：我必從萬民中召集你們，從分散的列邦中聚集你們，又將以色列地賜給你們。』","notes":[]},{"n":18,"t":"他們到了那裏，必從其中除掉一切可憎之物、可厭的事。","notes":[]},{"n":19,"t":"我要使他們有合一的心，也要將新靈放在你們裏面，又從他們的肉體中除掉石心，賜給他們肉心，","notes":["「你們」：有古卷、七十士譯本和其他古譯本是「他們」。"]},{"n":20,"t":"使他們順從我的律例，謹守遵行我的典章。他們要作我的子民，我要作他們的神。","notes":[]},{"n":21,"t":"至於那些心中隨從可憎之物、可厭的事的人，我必照他們所做的報應在他們頭上。這是主耶和華說的。」","notes":[]},{"n":22,"t":"於是，基路伯展開翅膀，輪子都在他們旁邊；在他們上面有以色列神的榮耀。","notes":[],"heads":["神的榮耀離開耶路撒冷"]},{"n":23,"t":"耶和華的榮耀從城中上升，停在城東的那座山上。","notes":[]},{"n":24,"t":"靈將我舉起，在異象中神的靈將我帶回迦勒底地，到被擄的人那裏；之後我所見的異象就離我上升去了。","notes":[]},{"n":25,"t":"我就把耶和華指示我的一切事都說給被擄的人聽。","notes":[]}]},"12":{"heading":"先知扮演難民","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你住在悖逆之家中；他們有眼可看卻看不見，有耳可聽卻聽不到，因為他們是悖逆之家。","notes":[]},{"n":3,"t":"所以人子啊，你要收拾被擄時需用的物件，白天在他們眼前離去，在他們眼前離開你所住的地方，移到別處去；他們雖是悖逆之家，或者可以領悟。","notes":[]},{"n":4,"t":"你要白天在他們眼前拿出你被擄時需用的物件。到了晚上，要在他們眼前離去，像被擄的人離去一樣。","notes":[]},{"n":5,"t":"你要在他們眼前挖通牆壁，從其中將物件帶出去。","notes":["「從其中...出去」：七十士譯本是「穿過它出去」。"]},{"n":6,"t":"到天黑時，在他們眼前背在肩上帶走，並要蒙住臉看不見地，因為我要使你成為以色列家的預兆。」","notes":["「帶走」：七十士譯本是「出去」；下同。"]},{"n":7,"t":"我就照著所吩咐的去做，白天拿出被擄時需用的物件。到了晚上，用手挖通牆壁；天黑的時候，在他們眼前背在肩上帶走。","notes":[]},{"n":8,"t":"次日早晨，耶和華的話臨到我，說：","notes":[]},{"n":9,"t":"「人子啊，以色列家，就是那悖逆之家，豈不是問你說：『你在做甚麼呢？』","notes":[]},{"n":10,"t":"你要對他們說：『主耶和華如此說：這是關乎耶路撒冷君王和其中以色列全家的默示。』","notes":[]},{"n":11,"t":"你要說：『我是你們的預兆：我怎樣做，他們所遭遇的也必這樣，他們必被擄去，作俘虜。』","notes":[]},{"n":12,"t":"他們中間的君王也必在天黑時把物件背在肩上帶走。他們要挖通牆壁，從其中帶出去。他必蒙住臉，眼看不見地。","notes":["「從其中帶出去」：七十士譯本是「穿過它出去」。"]},{"n":13,"t":"我要把我的網撒在他身上，他就被我的羅網纏住。我要帶他到迦勒底人之地的巴比倫；他沒有看見那地，就死在那裏。","notes":[]},{"n":14,"t":"我要把四圍幫助他的和他所有的軍隊分散到四方，也要拔刀追趕他們。","notes":["「方」：原文是「風」。"]},{"n":15,"t":"我把他們驅逐到列國，分散在列邦的時候，他們就知道我是耶和華。","notes":[]},{"n":16,"t":"我卻要留下他們當中幾個人得免刀劍、饑荒、瘟疫，使他們在所到的列國述說自己所做一切可憎的事；他們就知道我是耶和華。」","notes":[]},{"n":17,"t":"耶和華的話臨到我，說：","notes":[],"heads":["憂慮驚惶的預兆"]},{"n":18,"t":"「人子啊，你吃飯時必戰抖，喝水時必驚惶憂慮。","notes":[]},{"n":19,"t":"你要對這地的百姓說：主耶和華論以色列地的耶路撒冷居民如此說，他們吃飯時必憂慮，喝水時必驚惶，因其中居民所行殘暴的事，這地必然荒廢，一無所存。","notes":[]},{"n":20,"t":"有人居住的城鎮必變為廢墟，地必荒涼；你們就知道我是耶和華。」","notes":[]},{"n":21,"t":"耶和華的話臨到我，說：","notes":[],"heads":["平凡的俗語和非凡的信息"]},{"n":22,"t":"「人子啊，在以色列地你們怎麼有這俗語說：『日子延長，一切異象卻落了空』呢？","notes":[]},{"n":23,"t":"你要告訴他們說：『主耶和華如此說：我必令這俗語止息，以色列中不再有人引用這俗語。』你卻要對他們說：『日子臨近，一切的異象都必應驗。』","notes":[]},{"n":24,"t":"從此以後，以色列家不再有虛假的異象和奉承的占卜。","notes":[]},{"n":25,"t":"我─耶和華說話，所說的必定實現，不再耽延。你們這悖逆之家啊，你們在世的日子，我所說的話必定實現。這是主耶和華說的。」","notes":[]},{"n":26,"t":"耶和華的話臨到我，說：","notes":[]},{"n":27,"t":"「人子，看哪，以色列家的人說：『他所見的異象是許多日子以後的事，所說的預言是指著遙遠的時候。』","notes":[]},{"n":28,"t":"所以你要對他們說：『主耶和華如此說：我的話不再有一句耽延，我所說的話必定實現。』這是主耶和華說的。」","notes":[]}]},"13":{"heading":"斥責假先知","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要說預言，攻擊以色列中說預言的先知，對那些隨心說預言的人說：『你們當聽耶和華的話。』」","notes":[]},{"n":3,"t":"主耶和華如此說：「禍哉！那些愚頑的先知，隨從自己的心意，卻一無所見。","notes":[]},{"n":4,"t":"以色列啊，你的先知好像廢墟中的狐狸，","notes":[]},{"n":5,"t":"沒有上去堵住缺口，也沒有為以色列家重修城牆，使它在耶和華的日子來臨時，可以在戰爭中站得住。","notes":[]},{"n":6,"t":"他們看見的是虛假，是謊詐的占卜，說是耶和華說的；其實耶和華並沒有差遣他們，他們卻指望那話必站立得住。","notes":[]},{"n":7,"t":"你們豈不是見了虛假的異象嗎？豈不是說了謊詐的占卜嗎？你們說，這是耶和華說的，其實我沒有說過。」","notes":[]},{"n":8,"t":"所以主耶和華如此說：「因你們說的是虛假，見的是謊詐，所以，看哪，我要敵對你們。這是主耶和華說的。","notes":[]},{"n":9,"t":"我的手必攻擊那見虛假異象、用謊詐占卜的先知，他們必不列在我百姓的會中，不錄在以色列家的名冊上，也不能進入以色列地；你們就知道我是主耶和華。","notes":[]},{"n":10,"t":"他們誘惑我的百姓，說：『平安！』其實沒有平安，就像有人築牆壁，看哪，他們倒去粉刷它。","notes":[]},{"n":11,"t":"所以你要對那些粉刷的人說：『牆要倒塌，暴雨漫過。你們大冰雹啊，要降下 ，狂風要吹裂這牆。』","notes":["「你們...降下」：七十士譯本是「我要降下大冰雹」。"]},{"n":12,"t":"看哪，這牆倒塌，人豈不是要問你們說：『你們所粉刷的在哪裏呢？』」","notes":[]},{"n":13,"t":"所以主耶和華如此說：「我要發怒，使狂風吹裂它，在怒中令暴雨漫過，又發怒降下大冰雹，毀壞它。","notes":[]},{"n":14,"t":"我要這樣拆毀你們那粉飾的牆，把它夷為平地，以致根基露出；牆一倒塌，你們也要在其中滅亡。你們就知道我是耶和華。","notes":[]},{"n":15,"t":"我要對牆和粉刷它的人發盡我的憤怒，我要對你們說：『牆沒有了！粉刷它的人也沒有了！』","notes":["「我」：原文另譯「他們」。"]},{"n":16,"t":"這就是以色列的先知，他們指著耶路撒冷說預言，見到這城平安的異象，其實沒有平安。這是主耶和華說的。」","notes":[]},{"n":17,"t":"「你，人子啊，要面向你百姓中隨心說預言的婦女們，說預言攻擊她們，","notes":[],"heads":["斥責假的女先知"]},{"n":18,"t":"說，主耶和華如此說：『這些婦女有禍了！她們為眾人的手腕縫驅邪帶，替身材高矮不同的人做頭巾，為要獵取人的性命。難道你們要獵取我百姓的性命，使自己存活嗎？","notes":[]},{"n":19,"t":"你們為幾把大麥、幾塊餅，在我的百姓中褻瀆我，對那肯聽謊言的百姓說謊言，讓不該死的人死，讓不該活的人活。』」","notes":[]},{"n":20,"t":"所以主耶和華如此說：「看哪，我要對付你們那用以獵取人，如獵飛鳥般的驅邪帶。我要把驅邪帶從你們的手腕扯去，釋放那些如飛鳥被你們獵取的人。","notes":[]},{"n":21,"t":"我也必撕裂你們的頭巾，救我百姓脫離你們的手，使他們不再被獵取，落在你們手中；你們就知道我是耶和華。","notes":[]},{"n":22,"t":"我未曾使義人傷心，你們卻以謊話使他傷心，且又堅固惡人的手，不使他回轉離開惡道得以存活。","notes":[]},{"n":23,"t":"所以，你們必不再看見虛假的異象，也不再行占卜的事；我要救我的百姓脫離你們的手；你們就知道我是耶和華。」","notes":[]}]},"14":{"heading":"神斥責拜偶像的罪","verses":[{"n":1,"t":"有幾個以色列的長老到我這裏來，坐在我面前。","notes":[]},{"n":2,"t":"耶和華的話臨到我，說：","notes":[]},{"n":3,"t":"「人子啊，這些人在心中設立偶像，把陷自己於罪的絆腳石放在面前，我真的能讓他們求問嗎？","notes":[]},{"n":4,"t":"所以你要告訴他們，對他們說：『主耶和華如此說：以色列家的人，凡在心中設立偶像，把陷自己於罪的絆腳石放在面前，卻來到先知那裏的，我─耶和華在他所求的事上，必因他拜許多偶像向他施行報應，","notes":["「在他...報應」：原文另譯「必報應那些帶著許多偶像來的人」。"]},{"n":5,"t":"為要奪回以色列家的心，他們全都拜偶像，與我疏遠了。』","notes":[]},{"n":6,"t":"「所以你要對以色列家說：『主耶和華如此說：回轉吧！回轉離開你們的偶像，轉臉離開一切可憎的事。』","notes":[]},{"n":7,"t":"因為以色列家的人，或在以色列中寄居的外人，凡與我隔絕，在心中設立偶像，把陷自己於罪的絆腳石放在面前，卻來到先知那裏，要為自己的事求問我的，我─耶和華必親自報應他。","notes":[]},{"n":8,"t":"我要向那人變臉，使他成為警戒和笑柄，並且我要把他從我民中剪除；你們就知道我是耶和華。","notes":[]},{"n":9,"t":"先知若被騙說了一句預言，是我─耶和華騙了那先知，我要伸手攻擊他，把他從我百姓以色列中除滅。","notes":[]},{"n":10,"t":"他們必擔當自己的罪孽。先知的罪孽和求問之人的罪孽都一樣，","notes":[]},{"n":11,"t":"使以色列家不再走迷離開我，也不再因各樣的罪過玷污自己，卻要作我的子民，我也作他們的神。這是主耶和華說的。」","notes":[]},{"n":12,"t":"耶和華的話臨到我，說：","notes":[],"heads":["挪亞、但以理、約伯"]},{"n":13,"t":"「人子啊，若有一國犯罪干犯我，我也伸手攻擊它，斷絕他們糧食的供應，使饑荒臨到那地，將人與牲畜從其中剪除；","notes":[]},{"n":14,"t":"雖有挪亞、但以理、約伯這三人在那裏，他們只能因自己的義救自己的命。這是主耶和華說的。","notes":[]},{"n":15,"t":"我若使惡獸經過那地，大肆蹂躪，使地荒涼，以致因這些獸，人都不得經過；","notes":[]},{"n":16,"t":"雖有這三人在其中，主耶和華說：我指著我的永生起誓，他們不能救兒子女兒，只有他們自己可以得救，那地仍然荒涼。","notes":[]},{"n":17,"t":"或者我使刀劍臨到那地，說：『讓刀劍穿越那地』，以致我把人與牲畜從其中剪除；","notes":[]},{"n":18,"t":"雖有這三人在其中，主耶和華說：我指著我的永生起誓，他們不能救兒子女兒，只有他們自己可以得救。","notes":[]},{"n":19,"t":"或者我叫瘟疫流行那地，把我的憤怒帶著血傾在其中，好使人與牲畜從其中剪除；","notes":[]},{"n":20,"t":"雖有挪亞、但以理、約伯在那裏，主耶和華說：我指著我的永生起誓，他們不能救兒子女兒，只能因自己的義救自己的命。","notes":[]},{"n":21,"t":"「主耶和華如此說：我若將這四樣大災，就是刀劍、饑荒、惡獸、瘟疫降在耶路撒冷，將人與牲畜從其中剪除，豈不是更嚴重嗎？","notes":[]},{"n":22,"t":"看哪，在那裏必有倖免於難的人帶著兒子女兒；看哪，他們來到你們這裏；你們看見他們的所作所為，就會因我降給耶路撒冷的災禍，因我降給它的一切，得到安慰。","notes":[]},{"n":23,"t":"你們因看見他們的所作所為，得到安慰，就會知道我在耶路撒冷所做的並非毫無緣故。這是主耶和華說的。」","notes":[]}]},"15":{"heading":"葡萄樹的比喻","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，葡萄樹比一切其他的樹，就是樹林裏眾樹木的樹枝，有甚麼長處呢？","notes":[]},{"n":3,"t":"可以從其中取木料來做工嗎？人可以拿來做釘子，掛東西在上面嗎？","notes":[]},{"n":4,"t":"看哪，它已經拋在火中當柴燒，火既燒了兩頭，中間也燒焦了，它還有甚麼用處呢？","notes":[]},{"n":5,"t":"看哪，它完整的時候尚且不能拿來做工，何況被火燒焦了，還能拿來做工嗎？","notes":[]},{"n":6,"t":"所以，主耶和華如此說：我怎樣使林中樹裏的葡萄樹在火中當柴燒，我也必照樣對待耶路撒冷的居民。","notes":[]},{"n":7,"t":"我必向他們變臉；他們雖從火中逃出來，火仍要燒滅他們。我向他們變臉的時候，你們就知道我是耶和華。","notes":[]},{"n":8,"t":"我必使這地荒涼，因為他們做了背叛的事。這是主耶和華說的。」","notes":[]}]},"16":{"heading":"不忠實的耶路撒冷","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要使耶路撒冷知道它那些可憎的事。","notes":[]},{"n":3,"t":"你要說，主耶和華對耶路撒冷如此說：你的根源，你的出身，是在迦南地；你的父親是亞摩利人，母親是赫人。","notes":[]},{"n":4,"t":"論到你出世的景況，在你出生的日子沒有人為你斷臍帶，也沒有用水清洗，使你潔淨；沒有人撒鹽在你身上，也沒有人用布包你。","notes":[]},{"n":5,"t":"沒有人顧惜你，為你做一件這樣的事來可憐你。你卻被扔在田野上面，因你出生的日子就被厭惡。","notes":[]},{"n":6,"t":"「我從你旁邊經過，見你在血中打滾，就對你說：『你雖在血中，卻要活下去！』我又說：『你雖在血中，卻要活下去！』","notes":["「我又說...去」：有些古卷、七十士譯本和其他古譯本沒有本句。"]},{"n":7,"t":"我使你成長如田間所生長的；你就漸長，美而又美，兩乳成形，頭髮秀長，但你仍然赤身露體。","notes":["「美而又美」：原文另譯「成為少女」。"]},{"n":8,"t":"「我從你旁邊經過看見你，看哪，正是你渴慕愛情的時候，我就用我衣服的邊搭在你身上，遮蓋你的赤體；又向你起誓，與你立約，你就歸我。這是主耶和華說的。","notes":[]},{"n":9,"t":"那時我用水洗你，洗淨你身上的血，又用油抹你。","notes":[]},{"n":10,"t":"我使你身穿錦繡衣裳，腳穿海狗皮鞋，用細麻布裹著你，精緻衣料披在你身上。","notes":[]},{"n":11,"t":"我用首飾打扮你：我把手鐲戴在你手上，項鏈在你頸上，","notes":[]},{"n":12,"t":"我也把環子戴在你鼻上，耳環在你耳上，華冠在你頭上。","notes":[]},{"n":13,"t":"這樣，你就有金銀的首飾，穿的是細麻衣和精緻衣料，以及錦繡衣裳；吃的是細麵、蜂蜜和油。你也極其美貌，配登王后之位。","notes":[]},{"n":14,"t":"你美貌的名聲傳到列國，因我加給你榮華，使你完美。這是主耶和華說的。","notes":[]},{"n":15,"t":"「只是你仗著自己美貌，又憑著你的名聲行淫。你向路人縱情淫亂，你的美貌就屬於他的了。","notes":["「你的美貌…他的了」：原文另譯「你就屬於他了」；七十士譯本的一些抄本和其他古譯本沒有本句。"]},{"n":16,"t":"你拿你的衣服為自己做成彩色丘壇，在其上行淫。這樣的事本不該有，以後也不該發生。","notes":[]},{"n":17,"t":"你拿我所賜給你的那些美麗的金銀寶物，為自己製造男性的偶像，與它們行淫；","notes":[]},{"n":18,"t":"你拿你的錦繡衣裳為它們披上，把我的膏油和香料擺在它們面前；","notes":[]},{"n":19,"t":"你把我賜給你的食物，就是我賜給你享用的細麵、油和蜂蜜，都擺在它們面前作為馨香的供物。事情就是這樣。這是主耶和華說的。","notes":[]},{"n":20,"t":"你拿你為我所生的兒女獻給它們吞噬。你的淫亂豈是小事？","notes":[]},{"n":21,"t":"你竟把我的兒女殺了，使他們經火獻給它們！","notes":[]},{"n":22,"t":"你做這一切可憎和淫亂的事，並未追念你幼年的日子，那時你赤身露體，在血中打滾。」","notes":[]},{"n":23,"t":"「你有禍了！你有禍了！這是主耶和華說的。你做這一切惡事之後，","notes":[],"heads":["耶路撒冷像淫婦"]},{"n":24,"t":"又為自己建造土墩，在各廣場上築起高臺。","notes":[]},{"n":25,"t":"你在各個街頭建造高臺，使你的美貌變為可憎；又向所有過路的人招手，多行淫亂。","notes":["「招手」：原文直譯「伸開雙腳」。"]},{"n":26,"t":"你也和你那放縱情慾的鄰邦埃及人行淫，增添你的淫亂，惹我發怒。","notes":[]},{"n":27,"t":"看哪，我伸手攻擊你，減少你的福分，卻將你交給恨惡你的非利士人，讓他們任意待你。他們為你的淫行也感到羞恥。","notes":["「非利士人」：原文直譯「非利士眾女子」；下同。"]},{"n":28,"t":"你尚且不滿意，又與亞述人行淫，但與他們行淫之後，仍不滿足；","notes":[]},{"n":29,"t":"於是你與那稱為貿易之地的迦勒底多行淫亂，即使這樣，你仍不滿足。","notes":[]},{"n":30,"t":"「你的心何等脆弱！這是主耶和華說的。你做這一切事，都是不知羞恥的妓女所做的，","notes":[]},{"n":31,"t":"在各個街頭建造土墩，在各廣場上築高臺；但你藐視行淫的賞金，又不像妓女。","notes":[]},{"n":32,"t":"你這行淫的妻子啊，竟然接外人，替代丈夫。","notes":[]},{"n":33,"t":"凡妓女都是得人贈禮，你反倒餽贈你所愛的人，倒貼他們，使他們從四圍來與你行淫。","notes":[]},{"n":34,"t":"你的淫行與其他婦女相反，不是人要求與你行淫；是你給人賞金，不是人給你賞金；你是相反的。」","notes":[]},{"n":35,"t":"「你這妓女啊，要聽耶和華的話。","notes":[],"heads":["神審判耶路撒冷"]},{"n":36,"t":"主耶和華如此說：因你放縱情慾，露出下體，與你所愛的行淫，因你敬拜一切可憎的偶像，就像自己兒女的血獻給它們，","notes":["「就像」：原文另譯「用」。"]},{"n":37,"t":"所以，看哪，我要聚集所有與你交歡的情人，不論是你所愛的或你所恨的，聚集他們從四圍到你那裏來；我要在他們面前暴露你的下體，使他們看盡你的下體。","notes":[]},{"n":38,"t":"我也要審判你，如審判淫婦和流人血的婦女一樣。我要在憤怒和妒忌中使流血的罪歸到你身上。","notes":[]},{"n":39,"t":"我要把你交在他們手中；他們必拆毀你的土墩，毀壞你的高臺，剝去你的衣服，奪取你美麗的寶物，留下你赤身露體。","notes":[]},{"n":40,"t":"他們必聚集眾人攻擊你，用石頭打死你，用刀劍刺透你，","notes":[]},{"n":41,"t":"用火焚燒你的房屋，在許多婦女眼前審判你。我必使你不再行淫，你也不再給賞金。","notes":[]},{"n":42,"t":"我止息了向你所發的憤怒，我的妒忌也離開了你；這樣，我就平靜，不再惱怒。","notes":[]},{"n":43,"t":"因你不追念幼年的日子，反而在這一切的事上惹我發烈怒，所以，看哪，我必照你所做的報應在你頭上。在你一切可憎的事上，你不是還行了淫亂嗎？這是主耶和華說的。」","notes":[]},{"n":44,"t":"「看哪，凡說俗語的必用這俗語攻擊你，說：『有其母必有其女。』","notes":[],"heads":["有其母必有其女"]},{"n":45,"t":"你實在是你母親的女兒，厭棄丈夫和兒女；你也是你姊妹的姊妹，厭棄丈夫和兒女。你的母親是赫人，父親是亞摩利人。","notes":[]},{"n":46,"t":"你的姊姊是撒瑪利亞，她和她的女兒們住在你北邊；你的妹妹是所多瑪，她和她的女兒們住在你南邊。","notes":[]},{"n":47,"t":"你不只效法她們的行為，照她們可憎的事去做，不消多時，你所做的一切就比她們更惡。","notes":["「不消多時」或譯「還以此為小事」。"]},{"n":48,"t":"主耶和華說：我指著我的永生起誓，你的妹妹所多瑪與她的女兒們並未做你和你女兒們所做的事。","notes":[]},{"n":49,"t":"看哪，你的妹妹所多瑪的罪孽是這樣：她和她的女兒們都驕傲，糧源充足，大享安逸，卻不扶持困苦和貧窮人的手。","notes":[]},{"n":50,"t":"她們狂傲，在我面前做可憎的事，我看見了就把她們除掉。","notes":[]},{"n":51,"t":"撒瑪利亞所犯的罪不及你的一半，你所做可憎的事比她更多；比起你所做這一切可憎的事，你的姊妹倒顯為義。","notes":[]},{"n":52,"t":"你既為你的姊妹辯護，就要擔當自己的羞辱。因你所犯的罪比她們更可憎，她們比你倒顯為義；你既使你的姊妹顯為義，就要抱愧，擔當自己的羞辱。」","notes":[]},{"n":53,"t":"「我必使她們被擄的歸回，使所多瑪和她的女兒們、撒瑪利亞和她的女兒們，並與你一起被擄的都歸回；","notes":[],"heads":["所多瑪、撒瑪利亞的復興"]},{"n":54,"t":"好使你擔當自己的羞辱，為所做的一切抱愧，讓她們得到安慰。","notes":[]},{"n":55,"t":"你的妹妹所多瑪和她的女兒們必回復原狀；撒瑪利亞和她的女兒們必回復原狀；你和你的女兒們也必回復原狀。","notes":[]},{"n":56,"t":"在你驕傲的日子，你的妹妹所多瑪豈不是你口中的笑柄嗎？","notes":[]},{"n":57,"t":"在你的惡行顯露以前，那受了凌辱的亞蘭女兒們和亞蘭四圍非利士的女兒們，都在四圍藐視你。","notes":[]},{"n":58,"t":"耶和華說：你的淫蕩和可憎之事，你自己要擔當。」","notes":[]},{"n":59,"t":"「主耶和華如此說：你這輕看誓言而背約的，我必照你所做的報應你。","notes":[],"heads":["永遠的約"]},{"n":60,"t":"然而我要追念在你幼年時我與你所立的約，也要與你立定永約。","notes":[]},{"n":61,"t":"當你接納你的姊姊和妹妹時，你要追念你所行的，自覺慚愧；並且我要將她們賞給你做女兒，卻不是按著我與你所立的約。","notes":[]},{"n":62,"t":"我要堅定與你所立的約，你就知道我是耶和華，","notes":[]},{"n":63,"t":"使你在我赦免你一切惡行時，心中追念，自覺慚愧，又因羞辱就不再開口。這是主耶和華說的。」","notes":[]}]},"17":{"heading":"大鷹和葡萄樹的比喻","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要向以色列家出謎語，設比喻，","notes":[]},{"n":3,"t":"說，主耶和華如此說：有一隻大鷹，翅膀大，翎毛長，羽毛豐滿，色彩繽紛；牠飛到黎巴嫩，啄去香柏樹梢，","notes":[]},{"n":4,"t":"啄斷它頂端的嫩枝，叼到貿易之地，放在商業城中。","notes":[]},{"n":5,"t":"牠又從這地取了一些種子，種在肥沃的田裏，栽於豐沛的水源旁，如種植柳樹。","notes":[]},{"n":6,"t":"它漸漸生長，成為低矮蔓生的葡萄樹；樹枝伸向那鷹，根部在牠下面。這樣，它就長成了一棵葡萄樹，生出枝子，長出枝幹。","notes":[]},{"n":7,"t":"「有一隻大鷹，翅膀大，羽毛多。看哪，葡萄樹從栽種它的苗圃向這鷹伸出根來，長出枝子，期盼從牠得到澆灌。","notes":["「一隻」：七十士譯本是「另一隻」。"]},{"n":8,"t":"這棵樹栽於肥田豐沛的水源旁，原是為了生枝、結果，成為佳美的葡萄樹。","notes":[]},{"n":9,"t":"你要說，主耶和華如此說：這棵葡萄樹豈能發旺呢？鷹豈不拔出它的根來，摘光它的果子，使它枯乾，連長出的嫩葉都枯萎了嗎？要把它連根拔除，並不需要費大力或動用許多人。","notes":[]},{"n":10,"t":"看哪，葡萄樹雖然栽種了，豈能發旺呢？一經東風擊打，豈不全然枯乾了嗎？它必在生長的苗圃中枯乾了。」","notes":[]},{"n":11,"t":"耶和華的話臨到我，說：","notes":[],"heads":["解釋比喻"]},{"n":12,"t":"「你要對那悖逆之家說：你們不知道這些事是甚麼意思嗎？你要這樣說，看哪，巴比倫王曾到耶路撒冷，把其中的君王和官長帶到巴比倫去，","notes":[]},{"n":13,"t":"又從以色列王室後裔中選取一人，與他立約，令他發誓，又擄走國中有勢力的人，","notes":[]},{"n":14,"t":"使王國衰弱，不再強盛，只能靠守盟約方得生存。","notes":[]},{"n":15,"t":"他卻背叛巴比倫王，差派使者前往埃及，要求埃及人給他馬匹和許多人。他豈能亨通呢？這樣做的人豈能逃脫呢？他背了約豈能逃脫呢？","notes":[]},{"n":16,"t":"主耶和華說：我指著我的永生起誓，他定要死在巴比倫，就是巴比倫王所在之處；因為巴比倫王立他為王，他竟輕看向王所起的誓，背棄王與他所立的約。","notes":[]},{"n":17,"t":"當敵人建土堆，築堡壘，要殲滅許多人時，法老雖有強大軍隊和大批人馬，在戰場上還是不能幫助他。","notes":[]},{"n":18,"t":"他輕看誓言，背棄盟約，看哪，雖已投降，卻又做這一切的事，他必不能逃脫。","notes":["「投降」：原文直譯「伸出他的手」。"]},{"n":19,"t":"所以主耶和華如此說：我指著我的永生起誓，他既輕看我的誓言，背棄我的約，我必使這罪歸到他頭上。","notes":[]},{"n":20,"t":"我要把我的網撒在他身上，他就被我的羅網纏住。我要帶他到巴比倫，在那裏因他背叛我的罪懲罰他。","notes":[]},{"n":21,"t":"所有逃跑的軍隊必倒在刀下；剩餘的也必分散四方。你們就知道說這話的是我─耶和華。」","notes":["「逃跑的」：有些古卷是「精銳的」。","「方」：原文是「風」。"]},{"n":22,"t":"主耶和華如此說：「我要從香柏樹高高的樹梢摘取並栽上，從頂端的嫩枝中折下一嫩枝，栽於極高的山上，","notes":[],"heads":["神對將來的應許"]},{"n":23,"t":"栽在以色列高處的山上。它就生枝、結果，成為高大的香柏樹，各類飛禽中的鳥都來宿在其下，宿在枝子的蔭下。","notes":["「各類飛禽...蔭下」：七十士譯本是「各類動物都來宿在其下，各類飛鳥宿在枝子的蔭下」。"]},{"n":24,"t":"田野的樹木因此就知道是我─耶和華使高樹矮小，使矮樹高大，使綠樹枯乾，使枯樹發旺。我─耶和華說了這話，就必成就。」","notes":[]}]},"18":{"heading":"","verses":[{"n":1,"t":"耶和華的話又臨到我，說：","notes":[]},{"n":2,"t":"「你們在以色列地何以有這俗語，『父親吃了酸葡萄，兒子牙齒就酸倒』呢？","notes":[]},{"n":3,"t":"主耶和華說：我指著我的永生起誓，你們在以色列必不再引用這俗語。","notes":[]},{"n":4,"t":"看哪，所有的生命都是屬我的；父親的生命怎樣屬我，兒子的生命也照樣屬我；然而犯罪的，他必定死。","notes":[]},{"n":5,"t":"「人若是公義，行公平公義的事：","notes":[]},{"n":6,"t":"未曾在山上吃祭物，未曾向以色列家的偶像舉目；未曾污辱鄰舍的妻，也未曾在婦人的經期間親近她；","notes":[]},{"n":7,"t":"未曾虧負人，而是將欠債之人的抵押品還給他；未曾搶奪人的物件，卻把食物給飢餓的人吃，把衣服給赤身的人穿；","notes":[]},{"n":8,"t":"未曾向人取利息，也未曾索取高利，反倒縮手不作惡，在人與人之間施行誠實的判斷；","notes":[]},{"n":9,"t":"遵行我的律例，謹守我的典章，按誠實行事；這人是公義的，必要存活。這是主耶和華說的。","notes":["「按誠實行事」或譯「遵行它」。"]},{"n":10,"t":"「他若生了兒子，兒子作強盜，流人的血，作父親的雖然未犯此過，兒子卻對弟兄行了以上所說的惡，在山上吃祭物，污辱鄰舍的妻；","notes":["「作父親的」：原文是「他」。","有些古譯本沒有「對弟兄」。"],"end":11},{"n":12,"t":"虧負困苦和貧窮的人，搶奪別人的物件，不歸還抵押品，卻向偶像舉目，做可憎的事；","notes":[]},{"n":13,"t":"向人取利息，索取高利，這人豈能存活呢？他不能存活。他因做這一切可憎的事，必要死亡，他的血要歸到自己身上。","notes":[]},{"n":14,"t":"「看哪，他若生了兒子，兒子見父親所犯的一切罪，他見了，卻不照樣去做；","notes":[]},{"n":15,"t":"他未曾在山上吃祭物，未曾向以色列家的偶像舉目，未曾污辱鄰舍的妻；","notes":[]},{"n":16,"t":"也未曾虧負人，未曾取人的抵押品，未曾搶奪人的物件，卻把食物給飢餓的人吃，把衣服給赤身的人穿，","notes":[]},{"n":17,"t":"縮手不害困苦人，未曾向人索取利息或高利；反倒順從我的典章，遵行我的律例；如此，他必不因父親的罪孽死亡，定要存活。","notes":[]},{"n":18,"t":"至於他父親，因為施行欺壓，搶奪弟兄，在百姓中行不善，看哪，他必因自己的罪孽死亡。","notes":[]},{"n":19,"t":"「你們還說：『兒子為甚麼不擔當父親的罪孽呢？』兒子若行公平公義的事，謹守遵行我一切的律例，他必要存活。","notes":[]},{"n":20,"t":"惟有犯罪的，卻必死亡。兒子不擔當父親的罪孽，父親也不擔當兒子的罪孽。義人的善果要歸自己，惡人的惡報也要歸自己。","notes":[]},{"n":21,"t":"「惡人若回轉離開所做的一切罪惡，謹守我的一切律例，行公平公義的事，他必要存活，不致死亡。","notes":[]},{"n":22,"t":"他所犯的一切罪過都不被記念；他因所行的義，必要存活。","notes":[]},{"n":23,"t":"惡人死亡，豈是我所喜悅的呢？我豈不是喜悅他回轉離開所行的道而存活嗎？這是主耶和華說的。","notes":[]},{"n":24,"t":"至於義人，他若轉離義行而作惡，照著惡人所做一切可憎的事去做，豈能存活呢？他所行的一切義都不被記念；反而因所行的惡、所犯的罪死亡。","notes":[]},{"n":25,"t":"「你們卻說：『主的道不公平！』以色列家啊，你們要聽，我的道不公平嗎？你們的道不是不公平嗎？","notes":[]},{"n":26,"t":"義人若轉離義行而作惡，他就因這些惡而死亡。他要死在他所作的惡中。","notes":[]},{"n":27,"t":"惡人若回轉離開所行的惡，行公平公義的事，他必救自己的命；","notes":[]},{"n":28,"t":"因為他省察，回轉離開所犯的一切罪過，他必要存活，不致死亡。","notes":[]},{"n":29,"t":"以色列家還說：『主的道不公平！』以色列家啊，我的道不公平嗎？你們的道不是不公平嗎？","notes":[]},{"n":30,"t":"所以，以色列家啊，我必按你們各人所做的審判你們。當回轉，回轉離開你們一切的罪過，免得罪孽成為你們的絆腳石。這是主耶和華說的。","notes":[]},{"n":31,"t":"你們要把所犯的一切罪過盡行拋棄，為自己造一個新的心和新的靈。以色列家啊，你們為甚麼要死呢？","notes":[]},{"n":32,"t":"我不喜歡有任何人死亡，所以你們當回轉，要存活！這是主耶和華說的。」","notes":[]}]},"19":{"heading":"哀歌","verses":[{"n":1,"t":"你當為以色列的領袖們唱哀歌，","notes":[]},{"n":2,"t":"說：你的母親在獅子中是怎樣的母獅呢？牠蹲伏在少壯獅子中，養育小獅子。","notes":[]},{"n":3,"t":"牠養大了其中一隻小獅子，成了少壯獅子，學會抓食，牠就吃人。","notes":[]},{"n":4,"t":"列國聽見了就把牠逮住在他們的坑裏，用鉤子拉牠到埃及地去。","notes":[]},{"n":5,"t":"母獅見自己等候，期望落空，就從小獅子中取一隻，養為少壯獅子；","notes":["「一隻」：七十士譯本是「另一隻」。"]},{"n":6,"t":"牠在眾獅子中徜徉，長大成為少壯獅子，學會抓食，牠就吃人。","notes":[]},{"n":7,"t":"牠拆毀他們的宮殿，使他們的城鎮變為廢墟；因牠咆哮的聲音，遍地和其中所充滿的都荒廢了。","notes":["「牠拆毀...宮殿」是根據一些古譯本；原文直譯「牠知道他們的寡婦」，意思是「牠與他們的寡婦同寢」。"]},{"n":8,"t":"於是四圍列國從各省前來攻擊牠，把網撒在牠身上，把牠逮住在他們的坑裏。","notes":[]},{"n":9,"t":"他們又用鉤子鉤住牠，把牠放入籠中，帶到巴比倫王那裏，把牠押進城堡，以色列山上就不再聽見牠的聲音。","notes":[]},{"n":10,"t":"你的母親如葡萄樹，在葡萄園中，栽於水邊，因為水多，就多結果子，多生枝子；","notes":["「在葡萄園中」：原文是「在你血中」。"]},{"n":11,"t":"它長出堅固的枝幹，可作統治者的權杖。這枝幹高舉在茂密的樹枝中，可見樹身高大，枝子繁多。","notes":[]},{"n":12,"t":"但在烈怒中它被拔出，摔在地上；東風吹乾其果子，那堅固的枝幹因折斷而枯乾，被火燒燬；","notes":[]},{"n":13,"t":"如今這葡萄樹移植於曠野，在乾旱無水之地，","notes":[]},{"n":14,"t":"火從枝幹中發出，燒滅它的枝條和它的果子，以致不再有堅固的枝幹，可作統治者的權杖。這是哀傷之歌，成為一首哀歌。","notes":["「它的枝條和它的果子」：原文另譯「它的枝條」。"]}]},"20":{"heading":"以色列人的抗命","verses":[{"n":1,"t":"第七年五月初十，有以色列的幾個長老前來求問耶和華，坐在我面前。","notes":[]},{"n":2,"t":"耶和華的話臨到我，說：","notes":[]},{"n":3,"t":"「人子啊，你要告訴以色列的長老，對他們說，主耶和華如此說：你們來是為求問我嗎？主耶和華說：我指著我的永生起誓，我必不讓你們求問。","notes":[]},{"n":4,"t":"人子啊，你要審問他們嗎？你要審問嗎？你當使他們知道他們祖先那些可憎的事；","notes":[]},{"n":5,"t":"你要對他們說，主耶和華如此說：當日我揀選以色列，對雅各家的後裔起誓，在埃及地向他們顯現，起誓說：我是耶和華─你們的神；","notes":[]},{"n":6,"t":"那日我向他們起誓，要領他們出埃及地，到我為他們所找到的流奶與蜜之地，就是全地中最美好之地。","notes":[]},{"n":7,"t":"我對他們說，你們各人要拋棄眼中所喜愛的可憎之物，不可用埃及的偶像玷污自己。我是耶和華─你們的神。","notes":[]},{"n":8,"t":"他們卻悖逆我，不肯聽從我，不拋棄他們眼中所喜愛的可憎之物，離棄埃及的偶像。「我就說，在埃及地，我要把我的憤怒傾倒在他們身上，向他們發盡我的怒氣。","notes":[]},{"n":9,"t":"我這麼做是為了我名的緣故，免得我的名在他們所居住之列國眼中被褻瀆；我曾在這些列國眼前向他們顯現，領他們出了埃及地。","notes":[]},{"n":10,"t":"我領他們出埃及地，帶他們到曠野。","notes":[]},{"n":11,"t":"我將我的律例賜給他們，將我的典章指示他們；人若遵行就必因此存活。","notes":[]},{"n":12,"t":"我將我的安息日賜給他們，在我與他們中間作記號，讓他們知道我─耶和華是使他們分別為聖的。","notes":[]},{"n":13,"t":"以色列家卻在曠野中悖逆我，不順從我的律例，厭棄我的典章；人若遵行就必因此存活。他們卻大大干犯我的安息日。「因此我說，我要在曠野把我的憤怒傾倒在他們身上，滅絕他們。","notes":[]},{"n":14,"t":"我這麼做是為了我名的緣故，免得我的名在列國眼中被褻瀆，因為在這些列國眼前我領了他們出來。","notes":[]},{"n":15,"t":"並且我在曠野向他們起誓，必不領他們進入我所賜的流奶與蜜之地，就是全地中最美好之地；","notes":[]},{"n":16,"t":"因為他們厭棄我的典章，不順從我的律例，干犯我的安息日，他們的心隨從自己的偶像。","notes":[]},{"n":17,"t":"雖然如此，我的眼仍顧惜他們，不毀滅他們，不在曠野把他們滅絕淨盡。","notes":[]},{"n":18,"t":"「我在曠野對他們的兒女說：『不要遵行你們祖先的律例，不要謹守他們的規條，也不要用他們的偶像玷污自己。","notes":[]},{"n":19,"t":"我是耶和華─你們的神，你們要順從我的律例，謹守遵行我的典章，","notes":[]},{"n":20,"t":"且以我的安息日為聖。這日必在我與你們中間作記號，使你們知道我是耶和華─你們的神。』","notes":[]},{"n":21,"t":"只是他們的兒女悖逆我，不順從我的律例，也不謹守遵行我的典章；人若遵行就必因此存活。他們卻干犯我的安息日。「因此我說，我要在曠野把我的憤怒傾倒在他們身上，向他們發盡我的怒氣。","notes":[]},{"n":22,"t":"但我卻縮手而未如此行；我這麼做是為了我名的緣故，免得我的名在列國眼中被褻瀆，因為在這些列國眼前我領了他們出來。","notes":[]},{"n":23,"t":"並且我在曠野向他們起誓，要把他們驅散到列國，分散在列邦；","notes":[]},{"n":24,"t":"因為他們不遵行我的典章，厭棄我的律例，干犯我的安息日，眼目向著他們祖先的偶像。","notes":[]},{"n":25,"t":"我也任他們遵行那無益的律例，隨從那不能使人存活的規條。","notes":[]},{"n":26,"t":"他們使所有頭生的經火，我就任憑他們在這供物上玷污自己；我令他們驚恐，他們就知道我是耶和華。","notes":[]},{"n":27,"t":"「人子啊，你要告訴以色列家，對他們說，主耶和華如此說：你們的祖先在背叛我的事上再次褻瀆了我；","notes":[]},{"n":28,"t":"我領他們到我起誓應許賜給他們的地，他們看見各高岡、各茂密的樹，就在那裏獻祭，獻上惹我發怒的供物，也在那裏焚燒馨香的祭，獻澆酒祭。","notes":[]},{"n":29,"t":"我就對他們說：你們去的那丘壇叫甚麼呢？它名叫巴麻，直到今日。","notes":[]},{"n":30,"t":"所以你要對以色列家說，主耶和華如此說：你們仍要照你們祖先所做的玷污自己嗎？還要照他們可憎的事行淫嗎？","notes":[]},{"n":31,"t":"當你們獻上供物，使你們兒子經火的時候，你們仍用各樣的偶像玷污自己，直到今日。以色列家啊，我豈能讓你們求問呢？主耶和華說：我指著我的永生起誓，我必不讓你們求問。","notes":[]},{"n":32,"t":"「你們說：『我們要像列國和列邦的宗族一樣，去事奉木頭與石頭。』你們所起的心意萬不能成就。」","notes":[]},{"n":33,"t":"「主耶和華說：我指著我的永生起誓，我要作王，用大能的手和伸出的膀臂，並傾倒出來的憤怒治理你們。","notes":[],"heads":["神的懲罰和赦免"]},{"n":34,"t":"我必用大能的手和伸出的膀臂，並傾倒出來的憤怒，把你們從萬民中領出來，從被趕散到的列邦聚集你們。","notes":[]},{"n":35,"t":"我必帶你們到萬民的曠野，在那裏當面審判你們。","notes":[]},{"n":36,"t":"我怎樣在埃及地的曠野審判你們的祖先，也必照樣審判你們。這是主耶和華說的。","notes":[]},{"n":37,"t":"我要使你們從杖下經過，按著約的拘束帶領你們。","notes":["「約的拘束」：七十士譯本是「數目」。"]},{"n":38,"t":"我必從你們中間除盡叛逆和得罪我的人；我將他們從所寄居的地方領出來，他們卻不得進入以色列地，你們就知道我是耶和華。","notes":[]},{"n":39,"t":"「你們，以色列家啊，主耶和華如此說：你們若不聽從我，從今以後就讓各人去事奉他的偶像吧，只是不可再以你們的供物和偶像褻瀆我的聖名。","notes":[]},{"n":40,"t":"「在我的聖山，就是以色列高處的山，以色列全家，那地所有的人，都要在那裏事奉我。在那裏我悅納他們，並要你們獻供物和初熟的土產，以及一切的聖物。這是主耶和華說的。","notes":[]},{"n":41,"t":"我把你們從萬民中領出來，從被趕散到的列邦聚集你們，那時我必悅納你們如同悅納馨香之祭，我要在列國眼前，在你們中間顯為聖。","notes":[]},{"n":42,"t":"我領你們進入以色列地，就是我起誓應許賜給你們列祖之地，那時你們就知道我是耶和華。","notes":[]},{"n":43,"t":"你們在那裏要追念那玷污自己的所作所為，又要因所行的一切惡事厭惡自己。","notes":[]},{"n":44,"t":"以色列家啊，我為我名的緣故，沒有照著你們的惡行和你們的敗壞對待你們；你們就知道我是耶和華。這是主耶和華說的。」","notes":[]},{"n":45,"t":"耶和華的話臨到我，說：","notes":[],"heads":["尼革夫大火"]},{"n":46,"t":"「人子啊，你要面向南方，向南方傳講，向尼革夫田野的樹林說預言。","notes":["「傳講」：原文是「滴下」；21．2同。","「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」；下同。"]},{"n":47,"t":"你要對尼革夫的樹林說，要聽耶和華的話。主耶和華如此說：看哪，我要在你那裏點火，燒滅你們中間所有的綠樹和枯樹，猛烈的火焰必不熄滅；從南到北，人的臉都被燒焦。","notes":[]},{"n":48,"t":"凡血肉之軀都知道是我─耶和華點了火，這火必不熄滅。」","notes":[]},{"n":49,"t":"於是我說：「唉！主耶和華啊，人都指著我說：他不是說比喻的人嗎？」","notes":[]}]},"21":{"heading":"耶和華的刀","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，把你的臉正對著耶路撒冷，對著聖所傳講 ，向以色列地說預言。","notes":["「聖所」：有古卷和七十士譯本是「他們的聖所」；原文另譯「她的聖所」。"]},{"n":3,"t":"你要向以色列地說，耶和華如此說：看哪，我與你為敵，拔刀出鞘，把義人和惡人從你中間剪除。","notes":[]},{"n":4,"t":"因為我要剪除你當中的義人和惡人，所以我的刀要出鞘，從南到北攻擊所有的血肉之軀；","notes":[]},{"n":5,"t":"凡血肉之軀都知道我─耶和華已拔刀出鞘，刀必不再入鞘。","notes":[]},{"n":6,"t":"你，人子啊，要嘆息，在他們眼前斷了腰，愁苦地嘆息。","notes":[]},{"n":7,"t":"若有人對你說：『你為甚麼嘆息呢？』你就說：『因為有風聲傳來，人心惶惶，雙手發軟，精神衰敗，膝弱如水。看哪，它臨近了，一定會發生。』這是主耶和華說的。」","notes":[]},{"n":8,"t":"耶和華的話臨到我，說：","notes":[]},{"n":9,"t":"「人子啊，你要預言說，耶和華如此吩咐，你要說：有刀，刀已磨快，又擦亮了；","notes":[]},{"n":10,"t":"磨快為要大大殺戮，擦亮為要像閃電。我們豈能快樂呢？它藐視我兒的權杖和一切的木頭。","notes":["「我們豈能快樂呢？」原文另譯「啊！它在炫耀。」","「它藐視...木頭」或譯「我兒的權杖藐視一切的木頭」。"]},{"n":11,"t":"它已經交給人擦亮，可以掌握使用；這刀已經磨快擦亮，好交在行殺戮的人手中。","notes":[]},{"n":12,"t":"人子啊，你要呼喊哀號，因為這刀將臨到我的百姓，臨到以色列所有的領袖身上。他們和我的百姓都要交在刀下，所以你要捶胸。","notes":["「捶胸」：原文直譯「拍腿」，表示苦惱和悲傷。"]},{"n":13,"t":"因為這是一個考驗，若它藐視權杖，也不算一回事，又怎麼樣呢？這是主耶和華說的。」","notes":[]},{"n":14,"t":"「人子啊，你要拍掌預言，使這刀三番兩次臨到；這是致人死傷的刀，就是包圍人，使人大受死傷的刀。","notes":[]},{"n":15,"t":"我設立這恐嚇的刀，攻擊他們一切的城門，為要使他們的心驚慌害怕，許多人因而跌倒。唉！它造得像閃電，磨得尖利，要行殺戮。","notes":["「恐嚇」：七十士譯本是「屠宰」。","「它」：原文另譯「這恐嚇的刀」。","「磨得尖利」：原文是「收入鞘內」。"]},{"n":16,"t":"刀啊，要行動一致，向右邊，或指向左邊；面向哪方，就向哪方。","notes":["「要行動一致」：七十士譯本是「要把自己磨得尖利」。"]},{"n":17,"t":"我也要拍掌，使我的憤怒平息。這是我─耶和華說的。」","notes":[]},{"n":18,"t":"耶和華的話臨到我，說：","notes":[],"heads":["巴比倫王的刀"]},{"n":19,"t":"「人子啊，你要畫定兩條路線，使巴比倫王的刀過來，這兩條路必從同一地分出來；要在通往城裏的路口畫手作指標。","notes":[]},{"n":20,"t":"你要劃定一條路，使刀來到亞捫人的拉巴，來到猶大，在堅固城耶路撒冷。","notes":[]},{"n":21,"t":"因為巴比倫王站在岔路上，在兩條路口占卜。他搖籤求問神像，察看肝臟；","notes":["「籤」：原文是「箭」。"]},{"n":22,"t":"右手是耶路撒冷的占卜，以便安設撞城槌，張口喊殺，揚聲呼叫，建土堆，築堡壘，以撞城槌攻打城門。","notes":["「喊殺」：七十士譯本是「大喊」。"]},{"n":23,"t":"在那些曾鄭重起誓的猶大人眼中，這是虛假的占卜；但巴比倫王要使他們想起自己的罪孽，以便俘擄他們。」","notes":[]},{"n":24,"t":"於是，主耶和華如此說：「因你們的過犯顯露，你們的罪孽被記得，以致你們的罪惡在你們一切的行為上都彰顯出來；你們既被記得，就被擄在掌中。","notes":[]},{"n":25,"t":"你這褻瀆行惡的以色列王啊，你的日子，最後懲罰的時刻已來臨。","notes":[]},{"n":26,"t":"主耶和華如此說：當除掉榮冕，摘下華冠，景況已不復從前；要使卑者升為高，使高者降為卑。","notes":[]},{"n":27,"t":"我要將這國傾覆，傾覆，再傾覆；這國必不存在，直等到那應得的人來到，我就將國賜給他。」","notes":[]},{"n":28,"t":"「人子啊，你要說預言；你要說，論到亞捫人和他們的凌辱，主耶和華吩咐我如此說：有刀，拔出來的刀，已經擦亮，為了行殺戮；它亮如閃電以行吞滅。","notes":[],"heads":["刀和亞捫人"]},{"n":29,"t":"他們為你見虛假的異象，行謊詐的占卜，使你倒在褻瀆之惡人的頸項上；他們的日子，最後懲罰的時刻已來臨。","notes":[]},{"n":30,"t":"你收刀入鞘吧！我要在你受造之處、生長之地懲罰你。","notes":[]},{"n":31,"t":"我要把我的憤怒傾倒在你身上，把我烈怒的火噴在你身上；又將你交在善於殺滅、畜牲一般的人手中。","notes":[]},{"n":32,"t":"你要成為火中之柴，你的血必在地裏；你必不再被記得，因為這是我─耶和華說的。」","notes":[]}]},"22":{"heading":"耶路撒冷的過犯","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「你，人子啊，你要審問，審問這流人血的城嗎？要使它知道它一切可憎的事。","notes":[]},{"n":3,"t":"你要說，主耶和華如此說：那在其中流人血的城啊，它的時刻已到，它製造偶像玷污了自己。","notes":[]},{"n":4,"t":"你因流了人的血，算為有罪；因所製造的偶像，玷污自己；你使你的日子臨近，你的年數已來到。所以我使你承受列國的凌辱和列邦的譏誚。","notes":["「你的年數已來到」：七十士譯本是「使你的年數來到」。"]},{"n":5,"t":"你這惡名昭彰、混亂的城啊，離你或遠或近的國家都必譏誚你。","notes":[]},{"n":6,"t":"「看哪，以色列的領袖在你那裏，為了流人的血各逞其能。","notes":[]},{"n":7,"t":"你那裏有輕慢父母的，在你當中有欺壓寄居者的，你那裏也有虧負孤兒寡婦的。","notes":[]},{"n":8,"t":"你藐視我的聖物，干犯我的安息日。","notes":[]},{"n":9,"t":"你那裏有為流人血而毀謗人的，你那裏有在山上吃祭物的，在你當中也有行淫亂的，","notes":[]},{"n":10,"t":"有露父親下體的，有玷辱經期中不潔淨之婦人的。","notes":["「有露父親下體的」：參利18．8。"]},{"n":11,"t":"這人與鄰舍的妻子行可憎的事，那人行淫污辱媳婦，在你那裏還有人污辱他的姊妹，父親的女兒。","notes":[]},{"n":12,"t":"你那裏有收取報酬而流人血的。你取利息，又索取高利；欺壓鄰舍，奪取財物；你竟然忘了我。這是主耶和華說的。","notes":[]},{"n":13,"t":"「看哪，我因你所得不義之財和你們中間所流的血，就擊打手掌。","notes":[]},{"n":14,"t":"到了我對付你的日子，你的心豈能忍受呢？你的手還能有力嗎？我─耶和華說了這話，就必成就。","notes":[]},{"n":15,"t":"我要把你驅散到列國，分散在列邦。我也必除掉你們中間的污穢。","notes":[]},{"n":16,"t":"你在列國眼前因自己所做的被侮辱，你就知道我是耶和華。」","notes":["「你...被侮辱」：七十士譯本和其他古譯本是「我在列國眼前因你而受褻瀆」。"]},{"n":17,"t":"耶和華的話臨到我，說：","notes":[],"heads":["神的大煉爐"]},{"n":18,"t":"「人子啊，我看以色列家為渣滓。他們是爐中的銅、錫、鐵、鉛，是煉銀的渣滓。","notes":["「他們是...渣滓」：原文另譯「他們是銀、銅、錫、鐵、鉛，是爐中的渣滓」。"]},{"n":19,"t":"所以主耶和華如此說：因你們全都成為渣滓，所以，看哪，我必將你們聚集在耶路撒冷中。","notes":[]},{"n":20,"t":"人怎樣把銀、銅、鐵、鉛、錫聚在爐中，吹火使它鎔化；照樣，我也要在我的怒氣和憤怒中聚集你們，把你們安置在城中，使你們鎔化。","notes":[]},{"n":21,"t":"我必聚集你們，把我烈怒的火吹在你們身上，你們就在其中鎔化。","notes":[]},{"n":22,"t":"銀子怎樣在爐中鎔化，你們也必照樣在城中鎔化，因此就知道是我─耶和華把憤怒傾倒在你們身上。」","notes":[]},{"n":23,"t":"耶和華的話臨到我，說：","notes":[],"heads":["以色列領袖們的罪惡"]},{"n":24,"t":"「人子啊，你要向這地說：你是未被潔淨之地，在我盛怒的日子，沒有雨水在其上。","notes":["「被潔淨」：七十士譯本是「被雨浸透」。"]},{"n":25,"t":"其中的先知同謀背叛，如咆哮的獅子抓撕掠物。他們吞滅人命，搶奪財寶，使這地寡婦增多。","notes":["「其中的先知同謀背叛」：七十士譯本是「它其中的領袖」。"]},{"n":26,"t":"其中的祭司曲解我的律法，褻瀆我的聖物，不分別聖與俗，也不使人分辨潔淨和不潔淨，又遮眼不顧我的安息日；在他們中間連我也被褻慢了。","notes":[]},{"n":27,"t":"其中的領袖彷彿野狼抓撕掠物，流人的血，傷害人命，為得不義之財。","notes":[]},{"n":28,"t":"其中的先知為他們粉刷，見虛假的異象，行謊詐的占卜，說：『主耶和華如此說』，其實耶和華並沒有說。","notes":[]},{"n":29,"t":"這地的百姓慣行欺壓搶奪之事，虧負困苦和貧窮的人，欺壓寄居者，沒有公平。","notes":[]},{"n":30,"t":"我在他們中間尋找一人重修城牆，在我面前為這地站在缺口上，使我不致滅絕它，卻連一個也找不著。","notes":[]},{"n":31,"t":"所以我把憤怒傾倒在他們身上，用烈怒之火消滅他們，照他們所做的報應在他們頭上。這是主耶和華說的。」","notes":[]}]},"23":{"heading":"兩個犯罪的姊妹","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，有兩個女子，是一母所生，","notes":[]},{"n":3,"t":"她們在埃及行淫，年少時就開始行淫；在那裏任人擁抱胸懷，撫弄她們少女的乳房。","notes":[]},{"n":4,"t":"她們的名字，大的叫阿荷拉，妹妹叫阿荷利巴。她們都歸於我，生了兒女。論到她們的名字，阿荷拉是撒瑪利亞，阿荷利巴是耶路撒冷。","notes":[]},{"n":5,"t":"「阿荷拉歸我之後卻仍行淫，戀慕所愛的人，就是亞述人，都是戰士，","notes":["「戰士」或譯「鄰邦」；下同。"]},{"n":6,"t":"穿著藍衣，作省長、副省長，全都是俊美的年輕人，騎著馬的騎士。","notes":[]},{"n":7,"t":"阿荷拉與亞述人中所有的美男子放縱淫行，她因拜所戀慕之人的一切偶像，玷污了自己。","notes":[]},{"n":8,"t":"她從埃及的時候，就沒有離開過淫亂；因為她年輕時，有人與她同寢，撫弄她少女的乳房，和她縱慾行淫。","notes":[]},{"n":9,"t":"因此，我把她交在她所愛的人手中，就是她所戀慕的亞述人手中。","notes":[]},{"n":10,"t":"他們暴露她的下體，擄掠她的兒女，用刀殺了她；他們向她施行審判，使她在婦女中留下臭名。","notes":[]},{"n":11,"t":"「她妹妹阿荷利巴雖然看見了，卻還是縱慾，比姊姊更加腐敗，行淫亂比姊姊更甚。","notes":[]},{"n":12,"t":"她戀慕亞述人，就是省長和副省長，披掛整齊的戰士，騎著馬的騎士，全都是俊美的年輕人。","notes":[]},{"n":13,"t":"我看見她被污辱，姊妹二人同行一路。","notes":[]},{"n":14,"t":"阿荷利巴又加增淫行，她看見牆上刻有人像，就是鮮紅色的迦勒底人雕刻的像。","notes":[]},{"n":15,"t":"它們腰間繫著帶子，頭上有飄揚的裹頭巾，都是將軍的樣子，巴比倫人的形像；迦勒底是他們的出生地。","notes":[]},{"n":16,"t":"阿荷利巴一看見就戀慕他們，派遣使者往迦勒底他們那裏去。","notes":[]},{"n":17,"t":"巴比倫人來到她那裏，上了她愛情的床，與她行淫污辱她。她被污辱，隨後她的心卻與他們生疏。","notes":[]},{"n":18,"t":"這樣，她既暴露淫行，暴露下體；我的心就與她生疏，像先前與她的姊姊生疏一樣。","notes":[]},{"n":19,"t":"她仍繼續增添淫行，追念她年輕時在埃及地行淫的日子，","notes":[]},{"n":20,"t":"戀慕情人的身壯精足，如驢似馬。","notes":[]},{"n":21,"t":"這樣，你就渴望年輕時的淫蕩；那時，埃及人因你年輕時的胸懷，撫弄你的乳房。」","notes":["「因你...乳房」：原文另譯「撫弄你的乳房，撫摸你的胸懷」。"]},{"n":22,"t":"阿荷利巴啊，主耶和華如此說：「看哪，我要激起先前你喜愛，而後生疏的人前來攻擊你。我必使他們前來，在你四圍攻擊你；","notes":[],"heads":["神審判妹妹"]},{"n":23,"t":"有巴比倫人、迦勒底眾人、比割人、書亞人、哥亞人，還有亞述眾人與他們一起，都是俊美的年輕人。他們是省長、副省長、將軍、有名聲的，全都騎著馬。","notes":[]},{"n":24,"t":"他們用兵器、戰車、輜重車，率領大軍前來攻擊你。他們要拿大小盾牌，戴著頭盔，在你四圍擺陣攻擊你。我要把審判交給他們，他們必按著自己的規條審判你。","notes":["「用兵器、」：原文另譯「配備」；七十士譯本是「從北方用」。"]},{"n":25,"t":"我要向你傾洩我的妒忌，使他們以憤怒對待你。他們必割去你的鼻子和耳朵，你剩餘的人必倒在刀下。他們必擄去你的兒女，你所剩餘的必被火焚燒。","notes":[]},{"n":26,"t":"他們必剝去你的衣服，奪取你美麗的寶物。","notes":[]},{"n":27,"t":"這樣，我必止息你的淫行和你從埃及地就開始犯的淫亂，使你不再仰望亞述，也不再追念埃及。","notes":[]},{"n":28,"t":"主耶和華如此說：看哪，我必把你交在你所恨惡的人手中，就是你心與他生疏的人手中。","notes":[]},{"n":29,"t":"他們要以恨惡對待你，奪取你勞碌得來的一切，留下你赤身露體。你淫亂的下體，連你的淫行和淫蕩，都必顯露。","notes":[]},{"n":30,"t":"人必向你行這些事；因為你隨從外邦人行淫，用他們的偶像玷污自己。","notes":[]},{"n":31,"t":"你走了你姊姊的路，所以我必把她的杯交在你的手中。」","notes":[]},{"n":32,"t":"主耶和華如此說：「你必喝你姊姊的杯，那杯又深又廣，盛得很多，使你遭受嗤笑譏刺。","notes":[]},{"n":33,"t":"你必酩酊大醉，滿有愁苦。你姊姊撒瑪利亞的杯，驚駭和淒涼的杯，","notes":[]},{"n":34,"t":"你必喝它，並且喝乾。甚至咀嚼杯片，撕裂自己的胸脯；因為我曾說過。這是主耶和華說的。」","notes":[]},{"n":35,"t":"主耶和華如此說：「因你忘記我，將我丟在背後，所以你要擔當你的淫行和淫蕩。」","notes":[]},{"n":36,"t":"耶和華對我說：「人子啊，你要審問阿荷拉與阿荷利巴嗎？要指出她們所做可憎的事。","notes":[],"heads":["神審判兩姊妹"]},{"n":37,"t":"她們行姦淫，手中有血。她們與偶像行姦淫，使她們為我所生的兒女經火，給它們當食物。","notes":[]},{"n":38,"t":"此外，她們還向我這樣做：同一天又玷污我的聖所，干犯我的安息日。","notes":[]},{"n":39,"t":"她們殺了兒女獻給偶像，當天又進入我的聖所，褻瀆了它。看哪，這就是她們在我殿中所做的。","notes":[]},{"n":40,"t":"「況且你們兩姊妹派人從遠方召人來。使者到了他們那裏，看哪，他們就來了。為了他們，你們沐浴，畫眼影，佩戴首飾，","notes":[]},{"n":41,"t":"坐在華美的床上，前面擺設桌子，把我的香料和膏油放在其上。","notes":[]},{"n":42,"t":"在那裏有一群人歡樂的聲音；有許多的平民，從曠野來的醉漢，把鐲子戴在她們手上，把華冠戴在她們頭上。","notes":["「醉漢」：原文另譯「西巴人」；七十士譯本的一些抄本是「男子」。"]},{"n":43,"t":"「我論到這久行姦淫而色衰的婦人說：現在人們還要與她行淫，她也要與人行淫。","notes":[]},{"n":44,"t":"人去到阿荷拉和阿荷利巴二淫婦那裏，好像與妓女行淫。","notes":["「人...那裏」：七十士譯本是「人與阿荷拉及阿荷利巴行淫」。"]},{"n":45,"t":"義人必按照審判淫婦和流人血之婦人的規條，審判她們；因為她們是淫婦，她們的手中有血。」","notes":[]},{"n":46,"t":"主耶和華如此說：「我要讓軍隊上來攻擊她們，使她們驚駭，成為擄物。","notes":[]},{"n":47,"t":"這軍隊必用石頭打死她們，用刀劍殺害她們，又殺戮她們的兒女，用火焚燒她們的房屋。","notes":[]},{"n":48,"t":"我必使這地不再有淫行，所有的婦女都受警戒，不再效法你們的淫行。","notes":["「你們的淫行」：七十士譯本是「她們的淫行」。"]},{"n":49,"t":"人必因你們的淫行報應你們；你們要擔當拜偶像的罪，因此你們就知道我是主耶和華。」","notes":[]}]},"24":{"heading":"生銹的鍋","verses":[{"n":1,"t":"第九年十月初十，耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要記錄這一天的名稱，這特別的一天，巴比倫王圍困耶路撒冷，就在這特別的一天。","notes":[]},{"n":3,"t":"你要向這悖逆之家設比喻，對他們說，主耶和華如此說：把鍋放在火上，放好了，倒水在其中；","notes":[]},{"n":4,"t":"要將肉塊，一切肥美的肉塊，腿和肩都放在鍋裏，要裝滿上等的骨頭；","notes":[]},{"n":5,"t":"要取羊群中最好的，把柴堆在下面，把它煮開，骨頭煮在其中。","notes":["「柴」：原文是「骨頭」。"]},{"n":6,"t":"「主耶和華如此說：禍哉！這流人血的城，就是長銹的鍋。它的銹未曾除掉，要將肉塊從其中一一取出，不必抽籤。","notes":[]},{"n":7,"t":"這城所流的血還在城中，血倒在光滑的磐石上，沒有倒在地上，用土掩蓋；","notes":[]},{"n":8,"t":"是我使這城所流的血倒在光滑的磐石上，不得掩蓋，為要惹動憤怒，施行報應。","notes":[]},{"n":9,"t":"所以主耶和華如此說：禍哉！這流人血的城，我必親自加大柴堆。","notes":[]},{"n":10,"t":"你要添上木柴，使火著旺，將肉煮爛，加上香料，烤焦骨頭；","notes":["「加上香料」：原文另譯「把湯倒出」；七十士譯本是「把湯熬濃」。"]},{"n":11,"t":"你要把空鍋放在炭火上，將鍋燒熱，把銅燒紅，鎔化其中的污穢，除淨其上的銹。","notes":[]},{"n":12,"t":"然而這一切勞碌無效，它厚厚的銹，即使用火也除不掉。","notes":["「然而...無效」：原文另譯「我的勞碌無效」；七十士譯本沒有本句。"]},{"n":13,"t":"雖然我想潔淨你污穢的淫行，你卻不潔淨，你的污穢再也不能潔淨，直等我止息了向你發的憤怒。","notes":[]},{"n":14,"t":"我─耶和華說了這話，時候到了，就必成就；必不退縮，不顧惜，也不憐憫。人必照你的所作所為審判你。這是主耶和華說的。」","notes":[]},{"n":15,"t":"耶和華的話臨到我，說：","notes":[],"heads":["先知妻子的死"]},{"n":16,"t":"「人子，看哪，我要以災病奪取你眼中所喜愛的，你卻不可悲哀哭泣，也不可流淚，","notes":[]},{"n":17,"t":"只可嘆息，不可出聲，不可辦理喪事；裹上頭巾，腳上穿鞋，不可摀著鬍鬚，也不可吃一般人的食物。」","notes":["「一般人的食物」：原文另譯「弔喪的食物」；下同。"]},{"n":18,"t":"到了早晨我把這事告訴百姓，晚上我的妻子就死了。次日早晨我就遵命而行。","notes":[]},{"n":19,"t":"百姓對我說：「你這樣做跟我們有甚麼關係，你不告訴我們嗎？」","notes":[]},{"n":20,"t":"我對他們說：「耶和華的話臨到我，說：","notes":[]},{"n":21,"t":"『你告訴以色列家，主耶和華如此說：我要使我的聖所被褻瀆，就是你們憑勢力所誇耀、眼裏所喜愛、心中所愛惜的；並且你們所遺留的兒女必倒在刀下。","notes":[]},{"n":22,"t":"那時，你們要照我所做的去做。你們不可摀著鬍鬚，也不可吃一般人的食物。","notes":[]},{"n":23,"t":"你們頭要裹上頭巾，腳要穿上鞋；不可悲哀哭泣。你們必因自己的罪孽衰殘，相對嘆息。","notes":[]},{"n":24,"t":"以西結必這樣成為你們的預兆；凡他所做的，你們也必照樣做。那事來到，你們就知道我是主耶和華。』」","notes":[]},{"n":25,"t":"「你，人子啊，那日當我除掉他們所倚靠的保障、所歡喜的榮耀，並眼中所喜愛的，心裏所重看的兒女時，","notes":[]},{"n":26,"t":"逃脫的人豈不來到你這裏，使你耳聞這事嗎？","notes":[]},{"n":27,"t":"那日你要向逃脫的人開口說話，不再啞口無言。你必這樣成為他們的預兆，他們就知道我是耶和華。」","notes":[]}]},"25":{"heading":"預言亞捫受懲罰","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要面向亞捫人說預言，攻擊他們。","notes":[]},{"n":3,"t":"你要對亞捫人說，當聽主耶和華的話。主耶和華如此說：我的聖所遭褻瀆，以色列地變荒涼，猶大家被擄掠；那時，你因這些事說『啊哈』，","notes":[]},{"n":4,"t":"所以，看哪，我要把你交給東方人為業；他們必在你中間安營居住，設立居所，吃你的果子，喝你的奶。","notes":[]},{"n":5,"t":"我必使拉巴成為牧放駱駝之地，使亞捫成為羊群躺臥之處，你們就知道我是耶和華。","notes":[]},{"n":6,"t":"主耶和華如此說：因你們拍手頓足，幸災樂禍，藐視以色列地，","notes":[]},{"n":7,"t":"所以，看哪，我要伸手攻擊你，把你交給列國作為擄物。我必從萬民中剪除你，從列邦中消滅你。我必除滅你，你就知道我是耶和華。」","notes":[]},{"n":8,"t":"「主耶和華如此說：因摩押和西珥人說『看哪，猶大家與列國無異』，","notes":[],"heads":["斥責摩押"]},{"n":9,"t":"所以，看哪，我要破開摩押邊界的城鎮，就是摩押人所誇耀的城鎮，伯‧耶施末、巴力‧免、基列亭，","notes":[]},{"n":10,"t":"令東方人前來攻擊亞捫人。我必將亞捫交給他們為業，使亞捫人在列國中不再被記念。","notes":[]},{"n":11,"t":"我也必向摩押施行審判，他們就知道我是耶和華。」","notes":[]},{"n":12,"t":"「主耶和華如此說：因為以東向猶大家報仇，因向他們報仇而大大顯為有罪，","notes":[],"heads":["斥責以東"]},{"n":13,"t":"所以主耶和華如此說：我要伸手攻擊以東，將人與牲畜剪除，使以東從提幔起，直到底但，地變荒涼，人也都倒在刀下。","notes":[]},{"n":14,"t":"我要藉我子民以色列的手報復以東；他們必照我的怒氣，按我的憤怒對待以東，以東人就知道施報的是我。這是主耶和華說的。」","notes":[]},{"n":15,"t":"「主耶和華如此說：因非利士人報仇，就是心存輕蔑報仇；他們永懷仇恨，意圖毀滅，","notes":[],"heads":["斥責非利士"]},{"n":16,"t":"所以主耶和華如此說：看哪，我要伸手攻擊非利士人，剪除基利提人，滅絕沿海剩餘的居民。","notes":[]},{"n":17,"t":"我要大大報復他們，發怒斥責他們。我報復他們的時候，他們就知道我是耶和華。」","notes":[]}]},"26":{"heading":"斥責推羅","verses":[{"n":1,"t":"第十一年某月初一，耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，因推羅向耶路撒冷說：『啊哈！那眾民之門已經破壞，向我敞開；它既變為廢墟，我必豐盛。』","notes":[]},{"n":3,"t":"所以，主耶和華如此說：推羅，看哪，我與你為敵，使許多國家湧上攻擊你，如同海洋使波浪湧上一樣。","notes":[]},{"n":4,"t":"他們要破壞推羅的城牆，拆毀它的城樓。我也要刮淨它的塵土，使它成為光滑的磐石。","notes":[]},{"n":5,"t":"推羅必成為海中的曬網場，因為我曾說過， 這是主耶和華說的。它必成為列國的擄物，","notes":[]},{"n":6,"t":"推羅鄉間鄰近的城鎮必遭刀劍滅絕，他們就知道我是耶和華。」","notes":["「鄰近的城鎮」：原文直譯「眾女子」；下同。"]},{"n":7,"t":"主耶和華如此說：「看哪，我必使諸王之王，就是巴比倫王尼布甲尼撒，率領馬匹、戰車、騎兵、軍隊和許多人從北方來攻擊推羅。","notes":[]},{"n":8,"t":"他必用刀劍殺滅你鄉間鄰近的城鎮，也必築堡壘，建土堆，舉盾牌攻擊你。","notes":[]},{"n":9,"t":"他要安設撞城槌攻破你的城牆，以刀劍拆毀你的城樓。","notes":[]},{"n":10,"t":"因他馬匹眾多，塵土必揚起遮蔽你。他進入你的城門，如同進入已有缺口之城。那時，你的城牆必因騎兵、車輪和戰車的響聲震動。","notes":[]},{"n":11,"t":"他的馬蹄必踐踏你所有的街道；他必用刀劍殺戮你的居民。你堅固的柱子必倒在地上。","notes":["「柱子」或譯「柱像」。"]},{"n":12,"t":"人必擄獲你的財寶，掠奪你的貨財；他們要破壞你的城牆，拆毀你華美的房屋，將你的石頭、木頭、塵土都拋在水中。","notes":[]},{"n":13,"t":"我要使你唱歌的聲音止息；人不再聽見你彈琴的聲音。","notes":[]},{"n":14,"t":"我必使你成為光滑的磐石，作曬網的場所。你不得再被建造，因為我─耶和華已這樣說了。這是主耶和華說的。」","notes":[]},{"n":15,"t":"主耶和華對推羅如此說：「在你中間行殺戮，受傷的人唉哼時，海島豈不都因你傾倒的響聲震動嗎？","notes":[]},{"n":16,"t":"那時沿海的君王都要從寶座下來，除去朝服，脫下錦衣，披上戰兢，坐在地上，不停發抖，為你而驚駭。","notes":[]},{"n":17,"t":"他們必為你作哀歌，向你說：『你這聞名之城，航海之人居住，海上最為堅固的，你和居民使所有住在沿海的人無不驚恐，現在竟然毀滅了！","notes":[]},{"n":18,"t":"如今在你傾覆的日子，海島都要戰兢；海中的群島見你歸於無有就都驚惶。』」","notes":[]},{"n":19,"t":"主耶和華如此說：「推羅啊，我要使你變為荒涼，如無人居住的城鎮；又使深水漫過你，大水淹沒你。","notes":["原文沒有「推羅啊」。"]},{"n":20,"t":"那時，我要使你和下到地府的人同去，到古時候的人那裏；我要使你和下到地府的人一同住在地的深處，在久已荒廢的地方，使你那裏不再有人居住；我要在活人之地顯榮耀。","notes":["「我要...顯榮耀」：七十士譯本是「你不能在活人之地立足」。"]},{"n":21,"t":"我必叫你令人驚恐，使你不再存留於世；人雖尋找你，卻永不尋見。這是主耶和華說的。」","notes":[]}]},"27":{"heading":"哀悼推羅的輓歌","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，要為推羅作哀歌。","notes":[]},{"n":3,"t":"你要對位於海口，跟許多海島的百姓做生意的推羅說，主耶和華如此說：推羅啊，你曾說：『我全然美麗。』","notes":[]},{"n":4,"t":"你的疆界在海的中心，造你的使你全然美麗。","notes":[]},{"n":5,"t":"他們用示尼珥的松樹作你的甲板，用黎巴嫩的香柏樹作桅杆，","notes":[]},{"n":6,"t":"用巴珊的橡樹作你的槳，用鑲嵌象牙的基提海島黃楊木為艙板。","notes":["「黃楊木」：原文另譯「柏樹」。"]},{"n":7,"t":"你的帆是用埃及繡花細麻布做的，可作你的大旗；你的篷是用以利沙島的藍色和紫色布做的。","notes":[]},{"n":8,"t":"西頓和亞發的居民為你划槳；推羅啊，你們中間的智慧人為你掌舵。","notes":[]},{"n":9,"t":"迦巴勒的長者和智者在你中間修補裂縫；海上一切的船隻和水手都在你那裏進行貨物交易。","notes":[]},{"n":10,"t":"「波斯人、路德人、弗人在你的軍營中作戰士；他們在你們中間懸掛盾牌和頭盔，彰顯你的尊榮。","notes":["「弗」是利比亞的一部分。"]},{"n":11,"t":"亞發人和你的軍隊都駐守在四圍的城牆上，你的城樓上也有勇士；他們懸掛盾牌，成全你的美麗。","notes":[]},{"n":12,"t":"「他施因你多有財物，就作你的客商，他們帶著銀、鐵、錫、鉛前來換你的商品。","notes":[]},{"n":13,"t":"雅完、土巴、米設都與你交易，以人口和銅器換你的貨物。","notes":[]},{"n":14,"t":"陀迦瑪族用馬匹、戰馬和騾子換你的商品。","notes":[]},{"n":15,"t":"底但人與你交易，許多海島成為你的碼頭；他們拿象牙、黑檀木與你交換。","notes":[]},{"n":16,"t":"亞蘭 因你貨品充裕，就作你的客商；他們用綠寶石、紫色布、刺繡、細麻布、珊瑚、紅寶石換你的商品。","notes":["「亞蘭」：有古卷是「以東」。"]},{"n":17,"t":"猶大和以色列地都與你交易；他們用米匿的小麥、餅、蜜、油、乳香換你的貨物。","notes":[]},{"n":18,"t":"大馬士革也因你貨品充裕，多有各類財物，就帶來黑本酒和白羊毛與你交易。","notes":[]},{"n":19,"t":"威但和從烏薩來的雅完人為了你的貨物，以加工的鐵、桂皮、香菖蒲換你的商品。","notes":["「威但...雅完人」：原文另譯「他們用從烏薩來的酒」。"]},{"n":20,"t":"底但以騎馬用的座墊毯子與你交換。","notes":[]},{"n":21,"t":"阿拉伯和基達所有的領袖都作你的客商，用羔羊、公綿羊、公山羊與你交換。","notes":[]},{"n":22,"t":"示巴和拉瑪的商人也來與你交易，他們用各類上好的香料、各類的寶石和黃金換你的商品。","notes":[]},{"n":23,"t":"哈蘭、干尼、伊甸、示巴商人、亞述和基抹都與你交易。","notes":["「示巴商人、亞述」：原文另譯「亞述商人」；或另譯「亞述」。"]},{"n":24,"t":"這些商人將美好的貨物包在藍色的繡花包袱內，又將華麗的衣服裝在香柏木的箱子裏，用繩索捆著，以此與你交易。","notes":["「以此與你交易」：原文直譯「在你的市場」。"]},{"n":25,"t":"他施的船隻為你運貨，你在海中滿載貨物，極其沉重。","notes":[]},{"n":26,"t":"划槳的把你划到水深之處，東風在海中將你擊破。","notes":[]},{"n":27,"t":"你的財寶、商品、貨物、水手、掌舵的、修補船縫的、進行貨物交易的，並你那裏所有的戰士和你中間所有的軍隊，在你傾覆的日子都必沉在海底。","notes":[]},{"n":28,"t":"因掌舵者的呼聲，郊野就必震動。","notes":[]},{"n":29,"t":"所有划槳的都從他們的船下來；水手和所有在海上掌舵的，都要登岸。","notes":[]},{"n":30,"t":"他們必為你放聲痛哭，撒塵土於頭上，在灰中打滾；","notes":[]},{"n":31,"t":"又為你使頭光禿，用麻布束腰，號咷痛哭，痛苦至極。","notes":[]},{"n":32,"t":"他們哀號的時候，為你作哀歌，為你痛哭：有何城如推羅，在海中沉寂呢？","notes":[]},{"n":33,"t":"你由海上運出商品，使許多民族充裕；你以許多財寶貨物令地上的君王豐富。","notes":[]},{"n":34,"t":"在深水中被海浪打破的時候，你的貨物和你中間所有的軍隊都下沉。","notes":[]},{"n":35,"t":"海島所有的居民為你驚奇，他們的君王都甚恐慌，面帶愁容。","notes":[]},{"n":36,"t":"萬民中的商人向你發噓聲；你令人驚恐，不再存留於世，直到永遠。」","notes":[]}]},"28":{"heading":"斥責推羅王","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要對推羅的君王說，主耶和華如此說：你心裏高傲，說：『我是神明；我在海中坐諸神之位。』雖然你把你的心比作神明的心，你卻不過是人，並不是神明！","notes":[]},{"n":3,"t":"看哪，你比但以理更有智慧，任何祕密都不能向你隱藏。","notes":[]},{"n":4,"t":"你靠自己的智慧聰明得了財寶，把金銀收入庫房；","notes":[]},{"n":5,"t":"你靠自己的大智慧以貿易增添財寶，又因你的財寶心裏高傲；","notes":[]},{"n":6,"t":"所以主耶和華如此說：因你把你的心比作神明的心，","notes":[]},{"n":7,"t":"所以，看哪，我必使外國人，就是列國中兇暴的人臨到你這裏；他們要拔刀摧毀你用智慧得來的美物，污損你的榮光。","notes":[]},{"n":8,"t":"他們必使你墜入地府；你要像被刺殺之人的死，死在海中。","notes":[]},{"n":9,"t":"在殺你的人面前，你還能說『我是神明』嗎？在殺害你的人手中，你不過是人，並不是神明。","notes":[]},{"n":10,"t":"你要死在陌生人手中，像未受割禮之人的死，因為我曾說過，這是主耶和華說的。」","notes":[]},{"n":11,"t":"耶和華的話臨到我，說：","notes":[],"heads":["推羅王的結局"]},{"n":12,"t":"「人子啊，要為推羅王作哀歌，對他說，主耶和華如此說：你曾是完美的典範，智慧充足，全然美麗。","notes":[]},{"n":13,"t":"你在伊甸─神的園中，佩戴各樣寶石，就是紅寶石、紅璧璽、金剛石、水蒼玉、紅瑪瑙、碧玉、藍寶石、綠寶石、紅玉；你的寶石有黃金的底座，手工精巧，都是在你受造之日預備的。","notes":["「你的寶石...精巧」：原文另譯「和黃金；又有精美的鼓笛在你那裏」。"]},{"n":14,"t":"我指定你為受膏的基路伯，看守保護；你在神的聖山上；往來在如火的寶石中。","notes":[]},{"n":15,"t":"你從受造之日起行為正直，直到後來查出你的不義。","notes":[]},{"n":16,"t":"你因貿易發達，暴力充斥其中，以致犯罪，所以我污辱你，使你離開神的山。守護者基路伯啊，我已將你從如火的寶石中殲滅。","notes":[]},{"n":17,"t":"你因美麗心中高傲，因榮光而敗壞智慧，我已將你拋棄在地，把你擺在君王面前，好叫他們目睹眼見。","notes":[]},{"n":18,"t":"你因罪孽眾多，貿易不公，褻瀆了你的聖所；因此我使火從你中間發出，燒滅了你，使你在所有觀看的人眼前變為地上的灰燼。","notes":[]},{"n":19,"t":"萬民中凡認識你的都必為你驚奇。你令人驚恐，不再存留於世，直到永遠。」","notes":[]},{"n":20,"t":"耶和華的話臨到我，說：","notes":[],"heads":["斥責西頓"]},{"n":21,"t":"「人子啊，你要面向西頓，向它說預言。","notes":[]},{"n":22,"t":"你要說，主耶和華如此說：『西頓，看哪，我與你為敵，我要在你中間得榮耀。』我在它中間施行審判、顯為聖的時候，人就知道我是耶和華。","notes":[]},{"n":23,"t":"我必令瘟疫進入西頓，使血流在街上。刀劍從四圍臨到它，被殺的要仆倒在其中；人就知道我是耶和華。」","notes":[]},{"n":24,"t":"「四圍恨惡以色列家的人，對他們必不再如刺人的荊棘，傷人的蒺藜；他們就知道我是主耶和華。」","notes":[],"heads":["以色列要蒙福"]},{"n":25,"t":"主耶和華如此說：「我將分散在萬民中的以色列家召集回來，在列國眼前向他們顯為聖的時候，他們仍可在我所賜給我僕人雅各之地居住。","notes":[]},{"n":26,"t":"他們要在這地上安然居住。我向四圍恨惡他們的眾人施行審判之後，他們要建造房屋，栽葡萄園，安然居住，他們就知道我是耶和華─他們的神。」","notes":[]}]},"29":{"heading":"斥責埃及","verses":[{"n":1,"t":"第十年十月十二日，耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要面向埃及王法老，向他和埃及全地說預言。","notes":[]},{"n":3,"t":"你要說，主耶和華如此說：埃及王法老，你這臥在自己江河中的海怪，看哪，我與你為敵。你曾說：『我的尼羅河是我的，是我為自己造的。』","notes":[]},{"n":4,"t":"我必用鉤子鉤住你的腮頰，令江河中的魚貼住你的鱗甲；我要把你和所有貼著鱗甲的魚從你的江河中拉上來。","notes":[]},{"n":5,"t":"我要把你和江河中的魚全都拋棄在曠野；你必仆倒在田間，無人收殮，無人掩埋。我已將你給了地上的走獸、空中的飛鳥作食物。","notes":[]},{"n":6,"t":"「埃及所有的居民必定知道我是耶和華。因為你已成為以色列家蘆葦的杖；","notes":[]},{"n":7,"t":"他們用手掌一握，你就斷裂，傷了他們的肩；他們靠著你，你卻折斷，閃了他們的腰。","notes":["「閃了他們的腰」是根據七十士譯本和其他古譯本；原文是「穩住他們的腰」。"]},{"n":8,"t":"所以主耶和華如此說：我必使刀劍臨到你，把人與牲畜從你中間剪除。","notes":[]},{"n":9,"t":"埃及地必荒蕪廢棄，他們就知道我是耶和華。「因為法老說『尼羅河是我的，是我所造的』，","notes":[]},{"n":10,"t":"所以，看哪，我必與你和你的江河為敵，使埃及地，從密奪到色弗尼，直到古實邊界，全然廢棄荒蕪。","notes":["「古實」包括蘇丹的大部分和埃塞俄比亞的一部分。"]},{"n":11,"t":"人的腳不經過，獸的蹄也不經過，四十年之久無人居住。","notes":[]},{"n":12,"t":"我要使埃及地成為荒蕪中最荒蕪的地，使它的城鎮變為荒廢中最荒廢的城鎮，共四十年之久。我必將埃及人分散到列國，四散在列邦。","notes":[]},{"n":13,"t":"「主耶和華如此說：滿了四十年後，我必招聚分散在萬民中的埃及人。","notes":[]},{"n":14,"t":"我要令埃及被擄的人歸回，使他們回到本地巴特羅。在那裏，他們必成為弱小的國家，","notes":[]},{"n":15,"t":"成為列國中最低微的，不再自高於列邦之上。我必使他們變為小國，不再轄制列邦。","notes":[]},{"n":16,"t":"埃及必不再作以色列家的倚靠，卻使以色列家想起他們仰賴埃及的罪。他們就知道我是主耶和華。」","notes":[]},{"n":17,"t":"第二十七年正月初一，耶和華的話臨到我，說：","notes":[],"heads":["尼布甲尼撒將征服埃及"]},{"n":18,"t":"「人子啊，巴比倫王尼布甲尼撒令他的軍兵大力攻打推羅，以致頭都光禿，肩都磨破；然而他和軍兵雖然為攻打推羅花這麼多力氣，卻沒有從那裏得到甚麼犒賞。","notes":[]},{"n":19,"t":"所以主耶和華如此說：我要將埃及地賜給巴比倫王尼布甲尼撒；他必擄掠埃及的財富，搶奪它的擄物，擄掠它的掠物，用以犒賞他的軍兵。","notes":[]},{"n":20,"t":"我將埃及地賜給他，犒賞他，因他們為我效勞。這是主耶和華說的。","notes":[]},{"n":21,"t":"「當那日，我必使以色列家壯大，又必使你─以西結在他們中間開口；他們就知道我是耶和華。」","notes":["「壯大」：原文是「角長出來」。"]}]},"30":{"heading":"耶和華懲罰埃及","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要說預言；你要說，主耶和華如此說：哀哉這日！你們應當哭號，","notes":[]},{"n":3,"t":"因為日子近了，耶和華的日子臨近了；那是密雲之日，是列國受罰之期。","notes":["原文沒有「受罰」。"]},{"n":4,"t":"必有刀劍臨到埃及；被殺的人仆倒在埃及時，古實人顫驚不已。埃及的財富遭擄掠，根基被拆毀。","notes":[]},{"n":5,"t":"古實人、弗人、路德人、混居的各族和古伯人，以及盟國的人都要與埃及人一同倒在刀下。","notes":[]},{"n":6,"t":"「耶和華如此說：扶助埃及的必傾倒，埃及驕傲的權勢必降為卑，從密奪到色弗尼，人必倒在刀下。這是主耶和華說的。","notes":[]},{"n":7,"t":"埃及成為荒涼中最荒涼的國，它的城鎮變為荒廢中最荒廢的城鎮。","notes":[]},{"n":8,"t":"我在埃及放火，幫助埃及的，都遭滅絕；那時，他們就知道我是耶和華。","notes":[]},{"n":9,"t":"「到那日，必有使者從我面前乘船出去，使安逸無慮的古實人驚懼；當埃及遭難的日子，痛苦也必臨到他們。看哪，這事臨近了！","notes":[]},{"n":10,"t":"「主耶和華如此說：我要藉巴比倫王尼布甲尼撒的手除滅埃及的軍隊。","notes":[]},{"n":11,"t":"他和隨從他的人，就是列國中兇暴的人，要前來毀滅這地，拔刀攻擊埃及，使遍地佈滿被殺的人。","notes":[]},{"n":12,"t":"我要使江河乾涸，將這地賣在惡人手中；我要藉外國人的手，使這地和其中所充滿的變為荒蕪；這是我─耶和華說的。","notes":[]},{"n":13,"t":"「主耶和華如此說：我要毀滅偶像，從挪弗除掉神像；不再有君王出自埃及地，我要使埃及地的人懼怕。","notes":["「挪弗」就是埃及的孟斐斯；下同。"]},{"n":14,"t":"我必令巴特羅荒涼，在瑣安放火，向挪施行審判。","notes":["「挪」就是埃及的底比斯；下同。"]},{"n":15,"t":"我要將我的憤怒傾倒在訓，埃及的堡壘上，要剪除挪的眾民。","notes":[]},{"n":16,"t":"我必在埃及放火，訓必大大痛苦，挪被攻破，挪弗終日遭敵侵襲。","notes":[]},{"n":17,"t":"亞文和比‧伯實的年輕人必倒在刀下，這些城鎮將被擄掠。","notes":[]},{"n":18,"t":"我在答比匿折斷埃及的軛，使它驕傲的權勢止息。那時，日光必退去；至於這城，必有密雲遮蔽，鄰近的城鎮也遭擄掠。","notes":["「軛」：有古卷和七十士譯本是「權杖」。","「鄰近的城鎮」：原文直譯「其中的眾女子」。"]},{"n":19,"t":"我要如此向埃及施行審判，他們就知道我是耶和華。」","notes":[]},{"n":20,"t":"第十一年正月初七，耶和華的話臨到我，說：","notes":[],"heads":["埃及王的崩潰"]},{"n":21,"t":"「人子啊，我已折斷埃及王法老的一隻膀臂；看哪，無人為他敷藥，也無人為他包紮繃帶，使他有力持刀。","notes":[]},{"n":22,"t":"因此，主耶和華如此說：看哪，我與埃及王法老為敵，要折斷他的膀臂，折斷強壯的和已受傷的，使刀從他手中掉落。","notes":[]},{"n":23,"t":"我必將埃及人分散到列國，四散在列邦。","notes":[]},{"n":24,"t":"我要使巴比倫王的膀臂有力，把我的刀交在他手中；卻要折斷法老的膀臂，使他在巴比倫王面前呻吟，如同被殺的人一樣。","notes":[]},{"n":25,"t":"我要使巴比倫王的膀臂強壯，法老的膀臂卻要下垂；當我把我的刀交在巴比倫王手中時，他要舉刀攻擊埃及地，他們就知道我是耶和華。","notes":[]},{"n":26,"t":"我必將埃及人分散到列國，四散在列邦；他們就知道我是耶和華。」","notes":[]}]},"31":{"heading":"高聳的香柏樹","verses":[{"n":1,"t":"第十一年三月初一，耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要對埃及王法老和他的軍隊說：論到你的強盛，誰能與你相比呢？","notes":[]},{"n":3,"t":"看哪，亞述是黎巴嫩的香柏樹，枝條榮美，蔭密如林，極其高大，樹頂高聳入雲。","notes":[]},{"n":4,"t":"眾水使它生長，深水使它長高；所栽之地有江河環繞，汊出的水道流至田野的樹木。","notes":[]},{"n":5,"t":"所以它高大超過田野的樹木；生長時因水源豐沛，枝子繁多，枝條增長。","notes":[]},{"n":6,"t":"空中所有的飛鳥在枝子上搭窩，野地所有的走獸在枝條下生子，所有的大國也在它的蔭下居住。","notes":[]},{"n":7,"t":"它樹大枝長，極為榮美，因它的根在眾水之旁。","notes":[]},{"n":8,"t":"神園中的香柏樹不能遮蔽它；松樹不及它的枝子，楓樹不及它的枝條，神園中的樹都沒有它榮美。","notes":[]},{"n":9,"t":"我使它枝條繁多，極為榮美；在神的園中，伊甸所有的樹都嫉妒它。」","notes":[]},{"n":10,"t":"所以主耶和華如此說：「因它高大，樹頂高聳入雲，心高氣傲，","notes":["「它」是根據古譯本；原文是「你」。"]},{"n":11,"t":"我要把它交給列國中強人的手裏，他們必定按它的罪惡懲治它。我已經驅逐它。","notes":["「我要把它交給」：有古卷和七十士譯本是「我已把它交給」。"]},{"n":12,"t":"外國人，就是列國中兇暴的人，已把它砍斷拋棄。它的枝條掉落山間和一切谷中，枝子折斷，落在地上一切河道。地上的萬民都離開它的遮蔭，拋棄了它。","notes":[]},{"n":13,"t":"空中的飛鳥都棲身在掉落的樹幹上，野地的走獸也都躺臥在它的枝條中。","notes":[]},{"n":14,"t":"為了要使水邊的樹木枝幹不再長高，樹頂也不再高聳入雲；那些得水滋潤的，不再屹立於其中。因為它們和下到地府的人一起，都被交與死亡，到了地底下。」","notes":[]},{"n":15,"t":"主耶和華如此說：「它墜落陰間的那日，我為它遮蓋深淵，攔住江河，使眾水停流，以表哀悼。我使黎巴嫩為它悲哀，田野的樹木都因它枯萎。","notes":[]},{"n":16,"t":"我把它扔到陰間，與下到地府的人一同墜落。那時，列國聽見墜落的響聲就震驚；伊甸一切的樹木，就是黎巴嫩中得水滋潤、最佳最美的樹，在地底下都得了安慰。","notes":[]},{"n":17,"t":"這些樹也要與它同下陰間，到被刀所殺的人那裏；它們曾作它的膀臂，在列國中曾居住在它的蔭下。","notes":["「它的膀臂」：原文另譯和七十士譯本是「它的後裔」。"]},{"n":18,"t":"在這樣的榮耀與威勢中，伊甸樹木有誰能與你相比呢？然而你要與伊甸的樹木一同到地底下；在未受割禮的人中，與被刀所殺的人一同躺下。「法老和他的軍隊正是如此。這是主耶和華說的。」","notes":[]}]},"32":{"heading":"以海怪比埃及王","verses":[{"n":1,"t":"第十二年十二月初一，耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要為埃及王法老作哀歌，說：你在列國中，如同少壯獅子，卻像海裏的海怪，衝出江河，以爪攪動諸水，使江河渾濁。","notes":[]},{"n":3,"t":"主耶和華如此說：許多民族聚集時，我要將我的網撒在你身上，他們要把你拉上來。","notes":[]},{"n":4,"t":"我要把你丟在地上，拋在田野，使空中的飛鳥落在你身上，遍地的野獸因你得以飽足。","notes":[]},{"n":5,"t":"我要將你的肉丟在山間，用你巨大的屍首填滿山谷。","notes":["「巨大的屍首」：原文另譯「腐爛的屍首」。"]},{"n":6,"t":"我要以你所流的血浸透大地，漫過山頂，溢滿河道。","notes":[]},{"n":7,"t":"我毀滅你時，要遮蔽諸天，使眾星昏暗；我必以密雲遮掩太陽，月亮也不放光。","notes":[]},{"n":8,"t":"我要使天上發亮的光體在你上面變為昏暗，使你的地也變為黑暗。這是主耶和華說的。","notes":[]},{"n":9,"t":"「我使你在列國，在你所不認識的列邦中滅亡。那時，我必使許多民族的心因你愁煩。","notes":["「滅亡」：七十士譯本是「被擄」。"]},{"n":10,"t":"當我在他們面前舉起我的刀，我要使許多民族因你驚恐，他們的君王也必因你極其恐慌。在你仆倒的日子，他們各人為自己的性命時時戰兢。","notes":[]},{"n":11,"t":"主耶和華如此說：巴比倫王的刀必臨到你。","notes":[]},{"n":12,"t":"我必藉勇士的刀使你的軍隊仆倒；這些勇士都是列國中兇暴的人。他們必使埃及的驕傲歸於無有，埃及的軍隊必被滅絕。","notes":[]},{"n":13,"t":"我要除滅眾水旁一切的走獸，人的腳必不再攪渾這水，獸的蹄也不攪渾這水。","notes":[]},{"n":14,"t":"那時，我必使他們的水澄清，使他們的江河像油緩流。這是主耶和華說的。","notes":[]},{"n":15,"t":"我使埃及地荒廢，使這地空無一物，又擊殺其中所有的居民；那時，他們就知道我是耶和華。","notes":[]},{"n":16,"t":"「這是一首為人所吟唱的哀歌；列國的女子要唱這哀歌，她們要為埃及和它的軍隊唱這哀歌。這是主耶和華說的。」","notes":[]},{"n":17,"t":"第十二年某月十五日，耶和華的話臨到我，說：","notes":["「某月」：七十士譯本是「正月」。"],"heads":["為埃及哀號"]},{"n":18,"t":"「人子啊，你要為埃及的軍隊哀號，把他們和強盛之國一同扔到地底下，與那些下到地府的人在一起。","notes":["「強盛之國」：原文直譯「強盛之國的女子」。"]},{"n":19,"t":"『你的美麗勝過誰呢？墜落吧，與未受割禮的人躺在一起！』","notes":[]},{"n":20,"t":"他們要仆倒在被刀所殺的人當中。埃及被交給刀劍，人要把它和它的軍隊拉走。","notes":[]},{"n":21,"t":"強壯的勇士要在陰間對埃及王和他的盟友說話；他們未受割禮，被刀劍所殺，已經墜落躺下。","notes":[]},{"n":22,"t":"「亞述和它的全軍在那裏，四圍都是墳墓；他們全都是被殺倒在刀下的人。","notes":[]},{"n":23,"t":"他們的墳墓在地府極深之處，它的眾軍環繞它的墳墓，他們全都是被殺倒在刀下的人，曾在活人之地使人驚恐。","notes":[]},{"n":24,"t":"「以攔在那裏，它的全軍環繞它的墳墓；他們全都是被殺倒在刀下、未受割禮而到地底下的，曾在活人之地使人驚恐；他們與下到地府的人一同擔當羞辱。","notes":[]},{"n":25,"t":"人為它和它的軍隊在被殺的人中設立床榻，四圍都是墳墓；他們都是未受割禮被刀所殺的，曾在活人之地使人驚恐；他們與下到地府的人一同擔當羞辱。以攔已列在被殺的人中。","notes":[]},{"n":26,"t":"「米設、土巴和他們的全軍都在那裏，四圍都是墳墓；他們都是未受割禮被刀所殺的，曾在活人之地使人驚恐。","notes":[]},{"n":27,"t":"他們不得與那未受割禮仆倒的勇士躺在一起；這些勇士帶著兵器下到陰間，頭枕著刀劍，骨頭帶著本身的罪孽，曾在活人之地使人驚恐。","notes":["「那未受割禮」：七十士譯本和其他古譯本是「古代」。"]},{"n":28,"t":"法老啊，你必與未受割禮的人一起毀滅，與被刀所殺的人躺在一起。","notes":[]},{"n":29,"t":"「以東在那裏，它的君王和所有官長雖然英勇，還是與被刀所殺的人同列；他們必與未受割禮的和下到地府的人躺在一起。","notes":[]},{"n":30,"t":"「在那裏有北方的眾王子和所有的西頓人，全都與被殺的人一同下去。他們雖然英勇，使人驚恐，還是蒙羞。他們未受割禮，和被刀所殺的人躺在一起，與下到地府的人一同擔當羞辱。","notes":[]},{"n":31,"t":"「法老看見他們，就為他的軍兵，就是被刀所殺屬法老的人和他的全軍感到安慰。這是主耶和華說的。","notes":[]},{"n":32,"t":"我任憑法老在活人之地使人驚恐，法老和他的軍兵必躺在未受割禮和被刀所殺的人中。這是主耶和華說的。」","notes":[]}]},"33":{"heading":"神派以西結作守望者","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要吩咐本國的百姓，對他們說：我使刀劍臨到哪一國，哪一國的百姓從他們中間選立一人，作為守望者。","notes":[]},{"n":3,"t":"守望者見刀劍臨到那地，若吹角警戒百姓，","notes":[]},{"n":4,"t":"有人聽見角聲卻不受警戒，刀劍來除滅了他，這人的血必歸到自己頭上。","notes":[]},{"n":5,"t":"他聽見角聲，不受警戒，他的血必歸到自己身上；他若受警戒，就救了自己的命。","notes":[]},{"n":6,"t":"倘若守望者見刀劍臨到，卻不吹角，以致百姓未受警戒，刀劍來殺了他們中間的一個人，這人雖然因自己的罪孽而死，我卻要從守望者的手裏討他的血債。","notes":[]},{"n":7,"t":"「人子啊，我照樣立你作以色列家的守望者；你要聽我口中的話，替我警戒他們。","notes":[]},{"n":8,"t":"我對惡人說：『惡人哪，你必要死！』你若不開口警戒惡人，使他離開所行的道，這惡人必因自己的罪孽而死，我卻要從你手裏討他的血債。","notes":[]},{"n":9,"t":"但是你，你若警戒惡人，叫他離棄所行的道，他仍不轉離，他必因自己的罪孽而死，你卻救了自己的命。」","notes":[]},{"n":10,"t":"「人子啊，你要對以色列家說：你們曾這樣說：『我們的過犯罪惡在自己身上，我們必因此消滅，怎能存活呢？』","notes":[],"heads":["個人的責任"]},{"n":11,"t":"你要對他們說，主耶和華說：我指著我的永生起誓，我斷不喜悅惡人死亡，惟喜悅惡人轉離他所行的道而存活。以色列家啊，你們回轉，回轉離開惡道吧！何必死亡呢？","notes":[]},{"n":12,"t":"人子啊，你要對本國的百姓說：義人的義，在他犯罪之日不能救他；至於惡人的惡，在他轉離惡行之日不會使他傾倒；義人在他犯罪之日不能因自己的義存活。","notes":[]},{"n":13,"t":"我對義人說：『你必存活！』他若倚靠自己的義作惡，所行的義就不被記念；他必因所作的惡死亡。","notes":[]},{"n":14,"t":"我對惡人說：『你必死亡！』他若轉離他的罪惡，行公平公義的事；","notes":[]},{"n":15,"t":"惡人若歸還抵押品，歸回所搶奪的東西，遵行生命的律例，不再作惡；他必存活，不致死亡。","notes":[]},{"n":16,"t":"他所犯的一切罪必不被記念；他行了公平公義的事，必要存活。","notes":[]},{"n":17,"t":"「你本國的百姓說：『主的道不公平。』其實他們，他們的道才是不公平。","notes":[]},{"n":18,"t":"義人轉離自己的義作惡，他必因此而死亡。","notes":[]},{"n":19,"t":"惡人轉離他的惡，行公平公義的事，他必因此而存活。","notes":[]},{"n":20,"t":"你們還說：『主的道不公平。』以色列家啊，我必按你們各人所行的審判你們。」","notes":[]},{"n":21,"t":"我們被擄後第十二年的十月初五，有人從耶路撒冷逃到我這裏，說：「城已被攻破。」","notes":[],"heads":["耶路撒冷陷落的消息"]},{"n":22,"t":"逃來的人到的前一天晚上，耶和華的手按在我身上，開我的口。第二天早晨，等那人來到我這裏，我的口就開了，不再說不出話來。","notes":[]},{"n":23,"t":"耶和華的話臨到我，說：","notes":[],"heads":["百姓的罪"]},{"n":24,"t":"「人子啊，住在以色列荒廢之地的人說：『亞伯拉罕一人能得這地為業，我們人數眾多，這地更是給我們為業的。』","notes":[]},{"n":25,"t":"所以你要對他們說，主耶和華如此說：你們吃帶血的食物，向偶像舉目，並且流人的血，你們還能得這地為業嗎？","notes":[]},{"n":26,"t":"你們倚靠自己的刀劍行可憎的事，人人污辱鄰舍的妻，你們還能得這地為業嗎？","notes":[]},{"n":27,"t":"你要對他們這樣說，主耶和華如此說：我指著我的永生起誓，在廢墟的，必倒在刀下；在田野的，必交給野獸吞吃；在堡壘和洞中的，必遭瘟疫而死。","notes":[]},{"n":28,"t":"我必使這地荒廢荒涼，它驕傲的權勢也必止息；以色列的山都必荒廢，無人經過。","notes":[]},{"n":29,"t":"我因他們所做一切可憎的事，使地荒廢荒涼；那時，他們就知道我是耶和華。」","notes":[]},{"n":30,"t":"「你，人子啊，你本國的百姓在城牆旁邊、在房屋門口談論你。弟兄對弟兄彼此說：『來吧！聽聽有甚麼話從耶和華而出。』","notes":[],"heads":["先知傳講的信息"]},{"n":31,"t":"他們如同百姓前來，來到你這裏，坐在你面前彷彿是我的子民。他們聽了你的話，卻不實行；因為他們口裏說愛，心卻追隨財利。","notes":[]},{"n":32,"t":"看哪，他們看你如同一個唱情歌的人，聲音優雅、善於奏樂；他們聽了你的話，卻不實行。","notes":["「一個唱情歌的人」：原文是「一首情歌」。"]},{"n":33,"t":"看哪，這話就要應驗；應驗時，他們就知道在他們中間有了先知。」","notes":[]}]},"34":{"heading":"以色列的牧人","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要向以色列的牧人說預言，對他們說，主耶和華如此說：禍哉！以色列的牧人只知牧養自己。牧人豈不當牧養群羊嗎？","notes":[]},{"n":3,"t":"你們吃肥油、穿羊毛、宰殺肥羊，卻不牧養群羊。","notes":["「肥油」：七十士譯本和其他古譯本是「奶」。"]},{"n":4,"t":"瘦弱的，你們不調養；有病的，你們不醫治；受傷的，你們未包紮；被逐的，你們不去領回；失喪的，你們不尋找；卻用暴力嚴嚴地轄制牠們。","notes":["「用暴力...牠們」：七十士譯本是「你們嚴嚴地轄制強壯者」。"]},{"n":5,"t":"牠們因無牧人就分散；既分散，就成為一切野獸的食物。","notes":[]},{"n":6,"t":"我的羊流落眾山之間和各高岡上，分散在全地，無人去尋，無人去找。","notes":[]},{"n":7,"t":"「所以，你們這些牧人要聽耶和華的話。","notes":[]},{"n":8,"t":"主耶和華說：我指著我的永生起誓，我的羊因無牧人就成為掠物，也作了一切野獸的食物。我的牧人不尋找我的羊；這些牧人只知餵養自己，並不餵養我的羊。","notes":[]},{"n":9,"t":"所以你們這些牧人要聽耶和華的話。","notes":[]},{"n":10,"t":"主耶和華如此說：看哪，我必與牧人為敵，從他們手裏討回我的羊，使他們不再牧放群羊；牧人也不再餵養自己。我必救我的羊脫離他們的口，不再作他們的食物。」","notes":[]},{"n":11,"t":"「主耶和華如此說：『看哪，我必親自尋找我的羊，將牠們尋見。","notes":[],"heads":["好牧人"]},{"n":12,"t":"牧人在羊群四散的日子怎樣尋找他的羊，我必照樣尋找我的羊。這些羊在密雲黑暗的日子散在各處，我要從那裏救回牠們。","notes":[]},{"n":13,"t":"我要從萬民中領出牠們，從各國聚集牠們，引領牠們歸回故土。我要在以色列山上，在一切溪水旁邊，在境內所有可居住的地牧養牠們。","notes":[]},{"n":14,"t":"我要在肥美的草場牧養牠們。牠們的圈必在以色列高處的山上，牠們必躺臥在佳美的圈內，在以色列山肥美的草場上吃草。","notes":[]},{"n":15,"t":"我要親自牧養我的群羊，使牠們得以躺臥。這是主耶和華說的。","notes":[]},{"n":16,"t":"失喪的，我必尋找；被逐的，我必領回；受傷的，我必包紮；有病的，我必醫治；只是肥的壯的，我要除滅；我必秉公牧養牠們。』","notes":["「我要除滅」：七十士譯本和其他古譯本是「我要看管」。"]},{"n":17,"t":"「我的羊群哪，論到你們，主耶和華如此說：看哪，我要在羊與羊中間、公綿羊與公山羊中間施行審判。","notes":[]},{"n":18,"t":"你們在肥美的草場上吃草還以為是小事嗎？竟用你們的腳踐踏剩下的草；你們喝了清水，竟用你們的腳攪渾剩下的水。","notes":[]},{"n":19,"t":"至於我的羊，只能吃你們所踐踏的，喝你們所攪渾的。","notes":[]},{"n":20,"t":"「所以，主耶和華對牠們如此說：看哪，我要親自在肥羊和瘦羊中間施行審判。","notes":[]},{"n":21,"t":"因為你們用側邊用肩推擠一切瘦弱的羊，又用角牴撞，使牠們四散在外；","notes":[]},{"n":22,"t":"所以，我要拯救我的群羊，牠們必不再作掠物；我也要在羊和羊中間施行審判。","notes":[]},{"n":23,"t":"我必在他們之上立一牧人，就是我的僕人大衛，牧養牠們；他必牧養他們，作他們的牧人。","notes":["「一牧人」：七十士譯本的一份抄本是「另一牧人」。"]},{"n":24,"t":"我─耶和華必作他們的神，我的僕人大衛要在他們中間作王。這是我─耶和華說的。","notes":[]},{"n":25,"t":"「我要與他們立平安的約，使惡獸從境內斷絕；他們在曠野也能安然居住，在樹林也能躺臥。","notes":[]},{"n":26,"t":"我要使他們和我山岡的四圍蒙福；我也必叫時雨落下，使福如甘霖降下。","notes":[]},{"n":27,"t":"田野的樹木必結果子，地也必有出產；他們要在自己的土地安然居住。我折斷他們所負的軛，救他們脫離奴役他們之人的手；那時，他們就知道我是耶和華。","notes":[]},{"n":28,"t":"他們必不再作外邦人的掠物，地上的野獸也不再吞吃他們；他們卻要安然居住，無人使他們驚嚇。","notes":[]},{"n":29,"t":"我必為他們建立聞名的栽種之地；他們在境內就不再為饑荒所滅，也不再受列國的羞辱。","notes":["「聞名的」：七十士譯本是「平安的」。"]},{"n":30,"t":"他們必知道我─耶和華他們的神與他們同在，並知道他們，以色列家，是我的子民。這是主耶和華說的。","notes":[]},{"n":31,"t":"你們這些人，你們是我的羊，我草場上的羊；我是你們的神。這是主耶和華說的。」","notes":[]}]},"35":{"heading":"神懲罰以東","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要面向西珥山，向它說預言，","notes":[]},{"n":3,"t":"對它說，主耶和華如此說：西珥山，看哪，我與你為敵，必伸手攻擊你，使你荒涼荒廢。","notes":[]},{"n":4,"t":"我必使你的城鎮變為廢墟，使你成為荒涼；你就知道我是耶和華。","notes":[]},{"n":5,"t":"因為你永懷仇恨，在以色列人遭遇災難、罪孽到了盡頭時，把他們交給刀劍，","notes":[]},{"n":6,"t":"所以主耶和華說：我指著我的永生起誓，我必使你遭遇血的報應，血必追趕你；你既不恨惡血，血必追趕你。","notes":[]},{"n":7,"t":"我要使西珥山荒涼荒廢，把來往經過的人從它那裏剪除。","notes":[]},{"n":8,"t":"我要使西珥山佈滿被殺的人。被刀殺的要倒在小山和山谷，並一切的溪水中。","notes":[]},{"n":9,"t":"我必使你永遠荒涼，使你的城鎮無人居住，你們就知道我是耶和華。","notes":[]},{"n":10,"t":"「因為你曾說『這二國、這二邦必歸我，我們必得為業』，其實耶和華仍在那裏；","notes":[]},{"n":11,"t":"所以主耶和華說：我指著我的永生起誓，我必照你因仇恨向他們發的怒氣和嫉妒對待你；我審判你的時候，要在他們中間顯明自己。","notes":[]},{"n":12,"t":"你必知道我─耶和華已聽見你一切凌辱的話，是針對以色列群山說的：『這些山荒涼了，它們是給我們作食物的。』","notes":[]},{"n":13,"t":"你們用口向我說誇大的話，增多與我敵對的話，我都聽見了。","notes":[]},{"n":14,"t":"主耶和華如此說：全地歡樂的時候，我必使你荒涼。","notes":[]},{"n":15,"t":"你怎樣因以色列家的地業荒涼而喜樂，我也要照你所做的對待你。西珥山哪，你和以東全地都必荒涼；人就知道我是耶和華。」","notes":["「人就知道」：七十士譯本是「你就知道」。"]}]},"36":{"heading":"神賜福給以色列","verses":[{"n":1,"t":"「人子啊，你要對以色列群山說預言：以色列群山哪，要聽耶和華的話。","notes":[]},{"n":2,"t":"主耶和華如此說，因仇敵說：『啊哈！這古老的丘壇都歸我們為業了！』","notes":[]},{"n":3,"t":"所以你要預言，說：主耶和華如此說：因為敵人使你荒涼，四圍踐踏你，要叫你歸其餘的列國為業，使你們成為各族的話柄與百姓的笑談；","notes":[]},{"n":4,"t":"因此，以色列群山哪，要聽主耶和華的話。對那遭四圍其餘列國佔據、譏刺的大山小岡、水溝山谷、荒廢之地、被棄之城，主耶和華如此說；","notes":[]},{"n":5,"t":"所以，主耶和華如此說：我因妒火中燒，就責備其餘的列國和以東的眾人。他們快樂滿懷，心存恨惡，將我的地佔為己有，視為被拋棄的掠物。","notes":[]},{"n":6,"t":"所以，你要指著以色列地說預言，對大山小岡、水溝山谷說，主耶和華如此說：看哪，我在妒忌和憤怒中宣佈：因你們曾受列國的羞辱，","notes":[]},{"n":7,"t":"所以我起誓說，你們四圍的列國要擔當自己的羞辱。這是主耶和華說的。","notes":[]},{"n":8,"t":"「以色列群山哪，要長出枝條，為我子民以色列結出果子，因為他們即將來到。","notes":[]},{"n":9,"t":"看哪，我是幫助你們的，我要轉向你們，使你們得以耕作栽種。","notes":[]},{"n":10,"t":"我要使以色列全家在你們那裏人數增多，城鎮有人居住，廢墟重新建造。","notes":[]},{"n":11,"t":"我要使人丁和牲畜在你們那裏加增，他們必生養眾多。我要使你們那裏像以前一樣有人居住，並要賜福，比先前更多；你們就知道我是耶和華。","notes":[]},{"n":12,"t":"我要使我的子民以色列在你們那裏行走，他們必得你為業；你就成為他們的產業，不再使他們喪失兒女。","notes":[]},{"n":13,"t":"主耶和華如此說，因為人對你們說『你是吞吃人的，又使國民喪失兒女』，","notes":[]},{"n":14,"t":"所以你必不再吞吃人，也不再使國民喪失兒女。這是主耶和華說的。","notes":[]},{"n":15,"t":"我使你不再聽見列國的羞辱；你必不再受萬民的辱罵，也不再使國民絆跌。這是主耶和華說的。」","notes":[]},{"n":16,"t":"耶和華的話臨到我，說：","notes":[],"heads":["以色列的新生活"]},{"n":17,"t":"「人子啊，以色列家住本地的時候，所作所為使那地玷污。他們的行為在我面前，好像婦人在經期中那樣污穢。","notes":[]},{"n":18,"t":"所以我因他們在那地流人的血，且以偶像使那地玷污，就把我的憤怒傾倒在他們身上。","notes":[]},{"n":19,"t":"我將他們分散到列國，四散在列邦，按他們的所作所為懲罰他們。","notes":[]},{"n":20,"t":"他們到了所去的列國，使我的聖名被褻瀆；因為人談論他們說，這是耶和華的子民，卻從耶和華的地出來。","notes":["「他們到了」是根據一些古卷和七十士譯本；原文是「他到了」。"]},{"n":21,"t":"但我顧惜我的聖名，就是以色列家在所到的列國中褻瀆的。","notes":[]},{"n":22,"t":"「所以，你要對以色列家說，主耶和華如此說：以色列家啊，我做這事不是為你們，而是為了我的聖名，就是你們在所到的列國中褻瀆的。","notes":[]},{"n":23,"t":"我要使我至大的名顯為聖；這名在列國中已遭褻瀆，是你們在他們中間褻瀆的。我在他們眼前，在你們身上顯為聖的時候，他們就知道我是耶和華。這是主耶和華說的。","notes":[]},{"n":24,"t":"我必從列國帶領你們，從列邦聚集你們，領你們回到本地。","notes":[]},{"n":25,"t":"我必灑清水在你們身上，你們就潔淨了。我要潔淨你們，使你們脫離一切的污穢，棄絕一切的偶像。","notes":[]},{"n":26,"t":"我也要賜給你們一顆新心，將新靈放在你們裏面，又從你們的肉體中除掉石心，賜給你們肉心。","notes":[]},{"n":27,"t":"我必將我的靈放在你們裏面，使你們順從我的律例，謹守遵行我的典章。","notes":[]},{"n":28,"t":"你們必住在我所賜給你們祖先之地；你們要作我的子民，我要作你們的神。","notes":[]},{"n":29,"t":"我要救你們脫離一切的污穢，也要令五穀豐登，使你們不再遭遇饑荒。","notes":[]},{"n":30,"t":"我要使樹木多結果子，田地多出土產，好叫你們不再因饑荒被列國凌辱。","notes":[]},{"n":31,"t":"那時，你們必追念自己的惡行和不好的作為，就因你們的罪孽和可憎的事厭惡自己。","notes":[]},{"n":32,"t":"你們要知道，我這樣做不是為你們。以色列家啊，你們當為自己的行為抱愧蒙羞。這是主耶和華說的。","notes":[]},{"n":33,"t":"「主耶和華如此說：我潔淨你們，使你們脫離一切罪孽的日子，必使城鎮有人居住，廢墟重新建造。","notes":[]},{"n":34,"t":"這荒蕪的土地，曾被過路的人看為荒蕪，現今卻得以耕種。","notes":[]},{"n":35,"t":"他們必說：『這荒蕪之地，現在成了像伊甸園一樣；這荒涼、荒廢、毀壞的城鎮，現今堅固，有人居住。』","notes":[]},{"n":36,"t":"那時，在你們四圍其餘的列國必知道，我─耶和華修造那毀壞之處，開墾那荒蕪之地。我─耶和華說了這話，就必成就。","notes":[]},{"n":37,"t":"「主耶和華如此說：我要回應以色列家的求問，成全他們，增添他們的人數，使他們多如羊群。","notes":[]},{"n":38,"t":"在耶路撒冷守節時，作為祭物所獻的羊群有多少，照樣，荒涼的城鎮必為人群所充滿；他們就知道我是耶和華。」","notes":[]}]},"37":{"heading":"枯骨復甦","verses":[{"n":1,"t":"耶和華的手按在我身上。耶和華藉著他的靈帶我出去，把我放在平原中，平原遍滿骸骨。","notes":[]},{"n":2,"t":"他使我從骸骨的四圍經過，看哪，平原上面的骸骨甚多，看哪，極其枯乾。","notes":[]},{"n":3,"t":"他對我說：「人子啊，這些骸骨能活過來嗎？」我說：「主耶和華啊，你是知道的。」","notes":[]},{"n":4,"t":"他又對我說：「你要向這些骸骨說預言，對它們說：枯乾的骸骨啊，要聽耶和華的話。","notes":[]},{"n":5,"t":"主耶和華對這些骸骨如此說：『看哪，我必使氣息進入你們裏面，你們就要活過來。","notes":["「氣息」或譯「靈」；下同。"]},{"n":6,"t":"我要給你們加上筋，長出肉，又給你們包上皮，使氣息進入你們裏面，你們就要活過來；你們就知道我是耶和華。』」","notes":[]},{"n":7,"t":"於是，我遵命說預言。正說預言的時候，有響聲，看哪，有地震；骨與骨彼此接連。","notes":[]},{"n":8,"t":"我觀看，看哪，骸骨上面有筋，長了肉，又包上皮，只是裏面還沒有氣息。","notes":[]},{"n":9,"t":"耶和華對我說：「人子啊，你要說預言，向風說預言。你要說，耶和華如此說：氣息啊，要從四方而來，吹在這些被殺的人身上，使他們活過來。」","notes":["「風」或譯「靈」。","「方」：原文是「風」。"]},{"n":10,"t":"於是我遵命說預言，氣息就進入骸骨，骸骨就活過來，並且用腳站起來，成為極大的軍隊。","notes":[]},{"n":11,"t":"他對我說：「人子啊，這些骸骨就是以色列全家。他們說：『看哪，我們的骨頭枯乾了，我們的指望失去了，我們滅絕淨盡了！』","notes":[]},{"n":12,"t":"所以你要說預言，對他們說，主耶和華如此說：我的子民，看哪，我要打開你們的墳墓，把你們帶出墳墓，領你們進入以色列地。","notes":[]},{"n":13,"t":"我的子民哪，我打開你們的墳墓，把你們帶出墳墓時，你們就知道我是耶和華。","notes":[]},{"n":14,"t":"我必將我的靈放在你們裏面，你們就要活過來。我把你們安置在本地，你們就知道我─耶和華說了這話，就必成就。這是耶和華說的。」","notes":[]},{"n":15,"t":"耶和華的話臨到我，說：","notes":[],"heads":["猶大和以色列合一"]},{"n":16,"t":"「人子啊，你要取一根木杖，在其上寫『為猶大和他的盟友以色列人』；又取一根木杖，在其上寫『為約瑟，就是以法蓮的杖，和他的盟友以色列全家』。","notes":["「一根」：七十士譯本是「第二根」；有古譯本是「另一根」。"]},{"n":17,"t":"你要將這兩根木杖彼此相接，連成一根，使它們在你手中合而為一。","notes":[]},{"n":18,"t":"當你本國的子民對你說：『你這是甚麼意思，你不指示我們嗎？』","notes":[]},{"n":19,"t":"你就對他們說，主耶和華如此說：看哪，我要將約瑟和他的盟友以色列支派的杖，就是在以法蓮手中的那根，與猶大的杖接連成為一根，在我手中合而為一。","notes":[]},{"n":20,"t":"你要在他們眼前，把寫了字的那兩根杖拿在手中，","notes":[]},{"n":21,"t":"對他們說，主耶和華如此說：看哪，我要從以色列人所到的列國帶領他們，從四圍聚集他們，領他們回到本地。","notes":[]},{"n":22,"t":"我要使他們在這地，在以色列群山上成為一國，必有一王作他們全體的王。他們不再成為二國，絕不再分為二國。","notes":[]},{"n":23,"t":"他們不再因偶像和可憎的物，並一切的罪過玷污自己。我卻要救他們離開一切犯罪所住的地方；我要潔淨他們，如此，他們要作我的子民，我要作他們的神。","notes":["「犯罪所住的地方」：七十士譯本是「所犯墮落的罪」。"]},{"n":24,"t":"「我的僕人大衛要作他們的王；他們全體必歸一個牧人。他們必順從我的典章，謹守遵行我的律例。","notes":[]},{"n":25,"t":"他們要住在我賜給我僕人雅各的地上，就是你們列祖所住之地。他們和他們的子孫，並子孫的子孫，都永遠住在那裏。我的僕人大衛要作他們的王，直到永遠；","notes":[]},{"n":26,"t":"並且我要與他們立平安的約，作為永約。我要安頓他們，使他們人數增多，又在他們中間設立我的聖所，直到永遠。","notes":[]},{"n":27,"t":"我的居所必在他們中間；我要作他們的神，他們要作我的子民。","notes":[]},{"n":28,"t":"我的聖所在以色列人中間直到永遠，列國就知道是我─耶和華使以色列分別為聖。」","notes":[]}]},"38":{"heading":"耶和華使用歌革","verses":[{"n":1,"t":"耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「人子啊，你要面向瑪各地的歌革，就是米設和土巴的大王，向他說預言。","notes":[]},{"n":3,"t":"你要說，主耶和華如此說：米設和土巴的大王歌革，看哪，我與你為敵。","notes":[]},{"n":4,"t":"我要把你掉轉過來，用鉤子鉤住你的腮頰，把你和你的軍兵、馬匹、騎兵都帶走。他們全都披掛整齊，成為大軍，佩帶大小盾牌，各人拿著刀劍；","notes":[]},{"n":5,"t":"他們當中有波斯人、古實人和弗人，都帶著盾牌和頭盔；","notes":[]},{"n":6,"t":"還有歌篾人和他的軍隊，北方極遠的陀迦瑪族和他的軍隊，這許多民族都跟著你。","notes":[]},{"n":7,"t":"「你和聚集到你那裏的軍隊都要預備，預備妥當，你要作他們的守衛。","notes":[]},{"n":8,"t":"過了多日，你必被差派；到末後之年，你要來到那脫離刀劍、從列國召集回來的人所住之地，來到以色列常久荒涼的山上；他們都從列國中被領出，在那裏安然居住。","notes":[]},{"n":9,"t":"你和你的全軍，並跟隨你的許多民族都要上來，如暴風刮來，如密雲遮蓋地面。","notes":[]},{"n":10,"t":"「主耶和華如此說：那時，你的心必起意念，圖謀惡計，","notes":[]},{"n":11,"t":"說：『我要上那無牆的鄉村之地，到那安靜的居民那裏，他們無牆，無門、無閂，安然居住。","notes":[]},{"n":12,"t":"我去那裏要搶財為擄物，奪貨為掠物，反手攻擊那從前荒涼、現在有人居住之地，又攻擊那從列國招聚出來、得了牲畜財貨、住在地的高處的百姓。』","notes":[]},{"n":13,"t":"示巴人、底但人、他施的商人和他們的少壯獅子都對你說：『你來是要搶財為擄物嗎？你聚集軍隊是要奪貨為掠物，奪取金銀，擄去牲畜、財貨，搶奪許多財寶為擄物嗎？』","notes":[]},{"n":14,"t":"「人子啊，你要因此說預言，對歌革說，主耶和華如此說：我的子民以色列安然居住時，你是知道的。","notes":["「你是知道的。」七十士譯本是「你豈不是要興起嗎？」"]},{"n":15,"t":"你從你的地方，從北方極遠處率領許多民族前來，他們都騎著馬，是一隊強而多的軍兵。","notes":[]},{"n":16,"t":"歌革啊，你必上來攻擊我的子民以色列，如密雲遮蓋地面。末後的日子，我必領你來攻擊我的地，我藉你在列國眼前顯為聖的時候，他們就要認識我。","notes":[]},{"n":17,"t":"主耶和華如此說：我在古時藉我僕人以色列眾先知所說的，不就是你嗎？他們在那些日子，多年說預言，我必領你來攻擊以色列人。」","notes":["「不就是你嗎？」七十士譯本和其他古譯本是「就是你。」"]},{"n":18,"t":"「主耶和華說：歌革上來攻擊以色列地的時候，我的怒氣要從鼻孔裏發出。","notes":[],"heads":["耶和華懲罰歌革"]},{"n":19,"t":"我在妒忌和如火的烈怒中說：那日在以色列地必有大震動，","notes":[]},{"n":20,"t":"甚至海中的魚、天空的鳥、野地的獸，和地上爬的各種爬行動物，並地面上的眾人，因見我的面就都震動；山嶺崩裂，陡巖塌陷，一切的牆都必坍塌。","notes":[]},{"n":21,"t":"我必令刀劍在我的眾山攻擊歌革；人要用刀劍殺害弟兄。這是主耶和華說的。","notes":[]},{"n":22,"t":"我要用瘟疫和血懲罰他。我也必降暴雨、大冰雹、火及硫磺在他和他的軍隊，並跟隨他的許多民族身上。","notes":[]},{"n":23,"t":"我必顯為大，顯為聖，在許多國家眼前顯明自己；他們就知道我是耶和華。」","notes":[]}]},"39":{"heading":"歌革的潰敗","verses":[{"n":1,"t":"「你，人子啊，要向歌革說預言。你要說，主耶和華如此說：米設和土巴的大王歌革，看哪，我與你為敵。","notes":[]},{"n":2,"t":"我要把你調轉過來，帶領你，從北方極遠的地方上來，帶你到以色列的群山上。","notes":[]},{"n":3,"t":"我要打落你左手的弓，打掉你右手的箭。","notes":[]},{"n":4,"t":"你和你的全軍，並跟隨你的列國的人，都必倒在以色列的群山上。我要將你給各類攫食的飛鳥和野地的走獸作食物。","notes":[]},{"n":5,"t":"你必倒在田野，因為我曾說過，這是主耶和華說的。","notes":[]},{"n":6,"t":"我要降火在瑪各和海島安然居住的人身上，他們就知道我是耶和華。","notes":[]},{"n":7,"t":"「我要在我的子民以色列中彰顯我的聖名，不容我的聖名再被褻瀆，列國就知道我─耶和華是以色列中的聖者。","notes":[]},{"n":8,"t":"看哪，時候到了，必然成就，這就是我曾說過的日子。這是主耶和華說的。","notes":[]},{"n":9,"t":"「住以色列城鎮的人要出去生火，用軍器燃燒，就是大小盾牌、弓箭、棍棒、槍矛；用它們來燒火，直燒了七年。","notes":[]},{"n":10,"t":"他們不必從田野撿柴，也不必從森林伐木，因為他們要用這些軍器燒火。他們要搶奪那搶奪他們的人，擄掠那擄掠他們的人。這是主耶和華說的。」","notes":[]},{"n":11,"t":"「當那日，我要把以色列境內、海東邊的旅人谷給歌革在那裏作墳地，阻擋了旅行的人。在那裏，人要埋葬歌革和他的軍兵，稱那地為哈們‧歌革谷。","notes":["「旅人谷」：原文另譯「亞巴琳谷」，參民27．12。","「在那裏作墳地」：七十士譯本和其他古譯本是「作有名的墳地」。","「旅行的人」：原文另譯「亞巴琳人」。","「哈們‧歌革谷」意思是「歌革軍兵谷」；下同。"],"heads":["歌革的埋葬"]},{"n":12,"t":"以色列家的人要用七個月埋葬他們，好使那地潔淨。","notes":[]},{"n":13,"t":"那地所有的百姓都來埋葬他們。當我得榮耀的日子，這事必叫百姓得名聲。這是主耶和華說的。","notes":[]},{"n":14,"t":"他們要分派人專職巡查遍地，埋葬那遺留在地面上入侵者的屍首，好潔淨全地。過了七個月，他們還要再巡查。","notes":[]},{"n":15,"t":"巡查的人要遍行全地，見有人的骸骨，就在旁邊立一標記，等埋葬的人來將骸骨葬在哈們‧歌革谷，","notes":[]},{"n":16,"t":"且有一城要取名為哈摩那。他們必這樣潔淨那地。","notes":["「哈摩那」意思是「軍兵城」。"]},{"n":17,"t":"「你，人子啊，主耶和華如此說：你要向各類的飛鳥和野地的走獸說：你們要聚集，來吧，從四方聚集來吃我為你們準備的祭物，就是在以色列的群山上豐盛的祭物，叫你們吃肉、喝血。","notes":[]},{"n":18,"t":"你們要吃勇士的肉，喝地上領袖的血，如吃公綿羊、羔羊、公山羊、公牛；他們全都是巴珊的肥畜。","notes":[]},{"n":19,"t":"你們吃我為你們準備的祭物，必吃油脂直到飽了，喝血直到醉了。","notes":[]},{"n":20,"t":"你們要因我席上的馬匹、騎兵、勇士和所有的戰士而飽足。這是主耶和華說的。」","notes":[]},{"n":21,"t":"「我要在列國中彰顯我的榮耀，萬國就必看見我怎樣把手加在他們身上，施行審判。","notes":[],"heads":["以色列的復興"]},{"n":22,"t":"從那日以後，以色列家就知道我是耶和華─他們的神，","notes":[]},{"n":23,"t":"列國也必知道，以色列家被擄掠是因他們的罪孽。他們得罪我，我就轉臉不顧他們，將他們交在敵人手中，使他們全都倒在刀下。","notes":[]},{"n":24,"t":"我照他們的污穢和罪過待他們，轉臉不顧他們。","notes":[]},{"n":25,"t":"「所以主耶和華如此說：現在，我要使雅各被擄的人歸回，要憐憫以色列全家，又為我的聖名發熱心。","notes":[]},{"n":26,"t":"我將他們從萬民中領回，從仇敵之地召來，在許多國家的眼前，在他們身上顯為聖，他們在本地安然居住，無人使他們驚嚇，那時，他們要擔當自己的羞辱和干犯我的一切罪。","notes":["「擔當」或譯「忘記」。"],"end":27},{"n":28,"t":"我使他們被擄到列國，後又聚集他們回到本地，不再留一人在那裏，那時他們就知道我是耶和華─他們的神。","notes":[]},{"n":29,"t":"我不再轉臉不顧他們，因我已將我的靈澆灌以色列家。這是主耶和華說的。」","notes":[]}]},"40":{"heading":"新聖殿的異象","verses":[{"n":1,"t":"我們被擄的第二十五年，耶路撒冷城攻破後十四年，正在年初，某月初十，就在那一天，耶和華的手按在我身上，把我帶到那裏。","notes":[],"heads":["以西結被帶到耶路撒冷"]},{"n":2,"t":"在神的異象中，他帶我到以色列地，把我安置在一座極高的山上；在山的南邊有彷彿一座城的建築物。","notes":[]},{"n":3,"t":"他帶我到那裏，看哪，有一人面貌如銅，手拿麻繩和丈量的蘆葦竿，站在門口。","notes":["「面貌」：原文是「形狀」。"]},{"n":4,"t":"那人對我說：「人子啊，凡我所指示你的，你都要用眼看，用耳聽，並要放在心上。我帶你到這裏來，為要指示你；凡你所見的，都要告訴以色列家。」","notes":[]},{"n":5,"t":"看哪，殿外四圍有牆。那人手拿丈量的蘆葦竿，長六肘，每肘再加一掌。他量圍牆，寬一竿，高一竿。","notes":[],"heads":["東門"]},{"n":6,"t":"他到了朝東的門，就上臺階，量這門的門檻，寬一竿；這門檻寬一竿。","notes":[]},{"n":7,"t":"又有守衛房，每間長一竿，寬一竿，守衛房之間相隔五肘。挨著通往殿之門走廊的門檻，一竿。","notes":[]},{"n":8,"t":"他量通往殿之門的走廊，一竿。","notes":[]},{"n":9,"t":"他量門的走廊，八肘；牆柱，二肘；門的走廊通往殿那裏。","notes":[]},{"n":10,"t":"往東的門有守衛房：這旁三間，那旁三間，大小都一樣；這邊和那邊的牆柱，大小也一樣。","notes":[]},{"n":11,"t":"他量門的入口，寬十肘，門長十三肘。","notes":[]},{"n":12,"t":"守衛房前有矮牆，一肘，那邊的矮牆也是一肘；守衛房這邊六肘，那邊也是六肘。","notes":[]},{"n":13,"t":"他量門，從守衛房這邊的房頂到那邊的房頂，寬二十五肘；入口與入口相對。","notes":[]},{"n":14,"t":"他量牆柱，六十肘，院子的四周圍有挨著牆柱的門。","notes":[]},{"n":15,"t":"從大門入口到裏面門的走廊，五十肘。","notes":[]},{"n":16,"t":"守衛房和四圍挨著牆柱的門，都有嵌壁式的窗戶，廊子也有；裏面到處都有窗戶，牆柱上雕刻著棕樹。","notes":[]},{"n":17,"t":"他帶我到外院，看哪，院子的四圍有房間，有石板地；石板地上有三十個房間。","notes":[],"heads":["外院"]},{"n":18,"t":"沿著門側邊的石板地，就是下面的石板地，與門的長度相同。","notes":[]},{"n":19,"t":"他量寬度，從下門的前面到內院外的前面，東向北向一百肘。","notes":[]},{"n":20,"t":"他量外院朝北的門的長和寬。","notes":[],"heads":["北門"]},{"n":21,"t":"門的守衛房，這旁三間，那旁三間；牆柱和廊子，與第一個門的大小一樣。長五十肘，寬二十五肘。","notes":[]},{"n":22,"t":"其窗戶和廊子，並雕刻的棕樹，與朝東的門大小一樣。要登七個臺階才能上到這門，前面有廊子。","notes":["「前面」：七十士譯本是「裏面」。"]},{"n":23,"t":"內院有門與這門相對，北面東面都是如此。他從這門量到那門，共一百肘。","notes":[]},{"n":24,"t":"他帶我往南去，看哪，朝南有門，他量門的牆柱和廊子，大小與先前一樣。","notes":["「牆柱」：七十士譯本是「守衛房、牆柱」。"],"heads":["南門"]},{"n":25,"t":"門兩旁與廊子的周圍都有窗戶，和先前量的窗戶一樣。門長五十肘，寬二十五肘。","notes":[]},{"n":26,"t":"要登七個臺階才能上到這門，前面有廊子；牆柱上雕刻著棕樹，這邊一棵，那邊一棵。","notes":["「前面」：七十士譯本是「裏面」。"]},{"n":27,"t":"內院朝南也有門，從這門量到朝南的那門，共一百肘。","notes":[]},{"n":28,"t":"他帶我從南門到內院，他量南門，大小與先前一樣。","notes":[],"heads":["內院的南門"]},{"n":29,"t":"守衛房和牆柱、廊子，大小與先前一樣。門兩旁與廊子的周圍都有窗戶。門長五十肘，寬二十五肘。","notes":[]},{"n":30,"t":"周圍有廊子，長二十五肘，寬五肘。","notes":[]},{"n":31,"t":"廊子朝著外院，牆柱上雕刻著棕樹。要登八個臺階才能上到這門。","notes":[]},{"n":32,"t":"他帶我到內院的東邊，他量那門，大小與先前一樣。","notes":[],"heads":["內院的東門"]},{"n":33,"t":"守衛房和牆柱、廊子，大小與先前一樣。門兩旁與廊子的周圍都有窗戶。長五十肘，寬二十五肘。","notes":[]},{"n":34,"t":"廊子朝著外院。牆柱兩邊都雕刻著棕樹。要登八個臺階才能上到這門。","notes":[]},{"n":35,"t":"他帶我到北門，他量了，大小與先前一樣，","notes":[],"heads":["內院的北門"]},{"n":36,"t":"就是量守衛房和牆柱、廊子。門的周圍都有窗戶；門長五十肘，寬二十五肘。","notes":[]},{"n":37,"t":"牆柱朝著外院。牆柱兩邊都雕刻著棕樹。要登八個臺階才能上到這門。","notes":["「牆柱」：七十士譯本和其他古譯本是「廊子」。"]},{"n":38,"t":"有房間和它的入口在門的牆柱旁，那裏是洗燔祭牲的地方。","notes":["「牆柱」：原文另譯「走廊」。"],"heads":["廂房"]},{"n":39,"t":"在門的走廊內，這邊有兩張桌子，那邊也有兩張桌子，其上可宰殺燔祭牲、贖罪祭牲和贖愆祭牲。","notes":[]},{"n":40,"t":"上到北門的入口，朝向外面的這邊有兩張桌子，門的走廊那邊也有兩張桌子。","notes":[]},{"n":41,"t":"門這邊有四張桌子，那邊也有四張桌子，共八張，在其上宰殺祭牲。","notes":[]},{"n":42,"t":"為燔祭牲的四張桌子是用石頭鑿成的，長一肘半，寬一肘半，高一肘。宰殺燔祭牲和其他祭牲所用的器皿可放在其上。","notes":[]},{"n":43,"t":"有鉤子，寬一掌，掛在廊內的四周圍。桌子上可放祭牲的肉。","notes":[]},{"n":44,"t":"從外面進到內門，內院裏有房間，為歌唱的人而設；一間在北門旁，朝南，又有一間在南門旁，朝北。","notes":["「從外面...而設」：七十士譯本是「他帶我進到內院，看哪，內院有兩個房間」。","「南」是根據七十士譯本；原文是「東」。"]},{"n":45,"t":"他對我說：「這朝南的房間是為了聖殿供職的祭司，","notes":[]},{"n":46,"t":"那朝北的房間是為了祭壇前供職的祭司；這些祭司是利未人中撒督的子孫，近前來事奉耶和華的。」","notes":[]},{"n":47,"t":"他又量內院，長一百肘，寬一百肘，是正方的。祭壇就在殿前。","notes":[],"heads":["內院和聖殿"]},{"n":48,"t":"於是他帶我到殿前的走廊，量走廊的牆柱。這面寬五肘，那面寬五肘。門的兩旁，這邊三肘，那邊三肘。","notes":["七十士譯本在此有「門寬十四肘」。"]},{"n":49,"t":"走廊長二十肘，寬十一肘 。要登臺階才能上到走廊。靠近牆柱又有柱子，這邊一根，那邊一根。","notes":["「十一肘」：七十士譯本是「十二肘」。","「要登臺階」：七十士譯本是「要登十個臺階」。"]}]},"41":{"heading":"靠聖殿牆邊的廂房","verses":[{"n":1,"t":"他帶我到殿那裏，他量牆柱：這面寬六肘，那面寬六肘，寬窄與會幕相同。","notes":["有古卷和七十士譯本沒有「寬窄與會幕相同」。"]},{"n":2,"t":"門口寬十肘。門的兩旁，這邊五肘，那邊五肘。他又量了殿，長四十肘，寬二十肘。","notes":[]},{"n":3,"t":"他到內殿量門的牆柱，二肘，門口六肘，門的兩旁各寬七肘。","notes":[]},{"n":4,"t":"他量內殿，長二十肘，寬二十肘。他對我說：「這是至聖所。」","notes":[]},{"n":5,"t":"他又量殿的牆，六肘；圍著殿有廂房，各寬四肘。","notes":[]},{"n":6,"t":"廂房有三層，層疊而上，每層排列三十間。殿的牆四周有凸出的牆支撐廂房，廂房就不必以殿的牆為支柱。","notes":[]},{"n":7,"t":"這圍繞著殿的廂房越高越寬；廂房圍著殿懸疊而上，所以越上面越寬，從下一層，到中一層，到上一層。","notes":[]},{"n":8,"t":"我又見有高臺圍繞著殿，作為廂房的根基，高足足有一竿，就是六大肘。","notes":[]},{"n":9,"t":"廂房的外牆寬五肘。殿的廂房和那邊的房間中間還有空地，寬二十肘，圍繞著殿。","notes":[],"end":10},{"n":11,"t":"廂房的門口向著空地：一門向北，一門向南。周圍的空地寬五肘。","notes":[]},{"n":12,"t":"在西邊空地之後有房子，寬七十肘，長九十肘，牆四圍厚五肘。","notes":[],"heads":["西邊的房子"]},{"n":13,"t":"這樣，他量了殿，長一百肘，又量空地和那房子並牆，共長一百肘。","notes":[],"heads":["聖殿的面積"]},{"n":14,"t":"殿的前面和東邊的空地，寬一百肘。","notes":[]},{"n":15,"t":"他量了空地後面的那房子，並兩旁的樓廊，共長一百肘。內殿、院的走廊、","notes":[]},{"n":16,"t":"門檻、嵌壁式的窗戶，並對著門檻的三層樓廊，周圍都鑲上木板；地板到窗戶，窗戶都關著，","notes":["「內殿、院的走廊、門檻」：七十士譯本是「鑲了板的內殿和院廊」。"]},{"n":17,"t":"直到門以上，就是到內殿和外殿內外四圍牆壁，都這樣測量。","notes":[]},{"n":18,"t":"牆上雕刻基路伯和棕樹，基路伯和基路伯之間有一棵棕樹，每基路伯有兩張臉；","notes":[]},{"n":19,"t":"人的臉向著這邊的棕樹，獅子的臉向著那邊的棕樹，殿內四周圍都是如此。","notes":[]},{"n":20,"t":"從地板到門的上面，都有基路伯和棕樹。殿的牆就是這樣。","notes":[]},{"n":21,"t":"殿的門柱是方的。至聖所的前面有個東西形狀像","notes":[]},{"n":22,"t":"木頭做的壇，高三肘，長二肘。壇角和底座，並四面，都是木頭做的。他對我說：「這是耶和華面前的供桌。」","notes":["「長二肘」：七十士譯本是「長二肘，寬二肘」。","「底座」是依據七十士譯本；原文是「長度」。"]},{"n":23,"t":"殿和聖所各有一個雙層門。","notes":[],"heads":["門"]},{"n":24,"t":"每個門有兩扇，每扇又有兩個摺疊頁；這一扇有兩頁，另一扇也有兩頁。","notes":[]},{"n":25,"t":"殿的門扇上雕刻著基路伯和棕樹，與刻在牆上的一樣。在外面門的走廊前有木頭做的飛簷。","notes":[]},{"n":26,"t":"門的走廊這邊和那邊都有嵌壁式的窗戶和棕樹；殿的廂房和飛簷也是這樣。","notes":[]}]},"42":{"heading":"聖殿附近的房間","verses":[{"n":1,"t":"他帶我出來往北，到外院，又帶我進入一個房間，一面對著空地，一面對著北邊的房子。","notes":[]},{"n":2,"t":"前面長一百肘，寬五十肘，有門向北；","notes":[]},{"n":3,"t":"對著內院那二十肘，又對著外院的石板地，在第三層樓有樓廊對著樓廊。","notes":["「那二十肘」：七十士譯本是「那些門」。"]},{"n":4,"t":"那些房間前有一條走道，寬十肘，往裏面有寬一肘的通道。房門都向北。","notes":["「往裏面...通道」：七十士譯本是「長一百肘」。"]},{"n":5,"t":"房間因為樓廊佔掉一些地方，所以房子的上層比中下兩層窄。","notes":[]},{"n":6,"t":"房間分三層，卻不像外院的屋子用柱子支撐，而是從地面往上，所以一層比一層更窄。","notes":[]},{"n":7,"t":"外面有一道牆，長五十肘，在房間前面，與朝外院的房間平行。","notes":[]},{"n":8,"t":"靠著外院的房間長五十肘，看哪，朝聖殿的長一百肘。","notes":[]},{"n":9,"t":"這些房間下面的東邊有一個入口，從外院可由此進入；","notes":[]},{"n":10,"t":"其寬如院牆。朝東也有房間，一面對著空地，一面對著房子。","notes":["「東」：七十士譯本是「南」。"]},{"n":11,"t":"這些房間前的通道與北邊房間的通道一樣；長、寬、出口、樣式和入口都相同。","notes":[]},{"n":12,"t":"在東邊通道的開端，正對著那道牆有門可以進入，與向南邊房間的門一樣。","notes":[]},{"n":13,"t":"他對我說：「面對空地南邊的房間和北邊的房間，都是聖的房間；親近耶和華的祭司當在那裏吃至聖的東西，也當在那裏存放至聖的東西，就是素祭、贖罪祭和贖愆祭，因此處為聖。","notes":[]},{"n":14,"t":"祭司進聖所，出來的時候，不可直接到外院，要在那裏放下他們供職的衣服，因為這是聖衣；要穿上別的衣服才可以到百姓所在之處。」","notes":[]},{"n":15,"t":"他量完了內殿的大小，就帶我出朝東的門，去量院的四周圍。","notes":[],"heads":["聖殿周圍的面積"]},{"n":16,"t":"他用丈量的蘆葦竿量東面，五百竿；又轉去","notes":["「竿」：七十士譯本是「肘」；下同。"]},{"n":17,"t":"用丈量的蘆葦竿量北面，五百竿；又轉去","notes":[]},{"n":18,"t":"用丈量的蘆葦竿量南面，五百竿。","notes":[]},{"n":19,"t":"他又轉到西面，用丈量的蘆葦竿去量，五百竿。","notes":[]},{"n":20,"t":"他量四面，長五百，寬五百，四周圍有牆，為要分別聖與俗。","notes":[]}]},"43":{"heading":"耶和華的榮耀回到聖殿","verses":[{"n":1,"t":"以後，他帶我到一座門，就是朝東的門。","notes":[]},{"n":2,"t":"看哪，以色列神的榮光從東而來，他的聲音如同眾水的響聲，地因他的榮耀發光。","notes":[]},{"n":3,"t":"我所見的異象如同從前我來滅城的時候所見的異象，又如我在迦巴魯河邊所見的異象，我就臉伏於地。","notes":["「我」：有古卷和古譯本是「他」。"]},{"n":4,"t":"耶和華的榮光從朝東的門照入殿中。","notes":[]},{"n":5,"t":"靈將我舉起，帶入內院，看哪，耶和華的榮光充滿了殿。","notes":[]},{"n":6,"t":"我聽見有一位從殿中向我說話，有一人站在我旁邊。","notes":[]},{"n":7,"t":"他對我說：「人子啊，這是我寶座之地，是我腳掌所踏之地。我要住在這裏，住在以色列人中間直到永遠。以色列家和他們的君王不可再以淫行，或在高處以君王的屍首玷污我的聖名。","notes":["「在高處以君王的屍首」：有古卷和古譯本是「以君王死時的屍首」。"]},{"n":8,"t":"因他們使自己的門檻挨近我的門檻，使自己的門框挨近我的門框，又使他們與我之間僅隔一牆，並且行可憎的事，玷污我的聖名，所以我發怒滅絕他們。","notes":[]},{"n":9,"t":"現在，他們當從我面前遠離淫行和君王的屍首，我就要住在他們中間，直到永遠。","notes":[]},{"n":10,"t":"「你，人子啊，要將這殿指示以色列家，讓他們量殿的大小，使他們因自己的罪孽羞愧。","notes":["「要將這殿<ins>.大小」：七十士譯本和其他古譯本是「要將這殿，其外觀和樣式指示以色列家」。"]},{"n":11,"t":"他們若因自己所做的一切感到羞愧，你就要將殿的規模、樣式、出口、入口，以及有關整體規模的條例、禮儀、律法指示他們，在他們眼前寫下，使他們遵照殿整體的規模和條例去做。","notes":["「你就要</ins>.指示他們」：七十士譯本是「你就要描述殿和其出口、樣式，並它一切的條例，又要將它一切的律法指示他們」。"]},{"n":12,"t":"這是殿的律法：山頂上四周圍的全地界都稱為至聖；看哪，這就是殿的律法。」","notes":["七十士譯本沒有「看哪...律法」。"]},{"n":13,"t":"這些是祭壇的大小，以肘來量，這肘是一肘一掌。底座高一肘，邊寬一肘，四周圍有邊，高一虎口；這是祭壇的座。","notes":["「座」：七十士譯本是「高度」。"],"heads":["祭壇"]},{"n":14,"t":"從底座到下層的臺座，二肘，邊寬一肘。從小臺座到大臺座，四肘，邊寬一肘。","notes":[]},{"n":15,"t":"壇上的爐臺，高四肘，從爐臺向上突起四個角。","notes":[]},{"n":16,"t":"這爐臺長十二肘，寬十二肘，四面見方。","notes":[]},{"n":17,"t":"臺座長十四肘，寬十四肘，四面見方。四周圍有邊，高半肘，底座四圍的邊寬一肘。有臺階朝東。","notes":[]},{"n":18,"t":"他對我說：「人子啊，主耶和華如此說：這些是建造祭壇，為要在其上獻燔祭，把血灑在上面的條例：","notes":[],"heads":["奉獻祭壇"]},{"n":19,"t":"你要將一頭公牛犢作為贖罪祭，交給那近前來事奉我的利未家的祭司撒督的後裔；這是主耶和華說的。","notes":[]},{"n":20,"t":"你要取那公牛犢的一些血，抹在壇的四角和臺座的四角，並周圍的邊上。你要這樣潔淨壇，為壇贖罪。","notes":[]},{"n":21,"t":"你又要將那作贖罪祭的公牛燒在聖所外面，殿的預定之處。","notes":[]},{"n":22,"t":"次日，要將無殘疾的公山羊獻為贖罪祭；要潔淨壇，像用公牛潔淨一樣。","notes":[]},{"n":23,"t":"你潔淨了壇，就要將一頭無殘疾的公牛犢和羊群中一隻無殘疾的公綿羊","notes":[]},{"n":24,"t":"奉到耶和華面前。祭司要撒鹽在其上，獻給耶和華為燔祭。","notes":[]},{"n":25,"t":"七日內，你要每日獻一隻公山羊為贖罪祭，也要獻一頭公牛犢和羊群中的一隻公綿羊，都要沒有殘疾的。","notes":[]},{"n":26,"t":"七日內祭司要為壇贖罪，使它潔淨，把它分別為聖。","notes":[]},{"n":27,"t":"滿了七日，自八日以後，祭司要在壇上獻你們的燔祭和平安祭；我必悅納你們。這是主耶和華說的。」","notes":[]}]},"44":{"heading":"東門的使用","verses":[{"n":1,"t":"他又帶我回到聖所朝東的外門，那門關閉了。","notes":[]},{"n":2,"t":"耶和華對我說：「這門必須關閉，不可敞開，誰也不可由其中進入；因為耶和華─以色列的神已經由其中進入，所以必須關閉。","notes":[]},{"n":3,"t":"至於君王，他必按君王的位分坐在其內，在耶和華面前吃餅。他必由這門的走廊而入，也必由此而出。」","notes":[]},{"n":4,"t":"他又帶我由北門來到殿前。我觀看，看哪，耶和華的榮光充滿耶和華的殿，我就臉伏於地。","notes":[],"heads":["進入聖殿之規定"]},{"n":5,"t":"耶和華對我說：「人子啊，我對你所說耶和華殿中一切的條例和律法，你要留心，用眼看，用耳聽，要留心殿的入口和聖所一切的出口。","notes":[]},{"n":6,"t":"你要對那悖逆的以色列家說，主耶和華如此說：以色列家啊，你們行這一切可憎的事，夠了吧！","notes":[]},{"n":7,"t":"你們把我的食物，就是脂肪和血獻上的時候，竟把心和肉體未受割禮的外邦人領進我的聖所，玷污我的殿；你們行這一切可憎的事，違背了我的約。","notes":[]},{"n":8,"t":"你們未盡看守我聖物的職責，竟派別人在我的聖所替你們盡看守之責。","notes":[]},{"n":9,"t":"「主耶和華如此說：所有心和肉體未受割禮的外邦人，就是住在以色列中間的任何外邦人，都不可進入我的聖所。」","notes":[]},{"n":10,"t":"「以色列人走迷的時候，利未人遠離我，隨從他們的偶像走迷離開我，他們必擔當自己的罪孽。","notes":[],"heads":["不准當祭司的利未人"]},{"n":11,"t":"他們必在我的聖所當僕役，照管殿門，在殿裏伺候；他們要為百姓宰殺燔祭牲和其他祭牲，站在百姓面前伺候他們。","notes":[]},{"n":12,"t":"因為這些利未人曾在偶像前伺候他們，成了以色列家罪孽的絆腳石，所以我向他們起誓：他們必擔當自己的罪孽。這是主耶和華說的。","notes":[]},{"n":13,"t":"他們不可親近我，作事奉我的祭司，也不可挨近我任何一件聖物，就是至聖的物；他們卻要擔當自己的羞辱和所行可憎之事的報應。","notes":[]},{"n":14,"t":"我要指派他們在殿裏看守，辦理殿中一切事務，做一切當做的工。」","notes":[]},{"n":15,"t":"「以色列人走迷離開我的時候，利未家的祭司撒督的子孫仍然盡看守我聖所的職責；因此他們必親近我，事奉我，並且侍立在我面前，把脂肪與血獻給我。這是主耶和華說的。","notes":[],"heads":["利未家的祭司"]},{"n":16,"t":"只有他們可以進我的聖所，來到我的桌前事奉我，守我吩咐的職責。","notes":[]},{"n":17,"t":"他們進內院的門要穿細麻衣，在內院門和殿內供職時不可穿羊毛衣服。","notes":[]},{"n":18,"t":"他們要頭戴細麻布的頭巾，腰穿細麻布的褲子；不可穿容易出汗的衣服。","notes":[]},{"n":19,"t":"他們出到外院，到外院百姓那裏，要脫下供職所穿的衣服，放在聖的房間內，換上別的衣服，免得因他們的衣服使百姓成為聖。","notes":["有些古卷、七十士譯本和其他古譯本沒有「到外院」。"]},{"n":20,"t":"他們不可剃頭，也不可留長髮，頭髮一定要修剪。","notes":[]},{"n":21,"t":"祭司進內院時不可喝酒。","notes":[]},{"n":22,"t":"他們不可娶寡婦或被休的婦人為妻，只可娶以色列後裔中的處女，或祭司的寡婦。","notes":[]},{"n":23,"t":"他們要教導我的子民分辨聖與俗，使他們知道潔淨和不潔淨的分別。","notes":[]},{"n":24,"t":"有爭訟的事，他們應當審判，按我的典章審判。他們要在我的節期守我的律法和條例，也當以我的安息日為聖日。","notes":[]},{"n":25,"t":"祭司不可挨近死屍使自己不潔淨，只可為父親、母親、兒子、女兒、兄弟和未出嫁的姊妹使自己不潔淨。","notes":[]},{"n":26,"t":"他潔淨之後，他們必須再為他計算七天。","notes":[]},{"n":27,"t":"當他進內院，入聖所，在聖所中事奉的日子，要為自己獻上贖罪祭。這是主耶和華說的。","notes":[]},{"n":28,"t":"「祭司必有產業，我就是他們的產業。不可在以色列中給他們基業，我就是他們的基業。","notes":[]},{"n":29,"t":"素祭、贖罪祭和贖愆祭他們都可以吃，以色列中一切永獻的祭物都歸他們。","notes":[]},{"n":30,"t":"各樣上好的初熟之物和所獻的供物，都要歸祭司。你們也要將最先的麵團給祭司；這樣，福氣就必臨到你們的家。","notes":[]},{"n":31,"t":"無論是鳥是獸，凡自然死去的，或是被撕裂的，祭司都不可吃。」","notes":[]}]},"45":{"heading":"歸給耶和華的土地","verses":[{"n":1,"t":"你們抽籤分地為業，要獻上一份作為獻給耶和華的聖地，長二萬五千肘，寬二萬肘。整個地區都作為聖地。","notes":["原文沒有「肘」；下同。","「二萬」是根據七十士譯本；原文是「一萬」。"]},{"n":2,"t":"再從其中劃出一塊作為聖所，長五百肘，寬五百肘，四面見方；四圍再加五十肘的空地。","notes":[]},{"n":3,"t":"從這整個範圍要劃出長二萬五千肘，寬一萬肘的地，其中要有聖所，是至聖的。","notes":[]},{"n":4,"t":"這是地上的一塊聖地，要歸給在聖所供職、親近事奉耶和華的祭司，作為他們房屋用地與聖所的聖地。","notes":[]},{"n":5,"t":"其餘長二萬五千肘，寬一萬肘，要歸給在殿中供職的利未人，作為他們二十間房屋的地業。","notes":["「二十間房屋」：七十士譯本是「居住的城鎮」。"]},{"n":6,"t":"在那塊獻上的聖地旁邊，你們要劃分造城的地業，寬五千肘，長二萬五千肘，歸以色列全家。","notes":[]},{"n":7,"t":"劃歸君王的地要在獻上的聖地和城用地的兩旁，面對著聖地，又面對城的用地，西至西邊的疆界，東至東邊的疆界，從西到東，長度與每支派所分得的一樣。","notes":[],"heads":["君王的土地"]},{"n":8,"t":"這地要在以色列中歸君王為業。我所立的君王必不再欺壓我的子民，卻要按支派把地分給以色列家。","notes":[]},{"n":9,"t":"主耶和華如此說：「以色列的王啊，你們夠了吧！要除掉殘暴和搶奪的事，行公平和公義，不可再勒索我的百姓。這是主耶和華說的。","notes":[],"heads":["君王應守的規例"]},{"n":10,"t":"「你們要用公道的天平、公道的伊法、公道的罷特。","notes":[]},{"n":11,"t":"伊法要與罷特等量；一罷特為賀梅珥的十分之一，一伊法也是賀梅珥的十分之一，都以賀梅珥為計算單位。","notes":[]},{"n":12,"t":"一舍客勒是二十季拉；二十舍客勒，二十五舍客勒，十五舍客勒，合起來為你們的一彌那。","notes":[]},{"n":13,"t":"「你們當獻的供物是這樣：一賀梅珥麥子要獻六分之一伊法，一賀梅珥大麥也要獻六分之一伊法。","notes":[]},{"n":14,"t":"獻油的條例是這樣，按油的罷特：每一歌珥油，即十罷特或一賀梅珥，要獻十分之一罷特，原來十罷特等於一賀梅珥。","notes":[]},{"n":15,"t":"從以色列水源豐沛的草場上，每二百隻羊中要獻一隻羔羊。這都可作素祭、燔祭、平安祭，來為民贖罪。這是主耶和華說的。","notes":[]},{"n":16,"t":"這地所有的百姓都要帶這些供物到以色列王那裏。","notes":[]},{"n":17,"t":"王的本分是在節期、初一、安息日，就是以色列家一切的盛會，奉上燔祭、素祭、澆酒祭。他要獻上贖罪祭、素祭、燔祭和平安祭，為以色列家贖罪。」","notes":[]},{"n":18,"t":"主耶和華如此說：「正月初一，你要取無殘疾的公牛犢，潔淨聖所。","notes":[],"heads":["節期"]},{"n":19,"t":"祭司要取一些贖罪祭牲的血，抹在殿的門柱上和祭壇臺座的四角上，並內院的門框上。","notes":[]},{"n":20,"t":"本月初七，你也要為誤犯罪的和因無知而犯罪的這樣做；你們要為聖殿贖罪。","notes":[]},{"n":21,"t":"「正月十四日，你們要守逾越節，七天的節期都要吃無酵餅。","notes":[]},{"n":22,"t":"當日，王要為自己和全國百姓預備一頭公牛作贖罪祭。","notes":[]},{"n":23,"t":"節期的七天內，每天他要預備無殘疾的七頭公牛、七隻公綿羊，給耶和華為燔祭；每天又要預備一隻公山羊為贖罪祭。","notes":[]},{"n":24,"t":"他也要預備素祭，為一頭公牛同獻一伊法細麵，為一隻公綿羊同獻一伊法細麵，每一伊法加一欣油。","notes":[]},{"n":25,"t":"七月十五日守節的時候，七天他都要像這樣預備贖罪祭、燔祭、素祭和油。」","notes":[]}]},"46":{"heading":"王和節期","verses":[{"n":1,"t":"主耶和華如此說：「內院朝東的門，在六個工作的日子必須關閉；惟有安息日和初一要敞開。","notes":[]},{"n":2,"t":"王從外面要由門的走廊進入，站在門框旁邊；祭司要為他預備燔祭和平安祭，王要在門的門檻那裏敬拜，然後退出。這門直到晚上不可關閉。","notes":[]},{"n":3,"t":"安息日和初一，這地的百姓要在這門口，在耶和華面前敬拜。","notes":[]},{"n":4,"t":"安息日，王要用六隻無殘疾的羔羊、一隻無殘疾的公綿羊，獻給耶和華為燔祭；","notes":[]},{"n":5,"t":"同獻的素祭，要為公綿羊獻一伊法細麵，為羔羊則按照他的力量獻，一伊法要加一欣油。","notes":[]},{"n":6,"t":"初一，他要獻一頭無殘疾的公牛犢、六隻羔羊、一隻公綿羊，全都要用無殘疾的。","notes":[]},{"n":7,"t":"他也要預備素祭，為公牛獻一伊法細麵，為公綿羊獻一伊法細麵，為羔羊則按照他的力量獻，一伊法要加一欣油。","notes":[]},{"n":8,"t":"王進入的時候要由這門的走廊而入，也要從原路出去。","notes":[]},{"n":9,"t":"「在各節期，這地的百姓朝見耶和華的時候，從北門進入敬拜的，要由南門而出；從南門進入的，要由北門而出。不可從進入的門出去，要往前直行，從對面的門出去。","notes":[]},{"n":10,"t":"他們進入時，王也跟他們一同進入；他們出去，他也要出去。","notes":[]},{"n":11,"t":"「在節期和盛會的日子同獻的素祭，要為一頭公牛獻一伊法細麵，為一隻公綿羊獻一伊法細麵，為羔羊則按照各人的力量獻，一伊法要加一欣油。","notes":[]},{"n":12,"t":"王奉獻甘心祭，就是向耶和華甘心獻的燔祭或平安祭時，當有人為他開朝東的門。他就獻上燔祭和平安祭，與安息日所獻的一樣，然後退出。他出去之後，當有人將門關閉。」","notes":[]},{"n":13,"t":"「每日，你要取一隻無殘疾一歲的羔羊獻給耶和華為燔祭；要每天早晨獻上。","notes":[],"heads":["每日獻的祭"]},{"n":14,"t":"每天早晨你也要預備同獻的素祭，六分之一伊法細麵，並三分之一欣油，調和細麵。這素祭要經常獻給耶和華，作為永遠的定例。","notes":[]},{"n":15,"t":"每天早晨要這樣獻上羔羊、素祭和油，為經常獻的燔祭。」","notes":[]},{"n":16,"t":"主耶和華如此說：「王若將禮物賜給他的任何一個兒子，這就成為兒子的產業，可留給子孫，是他們所承受的地業。","notes":[],"heads":["王和土地"]},{"n":17,"t":"倘若王將他產業的一份賜給他的一個臣僕，這就成為他臣僕的產業，直到自由之年，然後地要歸還王；王的產業終究要歸自己的兒子。","notes":[]},{"n":18,"t":"王不可奪取百姓的產業，以致趕逐他們離開自己的地業；他應該從自己的地業中將產業賜給子孫，免得我的子民離開自己的地業，四散各處。」","notes":[]},{"n":19,"t":"他帶領我從大門旁邊的入口，進到朝北為祭司所預備聖的房間，看哪，西邊盡頭有一塊土地。","notes":[],"heads":["聖殿的廚房"]},{"n":20,"t":"他對我說：「這是祭司煮贖愆祭牲、贖罪祭牲，烤素祭的地方，免得帶出外院，使百姓成為聖。」","notes":[]},{"n":21,"t":"他又帶我出到外院，使我經過院子的四個角落，看哪，院子的每個角落都有一個小院子。","notes":[]},{"n":22,"t":"院子四個角落有小院子，周圍有牆，每個小院子長四十肘，寬三十肘；四個角落的小院子大小都一樣，","notes":["原文沒有「肘」；下同。"]},{"n":23,"t":"小院子周圍各有一排石牆，每排石牆下面有爐灶。","notes":[]},{"n":24,"t":"他對我說：「這些是煮肉用的屋子，殿內的僕役要在這裏煮百姓的祭物。」","notes":[]}]},"47":{"heading":"從聖殿流出的水","verses":[{"n":1,"t":"他帶我回到殿門，看哪，有水從殿的門檻下面往東流出，因為這殿是朝東的。水從殿的側面，就是右邊，從祭壇的南邊往下流。","notes":[]},{"n":2,"t":"他帶我出北門，又領我從外邊轉到朝東的外門，看哪，水從右邊流出。","notes":[]},{"n":3,"t":"他手拿繩子往東出去，量了一千肘，使我涉水而過，水到腳踝。","notes":[]},{"n":4,"t":"他又量了一千，使我涉水而過，水就到膝；再量了一千，使我過去，水就到腰；","notes":[]},{"n":5,"t":"又量了一千，水已成河，無法過去；因為水勢高漲成河，只能游泳，無法走過。","notes":[]},{"n":6,"t":"他對我說：「人子啊，你看見了嗎？」他帶我回到河邊。","notes":[]},{"n":7,"t":"我回到河邊時，看哪，河這邊與那邊的岸上有極多的樹木。","notes":[]},{"n":8,"t":"他對我說：「這水往東方流，下到亞拉巴，直到海。所流出來的水，一入海就使水變淡。","notes":["「直到海...一入海」：有古譯本是「一入臭水的海」。","「使水變淡」：原文是「使水得醫治」；下同。"]},{"n":9,"t":"這兩條河所到之處，凡滋生的動物都必存活；這水流到那裏，使那裏的水變淡，因此裏面有極多的魚。這河水所到之處，百物都必存活。","notes":["「這兩條河」：七十士譯本和其他古譯本是「這條河」。"]},{"n":10,"t":"必有漁夫站在河邊，從隱‧基底直到隱‧以革蓮，全都成了曬網的場所。那裏的魚各從其類，好像大海的魚甚多。","notes":["「曬」或譯「張」。"]},{"n":11,"t":"但是沼澤與池塘的水無法變淡，只能作產鹽之用。","notes":[]},{"n":12,"t":"河這邊與那邊的岸上必生長各類樹木，可作食物；葉子不枯乾，果子不斷絕。每月必結新果子，因為這水是從聖所流出來的。樹上的果子必作食物，葉子可以治病。」","notes":[]},{"n":13,"t":"主耶和華如此說：「這是你們按以色列十二支派分地為業的地界，約瑟要得兩份。","notes":[],"heads":["地界"]},{"n":14,"t":"你們承受這地為業，要彼此均分；我曾起誓應許將這地賜給你們的列祖，這地必歸你們為業。","notes":[]},{"n":15,"t":"「這地的疆界如下：北界從大海往希特倫，直到西達達口；","notes":[]},{"n":16,"t":"又往哈馬、比羅他、西伯蓮(西伯蓮在大馬士革的邊界與哈馬的邊界中間)，到浩蘭邊界的哈撒‧哈提干。","notes":["「直到西達達口；又往哈馬」：七十士譯本是「直到哈馬口；又往西達達」。"]},{"n":17,"t":"這樣，疆界是從大海往大馬士革地界上的哈薩‧以難，北邊以哈馬為界。這是北界。","notes":[]},{"n":18,"t":"「東界在浩蘭和大馬士革中間，基列和以色列地的中間，以約旦河為界。你們要量疆界直到東海。這是東界。","notes":["「你們要...到東海」：有古譯本是「疆界要從東海直到他瑪」。"]},{"n":19,"t":"「南界是從他瑪到加低斯的米利巴水，經埃及溪谷，直到大海。這是南界。","notes":["「埃及溪谷」：原文是「溪谷」。"]},{"n":20,"t":"「西界就是大海，從南界直到哈馬口對面。這是西界。","notes":[]},{"n":21,"t":"「你們要為自己按以色列的支派分這地。","notes":[]},{"n":22,"t":"要抽籤分這地為業，歸自己和那在你們中間寄居，生兒育女的外人。你們要看他們如本地出生的以色列人，他們要在以色列支派中與你們同得地業。","notes":[]},{"n":23,"t":"外人寄居在哪個支派，你們就在哪裏將地業分給他們。這是主耶和華說的。」","notes":[]}]},"48":{"heading":"各支派分配土地","verses":[{"n":1,"t":"眾支派的名字如下：從北邊盡頭，由希特倫往哈馬口，到大馬士革地界上的哈薩‧以難。北邊靠著哈馬地，從東到西是但的一份。","notes":[]},{"n":2,"t":"靠著但的地界，從東到西，是亞設的一份。","notes":[]},{"n":3,"t":"靠著亞設的地界，從東到西，是拿弗他利的一份。","notes":[]},{"n":4,"t":"靠著拿弗他利的地界，從東到西，是瑪拿西的一份。","notes":[]},{"n":5,"t":"靠著瑪拿西的地界，從東到西，是以法蓮的一份。","notes":[]},{"n":6,"t":"靠著以法蓮的地界，從東到西，是呂便的一份。","notes":[]},{"n":7,"t":"靠著呂便的地界，從東到西，是猶大的一份。","notes":[]},{"n":8,"t":"靠著猶大的地界，從東到西，必有你們所當獻的聖地，寬二萬五千肘；長短與各族從東到西所分的地相同，聖所當在其中。","notes":["原文沒有「肘」；下同。"],"heads":["中部的聖地"]},{"n":9,"t":"你們獻給耶和華的聖地要長二萬五千肘，寬一萬肘。","notes":[]},{"n":10,"t":"這聖地要歸祭司，北長二萬五千肘，西寬一萬肘，東寬一萬肘，南長二萬五千肘。耶和華的聖所當在其中。","notes":[]},{"n":11,"t":"這地要歸撒督的子孫中成為聖的祭司，他們謹守我所吩咐的；當以色列人走迷的時候，他們不像那些利未人走迷了。","notes":[]},{"n":12,"t":"在聖地中要特別保留一份歸他們，為至聖，緊鄰著利未人的地界。","notes":[]},{"n":13,"t":"利未人所得的地長二萬五千肘，寬一萬肘，與祭司的地界相等，都長二萬五千肘，寬一萬肘。","notes":[]},{"n":14,"t":"這地不可賣，不可換；這上好的部分不可轉讓給別人，因為它歸耶和華為聖。","notes":[]},{"n":15,"t":"剩下的地長二萬五千肘、寬五千肘，要作公用，為造城、蓋房、空地之用；城要在中間。","notes":[]},{"n":16,"t":"以下是城的大小：北面四千五百肘，南面四千五百肘，東面四千五百肘，西面四千五百肘。","notes":[]},{"n":17,"t":"城要有空地，向北二百五十肘，向南二百五十肘，向東二百五十肘，向西二百五十肘。","notes":[]},{"n":18,"t":"靠著聖地並排剩餘的，東長一萬肘，西長一萬肘；它與聖地並排，其中所出產的要作城內工人的食物。","notes":[]},{"n":19,"t":"以色列支派中所有在城內做工的，都要耕種這地。","notes":[]},{"n":20,"t":"你們要將整塊四方的聖地，長二萬五千肘，寬二萬五千肘，連同城的用地都獻作聖地。","notes":[]},{"n":21,"t":"聖地和城的用地兩邊剩餘的要歸給王。地的東邊，南北二萬五千肘，東至東界；西邊，南北二萬五千肘，西至西界；靠著各支派所分的地，都要歸給王。聖地和殿的聖所要在其中。","notes":[]},{"n":22,"t":"利未人的地與城的用地都在王的地中間，猶大邊界和便雅憫邊界之間，要歸給王。","notes":[]},{"n":23,"t":"論到其餘的支派，從東到西，是便雅憫的一份。","notes":[],"heads":["其他支派的土地"]},{"n":24,"t":"靠著便雅憫的地界，從東到西，是西緬的一份。","notes":[]},{"n":25,"t":"靠著西緬的地界，從東到西，是以薩迦的一份。","notes":[]},{"n":26,"t":"靠著以薩迦的地界，從東到西，是西布倫的一份。","notes":[]},{"n":27,"t":"靠著西布倫的地界，從東到西，是迦得的一份。","notes":[]},{"n":28,"t":"靠著迦得南邊的地界，界限從他瑪到加低斯的米利巴水，經埃及溪谷，直到大海。","notes":["「埃及溪谷」：原文是「溪谷」。"]},{"n":29,"t":"這就是你們要抽籤分給以色列支派為業之地，是他們各支派所得的份。這是主耶和華說的。","notes":[]},{"n":30,"t":"以下是城的出口：北面四千五百肘，","notes":[],"heads":["耶路撒冷的城門"]},{"n":31,"t":"城的各門要按以色列的支派命名。北面有三個門，一為呂便門，一為猶大門，一為利未門。","notes":[]},{"n":32,"t":"東面四千五百肘，有三個門，一為約瑟門，一為便雅憫門，一為但門。","notes":[]},{"n":33,"t":"南面四千五百肘，有三個門，一為西緬門，一為以薩迦門，一為西布倫門。","notes":[]},{"n":34,"t":"西面四千五百肘，有三個門，一為迦得門，一為亞設門，一為拿弗他利門。","notes":[]},{"n":35,"t":"城的周圍共一萬八千肘。從此以後，這城的名字必稱為「耶和華的所在」。","notes":[]}]}},"DAN":{"1":{"heading":"但以理和他的朋友","verses":[{"n":1,"t":"猶大王約雅敬在位第三年，巴比倫王尼布甲尼撒來到耶路撒冷，將城圍困。","notes":[],"heads":["但以理在尼布甲尼撒的宮廷裏"]},{"n":2,"t":"主將猶大王約雅敬和神殿中的一些器皿交在他的手中。他就把他們帶到示拿地他神明的廟裏，將器皿收入他神明的庫房中。","notes":[]},{"n":3,"t":"王吩咐太監長亞施毗拿，從以色列人的王室後裔和貴族中帶進幾個人來，","notes":[]},{"n":4,"t":"就是沒有殘疾、相貌俊美、通達各樣學問、知識聰明俱備、足能在王宮侍立的少年，要教他們迦勒底的文字和語言。","notes":["「學問」：原文是「智慧」；下同。"]},{"n":5,"t":"王從自己所用的膳和所飲的酒中，派給他們每日的分量，養育他們三年，好叫他們期滿以後侍立在王面前。","notes":[]},{"n":6,"t":"他們中間有猶大人但以理、哈拿尼雅、米沙利和亞撒利雅。","notes":[]},{"n":7,"t":"太監長給他們另外起名，稱但以理為伯提沙撒，稱哈拿尼雅為沙得拉，稱米沙利為米煞，稱亞撒利雅為亞伯尼歌。","notes":[]},{"n":8,"t":"但以理卻立志，不以王的膳和王所飲的酒玷污自己，於是懇求太監長容他不使自己玷污。","notes":[]},{"n":9,"t":"神使但以理在太監長眼前蒙恩，得憐憫。","notes":[]},{"n":10,"t":"太監長對但以理說：「我懼怕我主我王，他已經派給你們的飲食，何必讓他見你們的面貌比你們同年齡的少年憔悴呢？這樣，你們就使我的頭在王那裏不保了。」","notes":[]},{"n":11,"t":"但以理對太監長所派監管但以理、哈拿尼雅、米沙利、亞撒利雅的管理者說：","notes":[]},{"n":12,"t":"「請你考驗僕人們十天，給我們素菜吃，清水喝，","notes":[]},{"n":13,"t":"然後你親自觀察我們的面貌和那用王膳的少年的面貌；就照你所觀察的待你的僕人吧！」","notes":[]},{"n":14,"t":"管理者准許他們這件事，考驗他們十天。","notes":[]},{"n":15,"t":"過了十天，他們的身材看來比所有享用王膳的少年更加俊美健壯，","notes":[]},{"n":16,"t":"於是管理者撤去王派給他們用的膳和所飲的酒，只給他們素菜。","notes":[]},{"n":17,"t":"這四個少年，神在各樣文字學問上賜給他們知識和聰明；但以理又明白各樣異象和夢兆。","notes":[]},{"n":18,"t":"王吩咐帶他們進宮的日子到了，太監長就把他們帶到尼布甲尼撒面前。","notes":[]},{"n":19,"t":"王與他們談論，在所有少年中找不到人能與但以理、哈拿尼雅、米沙利、亞撒利雅相比，於是他們就在王面前侍立。","notes":[]},{"n":20,"t":"王考問他們一切智慧和聰明的事，發現他們比全國所有的術士和巫師勝過十倍。","notes":[]},{"n":21,"t":"到居魯士王元年，但以理還健在。","notes":[]}]},"2":{"heading":"神指示但以理","verses":[{"n":1,"t":"尼布甲尼撒在位第二年，他做了很多夢，心裏煩亂，不能睡覺。","notes":[]},{"n":2,"t":"王吩咐人將術士、巫師、行邪術的和迦勒底人召來，要他們把王的夢告訴王；他們就來，站在王面前。","notes":[]},{"n":3,"t":"王對他們說：「我做了一個夢，心裏煩亂，想要知道這是甚麼夢。」","notes":[]},{"n":4,"t":"迦勒底人用亞蘭話對王說：「願王萬歲！請將夢告訴僕人，我們就可以講解。」","notes":["從「願王萬歲」開始到第七章結尾，原文是亞蘭文。"]},{"n":5,"t":"王回答迦勒底人說：「這事我已決定，你們若不把夢和夢的解釋告訴我，就必被凌遲，你們的房屋必成糞堆；","notes":[]},{"n":6,"t":"但你們若能說出這個夢和夢的解釋，就必從我得到禮物、賞賜和殊榮。現在，你們要把夢和夢的解釋告訴我。」","notes":[]},{"n":7,"t":"他們再一次回答說：「請王將夢告訴僕人，我們就可以講解。」","notes":[]},{"n":8,"t":"王回答說：「我確實知道你們是故意拖延，因為你們知道這事我已決定。","notes":[]},{"n":9,"t":"你們若不將夢告訴我，只有一個辦法對待你們；因為你們彼此串通，向我胡言亂語，要等候情勢改變。現在，你們要將夢告訴我，讓我知道你們真能為我解夢。」","notes":[]},{"n":10,"t":"迦勒底人回答王說：「世上沒有人能解釋王的事情；從來沒有君王、大臣、掌權者向術士、巫師，或迦勒底人問過這樣的事。","notes":[]},{"n":11,"t":"王所問的事很難，除了不與血肉之軀同住的神，沒有人能在王面前解釋。」","notes":[]},{"n":12,"t":"王因這事生氣，大大震怒，吩咐滅絕巴比倫所有的智慧人。","notes":[]},{"n":13,"t":"命令發出，智慧人將要被殺，人就尋找但以理和他的同伴，要殺他們。","notes":[]},{"n":14,"t":"王的護衛長亞略奉命去殺巴比倫的智慧人，但以理用婉言和智慧回應，","notes":[]},{"n":15,"t":"向王的大臣亞略說：「王的命令為何這樣緊急呢？」亞略就把事情告訴但以理。","notes":[]},{"n":16,"t":"於是但以理進去求王寬限，好為王解夢。","notes":[]},{"n":17,"t":"但以理回到他的居所，把這事告訴他的同伴哈拿尼雅、米沙利、亞撒利雅，","notes":[]},{"n":18,"t":"要他們祈求天上的神施憐憫，將這奧祕指明，免得但以理和他的同伴與巴比倫其餘的智慧人一同滅亡。","notes":[]},{"n":19,"t":"這奧祕就在夜間異象中顯明給但以理，但以理就稱頌天上的神。","notes":[]},{"n":20,"t":"但以理說：「神的名是應當稱頌的，從亙古直到永遠！因為智慧和能力都屬乎他。","notes":[]},{"n":21,"t":"他改變時間、季節，他廢王，立王；將智慧賜給智慧人，將知識賜給聰明人。","notes":[]},{"n":22,"t":"他顯明深奧隱祕的事，洞悉幽暗中的一切，光明也與他同住。","notes":[]},{"n":23,"t":"我列祖的神啊，我感謝你，讚美你，因你將智慧才能賜給我，我們所求問的現在你已指明給我，把王的事給我們指明。」","notes":[]},{"n":24,"t":"於是，但以理進到王所派滅絕巴比倫智慧人的亞略那裏去，對他這樣說：「不要滅絕巴比倫的智慧人，求你領我到王面前，我可以為王解夢。」","notes":[],"heads":["但以理解夢"]},{"n":25,"t":"亞略就急忙領但以理到王面前，對王這樣說：「我在被擄的猶大人中找到一人，能將夢的解釋告訴王。」","notes":[]},{"n":26,"t":"王對那稱為伯提沙撒的但以理說：「你能將我所做的夢和夢的解釋告訴我嗎？」","notes":[]},{"n":27,"t":"但以理回答王說：「王所問的那奧祕，智慧人、巫師、術士、觀兆的都不能告訴王，","notes":[]},{"n":28,"t":"只有那在天上的神能顯明奧祕。他已把日後將要發生的事指示尼布甲尼撒王。你在床上做的夢和你腦中的異象是這樣：","notes":[]},{"n":29,"t":"你，王啊，你在床上所思想的是關乎日後的事，那顯明奧祕的主已把將來要發生的事指示你。","notes":[]},{"n":30,"t":"至於我，那奧祕顯明給我，並非因我智慧勝過一切活著的人，而是為了讓王知道夢的解釋，知道你心裏的意念。","notes":[]},{"n":31,"t":"「你，王啊，你正觀看，看哪，有一個很大的像，這像甚高，極其光耀，立在你面前，形狀非常可怕。","notes":[]},{"n":32,"t":"這像的頭是純金的，胸膛和膀臂是銀的，腹部和腰是銅的，","notes":[]},{"n":33,"t":"腿是鐵的，腳是半鐵半泥的。","notes":[]},{"n":34,"t":"你正觀看，見有一塊非人手鑿出來的石頭打在它半鐵半泥的腳上，把腳砸碎；","notes":[]},{"n":35,"t":"於是鐵、泥、銅、銀、金都一同砸得粉碎，如夏天禾場上的糠秕，被風吹散，無處可尋。打碎這像的石頭成了一座大山，覆蓋全地。","notes":[]},{"n":36,"t":"「這就是那夢；我們要在王面前講解那夢。","notes":[]},{"n":37,"t":"你，王啊，你是諸王之王。天上的神已將國度、權勢、能力、尊榮都賜給你。","notes":[]},{"n":38,"t":"世人和走獸，並天空的飛鳥，不論居住何處，他都交在你的手中，令你掌管這一切。你就是那金的頭。","notes":[]},{"n":39,"t":"在你以後必興起另一國，不及於你；又有第三國如銅，必掌管全地。","notes":[]},{"n":40,"t":"第四國必堅壯如鐵，就像鐵能打碎砸碎一切；鐵怎樣壓碎一切，那國也必照樣打碎壓碎。","notes":[]},{"n":41,"t":"你既看見像的腳和腳趾頭，一半是陶匠的泥，一半是鐵，那國將來也必分裂。你既看見鐵和泥攙雜，那國也必有鐵的力量。","notes":[]},{"n":42,"t":"那腳趾頭既是半鐵半泥，那國也必半強半弱。","notes":[]},{"n":43,"t":"你既看見鐵和泥攙雜，他們必有混雜的後裔，卻不能彼此相合，正如鐵和泥不能相合。","notes":[]},{"n":44,"t":"當諸王在位的時候，天上的神必另立一個永不敗壞的國度，這國度必不歸給其他百姓，卻要打碎滅絕所有的國度，存立到永遠。","notes":[]},{"n":45,"t":"你既看見非人手鑿出來的一塊石頭從山而出，打碎鐵、銅、泥、銀、金，那就是至大的神把將來要發生的事給王指明。這夢是確實的，這解釋也是準確的。」","notes":[]},{"n":46,"t":"當時，尼布甲尼撒王臉伏於地，向但以理下拜，並且吩咐人給他奉上供物和香。","notes":[],"heads":["王獎賞但以理"]},{"n":47,"t":"王對但以理說：「你既能講明這奧祕，你們的神誠然是萬神之神、萬王之主，是奧祕的啟示者。」","notes":[]},{"n":48,"t":"於是王使但以理高升，賞賜他極多的禮物，派他管理巴比倫全省，又立他為總理，掌管巴比倫所有的智慧人。","notes":[]},{"n":49,"t":"但以理求王，王就派沙得拉、米煞、亞伯尼歌管理巴比倫省的事務，只是但以理仍在朝中侍立。","notes":[]}]},"3":{"heading":"尼布甲尼撒下令拜金像","verses":[{"n":1,"t":"尼布甲尼撒王造了一個金像，高六十肘，寬六肘，立在巴比倫省的杜拉平原。","notes":[]},{"n":2,"t":"尼布甲尼撒王差人將總督、欽差、省長、參謀、財務、法官、地方官和各省的官員都召了來，為尼布甲尼撒王所立的像行開光禮。","notes":[]},{"n":3,"t":"於是總督、欽差、省長、參謀、財務、法官、地方官和各省的官員都聚集，站在尼布甲尼撒所立的像前，要為尼布甲尼撒王所立的像行開光禮。","notes":[]},{"n":4,"t":"那時傳令的大聲呼叫說：「各方、各國、各族的人哪，有命令傳給你們：","notes":["「族」：原文是「舌」；下同。"]},{"n":5,"t":"你們一聽見角、號、琴、瑟、三角琴、鼓和各樣樂器的聲音，就當俯伏，拜尼布甲尼撒王所立的金像。","notes":[]},{"n":6,"t":"凡不俯伏下拜的，必立刻扔在烈火的窯中。」","notes":[]},{"n":7,"t":"因此百姓一聽見角、號、琴、瑟、三角琴和各樣樂器的聲音，各方、各國、各族的人就都俯伏，拜尼布甲尼撒王所立的金像。","notes":["有古卷在此有「鼓」。"]},{"n":8,"t":"在那時，有幾個迦勒底人進前來控告猶大人。","notes":[],"heads":["但以理的三個朋友被控違令"]},{"n":9,"t":"他們對尼布甲尼撒王說：「願王萬歲！","notes":[]},{"n":10,"t":"你，王啊，你曾降旨，凡聽見角、號、琴、瑟、三角琴、鼓和各樣樂器聲音的，都當俯伏拜這金像。","notes":[]},{"n":11,"t":"凡不俯伏下拜的，必扔在烈火的窯中。","notes":[]},{"n":12,"t":"現在有幾個猶大人，就是王所派管理巴比倫省事務的沙得拉、米煞、亞伯尼歌；王啊，這些人不理你的諭旨，不事奉你的神明，也不拜你所立的金像。」","notes":[]},{"n":13,"t":"當時，尼布甲尼撒大發烈怒，命令把沙得拉、米煞、亞伯尼歌帶過來；他們就把這幾個人帶到王面前。","notes":[]},{"n":14,"t":"尼布甲尼撒問他們說：「沙得拉、米煞、亞伯尼歌，你們不事奉我的神明，不拜我所立的金像，是真的嗎？","notes":[]},{"n":15,"t":"現在，你們若準備好，一聽見角、號、琴、瑟、三角琴、鼓和各樣樂器的聲音，就俯伏拜我所造的像；若不下拜，必立刻扔在烈火的窯中，有哪一個神明能救你們脫離我的手呢？」","notes":[]},{"n":16,"t":"沙得拉、米煞、亞伯尼歌對王說：「尼布甲尼撒啊，這件事我們不必回答你，","notes":[]},{"n":17,"t":"即便如此，我們所事奉的神能將我們從烈火的窯中救出來。王啊，他必救我們脫離你的手；","notes":[]},{"n":18,"t":"即或不然，王啊，你當知道，我們絕不事奉你的神明，也不拜你所立的金像。」","notes":[]},{"n":19,"t":"當時，尼布甲尼撒怒氣填胸，向沙得拉、米煞、亞伯尼歌變了臉色，命令把窯燒熱，比平常熱七倍；","notes":[],"heads":["但以理的三個朋友被扔進火窯"]},{"n":20,"t":"又命令他軍中的幾個壯士，把沙得拉、米煞、亞伯尼歌捆起來，扔在烈火的窯中。","notes":[]},{"n":21,"t":"這三人穿著內袍、外衣、頭巾和其他的衣服，被捆起來扔在烈火的窯中。","notes":[]},{"n":22,"t":"因為王的命令緊急，窯又非常熱，那抬沙得拉、米煞、亞伯尼歌的人都被火焰燒死。","notes":[]},{"n":23,"t":"但是這三個人，沙得拉、米煞、亞伯尼歌被捆綁著，掉進烈火的窯中。","notes":[]},{"n":24,"t":"那時，尼布甲尼撒王驚奇，急忙站起來，對謀士說：「我們捆起來扔在火裏的不是三個人嗎？」他們回答王說：「王啊，是的。」","notes":[]},{"n":25,"t":"王說：「看哪，我看見有四個人，並沒有捆綁，在火中行走，也沒有受傷；那第四個的相貌好像神明的兒子。」","notes":[]},{"n":26,"t":"於是尼布甲尼撒靠近烈火窯門，說：「至高神的僕人沙得拉、米煞、亞伯尼歌，出來，來吧！」沙得拉、米煞、亞伯尼歌就從火中出來。","notes":[],"heads":["三人獲釋且得高升"]},{"n":27,"t":"那些總督、欽差、省長和王的謀士一同聚集來看這三個人，見火不能傷他們的身體，頭髮沒有燒焦，衣裳也沒有變色，都沒有火燒過的氣味。","notes":[]},{"n":28,"t":"尼布甲尼撒說：「沙得拉、米煞、亞伯尼歌的神是應當稱頌的！他差遣使者救護倚靠他的僕人，他們不遵王的命令，甚至捨身，在他們神以外不肯事奉敬拜別神。","notes":[]},{"n":29,"t":"現在我降旨，無論何方、何國、何族，凡有人毀謗沙得拉、米煞、亞伯尼歌的神，他必被凌遲，他的房屋必成糞堆，因為沒有別神能像這樣施行拯救。」","notes":[]},{"n":30,"t":"那時王在巴比倫省使沙得拉、米煞、亞伯尼歌高升。","notes":[]}]},"4":{"heading":"尼布甲尼撒的第二個夢","verses":[{"n":1,"t":"尼布甲尼撒王對住在全地各方、各國、各族的人說：「願你們大享平安！","notes":[]},{"n":2,"t":"我樂意宣揚至高神向我所行的神蹟奇事。","notes":[]},{"n":3,"t":"他的神蹟何其大！他的奇事何其盛！他的國度存到永遠；他的權柄存到萬代！","notes":[]},{"n":4,"t":"「我－尼布甲尼撒安居在家中，在宮裏享受榮華。","notes":[]},{"n":5,"t":"我做了一個夢，使我懼怕。我在床上的意念和腦中的異象，使我驚惶。","notes":[]},{"n":6,"t":"因此我降旨召巴比倫的智慧人全都到我面前，要他們將夢的解釋告訴我。","notes":[]},{"n":7,"t":"於是那些術士、巫師、迦勒底人、觀兆的都進來，我將那夢告訴他們，他們卻不能把夢的解釋告訴我。","notes":[]},{"n":8,"t":"最後，但以理，就是按照我神明的名字稱為伯提沙撒的，來到我面前，他裏頭有神聖神明的靈，我將夢告訴他：","notes":[]},{"n":9,"t":"『術士的領袖伯提沙撒啊，我知道你裏頭有神聖神明的靈，甚麼奧祕都不能為難你。現在你要把我夢中所見的異象和夢的解釋告訴我。』","notes":["「現在...告訴我」：七十士譯本是「現在你要聽我在夢中所見的異象，把夢的解釋告訴我」。"]},{"n":10,"t":"「我在床上腦中的異象是這樣：我觀看，看哪，大地中間有一棵樹，極其高大。","notes":[]},{"n":11,"t":"那樹漸長，而且茁壯，高得頂天，從地極都能看見，","notes":[]},{"n":12,"t":"葉子華美，果子甚多，可作所有動物的食物；野地的走獸臥在蔭下，天空的飛鳥宿在枝上，凡有血肉的都從這樹得食物。","notes":[]},{"n":13,"t":"「我觀看，我在床上腦中的異象是這樣，看哪，有守望者，就是神聖的一位，從天而降，","notes":[]},{"n":14,"t":"大聲呼叫說：『砍倒這樹！砍下枝子！拔掉葉子！拋散果子！使走獸逃離樹下，飛鳥躲開樹枝。","notes":[]},{"n":15,"t":"樹的殘幹卻要留在地裏，在田野的青草中用鐵圈和銅圈套住。任他讓天上的露水滴濕，和地上的走獸一同吃草，","notes":[]},{"n":16,"t":"使他的心改變，不再是人的心，而給他一個獸心，使他經過七個時期。","notes":["「七個時期」或譯「七年」；下同。"]},{"n":17,"t":"這是眾守望者所發的命令，是眾聖者所作的決定，好叫世人知道至高者在人的國中掌權，要將國賜給誰就賜給誰，並且立極卑微的人執掌國權。』","notes":[]},{"n":18,"t":"「這是我－尼布甲尼撒王所做的夢。伯提沙撒啊，你要說明這夢的解釋；我國中所有的智慧人都不能把夢的解釋告訴我，惟獨你能，因你裏頭有神聖神明的靈。」","notes":[]},{"n":19,"t":"於是稱為伯提沙撒的但以理驚駭片時，心意驚惶。王說：「伯提沙撒啊，不要因夢和夢的解釋驚惶。」伯提沙撒回答說：「我主啊，願這夢歸給恨惡你的人，這夢的解釋歸給你的敵人。","notes":[],"heads":["但以理解夢"]},{"n":20,"t":"你所見的樹漸長，而且茁壯，高得頂天，全地都能看見，","notes":[]},{"n":21,"t":"葉子華美，果子甚多，可作所有動物的食物；野地的走獸住在其下，天空的飛鳥宿在枝上。","notes":[]},{"n":22,"t":"「王啊，這成長又茁壯的樹就是你。你的威勢成長及於天，你的權柄達到地極。","notes":[]},{"n":23,"t":"王既看見一位神聖的守望者從天而降，說：『將這樹砍倒毀壞，樹的殘幹卻要留在地裏，在田野的青草中用鐵圈和銅圈套住。任他讓天上的露水滴濕，與野地的走獸一同吃草，直到經過七個時期。』","notes":[]},{"n":24,"t":"「王啊，夢的解釋就是這樣：臨到我主我王的事是出於至高者的命令。","notes":[]},{"n":25,"t":"你必被趕出離開世人，與野地的走獸同住，吃草如牛，讓天上的露水滴濕，且要經過七個時期，直等到你知道至高者在人的國中掌權，要將國賜給誰就賜給誰。","notes":[]},{"n":26,"t":"這使樹的殘幹存留的命令，是要等你知道天在掌權，你的國必定歸你。","notes":[]},{"n":27,"t":"王啊，求你悅納我的諫言，以施行公義除去罪過，以憐憫窮人除掉罪惡，或者你的平安可以延長。」","notes":[]},{"n":28,"t":"這些事都臨到尼布甲尼撒王。","notes":[]},{"n":29,"t":"過了十二個月，他在巴比倫王宮頂上散步。","notes":[]},{"n":30,"t":"王說：「這大巴比倫豈不是我用大能大力建為首都，要顯示我威嚴的榮耀嗎？」","notes":[]},{"n":31,"t":"這話還在王口中的時候，有聲音從天降下，說：「尼布甲尼撒王啊，有話對你說，你的國離開你了。","notes":[]},{"n":32,"t":"你必被趕出離開世人，與野地的走獸同住，吃草如牛，且要經過七個時期；等你知道至高者在人的國中掌權，要將國賜給誰就賜給誰。」","notes":[]},{"n":33,"t":"當時這話就應驗在尼布甲尼撒身上，他被趕出離開世人，吃草如牛，身體被天上的露水滴濕，頭髮長得像鷹的羽毛，指甲長得像鳥爪。","notes":[]},{"n":34,"t":"「時候到了，我－尼布甲尼撒舉目望天，我的知識復歸於我，我就稱頌至高者，讚美尊敬活到永遠的神。他的權柄存到永遠，他的國度存到萬代。","notes":[],"heads":["尼布甲尼撒頌讚神"]},{"n":35,"t":"地上所有的居民都算為虛無；在天上萬軍和地上居民中，他都憑自己的旨意行事。無人能攔住他的手，或問他說，你在做甚麼呢？","notes":[]},{"n":36,"t":"「那時，我的知識復歸於我，威嚴和光榮也復歸於我，使我的國度得榮耀，我的謀士和大臣也來朝見我。我又重建我的國度，更大的權勢加添在我身上。","notes":[]},{"n":37,"t":"現在我－尼布甲尼撒讚美、尊崇、恭敬天上的王，因為他所行的全都信實，他所做的盡都公平。那行事驕傲的，他能降為卑。」","notes":[]}]},"5":{"heading":"伯沙撒王的宴會","verses":[{"n":1,"t":"伯沙撒王為他的一千大臣擺設盛筵，與這一千人飲酒。","notes":[]},{"n":2,"t":"伯沙撒在歡飲之間，吩咐人將他父尼布甲尼撒從耶路撒冷聖殿所擄掠的金銀器皿拿來，好使王與大臣、王后、妃嬪用這器皿飲酒。","notes":["「父」或譯「祖」；下同。"]},{"n":3,"t":"於是他們把聖殿，就是耶路撒冷神殿中所擄掠的金器皿拿來，王和大臣、王后、妃嬪就用這器皿飲酒。","notes":[]},{"n":4,"t":"他們飲酒，讚美金、銀、銅、鐵、木、石造的神明。","notes":[]},{"n":5,"t":"當時，忽然有人的指頭出現，在燈臺對面王宮粉刷的牆上寫字。王看見寫字的指頭，","notes":[]},{"n":6,"t":"就變了臉色，心意驚惶，腰骨好像脫節，雙膝彼此相碰，","notes":[]},{"n":7,"t":"大聲吩咐將巫師、迦勒底人和觀兆的領進來。王對巴比倫的智慧人說：「誰能讀這文字，並且向我講解它的意思，他必身穿紫袍，項帶金鏈，在我國中位列第三。」","notes":[]},{"n":8,"t":"於是王所有的智慧人都進前來，他們卻不能讀那文字，也不能為王講解它的意思。","notes":[]},{"n":9,"t":"伯沙撒王就甚驚惶，臉色改變，他的大臣也都困惑。","notes":[]},{"n":10,"t":"太后因王和他大臣所說的話，就進入宴會廳，說：「願王萬歲！你的心不要驚惶，臉不要變色。","notes":["「太后」或譯「王后」；下同。"]},{"n":11,"t":"在你國中有一人，他裏頭有神聖神明的靈，你父在世的日子，這人心中光明，又有聰明智慧，好像神明的智慧。你父尼布甲尼撒王，就是王的父，曾立他為術士、巫師、迦勒底人和觀兆者的領袖，","notes":[]},{"n":12,"t":"都因為他有美好的靈性，又有知識聰明，能解夢，釋謎語，解疑惑。這人名叫但以理，尼布甲尼撒王又稱他為伯提沙撒，現在可以召他來，他必解明這意思。」","notes":[]},{"n":13,"t":"於是但以理被領到王面前。王問但以理說：「你就是我父王從猶大帶來、被擄的猶大人但以理嗎？","notes":[],"heads":["但以理解釋牆上的字"]},{"n":14,"t":"我聽說你裏頭有神明的靈，心中有光，又有聰明和高超的智慧。","notes":[]},{"n":15,"t":"現在智慧人和巫師都被帶到我面前，要叫他們讀這文字，為我講解它的意思；無奈他們都不能講解它的意思。","notes":[]},{"n":16,"t":"我聽說你能講解，能解疑惑；現在你若能讀這文字，為我講解它的意思，就必身穿紫袍，項戴金鏈，在我國中位列第三。」","notes":[]},{"n":17,"t":"但以理回答王說：「你的禮物可以歸你自己，你的賞賜可以歸給別人；我卻要為王讀這文字，講解它的意思。","notes":[]},{"n":18,"t":"你，王啊，至高的神曾將國度、大權、榮耀、威嚴賜給你父尼布甲尼撒；","notes":[]},{"n":19,"t":"因神所賜給他的大權，各方、各國、各族的人都在他面前恐懼戰兢，因他要殺就殺，要人活就活，要升就升，要降就降。","notes":[]},{"n":20,"t":"但他的心高傲，靈也剛愎，以致行事狂傲，就被革去國度的王位，奪走榮耀。","notes":[]},{"n":21,"t":"他被趕出離開世人，他的心變為獸心，與野驢同住，吃草如牛，身體被天上的露水滴濕，直到他知道，至高的神在人的國中掌權，憑自己的旨意立人治國。","notes":[]},{"n":22,"t":"伯沙撒啊，你是他的兒子，你雖知道這一切，卻不謙卑自己，","notes":["「兒子」或譯「孫子」。"]},{"n":23,"t":"竟向天上的主自高，差人將他殿中的器皿拿到你面前，你和大臣、王后、妃嬪用這器皿飲酒。你又讚美那不能看、不能聽、無知無識，用金、銀、銅、鐵、木、石造的神明，沒有將榮耀歸與那手中掌管你氣息，管理你一切行動的神。","notes":[]},{"n":24,"t":"於是從他那裏顯出指頭寫這文字。","notes":[]},{"n":25,"t":"「所寫的文字是：『彌尼，彌尼，提客勒，烏法珥新。』","notes":["「烏法珥新」﹕亞蘭文音譯；原文另譯「以及毗勒斯」；參28節。"]},{"n":26,"t":"解釋是這樣：彌尼就是神數算你國的年日到此完畢。","notes":[]},{"n":27,"t":"提客勒就是你被秤在天平上，秤出你的虧欠來。","notes":[]},{"n":28,"t":"毗勒斯就是你的國要分裂，歸給瑪代人和波斯人。」","notes":["「毗勒斯」與「烏法珥新」同義。"]},{"n":29,"t":"於是伯沙撒下令，人就把紫袍給但以理穿上，把金鏈給他戴在頸項上，又傳令使他在國中位列第三。","notes":[]},{"n":30,"t":"當夜，迦勒底王伯沙撒被殺。","notes":[]},{"n":31,"t":"瑪代人大流士年六十二歲，取了迦勒底國。","notes":[]}]},"6":{"heading":"但以理在獅子坑中","verses":[{"n":1,"t":"大流士隨心所願，立了一百二十個總督，治理全國，","notes":[]},{"n":2,"t":"又在他們以上立總長三人，但以理也在其中；使總督在他們三人面前呈報，免得王受虧損。","notes":[]},{"n":3,"t":"這但以理因有卓越的靈性，超乎其餘的總長和總督，王想立他治理全國。","notes":[]},{"n":4,"t":"那時，總長和總督在治國的事務上尋找但以理的把柄，為要控告他；只是找不到任何的把柄和過失，因他忠心辦事，毫無錯誤過失。","notes":[]},{"n":5,"t":"那些人就說：「我們要找但以理的把柄，若不從他神的律法中下手，就尋不著。」","notes":[]},{"n":6,"t":"於是，總長和總督紛紛聚集來見王，說：「大流士王萬歲！","notes":[]},{"n":7,"t":"國中的總長、欽差、總督、謀士和省長彼此商議，求王下旨，立一條禁令，三十天之內，不拘何人，若在王以外，或向神明或向人求甚麼，就必扔在獅子坑中。","notes":[]},{"n":8,"t":"王啊，現在求你立這禁令，在這文件上簽署，使它不能更改；照瑪代人和波斯人的例，絕不更動。」","notes":[]},{"n":9,"t":"於是大流士王在這禁令的文件上簽署。","notes":[]},{"n":10,"t":"但以理知道這文件已經簽署，就進自己的家，他家樓上的窗戶開向耶路撒冷。他一天三次，雙膝跪著，在他的神面前禱告感謝，像平常一樣。","notes":[]},{"n":11,"t":"於是，那些人紛紛聚集，發現但以理在他神面前祈禱懇求。","notes":[]},{"n":12,"t":"他們就進到王面前，向王提及禁令，說：「三十天之內不拘何人，若在王以外，或向神明或向人求甚麼，必被扔在獅子坑中，王不是在這禁令上簽署了嗎？」王回答說：「確有這事，照瑪代人和波斯人的例是不可更改的。」","notes":[]},{"n":13,"t":"他們對王說：「王啊，那被擄的猶大人但以理不理會你，也不遵守你簽署的禁令，竟一天三次祈禱。」","notes":[]},{"n":14,"t":"王聽見這話，就甚愁煩，一心要救但以理，直到日落的時候，他還在籌劃解救他。","notes":[]},{"n":15,"t":"那些人就紛紛聚集到王那裏，對王說：「王啊，當知道瑪代人和波斯人有例，凡王所立的禁令和律例都不可更改。」","notes":[]},{"n":16,"t":"於是王下令，人就把但以理帶來，扔在獅子坑中。王對但以理說：「你經常事奉的神，他必拯救你。」","notes":[]},{"n":17,"t":"有人搬來一塊石頭放在坑口，王用自己的璽和大臣的印，封閉那坑，使懲辦但以理的事絕不更改。","notes":[]},{"n":18,"t":"王回到宮裏，終夜禁食，不讓人帶樂器到他面前，他也失眠了。","notes":["「樂器」或譯「跳舞的女子」或「食物」。"]},{"n":19,"t":"次日黎明，王起來，急忙往獅子坑那裏去，","notes":[]},{"n":20,"t":"臨近坑邊，哀聲呼叫但以理。王對但以理說：「永生神的僕人但以理啊，你經常事奉的神能救你脫離獅子嗎？」","notes":[]},{"n":21,"t":"但以理對王說：「願王萬歲！","notes":[]},{"n":22,"t":"我的神差遣使者封住獅子的口，叫獅子不傷我，因我在神面前無辜。王啊，在你面前我也沒有做過任何虧損的事。」","notes":[]},{"n":23,"t":"王因此就甚喜樂，吩咐把但以理從坑裏拉上來。於是但以理從坑裏被拉上來，身上毫無損傷，因為他信靠他的神。","notes":[]},{"n":24,"t":"王下令，把那些控告但以理的人和他們的妻子兒女都帶來，扔在獅子坑中。他們還沒有到坑底，獅子就制伏他們，咬碎他們的骨頭。","notes":[]},{"n":25,"t":"於是，大流士王傳旨給住在全地各方、各國、各族的人說：「願你們大享平安！","notes":[]},{"n":26,"t":"現在我降旨，我所統轄全國的人民，都要在但以理的神面前戰兢畏懼。因為他是活的神，永遠長存，他的國度永不敗壞，他的權柄永存無極！","notes":[]},{"n":27,"t":"他庇護，搭救，在天上地下施行神蹟奇事，救了但以理脫離獅子的口。」","notes":[]},{"n":28,"t":"如此，這但以理，當大流士在位的時候和波斯的居魯士在位的時候，大享亨通。","notes":[]}]},"7":{"heading":"但以理敘述異象","verses":[{"n":1,"t":"巴比倫王伯沙撒元年，但以理在床上做夢，腦中看見異象，就記錄這夢，述說其中的大意。","notes":[],"heads":["四獸的異象"]},{"n":2,"t":"但以理說：我在夜間的異象中觀看，看哪，天上有四風，突然颳在大海之上。","notes":[]},{"n":3,"t":"有四隻巨獸從海裏上來，牠們各不相同：","notes":[]},{"n":4,"t":"頭一個像獅子，有鷹的翅膀；我正觀看的時候，牠的翅膀被拔去，牠從地上被扶起來，用兩腳站立，像人一樣，還給了牠人的心。","notes":[]},{"n":5,"t":"看哪，另有一獸如熊，就是第二獸，半身側立，口裏的牙齒中有三根獠牙。有人吩咐這獸說：「起來，吞吃許多的肉。」","notes":["「獠牙」或譯「肋骨」。"]},{"n":6,"t":"其後，我觀看，看哪，另有一獸如豹，背上有四個鳥的翅膀；這獸有四個頭，還給了牠權柄。","notes":[]},{"n":7,"t":"其後，我在夜間的異象中觀看，看哪，第四獸可怕可懼，極其強壯，有大鐵牙，吞吃嚼碎，剩下的用腳踐踏。這獸與前面所有的獸不同，牠有十隻角。","notes":[]},{"n":8,"t":"我正思考這些角的時候，看哪，其中又長出另一隻小角；先前的角中有三隻角在它面前連根被拔出。看哪，這角有眼，像人的眼，有口說誇大的話。","notes":[]},{"n":9,"t":"我正觀看的時候，有寶座設立，上面坐著亙古常在者。他的衣服潔白如雪，頭髮如純淨的羊毛。寶座是火焰，其輪為烈火。","notes":[],"heads":["永存者的異象"]},{"n":10,"t":"有火如河湧出，從他面前流出來；事奉他的有千千，在他面前侍立的有萬萬；他坐著要行審判，案卷都展開了。","notes":["「他坐著要行審判」或譯「審判即將開始」；26節同。"]},{"n":11,"t":"於是我觀看，因這角說誇大的話，我正觀看的時候，那獸被殺，身體被毀，扔在火中焚燒。","notes":[]},{"n":12,"t":"其餘的獸，權柄都被奪去，生命卻得以延續，直到所定的時候和日期。","notes":[]},{"n":13,"t":"我在夜間的異象中觀看，看哪，有一位像人子的，駕著天上的雲而來，被領到亙古常在者面前。","notes":[]},{"n":14,"t":"他得了權柄、榮耀、國度，使各方、各國、各族的人都事奉他。他的權柄是永遠的，不能廢去，他的國度必不敗壞。","notes":[]},{"n":15,"t":"至於我－但以理，我的靈在我裏面憂傷，我腦中的異象使我驚惶。","notes":[],"heads":["解釋異象"]},{"n":16,"t":"我走近其中一位侍立者，問他這一切的實情。他就告訴我，使我知道這事的解釋：","notes":[]},{"n":17,"t":"這四隻巨獸就是將要在世上興起的四個王。","notes":["「王」：有古卷、七十士譯本和其他古譯本是「國度」。"]},{"n":18,"t":"然而，至高者的眾聖者必要得到這國度，並且擁有它，直到永遠，永永遠遠。","notes":[]},{"n":19,"t":"於是我想要更清楚知道第四獸的實情，牠與一切的獸不同，甚是可怕，有鐵牙銅爪，吞吃嚼碎，剩下的用腳踐踏；","notes":[]},{"n":20,"t":"頭上有十隻角和那另長出的一角，三隻角在這角面前掉落；這角有眼，有口說誇大的話，形狀比牠的同類更強。","notes":[]},{"n":21,"t":"我觀看，這角與眾聖者爭戰，勝了他們，","notes":[]},{"n":22,"t":"直到亙古常在者來到，為至高者的眾聖者伸冤，眾聖者得到國度的時候就到了。","notes":[]},{"n":23,"t":"那侍立者這樣說：第四獸就是世上要興起的第四國，與其他各國不同，它要併吞全地，並且踐踏嚼碎。","notes":[]},{"n":24,"t":"至於那十隻角，就是從這國中興起的十個王；後來又興起另一王，與先前的不相同，他要制伏三個王。","notes":[]},{"n":25,"t":"他說話抵擋至高者，折磨至高者的眾聖者，又改變節期和律法。眾聖者要交在他手中一年、兩年、又半年。","notes":["「年」或譯「時期」；下同。"]},{"n":26,"t":"然而，他坐著要行審判；他的權柄要被奪去，毀壞，滅絕，一直到底。","notes":[]},{"n":27,"t":"國度、權柄和天下諸國的大權必賜給至高者的眾聖民。他的國是永遠的國，所有掌權的都必事奉他，順從他。","notes":[]},{"n":28,"t":"這事到此結束。我－但以理因這些念頭甚是驚惶，臉色也變了，卻將這事記在心裏。","notes":[]}]},"8":{"heading":"公綿羊、公山羊的異象","verses":[{"n":1,"t":"伯沙撒王在位第三年，有異象向我－但以理顯現，是在先前所見的異象之後。","notes":[]},{"n":2,"t":"我在異象中觀看，見自己在以攔省書珊的城堡中；我在異象中又見自己在烏萊河邊。","notes":[]},{"n":3,"t":"我舉目觀看，看哪，有一隻公綿羊站在河邊，牠有兩隻角，這兩角都高，一角高過另一角，後長出來的比較高。","notes":[]},{"n":4,"t":"我見那公綿羊向西、向北、向南牴撞，沒有任何獸在牠面前站立得住，沒有能逃脫牠手的；牠任意而行，自高自大。","notes":[]},{"n":5,"t":"我正思想的時候，看哪，有一隻公山羊從西而來，遍行全地，腳不著地。這山羊兩眼當中有一隻顯眼的角。","notes":[]},{"n":6,"t":"牠往我先前所見、站在河邊、有雙角的公綿羊那裏，以猛烈的怒氣向牠直闖。","notes":[]},{"n":7,"t":"我見公山羊靠近公綿羊，向牠發怒，攻擊牠，折斷牠的兩角。公綿羊在公山羊面前站立不住；牠把公綿羊撞倒在地，用腳踐踏，沒有能救公綿羊脫離牠手的。","notes":[]},{"n":8,"t":"這公山羊長得極其高大，正強壯的時候，那大角折斷了，從角的下面向天的四方長出四隻顯眼的角來。","notes":["「方」：原文是「風」。"]},{"n":9,"t":"從四角中的一角又長出另一隻小角，向南、向東、向佳美之地，日漸壯大。","notes":[]},{"n":10,"t":"牠漸壯大，高及諸天萬象，把一些天象和星辰摔落在地，用腳踐踏。","notes":[]},{"n":11,"t":"牠自高自大，自以為高及萬象之君，牠除掉經常獻給君的祭，毀壞君的聖所。","notes":["「牠自高自大」：原文另譯「牠被高舉」。"]},{"n":12,"t":"因罪過的緣故，有軍隊和經常獻的祭交給牠。牠把真理拋在地上，任意而行，無往不利。","notes":["「牠把真理...任意而行」：有古卷是「真理被拋在地上，牠任意而行」。"]},{"n":13,"t":"我聽見有一位聖者說話，又有一位聖者向那說話的聖者說：「這經常獻的祭、帶來荒涼的罪過、聖所與軍隊被踐踏的異象，要持續到幾時呢？」","notes":[]},{"n":14,"t":"他對我說：「要到二千三百日，聖所就必潔淨。」","notes":["「我」：七十士譯本和其他古譯本是「他」。","「潔淨」或譯「重行奉獻禮」。"]},{"n":15,"t":"我－但以理見了這異象，想要明白其中的意思。看哪，有一位形狀像人的站在我面前。","notes":[],"heads":["天使加百列解釋異象"]},{"n":16,"t":"我聽見烏萊河中有人聲呼叫說：「加百列啊，要使這人明白這異象。」","notes":[]},{"n":17,"t":"他就來到我所站的地方。他一來，我就驚慌，臉伏於地。他對我說：「人子啊，你要明白，因為這是關乎末後時期的異象。」","notes":[]},{"n":18,"t":"他對我說話的時候，我在沉睡，臉伏於地。他就摸我，扶我站起來。","notes":[]},{"n":19,"t":"他說：「看哪，我要指示你惱怒結束的時候必成的事，因為這是關乎末後指定的時期。","notes":[]},{"n":20,"t":"你所看見那有雙角的公綿羊就是瑪代王和波斯王。","notes":[]},{"n":21,"t":"那公山羊就是希臘王；兩眼當中的大角就是第一個王。","notes":["「希臘」：原文是「雅完」；本卷書下同。"]},{"n":22,"t":"至於角折斷了，又從角的下面長出四隻角，意思就是有四個國要從這國興起，只是權勢都不及它。","notes":[]},{"n":23,"t":"這四國末期，惡貫滿盈的時候，必有一王興起，面貌兇惡，詭計多端。","notes":[]},{"n":24,"t":"他的權柄極大，卻不是因自己的能力；他要施行驚人的毀滅，無往不利，任意而行，又要毀滅強有力的人和眾聖民。","notes":[]},{"n":25,"t":"他用權術使手中的詭計成功；他的心自高自大，趁人無備的時候毀滅多人。他又起來攻擊萬君之君，至終卻非因人的手而遭毀滅。","notes":[]},{"n":26,"t":"所說二千三百日的異象是真的，但你要將這異象封住，因為它關乎未來許多的日子。」","notes":["「二千三百日」：參8．14；原文是「晚上和早上」，指的是晚祭和早祭。"]},{"n":27,"t":"於是我－但以理昏倒，病了數日，然後起來辦理王的事務。我因這異象驚駭不已，但還是不能了解。","notes":[]}]},"9":{"heading":"但以理為同胞禱告","verses":[{"n":1,"t":"瑪代族亞哈隨魯的兒子大流士被立為王，統治迦勒底國元年，","notes":[]},{"n":2,"t":"就是他在位第一年，我－但以理從書上得知，耶和華的話臨到耶利米先知，論耶路撒冷荒涼期滿的年數為七十年。","notes":[]},{"n":3,"t":"我面向主神，禁食，披麻蒙灰，懇切禱告祈求。","notes":[]},{"n":4,"t":"我向耶和華－我的神祈禱、認罪，說：「主啊，你是大而可畏的神，向愛主、守主誡命的人守約施慈愛。","notes":[]},{"n":5,"t":"我們犯罪作惡，行惡叛逆，偏離你的誡命典章，","notes":[]},{"n":6,"t":"沒有聽從你僕人眾先知奉你的名向我們君王、官長、祖先和這地所有百姓所說的話。","notes":[]},{"n":7,"t":"主啊，你是公義的，但我們猶大人和耶路撒冷的居民，並你所趕到各國的以色列眾人，不論遠近，因為背叛了你，臉上蒙羞，正如今日一樣。","notes":[]},{"n":8,"t":"耶和華啊，我們和我們的君王、官長、祖先因得罪了你，臉上就都蒙羞。","notes":[]},{"n":9,"t":"主－我們的神是憐憫饒恕人的，我們卻違背了他，","notes":[]},{"n":10,"t":"沒有聽從耶和華－我們神的話，沒有遵行他藉僕人眾先知向我們頒佈的律法。","notes":[]},{"n":11,"t":"以色列眾人都犯了你的律法，偏離、不聽從你的話；因此，你僕人摩西律法上所寫的詛咒和誓言傾倒在我們身上，因我們得罪了神。","notes":[]},{"n":12,"t":"神使大災禍臨到我們，實現了警戒我們和審判我們官長的話；原來耶路撒冷所遭遇的災禍是普天之下未曾有過的。","notes":[]},{"n":13,"t":"這一切災禍臨到我們，是照摩西律法上所寫的，我們卻沒有求耶和華－我們神的恩惠，使我們回轉離開罪孽，明白你的真理。","notes":[]},{"n":14,"t":"所以耶和華特意使這災禍臨到我們，耶和華－我們的神在他所行的事上都是公義的；我們並沒有聽從他的話。","notes":[]},{"n":15,"t":"主－我們的神啊，你曾用大能的手領你的子民出埃及地，使自己得了名聲，正如今日一樣，現在，我們犯了罪，作了惡。","notes":[]},{"n":16,"t":"主啊，求你按你豐盛的公義，使你的怒氣和憤怒轉離你的城耶路撒冷，就是你的聖山。因我們的罪惡和我們祖先的罪孽，耶路撒冷和你的子民被四圍的人羞辱。","notes":[]},{"n":17,"t":"我們的神啊，現在求你垂聽你僕人的祈禱懇求，為你自己的緣故使你的臉向荒涼的聖所發光。","notes":[]},{"n":18,"t":"我的神啊，求你側耳而聽，睜眼而看，眷顧我們那荒涼之地和稱為你名下的城。我們在你面前懇求，不是因自己的義，而是因你豐富的憐憫。","notes":[]},{"n":19,"t":"主啊，求你垂聽！主啊，求你赦免！主啊，求你側耳，求你實行！為你自己的緣故不要遲延。我的神啊，因這城和這民都是稱為你名下的。」","notes":[]},{"n":20,"t":"我正說話、禱告，承認我的罪和我百姓以色列的罪，為我神的聖山，在耶和華－我的神面前懇求；","notes":[],"heads":["加百列解釋預言"]},{"n":21,"t":"我正在禱告中說話，先前在異象中所見的那位加百列，約在獻晚祭的時候迅速飛到我這裏來。","notes":[]},{"n":22,"t":"他指教我說：「但以理啊，現在我來要使你有智慧，有聰明。","notes":["「他指教我說」：七十士譯本和其他古譯本是「他來對我說」。"]},{"n":23,"t":"你剛開始懇求的時候，就有命令發出。現在我來告訴你，因你是蒙愛的；所以你要思想這事，明白這異象。","notes":[]},{"n":24,"t":"「為你百姓和你聖城，已經定了七十個七，要止住罪過，除淨罪惡，贖盡罪孽，引進永恆的公義，封住異象和預言，並膏至聖所。","notes":["「至聖所」或譯「至聖者」。"]},{"n":25,"t":"你當知道，當明白，從發出命令恢復並重建耶路撒冷，直到受膏的君出現，必有七個七和六十二個七。耶路撒冷城連街帶濠都必在艱難中恢復並重建。","notes":[]},{"n":26,"t":"過了六十二個七，那受膏者被剪除，一無所有；必有一王的百姓來毀滅這城和聖所，它的結局必如洪水沖沒。必有戰爭，一直到末了，荒涼的事已經定了。","notes":["「那受膏者」或譯「有受膏者」。","「它的結局」或譯「他的結局」。"]},{"n":27,"t":"在一七之期，他必與許多人堅立盟約；一七之半，他必使獻祭與供獻止息。那施行毀滅的可憎之物必立在聖殿裏，直到所定的結局傾倒在那行毀滅者的身上。」","notes":["「聖殿裏」是根據七十士譯本；原文是「翅膀上」。"]}]},"10":{"heading":"底格里斯河邊的異象","verses":[{"n":1,"t":"波斯王居魯士第三年，有話指示那稱為伯提沙撒的但以理。這話是確實的，指著大戰爭；但以理明白這話，明白這異象。","notes":[]},{"n":2,"t":"那時，我－但以理悲傷了三個七日；","notes":[]},{"n":3,"t":"美味我沒有吃，酒和肉沒有入我的口，也沒有用油抹我的身，直到滿了三個七日。","notes":[]},{"n":4,"t":"正月二十四日，我在大河，就是底格里斯河邊，","notes":[]},{"n":5,"t":"舉目觀看，看哪，有一人身穿細麻衣，腰束烏法的純金腰帶。","notes":[]},{"n":6,"t":"他的身體如水蒼玉，面貌如閃電，眼目如火把，手臂和腳如明亮的銅，說話的聲音像眾人的聲音。","notes":[]},{"n":7,"t":"我－但以理一人看見這異象，跟我一起的人沒有看見，卻有極大的戰兢落在他們身上，他們就逃跑躲避，","notes":[]},{"n":8,"t":"只剩下我一人。我看見這大異象就渾身無力，面容變色，毫無氣力。","notes":[]},{"n":9,"t":"我聽見他說話的聲音；一聽見他說話的聲音，我就沉睡，臉伏於地。","notes":[]},{"n":10,"t":"看哪，有一隻手摸我，使我膝蓋和手掌戰抖。","notes":[]},{"n":11,"t":"他對我說：「蒙愛的但以理啊，要思想我對你所說的話，只管站起來，因為我現在奉差遣來到你這裏。」他對我說這話，我就戰戰兢兢地站起來。","notes":[]},{"n":12,"t":"他說：「但以理啊，不要懼怕！因為自從第一日你立志要明白，又在你神面前刻苦自己，你的話已蒙應允；我就是因你的話而來。","notes":[]},{"n":13,"t":"但波斯國的領袖攔阻了我二十一天。看哪，天使長中的一位米迦勒來幫助我，因為我被留在波斯諸王那裏。","notes":["「天使長」：原文是「領袖之首」。"]},{"n":14,"t":"現在我來，要使你明白你百姓日後必遭遇的事，因為這異象關乎未來的日子。」","notes":[]},{"n":15,"t":"他向我這樣說，我就臉面朝地，啞口無聲。","notes":[]},{"n":16,"t":"看哪，有一位形狀像人的，摸我的嘴唇，我就開口說話，向那站在我面前的說：「我主啊，因這異象使我感到劇痛，毫無氣力。","notes":[]},{"n":17,"t":"我主的僕人怎能跟我主說話呢？我現在渾身無力，毫無氣息。」","notes":[]},{"n":18,"t":"有一位形狀像人的再一次摸我，使我有力量。","notes":[]},{"n":19,"t":"他說：「蒙愛的人哪，不要懼怕，願你平安！你要剛強！要剛強！」他一對我說話，我就覺得有力量，說：「我主請說，因你使我有力量。」","notes":["「你要剛強！要剛強！」：有古卷是「你要剛強壯膽！」"]},{"n":20,"t":"他說：「你知道我為甚麼到你這裏來嗎？現在我要回去與波斯的領袖爭戰，我去了之後，看哪，希臘的領袖必來。","notes":[]},{"n":21,"t":"但我要將那記錄在真理之書上的話告訴你。除了你們的天使米迦勒之外，沒有人幫助我抵擋他們。」","notes":[]}]},"11":{"heading":"南方王和北方王","verses":[{"n":1,"t":"「至於我，當瑪代的大流士元年，我曾起來扶助米迦勒，使他堅強。","notes":[]},{"n":2,"t":"現在我要指示你確實的事。」「看哪，波斯還有三個王要興起，第四王必富足遠勝諸王。他因富足成為強盛，就必煽動各國攻擊希臘國。","notes":[]},{"n":3,"t":"必有一個勇敢的王興起，執掌大權，隨意而行。","notes":[]},{"n":4,"t":"他正興起的時候，他的國必瓦解，向天的四方裂開，卻不歸他的後裔，也不如他當年統治的權威；他的國必被拔出，歸給他後裔之外的人。","notes":["「方」：原文是「風」。"]},{"n":5,"t":"「南方的王必強盛，他的將帥中必有一個比他更強，執掌權柄，權柄甚大。","notes":[]},{"n":6,"t":"過了幾年，他們必結盟，南方王的女兒必來到北方王那裏，使約生效；但這女子不能保留實力，王的力量也未能存留。這女子、帶她來的、生她的和當時扶助她的必被殺害。","notes":["「力量」：七十士譯本和其他古譯本是「後裔」。","「生她的」：有古譯本是「她的孩子」。","「被殺害」：原文是「被交出來」。"]},{"n":7,"t":"但從這女子的本家必另有一子接續王位，他要率領軍隊進入北方王的堡壘，攻擊他們，而且得勝，","notes":["「本家必另有一子」：原文是「根必另生一枝」。"]},{"n":8,"t":"把他們的神像和鑄成的偶像，與金銀寶器都擄掠到埃及去。數年之內，他不去攻擊北方的王。","notes":[]},{"n":9,"t":"北方的王必侵入南方王的國土，但卻要撤回本地。","notes":[]},{"n":10,"t":"「北方王的兒子們必動干戈，招聚許多軍兵。他要前進，如洪水氾濫；要再度爭戰，直搗南方王的堡壘。","notes":[]},{"n":11,"t":"南方王必發烈怒，出來與北方王爭戰，擺列大軍；北方王的軍兵必敗在南方王的手下。","notes":[]},{"n":12,"t":"這大軍既被掃蕩，南方王的心就自高；他雖使萬人仆倒，卻不能保持勝利。","notes":[]},{"n":13,"t":"「北方王要再度擺列大軍，比先前更多。過了幾年，他必率領大軍，帶極多的裝備而來。","notes":[]},{"n":14,"t":"那時，必有許多人起來攻擊南方王，並且你百姓中的殘暴人要興起，應驗異象，他們卻要敗亡。","notes":[]},{"n":15,"t":"北方王必來建土堆攻取堅固城，南方的軍兵抵擋不住，就是精選的部隊也無力抵擋；","notes":[]},{"n":16,"t":"前來攻擊南方王的必任意而行，無人在北方王面前站立得住。他要站在那佳美之地，用手施行毀滅。","notes":[]},{"n":17,"t":"「他必定意傾全國之力而來，與南方王訂約，把自己的女兒給南方王為妻，企圖敗壞他的國度。這計謀卻未得逞，自己也得不到好處。","notes":["「自己的女兒」：原文是「婦人的女兒 」。"]},{"n":18,"t":"其後北方王必轉頭，奪取許多海島。但有一將帥除掉北方王對人的羞辱，並且使羞辱歸到他自己身上。","notes":[]},{"n":19,"t":"他必轉頭回到本地的堡壘，卻要絆跌仆倒，歸於無有。","notes":[]},{"n":20,"t":"「那時，有一人興起接續他的王位，他為了王國的榮華，差官員橫征暴斂。這王過不多時就死了，不是因怒氣，也不是因戰役。」","notes":["「怒氣」或譯「面對面的搏鬥」。"]},{"n":21,"t":"「後來，有一個卑鄙的人興起接續他的王位，人未曾將國的尊榮給他，他卻趁人無備的時候前來，用詭詐奪取政權。","notes":[],"heads":["北方的惡王"]},{"n":22,"t":"勢如洪水般的軍兵在他面前被沖沒，遭擊潰；立約的領袖也是如此。","notes":[]},{"n":23,"t":"他與人結盟之後，卻行詭詐。跟隨他的人雖不多，他卻日漸強盛。","notes":[]},{"n":24,"t":"他趁人無備的時候，來到國中極肥沃之地，做他祖宗和祖宗的祖宗未曾做過的事，瓜分擄物、掠物和財寶，又策劃進攻堡壘；然而這都是暫時的。","notes":[]},{"n":25,"t":"「他必奮勇向前，率領大軍攻擊南方王；南方王以極強的大軍迎戰，卻抵擋不住，因為有人設計謀害南方王。","notes":[]},{"n":26,"t":"吃王餉的使王敗壞，王的軍隊必被沖沒，仆倒被殺的甚多。","notes":[]},{"n":27,"t":"至於這二王，他們心懷惡計，同席吃飯卻彼此說謊，但計謀不成，因為結局要在指定的時期來到。","notes":[]},{"n":28,"t":"北方王必帶許多財寶回本地，但他的心反對聖約；他恣意橫行，回到本地。","notes":[]},{"n":29,"t":"「到了指定的時期，他必返回，侵入南方。這一次卻不像前一次，","notes":[]},{"n":30,"t":"因為基提的戰船要來攻擊他，他就喪膽而退。他惱恨聖約，恣意橫行，要回來善待那些背棄聖約的人。","notes":[]},{"n":31,"t":"他要興兵，這兵必褻瀆聖所，就是堡壘，除掉經常獻的祭，設立那施行毀滅的可憎之物。","notes":[]},{"n":32,"t":"他必用巧言奉承違背聖約的惡人；惟獨認識神的子民必剛強行事。","notes":[]},{"n":33,"t":"民間的智慧人必訓誨許多人，然而在一段日子裏，他們必因刀劍、火燒、擄掠、搶奪而仆倒。","notes":[]},{"n":34,"t":"他們仆倒的時候，會得到少許援助，卻有許多人用詭詐加入他們。","notes":[]},{"n":35,"t":"智慧人中有些人仆倒，為要使他們受熬煉，成為潔淨、潔白，直到末了；因為還有一段日子才到所定的時期。","notes":[]},{"n":36,"t":"「王必任意而行，自高自大，超過所有的神明，又用荒謬的話攻擊萬神之神。他必行事亨通，直到主的憤怒結束，因為所定的事必然實現。","notes":[]},{"n":37,"t":"他不顧他祖宗的神明，也不顧婦女所仰慕的神明，任何神明他都不顧；因為他自大，高過一切，","notes":[]},{"n":38,"t":"以敬奉堡壘的神明取而代之，用金、銀、寶石和珍寶敬奉他祖宗所不認識的神明。","notes":[]},{"n":39,"t":"他靠外邦神明的幫助，攻破最堅固的堡壘。凡承認他的，他要給他們許多尊榮，使他們管轄許多人，又分封土地作為報償。","notes":[]},{"n":40,"t":"「到末了，南方王要與北方王交戰。北方王要用戰車、騎兵和許多戰船，勢如暴風來攻擊他，又要侵入列國，如洪水氾濫。","notes":[]},{"n":41,"t":"他要侵入那佳美之地，許多國就被傾覆，但以東人、摩押人和大半的亞捫人必逃離他的手。","notes":["「許多國就被傾覆」：原文另譯「千萬人要傷亡」。","「大半的」：有古譯本是「殘餘的」。"]},{"n":42,"t":"他要伸手攻擊列國，連埃及地也不得逃脫。","notes":[]},{"n":43,"t":"他要掌管埃及的金銀財寶和各樣珍寶，路比人和古實人都跟從他的腳步。","notes":["「路比」就是利比亞。","「古實」包括蘇丹的大部分和埃塞俄比亞的一部分。"]},{"n":44,"t":"但從東方和北方必有消息傳來擾亂他，他就大發烈怒出去，要將許多人殺滅淨盡。","notes":[]},{"n":45,"t":"他要在海和榮美的聖山之間搭起王宮的帳幕；然而他的結局到了，無人能幫助他。」","notes":[]}]},"12":{"heading":"末日","verses":[{"n":1,"t":"「那時，保佑你百姓的天使長米迦勒必站起來，並且有大艱難，自從有國以來直到此時，未曾有過這樣的事。那時，你的百姓凡記錄在冊上的，必得拯救。","notes":["「天使長」：原文是「大領袖」。"]},{"n":2,"t":"睡在地裏塵埃中的必有多人醒過來；其中有得永生的，有受羞辱永遠被憎惡的。","notes":[]},{"n":3,"t":"智慧人要發光，如同天上的光；那領許多人歸於義的必發光如星，直到永永遠遠。","notes":[]},{"n":4,"t":"但以理啊，你要隱藏這話，封閉這書，直到末時。必有許多人往來奔跑，知識就必增長。」","notes":["「往來奔跑」或譯「悉心研究」。","「知識」：原文另譯「邪惡」；七十士譯本是「不義」。"]},{"n":5,"t":"我－但以理觀看，看哪，另有兩個人站立：一個在河這邊，一個在河那邊。","notes":[]},{"n":6,"t":"其中一個對那在河水之上、穿細麻衣的說：「這奇異的事要到幾時才應驗呢？」","notes":[]},{"n":7,"t":"我聽見那在河水之上、穿細麻衣的，向天舉起左右手，指著那活到永遠的起誓說：「要到一年、兩年，又半年，粉碎聖民力量結束的時候，這一切的事就要應驗。」","notes":["「年」或譯「時期」；下同。"]},{"n":8,"t":"我聽了卻不明白，就說：「我主啊，這些事的結局是怎樣呢？」","notes":[]},{"n":9,"t":"他說：「但以理，去吧！因為這話已經隱藏封閉，直到末時。","notes":[]},{"n":10,"t":"必有許多人使自己潔淨、潔白，且受熬煉；但惡人仍必行惡，沒有一個惡人明白，惟獨智慧人能明白。","notes":[]},{"n":11,"t":"從除掉經常獻的祭，設立那施行毀滅的可憎之物的時候起，必有一千二百九十日。","notes":[]},{"n":12,"t":"那等候，直到一千三百三十五日的有福了。","notes":[]},{"n":13,"t":"「至於你，你要去等候結局。你必安息，到了末期，你必起來，享受你的福分。」","notes":[]}]}},"HOS":{"1":{"heading":"何西阿的妻子和兒女","verses":[{"n":1,"t":"當烏西雅、約坦、亞哈斯、希西家作猶大王，約阿施的兒子耶羅波安作以色列王的時候，耶和華的話臨到備利的兒子何西阿。","notes":[]},{"n":2,"t":"耶和華初次向何西阿說話。耶和華對他說：「你去娶一個淫蕩的女子為妻，收那從淫亂所生的兒女；因為這地行大淫亂，離棄耶和華。」","notes":[]},{"n":3,"t":"於是，何西阿去娶了滴拉音的女兒歌篾。她就懷孕，為何西阿生了一個兒子。","notes":[]},{"n":4,"t":"耶和華對何西阿說：「給他起名叫耶斯列；因為再過片時，我要懲罰耶戶家在耶斯列流人血的罪，也必終結以色列家的王朝。","notes":["「耶斯列」意思是「神栽種」；2．22同。"]},{"n":5,"t":"到那日，我必在耶斯列平原折斷以色列的弓。」","notes":[]},{"n":6,"t":"歌篾又懷孕，生了一個女兒，耶和華對何西阿說：「給她起名叫羅‧路哈瑪；因為我必不再憐憫以色列家，絕不赦免他們。","notes":["「羅‧路哈瑪」意思是「不蒙憐憫」；2．23同。"]},{"n":7,"t":"我卻要憐憫猶大家，使他們靠耶和華－他們的神得救；我必不讓他們靠弓、刀、戰爭、馬匹與騎兵得救。」","notes":[]},{"n":8,"t":"歌篾在羅‧路哈瑪斷奶以後，又懷孕生了一個兒子。","notes":[]},{"n":9,"t":"耶和華說：「給他起名叫羅‧阿米；因為你們不是我的子民，我也不是你們的神。」","notes":["「羅‧阿米」意思是「非我民」；2．23同。","原文沒有「神」。"]},{"n":10,"t":"然而，以色列的人數必多如海沙，不可量，不可數。從前在甚麼地方對他們說「你們不是我的子民」，將來就在那裏稱他們為「永生神的兒子」。","notes":[],"heads":["以色列將要復興"]},{"n":11,"t":"猶大人和以色列人要一同聚集，為自己設立一個「頭」，從這地上來，因為耶斯列的日子必為大日。","notes":[]}]},"2":{"heading":"不貞的歌篾－不忠的以色列","verses":[{"n":1,"t":"你們要稱你們的眾弟兄為阿米，稱你們的眾姊妹為路哈瑪。","notes":["「眾弟兄」：七十士譯本是「弟兄」。","「阿米」意思是「我民」。","「眾姊妹」：七十士譯本和其他古譯本是「姊妹」。","「路哈瑪」意思是「蒙憐憫」。"]},{"n":2,"t":"要跟你們的母親理論，理論，─因為她不是我的妻子，我也不是她的丈夫─叫她除掉臉上的淫相和胸間的淫態，","notes":[]},{"n":3,"t":"免得我剝光她，使她赤身，如剛出生的時候一樣，使她如曠野，如乾旱之地，乾渴而死。","notes":[]},{"n":4,"t":"我必不憐憫她的兒女，因為他們是從淫亂生的兒女。","notes":[]},{"n":5,"t":"他們的母親行了淫亂，懷他們的做了可羞恥的事；因為她說：「我要跟隨我所愛的，我的餅、水、羊毛、麻、油、酒，都是他們給的。」","notes":[]},{"n":6,"t":"因此，看哪，我要用荊棘堵塞她的道，築牆擋住她，使她找不著路；","notes":["「她」是根據七十士譯本和其他古譯本；原文是「你」。"]},{"n":7,"t":"以致她追隨所愛的人，卻追不上，尋找他們，卻尋不著，就說：「我要回到前夫那裏去，因我那時比現在還好。」","notes":[]},{"n":8,"t":"她不知道是我給她五穀、新酒和新的油，又加添她的金銀；他們卻用來供奉巴力。","notes":[]},{"n":9,"t":"因此，我要在收割的日子收回我的五穀，在當令的季節收回我的新酒，我要奪回她用以遮體的羊毛和麻。","notes":[]},{"n":10,"t":"如今我必在她所愛的人眼前顯露她的羞恥，無人能救她脫離我的手。","notes":["「顯露她的羞恥」或譯「暴露她的下體」。"]},{"n":11,"t":"我必使她的宴樂、節期、初一、安息日，她一切的盛會都止息。","notes":[]},{"n":12,"t":"我要毀壞她的葡萄樹和無花果樹，就是她所說「我所愛的給我為賞賜」的；我要使它們變為荒林，為野地的走獸所吞吃。","notes":[]},{"n":13,"t":"我要懲罰她素日給諸巴力燒香的罪；那時她佩戴耳環和珠寶，跟隨她所愛的，卻忘記我。這是耶和華說的。","notes":[]},{"n":14,"t":"因此，看哪，我要誘導她，領她到曠野，我要說動她的心。","notes":[],"heads":["神對他子民的愛"]},{"n":15,"t":"在那裏，我必賜她葡萄園，又賜她亞割谷作為指望的門。她必在那裏回應，像在年輕時從埃及地上來的時候一樣。","notes":[]},{"n":16,"t":"那日你必稱呼我伊施，不再稱呼我巴力。這是耶和華說的。","notes":["「伊施」意思是「我的丈夫」。","「巴力」意思是「我的主」。"]},{"n":17,"t":"因為我必從她口中除掉諸巴力的名號，不再有人提這名號。","notes":[]},{"n":18,"t":"當那日，我必為我的百姓，與野地的走獸、天空的飛鳥和地上爬行的動物立約；又要在國中折斷弓和刀，止息戰爭，使他們安然躺臥。","notes":[]},{"n":19,"t":"我必聘你永遠歸我為妻，以公義、公平、慈愛、憐憫聘你歸我；","notes":[]},{"n":20,"t":"也以信實聘你歸我，你就必認識耶和華。","notes":[]},{"n":21,"t":"耶和華說：那日我必應允，我必應允天，天必應允地，","notes":[]},{"n":22,"t":"地必應允五穀、新酒和新的油；這些都必應允在耶斯列身上。","notes":[]},{"n":23,"t":"我為自己必將她種在這地。我必憐憫羅‧路哈瑪；對羅‧阿米說：「你是我的子民」；他必說：「我的神。」","notes":[]}]},"3":{"heading":"何西阿和不貞的婦人","verses":[{"n":1,"t":"耶和華又對我說：「你去愛那情人所愛卻犯姦淫的婦人，正如耶和華愛那偏向別神、喜愛葡萄餅的以色列人。」","notes":["「葡萄餅」是祭祀神明用的。"]},{"n":2,"t":"於是我用十五舍客勒銀子和一賀梅珥半大麥買她歸我。","notes":[]},{"n":3,"t":"我對她說：「你當多日與我同住，不可行淫，不可歸與別人，我對你也一樣。」","notes":[]},{"n":4,"t":"因為以色列人必多日過著無君王，無領袖，無祭祀，無柱像，無以弗得，無家中神像的生活。","notes":[]},{"n":5,"t":"後來以色列人必歸回，尋求耶和華─他們的神和他們的王大衛。在末後的日子，他們必敬畏耶和華，領受他的恩惠。","notes":["「歸回」或譯「回轉」。"]}]},"4":{"heading":"耶和華譴責以色列","verses":[{"n":1,"t":"以色列人哪，當聽耶和華的話。耶和華指控這地的居民，因為在這地上無誠信，無慈愛，無人認識神；","notes":[]},{"n":2,"t":"惟起誓、欺騙、殺害、偷盜、姦淫、殘暴、流血又流血。","notes":[]},{"n":3,"t":"因此，這地悲哀，其上的居民、野地的走獸、天空的飛鳥都日趨衰微，海中的魚也必消滅。","notes":[]},{"n":4,"t":"然而，人都不必爭辯，也不必指責。你的百姓與抗拒祭司的人一樣。","notes":[],"heads":["譴責祭司"]},{"n":5,"t":"日間你必跌倒，夜間先知也要與你一同跌倒；我要滅絕你的母親。","notes":[]},{"n":6,"t":"我的百姓因無知識而滅亡。你拋棄知識，我也必拋棄你，使你不再作我的祭司。你既忘了你神的律法，我也必忘記你的兒女。","notes":[]},{"n":7,"t":"祭司越發增多，就越發得罪我；我必使他們的榮耀變為羞辱。","notes":[]},{"n":8,"t":"他們吞吃我百姓的贖罪祭，滿心願意我的子民犯罪。","notes":["「贖罪祭」或譯「罪」。"]},{"n":9,"t":"將來百姓所受的，祭司也必承受；我必因他們所行的懲罰他們，照他們所做的報應他們。","notes":[]},{"n":10,"t":"他們吃，卻不得飽足；行淫，卻不繁衍；因為他們離棄耶和華，常行","notes":[]},{"n":11,"t":"淫亂。酒和新酒奪去人的心。","notes":[]},{"n":12,"t":"我的百姓求問木偶，以為木杖能指示他們；淫亂的心使他們失迷，以致行淫離棄他們的神，","notes":[],"heads":["譴責拜偶像的罪"]},{"n":13,"t":"在各山頂獻祭，在各高岡上燒香，在橡樹、楊樹、大樹之下，因為那裏樹影美好。所以，你們的女兒行淫，你們的媳婦犯姦淫。","notes":["「媳婦」或譯「新娘」；下同。"]},{"n":14,"t":"我不因你們的女兒行淫或你們的媳婦犯姦淫懲罰她們；因為人自己轉去與娼妓同居，與神廟娼妓一同獻祭。這無知的百姓必致傾倒。","notes":[]},{"n":15,"t":"以色列啊，你雖然行淫，猶大卻不可犯罪；不要往吉甲去，不要上到伯‧亞文，也不要指著永生的耶和華起誓。","notes":[]},{"n":16,"t":"以色列倔強，猶如倔強的母牛；現在耶和華能牧放他們，如在寬闊之地牧放羔羊嗎？","notes":[]},{"n":17,"t":"以法蓮親近偶像，任憑他吧！","notes":[]},{"n":18,"t":"他們喝完了酒，荒淫無度，他們的官長甚愛羞恥的事。","notes":[]},{"n":19,"t":"風把他們捲在翅膀裏，他們必因所獻的祭蒙羞。","notes":["「所獻的祭」：七十士譯本是「祭壇」。"]}]},"5":{"heading":"何西阿警告拜偶像的人","verses":[{"n":1,"t":"眾祭司啊，要聽這話！以色列家啊，要留心聽！王室啊，要側耳而聽！審判將臨到你們，因你們在米斯巴如羅網，在他泊山如張開的網。","notes":[]},{"n":2,"t":"這些悖逆的人大行殺戮，我要斥責他們眾人。","notes":[]},{"n":3,"t":"至於我，我認識以法蓮，以色列不能向我隱藏。以法蓮哪，現在你竟然行淫，以色列竟然被污辱。","notes":["「以法蓮哪...行淫」：七十士譯本是「現在以法蓮竟然行淫」。"]},{"n":4,"t":"他們所做的使他們不能歸向神，因有淫亂的心在他們裏面；他們不認識耶和華。","notes":[]},{"n":5,"t":"以色列的驕傲使自己臉面無光；以色列和以法蓮必因自己的罪孽跌倒，猶大也必與他們一同跌倒。","notes":["「使自己臉面無光」或譯「當面見證自己的不是」或「使自己卑微」；7．10同。"]},{"n":6,"t":"他們牽著牛羊去尋求耶和華，卻尋不著；因他已轉去離開他們。","notes":[]},{"n":7,"t":"他們不忠於耶和華，生了私生子。現在新月必吞滅他們和他們的地業。","notes":[]},{"n":8,"t":"你們當在基比亞吹角，在拉瑪吹號，在伯‧亞文發出警報；便雅憫哪，留意你的背後！","notes":[],"heads":["猶大和以色列的戰爭"]},{"n":9,"t":"到了懲罰的日子，以法蓮必變為廢墟；我在以色列眾支派中，已指示將來必成的事。","notes":[]},{"n":10,"t":"猶大的領袖如同挪移地界的人，我必把我的憤怒如水傾倒在他們身上。","notes":[]},{"n":11,"t":"以法蓮因喜愛遵從荒謬的命令，就受欺壓，在審判中被壓碎。","notes":["「遵從荒謬的命令」：原文另譯「追求糞土」；七十士譯本和其他古譯本是「追求虛無」。"]},{"n":12,"t":"我對以法蓮竟如蛀蟲，向猶大家竟如朽爛。","notes":[]},{"n":13,"t":"以法蓮見自己有病，猶大見自己有傷，以法蓮就前往亞述，差遣人去見大王；他卻不能醫治你們，不能治好你們的傷。","notes":["「大王」或譯「耶雷布王」；10．6同。"]},{"n":14,"t":"我必向以法蓮如獅子，向猶大家如少壯獅子。我要撕裂，並且離去，我必奪去，無人搭救。","notes":[]},{"n":15,"t":"我要去，我要回到原處，等他們自覺有罪，尋求我的面；急難時他們必切切尋求我。","notes":[]}]},"6":{"heading":"以色列無悔改誠意","verses":[{"n":1,"t":"來，我們歸向耶和華吧！他撕裂我們，也必醫治；打傷我們，也必包紮。","notes":[]},{"n":2,"t":"過兩天他必使我們甦醒，第三天他必使我們興起，我們就在他面前得以存活。","notes":[]},{"n":3,"t":"我們要認識，要追求認識耶和華。他如黎明必然出現，他必臨到我們像甘霖，像滋潤土地的春雨。","notes":[]},{"n":4,"t":"以法蓮哪，我可以向你怎樣行呢？猶大啊，我可以向你怎樣做呢？因為你們的慈愛如同早晨的雲霧，又如速散的露水。","notes":[]},{"n":5,"t":"因此，我藉先知砍伐他們，以我口中的話殺戮他們；對你的審判如光發出。","notes":["「對你的審判」：七十士譯本和其他古譯本是「我的審判」。"]},{"n":6,"t":"我喜愛慈愛，不喜愛祭物；喜愛人認識神，勝於燔祭。","notes":["「慈愛」：七十士譯本是「憐憫」。"]},{"n":7,"t":"他們卻如亞當背約，在那裏向我行詭詐。","notes":["「如亞當」或譯「如人」。"]},{"n":8,"t":"基列是作惡之人的城，被血沾染。","notes":[]},{"n":9,"t":"成群的祭司如強盜埋伏等候，在示劍的路上殺戮，行了邪惡。","notes":[]},{"n":10,"t":"在以色列家我看見可憎的事，在以法蓮那裏有淫行，以色列被污辱了。","notes":[]},{"n":11,"t":"猶大啊，我使被擄之民歸回的時候，必有為你所預備的豐收。","notes":[]}]},"7":{"heading":"宮廷內亂","verses":[{"n":1,"t":"我正要醫治以色列的時候，以法蓮的罪孽和撒瑪利亞的邪惡就顯露出來。他們行事虛謊，內有賊人入侵，外有群盜劫掠。","notes":[]},{"n":2,"t":"他們以為我不在意他們一切的惡行；現在，他們所做的在我面前纏繞他們。","notes":[]},{"n":3,"t":"他們行惡使君王歡喜，說謊使官長快樂。","notes":[]},{"n":4,"t":"他們全都犯姦淫，如同烤熱的火爐，師傅在揉麵到發麵時暫時停止煽火。","notes":[]},{"n":5,"t":"在我們君王宴樂的日子，官長因酒的烈性而生病，王與褻慢的人握手。","notes":["「因酒...生病」：七十士譯本是「開始因酒而狂熱」。"]},{"n":6,"t":"他們臨近，心裏如火爐一般，他們等待，如烤餅的整夜睡覺，到了早晨如火焰熊熊。","notes":[]},{"n":7,"t":"他們全都熱如火爐，吞滅他們的審判官。他們的君王都仆倒，他們中間無一人求告我。","notes":[]},{"n":8,"t":"以法蓮混居在萬民中，以法蓮是沒有翻過的餅。","notes":["「混居在萬民中」或譯「在萬民中逐漸枯朽」。"],"heads":["以色列和列邦"]},{"n":9,"t":"外邦人消耗他的力量，他卻不知道；頭髮斑白，他也不覺得。","notes":[]},{"n":10,"t":"以色列的驕傲使自己臉面無光。他們雖遭遇這一切，仍不歸向耶和華－他們的神，也不尋求他。","notes":[]},{"n":11,"t":"以法蓮好像鴿子愚蠢無知，他們求告埃及，投奔亞述。","notes":[]},{"n":12,"t":"他們去的時候，我要把我的網撒在他們身上；我要捕獲他們如同空中的鳥。我必按他們會眾所聽到的懲罰他們。","notes":["「他們會眾所聽到的」：原文另譯「他們的邪惡」；七十士譯本是「聽到他們的災難而」。"]},{"n":13,"t":"他們因離棄我，必定有禍；因違背我，必遭毀滅。我雖想要救贖他們，他們卻向我說謊。","notes":[]},{"n":14,"t":"他們在床上呼號，卻不誠心哀求我；他們為求五穀新酒而聚集，卻背叛我。","notes":["「聚集」：有古卷和七十士譯本是「割傷自己」。"]},{"n":15,"t":"我雖管教他們，堅固他們的膀臂，他們卻圖謀邪惡抗拒我。","notes":[]},{"n":16,"t":"他們歸向，但不是歸向至上者；終究必如鬆弛的弓。他們的領袖必因舌頭的狂傲倒在刀下，這在埃及地必成為人的笑柄。","notes":["「他們...至上者」：原文另譯「他們歸向巴力」；七十士譯本是「他們歸向那不存在的」。"]}]},"8":{"heading":"以色列人因拜偶像被定罪","verses":[{"n":1,"t":"你用口吹角吧！敵人如鷹攻打耶和華的家；因為他們違背了我的約，干犯了我的律法。","notes":[]},{"n":2,"t":"他們必呼求我：「我的神啊，我們以色列認識你了。」","notes":["「我的神啊...認識你了」：原文另譯「以色列的神啊，我們認識你了」。"]},{"n":3,"t":"以色列丟棄良善；仇敵必追逼他。","notes":["「良善」或譯「福分」。"]},{"n":4,"t":"他們立君王，並非出於我；立官長，我卻不知道。他們用金銀為自己製造偶像，以致被剪除。","notes":[]},{"n":5,"t":"撒瑪利亞啊，耶和華已拋棄你的牛犢；我的怒氣向拜牛犢的人發作。他們要到幾時方能無罪呢？","notes":[]},{"n":6,"t":"因這牛犢是出於以色列，是匠人所造的，並不是神。撒瑪利亞的牛犢必被打碎。","notes":[]},{"n":7,"t":"他們所栽種的是風，所收割的是暴風；禾稼不長穗，無以製成麵粉；即便製成，外邦人也必吞吃它。","notes":[]},{"n":8,"t":"以色列被吞吃，如今在列國中像人所不喜愛的器皿。","notes":[]},{"n":9,"t":"他們投奔亞述如獨行的野驢。以法蓮雇用情人，","notes":[]},{"n":10,"t":"他們雇用列國；如今我要聚集他們，他們必因君王和官長所加的重擔開始衰微。","notes":["「他們必因...衰微」：七十士譯本是「他們要停止片時，不再膏君王和官長」。"]},{"n":11,"t":"以法蓮為贖罪增添許多祭壇，這些祭壇卻使他犯罪。","notes":[]},{"n":12,"t":"我為他寫了許多條律法，他卻以為與他毫無關係。","notes":["「許多條」：原文另譯「萬條」。"]},{"n":13,"t":"他們獻祭物作為給我的供物，卻自食其肉，耶和華並不悅納他們。現在他必記起他們的罪孽，懲罰他們的罪惡；他們必返回埃及。","notes":[]},{"n":14,"t":"以色列忘記造他的主，建造宮殿，猶大增添許多堅固的城；我卻要降火在他的城鎮，吞滅其堡壘。","notes":[]}]},"9":{"heading":"宣佈以色列受懲罰","verses":[{"n":1,"t":"以色列啊，不要歡喜，像萬民一樣快樂；因為你行淫離棄你的神，喜愛各禾場上賣淫所得的賞金。","notes":["「像」：七十士譯本是「不要像」。"]},{"n":2,"t":"禾場和壓酒池都不足以餵養他們，它的新酒也必缺乏。","notes":[]},{"n":3,"t":"他們必不得住耶和華的地；以法蓮卻要返回埃及，在亞述吃不潔淨的食物。","notes":[]},{"n":4,"t":"他們必不得向耶和華獻澆酒祭，所獻的祭也不蒙悅納。他們的祭物如居喪者的食物，凡吃的必使自己玷污；因為他們的食物只為自己的口腹，必不得入耶和華的殿。","notes":[]},{"n":5,"t":"到盛會的日子，在耶和華的節期，你們要怎樣行呢？","notes":[]},{"n":6,"t":"看哪，他們要逃避災難；埃及人要收殮他們，摩弗人要埋葬他們。蒺藜盤踞他們貴重的銀器，荊棘必佔據他們的帳棚。","notes":["「摩弗」就是埃及的孟斐斯，也稱「挪弗」。"]},{"n":7,"t":"降罰的日子近了，報應的時候已經來到。以色列必知道，先知愚昧，受靈感動的人狂妄，皆因你多多作惡，大懷怨恨。","notes":[]},{"n":8,"t":"以法蓮替我的神守望；至於先知，他所到之處都有捕鳥人的羅網，在他神的家中也遭人懷恨。","notes":[]},{"n":9,"t":"他們深深敗壞，如在基比亞的日子一樣。耶和華必記起他們的罪孽，懲罰他們的罪惡。","notes":[]},{"n":10,"t":"我發現以色列，如在曠野的葡萄；我看見你們的祖先，如春季無花果樹上初熟的果子。他們卻來到巴力‧毗珥，獻上自己做羞恥的事，成為可憎惡的，與他們所愛的一樣。","notes":[],"heads":["以色列的罪及其後果"]},{"n":11,"t":"以法蓮，他們的榮耀如鳥飛去，必不生產，不懷胎，不成孕；","notes":[]},{"n":12,"t":"他們縱然將兒女養大，我卻要使他們喪子，一個也不留。我離棄他們，他們就有禍了。","notes":[]},{"n":13,"t":"我看以法蓮如推羅栽於美地。以法蓮卻要將自己的兒女帶出來，交給行殺戮的人。","notes":[]},{"n":14,"t":"耶和華啊，求你加給他們，加給他們甚麼呢？要使他們懷孕流產，乳房枯乾。","notes":[]},{"n":15,"t":"因他們在吉甲的一切惡事，我在那裏憎惡他們。因他們所行的惡，我必把他們趕出我的殿，不再愛他們；他們的領袖都是悖逆的。","notes":[],"heads":["耶和華審判以色列"]},{"n":16,"t":"以法蓮受擊打，其根枯乾，不能結果，即或生產，我也要殺他們所生的愛子。","notes":[]},{"n":17,"t":"我的神必棄絕他們，因為他們不聽從他；他們必飄流在列國中。","notes":[],"heads":["先知論以色列"]}]},"10":{"heading":"神審判以色列","verses":[{"n":1,"t":"以色列是茂盛的葡萄樹，結果繁多。果子越多，就越增添祭壇；土地越肥美，就越建造美麗的柱像。","notes":[]},{"n":2,"t":"他們心懷二意，現今要定為有罪。耶和華必拆毀他們的祭壇，粉碎他們的柱像。","notes":[]},{"n":3,"t":"現在他們要說：「我們沒有王；因為我們不敬畏耶和華，王又能為我們做甚麼呢？」","notes":[]},{"n":4,"t":"他們講空話，以假誓立約；因此，懲罰如苦菜滋生在田間的犁溝中。","notes":[]},{"n":5,"t":"撒瑪利亞的居民必因伯‧亞文的牛犢驚恐；它的百姓為它悲哀，它的祭司為它戰兢，因為榮耀已經離開它。","notes":[]},{"n":6,"t":"人必將牛犢帶到亞述，當作禮物獻給大王。以法蓮必蒙羞，以色列必因自己的計謀慚愧。","notes":[]},{"n":7,"t":"撒瑪利亞的王要滅亡，如水面上的泡沫一般。","notes":[]},{"n":8,"t":"亞文的丘壇，以色列犯罪的地方必毀壞，荊棘和蒺藜必長在他們的祭壇上。他們要向大山說：遮蓋我們！向小山說：倒在我們身上！","notes":[]},{"n":9,"t":"以色列啊，你從基比亞的日子以來就時常犯罪，他們仍停留在那裏。攻擊罪孽之輩的戰事豈不會臨到基比亞嗎？","notes":[]},{"n":10,"t":"我必隨己意懲罰他們，他們為雙重的罪所纏；萬民必聚集攻擊他們。","notes":[]},{"n":11,"t":"以法蓮是馴良的母牛犢，喜愛踹穀，我要將軛套在牠肥美的頸項上，我要使以法蓮被套住；猶大必耕田，雅各必耙地。","notes":[]},{"n":12,"t":"你們要為自己栽種公義，收割慈愛。你們要開墾荒地，現今正是尋求耶和華的時候；等他臨到，公義必如雨降給你們。","notes":[]},{"n":13,"t":"你們耕種奸惡，收割罪孽，吃的是謊言的果實。因你倚靠自己的行為，仰賴你眾多的勇士，","notes":[]},{"n":14,"t":"所以在你百姓中必掀起鬧鬨，你一切的堡壘必被拆毀，就如沙勒幔在爭戰的日子拆毀伯‧亞比勒，將城中的母子一同摔碎。","notes":[]},{"n":15,"t":"伯特利啊，因你們的大惡，你們必遭遇如此。黎明來臨，以色列的王必全然滅絕。","notes":["「伯特利」：七十士譯本是「以色列家」。"]}]},"11":{"heading":"憐愛叛民","verses":[{"n":1,"t":"以色列年幼的時候，我愛他，就從埃及召我的兒子出來。","notes":[]},{"n":2,"t":"先知越是呼喚他們，他們越是遠離，向諸巴力獻祭，為雕刻的偶像燒香。","notes":["「先知」：原文是「他們」。","「先知...遠離」：七十士譯本是「我越是呼喚他們，他們越是遠離我」。"]},{"n":3,"t":"我曾教導以法蓮行走，我用膀臂抱起他們，他們卻不知道是我醫治他們。","notes":["「我用膀臂」是根據七十士譯本；原文是「他用他的膀臂」。"]},{"n":4,"t":"我用慈繩愛索牽引他們；我待他們如人鬆開牛兩腮旁邊的軛，彎下身來餵養他們。","notes":[]},{"n":5,"t":"他們不必返回埃及地；然而亞述人要作他們的王，因他們不肯歸向我。","notes":[]},{"n":6,"t":"刀劍必臨到他們的城鎮，毀壞門閂，吞滅眾人，都因他們自己的計謀。","notes":[]},{"n":7,"t":"我的百姓偏要背離我，他們雖向至高者呼求，他卻不抬舉他們。","notes":["「他們雖...不抬舉他們」或譯「雖然人呼召他們歸向至高者，卻無人尊崇他」。"]},{"n":8,"t":"以法蓮哪，我怎能捨棄你？以色列啊，我怎能棄絕你？我怎能使你如押瑪？怎能使你如洗扁？我回心轉意，我的憐憫燃了起來。","notes":[]},{"n":9,"t":"我必不發猛烈的怒氣，也不再毀滅以法蓮。因我是神，並非世人，是你們中間的聖者；我必不在怒中臨到你們。","notes":[]},{"n":10,"t":"耶和華如獅子吼叫，他的兒女必跟隨他。他一吼叫，他們就從西方戰兢而來。","notes":[]},{"n":11,"t":"他們必如雀鳥從埃及戰兢而來，又如鴿子從亞述地來到。我必使他們住自己的房屋；這是耶和華說的。","notes":[]},{"n":12,"t":"以法蓮用謊言圍繞我，以色列家用詭計環繞我；猶大卻仍與神同行，向聖者忠心。","notes":["「與神同行」：七十士譯本是「為神所認識」。"],"heads":["譴責以色列"]}]},"12":{"heading":"續論以色列","verses":[{"n":1,"t":"以法蓮以風為食物，終日追逐東風，增添虛謊和殘暴，與亞述立約，也把油送到埃及。","notes":[]},{"n":2,"t":"耶和華指控猶大，要照雅各所行的懲罰他，按他所做的報應他。","notes":[]},{"n":3,"t":"他在腹中抓住哥哥的腳跟，壯年的時候與神角力，","notes":[]},{"n":4,"t":"他與天使角力，並且得勝。他曾哀哭，懇求施恩。在伯特利遇見耶和華，耶和華在那裏吩咐我們，","notes":["「我們」：七十士譯本和其他古譯本是「他」。"]},{"n":5,"t":"耶和華是萬軍之神，耶和華是他可記念的名。","notes":[]},{"n":6,"t":"所以你當歸向你的神，謹守慈愛和公平，常常等候你的神。","notes":[]},{"n":7,"t":"商人手持詭詐的天平，喜愛欺壓。","notes":["「商人」或譯「迦南」。"]},{"n":8,"t":"以法蓮說：我果然富有，得了財寶；我所勞碌得來的一切，人必找不到我有甚麼可算為有罪的惡。","notes":[]},{"n":9,"t":"自從你出埃及地以來，我就是耶和華－你的神；我必使你再住帳棚，如同節期的日子一樣。","notes":[]},{"n":10,"t":"我已吩咐眾先知，又增加異象，藉先知設比喻。","notes":[]},{"n":11,"t":"基列沒有罪孽嗎？他們誠然是虛假的，在吉甲獻牛犢為祭；他們的祭壇如同田間犁溝中的亂堆。","notes":[]},{"n":12,"t":"從前雅各逃到亞蘭地，以色列為娶妻子工作，為娶妻子而牧放。","notes":[]},{"n":13,"t":"後來耶和華藉先知領以色列從埃及上來，也藉先知看顧他們。","notes":[]},{"n":14,"t":"然而以法蓮大大惹動主怒，他所流的血必歸到他身上。主必使他的羞辱歸還給他。","notes":[]}]},"13":{"heading":"以色列最後的審判","verses":[{"n":1,"t":"從前以法蓮說話，人都戰兢，他在以色列中居處高位；但他因巴力犯罪就死了。","notes":[]},{"n":2,"t":"如今他們罪上加罪，為自己鑄造偶像，憑自己的聰明用銀子造偶像，全都是匠人所製的。論到它，有話說：獻祭的人都要親吻牛犢。","notes":[]},{"n":3,"t":"因此，他們必如早晨的雲霧，又如速散的露水，如被狂風吹離禾場的糠秕，又如煙囪冒出的煙。","notes":[]},{"n":4,"t":"自從你出埃及地以來，我就是耶和華－你的神；除了我神以外，你不認識別的，在我以外，並沒有救主。","notes":[]},{"n":5,"t":"我曾在曠野，就是那乾旱之地認識你。","notes":[]},{"n":6,"t":"他們得到餵養，就飽足；既得飽足，就心高氣傲，因而忘記了我。","notes":[]},{"n":7,"t":"因此我向他們如同獅子，又如豹伏在道旁。","notes":[]},{"n":8,"t":"我如失去小熊的母熊，攻擊他們，撕裂他們的胸膛。在那裏我必如母獅吞吃他們，如野獸撕開他們。","notes":[]},{"n":9,"t":"以色列啊，你自取滅亡了 ，因為我才是你的幫助。","notes":["「你自取滅亡了」：原文另譯「我要毀滅你」。","本節七十士譯本是「以色列啊，在你的毀滅中，誰能幫助呢？」"]},{"n":10,"t":"現在，你的王在哪裏呢？讓他在你的各城中拯救你吧！你曾說「給我立君王和官長」，那些治理你的又在哪裏呢？","notes":[]},{"n":11,"t":"我在怒氣中將王賜給你，又在烈怒中將王廢去。","notes":[]},{"n":12,"t":"以法蓮的罪孽被捲起來，他的罪惡被收藏起來。","notes":[]},{"n":13,"t":"產婦的疼痛必臨到他身上；他是無智慧之子，如同臨盆時未出現的胎兒。","notes":[]},{"n":14,"t":"我必救贖他們脫離陰間，救贖他們脫離死亡。死亡啊，你的災害在哪裏？陰間哪，你的毀滅在哪裏？憐憫必從我眼前消逝。","notes":[]},{"n":15,"t":"他在弟兄中雖然旺盛，卻有東風颳來，就是耶和華的風從曠野上來。他的泉源必乾涸，他的源頭必枯竭，這風必奪走他所積蓄的一切寶物。","notes":[]},{"n":16,"t":"撒瑪利亞要擔當罪孽，因為背叛自己的神。他們必倒在刀下，嬰孩必被摔碎，孕婦必被剖開。","notes":[]}]},"14":{"heading":"勸告以色列人","verses":[{"n":1,"t":"以色列啊，你要歸向耶和華－你的神，你因自己的罪孽跌倒了。","notes":[]},{"n":2,"t":"當歸向耶和華，用言語向他說：「求你除盡罪孽，悅納善行，我們就用嘴唇的祭代替牛犢獻上。","notes":[]},{"n":3,"t":"亞述不能救我們，我們不再騎馬，也不再對我們手所造的偶像說：『你是我們的神』；孤兒在你那裏得蒙憐憫。」","notes":[]},{"n":4,"t":"我必醫治他們背道的病，甘心愛他們，因為我向他們所發的怒氣已轉消。","notes":[],"heads":["應許以色列新生命"]},{"n":5,"t":"我必向以色列如甘露；他必如百合花開放，如黎巴嫩的樹扎根。","notes":[]},{"n":6,"t":"他的嫩枝必延伸，他的榮華如橄欖樹，香氣如黎巴嫩的香柏樹。","notes":[]},{"n":7,"t":"曾住在他蔭下的必歸回，使五穀生長，他們要發旺如葡萄樹，他的名氣如黎巴嫩的酒。","notes":["「使五穀生長」：原文另譯「他們生長如園子」；七十士譯本是「以五穀維生和得灌溉」。","「名氣」或譯「香氣」。"]},{"n":8,"t":"以法蓮說：「我與偶像有何相干？」我應允他，顧念他：我如青翠的松樹，你的果實從我而來。","notes":[]},{"n":9,"t":"智慧人必明白這些事，聰明人必知道這一切。耶和華的道是正直的，義人行在其中，罪人卻在其上跌倒。","notes":[],"heads":["結語"]}]}},"JOL":{"1":{"heading":"百姓的悲傷","verses":[{"n":1,"t":"耶和華的話臨到毗土珥的兒子約珥。","notes":[]},{"n":2,"t":"老年人哪，當聽這話；這地所有的居民哪，要側耳而聽。在你們的日子，或你們祖先的日子，曾發生過這樣的事嗎？","notes":[]},{"n":3,"t":"你們要將這事傳與子，子傳與孫，孫傳與後代。","notes":[]},{"n":4,"t":"剪蟲吃剩的，蝗蟲來吃；蝗蟲吃剩的，蝻子來吃；蝻子吃剩的，螞蚱來吃。","notes":["剪蟲、蝻子、螞蚱都是蝗蟲的一種。"]},{"n":5,"t":"醉酒的人哪，要清醒，要哭泣；好酒的人哪，都要為甜酒哀號，因為酒從你們的口中斷絕了。","notes":[]},{"n":6,"t":"有一隊蝗蟲，強盛且不可數，上來侵犯我的地；牠的牙齒如獅子的牙齒，如母獅的大牙。","notes":["「一隊蝗蟲」：原文是「一國」；2．2同。"]},{"n":7,"t":"牠毀壞我的葡萄樹，撕裂我的無花果樹，剝光又丟棄，使枝條露白。","notes":[]},{"n":8,"t":"你要像童女腰束麻布，為她年少時的丈夫哀號。","notes":[]},{"n":9,"t":"耶和華的殿中斷絕素祭和澆酒祭，事奉耶和華的祭司都悲哀。","notes":[]},{"n":10,"t":"田荒涼，地悲哀；因為五穀毀壞，新酒枯竭，新的油也缺乏。","notes":[]},{"n":11,"t":"農夫啊，你們要慚愧；修整葡萄園的啊，你們要哀號；因為大麥、小麥與田間的莊稼全都毀了。","notes":[]},{"n":12,"t":"葡萄樹枯乾，無花果樹衰殘，石榴樹、棕樹、蘋果樹，田野一切的樹木都枯乾；眾人的喜樂盡都消逝。","notes":[]},{"n":13,"t":"祭司啊，當束上麻布痛哭；事奉祭壇的啊，要哀號；事奉我神的啊，你們要來，披上麻布過夜，因為在你們神的殿中不再有素祭和澆酒祭了。","notes":[]},{"n":14,"t":"你們要使禁食的日子分別為聖，宣告嚴肅會，召集長老和這地所有的居民來到耶和華－你們神的殿，向耶和華哀求。","notes":[]},{"n":15,"t":"哀哉，這日子！因為耶和華的日子臨近，好像毀滅從全能者來到。","notes":[]},{"n":16,"t":"糧食不是在我們眼前斷絕了嗎？歡喜快樂不是從我們神的殿中止息了嗎？","notes":[]},{"n":17,"t":"種子在土塊下朽爛，倉荒涼，廩破壞，因為五穀枯乾了。","notes":[]},{"n":18,"t":"牲畜哀鳴，牛群混亂，因無草場，羊群也受苦。","notes":[]},{"n":19,"t":"耶和華啊，我向你求告，因為有火吞噬野地的草場，火焰燒盡田野的樹木。","notes":[]},{"n":20,"t":"田野的走獸切慕你，因為溪水乾涸，火吞噬了野地的草場。","notes":[]}]},"2":{"heading":"蝗災臨近","verses":[{"n":1,"t":"你們要在錫安吹角，在我的聖山發出警報。這地所有的居民要發顫，因為耶和華的日子快到，已經臨近了。","notes":[]},{"n":2,"t":"那是黑暗、陰森的日子，是密雲、烏黑的日子，如同黎明籠罩山嶺。有一隊蝗蟲，又大又強，自古以來沒有像這樣的，以後直到萬代也必沒有。","notes":[]},{"n":3,"t":"牠們前面有火吞噬，後面有火焰燒盡。牠們未到以前，地如伊甸園，過去以後，卻成了荒涼的曠野，沒有一樣能躲避牠們。","notes":[]},{"n":4,"t":"牠們形狀如馬，奔跑如戰馬。","notes":[]},{"n":5,"t":"響聲如戰車在山頂上跳動，如火焰吞噬碎稭，好像強大的軍隊擺陣備戰。","notes":[]},{"n":6,"t":"在牠們面前，萬民傷慟，臉都變色。","notes":[]},{"n":7,"t":"牠們如勇士奔跑，如戰士攀登城牆，各行於自己的道路，不亂隊伍；","notes":[]},{"n":8,"t":"牠們並不彼此推擠，各行於自己的大道，衝過防禦，並不停止。","notes":["「防禦」：原文是「兵器」。"]},{"n":9,"t":"牠們蹦上城，跳上牆，爬上房屋，從窗戶進來，如同盜賊。","notes":[]},{"n":10,"t":"在牠們面前，地動天搖，日月昏暗，星宿無光。","notes":[]},{"n":11,"t":"耶和華在他的軍旅前出聲，他的隊伍龐大，遵行他命令的強盛。耶和華的日子大而可畏，誰能當得起呢？","notes":[]},{"n":12,"t":"然而你們現在要禁食，哭泣，哀號，一心歸向我。這是耶和華說的。","notes":[],"heads":["呼籲百姓悔改"]},{"n":13,"t":"你們要撕裂心腸，不要撕裂衣服。歸向耶和華－你們的神，因為他有恩惠，有憐憫，不輕易發怒，有豐盛的慈愛，並且會改變心意，不降那災難。","notes":[]},{"n":14,"t":"誰知道他也許會回心轉意，留下餘福，就是獻給耶和華－你們神的素祭和澆酒祭。","notes":[]},{"n":15,"t":"你們要在錫安吹角，使禁食的日子分別為聖，宣告嚴肅會。","notes":[]},{"n":16,"t":"聚集百姓，使會眾自潔；召集老年人，聚集孩童和在母懷吃奶的；使新郎出內室，新娘離開洞房。","notes":[]},{"n":17,"t":"事奉耶和華的祭司要在走廊和祭壇間哭泣，說：「耶和華啊，求你顧惜你的百姓，不要使你的產業受羞辱，在列國中成為笑柄。為何讓人在萬民中說『他們的神在哪裏』呢？」","notes":[]},{"n":18,"t":"耶和華為自己的地發熱心，憐憫他的百姓。","notes":[],"heads":["神再賜福澤"]},{"n":19,"t":"耶和華應允他的百姓說：「看哪，我要賞賜你們五穀、新酒和新的油，使你們飽足，我必不再使你們受列國的羞辱。","notes":[]},{"n":20,"t":"我要使北方來的隊伍遠離你們，將他們趕到乾旱荒蕪之地：前隊趕入東海，後隊趕入西海；臭氣上升，惡臭騰空。耶和華果然行了大事！","notes":[]},{"n":21,"t":"「土地啊，不要懼怕，要歡喜快樂，因為耶和華行了大事。","notes":[]},{"n":22,"t":"田野的走獸啊，不要懼怕，因為曠野的草已生長，樹木結果，無花果樹、葡萄樹也都效力。","notes":["「效力」意思是「出產豐盛」。"]},{"n":23,"t":"「錫安的民哪，你們要歡喜，要因耶和華－你們的神快樂；因他賞賜你們合宜的秋雨，為你們降下甘霖，秋雨和春雨，和先前一樣。","notes":["「因他賞賜...秋雨」或譯「因他按公義賜秋雨給你們」或「因他賞賜你們公義的教師」。"]},{"n":24,"t":"「禾場充滿五穀，池中漫溢新酒和新的油。","notes":[]},{"n":25,"t":"我差遣到你們中間的大軍隊，就是蝗蟲、蝻子、螞蚱、剪蟲，那些年間所吃的，我要補還給你們。","notes":[]},{"n":26,"t":"「你們必吃得飽足，讚美耶和華－你們神的名，他為你們行了奇妙的事。我的百姓不致羞愧，直到永遠。","notes":[]},{"n":27,"t":"你們必知道我是在以色列中，又知道我是耶和華－你們的神，沒有別的。我的百姓不致羞愧，直到永遠。」","notes":[]},{"n":28,"t":"「以後，我要將我的靈澆灌凡有血肉之軀的。你們的兒女要說預言，你們的老人要做異夢，你們的少年要見異象。","notes":[],"heads":["耶和華的日子"]},{"n":29,"t":"在那些日子，我要將我的靈澆灌我的僕人和婢女。","notes":[]},{"n":30,"t":"「我要在天上地下顯出奇事，有血，有火，有煙柱。","notes":[]},{"n":31,"t":"太陽要變為黑暗，月亮要變為血，這都在耶和華大而可畏的日子未到以前。","notes":[]},{"n":32,"t":"那時，凡求告耶和華名的就必得救；因為照耶和華所說的，在錫安山，在耶路撒冷將有逃脫的人。凡耶和華所召的，都在餘民之列。」","notes":["「凡耶和華所召的」或譯「凡呼求耶和華的」。"]}]},"3":{"heading":"神要審判列國","verses":[{"n":1,"t":"「看哪，在那些日子，到那個時候，我使猶大和耶路撒冷被擄之人歸回的時候，","notes":[]},{"n":2,"t":"我要聚集萬民，帶他們下到約沙法谷去，在那裏我要為我百姓，我產業以色列的緣故，向萬民施行審判；因為他們把我的百姓分散到列國，瓜分了我的土地，","notes":[]},{"n":3,"t":"為我的百姓抽籤，以男孩換取妓女，為喝酒賣掉女孩。","notes":[]},{"n":4,"t":"「推羅、西頓和非利士四境的人哪，你們與我何干？你們要報復我嗎？若要報復我，我必使報應速速歸到你們頭上。","notes":[]},{"n":5,"t":"你們奪取我的金銀，把我珍貴的寶物帶入你們的廟宇，","notes":["「廟宇」或譯「宮殿」。"]},{"n":6,"t":"並將猶大人和耶路撒冷人賣給希臘人，使他們遠離自己的疆界。","notes":["「希臘人」：原文是「雅完人」。"]},{"n":7,"t":"看哪，我必激發他們離開你們把他們賣去的地方，又必使報應歸到你們頭上。","notes":[]},{"n":8,"t":"我要將你們的兒女賣到猶大人手中，他們必轉賣給遠方的國家示巴人。這是耶和華說的。」","notes":[]},{"n":9,"t":"當在列國中宣告：預備打仗，激發勇士，使所有戰士上前來。","notes":[]},{"n":10,"t":"要將犁頭打成刀劍，鐮刀打成戈矛；弱者要說：「我是勇士。」","notes":[]},{"n":11,"t":"四圍的列國啊，你們要速速前來，一同聚集。耶和華啊，求你使你的勇士降臨。","notes":[]},{"n":12,"t":"列國都當興起，上到約沙法谷；因為我必坐在那裏，審判四圍的列國。","notes":[]},{"n":13,"t":"揮鐮刀吧！因為莊稼熟了；來踩踏吧！因為醡酒池滿了。酒池已經滿溢，因為他們的罪惡甚大。","notes":[]},{"n":14,"t":"在斷定谷有許多許多的人，因為耶和華的日子臨近斷定谷了。","notes":[]},{"n":15,"t":"日月昏暗，星宿無光。","notes":[]},{"n":16,"t":"耶和華必從錫安吼叫，從耶路撒冷出聲，天地就震動。耶和華卻要作他百姓的避難所，作以色列人的保障。","notes":[],"heads":["神將賜福給他的子民"]},{"n":17,"t":"你們就知道我是耶和華－你們的神，我住在錫安－我的聖山。耶路撒冷必成為聖；陌生人不再從其中經過。","notes":[]},{"n":18,"t":"在那日，大山要滴甜酒，小山要流奶，猶大的溪河都有水流出；必有泉源從耶和華的殿中流出，滋潤什亭谷。","notes":[]},{"n":19,"t":"埃及必定荒涼，以東成為荒涼的曠野，因為他們向猶大人行殘暴，又因他們在本地流無辜人的血。","notes":[]},{"n":20,"t":"但猶大必存到永遠，耶路撒冷必存到萬代。","notes":[]},{"n":21,"t":"我要免除流人血的罪，是先前未曾免除的，耶和華居住在錫安。","notes":["「免除」：七十士譯本是「報復」；下同。"]}]}},"AMO":{"1":{"heading":"神審判以色列的鄰國","verses":[{"n":1,"t":"這是猶大王烏西雅在位與約阿施的兒子以色列王耶羅波安在位的時候，大地震前二年，從提哥亞來的牧人阿摩司所見的─他的話論到以色列。","notes":[]},{"n":2,"t":"他說：「耶和華必從錫安吼叫，從耶路撒冷出聲；牧人的草場哀傷，迦密的山頂枯乾。」","notes":[]},{"n":3,"t":"耶和華如此說：「大馬士革三番四次犯罪，以鐵的打穀機擊打基列，我必不撤銷對它的懲罰。","notes":[]},{"n":4,"t":"我要降火在哈薛的王宮，吞滅便‧哈達的宮殿；","notes":[]},{"n":5,"t":"我要折斷大馬士革的門閂，剪除亞文平原的居民和伯‧伊甸的掌權者，亞蘭人必被擄到吉珥。」這是耶和華說的。","notes":[]},{"n":6,"t":"耶和華如此說：「迦薩三番四次犯罪，擄掠全體百姓交給以東，我必不撤銷對它的懲罰。","notes":[]},{"n":7,"t":"我要降火在迦薩城內，吞滅它的宮殿；","notes":[]},{"n":8,"t":"我要剪除亞實突的居民和亞實基倫的掌權者，反手攻擊以革倫，剩餘的非利士人都必滅亡。」這是主耶和華說的。","notes":[]},{"n":9,"t":"耶和華如此說：「推羅三番四次犯罪，將全體百姓交給以東，不顧念弟兄的盟約，我必不撤銷對它的懲罰，","notes":[]},{"n":10,"t":"我要降火在推羅城內，吞滅它的宮殿。」","notes":[]},{"n":11,"t":"耶和華如此說：「以東三番四次犯罪，怒氣不停發作，永遠懷著憤怒，拿刀追趕兄弟，絲毫不存憐憫，我必不撤銷對它的懲罰。","notes":[]},{"n":12,"t":"我要降火在提幔，吞滅波斯拉的宮殿。」","notes":[]},{"n":13,"t":"耶和華如此說：「亞捫人三番四次犯罪，剖開基列的孕婦，擴張自己的疆界，我必不撤銷對它的懲罰。","notes":[]},{"n":14,"t":"我要在戰爭吶喊的日子，在旋風狂吹時，在拉巴城內放火，吞滅它的宮殿；","notes":[]},{"n":15,"t":"他們的君王和官長必一同被擄。」這是耶和華說的。","notes":[]}]},"2":{"heading":"神審判以色列","verses":[{"n":1,"t":"耶和華如此說：「摩押三番四次犯罪，把以東王的骸骨焚燒成灰，我必不撤銷對它的懲罰。","notes":[]},{"n":2,"t":"我要降火在摩押，吞滅加略的宮殿，摩押必在鬧鬨、吶喊、吹角聲中滅亡；","notes":[]},{"n":3,"t":"我要剪除摩押的領袖，把所有的官長和他一同殺戮。」這是耶和華說的。","notes":[]},{"n":4,"t":"耶和華如此說：「猶大三番四次犯罪，厭棄耶和華的訓誨，不遵守他的律例；他們祖先所隨從虛假的偶像使他們走迷了，我必不撤銷對它的懲罰。","notes":["「虛假的偶像」：原文是「虛假」。"]},{"n":5,"t":"我要降火在猶大，吞滅耶路撒冷的宮殿。」","notes":[]},{"n":6,"t":"耶和華如此說：「以色列三番四次犯罪，為銀子賣了義人，為一雙鞋賣了窮人，我必不撤銷對它的懲罰。","notes":[]},{"n":7,"t":"他們把貧寒人的頭踐踏在地的塵土上，又阻礙困苦人的道路。父子與同一個女子行淫，以致褻瀆我的聖名。","notes":["「他們...塵土上」或譯「他們切慕貧寒人頭上所蒙土地的灰塵」。"]},{"n":8,"t":"他們在各祭壇旁邊，躺臥在人所典當的衣服上，又在他們神的殿裏喝受罰之人的酒。","notes":["「他們神的殿裏」或譯「他們神明的廟中」。"]},{"n":9,"t":"「我從他們面前除滅亞摩利人；他雖高大如香柏樹，強壯如橡樹，我卻上滅其果，下絕其根。","notes":[]},{"n":10,"t":"我曾將你們從埃及地領上來，在曠野裏引導你們四十年，使你們得亞摩利人之地為業；","notes":[]},{"n":11,"t":"我從你們子孫中興起先知，又從你們少年中興起拿細耳人。以色列人哪，不是這樣嗎？」這是耶和華說的。","notes":[]},{"n":12,"t":"「你們卻把酒給拿細耳人喝，囑咐先知說：『不要說預言。』","notes":[]},{"n":13,"t":"「看哪，我要把你們壓下去，如同裝滿禾捆的車壓過一樣。","notes":[]},{"n":14,"t":"快跑的無從避難，壯士無法使力，勇士也不能自救；","notes":[]},{"n":15,"t":"拿弓的站立不住，腿快的不能逃脫，騎馬的也不能自救。","notes":[]},{"n":16,"t":"到那日，勇士中最有膽量的，必赤身逃跑。」這是耶和華說的。","notes":[]}]},"3":{"heading":"先知的任務","verses":[{"n":1,"t":"以色列人哪，當聽耶和華責備你們的話，責備我從埃及地領上來的全家，說：","notes":[]},{"n":2,"t":"「在地上萬族中，我只認識你們；因此，我必懲罰你們一切的罪孽。」","notes":[]},{"n":3,"t":"二人若不同心，豈能同行呢？","notes":[]},{"n":4,"t":"獅子若無獵物，豈會在林中咆哮呢？少壯獅子若無所得，豈會從洞裏吼叫呢？","notes":[]},{"n":5,"t":"若未設圈套，雀鳥豈能陷入地上的羅網呢？羅網若無所得，豈會從地上翻起呢？","notes":[]},{"n":6,"t":"城中若吹角，百姓豈不戰兢嗎？災禍若臨到一城，豈非耶和華所降的嗎？","notes":[]},{"n":7,"t":"主耶和華不會做任何事情，除非先將奧祕指示他的僕人眾先知。","notes":[]},{"n":8,"t":"獅子吼叫，誰不懼怕呢？主耶和華既已說了，誰能不說預言呢？","notes":[]},{"n":9,"t":"你們要在亞實突的宮殿和埃及地的宮殿傳揚，說：「要聚集在撒瑪利亞的山上，看城裏有何等大的擾亂與欺壓。」","notes":[],"heads":["撒瑪利亞的結局"]},{"n":10,"t":"「他們以暴力搶奪，堆積在自己的宮殿裏，卻不懂得行正直的事。」這是耶和華說的。","notes":[]},{"n":11,"t":"所以主耶和華如此說：「敵人必來圍攻這地，削弱你的勢力，搶掠你的宮殿。」","notes":[]},{"n":12,"t":"耶和華如此說：「牧人怎樣從獅子口中搶回兩條腿或耳朵的一小片，住撒瑪利亞的以色列人得救也是如此，不過搶回床的一角和床榻的靠枕而已。」","notes":["「床榻的靠枕」：原文另譯「大馬士革的床榻」或「床腳的一部分」。"]},{"n":13,"t":"主耶和華－萬軍之神說：「當聽這話，警戒雅各家。","notes":[]},{"n":14,"t":"我懲罰以色列罪孽的日子，也要懲罰伯特利的祭壇；祭壇的角必被砍下，墜落於地。","notes":[]},{"n":15,"t":"我要拆毀過冬和避暑的房屋，象牙的房屋必毀滅，廣廈豪宅都歸無有。」這是耶和華說的。","notes":[]}]},"4":{"heading":"以色列的失敗","verses":[{"n":1,"t":"「你們這些撒瑪利亞山上的巴珊母牛啊，當聽這話！你們欺負貧寒人，壓碎貧窮人，對主人說：『拿酒來，我們喝吧！』","notes":[]},{"n":2,"t":"主耶和華指著自己的神聖起誓說：『看哪，日子將到，人必用鉤子將你們鉤去，用魚鉤把你們中最後一個鉤去。","notes":[]},{"n":3,"t":"你們必從城牆的缺口出去，各人直往前行，投向哈門。』」這是耶和華說的。","notes":["「城牆的缺口」：原文是「缺口」。","「哈門」：原文另譯「黑門山」或「糞堆」。"]},{"n":4,"t":"「以色列人哪，任你們往伯特利去犯罪，到吉甲增加罪過，每早晨獻上你們的祭物，每三日納你們的十一奉獻；","notes":[]},{"n":5,"t":"任你們獻上有酵的感謝祭，宣揚你們的甘心祭，使人聽見，因為這是你們所喜愛的。」這是主耶和華說的。","notes":[]},{"n":6,"t":"「我使你們在每一座城裏牙齒乾淨，使你們各處的糧食缺乏，你們仍不歸向我。」這是耶和華說的。","notes":[]},{"n":7,"t":"「在收割的前三個月，我不降雨在你們那裏，我降雨在這城，不降雨在那城；這塊地有雨，那塊無雨的地就必枯乾。","notes":[]},{"n":8,"t":"兩三城的人擠到一個城去找水喝，卻喝不足，你們仍不歸向我。」這是耶和華說的。","notes":[]},{"n":9,"t":"「我以焚風和霉爛攻擊你們，你們許多的菜園、葡萄園、無花果樹、橄欖樹屢屢被剪蟲所吃，你們仍不歸向我。」這是耶和華說的。","notes":["「焚風」或譯「蟲害」。","「剪蟲」就是蝗蟲的一種。"]},{"n":10,"t":"「我降瘟疫在你們中間，如在埃及的樣子；用刀殺戮你們的年輕人和你們遭擄掠的馬匹，營中臭氣撲鼻，你們仍不歸向我。」這是耶和華說的。","notes":[]},{"n":11,"t":"「我傾覆你們，如同神從前傾覆所多瑪、蛾摩拉一樣；你們好像從火中搶救出來的一根柴，你們仍不歸向我。」這是耶和華說的。","notes":[]},{"n":12,"t":"「因此，以色列啊，我要如此對待你；因為我要這樣對待你，以色列啊，你當預備迎見你的神。」","notes":[]},{"n":13,"t":"看哪，那創山，造風，將其心意指示人，使晨光變幽暗，踩行在地之高處的，他的名是耶和華－萬軍之神。","notes":[]}]},"5":{"heading":"呼籲以色列人悔改","verses":[{"n":1,"t":"以色列家啊，聽我為你們所作的哀歌：","notes":[]},{"n":2,"t":"「以色列民跌倒，不得再起；躺在地上，無人扶起。」","notes":["「民」：原文是「少女」。"]},{"n":3,"t":"主耶和華如此說：「以色列家的城派出一千，只剩一百；派出一百，只剩十個。」","notes":[]},{"n":4,"t":"耶和華向以色列家如此說：「你們要尋求我，就必存活。","notes":[]},{"n":5,"t":"不要往伯特利尋求，不要進入吉甲，也不要過到別是巴；因為吉甲必被擄走，伯特利必歸無有。」","notes":[]},{"n":6,"t":"要尋求耶和華，就必存活，免得他在約瑟家如火發出，焚燒伯特利，無人撲滅。","notes":["「伯特利」：七十士譯本是「以色列家」。"]},{"n":7,"t":"你們這使公平變為茵蔯，將公義丟棄於地的人哪！","notes":[]},{"n":8,"t":"那造昴星和參星，使死蔭變為晨光，使白晝變為黑夜，召喚海水、使其傾倒在地面上的，耶和華是他的名。","notes":[]},{"n":9,"t":"他快速摧毀強壯的人，毀滅就臨到堡壘。","notes":[]},{"n":10,"t":"你們怨恨那在城門口斷是非的，憎惡那說正直話的。","notes":[]},{"n":11,"t":"所以，因你們踐踏貧寒人，向他們勒索糧稅；你們雖建造石鑿的房屋，卻不得住在其內；雖栽植美好的葡萄園，卻不得喝其中所出的酒。","notes":[]},{"n":12,"t":"我知道你們的罪過何其多，你們的罪惡何其大；你們迫害義人，收受賄賂，在城門口屈枉貧窮人。","notes":[]},{"n":13,"t":"所以智慧人在這樣的時候必靜默不言，因為這是險惡的時候。","notes":[]},{"n":14,"t":"你們要尋求良善，不要尋求邪惡，就必存活。這樣，耶和華－萬軍之神必照你們所說的與你們同在。","notes":[]},{"n":15,"t":"要恨惡邪惡，喜愛良善，在城門口秉公行義；或者耶和華－萬軍之神會施恩給約瑟的餘民。","notes":[]},{"n":16,"t":"因此，主耶和華－萬軍之神如此說：「在一切的廣場上必有哀號的聲音；在各街市上必有人說：『哀哉！哀哉！』他們叫農夫來哭號，叫善唱哀歌的來舉哀；","notes":[]},{"n":17,"t":"各葡萄園都有哀號的聲音，因為我必從你中間經過。」這是耶和華說的。","notes":[]},{"n":18,"t":"想望耶和華日子的人有禍了！為甚麼你們要耶和華的日子呢？那是黑暗沒有光明的日子，","notes":[]},{"n":19,"t":"好像人躲避獅子卻遇見熊；進房屋以手靠牆，卻被蛇咬。","notes":[]},{"n":20,"t":"耶和華的日子豈不是黑暗沒有光明，幽暗毫無光輝嗎？","notes":[]},{"n":21,"t":"「我厭惡你們的節期，也不喜悅你們的嚴肅會。","notes":[]},{"n":22,"t":"你們雖然向我獻燔祭和素祭，我卻不悅納，也不看你們用肥畜獻的平安祭。","notes":[]},{"n":23,"t":"要使你們歌唱的聲音遠離我，因為我不聽你們琴瑟的樂曲。","notes":[]},{"n":24,"t":"惟願公平如大水滾滾，公義如江河滔滔。","notes":[]},{"n":25,"t":"「以色列家啊，你們在曠野四十年，何嘗將祭物和供物獻給我呢？","notes":[]},{"n":26,"t":"你們抬著你們的撒古特君王，和你們為自己所造之偶像迦溫─你們的神明之星。","notes":["「你們的撒古特君王」：七十士譯本是「摩洛的帳幕」。"]},{"n":27,"t":"所以我要把你們擄到大馬士革以外。」這是耶和華說的，他的名為萬軍之神。","notes":[]}]},"6":{"heading":"以色列的毀滅","verses":[{"n":1,"t":"「那在錫安安逸，在撒瑪利亞山安穩，為列國之首，具有名望，且為以色列家所歸向的，有禍了！","notes":[]},{"n":2,"t":"你們要過到甲尼察看，從那裏往哈馬大城去，又下到非利士人的迦特，你們比這些國更好嗎？或是他們的疆界比你們的疆界廣大呢？","notes":[]},{"n":3,"t":"你們以為降禍的日子尚遠，卻使殘暴的統治臨近。","notes":["「統治」：原文是「座位」。"]},{"n":4,"t":"「那些躺臥在象牙床上，舒身在榻上的，吃群中的羔羊和棚裏的牛犢。","notes":[]},{"n":5,"t":"他們以琴瑟逍遙歌唱，為自己作曲，像大衛一樣；","notes":["「作曲」：原文是「製造樂器」。"]},{"n":6,"t":"以大碗喝酒，用上等油抹身，卻不為約瑟所受的苦難憂傷；","notes":[]},{"n":7,"t":"所以，現在這些人必首先被擄，逍遙的歡宴必消失。」","notes":[]},{"n":8,"t":"主耶和華指著自己起誓說：「我憎惡雅各的驕傲，厭棄他的宮殿；我必將城和其中一切所有的都交給敵人。」這是耶和華－萬軍之神說的。","notes":["七十士譯本沒有「這是...神說的」。"]},{"n":9,"t":"那時，若一房之內剩下十個人，也都必死。","notes":[]},{"n":10,"t":"死人的叔伯要把屍首抬到屋外焚燒，就問房屋內間的人說：「你那裏還有別人嗎？」他說：「沒有。」又說：「不要作聲，不可提耶和華的名。」","notes":[]},{"n":11,"t":"看哪，耶和華發命令，把大房子拆成碎片，小屋子裂為小塊。","notes":[]},{"n":12,"t":"馬豈能在巖石上奔跑？人豈能在那裏用牛耕種呢？你們卻使公平變為苦膽，使公義的果子變為茵蔯。","notes":["「在那裏」：原文另譯「在海上」。"]},{"n":13,"t":"你們這些喜愛羅‧底巴的，自誇說：「我們不是憑自己的力量攻佔了加寧嗎？」","notes":["「羅‧底巴」意思是「虛浮的事」。","「加寧」意思是「兩角」。"]},{"n":14,"t":"耶和華─萬軍之神說：「以色列家，看哪，我必興起一國攻擊你們；他們必欺壓你們，從哈馬口直到亞拉巴的河。」","notes":[]}]},"7":{"heading":"蝗蟲的異象","verses":[{"n":1,"t":"主耶和華指示我一件事，在春天作物剛長出時，看哪，主造了蝗蟲；看哪，這是王收割後長出的春天作物。","notes":["「主」：原文是「他」。"]},{"n":2,"t":"蝗蟲吃盡那地青草的時候，我說：「主耶和華啊，求你赦免；因為雅各弱小，他怎能站立得住呢？」","notes":[]},{"n":3,"t":"耶和華對這事改變心意，耶和華說：「這災可以免了。」","notes":[]},{"n":4,"t":"主耶和華又指示我一件事，看哪，主耶和華命火施行審判，火就吞滅深淵，燒盡產業。","notes":[],"heads":["火的異象"]},{"n":5,"t":"我就說：「主耶和華啊，求你止息；因為雅各弱小，他怎能站立得住呢？」","notes":[]},{"n":6,"t":"耶和華對這事改變心意，主耶和華說：「這災也可免了。」","notes":[]},{"n":7,"t":"他又指示我一件事，看哪，主手拿鉛垂線，站立在依鉛垂線建好的牆邊。","notes":[],"heads":["鉛垂線的異象"]},{"n":8,"t":"耶和華對我說：「阿摩司，你看見甚麼？」我說：「鉛垂線。」主說：「看哪，我要在我子民以色列中吊起鉛垂線，不再寬恕他們。","notes":[]},{"n":9,"t":"以撒的丘壇必荒涼，以色列的聖所必荒廢；我要起來用刀攻擊耶羅波安的家。」","notes":[]},{"n":10,"t":"伯特利的祭司亞瑪謝派人到以色列王耶羅波安那裏，說：「阿摩司在以色列家中圖謀背叛你，他所說的一切話，這地不能承擔；","notes":[],"heads":["阿摩司和亞瑪謝"]},{"n":11,"t":"因為阿摩司這樣說：『耶羅波安必被刀殺，以色列百姓必被擄，離開本地。』」","notes":[]},{"n":12,"t":"於是亞瑪謝對阿摩司說：「你這先見哪，要逃到猶大地，在那裏過活，在那裏說預言；","notes":["「過活」：原文是「吃」。"]},{"n":13,"t":"卻不要在伯特利再說預言，因為這裏有王的聖所，有王的宮殿。」","notes":[]},{"n":14,"t":"阿摩司對亞瑪謝說：「我原不是先知，也不是先知的門徒；我是牧人，是修剪桑樹的。","notes":[]},{"n":15,"t":"耶和華帶領我，叫我不再牧放羊群，對我說：『你去向我子民以色列說預言。』","notes":[]},{"n":16,"t":"「現在你要聽耶和華的話。你說：『不要向以色列說預言，也不要向以撒家傳講。』","notes":["「傳講」：原文是「滴下」。"]},{"n":17,"t":"所以耶和華如此說：『你的妻子要在城中作妓女，你的兒女要倒在刀下；你的地必有人用繩子量了瓜分，你自己必死在不潔淨之地；以色列百姓必被擄，離開本地。』」","notes":[]}]},"8":{"heading":"一筐果子的異象","verses":[{"n":1,"t":"主耶和華又指示我一件事，看哪，有一筐夏天的果子。","notes":[]},{"n":2,"t":"他說：「阿摩司，你看見甚麼？」我說：「一筐夏天的果子。」耶和華對我說：「我子民以色列的結局到了，我必不再寬恕他們。","notes":["「結局」與「夏天的果子」希伯來話發音相近。"]},{"n":3,"t":"那日，宮殿裏的詩歌要變為哀號；必有許多屍首拋在各處，安靜無聲。」這是主耶和華說的。","notes":["「宮殿裏...哀號」：原文另譯「宮殿裏唱歌的女子要哀號」。"]},{"n":4,"t":"你們這些踐踏貧窮人、使這地困苦人衰敗的，當聽這話！","notes":[],"heads":["以色列的結局"]},{"n":5,"t":"你們說：「初一幾時過去，我們好賣糧；安息日幾時過去，我們好擺開穀物；我們要把伊法變小，把舍客勒變大，以詭詐的天平欺哄人，","notes":[]},{"n":6,"t":"用銀子買貧寒人，以一雙鞋換貧窮人，把壞的穀物賣給人。」","notes":[]},{"n":7,"t":"耶和華指著雅各的驕傲起誓說：「他們這一切的行為，我必永遠不忘。","notes":[]},{"n":8,"t":"地豈不因這事震動？其中的居民豈不悲哀嗎？全地必如尼羅河漲起，如埃及的尼羅河湧起退落。","notes":[]},{"n":9,"t":"「到那日，我要使太陽在正午落下，使這地在白晝黑暗。」這是主耶和華說的。","notes":[]},{"n":10,"t":"「我要使你們的節期變為悲哀，你們一切的歌曲變為哀歌；我要使眾人腰束麻布，頭上光禿；我要使這悲哀如喪獨子，其結局如悲痛的日子。","notes":[]},{"n":11,"t":"「看哪，日子將到，我必命饑荒降在地上；人飢餓非因無餅，乾渴非因無水，而是因不聽耶和華的話。」這是主耶和華說的。","notes":[]},{"n":12,"t":"他們必飄流，從這海到那海，從北邊到東邊，往來奔跑，尋求耶和華的話，卻尋不著。","notes":[]},{"n":13,"t":"「當那日，少年和美貌的少女必因乾渴而發昏。","notes":[]},{"n":14,"t":"那些指著撒瑪利亞的罪孽起誓的，說：『但哪，我們指著你那裏的神明起誓』，又說：『我們指著通往別是巴的路起誓』，這些人都必仆倒，永不再起。」","notes":["「罪孽」：原文另譯「亞示瑪像」；參王下17．30。"]}]},"9":{"heading":"耶和華的審判","verses":[{"n":1,"t":"我看見主站在祭壇旁，說：「你要擊打柱頂，使門檻震動，要剪除眾人當中為首的，他們中最後的，我必用刀殺戮；無一人能逃避，無一人能逃脫。","notes":["「要剪除...最後的」或譯「要砍掉它們，落在眾人頭上，所剩下的人」。"]},{"n":2,"t":"「雖然他們挖透陰間，我的手必從那裏拉出他們；雖然他們爬到天上，我必從那裏拿下他們；","notes":[]},{"n":3,"t":"雖然藏在迦密山頂，我必在那裏搜尋，擒拿他們；雖然離開我眼前藏在海底，我必在那裏命令蛇咬他們；","notes":[]},{"n":4,"t":"雖然被仇敵擄去，我也必在那裏命令刀劍殺戮他們；我必定睛在他們身上，降禍不降福。」","notes":[]},{"n":5,"t":"萬軍的主耶和華觸摸地，地就融化，凡住在地上的都必悲哀；全地必如尼羅河漲起，如同埃及的尼羅河落下。","notes":[]},{"n":6,"t":"那在天上建造樓閣、在地上奠定穹蒼、召喚海水、使其傾倒在地面上的，耶和華是他的名。","notes":[]},{"n":7,"t":"耶和華說：「以色列人哪，我豈不是看你們如古實人嗎？我豈不是領以色列人出埃及地，也領非利士人出迦斐託，領亞蘭人出吉珥嗎？","notes":["「古實」包括蘇丹的大部分和埃塞俄比亞的一部分。"]},{"n":8,"t":"看哪，主耶和華的眼目察看這有罪的國度，要把它從地面上滅絕，卻不將雅各家滅絕淨盡。」這是耶和華說的。","notes":[]},{"n":9,"t":"「看哪，我發命令，使以色列家在萬國中飄流，好像人用篩子篩穀，連一粒也不落在地上。","notes":[]},{"n":10,"t":"我子民中所有的罪人，就是那些說『災禍必不靠近，必不追上我們』的，都必死在刀下。」","notes":[]},{"n":11,"t":"「在那日，我必重建大衛倒塌的帳幕，修補其中的缺口；我必建立那遭破壞的，重新修造，如古時一般，","notes":[],"heads":["以色列的復興"]},{"n":12,"t":"使以色列人接管以東所剩餘的和所有稱為我名下的國。這是耶和華說的，他要行這事。","notes":[]},{"n":13,"t":"「看哪，日子將到，耕種的必接續收割的，踹葡萄的必接續撒種的；大山要滴下甜酒，小山也被漫過。」這是耶和華說的。","notes":[]},{"n":14,"t":"「我要使以色列被擄的子民歸回；他們要重修荒廢的城鎮，居住在其中；栽植葡萄園，喝其中所出的酒，修造果園，吃其中的果子。","notes":[]},{"n":15,"t":"我要將他們栽植於本地，他們必不再從我所賜給他們的地上被拔出。」這是耶和華－你的神說的。","notes":[]}]}},"OBA":{"1":{"heading":"耶和華懲罰以東","verses":[{"n":1,"t":"俄巴底亞所見的異象。我們從耶和華那裏得到消息，有使者被差往列國去：「起來吧，我們要起來與以東爭戰！」主耶和華論以東如此說：","notes":[]},{"n":2,"t":"看哪，我要使你在列國中為最小，被人大大藐視。","notes":[]},{"n":3,"t":"你狂傲的心欺騙了你，你住在巖穴，居所在高處，心裏說：「誰能把我拉下來到地上呢？」","notes":[]},{"n":4,"t":"你雖如鷹高飛，在星宿之間搭窩，我必從那裏拉你下來。這是耶和華說的。","notes":[]},{"n":5,"t":"盜賊若來到你那裏，小偷夜間來到，豈不是只偷他們所需要的嗎？摘葡萄的若來到你那裏，豈不留下幾串嗎？你竟全然滅絕！","notes":[]},{"n":6,"t":"以掃遭到搜查，他隱藏的寶物竟被尋出！","notes":[]},{"n":7,"t":"與你結盟的都驅趕你，直到邊界，與你和好的欺騙你，勝過你，吃你飯的人設下圈套陷害你─他卻毫無聰明。","notes":["「他卻毫無聰明」或譯「你卻毫無知覺」。"]},{"n":8,"t":"到那日，我豈不從以東除滅智慧人？從以掃山除滅聰明人？這是耶和華說的。","notes":[]},{"n":9,"t":"提幔哪，你的勇士必驚惶，以致以掃山的人都被殺戮剪除。","notes":[]},{"n":10,"t":"因你向兄弟雅各施暴，你必蒙羞，永被剪除。","notes":[],"heads":["以東受罰的原因"]},{"n":11,"t":"當陌生人擄掠雅各的財物，當外邦人進入他的城門，為耶路撒冷抽籤分取財物的日子，你竟站在一旁，像與他們同夥。","notes":[]},{"n":12,"t":"你兄弟遭難的日子，你不該瞪著眼看；猶大人被滅的日子，你不該幸災樂禍；他們遭難的日子，你不該說狂傲的話。","notes":[]},{"n":13,"t":"我子民遭災的日子，你不該進他們的城門；他們遭災的日子，你不該瞪著眼看他們受苦；他們遭災的日子，你不該伸手搶他們的財物。","notes":[]},{"n":14,"t":"他們遭難的日子，你不該站在岔路口剪除他們逃脫的人，你不該交出他們的倖存者。","notes":[]},{"n":15,"t":"耶和華的日子臨近萬國；你所做的，人也必向你照樣做，你的報應必歸到自己頭上。","notes":[],"heads":["耶和華審判萬國"]},{"n":16,"t":"你們在我聖山怎樣喝了苦杯，萬國必照樣不停地喝，且喝且吞，他們就必歸於無有。","notes":[]},{"n":17,"t":"但在錫安山必有逃脫的人，那山必成為聖；雅各家必得原有的產業。","notes":["「原有的產業」：七十士譯本是「那搶奪他們之人的產業」。"],"heads":["以色列的勝利"]},{"n":18,"t":"雅各家必成為大火，約瑟家成為火焰；以掃家必如碎稭，遭燃燒，被吞滅，以掃家必無倖存者。這是耶和華說的。","notes":[]},{"n":19,"t":"他們必得尼革夫和以掃山，得謝非拉，非利士人之地，他們必得以法蓮地和撒瑪利亞地，得便雅憫和基列；","notes":["「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」；下同。","「謝非拉」是音譯，意思是「低地」。"]},{"n":20,"t":"被擄的以色列大軍必得迦南人的地，直到撒勒法，在西法拉被擄的耶路撒冷人必得尼革夫的城鎮。","notes":["「迦南」指「腓尼基」。"]},{"n":21,"t":"必有一些解救者上到錫安山，審判以掃山，國度就歸耶和華了。","notes":["「一些解救者」：七十士譯本是「一些被救出的人」。"]}]}},"JON":{"1":{"heading":"約拿違背耶和華","verses":[{"n":1,"t":"耶和華的話臨到亞米太的兒子約拿，說：","notes":[]},{"n":2,"t":"「起來，到尼尼微大城去，向其中的居民宣告，因為他們的惡已達到我面前。」","notes":[]},{"n":3,"t":"約拿卻起身，逃往他施去躲避耶和華。他下到約帕，遇見一條船要往他施去。約拿付了船費，就上船，與船上的人同往他施，為要躲避耶和華。","notes":[]},{"n":4,"t":"耶和華在海上颳起大風，海就狂風大作，船幾乎破裂。","notes":[]},{"n":5,"t":"水手都懼怕，各人哀求自己的神明。他們把船上的貨物拋進海裏，為要減輕載重。約拿卻下到艙底，躺臥沉睡。","notes":[]},{"n":6,"t":"船長到他那裏，對他說：「你怎麼還在沉睡呢？起來，求告你的神明，或者神明顧念我們，使我們不致滅亡。」","notes":[]},{"n":7,"t":"船上的人彼此說：「來吧，我們來抽籤，看看這災難臨到我們是因誰的緣故。」於是他們就抽籤，抽出約拿來。","notes":[]},{"n":8,"t":"他們對約拿說：「請你告訴我們，這災難臨到我們是因誰的緣故呢？你做甚麼行業？你從哪裏來？你是哪一國的人？屬哪一族？」","notes":[]},{"n":9,"t":"他說：「我是希伯來人，我敬畏耶和華，天上的神，他創造了滄海和陸地。」","notes":[]},{"n":10,"t":"那些人就大大懼怕，對他說：「你做的是甚麼事呢？」原來他們已經知道他在躲避耶和華，因為他告訴了他們。","notes":[]},{"n":11,"t":"海浪越來越洶湧，他們就問他說：「我們當向你做甚麼，才能使海浪平靜呢？」","notes":[]},{"n":12,"t":"他對他們說：「你們把我抬起來，拋進海裏，海就會平靜了；我知道你們遭遇這大風浪是因我的緣故。」","notes":[]},{"n":13,"t":"然而那些人竭力划槳，想要把船靠回陸地，卻是不能；因風浪越來越大，撲向他們。","notes":[]},{"n":14,"t":"於是他們求告耶和華說：「耶和華啊，求求你不要因這人的性命使我們滅亡，不要使流無辜人血的罪歸給我們；因為你－耶和華隨自己的旨意行事。」","notes":[]},{"n":15,"t":"他們把約拿抬起來，拋進海裏，海的狂浪就平息了。","notes":[]},{"n":16,"t":"那些人就大大懼怕耶和華，向耶和華獻祭許願。","notes":[]},{"n":17,"t":"耶和華安排一條大魚吞下約拿，約拿在魚腹中三日三夜。","notes":[]}]},"2":{"heading":"約拿的禱告","verses":[{"n":1,"t":"約拿在魚腹中向耶和華－他的神禱告，","notes":[]},{"n":2,"t":"說：「我在患難中求告耶和華，他就應允我；我從陰間的深處呼求，你就俯聽我的聲音。","notes":[]},{"n":3,"t":"你將我投下深淵，直到海心；大水環繞我，你的波浪洪濤漫過我身。","notes":[]},{"n":4,"t":"我說：『我從你眼前被驅逐，然而我仍要仰望你的聖殿。』","notes":[]},{"n":5,"t":"眾水環繞我，幾乎淹沒我；深淵圍住我；海草纏繞我的頭。","notes":[]},{"n":6,"t":"我下沉到山的根基，地的門閂將我永遠關住。耶和華－我的神啊，你卻將我的性命從地府裏救出來。","notes":[]},{"n":7,"t":"我心靈發昏時，就想起耶和華。我的禱告進入你的聖殿，達到你面前。","notes":[]},{"n":8,"t":"那信奉虛無神明的人，丟棄自己的慈愛；","notes":["「虛無神明」：原文是「虛無」。"]},{"n":9,"t":"但我要以感謝的聲音向你獻祭。我所許的願，我必償還。救恩出於耶和華。」","notes":[]},{"n":10,"t":"耶和華吩咐那魚，魚就把約拿吐在陸地上。","notes":[]}]},"3":{"heading":"約拿順服耶和華","verses":[{"n":1,"t":"耶和華的話第二次臨到約拿，說：","notes":[]},{"n":2,"t":"「起來，到尼尼微大城去，把我告訴你的信息向其中的居民宣告。」","notes":[]},{"n":3,"t":"約拿就照耶和華的話起來，到尼尼微去。尼尼微是一座極大的城，約有三天的路程。","notes":[]},{"n":4,"t":"約拿進城，走了一天，宣告說：「再過四十天，尼尼微要傾覆了！」","notes":[]},{"n":5,"t":"尼尼微人就信服神，宣告禁食，從最大的到最小的都穿上麻衣。","notes":[]},{"n":6,"t":"這消息傳到尼尼微王那裏，他就從寶座起來，脫下朝服，披上麻布，坐在灰中。","notes":[]},{"n":7,"t":"他叫人通告尼尼微全城，說：「王和大臣有令，人、畜、牛、羊都不可嘗任何東西，不可吃，也不可喝水。","notes":[]},{"n":8,"t":"人與牲畜都要披上麻布，切切求告神。各人要回轉離開惡道，離棄自己掌中的殘暴。","notes":[]},{"n":9,"t":"誰知道神也許會回心轉意，不發烈怒，使我們不致滅亡。」","notes":[]},{"n":10,"t":"神察看他們的行為，見他們離開惡道，神就改變心意，原先所說要降與他們的災難，他不降了。","notes":[]}]},"4":{"heading":"約拿的憤怒和神的憐憫","verses":[{"n":1,"t":"這事令約拿大大不悅，甚至發怒。","notes":[]},{"n":2,"t":"他就向耶和華禱告，說：「耶和華啊，這不就是我仍在本國的時候所說的嗎？我知道你是有恩惠，有憐憫的神，不輕易發怒，有豐盛的慈愛，並且會改變心意，不降那災難。我就是因為這樣，才急速逃往他施去的呀！","notes":[]},{"n":3,"t":"耶和華啊，現在求你取走我的性命吧！因為我死了比活著更好。」","notes":[]},{"n":4,"t":"耶和華說：「你這樣發怒，對嗎？」","notes":[]},{"n":5,"t":"約拿出城，坐在城的東邊，在那裏為自己搭了一座棚。他坐在棚子的蔭下，要看看城裏會發生甚麼事。","notes":[]},{"n":6,"t":"耶和華神安排了一棵蓖麻，使它生長高過約拿，影子遮蓋他的頭，使他免受苦難；約拿因這棵蓖麻大大歡喜。","notes":[]},{"n":7,"t":"次日黎明，神卻安排一條蟲來咬這蓖麻，以致枯乾。","notes":[]},{"n":8,"t":"太陽出來的時候，神安排炎熱的東風，太陽曝曬約拿的頭，使他發昏，他就為自己求死，說：「我死了比活著更好！」","notes":[]},{"n":9,"t":"神對約拿說：「你因這棵蓖麻這樣發怒，對嗎？」他說：「我發怒以至於死，都是對的！」","notes":[]},{"n":10,"t":"耶和華說：「這棵蓖麻你沒有為它操勞，也不是你使它長大的；它一夜生長，一夜枯死，你尚且愛惜；","notes":[]},{"n":11,"t":"何況這尼尼微大城，其中不能分辨左右手的就有十二萬多人，還有許多牲畜，我豈能不愛惜呢？」","notes":[]}]}},"MIC":{"1":{"heading":"先知唱哀歌","verses":[{"n":1,"t":"當猶大王約坦、亞哈斯、希西家在位的時候，耶和華的話臨到摩利沙人彌迦，他見到有關撒瑪利亞和耶路撒冷的異象。","notes":[]},{"n":2,"t":"萬民哪，你們都要聽！地和其上所有的，要留心聽！主耶和華要從他的聖殿指證你們的不是。","notes":[]},{"n":3,"t":"看哪，耶和華從他的居所出來，降臨步行地之高處。","notes":[]},{"n":4,"t":"眾山在他底下熔化，諸谷崩裂，如蠟熔在火中，如水沖下山坡。","notes":[]},{"n":5,"t":"這都是因雅各的罪過，因以色列家的罪惡。雅各的罪過在哪裏呢？豈不是在撒瑪利亞嗎？猶大的丘壇在哪裏呢？豈不是在耶路撒冷嗎？","notes":[]},{"n":6,"t":"因此，我必使撒瑪利亞變為田野的廢墟，用以栽植葡萄；我必把它的石頭倒在山谷，掀開它的地基。","notes":[]},{"n":7,"t":"城裏一切雕刻的偶像必被打碎，行淫的賞金全被火燒，我要毀滅它的一切偶像；因為從妓女的賞金積聚而來的，它們仍歸為妓女的賞金。","notes":[]},{"n":8,"t":"為此我要大聲哀號，赤身赤腳行走；我要呼號如野狗，哀鳴如鴕鳥。","notes":[]},{"n":9,"t":"因為撒瑪利亞的創傷無法醫治，蔓延到猶大，到了我百姓的城門，直達耶路撒冷。","notes":[]},{"n":10,"t":"不要在迦特宣揚這事，千萬不要哭泣；卻要在伯‧亞弗拉翻滾於灰塵中。","notes":["「宣揚」與「迦特」的希伯來話發音相近。","「灰塵」與「亞弗拉」的希伯來話發音相近。"],"heads":["敵人迫近耶路撒冷"]},{"n":11,"t":"沙斐的居民哪，要赤身羞愧地經過，撒南的居民不敢出門，伯‧以薛哀哭，不再支持你們。","notes":[]},{"n":12,"t":"瑪律的居民心甚憂急，切望得著福氣，因為災禍已從耶和華那裏臨到耶路撒冷的城門。","notes":[]},{"n":13,"t":"拉吉的居民哪，要用快馬套車；錫安的罪由你而起，以色列的罪過在你那裏顯出。","notes":["「用快馬」與「拉吉」的希伯來話發音相近。","「錫安」：原文直譯「錫安女子」。"]},{"n":14,"t":"因此，你要將送別禮送到摩利設‧迦特；亞革悉的眾家族必用詭詐待以色列諸王。","notes":["「詭詐」與「亞革悉」的希伯來話發音相近。"]},{"n":15,"t":"瑪利沙的居民哪，我必使搶奪者來到你這裏；以色列的貴族必來到亞杜蘭。","notes":["「貴族」：原文是「榮耀」。"]},{"n":16,"t":"猶大啊，為了你所喜愛的兒女，你要剪髮，剃光頭，要使你的頭光禿，如同禿鷹，因為他們被擄去離開你了。","notes":[]}]},"2":{"heading":"欺壓者的命運","verses":[{"n":1,"t":"禍哉，那些在床上圖謀罪孽、籌劃惡事的人！天一亮，他們因手中有能力就去行惡。","notes":[]},{"n":2,"t":"他們看上田地就佔據，貪圖房屋便奪取；他們欺壓戶主和他的家庭，霸佔人和他的產業。","notes":[]},{"n":3,"t":"所以耶和華如此說：看哪，我籌劃災禍降與這家族；這災禍在你們頸項上無法解脫，你們也不能昂首而行，因為這是災禍的時刻。","notes":[]},{"n":4,"t":"到那日，必有人為你們唱詩歌，用悲哀的哀歌哀號，說：「我們全然敗落，我百姓的產業易主了！耶和華竟然使它離開我，我們的田地為悖逆的人所瓜分了！」","notes":[]},{"n":5,"t":"因此，你必無人能在耶和華的會中抽籤拉繩。","notes":["「抽籤拉繩」意思是「劃地為界」。"]},{"n":6,"t":"他們傳講說：「不可傳講；人都不可傳講這些事，羞辱不會臨到我們。」","notes":[]},{"n":7,"t":"雅各家啊，可這麼說嗎？耶和華沒有耐心嗎？這些事是他所行的嗎？我的言語豈不是與行動正直的人有益嗎？","notes":["「雅各家…說嗎」：原文另譯「雅各家能被詛咒嗎」。"]},{"n":8,"t":"然而，近來我的百姓興起如仇敵。你們剝去那些安然行路、不願打仗之人身上的外衣，","notes":[]},{"n":9,"t":"把我百姓中的婦人從安樂家中趕出，又將我的榮耀從她們孩子身上永遠奪去。","notes":[]},{"n":10,"t":"起來，走吧！這裏並非安歇之處；因為不潔淨帶來毀壞，且是大大的毀壞。","notes":[]},{"n":11,"t":"若有人心存虛假，用謊言說：「我向你們傳講可得清酒和烈酒」，那人就必作這百姓的傳講者。","notes":["「用謊言說」：原文另譯「我會用謊言說」。","「烈酒」與「謊言」的希伯來話發音相近。"]},{"n":12,"t":"雅各家啊，我定要聚集你們，定要召集以色列的餘民，將他們安置在一處，如波斯拉的羊，又如草場上的羊群，人數眾多，大大喧嘩。","notes":["「波斯拉」或譯「羊圈」。"]},{"n":13,"t":"開路的在他們前面上去，直闖過城門，從城門出去；他們的王在前面行，耶和華在他們的前頭。","notes":[]}]},"3":{"heading":"斥責以色列的領袖","verses":[{"n":1,"t":"於是我說：雅各的領袖，以色列家的官長啊，你們要聽！你們豈不知道公平嗎？","notes":[]},{"n":2,"t":"你們惡善好惡，剝我百姓身上的皮，從他們的骨頭上剔肉，","notes":["「我百姓」：原文是「他們」。"]},{"n":3,"t":"你們吃我百姓的肉，剝他們的皮，打斷他們的骨頭，如切塊下鍋，如釜中的肉。","notes":["「如切塊」：七十士譯本是「如切肉塊」。"]},{"n":4,"t":"到了遭災的時候，這些人要哀求耶和華，他卻不應允他們。那時，因他們所行的惡，他必轉臉離開他們。","notes":[]},{"n":5,"t":"論到使我百姓走入歧途的先知，他們牙齒有所嚼，就呼喊說：「平安！」誰不給他們吃，就揚言攻擊他，耶和華如此說：","notes":[]},{"n":6,"t":"你們因此必遭遇黑夜，看不到異象；遭遇幽暗，無法占卜。太陽必向先知沉落，白晝轉為黑暗。","notes":[]},{"n":7,"t":"先見必抱愧，占卜的必蒙羞，他們全都摀著鬍鬚，因為神不應允他們。","notes":[]},{"n":8,"t":"至於我，我藉耶和華的靈，滿有能力、公平和勇氣，可以向雅各述說他的過犯，向以色列指出他的罪惡。","notes":[]},{"n":9,"t":"當聽這話，雅各家的領袖，以色列家的官長啊！你們厭棄公平，在一切事上屈枉正直；","notes":[]},{"n":10,"t":"以血建立錫安，以罪孽建造耶路撒冷。","notes":[]},{"n":11,"t":"城裏的領袖為賄賂行審判，祭司為酬勞施訓誨，先知為銀錢行占卜；他們卻倚賴耶和華，說：「耶和華不是在我們中間嗎？災禍必不臨到我們。」","notes":[]},{"n":12,"t":"因此，為你們的緣故，錫安要被耕種像一塊田地，耶路撒冷要變為廢墟，這殿的山必如叢林的高處。","notes":[]}]},"4":{"heading":"永恆的和平","verses":[{"n":1,"t":"末後的日子，耶和華殿的山必堅立，超乎諸山，高舉過於萬嶺；萬民都要流歸這山。","notes":[]},{"n":2,"t":"必有許多民族前往，說：「來吧，我們登耶和華的山，到雅各神的殿。他必將他的道指教我們，我們也要行他的路。」因為教誨必出於錫安，耶和華的言語必出於耶路撒冷。","notes":[]},{"n":3,"t":"他必在許多民族中施行審判，為遠方強盛的國斷定是非。他們要將刀打成犁頭，把槍打成鐮刀。這國不舉刀攻擊那國，他們也不再學習戰事。","notes":[]},{"n":4,"t":"人人都要坐在自己的葡萄樹和無花果樹下，無人使他們驚嚇；這是萬軍之耶和華親口說的。","notes":[]},{"n":5,"t":"萬民都奉自己神明的名行事，我們卻要奉耶和華－我們神的名而行，直到永永遠遠。","notes":[]},{"n":6,"t":"耶和華說：在那日，我必聚集瘸腿的，召集被趕逐的，以及我所懲治的人。","notes":[],"heads":["以色列人歸回本國"]},{"n":7,"t":"我要使瘸腿的成為餘民，使被趕到遠方的成為強盛之國。耶和華要在錫安山作王治理他們，從今直到永遠。","notes":[]},{"n":8,"t":"你，以得臺，錫安的山岡啊，先前的權柄必歸給你，耶路撒冷的國權必將歸還。","notes":["「以得臺」就是「牧羊人的瞭望臺」；參創35．21。","「錫安」：原文直譯「錫安女子」；下同。","「耶路撒冷」：原文是「耶路撒冷女子」。"]},{"n":9,"t":"現在，你為何大聲呼喊呢？你中間沒有君王，你的謀士滅絕，以致疼痛抓住你，如臨產的婦人嗎？","notes":[]},{"n":10,"t":"錫安哪，你要疼痛生產，彷彿臨產的婦人；因為你必從城裏出來，住在田野；你要到巴比倫去，在那裏，你要蒙解救，在那裏，耶和華必救贖你脫離仇敵的手掌。","notes":[]},{"n":11,"t":"現在，許多國家聚集攻擊你，說：「讓錫安被玷污！讓我們親眼看到！」","notes":[]},{"n":12,"t":"他們卻不知道耶和華的意念，也不明白他的籌算，他聚集他們，像把禾捆聚到禾場。","notes":[]},{"n":13,"t":"錫安哪，起來踹穀吧！我必使你的角成為鐵，使你的蹄成為銅。你必打碎許多民族，將他們的財寶獻給耶和華，將他們的財富獻給全地的主。","notes":[]}]},"5":{"heading":"神應許一位掌權者出於伯利恆","verses":[{"n":1,"t":"成群的民哪，現在要聚集成隊；仇敵前來圍攻我們，要用杖擊打以色列領袖的臉頰。","notes":["「民」：原文是「女兒」。"]},{"n":2,"t":"伯利恆的以法他啊，你在猶大諸城中雖小，將來必有一位從你那裏出來，在以色列中為我作掌權者；他的根源自亙古，從太初就有。","notes":[]},{"n":3,"t":"因此，耶和華要將以色列人交給敵人，直到臨產的婦人生下孩子；那時，他其餘的弟兄必回到以色列人那裏。","notes":[]},{"n":4,"t":"他必倚靠耶和華的大能，倚靠耶和華－他神之名的威嚴，站立並牧養，使他們安然居住；因為現在他必尊大，直到地極。","notes":[]},{"n":5,"t":"這位就是和平。當亞述侵入我們領土，踐踏我們宮殿時，我們就立七個牧者，八個領袖攻擊它。","notes":["「和平」或譯「平安」。"]},{"n":6,"t":"他們要用刀劍毀壞亞述地和寧錄地的關口。當亞述侵入我們領土，踐踏我們邊境時，他必拯救我們。","notes":["「寧錄地的關口」：有古譯本是「向寧錄地拔出刀來」。"]},{"n":7,"t":"雅各的餘民必在許多民族中，如從耶和華降下的露水，又如甘霖降在草上；他們不倚靠人，也不仰賴世人。","notes":[]},{"n":8,"t":"雅各的餘民必在列國中，在許多民族中，如林間百獸中的獅子，又如少壯獅子在羊群中；他若經過就必踐踏撕裂，無人搭救。","notes":[]},{"n":9,"t":"願你的手舉起，高過敵人！願你的仇敵都被剪除！","notes":[]},{"n":10,"t":"耶和華說：到那日，我必從你中間剪除馬匹，毀壞戰車；","notes":[]},{"n":11,"t":"除滅你國中的城鎮，拆毀你一切的堡壘；","notes":[]},{"n":12,"t":"除掉你手中的邪術，你那裏也不再有占卜的人。","notes":[]},{"n":13,"t":"我必從你中間除滅雕刻的偶像和柱像，你就不再跪拜自己手所造的；","notes":[]},{"n":14,"t":"我必從你中間拔除亞舍拉，毀滅你的城鎮；","notes":[]},{"n":15,"t":"我必在怒氣和憤怒中報應那不聽從我的列國。","notes":[]}]},"6":{"heading":"耶和華譴責以色列","verses":[{"n":1,"t":"當聽耶和華說的話：起來，向山嶺爭辯，使岡陵聽見你的聲音。","notes":[]},{"n":2,"t":"山嶺啊，要聽耶和華的指控！大地永久的根基啊，要聽！因耶和華控告他的百姓，與以色列爭辯。","notes":[]},{"n":3,"t":"「我的百姓啊，我向你做了甚麼呢？我在甚麼事上使你厭煩？你回答我吧！","notes":[]},{"n":4,"t":"我曾將你從埃及地領出來，從為奴之家救贖你，我差遣摩西、亞倫和米利暗在你前面帶領。","notes":[]},{"n":5,"t":"我的百姓啊，當記念從前摩押王巴勒如何籌算，比珥的兒子巴蘭如何回應他，當記念從什亭到吉甲所發生的事，好使你們明白耶和華公義的作為。」","notes":[]},{"n":6,"t":"「我朝見耶和華，在至高神面前跪拜，當獻上甚麼呢？難道獻一歲的牛犢為燔祭來朝見他嗎？","notes":[],"heads":["耶和華的要求"]},{"n":7,"t":"耶和華豈喜悅千千的公羊，或是萬萬的油河嗎？我豈可為自己的過犯獻我的長子，為自己的罪惡獻我所親生的嗎？」","notes":[]},{"n":8,"t":"世人哪，耶和華已指示你何為善。他向你所要的是甚麼呢？只要你行公義，好憐憫，存謙卑的心與你的神同行。","notes":[]},{"n":9,"t":"耶和華向這城呼叫─看重你的名是真智慧─你們當聽懲罰和派定懲罰的人。","notes":["「看重...真智慧」：七十士譯本是「他會拯救敬畏他名的人」。","「懲罰」：原文是「刑杖」；下同。","「你們當聽...的人」：有古譯本是「聽啊，支派和城的眾民！」七十士譯本是「聽啊，支派，誰管治這城？」"]},{"n":10,"t":"惡人家中不是仍有不義之財和惹人生氣的變小了的伊法嗎？","notes":[]},{"n":11,"t":"我若用不公道的天平和袋中詭詐的法碼，豈可算為清白呢？","notes":[]},{"n":12,"t":"城裏的有錢人遍行殘暴，其中的居民說謊話，口中的舌頭盡是詭詐。","notes":[]},{"n":13,"t":"因此，我也擊打你，使你受傷，因你的罪惡使你受驚駭。","notes":["「我也擊打你，使你受傷」：七十士譯本和其他古譯本是「我也開始擊打你」。"]},{"n":14,"t":"你要吃，卻吃不飽，你的肚子仍是空空。你必被挪去，不得逃脫；如有逃脫的，我必交給刀劍。","notes":[]},{"n":15,"t":"你撒種，卻不得收割；踹橄欖，卻不得油抹身；有新酒，卻不得酒喝。","notes":[]},{"n":16,"t":"因為你遵守暗利的規條，行亞哈家一切所行的，順從他們的計謀；因此，我必使你荒涼，使你的居民遭人嗤笑，你們也必擔當我百姓的羞辱。","notes":[]}]},"7":{"heading":"以色列人的腐敗","verses":[{"n":1,"t":"我有禍了！我好像夏日收割後的果子，又如收成之後剩餘的葡萄，沒有一掛可吃的，也沒有我心所渴想初熟的無花果。","notes":[]},{"n":2,"t":"地上的虔誠人滅盡了，人世間已無正直的人；他們都埋伏，為要流人的血，用羅網獵取自己的弟兄。","notes":[]},{"n":3,"t":"他們雙手善於作惡，君王和審判官都索取賄賂；位高的人吐出心中的慾望，彼此勾結。","notes":["「彼此勾結」：原文另譯「禍哉，公義被扭曲了」。"]},{"n":4,"t":"他們當中最好的，不過像蒺藜；最正直的，不過如荊棘籬笆。你守候的日子，懲罰已經來到，他們必擾亂不安。","notes":[]},{"n":5,"t":"不可倚賴鄰舍，不可信靠密友；甚至對躺在你懷中的妻子也要守住你的口。","notes":[]},{"n":6,"t":"因為兒子藐視父親，女兒抵擋母親，媳婦抗拒婆婆，人的仇敵就是自己家裏的人。","notes":[]},{"n":7,"t":"至於我，我要仰望耶和華，等候那救我的神；我的神必應允我。","notes":[]},{"n":8,"t":"我的仇敵啊，不要向我誇耀。我雖跌倒，仍要起來；雖坐在黑暗裏，耶和華卻作我的光。","notes":[],"heads":["耶和華拯救他的子民"]},{"n":9,"t":"我要承受耶和華的惱怒，直到他為我辯護，為我伸冤，因我得罪了他；他要領我進入光明，我必得見他的公義。","notes":[]},{"n":10,"t":"那時我的仇敵看見這事就羞愧，他曾對我說：「耶和華－你的神在哪裏？」我必親眼見他遭報，現在，他必被踐踏，如同街上的泥土。","notes":[]},{"n":11,"t":"你的城牆重修的日子到了！到那日，邊界必擴展。","notes":[]},{"n":12,"t":"到那日，人必從亞述，從埃及的城鎮，從埃及到大河，從這海到那海，從這山到那山，都歸到你這裏。","notes":[]},{"n":13,"t":"然而，因居民的緣故，為了他們行事的結果，這地必然荒涼。","notes":[]},{"n":14,"t":"求你在迦密的樹林中，以你的杖牧放你獨居的民，你產業中的羊群；願他們像古時一樣，牧放在巴珊和基列。","notes":["「迦密」或譯「佳美園地」。"],"heads":["耶和華憐憫以色列"]},{"n":15,"t":"我要顯奇事給他們看，好像出埃及地的時候一樣。","notes":[]},{"n":16,"t":"列國看見，雖大有勢力仍覺慚愧；他們必用手摀口，掩耳不聽。","notes":[]},{"n":17,"t":"他們要舔土如蛇，又如地上爬行的動物，戰戰兢兢離開他們的營寨；他們必畏懼耶和華─我們的神，也必因你而害怕。","notes":[]},{"n":18,"t":"有哪一個神明像你，赦免罪孽，饒恕他產業中餘民的罪過？他不永遠懷怒，喜愛施恩。","notes":[]},{"n":19,"t":"他必轉回憐憫我們，把我們的罪孽踏在腳下。你必將他們一切的罪投於深海。","notes":["「他」：原文另譯「你」。","「他們」：七十士譯本和其他古譯本是「我們」。"]},{"n":20,"t":"你必按古時向我們列祖起誓的話，以信實待雅各，向亞伯拉罕施慈愛。","notes":[]}]}},"NAM":{"1":{"heading":"耶和華向尼尼微發怒","verses":[{"n":1,"t":"論尼尼微的默示，伊勒歌斯人那鴻所見異象的書。","notes":[]},{"n":2,"t":"耶和華是忌邪、報應的神。耶和華施報應，大有憤怒；耶和華向他的敵人報應，向他的仇敵懷怒。","notes":["「忌邪」：原文是「妒忌」，意思是「不容許有對立的神明」。"]},{"n":3,"t":"耶和華不輕易發怒，大有能力，但耶和華萬不以有罪的為無罪。他的道路在旋風和暴風之中，雲彩為他腳下的塵土。","notes":[]},{"n":4,"t":"他斥責海，使海枯乾，使一切江河乾涸。巴珊和迦密衰殘，黎巴嫩的花草也衰殘了。","notes":[]},{"n":5,"t":"大山因他震動，小山也都融化；大地在他面前突起，世界和住在其間的也都如此。","notes":[]},{"n":6,"t":"他發憤恨，誰能立得住呢？他發烈怒，誰能當得起呢？他的憤怒如火傾洩而出，磐石因他崩裂。","notes":[]},{"n":7,"t":"耶和華本為善，在患難的日子為人的保障，並且認識那些投靠他的人；","notes":[]},{"n":8,"t":"但他必以漲溢的洪水淹沒其地方，又驅逐仇敵進入黑暗。","notes":["「其地方」：七十士譯本是「起來攻擊的人」。"]},{"n":9,"t":"你們籌劃何種計謀攻擊耶和華呢？他必終結一切，仇敵不會再度興起。","notes":["「仇敵」或譯「災難」。"]},{"n":10,"t":"你們像雜亂的荊棘，像喝醉了的人，又如枯乾的碎稭，全然燒滅。","notes":[]},{"n":11,"t":"有一人從你那裏出來，圖謀邪惡，設惡計攻擊耶和華。","notes":[]},{"n":12,"t":"耶和華如此說：「他們雖然勢力強大，人數眾多，也要被剪除，歸於無有。我雖曾使你受苦，卻不再使你受苦。","notes":[]},{"n":13,"t":"現在，我要從你身上折斷他的軛，解開捆綁你的繩索。」","notes":[]},{"n":14,"t":"耶和華已經發命令，指著你說：「你的名下必不再留後；我要從你神明的廟中除滅雕刻的偶像和鑄造的偶像，我必因你的卑賤，為你預備墳墓。」","notes":[]},{"n":15,"t":"看哪，在山上有報佳音、傳平安之人的腳蹤。猶大啊，守你的節期，還你的願吧！因為惡人不再侵犯你，他已滅絕淨盡了。","notes":[]}]},"2":{"heading":"尼尼微的傾覆","verses":[{"n":1,"t":"那打碎你的人上到你面前。要看守堡壘，把守道路，要挺起腰來，大大使力。","notes":["「打碎你的人」或譯「驅散你的人」。"]},{"n":2,"t":"耶和華復興雅各的榮華，像復興以色列的榮華；因為蹂躪者曾經蹂躪他們，毀壞了他們的葡萄枝。","notes":[]},{"n":3,"t":"他勇士的盾牌是紅的，精兵都穿朱紅衣服。在預備打仗的日子，戰車上的鐵閃爍如火，柏木的槍桿也已舉起；","notes":["「戰車...如火」：原文另譯「戰車如火把的火」。","「柏木...舉起」：七十士譯本是「騎兵在躍馬前進」。"]},{"n":4,"t":"戰車在街上疾行，在廣場上來往奔馳，形狀如火把，飛馳如閃電。","notes":[]},{"n":5,"t":"他招聚他的貴族；他們前行時絆跌，速上城牆，預備屏障。","notes":["「他」指「尼尼微王」。"]},{"n":6,"t":"河閘開放，宮殿沖沒。","notes":[]},{"n":7,"t":"這是命定之事：王后赤身被擄，宮女捶胸，哀鳴如鴿子。","notes":["「這是命定之事...被擄」或譯「女神像赤身被擄」；原文另可音譯作「胡釵芙王后赤身被擄」。"]},{"n":8,"t":"尼尼微自古以來如同聚水的池子；現在居民都在逃跑。「站住！站住！」卻無人回轉。","notes":["「尼尼微...逃跑」：七十士譯本是「至於尼尼微，它的水如同一個漏水的池子」。"]},{"n":9,"t":"你們搶奪金子吧！你們搶奪銀子吧！因為所積蓄的無窮，華美的寶器無數。","notes":[]},{"n":10,"t":"荒蕪，荒涼，全然荒廢，人心害怕，雙膝顫抖，腰部疼痛，臉都變色。","notes":[]},{"n":11,"t":"獅子的洞，幼獅餵養之處在哪裏呢？公獅、母獅、小獅出入，無人使牠們驚嚇之地在哪裏呢？","notes":[]},{"n":12,"t":"公獅撕碎的足夠給幼獅吃，又為母獅掐死獵物，把獵物塞滿牠的洞穴，把撕碎的裝滿牠的窩。","notes":[]},{"n":13,"t":"看哪，我與你為敵，將它的戰車焚燒成煙，刀劍必吞滅你的少壯獅子；我必從地上除滅你的獵物，你使者的聲音必不再聽見。這是萬軍之耶和華說的。","notes":["「它的戰車」：原文另譯「你的戰車」；七十士譯本是「你的群眾」。"]}]},"3":{"heading":"","verses":[{"n":1,"t":"禍哉！這流人血的城，欺詐連連，搶奪充斥，擄掠的事總不止息。","notes":[]},{"n":2,"t":"鞭聲響亮，車輪轟轟，馬匹跳躍，戰車奔騰；","notes":[]},{"n":3,"t":"騎兵爭先，刀劍發光，槍矛閃爍，被殺的甚多，屍首成堆，屍骸無數，人因屍骸而絆跌，","notes":[]},{"n":4,"t":"都因那美貌的妓女多有淫行，慣行邪術，藉淫行誘惑列國，用邪術誘惑萬族。","notes":["「誘惑」：原文是「賣」；下同。"]},{"n":5,"t":"看哪，我與你為敵，掀開你的下襬，蒙在你臉上，使列邦看見你的赤體，使列國觀看你的羞辱。這是萬軍之耶和華說的。","notes":[]},{"n":6,"t":"我必將可憎污穢之物拋在你身上，使你被藐視，為眾人所觀看。","notes":[]},{"n":7,"t":"凡看見你的，都必逃離你，說：「尼尼微荒涼了！有誰為你悲傷呢？我何處找到安慰你的人呢？」","notes":[]},{"n":8,"t":"你能勝過挪亞們嗎？它坐落在眾河之間，周圍有水，海作它的城郭，海作它的城牆。","notes":["「挪亞們」就是埃及的底比斯，也稱「挪」。","「海」指尼羅河；下同。","「海」：七十士譯本是「眾水」。"]},{"n":9,"t":"古實和埃及是它的力量，沒有窮盡，弗人和路比人是它的幫手。","notes":["「古實」包括蘇丹的大部分和埃塞俄比亞的一部分。","「弗」是利比亞的一部分。","「路比」就是利比亞。"]},{"n":10,"t":"但它被流放，被人擄去，它的嬰孩也被摔碎在各街頭；人為它的貴族抽籤，它的權貴都被鎖鏈鎖住。","notes":[]},{"n":11,"t":"你也必喝醉，昏迷錯亂，並因仇敵的緣故尋求庇護。","notes":[]},{"n":12,"t":"你一切的堡壘必如無花果樹上初熟的果子，一經搖動，就落在想吃的人口中。","notes":[]},{"n":13,"t":"看哪，你中間的士兵是婦女，你國中的關口向仇敵敞開，你的門閂被火焚燒。","notes":[]},{"n":14,"t":"你要打水預備受困；要加強防禦，取土踹泥，做成磚模。","notes":[]},{"n":15,"t":"在那裏，火要吞滅你，刀必殺戮你，如蝻子般吞滅你。你人數增多如蝻子，增多如蝗蟲吧！","notes":[]},{"n":16,"t":"你增添商賈，多過天上的星宿；如蝻子蛻皮飛去。","notes":[]},{"n":17,"t":"你的領袖多如蝗蟲，你的將軍彷彿成群的蝗蟲；天涼時齊落在籬笆上，太陽一出就飛去，人不知道落在何處。","notes":[]},{"n":18,"t":"亞述王啊，你的牧人睡覺，你的貴族躺臥，你的百姓散在山間，無人招聚。","notes":["「躺臥」：原文另譯「安歇」。"]},{"n":19,"t":"你的損傷並未減輕，你的傷痕極其重大。凡聽見這消息的人都因你拍掌。有誰沒有時常遭受你的暴行呢？","notes":[]}]}},"HAB":{"1":{"heading":"哈巴谷的訴苦","verses":[{"n":1,"t":"哈巴谷先知所看見的默示。","notes":[]},{"n":2,"t":"耶和華啊，我呼求，你不應允，要到幾時呢？我向你呼喊「暴力！」你還不拯救？","notes":[]},{"n":3,"t":"你為何使我看見罪孽？你為何坐視奸惡呢？毀滅和兇暴在我面前，爭執與紛爭不斷發生。","notes":[]},{"n":4,"t":"因此律法無效，公理從未彰顯。惡人圍困義人，所以公理遭受扭曲。","notes":[]},{"n":5,"t":"你們要向列國觀看，注意看，要驚奇，再驚奇！因為在你們的日子，有一件事發生，儘管有人說了，你們還是不信。","notes":["「你們要向列國觀看」：七十士譯本是「你們這些藐視的人要觀看」。","「有一件事發生」：七十士譯本是「我行一件事」。"],"heads":["耶和華的回答"]},{"n":6,"t":"看哪，我必興起迦勒底人，就是那殘忍暴躁之民，通行遍地，霸佔不屬自己的住處。","notes":[]},{"n":7,"t":"他威武可畏，審判與威權都由他而出。","notes":[]},{"n":8,"t":"他的馬比豹更快，比晚上的野狼更猛。他的戰馬跳躍，他的戰馬從遠方而來；他們飛跑，如鷹急速抓食，","notes":["「晚上」：七十士譯本是「阿拉伯」。","「他的戰馬跳躍...而來」：七十士譯本是「他的騎兵奔馳，從遠方而來」。"]},{"n":9,"t":"都為施行殘暴而來，他們的臉面向東，聚集俘虜，多如塵沙。","notes":["「向東」：原文另譯「向前」。"]},{"n":10,"t":"他譏誚列王，嘲諷領袖，嗤笑一切堡壘，堆土攻取它。","notes":[]},{"n":11,"t":"那時，他如風猛然掃過，他背叛，顯為有罪；他以自己的力量為神明。","notes":[]},{"n":12,"t":"耶和華－我的神，我的聖者啊，你不是從亙古就有嗎？我們必不致死。耶和華啊，你派他為要行審判；磐石啊，你立他為要懲治人。","notes":[],"heads":["哈巴谷又訴苦"]},{"n":13,"t":"你的眼目清潔，不看邪惡，也不看奸惡，為何你卻看著人行詭詐呢？惡人吞滅比自己公義的人，為何你保持沉默呢？","notes":[]},{"n":14,"t":"你為何使人如海中的魚，又如無人管轄的爬行動物呢？","notes":[]},{"n":15,"t":"他用鉤子把他們全拉上來，用羅網捕獲他們，拉漁網聚集他們。因此，他歡喜快樂，","notes":[]},{"n":16,"t":"向羅網獻祭，向漁網燒香；因為他藉此得豐盛的收穫與肥美的食物。","notes":[]},{"n":17,"t":"但他豈可因此屢屢倒空羅網，時常殺戮列國的人，毫不顧惜呢？","notes":["「倒空羅網」：死海古卷是「拔刀出鞘」。"]}]},"2":{"heading":"耶和華回答哈巴谷","verses":[{"n":1,"t":"我要站在我的瞭望臺，立在城樓上觀看，看耶和華要對我說甚麼，我可用甚麼話向他訴冤。","notes":["「城樓」：死海古卷是「我的城樓」。"]},{"n":2,"t":"耶和華回答我，說：將這默示清楚地寫在看板上，使人容易朗讀。","notes":["「使人容易朗讀」：原文是「使跑的人也可以朗讀」。"]},{"n":3,"t":"因為這默示有一定的日期，論及終局，絕不落空。它雖然耽延，你要等候；因為它必臨到，不再遲延。","notes":[]},{"n":4,"t":"看哪，惡人自高自大，心不正直；惟義人必因他的信得生。","notes":["「因他的信得生」或譯「因他的信實得生」；七十士譯本是「因我的信實得生」。"]},{"n":5,"t":"他因酒詭詐、狂傲、不安於位；他張開喉嚨，好像陰間，如死亡不能知足，他聚集萬國，招聚萬民全歸自己。","notes":["「張開喉嚨」或譯「擴充心欲」。"],"heads":["不義的結局"]},{"n":6,"t":"這些人豈不都要提起詩歌和俗語，嘲諷他說：禍哉！你增添不屬自己的財物，靠押金發財，要到幾時呢？","notes":[]},{"n":7,"t":"咬傷你的豈不忽然興起，擾害你的豈不突然崛起，你就成為他們的擄物嗎？","notes":["「咬傷你的」或譯「借你錢的」。"]},{"n":8,"t":"因你搶奪許多國家，流人的血，向土地、城鎮和全城的居民施行殘暴，各國殘存之民都必搶奪你。","notes":[]},{"n":9,"t":"禍哉！那為本家積蓄不義之財、在高處搭窩、指望得免災禍的人！","notes":[]},{"n":10,"t":"你圖謀剪除許多民族，犯了罪，使自己的家蒙羞，自害己命。","notes":[]},{"n":11,"t":"牆裏的石頭要呼叫，屋內的棟梁必應聲。","notes":[]},{"n":12,"t":"禍哉！那以鮮血建城、以罪孽造鎮的人！","notes":[]},{"n":13,"t":"看哪，這不都是出於萬軍之耶和華嗎？萬民勞碌得來的被火焚燒，萬族辛苦建造的，歸於虛空。","notes":["「看哪，這不都是」：原文另譯「它們不都是」。"]},{"n":14,"t":"全地都必認識耶和華的榮耀，好像水充滿海洋一般。","notes":[]},{"n":15,"t":"禍哉！那給鄰舍酒喝，加上毒物，使人喝醉，為要看見他們下體的人！","notes":["「加上毒物」或譯「傾倒怒氣」。"]},{"n":16,"t":"你滿受羞辱，不得榮耀；你也喝吧，顯明你是未受割禮的！耶和華右手的杯必傳到你那裏，你的榮耀就變為羞辱。","notes":["「顯明你是未受割禮的」：死海古卷、一些古卷和七十士譯本是「搖搖晃晃吧」。"]},{"n":17,"t":"黎巴嫩所受的殘暴必淹沒你，野獸所遭遇的毀滅使你驚嚇；因你流人的血，向土地、城鎮和全城的居民施行殘暴。","notes":["「使你驚嚇」是根據七十士譯本和其他古譯本；原文是「使牠們驚嚇」。"]},{"n":18,"t":"偶像有甚麼益處呢？製造者雕刻它，鑄成偶像，作虛假的教師；製造者倚靠的是自己所做的啞巴偶像。","notes":[]},{"n":19,"t":"禍哉！那對木頭說「醒起」，對啞巴石頭說「起來」的人！偶像豈能教導人呢？看哪，它以金銀包裹，其中並無氣息。","notes":[]},{"n":20,"t":"惟耶和華在他的聖殿中，全地都當在他面前肅靜。","notes":[]}]},"3":{"heading":"哈巴谷的祈禱","verses":[{"n":1,"t":"哈巴谷先知的禱告，調用流離歌。","notes":[]},{"n":2,"t":"耶和華啊，我聽見你的名聲；耶和華啊，我懼怕你的作為。求你在這些年間復興你的作為，在這些年間將它顯明出來；在發怒的時候以憐憫為念。","notes":["「在這些年間」：七十士譯本是「這些年臨近的時候」。","「將它顯明出來」：七十士譯本是「你會顯明出來」。"]},{"n":3,"t":"神從提幔而來，聖者從巴蘭山臨到；（細拉）他的榮光遮蔽諸天，頌讚遍滿全地。","notes":[]},{"n":4,"t":"他的輝煌如同日光，從他手裏發出光芒，那裏隱藏他的能力。","notes":["「那裏」：原文另譯「天上」。"]},{"n":5,"t":"在他前面有瘟疫流行，在他腳下有熱症發出。","notes":[]},{"n":6,"t":"他站立，震動大地，他觀看，震動列國。永久的山崩裂，長存的嶺塌陷，他的作為與古時一樣。","notes":["「震動」或譯「量」。"]},{"n":7,"t":"我見古珊的帳棚遭難，米甸地的幔子動搖。","notes":[]},{"n":8,"t":"耶和華啊，你豈是向江河發怒，向江河生氣，向海洋發烈怒嗎？你騎在馬上，坐在得勝的戰車上，","notes":[]},{"n":9,"t":"你的弓全然顯露，箭是發誓的言語；（細拉）你以江河分開大地。","notes":["「你的弓全然顯露」：原文另譯「你打開弓套」。","「箭是發誓的言語」：原文另譯「箭在弦上待命」；七十士譯本的一個抄本是「你把你的箭袋裝滿了箭」。"]},{"n":10,"t":"山嶺見你，無不戰抖；大水氾濫而過，深淵發聲，洶湧翻騰。","notes":["「洶湧翻騰」：原文是「向上舉手」。"]},{"n":11,"t":"因你的箭射出光芒，你的槍閃出光耀，日月都停在原處。","notes":[]},{"n":12,"t":"你發怒遍行大地，以怒氣責打列國，如打穀一般。","notes":[]},{"n":13,"t":"你出來拯救你的百姓，拯救你的受膏者；你打破惡人之家的頭，暴露其根基，直到頸項。 （細拉）","notes":["「頸項」意思是「上端」。"]},{"n":14,"t":"你以其戈矛刺透他戰士的頭；他們如旋風將我颳散，他們喜愛暗中吞吃困苦的人。","notes":["「我」：原文另譯「我們」。"]},{"n":15,"t":"你騎馬踐踏海，踐踏洶湧的大水。","notes":[]},{"n":16,"t":"我聽見這聲音，身體戰兢，嘴唇發顫，骨中朽爛，在所立之處戰兢；但我安靜等候災難之日臨到那上來侵犯我們的民。","notes":["「在所立之處戰兢」：原文另譯「我的腳步在所立之處戰兢」。","「但我...民」或譯「我只可安靜等候災難之日臨到，侵犯我們的民上來」。"]},{"n":17,"t":"雖然無花果樹不發旺，葡萄樹不結果，橄欖樹也不收成，田地不出糧食，圈中絕了羊，棚內也沒有牛；","notes":[]},{"n":18,"t":"然而，我要因耶和華歡欣，因救我的神喜樂。","notes":[]},{"n":19,"t":"主耶和華是我的力量，他使我的腳快如母鹿，又使我穩行在高處。這歌交給聖詠團長，用絲弦的樂器。","notes":[]}]}},"ZEP":{"1":{"heading":"耶和華審判的日子","verses":[{"n":1,"t":"當亞們的兒子猶大王約西亞在位的時候，耶和華的話臨到希西家的玄孫，亞瑪利雅的曾孫，基大利的孫子，古示的兒子西番雅。","notes":[]},{"n":2,"t":"耶和華說：「我必從地面上徹底除滅萬物。","notes":[]},{"n":3,"t":"我必除滅人與牲畜，除滅空中的鳥、海裏的魚、絆腳石和惡人；我必把人從地面上剪除，這是耶和華說的。","notes":[]},{"n":4,"t":"我必伸手攻擊猶大和耶路撒冷所有的居民；從這地方剪除剩下的巴力、事奉偶像之祭司的名字與祭司；","notes":[]},{"n":5,"t":"還有那些在屋頂拜天上萬象的，那些敬拜耶和華指著他起誓，卻又指著米勒公起誓的；","notes":["「米勒公」是根據七十士譯本和其他古譯本，亞捫人神明的名字，又名「摩洛」；原文是「他們的王」，音譯「瑪勒堪」。"]},{"n":6,"t":"並那些轉去不跟從耶和華，不尋求耶和華，也不求問他的。」","notes":[]},{"n":7,"t":"在主耶和華面前要靜默無聲，因為耶和華的日子快到了。耶和華已經預備祭物，將召來的人分別為聖。","notes":[]},{"n":8,"t":"「到了獻祭給耶和華的日子，我要懲罰領袖和王子，及所有穿外邦衣服的人。","notes":[]},{"n":9,"t":"到那日，我必懲罰所有跳過門檻，以殘暴和詭詐塞滿主人房屋的人。","notes":[]},{"n":10,"t":"「當那日，從魚門必發出悲哀的聲音，從第二城區發出哀號的聲音，從山間發出破裂的大響聲。這是耶和華說的。","notes":[]},{"n":11,"t":"瑪革提施的居民哪，你們要哀號，因為所有的商人都滅亡了，滿載銀子的人都被剪除。","notes":["「商人」或譯「迦南人」。"]},{"n":12,"t":"那時，我必用燈巡查耶路撒冷，懲罰那些沉湎在酒渣上的人；他們心裏說：『耶和華必不降福，也不降禍。』","notes":[]},{"n":13,"t":"他們的財寶成為掠物，房屋變為廢墟。他們建造房屋，卻不得住在其內；栽葡萄園，卻不得喝其中所出的酒。」","notes":[]},{"n":14,"t":"耶和華的大日臨近，臨近而且甚快；那是耶和華日子的風聲，勇士必在那裏痛痛地哭號。","notes":[]},{"n":15,"t":"那日是憤怒的日子，急難困苦的日子，荒廢淒涼的日子，黑暗幽冥的日子，烏雲密佈的日子，","notes":[]},{"n":16,"t":"是吹角吶喊的日子，要攻擊堅固的城，攻擊高大的城樓。","notes":[]},{"n":17,"t":"我必使災禍臨到人身上，使他們行走如同盲人，因為他們得罪了耶和華；他們的血必倒出如灰塵，肉身拋棄如糞土。","notes":[]},{"n":18,"t":"當耶和華發怒的日子，他們的金銀不能救自己；耶和華妒忌的火必燒滅全地，要向地上所有的居民施行可怕的毀滅。","notes":[]}]},"2":{"heading":"呼籲百姓悔改","verses":[{"n":1,"t":"不知羞恥的國民哪，趁命令尚未發出，日子流逝如糠秕，耶和華的烈怒尚未臨到你們，他發怒的日子未到以先，你們應當聚集，聚集起來。","notes":[],"end":2},{"n":3,"t":"世上遵守耶和華典章的謙卑人哪，你們都當尋求耶和華，尋求公義，尋求謙卑；或許在耶和華發怒的日子得以隱藏。","notes":[]},{"n":4,"t":"迦薩必遭遺棄，亞實基倫必然荒涼；亞實突人必在正午被趕出，以革倫也要連根拔除。","notes":["「遺棄」與「迦薩」的希伯來話發音相近。","「連根拔除」與「以革倫」的希伯來話發音相近。"],"heads":["以色列鄰國的結局"]},{"n":5,"t":"禍哉，住沿海之地的基利提人！迦南、非利士人之地啊，耶和華的話攻擊你們：我必毀滅你，以致無人居住。","notes":[]},{"n":6,"t":"沿海之地要變為草場，牧人的住處和羊群的圈。","notes":["「住處」或譯「井」或「牧場」。"]},{"n":7,"t":"這地必為猶大家的餘民所得；他們要在那裏放牧，晚上躺臥在亞實基倫的房屋中；因為耶和華－他們的神必眷顧他們，使被擄的人歸回。","notes":[]},{"n":8,"t":"我聽見摩押毀謗，亞捫人辱罵；他們辱罵我的百姓，自誇自大，侵犯他們的疆土。」","notes":[]},{"n":9,"t":"萬軍之耶和華－以色列的神說：因此，我指著我的永生起誓：摩押必如所多瑪，亞捫人必像蛾摩拉，都變為刺草、鹽坑、永遠荒廢之地。我百姓中剩餘的必擄掠他們，我國中的倖存者必得他們的地。","notes":[]},{"n":10,"t":"這事臨到他們是因他們的驕傲，他們自誇自大，辱罵萬軍之耶和華的百姓。","notes":[]},{"n":11,"t":"耶和華必向他們顯為可畏，因他使地上的眾神衰微；列國的海島各在自己的地方敬拜他。","notes":[]},{"n":12,"t":"你們古實人，也是被我的刀所殺的。","notes":["「古實」包括蘇丹的大部分和埃塞俄比亞的一部分。"]},{"n":13,"t":"耶和華要伸手攻擊北方，毀滅亞述，使尼尼微荒涼，乾旱如同曠野。","notes":[]},{"n":14,"t":"群畜，就是各類的走獸必臥在其中，鵜鶘和豪豬要宿在柱頂；窗戶有鳴叫的聲音，門檻毀壞，他要毀壞香柏木板。","notes":["「類」：原文是「國」。","「門檻毀壞」：七十士譯本是「烏鴉在門檻」。","「他要毀壞香柏木板」：原文另譯「香柏木板顯露」。"]},{"n":15,"t":"這素來歡樂、安然居住的城，心裏說：「惟有我，除我以外再沒有別的」，現在竟然荒涼，成為野獸躺臥之處！凡經過的人都必搖著手嗤笑它。","notes":[]}]},"3":{"heading":"耶路撒冷的罪惡和救贖","verses":[{"n":1,"t":"禍哉，這欺壓的城！悖逆，污穢，","notes":[]},{"n":2,"t":"不聽從命令，不領受訓誨，不倚靠耶和華，不親近它的神。","notes":[]},{"n":3,"t":"其中的領袖是咆哮的獅子，審判官是晚上的野狼，不留一點到早晨。","notes":["「晚上」：七十士譯本是「阿拉伯」。"]},{"n":4,"t":"它的先知是虛浮詭詐的人，祭司褻瀆聖所，強解律法。","notes":[]},{"n":5,"t":"耶和華在它中間是公義的，斷不做非義的事，每早晨顯明他的公義，無日不然；只是不義的人不知羞恥。","notes":[]},{"n":6,"t":"「我已經除滅列國，使他們的城樓荒廢。我使他們街道荒涼，無人經過；他們的城鎮毀壞，沒有人，沒有居民。","notes":[]},{"n":7,"t":"我說：『只要你敬畏我，領受訓誨；其住處就不會照我原先所定的被剪除。』然而，他們從早起來就在各樣事上敗壞自己。","notes":["「其住處...被剪除」：七十士譯本是「你們就不會從它眼中被剪除，我要徹底地報復它」。"]},{"n":8,"t":"「你們要等候我，直到我興起擄掠的日子；因為我已定意招聚列邦，聚集列國，將我的惱怒，我一切的烈怒，都傾倒在它們身上。我妒忌的火必燒滅全地。這是耶和華說的。","notes":["「擄掠」：七十士譯本和其他古譯本是「作證」。"]},{"n":9,"t":"「那時，我要改變萬民，使他們有清潔的嘴唇，好求告耶和華的名，同心合意事奉我。","notes":[]},{"n":10,"t":"那些向我祈求的，我所分散的子民，必從古實河的那一邊，獻供物給我。","notes":["「子民」：原文是「女兒」。"]},{"n":11,"t":"「當那日，你必不再因一切得罪我的事蒙羞，因為那時我必從你中間除掉狂喜高傲的人，在我的聖山上你也不再狂傲。","notes":[]},{"n":12,"t":"我卻要在你中間留下困苦貧寒的百姓，他們必投靠耶和華的名。","notes":[]},{"n":13,"t":"以色列的餘民必不行惡，不說謊，口中沒有詭詐的舌頭；他們吃喝躺臥，無人使他們驚嚇。」","notes":[]},{"n":14,"t":"錫安哪，應當歌唱！以色列啊，應當歡呼！耶路撒冷啊，應當滿心歡喜快樂！","notes":["「錫安」：原文直譯「錫安女子」。","「耶路撒冷」：原文是「耶路撒冷女子」。"],"heads":["歡樂之歌"]},{"n":15,"t":"耶和華已經免去對你的審判，趕出你的仇敵。以色列的王－耶和華在你中間；你必不再懼怕災禍。","notes":[]},{"n":16,"t":"當那日，必有話對耶路撒冷說：「不要懼怕！錫安哪，不要手軟！","notes":[]},{"n":17,"t":"耶和華－你的神在你中間大有能力，施行拯救。他必因你歡欣喜樂，他在愛中靜默，且因你而喜樂歡呼。","notes":[]},{"n":18,"t":"我要聚集那些因無節期而愁煩的人，他們曾遠離你，是你的重擔和羞辱。","notes":["「是你的…羞辱」：原文是「是它的重擔和羞辱」；七十士譯本是「哀哉，誰使它受到羞辱」。"]},{"n":19,"t":"那時，看哪，我必對付所有苦待你的人，拯救瘸腿的，召集被趕出的；那些在全地受羞辱的，我必使他們得稱讚，享名聲。","notes":[]},{"n":20,"t":"那時，我必領你們回來，召集你們；我使你們被擄之人歸回的時候，必使你們在地上的萬民中享名聲，得稱讚；這是耶和華說的。」","notes":[]}]}},"HAG":{"1":{"heading":"耶和華命令重建聖殿","verses":[{"n":1,"t":"大流士王第二年六月初一，耶和華的話藉哈該先知向撒拉鐵的兒子猶大省長所羅巴伯和約撒答的兒子約書亞大祭司傳講，說：","notes":[]},{"n":2,"t":"「萬軍之耶和華如此說，這百姓說，建造耶和華殿的時候還沒有到。」","notes":["「建造...還沒有到」：原文另譯「現在還沒有到建造耶和華殿的時候」。"]},{"n":3,"t":"耶和華的話藉哈該先知傳講，說：","notes":[]},{"n":4,"t":"「這殿荒涼，你們自己還住天花板的房屋嗎？","notes":[]},{"n":5,"t":"現在，萬軍之耶和華如此說，你們要省察自己的行為。","notes":[]},{"n":6,"t":"你們撒的種多，收的卻少；你們吃，卻不得飽；喝，卻不得足；穿衣服，卻不得暖；領工錢的，領了工錢卻裝入有破洞的袋中。","notes":[]},{"n":7,"t":"「萬軍之耶和華如此說，你們要省察自己的行為。","notes":[]},{"n":8,"t":"你們要上山取木料，建造這殿，我就因此喜樂，且得榮耀。這是耶和華說的。","notes":[]},{"n":9,"t":"你們盼望多得，看哪，所得的卻少；你們收到家中，我就吹去。這是為甚麼呢？因為我的殿荒涼，你們各人卻只為自己的房屋奔走。這是萬軍之耶和華說的。","notes":[]},{"n":10,"t":"所以，因你們的緣故，天不降甘露，地也不出土產。","notes":["七十士譯本沒有「因你們的緣故」。"]},{"n":11,"t":"我命令乾旱臨到土地、山岡、五穀、新酒、新油和地上的出產，也臨到人和牲畜，以及一切人手勞碌得來的。」","notes":[]},{"n":12,"t":"那時，撒拉鐵的兒子所羅巴伯、約撒答的兒子約書亞大祭司，和所有倖存的百姓都聽從耶和華－他們神的話，就是哈該先知奉耶和華他們神差遣所說的話；百姓在耶和華面前存敬畏的心。","notes":[],"heads":["百姓順從耶和華的命令"]},{"n":13,"t":"耶和華的使者哈該奉耶和華差遣對百姓說：「我與你們同在。這是耶和華說的。」","notes":[]},{"n":14,"t":"耶和華激發撒拉鐵的兒子猶大省長所羅巴伯、約撒答的兒子約書亞大祭司，和所有倖存百姓的心，他們就來為萬軍之耶和華－他們神的殿做工。","notes":[]},{"n":15,"t":"這是在大流士王第二年六月二十四日。","notes":[]}]},"2":{"heading":"新殿的榮耀","verses":[{"n":1,"t":"七月二十一日，耶和華的話藉哈該先知傳講，說：","notes":[]},{"n":2,"t":"「你要曉諭撒拉鐵的兒子猶大省長所羅巴伯、約撒答的兒子約書亞大祭司，和所有倖存的百姓，說：","notes":[]},{"n":3,"t":"『你們中間存留的，有誰見過這殿從前的榮耀呢？現在你們看如何？在你們眼中豈不是如同無有嗎？","notes":[]},{"n":4,"t":"所羅巴伯啊，現在，你當剛強！這是耶和華說的。約撒答的兒子約書亞大祭司啊，你當剛強！這是耶和華說的。這地的百姓啊，你們都當剛強做工，因為我與你們同在。這是萬軍之耶和華說的。","notes":[]},{"n":5,"t":"這是照著你們出埃及時我與你們立約的話。我的靈仍要住在你們中間，你們不必懼怕。","notes":[]},{"n":6,"t":"萬軍之耶和華如此說：過些時候，我必再一次震動天地、滄海與乾地。","notes":[]},{"n":7,"t":"我必震動萬國，萬國的珍寶都必運來，我就使這殿充滿榮耀。這是萬軍之耶和華說的。","notes":["「萬國...必運來」或譯「萬國所羨慕的必來到」。"]},{"n":8,"t":"銀子是我的，金子也是我的。這是萬軍之耶和華說的。","notes":[]},{"n":9,"t":"這後來的殿的榮耀必大過先前的榮耀。這是萬軍之耶和華說的。在這地方我必賜平安。這是萬軍之耶和華說的。』」","notes":[]},{"n":10,"t":"大流士王第二年九月二十四日，耶和華的話臨到哈該先知，說：","notes":[],"heads":["先知向祭司請教"]},{"n":11,"t":"「萬軍之耶和華如此說，你要向祭司請教律法，說：","notes":[]},{"n":12,"t":"『看哪，若有人用衣服的邊兜聖肉，這衣服的邊接觸了餅，或湯，或酒，或油，或別的食物，這些是否成為聖呢？』」祭司回答說：「不。」","notes":[]},{"n":13,"t":"哈該又說：「若有人因摸屍體染了不潔淨，然後接觸任何東西，這東西就變為不潔淨嗎？」祭司回答說：「必不潔淨。」","notes":[]},{"n":14,"t":"於是哈該說：「耶和華說，在我面前這民如此，這國也是如此；他們手裏的各樣工作都是如此；他們在那裏所獻的都不潔淨。」","notes":[]},{"n":15,"t":"「現在，你們心裏要想一想，從今日起，耶和華的殿還沒有一塊石頭放在石頭上的情況。","notes":[],"heads":["耶和華應許賜福"]},{"n":16,"t":"那時你們怎麼了？有人來到二十斗的穀堆那裏，卻只得了十斗；有人來到酒池那裏要取五十桶，卻只得了二十桶。","notes":["「你們怎麼了？」是根據七十士譯本，原文是「自從你們這麼樣」。"]},{"n":17,"t":"我以焚風、霉爛、冰雹攻擊你們，和你們手上的各樣工作，你們仍不歸向我。這是耶和華說的。","notes":["「焚風」或譯「蟲害」。"]},{"n":18,"t":"你們心裏要想一想，從今日起，就是從這九月二十四日起，從立耶和華殿根基的日子起，你們心裏想一想：","notes":[]},{"n":19,"t":"倉裏還有穀種嗎？葡萄樹、無花果樹、石榴樹、橄欖樹雖沒有結果子，從今日起，我必賜福。」","notes":["「葡萄樹...果子，」七十士譯本是「葡萄樹、無花果樹、石榴樹、橄欖樹都還沒有結果子嗎？」"]},{"n":20,"t":"這月二十四日，耶和華的話再次臨到哈該，說：","notes":[],"heads":["耶和華給所羅巴伯的應許"]},{"n":21,"t":"「你要告訴猶大省長所羅巴伯說，我必震動天地，","notes":[]},{"n":22,"t":"傾覆列國的寶座，除滅列邦列國的勢力，並傾覆戰車和坐在其上的。馬和騎兵都必跌倒，各人被弟兄的刀所殺。","notes":[]},{"n":23,"t":"萬軍之耶和華說：撒拉鐵的兒子我僕人所羅巴伯啊，這是耶和華說的，到那日，我必以你為印，因我揀選了你。這是萬軍之耶和華說的。」","notes":[]}]}},"ZEC":{"1":{"heading":"耶和華呼喚子民歸向他","verses":[{"n":1,"t":"大流士王第二年八月，耶和華的話臨到易多的孫子，比利家的兒子撒迦利亞先知，說：","notes":[]},{"n":2,"t":"「耶和華曾向你們祖先大發烈怒。","notes":[]},{"n":3,"t":"你要對以色列人說，萬軍之耶和華如此說：你們要轉向我，這是萬軍之耶和華說的，我就轉向你們，這是萬軍之耶和華說的。","notes":[]},{"n":4,"t":"不要效法你們的祖先。從前的先知呼叫他們說：『萬軍之耶和華如此說，當回轉離開你們的惡道惡行。』他們卻不聽，也不順從我。這是耶和華說的。","notes":[]},{"n":5,"t":"你們的祖先在哪裏呢？那些先知能永遠存活嗎？","notes":[]},{"n":6,"t":"然而我的言語和律例，就是我所吩咐我僕人眾先知的，豈不臨到你們的祖先嗎？他們就回轉，說：萬軍之耶和華定意按我們的所作所為對待我們，他也已經照樣行了。」","notes":[]},{"n":7,"t":"大流士第二年十一月，就是細罷特月二十四日，耶和華的話臨到易多的孫子，比利家的兒子撒迦利亞先知，說：","notes":[],"heads":["馬的異象"]},{"n":8,"t":"「我夜間觀看，看哪，有一人騎著紅馬，站在窪地的番石榴樹中間。在他身後有紅色、褐色和白色的馬。」","notes":[]},{"n":9,"t":"我說：「主啊，這是甚麼意思？」與我說話的天使說：「我要指示你這是甚麼意思。」","notes":[]},{"n":10,"t":"那站在番石榴樹中間的人回答說：「這是奉耶和華差遣，在遍地巡邏的。」","notes":[]},{"n":11,"t":"他們對站在番石榴樹中間耶和華的使者說：「我們在遍地巡邏，看哪，全地都安息平靜。」","notes":[]},{"n":12,"t":"於是，耶和華的使者說：「萬軍之耶和華啊，你惱恨耶路撒冷和猶大的城鎮已經七十年了，你不施憐憫要到幾時呢？」","notes":[]},{"n":13,"t":"耶和華就用美善的話和安慰的話回答那與我說話的天使。","notes":[]},{"n":14,"t":"與我說話的天使對我說：「你要宣告，萬軍之耶和華如此說：我為耶路撒冷而妒忌，為錫安大大妒忌。","notes":[]},{"n":15,"t":"我非常惱怒那享安逸的列國，因我從前稍微惱怒，他們就越發加害。","notes":[]},{"n":16,"t":"所以耶和華如此說：現在我回到耶路撒冷，仍要施憐憫，我的殿要重建在其中，準繩必拉在耶路撒冷之上。這是萬軍之耶和華說的。","notes":[]},{"n":17,"t":"你要再宣告，萬軍之耶和華如此說：我的城鎮要再度繁榮發達。耶和華必再安慰錫安，揀選耶路撒冷。」","notes":[]},{"n":18,"t":"我舉目觀看，看哪，有四隻角。","notes":[],"heads":["角的異象"]},{"n":19,"t":"我問那與我說話的天使：「這是甚麼意思？」他對我說：「這是擊散猶大、以色列和耶路撒冷的角。」","notes":[]},{"n":20,"t":"耶和華又把四個匠人指給我看。","notes":[]},{"n":21,"t":"我問：「這些人來做甚麼呢？」他說：「那是擊散猶大的角，使人不敢抬頭；但這些匠人前來威嚇他們，打掉列國的角，因為他們舉起角來擊散猶大地。」","notes":[]}]},"2":{"heading":"丈量繩的異象","verses":[{"n":1,"t":"我舉目觀看，看哪，有一人手拿丈量的繩。","notes":[]},{"n":2,"t":"我問：「你到哪裏去？」他對我說：「要去丈量耶路撒冷，看有多寬多長。」","notes":[]},{"n":3,"t":"看哪，與我說話的天使出去，另有一位天使迎著他來，","notes":["「出去」：七十士譯本是「站著」。"]},{"n":4,"t":"對他說：「你跑去告訴這個年輕人說，耶路撒冷必有人居住，如同無城牆的鄉村，因為其中的人和牲畜很多。","notes":[]},{"n":5,"t":"耶和華說：『我要作耶路撒冷四圍火的城牆，並要作城中的榮耀。』」","notes":[]},{"n":6,"t":"耶和華說：「來，來！你們要從北方之地逃回；因我曾把你們分散到天的四方。這是耶和華說的。」","notes":["「到天的四方」：原文是「猶如天的四風」。"],"heads":["呼喚被擄者歸回"]},{"n":7,"t":"來！住巴比倫的錫安百姓啊，逃吧！","notes":["「巴比倫」：原文直譯「巴比倫女子」。"]},{"n":8,"t":"萬軍之耶和華在顯出榮耀之後，差遣我到擄掠你們的列國那裏，他如此說：「碰你們的就是碰他自己眼中的瞳人。","notes":["「他自己」：原文另譯「我」。"]},{"n":9,"t":"看哪，我要揮手攻擊他們，他們就必作自己奴僕的擄物。」你們就知道萬軍之耶和華差遣了我。","notes":[]},{"n":10,"t":"耶和華說：「錫安哪，應當歡樂歌唱，因為，看哪，我要來，要住在你中間。","notes":["「錫安」：原文直譯「錫安女子」。"]},{"n":11,"t":"在那日，必有許多國家歸附耶和華，作我的子民。我要住在你中間。」你就知道萬軍之耶和華差遣我到你那裏去。","notes":["「我要住」：原文另譯「他要住」；七十士譯本是「他們要住」。"]},{"n":12,"t":"耶和華必收回猶大，作為他聖地的產業，他必再度揀選耶路撒冷。","notes":[]},{"n":13,"t":"凡血肉之軀都當在耶和華面前靜默無聲，因為他從他的聖所奮起了。","notes":[]}]},"3":{"heading":"大祭司的異象","verses":[{"n":1,"t":"天使指給我看：約書亞大祭司站在耶和華的使者面前，撒但站在約書亞的右邊控告他。","notes":["「天使」：原文是「他」。"]},{"n":2,"t":"耶和華向撒但說：「撒但哪，耶和華責備你！揀選耶路撒冷的耶和華責備你！這不是從火中抽出來的一根柴嗎？」","notes":[]},{"n":3,"t":"約書亞穿著污穢的衣服，站在那使者面前。","notes":[]},{"n":4,"t":"使者吩咐那些侍立在他面前的說：「脫去他污穢的衣服。」又對約書亞說：「你看，我使你的罪孽離開你，要給你穿上華美的衣服。」","notes":[]},{"n":5,"t":"我說：「要將潔淨的冠冕戴在他頭上。」他們就把潔淨的冠冕戴在他頭上，給他穿上華美的衣服，耶和華的使者在旁邊站立。","notes":["「我說」：原文另譯「他說」；七十士譯本沒有「我說」。"]},{"n":6,"t":"耶和華的使者告誡約書亞說，","notes":[]},{"n":7,"t":"萬軍之耶和華如此說：「你若遵行我的道，謹守我的命令，就可以管理我的家，看守我的院宇；我也要使你在這些侍立的人中間來往。","notes":[]},{"n":8,"t":"約書亞大祭司啊，你和坐在你面前的同伴都當聽，因為他們是作預兆的：看哪，我必使我僕人大衛的苗裔長出。","notes":["「大衛的苗裔」：原文是「苗裔」。"]},{"n":9,"t":"看哪，這是我在約書亞面前所立的石頭，這一塊石頭上有七眼。看哪，我要親自雕刻這石頭，並在一日之間除掉這地的罪孽。這是萬軍之耶和華說的。","notes":[]},{"n":10,"t":"在那日，你們各人要請鄰舍坐在葡萄樹和無花果樹下。這是萬軍之耶和華說的。」","notes":[]}]},"4":{"heading":"金燈臺的異象","verses":[{"n":1,"t":"那與我說話的天使又來叫醒我，好像人睡覺時被喚醒一樣。","notes":[]},{"n":2,"t":"他問我：「你看見甚麼？」我說：「我看見了，看哪，有一個純金的燈臺，頂上有燈座，其上有七盞燈，每盞燈的上頭有七根管子；","notes":[]},{"n":3,"t":"旁邊有兩棵橄欖樹，一棵在燈座的右邊，一棵在燈座的左邊。」","notes":[]},{"n":4,"t":"我問與我說話的天使說：「主啊，這是甚麼意思？」","notes":[]},{"n":5,"t":"與我說話的天使回答，對我說：「你不知道這是甚麼意思嗎？」我說：「主啊，我不知道。」","notes":[]},{"n":6,"t":"他回答我說：「這是耶和華指示所羅巴伯的話。萬軍之耶和華說：不是倚靠勢力，不是倚靠才能，乃是倚靠我的靈方能成事。","notes":["原文沒有「方能成事」。"],"heads":["神給所羅巴伯的應許"]},{"n":7,"t":"大山哪，你算甚麼呢？在所羅巴伯面前，你必夷為平地。他安放頂上的那塊石頭，人就歡呼：『願恩惠、恩惠歸與這殿！』」","notes":[]},{"n":8,"t":"耶和華的話臨到我，說：","notes":[]},{"n":9,"t":"「所羅巴伯的手立了這殿的根基，他的手也必完成這工，你就知道萬軍之耶和華差遣我到你們這裏。","notes":[]},{"n":10,"t":"誰藐視這日的事為小呢？他們見所羅巴伯手拿石垂線就歡喜。這七盞燈是耶和華的眼睛，遍察全地。」","notes":["「七盞燈」：原文是「七」。"]},{"n":11,"t":"我問天使說：「那麼在燈臺左右的這兩棵橄欖樹是甚麼意思呢？」","notes":[]},{"n":12,"t":"我再次問他：「這兩根橄欖樹枝在兩根流出金色油的金嘴旁邊，是甚麼意思呢？」","notes":[]},{"n":13,"t":"他對我說：「你不知道這是甚麼意思嗎？」我說：「主啊，我不知道。」","notes":[]},{"n":14,"t":"他說：「這是兩位受膏者，侍立在全地之主的旁邊。」","notes":[]}]},"5":{"heading":"飛卷的異象","verses":[{"n":1,"t":"我又舉目觀看，看哪，有一飛行的書卷。","notes":[]},{"n":2,"t":"他問我：「你看見甚麼？」我回答：「我看見一飛行的書卷，長二十肘，寬十肘。」","notes":[]},{"n":3,"t":"他對我說：「這就是向全地面發出的詛咒。凡偷竊的必按書卷這面的話除滅，凡起假誓的必按書卷那面的話除滅。","notes":[]},{"n":4,"t":"萬軍之耶和華說：我要把這書卷送出去，進入偷竊者的家和指著我名起假誓者的家，停留在他家裏，連房屋帶木頭和石頭都毀滅了。」","notes":[]},{"n":5,"t":"與我說話的天使前來，對我說：「你要舉目觀看，看那出現的是甚麼。」","notes":[],"heads":["量器中婦人的異象"]},{"n":6,"t":"我問：「這是甚麼呢？」他說：「這出現的是量器。」又說：「是他們的眼目，遍行全地。」","notes":["「量器」：原文是「伊法」；下同。","「他們的眼目，遍行全地」：七十士譯本和其他古譯本是「他們在遍地的惡行」。"]},{"n":7,"t":"看哪，圓形的鉛蓋被抬起來，有一個婦人坐在量器中。","notes":[]},{"n":8,"t":"天使說：「這是罪惡。」他就把婦人推進量器裏，把鉛蓋壓在量器的口上。","notes":[]},{"n":9,"t":"於是我舉目觀看，看哪，有兩個婦人前來，她們的翅膀中有風，翅膀如同鸛鳥的翅膀。她們把量器抬起來，懸在天地之間。","notes":[]},{"n":10,"t":"我問那與我說話的天使：「她們要把量器抬到哪裏去呢？」","notes":[]},{"n":11,"t":"他對我說：「要抬到示拿地去，為它建造房屋；等預備妥當，就把它安放在自己的臺座上。」","notes":[]}]},"6":{"heading":"馬車的異象","verses":[{"n":1,"t":"我又舉目觀看，看哪，有四輛馬車從兩座山的中間出來；那兩座山是銅山。","notes":[]},{"n":2,"t":"第一輛車套著紅馬，第二輛車套著黑馬，","notes":[]},{"n":3,"t":"第三輛車套著白馬，第四輛車套著帶斑點的馬，都是強壯的。","notes":["「帶斑點...強壯的」或譯「帶斑點的灰馬」。"]},{"n":4,"t":"我就回應與我說話的天使說：「主啊，這是甚麼意思？」","notes":[]},{"n":5,"t":"天使回答，對我說：「這是天的四風，是從全地之主面前出來的。」","notes":[]},{"n":6,"t":"套著黑馬的車往北方之地去，白馬跟隨在後；有斑點的馬往南方之地去；","notes":[]},{"n":7,"t":"那些壯馬出來，急著要在地上巡邏。天使說：「你們只管在地上巡邏。」牠們就在地上巡邏。","notes":[]},{"n":8,"t":"他又呼叫我，告訴我說：「你看，往北方地去的已在北方之地使我放心。」","notes":[]},{"n":9,"t":"耶和華的話臨到我，說：","notes":[],"heads":["為約書亞加冕"]},{"n":10,"t":"「你要拿從巴比倫歸來的被擄之人黑玳、多比雅、耶大雅所獻的，當日就要進到西番雅的兒子約西亞的家裏，","notes":[]},{"n":11,"t":"拿這金銀做冠冕，戴在約撒答的兒子約書亞大祭司的頭上；","notes":[]},{"n":12,"t":"對他說，萬軍之耶和華如此說：『看哪，那名稱為大衛苗裔的，要在本處生長，並要建造耶和華的殿。","notes":[]},{"n":13,"t":"就是他，要建造耶和華的殿，他要承受尊榮，坐在位上掌王權；又有一位祭司坐在自己的位上，兩職之間籌劃和平。","notes":[]},{"n":14,"t":"這冠冕要歸希連、多比雅、耶大雅，和西番雅的兒子賢，放在耶和華的殿裏作為紀念。』」","notes":["「希連」就是「黑玳」。","「賢」就是「約西亞」。"]},{"n":15,"t":"遠方的人要來建造耶和華的殿，你們因此就知道，萬軍之耶和華差遣我到你們這裏來。你們若留意聽從耶和華－你們神的話，這事必然成就。","notes":[]}]},"7":{"heading":"譴責不誠懇的禁食","verses":[{"n":1,"t":"大流士王第四年九月，就是基斯流月初四，耶和華的話臨到撒迦利亞。","notes":[]},{"n":2,"t":"那時伯特利人已經差遣沙利色和利堅‧米勒，並他們的人，去懇求耶和華的恩，","notes":["「利堅‧米勒」：原文另譯「國王的重臣」。"]},{"n":3,"t":"問萬軍之耶和華殿中的祭司，又問先知：「我當如歷年以來所行，在五月哭泣齋戒嗎？」","notes":[]},{"n":4,"t":"萬軍之耶和華的話臨到我，說：","notes":[]},{"n":5,"t":"「你要向這地全體百姓和祭司說：『你們這七十年來，在五月、七月禁食悲哀，豈是真的向我禁食嗎？","notes":[]},{"n":6,"t":"你們吃喝，不是為自己吃，為自己喝嗎？","notes":[]},{"n":7,"t":"當耶路撒冷和四圍的城鎮有人居住，享繁榮，尼革夫和謝非拉也有人居住的時候，耶和華藉從前的先知所宣告的，你們不當聽嗎？』」","notes":["「尼革夫」是音譯，意思是「曠野乾旱的地方」，指「南方之地」。","「謝非拉」是音譯，意思是「低地」。"]},{"n":8,"t":"耶和華的話臨到撒迦利亞，說：","notes":[],"heads":["被擄的原因"]},{"n":9,"t":"「萬軍之耶和華如此說：你們要按真正的公平來審判，彼此以慈愛憐憫相待。","notes":[]},{"n":10,"t":"不可欺壓寡婦、孤兒、寄居的和困苦的人。誰都不可心裏謀害弟兄。","notes":[]},{"n":11,"t":"他們卻不留意；聳肩悖逆，耳朵發沉，不肯聽從。","notes":[]},{"n":12,"t":"他們的心堅硬如金剛石，不聽律法和萬軍之耶和華藉著他的靈差遣從前先知所說的話。因此，萬軍之耶和華大發烈怒。","notes":[]},{"n":13,"t":"萬軍之耶和華說：我曾呼喚他們，他們不聽；將來他們呼求我，我也不聽！","notes":[]},{"n":14,"t":"我必以旋風將他們吹散到素不認識的萬國中。他們離開以後，地就荒涼，無人來往經過；他們使美好之地荒涼了。」","notes":[]}]},"8":{"heading":"耶和華應許復興耶路撒冷","verses":[{"n":1,"t":"萬軍之耶和華的話臨到我，說：","notes":[]},{"n":2,"t":"「萬軍之耶和華如此說：我為錫安而妒忌，大大妒忌；我為了它妒忌而大發烈怒。","notes":[]},{"n":3,"t":"耶和華如此說：我要回到錫安，住在耶路撒冷中間。耶路撒冷必稱為忠實的城，萬軍之耶和華的山必稱為聖山。","notes":[]},{"n":4,"t":"萬軍之耶和華如此說：將來必有年老的男女坐在耶路撒冷的廣場上，各人因年紀老邁而手拿枴杖。","notes":[]},{"n":5,"t":"城裏的廣場滿有男孩女孩在玩耍。","notes":[]},{"n":6,"t":"萬軍之耶和華如此說：在那些日子，即使這事在這餘民眼中看為奇妙，難道在我眼中也看為奇妙嗎？這是萬軍之耶和華說的。","notes":[]},{"n":7,"t":"萬軍之耶和華如此說：看哪，我要從日出之地、從日落之地拯救我的子民。","notes":[]},{"n":8,"t":"我要領他們來，使他們住在耶路撒冷中間。他們要作我的子民，我要作他們的神，都憑信實和公義。","notes":[]},{"n":9,"t":"「萬軍之耶和華如此說：你們的手要堅強；這些日子，你們已聽見先知的口，在萬軍之耶和華殿的根基立定、聖殿建造的日子所說的這些話。","notes":[]},{"n":10,"t":"那些日子以前，人得不著工價，牲畜也無人雇用；且因敵人的緣故，出入不得平安；因我使人與人互相攻擊。","notes":[]},{"n":11,"t":"但如今，我對這餘民必不像先前的日子。這是萬軍之耶和華說的。","notes":[]},{"n":12,"t":"因為他們要平安撒種，葡萄樹要結果子，土地必有出產，天也必降甘露。我要使這餘民享受這一切。","notes":[]},{"n":13,"t":"猶大家和以色列家啊，你們從前在列國中怎樣成為可詛咒的；照樣，我要拯救你們，使你們得福。不要懼怕，你們的手要堅強。","notes":["「使你們得福」或譯「使你們叫人得福」。"]},{"n":14,"t":"「萬軍之耶和華如此說：你們祖先惹我發怒的時候，我怎樣定意降禍，並不改變；萬軍之耶和華說，","notes":[]},{"n":15,"t":"這些日子我也定意施恩給耶路撒冷和猶大家；你們不要懼怕。","notes":[]},{"n":16,"t":"你們所當行的是這樣：每個人要與鄰舍說誠實話，在城門口要按真正的公平來審判，使人和睦。","notes":[]},{"n":17,"t":"誰都不可心裏謀害鄰舍，也不可喜愛起假誓，因為這些事都為我所恨惡。這是耶和華說的。」","notes":[]},{"n":18,"t":"萬軍之耶和華的話臨到我，說：","notes":[]},{"n":19,"t":"「萬軍之耶和華如此說：四月的禁食、五月的禁食、七月的禁食和十月的禁食，必成為猶大家的歡喜和快樂，以及美好的節期；所以你們要喜愛誠實與和平。","notes":[]},{"n":20,"t":"「萬軍之耶和華如此說：將來還有眾百姓和許多城鎮的居民要來。","notes":[]},{"n":21,"t":"這城的居民必到那城，說：『我們快去懇求耶和華的恩，尋求萬軍之耶和華；我自己也要去。』","notes":[]},{"n":22,"t":"必有許多民族和強盛的國家來到耶路撒冷尋求萬軍之耶和華，懇求耶和華的恩。","notes":[]},{"n":23,"t":"萬軍之耶和華如此說：在那些日子，列國中說各種語言的人，必有十個人強拉住一個猶大人衣服的邊，說：『我們要與你們同去，因為我們聽見神與你們同在了。』」","notes":[]}]},"9":{"heading":"審判鄰國","verses":[{"n":1,"t":"耶和華的默示，他的話臨到哈得拉地、大馬士革－因世人和以色列各支派的眼目都向著耶和華－","notes":[]},{"n":2,"t":"和鄰近的哈馬，以及推羅和西頓。因為它極有智慧，","notes":[]},{"n":3,"t":"推羅為自己建造堅固城，堆起銀子如塵沙，純金如街上的泥土。","notes":["「堅固城」與「推羅」的希伯來話發音相近。"]},{"n":4,"t":"看哪，主必趕出它，重創它海上的勢力，它必被火吞滅。","notes":[]},{"n":5,"t":"亞實基倫看見必懼怕，迦薩看見甚痛苦，以革倫因失了盼望而蒙羞；迦薩必不再有君王，亞實基倫也不再有人居住，","notes":[]},{"n":6,"t":"混血的人要住在亞實突；我必除滅非利士人的驕傲。","notes":[]},{"n":7,"t":"我要除去他口中帶血之肉和牙齒內可憎之物。他必作餘民歸於我們的神，在猶大像族長一樣；以革倫必如耶布斯人。","notes":[]},{"n":8,"t":"我要紮營在我的家，敵軍不得任意往來，暴虐的人也不再經過，因為我親眼看顧。","notes":[]},{"n":9,"t":"錫安哪，應當大大喜樂；耶路撒冷啊，應當歡呼。看哪，你的王來到你這裏！他是公義的，並且施行拯救，謙和地騎著驢，騎著小驢，驢的駒子。","notes":["「錫安」：原文直譯「錫安女子」。","「耶路撒冷」：原文直譯「耶路撒冷女子」。"],"heads":["未來的君王"]},{"n":10,"t":"我必除滅以法蓮的戰車和耶路撒冷的戰馬；戰爭的弓也必剪除。他要向列國講和平；他的權柄必從這海管到那海，從大河管到地極。","notes":[]},{"n":11,"t":"錫安哪，我因與你立約的血，要從無水坑裏釋放你中間被囚的人。","notes":[],"heads":["神子民的復興"]},{"n":12,"t":"被囚而有指望的人哪，要轉回堡壘；我今日宣告，我必加倍補償你。","notes":[]},{"n":13,"t":"我為自己把猶大彎緊，我使以法蓮如滿弓。錫安哪，我要喚起你的兒女，希臘啊，我要攻擊你的兒女，使你如勇士的刀。","notes":["「希臘」：原文是「雅完」。"]},{"n":14,"t":"耶和華要顯現在他們身上，他的箭要射出如閃電。主耶和華必吹角，乘南方的旋風而行。","notes":[]},{"n":15,"t":"萬軍之耶和華必保護他們；他們要吞滅，要踐踏彈弓的石頭；他們吶喊，狂飲如喝酒，如盛滿的碗，又如壇的四角。","notes":["「他們要吞滅...石頭」或譯「彈弓的石頭要吞滅和踐踏」。","「他們吶喊，狂飲」：七十士譯本的一些抄本是「他們飲血」。"]},{"n":16,"t":"當那日，耶和華－他們的神必看他的百姓如羊群，拯救他們；因為他們如冠冕上的寶石，在他的地上如旗幟高舉。","notes":["「如旗幟高舉」或譯「發出光輝」。"]},{"n":17,"t":"他是何等善！他是何其美！五穀使少男強壯，新酒使少女健美。","notes":[]}]},"10":{"heading":"耶和華應許解救","verses":[{"n":1,"t":"春雨的季節，你們要向耶和華求雨。耶和華發出雷電，為眾人降下大雨，把田園的菜蔬賜給人。","notes":[]},{"n":2,"t":"因為家中神像所言的是虛空，占卜者所見的是虛假，他們講說假夢，徒然安慰人。所以眾人如羊流離，因無牧人就受欺壓。","notes":[]},{"n":3,"t":"我的怒氣向牧人發作，我必懲罰那為首的；萬軍之耶和華眷顧他的羊群，就是猶大家，必使他們如戰場上的駿馬。","notes":["「為首的」或譯「公山羊」。"]},{"n":4,"t":"房角石從他而出，橛子從他而出，戰爭的弓也從他而出，每一個掌權的都從他而出。","notes":[]},{"n":5,"t":"他們必如戰場上的勇士，踐踏仇敵如街上的泥土。他們必爭戰，因為耶和華與他們同在，他們必使騎馬的羞愧。","notes":[]},{"n":6,"t":"我要堅固猶大家，拯救約瑟家，我要領他們歸回，因我憐憫他們，他們必像我未曾棄絕他們一樣；都因我是耶和華－他們的神，我必應允他們。","notes":[]},{"n":7,"t":"以法蓮人必如勇士，他們心中暢快如同喝酒；他們的兒女看見就歡喜，他們的心必因耶和華喜樂。","notes":[]},{"n":8,"t":"我要呼叫，聚集他們，因我已經救贖他們。他們的人數必增添，如從前增添一樣。","notes":[]},{"n":9,"t":"我要將他們分散在列國中，他們必在遠方記得我；他們與兒女都必存活，他們要歸回。","notes":[]},{"n":10,"t":"我必使他們從埃及地歸回，從亞述召集他們，領他們到基列地和黎巴嫩；這些還不夠他們居住。","notes":[]},{"n":11,"t":"耶和華必經過苦海，擊打海浪。尼羅河的深處全都枯乾，亞述的驕傲必降卑，埃及的權杖必除去。","notes":["「耶和華」：原文是「他」；七十士譯本是「他們」。"]},{"n":12,"t":"我要使他們倚靠耶和華，得以堅固，他們必奉他的名而行；這是耶和華說的。","notes":["「他們必奉他的名而行」：七十士譯本是「他們必榮耀他的名」。"]}]},"11":{"heading":"暴君的沒落","verses":[{"n":1,"t":"黎巴嫩哪，敞開你的門，任火吞滅你的香柏樹。","notes":[]},{"n":2,"t":"哀號吧，松樹！因為香柏樹傾倒了，高大的樹毀壞了。哀號吧，巴珊的橡樹！因為茂盛的樹林倒下來了。","notes":[]},{"n":3,"t":"聽啊，有牧人在哀號，因他們的榮華敗落了；聽啊，有少壯獅子咆哮，因約旦河旁的叢林荒廢了。","notes":[]},{"n":4,"t":"耶和華－我的神如此說：「你要牧養這群將宰的羊。","notes":[],"heads":["兩個牧人"]},{"n":5,"t":"買羊的宰了他們，卻不認為自己有罪；賣他們的也說：『耶和華是應當稱頌的，因我富足了。』牧養他們的並不憐憫他們。","notes":[]},{"n":6,"t":"我不再憐憫這地的居民。看哪，我要將這些人交在各人的鄰舍和君王手中；他們必毀滅這地，我卻不救任何一個脫離他們的手。這是耶和華說的。」","notes":[]},{"n":7,"t":"於是，我牧養這群將宰的羊，就是羊群中最困苦的；我拿著兩根杖，一根我稱為「恩惠」，一根稱為「聯合」。這樣，我就牧養這群羊。","notes":["「我牧養...最困苦的」：原文另譯「我為了那些買賣羊群的人牧養這群將宰的羊」。","「恩惠」或譯「榮美」；下同。"]},{"n":8,"t":"一個月之內，我廢除了三個牧人，因為我的心厭煩他們，他們的心也憎惡我。","notes":[]},{"n":9,"t":"我就說：「我不牧養你們。要死的，由他死；滅亡的，由他滅亡；剩餘的，由他們彼此吞食。」","notes":[]},{"n":10,"t":"我拿起那根稱為「恩惠」的杖，折斷它，表明我廢棄與萬民所立的約。","notes":[]},{"n":11,"t":"當日約就廢了。因此，那些羊群中最困苦的，看著我，就知道這真是耶和華的話。","notes":["「那些羊群中最困苦的」：原文另譯「那些買賣羊群的人」。"]},{"n":12,"t":"我對他們說：「你們若看為美，就給我工價。不然，就罷了！」於是他們秤了三十塊銀錢作為我的工價。","notes":[]},{"n":13,"t":"耶和華對我說：「把它丟給窯戶。那是他們對我所估定的好價錢！」我就取這三十塊銀錢，在耶和華的殿中將它丟給窯戶。","notes":[]},{"n":14,"t":"我又折斷第二根杖，就是稱為「聯合」的那根杖，表明我廢棄猶大與以色列弟兄間的情誼。","notes":[]},{"n":15,"t":"耶和華對我說：「你再把愚昧牧人所用的器具拿來，","notes":[]},{"n":16,"t":"因為，看哪，我要在這地立一個牧人；他不看顧將亡的，不尋找分散的，不醫治受傷的，也不牧養強壯的；卻要吞吃肥羊的肉，撕裂牠們的蹄。","notes":[]},{"n":17,"t":"禍哉！無用的牧人丟棄羊群，刀必臨到他的膀臂和右眼上；他的膀臂必全然枯乾，他的右眼也必昏暗失明。」","notes":[]}]},"12":{"heading":"耶路撒冷將蒙拯救","verses":[{"n":1,"t":"耶和華的默示，他的話論到以色列。鋪張諸天、建立地基、造人裏面之靈的耶和華說：","notes":[]},{"n":2,"t":"「看哪，我要使耶路撒冷成為令四圍列國百姓昏醉的杯；耶路撒冷被圍困，猶大也一樣受困。","notes":["「耶路撒冷被圍困...受困」：有古譯本是「猶大也去圍困耶路撒冷」。"]},{"n":3,"t":"在那日，我要使耶路撒冷成為萬民的一塊沉重石頭，凡舉起它的必受重傷；地上的萬國都聚集攻擊它。","notes":[]},{"n":4,"t":"到那日，我必令一切的馬匹驚惶，使騎馬的癲狂。我必張開眼睛看顧猶大家，卻使列國一切的馬匹瞎眼。這是耶和華說的。","notes":[]},{"n":5,"t":"猶大的族長心裏要說：『耶路撒冷的居民因倚靠萬軍之耶和華－他們的神，就成為我的力量。』","notes":["「就成為我的力量」：原文另譯「就有力量」。"]},{"n":6,"t":"「那日，我必使猶大的族長如柴堆中的火盆，又如禾捆裏的火把；他們必左右吞滅四圍列國的百姓。耶路撒冷卻仍屹立在本處，仍在耶路撒冷！","notes":[]},{"n":7,"t":"「耶和華要先拯救猶大的帳棚，免得大衛家的榮耀和耶路撒冷居民的榮耀勝過猶大。","notes":[]},{"n":8,"t":"那日，耶和華必保護耶路撒冷的居民。他們中間軟弱的在那日必如大衛；大衛家必如神，如行在他們前面的耶和華的使者。","notes":[]},{"n":9,"t":"那日，我必定意滅絕前來攻擊耶路撒冷的萬國。」","notes":[]},{"n":10,"t":"「我要將那施恩與懇求的靈，澆灌大衛家和耶路撒冷的居民。他們必仰望我，就是他們所扎的那位。他們必為他悲傷，如喪獨子，又為他哀哭，如喪長子。","notes":[],"heads":["為所刺的哀傷"]},{"n":11,"t":"那日，在耶路撒冷必有大大的哀號，如米吉多平原上哈達‧臨門的哀號。","notes":[]},{"n":12,"t":"這地必哀哭：一家一家地哭，大衛家的家族聚在一處，他們的婦女聚在一處；拿單家的家族聚在一處，他們的婦女聚在一處。","notes":[]},{"n":13,"t":"利未家的家族聚在一處，他們的婦女聚在一處；示每家的家族聚在一處，他們的婦女聚在一處。","notes":[]},{"n":14,"t":"其餘的各家，每一家的家族聚在一處，他們的婦女聚在一處。」","notes":[]}]},"13":{"heading":"牧人被殺","verses":[{"n":1,"t":"「在那日，因罪惡與污穢的緣故，必有一泉源為大衛家和耶路撒冷的居民而開。」","notes":[]},{"n":2,"t":"萬軍之耶和華說：「在那日，我要從地上除滅偶像的名，使它不再被記得；我也必使這地不再有先知，不再有污穢的靈。","notes":[]},{"n":3,"t":"若還有人說預言，生他的父母必對他說：『你不得存活，因為你假借耶和華的名說謊話。』生他的父母在他說預言時，要將他刺死。","notes":[]},{"n":4,"t":"那日，凡作先知說預言的必因所論的異象羞愧，不再穿毛皮外袍哄騙人。","notes":[]},{"n":5,"t":"他要說：『我不是先知，我是耕地的；我從幼年就作人的奴僕。』","notes":[]},{"n":6,"t":"有人對他說：『你兩手臂間是甚麼傷呢？』他說：『這是我在親友家中所受的傷。』」","notes":[]},{"n":7,"t":"萬軍之耶和華說：刀劍哪，興起攻擊我的牧人，攻擊我的同伴吧！要擊打牧人，羊就分散了；我必反手攻擊那微小的。","notes":[]},{"n":8,"t":"這全地的人，三分之二將被剪除而死，三分之一仍必存留。這是耶和華說的。","notes":[]},{"n":9,"t":"我要使這三分之一經過火，熬煉他們，如熬煉銀子；試煉他們，如試煉金子。他們要求告我的名，我必應允他們。我說：「這是我的子民。」他們要說：「耶和華是我的神。」","notes":[]}]},"14":{"heading":"耶路撒冷和列國","verses":[{"n":1,"t":"看哪，耶和華的日子臨近了，你的財物必被搶掠，在你中間被瓜分。","notes":[]},{"n":2,"t":"我要招聚萬國與耶路撒冷爭戰；城必被攻取，房屋被搶奪，婦女被玷污，城中的一半被擄去；但其餘的百姓不會從城中被剪除。","notes":[]},{"n":3,"t":"那時，耶和華要出去與那些國家打仗，如同從前戰爭的日子打仗一樣。","notes":[]},{"n":4,"t":"那日，他的腳必站在橄欖山上，這山面向耶路撒冷的東邊。橄欖山必從中間裂開，自東至西成為極大的谷；山的一半向北挪移，一半向南挪移。","notes":[]},{"n":5,"t":"你們要從我的山谷中逃跑，因為山谷必延到亞薩。你們要逃跑，如在猶大王烏西雅年間逃避大地震一樣。耶和華－我的神必降臨，所有的聖者與你同來。","notes":["「你們要從...一樣」：七十士譯本是「我的山谷要被堵塞，因為山谷必延到亞薩，被堵塞，如在猶大王烏西雅年間大地震時堵塞一樣」。","「與你」：七十士譯本和其他古譯本是「與他」。"]},{"n":6,"t":"在那日，必沒有光，不會放晴，只有烏雲。","notes":["「不會放晴，只有烏雲」：原文另譯「榮光被凍結了」；七十士譯本是「只有寒冷與冰霜」。"]},{"n":7,"t":"耶和華所知的那一日，沒有白天，沒有黑夜，到了晚上仍有亮光。","notes":[]},{"n":8,"t":"在那日，必有活水從耶路撒冷出來，一半往東海流，一半往西海流；冬夏都是如此。","notes":[]},{"n":9,"t":"耶和華要作全地的王。那日，耶和華必為獨一無二，他的名也是獨一無二。","notes":[]},{"n":10,"t":"從迦巴直到耶路撒冷南方的臨門，全地要變為曠野。耶路撒冷要矗立於本處，從便雅憫門到舊門，又到角門，並從哈楠業樓，直到王的酒池。","notes":[]},{"n":11,"t":"人要住在其中，不再有詛咒；耶路撒冷必安然屹立。","notes":[]},{"n":12,"t":"這是耶和華所降的災殃，要攻擊那些與耶路撒冷作戰的萬民；他們兩腳站立時，肉要潰爛，眼在眶中潰爛，舌在口中也潰爛。","notes":[]},{"n":13,"t":"那日，耶和華必使他們大大混亂。他們彼此用手揪住，用手互相攻擊。","notes":[]},{"n":14,"t":"猶大也要在耶路撒冷打仗。那時四圍各國的財物，就是許許多多的金銀和衣服，必被收聚。","notes":["「猶大...打仗」或譯「甚至猶大也要攻打耶路撒冷」。"]},{"n":15,"t":"馬匹、騾子、駱駝、驢和營中一切的牲畜所遭的災殃與那災殃一樣。","notes":[]},{"n":16,"t":"上來攻擊耶路撒冷的列國中所有剩下的人，要年年上來敬拜大君王－萬軍之耶和華，並守住棚節。","notes":[]},{"n":17,"t":"地上萬族中，凡不上耶路撒冷敬拜大君王－萬軍之耶和華的，雨必不降在他們的地上。","notes":[]},{"n":18,"t":"埃及族若不上來，雨必不降在他們的地上；凡不上來守住棚節的列國，耶和華必用這災攻擊他們。","notes":[]},{"n":19,"t":"這就是埃及的懲罰和那些不上來守住棚節之列國的懲罰。","notes":[]},{"n":20,"t":"在那日，馬的鈴鐺上要刻上「歸耶和華為聖」。耶和華殿內的鍋必如祭壇前的碗一樣。","notes":[]},{"n":21,"t":"耶路撒冷和猶大一切的鍋都必歸萬軍之耶和華為聖。凡獻祭的都必來取這鍋，在其中煮肉。當那日，在萬軍之耶和華的殿中必不再有做買賣的人。","notes":["「做買賣的人」或譯「迦南人」。"]}]}},"MAL":{"1":{"heading":"耶和華愛以色列","verses":[{"n":1,"t":"耶和華的話，藉瑪拉基傳給以色列的默示。","notes":[]},{"n":2,"t":"耶和華說：「我曾愛你們。」你們卻說：「你在何事上愛我們呢？」耶和華說：「以掃不是雅各的哥哥嗎？我卻愛雅各，","notes":[]},{"n":3,"t":"惡以掃，使他的山嶺荒涼，把他的地業交給曠野的野狗。」","notes":[]},{"n":4,"t":"以東若說：「我們雖被毀壞，卻要重建荒廢之處。」萬軍之耶和華如此說：「任他們建造，我必拆毀；人必稱他們為『邪惡之境』，為『耶和華永遠惱怒之民』。」","notes":[]},{"n":5,"t":"你們必親眼看見，你們要說：「耶和華在以色列疆界之外必尊為大！」","notes":[]},{"n":6,"t":"萬軍之耶和華對你們說：「兒子孝敬父親，僕人敬畏主人；我既為父親，孝敬我的在哪裏呢？我既為主人，敬畏我的在哪裏呢？你們這些藐視我名的祭司啊！」你們卻說：「我們在何事上藐視你的名呢？」","notes":[],"heads":["斥責祭司"]},{"n":7,"t":"「你們將不潔淨的食物獻在我的祭壇上，卻說：『我們在何事上使你不潔淨呢？』你們說，耶和華的供桌是可藐視的。","notes":[]},{"n":8,"t":"你們將瞎眼的獻為祭物，這不算為惡嗎？將瘸腿的、有病的獻上，這不算為惡嗎？那麼，請把這些獻給你的省長，他豈會悅納你，豈會抬舉你呢？這是萬軍之耶和華說的。」","notes":["「你」：七十士譯本是「它」。"]},{"n":9,"t":"現在我勸你們要懇求神，好讓他施恩給我們。這事既出於你們的手，他豈會抬舉你們任何人呢？這是萬軍之耶和華說的。","notes":[]},{"n":10,"t":"萬軍之耶和華說：「甚願你們中間有人把殿的門關上，免得你們徒然在我壇上燒火。我不喜歡你們，也不從你們手中悅納供物。」","notes":["「殿的門」：原文是「門」。"]},{"n":11,"t":"萬軍之耶和華說：「從日出之地到日落之處，我的名在列國中必尊為大。在各處，人必奉我的名燒香，獻潔淨的供物，因為我的名在列國中必尊為大。","notes":[]},{"n":12,"t":"你們卻褻瀆我的名，說：『主的供桌是不潔淨的，供桌上的果子和食物是可藐視的。』","notes":[]},{"n":13,"t":"你們又說：『看哪，這些事何等煩瑣！』並嗤之以鼻。這是萬軍之耶和華說的。你們把搶來的、瘸腿的、有病的拿來獻上為祭，我豈能從你們手中悅納它呢？這是耶和華說的。","notes":["「嗤之以鼻」：原文另譯「瞧不起我」。"]},{"n":14,"t":"行詭詐的人是可詛咒的！他的群畜中雖有公羊，他許了願，卻將有殘疾的獻給主。因我是大君王，我的名在列國中是可畏的。這是萬軍之耶和華說的。」","notes":[]}]},"2":{"heading":"百姓對神不忠","verses":[{"n":1,"t":"現在，眾祭司啊，這誡命是給你們的。","notes":[]},{"n":2,"t":"萬軍之耶和華說：「你們若不聽，若不放在心上，將榮耀歸給我的名，我就使詛咒臨到你們，使你們的福分變為詛咒；其實我已經詛咒了你們的福分，因你們不把誡命放在心上。","notes":[]},{"n":3,"t":"看哪，我要斥責你們的後裔，把糞抹在你們臉上，就是你們祭牲的糞。人要把你們和糞一起抬出去，","notes":["「祭牲」：原文是「節期」。"]},{"n":4,"t":"你們就知道我頒這誡命給你們，使我與利未所立的約可以常存。這是萬軍之耶和華說的。","notes":[]},{"n":5,"t":"我曾與他立生命和平安的約。我將這兩樣賜給他，使他存敬畏的心；他就敬畏我，懼怕我的名。","notes":[]},{"n":6,"t":"真實的訓誨在他口中，他的嘴唇中沒有不義。他以平安和正直與我同行，使許多人回轉離開罪孽。","notes":[]},{"n":7,"t":"祭司的嘴唇當守護知識，人也當從他口中尋求訓誨，因為他是萬軍之耶和華的使者。","notes":[]},{"n":8,"t":"你們卻偏離正道，使許多人在這訓誨上絆跌。你們破壞了我與利未人所立的約。這是萬軍之耶和華說的。","notes":[]},{"n":9,"t":"所以我使你們被眾百姓藐視，看為卑賤；因你們不遵守我的道，在律法上看人的情面。」","notes":["「在律法上看人的情面」或譯「你們的訓誨沒有使人得福」。"]},{"n":10,"t":"我們豈不都有一位父嗎？豈不是一位神創造了我們嗎？為何互相行詭詐，褻瀆了神與我們列祖所立的約呢？","notes":[]},{"n":11,"t":"猶大行事詭詐，在以色列和耶路撒冷中行了可憎的事；因為猶大褻瀆耶和華所喜愛的聖殿，娶外邦神明的女子為妻。","notes":[]},{"n":12,"t":"凡做這事的，無論是清醒的或回應的，即使獻供物給萬軍之耶和華，耶和華也要將他從雅各的帳棚中剪除。","notes":["「清醒的」或譯「看守的」。"]},{"n":13,"t":"你們又再做這樣的事，使哭泣和嘆息的眼淚遮蓋耶和華的祭壇，以致耶和華不再理會那供物，也不喜歡從你們的手中收納。","notes":[]},{"n":14,"t":"你們還說：「這是為甚麼呢？」因為耶和華在你和你年輕時所娶的妻之間作證。她雖是你的配偶，你誓約的妻，你卻背棄她。","notes":["「誓約」與「配偶」的希伯來話發音相近。"]},{"n":15,"t":"一個人如果還剩下一點靈性，他不會這麼做。這人在尋找甚麼呢？神的後裔！當謹守你們的靈性，誰也不可背棄年輕時所娶的妻。","notes":["「一個人...後裔！」或譯「神有靈的餘力，不是只能單造一人。為何只造一人呢？乃是願人得神的子孫。」"]},{"n":16,"t":"耶和華－以色列的神說：「我恨惡休妻的事和衣服外面披上暴力的人。所以當謹守你們的心，不可行詭詐。這是萬軍之耶和華說的。」","notes":[]},{"n":17,"t":"你們用言語使耶和華厭煩，卻說：「我們在何事上使他厭煩呢？」因為你們說：「凡行惡的，耶和華看為善，並且喜愛他們；」又說：「公平的神在哪裏呢？」","notes":[],"heads":["審判之日已近"]}]},"3":{"heading":"十一奉獻","verses":[{"n":1,"t":"萬軍之耶和華說：「看哪，我要差遣我的使者在我前面預備道路。你們所尋求的主必忽然來到他的殿；立約的使者，就是你們所仰慕的，看哪，快要來到。」","notes":[]},{"n":2,"t":"他來的日子，誰能當得起呢？他顯現的時候，誰能立得住呢？因為他如煉金匠的火，如漂洗者的鹼。","notes":[]},{"n":3,"t":"他必坐下如煉淨銀子的人，必潔淨利未人，熬煉他們像金銀一樣；他們就憑公義獻供物給耶和華。","notes":[]},{"n":4,"t":"那時，猶大和耶路撒冷所獻的供物必蒙耶和華悅納，彷彿古時之日、上古之年。","notes":[]},{"n":5,"t":"萬軍之耶和華說：「我必臨近你們，施行審判。我必速速作見證，警戒那些行邪術的、犯姦淫的、起假誓的、剝削雇工工錢的、欺壓孤兒寡婦的、屈枉寄居者的和不敬畏我的人。」","notes":[]},{"n":6,"t":"「我－耶和華是不改變的；所以，雅各的子孫啊，你們不致滅亡。","notes":[]},{"n":7,"t":"從你們祖先的日子以來，你們就偏離我的律例而不遵守。現在你們要轉向我，我就轉向你們。這是萬軍之耶和華說的。你們卻說：『我們如何轉向呢？』","notes":[]},{"n":8,"t":"人豈可搶奪神呢？你們竟搶奪我！你們卻說：『我們在何事上搶奪你呢？』其實就是在你們當納的十分之一奉獻和當獻的供物上。","notes":[]},{"n":9,"t":"因你們全國上下都搶奪我的供物，詛咒就臨到你們身上。","notes":[]},{"n":10,"t":"你們要將當納的十分之一全然送入倉庫，使我家有糧，以此試試我，是否為你們敞開天上的窗戶，傾福與你們，甚至無處可容。這是萬軍之耶和華說的。","notes":[]},{"n":11,"t":"我必為你們斥責蝗蟲，不容牠毀壞你們的土產。你們田間的葡萄樹，果實未熟以先也不會掉落。這是萬軍之耶和華說的。","notes":["「蝗蟲」：原文是「吞噬者」。"]},{"n":12,"t":"萬國必稱你們為有福的，因你們必成為喜樂之地。這是萬軍之耶和華說的。」","notes":[]},{"n":13,"t":"耶和華說：「你們用話頂撞我。」你們卻說：「我們說了甚麼話頂撞你呢？」","notes":[],"heads":["神應許施憐憫"]},{"n":14,"t":"你們說：「事奉神是枉然，我們遵守神所吩咐的，在萬軍之耶和華面前哀痛而行，有甚麼益處呢？","notes":[]},{"n":15,"t":"現在，我們稱狂傲的人為有福，並且行惡的人得以建立；他們雖然試探神，卻得以逃脫。」","notes":[]},{"n":16,"t":"那時，敬畏耶和華的人彼此談論，耶和華側耳而聽，且有紀念冊在他面前，記錄那敬畏耶和華、思念他名的人。","notes":[]},{"n":17,"t":"萬軍之耶和華說：「在我所定的日子，他們必屬我，是我寶貴的產業。我必憐憫他們，如同人憐憫那服侍他的兒子。","notes":[]},{"n":18,"t":"那時你們必再一次看出義人和惡人，事奉神和不事奉神的人有何差別。」","notes":["「再一次」：七十士譯本是「歸回」。"]}]},"4":{"heading":"耶和華的日子臨近","verses":[{"n":1,"t":"萬軍之耶和華說：「看哪，那日臨近，勢如燒著的火爐，凡狂傲的和行惡的都如碎稭，在那日被燒盡，根與枝條無一存留。","notes":[]},{"n":2,"t":"但是，對你們敬畏我名的人，必有公義的太陽出現，其光線有醫治的能力。你們必出來跳躍如圈裏的牛犢。","notes":["「光線」﹕原文是「翅膀」。"]},{"n":3,"t":"你們必踐踏惡人；在我所定的日子，他們必成為你們腳掌下的灰塵。這是萬軍之耶和華說的。","notes":[]},{"n":4,"t":"「你們當記念我僕人摩西的律法，就是我在何烈山為以色列眾人所吩咐他的律例典章。","notes":[]},{"n":5,"t":"「看哪，耶和華大而可畏之日未到以前，我要差遣以利亞先知到你們那裏去。","notes":[]},{"n":6,"t":"他必使父親的心轉向兒女，兒女的心轉向父親，免得我來詛咒這地。」","notes":[]}]}},"MAT":{"1":{"heading":"耶穌基督的家譜","verses":[{"n":1,"t":"亞伯拉罕的後裔、大衛的子孫耶穌基督的家譜：","notes":["「後裔，子孫」：原文直譯「兒子」。"]},{"n":2,"t":"亞伯拉罕生以撒，以撒生雅各，雅各生猶大和他的兄弟，","notes":[]},{"n":3,"t":"猶大從她瑪氏生法勒斯和謝拉，法勒斯生希斯崙，希斯崙生亞蘭，","notes":[]},{"n":4,"t":"亞蘭生亞米拿達，亞米拿達生拿順，拿順生撒門，","notes":[]},{"n":5,"t":"撒門從喇合氏生波阿斯，波阿斯從路得氏生俄備得，俄備得生耶西，","notes":[]},{"n":6,"t":"耶西生大衛王。大衛從烏利亞的妻子生所羅門，","notes":[]},{"n":7,"t":"所羅門生羅波安，羅波安生亞比雅，亞比雅生亞撒，","notes":[]},{"n":8,"t":"亞撒生約沙法，約沙法生約蘭，約蘭生烏西雅，","notes":[]},{"n":9,"t":"烏西雅生約坦，約坦生亞哈斯，亞哈斯生希西家，","notes":[]},{"n":10,"t":"希西家生瑪拿西，瑪拿西生亞們，亞們生約西亞，","notes":[]},{"n":11,"t":"百姓被遷到巴比倫的時候，約西亞生耶哥尼雅和他的兄弟。","notes":[]},{"n":12,"t":"遷到巴比倫之後，耶哥尼雅生撒拉鐵，撒拉鐵生所羅巴伯，","notes":[]},{"n":13,"t":"所羅巴伯生亞比玉，亞比玉生以利亞敬，以利亞敬生亞所，","notes":[]},{"n":14,"t":"亞所生撒督，撒督生亞金，亞金生以律，","notes":[]},{"n":15,"t":"以律生以利亞撒，以利亞撒生馬但，馬但生雅各，","notes":[]},{"n":16,"t":"雅各生約瑟，就是馬利亞的丈夫；那稱為基督的耶穌是從馬利亞生的。","notes":[]},{"n":17,"t":"這樣，從亞伯拉罕到大衛共有十四代，從大衛到遷至巴比倫的時候也有十四代，從遷至巴比倫的時候到基督又有十四代。","notes":[]},{"n":18,"t":"耶穌基督降生的事記在下面：他母親馬利亞已經許配給約瑟，還沒有迎娶，馬利亞就從聖靈懷了孕。","notes":[],"heads":["耶穌基督降生"]},{"n":19,"t":"她丈夫約瑟是個義人，不願意當眾羞辱她，想要暗地裏把她休了。","notes":[]},{"n":20,"t":"正考慮這些事的時候，忽然主的使者在約瑟夢中向他顯現，說：「大衛的子孫約瑟，不要怕，把你的妻子馬利亞娶過來，因她所懷的孕是從聖靈來的。","notes":[]},{"n":21,"t":"她將要生一個兒子，你要給他起名叫耶穌，因他要將自己的百姓從罪惡裏救出來。」","notes":[]},{"n":22,"t":"這整件事的發生，是要應驗主藉先知所說的話：","notes":[]},{"n":23,"t":"「必有童女懷孕生子；人要稱他的名為以馬內利。」（以馬內利翻出來就是「神與我們同在」。）","notes":[]},{"n":24,"t":"約瑟醒來，就遵照主的使者的吩咐把妻子娶過來；","notes":[]},{"n":25,"t":"但是沒有和她同房，直到她生了兒子，就給他起名叫耶穌。","notes":["「兒子」：有古卷是「頭胎的兒子」。"]}]},"2":{"heading":"博學之士朝拜","verses":[{"n":1,"t":"在希律作王的時候，耶穌生在猶太的伯利恆。有幾個博學之士從東方來到耶路撒冷，說：","notes":["「博學之士」或譯「星象家」；7、16節同。"]},{"n":2,"t":"「那生下來作猶太人之王的在哪裏？我們在東方看見他的星，特來拜他。」","notes":[]},{"n":3,"t":"希律王聽見了，就心裏不安；耶路撒冷全城的人也都不安。","notes":[]},{"n":4,"t":"他就召集了祭司長和民間的文士，問他們：「基督該生在哪裏？」","notes":[]},{"n":5,"t":"他們說：「在猶太的伯利恆。因為有先知記著：","notes":[]},{"n":6,"t":"『猶大地的伯利恆啊，你在猶大諸城中並不是最小的；因為將來有一位統治者要從你那裏出來，牧養我以色列民。』」","notes":[]},{"n":7,"t":"於是，希律暗地裏召了博學之士來，查問那星是甚麼時候出現的，","notes":[]},{"n":8,"t":"就派他們往伯利恆去，說：「你們去仔細尋訪那小孩子，找到了就來報信，我也好去拜他。」","notes":[]},{"n":9,"t":"他們聽了王的話就去了。忽然，在東方所看到的那顆星在前面引領他們，一直行到小孩子所在地方的上方就停住了。","notes":[]},{"n":10,"t":"他們看見那星，就非常歡喜；","notes":[]},{"n":11,"t":"進了房子，看見小孩子和他母親馬利亞，就俯伏拜那小孩子，揭開寶盒，拿出黃金、乳香、沒藥，作為禮物獻給他。","notes":[]},{"n":12,"t":"因為在夢中得到主的指示，不要回去見希律，他們就從別的路回自己的家鄉去了。","notes":[]},{"n":13,"t":"他們走後，忽然主的使者在約瑟夢中向他顯現，說：「起來！帶著小孩子和他母親逃往埃及，住在那裏，等我的指示；因為希律要搜尋那小孩子來殺害他。」","notes":[],"heads":["逃往埃及"]},{"n":14,"t":"約瑟就起來，連夜帶著小孩子和他母親往埃及去，","notes":[]},{"n":15,"t":"住在那裏，直到希律死了。這是要應驗主藉先知所說的話：「我從埃及召我的兒子出來。」","notes":[]},{"n":16,"t":"希律見自己被博學之士愚弄，極其憤怒，差人將伯利恆城裏和四境所有的男孩，根據他向博學之士仔細查問到的時間，凡兩歲以內的，都殺盡了。","notes":[],"heads":["屠殺男孩"]},{"n":17,"t":"這就應驗了耶利米先知所說的話：","notes":[]},{"n":18,"t":"「在拉瑪聽見號咷大哭的聲音，是拉結哭她兒女；她不肯受安慰，因為他們都不在了。」","notes":[]},{"n":19,"t":"希律死了以後，在埃及，忽然主的使者在約瑟夢中向他顯現，","notes":[],"heads":["從埃及回來"]},{"n":20,"t":"說：「起來，帶著小孩子和他母親回以色列地去！因為要殺害這小孩子的人已經死了。」","notes":[]},{"n":21,"t":"約瑟就起來，帶著小孩子和他母親進入以色列地去。","notes":[]},{"n":22,"t":"但是他因聽見亞基老繼承他父親希律作了猶太王，怕到那裏去；又在夢中得到主的指示，就往加利利境內去了。","notes":[]},{"n":23,"t":"他們到了一座城，名叫拿撒勒，就住在那裏。這是要應驗先知所說的話：「他將稱為拿撒勒人。」","notes":[]}]},"3":{"heading":"施洗約翰傳道","verses":[{"n":1,"t":"在那些日子，施洗的約翰出來，在猶太的曠野宣講：","notes":[]},{"n":2,"t":"「你們要悔改！因為天國近了。」","notes":[]},{"n":3,"t":"這人就是以賽亞先知所說的：「在曠野有聲音呼喊著：預備主的道，修直他的路。」","notes":[]},{"n":4,"t":"這約翰身穿駱駝毛的衣服，腰束皮帶，吃的是蝗蟲和野蜜。","notes":[]},{"n":5,"t":"那時，耶路撒冷、全猶太和全約旦河地區的人，都到約翰那裏去，","notes":[]},{"n":6,"t":"承認他們的罪，在約旦河裏受他的洗。","notes":[]},{"n":7,"t":"約翰看見許多法利賽人和撒都該人也來受洗，就對他們說：「毒蛇的孽種啊，誰指示你們逃避那將要來的憤怒呢？","notes":[]},{"n":8,"t":"你們要結出果子來，和悔改的心相稱。","notes":[]},{"n":9,"t":"不要自己心裏說：『我們有亞伯拉罕為祖宗。』我告訴你們，神能從這些石頭中給亞伯拉罕興起子孫來。","notes":[]},{"n":10,"t":"現在斧子已經放在樹根上，凡不結好果子的樹就砍下來，丟在火裏。","notes":[]},{"n":11,"t":"我是用水給你們施洗，叫你們悔改；但那在我以後來的，能力比我更大，我就是給他提鞋子也不配，他要用聖靈與火給你們施洗。","notes":[]},{"n":12,"t":"他手裏拿著簸箕，要揚淨他的穀物，把麥子收在倉裏，把糠用不滅的火燒盡。」","notes":[]},{"n":13,"t":"當時，耶穌從加利利來到約旦河，到了約翰那裏，請約翰為他施洗。","notes":[],"heads":["耶穌受洗"]},{"n":14,"t":"約翰想要阻止他，說：「我應該受你的洗，你怎麼到我這裏來呢？」","notes":[]},{"n":15,"t":"耶穌回答他：「暫且這樣做吧，因為我們理當這樣履行全部的義。」於是約翰就依了他。","notes":["「義」或譯「禮」。"]},{"n":16,"t":"耶穌受了洗，隨即從水裏上來。天忽然為他開了，他看見神的靈降下，彷彿鴿子落在他身上。","notes":["有古卷沒有「為他」。"]},{"n":17,"t":"這時，天上有聲音說：「這是我的愛子，我所喜愛的。」","notes":[]}]},"4":{"heading":"耶穌受試探","verses":[{"n":1,"t":"當時，耶穌被聖靈引到曠野，受魔鬼的試探。","notes":[]},{"n":2,"t":"他禁食四十晝夜，後來就餓了。","notes":[]},{"n":3,"t":"那試探者進前來對他說：「你若是神的兒子，叫這些石頭變成食物吧。」","notes":[]},{"n":4,"t":"耶穌卻回答說：「經上記著：『人活著，不是單靠食物，乃是靠神口裏所出的一切話。』」","notes":[]},{"n":5,"t":"魔鬼就帶他進了聖城，叫他站在聖殿頂上，","notes":[]},{"n":6,"t":"對他說：「你若是神的兒子，就跳下去！因為經上記著：『主要為你命令他的使者，用手托住你，免得你的腳碰在石頭上。』」","notes":[]},{"n":7,"t":"耶穌對他說：「經上又記著：『不可試探主—你的神。』」","notes":[]},{"n":8,"t":"魔鬼又帶他上了一座很高的山，將世上的萬國和萬國的榮華都指給他看，","notes":[]},{"n":9,"t":"對他說：「你若俯伏拜我，我就把這一切賜給你。」","notes":[]},{"n":10,"t":"耶穌說：「撒但，退去！因為經上記著：『要拜主—你的神，惟獨事奉他。』」","notes":["「撒但」就是敵對者的意思，是魔鬼的別名。"]},{"n":11,"t":"於是，魔鬼離開了耶穌，立刻有天使來伺候他。","notes":[]},{"n":12,"t":"耶穌聽見約翰下了監，就退到加利利去；","notes":[],"heads":["開始在加利利傳道"]},{"n":13,"t":"後來離開拿撒勒，往迦百農去，住在那裏。那地方靠海，在西布倫和拿弗他利地區。","notes":[]},{"n":14,"t":"這是要應驗以賽亞先知所說的話：","notes":[]},{"n":15,"t":"「西布倫，拿弗他利，沿海的路，約旦河的東邊，外邦人的加利利—","notes":[]},{"n":16,"t":"那坐在黑暗裏的百姓看見了大光；坐在死蔭之地的人有光照耀他們。」","notes":[]},{"n":17,"t":"從那時候，耶穌開始宣講，說：「你們要悔改！因為天國近了。」","notes":[]},{"n":18,"t":"耶穌沿著加利利海邊行走，看見兩兄弟，就是那叫彼得的西門和他弟弟安得烈，正往海裏撒網；他們本是打魚的。","notes":[],"heads":["呼召四個漁夫"]},{"n":19,"t":"耶穌對他們說：「來跟從我，我要叫你們得人如得魚一樣。」","notes":[]},{"n":20,"t":"他們立刻捨了網，跟從他。","notes":[]},{"n":21,"t":"耶穌從那裏往前走，看見另外兩兄弟，就是西庇太的兒子雅各和他弟弟約翰，同他們的父親西庇太在船上補網，耶穌就呼召他們。","notes":[]},{"n":22,"t":"他們立刻捨了船，辭別父親，跟從了耶穌。","notes":[]},{"n":23,"t":"耶穌走遍加利利，在各會堂裏教導人，宣講天國的福音，醫治百姓各樣的疾病。","notes":[],"heads":["向大眾傳道"]},{"n":24,"t":"他的名聲傳遍了敘利亞。那裏的人把一切病人，就是有各樣疾病和疼痛的、被鬼附的、癲癇的、癱瘓的，都帶了來，耶穌就治好了他們。","notes":[]},{"n":25,"t":"當時，有一大群人從加利利、低加坡里、耶路撒冷、猶太、約旦河的東邊，來跟從他。","notes":[]}]},"5":{"heading":"山上寶訓","verses":[{"n":1,"t":"耶穌看見這一群人，就上了山，坐下後，門徒到他跟前來，","notes":[]},{"n":2,"t":"他開口教導他們說：","notes":[]},{"n":3,"t":"「心靈貧窮的人有福了！因為天國是他們的。","notes":[],"heads":["論福"]},{"n":4,"t":"哀慟的人有福了！因為他們必得安慰。","notes":[]},{"n":5,"t":"謙和的人有福了！因為他們必承受土地。","notes":[]},{"n":6,"t":"飢渴慕義的人有福了！因為他們必得飽足。","notes":[]},{"n":7,"t":"憐憫人的人有福了！因為他們必蒙憐憫。","notes":[]},{"n":8,"t":"清心的人有福了！因為他們必得見神。","notes":[]},{"n":9,"t":"締造和平的人有福了！因為他們必稱為神的兒子。","notes":[]},{"n":10,"t":"為義受迫害的人有福了！因為天國是他們的。","notes":[]},{"n":11,"t":"「人若因我辱罵你們，迫害你們，捏造各樣壞話毀謗你們，你們就有福了！","notes":["「捏造…你們」：有古卷是「說各樣壞話毀謗你們」。"]},{"n":12,"t":"要歡喜快樂，因為你們在天上的賞賜是很多的。在你們以前的先知，人也是這樣迫害他們。」","notes":[]},{"n":13,"t":"「你們是地上的鹽。鹽若失了味，怎能叫它再鹹呢？它不再有用，只好被丟在外面，任人踐踏。","notes":[],"heads":["鹽和光"]},{"n":14,"t":"你們是世上的光。城造在山上是不能隱藏的。","notes":[]},{"n":15,"t":"人點燈，不放在斗底下，而是放在燈臺上，就照亮一家的人。","notes":[]},{"n":16,"t":"你們的光也要這樣照在人前，叫他們看見你們的好行為，把榮耀歸給你們在天上的父。」","notes":[]},{"n":17,"t":"「不要以為我來是要廢掉律法和先知。我來不是要廢掉，而是要成全。","notes":[],"heads":["論律法"]},{"n":18,"t":"我實在告訴你們，就是到天地都廢去，律法的一點一畫也不能廢去，直到一切都實現。","notes":[]},{"n":19,"t":"所以，無論誰廢掉這誡命中最小的一條，又教導人也這樣做，他在天國裏要稱為最小的。但無論誰遵行並如此教導人的，他在天國裏要稱為大。","notes":[]},{"n":20,"t":"我告訴你們，你們的義若不勝過文士和法利賽人的義，絕不能進天國。」","notes":[]},{"n":21,"t":"「你們聽過有對古人說：『不可殺人』；『凡殺人的，必須受審判。』","notes":[],"heads":["論發怒"]},{"n":22,"t":"但是我告訴你們：凡向弟兄動怒的，必須受審判；凡罵弟兄是廢物的，必須受議會的審判；凡罵弟兄是白痴的，必須遭受地獄的火。","notes":[]},{"n":23,"t":"所以，你在祭壇上獻祭物的時候，若想起有弟兄對你懷恨，","notes":[]},{"n":24,"t":"就要把祭物留在壇前，先去跟弟兄和好，然後來獻祭物。","notes":[]},{"n":25,"t":"你同告你的冤家還在路上，就要趕快與他講和，免得他把你送交給法官，法官交給警衛，你就下在監裏了。","notes":[]},{"n":26,"t":"我實在告訴你，就是有一個大文錢還沒有還清，你也絕不能從那裏出來。」","notes":["「大文錢」﹕參「度量衡表」。"]},{"n":27,"t":"「你們聽過有話說：『不可姦淫。』","notes":[],"heads":["論姦淫"]},{"n":28,"t":"但是我告訴你們：凡看見婦女就動淫念的，這人心裏已經與她犯姦淫了。","notes":[]},{"n":29,"t":"若是你的右眼使你跌倒，就把它挖出來，丟掉。寧可失去身體中的一部分，也不讓整個身體被扔進地獄。","notes":[]},{"n":30,"t":"若是你的右手使你跌倒，就把它砍下來，丟掉。寧可失去身體中的一部分，也不讓整個身體下地獄。」","notes":[]},{"n":31,"t":"「又有話說：『無論誰休妻，都要給她休書。』","notes":[],"heads":["論休妻"]},{"n":32,"t":"但是我告訴你們：凡休妻的，除非是因不貞的緣故，否則就是使她犯姦淫了；人若娶被休的婦人，也是犯姦淫了。」","notes":[]},{"n":33,"t":"「你們又聽過有對古人說：『不可背誓，所起的誓總要向主謹守。』","notes":[],"heads":["論起誓"]},{"n":34,"t":"但是我告訴你們：甚麼誓都不可起。不可指著天起誓，因為天是神的寶座。","notes":[]},{"n":35,"t":"不可指著地起誓，因為地是他的腳凳；也不可指著耶路撒冷起誓，因為耶路撒冷是大君王的京城。","notes":[]},{"n":36,"t":"又不可指著你的頭起誓，因為你不能使一根頭髮變黑變白。","notes":[]},{"n":37,"t":"你們的話，是，就說是；不是，就說不是。若再多說，就是出於那惡者。」","notes":[]},{"n":38,"t":"「你們聽過有話說：『以眼還眼，以牙還牙。』","notes":[],"heads":["論報復"]},{"n":39,"t":"但是我告訴你們：不要與惡人作對。有人打你的右臉，連另一邊也轉過去由他打。","notes":[]},{"n":40,"t":"有人想要告你，要拿你的裏衣，連外衣也由他拿去。","notes":[]},{"n":41,"t":"有人強迫你走一里路，你就跟他走二里。","notes":["「里」原文音譯「米利翁」，古羅馬長度單位；參「度量衡表」；下同。"]},{"n":42,"t":"有求你的，就給他；有向你借貸的，不可推辭。」","notes":[]},{"n":43,"t":"「你們聽過有話說：『要愛你的鄰舍，恨你的仇敵。』","notes":[],"heads":["論愛仇敵"]},{"n":44,"t":"但是我告訴你們：要愛你們的仇敵，為那迫害你們的禱告。","notes":[]},{"n":45,"t":"這樣，你們就可以作天父的兒女了。因為他叫太陽照好人，也照壞人；降雨給義人，也給不義的人。","notes":[]},{"n":46,"t":"你們若只愛那愛你們的人，有甚麼賞賜呢？就是稅吏不也是這樣做嗎？","notes":[]},{"n":47,"t":"你們若只請你弟兄的安，有甚麼比別人強呢？就是外邦人不也是這樣做嗎？","notes":[]},{"n":48,"t":"所以，你們要完全，如同你們的天父是完全的。」","notes":[]}]},"6":{"heading":"論施捨","verses":[{"n":1,"t":"「你們要謹慎，不可故意在人面前表現虔誠，叫他們看見，若是這樣，就不能得你們天父的賞賜了。","notes":[]},{"n":2,"t":"「所以，你施捨的時候，不可叫人在你前面吹號，像那假冒為善的人在會堂裏和街道上所做的，故意要得人的稱讚。我實在告訴你們，他們已經得了他們的賞賜。","notes":[]},{"n":3,"t":"你施捨的時候，不要讓左手知道右手所做的，","notes":[]},{"n":4,"t":"好使你隱祕地施捨；你父在隱祕中察看，必然賞賜你。」","notes":[]},{"n":5,"t":"「你們禱告的時候，不可像那假冒為善的人，愛站在會堂裏和十字路口禱告，故意讓人看見。我實在告訴你們，他們已經得了他們的賞賜。","notes":[],"heads":["論禱告"]},{"n":6,"t":"你禱告的時候，要進入內室，關上門，向那在隱祕中的父禱告；你父在隱祕中察看，必將賞賜你。","notes":[]},{"n":7,"t":"你們禱告，不可像外邦人那樣重複一些空話，他們以為話多了必蒙垂聽。","notes":[]},{"n":8,"t":"你們不可效法他們。因為在你們祈求以前，你們所需要的，你們的父早已知道了。」","notes":[]},{"n":9,"t":"「所以，你們要這樣禱告：『我們在天上的父：願人都尊你的名為聖。","notes":[],"heads":["主禱文"]},{"n":10,"t":"願你的國降臨；願你的旨意行在地上，如同行在天上。","notes":[]},{"n":11,"t":"我們日用的飲食，今日賜給我們。","notes":[]},{"n":12,"t":"免我們的債，如同我們免了人的債。","notes":[]},{"n":13,"t":"不叫我們陷入試探；救我們脫離那惡者。因為國度、權柄、榮耀，全是你的，直到永遠。阿們！』","notes":["有古卷沒有「因為...阿們」等字。"]},{"n":14,"t":"你們若饒恕人的過犯，你們的天父也必饒恕你們；","notes":[]},{"n":15,"t":"你們若不饒恕人，你們的天父也必不饒恕你們的過犯。」","notes":["有古卷加「的過犯」。"]},{"n":16,"t":"「你們禁食的時候，不可像那假冒為善的人，臉上帶著愁容；因為他們蓬頭垢面，故意讓人看出他們在禁食。我實在告訴你們，他們已經得了他們的賞賜。","notes":[],"heads":["論禁食"]},{"n":17,"t":"你禁食的時候，要梳頭洗臉，","notes":[]},{"n":18,"t":"不要讓人看出你在禁食，只讓你隱祕中的父看見；你父在隱祕中察看，必然賞賜你。」","notes":[]},{"n":19,"t":"「不要為自己在地上積蓄財寶；地上有蟲子咬，能銹壞，也有賊挖洞來偷。","notes":[],"heads":["論天上的財寶"]},{"n":20,"t":"要在天上積蓄財寶；天上沒有蟲子咬，不會銹壞，也沒有賊挖洞來偷。","notes":[]},{"n":21,"t":"因為你的財寶在哪裏，你的心也在哪裏。」","notes":[]},{"n":22,"t":"「眼睛是身體的燈。你的眼睛若明亮，全身就光明；","notes":[],"heads":["眼睛是身體的燈"]},{"n":23,"t":"你的眼睛若昏花，全身就黑暗。你裏面的光若黑暗了，那黑暗是何等大呢！」","notes":[]},{"n":24,"t":"「一個人不能服侍兩個主；他不是恨這個愛那個，就是重這個輕那個。你們不能又服侍神，又服侍瑪門。」","notes":["「瑪門」意思是「錢財」。"],"heads":["論神和錢財"]},{"n":25,"t":"「所以，我告訴你們，不要為你們的生命憂慮吃甚麼喝甚麼，或為你們的身體憂慮穿甚麼。生命不勝於飲食嗎？身體不勝於衣裳嗎？","notes":["有古卷沒有「喝甚麼」。"],"heads":["不要憂慮"]},{"n":26,"t":"你們看一看那天上的飛鳥，也不種也不收，也不在倉裏存糧，你們的天父尚且養活牠們。你們不比飛鳥貴重得多嗎？","notes":[]},{"n":27,"t":"你們哪一個能藉著憂慮使壽數多加一刻呢？","notes":["「使壽數多加一刻呢」或譯「使身量多加一肘呢」。"]},{"n":28,"t":"何必為衣裳憂慮呢？你們想一想野地裏的百合花是怎麼長起來的：它也不勞動也不紡線。","notes":[]},{"n":29,"t":"然而我告訴你們，就是所羅門極榮華的時候，他所穿戴的還不如這些花的一朵呢！","notes":[]},{"n":30,"t":"你們這小信的人哪！野地裏的草今天還在，明天就丟在爐裏，神還給它這樣的妝飾，何況你們呢？","notes":[]},{"n":31,"t":"所以，不要憂慮，說：『我們吃甚麼？喝甚麼？穿甚麼？』","notes":[]},{"n":32,"t":"這都是外邦人所求的。你們需要這一切東西，你們的天父都知道。","notes":[]},{"n":33,"t":"你們要先求神的國和他的義，這些東西都要加給你們了。","notes":[]},{"n":34,"t":"所以，不要為明天憂慮，因為明天自有明天的憂慮；一天的難處一天當就夠了。」","notes":[]}]},"7":{"heading":"不要評斷人","verses":[{"n":1,"t":"「你們不要評斷別人，免得你們被審判。","notes":[]},{"n":2,"t":"因為你們怎樣評斷別人，也必怎樣被審判；你們用甚麼量器量給人，也必用甚麼量器量給你們。","notes":[]},{"n":3,"t":"為甚麼看見你弟兄眼中有刺，卻不想自己眼中有梁木呢？","notes":[]},{"n":4,"t":"你自己眼中有梁木，怎能對你弟兄說『讓我去掉你眼中的刺』呢？","notes":[]},{"n":5,"t":"你這假冒為善的人！先去掉自己眼中的梁木，然後才能看得清楚，好去掉你弟兄眼中的刺。","notes":[]},{"n":6,"t":"不要把聖物給狗，也不要把你們的珍珠丟在豬面前，恐怕牠們踐踏了珍珠，轉過來咬你們。」","notes":[]},{"n":7,"t":"「你們祈求，就給你們；尋找，就找到；叩門，就給你們開門。","notes":[],"heads":["祈求、尋找、叩門"]},{"n":8,"t":"因為凡祈求的，就得著；尋找的，就找到；叩門的，就給他開門。","notes":[]},{"n":9,"t":"你們中間誰有兒子求餅，反給他石頭呢？","notes":[]},{"n":10,"t":"求魚，反給他蛇呢？","notes":[]},{"n":11,"t":"你們雖然不好，尚且知道拿好東西給兒女，何況你們在天上的父，他豈不更要把好東西賜給求他的人嗎？","notes":[]},{"n":12,"t":"所以，無論何事，你們想要人怎樣待你們，你們也要怎樣待人，因為這就是律法和先知的道理。」","notes":[]},{"n":13,"t":"「你們要進窄門。因為通往滅亡的門是寬的，路是大的，進去的人也多；","notes":[],"heads":["要進窄門"]},{"n":14,"t":"通往生命的門是窄的，路是小的，找到的人也少。」","notes":[]},{"n":15,"t":"「你們要防備假先知。他們到你們這裏來，外面披著羊皮，裏面卻是殘暴的狼。","notes":[],"heads":["兩種果樹"]},{"n":16,"t":"豈能在荊棘上摘葡萄呢？豈能在蒺藜裏摘無花果呢？憑著他們的果子，就可以認出他們來。","notes":[]},{"n":17,"t":"這樣，凡好樹都結好果子，而壞樹結壞果子。","notes":[]},{"n":18,"t":"好樹不能結壞果子，壞樹也不能結好果子。","notes":[]},{"n":19,"t":"凡不結好果子的樹就砍下來，丟在火裏。","notes":[]},{"n":20,"t":"所以，憑著他們的果子就可以認出他們來。」","notes":[]},{"n":21,"t":"「不是每一個稱呼我『主啊，主啊』的人都能進天國；惟有遵行我天父旨意的人才能進去。","notes":[],"heads":["遵主旨得進天國"]},{"n":22,"t":"在那日必有許多人對我說：『主啊，主啊，我們不是奉你的名傳道，奉你的名趕鬼，奉你的名行許多異能嗎？』","notes":[]},{"n":23,"t":"我要向他們宣告：『我從來不認識你們，你們這些作惡的人，給我走開！』」","notes":[]},{"n":24,"t":"「所以，凡聽了我這些話又去做的，好比一個聰明人把房子蓋在磐石上。","notes":[],"heads":["兩種根基"]},{"n":25,"t":"風吹，雨打，水沖，撞擊那房子，房子總不倒塌，因為根基立在磐石上。","notes":[]},{"n":26,"t":"凡聽了我這些話而不去做的，好比一個無知的人把房子蓋在沙土上。","notes":[]},{"n":27,"t":"風吹，雨打，水沖，撞擊那房子，房子就倒塌了，並且倒塌得很厲害。」","notes":[]},{"n":28,"t":"耶穌講完了這些話，眾人對他的教導都感到驚奇，","notes":[]},{"n":29,"t":"因為他教導他們正像有權柄的人，不像他們的文士。","notes":[]}]},"8":{"heading":"潔淨痲瘋病人","verses":[{"n":1,"t":"耶穌下了山，有一大群人跟著他。","notes":[]},{"n":2,"t":"這時，一個痲瘋病人前來拜他，說：「主啊，你若肯，你能使我潔淨。」","notes":[]},{"n":3,"t":"耶穌伸手摸他，說：「我肯，你潔淨了吧！」他的痲瘋病立刻就潔淨了。","notes":[]},{"n":4,"t":"耶穌對他說：「你要注意，不可告訴任何人，只要去，讓祭司為你檢查，並獻上摩西所吩咐的祭物，作為證據給眾人看。」","notes":[]},{"n":5,"t":"耶穌進了迦百農，有一個百夫長進前來，求他，","notes":[],"heads":["治好百夫長的僮僕"]},{"n":6,"t":"說：「主啊，我的僮僕癱瘓了，躺在家裏，非常痛苦。」","notes":[]},{"n":7,"t":"耶穌說：「我去醫治他。」","notes":[]},{"n":8,"t":"百夫長回答：「主啊，你到舍下來，我不敢當；只要你說一句話，我的僮僕就會痊癒。","notes":[]},{"n":9,"t":"因為我在人的權下，也有兵在我以下。我對這個說：『去！』他就去；對那個說：『來！』他就來；對我的僕人說：『做這事！』他就去做。」","notes":[]},{"n":10,"t":"耶穌聽了就很驚訝，對跟從的人說：「我實在告訴你們，這麼大的信心，就是在以色列，我也沒有見過。","notes":[]},{"n":11,"t":"我又告訴你們，從東從西，將有許多人來，在天國裏與亞伯拉罕、以撒、雅各一同坐席；","notes":[]},{"n":12,"t":"本國的子民反而被趕到外邊黑暗裏去，在那裏要哀哭切齒了。」","notes":[]},{"n":13,"t":"耶穌對百夫長說：「你回去吧！照你的信心成全你了。」就在那時，他的僮僕好了。","notes":[]},{"n":14,"t":"耶穌到了彼得家裏，見彼得的岳母正發燒躺著。","notes":[],"heads":["治好許多病人"]},{"n":15,"t":"耶穌一摸她的手，燒就退了，於是她起來服事耶穌。","notes":[]},{"n":16,"t":"傍晚的時候，有人帶著許多被鬼附的來到耶穌跟前，他只用一句話就把邪靈都趕出去，並且治好了一切有病的人。","notes":[]},{"n":17,"t":"這是要應驗以賽亞先知所說的話：「他代替了我們的軟弱，擔當了我們的疾病。」","notes":[]},{"n":18,"t":"耶穌見許多人圍著他，就吩咐渡到對岸去。","notes":[],"heads":["跟從耶穌應有的準備"]},{"n":19,"t":"有一個文士進前來對他說：「老師，你無論往哪裏去，我都要跟從你。」","notes":[]},{"n":20,"t":"耶穌說：「狐狸有洞，天空的飛鳥有窩，人子卻沒有枕頭的地方。」","notes":[]},{"n":21,"t":"又有一個門徒對耶穌說：「主啊，容許我先回去埋葬我的父親。」","notes":[]},{"n":22,"t":"耶穌說：「讓死人埋葬他們的死人。你跟從我吧！」","notes":[]},{"n":23,"t":"耶穌上了船，門徒跟著他。","notes":[],"heads":["平靜風和海"]},{"n":24,"t":"海裏忽然起了猛烈的風暴，以致船幾乎被波浪淹沒，耶穌卻睡著了。","notes":[]},{"n":25,"t":"門徒去叫醒他，說：「主啊，救命啊，我們快沒命啦！」","notes":[]},{"n":26,"t":"耶穌說：「你們這些小信的人哪，為甚麼膽怯呢？」於是他起來，斥責風和海，風和海就大大平靜了。","notes":[]},{"n":27,"t":"眾人驚訝地說：「這是怎樣的一個人？連風和海都聽從他。」","notes":[]},{"n":28,"t":"耶穌渡到對岸去，到加大拉人的地區，有兩個被鬼附的人從墳墓迎著他走來。他們極其兇猛，甚至沒有人敢從那條路經過。","notes":["有古卷是「格各森人」；另有古卷是「格拉森人」。"],"heads":["治好加大拉被鬼附的人"]},{"n":29,"t":"他們喊著說：「神的兒子，你為甚麼干擾我們？時候還沒有到，你就上這裏來叫我們受苦嗎？」","notes":[]},{"n":30,"t":"離他們很遠，有一大群豬正在吃食。","notes":[]},{"n":31,"t":"鬼就央求耶穌，說：「若要把我們趕出去，就打發我們進入豬群吧！」","notes":[]},{"n":32,"t":"耶穌對他們說：「去吧！」鬼就出來，進入豬群。一轉眼，整群豬都闖下山崖，投進海裏，淹死了。","notes":[]},{"n":33,"t":"放豬的就逃進城去，把這一切事和被鬼附的人所遭遇的都告訴眾人。","notes":[]},{"n":34,"t":"全城的人都出來迎見耶穌，見了他以後，就央求他離開他們的地區。","notes":[]}]},"9":{"heading":"治好癱子","verses":[{"n":1,"t":"耶穌上了船，渡過海，來到自己的城裏。","notes":[]},{"n":2,"t":"有人用褥子抬著一個癱子到耶穌跟前來。耶穌見他們的信心，就對癱子說：「孩子，放心吧，你的罪赦了。」","notes":[]},{"n":3,"t":"這時，有幾個文士心裏說：「這個人說褻瀆的話了。」","notes":[]},{"n":4,"t":"耶穌知道他們的心思，就說：「你們心裏為甚麼懷著惡念呢？","notes":[]},{"n":5,"t":"說『你的罪赦了』，或說『你起來行走』，哪一樣容易呢？","notes":[]},{"n":6,"t":"但要讓你們知道，人子在地上有赦罪的權柄」，於是對癱子說：「起來！拿你的褥子回家去吧。」","notes":[]},{"n":7,"t":"那人就起來，回家去了。","notes":[]},{"n":8,"t":"眾人看見都畏懼，歸榮耀給神，因為他把這樣的權柄賜給人。","notes":[]},{"n":9,"t":"耶穌從那裏往前走，看見一個人名叫馬太，在稅關坐著，就對他說：「來跟從我！」他就起來跟從耶穌。","notes":[],"heads":["呼召馬太"]},{"n":10,"t":"耶穌在屋裏坐席的時候，有好些稅吏和罪人來，與耶穌和他的門徒一同坐席。","notes":[]},{"n":11,"t":"法利賽人看見，就對耶穌的門徒說：「你們的老師為甚麼與稅吏和罪人一同吃飯呢？」","notes":[]},{"n":12,"t":"耶穌聽見，就說：「健康的人用不著醫生；有病的人才用得著。","notes":[]},{"n":13,"t":"經上說：『我喜愛憐憫，不喜愛祭祀。』這句話的意思，你們去揣摩。我不是來召義人，而是召罪人。」","notes":[]},{"n":14,"t":"那時，約翰的門徒來見耶穌，說：「我們和法利賽人常常禁食，你的門徒卻不禁食，這是為甚麼呢？」","notes":["有古卷沒有「常常」。"],"heads":["禁食的問題"]},{"n":15,"t":"耶穌對他們說：「新郎和賓客在一起的時候，賓客怎麼能哀慟呢？但日子將到，新郎要被帶走，那時候他們就要禁食了。","notes":[]},{"n":16,"t":"沒有人把新布補在舊衣服上；因為所補上的會撕破那衣服，裂口就更大了。","notes":[]},{"n":17,"t":"也沒有人把新酒裝在舊皮袋裏，若是這樣，皮袋會脹破，酒就漏出來，皮袋也糟蹋了。相反地，把新酒裝在新皮袋裏，兩樣就都保全了。」","notes":[]},{"n":18,"t":"耶穌說這些話的時候，有一個會堂主管來，向他下跪，說：「我女兒剛死了，求你去按手在她身上，她就會活過來。」","notes":[],"heads":["會堂主管的女兒和經血不止的女人"]},{"n":19,"t":"耶穌就起來跟他去；門徒也跟了去。","notes":[]},{"n":20,"t":"這時，有一個女人，患了經血不止的病有十二年，來到耶穌背後，摸他的衣裳繸子；","notes":[]},{"n":21,"t":"因為她心裏說：「我只要摸他的衣裳，就會痊癒。」","notes":[]},{"n":22,"t":"耶穌轉過來，看見她，就說：「女兒，放心！你的信救了你。」從那時起，這女人就痊癒了。","notes":[]},{"n":23,"t":"耶穌到了會堂主管的家裏，看見吹鼓手和亂哄哄的一群人，","notes":[]},{"n":24,"t":"就說：「退去吧！這女孩不是死了，而是睡著了。」他們就嘲笑他。","notes":[]},{"n":25,"t":"眾人被趕出後，耶穌就進去，拉著她的手，女孩就起來了。","notes":[]},{"n":26,"t":"於是這消息傳遍了那地方。","notes":[]},{"n":27,"t":"耶穌從那裏往前走，有兩個盲人跟著他，喊叫說：「大衛之子，可憐我們吧！」","notes":[],"heads":["治好兩個盲人"]},{"n":28,"t":"耶穌進了屋子，盲人就來到他跟前。耶穌說：「你們信我能做這事嗎？」他們說：「主啊，我們信。」","notes":[]},{"n":29,"t":"耶穌就摸他們的眼睛，說：「照著你們的信心成全你們吧。」","notes":[]},{"n":30,"t":"他們的眼睛就開了。耶穌嚴嚴地叮囑他們說：「要小心，不可讓人知道。」","notes":[]},{"n":31,"t":"他們出去，竟把他的名聲傳遍了那地方。","notes":[]},{"n":32,"t":"他們出去的時候，有人把一個被鬼附的啞巴帶到耶穌跟前來。","notes":[],"heads":["治好啞巴"]},{"n":33,"t":"鬼被趕出去，啞巴就說出話來。眾人都很驚訝，說：「在以色列，從來沒有見過這樣的事。」","notes":[]},{"n":34,"t":"法利賽人卻說：「他是靠著鬼王趕鬼的。」","notes":[]},{"n":35,"t":"耶穌走遍各城各鄉，在他們的會堂裏教導人，宣講天國的福音，又醫治各樣的病症。","notes":[],"heads":["耶穌的憐憫"]},{"n":36,"t":"他看見一大群人，就憐憫他們；因為他們困苦無助，如同羊沒有牧人一樣。","notes":[]},{"n":37,"t":"於是他對門徒說：「要收的莊稼多，做工的人少。","notes":[]},{"n":38,"t":"所以，你們要求莊稼的主差遣做工的人出去收他的莊稼。」","notes":[]}]},"10":{"heading":"耶穌揀選十二使徒","verses":[{"n":1,"t":"耶穌叫了十二個門徒來，給他們權柄，能驅趕污靈和醫治各樣的疾病。","notes":[]},{"n":2,"t":"這十二使徒的名字如下：頭一個叫西門（又稱彼得），還有他弟弟安得烈，西庇太的兒子雅各和雅各的弟弟約翰，","notes":[]},{"n":3,"t":"腓力和巴多羅買，多馬和稅吏馬太，亞勒腓的兒子雅各，和達太，","notes":[]},{"n":4,"t":"激進黨的西門，還有出賣耶穌的加略人猶大。","notes":[]},{"n":5,"t":"耶穌差遣這十二個人出去，吩咐他們說：「外邦人的路，你們不要走；撒瑪利亞人的城，你們不要進；","notes":[],"heads":["耶穌差遣十二使徒"]},{"n":6,"t":"寧可往以色列家迷失的羊那裏去。","notes":[]},{"n":7,"t":"要邊走邊傳，說『天國近了』。","notes":[]},{"n":8,"t":"要醫治病人，使死人復活，使痲瘋病人潔淨，把鬼趕出去。你們白白地得來，也要白白地給人。","notes":[]},{"n":9,"t":"腰袋裏不要帶金銀銅錢；","notes":[]},{"n":10,"t":"途中不要帶行囊，不要帶兩件內衣，也不要帶鞋子和手杖，因為工人得飲食是應當的。","notes":[]},{"n":11,"t":"你們無論進哪一城、哪一村，要打聽那裏誰是合適的人，就住在他家，直住到離開的時候。","notes":[]},{"n":12,"t":"進他家時，要向那家請安。","notes":[]},{"n":13,"t":"那家若配得平安，你們所求的平安就臨到那家；若不配得，你們所求的平安仍歸你們。","notes":[]},{"n":14,"t":"凡不接待你們，不聽你們話的人，你們離開那家，或是那城的時候，要跺掉你們腳上的塵土。","notes":[]},{"n":15,"t":"我實在告訴你們，在審判的日子，所多瑪和蛾摩拉地方所受的，比那城還容易受呢！」","notes":[]},{"n":16,"t":"「看哪！我差你們出去，如同羊進入狼群，所以你們要機警如蛇，純真如鴿。","notes":[],"heads":["將來的迫害"]},{"n":17,"t":"你們要防備那些人，因為他們要把你們交給議會，也要在會堂裏鞭打你們。","notes":[]},{"n":18,"t":"你們要為我的緣故被送到統治者和君王面前，對他們和外邦人作見證。","notes":[]},{"n":19,"t":"當人把你們交出時，不要擔心怎樣說話，或說甚麼話。到那時候，必賜給你們該說的話，","notes":[]},{"n":20,"t":"因為不是你們自己說的，而是你們父的靈在你們裏面說的。","notes":[]},{"n":21,"t":"兄弟要把兄弟、父親要把兒女置於死地；兒女要起來與父母為敵，害死他們。","notes":[]},{"n":22,"t":"而且你們要為我的名被眾人憎恨。但堅忍到底的終必得救。","notes":[]},{"n":23,"t":"有人在這城迫害你們，就逃到另一城去。我實在告訴你們，以色列的城鎮，你們還沒有走遍，人子就要來臨。","notes":["有古卷加「若那城的人迫害你們，就逃到別的城去。」"]},{"n":24,"t":"「學生不高過老師，僕人不高過主人。","notes":[]},{"n":25,"t":"學生所遭遇的與老師一樣，僕人所遭遇的與主人一樣，也就夠了。既然有人罵一家的主人是『別西卜』，更何況他的家人呢？」","notes":["「別西卜」：鬼王的名。"]},{"n":26,"t":"「所以，不要怕他們，因為掩蓋的事沒有不顯露出來的，隱藏的事也沒有不被知道的。","notes":[],"heads":["不要懼怕"]},{"n":27,"t":"我在暗中告訴你們的，你們要在明處說出來；你們耳中所聽的，要在屋頂上宣揚出來。","notes":[]},{"n":28,"t":"那殺人身體但不能滅人靈魂的，不要怕他們；惟有那能在地獄裏毀滅身體和靈魂的，才要怕他。","notes":[]},{"n":29,"t":"兩隻麻雀不是賣一銅錢嗎？你們的父若不許，一隻也不會掉在地上。","notes":["「銅錢」：參「度量衡表」。"]},{"n":30,"t":"就是你們的頭髮也都數過了。","notes":[]},{"n":31,"t":"所以，不要懼怕，你們比許多的麻雀還貴重！」","notes":[]},{"n":32,"t":"「所以，凡在人面前認我的，我在我天上的父面前也必認他；","notes":[],"heads":["在人的面前認基督"]},{"n":33,"t":"凡在人面前不認我的，我在我天上的父面前也必不認他。」","notes":[]},{"n":34,"t":"「你們不要以為我來是帶給地上和平，我來並不是帶來和平，而是刀劍。","notes":[],"heads":["作門徒的代價"]},{"n":35,"t":"因為我來是要叫『人與父親對立，女兒與母親對立，媳婦與婆婆對立。","notes":[]},{"n":36,"t":"人的仇敵就是自己家裏的人。』","notes":[]},{"n":37,"t":"愛父母勝過愛我的，不配作我的門徒；愛兒女勝過愛我的，不配作我的門徒。","notes":[]},{"n":38,"t":"不背自己的十字架跟從我的，不配作我的門徒。","notes":[]},{"n":39,"t":"得著性命的，要喪失性命；為我喪失性命的，要得著性命。」","notes":[]},{"n":40,"t":"「接納你們的就是接納我；接納我的就是接納差遣我來的那位。","notes":[],"heads":["論賞賜"]},{"n":41,"t":"把先知當作先知接納的，必得先知的賞賜；把義人當作義人接納的，必得義人的賞賜。","notes":[]},{"n":42,"t":"無論誰，只因門徒的名，就算把一杯涼水給這些小子中的一個喝，我實在告訴你們，他一定會得到賞賜。」","notes":[]}]},"11":{"heading":"施洗約翰的門徒來見耶穌","verses":[{"n":1,"t":"耶穌吩咐完了十二個門徒，就離開那裏，往各城去傳道，教導人。","notes":[]},{"n":2,"t":"約翰在監獄裏聽見基督所做的事，就派他的門徒去，","notes":[]},{"n":3,"t":"問耶穌：「將要來的那位就是你嗎？還是我們要等候另一位呢？」","notes":[]},{"n":4,"t":"耶穌回答他們：「你們去，把所聽見、所看見的告訴約翰：","notes":[]},{"n":5,"t":"就是盲人看見，瘸子行走，痲瘋病人得潔淨，聾子聽見，死人復活，窮人聽到福音。","notes":[]},{"n":6,"t":"凡不因我跌倒的有福了！」","notes":[]},{"n":7,"t":"他們一走，耶穌就對眾人談到約翰，說：「你們從前到曠野去，是要看甚麼呢？看風吹動的蘆葦嗎？","notes":[]},{"n":8,"t":"你們出去到底是要看甚麼？看穿細軟衣服的人嗎？那穿細軟衣服的人是在王宮裏。","notes":[]},{"n":9,"t":"你們出去究竟是要看甚麼？是先知嗎？是的，我告訴你們，他比先知大多了。","notes":[]},{"n":10,"t":"這個人就是經上所說的：『看哪，我要差遣我的使者在你面前，他要在你前面為你預備道路。』","notes":[]},{"n":11,"t":"我實在告訴你們，凡女子所生的，沒有一個比施洗約翰大；但在天國裏，最小的比他還大。","notes":[]},{"n":12,"t":"從施洗約翰的日子到今天，天國受到強烈的攻擊，強者奪取它。","notes":["「天國…奪取它」或譯「天國是要努力進入的，努力的人就得著了」。"]},{"n":13,"t":"眾先知和律法，直到約翰為止，都說了預言。","notes":[]},{"n":14,"t":"如果你們願意接受，這人就是那要來的以利亞。","notes":[]},{"n":15,"t":"有耳的，就應當聽！","notes":[]},{"n":16,"t":"「我該用甚麼來比這世代呢？這正像孩童坐在街市上向同伴呼喊：","notes":[]},{"n":17,"t":"『我們為你們吹笛，你們不跳舞；我們唱哀歌，你們不捶胸。』","notes":[]},{"n":18,"t":"約翰來了，既不吃也不喝，人們就說他是被鬼附的；","notes":[]},{"n":19,"t":"人子來了，也吃也喝，他們又說這人貪食好酒，是稅吏和罪人的朋友。而智慧是由它的果子來證實的。」","notes":["有古卷是「而智慧是以行為來證實的」。"]},{"n":20,"t":"那時，耶穌在一些城行了許多異能。因為城裏的人不肯悔改，他就責備那些城說：","notes":[],"heads":["耶穌責備不悔改的城"]},{"n":21,"t":"「哥拉汛哪，你有禍了！伯賽大啊，你有禍了！因為在你們中間所行的異能若行在推羅、西頓，他們早已披麻蒙灰悔改了。","notes":[]},{"n":22,"t":"但我告訴你們，在審判的日子，推羅和西頓所受的，比你們還容易受呢！","notes":[]},{"n":23,"t":"迦百農啊，你以為要被舉到天上嗎？你要被推下陰間！因為在你那裏所行的異能，若行在所多瑪，它還可以存留到今日。","notes":[]},{"n":24,"t":"但我告訴你們，在審判的日子，所多瑪地方所受的，比你們還容易受呢！」","notes":[]},{"n":25,"t":"那時，耶穌說：「父啊，天地的主，我感謝你！因為你把這些事向聰明智慧的人隱藏起來，而向嬰孩啟示出來。","notes":[],"heads":["到我這裏來"]},{"n":26,"t":"父啊，是的，因為你的美意本是如此。","notes":[]},{"n":27,"t":"一切都是我父交給我的；除了父，沒有人知道子；除了子和子所願意啟示的人，沒有人知道父。","notes":[]},{"n":28,"t":"凡勞苦擔重擔的人都到我這裏來，我要使你們得安息。","notes":[]},{"n":29,"t":"我心裏柔和謙卑，你們當負我的軛，向我學習；這樣，你們的心靈就必得安息。","notes":[]},{"n":30,"t":"因為我的軛是容易的，我的擔子是輕省的。」","notes":[]}]},"12":{"heading":"在安息日摘麥穗","verses":[{"n":1,"t":"那時，耶穌在安息日從麥田經過。他的門徒餓了，就摘麥穗來吃。","notes":[]},{"n":2,"t":"法利賽人看見，對耶穌說：「看哪，你的門徒在安息日做不合法的事了。」","notes":[]},{"n":3,"t":"耶穌對他們說：「大衛和跟從他的人飢餓時所做的事，你們沒有念過嗎？","notes":[]},{"n":4,"t":"他怎麼進了神的居所，吃了供餅呢？這餅是他和跟從他的人不可以吃的，惟獨祭司才可以吃。","notes":[]},{"n":5,"t":"再者，律法上所記的，在安息日，祭司在聖殿裏犯了安息日也不算有罪，你們沒有念過嗎？","notes":[]},{"n":6,"t":"但我告訴你們，比聖殿更大的在這裏。","notes":[]},{"n":7,"t":"『我喜愛憐憫，不喜愛祭祀。』你們若明白這話的意思，就不將無罪的當作有罪了。","notes":[]},{"n":8,"t":"因為人子是安息日的主。」","notes":[]},{"n":9,"t":"耶穌離開那地方，進了猶太人的會堂；","notes":[],"heads":["治好萎縮了的手"]},{"n":10,"t":"那裏有個一隻手萎縮了的人。有人為了要控告耶穌，就問他：「安息日治病合不合法？」","notes":[]},{"n":11,"t":"耶穌對他們說：「你們中間誰有一隻羊在安息日掉在坑裏，不抓住牠，把牠拉上來呢？","notes":[]},{"n":12,"t":"人比羊貴重得多了！所以，在安息日做善事是合法的。」","notes":[]},{"n":13,"t":"於是對那人說：「伸出手來！」他把手一伸，手就復原了，和另一隻一樣。","notes":[]},{"n":14,"t":"法利賽人出去，商議怎樣除掉耶穌。","notes":[]},{"n":15,"t":"耶穌知道了，就離開那裏，有一大群人跟著他。他把所有的病人都治好了，","notes":[],"heads":["神所揀選的僕人"]},{"n":16,"t":"又囑咐他們不要把他宣揚出去。","notes":[]},{"n":17,"t":"這是要應驗以賽亞先知所說的話：","notes":[]},{"n":18,"t":"「看哪，我所揀選的僕人，我所親愛，心所喜悅的；我要將我的靈賜給他，他必將公理傳給外邦。","notes":[]},{"n":19,"t":"他不爭吵，不喧嚷，街上也沒有人聽見他的聲音。","notes":[]},{"n":20,"t":"壓傷的蘆葦，他不折斷，將殘的燈火，他不吹滅，直到他使公理得勝。","notes":[]},{"n":21,"t":"外邦人都要仰望他的名。」","notes":[]},{"n":22,"t":"當時，有人把一個被鬼附，又盲又啞的人帶到耶穌那裏，耶穌醫治他，那啞巴就能說話，又能看見。","notes":[],"heads":["誣蔑耶穌為別西卜"]},{"n":23,"t":"眾人都驚奇，說：「這不是大衛之子嗎？」","notes":[]},{"n":24,"t":"但法利賽人聽見，就說：「這個人趕鬼，無非是靠著鬼王別西卜罷了。」","notes":[]},{"n":25,"t":"耶穌知道他們的心思，就對他們說：「一國自相紛爭，必定荒蕪；一城一家自相紛爭，必立不住。","notes":[]},{"n":26,"t":"若撒但趕出撒但，就是自相紛爭，他的國怎能立得住呢？","notes":[]},{"n":27,"t":"我若靠著別西卜趕鬼，你們的子弟趕鬼又靠著誰呢？這樣，他們要作你們的判官。","notes":[]},{"n":28,"t":"我若靠著神的靈趕鬼，那麼，神的國就已臨到你們了。","notes":[]},{"n":29,"t":"人怎能進壯士家裏搶奪他的東西呢？除非先綁住那壯士，否則無法搶奪他的家。","notes":[]},{"n":30,"t":"不跟我一起的，就是反對我；不與我一起收聚的，就是在拆散。","notes":[]},{"n":31,"t":"所以我告訴你們，人一切的罪和褻瀆的話都可得赦免，但是褻瀆聖靈，總不得赦免。","notes":[]},{"n":32,"t":"凡說話干犯人子的，還可得赦免；但是說話干犯聖靈的，今世來世總不得赦免。」","notes":[]},{"n":33,"t":"「你們知道樹好，果子也好；又知道樹壞，果子也壞；因為看果子就可以知道樹。","notes":[],"heads":["樹和果子"]},{"n":34,"t":"毒蛇的孽種啊，你們既是惡人，怎能說出好話來呢？因為心裏所充滿的，口裏就說出來。","notes":[]},{"n":35,"t":"善人從他所存的善發出善來；惡人從他所存的惡發出惡來。","notes":[]},{"n":36,"t":"我告訴你們，凡是人所說的閒話，在審判的日子，要句句供出來；","notes":[]},{"n":37,"t":"因為要憑你的話定你為義，也要憑你的話定你有罪。」","notes":[]},{"n":38,"t":"當時，有幾個文士和法利賽人對耶穌說：「老師，我們想請你顯個神蹟給我們看看。」","notes":[],"heads":["求神蹟"]},{"n":39,"t":"耶穌回答他們：「邪惡淫亂的世代求看神蹟，除了先知約拿的神蹟以外，再沒有神蹟給他們看了。","notes":[]},{"n":40,"t":"約拿三日三夜在大魚肚腹中，同樣，人子也要三日三夜在地裏面。","notes":[]},{"n":41,"t":"在審判的時候，尼尼微人要起來定這世代的罪，因為尼尼微人聽了約拿所傳的就悔改了。看哪，比約拿更大的在這裏！","notes":[]},{"n":42,"t":"在審判的時候，南方的女王要起來定這世代的罪，因為她從地極而來，要聽所羅門智慧的話。看哪，比所羅門更大的在這裏！」","notes":[]},{"n":43,"t":"「污靈離了人身，走遍無水之地尋找安歇之處，卻找不到。","notes":[],"heads":["污靈回來"]},{"n":44,"t":"於是他說：『我要回到我原來的屋裏去。』他到了，看見裏面空著，打掃乾淨，修飾好了，","notes":[]},{"n":45,"t":"就去另帶了七個比自己更惡的靈來，都進去住在那裏。那人後來的景況比先前更壞了。這邪惡的世代也要如此。」","notes":[]},{"n":46,"t":"耶穌還在對眾人說話的時候，不料，他母親和他兄弟站在外邊想要跟他說話。","notes":[],"heads":["遵父旨意的人都是親屬"]},{"n":47,"t":"有人告訴他：「看哪！你母親和你兄弟站在外邊，想要跟你說話。」","notes":["有古卷沒有47節。"]},{"n":48,"t":"他卻回答那對他說話的人，說：「誰是我的母親？誰是我的兄弟？」","notes":[]},{"n":49,"t":"於是他伸手指著門徒，說：「看哪，我的母親，我的兄弟！","notes":[]},{"n":50,"t":"凡遵行我天父旨意的人就是我的兄弟、姊妹和母親。」","notes":[]}]},"13":{"heading":"撒種的比喻","verses":[{"n":1,"t":"就在那天，耶穌從房子裏出來，坐在海邊。","notes":[]},{"n":2,"t":"有一大群人到他那裏聚集，他只好上船坐下，眾人都站在岸上。","notes":[]},{"n":3,"t":"他用比喻對他們講了許多話。他說：「有一個撒種的出去撒種。","notes":[]},{"n":4,"t":"他撒的時候，有的落在路旁，飛鳥來把它們吃掉了。","notes":[]},{"n":5,"t":"有的落在土淺的石頭地上，因為土不深，很快就長出苗來，","notes":[]},{"n":6,"t":"太陽出來一曬，因為沒有根就枯乾了。","notes":[]},{"n":7,"t":"有的落在荊棘裏，荊棘長起來，把它擠住了。","notes":[]},{"n":8,"t":"又有的落在好土裏，就結出果實，有一百倍的，有六十倍的，有三十倍的。","notes":[]},{"n":9,"t":"有耳的，就應當聽！」","notes":[]},{"n":10,"t":"門徒進前來問耶穌：「對眾人講話，為甚麼用比喻呢？」","notes":[],"heads":["用比喻的目的"]},{"n":11,"t":"耶穌回答他們說：「因為天國的奧祕只讓你們知道，不讓他們知道。","notes":[]},{"n":12,"t":"凡有的，還要給他，讓他有餘；凡沒有的，連他所有的也要奪去。","notes":[]},{"n":13,"t":"我之所以用比喻對他們講，是因為他們看卻看不清，聽卻聽不見，也不明白。","notes":[]},{"n":14,"t":"在他們身上，正應驗了以賽亞的預言：『你們聽了又聽，卻不明白，看了又看，卻看不清。","notes":[]},{"n":15,"t":"因為這百姓的心麻木，耳朵發沉，眼睛閉著，免得眼睛看見，耳朵聽見，心裏明白，回轉過來，我會醫治他們。』","notes":[]},{"n":16,"t":"但你們的眼睛是有福的，因為看得見；你們的耳朵也是有福的，因為聽得見。","notes":[]},{"n":17,"t":"我實在告訴你們，從前有許多先知和義人要看你們所看的，卻沒有看見；要聽你們所聽的，卻沒有聽見。」","notes":[]},{"n":18,"t":"「所以，你們要聽這撒種的比喻。","notes":[],"heads":["解釋撒種的比喻"]},{"n":19,"t":"凡聽見天國的道而不明白的，那惡者就來，把撒在他心裏的奪了去；這就是撒在路旁的了。","notes":[]},{"n":20,"t":"撒在石頭地上的，就是人聽了道，立刻歡喜領受，","notes":[]},{"n":21,"t":"只因心裏沒有根，不過是暫時的，一旦為道遭受患難或迫害，立刻就跌倒。","notes":[]},{"n":22,"t":"撒在荊棘裏的，就是人聽了道，後來有世上的憂慮、錢財的迷惑把道擠住了，結不出果實。","notes":[]},{"n":23,"t":"撒在好土裏的，就是人聽了道，明白了，後來結了果實，有一百倍的，有六十倍的，有三十倍的。」","notes":[]},{"n":24,"t":"耶穌又設個比喻對他們說：「天國好比人撒好種在田裏，","notes":[],"heads":["雜草的比喻"]},{"n":25,"t":"在人睡覺的時候，他的仇敵來，把雜草撒在麥子裏就走了。","notes":[]},{"n":26,"t":"到長苗吐穗的時候，雜草也顯出來。","notes":[]},{"n":27,"t":"地主的僕人進前來對他說：『主人，你不是撒好種在田裏嗎？哪裏來的雜草呢？』","notes":[]},{"n":28,"t":"主人回答他們：『這是仇敵做的。』僕人對他說：『你要我們去拔掉嗎？』","notes":[]},{"n":29,"t":"主人說：『不必，恐怕拔雜草，也把麥子連根拔出來。","notes":[]},{"n":30,"t":"讓這兩樣一起長，等到收割。當收割的時候，我會對收割的人說，先把雜草拔出來，捆成捆，留著燒，把麥子收在我的倉裏。』」","notes":[]},{"n":31,"t":"他又設個比喻對他們說：「天國好比一粒芥菜種，有人拿去種在田裏。","notes":[],"heads":["芥菜種和麵酵的比喻"]},{"n":32,"t":"它原比所有的種子都小，等到長起來，卻比各樣的菜都大，且成了樹，以致天上的飛鳥來在它的枝上築巢。」","notes":[]},{"n":33,"t":"他又對他們講另一個比喻：「天國好比麵酵，有婦人拿來放進三斗麵裏，直到全團都發起來。」","notes":[]},{"n":34,"t":"這都是耶穌用比喻對眾人說的話，不用比喻，他就不對他們說甚麼。","notes":[],"heads":["用比喻的原因"]},{"n":35,"t":"這是要應驗先知所說的話：「我要開口說比喻，說出從創世以來所隱藏的事。」","notes":["有古卷加「以賽亞」。"]},{"n":36,"t":"當時，耶穌離開眾人，進了屋子。他的門徒進前來，說：「請把田間雜草的比喻講給我們聽。」","notes":[],"heads":["解釋雜草的比喻"]},{"n":37,"t":"他回答：「那撒好種的就是人子，","notes":[]},{"n":38,"t":"田地就是世界，好種就是天國之子，雜草就是那惡者之子，","notes":[]},{"n":39,"t":"撒雜草的仇敵就是魔鬼，收割的時候就是世代的終結，收割的人就是天使。","notes":[]},{"n":40,"t":"正如把雜草拔出來用火焚燒，世代的終結也要如此。","notes":[]},{"n":41,"t":"人子要差遣他的使者，把一切使人跌倒的和作惡的從他國裏挑出來，","notes":[]},{"n":42,"t":"丟在火爐裏，在那裏要哀哭切齒了。","notes":[]},{"n":43,"t":"那時，義人要在他們父的國裏發出光來，像太陽一樣。有耳的，就應當聽！」","notes":[]},{"n":44,"t":"「天國好比寶貝藏在地裏，人發現了就把它藏起來，歡歡喜喜地去變賣一切所有的，買這塊地。","notes":[],"heads":["藏寶和尋珠的比喻"]},{"n":45,"t":"「天國又好比商人尋找好的珍珠，","notes":[]},{"n":46,"t":"發現一顆貴重的珍珠，就去變賣他一切所有的，買下這顆珍珠。」","notes":[]},{"n":47,"t":"「天國又好比網撒在海裏，聚攏各種魚類，","notes":[],"heads":["撒網的比喻"]},{"n":48,"t":"網一滿，人們就把它拉上岸，坐下來，揀好的收在桶裏，不好的丟掉。","notes":[]},{"n":49,"t":"世代的終結也要這樣：天使要出來，把惡人從義人中分別出來，","notes":[]},{"n":50,"t":"丟在火爐裏，在那裏要哀哭切齒了。」","notes":[]},{"n":51,"t":"耶穌說：「這一切的話你們都明白了嗎？」他們對他說：「明白了。」","notes":[],"heads":["新舊庫藏"]},{"n":52,"t":"他對他們說：「凡文士學習作天國的門徒，就像一個家的主人從他庫裏拿出新的和舊的東西來。」","notes":[]},{"n":53,"t":"耶穌說完了這些比喻，就離開那裏，","notes":[],"heads":["拿撒勒人厭棄耶穌"]},{"n":54,"t":"來到自己的家鄉，在會堂裏教導人，以致他們都很驚奇，說：「這人哪來這樣的智慧和異能呢？","notes":[]},{"n":55,"t":"這不是那木匠的兒子嗎？他母親不是叫馬利亞嗎？他兄弟們不是叫雅各、約瑟、西門、猶大嗎？","notes":["「約瑟」：有古卷是「約西」。"]},{"n":56,"t":"他姊妹們不是都在我們這裏嗎？他這一切是從哪裏來的呢？」","notes":[]},{"n":57,"t":"他們就厭棄他。耶穌對他們說：「先知除了在本鄉和自己的家之外，沒有不被尊敬的。」","notes":[]},{"n":58,"t":"耶穌因為他們不信，沒有在那裏行很多異能。","notes":[]}]},"14":{"heading":"施洗約翰之死","verses":[{"n":1,"t":"那時，希律分封王聽見耶穌的名聲，","notes":[]},{"n":2,"t":"就對臣僕說：「這是施洗的約翰從死人中復活，因此才有這些異能在他裏面運行。」","notes":[]},{"n":3,"t":"原來，希律為他兄弟腓力的妻子希羅底的緣故，把約翰抓住綁了，關進監獄，","notes":[]},{"n":4,"t":"因為約翰曾對他說：「你佔有這婦人是不合法的。」","notes":[]},{"n":5,"t":"希律就想要殺他，可是怕民眾，因為他們認為約翰是先知。","notes":[]},{"n":6,"t":"到了希律的生日，希羅底的女兒在眾人面前跳舞，使希律歡喜，","notes":[]},{"n":7,"t":"於是希律發誓許諾隨她所求的給她。","notes":[]},{"n":8,"t":"女兒被母親指使，就說：「請把施洗約翰的頭放在盤子裏，拿來給我。」","notes":[]},{"n":9,"t":"王就憂愁，然而因他所發的誓，又因同席的人，就下令給她；","notes":[]},{"n":10,"t":"於是打發人去，在監獄裏斬了約翰，","notes":[]},{"n":11,"t":"把頭放在盤子裏，拿來給那女孩，她拿去給她母親。","notes":[]},{"n":12,"t":"約翰的門徒來，把屍體領去埋葬了，又去告訴耶穌。","notes":[]},{"n":13,"t":"耶穌聽到了，就從那裏上船，私下退到荒野的地方去。眾人聽到後，從各城來，步行跟隨他。","notes":[],"heads":["耶穌使五千人吃飽"]},{"n":14,"t":"耶穌出來，見有一大群人，就憐憫他們，治好了他們的病人。","notes":[]},{"n":15,"t":"傍晚的時候，門徒進前來，說：「這地方偏僻，而且時候已經晚了，請叫眾人散去，他們好進村子，自己買些食物。」","notes":[]},{"n":16,"t":"耶穌對他們說：「不用他們去，你們給他們吃吧！」","notes":[]},{"n":17,"t":"門徒說：「我們這裏只有五個餅、兩條魚。」","notes":[]},{"n":18,"t":"耶穌說：「拿過來給我。」","notes":[]},{"n":19,"t":"於是他吩咐眾人坐在草地上，就拿著這五個餅和兩條魚，望著天祝福，擘開餅，遞給門徒，門徒又遞給眾人。","notes":[]},{"n":20,"t":"他們都吃，並且吃飽了。門徒把剩下的碎屑收拾起來，裝滿了十二個籃子。","notes":[]},{"n":21,"t":"吃的人中，男的約有五千，還不算婦女和孩子。","notes":[]},{"n":22,"t":"耶穌隨即催門徒上船，先渡到對岸，等他叫眾人散去。","notes":[],"heads":["耶穌在海上行走"]},{"n":23,"t":"疏散了眾人以後，他獨自上山去禱告。到了晚上，只有他一人在那裏。","notes":[]},{"n":24,"t":"那時船已離岸好幾里 ，因風不順，被浪顛簸。","notes":["「里」：原文是「斯他迪」，古希臘長度單位；參「度量衡表」。","「已離岸好幾里」：有古卷是「正在海中」。"]},{"n":25,"t":"天快亮的時候，耶穌在海面上走，往門徒那裏去。","notes":[]},{"n":26,"t":"但門徒看見他在海面上走，就驚慌了，說：「是個鬼怪！」他們害怕得喊叫起來。","notes":[]},{"n":27,"t":"耶穌連忙對他們說：「放心！是我，不要怕！」","notes":[]},{"n":28,"t":"彼得回答他說：「主啊，如果是你，請叫我從水面上走到你那裏去。」","notes":[]},{"n":29,"t":"耶穌說：「你來吧！」彼得就從船上下去，在水面上走，往耶穌那裏去；","notes":[]},{"n":30,"t":"只因見風很強，害怕起來，將要沉下去，就喊著說：「主啊，救我！」","notes":["「風很強」：有古卷沒有「很強」；另有古卷是「風勢非常猛烈」。"]},{"n":31,"t":"耶穌立刻伸手拉住他，說：「你這小信的人哪，為甚麼疑惑呢？」","notes":[]},{"n":32,"t":"他們一上船，風就停了。","notes":[]},{"n":33,"t":"在船上的人都拜他，說：「你真是神的兒子。」","notes":[]},{"n":34,"t":"他們渡過了海，在革尼撒勒上岸。","notes":[],"heads":["治好革尼撒勒的病人"]},{"n":35,"t":"那裏的人認出耶穌，就打發人到整個周圍地區去，把所有的病人帶到他那裏，","notes":[]},{"n":36,"t":"求耶穌讓他們只摸一摸他的衣裳繸子，摸著的人就都好了。","notes":[]}]},"15":{"heading":"論古人的傳統","verses":[{"n":1,"t":"那時，有法利賽人和文士從耶路撒冷來見耶穌，說：","notes":[]},{"n":2,"t":"「你的門徒為甚麼違反古人的傳統？因為他們吃飯的時候不洗手。」","notes":[]},{"n":3,"t":"耶穌回答他們：「你們為甚麼因你們的傳統而違反神的誡命呢？","notes":[]},{"n":4,"t":"神說：『當孝敬父母』；又說：『咒罵父母的，必須處死。』","notes":[]},{"n":5,"t":"你們倒說：『無論誰對父母說：我所當供奉你的已經作了奉獻，","notes":[]},{"n":6,"t":"就可以不孝敬他的父親。』這就是你們藉著傳統，廢了神的話。","notes":["有古卷是「他的父母」。"]},{"n":7,"t":"假冒為善的人哪！以賽亞指著你們所預言的說得好：","notes":[]},{"n":8,"t":"『這百姓用嘴唇尊敬我，他們的心卻遠離我。","notes":[]},{"n":9,"t":"他們把人的規條當作教義教導人；他們拜我也是枉然。』」","notes":[]},{"n":10,"t":"耶穌叫了眾人來，對他們說：「你們要聽，也要明白。","notes":[]},{"n":11,"t":"從口裏進去的不玷污人，從口裏出來的才玷污人。」","notes":[]},{"n":12,"t":"當時，門徒進前來對他說：「法利賽人聽見這話很反感，你知道嗎？」","notes":[]},{"n":13,"t":"耶穌回答：「一切植物，若不是我天父栽植的，都要連根拔出來。","notes":[]},{"n":14,"t":"由他們吧！他們是瞎子作瞎子的嚮導；若是瞎子領瞎子，兩個人都要掉在坑裏。」","notes":["有古卷是「他們是瞎子作嚮導」。"]},{"n":15,"t":"彼得回應他說：「請將這比喻講解給我們聽。」","notes":[]},{"n":16,"t":"耶穌說：「連你們也還不明白嗎？","notes":[]},{"n":17,"t":"難道你們不了解，凡進到口裏的，是經過肚子，又排入廁所嗎？","notes":[]},{"n":18,"t":"然而口裏出來的是出於心裏，這才玷污人。","notes":[]},{"n":19,"t":"因為出於心裏的有種種惡念，如兇殺、姦淫、淫亂、偷盜、偽證、毀謗。","notes":[]},{"n":20,"t":"這些才玷污人。至於不洗手吃飯，那並不玷污人。」","notes":[]},{"n":21,"t":"耶穌離開那裏，退到推羅、西頓境內。","notes":[],"heads":["迦南婦人的信心"]},{"n":22,"t":"有一個迦南婦人從那地方出來，喊著說：「主啊，大衛之子，可憐我！我女兒被鬼纏得很苦。」","notes":[]},{"n":23,"t":"耶穌卻一言不答。門徒進前來，求他說：「這婦人在我們後頭喊叫，請打發她走吧。」","notes":[]},{"n":24,"t":"耶穌回答：「我奉差遣只到以色列家迷失的羊那裏去。」","notes":[]},{"n":25,"t":"那婦人來拜他，說：「主啊，幫幫我！」","notes":[]},{"n":26,"t":"他回答：「拿孩子的餅丟給小狗吃是不妥的。」","notes":[]},{"n":27,"t":"婦人說：「主啊，不錯，可是小狗也吃牠主人桌上掉下來的碎屑。」","notes":[]},{"n":28,"t":"於是耶穌回答她說：「婦人，你的信心很大！照你所要的成全你吧。」從那時起，她的女兒就好了。","notes":[]},{"n":29,"t":"耶穌離開那地方，來到靠近加利利的海邊，就上山坐下。","notes":[],"heads":["治好許多病人"]},{"n":30,"t":"有一大群人到他那裏，帶著瘸子、盲人、肢殘的、聾啞的，和好些別的病人，都放在他腳前，他就治好了他們。","notes":[]},{"n":31,"t":"於是眾人都驚訝，因為看見聾啞的說話，肢殘的痊癒，瘸子行走，盲人看見，他們就歸榮耀給以色列的神。","notes":[]},{"n":32,"t":"耶穌叫門徒來，說：「我憐憫這群人，因為他們同我在這裏已經三天，沒有吃的東西了。我不願意叫他們餓著回去，恐怕他們在路上餓昏了。」","notes":[],"heads":["耶穌使四千人吃飽"]},{"n":33,"t":"門徒說：「我們在這野地，哪裏有這麼多的餅讓這許多人吃飽呢？」","notes":[]},{"n":34,"t":"耶穌對他們說：「你們有多少餅？」他們說：「有七個，還有幾條小魚。」","notes":[]},{"n":35,"t":"他就吩咐眾人坐在地上，","notes":[]},{"n":36,"t":"拿著這七個餅和幾條魚，祝謝了，擘開，遞給門徒；門徒又遞給眾人。","notes":[]},{"n":37,"t":"他們都吃，並且吃飽了，收拾剩下的碎屑，裝滿了七個筐子。","notes":[]},{"n":38,"t":"吃的人中，男的有四千，還不算婦女和孩子。","notes":[]},{"n":39,"t":"耶穌叫眾人散去，就上船，來到馬加丹境內。","notes":["「馬加丹」：有古卷是「抹大拉」。"]}]},"16":{"heading":"求神蹟","verses":[{"n":1,"t":"法利賽人和撒都該人來試探耶穌，請他顯個來自天上的神蹟給他們看。","notes":[]},{"n":2,"t":"耶穌回答他們：「傍晚天發紅，你們就說：『明日天晴。』","notes":[]},{"n":3,"t":"早晨天色又紅又暗，你們就說：『今日有風雨。』你們知道分辨天上的氣象，倒不能分辨這個時代的神蹟。","notes":["有古卷沒有「傍晚…神蹟」。"]},{"n":4,"t":"邪惡淫亂的世代求看神蹟，除了約拿的神蹟以外，再沒有神蹟給他們看了。」於是耶穌離開他們走了。","notes":[]},{"n":5,"t":"門徒渡到對岸，忘了帶餅。","notes":[],"heads":["防備法利賽人和撒都該人的酵"]},{"n":6,"t":"耶穌對他們說：「你們要謹慎，要防備法利賽人和撒都該人的酵。」","notes":[]},{"n":7,"t":"門徒彼此議論說：「這是因為我們沒有帶餅吧。」","notes":[]},{"n":8,"t":"耶穌知道了，就說：「你們這小信的人，為甚麼因為沒有餅就彼此議論呢？","notes":[]},{"n":9,"t":"你們還不明白嗎？不記得那五個餅分給五千人，你們收拾了多少籃子的碎屑嗎？","notes":[]},{"n":10,"t":"也不記得那七個餅分給四千人，你們又收拾了多少筐子的碎屑嗎？","notes":[]},{"n":11,"t":"我對你們說『要防備法利賽人和撒都該人的酵』，這話不是指著餅說的，你們怎麼不明白呢？」","notes":[]},{"n":12,"t":"門徒這才明白他所說的不是要他們防備餅的酵，而是要防備法利賽人和撒都該人的教訓。","notes":["「防備餅的酵」：有古卷是「防備法利賽人和撒都該人的酵」。"]},{"n":13,"t":"耶穌到了凱撒利亞．腓立比的境內，就問門徒：「人們說人子是誰？」","notes":[],"heads":["彼得認耶穌為基督"]},{"n":14,"t":"他們說：「有人說是施洗的約翰；有人說是以利亞；又有人說是耶利米或是先知中的一位。」","notes":[]},{"n":15,"t":"耶穌問他們：「你們說我是誰？」","notes":[]},{"n":16,"t":"西門‧彼得回答說：「你是基督，是永生神的兒子。」","notes":[]},{"n":17,"t":"耶穌回答他說：「約拿的兒子西門，你是有福的！因為這不是屬血肉的啟示你的，而是我在天上的父啟示的。","notes":[]},{"n":18,"t":"我還告訴你，你是彼得，我要把我的教會建造在這磐石上，陰間的權柄不能勝過它。","notes":["「彼得」：原文的意思是「磐石」。"]},{"n":19,"t":"我要把天國的鑰匙給你，凡你在地上所捆綁的，在天上也要捆綁；凡你在地上所釋放的，在天上也要釋放。」","notes":[]},{"n":20,"t":"當時，耶穌囑咐門徒不可對任何人說他是基督。","notes":[]},{"n":21,"t":"從那時起，耶穌才向門徒明說，他必須上耶路撒冷去，受長老、祭司長和文士許多的苦，並且被殺，第三天復活。","notes":[],"heads":["耶穌預言受難和復活"]},{"n":22,"t":"彼得就拉著他，責備他說：「主啊，千萬不可如此！這事絕不可臨到你身上。」","notes":[]},{"n":23,"t":"耶穌轉過來，對彼得說：「撒但，退到我後邊去！你是我的絆腳石，因為你不體會神的心意，而是體會人的意思。」","notes":[]},{"n":24,"t":"於是耶穌對門徒說：「若有人要跟從我，就當捨己，背起自己的十字架來跟從我。","notes":[]},{"n":25,"t":"因為凡要救自己生命的，要喪失生命；凡為我喪失生命的，要得著生命。","notes":[]},{"n":26,"t":"人若賺得全世界，賠上自己的生命，有甚麼益處呢？人還能拿甚麼換生命呢？","notes":[]},{"n":27,"t":"人子要在他父的榮耀裏與他的眾使者一起來臨，那時候，他要照各人的行為報應各人。","notes":[]},{"n":28,"t":"我實在告訴你們，站在這裏的，有人在沒經歷死亡以前，必定看見人子來到他的國裏。」","notes":[]}]},"17":{"heading":"耶穌登山顯榮","verses":[{"n":1,"t":"過了六天，耶穌帶著彼得、雅各和雅各的弟弟約翰，領他們悄悄地上了高山。","notes":[]},{"n":2,"t":"他在他們面前變了形像，他的臉明亮如太陽，衣裳潔白如光。","notes":[]},{"n":3,"t":"忽然，有摩西和以利亞向他們顯現，與耶穌說話。","notes":[]},{"n":4,"t":"彼得回應，對耶穌說：「主啊，我們在這裏真好！你若願意，我就在這裏搭三座棚，一座為你，一座為摩西 ，一座為以利亞。」","notes":[]},{"n":5,"t":"說話之間，忽然有一朵明亮的雲彩遮蓋他們，又有聲音從雲彩裏出來，說：「這是我的愛子，我所喜愛的。你們要聽從他！」","notes":[]},{"n":6,"t":"門徒聽見，就俯伏在地，極其害怕。","notes":[]},{"n":7,"t":"耶穌進前來，拍拍他們，說：「起來，不要害怕！」","notes":[]},{"n":8,"t":"他們舉目，不見一人，只見耶穌獨自一人。","notes":[]},{"n":9,"t":"下山的時候，耶穌囑咐他們說：「人子還沒有從死人中復活，你們不要把所看到的告訴人。」","notes":[]},{"n":10,"t":"門徒問耶穌：「那麼，文士為甚麼說以利亞必須先來？」","notes":[]},{"n":11,"t":"耶穌回答：「以利亞的確要來，並要復興萬事；","notes":[]},{"n":12,"t":"可是我告訴你們，以利亞已經來了，人不認識他，反倒任意待他。人子也將這樣受他們的苦。」","notes":[]},{"n":13,"t":"門徒這才明白耶穌所說的是指施洗的約翰。","notes":[]},{"n":14,"t":"耶穌和門徒到了眾人那裏，有一個人來見耶穌，跪下，","notes":[],"heads":["治好被鬼附的孩子"]},{"n":15,"t":"說：「主啊，可憐我的兒子。他害癲癇病很苦，屢次跌進火裏，屢次跌進水裏。","notes":[]},{"n":16,"t":"我帶他到你門徒那裏，他們卻不能醫治他。」","notes":[]},{"n":17,"t":"耶穌回答：「唉！這又不信又悖謬的世代啊，我和你們在一起要到幾時呢？我忍耐你們要到幾時呢？把他帶到我這裏來！」","notes":[]},{"n":18,"t":"耶穌斥責那鬼，鬼就出來；從那時起，孩子就痊癒了。","notes":[]},{"n":19,"t":"門徒私下進前來問耶穌：「我們為甚麼不能趕出那鬼呢？」","notes":[]},{"n":20,"t":"耶穌對他們說：「是因你們的信心小。我實在告訴你們，你們若有信心像一粒芥菜種，就是對這座山說：『你從這邊移到那邊』，它也會移過去，並且你們沒有一件不能做的事了。」","notes":["有古卷加「21 至於這一類的鬼，若不禱告禁食，他就不出來。」"]},{"n":22,"t":"他們聚集在加利利的時候，耶穌對門徒說：「人子將要被交在人手裏。","notes":[],"heads":["耶穌第二次預言受難和復活"]},{"n":23,"t":"他們要殺害他，第三天他要復活。」門徒就非常憂愁。","notes":[]},{"n":24,"t":"他們到了迦百農，收聖殿稅的人來見彼得，說：「你們的老師不納聖殿稅嗎？」","notes":["「聖殿稅」：原文是「二德拉克馬」，或譯「丁稅」，即半塊錢；參「度量衡表」。"],"heads":["繳納聖殿稅"]},{"n":25,"t":"彼得說：「納。」他進了屋子，耶穌先對他說：「西門，你的意見如何？世上的君王向誰徵收關稅或丁稅？是向自己的兒子呢？還是向外人呢？」","notes":[]},{"n":26,"t":"彼得說：「是向外人。」耶穌對他說：「既然如此，兒子就可以免了。","notes":[]},{"n":27,"t":"但恐怕觸犯他們，你往海邊去釣魚，把先釣上來的魚拿起來，開了牠的口，會發現一個司塔特，可以拿去給他們，作你我的稅錢。」","notes":["「司塔特」：古羅馬銀幣；參「度量衡表」。"]}]},"18":{"heading":"天國裏誰最大","verses":[{"n":1,"t":"當時，門徒前來問耶穌：「天國裏誰是最大的？」","notes":[]},{"n":2,"t":"耶穌叫一個小孩子來，讓他站在他們當中，","notes":[]},{"n":3,"t":"說：「我實在告訴你們，你們若不回轉，變成像小孩子一樣，絕不能進天國。","notes":[]},{"n":4,"t":"所以，凡自己謙卑像這小孩子的，他在天國裏就是最大的。","notes":[]},{"n":5,"t":"凡為我的名接納一個像這小孩子的，就是接納我。」","notes":[]},{"n":6,"t":"「凡使這些信我的小子中的一個跌倒的，倒不如把大磨石拴在這人的頸項上，沉在深海裏。","notes":[],"heads":["拒絕罪的誘惑"]},{"n":7,"t":"這世界有禍了，因為它使人跌倒；絆倒人的事是免不了的，但那絆倒人的有禍了！","notes":[]},{"n":8,"t":"如果你一隻手或是一隻腳使你跌倒，就把它砍下來扔掉。你缺一隻手或是一隻腳進入永生，比有兩手兩腳被扔進永火裏還好。","notes":[]},{"n":9,"t":"如果你一隻眼使你跌倒，就把它挖出來扔掉。你只有一隻眼進入永生，比有兩隻眼被扔進地獄的火裏還好。」","notes":[]},{"n":10,"t":"「你們要小心，不可輕看這些小子中的一個；我告訴你們，他們的天使在天上，常見我天父的面。","notes":["有古卷加「11 人子來，為要拯救失喪的人。」"],"heads":["迷羊的比喻"]},{"n":12,"t":"「一個人若有一百隻羊，其中一隻走迷了路，你們的意見如何？他豈不留下這九十九隻在山上，去找那隻迷路的羊嗎？","notes":[]},{"n":13,"t":"若是找到了，我實在告訴你們，他為這一隻羊歡喜，比為那沒有迷路的九十九隻歡喜還大呢！","notes":[]},{"n":14,"t":"你們在天上的父也是這樣，不願意失去這些小子中的一個。」","notes":["有古卷是「我」。"]},{"n":15,"t":"「若是你的弟兄得罪你，你要去，趁著只有他和你在一起的時候，指出他的錯來。他若聽你，你就贏得了你的弟兄；","notes":["「得罪你」：有古卷是「犯罪」。"],"heads":["如何對待有過錯的弟兄"]},{"n":16,"t":"他若不聽，你就另外帶一個或兩個人同去，因為『任何指控都要憑兩個或三個證人的口述才能成立』。","notes":[]},{"n":17,"t":"他若是不聽他們，就去告訴教會；若是不聽教會，就把他看作外邦人和稅吏。","notes":[]},{"n":18,"t":"「我實在告訴你們，凡你們在地上所捆綁的，在天上也要捆綁；凡你們在地上所釋放的，在天上也要釋放。","notes":[]},{"n":19,"t":"我又實在告訴你們，若是你們中間有兩個人在地上同心合意地求甚麼事，我在天上的父必為他們成全。","notes":["有古卷沒有「實在」。"]},{"n":20,"t":"因為，哪裏有兩三個人奉我的名聚會，哪裏就有我在他們中間。」","notes":[]},{"n":21,"t":"那時，彼得進前來，對耶穌說：「主啊，我弟兄得罪我，我當饒恕他幾次呢？到七次夠嗎？」","notes":[],"heads":["不饒恕人的惡僕"]},{"n":22,"t":"耶穌說：「我告訴你，不是到七次，而是到七十個七次。","notes":[]},{"n":23,"t":"因為天國好像一個王要和他僕人算賬。","notes":[]},{"n":24,"t":"他開始算的時候，有人帶了一個欠一萬他連得的僕人來。","notes":[]},{"n":25,"t":"因為他沒有甚麼償還之物，主人下令把他和他妻子兒女，以及一切所有的都賣了來償還。","notes":[]},{"n":26,"t":"那僕人就俯伏向他叩頭，說：『寬容我吧，我都會還你的。』","notes":[]},{"n":27,"t":"那僕人的主人就動了慈心，把他釋放了，並且免了他的債。","notes":[]},{"n":28,"t":"那僕人出來，遇見一個欠他一百個銀幣的同伴，就揪著他，扼住他的喉嚨，說：『把你所欠的還我！』","notes":[]},{"n":29,"t":"他的同伴就俯伏央求他，說：『寬容我吧，我會還你的。』","notes":[]},{"n":30,"t":"他不肯，卻把他下在監裏，直到他還了所欠的債。","notes":[]},{"n":31,"t":"同伴們看見他所做的事就很悲憤，把這一切的事都告訴了主人。","notes":[]},{"n":32,"t":"於是主人叫了他來，對他說：『你這惡奴才！你央求我，我就把你所欠的都免了；","notes":[]},{"n":33,"t":"你不應該憐憫你的同伴，像我憐憫你嗎？』","notes":[]},{"n":34,"t":"主人就大怒，把他交給司刑的，直到他還清了所欠的債。","notes":[]},{"n":35,"t":"你們各人若不從心裏饒恕你的弟兄，我天父也要這樣待你們。」","notes":[]}]},"19":{"heading":"休妻的問題","verses":[{"n":1,"t":"耶穌說完了這些話，就離開加利利，來到猶太的境內、約旦河的東邊。","notes":[]},{"n":2,"t":"有一大群人跟著他，他就在那裏治好了他們。","notes":[]},{"n":3,"t":"有些法利賽人來試探耶穌說：「無論甚麼緣故，人休妻都合法嗎？」","notes":[]},{"n":4,"t":"耶穌回答：「那起初造人的，是造男造女，並且說：『因此，人要離開父母，與妻子結合，二人成為一體。』這經文你們沒有念過嗎？","notes":[],"end":5},{"n":6,"t":"既然如此，夫妻不再是兩個人，而是一體的了。所以，神配合的，人不可分開。」","notes":[]},{"n":7,"t":"法利賽人說：「這樣，摩西為甚麼吩咐給妻子休書就可以休她呢？」","notes":[]},{"n":8,"t":"耶穌說：「摩西因為你們的心硬，所以准許你們休妻，但起初並不是這樣。","notes":[]},{"n":9,"t":"我告訴你們，凡休妻另娶的，若不是為不貞的緣故，就是犯姦淫了。」","notes":["有古卷加「有人娶那被休的婦人，也是犯姦淫了。」"]},{"n":10,"t":"門徒對耶穌說：「丈夫和妻子的關係既是這樣，倒不如不娶。」","notes":[]},{"n":11,"t":"耶穌對他們說：「這話不是人人都能領受的，惟獨賜給誰，誰才能領受。","notes":[]},{"n":12,"t":"因為有人從母腹裏就是不宜結婚的，也有因人為的緣故不宜結婚的，並有為天國的緣故自己不結婚的。這話誰能領受，就領受吧。」","notes":["「不宜結婚的」與「不結婚的」：原文直譯「閹人」。"]},{"n":13,"t":"那時，有人帶著小孩子來見耶穌，要他給他們按手禱告，門徒就責備那些人。","notes":[],"heads":["耶穌為小孩祝福"]},{"n":14,"t":"耶穌說：「讓小孩子到我這裏來，不要阻止他們，因為在天國的正是這樣的人。」","notes":[]},{"n":15,"t":"耶穌給他們按手，然後離開那地方。","notes":[]},{"n":16,"t":"有一個人進前來問耶穌：「老師，我該做甚麼善事才能得永生？」","notes":[],"heads":["青年財主尋求永生"]},{"n":17,"t":"耶穌對他說：「你為甚麼問我關於善的事呢？只有一位是善良的。你若要進入永生，就該遵守誡命。」","notes":[]},{"n":18,"t":"他說：「哪些誡命？」耶穌說：「就是不可殺人；不可姦淫；不可偷盜；不可作假見證；","notes":[]},{"n":19,"t":"當孝敬父母；又當愛鄰如己。」","notes":["「鄰」也可譯作「人」。"]},{"n":20,"t":"那青年說：「這一切我都遵守了，還缺少甚麼呢？」","notes":[]},{"n":21,"t":"耶穌說：「你若願意作完全人，去變賣你所擁有的，分給窮人，就必有財寶在天上；然後來跟從我。」","notes":[]},{"n":22,"t":"那青年聽見這話，就憂憂愁愁地走了，因為他的產業很多。","notes":[]},{"n":23,"t":"耶穌對門徒說：「我實在告訴你們，財主進天國是難的。","notes":[]},{"n":24,"t":"我再告訴你們，駱駝穿過針眼比財主進神的國還容易呢！」","notes":[]},{"n":25,"t":"門徒聽見這話，就非常驚奇，說：「這樣，誰能得救呢？」","notes":[]},{"n":26,"t":"耶穌看著他們，說：「在人這是不能，在神凡事都能。」","notes":[]},{"n":27,"t":"於是彼得回應，對他說：「看哪，我們已經撇下一切跟從你了，我們會得到甚麼呢？」","notes":[]},{"n":28,"t":"耶穌對他們說：「我實在告訴你們，你們這些跟從我的人，到了萬物更新、人子坐在他榮耀寶座上的時候，你們也要坐在十二個寶座上，審判以色列十二個支派。","notes":[]},{"n":29,"t":"凡為我的名撇下房屋，或是兄弟、姊妹、父親、母親、兒女、田地的，將得著百倍，並且承受永生。","notes":["有古卷加「妻子」。"]},{"n":30,"t":"然而，有許多在前的，將要在後；在後的，將要在前。」","notes":[]}]},"20":{"heading":"在葡萄園做工的比喻","verses":[{"n":1,"t":"「因為天國好比一家的主人清早去雇人進他的葡萄園做工。","notes":[]},{"n":2,"t":"他和工人講定一天一個銀幣，就打發他們進葡萄園去。","notes":["這是當時一日的工資。"]},{"n":3,"t":"約在上午九點鐘出去，看見市場上還有閒站的人，","notes":[]},{"n":4,"t":"就對那些人說：『你們也進葡萄園去，我會給你們合理的工錢。』","notes":[]},{"n":5,"t":"他們也進去了。約在正午和下午三點鐘又出去，他也是這麼做。","notes":[]},{"n":6,"t":"約在下午五點鐘出去，他看見還有人站在那裏，就問他們：『你們為甚麼整天在這裏閒站呢？』","notes":[]},{"n":7,"t":"他們說：『因為沒有人雇我們。』他說：『你們也進葡萄園去。』","notes":[]},{"n":8,"t":"到了晚上，園主對工頭說：『叫工人都來，給他們工錢，從後來的起，到先來的為止。』","notes":[]},{"n":9,"t":"約在下午五點鐘雇的人來了，各人領了一個銀幣。","notes":[]},{"n":10,"t":"那些最先雇的來了，以為可以多領，誰知也是各領一個銀幣。","notes":[]},{"n":11,"t":"他們領了工錢，就埋怨那家的主人說：","notes":[]},{"n":12,"t":"『我們整天勞苦受熱，那些後來的只做了一小時，你竟待他們和我們一樣嗎？』","notes":[]},{"n":13,"t":"主人回答其中的一人說：『朋友，我沒虧待你，你與我講定的不是一個銀幣嗎？","notes":[]},{"n":14,"t":"拿你的錢走吧！我樂意給那後來的和給你的一樣，","notes":[]},{"n":15,"t":"難道我的東西不可隨我的意思用嗎？因為我作好人，你就眼紅了嗎？』","notes":[]},{"n":16,"t":"這樣，那在後的，將要在前；在前的，將要在後了。」","notes":[]},{"n":17,"t":"耶穌上耶路撒冷去的時候，在路上把十二個門徒帶到一邊，對他們說：","notes":[],"heads":["耶穌第三次預言受難和復活"]},{"n":18,"t":"「看哪，我們上耶路撒冷去，人子將被交給祭司長和文士；他們要定他死罪，","notes":[]},{"n":19,"t":"把他交給外邦人戲弄，鞭打，釘在十字架上；第三天他要復活。」","notes":[]},{"n":20,"t":"那時，西庇太兒子的母親和她兩個兒子上前來，向耶穌叩頭，求他一件事。","notes":[],"heads":["為首與為僕"]},{"n":21,"t":"耶穌問她：「你要甚麼呢？」她對耶穌說：「在你的國裏，請讓我這兩個兒子一個坐在你右邊，一個坐在你左邊。」","notes":[]},{"n":22,"t":"耶穌回答：「你們不知道所求的是甚麼。我將要喝的杯，你們能喝嗎？」他們對他說：「我們能。」","notes":[]},{"n":23,"t":"耶穌說：「我所喝的杯，你們要喝。可是坐在我的左右，不是我可以賜的，而是我父為誰預備就賜給誰。」","notes":[]},{"n":24,"t":"其餘十個門徒聽見，就對他們兄弟二人很生氣。","notes":[]},{"n":25,"t":"耶穌叫了他們來，說：「你們知道，外邦人有君王作主治理他們，有大臣操權管轄他們。","notes":[]},{"n":26,"t":"但是在你們中間，不可這樣。你們中間誰願為大，就要作你們的用人；","notes":[]},{"n":27,"t":"誰願為首，就要作你們的僕人。","notes":[]},{"n":28,"t":"正如人子來，不是要受人的服事，乃是要服事人，並且要捨命，作多人的贖價。」","notes":[]},{"n":29,"t":"他們出耶利哥的時候，有一大群人跟隨耶穌。","notes":[],"heads":["治好兩個盲人"]},{"n":30,"t":"有兩個盲人坐在路旁，聽說是耶穌經過，就喊著說：「主啊，大衛之子，可憐我們吧！」","notes":["有古卷沒有「主啊」；另有古卷是「耶穌啊」。"]},{"n":31,"t":"眾人責備他們，不許他們作聲，他們卻越發喊著說：「主啊，大衛之子，可憐我們吧！」","notes":["有古卷沒有「主啊」。"]},{"n":32,"t":"耶穌就站住，叫他們來，說：「你們要我為你們做甚麼？」","notes":[]},{"n":33,"t":"他們說：「主啊，讓我們的眼睛能看見。」","notes":[]},{"n":34,"t":"耶穌動了慈心，摸了他們的眼睛，他們立刻看得見，就跟從耶穌。","notes":[]}]},"21":{"heading":"榮入聖城","verses":[{"n":1,"t":"耶穌和門徒快到耶路撒冷，進了橄欖山的伯法其時，打發兩個門徒，","notes":[]},{"n":2,"t":"對他們說：「你們往對面村子裏去，會立刻看見一匹驢拴在那裏，還有驢駒同在一處，解開牠們，牽到我這裏來。","notes":[]},{"n":3,"t":"若有人對你們說甚麼，你們就說：『主要用牠們。』那人會立刻讓你們牽來。」","notes":[]},{"n":4,"t":"這事發生是要應驗先知所說的話：","notes":[]},{"n":5,"t":"「要對錫安的兒女說：看哪，你的王來到你這裏，謙和地騎著驢，騎著小驢—驢的駒子。」","notes":["「兒女」：原文直譯「女兒」。"]},{"n":6,"t":"門徒就照耶穌所吩咐的去做，","notes":[]},{"n":7,"t":"牽了驢和驢駒來，把他們的衣服搭在上面，耶穌就騎上。","notes":[]},{"n":8,"t":"許許多多的人把自己的衣服鋪在路上，還有人砍下樹枝來鋪在路上。","notes":[]},{"n":9,"t":"前呼後擁的人群喊著說：「和散那歸於大衛之子！奉主名來的是應當稱頌的！至高無上的，和散那！」","notes":["「和散那」：原是求救的意思，在此是稱頌的話。"]},{"n":10,"t":"耶穌進了耶路撒冷，全城都驚動了，說：「這是誰？」","notes":[]},{"n":11,"t":"眾人說：「這是從加利利的拿撒勒來的先知耶穌。」","notes":[]},{"n":12,"t":"耶穌進了聖殿，趕出聖殿裏所有在做買賣的人，推倒兌換銀錢之人的桌子和賣鴿子之人的凳子，","notes":["「聖殿」：有古卷是「神的殿」。"],"heads":["潔淨聖殿"]},{"n":13,"t":"對他們說：「經上記著：『我的殿要稱為禱告的殿，你們倒使它成為賊窩了。』」","notes":[]},{"n":14,"t":"在聖殿裏有盲人和瘸子到耶穌跟前，他就治好了他們。","notes":[]},{"n":15,"t":"祭司長和文士看見耶穌所行的奇事，又見小孩子在聖殿裏喊著說：「和散那歸於大衛之子！」就很生氣，","notes":[]},{"n":16,"t":"對他說：「這些人所喊的，你聽到了嗎？」耶穌對他們說：「聽到了。經上說：『你藉孩童和吃奶的口發出完全的讚美』，你們沒有念過嗎？」","notes":[]},{"n":17,"t":"於是他離開他們，出城到伯大尼去，在那裏過夜。","notes":[]},{"n":18,"t":"早晨回城的時候，他餓了，","notes":[],"heads":["詛咒無花果樹"]},{"n":19,"t":"看見路旁有一棵無花果樹，就走到跟前，在樹上找不到甚麼，只有葉子，就對樹說：「從今以後，你永不結果子！」那無花果樹立刻枯乾了。","notes":[]},{"n":20,"t":"門徒看見了，驚訝地說：「無花果樹怎麼立刻枯乾了呢？」","notes":[]},{"n":21,"t":"耶穌回答他們：「我實在告訴你們，你們若有信心，不疑惑，不但能行我對無花果樹所行的事，就是對這座山說：『離開此地，投在海裏！』也會實現。","notes":[]},{"n":22,"t":"你們禱告，無論求甚麼，只要信，就必得著。」","notes":[]},{"n":23,"t":"耶穌進了聖殿，正教導人的時候，祭司長和百姓的長老來問他：「你仗著甚麼權柄做這些事？給你這權柄的是誰呢？」","notes":[],"heads":["耶穌的權柄受到質問"]},{"n":24,"t":"耶穌回答他們說：「我也要問你們一句話，你們若告訴我，我就告訴你們我仗著甚麼權柄做這些事。","notes":[]},{"n":25,"t":"約翰的洗禮是從哪裏來的？是從天上來的，還是從人間來的呢？」他們彼此商議說：「我們若說『從天上來的』，他會對我們說：『這樣，你們為甚麼不信他呢？』","notes":[]},{"n":26,"t":"若說『從人間來的』，我們又怕眾人，因為大家都認為約翰是先知。」","notes":[]},{"n":27,"t":"於是他們回答耶穌：「我們不知道。」耶穌也對他們說：「我也不告訴你們，我仗著甚麼權柄做這些事。」","notes":[]},{"n":28,"t":"「有一件事，你們的意見如何？一個人有兩個兒子。他來對大兒子說：『孩子，今天到葡萄園裏做工去。』","notes":[],"heads":["兩個兒子的比喻"]},{"n":29,"t":"他回答：『我不去』，以後自己懊悔，就去了。","notes":[]},{"n":30,"t":"他來對小兒子也是這樣說。他回答：『父親大人，我去』，卻不去。","notes":[]},{"n":31,"t":"這兩個兒子是哪一個照著父親的意願做了呢？」他們說：「大兒子。」耶穌說：「我實在告訴你們，稅吏和娼妓倒比你們先進神的國。","notes":[]},{"n":32,"t":"因為約翰到你們這裏來指引你們走義路，你們卻不信他，稅吏和娼妓倒信了他。你們看見了以後，還是不悔悟去信他。」","notes":[]},{"n":33,"t":"「你們再聽一個比喻：有一個家的主人開墾了一個葡萄園，四周圍上籬笆，裏面挖了一個醡酒池，蓋了一座守望樓，租給園戶，就出外遠行去了。","notes":[],"heads":["惡園戶的比喻"]},{"n":34,"t":"收果子的時候快到了，他打發僕人到園戶那裏去收果子。","notes":[]},{"n":35,"t":"園戶拿住僕人，打了一個，殺了一個，用石頭打死了一個。","notes":[]},{"n":36,"t":"主人又打發別的僕人去，比先前更多；園戶還是照樣對待他們。","notes":[]},{"n":37,"t":"最後他打發自己的兒子到他們那裏去，說：『他們會尊敬我的兒子。』","notes":[]},{"n":38,"t":"可是，園戶看見他兒子，彼此說：『這是承受產業的。來，我們殺了他，佔他的產業！』","notes":[]},{"n":39,"t":"於是他們拿住他，把他扔出葡萄園外，殺了。","notes":[]},{"n":40,"t":"葡萄園的主人來的時候，要怎樣處置那些園戶呢？」","notes":[]},{"n":41,"t":"他們說：「要狠狠地除滅那些惡人，將葡萄園轉租給那些按時候交果子的園戶。」","notes":[]},{"n":42,"t":"耶穌對他們說：「『匠人所丟棄的石頭已作了房角的頭塊石頭。這是主所做的，在我們眼中看為奇妙。』這段經文你們從來沒有念過嗎？","notes":[]},{"n":43,"t":"所以我告訴你們，神的國必從你們奪去，賜給那能結果子的民。","notes":[]},{"n":44,"t":"誰跌在這石頭上，一定會跌得粉碎；這石頭掉在誰的身上，就要把誰壓得稀爛。」","notes":["有古卷沒有44節。"]},{"n":45,"t":"祭司長和法利賽人聽見他的比喻，就看出他是指著他們說的。","notes":[]},{"n":46,"t":"他們想要捉拿他，但是懼怕眾人，因為眾人認為他是先知。","notes":[]}]},"22":{"heading":"喜宴的比喻","verses":[{"n":1,"t":"耶穌又用比喻對他們說：","notes":[]},{"n":2,"t":"「天國好比一個王為他兒子擺設娶親的宴席。","notes":[]},{"n":3,"t":"他打發僕人去，請那些被邀的人來赴宴，他們卻不肯來。","notes":[]},{"n":4,"t":"王又打發別的僕人，說：『你們去告訴那被邀的人，我的宴席已經預備好了，牛和肥畜已經宰了，各樣都齊備，請你們來赴宴。』","notes":[]},{"n":5,"t":"那些人不理就走了，一個到自己田裏去，一個做買賣去。","notes":[]},{"n":6,"t":"其餘的抓住僕人，凌辱他們，把他們殺了。","notes":[]},{"n":7,"t":"王就大怒，發兵除滅那些兇手，燒燬他們的城。","notes":[]},{"n":8,"t":"於是王對僕人說：『喜宴已經齊備，只是所邀的人不配。","notes":[]},{"n":9,"t":"所以你們要往岔路口上去，凡遇見的，都邀來赴宴。』","notes":[]},{"n":10,"t":"那些僕人就出去，到大路上，凡遇見的，不論善惡都招聚了來，宴席上就坐滿了客人。","notes":[]},{"n":11,"t":"王進來見賓客，看到那裏有一個沒有穿禮服的，","notes":[]},{"n":12,"t":"就對他說：『朋友，你到這裏來怎麼不穿禮服呢？』那人無言可答。","notes":[]},{"n":13,"t":"於是王對侍從說：『捆起他的手腳，把他扔在外邊的黑暗裏；在那裏他要哀哭切齒了。』","notes":[]},{"n":14,"t":"因為被召的人多，選上的人少。」","notes":[]},{"n":15,"t":"於是，法利賽人出去商議，怎樣找話柄來陷害耶穌，","notes":[],"heads":["納稅給凱撒的問題"]},{"n":16,"t":"就打發他們的門徒同希律黨人去見耶穌，說：「老師，我們知道你是誠實的，並且誠誠實實傳神的道，無論誰你都一視同仁，因為你不看人的面子。","notes":[]},{"n":17,"t":"請告訴我們，你的意見如何？納稅給凱撒合不合法？」","notes":[]},{"n":18,"t":"耶穌看出他們的惡意，就說：「假冒為善的人哪，為甚麼試探我？","notes":[]},{"n":19,"t":"拿一個納稅的錢給我看！」他們就拿一個銀幣來給他。","notes":[]},{"n":20,"t":"耶穌問他們：「這像和這名號是誰的？」","notes":[]},{"n":21,"t":"他們說：「是凱撒的。」於是耶穌說：「這樣，凱撒的歸凱撒；神的歸神。」","notes":[]},{"n":22,"t":"他們聽了十分驚訝，就離開他走了。","notes":[]},{"n":23,"t":"那天，撒都該人來見耶穌。他們說沒有復活這回事，於是問耶穌：","notes":[],"heads":["復活的問題"]},{"n":24,"t":"「老師，摩西說：『某人若死了，沒有孩子，他弟弟該娶他的妻子，為哥哥生子立後。』","notes":[]},{"n":25,"t":"從前，在我們這裏有兄弟七人，第一個娶了妻，死了，沒有孩子，撇下妻子給弟弟。","notes":[]},{"n":26,"t":"第二、第三，直到第七個，都是如此。","notes":[]},{"n":27,"t":"後來，那婦人也死了。","notes":[]},{"n":28,"t":"那麼，在復活的時候，她是七個人中哪一個的妻子呢？因為他們都娶過她。」","notes":[]},{"n":29,"t":"耶穌回答他們說：「你們錯了，因為不明白聖經，也不知道神的大能。","notes":[]},{"n":30,"t":"在復活的時候，人也不娶也不嫁，而是像天上的天使一樣。","notes":[]},{"n":31,"t":"論到死人復活，神向你們所說的話，你們沒有念過嗎？","notes":[]},{"n":32,"t":"他說：『我是亞伯拉罕的神，以撒的神，雅各的神。』神不是死人的神，而是活人的神。」","notes":[]},{"n":33,"t":"眾人聽見這話，對他的教導非常驚訝。","notes":[]},{"n":34,"t":"法利賽人聽見耶穌堵住了撒都該人的口，他們就聚集在一起。","notes":[],"heads":["最大的誡命"]},{"n":35,"t":"其中有一個人是律法師，要試探耶穌，就問他：","notes":["有古卷沒有「是律法師」。"]},{"n":36,"t":"「老師，律法上的誡命哪一條是最大的呢？」","notes":[]},{"n":37,"t":"耶穌對他說：「你要盡心、盡性、盡意愛主—你的神。","notes":[]},{"n":38,"t":"這是最大的，且是第一條誡命。","notes":[]},{"n":39,"t":"第二條也如此，就是要愛鄰如己。","notes":["「鄰」也可譯作「人」。"]},{"n":40,"t":"這兩條誡命是一切律法和先知書的總綱。」","notes":[]},{"n":41,"t":"法利賽人聚集的時候，耶穌問他們：","notes":[],"heads":["基督與大衛的關係"]},{"n":42,"t":"「論到基督，你們的意見如何？他是誰的後裔呢？」他們說：「是大衛的。」","notes":[]},{"n":43,"t":"耶穌說：「這樣，大衛被聖靈感動，怎麼還稱他為主，說：","notes":[]},{"n":44,"t":"『主對我主說：你坐在我的右邊，等我把你的仇敵放在你腳下？』","notes":[]},{"n":45,"t":"大衛既稱他為主，他怎麼又是大衛的後裔呢？」","notes":[]},{"n":46,"t":"沒有一個人能回答一句話，從那日以後沒有人敢再問他甚麼。","notes":[]}]},"23":{"heading":"譴責文士和法利賽人","verses":[{"n":1,"t":"那時，耶穌對眾人和門徒講論，","notes":[]},{"n":2,"t":"說：「文士和法利賽人坐在摩西的位上，","notes":[]},{"n":3,"t":"所以凡他們所吩咐你們的，你們都要謹守遵行。但不要效法他們的行為，因為他們能說不能行。","notes":[]},{"n":4,"t":"他們把難挑的重擔捆起來，擱在人的肩上，但自己一個指頭也不肯動。","notes":["有古卷沒有「難挑的」。"]},{"n":5,"t":"他們所做的一切事都是要讓人看見，所以把佩戴的經匣加寬了，衣裳的繸子加長了，","notes":["「經匣」是一種經文袋。猶太人在晨禱時，常把裝有經文的皮袋綁在左臂或前額。"]},{"n":6,"t":"喜愛宴席上的首座、會堂裏的高位，","notes":[]},{"n":7,"t":"又喜歡人們在街市上向他們問安，稱呼他們拉比。","notes":["「拉比」意思是「老師」。"]},{"n":8,"t":"但你們不要接受拉比的稱呼，因為只有一位是你們的老師；你們都是弟兄。","notes":[]},{"n":9,"t":"也不要稱呼地上的人為父，因為只有一位是你們的父，就是在天上的父。","notes":[]},{"n":10,"t":"不要接受師傅的稱呼，因為只有一位是你們的師傅，就是基督。","notes":[]},{"n":11,"t":"你們中間誰為大，誰就要作你們的用人。","notes":[]},{"n":12,"t":"凡自高的，必降為卑；自甘卑微的，必升為高。","notes":[]},{"n":13,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們當著人的面把天國的門關了，自己不進去，要進去的人，你們也不容他們進去。","notes":["有古卷加「14 你們這假冒為善的文士和法利賽人有禍了！因為你們侵吞寡婦的家產，假意作很長的禱告，所以要受更重的懲罰。」"]},{"n":15,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們走遍海洋陸地，說服一個人入教，既入了教，卻使他成為比你們加倍壞的地獄之子。","notes":[]},{"n":16,"t":"「你們這瞎眼的嚮導有禍了！你們說：『凡指著聖所起誓的算不得甚麼；但是凡指著聖所中的金子起誓的，他就該謹守。』","notes":[]},{"n":17,"t":"你們這無知的瞎子啊，哪個更大呢？是金子，還是使金子成聖的聖所呢？","notes":[]},{"n":18,"t":"你們又說：『凡指著祭壇起誓的算不得甚麼；但是凡指著壇上祭物起誓的，他就該謹守。』","notes":[]},{"n":19,"t":"你們這些瞎子啊，哪個更大呢？是祭物，還是使祭物成聖的壇呢？","notes":[]},{"n":20,"t":"所以，人指著祭壇起誓，就是指著壇和壇上一切所有的起誓；","notes":[]},{"n":21,"t":"人指著聖所起誓，就是指著聖所和那住在聖所裏的起誓；","notes":[]},{"n":22,"t":"人指著天起誓，就是指著神的寶座和那坐在上面的起誓。","notes":[]},{"n":23,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們將薄荷、大茴香、小茴香獻上十分之一，那律法上更重要的事，就是公義、憐憫、信實，你們反倒不做；這原是你們該做的－至於那些奉獻也不可廢棄。","notes":[]},{"n":24,"t":"你們這瞎眼的嚮導，蠓蟲你們就濾出來，駱駝你們倒吞下去。","notes":[]},{"n":25,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們洗淨杯盤的外面，裏面卻滿了貪婪和放蕩。","notes":[]},{"n":26,"t":"你這瞎眼的法利賽人，先洗淨杯子的裏面，好使外面也乾淨了。","notes":["「杯子」：有古卷是「杯盤」。"]},{"n":27,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們好像粉飾了的墳墓，外面好看，裏面卻滿了死人的骨頭和一切的污穢。","notes":[]},{"n":28,"t":"你們也是如此，外面對人顯出公義，裏面卻滿了虛偽和不法的事。","notes":[]},{"n":29,"t":"「你們這假冒為善的文士和法利賽人有禍了！因為你們建造先知的墳，裝修義人的墓，","notes":[]},{"n":30,"t":"說：『若是我們在先祖的時代，必不和他們一同流先知的血。』","notes":[]},{"n":31,"t":"這樣，你們就證明自己是殺害先知的人的子孫了。","notes":[]},{"n":32,"t":"你們去充滿你們祖宗的惡貫吧！","notes":[]},{"n":33,"t":"你們這些蛇啊，毒蛇的孽種啊，怎能逃脫地獄的懲罰呢？","notes":[]},{"n":34,"t":"所以，我差遣先知、智慧人和文士到你們這裏來，有的你們要殺害，要釘十字架；有的你們要在會堂裏鞭打，從這城追逼到那城，","notes":[]},{"n":35,"t":"如此，地上所有義人流的血都歸到你們身上，從義人亞伯的血起，直到你們在聖所和祭壇中間所殺的巴拉加的兒子撒迦利亞的血為止。","notes":[]},{"n":36,"t":"我實在告訴你們，這一切的罪都要歸到這世代了。」","notes":[]},{"n":37,"t":"「耶路撒冷啊，耶路撒冷啊，你常殺害先知，又用石頭打死那奉差遣到你這裏來的人。我多少次想聚集你的兒女，好像母雞把小雞聚集在翅膀底下，但是你們不願意。","notes":[],"heads":["為耶路撒冷哀哭"]},{"n":38,"t":"看吧，你們的家要被廢棄成為荒蕪。","notes":[]},{"n":39,"t":"我告訴你們，從今以後，你們絕不會再見到我，直到你們說：『奉主名來的是應當稱頌的！』」","notes":[]}]},"24":{"heading":"預言聖殿被毀","verses":[{"n":1,"t":"耶穌出了聖殿，正離開的時候，門徒前來，把聖殿的建築指給他看。","notes":[]},{"n":2,"t":"耶穌回應他們說：「你們不是看見這一切嗎？我實在告訴你們，這裏將沒有一塊石頭會留在另一塊石頭上，而不被拆毀的。」","notes":[]},{"n":3,"t":"耶穌在橄欖山上坐著，門徒私下進前來問他：「請告訴我們，甚麼時候有這些事呢？你來臨和世代的終結有甚麼預兆呢？」","notes":[],"heads":["終局的預兆"]},{"n":4,"t":"耶穌回答他們：「你們要謹慎，免得有人迷惑你們。","notes":[]},{"n":5,"t":"因為將有好些人冒我的名來，說『我是基督』，並且要迷惑許多人。","notes":[]},{"n":6,"t":"你們也將聽見打仗和打仗的風聲。注意，不要驚慌！因為這些事必須發生，但這還不是終結。","notes":[]},{"n":7,"t":"民要攻打民，國要攻打國，多處必有饑荒、地震。","notes":[]},{"n":8,"t":"這都是災難的起頭。","notes":["「災難」：原文直譯「生產的陣痛」。"]},{"n":9,"t":"那時，人要使你們陷在患難裏，也要殺害你們；你們又要為我的名被萬民憎恨。","notes":[]},{"n":10,"t":"那時，會有許多人跌倒，也會彼此陷害，彼此憎恨；","notes":[]},{"n":11,"t":"且有好些假先知起來，迷惑許多人。","notes":[]},{"n":12,"t":"因為不法的事增多，許多人的愛心漸漸冷淡了。","notes":[]},{"n":13,"t":"但堅忍到底的終必得救。","notes":[]},{"n":14,"t":"這天國的福音要傳遍天下，對萬民作見證，然後終結才來到。」","notes":[]},{"n":15,"t":"「當你們看見先知但以理所說的那『施行毀滅的褻瀆者』站在聖地（讀這經的人要會意），","notes":[],"heads":["大災難"]},{"n":16,"t":"那時，在猶太的，應當逃到山上；","notes":[]},{"n":17,"t":"在屋頂上的，不要下來拿家裏的東西；","notes":[]},{"n":18,"t":"在田裏的，不要回去取衣裳。","notes":[]},{"n":19,"t":"在那些日子，懷孕的和奶孩子的就苦了。","notes":[]},{"n":20,"t":"你們要祈求，好讓你們逃走的時候，不遇見冬天或安息日。","notes":[]},{"n":21,"t":"因為那時必有大災難，自從世界的起頭直到如今，從沒有這樣的災難，將來也不會有。","notes":[]},{"n":22,"t":"若不減少那些日子，凡血肉之軀的，就沒有一個能得救；可是為了選民，那些日子將減少。","notes":[]},{"n":23,"t":"那時，若有人對你們說：『看哪，基督在這裏！』或『在那裏！』你們不要信。","notes":[]},{"n":24,"t":"因為假基督和假先知將要起來，顯大神蹟、大奇事，如果可能，要把選民也迷惑了。","notes":[]},{"n":25,"t":"看哪，我已經預先告訴你們了。","notes":[]},{"n":26,"t":"若有人對你們說：『看哪，基督在曠野裏！』你們不要出去；或說：『看哪，基督在內室中！』你們不要信。","notes":[]},{"n":27,"t":"好像閃電從東邊發出，直照到西邊，人子來臨也要這樣。","notes":[]},{"n":28,"t":"屍首在哪裏，鷹也會聚在哪裏。」","notes":[]},{"n":29,"t":"「那些日子的災難一過去，太陽要變黑，月亮也不放光，眾星要從天上墜落，天上的萬象都要震動。","notes":[],"heads":["人子的來臨"]},{"n":30,"t":"那時，人子的預兆要顯在天上，地上的萬族都要哀哭。他們要看見人子帶著能力和大榮耀，駕著天上的雲來臨。","notes":[]},{"n":31,"t":"他要差遣天使，用大聲的號筒，從四方，從天這邊直到天那邊，召集他的選民。」","notes":[]},{"n":32,"t":"「你們要從無花果樹學習功課：當樹枝發芽長葉的時候，你們就知道夏天近了。","notes":[],"heads":["從無花果樹學功課"]},{"n":33,"t":"同樣，當你們看見這一切，就知道那時候近了，就在門口了。","notes":[]},{"n":34,"t":"我實在告訴你們，這世代還沒有過去，這一切都要發生。","notes":[]},{"n":35,"t":"天地要廢去，我的話卻絕不廢去。」","notes":[]},{"n":36,"t":"「但那日子，那時辰，沒有人知道，連天上的天使也不知道，子也不知道，惟有父知道。","notes":[],"heads":["那日那時沒有人知道"]},{"n":37,"t":"挪亞的日子怎樣，人子來臨也要怎樣。","notes":[]},{"n":38,"t":"在洪水以前的那些日子，人照常吃喝嫁娶，直到挪亞進方舟的那日，","notes":[]},{"n":39,"t":"不知不覺洪水來了，把他們全都沖去。人子來臨也要這樣。","notes":[]},{"n":40,"t":"那時，兩個人在田裏，一個被接去，一個被撇下。","notes":[]},{"n":41,"t":"兩個女人推磨，一個被接去，一個被撇下。","notes":[]},{"n":42,"t":"所以，你們要警醒，因為不知道你們的主哪一天來到。","notes":[]},{"n":43,"t":"你們要知道，一家的主人若知道晚上甚麼時候有賊來，就必警醒，不讓賊挖穿房屋。","notes":[]},{"n":44,"t":"所以，你們也要預備，因為在你們想不到的時候，人子就來了。」","notes":[]},{"n":45,"t":"「那麼，誰是那忠心又精明的僕人，主人派他管理自己的家僕、按時分糧給他們的呢？","notes":[],"heads":["忠心和不忠心的僕人"]},{"n":46,"t":"主人來到，看見僕人這樣做，那僕人就有福了。","notes":[]},{"n":47,"t":"我實在告訴你們，主人要派他管理所有的財產。","notes":[]},{"n":48,"t":"如果那惡僕心裏說：『我的主人會來得遲』，","notes":[]},{"n":49,"t":"就動手打他的同伴，又和醉酒的人一同吃喝，","notes":[]},{"n":50,"t":"在想不到的日子，不知道的時候，那僕人的主人要來，","notes":[]},{"n":51,"t":"重重地懲罰他，定他和假冒為善的人同罪，在那裏他要哀哭切齒了。」","notes":["「重重地懲罰他」或譯「把他腰斬了」。"]}]},"25":{"heading":"十童女的比喻","verses":[{"n":1,"t":"「那時，天國好比十個童女拿著燈出去迎接新郎。","notes":[]},{"n":2,"t":"其中有五個是愚拙的，五個是聰明的。","notes":[]},{"n":3,"t":"愚拙的拿著燈，卻沒有帶油；","notes":[]},{"n":4,"t":"聰明的拿著燈，又盛了油在器皿裏。","notes":[]},{"n":5,"t":"新郎遲延的時候，她們都打盹，睡著了。","notes":[]},{"n":6,"t":"半夜有人喊：『看，新郎來了，你們出來迎接他。』","notes":[]},{"n":7,"t":"那些童女就都起來挑亮她們的燈。","notes":[]},{"n":8,"t":"愚拙的對聰明的說：『請分點油給我們，因為我們的燈要滅了。』","notes":[]},{"n":9,"t":"聰明的回答：『恐怕不夠你我用的；你們還是自己到賣油的那裏去買吧。』","notes":[]},{"n":10,"t":"她們去買的時候，新郎到了。那預備好了的，與他進去共赴婚宴，門就關了。","notes":[]},{"n":11,"t":"其餘的童女隨後也來了，說：『主啊，主啊，給我們開門！』","notes":[]},{"n":12,"t":"他卻回答：『我實在告訴你們，我不認識你們。』","notes":[]},{"n":13,"t":"所以，你們要警醒，因為那日子，那時辰，你們不知道。」","notes":[]},{"n":14,"t":"「天國又好比一個人要出外遠行，就叫了僕人來，把他的家業交給他們。","notes":[],"heads":["按才受託的比喻"]},{"n":15,"t":"他按著各人的才幹，給他們銀子：一個給了五千，一個給了二千，一個給了一千，就出外遠行去了。","notes":["「五千」：原文直譯「五個他連得」；16、20節同。","「二千」：原文直譯「二個他連得」；17、22節同。","「一千」：原文直譯「一個他連得」；18、24、25、28節同。"]},{"n":16,"t":"那領五千的立刻拿去做買賣，另外賺了五千。","notes":[]},{"n":17,"t":"那領二千的也照樣另賺了二千。","notes":[]},{"n":18,"t":"但那領一千的去掘開地，把主人的銀子埋藏了。","notes":[]},{"n":19,"t":"過了許久，那些僕人的主人來了，和他們算賬。","notes":[]},{"n":20,"t":"那領五千的又帶著另外的五千來，說：『主啊，你交給我五千。請看，我又賺了五千。』","notes":[]},{"n":21,"t":"主人說：『好，你這又善良又忠心的僕人，你在少許的事上忠心，我要派你管理許多的事，進來享受你主人的快樂吧！』","notes":[]},{"n":22,"t":"那領二千的也進前來，說：『主啊，你交給我二千。請看，我又賺了二千。』","notes":[]},{"n":23,"t":"主人說：『好，你這又善良又忠心的僕人，你在少許的事上忠心，我要派你管理許多的事，進來享受你主人的快樂吧！』","notes":[]},{"n":24,"t":"那領一千的也進前來，說：『主啊，我知道你，你是個嚴厲的人：沒有種的地方也要收割，沒有播的地方也要收穫，","notes":[]},{"n":25,"t":"我就害怕，去把你的一千銀子埋藏在地裏。請看，你的銀子在這裏。』","notes":[]},{"n":26,"t":"他的主人回答他說：『你這又惡又懶的僕人，你既知道我沒有種的地方也要收割，沒有播的地方也要收穫，","notes":[]},{"n":27,"t":"就該把我的銀子放給兌換銀錢的人，到我來的時候可以連本帶利收回。","notes":[]},{"n":28,"t":"把他這一千奪過來，給那有一萬的。","notes":["「一萬」：原文直譯「十個他連得」。"]},{"n":29,"t":"因為凡有的，還要加給他，叫他有餘；沒有的，連他所有的也要奪過來。","notes":[]},{"n":30,"t":"把這無用的僕人丟在外面黑暗裏，在那裏他要哀哭切齒了。』」","notes":[]},{"n":31,"t":"「當人子在他榮耀裏，同著眾天使來臨的時候，要坐在他榮耀的寶座上。","notes":[],"heads":["萬民受審判"]},{"n":32,"t":"萬民都要聚集在他面前。他要把他們分別出來，好像牧人分別綿羊、山羊一般，","notes":[]},{"n":33,"t":"把綿羊安置在右邊，山羊在左邊。","notes":[]},{"n":34,"t":"於是王要向他右邊的說：『你們這蒙我父賜福的，可來承受那創世以來為你們所預備的國。","notes":[]},{"n":35,"t":"因為我餓了，你們給我吃；渴了，你們給我喝；我流浪在外，你們留我住；","notes":[]},{"n":36,"t":"我赤身露體，你們給我穿；我病了，你們看顧我；我在監獄裏，你們來看我。』","notes":[]},{"n":37,"t":"義人就回答：『主啊，我們甚麼時候見你餓了，給你吃；渴了，給你喝？","notes":[]},{"n":38,"t":"甚麼時候見你流浪在外，留你住；或是赤身露體，給你穿？","notes":[]},{"n":39,"t":"又甚麼時候見你病了，或是在監獄裏，來看你呢？』","notes":[]},{"n":40,"t":"王回答他們說：『我實在告訴你們，這些事你們做在我弟兄中一個最小的身上，就是做在我身上了。』","notes":[]},{"n":41,"t":"「王又要向那左邊的說：『你們這被詛咒的人，離開我！進入那為魔鬼和他的使者所預備的永火裏去！","notes":[]},{"n":42,"t":"因為我餓了，你們沒有給我吃；渴了，你們沒有給我喝；","notes":[]},{"n":43,"t":"我流浪在外，你們沒有留我住；我赤身露體，你們沒有給我穿；我病了，我在監獄裏，你們沒有來看顧我。』","notes":[]},{"n":44,"t":"他們也要回答：『主啊，我們甚麼時候見你餓了，或渴了，或流浪在外，或赤身露體，或病了，或在監獄裏，沒有伺候你呢？』","notes":[]},{"n":45,"t":"王要回答：『我實在告訴你們，這些事你們沒有做在任何一個最小的弟兄身上，就是沒有做在我身上了。』","notes":[]},{"n":46,"t":"這些人要往永刑裏去；那些義人要往永生裏去。」","notes":[]}]},"26":{"heading":"殺害耶穌的陰謀","verses":[{"n":1,"t":"耶穌說完了這一切的話，就對門徒說：","notes":[]},{"n":2,"t":"「你們知道，過兩天是逾越節，人子將要被出賣，釘在十字架上。」","notes":[]},{"n":3,"t":"那時，祭司長和百姓的長老聚集在那稱為該亞法的大祭司的院裏。","notes":[]},{"n":4,"t":"大家商議要設計捉拿耶穌，把他殺掉。","notes":[]},{"n":5,"t":"可是他們說：「不可在過節的日子，恐怕百姓生亂。」","notes":[]},{"n":6,"t":"耶穌在伯大尼的痲瘋病人西門家裏，","notes":[],"heads":["在伯大尼受膏"]},{"n":7,"t":"有一個女人拿著一玉瓶極貴的香膏來，趁耶穌坐席的時候，澆在他的頭上。","notes":[]},{"n":8,"t":"門徒看見就很不高興，說：「何必這樣浪費呢！","notes":[]},{"n":9,"t":"這香膏可以賣許多錢，賙濟窮人。」","notes":[]},{"n":10,"t":"耶穌看出他們的意思，就說：「為甚麼難為這女人呢？她在我身上做的是一件美事。","notes":[]},{"n":11,"t":"因為常有窮人和你們在一起，但是你們不常有我。","notes":[]},{"n":12,"t":"她把這香膏澆在我身上是為我安葬作準備的。","notes":[]},{"n":13,"t":"我實在告訴你們，普天之下，無論在甚麼地方傳這福音，都要述說這女人所做的，來記念她。」","notes":[]},{"n":14,"t":"當時，十二使徒中有一個叫加略人猶大的，去見祭司長，","notes":[],"heads":["猶大出賣耶穌"]},{"n":15,"t":"說：「我把他交給你們，你們願意給我多少錢？」他們給了他三十塊銀錢。","notes":[]},{"n":16,"t":"從那時候起，他就找機會要把耶穌交給他們。","notes":[]},{"n":17,"t":"除酵節的第一天，門徒來問耶穌：「你要我們在哪裏給你預備吃逾越節的宴席呢？」","notes":[],"heads":["與門徒同守逾越節"]},{"n":18,"t":"耶穌說：「你們進城去，到某人那裏，對他說：『老師說：我的時候快到了，我要和我的門徒在你家裏守逾越節。』」","notes":[]},{"n":19,"t":"門徒遵照耶穌所吩咐的去預備了逾越節的宴席。","notes":[]},{"n":20,"t":"到了晚上，耶穌和十二使徒坐席。","notes":[]},{"n":21,"t":"他們吃的時候，耶穌說：「我實在告訴你們，你們中間有一個人要出賣我。」","notes":[]},{"n":22,"t":"他們就非常憂愁，一個一個地問他：「主，該不是我吧？」","notes":[]},{"n":23,"t":"耶穌回答說：「同我蘸手在盤子裏的，就是要出賣我的。","notes":[]},{"n":24,"t":"人子要去了，正如經上所寫有關他的；但出賣人子的人有禍了！那人沒有出生倒好。」","notes":[]},{"n":25,"t":"出賣耶穌的猶大回答他說：「拉比，該不是我吧？」耶穌說：「你自己說了。」","notes":[]},{"n":26,"t":"他們吃的時候，耶穌拿起餅來，祝福了，就擘開，遞給門徒，說：「你們拿去，吃吧。這是我的身體。」","notes":[],"heads":["設立主的晚餐"]},{"n":27,"t":"他又拿起杯來，祝謝了，遞給他們，說：「你們都喝這個，","notes":[]},{"n":28,"t":"因為這是我立約的血，為許多人流出來，使罪得赦。","notes":[]},{"n":29,"t":"但我告訴你們，從今以後，我不再喝這葡萄汁，直到我在我父的國裏與你們同喝新的那日子。」","notes":[]},{"n":30,"t":"他們唱了詩，就出來往橄欖山去。","notes":[]},{"n":31,"t":"那時，耶穌對他們說：「今夜，你們為我的緣故都要跌倒。因為經上記著：『我要擊打牧人，羊就分散了。』","notes":[],"heads":["預言彼得不認主"]},{"n":32,"t":"但我復活以後，要在你們之前往加利利去。」","notes":[]},{"n":33,"t":"彼得回答他說：「即使眾人為你的緣故跌倒，我也絕不跌倒。」","notes":[]},{"n":34,"t":"耶穌說：「我實在告訴你，今夜雞叫以前，你要三次不認我。」","notes":[]},{"n":35,"t":"彼得說：「我就是必須和你同死，也絕不會不認你。」所有的門徒都是這樣說。","notes":[]},{"n":36,"t":"耶穌和門徒來到一個地方，名叫客西馬尼。他對他們說：「你們坐在這裏，我到那邊去禱告。」","notes":[],"heads":["在客西馬尼禱告"]},{"n":37,"t":"於是他帶著彼得和西庇太的兩個兒子同去。他憂愁起來，極其難過，","notes":[]},{"n":38,"t":"就對他們說：「我心裏非常憂傷，幾乎要死；你們留在這裏，和我一同警醒。」","notes":[]},{"n":39,"t":"他就稍往前走，俯伏在地，禱告說：「我父啊，如果可能，求你使這杯離開我。然而，不是照我所願的，而是照你所願的。」","notes":[]},{"n":40,"t":"他回到門徒那裏，見他們睡著了，就對彼得說：「怎麼樣？你們不能同我警醒一小時嗎？","notes":[]},{"n":41,"t":"總要警醒禱告，免得陷入試探。你們心靈固然願意，肉體卻軟弱了。」","notes":[]},{"n":42,"t":"他第二次又去禱告說：「我父啊，這杯若不能離開我，必須我喝，就願你的旨意成全。」","notes":[]},{"n":43,"t":"他又來，見他們睡著了，因為他們的眼睛困倦。","notes":[]},{"n":44,"t":"耶穌又離開他們，第三次去禱告，說的話跟先前一樣。","notes":[]},{"n":45,"t":"然後他來到門徒那裏，對他們說：「現在你們仍在睡覺安歇嗎？看哪，時候到了，人子被出賣在罪人手裏了。","notes":[]},{"n":46,"t":"起來，我們走吧！看哪，那出賣我的人快來了。」","notes":[]},{"n":47,"t":"耶穌還在說話的時候，十二使徒之一的猶大來了，還有一大群人帶著刀棒，從祭司長和百姓的長老那裏跟他同來。","notes":[],"heads":["耶穌被捕"]},{"n":48,"t":"那出賣耶穌的給了他們一個暗號，說：「我親誰，誰就是。你們把他抓住。」","notes":[]},{"n":49,"t":"猶大立刻進前來對耶穌說：「拉比，你好！」就跟他親吻。","notes":[]},{"n":50,"t":"耶穌對他說：「朋友，你來要做的事，就做吧。」於是那些人上前，下手抓住耶穌。","notes":["「你來要做的事，就做吧。」或譯「你來做甚麼？」"]},{"n":51,"t":"忽然，有一個和耶穌一起的人伸手拔出刀來，把大祭司的僕人砍了一刀，削掉了他一隻耳朵。","notes":[]},{"n":52,"t":"耶穌對他說：「收刀入鞘吧！凡動刀的，必死在刀下。","notes":[]},{"n":53,"t":"你想我不能求我父，現在為我差遣比十二營還多的天使來嗎？","notes":[]},{"n":54,"t":"若是這樣，經上所說事情必須如此發生的話怎麼應驗呢？」","notes":[]},{"n":55,"t":"就在那時，耶穌對眾人說：「你們帶著刀棒出來抓我，如同拿強盜嗎？我天天坐在聖殿裏教導人，你們並沒有抓我。","notes":[]},{"n":56,"t":"但這整件事的發生，是要應驗先知書上的話。」那時，門徒都離開他，逃走了。","notes":[]},{"n":57,"t":"抓耶穌的人把他帶到大祭司該亞法那裏去，文士和長老已經在那裏聚集。","notes":[],"heads":["耶穌在議會受審"]},{"n":58,"t":"彼得遠遠地跟著耶穌，直到大祭司的院子，進到裏面，就和警衛同坐，要看結局怎樣。","notes":[]},{"n":59,"t":"祭司長和全議會尋找假見證控告耶穌，要處死他。","notes":[]},{"n":60,"t":"雖然有好些人來作假見證，總找不到實據。最後有兩個人前來，","notes":[]},{"n":61,"t":"說：「這個人曾說：『我能拆毀神的殿，三日內又建造起來。』」","notes":[]},{"n":62,"t":"大祭司就站起來，對耶穌說：「這些人作證告你的事，你甚麼都不回答嗎？」","notes":[]},{"n":63,"t":"耶穌卻不言語。大祭司對他說：「我指著永生神命令你起誓告訴我們，你是不是基督—神的兒子？」","notes":[]},{"n":64,"t":"耶穌對他說：「你自己說了。然而，我告訴你們，此後你們要看見人子坐在權能者的右邊，駕著天上的雲來臨。」","notes":[]},{"n":65,"t":"大祭司就撕裂衣服，說：「他說了褻瀆的話，我們何必再要證人呢？現在你們已經聽見他這褻瀆的話了。","notes":[]},{"n":66,"t":"你們的意見如何？」他們回答：「他該處死。」","notes":[]},{"n":67,"t":"他們就吐唾沫在他臉上，用拳頭打他，也有打他耳光的，","notes":[]},{"n":68,"t":"說：「基督啊，向我們說預言吧！打你的是誰？」","notes":[]},{"n":69,"t":"彼得在外面院子裏坐著，有一個使女前來，說：「你素來也是同那加利利人耶穌一起的。」","notes":[],"heads":["彼得三次不認主"]},{"n":70,"t":"彼得在眾人面前卻不承認，說：「我不知道你說的是甚麼！」","notes":[]},{"n":71,"t":"他出去，到了門口，又有一個使女看見他，就對那裏的人說：「這個人是同拿撒勒人耶穌一起的。」","notes":[]},{"n":72,"t":"彼得又不承認，起誓說：「我不認得那個人。」","notes":[]},{"n":73,"t":"過了不久，旁邊站著的人進前來，對彼得說：「你的確是他們一夥的，你的口音把你顯露出來了。」","notes":[]},{"n":74,"t":"彼得就賭咒發誓說：「我不認得那個人。」立刻雞就叫了。","notes":[]},{"n":75,"t":"彼得想起耶穌所說的話：「雞叫以前，你要三次不認我。」他就出去痛哭。","notes":[]}]},"27":{"heading":"耶穌被解送給彼拉多","verses":[{"n":1,"t":"到了早晨，眾祭司長和百姓的長老商議要處死耶穌，","notes":[]},{"n":2,"t":"就把他綁著，解去，交給彼拉多總督。","notes":[]},{"n":3,"t":"這時，出賣耶穌的猶大看見耶穌已經定了罪，就後悔，把那三十塊銀錢拿回來給祭司長和長老，","notes":[],"heads":["猶大之死"]},{"n":4,"t":"說：「我出賣了無辜人的血有罪了。」他們說：「那跟我們有甚麼相干？你自己承當吧！」","notes":[]},{"n":5,"t":"猶大就把那銀錢丟在殿裏，出去吊死了。","notes":[]},{"n":6,"t":"祭司長拾起銀錢來，說：「這是血價，不可放在聖殿的銀庫裏。」","notes":[]},{"n":7,"t":"他們商議，就用那銀錢買了窯戶的一塊田，用來埋葬外鄉人。","notes":[]},{"n":8,"t":"所以，那塊田直到今日還叫做「血田」。","notes":[]},{"n":9,"t":"這就應驗了先知耶利米所說的話：「他們用那三十塊銀錢，就是以色列人給那被估定的人所估定的價錢，","notes":[]},{"n":10,"t":"買了窯戶的一塊田；這是照著主所吩咐我的。」","notes":[]},{"n":11,"t":"耶穌站在總督面前，總督問他：「你是猶太人的王嗎？」耶穌說：「是你說的。」","notes":[],"heads":["耶穌在彼拉多面前受審"]},{"n":12,"t":"他被祭司長和長老控告的時候，甚麼都不回答。","notes":[]},{"n":13,"t":"彼拉多就對他說：「他們作證告你這麼多的事，你沒有聽見嗎？」","notes":[]},{"n":14,"t":"耶穌仍不回答，連一句話也不說，以致總督覺得非常驚訝。","notes":[]},{"n":15,"t":"總督有一個常例，每逢這節期，隨眾人的意願釋放一個囚犯給他們。","notes":[],"heads":["耶穌被判死刑"]},{"n":16,"t":"當時有一個出名的囚犯叫巴拉巴。","notes":["有古卷是「耶穌‧巴拉巴」；17節同。"]},{"n":17,"t":"眾人聚集的時候，彼拉多就對他們說：「你們要我釋放哪一個給你們？是巴拉巴呢？是稱為基督的耶穌呢？」","notes":[]},{"n":18,"t":"總督原知道他們是因為嫉妒才把他解了來。","notes":[]},{"n":19,"t":"正坐堂的時候，他的夫人打發人來說：「這義人的事，你一點不可管，因為我今天在夢中因他受了許多的苦。」","notes":[]},{"n":20,"t":"祭司長和長老挑唆眾人，要求釋放巴拉巴，除掉耶穌。","notes":[]},{"n":21,"t":"總督回答他們說：「這兩個人，你們要我釋放哪一個給你們呢？」他們說：「巴拉巴。」","notes":[]},{"n":22,"t":"彼拉多說：「這樣，那稱為基督的耶穌我怎麼辦他呢？」他們都說：「把他釘十字架！」","notes":[]},{"n":23,"t":"總督說：「為甚麼？他做了甚麼惡事呢？」他們更加喊著說：「把他釘十字架！」","notes":[]},{"n":24,"t":"彼拉多見說也無濟於事，反要生亂，就拿水在眾人面前洗手，說：「流這人的血，罪不在我，你們承當吧。」","notes":["「人」：有古卷是「義人」。"]},{"n":25,"t":"眾人都回答：「他的血歸到我們和我們的子孫身上！」","notes":[]},{"n":26,"t":"於是彼拉多釋放巴拉巴給他們，把耶穌鞭打後交給人釘十字架。","notes":[]},{"n":27,"t":"總督的兵把耶穌帶進總督府，把全營的兵都聚集在耶穌那裏。","notes":[],"heads":["士兵戲弄耶穌"]},{"n":28,"t":"他們脫了他的衣服，穿上一件朱紅色的袍子，","notes":[]},{"n":29,"t":"用荊棘編了冠冕，戴在他頭上，拿一根蘆葦稈放在他右手裏，跪在他面前，戲弄他，說：「萬歲，猶太人的王！」","notes":[]},{"n":30,"t":"他們又向他吐唾沫，拿蘆葦稈打他的頭。","notes":[]},{"n":31,"t":"他們戲弄完了，就給他脫了袍子，又穿上他自己的衣服，帶他出去，要釘十字架。","notes":[]},{"n":32,"t":"他們出去的時候，遇見一個古利奈人，名叫西門，就強迫他同去，好背耶穌的十字架。","notes":[],"heads":["耶穌被釘十字架"]},{"n":33,"t":"他們到了一個地方，名叫各各他，就是「髑髏地」。","notes":[]},{"n":34,"t":"士兵拿苦膽調和的酒給耶穌喝。他嘗了，不肯喝。","notes":[]},{"n":35,"t":"他們把他釘在十字架上，然後抽籤分了他的衣服，","notes":[]},{"n":36,"t":"又坐在那裏看守他。","notes":[]},{"n":37,"t":"他們在他頭上方安了一個罪狀牌，寫著：「這是猶太人的王耶穌。」","notes":[]},{"n":38,"t":"當時，有兩個強盜和他同釘十字架，一個在右邊，一個在左邊。","notes":[]},{"n":39,"t":"從那裏經過的人譏笑他，搖著頭，","notes":[]},{"n":40,"t":"說：「你這拆毀殿、三日又建造起來的，救救你自己吧！如果你是神的兒子，就從十字架上下來呀！」","notes":[]},{"n":41,"t":"眾祭司長、文士和長老也同樣嘲笑他，說：","notes":[]},{"n":42,"t":"「他救了別人，不能救自己。他是以色列的王，現在從十字架上下來，我們就信他。","notes":[]},{"n":43,"t":"他倚靠神，神若願意，現在就來救他，因為他曾說『我是神的兒子』。」","notes":[]},{"n":44,"t":"和他同釘的強盜也這樣譏諷他。","notes":[]},{"n":45,"t":"從正午到下午三點鐘，遍地都黑暗了。","notes":[],"heads":["耶穌之死"]},{"n":46,"t":"約在下午三點鐘，耶穌大聲高呼，說：「以利！以利！拉馬撒巴各大尼？」就是說：「我的神！我的神！為甚麼離棄我？」","notes":[]},{"n":47,"t":"站在那裏的人，有的聽見就說：「這個人呼叫以利亞呢！」","notes":[]},{"n":48,"t":"其中有一個人立刻跑去，拿海綿蘸滿了醋，綁在蘆葦稈上，送給他喝。","notes":[]},{"n":49,"t":"其餘的人說：「且等著，看以利亞來不來救他。」","notes":[]},{"n":50,"t":"耶穌又大喊一聲，氣就斷了。","notes":[]},{"n":51,"t":"忽然，殿的幔子從上到下裂為兩半，地震動，磐石崩裂，","notes":[]},{"n":52,"t":"墳墓也開了，有許多已睡了的聖徒的身體也復活了。","notes":[]},{"n":53,"t":"耶穌復活以後，他們從墳墓裏出來，進了聖城，向許多人顯現。","notes":[]},{"n":54,"t":"百夫長和跟他一同看守耶穌的人看見地震和所經歷的事，非常害怕，說：「他真是神的兒子！」","notes":[]},{"n":55,"t":"有好些婦女在那裏，遠遠地觀看，她們是從加利利跟隨耶穌，來服事他的；","notes":[]},{"n":56,"t":"其中有抹大拉的馬利亞，又有雅各和約瑟的母親馬利亞，並有西庇太兩個兒子的母親。","notes":[]},{"n":57,"t":"到了晚上，有一個財主，名叫約瑟，是亞利馬太來的，他也是耶穌的門徒。","notes":[],"heads":["耶穌的安葬"]},{"n":58,"t":"這人去見彼拉多，請求要耶穌的身體，彼拉多就吩咐給他。","notes":[]},{"n":59,"t":"約瑟取了身體，用乾淨的細麻布裹好，","notes":[]},{"n":60,"t":"然後把他安放在自己的新墓穴裏，就是他鑿在巖石裏的。他又把大石頭滾到墓門口，然後離開。","notes":[]},{"n":61,"t":"有抹大拉的馬利亞和另一個馬利亞在那裏，對著墳墓坐著。","notes":[]},{"n":62,"t":"次日，就是預備日的第二天，祭司長和法利賽人聚集來見彼拉多，","notes":[],"heads":["封石妥守"]},{"n":63,"t":"說：「大人，我們記得那迷惑人的還活著的時候曾說：『三天後我要復活。』","notes":[]},{"n":64,"t":"因此，請吩咐人將墳墓把守妥當，直到第三天，恐怕他的門徒來把他偷了去，就告訴百姓說：『他從死人中復活了。』這樣的話，那後來的迷惑就比先前的更厲害了。」","notes":[]},{"n":65,"t":"彼拉多說：「你們有看守的兵，去吧！盡你們所能的把守妥當。」","notes":[]},{"n":66,"t":"他們就帶著看守的兵同去，封了石頭，將墳墓把守妥當。","notes":[]}]},"28":{"heading":"耶穌復活","verses":[{"n":1,"t":"安息日過後，七日的第一日，天快亮的時候，抹大拉的馬利亞和另一個馬利亞來看墳墓。","notes":[]},{"n":2,"t":"忽然，地大震動；因為有主的一個使者從天上下來，把石頭滾開，坐在上面。","notes":[]},{"n":3,"t":"他的相貌如同閃電，衣服潔白如雪。","notes":[]},{"n":4,"t":"看守的人嚇得渾身顫抖，甚至和死人一樣。","notes":[]},{"n":5,"t":"天使回應婦女說：「不要害怕！我知道你們是尋找那釘十字架的耶穌。","notes":[]},{"n":6,"t":"他不在這裏，照他所說的，他已經復活了。你們來！看看安放他的地方。","notes":[]},{"n":7,"t":"快去告訴他的門徒，說他已從死人中復活了，並且要比你們先到加利利去，在那裏你們會看見他。看哪！我已經告訴你們了。」","notes":[]},{"n":8,"t":"婦女們急忙離開墳墓，又害怕，又大為歡喜，跑去告訴他的門徒。","notes":[]},{"n":9,"t":"忽然，耶穌迎上她們，說：「平安！」她們就上前抱住他的腳拜他。","notes":[]},{"n":10,"t":"耶穌對她們說：「不要害怕！你們去告訴我的弟兄，叫他們往加利利去，在那裏會見到我。」","notes":[]},{"n":11,"t":"她們去的時候，看守的兵有幾個進城去，把所發生的事都報告祭司長。","notes":[],"heads":["祭司長捏造謊言"]},{"n":12,"t":"祭司長和長老聚集商議，就拿許多銀錢給士兵，","notes":[]},{"n":13,"t":"說：「你們要這樣說：『夜間我們睡覺的時候，他的門徒來把他偷去了。』","notes":[]},{"n":14,"t":"若是這話被總督聽見，有我們勸他，保你們無事。」","notes":[]},{"n":15,"t":"士兵收了銀錢，就照所囑咐他們的去做。這話就在猶太人中間流傳，直到今日。","notes":[]},{"n":16,"t":"十一個門徒往加利利去，到了耶穌指定他們去的山上。","notes":[],"heads":["門徒奉差遣"]},{"n":17,"t":"他們見了耶穌就拜他，然而還有人疑惑。","notes":[]},{"n":18,"t":"耶穌進前來，對他們說：「天上地下所有的權柄都賜給我了。","notes":[]},{"n":19,"t":"所以，你們要去，使萬民作我的門徒，奉父、子、聖靈的名給他們施洗，","notes":["「奉父、子、聖靈的名給他們施洗」或譯「給他們施洗，歸於父、子、聖靈的名」。"]},{"n":20,"t":"凡我所吩咐你們的，都教導他們遵守。看哪，我天天與你們同在，直到世代的終結。」","notes":[]}]}},"MRK":{"1":{"heading":"施洗約翰傳道","verses":[{"n":1,"t":"神的兒子，耶穌基督福音的起頭。","notes":["有古卷沒有「神的兒子」。"]},{"n":2,"t":"正如以賽亞先知書上記著：「看哪，我要差遣我的使者在你面前，他要為你預備道路。","notes":[]},{"n":3,"t":"在曠野有聲音呼喊著：預備主的道，修直他的路。」","notes":[]},{"n":4,"t":"照這話，施洗約翰來到曠野，宣講悔改的洗禮，使罪得赦。","notes":["有古卷是「約翰來了，在曠野施洗」。"]},{"n":5,"t":"猶太全地和全耶路撒冷的人都出去，到約翰那裏，承認他們的罪，在約旦河裏受他的洗。","notes":[]},{"n":6,"t":"約翰穿駱駝毛的衣服，腰束皮帶，吃的是蝗蟲和野蜜。","notes":[]},{"n":7,"t":"他宣講，說：「有一位在我以後來的，能力比我更大，我就是彎腰給他解鞋帶也不配。","notes":[]},{"n":8,"t":"我用水給你們施洗，他卻要用聖靈給你們施洗。」","notes":[]},{"n":9,"t":"那時，耶穌從加利利的拿撒勒來，在約旦河裏受了約翰的洗。","notes":[],"heads":["耶穌受洗"]},{"n":10,"t":"他從水裏一上來，就看見天裂開了，聖靈彷彿鴿子降在他身上。","notes":[]},{"n":11,"t":"又有聲音從天上來，說：「你是我的愛子，我喜愛你。」","notes":[]},{"n":12,"t":"聖靈立刻把耶穌催促到曠野裏去。","notes":[],"heads":["耶穌受試探"]},{"n":13,"t":"他在曠野四十天，受撒但的試探，並與野獸同在一起，且有天使來伺候他。","notes":[]},{"n":14,"t":"約翰下監以後，耶穌來到加利利，宣講神的福音，","notes":[],"heads":["開始在加利利傳道"]},{"n":15,"t":"說：「日期滿了，神的國近了。你們要悔改，信福音！」","notes":[]},{"n":16,"t":"耶穌沿著加利利的海邊走，看見西門和西門的弟弟安得烈在海上撒網；他們本是打魚的。","notes":[],"heads":["呼召四個漁夫"]},{"n":17,"t":"耶穌對他們說：「來跟從我，我要叫你們得人如得魚一樣。」","notes":[]},{"n":18,"t":"他們立刻捨了網，跟從他。","notes":[]},{"n":19,"t":"耶穌稍往前走，又見西庇太的兒子雅各和他弟弟約翰在船上補網。","notes":[]},{"n":20,"t":"耶穌隨即呼召他們，他們就把父親西庇太和雇工留在船上，跟從了耶穌。","notes":[]},{"n":21,"t":"他們到了迦百農，耶穌就在安息日進了會堂教導人。","notes":[],"heads":["耶穌趕逐污靈"]},{"n":22,"t":"他們對他的教導感到很驚奇，因為他教導他們正像有權柄的人，不像文士。","notes":[]},{"n":23,"t":"當時，會堂裏有一個污靈附身的人，他在喊叫，","notes":[]},{"n":24,"t":"說：「拿撒勒人耶穌，你為甚麼干擾我們？你來消滅我們嗎？我知道你是誰，你是神的聖者。」","notes":[]},{"n":25,"t":"耶穌斥責他說：「不要作聲，從這人身上出來吧！」","notes":[]},{"n":26,"t":"污靈使那人抽了一陣風，大聲喊叫，就出來了。","notes":[]},{"n":27,"t":"眾人都驚訝，以致彼此對問：「這是甚麼事？是個新的教導啊！他用權柄命令污靈，連污靈也聽從了他。」","notes":[]},{"n":28,"t":"於是耶穌的名聲立刻傳遍了全加利利周圍地區。","notes":[]},{"n":29,"t":"他們一出會堂，就同雅各和約翰進了西門和安得烈的家。","notes":[],"heads":["治好許多病人"]},{"n":30,"t":"西門的岳母正發燒躺著，就有人告訴耶穌。","notes":[]},{"n":31,"t":"耶穌進前拉著她的手，扶她起來，燒就退了，於是她服事他們。","notes":[]},{"n":32,"t":"傍晚日落的時候，有人帶著一切害病的和被鬼附的，來到耶穌跟前。","notes":[]},{"n":33,"t":"全城的人都聚集在門前。","notes":[]},{"n":34,"t":"耶穌治好了許多害各樣病的人，又趕出許多鬼，不許鬼說話，因為鬼認識他。","notes":[]},{"n":35,"t":"次日早晨，天未亮的時候，耶穌起來，到曠野地方去，在那裏禱告。","notes":[],"heads":["在加利利傳道"]},{"n":36,"t":"西門和同伴出去找他，","notes":[]},{"n":37,"t":"找到了就對他說：「眾人都在找你！」","notes":[]},{"n":38,"t":"耶穌對他們說：「讓我們往別處去，到鄰近的鄉村，我也好在那裏傳道，因為我是為這事出來的。」","notes":[]},{"n":39,"t":"於是他走遍全加利利，在他們的會堂傳道，並且趕鬼。","notes":[]},{"n":40,"t":"有一個痲瘋病人來求耶穌，向他跪下，說：「你若肯，你能使我潔淨。」","notes":["有古卷沒有「向他跪下」。"],"heads":["潔淨痲瘋病人"]},{"n":41,"t":"耶穌動了慈心，就伸手摸他，說：「我肯，你潔淨了吧！」","notes":[]},{"n":42,"t":"痲瘋病立刻離開他，他就潔淨了。","notes":[]},{"n":43,"t":"耶穌嚴嚴地叮囑他，立刻打發他走，","notes":[]},{"n":44,"t":"對他說：「你要注意，千萬不可告訴任何人，只要去，讓祭司為你檢查，又因為你已經潔淨，獻上摩西所吩咐的祭物，作為證據給眾人看。」","notes":[]},{"n":45,"t":"那人出去，倒說許多的話，把這件事傳揚開了，使耶穌不能再公開進城，只好留在外邊曠野地方，人從各處都到他跟前來。","notes":[]}]},"2":{"heading":"治好癱子","verses":[{"n":1,"t":"過了些日子，耶穌又進了迦百農。人聽說他在屋裏，","notes":[]},{"n":2,"t":"於是許多人聚集，甚至連門前都沒有空地；耶穌就對他們講道。","notes":[]},{"n":3,"t":"有人帶著一個癱子來見耶穌，是由四個人抬來的；","notes":[]},{"n":4,"t":"因為人多，無法抬到耶穌跟前，就把他所在那房子的屋頂拆了，既拆通了，就把癱子連所躺臥的褥子都縋下去。","notes":[]},{"n":5,"t":"耶穌見他們的信心，就對癱子說：「孩子，你的罪赦了。」","notes":[]},{"n":6,"t":"有幾個文士坐在那裏，心裏議論，說：","notes":[]},{"n":7,"t":"「這個人為甚麼這樣說呢？他說褻瀆的話了。除了神一位之外，誰能赦罪呢？」","notes":[]},{"n":8,"t":"耶穌心中立刻知道他們心裏這樣議論，就說：「你們心裏為甚麼這樣議論呢？","notes":[]},{"n":9,"t":"對癱子說『你的罪赦了』，或說『起來！拿你的褥子行走』，哪一樣容易呢？","notes":[]},{"n":10,"t":"但要讓你們知道，人子在地上有赦罪的權柄。」就對癱子說：","notes":[]},{"n":11,"t":"「我吩咐你，起來！拿你的褥子回家去吧。」","notes":[]},{"n":12,"t":"那人就起來，立刻拿著褥子，當著眾人面前出去了，以致眾人都驚奇，歸榮耀給神，說：「我們從來沒有見過這樣的事！」","notes":[]},{"n":13,"t":"耶穌又到海邊去，眾人都到他跟前來，他就教導他們。","notes":[],"heads":["呼召利未"]},{"n":14,"t":"耶穌往前走，看見亞勒腓的兒子利未在稅關坐著，就對他說：「來跟從我！」他就起來跟從耶穌。","notes":[]},{"n":15,"t":"耶穌在利未家裏坐席的時候，有好些稅吏和罪人與耶穌和他的門徒一同坐席，因為有很多人也跟隨耶穌。","notes":[]},{"n":16,"t":"法利賽人中的文士看見耶穌與罪人和稅吏一同吃飯，就對他的門徒說：「他與稅吏和罪人一同吃飯嗎？」","notes":["有古卷是「文士和法利賽人」。"]},{"n":17,"t":"耶穌聽見，就對他們說：「健康的人用不著醫生，有病的人才用得著。我不是來召義人，而是召罪人。」","notes":[]},{"n":18,"t":"那時，約翰的門徒和法利賽人都禁食。他們來問耶穌說：「約翰的門徒和法利賽人的門徒禁食，你的門徒卻不禁食，這是為甚麼呢？」","notes":[],"heads":["禁食的問題"]},{"n":19,"t":"耶穌對他們說：「新郎和賓客在一起的時候，賓客怎麼能禁食呢？只要新郎和他們在一起，他們不能禁食。","notes":[]},{"n":20,"t":"但日子將到，新郎要被帶走，那日他們就要禁食了。","notes":[]},{"n":21,"t":"「沒有人把新布縫在舊衣服上，若是這樣，所補上的新布會撕破舊衣服，裂口就更大了。","notes":[]},{"n":22,"t":"也沒有人把新酒裝在舊皮袋裏，若是這樣，酒會脹破皮袋，酒和皮袋都糟蹋了。相反地，新酒要裝在新皮袋裏。」","notes":["有古卷是「酒就漏出來，皮袋也糟蹋了」。","有古卷沒有「相反地…皮袋裏」。"]},{"n":23,"t":"有一個安息日，耶穌從麥田經過。他的門徒走路的時候，摘起麥穗來。","notes":[],"heads":["在安息日摘麥穗"]},{"n":24,"t":"法利賽人對耶穌說：「看哪！他們為甚麼做安息日不合法的事呢？」","notes":[]},{"n":25,"t":"耶穌對他們說：「大衛和跟從他的人飢餓需要食物時所做的事，你們沒有念過嗎？","notes":[]},{"n":26,"t":"他在亞比亞他作大祭司的時候，怎麼進了神的居所，吃了供餅，又給跟從他的人吃呢？這餅除了祭司以外，人都不可以吃。」","notes":[]},{"n":27,"t":"他又對他們說：「安息日是為人設立的，人不是為安息日設立的。","notes":[]},{"n":28,"t":"所以，人子也是安息日的主。」","notes":[]}]},"3":{"heading":"治好萎縮了的手","verses":[{"n":1,"t":"耶穌又進了會堂，在那裏有一個人，他的一隻手萎縮了。","notes":[]},{"n":2,"t":"眾人為了要控告耶穌，就窺探他會不會在安息日醫治那人。","notes":[]},{"n":3,"t":"耶穌對那手萎縮了的人說：「起來站在當中！」","notes":[]},{"n":4,"t":"他又問眾人：「在安息日行善行惡，救命害命，哪樣是合法的呢？」他們都不作聲。","notes":[]},{"n":5,"t":"耶穌怒目環視他們，因他們的心剛硬而憂傷，就對那人說：「伸出手來！」他把手一伸，手就復原了。","notes":[]},{"n":6,"t":"法利賽人出去，立刻同希律一黨的人商議怎樣除掉耶穌。","notes":[]},{"n":7,"t":"耶穌和門徒退到海邊去，有許多人從加利利跟隨他。還有許多人聽見他所做的事，就從猶太、耶路撒冷、以土買、約旦河的東邊，以及推羅和西頓的附近地方來到他那裏。","notes":[],"end":8,"heads":["海邊的群眾"]},{"n":9,"t":"因為人多，他吩咐門徒為他預備一隻小船，免得眾人擁擠他。","notes":[]},{"n":10,"t":"他治好了許多人，所以凡有疾病的，都擠著要摸他。","notes":[]},{"n":11,"t":"每當污靈看見他，就俯伏在他面前，喊著說：「你是神的兒子。」","notes":[]},{"n":12,"t":"耶穌再三囑咐他們不要把他宣揚出去。","notes":[]},{"n":13,"t":"耶穌上了山，把自己所要的人召來，他們就來到他那裏。","notes":[],"heads":["揀選十二使徒"]},{"n":14,"t":"於是他設立十二個人，又稱他們為使徒，要他們常和自己同在，也要差他們去傳道，","notes":["有古卷沒有「又稱他們為使徒」。"]},{"n":15,"t":"並給他們權柄趕鬼。","notes":[]},{"n":16,"t":"他設立的十二個人有西門－耶穌又給他起名叫彼得，","notes":["有古卷沒有「他設立的十二個人」。"]},{"n":17,"t":"還有西庇太的兒子雅各和雅各的弟弟約翰—耶穌又給他們起名叫半尼其，就是雷的兒子—","notes":[]},{"n":18,"t":"又有安得烈、腓力、巴多羅買、馬太、多馬、亞勒腓的兒子雅各、達太和激進黨的西門，","notes":[]},{"n":19,"t":"還有出賣耶穌的加略人猶大。","notes":[]},{"n":20,"t":"耶穌進了屋子，眾人又聚集，甚至他連飯也顧不得吃。","notes":[],"heads":["誣蔑耶穌為別西卜"]},{"n":21,"t":"耶穌的家人聽見，就出來要拉住他，因為他們說他癲狂了。","notes":[]},{"n":22,"t":"從耶路撒冷下來的文士說：「他是被別西卜附身的」，又說：「他是靠著鬼王趕鬼的。」","notes":[]},{"n":23,"t":"耶穌叫他們來，用比喻對他們說：「撒但怎能趕出撒但呢？","notes":[]},{"n":24,"t":"一國若自相紛爭，那國就立不住；","notes":[]},{"n":25,"t":"一家若自相紛爭，那家就立不住。","notes":[]},{"n":26,"t":"撒但若自相攻打紛爭，他就立不住，必定滅亡。","notes":[]},{"n":27,"t":"沒有人能進壯士家裏，搶奪他的東西；除非先綁住那壯士，否則無法搶奪他的家。","notes":[]},{"n":28,"t":"我實在告訴你們，世人一切的罪和一切褻瀆的話都可以得到赦免；","notes":[]},{"n":29,"t":"凡褻瀆聖靈的，卻永不得赦免，而要擔當永遠的罪。」","notes":[]},{"n":30,"t":"因為他們說：「他是被污靈附身的。」","notes":[]},{"n":31,"t":"那時，耶穌的母親和他兄弟來，站在外邊，打發人去叫他。","notes":[],"heads":["遵父旨意的人都是親屬"]},{"n":32,"t":"有許多人在耶穌周圍坐著，他們就告訴他說：「看哪！你母親、你兄弟和你姊妹在外邊找你。」","notes":["有古卷沒有「和你姊妹」。"]},{"n":33,"t":"耶穌回答他們：「誰是我的母親？誰是我的兄弟？」","notes":[]},{"n":34,"t":"就環視那周圍坐著的人，說：「看哪，我的母親，我的兄弟！","notes":[]},{"n":35,"t":"凡遵行神旨意的人就是我的兄弟姊妹和母親。」","notes":[]}]},"4":{"heading":"撒種的比喻","verses":[{"n":1,"t":"耶穌又在海邊教導人。有一大群人到他那裏聚集，他只好上船坐下。船在海裏，眾人都靠近海，站在岸上。","notes":[]},{"n":2,"t":"耶穌就用許多比喻教導他們。在教導的時候，他對他們說：","notes":[]},{"n":3,"t":"「你們聽啊，有一個撒種的出去撒種。","notes":[]},{"n":4,"t":"他撒的時候，有的落在路旁，飛鳥來把它吃掉了。","notes":[]},{"n":5,"t":"有的落在土淺的石頭地上，因為土不深，很快就長出苗來，","notes":[]},{"n":6,"t":"太陽出來一曬，因為沒有根就枯乾了。","notes":[]},{"n":7,"t":"有的落在荊棘裏，荊棘長起來，把它擠住了，就結不出果實。","notes":[]},{"n":8,"t":"又有的落在好土裏，就發芽長大，結出果實，有三十倍的，有六十倍的，有一百倍的。」","notes":[]},{"n":9,"t":"耶穌又說：「有耳可聽的，就應當聽！」","notes":[]},{"n":10,"t":"耶穌獨自一人的時候，跟隨他的人和十二使徒問他這些比喻的意思。","notes":[],"heads":["用比喻的目的"]},{"n":11,"t":"耶穌對他們說：「神國的奧祕只讓你們知道，若是對外人講，凡事就用比喻，","notes":[]},{"n":12,"t":"要他們看了又看，卻看不清，聽了又聽，卻不明白，免得他們回轉過來，獲得赦免。」","notes":[]},{"n":13,"t":"耶穌又對他們說：「你們不明白這比喻嗎？這樣怎能明白一切的比喻呢？","notes":[],"heads":["解釋撒種的比喻"]},{"n":14,"t":"撒種的人所撒的就是道。","notes":[]},{"n":15,"t":"那撒在路旁的種子，就是人聽了道，撒但立刻來，把撒在他們心裏的道奪了去。","notes":[]},{"n":16,"t":"那撒在石頭地上的，就是人聽了道，立刻歡喜領受，","notes":[]},{"n":17,"t":"因心裏沒有根，不過是暫時的，一旦為道遭受患難或迫害，立刻就跌倒。","notes":[]},{"n":18,"t":"還有那撒在荊棘裏的，就是人聽了道，","notes":[]},{"n":19,"t":"後來有世上的憂慮、錢財的迷惑，和別樣的私慾進來，把道擠住了，結不出果實。","notes":[]},{"n":20,"t":"那撒在好土裏的，就是人聽了道，領受了，並且結了果實，有三十倍的，有六十倍的，有一百倍的。」","notes":[]},{"n":21,"t":"耶穌又對他們說：「人拿燈來，難道是要放在斗底下，床底下，而不放在燈臺上嗎？","notes":[],"heads":["斗下的燈"]},{"n":22,"t":"因為掩藏的事沒有不顯出來的，隱瞞的事也沒有不露出來的。","notes":[]},{"n":23,"t":"有耳可聽的，就應當聽！」","notes":[]},{"n":24,"t":"他又說：「你們要留心所聽的。你們用甚麼量器來量，也將要用甚麼來量給你們，並且要多給你們。","notes":[]},{"n":25,"t":"因為有的，還要給他；沒有的，連他所有的也要奪去。」","notes":[]},{"n":26,"t":"耶穌又說：「神的國如同人把種子撒在地上，","notes":[],"heads":["種子長大的比喻"]},{"n":27,"t":"黑夜睡覺，白日起來，這種子就發芽生長，那人卻不知道如何會這樣。","notes":[]},{"n":28,"t":"土地自然而然地出產五穀，先發苗，後長穗，然後穗上結成飽滿的穀子。","notes":[]},{"n":29,"t":"五穀熟了，就用鐮刀去割，因為收成的時候到了。」","notes":[]},{"n":30,"t":"耶穌又說：「我們可用甚麼來比擬神的國呢？可用甚麼比喻來說明呢？","notes":[],"heads":["芥菜種的比喻"]},{"n":31,"t":"它像一粒芥菜種，種在地裏的時候，雖比地上所有的種子都小，","notes":[]},{"n":32,"t":"但種下去以後，它長起來，比各樣的菜都大，又長出大枝，以致天上的飛鳥可以在它的蔭下築巢。」","notes":[]},{"n":33,"t":"耶穌用許多這樣的比喻，照他們所能聽的，對他們講道；","notes":[],"heads":["用比喻講道"]},{"n":34,"t":"若不用比喻，他就不對他們講，但私下沒有人的時候，就把一切的道講給門徒聽。","notes":[]},{"n":35,"t":"那天晚上，耶穌對門徒說：「我們渡到對岸去吧。」","notes":[],"heads":["平靜風和海"]},{"n":36,"t":"門徒離開眾人，耶穌已在船上，他們就請他一同去；也有別的船和他同行。","notes":[]},{"n":37,"t":"忽然狂風大作，波浪打入船內，以致船灌滿了水。","notes":[]},{"n":38,"t":"耶穌在船尾上，枕著枕頭睡覺。門徒叫醒他，說：「老師！我們快沒命了，你不管嗎？」","notes":[]},{"n":39,"t":"耶穌醒了，斥責那風，向海說：「住了吧！靜了吧！」風就止住，大大平靜了。","notes":[]},{"n":40,"t":"耶穌對他們說：「為甚麼膽怯？你們還沒有信心嗎？」","notes":[]},{"n":41,"t":"他們就非常懼怕，彼此說：「這到底是誰？連風和海都聽從他。」","notes":[]}]},"5":{"heading":"治好格拉森污靈附身的人","verses":[{"n":1,"t":"他們渡到海的對岸，到格拉森人的地區。","notes":["有古卷是「加大拉人」；另有古卷是「格各森人」。"]},{"n":2,"t":"耶穌一下船，就有一個污靈附身的人從墳墓迎著他走來。","notes":[]},{"n":3,"t":"那人常住在墳墓裏，沒有人能捆住他，就是用鐵鏈也不能；","notes":[]},{"n":4,"t":"因為人屢次用腳鐐和鐵鏈捆鎖他，鐵鏈被他掙斷，腳鐐也被他弄碎了，總沒有人能制伏他。","notes":[]},{"n":5,"t":"他晝夜常在墳墓裏和山中喊叫，又用石頭打自己。","notes":[]},{"n":6,"t":"他遠遠看見耶穌，就跑過來拜他，","notes":[]},{"n":7,"t":"大聲呼叫說：「至高神的兒子耶穌，你為甚麼干擾我？我指著神懇求你，不要叫我受苦！」","notes":[]},{"n":8,"t":"這是因耶穌曾吩咐他說：「污靈啊，從這人身上出來！」","notes":[]},{"n":9,"t":"耶穌問他：「你叫甚麼名字？」他說：「我名叫群，因為我們數目眾多。」","notes":[]},{"n":10,"t":"他就再三求耶穌不要叫他們離開那地方。","notes":[]},{"n":11,"t":"在山坡那裏，有一大群豬正在吃食；","notes":[]},{"n":12,"t":"污靈就央求耶穌，說：「求你打發我們進入豬群，好附著牠們。」","notes":[]},{"n":13,"t":"耶穌准了他們，污靈就出來，進入豬裏，那群豬就闖下山崖，投進海裏，淹死了。豬的數目約有二千。","notes":[]},{"n":14,"t":"放豬的逃跑了，去告訴城裏和鄉下的人。眾人就來，要看發生了甚麼事。","notes":[]},{"n":15,"t":"他們來到耶穌那裏，看見那被鬼附的人，就是曾被群鬼所附的，坐著，穿著衣服，神智清醒，他們就害怕。","notes":[]},{"n":16,"t":"看見這事的人把被鬼附的人所遇見的，和那群豬的事，都告訴了眾人，","notes":[]},{"n":17,"t":"眾人就央求耶穌離開他們的地區。","notes":[]},{"n":18,"t":"耶穌上船的時候，那曾被鬼附的人懇求要和耶穌在一起。","notes":[]},{"n":19,"t":"耶穌不許，卻對他說：「你回家去，到你的親友那裏，將主為你所做多麼大的事和他怎樣憐憫你，都告訴他們。」","notes":[]},{"n":20,"t":"那人就走了，開始在低加坡里傳揚耶穌為他做了多麼大的事，眾人就都驚訝。","notes":[]},{"n":21,"t":"耶穌又坐船渡到對岸，有一大群人聚集到他身邊；他正在海邊。","notes":["有古卷沒有「坐船」。"],"heads":["葉魯的女兒和經血不止的女人"]},{"n":22,"t":"有一個會堂主管，名叫葉魯，也來了，一見到耶穌，就俯伏在他腳前，","notes":[]},{"n":23,"t":"再三求他，說：「我的小女兒快要死了，求你去為她按手，使她痊癒，可以活下去。」","notes":[]},{"n":24,"t":"耶穌就和他同去。有一大群人跟隨他，擁擠著他。","notes":[]},{"n":25,"t":"有一個女人，患了經血不止的病有十二年，","notes":[]},{"n":26,"t":"在好多醫生手裏受了許多苦，又花盡了她所有的，一點也不見好，反而更重了。","notes":[]},{"n":27,"t":"她聽見耶穌的事，就夾在眾人中間，從後面來摸耶穌的衣裳，","notes":[]},{"n":28,"t":"因她想：「我只摸到他的衣裳，就會痊癒。」","notes":[]},{"n":29,"t":"於是她的流血立刻止住，她覺得身上的疾病好了。","notes":[]},{"n":30,"t":"耶穌頓時心裏覺得有能力從自己身上出去，就在眾人中間轉過來，說：「誰摸我的衣裳？」","notes":[]},{"n":31,"t":"門徒對他說：「你看眾人擁擠著你，還說『誰摸我』呢？」","notes":[]},{"n":32,"t":"耶穌周圍觀看，要見做這事的女人。","notes":[]},{"n":33,"t":"那女人知道在自己身上所成的事，就恐懼戰兢，來俯伏在耶穌跟前，將實情全告訴他。","notes":[]},{"n":34,"t":"耶穌對她說：「女兒，你的信救了你，平安地回去吧！你的疾病痊癒了。」","notes":[]},{"n":35,"t":"耶穌還在說話的時候，有人從會堂主管的家裏來，說：「你的女兒死了，何必還勞駕老師呢？」","notes":[]},{"n":36,"t":"耶穌不理會他們所說的話，就對會堂主管說：「不要怕，只要信！」","notes":[]},{"n":37,"t":"於是他帶著彼得、雅各和雅各的弟弟約翰同去，不許別人跟著他。","notes":[]},{"n":38,"t":"他們來到會堂主管的家裏，耶穌看到一片吵鬧，並有人大聲哭泣哀號，","notes":[]},{"n":39,"t":"就進到裏面，對他們說：「為甚麼大吵大哭呢？孩子不是死了，是睡著了。」","notes":[]},{"n":40,"t":"他們就嘲笑耶穌。耶穌把他們都趕出去，帶著孩子的父母和跟隨的人進了孩子所在的地方，","notes":[]},{"n":41,"t":"就拉著孩子的手，對她說：「大利大，古米！」翻出來就是說：「女孩，我吩咐你，起來！」","notes":[]},{"n":42,"t":"那女孩子立刻起來走動—她已經十二歲了；他們就非常驚奇。","notes":[]},{"n":43,"t":"耶穌切切地囑咐他們，不要讓人知道這事，又吩咐給她東西吃。","notes":[]}]},"6":{"heading":"拿撒勒人厭棄耶穌","verses":[{"n":1,"t":"耶穌離開那裏，來到自己的家鄉；門徒也跟從他。","notes":[]},{"n":2,"t":"到了安息日，他在會堂裏教導人。眾人聽見，就很驚奇，說：「這人哪來這本事呢？所賜給他的是甚麼智慧？他手所做的是何等的異能呢？","notes":[]},{"n":3,"t":"這不是那木匠嗎？不是馬利亞的兒子雅各、約西、猶大、西門的長兄嗎？他姊妹們不也是在我們這裏嗎？」他們就厭棄他。","notes":[]},{"n":4,"t":"耶穌對他們說：「先知除了在本鄉、本族和自己的家之外，沒有不被尊敬的。」","notes":[]},{"n":5,"t":"耶穌在那裏不能行甚麼異能，不過為幾個病人按手，治好他們。","notes":[]},{"n":6,"t":"他也詫異他們不信。耶穌走遍周圍鄉村教導人。","notes":[]},{"n":7,"t":"他叫了十二個使徒來，差遣他們兩個兩個地出去，也賜給他們權柄制伏污靈，","notes":[]},{"n":8,"t":"並且吩咐他們：途中不要帶食物和行囊，腰袋裏也不要帶錢，除了手杖以外，甚麼都不要帶；","notes":[]},{"n":9,"t":"只要穿鞋子，也不要穿兩件內衣。","notes":[]},{"n":10,"t":"他又對他們說：「你們無論到何處，進哪家，就住在哪裏，直到離開那地方。","notes":[]},{"n":11,"t":"若有甚麼地方的人不接待你們，不聽你們，你們離開那裏的時候，要跺掉你們腳上的塵土，證明他們的不是。」","notes":[]},{"n":12,"t":"使徒就出去傳道，叫人悔改，","notes":[]},{"n":13,"t":"又趕出許多鬼，用油抹了許多病人，治好他們。","notes":[]},{"n":14,"t":"耶穌的名聲傳開了，希律王也聽見。有人說：「施洗的約翰從死人中復活了，因此才有這些異能在他裏面運行。」","notes":[],"heads":["施洗約翰之死"]},{"n":15,"t":"但別人說：「他是以利亞。」又有人說：「是先知，正如先知中的一位。」","notes":[]},{"n":16,"t":"希律聽見卻說：「是我所斬的約翰，他復活了。」","notes":[]},{"n":17,"t":"原來，希律為他兄弟腓力的妻子希羅底的緣故，派人去抓了約翰，把他綁了在監獄裏，因為希律已經娶了那婦人。","notes":[]},{"n":18,"t":"約翰曾對希律說：「你佔有你兄弟的妻子是不合法的。」","notes":[]},{"n":19,"t":"於是希羅底懷恨他，想要殺他，只是不能。","notes":[]},{"n":20,"t":"因為希律怕約翰，知道他是義人，是聖人，所以就保護他，雖然聽了他的講論十分困惑，仍然樂意聽他。","notes":["「十分困惑」：有古卷是「也做了許多事」。"]},{"n":21,"t":"有一天，恰巧是希律的生日，希律擺設宴席，請了大臣、千夫長和加利利的領袖。","notes":[]},{"n":22,"t":"他的女兒希羅底進來跳舞，使希律和同席的人都很高興。王就對女孩說：「無論你要甚麼，向我求，我都會給你」；","notes":["有古卷是「希羅底自己的女兒」；另有古卷是「希羅底的女兒」。"]},{"n":23,"t":"又對她多次起誓說：「無論你向我求甚麼，就是我國家的一半，我也會給你。」","notes":["有古卷沒有「多次」。"]},{"n":24,"t":"她就出去對她母親說：「我該求甚麼呢？」她母親說：「施洗約翰的頭。」","notes":[]},{"n":25,"t":"她就急忙進去見王，求他說：「我願王立刻把施洗約翰的頭放在盤子裏給我。」","notes":[]},{"n":26,"t":"王就很憂愁，然而因他所發的誓，又因同席的人，不願食言，","notes":[]},{"n":27,"t":"就立刻派一個衛兵，吩咐拿約翰的頭來。衛兵就去，在監獄裏斬了約翰，","notes":[]},{"n":28,"t":"把頭放在盤子裏，拿來給那女孩，她就給她母親。","notes":[]},{"n":29,"t":"約翰的門徒聽到了，就來把他的屍體領去，放在墳墓裏。","notes":[]},{"n":30,"t":"使徒們聚集到耶穌那裏，把一切所做的事、所傳的道全告訴他。","notes":[],"heads":["耶穌使五千人吃飽"]},{"n":31,"t":"他就說：「你們來，同我私下到荒野的地方去歇一歇。」這是因為來往的人多，他們連吃飯的時間也沒有。","notes":[]},{"n":32,"t":"他們就坐船，私下往荒野的地方去。","notes":[]},{"n":33,"t":"眾人看見他們走了，有許多認識他們的，就從各城步行，一同跑到那裏，比他們先趕到了。","notes":[]},{"n":34,"t":"耶穌出來，見有一大群的人，就憐憫他們，因為他們如同羊沒有牧人一般，於是開始教導他們許多事。","notes":[]},{"n":35,"t":"天已經很晚，門徒進前來，說：「這地方偏僻，而且天已經很晚了，","notes":[]},{"n":36,"t":"請叫眾人散去，他們好往四面的鄉鎮村莊去，自己買些東西吃。」","notes":[]},{"n":37,"t":"耶穌回答他們說：「你們給他們吃吧！」門徒對他說：「我們要拿兩百個銀幣去買餅給他們吃嗎？」","notes":[]},{"n":38,"t":"耶穌說：「你們有多少餅？去看看。」他們知道後就說：「有五個，還有兩條魚。」","notes":[]},{"n":39,"t":"耶穌吩咐他們，叫眾人一組一組地坐在青草地上。","notes":[]},{"n":40,"t":"眾人就一群一群地坐下，有一百的，有五十的。","notes":[]},{"n":41,"t":"耶穌拿著這五個餅和兩條魚，望著天祝福，擘開餅，遞給門徒，擺在眾人面前，也把那兩條魚分給眾人。","notes":[]},{"n":42,"t":"他們都吃，並且吃飽了。","notes":[]},{"n":43,"t":"門徒把餅和魚的碎屑收拾起來，裝滿了十二個籃子。","notes":[]},{"n":44,"t":"吃餅的男人共有五千。","notes":[]},{"n":45,"t":"耶穌隨即催門徒上船，先渡到對岸，到伯賽大去，等他叫眾人散去。","notes":[],"heads":["耶穌在海上行走"]},{"n":46,"t":"他辭別了他們，就往山上去禱告。","notes":[]},{"n":47,"t":"到了晚上，船在海中，耶穌獨自在岸上。","notes":[]},{"n":48,"t":"他看見門徒因風不順，搖櫓很苦。天快亮的時候，他在海面上走，往他們那裏去，想要超過他們。","notes":[]},{"n":49,"t":"但門徒看見他在海面上走，以為是鬼怪，就喊叫起來；","notes":[]},{"n":50,"t":"因為他們都看見了他，甚為驚慌。耶穌連忙對他們說：「放心！是我，不要怕！」","notes":[]},{"n":51,"t":"於是他到他們那裏，一上船，風就停了；他們心裏十分驚奇。","notes":[]},{"n":52,"t":"這是因為他們不明白那分餅的事，心裏還是愚頑。","notes":[]},{"n":53,"t":"他們渡過了海，在革尼撒勒靠岸，泊了船，","notes":[],"heads":["治好革尼撒勒的病人"]},{"n":54,"t":"他們一下來，眾人立刻認出是耶穌，","notes":[]},{"n":55,"t":"就跑遍那整個地區，聽到他在哪裏，就把有病的人用褥子抬到哪裏。","notes":[]},{"n":56,"t":"耶穌所到的地方，或村中、或城裏、或鄉間，他們都把病人放在街市上，求耶穌讓他們摸一摸他的衣裳繸子，摸著的人就都好了。","notes":[]}]},"7":{"heading":"論古人的傳統","verses":[{"n":1,"t":"有法利賽人和幾個從耶路撒冷來的文士聚集到耶穌那裏。","notes":[]},{"n":2,"t":"他們曾看見他的門徒中有人用不潔淨的手，就是沒有洗的手吃飯。","notes":[]},{"n":3,"t":"法利賽人和所有的猶太人都拘守古人的傳統，若不按規矩洗手就不吃飯；","notes":[]},{"n":4,"t":"從市場來，若不洗淨也不吃飯；他們還拘守好些別的規矩，如洗杯、罐、銅器、床鋪等。","notes":["有古卷沒有「床鋪」。"]},{"n":5,"t":"法利賽人和文士問他說：「你的門徒為甚麼不照古人的傳統，竟然用不潔淨的手吃飯呢？」","notes":[]},{"n":6,"t":"耶穌對他們說：「以賽亞指著你們假冒為善的人所預言的說得好。如經上所記：『這百姓用嘴唇尊敬我，他們的心卻遠離我。","notes":[]},{"n":7,"t":"他們把人的規條當作教義教導人；他們拜我也是枉然。』","notes":[]},{"n":8,"t":"你們是離棄神的誡命，拘守人的傳統。」","notes":[]},{"n":9,"t":"耶穌又說：「你們誠然是廢棄神的誡命，為要守自己的傳統。","notes":[]},{"n":10,"t":"摩西說：『當孝敬父母』；又說：『咒罵父母的，必須處死。』","notes":[]},{"n":11,"t":"你們倒說：『人若對父母說：我所當供奉你的已經作了各耳板』（各耳板就是奉獻的意思），","notes":[]},{"n":12,"t":"你們就容許他不必再奉養父母。","notes":[]},{"n":13,"t":"這就是你們藉著繼承傳統，廢了神的話。你們還做許多這樣的事。」","notes":[]},{"n":14,"t":"耶穌又叫眾人來，對他們說：「你們都要聽我的話，也要明白。","notes":[]},{"n":15,"t":"從外面進去的不能玷污人，惟有從裏面出來的才玷污人。」","notes":["有古卷加「16 有耳可聽的，就應當聽！」"]},{"n":17,"t":"耶穌離開眾人，進了屋子，門徒就問他這比喻的意思。","notes":[]},{"n":18,"t":"耶穌對他們說：「你們也是這樣不明白嗎？難道你們不了解，凡從外面進去的不能玷污人嗎？","notes":[]},{"n":19,"t":"因為不是進入他的心，而是進入他的肚子，又排入廁所。」（這是說，各樣的食物都是潔淨的。）","notes":[]},{"n":20,"t":"耶穌又說：「從人裏面出來的，那才玷污人；","notes":[]},{"n":21,"t":"因為從人心裏發出種種惡念，如淫亂、偷盜、兇殺、","notes":[]},{"n":22,"t":"姦淫、貪婪、邪惡、詭詐、淫蕩、嫉妒、毀謗、驕傲、狂妄。","notes":[]},{"n":23,"t":"這一切的惡都是從裏面出來，且能玷污人。」","notes":[]},{"n":24,"t":"耶穌從那裏起身，往推羅境內去，進了一家，他不願意人知道，卻隱藏不住。","notes":["有古卷加「西頓」。"],"heads":["腓尼基婦人的信心"]},{"n":25,"t":"立刻有一個婦人，她的小女兒被污靈附著，一聽見耶穌的事，就來俯伏在他腳前。","notes":[]},{"n":26,"t":"這婦人是希臘人，屬敘利亞的腓尼基族。她求耶穌從她女兒身上趕出那鬼。","notes":[]},{"n":27,"t":"耶穌對她說：「讓孩子們先吃飽，拿孩子的餅丟給小狗吃是不妥的。」","notes":[]},{"n":28,"t":"婦人回答：「主啊，桌子底下的小狗也吃小孩子的碎屑呀！」","notes":[]},{"n":29,"t":"耶穌對她說：「憑著這句話，你回去吧，鬼已經離開你的女兒了。」","notes":[]},{"n":30,"t":"她就回家去，見小孩子躺在床上，鬼已經出去了。","notes":[]},{"n":31,"t":"耶穌又離開了推羅地區，經過西頓，就從低加坡里境內來到加利利海。","notes":[],"heads":["耶穌治好耳聾舌結的人"]},{"n":32,"t":"有人帶著一個耳聾舌結的人來見耶穌，求他為他按手。","notes":[]},{"n":33,"t":"耶穌領他離開眾人，到一邊去，就用指頭探他的耳朵，吐唾沫抹他的舌頭，","notes":[]},{"n":34,"t":"望天嘆息，對他說：「以法大！」就是說「開了吧！」","notes":[]},{"n":35,"t":"他的耳朵立刻開了，舌結也解了，他說話也清楚了。","notes":["有古卷沒有「立刻」。"]},{"n":36,"t":"耶穌囑咐他們不要告訴人；但他越囑咐，他們越發傳揚。","notes":[]},{"n":37,"t":"眾人分外驚奇，說：「他所做的事樣樣都好，他甚至使聾子聽見，啞巴說話。」","notes":[]}]},"8":{"heading":"耶穌使四千人吃飽","verses":[{"n":1,"t":"那時，又有一大群人聚集，沒有甚麼吃的。耶穌叫門徒來，說：","notes":[]},{"n":2,"t":"「我憐憫這群人，因為他們同我在這裏已經三天，沒有吃的東西了。","notes":[]},{"n":3,"t":"我若叫他們餓著回家，他們會在路上餓昏，因為其中有從遠處來的。」","notes":[]},{"n":4,"t":"門徒回答：「在這野地，從哪裏能得餅使這些人吃飽呢？」","notes":[]},{"n":5,"t":"耶穌問他們：「你們有多少餅？」他們說：「七個。」","notes":[]},{"n":6,"t":"他吩咐眾人坐在地上，就拿著這七個餅祝謝了，擘開，遞給門徒，叫他們擺開，門徒就擺在眾人面前。","notes":[]},{"n":7,"t":"他們還有幾條小魚；耶穌祝謝了，就吩咐也擺在眾人面前。","notes":[]},{"n":8,"t":"他們都吃，並且吃飽了，收拾剩下的碎屑，有七筐子。","notes":[]},{"n":9,"t":"人數約有四千。耶穌打發他們走了，","notes":[]},{"n":10,"t":"隨即同門徒上船，來到大瑪努他境內。","notes":[]},{"n":11,"t":"法利賽人出來盤問耶穌，要求他從天上顯個神蹟給他們看，想要試探他。","notes":[],"heads":["法利賽人求神蹟"]},{"n":12,"t":"耶穌心裏深深嘆息，說：「這世代為甚麼求神蹟呢？我實在告訴你們，沒有神蹟給這世代看。」","notes":[]},{"n":13,"t":"他就離開他們，又上船往海的對岸去了。","notes":[]},{"n":14,"t":"門徒忘了帶餅，在船上除了一個餅，沒有別的食物。","notes":[],"heads":["防備法利賽人和希律的酵"]},{"n":15,"t":"耶穌囑咐他們說：「你們要謹慎，要防備法利賽人的酵和希律的酵。」","notes":[]},{"n":16,"t":"他們彼此議論說：「這是因為我們沒有餅吧。」","notes":[]},{"n":17,"t":"耶穌知道了，就說：「你們為甚麼因為沒有餅就議論呢？你們還不領悟，還不明白嗎？你們的心還是愚頑嗎？","notes":[]},{"n":18,"t":"你們有眼睛，看不見嗎？有耳朵，聽不到嗎？也不記得嗎？","notes":[]},{"n":19,"t":"我擘開那五個餅分給五千人，你們收拾的碎屑裝滿了多少個籃子呢？」他們說：「十二個。」","notes":[]},{"n":20,"t":"「又擘開那七個餅分給四千人，你們收拾的碎屑裝滿了多少個筐子呢？」他們說：「七個。」","notes":[]},{"n":21,"t":"耶穌說：「你們還不明白嗎？」","notes":[]},{"n":22,"t":"他們來到伯賽大，有人帶一個盲人來，求耶穌摸他。","notes":[],"heads":["治好伯賽大的盲人"]},{"n":23,"t":"耶穌拉著盲人的手，領他到村外，就吐唾沫在他眼睛上，為他按手，問他：「你看見甚麼？」","notes":[]},{"n":24,"t":"他抬頭一看，說：「我看見人，他們好像樹木，並且行走。」","notes":[]},{"n":25,"t":"隨後耶穌又按手在他眼睛上，他定睛一看，就復原了，樣樣都看得清楚了。","notes":[]},{"n":26,"t":"耶穌打發他回家，說：「連這村子你也不要進去。」","notes":[]},{"n":27,"t":"耶穌和門徒出去，往凱撒利亞‧腓立比附近的村莊去。在路上，他問門徒：「人們說我是誰？」","notes":[],"heads":["彼得認耶穌為基督"]},{"n":28,"t":"他們對他說：「是施洗的約翰；有人說是以利亞；又有人說是先知中的一位。」","notes":[]},{"n":29,"t":"他又問他們：「你們說我是誰？」彼得回答他：「你是基督。」","notes":[]},{"n":30,"t":"於是耶穌切切地囑咐他們不可對任何人說起他。","notes":[]},{"n":31,"t":"從此，他教導他們說：「人子必須受許多的苦，被長老、祭司長和文士棄絕，並且被殺，三天後復活。」","notes":[],"heads":["耶穌預言受難和復活"]},{"n":32,"t":"耶穌明白地說了這話，彼得就拉著他，責備他。","notes":[]},{"n":33,"t":"耶穌轉過來看著門徒，斥責彼得說：「撒但，退到我後邊去！因為你不體會神的心意，而是體會人的意思。」","notes":[]},{"n":34,"t":"於是他叫眾人和門徒來，對他們說：「若有人要跟從我，就當捨己，背起自己的十字架來跟從我。","notes":[]},{"n":35,"t":"因為凡要救自己生命的，必喪失生命；凡為我和福音喪失生命的，必救自己的生命。","notes":[]},{"n":36,"t":"人就是賺得全世界，賠上自己的生命，有甚麼益處呢？","notes":[]},{"n":37,"t":"人還能拿甚麼換生命呢？","notes":[]},{"n":38,"t":"凡在這淫亂罪惡的世代，把我和我的道當作可恥的，人子在他父的榮耀裏與聖天使一同來臨的時候，也要把那人當作可恥的。」","notes":[]}]},"9":{"heading":"耶穌登山顯榮","verses":[{"n":1,"t":"耶穌又對他們說：「我實在告訴你們，站在這裏的，有人在沒經歷死亡以前，必定看見神的國帶著能力臨到。」","notes":[]},{"n":2,"t":"過了六天，耶穌帶著彼得、雅各、約翰，領他們悄悄地上了高山。他在他們面前變了形像，","notes":[]},{"n":3,"t":"衣服放光，極其潔白，地上漂布的人沒有一個能漂得那樣白。","notes":[]},{"n":4,"t":"有以利亞和摩西向他們顯現，並且與耶穌說話。","notes":[]},{"n":5,"t":"彼得對耶穌說：「拉比，我們在這裏真好！我們來搭三座棚，一座為你，一座為摩西，一座為以利亞。」","notes":["「拉比」意思是「老師」。"]},{"n":6,"t":"彼得不知道說甚麼才好，因為他們很害怕。","notes":[]},{"n":7,"t":"有一朵雲彩來遮蓋他們，又有聲音從雲彩裏出來，說：「這是我的愛子，你們要聽從他！」","notes":[]},{"n":8,"t":"門徒連忙向周圍觀看，不再看見任何人，只見耶穌同他們在一起。","notes":[]},{"n":9,"t":"下山的時候，耶穌囑咐他們說：「人子還沒有從死人中復活，你們不要把所看到的告訴人。」","notes":[]},{"n":10,"t":"門徒將這話存記在心，彼此議論「從死人中復活」是甚麼意思。","notes":[]},{"n":11,"t":"他們就問耶穌：「文士為甚麼說以利亞必須先來？」","notes":[]},{"n":12,"t":"耶穌說：「以利亞的確先來復興萬事。經上不是指著人子說，他要受許多的苦和被人輕慢嗎？","notes":[]},{"n":13,"t":"我告訴你們，以利亞已經來了，他們任意待他，正如經上指著他說的。」","notes":[]},{"n":14,"t":"他們到了門徒那裏，看見有一大群人圍著他們，又有文士和他們辯論。","notes":[],"heads":["治好污靈附身的孩子"]},{"n":15,"t":"眾人一見耶穌，都很驚奇，就跑上去向他問安。","notes":[]},{"n":16,"t":"耶穌問他們：「你們和他們辯論甚麼？」","notes":[]},{"n":17,"t":"眾人中的一個回答：「老師，我帶了我的兒子到你這裏來，他被啞巴的靈附著。","notes":[]},{"n":18,"t":"無論在哪裏，那靈拿住他，把他摔倒，他就口吐白沫，牙關緊鎖，身體僵硬。我請過你的門徒把那靈趕出去，他們卻不能。」","notes":[]},{"n":19,"t":"耶穌回答：「唉！這不信的世代啊，我和你們在一起要到幾時呢？我忍耐你們要到幾時呢？把他帶到我這裏！」","notes":[]},{"n":20,"t":"他們就帶了他來。那靈一見耶穌，就使他重重地抽風，倒在地上，翻來覆去，口吐白沫。","notes":[]},{"n":21,"t":"耶穌問他父親：「他得這病有多久了呢？」父親說：「從小的時候。","notes":[]},{"n":22,"t":"那靈屢次把他扔在火裏、水裏，要治死他。你若能做甚麼，求你憐憫我們，幫助我們。」","notes":[]},{"n":23,"t":"耶穌對他說：「『你若能』，在信的人，凡事都能。」","notes":[]},{"n":24,"t":"孩子的父親立刻喊著說：「我信；求你幫助我的不信！」","notes":[]},{"n":25,"t":"耶穌看見眾人都跑上來，就斥責那污靈說：「你這聾啞的靈，我命令你從他裏頭出來，再不要進去！」","notes":[]},{"n":26,"t":"那靈大喊一聲，使孩子猛烈地抽了一陣風，就出來了。孩子好像死了一般，以致眾人多半說：「他死了。」","notes":[]},{"n":27,"t":"但耶穌拉著他的手，扶他起來，他就站起來了。","notes":[]},{"n":28,"t":"耶穌進了屋子，門徒就私下問他：「我們為甚麼不能趕出那靈呢？」","notes":[]},{"n":29,"t":"耶穌對他們說：「非用禱告，這一類的邪靈總趕不出來。」","notes":["有古卷加「禁食」。"]},{"n":30,"t":"他們離開那地方，經過加利利；耶穌不願意人知道，","notes":[],"heads":["耶穌第二次預言受難和復活"]},{"n":31,"t":"因為他正教導門徒說：「人子將要被交在人手裏，他們要殺害他；被殺以後，三天後他要復活。」","notes":[]},{"n":32,"t":"門徒卻不明白這話，又不敢問他。","notes":[]},{"n":33,"t":"他們來到迦百農。耶穌在屋裏問門徒說：「你們在路上議論的是甚麼？」","notes":[],"heads":["誰最大"]},{"n":34,"t":"門徒不作聲，因為他們在路上彼此爭論誰最大。","notes":[]},{"n":35,"t":"耶穌坐下，叫十二個使徒來，說：「若有人願意為首，他要作眾人之後，作眾人的用人。」","notes":[]},{"n":36,"t":"於是耶穌領一個小孩過來，讓他站在門徒當中，又抱起他來，對他們說：","notes":[]},{"n":37,"t":"「凡為我的名接納一個像這小孩子的，就是接納我；凡接納我的，不是接納我，而是接納那差我來的。」","notes":[]},{"n":38,"t":"約翰對耶穌說：「老師，我們看見一個人奉你的名趕鬼，我們就阻止他，因為他不跟從我們。」","notes":[],"heads":["不抵擋我們就是幫助我們"]},{"n":39,"t":"耶穌說：「不要阻止他，因為沒有人奉我的名行異能，反倒輕易毀謗我。","notes":[]},{"n":40,"t":"不抵擋我們的，就是幫助我們的。","notes":[]},{"n":41,"t":"凡因你們是屬基督，給你們一杯水喝的，我實在告訴你們，他一定會得到賞賜。」","notes":[]},{"n":42,"t":"「凡使這些信我的小子中的一個跌倒的，倒不如把大磨石拴在這人的頸項上，扔在海裏。","notes":["「這些…小子」：有古卷是「這些有信心的小子」。"],"heads":["拒絕罪的誘惑"]},{"n":43,"t":"如果你一隻手使你跌倒，就把它砍下來；你缺一隻手進入永生，比有兩隻手落到地獄，入那不滅的火裏去還好。","notes":["有古卷加44節，經文與48節同。"]},{"n":45,"t":"如果你一隻腳使你跌倒，就把它砍下來；你瘸腿進入永生，比有兩隻腳被扔進地獄裏還好。","notes":["有古卷加46節，經文與48節同。"]},{"n":47,"t":"如果你一隻眼使你跌倒，就去掉它；你只有一隻眼進入神的國，比有兩隻眼被扔進地獄裏還好。","notes":[]},{"n":48,"t":"在那裏，蟲是不死的，火是不滅的。","notes":[]},{"n":49,"t":"因為每個人必被火像鹽一般醃起來。","notes":["有古卷加「凡祭物必用鹽醃。」"]},{"n":50,"t":"鹽本是好的，若失了鹹味，你們怎能用它調味呢？你們中間要有鹽，彼此和睦。」","notes":[]}]},"10":{"heading":"休妻的問題","verses":[{"n":1,"t":"耶穌從那裏起身，來到猶太的境內，約旦河的東邊。眾人又聚集到他那裏，他又照常教導他們。","notes":[]},{"n":2,"t":"有法利賽人來問他說：「男人休妻合不合法？」意思是要試探他。","notes":[]},{"n":3,"t":"耶穌回答他們說：「摩西吩咐你們的是甚麼？」","notes":[]},{"n":4,"t":"他們說：「摩西准許寫了休書就可以休妻。」","notes":[]},{"n":5,"t":"耶穌對他們說：「摩西因為你們的心硬，所以寫這誡命給你們。","notes":[]},{"n":6,"t":"但從起初創造的時候，神造人是造男造女。","notes":[]},{"n":7,"t":"因此，人要離開他的父母，與妻子結合，","notes":["有古卷沒有「與妻子結合」。"]},{"n":8,"t":"二人成為一體。既然如此，夫妻不再是兩個人，而是一體的了。","notes":[]},{"n":9,"t":"所以，神配合的，人不可分開。」","notes":[]},{"n":10,"t":"他們到了屋裏，門徒又問他這事。","notes":[]},{"n":11,"t":"耶穌對他們說：「凡休妻另娶的，就是犯姦淫，辜負他的妻子；","notes":[]},{"n":12,"t":"妻子若離棄丈夫另嫁，也是犯姦淫了。」","notes":[]},{"n":13,"t":"有人帶著小孩子來見耶穌，要他摸他們，門徒就責備那些人。","notes":[],"heads":["耶穌為小孩祝福"]},{"n":14,"t":"耶穌看見就很生氣，對門徒說：「讓小孩到我這裏來，不要阻止他們，因為在神國的正是這樣的人。","notes":[]},{"n":15,"t":"我實在告訴你們，凡要接受神國的，若不像小孩子，絕不能進去。」","notes":[]},{"n":16,"t":"於是他抱著小孩子，給他們按手，為他們祝福。","notes":[]},{"n":17,"t":"耶穌剛上路的時候，有一個人跑來，跪在他面前，問他：「善良的老師，我該做甚麼事才能承受永生？」","notes":[],"heads":["財主尋求永生"]},{"n":18,"t":"耶穌對他說：「你為甚麼稱我是善良的？除了神一位之外，再沒有善良的。","notes":[]},{"n":19,"t":"誡命你是知道的：『不可殺人；不可姦淫；不可偷盜；不可作假見證；不可虧負人；當孝敬父母。』」","notes":[]},{"n":20,"t":"他對耶穌說：「老師，這一切我從小都遵守了。」","notes":[]},{"n":21,"t":"耶穌看著他，就愛他，對他說：「你還缺少一件：去變賣你所有的，分給窮人，就必有財寶在天上；然後來跟從我。」","notes":[]},{"n":22,"t":"他聽見這話，臉就變了色，憂憂愁愁地走了，因為他的產業很多。","notes":[]},{"n":23,"t":"耶穌看了看周圍，對門徒說：「有錢財的人進神的國是何等的難哪！」","notes":[]},{"n":24,"t":"門徒對他的話非常驚奇。耶穌又對他們說：「孩子們，要進神的國是何等的難哪！","notes":["有古卷加「倚靠錢財的人」。"]},{"n":25,"t":"駱駝穿過針眼比財主進神的國還容易呢！」","notes":[]},{"n":26,"t":"門徒就更為驚訝，彼此對問：「這樣，誰能得救呢？」","notes":[]},{"n":27,"t":"耶穌看著他們，說：「在人不能，在神卻不然，因為在神凡事都能。」","notes":[]},{"n":28,"t":"彼得就對他說：「看哪，我們已經撇下一切跟從你了。」","notes":[]},{"n":29,"t":"耶穌說：「我實在告訴你們，凡為我和福音撇下房屋，或是兄弟、姊妹、父親、母親、兒女、田地，","notes":[]},{"n":30,"t":"沒有不在今世得百倍的，就是房屋、兄弟、姊妹、母親、兒女、田地，並且要受迫害，在來世得永生。","notes":[]},{"n":31,"t":"然而，有許多在前的，將要在後；在後的，將要在前。」","notes":[]},{"n":32,"t":"他們行路上耶路撒冷去。耶穌在前頭走，他們很驚訝，跟從的人也害怕。耶穌又叫十二使徒來，把自己將要遭遇的事告訴他們，","notes":[],"heads":["耶穌第三次預言受難和復活"]},{"n":33,"t":"說：「看哪，我們上耶路撒冷去，人子將被交給祭司長和文士；他們要定他死罪，又交給外邦人。","notes":[]},{"n":34,"t":"他們要戲弄他，向他吐唾沫，鞭打他，殺害他；三天後，他要復活。」","notes":[]},{"n":35,"t":"西庇太的兒子雅各和約翰進前來，對耶穌說：「老師，我們無論求你甚麼，願你為我們做。」","notes":[],"heads":["為首與為僕"]},{"n":36,"t":"耶穌對他們說：「要我為你們做甚麼？」","notes":[]},{"n":37,"t":"他們對他說：「在你的榮耀裏，請賜我們一個坐在你右邊，一個坐在你左邊。」","notes":[]},{"n":38,"t":"耶穌對他們說：「你們不知道所求的是甚麼。我所喝的杯，你們能喝嗎？我所受的洗，你們能受嗎？」","notes":[]},{"n":39,"t":"他們對他說：「我們能。」耶穌對他們說：「我所喝的杯，你們要喝；我所受的洗，你們也要受。","notes":[]},{"n":40,"t":"可是坐在我的左右，不是我可以賜的，而是為誰預備就賜給誰。」","notes":[]},{"n":41,"t":"其餘十個門徒聽見，就對雅各和約翰很生氣。","notes":[]},{"n":42,"t":"耶穌叫了他們來，對他們說：「你們知道，外邦人有君王作主治理他們，有大臣操權管轄他們。","notes":[]},{"n":43,"t":"但是在你們中間，不可這樣。你們中間誰願為大，就要作你們的用人；","notes":[]},{"n":44,"t":"在你們中間誰願為首，就要作眾人的僕人。","notes":[]},{"n":45,"t":"因為人子來，並不是要受人的服事，乃是要服事人，並且要捨命作多人的贖價。」","notes":[]},{"n":46,"t":"他們到了耶利哥。耶穌同門徒並許多人離開耶利哥的時候，有一個討飯的盲人，是底買的兒子巴底買，坐在路旁。","notes":[],"heads":["治好盲人巴底買"]},{"n":47,"t":"他聽見是拿撒勒的耶穌，就喊了起來，說：「大衛之子耶穌啊，可憐我吧！」","notes":[]},{"n":48,"t":"有許多人責備他，不許他作聲，他卻越發喊著：「大衛之子啊，可憐我吧！」","notes":[]},{"n":49,"t":"耶穌就站住，說：「叫他過來。」他們就叫那盲人，對他說：「放心，起來！他在叫你啦。」","notes":[]},{"n":50,"t":"盲人就丟下衣服，跳起來，走到耶穌那裏。","notes":[]},{"n":51,"t":"耶穌回答他說：「你要我為你做甚麼？」盲人對他說：「拉波尼，我要能看見。」","notes":["「拉波尼」意思是「我的老師」。"]},{"n":52,"t":"耶穌對他說：「你去吧！你的信救了你。」盲人立刻看得見，就在路上跟隨耶穌。","notes":[]}]},"11":{"heading":"榮入聖城","verses":[{"n":1,"t":"耶穌和門徒快到耶路撒冷，來到伯法其和伯大尼，在橄欖山那裏。耶穌打發兩個門徒，","notes":[]},{"n":2,"t":"對他們說：「你們往對面村子裏去，一進去的時候會看見一匹驢駒拴在那裏，是從來沒有人騎過的，把牠解開，牽來。","notes":[]},{"n":3,"t":"若有人對你們說：『為甚麼做這事？』你們就說：『主要用牠，但會立刻把牠牽回到這裏來。』」","notes":[]},{"n":4,"t":"他們去了，看見一匹驢駒拴在門外街道上，就把牠解開。","notes":[]},{"n":5,"t":"在那裏站著的人，有幾個說：「你們解開驢駒做甚麼？」","notes":[]},{"n":6,"t":"門徒照著耶穌的話說，那些人就任憑他們牽去了。","notes":[]},{"n":7,"t":"他們把驢駒牽到耶穌那裏，把自己的衣服搭在上面，耶穌就騎上。","notes":[]},{"n":8,"t":"有許多人把衣服鋪在路上，還有人把田間的樹枝砍下來鋪上。","notes":[]},{"n":9,"t":"前呼後擁的人都喊著說：「和散那！奉主名來的是應當稱頌的！","notes":["「和散那」：原是求救的意思，在此是稱頌的話。"]},{"n":10,"t":"那將要來的我祖大衛之國是應當稱頌的！至高無上的，和散那！」","notes":[]},{"n":11,"t":"耶穌到了耶路撒冷，進入聖殿，看了周圍的一切。天色已晚，他就和十二使徒出城，往伯大尼去。","notes":[]},{"n":12,"t":"第二天，他們從伯大尼出來，耶穌餓了。","notes":[],"heads":["詛咒無花果樹"]},{"n":13,"t":"他遠遠地看見一棵無花果樹，樹上有葉子，就過去，看是不是在樹上可以找到甚麼。他到了樹下，竟找不到甚麼，只有葉子，因為不是無花果的季節。","notes":[]},{"n":14,"t":"耶穌就對樹說：「從今以後，永沒有人吃你的果子。」他的門徒都聽到了。","notes":[]},{"n":15,"t":"他們來到耶路撒冷。耶穌一進聖殿，就趕出在聖殿裏做買賣的人，推倒兌換銀錢之人的桌子和賣鴿子之人的凳子；","notes":[],"heads":["潔淨聖殿"]},{"n":16,"t":"也不許人拿著器具從聖殿裏經過。","notes":[]},{"n":17,"t":"他教導他們說：「經上不是記著：『我的殿要稱為萬國禱告的殿嗎？你們倒使它成為賊窩了。』」","notes":[]},{"n":18,"t":"祭司長和文士聽見這話，就想法子要除掉耶穌，卻又怕他，因為眾人都對他的教導感到驚奇。","notes":[]},{"n":19,"t":"每天晚上，他們都到城外去。","notes":["有古卷是「耶穌」。"]},{"n":20,"t":"早晨，他們從那裏經過，看見無花果樹連根都枯乾了。","notes":[],"heads":["從無花果樹得教導"]},{"n":21,"t":"彼得想起耶穌的話來，就對他說：「拉比，你看！你所詛咒的無花果樹已經枯乾了。」","notes":[]},{"n":22,"t":"耶穌回答：「你們對神要有信心。","notes":[]},{"n":23,"t":"我實在告訴你們，無論何人對這座山說：『離開此地，投在海裏！』他心裏若不疑惑，只信所說的必成，就為他實現。","notes":[]},{"n":24,"t":"所以我告訴你們，凡你們禱告祈求的，無論是甚麼，只要信你們已經得著了，就為你們實現。","notes":[]},{"n":25,"t":"你們站著禱告的時候，若想起有人得罪你們，就該饒恕他，好讓你們在天上的父也饒恕你們的過犯。」","notes":["有古卷加「26 你們若不饒恕人，你們在天上的父也不饒恕你們的過犯。」"]},{"n":27,"t":"他們又來到耶路撒冷。耶穌在聖殿裏行走的時候，祭司長、文士和長老進前來，","notes":[],"heads":["耶穌的權柄受到質問"]},{"n":28,"t":"問他說：「你仗著甚麼權柄做這些事？給你權柄做這些事的是誰呢？」","notes":[]},{"n":29,"t":"耶穌對他們說：「我要問你們一句話，你們回答我，我就告訴你們我仗著甚麼權柄做這些事。","notes":[]},{"n":30,"t":"約翰的洗禮是從天上來的，還是從人間來的呢？你們回答我吧。」","notes":[]},{"n":31,"t":"他們彼此商議說：「我們若說『從天上來的』，他會說：『這樣，你們為甚麼不信他呢？』","notes":[]},{"n":32,"t":"但若說『從人間來的』，卻又怕眾人，因為大家認為約翰確是先知。」","notes":[]},{"n":33,"t":"於是他們回答耶穌：「我們不知道。」耶穌說：「我也不告訴你們，我仗著甚麼權柄做這些事。」","notes":[]}]},"12":{"heading":"惡園戶的比喻","verses":[{"n":1,"t":"耶穌就用比喻對他們說：「有人開墾了一個葡萄園，四周圍上籬笆，挖了一個醡酒池，蓋了一座守望樓，租給園戶，就出外遠行去了。","notes":[]},{"n":2,"t":"到了時候，他打發一個僕人到園戶那裏，要向他們收葡萄園的果子。","notes":[]},{"n":3,"t":"他們拿住他，打了他，叫他空手回去。","notes":[]},{"n":4,"t":"園主再打發一個僕人到他們那裏。他們打傷他的頭，並且侮辱他。","notes":[]},{"n":5,"t":"園主又打發一個僕人去，他們就殺了他。以後又打發好些僕人去，有的被他們打了，有的被他們殺了。","notes":[]},{"n":6,"t":"園主還有一位，是他的愛子，最後又打發他去，說：『他們會尊敬我的兒子。』","notes":[]},{"n":7,"t":"那些園戶卻彼此說：『這是承受產業的。來，我們殺了他，產業就歸我們了！』","notes":[]},{"n":8,"t":"於是他們拿住他，殺了他，把他扔出葡萄園。","notes":[]},{"n":9,"t":"這樣，葡萄園主要怎麼做呢？他要來除滅那些園戶，將葡萄園轉給別人。","notes":[]},{"n":10,"t":"『匠人所丟棄的石頭已作了房角的頭塊石頭。這是主所做的，在我們眼中看為奇妙。』這經文你們沒有念過嗎？」","notes":[],"end":11},{"n":12,"t":"他們看出這比喻是指著他們說的，就想要捉拿他，但是懼怕眾人，於是離開他走了。","notes":[]},{"n":13,"t":"後來，他們打發幾個法利賽人和希律黨人到耶穌那裏，要用他自己的話陷害他。","notes":[],"heads":["納稅給凱撒的問題"]},{"n":14,"t":"他們來了，就對他說：「老師，我們知道你是誠實的，無論誰你都一視同仁；因為你不看人的面子，而是誠誠實實傳神的道。納稅給凱撒合不合法？","notes":[]},{"n":15,"t":"我們該不該納？」耶穌知道他們的虛偽，就對他們說：「你們為甚麼試探我？拿一個銀幣來給我看。」","notes":[]},{"n":16,"t":"他們就拿了來。耶穌問他們：「這像和這名號是誰的？」他們對他說：「是凱撒的。」","notes":[]},{"n":17,"t":"耶穌對他們說：「凱撒的歸凱撒；神的歸神。」他們對他非常驚訝。","notes":[]},{"n":18,"t":"撒都該人來見耶穌。他們說沒有復活這回事，於是問耶穌：","notes":[],"heads":["復活的問題"]},{"n":19,"t":"「老師，摩西為我們寫下這話：『某人的哥哥若死了，撇下妻子，沒有孩子，他該娶哥哥的妻子，為哥哥生子立後。』","notes":[]},{"n":20,"t":"那麼，有兄弟七人，第一個娶了妻，死了，沒有留下孩子。","notes":[]},{"n":21,"t":"第二個娶了她，也死了，沒有留下孩子。第三個也是這樣。","notes":[]},{"n":22,"t":"那七個人都沒有留下孩子。最後，那婦人也死了。","notes":[]},{"n":23,"t":"在復活的時候，她是哪一個的妻子呢？因為他們七個人都娶過她。」","notes":["有古卷加「當他們復活」。"]},{"n":24,"t":"耶穌說：「你們錯了，不正是因為不明白聖經，也不知道神的大能嗎？","notes":[]},{"n":25,"t":"當人從死人中復活後，也不娶也不嫁，而是像天上的天使一樣。","notes":[]},{"n":26,"t":"論到死人復活，你們沒有念過摩西書中《荊棘篇》上所記載的嗎？神對摩西說：『我是亞伯拉罕的神，以撒的神，雅各的神。』","notes":[]},{"n":27,"t":"神不是死人的神，而是活人的神。你們是大錯了。」","notes":[]},{"n":28,"t":"有一個文士來，聽見他們的辯論，知道耶穌回答得好，就問他說：「誡命中哪一條是第一呢？」","notes":[],"heads":["最大的誡命"]},{"n":29,"t":"耶穌回答：「第一是：『以色列啊，你要聽，主—我們的神是獨一的主。","notes":[]},{"n":30,"t":"你要盡心、盡性、盡意、盡力愛主—你的神。』","notes":[]},{"n":31,"t":"第二是：『要愛鄰如己。』再沒有比這兩條誡命更大的了。」","notes":["「鄰」也可譯作「人」；33節同。"]},{"n":32,"t":"那文士對耶穌說：「好，老師，你說得對，神是一位，除了他以外，再沒有別的了；","notes":[]},{"n":33,"t":"並且盡心、盡智、盡力愛他，又愛鄰如己，要比一切燔祭和祭祀好得多。」","notes":[]},{"n":34,"t":"耶穌見他回答得有智慧，就對他說：「你離神的國不遠了。」從此以後，沒有人敢再問他甚麼。","notes":[]},{"n":35,"t":"耶穌在聖殿裏教導人，問他們說：「文士怎麼說基督是大衛的後裔呢？","notes":[],"heads":["基督與大衛的關係"]},{"n":36,"t":"大衛被聖靈感動，說：『主對我主說：你坐在我的右邊，等我把你的仇敵放在你腳下。』","notes":["「放在你腳下」：有古卷是「作你的腳凳」。"]},{"n":37,"t":"大衛親自稱他為主，他怎麼又是大衛的後裔呢？」一大群的人都喜歡聽他。","notes":[]},{"n":38,"t":"他在教導的時候，說：「你們要防備文士。他們好穿長袍走來走去，喜歡人們在街市上向他們問安，","notes":[],"heads":["譴責文士"]},{"n":39,"t":"又喜愛會堂裏的高位，宴席上的首座。","notes":[]},{"n":40,"t":"他們侵吞寡婦的家產，假意作很長的禱告。這些人要受更重的懲罰！」","notes":[]},{"n":41,"t":"耶穌面向聖殿銀庫坐著，看眾人怎樣把錢投入銀庫。有好些財主投了許多錢。","notes":[],"heads":["寡婦的奉獻"]},{"n":42,"t":"有一個窮寡婦來，投了兩個小文錢，就是一個大文錢。","notes":["「小文錢」：參「度量衡表」。","「大文錢」：參「度量衡表」。"]},{"n":43,"t":"耶穌叫門徒來，對他們說：「我實在告訴你們，這窮寡婦投入銀庫裏的比眾人所投的更多。","notes":[]},{"n":44,"t":"因為，眾人都是拿有餘的捐獻，但這寡婦，雖然自己不足，卻把她一生所有的全都投進去了。」","notes":[]}]},"13":{"heading":"預言聖殿被毀","verses":[{"n":1,"t":"耶穌從聖殿裏出來的時候，有一個門徒對他說：「老師，請看，這是多麼了不起的石頭！多麼了不起的建築！」","notes":[]},{"n":2,"t":"耶穌對他說：「你看見這些宏偉的建築嗎？這裏將沒有一塊石頭會留在另一塊石頭上而不被拆毀的。」","notes":[]},{"n":3,"t":"耶穌在橄欖山上，面向聖殿坐著；彼得、雅各、約翰和安得烈私下問他說：","notes":[],"heads":["終局的預兆"]},{"n":4,"t":"「請告訴我們，甚麼時候有這些事呢？這一切事將成的時候有甚麼預兆呢？」","notes":[]},{"n":5,"t":"耶穌說：「你們要謹慎，免得有人迷惑你們。","notes":[]},{"n":6,"t":"將有好些人冒我的名來，說『我是基督』，並且要迷惑許多人。","notes":[]},{"n":7,"t":"當你們聽見打仗和打仗的風聲，不要驚慌；這些事必須發生，但這還不是終結。","notes":[]},{"n":8,"t":"民要攻打民，國要攻打國，多處必有地震、饑荒。這都是災難的起頭。","notes":["「災難」：原文直譯「生產的陣痛」。"]},{"n":9,"t":"但你們自己要謹慎；因為有人要把你們交給議會，並且你們在會堂裏要受鞭打，又為我的緣故站在統治者和君王面前，對他們作見證。","notes":[]},{"n":10,"t":"然而，福音必須先傳給萬民。","notes":[]},{"n":11,"t":"有人把你們解送去受審的時候，不要事先擔心說甚麼；到那時候，賜給你們甚麼話，你們就說甚麼；因為說話的不是你們，而是聖靈。","notes":[]},{"n":12,"t":"兄弟要把兄弟、父親要把兒女置於死地；兒女要起來與父母為敵，害死他們；","notes":[]},{"n":13,"t":"而且你們要為我的名被眾人憎恨。但堅忍到底的終必得救。」","notes":[]},{"n":14,"t":"「當你們看見那『施行毀滅的褻瀆者』站在不當站的地方（讀這經的人要會意），那時，在猶太的，應當逃到山上；","notes":[],"heads":["大災難"]},{"n":15,"t":"在屋頂上的，不要下來，也不要進家裏去拿東西；","notes":[]},{"n":16,"t":"在田裏的，不要回去取衣裳。","notes":[]},{"n":17,"t":"在那些日子，懷孕的和奶孩子的就苦了。","notes":[]},{"n":18,"t":"你們要祈求，叫這事不在冬天發生。","notes":[]},{"n":19,"t":"因為，在那些日子必有災難，自從神創造萬物直到如今，從沒有這樣的災難，將來也不會有。","notes":[]},{"n":20,"t":"若不是主減少那些日子，凡血肉之軀的，就沒有一個能得救；但是為了他所揀選的選民，他將那些日子減少了。","notes":[]},{"n":21,"t":"那時，若有人對你們說：『看哪，基督在這裏！看哪，在那裏！』你們不要信。","notes":[]},{"n":22,"t":"因為假基督和假先知將要起來，顯神蹟奇事，如果可能，連選民也迷惑了。","notes":[]},{"n":23,"t":"你們要謹慎！凡事我都預先告訴你們了。」","notes":[]},{"n":24,"t":"「在那些日子、那災難以後，太陽要變黑，月亮也不放光，","notes":[],"heads":["人子的來臨"]},{"n":25,"t":"眾星要從天上墜落，天上的萬象都要震動。","notes":[]},{"n":26,"t":"那時，他們要看見人子帶著大能力和榮耀駕雲來臨。","notes":[]},{"n":27,"t":"他要差遣天使，從四方，從地極直到天邊，召集他的選民。」","notes":[]},{"n":28,"t":"「你們要從無花果樹學習功課：當樹枝發芽長葉的時候，你們就知道夏天近了。","notes":[],"heads":["從無花果樹學功課"]},{"n":29,"t":"同樣，當你們看見這些事發生，就知道那時候近了，就在門口了。","notes":[]},{"n":30,"t":"我實在告訴你們，這世代還沒有過去，這一切都要發生。","notes":[]},{"n":31,"t":"天地要廢去，我的話卻絕不廢去。」","notes":[]},{"n":32,"t":"「但那日子，那時辰，沒有人知道，連天上的天使也不知道，子也不知道，惟有父知道。","notes":[],"heads":["那日那時沒有人知道"]},{"n":33,"t":"你們要謹慎，要警醒，因為你們不知道那時刻幾時來到。","notes":["有古卷加「祈禱」。"]},{"n":34,"t":"這事正如一個人離家遠行，授權給僕人們，分派各人的工作，又吩咐看門的警醒。","notes":[]},{"n":35,"t":"所以，你們要警醒，因為你們不知道這家的主人甚麼時候來，是晚上，或半夜，或雞叫時，或早晨，","notes":[]},{"n":36,"t":"免得他忽然來到，看見你們睡著了。","notes":[]},{"n":37,"t":"我對你們所說的話，也是對眾人說的：要警醒！」","notes":[]}]},"14":{"heading":"殺害耶穌的陰謀","verses":[{"n":1,"t":"過兩天是逾越節，又是除酵節，祭司長和文士在想法子怎樣設計捉拿耶穌，把他殺掉。","notes":[]},{"n":2,"t":"他們說：「不可在過節的日子，恐怕百姓生亂。」","notes":[]},{"n":3,"t":"耶穌在伯大尼痲瘋病人西門家裏坐席的時候，有一個女人拿著一玉瓶極貴的純哪噠香膏來，打破玉瓶，把膏澆在耶穌的頭上。","notes":["「哪噠」即「甘松」。"],"heads":["在伯大尼受膏"]},{"n":4,"t":"有幾個人心中很不高興，說：「何必這樣浪費香膏呢？","notes":[]},{"n":5,"t":"這香膏可以賣三百多個銀幣賙濟窮人。」他們就對那女人生氣。","notes":[]},{"n":6,"t":"耶穌說：「由她吧！為甚麼難為她呢？她在我身上做的是一件美事。","notes":[]},{"n":7,"t":"因為常有窮人和你們在一起，要向他們行善，隨時都可以，但是你們不常有我。","notes":[]},{"n":8,"t":"她所做的是盡她所能的；她是為了我的安葬，把香膏預先澆在我身上。","notes":[]},{"n":9,"t":"我實在告訴你們，普天之下，無論在甚麼地方傳這福音，都要述說這女人所做的，來記念她。」","notes":[]},{"n":10,"t":"十二使徒中有一個加略人猶大，去見祭司長，要把耶穌交給他們。","notes":[],"heads":["猶大出賣耶穌"]},{"n":11,"t":"他們聽見就很高興，又應許給他銀子；他就想怎樣找機會把耶穌交給他們。","notes":[]},{"n":12,"t":"除酵節的第一天，就是宰逾越節羔羊的那一天，門徒對耶穌說：「你要我們到哪裏去預備你吃逾越節的宴席呢？」","notes":[],"heads":["與門徒同守逾越節"]},{"n":13,"t":"耶穌就打發兩個門徒，對他們說：「你們進城去，會有人拿著一罐水迎面而來，你們就跟著他。","notes":[]},{"n":14,"t":"無論他進哪一家，你們就對那家的主人說：『老師問：我的客房在哪裏？我和我的門徒要在那裏吃逾越節的宴席。』","notes":[]},{"n":15,"t":"他會帶你們看一間擺設齊全、準備妥當的樓上大廳，你們就在那裏為我們預備。」","notes":[]},{"n":16,"t":"門徒出去，進了城，所看到的正如耶穌所說的。他們就預備了逾越節的宴席。","notes":[]},{"n":17,"t":"到了晚上，耶穌和十二使徒都來了。","notes":[]},{"n":18,"t":"他們坐席，正吃的時候，耶穌說：「我實在告訴你們，你們中間有一個與我同吃的人要出賣我了。」","notes":[]},{"n":19,"t":"他們就憂愁起來，一個個地問他：「不是我吧？」","notes":[]},{"n":20,"t":"耶穌對他們說：「是十二人中的一個，就是同我蘸餅在盤子裏的那個人。","notes":[]},{"n":21,"t":"人子要去了，正如經上所寫有關他的；但出賣人子的人有禍了！那人沒有出生倒好。」","notes":[]},{"n":22,"t":"他們吃的時候，耶穌拿起餅來，祝福了，就擘開，遞給他們，說：「你們拿去，這是我的身體。」","notes":[],"heads":["設立主的晚餐"]},{"n":23,"t":"他又拿起杯來，祝謝了，遞給他們；他們都喝了。","notes":[]},{"n":24,"t":"耶穌對他們說：「這是我立約的血，為許多人流出來的。","notes":[]},{"n":25,"t":"我實在告訴你們，我不再喝這葡萄汁，直到我在神的國裏喝新的那日子。」","notes":[]},{"n":26,"t":"他們唱了詩，就出來往橄欖山去。","notes":[]},{"n":27,"t":"耶穌對他們說：「你們都要跌倒，因為經上記著：『我要擊打牧人，羊就分散了。』","notes":[],"heads":["預言彼得不認主"]},{"n":28,"t":"但我復活以後，要在你們之前往加利利去。」","notes":[]},{"n":29,"t":"彼得說：「雖然眾人跌倒，但我不會。」","notes":[]},{"n":30,"t":"耶穌對他說：「我實在告訴你，今天夜裏，雞叫兩遍以前，你要三次不認我。」","notes":["有古卷沒有「兩遍」。"]},{"n":31,"t":"彼得卻極力地說：「我就是必須和你同死，也絕不會不認你。」所有的門徒都是這樣說。","notes":["「所有的門徒」：原文直譯「所有的人」。"]},{"n":32,"t":"他們來到一個地方，名叫客西馬尼。耶穌對門徒說：「你們坐在這裏，我去禱告。」","notes":[],"heads":["在客西馬尼禱告"]},{"n":33,"t":"於是他帶著彼得、雅各和約翰同去。他驚恐起來，極其難過，","notes":[]},{"n":34,"t":"對他們說：「我心裏非常憂傷，幾乎要死；你們留在這裏，要警醒。」","notes":[]},{"n":35,"t":"他就稍往前走，俯伏在地，禱告說，如果可能，就叫那時候離開他。","notes":[]},{"n":36,"t":"他說：「阿爸，父啊！在你凡事都能；求你將這杯撤去。然而，不是照我所願的，而是照你所願的。」","notes":[]},{"n":37,"t":"耶穌回來，見他們睡著了，就對彼得說：「西門，你睡著了嗎？不能警醒一小時嗎？","notes":[]},{"n":38,"t":"總要警醒禱告，免得陷入試探。你們心靈固然願意，肉體卻軟弱了。」","notes":[]},{"n":39,"t":"耶穌又去禱告，說的話跟先前一樣。","notes":[]},{"n":40,"t":"他又來，見他們睡著了，因為他們的眼睛很困倦；他們也不知道怎麼回答他。","notes":[]},{"n":41,"t":"他第三次來對他們說：「現在你們仍在睡覺安歇嗎？夠了，時候到了。看哪，人子被出賣在罪人手裏了。","notes":[]},{"n":42,"t":"起來，我們走吧！看哪，那出賣我的人快來了。」","notes":[]},{"n":43,"t":"耶穌還在說話的時候，忽然十二使徒之一的猶大來了，還有一群人帶著刀棒，從祭司長、文士和長老那裏跟他同來。","notes":[],"heads":["耶穌被捕"]},{"n":44,"t":"那出賣耶穌的人曾給他們一個暗號，說：「我親誰，誰就是。你們把他抓住，穩妥地帶走。」","notes":[]},{"n":45,"t":"猶大來了，隨即到耶穌跟前，說：「拉比」，就跟他親吻。","notes":[]},{"n":46,"t":"他們就下手抓住他。","notes":[]},{"n":47,"t":"旁邊站著的人，有一個拔出刀來，把大祭司的僕人砍了一刀，削掉了他一隻耳朵。","notes":[]},{"n":48,"t":"耶穌回應他們說：「你們帶著刀棒出來拿我，如同拿強盜嗎？","notes":[]},{"n":49,"t":"我天天教導人，同你們在殿裏，你們並沒有抓我。但這是要應驗經上的話。」","notes":[]},{"n":50,"t":"門徒都離開他，逃走了。","notes":[]},{"n":51,"t":"有一個青年光著身子，只披一塊麻布，跟隨耶穌，眾人就抓住他。","notes":[],"heads":["逃走的青年"]},{"n":52,"t":"他卻丟下麻布，赤身逃走了。","notes":[]},{"n":53,"t":"他們把耶穌帶到大祭司那裏，又有眾祭司長、長老和文士都來一同聚集。","notes":[],"heads":["耶穌在議會受審"]},{"n":54,"t":"彼得遠遠地跟著耶穌，直到進了大祭司的院子，和警衛一同坐在火邊取暖。","notes":[]},{"n":55,"t":"祭司長和全議會尋找見證控告耶穌，要處死他，卻找不到實據。","notes":[]},{"n":56,"t":"因為有好些人作假見證告他，他們的見證又各不相符。","notes":[]},{"n":57,"t":"又有幾個人站起來，作假見證告他說：","notes":[]},{"n":58,"t":"「我們聽見他說：『我要拆毀這人手所造的殿，三日內另造一座不是人手所造的。』」","notes":[]},{"n":59,"t":"就是這樣，他們的見證還是不相符。","notes":[]},{"n":60,"t":"大祭司起來站在中間，問耶穌說：「這些人作證告你的事，你甚麼都不回答嗎？」","notes":[]},{"n":61,"t":"耶穌卻不言語，一句也不回答。大祭司又問他：「你是不是基督，那當稱頌者的兒子？」","notes":[]},{"n":62,"t":"耶穌說：「我是。你們要看見人子坐在那權能者的右邊，駕著天上的雲來臨。」","notes":[]},{"n":63,"t":"大祭司就撕裂衣服，說：「我們何必再要證人呢？","notes":[]},{"n":64,"t":"你們已經聽見他這褻瀆的話了。你們的決定如何？」他們都判定他該處死。","notes":[]},{"n":65,"t":"於是有人開始向他吐唾沫，又蒙著他的臉，用拳頭打他，對他說：「你說預言吧！」警衛把他拉過來，打他耳光。","notes":[]},{"n":66,"t":"彼得在下邊院子裏，大祭司的一個使女來了，","notes":[],"heads":["彼得三次不認主"]},{"n":67,"t":"見彼得取暖，就看著他，說：「你素來也是同拿撒勒人耶穌一起的。」","notes":[]},{"n":68,"t":"彼得卻不承認，說：「我不知道，也不明白你說的是甚麼！」於是他出來，到了前院，雞就叫了。","notes":["有古卷沒有「雞就叫了」。"]},{"n":69,"t":"那使女看見他，又對旁邊站著的人說：「這個人也是他們一夥的。」","notes":[]},{"n":70,"t":"彼得又不承認。過了不久，旁邊站著的人又對彼得說：「你真是他們一夥的，因為你也是加利利人。」","notes":[]},{"n":71,"t":"彼得就賭咒發誓說：「我不認得你們說的這個人。」","notes":[]},{"n":72,"t":"立刻，雞叫了第二遍。彼得想起耶穌對他所說的話：「雞叫兩遍以前，你要三次不認我。」他就忍不住哭了。","notes":[]}]},"15":{"heading":"耶穌在彼拉多面前受審","verses":[{"n":1,"t":"一到早晨，眾祭司長、長老、文士，和全議會的人大家商議，就把耶穌綁著，解去，交給彼拉多。","notes":[]},{"n":2,"t":"彼拉多問他：「你是猶太人的王嗎？」耶穌回答：「是你說的。」","notes":[]},{"n":3,"t":"祭司長們告他許多的事。","notes":[]},{"n":4,"t":"彼拉多又問他：「你看，他們告你這麼多的事，你甚麼都不回答嗎？」","notes":[]},{"n":5,"t":"耶穌仍不回答，以致彼拉多覺得驚訝。","notes":[]},{"n":6,"t":"每逢這節期，彼拉多照眾人所求的，釋放一個囚犯給他們。","notes":[],"heads":["耶穌被判死刑"]},{"n":7,"t":"有一個人名叫巴拉巴，和作亂的人監禁在一起。他們作亂的時候曾殺過人。","notes":[]},{"n":8,"t":"眾人上去求彼拉多照常例給他們辦理。","notes":[]},{"n":9,"t":"彼拉多說：「你們要我釋放猶太人的王給你們嗎？」","notes":[]},{"n":10,"t":"他原知道祭司長們是因嫉妒才把耶穌解了來。","notes":[]},{"n":11,"t":"但是祭司長們煽動眾人，寧可要他釋放巴拉巴給他們。","notes":[]},{"n":12,"t":"彼拉多又說：「那麼，你們稱為猶太人的王的，要我怎麼辦他呢？」","notes":["「你們…的王的」：有古卷是「猶太人的王」。","有古卷沒有「要」。"]},{"n":13,"t":"他們又再喊著：「把他釘十字架！」","notes":[]},{"n":14,"t":"彼拉多說：「為甚麼？他做了甚麼惡事呢？」他們更加喊著：「把他釘十字架！」","notes":[]},{"n":15,"t":"彼拉多要討好眾人，就釋放巴拉巴給他們，把耶穌鞭打後交給人釘十字架。","notes":[]},{"n":16,"t":"士兵把耶穌帶進總督府的庭院裏，叫齊了全營的兵。","notes":[],"heads":["士兵戲弄耶穌"]},{"n":17,"t":"他們給他穿上紫袍，又用荊棘編了冠冕給他戴上，","notes":[]},{"n":18,"t":"然後向他致敬，說：「萬歲，猶太人的王！」","notes":[]},{"n":19,"t":"他們又拿一根蘆葦稈打他的頭，向他吐唾沫，屈膝拜他。","notes":[]},{"n":20,"t":"他們戲弄完了，就給他脫了紫袍，又穿上他自己的衣服，帶他出去，要把他釘十字架。","notes":[]},{"n":21,"t":"有一個古利奈人西門，就是亞歷山大和魯孚的父親，從鄉下來，經過那地方，他們就強迫他同去，好背耶穌的十字架。","notes":[],"heads":["耶穌被釘十字架"]},{"n":22,"t":"他們帶耶穌到了一個地方叫各各他（翻出來就是「髑髏地」），","notes":[]},{"n":23,"t":"拿沒藥調和的酒給耶穌，他卻不受。","notes":[]},{"n":24,"t":"於是他們把他釘在十字架上，抽籤分他的衣服，看誰得甚麼。","notes":[]},{"n":25,"t":"他們把他釘十字架的時候是上午九點鐘。","notes":[]},{"n":26,"t":"罪狀牌上寫的是：「猶太人的王。」","notes":[]},{"n":27,"t":"他們又把兩個強盜和他同釘十字架，一個在右邊，一個在左邊。","notes":["有古卷加「28 這就應驗了經上的話說：他被列在罪犯之中。」"]},{"n":29,"t":"從那裏經過的人譏笑他，搖著頭，說：「哼！你這拆毀殿、三日又建造起來的，","notes":[]},{"n":30,"t":"救救你自己，從十字架上下來呀！」","notes":[]},{"n":31,"t":"眾祭司長和文士也這樣嘲笑他，彼此說：「他救了別人，不能救自己。","notes":[]},{"n":32,"t":"以色列的王基督，現在從十字架上下來，好讓我們看見就信了呀！」那和他同釘的人也譏諷他。","notes":[]},{"n":33,"t":"到了正午，全地都黑暗了，直到下午三點鐘。","notes":[],"heads":["耶穌之死"]},{"n":34,"t":"下午三點鐘的時候，耶穌大聲呼喊：「以羅伊！以羅伊！拉馬撒巴各大尼？」（翻出來就是：我的神！我的神！為甚麼離棄我？）","notes":[]},{"n":35,"t":"旁邊站著的人，有的聽見就說：「看哪，他叫以利亞呢！」","notes":[]},{"n":36,"t":"有一個人跑去，把海綿蘸滿了醋，綁在蘆葦稈上，送給他喝，說：「且等著，看以利亞會不會來把他放下來。」","notes":[]},{"n":37,"t":"耶穌大喊一聲，氣就斷了。","notes":[]},{"n":38,"t":"殿的幔子從上到下裂為兩半。","notes":[]},{"n":39,"t":"對面站著的百夫長看見耶穌這樣斷氣，就說：「這人真是神的兒子！」","notes":["「這樣斷氣」：有古卷是「這樣喊叫斷氣」。"]},{"n":40,"t":"還有些婦女遠遠地觀看，其中有抹大拉的馬利亞，又有小雅各和約西的母親馬利亞，並有撒羅米，","notes":[]},{"n":41,"t":"就是耶穌在加利利的時候，跟隨他、服事他的那些人，還有同耶穌上耶路撒冷的好些婦女。","notes":[]},{"n":42,"t":"到了晚上，因為這是預備日，就是安息日的前一日，","notes":[],"heads":["耶穌的安葬"]},{"n":43,"t":"有亞利馬太的約瑟前來，他是尊貴的議員，也是盼望著神國的，他放膽進去見彼拉多，請求要耶穌的身體。","notes":[]},{"n":44,"t":"彼拉多詫異耶穌已經死了，就叫百夫長來，問他耶穌是不是死了很久；","notes":[]},{"n":45,"t":"既從百夫長得知實情，就把耶穌的身體賜給約瑟。","notes":[]},{"n":46,"t":"約瑟買了細麻布，把耶穌取下來，用細麻布裹好，安放在巖石中鑿出來的墓穴裏，又滾來一塊石頭擋住墓門。","notes":[]},{"n":47,"t":"抹大拉的馬利亞和約西的母親馬利亞都看見安放他的地方。","notes":[]}]},"16":{"heading":"耶穌復活","verses":[{"n":1,"t":"過了安息日，抹大拉的馬利亞、雅各的母親馬利亞，和撒羅米，買了香料，要去膏耶穌的身體。","notes":[]},{"n":2,"t":"七日的第一日清早，太陽出來後，她們來到墳墓那裏，","notes":[]},{"n":3,"t":"彼此說：「誰要替我們把石頭從墓門滾開呢？」","notes":[]},{"n":4,"t":"她們抬頭一看，看見石頭已經滾開了，原來那石頭很大。","notes":[]},{"n":5,"t":"她們進了墳墓，看見一個年輕人坐在右邊，穿著白袍，就很驚奇。","notes":[]},{"n":6,"t":"那年輕人對她們說：「不要驚慌！你們尋找那釘十字架的拿撒勒人耶穌，他已經復活了，不在這裏。來看安放他的地方。","notes":[]},{"n":7,"t":"你們去，對他的門徒和彼得說：『他要比你們先到加利利去，在那裏你們會看見他，正如他從前所告訴你們的。』」","notes":[]},{"n":8,"t":"於是她們出來，從墳墓那裏逃走，又發抖又驚訝，甚麼也沒有告訴人，因為她們害怕。","notes":[]},{"n":9,"t":"〔 凡耶穌所吩咐的，她們簡潔地告訴彼得和他周圍的人。這些事以後，耶穌親自藉著他的門徒，從東到西，把那神聖、不朽、永遠拯救的福音傳出去。阿們！〕","notes":[],"seq":1,"heads":["．有些古卷有下列結語．","短結語："]},{"n":9,"t":"〔 在七日的第一日清早，耶穌復活了，先向抹大拉的馬利亞顯現；耶穌曾從她身上趕出七個鬼。","notes":[],"seq":2,"heads":["長結語：","向抹大拉的馬利亞顯現"]},{"n":10,"t":"她去告訴那向來跟隨耶穌的人；那時他們正哀慟哭泣。","notes":[]},{"n":11,"t":"他們聽見耶穌活了，被馬利亞看見，可是不信。〕","notes":[]},{"n":12,"t":"〔 這些事以後，門徒中有兩個人往鄉下去；正走著的時候，耶穌以另一種形像向他們顯現。","notes":[],"heads":["向兩個門徒顯現"]},{"n":13,"t":"他們去告訴其餘的門徒，那些門徒還是不信。〕","notes":[]},{"n":14,"t":"〔 後來十一使徒坐席的時候，耶穌向他們顯現，責備他們不信，心裏剛硬，因為他們不信那些在他復活以後看見他的人。","notes":[],"heads":["門徒奉差遣"]},{"n":15,"t":"他又對他們說：「你們往普天下去，傳福音給萬民聽。","notes":["「萬民」：原文直譯「凡受造的」。"]},{"n":16,"t":"信而受洗的必然得救，不信的必被定罪。","notes":[]},{"n":17,"t":"信的人將有神蹟隨著他們：就是奉我的名趕鬼；說新方言；","notes":[]},{"n":18,"t":"手能拿蛇；若喝了甚麼毒物，也不會受害；手按病人，病人就好了。」〕","notes":["有古卷沒有「手」。"]},{"n":19,"t":"〔 主耶穌和他們說完了話以後，被接到天上，坐在神的右邊。","notes":["有古卷是「主耶穌基督」；有古卷是「主」；另有古卷是「耶穌」。"],"heads":["耶穌升天"]},{"n":20,"t":"門徒出去，到處傳福音。主和他們同工，藉著伴隨的神蹟證實所傳的道。〕","notes":["有古卷加「阿們！」"]}]}},"LUK":{"1":{"heading":"預言施洗約翰的出生","verses":[{"n":1,"t":"提阿非羅大人哪，有好些人提筆作書，述說在我們中間所實現的事，是照傳道的人從起初親眼看見又傳給我們的。這些事我從起頭都詳細考察了，我也想按著次序寫給你，","notes":[],"end":3},{"n":4,"t":"要讓你知道所學的道都是確實的。","notes":[]},{"n":5,"t":"在希律作猶太王的時候，亞比雅班裏有一個祭司，名叫撒迦利亞；他妻子是亞倫的後代，名叫伊利莎白。","notes":[]},{"n":6,"t":"他們兩人在神面前都是義人，遵行主的一切誡命和條例，沒有可指責的。","notes":[]},{"n":7,"t":"只是他們沒有孩子，因為伊利莎白不生育，兩個人又年紀老邁了。","notes":[]},{"n":8,"t":"撒迦利亞按班次在神面前執行祭司的職務，","notes":[]},{"n":9,"t":"照祭司的規矩抽籤，進到主的殿裏燒香。","notes":[]},{"n":10,"t":"燒香的時候，眾百姓在外面禱告。","notes":[]},{"n":11,"t":"有主的一個使者站在香壇的右邊，向他顯現。","notes":[]},{"n":12,"t":"撒迦利亞看見，就驚慌害怕。","notes":[]},{"n":13,"t":"天使對他說：「撒迦利亞，不要害怕，因為你的祈禱已經被聽見了。你的妻子伊利莎白要給你生一個兒子，你要給他起名叫約翰。","notes":[]},{"n":14,"t":"你必歡喜快樂；有許多人因他出世也必喜樂。","notes":[]},{"n":15,"t":"他在主面前將要為大，淡酒烈酒都不喝，從母腹裏就被聖靈充滿。","notes":[]},{"n":16,"t":"他要使許多以色列人回轉，歸於主—他們的神。","notes":[]},{"n":17,"t":"他將有以利亞的精神和能力，走在主的前面，叫父親的心轉向兒女，叫悖逆的人轉向義人的智慧，又為主預備迎接他的百姓。」","notes":[]},{"n":18,"t":"撒迦利亞對天使說：「我怎麼能知道這事呢？我已經老了，我的妻子也年紀老邁了。」","notes":[]},{"n":19,"t":"天使回答他說：「我是站在神面前的加百列，奉差遣來對你說話，把這好信息報給你。","notes":[]},{"n":20,"t":"到了時候，這些話必然應驗；只因你不信我的話，你會成為啞巴，不能說話，直到這些事實現的日子。」","notes":[]},{"n":21,"t":"百姓等候撒迦利亞，詫異他在聖所裏遲延那麼久。","notes":[]},{"n":22,"t":"到他出來，卻不能和他們說話，他們就知道他在聖所裏見了異象；他直向他們打手勢，因為他成了啞巴。","notes":[]},{"n":23,"t":"他供職的日子一滿，就回家去了。","notes":[]},{"n":24,"t":"這些日子以後，他的妻子伊利莎白就懷孕，隱藏了五個月；","notes":[]},{"n":25,"t":"她說：「主在眷顧我的日子，這樣看顧我，要除掉我在人前的羞恥。」","notes":[]},{"n":26,"t":"到了第六個月，天使加百列奉神的差遣往加利利的一座城去，這城名叫拿撒勒，","notes":[],"heads":["預言耶穌的降生"]},{"n":27,"t":"到一個童女那裏，她已經許配大衛家的一個人，名叫約瑟；童女的名字叫馬利亞。","notes":[]},{"n":28,"t":"天使進去，對她說：「蒙大恩的女子，你好，主和你同在！」","notes":[]},{"n":29,"t":"馬利亞因這話就很驚慌，又反覆思考這樣問候是甚麼意思。","notes":[]},{"n":30,"t":"天使對她說：「馬利亞，不要怕，你在神面前已經蒙恩了。","notes":[]},{"n":31,"t":"你要懷孕生子，要給他起名叫耶穌。","notes":[]},{"n":32,"t":"他將要為大，稱為至高者的兒子；主神要把他祖先大衛的王位給他。","notes":[]},{"n":33,"t":"他要作雅各家的王，直到永遠；他的國沒有窮盡。」","notes":[]},{"n":34,"t":"馬利亞對天使說：「我沒有出嫁，怎麼會有這事呢？」","notes":[]},{"n":35,"t":"天使回答她說：「聖靈要臨到你身上；至高者的能力要庇蔭你，因此，那要出生的聖者要稱為神的兒子。","notes":["「那要出生的聖者要稱為神的兒子」或譯「那要出生的要稱為聖，為神的兒子」。"]},{"n":36,"t":"況且，你的親戚伊利莎白，就是那素來稱為不生育的，在年老的時候也懷了男胎，現在懷孕六個月了。","notes":[]},{"n":37,"t":"因為，出於神的話，沒有一句不帶能力的。」","notes":[]},{"n":38,"t":"馬利亞說：「我是主的使女，願意照你的話實現在我身上。」於是天使離開她去了。","notes":[]},{"n":39,"t":"在那些日子，馬利亞起身，急忙前往山區，來到猶大的一座城，","notes":[],"heads":["馬利亞看望伊利莎白"]},{"n":40,"t":"進了撒迦利亞的家，向伊利莎白問安。","notes":[]},{"n":41,"t":"伊利莎白一聽到馬利亞問安，所懷的胎就在腹裏跳動。伊利莎白被聖靈充滿，","notes":[]},{"n":42,"t":"高聲喊著說：「你在婦女中是有福的！你所懷的胎也是有福的！","notes":[]},{"n":43,"t":"我主的母親到我這裏來，為何這事臨到我呢？","notes":[]},{"n":44,"t":"因為你問安的聲音一入我耳，我腹裏的胎就歡喜跳動。","notes":[]},{"n":45,"t":"這相信的女子是有福的！因為主對她所說的話都要應驗。」","notes":[]},{"n":46,"t":"馬利亞說：「我心尊主為大；","notes":[],"heads":["馬利亞的尊主頌"]},{"n":47,"t":"我靈以神我的救主為樂；","notes":[]},{"n":48,"t":"因為他顧念他使女的卑微；從今以後，萬代要稱我有福。","notes":[]},{"n":49,"t":"因為那有權能的為我做了大事；他的名是聖的。","notes":[]},{"n":50,"t":"他憐憫敬畏他的人，直到世世代代。","notes":[]},{"n":51,"t":"他用膀臂施展大能；他趕散心裏妄想的狂傲人。","notes":[]},{"n":52,"t":"他叫有權柄的失位，叫卑賤的升高。","notes":[]},{"n":53,"t":"他叫飢餓的飽餐美食，叫富足的空手回去。","notes":[]},{"n":54,"t":"他扶助了他的僕人以色列，不忘記施憐憫，","notes":[]},{"n":55,"t":"正如他對我們的列祖說過，『憐憫亞伯拉罕和他的後裔，直到永遠。』」","notes":[]},{"n":56,"t":"馬利亞和伊利莎白同住，約有三個月，然後回家去了。","notes":[]},{"n":57,"t":"伊利莎白的產期到了，生了一個兒子。","notes":[],"heads":["施洗約翰的出生"]},{"n":58,"t":"鄰里親屬聽見主向她大施憐憫，就和她一同歡樂。","notes":[]},{"n":59,"t":"到了第八日，他們來給孩子行割禮，並要照他父親的名字叫他撒迦利亞。","notes":[]},{"n":60,"t":"他母親回應說：「不！要叫他約翰。」","notes":[]},{"n":61,"t":"他們對她說：「你親族中沒有叫這名字的。」","notes":[]},{"n":62,"t":"他們就向他父親打手勢，問他這孩子要叫甚麼名字。","notes":[]},{"n":63,"t":"他要了一塊寫字的板，寫上：「他的名字是約翰。」他們就都驚訝。","notes":[]},{"n":64,"t":"撒迦利亞的口立刻開了，舌頭也鬆了，就開始說話稱頌神。","notes":[]},{"n":65,"t":"周圍居住的人都懼怕；這一切的事就傳遍了猶太山區。","notes":[]},{"n":66,"t":"凡聽見的人都把這事放在心裏，他們說：「這個孩子將來會怎麼樣呢？」因為有主的手與他同在。","notes":[]},{"n":67,"t":"他父親撒迦利亞被聖靈充滿，就預言說：","notes":[],"heads":["撒迦利亞頌"]},{"n":68,"t":"「主—以色列的神是應當稱頌的！因他眷顧他的百姓，為他們施行救贖，","notes":[]},{"n":69,"t":"在他僕人大衛家中，為我們興起了拯救的角，","notes":[]},{"n":70,"t":"正如主藉著古時候聖先知的口所說的，","notes":[]},{"n":71,"t":"『他拯救我們脫離仇敵，脫離一切恨我們之人的手。","notes":[]},{"n":72,"t":"他向我們列祖施憐憫，記得他的聖約，","notes":[]},{"n":73,"t":"就是他對我們祖宗亞伯拉罕所起的誓，","notes":[]},{"n":74,"t":"叫我們既從仇敵手中被救出來，就可以終身在他面前，無所懼怕地用聖潔和公義事奉他。","notes":[],"end":75},{"n":76,"t":"孩子啊，你要稱為至高者的先知；因為你要走在主的前面，為他預備道路，","notes":[]},{"n":77,"t":"叫他的百姓因罪得赦，認識救恩；","notes":[]},{"n":78,"t":"因我們神憐憫的心腸，叫清晨的日光從高天臨到我們，","notes":[]},{"n":79,"t":"要照亮坐在黑暗中死蔭裏的人，把我們的腳引到和平的路上。』」","notes":[]},{"n":80,"t":"這孩子漸漸長大，心靈堅強，住在曠野，直到他在以色列人面前公開出現的日子。","notes":[]}]},"2":{"heading":"耶穌降生","verses":[{"n":1,"t":"在那些日子，凱撒奧古斯都降旨，叫全國人民都登記戶籍。","notes":[]},{"n":2,"t":"這第一次登記戶籍是在居里扭作敘利亞總督的時候行的。","notes":[]},{"n":3,"t":"眾人各歸各城，辦理登記。","notes":[]},{"n":4,"t":"約瑟也從加利利的拿撒勒城上猶太去，到了大衛的城名叫伯利恆，因為他是大衛家族的人，","notes":[]},{"n":5,"t":"要和他所聘之妻馬利亞一同登記戶籍。那時馬利亞已經懷孕。","notes":[]},{"n":6,"t":"他們在那裏的時候，馬利亞的產期到了，","notes":[]},{"n":7,"t":"就生了頭胎的兒子，用布包起來，放在馬槽裏，因為客店裏沒有地方。","notes":[]},{"n":8,"t":"在伯利恆的野外有牧羊人，夜間值班看守羊群。","notes":["「在伯利恆」：原文直譯「在同一個區域」。"],"heads":["天使報喜訊給牧羊人"]},{"n":9,"t":"有主的一個使者站在他們旁邊，主的榮光四面照著他們，牧羊人就很懼怕。","notes":[]},{"n":10,"t":"那天使對他們說：「不要懼怕！看哪！因為我報給你們大喜的信息，是關乎萬民的：","notes":[]},{"n":11,"t":"因今天在大衛的城裏，為你們生了救主，就是主基督。","notes":[]},{"n":12,"t":"你們要看見一個嬰孩，包著布，臥在馬槽裏，那就是給你們的記號。」","notes":[]},{"n":13,"t":"忽然，有一大隊天兵同那天使讚美神說：","notes":[]},{"n":14,"t":"「在至高之處榮耀歸與神！在地上平安歸與他所喜悅的人！」","notes":[]},{"n":15,"t":"眾天使離開他們，升天去了。牧羊人彼此說：「我們往伯利恆去，看看所成的事，就是主所告訴我們的。」","notes":[]},{"n":16,"t":"他們急忙去了，找到馬利亞和約瑟，還有那嬰孩臥在馬槽裏。","notes":[]},{"n":17,"t":"他們看見，就把天使論這孩子的話傳開了。","notes":[]},{"n":18,"t":"聽見的人都詫異牧羊人對他們所說的話。","notes":[]},{"n":19,"t":"馬利亞卻把這一切的事存在心裏，反覆思考。","notes":[]},{"n":20,"t":"牧羊人回去了，因所聽見所看見的一切事，正如天使向他們所說的，就歸榮耀於神，讚美他。","notes":[]},{"n":21,"t":"滿了八天，他們就給孩子行割禮，又給他起名叫耶穌；這是他還沒有在母腹裏成胎以前天使所起的名。","notes":[]},{"n":22,"t":"按摩西律法滿了潔淨的日子，他們就帶著孩子上耶路撒冷去，要把他獻給主。","notes":[],"heads":["把耶穌獻給主"]},{"n":23,"t":"正如主的律法上所記：「凡頭生的男子必歸主為聖」；","notes":[]},{"n":24,"t":"又要照主的律法上所說，用一對斑鳩，或用兩隻雛鴿獻祭。","notes":[]},{"n":25,"t":"那時，在耶路撒冷有一個人，名叫西面；這人又公義又虔誠，素常盼望以色列的安慰者來到，又有聖靈在他身上。","notes":[]},{"n":26,"t":"他得了聖靈的啟示，知道自己未死以前必看見主所立的基督。","notes":[]},{"n":27,"t":"他受了聖靈的感動，進入聖殿，正遇見耶穌的父母抱著孩子進來，要照律法的規矩而行。","notes":[]},{"n":28,"t":"西面就把他抱過來，稱頌神說：","notes":[]},{"n":29,"t":"「主啊，如今可以照你的話，容你的僕人安然去世；","notes":[]},{"n":30,"t":"因為我的眼睛已經看見你的救恩，","notes":[]},{"n":31,"t":"就是你在萬民面前所預備的：","notes":[]},{"n":32,"t":"是啟示外邦人的光，是你民以色列的榮耀。」","notes":[]},{"n":33,"t":"孩子的父母因論耶穌的這些話就驚訝。","notes":[]},{"n":34,"t":"西面給他們祝福，又對孩子的母親馬利亞說：「這孩子被立，是要叫以色列中許多人跌倒，許多人興起；又要成為毀謗的對象，","notes":[]},{"n":35,"t":"叫許多人心裏的意念顯露出來；你自己的心也要被劍刺透。」","notes":[]},{"n":36,"t":"又有位女先知，名叫亞拿，是亞設支派法內力的女兒，年紀已經老邁，從童女出嫁，同丈夫住了七年，","notes":[]},{"n":37,"t":"就寡居了，現在已經八十四歲。她不離開聖殿，禁食祈求，晝夜事奉神。","notes":["「就寡居了，現在已經八十四歲」或譯「就寡居了八十四年」。"]},{"n":38,"t":"正當那時，她進前來感謝神，對一切盼望耶路撒冷得救贖的人講論這孩子的事。","notes":[]},{"n":39,"t":"約瑟和馬利亞照主的律法辦完了一切的事，就回加利利，到自己的城拿撒勒去了。","notes":[],"heads":["回拿撒勒"]},{"n":40,"t":"孩子漸漸長大，強健起來，充滿智慧，又有神的恩典在他身上。","notes":[]},{"n":41,"t":"每年逾越節，他父母都上耶路撒冷去。","notes":[],"heads":["少年耶穌在聖殿裏"]},{"n":42,"t":"當他十二歲的時候，他們按著過節的規矩上去。","notes":[]},{"n":43,"t":"守滿了節期，他們回去，孩童耶穌仍舊在耶路撒冷。他的父母並不知道，","notes":[]},{"n":44,"t":"以為他在同行的人中間，走了一天的路程才在親屬和熟悉的人中找他，","notes":[]},{"n":45,"t":"既找不著，就回耶路撒冷去找他。","notes":[]},{"n":46,"t":"過了三天，他們發現他在聖殿裏，坐在教師中間，一面聽，一面問。","notes":[]},{"n":47,"t":"凡聽見他的人都對他的聰明和應對感到驚奇。","notes":[]},{"n":48,"t":"他父母看見就很驚奇。他母親對他說：「我兒啊，為甚麼對我們這樣做呢？看哪，你父親和我很焦急，到處找你！」","notes":[]},{"n":49,"t":"耶穌對他們說：「為甚麼找我呢？難道你們不知道我應當在我父的家裏嗎？」","notes":["「難道你們不知道我應當在我父的家裏嗎？」或譯「難道你們不知道我應當以我父的事為念嗎？」"]},{"n":50,"t":"他所說的這話，他們不明白。","notes":[]},{"n":51,"t":"他就同他們下去，回到拿撒勒，並且順從他們。他母親把這一切的事都存在心裏。","notes":[]},{"n":52,"t":"耶穌的智慧和身量，並神和人喜愛他的心，都一齊增長。","notes":["「身量」或譯「年紀」。"]}]},"3":{"heading":"施洗約翰傳道","verses":[{"n":1,"t":"凱撒提庇留在位第十五年，本丟‧彼拉多作猶太總督，希律作加利利分封的王，他兄弟腓力作以土利亞和特拉可尼地區分封的王，呂撒聶作亞比利尼分封的王，","notes":[]},{"n":2,"t":"亞那和該亞法作大祭司。那時，撒迦利亞的兒子約翰在曠野裏，神的話臨到他。","notes":[]},{"n":3,"t":"他就走遍約旦河一帶地方，宣講悔改的洗禮，使罪得赦。","notes":[]},{"n":4,"t":"正如以賽亞先知書上所記的話：「在曠野有聲音呼喊著：預備主的道，修直他的路！","notes":[]},{"n":5,"t":"一切山窪都要填滿；大小山岡都要削平！彎彎曲曲的地方要改為筆直；高高低低的道路要改為平坦！","notes":[]},{"n":6,"t":"凡有血肉之軀的，都要看見神的救恩！」","notes":[]},{"n":7,"t":"約翰對那出來要受他洗的眾人說：「毒蛇的孽種啊，誰指示你們逃避那將要來的憤怒呢？","notes":[]},{"n":8,"t":"你們要結出果子來，和悔改的心相稱。不要自己心裏說：『我們有亞伯拉罕為祖宗。』我告訴你們，神能從這些石頭中給亞伯拉罕興起子孫來。","notes":[]},{"n":9,"t":"現在斧子已經放在樹根上，凡不結好果子的樹就砍下來，丟在火裏。」","notes":[]},{"n":10,"t":"眾人問他：「這樣，我們該做甚麼呢？」","notes":[]},{"n":11,"t":"約翰回答：「有兩件衣裳的，就分給那沒有的；有食物的，也該這樣做。」","notes":[]},{"n":12,"t":"也有稅吏來要受洗，對他說：「老師，我們該做甚麼呢？」","notes":[]},{"n":13,"t":"約翰對他們說：「除了規定的數目，不要多收。」","notes":[]},{"n":14,"t":"也有士兵問他說：「我們該做甚麼呢？」約翰說：「不要勒索任何人，也不要敲詐人；自己有糧餉就該知足。」","notes":[]},{"n":15,"t":"百姓期待基督的來臨；他們心裏猜測，或許約翰是基督。","notes":[]},{"n":16,"t":"約翰對眾人說：「我是用水給你們施洗，但有一位能力比我更大的要來，我就是給他解鞋帶也不配。他要用聖靈與火給你們施洗。","notes":[]},{"n":17,"t":"他手裏拿著簸箕，要揚淨他的穀物，把麥子收在倉裏，把糠用不滅的火燒盡。」","notes":[]},{"n":18,"t":"約翰又用許多別的話勸百姓，向他們傳福音。","notes":[]},{"n":19,"t":"希律分封王，因他兄弟之妻希羅底的緣故，並因他所做的一切惡事，受了約翰的責備。","notes":[]},{"n":20,"t":"希律在一切事上又添了這一件，就是把約翰收在監裏。","notes":[]},{"n":21,"t":"眾百姓都受了洗，耶穌也受了洗。他正禱告的時候，天開了，","notes":[],"heads":["耶穌受洗"]},{"n":22,"t":"聖靈降在他身上，形狀彷彿鴿子；又有聲音從天上來，說：「你是我的愛子，我喜愛你。」","notes":[]},{"n":23,"t":"耶穌開始傳道，年紀約有三十歲。依人看來，他是約瑟的兒子，約瑟是希里的兒子，","notes":[],"heads":["耶穌的家譜"]},{"n":24,"t":"希里是瑪塔的兒子，瑪塔是利未的兒子，利未是麥基的兒子，麥基是雅拿的兒子，雅拿是約瑟的兒子，","notes":[]},{"n":25,"t":"約瑟是瑪他提亞的兒子，瑪他提亞是亞摩斯的兒子，亞摩斯是拿鴻的兒子，拿鴻是以斯利的兒子，以斯利是拿該的兒子，","notes":[]},{"n":26,"t":"拿該是瑪押的兒子，瑪押是瑪他提亞的兒子，瑪他提亞是西美的兒子，西美是約瑟的兒子，約瑟是猶大的兒子，猶大是約亞拿的兒子，","notes":[]},{"n":27,"t":"約亞拿是利撒的兒子，利撒是所羅巴伯的兒子，所羅巴伯是撒拉鐵的兒子，撒拉鐵是尼利的兒子，尼利是麥基的兒子，","notes":[]},{"n":28,"t":"麥基是亞底的兒子，亞底是哥桑的兒子，哥桑是以摩當的兒子，以摩當是珥的兒子，珥是約細的兒子，","notes":[]},{"n":29,"t":"約細是以利以謝的兒子，以利以謝是約令的兒子，約令是瑪塔的兒子，瑪塔是利未的兒子，","notes":[]},{"n":30,"t":"利未是西緬的兒子，西緬是猶大的兒子，猶大是約瑟的兒子，約瑟是約南的兒子，約南是以利亞敬的兒子，","notes":[]},{"n":31,"t":"以利亞敬是米利亞的兒子，米利亞是買南的兒子，買南是瑪達他的兒子，瑪達他是拿單的兒子，拿單是大衛的兒子，","notes":[]},{"n":32,"t":"大衛是耶西的兒子，耶西是俄備得的兒子，俄備得是波阿斯的兒子，波阿斯是沙拉的兒子，沙拉是拿順的兒子，","notes":["有古卷是「波阿斯是撒門的兒子，撒門是拿順的兒子」。"]},{"n":33,"t":"拿順是亞米拿達的兒子，亞米拿達是亞民的兒子，亞民是亞尼的兒子，亞尼是希斯崙的兒子，希斯崙是法勒斯的兒子，法勒斯是猶大的兒子，","notes":["有古卷是「亞米拿達是亞蘭的兒子，亞蘭是希斯崙的兒子」；其他古卷的內文有許多不同。"]},{"n":34,"t":"猶大是雅各的兒子，雅各是以撒的兒子，以撒是亞伯拉罕的兒子，亞伯拉罕是他拉的兒子，他拉是拿鶴的兒子，","notes":[]},{"n":35,"t":"拿鶴是西鹿的兒子，西鹿是拉吳的兒子，拉吳是法勒的兒子，法勒是希伯的兒子，希伯是沙拉的兒子，","notes":[]},{"n":36,"t":"沙拉是該南的兒子，該南是亞法撒的兒子，亞法撒是閃的兒子，閃是挪亞的兒子，挪亞是拉麥的兒子，","notes":[]},{"n":37,"t":"拉麥是瑪土撒拉的兒子，瑪土撒拉是以諾的兒子，以諾是雅列的兒子，雅列是瑪勒列的兒子，瑪勒列是該南的兒子，該南是以挪士的兒子，","notes":[]},{"n":38,"t":"以挪士是塞特的兒子，塞特是亞當的兒子，亞當是神的兒子。","notes":[]}]},"4":{"heading":"耶穌受試探","verses":[{"n":1,"t":"耶穌滿有聖靈，從約旦河回來，聖靈把他引到曠野，","notes":[]},{"n":2,"t":"四十天受魔鬼的試探。在那些日子，他沒有吃甚麼，日子滿了，他餓了。","notes":[]},{"n":3,"t":"魔鬼對他說：「你若是神的兒子，叫這塊石頭變成食物吧。」","notes":[]},{"n":4,"t":"耶穌回答說：「經上記著：『人活著，不是單靠食物。』」","notes":["有古卷加「乃是靠神口裏所出的一切話。」"]},{"n":5,"t":"魔鬼又領他上了高山，霎時間把天下萬國都指給他看，","notes":[]},{"n":6,"t":"對他說：「這一切權柄和榮華我都要給你，因為這原是交給我的，我願意給誰就給誰。","notes":[]},{"n":7,"t":"你若在我面前下拜，這一切都歸你。」","notes":[]},{"n":8,"t":"耶穌回答他說：「經上記著：『要拜主—你的神，惟獨事奉他。』」","notes":[]},{"n":9,"t":"魔鬼又領他到耶路撒冷去，叫他站在聖殿頂上，對他說：「你若是神的兒子，從這裏跳下去！","notes":[]},{"n":10,"t":"因為經上記著：『主要為你命令他的使者保護你；","notes":[]},{"n":11,"t":"他們要用手托住你，免得你的腳碰在石頭上。』」","notes":[]},{"n":12,"t":"耶穌回答他說：「經上說：『不可試探主—你的神。』」","notes":[]},{"n":13,"t":"魔鬼用完了各樣的試探，就離開耶穌，再等時機。","notes":[]},{"n":14,"t":"耶穌帶著聖靈的能力回到加利利，他的名聲傳遍了四方。","notes":[],"heads":["開始在加利利傳道"]},{"n":15,"t":"他在各會堂裏教導人，眾人都稱讚他。","notes":[]},{"n":16,"t":"耶穌來到拿撒勒，就是他長大的地方。在安息日，照他素常的規矩進了會堂，站起來要念聖經。","notes":[],"heads":["拿撒勒人厭棄耶穌"]},{"n":17,"t":"有人把以賽亞先知的書交給他，他就打開，找到一處寫著：","notes":[]},{"n":18,"t":"「主的靈在我身上，因為他用膏膏我，叫我傳福音給貧窮的人；差遣我宣告：被擄的得釋放，失明的得看見，受壓迫的得自由，","notes":[]},{"n":19,"t":"宣告神悅納人的禧年。」","notes":[]},{"n":20,"t":"於是他把書捲起來，交還給管理人，就坐下。會堂裏的人都定睛看他。","notes":[]},{"n":21,"t":"耶穌對他們說：「你們聽見的這段經文，今天已經應驗了。」","notes":[]},{"n":22,"t":"眾人都稱讚他，並對他口中所出的恩言感到驚訝；他們說：「這不是約瑟的兒子嗎？」","notes":[]},{"n":23,"t":"耶穌對他們說：「你們一定會用這俗語向我說：『醫生，你醫治自己吧！我們聽見你在迦百農所做的事，也該在你自己的家鄉做吧。』」","notes":[]},{"n":24,"t":"他又說：「我實在告訴你們，沒有先知在自己家鄉被人接納的。","notes":[]},{"n":25,"t":"我對你們說實話，在以利亞的時候，天閉塞了三年六個月，遍地有大饑荒，那時，以色列中有許多寡婦，","notes":[]},{"n":26,"t":"以利亞並沒有奉差往她們中任何一個人那裏去，只奉差往西頓的撒勒法一個寡婦那裏去。","notes":[]},{"n":27,"t":"在以利沙先知的時候，以色列中有許多痲瘋病人，但除了敘利亞的乃縵，沒有一個得潔淨的。」","notes":[]},{"n":28,"t":"會堂裏的人聽見這些話，都怒氣填胸，","notes":[]},{"n":29,"t":"就起來趕他出城。他們的城造在山上；他們帶他到山崖，要把他推下去。","notes":[]},{"n":30,"t":"他卻從他們中間穿過去，走了。","notes":[]},{"n":31,"t":"耶穌下到迦百農，就是加利利的一座城，在安息日教導眾人。","notes":[],"heads":["耶穌趕逐污靈"]},{"n":32,"t":"他們對他的教導感到很驚奇，因為他的話裏有權柄。","notes":[]},{"n":33,"t":"在會堂裏有一個人，被污鬼的靈附著，大聲喊叫說：","notes":[]},{"n":34,"t":"「唉！拿撒勒人耶穌，你為甚麼干擾我們？你來消滅我們嗎？我知道你是誰，你是神的聖者。」","notes":[]},{"n":35,"t":"耶穌斥責他說：「不要作聲，從這人身上出來吧！」鬼把那人摔倒在眾人中間，就出來了，卻沒有傷害他。","notes":[]},{"n":36,"t":"眾人都驚訝，彼此對問：「這是甚麼道理呢？因為他用權柄能力命令污靈，污靈就出來。」","notes":[]},{"n":37,"t":"於是耶穌的名聲傳遍了周圍各地。","notes":[]},{"n":38,"t":"耶穌出了會堂，進了西門的家。西門的岳母在發高燒，有些人為她求耶穌。","notes":[],"heads":["治好許多病人"]},{"n":39,"t":"耶穌站在她旁邊，斥責那高燒，燒就退了。她立刻起來服事他們。","notes":[]},{"n":40,"t":"日落的時候，凡有病人的，不論害甚麼病，都帶到耶穌那裏。耶穌給他們每一個人按手，治好他們。","notes":[]},{"n":41,"t":"又有鬼從好些人身上出來，喊著說：「你是神的兒子！」耶穌斥責他們，不許他們說話，因為他們知道他是基督。","notes":[]},{"n":42,"t":"天亮的時候，耶穌出來，走到荒野的地方。眾人去找他，到了他那裏，要留住他，不讓他離開他們。","notes":[],"heads":["在猶太傳道"]},{"n":43,"t":"但耶穌對他們說：「我也必須在別的城傳神國的福音，因我奉差原是為此。」","notes":[]},{"n":44,"t":"於是耶穌在猶太的各會堂傳道。","notes":[]}]},"5":{"heading":"耶穌呼召早先的門徒","verses":[{"n":1,"t":"耶穌站在革尼撒勒湖邊，眾人擁擠他，要聽神的道。","notes":[]},{"n":2,"t":"他見有兩隻船靠在湖邊，打魚的人卻離開船，洗網去了。","notes":[]},{"n":3,"t":"有一隻船是西門的，耶穌就上去，請他把船撐開，稍微離岸，就坐下，在船上教導眾人。","notes":[]},{"n":4,"t":"他講完了，對西門說：「把船開到水深的地方下網打魚。」","notes":[]},{"n":5,"t":"西門說：「老師，我們整夜勞累，並沒有打著甚麼。但依從你的話，我就下網。」","notes":[]},{"n":6,"t":"他們下了網，圈住許多魚，網險些裂開，","notes":[]},{"n":7,"t":"就招手叫另一隻船上的同伴來幫助。他們就來，把魚裝滿了兩隻船，船甚至要沉下去。","notes":[]},{"n":8,"t":"西門‧彼得看見，就俯伏在耶穌膝前，說：「主啊，離開我，我是個罪人。」","notes":[]},{"n":9,"t":"他和一切跟他一起的人對打到了這一網的魚都很驚訝。","notes":[]},{"n":10,"t":"他的夥伴西庇太的兒子雅各、約翰，也是這樣。耶穌對西門說：「不要怕！從今以後，你要得人了。」","notes":[]},{"n":11,"t":"他們把兩隻船靠了岸，就撇下所有的，跟從了耶穌。","notes":[]},{"n":12,"t":"有一回，耶穌在一個城裏，有人滿身長了痲瘋，看見他，就俯伏在地，求他說：「主啊，你若肯，你能使我潔淨。」","notes":[],"heads":["潔淨痲瘋病人"]},{"n":13,"t":"耶穌伸手摸他，說：「我肯，你潔淨了吧！」痲瘋病立刻離開了他。","notes":[]},{"n":14,"t":"耶穌吩咐他：「你不可告訴任何人，只要去，把自己給祭司察看，又因為你已經潔淨，要照摩西所吩咐的獻上祭物，作為證據給眾人看。」","notes":[]},{"n":15,"t":"但耶穌的名聲越發傳揚出去。有一大群人聚集來聽道，也希望耶穌醫治他們的病。","notes":[]},{"n":16,"t":"耶穌卻退到曠野去禱告。","notes":[]},{"n":17,"t":"有一天，耶穌教導人，有法利賽人和律法教師在旁邊坐著；他們是從加利利各鄉村、猶太和耶路撒冷來的。主的能力與耶穌同在，使他能治好病人。","notes":[],"heads":["治好癱子"]},{"n":18,"t":"這時，有些人用褥子抬著一個癱子，要把他抬進去放在耶穌面前，","notes":[]},{"n":19,"t":"卻因人多，找不出法子抬進去，就上了房頂，從瓦間把他連褥子縋到當中，在耶穌面前。","notes":[]},{"n":20,"t":"耶穌見他們的信心，就說：「朋友，你的罪赦了。」","notes":[]},{"n":21,"t":"文士和法利賽人就開始議論說：「這個人是誰，竟說褻瀆的話？除了神一位之外，誰能赦罪呢？」","notes":[]},{"n":22,"t":"耶穌知道他們所議論的，就回答他們說：「你們心裏為甚麼議論呢？","notes":[]},{"n":23,"t":"說『你的罪赦了』，或說『你起來行走』，哪一樣容易呢？","notes":[]},{"n":24,"t":"但要讓你們知道，人子在地上有赦罪的權柄。」他就對癱子說：「我吩咐你，起來！拿你的褥子回家去吧。」","notes":[]},{"n":25,"t":"那人當著眾人面前立刻起來，拿了他所躺臥的褥子回家去，歸榮耀給神。","notes":[]},{"n":26,"t":"眾人都驚奇，也歸榮耀給神，並且滿心懼怕，說：「我們今日看見不尋常的事了！」","notes":[]},{"n":27,"t":"這些事以後，耶穌出去，看見一個稅吏，名叫利未，在稅關坐著，就對他說：「來跟從我！」","notes":[],"heads":["呼召利未"]},{"n":28,"t":"他就撇下所有的，起來跟從耶穌。","notes":[]},{"n":29,"t":"利未在自己家裏為耶穌大擺宴席，有一大群稅吏和別的人與他們一同坐席。","notes":[]},{"n":30,"t":"法利賽人和文士就向耶穌的門徒發怨言說：「你們為甚麼跟稅吏和罪人一同吃喝呢？」","notes":[]},{"n":31,"t":"耶穌回答他們：「健康的人用不著醫生；有病的人才用得著。","notes":[]},{"n":32,"t":"我不是來召義人悔改，而是召罪人悔改。」","notes":[]},{"n":33,"t":"他們對耶穌說：「約翰的門徒常常禁食祈禱，法利賽人的門徒也是這樣，惟獨跟你在一起的又吃又喝。」","notes":[],"heads":["禁食的問題"]},{"n":34,"t":"耶穌對他們說：「新郎和賓客在一起的時候，你們怎麼能叫賓客禁食呢？","notes":[]},{"n":35,"t":"但日子將到，新郎要被帶走，那些日子他們就要禁食了。」","notes":[]},{"n":36,"t":"耶穌又講一個比喻，對他們說：「沒有人把新衣服撕下一塊來補在舊衣服上，若是這樣，會把新的撕裂了，並且所撕下來的那塊新的和舊的也不相稱。","notes":[]},{"n":37,"t":"也沒有人把新酒裝在舊皮袋裏；若是這樣，新酒會脹破皮袋，酒就漏出來，皮袋也糟蹋了。","notes":[]},{"n":38,"t":"相反地，新酒必須裝在新皮袋裏。","notes":[]},{"n":39,"t":"沒有人喝了陳酒又想喝新的；他總說陳的好。」","notes":[]}]},"6":{"heading":"在安息日摘麥穗","verses":[{"n":1,"t":"有一個安息日，耶穌從麥田經過。他的門徒摘了麥穗，用手搓著吃。","notes":["有古卷是「在第二個首安息日」。"]},{"n":2,"t":"有幾個法利賽人說：「你們為甚麼做安息日不合法的事呢？」","notes":[]},{"n":3,"t":"耶穌回答他們：「大衛和跟從他的人飢餓時所做的事，你們沒有念過嗎？","notes":[]},{"n":4,"t":"他怎麼進了神的居所，拿供餅吃，又給跟從的人吃呢？這餅惟獨祭司可以吃，別人都不可以吃。」","notes":[]},{"n":5,"t":"他又對他們說：「人子是安息日的主。」","notes":[]},{"n":6,"t":"又有一個安息日，耶穌進了會堂教導人，在那裏有一個人，他的右手萎縮了。","notes":[],"heads":["治好萎縮的手"]},{"n":7,"t":"文士和法利賽人窺探耶穌會不會在安息日治病，為要找把柄告他。","notes":[]},{"n":8,"t":"耶穌卻知道他們的意念，就對那萎縮了手的人說：「起來，站在當中！」那人就起來，站著。","notes":[]},{"n":9,"t":"耶穌對他們說：「我問你們，在安息日行善行惡，救命害命，哪樣是合法的呢？」","notes":[]},{"n":10,"t":"他就環視眾人，對那人說：「伸出手來！」他照著做，他的手就復原了。","notes":[]},{"n":11,"t":"他們怒氣填胸，彼此商議怎樣對付耶穌。","notes":[]},{"n":12,"t":"在那些日子，耶穌出去，上山祈禱，整夜向神禱告。","notes":[],"heads":["揀選十二使徒"]},{"n":13,"t":"到了天亮，他叫門徒來，就從他們中間挑選十二個人，稱他們為使徒。","notes":[]},{"n":14,"t":"這十二個人有西門（耶穌又給他起名叫彼得），還有他弟弟安得烈，又有雅各和約翰，腓力和巴多羅買，","notes":[]},{"n":15,"t":"馬太和多馬，亞勒腓的兒子雅各和激進黨的西門，","notes":[]},{"n":16,"t":"雅各的兒子猶大和後來成為出賣者的加略人猶大。","notes":[]},{"n":17,"t":"耶穌和他們下了山，站在一塊平地上；在一起的有許多門徒，又有許多百姓從全猶太和耶路撒冷，並推羅、西頓的海邊來，","notes":[],"heads":["向大眾傳道"]},{"n":18,"t":"都要聽他講道，又希望耶穌醫治他們的病；還有被污靈纏磨的，也得了醫治。","notes":[]},{"n":19,"t":"眾人都想要摸他，因為有能力從他身上發出來，治好了他們。","notes":[]},{"n":20,"t":"耶穌舉目看著門徒，說：「貧窮的人有福了！因為神的國是你們的。","notes":[],"heads":["論福與禍"]},{"n":21,"t":"現在飢餓的人有福了！因為你們將得飽足。現在哭泣的人有福了！因為你們將要歡笑。","notes":[]},{"n":22,"t":"人為人子的緣故憎恨你們，拒絕你們，辱罵你們，把你們當惡人除掉你們的名，你們就有福了！","notes":[]},{"n":23,"t":"在那日，你們要歡欣雀躍，因為你們在天上的賞賜是很多的；他們的祖宗也是這樣待先知的。","notes":[]},{"n":24,"t":"但你們富足的人有禍了！因為你們已經受過安慰。","notes":[]},{"n":25,"t":"你們現在飽足的人有禍了！因為你們將要飢餓。你們現在歡笑的人有禍了！因為你們將要哀慟哭泣。","notes":[]},{"n":26,"t":"人都說你們好的時候，你們有禍了！因為他們的祖宗也是這樣待假先知的。」","notes":[]},{"n":27,"t":"「可是我告訴你們這些聽的人，要愛你們的仇敵！要善待恨你們的人！","notes":[],"heads":["論愛仇敵"]},{"n":28,"t":"要祝福詛咒你們的人！要為凌辱你們的人禱告！","notes":[]},{"n":29,"t":"有人打你的臉，連另一邊也由他打。有人拿你的外衣，連內衣也由他拿去。","notes":[]},{"n":30,"t":"凡求你的，就給他；有人拿走你的東西，不要討回來。","notes":[]},{"n":31,"t":"「你們想要人怎樣待你們，你們也要怎樣待人。","notes":[]},{"n":32,"t":"你們若只愛那愛你們的人，有甚麼可感謝的呢？就是罪人也愛那愛他們的人。","notes":[]},{"n":33,"t":"你們若善待那善待你們的人，有甚麼可感謝的呢？就是罪人也是這樣做。","notes":[]},{"n":34,"t":"你們若借給人，希望從他收回，有甚麼可感謝的呢？就是罪人也借給罪人，再如數收回。","notes":[]},{"n":35,"t":"你們倒要愛仇敵，要善待他們，並要借給人不指望償還，你們的賞賜就很多了，你們必作至高者的兒子，因為他恩待那忘恩的和作惡的。","notes":[]},{"n":36,"t":"你們要仁慈，像你們的父是仁慈的。」","notes":[]},{"n":37,"t":"「你們不要評斷別人，就不被審判；你們不要定人的罪，就不被定罪；你們要饒恕人，就必蒙饒恕。","notes":[],"heads":["不要評斷人"]},{"n":38,"t":"你們要給人，就必有給你們的，並且用十足的升斗，連搖帶按，上尖下流地倒在你們懷裏；因為你們用甚麼量器量給人，也必用甚麼量器量給你們。」","notes":[]},{"n":39,"t":"耶穌又用比喻對他們說：「瞎子豈能領瞎子，兩個人不是都要掉在坑裏嗎？","notes":[]},{"n":40,"t":"學生不高過老師，凡學成了的會和老師一樣。","notes":[]},{"n":41,"t":"為甚麼看見你弟兄眼中有刺，卻不想自己眼中有梁木呢？","notes":[]},{"n":42,"t":"你不見自己眼中有梁木，怎能對你弟兄說：『讓我去掉你眼中的刺』呢？你這假冒為善的人！先去掉自己眼中的梁木，然後才能看得清楚，好去掉你弟兄眼中的刺。」","notes":[]},{"n":43,"t":"「沒有好樹結壞果子，也沒有壞樹結好果子。","notes":[],"heads":["樹和果子"]},{"n":44,"t":"每一種樹木可以從其果子看出來。人不是從荊棘上摘無花果的，也不是從蒺藜裏摘葡萄的。","notes":[]},{"n":45,"t":"善人從他心裏所存的善發出善來，惡人從他所存的惡發出惡來；因為心裏所充滿的，口裏就說出來。」","notes":[]},{"n":46,"t":"「你們為甚麼稱呼我『主啊，主啊』，卻不照我的話做呢？","notes":[],"heads":["兩種根基"]},{"n":47,"t":"凡到我這裏來，聽了我的話又去做的，我要告訴你們他像甚麼人：","notes":[]},{"n":48,"t":"他像一個人蓋房子，把地挖深，將根基立在磐石上，到發大水的時候，水沖那房子，房子總不動搖，因為蓋造得好。","notes":[]},{"n":49,"t":"但聽了不去做的，就像一個人在土地上蓋房子，沒有根基，水一沖，立刻倒塌了，並且那房子損壞得很厲害。」","notes":[]}]},"7":{"heading":"治好百夫長的僮僕","verses":[{"n":1,"t":"耶穌對百姓講完了這一切的話，就進了迦百農。","notes":[]},{"n":2,"t":"有一個百夫長所器重的僕人害病，快要死了。","notes":[]},{"n":3,"t":"百夫長風聞耶穌的事，就託猶太人的幾個長老去求耶穌來救他的僕人。","notes":[]},{"n":4,"t":"他們到了耶穌那裏，切切地求他說：「你為他做這事是他配得的；","notes":[]},{"n":5,"t":"因為他愛我們的民族，為我們建造會堂。」","notes":[]},{"n":6,"t":"耶穌就和他們同去。離那家不遠，百夫長託幾個朋友去見耶穌，對他說：「主啊，不必勞駕，因你到舍下來，我不敢當。","notes":[]},{"n":7,"t":"我也自以為不配去見你，只要你說一句話，就會讓我的僮僕得痊癒。","notes":[]},{"n":8,"t":"因為我被派在人的權下，也有兵在我之下。我對這個說：『去！』他就去；對那個說：『來！』他就來；對我的僕人說：『做這事！』他就去做。」","notes":[]},{"n":9,"t":"耶穌聽到這些話，就很驚訝，轉身對跟隨的眾人說：「我告訴你們，這麼大的信心，就是在以色列，我也沒有見過。」","notes":[]},{"n":10,"t":"那差來的人回到百夫長家裏，發現僕人已經好了。","notes":[]},{"n":11,"t":"過了不久，耶穌往一座城去，這城名叫拿因，他的門徒和一大群人與他同行。","notes":["有古卷是「次日」。"],"heads":["使寡婦的獨子起死回生"]},{"n":12,"t":"當他走近城門時，有一個死人被抬出來。這人是他母親獨生的兒子，而他母親又是寡婦。城裏的許多人與她一同送殯。","notes":[]},{"n":13,"t":"主看見那寡婦就憐憫她，對她說：「不要哭。」","notes":[]},{"n":14,"t":"於是耶穌進前來，按著槓，抬的人就站住了。耶穌說：「年輕人，我吩咐你，起來！」","notes":[]},{"n":15,"t":"那死人就坐了起來，開始說話，耶穌就把他交給他的母親。","notes":[]},{"n":16,"t":"眾人都驚奇，歸榮耀給神，說：「有大先知在我們當中興起了！」又說：「神眷顧了他的百姓！」","notes":[]},{"n":17,"t":"關於耶穌的這事就傳遍了猶太和周圍地區。","notes":[]},{"n":18,"t":"約翰的門徒把這些事都告訴約翰。於是約翰叫了兩個門徒來，","notes":[],"heads":["施洗約翰差人問主"]},{"n":19,"t":"差他們到主那裏去，說：「將要來的那位就是你嗎？還是我們要等候別人呢？」","notes":["「主」：有古卷是「耶穌」；另有古卷是「主耶穌」。"]},{"n":20,"t":"那兩個人來到耶穌那裏，說：「施洗的約翰差我們來問你：『將要來的那位就是你嗎？還是我們要等候別人呢？』」","notes":[]},{"n":21,"t":"就在那時，耶穌治好了許多患疾病的，得瘟疫的，被邪靈附身的，又開恩使好些盲人能看見。","notes":[]},{"n":22,"t":"耶穌回答他們：「你們去，把所看見、所聽見的告訴約翰：就是盲人看見，瘸子行走，痲瘋病人得潔淨，聾子聽見，死人復活，窮人聽到福音。","notes":[]},{"n":23,"t":"凡不因我跌倒的有福了！」","notes":[]},{"n":24,"t":"約翰所差來的人一走，耶穌就對眾人談到約翰，說：「你們從前到曠野去，是要看甚麼呢？被吹動的蘆葦嗎？","notes":[]},{"n":25,"t":"你們出去到底是要看甚麼？穿細軟衣服的人嗎？看哪，那穿華麗衣服、宴樂度日的人是在王宮裏。","notes":[]},{"n":26,"t":"你們出去究竟是要看甚麼？是先知嗎？是的，我告訴你們，他比先知大多了。","notes":[]},{"n":27,"t":"這個人就是經上所說的：『看哪，我要差遣我的使者在你面前，他要在你前面為你預備道路。』","notes":[]},{"n":28,"t":"我告訴你們，凡女子所生的，沒有比約翰大的；但在神國裏，最小的比他還大。」","notes":[]},{"n":29,"t":"眾百姓和稅吏已受過約翰的洗，聽見這話，就以神為義；","notes":[]},{"n":30,"t":"但法利賽人和律法師沒有受過約翰的洗，竟廢棄了神為他們所定的旨意。","notes":["29-30兩節或譯「眾百姓和稅吏聽見了約翰的話，就受了他的洗，就以神為義；但法利賽人和律法師不受約翰的洗，竟為自己廢棄了神為他們所定的旨意。」"]},{"n":31,"t":"主又說：「這樣，我該用甚麼來比這世代的人呢？他們好像甚麼呢？","notes":[]},{"n":32,"t":"這正像孩童坐在街市上，彼此喊叫：『我們為你們吹笛，你們不跳舞；我們唱哀歌，你們不啼哭。』","notes":[]},{"n":33,"t":"施洗的約翰來，不吃餅，不喝酒，你們說他是被鬼附的。","notes":[]},{"n":34,"t":"人子來，也吃也喝，你們又說這人貪食好酒，是稅吏和罪人的朋友。","notes":[]},{"n":35,"t":"而智慧是由所有智慧的人來證實的。」","notes":[]},{"n":36,"t":"有一個法利賽人請耶穌和他吃飯，耶穌就到那法利賽人家裏去坐席。","notes":[],"heads":["有罪的女人得蒙赦免"]},{"n":37,"t":"那城裏有一個女人，是個罪人，知道耶穌在法利賽人家裏坐席，就拿著盛滿香膏的玉瓶，","notes":[]},{"n":38,"t":"站在耶穌背後，挨著他的腳哭，眼淚滴濕了耶穌的腳，就用自己的頭髮擦乾，又用嘴連連親他的腳，把香膏抹上。","notes":[]},{"n":39,"t":"請耶穌的法利賽人看見這事，心裏說：「這人若是先知，一定知道摸他的是誰，是個怎樣的女人；她是個罪人哪！」","notes":[]},{"n":40,"t":"耶穌回應他說：「西門，我有話要對你說。」西門說：「老師，請說。」","notes":[]},{"n":41,"t":"耶穌說：「有兩個人欠了某一個債主的錢，一個欠五百個銀幣，一個欠五十個銀幣。","notes":[]},{"n":42,"t":"因為他們無力償還，債主就開恩赦免了他們兩個人的債。那麼，這兩個人哪一個更愛他呢？」","notes":[]},{"n":43,"t":"西門回答：「我想是那多得赦免的人。」耶穌對他說：「你的判斷不錯。」","notes":[]},{"n":44,"t":"於是他轉過來向著那女人，對西門說：「你看見這女人嗎？我進了你的家，你沒有給我水洗腳，但這女人用眼淚滴濕了我的腳，又用頭髮擦乾。","notes":[]},{"n":45,"t":"你沒有親我，但這女人從我進來就不住地親我的腳。","notes":[]},{"n":46,"t":"你沒有用油抹我的頭，但這女人用香膏抹我的腳。","notes":[]},{"n":47,"t":"所以我告訴你，她許多的罪都赦免了，因為她愛的多；而那少得赦免的，愛的就少。」","notes":[]},{"n":48,"t":"於是耶穌對那女人說：「你的罪都赦免了。」","notes":[]},{"n":49,"t":"同席的人心裏說：「這是甚麼人，竟赦免人的罪呢？」","notes":[]},{"n":50,"t":"耶穌對那女人說：「你的信救了你，平安地回去吧！」","notes":[]}]},"8":{"heading":"跟從耶穌的婦女們","verses":[{"n":1,"t":"過了不久，耶穌周遊各城各鄉傳道，宣講神國的福音。和他同去的有十二個使徒，","notes":[]},{"n":2,"t":"還有曾被邪靈所附，被疾病所纏，而已經治好的幾個婦女，其中有稱為抹大拉的馬利亞，曾有七個鬼從她身上趕出來，","notes":[]},{"n":3,"t":"又有希律的管家苦撒的妻子約亞拿，和蘇撒拿以及好些別的婦女，她們都是用自己的財物供給耶穌和使徒。","notes":[]},{"n":4,"t":"當一大群人聚集，又有人從各城裏出來見耶穌的時候，耶穌用比喻說：","notes":[],"heads":["撒種的比喻"]},{"n":5,"t":"「有一個撒種的出去撒種。他撒的時候，有的落在路旁，被人踐踏，天上的飛鳥又來把它吃掉了。","notes":[]},{"n":6,"t":"有的落在磐石上，一出來就枯乾了，因為得不著滋潤。","notes":[]},{"n":7,"t":"有的落在荊棘裏，荊棘跟它一同生長，把它擠住了。","notes":[]},{"n":8,"t":"又有的落在好土裏，生長起來，結實百倍。」耶穌說完這些話，大聲說：「有耳可聽的，就應當聽！」","notes":[]},{"n":9,"t":"門徒問耶穌這比喻是甚麼意思。","notes":[],"heads":["用比喻的目的"]},{"n":10,"t":"他說：「神國的奧祕只讓你們知道，至於別人，就用比喻，要他們看也看不見，聽也不明白。」","notes":[]},{"n":11,"t":"「這比喻是這樣的：種子就是神的道。","notes":[],"heads":["解釋撒種的比喻"]},{"n":12,"t":"那些在路旁的，就是人聽了道，隨後魔鬼來，從他們心裏把道奪去，以免他們信了得救。","notes":[]},{"n":13,"t":"那些在磐石上的，就是人聽道，歡喜領受，但沒有根，不過暫時相信，等到碰上試煉就退後了。","notes":[]},{"n":14,"t":"那落在荊棘裏的，就是人聽了道，走開以後，被今生的憂慮、錢財、宴樂擠住了，結不出成熟的子粒來。","notes":[]},{"n":15,"t":"那落在好土裏的，就是人聽了道，並用純真善良的心持守它，耐心等候結果實。」","notes":[]},{"n":16,"t":"「沒有人點燈用器皿蓋上，或放在床底下，而是放在燈臺上，讓進來的人看見亮光。","notes":[],"heads":["器皿下的燈"]},{"n":17,"t":"因為掩藏的事沒有不顯出來的，隱瞞的事也沒有不露出來被人知道的。","notes":[]},{"n":18,"t":"所以，你們應當小心怎樣聽。因為凡有的，還要給他；凡沒有的，連他自以為有的也要奪去。」","notes":[]},{"n":19,"t":"耶穌的母親和他兄弟來看他，因為人多，不能到他跟前。","notes":[],"heads":["遵父旨意的人都是親屬"]},{"n":20,"t":"有人告訴他說：「你母親和你兄弟站在外邊，要見你。」","notes":[]},{"n":21,"t":"耶穌回答他們：「聽了神的道而遵行的人，就是我的母親，我的兄弟了。」","notes":[]},{"n":22,"t":"有一天，耶穌和門徒上了船，他對門徒說：「我們渡到湖的對岸去吧。」他們就開了船。","notes":[],"heads":["平靜風和海"]},{"n":23,"t":"船行的時候，耶穌睡著了。湖上忽然起了狂風，船將灌滿了水，很危險。","notes":[]},{"n":24,"t":"門徒去叫醒他，說：「老師！老師！我們快沒命啦！」耶穌醒了，斥責那狂風大浪，風浪就止住，平靜了。","notes":[]},{"n":25,"t":"耶穌對他們說：「你們的信心在哪裏呢？」他們又懼怕又驚訝，彼此說：「這到底是誰？他吩咐風和水，連風和水都聽從他。」","notes":[]},{"n":26,"t":"他們到了格拉森人的地區，就在加利利的對面。","notes":["有古卷是「格各森」，另有古卷是「加大拉」；37節同。"],"heads":["治好格拉森被鬼附的人"]},{"n":27,"t":"耶穌上了岸，就有城裏一個被鬼附的人迎著他走來。這個人好久不穿衣服，不住在屋子裏，而住在墳墓裏。","notes":[]},{"n":28,"t":"他看見耶穌，就喊叫著俯伏在他面前，大聲說：「至高神的兒子耶穌，你為甚麼干擾我？我求你，不要叫我受苦！」","notes":[]},{"n":29,"t":"這是因耶穌曾吩咐污靈從這人身上出來。原來這污靈屢次抓住他；他常被人看守，又被鐵鏈和腳鐐捆鎖，他竟把鎖鏈掙斷，被鬼趕到曠野去。","notes":[]},{"n":30,"t":"耶穌問他：「你的名字叫甚麼？」他說：「群」；這是因為附著他的鬼多。","notes":[]},{"n":31,"t":"鬼就央求耶穌不要命令他們到無底坑裏去。","notes":[]},{"n":32,"t":"那裏有一大群豬正在山坡上吃食，鬼央求耶穌准他們進入豬裏；耶穌准了他們。","notes":[]},{"n":33,"t":"於是鬼從那人出來，進入豬裏，那群豬就闖下山崖，投進湖裏，淹死了。","notes":[]},{"n":34,"t":"放豬的看見這事就逃跑了，去告訴城裏和鄉下的人。","notes":[]},{"n":35,"t":"眾人出來，要看發生了甚麼事；到了耶穌那裏，發現那人坐在耶穌腳前，鬼已離開了他，穿著衣服，神智清醒，他們就害怕。","notes":[]},{"n":36,"t":"看見這事的人把被鬼附的人怎麼得醫治的事告訴他們。","notes":[]},{"n":37,"t":"格拉森周圍地區的人，因為害怕得很，都求耶穌離開他們；耶穌就上船回去了。","notes":[]},{"n":38,"t":"鬼已從身上出去的那人懇求要和耶穌在一起，耶穌卻打發他回去，說：","notes":[]},{"n":39,"t":"「你回家去，傳講神為你做了多麼大的事。」他就走遍全城，傳揚耶穌為他做了多麼大的事。","notes":[]},{"n":40,"t":"耶穌回來的時候，眾人迎接他，因為他們都等候著他。","notes":[],"heads":["葉魯的女兒和經血不止的女人"]},{"n":41,"t":"有一個會堂主管，名叫葉魯，來俯伏在耶穌腳前，求耶穌到他家裏去，","notes":[]},{"n":42,"t":"因為他有一個獨生女，約十二歲，快要死了。耶穌去的時候，眾人簇擁著他。","notes":[]},{"n":43,"t":"有一個女人，患了經血不止的病有十二年，在醫生手裏花盡了一生所有的，但沒有人能治好她。","notes":["有古卷沒有「在醫生手裏…一生所有的」。"]},{"n":44,"t":"她來到耶穌背後，摸他的衣裳繸子，經血立刻止住了。","notes":[]},{"n":45,"t":"耶穌說：「摸我的是誰？」眾人都不承認。彼得說：「老師，眾人擁擁擠擠緊靠著你。」","notes":[]},{"n":46,"t":"耶穌說：「有人摸了我，因為我覺得有能力從我身上出去。」","notes":[]},{"n":47,"t":"那女人知道瞞不住了，就戰戰兢兢地俯伏在耶穌跟前，把摸他的緣故和怎樣立刻痊癒的事，當著眾人都說出來。","notes":[]},{"n":48,"t":"耶穌對她說：「女兒，你的信救了你。平安地回去吧！」","notes":[]},{"n":49,"t":"耶穌還在說話的時候，有人從會堂主管的家裏來，說：「你的女兒死了，不要勞駕老師了。」","notes":[]},{"n":50,"t":"耶穌聽見就對他說：「不要怕，只要信！她必得痊癒。」","notes":[]},{"n":51,"t":"耶穌到了他的家，除了彼得、約翰、雅各，和女兒的父母，不許別人同他進去。","notes":[]},{"n":52,"t":"眾人都在為這女孩哀哭捶胸。耶穌說：「不要哭，她不是死了，是睡著了。」","notes":[]},{"n":53,"t":"他們知道她已經死了，就嘲笑耶穌。","notes":[]},{"n":54,"t":"耶穌拉著她的手，呼叫著：「孩子，起來吧！」","notes":[]},{"n":55,"t":"她的靈魂就回來了，她立刻起來。耶穌吩咐給她東西吃。","notes":[]},{"n":56,"t":"她的父母非常驚奇；耶穌吩咐他們不要把所發生的事告訴任何人。","notes":[]}]},"9":{"heading":"耶穌差遣十二使徒","verses":[{"n":1,"t":"耶穌叫齊了十二使徒，給他們能力和權柄制伏一切的鬼，醫治疾病，","notes":[]},{"n":2,"t":"又差遣他們宣講神的國，醫治病人，","notes":[]},{"n":3,"t":"對他們說：「途中甚麼都不要帶；不要帶手杖和行囊，不要帶食物和銀錢，也不要帶兩件內衣。","notes":["有古卷是「每人也不要帶兩件內衣」。"]},{"n":4,"t":"你們無論進哪一家，就住在哪裏，也從那裏離開。","notes":[]},{"n":5,"t":"凡不接待你們的，你們離開那城的時候，要跺掉你們腳上的塵土，證明他們的不是。」","notes":[]},{"n":6,"t":"於是使徒出去，走遍各鄉傳福音，到處治病。","notes":[]},{"n":7,"t":"希律分封王聽見耶穌所做的一切事，就困惑起來，因為有人說：「約翰從死人中復活了。」","notes":[],"heads":["希律的困惑"]},{"n":8,"t":"又有人說：「以利亞顯現了。」還有人說：「古時的一個先知又活了。」","notes":[]},{"n":9,"t":"希律說：「約翰我已經斬了，但這是甚麼人？關於他，我竟聽到這樣的事！」於是希律想要見他。","notes":[]},{"n":10,"t":"使徒們回來，把所做的事告訴耶穌，耶穌就私下帶他們離開那裏，往一座叫伯賽大的城去。","notes":[],"heads":["耶穌使五千人吃飽"]},{"n":11,"t":"眾人知道了，就跟著他去；耶穌接待他們，對他們講論神國的事，治好那些需要醫治的人。","notes":[]},{"n":12,"t":"太陽快要下山，十二使徒進前來對他說：「請叫眾人散去，他們好往四面村莊鄉鎮裏去借宿和找吃的，因為我們這裏地方偏僻。」","notes":[]},{"n":13,"t":"耶穌對他們說：「你們給他們吃吧！」他們說：「我們不過有五個餅、兩條魚，若不去為這許多人買食物就不夠。」","notes":[]},{"n":14,"t":"那時，男人約有五千。耶穌對門徒說：「叫他們分組坐下，每組大約五十個人。」","notes":[]},{"n":15,"t":"門徒就這樣做了，叫眾人都坐下。","notes":[]},{"n":16,"t":"耶穌拿著這五個餅和兩條魚，望著天祝福，擘開，遞給門徒，擺在眾人面前。","notes":[]},{"n":17,"t":"所有的人都吃，並且吃飽了。他們把剩下的碎屑收拾起來，裝滿了十二個籃子。","notes":[]},{"n":18,"t":"耶穌獨自禱告的時候，門徒也同他在那裏。耶穌問他們：「眾人說我是誰？」","notes":[],"heads":["彼得認耶穌為基督"]},{"n":19,"t":"他們回答：「是施洗的約翰；有人說是以利亞；還有人說是古時的一個先知又活了。」","notes":[]},{"n":20,"t":"耶穌問他們：「你們說我是誰？」彼得回答：「是神所立的基督。」","notes":[]},{"n":21,"t":"耶穌切切吩咐他們，命令他們不可把這事告訴任何人；","notes":[],"heads":["耶穌預言受難和復活"]},{"n":22,"t":"又說：「人子必須受許多的苦，被長老、祭司長和文士棄絕，並且被殺，第三天復活。」","notes":[]},{"n":23,"t":"耶穌又對眾人說：「若有人要跟從我，就當捨己，天天背起自己的十字架來跟從我。","notes":[]},{"n":24,"t":"因為凡要救自己生命的，必喪失生命；凡為我喪失生命的，他必救自己的生命。","notes":[]},{"n":25,"t":"人就是賺得全世界，卻喪失了自己，或賠上自己，有甚麼益處呢？","notes":[]},{"n":26,"t":"凡把我和我的道當作可恥的，人子在自己的榮耀裏，和天父與聖天使的榮耀裏來臨的時候，也要把那人當作可恥的。","notes":[]},{"n":27,"t":"我實在告訴你們，站在這裏的，有人在沒經歷死亡以前，必定看見神的國。」","notes":[]},{"n":28,"t":"說了這些話以後約有八天，耶穌帶著彼得、約翰、雅各上山去禱告。","notes":[],"heads":["耶穌登山顯榮"]},{"n":29,"t":"正禱告的時候，他的面貌改變了，衣服潔白放光。","notes":[]},{"n":30,"t":"忽然有摩西和以利亞兩個人同耶穌說話；","notes":[]},{"n":31,"t":"他們在榮光裏顯現，談論耶穌去世的事，就是他在耶路撒冷將要完成的事。","notes":[]},{"n":32,"t":"彼得和他的同伴都打盹，但一清醒，就看見耶穌的榮光和與他一起站著的那兩個人。","notes":[]},{"n":33,"t":"二人正要和耶穌分離的時候，彼得對耶穌說：「老師，我們在這裏真好！我們來搭三座棚，一座為你，一座為摩西，一座為以利亞。」他卻不知道自己在說些甚麼。","notes":[]},{"n":34,"t":"說這些話的時候，有一朵雲彩來遮蓋他們；他們一進入雲彩就很懼怕。","notes":[]},{"n":35,"t":"有聲音從雲彩裏出來，說：「這是我的兒子，我所揀選的。你們要聽從他！」","notes":["有古卷是「我所愛的」。"]},{"n":36,"t":"聲音停止後，只見耶穌獨自一人。當那些日子，門徒保持沉默，不把所看見的事告訴任何人。","notes":[]},{"n":37,"t":"第二天，他們下了山，有一大群人來迎見耶穌。","notes":[],"heads":["治好被靈附身的孩子"]},{"n":38,"t":"其中有一人喊著說：「老師！求你看看我的兒子，因為他是我的獨子。","notes":[]},{"n":39,"t":"他被靈拿住就突然喊叫，那靈又使他抽風，口吐白沫，並且重重地傷害他，不輕易放過他。","notes":[]},{"n":40,"t":"我求過你的門徒把那靈趕出去，他們卻不能。」","notes":[]},{"n":41,"t":"耶穌回答：「唉！這又不信又悖謬的世代啊，我和你們在一起，忍耐你們，要到幾時呢？把你的兒子帶到這裏來！」","notes":[]},{"n":42,"t":"他正來的時候，那鬼把他摔倒，使他重重地抽風。耶穌斥責那污靈，把孩子治好了，交給他父親。","notes":[]},{"n":43,"t":"眾人都詫異神的大能。眾人正驚訝於耶穌所做的一切事的時候，耶穌對門徒說：","notes":["「大能」或譯「威榮」。"]},{"n":44,"t":"「你們要把這些話聽進去，因為人子將要被交在人手裏。」","notes":[]},{"n":45,"t":"門徒卻不明白這話，其中的意思對他們隱藏著，使他們不能明白，他們也不敢問這話的意思。","notes":[]},{"n":46,"t":"門徒互相議論，他們中間誰最大。","notes":[],"heads":["誰最大"]},{"n":47,"t":"耶穌看出他們心中的議論，就領一個小孩子來，叫他站在自己旁邊，","notes":[]},{"n":48,"t":"對他們說：「凡為我的名接納這小孩子的，就是接納我；凡接納我的，就是接納那差我來的。你們中間最小的，他就是最大的。」","notes":[]},{"n":49,"t":"約翰回應說：「老師，我們看見一個人奉你的名趕鬼，我們就阻止他，因為他不與我們一同跟從你。」","notes":[],"heads":["不抵擋你們就是幫助你們"]},{"n":50,"t":"耶穌對他說：「不要阻止他，因為不抵擋你們的，就是幫助你們的。」","notes":[]},{"n":51,"t":"耶穌被接上升的日子將到，他決定面向耶路撒冷走去。","notes":[],"heads":["撒瑪利亞人不接待主"]},{"n":52,"t":"他打發使者在他前頭走；他們進了撒瑪利亞的一個村莊，要為他作準備。","notes":[]},{"n":53,"t":"那裏的人不接待他，因為他面向著耶路撒冷去。","notes":[]},{"n":54,"t":"他的門徒雅各和約翰看見了，就說：「主啊！你要我們吩咐火從天上降下來，燒滅他們嗎？」","notes":["有古卷加「像以利亞所做的」。"]},{"n":55,"t":"耶穌轉身責備兩個門徒。","notes":["有古卷加「他說：『你們的心如何，你們並不知道。56 人子來不是要滅人的性命，而是要救人的性命。』」"]},{"n":56,"t":"於是他們就往別的村莊去了。","notes":[]},{"n":57,"t":"他們在路上走的時候，有一個人對耶穌說：「你無論往哪裏去，我都要跟從你。」","notes":[],"heads":["跟從耶穌應有的準備"]},{"n":58,"t":"耶穌對他說：「狐狸有洞，天空的飛鳥有窩，人子卻沒有枕頭的地方。」","notes":[]},{"n":59,"t":"他又對另一個人說：「來跟從我！」那人說：「主啊，容許我先回去埋葬我的父親。」","notes":["有古卷沒有「主啊」。"]},{"n":60,"t":"耶穌對他說：「讓死人埋葬他們的死人，你只管去傳講神的國。」","notes":[]},{"n":61,"t":"又有一人說：「主啊，我要跟從你，但容許我先去辭別我家裏的人。」","notes":[]},{"n":62,"t":"耶穌對他說：「手扶著犁向後看的人，不配進神的國。」","notes":[]}]},"10":{"heading":"主差遣七十二人","verses":[{"n":1,"t":"這些事以後，主另外指定七十二個人，差遣他們兩個兩個地在他前面，往自己所要到的各城各地去。","notes":["有古卷是「七十個人」；17節同。"]},{"n":2,"t":"他對他們說：「要收的莊稼多，做工的人少。所以，你們要求莊稼的主差遣做工的人出去收他的莊稼。","notes":[]},{"n":3,"t":"你們去吧！看！我差你們出去，如同羔羊進入狼群。","notes":[]},{"n":4,"t":"不要帶錢囊，不要帶行囊，不要帶鞋子；在路上也不要向人問安。","notes":[]},{"n":5,"t":"無論進哪一家，先要說：『願這一家平安。』","notes":[]},{"n":6,"t":"那裏若有當得平安的人，你們所求的平安就必臨到那家，不然，將歸還你們。","notes":[]},{"n":7,"t":"你們要住在那家，吃喝他們所供給的，因為工人得工錢是應當的；不要從這家搬到那家。","notes":[]},{"n":8,"t":"無論進哪一城，人若接待你們，給你們擺上甚麼食物，你們就吃甚麼。","notes":[]},{"n":9,"t":"要醫治那城裏的病人，對他們說：『神的國臨近你們了。』","notes":[]},{"n":10,"t":"無論進哪一城，人若不接待你們，你們就到大街上去，說：","notes":[]},{"n":11,"t":"『就是你們城裏的塵土黏在我們的腳上，我們也當著你們擦去。但是，你們該知道神的國臨近了。』","notes":[]},{"n":12,"t":"我告訴你們，在那日子，所多瑪所受的，比那城還容易受呢！」","notes":[]},{"n":13,"t":"「哥拉汛哪，你有禍了！伯賽大啊，你有禍了！因為在你們中間所行的異能，若行在推羅、西頓，他們早已披麻蒙灰，坐在地上悔改了。","notes":[],"heads":["耶穌責備不悔改的城"]},{"n":14,"t":"在審判的時候，推羅和西頓所受的，比你們還容易受呢！","notes":[]},{"n":15,"t":"迦百農啊，你以為要被舉到天上嗎？你要被推下陰間！」","notes":[]},{"n":16,"t":"耶穌又對門徒說：「聽從你們的就是聽從我；棄絕你們的就是棄絕我；棄絕我的就是棄絕差遣我來的那位。」","notes":[]},{"n":17,"t":"那七十二個人歡歡喜喜地回來，說：「主啊，因你的名，就是鬼也服了我們。」","notes":[],"heads":["七十二人回來"]},{"n":18,"t":"耶穌對他們說：「我看見撒但從天上墜落，像閃電一樣。","notes":[]},{"n":19,"t":"我已經給你們權柄可以踐踏蛇和蠍子，又勝過仇敵一切的能力，絕沒有甚麼能害你們。","notes":[]},{"n":20,"t":"然而，不要因靈服了你們就歡喜，而要因你們的名記錄在天上歡喜。」","notes":[]},{"n":21,"t":"正當那時，耶穌被聖靈感動而歡喜快樂，說：「父啊，天地的主，我感謝你！因為你把這些事向聰明智慧的人隱藏起來，而向嬰孩啟示出來。父啊，是的，因為你的美意本是如此。","notes":[],"heads":["耶穌的歡樂"]},{"n":22,"t":"一切都是我父交給我的。除了父，沒有人知道子是誰；除了子和子所願意啟示的人，沒有人知道父是誰。」","notes":[]},{"n":23,"t":"耶穌轉身私下對門徒說：「看見你們所看見的，那眼睛有福了。","notes":[]},{"n":24,"t":"我告訴你們，從前有許多先知和君王要看你們所看的，卻沒有看見，要聽你們所聽的，卻沒有聽見。」","notes":[]},{"n":25,"t":"有一個律法師起來試探耶穌，說：「老師！我該做甚麼才可以承受永生？」","notes":[],"heads":["好撒瑪利亞人"]},{"n":26,"t":"耶穌對他說：「律法上寫的是甚麼？你是怎樣念的呢？」","notes":[]},{"n":27,"t":"他回答說：「你要盡心、盡性、盡力、盡意愛主—你的神，又要愛鄰如己。」","notes":["「鄰」也可譯作「人」。"]},{"n":28,"t":"耶穌對他說：「你回答得正確，你這樣做就會得永生。」","notes":[]},{"n":29,"t":"那人要證明自己有理，就對耶穌說：「誰是我的鄰舍呢？」","notes":[]},{"n":30,"t":"耶穌回答：「有一個人從耶路撒冷下耶利哥去，落在強盜手中。他們剝去他的衣裳，把他打個半死，丟下他走了。","notes":[]},{"n":31,"t":"偶然有一個祭司從那條路下來，看見他就從另一邊過去了。","notes":[]},{"n":32,"t":"又有一個利未人來到那裏，看見他，也照樣從另一邊過去了。","notes":[]},{"n":33,"t":"可是，有一個撒瑪利亞人路過那裏，看見他就動了慈心，","notes":[]},{"n":34,"t":"上前用油和酒倒在他的傷處，包裹好了，扶他騎上自己的牲口，帶他到旅店裏去，照應他。","notes":[]},{"n":35,"t":"第二天，他拿出兩個銀幣來，交給店主，說：『請你照應他，額外的費用，我回來時會還你。』","notes":[]},{"n":36,"t":"你想，這三個人哪一個是落在強盜手中那人的鄰舍呢？」","notes":[]},{"n":37,"t":"他說：「是憐憫他的。」耶穌對他說：「你去，照樣做吧！」","notes":[]},{"n":38,"t":"他們繼續前行，耶穌進了一個村莊。有一個女人，名叫馬大，接他到自己家裏。","notes":[],"heads":["耶穌探望馬大和馬利亞"]},{"n":39,"t":"她有一個妹妹，名叫馬利亞，在主的腳前坐著聽他的道。","notes":[]},{"n":40,"t":"馬大伺候的事多，心裏忙亂，進前來，說：「主啊，我的妹妹留下我一個人伺候，你不在意嗎？請吩咐她來幫助我。」","notes":[]},{"n":41,"t":"主回答說：「馬大，馬大，你為許多的事操心煩惱，","notes":[]},{"n":42,"t":"但是不可少的只有一件。馬利亞已經選擇了那上好的福分，是沒有人能從她奪去的。」","notes":["「只有一件」：有古卷是「只有幾件，或是一件」。"]}]},"11":{"heading":"論禱告","verses":[{"n":1,"t":"耶穌在一個地方禱告。禱告完了，有個門徒對他說：「主啊，求你教導我們禱告，像約翰教導他的門徒一樣。」","notes":[]},{"n":2,"t":"耶穌對他們說：「你們禱告的時候，要說：『父啊，願人都尊你的名為聖；願你的國降臨；","notes":["有古卷是「我們在天上的父」。","有古卷加「願你的旨意行在地上，如同行在天上。」"]},{"n":3,"t":"我們日用的飲食，天天賜給我們。","notes":[]},{"n":4,"t":"赦免我們的罪，因為我們也赦免凡虧欠我們的人。不叫我們陷入試探。』」","notes":["有古卷加「救我們脫離那惡者。」"]},{"n":5,"t":"耶穌又對他們說：「你們中間誰有一個朋友半夜到他那裏去，對他說：『朋友！請借給我三個餅；","notes":[]},{"n":6,"t":"因為我有一個朋友旅途中來到我這裏，我沒有東西招待他。』","notes":[]},{"n":7,"t":"那人在裏面回答：『不要打擾我，門已經關了，孩子們也同我在床上了，我不能起來給你。』","notes":[]},{"n":8,"t":"我告訴你們，雖不因他是朋友起來給他，也會因他不顧面子地直求，起來照他所需要的給他。","notes":[]},{"n":9,"t":"我又告訴你們，祈求，就給你們；尋找，就找到；叩門，就給你們開門。","notes":[]},{"n":10,"t":"因為凡祈求的，就得著；尋找的，就找到；叩門的，就給他開門。","notes":[]},{"n":11,"t":"你們中間作父親的，誰有兒子求魚，反拿蛇當魚給他呢？","notes":["有古卷加「求餅，反給他石頭呢？」"]},{"n":12,"t":"求雞蛋，反給他蠍子呢？","notes":[]},{"n":13,"t":"你們雖然不好，尚且知道拿好東西給兒女，何況天父，他豈不更要把聖靈賜給求他的人嗎？」","notes":["有古卷加「你們的」。"]},{"n":14,"t":"耶穌趕出一個使人成為啞巴的鬼，鬼出去了，啞巴就說出話來；眾人都很驚訝。","notes":["有古卷是「一個啞巴鬼」。"],"heads":["誣蔑耶穌為別西卜"]},{"n":15,"t":"其中卻有人說：「他是靠著鬼王別西卜趕鬼。」","notes":[]},{"n":16,"t":"又有人試探耶穌，要他顯個來自天上的神蹟。","notes":[]},{"n":17,"t":"他知道他們的意念，就對他們說：「一國自相紛爭，必定荒蕪；一家自相紛爭，就必敗落。","notes":[]},{"n":18,"t":"撒但若自相紛爭，他的國怎能立得住呢？因為你們說我是靠著別西卜趕鬼。","notes":[]},{"n":19,"t":"我若靠著別西卜趕鬼，你們的子弟趕鬼又靠著誰呢？這樣，他們要作你們的判官。","notes":[]},{"n":20,"t":"我若靠著神的能力趕鬼，那麼，神的國就已臨到你們了。","notes":[]},{"n":21,"t":"壯士全副武裝，看守自己的住宅，他所有的都很安全；","notes":[]},{"n":22,"t":"但有一個比他更強的來攻擊他，並且戰勝了他，就奪去他所倚靠的盔甲兵器，又分了他的掠物。","notes":[]},{"n":23,"t":"不跟我一起的，就是反對我；不與我一起收聚的，就是在拆散。」","notes":[]},{"n":24,"t":"「污靈離了人身，走遍無水之地尋找安歇之處，卻找不到。就說：『我要回到我原來的屋裏去。』","notes":[],"heads":["污靈回來"]},{"n":25,"t":"他到了，看見裏面打掃乾淨，修飾好了，","notes":[]},{"n":26,"t":"就去另帶了七個比自己更惡的靈來，都進去住在那裏。那人後來的景況比先前更壞了。」","notes":[]},{"n":27,"t":"耶穌正說這些話的時候，眾人中間有一個女人高聲對他說：「懷你胎乳養你的有福了！」","notes":[],"heads":["真正的福"]},{"n":28,"t":"耶穌卻說：「更有福的是聽神的道而遵守的人！」","notes":[]},{"n":29,"t":"當眾人越來越擁擠的時候，耶穌說：「這世代是一個邪惡的世代。他們求看神蹟，除了約拿的神蹟以外，再沒有神蹟給他們看了。","notes":[],"heads":["求神蹟"]},{"n":30,"t":"約拿怎樣為尼尼微人成了神蹟，人子也要照樣為這世代的人成為神蹟。","notes":[]},{"n":31,"t":"在審判的時候，南方的女王要起來定這世代的人的罪，因為她從地極而來，要聽所羅門智慧的話。看哪，比所羅門更大的在這裏！","notes":[]},{"n":32,"t":"在審判的時候，尼尼微人要起來定這世代的罪，因為尼尼微人聽了約拿所傳的就悔改了。看哪，比約拿更大的在這裏！」","notes":[]},{"n":33,"t":"「沒有人點燈放在地窖裏，或是斗底下，總是放在燈臺上，讓進來的人看見亮光。","notes":["有古卷沒有「或是斗底下」。"],"heads":["眼睛是身體的燈"]},{"n":34,"t":"你的眼睛就是身體的燈。當你的眼睛明亮，全身就光明，當眼睛昏花，全身就黑暗。","notes":[]},{"n":35,"t":"所以，你要注意，免得你裏面的光暗了。","notes":[]},{"n":36,"t":"若是你全身光明，毫無黑暗，就必全然光明，如同燈的明光照亮你。」","notes":[]},{"n":37,"t":"耶穌正說話的時候，有一個法利賽人請他吃飯，耶穌就進去坐席。","notes":[],"heads":["譴責法利賽人和文士"]},{"n":38,"t":"這法利賽人看見耶穌飯前不先洗手就很詫異。","notes":[]},{"n":39,"t":"主對他說：「如今你們法利賽人洗淨杯盤的外面，你們裏面卻滿了貪婪和邪惡。","notes":[]},{"n":40,"t":"無知的人哪！造外面的，不也造了裏面嗎？","notes":[]},{"n":41,"t":"只要把杯盤裏面的施捨給人，對你們來說一切就都潔淨了。","notes":[]},{"n":42,"t":"「但是你們法利賽人有禍了！因為你們將薄荷、芸香，和各樣蔬菜獻上十分之一，疏忽了公義和愛神的事；這原是你們該做的—至於其他也不可忽略。","notes":[]},{"n":43,"t":"你們法利賽人有禍了！因為你們喜愛會堂裏的高位，又喜歡人們在街市上向你們問安。","notes":[]},{"n":44,"t":"你們有禍了！因為你們如同不顯露的墳墓，走在上面的人並不知道。」","notes":[]},{"n":45,"t":"律法師中有一個回答耶穌，說：「老師，你這樣說也把我們侮辱了。」","notes":[]},{"n":46,"t":"耶穌說：「你們律法師也有禍了！因為你們把難挑的擔子放在別人身上，自己卻不肯動一個指頭去減輕這些擔子。","notes":[]},{"n":47,"t":"你們有禍了！因為你們建造先知的墳墓，那些先知正是你們的祖宗所殺的。","notes":[]},{"n":48,"t":"可見你們祖宗所做的事，你們是證人，你們也贊同，因為他們殺了先知，你們建造先知的墳墓。","notes":[]},{"n":49,"t":"所以，神的智慧也曾說：『我要差遣先知和使徒到他們那裏去，有的他們要殘殺，有的他們要迫害』，","notes":[]},{"n":50,"t":"為使創世以來所流眾先知的血的罪都歸在這世代的人身上，","notes":[]},{"n":51,"t":"就是從亞伯的血起，直到被殺在祭壇和聖所中間的撒迦利亞的血為止。是的，我告訴你們，這都要向這世代的人追討。","notes":[]},{"n":52,"t":"你們律法師有禍了！因為你們把知識的鑰匙奪了去，自己不進去，要進去的人，你們也阻擋他們。」","notes":[]},{"n":53,"t":"耶穌從那裏出來，文士和法利賽人就開始極力地催逼他，盤問他許多事，","notes":[]},{"n":54,"t":"伺機要抓他的話柄。","notes":[]}]},"12":{"heading":"警戒假冒為善","verses":[{"n":1,"t":"這時，有幾萬人聚集，甚至彼此踐踏。耶穌就先對門徒說：「你們要防備法利賽人的酵，就是假冒為善。","notes":[]},{"n":2,"t":"掩蓋的事沒有不顯露出來的，隱藏的事也沒有不被人知道的。","notes":[]},{"n":3,"t":"因此，你們在暗中所說的，將要在明處被人聽見；在密室附耳所說的，將要在屋頂上被人宣揚。」","notes":[]},{"n":4,"t":"「我的朋友，我對你們說，那最多只能殺人身體而不能再做甚麼的，不要怕他們。","notes":[],"heads":["不要懼怕"]},{"n":5,"t":"我提醒你們該怕的是誰：該怕那殺了以後又有權柄把人扔在地獄裏的。是的，我告訴你們，正要怕他。","notes":[]},{"n":6,"t":"五隻麻雀不是賣二銅錢嗎？但在神面前，一隻也不被忘記；","notes":["「銅錢」：參「度量衡表」。"]},{"n":7,"t":"就是你們的頭髮也都數過了。不要懼怕，你們比許多的麻雀還貴重！」","notes":[]},{"n":8,"t":"「我又告訴你們，凡在人面前認我的，人子在神的使者面前也必認他；","notes":[],"heads":["在人的面前認基督"]},{"n":9,"t":"在人面前不認我的，人子在神的使者面前也必不認他。","notes":[]},{"n":10,"t":"凡說話干犯人子的，還可得赦免；但是褻瀆聖靈的，總不得赦免。","notes":[]},{"n":11,"t":"有人帶你們到會堂、官長和掌權的人面前，不要擔心怎麼答辯，說甚麼話；","notes":[]},{"n":12,"t":"因為就在那時候，聖靈要指教你們該說的話。」","notes":[]},{"n":13,"t":"人群中有一個人對耶穌說：「老師！請你吩咐我的兄弟和我分家產。」","notes":[],"heads":["無知的財主"]},{"n":14,"t":"耶穌對他說：「你這個人！誰立我作你們的判官，或給你們分家產的呢？」","notes":[]},{"n":15,"t":"於是他對他們說：「你們要謹慎自守，躲避一切的貪心，因為人的生命不在於家道豐富。」","notes":[]},{"n":16,"t":"然後他用比喻對他們說：「有一個財主，田地出產豐富。","notes":[]},{"n":17,"t":"他自己心裏想：『我的出產沒有地方儲藏，怎麼辦呢？』","notes":[]},{"n":18,"t":"就說：『我要這麼辦：要把我的倉庫拆了，另蓋更大的，在那裏好儲藏我一切的糧食和財物，","notes":[]},{"n":19,"t":"然後要對我自己說：你這個人哪，你有許多財物積存，可供多年享用，只管安安逸逸吃喝快樂吧！』","notes":[]},{"n":20,"t":"神卻對他說：『無知的人哪！今夜就要你的性命，你所預備的要歸誰呢？』","notes":[]},{"n":21,"t":"凡為自己積財，在神面前卻不富足的，也是這樣。」","notes":[]},{"n":22,"t":"耶穌又對門徒說：「所以，我告訴你們，不要為生命憂慮吃甚麼，為身體憂慮穿甚麼。","notes":[],"heads":["不要憂慮"]},{"n":23,"t":"因為生命勝於飲食，身體勝於衣裳。","notes":[]},{"n":24,"t":"你們想一想烏鴉：牠們既不種也不收，既沒有倉又沒有庫，神尚且養活牠們。你們比飛鳥要貴重得多呢！","notes":[]},{"n":25,"t":"你們哪一個能藉著憂慮使壽數多加一刻呢？","notes":["「使壽數多加一刻呢？」或譯「使身量多加一肘呢？」"]},{"n":26,"t":"這最小的事你們尚且不能做，何必憂慮其餘的事呢？","notes":[]},{"n":27,"t":"你們想一想百合花是怎麼長起來的：它也不勞動，也不紡線。然而我告訴你們，就是所羅門極榮華的時候，他所穿戴的還不如這些花的一朵呢！","notes":[]},{"n":28,"t":"你們這小信的人哪！野地裏的草今天還在，明天就丟在爐裏，神還給它這樣的妝飾，何況你們呢？","notes":[]},{"n":29,"t":"你們不要求吃甚麼，喝甚麼，也不要掛慮。","notes":[]},{"n":30,"t":"這都是世上的外邦人所求的；你們需要這些東西，你們的父都知道。","notes":[]},{"n":31,"t":"你們只要求他的國，這些東西就必加給你們了。","notes":[]},{"n":32,"t":"你們這小群，不要懼怕，因為你們的父樂意把國賜給你們。","notes":[]},{"n":33,"t":"你們要變賣財產賙濟人，為自己預備永不壞的錢囊和用不盡的財寶在天上，就是賊不能近，蟲不能蛀的地方。","notes":[]},{"n":34,"t":"因為你們的財寶在哪裏，你們的心也在哪裏。」","notes":[]},{"n":35,"t":"「你們要束緊腰帶，燈也要點著，","notes":[],"heads":["警醒的僕人"]},{"n":36,"t":"好像僕人等候自己的主人從婚宴上回來。他來叩門，就立刻給他開門。","notes":[]},{"n":37,"t":"主人來了，看見僕人警醒，那些僕人就有福了。我實在告訴你們，主人會叫他們坐席，自己束上腰帶，前來伺候他們。","notes":[]},{"n":38,"t":"他或是半夜來，或是天亮之前來，看見僕人這樣，那些僕人就有福了。","notes":[]},{"n":39,"t":"你們要知道，一家的主人若知道賊甚麼時候來，就不容賊挖穿房屋。","notes":["有古卷加「必警醒」。"]},{"n":40,"t":"你們也要預備，因為在你們想不到的時候，人子就來了。」","notes":[]},{"n":41,"t":"彼得說：「主啊，這比喻是對我們說的呢？還是也對眾人呢？」","notes":[]},{"n":42,"t":"主說：「那麼，誰是那忠心又精明的管家，主人要派他管理自己的家僕，按時定量分糧給他們的呢？","notes":[]},{"n":43,"t":"主人來到，看見僕人這樣做，那僕人就有福了。","notes":[]},{"n":44,"t":"我實在告訴你們，主人要派他管理所有的財產。","notes":[]},{"n":45,"t":"如果那僕人心裏說『我的主人會來得遲』，就動手打僮僕和使女，並且吃喝醉酒，","notes":[]},{"n":46,"t":"在想不到的日子，不知道的時候，那僕人的主人要來，重重地懲罰他，定他和不忠心的人同罪。","notes":["「重重地懲罰他」或譯「把他腰斬了」。"]},{"n":47,"t":"僕人知道主人的意思，卻沒預備，又未順他的意思做，那僕人要多受責打；","notes":[]},{"n":48,"t":"至於那不知道而做了當受責打的事的，要少受責打。多給誰，就向誰多取；多託誰，就向誰多要。」","notes":[]},{"n":49,"t":"「我來是要把火丟在地上，假如已經燒起來，不也是我所希望的嗎？","notes":[],"heads":["分裂的原因"]},{"n":50,"t":"我有當受的洗還沒有受，在這事完成之前，我是多麼地焦急！","notes":[]},{"n":51,"t":"你們以為我來是要使地上太平嗎？不！我告訴你們，是使人紛爭。","notes":[]},{"n":52,"t":"從今以後，一家五個人將要紛爭，三個和兩個相爭，兩個和三個相爭：","notes":[]},{"n":53,"t":"父親和兒子相爭，兒子和父親相爭；母親和女兒相爭，女兒和母親相爭；婆婆和媳婦相爭，媳婦和婆婆相爭。」","notes":[]},{"n":54,"t":"耶穌又對眾人說：「你們看見西邊起了雲彩，就說：『要下大雨了』，果然就有；","notes":[],"heads":["分辨時候"]},{"n":55,"t":"起了南風，你們就說：『要燥熱了』，也就有了。","notes":[]},{"n":56,"t":"假冒為善的人哪，你們知道分辨天地的氣象，怎麼不知道分辨這是甚麼時代呢？」","notes":[]},{"n":57,"t":"「你們又為何不自己判斷甚麼是合理的呢？","notes":[],"heads":["與冤家和解"]},{"n":58,"t":"你同告你的冤家去見官，還在路上，要盡力跟他和解，免得他拉你到法官面前，法官把你交給法警，法警把你下在監裏。","notes":[]},{"n":59,"t":"我告訴你，就是最後一小文錢還沒有還清，你也絕不能從那裏出來。」","notes":["「小文錢」：參「度量衡表」。"]}]},"13":{"heading":"不悔改必滅亡","verses":[{"n":1,"t":"正當那時，有些在場的人把彼拉多使加利利人的血攙雜在他們祭物中的事，告訴耶穌。","notes":[]},{"n":2,"t":"耶穌對他們說：「你們以為這些加利利人比其他的加利利人更有罪，所以受這害嗎？","notes":[]},{"n":3,"t":"我告訴你們，不是的！你們若不悔改，都同樣要滅亡！","notes":[]},{"n":4,"t":"從前西羅亞樓倒塌，壓死了十八個人，你們以為那些人比一切住在耶路撒冷的人更有罪嗎？","notes":[]},{"n":5,"t":"我告訴你們，不是的！你們若不悔改，都照樣要滅亡！」","notes":[]},{"n":6,"t":"於是，耶穌用比喻說：「有一個人在葡萄園裏栽了一棵無花果樹。他前來在樹上找果子，卻找不到，","notes":[],"heads":["不結果子的無花果樹"]},{"n":7,"t":"就對園丁說：『看哪，我這三年來到這棵無花果樹前找果子，竟找不到。把它砍了吧，何必白佔土地呢？』","notes":[]},{"n":8,"t":"園丁回答：『主啊，今年且留著，等我在樹周圍掘開土，加上肥料，","notes":[]},{"n":9,"t":"以後若結果子便罷，不然再把它砍了。』」","notes":[]},{"n":10,"t":"安息日，耶穌在一個會堂裏教導人。","notes":[],"heads":["在安息日治好駝背的女人"]},{"n":11,"t":"有一個女人被靈附身，病了十八年，腰彎得一點都直不起來。","notes":[]},{"n":12,"t":"耶穌看見，就叫她過來，對她說：「婦人，你的病好了！」","notes":[]},{"n":13,"t":"於是用雙手按著她，她立刻直起腰來，就歸榮耀給神。","notes":[]},{"n":14,"t":"會堂的主管因為耶穌在安息日治病，就很生氣，對眾人說：「有六天應當做工，那六天之內可以來求醫，在安息日卻不可。」","notes":[]},{"n":15,"t":"主回答他：「假冒為善的人哪，難道你們各人在安息日不解開槽上的牛和驢，牽去喝水嗎？","notes":[]},{"n":16,"t":"何況她本是亞伯拉罕的後裔，被撒但捆綁了十八年，不該在安息日這天解開她的綁嗎？」","notes":[]},{"n":17,"t":"耶穌說這些話，他的敵人都慚愧了；所有的人因他所做一切榮耀的事都很歡喜。","notes":[]},{"n":18,"t":"耶穌說：「神的國像甚麼？我拿甚麼來比擬呢？","notes":[],"heads":["芥菜種和麵酵的比喻"]},{"n":19,"t":"它好比一粒芥菜種，有人拿去種在園子裏，長大成樹，天上的飛鳥在它的枝上築巢。」","notes":[]},{"n":20,"t":"他又說：「我拿甚麼來比擬神的國呢？","notes":[]},{"n":21,"t":"它好比麵酵，有婦人拿來放進三斗麵裏，直到全團都發起來。」","notes":[]},{"n":22,"t":"耶穌往耶路撒冷去，在所經過的各城各鄉教導人。","notes":[],"heads":["要進窄門"]},{"n":23,"t":"有一個人問他：「主啊，得救的人很少吧？」 耶穌對眾人說：","notes":[]},{"n":24,"t":"「你們要努力進窄門。我告訴你們，將來有許多人想要進去，卻不能。","notes":[]},{"n":25,"t":"等到一家之主起來關了門，你們才站在外面敲門，說：『主啊，給我們開門！』他要回答你們說：『我不認識你們，不知道你們是哪裏來的。』","notes":[]},{"n":26,"t":"那時，你們要說：『我們在你面前吃過喝過，你也在我們的街上教導過人。』","notes":[]},{"n":27,"t":"他要對你們說：『我告訴你們，我不知道你們是哪裏來的。你們這一切不義的人，給我走開！』","notes":["有古卷加「實在」。"]},{"n":28,"t":"你們要看見亞伯拉罕、以撒、雅各和眾先知都在神的國裏，你們卻被趕到外面，在那裏要哀哭切齒了。","notes":[]},{"n":29,"t":"從東從西，從南從北，將有人來，在神的國裏坐席。","notes":[]},{"n":30,"t":"看吧，在後的，將要在前；在前的，將要在後。」","notes":[]},{"n":31,"t":"就在那時，有幾個法利賽人來對耶穌說：「離開這裏到別處去吧，因為希律想要殺你。」","notes":[],"heads":["為耶路撒冷哀哭"]},{"n":32,"t":"耶穌對他們說：「你們去告訴那個狐狸：『你看吧，今天明天我趕鬼治病，第三天我的事就成了。』","notes":[]},{"n":33,"t":"雖然這樣，今天明天後天我必須向前走，因為先知是不可能在耶路撒冷之外被害的。","notes":[]},{"n":34,"t":"耶路撒冷啊，耶路撒冷啊，你常殺害先知，又用石頭打死那奉差遣到你這裏來的人。我多少次想聚集你的兒女，好像母雞把小雞聚集在翅膀底下，可是你們不願意。","notes":[]},{"n":35,"t":"看吧，你們的家要被廢棄。我告訴你們，你們絕不會再見到我，直到你們說：『奉主名來的是應當稱頌的！』」","notes":[]}]},"14":{"heading":"在安息日治好水腫病人","verses":[{"n":1,"t":"安息日，耶穌到一個法利賽人的領袖家裏去吃飯，他們就窺探他。","notes":[]},{"n":2,"t":"這時在他面前有一個患水腫病的人。","notes":[]},{"n":3,"t":"耶穌回答律法師和法利賽人，說：「安息日治病合不合法？」","notes":[]},{"n":4,"t":"他們卻不說話。耶穌扶著那人，治好了他，叫他走了。","notes":[]},{"n":5,"t":"耶穌對他們說：「你們中間誰有兒子或有牛在安息日掉在井裏，不立刻拉他上來呢？」","notes":["「兒子」：有古卷是「驢」。"]},{"n":6,"t":"他們對這些事不能反駁。","notes":[]},{"n":7,"t":"耶穌見所請的客人選擇首位，就用比喻對他們說：","notes":[],"heads":["對客人和主人的教導"]},{"n":8,"t":"「你被人請去赴婚宴，不要坐在首位上，恐怕主人請了比你尊貴的客人，","notes":[]},{"n":9,"t":"請了你和他的那人前來，對你說：『請讓座給這一位吧。』你就羞羞慚慚地退到末位去了。","notes":[]},{"n":10,"t":"你被請的時候，去坐在末位上，好讓主人來對你說：『朋友，請上座。』那時，你在同席的人面前就有光彩了。","notes":[]},{"n":11,"t":"因為凡自高的，必降為卑；自甘卑微的，必升為高。」","notes":[]},{"n":12,"t":"耶穌又對請他的人說：「你準備午飯或晚餐，不要請你的朋友、弟兄、親屬和富足的鄰舍，免得他們回請你，你就得了報答。","notes":[]},{"n":13,"t":"你擺設宴席，倒要請那貧窮的、殘疾的、瘸腿的、失明的，","notes":[]},{"n":14,"t":"你就有福了！因為他們沒有甚麼可報答你。到義人復活的時候，你要得到報答。」","notes":[]},{"n":15,"t":"同席的有一人聽見這些話，就對耶穌說：「在神國裏吃飯的有福了！」","notes":[],"heads":["大宴席的比喻"]},{"n":16,"t":"耶穌對他說：「有人擺設大宴席，請了許多客人。","notes":[]},{"n":17,"t":"到了坐席的時候，他打發僕人去對所請的人說：『請來吧！樣樣都已齊備了。』","notes":[]},{"n":18,"t":"眾人異口同聲地推辭。頭一個對他說：『我買了一塊地，必須去看看。請你准我辭了。』","notes":[]},{"n":19,"t":"另一個說：『我買了五對牛，要去試一試。請你准我辭了。』","notes":[]},{"n":20,"t":"又有一個說：『我才娶了妻子，所以不能去。』","notes":[]},{"n":21,"t":"那僕人回來，把這些事都告訴了主人。這家的主人就發怒，對僕人說：『快出去，到城裏大街小巷，領那貧窮的、殘疾的、失明的、瘸腿的來。』","notes":[]},{"n":22,"t":"僕人說：『主啊，你所吩咐的已經辦了，還有空位。』","notes":[]},{"n":23,"t":"主人對僕人說：『你出去，到大街小巷強拉人進來，坐滿我的屋子。","notes":[]},{"n":24,"t":"我告訴你們，先前所請的人沒有一個可以嘗到我的宴席。』」","notes":[]},{"n":25,"t":"有一大群人和耶穌同行。他轉過來對他們說：","notes":[],"heads":["作門徒的代價"]},{"n":26,"t":"「無論甚麼人到我這裏來，若不愛我勝過愛自己的父母、妻子、兒女、兄弟、姊妹，甚至自己的性命，就不能作我的門徒。","notes":["「愛我勝過愛」：原文直譯「恨」。"]},{"n":27,"t":"凡不背著自己的十字架來跟從我的，也不能作我的門徒。","notes":[]},{"n":28,"t":"你們哪一個要蓋一座樓，不先坐下來計算費用，看能不能蓋成？","notes":[]},{"n":29,"t":"免得安了地基，不能蓋成，看見的人都笑話他，說：","notes":[]},{"n":30,"t":"『這個人開了工，卻不能完工。』","notes":[]},{"n":31,"t":"或是一個王出去和別的王打仗，豈不先坐下來酌量，他能不能用一萬兵去抵抗那領二萬兵來攻打他的嗎？","notes":[]},{"n":32,"t":"若是不能，他就趁敵人還遠的時候，派使者去談和平的條件。","notes":[]},{"n":33,"t":"這樣，你們無論甚麼人，若不撇下一切所有的，就不能作我的門徒。」","notes":[]},{"n":34,"t":"「鹽本是好的；鹽若失了味，怎能叫它再鹹呢？","notes":[],"heads":["失味的鹽"]},{"n":35,"t":"或用在田裏，或堆在糞裏，都不合適，只好丟在外面。有耳可聽的，就應當聽！」","notes":[]}]},"15":{"heading":"迷羊的比喻","verses":[{"n":1,"t":"許多稅吏和罪人都挨近耶穌，要聽他講道。","notes":[]},{"n":2,"t":"法利賽人和文士私下議論說：「這個人接納罪人，又同他們吃飯。」","notes":[]},{"n":3,"t":"耶穌就用比喻對他們說：","notes":[]},{"n":4,"t":"「你們中間誰有一百隻羊，失去其中的一隻，不把這九十九隻留在曠野，去找那失去的羊，直到找著呢？","notes":[]},{"n":5,"t":"找到了，他就歡歡喜喜地把羊扛在肩上。","notes":[]},{"n":6,"t":"他回到家裏，請朋友和鄰舍來，對他們說：『你們和我一同歡喜吧，我失去的羊已經找到了！』","notes":[]},{"n":7,"t":"我告訴你們，一個罪人悔改，在天上也要這樣為他歡喜，比為九十九個不用悔改的義人歡喜還大呢！」","notes":[]},{"n":8,"t":"「同樣，哪一個婦人有十塊錢，若失落一塊，不點上燈，打掃屋子，細細地找，直到找著呢？","notes":["「錢」：參「度量衡表」；下同。"],"heads":["失錢的比喻"]},{"n":9,"t":"找到了，她就請朋友和鄰舍來，對她們說：『你們和我一同歡喜吧，我失落的那塊錢已經找到了！』","notes":[]},{"n":10,"t":"我告訴你們，一個罪人悔改，神的使者也是這樣為他歡喜。」","notes":[]},{"n":11,"t":"耶穌又說：「一個人有兩個兒子。","notes":[],"heads":["浪子的比喻"]},{"n":12,"t":"小兒子對父親說：『父親，請你把我應得的家業分給我。』他父親就把財產分給他們。","notes":[]},{"n":13,"t":"過了不多幾天，小兒子把他一切所有的都收拾起來，往遠方去了。在那裏，他任意放蕩，浪費錢財。","notes":[]},{"n":14,"t":"他耗盡了一切所有的，又恰逢那地方有大饑荒，就窮困起來。","notes":[]},{"n":15,"t":"於是他去投靠當地的一個居民，那人打發他到田裏去放豬。","notes":[]},{"n":16,"t":"他恨不得拿豬所吃的豆莢充飢，也沒有人給他甚麼吃的。","notes":[]},{"n":17,"t":"他醒悟過來，就說：『我父親有多少雇工，糧食有餘，我倒在這裏餓死嗎？","notes":[]},{"n":18,"t":"我要起來，到我父親那裏去，對他說：父親！我得罪了天，又得罪了你，","notes":[]},{"n":19,"t":"從今以後，我不配稱為你的兒子，把我當作一個雇工吧。』","notes":[]},{"n":20,"t":"於是他起來，往他父親那裏去。相離還遠，他父親看見，就動了慈心，跑去擁抱著他，連連親他。","notes":[]},{"n":21,"t":"兒子對他說：『父親！我得罪了天，又得罪了你，從今以後，我不配稱為你的兒子。』","notes":[]},{"n":22,"t":"父親卻吩咐僕人：『快把那上好的袍子拿出來給他穿，把戒指戴在他指頭上，把鞋穿在他腳上，","notes":[]},{"n":23,"t":"把那肥牛犢牽來宰了，我們來吃喝慶祝；","notes":[]},{"n":24,"t":"因為我這個兒子是死而復活，失而復得的。』他們就開始慶祝。","notes":[]},{"n":25,"t":"「那時，大兒子正在田裏。他回來，離家不遠時，聽見奏樂跳舞的聲音，","notes":[]},{"n":26,"t":"就叫一個僮僕來，問是甚麼事。","notes":[]},{"n":27,"t":"僮僕對他說：『你弟弟回來了，你父親因為他無災無病地回來，把肥牛犢宰了。』","notes":[]},{"n":28,"t":"大兒子就生氣，不肯進去，他父親出來勸他。","notes":[]},{"n":29,"t":"他對父親說：『你看，我服侍你這麼多年，從來沒有違背過你的命令，而你從來沒有給我一隻小山羊，叫我和朋友們一同快樂。","notes":[]},{"n":30,"t":"但你這個兒子和娼妓吃光了你的財產，他一回來，你倒為他宰了肥牛犢。』","notes":[]},{"n":31,"t":"父親對他說：『兒啊！你常和我同在，我所有的一切都是你的；","notes":[]},{"n":32,"t":"可是你這個弟弟是死而復活，失而復得的，所以我們理當歡喜慶祝。』」","notes":[]}]},"16":{"heading":"不義的管家","verses":[{"n":1,"t":"耶穌又對門徒說：「某財主有一個管家，有人向主人告管家浪費他的財物。","notes":[]},{"n":2,"t":"主人叫他來，對他說：『我聽到了，你做的是甚麼事？把你所經管的交代清楚，你不能再作我的管家了。』","notes":[]},{"n":3,"t":"那管家心裏說：『主人辭我，不用我再作管家，我將來做甚麼呢？鋤地嘛，沒有力氣；討飯嘛，怕羞。","notes":[]},{"n":4,"t":"我知道怎麼做，好叫人們在我不作管家之後，接我到他們家裏去。』","notes":[]},{"n":5,"t":"於是他把欠他主人債的，一個一個地叫了來，問頭一個說：『你欠我主人多少？』","notes":[]},{"n":6,"t":"他說：『一百簍油。』管家對他說：『拿你的賬，快坐下，寫五十。』","notes":["「簍」：參「度量衡表」。"]},{"n":7,"t":"他問另一個說：『你欠多少？』他說：『一百石麥子。』管家對他說：『拿你的賬，寫八十。』","notes":[]},{"n":8,"t":"主人就誇獎這不義的管家做事精明，因為今世之子應付自己的世代比光明之子更加精明。","notes":[]},{"n":9,"t":"我又告訴你們，要藉著那不義的錢財結交朋友，到了錢財無用的時候，他們可以接你們到永遠的住處去。","notes":["「住處」：原文直譯「帳幕」。"]},{"n":10,"t":"人在最小的事上忠心，在大事上也忠心；在最小的事上不義，在大事上也不義。","notes":[]},{"n":11,"t":"若是你們在不義的錢財上不忠心，誰還把那真實的錢財託付你們呢？","notes":[]},{"n":12,"t":"如果你們在別人的東西上不忠心，誰還把你們自己的東西給你們呢？","notes":[]},{"n":13,"t":"一個僕人不能服侍兩個主；他不是恨這個愛那個，就是重這個輕那個。你們不能又服侍神，又服侍瑪門。」","notes":["「瑪門」意思是「錢財」。"]},{"n":14,"t":"法利賽人是貪愛錢財的；他們聽見這一切話，就嘲笑耶穌。","notes":[],"heads":["律法和神的國"]},{"n":15,"t":"耶穌對他們說：「你們是在人面前自稱為義的，你們的心，神卻知道；因為人以為尊貴的，是神看為可憎惡的。","notes":[]},{"n":16,"t":"律法和先知到約翰為止，從此神國的福音傳開了，人人努力要進去。","notes":[]},{"n":17,"t":"天地廢去比律法的一點一畫落空還要容易。","notes":[]},{"n":18,"t":"凡休妻另娶的，就是犯姦淫；娶被丈夫休了的婦人的，也是犯姦淫。」","notes":[]},{"n":19,"t":"「有一個財主穿著紫色袍和細麻布衣服，天天奢華宴樂。","notes":[],"heads":["財主和拉撒路"]},{"n":20,"t":"又有一個討飯的，名叫拉撒路，渾身長瘡，被人放在財主門口，","notes":[]},{"n":21,"t":"想得財主桌子上掉下來的碎食充飢，甚至還有狗來舔他的瘡。","notes":[]},{"n":22,"t":"後來那討飯的死了，被天使帶去放在亞伯拉罕的懷裏。財主也死了，並且埋葬了。","notes":[]},{"n":23,"t":"他在陰間受苦，舉目遠遠地望見亞伯拉罕，又望見拉撒路在他懷裏，","notes":[]},{"n":24,"t":"他就喊著說：『我祖亞伯拉罕哪，可憐我吧！請打發拉撒路來，用指頭尖蘸點水，涼涼我的舌頭，因為我在這火焰裏，極其痛苦。』","notes":[]},{"n":25,"t":"亞伯拉罕說：『孩子啊，你該回想你生前享過福，拉撒路也同樣受過苦，如今他在這裏得安慰，你卻受痛苦。","notes":[]},{"n":26,"t":"除此之外，在你們和我們之間，有深淵隔開，以致人要從這邊過到你們那邊是不可能的；要從那邊過到這邊也是不可能的。』","notes":[]},{"n":27,"t":"財主說：『我祖啊，既然這樣，求你打發拉撒路到我父家去，","notes":[]},{"n":28,"t":"因為我還有五個兄弟，他可以警告他們，免得他們也來到這痛苦的地方。』","notes":[]},{"n":29,"t":"亞伯拉罕說：『他們有摩西和先知的話可以聽從。』","notes":[]},{"n":30,"t":"他說：『不！我祖亞伯拉罕哪，假如有一個人從死人中到他們那裏去，他們一定會悔改。』","notes":[]},{"n":31,"t":"亞伯拉罕對他說：『如果他們不聽從摩西和先知的話，就是有人從死人中復活，他們也不會信服的。』」","notes":[]}]},"17":{"heading":"饒恕得罪你的人","verses":[{"n":1,"t":"耶穌又對門徒說：「絆倒人的事是免不了的，但那絆倒人的有禍了！","notes":[]},{"n":2,"t":"人若把這些小子中的一個絆倒的，還不如把磨石拴在他的頸項上，丟在海裏。","notes":[]},{"n":3,"t":"你們要謹慎！若是你的弟兄犯罪，就勸戒他；他若懊悔，就饒恕他。","notes":[]},{"n":4,"t":"如果他一天七次得罪你，又七次回頭，說：『我懊悔了』，你總要饒恕他。」","notes":[]},{"n":5,"t":"使徒對主說：「請加增我們的信心。」","notes":[],"heads":["信心的能力"]},{"n":6,"t":"主說：「你們若有信心像一粒芥菜種，就是對這棵桑樹說：『你要連根拔起，栽在海裏』，它也會聽從你們。」","notes":[]},{"n":7,"t":"「你們當中誰有僕人耕地或是放羊，從田裏回來，就對他說『你快來坐下吃飯』呢？","notes":[],"heads":["僕人的本分"]},{"n":8,"t":"他豈不對僕人說『你給我預備晚飯，束上帶子伺候我，等我吃喝完了，你才可以吃喝』嗎？","notes":[]},{"n":9,"t":"僕人照所吩咐的去做，主人還謝謝他嗎？","notes":[]},{"n":10,"t":"這樣，你們做完了一切所吩咐的，要說：『我們是無用的僕人，所做的本是我們該做的。』」","notes":[]},{"n":11,"t":"耶穌往耶路撒冷去，經過撒瑪利亞和加利利中間的地區。","notes":[],"heads":["治好十個痲瘋病人"]},{"n":12,"t":"他進入一個村子，有十個痲瘋病人迎面而來，遠遠地站著，","notes":[]},{"n":13,"t":"高聲說：「耶穌，老師啊，可憐我們吧！」","notes":[]},{"n":14,"t":"耶穌看見，就對他們說：「你們去，把身體給祭司檢查。」他們正去的時候就潔淨了。","notes":[]},{"n":15,"t":"其中有一個見自己已經好了，就回來大聲歸榮耀給神，","notes":[]},{"n":16,"t":"又俯伏在耶穌腳前感謝他。這人是撒瑪利亞人。","notes":[]},{"n":17,"t":"耶穌回答說：「潔淨了的不是十個人嗎？那九個在哪裏呢？","notes":[]},{"n":18,"t":"除了這外族人，再沒有別人回來歸榮耀給神嗎？」","notes":[]},{"n":19,"t":"於是他對那人說：「起來，走吧，你的信救了你！」","notes":[]},{"n":20,"t":"法利賽人問：「神的國幾時來到？」耶穌回答：「神的國來到，不是眼睛看得見的。","notes":[],"heads":["神國的來到"]},{"n":21,"t":"人也不能說：『看哪，在這裏！』或說：『在那裏！』因為神的國就在你們心裏。」","notes":["「心裏」或譯「中間」。"]},{"n":22,"t":"他又對門徒說：「那些日子將到，你們渴望能看見人子的一個日子，卻看不見。","notes":[]},{"n":23,"t":"有人要對你們說：『看哪，在那裏！』或說：『看哪，在這裏！』你們不要出去，也不要追隨他們。","notes":[]},{"n":24,"t":"好像閃電從天這邊一閃直照到天那邊，人子在他的日子也要這樣。","notes":["有古卷沒有「在他的日子」。"]},{"n":25,"t":"可是他必須先受許多苦，又被這世代所棄絕。","notes":[]},{"n":26,"t":"挪亞的日子怎樣，人子的日子也要怎樣。","notes":[]},{"n":27,"t":"那時，人又吃又喝，又娶又嫁，直到挪亞進方舟的那日，洪水就來，把他們全都滅了。","notes":[]},{"n":28,"t":"同樣，就像在羅得的日子，人又吃又喝，又買又賣，又耕種又建造，","notes":[]},{"n":29,"t":"到羅得離開所多瑪的那日，有火與硫磺從天上降下來，把他們全都滅了。","notes":[]},{"n":30,"t":"人子顯現的日子也要這樣。","notes":[]},{"n":31,"t":"在那日，人在屋頂上，東西在屋裏，不要下來拿；人在田裏，也不要回家。","notes":[]},{"n":32,"t":"你們想想羅得的妻子吧！","notes":[]},{"n":33,"t":"凡想保全性命的，要喪失性命；凡喪失性命的，要保存性命。","notes":[]},{"n":34,"t":"我告訴你們，在那一夜，兩個人在一張床上，一個被接去，一個被撇下。","notes":[]},{"n":35,"t":"兩個女人一同推磨，一個被接去，一個被撇下。」","notes":["有古卷加「36 兩個人在田裏，一個被接去，一個被撇下。」"]},{"n":37,"t":"門徒回答他說：「主啊，在哪裏呢？」耶穌對他們說：「屍首在哪裏，鷹也會聚在哪裏。」","notes":[]}]},"18":{"heading":"寡婦和法官的比喻","verses":[{"n":1,"t":"耶穌對門徒講了一個比喻，為了要他們常常禱告，不可灰心。","notes":[]},{"n":2,"t":"他說：「某城有一個官，不懼怕神，也不尊重人。","notes":[]},{"n":3,"t":"那城裏有個寡婦，常到他那裏，說：『我有一個冤家，求你給我伸冤。』","notes":[]},{"n":4,"t":"他很久不受理，後來心裏說：『我雖不懼怕神，也不尊重人，","notes":[]},{"n":5,"t":"只因這寡婦煩擾我，我就給她伸冤吧，免得她常來糾纏我。』」","notes":[]},{"n":6,"t":"主說：「你們聽這不義的官所說的話。","notes":[]},{"n":7,"t":"神的選民晝夜呼籲他，他豈會延遲不給他們伸冤嗎？","notes":[]},{"n":8,"t":"我告訴你們，他很快就要給他們伸冤。然而，人子來的時候，能在世上找到這樣的信德嗎？」","notes":[]},{"n":9,"t":"耶穌向那些自以為義而藐視別人的人講了這比喻：","notes":[],"heads":["法利賽人和稅吏的禱告"]},{"n":10,"t":"「有兩個人上聖殿去禱告，一個是法利賽人，一個是稅吏。","notes":[]},{"n":11,"t":"法利賽人獨自站著，自言自語地禱告說：『神啊，我感謝你，我不像別人勒索、不義、姦淫，也不像這個稅吏。","notes":[]},{"n":12,"t":"我每週禁食兩次，凡我所得的都獻上十分之一。』","notes":[]},{"n":13,"t":"那稅吏遠遠地站著，連舉目望天也不敢，只捶著胸，說：『神啊，開恩可憐我這個罪人！』","notes":[]},{"n":14,"t":"我告訴你們，這人回家去比那人倒算為義了。因為凡自高的，必降為卑；自甘卑微的，必升為高。」","notes":[]},{"n":15,"t":"有人甚至連嬰孩也帶來見耶穌，要他摸他們，門徒看見就責備那些人。","notes":[],"heads":["耶穌為小孩祝福"]},{"n":16,"t":"耶穌卻叫他們來，說：「讓小孩子到我這裏來，不要阻止他們，因為在神國的正是這樣的人。","notes":[]},{"n":17,"t":"我實在告訴你們，凡要接受神國的，若不像小孩子，絕不能進去。」","notes":[]},{"n":18,"t":"有一個官問耶穌說：「善良的老師，我該做甚麼事才能承受永生？」","notes":[],"heads":["富足的官尋求永生"]},{"n":19,"t":"耶穌對他說：「你為甚麼稱我是善良的？除了神一位之外，再沒有善良的。","notes":[]},{"n":20,"t":"誡命你是知道的：『不可姦淫；不可殺人；不可偷盜；不可作假見證；當孝敬父母。』」","notes":[]},{"n":21,"t":"那人說：「這一切我從小都遵守了。」","notes":[]},{"n":22,"t":"耶穌聽見了，就對他說：「你還缺少一件：要變賣你一切所有的，分給窮人，就必有財寶在天上；你還要來跟從我。」","notes":[]},{"n":23,"t":"他聽見這些話，就很憂愁，因為他很富有。","notes":[]},{"n":24,"t":"耶穌見他變得很憂愁，就說：「有錢財的人進神的國是何等的難哪！","notes":["有古卷沒有「變得很憂愁」。"]},{"n":25,"t":"駱駝穿過針眼比財主進神的國還容易呢！」","notes":[]},{"n":26,"t":"聽見的人說：「這樣，誰能得救呢？」","notes":[]},{"n":27,"t":"耶穌說：「在人所不能的事，在神都能。」","notes":[]},{"n":28,"t":"彼得說：「看哪，我們已經撇下自己所有的跟從你了。」","notes":[]},{"n":29,"t":"耶穌對他們說：「我實在告訴你們，凡是為神的國撇下房屋，或是妻子、兄弟、父母、兒女的，","notes":[]},{"n":30,"t":"沒有不在今世得更多倍，而在來世得永生的。」","notes":[]},{"n":31,"t":"耶穌把十二使徒帶到一邊，對他們說：「看哪，我們上耶路撒冷去，先知所寫的一切事都要成就在人子身上。","notes":[],"heads":["耶穌第三次預言受難和復活"]},{"n":32,"t":"他將被交給外邦人；他們要戲弄他，凌辱他，向他吐唾沫，","notes":[]},{"n":33,"t":"並要鞭打他，殺害他；第三天他要復活。」","notes":[]},{"n":34,"t":"這些事門徒一點也不明白，這話的意思對他們是隱藏的；他們不知道所說的是甚麼。","notes":[]},{"n":35,"t":"耶穌將近耶利哥的時候，有一個盲人坐在路旁討飯。","notes":[],"heads":["治好耶利哥的盲人"]},{"n":36,"t":"他聽見許多人經過，就問是甚麼事。","notes":[]},{"n":37,"t":"他們告訴他，是拿撒勒人耶穌經過。","notes":[]},{"n":38,"t":"他就呼叫說：「大衛之子耶穌啊，可憐我吧！」","notes":[]},{"n":39,"t":"在前頭走的人就責備他，不許他作聲，他卻越發喊叫：「大衛之子啊，可憐我吧！」","notes":[]},{"n":40,"t":"耶穌就站住，吩咐把他領過來，他到了跟前，就問他：","notes":[]},{"n":41,"t":"「你要我為你做甚麼？」他說：「主啊，我要能看見。」","notes":[]},{"n":42,"t":"耶穌對他說：「你看見吧！你的信救了你。」","notes":[]},{"n":43,"t":"那盲人立刻看得見了，就跟隨耶穌，一路歸榮耀給神。眾人看見這事，也都讚美神。","notes":[]}]},"19":{"heading":"撒該悔改","verses":[{"n":1,"t":"耶穌進了耶利哥，要從那裏經過。","notes":[]},{"n":2,"t":"有一個人名叫撒該，作稅吏長，是個財主。","notes":[]},{"n":3,"t":"他要看看耶穌是怎樣的人，只因人多，他的身材又矮，所以看不見。","notes":[]},{"n":4,"t":"於是他跑到前頭，爬上桑樹，要看耶穌，因為耶穌要從那裏經過。","notes":[]},{"n":5,"t":"耶穌到了那裏，抬頭一看，對他說：「撒該，快下來！今天我必須住在你家裏。」","notes":[]},{"n":6,"t":"他就急忙下來，歡歡喜喜地接待耶穌。","notes":[]},{"n":7,"t":"眾人看見，都私下議論說：「他竟然到罪人家裏去住宿。」","notes":[]},{"n":8,"t":"撒該站著對主說：「主啊，我把所有的一半給窮人；我若勒索了誰，就還他四倍。」","notes":[]},{"n":9,"t":"耶穌對他說：「今天救恩到了這家，因為他也是亞伯拉罕的子孫。","notes":[]},{"n":10,"t":"人子來是要尋找和拯救失喪的人。」","notes":[]},{"n":11,"t":"眾人正聽見這些話的時候，耶穌因為將近耶路撒冷，又因他們以為神的國快要顯現，就接著講了一個比喻，","notes":[],"heads":["十錠銀子的比喻"]},{"n":12,"t":"說：「有一個貴族往遠方去，為要取得王位，然後回來。","notes":[]},{"n":13,"t":"他叫了自己的十個僕人來，交給他們十錠銀子，說：『你們去做生意，直到我回來。』","notes":[]},{"n":14,"t":"他本國的百姓卻恨他，打發使者隨後去，說：『我們不願意這個人作我們的王。』","notes":[]},{"n":15,"t":"他得了王位回來，就吩咐叫那領了銀子的僕人來，要知道他們做生意賺了多少。","notes":[]},{"n":16,"t":"頭一個上來，說：『主啊，你的一錠銀子已經賺了十錠。』","notes":[]},{"n":17,"t":"主人對他說：『好，我善良的僕人，你既在最小的事上忠心，你有權柄管十座城。』","notes":[]},{"n":18,"t":"第二個來，說：『主啊，你的一錠銀子已經賺了五錠。』","notes":[]},{"n":19,"t":"主人也對這個說：『你管五座城。』","notes":[]},{"n":20,"t":"又有一個來說：『主啊！看哪，你的一錠銀子在這裏，我把它包在手巾裏存著。","notes":[]},{"n":21,"t":"我向來怕你，因為你是嚴厲的人：沒有放的，也要去拿；沒有種的，也要去收。』","notes":[]},{"n":22,"t":"主人對他說：『你這惡僕，我要憑你的話定你的罪。你既知道我是嚴厲的人，沒有放的也去拿，沒有種的也去收，","notes":[]},{"n":23,"t":"為甚麼不把我的銀子存在銀行，等我來的時候，連本帶利都取回來呢？』","notes":[]},{"n":24,"t":"於是他對那些站在旁邊的人說：『把他這一錠奪過來，給那有十錠的。』","notes":[]},{"n":25,"t":"他們對他說：『主啊，他已經有十錠了。』","notes":[]},{"n":26,"t":"主人說：『我告訴你們，凡有的，還要給他；沒有的，連他所有的也要奪過來。","notes":[]},{"n":27,"t":"至於我那些仇敵，不要我作他們王的，把他們拉來，在我面前殺了！』」","notes":[]},{"n":28,"t":"耶穌說完了這些話，就走在前面，上耶路撒冷去。","notes":[],"heads":["榮入聖城"]},{"n":29,"t":"快到伯法其和伯大尼，在名叫橄欖山的地方，他打發兩個門徒，","notes":[]},{"n":30,"t":"說：「你們往對面村子裏去，進去的時候會看見一匹驢駒拴在那裏，是從來沒有人騎過的，把牠解開，牽來。","notes":[]},{"n":31,"t":"若有人問為甚麼解開牠，你們就這樣說：『主要用牠。』」","notes":[]},{"n":32,"t":"被打發的人去了，所遇見的正如耶穌對他們所說的。","notes":[]},{"n":33,"t":"他們解開驢駒的時候，主人問他們：「為甚麼解開驢駒？」","notes":[]},{"n":34,"t":"他們說：「主要用牠。」","notes":[]},{"n":35,"t":"他們把驢駒牽到耶穌那裏，把自己的衣服搭在上面，扶耶穌騎上。","notes":[]},{"n":36,"t":"他前進的時候，眾人把衣服鋪在路上。","notes":[]},{"n":37,"t":"他將近耶路撒冷，正下橄欖山的時候，一大群門徒因所見過的一切異能，都歡呼起來，大聲讚美神，","notes":[]},{"n":38,"t":"說：「奉主名來的王是應當稱頌的！在天上有和平；在至高之處有榮光。」","notes":["有古卷沒有「王」。"]},{"n":39,"t":"人群中有幾個法利賽人對耶穌說：「老師，責備你的門徒吧！」","notes":[]},{"n":40,"t":"耶穌回答：「我告訴你們，若是這些人閉口不說，石頭也要呼叫起來。」","notes":[]},{"n":41,"t":"耶穌快到耶路撒冷，看見那城，就為它哀哭，","notes":[]},{"n":42,"t":"說：「但願你在這日子知道有關你平安的事，不過這事現在是隱藏的，你的眼睛看不出來。","notes":[]},{"n":43,"t":"因為日子將到，你的仇敵要築起土壘包圍你，四面困住你，","notes":[]},{"n":44,"t":"並要消滅你和你裏頭的兒女，連一塊石頭也不留在另一塊石頭上，因為你不知道你蒙眷顧的時候。」","notes":[]},{"n":45,"t":"耶穌一進聖殿就趕出在裏面做買賣的人，","notes":[],"heads":["潔淨聖殿"]},{"n":46,"t":"對他們說：「經上說：『我的殿是禱告的殿，你們倒使它成為賊窩了。』」","notes":[]},{"n":47,"t":"耶穌天天在聖殿裏教導人。祭司長、文士和百姓的領袖都想殺他，","notes":[]},{"n":48,"t":"但找不出方法來，因為百姓都側耳聽他。","notes":[]}]},"20":{"heading":"耶穌的權柄受到質問","verses":[{"n":1,"t":"有一天，耶穌在聖殿裏教導百姓，宣講福音的時候，祭司長、文士和長老上前來，","notes":[]},{"n":2,"t":"問他說：「你告訴我們，你仗著甚麼權柄做這些事？給你這權柄的是誰呢？」","notes":[]},{"n":3,"t":"耶穌回答他們：「我也要問你們一句話，你們告訴我。","notes":[]},{"n":4,"t":"約翰的洗禮是從天上來的，還是從人間來的呢？」","notes":[]},{"n":5,"t":"他們彼此商量說：「我們若說『從天上來的』，他會說『這樣，你們為甚麼不信他呢？』","notes":[]},{"n":6,"t":"我們若說『從人間來的』，所有的百姓都會用石頭打死我們，因為他們信約翰是先知。」","notes":[]},{"n":7,"t":"於是他們回答：「我們不知道是從哪裏來的。」","notes":[]},{"n":8,"t":"耶穌對他們說：「我也不告訴你們，我仗著甚麼權柄做這些事。」","notes":[]},{"n":9,"t":"耶穌用這個比喻對百姓說：「有人開墾了一個葡萄園，租給園戶，就出外遠行，去了許久。","notes":[],"heads":["惡園戶的比喻"]},{"n":10,"t":"到了時候，他打發一個僕人到園戶那裏去，叫他們把園中當納的果子交給他；園戶竟打了他，叫他空手回去。","notes":[]},{"n":11,"t":"園主又打發另一個僕人去，他們也打了他，並且侮辱他，叫他空手回去。","notes":[]},{"n":12,"t":"園主又打發第三個僕人去，他們也打傷了他，把他推出去了。","notes":[]},{"n":13,"t":"葡萄園主說：『我要怎麼做呢？我要打發我的愛子去，或許他們會尊敬他。』","notes":[]},{"n":14,"t":"可是，園戶看見他，彼此說：『這是承受產業的。我們殺了他，產業就歸我們了！』","notes":[]},{"n":15,"t":"於是他們把他扔出葡萄園外，殺了。這樣，葡萄園主要怎麼處置他們呢？","notes":[]},{"n":16,"t":"他要來除滅那些園戶，將葡萄園轉給別人。」聽見的人說：「絕對不可！」","notes":[]},{"n":17,"t":"耶穌看著他們，說：「那麼，經上記著：『匠人所丟棄的石頭已作了房角的頭塊石頭。』這是甚麼意思呢？","notes":[]},{"n":18,"t":"凡跌在那石頭上的，一定會跌得粉碎；那石頭掉在誰的身上，就要把誰壓得稀爛。」","notes":[]},{"n":19,"t":"文士和祭司長看出這比喻是指著他們說的，當時就想要下手拿他，只是懼怕百姓。","notes":[]},{"n":20,"t":"於是他們窺探耶穌，打發奸細裝作好人，要在他的話上抓把柄，好把他交給總督處置。","notes":[],"heads":["納稅給凱撒的問題"]},{"n":21,"t":"奸細就問耶穌：「老師，我們知道你所講所教的都很正確，也不看人的面子，而是誠誠實實傳神的道。","notes":[]},{"n":22,"t":"我們納稅給凱撒合不合法？」","notes":[]},{"n":23,"t":"耶穌看出他們的詭詐，就對他們說：","notes":[]},{"n":24,"t":"「拿一個銀幣來給我看。這像和這名號是誰的？」他們說：「是凱撒的。」","notes":[]},{"n":25,"t":"耶穌對他們說：「這樣，凱撒的歸凱撒，神的歸神。」","notes":[]},{"n":26,"t":"他們無法當著百姓在他的話上抓到把柄，又因他的對答而驚訝，就閉口不言了。","notes":[]},{"n":27,"t":"有些撒都該人來見耶穌。他們說沒有復活這回事，於是問耶穌：","notes":[],"heads":["復活的問題"]},{"n":28,"t":"「老師，摩西為我們寫下這話：『某人的哥哥若死了，有妻無子，他該娶哥哥的妻子，為哥哥生子立後。』","notes":[]},{"n":29,"t":"那麼，有兄弟七人，第一個娶了妻，沒有孩子死了。","notes":[]},{"n":30,"t":"第二個、","notes":[]},{"n":31,"t":"第三個也娶過她；同樣地，七個人都娶過她，沒有留下孩子就死了。","notes":[]},{"n":32,"t":"後來，那婦人也死了。","notes":[]},{"n":33,"t":"那麼，在復活的時候，那婦人是哪一個的妻子呢？因為他們七個人都娶過她。」","notes":[]},{"n":34,"t":"耶穌對他們說：「這世代的人有娶有嫁，","notes":[]},{"n":35,"t":"惟有配得那要來的世代和從死人中復活的人不娶也不嫁。","notes":[]},{"n":36,"t":"因為他們不能再死，和天使一樣；既然是復活的人，他們就是神的兒子。","notes":[]},{"n":37,"t":"至於死人復活，摩西在《荊棘篇》上就指明了，他稱主是亞伯拉罕的神，以撒的神，雅各的神。","notes":[]},{"n":38,"t":"神不是死人的神，而是活人的神，因為對他來說，人都是活的。」","notes":[]},{"n":39,"t":"有幾個文士說：「老師，你說得好。」","notes":[]},{"n":40,"t":"以後，他們不敢再問他甚麼了。","notes":[]},{"n":41,"t":"耶穌對他們說：「人們怎麼說基督是大衛的後裔呢？","notes":[],"heads":["基督與大衛的關係"]},{"n":42,"t":"《詩篇》上大衛自己說：「主對我主說：『你坐在我的右邊，","notes":[]},{"n":43,"t":"等我使你的仇敵作你的腳凳。』","notes":[]},{"n":44,"t":"大衛既稱他為主，他怎麼又是大衛的後裔呢？」","notes":[]},{"n":45,"t":"眾百姓聽的時候，耶穌對他的門徒說：","notes":[],"heads":["譴責文士"]},{"n":46,"t":"「你們要防備文士。他們好穿長袍走來走去，喜歡人們在街市上向他們問安，又喜愛會堂裏的高位，宴席上的首座。","notes":[]},{"n":47,"t":"他們侵吞寡婦的家產，假意作很長的禱告。這些人要受更重的懲罰！」","notes":[]}]},"21":{"heading":"寡婦的奉獻","verses":[{"n":1,"t":"耶穌抬頭觀看，見財主把捐項投入聖殿銀庫，","notes":[]},{"n":2,"t":"又見一個窮寡婦投了兩個小文錢，","notes":["「小文錢」：參「度量衡表」。"]},{"n":3,"t":"就說：「我實在告訴你們，這窮寡婦所投的比眾人更多。","notes":[]},{"n":4,"t":"因為眾人都是拿有餘的捐獻，但這寡婦，雖然自己不足，卻把一生所有的都投進去了。」","notes":[]},{"n":5,"t":"有人談論聖殿是用美石和供物裝飾的，耶穌就說：","notes":[],"heads":["預言聖殿被毀"]},{"n":6,"t":"「你們所看見的這一切，日子將到，沒有一塊石頭會留在另一塊石頭上而不被拆毀的。」","notes":[]},{"n":7,"t":"他們問他：「老師，甚麼時候有這些事呢？這些事將臨到的時候有甚麼預兆呢？」","notes":[],"heads":["終局的預兆"]},{"n":8,"t":"耶穌說：「你們要謹慎，不要受迷惑，因為將有好些人冒我的名來，說『我是基督』，又說『時候近了』，你們不要跟從他們！","notes":[]},{"n":9,"t":"當你們聽見打仗和動亂的事，不要驚惶；因為這些事必須先發生，但終結不會立刻就到。」","notes":[]},{"n":10,"t":"於是耶穌對他們說：「民要攻打民，國要攻打國，","notes":[]},{"n":11,"t":"將有大地震，多處必有饑荒、瘟疫，又有可怕的異象和大神蹟從天上顯現。","notes":[]},{"n":12,"t":"但這一切的事以前，有人要下手拿你們，迫害你們，把你們交給會堂，並且關在監裏，又為我名的緣故拉你們到君王和統治者面前。","notes":[]},{"n":13,"t":"但這些事終必成為你們作見證的機會。","notes":[]},{"n":14,"t":"所以，你們要立定心意，不要預先考慮怎樣申辯；","notes":[]},{"n":15,"t":"因為我必賜你們口才和智慧，是你們一切敵人所敵不住、駁不倒的。","notes":[]},{"n":16,"t":"連你們的父母、兄弟、親族、朋友也要把你們交給官府；你們中間也將有被他們害死的。","notes":[]},{"n":17,"t":"你們要為我的名被眾人憎恨。","notes":[]},{"n":18,"t":"然而，你們連一根頭髮也不會損失。","notes":[]},{"n":19,"t":"你們憑著堅忍，就必保全性命。」","notes":[]},{"n":20,"t":"「當你們看見耶路撒冷被兵圍困，就可知道它成為荒蕪的日子近了。","notes":[],"heads":["預言耶路撒冷被毀"]},{"n":21,"t":"那時，在猶太的，應當逃到山上；在城裏的，應當出來；在鄉下的，不要進城。","notes":[]},{"n":22,"t":"因為這是報應的日子，要使經上所寫的都得應驗。","notes":[]},{"n":23,"t":"在那些日子，懷孕的和奶孩子的就苦了。因為將有大災難降在這地方，也有憤怒臨到這百姓。","notes":[]},{"n":24,"t":"他們要倒在刀下，又被擄到各國去。耶路撒冷要被外邦人踐踏，直到外邦人的日子滿了。」","notes":[]},{"n":25,"t":"「日月星辰要顯出預兆，地上的邦國也有困苦，因海中波浪的響聲而惶惶不安。","notes":[],"heads":["人子的來臨"]},{"n":26,"t":"人想到那要臨到世界的事，就都嚇得魂不附體，因為天上的萬象都要震動。","notes":[]},{"n":27,"t":"那時，他們要看見人子帶著能力和大榮耀駕雲來臨。","notes":[]},{"n":28,"t":"一有這些事，你們就當挺身昂首，因為你們得救贖的日子近了。」","notes":[]},{"n":29,"t":"耶穌對他們講了一個比喻說：「你們看無花果樹和各樣的樹，","notes":[],"heads":["從無花果樹學功課"]},{"n":30,"t":"樹葉一長出來，你們看了自然就知道夏天近了。","notes":[]},{"n":31,"t":"同樣，當你們看見這些事發生，就知道神的國近了。","notes":[]},{"n":32,"t":"我實在告訴你們，這世代還沒有過去，一切都要發生。","notes":[]},{"n":33,"t":"天地要廢去，我的話卻絕不廢去。」","notes":[]},{"n":34,"t":"「你們要謹慎，免得被貪食、醉酒和今生的憂慮壓住你們的心，那日子就忽然臨到你們，","notes":[],"heads":["勸告門徒警醒"]},{"n":35,"t":"如同羅網一樣，因為那日子要臨到所有居住在地面上的人。","notes":[]},{"n":36,"t":"你們要時時警醒，常常祈求，使你們能逃避這一切要來的事，得以站立在人子面前。」","notes":[]},{"n":37,"t":"耶穌每日在聖殿裏教導人，每夜出城到橄欖山住宿。","notes":[]},{"n":38,"t":"眾百姓清早上聖殿，到耶穌那裏聽他講道。","notes":[]}]},"22":{"heading":"殺害耶穌的陰謀","verses":[{"n":1,"t":"除酵節，又叫逾越節，近了。","notes":[]},{"n":2,"t":"祭司長和文士在想法子怎樣殺害耶穌，因他們懼怕百姓。","notes":[]},{"n":3,"t":"這時，撒但入了那稱為加略人猶大的心。他本是十二使徒裏的一個。","notes":[]},{"n":4,"t":"他去跟祭司長和守殿官商量怎樣把耶穌交給他們。","notes":[]},{"n":5,"t":"他們很高興，就約定給他銀子。","notes":[]},{"n":6,"t":"他應允了，就找機會，要趁眾人不在跟前的時候把耶穌交給他們。","notes":[]},{"n":7,"t":"除酵節到了，這一天必須宰逾越節的羔羊。","notes":[],"heads":["預備逾越節的宴席"]},{"n":8,"t":"耶穌打發彼得和約翰，說：「你們去為我們預備逾越節的宴席，好讓我們吃。」","notes":[]},{"n":9,"t":"他們問他：「你要我們在哪裏預備？」","notes":[]},{"n":10,"t":"耶穌對他們說：「你們進了城，會有人拿著一罐水迎面而來，你們就跟著他，到他所進的房子裏去，","notes":[]},{"n":11,"t":"對那家的主人說：『老師問：客房在哪裏？我和我的門徒要在那裏吃逾越節的宴席。』","notes":[]},{"n":12,"t":"他會帶你們看一間擺設齊全的樓上大廳，你們就在那裏預備。」","notes":[]},{"n":13,"t":"他們去了，所看到的正如耶穌所說的。他們就預備了逾越節的宴席。","notes":[]},{"n":14,"t":"時候到了，耶穌坐席，使徒們也和他同坐。","notes":[],"heads":["設立主的晚餐"]},{"n":15,"t":"耶穌對他們說：「我非常渴望在受害以前和你們吃這逾越節的宴席。","notes":[]},{"n":16,"t":"我告訴你們，我不再吃這宴席，直到它實現在神的國裏。」","notes":[]},{"n":17,"t":"耶穌接過杯來，祝謝了，說：「你們拿這杯，大家分著喝。","notes":[]},{"n":18,"t":"我告訴你們，從今以後，我不再喝這葡萄汁，直等神的國來到。」","notes":[]},{"n":19,"t":"他又拿起餅來，祝謝了，就擘開，遞給他們，說：「這是我的身體，為你們捨的，你們要如此行，為的是記念我。」","notes":[]},{"n":20,"t":"飯後他照樣拿起杯來，說：「這杯是用我的血所立的新約，為你們流出來的。","notes":[]},{"n":21,"t":"但是，看哪，那出賣我的人的手跟我一同在桌子上。","notes":[]},{"n":22,"t":"人子固然要照所預定的離去，但那出賣人子的人有禍了！」","notes":[]},{"n":23,"t":"於是他們開始互相追問他們中間哪一個會做這事。","notes":[]},{"n":24,"t":"門徒中間也起了爭論：他們中哪一個可算為大。","notes":[],"heads":["爭論誰為大"]},{"n":25,"t":"耶穌對他們說：「外邦人有君王為主治理他們，那掌權管他們的稱為恩主。","notes":[]},{"n":26,"t":"但你們不可這樣。你們中間最大的，倒要成為最小的；為領袖的，倒要像服事人的。","notes":[]},{"n":27,"t":"是誰為大？是坐席的還是服事人的呢？不是坐席的大嗎？然而，我在你們中間是如同服事人的。","notes":[]},{"n":28,"t":"「我在試煉之中，常和我同在的就是你們。","notes":[]},{"n":29,"t":"我把國賜給你們，正如我父賜給我一樣，","notes":[]},{"n":30,"t":"使你們在我的國裏坐在我的席上吃喝，並且坐在寶座上審判以色列十二個支派。」","notes":[]},{"n":31,"t":"主又說：「西門，西門！撒但要得著你們，好篩你們像篩麥子一樣；","notes":[],"heads":["預言彼得不認主"]},{"n":32,"t":"但我已經為你祈求，使你不至於失了信心。你回頭以後，要堅固你的弟兄。」","notes":[]},{"n":33,"t":"彼得對他說：「主啊，我已準備好要同你坐牢，與你同死。」","notes":[]},{"n":34,"t":"耶穌說：「彼得，我告訴你，今日雞還沒有叫，你要三次說不認得我。」","notes":[]},{"n":35,"t":"耶穌又對他們說：「我差你們出去的時候，沒有錢囊，沒有行囊，沒有鞋子，你們缺少甚麼沒有？」他們說：「沒有。」","notes":[],"heads":["錢囊、行囊、刀"]},{"n":36,"t":"耶穌對他們說：「但如今，有錢囊的要帶著，有行囊的也一樣；沒有刀的要賣衣服買刀。","notes":[]},{"n":37,"t":"我告訴你們，經上寫著說：『他被列在罪犯之中。』這話必須應驗在我身上，因為那關於我的事必然成就。」","notes":[]},{"n":38,"t":"他們說：「主啊，請看！這裏有兩把刀。」耶穌對他們說：「夠了。」","notes":[]},{"n":39,"t":"耶穌出來，照常往橄欖山去，門徒也跟隨他。","notes":[],"heads":["在橄欖山上禱告"]},{"n":40,"t":"到了那地方，他就對他們說：「你們要禱告，免得陷入試探。」","notes":[]},{"n":41,"t":"於是他離開他們約有一塊石頭扔出去那麼遠，跪下禱告，","notes":[]},{"n":42,"t":"說：「父啊！你若願意，求你將這杯撤去；然而，不是照我的意願，而是要成全你的旨意。」","notes":[]},{"n":43,"t":"〔 有一位天使從天上顯現，加添他的力量。","notes":[]},{"n":44,"t":"耶穌非常痛苦焦慮，禱告更加懇切，汗如大血點滴在地上。〕","notes":["有古卷沒有43、44兩節。"]},{"n":45,"t":"禱告完了，他起來，到門徒那裏，見他們因為憂愁都睡著了，","notes":[]},{"n":46,"t":"就對他們說：「你們為甚麼睡覺呢？起來禱告，免得陷入試探！」","notes":[]},{"n":47,"t":"耶穌還在說話的時候，來了一群人。十二使徒之一名叫猶大的，走在前頭，接近耶穌，要親他。","notes":[],"heads":["耶穌被捕"]},{"n":48,"t":"耶穌對他說：「猶大，你用親吻來出賣人子嗎？」","notes":[]},{"n":49,"t":"左右的人見了要發生的事，就說：「主啊，我們拿刀砍好不好？」","notes":[]},{"n":50,"t":"其中有一個人把大祭司的僕人砍了一刀，削掉了他的右耳。","notes":[]},{"n":51,"t":"耶穌回答說：「算了，住手吧！」就摸那人的耳朵，把他治好了。","notes":[]},{"n":52,"t":"耶穌對那些來抓他的祭司長、守殿官和長老說：「你們帶著刀棒出來，如同對付強盜嗎？","notes":[]},{"n":53,"t":"我天天同你們在聖殿裏，你們不下手抓我。現在卻是你們的時候，黑暗掌權了。」","notes":[]},{"n":54,"t":"他們拿住耶穌，把他帶走，進入大祭司的住宅。彼得遠遠地跟著。","notes":[],"heads":["彼得三次不認主"]},{"n":55,"t":"他們在院子中間生了火，一同坐著，彼得也坐在他們當中。","notes":[]},{"n":56,"t":"有一個使女看見彼得面向火光坐著，就定睛看他，說：「這個人素來也是同那人一起的。」","notes":[]},{"n":57,"t":"彼得卻不承認，說：「你這個女人，我不認得他！」","notes":[]},{"n":58,"t":"過了一會兒，又有一個人看見他，說：「你也是他們一夥的。」彼得說：「你這個人，我不是！」","notes":[]},{"n":59,"t":"約過了一小時，又有一個人堅持說：「他實在是同那人一起的，因為他也是加利利人。」","notes":[]},{"n":60,"t":"彼得說：「你這個人，我不知道你在說甚麼！」正說話之間，雞就叫了。","notes":[]},{"n":61,"t":"主轉過身來看彼得，彼得就想起主對他所說的話：「今日雞叫以前，你要三次不認我。」","notes":[]},{"n":62,"t":"他就出去痛哭。","notes":[]},{"n":63,"t":"看守耶穌的人戲弄他，打他，","notes":[],"heads":["戲弄鞭打耶穌"]},{"n":64,"t":"又蒙著他的眼，問他：「你說預言吧！打你的是誰？」","notes":[]},{"n":65,"t":"他們還用許多別的話辱罵他。","notes":[]},{"n":66,"t":"天一亮，民間的眾長老、祭司長和文士都聚集，把耶穌帶到他們的議會裏，","notes":[],"heads":["耶穌在議會受審"]},{"n":67,"t":"說：「如果你是基督，就告訴我們。」耶穌對他們說：「我若告訴你們，你們也不信；","notes":[]},{"n":68,"t":"我若問你們，你們也不回答。","notes":[]},{"n":69,"t":"從今以後，人子要坐在權能者神的右邊。」","notes":[]},{"n":70,"t":"他們都說：「那麼，你是神的兒子了？」耶穌對他們說：「你們說我是。」","notes":[]},{"n":71,"t":"他們說：「我們何必再要見證呢？他親口所說的，我們都親耳聽見了。」","notes":[]}]},"23":{"heading":"耶穌在彼拉多面前受審","verses":[{"n":1,"t":"眾人都起來，把耶穌解到彼拉多面前。","notes":[]},{"n":2,"t":"他們開始控告他說：「我們見這人煽惑我們的國民，禁止我們納稅給凱撒，並說自己是基督，是王。」","notes":[]},{"n":3,"t":"彼拉多問耶穌：「你是猶太人的王嗎？」耶穌回答：「是你說的。」","notes":[]},{"n":4,"t":"彼拉多對祭司長們和眾人說：「我查不出這人有甚麼罪來。」","notes":[]},{"n":5,"t":"但他們越發竭力地說：「他煽動百姓，在猶太全地傳道，從加利利起，直到這裏了。」","notes":[]},{"n":6,"t":"彼拉多一聽見，就問：「這人是加利利人嗎？」","notes":[],"heads":["耶穌在希律面前受審"]},{"n":7,"t":"既知道耶穌屬希律所管，彼拉多就把他送到希律那裏去。那時希律正在耶路撒冷。","notes":[]},{"n":8,"t":"希律看見耶穌就非常高興；因為聽見過他的事，早就想要見他，並且指望看他行些神蹟，","notes":[]},{"n":9,"t":"於是問他許多的話，耶穌卻一言不答。","notes":[]},{"n":10,"t":"那些祭司長和文士都站著，竭力控告他。","notes":[]},{"n":11,"t":"希律和他的士兵就藐視耶穌，戲弄他，給他穿上華麗的衣服，把他送回彼拉多那裏去。","notes":[]},{"n":12,"t":"從前希律和彼拉多彼此有仇，在那一天竟成了朋友。","notes":[]},{"n":13,"t":"彼拉多傳齊了眾祭司長、官長和百姓，","notes":[],"heads":["耶穌被判死刑"]},{"n":14,"t":"對他們說：「你們解這人到我這裏，說他是煽惑百姓的。看哪，我也曾在你們面前審問他，並沒有查出這人犯過你們控告他的任何罪；","notes":[]},{"n":15,"t":"就是希律也是如此，所以把他送回來。可見他沒有做甚麼該死的事。","notes":[]},{"n":16,"t":"所以，我要責打他，把他釋放。」","notes":["有古卷加「17 每逢這節期，總督必須釋放一個囚犯給他們。」"]},{"n":18,"t":"眾人卻一齊喊著說：「除掉這個人！釋放巴拉巴給我們！」","notes":[]},{"n":19,"t":"這巴拉巴是因在城裏作亂和殺人而下在監裏的。","notes":[]},{"n":20,"t":"彼拉多願意釋放耶穌，就再次向他們講話。","notes":[]},{"n":21,"t":"無奈他們喊著說：「把他釘十字架！把他釘十字架！」","notes":[]},{"n":22,"t":"彼拉多第三次對他們說：「為甚麼呢？這人做了甚麼惡事呢？我並沒有查出他有甚麼該死的罪來。所以，我要責打他，把他釋放。」","notes":[]},{"n":23,"t":"他們大聲催逼彼拉多，要求他把耶穌釘十字架；他們的聲音終於得勝。","notes":[]},{"n":24,"t":"彼拉多這才照他們的要求定案；","notes":[]},{"n":25,"t":"又把他們所要求的那因作亂和殺人而下在監裏的人釋放了，而把耶穌交給他們，隨他們的意思處置。","notes":[]},{"n":26,"t":"他們把耶穌帶去的時候，有一個古利奈人西門從鄉下來，他們就拿住他，把十字架擱在他身上，叫他背著跟在耶穌後面。","notes":[],"heads":["耶穌被釘十字架"]},{"n":27,"t":"有許多百姓跟隨耶穌，其中有好些婦女為他號咷痛哭。","notes":[]},{"n":28,"t":"耶穌轉身對她們說：「耶路撒冷的女子，不要為我哭，要為你們自己和你們的兒女哭。","notes":[]},{"n":29,"t":"因為日子將到，人要說：『不生育的、未曾懷孕的，和未曾哺乳孩子的有福了！』","notes":[]},{"n":30,"t":"那時，人要向大山說：『倒在我們身上！』向小山說：『遮蓋我們！』","notes":[]},{"n":31,"t":"他們若在樹木青綠的時候做這些事，那麼在枯乾的時候將會怎麼樣呢？」","notes":[]},{"n":32,"t":"另外有兩個犯人也被帶來和耶穌一同處死。","notes":[]},{"n":33,"t":"到了一個地方，名叫髑髏地，他們就在那裏把耶穌釘在十字架上，又釘了兩個犯人：一個在右邊，一個在左邊。","notes":[]},{"n":34,"t":"〔 這時，耶穌說：「父啊！赦免他們，因為他們所做的，他們不知道。」〕士兵就抽籤分他的衣服。","notes":["有古卷沒有括號裏的文字。"]},{"n":35,"t":"百姓站在那裏觀看。官長也嘲笑他，說：「他救了別人，他若是基督，是神所揀選的，救救他自己吧！」","notes":[]},{"n":36,"t":"士兵也戲弄他，上前拿醋送給他喝，","notes":[]},{"n":37,"t":"說：「你若是猶太人的王，救救你自己吧！」","notes":[]},{"n":38,"t":"在耶穌上方有一個牌子寫著：「這是猶太人的王。」","notes":[]},{"n":39,"t":"同釘的犯人中有一個譏笑他，說：「你不是基督嗎？救救你自己和我們吧！」","notes":[]},{"n":40,"t":"另一個就應聲責備他，說：「你是一樣受刑的，還不怕神嗎？","notes":[]},{"n":41,"t":"我們是應得的，因為我們是自作自受，但這個人沒有做過一件不對的事。」","notes":[]},{"n":42,"t":"他對耶穌說：「耶穌啊，你進入你國的時候，求你記念我。」","notes":[]},{"n":43,"t":"耶穌對他說：「我實在告訴你，今日你要同我在樂園裏了。」","notes":["「我實在…樂園裏了。」或譯「我今日實在告訴你，你將要同我在樂園裏。」"]},{"n":44,"t":"那時大約是正午，全地都黑暗了，直到下午三點鐘，","notes":[],"heads":["耶穌之死"]},{"n":45,"t":"太陽變黑了，殿的幔子從當中裂為兩半。","notes":[]},{"n":46,"t":"耶穌大聲喊著說：「父啊，我將我的靈交在你手裏！」他說了這話，氣就斷了。","notes":[]},{"n":47,"t":"百夫長看見所發生的事，就歸榮耀給神，說：「這人真是個義人！」","notes":[]},{"n":48,"t":"聚集觀看這事的眾人，見了所發生的事，都捶著胸回去了。","notes":[]},{"n":49,"t":"所有與耶穌熟悉的人，和從加利利跟著他來的婦女們，都遠遠地站著，看這些事。","notes":[]},{"n":50,"t":"有一個人名叫約瑟，是個議員，為人善良正直，","notes":[],"heads":["耶穌的安葬"]},{"n":51,"t":"卻沒有附從別人的所謀所為。他是猶太的亞利馬太城人，素常盼望著神的國。","notes":[]},{"n":52,"t":"這人去見彼拉多，請求要耶穌的身體。","notes":[]},{"n":53,"t":"他把耶穌的身體取下來，用細麻布裹好，安放在鑿巖而成的墳墓裏；那墳墓從來沒有葬過人。","notes":[]},{"n":54,"t":"那日是預備日，安息日快到了。","notes":[]},{"n":55,"t":"那些從加利利和耶穌同來的婦女跟在後面，看見了墳墓和他的身體怎樣安放。","notes":[]},{"n":56,"t":"她們就回去，預備了香料香膏。在安息日，她們遵照誡命安息了。","notes":[]}]},"24":{"heading":"耶穌復活","verses":[{"n":1,"t":"七日的第一日，黎明的時候，那些婦女帶著所預備的香料來到墳墓那裏，","notes":[]},{"n":2,"t":"發現石頭已經從墳墓滾開了，","notes":[]},{"n":3,"t":"她們就進去，只是不見主耶穌的身體。","notes":[]},{"n":4,"t":"正在為這事困惑的時候，忽然有兩個人站在旁邊，衣服放光。","notes":[]},{"n":5,"t":"婦女們非常害怕，就俯伏在地上。那兩個人對她們說：「為甚麼在死人中找活人呢？","notes":[]},{"n":6,"t":"他不在這裏，已經復活了。要記得他還在加利利的時候怎樣告訴你們的，","notes":[]},{"n":7,"t":"他說：『人子必須被交在罪人手裏，釘在十字架上，第三天復活。』」","notes":[]},{"n":8,"t":"她們就想起耶穌的話來。","notes":[]},{"n":9,"t":"於是她們從墳墓那裏回去，把這一切事告訴十一個使徒和其餘的人。","notes":[]},{"n":10,"t":"把這些事告訴使徒的有抹大拉的馬利亞、約亞拿，和雅各的母親馬利亞，還有跟她們在一起的婦女。","notes":[]},{"n":11,"t":"她們這些話，使徒以為是胡言，就不相信。","notes":[]},{"n":12,"t":"彼得起來，跑到墳墓前，俯身往裏看，只見細麻布，就回去了，因所發生的事而心裏驚訝。","notes":[]},{"n":13,"t":"同一天，門徒中有兩個人往一個村子去；這村子名叫以馬忤斯，離耶路撒冷約有二十五里。","notes":["「二十五里」：即十一公里，原文是「六十斯他迪」，古希臘長度單位；參「度量衡表」。"],"heads":["在去以馬忤斯的路上"]},{"n":14,"t":"他們彼此談論所發生的這一切事。","notes":[]},{"n":15,"t":"正交談議論的時候，耶穌親自走近他們，和他們同行，","notes":[]},{"n":16,"t":"可是他們的眼睛模糊了，沒認出他。","notes":[]},{"n":17,"t":"耶穌對他們說：「你們一邊走一邊談，彼此談論的是甚麼事呢？」他們就站住，臉上帶著愁容。","notes":[]},{"n":18,"t":"兩人中有一個名叫革流巴的回答：「你是在耶路撒冷的旅客中，惟一還不知道這幾天在那裏發生了甚麼事的人嗎？」","notes":[]},{"n":19,"t":"耶穌對他們說：「甚麼事呢？」他們對他說：「就是拿撒勒人耶穌的事。他是個先知，在神和眾百姓面前，說話行事都大有能力。","notes":[]},{"n":20,"t":"祭司長們和我們的官長竟把他解去，定了死罪，釘在十字架上。","notes":[]},{"n":21,"t":"但我們素來所盼望要救贖以色列民的就是他。不但如此，這些事發生到現在已經三天了。","notes":[]},{"n":22,"t":"還有，我們中間的幾個婦女使我們驚奇：她們清早去了墳墓，","notes":[]},{"n":23,"t":"不見他的身體，就回來告訴我們，說她們看見了天使顯現，說他活了。","notes":[]},{"n":24,"t":"又有我們的幾個人往墳墓那裏去，所發現的正如婦女們所說的，只是沒有看見他。」","notes":[]},{"n":25,"t":"耶穌對他們說：「無知的人哪，先知所說的一切話，你們的心信得太遲鈍了。","notes":[]},{"n":26,"t":"基督不是必須受這些苦難，然後進入他的榮耀嗎？」","notes":[]},{"n":27,"t":"於是，他從摩西和眾先知起，凡經上所指著自己的話都給他們作了解釋。","notes":[]},{"n":28,"t":"他們走近所要去的村子，耶穌好像還要往前走，","notes":[]},{"n":29,"t":"他們卻強留他說：「時候晚了，天快黑了，請你同我們住下吧。」耶穌就進去，要同他們住下。","notes":[]},{"n":30,"t":"坐下來和他們用餐的時候，耶穌拿起餅來，祝福了，擘開，遞給他們。","notes":[]},{"n":31,"t":"他們的眼睛開了，這才認出他來。耶穌卻從他們眼前消失了。","notes":[]},{"n":32,"t":"他們彼此說：「在路上他和我們說話，給我們講解聖經的時候，我們的心在我們裏面豈不是火熱的嗎？」","notes":["有古卷沒有「在我們裏面」。"]},{"n":33,"t":"於是他們立刻起身，回耶路撒冷去，看見十一個使徒和與他們正在一起的人聚集在一處，","notes":[]},{"n":34,"t":"說：「主果然復活了，已經顯現給西門看了。」","notes":[]},{"n":35,"t":"於是，兩個人把路上所遇到，和耶穌擘餅的時候怎麼被他們認出來的事，都述說了一遍。","notes":[]},{"n":36,"t":"正說這些話的時候，耶穌親自站在他們當中，說：「願你們平安！」","notes":[],"heads":["向門徒顯現"]},{"n":37,"t":"他們卻驚慌害怕，以為所看見的是魂。","notes":[]},{"n":38,"t":"耶穌對他們說：「你們為甚麼驚恐不安？為甚麼心裏起疑惑呢？","notes":[]},{"n":39,"t":"你們看我的手和我的腳，就知道實在是我了。摸摸我，看，因為魂無骨無肉，你們看，我是有的。」","notes":[]},{"n":40,"t":"說了這話，他就把手和腳給他們看。","notes":[]},{"n":41,"t":"他們還在又驚又喜、不敢相信的時候，耶穌對他們說：「你們這裏有甚麼吃的沒有？」","notes":[]},{"n":42,"t":"他們給了他一片烤魚，","notes":[]},{"n":43,"t":"他接過來，在他們面前吃了。","notes":[]},{"n":44,"t":"耶穌對他們說：「這就是我從前和你們同在時所告訴你們的話：摩西的律法、先知的書，和《詩篇》上所記一切指著我的話都必須應驗。」","notes":[]},{"n":45,"t":"於是耶穌開他們的心竅，使他們能明白聖經，","notes":[]},{"n":46,"t":"又對他們說：「照經上所寫的，基督必受害，第三天從死人中復活，","notes":[]},{"n":47,"t":"並且人們要奉他的名傳悔改、使罪得赦的道，從耶路撒冷起直傳到萬邦。","notes":[]},{"n":48,"t":"你們就是這些事的見證。","notes":[]},{"n":49,"t":"我要將我父所應許的降在你們身上，你們要在城裏等候，直到你們領受從上面來的能力。」","notes":[]},{"n":50,"t":"耶穌領他們出來，直到伯大尼附近，就舉手給他們祝福。","notes":[],"heads":["耶穌升天"]},{"n":51,"t":"正祝福的時候，他離開他們，被帶到天上去了。","notes":[]},{"n":52,"t":"他們就拜他，帶著極大的喜樂回耶路撒冷去，","notes":[]},{"n":53,"t":"常在聖殿裏稱頌神。","notes":[]}]}},"JHN":{"1":{"heading":"道成了肉身","verses":[{"n":1,"t":"太初有道，道與神同在，道就是神。","notes":[]},{"n":2,"t":"這道太初與神同在。","notes":[]},{"n":3,"t":"萬物都是藉著他造的，沒有一樣不是藉著他造的。凡被造的，","notes":[]},{"n":4,"t":"在他裏面有生命，這生命就是人的光。","notes":["「沒有一樣…有生命」：有古卷是「凡被造的，沒有一樣不是藉著他造的。在他裏面有生命」。"]},{"n":5,"t":"光照在黑暗裏，黑暗卻沒有勝過光。","notes":["「黑暗卻沒有勝過光」或譯「黑暗卻不接受光」。"]},{"n":6,"t":"有一個人，是從神那裏差來的，名叫約翰。","notes":[]},{"n":7,"t":"這人來是為了作見證，是為那光作見證，要使眾人藉著他而信。","notes":[]},{"n":8,"t":"他不是那光，而是要為那光作見證。","notes":[]},{"n":9,"t":"那光是真光，來到世上，照亮所有的人。","notes":["本節或譯「他是那來到世界照亮所有的人的真光」。"]},{"n":10,"t":"他在世界，世界是藉著他造的，世界卻不認識他。","notes":[]},{"n":11,"t":"他來到自己的地方，自己的人並不接納他。","notes":[]},{"n":12,"t":"凡接納他的，就是信他名的人，他就賜他們權柄作神的兒女。","notes":[]},{"n":13,"t":"這些人不是從血生的，不是從情慾生的，也不是從人的意願生的，而是從神生的。","notes":[]},{"n":14,"t":"道成了肉身，住在我們中間，充充滿滿地有恩典有真理，我們也見過他的榮光，正是父獨一兒子的榮光。","notes":["「獨一兒子」或譯「獨生子」； 18節同。"]},{"n":15,"t":"約翰為他作見證，喊著說：「這就是我曾說：『那在我以後來的先於我，因為在我以前，他已經存在。』」","notes":[]},{"n":16,"t":"從他的豐富裏，我們都領受了恩典，而且恩上加恩。","notes":[]},{"n":17,"t":"律法是藉著摩西頒佈的；恩典和真理卻是由耶穌基督來的。","notes":[]},{"n":18,"t":"從來沒有人見過神，只有在父懷裏獨一的兒子將他表明出來。","notes":[]},{"n":19,"t":"這是約翰的見證：猶太人從耶路撒冷差祭司和利未人到約翰那裏去問他：「你是誰？」","notes":[],"heads":["施洗約翰的見證"]},{"n":20,"t":"他就承認，並不隱瞞，承認說：「我不是基督。」","notes":[]},{"n":21,"t":"他們又問他：「那麼，你是誰？是以利亞嗎？」他說：「我不是。」「是那位先知嗎？」他回答：「不是。」","notes":[]},{"n":22,"t":"於是他們對他說：「你到底是誰，好讓我們回覆差我們來的人。你說，你自己是誰？」","notes":[]},{"n":23,"t":"他說：「我就是那在曠野呼喊的聲音：修直主的道。」正如以賽亞先知所說的。","notes":[]},{"n":24,"t":"那些人是法利賽人差來的。","notes":[]},{"n":25,"t":"他們就問他：「你既不是基督，不是以利亞，也不是那位先知，那麼，你為甚麼施洗呢？」","notes":[]},{"n":26,"t":"約翰回答：「我是用水施洗，但有一位站在你們中間，是你們不認識的，","notes":[]},{"n":27,"t":"就是那在我以後來的，我給他解鞋帶也不配。」","notes":[]},{"n":28,"t":"這些事發生在約旦河東邊的伯大尼，約翰施洗的地方。","notes":["有古卷是「伯大巴喇」。"]},{"n":29,"t":"第二天，約翰看見耶穌來到他那裏，就說：「看哪，神的羔羊，除去世人的罪的！","notes":[],"heads":["神的羔羊"]},{"n":30,"t":"這就是我曾說『那在我以後來的先於我，因為在我以前，他已經存在』的那一位。","notes":[]},{"n":31,"t":"我先前不認識他，如今我來用水施洗，為要使他顯明給以色列人。」","notes":[]},{"n":32,"t":"約翰又作見證說：「我曾看見聖靈彷彿鴿子從天降下，停留在他的身上。","notes":[]},{"n":33,"t":"我先前不認識他，可是那差我來用水施洗的對我說：『你看見聖靈降下來，停留在誰的身上，誰就是用聖靈施洗的。』","notes":[]},{"n":34,"t":"我看見了，所以作證：這一位是神的兒子。」","notes":[]},{"n":35,"t":"又過了一天，約翰同兩個門徒站在那裏。","notes":[],"heads":["初次選召門徒"]},{"n":36,"t":"他見耶穌走過，就說：「看哪，神的羔羊！」","notes":[]},{"n":37,"t":"兩個門徒聽見他的話，就跟從了耶穌。","notes":[]},{"n":38,"t":"耶穌轉過身來，看見他們跟著，就問他們說：「你們要甚麼？」他們對他說：「拉比，你在哪裏住？」（「拉比」翻出來就是老師。）","notes":[]},{"n":39,"t":"耶穌說：「你們來看。」他們就去看他在哪裏住。這一天他們就跟他同住；那時大約是下午四點鐘。","notes":[]},{"n":40,"t":"聽了約翰的話而跟從耶穌的那兩個人，其中一個是西門‧彼得的弟弟安得烈。","notes":[]},{"n":41,"t":"他先找到自己的哥哥西門，對他說：「我們遇見彌賽亞了。」（「彌賽亞」翻出來就是基督。）","notes":[]},{"n":42,"t":"於是安得烈領西門去見耶穌。耶穌看著他，說：「你是約翰的兒子西門，你要稱為磯法。」（「磯法」翻出來就是彼得。）","notes":["有古卷是「約拿」。","「磯法」是亞蘭語，與希臘語的「彼得」同義，意思是「磐石」。"]},{"n":43,"t":"又過了一天，耶穌想要往加利利去。他找到腓力，就對他說：「來跟從我！」","notes":[],"heads":["呼召腓力和拿但業"]},{"n":44,"t":"這腓力是伯賽大人，是安得烈和彼得的同鄉。","notes":[]},{"n":45,"t":"腓力找到拿但業，對他說：「摩西在律法書上所寫的，和眾先知所記的那一位，我們遇見了，就是約瑟的兒子拿撒勒人耶穌。」","notes":[]},{"n":46,"t":"拿但業對他說：「拿撒勒還能出甚麼好的嗎？」腓力說：「你來看。」","notes":[]},{"n":47,"t":"耶穌看見拿但業向他走來，就論到他說：「看哪，這真是個以色列人！他心裏是沒有詭詐的。」","notes":[]},{"n":48,"t":"拿但業對耶穌說：「你從哪裏認識我的？」耶穌回答他說：「腓力還沒有呼喚你，你在無花果樹底下，我就看見你了。」","notes":[]},{"n":49,"t":"拿但業回答他：「拉比！你是神的兒子，你是以色列的王。」","notes":[]},{"n":50,"t":"耶穌回答他說：「因為我說在無花果樹底下看見你，你就信嗎？你將看見比這些更大的事呢！」","notes":[]},{"n":51,"t":"他又說：「我實實在在地告訴你們，你們將要看見天開了，神的使者在人子身上，上去下來。」","notes":[]}]},"2":{"heading":"迦拿的婚禮","verses":[{"n":1,"t":"第三日，在加利利的迦拿有一個婚宴，耶穌的母親在那裏。","notes":[]},{"n":2,"t":"耶穌和他的門徒也被請去赴宴。","notes":[]},{"n":3,"t":"酒用完了，耶穌的母親對他說：「他們沒有酒了。」","notes":[]},{"n":4,"t":"耶穌說：「母親，我與你何干呢？我的時候還沒有到。」","notes":["原文直譯「婦人」，在猶太文化中不是一種不尊敬的稱呼。"]},{"n":5,"t":"他母親對用人說：「他告訴你們甚麼，你們就做吧。」","notes":[]},{"n":6,"t":"照猶太人潔淨禮的規矩，有六口石缸擺在那裏，每口可以盛兩三桶水。","notes":["「桶」：參「度量衡表」。"]},{"n":7,"t":"耶穌對用人說：「把缸倒滿水。」他們就倒滿了，直到缸口。","notes":[]},{"n":8,"t":"耶穌又說：「現在舀出來，送給宴會總管。」他們就送了去。","notes":[]},{"n":9,"t":"宴會總管嘗了那水變的酒，並不知道是哪裏來的，只有舀水的用人知道。於是宴會總管叫新郎來，","notes":[]},{"n":10,"t":"對他說：「人家都是先擺上好酒，等客人喝夠了才擺上次的，你倒把好酒留到現在！」","notes":[]},{"n":11,"t":"這是耶穌所行的第一個神蹟，是在加利利的迦拿行的，顯出了他的榮耀來，他的門徒就信他了。","notes":[]},{"n":12,"t":"這事以後，耶穌與他的母親、兄弟和門徒都下迦百農去，在那裏住了不多幾天。","notes":["有古卷沒有「兄弟」。","有古卷沒有「門徒」。"]},{"n":13,"t":"猶太人的逾越節近了，耶穌上耶路撒冷去。","notes":[],"heads":["潔淨聖殿"]},{"n":14,"t":"他看見聖殿裏有賣牛羊和鴿子的，還有兌換銀錢的人坐著，","notes":[]},{"n":15,"t":"耶穌就拿繩子做成鞭子，把所有的，包括牛羊都趕出聖殿，倒出兌換銀錢之人的銀錢，推翻他們的桌子，","notes":[]},{"n":16,"t":"又對賣鴿子的說：「把這些東西拿走！不要把我父的殿當作買賣的地方。」","notes":[]},{"n":17,"t":"他的門徒就想起經上記著：「我為你的殿心裏焦急，如同火燒。」","notes":[]},{"n":18,"t":"因此猶太人問他：「你能顯甚麼神蹟給我們看，表明你可以做這些事呢？」","notes":[]},{"n":19,"t":"耶穌回答他們說：「你們拆毀這殿，我三日內要把它重建。」","notes":[]},{"n":20,"t":"猶太人說：「這殿造了四十六年，你三日內就能重建嗎？」","notes":[]},{"n":21,"t":"但耶穌所說的殿是指他的身體。","notes":[]},{"n":22,"t":"所以他從死人中復活以後，門徒想起他曾說過這事，就信了聖經和耶穌所說的話。","notes":[]},{"n":23,"t":"耶穌在耶路撒冷過逾越節的時候，有許多人看見他所行的神蹟，就信了他的名。","notes":[],"heads":["耶穌洞察人心"]},{"n":24,"t":"耶穌自己卻不信任他們，因為他認識所有的人，","notes":[]},{"n":25,"t":"也用不著誰來證明人是怎樣的，因為他自己認識人的內心。","notes":[]}]},"3":{"heading":"耶穌和尼哥德慕談重生","verses":[{"n":1,"t":"有一個法利賽人，名叫尼哥德慕，是猶太人的官。","notes":[]},{"n":2,"t":"這人夜裏來見耶穌，對他說：「拉比，我們知道你是由神那裏來作老師的；因為你所行的神蹟，若沒有神同在，無人能行。」","notes":[]},{"n":3,"t":"耶穌回答他說：「我實實在在地告訴你，人若不重生，就不能見神的國。」","notes":["「重生」或譯「從上面而生」。"]},{"n":4,"t":"尼哥德慕對他說：「人已經老了，如何能重生呢？豈能再進母腹生出來嗎？」","notes":[]},{"n":5,"t":"耶穌回答：「我實實在在地告訴你，人若不是從水和聖靈生的，就不能進神的國。","notes":[]},{"n":6,"t":"從肉身生的就是肉身；從靈生的就是靈。","notes":[]},{"n":7,"t":"我說『你們必須重生』，你不要驚訝。","notes":[]},{"n":8,"t":"風隨著意思吹，你聽見風的聲音，卻不知道是從哪裏來，往哪裏去；凡從聖靈生的也是如此。」","notes":["原文的「風」與「靈」同字。"]},{"n":9,"t":"尼哥德慕問他：「怎麼能有這些事呢？」","notes":[]},{"n":10,"t":"耶穌回答，對他說：「你是以色列人的老師，還不明白這些事嗎？","notes":[]},{"n":11,"t":"我實實在在地告訴你，我們所說的是我們知道的，我們所見證的是我們見過的，你們卻不領受我們的見證。","notes":[]},{"n":12,"t":"我對你們說地上的事，你們尚且不信，若對你們說天上的事，如何能信呢？","notes":[]},{"n":13,"t":"除了從天降下的人子，沒有人升過天。","notes":["有古卷加「仍舊在天」。"]},{"n":14,"t":"摩西在曠野怎樣舉蛇，人子也必須照樣被舉起來，","notes":[]},{"n":15,"t":"要使一切信他的人都得永生。","notes":[]},{"n":16,"t":"「神愛世人，甚至將他獨一的兒子賜給他們，叫一切信他的人不致滅亡，反得永生。","notes":["「他獨一的兒子」或譯「他的獨生子」；18節同。"]},{"n":17,"t":"因為神差他的兒子到世上來，不是要定世人的罪，而是要使世人因他得救。","notes":["「定世人的罪」或譯「審判世人」；18、19節同。"]},{"n":18,"t":"信他的人不被定罪；不信的人已經被定罪了，因為他不信神獨一兒子的名。","notes":[]},{"n":19,"t":"光來到世上，世人因自己的行為是惡的，不愛光，倒愛黑暗，這就定了他們的罪。","notes":[]},{"n":20,"t":"凡作惡的人都恨惡光，不來接近光，恐怕他的行為被暴露。","notes":[]},{"n":21,"t":"但實行真理的人就來接近光，為要顯明他的行為是靠神而行的。」","notes":[]},{"n":22,"t":"這些事以後，耶穌和門徒到了猶太地區，在那裏他和他們同住，並且施洗。","notes":[],"heads":["耶穌和施洗約翰"]},{"n":23,"t":"約翰也在靠近撒冷的哀嫩施洗，因為那裏水多，眾人都去受洗。","notes":[]},{"n":24,"t":"那時約翰還沒有下在監裏。","notes":[]},{"n":25,"t":"約翰的門徒和一個猶太人辯論潔淨的禮儀，","notes":[]},{"n":26,"t":"就來見約翰，對他說：「拉比，從前同你在約旦河的東邊，你所見證的那位，你看，他在施洗，眾人都到他那裏去了。」","notes":[]},{"n":27,"t":"約翰回答說：「若不是從天上賜的，人就不能得到甚麼。","notes":[]},{"n":28,"t":"你們自己可以為我作見證，我曾說，我不是基督，只是奉差遣在他前面開路的。","notes":[]},{"n":29,"t":"娶新娘的是新郎；新郎的朋友站在一旁聽，一聽見新郎的聲音就歡喜快樂。因此，我這喜樂得以滿足了。","notes":[]},{"n":30,"t":"他必興旺；我必衰微。」","notes":[]},{"n":31,"t":"「從上頭來的是在萬有之上；出於地的是屬於地，他所說的也是屬於地。從天上來的是在萬有之上。","notes":[],"heads":["從天上來的那一位"]},{"n":32,"t":"他把所見所聞的見證出來，只是沒有人領受他的見證。","notes":[]},{"n":33,"t":"那領受他見證的，就印證神是真實的。","notes":[]},{"n":34,"t":"神所差來的說神的話，因為神所賜給他的聖靈是沒有限量的。","notes":[]},{"n":35,"t":"父愛子，已把萬有交在他手裏。","notes":[]},{"n":36,"t":"信子的人有永生；不信子的人得不到永生，而且神的憤怒常在他身上。」","notes":[]}]},"4":{"heading":"耶穌和撒瑪利亞婦人談道","verses":[{"n":1,"t":"耶穌知道法利賽人聽見他收門徒和施洗比約翰還多， （","notes":["有古卷是「主」。"]},{"n":2,"t":"其實不是耶穌親自施洗，而是他的門徒施洗，）","notes":[]},{"n":3,"t":"他就離開猶太，又回加利利去。","notes":[]},{"n":4,"t":"他必須經過撒瑪利亞，","notes":[]},{"n":5,"t":"於是到了撒瑪利亞的一座城，名叫敘加，靠近雅各給他兒子約瑟的那塊地。","notes":[]},{"n":6,"t":"雅各井就在那裏；耶穌因旅途疲乏，坐在井旁。那時約是正午。","notes":[]},{"n":7,"t":"有一個撒瑪利亞婦人來打水。耶穌對她說：「請給我水喝。」","notes":[]},{"n":8,"t":"因為那時門徒進城買食物去了。","notes":[]},{"n":9,"t":"撒瑪利亞婦人對他說：「你是猶太人，怎麼向我一個撒瑪利亞女人要水喝呢？」因為猶太人和撒瑪利亞人沒有來往。","notes":[]},{"n":10,"t":"耶穌回答她說：「你若知道神的恩賜，和對你說『請給我水喝』的是誰，你早就會求他，他也早就會給了你活水。」","notes":[]},{"n":11,"t":"婦人對耶穌說：「先生，你沒有打水的器具，井又深，哪裏去取活水呢？","notes":[]},{"n":12,"t":"我們的祖宗雅各把這井留給我們，他自己和兒女以及牲畜都喝這井裏的水，難道你比他還大嗎？」","notes":[]},{"n":13,"t":"耶穌回答，對她說：「凡喝這水的，還要再渴；","notes":[]},{"n":14,"t":"誰喝我所賜的水，就永遠不渴。我所賜的水要在他裏面成為泉源，直湧到永生。」","notes":[]},{"n":15,"t":"婦人對他說：「先生，請把這水賜給我，使我不渴，也不用到這裏來打水。」","notes":[]},{"n":16,"t":"耶穌對她說：「你去，叫你的丈夫，再到這裏來。」","notes":[]},{"n":17,"t":"婦人回答，對耶穌說：「我沒有丈夫。」耶穌說：「你說沒有丈夫是對的。","notes":[]},{"n":18,"t":"你已經有過五個丈夫，你現在有的並不是你的丈夫。你這話是真的。」","notes":[]},{"n":19,"t":"婦人對他說：「先生，我看你是一位先知。","notes":[]},{"n":20,"t":"我們的祖宗在這山上敬拜神，你們倒說，應當敬拜的地方是在耶路撒冷。」","notes":[]},{"n":21,"t":"耶穌對她說：「婦人，你要信我。時候將到，你們敬拜父，既不在這山上，也不在耶路撒冷。","notes":[]},{"n":22,"t":"你們所敬拜的，你們不知道；我們所敬拜的，我們知道，因為救恩是從猶太人出來的。","notes":[]},{"n":23,"t":"時候將到，現在就是了，那真正敬拜父的，要用心靈和誠實敬拜他，因為父要這樣的人敬拜他。","notes":[]},{"n":24,"t":"神是靈，所以敬拜他的必須用心靈和誠實敬拜他。」","notes":[]},{"n":25,"t":"婦人對他說：「我知道彌賽亞—就是那稱為基督的—要來；他來了，會把一切的事都告訴我們。」","notes":[]},{"n":26,"t":"耶穌對她說：「我就是，正在跟你說話呢！」","notes":[]},{"n":27,"t":"正在這時，門徒回來了。他們對耶穌正在和一個婦人說話感到驚訝，可是沒有人說：「你要甚麼？」或說：「你為甚麼和她說話？」","notes":[]},{"n":28,"t":"那婦人留下水罐，往城裏去，對眾人說：","notes":[]},{"n":29,"t":"「你們來看！有一個人把我素來所做的一切事都說了出來，難道這個人就是基督嗎？」","notes":[]},{"n":30,"t":"他們就出城，來到耶穌那裏。","notes":[]},{"n":31,"t":"就在這個時候，門徒求耶穌說：「拉比，請吃吧。」","notes":[]},{"n":32,"t":"耶穌對他們說：「我有食物吃，是你們不知道的。」","notes":[]},{"n":33,"t":"門徒就彼此說：「難道有人拿甚麼給他吃了嗎？」","notes":[]},{"n":34,"t":"耶穌對他們說：「我的食物就是要遵行差我來那位的旨意，完成他的工作。","notes":[]},{"n":35,"t":"你們不是說『到收割的時候還有四個月』嗎？我告訴你們，舉目向田觀看，莊稼熟了，可以收割了。","notes":[]},{"n":36,"t":"收割的人已經得工錢，為永生儲存五穀，使撒種的和收割的一同快樂。","notes":["「莊稼熟了…已經得工錢」：有古卷是「莊稼已經熟了…得工錢」。"]},{"n":37,"t":"『那人撒種，這人收割』，這話可見是真的。","notes":[]},{"n":38,"t":"我差你們去收你們所沒有辛勞的；別人辛勞，你們享受他們辛勞的成果。」","notes":[]},{"n":39,"t":"那城裏有好些撒瑪利亞人信了耶穌，因為那婦人作見證，說：「他把我素來所做的一切事都說了出來。」","notes":[]},{"n":40,"t":"於是撒瑪利亞人來見耶穌，求他在他們那裏住下，他就在那裏住了兩天。","notes":[]},{"n":41,"t":"因為耶穌的話，信的人就更多了。","notes":[]},{"n":42,"t":"他們對那婦人說：「現在我們信，不再是因為你的話，而是我們親自聽見了，知道這人真是世界的救主。」","notes":[]},{"n":43,"t":"過了那兩天，耶穌離開那地方，往加利利去。","notes":[],"heads":["耶穌治好大臣的兒子"]},{"n":44,"t":"因為耶穌自己作過見證說：「先知在自己的家鄉是沒有人尊敬的。」","notes":[]},{"n":45,"t":"到了加利利，加利利人都歡迎他，因為他們也上耶路撒冷去過節，曾經看過他在節期間所做的一切事。","notes":[]},{"n":46,"t":"耶穌又到了加利利的迦拿，就是他從前變水為酒的地方。有一個大臣，他的兒子在迦百農病了。","notes":[]},{"n":47,"t":"他聽見耶穌從猶太到了加利利，就來見他，求他下去醫治他的兒子，因為他兒子快要死了。","notes":[]},{"n":48,"t":"耶穌對他說：「若不看見神蹟奇事，你們總是不信。」","notes":[]},{"n":49,"t":"那大臣對他說：「先生，求你趁著我的孩子還沒有死就下去吧。」","notes":[]},{"n":50,"t":"耶穌對他說：「回去吧，你的兒子會活！」那人信耶穌所說的話，就回去了。","notes":[]},{"n":51,"t":"正下去的時候，他的僕人迎面而來，說他的兒子活了。","notes":[]},{"n":52,"t":"他就問甚麼時候見好的。他們對他說：「昨天下午一點鐘熱就退了。」","notes":[]},{"n":53,"t":"他就知道這正是耶穌對他說「你的兒子會活」的時候；他自己和全家就都信了。","notes":[]},{"n":54,"t":"這是耶穌從猶太回到加利利後所行的第二個神蹟。","notes":[]}]},"5":{"heading":"在畢士大池邊治病","verses":[{"n":1,"t":"這些事以後，到了猶太人的一個節期，耶穌上耶路撒冷去。","notes":[]},{"n":2,"t":"在耶路撒冷，靠近羊門有一個池子，希伯來話叫畢士大，旁邊有五個柱廊；","notes":["有古卷是「伯賽大」。"]},{"n":3,"t":"裏面躺著許多病人，有失明的、瘸腿的、癱瘓的。","notes":["有古卷加「等候水動，4 因為有天使按時下池子攪動那水，水動之後，先下水的人無論患甚麼病都能得痊癒。」"]},{"n":5,"t":"在那裏有一個人，病了三十八年。","notes":[]},{"n":6,"t":"耶穌看見他躺著，知道他病了很久，就問他：「你要痊癒嗎？」","notes":[]},{"n":7,"t":"病人回答他：「先生，水動的時候，沒有人把我放在池子裏；我正要去的時候，別人比我先下去了。」","notes":[]},{"n":8,"t":"耶穌對他說：「起來，拿起你的褥子走吧！」","notes":[]},{"n":9,"t":"那人立刻痊癒，就拿起自己的褥子走了。那天是安息日，","notes":[]},{"n":10,"t":"所以猶太人對那被治好了的人說：「今天是安息日，你拿褥子是不合法的。」","notes":[]},{"n":11,"t":"他卻回答他們：「那使我痊癒的人對我說：『拿起你的褥子走吧！』」","notes":[]},{"n":12,"t":"他們問他：「對你說『拿起褥子走』的是甚麼人？」","notes":[]},{"n":13,"t":"那治好了的人不知道那人是誰，因為那裏人很多，耶穌已經躲開了。","notes":[]},{"n":14,"t":"後來耶穌在聖殿裏找到他，對他說：「你已經痊癒了，不要再犯罪，免得你的遭遇更壞。」","notes":[]},{"n":15,"t":"那人就去告訴猶太人，使他痊癒的是耶穌。","notes":[]},{"n":16,"t":"所以猶太人迫害耶穌，因為他在安息日做了這些事。","notes":[]},{"n":17,"t":"耶穌就回答他們：「我父做事直到如今，我也做事。」","notes":[]},{"n":18,"t":"為了這緣故，猶太人越發想要殺他，因為他不但犯了安息日，而且稱神為他的父，把自己和神看為同等。","notes":[]},{"n":19,"t":"於是耶穌回答，對他們說：「我實實在在地告訴你們，子憑著自己不能做甚麼，惟有看見父所做的，他才做；父所做的事，子也照樣做。","notes":[],"heads":["聖子的權柄"]},{"n":20,"t":"父愛子，將自己所做的一切事指示給他看，還要將比這更大的事給他看，使你們驚訝。","notes":[]},{"n":21,"t":"父怎樣叫死人復活，賜他們生命，子也照樣隨自己的意願賜人生命。","notes":[]},{"n":22,"t":"父不審判任何人，而是把審判的事全交給子，","notes":[]},{"n":23,"t":"為要使人都尊敬子，如同尊敬父一樣。不尊敬子的，就是不尊敬差子來的父。","notes":[]},{"n":24,"t":"「我實實在在地告訴你們，那聽我話又信差我來那位的，就有永生，不至於被定罪，而是已經出死入生了。","notes":[]},{"n":25,"t":"我實實在在地告訴你們，時候將到，現在就是了，死人要聽見神兒子的聲音，聽見的人就要活了。","notes":[]},{"n":26,"t":"因為父怎樣自己裏面有生命，也照樣賜給他兒子自己裏面有生命，","notes":[]},{"n":27,"t":"並且賜給他施行審判的權柄，因為他是人子。","notes":[]},{"n":28,"t":"你們不要對這事感到驚訝，因為時候將到，凡在墳墓裏的，都要聽見他的聲音，","notes":[]},{"n":29,"t":"並且要出來：行善的，復活得生命；作惡的，復活被定罪。","notes":[]},{"n":30,"t":"「我憑著自己不能做甚麼。我怎麼聽見就怎麼審判，而我的審判是公平的，因為我不尋求自己的意願，只尋求差我來那位的旨意。」","notes":[]},{"n":31,"t":"「我若為自己作見證，我的見證就不真。","notes":[],"heads":["為耶穌作見證"]},{"n":32,"t":"另有一位為我作見證，我也知道他為我作的見證是真的。","notes":[]},{"n":33,"t":"你們曾差人到約翰那裏，他為真理作過見證。","notes":[]},{"n":34,"t":"其實，我所受的見證不是從人來的；然而，我說這些話是為了使你們得救。","notes":[]},{"n":35,"t":"約翰是點亮的明燈，你們情願因他的光歡欣一時。","notes":[]},{"n":36,"t":"但我有比約翰更大的見證：父交給我去完成的工作，就是我正在做的，為我作證是父差遣了我。","notes":[]},{"n":37,"t":"那差我來的父也為我作了見證。你們從來沒有聽見他的聲音，也沒有看見他的形像。","notes":[]},{"n":38,"t":"你們並沒有他的道存在心裏，因為你們不信他所差來的那一位。","notes":[]},{"n":39,"t":"你們查考聖經，因你們以為其中有永生；而這經正是為我作見證的。","notes":[]},{"n":40,"t":"然而，你們不肯到我這裏來得生命。","notes":[]},{"n":41,"t":"「我不接受從人來的榮耀，","notes":[]},{"n":42,"t":"但我知道，你們沒有愛神的心。","notes":[]},{"n":43,"t":"我奉我父的名來了，你們並不接納我；若有別人奉自己的名來，你們倒會接納他。","notes":[]},{"n":44,"t":"你們互相受榮耀，卻不尋求從獨一神來的榮耀，怎能信我呢？","notes":[]},{"n":45,"t":"不要以為我會在父面前告你們；有一位告你們的，就是你們所仰望的摩西。","notes":[]},{"n":46,"t":"如果你們信摩西，也會信我，因為他寫過關於我的事。","notes":[]},{"n":47,"t":"你們若不信他的書，怎能信我的話呢？」","notes":[]}]},"6":{"heading":"耶穌使五千人吃飽","verses":[{"n":1,"t":"這些事以後，耶穌渡過加利利海，就是提比哩亞海。","notes":[]},{"n":2,"t":"有一大群人因為看見他在病人身上所行的神蹟，就跟隨他。","notes":[]},{"n":3,"t":"耶穌上了山，和門徒一同坐在那裏。","notes":[]},{"n":4,"t":"那時猶太人的逾越節近了。","notes":[]},{"n":5,"t":"耶穌舉目看見一大群人來，就對腓力說：「我們到哪裏去買餅給這些人吃呢？」","notes":[]},{"n":6,"t":"他說這話是要考驗腓力，他自己原知道要怎樣做。","notes":[]},{"n":7,"t":"腓力回答他：「就是兩百個銀幣的餅也不夠給他們每人吃一點點。」","notes":[]},{"n":8,"t":"有一個門徒，就是西門‧彼得的弟弟安得烈，對耶穌說：","notes":[]},{"n":9,"t":"「這裏有一個孩子，帶著五個大麥餅和兩條魚，但是分給這麼多人還算甚麼呢？」","notes":[]},{"n":10,"t":"耶穌說：「你們叫大家坐下。」那地方的草多，人們就坐下，男人的數目約有五千。","notes":[]},{"n":11,"t":"耶穌拿起餅來，祝謝了，就分給坐著的人，也同樣分了魚，都照他們所要的來分。","notes":[]},{"n":12,"t":"他們吃飽後，耶穌對門徒說：「把剩下的碎屑收拾起來，免得糟蹋了。」","notes":[]},{"n":13,"t":"他們就把那五個大麥餅的碎屑，就是大家吃剩的，收拾起來，裝滿了十二個籃子。","notes":[]},{"n":14,"t":"人們看見耶穌所行的神蹟，就說：「這真是那要到世上來的先知！」","notes":[]},{"n":15,"t":"耶穌知道他們要來強迫他作王，就獨自又退到山上去了。","notes":[]},{"n":16,"t":"到了晚上，他的門徒下到海邊，","notes":[],"heads":["耶穌在海上行走"]},{"n":17,"t":"上了船，要過海往迦百農去。天已經黑了，耶穌還沒有來到他們那裏。","notes":[]},{"n":18,"t":"忽然狂風大作，海浪翻騰。","notes":[]},{"n":19,"t":"門徒搖櫓，約行了十里多，看見耶穌在海面上走，漸漸靠近了船，他們就害怕。","notes":["「十里多」﹕即五、六公里，原文即「二十五或三十斯他迪」，古希臘長度單位；參「度量衡表」。"]},{"n":20,"t":"耶穌對他們說：「是我，不要怕！」","notes":[]},{"n":21,"t":"門徒就欣然接他上船，船立刻到了他們所要去的地方。","notes":[]},{"n":22,"t":"第二天，留在海的對岸的眾人發覺那裏原來只有一條小船，而且耶穌沒有同他的門徒上船，是門徒自己去的。","notes":[],"heads":["耶穌是生命的糧"]},{"n":23,"t":"另外有幾條從提比哩亞來的小船，卻停靠在主祝謝後給他們吃餅的地方附近。","notes":[]},{"n":24,"t":"這時眾人見耶穌和門徒都不在那裏，就上了船，往迦百農去找耶穌。","notes":[]},{"n":25,"t":"他們在海的對岸找到他後，對他說：「拉比，你幾時到這裏來的？」","notes":[]},{"n":26,"t":"耶穌回答他們說：「我實實在在地告訴你們，你們找我，並不是因見了神蹟，而是因吃餅吃飽了。","notes":[]},{"n":27,"t":"不要為那會壞的食物操勞，而要為那存到永生的食物操勞。這食物是人子要賜給你們的，因為父神已印證了。」","notes":[]},{"n":28,"t":"於是他們問他：「我們該做甚麼才算是做神的工作呢？」","notes":[]},{"n":29,"t":"耶穌回答，對他們說：「信神所差來的，這就是神的工作。」","notes":[]},{"n":30,"t":"於是他們對他說：「你行甚麼神蹟，好讓我們看見而信你呢？你到底要做甚麼呢？","notes":[]},{"n":31,"t":"我們的祖宗在曠野吃過嗎哪，如經上寫著：『他從天上賜下糧食來給他們吃。』」","notes":[]},{"n":32,"t":"於是耶穌對他們說：「我實實在在地告訴你們，那從天上來的糧不是摩西賜給你們的，那從天上來的真糧是我父賜給你們的。","notes":[]},{"n":33,"t":"因為神的糧就是那位從天上降下來，並且賜生命給世界的。」","notes":[]},{"n":34,"t":"於是他們對他說：「主啊，請常常把這糧賜給我們！」","notes":[]},{"n":35,"t":"耶穌對他們說：「我就是生命的糧。到我這裏來的，絕不飢餓；信我的，永不乾渴。","notes":[]},{"n":36,"t":"可是，我告訴過你們，你們已經看見我，還是不信。","notes":["有古卷沒有「我」。"]},{"n":37,"t":"凡父所賜給我的人，必到我這裏來；到我這裏來的，我總不丟棄他。","notes":[]},{"n":38,"t":"因為我從天上降下來，不是要按自己的意願行，而是要遵行差我來那位的旨意。","notes":[]},{"n":39,"t":"差我來那位的旨意就是：他所賜給我的，要我一個也不失落，並且在末日使他復活。","notes":[]},{"n":40,"t":"因為我父的旨意是要使每一個見了子而信的人得永生，並且在末日我要使他復活。」","notes":[]},{"n":41,"t":"猶太人因為耶穌說「我是從天上降下來的糧」，就私下議論他，","notes":[]},{"n":42,"t":"說：「這不是約瑟的兒子耶穌嗎？我們豈不認得他的父母嗎？現在他怎麼說『我是從天上降下來的』呢？」","notes":[]},{"n":43,"t":"耶穌回答，對他們說：「你們不要彼此私下議論。","notes":[]},{"n":44,"t":"若不是差我來的父吸引人，就沒有人能到我這裏來；到我這裏來的，在末日我要使他復活。","notes":[]},{"n":45,"t":"在先知書上寫著：『他們都要蒙神教導。』凡聽了父的教導而學習的，都到我這裏來。","notes":[]},{"n":46,"t":"這不是說有人看見過父，惟獨從神來的，他才看見過父。","notes":[]},{"n":47,"t":"我實實在在地告訴你們，信的人有永生。","notes":[]},{"n":48,"t":"我就是生命的糧。","notes":[]},{"n":49,"t":"你們的祖宗在曠野吃過嗎哪，還是死了。","notes":[]},{"n":50,"t":"這是從天上降下來的糧，使人吃了就不死。","notes":[]},{"n":51,"t":"我就是從天上降下來生命的糧；人若吃這糧，必永遠活著。我為世人的生命所賜下的糧就是我的肉。」","notes":[]},{"n":52,"t":"因此，猶太人彼此爭論說：「這個人怎能把他的肉給我們吃呢？」","notes":[]},{"n":53,"t":"耶穌對他們說：「我實實在在地告訴你們，你們若不吃人子的肉，不喝人子的血，在你們裏面就沒有生命。","notes":[]},{"n":54,"t":"吃我肉、喝我血的人就有永生，並且在末日我要使他復活。","notes":[]},{"n":55,"t":"我的肉是真正可吃的；我的血是真正可喝的。","notes":[]},{"n":56,"t":"吃我肉、喝我血的人常在我裏面，我也常在他裏面。","notes":[]},{"n":57,"t":"永生的父怎樣差我來，我又怎樣因父活著，照樣，吃我肉的人也要因我活著。","notes":[]},{"n":58,"t":"這是從天上降下來的糧，不像你們的祖宗吃過嗎哪還是死了；吃這糧的人將永遠活著。」","notes":[]},{"n":59,"t":"這些話是耶穌在迦百農會堂裏教導人的時候說的。","notes":[]},{"n":60,"t":"他的門徒中有好些人聽見了，就說：「這話很難，誰聽得進呢？」","notes":[],"heads":["永生的話"]},{"n":61,"t":"耶穌心裏知道門徒為這話私下議論，就對他們說：「這話成了你們的絆腳石嗎？","notes":[]},{"n":62,"t":"如果你們看見人子升到他原來所在之處，會怎麼樣呢？","notes":[]},{"n":63,"t":"聖靈賜人生命，肉體毫無用處。我對你們所說的話就是靈，就是生命。","notes":[]},{"n":64,"t":"可是你們中間有些人不信。」耶穌起初就知道哪些人不信他，哪一個要出賣他。","notes":[]},{"n":65,"t":"於是耶穌說：「所以，我對你們說過，若不是蒙我父的恩賜，沒有人能到我這裏來。」","notes":[]},{"n":66,"t":"從此，他門徒中有很多退卻了，不再和他同行。","notes":[]},{"n":67,"t":"耶穌就對那十二使徒說：「你們也要離開嗎？」","notes":[]},{"n":68,"t":"西門‧彼得回答他：「主啊，你有永生之道，我們還跟從誰呢？","notes":[]},{"n":69,"t":"我們已經信了，又知道你是神的聖者。」","notes":[]},{"n":70,"t":"耶穌回答他們：「我不是揀選了你們十二個嗎？但你們中間有一個是魔鬼。」","notes":[]},{"n":71,"t":"耶穌這話是指著要出賣他的加略人西門的兒子猶大說的；他本是十二使徒裏的一個。","notes":[]}]},"7":{"heading":"耶穌的兄弟們不信","verses":[{"n":1,"t":"這些事以後，耶穌周遊加利利，不願在猶太往來，因為猶太人想要殺他。","notes":[]},{"n":2,"t":"這時猶太人的住棚節近了。","notes":[]},{"n":3,"t":"耶穌的兄弟們對他說：「你離開這裏上猶太去吧，好讓你的門徒也看見你所做的事。","notes":[]},{"n":4,"t":"因為人要揚名，沒有在隱祕的地方行事的，如果你要做這些事，該把自己顯明給世人看。」","notes":[]},{"n":5,"t":"原來連他的兄弟們也不信他。","notes":[]},{"n":6,"t":"於是耶穌對他們說：「我的時機還沒有到，你們的時機卻隨時都有。","notes":[]},{"n":7,"t":"世人不會恨你們，卻是恨我，因為我指證他們的行為是惡的。","notes":[]},{"n":8,"t":"你們上去過節吧！我現在不上去過這節，因為我的時機還沒有成熟。」","notes":["有古卷是「我現在還沒有上去過這節」。"]},{"n":9,"t":"耶穌說了這些話，仍然留在加利利。","notes":[]},{"n":10,"t":"但他的兄弟們上去過節以後，他也上去，不是公開去，卻似乎是祕密地去的。","notes":["有古卷沒有「似乎」。"],"heads":["耶穌過住棚節"]},{"n":11,"t":"節期間，猶太人尋找耶穌，說：「他在哪裏？」","notes":[]},{"n":12,"t":"人群中有許多人對他議論紛紛，另有的說：「他是好人。」有的說：「不，他是迷惑群眾的。」","notes":[]},{"n":13,"t":"可是沒有人公開談論他，因為他們怕猶太人。","notes":[]},{"n":14,"t":"節期已過了一半，耶穌上聖殿去教導人。","notes":[]},{"n":15,"t":"猶太人驚訝地說：「這個人沒有學過，怎麼那樣熟悉經典呢？」","notes":[]},{"n":16,"t":"於是耶穌回答他們，說：「我的教導不是我自己的，而是差我來那位的。","notes":[]},{"n":17,"t":"人若立志要遵行神的旨意，就會知道這教導究竟是出於神，還是我憑著自己說的。","notes":[]},{"n":18,"t":"憑著自己說的人是尋求自己的榮耀；但那尋求差他來那位的榮耀的人，他是真誠的，在他心裏沒有不義。","notes":[]},{"n":19,"t":"摩西不是傳了律法給你們嗎？你們卻沒有一個人守律法。為甚麼想要殺我呢？」","notes":[]},{"n":20,"t":"眾人回答：「你是被鬼附了！誰想要殺你呢？」","notes":[]},{"n":21,"t":"耶穌回答，對他們說：「我做了一件事，你們都驚訝。","notes":[]},{"n":22,"t":"摩西傳割禮給你們（其實割禮不是從摩西開始，而是從列祖開始的），你們就在安息日給人行割禮。","notes":[]},{"n":23,"t":"人若在安息日受割禮，是為了不違背摩西的律法，我在安息日使一個人痊癒了，你們就向我發怒嗎？","notes":[]},{"n":24,"t":"不要憑外表斷定是非，總要按公平斷定是非。」","notes":[]},{"n":25,"t":"於是耶路撒冷人中有的說：「這個人不是他們想要殺的嗎？","notes":[],"heads":["這是基督嗎？"]},{"n":26,"t":"你看，他還公開講道，他們也不對他說甚麼。難道官長真的認為這是基督嗎？","notes":[]},{"n":27,"t":"然而，我們知道這個人從哪裏來；可是基督來的時候，沒有人知道他從哪裏來。」","notes":[]},{"n":28,"t":"那時，耶穌在聖殿裏教導人，喊著說：「你們認識我，也知道我從哪裏來；我並不是憑著自己來的。但差我來的那位是真實的，你們不認識他。","notes":[]},{"n":29,"t":"我卻認識他，因為我從他那裏來，是他差遣了我。」","notes":[]},{"n":30,"t":"於是他們想要捉拿耶穌，只是沒有人下手，因為他的時候還沒有到。","notes":[]},{"n":31,"t":"但人群中有好些人信他，他們說：「基督來的時候，他所行的神蹟難道會比這人行的更多嗎？」","notes":[]},{"n":32,"t":"法利賽人聽見群眾對耶穌這樣議論紛紛，祭司長和法利賽人就打發聖殿警衛去捉拿他。","notes":[],"heads":["祭司長差人捉拿耶穌"]},{"n":33,"t":"於是耶穌說：「我跟你們在一起的時候不會太久了，我要回到那差我來的那裏去。","notes":[]},{"n":34,"t":"你們要找我，卻找不到；我所在的地方，你們不能去。」","notes":[]},{"n":35,"t":"於是猶太人彼此問：「這人要往哪裏去，使我們找不到他呢？難道他要往散居在希臘的猶太人那裏去教導希臘人嗎？","notes":[]},{"n":36,"t":"他說『你們要找我，卻找不到；我所在的地方，你們不能去』，這話是甚麼意思呢？」","notes":[]},{"n":37,"t":"節期的最後一天，就是最隆重的一天，耶穌站著，喊著說：「人若渴了，到我這裏來喝！","notes":[],"heads":["活水的江河"]},{"n":38,"t":"信我的人，就如經上所說：『從他腹中將流出活水的江河來。』」","notes":[]},{"n":39,"t":"耶穌這話是指信他的人要受聖靈說的；那時還沒有賜下聖靈，因為耶穌還沒有得到榮耀。","notes":[]},{"n":40,"t":"眾人聽見這些話，有的說：「這真是那先知。」","notes":[],"heads":["眾人因耶穌而分裂"]},{"n":41,"t":"另有的說：「這是基督。」但也有的說：「難道基督是出自加利利嗎？","notes":[]},{"n":42,"t":"經上不是說『基督是大衛的後裔，出自大衛的本鄉伯利恆』嗎？」","notes":[]},{"n":43,"t":"於是眾人因耶穌而分裂了。","notes":[]},{"n":44,"t":"其中有人要捉拿他，只是沒有人下手。","notes":[]},{"n":45,"t":"警衛們回到祭司長和法利賽人那裏。他們對警衛說：「你們為甚麼沒有帶他來呢？」","notes":[],"heads":["猶太領袖的不信"]},{"n":46,"t":"警衛回答：「從來沒有像他這樣說話的！」","notes":[]},{"n":47,"t":"於是法利賽人說：「你們也受了迷惑嗎？","notes":[]},{"n":48,"t":"難道官長或法利賽人中有信他的嗎？","notes":[]},{"n":49,"t":"但這些不明白律法的眾人是被詛咒的！」","notes":[]},{"n":50,"t":"其中有尼哥德慕，就是從前去見過耶穌的，對他們說：","notes":[]},{"n":51,"t":"「不先聽本人的口供，查明他所做的事，難道我們的律法還定他的罪嗎？」","notes":[]},{"n":52,"t":"他們回答他說：「你也是出自加利利嗎？你去查考就知道，加利利是不出先知的。」","notes":[]},{"n":53,"t":"〔 於是各人都回家去了，","notes":[],"heads":["犯姦淫時被捉的女人"]}]},"8":{"heading":"耶穌是世界的光","verses":[{"n":1,"t":"耶穌卻到橄欖山去。","notes":[]},{"n":2,"t":"清早，他又回到聖殿裏。眾百姓都到他那裏去，他就坐下，教導他們。","notes":[]},{"n":3,"t":"文士和法利賽人帶著一個犯姦淫時被捉的女人來，叫她站在當中，","notes":[]},{"n":4,"t":"然後對耶穌說：「老師，這女人是正在犯姦淫的時候被捉到的。","notes":[]},{"n":5,"t":"摩西在律法書上命令我們把這樣的女人用石頭打死。那麼，你怎麼說呢？」","notes":[]},{"n":6,"t":"他們說這話是要試探耶穌，要抓到控告他的把柄。耶穌卻彎下腰，用指頭在地上寫字。","notes":[]},{"n":7,"t":"他們還是不住地問他，耶穌就直起腰來，對他們說：「你們中間誰沒有罪，誰就先拿石頭打她！」","notes":[]},{"n":8,"t":"於是他又彎著腰，用指頭在地上寫字。","notes":[]},{"n":9,"t":"他們聽見這話，從老的開始，一個一個都走開了，只剩下耶穌一人和那仍然站在中間的女人。","notes":[]},{"n":10,"t":"耶穌就直起腰來，對她說：「婦人，那些人在哪裏呢？沒有任何人定你的罪嗎？」","notes":[]},{"n":11,"t":"她說：「主啊，沒有。」耶穌說：「我也不定你的罪。去吧！從今以後不要再犯罪了。」〕","notes":["最早的古卷沒有括弧內7．53和8．1-11這段經文；有古卷把它放在約翰福音21．24之後；另有古卷把它放在路加福音21．38之後。"]},{"n":12,"t":"耶穌又對眾人說：「我就是世界的光。跟從我的，必不在黑暗裏走，卻要得著生命的光。」","notes":[]},{"n":13,"t":"法利賽人對他說：「你是為自己作見證，你的見證不真。」","notes":[]},{"n":14,"t":"耶穌回答他們，對他們說：「即使我為自己作見證，我的見證還是真的，因為我知道我從哪裏來，到哪裏去。你們卻不知道我從哪裏來，到哪裏去。","notes":[]},{"n":15,"t":"你們是以人的標準來判斷人，我不判斷任何人。","notes":[]},{"n":16,"t":"即使我判斷人，我的判斷也是真確的，因為不是我獨自在判斷，而是差我來的父與我一同判斷。","notes":[]},{"n":17,"t":"你們的律法也記著說：『兩個人的見證才算為真』。","notes":[]},{"n":18,"t":"我是為自己作見證，還有差我來的父也為我作見證。」","notes":[]},{"n":19,"t":"於是他們問他：「你的父在哪裏？」耶穌回答：「你們不認識我，也不認識我的父；若是認識我，也會認識我的父。」","notes":[]},{"n":20,"t":"這些話是耶穌在聖殿的銀庫房裏教導人的時候說的。當時沒有人捉拿他，因為他的時候還沒有到。","notes":[]},{"n":21,"t":"於是耶穌又對他們說：「我去了，你們會找我，而你們會死在自己的罪中；我所去的地方，你們不能去。」","notes":[],"heads":["我所去的地方你們不能去"]},{"n":22,"t":"猶太人說：「他說『我所去的地方，你們不能去』，難道他要自殺嗎？」","notes":[]},{"n":23,"t":"耶穌對他們說：「你們是從下面來的，我是從上面來的；你們是屬這世界的，我不是屬這世界的。","notes":[]},{"n":24,"t":"所以我對你們說，你們會死在自己的罪中，你們若不信我就是那位，就會死在自己的罪中。」","notes":[]},{"n":25,"t":"他們就問他：「你到底是誰？」耶穌對他們說：「我從起初就告訴你們了。","notes":[]},{"n":26,"t":"我有許多事要講論你們，判斷你們；但差我來的那位是真實的，我從他那裏所聽見的，就告訴世人。」","notes":[]},{"n":27,"t":"他們不明白耶穌是對他們講父的事。","notes":[]},{"n":28,"t":"所以耶穌說：「你們舉起人子以後就會知道我就是那位了，並且知道我沒有一件事是憑著自己做的。我說這些話是照著父所教導我的。","notes":[]},{"n":29,"t":"差我來的那位與我同在；他沒有撇下我獨自一人，因為我一直行他所喜悅的事。」","notes":[]},{"n":30,"t":"耶穌說這些話的時候，有許多人信了他。","notes":[]},{"n":31,"t":"耶穌對信他的猶太人說：「你們若繼續遵守我的道，就真是我的門徒了。","notes":[],"heads":["真理使你們自由"]},{"n":32,"t":"你們將認識真理，真理會使你們自由。」","notes":[]},{"n":33,"t":"他們回答他：「我們是亞伯拉罕的後裔，從來沒有作過誰的奴隸，你怎麼說『會使你們自由』呢？」","notes":[]},{"n":34,"t":"耶穌回答他們：「我實實在在地告訴你們，所有犯罪的人就是罪的奴隸。","notes":[]},{"n":35,"t":"奴隸不能永遠住在家裏；兒子才永遠住在家裏。","notes":[]},{"n":36,"t":"所以，神的兒子若使你們自由，你們就真正自由了。」","notes":[]},{"n":37,"t":"「我知道，你們是亞伯拉罕的後裔，你們卻想要殺我，因為你們心裏容不下我的道。","notes":[],"heads":["出於神的必聽神的話"]},{"n":38,"t":"我所說的是在我父那裏看見的；你們所做的是在你們的父那裏聽到的。」","notes":[]},{"n":39,"t":"他們回答耶穌：「我們的父是亞伯拉罕。」耶穌對他們說：「你們若是亞伯拉罕的兒女，就會做亞伯拉罕所做的事。","notes":[]},{"n":40,"t":"我把在神那裏所聽見的真理告訴了你們，現在你們卻想要殺我；亞伯拉罕沒有做過這樣的事。","notes":[]},{"n":41,"t":"你們是做你們父的工作。」他們就對他說：「我們不是從淫亂生的，我們只有一位父，就是神。」","notes":[]},{"n":42,"t":"耶穌對他們說：「假如神是你們的父，你們會愛我，因為我本是出於神，也是從神而來，我不是憑著自己來，而是他差我來的。","notes":[]},{"n":43,"t":"你們為甚麼不明白我的話呢？無非是你們聽不進我的道。","notes":[]},{"n":44,"t":"你們是出於你們的父魔鬼，你們寧願隨著你們父的慾念而行。他從起初就是殺人的，不守真理，因他心裏沒有真理。他說謊是出於自己的本性，因他本來是說謊的，也是說謊者之父。","notes":[]},{"n":45,"t":"但是，因為我講真理，你們就不信我。","notes":[]},{"n":46,"t":"你們中間誰能指證我有罪呢？既然我講真理，你們為甚麼不信我呢？","notes":[]},{"n":47,"t":"出於神的，必聽神的話；你們不聽，因為你們不是出於神。」","notes":[]},{"n":48,"t":"猶太人回答他：「我們說你是撒瑪利亞人，並且是被鬼附的，這話不是很對嗎？」","notes":[],"heads":["耶穌在亞伯拉罕之先"]},{"n":49,"t":"耶穌回答：「我沒有被鬼附；我尊敬我的父，你們卻不尊敬我。","notes":[]},{"n":50,"t":"我不尋求自己的榮耀，但有一位為我尋求榮耀，判斷是非。","notes":[]},{"n":51,"t":"我實實在在地告訴你們，人若遵守我的道，就永遠不經歷死亡。」","notes":[]},{"n":52,"t":"於是猶太人對他說：「現在我們知道你是被鬼附了。亞伯拉罕死了，眾先知也死了，你還說：『人若遵守我的道，就永遠不經歷死亡。』","notes":[]},{"n":53,"t":"難道你比我們的祖宗亞伯拉罕還大嗎？他死了，眾先知也死了，你把自己當作甚麼人呢？」","notes":[]},{"n":54,"t":"耶穌回答：「我若榮耀自己，我的榮耀就算不了甚麼；榮耀我的是我的父，就是你們所說的你們的神。","notes":[]},{"n":55,"t":"你們不認識他，我卻認識他。我若說不認識他，我就是說謊的，像你們一樣；但我認識他，也遵守他的道。","notes":[]},{"n":56,"t":"你們的祖宗亞伯拉罕歡歡喜喜地仰望我的日子，他看見了，就快樂。」","notes":[]},{"n":57,"t":"猶太人就對他說：「你還沒有五十歲，難道見過亞伯拉罕嗎？」","notes":[]},{"n":58,"t":"耶穌對他們說：「我實實在在地告訴你們，還沒有亞伯拉罕我就存在了。」","notes":[]},{"n":59,"t":"於是他們拿石頭要打他，耶穌卻躲開，走出了聖殿。","notes":[]}]},"9":{"heading":"治好生來失明的人","verses":[{"n":1,"t":"耶穌往前走的時候，看見一個生來就失明的人。","notes":[]},{"n":2,"t":"門徒問耶穌：「拉比，這人生來失明，是誰犯了罪？是這人還是他的父母呢？」","notes":[]},{"n":3,"t":"耶穌回答：「既不是這人犯了罪，也不是他的父母，而是要在他身上顯出神的作為來。","notes":[]},{"n":4,"t":"趁著白日，我們必須做差我來的那位的工；黑夜來到，就沒有人能做工了。","notes":["有古卷是「我」。","有古卷是「我們」。"]},{"n":5,"t":"我在世上的時候，是世上的光。」","notes":[]},{"n":6,"t":"耶穌說了這些話，就吐唾沫在地上，用唾沫和了泥抹在盲人的眼睛上，","notes":[]},{"n":7,"t":"對他說：「你到西羅亞池子裏去洗。」（西羅亞翻出來就是「奉差遣」。）於是他去，洗了，回來就看見了。","notes":[]},{"n":8,"t":"他的鄰舍和素常見他討飯的人，就說：「這不是那從前坐著討飯的人嗎？」","notes":[]},{"n":9,"t":"有的說：「是他」；又有的說：「不是，卻是像他。」他自己說：「是我。」","notes":[]},{"n":10,"t":"於是他們對他說：「你的眼睛是怎麼開的呢？」","notes":[]},{"n":11,"t":"那人回答：「有一個名叫耶穌的，他和了泥抹我的眼睛，對我說：『你到西羅亞池子去洗。』我去一洗，就看見了。」","notes":[]},{"n":12,"t":"他們對他說：「那個人在哪裏？」他說：「我不知道。」","notes":[]},{"n":13,"t":"他們把以前失明的那個人帶到法利賽人那裏。","notes":[],"heads":["法利賽人盤問醫治的事"]},{"n":14,"t":"耶穌和泥開他眼睛的那一天是安息日。","notes":[]},{"n":15,"t":"法利賽人又問他是怎麼得看見的。他對他們說：「他把泥抹在我的眼睛上，我一洗，就看見了。」","notes":[]},{"n":16,"t":"於是法利賽人中有的說：「這個人不是從神來的，因為他不守安息日。」另有的說：「一個罪人怎能行這樣的神蹟呢？」他們之間就產生了分裂。","notes":[]},{"n":17,"t":"於是他們又對那盲人說：「他開了你的眼睛，你說他是怎樣的人呢？」他說：「他是個先知。」","notes":[]},{"n":18,"t":"猶太人不信他以前是失明，後來能看見的，等到叫了他的父母來，","notes":[]},{"n":19,"t":"問他們說：「這是你們的兒子嗎？你們說他生來是失明的，現在怎麼看見了呢？」","notes":[]},{"n":20,"t":"他的父母就回答說：「他是我們的兒子，生來就失明，這是我們知道的。","notes":[]},{"n":21,"t":"至於他現在怎麼能看見，我們卻不知道；是誰開了他的眼睛，我們也不知道。他已經是成人，你們問他吧，他自己會說。」","notes":[]},{"n":22,"t":"他父母說這些話，是怕猶太人，因為猶太人已經商定，若有宣認耶穌是基督的，要把他趕出會堂。","notes":[]},{"n":23,"t":"因此他父母說「他已經是成人，你們問他吧」。","notes":[]},{"n":24,"t":"於是法利賽人第二次叫了那以前失明的人來，對他說：「你要將榮耀歸給神，我們知道這人是個罪人。」","notes":[]},{"n":25,"t":"那人就回答：「他是不是個罪人，我不知道；有一件事我知道，我本來是失明的，現在我看見了。」","notes":[]},{"n":26,"t":"他們就問他：「他給你做了甚麼？是怎麼開了你的眼睛？」","notes":[]},{"n":27,"t":"他回答他們：「我已經告訴你們了，你們不聽，為甚麼又要聽呢？難道你們也要作他的門徒嗎？」","notes":[]},{"n":28,"t":"他們就罵他：「你是他的門徒，而我們是摩西的門徒。","notes":[]},{"n":29,"t":"神對摩西說話是我們知道的，可是這個人，我們不知道他從哪裏來。」","notes":[]},{"n":30,"t":"那人回答，對他們說：「他開了我的眼睛，你們竟不知道他從哪裏來，這真是奇怪！","notes":[]},{"n":31,"t":"我們知道神不聽罪人，惟有敬奉神、遵行他旨意的，神才聽他。","notes":[]},{"n":32,"t":"從創世以來，未曾聽見有人開了生來就失明的人的眼睛。","notes":[]},{"n":33,"t":"這人若不是從神來的，甚麼也不能做。」","notes":[]},{"n":34,"t":"他們回答他說：「你完全是生在罪中的，還要來教訓我們嗎？」於是他們把他趕出去了。","notes":[]},{"n":35,"t":"耶穌聽說他們把他趕出去，就找到他，說：「你信人子嗎？」","notes":["有古卷是「神的兒子」。"],"heads":["靈性的盲目"]},{"n":36,"t":"那人回答說：「主啊，人子是誰？告訴我，好讓我信他。」","notes":[]},{"n":37,"t":"耶穌對他說：「你已經看見他，現在和你說話的就是他。」","notes":[]},{"n":38,"t":"他說：「主啊，我信！」他就拜耶穌。","notes":[]},{"n":39,"t":"耶穌說：「我為審判到這世上來，使不能看見的看見，能看見的反而失明。」","notes":[]},{"n":40,"t":"同他在那裏的法利賽人聽見這些話，就對他說：「難道我們也失明了嗎？」","notes":[]},{"n":41,"t":"耶穌對他們說：「你們若是失明的，就沒有罪了；但現在你們說『我們能看見』，你們的罪還在。」","notes":[]}]},"10":{"heading":"羊圈的比喻","verses":[{"n":1,"t":"「我實實在在地告訴你們，那不從門進羊圈，倒從別處爬進去的，就是賊，就是強盜。","notes":[]},{"n":2,"t":"那從門進去的才是羊的牧人。","notes":[]},{"n":3,"t":"看門的給他開門，羊也聽他的聲音。他按著名叫自己的羊，把羊領出來。","notes":[]},{"n":4,"t":"當他把自己的羊都放出來，就走在前面，羊也跟著他，因為牠們認得他的聲音。","notes":[]},{"n":5,"t":"羊絕不跟陌生人，反而會逃走，因為不認得陌生人的聲音。」","notes":[]},{"n":6,"t":"耶穌把這比方告訴他們，但他們不明白他所說的是甚麼。","notes":[]},{"n":7,"t":"所以，耶穌又對他們說：「我實實在在地告訴你們，我就是羊的門。","notes":[],"heads":["耶穌是好牧人"]},{"n":8,"t":"凡在我以前來的都是賊，是強盜；羊沒有聽從他們。","notes":["有古卷沒有「在我以前」。"]},{"n":9,"t":"我就是門，凡從我進來的，必得安全，並且可進出，找到草吃。","notes":["「必得安全」或譯「必然得救」。"]},{"n":10,"t":"盜賊來，無非要偷竊、殺害、毀壞；我來了，是要羊得生命，並且得的更豐盛。","notes":[]},{"n":11,"t":"「我是好牧人，好牧人為羊捨命。","notes":[]},{"n":12,"t":"雇工不是牧人，羊不是他自己的，他一看見狼來，就撇下羊群逃跑；狼抓住羊，把牠們趕散。","notes":[]},{"n":13,"t":"雇工逃走，因為他是雇工，對羊毫不關心。","notes":[]},{"n":14,"t":"我是好牧人；我認識我的羊，我的羊也認識我，","notes":[]},{"n":15,"t":"正如父認識我，我也認識父一樣；並且我為羊捨命。","notes":[]},{"n":16,"t":"我另外有羊，不屬這圈裏的，我必須領牠們來，牠們也要聽我的聲音，並且要合成一群，歸一個牧人。","notes":[]},{"n":17,"t":"為此，我父愛我，因為我把命捨去，好再取回來。","notes":[]},{"n":18,"t":"沒有人奪去我的命，是我自己捨的；我有權捨棄，也有權再取回。這是我從我父所受的命令。」","notes":[]},{"n":19,"t":"猶太人為這些話又起了分裂。","notes":[]},{"n":20,"t":"其中有好些人說：「他是被鬼附了，而且瘋了，為甚麼聽他的呢？」","notes":[]},{"n":21,"t":"另有的說：「這不是被鬼附的人所說的話。鬼豈能開盲人的眼睛呢？」","notes":[]},{"n":22,"t":"那時正是冬天，在耶路撒冷有獻殿節。","notes":[],"heads":["猶太人棄絕耶穌"]},{"n":23,"t":"耶穌在聖殿裏的所羅門廊下行走。","notes":[]},{"n":24,"t":"猶太人圍著他，對他說：「你讓我們猶豫不定到幾時呢？你若是基督，就明白地告訴我們。」","notes":[]},{"n":25,"t":"耶穌回答他們：「我已經告訴你們，你們卻不信。我奉我父的名所行的事可以為我作見證。","notes":[]},{"n":26,"t":"但是你們不信，因為你們不是我的羊。","notes":[]},{"n":27,"t":"我的羊聽我的聲音，我認識牠們，牠們也跟從我。","notes":[]},{"n":28,"t":"並且，我賜給他們永生；他們永不滅亡，誰也不能從我手裏把他們奪去。","notes":[]},{"n":29,"t":"我父所賜給我的比萬有都大，誰也不能從我父手裏把他們奪去。","notes":["有古卷是「我父把他們賜給我，他比萬有都大」。"]},{"n":30,"t":"我與父原為一。」","notes":[]},{"n":31,"t":"猶太人又拿起石頭來要打他。","notes":[]},{"n":32,"t":"耶穌回應他們：「我做了許多從父那裏來的善事給你們看，你們是為哪一件拿石頭打我呢？」","notes":[]},{"n":33,"t":"猶太人回答他：「我們不是為了善事拿石頭打你，而是為了你說褻瀆的話；因為你是個人，卻把自己當作神。」","notes":[]},{"n":34,"t":"耶穌回答他們：「你們的律法書上不是寫著『我曾說你們是諸神』嗎？","notes":[]},{"n":35,"t":"經上的話是不能廢的；如果那些領受神的道的人，神尚且稱他們為諸神，","notes":[]},{"n":36,"t":"那麼父所分別為聖又差到世上來的那位說『我是神的兒子』，你們還對他說『你說褻瀆的話』嗎？","notes":[]},{"n":37,"t":"我若不做我父的工作，你們就不必信我；","notes":[]},{"n":38,"t":"我若做了，你們即使不信我，也當信這些工作，好讓你們知道並且明白父在我裏面，我也在父裏面。」","notes":[]},{"n":39,"t":"於是，他們又要捉拿他，他卻從他們手中逃脫了。","notes":[]},{"n":40,"t":"耶穌又往約旦河的東邊去，到了約翰起初施洗的地方，就住在那裏。","notes":[]},{"n":41,"t":"有許多人來到他那裏，說：「約翰沒有行過一件神蹟，但約翰所說有關這人的一切話都是真的。」","notes":[]},{"n":42,"t":"在那裏，許多人信了耶穌。","notes":[]}]},"11":{"heading":"拉撒路的死","verses":[{"n":1,"t":"有一個患病的人，名叫拉撒路，住在伯大尼，就是馬利亞和她姐姐馬大的村莊。","notes":[]},{"n":2,"t":"這馬利亞就是那用香膏抹主，又用頭髮擦他腳的；患病的拉撒路是她的弟弟。","notes":[]},{"n":3,"t":"姊妹兩個就打發人去見耶穌，說：「主啊，你所愛的人病了。」","notes":[]},{"n":4,"t":"耶穌聽見後卻說：「這病不至於死，而是為了神的榮耀，為要使神的兒子藉此得榮耀。」","notes":[]},{"n":5,"t":"耶穌素來愛馬大和她妹妹，以及拉撒路。","notes":[]},{"n":6,"t":"他聽見拉撒路病了，仍在原地住了兩天，","notes":[]},{"n":7,"t":"然後對門徒說：「我們再到猶太去吧！」","notes":[]},{"n":8,"t":"門徒對他說：「拉比，猶太人近來要拿石頭打你，你還再到那裏去嗎？」","notes":[]},{"n":9,"t":"耶穌回答：「白天不是有十二小時嗎？人若在白天行走，就不致跌倒，因為他看見這世上的光。","notes":[]},{"n":10,"t":"人若在黑夜行走，就會跌倒，因為他沒有光。」","notes":[]},{"n":11,"t":"耶穌說了這些話，隨後對他們說：「我們的朋友拉撒路睡了，我去叫醒他。」","notes":[]},{"n":12,"t":"門徒就說：「主啊，他若睡了，就會好的。」","notes":[]},{"n":13,"t":"耶穌說這話是指拉撒路死了，他們卻以為他是指通常的睡眠。","notes":[]},{"n":14,"t":"於是耶穌就明白地告訴他們：「拉撒路死了。","notes":[]},{"n":15,"t":"為了你們的緣故，我不在那裏反而歡喜，為要使你們信。現在我們到他那裏去吧。」","notes":[]},{"n":16,"t":"於是那稱為低土馬的多馬對其他的門徒說：「我們也去和他同死吧！」","notes":[]},{"n":17,"t":"耶穌到了，知道拉撒路在墳墓裏已經四天了。","notes":[],"heads":["耶穌是復活，是生命"]},{"n":18,"t":"伯大尼離耶路撒冷不遠，約有六里路。","notes":["「六里」﹕即三公里，原文即「十五斯他迪」，古希臘長度單位；參「度量衡表」。"]},{"n":19,"t":"有好些猶太人來看馬大和馬利亞，要為她們弟弟的緣故安慰她們。","notes":[]},{"n":20,"t":"馬大聽見耶穌來了，就出去迎接他；馬利亞卻仍然坐在家裏。","notes":[]},{"n":21,"t":"馬大對耶穌說：「主啊，你若早在這裏，我弟弟就不會死了。","notes":[]},{"n":22,"t":"我也知道，即使現在，你無論向神求甚麼，神也必賜給你。」","notes":[]},{"n":23,"t":"耶穌對她說：「你弟弟會復活的。」","notes":[]},{"n":24,"t":"馬大對他說：「我知道在末日復活的時候，他會復活。」","notes":[]},{"n":25,"t":"耶穌對她說：「復活在我，生命也在我。信我的人雖然死了，也必復活。","notes":["「復活...也在我」：原文直譯「我就是復活和生命」。"]},{"n":26,"t":"凡活著信我的人必永遠不死。你信這話嗎？」","notes":[]},{"n":27,"t":"馬大對他說：「主啊，是的。我信你是基督，是神的兒子，就是那要臨到世界的。」","notes":[]},{"n":28,"t":"馬大說了這話就回去，叫她妹妹馬利亞，私下說：「老師來了，他在叫你。」","notes":[],"heads":["耶穌哭了"]},{"n":29,"t":"馬利亞聽見了，急忙起來，到耶穌那裏去。","notes":[]},{"n":30,"t":"那時，耶穌還沒有進村子，仍在馬大迎接他的地方。","notes":[]},{"n":31,"t":"那些同馬利亞在家裏安慰她的猶太人，見她急忙起來，出去，就跟著她，以為她要往墳墓那裏去哭。","notes":[]},{"n":32,"t":"馬利亞到了耶穌那裏，看見他，就俯伏在他腳前，對他說：「主啊，你若早在這裏，我弟弟就不會死了。」","notes":[]},{"n":33,"t":"耶穌看見她哭，並看見與她同來的猶太人也哭，就心裏悲嘆，又甚憂愁，","notes":[]},{"n":34,"t":"就說：「你們把他安放在哪裏？」他們對他說：「主啊，請你來看。」","notes":[]},{"n":35,"t":"耶穌哭了。","notes":[]},{"n":36,"t":"猶太人就說：「你看，他多麼愛他！」","notes":[]},{"n":37,"t":"其中有人說：「他既然開了盲人的眼睛，難道不能叫這人不死嗎？」","notes":[]},{"n":38,"t":"耶穌又心裏悲嘆，來到墳墓前。那墳墓是個穴，有一塊石頭擋著。","notes":[],"heads":["拉撒路復活"]},{"n":39,"t":"耶穌說：「把石頭挪開！」那死者的姐姐馬大對他說：「主啊，他現在必定臭了，因為他已經死了四天了。」","notes":[]},{"n":40,"t":"耶穌對她說：「我不是對你說過，你若信就必看見神的榮耀嗎？」","notes":[]},{"n":41,"t":"於是他們把石頭挪開。耶穌舉目望天，說：「父啊，我感謝你，因為你已經聽了我。","notes":[]},{"n":42,"t":"我知道你常常聽我，但我說這話是為了周圍站著的眾人，要使他們信是你差了我來的。」","notes":[]},{"n":43,"t":"說了這些話，他大聲呼叫說：「拉撒路，出來！」","notes":[]},{"n":44,"t":"那死了的人就出來了，手腳都裹著布，臉上包著頭巾。耶穌對他們說：「解開他，讓他走！」","notes":[]},{"n":45,"t":"於是來看馬利亞的猶太人中，有很多人見了耶穌所做的事，就信了他。","notes":[],"heads":["殺害耶穌的陰謀"]},{"n":46,"t":"但其中也有人去見法利賽人，把耶穌所做的事告訴他們。","notes":[]},{"n":47,"t":"祭司長和法利賽人召開議會，說：「這人行好些神蹟，我們怎麼辦呢？","notes":[]},{"n":48,"t":"若讓他這樣做，人人都要信他；羅馬人也要來毀滅我們的聖殿和我們的民族。」","notes":["「聖殿」或譯「土地」。"]},{"n":49,"t":"其中有一個人，名叫該亞法，那年當大祭司，對他們說：「你們甚麼都不知道，","notes":[]},{"n":50,"t":"也不想想，一個人替百姓死，免得整個民族滅亡，這對你們是有利的。」","notes":[]},{"n":51,"t":"他這話不是出於自己的意思，而是因他那年當大祭司，所以預言耶穌將為這民族而死。","notes":[]},{"n":52,"t":"他不但替這民族死，還要把神四散的兒女都聚集起來，合成一群。","notes":[]},{"n":53,"t":"從那日起，他們就商議要殺耶穌。","notes":[]},{"n":54,"t":"所以，耶穌不再公開在猶太人中走動，卻離開那裏，往靠近曠野的鄉間去，到了一座城，名叫以法蓮，就在那裏和門徒住下來。","notes":[]},{"n":55,"t":"猶太人的逾越節近了，有許多人從鄉下上耶路撒冷去，要在過節前潔淨自己。","notes":[]},{"n":56,"t":"於是他們尋找耶穌，站在聖殿裏彼此說：「你們認為怎樣，他不會來過節吧？」","notes":[]},{"n":57,"t":"那時，祭司長和法利賽人早已下令，若有人知道耶穌的下落，就要報告，他們好去捉拿他。","notes":[]}]},"12":{"heading":"在伯大尼受膏","verses":[{"n":1,"t":"逾越節前六天，耶穌來到伯大尼，就是他使拉撒路從死人中復活的地方。","notes":[]},{"n":2,"t":"有人在那裏為耶穌預備宴席；馬大伺候，拉撒路也在同耶穌坐席的人中間。","notes":[]},{"n":3,"t":"馬利亞拿著一斤極貴的純哪噠香膏，抹耶穌的腳，又用自己頭髮去擦，屋裏充滿了膏的香氣。","notes":["「哪噠」即「甘松」。"]},{"n":4,"t":"有一個門徒，就是那將要出賣耶穌的加略人猶大，說：","notes":[]},{"n":5,"t":"「為甚麼不把這香膏賣三百個銀幣去賙濟窮人呢？」","notes":[]},{"n":6,"t":"他說這話，並不是關心窮人，而是因為他是個賊，又管錢囊，常偷取錢囊中所存的。","notes":[]},{"n":7,"t":"耶穌說：「由她吧！她這香膏本是為我的安葬之日留著的。","notes":[]},{"n":8,"t":"因為常有窮人和你們在一起，但是你們不常有我。」","notes":[]},{"n":9,"t":"有一大群猶太人知道耶穌在那裏，就來了，不但是為耶穌的緣故，也是要看耶穌使他從死人中復活的拉撒路。","notes":[],"heads":["殺害拉撒路的陰謀"]},{"n":10,"t":"於是眾祭司長商議連拉撒路也要殺了，","notes":[]},{"n":11,"t":"因為有許多猶太人為了拉撒路的緣故，開始背離他們，信了耶穌。","notes":[]},{"n":12,"t":"第二天，有一大群上來過節的人聽見耶穌要來耶路撒冷，","notes":[],"heads":["榮入聖城"]},{"n":13,"t":"就拿著棕樹枝出去迎接他，喊著：「和散那，以色列的王！奉主名來的是應當稱頌的！」","notes":["「和散那」：原是求救的意思，在此是稱頌的話。"]},{"n":14,"t":"耶穌找到了一匹驢駒，就騎上，如經上所記：","notes":[]},{"n":15,"t":"「錫安的兒女啊，不要懼怕！看哪，你的王來了；他騎在驢駒上。」","notes":["「兒女」：原文直譯「女兒」。"]},{"n":16,"t":"門徒當初不明白這些事，等到耶穌得了榮耀後才想起這些話是指他寫的，並且人們果然對他做了這些事。","notes":[]},{"n":17,"t":"當耶穌呼喚拉撒路，使他從死人中復活出墳墓的時候，同耶穌在那裏的眾人就作見證。","notes":[]},{"n":18,"t":"眾人因聽見耶穌行了這神蹟，就去迎接他。","notes":[]},{"n":19,"t":"法利賽人彼此說：「你們看，你們一事無成，世人都隨著他去了。」","notes":[]},{"n":20,"t":"那時，上來過節禮拜的人中，有幾個希臘人。","notes":[],"heads":["希臘人求見耶穌"]},{"n":21,"t":"他們來見加利利的伯賽大人腓力，請求他說：「先生，我們想見耶穌。」","notes":[]},{"n":22,"t":"腓力去告訴安得烈，然後安得烈同腓力去告訴耶穌。","notes":[]},{"n":23,"t":"耶穌回答他們說：「人子得榮耀的時候到了。","notes":[]},{"n":24,"t":"我實實在在地告訴你們，一粒麥子不落在地裏死了，仍舊是一粒；若是死了，就結出許多子粒來。","notes":[]},{"n":25,"t":"愛惜自己性命的，就喪失性命；那恨惡自己在這世上的性命的，要保全性命到永生。","notes":[]},{"n":26,"t":"若有人服事我，就當跟從我；我在哪裏，服事我的人也要在哪裏；若有人服事我，我父必尊重他。」","notes":[]},{"n":27,"t":"「我現在心裏憂愁，我說甚麼才好呢？說『父啊，救我脫離這時候』嗎？但我正是為這時候來的。","notes":[],"heads":["人子必須被舉起來"]},{"n":28,"t":"父啊，願你榮耀你的名！」於是有聲音從天上來，說：「我已經榮耀了我的名，還要再榮耀。」","notes":[]},{"n":29,"t":"站在旁邊的眾人聽見，就說：「打雷了。」另有的說：「有天使對他說話。」","notes":[]},{"n":30,"t":"耶穌回答說：「這聲音不是為我，而是為你們來的。","notes":[]},{"n":31,"t":"現在正是這世界受審判的時候；現在這世界的統治者要被趕出去。","notes":[]},{"n":32,"t":"我從地上被舉起來的時候，我要吸引萬人來歸我。」","notes":[]},{"n":33,"t":"耶穌這話是指自己將要怎樣死說的。","notes":[]},{"n":34,"t":"眾人就回答他：「我們聽見律法書上說，基督是永存的；你怎麼說，人子必須被舉起來呢？這人子是誰呢？」","notes":[]},{"n":35,"t":"耶穌對他們說：「光在你們中間為時不多了，應該趁著有光的時候行走，免得黑暗臨到你們；那在黑暗裏行走的，不知道往何處去。","notes":[]},{"n":36,"t":"你們趁著有光，要信從這光，使你們成為光明之子。」耶穌說了這些話，就離開他們隱藏了。","notes":[]},{"n":37,"t":"他雖然在他們面前行了許多神蹟，他們還是不信他。","notes":[]},{"n":38,"t":"這是要應驗以賽亞先知所說的話：「主啊，我們所傳的有誰信呢？主的膀臂向誰顯露呢？」","notes":[]},{"n":39,"t":"他們所以不能信，因為以賽亞又說：","notes":[]},{"n":40,"t":"「主使他們瞎了眼，使他們硬了心，免得他們眼睛看見，他們心裏明白，回轉過來，我會醫治他們。」","notes":[]},{"n":41,"t":"以賽亞因看見了他的榮耀，就說了關於他的這話。","notes":[]},{"n":42,"t":"雖然如此，官長中卻有好些信他的，只因法利賽人的緣故不敢承認，恐怕被趕出會堂。","notes":[]},{"n":43,"t":"這是因他們愛人給的尊榮過於愛神給的尊榮。","notes":[]},{"n":44,"t":"耶穌喊著說：「信我的人不是信我，而是信差我來的那位。","notes":[],"heads":["耶穌的道要審判人"]},{"n":45,"t":"看見我的，就是看見差我來的那位。","notes":[]},{"n":46,"t":"我就是來到世上的光，使凡信我的不住在黑暗裏。","notes":[]},{"n":47,"t":"若有人聽見我的話而不遵守，我不審判他，因為我來不是要審判世人，而是要拯救世人。","notes":[]},{"n":48,"t":"棄絕我、不領受我話的人自有審判他的；我所講的道在末日要審判他。","notes":[]},{"n":49,"t":"因為我沒有憑著自己講，而是差我來的父已經給我命令，叫我說甚麼，講甚麼。","notes":[]},{"n":50,"t":"我也知道他的命令就是永生。所以，我講的正是照著父所告訴我的，我就這麼講了。」","notes":[]}]},"13":{"heading":"耶穌為門徒洗腳","verses":[{"n":1,"t":"逾越節以前，耶穌知道自己離世歸父的時候到了。他一向愛世間屬自己的人，就愛他們到底。","notes":[]},{"n":2,"t":"晚餐的時候，魔鬼已把出賣耶穌的意思放在加略人西門的兒子猶大心裏。","notes":[]},{"n":3,"t":"耶穌知道父已把萬有交在他手裏，且知道自己是從神出來的，又要回到神那裏去，","notes":[]},{"n":4,"t":"就離席站起來，脫了衣服，拿一條手巾束腰，","notes":[]},{"n":5,"t":"隨後把水倒在盆裏，開始洗門徒的腳，並用束腰的手巾擦乾。","notes":[]},{"n":6,"t":"到了西門‧彼得跟前，彼得對他說：「主啊，你洗我的腳嗎？」","notes":[]},{"n":7,"t":"耶穌回答他說：「我所做的，你現在不知道，但以後會明白。」","notes":[]},{"n":8,"t":"彼得對他說：「你絕對不可以洗我的腳！」耶穌回答他：「我若不洗你，你就與我無份了。」","notes":[]},{"n":9,"t":"西門‧彼得對他說：「主啊，不僅是我的腳，連手和頭也要洗！」","notes":[]},{"n":10,"t":"耶穌對他說：「凡洗過澡的人不需要再洗，只要把腳一洗，全身就乾淨了。你們是乾淨的，然而不都是乾淨的。」","notes":[]},{"n":11,"t":"耶穌已知道要出賣他的是誰，因此說「你們不都是乾淨的」。","notes":[]},{"n":12,"t":"耶穌洗完了他們的腳，就穿上衣服，又坐下，對他們說：「我為你們所做的，你們明白嗎？","notes":[]},{"n":13,"t":"你們稱呼我老師，稱呼我主，你們說的不錯，我本來就是。","notes":[]},{"n":14,"t":"我是你們的主，你們的老師，尚且洗你們的腳，你們也應當彼此洗腳。","notes":[]},{"n":15,"t":"我給你們作了榜樣，為要你們照著我為你們所做的去做。","notes":[]},{"n":16,"t":"我實實在在地告訴你們，僕人不大於主人；奉差的人也不大於差他的人。","notes":[]},{"n":17,"t":"你們既知道這些事，若是去實行就有福了。","notes":[]},{"n":18,"t":"我不是指著你們眾人說的，我知道我所揀選的是誰；但是要應驗經上的話：『吃我飯的人用腳踢我。』","notes":["有古卷是「同我吃飯的人」。"]},{"n":19,"t":"事情還沒有發生，我現在先告訴你們，讓你們到事情發生的時候好信我就是那位。","notes":[]},{"n":20,"t":"我實實在在地告訴你們，接納我所差遣的就是接納我；接納我的就是接納差遣我的那位。」","notes":[]},{"n":21,"t":"耶穌說了這些話，心裏憂愁，於是明確地說：「我實實在在地告訴你們，你們中間有一個人要出賣我。」","notes":[],"heads":["耶穌預言將被出賣"]},{"n":22,"t":"門徒彼此相看，猜不出他說的是誰。","notes":[]},{"n":23,"t":"門徒中有一個人，是耶穌所愛的，側身挨近耶穌的胸懷。","notes":[]},{"n":24,"t":"西門‧彼得就對這個人示意，要問耶穌是指著誰說的。","notes":[]},{"n":25,"t":"於是那人緊靠著耶穌的胸膛，問他：「主啊，是誰呢？」","notes":[]},{"n":26,"t":"耶穌回答：「我蘸一點餅給誰，就是誰。」耶穌就蘸了一點餅，遞給加略人西門的兒子猶大。","notes":[]},{"n":27,"t":"他接了那餅以後，撒但就進入他的心。於是耶穌對他說：「你要做的，快做吧！」","notes":["「接」或譯「吃」。"]},{"n":28,"t":"同席的人沒有一個知道耶穌為甚麼對他說這話。","notes":[]},{"n":29,"t":"有人因猶大管錢囊，以為耶穌是對他說「你去買我們過節所需要的東西」，或是叫他拿些甚麼給窮人。","notes":[]},{"n":30,"t":"猶大受了那點餅以後立刻出去。那時候是夜間了。","notes":["「受」或譯「吃」。"]},{"n":31,"t":"猶大出去後，耶穌說：「如今人子得了榮耀，神在人子身上也得了榮耀。","notes":[],"heads":["新的命令"]},{"n":32,"t":"如果神因人子得了榮耀，神也要因自己榮耀人子，並且要立刻榮耀他。","notes":["有古卷沒有「如果…得了榮耀」。"]},{"n":33,"t":"孩子們！我與你們同在的時候不多了；你們會找我，但我所去的地方，你們不能去。這話我曾對猶太人說過，現在也照樣對你們說。","notes":[]},{"n":34,"t":"我賜給你們一條新命令，乃是叫你們彼此相愛；我怎樣愛你們，你們也要怎樣彼此相愛。","notes":[]},{"n":35,"t":"你們若彼此相愛，眾人因此就認出你們是我的門徒了。」","notes":[]},{"n":36,"t":"西門‧彼得問耶穌：「主啊，你去哪裏？」耶穌回答：「我所去的地方，你現在不能跟我去，以後卻要跟我去。」","notes":[],"heads":["預言彼得不認主"]},{"n":37,"t":"彼得對他說：「主啊，為甚麼我現在不能跟你去？我願意為你捨命。」","notes":[]},{"n":38,"t":"耶穌回答：「你願意為我捨命嗎？我實實在在地告訴你，雞叫以前，你要三次不認我。」","notes":[]}]},"14":{"heading":"耶穌是道路、真理、生命","verses":[{"n":1,"t":"「你們心裏不要憂愁；你們信神，也當信我。","notes":[]},{"n":2,"t":"在我父的家裏有許多住處；若是沒有，我就早已告訴你們了。我去原是為你們預備地方去。","notes":["「若是沒有…預備地方去。」或譯「若是沒有，我會告訴你們，我去是為你們預備地方嗎？」"]},{"n":3,"t":"我若去為你們預備了地方，就必再來接你們到我那裏去，我在哪裏，叫你們也在哪裏。","notes":[]},{"n":4,"t":"我往哪裏去，你們知道那條路。」","notes":[]},{"n":5,"t":"多馬對他說：「主啊，我們不知道你去哪裏，怎麼能知道那條路呢？」","notes":[]},{"n":6,"t":"耶穌對他說：「我就是道路、真理、生命；若不藉著我，沒有人能到父那裏去。","notes":[]},{"n":7,"t":"既然你們認識了我，也會認識我的父。從今以後，你們就認識他，並且已經看見他了。」","notes":[]},{"n":8,"t":"腓力對他說：「主啊，將父顯給我們看，我們就知足了。」","notes":[]},{"n":9,"t":"耶穌對他說：「腓力，我與你們在一起這麼久了，你還不認識我嗎？看見我的就是看見了父，你怎麼還說『將父顯給我們看』呢？","notes":[]},{"n":10,"t":"我在父裏面，父在我裏面，你不信嗎？我對你們所說的話不是憑著自己說的，而是住在我裏面的父在做他的工作。","notes":[]},{"n":11,"t":"你們要信我，我在父裏面，父在我裏面；即使不信，也要因我所做的工作信我。","notes":[]},{"n":12,"t":"我實實在在地告訴你們，我所做的工作，信我的人也要做，並且要做得比這些更大，因為我到父那裏去。","notes":[]},{"n":13,"t":"你們奉我的名無論求甚麼，我必成全，為了使父因兒子得榮耀。","notes":[]},{"n":14,"t":"你們若奉我的名向我求甚麼，我必成全。」","notes":[]},{"n":15,"t":"「你們若愛我，就會遵守我的命令。","notes":[],"heads":["應許賜聖靈"]},{"n":16,"t":"我要求父，父就賜給你們另外一位保惠師，使他永遠與你們同在。","notes":["「保惠師」或譯「勸慰者」﹔26節，15．26，16．7同。"]},{"n":17,"t":"他就是真理的靈，是世人不能接受的。因為他們既看不見他，也不認識他；你們卻認識他，因他常與你們同在，也要在你們裏面。","notes":[]},{"n":18,"t":"我不會撇下你們為孤兒，我必到你們這裏來。","notes":[]},{"n":19,"t":"再過不久，世人不再看見我，你們卻會看見我，因為我活著，你們也要活著。","notes":[]},{"n":20,"t":"到那日，你們就會知道我在父裏面，你們在我裏面，我也在你們裏面。","notes":[]},{"n":21,"t":"有了我的命令而又遵守的人，就是愛我的；愛我的人，我父要愛他，我也要愛他，並且要親自向他顯現。」","notes":[]},{"n":22,"t":"猶大（不是加略人猶大）問耶穌：「主啊，為甚麼親自向我們顯現，而不向世人顯現呢？」","notes":[]},{"n":23,"t":"耶穌回答他說：「凡愛我的人就會遵守我的道，我父也會愛他，並且我們要到他那裏去，與他同住。","notes":[]},{"n":24,"t":"不愛我的人就不遵守我的道。你們所聽見的道不是我的，而是差我來之父的。","notes":[]},{"n":25,"t":"「我還與你們在一起的時候，已對你們說了這些事。","notes":[]},{"n":26,"t":"但保惠師，就是父因我的名所要差來的聖靈，他要把一切的事教導你們，並且要使你們想起我對你們所說的一切話。","notes":[]},{"n":27,"t":"我留下平安給你們，我把我的平安賜給你們。我所賜給你們的，不像世人所賜的。你們心裏不要憂愁，也不要膽怯。","notes":[]},{"n":28,"t":"你們聽見我對你們說過，我去了還要回到你們這裏來。你們若愛我，就會因我到父那裏去而喜樂，因為父比我大。","notes":[]},{"n":29,"t":"現在事情還沒有發生，我預先告訴你們，使你們在事情發生的時候會信。","notes":[]},{"n":30,"t":"我不再和你們多說了，因為這世界的統治者將到，他在我身上一無所能。","notes":[]},{"n":31,"t":"我這麼做是照著父命令我的，為了讓世人知道我愛父。起來，我們走吧！」","notes":[]}]},"15":{"heading":"耶穌是真葡萄樹","verses":[{"n":1,"t":"「我就是真葡萄樹，我父是栽培的人。","notes":[]},{"n":2,"t":"凡屬我不結果子的枝子，他就剪掉；凡結果子的，他就修剪乾淨，使枝子結果子更多。","notes":[]},{"n":3,"t":"現在你們因我講給你們的道已經潔淨了。","notes":[]},{"n":4,"t":"你們要常在我裏面，我也常在你們裏面。枝子若不常在葡萄樹上，自己就不能結果子；你們若不常在我裏面，也是這樣。","notes":[]},{"n":5,"t":"我就是葡萄樹，你們是枝子。常在我裏面的，我也常在他裏面，這人就多結果子，因為離了我，你們就不能做甚麼。","notes":[]},{"n":6,"t":"人若不常在我裏面，就像枝子被丟在外面，枯乾了，人撿起來，扔進火裏燒了。","notes":[]},{"n":7,"t":"你們若常在我裏面，我的話也常在你們裏面，凡你們想要的，祈求，就給你們成全。","notes":[]},{"n":8,"t":"你們多結果子，我父就因此得榮耀，你們也就是我的門徒了。","notes":["「是」：有古卷是「成為」。"]},{"n":9,"t":"我愛你們，正如父愛我一樣；你們要常在我的愛裏。","notes":[]},{"n":10,"t":"你們若遵守我的命令，就會常在我的愛裏，正如我遵守了我父的命令，常在他的愛裏。","notes":[]},{"n":11,"t":"「我已對你們說了這些事，是要讓我的喜樂存在你們心裏，並讓你們的喜樂得以滿足。","notes":[]},{"n":12,"t":"你們要彼此相愛，像我愛你們一樣，這是我的命令。","notes":[]},{"n":13,"t":"人為朋友捨命，人的愛心沒有比這個更大的了。","notes":[]},{"n":14,"t":"你們若遵行我所命令的，就是我的朋友。","notes":[]},{"n":15,"t":"以後我不再稱你們為僕人，因為僕人不知道主人所做的事；但我稱你們為朋友，因為我從我父所聽見的一切都已經讓你們知道了。","notes":[]},{"n":16,"t":"不是你們揀選了我，而是我揀選了你們，並且派你們去結果子，讓你們的果子得以長存，好使你們奉我的名，無論向父求甚麼，他會賜給你們。","notes":[]},{"n":17,"t":"我這樣命令你們，是要你們彼此相愛。」","notes":[]},{"n":18,"t":"「世人若恨你們，你們要知道，他們在恨你們以前已經恨我了。","notes":[],"heads":["世人的憎恨"]},{"n":19,"t":"你們若屬世界，世界會愛屬自己的；只因你們不屬世界，而是我從世界中揀選了你們，所以世界就恨你們。","notes":[]},{"n":20,"t":"你們要記得我對你們說過的話：『僕人不大於主人。』他們若迫害了我，也會迫害你們，他們若遵守了我的話，也會遵守你們的話。","notes":[]},{"n":21,"t":"但他們要因我的名向你們做這一切的事，因為他們不認識差我來的那位。","notes":[]},{"n":22,"t":"我若沒有來教導他們，他們就沒有罪；但如今他們的罪無可推諉了。","notes":[]},{"n":23,"t":"恨我的也恨我的父。","notes":[]},{"n":24,"t":"我若沒有在他們中間做過別人未曾做的事，他們就沒有罪；但如今連我與我的父，他們也看見了，也恨惡了。","notes":[]},{"n":25,"t":"這是要應驗他們律法上所寫的話：『他們無故地恨我。』","notes":[]},{"n":26,"t":"「但我要從父那裏差保惠師來，就是從父出來的那真理的靈，他來的時候要為我作見證。","notes":[]},{"n":27,"t":"你們也要作見證，因為你們從起初就與我同在。」","notes":[]}]},"16":{"heading":"聖靈的工作","verses":[{"n":1,"t":"「我對你們說了這些事，是要使你們不至於跌倒。","notes":[]},{"n":2,"t":"人要把你們趕出會堂，而且時候將到，凡殺你們的還以為是在事奉神。","notes":[]},{"n":3,"t":"他們這樣做，是因為沒有認識父，也沒有認識我。","notes":[]},{"n":4,"t":"我對你們說了這些事，是要在他們做這些事的時候，你們會想起我對你們說過的話。」「我起先沒有對你們說這些事，因為我一直與你們同在。","notes":[]},{"n":5,"t":"現在我要到差我來的父那裏去，你們中間卻沒有人問我『你去哪裏？』","notes":[]},{"n":6,"t":"只因我對你們說了這些事，你們就滿心憂愁。","notes":[]},{"n":7,"t":"然而，我把真情告訴你們，我去對你們是有益的。我若不去，保惠師就不會到你們這裏來；我若去，就差他到你們這裏來。","notes":[]},{"n":8,"t":"他來的時候，要為罪、為義，為審判，指證世人；","notes":[]},{"n":9,"t":"為罪，是因他們不信我；","notes":[]},{"n":10,"t":"為義，是因我到父那裏去，你們將不再見到我；","notes":[]},{"n":11,"t":"為審判，是因這世界的統治者已受了審判。","notes":[]},{"n":12,"t":"「我還有好些事要告訴你們，但你們現在擔當不了。","notes":["「擔當不了」或譯「不能領會」。"]},{"n":13,"t":"但真理的靈來的時候，他要引導你們進入一切真理。因為他不是憑著自己說的，而是把他所聽見的都說出來，並且要把將要來的事向你們傳達。","notes":[]},{"n":14,"t":"他要榮耀我，因為他要把從我領受的向你們傳達。","notes":[]},{"n":15,"t":"凡父所有的都是我的，所以我說，他要把從我領受的向你們傳達。」","notes":[]},{"n":16,"t":"「不久，你們將不再見到我；再過不久，你們還要見到我。」","notes":[],"heads":["憂愁變為喜樂"]},{"n":17,"t":"有幾個門徒彼此說：「他對我們說『不久，你們將不再見到我；再過不久，你們還要見到我』；又說『因我到父那裏去』。這是甚麼意思呢？」","notes":[]},{"n":18,"t":"於是門徒說：「他說『不久』到底是甚麼意思呢？我們不明白他說甚麼。」","notes":["有古卷沒有「他說」。"]},{"n":19,"t":"耶穌看出他們要問他，就對他們說：「我說『不久，你們將不再見到我；再過不久，你們還要見到我』，你們為這話彼此詢問嗎？","notes":[]},{"n":20,"t":"我實實在在地告訴你們，你們將要痛哭，哀號，世人反要歡喜。你們將要憂愁，然而你們的憂愁要變成喜樂。","notes":[]},{"n":21,"t":"婦人生產的時候會憂愁，因為她的時候到了；但孩子一生出來，就不再記得那痛苦了，因為歡喜有一個人生在世上了。","notes":[]},{"n":22,"t":"你們現在也是憂愁，但我要再見到你們，你們的心就會有喜樂了；這喜樂沒有人能奪去。","notes":[]},{"n":23,"t":"到那日，你們甚麼也不會問我了。我實實在在地告訴你們，你們奉我的名無論向父求甚麼，他會賜給你們。","notes":["「你們奉我的名…賜給你們」：有古卷是「你們若向父求甚麼，他會因我的名賜給你們」。"]},{"n":24,"t":"直到現在，你們沒有奉我的名求甚麼，如今你們求就必得著，使你們的喜樂得以滿足。」","notes":[]},{"n":25,"t":"「這些事，我是用比方對你們說的；時候將到，我不再用比方對你們說，而是要把父的事明白地告訴你們。","notes":[],"heads":["我已經勝過世界"]},{"n":26,"t":"到那日，你們要奉我的名祈求；我並不對你們說，我要為你們向父祈求。","notes":[]},{"n":27,"t":"父自己愛你們，因為你們已經愛我，又信我是從神而來的。","notes":["「神」：有古卷是「父」。"]},{"n":28,"t":"我從父而來，到了世界，又離開世界，到父那裏去。」","notes":["「我從…世界」：有古卷是「我到了世界」。"]},{"n":29,"t":"門徒說：「你看，如今你是明說，不用比方了。","notes":[]},{"n":30,"t":"現在我們曉得你凡事都知道，也不需要有人問你；從此我們信你是從神而來的。」","notes":[]},{"n":31,"t":"耶穌回答他們：「現在你們信了嗎？","notes":[]},{"n":32,"t":"看哪，時候將到，其實已經到了，你們要分散，各歸自己的地方，留下我獨自一人；然而我不是獨自一人，因為有父與我同在。","notes":[]},{"n":33,"t":"我對你們說了這些事，是要使你們在我裏面有平安。在世上你們有苦難，但你們要有勇氣，我已經勝過世界。」","notes":["「但你們要有勇氣」或譯「但你們放心」。"]}]},"17":{"heading":"耶穌的禱告","verses":[{"n":1,"t":"耶穌說了這些話，就舉目望天，說：「父啊，時候到了，願你榮耀你的兒子，使兒子也榮耀你；","notes":[]},{"n":2,"t":"因為你曾賜給他權柄掌管凡血肉之軀的，使他把永生賜給你所賜給他的人。","notes":[]},{"n":3,"t":"認識你—獨一的真神，並且認識你所差來的耶穌基督，這就是永生。","notes":[]},{"n":4,"t":"我在地上已經榮耀你，你交給我做的工作，我已完成了。","notes":[]},{"n":5,"t":"父啊，現在求你使我在你面前得榮耀，就是在未有世界以前，我同你享有的榮耀。","notes":[]},{"n":6,"t":"「你從世上賜給我的人，我已把你的名顯明給他們。他們本是你的，你把他們賜給我，他們也遵守了你的道。","notes":[]},{"n":7,"t":"現在他們知道，你所賜給我的一切都是從你那裏來的；","notes":[]},{"n":8,"t":"因為你所賜給我的話，我已經賜給他們，他們也領受了，又確實知道，我是從你出來的，並且信你差了我來。","notes":[]},{"n":9,"t":"我為他們祈求，不為世人祈求，卻為你所賜給我的人祈求，因他們本是你的。","notes":[]},{"n":10,"t":"凡是我的都是你的，你的也是我的，並且我因他們得了榮耀。","notes":[]},{"n":11,"t":"我到你那裏去；我不再留在世上，他們卻在世上。聖父啊，求你因你的名，就是你所賜給我的名，保守他們，使他們像我們一樣合而為一。","notes":[]},{"n":12,"t":"我與他們同在的時候，我奉你的名，就是你所賜給我的名，保守了他們，我也護衛了他們；其中除了那滅亡之子，沒有一個滅亡的，好使經上的話得以應驗。","notes":[]},{"n":13,"t":"現在我到你那裏去，我在世上說這些話，是要他們心裏充滿了我的喜樂。","notes":[]},{"n":14,"t":"我已把你的道賜給他們；世界恨他們，因為他們不屬世界，正如我不屬世界一樣。","notes":[]},{"n":15,"t":"我不求你把他們從世上接走，只求你保全他們，使他們脫離那惡者。","notes":[]},{"n":16,"t":"他們不屬世界，正如我不屬世界一樣。","notes":[]},{"n":17,"t":"求你用真理使他們成聖；你的道就是真理。","notes":[]},{"n":18,"t":"你怎樣差我到世上，我也照樣差他們到世上。","notes":[]},{"n":19,"t":"我為他們的緣故使自己分別為聖，為要使他們也因真理成聖。","notes":[]},{"n":20,"t":"「我不但為這些人祈求，也為那些藉著他們的話信我的人祈求，","notes":[]},{"n":21,"t":"使他們都合而為一。正如父你在我裏面，我在你裏面，使他們也在我們裏面，好讓世人信是你差我來的。","notes":[]},{"n":22,"t":"你所賜給我的榮耀，我已賜給他們，使他們合而為一，像我們合而為一。","notes":[]},{"n":23,"t":"我在他們裏面，你在我裏面，使他們完完全全合而為一，讓世人知道是你差我來的，也知道你愛他們，如同愛我一樣。","notes":[]},{"n":24,"t":"父啊，我在哪裏，願你所賜給我的人也同我在哪裏，使他們看見你所賜給我的榮耀，因為創世以前，你已經愛我了。","notes":[]},{"n":25,"t":"公義的父啊，世人未曾認識你，我卻認識你，這些人也知道是你差我來的。","notes":[]},{"n":26,"t":"我已讓他們認識你的名，還要讓他們認識，好讓你愛我的愛在他們裏面，我也在他們裏面。」","notes":[]}]},"18":{"heading":"耶穌被捕","verses":[{"n":1,"t":"耶穌說了這些話，就同門徒出去，過了汲淪溪。在那裏有一個園子，他和門徒進去了。","notes":[]},{"n":2,"t":"出賣耶穌的猶大也知道那地方，因為耶穌和門徒屢次在那裏聚集。","notes":[]},{"n":3,"t":"猶大領了一隊兵，以及祭司長和法利賽人的聖殿警衛，拿著燈籠、火把和兵器來到園裏。","notes":[]},{"n":4,"t":"耶穌知道將要臨到自己的一切事，就出來對他們說：「你們找誰？」","notes":[]},{"n":5,"t":"他們回答他：「拿撒勒人耶穌。」耶穌對他們說：「我就是。」出賣他的猶大也同他們站在一起。","notes":[]},{"n":6,"t":"耶穌一對他們說「我就是」，他們就退後，倒在地上。","notes":[]},{"n":7,"t":"他又問他們：「你們找誰？」他們說：「拿撒勒人耶穌。」","notes":[]},{"n":8,"t":"耶穌回答：「我已經告訴你們，我就是。你們若找的是我，就讓這些人走吧。」","notes":[]},{"n":9,"t":"這要應驗耶穌說過的話：「你所賜給我的人，我一個也不失落。」","notes":[]},{"n":10,"t":"西門‧彼得帶著一把刀，就拔出來，把大祭司的僕人砍了一刀，削掉了他的右耳，那僕人名叫馬勒古。","notes":[]},{"n":11,"t":"於是耶穌對彼得說：「收刀入鞘吧！我父給我的杯，我豈可不喝呢？」","notes":[]},{"n":12,"t":"那隊兵、千夫長和猶太人的警衛拿住耶穌，把他捆綁了，","notes":[],"heads":["耶穌被帶到亞那面前"]},{"n":13,"t":"先帶到亞那面前，因為他是那年的大祭司該亞法的岳父。","notes":[]},{"n":14,"t":"這該亞法就是從前向猶太人忠告說「一個人替百姓死是有利的」那個人。","notes":[]},{"n":15,"t":"西門‧彼得跟著耶穌，另一個門徒也跟著；那門徒是大祭司所認識的，他就同耶穌進了大祭司的院子。","notes":[],"heads":["彼得不認耶穌"]},{"n":16,"t":"彼得卻站在門外。大祭司所認識的那個門徒出來，對看門的使女說了一聲，就領彼得進去。","notes":[]},{"n":17,"t":"那看門的使女對彼得說：「你不也是這人的門徒嗎？」他說：「我不是。」","notes":[]},{"n":18,"t":"僕人和警衛因為天冷生了炭火，站在那裏取暖；彼得也同他們站著取暖。","notes":[]},{"n":19,"t":"於是，大祭司盤問耶穌有關他的門徒和他教導的事。","notes":[],"heads":["大祭司盤問耶穌"]},{"n":20,"t":"耶穌回答他：「我一向都是公開地對世人講話，我常在會堂和聖殿裏，就是猶太人聚集的地方教導人，我私下並沒有講甚麼。","notes":[]},{"n":21,"t":"你為甚麼問我呢？去問那些聽過我講話的人，我所說的，他們都知道。」","notes":[]},{"n":22,"t":"耶穌說了這些話，旁邊站著的一個警衛打了他一耳光，說：「你這樣回答大祭司嗎？」","notes":[]},{"n":23,"t":"耶穌回答他：「假如我說的不對，你指證不對的地方；假如我說的對，你為甚麼打我呢？」","notes":[]},{"n":24,"t":"於是亞那把耶穌綁著押解到大祭司該亞法那裏。","notes":[]},{"n":25,"t":"西門‧彼得正站著取暖，有人對他說：「你不也是他的門徒嗎？」彼得不承認，說：「我不是。」","notes":[],"heads":["彼得再次不認耶穌"]},{"n":26,"t":"大祭司的一個僕人，是被彼得削掉耳朵那人的親屬，說：「我不是看見你同他在園子裏嗎？」","notes":[]},{"n":27,"t":"彼得又不承認，立刻雞就叫了。","notes":[]},{"n":28,"t":"他們把耶穌從該亞法那裏押解到總督府。那時是清早。他們自己卻不進總督府，恐怕染了污穢，不能吃逾越節的宴席。","notes":[],"heads":["耶穌在彼拉多面前受審"]},{"n":29,"t":"於是彼拉多出來，到他們那裏，說：「你們告這人是為甚麼事呢？」","notes":[]},{"n":30,"t":"他們回答他說：「這人若不作惡，我們就不會把他交給你了。」","notes":[]},{"n":31,"t":"彼拉多對他們說：「你們自己帶他去，按著你們的律法問他吧！」猶太人說：「我們沒有殺人的權柄。」","notes":[]},{"n":32,"t":"這是要應驗耶穌所說，指自己將要怎樣死的話。","notes":[]},{"n":33,"t":"於是彼拉多又進了總督府，叫耶穌來，對他說：「你是猶太人的王嗎？」","notes":[]},{"n":34,"t":"耶穌回答：「這話是你說的，還是別人論到我時對你說的呢？」","notes":[]},{"n":35,"t":"彼拉多回答：「難道我是猶太人嗎？你的同胞和祭司長把你交給我。你做了甚麼事呢？」","notes":[]},{"n":36,"t":"耶穌回答：「我的國不屬於這世界；我的國若屬於這世界，我的部下就會為我戰鬥，使我不至於被交給猶太人。只是我的國不屬於這世界。」","notes":[]},{"n":37,"t":"於是彼拉多對他說：「那麼，你是王了？」耶穌回答：「是你說我是王。我為此而生，也為此來到世界，為了給真理作見證。凡屬真理的人都聽我的話。」","notes":[]},{"n":38,"t":"彼拉多對他說：「真理是甚麼呢？」說了這話，彼拉多又出來到猶太人那裏，對他們說：「我查不出他有甚麼罪狀。","notes":[]},{"n":39,"t":"但你們有個規矩，在逾越節要我給你們釋放一個人，你們要我給你們釋放這猶太人的王嗎？」","notes":[]},{"n":40,"t":"他們又再喊著說：「不要這人！要巴拉巴！」這巴拉巴是個強盜。","notes":[]}]},"19":{"heading":"耶穌被釘十字架","verses":[{"n":1,"t":"於是，彼拉多命令把耶穌帶去鞭打了。","notes":[]},{"n":2,"t":"士兵用荊棘編了冠冕，戴在他頭上，給他穿上紫袍，","notes":[]},{"n":3,"t":"又走到他面前，說：「萬歲，猶太人的王！」他們就打他耳光。","notes":[]},{"n":4,"t":"彼拉多又出來對眾人說：「看，我帶他出來見你們，讓你們知道我查不出他有甚麼罪狀。」","notes":[]},{"n":5,"t":"耶穌出來，戴著荊棘冠冕，穿著紫袍。彼拉多對他們說：「看哪，這個人！」","notes":[]},{"n":6,"t":"祭司長和聖殿警衛看見他，就喊著說：「釘十字架！釘十字架！」彼拉多對他們說：「你們自己把他帶去釘十字架吧！我查不出他有甚麼罪狀。」","notes":[]},{"n":7,"t":"猶太人回答他：「我們有律法，按照律法，他是該死的，因為他自以為是神的兒子。」","notes":[]},{"n":8,"t":"彼拉多聽見這話，越發害怕，","notes":[]},{"n":9,"t":"又進了總督府，對耶穌說：「你是哪裏來的？」耶穌卻不回答。","notes":[]},{"n":10,"t":"於是彼拉多對他說：「你不對我說話嗎？難道你不知道我有權柄釋放你，也有權柄把你釘十字架嗎？」","notes":[]},{"n":11,"t":"耶穌回答他：「若不是從上頭賜給你的，你就毫無權柄辦我，所以，把我交給你的那人罪更重了。」","notes":[]},{"n":12,"t":"從此，彼拉多想要釋放耶穌，無奈猶太人喊著說：「你若釋放這個人，你就不是凱撒的忠臣。凡自立為王的就是背叛凱撒。」","notes":["「忠臣」：原文直譯「朋友」。"]},{"n":13,"t":"彼拉多聽見這些話，就帶耶穌出來，到了一個地方，叫「鋪華石處」，希伯來話叫厄巴大，就在那裏坐堂。","notes":[]},{"n":14,"t":"那日是逾越節的預備日，約在正午。彼拉多對猶太人說：「看哪，你們的王！」","notes":[]},{"n":15,"t":"他們就喊著：「除掉他！除掉他！把他釘十字架！」彼拉多對他們說：「要我把你們的王釘十字架嗎？」祭司長回答：「除了凱撒，我們沒有王。」","notes":[]},{"n":16,"t":"於是彼拉多把耶穌交給他們去釘十字架。他們就把耶穌帶了去。","notes":[]},{"n":17,"t":"耶穌背著自己的十字架出來，到了一個地方，名叫「髑髏地」，希伯來話叫各各他。","notes":[]},{"n":18,"t":"他們就在那裏把他釘在十字架上，還有兩個人和他一同被釘，一邊一個，耶穌在中間。","notes":[]},{"n":19,"t":"彼拉多又寫了一個牌子，釘在十字架上，寫的是：「猶太人的王，拿撒勒人耶穌。」","notes":[]},{"n":20,"t":"有許多猶太人念這牌子，因為耶穌被釘十字架的地方靠近城，而且牌子是用希伯來、羅馬、希臘三種文字寫的。","notes":[]},{"n":21,"t":"猶太人的祭司長就對彼拉多說：「不要寫『猶太人的王』，要寫『那人說：我是猶太人的王』。」","notes":[]},{"n":22,"t":"彼拉多回答：「我寫了就寫了。」","notes":[]},{"n":23,"t":"士兵把耶穌釘在十字架上以後，把他的衣服拿來分為四份，每人一份。他們又拿他的內衣，這件內衣沒有縫，是上下一片織成的。","notes":[]},{"n":24,"t":"他們就彼此說：「我們不要撕開，我們抽籤，看是誰的。」這要應驗經上的話說：「他們分了我的外衣，為我的內衣抽籤。」士兵果然做了這些事。","notes":[]},{"n":25,"t":"站在耶穌十字架旁邊的，有他的母親、姨母、革羅罷的妻子馬利亞，和抹大拉的馬利亞。","notes":[]},{"n":26,"t":"耶穌見母親和他所愛的那門徒站在旁邊，就對母親說：「母親，看，你的兒子！」","notes":["「母親」：原文直譯「婦人」。"]},{"n":27,"t":"又對那門徒說：「看，你的母親！」從那刻起，那門徒就接她到自己家裏去了。","notes":[]},{"n":28,"t":"這事以後，耶穌知道各樣的事已經成了，為使經上的話應驗，就說：「我渴了。」","notes":[],"heads":["耶穌之死"]},{"n":29,"t":"有一個盛滿了醋的罐子放在那裏，他們就拿海綿蘸滿了醋，綁在牛膝草上，送到他嘴邊。","notes":[]},{"n":30,"t":"耶穌嘗了那醋，說：「成了！」就低下頭，斷了氣。","notes":["「斷了氣」或譯「交上了靈」。"]},{"n":31,"t":"因為這日是預備日，又因為那安息日是個大日子，猶太人就來求彼拉多叫人打斷他們的腿，把他們搬走，免得屍首在安息日留在十字架上。","notes":[],"heads":["耶穌的肋旁被刺"]},{"n":32,"t":"於是士兵來，把第一個人的腿，和與耶穌同釘的另一個人的腿，都打斷了。","notes":[]},{"n":33,"t":"當他們來到耶穌那裏，見他已經死了，就沒有打斷他的腿。","notes":[]},{"n":34,"t":"然而有一個士兵拿槍扎他的肋旁，立刻有血和水流出來。","notes":[]},{"n":35,"t":"看見這事的人作了見證—他的見證是真的，他知道自己所說的是真的—好讓你們也信。","notes":[]},{"n":36,"t":"這些事發生，為要應驗經上的話：「他的骨頭一根也不可折斷。」","notes":[]},{"n":37,"t":"另有經文也說：「他們要仰望自己所扎的人。」","notes":[]},{"n":38,"t":"這些事以後，亞利馬太的約瑟來求彼拉多，要把耶穌的身體領去。他是耶穌的門徒，只因怕猶太人，就暗地裏作門徒。彼拉多准許了，他就把耶穌的身體領走。","notes":[],"heads":["耶穌的安葬"]},{"n":39,"t":"尼哥德慕也來了，就是先前夜裏去見耶穌的那位，他帶著約一百斤的沒藥和沉香。","notes":[]},{"n":40,"t":"他們照猶太人喪葬的規矩，用細麻布加上香料，把耶穌的身體裹好了。","notes":[]},{"n":41,"t":"在耶穌釘十字架的地方有一個園子，園子裏有一座新墓穴，是從來沒有葬過人的。","notes":[]},{"n":42,"t":"因為那天是猶太人的預備日，而那墳墓又在附近，他們就把耶穌安放在那裏。","notes":[]}]},"20":{"heading":"耶穌復活","verses":[{"n":1,"t":"七日的第一日清早，天還黑的時候，抹大拉的馬利亞來到墳墓，看見石頭已從墳墓挪開了，","notes":[]},{"n":2,"t":"就跑來見西門‧彼得和耶穌所愛的那個門徒，對他們說：「有人從墳墓裏把主移走了，我們不知道他們把他放在哪裏。」","notes":[]},{"n":3,"t":"彼得和那門徒就出來，往墳墓去。","notes":[]},{"n":4,"t":"兩個人同跑，那門徒比彼得跑得快，先到了墳墓，","notes":[]},{"n":5,"t":"低頭往裏看，看見細麻布還放在那裏，只是沒有進去。","notes":[]},{"n":6,"t":"西門‧彼得隨後也到了，進了墳墓，看見細麻布放在那裏，","notes":[]},{"n":7,"t":"又看見耶穌的裹頭巾沒有和細麻布放在一起，是另在一處捲著。","notes":[]},{"n":8,"t":"然後先到墳墓的那門徒也進去，他看見就信了。","notes":[]},{"n":9,"t":"他們還不明白聖經所說耶穌必須從死人中復活的意思。","notes":[]},{"n":10,"t":"於是兩個門徒回自己的住處去了。","notes":[]},{"n":11,"t":"馬利亞卻站在墳墓外面哭。她哭的時候，低頭往墳墓裏看，","notes":[],"heads":["向抹大拉的馬利亞顯現"]},{"n":12,"t":"看見兩個天使穿著白衣，在安放耶穌身體的地方坐著，一個在頭，一個在腳。","notes":[]},{"n":13,"t":"天使對她說：「婦人，你為甚麼哭？」她對他們說：「因為有人把我主移走了，我不知道他們把他放在哪裏。」","notes":[]},{"n":14,"t":"說了這些話，她轉過身來，看見耶穌站在那裏，卻不知道他是耶穌。","notes":[]},{"n":15,"t":"耶穌問她：「婦人，你為甚麼哭？你找誰？」馬利亞以為他是看園子的，就對他說：「先生，若是你把他移了去，請告訴我，你把他放在哪裏，我去把他移回來。」","notes":[]},{"n":16,"t":"耶穌對她說：「馬利亞。」馬利亞轉過身來，用希伯來話對他說：「拉波尼！」（「拉波尼」就是老師的意思。）","notes":[]},{"n":17,"t":"耶穌對她說：「不要拉住我，因為我還沒有升上去見我的父。你到我弟兄那裏去告訴他們，我要升上去見我的父，也是你們的父，見我的神，也是你們的神。」","notes":[]},{"n":18,"t":"抹大拉的馬利亞就向門徒報信：「我已經看見了主。」她又把主對她說的話告訴他們。","notes":[]},{"n":19,"t":"那日（就是七日的第一日）晚上，門徒因怕猶太人，所在的地方門都關了。耶穌來，站在當中，對他們說：「願你們平安！」","notes":[],"heads":["向門徒顯現"]},{"n":20,"t":"說了這話，他把手和肋旁給他們看。門徒一看見主就喜樂了。","notes":[]},{"n":21,"t":"於是耶穌又對他們說：「願你們平安！父怎樣差遣了我，我也照樣差遣你們。」","notes":[]},{"n":22,"t":"說了這話，他向他們吹一口氣，說：「領受聖靈吧！","notes":[]},{"n":23,"t":"你們赦免誰的罪，誰的罪就得赦免；你們不赦免誰的罪，誰的罪就不得赦免。」","notes":[]},{"n":24,"t":"那十二使徒中，有個叫低土馬的多馬，耶穌來的時候，他沒有和他們在一起。","notes":[],"heads":["耶穌和多馬"]},{"n":25,"t":"其他的門徒就對他說：「我們已經看見主了。」多馬卻對他們說：「除非我看見他手上的釘痕，用我的指頭探入那釘痕，用我的手探入他的肋旁，我絕不信。」","notes":[]},{"n":26,"t":"過了八日，門徒又在屋裏，多馬也和他們在一起。門都關了，耶穌來，站在當中，說：「願你們平安！」","notes":[]},{"n":27,"t":"然後他對多馬說：「把你的指頭伸到這裏來，看看我的手；把你的手伸過來，探入我的肋旁。不要疑惑，總要信！」","notes":[]},{"n":28,"t":"多馬回答，對他說：「我的主！我的神！」","notes":[]},{"n":29,"t":"耶穌對他說：「你因為看見了我才信嗎？那沒有看見卻信的有福了。」","notes":[]},{"n":30,"t":"耶穌在他門徒面前另外行了許多神蹟，沒有記錄在這書上。","notes":[],"heads":["本書的目的"]},{"n":31,"t":"但記載這些事是要使你們信耶穌是基督，是神的兒子，並且使你們信他，好因著他的名得生命。","notes":["「使你們信」：有古卷是「使你們繼續信」。"]}]},"21":{"heading":"耶穌向七個門徒顯現","verses":[{"n":1,"t":"這些事以後，耶穌在提比哩亞海邊又向門徒顯現。他怎樣顯現記在下面。","notes":[]},{"n":2,"t":"西門‧彼得、叫低土馬的多馬、加利利的迦拿人拿但業、西庇太的兩個兒子，和另外兩個門徒，都在一起。","notes":[]},{"n":3,"t":"西門‧彼得對他們說：「我打魚去。」他們對他說：「我們也和你一起去。」他們就出去，上了船；那一夜並沒有打著甚麼。","notes":[]},{"n":4,"t":"天剛亮的時候，耶穌站在岸上，門徒卻不知道他是耶穌。","notes":[]},{"n":5,"t":"耶穌就對他們說：「孩子們！你們有吃的沒有？」他們回答他：「沒有。」","notes":[]},{"n":6,"t":"耶穌對他們說：「你們把網撒在船的右邊，就會得到。」於是他們撒下網去，竟拉不上來了，因為魚很多。","notes":[]},{"n":7,"t":"耶穌所愛的那門徒對彼得說：「是主！」那時西門‧彼得赤著身子，一聽見是主，就束上外衣，跳進海裏。","notes":[]},{"n":8,"t":"其餘的門徒因離岸不遠，約有二百肘，就坐著小船把那網魚拉過來。","notes":[]},{"n":9,"t":"他們上了岸，看見那裏有炭火，上面有魚和餅。","notes":[]},{"n":10,"t":"耶穌對他們說：「把剛才打的魚拿幾條來。」","notes":[]},{"n":11,"t":"西門‧彼得就上船，把網拉到岸上，網裏滿了大魚，共一百五十三條；雖然魚這樣多，網卻沒有破。","notes":[]},{"n":12,"t":"耶穌對他們說：「你們來吃早飯。」門徒中沒有一個敢問他：「你是誰？」因為他們知道他是主。","notes":[]},{"n":13,"t":"耶穌走過來，拿餅給他們，也照樣拿魚給他們。","notes":[]},{"n":14,"t":"耶穌從死人中復活後向門徒顯現，這是第三次。","notes":[]},{"n":15,"t":"他們吃完了早飯，耶穌對西門‧彼得說：「約翰的兒子西門，你愛我比這些更深嗎？」彼得對他說：「主啊，是的，你知道我愛你。」耶穌說：「你餵養我的小羊。」","notes":["「約翰」在馬太福音16．17稱為「約拿」。"],"heads":["三問彼得"]},{"n":16,"t":"耶穌第二次又對他說：「約翰的兒子西門，你愛我嗎？」彼得對他說：「主啊，是的，你知道我愛你。」耶穌說：「你牧養我的羊。」","notes":[]},{"n":17,"t":"耶穌第三次對他說：「約翰的兒子西門，你愛我嗎？」彼得因為耶穌第三次對他說「你愛我嗎」，就憂愁，對耶穌說：「主啊，你無所不知，你知道我愛你。」耶穌說：「你餵養我的羊。","notes":[]},{"n":18,"t":"我實實在在地告訴你，你年輕的時候，自己束上帶子，隨意往來；但年老的時候，你要伸出手來，別人要把你束上，帶你到不願意去的地方。」","notes":[]},{"n":19,"t":"耶穌說這話，是指彼得會怎樣死來榮耀神。說了這話，耶穌對他說：「你跟從我吧！」","notes":[]},{"n":20,"t":"彼得轉過身來，看見耶穌所愛的那門徒跟著，就是在晚餐時靠著耶穌胸膛說「主啊，出賣你的是誰」的那門徒。","notes":[],"heads":["耶穌和他所愛的那門徒"]},{"n":21,"t":"彼得看見他，就問耶穌：「主啊，這個人怎樣呢？」","notes":[]},{"n":22,"t":"耶穌對他說：「假如我要他等到我來的時候還在，跟你有甚麼關係呢？你跟從我吧！」","notes":[]},{"n":23,"t":"於是這話在弟兄中間流傳，說那門徒不死。其實，耶穌不是說他不死，而是對彼得說：「假如我要他等到我來的時候還在，跟你有甚麼關係呢？」","notes":["有古卷沒有「跟你有甚麼關係呢？」"]},{"n":24,"t":"這門徒就是為這些事作見證、並且記載這些事的，我們知道他的見證是真的。","notes":[]},{"n":25,"t":"耶穌所行的事還有許多，若是一一都寫出來，我想，就是全世界也容不下所要寫的書。","notes":[]}]}},"ACT":{"1":{"heading":"賜聖靈的應許","verses":[{"n":1,"t":"提阿非羅啊，我在第一本書中已論到耶穌從開頭所做和所教導的一切事，","notes":[]},{"n":2,"t":"直到他藉著聖靈吩咐所揀選的使徒後，被接上升的日子為止。","notes":[]},{"n":3,"t":"他受害以後，用許多確據向使徒顯明自己是活著的，在四十天之中向他們顯現，並講說神國的事。","notes":[]},{"n":4,"t":"耶穌和他們聚集的時候，囑咐他們說：「不要離開耶路撒冷，但要等候父的應許，就是你們聽見我說過的。","notes":[]},{"n":5,"t":"約翰是用水施洗，但過了不多幾天，你們要在聖靈裏受洗。」","notes":[]},{"n":6,"t":"他們聚集的時候，問耶穌：「主啊，你就要在這時候復興以色列國嗎？」","notes":[],"heads":["耶穌升天"]},{"n":7,"t":"耶穌對他們說：「父憑著自己的權柄所定的時候和日期，不是你們可以知道的。","notes":[]},{"n":8,"t":"但聖靈降臨在你們身上，你們就必得著能力，並要在耶路撒冷、猶太全地和撒瑪利亞，直到地極，作我的見證。」","notes":[]},{"n":9,"t":"說了這些話，他們正看的時候，他被接上升，有一朵雲彩從他們眼前把他接去。","notes":[]},{"n":10,"t":"他升上去的時候，他們定睛望天，看哪，有兩個人身穿白衣站在他們旁邊，","notes":[]},{"n":11,"t":"說：「加利利人哪，你們為甚麼站著望天呢？這離開你們被接升天的耶穌，你們見他怎樣升上天去，他也要怎樣來臨。」","notes":[]},{"n":12,"t":"有一座山，名叫橄欖山，離耶路撒冷不遠，有安息日可行走的路程。那時，門徒從那裏回耶路撒冷去，","notes":["「安息日…路程」：約二千肘或一公里。"],"heads":["接替猶大職分的人"]},{"n":13,"t":"他們一進城，就上了所住的樓房；在那裏有彼得、約翰、雅各、安得烈、腓力、多馬、巴多羅買、馬太、亞勒腓的兒子雅各、激進黨的西門，和雅各的兒子猶大。","notes":["「兒子」或譯「兄弟」。"]},{"n":14,"t":"這些人和幾個婦人，包括耶穌的母親馬利亞，和耶穌的兄弟，都同心合意地恆切禱告。","notes":[]},{"n":15,"t":"那時，有許多人聚會，約有一百二十名，彼得在弟兄中間站起來，說：","notes":[]},{"n":16,"t":"「諸位弟兄，聖經的話必須應驗。聖經中，聖靈曾藉大衛的口預先說到那領人來拿耶穌的猶大；","notes":[]},{"n":17,"t":"他本來算是我們中的一個，並且得了這一份使徒的職任。","notes":[]},{"n":18,"t":"這人用他不義的代價買了一塊田，以後身子仆倒，肚腹崩裂，腸子都流出來。","notes":[]},{"n":19,"t":"住在耶路撒冷的人都知道這事，所以按著他們當地的話把那塊田叫亞革大馬，就是「血田」的意思。","notes":[]},{"n":20,"t":"因為《詩篇》上寫著：「願他的住處變為廢墟，無人在內居住。」又說：「願別人得他的職分。」","notes":[]},{"n":21,"t":"所以，主耶穌在我們中間出入的整段時間，就是從約翰施洗起，直到主離開我們被接上升的日子為止，必須從那常與我們一起的人中，立一位與我們同作耶穌復活的見證。」","notes":[],"end":22},{"n":23,"t":"於是他們推舉兩個人，就是那叫巴撒巴，又稱為猶士都的約瑟，和馬提亞。","notes":[]},{"n":24,"t":"眾人禱告說：「主啊，你知道萬人的心，求你從這兩個人中指明你所揀選的是哪一位，","notes":[]},{"n":25,"t":"去得這使徒的職任；這職位猶大已經丟棄，往自己的地方去了。」","notes":[]},{"n":26,"t":"於是眾人為他們搖籤，搖出馬提亞來；他就和十一個使徒同列。","notes":[]}]},"2":{"heading":"聖靈降臨","verses":[{"n":1,"t":"五旬節那日到了，他們全都聚集在一起。","notes":[]},{"n":2,"t":"忽然，有響聲從天上下來，好像一陣大風吹過，充滿了他們所坐的整座屋子；","notes":[]},{"n":3,"t":"又有舌頭如火焰向他們顯現，分開落在他們每個人身上。","notes":[]},{"n":4,"t":"他們都被聖靈充滿，就按著聖靈所賜的口才說起別國的話來。","notes":[]},{"n":5,"t":"那時，有從天下各國來的虔誠的猶太人，住在耶路撒冷。","notes":[]},{"n":6,"t":"這聲音一響，許多人都來聚集，各人因為聽見門徒用他們各自的鄉談說話，就甚納悶，","notes":[]},{"n":7,"t":"都詫異驚奇說：「看哪，這些說話的不都是加利利人嗎？","notes":[]},{"n":8,"t":"我們每個人怎麼聽見他們說我們生來所用的鄉談呢？","notes":[]},{"n":9,"t":"我們帕提亞人、瑪代人、以攔人，和住在美索不達米亞、猶太、加帕多家、本都、亞細亞、","notes":[]},{"n":10,"t":"弗呂家、旁非利亞、埃及的人，並靠近古利奈的利比亞一帶地方的人，僑居的羅馬人，","notes":[]},{"n":11,"t":"包括猶太人和皈依猶太教的人， 克里特人和阿拉伯人，都聽見他們用我們的鄉談講論神的大作為。」","notes":[]},{"n":12,"t":"眾人就都驚奇困惑，彼此說：「這是甚麼意思呢？」","notes":[]},{"n":13,"t":"還有人譏誚，說：「他們是灌滿了新酒吧！」","notes":[]},{"n":14,"t":"彼得和十一個使徒站起來，他就高聲向眾人說：「猶太人和所有住在耶路撒冷的人哪，這件事你們要知道，要側耳聽我的話。","notes":[],"heads":["彼得在五旬節的演講"]},{"n":15,"t":"這些人並不像你們所想的喝醉了，因為現在才早晨九點鐘。","notes":[]},{"n":16,"t":"這正是藉著先知約珥所說的：","notes":[]},{"n":17,"t":"『神說：在末後的日子，我要將我的靈澆灌凡血肉之軀的。你們的兒女要說預言；你們的少年要見異象；你們的老人要做異夢。","notes":[]},{"n":18,"t":"在那些日子，我要把我的靈澆灌，甚至給我的僕人和婢女，他們要說預言。","notes":[]},{"n":19,"t":"在天上，我要顯出奇事，在地下，我要顯出神蹟，有血，有火，有煙霧。","notes":[]},{"n":20,"t":"太陽要變為黑暗，月亮要變為血，這都在主大而光榮的日子未到以前。","notes":[]},{"n":21,"t":"那時，凡求告主名的都必得救。』","notes":[]},{"n":22,"t":"「以色列人哪，你們要聽我這些話：拿撒勒人耶穌就是神以異能、奇事、神蹟向你們證明出來的人，這些事是神藉著他在你們中間施行，正如你們自己知道的。","notes":[]},{"n":23,"t":"他既按著神確定的旨意和預知被交與人，你們就藉著不法之人的手把他釘在十字架上，殺了。","notes":[]},{"n":24,"t":"神卻將死的痛苦解除，使他復活了，因為他原不能被死拘禁。","notes":[]},{"n":25,"t":"大衛指著他說：『我看見主常在我眼前，他在我右邊，使我不至於動搖。","notes":["「看見」：原文直譯「預見」。"]},{"n":26,"t":"所以我心裏歡喜，我的舌頭快樂，而且我的肉身要安居在指望中。","notes":[]},{"n":27,"t":"因你必不將我的靈魂撇在陰間，也不讓你的聖者見朽壞。","notes":[]},{"n":28,"t":"你已將生命的道路指示我，必使我在你面前充滿快樂。』","notes":[]},{"n":29,"t":"「諸位弟兄，先祖大衛的事，我可以坦然地對你們說：他死了，也埋葬了，而且他的墳墓直到今日還在我們這裏。","notes":[]},{"n":30,"t":"既然大衛是先知，他知道神曾向他起誓，要從他的後裔中立一位坐在他的寶座上。","notes":[]},{"n":31,"t":"他預先看見了，就講論基督的復活，說：『他不被撇在陰間；他的肉身也不見朽壞。』","notes":[]},{"n":32,"t":"這耶穌，神已經使他復活了，我們都是這事的見證人。","notes":[]},{"n":33,"t":"他既被高舉在神的右邊，又從父受了所應許的聖靈，就把你們所看見所聽見的，澆灌下來。","notes":[]},{"n":34,"t":"大衛並沒有升到天上，但他自己說：『主對我主說：你坐在我的右邊，","notes":[]},{"n":35,"t":"等我使你的仇敵作你的腳凳。』","notes":[]},{"n":36,"t":"故此，以色列全家當確實知道，你們釘在十字架上的這位耶穌，神已經立他為主，為基督了。」","notes":[]},{"n":37,"t":"眾人聽見這話，覺得扎心，就對彼得和其餘的使徒說：「諸位弟兄，我們該怎樣做呢？」","notes":[]},{"n":38,"t":"彼得對他們說：「你們各人要悔改，奉耶穌基督的名受洗，使你們的罪得赦免，就會領受所賜的聖靈。","notes":[]},{"n":39,"t":"因為這應許是給你們和你們的兒女，並一切在遠方的人，就是給所有主—我們的神所召來的人。」","notes":[]},{"n":40,"t":"彼得還用更多別的話作見證，勸勉他們說：「你們當救自己脫離這彎曲的世代。」","notes":[]},{"n":41,"t":"於是領受他話的人，都受了洗；那一天，門徒約添了三千人。","notes":[]},{"n":42,"t":"他們都專注於使徒的教導和彼此的團契，擘餅和祈禱。","notes":[]},{"n":43,"t":"眾人都心存敬畏；使徒們又行了許多奇事神蹟。","notes":["有古卷加「在耶路撒冷」。"],"heads":["信徒的團契生活"]},{"n":44,"t":"信的人都聚在一處，凡物公用，","notes":[]},{"n":45,"t":"又賣了田產和家業，照每一個人所需要的分給他們。","notes":[]},{"n":46,"t":"他們天天同心合意恆切地在聖殿裏敬拜，且在家中擘餅，存著歡喜坦誠的心用飯，","notes":["「在家中」：原文或譯「挨家挨戶」。"]},{"n":47,"t":"讚美神，得全體百姓的喜愛。主將得救的人天天加給他們。","notes":[]}]},"3":{"heading":"聖殿門口的瘸腿者得醫治","verses":[{"n":1,"t":"下午三點鐘禱告的時候，彼得和約翰上聖殿去。","notes":[]},{"n":2,"t":"一個從母腹裏就是瘸腿的人正被人抬來，他們天天把他放在聖殿的一個叫美門的門口，求進聖殿的人施捨。","notes":[]},{"n":3,"t":"他看見彼得、約翰將要進聖殿，就求他們施捨。","notes":[]},{"n":4,"t":"彼得和約翰定睛看他，彼得說：「看著我們！」","notes":[]},{"n":5,"t":"那人就注目看他們，指望從他們得著甚麼。","notes":[]},{"n":6,"t":"彼得卻說：「金銀我都沒有，但我把我有的給你：奉拿撒勒人耶穌基督的名起來行走！」","notes":["有古卷沒有「起來」。"]},{"n":7,"t":"於是彼得拉著他的右手，扶他起來；他的腳和踝骨立刻健壯了，","notes":[]},{"n":8,"t":"就跳起來，站著，又開始行走。他跟他們進了聖殿，邊走邊跳，讚美神。","notes":[]},{"n":9,"t":"百姓都看見他又行走，又讚美神，","notes":[]},{"n":10,"t":"認得他是那素常坐在聖殿的美門口求人施捨的，就因他所遇到的事滿心驚訝詫異。","notes":[]},{"n":11,"t":"那人正在稱為所羅門的廊下，拉住彼得和約翰，大家都覺得很驚訝，一齊跑到他們那裏。","notes":[],"heads":["彼得在所羅門廊下的演講"]},{"n":12,"t":"彼得看見，就對百姓說：「以色列人哪，為甚麼因這事而驚訝呢？為甚麼定睛看我們，以為我們憑自己的能力和虔誠使這人行走呢？","notes":[]},{"n":13,"t":"亞伯拉罕的神、以撒的神、雅各的神，就是我們列祖的神，已經榮耀了他的僕人耶穌，這耶穌就是你們交付官府的那位，彼拉多決定要釋放他時，你們卻在彼拉多面前棄絕了他。","notes":[]},{"n":14,"t":"你們棄絕了那聖潔公義者，反而要求釋放一個兇手給你們。","notes":[]},{"n":15,"t":"你們殺了那生命的創始者，神卻叫他從死人中復活；我們都是這事的見證人。","notes":[]},{"n":16,"t":"因信他的名，他的名使你們所看見所認識的這人健壯了；正是他所賜的信心使這人在你們眾人面前完全好了。","notes":[]},{"n":17,"t":"「如今，弟兄們，我知道你們做這事是出於無知，你們的官長也是如此。","notes":[]},{"n":18,"t":"但神藉著眾先知的口預先宣告過基督將要受害的事，就這樣應驗了。","notes":[]},{"n":19,"t":"所以，你們當悔改歸正，使你們的罪得以塗去，","notes":[]},{"n":20,"t":"這樣，那安舒的日子就必從主面前來到；主也必差遣所預定給你們的基督耶穌來臨。","notes":[]},{"n":21,"t":"他必須留在天上，直到萬物復興的時候，就是神自古藉著聖先知的口所說的。","notes":[]},{"n":22,"t":"摩西曾說：『主—你們的神要從你們弟兄中給你們興起一位先知像我，凡他向你們所說的一切，你們都要聽從。","notes":["有古卷是「我們」。"]},{"n":23,"t":"凡不聽從那先知的，必將從民中滅絕。』","notes":[]},{"n":24,"t":"從撒母耳以來和後繼的眾先知，凡說預言的，也都曾宣告這些日子。","notes":[]},{"n":25,"t":"你們是先知的子孫，也是神與你們祖宗所立之約的子孫，就是對亞伯拉罕說：『地上萬族都將因你的後裔得福。』","notes":["有古卷是「我們」。"]},{"n":26,"t":"神既興起他的僕人，就先差他到你們這裏來，賜福給你們，使各人回轉，離開你們的邪惡。」","notes":[]}]},"4":{"heading":"彼得和約翰在議會前被查問","verses":[{"n":1,"t":"彼得和約翰正向百姓說話的時候，祭司們、守殿官和撒都該人來了，","notes":[]},{"n":2,"t":"就很煩惱，因為使徒們教導百姓，傳揚在耶穌的事上證明有死人復活，","notes":[]},{"n":3,"t":"於是下手拿住他們；因為天已經晚了，就把他們押在拘留所到第二天。","notes":[]},{"n":4,"t":"但聽道的人有許多信了，男人的數目約有五千。","notes":[]},{"n":5,"t":"第二天，官長、長老和文士在耶路撒冷聚集，","notes":[]},{"n":6,"t":"又有亞那大祭司、該亞法、約翰、亞歷山大，和大祭司的親族都在那裏。","notes":[]},{"n":7,"t":"他們叫使徒站在中間，問他們：「你們憑甚麼能力，奉誰的名做這事呢？」","notes":[]},{"n":8,"t":"那時，彼得被聖靈充滿，對他們說：「民間的官長和長老啊，","notes":[]},{"n":9,"t":"倘若今日我們被查問是因為在殘障的人身上所行的善事，就是這人怎麼得了痊癒，","notes":[]},{"n":10,"t":"那麼，你們大家和以色列全民都當知道，站在你們面前的這人得痊癒，是因你們所釘在十字架、神使他從死人中復活的拿撒勒人耶穌基督的名。","notes":[]},{"n":11,"t":"這位耶穌是：『你們匠人所丟棄的石頭，已成了房角的頭塊石頭。』","notes":[]},{"n":12,"t":"除他以外，別無拯救，因為在天下人間，沒有賜下別的名，我們可以靠著得救。」","notes":[]},{"n":13,"t":"他們見彼得、約翰的膽量，又看出他們原是沒有學問的平民，就很驚訝，認出他們曾是跟耶穌一起的；","notes":[]},{"n":14,"t":"又看見那治好了的人和他們一同站著，就無話可駁。","notes":[]},{"n":15,"t":"於是他們吩咐他們兩人從議會退出，就彼此商議，","notes":[]},{"n":16,"t":"說：「我們當怎樣辦這兩個人呢？因為他們誠然行了一件明顯的神蹟，凡住在耶路撒冷的人都知道，我們也不能否認。","notes":[]},{"n":17,"t":"但為避免這事越發在民間傳揚，我們必須威嚇他們，叫他們不可再奉這名對任何人講論。」","notes":[]},{"n":18,"t":"於是他們叫了兩人來，禁止他們，再不可奉耶穌的名講論或教導人。","notes":[]},{"n":19,"t":"彼得和約翰回答他們說：「聽從你們，不聽從神，在神面前合理不合理，你們自己判斷吧！","notes":[]},{"n":20,"t":"我們所看見所聽見的，我們不能不說。」","notes":[]},{"n":21,"t":"官長為百姓的緣故，想不出任何法子懲罰他們，只好威嚇一番就把他們釋放了；這是因眾人為了所行的奇事都歸榮耀與神。","notes":[]},{"n":22,"t":"原來經歷這神蹟醫好的人有四十多歲了。","notes":[]},{"n":23,"t":"二人既被釋放，就到自己的人那裏去，把祭司長和長老所說的話都告訴他們。","notes":[],"heads":["門徒求主賜膽量"]},{"n":24,"t":"他們聽見了，就同心合意地高聲向神說：「主宰啊！你是那創造天、地、海和其中萬物的；","notes":[]},{"n":25,"t":"你曾藉著聖靈託你僕人—我們祖宗大衛的口說：『外邦為甚麼擾動？萬民為甚麼謀算虛妄的事？","notes":[]},{"n":26,"t":"地上的君王都站穩，臣宰也聚集一處，要對抗主，對抗主的受膏者。』","notes":["「受膏者」或譯「基督」。"]},{"n":27,"t":"希律和本丟‧彼拉多，同外邦人和以色列民，果然在這城裏聚集，要攻打你所膏的聖僕耶穌，","notes":[]},{"n":28,"t":"做了你手和你旨意所預定必成就的事。","notes":[]},{"n":29,"t":"主啊，現在求你鑒察，他們的威嚇，使你僕人放膽講你的道，","notes":[]},{"n":30,"t":"伸出你的手來，讓醫治、神蹟、奇事藉著你聖僕耶穌的名行出來。」","notes":[]},{"n":31,"t":"他們禱告完了，聚會的地方震動；他們都被聖靈充滿，放膽傳講神的道。","notes":[]},{"n":32,"t":"許多信徒都一心一意，沒有一人說他的任何東西是自己的，都是大家公用。","notes":[],"heads":["凡物公用"]},{"n":33,"t":"使徒以大能見證主耶穌復活；眾人也都蒙了大恩。","notes":["「主耶穌」：有古卷是「主耶穌基督」。"]},{"n":34,"t":"他們當中沒有一個缺乏的，因為凡有田產房屋的都賣了，把所賣的錢拿來，","notes":[]},{"n":35,"t":"放在使徒腳前，照每人所需要的，分給每人。","notes":[]},{"n":36,"t":"有一個利未人，名叫約瑟，使徒稱他為巴拿巴（巴拿巴翻出來就是安慰之子），生在塞浦路斯。","notes":[]},{"n":37,"t":"他有田地，也賣了，把錢拿來，放在使徒腳前。","notes":[]}]},"5":{"heading":"亞拿尼亞和撒非喇","verses":[{"n":1,"t":"有一個人，名叫亞拿尼亞，同他的妻子撒非喇，賣了田產，","notes":[]},{"n":2,"t":"把錢私自留下一部分，他的妻子也知道，其餘的部分拿來放在使徒腳前。","notes":[]},{"n":3,"t":"彼得說：「亞拿尼亞！為甚麼撒但充滿了你的心，使你欺騙聖靈，把賣田地的錢私自留下一部分呢？","notes":[]},{"n":4,"t":"田地還沒有賣，不是你自己的嗎？既賣了，錢不是你作主嗎？你怎麼心裏會想這樣做呢？你不是欺騙人，是欺騙神！」","notes":[]},{"n":5,"t":"亞拿尼亞一聽見這些話，就仆倒，斷了氣；所有聽見的人都非常懼怕。","notes":[]},{"n":6,"t":"有些年輕人起來，把他裹好，抬出去埋葬了。","notes":[]},{"n":7,"t":"約過了三小時，他的妻子進來，還不知道所發生的事。","notes":[]},{"n":8,"t":"彼得對她說：「你告訴我，你們賣田地的錢就是這些嗎？」她說：「就是這些。」","notes":[]},{"n":9,"t":"彼得對她說：「你們為甚麼同謀來試探主的靈呢？你看，埋葬你丈夫之人的腳已到門口，他們也要把你抬出去。」","notes":[]},{"n":10,"t":"她立刻仆倒在彼得腳前，斷了氣。那些年輕人進來，見她已經死了，就把她抬出去，埋在她丈夫旁邊。","notes":[]},{"n":11,"t":"全教會和所有聽見這些事的人都非常懼怕。","notes":[]},{"n":12,"t":"主藉使徒的手在民間行了許多神蹟奇事；他們都同心合意地聚集在所羅門的廊下。","notes":[],"heads":["主藉使徒行許多神蹟奇事"]},{"n":13,"t":"其餘的人沒有一個敢接近他們，百姓卻尊重他們。","notes":[]},{"n":14,"t":"信主的人越發增添，連男帶女都很多，","notes":[]},{"n":15,"t":"甚至有人將病人抬到街上，放在床上或褥子上，好讓彼得走過來的時候，或者影子投在一些人身上。","notes":[]},{"n":16,"t":"還有許多人帶著病人和被污靈纏磨的，從耶路撒冷四圍的城鎮來，他們全都得了醫治。","notes":[]},{"n":17,"t":"於是，大祭司採取行動，他和他所有一起的人，就是撒都該派的人，滿心忌恨，","notes":[],"heads":["使徒受迫害"]},{"n":18,"t":"就下手拿住使徒，把他們押在公共拘留所內。","notes":[]},{"n":19,"t":"但在夜間主的使者開了監門，領他們出來，說：","notes":[]},{"n":20,"t":"「你們去，站在聖殿裏，把這生命的一切話講給百姓聽。」","notes":[]},{"n":21,"t":"使徒聽了這話，天將亮的時候就進聖殿裏去教導人。大祭司和他一起的人來了，叫齊議會的人和以色列人的眾長老，然後派人到監牢裏去把使徒提出來。","notes":[]},{"n":22,"t":"但差役到了，不見他們在監裏，就回來稟報，","notes":[]},{"n":23,"t":"說：「我們看見監牢關得很緊，警衛也站在門外，但打開門來，裏面一個人都不見。」","notes":[]},{"n":24,"t":"守殿官和祭司長聽了這些話，心裏困惑，不知這事將來如何。","notes":[]},{"n":25,"t":"有一個人來稟報說：「你們押在監裏的人，現在站在聖殿裏教導百姓。」","notes":[]},{"n":26,"t":"於是守殿官和差役去帶使徒來，並沒有用暴力，因為怕百姓用石頭打他們。","notes":[]},{"n":27,"t":"他們把使徒帶來了，就叫他們站在議會前。大祭司問他們，","notes":[]},{"n":28,"t":"說：「我們不是嚴嚴地禁止你們，不可奉這名教導人嗎？看，你們倒把你們的道理充滿了耶路撒冷，想要叫這人的血歸到我們身上！」","notes":["「我們…教導人嗎？」：有古卷是「我們嚴嚴地禁止你們不可奉這名教導人。」"]},{"n":29,"t":"彼得和眾使徒回答：「我們必須順從神，勝於順從人。","notes":[]},{"n":30,"t":"你們掛在木頭上殺害的耶穌，我們祖宗的神已經使他復活了。","notes":[]},{"n":31,"t":"神把他高舉在自己的右邊，使他作元帥，作救主，使以色列人得以悔改，並且罪得赦免。","notes":[]},{"n":32,"t":"我們是這些事的見證人；神賜給順從的人的聖靈也為這些事作見證。」","notes":[]},{"n":33,"t":"議會的人聽了極其惱怒，想要殺他們。","notes":[]},{"n":34,"t":"但有一個法利賽人，名叫迦瑪列，是眾百姓所敬重的律法教師，他在議會中站起來，吩咐人把使徒暫且帶到外面去，","notes":[]},{"n":35,"t":"然後對眾人說：「以色列人哪，對於這些人，你們應當小心怎樣處理。","notes":[]},{"n":36,"t":"從前杜達出現，自命不凡，附從他的人數約有四百；他被殺後，附從他的人全都散了，歸於無有。","notes":[]},{"n":37,"t":"此後，登記戶籍的時候，又有加利利的猶大出現，引誘百姓跟從他，他也滅亡，附從他的人也都四散了。","notes":[]},{"n":38,"t":"現在，我勸你們不要管這些人，任憑他們吧！他們所謀所為若是出於人，必要敗壞；","notes":[]},{"n":39,"t":"若是出於神，你們就不能敗壞他們，恐怕你們倒是攻擊神了。」議會的人被他說服了，","notes":[]},{"n":40,"t":"就叫使徒來，把他們打了，又吩咐他們不可奉耶穌的名講道，然後把他們釋放了。","notes":[]},{"n":41,"t":"他們歡歡喜喜地離開議會，因他們算配為這名受辱。","notes":[]},{"n":42,"t":"他們就每日在聖殿裏，在家裏，不住地教導人，傳耶穌是基督的福音。","notes":["「在家裏」：原文或譯「挨家挨戶」。"]}]},"6":{"heading":"揀選七人辦理供給之事","verses":[{"n":1,"t":"那些日子，門徒增多，有說希臘話的猶太人向希伯來人發怨言，因為在日常的供給上忽略了他們的寡婦。","notes":[]},{"n":2,"t":"十二使徒叫眾門徒來，說：「我們撇下神的道去管理飯食，是不合宜的。","notes":[]},{"n":3,"t":"所以弟兄們，當從你們中間選出七個有好名聲、滿有聖靈和智慧，我們派他們管理這事。","notes":[]},{"n":4,"t":"至於我們，我們要專注於祈禱和傳道的事奉。」","notes":[]},{"n":5,"t":"這話使全會眾都喜悅，就揀選了司提反—他是一個滿有信心和聖靈的人；他們又揀選了腓利、伯羅哥羅、尼迦挪、提門、巴米拿，並皈依猶太教的安提阿人尼哥拉，","notes":[]},{"n":6,"t":"叫他們站在使徒面前，使徒禱告後，就為他們按手。","notes":[]},{"n":7,"t":"神的道興旺起來；在耶路撒冷門徒數目增加得很多，也有許多祭司聽從了這信仰。","notes":[]},{"n":8,"t":"司提反滿有恩惠和能力，在民間行了大奇事和神蹟。","notes":[],"heads":["司提反被捕"]},{"n":9,"t":"當時有從稱為「自由人」會堂，並古利奈、亞歷山大會堂來的人，還有些從基利家、亞細亞來的人，起來和司提反辯論。","notes":[]},{"n":10,"t":"司提反是以智慧和聖靈說話，眾人抵擋不住，","notes":[]},{"n":11,"t":"就收買人來說：「我們聽見他說褻瀆摩西和神的話。」","notes":[]},{"n":12,"t":"他們又煽動百姓、長老和文士，就突然來捉拿他，把他帶到議會去，","notes":[]},{"n":13,"t":"設下假見證，說：「這個人不斷地說話，侮辱神聖的地方和律法。","notes":[]},{"n":14,"t":"我們曾聽見他說，這拿撒勒人耶穌要毀壞這地方，也要改變摩西所交給我們的規矩。」","notes":[]},{"n":15,"t":"在議會裏坐著的人都定睛看他，見他的面貌好像天使的面貌。","notes":[]}]},"7":{"heading":"司提反當眾申訴","verses":[{"n":1,"t":"大祭司說：「果真有這些事嗎？」","notes":[]},{"n":2,"t":"司提反說：「諸位父老弟兄請聽！從前我們的祖宗亞伯拉罕在美索不達米亞，還沒有住在哈蘭的時候，榮耀的神向他顯現，","notes":[]},{"n":3,"t":"對他說：『你要離開本地和親族，往我所要指示你的地去。』","notes":[]},{"n":4,"t":"他就離開迦勒底人的地方，住在哈蘭。他父親死了以後，神使他從那裏搬到你們現在所住的地方。","notes":[]},{"n":5,"t":"在這裏神並沒有給他產業，連立足的地方都沒有，但應許要將這地賜給他和他的後裔為業，雖然那時他還沒有兒子。","notes":[]},{"n":6,"t":"神這樣說：『他的後裔必寄居外邦，那裏的人要使他們作奴隸，苦待他們四百年。』","notes":[]},{"n":7,"t":"神又說：『但我要懲罰使他們作奴隸的那國。以後他們要出來，在這地方事奉我。』","notes":[]},{"n":8,"t":"神又賜他割禮的約。於是亞伯拉罕生了以撒，在第八日給他行了割禮；後來以撒生雅各，雅各生十二位先祖。","notes":[]},{"n":9,"t":"「先祖嫉妒約瑟，把他賣到埃及去，神卻與他同在，","notes":[]},{"n":10,"t":"救他脫離一切苦難，又使他在埃及王法老面前蒙恩，又有智慧。法老派他作埃及國的宰相兼管法老的全家。","notes":[]},{"n":11,"t":"後來全埃及和迦南遭遇饑荒和大災難，我們的祖宗絕了糧。","notes":[]},{"n":12,"t":"雅各聽見在埃及有糧，就打發我們的祖宗初次往那裏去。","notes":[]},{"n":13,"t":"第二次約瑟與兄弟們相認，法老才認識他的家族。","notes":[]},{"n":14,"t":"約瑟就打發人，請父親雅各和全族七十五個人都來。","notes":[]},{"n":15,"t":"於是雅各下了埃及，後來他和我們的祖宗都死在那裏；","notes":[]},{"n":16,"t":"他們又被遷到示劍，葬於亞伯拉罕在示劍用銀子從哈抹子孫買來的墳墓裏。","notes":["「在示劍…子孫」：有古卷是「用銀子從示劍的哈抹子孫」。"]},{"n":17,"t":"「當神應許亞伯拉罕的日期將到的時候，以色列人在埃及人丁興旺，","notes":[]},{"n":18,"t":"直到另一位不認識約瑟的王興起統治埃及。","notes":["有古卷沒有「統治埃及」。"]},{"n":19,"t":"他用詭計待我們的宗族，苦待我們的祖宗，強迫他們丟棄嬰孩，使嬰孩不能存活。","notes":[]},{"n":20,"t":"就在那時，摩西生了下來，神看為俊美，在父親家裏被撫養了三個月。","notes":[]},{"n":21,"t":"他被丟棄的時候，法老的女兒拾了去，當自己的兒子撫養。","notes":[]},{"n":22,"t":"摩西學了埃及人一切的學問，說話辦事都有才能。","notes":[]},{"n":23,"t":"「他到了四十歲，心中起意去看望他的弟兄以色列人。","notes":[]},{"n":24,"t":"他見他們中的一個人受冤屈，就庇護他，為那被壓迫的人報仇，打死了那埃及人。","notes":[]},{"n":25,"t":"他以為他的弟兄們必明白神是藉他的手搭救他們，他們卻不明白。","notes":[]},{"n":26,"t":"第二天，他遇見有人在打架，就想勸他們和好，說：『二位，你們是弟兄，為甚麼彼此欺負呢？』","notes":[]},{"n":27,"t":"那欺負鄰舍的人把他推開，說：『誰立你作我們的領袖和審判官呢？","notes":[]},{"n":28,"t":"難道你要殺我像昨天殺那埃及人一樣嗎？』","notes":[]},{"n":29,"t":"摩西聽見這話就逃走了，寄居於米甸地，在那裏生了兩個兒子。","notes":[]},{"n":30,"t":"「過了四十年，在西奈山的曠野，有一位天使在荊棘的火焰中向摩西顯現。","notes":[]},{"n":31,"t":"摩西見了那異象，覺得很驚訝，正往前觀看的時候，有主的聲音說：","notes":[]},{"n":32,"t":"『我是你列祖的神，就是亞伯拉罕、以撒、雅各的神。』摩西戰戰兢兢，不敢觀看。","notes":[]},{"n":33,"t":"主對他說：『把你腳上的鞋脫下來，因為你所站的地方是聖地。","notes":[]},{"n":34,"t":"我的百姓在埃及所受的困苦，我確實看見了；他們悲嘆的聲音，我也聽見了。我下來要救他們。現在，你來，我要差你往埃及去。』","notes":[]},{"n":35,"t":"「這摩西就是有人曾棄絕他說『誰立你作我們的領袖和審判官』的，神卻藉那在荊棘中顯現的天使的手差派他作領袖，作解救者。","notes":[]},{"n":36,"t":"這人領以色列人出來，在埃及地，在紅海，在曠野的四十年間行了奇事神蹟。","notes":[]},{"n":37,"t":"這人是摩西，就是那曾對以色列人說『神要從你們弟兄中給你們興起一位先知像我』的。","notes":[]},{"n":38,"t":"這人是那曾在曠野的會眾中和西奈山上，與那對他說話的天使同在，又與我們祖宗同在的，他領受了活潑的聖言傳給我們。","notes":[]},{"n":39,"t":"我們的祖宗不肯聽從，反棄絕他，他們的心轉向埃及，","notes":[]},{"n":40,"t":"對亞倫說：『你為我們造神明，在我們前面引路，因為領我們出埃及地的這個摩西，我們不知道他遭遇了甚麼事。』","notes":[]},{"n":41,"t":"那時，他們造了一個牛犢，又拿祭物獻給那像，為自己手所做的工作歡躍。","notes":[]},{"n":42,"t":"但是神轉臉不顧，任憑他們祭拜天上的日月星辰，正如先知書上所寫的：『以色列家啊，你們四十年間在曠野，何曾將犧牲和祭物獻給我？","notes":[]},{"n":43,"t":"你們抬著摩洛的帳幕和理番─你們神明的星，就是你們所造為要敬拜的像。因此，我要把你們遷到巴比倫外去。』","notes":[]},{"n":44,"t":"「我們的祖宗在曠野，有作證的會幕，是神吩咐摩西照著他所看見的樣式做的。","notes":[]},{"n":45,"t":"這帳幕，我們的祖宗同約書亞相繼承受了，當神在他們面前趕走外邦人的時候，他們把這帳幕搬進承受為業之地，直存到大衛的日子。","notes":[]},{"n":46,"t":"大衛在神面前蒙恩，祈求為雅各的家預備居所。","notes":["「家」：有古卷是「神」。"]},{"n":47,"t":"但卻是所羅門為神造成殿宇。","notes":[]},{"n":48,"t":"其實，至高者並不住人手所造的，就如先知所言：","notes":[]},{"n":49,"t":"『主說：天是我的寶座，地是我的腳凳。你們要為我造怎樣的殿宇？哪裏是我安歇的地方呢？","notes":[]},{"n":50,"t":"這一切不都是我手所造的嗎？』","notes":[]},{"n":51,"t":"「你們這硬著頸項，心與耳未受割禮的人哪，時常抗拒聖靈！你們的祖宗怎樣，你們也怎樣。","notes":[]},{"n":52,"t":"先知中有哪一個不是受你們祖宗的迫害呢？他們把預先宣告那義者要來的人殺了。如今你們成了那義者的出賣者和兇手了。","notes":[]},{"n":53,"t":"你們領受了天使所傳佈的律法，竟不遵守。」","notes":[]},{"n":54,"t":"眾人聽見這些話，心中極其惱怒，向司提反咬牙切齒。","notes":[],"heads":["眾人用石頭打死司提反"]},{"n":55,"t":"但司提反滿有聖靈，定睛望天，看見神的榮耀，又看見耶穌站在神的右邊，","notes":[]},{"n":56,"t":"就說：「我看見天開了，人子站在神的右邊。」","notes":[]},{"n":57,"t":"眾人大聲喊叫，摀著耳朵，齊心衝向他，","notes":[]},{"n":58,"t":"把他推到城外，用石頭打他。作見證的人把他們的衣裳放在一個名叫掃羅的青年腳前。","notes":[]},{"n":59,"t":"他們正用石頭打司提反的時候，他呼求說：「主耶穌啊，求你接納我的靈魂！」","notes":[]},{"n":60,"t":"然後他跪下來，大聲喊著：「主啊，不要將這罪歸於他們！」說了這話，就長眠了。","notes":[]}]},"8":{"heading":"掃羅迫害教會","verses":[{"n":1,"t":"掃羅也贊同處死他。從那一天開始，耶路撒冷的教會遭受到大迫害，除了使徒以外，眾門徒都分散在猶太和撒瑪利亞各處。","notes":[]},{"n":2,"t":"有些虔誠的人把司提反埋葬了，為他大大哀哭。","notes":[]},{"n":3,"t":"掃羅卻殘害教會，挨家挨戶地進去，拉著男女關在監裏。","notes":[]},{"n":4,"t":"那些分散的人往各地去傳福音的道。","notes":[],"heads":["福音傳到撒瑪利亞"]},{"n":5,"t":"腓利下撒瑪利亞城去，向當地人宣講基督。","notes":["「下…城去」：有古卷是「下撒瑪利亞的一座城去」。"]},{"n":6,"t":"眾人都聚精會神，同心合意地聽腓利所說的話，一邊聽他的話，一邊看他所行的神蹟。","notes":[]},{"n":7,"t":"因為有許多人被污靈附著，那些污靈大聲呼叫，從他們身上出來；還有許多癱瘓的、瘸腿的都得了醫治。","notes":[]},{"n":8,"t":"那城裏，有極大的喜樂。","notes":[]},{"n":9,"t":"有一個人名叫西門，向來在那城裏行邪術，自命為大人物，使撒瑪利亞的居民驚奇。","notes":[]},{"n":10,"t":"所有的人，從小到大都聽從他，說：「這個人就是神的能力，那稱為大能者的。」","notes":[]},{"n":11,"t":"他們聽從他，因他很久以來用邪術使他們驚奇。","notes":[]},{"n":12,"t":"當他們信了腓利所傳神國的福音和耶穌基督的名，連男帶女都受了洗。","notes":[]},{"n":13,"t":"西門自己也信了；既受了洗，就常與腓利在一處，看見他所行的神蹟和大異能，就覺得很驚奇。","notes":[]},{"n":14,"t":"在耶路撒冷的使徒聽見撒瑪利亞人領受了神的道，就打發彼得和約翰到他們那裏去。","notes":[]},{"n":15,"t":"兩個人下去，就為他們禱告，要讓他們領受聖靈，","notes":[]},{"n":16,"t":"因為聖靈還沒有降在他們任何一個人身上，他們只奉主耶穌的名受了洗。","notes":[]},{"n":17,"t":"於是使徒按手在他們頭上，他們就領受了聖靈。","notes":[]},{"n":18,"t":"西門看見使徒一按手，就有聖靈賜下，就拿錢給使徒，","notes":[]},{"n":19,"t":"說：「請把這權柄也給我，使我手按著誰，誰就可以領受聖靈。」","notes":[]},{"n":20,"t":"彼得對他說：「你的銀子和你一同滅亡吧！因為你想神的恩賜是可以用錢買的。","notes":[]},{"n":21,"t":"你在這道上無份無關；因為你在神面前心懷不正。","notes":[]},{"n":22,"t":"你要為你這樣的惡而悔改，祈求主，或者你心裏的意念可得赦免。","notes":[]},{"n":23,"t":"我看出你正在苦膽之中，被不義捆綁著。」","notes":[]},{"n":24,"t":"西門回答說：「請你們為我求主，使你們所說的，沒有一樣臨到我身上。」","notes":[]},{"n":25,"t":"使徒既作了見證，並且宣講了主的道，就回耶路撒冷去，一路在撒瑪利亞好些村莊傳揚福音。","notes":[]},{"n":26,"t":"有主的一個使者對腓利說：「起來！向南走，往那從耶路撒冷下迦薩的路上去。」那路是曠野。","notes":[],"heads":["腓利與埃塞俄比亞的太監"]},{"n":27,"t":"腓利就起身去了。不料，有一個埃塞俄比亞人，是個有大權的太監，在埃塞俄比亞女王甘大基的手下總管銀庫，他上耶路撒冷去禮拜。","notes":[]},{"n":28,"t":"回程中，他坐在車上，正念著以賽亞先知的書，","notes":[]},{"n":29,"t":"聖靈對腓利說：「你去！靠近那車走。」","notes":[]},{"n":30,"t":"腓利就跑到太監那裏，聽見他正在念以賽亞先知的書，就說：「你明白你所念的嗎？」","notes":[]},{"n":31,"t":"他說：「沒有人指教我，怎能明白呢？」於是他請腓利上車，與他同坐。","notes":[]},{"n":32,"t":"他所念的那段經文是這樣：「他像羊被牽去宰殺，又像羔羊在剪毛的人手下無聲，他也是這樣不開口。","notes":[]},{"n":33,"t":"他卑微的時候，得不到公義的審判，誰能述說他的身世？因為他的生命從地上被奪去。」","notes":[]},{"n":34,"t":"太監回答腓利說：「請問，先知說這話是指誰，是指自己，還是指別人呢？」","notes":[]},{"n":35,"t":"腓利就開口，從這段經文開始，對他傳講耶穌的福音。","notes":[]},{"n":36,"t":"二人正沿路往前走，到了有水的地方，太監說：「看哪！這裏有水，有甚麼能阻止我受洗呢？」","notes":["有古卷加「37 腓利說：『你若是一心相信，就可以。』他回答：『我信耶穌基督是神的兒子。』」"]},{"n":38,"t":"於是他吩咐把車停下來，腓利和太監二人一同下到水裏，腓利就給他施洗。","notes":[]},{"n":39,"t":"他們從水裏上來，主的靈把腓利提了去，太監再也看不見他了，就歡歡喜喜地上路。","notes":[]},{"n":40,"t":"後來有人在亞鎖都遇見腓利；他走遍那地方，在各城宣揚福音，一直到凱撒利亞。","notes":[]}]},"9":{"heading":"掃羅的悔改","verses":[{"n":1,"t":"掃羅不斷用威嚇兇悍的口氣向主的門徒說話。他去見大祭司，","notes":[]},{"n":2,"t":"要求發信給大馬士革的各會堂，若是找著信奉這道的人，無論男女，都准他捆綁帶到耶路撒冷。","notes":[]},{"n":3,"t":"掃羅在途中，將到大馬士革的時候，忽然有一道光從天上下來，四面照射著他，","notes":[]},{"n":4,"t":"他就仆倒在地，聽見有聲音對他說：「掃羅！掃羅！你為甚麼迫害我？」","notes":[]},{"n":5,"t":"他說：「主啊！你是誰？」主說：「我就是你所迫害的耶穌。","notes":[]},{"n":6,"t":"起來！進城去，你應該做的事，必有人告訴你。」","notes":[]},{"n":7,"t":"同行的人站在那裏，說不出話來，因為他們聽見聲音，卻看不見人。","notes":[]},{"n":8,"t":"掃羅從地上起來，睜開眼睛，竟不能看見甚麼。有人拉他的手，領他進了大馬士革。","notes":[]},{"n":9,"t":"他三天甚麼都看不見，也不吃也不喝。","notes":[]},{"n":10,"t":"那時，在大馬士革有一個門徒，名叫亞拿尼亞。主在異象中對他說：「亞拿尼亞！」他說：「主啊，我在這裏。」","notes":[]},{"n":11,"t":"主對他說：「起來！往那叫直街的路去，在猶大的家裏，去找一個大數人，名叫掃羅；他正在禱告，","notes":[]},{"n":12,"t":"在異象中看見了一個人，名叫亞拿尼亞，進來為他按手，讓他能再看得見。」","notes":["有古卷沒有「在異象中」。"]},{"n":13,"t":"亞拿尼亞回答：「主啊，我聽見許多人講到這個人，說他怎樣在耶路撒冷多多苦待你的聖徒，","notes":[]},{"n":14,"t":"並且他在這裏有從祭司長得來的權柄，要捆綁一切求告你名的人。」","notes":[]},{"n":15,"t":"主對他說：「你只管去。他是我所揀選的器皿，要在外邦人、君王和以色列人面前宣揚我的名。","notes":[]},{"n":16,"t":"我也要指示他，為我的名必須受許多的苦難。」","notes":[]},{"n":17,"t":"亞拿尼亞就去了，進入那家，把手按在掃羅身上，說：「掃羅弟兄，在你來的路上向你顯現的主，就是耶穌，打發我來，叫你能再看得見，又被聖靈充滿。」","notes":[]},{"n":18,"t":"掃羅的眼睛上立刻好像有鱗一般的東西掉下來，他就能再看得見，於是他起來，受了洗，","notes":[]},{"n":19,"t":"吃過飯體力就恢復了。掃羅和大馬士革的門徒一起住了些日子，","notes":[]},{"n":20,"t":"立刻在各會堂裏傳揚耶穌，說他是神的兒子。","notes":[]},{"n":21,"t":"凡聽見的人都很驚奇，說：「在耶路撒冷殘害求告這名的不就是這個人嗎？他不是到這裏來要捆綁他們，帶到祭司長那裏去嗎？」","notes":[]},{"n":22,"t":"但掃羅越發有能力，駁倒住在大馬士革的猶太人，證明耶穌是基督。","notes":[]},{"n":23,"t":"過了好些日子，猶太人商議要殺掃羅，","notes":[],"heads":["逃脫猶太人的謀害"]},{"n":24,"t":"但他們的計謀被掃羅知道了。他們晝夜在城門守候著要殺他。","notes":[]},{"n":25,"t":"他的門徒就在夜間用筐子把他從城牆上縋了下去。","notes":[]},{"n":26,"t":"掃羅到了耶路撒冷，想與門徒結交，大家卻都怕他，不信他是門徒。","notes":[],"heads":["掃羅在耶路撒冷"]},{"n":27,"t":"只有巴拿巴接待他，領他去見使徒，把他在路上怎麼看見主，主怎麼向他說話，他在大馬士革怎麼奉耶穌的名放膽傳道，都述說出來。","notes":[]},{"n":28,"t":"於是掃羅在耶路撒冷同門徒出入來往，奉主的名放膽傳道，","notes":[]},{"n":29,"t":"並和說希臘話的猶太人講論辯駁，他們卻想法子要殺他。","notes":[]},{"n":30,"t":"弟兄們知道了，就帶他下凱撒利亞，送他往大數去。","notes":[]},{"n":31,"t":"那時，猶太、加利利、撒瑪利亞各處的教會都得平安，建立起來，凡事敬畏主，蒙聖靈的安慰，人數逐漸增多。","notes":[]},{"n":32,"t":"彼得在眾信徒中到處奔波的時候，也到了住在呂大的聖徒那裏。","notes":[],"heads":["以尼雅得醫治"]},{"n":33,"t":"他在那裏遇見一個人，名叫以尼雅，得了癱瘓，在褥子上躺了八年。","notes":[]},{"n":34,"t":"彼得對他說：「以尼雅，耶穌基督醫好你了，起來！整理你的褥子吧。」他立刻就起來了。","notes":[]},{"n":35,"t":"凡住呂大和沙崙的人都看見了他，就歸向主。","notes":[]},{"n":36,"t":"在約帕有一個女門徒，名叫大比大，翻出來的意思是多加；她廣行善事，多施賙濟。","notes":["「多加」意思是「羚羊」。"],"heads":["多加復活"]},{"n":37,"t":"當時，她患病死了，有人把她清洗後，停在樓上。","notes":[]},{"n":38,"t":"呂大原與約帕相近；門徒聽見彼得在那裏，就派兩個人去見他，央求他說：「請快到我們那裏去，不要耽延。」","notes":[]},{"n":39,"t":"彼得就起身和他們同去。他到了，就有人領他上樓。眾寡婦都站在彼得旁邊哭，拿多加與她們同在時所做的內衣外衣給他看。","notes":[]},{"n":40,"t":"彼得叫她們都出去，然後跪下禱告，轉身對著屍體說：「大比大，起來！」她就睜開眼睛，看見彼得，就坐了起來。","notes":[]},{"n":41,"t":"彼得伸手扶她起來，叫那些聖徒和寡婦都進來，把多加活活地交給他們。","notes":[]},{"n":42,"t":"這事傳遍了約帕，就有許多人信了主。","notes":[]},{"n":43,"t":"此後，彼得在約帕一個皮革匠西門的家裏住了好些日子。","notes":[]}]},"10":{"heading":"彼得和哥尼流","verses":[{"n":1,"t":"在凱撒利亞有一個人名叫哥尼流，是意大利營的百夫長。","notes":[]},{"n":2,"t":"他是個虔誠人，他和全家都敬畏神。他多多賙濟百姓，常常向神禱告。","notes":[]},{"n":3,"t":"有一天，約在下午三點鐘，他在異象中清楚看見神的一個使者進來，到他那裏，對他說：「哥尼流。」","notes":[]},{"n":4,"t":"哥尼流定睛看他，驚惶地說：「主啊，甚麼事？」天使對他說：「你的禱告和你的賙濟已達到神面前，蒙記念了。","notes":[]},{"n":5,"t":"現在你要派人往約帕去，請一位稱為彼得的西門來。","notes":[]},{"n":6,"t":"他住在一個皮革匠西門的家裏，房子就在海邊。」","notes":[]},{"n":7,"t":"向他說話的天使離開後，哥尼流叫了兩個僕人和常伺候他的一個虔誠的兵來，","notes":[]},{"n":8,"t":"把一切的事都講給他們聽，然後就派他們往約帕去。","notes":[]},{"n":9,"t":"第二天，他們走路將近那城，約在正午，彼得上房頂去禱告。","notes":[]},{"n":10,"t":"他覺得餓了，想要吃。那家的人正預備飯的時候，彼得魂遊象外，","notes":[]},{"n":11,"t":"看見天開了，有一塊好像大布的東西降下，四角吊著縋在地上，","notes":["有古卷加「綁住」。"]},{"n":12,"t":"裏面有地上各樣四腳的走獸、爬蟲和天上的飛鳥。","notes":[]},{"n":13,"t":"又有聲音對他說：「彼得，起來！宰了吃。」","notes":[]},{"n":14,"t":"彼得卻說：「主啊，絕對不可！凡污俗和不潔淨的東西，我從來沒有吃過。」","notes":[]},{"n":15,"t":"第二次有聲音再對他說：「神所潔淨的，你不可當作污俗的。」","notes":[]},{"n":16,"t":"這樣一連三次，那東西隨即收回天上去了。","notes":[]},{"n":17,"t":"正當彼得心裏困惑，不知所看見的異象是甚麼意思時，哥尼流所差來的人已經找到了西門的家，站在門外，","notes":[]},{"n":18,"t":"喊著問有沒有一位稱為彼得的西門住在這裏。","notes":[]},{"n":19,"t":"彼得還在思考那異象的時候，聖靈對他說：「有三個人來找你。","notes":[]},{"n":20,"t":"起來，下去，跟他們同去，不要疑惑，因為是我差他們來的。」","notes":[]},{"n":21,"t":"於是彼得下去見那些人，說：「我就是你們要找的人，你們是為了甚麼緣故在這裏？」","notes":[]},{"n":22,"t":"他們說：「百夫長哥尼流是個義人，敬畏神，為猶太全民族所稱讚。他蒙一位聖天使指示，叫他請你到他家裏去，要聽你講話。」","notes":[]},{"n":23,"t":"彼得就請他們進去住宿。次日，他起身和他們同去，還有約帕的幾個弟兄跟他一起去。","notes":[]},{"n":24,"t":"又次日，他進入凱撒利亞，哥尼流已經請了他的親朋好友在等候他們。","notes":["有古卷是「他們」。"]},{"n":25,"t":"彼得一進去，哥尼流就迎接他，俯伏在他腳前拜他。","notes":[]},{"n":26,"t":"但是彼得拉他起來，說：「你起來，我自己也不過是人。」","notes":[]},{"n":27,"t":"彼得和他一邊說話一邊進去，見有好些人聚集，","notes":[]},{"n":28,"t":"就對他們說：「你們知道，猶太人和別國的人結交來往本是不合規矩的，但神已經指示我，無論甚麼人都不可看作污俗或不潔淨的。","notes":[]},{"n":29,"t":"所以，我一被邀請，沒有推辭就來了。現在請問，你們為甚麼叫我來呢？」","notes":[]},{"n":30,"t":"哥尼流說：「四天前，這個時候，我在家中守著下午三點鐘的禱告，忽然有一個人穿著明亮的衣裳站在我面前，","notes":[]},{"n":31,"t":"說：『哥尼流，你的禱告已蒙垂聽，你的賙濟在神面前已蒙記念了。","notes":[]},{"n":32,"t":"你要派人往約帕去，請那稱為彼得的西門來，他住在海邊一個皮革匠西門的家裏。』","notes":[]},{"n":33,"t":"所以我立刻派人去請你。你來了真好。現在我們都在神面前，要聽主吩咐你的一切話。」","notes":["「主」：有古卷是「神」。"]},{"n":34,"t":"彼得開口說：「我真的看出神是不偏待人的。","notes":[],"heads":["在哥尼流家中講道"]},{"n":35,"t":"不但如此，在各國中那敬畏他而行義的人都為他所悅納。","notes":[]},{"n":36,"t":"神藉著耶穌基督—他是萬有的主—傳和平的福音，把這道傳給以色列人。","notes":[]},{"n":37,"t":"這話在約翰傳揚洗禮以後，從加利利起，傳遍了猶太。神怎樣以聖靈和能力膏了拿撒勒人耶穌，這都是你們知道的。他到處奔波，行善事，醫好凡被魔鬼壓制的人，因為神與他同在。","notes":[],"end":38},{"n":39,"t":"他在猶太人之地和耶路撒冷所行的一切事，有我們作見證人。他們竟把他掛在木頭上殺了。","notes":[]},{"n":40,"t":"第三天，神使他復活，使他顯現出來；","notes":[]},{"n":41,"t":"不是顯現給所有的人看，而是顯現給神預先所揀選為他作見證的人看，就是我們這些在他從死人中復活以後和他同吃同喝的人。","notes":[]},{"n":42,"t":"他吩咐我們傳道給眾人，證明他是神所立定，要作審判活人、死人的審判者。","notes":[]},{"n":43,"t":"眾先知也為這人作見證：凡信他的人，必藉著他的名得蒙赦罪。」","notes":[]},{"n":44,"t":"彼得還在說這些話的時候，聖靈降在一切聽道的人身上。","notes":[],"heads":["外邦人領受聖靈"]},{"n":45,"t":"那些奉割禮的信徒和彼得同來，見聖靈的恩賜也澆在外邦人身上，就都驚奇；","notes":[]},{"n":46,"t":"因聽見他們說方言，稱讚神為大。於是彼得回答：","notes":["「方言」或譯「靈語」。"]},{"n":47,"t":"「這些人既受了聖靈，跟我們一樣，誰能阻止用水給他們施洗呢？」","notes":[]},{"n":48,"t":"他就吩咐奉耶穌基督的名給他們施洗。於是他們請彼得住了幾天。","notes":[]}]},"11":{"heading":"向耶路撒冷教會報告","verses":[{"n":1,"t":"使徒和在猶太的眾弟兄聽到外邦人也領受了神的道。","notes":[]},{"n":2,"t":"等到彼得上了耶路撒冷，那些奉割禮的信徒和他爭辯，","notes":[]},{"n":3,"t":"說：「你竟進入未受割禮之人當中，和他們一同吃飯！」","notes":[]},{"n":4,"t":"彼得就開始把這事逐一向他們解釋，說：","notes":[]},{"n":5,"t":"「我在約帕城裏禱告的時候，魂遊象外，看見異象，有一塊好像大布的東西降下，四角吊著從天縋下，直來到我跟前。","notes":[]},{"n":6,"t":"我定睛觀看，見內中有地上四腳的牲畜、野獸、爬蟲和天上的飛鳥。","notes":[]},{"n":7,"t":"我還聽見有聲音對我說：『彼得，起來！宰了吃。』","notes":[]},{"n":8,"t":"我說：『主啊，絕對不可！凡污俗或不潔淨的東西從來沒有進過我的口。』","notes":[]},{"n":9,"t":"第二次，有聲音從天上回答：『神所潔淨的，你不可當作污俗的。』","notes":[]},{"n":10,"t":"這樣一連三次，然後一切就都收回天上去了。","notes":[]},{"n":11,"t":"正當那時，有三個從凱撒利亞差來見我的人，站在我們所住的屋子門前。","notes":["有古卷是「我」。"]},{"n":12,"t":"聖靈吩咐我和他們同去，不要疑惑，還有這六位弟兄也跟我一起去，我們進了那人的家。","notes":[]},{"n":13,"t":"那人就告訴我們，他如何看見一位天使站在他家裏，說：『你派人往約帕去，請那稱為彼得的西門來，","notes":[]},{"n":14,"t":"他有話要告訴你，因這些話你和你的全家都可以得救。』","notes":[]},{"n":15,"t":"我一開始講話，聖靈就降在他們身上，正像當初降在我們身上一樣。","notes":[]},{"n":16,"t":"我就想起主的話如何說：『約翰用水施洗，但你們要在聖靈裏受洗。』","notes":[]},{"n":17,"t":"既然神給他們恩賜，像在我們信主耶穌基督的時候給了我們一樣，我是誰，能攔阻神嗎？」","notes":[]},{"n":18,"t":"眾人聽見這些話，就不說話了，只歸榮耀給神，說：「這樣看來，神也賜恩給外邦人，使他們悔改得生命了。」","notes":[]},{"n":19,"t":"那些因司提反的事遭患難而四處分散的門徒，直走到腓尼基、塞浦路斯和安提阿。他們不向別人講道，只向猶太人講。","notes":[],"heads":["安提阿的教會"]},{"n":20,"t":"但內中有塞浦路斯和古利奈人，他們到了安提阿也向希臘人傳講主耶穌的福音。","notes":["有古卷是「也向說希臘話的猶太人傳講主耶穌的福音」。"]},{"n":21,"t":"主的手與他們同在，信而歸主的人數很多。","notes":[]},{"n":22,"t":"這風聲傳到耶路撒冷教會的人耳中，他們就打發巴拿巴到安提阿去。","notes":[]},{"n":23,"t":"他到了那裏，看見神所賜的恩就歡喜，勸勉眾人要立定心志，恆久靠主。","notes":[]},{"n":24,"t":"這巴拿巴原是個好人，滿有聖靈和信心，於是有許多人歸服了主。","notes":[]},{"n":25,"t":"他又往大數去找掃羅，","notes":[]},{"n":26,"t":"找著了，就帶他到安提阿去。他們足有一年和教會一同聚集，教導了許多人。門徒稱為「基督徒」是從安提阿開始的。","notes":[]},{"n":27,"t":"當那些日子，有幾位先知從耶路撒冷下到安提阿。","notes":[]},{"n":28,"t":"內中有一位，名叫亞迦布，站起來，藉著聖靈指示普天下將有大饑荒；這事在克勞第年間果然實現了。","notes":[]},{"n":29,"t":"於是門徒決定，照各人的力量捐錢，送去供給住在猶太的弟兄。","notes":[]},{"n":30,"t":"他們就這樣做了，託巴拿巴和掃羅的手送到眾長老那裏。","notes":[]}]},"12":{"heading":"雅各被殺，彼得被囚","verses":[{"n":1,"t":"約在那時候，希律王下手苦待教會中的一些人，","notes":[]},{"n":2,"t":"用刀殺了約翰的哥哥雅各。","notes":[]},{"n":3,"t":"他見猶太人喜歡這事，也去拿住彼得。那時候正是除酵節期間。","notes":[]},{"n":4,"t":"希律捉了彼得，押在監裏，交給四班士兵看守，每班四個人，企圖要在逾越節後把他提出來，當著百姓辦他。","notes":[]},{"n":5,"t":"於是彼得被囚在監裏，教會卻為他切切禱告神。","notes":[]},{"n":6,"t":"希律將要提他出來的前一夜，彼得被兩條鐵鏈鎖著，睡在兩個士兵當中；門前還有警衛看守。","notes":[],"heads":["彼得獲救出監"]},{"n":7,"t":"忽然，有主的一個使者顯現，牢房裏有光照耀；天使拍彼得的肋旁，叫醒了他，說：「快起來！」鐵鏈就從他手上脫落下來。","notes":[]},{"n":8,"t":"天使對他說：「束上腰帶，穿上鞋子。」他就照著做了。天使又對他說：「披上外衣，跟我來。」","notes":[]},{"n":9,"t":"彼得就出來跟著他走，不知道天使所做是真的，以為見了異象。","notes":[]},{"n":10,"t":"他們經過了第一層和第二層監牢，就來到往城內的鐵門，那門就自動給他們開了。他們出來，走過一條街，忽然天使離開他去了。","notes":[]},{"n":11,"t":"彼得清醒過來，說：「現在我真知道主差遣他的使者，救我脫離希律的手，和猶太人所期待的一切。」","notes":[]},{"n":12,"t":"他明白了，就到那稱為馬可的約翰的母親馬利亞家去，在那裏已有好些人聚集禱告。","notes":[]},{"n":13,"t":"彼得敲外門時，有一個使女，名叫羅大，出來應門，","notes":[]},{"n":14,"t":"認出是彼得的聲音，歡喜得顧不了開門，就跑進去報信，說彼得站在門外。","notes":[]},{"n":15,"t":"他們對她說：「你瘋了！」使女堅持真有其事。他們說：「那是他的天使。」","notes":[]},{"n":16,"t":"彼得不停地敲門；他們開了門，一見是他，就很驚奇。","notes":[]},{"n":17,"t":"彼得做個手勢，要他們不作聲，就告訴他們主怎樣領他出監；又說：「你們要把這些事告訴雅各和眾弟兄。」然後，他離開往別處去了。","notes":[]},{"n":18,"t":"到了天亮，士兵中起了不少騷動，不知道彼得到哪裏去了。","notes":[]},{"n":19,"t":"希律找他，找不著，就審問警衛，下令帶走他們處死。後來希律離開猶太，下凱撒利亞去，住在那裏。","notes":[]},{"n":20,"t":"希律向推羅和西頓的人發怒。他們那一帶地方是從王的土地供應糧食的，因此就託了王的內侍大臣伯拉斯都的情，一心來求和。","notes":[],"heads":["希律之死"]},{"n":21,"t":"希律在所定的日子，穿上朝服，坐在位上，對他們演講。","notes":[]},{"n":22,"t":"民眾一直喊著：「這是神明的聲音，不是人的聲音。」","notes":[]},{"n":23,"t":"希律不歸榮耀給神，所以主的使者立刻擊打他，他被蟲咬，就斷了氣。","notes":[]},{"n":24,"t":"神的道日見興旺，越發廣傳。","notes":[]},{"n":25,"t":"巴拿巴和掃羅完成了供給的事，就回到耶路撒冷，帶著稱為馬可的約翰同去。","notes":["有古卷是「就從耶路撒冷回去」。"]}]},"13":{"heading":"巴拿巴和掃羅奉差遣","verses":[{"n":1,"t":"在安提阿的教會中，有幾位先知和教師，就是巴拿巴和稱為尼結的西面、古利奈人路求，與希律分封王一起長大的馬念，和掃羅。","notes":[]},{"n":2,"t":"他們在事奉主和禁食的時候，聖靈說：「要為我分派巴拿巴和掃羅去做我召他們做的工作。」","notes":[]},{"n":3,"t":"於是他們禁食禱告後，給巴拿巴和掃羅按手，然後派遣他們走了。","notes":[]},{"n":4,"t":"他們既蒙聖靈差遣，就下到西流基，從那裏坐船往塞浦路斯去，","notes":[],"heads":["在塞浦路斯傳道"]},{"n":5,"t":"到了撒拉米，就在猶太人各會堂裏宣講神的道，也有約翰作他們的幫手。","notes":[]},{"n":6,"t":"他們走遍全島，直到帕弗，在那裏遇見一個術士—猶太人的假先知，名叫巴耶穌。","notes":[]},{"n":7,"t":"這人常和士求‧保羅省長在一起。士求‧保羅是個通達人，他請巴拿巴和掃羅來，要聽神的道。","notes":[]},{"n":8,"t":"只是術士以呂馬(他的名字翻出來就是行法術的意思)敵對使徒，設法使省長遠離這信仰。","notes":[]},{"n":9,"t":"掃羅，又名保羅，被聖靈充滿，定睛看他，","notes":[]},{"n":10,"t":"說：「你這充滿各樣詭詐奸惡，魔鬼的兒子，一切正義的仇敵，你還不停止扭曲主的正道嗎？","notes":[]},{"n":11,"t":"現在你看，主的手臨到你身上，你會瞎眼，暫時看不見日光。」立刻迷濛和黑暗籠罩著他，他到處摸索，求人拉著手領他。","notes":[]},{"n":12,"t":"省長看見所發生的事就信了，因對主的教導感到驚奇。","notes":[]},{"n":13,"t":"保羅和他的同伴從帕弗開船，來到旁非利亞的別加，約翰卻離開他們，回耶路撒冷去了。","notes":[],"heads":["在彼西底的安提阿傳道"]},{"n":14,"t":"他們從別加往前行，來到彼西底的安提阿。在安息日，他們進了會堂就坐下。","notes":[]},{"n":15,"t":"在讀完了律法和先知的書，會堂主管們叫人過去，對他們說：「二位弟兄，你們若有甚麼勸勉眾人的話，請說。」","notes":[]},{"n":16,"t":"保羅就站起來，做個手勢，說：「諸位以色列人和一切敬畏神的人，請聽。","notes":[]},{"n":17,"t":"這以色列民的神揀選了我們的祖宗，當百姓寄居埃及的時候抬舉他們，用大能的手領他們從那地出來。","notes":[]},{"n":18,"t":"他在曠野容忍他們，約有四十年。","notes":["「容忍」：有古卷是「撫養」。"]},{"n":19,"t":"他消滅了迦南地七族的人後，把那地分給他們為業，","notes":[]},{"n":20,"t":"約有四百五十年。此後，他給他們設立士師，直到撒母耳先知的時候。","notes":["「約有…此後」：有古卷是「此後，約有四百五十年」。"]},{"n":21,"t":"從那時起，他們要求立一個王，神就將便雅憫支派中基士的兒子掃羅給他們作王，共四十年。","notes":[]},{"n":22,"t":"他廢了掃羅之後，就興起大衛作他們的王，又為他作見證說：『我尋得耶西的兒子大衛，他是合我心意的人，他要遵行我一切的旨意。』","notes":[]},{"n":23,"t":"從這人的後裔中，神已經照著所應許的為以色列人興起一位救主，就是耶穌。","notes":[]},{"n":24,"t":"在他沒有出來以前，約翰已向以色列全民宣講悔改的洗禮。","notes":[]},{"n":25,"t":"約翰快走完他的人生路程時，說：『你們以為我是誰？我不是；但是有一位在我以後來的，我就是解他腳上的鞋帶也不配。』","notes":["或譯「我不是基督」。"]},{"n":26,"t":"「諸位弟兄—亞伯拉罕的子孫和你們中間敬畏神的人哪，這救世的道是傳給我們的。","notes":[]},{"n":27,"t":"耶路撒冷的居民和他們的官長，因為不認識這基督，也不明白每安息日所讀的先知的書，把他定了死罪，正應驗了先知的預言。","notes":[]},{"n":28,"t":"雖然他們查不出他有該死的罪狀，還是要求彼拉多把他殺了。","notes":[]},{"n":29,"t":"他們既實現了經上指著他所記的一切話，就從木頭上把他取下來，放在墳墓裏。","notes":[]},{"n":30,"t":"神卻使他從死人中復活。","notes":[]},{"n":31,"t":"有許多日子，他向那些從加利利同他上耶路撒冷的人顯現，這些人如今在民間成為他的見證人。","notes":[]},{"n":32,"t":"我們報好信息給你們，就是那應許祖宗的話，","notes":[]},{"n":33,"t":"神已經向我們這些作他們兒女的應驗，使耶穌復活了。正如《詩篇》第二篇上記著：『你是我的兒子，我今日生了你。』","notes":["「向我們…兒女的」：有古卷是「向我們的兒女」。"]},{"n":34,"t":"論到神使他從死人中復活，不再歸於朽壞，他曾這樣說：『我必將所應許大衛那聖潔、可靠的恩典賜給你們。』","notes":[]},{"n":35,"t":"所以他也在另一篇說：『你必不讓你的聖者見朽壞。』","notes":[]},{"n":36,"t":"大衛在世的時候，遵行了神的旨意就長眠了，歸到他祖宗那裏，已見朽壞；","notes":["或譯「大衛按神的旨意服侍了那一世的人，就長眠了」。"]},{"n":37,"t":"惟獨神使他復活的那一位，他並未見朽壞。","notes":[]},{"n":38,"t":"所以弟兄們，你們當知道：赦罪的道是由這人傳給你們的，","notes":[]},{"n":39,"t":"你們靠摩西的律法在不得稱義的一切事上，每一個信靠這位耶穌的都得稱義了。","notes":[]},{"n":40,"t":"所以，你們要小心，免得先知書上所說的臨到你們：","notes":[]},{"n":41,"t":"『要觀看，你們這些藐視的人，要驚訝，要滅亡，因為在你們的日子，我行一件事，雖有人告訴你們，你們總是不信。』」","notes":[]},{"n":42,"t":"他們走出會堂的時候，眾人請他們在下一個安息日再講這些話給他們聽。","notes":[]},{"n":43,"t":"散會以後，有許多猶太人和敬虔的皈依猶太教的人跟從了保羅和巴拿巴。二人對他們講話，勸他們務要恆久倚靠神的恩典。","notes":[]},{"n":44,"t":"到下一個安息日，全城的人幾乎都聚集起來，要聽主的道。","notes":["有古卷是「神的道」；48節同。"]},{"n":45,"t":"但猶太人看見這麼多的人，就滿心嫉妒，辯駁保羅所說的話，並且毀謗他。","notes":[]},{"n":46,"t":"於是保羅和巴拿巴放膽說：「神的道本應先傳給你們；只因你們棄絕這道，斷定自己不配得永生，我們就轉向外邦人。","notes":[]},{"n":47,"t":"因為主曾這樣吩咐我們：『我已經立你作萬邦之光，使你施行我的救恩，直到地極。』」","notes":[]},{"n":48,"t":"外邦人聽見這話很歡喜，讚美主的道，凡被指定得永生的人都信了。","notes":[]},{"n":49,"t":"於是主的道傳遍了那一帶地方。","notes":[]},{"n":50,"t":"但猶太人挑唆虔敬尊貴的婦女和城內有名望的人，迫害保羅和巴拿巴，把他們趕出境外。","notes":[]},{"n":51,"t":"二人對著眾人跺掉腳上的塵土，然後往以哥念去了。","notes":[]},{"n":52,"t":"門徒滿心喜樂，又被聖靈充滿。","notes":[]}]},"14":{"heading":"在以哥念傳道","verses":[{"n":1,"t":"同樣的事也發生在以哥念。保羅和巴拿巴進了猶太人的會堂，在那裏講道，所以有很多猶太人和希臘人都信了。","notes":[]},{"n":2,"t":"但那不順從的猶太人煽動外邦人，使他們心裏仇恨弟兄。","notes":[]},{"n":3,"t":"二人在那裏住了好些日子，倚靠主放膽講道，主藉他們的手施行神蹟奇事，證明他恩惠的道。","notes":[]},{"n":4,"t":"城裏的眾人卻分裂了：有依附猶太人的，有依附使徒的。","notes":[]},{"n":5,"t":"那時，外邦人、猶太人和他們的官長，一齊擁上來，要凌辱使徒，用石頭打他們。","notes":[]},{"n":6,"t":"使徒知道了，就逃到呂高尼的路司得和特庇兩個城，以及周圍地方去，","notes":[]},{"n":7,"t":"在那裏繼續傳福音。","notes":[]},{"n":8,"t":"路司得城裏有一個兩腳無力的人，他從母腹裏就是瘸腿的，老是坐著，從來沒有走過。","notes":[],"heads":["在路司得傳道"]},{"n":9,"t":"他聽保羅講道；保羅定睛看他，見他有信心，可得痊癒，","notes":[]},{"n":10,"t":"就大聲說：「起來！兩腳站直。」那人就跳起來，開始行走。","notes":[]},{"n":11,"t":"眾人看見保羅所做的事，就用呂高尼話大聲說：「有神明藉著人形降臨在我們中間了。」","notes":[]},{"n":12,"t":"於是他們稱巴拿巴為宙斯，稱保羅為希耳米，因為他總是帶頭說話。","notes":[]},{"n":13,"t":"城外有宙斯廟的祭司牽著牛，拿著花環，來到門前，要同眾人一起獻祭。","notes":[]},{"n":14,"t":"巴拿巴和保羅二位使徒聽見，就撕開衣裳，跳進眾人中間，喊著：","notes":[]},{"n":15,"t":"「諸位，為甚麼做這些事呢？我們也是人，性情和你們一樣。我們傳福音給你們，是要你們離棄這些虛妄的事，歸向那創造天、地、海和其中萬物的永生的神。","notes":[]},{"n":16,"t":"他在從前的世代，任憑萬國各行其道；","notes":[]},{"n":17,"t":"然而他未嘗不為自己留下證據來，就如常行善事，從天降雨，賞賜豐年，使你們飲食飽足，滿心喜樂。」","notes":[]},{"n":18,"t":"二人說了這些話，總算攔住眾人不獻祭給他們。","notes":[]},{"n":19,"t":"但有些猶太人，從安提阿和以哥念來，挑唆眾人，並且用石頭打保羅，以為他死了，就把他拖到城外。","notes":[]},{"n":20,"t":"當門徒圍著他的時候，他站了起來，走進城去。第二天，保羅同巴拿巴往特庇去。","notes":[]},{"n":21,"t":"保羅和巴拿巴對那城裏的人傳了福音，使好些人成為門徒後，又回路司得、以哥念、安提阿去，","notes":[],"heads":["回到敘利亞的安提阿"]},{"n":22,"t":"堅固門徒的心，勸他們持守他們的信仰，說：「我們進入神的國，必須經歷許多艱難。」","notes":[]},{"n":23,"t":"二人在各教會中選立了長老，禁食禱告後，把他們交託給他們所信的主。","notes":[]},{"n":24,"t":"二人經過彼西底來到旁非利亞，","notes":[]},{"n":25,"t":"在別加講了道，就下亞大利去，","notes":[]},{"n":26,"t":"從那裏坐船回安提阿去。當初，眾人就在這地方，把他們交託在神的恩典中，要完成現在所做的工。","notes":[]},{"n":27,"t":"他們一到那裏，就聚集了會眾，述說神藉他們所行的一切事，並且神怎樣為外邦人開了信道的門。","notes":[]},{"n":28,"t":"二人在那裏同門徒住了一段日子。","notes":[]}]},"15":{"heading":"耶路撒冷會議","verses":[{"n":1,"t":"有幾個人從猶太下來，教導弟兄們說：「你們若不按照摩西的規矩受割禮，不能得救。」","notes":[]},{"n":2,"t":"保羅和巴拿巴跟他們發生了激烈的爭執和辯論；大家就決定指派保羅、巴拿巴和本會的幾個人，為所辯論的事上耶路撒冷去見使徒和長老。","notes":[]},{"n":3,"t":"於是教會為他們送行。他們經過腓尼基、撒瑪利亞，沿途敘說外邦人歸主的事，使眾弟兄都非常歡喜。","notes":[]},{"n":4,"t":"他們到了耶路撒冷，教會、使徒和長老都接待他們，他們就述說神同他們所做的一切事。","notes":[]},{"n":5,"t":"惟有幾個法利賽派的信徒起來，說：「必須給外邦人行割禮，吩咐他們遵守摩西的律法。」","notes":[]},{"n":6,"t":"使徒和長老聚集商議這事。","notes":[]},{"n":7,"t":"辯論了許久後，彼得站起來，對他們說：「諸位弟兄，你們知道神早已在你們中間揀選了我，讓外邦人從我口中得聽福音之道，而且相信。","notes":[]},{"n":8,"t":"知道人心的神也為他們作了見證，賜聖靈給他們，正如給我們一樣；","notes":[]},{"n":9,"t":"又藉著信潔淨了他們的心，他們和我們之間並沒有甚麼分別。","notes":[]},{"n":10,"t":"現在你們為甚麼試探神，要把我們祖宗和我們所不能負的軛放在門徒的頸項上呢？","notes":[]},{"n":11,"t":"相反地，我們相信，我們得救是因主耶穌的恩典，和他們一樣。」","notes":[]},{"n":12,"t":"眾人都默默無聲，聽巴拿巴和保羅述說神藉著他們在外邦人中所行的神蹟和奇事。","notes":[]},{"n":13,"t":"他們講完了，雅各回答說：「諸位弟兄，請聽我說。","notes":[]},{"n":14,"t":"剛才西門述說神當初怎樣眷顧外邦人，從他們中間選取人民歸於自己的名下；","notes":[]},{"n":15,"t":"眾先知的話也與這意思相符合。","notes":[]},{"n":16,"t":"正如經上所寫的：『此後，我要回來，重新修造大衛倒塌了的帳幕，從廢墟中重新修造，把它建立起來，","notes":[]},{"n":17,"t":"使剩餘的人，就是凡稱我名的外邦人，都尋求主。這話是自古以來顯明這些事的主說的。』","notes":[],"end":18},{"n":19,"t":"所以，我的意見是不可難為那歸向神的外邦人；","notes":[]},{"n":20,"t":"但是要寫信吩咐他們禁戒偶像所玷污的東西、血和勒死的牲畜，禁戒淫亂。","notes":["有古卷沒有「勒死的牲畜」﹔29節，21．25同。"]},{"n":21,"t":"因為歷代以來，摩西的書在各城都有人宣講，每逢安息日，也在會堂裏誦讀。」","notes":[]},{"n":22,"t":"那時，使徒、長老和全教會認為應從他們中間揀選人，差他們和保羅、巴拿巴一同到安提阿去，所揀選的就是稱為巴撒巴的猶大和西拉。這二人在弟兄中是領袖。","notes":[],"heads":["會議的覆函"]},{"n":23,"t":"他們帶去的信說：「使徒和作長老的弟兄們向安提阿、敘利亞、基利家外邦眾弟兄問安。","notes":[]},{"n":24,"t":"我們聽說，有幾個人從我們這裏出去，用一些話騷擾你們，使你們的心困惑，其實我們並沒有吩咐他們。","notes":["有古卷沒有「出去」。","有古卷加「說你們必須受割禮，守摩西的律法。」"]},{"n":25,"t":"我們認為，既然我們同心定意，就揀選幾個人，派他們同我們所親愛的巴拿巴和保羅到你們那裏去。","notes":[]},{"n":26,"t":"這二人曾為我主耶穌基督的名不顧自己的性命。","notes":[]},{"n":27,"t":"所以我們派猶大和西拉去，他們也會親口述說這些事。","notes":[]},{"n":28,"t":"因為聖靈和我們決定除了這幾件重要的事，不將別的重擔放在你們身上，","notes":[]},{"n":29,"t":"就是禁戒偶像所玷污的東西、血和勒死的牲畜，禁戒淫亂。這幾件你們若能自己禁戒就好了。祝你們安康！」","notes":[]},{"n":30,"t":"他們既奉了差遣就下安提阿去，聚集會眾，把書信交給他們。","notes":[]},{"n":31,"t":"眾人念了，因為信上鼓勵的話而感到欣慰。","notes":[]},{"n":32,"t":"猶大和西拉自己也是先知，就用許多話勸勉弟兄，堅固他們。","notes":[]},{"n":33,"t":"二人住了些日子，弟兄們打發他們平平安安地回到差遣他們的人那裏去。","notes":["有古卷加「34 惟有西拉決定仍住在那裏。」"]},{"n":35,"t":"但保羅和巴拿巴仍留在安提阿，和許多別的人一同教導，並傳揚主的道。","notes":[]},{"n":36,"t":"過了些日子，保羅對巴拿巴說：「讓我們回到從前宣揚主道的各城，看看弟兄們的情況如何。」","notes":[],"heads":["保羅和巴拿巴分手"]},{"n":37,"t":"巴拿巴有意要帶稱為馬可的約翰同去；","notes":[]},{"n":38,"t":"但保羅認為不宜帶他去，因為馬可從前在旁非利亞離開他們，不和他們一起工作。","notes":[]},{"n":39,"t":"於是二人起了爭執，甚至彼此分手。巴拿巴帶著馬可，坐船往塞浦路斯去；","notes":[]},{"n":40,"t":"保羅則揀選了西拉，也出發了，蒙弟兄們把他交於主的恩典中。","notes":[]},{"n":41,"t":"他就走遍了敘利亞、基利家，堅固眾教會。","notes":[]}]},"16":{"heading":"提摩太跟保羅和西拉同工","verses":[{"n":1,"t":"後來，保羅來到特庇，又到路司得。在那裏有一個門徒，名叫提摩太，是信主的猶太婦人的兒子，他父親卻是希臘人。","notes":[]},{"n":2,"t":"路司得和以哥念的弟兄都稱讚他。","notes":[]},{"n":3,"t":"保羅要帶他同去，只因那些地方的猶太人都知道他父親是希臘人，就給他行了割禮。","notes":[]},{"n":4,"t":"他們經過各城，把耶路撒冷使徒和長老所決定的規條交給門徒遵守。","notes":[]},{"n":5,"t":"於是眾教會信心越發堅固，人數天天增加。","notes":[]},{"n":6,"t":"因為聖靈禁止他們在亞細亞講道，他們就經過弗呂家、加拉太一帶地方。","notes":[],"heads":["保羅看見馬其頓人的異象"]},{"n":7,"t":"到了每西亞的邊界，他們想要往庇推尼去，耶穌的靈卻不許。","notes":[]},{"n":8,"t":"他們就越過每西亞，下特羅亞去。","notes":[]},{"n":9,"t":"夜間，有異象向保羅顯現。有一個馬其頓人站著求他說：「請你過來，到馬其頓來幫助我們！」","notes":[]},{"n":10,"t":"保羅既看見這異象，我們就立即設法往馬其頓去，認為神呼召我們傳福音給那裏的人。","notes":[]},{"n":11,"t":"我們從特羅亞開船，直行駛到撒摩特喇，第二天到了尼亞坡里；","notes":[],"heads":["呂底亞歸主"]},{"n":12,"t":"從那裏來到腓立比，就是馬其頓這一帶的一個重要城市，也是羅馬的駐防城。我們在這城裏住了幾天。","notes":["「這一帶…城市」：有古卷是「第一區的一個城市」。"]},{"n":13,"t":"在安息日，我們出城門，到了河邊，知道那裏有一個禱告的地方，我們就坐下來對那些聚會的婦女講道。","notes":["「知道…地方」：有古卷是「那裏是人們慣常禱告的地方」；另有古卷是「那裏被認為是個禱告的地方」。"]},{"n":14,"t":"有一個賣紫色布的婦人，名叫呂底亞，是推雅推喇城的人，素來敬拜神。她在聽著，主就開導她的心，使她留心聽保羅所講的話。","notes":[]},{"n":15,"t":"她和她一家都領了洗，就求我們說：「你們若以為我是真心信主的，請到我家裏來住。」於是她堅決請我們留下。","notes":["或譯「你們若以為我是忠心於主的」。"]},{"n":16,"t":"後來，我們往那禱告的地方去時，有一個被占卜的靈附身的使女迎面走來，她使用法術使她的主人們發了大財。","notes":[],"heads":["在腓立比被囚"]},{"n":17,"t":"她跟隨保羅和我們，喊著說：「這些人是至高神的僕人，對你們傳講救人的道路。」","notes":[]},{"n":18,"t":"她一連好幾天這樣喊叫，保羅就心中厭煩，轉身對那靈說：「我奉耶穌基督的名吩咐你從她身上出來！」那靈立刻出來了。","notes":[]},{"n":19,"t":"使女的主人們見發財的指望沒有了，就揪住保羅和西拉，拉他們到市上去見官；","notes":[]},{"n":20,"t":"又帶他們到行政官長們面前，說：「這些騷擾我們城的，他們是猶太人，","notes":[]},{"n":21,"t":"竟傳佈我們羅馬人所不可接受、不可遵守的規矩。」","notes":[]},{"n":22,"t":"群眾就一齊起來攻擊他們。官長們吩咐撕開他們的衣裳，用棍子打；","notes":[]},{"n":23,"t":"打了許多棍，就把他們下在監裏，囑咐獄警嚴緊看守。","notes":[]},{"n":24,"t":"獄警領了這樣的命令，就把他們下在內監，兩腳拴在木架上。","notes":[]},{"n":25,"t":"約在半夜，保羅和西拉正在禱告，唱詩讚美神，眾囚犯也側耳聽著的時候，","notes":[]},{"n":26,"t":"忽然，地大震動，甚至監牢的地基都搖動了，監門立刻全開，眾囚犯的鎖鏈也都解開了。","notes":[]},{"n":27,"t":"獄警一醒，看見監門全開，以為囚犯已經逃走，就拔刀要自殺。","notes":[]},{"n":28,"t":"保羅大聲呼叫：「不要傷害自己！我們都在這裏。」","notes":[]},{"n":29,"t":"獄警叫人拿燈來，就衝進去，戰戰兢兢地俯伏在保羅和西拉面前。","notes":[]},{"n":30,"t":"然後獄警領他們出來，說：「二位先生，我必須做甚麼才可以得救？」","notes":[]},{"n":31,"t":"他們說：「當信主耶穌，你和你一家都必得救。」","notes":["「你和你…得救」：原文直譯「你必得救，你的一家也是這樣」。"]},{"n":32,"t":"他們就把主的道講給他和他全家的人聽。","notes":[]},{"n":33,"t":"當夜，就在那時候，獄警把他們帶去，洗他們的傷；他和他所有的家人立刻都受了洗。","notes":[]},{"n":34,"t":"於是獄警領他們上自己的家裏去，給他們擺上飯。他和全家的人，因為信了神，都滿心喜樂。","notes":[]},{"n":35,"t":"到了天亮，官長們打發差役來，說：「釋放那兩個人吧。」","notes":[]},{"n":36,"t":"獄警就把這些話告訴保羅：「官長們打發人來，要釋放你們，現在可以出監，平平安安去吧。」","notes":[]},{"n":37,"t":"保羅卻說：「我們是羅馬人，並沒有定罪，他們竟在公眾面前打了我們，又把我們下在監裏；現在要私下趕我們出去嗎？這不行！叫他們自己來領我們出去吧！」","notes":[]},{"n":38,"t":"差役把這些話回稟官長們；官長們聽見他們是羅馬人，就害怕了，","notes":[]},{"n":39,"t":"於是來勸他們，領他們出來，請他們離開那城。","notes":[]},{"n":40,"t":"二人出了監牢，往呂底亞家裏去，見了弟兄們，勸慰他們一番，就離開了。","notes":[]}]},"17":{"heading":"帖撒羅尼迦的騷動","verses":[{"n":1,"t":"保羅和西拉經過暗妃坡里、亞波羅尼亞，來到帖撒羅尼迦，在那裏有猶太人的會堂。","notes":[]},{"n":2,"t":"保羅照他素常的規矩進去，一連三個安息日，根據聖經與他們辯論，","notes":[]},{"n":3,"t":"講解和說明基督必須受害，從死人中復活；又說：「我所傳給你們的這位耶穌就是基督。」","notes":[]},{"n":4,"t":"他們中間有些人聽了勸，就跟從保羅和西拉，還有許多虔敬的希臘人，尊貴的婦女也不少。","notes":[]},{"n":5,"t":"但不信的猶太人心裏嫉妒，聚集了些市井流氓，搭夥成群，煽動全城的人闖進耶孫的家，要把保羅和西拉帶到民眾那裏。","notes":[]},{"n":6,"t":"那些人找不著他們，就把耶孫和幾個弟兄拉到地方官那裏，喊叫著：「這些攪亂天下的人也到這裏來了，","notes":[]},{"n":7,"t":"耶孫竟收留他們。這些人都違背凱撒的命令，說另有一個王耶穌。」","notes":[]},{"n":8,"t":"眾人和地方官聽見這些話，就惶恐了，","notes":[]},{"n":9,"t":"於是收了耶孫和其餘的人的保證金後，釋放了他們。","notes":[]},{"n":10,"t":"當夜，弟兄們立刻送保羅和西拉往庇哩亞去；二人到了，就進入猶太人的會堂。","notes":[],"heads":["使徒們在庇哩亞傳道"]},{"n":11,"t":"這地方的猶太人比帖撒羅尼迦的人開明，熱心領受這道，天天查考聖經，要知道這道是否真實。","notes":[]},{"n":12,"t":"所以，他們中間有許多信了，又有希臘的尊貴婦人，男人也不少。","notes":[]},{"n":13,"t":"但帖撒羅尼迦的猶太人知道保羅又在庇哩亞傳神的道，就往那裏去，煽動挑撥群眾。","notes":[]},{"n":14,"t":"於是，弟兄們立刻送保羅到海邊去，西拉和提摩太卻仍留在庇哩亞。","notes":[]},{"n":15,"t":"護送保羅的人帶他到了雅典，他們領了保羅的命令，叫西拉和提摩太趕快到他那裏來，然後回去了。","notes":[]},{"n":16,"t":"保羅在雅典等候他們的時候，看見滿城都是偶像，就心裏非常難過。","notes":[],"heads":["保羅在雅典"]},{"n":17,"t":"於是他在會堂裏與猶太人和虔敬的人，以及每日在市場上所遇見的人辯論。","notes":[]},{"n":18,"t":"還有伊壁鳩魯和斯多亞兩派的哲學家也與他爭辯。有的說：「這胡言亂語的要說甚麼？」有的說：「他似乎是宣傳外邦鬼神的。」這是因保羅傳講耶穌與復活的福音。","notes":[]},{"n":19,"t":"他們就把他帶到亞略巴古，說：「你所講的這新學說，我們也可以知道嗎？","notes":[]},{"n":20,"t":"因為你有些奇怪的事傳到我們耳中，我們想知道這些事是甚麼意思。」","notes":[]},{"n":21,"t":"原來所有的雅典人和居住在那裏的外國人都無暇管別的事，只是談談或聽聽新聞。","notes":[]},{"n":22,"t":"保羅站在亞略巴古當中，說：「諸位雅典人！我看你們凡事很敬畏鬼神。","notes":[]},{"n":23,"t":"我到處走走的時候，仔細觀察你們所敬拜的，發現一座壇，上面寫著『獻給未識之神明』。你們所不認識而敬拜的，我現在向你們宣告：","notes":[]},{"n":24,"t":"他是創造宇宙和其中萬物的神；他既是天地的主，就不住在人手所造的殿宇裏，","notes":[]},{"n":25,"t":"也不用人手去服侍，好像缺少甚麼似的；自己倒將生命、氣息、萬物賜給萬人。","notes":[]},{"n":26,"t":"他從一人造出萬族，居住在全地面上，並且預先定準他們的年限和所住的疆界，","notes":["「人」：有古卷是「血脈」。"]},{"n":27,"t":"為要使他們尋求神，或者可以揣摩而找到他，其實他離我們各人不遠。","notes":[]},{"n":28,"t":"我們生活、行動、存在都在於他。就如你們的詩人也有人說：『我們也是他所生的。』","notes":[]},{"n":29,"t":"既然我們是神所生的，就不應該以為神的神性像人用手藝和心思所雕刻的金、銀、石像一般。","notes":[]},{"n":30,"t":"世人蒙昧無知的時候，神並不追究，如今卻吩咐各處的人都要悔改。","notes":[]},{"n":31,"t":"因為他已經定了日子，要藉著他所設立的人按公義審判天下，並且使他從死人中復活，給萬人作可信的憑據。」","notes":[]},{"n":32,"t":"眾人聽見死人復活的話，就有人譏誚他；又有人說：「我們會再聽你講這事。」","notes":[]},{"n":33,"t":"於是保羅從他們當中出去了。","notes":[]},{"n":34,"t":"但有幾個人依附他，信了主，其中有亞略巴古的議員丟尼修，和一個名叫大馬哩的婦人，還有幾個與他們一起的人。","notes":[]}]},"18":{"heading":"保羅在哥林多","verses":[{"n":1,"t":"這些事以後，保羅離開雅典，來到哥林多。","notes":[]},{"n":2,"t":"他遇見一個生在本都的猶太人，名叫亞居拉。不久前，他帶著妻子百基拉從意大利來，因為克勞第命令所有的猶太人都離開羅馬。保羅去投靠他們。","notes":[]},{"n":3,"t":"他們本是製造帳棚為業。保羅因與他們同業，就和他們同住，一同做工。","notes":[]},{"n":4,"t":"每逢安息日，保羅在會堂裏辯論，勸導猶太人和希臘人。","notes":[]},{"n":5,"t":"西拉和提摩太從馬其頓來的時候，保羅正專心傳道，向猶太人證明耶穌是基督。","notes":[]},{"n":6,"t":"當他們抗拒他、毀謗他的時候，他就抖掉衣裳的灰塵，對他們說：「你們的罪歸到你們自己的頭上，與我無干。從今以後，我要往外邦人那裏去。」","notes":[]},{"n":7,"t":"於是他離開那裏，到了一個人的家裏，他名叫提多‧猶士都，是敬拜神的人，他的家靠近會堂。","notes":["「提多‧猶士都」：有古卷是「猶士都」。"]},{"n":8,"t":"會堂的主管基利司布和全家都信了主，還有許多哥林多人聽了就信，而且受了洗。","notes":[]},{"n":9,"t":"夜間，主在異象中對保羅說：「不要怕，只管講，不要沉默，","notes":[]},{"n":10,"t":"有我與你同在，沒有人會下手害你，因為在這城裏有許多屬我的人。」","notes":[]},{"n":11,"t":"保羅在那裏住了一年六個月，將神的道教導他們。","notes":[]},{"n":12,"t":"到迦流作亞該亞省長的時候，猶太人齊心起來攻擊保羅，拉他到法庭，","notes":[]},{"n":13,"t":"說：「這個人教唆人不按著律法敬拜神。」","notes":[]},{"n":14,"t":"保羅剛要開口，迦流對猶太人說：「你們這些猶太人哪！如果是為冤枉或奸惡的事，我理當耐性聽你們。","notes":[]},{"n":15,"t":"既然你們所爭論的是關乎用字、名目和你們的律法，你們自己去辦吧！這樣的事我不願意審問。」","notes":[]},{"n":16,"t":"於是，他把他們逐出法庭。","notes":[]},{"n":17,"t":"眾人就揪住會堂的主管所提尼，在法庭前打他。這些事迦流都不管。","notes":[]},{"n":18,"t":"保羅又住了好些日子，就辭別了弟兄，坐船到敘利亞去。百基拉、亞居拉和他同去。他因為許過願，就在堅革哩剃了頭髮。","notes":[],"heads":["保羅回到安提阿"]},{"n":19,"t":"到了以弗所，保羅就把他們留在那裏，自己進了會堂，和猶太人辯論。","notes":[]},{"n":20,"t":"眾人請他多住些日子，他沒有答應，","notes":[]},{"n":21,"t":"就辭別他們，說：「神若許可，我還要回到你們這裏來。」於是他上船離開以弗所。","notes":[]},{"n":22,"t":"他在凱撒利亞下了船，上耶路撒冷去問候教會，隨後下安提阿去。","notes":[]},{"n":23,"t":"他在那裏住了些日子，又離開了那裏，逐一經過加拉太和弗呂家各地方，堅固眾門徒。","notes":[]},{"n":24,"t":"有一個生在亞歷山大的猶太人，名叫亞波羅，來到以弗所，他很有口才，很會講解聖經。","notes":[],"heads":["亞波羅在以弗所講道"]},{"n":25,"t":"這人已經在主的道路上受了訓練，心裏火熱，精確地講論和教導耶穌的事；可是他只知道約翰的洗禮。","notes":[]},{"n":26,"t":"他開始在會堂裏放膽講道；百基拉、亞居拉聽見，就接他來，將神的道路給他更精確地講解。","notes":["有古卷是「主的道路」。"]},{"n":27,"t":"他想要往亞該亞去，弟兄們就勉勵他，並寫信請門徒們接待他，他到了那裏，多多幫助那些蒙恩信主的人，","notes":[]},{"n":28,"t":"因為他在公眾面前極力駁倒猶太人，引聖經證明耶穌是基督。","notes":[]}]},"19":{"heading":"保羅在以弗所","verses":[{"n":1,"t":"亞波羅在哥林多的時候，保羅經過了內陸地區，來到以弗所，在那裏他遇見幾個門徒，","notes":[]},{"n":2,"t":"問他們：「你們信的時候領受了聖靈沒有？」他們說：「沒有，我們連甚麼是聖靈都沒有聽過。」","notes":[]},{"n":3,"t":"保羅說：「這樣，你們受的是甚麼洗呢？」他們說：「是受了約翰的洗。」","notes":[]},{"n":4,"t":"保羅說：「約翰所施的是悔改的洗禮，他告訴百姓當信那在他以後要來的那位，就是耶穌。」","notes":[]},{"n":5,"t":"他們聽見這話以後，就奉主耶穌的名受洗。","notes":[]},{"n":6,"t":"保羅給他們按手，聖靈就降在他們身上，他們開始說方言 和說預言。","notes":["「方言」或譯「靈語」。"]},{"n":7,"t":"他們約有十二個人。","notes":[]},{"n":8,"t":"保羅進會堂，一連三個月放膽講道，辯論神國的事，勸導眾人。","notes":[]},{"n":9,"t":"後來，有些人心裏剛硬不信，在眾人面前毀謗這道；保羅就離開他們，也叫門徒與他們分開，就在推喇奴的講堂天天辯論。","notes":[]},{"n":10,"t":"這樣有兩年之久，使一切住在亞細亞的，無論是猶太人是希臘人，都聽見主的道。","notes":[]},{"n":11,"t":"神藉保羅的手行了些奇異的神蹟，","notes":[],"heads":["士基瓦的兒子們"]},{"n":12,"t":"甚至有人從保羅身上拿走手巾或圍裙放在病人身上，病就消除了，邪靈也出去了。","notes":[]},{"n":13,"t":"那時，有幾個巡迴各處念咒趕鬼的猶太人，擅自利用主耶穌的名，向那些被邪靈所附的人說：「我奉保羅所傳的耶穌命令你們出來！」","notes":[]},{"n":14,"t":"做這事的是猶太祭司長士基瓦的七個兒子。","notes":[]},{"n":15,"t":"但邪靈回答他們：「耶穌我知道，保羅我也認識，你們卻是誰呢？」","notes":[]},{"n":16,"t":"被邪靈所附的人就撲到他們身上，制伏他們，勝過他們，使他們赤著身子，受了傷，從那房子裏逃出去了。","notes":[]},{"n":17,"t":"凡住在以弗所的，無論是猶太人是希臘人，都知道這件事，也都懼怕；主耶穌的名從此就更被尊為大了。","notes":[]},{"n":18,"t":"許多已經信的人來承認並公開自己所行的事。","notes":[]},{"n":19,"t":"又有許多平素行邪術的人把他們的書都拿來，堆積在眾人面前焚燒。他們計算書價，得知共值五萬塊銀錢。","notes":[]},{"n":20,"t":"這樣，主的道大大興旺，而且普遍傳開了。","notes":[]},{"n":21,"t":"這些事過後，保羅心裏決定要經過馬其頓、亞該亞，就往耶路撒冷去。他說：「我到了那裏以後，也必須到羅馬去看看。」","notes":[],"heads":["以弗所的暴動"]},{"n":22,"t":"於是他差遣兩個助手提摩太和以拉都往馬其頓去，自己暫時留在亞細亞。","notes":[]},{"n":23,"t":"那時，因這道路而起的騷動不小。","notes":[]},{"n":24,"t":"有一個銀匠，名叫底米丟，是製造亞底米神銀龕的，他使從事這手藝的人生意發達。","notes":[]},{"n":25,"t":"他聚集他們和同行的工人，說：「諸位，你們知道我們是倚靠這生意發財的。","notes":[]},{"n":26,"t":"你們看到，也聽見這保羅不但在以弗所，也幾乎在亞細亞全地，引誘迷惑了許多人，說：『人手所做的不是神明。』","notes":[]},{"n":27,"t":"這樣，不僅我們這行業陷入被藐視的危險，就是大女神亞底米的廟也要被人輕看，連亞細亞全地和普天下所敬拜的女神的威望也受損害了。」","notes":[]},{"n":28,"t":"眾人聽見，就怒氣沖沖，喊著說：「大哉，以弗所人的亞底米！」","notes":[]},{"n":29,"t":"於是滿城都騷動起來。眾人抓住與保羅同行的馬其頓人該猶和亞里達古，齊心衝進劇場。","notes":[]},{"n":30,"t":"保羅想要進到民眾那裏，門徒卻不許他去。","notes":[]},{"n":31,"t":"連亞細亞的幾位官員，是保羅的朋友，也打發人來勸他不要冒險到劇場裏去。","notes":[]},{"n":32,"t":"聚集的人亂成一團，有的喊這個，有的喊那個，大半不知道為了甚麼聚集。","notes":[]},{"n":33,"t":"猶太人把亞歷山大推出去，人群中有人慫恿他，他就做手勢，要向民眾申訴。","notes":[]},{"n":34,"t":"但他們一認出他是猶太人，大家就異口同聲喊著：「大哉，以弗所人的亞底米！」約喊了兩小時。","notes":[]},{"n":35,"t":"城裏的書記官安撫了群眾後，說：「以弗所人哪，誰不知道以弗所人的城是看守大亞底米的廟和從宙斯那裏落下來的像的守護者呢？","notes":[]},{"n":36,"t":"既然這些事是駁不倒的，你們就要安靜下來，不可妄動。","notes":[]},{"n":37,"t":"你們把這些人帶來，他們並沒有偷竊廟中之物，也沒有褻瀆我們的女神。","notes":[]},{"n":38,"t":"如果底米丟和他同行的手藝人有控告的事，自有公堂，也有省長，他們可以彼此控告。","notes":[]},{"n":39,"t":"你們若有別的事請求，可以在合法的集會裏解決。","notes":[]},{"n":40,"t":"今日的擾亂本是無緣無故的，有被控告的危險。這次的騷動，我們也說不出理由來。」","notes":[]},{"n":41,"t":"他說完這些話，就叫眾人散會。","notes":[]}]},"20":{"heading":"保羅再次訪問馬其頓和希臘","verses":[{"n":1,"t":"騷亂平定以後，保羅請門徒來，勸勉了他們，就辭別他們，往馬其頓去。","notes":[]},{"n":2,"t":"他走遍那一帶地方，用許多話勸勉門徒，然後來到希臘，","notes":[]},{"n":3,"t":"在那裏住了三個月。他快要坐船往敘利亞去的時候，猶太人設計害他，他就決定從馬其頓回去。","notes":[]},{"n":4,"t":"同他到亞細亞去的，有庇哩亞人畢羅斯的兒子所巴特，帖撒羅尼迦人亞里達古和西公都，還有特庇人該猶和提摩太，又有亞細亞人推基古和特羅非摩。","notes":[]},{"n":5,"t":"這些人先走，在特羅亞等候我們。","notes":[]},{"n":6,"t":"過了除酵節的日子，我們從腓立比開船，五天以後到了特羅亞，和他們相會，在那裏住了七天。","notes":[]},{"n":7,"t":"七日的第一日，我們聚會擘餅的時候，保羅因次日要起行，就為他們講道，直講到半夜。","notes":[],"heads":["保羅最後一次訪問特羅亞"]},{"n":8,"t":"我們聚會的那座樓上有好些燈火。","notes":[]},{"n":9,"t":"有一個少年，名叫猶推古，坐在窗口上，沉沉入睡。保羅講了多時，少年睡熟了，從三層樓上掉下去，扶起來時已經死了。","notes":[]},{"n":10,"t":"保羅下去，伏在他身上，抱著他，說：「你們不要慌亂，他還有氣呢！」","notes":[]},{"n":11,"t":"保羅又上樓去，擘餅，吃了，再講了許久，直到天亮才離開。","notes":[]},{"n":12,"t":"他們把那活過來的孩子帶走，大家得到很大的安慰。","notes":[]},{"n":13,"t":"我們先上船，起航往亞朔去，想要在那裏接保羅；因為他是這樣安排的，他自己本來打算要走陸路。","notes":[],"heads":["從特羅亞到米利都"]},{"n":14,"t":"他既在亞朔與我們相會，我們就接他上船，來到米推利尼。","notes":[]},{"n":15,"t":"我們從那裏開船，第二天到了基阿的對岸；再下一天，在撒摩靠岸，又過了一天，到了米利都。","notes":[]},{"n":16,"t":"因為保羅早已決定要越過以弗所，免得在亞細亞耽延，他急忙前行，假如可能的話，在五旬節前能趕到耶路撒冷。","notes":[]},{"n":17,"t":"保羅從米利都打發人往以弗所去，請教會的長老來。","notes":[],"heads":["保羅向以弗所長老講話"]},{"n":18,"t":"他們來了，保羅對他們說：「你們自己知道，自從我到亞細亞的第一天，我怎樣跟你們相處，","notes":[]},{"n":19,"t":"怎樣凡事謙卑，以眼淚服侍主，又因猶太人的謀害經歷試煉。","notes":[]},{"n":20,"t":"你們也知道，凡對你們有益的，我沒有一樣隱瞞不說的，或在公眾面前，或在每一個人的家裏，我都教導你們，","notes":[]},{"n":21,"t":"不論猶太人和希臘人，我都已證明他們當在神面前悔改，信靠我們的主耶穌。","notes":[]},{"n":22,"t":"現在我被聖靈催迫要往耶路撒冷去，雖然不知道在那裏會遭遇甚麼事，","notes":["「催迫」：原文直譯「捆綁」。"]},{"n":23,"t":"但知道聖靈在各城裏向我指證，說有捆鎖與患難等著我。","notes":[]},{"n":24,"t":"我卻不以性命為念，只要走完我的路程，完成我從主耶穌所領受的職分，為神恩典的福音作見證。","notes":[]},{"n":25,"t":"「我素常在你們中間到處傳講神的國；現在我知道，你們眾人以後不會再見到我的面了。","notes":[]},{"n":26,"t":"所以我今日向你們作證，你們中間無論何人死亡，罪不在我。","notes":[]},{"n":27,"t":"因為神一切的旨意，我並沒有退縮不傳給你們的。","notes":[]},{"n":28,"t":"聖靈立你們作全群的監督，你們就當為自己謹慎，也為全群謹慎，牧養神的教會，就是他用自己血所買來的。","notes":["「神」：有古卷是「主」；另有古卷是「主和神」。","「買來的」或譯「救贖的」。"]},{"n":29,"t":"我知道，在我離開以後必有兇暴的豺狼進入你們中間，不顧惜羊群。","notes":[]},{"n":30,"t":"就是你們中間也必有人起來，說悖謬的話，要引誘門徒跟從他們。","notes":[]},{"n":31,"t":"所以你們要警醒，記念我三年之久，晝夜不斷地流淚勸戒你們各人。","notes":[]},{"n":32,"t":"現在我把你們交託給神和他恩惠的道；這道能建立你們，使你們和一切成聖的人同得基業。","notes":[]},{"n":33,"t":"我未曾貪圖一個人的金、銀或衣服。","notes":[]},{"n":34,"t":"你們自己知道，我靠兩隻手工作來供給我和同工的需用。","notes":[]},{"n":35,"t":"我凡事給你們作榜樣，叫你們知道應當這樣勞苦，扶助軟弱的人，又當記念主耶穌的話，說：『施比受更為有福。』」","notes":[]},{"n":36,"t":"保羅說完了這些話，就和大家跪下來禱告。","notes":[]},{"n":37,"t":"眾人痛哭，抱著保羅的頸項跟他親吻。","notes":[]},{"n":38,"t":"叫他們最傷心的，就是他說「以後不會再見到我的面」那句話。於是他們送他上船去了。","notes":[]}]},"21":{"heading":"保羅上耶路撒冷","verses":[{"n":1,"t":"我們離別了眾人，就開船直航到哥士，第二天到了羅底，又從那裏到帕大喇。","notes":[]},{"n":2,"t":"我們遇見一隻船要往腓尼基去，就上船起航。","notes":[]},{"n":3,"t":"我們望見塞浦路斯，就從南邊行過，往敘利亞去，在推羅上岸，因為船要在那裏卸貨。","notes":[]},{"n":4,"t":"我們在那裏找到了一些門徒，就住了七天。他們藉著聖靈的感動，告訴保羅不要上耶路撒冷去。","notes":[]},{"n":5,"t":"幾天之後，我們又出發前行。他們眾人同妻子兒女都送我們到城外，我們都跪在灘上禱告，彼此辭別。","notes":[]},{"n":6,"t":"我們上了船，他們就回家去了。","notes":[]},{"n":7,"t":"我們從推羅行完航程，來到了多利買，問候那裏的弟兄，和他們同住了一天。","notes":[]},{"n":8,"t":"第二天，我們離開那裏，來到凱撒利亞，就進了傳福音的腓利家裏，和他同住；他是那七個執事裏的一個。","notes":[]},{"n":9,"t":"他有四個女兒，都是未出嫁的，都會說預言。","notes":[]},{"n":10,"t":"我們在那裏多住了好幾天，有一個先知，名叫亞迦布，從猶太下來。","notes":[]},{"n":11,"t":"他到了我們這裏，就拿保羅的腰帶，捆上自己的手腳，說：「聖靈這樣說：『猶太人在耶路撒冷要如此捆綁這腰帶的主人，把他交在外邦人手裏。』」","notes":[]},{"n":12,"t":"我們聽見這些話，就跟當地的人苦勸保羅不要上耶路撒冷去。","notes":[]},{"n":13,"t":"於是保羅回答：「你們為甚麼這樣痛哭，使我心碎呢？我為主耶穌的名，不但被人捆綁，就是死在耶路撒冷也是願意的。」","notes":[]},{"n":14,"t":"既然保羅不聽勸，我們就住了口，只說：「願主的旨意成就。」","notes":[]},{"n":15,"t":"過了這幾天，我們收拾行李上耶路撒冷去。","notes":[]},{"n":16,"t":"有凱撒利亞的幾個門徒和我們同去，帶我們到一個早期的門徒塞浦路斯人拿孫的家裏，請我們與他同住。","notes":[]},{"n":17,"t":"我們到了耶路撒冷，弟兄們歡歡喜喜地接待我們。","notes":[],"heads":["保羅訪問雅各"]},{"n":18,"t":"第二天，保羅同我們去見雅各；所有的長老也都在場。","notes":[]},{"n":19,"t":"保羅向他們問安，然後將神用他在外邦人中所做的事奉，一一述說了。","notes":[]},{"n":20,"t":"他們聽見了，就歸榮耀給神，對保羅說：「弟兄，你看猶太人中有數以萬計的信徒，而他們都是熱心於律法的人。","notes":[]},{"n":21,"t":"他們曾聽見人說，你教導所有在外邦的猶太人離棄摩西，對他們說，不要給孩子行割禮，也不要遵守規矩。","notes":[]},{"n":22,"t":"眾人必聽見你來了，這可怎麼辦呢？","notes":[]},{"n":23,"t":"你就照著我們的話做吧！我們這裏有四個人，都有願在身。","notes":[]},{"n":24,"t":"你帶他們去，與他們一同行潔淨的禮，替他們繳納規費，讓他們得以剃頭。這樣，眾人就會知道，先前所聽見關於你的事都是假的；而且也知道，你自己為人循規蹈矩，遵行律法。","notes":[]},{"n":25,"t":"至於信主的外邦人，我們已經根據我們的決議寫信，叫他們要禁戒偶像所玷污的東西、血和勒死的牲畜，禁戒淫亂。」","notes":["有古卷加「他們沒有甚麼可控告你。」"]},{"n":26,"t":"於是保羅帶著那四個人，第二天與他們一同行了潔淨禮，進了聖殿，報告潔淨期滿的日子，等候祭司為他們各人獻上祭物。","notes":[]},{"n":27,"t":"那七日將完，從亞細亞來的猶太人看見保羅在聖殿裏，就煽動所有的群眾，下手拿住他，","notes":[],"heads":["保羅在聖殿裏被捕"]},{"n":28,"t":"喊著：「以色列人哪，來幫忙！這就是在各處教導眾人糟蹋我們百姓、律法和這地方的人。不但如此，他還帶了希臘人進聖殿，污穢了這聖地。」","notes":[]},{"n":29,"t":"這話是因他們曾看見以弗所人特羅非摩跟保羅一起在城裏，以為保羅帶他進了聖殿。","notes":[]},{"n":30,"t":"於是全城都騷動，百姓一齊跑來，拿住保羅，拉他出聖殿，殿門立刻都關了。","notes":[]},{"n":31,"t":"他們正想要殺他，有人報信給營裏的千夫長，說耶路撒冷全城都亂了。","notes":[]},{"n":32,"t":"千夫長立刻帶著士兵和幾個百夫長，跑下去到他們那裏。他們見了千夫長和士兵，就停下來不打保羅。","notes":[]},{"n":33,"t":"於是千夫長上前拿住他，吩咐用兩條鐵鏈捆鎖，又問他是甚麼人，做了甚麼事。","notes":[]},{"n":34,"t":"群眾中有的喊這個，有的喊那個；因為這樣亂嚷，千夫長無法知道實情，就下令將保羅帶進營樓去。","notes":[]},{"n":35,"t":"保羅一走上臺階，群眾擠得兇猛，士兵只得將保羅抬起來。","notes":[]},{"n":36,"t":"一群人跟在後面，喊著：「除掉他！」","notes":[]},{"n":37,"t":"保羅快要被帶進營樓時，對千夫長說：「我可以對你說句話嗎？」千夫長說：「你懂得希臘話嗎？","notes":[],"heads":["保羅為自己辯護"]},{"n":38,"t":"那你就不是從前作亂、帶領四千兇徒往曠野去的那埃及人了。」","notes":[]},{"n":39,"t":"保羅說：「我本是猶太人，生在基利家的大數，並不是無名小城的公民。求你准我對百姓說話。」","notes":[]},{"n":40,"t":"千夫長准了。保羅就站在臺階上，向百姓做了個手勢，要他們靜下來，保羅就用希伯來話對他們說：","notes":[]}]},"22":{"heading":"保羅敘述歸主的經過","verses":[{"n":1,"t":"「諸位父老弟兄，請聽我現在對你們的申辯。」","notes":[]},{"n":2,"t":"他們聽保羅說的是希伯來話，就更加安靜了。","notes":[]},{"n":3,"t":"保羅說：「我原是猶太人，生在基利家的大數，但在這城裏長大，在迦瑪列門下按著我們祖宗嚴緊的律法受教，熱心事奉神，就如你們大家今日一樣。","notes":[]},{"n":4,"t":"我也曾迫害信奉這道路的人，置他們於死地，無論男女都捆綁，關在監裏。","notes":[]},{"n":5,"t":"這是大祭司和議會的眾長老都可以給我作證的。我又從他們那裏領了致弟兄們的書信，往大馬士革去，要把在那裏的信徒綁起來，帶到耶路撒冷受刑。」","notes":[]},{"n":6,"t":"「當我走近大馬士革的時候，約在中午，忽然有一道大光從天上下來，照射在我周圍。","notes":[]},{"n":7,"t":"我就仆倒在地，聽見有聲音對我說：『掃羅！掃羅！你為甚麼迫害我？』","notes":[]},{"n":8,"t":"我回答：『主啊！你是誰？』他對我說：『我就是你所迫害的拿撒勒人耶穌。』","notes":[]},{"n":9,"t":"跟我一起的人看見了那光，卻沒有聽見那位對我說話的聲音。","notes":[]},{"n":10,"t":"我說：『主啊，我該做甚麼？』主說：『起來，進大馬士革去，在那裏有人會把指派你做的一切事告訴你。』","notes":[]},{"n":11,"t":"我因那光的閃耀不能看見，跟我一起的人就拉著我的手進了大馬士革。","notes":[]},{"n":12,"t":"「那裏有一個人，名叫亞拿尼亞，按著律法是虔誠人，為所有住在那裏的猶太人所稱讚。","notes":[]},{"n":13,"t":"他來見我，站在旁邊，對我說：『掃羅弟兄，你看見吧！』就在那時，我恢復視覺，看見了他。","notes":[]},{"n":14,"t":"他又說：『我們祖宗的神揀選了你，讓你明白他的旨意，又看見那義者，聽見他口中所出的聲音。","notes":[]},{"n":15,"t":"因為你要將所看見的、所聽見的，對著萬人作他的見證人。","notes":[]},{"n":16,"t":"現在你為甚麼耽延呢？起來，受洗，求告他的名，洗去你的罪。』」","notes":[]},{"n":17,"t":"「後來，我回到耶路撒冷，在聖殿裏禱告的時候，魂遊象外，","notes":[],"heads":["保羅奉召向外邦人傳道"]},{"n":18,"t":"看見主對我說：『你趕緊離開耶路撒冷，越快越好，因為這裏的人不接受你為我作的見證。』","notes":[]},{"n":19,"t":"我就說：『主啊，他們都知道，我從前在各會堂裏把信你的人監禁，又鞭打他們。","notes":[]},{"n":20,"t":"當你的見證人司提反被害流血的時候，我也站在一旁贊同；又為打死他的人看守衣裳。』","notes":[]},{"n":21,"t":"主對我說：『你去吧！我要差你到遠方外邦人那裏去。』」","notes":[]},{"n":22,"t":"眾人聽他說到這句話，就高聲說：「這樣的人，從地上除掉他吧！他是該死的。」","notes":[],"heads":["保羅與長官交涉"]},{"n":23,"t":"大家一邊喧嚷一邊摔衣裳，向空中撒灰塵。","notes":[]},{"n":24,"t":"千夫長下令把保羅帶進營樓，叫人用鞭子拷問他，要知道他們向他這樣喧嚷是甚麼緣故。","notes":[]},{"n":25,"t":"他們剛用皮條把他捆上的時候，保羅對站在旁邊的百夫長說：「一個羅馬人，又未被定罪，你們就鞭打他是合法的嗎？」","notes":[]},{"n":26,"t":"百夫長聽見這話，就去見千夫長，報告說：「你要怎麼辦呢？這個人是羅馬人。」","notes":[]},{"n":27,"t":"千夫長就來問保羅：「你告訴我，你是羅馬人嗎？」保羅說：「是。」","notes":[]},{"n":28,"t":"千夫長回答：「我用了許多銀子才得到羅馬公民的身份。」保羅說：「我生來就是。」","notes":[]},{"n":29,"t":"於是那些要拷問保羅的人立刻離開他走了。千夫長一知道他是羅馬人，又因為曾捆綁了他，也害怕起來。","notes":[]},{"n":30,"t":"第二天，千夫長為要知道猶太人控告保羅的實情，就解開他，下令祭司長們和全議會的人都聚集，然後將保羅帶下來，叫他站在他們面前。","notes":[],"heads":["保羅在議會前申訴"]}]},"23":{"heading":"殺害保羅的陰謀","verses":[{"n":1,"t":"保羅定睛看著議會的人，說：「諸位弟兄，我在神面前，行事為人都是憑著清白的良心，直到今日。」","notes":[]},{"n":2,"t":"亞拿尼亞大祭司就吩咐旁邊站著的人打他的嘴。","notes":[]},{"n":3,"t":"這時，保羅對他說：「你這粉飾的牆，神要打你！你坐堂是要按律法審問我，你竟違背律法，命令人打我嗎？」","notes":[]},{"n":4,"t":"站在旁邊的人說：「你竟敢辱罵神的大祭司嗎？」","notes":[]},{"n":5,"t":"保羅說：「弟兄們，我不知道他是大祭司；因為經上記著：『不可毀謗你百姓的官長。』」","notes":[]},{"n":6,"t":"保羅看出他們一部分是撒都該人，一部分是法利賽人，就在議會中喊著：「諸位弟兄，我是法利賽人，也是法利賽人的子孫。我現在受審問是為有關死人復活的盼望。」","notes":[]},{"n":7,"t":"說了這話，法利賽人和撒都該人爭論起來，會眾分為兩派。","notes":[]},{"n":8,"t":"因為撒都該人一方面說沒有復活，另一方面沒有天使和鬼魂；法利賽人卻承認兩方面都有。","notes":[]},{"n":9,"t":"於是大大地爭吵起來；有幾個法利賽派的文士站起來爭辯說：「我們看不出這人有甚麼錯處；說不定有鬼魂或者天使對他說過話呢！」","notes":[]},{"n":10,"t":"那時爭辯越來越大，千夫長恐怕保羅被他們扯碎了，就命令士兵下去，把他從眾人當中搶出來，帶進營樓去。","notes":[]},{"n":11,"t":"當夜，主站在保羅旁邊，說：「放心吧！你怎樣在耶路撒冷為我作見證，也必怎樣在羅馬為我作見證。」","notes":[]},{"n":12,"t":"到了天亮，猶太人同謀起誓，說「若不先殺保羅就不吃不喝」。","notes":[]},{"n":13,"t":"參與這陰謀的有四十多人。","notes":[]},{"n":14,"t":"他們來見祭司長和長老，說：「我們已經發了重誓，若不先殺保羅就甚麼也不吃。","notes":[]},{"n":15,"t":"現在你們和議會要通知千夫長，叫他把保羅帶到你們這裏來，假裝要詳細調查他的事；我們已經預備好，在他來到這裏以前就殺掉他。」","notes":[]},{"n":16,"t":"保羅的外甥聽見他們設下埋伏，就來到營樓裏告訴保羅。","notes":[]},{"n":17,"t":"保羅請一個百夫長來，說：「你領這青年去見千夫長，他有事告訴他。」","notes":[]},{"n":18,"t":"於是百夫長把他領去見千夫長，說：「被囚的保羅請我到他那裏，求我領這青年來見你；他有事告訴你。」","notes":[]},{"n":19,"t":"千夫長就拉著他的手，走到一旁，私下問他：「你有甚麼事告訴我呢？」","notes":[]},{"n":20,"t":"他說：「猶太人已經約定，要求你明天把保羅帶到議會去，假裝要詳細查問他的事。","notes":[]},{"n":21,"t":"你切不要隨從他們，因為他們有四十多人埋伏，已經起誓，若不先殺掉保羅就不吃不喝。現在都預備好了，只等你的允准。」","notes":[]},{"n":22,"t":"於是千夫長打發那青年走，囑咐他：「不要告訴人，你已將這些事報告我了。」","notes":[]},{"n":23,"t":"於是，千夫長叫了兩個百夫長來，說：「預備步兵二百、騎兵七十、長槍手二百，今夜九點往凱撒利亞去；","notes":[],"heads":["保羅被解交腓力斯總督"]},{"n":24,"t":"也要預備牲口讓保羅騎上，護送到腓力斯總督那裏去。」","notes":[]},{"n":25,"t":"千夫長又寫了公文，大略說：","notes":[]},{"n":26,"t":"「克勞第‧呂西亞向腓力斯總督大人請安。","notes":[]},{"n":27,"t":"這個人被猶太人拿住，快被殺害時，我得知他是羅馬人，就帶士兵下去，把他救了出來。","notes":[]},{"n":28,"t":"因為我要知道他們告他的罪狀，就帶他下到他們的議會去。","notes":[]},{"n":29,"t":"我查知他被告發是因他們律法上的爭論，並沒有甚麼該死或該監禁的罪名。","notes":[]},{"n":30,"t":"後來有人把要害他的計謀告訴我，我立刻把他解到你那裏去，又命令告他的人在你面前告他。」","notes":["有古卷加「願你平安。」"]},{"n":31,"t":"於是士兵照所命令他們的，連夜把保羅帶到安提帕底。","notes":[]},{"n":32,"t":"第二天，由騎兵護送保羅，他們就回營樓去。","notes":[]},{"n":33,"t":"騎兵來到凱撒利亞，把公文呈給總督，就叫保羅站在他面前。","notes":[]},{"n":34,"t":"總督讀了公文，問保羅是哪一省的人；一知道他是基利家人，","notes":[]},{"n":35,"t":"就說：「等告你的人來到，我才詳細聽你。」於是他命令把保羅拘留在希律的衙門裏。","notes":[]}]},"24":{"heading":"猶太人控告保羅","verses":[{"n":1,"t":"過了五天，亞拿尼亞大祭司、幾個長老和一個叫帖土羅的律師下來，向總督控告保羅。","notes":[]},{"n":2,"t":"保羅一被傳來，帖土羅就開始控告他，說：「腓力斯大人，我們因你得以享受國泰民安，並且這一國的弊病，因著你的遠見得以改革。","notes":[]},{"n":3,"t":"我們隨時隨地都滿心感激不盡。","notes":[]},{"n":4,"t":"為了不敢耽擱你太久，我只求你寬容一下，聽我們說幾句話。","notes":[]},{"n":5,"t":"我們看這個人如同瘟疫一般，是鼓動普天下所有的猶太人作亂的人，又是拿撒勒教派裏的一個頭目。","notes":[]},{"n":6,"t":"他甚至連聖殿也要污穢，我們就把他捉拿了。","notes":["有古卷加「要按我們的律法審問，7 可是，呂西亞千夫長前來，甚是強橫，從我們手中把他奪去，下令告他的人到你這裏來。」"]},{"n":8,"t":"你自己審問他，就可以知道我們所控告他的一切事了。」","notes":[]},{"n":9,"t":"眾猶太人也隨著控告他，說：「這些事情確是這樣。」","notes":[]},{"n":10,"t":"總督示意叫保羅說話，保羅就回答：「我知道你在本國作法官多年，所以我樂意為自己申辯。","notes":[],"heads":["保羅為自己辯護"]},{"n":11,"t":"你查問就可以知道，從我上耶路撒冷去禮拜到今日不過十二天。","notes":[]},{"n":12,"t":"他們並沒有看見我在聖殿裏跟人辯論，或在會堂裏、在城裏煽動群眾。","notes":[]},{"n":13,"t":"也不能對你證實他們現在所控告我的事。","notes":[]},{"n":14,"t":"但有一件事我向你承認，就是我正按著他們所稱為異端的道事奉我祖宗的神，又信合乎律法和先知書上所記載的一切。","notes":[]},{"n":15,"t":"我對神存著這些人自己也接受的盼望，就是義人和不義的人都要復活。","notes":[]},{"n":16,"t":"因此，我勉勵自己，對神對人，時常存著無虧的良心。","notes":[]},{"n":17,"t":"過了幾年，我帶著賙濟本國的捐項和供物上去。","notes":[]},{"n":18,"t":"正獻的時候，他們看見我在聖殿裏已經潔淨了，並沒有聚眾，也沒有吵嚷，","notes":[]},{"n":19,"t":"惟有幾個從亞細亞來的猶太人—他們若有控告我的事，應當到你面前來告我。","notes":[]},{"n":20,"t":"不然，讓這些人自己說，他們看出我站在議會前的時候，有甚麼不對的地方。","notes":[]},{"n":21,"t":"縱然有，也不過是為了一句話，就是我站在他們中間喊說：『我今日在你們面前受審，是為了死人復活。』」","notes":[]},{"n":22,"t":"腓力斯本是詳細認識這道，就拖延他們，說：「且等呂西亞千夫長下來，我再審判你們的案。」","notes":[]},{"n":23,"t":"於是他下令百夫長看守保羅，要從寬待他，不可攔阻他的親友來供給他。","notes":[]},{"n":24,"t":"過了幾天，腓力斯和他夫人猶太女子土西拉一同來到，就叫保羅來，聽他講論信基督耶穌的事。","notes":[],"heads":["腓力斯留保羅在監裏"]},{"n":25,"t":"保羅講論公義、節制和將來的審判，腓力斯害怕起來，就回答：「你暫且去吧！等我有機會時再來叫你。」","notes":[]},{"n":26,"t":"腓力斯又指望保羅送他銀錢，所以屢次叫他來，和他談論。","notes":[]},{"n":27,"t":"過了兩年，波求‧非斯都接了腓力斯的任；腓力斯要討猶太人的喜歡，就把保羅留在監裏。","notes":[]}]},"25":{"heading":"保羅要向凱撒上訴","verses":[{"n":1,"t":"非斯都到省裏上任，過了三天，就從凱撒利亞上耶路撒冷去。","notes":[]},{"n":2,"t":"祭司長和猶太人的領袖向他控告保羅；又央求他，","notes":[]},{"n":3,"t":"向他求情要對付保羅，把他提到耶路撒冷來，他們要在路上埋伏殺害他。","notes":[]},{"n":4,"t":"非斯都就回答：「保羅押在凱撒利亞，我自己快要往那裏去。」","notes":[]},{"n":5,"t":"他又說：「所以，你們中間有權的人與我一同下去，那人若有甚麼不是，就讓他們控告他。」","notes":[]},{"n":6,"t":"非斯都在他們那裏住了不超過八天或十天，就下凱撒利亞去；第二天開庭，下令把保羅提上來。","notes":[]},{"n":7,"t":"保羅來了，那些從耶路撒冷下來的猶太人周圍站著，提出許多嚴重而不能證實的事控告他。","notes":[]},{"n":8,"t":"保羅申辯說：「無論猶太人的律法，或是聖殿，或是凱撒，我都沒有干犯。」","notes":[]},{"n":9,"t":"但非斯都要討猶太人的喜歡，就回答保羅說：「你願意上耶路撒冷去，在那裏為這些事受我的審判嗎？」","notes":[]},{"n":10,"t":"保羅說：「我現在站在凱撒的審判臺前，這就是我應當受審的地方。我並沒有對猶太人做過甚麼不對的事，這也是你明明知道的。","notes":[]},{"n":11,"t":"我若做了不對的事，犯了甚麼該死的罪，就是死我也不辭。他們所控告我的事若都不實，就沒有人能把我交給他們。我要向凱撒上訴。」","notes":[]},{"n":12,"t":"非斯都和議會商量了，就回答：「既然你要向凱撒上訴，你就到凱撒那裏去吧。」","notes":[]},{"n":13,"t":"過了些日子，亞基帕王和百妮基來到凱撒利亞，拜訪非斯都。","notes":[],"heads":["被帶到亞基帕百妮基前"]},{"n":14,"t":"他們在那裏住了好些日子，非斯都將保羅的案件向王陳述，說：「這裏有一個人，是腓力斯留在監裏的。","notes":[]},{"n":15,"t":"我在耶路撒冷的時候，祭司長和猶太的長老把他的事稟報了，要求定他的罪。","notes":[]},{"n":16,"t":"我回覆他們，無論甚麼人，被告還沒有和原告當面對質，沒有機會為所控告的事申辯，就先定他罪的，這不是羅馬人的規矩。","notes":[]},{"n":17,"t":"及至他們都來到這裏，我沒有耽誤，第二天就開庭，下令把那人提上來。","notes":[]},{"n":18,"t":"控告他的人站起來告他，所控告的並沒有任何我所預料的那等惡事。","notes":["有古卷沒有「那等惡」。"]},{"n":19,"t":"不過，有幾樣辯論是有關他們自己敬鬼神的事，以及一個名叫耶穌的人，他已經死了，保羅卻說他是活著的。","notes":[]},{"n":20,"t":"我對這些事不知該怎樣處理，所以問他是否願意上耶路撒冷去，在那裏為這些事接受審判。","notes":[]},{"n":21,"t":"但保羅要求我留下他，要聽皇上判斷，我就下令把他留下，等我解他到凱撒那裏去。」","notes":[]},{"n":22,"t":"亞基帕對非斯都說：「我也願意親自聽聽這個人。」非斯都說：「明天你就可以聽他。」","notes":[]},{"n":23,"t":"第二天，亞基帕和百妮基大張旗鼓而來，與眾千夫長和城裏的顯要進了大廳。非斯都一聲令下，就有人將保羅帶進來。","notes":[]},{"n":24,"t":"非斯都說：「亞基帕王和在這裏的諸位，你們看這個人，他就是所有在耶路撒冷和這裏的猶太人曾向我懇求呼叫，說不可容他再活著的。","notes":[]},{"n":25,"t":"但我查明他並沒有犯甚麼該死的罪，並且他自己也已向皇帝上訴了，所以我決定把他解去。","notes":[]},{"n":26,"t":"論到這個人，我沒有確實的事可以奏明主上。因此，我帶他到你們面前，尤其到你亞基帕王面前，為要在查問之後有所呈奏。","notes":[]},{"n":27,"t":"因為據我看，解送囚犯而不指明他的罪狀是不合理的。」","notes":[]}]},"26":{"heading":"保羅在亞基帕前申辯","verses":[{"n":1,"t":"亞基帕對保羅說：「准你為自己申訴。」於是保羅伸手辯護說：","notes":[]},{"n":2,"t":"「亞基帕王啊，猶太人所控告我的一切事，今日得以在你面前辯護，實為萬幸。","notes":[]},{"n":3,"t":"更慶幸的是你熟悉猶太人的規矩和他們的爭論；所以，求你耐心聽我。","notes":[]},{"n":4,"t":"「我自幼為人如何，從起初在本國的同胞中，以及在耶路撒冷，所有的猶太人都知道。","notes":[]},{"n":5,"t":"他們若肯作見證，就知道我從起初是按著我們教中最嚴緊的教門作了法利賽人。","notes":[]},{"n":6,"t":"現在我站在這裏受審，是為了對神向我們祖宗的應許存著盼望。","notes":[]},{"n":7,"t":"這應許，我們十二個支派，晝夜切切地事奉神，都指望得著。王啊，我正是因這指望被猶太人控告。","notes":[]},{"n":8,"t":"神使死人復活，你們為甚麼判斷為不可信呢？","notes":[]},{"n":9,"t":"「從前我自己認為必須竭力反對拿撒勒人耶穌的名，","notes":[]},{"n":10,"t":"我在耶路撒冷也曾這樣做過；我不但從祭司長得了權柄，把許多聖徒收在監裏，而且他們被殺，我也表示贊成。","notes":["「表示」可能是以投不同顏色的卵石來表示贊成或反對。"]},{"n":11,"t":"在各會堂，我屢次用刑強迫他們說褻瀆的話，我非常厭惡他們，甚至追逼他們，直到外邦的城鎮。」","notes":[]},{"n":12,"t":"「那時，我帶著祭司長的權柄和命令往大馬士革去。","notes":[],"heads":["保羅敘述歸主經過"]},{"n":13,"t":"王啊！我在路上，中午的時候，看見從天上有一道光，比太陽還亮，四面照射著我和跟我同行的人。","notes":[]},{"n":14,"t":"我們都仆倒在地，我就聽見有聲音用希伯來話對我說：『掃羅！掃羅！你為甚麼迫害我？你用腳踢刺棒是自找苦吃的！』","notes":[]},{"n":15,"t":"我說：『主啊，你是誰？』主說：『我就是你所迫害的耶穌。","notes":[]},{"n":16,"t":"起來，站著，我向你顯現的目的是要派你作僕役，為你所看見我的事，和我將要指示你的事作見證人。","notes":["有古卷沒有「我」。"]},{"n":17,"t":"我也要救你脫離百姓和外邦人的手。我差你到他們那裏去，","notes":[]},{"n":18,"t":"要開他們的眼睛，使他們從黑暗中轉向光明，從撒但權下歸向神；使他們因信我而得蒙赦罪，和一切成聖的人同得基業。』」","notes":[]},{"n":19,"t":"「因此，亞基帕王啊！我沒有違背那從天上來的異象；","notes":[],"heads":["保羅向猶太和外邦人作見證"]},{"n":20,"t":"我先在大馬士革，後在耶路撒冷和猶太全地，以及外邦，勸勉他們應當悔改歸向神，行事與悔改的心相稱。","notes":[]},{"n":21,"t":"為這緣故，猶太人在聖殿裏拿住我，想要殺我。","notes":[]},{"n":22,"t":"然而，我蒙神的幫助，直到今日還站立得穩，向尊貴的和卑微的作見證。我所講的，並不外乎眾先知和摩西所說將來必成的事，","notes":[]},{"n":23,"t":"就是基督必須受害，並且首先從死人中復活，把亮光傳給猶太人和外邦人。」","notes":[]},{"n":24,"t":"保羅這樣申訴時，非斯都大聲說：「保羅，你瘋了！你的學問太大，反使你瘋了！」","notes":[],"heads":["保羅懇請亞基帕信主"]},{"n":25,"t":"保羅說：「非斯都大人，我不是瘋了，我說的乃是真實和清醒的話。","notes":[]},{"n":26,"t":"王也知道這些事，所以對王大膽直言，我深信這些事沒有一件能向王隱瞞的，因為都不是在背地裏做的。","notes":[]},{"n":27,"t":"亞基帕王啊，你信先知嗎？我知道你是信的。」","notes":[]},{"n":28,"t":"亞基帕對保羅說：「你想稍微勸一勸就能說服我作基督徒了嗎？」","notes":[]},{"n":29,"t":"保羅說：「無論少勸還是多勸，我向神所求的，不但你一個人，就是今天所有聽我說話的人都要像我一樣，只是不要有這些鎖鏈。」","notes":[]},{"n":30,"t":"於是，王和總督以及百妮基跟同坐的人都站起來，","notes":[]},{"n":31,"t":"退到裏面，彼此談論說：「這個人並沒有犯甚麼該死該監禁的罪。」","notes":[]},{"n":32,"t":"亞基帕對非斯都說：「這人若沒有向凱撒上訴，早就被釋放了。」","notes":[]}]},"27":{"heading":"保羅坐船往羅馬","verses":[{"n":1,"t":"既然非斯都決定要我們坐船往意大利去，就將保羅和別的囚犯交給御營裏的一個名叫猶流的百夫長。","notes":[]},{"n":2,"t":"有一隻亞大米田的船要開往亞細亞沿海一帶地方去，我們上了那船，就起航了；有馬其頓的帖撒羅尼迦人亞里達古和我們同去。","notes":[]},{"n":3,"t":"第二天，我們到了西頓。猶流寬待保羅，准他往朋友那裏去，受他們的照應。","notes":[]},{"n":4,"t":"我們又從那裏開船，因為遇到逆風，就貼著塞浦路斯的背風岸航行，","notes":[]},{"n":5,"t":"渡過了基利家、旁非利亞一帶的海面，就到了呂家的每拉。","notes":[]},{"n":6,"t":"在那裏，百夫長找到一隻亞歷山大的船要往意大利去，就叫我們上了那船。","notes":[]},{"n":7,"t":"一連多日，船行得很慢，我們好不容易才來到革尼土的對面；又因被風攔阻，我們就貼著克里特島背風岸，從撒摩尼對面航行。","notes":[]},{"n":8,"t":"我們沿岸前進，十分艱難，來到一個名叫佳澳的地方，離那裏不遠有拉西亞城。","notes":[]},{"n":9,"t":"航行的日子久了，已經過了禁食的節期，行船又危險，保羅就建議，","notes":[]},{"n":10,"t":"對眾人說：「諸位，我看這次航行，不但貨物和船要受損傷，大遭破壞，連我們的性命也難保。」","notes":[]},{"n":11,"t":"但百夫長信從船長和船主，不信保羅所說的。","notes":[]},{"n":12,"t":"且因在這港口不適宜過冬，船上大多數的人都主張開船離開這地方，或者能到非尼基去過冬。非尼基是克里特的一個港口，一面朝西南，一面朝西北。","notes":[]},{"n":13,"t":"當南風微微吹起時，他們以為對目的地已有了把握，就起錨，貼近克里特開去。","notes":[],"heads":["海上的風暴"]},{"n":14,"t":"過了不久，有一股叫「友拉革羅」的東北巨風從島上撲來，","notes":[]},{"n":15,"t":"船被風抓住，無法頂風航行，我們只好任它漂流。","notes":[]},{"n":16,"t":"我們貼著一個叫高大的小島的背風岸急航，好不容易才保住了救生艇。","notes":[]},{"n":17,"t":"既然把救生艇拉上來，他們就用纜索捆綁船底，又恐怕在賽耳底淺灘上擱淺，就落了篷，任船漂流。","notes":[]},{"n":18,"t":"我們被風浪逼得很急，第二天眾人就把貨物拋在海裏。","notes":[]},{"n":19,"t":"第三天，他們又親手把船上的器具拋棄了。","notes":[]},{"n":20,"t":"許多天都沒有看到太陽和星辰，又有狂風大浪催逼，我們獲救的指望都放棄了。","notes":[]},{"n":21,"t":"眾人已有好幾天沒有吃東西，保羅就出來站在他們中間，說：「諸位，你們本該聽我的話不離開克里特島，就不致遭到這樣的損失和破壞。","notes":[]},{"n":22,"t":"現在我勸你們放心，除了損失這條船，你們中間沒有一人會喪失性命。","notes":[]},{"n":23,"t":"因為昨夜，我所屬所事奉的神的使者站在我旁邊，","notes":[]},{"n":24,"t":"說：『保羅，不要害怕，你必定站在凱撒面前；並且神已把安全賜給與你同船的人了。』","notes":[]},{"n":25,"t":"所以，諸位可以放心，我信神怎樣對我說，事情也要怎樣成就；","notes":[]},{"n":26,"t":"只是我們必須在一個島上擱淺。」","notes":[]},{"n":27,"t":"到了第十四天夜間，船在亞得里亞海漂來漂去。約在半夜，水手以為漸近旱地，","notes":[]},{"n":28,"t":"就去探測深淺，探得有十二丈；稍往前行，又探深淺，探得有九丈。","notes":["「丈」：參「度量衡表」；下同。"]},{"n":29,"t":"恐怕我們撞到礁石，他們就從船尾拋下四個錨，盼望天亮。","notes":[]},{"n":30,"t":"水手想棄船逃走，把救生艇縋下海裏，假裝要從船頭拋錨的樣子。","notes":[]},{"n":31,"t":"保羅對百夫長和士兵說：「這些人若不留在船上，你們就不能獲救。」","notes":[]},{"n":32,"t":"於是士兵砍斷救生艇的繩子，由它漂去。","notes":[]},{"n":33,"t":"天快亮的時候，保羅勸眾人都用餐，說：「你們一直捱餓等候，不吃甚麼，已經十四天了。","notes":[]},{"n":34,"t":"所以我勸你們吃點東西，這是關乎你們獲救的，因為你們各人連一根頭髮也不至於掉落。」","notes":[]},{"n":35,"t":"保羅說了這話，就拿起餅來，在眾人面前祝謝了神，然後擘開來吃。","notes":[]},{"n":36,"t":"於是他們都放心，就吃了。","notes":[]},{"n":37,"t":"我們在船上的共有二百七十六個人。","notes":[]},{"n":38,"t":"他們吃飽了，為要使船輕一點，就把船上的麥子拋到海裏。","notes":[]},{"n":39,"t":"天亮的時候，他們不認得那地方，只見一個有岸可登的海灣，就想法子看能不能把船靠岸。","notes":[],"heads":["船擱了淺"]},{"n":40,"t":"於是他們砍斷纜索，把錨丟到海裏，同時也鬆開舵繩，拉起頭篷，順風向著岸行去。","notes":[]},{"n":41,"t":"但碰到兩水夾流的地方，就擱了淺，船頭膠住不動，船尾被浪的猛力衝壞了。","notes":["「船尾…衝壞了」：有古卷是「船尾被猛力衝壞了」；另有古卷是「船尾被浪衝壞了」。"]},{"n":42,"t":"士兵的意思要把囚犯都殺了，免得有游水脫逃的。","notes":[]},{"n":43,"t":"但百夫長要救保羅，不准他們任意而行，就吩咐會游水的，跳下水去，先上岸；","notes":[]},{"n":44,"t":"其餘的人則用板子或船的碎片上岸。這樣，眾人都獲救，上了岸。","notes":[]}]},"28":{"heading":"保羅在馬耳他島上","verses":[{"n":1,"t":"我們既已獲救，才知道那島名叫馬耳他。","notes":[]},{"n":2,"t":"當地人非常友善地接待我們；因為正在下雨，天氣又冷，他們就生了火歡迎我們眾人。","notes":[]},{"n":3,"t":"那時，保羅拾起一捆柴，放在火中，有一條毒蛇，因為熱的緣故鑽了出來，纏住他的手。","notes":[]},{"n":4,"t":"當地的人看見那毒蛇懸在他手上，就彼此說：「這人必是個兇手，雖然他從海裏獲救，天理仍不容他活著。」","notes":[]},{"n":5,"t":"保羅竟把那毒蛇甩在火裏，並沒有受傷。","notes":[]},{"n":6,"t":"當地的人想他快要腫起來，或是忽然倒下死了，但等了好久，見他沒有甚麼異樣，就轉念說他是個神明。","notes":[]},{"n":7,"t":"離那地方不遠有一些田產，是島長部百流的。他接納我們，盡情款待了我們三日。","notes":[]},{"n":8,"t":"當時，部百流的父親臥病不起，患了熱病和痢疾。保羅進去見他，為他禱告按手，治好了他。","notes":[]},{"n":9,"t":"從此，島上其餘的病人也都來，得了醫治。","notes":[]},{"n":10,"t":"他們又多方面尊敬我們，到了開船的時候，又把我們所需用的東西送到船上。","notes":[]},{"n":11,"t":"過了三個月，我們上了亞歷山大的船起航。這船以「宙斯雙子」為記，是在那海島過冬的。","notes":[],"heads":["保羅抵達羅馬"]},{"n":12,"t":"我們到了敘拉古，停泊了三日；","notes":[]},{"n":13,"t":"又從那裏起錨開船，來到利基翁。過了一天，起了南風，第二天就來到部丟利。","notes":["有古卷是「從那裏繞道航行」。"]},{"n":14,"t":"我們在那裏遇見一些弟兄，他們請我們同住了七天。就這樣，我們來到羅馬。","notes":[]},{"n":15,"t":"那裏的弟兄們一聽見我們的消息，就到亞比烏市和三館來迎接我們。保羅見了他們，就感謝神，越發壯膽。","notes":[]},{"n":16,"t":"我們進了羅馬城，保羅蒙准和那個看守他的兵另住在一處。","notes":["有古卷加「百夫長把眾囚犯交給御營的統領，惟有」。"]},{"n":17,"t":"過了三天，保羅請當地猶太人的領袖來。他們來了，保羅對他們說：「諸位弟兄，雖然我沒有做甚麼事干犯本國的百姓和我們祖宗的規矩，卻在耶路撒冷被囚禁，交在羅馬人的手裏。","notes":[],"heads":["保羅在羅馬傳道"]},{"n":18,"t":"他們審問了我，有意要釋放我，因為在我身上並沒有該死的罪狀。","notes":[]},{"n":19,"t":"但猶太人反對，我不得已只好上訴於凱撒，並不是有甚麼事要控告我本國的百姓。","notes":[]},{"n":20,"t":"為這緣故，我請你們來見我當面談話，我原是為以色列人所指望的那位才被這鐵鏈捆綁的。」","notes":[]},{"n":21,"t":"他們對他說：「我們並沒有接到從猶太寄來有關於你的信，也沒有弟兄到這裏來向我們報告，或說你有甚麼不好的地方。","notes":[]},{"n":22,"t":"但我們願意聽聽你的意見，因為我們知道這教門是到處遭人反對的。」","notes":[]},{"n":23,"t":"他們和保羅約定了日子，就有許多人到他的住處來。保羅從早到晚向他們講解這事，為神的國作證，並引摩西的律法和先知的書勸導他們信從耶穌。","notes":[]},{"n":24,"t":"他所說的話，有的信，有的不信。","notes":[]},{"n":25,"t":"他們間彼此不合，就分散了；未散以先，保羅說了一句話：「聖靈藉以賽亞先知向你們祖宗所說的話是對的。","notes":[]},{"n":26,"t":"他說：『你去對這百姓說：你們聽了又聽，卻不明白；看了又看，卻看不清。","notes":[]},{"n":27,"t":"因為這百姓的心麻木，耳朵塞著，眼睛閉著，免得眼睛看見，耳朵聽見，心裏明白，回轉過來，我會醫治他們。』","notes":[]},{"n":28,"t":"所以，你們當知道，神這救恩已經傳給外邦人；他們會聽的。」","notes":["有古卷在此加「29 保羅說了這些話，猶太人議論紛紛地走了。」"]},{"n":30,"t":"保羅在自己所租的房子裏住了足足兩年。凡來見他的人，他都接待，","notes":[]},{"n":31,"t":"放膽傳講神的國，並教導主耶穌基督的事，沒有人禁止。","notes":[]}]}},"ROM":{"1":{"heading":"問候與祝願","verses":[{"n":1,"t":"基督耶穌的僕人保羅，蒙召為使徒，奉派傳神的福音。","notes":[]},{"n":2,"t":"這福音是神從前藉眾先知，在聖經上所應許的。","notes":[]},{"n":3,"t":"論到他兒子－我主耶穌基督，按肉體說，是從大衛後裔生的；按神聖的靈說，因從死人中復活，用大能顯明他是神的兒子。","notes":[],"end":4},{"n":5,"t":"我們從他蒙恩受了使徒的職分，為他的名在萬國中使人因信而順服，","notes":[]},{"n":6,"t":"其中也有你們這蒙召屬耶穌基督的人。","notes":[]},{"n":7,"t":"我寫信給你們在羅馬、為神所愛、蒙召作聖徒的眾人。願恩惠、平安從我們的父神和主耶穌基督歸給你們！","notes":["「平安」或譯「和平」。"]},{"n":8,"t":"首先，我靠著耶穌基督，為你們眾人感謝我的神，因你們的信德傳遍了天下。","notes":[],"heads":["保羅有意訪問羅馬"]},{"n":9,"t":"我在他兒子的福音上，用心靈所事奉的神可以見證，我怎樣不住地提到你們，","notes":[]},{"n":10,"t":"在我的禱告中常常懇求，或許照神的旨意，最終我能毫無阻礙地往你們那裏去。","notes":[]},{"n":11,"t":"因為我迫切地想見你們，要把一些屬靈的恩賜分給你們，使你們得以堅固，","notes":[]},{"n":12,"t":"也可以說，我在你們中間，因你我彼此的信心而同得安慰。","notes":[]},{"n":13,"t":"弟兄們，我不願意你們不知道，我屢次計劃往你們那裏去，要在你們中間得些果子，如同在其餘的外邦人中一樣，只是到如今仍有攔阻。","notes":[]},{"n":14,"t":"無論是希臘人、未開化的人、聰明人、愚拙人，我都欠他們的債，","notes":[]},{"n":15,"t":"所以願意盡我的力量把福音也傳給你們在羅馬的人。","notes":[]},{"n":16,"t":"我不以福音為恥；這福音本是神的大能，要救一切相信的，先是猶太人，後是希臘人。","notes":[],"heads":["福音是神的大能"]},{"n":17,"t":"因為神的義正在這福音上顯明出來；這義是本於信，以至於信。如經上所記：「義人必因信得生。」","notes":[]},{"n":18,"t":"原來，神的憤怒從天上顯明在一切不虔不義的人身上，就是那些行不義壓制真理的人。","notes":[],"heads":["人類的罪惡"]},{"n":19,"t":"神的事情，人所能知道的，原顯明在人心裏，因為神已經向他們顯明。","notes":[]},{"n":20,"t":"自從造天地以來，神的永能和神性是明明可知的，雖然眼不能見，但藉著所造之物就可以了解看見，叫人無可推諉。","notes":[]},{"n":21,"t":"因為，他們雖然知道神，卻不把他當作神榮耀他，也不感謝他。他們的思想變為虛妄，無知的心昏暗了。","notes":[]},{"n":22,"t":"他們自以為聰明，反成了愚昧，","notes":[]},{"n":23,"t":"將不能朽壞之神的榮耀變為偶像，仿照必朽壞的人、飛禽、走獸、爬蟲的形像。","notes":[]},{"n":24,"t":"所以，神任憑他們隨著心裏的情慾行污穢的事，以致彼此羞辱自己的身體。","notes":[]},{"n":25,"t":"他們將神的真實變為虛謊，去敬拜事奉受造之物，不敬奉那造物的主—主是可稱頌的，直到永遠。阿們！","notes":[]},{"n":26,"t":"因此，神任憑他們放縱可羞恥的情慾。他們的女人把自然的關係變成違反自然的；","notes":[]},{"n":27,"t":"男人也是如此，放棄了和女人自然的關係，慾火攻心，男的和男的彼此貪戀，行可恥的事，就在自己身上受這逆性行為當得的報應。","notes":[]},{"n":28,"t":"他們既然故意不認識神，神就任憑他們存扭曲的心，做那些不該做的事，","notes":[]},{"n":29,"t":"裝滿了各樣不義、邪惡、貪婪、惡毒，滿心是嫉妒、兇殺、紛爭、詭詐、毒恨，又是毀謗的、","notes":["有古卷加「淫亂」。"]},{"n":30,"t":"說人壞話的、怨恨神的、侮辱人的、狂傲的、自誇的、製造是非的、忤逆父母的、","notes":["「怨恨神的」或譯「被神所憎惡的」。"]},{"n":31,"t":"頑梗不化的、言而無信的、無情無義的、不憐憫人的。","notes":[]},{"n":32,"t":"他們雖知道神判定做這樣事的人是該死的，然而他們不但自己去做，還贊同別人去做。","notes":[]}]},"2":{"heading":"神的公義審判","verses":[{"n":1,"t":"所以，你這評斷人的人哪，無論你是誰，都無可推諉。你在甚麼事上評斷人，就在甚麼事上定自己的罪。因你這評斷人的，自己所做的卻和別人一樣。","notes":[]},{"n":2,"t":"我們知道這樣做的人，神必公平地審判他。","notes":[]},{"n":3,"t":"你這個人哪，你評斷做這樣事的人，自己所做的卻和別人一樣，你以為能逃脫神的審判嗎？","notes":[]},{"n":4,"t":"還是你藐視他豐富的恩慈、寬容、忍耐，不知道他的恩慈是領你悔改嗎？","notes":[]},{"n":5,"t":"你竟放任你剛硬不悔改的心，為自己累積憤怒！在憤怒的日子，神公義的審判要顯示出來。","notes":[]},{"n":6,"t":"他要照各人的行為報應各人。","notes":[]},{"n":7,"t":"凡恆心行善，尋求榮耀、尊貴和不能朽壞的，就有永生報償他們；","notes":[]},{"n":8,"t":"但是那些自私自利、不順從真理、反順從不義的人，就有惱恨、憤怒報應他們。","notes":[]},{"n":9,"t":"他要把患難、困苦加給一切作惡的人，先是猶太人，後是希臘人；","notes":[]},{"n":10,"t":"卻把榮耀、尊貴、平安加給一切行善的人，先是猶太人，後是希臘人。","notes":[]},{"n":11,"t":"因為神不偏待人。","notes":[]},{"n":12,"t":"凡在律法之外犯了罪的，將在律法之外滅亡；凡在律法之內犯了罪的，將按律法受審判。","notes":[]},{"n":13,"t":"原來在神面前，不是聽律法的為義，而是行律法的稱義。","notes":[]},{"n":14,"t":"沒有律法的外邦人若順著本性行律法上的事，他們雖然沒有律法，自己就是自己的律法。","notes":[]},{"n":15,"t":"他們顯明律法的功用刻在他們心裏，他們的良心一同作證—他們的內心掙扎，有時自責，有時為自己辯護。","notes":[]},{"n":16,"t":"在那日，神要藉著基督耶穌，按照我所傳的福音，審判人隱藏的事。","notes":["「基督耶穌」：有古卷是「耶穌基督」。"]},{"n":17,"t":"但是你，你既自稱為猶太人，倚靠律法，以神誇口，","notes":[],"heads":["猶太人與律法"]},{"n":18,"t":"知道神的旨意，從律法受了教導而能分辨是非；","notes":[]},{"n":19,"t":"你既深信自己是給盲人領路的，是在黑暗中人的光，","notes":[]},{"n":20,"t":"是無知的人的師傅，是小孩子的老師，體現了律法中的知識和真理；","notes":[]},{"n":21,"t":"那麼，你這教導別人的，還不教導自己嗎？你這宣講不可偷竊的，自己還偷竊嗎？","notes":[]},{"n":22,"t":"你這說不可姦淫的，自己還姦淫嗎？你這厭惡偶像的，自己還搶劫廟中之物嗎？","notes":[]},{"n":23,"t":"你這以律法誇口的，自己倒違犯律法，羞辱神！","notes":[]},{"n":24,"t":"神的名在外邦人中因你們受了褻瀆，正如經上所記的。","notes":[]},{"n":25,"t":"你若遵行律法，割禮固然於你有益；若違犯律法，你的割禮就算不得割禮。","notes":[]},{"n":26,"t":"所以，那未受割禮的，若遵守律法的要求，他雖然未受割禮，豈不算是受了割禮嗎？","notes":[]},{"n":27,"t":"而且那本來未受割禮的，若能全守律法，豈不是要審判你這有儀文和割禮，竟違犯律法的人嗎？","notes":[]},{"n":28,"t":"因為外表是猶太人的不是真猶太人；外表肉身的割禮也不是真割禮。","notes":[]},{"n":29,"t":"惟有內心作猶太人的才是真猶太人，真割禮也是心裏的，在乎聖靈，不在乎儀文。這樣的人所受的稱讚不是從人來的，而是從神來的。","notes":["「聖靈」或譯「靈」。"]}]},"3":{"heading":"沒有義人","verses":[{"n":1,"t":"這樣說來，猶太人有甚麼比別人強呢？割禮有甚麼益處呢？","notes":[]},{"n":2,"t":"很多，各方面都有。首先，神的聖言交託他們。","notes":[]},{"n":3,"t":"即使有不信的，這又何妨呢？難道他們的不信就廢掉神的信實嗎？","notes":[]},{"n":4,"t":"絕對不會！不如說，神是真實的，而人都是虛謊的。如經上所記：「以致你責備的時候顯為公義；你被指控的時候一定勝訴。」","notes":[]},{"n":5,"t":"我姑且照著人的看法來說，我們的不義若顯出神的義來，我們要怎麼說呢？神降怒是他不義嗎？","notes":[]},{"n":6,"t":"絕對不是！若是這樣，神怎能審判世界呢？","notes":[]},{"n":7,"t":"若神的真實因我的虛謊越發顯出他的榮耀，為甚麼我還像罪人一樣受審判呢？","notes":[]},{"n":8,"t":"為甚麼不說，我們可以作惡以成善呢？有人毀謗我們，說我們講過這話；這等人被定罪是應該的。","notes":[]},{"n":9,"t":"那又怎麼樣呢？我們比他們強嗎？絕不是！因我們已經指證：猶太人和希臘人都在罪惡之下。","notes":[]},{"n":10,"t":"就如經上所記：「沒有義人，連一個也沒有。","notes":[]},{"n":11,"t":"沒有明白的，沒有尋求神的。","notes":[]},{"n":12,"t":"人人偏離正路，一同走向敗壞。沒有行善的，連一個也沒有。","notes":["「沒有行善…沒有」：有古卷是「連一個行善的也沒有」。"]},{"n":13,"t":"他們的喉嚨是敞開的墳墓；他們的舌頭玩弄詭詐。他們的嘴唇裏有毒蛇的毒液，","notes":[]},{"n":14,"t":"滿口是咒罵苦毒。","notes":[]},{"n":15,"t":"他們的腳為殺人流血飛跑；","notes":[]},{"n":16,"t":"他們的路留下毀壞和災難。","notes":[]},{"n":17,"t":"和平的路，他們不認識；","notes":[]},{"n":18,"t":"他們眼中不怕神。」","notes":[]},{"n":19,"t":"我們知道律法所說的話都是對律法之下的人說的，好塞住各人的口，使普世的人都伏在神的審判之下。","notes":[]},{"n":20,"t":"所以，凡血肉之軀沒有一個能因律法的行為而在神面前稱義，因為律法本是要人認識罪。","notes":[]},{"n":21,"t":"但如今，神的義在律法之外已經顯明出來，有律法和先知為證：","notes":[],"heads":["因信稱義"]},{"n":22,"t":"就是神的義，因信耶穌基督加給一切信的人。這並沒有分別，","notes":["「因信耶穌基督」或譯「藉耶穌基督的信」。"]},{"n":23,"t":"因為世人都犯了罪，虧缺了神的榮耀，","notes":[]},{"n":24,"t":"如今卻蒙神的恩典，藉著在基督耶穌裏的救贖，就白白地得稱為義。","notes":[]},{"n":25,"t":"神設立耶穌作贖罪祭，是憑耶穌的血，藉著信，要顯明神的義；因為他用忍耐的心寬容人先前所犯的罪，好使今時顯明他的義，讓人知道他自己為義，也稱信耶穌的人為義。","notes":["「也稱…為義」或譯「也稱本著耶穌之信的人為義」。"],"end":26},{"n":27,"t":"既是這樣，哪裏可誇口呢？沒有可誇的。是藉甚麼法呢？功德嗎？不是！是藉信主之法。","notes":[]},{"n":28,"t":"所以我們認定，人稱義是因著信，不在於律法的行為。","notes":[]},{"n":29,"t":"難道神只是猶太人的嗎？不也是外邦人的嗎？是的，他也是外邦人的神。","notes":[]},{"n":30,"t":"既然神是一位，他就要本於信稱那受割禮的為義，也要藉著信稱那未受割禮的為義。","notes":[]},{"n":31,"t":"這樣，我們藉著信廢了律法嗎？絕對不是！更是鞏固律法。","notes":[]}]},"4":{"heading":"亞伯拉罕的榜樣","verses":[{"n":1,"t":"這樣，那按肉體作我們祖宗的亞伯拉罕，我們要怎麼說呢？","notes":[]},{"n":2,"t":"倘若亞伯拉罕是因行為稱義，他就有可誇的，但是在神面前他一無可誇。","notes":[]},{"n":3,"t":"經上說甚麼呢？「亞伯拉罕信了神，這就算他為義。」","notes":[]},{"n":4,"t":"做工的得工資不算是恩典，而是應得的；","notes":[]},{"n":5,"t":"但那不做工的，只信那位稱不敬虔之人為義的，他的信就算為義。","notes":[]},{"n":6,"t":"正如大衛稱那在行為之外蒙神算為義的人是有福的：","notes":[]},{"n":7,"t":"「過犯得赦免，罪惡蒙遮蓋的人有福了！","notes":[]},{"n":8,"t":"主不算為有罪的，這樣的人有福了！」","notes":[]},{"n":9,"t":"如此看來，這福只加給那受割禮的人嗎？不也加給那未受割禮的人嗎？我們說，因著信，就算亞伯拉罕為義。","notes":[]},{"n":10,"t":"那麼，這是怎麼算的呢？是在他受割禮的時候呢？還是在他未受割禮的時候呢？不是在受割禮的時候，而是在未受割禮的時候。","notes":[]},{"n":11,"t":"並且，他受了割禮的記號，作他未受割禮的時候因信稱義的印證，為使他作一切未受割禮而信之人的父，使他們也算為義，","notes":[]},{"n":12,"t":"也使他作受割禮之人的父，就是那些不但受割禮，而且跟隨我們的祖宗亞伯拉罕未受割禮而信的足跡的人。","notes":[]},{"n":13,"t":"因為神給亞伯拉罕和他後裔承受世界的應許不是藉著律法，而是藉著信而得的義。","notes":[],"heads":["應許因信而實現"]},{"n":14,"t":"若是屬於律法的人才是後嗣，信就落空了，應許也就失效了。","notes":[]},{"n":15,"t":"因為律法是惹動憤怒的，哪裏沒有律法，哪裏就沒有過犯。","notes":[]},{"n":16,"t":"所以，人作後嗣是出於信，因此就屬乎恩，以致應許保證歸給所有的後裔，不但歸給那屬於律法的，也歸給那效法亞伯拉罕之信的人。亞伯拉罕所信的是那叫死人復活、使無變為有的神，在這位神面前亞伯拉罕成為我們眾人的父，如經上所記：「我已經立你作多國之父。」","notes":[],"end":17},{"n":18,"t":"他在沒有盼望的時候，仍存著盼望來相信，就得以作多國之父，正如先前所說：「你的後裔將要如此。」","notes":[]},{"n":19,"t":"他將近百歲的時候，雖然想到自己的身體如同已死，撒拉也不可能生育，他的信心還是不軟弱，","notes":["「雖然想到」：有古卷是「不顧念」。"]},{"n":20,"t":"仍仰望神的應許，總沒有因不信而起疑惑，反倒因信而剛強，將榮耀歸給神，","notes":[]},{"n":21,"t":"且滿心相信神所應許的必能成就。","notes":[]},{"n":22,"t":"所以這也就算他為義。","notes":["有古卷沒有「也」。"]},{"n":23,"t":"「算他為義」這句話不是單為他寫的，","notes":[]},{"n":24,"t":"也是為我們將來得算為義的人寫的，就是為我們這些信神使我們的主耶穌從死人中復活的人寫的。","notes":[]},{"n":25,"t":"耶穌被出賣，是為我們的過犯；他復活，是為使我們稱義。","notes":[]}]},"5":{"heading":"因信稱義的福","verses":[{"n":1,"t":"所以，我們既因信稱義，就藉著我們的主耶穌基督得以與神和好。","notes":[]},{"n":2,"t":"我們又藉著他，因信得以進入現在所站立的這恩典中，並且歡歡喜喜盼望神的榮耀。","notes":["有古卷沒有「因信」。"]},{"n":3,"t":"不但如此，就是在患難中也是歡歡喜喜的，因為知道患難生忍耐，","notes":[]},{"n":4,"t":"忍耐生老練，老練生盼望，","notes":[]},{"n":5,"t":"盼望不至於落空，因為神的愛，已藉著所賜給我們的聖靈，澆灌在我們心裏。","notes":[]},{"n":6,"t":"我們還軟弱的時候，基督就在特定的時刻為不敬虔之人死。","notes":[]},{"n":7,"t":"為義人死，是少有的；為仁人死，或者有敢做的。","notes":[]},{"n":8,"t":"惟有基督在我們還作罪人的時候為我們死，神的愛就在此向我們顯明了。","notes":[]},{"n":9,"t":"現在我們既靠著他的血稱義，就更要藉著他得救，免受神的憤怒。","notes":[]},{"n":10,"t":"因為我們作仇敵的時候，尚且藉著神兒子的死得以與神和好，既已和好，就更要因他的生得救了。","notes":[]},{"n":11,"t":"不但如此，我們既藉著我們的主耶穌基督得以與神和好，也就藉著他以神為樂。","notes":[]},{"n":12,"t":"為此，正如罪是從一人進入世界，死又從罪而來，於是死就臨到所有的人，因為人人都犯了罪。","notes":[],"heads":["亞當和基督"]},{"n":13,"t":"沒有律法之前，罪已經在世上，但沒有律法，罪也不算罪。","notes":[]},{"n":14,"t":"然而，從亞當到摩西，死就掌了權，連那些不與亞當犯一樣罪過的，也在死的權下。亞當是那以後要來之人的預像。","notes":[]},{"n":15,"t":"但是過犯不如恩賜，若因一人的過犯，眾人都死了，那麼，神的恩典，與那因耶穌基督一人而來的恩典中的賞賜，豈不加倍地臨到眾人嗎？","notes":[]},{"n":16,"t":"因一人犯罪而來的後果，也不如賞賜，原來審判是由一人而定罪，恩賜乃是由許多過犯而稱義。","notes":[]},{"n":17,"t":"若因一人的過犯，死就因這一人掌權，那些受洪恩又蒙所賜之義的，豈不更要因耶穌基督一人在他們生命中掌權嗎？","notes":[]},{"n":18,"t":"這樣看來，因一次的過犯，所有的人都被定罪；照樣，因一次的義行，所有的人也就被稱義而得生命了。","notes":[]},{"n":19,"t":"因一人的悖逆，眾人成為罪人；照樣，因一人的順從，眾人也成為義了。","notes":[]},{"n":20,"t":"而且加添了律法，使得過犯增加，只是罪在哪裏增加，恩典就在哪裏越發豐盛了。","notes":[]},{"n":21,"t":"所以，正如罪藉著死掌權；照樣，恩典也藉著義掌權，使人因我們的主耶穌基督得永生。","notes":[]}]},"6":{"heading":"對罪死，在基督裏活","verses":[{"n":1,"t":"這樣，我們要怎麼說呢？我們可以仍在罪中使恩典增多嗎？","notes":[]},{"n":2,"t":"絕對不可！我們向罪死了的人，豈可仍在罪中活著呢？","notes":[]},{"n":3,"t":"難道你們不知道，我們這受洗歸入基督耶穌的人，就是受洗歸入他的死嗎？","notes":[]},{"n":4,"t":"所以，我們藉著洗禮歸入死，和他一同埋葬，是要我們行事為人都有新生的樣子，像基督藉著父的榮耀從死人中復活一樣。","notes":[]},{"n":5,"t":"我們若與他合一，經歷與他一樣的死，也將經歷與他一樣的復活。","notes":[]},{"n":6,"t":"我們知道，我們的舊人和他同釘十字架，使罪身滅絕，叫我們不再作罪的奴隸，","notes":[]},{"n":7,"t":"因為已死的人是脫離了罪。","notes":[]},{"n":8,"t":"我們若與基督同死，我們信也必與他同活，","notes":[]},{"n":9,"t":"因為知道基督既從死人中復活，就不再死，死也不再作他的主了。","notes":[]},{"n":10,"t":"他死了，是對罪死，只這一次；他活，是對神活著。","notes":[]},{"n":11,"t":"這樣，你們也要看自己對罪是死的，在基督耶穌裏對神卻是活的。","notes":[]},{"n":12,"t":"所以，不要讓罪在你們必死的身上掌權，使你們順從身體的私慾。","notes":[]},{"n":13,"t":"也不要把你們的肢體獻給罪作不義的工具，倒要像從死人中活著的人，把自己獻給神，並把你們的肢體獻給神作義的工具。","notes":[]},{"n":14,"t":"罪必不能作你們的主，因你們不在律法之下，而是在恩典之下。","notes":[]},{"n":15,"t":"那又怎麼樣呢？我們在恩典之下，不在律法之下，就可以犯罪嗎？絕對不可！","notes":[],"heads":["義的奴僕"]},{"n":16,"t":"難道你們不知道，你們獻自己作奴僕，順從誰就作誰的奴僕嗎？或作罪的奴隸，以至於死；或作順服的奴僕，以至於成義。","notes":[]},{"n":17,"t":"感謝神！因為你們從前雖然作罪的奴隸，現在卻從心裏順服了所傳給你們教導的典範。","notes":[]},{"n":18,"t":"你們既從罪裏得了釋放，就作了義的奴僕。","notes":[]},{"n":19,"t":"我因你們肉體的軟弱，就以人的觀點來說。你們從前怎樣把肢體獻給不潔不法作奴隸，以至於不法；現在也要照樣將肢體獻給義作奴僕，以至於成聖。","notes":[]},{"n":20,"t":"因為你們作罪的奴隸時，不被義所約束。","notes":[]},{"n":21,"t":"那麼，你們現在所看為羞恥的事，當時有甚麼果子呢？那些事的結局就是死。","notes":[]},{"n":22,"t":"但如今，你們既從罪裏得了釋放，作了神的奴僕，就結出果子，以至於成聖，那結局就是永生。","notes":[]},{"n":23,"t":"因為罪的工價乃是死；惟有神的恩賜，在我們的主基督耶穌裏，乃是永生。","notes":[]}]},"7":{"heading":"律法的約束力","verses":[{"n":1,"t":"弟兄們，我對你們這些明白律法的人說，你們豈不知道律法約束人是在他活著的時候嗎？","notes":[]},{"n":2,"t":"就如女人有了丈夫，丈夫還活著，她就被律法約束；丈夫若死了，她就從丈夫的律法中解脫了。","notes":[]},{"n":3,"t":"所以丈夫還活著，她若跟了別的男人，就叫淫婦；丈夫若死了，她就脫離了律法，雖然跟了別的男人，也不是淫婦。","notes":[]},{"n":4,"t":"我的弟兄們，這樣說來，你們藉著基督的身體對律法也是死了，使你們歸於另一位，就是歸於那從死人中復活的，為要使我們結果子給神。","notes":[]},{"n":5,"t":"因為我們屬肉體的時候，那因律法而生犯罪的慾望在我們肢體中發動，以致結出死亡的果子。","notes":[]},{"n":6,"t":"但如今，我們既然在捆綁我們的律法上死了，就從律法中解脫，使我們服侍主，要按著聖靈的新樣，不按著儀文的舊樣。","notes":["「聖靈」或譯「靈」。"]},{"n":7,"t":"這樣，我們要怎麼說呢？律法是罪嗎？絕對不是！但是，若不是藉著律法，我就不知何為罪；若不是律法說「不可貪心」，我就不知何為貪心。","notes":[],"heads":["律法與罪的關係"]},{"n":8,"t":"然而，罪趁著機會，藉著誡命，使各樣的貪心在我裏頭發動，因為沒有律法，罪是死的。","notes":[]},{"n":9,"t":"以前沒有律法的時候，我是活的；但是誡命來到，罪活起來，","notes":[]},{"n":10,"t":"我就死了。那本該叫人活的誡命反而叫我死。","notes":[]},{"n":11,"t":"因為罪趁著機會，藉著誡命誘惑我，並且藉著誡命殺了我。","notes":[]},{"n":12,"t":"這樣看來，律法是聖的，誡命也是聖的、義的、善的。","notes":[]},{"n":13,"t":"那麼，那善的是叫我死嗎？絕對不是！叫我死的是罪。罪藉著那善的叫我死，為要顯出這真是罪，以致罪藉著誡命更顯出是惡極了。","notes":[]},{"n":14,"t":"我們原知道律法是屬靈的，我卻是屬肉體的，是已經賣給罪了。","notes":[],"heads":["靈與肉的交戰"]},{"n":15,"t":"因為我所做的，我自己不明白。我所願意的，我並不做；我所恨惡的，我反而去做。","notes":[]},{"n":16,"t":"如果我所做的是我所不願意的，我得承認律法是善的。","notes":[]},{"n":17,"t":"事實上，這不是我做的，而是住在我裏面的罪做的。","notes":[]},{"n":18,"t":"我也知道，住在我裏面的，就是我肉體之中，沒有善。因為立志為善由得我，只是行出來由不得我。","notes":[]},{"n":19,"t":"我所願意的善，我不去做；我所不願意的惡，我反而去做。","notes":[]},{"n":20,"t":"如果我去做我不願意做的，就不是我做的，而是住在我裏面的罪做的。","notes":[]},{"n":21,"t":"我覺得有個律，就是我願意行善的時候，就有惡纏著我。","notes":[]},{"n":22,"t":"因為，按著我裏面的人，我喜歡神的律，","notes":[]},{"n":23,"t":"但我看出肢體中另有個律和我內心的律交戰，把我擄去，使我附從那肢體中罪的律。","notes":[]},{"n":24,"t":"我真苦啊！誰能救我脫離這必死的身體呢？","notes":[]},{"n":25,"t":"感謝神，靠著我們的主耶穌基督就能！這樣看來，一方面，我內心順服神的律，另一方面，肉體卻順服罪的律了。","notes":[]}]},"8":{"heading":"在聖靈裏的生活","verses":[{"n":1,"t":"如今，那些在基督耶穌裏的人就不被定罪了。","notes":[]},{"n":2,"t":"因為賜生命的聖靈的律，在基督耶穌裏從罪和死的律中把你釋放出來。","notes":[]},{"n":3,"t":"律法既因肉體軟弱而無能為力，神就差遣自己的兒子成為罪身的樣子，為了對付罪，在肉體中定了罪，","notes":["「為了對付罪」或譯「作了贖罪祭」。"]},{"n":4,"t":"為要使律法要求的義，實現在我們這不隨從肉體、只隨從聖靈去行的人身上。","notes":[]},{"n":5,"t":"因為，隨從肉體的人體貼肉體的事；隨從聖靈的人體貼聖靈的事。","notes":[]},{"n":6,"t":"體貼肉體就是死；體貼聖靈就是生命和平安。","notes":["「平安」或譯「和平」。"]},{"n":7,"t":"因為體貼肉體就是與神為敵，對神的律法不順服，事實上也無法順服。","notes":[]},{"n":8,"t":"屬肉體的人無法使神喜悅。","notes":[]},{"n":9,"t":"如果神的靈住在你們裏面，你們就不屬肉體，而是屬聖靈了。人若沒有基督的靈，就不是屬基督的。","notes":[]},{"n":10,"t":"基督若在你們裏面，身體就因罪而死，靈卻因義而活。","notes":[]},{"n":11,"t":"然而，使耶穌從死人中復活的神的靈若住在你們裏面，那使基督從死人中復活的，也必藉著住在你們裏面的聖靈使你們必死的身體又活過來。","notes":[]},{"n":12,"t":"弟兄們，這樣看來，我們不是欠肉體的債去順從肉體而活。","notes":[]},{"n":13,"t":"你們若順從肉體活著，必定會死；若靠著聖靈把身體的惡行處死，就必存活。","notes":[]},{"n":14,"t":"因為凡被神的靈引導的都是神的兒子。","notes":[]},{"n":15,"t":"你們所領受的不是奴僕的靈，仍舊害怕；所領受的是兒子名分的靈，因此我們呼叫：「阿爸，父！」","notes":[]},{"n":16,"t":"聖靈自己與我們的靈一同見證我們是神的兒女。","notes":[]},{"n":17,"t":"若是兒女，就是後嗣，是神的後嗣，和基督同作後嗣。如果我們和他一同受苦，是要我們和他一同得榮耀。","notes":[]},{"n":18,"t":"我認為，現在的苦楚，若比起將來要顯示給我們的榮耀，是不足介意的。","notes":[],"heads":["將來的榮耀"]},{"n":19,"t":"受造之物切望等候神的眾子顯出來。","notes":[]},{"n":20,"t":"因為受造之物屈服在虛空之下，不是自己願意，而是因那使它屈服的叫他如此。但受造之物仍然指望從敗壞的轄制下得釋放，得享神兒女榮耀的自由。","notes":[],"end":21},{"n":22,"t":"我們知道，一切受造之物一同呻吟，一同忍受陣痛，直到如今。","notes":[]},{"n":23,"t":"不但如此，就是我們這有聖靈作初熟果子的，也是自己內心呻吟，等候得著兒子的名分，就是我們的身體得救贖。","notes":[]},{"n":24,"t":"我們得救是在於盼望；可是看得見的盼望就不是盼望。誰還去盼望他所看得見的呢？","notes":[]},{"n":25,"t":"但我們若盼望那看不見的，我們就耐心等候。","notes":[]},{"n":26,"t":"同樣，我們的軟弱有聖靈幫助。我們本不知道當怎樣禱告，但是聖靈親自用無可言喻的嘆息替我們祈求。","notes":[]},{"n":27,"t":"那鑒察人心的知道聖靈所體貼的，因為聖靈照著神的旨意替聖徒祈求。","notes":[]},{"n":28,"t":"我們知道，萬事都互相效力，叫愛神的人得益處，就是按他旨意被召的人。","notes":["「萬事」：有古卷是「神使萬事」。"]},{"n":29,"t":"因為他所預知的人，他也預定他們效法他兒子的榜樣，使他兒子在許多弟兄中作長子。","notes":["「作長子」或譯「為首生者」。"]},{"n":30,"t":"他所預定的人，他又召他們來；所召來的人，他又稱他們為義；所稱為義的人，他又叫他們得榮耀。","notes":[]},{"n":31,"t":"既是這樣，我們對這些事還要怎麼說呢？神若幫助我們，誰能抵擋我們呢？","notes":[],"heads":["不能隔絕的愛"]},{"n":32,"t":"神既不顧惜自己的兒子，為我們眾人捨了他，豈不也把萬物和他一同白白地賜給我們嗎？","notes":[]},{"n":33,"t":"誰能控告神所揀選的人呢？有神稱他們為義了。","notes":[]},{"n":34,"t":"誰能定他們的罪呢？有基督耶穌 已經死了，而且復活了，現今在神的右邊，也替我們祈求。","notes":["有古卷沒有「耶穌」。"]},{"n":35,"t":"誰能使我們與基督的愛隔絕呢？難道是患難嗎？是困苦嗎？是迫害嗎？是飢餓嗎？是赤身露體嗎？是危險嗎？是刀劍嗎？","notes":[]},{"n":36,"t":"如經上所記：「我們為你的緣故終日被殺；人看我們如將宰的羊。」","notes":[]},{"n":37,"t":"然而，靠著愛我們的主，在這一切的事上，我們已經得勝有餘了。","notes":[]},{"n":38,"t":"因為我深信，無論是死，是活，是天使，是掌權的，是有權能的 ，是現在的事，是將來的事，","notes":["「是掌權的，是有權能的」指靈界的勢力。"]},{"n":39,"t":"是高處的，是深處的，是別的受造之物，都不能使我們與神的愛隔絕，這愛是在我們的主基督耶穌裏的。","notes":[]}]},"9":{"heading":"神揀選以色列人","verses":[{"n":1,"t":"我在基督裏說真話，不說謊話；我的良心被聖靈感動為我作證。","notes":[]},{"n":2,"t":"我非常憂愁，心裏時常傷痛。","notes":[]},{"n":3,"t":"為我弟兄，我骨肉之親，就是自己被詛咒，與基督分離，我也願意。","notes":[]},{"n":4,"t":"他們是以色列人，那兒子的名分、榮耀、諸約、律法的頒佈、敬拜的禮儀、應許都是給他們的。","notes":[]},{"n":5,"t":"列祖是他們的，基督按肉體說也是從他們出來的。願在萬有之上的神被稱頌，直到永遠。阿們！","notes":["「基督按肉體…直到永遠」：原文或譯「基督按肉體說也是從他們出來的，他是在萬有之上，永遠可稱頌的神」。"]},{"n":6,"t":"這不是說神的話落了空。因為從以色列生的不都是以色列人，","notes":[]},{"n":7,"t":"也不因為是亞伯拉罕的後裔就都是他的兒女；惟獨「從以撒生的才要稱為你的後裔。」","notes":[]},{"n":8,"t":"這就是說，肉身所生的兒女不是神的兒女，惟獨那應許的兒女才算是後裔。","notes":[]},{"n":9,"t":"因為所應許的話是這樣：「到明年這時候我要來，撒拉必會生一個兒子。」","notes":[]},{"n":10,"t":"不但如此，利百加也是這樣。她從一個人，就是從我們的祖宗以撒懷了孕。","notes":[]},{"n":11,"t":"雙胞胎還沒有生下來，善惡還沒有行出來，為要貫徹神揀選人的旨意，","notes":[]},{"n":12,"t":"不是憑著人的行為，而是憑著那呼召人的，神就對利百加說：「將來，大的要服侍小的。」","notes":[]},{"n":13,"t":"正如經上所記：「雅各是我所愛的；以掃是我所惡的。」","notes":[]},{"n":14,"t":"這樣，我們要怎麼說呢？難道神有甚麼不義嗎？絕對沒有！","notes":[]},{"n":15,"t":"因他對摩西說：「我要憐憫誰就憐憫誰，要恩待誰就恩待誰。」","notes":[]},{"n":16,"t":"由此看來，這不靠人的意願，也不靠人的努力，只靠神的憐憫。","notes":[]},{"n":17,"t":"因為經上有話對法老說：「我將你興起來，特要在你身上彰顯我的權能，為要使我的名傳遍全地。」","notes":[]},{"n":18,"t":"由此看來，神要憐憫誰就憐憫誰，要使誰剛硬就使誰剛硬。","notes":[]},{"n":19,"t":"這樣，你會對我說：「那麼，他為甚麼還指責人呢？有誰能抗拒他的旨意呢？」","notes":[],"heads":["神的憤怒和憐憫"]},{"n":20,"t":"你這個人哪，你是誰，竟敢向神頂嘴呢？受造之物豈會對造他的說：「你為甚麼把我造成這樣呢？」","notes":[]},{"n":21,"t":"難道陶匠沒有權從一團泥裏拿一塊做成貴重的器皿，又拿一塊做成卑賤的器皿嗎？","notes":[]},{"n":22,"t":"倘若神要顯明他的憤怒，彰顯他的權能，難道不可多多忍耐寬容那應受憤怒、預備遭毀滅的器皿嗎？","notes":[]},{"n":23,"t":"這是為了要把他豐盛的榮耀彰顯在那蒙憐憫、早預備得榮耀的器皿上。","notes":[]},{"n":24,"t":"這器皿也就是我們這些蒙神所召的，不但是從猶太人中，也是從外邦人中召來的。","notes":[]},{"n":25,"t":"正如神在《何西阿書》上說：「那本來不是我子民的，我要稱為『我的子民』；本來不是蒙愛的，我要稱為『蒙愛的』。","notes":[]},{"n":26,"t":"從前在甚麼地方對他們說：你們不是我的子民，將來就在那裏稱他們為『永生神的兒子』。」","notes":[]},{"n":27,"t":"關於以色列人，以賽亞喊著：「雖然以色列人多如海沙，得救的將是剩下的餘數，","notes":[]},{"n":28,"t":"因為主要在地上施行他的話，徹底而又迅速。」","notes":[]},{"n":29,"t":"又如以賽亞先前說過：「若不是萬軍之主給我們存留餘種，我們早已變成所多瑪，像蛾摩拉一樣了。」","notes":[]},{"n":30,"t":"這樣，我們要怎麼說呢？那不追求義的外邦人卻獲得了義，就是因信而獲得的義。","notes":[],"heads":["以色列人和福音"]},{"n":31,"t":"但以色列人追求律法的義，反而達不到律法的義。","notes":[]},{"n":32,"t":"這是甚麼緣故呢？是因為他們不憑著信心，而是憑著行為，他們正跌在那絆腳石上。","notes":[]},{"n":33,"t":"就如經上所記：「我在錫安放一塊絆腳的石頭，使人跌倒的磐石；信靠他的人必不蒙羞。」","notes":[]}]},"10":{"heading":"求告主名的必定得救","verses":[{"n":1,"t":"弟兄們，我心裏所渴望的和向神所求的，是要以色列人得救。","notes":[]},{"n":2,"t":"我為他們作證，他們對神有熱心，但不是按著真知識。","notes":[]},{"n":3,"t":"因為不明白神的義，想要立自己的義，他們就不服神的義了。","notes":[]},{"n":4,"t":"律法的總結就是基督，使所有信他的人都得著義。","notes":[]},{"n":5,"t":"論到出於律法的義，摩西寫著：「行這些事的人，就必因此得生。」","notes":[]},{"n":6,"t":"但出於信的義卻如此說：「你不要心裏說：誰要升到天上去呢？（就是說，把基督領下來。）","notes":[]},{"n":7,"t":"或說：誰要下到陰間去呢？（就是說，把基督從死人中領上來。）」","notes":[]},{"n":8,"t":"他到底怎麼說呢？「這話語就離你近，就在你口中，在你心裏，」（就是說，我們傳揚所信的話語。）","notes":[]},{"n":9,"t":"你若口裏宣認耶穌為主，心裏信神叫他從死人中復活，就必得救。","notes":[]},{"n":10,"t":"因為，人心裏信就可以稱義，口裏宣認就可以得救。","notes":[]},{"n":11,"t":"經上說：「凡信靠他的人必不蒙羞。」","notes":[]},{"n":12,"t":"猶太人和希臘人並沒有分別，因為人人都有同一位主，他也厚待求告他的每一個人。","notes":[]},{"n":13,"t":"因為「凡求告主名的就必得救」。","notes":[]},{"n":14,"t":"然而，人未曾信他，怎能求告他呢？未曾聽見他，怎能信他呢？沒有傳道的，怎能聽見呢？","notes":[]},{"n":15,"t":"若沒有奉差遣，怎能傳道呢？如經上所記：「報福音、傳喜信的人，他們的腳蹤何等佳美！」","notes":[]},{"n":16,"t":"但不是每一個人都聽從福音，因為以賽亞說：「主啊，我們所傳的有誰信呢？」","notes":[]},{"n":17,"t":"可見，信道是從聽道來的，聽道是從基督的話來的。","notes":[]},{"n":18,"t":"但我要問，人沒有聽見嗎？當然聽見了。「他們的聲音傳遍全地；他們的言語傳到地極。」","notes":[]},{"n":19,"t":"我再問，以色列人不知道嗎？先有摩西說：「我要以不成國的激起你們嫉妒；我要以愚頑的國惹起你們發怒。」","notes":[]},{"n":20,"t":"又有以賽亞放膽說：「沒有尋找我的，我要讓他們尋見；沒有求問我的，我要向他們顯現。」","notes":[]},{"n":21,"t":"關於以色列人，他說：「我整天向那悖逆頂嘴的百姓招手。」","notes":[]}]},"11":{"heading":"以色列的餘民","verses":[{"n":1,"t":"那麼，我要問，神棄絕了他的百姓嗎？絕對沒有！因為我也是以色列人，亞伯拉罕的後裔，屬便雅憫支派的。","notes":[]},{"n":2,"t":"神並沒有棄絕他預先所知道的百姓。你們豈不知道經上論到以利亞是怎麼說的呢？他在神面前怎樣控告以色列人說：","notes":[]},{"n":3,"t":"「主啊，他們殺了你的先知，拆了你的祭壇，只剩下我一個人，他們還要我的命。」","notes":[]},{"n":4,"t":"但神的指示是怎麼對他說的呢？他說：「我為自己留下七千人，是未曾向巴力屈膝的。」","notes":[]},{"n":5,"t":"現在這時刻也是這樣，照著出於恩典的揀選，還有所留的餘數。","notes":[]},{"n":6,"t":"既是靠恩典，就不憑行為，不然，恩典就不再是恩典了。","notes":[]},{"n":7,"t":"那又怎麼說呢？以色列人所尋求的，他們沒有得著。但是蒙揀選的人得著了，其餘的人卻成了頑梗不化的。","notes":[]},{"n":8,"t":"如經上所記：「神給他們昏沉的靈，眼睛看不見，耳朵聽不到，直到今日。」","notes":[]},{"n":9,"t":"大衛也說：「願他們的宴席變為羅網，變為陷阱，變為絆腳石，作他們的報應。","notes":[]},{"n":10,"t":"願他們的眼睛昏花，看不見；願你時常彎下他們的腰。」","notes":[]},{"n":11,"t":"那麼，我再問，他們失足是要他們跌倒嗎？絕對不是！因他們的過犯，救恩反而臨到外邦人，要激起他們嫉妒的心。","notes":[],"heads":["外邦人得救"]},{"n":12,"t":"如果他們的過犯成為世界的富足，他們的缺乏成為外邦人的富足，更何況他們全數得救呢？","notes":[]},{"n":13,"t":"我對你們外邦人說，正因為我是外邦人的使徒，我敬重我的職分，","notes":[]},{"n":14,"t":"希望可以激起我骨肉之親的嫉妒，好救他們一些人。","notes":[]},{"n":15,"t":"如果他們被丟棄，世界因而得以與神和好；他們被收納，豈不就是從死人中復生嗎？","notes":[]},{"n":16,"t":"所獻的新麵若聖潔，整個麵團都聖潔了；樹根若聖潔，樹枝也聖潔了。","notes":[]},{"n":17,"t":"若有幾根枝子被折下來，你這野橄欖枝接上去，同享橄欖根的肥汁，","notes":[]},{"n":18,"t":"你就不可向舊枝子誇口；若是誇口，該知道不是你托著根，而是根托著你。","notes":[]},{"n":19,"t":"你會說，那些枝子被折下來是為了使我接上去。","notes":[]},{"n":20,"t":"不錯。他們因為不信，所以被折下來；你因為信，所以立得住。你不可自高，反要戰戰兢兢。","notes":[]},{"n":21,"t":"神既然不顧惜原來的枝子，豈會顧惜你？","notes":["「豈會顧惜你？」有古卷是「也不會顧惜你。」"]},{"n":22,"t":"可見，神又恩慈又嚴厲：對那跌倒的人是嚴厲的；對你是恩慈的，只要你長久在他的恩慈裏，不然，你也要被砍下來。","notes":[]},{"n":23,"t":"而且，他們若不是長久不信，仍要被接上，因為神能夠重新把他們接上去。","notes":[]},{"n":24,"t":"你是從那天生的野橄欖上砍下來的，尚且違反自然地接在好橄欖上，何況這些原來的枝子豈不更要接在原樹上嗎？","notes":[]},{"n":25,"t":"弟兄們，我不願意你們不知道這奧祕，恐怕你們自以為聰明。這奧祕就是有一部分以色列人是硬心的，等到外邦人的數目添滿了，","notes":[],"heads":["全以色列都將得救"]},{"n":26,"t":"以色列全家都要得救。如經上所記：「必有一位救主從錫安出來，要消除雅各家一切不虔不敬。」","notes":[]},{"n":27,"t":"「這就是我與他們所立的約，那時我要除去他們的罪。」","notes":[]},{"n":28,"t":"就福音來說，他們為你們的緣故是仇敵；就揀選來說，他們因列祖的緣故是蒙愛的。","notes":[]},{"n":29,"t":"因為神的恩賜和選召是不會撤回的。","notes":[]},{"n":30,"t":"你們從前不順服神，如今因他們的不順服，你們倒蒙了憐憫。","notes":[]},{"n":31,"t":"同樣，他們現在也是不順服，叫他們因著施給你們的憐憫，現在也就蒙憐憫。","notes":["有古卷沒有「現在」。"]},{"n":32,"t":"因為神把眾人都圈在不順服中，為的是要憐憫眾人。","notes":[]},{"n":33,"t":"深哉，神的豐富、智慧和知識！他的判斷何其難測！他的蹤跡何其難尋！","notes":[]},{"n":34,"t":"誰知道主的心？誰作過他的謀士？","notes":[]},{"n":35,"t":"誰先給了他，使他後來償還呢？","notes":[]},{"n":36,"t":"因為萬有都是本於他，倚靠他，歸於他。願榮耀歸給他，直到永遠。阿們！","notes":[]}]},"12":{"heading":"基督裏的新生活","verses":[{"n":1,"t":"所以，弟兄們，我以神的慈悲勸你們，將身體獻上當作活祭，是聖潔的，是神所喜悅的，你們如此事奉乃是理所當然的。","notes":["「你們如此…當然的」或譯「你們如此敬拜乃是屬靈的」。"]},{"n":2,"t":"不要效法這個世界，只要心意更新而變化，叫你們察驗何為神的善良、純全、可喜悅的旨意。","notes":[]},{"n":3,"t":"我憑著所賜我的恩對你們每一位說：不要把自己看得太高，要照著神所分給各人的信心來衡量，看得合乎中道。","notes":[]},{"n":4,"t":"正如我們一個身子上有好些肢體，肢體也不都有一樣的用處。","notes":[]},{"n":5,"t":"這樣，我們許多人在基督裏是一個身體，互相聯絡作肢體。","notes":[]},{"n":6,"t":"按著所得的恩典，我們各有不同的恩賜：或說預言，要按著信心的程度說預言；","notes":[]},{"n":7,"t":"或服事的，要專一服事；或教導的，要專一教導；","notes":[]},{"n":8,"t":"或勸勉的，要專一勸勉；施捨的，要誠實；治理的，要殷勤；憐憫人的，要樂意。","notes":[]},{"n":9,"t":"愛，不可虛假；惡，要厭惡；善，要親近。","notes":[],"heads":["基督徒的生活守則"]},{"n":10,"t":"愛弟兄，要相親相愛；恭敬人，要彼此推讓；","notes":[]},{"n":11,"t":"殷勤，不可懶惰。要靈裏火熱；常常服侍主。","notes":[]},{"n":12,"t":"在盼望中要喜樂；在患難中要忍耐；禱告要恆切。","notes":[]},{"n":13,"t":"聖徒有缺乏，要供給；異鄉客，要殷勤款待。","notes":[]},{"n":14,"t":"要祝福迫害你們的，要祝福，不可詛咒。","notes":["有古卷沒有「你們」。"]},{"n":15,"t":"要與喜樂的人同樂；要與哀哭的人同哭。","notes":[]},{"n":16,"t":"要彼此同心，不要心高氣傲，倒要俯就卑微的人。不要自以為聰明。","notes":[]},{"n":17,"t":"不要以惡報惡，眾人以為美的事要留心去做。","notes":[]},{"n":18,"t":"若是可行，總要盡力與眾人和睦。","notes":[]},{"n":19,"t":"各位親愛的，不要自己伸冤，寧可給主的憤怒留地步，因為經上記著：「主說：『伸冤在我，我必報應。』」","notes":[]},{"n":20,"t":"不但如此，「你的仇敵若餓了，就給他吃；若渴了，就給他喝。因為你這樣做，就是把炭火堆在他的頭上。」","notes":[]},{"n":21,"t":"不要被惡所勝，反要以善勝惡。","notes":[]}]},"13":{"heading":"順服掌權者","verses":[{"n":1,"t":"在上有權柄的，人人要順服，因為沒有權柄不是來自神的。掌權的都是神所立的。","notes":[]},{"n":2,"t":"所以，抗拒掌權的就是抗拒神所立的；抗拒的人必自招審判。","notes":[]},{"n":3,"t":"作官的原不是要使行善的懼怕，而是要使作惡的懼怕。你願意不懼怕掌權的嗎？只要行善，你就可得他的稱讚；","notes":[]},{"n":4,"t":"因為他是神的用人，是與你有益的。你若作惡，就該懼怕，因為他不是徒然佩劍；他是神的用人，為神的憤怒，報應作惡的。","notes":[]},{"n":5,"t":"所以，你們必須順服，不但是因神的憤怒，也是因著良心。","notes":[]},{"n":6,"t":"你們納糧也為這個緣故，因他們是神的僕役，專管這事。","notes":[]},{"n":7,"t":"凡人所當得的，就給他。當得糧的，給他納糧；當得稅的，給他上稅；當懼怕的，懼怕他；當恭敬的，恭敬他。","notes":[]},{"n":8,"t":"你們除了彼此相愛，對任何人都不可虧欠甚麼，因為那愛人的就成全了律法。","notes":[],"heads":["愛成全律法"]},{"n":9,"t":"那不可姦淫，不可殺人，不可偷盜，不可貪婪，或別的誡命，都包括在「愛鄰如己」這一句話之內了。","notes":["「鄰」也可譯作「人」。"]},{"n":10,"t":"愛是不對鄰人作惡，所以愛就成全了律法。","notes":[]},{"n":11,"t":"還有，你們要知道，現在正是該從睡夢中醒來的時候了；因為我們得救，現在比初信的時候更近了。","notes":[],"heads":["白晝將近"]},{"n":12,"t":"黑夜已深，白晝將近。所以我們該除去暗昧的行為，帶上光明的兵器。","notes":[]},{"n":13,"t":"行事為人要端正，好像在白晝行走。不可荒宴醉酒；不可好色淫蕩；不可紛爭嫉妒。","notes":[]},{"n":14,"t":"總要披戴主耶穌基督，不要只顧滿足肉體，去放縱私慾。","notes":[]}]},"14":{"heading":"不可評斷弟兄","verses":[{"n":1,"t":"信心軟弱的，你們要接納，不同的意見，不要爭論。","notes":[]},{"n":2,"t":"有人信甚麼都可吃；但那軟弱的，只吃蔬菜。","notes":[]},{"n":3,"t":"吃的人不可輕看不吃的人；不吃的人也不可評斷吃的人，因為神已經接納他了。","notes":[]},{"n":4,"t":"你是誰，竟評斷別人的僕人呢？他或站立或跌倒，自有他的主人在，而且他也必會站立，因為主能使他站穩。","notes":[]},{"n":5,"t":"有人看這日比那日強；有人看日日都是一樣。只是各人要在自己的心意上堅定。","notes":[]},{"n":6,"t":"守日子的人是為主守的。吃的人是為主吃的，因他感謝神；不吃的人是為主不吃的，他也感謝神。","notes":[]},{"n":7,"t":"我們沒有一個人為自己而活，也沒有一個人為自己而死。","notes":[]},{"n":8,"t":"我們若活，是為主而活；我們若死，是為主而死。所以，我們或死或活總是主的人。","notes":[]},{"n":9,"t":"為此，基督死了，又活了，為要作死人和活人的主。","notes":[]},{"n":10,"t":"可是你，你為甚麼評斷弟兄呢？你又為甚麼輕看弟兄呢？因我們都要站在神的審判臺前。","notes":[]},{"n":11,"t":"經上寫著：「主說，我指著我的永生起誓：萬膝必向我跪拜；萬口必稱頌神。」","notes":[]},{"n":12,"t":"這樣看來，我們各人一定要把自己的事在神面前交代。","notes":["有古卷沒有「在神面前」。"]},{"n":13,"t":"所以，我們不可再彼此評斷，寧可決意不給弟兄放置障礙或絆腳石。","notes":[],"heads":["不可使弟兄跌倒"]},{"n":14,"t":"我憑著主耶穌確知深信，凡物本來沒有不潔淨的，除非人以為不潔淨的，在他就不潔淨了。","notes":[]},{"n":15,"t":"你若因食物使弟兄憂愁，就不是按著愛心行事。基督已經為他死，你不可因你的食物使他敗壞。","notes":[]},{"n":16,"t":"所以，不可讓你們的善被人毀謗。","notes":[]},{"n":17,"t":"因為神的國不在乎飲食，而在乎公義、和平及聖靈中的喜樂。","notes":["「公義…喜樂」或譯「聖靈中的公義、和平及喜樂」。"]},{"n":18,"t":"凡這樣服侍基督的，就為神所喜悅，又為人所讚許。","notes":[]},{"n":19,"t":"所以，我們務要追求和平與彼此造就的事。","notes":["「務要追求」：有古卷是「追求」。"]},{"n":20,"t":"不可因食物毀壞神的工作。一切都是潔淨的，但有人因食物使人跌倒，這在他就是惡了。","notes":[]},{"n":21,"t":"無論是吃肉是喝酒，是甚麼別的事，使弟兄跌倒，一概不做，才是善的。","notes":[]},{"n":22,"t":"你有信心，就要在神面前持守。人能在自己以為可行的事上不自責就有福了。","notes":[]},{"n":23,"t":"若有人疑惑而吃的，就被定罪，因為他吃不是出於信心。凡不出於信心的都是罪。","notes":[]}]},"15":{"heading":"要讓鄰人喜悅","verses":[{"n":1,"t":"我們堅強的人應該分擔不堅強的人的軟弱，不求自己的喜悅。","notes":[]},{"n":2,"t":"我們各人務必要讓鄰人喜悅，使他得益處，得造就。","notes":[]},{"n":3,"t":"因為基督也不求自己的喜悅，如經上所記：「辱罵你的人的辱罵都落在我身上。」","notes":[]},{"n":4,"t":"從前所寫的聖經都是為教導我們寫的，要使我們藉著忍耐和因聖經所生的安慰，得著盼望。","notes":[]},{"n":5,"t":"但願賜忍耐和安慰的神使你們彼此同心，效法基督耶穌，","notes":[]},{"n":6,"t":"為使你們同心同聲榮耀我們主耶穌基督的父神！","notes":[]},{"n":7,"t":"所以，你們要彼此接納，如同基督接納你們一樣，歸榮耀給神。","notes":[],"heads":["神的福音一視同仁"]},{"n":8,"t":"我說，基督是為神真理作了受割禮的人的執事，要證實所應許列祖的話，","notes":[]},{"n":9,"t":"並使外邦人，因他的憐憫，榮耀神。如經上所記：「因此，我要在外邦中稱頌你，歌頌你的名。」","notes":[]},{"n":10,"t":"又說：「外邦人哪，你們要與主的子民一同歡樂。」","notes":[]},{"n":11,"t":"又說：「列邦啊，你們要讚美主！萬民哪，你們都要頌讚他！」","notes":[]},{"n":12,"t":"又有以賽亞說：「將來有耶西的根，就是那興起來要治理列邦的；外邦人要仰望他。」","notes":[]},{"n":13,"t":"願賜盼望的神，因你們的信把各樣的喜樂、平安充滿你們的心，使你們藉著聖靈的能力大有盼望！","notes":["「平安」或譯「和平」；33節同。"]},{"n":14,"t":"我的弟兄們，我本人也深信你們自己充滿良善，有各種豐富的知識，也能彼此勸戒。","notes":[],"heads":["保羅的宣教使命"]},{"n":15,"t":"但我更大膽寫信給你們，是要在一些事上提醒你們，我因神所賜我的恩，","notes":[]},{"n":16,"t":"使我為外邦人作基督耶穌的僕役，作神福音的祭司，使所獻上的外邦人因著聖靈成為聖潔，可蒙悅納。","notes":[]},{"n":17,"t":"所以，有關神面前的事奉，我在基督耶穌裏是有可誇的。","notes":[]},{"n":18,"t":"除了基督藉我做的那些事，我甚麼都不敢提，只提他藉我的言語作為，用神蹟奇事的能力，並神的靈的能力，使外邦人順服；甚至我從耶路撒冷，直轉到以利哩古，到處傳了基督的福音。","notes":["「神的靈」：有古卷是「聖靈」。"],"end":19},{"n":20,"t":"這樣，我立了志向，不在基督的名已經傳揚過的地方傳福音，免得建造在別人的根基上；","notes":[]},{"n":21,"t":"卻如經上所記：「未曾傳給他們的，他們必看見；未曾聽見過的事，他們要明白。」","notes":[]},{"n":22,"t":"因此我多次被攔阻，不能到你們那裏去。","notes":[],"heads":["保羅計劃訪問羅馬"]},{"n":23,"t":"但如今，在這一帶再沒有可傳的地方，而且這許多年來，我迫切想去你們那裏，","notes":[]},{"n":24,"t":"盼望到西班牙去的時候經過，得見你們，先與你們彼此交往，心裏稍得滿足，然後蒙你們為我送行。","notes":[]},{"n":25,"t":"但如今我要到耶路撒冷去，供應聖徒的需要。","notes":[]},{"n":26,"t":"因為馬其頓和亞該亞人樂意湊出一些捐款給耶路撒冷聖徒中的窮人。","notes":[]},{"n":27,"t":"這固然是他們樂意的，其實也算是所欠的債；因為外邦人既然分享了他們靈性上的好處，就當把肉體上的需用供給他們。","notes":[]},{"n":28,"t":"等我辦完了這事，把這筆捐款交付給他們，我就要路過你們那裏，到西班牙去。","notes":["「捐款」：原文直譯「果實」。"]},{"n":29,"t":"我也知道去你們那裏的時候，我將帶著基督豐盛的恩典去。","notes":[]},{"n":30,"t":"弟兄們，我藉著我們的主耶穌基督，又藉著聖靈的愛，勸你們與我一同竭力為我祈求神，","notes":[]},{"n":31,"t":"使我脫離在猶太不順從的人，也讓我在耶路撒冷的事奉可蒙聖徒悅納，","notes":[]},{"n":32,"t":"並使我照著神的旨意歡歡喜喜地到你們那裏，與你們同得安息。","notes":[]},{"n":33,"t":"願賜平安的神與你們眾人同在。阿們！","notes":[]}]},"16":{"heading":"問安","verses":[{"n":1,"t":"我對你們推薦我們的姊妹非比，她是堅革哩教會中的執事。","notes":[]},{"n":2,"t":"請你們在主裏用合乎聖徒的方式來接待她。她在任何事上需要你們幫助，你們就幫助她；因她素來幫助許多人，也幫助了我。","notes":[]},{"n":3,"t":"請向百基拉和亞居拉問安。他們在基督耶穌裏作我的同工，","notes":[]},{"n":4,"t":"也為我的性命把自己的生死置之度外；不但我感謝他們，就是外邦的眾教會也感謝他們。","notes":[]},{"n":5,"t":"又向在他們家中的教會問安。向我所親愛的以拜尼土問安，他是亞細亞歸於基督的初結果子。","notes":[]},{"n":6,"t":"又向馬利亞問安，她為你們非常辛勞。","notes":[]},{"n":7,"t":"又向與我一同坐監的親戚安多尼古和猶尼亞問安，他們在使徒中是有名望的，也是比我先在基督裏的。","notes":[]},{"n":8,"t":"又向我在主裏面所親愛的暗伯利問安。","notes":[]},{"n":9,"t":"又向我們在基督裏的同工耳巴奴和我所親愛的士大古問安。","notes":[]},{"n":10,"t":"又向在基督裏經過考驗的亞比利問安。向亞利多布家裏的人問安。","notes":[]},{"n":11,"t":"又向我親戚希羅天問安。向拿其數家在主裏的人問安。","notes":[]},{"n":12,"t":"又向為主辛勞的土非拿和土富撒問安。向所親愛、為主非常辛勞的彼息問安。","notes":[]},{"n":13,"t":"又向在主裏蒙揀選的魯孚和他母親問安，他的母親就是我的母親。","notes":[]},{"n":14,"t":"又向亞遜其土、弗勒干、黑米、八羅巴、黑馬，和跟他們在一起的弟兄們問安。","notes":[]},{"n":15,"t":"又向非羅羅古和猶利亞，尼利亞和他姊妹，阿林巴和跟他們在一起的眾聖徒問安。","notes":[]},{"n":16,"t":"你們要以聖潔的吻彼此問安。基督的眾教會都向你們問安！","notes":[]},{"n":17,"t":"弟兄們，那些離間你們、使你們跌倒、違背所學之道的人，我勸你們要留意躲避他們。","notes":[]},{"n":18,"t":"因為這樣的人不服侍我們的主基督，只服侍自己的肚腹，用花言巧語誘惑老實人的心。","notes":[]},{"n":19,"t":"你們的順服已經傳於眾人，所以我為你們歡喜；但我願你們在善上聰明，在惡上愚拙。","notes":[]},{"n":20,"t":"那賜平安的神快要把撒但踐踏在你們腳下。願我們主耶穌基督的恩與你們同在！","notes":["「平安」或譯「和平」。"]},{"n":21,"t":"我的同工提摩太，和我的親戚路求、耶孫、所西巴德，向你們問安。","notes":[]},{"n":22,"t":"我這代筆寫信的德提，在主裏向你們問安。","notes":[]},{"n":23,"t":"那接待我，也接待全教會的該猶，向你們問安。城裏的財務官以拉都和弟兄括土向你們問安。","notes":["有古卷加「24 願我們的主耶穌基督賜恩典給你們各位！阿們！」"]},{"n":25,"t":"惟有神能照我所傳的福音和所講的耶穌基督，並照歷代以來隱藏的奧祕的啟示，堅固你們。","notes":[],"heads":["頌讚"]},{"n":26,"t":"這奧祕如今顯示出來，而且按著永生神的命令，藉眾先知的書指示萬民，使他們因信而順服。","notes":[]},{"n":27,"t":"願榮耀，藉著耶穌基督，歸給獨一全智的神，直到永遠。阿們！","notes":[]}]}},"1CO":{"1":{"heading":"祝福和感謝","verses":[{"n":1,"t":"奉神旨意，蒙召作基督耶穌使徒的保羅，同弟兄所提尼，","notes":[]},{"n":2,"t":"寫信給在哥林多神的教會—就是在基督耶穌裏成聖、蒙召作聖徒的—以及所有在各處求告我主耶穌基督之名的人。基督是他們的主，也是我們的主。","notes":[]},{"n":3,"t":"願恩惠、平安從我們的父神並主耶穌基督歸給你們！","notes":["「平安」或譯「和平」。"]},{"n":4,"t":"我常為你們感謝我的神，因神在基督耶穌裏所賜給你們的恩惠。","notes":[]},{"n":5,"t":"因為你們在他裏面凡事富足，具有各種口才、各樣知識，","notes":[]},{"n":6,"t":"正如我為基督作的見證在你們心裏得以堅固，","notes":[]},{"n":7,"t":"以致你們在恩賜上一無欠缺，切切等候我們主耶穌基督的顯現。","notes":[]},{"n":8,"t":"他也必堅固你們到底，使你們在我們主耶穌基督的日子無可指責。","notes":["有古卷沒有「基督」。"]},{"n":9,"t":"神是信實的，他呼召你們好與他兒子—我們的主耶穌基督—共享團契。","notes":[]},{"n":10,"t":"弟兄們，我藉我們主耶穌基督的名勸你們說話要一致。你們中間不可分裂，只要一心一意彼此團結。","notes":[],"heads":["教會中的紛爭"]},{"n":11,"t":"我的弟兄們，革來氏家裏的人曾對我提起你們，說你們中間有紛爭。","notes":[]},{"n":12,"t":"我的意思是，你們各人說：「我是屬保羅的」；「我是屬亞波羅的」；「我是屬磯法的」；「我是屬基督的。」","notes":[]},{"n":13,"t":"基督是分裂的嗎？保羅為你們釘了十字架嗎？你們是奉保羅的名受了洗嗎？","notes":[]},{"n":14,"t":"我感謝神，除了基利司布和該猶以外，我沒有給你們中的任何一個人施洗，","notes":["有古卷沒有「神」。"]},{"n":15,"t":"免得有人說你們是奉我的名受洗的。","notes":[]},{"n":16,"t":"我曾為司提法那家施過洗；此外我已記不清有沒有給別人施過洗。","notes":[]},{"n":17,"t":"因為基督差遣我不是為施洗，而是為傳福音；並不是用智慧的言論，免得基督的十字架落了空。","notes":[]},{"n":18,"t":"因為十字架的道理，在那滅亡的人是愚拙，在我們得救的人卻是神的大能。","notes":[],"heads":["基督是神的大能和智慧"]},{"n":19,"t":"就如經上所記：「我要摧毀智慧人的智慧，廢棄聰明人的聰明。」","notes":[]},{"n":20,"t":"智慧人在哪裏？文士在哪裏？這世上的辯士在哪裏？神豈不是已使這世上的智慧變成愚拙了嗎？","notes":[]},{"n":21,"t":"既然世人憑自己的智慧不認識神，神就本著自己的智慧樂意藉著人所傳愚拙的話拯救那些信的人。","notes":[]},{"n":22,"t":"猶太人要的是神蹟，希臘人求的是智慧，","notes":[]},{"n":23,"t":"我們卻是傳被釘十字架的基督，這對猶太人是絆腳石，對外邦人是愚拙；","notes":[]},{"n":24,"t":"但對那蒙召的，無論是猶太人、希臘人，基督總是神的大能，神的智慧。","notes":[]},{"n":25,"t":"因為，神的愚拙總比人智慧；神的軟弱總比人強壯。","notes":[]},{"n":26,"t":"弟兄們哪，想一想你們的蒙召，按著人的觀點，有智慧的不多，有能力的不多，有尊貴地位的也不多。","notes":[]},{"n":27,"t":"但是，神揀選了世上愚拙的，為了使有智慧的羞愧；又揀選了世上軟弱的，為了使強壯的羞愧。","notes":[]},{"n":28,"t":"神也揀選了世上卑賤的，被人厭惡的，以及那一無所有的，為要廢掉那樣樣都有的，","notes":[]},{"n":29,"t":"使凡血肉之軀的，在神面前，一個也不能自誇。","notes":[]},{"n":30,"t":"但你們得以在基督耶穌裏是本乎神，他使基督成為我們的智慧，成為公義、聖潔、救贖。","notes":[]},{"n":31,"t":"如經上所記：「要誇耀的，該誇耀主。」","notes":[]}]},"2":{"heading":"傳揚釘十字架的基督","verses":[{"n":1,"t":"弟兄們，從前我到你們那裏去，並沒有用高言大智對你們宣講神的奧祕。","notes":[]},{"n":2,"t":"因為我曾定了主意，在你們中間不知道別的，只知道耶穌基督並他釘十字架。","notes":[]},{"n":3,"t":"我在你們那裏時，又軟弱，又懼怕，又戰戰兢兢。","notes":[]},{"n":4,"t":"我說的話、講的道不是用委婉智慧的言語，而是以聖靈的大能來證明，","notes":["「委婉智慧的言語」：有古卷是「委婉的智慧」；另有古卷是「人委婉智慧的言語」。"]},{"n":5,"t":"為要使你們的信不靠著人的智慧，而是靠著神的大能。","notes":[]},{"n":6,"t":"然而，在成熟的人中，我們也講智慧，但不是今世的智慧，也不是今世有權有位、將要滅亡的人的智慧。","notes":[],"heads":["神之靈的啟示"]},{"n":7,"t":"我們講的是從前隱藏的、神奧祕的智慧，就是神在萬世以前預定使我們得榮耀的智慧；","notes":[]},{"n":8,"t":"這智慧，今世有權有位的人沒有一個知道，若知道，他們就不會把榮耀的主釘在十字架上了。","notes":[]},{"n":9,"t":"如經上所記：「神為愛他的人所預備的是眼睛未曾看見，耳朵未曾聽見，人心也未曾想到的。」","notes":[]},{"n":10,"t":"只有神藉著聖靈把這事向我們顯明了；因為聖靈參透萬事，就是神深奧的事也參透了。","notes":[]},{"n":11,"t":"除了在人裏頭的靈，誰知道人的事？照樣，除了神的靈，也沒有人知道神的事。","notes":[]},{"n":12,"t":"我們所領受的並不是世上的靈，而是從神來的靈，為使我們知道神把恩賜賞給我們的事。","notes":[]},{"n":13,"t":"我們也講說這些事，不是用人的智慧所教的言語，而是用聖靈所教的言語，用屬靈的話解釋屬靈的事。","notes":["「用屬靈的話解釋屬靈的事」或譯「把屬靈的事講給屬靈的人」。"]},{"n":14,"t":"然而，屬血氣的人不接受神的靈的事，他反倒以這為愚拙，並且他不能了解，因為這些事惟有屬靈的人才能領悟。","notes":[]},{"n":15,"t":"屬靈的人能看透萬事，卻沒有一人能看透他。","notes":[]},{"n":16,"t":"「誰曾知道主的心？誰會教導他？」至於我們，我們有基督的心。","notes":[]}]},"3":{"heading":"神的同工","verses":[{"n":1,"t":"弟兄們，我從前對你們說話，還不能把你們當作屬靈的，只能把你們當作屬肉體的，你們在基督裏僅是嬰孩。","notes":[]},{"n":2,"t":"我用奶餵你們，沒有用飯餵你們，因為那時你們不能吃。就是如今還是不能，","notes":[]},{"n":3,"t":"因為你們仍是屬肉體的。你們中間有嫉妒、紛爭，這豈不是屬乎肉體，照著世人的樣子生活嗎？","notes":[]},{"n":4,"t":"有人說：「我是屬保羅的」；有人說：「我是屬亞波羅的」；這樣你們豈不是和世人一樣嗎？","notes":[]},{"n":5,"t":"亞波羅算甚麼？保羅算甚麼？我們都是神的執事，藉著我們，你們信了；這不過是照著主給各人的恩賜去做罷了。","notes":[]},{"n":6,"t":"我栽種了，亞波羅澆灌了，惟有神使它生長。","notes":[]},{"n":7,"t":"可見，栽種的算不了甚麼，澆灌的也算不了甚麼；惟有神能使它生長。","notes":[]},{"n":8,"t":"栽種的和澆灌的都是一樣，但將來各人要照自己的勞苦得到自己的報酬。","notes":[]},{"n":9,"t":"因為我們是神的同工，而你們是神的田地、神的房屋。","notes":[]},{"n":10,"t":"我照神所給我的恩典，好像一個聰明的工頭，立好了根基，別人在上面建造；只是各人要謹慎怎樣在上面建造。","notes":[]},{"n":11,"t":"因為，那已經立好的根基就是耶穌基督，此外沒有人能立別的根基。","notes":[]},{"n":12,"t":"若有人用金銀、寶石，草木、禾稭，在這根基上建造，","notes":[]},{"n":13,"t":"各人的工程必將顯露，因為那日子要將它顯明，有火把它暴露出來，這火要試煉各人的工程怎樣。","notes":[]},{"n":14,"t":"人在那根基上所建造的工程若能保得住，他將要得賞賜。","notes":[]},{"n":15,"t":"人的工程若被燒了，他將損失，雖然他自己將得救，卻要像從火裏經過一樣。","notes":[]},{"n":16,"t":"難道不知你們是神的殿，神的靈住在你們裏面嗎？","notes":[]},{"n":17,"t":"若有人毀壞神的殿，神一定要毀滅那人；因為神的殿是神聖的，這殿就是你們。","notes":[]},{"n":18,"t":"誰都不可自欺。你們中間若有人自以為在今世有智慧，倒不如變為愚拙，好成為有智慧的。","notes":[]},{"n":19,"t":"因為這世界的智慧在神看來是愚拙的。如經上記著：「主使有智慧的人中了自己的詭計；」","notes":[]},{"n":20,"t":"又說：「主知道智慧人的意念，因為它們是虛妄的。」","notes":[]},{"n":21,"t":"所以，無論誰都不可誇耀人；因為萬有都是你們的，","notes":[]},{"n":22,"t":"或保羅，或亞波羅，或磯法，或世界，或生，或死，或現今的事，或將來的事，全是你們的，","notes":[]},{"n":23,"t":"而你們是屬基督的，基督是屬神的。","notes":[]}]},"4":{"heading":"使徒的工作","verses":[{"n":1,"t":"人應該把我們看為基督的執事，為神的奧祕的管家。","notes":[]},{"n":2,"t":"所求於管家的，是要他忠心。","notes":[]},{"n":3,"t":"我被你們評斷，或被別人評斷，我都以為是極小的事；連我自己也不評斷自己。","notes":[]},{"n":4,"t":"雖然我不覺得自己有錯，卻也不能因此判為無罪；審斷我的是主。","notes":[]},{"n":5,"t":"所以，時候未到，在主來以前甚麼都不要評斷，他要照出暗中的隱情，揭發人的動機。那時，各人要從神那裏得著稱讚。","notes":[]},{"n":6,"t":"弟兄們，為你們的緣故，我拿這些事應用到我自己和亞波羅身上，讓你們從我們學到「不可過於聖經所記」這話的意思，免得你們自高自大，看重這個，看輕那個。","notes":[]},{"n":7,"t":"使你與人不同的是誰呢？你所有的有哪一個不是領受的呢？若是領受的，為何自誇，彷彿不是領受的呢？","notes":[]},{"n":8,"t":"你們已經飽足了，已經富足了，用不著我們，自己就作王了。我願意你們果真作王，讓我們也可以與你們一同作王！","notes":[]},{"n":9,"t":"我想，神把我們作使徒的明顯地列在末後，好像定死罪的囚犯，因為我們成了一臺戲，給世界、天使和眾人觀看。","notes":[]},{"n":10,"t":"我們為基督的緣故成為愚拙的；你們在基督裏倒是聰明的。我們軟弱，你們倒強壯；你們有榮耀，我們倒被藐視。","notes":[]},{"n":11,"t":"直到如今，我們還是又飢又渴，又赤身露體，又挨打，又到處漂泊，","notes":[]},{"n":12,"t":"並且勞碌，親手做工；被人咒罵，我們就祝福；被人迫害，我們就忍受；","notes":[]},{"n":13,"t":"被人毀謗，我們就勸導。直到如今，人還把我們看作世上的污穢，萬物中的渣滓。","notes":[]},{"n":14,"t":"我寫這些話，不是要使你們羞愧，而是要警戒你們，好像我所愛的兒女一樣。","notes":[]},{"n":15,"t":"雖然你們在基督裏有無數的導師，卻沒有許多父親，因我是在基督耶穌裏用福音生了你們。","notes":[]},{"n":16,"t":"所以，我求你們要效法我。","notes":[]},{"n":17,"t":"因此，我已差提摩太到你們那裏去。他在主裏面是我親愛和忠心的兒子；他要提醒你們，我在基督耶穌裏怎樣行事為人，在各處各教會中怎樣教導人。","notes":["「基督耶穌」：有古卷是「基督」。"]},{"n":18,"t":"有些人以為我不到你們那裏去而自高自大。","notes":[]},{"n":19,"t":"但是，主若准許，我會很快到你們那裏去；我所要知道的，不是那些自高自大者的言語，而是他們的權能。","notes":[]},{"n":20,"t":"因為神的國不在乎言語，而在乎權能。","notes":[]},{"n":21,"t":"你們願意怎麼樣呢？要我帶著棍子到你們那裏去呢，還是帶著慈愛溫柔的心呢？","notes":[]}]},"5":{"heading":"不容忍淫亂的事","verses":[{"n":1,"t":"我確實聽說在你們中間有淫亂的事；這種淫亂連外邦人中也沒有，就是有人和他的繼母同居。","notes":[]},{"n":2,"t":"你們還自高自大！你們不是該覺得痛心，把做這事的人從你們中間趕出去嗎？","notes":[]},{"n":3,"t":"我人雖然不在你們那裏，心卻在你們那裏，好像親自與你們同在。我奉我們主耶穌的名，已經判斷了做這事的人。你們聚會的時候，我的心和你們同在。你們藉著我們主耶穌的權能，","notes":["「我們主耶穌」：有古卷是「主耶穌基督」；另有古卷是「我們主耶穌基督」。"],"end":4},{"n":5,"t":"要把這樣的人交給撒但，使他的肉體敗壞，好讓他的靈魂在主的日子可以得救。","notes":[]},{"n":6,"t":"你們這樣自誇是不好的。你們不知道一點麵酵能使全團發起來嗎？","notes":[]},{"n":7,"t":"既然你們是無酵的麵，要把舊酵除淨，好使你們成為新團；因為我們逾越節的羔羊—基督已經被殺獻為祭牲了。","notes":[]},{"n":8,"t":"所以，我們來守這節，不可用舊酵，就是不可用惡毒、邪惡的酵，只用純潔真實的無酵餅。","notes":[]},{"n":9,"t":"我先前寫信告訴過你們，不可與淫亂的人交往。","notes":[]},{"n":10,"t":"此話不是泛指這世上所有行淫亂的，或貪婪的，勒索的，或拜偶像的；若是這樣，你們非離開這世界不可。","notes":[]},{"n":11,"t":"但現在，我寫信告訴你們，若有稱為弟兄的人卻仍犯淫亂，或貪婪，或拜偶像，或辱罵，或醉酒，或勒索，這樣的人不可跟他交往，就是跟他吃飯都不可以。","notes":[]},{"n":12,"t":"因為審判教外的人與我何干？教內的人豈不是你們要審判嗎？","notes":[]},{"n":13,"t":"至於外人有神審判他們。如經上說：「要從你們中間把那邪惡的人趕出去。」","notes":[]}]},"6":{"heading":"不可彼此告狀","verses":[{"n":1,"t":"你們中間有彼此爭吵的事，怎敢告到不義的人面前，而不告到聖徒面前呢？","notes":[]},{"n":2,"t":"你們豈不知聖徒要審判世界嗎？若世界要受你們的審判，難道你們不配審判這最小的事嗎？","notes":[]},{"n":3,"t":"你們豈不知我們要審判天使嗎？何況今生的事呢！","notes":[]},{"n":4,"t":"既是這樣，你們若有今生當審判的事，會讓教會所輕看的人來審判嗎？","notes":[]},{"n":5,"t":"我說這話是要使你們慚愧。難道你們中間沒有一個有智慧的人能審斷弟兄中的事嗎？","notes":[]},{"n":6,"t":"你們竟然有弟兄去告弟兄，而且告到不信主的人面前。","notes":[]},{"n":7,"t":"你們彼此告狀，這已經是你們的大錯了。為甚麼不情願受冤屈呢？為甚麼不情願吃虧呢？","notes":[]},{"n":8,"t":"你們反倒去冤枉人，虧負人，況且所冤枉所虧負的就是弟兄。","notes":[]},{"n":9,"t":"你們豈不知不義的人不能承受神的國嗎？不要自欺！無論是淫亂的、拜偶像的、姦淫的、作娼妓的，親男色的、","notes":["「作娼妓」：原文意思是「嬌媚」，可能指神廟裏的男妓。"]},{"n":10,"t":"偷竊的、貪婪的、醉酒的、辱罵的、勒索的，都不能承受神的國。","notes":[]},{"n":11,"t":"從前你們中間也有人是這樣；但現在你們奉主耶穌基督的名，並藉著我們神的靈，已經洗淨，已經成聖，已經稱義了。","notes":["「主耶穌基督」：有古卷是「主耶穌」；另有古卷是「我們主耶穌基督」。"]},{"n":12,"t":"「凡事我都可行」，但不是凡事都有益處。「凡事我都可行」，但無論哪一件，我都不受它的轄制。","notes":[],"heads":["在身體上榮耀神"]},{"n":13,"t":"「食物是為肚腹，肚腹是為食物」；但神要使這兩樣都毀壞。身體不是為淫亂，而是為主；主也是為身體。","notes":[]},{"n":14,"t":"神已經使主復活，也要用他自己的能力使我們復活。","notes":[]},{"n":15,"t":"你們豈不知道你們的身體是基督的肢體嗎？我可以把基督的肢體作為娼妓的肢體嗎？絕對不可！","notes":[]},{"n":16,"t":"你們豈不知道與娼妓苟合的，就是與她成為一體嗎？因為主說：「二人要成為一體。」","notes":[]},{"n":17,"t":"但與主聯合的，就是與主成為一靈。","notes":[]},{"n":18,"t":"你們要遠避淫行。人所犯的，無論甚麼罪，都在身體以外；惟有行淫的，是得罪自己的身體。","notes":[]},{"n":19,"t":"你們豈不知道你們的身體是聖靈的殿嗎？這聖靈是從神而來，住在你們裏面的。而且你們不是屬自己的人，","notes":[]},{"n":20,"t":"因為你們是重價買來的。所以，要在你們的身體上榮耀神。","notes":[]}]},"7":{"heading":"婚姻的問題","verses":[{"n":1,"t":"關於你們信上所提的事，男人不親近女人倒好。","notes":[]},{"n":2,"t":"但為了避免淫亂的事，男人當各有自己的妻子，女人也當各有自己的丈夫。","notes":[]},{"n":3,"t":"丈夫對妻子要盡本分；妻子對丈夫也要如此。","notes":[]},{"n":4,"t":"妻子對自己的身體沒有主張的權柄，權柄在丈夫；丈夫對自己的身體也沒有主張的權柄，權柄在妻子。","notes":[]},{"n":5,"t":"夫妻不可忽略對方的需求，除非為了要專心禱告，在兩相情願下暫時分房；以後仍要同房，免得撒但趁著你們情不自禁而引誘你們。","notes":[]},{"n":6,"t":"我說這話是出於容忍，不是命令。","notes":[]},{"n":7,"t":"我願眾人像我一樣；但是各人都有來自神的恩賜，一個是這樣，一個是那樣。","notes":[]},{"n":8,"t":"我對沒有嫁娶的和寡婦說，他們若能維持獨身像我一樣就好。","notes":[]},{"n":9,"t":"但他們若不能自制，就應該嫁娶，與其慾火攻心，倒不如結婚為妙。","notes":[]},{"n":10,"t":"至於那已經嫁娶的，我吩咐他們—其實不是我，而是主吩咐的：妻子不可離開丈夫，","notes":[]},{"n":11,"t":"若是離開了，不可再嫁，不然要跟丈夫復和；丈夫也不可離棄妻子。","notes":[]},{"n":12,"t":"我對其餘的人說—是我，不是主說—倘若某弟兄有不信的妻子，妻子也情願和他一起生活，他就不可離棄妻子。","notes":[]},{"n":13,"t":"妻子有不信的丈夫，丈夫也情願和她一起生活，她就不可離棄丈夫。","notes":[]},{"n":14,"t":"因為不信的丈夫會因著妻子成了聖潔；不信的妻子也會因著丈夫成了聖潔。不然，你們的兒女就不潔淨了，但現在他們是聖潔的。","notes":["「丈夫」：原文直譯「弟兄」。"]},{"n":15,"t":"倘若那不信的人要離開，就由他離開吧！無論是弟兄是姊妹，遇著這樣的事都不必拘束。神召你們原是要你們和睦。","notes":[]},{"n":16,"t":"你這作妻子的怎麼知道不能救你的丈夫呢？你這作丈夫的怎麼知道不能救你的妻子呢？","notes":[]},{"n":17,"t":"無論如何，要照主所分給各人的恩賜和神所召各人的情況生活。我在各教會裏都是這樣規定的。","notes":[],"heads":["照蒙召時的身份生活"]},{"n":18,"t":"有人受割禮後才蒙召，他就不必除去割禮的記號。有人未受割禮前蒙召，他就不必受割禮。","notes":[]},{"n":19,"t":"受割禮算不了甚麼，不受割禮也算不了甚麼，只要謹守神的誡命就是了。","notes":[]},{"n":20,"t":"各人蒙召的時候是甚麼身份，要守住這身份。","notes":[]},{"n":21,"t":"你是作奴隸時蒙召的嗎？不要介意；若能獲得自由，就爭取自由更好。","notes":[]},{"n":22,"t":"因為，蒙主呼召的奴僕是主所釋放的人；蒙主呼召的自由之人是基督的奴僕。","notes":[]},{"n":23,"t":"你們是重價買來的；不要作人的奴僕。","notes":[]},{"n":24,"t":"弟兄們，你們各人蒙召的時候是甚麼身份，要在神面前守住這身份。","notes":[]},{"n":25,"t":"關於未婚女子，我沒有主的命令，但我既蒙主憐憫、作為一個可信靠的人，把自己的意見告訴你們。","notes":[],"heads":["未婚和寡居"]},{"n":26,"t":"因現今的艱難，據我看來，人不如安於現狀。","notes":[]},{"n":27,"t":"你已經有了妻子，就不要求擺脫；你還沒有妻子，就不要想娶妻。","notes":[]},{"n":28,"t":"你若娶妻，並不是犯罪；未婚女子若出嫁，也不是犯罪。然而，這等人會遭受肉身上的苦難，我寧願你們免受這苦難。","notes":[]},{"n":29,"t":"弟兄們，我是說：時候不多了。從此以後，那有妻子的，要像沒有一樣；","notes":[]},{"n":30,"t":"哀哭的，不像在哀哭；快樂的，不像在快樂；購買的，像一無所得；","notes":[]},{"n":31,"t":"享受這世界的，不像在享受這世界；因為這世界的局面將要過去了。","notes":[]},{"n":32,"t":"我願你們一無掛慮。沒有結婚的是為主的事掛慮，想怎樣令主喜悅；","notes":[]},{"n":33,"t":"結了婚的是為世上的事掛慮，想怎樣讓妻子喜悅，","notes":[]},{"n":34,"t":"於是，他就分心了。沒有結婚的和未婚的女子是為主的事掛慮，為要身體和心靈都聖潔；已經出嫁的是為世上的事掛慮，想怎樣讓丈夫喜悅。","notes":[]},{"n":35,"t":"我說這話是為你們的益處，不是要限制你們，而是要你們做合宜的事，得以不分心地對主忠誠。","notes":[]},{"n":36,"t":"若有人認為自己待他的女兒不合宜，女兒也過了適婚年齡，他可以隨意處理，不算有罪，讓兩人結婚就是了。","notes":["「女兒」或譯「未婚妻」。","「女兒…適婚年齡」或譯「女兒也過了年齡，應該結婚」；又或譯「對未婚妻有強烈的慾望」。"]},{"n":37,"t":"倘若有人心裏堅定，沒有不得已的事，並且由得自己作主，心裏又決定了不讓女兒結婚，這樣做也好。","notes":["「不讓女兒結婚」或譯「不跟未婚妻結婚」。"]},{"n":38,"t":"這樣看來，讓自己的女兒結婚固然是好，不讓她結婚更好。","notes":["「讓…結婚」或譯「跟自己的未婚妻結婚」。"]},{"n":39,"t":"丈夫活著的時候，妻子是受約束的；丈夫若長眠了，妻子就自由了，可以隨意再嫁，只是要嫁給主裏面的人。","notes":[]},{"n":40,"t":"然而，按我的意見，她若能守節就更有福氣。我想我自己也有神的靈的感動。","notes":[]}]},"8":{"heading":"祭過偶像的食物","verses":[{"n":1,"t":"關於祭過偶像的食物，我們曉得「我們都有知識」，但知識使人自高自大，惟有愛心能造就人。","notes":[]},{"n":2,"t":"若有人自以為知道甚麼，他其實仍不知道他所應當知道的。","notes":[]},{"n":3,"t":"若有人愛神，他就是神所認識的人了。","notes":[]},{"n":4,"t":"關於吃祭過偶像的食物，我們知道「偶像在世上算不得甚麼」；也知道「神只有一位，沒有別的」。","notes":[]},{"n":5,"t":"雖然在天上或地上有許多所謂的神明，就如他們中間有許多的神明，許多的主，","notes":[]},{"n":6,"t":"但是我們只有一位神，就是父，萬物都出於他，我們也歸於他；並只有一位主，就是耶穌基督，萬物都是藉著他而有，我們也是藉著他而有。","notes":[]},{"n":7,"t":"可是，不是人人都有這知識。有人到現在因拜慣了偶像，仍以為所吃的是祭過偶像的食物；既然他們的良心軟弱，也就污穢了。","notes":[]},{"n":8,"t":"其實，食物不能使我們更接近神，因為我們不吃也無損，吃也無益。","notes":[]},{"n":9,"t":"可是，你們要謹慎，免得你們這自由竟成了軟弱人的絆腳石。","notes":[]},{"n":10,"t":"若有人見你這有知識的在偶像的廟裏坐席，而這人的良心是軟弱的，他豈不放膽去吃那祭過偶像的食物嗎？","notes":[]},{"n":11,"t":"因此，基督為他死的那軟弱弟兄，也就因你的知識沉淪了。","notes":[]},{"n":12,"t":"你們這樣得罪弟兄，傷了他們軟弱的良心，就是得罪基督。","notes":[]},{"n":13,"t":"所以，食物若使我的弟兄跌倒，我就永遠不吃肉，免得使我的弟兄跌倒了。","notes":[]}]},"9":{"heading":"使徒的權利","verses":[{"n":1,"t":"我不是自由的嗎？我不是使徒嗎？我不是見過我們的主耶穌嗎？你們不是我在主裏面工作的成果嗎？","notes":[]},{"n":2,"t":"假若對別人來說，我不是使徒，對你們來說，我總是使徒；因為你們在主裏正是我作使徒的印證。","notes":[]},{"n":3,"t":"對那些質問我的人，這就是我的答辯。","notes":[]},{"n":4,"t":"難道我們沒有權利靠著傳福音吃喝嗎？","notes":[]},{"n":5,"t":"難道我們沒有權利帶著信主的妻子一起出入，如同其餘的使徒，和主的兄弟們，和磯法一樣嗎？","notes":[]},{"n":6,"t":"只有我和巴拿巴沒有權利不做工嗎？","notes":[]},{"n":7,"t":"有誰當兵而自備糧餉呢？有誰栽葡萄園而不吃園裏的果子呢？有誰牧養牛羊而不喝牛羊的奶呢？","notes":[]},{"n":8,"t":"我說這些話豈是照一般人的看法？律法不也是這樣說嗎？","notes":[]},{"n":9,"t":"就如摩西的律法記著：「牛在踹穀的時候，不可籠住牠的嘴。」難道神所掛念的是牛嗎？","notes":[]},{"n":10,"t":"他不全是為我們說的嗎？的確是為我們說的！因為耕種的要存著指望去耕種；收割的也要存著分享穀物的指望去收割。","notes":[]},{"n":11,"t":"我們既然把屬靈的種子撒在你們中間，若從你們收取養生之物，這還算大事嗎？","notes":[]},{"n":12,"t":"假如別人在你們身上享有這權利，何況我們呢？然而，我們並沒有用過這權利，倒是凡事忍受，免得基督的福音受到阻礙。","notes":[]},{"n":13,"t":"你們豈不知在聖殿供職的人吃聖殿中的食物嗎？在祭壇伺候的人分享壇上的供物嗎？","notes":[]},{"n":14,"t":"主也是這樣命令，要傳福音的人靠著福音養生。","notes":[]},{"n":15,"t":"但這權利我全然沒有用過。我寫這些話，並非要你們這樣待我，因為我寧可死也不讓人使我所誇的落了空。","notes":[]},{"n":16,"t":"我傳福音原沒有可誇耀的，因為我是不得已的，若不傳福音，我就有禍了。","notes":[]},{"n":17,"t":"我若甘心做這事，就有賞賜；若不甘心，責任卻已經託付給我了。","notes":[]},{"n":18,"t":"這樣，我的賞賜是甚麼呢？就是我傳福音的時候，使人不花錢得福音，免得我用盡了傳福音的權利。","notes":[]},{"n":19,"t":"我雖然是自由的，不受人管轄，但我甘心作了眾人的僕人，為贏得更多的人。","notes":[]},{"n":20,"t":"對猶太人，我就作猶太人，為要贏得猶太人；對律法以下的人，我雖不在律法以下，還是作律法以下的人，為要贏得律法以下的人。","notes":[]},{"n":21,"t":"對沒有律法的人，我就作沒有律法的人，為要贏得沒有律法的人；其實我在神面前，不是沒有律法，而是在基督的律法之下。","notes":[]},{"n":22,"t":"對軟弱的人，我就作軟弱的人，為要贏得軟弱的人。對甚麼樣的人，我就作甚麼樣的人。無論如何我總要救一些人。","notes":[]},{"n":23,"t":"凡我所做的，都是為福音的緣故，為要與人共享這福音的好處。","notes":[]},{"n":24,"t":"你們不知道在運動場上賽跑的，大家都跑，但得獎賞的只有一人？你們也要這樣跑，好使你們得著獎賞。","notes":[]},{"n":25,"t":"凡參加競賽的，在各方面都要有節制，他們不過是要得會朽壞的冠冕；我們卻是要得不會朽壞的冠冕。","notes":[]},{"n":26,"t":"所以，我奔跑，不像無目標的；我鬥拳，不像打空氣的。","notes":[]},{"n":27,"t":"我克制己身，使它完全順服，免得我傳福音給別人，自己反而被淘汰了。","notes":[]}]},"10":{"heading":"警戒拜偶像","verses":[{"n":1,"t":"弟兄們，我不願意你們不知道，我們的祖宗從前都在雲下，都從海中經過，","notes":[]},{"n":2,"t":"都在雲裏、海裏受洗歸了摩西，","notes":["「受洗」：有古卷是「為自己施洗」。"]},{"n":3,"t":"並且都吃了一樣的靈糧，","notes":[]},{"n":4,"t":"也都喝了一樣的靈水，所喝的是出於跟隨著他們的靈磐石；那磐石就是基督。","notes":[]},{"n":5,"t":"但他們中間多半是神不喜歡的人，所以倒斃在曠野裏了。","notes":[]},{"n":6,"t":"這些事都是我們的鑒戒，使我們不要貪戀惡事，像他們貪戀過的一樣。","notes":[]},{"n":7,"t":"也不要拜偶像，像他們中有些人曾經拜過。如經上所記：「百姓坐下吃喝，起來玩樂。」","notes":[]},{"n":8,"t":"我們也不可犯姦淫，像他們中有些人曾經犯過，一天就倒斃了二萬三千人。","notes":[]},{"n":9,"t":"也不可試探主，像他們中有些人曾試探主就被蛇咬死。","notes":["「主」：有古卷是「基督」。"]},{"n":10,"t":"你們也不可發怨言，像他們中有些人曾經發過，就被毀滅者所滅。","notes":[]},{"n":11,"t":"這些事發生在他們身上，要作為鑒戒，而且寫下來正是要警戒我們這末世的人。","notes":[]},{"n":12,"t":"所以，自以為站得穩的人必須謹慎，免得跌倒。","notes":[]},{"n":13,"t":"你們所受的考驗無非是人所承受得了的。神是信實的，他不會讓你們遭受無法承受的考驗，在受考驗的時候，總會給你們開一條出路，讓你們能忍受得了。","notes":[]},{"n":14,"t":"所以，我親愛的，你們要遠避拜偶像的事。","notes":[]},{"n":15,"t":"我好像對精明人說的；你們要辨別我的話。","notes":[]},{"n":16,"t":"我們所祝謝的杯，豈不是同領基督的血嗎？我們所擘開的餅，豈不是同領基督的身體嗎？","notes":[]},{"n":17,"t":"因為餅只是一個，我們雖然人多，仍是一體，我們同享一個餅。","notes":[]},{"n":18,"t":"你們看那按肉體是以色列人的，那些吃祭物的人豈不是與祭壇有份嗎？","notes":[]},{"n":19,"t":"那麼，我怎麼說呢？是說祭偶像之物算得了甚麼嗎？或說偶像算得了甚麼嗎？","notes":[]},{"n":20,"t":"不，我是說，他們所獻的祭是祭鬼，不是祭神；我不願意你們與鬼來往。","notes":["有古卷是「外邦人」。"]},{"n":21,"t":"你們不能喝主的杯，又喝鬼的杯；不能吃主的筵席，又吃鬼的筵席。","notes":[]},{"n":22,"t":"我們要惹主的嫉恨嗎？我們比他更強嗎？","notes":[]},{"n":23,"t":"「凡事都可行」，但不都有益處；「凡事都可行」，但不都造就人。","notes":[],"heads":["凡事為榮耀神而做"]},{"n":24,"t":"無論甚麼人，不要求自己的益處，而要求別人的益處。","notes":[]},{"n":25,"t":"凡市場上所賣的，你們只管吃，不要為良心的緣故問甚麼，","notes":[]},{"n":26,"t":"「因為地和其中所充滿的都屬於主」。","notes":[]},{"n":27,"t":"倘若有一個不信的人請你們吃飯，而你們也願意去，凡擺在你們面前的，只管吃，不要為良心的緣故問甚麼。","notes":[]},{"n":28,"t":"若有人對你們說：「這是獻過祭的物」，那麼為了那告訴你們的人，並為了良心的緣故就不吃。","notes":[]},{"n":29,"t":"我說的良心不是你自己的，而是他的。我的自由為甚麼被別人的良心評斷呢？","notes":[]},{"n":30,"t":"我若謝恩而吃，為甚麼因我謝恩的物被人毀謗呢？","notes":[]},{"n":31,"t":"所以，你們或吃或喝，無論做甚麼，都要為榮耀神而做。","notes":[]},{"n":32,"t":"你們不要使猶太人、希臘人，或神教會中的人跌倒；","notes":[]},{"n":33,"t":"但要像我一樣，凡事都使眾人喜歡，不求自己的益處，只求眾人的益處，使他們得救。","notes":[]}]},"11":{"heading":"禮拜時蒙頭的問題","verses":[{"n":1,"t":"你們該效法我，像我效法基督一樣。","notes":[]},{"n":2,"t":"我稱讚你們，因為你們凡事記得我，又堅守我所傳授給你們的。","notes":[]},{"n":3,"t":"但是我要你們知道：基督是男人的頭；男人是女人的頭；神是基督的頭。","notes":["「男人是女人的頭」或譯「丈夫是妻子的頭」。"]},{"n":4,"t":"凡男人禱告或講道，若蒙著頭，就是羞辱自己的頭。","notes":["「講道」或譯「說預言」；5節同。"]},{"n":5,"t":"凡女人禱告或講道，若不蒙著頭，就是羞辱自己的頭，因為這就如同剃了頭髮一樣。","notes":[]},{"n":6,"t":"女人若不蒙著頭，就該剪了頭髮；女人若以剪髮剃髮為羞愧，就該蒙著頭。","notes":[]},{"n":7,"t":"男人本不該蒙著頭，因為他是神的形像和榮耀；但女人是男人的榮耀。","notes":[]},{"n":8,"t":"起初，男人不是由女人而出，女人卻是由男人而出。","notes":[]},{"n":9,"t":"而且男人不是為女人造的，女人卻是為男人造的。","notes":[]},{"n":10,"t":"因此，女人為天使的緣故應當在頭上有服權柄的記號。","notes":[]},{"n":11,"t":"然而，照主的安排，女人不可沒有男人，男人也不可沒有女人。","notes":[]},{"n":12,"t":"因為女人原是由男人而出，男人是藉著女人而生；但萬有都是出於神。","notes":[]},{"n":13,"t":"你們自己要判斷，女人禱告神，不蒙著頭合宜嗎？","notes":[]},{"n":14,"t":"你們的本性不也教導你們，男人若留長頭髮是他的羞辱嗎？","notes":[]},{"n":15,"t":"但女人留長頭髮是她的榮耀，因為這頭髮是給她蓋頭的。","notes":["「給她蓋頭的」：有古卷是「為蓋頭的」。"]},{"n":16,"t":"若有人想要辯駁，我們卻沒有這樣的規矩，神的眾教會也沒有。","notes":[]},{"n":17,"t":"我現在吩咐你們這話不是在稱讚你們，因為你們聚會是有損無益的。","notes":[],"heads":["妄用主的聖餐"]},{"n":18,"t":"首先，我聽說你們教會聚會的時候有分裂的事，我也有些相信這話。","notes":[]},{"n":19,"t":"在你們中間必然有分門結黨的事，好使那些經得起考驗的人顯明出來。","notes":[]},{"n":20,"t":"你們聚會的時候，不是在吃主的晚餐，","notes":[]},{"n":21,"t":"因為吃的時候，各人先吃自己的飯，甚至有人飢餓，有人酒醉。","notes":[]},{"n":22,"t":"難道你們沒有家可以吃喝嗎？還是你們藐視神的教會，使那沒有的羞愧呢？我該對你們說甚麼呢？我要稱讚你們嗎？在這事上我絕不稱讚你們！","notes":[]},{"n":23,"t":"我當日傳給你們的是從主所領受的。主耶穌被出賣的那一夜，拿起餅來，","notes":[],"heads":["聖餐的設立"]},{"n":24,"t":"祝謝了，就擘開，說：「這是我的身體，為你們捨的；你們要如此行，為的是記念我。」","notes":["「捨」：有古卷是「擘開」。"]},{"n":25,"t":"飯後，他也照樣拿起杯來，說：「這杯是用我的血所立的新約；你們每逢喝的時候，要如此行，來記念我。」","notes":[]},{"n":26,"t":"你們每逢吃這餅，喝這杯，是宣告主的死，直到他來。","notes":[]},{"n":27,"t":"所以，任何不按規矩吃了主的餅，喝了主的杯，就是干犯主的身體和主的血了。","notes":[],"heads":["聖餐前應省察自己"]},{"n":28,"t":"人應該省察自己，然後吃這餅，喝這杯。","notes":[]},{"n":29,"t":"因為人吃喝，若不分辨是主的身體，他的吃喝就是定自己的罪了。","notes":[]},{"n":30,"t":"因此，在你們中間有好些軟弱的與患病的，長眠了的也不少。","notes":[]},{"n":31,"t":"我們若是先省察自己，就不至於受審判。","notes":[]},{"n":32,"t":"我們受審判的時候，就是被主管教，這樣就免得和世人一同被定罪。","notes":[]},{"n":33,"t":"所以，我的弟兄們，你們聚會吃晚餐的時候，要彼此等待。","notes":[]},{"n":34,"t":"若有人餓了，要在家裏先吃，免得你們聚會，反被定罪。其餘的事等我來的時候再安排。","notes":[]}]},"12":{"heading":"屬靈的恩賜","verses":[{"n":1,"t":"弟兄們，關於屬靈的恩賜，我不願意你們不明白。","notes":["「屬靈的恩賜」或譯「屬靈的人」。"]},{"n":2,"t":"你們知道，你們作外邦人的時候，隨事被引誘，受了迷惑去拜不會出聲的偶像。","notes":[]},{"n":3,"t":"所以，我要你們知道，被神的靈感動的，沒有人會說「耶穌該受詛咒」；若不是被聖靈感動的，也沒有人能說「耶穌是主」。","notes":[]},{"n":4,"t":"恩賜有許多種，卻是同一位聖靈所賜。","notes":[]},{"n":5,"t":"事奉有許多種，卻是事奉同一位主。","notes":[]},{"n":6,"t":"工作有許多種，卻是同一位神在萬人中運行萬事。","notes":[]},{"n":7,"t":"聖靈彰顯在各人身上，是要使人得益處。","notes":[]},{"n":8,"t":"有人藉著聖靈領受智慧的言語；有人也靠著同一位聖靈領受知識的言語；","notes":[]},{"n":9,"t":"又有人由同一位聖靈領受信心；還有人由同一位聖靈領受醫病的恩賜；","notes":[]},{"n":10,"t":"又有人能行異能，又有人能作先知，又有人能辨別諸靈，又有人能說方言，又有人能翻方言。","notes":["「方言」或譯「靈語」；本節下同，28、30節同。"]},{"n":11,"t":"這一切都是由惟一的、同一位聖靈所運行，隨著自己的旨意分給各人的。","notes":[]},{"n":12,"t":"就如身體是一個，卻有許多肢體，身體的肢體雖多，仍是一個身體；基督也是這樣。","notes":[],"heads":["一個身體有許多肢體"]},{"n":13,"t":"我們無論是猶太人是希臘人，是為奴的是自主的，都從一位聖靈受洗成了一個身體，並且共享這位聖靈。","notes":[]},{"n":14,"t":"身體原不只是一個肢體，而是許多肢體。","notes":[]},{"n":15,"t":"假如腳說：「我不是手，所以不屬於身體」，它不能因此就不屬於身體。","notes":[]},{"n":16,"t":"假如耳朵說：「我不是眼睛，所以不屬於身體」，它也不能因此就不屬於身體。","notes":[]},{"n":17,"t":"假如全身是眼睛，聽覺在哪裏呢？假如全身是耳朵，嗅覺在哪裏呢？","notes":[]},{"n":18,"t":"但現在神隨自己的意思把肢體一一安置在身體上了。","notes":[]},{"n":19,"t":"假如全都是一個肢體，身體在哪裏呢？","notes":[]},{"n":20,"t":"但現在肢體雖多，身體還是一個。","notes":[]},{"n":21,"t":"眼睛不能對手說：「我用不著你。」頭也不能對腳說：「我用不著你。」","notes":[]},{"n":22,"t":"不但如此，身上的肢體，人以為軟弱的，更是不可缺少的；","notes":[]},{"n":23,"t":"身上的肢體，我們認為不體面的，越發給它加上體面；我們不雅觀的，越發裝飾得雅觀。","notes":[]},{"n":24,"t":"我們雅觀的肢體自然用不著裝飾；但神配搭這身子，把加倍的體面給那有缺欠的肢體，","notes":[]},{"n":25,"t":"免得身體不協調，總要肢體彼此照顧。","notes":[]},{"n":26,"t":"假如一個肢體受苦，所有的肢體就一同受苦；假如一個肢體得光榮，所有的肢體就一同快樂。","notes":[]},{"n":27,"t":"你們是基督的身體，並且各自都是肢體。","notes":[]},{"n":28,"t":"神在教會所設立的：第一是使徒；第二是先知；第三是教師；其次是行異能的；再次是醫病的恩賜，幫助人的，治理事的，說方言的。","notes":[]},{"n":29,"t":"難道個個都是使徒嗎？難道個個都是先知嗎？難道個個都是教師嗎？難道個個都是行異能的嗎？","notes":[]},{"n":30,"t":"難道個個都是有醫病的恩賜嗎？難道個個都是說方言的嗎？難道個個都是翻方言的嗎？","notes":[]},{"n":31,"t":"你們要追求那更大的恩賜。我現今把最妙的道指示你們。","notes":[]}]},"13":{"heading":"","verses":[{"n":1,"t":"我若能說人間的方言，甚至天使的語言，卻沒有愛，我就成為鳴的鑼、響的鈸一般。","notes":[]},{"n":2,"t":"我若有先知講道的能力，也明白各樣的奧祕，各樣的知識，而且有齊備的信心，使我能夠移山，卻沒有愛，我就算不了甚麼。","notes":[]},{"n":3,"t":"我若將所有的財產救濟窮人，又犧牲自己的身體讓人誇讚，卻沒有愛，仍然對我無益。","notes":["「讓人誇讚」：有古卷是「給人當作祭品焚燒」。"]},{"n":4,"t":"愛是恆久忍耐；又有恩慈；愛是不嫉妒；愛是不自誇，不張狂，","notes":[]},{"n":5,"t":"不做害羞的事，不求自己的益處，不輕易發怒，不計算人的惡，","notes":[]},{"n":6,"t":"不喜歡不義，只喜歡真理；","notes":[]},{"n":7,"t":"凡事包容，凡事相信，凡事盼望，凡事忍耐。","notes":[]},{"n":8,"t":"愛是永不止息。先知講道之能終必歸於無有；說方言之能終必停止；知識也終必歸於無有。","notes":["「方言」或譯「靈語」。"]},{"n":9,"t":"我們現在所知道的有限，先知所講的也有限，","notes":[]},{"n":10,"t":"等那完全的來到，這有限的必消逝。","notes":[]},{"n":11,"t":"我作孩子的時候，說話像孩子，心思像孩子，意念像孩子；既長大成人，就把孩子的事丟棄了。","notes":[]},{"n":12,"t":"我們現在是對著鏡子觀看，模糊不清；到那時，就要面對面了。我如今所認識的有限，到那時就全認識，如同主認識我一樣。","notes":["「模糊不清」：原文直譯「如同猜謎」。"]},{"n":13,"t":"如今常存的有信，有望，有愛這三樣，其中最大的是愛。","notes":[]}]},"14":{"heading":"說方言和作先知講道","verses":[{"n":1,"t":"你們要追求愛，也要切慕屬靈的恩賜，尤其是作先知講道。","notes":["「先知講道」：原文直譯「說預言」；3節同。"]},{"n":2,"t":"那說方言的，不是對人說，而是對神說，因為沒有人聽得懂；他是藉著聖靈說各樣的奧祕。","notes":["「方言」或譯「靈語」；4、5、6、13、14、16、18、19、22、23、24、26、27、39節同。"]},{"n":3,"t":"但作先知講道的，是對人說，要造就、安慰、勸勉人。","notes":[]},{"n":4,"t":"說方言的，是造就自己；作先知講道的，是造就教會。","notes":[]},{"n":5,"t":"我希望你們都說方言，更希望你們作先知講道；因為說方言的，若不解釋出來，使教會得造就，那作先知講道的就比他強了。","notes":[]},{"n":6,"t":"弟兄們，我到你們那裏去，若只說方言，不用啟示，或知識，或預言，或教導，給你們講解，我對你們有甚麼益處呢？","notes":[]},{"n":7,"t":"就連那有聲而沒有生命的東西，如簫，如琴，發出來的音若沒有分別，怎能知道所吹所彈的是甚麼呢？","notes":[]},{"n":8,"t":"號角吹出來的音若不清楚，誰會預備打仗呢？","notes":[]},{"n":9,"t":"你們也是如此；若用舌頭說聽不懂的信息，怎能知道所說的是甚麼呢？你們就是向空氣說話了。","notes":[]},{"n":10,"t":"世上有許多種語言，卻沒有一樣是無意思的。","notes":[]},{"n":11,"t":"我若不明白那語言的意思，說話的人必以我為未開化的人，我也以他為未開化的人。","notes":[]},{"n":12,"t":"你們也是如此，既然你們切慕屬靈的恩賜，就當追求多得造就教會的恩賜。","notes":[]},{"n":13,"t":"所以，那說方言的，就當祈求有翻方言的恩賜。","notes":[]},{"n":14,"t":"我若用方言禱告，是我的靈在禱告；但我的理智沒有效果。","notes":[]},{"n":15,"t":"我應該怎麼做呢？我要用靈禱告，也要用理智禱告；我要用靈歌唱，也要用理智歌唱。","notes":[]},{"n":16,"t":"不然，你用靈祝謝，那在座不通方言的人，既然不明白你的話，怎能在你感謝的時候說「阿們」呢？","notes":[]},{"n":17,"t":"你的感謝固然是好，不過不能造就別人。","notes":[]},{"n":18,"t":"我感謝神，我說方言比你們眾人還多；","notes":[]},{"n":19,"t":"但在教會中，我寧可用理智說五句教導人的話，強過說萬句方言。","notes":[]},{"n":20,"t":"弟兄們，在心志上不要作小孩子。但是，在惡事上要作嬰孩，而在心志上總要作大人。","notes":[]},{"n":21,"t":"律法上記著：「主說：我要用外邦人的舌頭和外邦人的嘴唇向這百姓說話；雖然如此，他們還是不聽從我。」","notes":[]},{"n":22,"t":"這樣看來，說方言不是為信的人作標記，而是為不信的人；作先知講道不是為不信的人作標記，而是為信的人。","notes":[]},{"n":23,"t":"所以，全教會聚在一處的時候，若都說方言，偶然有不通方言的或是不信的人進來，豈不會說你們瘋了嗎？","notes":[]},{"n":24,"t":"若個個都作先知講道，偶然有不信的或是不懂方言的人進來，就被眾人勸戒，被眾人審問，","notes":[]},{"n":25,"t":"他心裏的隱情被顯露出來，就必將臉伏地，敬拜神，宣告說：「神真的是在你們中間了。」","notes":[]},{"n":26,"t":"弟兄們，那麼，你們該怎麼做呢？你們聚會的時候，各人或有詩歌，或有教導，或有啟示，或有方言，或有翻出來，凡事都應當造就人。","notes":[],"heads":["凡事都要按次序行"]},{"n":27,"t":"若有說方言的，只可有兩個人，至多三個人，且要輪流著說，也要有一個人翻出來。","notes":[]},{"n":28,"t":"若沒有人翻，就當在會中閉口，只對自己和神說就是了。","notes":[]},{"n":29,"t":"至於作先知講道的，只可有兩個人或是三個人，其餘的人當慎思明辨。","notes":[]},{"n":30,"t":"假如旁邊坐著的得了啟示，那先說話的就當閉口不言。","notes":[]},{"n":31,"t":"因為你們都可以一個一個地作先知講道，使眾人都可以學習，使眾人都得勸勉。","notes":[]},{"n":32,"t":"先知的靈是順服先知的，","notes":[]},{"n":33,"t":"因為神不是叫人混亂，而是叫人和諧的神。在聖徒的眾教會中，","notes":[]},{"n":34,"t":"婦女應該閉口不言；因為，不准她們說話，總要順服，正如律法所說的。","notes":[]},{"n":35,"t":"她們若要學甚麼，應該在家裏問自己的丈夫，因為婦女在會中說話是可恥的。","notes":[]},{"n":36,"t":"難道神的話是從你們出來的嗎？難道是單臨到你們的嗎？","notes":[]},{"n":37,"t":"若有人自以為是先知，或是屬靈的，就應該知道，我所寫給你們的是主的命令。","notes":[]},{"n":38,"t":"若有不理會的，你們也不必理會他。","notes":[]},{"n":39,"t":"所以，我的弟兄們，你們要切慕作先知講道的恩賜，不要禁止說方言。","notes":[]},{"n":40,"t":"凡事都要規規矩矩地按著次序行。","notes":[]}]},"15":{"heading":"基督的復活","verses":[{"n":1,"t":"弟兄們，我要你們認清我先前傳給你們的福音；這福音你們領受了，又靠著它站立得住，","notes":[]},{"n":2,"t":"你們若能夠持守我傳給你們的信息，就必因這福音得救，否則你們是徒然相信。","notes":[]},{"n":3,"t":"我當日所領受又傳給你們的，最重要的就是：照聖經所說，基督為我們的罪死了，","notes":[]},{"n":4,"t":"而且埋葬了；又照聖經所說，第三天復活了，","notes":[]},{"n":5,"t":"還顯給磯法看，又顯給十二使徒看，","notes":[]},{"n":6,"t":"後來一次顯給五百多弟兄看，其中一大半到現在還在，卻也有已經睡了的。","notes":[]},{"n":7,"t":"以後他顯給雅各看，再顯給眾使徒看，","notes":[]},{"n":8,"t":"最後也顯給我看；我如同未到產期而生的人一般。","notes":[]},{"n":9,"t":"我原是使徒中最小的，不配稱為使徒，因為我曾迫害過神的教會。","notes":[]},{"n":10,"t":"然而，由於神的恩典，我才成了今日的我，並且他所賜給我的恩典不是徒然的。我比眾使徒格外勞苦；其實不是我，而是神的恩典與我同在。","notes":[]},{"n":11,"t":"無論是我或是其他使徒，我們都如此傳，你們也都如此信了。","notes":[]},{"n":12,"t":"既然我們傳基督是從死人中復活了，怎麼在你們中間有人說沒有死人復活的事呢？","notes":[],"heads":["死人的復活"]},{"n":13,"t":"若沒有死人復活的事，基督就沒有復活了。","notes":[]},{"n":14,"t":"基督若沒有復活，我們所傳的就是枉然，你們所信的也是枉然。","notes":[]},{"n":15,"t":"這樣，我們甚至被當作是為神妄作見證的，因為我們見證神是使基督復活了。如果死人真的沒有復活，神就沒有使基督復活了。","notes":[]},{"n":16,"t":"因為死人若不復活，基督也就沒有復活了。","notes":[]},{"n":17,"t":"基督若沒有復活，你們的信就是徒然，你們仍活在罪裏。","notes":[]},{"n":18,"t":"就是在基督裏睡了的人也滅亡了。","notes":[]},{"n":19,"t":"我們若靠基督只在今生有指望，就比所有的人更可憐了。","notes":[]},{"n":20,"t":"其實，基督已經從死人中復活，成為睡了之人初熟的果子。","notes":[]},{"n":21,"t":"既然死是因一人而來，死人復活也因一人而來。","notes":[]},{"n":22,"t":"在亞當裏眾人都死了；同樣，在基督裏眾人也都要復活。","notes":[]},{"n":23,"t":"但各人是按著自己的次序復活：初熟的果子是基督；然後在他來的時候，是那些屬於基督的。","notes":[]},{"n":24,"t":"再後，終結到了，那時基督既將一切執政的、掌權的、有權能的都毀滅了，就把國交給父神。","notes":[]},{"n":25,"t":"因為基督必須掌權，等神把一切仇敵都放在他的腳下。","notes":[]},{"n":26,"t":"他要毀滅的最後仇敵就是死亡。","notes":[]},{"n":27,"t":"因為經上說：「神使萬物都服在他的腳下。」既然說萬物都服了他，那使萬物屈服的，很明顯地是不在其內了。","notes":[]},{"n":28,"t":"既然萬物服了他，那時，子也要自己順服那叫萬物服他的，好使神在萬物之中，在萬物之上。","notes":[]},{"n":29,"t":"不然，那些為死人受洗的，能做甚麼呢？如果死人不會復活，為甚麼替他們受洗呢？","notes":[]},{"n":30,"t":"我們為甚麼要時刻冒險呢？","notes":[]},{"n":31,"t":"弟兄們，我在我們的主基督耶穌裏，指著你們—我所誇的極力地說，我天天冒死。","notes":["有古卷沒有「弟兄們」。"]},{"n":32,"t":"從人的觀點看來，我當日在以弗所同野獸搏鬥，對我有甚麼益處呢？如果死人沒有復活，「讓我們吃吃喝喝吧！因為明天要死了。」","notes":[]},{"n":33,"t":"不要被欺騙了；「濫交朋友敗壞品德。」","notes":[]},{"n":34,"t":"你們要醒悟為善，不再犯罪；因為有人不認識神。我說這話是要使你們羞愧。","notes":[]},{"n":35,"t":"但是有人會問：「死人怎樣復活呢？他們帶著甚麼身體來呢？」","notes":[],"heads":["復活的身體"]},{"n":36,"t":"無知的人哪，你所種的若不死就不能生。","notes":[]},{"n":37,"t":"並且你所種的不是那將來要有的形體，無論是麥子或別樣穀物，都不過是子粒。","notes":[]},{"n":38,"t":"但神隨自己的意思給它一個形體，並叫各樣子粒各有自己的形體。","notes":[]},{"n":39,"t":"不是所有的肉體都是同樣的：人是一個樣子，獸又是一個樣子，鳥又是一個樣子，魚又是一個樣子。","notes":[]},{"n":40,"t":"有天上的形體，也有地上的形體；但天上形體的榮光是一個樣子，地上形體的榮光又是一個樣子。","notes":[]},{"n":41,"t":"日有日的光輝，月有月的光輝，星有星的光輝；這星和那星的光輝也有區別。","notes":[]},{"n":42,"t":"死人復活也是這樣。所種的是會朽壞的，復活的是不朽壞的；","notes":[]},{"n":43,"t":"所種的是羞辱的，復活的是榮耀的；所種的是軟弱的，復活的是強壯的；","notes":[]},{"n":44,"t":"所種的是血肉的身體，復活的是靈性的身體。既有血肉的身體，也就有靈性的身體。","notes":[]},{"n":45,"t":"經上也是這樣記著說：「首先的人亞當成了有生命的人」；末後的亞當成了賜生命的靈。","notes":[]},{"n":46,"t":"但是，不是屬靈的在先，而是屬血肉的在先，然後才是屬靈的。","notes":[]},{"n":47,"t":"第一個人是出於地，是屬於塵土；第二個人是出於天。","notes":[]},{"n":48,"t":"那屬塵土的怎樣，凡屬塵土的也都怎樣；屬天的怎樣，凡屬天的也都怎樣。","notes":[]},{"n":49,"t":"就如我們既有屬塵土的形像，將來也必有屬天的形像。","notes":[]},{"n":50,"t":"弟兄們，我要告訴你們的是：血肉之軀不能承受神的國，必朽壞的也不能承受不朽壞的。","notes":[]},{"n":51,"t":"我如今把一件奧祕的事告訴你們：我們不是都要睡覺，而是都要改變，","notes":[]},{"n":52,"t":"就在一剎那，眨眼之間，號筒末次吹響的時候。因號筒要吹響，死人要復活成為不朽壞的，我們也要改變。","notes":[]},{"n":53,"t":"這會朽壞的必須變成不朽壞的；這會死的總要變成不會死的。","notes":["「變成」：原文直譯「穿」﹔下同。"]},{"n":54,"t":"當這會朽壞的變成不朽壞的，這會死的變成不會死的，那時經上所記「死亡已被勝利吞滅了」的話就應驗了。","notes":[]},{"n":55,"t":"「死亡啊！你得勝的權勢在哪裏？死亡啊！你的毒刺在哪裏？」","notes":[]},{"n":56,"t":"死亡的毒刺就是罪，罪的權勢就是律法。","notes":[]},{"n":57,"t":"感謝神，他使我們藉著我們的主耶穌基督得勝。","notes":[]},{"n":58,"t":"所以，我親愛的弟兄們，你們務要堅固，不可動搖，常常竭力多做主工，因為你們知道，你們在主裏的勞苦不是徒然的。","notes":[]}]},"16":{"heading":"捐助聖徒","verses":[{"n":1,"t":"關於為聖徒捐款的事，我從前怎樣吩咐加拉太的眾教會，你們也該怎樣做。","notes":[]},{"n":2,"t":"每逢七日的第一日，每人要照自己的收入抽出若干，保留起來，免得我來的時候現湊。","notes":[]},{"n":3,"t":"等到我來了，你們寫信舉薦誰，我就差遣他們，把你們的款項送到耶路撒冷去。","notes":[]},{"n":4,"t":"如果我也該去，他們可以和我同去。","notes":[]},{"n":5,"t":"我想穿越馬其頓；我經過了馬其頓後，就到你們那裏去，","notes":[],"heads":["行程的計劃"]},{"n":6,"t":"可能會和你們同住一些時候，甚至和你們一起過冬。這樣無論我往哪裏去，你們可以給我送行。","notes":[]},{"n":7,"t":"我現在不願意在路過的時候見你們；主若允許，我就指望和你們同住一些時候。","notes":[]},{"n":8,"t":"不過我要仍舊住在以弗所，直到五旬節，","notes":[]},{"n":9,"t":"因為有又寬大又有效的門為我開了，雖然反對的人也多。","notes":[]},{"n":10,"t":"若是提摩太來到，你們要留心照顧他，使他在你們那裏無所懼怕，因為他做主的工作像我一樣。","notes":[]},{"n":11,"t":"所以，無論誰都不可藐視他。只要送他平安前行，讓他到我這裏來，因為我等著他和弟兄們同來。","notes":[]},{"n":12,"t":"至於亞波羅弟兄，我再三勸他同弟兄們到你們那裏去；但現在他絕不願意去，等有機會他就會去。","notes":[]},{"n":13,"t":"你們要警醒，在信仰上要站穩，要勇敢，要剛強。","notes":[],"heads":["最後的請求和問安"]},{"n":14,"t":"你們所做的一切都要憑愛心而做。","notes":[]},{"n":15,"t":"弟兄們，你們知道司提法那一家，是亞該亞初結的果子；他們專以服事聖徒為念。","notes":[]},{"n":16,"t":"我勸你們順服這樣的人，和一切與他同工同勞的人。","notes":[]},{"n":17,"t":"司提法那、福徒拿都和亞該古到這裏來，我很高興，因為他們補上了你們不在我身邊的遺憾。","notes":[]},{"n":18,"t":"他們使我和你們心裏都快慰；這樣的人，你們務要敬重。","notes":[]},{"n":19,"t":"亞細亞的眾教會向你們問安。亞居拉、百基拉，和在他們家裏的教會，在主裏熱切地向你們問安。","notes":[]},{"n":20,"t":"眾弟兄都向你們問安。要用聖潔的吻彼此問安。","notes":[]},{"n":21,"t":"我—保羅親筆問安。","notes":[]},{"n":22,"t":"若有人不愛主，這人該受詛咒。主啊，願你來！","notes":[]},{"n":23,"t":"願主耶穌基督的恩常與你們眾人同在。","notes":[]},{"n":24,"t":"我在基督耶穌裏的愛與你們同在！","notes":["有古卷加「阿們！」"]}]}},"2CO":{"1":{"heading":"問候","verses":[{"n":1,"t":"奉神旨意作基督耶穌使徒的保羅和弟兄提摩太，寫信給在哥林多神的教會和全亞該亞的眾聖徒。","notes":[]},{"n":2,"t":"願恩惠、平安從我們的父神和主耶穌基督歸給你們！","notes":["「平安」或譯「和平」。"]},{"n":3,"t":"願頌讚歸於神—我們主耶穌基督的父；他是發慈悲的父，賜各樣安慰的神。","notes":[]},{"n":4,"t":"我們在一切患難中，他安慰我們，使我們能用神所賜的安慰去安慰那些遭各樣患難的人。","notes":[]},{"n":5,"t":"正如我們跟基督同受許多苦楚，我們也靠基督得許多安慰。","notes":[]},{"n":6,"t":"如果我們受患難，那是為使你們得安慰，得拯救；如果我們得安慰，那也是為使你們得安慰，這安慰能使你們忍受我們所受同樣的苦楚。","notes":[]},{"n":7,"t":"我們為你們所存的盼望是確定的，因為知道你們分擔了我們的痛苦，也要分享我們的安慰。","notes":[]},{"n":8,"t":"弟兄們，我們不要你們不知道，我們從前在亞細亞遭遇苦難，因受到無法忍受的壓力，甚至連活命的指望都沒有了。","notes":[]},{"n":9,"t":"自己心裏也斷定是必死無疑，這是要使我們不依靠自己，只依靠使死人復活的神。","notes":[]},{"n":10,"t":"他曾救我們脫離那極大的死亡，他要繼續救我們，而且我們指望他將來還要救我們。","notes":[]},{"n":11,"t":"你們也要一同用祈禱來幫助我們，好使許多人為我們感恩，因著他們許多的禱告，我們獲得了恩賜。","notes":[]},{"n":12,"t":"我們所誇的是：我們在世為人，特別是跟你們的關係，是憑著神所賜的坦率和真誠，不是靠人的聰明，而是靠神的恩惠；這是我們的良心可以作證的。","notes":[],"heads":["保羅延期訪問哥林多"]},{"n":13,"t":"我們現在寫給你們的話，無非是你們所能誦讀、所能明白的，我也盼望你們真能徹底明白。","notes":[]},{"n":14,"t":"你們已經有幾分認識我們，在我們主耶穌的日子，你們會以我們為榮，正像我們也以你們為榮。","notes":["「主耶穌」：有古卷是「主」。"]},{"n":15,"t":"既然我這樣深信，早就有意先到你們那裏去，讓你們得加倍的益處。","notes":[]},{"n":16,"t":"我要路過你們那裏往馬其頓去，再從馬其頓回到你們那裏，讓你們給我送行往猶太去。","notes":[]},{"n":17,"t":"我有此意，難道是反覆不定嗎？難道我的意願是從私慾起的，以致我忽是忽非嗎？","notes":[]},{"n":18,"t":"我指著信實的神說，我們向你們所傳的道並非又是又非的。","notes":[]},{"n":19,"t":"因為，我、西拉和提摩太在你們中間傳神的兒子耶穌基督，從沒有「又是又非」的；在他只有一個「是」。","notes":[]},{"n":20,"t":"神的應許，不論有多少，在基督都是「是」的。所以，我們藉著他說「阿們」，使神因我們得榮耀。","notes":[]},{"n":21,"t":"那在基督裏堅固我們和你們，並且膏抹我們的，就是神。","notes":[]},{"n":22,"t":"他在我們身上蓋了印，並賜聖靈在我們心裏作憑據。","notes":[]},{"n":23,"t":"我指著我的性命求告神作證，我沒有再往哥林多去是為了要寬容你們。","notes":[]},{"n":24,"t":"我們並不是要控制你們的信心，而是要作你們的同工，讓你們得快樂，因為你們在信仰上已經站得穩了。","notes":[]}]},"2":{"heading":"赦免犯過失的人","verses":[{"n":1,"t":"我自己定了主意，下次不再帶著悲傷到你們那裏去。","notes":[]},{"n":2,"t":"我若使你們悲傷，除了因我而使他悲傷的那人以外，誰能使我喜樂呢？","notes":[]},{"n":3,"t":"我曾把這事寫給你們，免得我到的時候，那該令我喜樂的人反倒令我悲傷。我也深信，你們眾人都以我的喜樂為自己的喜樂。","notes":[]},{"n":4,"t":"我先前憂心忡忡、眼淚汪汪地給你們寫了信，並非要使你們悲傷，而是要你們知道我格外疼愛你們。","notes":[]},{"n":5,"t":"如果有人使人悲傷，他不但使我悲傷，也是使你們眾人有些悲傷。我說有些，恐怕說得太重了。","notes":[]},{"n":6,"t":"這樣的人受了大多數人的責備也就夠了，","notes":[]},{"n":7,"t":"倒不如赦免他，安慰他，免得他過分悲傷，甚至受不了啦！","notes":[]},{"n":8,"t":"所以，我勸你們，要向他肯定你們的愛心。","notes":[]},{"n":9,"t":"為此，我先前也寫信給你們，正是要考驗你們，看你們是否在一切事上都順從我。","notes":[]},{"n":10,"t":"你們赦免誰，我也赦免誰。我若有所赦免，是在基督面前為你們的緣故赦免的，","notes":[]},{"n":11,"t":"免得撒但趁著機會勝過我們，因我們並非不知道他的詭計。","notes":[]},{"n":12,"t":"我從前為基督的福音到了特羅亞，主給我開了門。","notes":[],"heads":["保羅的不安和安慰"]},{"n":13,"t":"那時，因為沒有遇見我的弟兄提多，我心裏不安，就辭別那裏的人，往馬其頓去了。","notes":[]},{"n":14,"t":"感謝神！他常率領我們在基督裏得勝，並藉著我們在各處顯揚那因認識基督而有的香氣。","notes":[]},{"n":15,"t":"因為無論在得救的人或在滅亡的人當中，我們都是基督馨香之氣，是獻給神的。","notes":[]},{"n":16,"t":"對滅亡的人，這是死而又死的氣味；對得救的人，這是生而又生的氣味。這些事誰能當得起呢？","notes":[]},{"n":17,"t":"我們不像許多人，把神的道當商品販賣，而是由於真誠，而是受命於神，在神面前憑著基督講道。","notes":[]}]},"3":{"heading":"新約的執事","verses":[{"n":1,"t":"難道我們又開始推薦自己嗎？難道我們像某些人那樣要用人的推薦信介紹給你們，或用你們的推薦信給人嗎？","notes":[]},{"n":2,"t":"你們就是我們的推薦信，寫在我們心裏，被眾人所知道、所誦讀的，","notes":[]},{"n":3,"t":"而你們顯明自己是基督的書信，藉著我們寫成的。不是用墨寫的，而是用永生神的靈寫的；不是寫在石版上，而是寫在心版上的。","notes":[]},{"n":4,"t":"我們藉著基督才對神有這樣的信心。","notes":[]},{"n":5,"t":"並不是我們憑自己配做甚麼事，我們之所以配做是出於神；","notes":[]},{"n":6,"t":"他使我們能配作新約的執事，不是文字上的約，而是聖靈的約；因為文字使人死，聖靈能使人活。","notes":[]},{"n":7,"t":"那用字刻在石頭上屬死的事奉尚且有榮光，以致以色列人因摩西臉上那逐漸褪色的榮光不能定睛看他的臉，","notes":[]},{"n":8,"t":"那屬聖靈的事奉不是更有榮光嗎？","notes":[]},{"n":9,"t":"若是那使人定罪的事奉有榮光，那使人稱義的事奉的榮光就越發大了。","notes":[]},{"n":10,"t":"那從前有榮光的，因這更大的榮光，就算不得有榮光了；","notes":[]},{"n":11,"t":"若是那逐漸褪色的有榮光，這長存的就更有榮光了。","notes":[]},{"n":12,"t":"既然我們有這樣的盼望，就大有膽量，","notes":[]},{"n":13,"t":"不像摩西將面紗蒙在臉上，使以色列人不能定睛看到那逐漸褪色的榮光的結局。","notes":[]},{"n":14,"t":"但他們的心地剛硬，直到今日誦讀舊約的時候，這同樣的面紗還沒有揭去；因為這面紗在基督裏才被廢去。","notes":[]},{"n":15,"t":"然而直到今日，每逢誦讀摩西書的時候，面紗還在他們心上。","notes":[]},{"n":16,"t":"但他們的心何時歸向主，面紗就何時除去。","notes":[]},{"n":17,"t":"主就是那靈；主的靈在哪裏，哪裏就有自由。","notes":[]},{"n":18,"t":"既然我們眾人以揭去面紗的臉得以看見主的榮光，好像從鏡子裏返照，就變成了與主有同樣的形像，榮上加榮，如同從主的靈變成的。","notes":["「看見」或譯「反映」。","「從主的靈」或譯「從主，就是靈」。"]}]},"4":{"heading":"瓦器裏的寶貝","verses":[{"n":1,"t":"所以，既然我們蒙憐憫受了這事奉的責任，就不喪膽，","notes":[]},{"n":2,"t":"反而把那些暗昧可恥的事棄絕了，不行詭詐，不曲解神的道，只將真理顯揚出來，好在神面前把自己推薦給各人的良心。","notes":[]},{"n":3,"t":"即使我們的福音被遮蔽，那只是對滅亡的人遮蔽。","notes":[]},{"n":4,"t":"這些不信的人被這世界的神明弄瞎了心眼，使他們看不見基督榮耀的福音。基督本是神的像。","notes":[]},{"n":5,"t":"我們不是傳自己，而是傳耶穌基督為主，並且自己因耶穌作你們的僕人。","notes":[]},{"n":6,"t":"那吩咐光從黑暗裏照出來的神已經照在我們心裏，使我們知道神榮耀的光顯在耶穌基督的臉上。","notes":[]},{"n":7,"t":"我們有這寶貝放在瓦器裏，為要顯明這莫大的能力是出於神，不是出於我們。","notes":[]},{"n":8,"t":"我們處處受困，卻不被捆住；內心困擾，卻沒有絕望；","notes":[]},{"n":9,"t":"遭受迫害，卻不被撇棄；擊倒在地，卻不致滅亡。","notes":[]},{"n":10,"t":"我們身上常帶著耶穌的死，使耶穌的生也在我們身上顯明。","notes":[]},{"n":11,"t":"因為我們這活著的人常為耶穌被置於死地，使耶穌的生命在我們這必死的人身上顯明出來。","notes":[]},{"n":12,"t":"這樣看來，死是在我們身上運作，生卻在你們身上運作。","notes":[]},{"n":13,"t":"但我們既然有從同一位靈而來的信心，正如經上記著：「我信，故我說話」，我們也信，所以也說話；","notes":[]},{"n":14,"t":"因為知道，那使主耶穌復活的也必使我們與耶穌一同復活，並且使我們與你們一起站在他面前。","notes":[]},{"n":15,"t":"凡事都是為了你們，好使恩惠既藉著更多的人而加增，感恩也格外顯多，好歸榮耀給神。","notes":[]},{"n":16,"t":"所以，我們不喪膽。雖然我們外在的人日漸朽壞，內在的人卻日日更新。","notes":[],"heads":["靠信心生活"]},{"n":17,"t":"我們這短暫而輕微的苦楚要為我們成就極重、無比、永遠的榮耀。","notes":[]},{"n":18,"t":"因為我們不是顧念看得見的，而是顧念看不見的；原來看得見的是暫時的，看不見的才是永遠的。","notes":[]}]},"5":{"heading":"勸人與神和好的職分","verses":[{"n":1,"t":"因為我們知道，我們這地上的帳篷若拆毀了，我們將有神所造的居所，不是人手所造的，而是在天上永存的。","notes":[]},{"n":2,"t":"我們在這帳篷裏嘆息，渴望得到那從天上來的居所，好像穿上衣服；","notes":[]},{"n":3,"t":"倘若脫下也不至於赤身了。","notes":["有古卷是「倘若穿上就」。"]},{"n":4,"t":"其實，我們在這帳篷裏的人勞苦嘆息，並不是願意脫下地上的帳篷，而是願意穿上天上的居所，好使這必死的被生命吞滅了。","notes":[]},{"n":5,"t":"那為我們安排這事的是神，他賜給我們聖靈作憑據。","notes":["「憑據」：原文直譯「質」。"]},{"n":6,"t":"所以，我們總是勇敢的，並且知道，只要我們住在這身體內就是離開了主。","notes":[]},{"n":7,"t":"因為我們行事為人是憑著信心，不是憑著眼見。","notes":[]},{"n":8,"t":"我們勇敢，更情願離開身體，與主同住。","notes":[]},{"n":9,"t":"所以，無論是住在身內或住在身外，我們都立了志向要得主的喜悅。","notes":[]},{"n":10,"t":"因為我們眾人必須站在基督審判臺前受審，為使各人按著本身所行的，或善或惡受報。","notes":[]},{"n":11,"t":"既然我們知道主是可畏的，就勸導人；但是神是認識我們的，我盼望你們的良心也認識我們。","notes":[]},{"n":12,"t":"我們不是向你們再推薦自己，而是要讓你們有誇耀我們的機會，使你們好面對那憑外貌、不憑內心誇耀的人。","notes":[]},{"n":13,"t":"如果我們癲狂，是為神；如果我們清醒，是為你們。","notes":[]},{"n":14,"t":"原來基督的愛激勵我們；因我們這樣斷定，一人既替眾人死，眾人就都死了；","notes":[]},{"n":15,"t":"並且他替眾人死，是叫那些活著的人不再為自己活，乃為替他們死而復活的主活。","notes":[]},{"n":16,"t":"所以，從今以後，我們不再按照人的看法來認識人，縱使我們曾經按照人的看法認識基督，如今卻不再這樣認識他了。","notes":[]},{"n":17,"t":"所以，若有人在基督裏，他就是新造的人，舊事已過，都變成新的了。","notes":[]},{"n":18,"t":"一切都是出於神；他藉著基督使我們與他和好，又將勸人與他和好的使命賜給我們。","notes":[]},{"n":19,"t":"這就是：神在基督裏使世人與自己和好，不將他們的過犯歸到他們身上，並且將這和好的信息託付了我們。","notes":[]},{"n":20,"t":"所以，我們作基督的特使，就好像神藉我們勸你們一般。我們替基督求你們，與神和好吧！","notes":[]},{"n":21,"t":"神使那無罪的，替我們成為罪，好使我們在他裏面成為神的義。","notes":["「無罪」：原文直譯「不知罪」。"]}]},"6":{"heading":"永生神的殿","verses":[{"n":1,"t":"我們與神同工的也勸你們，不可白受他的恩典；","notes":[]},{"n":2,"t":"因為他說：「在悅納的時候，我應允了你；在拯救的日子，我幫助了你。」看哪，現在正是悅納的時候！看哪，現在正是拯救的日子！","notes":[]},{"n":3,"t":"我們不在任何事上妨礙任何人，免得這使命被人毀謗；","notes":[]},{"n":4,"t":"反倒在各樣的事上表明自己是神的用人：就如在持久的忍耐、患難、困苦、災難、","notes":[]},{"n":5,"t":"鞭打、監禁、動亂、勞碌、失眠、飢餓、","notes":[]},{"n":6,"t":"廉潔、知識、堅忍、恩慈、聖靈的感化、無偽的愛心、","notes":[]},{"n":7,"t":"真實的言語、神的大能、藉著仁義的兵器在左在右、","notes":[]},{"n":8,"t":"榮譽或羞辱、惡名或美名。我們似乎是誘惑人的，卻是誠實的；","notes":[]},{"n":9,"t":"似乎不為人所知，卻是人所共知；似乎是死了，卻是活著；似乎受懲罰，卻沒有被處死；","notes":[]},{"n":10,"t":"似乎憂愁，卻常有喜樂；似乎貧窮，卻使許多人富足；似乎一無所有，卻樣樣都有。","notes":[]},{"n":11,"t":"哥林多人哪，我們對你們，口是誠實的，心是寬宏的。","notes":[]},{"n":12,"t":"你們的狹窄不是由於我們，而是由於你們自己的心腸狹窄。","notes":[]},{"n":13,"t":"你們也要照樣用寬宏的心報答我；我這話正像對自己的孩子說的。","notes":[]},{"n":14,"t":"你們不要和不信的人同負一軛。義和不義有甚麼相關？光明和黑暗有甚麼相連？","notes":[]},{"n":15,"t":"基督和彼列有甚麼相和？信主的和不信主的有甚麼相干？","notes":["「彼列」是撒但的別名。"]},{"n":16,"t":"神的殿和偶像有甚麼相同？因為我們是永生神的殿，就如神曾說：「我要在他們中間居住來往；我要作他們的神，他們要作我的子民。」","notes":[]},{"n":17,"t":"所以主說：「你們務要從他們中間出來，跟他們分別；不要沾不潔淨的東西，我就收納你們。","notes":[]},{"n":18,"t":"我要作你們的父，你們要作我的兒女。這是全能的主說的。」","notes":[]}]},"7":{"heading":"保羅為教會悔改而歡喜","verses":[{"n":1,"t":"所以，親愛的，既然我們有這樣的應許，就當潔淨自己，除去身體和靈魂一切的污穢，藉著敬畏神，得以成聖。","notes":[]},{"n":2,"t":"寬宏大量地接納我們吧！我們未曾虧負誰，未曾敗壞誰，未曾佔誰的便宜。","notes":[]},{"n":3,"t":"我說這話，不是要定你們的罪，我已經說過，你們常在我們心裏，我們情願與你們同生共死。","notes":[]},{"n":4,"t":"我對你們很是放心，多多誇耀你們；我滿有安慰，在我們一切患難中格外喜樂。","notes":[]},{"n":5,"t":"我們從前到了馬其頓的時候，身體沒有絲毫安寧，反而到處遭患難，外有紛爭，內有懼怕。","notes":[]},{"n":6,"t":"但那安慰灰心之人的神藉著提多來安慰了我們；","notes":[]},{"n":7,"t":"不但藉著他來，也藉著他從你們所得的安慰，安慰了我們，因為他把你們的思念，你們的哀慟，你們對我的熱忱，都告訴了我，使我更加歡喜。","notes":[]},{"n":8,"t":"即使我先前那封信使你們憂愁，後來我曾懊悔，如今卻不懊悔；因為我知道，那封信使你們憂愁，不過是暫時的。","notes":[]},{"n":9,"t":"如今我歡喜，不是因你們曾憂愁，而是因憂愁導致你們的悔改。你們依著神的意思憂愁，凡事就不至於因我們受虧損了。","notes":[]},{"n":10,"t":"因為依著神的意思而憂愁，就生出沒有懊悔的悔改來，以致得救；但世俗的憂愁叫人死。","notes":[]},{"n":11,"t":"你看，你們依著神的意思而憂愁，這在你們當中產生了何等的殷勤、甚至辯白、甚至憤慨、甚至恐懼、甚至渴望、甚至熱忱、甚至責罰。在這一切事上，你們都表明自己是無可指責的。","notes":[]},{"n":12,"t":"所以，雖然我從前寫信給你們，卻不是為那虧負人的，也不是為那受人虧負的，而是要在神面前把你們顧念我們的熱忱表現出來。","notes":[]},{"n":13,"t":"因此，我們得了安慰。在我們所得的安慰之外，又因你們眾人使提多心裏暢快喜樂，我們就更加歡喜了。","notes":[]},{"n":14,"t":"我若對提多誇獎過你們甚麼，也不覺得慚愧，因為我對提多誇獎你們的話是真的，正如我對你們所說的話也向來都是真的。","notes":[]},{"n":15,"t":"提多一想起你們眾人的順服，怎樣恐懼戰兢地接待他，他愛你們的心就越發熱切了。","notes":[]},{"n":16,"t":"我如今歡喜，因為我在一切事上對你們有信心。","notes":[]}]},"8":{"heading":"慷慨的捐助","verses":[{"n":1,"t":"弟兄們，我們要把神賜給馬其頓眾教會的恩惠告訴你們：","notes":[]},{"n":2,"t":"他們在患難中受大考驗的時候，仍然滿有喜樂，在極度貧窮中還格外顯出他們樂捐的慷慨。","notes":[]},{"n":3,"t":"我可以證明，他們是按著能力，而且超過了能力來捐助，主動","notes":[]},{"n":4,"t":"再三懇求我們，准他們在這供給聖徒的善事上有份；","notes":[]},{"n":5,"t":"並且他們所做的，不但照我們所期望的，更照神的旨意先把自己獻給主，又給了我們。","notes":[]},{"n":6,"t":"因此，我們勸提多，既然在你們中間開始這慈善的事，就當把它辦成。","notes":[]},{"n":7,"t":"既然你們在信心、口才、知識、萬分的熱忱，以及我們對你們的愛心上，都勝人一等，那麼，當在這慈善的事上也要勝人一等。","notes":["有古卷是「你們對我們」。"]},{"n":8,"t":"我說這話，並不是命令你們，而是藉著別人的熱忱來考驗你們愛心的真誠。","notes":[]},{"n":9,"t":"你們知道我們主耶穌基督的恩典：他本是富足，卻為你們成了貧窮，好使你們因他的貧窮而成為富足。","notes":[]},{"n":10,"t":"我在這事上把我的意見告訴你們，是對你們有益，因為你們開始辦這事，而且起此心意已經有一年了。","notes":[]},{"n":11,"t":"如今就當辦成這事，既然有願做的心，也當照你們所有的去辦成。","notes":[]},{"n":12,"t":"因為人只要有願做的心，必照他所有的蒙悅納，並不是照他所沒有的。","notes":[]},{"n":13,"t":"我不是要別人輕鬆，你們受累，而是要均勻：","notes":[]},{"n":14,"t":"就是要你們現在的富餘補他們的不足，使他們的富餘將來也可以補你們的不足，這就均勻了。","notes":[]},{"n":15,"t":"如經上所記：多收的沒有餘，少收的也沒有缺。","notes":[]},{"n":16,"t":"感謝神，把我對你們的熱忱同樣放在提多心裏。","notes":[],"heads":["提多和他的同工"]},{"n":17,"t":"他固然聽了我的勸告，但自己更加熱心，自願往你們那裏去。","notes":[]},{"n":18,"t":"我們還差遣一位弟兄和他同去，這人在傳福音的事上得了眾教會的稱讚；","notes":[]},{"n":19,"t":"不但這樣，他也被眾教會選派跟我們同行，把所交託我們的這捐款送到了，為的是榮耀主，也表明我們的好意。","notes":[]},{"n":20,"t":"我們這樣做，免得有人因我們收的捐款多而挑剔我們。","notes":[]},{"n":21,"t":"我們留心做好事，不但在主面前，就是在人面前也是這樣。","notes":[]},{"n":22,"t":"我們又差遣一位弟兄同去。這人的熱忱，我們在許多事上屢次考驗過，現在他因為深深信任你們，就更加熱心了。","notes":[]},{"n":23,"t":"至於提多，他是我的夥伴，為服事你們作我的同工。至於那兩位弟兄，他們是眾教會的使者，是基督的榮耀。","notes":[]},{"n":24,"t":"所以，你們務要在眾教會面前向他們顯明你們的愛心和我所誇獎你們的憑據。","notes":[]}]},"9":{"heading":"幫助聖徒的捐款","verses":[{"n":1,"t":"關於供給聖徒的事，我本來不必寫信給你們；","notes":[]},{"n":2,"t":"因為我知道你們的好意，常對馬其頓人誇獎你們，說亞該亞人預備好已經有一年了。你們的熱心感動了許多人。","notes":[]},{"n":3,"t":"但我差遣那幾位弟兄去，要使你們照我的話預備妥當，免得我們在這事上誇獎你們的話落了空。","notes":[]},{"n":4,"t":"萬一有馬其頓人與我同去，見你們沒有預備好，就使我們所確信的反成了羞愧；你們的羞愧更不用說了。","notes":[]},{"n":5,"t":"因此，我想必須鼓勵那幾位弟兄先到你們那裏去，把從前所應許的捐款預備妥當，好顯出你們所捐的是出於樂意，不是出於勉強。","notes":[]},{"n":6,"t":"還有一點：「少種的少收；多種的多收。」","notes":[]},{"n":7,"t":"各人要隨心所願，不要為難，不要勉強，因為神愛樂捐的人。","notes":[]},{"n":8,"t":"神能將各樣的恩惠多多加給你們，使你們凡事常常充足，能多做各樣善事。","notes":[]},{"n":9,"t":"如經上所記：「他施捨，賙濟貧窮；他的義行存到永遠。」","notes":[]},{"n":10,"t":"那賜種子給撒種的，賜糧食給人吃的，必多多加給你們種地的種子，又增添你們仁義的果子。","notes":[]},{"n":11,"t":"你們必凡事富足，能多多施捨，使人藉著我們而生感謝神的心。","notes":[]},{"n":12,"t":"因為辦這供給的事，不但補聖徒的缺乏，而且使許多人對神充滿更多的感謝。","notes":[]},{"n":13,"t":"他們從這供給的事上得了憑據，知道你們宣認基督，順服他的福音，慷慨捐助給他們和眾人，把榮耀歸給神。","notes":[]},{"n":14,"t":"他們也因神極大的恩賜顯在你們身上而切切想念你們，為你們祈禱。","notes":[]},{"n":15,"t":"感謝神，因他有說不盡的恩賜！","notes":[]}]},"10":{"heading":"保羅為自己的工作辯護","verses":[{"n":1,"t":"我－保羅與你們見面的時候是溫和的，不在你們那裏的時候向你們是勇敢的，如今親自藉著基督的溫柔和慈祥勸你們。","notes":[]},{"n":2,"t":"有人認為我們是憑著血氣行事，我認為必須敢於對付這等人；我但求在那裏的時候，不必這樣勇敢。","notes":[]},{"n":3,"t":"我們雖然在血氣中行事，卻不憑著血氣爭戰。","notes":[]},{"n":4,"t":"因為我們爭戰的兵器本不是屬血氣的，而是憑著神的能力，能夠攻破堅固的營壘。我們攻破各樣的計謀，","notes":[]},{"n":5,"t":"和各樣攔阻人認識神的高壘，又奪回人心來順服基督。","notes":[]},{"n":6,"t":"我已經預備好了，等你們完全順服的時候來懲罰所有不順服的人。","notes":[]},{"n":7,"t":"你們只看事情的外表。倘若有人自信是屬基督的，他要再想想，他屬基督，我們也屬基督。","notes":[]},{"n":8,"t":"主賜給我們權柄，是要造就你們，並不是要拆毀你們；我就是為這權柄稍微誇口也不覺得慚愧。","notes":[]},{"n":9,"t":"我說這話，免得你們以為我寫信是要恐嚇你們。","notes":[]},{"n":10,"t":"因為有人說：「他信上的語氣既嚴厲又強硬，他本人卻軟弱無能，言語粗俗。」","notes":[]},{"n":11,"t":"這等人當明白，我們不在那裏時信上怎麼說，見面時也必怎麼做。","notes":[]},{"n":12,"t":"因為我們不敢將自己和某些自我推薦的人並列相比；他們用自己度量自己，用自己比較自己，是不明智的。","notes":[]},{"n":13,"t":"我們不願意過分誇口，但是我們只在神劃定的界限內誇口。這界限甚至擴展到你們那裏。","notes":[]},{"n":14,"t":"我們擴展到你們那裏時並沒有越過了自己的界限，其實我們是首先到你們那裏傳基督福音的。","notes":[]},{"n":15,"t":"我們不靠別人所勞碌的過分誇口；我們只希望你們信心增長的時候，所劃定給我們的範圍也能夠因著你們更加擴展，","notes":[]},{"n":16,"t":"使福音得以傳到你們以外的地方，而不在別人的範圍之內，以別人所成就的事誇口。","notes":[]},{"n":17,"t":"但「要誇耀的，該誇耀主」。","notes":[]},{"n":18,"t":"因為蒙悅納的，不是自我稱許的，而是主所稱許的。","notes":[]}]},"11":{"heading":"保羅和假使徒","verses":[{"n":1,"t":"但願你們容忍我小小的愚蠢；請你們務必容忍我。","notes":[]},{"n":2,"t":"我以神嫉妒的愛來愛你們，因為我曾把你們許配給一個丈夫，要把你們如同貞潔的童女獻給基督。","notes":[]},{"n":3,"t":"我只怕你們的心偏邪了，失去那向基督所獻誠懇貞潔的心，就像蛇用詭詐誘惑了夏娃一樣。","notes":["有古卷沒有「貞潔」。"]},{"n":4,"t":"假如有人來，傳另一個耶穌，不是我們所傳過的；或者你們另受一個靈，不是你們所受過的聖靈；或者接納另一個福音，不是你們所接納過的；你們居然容忍了！","notes":[]},{"n":5,"t":"但我想，我一點也不在那些超級使徒以下。","notes":[]},{"n":6,"t":"雖然我不擅長說話，我的知識卻不如此。這點我們已經在每一方面各樣事上向你們表明了。","notes":[]},{"n":7,"t":"我貶低自己，為了使你們高升，因為我白白地傳神的福音給你們，難道這算是我犯了錯嗎？","notes":[]},{"n":8,"t":"我剝奪了別的教會，向他們取了報酬來效勞你們。","notes":[]},{"n":9,"t":"我在你們那裏有缺乏的時候，並沒有連累你們一個人，因為我所缺乏的，那些從馬其頓來的弟兄都補足了。我向來凡事謹慎，將來也必謹慎，總不要連累你們。","notes":[]},{"n":10,"t":"既有基督的真誠在我裏面，在亞該亞一帶地方就沒有人能阻止我這樣自誇。","notes":[]},{"n":11,"t":"為甚麼呢？是因我不愛你們嗎？神知道，我愛你們！","notes":[]},{"n":12,"t":"我現在所做的，將來還要做，為要斷絕那些尋機會之人的機會，不讓他們在所誇耀的事上被人認為與我們一樣。","notes":[]},{"n":13,"t":"那樣的人是假使徒，行事詭詐，裝作基督的使徒。","notes":[]},{"n":14,"t":"這也不足為奇，因為連撒但也裝作光明的天使。","notes":[]},{"n":15,"t":"所以，他的差役若裝作公義的差役也沒有甚麼大不了。他們的結局必然跟他們的行為相符。","notes":[]},{"n":16,"t":"我再說，誰都不可把我看作愚蠢的；即使你們把我當作愚蠢人，那麼，也讓我稍微誇誇口吧。","notes":[],"heads":["保羅所受的患難"]},{"n":17,"t":"我說的話不是奉主的權柄說的，而是像愚蠢人具有自信地放膽誇口。","notes":[]},{"n":18,"t":"既然有好些人憑著血氣在誇口，我也要誇口了。","notes":[]},{"n":19,"t":"你們是聰明人，竟能甘心容忍愚蠢人！","notes":[]},{"n":20,"t":"假若有人奴役你們，或侵吞你們，或壓榨你們，或侮辱你們，或打你們的臉，你們居然都能容忍。","notes":[]},{"n":21,"t":"說來慚愧，在這方面好像我們是太軟弱了。然而，我說句蠢話，人在甚麼事上敢誇口，我也敢誇口。","notes":[]},{"n":22,"t":"他們是希伯來人嗎？我也是。他們是以色列人嗎？我也是。他們是亞伯拉罕的後裔嗎？我也是。","notes":[]},{"n":23,"t":"他們是基督的用人嗎？我說句狂話，我更是。我比他們忍受更多勞苦，坐過更多次監牢，受過無數次的鞭打，常常冒死。","notes":[]},{"n":24,"t":"我被猶太人鞭打五次，每次四十減去一下；","notes":[]},{"n":25,"t":"被棍打了三次，被石頭打了一次，遭海難三次，一晝一夜在深海裏掙扎。","notes":[]},{"n":26,"t":"我又屢次行遠路，遭江河的危險，盜賊的危險，同族人的危險，外族人的危險，城裏的危險，曠野的危險，海中的危險，假弟兄的危險。","notes":[]},{"n":27,"t":"我勞碌困苦，常常失眠，又飢又渴，忍飢耐寒，赤身露體。","notes":[]},{"n":28,"t":"除了這些外表的事以外，我還有為眾教會操心的事天天壓在我身上。","notes":[]},{"n":29,"t":"有誰軟弱，我不軟弱呢？有誰跌倒，我不焦急呢？","notes":[]},{"n":30,"t":"我若必須誇口，就誇我軟弱的事好了。","notes":[]},{"n":31,"t":"那永遠可稱頌之主耶穌的父神知道我不說謊。","notes":[]},{"n":32,"t":"在大馬士革的亞哩達王手下的提督把守大馬士革城，要捉拿我，","notes":[]},{"n":33,"t":"我被人用筐子從城牆上的窗口縋下，逃脫了他的手。","notes":[]}]},"12":{"heading":"異象和啟示","verses":[{"n":1,"t":"雖然自誇無益，我還是不得不誇。我現在要提到主的異象和啟示。","notes":[]},{"n":2,"t":"我認識一個在基督裏的人，他在十四年前被提到第三層天上去；或在身內，我不知道，或在身外，我也不知道，只有神知道。","notes":[]},{"n":3,"t":"我認識的這樣的一個人—或在身內，或在身外，我都不知道，只有神知道—","notes":[]},{"n":4,"t":"他被提到樂園裏，聽見隱祕的言語，是人不可說的。","notes":[]},{"n":5,"t":"為這人，我要誇口；但是為我自己，除了我的軟弱以外，我並不誇口。","notes":[]},{"n":6,"t":"就是我願意誇口也不算狂，因為我會說實話；只是我絕口不談，恐怕有人把我看得太高了，過於他在我身上所看見所聽見的；","notes":[]},{"n":7,"t":"又恐怕我因所得的啟示太高深，就過於高抬自己，所以有一根刺加在我身上，就是撒但的差役來折磨我，免得我過於高抬自己。","notes":["有古卷沒有「所以」。"]},{"n":8,"t":"為了這事，我曾三次求主使這根刺離開我。","notes":[]},{"n":9,"t":"他對我說：「我的恩典是夠你用的，因為我的能力是在人的軟弱上顯得完全。」所以，我更喜歡誇耀自己的軟弱，好使基督的能力覆庇我。","notes":[]},{"n":10,"t":"為基督的緣故，我以軟弱、凌辱、艱難、迫害、困苦為可喜樂的事；因為我甚麼時候軟弱，甚麼時候就剛強了。","notes":[]},{"n":11,"t":"我成了愚蠢人，是被你們逼出來的，因為我本該被你們讚許才是。雖然我算不了甚麼，卻沒有一件事在那些超級使徒以下。","notes":[],"heads":["保羅關心哥林多教會"]},{"n":12,"t":"我在你們中間，用百般的忍耐，藉著神蹟、奇事、異能顯出使徒的憑據來。","notes":[]},{"n":13,"t":"除了我不曾連累你們這一件事，你們還有甚麼事不及別的教會呢？這不公平之處，請你們饒恕我吧。","notes":[]},{"n":14,"t":"如今，我準備第三次到你們那裏去。我仍不會連累你們，因為我所求的是你們，不是你們的財物。兒女不該為父母積財，父母該為兒女積財。","notes":[]},{"n":15,"t":"我也甘心樂意為你們的靈魂費財費力。難道我越愛你們，就越少得你們的愛嗎？","notes":[]},{"n":16,"t":"罷了，我自己並沒有連累你們，你們卻有人說，我施詭詐，用心計牢籠你們。","notes":[]},{"n":17,"t":"我所差遣到你們那裏去的人，我何曾藉著他們中的任何人佔過你們的便宜呢？","notes":[]},{"n":18,"t":"我勸提多到你們那裏去，又差遣那位弟兄與他同去，提多佔過你們的便宜嗎？我們的行事為人不是同一心靈嗎？不是同一步伐嗎？","notes":["「心靈」或譯「聖靈」。"]},{"n":19,"t":"你們一直認為我們是在你們面前為自己辯護嗎？其實，我們本是在基督裏當著神面前說話。親愛的，一切的事都是為了造就你們。","notes":[]},{"n":20,"t":"我怕我再來的時候，見你們不合我所期望的，而你們見我也不合你們所期望的。我怕有紛爭、嫉妒、憤怒、自私、毀謗、讒言、狂傲、動亂的事。","notes":[]},{"n":21,"t":"我怕我再來的時候，我的神使我在你們面前蒙羞，並且又因許多人從前犯罪，行污穢、淫亂、放蕩的事，不肯悔改而悲傷。","notes":[]}]},"13":{"heading":"警告和問候","verses":[{"n":1,"t":"這是我第三次要到你們那裏去。「任何指控都要憑兩個或三個證人的口述才能成立。」","notes":[]},{"n":2,"t":"對那些犯了罪的人和其餘所有的人，正如我第二次見你們的時候曾說過，現在不在你們那裏再次說：「我若再來，必不寬容。」","notes":[]},{"n":3,"t":"因為你們想求證基督是否藉著我說話。基督對你們並不是軟弱的，而是在你們裏面大有能力的。","notes":[]},{"n":4,"t":"他因軟弱被釘在十字架上，卻因神的大能仍然活著。我們在他裏面也成為軟弱的，但對你們，我們將因神的大能而與他一同活著。","notes":[]},{"n":5,"t":"你們總要省察自己是否在信仰中生活；你們要考驗自己。除非你們經不起考驗，你們自己豈不應該知道有耶穌基督在你們裏面嗎？","notes":[]},{"n":6,"t":"我希望你們知道，我們並不是經不起考驗的人。","notes":[]},{"n":7,"t":"我們祈求神使你們不做任何惡事；這不是要顯明我們是經得起考驗的，而是要你們行事端正，即使我們似乎經不起考驗也沒有關係。","notes":[]},{"n":8,"t":"我們不能做任何對抗真理的事，只能維護真理。","notes":[]},{"n":9,"t":"當我們軟弱而你們剛強時，我們也歡喜。我們所祈求的是：你們能成為完全人。","notes":[]},{"n":10,"t":"所以，我不在你們那裏的時候，把這些話寫給你們，好使我見你們的時候不用照主所給我的權柄嚴厲地待你們；這權柄原是為造就人，而不是為摧毀人。","notes":[]},{"n":11,"t":"末了，弟兄們，願你們喜樂。要追求完全；要接受鼓勵；要同心合意；要彼此和睦。如此，慈愛和平的神必與你們同在。","notes":[]},{"n":12,"t":"你們要用聖潔的吻彼此問安。眾聖徒都向你們問安。","notes":[]},{"n":13,"t":"願主耶穌基督的恩惠、神的慈愛、聖靈的感動常與你們眾人同在！","notes":[]}]}},"GAL":{"1":{"heading":"問候","verses":[{"n":1,"t":"我使徒保羅和所有跟我一起的弟兄，寫信給加拉太的眾教會。我作使徒不是由於人，也不是藉著人，而是藉著耶穌基督與使他從死人中復活的父神。","notes":[],"end":2},{"n":3,"t":"願恩惠、平安從我們的父神和主耶穌基督歸給你們！","notes":["「平安」或譯「和平」。"]},{"n":4,"t":"基督照我們父神的旨意，為我們的罪捨己，要救我們脫離現今這罪惡的世代。","notes":[]},{"n":5,"t":"願榮耀歸給神，直到永永遠遠。阿們！","notes":[]},{"n":6,"t":"我很驚訝你們這麼快就離開那位藉著基督之恩呼召你們的神，而去隨從別的福音；","notes":["有古卷沒有「基督之」；另有古卷是「耶穌基督之」。"],"heads":["沒有別的福音"]},{"n":7,"t":"其實並沒有另一個福音，不過有些人騷擾你們，要把基督的福音更改了。","notes":[]},{"n":8,"t":"但無論是我們或是天上來的使者，若傳福音給你們，與我們所傳給你們的不同，他該受詛咒！","notes":["有古卷沒有「給你們」。"]},{"n":9,"t":"我們已經說了，現在我再說，若有人傳福音給你們，與你們以往所領受的不同，他該受詛咒！","notes":[]},{"n":10,"t":"我現在是要得人的心，還是要得神的心呢？難道我在討人的喜歡嗎？我若仍舊想討人的喜歡，我就不是基督的僕人了。","notes":[]},{"n":11,"t":"弟兄們，我要你們知道，我所傳的福音不是按照人的意思；","notes":[],"heads":["保羅怎樣成為使徒"]},{"n":12,"t":"因為我不是從人領受的，也不是人教導我的，而是藉著耶穌基督的啟示而來。","notes":[]},{"n":13,"t":"你們聽說過從前我在猶太教中的行徑，我怎樣竭力壓迫殘害神的教會。","notes":[]},{"n":14,"t":"在猶太教中，我比本國許多同輩的人更激進，為我祖宗的傳統更熱心。","notes":[]},{"n":15,"t":"然而，那位把我從母腹裏分別出來、又施恩呼召我的神，既然樂意","notes":["有古卷沒有「神」。"]},{"n":16,"t":"把他兒子啟示在我心裏，讓我在外邦人中傳揚他，我就沒有跟有血有肉的人商量，","notes":[]},{"n":17,"t":"也沒有上耶路撒冷去見那些比我先作使徒的，惟獨到阿拉伯去，後來又回到大馬士革。","notes":[]},{"n":18,"t":"過了三年，我才上耶路撒冷去見磯法，和他同住了十五天。","notes":[]},{"n":19,"t":"至於別的使徒，除了主的兄弟雅各，我都沒有見過。","notes":[]},{"n":20,"t":"我現在寫給你們的是在神面前說的，不說謊話。","notes":[]},{"n":21,"t":"以後我到了敘利亞和基利家一帶；","notes":[]},{"n":22,"t":"那時，在基督裏的猶太各教會都沒有見過我的面。","notes":[]},{"n":23,"t":"不過他們聽說「那從前壓迫我們的，現在竟傳揚他原先所殘害的信仰」。","notes":[]},{"n":24,"t":"他們就為我的緣故歸榮耀給神。","notes":[]}]},"2":{"heading":"保羅被其他使徒接納","verses":[{"n":1,"t":"過了十四年，我再上耶路撒冷去，巴拿巴同行，也帶了提多一起去。","notes":[]},{"n":2,"t":"我是奉了啟示上去的；我把在外邦人中所傳的福音對弟兄們說明，我是私下對那些有名望的人說的，免得我現在或是從前都徒然奔跑了。","notes":[]},{"n":3,"t":"但跟我同去的提多，雖是希臘人，也沒有勉強他受割禮；","notes":[]},{"n":4,"t":"因為有偷著混進來的假弟兄，暗中窺探我們在基督耶穌裏擁有的自由，要使我們作奴隸，","notes":[]},{"n":5,"t":"可是，為要使福音的真理仍存在你們中間，我們一點也沒有讓步順服他們。","notes":[]},{"n":6,"t":"至於那些有名望的，不論他們是何等人，都與我無關；神不以外貌取人。那些有名望的，並沒有加增我甚麼。","notes":[]},{"n":7,"t":"相反地，他們看見了主託付我傳福音給未受割禮的人，正如主託付彼得傳福音給受割禮的人；","notes":[]},{"n":8,"t":"那感動彼得、叫他為受割禮的人作使徒的，也感動我，叫我為外邦人作使徒。","notes":[]},{"n":9,"t":"那些被認為是教會柱石的雅各、磯法、約翰知道神所賜給我的恩典，就跟我和巴拿巴握右手以示合作，同意我們往外邦人那裏去，他們往受割禮的人那裏去。","notes":[]},{"n":10,"t":"他們只要求我們記念窮人，這也是我一向熱心在做的。","notes":[]},{"n":11,"t":"後來，磯法到了安提阿，因為他有可責之處，我就當面反對他。","notes":[],"heads":["保羅責備彼得"]},{"n":12,"t":"從雅各那裏來的人未到以前，他和外邦人一同吃飯，及至他們來到，他因怕奉割禮的人就退出，跟外邦人疏遠了。","notes":[]},{"n":13,"t":"其餘的猶太人也都隨著他裝假，甚至連巴拿巴也隨夥裝假。","notes":[]},{"n":14,"t":"但我一看見他們做得不對，與福音的真理不合，就在眾人面前對磯法說：「你既是猶太人，卻按照外邦人的樣子，不按照猶太人的樣子生活，怎麼能勉強外邦人按照猶太人的樣子生活呢？」","notes":[]},{"n":15,"t":"我們生來就是猶太人，不是外邦罪人；","notes":[],"heads":["猶太人也像外邦人因信得救"]},{"n":16,"t":"可是我們知道，人稱義不是因律法的行為，而是因信耶穌基督，我們也信了基督耶穌，為要使我們因信基督稱義，不因律法的行為稱義，因為，凡血肉之軀沒有一個能因律法的行為稱義。","notes":["「因信耶穌基督」或譯「藉耶穌基督的信」。"]},{"n":17,"t":"我們若求在基督裏稱義，自己卻還被視為罪人，那麼，基督是罪的用人嗎？絕對不是！","notes":[]},{"n":18,"t":"如果我重新建造我所拆毀的，這就證明自己是違犯律法的人。","notes":[]},{"n":19,"t":"我因律法而向律法死了，使我可以向神活著。我已經與基督同釘十字架，","notes":[]},{"n":20,"t":"現在活著的不再是我，乃是基督在我裏面活著；並且我如今在肉身活著，是因信神的兒子而活；他是愛我，為我捨己。","notes":[]},{"n":21,"t":"我不廢掉神的恩；如果義是藉著律法而獲得，那麼基督就白白死了。","notes":[]}]},"3":{"heading":"律法或信心","verses":[{"n":1,"t":"無知的加拉太人哪，耶穌基督釘十字架，已經活現在你們眼前，誰又迷惑了你們呢？","notes":[]},{"n":2,"t":"這是我惟一要問你們的：你們領受了聖靈，是因律法的行為或是因聽信福音呢？","notes":[]},{"n":3,"t":"你們既然以聖靈開始，如今竟要以肉身終結嗎？你們是這樣的無知嗎？","notes":[]},{"n":4,"t":"你們受這麼多的苦都是徒然的嗎？如果真是徒然的，","notes":[]},{"n":5,"t":"那麼，神賜給你們聖靈，又在你們中間行異能，是因律法的行為或是因聽信福音呢？","notes":[]},{"n":6,"t":"正如亞伯拉罕「信了神，這就算他為義」。","notes":[]},{"n":7,"t":"所以，你們知道：有信心的人才是亞伯拉罕的子孫。","notes":[]},{"n":8,"t":"聖經既然預先看見神要使外邦人因信稱義，預先傳福音給亞伯拉罕，說：「萬國都必因你得福。」","notes":[]},{"n":9,"t":"可見，那有信心的人和有信心的亞伯拉罕一同得福。","notes":[]},{"n":10,"t":"凡出於律法的行為都是受詛咒的，因為經上記著：「凡不持守律法書上所記的一切而去行的，都是受詛咒的。」","notes":[]},{"n":11,"t":"沒有一個人靠著律法在神面前稱義，這是明顯的，因為經上說：「義人必因信得生。」","notes":[]},{"n":12,"t":"律法並不出於信，而是說：「行這些事的就必因此得生。」","notes":[]},{"n":13,"t":"既然基督為我們成了詛咒，就把我們從律法的詛咒中贖出來。因為經上記著：「凡掛在木頭上的都是受詛咒的。」","notes":[]},{"n":14,"t":"這是要使亞伯拉罕的福，因著基督耶穌臨到外邦人，使我們能因信得著所應許的聖靈。","notes":[]},{"n":15,"t":"弟兄們，我照著人的觀點說，人的遺囑一經確定，沒有人能廢棄或加增。","notes":[],"heads":["律法和應許"]},{"n":16,"t":"那些應許原是向亞伯拉罕和他後裔說的，並不是說「和眾後裔」，指許多人，而是說「和你那個後裔」，指一個人，就是基督。","notes":[]},{"n":17,"t":"我是這麼說，神預先所立的約不能被四百三十年以後的律法廢掉，使應許失效。","notes":[]},{"n":18,"t":"因為承受產業若是出於律法，就不再是出於應許；但神是憑著應許把產業賜給亞伯拉罕。","notes":[]},{"n":19,"t":"這樣說來，為甚麼要有律法呢？律法是為過犯的緣故而加上去的，等候那蒙應許的子孫來到才結束，是藉著天使經中保之手而設立的。","notes":[]},{"n":20,"t":"但中保本不是為單方設立的；神卻是一位。","notes":[]},{"n":21,"t":"這樣，律法是與神的應許對立嗎？絕對不是！如果律法的頒佈能使人得生命，義就誠然出於律法了。","notes":["有古卷沒有「神的」；另有古卷是「基督的」。"],"heads":["奴隸和兒子"]},{"n":22,"t":"但聖經把萬物都圈在罪裏，為要使因信耶穌基督而來的應許歸給信的人。","notes":["「因信耶穌基督」或譯「藉耶穌基督的信」。"]},{"n":23,"t":"但這「信」還未來以前，我們被看守在律法之下，像被圈住，直到那將來的「信」顯明出來。","notes":[]},{"n":24,"t":"這樣，律法是我們的啟蒙教師，直到基督來了，好使我們因信稱義。","notes":["「直到基督來了」或譯「引我們到基督那裏」。"]},{"n":25,"t":"但這「信」既然來到，我們從此就不在啟蒙教師的手下了。","notes":[]},{"n":26,"t":"其實，你們藉著信，在基督耶穌裏都成為神的兒女。","notes":[]},{"n":27,"t":"你們凡受洗歸入基督的都披戴基督了：","notes":[]},{"n":28,"t":"不再分猶太人或希臘人，不再分為奴的自主的，不再分男的女的，因為你們在基督耶穌裏都成為一了。","notes":[]},{"n":29,"t":"既然你們屬於基督，你們就是亞伯拉罕的子孫，是照著應許承受產業的了。","notes":[]}]},"4":{"heading":"保羅關懷加拉太人","verses":[{"n":1,"t":"我說，雖然那承受產業的是整個產業的主人，但在未成年的時候卻與奴隸毫無分別，","notes":[]},{"n":2,"t":"仍是在監護人和管家的手下，直等他父親預定的時候來到。","notes":[]},{"n":3,"t":"我們也是一樣，在未成年的時候，被世上粗淺的學說所奴役，也是如此。","notes":["「世上粗淺的學說」或譯「宇宙的星宿」。"]},{"n":4,"t":"等到時候成熟，神就差遣他的兒子，為女子所生，且生在律法之下，","notes":[]},{"n":5,"t":"為要把律法之下的人贖出來，使我們獲得兒子的名分。","notes":[]},{"n":6,"t":"因為你們是兒子，神就差他兒子的靈進入我們的心，呼叫：「阿爸，父！」","notes":["「我們」：有古卷是「你們」。"]},{"n":7,"t":"可見，你不再是奴隸，而是兒子了，既然是兒子，就靠著神也成為後嗣了。","notes":[]},{"n":8,"t":"但從前不認識神的時候，你們是給那些本來不是神的神明作奴隸；","notes":[]},{"n":9,"t":"現在你們既然認識神，更可說是被神所認識的，怎麼還要轉回那懦弱無用的粗淺學說，情願再給它們作奴隸呢？","notes":["「粗淺學說」或譯「星宿之學」。"]},{"n":10,"t":"你們竟又謹守日子、月份、節期、年份，","notes":[]},{"n":11,"t":"我為你們擔心，惟恐我在你們身上是枉費工夫了。","notes":[]},{"n":12,"t":"弟兄們，我勸你們，要像我一樣，因為我也像你們一樣。你們一點沒有虧負我。","notes":[]},{"n":13,"t":"你們知道，我因為身體有疾病才有第一次傳福音給你們的機會。","notes":[]},{"n":14,"t":"雖然你們為我身體的緣故受試煉，卻沒有輕看我，也沒有厭棄我，反倒接待我如同神的使者，如同基督耶穌。","notes":[]},{"n":15,"t":"你們當日的好意哪裏去了呢？那時若辦得到，你們就是把自己的眼睛挖出來給我，也都情願。這是我可以給你們作證的。","notes":[]},{"n":16,"t":"如今我把真理告訴你們，倒成了你們的仇敵嗎？","notes":[]},{"n":17,"t":"那些熱心待你們的人，不懷好意，是要隔絕你們，好使你們熱心待他們。","notes":[]},{"n":18,"t":"在善事上，時刻熱心待別人原是好的，卻不只是我與你們同在的時候才這樣。","notes":[]},{"n":19,"t":"我的孩子們哪，我為你們再受生產之苦，直等到基督成形在你們心裏。","notes":["「成形在你們心裏」或譯「在你們當中成形」。"]},{"n":20,"t":"我期望現今就在你們那裏，可以改變我的口氣，因為我為你們心裏難過。","notes":[]},{"n":21,"t":"你們這願意在律法之下的人，請告訴我，你們沒有聽見律法嗎？","notes":[],"heads":["夏甲和撒拉的例子"]},{"n":22,"t":"因為律法上記著，亞伯拉罕有兩個兒子，一個是使女生的，一個是自由的婦人生的。","notes":[]},{"n":23,"t":"那使女所生的是按著肉體生的；那自由的婦人所生的是憑著應許生的。","notes":[]},{"n":24,"t":"這是比方：那兩個婦人就是兩個約；一個婦人是出於西奈山，生子為奴，就是夏甲。","notes":[]},{"n":25,"t":"這夏甲是指著阿拉伯的西奈山，與現在的耶路撒冷同類，因為耶路撒冷和她的兒女都是為奴的。","notes":["有古卷是「因為西奈山是指著阿拉伯的一座山」。"]},{"n":26,"t":"但另一婦人就是在上的耶路撒冷，是自由的，她是我們的母親。","notes":[]},{"n":27,"t":"因為經上記著：「不懷孕、不生養的，你要歡樂；未曾經過產難的，你要高聲歡呼；因為沒有丈夫的，比有丈夫的有更多的兒女。」","notes":[]},{"n":28,"t":"弟兄們，你們是憑著應許作兒女的，如同以撒一樣。","notes":[]},{"n":29,"t":"當時，那按著肉體生的迫害了那按著聖靈生的，現在也是這樣。","notes":[]},{"n":30,"t":"然而經上是怎麼說的呢？是說：「把使女和她兒子趕出去！因為使女的兒子絕不能與自由婦人的兒子一同承受產業。」","notes":[]},{"n":31,"t":"弟兄們，這樣看來，我們不是使女的兒女，而是自由婦人的兒女了。","notes":[]}]},"5":{"heading":"基督徒的自由","verses":[{"n":1,"t":"基督釋放了我們，為使我們得自由。所以要站穩了，不要再被奴隸的軛挾制。","notes":[]},{"n":2,"t":"我—保羅告訴你們，你們若受割禮，基督就對你們無益了。","notes":[]},{"n":3,"t":"我再指著凡受割禮的人確實地說，他有義務遵行全部的律法。","notes":[]},{"n":4,"t":"你們這要靠律法稱義的是與基督隔絕，從恩典中墜落了。","notes":[]},{"n":5,"t":"至於我們，我們是靠著聖靈，憑著信心，等候所盼望的義。","notes":[]},{"n":6,"t":"因為在基督耶穌裏，受割禮不受割禮都沒有功效，惟獨使人發出仁愛的信心才有功效。","notes":[]},{"n":7,"t":"你們向來跑得好，誰攔阻了你們，使你們不順從真理呢？","notes":[]},{"n":8,"t":"這樣的勸導不是出於那召你們的。","notes":[]},{"n":9,"t":"一點麵酵能使全團都發起來。","notes":[]},{"n":10,"t":"我在主裏深信你們必不懷別樣的心；但騷擾你們的，無論是誰，必須承受懲罰。","notes":[]},{"n":11,"t":"弟兄們，我若仍舊傳割禮，為甚麼還受迫害呢？若是這樣，十字架絆倒人的地方就沒有了。","notes":[]},{"n":12,"t":"恨不得那騷擾你們的人把自己閹割了。","notes":[]},{"n":13,"t":"弟兄們，你們蒙召是要得自由；只是不可把這自由當作放縱情慾的機會，總要用愛心互相服侍。","notes":[]},{"n":14,"t":"因為全部律法都包括在「愛鄰如己」這一句話之內了。","notes":["「鄰」也可譯作「人」。"]},{"n":15,"t":"你們要謹慎，你們若相咬相吞，恐怕要彼此消滅了。","notes":[]},{"n":16,"t":"我說，你們要順著聖靈而行，絕不可滿足肉體的情慾。","notes":[],"heads":["聖靈的果子和肉體的惡行"]},{"n":17,"t":"因為肉體的情慾和聖靈相爭，聖靈和肉體相爭，這兩個彼此敵對，使你們不能做所願意做的。","notes":[]},{"n":18,"t":"但你們若被聖靈引導，就不在律法之下。","notes":[]},{"n":19,"t":"情慾的事都是顯而易見的；就如淫亂、污穢、放蕩、","notes":[]},{"n":20,"t":"拜偶像、行邪術、仇恨、紛爭、忌恨、憤怒、自私、分派、結黨、","notes":[]},{"n":21,"t":"嫉妒、醉酒、荒宴等類。我從前告訴過你們，現在又告訴你們，做這樣事的人必不能承受神的國。","notes":["有古卷在此加「兇殺」。"]},{"n":22,"t":"聖靈的果子就是仁愛、喜樂、和平、忍耐、恩慈、良善、信實、","notes":[]},{"n":23,"t":"溫柔、節制。這樣的事沒有律法禁止。","notes":[]},{"n":24,"t":"凡屬基督耶穌的人，是已經把肉體與肉體的邪情私慾同釘在十字架上了。","notes":["「基督耶穌」：有古卷是「基督」。"]},{"n":25,"t":"我們若靠著聖靈而活，也要靠著聖靈行事。","notes":[]},{"n":26,"t":"不要貪圖虛名，彼此惹氣，互相嫉妒。","notes":[]}]},"6":{"heading":"各人的重擔要互相擔當","verses":[{"n":1,"t":"弟兄們，若有人偶然被過犯所勝，你們屬靈的人就要用溫柔的心把他挽回過來；自己也要留意，免得也被引誘。","notes":[]},{"n":2,"t":"你們各人的重擔要互相擔當，這樣就會成全基督的律法。","notes":["有古卷是「要這樣成全」。"]},{"n":3,"t":"人若沒有甚麼了不起，還自以為了不起的，就是自欺。","notes":[]},{"n":4,"t":"各人要省察自己的行為；這樣，他所誇口的只在自己，而不在別人。","notes":[]},{"n":5,"t":"因為人人必須擔當自己的擔子。","notes":[]},{"n":6,"t":"在真道上受教的，要把一切美好的東西與施教的人分享。","notes":[]},{"n":7,"t":"不要自欺；神是輕慢不得的，因為人種的是甚麼，收的也是甚麼。","notes":[]},{"n":8,"t":"順著肉體撒種的，必從肉體收敗壞；順著聖靈撒種的，必從聖靈收永生。","notes":[]},{"n":9,"t":"我們行善不可喪志，因為若不灰心，到了適當的時候就有收成。","notes":[]},{"n":10,"t":"所以，一有機會就要向眾人行善，向信徒一家的人更要這樣。","notes":[]},{"n":11,"t":"你們看我親手寫給你們的字是何等的大！","notes":[],"heads":["警告和祝福"]},{"n":12,"t":"那些想要炫耀外表的人才勉強你們受割禮，無非是怕自己為基督的十字架受迫害。","notes":[]},{"n":13,"t":"他們那些受割禮的，連自己也不守律法；他們要你們受割禮，不過是要拿你們的肉體誇口。","notes":[]},{"n":14,"t":"但我絕不以別的誇口，只誇我們主耶穌基督的十字架；因這十字架，就我而論，世界已經釘在十字架上；就世界而論，我已經釘在十字架上。","notes":["「因這十字架」或譯「藉著他（基督）」。"]},{"n":15,"t":"受割禮或不受割禮都無關緊要，要緊的就是作新造的人。","notes":[]},{"n":16,"t":"凡照這準則行的人，願平安憐憫加給他們，和神的以色列民。","notes":["「平安」或譯「和平」。"]},{"n":17,"t":"從今以後，不要有人再攪擾我，因為我身上帶著耶穌的印記。","notes":[]},{"n":18,"t":"弟兄們，願我們主耶穌基督的恩與你們的靈同在。阿們！","notes":[]}]}},"EPH":{"1":{"heading":"問候","verses":[{"n":1,"t":"奉神旨意作基督耶穌使徒的保羅，寫信給在以弗所的眾聖徒，就是在基督耶穌裏忠心的人。","notes":["有古卷沒有「在以弗所的」。"]},{"n":2,"t":"願恩惠、平安從我們的父神和主耶穌基督歸給你們！","notes":["「平安」或譯「和平」。"]},{"n":3,"t":"願頌讚歸給我們主耶穌基督的父神。他在基督裏曾把天上各樣屬靈的福氣賜給我們。","notes":[],"heads":["基督裏的屬靈福氣"]},{"n":4,"t":"因為他從創世以前，在基督裏揀選了我們，使我們在他面前成為聖潔，沒有瑕疵，滿有愛心。","notes":[]},{"n":5,"t":"他按著自己旨意所喜悅的，預定我們藉著耶穌基督得兒子的名分，","notes":["「沒有瑕疵...喜悅的」：原文或譯「沒有瑕疵。在愛中，他按著自己旨意所喜悅的」。"]},{"n":6,"t":"使他榮耀的恩典得到稱讚；這恩典是他在愛子裏白白賜給我們的。","notes":[]},{"n":7,"t":"我們藉著這愛子的血得蒙救贖，過犯得以赦免，這是照他豐富的恩典，","notes":[]},{"n":8,"t":"充充足足地賞給我們的。他以諸般的智慧聰明，","notes":[]},{"n":9,"t":"照自己在基督裏所立定的美意，使我們知道他旨意的奧祕，","notes":[]},{"n":10,"t":"要照著所安排的，在時機成熟的時候，使天上、地上、一切所有的，都在基督裏面同歸於一。","notes":[]},{"n":11,"t":"我們也在他裏面得了基業；這原是那位隨己意行萬事的神照著自己的旨意所預定的，","notes":[]},{"n":12,"t":"為要使我們，這些首先把希望寄託在基督裏的人，頌讚他的榮耀。","notes":[]},{"n":13,"t":"在基督裏你們聽見真理的道，就是那使你們得救的福音，你們也信了他，就受了所應許的聖靈為印記。","notes":[]},{"n":14,"t":"這聖靈是我們得基業的憑據，直等到神的子民得救贖，使他的榮耀得到稱讚。","notes":[]},{"n":15,"t":"因此，我既然聽見你們對主耶穌有信心，對眾聖徒有愛心，","notes":[],"heads":["保羅的禱告"]},{"n":16,"t":"就不住地為你們感謝神，禱告的時候常常提到你們，","notes":[]},{"n":17,"t":"求我們主耶穌基督的神，榮耀的父，把那賜人智慧和啟示的靈賜給你們，使你們真正認識他，","notes":[]},{"n":18,"t":"照亮你們心中的眼睛，使你們知道他呼召你們來得的指望是甚麼，他在聖徒中所得榮耀的基業是何等豐盛，","notes":[]},{"n":19,"t":"並知道他向我們這些信的人所顯的能力是何等浩大，這是照他的大能大力運行的。","notes":[]},{"n":20,"t":"這大能曾運行在基督身上，使他從死人中復活，又使他在天上坐在自己的右邊，","notes":[]},{"n":21,"t":"遠超越一切執政的、掌權的、有權能的、統治的和一切有名號的；不但是今世的，連來世的也都超越了。","notes":[]},{"n":22,"t":"神使萬有服在他的腳下，又使他為了教會作萬有之首；","notes":[]},{"n":23,"t":"教會是他的身體，是那充滿萬有者所充滿的。","notes":[]}]},"2":{"heading":"出死入生","verses":[{"n":1,"t":"從前，你們因著自己的過犯罪惡而死了。","notes":[]},{"n":2,"t":"那時，你們在過犯罪惡中生活，隨從今世的風俗，順服空中掌權者的領袖，就是現今在悖逆的人心中運行的邪靈。","notes":[]},{"n":3,"t":"我們從前也都生活在他們當中，放縱肉體的私慾，隨著肉體和心中的意念去做，和別人一樣，生來就是該受懲罰的人。","notes":[]},{"n":4,"t":"然而，神有豐富的憐憫，因著他愛我們的大愛，","notes":[]},{"n":5,"t":"竟在我們因過犯而死了的時候，使我們與基督一同活過來—可見你們得救是本乎恩—","notes":[]},{"n":6,"t":"他又使我們在基督耶穌裏與他一同復活，一同坐在天上，","notes":[]},{"n":7,"t":"為要把他極豐富的恩典，就是他在基督耶穌裏向我們所施的恩慈，顯明給後來的世代。","notes":[]},{"n":8,"t":"你們得救是本乎恩，也因著信；這並不是出於自己，而是神所賜的；","notes":[]},{"n":9,"t":"也不是出於行為，免得有人自誇。","notes":[]},{"n":10,"t":"我們是他所造之物，在基督耶穌裏創造的，為要使我們行善，就是神早已預備好要我們做的。","notes":[]},{"n":11,"t":"所以，你們要記得：從前你們按肉體是外邦人，是「沒受割禮的」；這名字是那些憑人手在肉身上「受割禮的人」所取的。","notes":[],"heads":["在基督裏合而為一"]},{"n":12,"t":"要記得那時候，你們與基督無關，與以色列選民團體隔絕，在所應許的約上是局外人，而且在世上沒有指望，沒有神。","notes":[]},{"n":13,"t":"從前你們是遠離神的人，如今卻在基督耶穌裏，靠著他的血，已經得以親近了。","notes":[]},{"n":14,"t":"因為他自己是我們的和平，使雙方合而為一，拆毀了中間隔絕的牆，而且以自己的身體終止了冤仇，","notes":["「因為…和平」或譯「因為他使我們和睦」。"]},{"n":15,"t":"廢掉那記在律法上的規條，為要使兩方藉著自己造成一個新人，促成了和平；","notes":[]},{"n":16,"t":"既在十字架上消滅了冤仇，就藉這十字架使雙方歸為一體，與神和好，","notes":[]},{"n":17,"t":"並且來傳和平的福音給你們遠處的人，也傳和平給那些近處的人，","notes":[]},{"n":18,"t":"因為我們雙方藉著他，在同一位聖靈裏得以進到父面前。","notes":[]},{"n":19,"t":"這樣，你們不再是外人或客旅，是與聖徒同國，是神家裏的人了，","notes":[]},{"n":20,"t":"被建造在使徒和先知的根基上，而基督耶穌自己為房角石，","notes":[]},{"n":21,"t":"靠著他整座房子連接得緊湊，漸漸成為在主裏的聖殿。","notes":[]},{"n":22,"t":"你們也靠他同被建造，成為神藉著聖靈居住的所在。","notes":[]}]},"3":{"heading":"保羅向外邦人傳福音","verses":[{"n":1,"t":"因此，我—保羅為你們外邦人作了基督耶穌囚徒的，替你們祈禱。","notes":["「基督耶穌」：有古卷是「基督」。","此句是對照14節所加的。"]},{"n":2,"t":"想必你們曾聽見神賜恩給我，把關切你們的職分託付我，","notes":[]},{"n":3,"t":"用啟示讓我知道福音的奧祕，正如我以前略略寫過的。","notes":[]},{"n":4,"t":"你們讀了，就會知道我深深了解基督的奧祕；","notes":[]},{"n":5,"t":"這奧祕在以前的世代沒有讓人知道，像如今藉著聖靈向他的聖使徒和先知啟示一樣，","notes":[]},{"n":6,"t":"就是外邦人在基督耶穌裏，藉著福音，得以同為後嗣，同為一體，同為蒙應許的人。","notes":[]},{"n":7,"t":"我作了這福音的僕役，是照著神的恩賜，是照他運行的大能賜給我的。","notes":[]},{"n":8,"t":"雖然我比眾聖徒中最小的還小，他還賜我這恩典，讓我把基督那測不透的豐富傳給外邦人，","notes":[]},{"n":9,"t":"又使眾人都明白甚麼是歷代以來隱藏在創造萬物之神裏的奧祕，","notes":["「使眾人都明白」：有古卷是「顯明」。"]},{"n":10,"t":"為要在現今藉著教會使天上執政的、掌權的知道神百般的智慧。","notes":[]},{"n":11,"t":"這是照著神在我們主基督耶穌裏所完成的永恆的計劃。","notes":[]},{"n":12,"t":"我們因信耶穌，就在他裏面放膽無懼，滿有自信地進到神面前。","notes":["「因信耶穌」或譯「藉耶穌的信」。"]},{"n":13,"t":"所以我求你們，不要因我為你們所受的患難喪膽；這原是你們的光榮。","notes":[]},{"n":14,"t":"因此，我在父面前屈膝—","notes":[],"heads":["明白基督的愛"]},{"n":15,"t":"天上地上的各家都是從他得名的－","notes":[]},{"n":16,"t":"為要他按著他豐盛的榮耀，藉著他的靈，使你們內心的力量剛強起來；","notes":[]},{"n":17,"t":"又要他使基督因著你們的信住在你們心裏，使你們既在愛中生根立基，","notes":[]},{"n":18,"t":"能夠和眾聖徒一同明白基督的愛是何等的長、闊、高、深，並知道這愛是超過人的知識所能測度的，為要使你們充滿神一切的豐盛。","notes":[],"end":19},{"n":20,"t":"神能照著運行在我們心裏的大能充充足足地成就一切，超過我們所求所想的。","notes":[]},{"n":21,"t":"願他在教會中，並在基督耶穌裏，得著榮耀，直到世世代代，永永遠遠。阿們！","notes":[]}]},"4":{"heading":"身體的合一","verses":[{"n":1,"t":"我為主作囚徒的勸你們，既然蒙召，行事為人就要與你們所蒙的呼召相稱。","notes":[]},{"n":2,"t":"凡事要謙虛、溫柔、忍耐，用愛心互相寬容，","notes":[]},{"n":3,"t":"以和平彼此聯繫，竭力保持聖靈所賜的合一。","notes":[]},{"n":4,"t":"身體只有一個，聖靈只有一位，正如你們蒙召，是為同有一個指望而蒙召，","notes":[]},{"n":5,"t":"一主，一信，一洗，","notes":[]},{"n":6,"t":"一神－就是萬人之父，超越萬有之上，貫通萬有，在萬有之中。","notes":[]},{"n":7,"t":"我們每個人蒙恩都是照基督所量給每個人的恩賜。","notes":[]},{"n":8,"t":"所以有話說：「他升上高天的時候，擄掠了俘虜，將各樣的恩賜賞給人。」","notes":[]},{"n":9,"t":"既說「他升上」，豈不是指他曾降到地底下嗎？","notes":[]},{"n":10,"t":"那降下的，就是高升遠超越諸天之上的，為要充滿萬有。","notes":[]},{"n":11,"t":"他所賜的有使徒，有先知，有傳福音的，有牧者和教師，","notes":[]},{"n":12,"t":"為要裝備聖徒，做事奉的工作，建立基督的身體，","notes":[]},{"n":13,"t":"直等到我們眾人在信仰上同歸於一，認識神的兒子，得以長大成人，達到基督完全長成的身量。","notes":[]},{"n":14,"t":"這樣，我們不再作小孩子，中了人的詭計和欺騙的法術，被一切邪說之風搖動，飄來飄去。","notes":[]},{"n":15,"t":"我們反而要用愛心說誠實話，各方面向著基督長進，連於元首基督，","notes":[]},{"n":16,"t":"靠著他全身都連接得緊湊，百節各按各職，照著各體的功用彼此相助，使身體漸漸增長，在愛中建立自己。","notes":[]},{"n":17,"t":"所以我這樣說，且在主裏鄭重地說，你們行事為人，不要再像外邦人存虛妄的心而活。","notes":[],"heads":["舊我和新我"]},{"n":18,"t":"他們心地昏昧，因自己無知，心裏剛硬而與神所賜的生命隔絕了。","notes":[]},{"n":19,"t":"既然他們已經麻木，就放縱情慾，貪婪地行種種污穢的事。","notes":[]},{"n":20,"t":"但你們從基督學的不是這樣。","notes":[]},{"n":21,"t":"如果你們聽過他的道，領了他的教，因為真理就在耶穌裏，","notes":[]},{"n":22,"t":"你們要脫去從前的行為，脫去舊我；這舊我是因私慾的迷惑而漸漸敗壞的。","notes":[]},{"n":23,"t":"你們要把自己的心志更新，","notes":[]},{"n":24,"t":"並且穿上新我；這新我是照著神的形像造的，有從真理來的公義和聖潔。","notes":[]},{"n":25,"t":"所以，你們要棄絕謊言，每個人要與鄰舍說誠實話，因為我們是互為肢體。","notes":[],"heads":["新生活的守則"]},{"n":26,"t":"即使生氣也不要犯罪；不可含怒到日落，","notes":[]},{"n":27,"t":"不可給魔鬼留地步。","notes":[]},{"n":28,"t":"偷竊的，不要再偷；總要勤勞，親手做正當的事，這樣才可以把自己有的，分給有缺乏的人。","notes":["有古卷沒有「親手」。"]},{"n":29,"t":"一句壞話也不可出口，只要隨著需要說造就人的好話，讓聽見的人得益處。","notes":[]},{"n":30,"t":"不要使神的聖靈擔憂，你們原是受了他的印記，等候得救贖的日子來到。","notes":[]},{"n":31,"t":"一切苦毒、憤怒、惱恨、嚷鬧、毀謗，和一切的惡毒都要從你們中間除掉。","notes":[]},{"n":32,"t":"要仁慈相待，存憐憫的心，彼此饒恕，正如神在基督裏饒恕了你們一樣。","notes":[]}]},"5":{"heading":"行事為人要像光明的子女","verses":[{"n":1,"t":"所以，作為蒙慈愛的兒女，你們該效法神。","notes":[]},{"n":2,"t":"要憑愛心行事，正如基督愛我們，為我們捨了自己，當作馨香的供物和祭物獻給神。","notes":[]},{"n":3,"t":"至於淫亂和一切污穢，或是貪婪，在你們中間連提都不可，這才合乎聖徒的體統。","notes":[]},{"n":4,"t":"淫詞、妄語和粗俗的俏皮話都不合宜；總要說感謝的話。","notes":[]},{"n":5,"t":"要確實知道，無論是淫亂的，是污穢的，是貪心的（貪心的就是拜偶像的），在基督和神的國裏都得不到基業。","notes":[]},{"n":6,"t":"不要被人虛浮的話欺騙了，因這些事，神的憤怒必臨到那些悖逆的人。","notes":[]},{"n":7,"t":"所以，不要與他們同夥。","notes":[]},{"n":8,"t":"從前你們是暗昧的，但如今在主裏面是光明的，行事為人要像光明的子女—","notes":[]},{"n":9,"t":"光明所結的果子就是一切的良善、公義、誠實。","notes":[]},{"n":10,"t":"總要察驗甚麼是主所喜悅的事。","notes":[]},{"n":11,"t":"那暗昧無益的事，不可參與，倒要把這種事揭發出來。","notes":[]},{"n":12,"t":"因為，他們暗中所做的，就是連提起來都是可恥的。","notes":[]},{"n":13,"t":"凡被光所照明的都顯露出來，","notes":[]},{"n":14,"t":"因為使一切顯露出來的就是光。所以有話說：「你這睡著的人醒過來吧！要從死人中復活，基督要光照你了。」","notes":[]},{"n":15,"t":"你們要謹慎行事，不要像無知的人，要像智慧的人。","notes":[]},{"n":16,"t":"要把握時機，因為現今的世代邪惡。","notes":["或譯「要愛惜光陰」。"]},{"n":17,"t":"不要作糊塗人，要明白主的旨意如何。","notes":[]},{"n":18,"t":"不要醉酒，酒能使人放蕩；要被聖靈充滿。","notes":[]},{"n":19,"t":"要用詩篇、讚美詩、靈歌彼此對說，口唱心和地讚美主。","notes":[]},{"n":20,"t":"凡事要奉我們主耶穌基督的名常常感謝父神。","notes":[]},{"n":21,"t":"要存敬畏基督的心彼此順服。","notes":[],"heads":["丈夫和妻子"]},{"n":22,"t":"作妻子的，你們要順服自己的丈夫，如同順服主。","notes":[]},{"n":23,"t":"因為丈夫是妻子的頭，如同基督是教會的頭；他又是這身體的救主。","notes":[]},{"n":24,"t":"教會怎樣順服基督，妻子也要怎樣凡事順服丈夫。","notes":[]},{"n":25,"t":"作丈夫的，你們要愛自己的妻子，正如基督愛教會，為教會捨己，","notes":[]},{"n":26,"t":"以水藉著道把教會洗淨，使她成為聖潔，","notes":[]},{"n":27,"t":"好獻給自己，作榮耀的教會，毫無玷污、皺紋等類的缺陷，而是聖潔沒有瑕疵的。","notes":[]},{"n":28,"t":"丈夫也應當照樣愛妻子，如同愛自己的身體；愛妻子就是愛自己了。","notes":[]},{"n":29,"t":"從來沒有人恨惡自己的身體，總是保養愛惜，正像基督待教會一樣，","notes":[]},{"n":30,"t":"因我們是他身體的肢體。","notes":[]},{"n":31,"t":"「為這個緣故，人要離開父母，與妻子結合，二人成為一體。」","notes":[]},{"n":32,"t":"這是極大的奧祕，而我是指基督和教會說的。","notes":[]},{"n":33,"t":"然而，你們每個人都要愛妻子，如同愛自己一樣；妻子也要敬重她的丈夫。","notes":[]}]},"6":{"heading":"兒女和父母","verses":[{"n":1,"t":"作兒女的，你們要在主裏聽從父母，這是理所當然的。","notes":["有古卷沒有「在主裏」。"]},{"n":2,"t":"當孝敬父母，使你得福，在世長壽。這是第一條帶應許的誡命。","notes":[],"end":3},{"n":4,"t":"作父親的，你們不要激怒兒女，但要照著主的教導和勸戒養育他們。","notes":[]},{"n":5,"t":"作僕人的，你們要懼怕戰兢，用誠實的心聽從你們肉身的主人，好像聽從基督一般；","notes":[],"heads":["僕人和主人"]},{"n":6,"t":"不要只在人的眼前這樣做，像僅是討人的喜歡，而是作基督的僕人，從心裏遵行神的旨意，","notes":[]},{"n":7,"t":"甘心服侍，好像服侍主，不像服侍人，","notes":[]},{"n":8,"t":"因為知道每個人所做的善事，不論是為奴的或是自主的，都必按所做的從主得到賞賜。","notes":[]},{"n":9,"t":"作主人的，你們待僕人也是一樣，不要威嚇他們，因為知道他們和你們在天上同有一位主，他並不偏待人。","notes":[]},{"n":10,"t":"最後，你們要靠著主，依賴他的大能大力作剛強的人。","notes":[],"heads":["與邪惡爭戰"]},{"n":11,"t":"要穿戴神所賜的全副軍裝，好抵擋魔鬼的詭計。","notes":[]},{"n":12,"t":"因為我們的爭戰並不是對抗有血有肉的人，而是對抗那些執政的、掌權的、管轄這幽暗世界的，以及天空靈界的惡魔。","notes":[]},{"n":13,"t":"所以，要拿起神所賜的全副軍裝，好在邪惡的日子能抵擋仇敵，並且完成了一切後還能站立得住。","notes":[]},{"n":14,"t":"所以，要站穩了，用真理當作帶子束腰，用公義當作護心鏡遮胸，","notes":[]},{"n":15,"t":"又用和平的福音當作預備走路的鞋穿在腳上。","notes":[]},{"n":16,"t":"此外，要拿信德當作盾牌，用來撲滅那惡者一切燒著的箭。","notes":[]},{"n":17,"t":"要戴上救恩的頭盔，拿著聖靈的寶劍—就是神的道。","notes":[]},{"n":18,"t":"要靠著聖靈，隨時多方禱告祈求，並要為此警醒不倦，為眾聖徒祈求。","notes":[]},{"n":19,"t":"也要為我祈求，讓我有口才，能放膽開口講明福音的奧祕，","notes":[]},{"n":20,"t":"我為這福音的奧祕作了帶鐵鏈的使者，讓我能照著當盡的本分放膽宣講。","notes":[]},{"n":21,"t":"今有親愛、忠心服事主的弟兄推基古，為了你們也明白我的事情和我的景況，他會讓你們知道一切的事。","notes":[],"heads":["祝福"]},{"n":22,"t":"我特意打發他到你們那裏去，好讓你們知道我們的情況，又讓他安慰你們的心。","notes":[]},{"n":23,"t":"願平安、慈愛、信心從父神和主耶穌基督歸給弟兄們。","notes":["「平安」或譯「和平」。"]},{"n":24,"t":"願所有恆心愛我們主耶穌基督的人都蒙恩惠。","notes":[]}]}},"PHP":{"1":{"heading":"問候","verses":[{"n":1,"t":"基督耶穌的僕人保羅和提摩太寫信給住腓立比、在基督耶穌裏的眾聖徒，以及諸位監督和執事。","notes":[]},{"n":2,"t":"願恩惠、平安從我們的父神和主耶穌基督歸給你們！","notes":["「平安」或譯「和平」。"]},{"n":3,"t":"我每逢想念你們，就感謝我的神，","notes":[],"heads":["保羅為腓立比信徒禱告"]},{"n":4,"t":"每逢為你們眾人祈求的時候，總是歡歡喜喜地祈求，","notes":[]},{"n":5,"t":"因為從第一天直到如今，你們都同心合意興旺福音。","notes":[]},{"n":6,"t":"我深信，那在你們心裏動了美好工作的，到了耶穌基督的日子必完成這工作。","notes":[]},{"n":7,"t":"我為你們眾人有這樣的想法原是應當的，因為你們常在我心裏；無論我是在捆鎖中，在辯明並證實福音的時候，你們都與我一同蒙恩。","notes":[]},{"n":8,"t":"我以基督耶穌的心腸切切想念你們眾人，這是神可以為我作證的。","notes":[]},{"n":9,"t":"我所禱告的就是：要你們的愛心，在知識和各樣見識上，不斷增長，","notes":[]},{"n":10,"t":"使你們能分辨是非，在基督的日子作真誠無可指責的人，","notes":[]},{"n":11,"t":"更靠著耶穌基督結滿仁義的果子，歸榮耀稱讚給神。","notes":[]},{"n":12,"t":"弟兄們，我要你們知道，我所遭遇的事反而使福音更興旺，","notes":[],"heads":["我活著就是基督"]},{"n":13,"t":"以致御營全軍和其餘的人都知道我是為基督的緣故受捆鎖的；","notes":[]},{"n":14,"t":"而且那在主裏的弟兄，多半都因我受的捆鎖而篤信不疑，越發放膽無所懼怕地傳道。","notes":[]},{"n":15,"t":"有些人傳基督是出於嫉妒紛爭；有些人是出於好意。","notes":[]},{"n":16,"t":"後者是出於愛心，知道我奉差遣是為福音辯護的。","notes":[]},{"n":17,"t":"前者傳基督是出於自私，動機不純，企圖要加增我捆鎖的苦楚。","notes":[]},{"n":18,"t":"這又何妨呢？或是假意或是真心，無論如何，只要基督被傳開了，為此我就歡喜。我還要歡喜，","notes":[]},{"n":19,"t":"因為我知道，這事藉著你們的祈禱和耶穌基督的靈的幫助，終必使我得到釋放。","notes":[]},{"n":20,"t":"這就是我所切慕、所盼望的：沒有一事能使我羞愧；反倒凡事坦然無懼，無論是生是死，總要讓基督在我身上照常顯大。","notes":[]},{"n":21,"t":"因為我活著就是基督，死了就有益處。","notes":[]},{"n":22,"t":"但是，我在肉身活著，若能有工作的成果，我就不知道該挑選甚麼。","notes":[]},{"n":23,"t":"我處在兩難之間：我情願離世與基督同在，因為這是好得無比的；","notes":[]},{"n":24,"t":"然而，我為你們肉身活著更加要緊。","notes":[]},{"n":25,"t":"既然我這樣深信，就知道仍要留在世間，且與你們眾人一起存留，使你們在所信的道上又長進又喜樂，","notes":[]},{"n":26,"t":"為了我再到你們那裏時，你們在基督耶穌裏的誇耀越發加增。","notes":[]},{"n":27,"t":"最重要的是：你們行事為人要與基督的福音相稱，這樣，無論我來見你們，或不在你們那裏，都可以聽到你們的景況，知道你們同有一個心志，站立得穩，為福音的信仰齊心努力，","notes":[]},{"n":28,"t":"絲毫不怕敵人的威脅；以此證明他們會沉淪，你們會得救，這是出於神。","notes":[]},{"n":29,"t":"因為你們蒙恩，不但得以信服基督，而且要為他受苦。","notes":[]},{"n":30,"t":"你們的爭戰，就與你們曾在我身上見過、現在所聽到的是一樣的。","notes":[]}]},"2":{"heading":"以基督的心為心","verses":[{"n":1,"t":"所以，在基督裏若有任何勸勉，若有任何愛心的安慰，若有任何聖靈的團契，若有任何慈悲憐憫，","notes":[]},{"n":2,"t":"你們就要意志相同，愛心相同，有一致的心思，一致的想法，使我的喜樂得以滿足。","notes":[]},{"n":3,"t":"凡事不可自私自利，不可貪圖虛榮；只要心存謙卑，各人看別人比自己強。","notes":[]},{"n":4,"t":"各人不要單顧自己的事，也要顧別人的事。","notes":[]},{"n":5,"t":"你們當以基督耶穌的心為心：","notes":[]},{"n":6,"t":"他本有神的形像，卻不堅持自己與神同等；","notes":["「卻不堅持…同等」或譯「卻不企圖攫取與神同等的地位」。"]},{"n":7,"t":"反倒虛己，取了奴僕的形像，成為人的樣式；既有人的樣子，","notes":[]},{"n":8,"t":"就謙卑自己，存心順服，以至於死，且死在十字架上。","notes":[]},{"n":9,"t":"所以神把他升為至高，又賜給他超乎萬名之上的名，","notes":[]},{"n":10,"t":"使一切在天上的、地上的和地底下的，因耶穌的名，眾膝都要跪下，","notes":[]},{"n":11,"t":"眾口都要宣認：耶穌基督是主，歸榮耀給父神。","notes":[]},{"n":12,"t":"我親愛的，這樣看來，你們向來是順服的，不但我在你們那裏，就是我現在不在你們那裏的時候更是順服的，就當恐懼戰兢完成你們自己得救的事；","notes":[],"heads":["在這世上像明光照耀"]},{"n":13,"t":"因為是神在你們心裏運行，使你們又立志又實行，為要成就他的美意。","notes":[]},{"n":14,"t":"你們無論做甚麼事，都不要發怨言起爭論，","notes":[]},{"n":15,"t":"好使你們無可指責，誠實無偽，在這彎曲悖謬的世代作神無瑕疵的兒女。你們在這世代中要像明光照耀，","notes":[]},{"n":16,"t":"將生命的道顯明出來，使我在基督的日子得以誇耀我沒有白跑，也沒有徒勞。","notes":[]},{"n":17,"t":"我以你們的信心為供獻的祭物，我若被澆獻在其上也是喜樂，並且與你們眾人一同喜樂。","notes":[]},{"n":18,"t":"你們也要照樣喜樂，並且與我一同喜樂。","notes":[]},{"n":19,"t":"我靠主耶穌希望很快能差提摩太去見你們，好讓我知道你們的事而心裏得著安慰。","notes":[],"heads":["提摩太和以巴弗提"]},{"n":20,"t":"因為我沒有別人與我同心，真正關懷你們的事。","notes":[]},{"n":21,"t":"其他的人都求自己的事，並不求耶穌基督的事。","notes":[]},{"n":22,"t":"但你們知道提摩太是經得起考驗的，他與我為了福音一同服侍，待我像兒子待父親一樣。","notes":[]},{"n":23,"t":"所以，我一看出我的事怎樣了結，我希望立刻差他去，","notes":[]},{"n":24,"t":"但我靠著主自信我不久也會去。","notes":[]},{"n":25,"t":"然而，我想必須差以巴弗提到你們那裏去。他是我的弟兄、同工和戰友，是你們差遣來供應我需要的。","notes":[]},{"n":26,"t":"他很想念你們眾人，並且極其難過，因為你們聽見他病了。","notes":["有古卷加「要見」。"]},{"n":27,"t":"他真的生病了，幾乎要死。然而神憐憫他，不但憐憫他，也憐憫我，免得我憂上加憂。","notes":[]},{"n":28,"t":"所以，我更要盡快送他回去，好讓你們再見到他而喜樂，我也可以減少憂愁。","notes":[]},{"n":29,"t":"故此，你們要在主裏歡歡喜喜地接待他，而且要尊重這樣的人，","notes":[]},{"n":30,"t":"因他為做基督的工作不顧性命，幾乎至死，為要補足你們供應我不夠的地方。","notes":[]}]},"3":{"heading":"真正的義","verses":[{"n":1,"t":"末了，我的弟兄們，你們要靠主喜樂。我把這些話再寫給你們，對我並不困難，對你們卻是妥當的。","notes":[]},{"n":2,"t":"應當防備犬類，防備作惡的，防備妄自行割的。","notes":[]},{"n":3,"t":"因為真受割禮的，就是我們這藉著神的靈敬拜、以基督耶穌為誇耀、不依靠肉體的。","notes":[]},{"n":4,"t":"其實，我也可以靠肉體；若是別人以為他可以依靠肉體，我更可以。","notes":[]},{"n":5,"t":"我出生後第八天受割禮；我是以色列族、便雅憫支派的人，是希伯來人所生的希伯來人。就律法說，我是法利賽人；","notes":[]},{"n":6,"t":"就熱心說，我是迫害教會的；就律法上的義說，我是無可指責的。","notes":[]},{"n":7,"t":"只是我先前以為對我是有益的，我現在因基督的緣故而當作是有損的。","notes":[]},{"n":8,"t":"不但如此，我已把萬事當作是有損的，因我以認識我主基督耶穌為至寶。我為他已經丟棄萬事，看作糞土，為要贏得基督，","notes":[]},{"n":9,"t":"並且得以在他裏面，不是有自己因律法而得的義，而是有信基督的義，就是基於信，從神而來的義，","notes":["「有信基督的義」或譯「有藉基督的信而來的義」。"]},{"n":10,"t":"使我認識基督，知道他復活的大能，並且知道和他一同受苦，效法他的死，","notes":[]},{"n":11,"t":"或許我也得以從死人中復活。","notes":[]},{"n":12,"t":"這不是說我已經得著了，已經完全了；而是竭力追求，或許可以得著基督耶穌所要我得著的。","notes":["「基督耶穌」：有古卷是「基督」。","「所要我得著的」或譯「所以得著我的」。"],"heads":["向著標竿直跑"]},{"n":13,"t":"弟兄們，我不是以為自己已經得著了；我只有一件事，就是忘記背後，努力面前的，","notes":[]},{"n":14,"t":"向著標竿直跑，要得神在基督耶穌裏從上面召我來得的獎賞。","notes":[]},{"n":15,"t":"所以，我們中間凡是成熟的人，總要存這樣的心；若在甚麼事上存別樣的心，神也會把這些事指示你們。","notes":[]},{"n":16,"t":"然而，我們達到甚麼地步，就當照這個地步行。","notes":[]},{"n":17,"t":"弟兄們，你們要一同效法我，也當留意看那些效法我們榜樣的人。","notes":[]},{"n":18,"t":"因為，我屢次告訴你們，現在又流淚告訴你們：許多人行事是基督十字架的仇敵。","notes":[]},{"n":19,"t":"他們的結局就是滅亡。他們的神明是自己的肚腹；他們以自己的羞辱為光榮，專以地上的事為念。","notes":[]},{"n":20,"t":"我們卻是天上的國民，並且等候救主，就是主耶穌基督從天上降臨。","notes":[]},{"n":21,"t":"他要按著那能使萬有歸服自己的大能，把我們這卑賤的身體改變形狀，和他自己榮耀的身體相似。","notes":[]}]},"4":{"heading":"保羅的勸導","verses":[{"n":1,"t":"我所親愛、所想念的弟兄們，你們就是我的喜樂，我的冠冕。我親愛的，你們應當靠主站立得穩。","notes":[]},{"n":2,"t":"我勸友阿蝶和循都基要在主裏同心。","notes":[]},{"n":3,"t":"我也求你這真實同負一軛的，要幫助這兩個女人，因為她們在福音上曾與我、革利免和我其餘的同工一同勞苦，他們的名字都在生命冊上。","notes":[]},{"n":4,"t":"你們要靠主常常喜樂。我再說，你們要喜樂。","notes":[]},{"n":5,"t":"要讓眾人知道你們謙讓的心。主已經近了。","notes":[]},{"n":6,"t":"應當一無掛慮，只要凡事藉著禱告、祈求和感謝，將你們所要的告訴神。","notes":[]},{"n":7,"t":"神所賜那超越人所能了解的平安，必在基督耶穌裏，保守你們的心懷意念。","notes":["「平安」或譯「和平」；9節同。"]},{"n":8,"t":"末了，弟兄們，凡是真實的、凡是可敬的、凡是公義的、凡是清潔的、凡是可愛的、凡是有美名的，若有甚麼德行，若有甚麼稱讚，你們都要留意。","notes":[]},{"n":9,"t":"你們從我所學習的，所領受的，所聽見的，所看見的事，你們都要繼續去做，賜平安的神就必與你們同在。","notes":[]},{"n":10,"t":"我靠主大大喜樂，因為你們關懷我的心如今又表現了出來；其實你們一直都關懷我，只是沒有機會罷了。","notes":[],"heads":["為饋贈致謝"]},{"n":11,"t":"我並不是因缺乏而說這話，因為我已經學會無論在甚麼景況都可以知足。","notes":[]},{"n":12,"t":"我知道怎樣處卑賤，也知道怎樣處豐富；或飽足或飢餓，或有餘或缺乏，任何事情，任何景況，我都得了祕訣。","notes":[]},{"n":13,"t":"我靠著那加給我力量的，凡事都能做。","notes":[]},{"n":14,"t":"然而，你們能和我分擔憂患是一件好事。","notes":[]},{"n":15,"t":"腓立比人哪，你們也知道我開始傳福音、離開馬其頓的時候，在收支的事上，除了你們以外，並沒有別的教會和我分擔。","notes":[]},{"n":16,"t":"就是我在帖撒羅尼迦，你們也一再差人來供給我的需用。","notes":[]},{"n":17,"t":"我並不求甚麼饋贈，只求你們的果子不斷增多，歸在你們的賬上。","notes":[]},{"n":18,"t":"但我已經如數收到，並且有餘；我已經充足，因我從以巴弗提受了你們的饋贈，當作極美的香氣，為神所接納、所喜悅的祭物。","notes":[]},{"n":19,"t":"我的神必照他榮耀的豐富，在基督耶穌裏，使你們一切所需用的都充足。","notes":[]},{"n":20,"t":"願榮耀歸給我們的父神，直到永永遠遠。阿們！","notes":[]},{"n":21,"t":"請問候在基督耶穌裏的各位聖徒。跟我一起的眾弟兄都問候你們。","notes":[],"heads":["祝福"]},{"n":22,"t":"眾聖徒都問候你們，特別在凱撒家裏的人問候你們。","notes":[]},{"n":23,"t":"願主耶穌基督的恩與你們的靈同在！","notes":[]}]}},"COL":{"1":{"heading":"問候","verses":[{"n":1,"t":"奉神旨意，作基督耶穌使徒的保羅，和我們的弟兄提摩太，","notes":[]},{"n":2,"t":"寫信給歌羅西的聖徒，在基督裏忠心的弟兄。願恩惠、平安從我們的父神歸給你們！","notes":["「平安」或譯「和平」。"]},{"n":3,"t":"我們為你們禱告的時候，常常感謝我們主耶穌基督的父神，","notes":["「父神」：有古卷是「父和神」。"],"heads":["為信徒感謝神"]},{"n":4,"t":"因為聽見你們對基督耶穌的信心，並對眾聖徒有的愛心。","notes":[]},{"n":5,"t":"這都是因著那給你們存在天上的盼望，它就是你們從前所聽見真理的道，就是福音；","notes":[]},{"n":6,"t":"這福音傳到你們那裏，也傳到普天下，並且繼續增長，不斷結果，正如自從你們聽見福音，真正知道神恩惠的日子起，在你們中間也是這樣。","notes":[]},{"n":7,"t":"這福音是你們從我們所親愛、一同作僕人的以巴弗學到的。他為我們作了基督的忠心僕役，","notes":["「我們」：有古卷是「你們」。"]},{"n":8,"t":"也把聖靈賜給你們的愛告訴我們。","notes":[]},{"n":9,"t":"因此，我們自從聽見的日子就不住地為你們禱告和祈求，願你們滿有一切屬靈的智慧和悟性，真正知道神的旨意，","notes":[],"heads":["基督和他的工作"]},{"n":10,"t":"好使你們行事為人對得起主，凡事蒙他喜悅，在一切善事上結果子，對神的認識更有長進。","notes":[]},{"n":11,"t":"願你們從他榮耀的權能中，得以在一切事上力上加力，好使你們凡事歡歡喜喜地忍耐寬容，","notes":[]},{"n":12,"t":"又感謝父，使你們配與眾聖徒在光明中分享基業。","notes":[]},{"n":13,"t":"他救了我們脫離黑暗的權勢，遷移到他愛子的國度裏。","notes":[]},{"n":14,"t":"藉著他的愛子，我們得蒙救贖，罪得赦免。","notes":[]},{"n":15,"t":"愛子是那看不見的神之像，是首生的，在一切被造的以先。","notes":["「首生的」或譯「長子」；18節同。"]},{"n":16,"t":"因為萬有都是在他裏面造的，無論是天上的、地上的，能看見的、不能看見的，或是有權位的、統治的，或是執政的、掌權的，一概都是藉著他為著他造的。","notes":["「在他裏面」或譯「藉著他」。"]},{"n":17,"t":"他在萬有之先；萬有也靠他而存在。","notes":[]},{"n":18,"t":"他是身體（教會）的頭；他是元始，是從死人中復活的首生者，好讓他在萬有中居首位。","notes":[]},{"n":19,"t":"因為神喜歡使一切的豐盛在他裏面居住，","notes":[]},{"n":20,"t":"藉著他，神使萬有與自己和好，無論是地上的、天上的，都藉著他在十字架上所流的血促成了和平。","notes":["有古卷沒有「藉著他」。"]},{"n":21,"t":"從前你們與神隔絕，心思上與他為敵，行為邪惡；","notes":[]},{"n":22,"t":"但如今，他藉著他兒子肉身的死，已經使你們與他自己和好了，把你們獻在他的面前，成為聖潔，沒有瑕疵，無可指責。","notes":["「他藉著…和好了」：有古卷是「藉著他兒子肉身的死，你們已經得以跟他和好了」。"]},{"n":23,"t":"只要你們持守信仰，根基穩固，堅定不移，不致動搖，離開了你們從前所聽見的福音的盼望；這福音也是傳給天下一切被造之物的，我—保羅作了這福音的僕役。","notes":[]},{"n":24,"t":"現在我為你們受苦，倒很快樂；並且為基督的身體，就是為教會，我要在自己的肉身上補滿基督未盡的苦難。","notes":[],"heads":["保羅為教會的工作"]},{"n":25,"t":"我照神為你們所賜我的職分作了教會的僕役，要把神的道傳得完滿；","notes":[]},{"n":26,"t":"這道就是歷世歷代所隱藏的奧祕，但如今向他的聖徒顯明了。","notes":[]},{"n":27,"t":"神要讓他們知道，這奧祕在外邦人中有何等豐盛的榮耀；就是基督在你們心裏成了得榮耀的盼望。","notes":["「心裏」或譯「中間」。"]},{"n":28,"t":"我們傳揚他，是用諸般的智慧，勸戒各人，教導各人，要把各人在基督裏完完全全地獻上。","notes":["「要把各人…獻上」或譯「要使各人在基督裏成熟地獻上」。"]},{"n":29,"t":"我也為此勞苦，照著他在我裏面運用的大能盡心竭力。","notes":[]}]},"2":{"heading":"基督裏的豐盛","verses":[{"n":1,"t":"我要你們知道，我為你們和老底嘉人，和所有沒有與我見過面的人，是何等地勤奮；","notes":[]},{"n":2,"t":"為要使他們的心得安慰，因愛心互相聯絡，以致有從確實了解所產生的豐盛，好深知神的奧祕，就是基督；","notes":[]},{"n":3,"t":"在他裏面蘊藏著一切智慧和知識。","notes":[]},{"n":4,"t":"我說這話，免得有人用花言巧語迷惑你們。","notes":[]},{"n":5,"t":"雖然我身體不在你們那裏，心卻與你們同在，很高興見你們循規蹈矩，對基督的信心也堅固。","notes":[]},{"n":6,"t":"既然你們接受了主基督耶穌，就要靠著他而生活，","notes":[]},{"n":7,"t":"照著你們所領受的教導，在他裏面生根建造，信心堅固，充滿著感謝的心。","notes":[]},{"n":8,"t":"你們要謹慎，免得有人用他的哲學和虛空的廢話，不照著基督，而是照人間的傳統和世上粗淺的學說，把你們擄去。","notes":["「世上粗淺的學說」或譯「宇宙的星宿」；20-21節同。"]},{"n":9,"t":"因為神本性一切的豐盛都有形有體地居住在基督裏面；","notes":[]},{"n":10,"t":"你們在他裏面也已經成為豐盛。他是所有執政掌權者的元首。","notes":[]},{"n":11,"t":"你們也在他裏面受了不是人手所行的割禮，而是使你們脫去肉體情慾的基督的割禮。","notes":[]},{"n":12,"t":"你們既受洗與他一同埋葬，也就在此禮上，因信那使他從死人中復活的神的作為跟他一同復活。","notes":[]},{"n":13,"t":"你們從前在過犯和未受割禮的肉體中死了，神卻赦免了你們一切的過犯，使你們與基督一同活過來，","notes":[]},{"n":14,"t":"塗去了在律例上所寫、敵對我們、束縛我們的字據，把它撤去，釘在十字架上。","notes":[]},{"n":15,"t":"基督既將一切執政者、掌權者的權勢解除了，就在凱旋的行列中，將他們公開示眾，仗著十字架誇勝。","notes":[]},{"n":16,"t":"所以，不要讓任何人在飲食上，或節期、初一、安息日等事上評斷你們。","notes":[]},{"n":17,"t":"這些原是未來的事的影子，真體卻是屬基督的。","notes":[]},{"n":18,"t":"不要讓人藉著故作謙虛和敬拜天使奪去你們的獎賞。這等人拘泥在所見過的幻象，隨著自己的慾望無故地自高自大，","notes":["有古卷是「這等人窺察所沒有見過的」。"]},{"n":19,"t":"不緊隨元首；其實，由於他全身藉著關節筋絡才得到滋養，互相聯絡，靠神所賜的成長而成長。","notes":[]},{"n":20,"t":"既然你們與基督同死而脫離了世上粗淺的學說，為甚麼仍像生活在世俗中一樣，去服從那「不可拿、不可嘗、不可摸」等類的規條呢？","notes":[],"end":21,"heads":["基督裏的新生活"]},{"n":22,"t":"這些都是根據人的命令和教導，論到這一切都是一經使用就都敗壞了。","notes":[]},{"n":23,"t":"這些規條使人徒有智慧之名，用私意崇拜，自表謙卑，苦待己身，其實在克制肉體的情慾上毫無功效。","notes":[]}]},"3":{"heading":"新生活的本分","verses":[{"n":1,"t":"所以，既然你們已經與基督一同復活，就當求上面的事；那裏有基督，坐在神的右邊。","notes":[]},{"n":2,"t":"你們要思考上面的事，不要思考地上的事。","notes":[]},{"n":3,"t":"因為你們已經死了，你們的生命與基督一同藏在神裏面。","notes":[]},{"n":4,"t":"基督是你們的生命，他顯現的時候，你們也要與他一同在榮耀裏顯現。","notes":[]},{"n":5,"t":"所以，要治死你們在地上的肢體；就如淫亂、污穢、邪情、惡慾和貪婪—貪婪就是拜偶像。","notes":[]},{"n":6,"t":"因這些事，神的憤怒必臨到那些悖逆的人。","notes":["「必臨到…的人」：有古卷是「必來臨」。"]},{"n":7,"t":"當你們在這些事中活著的時候，你們的行為也曾是這樣的。","notes":[]},{"n":8,"t":"但現在你們要棄絕這一切的事，就是惱恨、憤怒、惡毒、毀謗和口中污穢的言語。","notes":[]},{"n":9,"t":"不要彼此說謊，因為你們已經脫去舊人和舊人的行為，","notes":[]},{"n":10,"t":"穿上了新人，這新人照著造他的主的形像在知識上不斷地更新。","notes":[]},{"n":11,"t":"在這事上並不分希臘人和猶太人，受割禮的和未受割禮的，未開化的人、西古提人、為奴的、自主的；惟獨基督是一切，又在一切之內。","notes":[]},{"n":12,"t":"所以，你們既是神的選民，聖潔、蒙愛的人，要穿上憐憫、恩慈、謙虛、溫柔和忍耐。","notes":[]},{"n":13,"t":"倘若這人與那人有嫌隙，總要彼此容忍，彼此饒恕；主怎樣饒恕了你們，你們也要怎樣饒恕人。","notes":["有古卷是「基督」。"]},{"n":14,"t":"除此以外，還要穿上愛心，因為愛是貫通全德的。","notes":[]},{"n":15,"t":"你們要讓基督所賜的和平在你們心裏作主，也為此蒙召，歸為一體。你們還要存感謝的心。","notes":[]},{"n":16,"t":"當用各樣的智慧，把基督的道豐豐富富的存在心裏，用詩篇、讚美詩、靈歌，彼此教導，互相勸戒，以感恩的心歌頌神。","notes":[]},{"n":17,"t":"你們無論做甚麼，或說話或行事，都要奉主耶穌的名，藉著他感謝父神。","notes":[]},{"n":18,"t":"你們作妻子的，要順服自己的丈夫，這在主裏面是合宜的。","notes":[]},{"n":19,"t":"你們作丈夫的，要愛你們的妻子，不可虐待她們。","notes":[]},{"n":20,"t":"你們作兒女的，要凡事聽從父母，因為這是主所喜悅的。","notes":[]},{"n":21,"t":"你們作父親的，不要惹兒女生氣，恐怕他們會灰心。","notes":[]},{"n":22,"t":"你們作僕人的，要凡事聽從你們肉身的主人，不要只在眼前服事，像是討人喜歡的，總要心存誠實，因為你們敬畏主。","notes":[]},{"n":23,"t":"你們無論做甚麼，都要從心裏做，像是為主做的，不是為人做的；","notes":[]},{"n":24,"t":"因為你們知道，從主那裏必得著基業作為賞賜。你們要服侍的是主基督。","notes":[]},{"n":25,"t":"行不義的人必受不義的報應；主並不偏待人。","notes":[]}]},"4":{"heading":"勸導","verses":[{"n":1,"t":"你們作主人的，待僕人要公正，因為知道，你們也有一位主在天上。","notes":[]},{"n":2,"t":"你們要恆切禱告，在禱告中警醒感恩。","notes":[]},{"n":3,"t":"同時，也要為我們禱告，求神給我們開傳道的門，能宣講基督的奧祕，","notes":[]},{"n":4,"t":"使我能按著所該說的話將這奧祕顯明出來，我為此而被捆鎖。","notes":[]},{"n":5,"t":"你們要把握時機，用智慧與外人來往。","notes":[]},{"n":6,"t":"你們的言談要時常帶著溫和，好像用鹽調味，讓你們知道該怎樣應對每一個人。","notes":[]},{"n":7,"t":"推基古是我親愛的弟兄，忠心的僕役，和我一同作主的僕人；他要把我一切的事都告訴你們。","notes":[],"heads":["最後的問候"]},{"n":8,"t":"我特意打發他到你們那裏去，好讓你們知道我們的情況，又讓他安慰你們的心。","notes":[]},{"n":9,"t":"我又打發一位親愛忠心的弟兄阿尼西謀同去；他也是你們那裏的人。他們會把這裏一切的事都告訴你們。","notes":[]},{"n":10,"t":"與我一同坐牢的亞里達古問候你們。巴拿巴的表弟馬可也問候你們。關於他，你們已經得到指示；他若到你們那裏，你們要接待他。","notes":[]},{"n":11,"t":"稱為猶士都的耶數也問候你們。奉割禮的人中，只有這三個人是為神的國與我作同工的，也是使我心裏得安慰的。","notes":[]},{"n":12,"t":"有一位你們那裏的人，作基督耶穌僕人的以巴弗問候你們。他禱告的時候常為你們竭力祈求，願你們能站穩而成熟，充分確信神一切的旨意。","notes":["「基督耶穌」：有古卷是「基督」。"]},{"n":13,"t":"他為你們、老底嘉和希拉坡里的弟兄多多勞苦，這是我可以為他作見證的。","notes":[]},{"n":14,"t":"親愛的醫生路加和底馬問候你們。","notes":[]},{"n":15,"t":"請問候老底嘉的弟兄以及寧法，和她家裏的教會。","notes":["有古卷是「和他們家裏」。"]},{"n":16,"t":"你們宣讀了這書信，也要交給老底嘉的教會宣讀；你們也要宣讀從老底嘉轉來的書信。","notes":[]},{"n":17,"t":"你們要對亞基布說：「務要完成你從主所領受的職分。」","notes":[]},{"n":18,"t":"我—保羅親筆問候你們。要記念我在捆鎖中。願恩惠與你們同在！","notes":[]}]}},"1TH":{"1":{"heading":"問候","verses":[{"n":1,"t":"保羅、西拉、提摩太寫信給帖撒羅尼迦在父神和主耶穌基督裏的教會。願恩惠、平安歸給你們！","notes":["「平安」或譯「和平」。"]},{"n":2,"t":"我們為你們眾人常常感謝神，禱告的時候提到你們，","notes":[],"heads":["帖撒羅尼迦信徒的信心和榜樣"]},{"n":3,"t":"在我們的父神面前，不住地記念你們因信心所做的工作，因愛心所受的勞苦，因盼望我們主耶穌基督所存的堅忍。","notes":[]},{"n":4,"t":"神所愛的弟兄啊，我知道你們是蒙揀選的；","notes":[]},{"n":5,"t":"因為我們的福音傳到你們那裏，不僅在言語，也在能力，也在聖靈和充足的確信。你們知道，我們在你們那裏，為你們的緣故是怎樣為人。","notes":[]},{"n":6,"t":"你們成為效法我們，更效法主的人，因聖靈所激發的喜樂，在大患難中領受了真道，","notes":[]},{"n":7,"t":"從此你們作了馬其頓和亞該亞所有信主的人的榜樣。","notes":[]},{"n":8,"t":"因為主的道已經從你們那裏傳播出去，你們向神的信心不只在馬其頓和亞該亞，就是在各處也都傳開了，所以不用我們說甚麼話。","notes":[]},{"n":9,"t":"因為他們自己已經傳講我們是怎樣進到你們那裏，你們是怎樣離棄偶像，歸向神來服侍那又真又活的神，","notes":[]},{"n":10,"t":"等候他兒子從天降臨，就是神使他從死人中復活的那位救我們脫離將來憤怒的耶穌。","notes":[]}]},"2":{"heading":"保羅在帖撒羅尼迦的工作","verses":[{"n":1,"t":"弟兄們，你們自己知道我們來到你們那裏並不是徒然的。","notes":[]},{"n":2,"t":"我們從前在腓立比蒙難受辱，這是你們知道的，可是我們還是靠著神給我們的勇氣，在強烈反對中把神的福音傳給你們。","notes":[]},{"n":3,"t":"我們的勸勉不是出於錯誤，也不是出於污穢，也不是用詭詐。","notes":[]},{"n":4,"t":"但神既然認定我們經得起考驗，把福音託付我們，我們就照著傳講，不是要討人喜歡，而是要討那考驗我們的心的神喜歡。","notes":[]},{"n":5,"t":"因為我們從來沒有用過諂媚的話，這是你們知道的，也沒有藏著貪心，這是神可以作證的。","notes":[]},{"n":6,"t":"我們作為基督的使徒，雖然可以受人尊重，卻沒有向你們或向別人求榮耀，反而在你們當中心存溫柔，如同母親哺乳自己的孩子。","notes":[],"end":7},{"n":8,"t":"既然我們這樣愛你們，不但樂意將神的福音給你們，連自己的性命也樂意給你們，因為你們是我們所疼愛的。","notes":[]},{"n":9,"t":"弟兄們，你們記念我們的辛苦勞碌，晝夜做工，傳神的福音給你們，免得你們任何人受累。","notes":[]},{"n":10,"t":"我們對你們信主的人是何等聖潔、正直、無可指責，這有你們作證，也有神作證。","notes":[]},{"n":11,"t":"正如你們知道，我們待你們好像父親待自己的兒女一樣。","notes":[]},{"n":12,"t":"我們勸勉你們，安慰你們，囑咐你們，使你們行事對得起那召你們進他自己的國、得他榮耀的神。","notes":[]},{"n":13,"t":"為此，我們也不斷地感謝神，因為你們聽見我們所傳神的道的時候，你們領受了，不以為這是人的道，而以為這確實是神的道，而且在你們信主的人當中運行著。","notes":[]},{"n":14,"t":"弟兄們，你們與猶太地區神的各教會，就是在基督耶穌裏的各教會，有同樣的遭遇，因為你們也受了同胞的迫害，像他們受了猶太人的迫害一樣。","notes":[]},{"n":15,"t":"這些猶太人不但殺了主耶穌和先知們，又把我們趕出去。他們令神不悅，且與眾人為敵，","notes":[]},{"n":16,"t":"阻撓我們傳道給外邦人，使他們得救，以致常常惡貫滿盈，但神的憤怒終於臨到他們身上。","notes":[]},{"n":17,"t":"弟兄們，我們被迫暫時與你們分離，身體離開，心卻沒有；我們極力想法子，渴望見你們的面。","notes":[],"heads":["保羅希望再訪問帖撒羅尼迦教會"]},{"n":18,"t":"所以我們很想到你們那裏去。我－保羅有一兩次要去，只是撒但阻擋了我們。","notes":[]},{"n":19,"t":"當我們的主耶穌再來，我們站在他面前的時候，我們的盼望、喜樂和所誇的冠冕是甚麼呢？不正是你們嗎？","notes":[]},{"n":20,"t":"你們就是我們的榮耀和喜樂！","notes":[]}]},"3":{"heading":"","verses":[{"n":1,"t":"既然我們不能再忍，就決定獨自留在雅典，","notes":[]},{"n":2,"t":"於是差派我們在基督福音上作神同工的弟兄提摩太前去，在你們所信的道上堅固你們，勸勉你們，","notes":[]},{"n":3,"t":"免得有人被這些患難動搖。因為你們自己知道，我們受患難原是命定的。","notes":[]},{"n":4,"t":"我們在你們那裏的時候，曾預先告訴你們，我們必受患難；你們知道，這果然發生了。","notes":[]},{"n":5,"t":"為此，既然我不能再忍，就差派人去，要知道你們的信心如何，恐怕那誘惑人的果真誘惑了你們，以致我們的勞苦歸於徒然。","notes":[]},{"n":6,"t":"但是，提摩太剛從你們那裏回來，將你們信心和愛心的好消息報給我們，又說你們常常記念我們，切切想見我們，如同我們想見你們一樣。","notes":[]},{"n":7,"t":"所以，弟兄們，我們在一切困苦患難中，因著你們的信心得到鼓勵。","notes":[]},{"n":8,"t":"如今你們若靠主站立得穩，我們就得生了。","notes":[]},{"n":9,"t":"我們在神面前，因著你們滿有喜樂。為這一切喜樂，我們能用怎樣的感謝為你們報答神呢？","notes":[]},{"n":10,"t":"我們晝夜切切祈求要見你們的面，來補足你們信心的不足。","notes":[]},{"n":11,"t":"願我們的父神自己和我們的主耶穌，為我們開路到你們那裏去。","notes":[]},{"n":12,"t":"又願主使你們彼此相愛的心，和愛眾人的心，都能增長，充足，如同我們愛你們一樣，","notes":[]},{"n":13,"t":"好堅固你們的心，使你們在我們的主耶穌同他眾聖徒來臨的時候，在我們父神面前，成為聖潔，無可指責。阿們！","notes":["有古卷沒有「阿們！」"]}]},"4":{"heading":"神所悅納的生活","verses":[{"n":1,"t":"末了，弟兄們，我們靠著主耶穌求你們，勸你們，既然你們領受了我們的教導，知道該怎樣行事為人，討神的喜悅，其實你們也正這樣行，我勸你們要更加努力。","notes":[]},{"n":2,"t":"你們原知道，我們憑主耶穌傳給你們甚麼命令。","notes":[]},{"n":3,"t":"神的旨意就是要你們成為聖潔，遠避淫行；","notes":[]},{"n":4,"t":"要你們各人知道怎樣用聖潔、尊貴控制自己的身體 ，","notes":["「控制自己的身體」或譯「與自己的妻子相處」。"]},{"n":5,"t":"不放縱私慾的邪情，像不認識神的外邦人。","notes":[]},{"n":6,"t":"不准有人在這事上越軌，佔他弟兄的便宜；因為這一類的事，主必報應，正如我預先對你們說過，又切切警告過你們的。","notes":[]},{"n":7,"t":"神召我們本不是要我們沾染污穢，而是要我們聖潔。","notes":[]},{"n":8,"t":"所以，那棄絕這教導的不是棄絕人，而是棄絕那把自己的聖靈賜給你們的神。","notes":[]},{"n":9,"t":"有關弟兄間的手足之情，不用人寫信給你們，因為你們自己蒙了神的教導要彼此相愛。","notes":[]},{"n":10,"t":"你們向全馬其頓的眾弟兄固然是這樣行，但我勸弟兄們要更加努力。","notes":[]},{"n":11,"t":"要立志過安靜的生活，管自己的事，親手做工，正如我們從前吩咐你們的，","notes":["有古卷沒有「親手」。"]},{"n":12,"t":"好使你們的行為能得外人的尊敬，同時也不依賴任何人。","notes":[]},{"n":13,"t":"弟兄們，至於已睡了的人，我們不願意你們不知道，恐怕你們憂傷，像那些沒有指望的人一樣。","notes":[],"heads":["主的再臨"]},{"n":14,"t":"既然我們信耶穌死了，復活了，那些已經在耶穌裏睡了的人，神也必將他們與耶穌一同帶來。","notes":[]},{"n":15,"t":"我們照主的話告訴你們一件事：我們這活著還存留到主來臨的人，絕不會在那已經睡了的人之先。","notes":[]},{"n":16,"t":"因為，召集令一發，天使長的呼聲一叫，神的號角一吹，主必親自從天降臨；那在基督裏死了的人必先復活，","notes":[]},{"n":17,"t":"然後我們這些活著還存留的人必和他們一同被提到雲裏，在空中與主相會。這樣，我們就要和主永遠同在。","notes":[]},{"n":18,"t":"所以，你們當用這些話彼此勸勉。","notes":[]}]},"5":{"heading":"最後的勸勉與祝福","verses":[{"n":1,"t":"弟兄們，關於那時候和日期，不用人寫信給你們，","notes":[]},{"n":2,"t":"因為你們自己明明知道，主的日子來到會像賊在夜間突然來到一樣。","notes":[]},{"n":3,"t":"人正說平安穩定的時候，災禍忽然臨到他們，如同陣痛臨到懷胎的婦人一樣，他們絕逃脫不了。","notes":[]},{"n":4,"t":"弟兄們，你們並不在黑暗裏，那日子不會像賊一樣臨到你們。","notes":[]},{"n":5,"t":"你們都是光明之子，都是白晝之子；我們不屬黑夜，也不屬幽暗。","notes":[]},{"n":6,"t":"所以，我們不要沉睡，像別人一樣，總要警醒謹慎。","notes":[]},{"n":7,"t":"因為睡了的人是在夜間睡，醉了的人是在夜間醉。","notes":[]},{"n":8,"t":"但既然我們屬於白晝，就應當謹慎，把信和愛當作護心鏡遮胸，把得救的盼望當作頭盔戴上。","notes":[]},{"n":9,"t":"因為神不是預定我們受懲罰，而是預定我們藉著我們的主耶穌基督得救。","notes":[]},{"n":10,"t":"他替我們死，讓我們無論醒著、睡著，都與他同活。","notes":[]},{"n":11,"t":"所以，你們該彼此勸勉，互相造就，正如你們素常做的。","notes":[]},{"n":12,"t":"弟兄們，我們勸你們要敬重那些在你們中間勞苦的，就是在主裏面督導你們、勸戒你們的人。","notes":[]},{"n":13,"t":"又因他們所做的工作，要以愛心格外尊重他們。你們也要彼此和睦。","notes":[]},{"n":14,"t":"弟兄們，我們勸你們，要警戒不守規矩的人，勉勵灰心的人，扶助軟弱的人，對眾人要有耐心。","notes":[]},{"n":15,"t":"你們要謹慎，無論是誰都不要以惡報惡，彼此間和對眾人都要追求做好事。","notes":[]},{"n":16,"t":"要常常喜樂，","notes":[]},{"n":17,"t":"不住地禱告，","notes":[]},{"n":18,"t":"凡事謝恩，因為這是神在基督耶穌裏向你們所定的旨意。","notes":[]},{"n":19,"t":"不要熄滅聖靈；","notes":[]},{"n":20,"t":"不要藐視先知的講論。","notes":[]},{"n":21,"t":"但凡事要察驗：美善的事要持守，","notes":[]},{"n":22,"t":"各樣惡事要禁戒。","notes":[]},{"n":23,"t":"願賜平安的神親自使你們完全成聖！願你們的靈、魂、體得蒙保守，在我們的主耶穌基督來臨的時候，完全無可指責。","notes":["「平安」或譯「和平」。"]},{"n":24,"t":"那召你們的本是信實的，他必成就這事。","notes":[]},{"n":25,"t":"弟兄們，請也為我們禱告。","notes":["有古卷是「請為」。"]},{"n":26,"t":"用聖潔的吻向眾弟兄問安。","notes":[]},{"n":27,"t":"我指著主囑咐你們，要把這信宣讀給眾弟兄聽。","notes":[]},{"n":28,"t":"願我們的主耶穌基督的恩惠與你們同在！","notes":[]}]}},"2TH":{"1":{"heading":"問候","verses":[{"n":1,"t":"保羅、西拉和提摩太寫信給帖撒羅尼迦、在我們的父神與主耶穌基督裏的教會。","notes":[]},{"n":2,"t":"願恩惠、平安從我們的父神和主耶穌基督歸給你們！","notes":["「平安」或譯「和平」。","有古卷沒有「我們的」。"]},{"n":3,"t":"弟兄們，我們該常常為你們感謝神，這本是合宜的；因為你們的信心格外增長，你們眾人彼此相愛的心也都增加。","notes":[],"heads":["基督再來時的審判"]},{"n":4,"t":"所以，我們在神的各教會裏為你們誇耀，因為你們在所受的一切壓迫患難中仍牢守著耐心和信心。","notes":[]},{"n":5,"t":"這正是神公義判斷的明證，使你們配得上他的國，你們就是為這國受苦。","notes":[]},{"n":6,"t":"既然神是公義的，他必以患難報復那加患難給你們的人，","notes":[]},{"n":7,"t":"也必使你們這受患難的人與我們同得平安。那時，主耶穌同他有權能的天使從天上在火焰中顯現，要報應那些不認識神和不聽從我們的主耶穌福音的人。","notes":[],"end":8},{"n":9,"t":"他們要受懲罰，永遠沉淪，與主的面和他權能的榮光隔絕。","notes":[]},{"n":10,"t":"這正是主再來，要在他聖徒的身上得榮耀，就是要使一切信的人感到驚訝的那日子，因為你們信了我們對你們作的見證。","notes":[]},{"n":11,"t":"為此，我們常為你們禱告，願我們的神看你們與他的呼召相配，又用大能成就你們一切良善的美意和因信心所做的工作，","notes":[]},{"n":12,"t":"使我們主耶穌的名，照著我們的神和主耶穌基督的恩，在你們身上得榮耀，你們也在他身上得榮耀。","notes":[]}]},"2":{"heading":"不法的人","verses":[{"n":1,"t":"弟兄們，關於我們主耶穌基督的來臨和我們到他那裏聚集，我勸你們：","notes":[]},{"n":2,"t":"無論藉著靈，藉著言語，藉著冒我的名寫的書信，說主的日子已經到了，不要輕易動心，也不要驚慌。","notes":[]},{"n":3,"t":"不要讓任何人用甚麼法子欺騙你們，因為那日子以前必有叛教的事，並有那不法的人，那沉淪之子出現。","notes":[]},{"n":4,"t":"那抵擋者高抬自己超過一切稱為神明的，和一切受人敬拜的，甚至坐在神的殿裏，自稱為神。","notes":[]},{"n":5,"t":"我還在你們那裏的時候曾把這些事告訴你們，你們不記得嗎？","notes":[]},{"n":6,"t":"現在你們也知道那攔阻他的是甚麼，為要使他到了時機才出現。","notes":[]},{"n":7,"t":"因為那不法的隱祕已經運作，只是現在有一個阻擋的，要等到那阻擋的被除去才會發作，","notes":[]},{"n":8,"t":"那時這不法的人必出現，主耶穌要用口中的氣滅絕他，以自己來臨的光輝摧毀他。","notes":["「主耶穌」：有古卷是「主」。"]},{"n":9,"t":"這不法的人來，是靠撒但的運作，行各樣的異能、神蹟和一切虛假的奇事，","notes":[]},{"n":10,"t":"並且在那沉淪的人身上行各樣不義的詭詐，因為他們不領受愛真理的心，好讓他們得救。","notes":[]},{"n":11,"t":"故此，神就給他們一個引發錯誤的心，叫他們信從虛謊，","notes":[]},{"n":12,"t":"使一切不信真理、倒喜愛不義的人都被定罪。","notes":[]},{"n":13,"t":"主所愛的弟兄們哪，我們本該常為你們感謝神，因為他揀選你們為初熟的果子，使你們因信真道，又蒙聖靈感化成聖，得到拯救。","notes":["「他揀選你們為初熟的果子」：有古卷是「他從起初揀選了你們」。"],"heads":["被揀選接受救恩"]},{"n":14,"t":"為此，神藉著我們所傳的福音呼召你們，好得著我們主耶穌基督的榮光。","notes":[]},{"n":15,"t":"所以，弟兄們，你們要站立得穩，凡所領受的教導，無論是我們口傳的，是信上寫的，都要堅守。","notes":[]},{"n":16,"t":"願我們主耶穌基督自己，和那愛我們、開恩將永遠的安慰及美好的盼望賜給我們的父神，","notes":[]},{"n":17,"t":"安慰你們的心，並且在一切善行善言上堅固你們！","notes":[]}]},"3":{"heading":"為我們禱告","verses":[{"n":1,"t":"末了，弟兄們，請你們為我們禱告，好讓主的道快快傳開，得著榮耀，正如在你們中間一樣，","notes":[]},{"n":2,"t":"也讓我們能脫離無理和邪惡人的手，因為不是人人都有信仰。","notes":[]},{"n":3,"t":"但主是信實的，他要堅固你們，保護你們脫離那邪惡者。","notes":[]},{"n":4,"t":"我們靠主對你們有信心，你們現在遵行，以後也必遵行我們所吩咐的。","notes":[]},{"n":5,"t":"願主引導你們的心去愛神，並學基督的忍耐！","notes":[]},{"n":6,"t":"弟兄們，我們奉主耶穌基督的名吩咐你們，凡有弟兄懶散，不遵守我們所傳授的教導，要遠離他。","notes":[],"heads":["警戒懶散的人"]},{"n":7,"t":"你們自己知道該怎樣效法我們。因為我們在你們當中從未懶散過，","notes":[]},{"n":8,"t":"也從未白吃人的飯，倒是辛苦勞碌，晝夜做工，免得使你們中間有人受累。","notes":[]},{"n":9,"t":"這並不是因我們沒有權柄，而是要給你們作榜樣，好讓你們效法我們。","notes":[]},{"n":10,"t":"我們在你們那裏的時候曾吩咐你們，說若有人不肯做工，就不可吃飯。","notes":[]},{"n":11,"t":"因為我們聽說，在你們中間有人懶散，甚麼工都不做，反倒專管閒事。","notes":[]},{"n":12,"t":"我們靠主耶穌基督吩咐並勸戒這樣的人，要安分做工，自食其力。","notes":[]},{"n":13,"t":"弟兄們，你們行善不可喪志。","notes":[]},{"n":14,"t":"若有人不聽從我們這信上的話，要把他記下，不和他交往，使他自覺羞愧；","notes":[]},{"n":15,"t":"但不要把他當仇人，要勸他如勸弟兄。","notes":[]},{"n":16,"t":"願賜平安的主隨時隨事親自賜給你們平安！願主與你們眾人同在！","notes":["「平安」或譯「和平」﹔下同。"],"heads":["祝福"]},{"n":17,"t":"我—保羅親筆向你們問安。凡我的信都以此為記，我的筆跡就是這樣。","notes":[]},{"n":18,"t":"願我們主耶穌基督的恩惠與你們眾人同在！","notes":[]}]}},"1TI":{"1":{"heading":"問候","verses":[{"n":1,"t":"奉我們的救主神，和我們的盼望基督耶穌的命令，作基督耶穌使徒的保羅，","notes":[]},{"n":2,"t":"寫信給那因信主作我真兒子的提摩太。願恩惠、憐憫、平安從父神和我們主基督耶穌歸給你！","notes":["「平安」或譯「和平」。"]},{"n":3,"t":"我往馬其頓去的時候，曾勸你留在以弗所，好囑咐某些人不可傳別的教義，","notes":[],"heads":["警告虛偽的教義"]},{"n":4,"t":"也不要聽從無稽的傳說和冗長的家譜；這樣的事只會引起爭論，無助於神的計劃，這計劃是憑著信才能了解的。","notes":[]},{"n":5,"t":"但命令的目的就是愛；這愛是出於清潔的心、無愧的良心和無偽的信心。","notes":[]},{"n":6,"t":"有人偏離了這些而轉向空談，","notes":[]},{"n":7,"t":"想要作律法教師，卻不明白自己所講的是甚麼，也不知道所主張的是甚麼。","notes":[]},{"n":8,"t":"我們知道，只要人善用律法，律法是好的；","notes":[]},{"n":9,"t":"因為知道律法不是為義人訂立的，而是為不法和叛逆的，不虔誠和犯罪的，不聖潔和戀世俗的，弒父母和殺人的，","notes":[]},{"n":10,"t":"犯淫亂和親男色的，拐賣人口和說謊話的，並起假誓的，或是為任何違背健全教義的事訂立的。","notes":[]},{"n":11,"t":"這是按照可稱頌、榮耀之神交託我的福音說的。","notes":[]},{"n":12,"t":"我感謝那賜給我力量的我們的主基督耶穌，因為他認為我可信任，派我服事他。","notes":[],"heads":["感謝神的憐憫"]},{"n":13,"t":"我從前是褻瀆、迫害、侮慢神的人；然而我還蒙了憐憫，因為我是在不信、不明白的時候做的。","notes":[]},{"n":14,"t":"而且我們的主的恩典格外豐盛，使我在基督耶穌裏有信心和愛心。","notes":[]},{"n":15,"t":"這話可信，值得完全接受：「基督耶穌到世上來是要拯救罪人」，而在罪人中我是個罪魁。","notes":[]},{"n":16,"t":"然而，我蒙了憐憫，好讓基督耶穌在我這罪魁身上顯明他完全的忍耐，給後來信他得永生的人做榜樣。","notes":[]},{"n":17,"t":"願尊貴、榮耀歸給永世的君王，那不朽壞、看不見、獨一的神，直到永永遠遠。阿們！","notes":[]},{"n":18,"t":"我兒提摩太啊，我照從前指著你的預言把這命令交託你，使你能藉著這些預言打那美好的仗，","notes":[]},{"n":19,"t":"常存信心和無愧的良心。有些人丟棄良心，在信仰上觸了礁；","notes":[]},{"n":20,"t":"其中有許米乃和亞歷山大，我已經把他們交給撒但，讓他們學會不再褻瀆。","notes":[]}]},"2":{"heading":"有關禱告的指示","verses":[{"n":1,"t":"所以，我勸你，首先要為人人祈求、禱告、代求、感謝；","notes":[]},{"n":2,"t":"為君王和一切在位的，也要如此，使我們能夠敬虔端正地過平穩寧靜的生活。","notes":[]},{"n":3,"t":"這是好的，在我們的救主神面前可蒙悅納。","notes":[]},{"n":4,"t":"他願意人人得救，並得以認識真理。","notes":[]},{"n":5,"t":"因為只有一位神，在神和人之間也只有一位中保，是成為人的基督耶穌。","notes":[]},{"n":6,"t":"他獻上自己作人人的贖價；在適當的時候這事已經證實了。","notes":[]},{"n":7,"t":"我為此奉派作傳道，作使徒，在信仰和真理上作外邦人的教師。我說的是真話，不是說謊。","notes":[]},{"n":8,"t":"我希望男人舉起聖潔的手隨處禱告，不發怒，不爭論。","notes":[]},{"n":9,"t":"我也希望女人以端正、克制和合乎體統的服裝打扮自己，不以編髮、金飾、珍珠和名貴衣裳來打扮。","notes":[]},{"n":10,"t":"要有善行，這才與自稱為敬畏神的女人相稱。","notes":[]},{"n":11,"t":"女人要事事順服地安靜學習。","notes":[]},{"n":12,"t":"我不許女人教導，也不許她管轄男人，只要安靜。","notes":[]},{"n":13,"t":"因為亞當先被造，然後才是夏娃；","notes":[]},{"n":14,"t":"亞當並沒有受騙，而是女人受騙，陷在過犯裏。","notes":[]},{"n":15,"t":"然而，女人若持守信心、愛心，又聖潔克制，就必藉著生產而得救。","notes":[]}]},"3":{"heading":"監督的資格","verses":[{"n":1,"t":"「若有人想望監督的職分，他是在羨慕一件好事」，這話是可信的。","notes":[]},{"n":2,"t":"監督必須無可指責，只作一個婦人的丈夫，有節制、克己、端正，樂意接待外人，善於教導，","notes":[]},{"n":3,"t":"不酗酒，不打人；要溫和，不好鬥，不貪財。","notes":[]},{"n":4,"t":"要好好管理自己的家，使兒女順服，凡事莊重。","notes":[]},{"n":5,"t":"人若不知道管理自己的家，怎能照管神的教會呢？","notes":[]},{"n":6,"t":"剛信主的，不可作監督，恐怕他自高自大，落在魔鬼所受的懲罰裏。","notes":[]},{"n":7,"t":"監督也必須在教外有好名聲，免得被人毀謗，落在魔鬼的羅網裏。","notes":[]},{"n":8,"t":"同樣，執事也必須莊重，不一口兩舌，不好酒，不貪不義之財；","notes":[],"heads":["執事的資格"]},{"n":9,"t":"要存清白的良心固守信仰的奧祕。","notes":[]},{"n":10,"t":"這些人也要先受考驗，若沒有可責之處，才讓他們作執事。","notes":[]},{"n":11,"t":"同樣，女執事 也必須莊重，不說閒話，有節制，凡事忠心。","notes":["「女執事」或譯「他們的妻子」。"]},{"n":12,"t":"執事只作一個婦人的丈夫，要好好管兒女和自己的家。","notes":[]},{"n":13,"t":"因為善於作執事的，為自己得到美好的地位，並且無懼地堅信在基督耶穌裏的信仰。","notes":[]},{"n":14,"t":"我希望盡快到你那裏去，所以先把這些事寫給你；","notes":[],"heads":["敬虔的奧祕"]},{"n":15,"t":"倘若我延誤了，你也可以知道在神的家中該怎樣做。這家就是永生神的教會，真理的柱石和根基。","notes":[]},{"n":16,"t":"敬虔的奧祕是公認為偉大的：神在肉身顯現，被聖靈稱義，被天使看見，被傳於外邦，被世人信服，被接在榮耀裏。","notes":[]}]},"4":{"heading":"預言有人離棄信仰","verses":[{"n":1,"t":"聖靈明說，在末後的時期必有人離棄信仰，去聽信那誘惑人的邪靈和鬼魔的教訓。","notes":[]},{"n":2,"t":"這是出於撒謊者的假冒；這些人的良心如同被熱鐵烙了一般。","notes":[]},{"n":3,"t":"他們禁止嫁娶，又禁戒食物—就是神所造、讓那信而明白真理的人存感謝的心領受的。","notes":[]},{"n":4,"t":"神所造之物樣樣都是好的，若存感謝的心領受，沒有一樣是不可吃的，","notes":[]},{"n":5,"t":"都因神的話和人的祈禱而成為聖潔了。","notes":[]},{"n":6,"t":"你若把這些事提醒弟兄們，就是基督耶穌的好執事，在信仰的話語和你向來所服從的正確教義上得到了栽培。","notes":[],"heads":["基督耶穌的好執事"]},{"n":7,"t":"要棄絕那世俗的言語和老婦的無稽傳說。要在敬虔上操練自己：","notes":[]},{"n":8,"t":"因操練身體有些益處；但敬虔在各方面都有益，它有現今和未來的生命的應許。","notes":[]},{"n":9,"t":"這話可信，值得完全接受。","notes":[]},{"n":10,"t":"我們勞苦，努力正是為此，因為我們的指望在乎永生的神。他是人人的救主，更是信徒的救主。","notes":["有古卷是「遭受譴責」。"]},{"n":11,"t":"你要囑咐和教導這些事。","notes":[]},{"n":12,"t":"不可叫人小看你年輕，總要在言語、行為、愛心、信心、清潔上，都作信徒的榜樣。","notes":[]},{"n":13,"t":"要以宣讀聖經，勸勉，教導為念，直等到我來。","notes":[]},{"n":14,"t":"不要忽略你所得的恩賜，就是從前藉著預言、在眾長老按手的時候賜給你的。","notes":[]},{"n":15,"t":"這些事你要殷勤去做，並要在這些事上專心，讓眾人看出你的長進來。","notes":[]},{"n":16,"t":"要謹慎自己和自己的教導，要在這些事上恆心，因為這樣做，既能救自己，又能救聽你的人。","notes":[]}]},"5":{"heading":"對別人的本分","verses":[{"n":1,"t":"不可嚴責老年人，要勸他如同父親。要待年輕人如同弟兄，","notes":[]},{"n":2,"t":"年老婦女如同母親。要清清潔潔地待年輕婦女如同姊妹。","notes":[]},{"n":3,"t":"要尊敬真正守寡的婦人。","notes":[]},{"n":4,"t":"寡婦若有兒女，或有孫兒女，要讓兒孫先在自己家中學習行孝，報答親恩，因為這在神面前是可蒙悅納的。","notes":[]},{"n":5,"t":"獨居無靠的真寡婦只仰賴神，晝夜不住地祈求禱告。","notes":[]},{"n":6,"t":"但好宴樂的寡婦活著也算是死了。","notes":[]},{"n":7,"t":"這些事，你要囑咐她們，讓她們無可指責。","notes":[]},{"n":8,"t":"若有人不照顧親屬，尤其是自己家裏的人，就是背棄信仰，還不如不信的人。","notes":[]},{"n":9,"t":"寡婦登記，年齡必須在六十歲以上，只作一個丈夫的妻子，","notes":[]},{"n":10,"t":"又有行善的名聲，就如養育兒女，收留外人，洗聖徒的腳，救濟遭難的人，竭力行各樣善事。","notes":[]},{"n":11,"t":"至於年輕的寡婦，你要拒絕登記，因為她們情慾衝動、背棄基督的時候，就想嫁人，","notes":[]},{"n":12,"t":"她們因廢棄了當初所許的願而被定罪。","notes":[]},{"n":13,"t":"同時，她們又學了懶惰，習慣於挨家閒逛；不但懶惰，而且說長道短，好管閒事，說些不該說的話。","notes":[]},{"n":14,"t":"所以，我希望年輕的寡婦嫁人，生養兒女，治理家務，不讓敵人有辱罵的把柄，","notes":[]},{"n":15,"t":"因為已經有一些人轉去隨從撒但了。","notes":[]},{"n":16,"t":"信主的婦女若有親戚是寡婦，要救濟她們，不可拖累教會，好使教會能救濟真正無助的寡婦。","notes":[]},{"n":17,"t":"善於督導教會的長老，尤其是勤勞講道教導人的，應該得到加倍的敬奉。","notes":[]},{"n":18,"t":"因為經上說：「牛在踹穀的時候，不可籠住牠的嘴」；又說：「工人得工資是應當的。」","notes":[]},{"n":19,"t":"有控告長老的案件，非有兩三個證人就不要受理。","notes":[]},{"n":20,"t":"繼續犯罪的人，要在眾人面前責備他，使其餘的人也有所懼怕。","notes":[]},{"n":21,"t":"我在神、基督耶穌和蒙揀選的天使面前囑咐你要遵守這些話，不可存成見，做事也不可偏心。","notes":[]},{"n":22,"t":"不可急於給人行按手禮；也不可在別人的罪上有份，要保守自己純潔。","notes":[]},{"n":23,"t":"為了你的胃，又常患病，不要只喝水，要稍微喝點酒。","notes":[]},{"n":24,"t":"有些人的罪是明顯的，已先受審判了；有些人的罪是隨後跟著來。","notes":[]},{"n":25,"t":"同樣，善行也有明顯的，就是那不明顯的也不能隱藏。","notes":[]}]},"6":{"heading":"假教導和真財富","verses":[{"n":1,"t":"凡負軛作奴隸的，要認為自己的主人配受各樣的尊敬，免得神的名和教導被人褻瀆。","notes":[]},{"n":2,"t":"奴隸若有信主的主人，不可因他是主內弟兄就輕看他們，更要越發服侍他們，因為得到服侍的益處的正是信徒，是蒙愛的人。你要教導和勸勉這些事。","notes":[]},{"n":3,"t":"若有人傳別的教義，不符合我們主耶穌基督純正的話語與合乎敬虔的教導，","notes":[]},{"n":4,"t":"他是自高自大，一無所知，專好爭辯，擅於舌戰，因而生出嫉妒、紛爭、毀謗、惡意猜疑，","notes":[]},{"n":5,"t":"和心術不正與喪失真理的人不停地爭吵，以敬虔為得利的門路。","notes":[]},{"n":6,"t":"其實，敬虔加上知足就是大利。","notes":[]},{"n":7,"t":"因為我們沒有帶甚麼到世上來，也不能帶甚麼去；","notes":[]},{"n":8,"t":"只要有衣有食，我們就該知足。","notes":[]},{"n":9,"t":"但那些想要發財的人就陷在誘惑、羅網和許多無知有害的慾望中，使人沉淪，以致敗壞和滅亡。","notes":[]},{"n":10,"t":"貪財是萬惡之根。有人因貪戀錢財而背離信仰，用許多愁苦把自己刺透了。","notes":[]},{"n":11,"t":"但你這屬神的人哪，要逃避這些事；要追求公義、敬虔、信心、愛心、忍耐、溫柔。","notes":[],"heads":["美好的仗"]},{"n":12,"t":"你要為信仰打那美好的仗；要持定永生，你為此被召，也已經在許多見證人面前作了那美好的見證。","notes":[]},{"n":13,"t":"我在那賜生命給萬物的神面前，並在向本丟‧彼拉多作過那美好見證的基督耶穌面前囑咐你：","notes":["有古卷沒有「你」。"]},{"n":14,"t":"要守這命令，毫不玷污，無可指責，直到我們的主耶穌基督顯現。","notes":[]},{"n":15,"t":"到了適當的時候都要顯明出來：他是那可稱頌、獨一的權能者，萬王之王，萬主之主，","notes":[]},{"n":16,"t":"就是那獨一不死、住在人不能靠近的光裏，是人未曾看見，也是不能看見的。願尊貴和永遠的權能都歸給他。阿們！","notes":[]},{"n":17,"t":"至於那些今世富足的人，你要囑咐他們不要自高，也不要倚賴靠不住的錢財；要倚靠那厚賜萬物給我們享受的神。","notes":[]},{"n":18,"t":"又要囑咐他們行善，在好事上富足，甘心施捨，樂意分享，","notes":[]},{"n":19,"t":"為自己積存財富，而為將來打美好的根基，好使他們能把握那真正的生命。","notes":[]},{"n":20,"t":"提摩太啊，要持守所給你的託付。要躲避世俗的空談和那假冒知識的矛盾言論。","notes":[]},{"n":21,"t":"有人自稱有這知識而偏離了信仰。願恩惠與你們同在！","notes":[]}]}},"2TI":{"1":{"heading":"問候","verses":[{"n":1,"t":"奉神旨意，按照基督耶穌裏所應許的生命，作基督耶穌使徒的保羅，","notes":[]},{"n":2,"t":"寫信給我親愛的兒子提摩太。願恩惠、憐憫、平安從父神和我們的主基督耶穌歸給你！","notes":["「平安」或譯「和平」。"]},{"n":3,"t":"我感謝神，就是我接續祖先用純潔的良心所事奉的神，在祈禱中晝夜不停地想念你。","notes":[],"heads":["忠於福音"]},{"n":4,"t":"我一想起你的眼淚，就急切想見你，好讓我滿心快樂。","notes":[]},{"n":5,"t":"我記得你無偽的信心，這信心先存在你外祖母羅以和你母親友妮基的心裏，我深信也存在你的心裏。","notes":[]},{"n":6,"t":"為這緣故，我提醒你要把神藉著我按手所給你的恩賜再如火挑旺起來。","notes":[]},{"n":7,"t":"因為神賜給我們的不是膽怯的心，而是剛強、仁愛、自制的心。","notes":[]},{"n":8,"t":"所以，不要以給我們的主作見證為恥，也不要以我這為主被囚的為恥；總要靠著神的大能，與我為福音同受苦難。","notes":[]},{"n":9,"t":"神救了我們，以聖召召我們，不是按我們的行為，而是按他的旨意和恩典；這恩典是萬古之先在基督耶穌裏賜給我們的，","notes":[]},{"n":10,"t":"但如今藉著我們的救主基督耶穌的顯現已經表明出來；他把死廢去，藉著福音，將不朽的生命彰顯出來。","notes":[]},{"n":11,"t":"我為這福音奉派作傳道，作使徒，作教師。","notes":[]},{"n":12,"t":"為這緣故，我也受這些苦難。然而，我不以為恥，因為我知道我所信的是誰，也深信他能保全他所交託我的，直到那日。","notes":["「他所交託我的」或譯「我所信託他的」。"]},{"n":13,"t":"你從我聽到那健全的言論，要用在基督耶穌裏的信心和愛心常常守著，作為規範。","notes":[]},{"n":14,"t":"你要靠著那住在我們裏面的聖靈，牢牢守住所交託給你那美好的事。","notes":[]},{"n":15,"t":"你知道，所有在亞細亞的人都離棄了我，其中有腓吉路和黑摩其尼。","notes":[]},{"n":16,"t":"願主憐憫阿尼色弗一家的人，因為他屢次令我欣慰。他不以我的鐵鏈為恥，","notes":[]},{"n":17,"t":"反而一到羅馬就急切尋找我，並且找到了。","notes":[]},{"n":18,"t":"願主使他在那日能蒙主的憐憫。他在以弗所怎樣多服事我，你是清楚知道的。","notes":[]}]},"2":{"heading":"基督耶穌的精兵","verses":[{"n":1,"t":"我兒啊，你要在基督耶穌的恩典上剛強起來。","notes":[]},{"n":2,"t":"你在許多見證人面前聽見我所教導的，也要交託給那忠心而又能教導別人的人。","notes":[]},{"n":3,"t":"你要和我同受苦難，作基督耶穌的精兵。","notes":[]},{"n":4,"t":"凡當兵的，不讓世務纏身，好使那招他當兵的人喜悅。","notes":[]},{"n":5,"t":"運動員在比賽的時候，不按規則就不能得冠冕。","notes":[]},{"n":6,"t":"勤勞的農夫理當先得糧食。","notes":[]},{"n":7,"t":"我所說的話，你要考慮，因為主必在凡事上給你聰明。","notes":[]},{"n":8,"t":"要記得耶穌基督，他是大衛的後裔，從死人中復活；這就是我所傳的福音。","notes":[]},{"n":9,"t":"我為這福音受苦難，甚至像犯人一樣被捆綁，然而神的話沒有被捆綁。","notes":[]},{"n":10,"t":"所以，我為了選民事事忍耐，為使他們也能得到那在基督耶穌裏的救恩和永遠的榮耀。","notes":[]},{"n":11,"t":"這話是可信的：我們若與基督同死，也必與他同活；","notes":[]},{"n":12,"t":"我們若忍耐到底，也必和他一同作王。我們若不認他，他也必不認我們；","notes":[]},{"n":13,"t":"我們縱然失信，他仍是可信的，因為他不能否認自己。","notes":[]},{"n":14,"t":"你要向眾人提醒這些事，在神面前囑咐他們不可在言詞上爭辯；這是沒有益處的，只能傷害聽的人。","notes":["「神」：有古卷是「主」。"],"heads":["無愧的工人"]},{"n":15,"t":"你當竭力在神面前作一個經得起考驗、無愧的工人，按著正意講解真理的話。","notes":[]},{"n":16,"t":"要遠避世俗的空談，因為這等空談會使人進到更不敬虔的地步。","notes":[]},{"n":17,"t":"他們的話如同毒瘡越爛越大；其中有許米乃和腓理徒，","notes":[]},{"n":18,"t":"他們偏離了真理，說復活的事已過去，敗壞了好些人的信心。","notes":[]},{"n":19,"t":"然而，神堅固的根基屹立不移；上面有這印記說：「主認得他自己的人」，又說：「凡稱呼主名的人總要離開不義。」","notes":[]},{"n":20,"t":"大戶人家不但有金器銀器，也有木器瓦器；有作為貴重之用的，有作為卑賤之用的。","notes":[]},{"n":21,"t":"人若自潔，脫離卑賤的事，必成為貴重的器皿，成為聖潔，合乎主用，預備行各樣的善事。","notes":[]},{"n":22,"t":"你要逃避年輕人的私慾，同那以純潔的心求告主的人追求公義、信實、仁愛、和平。","notes":[]},{"n":23,"t":"但要棄絕那愚拙無知的辯論，因為你知道這等事只會引起爭辯。","notes":[]},{"n":24,"t":"主的僕人不可爭辯，只要溫和待人，善於教導，恆心忍耐，","notes":[]},{"n":25,"t":"用溫柔勸導反對的人。也許神會給他們悔改的心能明白真理，","notes":[]},{"n":26,"t":"讓他們這些已被魔鬼擄去順從他詭計的人能醒悟過來，脫離他的羅網。","notes":[]}]},"3":{"heading":"末世的人性","verses":[{"n":1,"t":"你該知道，末世必有艱難的日子來到。","notes":[]},{"n":2,"t":"那時人會專愛自己，貪愛錢財，自誇，狂傲，毀謗，違背父母，忘恩負義，心不聖潔，","notes":[]},{"n":3,"t":"沒有親情，抗拒和解，好說讒言，不能節制，性情兇暴，不愛良善，","notes":[]},{"n":4,"t":"賣主賣友，任意妄為，自高自大，愛好宴樂，不愛神，","notes":[]},{"n":5,"t":"有敬虔的外貌，卻背棄了敬虔的實質，這等人你要避開。","notes":[]},{"n":6,"t":"他們當中有人潛入別人家裏，操縱無知的婦女；這些婦女被罪惡壓制，被各樣的私慾引誘，","notes":[]},{"n":7,"t":"雖然常常學習，終久無法達到明白真理的地步。","notes":[]},{"n":8,"t":"從前雅尼和佯庇怎樣反對摩西，這等人也怎樣抵擋真理；他們的心地敗壞，信仰經不起考驗。","notes":[]},{"n":9,"t":"然而，他們沒有進步，因為他們的愚昧必在眾人面前顯露出來，像那兩人一樣。","notes":[]},{"n":10,"t":"但你已經追隨了我的教導、行為、志向、信心、寬容、愛心、忍耐，","notes":[],"heads":["對提摩太的最後指示"]},{"n":11,"t":"以及我在安提阿、以哥念、路司得所遭遇的迫害和苦難。我忍受了何等的迫害！但從這一切苦難中，主都把我救了出來。","notes":[]},{"n":12,"t":"其實，凡立志在基督耶穌裏敬虔度日的，也都將受迫害。","notes":[]},{"n":13,"t":"只是作惡的和騙人的將變本加厲，迷惑人也被人迷惑。","notes":[]},{"n":14,"t":"至於你，你要持守所學習的和所確信的，因為你知道是跟誰學的，","notes":[]},{"n":15,"t":"並且知道你從小明白聖經，這聖經能使你因在基督耶穌裏的信有得救的智慧。","notes":["「因在基督耶穌裏的信」或譯「因信基督耶穌」。"]},{"n":16,"t":"聖經都是神所默示的，於教訓、督責、使人歸正、教導人學義都是有益的，","notes":["「聖經都是神所默示的」或譯「凡神所默示的聖經」。"]},{"n":17,"t":"叫屬神的人得以完全，預備行各樣的善事。","notes":[]}]},"4":{"heading":"最後的吩咐","verses":[{"n":1,"t":"我在神面前，並在將來審判活人死人的基督耶穌面前，憑著他的顯現和他的國度鄭重地勸戒你：","notes":[]},{"n":2,"t":"務要傳道；無論得時不得時總要專心，並以百般的忍耐和各樣的教導責備人，警戒人，勸勉人。","notes":[]},{"n":3,"t":"因為時候將到，那時人會厭煩健全的教導，耳朵發癢，就隨心所欲地增添好些教師，","notes":[]},{"n":4,"t":"並且掩耳不聽真理，偏向無稽的傳說。","notes":[]},{"n":5,"t":"至於你，凡事要謹慎，忍受苦難，做傳福音的工作，盡你的職分。","notes":[]},{"n":6,"t":"至於我，我已經被澆獻，離世的時候到了。","notes":[]},{"n":7,"t":"那美好的仗我已經打過了，當跑的路我已經跑盡了，該信的道我已經守住了。","notes":[]},{"n":8,"t":"從此以後，有公義的冠冕為我存留，就是按著公義審判的主到了那日要賜給我的；不但賜給我，也賜給凡愛慕他顯現的人。","notes":[]},{"n":9,"t":"你要趕緊到我這裏來。","notes":[]},{"n":10,"t":"因為底馬貪愛現今的世界，已經離棄我，往帖撒羅尼迦去了；革勒士往加拉太去；提多往撻馬太去；","notes":[]},{"n":11,"t":"只有路加在我這裏。你來的時候把馬可帶來，因為他在服事上於我有益。","notes":["「服事」或譯「傳道」。"]},{"n":12,"t":"我已經打發推基古往以弗所去。","notes":[]},{"n":13,"t":"我在特羅亞留給加布的那件外衣，你來的時候要帶來，那些書也帶來，特別是那幾卷羊皮的書。","notes":[]},{"n":14,"t":"銅匠亞歷山大多方害我；主必照他所行的報應他。","notes":[]},{"n":15,"t":"你也要防備他，因為他極力抗拒我們的話。","notes":[]},{"n":16,"t":"我初次上訴時，沒有人前來幫助，竟都離棄了我，但願這罪不歸在他們身上。","notes":[]},{"n":17,"t":"惟有主站在我身邊，加給我力量，使我能把福音完整地傳開，讓所有的外邦人都聽見；我也從獅子口裏被救出來。","notes":[]},{"n":18,"t":"主必救我脫離一切的兇惡，也必救我進他的天國。願榮耀歸給他，直到永永遠遠。阿們！","notes":[]},{"n":19,"t":"請向百基拉、亞居拉和阿尼色弗一家的人問安。","notes":[],"heads":["問安與祝福"]},{"n":20,"t":"以拉都在哥林多住下了。特羅非摩病了，我把他留在米利都。","notes":[]},{"n":21,"t":"你要趕緊在冬天以前到我這裏來。友布羅、布田、利奴、革老底亞和眾弟兄都向你問安。","notes":[]},{"n":22,"t":"願主與你的靈同在！願恩惠與你們同在！","notes":[]}]}},"TIT":{"1":{"heading":"問候","verses":[{"n":1,"t":"神的僕人、耶穌基督的使徒保羅，為了使神的選民信從與認識合乎敬虔的真理—","notes":[]},{"n":2,"t":"這真理是在盼望那無謊言的神在萬古之先所應許的永生，","notes":[]},{"n":3,"t":"到了適當的時機，藉著傳揚福音，把他的道顯明了；這傳揚的責任是按著我們的救主神的命令交託給我的—","notes":[]},{"n":4,"t":"我寫信給在共同的信仰上作我真兒子的提多。願恩惠、平安從父神和我們的救主基督耶穌歸給你！","notes":["「平安」或譯「和平」。"]},{"n":5,"t":"我從前把你留在克里特，是要你將那沒有辦完的事都辦妥，又照我所吩咐你的，在各城設立長老。","notes":[],"heads":["提多在克里特的工作"]},{"n":6,"t":"若有無可指責的人，只作一個婦人的丈夫，兒女也是信主的，沒有人告他們放蕩，不受約束，就可以設立。","notes":[]},{"n":7,"t":"監督既然是神的管家，必須無可指責、不自負、不暴躁、不酗酒、不好鬥、不貪財；","notes":[]},{"n":8,"t":"卻要樂意接待外人、好善、克己、正直、聖潔、節制，","notes":[]},{"n":9,"t":"堅守合乎教義的可靠之道，就能將健全的教導勸勉人，又能駁倒爭辯的人。","notes":[]},{"n":10,"t":"因為也有許多人不受約束，說空話欺哄人，尤其是那些奉割禮的人。","notes":[]},{"n":11,"t":"這些人的口必須堵住，因為他們貪不義之財，將不該教導的事教導人，敗壞人的全家。","notes":[]},{"n":12,"t":"克里特人中有一個本地的先知說：「克里特人常說謊話，是惡獸，貪吃懶做。」","notes":[]},{"n":13,"t":"這個見證是真的。為這緣故，你要嚴厲地責備他們，使他們在信仰上健全。","notes":[]},{"n":14,"t":"不要聽猶太人無稽的傳說和背棄真理之人的命令。","notes":[]},{"n":15,"t":"在潔淨的人，凡物都潔淨；在污穢不信的人，甚麼都不潔淨，連心地和天良也都污穢了。","notes":[]},{"n":16,"t":"他們宣稱認識神，卻在行為上否認他；他們是可憎惡的，是悖逆的，不配做任何好事。","notes":[]}]},"2":{"heading":"健全的教導","verses":[{"n":1,"t":"至於你，你所講的總要合乎那健全的教導。","notes":[]},{"n":2,"t":"勸老年人要有節制、端正、克己，在信心、愛心、耐心上都要健全。","notes":[]},{"n":3,"t":"又要勸年長的婦女在操守上恭正，不說讒言，不作酒的奴隸，用善道教導人，","notes":[]},{"n":4,"t":"好指教年輕的婦女愛丈夫，愛兒女，","notes":[]},{"n":5,"t":"克己，貞潔，理家，善良，順服自己的丈夫，免得神的道被毀謗。","notes":[]},{"n":6,"t":"同樣，要勸年輕人凡事克己。","notes":[]},{"n":7,"t":"你要顯出自己是好行為的榜樣，在教導上要正直、莊重，","notes":[]},{"n":8,"t":"言語健全，無可指責，使那反對的人，因說不出我們有甚麼不好而自覺羞愧。","notes":[]},{"n":9,"t":"要勸僕人順服自己的主人，凡事討他的喜悅，不可頂撞他，","notes":[]},{"n":10,"t":"不可私竊財物；要凡事顯出完美的忠誠，好事事都能榮耀我們救主神的教導。","notes":[]},{"n":11,"t":"因為，神救眾人的恩典已經顯明出來，","notes":[]},{"n":12,"t":"訓練我們除去不敬虔的心和世俗的情慾，在今世過克己、正直、敬虔的生活，","notes":[]},{"n":13,"t":"等候福樂的盼望，並等候至大的神和我們的救主耶穌基督的榮耀顯現。","notes":["「神和我們的救主」或譯「神—我們的救主」。"]},{"n":14,"t":"他為我們的緣故捨己，為了要贖我們脫離一切罪惡，又潔淨我們作他自己的子民，熱心為善。","notes":[]},{"n":15,"t":"這些事你要講明，要充分運用你的職權勸勉人，責備人。不要讓任何人輕看你。","notes":[]}]},"3":{"heading":"熱心行善","verses":[{"n":1,"t":"你要提醒眾人，叫他們順服執政的、掌權的，要服從，預備行各樣善事。","notes":[]},{"n":2,"t":"不要毀謗，不要爭吵，要和氣，對眾人總要顯出溫柔。","notes":[]},{"n":3,"t":"我們從前也是無知、悖逆、受迷惑，作各樣私慾和宴樂的奴隸，在惡毒、嫉妒中度日，是可恨的，而且彼此相恨。","notes":[]},{"n":4,"t":"但到了我們救主神的恩慈和慈愛顯明的時候，","notes":[]},{"n":5,"t":"他救了我們，並不是因我們自己所行的義，而是照他的憐憫，藉著重生的洗和聖靈的更新。","notes":[]},{"n":6,"t":"聖靈就是神藉著我們的救主耶穌基督厚厚地澆灌在我們身上的，","notes":[]},{"n":7,"t":"好讓我們因他的恩得稱為義，可以憑著永生的盼望成為後嗣。","notes":["「可以憑著…成為後嗣」或譯「可以憑著…承受永生」。"]},{"n":8,"t":"這話是可信的。我願你堅持這些事，使那些已信神的人留心行善。這都是美好且對人有益的。","notes":["「行善」或譯「做正經的事業」；14節同。"]},{"n":9,"t":"要遠避愚拙的辯論、家譜、紛爭和因律法而起的爭辯，因為這都是虛妄無益的。","notes":[]},{"n":10,"t":"分門結黨的人，警戒過一兩次後就要拒絕跟他來往；","notes":[]},{"n":11,"t":"因為你知道這樣的人已經背道，常常犯罪，自己定自己的罪了。","notes":[]},{"n":12,"t":"我打發亞提馬或推基古到你那裏去的時候，你要趕緊往尼哥坡里來見我，因為我已經決定在那裏過冬。","notes":[],"heads":["指示和問安"]},{"n":13,"t":"你要趕緊給西納律師和亞波羅送行，讓他們沒有缺乏。","notes":[]},{"n":14,"t":"我們的人也該學習行善，幫助有迫切需要的人，這樣才不會不結果子。","notes":[]},{"n":15,"t":"跟我同在一起的人都向你問安。請代向在信仰上愛我們的人問安。願恩惠與你們眾人同在！","notes":[]}]}},"PHM":{"1":{"heading":"問候","verses":[{"n":1,"t":"為基督耶穌被囚的保羅，同弟兄提摩太，寫信給我們所親愛的同工腓利門、","notes":[]},{"n":2,"t":"亞腓亞姊妹，和我們的戰友亞基布，以及在你家裏的教會。","notes":[]},{"n":3,"t":"願恩惠、平安從我們的父神和主耶穌基督歸給你們！","notes":["「平安」或譯「和平」。"]},{"n":4,"t":"我在禱告中記念你的時候，常為你感謝我的神，","notes":[],"heads":["腓利門的愛心和信心"]},{"n":5,"t":"因聽說你對眾聖徒的愛心，和你對主耶穌的信心。","notes":[]},{"n":6,"t":"願你與人分享信心的時候，能產生功效，讓人知道我們所行的各樣善事都是為基督做的。","notes":["有古卷是「你們」。"]},{"n":7,"t":"弟兄啊，由於你的愛心，我得到極大的快樂和安慰，因為眾聖徒的心從你得到舒暢。","notes":[]},{"n":8,"t":"雖然我靠著基督能放膽吩咐你做該做的事，","notes":[],"heads":["保羅為阿尼西謀請求"]},{"n":9,"t":"可是像我這上了年紀的保羅，現在又是為基督耶穌被囚的，寧可憑著愛心求你，","notes":[]},{"n":10,"t":"就是為我在捆鎖中所生的兒子阿尼西謀求你。","notes":["「阿尼西謀」：此名就是「有益處」的意思。"]},{"n":11,"t":"從前他與你沒有益處，但如今與你我都有益處。","notes":[]},{"n":12,"t":"我現在打發他回到你那裏去，他是我心肝。","notes":[]},{"n":13,"t":"我本來有意將他留下，在我為福音所受的捆鎖中替你伺候我。","notes":[]},{"n":14,"t":"但不知道你的意見，我不願意這樣做，好使你的善行不是出於勉強，而是出於自願。","notes":[]},{"n":15,"t":"他暫時離開你，也許是要讓你永遠得著他，","notes":[]},{"n":16,"t":"不再是奴隸，而是高過奴隸，是親愛的弟兄；對我確實如此，何況對你呢！無論在肉身或在主裏更是如此。","notes":[]},{"n":17,"t":"所以，你若以我為同伴，就接納他，如同接納我一樣。","notes":[]},{"n":18,"t":"他若虧負你，或欠你甚麼，都算在我的賬上吧，","notes":[]},{"n":19,"t":"我必償還。這是我—保羅親筆寫的。我並不用對你說，甚至你自己也虧欠我呢！","notes":[]},{"n":20,"t":"弟兄啊，希望你使我在主裏因你得益處，讓我的心在基督裏得到舒暢。","notes":[]},{"n":21,"t":"我寫信給你，深信你必順服，知道你所要做的，必過於我所說的。","notes":[]},{"n":22,"t":"此外，還請給我預備住處，因為我盼望藉著你們的禱告，必蒙恩回到你們那裏去。","notes":[]},{"n":23,"t":"為基督耶穌與我一同坐監的以巴弗問候你。","notes":[],"heads":["最後的問安"]},{"n":24,"t":"我的同工馬可、亞里達古、底馬、路加也都問候你。","notes":[]},{"n":25,"t":"願主耶穌基督的恩與你們的靈同在。","notes":["有古卷加「我們」。","有古卷加「阿們！」"]}]}},"HEB":{"1":{"heading":"神藉著他兒子說話","verses":[{"n":1,"t":"古時候，神藉著眾先知多次多方向列祖說話，","notes":[]},{"n":2,"t":"末世，藉著他兒子向我們說話，又立他為承受萬有的，也藉著他創造宇宙。","notes":[]},{"n":3,"t":"他是神榮耀的光輝，是神本體的真像，常用他大能的命令托住萬有。他洗淨了人的罪，就坐在高天至大者的右邊。","notes":[]},{"n":4,"t":"他所承受的名比天使的名更尊貴，所以他遠比天使崇高。","notes":[],"heads":["神的兒子遠超過天使"]},{"n":5,"t":"神曾對哪一個天使說過：「你是我的兒子；我今日生了你」？又說過：「我要作他的父；他要作我的子」呢？","notes":[]},{"n":6,"t":"再者，神引領他長子進入世界的時候，說：「神的使者都要拜他。」","notes":["「長子」或譯「首生者」。"]},{"n":7,"t":"關於使者，他說：「神以風為使者，以火焰為僕役。」","notes":[]},{"n":8,"t":"關於子，他卻說：「神啊，你的寶座是永永遠遠的；你國度的權杖是正直的權杖。","notes":[]},{"n":9,"t":"你喜愛公義，恨惡罪惡；所以神，就是你的神，用喜樂油膏你，勝過膏你的同伴。」","notes":[]},{"n":10,"t":"他又說：「主啊，你起初立了地的根基，天也是你手所造的。","notes":[]},{"n":11,"t":"天地都會消滅，你卻長存；天地都會像衣服漸漸舊了；","notes":[]},{"n":12,"t":"你要將天地捲起來，像捲一件外衣，天地像衣服都會改變。你卻永不改變；你的年數沒有窮盡。」","notes":[]},{"n":13,"t":"神曾對哪一個天使說：「你坐在我的右邊，等我使你的仇敵作你的腳凳」？","notes":[]},{"n":14,"t":"眾天使不都是事奉的靈，奉差遣為那將要承受救恩的人服務的嗎？","notes":[]}]},"2":{"heading":"偉大的救恩","verses":[{"n":1,"t":"所以，我們必須越發注意所聽見的道，免得我們隨流失去。","notes":[]},{"n":2,"t":"既然那藉著天使所傳的話是確定的，凡違背不聽從的，都受了該受的報應；","notes":[]},{"n":3,"t":"我們若忽略這麼大的救恩，怎能逃避呢？這拯救起先是主親自講的，後來是聽見的人給我們證實了。","notes":[]},{"n":4,"t":"神又按自己的旨意，更用神蹟奇事、百般的異能，和聖靈所給的恩賜，與他們一同作見證。","notes":[]},{"n":5,"t":"我們所說將來的世界，神沒有交給天使管轄。","notes":[],"heads":["救恩的元帥"]},{"n":6,"t":"但有人在某處證明說：「人算甚麼，你竟顧念他；世人算甚麼，你竟眷顧他。","notes":[]},{"n":7,"t":"你使他暫時比天使微小，賜他榮耀尊貴為冠冕，你派他管理你手所造的，","notes":["或譯「你使他比天使微小一點」。"]},{"n":8,"t":"使萬物都服在他的腳下。」既然使萬物都服他，就沒有剩下一樣不服他的了。只是如今我們還不見萬物都服他；","notes":["有古卷是「既然使萬物都降服」。"]},{"n":9,"t":"惟獨見那成為暫時比天使微小的耶穌，因為受了死的痛苦，得了尊貴榮耀為冠冕，好使他因著神的恩，為人人經歷了死亡。","notes":[]},{"n":10,"t":"原來那為萬物所屬、為萬物所本的，為要領許多兒子進入榮耀，使救他們的元帥因受苦難而得以完全，本是合宜的。","notes":[]},{"n":11,"t":"因那使人成聖的，和那些得以成聖的，都是出於一。為這緣故，他稱他們為弟兄也不以為恥，","notes":[]},{"n":12,"t":"說：「我要將你的名傳給我的弟兄，在會眾中我要頌揚你。」","notes":[]},{"n":13,"t":"他又說：「我要依賴他。」他又說：「看哪！我與神所給我的兒女都在這裏。」","notes":[]},{"n":14,"t":"既然兒女同有血肉之軀，他也照樣親自成了血肉之軀，為能藉著死敗壞那掌管死權的，就是魔鬼，","notes":[]},{"n":15,"t":"並要釋放那些一生因怕死而作奴隸的人。","notes":[]},{"n":16,"t":"誠然，他並沒有幫助天使，而是幫助了亞伯拉罕的後裔。","notes":[]},{"n":17,"t":"所以，他凡事應當與他的弟兄相同，為要在神的事上成為慈悲忠信的大祭司，為百姓的罪獻上贖罪祭。","notes":[]},{"n":18,"t":"既然他自己被試探而受苦，他能幫助被試探的人。","notes":[]}]},"3":{"heading":"耶穌超越摩西","verses":[{"n":1,"t":"同蒙天召的聖潔弟兄啊，要思想我們所宣認為使者、為大祭司的耶穌；","notes":[]},{"n":2,"t":"他向指派他的盡忠，如同摩西向神的全家盡忠一樣。","notes":["有古卷沒有「全」。"]},{"n":3,"t":"他比摩西配得更多的榮耀，好像建造房屋的人比房屋更尊榮；","notes":[]},{"n":4,"t":"因為房屋都必有人建造，但建造萬物的是神。","notes":[]},{"n":5,"t":"摩西作為僕人，向神的全家盡忠，為將來要談論的事作證；","notes":[]},{"n":6,"t":"但是基督作為兒子，治理神的家。我們若堅持因盼望而有的膽量和誇耀，我們就是他的家了。","notes":[]},{"n":7,"t":"所以，正如聖靈所說：「今日，你們若聽他的話，","notes":[],"heads":["神子民的安息"]},{"n":8,"t":"就不可硬著心，像在背叛之時，就如在曠野受試探之日。","notes":[]},{"n":9,"t":"在那裏，你們的祖宗試探我，並且觀看我的作為，","notes":[]},{"n":10,"t":"有四十年之久。所以，我厭煩那世代，說：他們的心常常迷糊，竟不知道我的道路！","notes":[]},{"n":11,"t":"我在怒中起誓：他們斷不可進入我的安息！」","notes":[]},{"n":12,"t":"弟兄們，你們要謹慎，免得你們中間有人存著邪惡不信的心，離棄了永生的神。","notes":[]},{"n":13,"t":"總要趁著還有今日，天天彼此相勸，免得你們中間有人被罪迷惑，心腸剛硬了。","notes":[]},{"n":14,"t":"只要我們將起初確實的信心堅持到底，就在基督裏有份了。","notes":[]},{"n":15,"t":"經上說：「今日，你們若聽他的話，就不可硬著心，像在背叛之時。」","notes":[]},{"n":16,"t":"聽見他而又背叛他的是誰呢？豈不是跟著摩西從埃及出來的眾人嗎？","notes":[]},{"n":17,"t":"神向誰發怒四十年之久呢？豈不是那些犯罪而陳屍在曠野的人嗎？","notes":[]},{"n":18,"t":"他向誰起誓，不容他們進入他的安息呢？豈不是向那些不信從的人嗎？","notes":[]},{"n":19,"t":"這樣看來，他們不能進入安息是因為不信的緣故了。","notes":[]}]},"4":{"heading":"大祭司耶穌","verses":[{"n":1,"t":"所以，既然進入他安息的應許依舊存在，我們就該存畏懼的心，免得我們 中間有人似乎沒有得到安息。","notes":["「我們」：原文直譯「你們」。"]},{"n":2,"t":"因為的確有福音傳給我們像傳給他們一樣；只是所聽見的道對他們無益，因為他們沒有以信心與所聽見的道配合。","notes":[]},{"n":3,"t":"但我們已經信的人進入安息，正如神所說：「我在怒中起誓：他們斷不可進入我的安息！」其實造物之工，從創世以來已經完成了。","notes":[]},{"n":4,"t":"論到第七日，有一處說：「到第七日，神就歇了他一切工作。」","notes":[]},{"n":5,"t":"又有一處說：「他們斷不可進入我的安息！」","notes":[]},{"n":6,"t":"既有這安息保留著讓一些人進入，那些先前聽見福音的人，因不信從而不得進去，","notes":[]},{"n":7,"t":"所以神多年後藉著大衛的書，又定了一天—「今日」，如以上所引的說：「今日，你們若聽他的話，就不可硬著心。」","notes":[]},{"n":8,"t":"若是約書亞已使他們享了安息，後來神就不會再提別的日子了。","notes":[]},{"n":9,"t":"這樣看來，另有一安息日的安息為神的子民保留著。","notes":[]},{"n":10,"t":"因為那些進入安息的，也是歇了自己的工作，正如神歇了他的工作一樣。","notes":[]},{"n":11,"t":"所以，我們務必竭力進入那安息，免得有人學了不順從而跌倒了。","notes":[]},{"n":12,"t":"神的道是活潑的，是有功效的，比一切兩刃的劍更鋒利，甚至魂與靈、骨節與骨髓，都能刺入、剖開，連心中的思念和主意都能辨明。","notes":[]},{"n":13,"t":"被造的，沒有一樣在他面前不是顯露的；萬物在他眼前都是赤露敞開的，我們必須向他交賬。","notes":[]},{"n":14,"t":"既然我們有一位偉大、進入高天的大祭司，就是耶穌—神的兒子，我們應當持定所宣認的道。","notes":[]},{"n":15,"t":"因為我們的大祭司並非不能體恤我們的軟弱；他也在各方面受過試探，與我們一樣，只是他沒有犯罪。","notes":[]},{"n":16,"t":"所以，我們只管坦然無懼地來到施恩的寶座前，為要得憐憫，蒙恩惠，作及時的幫助。","notes":[]}]},"5":{"heading":"警戒叛道的人","verses":[{"n":1,"t":"凡從人間挑選的大祭司都是奉派替人辦理屬神的事，要為罪獻上禮物和祭物。","notes":["「要為罪獻上禮物和祭物」或譯「為要獻上禮物和贖罪祭」。"]},{"n":2,"t":"他能體諒無知和迷失的人，因為他自己也是被軟弱所困，","notes":[]},{"n":3,"t":"因此他理當為百姓和自己的罪獻祭。","notes":[]},{"n":4,"t":"沒有人可擅自取得大祭司的尊榮，惟有蒙神所選召的才可以，像亞倫一樣。","notes":[]},{"n":5,"t":"同樣，基督也沒有自取作大祭司的榮耀，而是在乎向他說話的那一位，他說：「你是我的兒子，我今日生了你。」","notes":[]},{"n":6,"t":"就如又有一處說：「你是照著麥基洗德的體系永遠為祭司。」","notes":[]},{"n":7,"t":"基督在他肉身的日子，曾大聲哀哭，流淚禱告，懇求那能救他免死的神，就因他的虔誠蒙了應允。","notes":[]},{"n":8,"t":"他雖然為兒子，還是因所受的苦難學了順從。","notes":[]},{"n":9,"t":"既然他得以完全，就為凡順從他的人成了永遠得救的根源，","notes":[]},{"n":10,"t":"並蒙神照著麥基洗德的體系宣稱他為大祭司。","notes":[]},{"n":11,"t":"論到這事，我們有好些話要說，可是很難解釋，因為你們聽不進去。","notes":[]},{"n":12,"t":"按時間說，你們早該作教師了，誰知還需要有人再將神聖言基礎的要道教導你們；你們成了那需要吃奶、不能吃乾糧的人。","notes":[]},{"n":13,"t":"凡只能吃奶的，就不熟練仁義的道理，因為他是嬰孩。","notes":[]},{"n":14,"t":"惟獨長大成人的才能吃乾糧，他們的心竅因練習而靈活，能分辨善惡了。","notes":[]}]},"6":{"heading":"神確切的應許","verses":[{"n":1,"t":"所以，我們應當離開基督道理的基礎，竭力進到成熟的地步；不必再立根基，就如懊悔致死的行為、信靠神、","notes":[]},{"n":2,"t":"各樣洗禮、按手禮、死人復活，以及永遠的審判等的教導。","notes":[]},{"n":3,"t":"神若准許，我們就這樣做。","notes":[]},{"n":4,"t":"論到那些已經蒙了光照、嘗過天恩的滋味、又於聖靈有份、並嘗過神的話的美味，和來世權能的人，若再離棄真道，就不可能使他們重新懊悔了；因為他們親自把神的兒子重釘十字架，公然羞辱他。","notes":[],"end":6},{"n":7,"t":"就如一塊田地吸收過屢次下的雨水，生長蔬菜，合乎耕種的人用，就從神得福。","notes":[]},{"n":8,"t":"這塊田地若長荊棘和蒺藜，必被廢棄，近於詛咒，結局就是焚燒。","notes":[]},{"n":9,"t":"親愛的，雖然這樣說，我們仍深信你們有更好的情況，更接近救恩。","notes":[]},{"n":10,"t":"因為神並非不公義，竟忘記你們的工作和你們為他的名所顯的愛心，就是你們過去和現在伺候聖徒的愛心。","notes":[]},{"n":11,"t":"我們盼望你們各人都顯出同樣的熱忱，一直到底，好達成所確信的指望。","notes":[]},{"n":12,"t":"這樣你們才不會懶惰，卻成為效法那些藉著信和忍耐承受應許的人。","notes":[]},{"n":13,"t":"當初神應許亞伯拉罕的時候，因為沒有比自己更大的可以指著起誓，就指著自己起誓，","notes":[]},{"n":14,"t":"說：「我必多多賜福給你；我必使你大大增多。」","notes":[]},{"n":15,"t":"這樣，亞伯拉罕因恆心等待而得了所應許的。","notes":[]},{"n":16,"t":"人都是指著比自己大的起誓，並且以起誓作保證，了結各樣的爭論。","notes":[]},{"n":17,"t":"照樣，神願意為那承受應許的人更有力地顯明他的旨意不可更改，他以起誓作保證。","notes":[]},{"n":18,"t":"藉這兩件不可更改的事—在這些事上，神絕不會說謊—我們這些逃往避難所的人能得到強有力的鼓勵，去抓住那擺在我們前頭的指望。","notes":[]},{"n":19,"t":"我們有這指望，如同靈魂的錨，又堅固又牢靠，進入幔子後面的至聖所。","notes":[]},{"n":20,"t":"為我們作先鋒的耶穌，既照著麥基洗德的體系成了永遠的大祭司，已經進入了。","notes":[]}]},"7":{"heading":"麥基洗德的祭司體系","verses":[{"n":1,"t":"這麥基洗德就是撒冷王，是至高神的祭司。他在亞伯拉罕打敗諸王回來的時候迎接他，並給他祝福。","notes":[]},{"n":2,"t":"亞伯拉罕也將自己所得來的一切，取十分之一給他。他頭一個名字翻譯出來是「公義的王」，他又名「撒冷王」，是和平王的意思。","notes":[]},{"n":3,"t":"他無父、無母、無族譜、無生之始、無命之終，是與神的兒子相似，他永遠作祭司。","notes":[]},{"n":4,"t":"你們想一想，這個人多麼偉大啊！連先祖亞伯拉罕都拿戰利品的十分之一給他。","notes":[]},{"n":5,"t":"那得祭司職分的利未子孫，奉命照例向百姓取十分之一，這百姓是自己的弟兄，雖是從亞伯拉罕親身生的，還是照例取十分之一。","notes":[]},{"n":6,"t":"惟獨麥基洗德那不與他們同族譜的，從亞伯拉罕收取了十分之一，並且給蒙應許的亞伯拉罕祝福。","notes":[]},{"n":7,"t":"向來位分大的給位分小的祝福，這是無可爭議的。","notes":[]},{"n":8,"t":"在這事上，一方面，收取十分之一的都是必死的人；另一方面，收取十分之一的卻是那位被證實是活著的。","notes":[]},{"n":9,"t":"我們可以說，那接受十分之一的利未也是藉著亞伯拉罕納了十分之一，","notes":[]},{"n":10,"t":"因為麥基洗德迎接亞伯拉罕的時候，利未還在他先祖的身體裏面。","notes":[]},{"n":11,"t":"那麼，如果百姓藉著利未人的祭司職任能達到完全—因為百姓是在這職分下領受律法的—為甚麼還需要按照麥基洗德的體系另外興起一位祭司，而不按照亞倫的體系呢？","notes":[]},{"n":12,"t":"既然祭司的職分已更改，律法也需要更改。","notes":[]},{"n":13,"t":"因為這些話所指的人本屬別的支派，那支派裏從來沒有一人在祭壇前事奉的。","notes":[]},{"n":14,"t":"很明顯地，我們的主是從猶大出來的；但關於這支派，摩西並沒有提到祭司。","notes":[]},{"n":15,"t":"倘若有另一位像麥基洗德的祭司興起來，我的話就更顯而易見了。","notes":[]},{"n":16,"t":"他成為祭司，並不是照屬肉身的條例，而是照無窮生命的大能。","notes":["「無窮」：原文直譯「不能毀壞」。"]},{"n":17,"t":"因為有給他作見證的說：「你是照著麥基洗德的體系永遠為祭司。」","notes":[]},{"n":18,"t":"一方面，先前的誡命因軟弱無能而廢掉了，","notes":[]},{"n":19,"t":"（律法本來就不能成就甚麼）；另一方面，一個更好的指望被引進來，靠這指望，我們就可以親近神。","notes":[]},{"n":20,"t":"再者，耶穌成為祭司，並不是沒有神的誓言；其他的祭司被指派時並沒有這種誓言，","notes":[]},{"n":21,"t":"只有耶穌是起誓立的，因為那位立他的對他說：「主起了誓，絕不改變。你是永遠為祭司。」","notes":[]},{"n":22,"t":"既是起誓立的，耶穌也作了更美之約的中保。","notes":[]},{"n":23,"t":"一方面，那些成為祭司的數目本來多，是因為受死亡限制不能長久留住。","notes":[]},{"n":24,"t":"另一方面，這位既是永遠留住的，他具有不可更換的祭司職任。","notes":[]},{"n":25,"t":"所以，凡靠著他進到神面前的人，他都能拯救到底，因為他長遠活著為他們祈求。","notes":[]},{"n":26,"t":"這樣一位聖潔、無邪惡、無玷污、遠離罪人、高過諸天的大祭司，對我們是最合適的；","notes":[]},{"n":27,"t":"他不像那些大祭司，每日必須先為自己的罪，後為百姓的罪獻祭，因為他只一次將自己獻上就把這事成全了。","notes":[]},{"n":28,"t":"律法所立的大祭司本是有弱點的人，但在律法以後，神以起誓的話立了兒子為大祭司，成為完全，直到永遠。","notes":[]}]},"8":{"heading":"更新更美之約的大祭司","verses":[{"n":1,"t":"我們所講的事，其中第一要緊的就是：我們有這樣一位大祭司，他已經坐在天上至大者寶座的右邊，","notes":[]},{"n":2,"t":"在聖所，就是在真帳幕裏作僕役；這帳幕是主所支搭的，不是人所支搭的。","notes":[]},{"n":3,"t":"凡大祭司都是為獻禮物和祭物設立的，所以這位大祭司也必須有所獻上。","notes":[]},{"n":4,"t":"他若在地上，就不用作祭司，因為已經有照律法獻禮物的祭司了。","notes":[]},{"n":5,"t":"他們所供奉的本是天上之事的樣式和影像，正如摩西將要造帳幕的時候，神警戒他，說：「要謹慎，一切都要照著在山上指示你的樣式去做。」","notes":[]},{"n":6,"t":"如今耶穌已經得了更優越的事奉，正如他作更美之約的中保；這約原是憑更美之應許立的。","notes":[]},{"n":7,"t":"第一個約若沒有瑕疵，就無須尋求第二個約了。","notes":[]},{"n":8,"t":"所以神指責他們說：「主說，看哪，日子將到，我要與以色列家和猶大家另立新的約；","notes":[]},{"n":9,"t":"不像我拉著他們祖宗的手領他們出埃及地的時候，與他們所立的約；因為他們不恆心守我的約，所以我也不理他們；這是主說的。","notes":[]},{"n":10,"t":"主又說：那些日子以後，我與以色列家所立的約是這樣：我要將我的律法放在他們的心思裏，寫在他們的心上；我要作他們的神，他們要作我的子民。","notes":[]},{"n":11,"t":"他們各人不用教導自己的鄉親和自己的弟兄，說：你要認識主；因為從最小的到最大的，他們都要認識我。","notes":[]},{"n":12,"t":"我要寬恕他們的不義，絕不再記得他們的罪惡。」","notes":[]},{"n":13,"t":"既然神提到「新的約」，那麼第一個約就成為舊的了；而那漸舊漸衰的必然很快消逝了。","notes":[]}]},"9":{"heading":"地上和天上的聖所","verses":[{"n":1,"t":"原來連第一個約都有敬拜的禮儀和屬世界的聖幕。","notes":[]},{"n":2,"t":"因為那預備好了的帳幕，第一層叫聖所，裏面有燈臺、供桌和供餅。","notes":[]},{"n":3,"t":"第二層幔子後又有一層帳幕，叫至聖所，","notes":[]},{"n":4,"t":"有金香壇和四周包金的約櫃，櫃裏有盛嗎哪的金罐、亞倫那根發過芽的杖和兩塊約版；","notes":[]},{"n":5,"t":"櫃上面有榮耀的基路伯罩著施恩座。有關這一切我現在不能一一細說。","notes":[]},{"n":6,"t":"這些物件既如此預備齊了，眾祭司就不斷地進第一層帳幕行拜神的禮。","notes":[]},{"n":7,"t":"至於第二層帳幕，惟有大祭司一年一次獨自進去，沒有一次不帶著血，為自己獻上，也為百姓無意所犯的過錯獻上。","notes":[]},{"n":8,"t":"聖靈藉此指明，第一層帳幕仍存在的時候，進入至聖所的路還沒有顯示。","notes":[]},{"n":9,"t":"那第一層帳幕是現今時代的一個預表，表示所獻的禮物和祭物都不能使敬拜的人在良心上得以完全。","notes":[]},{"n":10,"t":"這些事只不過是有關飲食和各種潔淨的規矩，是屬肉體的條例，它的功效是直到新次序的時期來到為止。","notes":[]},{"n":11,"t":"但現在基督已經來到，作了已實現的美事的大祭司，經過那更大更全備的帳幕，不是人手所造，也不是屬於這世界的；","notes":[]},{"n":12,"t":"他不用山羊和牛犢的血，而是用自己的血，只一次進入至聖所就獲得了永遠的贖罪。","notes":[]},{"n":13,"t":"若山羊和公牛的血，以及母牛犢的灰，灑在不潔的人身上，尚且使人成聖，身體潔淨，","notes":[]},{"n":14,"t":"何況基督的血，他藉著永遠的靈把自己無瑕疵地獻給神，更能洗淨我們的良心，除去致死的行為，好事奉那位永生的神。","notes":["「我們」：有古卷是「你們」。"]},{"n":15,"t":"為此，基督作了新約的中保；因為他的死，贖了人在第一個約之時所犯的罪過，使蒙召的人能得著所應許永遠的產業。","notes":[]},{"n":16,"t":"凡有遺囑，必須證實立遺囑的人已經死了。","notes":[]},{"n":17,"t":"因為人死了，遺囑才有效力；立遺囑的人尚在，遺囑就不能生效。","notes":[]},{"n":18,"t":"所以，第一個約也是用血立的。","notes":[]},{"n":19,"t":"因為摩西當日照著律法將各樣誡命傳給眾百姓，就拿朱紅色絨和牛膝草，把牛犢、山羊的血和水灑在書上，又灑在眾百姓身上，","notes":["有古卷沒有「山羊」。"]},{"n":20,"t":"說：「這血就是神與你們立約的憑據。」","notes":[]},{"n":21,"t":"他又照樣把血灑在帳幕和敬拜用的各樣器皿上。","notes":[]},{"n":22,"t":"按著律法，幾乎每樣東西都是用血潔淨的；沒有流血，就沒有赦罪。","notes":[]},{"n":23,"t":"這樣，照著天上樣式做的物件必須用這些禮儀去潔淨，但那天上的一切，自然當用更美的祭物去潔淨。","notes":[],"heads":["基督獻己為祭除掉了罪"]},{"n":24,"t":"因為基督並沒有進了人手所造的聖所—這不過是真聖所的影像—而是進到天上，如今為我們出現在神面前。","notes":[]},{"n":25,"t":"他也無須多次將自己獻上，像大祭司每年帶著牛羊的血進入至聖所。","notes":[]},{"n":26,"t":"如果這樣，他從創世以來就必須多次受苦了。但如今，他在今世的末期顯現，僅一次把自己獻為祭，好除掉罪。","notes":[]},{"n":27,"t":"按著命定，人人都有一死，死後且有審判。","notes":[]},{"n":28,"t":"同樣，基督既然一次獻上，擔當了許多人的罪，將來要第二次顯現，與罪無關，而是為了拯救熱切等候他的人。","notes":[]}]},"10":{"heading":"勸勉和警告","verses":[{"n":1,"t":"既然律法只不過是未來美好事物的影子，不是本體的真像，就不能藉著每年常獻一樣的祭物，使那些進前來的人完全。","notes":[]},{"n":2,"t":"若不然，獻祭的事豈不早已停止了嗎？因為敬拜的人僅只一次潔淨，良心就不再覺得有罪了。","notes":[]},{"n":3,"t":"但是這些祭物使人每年都想起罪來，","notes":[]},{"n":4,"t":"因為公牛和山羊的血不能除罪。","notes":[]},{"n":5,"t":"所以，基督到世上來的時候，就說：「祭物和禮物不是你所要的，但你曾給我預備了身體。","notes":[]},{"n":6,"t":"燔祭和贖罪祭是你不喜歡的。","notes":[]},{"n":7,"t":"那時我說：看哪！我來了，我的事在經卷上已經記載了；神啊！我來為要照你的旨意行。」","notes":[]},{"n":8,"t":"以上說：「祭物和禮物，以及燔祭和贖罪祭，不是你所要的，也不是你喜歡的。」這都是按著律法獻的。","notes":[]},{"n":9,"t":"他接著說：「看哪！我來了，為要照你的旨意行。」可見他除去在先的，為要立定在後的。","notes":[]},{"n":10,"t":"我們憑著這旨意，藉著耶穌基督，僅只一次獻上他的身體就得以成聖。","notes":[]},{"n":11,"t":"所有的祭司天天站著事奉神，屢次獻上一樣的祭物，這祭物永不能除罪。","notes":[]},{"n":12,"t":"但基督獻了一次永遠有效的贖罪祭，就坐在神的右邊，","notes":[]},{"n":13,"t":"從此等候他的仇敵成為他的腳凳。","notes":[]},{"n":14,"t":"因為他僅只一次獻祭，就使那些得以成聖的人永遠完全。","notes":[]},{"n":15,"t":"聖靈也對我們作證，因為他說過：","notes":[]},{"n":16,"t":"「主說：那些日子以後，我與他們所立的約是這樣的：我要將我的律法放在他們的心上，又要寫在他們的心思裏。」","notes":[]},{"n":17,"t":"並說：「他們的罪惡和他們的過犯，我絕不再記得。」","notes":[]},{"n":18,"t":"這些罪過既已蒙赦免，就不用再為罪獻祭了。","notes":[]},{"n":19,"t":"所以，弟兄們，既然我們靠著耶穌的血得以坦然進入至聖所，","notes":[]},{"n":20,"t":"是藉著他給我們開了一條又新又活的路，從幔子經過，這幔子就是他的身體。","notes":[]},{"n":21,"t":"既然我們有一位偉大祭司治理神的家，","notes":[]},{"n":22,"t":"那麼，我們該用誠心和充足的信心，同已蒙潔淨、無虧的良心，和清水洗淨了的身體來親近神。","notes":[]},{"n":23,"t":"我們要堅守所宣認的指望，毫不動搖，因為應許我們的那位是信實的。","notes":[]},{"n":24,"t":"我們要彼此相顧，激發愛心，勉勵行善；","notes":[]},{"n":25,"t":"不可停止聚會，好像那些停止慣了的人，倒要彼此勸勉，既然知道那日子臨近，就更當如此。","notes":[]},{"n":26,"t":"如果我們領受真理的知識以後仍故意犯罪，就不再有贖罪的祭物，","notes":[]},{"n":27,"t":"惟有戰戰兢兢等候審判和那將吞滅眾敵人的烈火了。","notes":[]},{"n":28,"t":"任何人干犯摩西的律法，憑兩個或三個證人，尚且必須處死，不得寬赦，","notes":[]},{"n":29,"t":"更何況踐踏神兒子的人，他們將那使他成聖之約的血當作不潔淨，又褻慢施恩的聖靈的人，你們想，他不該受更嚴厲的懲罰嗎？","notes":[]},{"n":30,"t":"因為我們知道誰說：「伸冤在我，我必報應。」又說：「主要審判他的百姓。」","notes":[]},{"n":31,"t":"落在永生神的手裏真是可怕呀！","notes":[]},{"n":32,"t":"你們要追念往日；你們蒙了光照以後，忍受了許多痛苦的掙扎：","notes":[]},{"n":33,"t":"一面在眾人面前公然被毀謗，遭患難；一面陪伴那些受這樣苦難的人。","notes":[]},{"n":34,"t":"你們同情那些遭監禁的人，也欣然忍受你們的家業被人搶去，因為你們知道自己有更美好更長存的家業。","notes":[]},{"n":35,"t":"所以，不可丟棄你們無懼的心，存這樣的心必得大賞賜。","notes":[]},{"n":36,"t":"你們必須忍耐，使你們行完了神的旨意，可以獲得所應許的。","notes":[]},{"n":37,"t":"因為「還有一點點時候，那要來的就來，必不遲延。","notes":[]},{"n":38,"t":"只是我的義人必因信得生；他若退縮，我心就不喜歡他。」","notes":[]},{"n":39,"t":"我們卻不是退縮以致沉淪的那等人，而是有信心以致得生命的人。","notes":[]}]},"11":{"heading":"論信","verses":[{"n":1,"t":"信就是對所盼望之事有把握，對未見之事有確據。","notes":[]},{"n":2,"t":"古人因著這信獲得了讚許。","notes":[]},{"n":3,"t":"因著信，我們知道這宇宙是藉神的話造成的。這樣，看得見的是從看不見的造出來的。","notes":[]},{"n":4,"t":"因著信，亞伯獻祭給神比該隱所獻的更美，因此獲得了讚許為義人，神親自悅納了他的禮物。他雖然死了，卻因這信仍舊在說話。","notes":[]},{"n":5,"t":"因著信，以諾被接去，得以不見死，人也找不著他，因為神已經把他接去了；只是他被接去以前，已討得神的喜悅而蒙讚許。","notes":[]},{"n":6,"t":"沒有信，就不能討神的喜悅，因為到神面前來的人必須信有神，並且信他會賞賜尋求他的人。","notes":[]},{"n":7,"t":"因著信，挪亞既蒙神指示他未見的事，動了敬畏的心，造了方舟，使他全家得救。藉此他定了那世代的罪，自己也承受了那從信而來的義。","notes":[]},{"n":8,"t":"因著信，亞伯拉罕蒙召的時候就遵命出去，往將來要承受為基業的地方去；他出去的時候還不知往哪裏去。","notes":[]},{"n":9,"t":"因著信，他就在所應許之地作客，好像在異鄉，居住在帳棚裏，與蒙同一個應許的以撒和雅各一樣。","notes":[]},{"n":10,"t":"因為他等候著那座有根基的城，就是神所設計和建造的。","notes":[]},{"n":11,"t":"因著信，撒拉自己已過了生育的年齡還能懷孕，因為她認為應許她的那位是可信的；","notes":["本節或譯「因著信，撒拉自己雖然已過了生育的年齡，亞伯拉罕也老了，但還能作父親，因為他認為應許他的那位是可信的」。"]},{"n":12,"t":"所以，從一個彷彿已死的人竟生出子孫，如同天上的星那樣眾多，海邊的沙那樣無數。","notes":[]},{"n":13,"t":"這些人都是存著信心死的，並沒有得著所應許的，卻從遠處觀望，且歡喜迎接。他們承認自己在地上是客旅，是寄居的。","notes":[]},{"n":14,"t":"說這樣話的人是表明自己要尋找一個家鄉。","notes":[]},{"n":15,"t":"他們若想念所離開的家鄉，還有回去的機會。","notes":[]},{"n":16,"t":"其實他們所羨慕的是一個更美的，就是在天上的家鄉。所以，神並不因他們稱他為神而覺得羞恥，因為他已經為他們預備了一座城。","notes":["「稱他為神」或譯「求告他」。"]},{"n":17,"t":"因著信，亞伯拉罕被考驗的時候把以撒獻上，這就是那領受了應許的人甘心把自己獨生的兒子獻上。","notes":[]},{"n":18,"t":"論到這兒子，神曾說：「從以撒生的才要稱為你的後裔。」","notes":[]},{"n":19,"t":"他認為神甚至能使人從死人中復活，意味著他得回了他的兒子。","notes":[]},{"n":20,"t":"因著信，以撒指著將來的事給雅各、以掃祝福。","notes":[]},{"n":21,"t":"因著信，雅各臨死的時候給約瑟的兩個兒子個別祝福，扶著枴杖敬拜神。","notes":[]},{"n":22,"t":"因著信，約瑟臨終的時候提到以色列人將來要出埃及，並為自己的骸骨留下遺言。","notes":[]},{"n":23,"t":"因著信，摩西生下來，他的父母見他是個俊美的孩子，把他藏了三個月，並不怕王的命令。","notes":[]},{"n":24,"t":"因著信，摩西長大了不肯稱為法老女兒之子。","notes":[]},{"n":25,"t":"他寧可和神的百姓一同受苦，也不願在罪中享受片刻的歡樂。","notes":[]},{"n":26,"t":"他把為彌賽亞受凌辱看得比埃及的財物更寶貴，因為他想望所要得的賞賜。","notes":[]},{"n":27,"t":"因著信，他離開埃及，不怕王的憤怒，因為他恆心忍耐，如同看見那不能看見的神。","notes":[]},{"n":28,"t":"因著信，他設立逾越節，在門上灑血，免得那毀滅者加害以色列人的長子。","notes":[]},{"n":29,"t":"因著信，他們過紅海如行乾地；埃及人試著要過去就被淹沒了。","notes":[]},{"n":30,"t":"因著信，以色列人圍繞耶利哥城七日，城牆就倒塌了。","notes":[]},{"n":31,"t":"因著信，妓女喇合曾友善地接待探子，就沒有跟那些不順從的人一同滅亡。","notes":[]},{"n":32,"t":"我還要說甚麼呢？若要一一細說基甸、巴拉、參孫、耶弗他、大衛、撒母耳和眾先知的事，時間就不夠了。","notes":[]},{"n":33,"t":"他們藉著信，制伏了敵國，行了公義，得了應許，堵住了獅子的口，","notes":[]},{"n":34,"t":"滅了烈火的威力，在鋒利的刀劍下逃生，從軟弱變為剛強，爭戰中顯出勇猛，打退外邦的全軍。","notes":[]},{"n":35,"t":"有些婦人得回從死人中復活的親人。又有人忍受嚴刑，拒絕被釋放，為要得著更美好的復活。","notes":[]},{"n":36,"t":"又有人忍受戲弄、鞭打、捆鎖、監禁、各等的磨煉；","notes":[]},{"n":37,"t":"他們被石頭打死，被鋸鋸死，被刀殺，披著綿羊山羊的皮各處奔跑，受貧窮、患難、虐待。","notes":["有古卷加「受試探」。"]},{"n":38,"t":"這世界配不上他們，他們在曠野、山嶺、山洞、地穴，飄流無定。","notes":[]},{"n":39,"t":"這些人都是因信獲得了讚許，卻仍未得著所應許的，","notes":[]},{"n":40,"t":"因為神給我們預備了更美好的事，若沒有我們，他們就不能達到完全。","notes":[]}]},"12":{"heading":"主的管教","verses":[{"n":1,"t":"所以，既然我們有這許多見證人如同雲彩圍繞著我們，就該卸下各樣重擔和緊緊纏累的罪，以堅忍的心奔那擺在我們前頭的路程，","notes":[]},{"n":2,"t":"仰望我們信心的創始成終者耶穌，他因那擺在前面的喜樂，輕看羞辱，忍受了十字架的苦難，如今已坐在神寶座的右邊。","notes":[]},{"n":3,"t":"你們要仔細想想這位忍受了罪人如此頂撞的耶穌，你們就不致心灰意懶了。","notes":[]},{"n":4,"t":"你們與罪惡爭鬥，還沒有抵抗到流血的地步。","notes":[]},{"n":5,"t":"你們又忘了神勸你們如同勸兒女的那些話，說：「我兒啊，不可輕看主的管教，被他責備的時候不可灰心；","notes":[]},{"n":6,"t":"因為主所愛的，他必管教，又鞭打他所接納的每一個孩子。」","notes":[]},{"n":7,"t":"為了受管教，你們要忍受。神待你們如同待兒女。哪有兒女不被父親管教的呢？","notes":[]},{"n":8,"t":"管教原是眾兒女共同所領受的；你們若不受管教，就是私生子，不是兒女了。","notes":[]},{"n":9,"t":"再者，我們曾有肉身之父管教我們，我們尚且敬重他，何況靈性之父，我們豈不更當順服他而得生命嗎？","notes":[]},{"n":10,"t":"肉身之父都是短時間隨己意管教我們，惟有靈性之父管教我們是要我們得益處，使我們在他的聖潔上有份。","notes":[]},{"n":11,"t":"凡管教的事，當時不覺得快樂，反覺得痛苦；後來卻為那經過鍛鍊的人結出平安的果子，就是義的果子。","notes":[]},{"n":12,"t":"所以，你們要把下垂的手舉起來，發酸的腿挺直；","notes":[]},{"n":13,"t":"要為自己的腳把道路修直了，使瘸了的腿不再脫臼，反而得到痊癒。","notes":[]},{"n":14,"t":"你們要追求與眾人和睦，並要追求聖潔；人非聖潔不能見主。","notes":[],"heads":["警告棄絕神恩典的人"]},{"n":15,"t":"要謹慎，免得有人失去了神的恩典；免得有毒根生出來擾亂你們，因而使許多人沾染污穢，","notes":[]},{"n":16,"t":"免得有人淫亂，或不敬虔如以掃，他因一點點食物把自己長子的名分賣了。","notes":[]},{"n":17,"t":"後來你們知道，他想要承受父親的祝福，竟被拒絕，雖然流著淚苦求，卻得不著門路使他父親回心轉意。","notes":[]},{"n":18,"t":"你們不是來到那可觸摸的山，那裏有火焰、密雲、黑暗、暴風、","notes":[]},{"n":19,"t":"角聲，和說話的聲音；當時那些聽見這聲音的，都求不要再向他們說話，","notes":[]},{"n":20,"t":"因為他們擔當不起所命令他們的話，說：「靠近這山的，即使是走獸，也要用石頭打死。」","notes":[]},{"n":21,"t":"所見的景象極其可怕，以致摩西說：「我恐懼戰兢。」","notes":[]},{"n":22,"t":"但是你們是來到錫安山，永生神的城，就是天上的耶路撒冷，那裏有千千萬萬的天使，","notes":[]},{"n":23,"t":"有名字記錄在天上眾長子的盛會，有審判眾人的神和成為完全的義人的靈魂，","notes":[]},{"n":24,"t":"並新約的中保耶穌，以及所灑的血；這血所說的信息比亞伯的血所說的更美。","notes":[]},{"n":25,"t":"你們總要謹慎，不可拒絕那向你們說話的，因為那些拒絕了在地上警戒他們的，尚且不能逃罪，何況我們違背那從天上警戒我們的呢？","notes":[]},{"n":26,"t":"當時他的聲音震動了地，但如今他應許說：「再一次我不單要震動地，還要震動天。」","notes":[]},{"n":27,"t":"這「再一次」的話是指明被震動的要像受造之物一樣被挪去，使那不被震動的能常存。","notes":[]},{"n":28,"t":"所以，既然我們得了不能被震動的國度，就要感恩，照著神所喜悅的，用虔誠、敬畏的心事奉神，","notes":[]},{"n":29,"t":"因為我們的神是吞滅的火。","notes":[]}]},"13":{"heading":"蒙神悅納的事奉","verses":[{"n":1,"t":"你們務要常存弟兄相愛的心。","notes":[]},{"n":2,"t":"不可忘記用愛心接待旅客，因為曾經有人這樣做，在無意中接待了天使。","notes":[]},{"n":3,"t":"要記念受監禁的人，好像與他們同受監禁；要記念受虐待的人，好像你們也親身受虐待一樣。","notes":[]},{"n":4,"t":"婚姻，人人都當尊重，共眠的床也不可污穢，因為淫亂和通姦的人，神必審判。","notes":[]},{"n":5,"t":"不可貪愛錢財，要以自己所有的為滿足，因為神曾說：「我絕不撇下你，也絕不丟棄你。」","notes":[]},{"n":6,"t":"所以，我們可以勇敢地說：「主是我的幫助，我必不懼怕。人能把我怎麼樣呢？」","notes":[]},{"n":7,"t":"從前引導你們、傳神的道給你們的人，你們要記念他們，效法他們的信心，回顧他們為人的結局。","notes":[]},{"n":8,"t":"耶穌基督昨日、今日，一直到永遠，是一樣的。","notes":[]},{"n":9,"t":"你們不要被種種怪異的教訓勾引了去，因為人的心靠恩典得堅固才是好的，並不是靠飲食。那在飲食上用心的，從來沒有得到益處。","notes":[]},{"n":10,"t":"我們有一祭壇，上面的祭物是那些在會幕中供職的人無權可吃的。","notes":[]},{"n":11,"t":"因為牲畜的血被大祭司帶入至聖所作贖罪祭，牲畜的體卻在營外燒掉。","notes":[]},{"n":12,"t":"所以，耶穌也在城門外受苦，為要用自己的血使百姓成聖。","notes":[]},{"n":13,"t":"這樣，我們也當走出營外，到他那裏去，忍受他所受的凌辱。","notes":[]},{"n":14,"t":"在這裏，我們本沒有永存的城，而是在尋求那將要來的城。","notes":[]},{"n":15,"t":"我們應當藉著耶穌，常常以頌讚為祭獻給神，這是那宣認他名的人嘴唇所結的果子。","notes":[]},{"n":16,"t":"只是不可忘記行善和分享，因為這樣的祭物是神所喜悅的。","notes":[]},{"n":17,"t":"你們要服從那些引導你們的，並且要順服，因為他們為你們的靈魂時刻警醒，像在神面前交賬的人，讓他們在交賬的時候有喜樂，而不是嘆息，嘆息就對你們無益了。","notes":[]},{"n":18,"t":"請你們為我們禱告；因為我們自覺良心無虧，願意凡事按正道而行。","notes":[]},{"n":19,"t":"我更求你們為我禱告，使我快些回到你們那裏去。","notes":[]},{"n":20,"t":"但願賜平安的神，就是那憑永約之血，把群羊的大牧人—我們主耶穌從死人中領出來的神，","notes":["「平安」或譯「和平」。"],"heads":["祝福和問安"]},{"n":21,"t":"在各樣善事上裝備你們，使你們遵行他的旨意；又藉著耶穌基督在我們裏面行他所喜悅的事。願榮耀歸給他，直到永永遠遠。阿們！","notes":["「我們」：有古卷是「你們」。","有古卷是「直到永遠」。"]},{"n":22,"t":"弟兄們，我簡略地寫信給你們，希望你們聽我勸勉的話。","notes":[]},{"n":23,"t":"你們該知道，我們的弟兄提摩太已經重獲自由了；他若很快就來，我必同他去見你們。","notes":[]},{"n":24,"t":"請你們向帶領你們的諸位和眾聖徒問安。從意大利來的人也向你們問安。","notes":[]},{"n":25,"t":"願恩惠與你們眾人同在。","notes":["有古卷加「阿們！」"]}]}},"JAS":{"1":{"heading":"問候","verses":[{"n":1,"t":"神和主耶穌基督的僕人雅各問候散居在各處的十二個支派的人。","notes":[]},{"n":2,"t":"我的弟兄們，你們遭受各種試煉時，都要認為是大喜樂，","notes":[],"heads":["信心和智慧"]},{"n":3,"t":"因為知道你們的信心經過考驗，就生忍耐。","notes":[]},{"n":4,"t":"但要讓忍耐發揮完全的功用，使你們能又完全又完整，一無所缺。","notes":[]},{"n":5,"t":"你們中間若有缺少智慧的，該求那厚賜與眾人又不斥責人的神，神必賜給他。","notes":[]},{"n":6,"t":"只要憑著信心求，一點也不疑惑；因為那疑惑的人，就像海中的波浪被風吹動翻騰。","notes":[]},{"n":7,"t":"這樣的人不要想從主那裏得到甚麼。","notes":[]},{"n":8,"t":"三心二意的人，在他一切所行的路上都搖擺不定。","notes":[]},{"n":9,"t":"卑微的弟兄要因高升而誇耀，","notes":[],"heads":["貧窮和富有"]},{"n":10,"t":"富足的卻要因被降卑而誇耀，因為富足的人要消逝，如同草上的花一樣。","notes":[]},{"n":11,"t":"太陽出來，熱風颳起，草就枯乾，花也凋謝，它美麗的樣子就消失了；那富足的人在他一生的奔波中也要這樣衰殘。","notes":[]},{"n":12,"t":"忍受試煉的人有福了，因為他經過考驗以後必得生命的冠冕，這是主應許給愛他之人的。","notes":[],"heads":["考驗和試探"]},{"n":13,"t":"人被誘惑，不可說：「我是被神誘惑」；因為神是不被惡誘惑的，他也不誘惑人。","notes":[]},{"n":14,"t":"但每一個人被誘惑是因自己的私慾牽引而被誘惑的。","notes":[]},{"n":15,"t":"私慾既懷了胎，就生出罪來；罪既長成，就生出死來。","notes":[]},{"n":16,"t":"我親愛的弟兄們，不要被欺騙了。","notes":[]},{"n":17,"t":"各樣美善的恩澤和各樣完美的賞賜都是從上頭來的，從眾光之父那裏降下來的；在他並沒有改變，也沒有轉動的影兒。","notes":[]},{"n":18,"t":"他按自己的旨意，用真理的道生了我們，使我們在他所造的萬物中成為初熟的果子。","notes":[]},{"n":19,"t":"我親愛的弟兄們，你們要明白：你們每一個人要快快地聽，慢慢地說，慢慢地動怒，","notes":[],"heads":["聽道和行道"]},{"n":20,"t":"因為人的怒氣並不能實現神的義。","notes":[]},{"n":21,"t":"所以，你們要除去一切的污穢和累積的惡毒，要存溫柔的心領受所栽種的道，就是能救你們靈魂的道。","notes":[]},{"n":22,"t":"但是，你們要作行道的人，不要只作聽道的人，自己欺騙自己。","notes":[]},{"n":23,"t":"因為只聽道而不行道的，就像人對著鏡子觀看自己本來的面目，","notes":[]},{"n":24,"t":"注視後，就離開，立刻忘了自己的相貌如何。","notes":[]},{"n":25,"t":"惟有查看那完美、使人自由的律法，並且時常遵守的，他不是聽了就忘，而是切實行出來，這樣的人在所行的事上必然蒙福。","notes":[]},{"n":26,"t":"若有人自以為虔誠，卻不勒住自己的舌頭，反欺騙自己的心，這人的虔誠是徒然的。","notes":[]},{"n":27,"t":"在神—我們的父面前，清潔沒有玷污的虔誠就是看顧在患難中的孤兒寡婦，並且保守自己不沾染世俗。","notes":[]}]},"2":{"heading":"警告偏私","verses":[{"n":1,"t":"我的弟兄們，你們信奉我們榮耀的主耶穌基督，就不可按著外貌待人。","notes":[]},{"n":2,"t":"若有一個人戴著金戒指，穿著華麗的衣服，進入你們的會堂，又有一個窮人穿著骯髒的衣服也進去，","notes":[]},{"n":3,"t":"而你們只看重那穿華麗衣服的人，說：「請坐在這裏」，又對那窮人說：「你站在那裏」，或「坐在我腳凳旁」；","notes":[]},{"n":4,"t":"這豈不是你們偏心待人，用惡意評斷人嗎？","notes":[]},{"n":5,"t":"我親愛的弟兄們，請聽，神豈不是揀選了世上的貧窮人，使他們在信心上富足，並承受他所應許給那些愛他之人的國嗎？","notes":[]},{"n":6,"t":"你們卻羞辱貧窮的人。欺壓你們，拉你們到公堂去的，不就是這些富有的人嗎？","notes":[]},{"n":7,"t":"毀謗為你們求告時所奉的尊名的，不就是他們嗎？","notes":[]},{"n":8,"t":"經上記著：「要愛鄰 如己」，你們若切實守這至尊的律法，你們就做得很好。","notes":["「鄰」也可譯作「人」。"]},{"n":9,"t":"但你們若按外貌待人就是犯罪，是被律法定為犯法的。","notes":[]},{"n":10,"t":"因為凡遵守全部律法的，只違背了一條就是違犯了所有的律法。","notes":[]},{"n":11,"t":"原來那說「不可姦淫」的，也說「不可殺人」。你就是不姦淫，卻殺人，也是成為違犯律法的。","notes":[]},{"n":12,"t":"既然你們要按使人自由的律法受審判，就要照這律法說話行事。","notes":[]},{"n":13,"t":"因為對那不憐憫人的，他們要受沒有憐憫的審判；憐憫勝過審判。","notes":[]},{"n":14,"t":"我的弟兄們，若有人說自己有信心，卻沒有行為，有甚麼益處呢？這信心能救他嗎？","notes":[],"heads":["信心和行為"]},{"n":15,"t":"若是弟兄或是姊妹沒有衣服穿，又缺少日用的飲食；","notes":[]},{"n":16,"t":"你們中間有人對他們說：「平平安安地去吧！願你們穿得暖，吃得飽」，卻不給他們身體所需要的，這有甚麼益處呢？","notes":[]},{"n":17,"t":"信心也是這樣，若沒有行為是死的。","notes":[]},{"n":18,"t":"但是有人會說：「你有信心，我有行為。」把你沒有行為的信心給我看，我就藉著我的行為把我的信心給你看。","notes":[]},{"n":19,"t":"你信神只有一位，你信得很好；連鬼魔也信，且怕得發抖。","notes":[]},{"n":20,"t":"你這虛浮的人哪，你願意知道沒有行為的信心是沒有用的嗎？","notes":[]},{"n":21,"t":"我們的祖宗亞伯拉罕把他兒子以撒獻在壇上，豈不是因行為得稱義嗎？","notes":[]},{"n":22,"t":"可見信心是與他的行為相輔並行，而且信心是因著行為才得以成全的。","notes":[]},{"n":23,"t":"這正應驗了經上所說：「亞伯拉罕信了神，這就算他為義」；他又得稱為神的朋友。","notes":[]},{"n":24,"t":"這樣看來，人稱義是因著行為，不是單因著信。","notes":[]},{"n":25,"t":"同樣，妓女喇合接待使者，又放他們從另一條路出去，不也是因行為稱義嗎？","notes":[]},{"n":26,"t":"所以，就如身體沒有靈魂是死的，信心沒有行為也是死的。","notes":[]}]},"3":{"heading":"制伏舌頭","verses":[{"n":1,"t":"我的弟兄們，不要許多人做教師，因為你們知道，我們做教師的要接受更嚴厲的審判。","notes":[]},{"n":2,"t":"原來我們在許多事上都有過失；若有人在言語上沒有過失，他就是完全的人，也能勒住自己的全身。","notes":[]},{"n":3,"t":"我們若把嚼環放在馬嘴裏使牠們馴服，就能控制牠們的全身。","notes":[]},{"n":4,"t":"再看船隻，雖然甚大，又被強風猛吹，只用小小的舵就隨著掌舵的意思轉動。","notes":[]},{"n":5,"t":"同樣，舌頭是小肢體，卻能說大話。看哪，最小的火能點燃最大的樹林。","notes":[]},{"n":6,"t":"舌頭就是火。在我們百體中，舌頭是個不義的世界，能玷污全身，也能燒燬生命的輪子，而且是被地獄的火點燃的。","notes":[]},{"n":7,"t":"各類的走獸、飛禽、爬蟲、水族，本來都可以制伏，也已經被人制伏了；","notes":[]},{"n":8,"t":"惟獨舌頭沒有人能制伏，是永不靜止的邪惡，充滿了害死人的毒氣。","notes":[]},{"n":9,"t":"我們用舌頭頌讚我們的主—我們的天父，又用舌頭詛咒照著神形像被造的人。","notes":[]},{"n":10,"t":"頌讚和詛咒從同一個口出來。我的弟兄們，這是不應該的。","notes":[]},{"n":11,"t":"泉源能從一個出口發出甜苦兩樣的水嗎？","notes":[]},{"n":12,"t":"我的弟兄們，無花果樹能生橄欖嗎？葡萄樹能結無花果嗎？鹹水也不能流出甜水來。","notes":[]},{"n":13,"t":"你們中間誰是有智慧有見識的呢？他就當在智慧的溫柔上顯出他的善行來。","notes":[],"heads":["從上頭來的智慧"]},{"n":14,"t":"你們心裏若懷著惡毒的嫉妒和自私，就不可自誇，不可說謊話抵擋真理。","notes":[]},{"n":15,"t":"這樣的智慧不是從上頭下來的，而是屬地上的，屬情慾的，屬鬼魔的。","notes":[]},{"n":16,"t":"在何處有嫉妒、自私，在何處就有動亂和各樣的壞事。","notes":[]},{"n":17,"t":"惟獨從上頭來的智慧，先是清潔，後是和平、溫良、柔順，滿有憐憫和美善的果子，沒有偏私，沒有虛偽。","notes":[]},{"n":18,"t":"正義的果實是為促進和平的人用和平栽種出來的。","notes":[]}]},"4":{"heading":"不可與世俗為友","verses":[{"n":1,"t":"你們中間的衝突是哪裏來的？爭執是哪裏來的？不是從你們肢體中交戰著的私慾來的嗎？","notes":[]},{"n":2,"t":"你們貪戀，得不著就殺人；你們嫉妒，不能得手就起爭執和衝突；你們得不著，是因為你們不求。","notes":[]},{"n":3,"t":"你們求也得不著，是因為你們妄求，為了要浪費在你們的宴樂中。","notes":[]},{"n":4,"t":"你們這些淫亂的人哪，豈不知道與世俗為友就是與神為敵嗎？所以，凡想要與世俗為友的，就是與神為敵了。","notes":[]},{"n":5,"t":"經上說：「神愛安置在我們裏面的靈，愛到嫉妒的地步。」你們以為這話是徒然的嗎？","notes":["「神愛…的地步。」或譯「神會嫉妒地愛戀他安置在我們裏面的靈。」"]},{"n":6,"t":"但是他賜更多的恩典，正如經上說：「神抵擋驕傲的人，但賜恩給謙卑的人。」","notes":[]},{"n":7,"t":"所以，要順服神。要抵擋魔鬼，魔鬼就必逃避你們；","notes":[]},{"n":8,"t":"要親近神，神就必親近你們。有罪的人哪，要潔淨你們的手！心懷二意的人哪，要清潔你們的心！","notes":[]},{"n":9,"t":"你們要愁苦，悲哀，哭泣；要將歡笑變為悲哀，歡樂變為愁悶。","notes":[]},{"n":10,"t":"要在主面前謙卑，他就使你們高升。","notes":[]},{"n":11,"t":"弟兄們，不可彼此詆毀。詆毀弟兄或評斷弟兄的人，就是詆毀律法，評斷律法；你若評斷律法，就不是遵行律法，而是評斷者了。","notes":[],"heads":["不可評斷弟兄"]},{"n":12,"t":"立法者和審判者只有一位；他就是那能拯救人也能毀滅人的。你是誰，竟敢評斷你的鄰舍！","notes":[]},{"n":13,"t":"注意！有人說：「今天或明天我們要往某城去，在那裏住一年，做買賣賺錢。」","notes":[],"heads":["警戒自誇"]},{"n":14,"t":"其實明天如何，你們還不知道。你們的生命是甚麼呢？你們原來是一片雲霧，出現片刻就不見了。","notes":["有古卷是「它」。"]},{"n":15,"t":"你們倒應當說：「主若願意，我們就能活著，也可以做這事或那事。」","notes":[]},{"n":16,"t":"現今你們竟然狂傲自誇；凡這樣的自誇都是邪惡的。","notes":[]},{"n":17,"t":"所以，人若知道該行善而不去行，這就是他的罪了。","notes":[]}]},"5":{"heading":"警告富足的人","verses":[{"n":1,"t":"注意！你們這些富足人哪，要為將要臨到你們身上的災難哭泣、號咷。","notes":[]},{"n":2,"t":"你們的財物腐爛了，你們的衣服被蟲子蛀了。","notes":[]},{"n":3,"t":"你們的金銀都生銹了；這銹要證明你們的不是，又要像火一樣吞吃你們的肉。你們在這末世只知道積蓄錢財。","notes":[]},{"n":4,"t":"工人給你們收割莊稼，你們剋扣他們的工錢；這工錢在喊冤，而且收割工人的冤聲已經進入萬軍之主的耳朵了。","notes":[]},{"n":5,"t":"你們在地上享奢華宴樂，把自己養肥了，等候宰殺的日子。","notes":[]},{"n":6,"t":"你們定了義人的罪，把他殺害，他沒有抵抗你們。","notes":[]},{"n":7,"t":"所以弟兄們，你們要忍耐，直到主來。看哪，農夫等候著地裏寶貴的出產，耐心地等到它得了秋霖春雨。","notes":[],"heads":["忍耐和禱告"]},{"n":8,"t":"你們也要忍耐，堅固你們的心，因為主來的日子近了。","notes":[]},{"n":9,"t":"弟兄們，你們不要彼此埋怨，免得受審判。看哪，審判的主站在門口了。","notes":[]},{"n":10,"t":"弟兄們，你們要把那先前奉主名說話的眾先知作能受苦、能忍耐的榜樣。","notes":[]},{"n":11,"t":"看哪，那些忍耐的人，我們稱他們是有福的。你們聽見過約伯的忍耐，也看見主給他的結局，知道主是充滿憐憫和慈悲的。","notes":[]},{"n":12,"t":"我的弟兄們，最要緊的是不可起誓；不可指著天起誓，也不可指著地起誓，任何誓都不可起。你們說話，是，就說是；不是，就說不是，免得你們落在審判之下。","notes":[]},{"n":13,"t":"你們中間若有人受苦，他該禱告；有人喜樂，他該歌頌。","notes":[]},{"n":14,"t":"你們中間若有人病了，他該請教會的長老們來為他禱告，奉主的名為他抹油。","notes":[]},{"n":15,"t":"出於信心的祈禱必能救那病人，主必叫他起來；他若犯了罪，也必蒙赦免。","notes":[]},{"n":16,"t":"所以，你們要彼此認罪，互相代求，使你們得醫治。義人祈禱所發的力量是大有功效的。","notes":[]},{"n":17,"t":"以利亞與我們是同樣性情的人，他懇切地祈求不要下雨，地上就三年六個月沒有下雨。","notes":[]},{"n":18,"t":"他又禱告，天就降下雨來，地就有了出產。","notes":[]},{"n":19,"t":"我的弟兄們，你們中間若有人迷失了真理而有人使他回轉，","notes":[]},{"n":20,"t":"這人該知道，使一個罪人從迷途中回轉，會從死亡中把他的靈魂救回來，而且遮蓋許多的罪。","notes":[]}]}},"1PE":{"1":{"heading":"問候","verses":[{"n":1,"t":"耶穌基督的使徒彼得寫信給那些被揀選，分散在本都、加拉太、加帕多家、亞細亞、庇推尼寄居的人，","notes":[]},{"n":2,"t":"就是照父神的預知，藉著聖靈得以成聖，以致順服耶穌基督，又蒙他血所灑的人。願恩惠、平安多多地賜給你們！","notes":["「平安」或譯「和平」。"]},{"n":3,"t":"願頌讚歸於我們主耶穌基督的父神！他曾照自己的大憐憫，藉著耶穌基督從死人中復活，重生了我們，使我們有活的盼望，","notes":[],"heads":["活的盼望"]},{"n":4,"t":"好得到不朽壞、不玷污、不衰殘、為你們存留在天上的基業，","notes":[]},{"n":5,"t":"就是為你們這些藉著信、蒙神大能保守的人，能獲得他所預備、到末世要顯現的救恩。","notes":[]},{"n":6,"t":"雖然你們必須在百般試煉中暫時憂愁，你們要為此喜樂 ，","notes":["「你們要為此喜樂」或譯「為此你們有喜樂」。"]},{"n":7,"t":"使你們的信心既被考驗，就比那被火試煉仍然能壞的金子更顯寶貴，可以在耶穌基督顯現的時候得著稱讚、榮耀、尊貴。","notes":[]},{"n":8,"t":"雖然你們沒有見過他，卻是愛他；如今雖看不見，你們卻因信他而有說不出來、滿有榮光的喜樂，","notes":[]},{"n":9,"t":"因為你們得到信心的效果，就是靈魂的得救。","notes":["有古卷是「我們」。"]},{"n":10,"t":"論到這救恩，那預先說你們要得恩典的眾先知已經詳細地搜索查考過，","notes":[]},{"n":11,"t":"查考在他們心裏的基督的靈預先證明基督受苦難，後來得榮耀，是指甚麼時候，甚麼樣的情況。","notes":[]},{"n":12,"t":"他們得了啟示，知道他們所服事的不是自己，而是你們。那藉著從天上差來的聖靈傳福音給你們的人，現在將這些事傳給你們；這些事連天使也都切望察看呢！","notes":[]},{"n":13,"t":"所以，要準備好你們的心，謹慎自守，專心盼望耶穌基督顯現的時候帶給你們的恩惠。","notes":["「準備」：原文直譯「束腰」。"],"heads":["應當過聖潔的生活"]},{"n":14,"t":"作為順服的兒女，就不要效法從前蒙昧無知的時候那放縱私慾的樣子。","notes":[]},{"n":15,"t":"但那召你們的既是聖潔，你們在一切所行的事上也要聖潔；","notes":[]},{"n":16,"t":"因為經上記著：「你們要成為聖，因為我是神聖的。」","notes":[]},{"n":17,"t":"既然你們稱那不偏待人、按各人行為審判人的主為父，就當存敬畏的心，度你們在世寄居的日子。","notes":["「稱那…為父」或譯「求告那不偏待人、按各人行為審判人的父」。"]},{"n":18,"t":"你們知道，你們得以從你們祖先傳下來虛妄的行為中救贖出來，不是靠著會朽壞的金銀等物，","notes":[]},{"n":19,"t":"而是憑著基督的寶血，如同無瑕疵、無玷污的羔羊的血。","notes":[]},{"n":20,"t":"基督是神在創世以前所預知，而在這末世才為你們顯現的。","notes":[]},{"n":21,"t":"你們也因著他而信那使他從死人中復活、又給他榮耀的神，好讓你們的信心和盼望都在於神。","notes":[]},{"n":22,"t":"既然你們因順從真理而潔淨了自己的心靈，能真誠愛弟兄，就該以清潔的心彼此切實相愛。","notes":["「以清潔的心」：有古卷是「從心裏」；另有古卷是「以真誠的心」。"]},{"n":23,"t":"你們蒙了重生，不是由於會朽壞的種子，而是由於不會朽壞的種子，是藉著神永活常存的道。","notes":[]},{"n":24,"t":"因為「凡血肉之軀的盡都如草，他的一切榮美像草上的花；草必枯乾，花必凋謝，","notes":[]},{"n":25,"t":"惟有主的道永遠常存。」這話就是傳給你們的福音。","notes":[]}]},"2":{"heading":"活石和聖潔的國度","verses":[{"n":1,"t":"所以，你們要除去一切的惡毒，一切詭詐、假善、嫉妒，和一切毀謗的話。","notes":[]},{"n":2,"t":"要愛慕那純淨的靈奶，像初生的嬰孩愛慕奶一樣，好使你們藉著它成長，以致得救，","notes":[]},{"n":3,"t":"因為你們已經嘗過主恩的滋味。","notes":[]},{"n":4,"t":"要親近主，他是活石，雖然被人所丟棄，卻是神所揀選、所珍貴的。","notes":[]},{"n":5,"t":"你們作為活石，要被建造成屬靈的殿，成為聖潔的祭司，藉著耶穌基督獻上蒙神悅納的屬靈祭物。","notes":[]},{"n":6,"t":"因為經上說：「看哪，我把一塊石頭放在錫安—一塊蒙揀選、珍貴的房角石；信靠他的人必不蒙羞。」","notes":[]},{"n":7,"t":"所以，這石頭在你們信的人是珍貴的；在那不信的人卻有話說：「匠人所丟棄的石頭已作了房角的頭塊石頭。」","notes":[]},{"n":8,"t":"又說：「作了絆腳的石頭，使人跌倒的磐石。」他們絆跌，因為不順從這道，這也是預定的。","notes":[]},{"n":9,"t":"不過，你們是被揀選的一族，是君尊的祭司，是神聖的國度，是屬神的子民，要使你們宣揚那召你們出黑暗入奇妙光明者的美德。","notes":[]},{"n":10,"t":"「你們從前不是子民，現在卻成了神的子民；從前未曾蒙憐憫，現在卻蒙了憐憫。」","notes":[]},{"n":11,"t":"親愛的，你們是客旅，是寄居的，我勸你們要禁戒肉體的情慾；這情慾是與靈魂爭戰的。","notes":[],"heads":["作神的僕人"]},{"n":12,"t":"你們在外邦人中要品行端正，好讓那些人，雖然毀謗你們是作惡的，會因看見你們的好行為而在鑒察的日子歸榮耀給神。","notes":["「鑒察」或譯「眷顧」或「來臨」。"]},{"n":13,"t":"你們為主的緣故要順服人的一切制度，或是在上的君王，","notes":[]},{"n":14,"t":"或是君王所派懲惡賞善的官員。","notes":[]},{"n":15,"t":"因為神的旨意原是要你們以行善來堵住糊塗無知人的口。","notes":[]},{"n":16,"t":"雖然你們是自由的，卻不可藉著自由遮蓋惡毒，總要作神的僕人。","notes":[]},{"n":17,"t":"務要尊重眾人；要敬愛教中的弟兄姊妹；要敬畏神；要尊敬君王。","notes":[]},{"n":18,"t":"你們作奴僕的，凡事要存敬畏的心順服主人；不但順服善良溫和的，就是乖僻的也要順服。","notes":[],"heads":["基督受苦的榜樣"]},{"n":19,"t":"倘若你們為使良心對得起神，忍受冤屈的痛苦，這是可讚許的。","notes":[]},{"n":20,"t":"你們若因犯罪受責打而忍耐，有甚麼可稱讚的呢？但你們若因行善受苦而忍耐，這在神看來是可讚許的。","notes":[]},{"n":21,"t":"你們蒙召就是為此，因為基督也為你們受過苦，給你們留下榜樣，為要使你們跟隨他的腳蹤。","notes":[]},{"n":22,"t":"「他並沒有犯罪，口裏也沒有詭詐。」","notes":[]},{"n":23,"t":"他被辱罵不還口，受害也不說威嚇的話，只將自己交託給公義的審判者。","notes":[]},{"n":24,"t":"他被掛在木頭上，親身擔當了我們的罪，使我們既然在罪上死，就得以在義上活。因他受的鞭傷，你們得了醫治。","notes":[]},{"n":25,"t":"你們從前好像迷路的羊，如今卻歸回你們靈魂的牧人和監督了。","notes":[]}]},"3":{"heading":"妻子和丈夫","verses":[{"n":1,"t":"同樣，你們作妻子的，要順服自己的丈夫，這樣，即使有不信從道理的丈夫，也會因妻子的品行，並非言語，而感化過來，","notes":[]},{"n":2,"t":"因為看見了你們敬虔純潔的品行。","notes":[]},{"n":3,"t":"你們不要藉外表來妝飾自己，如編頭髮，戴金飾，穿美麗的衣裳等，","notes":[]},{"n":4,"t":"而要有蘊藏在人內心不衰退的美，以溫柔嫻靜的心妝飾自己；這在神面前是極寶貴的。","notes":[]},{"n":5,"t":"因為古時仰賴神的聖潔婦人正是以此為妝飾，順服自己的丈夫。","notes":[]},{"n":6,"t":"就如撒拉聽從亞伯拉罕，稱他為主。你們只要行善，不怕任何恐嚇，就成為撒拉的女兒了。","notes":[]},{"n":7,"t":"同樣，你們作丈夫的，要按情理跟妻子共同生活，體貼女性是比較軟弱的器皿；要尊重她，因為她也與你一同承受生命之恩。這樣，你們的禱告就不會受阻礙。","notes":["「情理」：原文直譯「知識」。"]},{"n":8,"t":"總而言之，你們都要同心，彼此體恤，相愛如弟兄，存憐憫和謙卑的心。","notes":[],"heads":["為義受苦"]},{"n":9,"t":"不要以惡報惡，以辱罵還辱罵，倒要祝福，因為你們正是為此蒙召的，好使你們承受福氣。","notes":[]},{"n":10,"t":"因為經上說：「凡要愛惜生命、享受好日子的人，要禁止舌頭不出惡言，嘴唇不說詭詐的話。","notes":[]},{"n":11,"t":"也要棄惡行善，尋求和睦，一心追求。","notes":[]},{"n":12,"t":"因為主的眼看顧義人，他的耳聽他們的祈禱；但主向行惡的人變臉。」","notes":[]},{"n":13,"t":"你們若熱心行善，有誰會害你們呢？","notes":[]},{"n":14,"t":"即使你們為義受苦，也是有福的。不要怕人的威嚇，也不要驚慌；","notes":[]},{"n":15,"t":"只要心裏奉主基督為聖，尊他為主。有人問你們心中盼望的理由，要隨時準備答覆；","notes":[]},{"n":16,"t":"不過，要以溫柔、敬畏的心回答。要存無虧的良心，使你們在何事上被毀謗，就在何事上使那些凌辱你們在基督裏有好品行的人自覺羞愧。","notes":[]},{"n":17,"t":"神的旨意若是要你們因行善受苦，這總比因行惡受苦好。","notes":[]},{"n":18,"t":"因為基督也曾一次為罪受苦 ，就是義的代替不義的，為要引領你們到神面前。在肉體裏，他被治死；但在靈裏，他復活了。","notes":["「受苦」：有古卷是「受死」。","「你們」：有古卷是「我們」。"]},{"n":19,"t":"他藉這靈也曾去向那些在監獄裏的靈傳道，","notes":[]},{"n":20,"t":"就是那些從前在挪亞預備方舟、神容忍等待的時候不信從的人。當時進入方舟，藉著水得救的不多，只有八個人。","notes":[]},{"n":21,"t":"這水所預表的洗禮，現在藉著耶穌基督的復活拯救你們，不是除掉肉體的污穢，而是向神懇求有無虧的良心。","notes":[]},{"n":22,"t":"耶穌已經到天上去，在神的右邊，眾天使、有權柄的、有權能的都服從了他。","notes":[]}]},"4":{"heading":"神恩賜的好管家","verses":[{"n":1,"t":"既然基督在肉身受苦，你們也該將這樣的心志作為兵器，因為在肉身受過苦的已經與罪斷絕了，","notes":[]},{"n":2,"t":"使你們從今以後不再隨從人的情慾，只順從神的旨意，在世度餘下的光陰。","notes":[]},{"n":3,"t":"因為你們從前隨從外邦人的心意，生活在淫蕩、情慾、醉酒、荒宴、狂飲和可憎的偶像崇拜中，時候已經夠了。","notes":[]},{"n":4,"t":"在這些事上，他們見你們不與他們同奔放蕩無度的路就以為怪，毀謗你們。","notes":[]},{"n":5,"t":"他們必須在那位將要審判活人死人的主面前交賬。","notes":[]},{"n":6,"t":"為此，死人也曾有福音傳給他們，要使他們的肉體按著人受審判，他們的靈卻靠神活著。","notes":[]},{"n":7,"t":"萬物的結局近了。所以你們要謹慎自守，要警醒禱告。","notes":[]},{"n":8,"t":"最要緊的是彼此切實相愛，因為愛能遮掩許多的罪。","notes":[]},{"n":9,"t":"你們要互相款待，不發怨言。","notes":[]},{"n":10,"t":"人人要照自己所得的恩賜彼此服事，作神各種恩賜的好管家。","notes":[]},{"n":11,"t":"若有人講道，他要按著神的聖言講；若有人服事，他要按著神所賜的力量服事，好讓神在凡事上因耶穌基督得榮耀。願榮耀和權能都歸給他，直到永永遠遠。阿們！","notes":[]},{"n":12,"t":"親愛的，有火一般的考驗臨到你們，不要奇怪，似乎是遭遇非常的事；","notes":[],"heads":["基督徒的受苦"]},{"n":13,"t":"倒要歡喜，因為你們是與基督一同受苦，使你們在他榮耀顯現的時候也可以歡喜快樂。","notes":[]},{"n":14,"t":"你們若為基督的名受辱罵是有福的，因為榮耀的靈，就是神的靈，在你們身上。","notes":[]},{"n":15,"t":"你們中間，不可有人因為殺人、偷竊、作惡、好管閒事而受苦。","notes":[]},{"n":16,"t":"若有人因是基督徒而受苦，不要引以為恥，倒要因這名而歸榮耀給神。","notes":[]},{"n":17,"t":"因為時候到了，審判要從神的家開始；若是先從我們開始，那麼，不信從神福音的人將有何等的結局呢？","notes":[]},{"n":18,"t":"「若是義人還僅僅得救，不虔敬和犯罪的人將有何地可站呢？」","notes":[]},{"n":19,"t":"所以，照神旨意受苦的人要一心為善，將自己的靈魂交給那信實的造物主。","notes":[]}]},"5":{"heading":"牧養神的羊群","verses":[{"n":1,"t":"所以，我這同作長老，作基督受苦的證人和分享將來所要顯現的榮耀的人，勉勵在你們中間的長老們：","notes":[]},{"n":2,"t":"務要牧養在你們當中神的群羊，按著神的旨意照顧他們，不是出於勉強，而是出於甘心；也不是因為貪財，而是出於樂意。","notes":["「按著…他們」：有古卷沒有「按著神的旨意」；另有古卷沒有「照顧他們」。"]},{"n":3,"t":"不要轄制所託付你們的群羊，而是要作他們的榜樣。","notes":[]},{"n":4,"t":"到了大牧人顯現的時候，你們必得到那永不衰殘、榮耀的冠冕。","notes":[]},{"n":5,"t":"同樣，你們年輕的，要順服年長的。你們大家都要以謙卑當衣服穿上，彼此順服，因為「神抵擋驕傲的人，但賜恩給謙卑的人。」","notes":[]},{"n":6,"t":"所以，你們要謙卑服在神大能的手下，這樣，到了適當的時候，他必使你們升高。","notes":[]},{"n":7,"t":"你們要將一切的憂慮卸給神，因為他顧念你們。","notes":[]},{"n":8,"t":"務要謹慎，要警醒。因為你們的仇敵魔鬼，如同咆哮的獅子，走來走去，尋找可吞吃的人。","notes":[]},{"n":9,"t":"你們要用堅固的信心抵擋他，因為知道你們在世上的眾弟兄也正在經歷這樣的苦難。","notes":[]},{"n":10,"t":"那賜一切恩典的神曾在基督裏召了你們，得享他永遠的榮耀，在你們暫受苦難之後，必要親自成全你們，堅固你們，賜力量給你們，建立你們。","notes":["有古卷加「耶穌」。","有古卷沒有「建立你們」。"]},{"n":11,"t":"願權能歸給他，直到永永遠遠。阿們！","notes":[]},{"n":12,"t":"我簡單地寫了這信，託我所看為忠心的弟兄西拉交給你們，勸勉你們，又證明這恩是神真實的恩典；你們務要在這恩上站立得住。","notes":[],"heads":["問安"]},{"n":13,"t":"在巴比倫與你們同蒙揀選的教會向你們問安。我兒子馬可也向你們問安。","notes":[]},{"n":14,"t":"你們要用愛心彼此親吻問安。願平安歸給你們所有在基督裏的人！","notes":["「平安」或譯「和平」。"]}]}},"2PE":{"1":{"heading":"問候","verses":[{"n":1,"t":"耶穌基督的僕人和使徒西門‧彼得寫信給那因我們的神和救主耶穌基督的義，與我們同得一樣寶貴信心的人。","notes":["有古卷是「西面‧彼得」。","有古卷沒有「和」。"]},{"n":2,"t":"願恩惠、平安，因你們認識神和我們的主耶穌，多多加給你們！","notes":["「平安」或譯「和平」。"]},{"n":3,"t":"神的神能已把一切關乎生命和虔敬的事賜給我們，因我們認識那用自己榮耀和美德召我們的神。","notes":[],"heads":["信徒的蒙召和被選"]},{"n":4,"t":"因此，他已把又寶貴又極大的應許賜給我們，使我們既脫離世上從情慾來的敗壞，就得分享神的本性。","notes":[]},{"n":5,"t":"正因這緣故，你們要分外地努力。有了信心，又要加上德行；有了德行，又要加上知識；","notes":[]},{"n":6,"t":"有了知識，又要加上節制；有了節制，又要加上忍耐；有了忍耐，又要加上虔敬；","notes":[]},{"n":7,"t":"有了虔敬，又要加上愛弟兄的心；有了愛弟兄的心，又要加上愛眾人的心。","notes":[]},{"n":8,"t":"你們有了這幾樣，再繼續增長，就必使你們在認識我們的主耶穌基督上，不至於懶散和不結果子了。","notes":[]},{"n":9,"t":"沒有這幾樣的人就是瞎眼，是短視，忘了他過去的罪已經得了潔淨。","notes":[]},{"n":10,"t":"所以，弟兄們，要更加努力，使你們的蒙召和被選堅定不移。你們實行這幾樣，就永不失腳。","notes":[]},{"n":11,"t":"這樣，必叫你們豐豐富富地得以進入我們主－救主耶穌基督永遠的國度。","notes":[]},{"n":12,"t":"雖然你們已經知道這些事，並且在你們已有的真道上得到堅固，我還是要常常提醒你們這些事。","notes":[]},{"n":13,"t":"我認為趁我還在這帳棚的時候，應該激發你們的記憶，","notes":[]},{"n":14,"t":"因為知道我脫離這帳棚的時候快到了，正如我們的主耶穌基督所指示我的。","notes":[]},{"n":15,"t":"我也要盡心竭力，使你們在我去世以後時常記念這些事。","notes":[]},{"n":16,"t":"我們從前把我們主耶穌基督的大能和他來臨的事告訴你們，並不是隨從一些捏造出來的無稽傳說，我們是曾經親眼見過他的威榮的人。","notes":[],"heads":["基督的榮耀和先知的信息"]},{"n":17,"t":"他從父神得尊貴榮耀的時候，從至高無上的榮耀有聲音出來，對他說：「這是我的愛子，我所喜悅的。」","notes":[]},{"n":18,"t":"我們同他在聖山的時候，親自聽見這聲音從天上出來。","notes":[]},{"n":19,"t":"我們有先知更確實的信息，你們要好好地留意這信息，如同留意照耀在暗處的明燈，直等到天亮，晨星在你們心裏升起的時候。","notes":[]},{"n":20,"t":"第一要緊的，你們要知道，經上所有的預言是不可隨私意解釋的，","notes":[]},{"n":21,"t":"因為預言從來沒有出於人意的，而是人被聖靈感動說出神的話來。","notes":[]}]},"2":{"heading":"假先知和假教師","verses":[{"n":1,"t":"從前在民間有假先知起來；同樣，將來在你們中間也會有假教師，偷偷地引進使人滅亡的異端。他們甚至不認買他們的主人，自取迅速滅亡。","notes":[]},{"n":2,"t":"許多人會隨從他們淫蕩的行為，以致真理之道因他們的緣故被毀謗。","notes":[]},{"n":3,"t":"他們因貪婪，要用捏造的言語在你們身上取得利益。他們的懲罰，自古以來並不遲延；他們的滅亡也必迅速來到。","notes":[]},{"n":4,"t":"既然神沒有寬容犯了罪的天使，反而把他們丟在地獄裏，囚禁在幽暗中等候審判；","notes":[]},{"n":5,"t":"既然神也沒有寬容上古的世界，曾叫洪水臨到那不敬虔的世界，只保護了報公義信息的挪亞一家八口；","notes":[]},{"n":6,"t":"既然神判決了所多瑪和蛾摩拉，將二城傾覆，焚燒成灰，作為後世不敬虔人的鑒戒，","notes":["有古卷沒有「傾覆」。"]},{"n":7,"t":"只搭救了那常為惡人的淫蕩憂傷的義人羅得—","notes":[]},{"n":8,"t":"因為那義人住在他們當中，他正義的心因天天看見和聽見他們不法的事而傷痛；","notes":[]},{"n":9,"t":"那麼，主知道搭救敬虔的人脫離試煉，把不義的人留在懲罰之下等候審判的日子，","notes":[]},{"n":10,"t":"尤其那些隨從肉體、放縱污穢的情慾、藐視主的權威的人更是如此。他們膽大任性，無懼地毀謗眾尊榮者；","notes":[]},{"n":11,"t":"就是天使，雖然力量權能更大，在對他們宣告從主來的審判的時候還不用毀謗的話。","notes":["「在對他們…的話」：有古卷沒有「從主來的」；另有古卷是「還不用毀謗的話在主面前控告他們」。"]},{"n":12,"t":"但這些人好像沒有理性的牲畜，生來就是要被捉拿宰殺的。他們毀謗自己所不知道的事，正在敗壞人的時候，自己也遭遇敗壞，","notes":[]},{"n":13,"t":"為所行的不義受不義的工錢。他們喜愛白晝狂歡，他們已被玷污，又有瑕疵，正與你們一同歡宴，以自己的詭詐為樂。","notes":[]},{"n":14,"t":"他們滿眼是淫色，是止不住的罪，引誘心不堅定的人，心中習慣了貪婪，正是被詛咒的種類。","notes":[]},{"n":15,"t":"他們離棄了正路，走入歧途，隨從比珥的兒子巴蘭的路；巴蘭就是那貪愛不義的工錢的人，","notes":["有古卷是「比索」。"]},{"n":16,"t":"他卻為自己的過犯受了責備，而那不能說話的驢以人的聲音阻止了先知的狂妄。","notes":[]},{"n":17,"t":"這些人是無水的泉源，是狂風催逼的霧氣，有漆黑的幽暗為他們存留。","notes":[]},{"n":18,"t":"他們說虛妄誇大的話，用肉體的情慾和淫蕩的事引誘那些剛脫離錯謬生活的人。","notes":[]},{"n":19,"t":"他們應許人自由，自己卻作了腐敗的奴隸，因為人被誰制伏就是誰的奴隸。","notes":[]},{"n":20,"t":"倘若他們因認識我們的主和救主耶穌基督而得以脫離世上的污穢，後來又被污穢纏住，被制伏，他們末後的景況就比先前更不好了。","notes":[]},{"n":21,"t":"他們知道義路，竟背棄了傳授給他們那神聖的誡命，倒不如不知道為妙。","notes":[]},{"n":22,"t":"俗語說得好，這話正印證在他們身上了：「狗轉過來吃自己所吐的；」又說：「豬洗淨了，又回到爛泥裏打滾。」","notes":[]}]},"3":{"heading":"主再來的應許","verses":[{"n":1,"t":"親愛的，我現在寫給你們的是第二封信。在這兩封信裏，我都提醒你們，激發你們真誠的心，","notes":[]},{"n":2,"t":"要你們記得聖先知預先所說的話和主—救主的命令，就是使徒所傳給你們的。","notes":[]},{"n":3,"t":"第一要緊的，你們要知道，在末世必有好譏誚的人隨從自己的私慾出來譏誚，","notes":[]},{"n":4,"t":"說：「他要來臨的應許在哪裏呢？因為從列祖長眠以來，萬物與起初創造的時候仍是一樣啊！」","notes":[]},{"n":5,"t":"他們故意忘記這事，就是從太古憑神的話有了天，並由水而出和藉著水而成的地；","notes":[]},{"n":6,"t":"藉著水，當時的世界被水淹沒而消滅了。","notes":[]},{"n":7,"t":"但現在的天地還是憑著神的話存留，直留到不敬虔之人受審判遭沉淪的日子，用火焚燒。","notes":[]},{"n":8,"t":"親愛的，有一件事你們不可忘記，就是：主看一日如千年，千年如一日。","notes":[]},{"n":9,"t":"主沒有遲延他的應許，就如有人以為他是遲延，其實他是寬容你們，不願一人沉淪，而是人人都來悔改。","notes":[]},{"n":10,"t":"但主的日子要像賊一樣來到；那日，天必在轟然一聲中消失，天體都要被烈火熔化，地和地上的萬物都要燒盡。","notes":["「燒盡」：有古卷是「暴露無遺」；另有古卷是「消滅」或「消失」。"]},{"n":11,"t":"既然這一切都要如此消失，你們處世為人必須聖潔敬虔，","notes":["有古卷是「我們」。"]},{"n":12,"t":"等候並催促神的日子來到。因為在那日，天要被火燒而消滅，天體都要被烈火熔化。","notes":[]},{"n":13,"t":"但照他的應許，我們等候新天新地，其中有正義常住。","notes":[]},{"n":14,"t":"所以，親愛的，既然你們等候這些事，就要竭力使自己沒有玷污，無可指責，在主前和睦；","notes":[]},{"n":15,"t":"並且要以我們主的容忍作為你們得救的機會，就如我們所親愛的弟兄保羅，照著所賜給他的智慧寫信給你們。","notes":[]},{"n":16,"t":"他一切的信上都談到這事。信中有些難明白的，那無學問、不堅定的人加以曲解，如曲解別的經書一樣，自取滅亡。","notes":[]},{"n":17,"t":"所以，親愛的，既然你們預先知道這事，就當防備，免得被惡人的錯謬誘惑，從自己穩定的立場上墜落。","notes":[]},{"n":18,"t":"你們倒要在我們的主和救主耶穌基督的恩典和知識上有長進。願榮耀歸給他，從今直到永遠之日。阿們！","notes":["有古卷沒有「阿們！」"]}]}},"1JN":{"1":{"heading":"生命之道","verses":[{"n":1,"t":"論到從起初原有的生命之道，就是我們所聽見、所看見、親眼看過、親手摸過的－","notes":[]},{"n":2,"t":"這生命已經顯現出來，我們看見了，現在又作見證，把原與父同在，並且向我們顯現過的那永遠的生命傳揚給你們－","notes":[]},{"n":3,"t":"我們把所看見、所聽見的傳揚給你們，為要使你們也與我們有團契，而我們的團契是與父和他兒子耶穌基督所共有的。","notes":[]},{"n":4,"t":"我們把這些事寫給你們，使我們的喜樂得以滿足。","notes":["「我們」：有古卷是「你們」。"]},{"n":5,"t":"神就是光，在他毫無黑暗；這是我們從主所聽見，又報給你們的信息。","notes":[],"heads":["神就是光"]},{"n":6,"t":"我們若說，我們與神有團契，卻仍在黑暗裏行走，就是說謊話，不實行真理了。","notes":[]},{"n":7,"t":"我們若在光明中行走，如同神在光明中，就彼此有團契，他兒子耶穌的血就洗淨我們一切的罪。","notes":[]},{"n":8,"t":"我們若說自己沒有罪，就是欺騙自己，真理就不在我們裏面了。","notes":[]},{"n":9,"t":"我們若認自己的罪，神是信實的，是公義的，必要赦免我們的罪，洗淨我們一切的不義。","notes":[]},{"n":10,"t":"我們若說自己沒有犯過罪，就是把神當作說謊的，他的道就不在我們裏面了。","notes":[]}]},"2":{"heading":"我們的中保基督","verses":[{"n":1,"t":"我的孩子們哪，我把這些話寫給你們，是要你們不犯罪。若有人犯罪，在父那裏我們有一位中保，就是那義者耶穌基督。","notes":[]},{"n":2,"t":"他為我們的罪作了贖罪祭，不單是為我們的罪，也是為普天下人的罪。","notes":[]},{"n":3,"t":"我們若遵守神的命令，就知道我們確實認識他。","notes":[]},{"n":4,"t":"人若說「我認識他」，卻不遵守他的命令，就是說謊話的，真理就不在他裏面了。","notes":[]},{"n":5,"t":"凡遵守他的道的，愛神的心確實地在他裏面達到完全了。由此我們知道我們是在他裏面。","notes":[]},{"n":6,"t":"凡說自己住在他裏面的，就該照著他所行的去行。","notes":[]},{"n":7,"t":"親愛的，我寫給你們的不是一條新命令，而是你們從起初所受的舊命令；這舊命令就是你們所聽過的道。","notes":[],"heads":["新命令"]},{"n":8,"t":"然而，我寫給你們的是一條新命令，在基督裏是真實的，在你們也是真實的，因為黑暗漸漸消逝，真光已經在照耀。","notes":[]},{"n":9,"t":"人若說自己在光明中，卻恨他的弟兄，他到如今還是在黑暗裏。","notes":[]},{"n":10,"t":"那愛弟兄的，就是住在光明中，他不會使人失足犯罪。","notes":["「他不會…犯罪」或譯「在光裏並沒有任何絆腳石」。"]},{"n":11,"t":"惟獨那恨弟兄的，是在黑暗裏，也在黑暗裏行走，不知道往哪裏去，因為黑暗使他的眼睛瞎了。","notes":[]},{"n":12,"t":"孩子們哪，我寫信給你們，因為你們的罪藉著基督的名得了赦免。","notes":[]},{"n":13,"t":"父老們啊，我寫信給你們，因為你們認識從起初就有的那一位。青年們哪，我寫信給你們，因為你們勝過了那惡者。","notes":[]},{"n":14,"t":"孩子們哪，我曾寫信給你們，因為你們認識父。父老們啊，我曾寫信給你們，因為你們認識從起初就有的那一位。青年們哪，我曾寫信給你們，因為你們剛強，神的道常存在你們心裏，你們也勝過了那惡者。","notes":[]},{"n":15,"t":"不要愛世界和世界上的東西，若有人愛世界，愛父的心就不在他裏面了。","notes":[]},{"n":16,"t":"因為凡世界上的東西，好比肉體的情慾、眼目的情慾和今生的驕傲，都不是從父來的，而是從世界來的。","notes":[]},{"n":17,"t":"這世界和世上的情慾都要消逝，惟獨那遵行神旨意的人永遠常存。","notes":[]},{"n":18,"t":"孩子們哪，如今是末世的時光了。你們曾聽過那敵基督者要來，現在有好些敵基督者已經出來了；由此我們就知道，如今是末世的時光了。","notes":[],"heads":["敵基督者"]},{"n":19,"t":"他們從我們中間出去，卻不是屬我們的，若是屬我們的，就必仍舊與我們同在。他們出去，這就顯明他們都不是屬我們的。","notes":[]},{"n":20,"t":"你們從那聖者受了恩膏，並且你們大家都知道。","notes":["「你們大家都知道」：有古卷是「你們知道這一切的事」。"]},{"n":21,"t":"我寫信給你們，不是因你們不認識真理，而是因你們認識，並且知道一切虛謊都不是從真理出來的。","notes":[]},{"n":22,"t":"誰是說謊話的呢？不就是那不認耶穌為基督的嗎？那不認父與子的，這個人就是敵基督的。","notes":[]},{"n":23,"t":"凡不認子的，就沒有父；宣認子的，連父也有了。","notes":[]},{"n":24,"t":"論到你們，務要將那從起初所聽見的常存在心裏；若將從起初所聽見的存在心裏，你們就會住在子裏面，也會住在父裏面。","notes":[]},{"n":25,"t":"基督所應許我們的就是永生。","notes":[]},{"n":26,"t":"我將這些話寫給你們，是論到那些迷惑你們的人說的。","notes":[]},{"n":27,"t":"至於你們，你們從基督所受的恩膏常存在你們心裏，並不用人教導你們，自有他的恩膏在凡事上教導你們。這恩膏是真的，不是假的，你們要按這恩膏的教導住在他裏面。","notes":[]},{"n":28,"t":"孩子們哪，你們要住在基督裏面。這樣，他若顯現，我們就可以坦然無懼；當他來臨的時候，在他面前不至於慚愧。","notes":[],"heads":["神的兒女"]},{"n":29,"t":"你們若知道他是公義的，就知道凡行公義的人都是他所生的。","notes":[]}]},"3":{"heading":"彼此相愛","verses":[{"n":1,"t":"你們看父賜給我們的是何等的慈愛，讓我們得以稱為神的兒女；我們也真是他的兒女。世人不認識我們的理由，是因他們未曾認識父。","notes":["「我們」：有古卷是「你們」。"]},{"n":2,"t":"親愛的，我們現在是神的兒女，將來如何還未顯明。我們所知道的是：基督顯現的時候，我們會像他，因為我們將見到他的本相。","notes":[]},{"n":3,"t":"凡對他有這指望的，就潔淨自己，像他是潔淨的一樣。","notes":[]},{"n":4,"t":"凡犯罪的，就是做違背律法的事；違背律法就是罪。","notes":[]},{"n":5,"t":"你們知道，基督曾顯現是要除掉罪；在他並沒有罪。","notes":["「罪」：有古卷是「我們的罪」；另有古卷是「世人的罪」。"]},{"n":6,"t":"凡住在他裏面的，不犯罪；凡犯罪的，未曾看見他，也未曾認識他。","notes":[]},{"n":7,"t":"孩子們哪，不要讓人迷惑了你們；行義的才是義人，正如基督是義的。","notes":[]},{"n":8,"t":"犯罪的是出於魔鬼，因為魔鬼從起初就犯罪。神的兒子顯現出來，是為了要毀滅魔鬼的作為。","notes":[]},{"n":9,"t":"凡從神生的，不犯罪，因神的道存在他裏面，他也不能犯罪，因為他是由神所生的。","notes":["「道」：原文直譯「種」。"]},{"n":10,"t":"這就顯明誰是神的兒女，誰是魔鬼的兒女了。凡不行義的，不是出於神，不愛他弟兄的，也是如此。","notes":[]},{"n":11,"t":"我們要彼此相愛。這就是你們從起初所聽到的信息。","notes":[]},{"n":12,"t":"不要像該隱；他是屬那邪惡者，殺了自己的弟弟。為甚麼殺了他呢？因為自己的行為是邪惡的，而弟弟的行為是正直的。","notes":[]},{"n":13,"t":"弟兄們，世人若恨你們，不要驚訝。","notes":[]},{"n":14,"t":"我們知道，我們已經出死入生了，因為我們愛弟兄。沒有愛心的，仍住在死中。","notes":[]},{"n":15,"t":"凡恨自己弟兄的，就是殺人的；你們知道，凡殺人的，沒有永生住在他裏面。","notes":[]},{"n":16,"t":"基督為我們捨命，我們從此就知道何為愛；我們也當為弟兄捨命。","notes":[]},{"n":17,"t":"凡有世上財物的，看見弟兄缺乏，卻關閉了惻隱的心，神的愛怎能住在他裏面呢？","notes":[]},{"n":18,"t":"孩子們哪，我們相愛，不要只在言語或舌頭上，總要以行為和真誠表現出來。","notes":[]},{"n":19,"t":"從這一點，我們會知道，我們是出於真理的，並且我們在神面前可以安心，","notes":[],"heads":["在神面前坦然無懼"]},{"n":20,"t":"即使我們的心責備自己，神比我們的心大，他知道一切。","notes":[]},{"n":21,"t":"親愛的，我們的心若不責備我們，在神面前就可以坦然無懼了。","notes":[]},{"n":22,"t":"我們一切所求的，就從他得著，因為我們遵守他的命令，行他所喜悅的事。","notes":[]},{"n":23,"t":"神的命令就是：我們要信他兒子耶穌基督的名，並且照他所賜給我們的命令彼此相愛。","notes":[]},{"n":24,"t":"遵守神命令的，住在神裏面，而神也住在他裏面。從這一點，我們知道神住在我們裏面，這是由於他所賜給我們的聖靈。","notes":[]}]},"4":{"heading":"神的靈和敵基督者的靈","verses":[{"n":1,"t":"親愛的，一切的靈不可都信，總要察驗那些靈是否出於神，因為有許多假先知已經來到世上。","notes":[]},{"n":2,"t":"凡宣認耶穌基督是成了肉身而來的靈就是出於神的，由此你們可以認出神的靈來；","notes":[]},{"n":3,"t":"凡不宣認耶穌的靈，不是出於神。這是那敵基督者的靈；你們從前聽見他要來，現在他已經在世上了。","notes":[]},{"n":4,"t":"孩子們哪，你們是屬神的，並且勝過了假先知，因為那在你們裏面的比那在世界上的更大。","notes":[]},{"n":5,"t":"他們是屬世界的，所以講論世界的事，而世人也聽從他們。","notes":[]},{"n":6,"t":"我們是屬神的，認識神的就聽從我們；不屬神的就不聽從我們。從此我們可以認出真理的靈和錯謬的靈來。","notes":[]},{"n":7,"t":"親愛的，我們要彼此相愛，因為愛是從神來的。凡有愛的都是由神而生，並且認識神。","notes":[],"heads":["神就是愛"]},{"n":8,"t":"沒有愛的就不認識神，因為神就是愛。","notes":[]},{"n":9,"t":"神差他獨一的兒子到世上來，使我們藉著他得生命；由此，神對我們的愛就顯明了。","notes":[]},{"n":10,"t":"不是我們愛神，而是神愛我們，差他的兒子為我們的罪作了贖罪祭；這就是愛。","notes":[]},{"n":11,"t":"親愛的，既然神這樣愛我們，我們也要彼此相愛。","notes":[]},{"n":12,"t":"從來沒有人見過神，我們若彼此相愛，神就住在我們裏面，他的愛在我們裏面得以完滿了。","notes":[]},{"n":13,"t":"因為神將他的靈賜給我們，由此我們知道我們是住在他裏面，而他也住在我們裏面。","notes":[]},{"n":14,"t":"父差子作世人的救主，這是我們所看見並且作見證的。","notes":[]},{"n":15,"t":"凡宣認耶穌為神兒子的，神就住在他裏面，而他也住在神裏面。","notes":[]},{"n":16,"t":"我們知道並且深信神是愛我們的。神就是愛，住在愛裏面的就是住在神裏面；神也住在他裏面。","notes":[]},{"n":17,"t":"由此，愛在我們裏面得以完滿：我們可以在審判的日子坦然無懼，因為基督如何，我們在這世上也如何。","notes":[]},{"n":18,"t":"在愛裏沒有懼怕；完滿的愛把懼怕驅逐出去，因為懼怕裏含著懲罰，懼怕的人在愛裏尚未得到完滿。","notes":[]},{"n":19,"t":"我們愛，因為神先愛我們。","notes":[]},{"n":20,"t":"人若說「我愛神」，卻恨他的弟兄，就是說謊了；不愛他看得見的弟兄，就不能愛看不見的神。","notes":["有古卷是「怎能愛沒有看見的神呢？」"]},{"n":21,"t":"愛神的，也要愛弟兄；這是我們從神所受的命令。","notes":[]}]},"5":{"heading":"信心使我們勝過世界","verses":[{"n":1,"t":"凡信耶穌是基督的，都是從神生的；凡愛生他之神的，也必愛從神生的。","notes":["「凡信…神生的」或譯「凡愛那生他的，也要愛那由他而生的」。"]},{"n":2,"t":"我們愛神，又實行他的命令，由此就知道我們愛神的兒女了。","notes":["有古卷是「遵行」。"]},{"n":3,"t":"我們遵守神的命令，這就是愛他了，而且他的命令並不是難守的。","notes":[]},{"n":4,"t":"因為凡從神生的就勝過世界；使我們勝過世界的就是我們的信心。","notes":[]},{"n":5,"t":"勝過世界的是誰呢？不就是那信耶穌是神兒子的嗎？","notes":[]},{"n":6,"t":"這藉著水和血而來的，就是耶穌基督，不是單用水，而是用水又用血，並且有聖靈作見證，因為聖靈就是真理。","notes":[],"heads":["神為他兒子作的見證"]},{"n":7,"t":"作見證的有三：","notes":[]},{"n":8,"t":"就是聖靈、水與血，這三樣也都是一致的。","notes":[]},{"n":9,"t":"既然我們領受人的見證，神的見證更該領受了，因為神的見證是為他兒子作的。","notes":["「該領受」：原文直譯「大」。"]},{"n":10,"t":"信神兒子的，就有這見證在他心裏；不信神的，就是把神當作說謊的，因為不信神為他兒子作的見證。","notes":[]},{"n":11,"t":"這見證就是：神賜給我們永生，而這永生是在他兒子裏面的。","notes":[]},{"n":12,"t":"那有神兒子的，就有生命；沒有神兒子的，就沒有生命。","notes":[]},{"n":13,"t":"我把這些話寫給你們信奉神兒子之名的人，要讓你們知道自己有永生。","notes":[],"heads":["知道自己有永生"]},{"n":14,"t":"我們若照著神的旨意祈求，他就垂聽我們；這就是我們對他所存坦然無懼的心。","notes":[]},{"n":15,"t":"既然我們知道他聽我們一切所求的，就知道我們所求於他的，無不得著。","notes":[]},{"n":16,"t":"人若看見弟兄犯了不至於死的罪，就要為他祈求，神必將生命賜給他—有些人犯的罪是不至於死的；有的是至於死的罪，我不是說要為這罪祈求。","notes":[]},{"n":17,"t":"一切不義的事都是罪，但也有不至於死的罪。","notes":[]},{"n":18,"t":"我們知道，凡從神生的，必不犯罪；從神生的那一位，必保守他，那邪惡者無法加害於他。","notes":[]},{"n":19,"t":"我們知道，我們是屬神的，而全世界都伏在那邪惡者的權勢之下。","notes":[]},{"n":20,"t":"我們知道，神的兒子已經來到，並且將悟性賜給我們，使我們認識那位真實者，我們也在那位真實者裏面，就是在他兒子耶穌基督裏面。這是真神，也是永生。","notes":[]},{"n":21,"t":"孩子們哪，你們要遠避偶像。","notes":[]}]}},"2JN":{"1":{"heading":"問候","verses":[{"n":1,"t":"我作長老的寫信給蒙揀選的夫人和她的兒女，就是我真心所愛的；不但我愛，也是一切認識真理的人所愛的，","notes":["「夫人」或譯「教會」；5節同。"]},{"n":2,"t":"這是因為真理住在我們裏面，也必與我們同在直到永遠。","notes":[]},{"n":3,"t":"願恩惠、憐憫、平安從父神和他兒子耶穌基督，在真理和愛中必與我們同在。","notes":["「平安」或譯「和平」。"]},{"n":4,"t":"我非常歡喜見你的兒女，有照我們從父所受之命令遵行真理的。","notes":[],"heads":["真理和愛"]},{"n":5,"t":"夫人哪，我現在請求你，我們大家要彼此相愛。我寫給你的，並不是一條新命令，而是我們從起初就有的。","notes":[]},{"n":6,"t":"這就是愛，就是照他的命令行事；這就是命令，你們要照這命令行，正如你們從起初所聽見的。","notes":[]},{"n":7,"t":"有許多迷惑人的已經來到世上，他們不宣認耶穌基督是成了肉身來的；這樣的人是迷惑人的，是敵基督的。","notes":[]},{"n":8,"t":"你們要小心，不要失去你們所完成的工作，而要得到充足的賞賜。","notes":["「你們」：有古卷是「我們」。"]},{"n":9,"t":"凡越過基督的教導而不持守的，就沒有神；凡持守這教導的，就有父又有子。","notes":[]},{"n":10,"t":"若有人到你們那裏而不傳這教導，不要接他到家裏，也不要向他問安；","notes":[]},{"n":11,"t":"因為向他問安的，就在他的惡行上有份。","notes":[]},{"n":12,"t":"我還有許多事要寫給你們，卻不願意用紙用墨，但盼望到你們那裏，與你們面對面談論，使我們的喜樂得以滿足。","notes":[],"heads":["結束的問安"]},{"n":13,"t":"你那蒙揀選的姊妹的兒女向你問安。","notes":[]}]}},"3JN":{"1":{"heading":"問候","verses":[{"n":1,"t":"我作長老的寫信給親愛的該猶，就是我真心所愛的。","notes":[]},{"n":2,"t":"親愛的，我願你事事安寧，身體健康，正如你的心神安寧一樣。","notes":[]},{"n":3,"t":"我非常歡喜，有弟兄到這裏來，證實你對真理的忠誠，就是你按著真理而行。","notes":[]},{"n":4,"t":"我聽見我的兒女按真理而行，我的歡喜沒有比這個更大的。","notes":[]},{"n":5,"t":"親愛的，你對弟兄，特別是對作客旅的弟兄所做的都是忠誠的。","notes":[],"heads":["合作和反對"]},{"n":6,"t":"他們在教會面前證實了你的愛；你若以對得起神的方式，為他們送行就好了；","notes":[]},{"n":7,"t":"因為他們是為基督的名出外，並沒有從未信的人接受甚麼。","notes":["「基督的名」： 原文直譯「那名」。"]},{"n":8,"t":"所以，我們應當接待這樣的人，好讓我們與他們在真理上成為同工。","notes":[]},{"n":9,"t":"我曾寫過一些東西給教會，但他們中間那好作領袖的丟特腓不接納我們。","notes":[]},{"n":10,"t":"為此，我若去，要提起他所做的事，就是他用惡言攻擊我們，還不滿足，他自己不接納弟兄，有人願意接納，他還阻止，並且把接納弟兄的人趕出教會。","notes":[]},{"n":11,"t":"親愛的，不要效法惡，只要效法善。行善的人屬乎神；行惡的人未曾見過神。","notes":[]},{"n":12,"t":"低米丟行善，有眾人給他作見證，又有真理給他作見證，就是我們也給他作見證，你知道我們的見證是真的。","notes":[]},{"n":13,"t":"我還有許多事要寫給你，卻不願意用筆墨來寫給你，","notes":[],"heads":["問安"]},{"n":14,"t":"但盼望很快見到你，我們好面對面談論。","notes":[]},{"n":15,"t":"願你平安！朋友們都向你問安。請你替我按著名字一一向朋友們問安。","notes":[]}]}},"JUD":{"1":{"heading":"假教師受懲罰","verses":[{"n":1,"t":"耶穌基督的僕人、雅各的兄弟猶大，寫信給那些被召、在父神裏蒙愛、為耶穌基督保守的人。","notes":[]},{"n":2,"t":"願憐憫、平安、慈愛多多加給你們！","notes":["「平安」或譯「和平」。"]},{"n":3,"t":"親愛的，我一直很迫切地想要寫信給你們，論到我們同享的救恩，但我覺得有必要現在就寫信勸你們，要為從前一次交付給聖徒的真道竭力奮鬥。","notes":[]},{"n":4,"t":"因為有些人偷偷地進來，就是早就被判定受懲罰的不虔誠的人，他們把我們神的恩典變為放縱情慾的機會，並且不認獨一的主宰—我們的主耶穌基督。","notes":[]},{"n":5,"t":"這一切的事，你們雖然知道，我卻仍要提醒你們：從前主只一次就救了他的百姓出埃及地，後來卻把那些不信的滅絕了。","notes":["「主」：有古卷是「耶穌」；另有古卷是「神」。","「只一次就」：有古卷把這句話放在「你們雖然」後面。"]},{"n":6,"t":"至於那些不守本位、離開自己住處的天使，主用鎖鏈把他們永遠拘留在黑暗裏，等候大日子的審判。","notes":[]},{"n":7,"t":"同樣，所多瑪、蛾摩拉和周圍城鎮的人也跟著他們一樣犯淫亂，隨從逆性的情慾，以致遭受永不熄滅之火的懲罰，作為眾人的鑒戒。","notes":[]},{"n":8,"t":"照樣，這些做夢的人也污穢身體，輕慢掌權者，毀謗眾尊榮者。","notes":[]},{"n":9,"t":"天使長米迦勒為摩西的屍首與魔鬼爭辯的時候，尚且不敢用毀謗的話譴責他，只說：「主責備你吧！」","notes":[]},{"n":10,"t":"但這些人毀謗他們所不知道的。他們與那些沒有理性的牲畜一樣，只做本性所知道的事，敗壞了自己。","notes":[]},{"n":11,"t":"他們有禍了！因為他們走該隱的道路，又為財利往巴蘭的錯謬裏直奔，並在可拉的背叛中滅亡了。","notes":[]},{"n":12,"t":"這樣的人是你們愛筵上的污點；他們無所懼怕地同你們宴樂，彷彿牧人只顧餵飽自己。他們是無雨的浮雲，被風飄蕩；是秋天沒有果子的樹，死而又死，連根被拔出來；","notes":["「污點」：原文或譯「礁石」。"]},{"n":13,"t":"是海裏的狂浪，湧出自己可恥的沫子來；是流蕩的星，有漆黑的幽暗永遠為他們保留著。","notes":[]},{"n":14,"t":"亞當的七世孫以諾曾預言這些人說：「看哪，主帶著他的千萬聖者來臨，","notes":[]},{"n":15,"t":"要審判眾人，證實一切不敬虔的人所妄行一切不敬虔的事，又證實不敬虔的罪人所說頂撞他的剛愎的話。」","notes":[]},{"n":16,"t":"這些人喜出怨言，責怪他人，隨從自己的情慾而行，口說誇大的話，為自己的利益諂媚人。","notes":[]},{"n":17,"t":"親愛的，至於你們，要記得我們主耶穌基督的使徒從前所說的話。","notes":[],"heads":["警告和勸勉"]},{"n":18,"t":"他們曾對你們說過，末世必有好嘲弄的人隨從自己不敬虔的私慾而行。","notes":[]},{"n":19,"t":"這就是那些好結黨分派、屬乎血氣、沒有聖靈的人。","notes":[]},{"n":20,"t":"親愛的，至於你們，要在至聖的真道上造就自己，藉著聖靈禱告，","notes":[]},{"n":21,"t":"保守自己常在神的愛中，仰望我們主耶穌基督的憐憫，進入永生。","notes":[]},{"n":22,"t":"有些人心中猶疑，你們要憐憫他們；","notes":["「心中猶疑」：有古卷是「惹起爭辯」。","「憐憫」：有古卷是「駁斥」；23節同。"]},{"n":23,"t":"有些人你們要從火中搶出來，搭救他們；有些人你們要存懼怕的心憐憫他們，連那被情慾污染的衣服也要厭惡。","notes":["有古卷是「存懼怕的心搭救他們」。"]},{"n":24,"t":"願那能保守你們不失腳，使你們無瑕無疵、歡歡喜喜站在他榮耀之前的、","notes":[],"heads":["祝福"]},{"n":25,"t":"我們的救主獨一的神，藉著我們的主耶穌基督，得享榮耀、威嚴、能力、權柄，從萬古以前，到現今，直到永永遠遠。阿們！","notes":[]}]}},"REV":{"1":{"heading":"引言和問候","verses":[{"n":1,"t":"耶穌基督的啟示，就是神賜給他，要他將必須快要發生的事指示他的眾僕人。他差遣使者指明給他的僕人約翰，","notes":[]},{"n":2,"t":"約翰就將神的道和耶穌基督的見證，凡自己所看見的，都見證出來。","notes":[]},{"n":3,"t":"誦讀這書上預言的，和那些聽見又遵守其中所記載的，都是有福的，因為時候近了。","notes":[]},{"n":4,"t":"約翰寫信給亞細亞的七個教會。願那位今在、昔在、以後永在的神，與他寶座前的七靈，和那忠信的見證者、從死人中復活的首生者、世上君王的元首耶穌基督，賜恩惠和平安給你們。他愛我們，用自己的血使我們從罪中得釋放 ，","notes":["「首生者」或譯「長子」。","「平安」或譯「和平」。","「得釋放」：有古卷是「洗去」。"],"end":5},{"n":6,"t":"又使我們成為國度，作他父神的祭司。願榮耀、權能歸給他，直到永永遠遠。阿們！","notes":["有古卷是「直到永遠」。"]},{"n":7,"t":"「看哪，他駕雲降臨；眾目都要看見他，連刺他的人也要看見他；地上的萬族要因他哀哭。」這是真實的。阿們！","notes":[]},{"n":8,"t":"主神說：「我是阿拉法，我是俄梅戛 ，是今在、昔在、以後永在的全能者。」","notes":["「阿拉法」、「俄梅戛」是希臘文首末的二個字母；21．6，22．13同。"]},{"n":9,"t":"我—約翰就是你們的弟兄，在耶穌裏和你們一同在患難、國度、忍耐裏有份的，為神的道，並為給耶穌作的見證，曾在那名叫拔摩的海島上。","notes":[],"heads":["基督向約翰顯現"]},{"n":10,"t":"有一主日我被聖靈感動，聽見在我後面有大聲音如吹號，","notes":[]},{"n":11,"t":"說：「把你所看見的寫在書上，寄給以弗所、士每拿、別迦摩、推雅推喇、撒狄、非拉鐵非、老底嘉那七個教會。」","notes":[]},{"n":12,"t":"我轉過身來要看看是誰的聲音在跟我說話。我一轉過來，看見了七個金燈臺；","notes":[]},{"n":13,"t":"在燈臺中間有一位好像人子的，身穿垂到腳的長袍，胸間束著金帶。","notes":[]},{"n":14,"t":"他的頭與髮皆白，如白羊毛，如雪；他的眼睛好像火焰，","notes":[]},{"n":15,"t":"雙腳好像在爐中鍛鍊得發亮的銅，聲音好像眾水的聲音。","notes":[]},{"n":16,"t":"他右手拿著七顆星，從他口中吐出一把兩刃的利劍，面貌好像烈日放光。","notes":[]},{"n":17,"t":"我看見了他，就仆倒在他腳前，像死人一樣。他用右手按著我說：「不要怕。我是首先的，是末後的，","notes":[]},{"n":18,"t":"又是永活的。我曾死過，看哪，我是活著的，直到永永遠遠；並且我拿著死亡和陰間的鑰匙。","notes":[]},{"n":19,"t":"所以，你要把所看見的事、現在的事和以後將發生的事，都寫下來。","notes":[]},{"n":20,"t":"至於你所看見、在我右手中的七顆星和那七個金燈臺的奧祕就是：七顆星是七個教會的使者，七個燈臺是七個教會。」","notes":[]}]},"2":{"heading":"給以弗所教會的信","verses":[{"n":1,"t":"「你要寫信給以弗所教會的使者，說：『那右手拿著七顆星，在七個金燈臺中間行走的這樣說：","notes":[]},{"n":2,"t":"我知道你的行為、勞碌、忍耐，也知道你不容忍惡人。你也曾察驗那自稱為使徒卻不是使徒的，看出他們是假的。","notes":[]},{"n":3,"t":"你能忍耐，曾為我的名勞苦而不困倦。","notes":[]},{"n":4,"t":"然而，有一件事我要責備你，就是你把起初的愛心拋棄了。","notes":[]},{"n":5,"t":"所以你要回想你是從哪裏墜落的，並且要悔改，做起初所做的工作。你若不悔改，我要到你那裏去，把你的燈臺從原處挪去。","notes":[]},{"n":6,"t":"然而你還有一件可取的事，就是你恨惡尼哥拉派的行為，這種行為也是我所恨惡的。","notes":[]},{"n":7,"t":"凡有耳朵的都應當聽聖靈向眾教會所說的話。得勝的，我必將神樂園中生命樹的果子賜給他吃。』」","notes":[]},{"n":8,"t":"「你要寫信給士每拿教會的使者，說：『那首先的、末後的，死過又活了的這樣說：","notes":[],"heads":["給士每拿教會的信"]},{"n":9,"t":"我知道你的患難和貧窮—其實你卻是富足的，也知道那自稱是猶太人的所說毀謗的話，其實他們不是猶太人，而是撒但會堂的人。","notes":[]},{"n":10,"t":"你將要受的苦，你不用怕。看哪！魔鬼要把你們中間幾個人下在監裏，使你們受考驗，你們要遭受苦難十日。你務要至死忠心，我就賜給你那生命的冠冕。","notes":[]},{"n":11,"t":"凡有耳朵的都應當聽聖靈向眾教會所說的話。得勝的必不受第二次死的害。』」","notes":[]},{"n":12,"t":"「你要寫信給別迦摩教會的使者，說：『那有兩刃利劍的這樣說：","notes":[],"heads":["給別迦摩教會的信"]},{"n":13,"t":"我知道你的居所，就是有撒但座位之處；當我忠心的見證人安提帕在你們中間，在撒但所住的地方被殺之時，你還堅守我的名，沒有否認對我的信仰。","notes":[]},{"n":14,"t":"然而，有幾件事我要責備你，就是在你那裏有人服從了巴蘭的教訓；這巴蘭曾教唆巴勒將絆腳石放在以色列人面前，使他們吃祭過偶像之物，並且犯淫亂。","notes":[]},{"n":15,"t":"同樣，你那裏也有人服從了尼哥拉派的教訓。","notes":[]},{"n":16,"t":"所以，你當悔改；若不悔改，我很快就到你那裏來，用我口中的劍攻擊他們。","notes":[]},{"n":17,"t":"凡有耳朵的都應當聽聖靈向眾教會所說的話。得勝的，我必將那隱藏的嗎哪賜給他，並賜他一塊白石，石上寫著新的名字，除了那領受的以外，沒有人認識。』」","notes":[]},{"n":18,"t":"「你要寫信給推雅推喇教會的使者，說：『神的兒子，那位眼睛如火焰、雙腳像發亮的銅的這樣說：","notes":[],"heads":["給推雅推喇教會的信"]},{"n":19,"t":"我知道你的行為：愛心、信心、勤勞、忍耐；又知道你末後所行的善事比起初所行的更多。","notes":[]},{"n":20,"t":"然而，有一件事我要責備你，就是你容忍那自稱是先知的婦人耶洗別教唆我的僕人，引誘他們犯淫亂，吃祭過偶像之物。","notes":[]},{"n":21,"t":"我曾給她悔改的機會，她卻不肯悔改她的淫行。","notes":[]},{"n":22,"t":"看吧，我要使她病倒在床上。那些與她犯姦淫的人若不悔改他們的行為，我也要使他們同受大患難。","notes":[]},{"n":23,"t":"我又要殺死她的兒女，眾教會就知道，我是那察看人肺腑心腸的，我要照你們的行為報應各人。","notes":[]},{"n":24,"t":"至於你們其餘的推雅推喇人，就是一切不隨從這教訓，不明白他們所謂撒但深奧之理的人，我告訴你們，我不會再把別的擔子放在你們身上。","notes":[]},{"n":25,"t":"你們只要持守那已經有的，直到我來。","notes":[]},{"n":26,"t":"那得勝又遵守我命令到底的，我要賜給他權柄制伏列國；","notes":[]},{"n":27,"t":"他必用鐵杖管轄他們，如同打碎陶器，","notes":[]},{"n":28,"t":"像我也從我父領受了權柄一樣。我又要把晨星賜給他。","notes":[]},{"n":29,"t":"凡有耳朵的都應當聽聖靈向眾教會所說的話。』」","notes":[]}]},"3":{"heading":"給撒狄教會的信","verses":[{"n":1,"t":"「你要寫信給撒狄教會的使者，說：『那有神的七靈和七顆星的這樣說：我知道你的行為，就是名義上你是活的，實際上你是死的。","notes":[]},{"n":2,"t":"你要警醒，堅固那些剩下、快要死的，因為我發現你的行為，在我神面前沒有一樣是完全的。","notes":[]},{"n":3,"t":"所以，要記得你所領受和聽見的；要遵守，並要悔改。你若不警醒，我必如賊一樣來到；我幾時來到你那裏，你絕不會知道。","notes":[]},{"n":4,"t":"然而，在撒狄你還有幾位是未曾污穢自己衣服的，他們會穿白衣與我同行，因為他們是配穿的。","notes":[]},{"n":5,"t":"得勝的必這樣穿白衣，我也不從生命冊上塗去他的名；我要在我父面前，和我父的眾使者面前，宣認他的名。","notes":[]},{"n":6,"t":"凡有耳朵的都應當聽聖靈向眾教會所說的話。』」","notes":[]},{"n":7,"t":"「你要寫信給非拉鐵非教會的使者，說：『那神聖、真實的，拿著大衛的鑰匙，開了就沒有人能關，關了就沒有人能開的這樣說：","notes":[],"heads":["給非拉鐵非教會的信"]},{"n":8,"t":"我知道你的行為。看哪，我在你面前給你一個敞開的門，是沒有人能關的。我知道你有一點力量，也遵守我的道，沒有否認我的名。","notes":[]},{"n":9,"t":"那屬撒但會堂的，自稱是猶太人，其實不是猶太人，而是說謊話的，我要使他們來到你腳前下拜，使他們知道我已經愛你了。","notes":[]},{"n":10,"t":"因為你遵守了我堅忍的道，我也必在普天下人受試煉的時候保守你免受試煉。","notes":[]},{"n":11,"t":"我必快來，你要持守你所有的，免得人奪去你的冠冕。","notes":[]},{"n":12,"t":"得勝的，我要使他在我神的殿中作柱子，他必不再從那裏出去。我又要把我神的名和我神城的名—從天上我神那裏降下來的新耶路撒冷，和我的新名，都寫在他上面。","notes":[]},{"n":13,"t":"凡有耳朵的都應當聽聖靈向眾教會所說的話。』」","notes":[]},{"n":14,"t":"「你要寫信給老底嘉教會的使者，說：『那位阿們、誠信真實的見證者、神創造的根源這樣說：","notes":[],"heads":["給老底嘉教會的信"]},{"n":15,"t":"我知道你的行為，你也不冷也不熱；我巴不得你或冷或熱。","notes":[]},{"n":16,"t":"既然你如溫水，也不冷也不熱，我要從我口中把你吐出去。","notes":[]},{"n":17,"t":"你說：我是富足的，已經發了財，一樣都不缺，卻不知道你是困苦、可憐、貧窮、瞎眼、赤身的。","notes":[]},{"n":18,"t":"我勸你向我買從火中鍛鍊出來的金子，使你富足；又買白衣穿上，使你赤身的羞恥不露出來；又買眼藥抹你的眼睛，使你能看見。","notes":[]},{"n":19,"t":"凡我所疼愛的，我就責備管教。所以，你要發熱心，也要悔改。","notes":[]},{"n":20,"t":"看哪，我站在門外叩門，若有聽見我聲音而開門的，我要進到他那裏去，我與他，他與我一起吃飯。","notes":[]},{"n":21,"t":"得勝的，我要賜他在我寶座上與我同坐，就如我得了勝，在我父的寶座上與他同坐一般。","notes":[]},{"n":22,"t":"凡有耳朵的都應當聽聖靈向眾教會所說的話。』」","notes":[]}]},"4":{"heading":"天上的敬拜","verses":[{"n":1,"t":"這些事以後，我觀看，看見天上有一道門開著。我頭一次聽見的那好像吹號的聲音對我說：「你上這裏來，我要把此後必須發生的事指示你。」","notes":[]},{"n":2,"t":"我立刻被聖靈感動，見有一個寶座安置在天上，有一位坐在寶座上。","notes":[]},{"n":3,"t":"那坐著的，看來好像碧玉和紅寶石；又有彩虹圍著寶座，光彩好像綠寶石。","notes":[]},{"n":4,"t":"寶座的周圍又有二十四個座位，上面坐著二十四位長老，身穿白衣，頭上戴著金冠冕。","notes":[]},{"n":5,"t":"有閃電、聲音、雷轟從寶座中發出。在寶座前點著七支火炬，就是神的七靈。","notes":[]},{"n":6,"t":"寶座前有一個如同水晶的玻璃海。寶座的周圍，四邊有四個活物，遍體前後都長滿了眼睛。","notes":[]},{"n":7,"t":"第一個活物像獅子，第二個像牛犢，第三個的臉像人臉，第四個像飛鷹。","notes":[]},{"n":8,"t":"四個活物各有六個翅膀，遍體內外都長滿了眼睛。他們晝夜不住地說：「聖哉！聖哉！聖哉！主—全能的神；昔在、今在、以後永在！」","notes":[]},{"n":9,"t":"每逢四活物將榮耀、尊貴、感謝歸給那坐在寶座上、活到永永遠遠者的時候，","notes":[]},{"n":10,"t":"二十四位長老就俯伏敬拜坐在寶座上活到永永遠遠的那一位，又把他們的冠冕放在寶座前，說：","notes":[]},{"n":11,"t":"「我們的主，我們的神，你配得榮耀、尊貴、權柄，因為你創造了萬物，萬物因你的旨意被創造而存在。」","notes":[]}]},"5":{"heading":"書卷和羔羊","verses":[{"n":1,"t":"我看見坐在寶座那位的右手中有書卷，正反面都寫著字，用七個印密封著。","notes":[]},{"n":2,"t":"我又看見一位大力的天使大聲宣告說：「有誰配展開那書卷，揭開那七個印呢？」","notes":[]},{"n":3,"t":"在天上、地上、地底下，沒有人能展開、能閱覽那書卷。","notes":[]},{"n":4,"t":"因為沒有人配展開、閱覽那書卷，我就大哭。","notes":[]},{"n":5,"t":"長老中有一位對我說：「不要哭。看哪，猶大支派中的獅子，大衛的根，他已得勝，能展開那書卷，揭開那七個印。」","notes":[]},{"n":6,"t":"我又看見寶座和四個活物，以及長老之中有羔羊站著，像是被殺的，有七個角七隻眼睛，就是神的七靈，奉差遣往普天下去的。","notes":["有古卷沒有「七」。"]},{"n":7,"t":"這羔羊前來，從坐在寶座上那位的右手中拿了書卷。","notes":[]},{"n":8,"t":"他一拿了書卷，四活物和二十四位長老就俯伏在羔羊面前，各拿著琴和盛滿了香的金爐；這香就是眾聖徒的祈禱。","notes":[]},{"n":9,"t":"他們唱新歌，說：「你配拿書卷，配揭開它的七印；因為你曾被殺，用自己的血從各支派、各語言、各民族、各邦國中買了人來，使他們歸於神，","notes":[]},{"n":10,"t":"又使他們成為國民和祭司，歸於我們的神；他們將在地上執掌王權。」","notes":[]},{"n":11,"t":"我又觀看，我聽見寶座和活物及長老的周圍有許多天使的聲音；他們的數目有千千萬萬，","notes":[]},{"n":12,"t":"大聲說：「被殺的羔羊配得權能、豐富、智慧、力量、尊貴、榮耀、頌讚。」","notes":[]},{"n":13,"t":"我又聽見在天上、地上、地底下、滄海裏和天地間一切所有被造之物，都說：「願頌讚、尊貴、榮耀、權勢，都歸給坐在寶座上的那位和羔羊，直到永永遠遠！」","notes":[]},{"n":14,"t":"四活物就說：「阿們！」眾長老也俯伏敬拜。","notes":[]}]},"6":{"heading":"揭開密封的印","verses":[{"n":1,"t":"我看見羔羊揭開七個印中第一個印的時候，聽見四活物中的一個活物，聲音如雷，說：「你來！」","notes":[]},{"n":2,"t":"我就觀看，看見一匹白馬，騎在馬上的拿著弓，並有冠冕賜給他。他出來征服，勝而又勝。","notes":[]},{"n":3,"t":"羔羊揭開第二個印的時候，我聽見第二個活物說：「你來！」","notes":[]},{"n":4,"t":"就另有一匹馬出來，是紅色的；有權柄賜給了那騎馬的，要從地上奪去太平，使人彼此相殺；他又接受了一把大刀。","notes":[]},{"n":5,"t":"羔羊揭開第三個印的時候，我聽見第三個活物說：「你來！」我就觀看，看見一匹黑馬；騎在馬上的，手裏拿著天平。","notes":[]},{"n":6,"t":"我聽見在四個活物中似乎有聲音說：「一個銀幣買一升麥子，一個銀幣買三升大麥；油和酒不可糟蹋。」","notes":[]},{"n":7,"t":"羔羊揭開第四個印的時候，我聽見第四個活物說：「你來！」","notes":[]},{"n":8,"t":"我就觀看，看見一匹灰色馬；騎在馬上的，名字叫作「死」，陰間也隨著他；有權柄賜給他們，可以用刀劍、饑荒、瘟疫、野獸，殺害地上四分之一的人。","notes":[]},{"n":9,"t":"羔羊揭開第五個印的時候，我看見在祭壇底下有曾為神的道，並為作見證而被殺的人的靈魂，","notes":[]},{"n":10,"t":"大聲喊著說：「神聖真實的主宰啊，你不審判住在地上的人，為我們所流的血伸冤，要到幾時呢？」","notes":[]},{"n":11,"t":"於是有白袍賜給他們各人；又有話吩咐他們還要歇息片刻，等到與他們同作僕人的，和他們的弟兄，像他們一樣被殺的人的數目湊足的時候。","notes":[]},{"n":12,"t":"羔羊揭開第六個印的時候，我看見地大震動，太陽變黑像粗麻布，整個月亮變紅像血，","notes":[]},{"n":13,"t":"天上的星辰墜落在地上，如同無花果樹被大風搖動，落下未熟的果子一樣。","notes":[]},{"n":14,"t":"天就裂開，好像書卷被捲起來；山嶺海島都被移動離開原位。","notes":[]},{"n":15,"t":"地上的君王、臣宰、將軍、富戶、壯士，和一切為奴的、自主的，都藏在山洞和巖石穴裏，","notes":[]},{"n":16,"t":"向山和巖石說：「倒在我們身上吧！把我們藏起來，躲避坐寶座者的臉面和羔羊的憤怒；","notes":[]},{"n":17,"t":"因為他們遭憤怒的大日子到了，誰能站得住呢？」","notes":[]}]},"7":{"heading":"十四萬四千以色列人受印","verses":[{"n":1,"t":"此後，我看見四位天使站在地的四角，執掌地上四方的風，使風不吹在地上、海上和各種樹上。","notes":[]},{"n":2,"t":"我又看見另有一位天使從日出之地上來，拿著永生神的印。他向那得到權柄能傷害地和海的四位天使大聲喊著，","notes":[]},{"n":3,"t":"說：「你們不可傷害地、海和樹林，等我們在我們神眾僕人的額上蓋了印。」","notes":[]},{"n":4,"t":"我聽見以色列人各支派中受印的數目有十四萬四千；","notes":[]},{"n":5,"t":"猶大支派中受印的有一萬二千；呂便支派中有一萬二千；迦得支派中有一萬二千；","notes":[]},{"n":6,"t":"亞設支派中有一萬二千；拿弗他利支派中有一萬二千；瑪拿西支派中有一萬二千；","notes":[]},{"n":7,"t":"西緬支派中有一萬二千；利未支派中有一萬二千；以薩迦支派中有一萬二千；","notes":[]},{"n":8,"t":"西布倫支派中有一萬二千；約瑟支派中有一萬二千；便雅憫支派中受印的有一萬二千。","notes":[]},{"n":9,"t":"此後，我觀看，看見有許多人，沒有人能計算，是從各邦國、各支派、各民族、各語言來的，站在寶座和羔羊面前，身穿白衣，手拿棕樹枝，","notes":[],"heads":["無數的人從各國而來"]},{"n":10,"t":"大聲喊著說：「願救恩歸於坐在寶座上我們的神，也歸於羔羊！」","notes":[]},{"n":11,"t":"眾天使都站在寶座和眾長老，以及四個活物的周圍，俯伏在寶座前，敬拜神，","notes":[]},{"n":12,"t":"說：「阿們！頌讚、榮耀、智慧、感謝、尊貴、權能、力量都歸於我們的神，直到永永遠遠。阿們！」","notes":[]},{"n":13,"t":"長老中有一位回應我說：「這些穿白衣的是誰？是從哪裏來的？」","notes":[]},{"n":14,"t":"我對他說：「我主啊，你是知道的。」他向我說：「這些人是從大患難中出來的，他們曾用羔羊的血把衣裳洗得潔白。","notes":[]},{"n":15,"t":"所以，他們在神寶座前，晝夜在他殿中事奉他；那坐在寶座上的要用帳幕覆庇他們。","notes":[]},{"n":16,"t":"他們不再飢，不再渴；太陽必不傷害他們，任何炎熱也不傷害他們，","notes":[]},{"n":17,"t":"因為寶座中的羔羊必牧養他們，領他們到生命水的泉源；神必擦去他們一切的眼淚。」","notes":[]}]},"8":{"heading":"第七個印和金香爐","verses":[{"n":1,"t":"羔羊揭開第七個印的時候，天上寂靜約有半小時。","notes":[]},{"n":2,"t":"我看見那站在神面前的七位天使，有七枝號賜給他們。","notes":[]},{"n":3,"t":"另有一位天使拿著金香爐來，站在祭壇旁邊；有許多香賜給他，要和眾聖徒的祈禱一同獻在寶座前的金壇上。","notes":[]},{"n":4,"t":"那香的煙和眾聖徒的祈禱從天使的手中一同升到神面前。","notes":[]},{"n":5,"t":"天使拿著香爐，盛滿了壇上的火，倒在地上；就有雷轟、響聲、閃電、地震。","notes":[]},{"n":6,"t":"拿著七枝號筒的七位天使預備好要吹號。","notes":[],"heads":["七枝號筒"]},{"n":7,"t":"第一位天使吹號，就有冰雹和火攙著血扔在地上；地的三分之一和樹的三分之一被燒掉了，一切的青草也被燒掉了。","notes":[]},{"n":8,"t":"第二位天使吹號，就有像火燒著的大山扔在海中；海的三分之一變成血，","notes":[]},{"n":9,"t":"海中有生命的被造之物死了三分之一，船隻也毀壞了三分之一。","notes":[]},{"n":10,"t":"第三位天使吹號，就有燒著的大星好像火把從天上墜下來，落在江河的三分之一和眾水的泉源上。","notes":[]},{"n":11,"t":"這星名叫「苦艾」；眾水的三分之一變為苦艾，許多人因水變苦而死了。","notes":[]},{"n":12,"t":"第四位天使吹號，太陽的三分之一、月亮的三分之一、星辰的三分之一都被擊打，以致日月星的三分之一變黑了，白晝的三分之一沒有光，黑夜也是這樣。","notes":[]},{"n":13,"t":"我觀看，聽見一隻在空中飛的鷹大聲說：「禍哉！禍哉！禍哉！地上的居民哪，其餘的三位天使快要吹號了！」","notes":[]}]},"9":{"heading":"","verses":[{"n":1,"t":"第五位天使吹號，我就看見一顆星從天上墜落到地上；有無底坑的鑰匙賜給它。","notes":[]},{"n":2,"t":"它開了無底坑，就有煙從坑裏往上冒，好像大火爐的煙；太陽和天空都因這煙昏暗了。","notes":[]},{"n":3,"t":"有蝗蟲從煙中出來，飛到地上，有權柄賜給牠們，好像地上的蠍子有權柄一樣。","notes":[]},{"n":4,"t":"牠們奉命不可傷害地上的草、各樣綠色植物和各種樹木，惟獨可傷害額上沒有神印記的人；","notes":[]},{"n":5,"t":"但是不許蝗蟲害死他們，只可使他們受痛苦五個月；這痛苦就像人被蠍子螫了的痛苦一樣。","notes":[]},{"n":6,"t":"在那些日子，人求死，卻死不了；想死，死卻避開他們。","notes":[]},{"n":7,"t":"蝗蟲的形狀好像預備上陣的戰馬一樣，頭上戴的好像金冠冕，臉面好像男人的臉面，","notes":[]},{"n":8,"t":"頭髮像女人的頭髮，牙齒像獅子的牙齒；","notes":[]},{"n":9,"t":"牠們胸前有甲，好像鐵甲；又有翅膀的響聲，好像許多車馬奔跑上陣的聲音。","notes":[]},{"n":10,"t":"牠們有尾巴像蠍子，長著毒刺，尾巴上的毒刺有能力傷害人五個月。","notes":[]},{"n":11,"t":"牠們有無底坑的使者作牠們的王，按著希伯來話名叫亞巴頓，希臘話名叫亞玻倫。","notes":[]},{"n":12,"t":"第一樣災禍過去了；看哪，還有兩樣災禍要來。","notes":[]},{"n":13,"t":"第六位天使吹號，我聽見有聲音從神面前金壇的四角發出來，","notes":["有古卷沒有「四」。"]},{"n":14,"t":"吩咐那吹號的第六位天使，說：「把那捆綁在幼發拉底大河的四個使者釋放了。」","notes":[]},{"n":15,"t":"那四個使者就被釋放；他們原是預備好，在特定的年、月、日、時，要殺人類的三分之一。","notes":[]},{"n":16,"t":"騎兵有二億；他們的數目我聽見了。","notes":[]},{"n":17,"t":"我在異象中看見那些馬和騎馬的：騎馬的穿著火紅、紫瑪瑙及硫磺色的胸甲；馬的頭好像獅子的頭，有火、有煙、有硫磺從馬的口中噴出來。","notes":[]},{"n":18,"t":"從馬的口中所噴出來的火、煙和硫磺這三樣災害殺了人類的三分之一。","notes":[]},{"n":19,"t":"馬的能力在於牠們的口和尾巴；牠們的尾巴像蛇，有頭，用頭來傷害人。","notes":[]},{"n":20,"t":"其餘未曾被這些災難所殺的人仍舊不為自己手所做的悔改，還是去拜鬼魔和那些不能看、不能聽、不能走，用金、銀、銅、木、石所造的偶像。","notes":[]},{"n":21,"t":"他們也不為自己所犯的那些兇殺、邪術、淫亂、偷竊的事悔改。","notes":[]}]},"10":{"heading":"天使和小書卷","verses":[{"n":1,"t":"我又看見另一位大力的天使從天降下，披著雲彩，頭上有彩虹，臉面像太陽，兩腳像火柱。","notes":[]},{"n":2,"t":"他手裏拿著展開的小書卷。他右腳踏海，左腳踏地，","notes":[]},{"n":3,"t":"大聲呼喊，好像獅子吼叫。呼喊完了，就有七個雷發出聲音。","notes":[]},{"n":4,"t":"七個雷發聲後，我正要寫出來，就聽見從天上有聲音說：「七個雷所說的，你要封上，不可寫出來。」","notes":[]},{"n":5,"t":"我所看見的那踏海踏地的天使向天舉起右手，","notes":[]},{"n":6,"t":"指著創造天和天上之物、地和地上之物、海和海中之物、直活到永永遠遠的那位起誓，說：「不再有時日了。」","notes":["「不再有時日了」或譯「不再耽延了」。"]},{"n":7,"t":"但在第七位天使要吹號的日子，神的奧祕就要成全了，正如神向他僕人眾先知所宣告的。","notes":[]},{"n":8,"t":"我先前從天上所聽見的那聲音又吩咐我說：「你去，把那踏海踏地之天使手中展開的小書卷拿過來。」","notes":[]},{"n":9,"t":"我就走到天使那裏，對他說，請他把小書卷給我。他對我說：「你拿去，把它吃光。它會使你肚子發苦，然而在你口中會甘甜如蜜。」","notes":[]},{"n":10,"t":"於是我從天使手中把小書卷接過來，把它吃光了，在我口中果然甘甜如蜜，吃了以後，我肚子覺得發苦。","notes":[]},{"n":11,"t":"天使們對我說：「你必須指著許多民族、邦國、語言、君王再說預言。」","notes":[]}]},"11":{"heading":"兩個見證人","verses":[{"n":1,"t":"有一根蘆葦，像丈量的杖，賜給我；且有話說：「起來！將神的殿和祭壇，以及在殿中禮拜的人，都量一量。","notes":[]},{"n":2,"t":"只是殿外的院子不用量，因為這是要給外邦人的；他們將踐踏聖城四十二個月。","notes":[]},{"n":3,"t":"「我要賜權柄給我那兩個見證人，穿著粗麻衣說預言一千二百六十天。」","notes":[]},{"n":4,"t":"他們就是那站在世界之主面前的兩棵橄欖樹和兩個燈臺。","notes":[]},{"n":5,"t":"若有人想要害他們，就有火從他們口中噴出來，燒滅仇敵；凡想要害他們的都必須這樣被殺。","notes":[]},{"n":6,"t":"這二人有權柄關閉天空，使他們說預言的日子不下雨；又有權柄使水變為血，並且能隨時隨意用各樣的災害擊打大地。","notes":[]},{"n":7,"t":"他們作完見證的時候，那從無底坑裏上來的獸要跟他們交戰，並且得勝，把他們殺了。","notes":[]},{"n":8,"t":"他們的屍首將倒在大城的街道上；這城按著靈意叫所多瑪，又叫埃及，就是他們的主釘十字架的地方。","notes":[]},{"n":9,"t":"從各民族、支派、語言、邦國中有人觀看他們的屍首三天半，又不許人把屍首安放在墳墓裏。","notes":[]},{"n":10,"t":"住在地上的人會因他們而歡喜快樂，互相饋送禮物，因為這兩位先知曾使住在地上的人受痛苦。","notes":[]},{"n":11,"t":"過了這三天半，有生命的氣息從神那裏進入他們裏面，他們就站起來；看見他們的人都大大懼怕。","notes":[]},{"n":12,"t":"兩位先知聽見有大聲音從天上對他們說：「上這裏來。」他們就駕著雲上了天，他們的仇敵也看見了。","notes":[]},{"n":13,"t":"正在那時候，地大震動，城倒塌了十分之一；因地震而死的有七千人，其餘的都恐懼，歸榮耀給天上的神。","notes":[]},{"n":14,"t":"第二樣災禍過去了；看哪，第三樣災禍快到了。","notes":[]},{"n":15,"t":"第七位天使吹號，天上就有大聲音說：「世上的國已成了我們的主和他所立的基督的國了。他要作王直到永永遠遠！」","notes":[],"heads":["第七枝號筒"]},{"n":16,"t":"在神面前，坐在自己座位上的二十四位長老都俯伏在地上敬拜神，","notes":[]},{"n":17,"t":"說：「今在昔在的主—全能的神啊，我們感謝你！因你執掌大權作王了。","notes":[]},{"n":18,"t":"外邦發怒，你的憤怒臨到了。審判死人的時候也到了；你的僕人眾先知、眾聖徒及敬畏你名的人，連大帶小得賞賜的時候到了；你毀滅那些毀滅大地者的時候也到了。」","notes":[]},{"n":19,"t":"於是，神天上的聖所開了，在他聖所中，他的約櫃出現了；隨後有閃電、響聲、雷轟、地震、大冰雹。","notes":[]}]},"12":{"heading":"婦人和龍","verses":[{"n":1,"t":"天上出現了一個大兆頭：有一個婦人身披太陽，腳踏月亮，頭戴十二顆星的冠冕；","notes":[]},{"n":2,"t":"她懷了孕，在生產的陣痛中疼痛地喊叫。","notes":[]},{"n":3,"t":"天上又出現了另一個兆頭：有一條大紅龍，有七個頭十個角；七個頭上戴著七個冠冕。","notes":["「龍」：原文音譯「杜拉根」，指萬惡之獸。"]},{"n":4,"t":"牠的尾巴拖拉著天上星辰的三分之一，把它們摔在地上。然後龍站在那將要生產的婦人面前，等她生產後要吞吃她的孩子。","notes":[]},{"n":5,"t":"婦人生了一個男孩子，就是將來要用鐵杖管轄萬國的；她的孩子被提到神和他寶座那裏去。","notes":["「管轄」：原文直譯「牧養」。"]},{"n":6,"t":"婦人就逃到曠野，在那裏有神給她預備的地方，使她在那裏被供養一千二百六十天。","notes":[]},{"n":7,"t":"天上發生了爭戰。米迦勒同他的使者與龍作戰，龍同牠的使者也起來應戰，","notes":[]},{"n":8,"t":"牠們都打敗了，天上再也沒有牠們的地方。","notes":[]},{"n":9,"t":"大龍就是那古蛇，名叫魔鬼，又叫撒但，是迷惑普天下的；牠被摔在地上，牠的使者也一同被摔下去。","notes":[]},{"n":10,"t":"我聽見在天上有大聲音說：「我神的救恩、能力、國度，和他所立的基督的權柄現在都來到了。因為那個在我們神面前、晝夜控告我們弟兄的，已經被摔下去了。","notes":[]},{"n":11,"t":"弟兄勝過那條龍是因羔羊的血，和因自己所見證的道。雖然至於死，他們也不惜自己的性命。","notes":[]},{"n":12,"t":"所以，諸天和住在其中的，你們都快樂吧！只是地和海有禍了！因為魔鬼知道自己的時候不多，就氣憤憤地下到你們那裏去了。」","notes":[]},{"n":13,"t":"龍見自己被摔在地上，就迫害那生男孩子的婦人。","notes":[]},{"n":14,"t":"於是有大鷹的兩個翅膀賜給婦人，讓她能飛到曠野，到自己的地方，躲避那蛇。她在那裏受供養一載二載半載。","notes":[]},{"n":15,"t":"蛇在婦人背後，從口中噴出水來，像河一樣，要將婦人沖走。","notes":[]},{"n":16,"t":"地卻幫助了婦人，開口吞了從龍口噴出來的水。","notes":[]},{"n":17,"t":"於是龍向婦人發怒，去與她其餘的兒女作戰，就是與那些遵守神命令、為耶穌作見證的。","notes":["「命令」或譯「誡命」。","「為耶穌作見證的」：原文直譯「有耶穌的見證的」；19．10同。"]},{"n":18,"t":"那時龍站在海邊沙灘上。","notes":[]}]},"13":{"heading":"兩隻獸","verses":[{"n":1,"t":"我又看見一隻獸從海裏上來，有十個角七個頭；在十個角上戴著十個冠冕，七個頭上有褻瀆的名號。","notes":[]},{"n":2,"t":"我所看見的獸，形狀像豹，腳像熊的腳，口像獅子的口。那條龍將自己的能力、座位和大權柄都給了牠。","notes":[]},{"n":3,"t":"我看見獸的七個頭中，有一個似乎受了致命傷，那傷卻醫好了。全地的人都很驚訝，跟從了那隻獸。","notes":[]},{"n":4,"t":"他們都拜那條龍，因為牠把自己的權柄給了獸；又拜那隻獸，說：「誰能比這隻獸，誰能與牠交戰呢？」","notes":[]},{"n":5,"t":"龍又賜給那隻獸說誇大褻瀆話的口，又賜給牠權柄可以任意行事四十二個月。","notes":[]},{"n":6,"t":"那獸就開口向神說褻瀆的話，褻瀆神的名和他的帳幕，就是那些住在天上的。","notes":[]},{"n":7,"t":"牠又被准許與聖徒作戰，並且得勝，也賜給牠權柄，可以制伏各支派、各民族、各語言、各邦國。","notes":[]},{"n":8,"t":"凡住在地上、名字從創世以來沒有記在被殺羔羊的生命冊上的人都要拜牠。","notes":[]},{"n":9,"t":"凡有耳朵的都聽吧！","notes":[]},{"n":10,"t":"該被擄掠的，必被擄掠；該被刀殺的，必被刀殺。在此，聖徒要有耐心和信心。","notes":[]},{"n":11,"t":"我又看見另一隻獸從地裏上來。牠有兩個角如同羔羊，說話好像龍。","notes":[]},{"n":12,"t":"牠在第一隻獸面前施行第一隻獸所有的權柄，並且使地和住在地上的人拜那致命傷被醫好了的第一隻獸。","notes":[]},{"n":13,"t":"這隻獸又行大奇事，甚至在人面前使火從天降在地上。","notes":[]},{"n":14,"t":"牠得了權柄在第一隻獸面前能行奇事，迷惑住在地上的人，告訴他們要為那受過刀傷還活著的獸造個像。","notes":[]},{"n":15,"t":"又有權柄賜給牠，讓那隻獸的像有生氣，並且能說話，又使所有不拜獸像的人都被殺害。","notes":[]},{"n":16,"t":"牠又使眾人，無論大小、貧富，自主的、為奴的，都在右手上，或是在額上，打一個印記；","notes":[]},{"n":17,"t":"這樣，除了那有印記，有獸的名或有獸名數字的，都不得買或賣。","notes":[]},{"n":18,"t":"在此，要有智慧：讓有悟性的人解開獸的數目吧，因為這是一個人的數字，那數字是六百六十六。","notes":[]}]},"14":{"heading":"十四萬四千人的歌","verses":[{"n":1,"t":"我又觀看，看見羔羊站在錫安山，和他在一起的有十四萬四千人，都有他的名和他父親的名寫在額上。","notes":[]},{"n":2,"t":"我聽見從天上有聲音，像眾水的聲音和大雷的聲音，我所聽見的聲音好像琴師所彈的琴聲。","notes":[]},{"n":3,"t":"他們在寶座前，和在四活物及眾長老前唱新歌，除了從地上買來的那十四萬四千人以外，沒有人能學這歌。","notes":[]},{"n":4,"t":"這些人未曾沾染婦女，他們原是童身。羔羊無論往哪裏去，他們都跟隨他。他們是從人間買來的，作為初熟的果子歸給神和羔羊。","notes":[]},{"n":5,"t":"在他們口中找不出謊言，他們是沒有瑕疵的。","notes":[]},{"n":6,"t":"我又看見另一位天使在空中飛翔，有永遠的福音要傳給住在地上的人，就是各邦國、各支派、各語言、各民族。","notes":[],"heads":["三位天使的信息"]},{"n":7,"t":"他大聲說：「要敬畏神，把榮耀歸給他，因為他施行審判的時候已經到了。要敬拜那創造天、地、海和水源的主。」","notes":[]},{"n":8,"t":"另有第二位天使接著說：「傾覆了！那曾叫列國喝淫亂、烈怒之酒的大巴比倫傾覆了！」","notes":[]},{"n":9,"t":"另有第三位天使接著他們，大聲說：「若有人拜那隻獸和獸像，在額上或在手上受了印記，","notes":[]},{"n":10,"t":"他也必喝神烈怒的酒；這酒是斟在神憤怒的杯中的純酒。他要在聖天使和羔羊面前，在火與硫磺之中受痛苦。","notes":[]},{"n":11,"t":"使他們受痛苦的煙往上冒，直到永永遠遠。那些拜獸和獸像，受了牠名字的印記的人，晝夜不得安寧。」","notes":[]},{"n":12,"t":"在此，遵守神命令和堅信耶穌真道的聖徒要有耐心。","notes":["「命令」或譯「誡命」。"]},{"n":13,"t":"我聽見從天上有聲音說：「你要寫下：從今以後，在主裏死去的人有福了。」聖靈說：「是的，他們要從自己的勞苦中得安息，因為工作的成果永隨著他們。」","notes":[]},{"n":14,"t":"我又觀看，看見有一片白雲，雲上坐著一位好像是人子的，頭上戴著金冠冕，手裏拿著鋒利的鐮刀。","notes":[],"heads":["地上的收割"]},{"n":15,"t":"另有一位天使從聖所出來，向那坐在雲上的大聲喊著：「伸出你的鐮刀來收割吧，因為收割的時候已經到了，地上的莊稼已經熟透了。」","notes":[]},{"n":16,"t":"於是那坐在雲上的把鐮刀向地上揮去，地上的莊稼就收割了。","notes":[]},{"n":17,"t":"另有一位天使從天上的聖所出來，他也拿著鋒利的鐮刀。","notes":[]},{"n":18,"t":"另有一位天使從祭壇出來，是有權柄管火的，向那拿著鋒利鐮刀的大聲喊著說：「伸出鋒利的鐮刀來，收取地上葡萄樹的果子，因為葡萄熟透了。」","notes":[]},{"n":19,"t":"那天使就把鐮刀向地上揮去，收取了地上的葡萄，扔進神憤怒的大醡酒池裏。","notes":[]},{"n":20,"t":"那醡酒池在城外被踹踏，有血從醡酒池裏流出來，漲到馬的嚼環那麼高，約有一千六百斯他迪那麼遠。","notes":["「斯他迪」：古希臘長度單位；21．16同；參「度量衡表」。"]}]},"15":{"heading":"七位天使掌管最後的災難","verses":[{"n":1,"t":"我看見在天上有另一兆頭，大而且奇，就是七位天使掌管末了的七種災難，因為神的烈怒在這七種災難中發盡了。","notes":[]},{"n":2,"t":"我看見彷彿有攙雜火的玻璃海；又看見那些勝了那獸和獸像，以及牠名字的數字的人，都站在玻璃海上，拿著神的豎琴。","notes":[]},{"n":3,"t":"他們唱神僕人摩西的歌和羔羊的歌，說：「主—全能的神啊，你的作為又偉大又奇妙！萬國之王啊，你的道路又公義又真實！","notes":[]},{"n":4,"t":"主啊，誰敢不敬畏你，不把榮耀歸於你的名？因為只有你是神聖的。萬民都要來，在你面前敬拜，因你公義的作為已經彰顯了。」","notes":[]},{"n":5,"t":"此後，我看見在天上那存放法櫃的聖所開了。","notes":[]},{"n":6,"t":"那掌管七種災難的七位天使從聖所出來，穿著潔白明亮的細麻衣，胸間束著金帶。","notes":["「細麻衣」：有古卷是「寶石」。"]},{"n":7,"t":"四個活物中，有一個把盛滿了活到永永遠遠之神烈怒的七個金碗給了那七位天使。","notes":[]},{"n":8,"t":"聖所中充滿了神的榮耀和權能而來的煙。沒有人能進入聖所，直等到那七位天使降完了七種災難。","notes":[]}]},"16":{"heading":"神烈怒的碗","verses":[{"n":1,"t":"我聽見有大聲音從聖所裏出來，向那七位天使說：「你們去，把盛著神烈怒的七碗傾倒在地上。」","notes":[]},{"n":2,"t":"第一位天使去，把碗傾倒在地上，就有又臭又毒的瘡生在那些有獸的印記和拜獸像的人身上。","notes":[]},{"n":3,"t":"第二位天使把碗傾倒在海裏，海就變成像死人的血一樣，海裏所有的活物都死了。","notes":[]},{"n":4,"t":"第三位天使把碗傾倒在河流和水源裏，水就變成血了。","notes":[]},{"n":5,"t":"我聽見掌管眾水的天使說：「昔在、今在的聖者啊，你做的判斷公義；","notes":[]},{"n":6,"t":"因他們曾流過聖徒與先知的血，現在你給他們血喝，這是他們該受的。」","notes":[]},{"n":7,"t":"我又聽見祭壇中有聲音說：「是的，主—全能的神啊，你的判斷又真實又公義！」","notes":[]},{"n":8,"t":"第四位天使把碗傾倒在太陽上，使太陽可用火烤人。","notes":[]},{"n":9,"t":"人被炎熱所烤，就褻瀆那有權掌管這些災難的神的名，他們沒有悔改，也沒有把榮耀歸給神。","notes":[]},{"n":10,"t":"第五位天使把碗傾倒在獸的座位上，獸的國就變成黑暗。人因疼痛而咬自己的舌頭；","notes":[]},{"n":11,"t":"又因所受的疼痛和生的瘡，就褻瀆天上的神，也沒有為他們的行為悔改。","notes":[]},{"n":12,"t":"第六位天使把碗傾倒在大幼發拉底河上，河水就乾了，為要給從日出之地所來的眾王預備道路。","notes":[]},{"n":13,"t":"我又看見三個污穢的靈，好像青蛙，從龍的口、獸的口和假先知的口中出來。","notes":[]},{"n":14,"t":"他們本是鬼魔的靈，施行奇事，到普天下眾王那裏去，召集他們在全能者神的大日子作戰。","notes":[]},{"n":15,"t":"看哪，我來像賊一樣。那警醒、穿著衣服的人有福了；他不至於赤身而行，給人看見他的羞恥。","notes":[]},{"n":16,"t":"於是，那三個鬼魔把眾王聚集在希伯來話叫作哈米吉多頓的地方。","notes":[]},{"n":17,"t":"第七位天使把碗傾倒在空中，就有大聲音從聖所的寶座上出來，說：「成了！」","notes":[]},{"n":18,"t":"又有閃電、響聲、雷轟、大地震，自從地上有人以來沒有這樣大、這樣厲害的地震。","notes":[]},{"n":19,"t":"那大城裂為三段，列國的城也都倒塌了。神記起了大巴比倫城，把那盛自己烈怒的酒杯遞給她。","notes":[]},{"n":20,"t":"各海島都逃避了，眾山也不見了。","notes":[]},{"n":21,"t":"又有大冰雹從天掉落在人身上，每一個約重一他連得，以致人因冰雹的災難而褻瀆神，因為那災難太大了。","notes":[]}]},"17":{"heading":"大淫婦和獸","verses":[{"n":1,"t":"拿著七個碗的七位天使中，有一位前來對我說：「來，我要讓你看那坐在眾水之上的大淫婦所要受的懲罰；","notes":[]},{"n":2,"t":"地上的君王都曾與她行淫，住在地上的人也喝醉了她淫亂的酒。」","notes":[]},{"n":3,"t":"我在聖靈感動下，被天使帶到曠野去，我看見一個女人騎在朱紅色的獸上；那隻獸有七個頭十個角，遍體有褻瀆的名號。","notes":[]},{"n":4,"t":"那女人穿著紫色和朱紅色的衣服，用金子、寶石、珍珠作妝飾，手拿著金杯，杯中盛滿了可憎之物和她淫亂的污穢。","notes":[]},{"n":5,"t":"在她額上寫著奧祕的名字，說：「大巴比倫，世上的淫婦和一切可憎之物的母。」","notes":[]},{"n":6,"t":"我又看見那女人喝醉了聖徒的血和為耶穌作見證的人的血。我看見她，非常詫異。","notes":[]},{"n":7,"t":"天使對我說：「你為甚麼詫異呢？我要把這女人和馱著她那七頭十角的獸的奧祕告訴你。","notes":[]},{"n":8,"t":"你曾看見的獸，以前有，現在沒有，將來要從無底坑裏上來，又歸於沉淪。凡住在地上、名字從創世以來沒有記在生命冊上的人看見那隻獸都要詫異，因為牠以前有，現在沒有，以後再有。","notes":[]},{"n":9,"t":"在此要有智慧的心思：那七個頭就是女人所坐的七座山；他們又是七個王，","notes":[]},{"n":10,"t":"五個已經倒了，一個還在，一個還沒有來到；他來的時候必須只暫時停留。","notes":[]},{"n":11,"t":"那以前有、現在沒有的獸就是第八個，他也和那七個同列，正歸於沉淪。","notes":[]},{"n":12,"t":"你曾看見的那十個角就是十個王；他們還沒有得到國度，但他們要和那隻獸同得權柄作王一個時辰。","notes":[]},{"n":13,"t":"他們同心把自己的能力權柄交給那隻獸。","notes":[]},{"n":14,"t":"他們將與羔羊作戰，羔羊必勝過他們，因為羔羊是萬主之主、萬王之王，而同羔羊在一起的是蒙召、被選、忠心的人。」","notes":[]},{"n":15,"t":"天使又對我說：「你所看見那淫婦坐的眾水，就是許多民族、人民、邦國、語言。","notes":[]},{"n":16,"t":"你所看見的那十個角與獸必恨這淫婦，他們要使她孤獨赤身，又要吃她的肉，用火將她燒盡。","notes":[]},{"n":17,"t":"因為神使諸王同心執行他的旨意，把他們自己的國交給那隻獸，直等到神的話都應驗了。","notes":[]},{"n":18,"t":"你所看見的那女人就是管轄地上眾王的大城。」","notes":[]}]},"18":{"heading":"巴比倫傾覆","verses":[{"n":1,"t":"此後，我看見另一位有大權柄的天使從天降下，地由於他的榮耀而發光。","notes":[]},{"n":2,"t":"他以強而有力的聲音喊著說：「傾覆了！大巴比倫傾覆了！她成了鬼魔的住處，各樣污穢之靈的巢穴，各樣污穢之鳥的窩，各樣污穢可憎之獸的出沒處。","notes":["「各樣污穢之鳥…出沒處」：有古卷是「各樣污穢可憎之鳥的窩」。"]},{"n":3,"t":"因為列國都喝了她淫亂大怒的酒；地上的君王和她行淫；地上的商人因她極度奢華而發了財。」","notes":["「喝了…酒」：有古卷是「因她淫亂大怒的酒而傾倒了」。"]},{"n":4,"t":"我又聽見另一個聲音從天上說：「我的民哪，從那城出來吧！免得和她在罪上有份，受她所受的災殃；","notes":[]},{"n":5,"t":"因她的罪惡滔天，神已經記得她的不義。","notes":[]},{"n":6,"t":"她怎樣待人，也要怎樣待她，按她所行的加倍地報應她；用她調酒的杯加倍調給她喝。","notes":[]},{"n":7,"t":"她怎樣榮耀自己，怎樣奢華，也要使她照樣痛苦悲哀。因她心裏說：『我坐了皇后的位，並不是寡婦，絕不至於悲哀。』","notes":[]},{"n":8,"t":"所以在一天之內，她的災殃要一齊來到，就是死亡、悲哀、饑荒。她將被火燒盡，因為審判她的主神大有能力。」","notes":[]},{"n":9,"t":"地上的君王，與她行淫、一同奢華的，看見燒她的煙，就必為她哭泣哀號；","notes":[]},{"n":10,"t":"因怕她的痛苦，就遠遠地站著，說：「禍哉，禍哉，這大城！堅固的巴比倫城啊！一時之間，你的審判要來到了。」","notes":[]},{"n":11,"t":"地上的商人也都為她哭泣悲哀，因為沒有人再買他們的貨物了；","notes":[]},{"n":12,"t":"這貨物就是金、銀、寶石、珍珠、細麻布、絲綢、紫色和朱紅色衣料、各樣香木、各樣象牙的器皿、各樣極寶貴的木頭和銅、鐵、大理石的器皿，","notes":[]},{"n":13,"t":"和肉桂、豆蔻、香料、香膏、乳香、酒、油、細麵、麥子、牛、羊、馬、馬車，以及奴隸、人口。","notes":[]},{"n":14,"t":"「你所貪愛的果子離開了你；你一切的珍饈美味和華美的物件都從你那裏毀滅，絕對見不到了。」","notes":[]},{"n":15,"t":"販賣這些貨物、藉著她發財的商人，因怕她的痛苦，就遠遠地站著哭泣悲哀，","notes":[]},{"n":16,"t":"說：「禍哉，禍哉，這大城！她穿著細麻、紫色、朱紅色的衣服，用金子、寶石、珍珠為妝飾。","notes":[]},{"n":17,"t":"一時之間，這麼多的財富就歸於無有了。」所有的船長和到處航海的，水手以及所有靠海為業的，都遠遠地站著，","notes":[]},{"n":18,"t":"看見燒她的煙，就喊著說：「有哪一個城能跟這大城比呢？」","notes":[]},{"n":19,"t":"於是他們把灰塵撒在頭上，哭泣悲哀地喊著說：「禍哉，禍哉，這大城！凡有船在海中的，都因她的珍寶成了富足。她在一時之間就成為荒蕪。","notes":[]},{"n":20,"t":"天哪，眾聖徒、眾使徒、眾先知啊！你們都要因她歡喜，因為神已經在她身上為你們伸了冤。」","notes":[]},{"n":21,"t":"有一位大力的天使舉起一塊石頭，好像大磨石，扔在海裏，說：「巴比倫大城也必這樣猛力地被扔下去，絕對見不到了。","notes":[]},{"n":22,"t":"彈琴、歌唱、吹笛、吹號的聲音，在你中間絕對聽不見了；各行手藝的技工在你中間絕對見不到了；推磨的聲音在你中間絕對聽不見了；","notes":[]},{"n":23,"t":"燈臺的光在你中間絕對不再照耀了；新郎和新娘的聲音在你中間絕對聽不見了。你的商人原來是地上的顯要；萬國也被你的邪術迷惑了。","notes":[]},{"n":24,"t":"先知、聖徒和地上一切被殺的人的血都在這城裏找到了。」","notes":[]}]},"19":{"heading":"羔羊的婚宴","verses":[{"n":1,"t":"此後，我聽見好像有一大群人在天上大聲說：「哈利路亞！救恩、榮耀、權能都屬於我們的神。","notes":["「哈利路亞」就是「要讚美耶和華」的意思。"]},{"n":2,"t":"他的判斷又真實又公義；因他判斷了那大淫婦，她用淫行敗壞了世界。神為他的僕人伸冤，向淫婦討流僕人血的罪。」","notes":[]},{"n":3,"t":"他們又一次說：「哈利路亞！燒淫婦的煙往上冒，直到永永遠遠。」","notes":[]},{"n":4,"t":"那二十四位長老和四活物就俯伏敬拜坐在寶座上的神，說：「阿們。哈利路亞！」","notes":[]},{"n":5,"t":"接著，有聲音從寶座出來說：「神的眾僕人哪，凡敬畏他的，無論大小，都要讚美我們的神！」","notes":[]},{"n":6,"t":"我聽見好像一大群人的聲音，像眾水的聲音，像大雷的聲音，說：「哈利路亞！因為主─我們的神、全能者，作王了。","notes":["「主─我們的神」：有古卷是「神我們的主」；另有古卷是「我們的神」，或「主神」，或「主」。"]},{"n":7,"t":"我們要歡喜快樂，將榮耀歸給他；因為羔羊的婚期到了，他的新娘也自己預備好了，","notes":[]},{"n":8,"t":"她蒙恩得穿明亮潔白的細麻衣：這細麻衣就是聖徒們的義行。」","notes":[]},{"n":9,"t":"天使對我說：「你要寫下來：凡被請赴羔羊婚宴的人有福了！」他又對我說：「這些都是神真實的話。」","notes":[]},{"n":10,"t":"我就俯伏在他腳前要拜他。他對我說：「千萬不可！我和你，以及那些為耶穌作見證的弟兄同是僕人。你要敬拜神。」因為那些為耶穌作見證的人有預言的靈。","notes":[]},{"n":11,"t":"後來我看見天開了。有一匹白馬，騎在馬上的稱為「誠信」、「真實」，他審判和爭戰都憑著公義。","notes":["有古卷沒有「稱為」。"],"heads":["白馬騎士"]},{"n":12,"t":"他的眼睛如火焰，頭上戴著許多冠冕；他身上寫著一個名字，除了他自己沒有人知道。","notes":["有古卷沒有「如」。"]},{"n":13,"t":"他穿著浸過血的衣服；他的名稱為「神之道」。","notes":[]},{"n":14,"t":"眾天軍都騎著白馬，穿著又白又潔淨的細麻衣跟隨他。","notes":[]},{"n":15,"t":"有利劍從他口中出來，用來擊打列國。他要用鐵杖管轄他們，並且要踹全能神烈怒的醡酒池。","notes":["「管轄」：原文直譯「牧養」。"]},{"n":16,"t":"在他衣服和大腿上寫著「萬王之王，萬主之主」的名號。","notes":[]},{"n":17,"t":"我又看見一位天使站在太陽中，向天空一切的飛鳥大聲喊著說：「你們聚集來赴神的大宴席，","notes":[]},{"n":18,"t":"為要吃君王的肉、將軍的肉、壯士的肉、馬和騎士的肉、一切自主的和為奴的，以及尊貴的和卑賤的肉。」","notes":[]},{"n":19,"t":"我又看見那獸和地上的君王，和他們的軍隊都聚集，要與白馬騎士和他的軍隊作戰。","notes":[]},{"n":20,"t":"那獸被擒拿了；那在獸面前曾行奇事、迷惑了接受獸的印記和拜獸像的人的假先知，也與獸同被擒拿。他們兩個就活生生地被扔進燒著硫磺的火湖裏，","notes":[]},{"n":21,"t":"其餘的人被白馬騎士口中吐出來的劍殺了；所有的飛鳥都吃飽了他們的肉。","notes":[]}]},"20":{"heading":"一千年","verses":[{"n":1,"t":"我又看見一位天使從天降下，手裏拿著無底坑的鑰匙和一條大鐵鏈。","notes":[]},{"n":2,"t":"他抓住那龍，那古蛇，就是魔鬼、撒但，把牠捆綁了一千年，","notes":[]},{"n":3,"t":"扔在無底坑裏，把無底坑關閉，用印封上，使牠不再迷惑列國，等到那一千年滿了。這些事以後，牠必須暫時被釋放。","notes":[]},{"n":4,"t":"我又看見一些寶座，坐在上面的有審判的權柄賜給他們。我又看見那些因為給耶穌作見證，並為神之道被斬首的人的靈魂，和沒有拜過那獸與獸像、也沒有在額上和手上打過牠印記的人的靈魂。他們都復活了，與基督一同作王一千年。","notes":[]},{"n":5,"t":"這是頭一次的復活。其餘的死人還沒有復活，直等那一千年滿了。","notes":[]},{"n":6,"t":"在頭一次復活有份的有福了，聖潔了！第二次的死在他們身上沒有權柄，但他們要作神和基督的祭司，也要與基督一同作王一千年。","notes":[]},{"n":7,"t":"那一千年滿了，撒但會從監牢裏被釋放，","notes":[],"heads":["擊敗撒但"]},{"n":8,"t":"出來要迷惑地上四方的列國，就是歌革和瑪各，使他們聚集爭戰。他們的人數多如海沙。","notes":[]},{"n":9,"t":"他們上來佈滿了全地，圍住聖徒的營與蒙愛的城，就有火從天降下，燒滅了他們。","notes":[]},{"n":10,"t":"那迷惑他們的魔鬼被扔進硫磺的火湖裏，就是那獸和假先知所在的地方，他們會晝夜受折磨，直到永永遠遠。","notes":[]},{"n":11,"t":"我又看見一個白色的大寶座和那坐在上面的；天和地都從他面前逃避，再也找不到它們的位置了。","notes":[],"heads":["末日的審判"]},{"n":12,"t":"我又看見死了的人，無論大小，都站在寶座前。案卷都展開了，並另有一卷展開，就是生命冊。死了的人都憑著這些案卷所記載的，照他們所行的受審判。","notes":[]},{"n":13,"t":"於是海交出其中的死人，死亡和陰間也交出其中的死人；他們都照各人所行的受審判。","notes":[]},{"n":14,"t":"死亡和陰間也被扔進火湖裏，這火湖就是第二次的死。","notes":[]},{"n":15,"t":"凡名字沒有記在生命冊上的人，就被扔進火湖裏。","notes":[]}]},"21":{"heading":"新天新地","verses":[{"n":1,"t":"我又看見一個新天新地，因為先前的天和先前的地已經過去了，海也不再有了。","notes":[]},{"n":2,"t":"我又看見聖城，新耶路撒冷由神那裏，從天而降，預備好了，就如新娘打扮整齊，等候丈夫。","notes":[]},{"n":3,"t":"我聽見有大聲音從寶座出來，說：「看哪，神的帳幕在人間！他要和他們同住，他們要作他的子民。神要親自與他們同在。","notes":["有古卷加「作他們的神。」"]},{"n":4,"t":"神要擦去他們一切的眼淚；不再有死亡，也不再有悲哀、哭號、痛苦，因為先前的事都過去了。」","notes":[]},{"n":5,"t":"那位坐在寶座上的說：「看哪，我把一切都更新了！」他又說：「你要寫下來，因為這些話是可信靠的，是真實的。」","notes":[]},{"n":6,"t":"他又對我說：「成了！我是阿拉法，我是俄梅戛；我是開始，我是終結。我要把生命的泉水白白賜給那口渴的人喝。","notes":[]},{"n":7,"t":"得勝的要承受這些為業；我要作他的神，他要作我的兒子。","notes":[]},{"n":8,"t":"至於膽怯的、不信的、可憎的、殺人的、淫亂的、行邪術的、拜偶像的和一切說謊話的人，他們將在燒著硫磺的火湖裏有份；這是第二次的死。」","notes":[]},{"n":9,"t":"拿著七個金碗、盛滿末後七種災禍的七位天使中，有一位來對我說：「你來，我要給你看新娘，就是羔羊的妻子。」","notes":[],"heads":["新耶路撒冷"]},{"n":10,"t":"我在聖靈感動下，天使帶我到一座高大的山，給我看由神那裏、從天而降的聖城耶路撒冷，","notes":[]},{"n":11,"t":"這城有神的榮耀，它光輝如同極貴的寶石，好像碧玉，明如水晶。","notes":[]},{"n":12,"t":"它有高大的牆，有十二個門，門上有十二位天使，門上又寫著以色列人十二個支派的名字。","notes":["有古卷沒有「的名字」。"]},{"n":13,"t":"東邊有三個門，北邊有三個門，南邊有三個門，西邊有三個門。","notes":[]},{"n":14,"t":"城牆有十二個根基，根基上有羔羊十二使徒的名字。","notes":[]},{"n":15,"t":"那對我說話的天使拿著金的蘆葦當尺，要量那城、城門和城牆。","notes":[]},{"n":16,"t":"城是四方的，長寬一樣。天使用蘆葦量那城，共有一萬二千斯他迪，長、寬、高都是一樣。","notes":[]},{"n":17,"t":"他又量了城牆，按著人的尺寸，就是天使的尺寸，共有一百四十四肘。","notes":[]},{"n":18,"t":"牆是碧玉造的；城是純金的，如同明淨的玻璃。","notes":[]},{"n":19,"t":"城牆的根基是用各樣寶石修飾的：第一個根基是碧玉，第二是藍寶石，第三是綠瑪瑙，第四是綠寶石，","notes":[]},{"n":20,"t":"第五是紅瑪瑙，第六是紅寶石，第七是黃璧璽，第八是水蒼玉，第九是紅璧璽，第十是翡翠，第十一是紫瑪瑙，第十二是紫晶。","notes":[]},{"n":21,"t":"十二個門是十二顆珍珠；每一個門是一顆珍珠造的。城內的街道是純金的，好像透明的玻璃。","notes":[]},{"n":22,"t":"我沒有看見城內有殿，因主—全能者神和羔羊就是城的殿。","notes":[]},{"n":23,"t":"那城內不用日月光照，因為有神的榮耀光照，又有羔羊為城的燈。","notes":[]},{"n":24,"t":"列國要藉著城的光行走；地上的君王要把自己的榮耀帶給那城。","notes":[]},{"n":25,"t":"城門白晝總不關閉，在那裏沒有黑夜。","notes":[]},{"n":26,"t":"人要將列國的榮耀尊貴帶給那城。","notes":[]},{"n":27,"t":"凡不潔淨的，和那行可憎與虛謊之事的人，都不得進那城，只有名字寫在羔羊生命冊上的才得進去。","notes":[]}]},"22":{"heading":"基督來臨","verses":[{"n":1,"t":"天使又讓我看一道生命水的河，明亮如水晶，從神和羔羊的寶座流出來，","notes":[]},{"n":2,"t":"經過城內街道的中央；在河的兩邊有生命樹，結十二樣 的果子，每月都結果子；樹上的葉子可作醫治萬民之用。","notes":["「樣」或譯「回」。"]},{"n":3,"t":"以後不再有任何詛咒。在城裏將有神和羔羊的寶座。他的僕人都要事奉他，","notes":[]},{"n":4,"t":"也要見他的面。他的名字將寫在他們的額上。","notes":[]},{"n":5,"t":"不再有黑夜；他們也不需要燈光或日光，因為主神要光照他們。他們要作王，直到永永遠遠。","notes":[]},{"n":6,"t":"天使又對我說：「這些話是可信靠的，是真實的。主，就是賜靈感給眾先知的神，差遣他的使者，要將必須快要發生的事指示他的眾僕人。」","notes":[]},{"n":7,"t":"「看哪，我必快來！凡遵守這書上預言的有福了。」","notes":[]},{"n":8,"t":"這些事是我－約翰所聽見所看見的。當我聽見看見時，就俯伏在指示我的天使腳前要拜他。","notes":[]},{"n":9,"t":"他對我說：「千萬不可！我與你和你的弟兄眾先知，以及那些守這書上的話的人，同是作僕人。你要敬拜神。」","notes":[]},{"n":10,"t":"他又對我說：「不可封了這書上的預言，因為時候近了。","notes":[]},{"n":11,"t":"不義的，讓他仍舊不義；污穢的，讓他仍舊污穢；為義的，讓他仍舊為義；聖潔的，讓他仍舊聖潔。」","notes":[]},{"n":12,"t":"「看哪，我必快來！賞罰在我，要照每個人所行的報應他。","notes":[]},{"n":13,"t":"我是阿拉法，我是俄梅戛；我是首先的，我是末後的；我是開始，我是終結。」","notes":[]},{"n":14,"t":"那些洗淨自己衣服的有福了！他們可得權柄到生命樹那裏，也能從門進城。","notes":[]},{"n":15,"t":"城外有犬類、行邪術的、淫亂的、殺人的、拜偶像的，以及所有喜愛和行虛謊的人。","notes":[]},{"n":16,"t":"「我－耶穌差遣我的使者，為了眾教會向你們證明這些事。我是大衛的根，是他的後裔；我是明亮的晨星。」","notes":[]},{"n":17,"t":"聖靈和新娘都說：「來！」聽見的人也要說：「來！」口渴的人也要來，願意的人都可以白白取生命的水喝。","notes":[]},{"n":18,"t":"我警告一切聽見這書上預言的人：若有人在這預言上加添甚麼，神必將記在這書上的災禍加在他身上。","notes":[]},{"n":19,"t":"這書上的預言，若有人刪去甚麼，神必從這書上所記的生命樹和聖城刪去他的份。","notes":[]},{"n":20,"t":"證明這些事的說：「是的，我必快來！」阿們！主耶穌啊，我願你來！","notes":[]},{"n":21,"t":"願主耶穌的恩惠與眾聖徒同在。阿們！","notes":["有古卷沒有「阿們！」"]}]}}}}}};
